create table movie
(
    mid        varchar(10)   not null
        primary key,
    mname      varchar(50)   null,
    type       varchar(10)   null,
    content    varchar(700)  null,
    actors     varchar(30)   null,
    director   varchar(20)   null,
    rate       float         null,
    rate_num   int           null,
    imdb       varchar(15)   null,
    pic        varchar(85)   null,
    one_star   float         null,
    two_star   float         null,
    three_star float         null,
    four_star  float         null,
    five_star  float         null,
    feature    varchar(1500) null,
    s1_mid     varchar(10)   null,
    s2_mid     varchar(10)   null,
    s3_mid     varchar(10)   null,
    s4_mid     varchar(10)   null
);

create fulltext index director_fulltext
    on movie (director);

create fulltext index title_fulltext
    on movie (mname);

