INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10001432', '颠倒的帕特玛', '动画', '在秩序井然的艾嘉王国，人类谨遵祖先的教训，绝不抬头仰望苍穹，放纵思绪流淌狂奔。传说在很久以前，地上的人们挑战造物，结果致令重力反转，难以数计的人类和建筑“坠入”蓝天，销声匿迹。但森严的秩序和自由思想势必发生冲突，少年艾吉（冈本信彦 配音）夜晚偷偷溜到野外，躺在草地上仰望繁星点点的夜空，而就在此时，身后的洞口出现了一个神色慌张的女孩。她叫帕特玛（藤井雪代 配音），拥有和艾吉全然相反的重力场。为了防止帕特玛跌落到空中，艾吉小心翼翼将其带到小屋保护起来。可是政府很快发现了帕特玛的踪迹，最高领导人动员全部力量展开围捕。在你来我往的追逐过程中，艾嘉王国和反转人的秘密也悄然揭开……©豆瓣', '藤井雪代', '吉浦康裕', 8, 14034, 'tt2981768', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2043944718.jpg', 0.2, 2.1, 22.8, 46.7, 28.3, '0.233141,0.205014,-0.949691,0.643346,-0.030996,0.083161,0.704598,0.385662,-0.251158,-0.073713,0.440005,0.553061,-0.051772,-0.064655,0.357117,-0.132564,-0.455599,-0.715391,-0.313448,-0.043999,-0.402435,-0.253240,-0.186060,-0.367905,-0.138556,-0.485056,0.776001,0.115153,-0.480759,0.340489,-0.099521,0.051878,-0.447975,0.427530,-0.355666,-0.131093,0.046744,0.061098,-0.057404,0.313813,-0.475990,-0.567463,-0.208594,0.146027,-0.125724,0.119126,0.710096,-0.460506,-0.048388,0.127736,0.187125,-0.516766,0.072049,0.075455,0.408018,-0.125478,-0.171905,-0.061820,0.043533,-0.071763,0.056412,-0.124617,-0.563005,0.052086,0.087983,0.245620,-0.541624,0.504369,0.264568,-0.104535,0.023360,-0.309837,0.180285,0.084632,-0.035469,0.408995,-0.292983,0.043251,-0.545484,-0.144632,0.319733,-0.048109,-0.276904,0.172270,-0.091843,-0.428986,-0.227239,-0.012836,-0.246097,-0.604546,0.357217,0.215062,-0.112609,0.320243,-0.687703,0.157853,-0.142729,-0.483772,-0.253767,-0.452417,-0.358627,-0.370388,-0.198323,-0.222645,-0.209125,0.351514,-0.124548,-0.165326,0.429453,-0.662807,0.366250,0.474644,0.247374,0.042776,0.630566,-0.232028,-0.009341,0.017111,-0.053308,0.213795,0.364905,0.506180,-0.033300,0.154677,-0.290387,0.364182,-0.516292,0.340440', '21619567', '26342391', '1298405', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10047547', '饥饿游戏3：嘲笑鸟(下)', '动作', '施惠国爆发了全面战争，凯特尼斯（詹妮弗·劳伦斯 Jennifer Lawrence 饰）将在最后关头对峙斯诺总统（唐纳德·萨瑟兰 Donald Sutherland 饰）。在盖尔（利亚姆·海姆斯沃斯 Liam Hemsworth 饰）、芬尼克（山姆·克拉弗林 Sam Claflin 饰）和皮塔（乔什·哈切森 Josh Hutcherson 饰）等好友的陪伴下，凯特尼斯和十三区的小队一起为了解放施惠国的人民而冒险抗争，并且策划暗杀越来越执迷于杀死她的斯诺总统。凯特尼斯将面对致命陷阱、劲敌和道义上的选择，而这些挑战都不曾出现在饥饿游戏的竞技场中。', '詹妮弗·劳伦斯', '弗朗西斯·劳伦斯', 6.5, 134212, 'tt1951266', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2282434035.jpg', 3, 13.1, 50.2, 24, 9.7, '0.250871,-0.296346,-0.743042,0.338809,0.048418,-0.333678,0.847821,0.199658,-0.246702,0.048234,0.634510,1.002094,-0.126270,-0.259736,0.614120,-0.053876,-0.628465,-0.833385,0.015955,-0.178695,-0.074708,-0.774035,-0.501183,-0.128490,-0.181794,-0.457830,0.598698,-0.051732,0.074654,0.398745,0.550211,0.591310,0.106847,0.319283,0.273872,-0.130464,0.551212,-0.358563,-0.382072,0.327044,-0.061442,0.111512,-0.328442,0.513450,0.418453,0.275966,0.444987,-0.654950,0.588974,-0.226130,-0.065338,-0.422823,0.154109,0.183111,0.044294,-0.195035,0.162658,0.449683,-0.101884,-0.127046,0.372227,0.085242,-0.845248,0.392551,-0.016271,0.303897,-0.589129,0.157747,-0.489313,-0.028188,0.267239,-0.125679,-0.082501,0.637457,0.379839,-0.114208,-0.273556,-0.295287,-0.316358,-0.134723,0.272414,-0.326927,-0.347896,-0.244306,-0.047946,-0.271371,-0.043011,-0.245022,-0.554417,-0.454245,0.210827,-0.008426,-0.003788,0.552204,-0.819861,-0.200383,-0.553049,-0.481592,0.029137,-0.363286,-0.169685,-0.925823,-0.063964,-0.314652,-0.312447,0.035306,0.229341,-0.073410,0.470250,-0.831934,0.366137,0.488766,0.502813,-0.063512,0.513779,0.182932,0.296196,0.019514,0.025719,0.448358,0.195934,0.109483,0.117645,0.426725,0.278504,0.042455,-0.430882,0.573526', '6517421', '11541282', '35161768', '30143331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10174444', '剧场版魔法少女小圆 前篇 起始的故事', '动画', '市立见泷原中学，又迎来平静祥和的一天。就读于二年级的女孩鹿目圆（悠木碧 配音）和朋友美树沙耶加（喜多村英梨 配音）、志筑仁美（新谷良子 配音）尽情讨论恋爱的话题，享受少女的快乐青春。这时班上转来了名叫晓美焰（斋藤千和 配音）的新生，这个带着些许神秘气质的女孩让小圆颇感疑惑。与沙耶加下学回家路上，小圆听到呼救声，声音来自一只浑身伤痕累累的未知生物，而追杀它的正是晓美焰。危急时刻，她们得到同为见泷原中学学生的魔法少女巴麻美（水桥香织 配音）的帮助，进而得知那只名叫丘比的生物有能够帮助人变成魔法少女的能力。少女们无意间开启了通往另一个世界的大门……本片为魔法少女的剧场版，分三部上映，由TV版12话重新编集而成。©豆瓣', '悠木碧', '新房昭之', 9, 6211, 'tt2205948', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1634119717.jpg', 0.5, 0.9, 8.3, 30.7, 59.8, '0.048422,0.054916,-0.202453,0.511640,0.001802,0.028968,0.565462,0.184134,-0.334814,-0.420946,-0.017467,0.555654,-0.326355,0.523699,0.520285,0.028199,-0.114279,-0.375503,-0.089929,-0.240607,-0.129003,-0.220114,-0.009980,0.048073,-0.100954,-0.566618,0.881415,0.053064,-0.119757,0.570824,0.227576,0.316914,-0.361194,0.242063,0.001544,-0.186811,0.131494,-0.003902,0.026282,0.232334,-0.227673,-0.139677,-0.261279,-0.106190,-0.160814,0.097164,0.909866,-0.183152,0.006827,-0.143218,0.467086,-0.041883,-0.154681,-0.022044,0.424897,0.106140,0.338352,-0.160663,-0.041094,-0.165629,-0.024203,-0.346164,-0.452281,0.186553,0.148012,0.388312,-0.079567,0.234662,0.155324,-0.061102,0.527997,-0.090922,-0.007603,-0.027300,0.414448,0.526605,-0.230679,0.299562,0.003295,-0.059101,0.361815,-0.054656,-0.189056,0.398197,-0.083466,-0.540419,-0.139459,-0.035058,-0.366179,0.217496,-0.029372,0.377443,-0.100019,0.036566,-0.734653,0.018020,-0.096654,-0.016207,0.199294,-0.408429,-0.306071,-0.783471,0.076981,-0.204494,-0.141679,0.200927,0.295563,-0.201317,1.090011,-0.973286,0.021835,0.303429,0.237126,-0.005531,0.483567,-0.046593,0.134748,-0.571476,-0.156457,0.199787,-0.094537,0.334282,0.015215,0.468379,-0.279706,-0.019705,-0.446833,0.218919', '5403927', '25922902', '3811356', '26999591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10342838', '弯刀杀戮', '动作', '身怀绝技的弯刀（丹尼·特乔 Danny Trejo 饰）在追查犯罪组织卡特尔的行动中，其女友兼搭档ICE特工莎塔娜（杰西卡·阿尔芭 Jessica Alba 饰）不慎遇害，弯刀也被作为杀人凶手判处绞刑。关键时刻，美国总统秘密将其招至华府，命弯刀前往美国和墨西哥的边界，调查革命武装组织头目马科斯·门德斯革命者（德米安·比齐尔 Demián Bichir 饰）是否有袭击美国的打算，一旦证据确凿即可将其抹杀。弯刀率先与圣·安东尼奥小姐（艾梅柏·希尔德 Amber Heard 饰）接洽，随后潜入墨西哥见到门德斯。此时的门德斯仿佛已经人格分裂，他将导弹的控制系统与自己的心脏相连，一旦遇害导弹便自动飞向美国华府，而他的人头又高达千万美金，以至于弯刀被迫担负起保护门德斯性命的任务。返回美国的道路杀机四伏，凶险非常，更有意想不到的阴谋等待着他……©豆瓣', '丹尼·特雷霍', '罗伯特·罗德里格兹', 5.9, 15281, 'tt2002718', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2156580336.jpg', 7.1, 23.7, 45.9, 15.6, 7.7, '-0.062842,-0.025196,-0.577992,0.450836,0.073509,-0.032462,0.575556,0.119273,-0.164026,0.024621,0.483956,0.657176,-0.018791,-0.262047,0.330308,0.041907,-0.236390,-0.911485,-0.092457,-0.110656,-0.409473,-0.429123,-0.263612,-0.237083,-0.068765,-0.152627,0.518386,0.064947,-0.168278,0.248177,0.254024,0.656422,-0.228005,0.471954,-0.015905,-0.343996,0.155406,-0.361841,-0.297069,0.203701,-0.022663,-0.376205,0.105936,0.317966,0.042212,0.508142,0.532268,-0.228635,0.180245,-0.435665,0.129654,-0.272449,0.239592,0.106622,0.385650,0.025300,-0.118230,0.241736,-0.299376,0.098362,0.222912,-0.138201,-0.686114,-0.020039,-0.008771,0.140369,-0.414170,-0.105463,-0.556399,0.240573,0.047535,-0.066573,0.192324,0.378924,0.096410,-0.236417,-0.138735,0.025629,-0.528401,-0.027817,0.349678,-0.139844,-0.143936,-0.328416,0.051648,-0.514202,-0.036334,0.048195,0.014698,-0.160093,0.697350,-0.086996,0.018290,0.422474,-0.572241,-0.166073,-0.578207,-0.013896,-0.172355,-0.325273,0.044486,-0.627901,0.034273,-0.126146,-0.183345,0.074602,0.242072,0.200726,0.420195,-0.416107,-0.009448,0.585017,0.344739,-0.452560,0.291507,0.009895,0.237029,-0.271649,-0.063984,0.410595,0.420006,0.418054,-0.011590,0.161613,0.256386,-0.237995,-0.098083,0.266709', '26747274', '1307442', '1865012', '3170961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10344754', '毒战', '剧情', '刚刚结束一次危险任务的津海市缉毒大队队长张雷（孙红雷 饰），在医院意外见到因车祸入院治疗的香港人蔡添明（古天乐 饰），身经百战的张队迅速判定蔡与毒品勾当有关。通过对蔡的审讯得知，有一车来自粤江的冰毒当天抵达津海，即将和当地的贩毒分子哈哈哥交易，而蔡正是双方联络的中间人。为保住性命，蔡添明积极配合，协助张队伪装成粤江赫赫有名的大毒枭黎振标的侄子与哈哈碰头。随后缉毒大队一路南下，途经蔡在鄂州的毒品加工厂，并最终抵达粤江与黎振标交易。周旋在狡猾凶狠的犯罪分子中间，任是经验丰富的张队也必须步步为营，小心应对。经过一番凶险的试探，双方终于迎来交易的最后时刻，但此时这盘杀机四伏的棋局也全然失去了控制……©豆瓣', '孙红雷', '杜琪峰', 7.5, 216439, 'tt2165735', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1924498395.jpg', 0.9, 3.8, 31, 47, 17.3, '0.064954,-0.027837,-0.548760,0.293429,0.128849,-0.240670,0.300708,-0.044841,-0.507482,-0.118243,0.196761,0.381730,-0.131323,-0.198054,0.252601,-0.499640,-0.120353,-0.551368,-0.311831,0.027705,-0.261589,-0.636120,-0.258985,-0.120858,0.191601,-0.002715,0.405085,0.501073,-0.096417,0.808861,0.368472,0.240413,-0.505249,0.485065,0.042176,-0.384175,0.181705,-0.150485,-0.663776,0.153298,0.196873,-0.295698,-0.093965,-0.122068,0.513291,0.657543,0.549437,-0.146664,-0.400484,0.121068,0.097155,-0.296723,0.108920,-0.219808,0.455669,0.096989,0.085722,0.155447,-0.365655,0.056974,-0.107664,-0.061550,-0.637099,-0.153315,0.235322,-0.067648,-0.429617,0.046699,0.156656,0.212330,0.132802,-0.210027,0.337833,0.664613,0.346646,0.115022,-0.004665,0.090397,-0.336351,0.042552,0.635924,-0.071562,0.094944,-0.095312,0.257844,-0.589267,0.059051,-0.344957,0.096694,0.223495,0.330569,-0.045133,-0.040948,-0.054460,-0.412569,-0.167634,-0.235348,0.006418,0.124442,-0.189946,0.102890,-0.846246,-0.041614,-0.136311,-0.082722,0.473051,0.126174,-0.099151,0.337453,-0.749985,0.044871,0.411832,0.071242,-0.485867,0.235771,0.272936,0.187272,-0.595647,-0.075083,0.033442,0.496326,0.396924,0.117240,0.287244,-0.199956,-0.213008,-0.233228,0.017820', '25723905', '1968438', '1305179', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10355329', '巴菲的奇妙命运', '剧情', '不会说话也听不见的Barfi（兰碧 卡普尔 Ranbir Kapoor 饰）是个快乐的青年。他聪明机灵鬼点子不少，四处惹是生非，让人又爱又恨。这样的日子因为Shruti（艾琳娜 Ileana 饰）的到来而发生变化，Barfi恋爱了。但Shruti早已定有婚约，在妈妈的一 番劝说阻拦之下，Shruti离开了大吉岭，去往加尔各答和她“对的人”结婚，留下Barfi一人失魂落魄。为此郁郁的Barfi还没来得及调整，和其相依为命的父亲却因为肾衰竭而住进了医院。手术需要7000卢比。Barfi慌乱中想到了一个办法，绑架当地有钱人家的自闭症孙女Jhilmil（朴雅卡•乔普拉 Priyanka Chopra 饰）。结果这个想法被人先行一步实施了，但阴差阳错，Barfi意外拾到了Jhilmil，筹到钱赶到医院时，父亲却已离去。对Barfi抱有好感的Jhilmil不肯回家，对此无可奈何的Barfi带着Jhilmil浪迹天涯起来。二人在山水田园城市巷道里，滋生了默契与爱意。在看似顺利的表面下，却潜伏着不安的因素，Barfi再次遇见了Shruti，且被认为是绑架犯，在这变化中，Barfi能否与Jhilmil再次相遇携手呢？', '佩丽冉卡·曹帕拉', '阿努拉格·巴苏', 8.3, 10467, 'tt2082197', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1806323790.jpg', 0.7, 2.6, 17, 41.8, 37.9, '0.283340,0.058096,-1.010782,0.466549,-0.071159,-0.413849,0.952138,0.004999,-0.550648,-0.211406,-0.065822,0.642394,-0.113799,0.147769,0.116686,-0.057872,-0.207610,-0.491850,0.180047,-0.172947,-0.275375,-0.482626,-0.157281,-0.153772,-0.072718,-0.294123,0.252228,0.290299,-0.026181,0.808235,0.354202,0.158648,-0.101507,0.731908,-0.223006,0.140993,-0.047159,0.200334,-0.114066,0.282432,0.293136,-0.272697,-0.290394,0.230969,0.043720,0.595715,0.550768,0.017646,-0.372304,0.125953,0.131351,-0.204429,-0.050358,0.298366,0.241265,-0.100482,0.126072,0.021641,-0.415710,0.110303,0.086279,0.086161,-0.566430,0.094377,0.124525,0.228918,-0.795464,0.473821,-0.047907,-0.189176,-0.142128,-0.334583,0.277211,0.422744,0.185210,0.485649,-0.182606,0.090352,-0.707861,-0.149257,0.760311,-0.095348,-0.069606,0.463492,-0.251186,-0.366069,0.070077,-0.116604,-0.384653,-0.168972,0.242132,0.258880,-0.413347,-0.035473,-0.250561,0.068672,-0.198285,0.146489,-0.215417,-0.608371,-0.002116,-0.104684,-0.027492,-0.325392,-0.544875,0.344231,-0.036973,-0.127490,0.483521,-0.817450,0.268498,0.337782,0.615193,-0.668213,0.717357,0.386026