INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10428476', '小屁孩日记3', '喜剧', '又是一年暑假，顺利结束七年级学业的格雷格·赫夫利（扎克瑞·戈登 Zachary Gordon 饰）已经作好规划，首先狂玩电动游戏，然后抽空和霍莉·希尔斯（佩顿·利斯特 Peyton List 饰）发展一下关系。当然热爱运动的老爹弗兰克（史蒂夫·赞恩 Steve Zahn 饰）并不认同他的死宅计划。受不了父母花样百出的暑期安排，格雷格和死党罗利·杰佛森（罗伯特·卡普荣 Robert Capron 饰）参加了乡村俱乐部，令他喜出望外的是霍莉竟然也在此地，当然还有强硬霸气的佩蒂（Laine MacNeil 饰）。此后不久，谎言被揭穿的格雷格被迫把老哥罗德里克（戴文·博斯蒂克 Devon Bostick 饰），惹出不少的笑话。周旋于野外训练营和乡村俱乐部，初中时代最后一个暑假拉开序幕……本片根据美国作家杰夫·金尼（Jeff Kinney）的同名畅销儿童系列读物改编。', '扎克瑞·戈登', '大卫·博维斯', 7, 9420, 'tt2023453', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1707153400.jpg', 0.8, 6.9, 46.8, 31.3, 14.3, '0.241932,-0.055105,-0.335447,0.332931,-0.088529,-0.281348,0.069310,0.064775,-0.265522,-0.374488,-0.034271,0.768384,-0.394292,0.018975,0.244607,-0.067392,-0.466045,-0.625796,0.113051,-0.052167,0.015147,-0.657795,-0.063676,-0.241764,0.031966,-0.403636,0.430275,-0.192066,-0.155327,0.461830,0.337744,0.280626,0.199701,0.061935,0.127289,0.128119,0.238086,0.022538,-0.339673,0.099385,0.048122,0.015095,-0.136828,-0.048494,0.459946,0.312241,0.586718,0.054334,-0.033328,-0.179472,0.479285,-0.176475,-0.020705,0.038732,0.377081,-0.134215,0.183237,0.408395,-0.024000,0.158885,0.152579,-0.344249,-0.470230,0.251170,0.117054,-0.116259,-0.267461,0.418688,-0.169222,0.022142,-0.051896,-0.319199,-0.025577,0.376351,0.456610,0.195749,0.136600,0.126501,-0.216976,0.382475,0.405583,-0.041460,-0.255894,0.184406,-0.059846,-0.170132,0.017495,-0.158976,-0.497850,0.066177,0.326464,-0.073168,-0.107502,0.166800,-0.435186,-0.064615,-0.251836,-0.379962,0.069415,-0.304914,0.049413,-0.827897,0.169303,-0.194719,-0.178281,-0.066279,0.196376,-0.183550,0.455840,-0.621019,0.127417,0.387957,0.127905,-0.229696,0.377691,-0.052698,0.300960,-0.266895,0.131149,0.206007,-0.023450,-0.091199,0.179371,0.528853,0.107876,-0.552909,-0.241837,0.562663', '25723905', '31