INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10428501', '新·福音战士剧场版：终', '剧情', '成为“第三次冲击”元凶的碇真嗣，变得像废人一样……真嗣还能振作起来吗？2012年《福音战士新剧场版：Q》之后，这部动画讲述了被封印的故事的后续。', '绪方惠美', '庵野秀明', 9.2, 64154, 'tt2458948', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2636146386.jpg', 1.1, 1.4, 6.2, 17.9, 73.4, '-0.093651,-0.002162,0.003264,0.478704,0.191247,-0.352855,0.139248,0.192008,-0.531412,-0.148211,-0.301611,0.580625,-0.591101,0.115811,-0.105885,0.075641,-0.511069,-0.717619,-0.282366,-0.110108,-0.129736,-0.016624,-0.307272,-0.021508,0.022520,-0.765401,1.053599,0.018189,-0.254302,-0.251082,0.136242,0.335205,0.137722,0.183981,0.001331,0.525777,-0.300535,0.263767,-0.003721,0.715191,-0.097226,0.091042,0.261892,0.269420,-0.289157,0.176899,0.594285,-0.159855,-0.120657,-0.180152,0.645037,-0.092017,-0.407935,0.275707,0.271340,0.291109,0.188005,0.478395,-0.195433,-0.012265,-0.385601,-0.494446,-1.020877,-0.235946,0.000862,-0.115162,-0.148776,-0.054365,0.169358,0.493289,0.438094,-0.307740,0.192775,0.334060,1.032025,0.482138,-0.222974,0.223165,-0.197014,0.704991,0.699947,-0.273572,-0.886996,0.769161,0.387127,-0.267783,-0.709683,-0.410652,-0.192394,0.634421,0.309070,0.138061,-0.345374,0.190003,-0.643805,-0.529510,-0.450546,-0.313051,-0.011717,-0.223790,-0.019118,-0.582216,-0.260276,0.026565,0.505705,-0.170418,-0.055224,-0.629188,0.980853,-0.585340,0.630421,0.403557,-0.038015,-0.200337,-0.109397,0.096333,-0.124929,-0.241390,0.467206,0.188564,-0.254352,0.509446,0.401660,-0.008985,-0.033514,-0.165425,-0.445751,0.700859', '6844861', '27602116', '26759820', '35151491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10429695', '灵动：鬼影实录4', '恐怖', '五年前，仿佛被魔鬼所控制的凯蒂（Katie Featherston 饰）杀害了自己的男朋友、姐姐、姐夫，并带走他们尚在襁褓中的孩子亨特，不知所终。时间来到2011年，一个平凡幸福的四口之家，美丽女孩爱丽克丝（凯瑟琳·牛顿 Kathryn Newton 饰）过着无忧无虑的生活，她每天和男友本（麦特·西弗里 Matt Shively 饰）通过视频聊天，平日里本也会拿着摄像机随时拍摄。某天，无依无靠的小男孩罗比（Brady Allen 饰）入住爱丽克丝的家，罗比沉默寡言，并声称有一个名叫托比的朋友。爱丽克丝他们起初不以为意，但是渐渐却发现房屋里接二连三有奇怪诡异的事情发生。在本的建议下，他们在家中各个角落安装摄像头，监控着白天夜晚所发生的一切。屏幕前，令人匪夷所思且毛骨悚然的景象悄悄上演……©豆瓣', '凯蒂·菲德斯通', '亨利·朱斯特', 5.5, 6965, 'tt2109184', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1655123188.jpg', 9.1, 28.5, 44.6, 12.5, 5.2, '0.151441,-0.012756,-0.723470,0.305000,-0.033568,0.096811,0.915597,0.152616,-0.572846,-0.551641,0.126586,0.560318,-0.332872,0.539923,0.261137,0.141430,-0.492858,-0.639151,-0.167405,-0.264333,-0.249656,-0.383996,-0.192207,-0.332160,0.233815,-0.289783,0.170885,-0.035900,0.307733,0.424176,-0.018247,-0.039458,-0.513708,0.497815,-0.204190,-0.054027,-0.003303,0.184126,-0.118386,-0.057654,-0.166691,-0.067145,-0.185065,-0.051819,0.151088,0.261895,0.681987,-0.462222,-0.439234,-0.067331,0.311716,0.133591,-0.061889,0.054075,0.087779,-0.103626,0.280407,0.052577,-0.154000,0.063058,0.183560,-0.070984,-0.550143,0.135977,-0.042610,0.211461,-0.406689,0.415241,-0.052573,0.089238,0.178699,-0.480477,0.264114,0.204147,0.217197,0.340809,-0.255770,0.057513,-0.616330,0.153646,0.467198,0.164266,-0.298395,0.465056,-0.173142,-0.108692,-0.066036,0.013850,-0.683769,0.151487,0.260141,-0.043705,-0.206458,0.213005,-0.400714,0.111552,-0.032515,-0.102343,0.032846,-0.391096,-0.275190,-0.772331,-0.044445,-0.354289,-0.501803,0.092420,-0.219222,-0.258718,0.623996,-0.683346,0.401037,0.581989,0.248152,-0.174267,0.580270,0.112587,0.222578,0.040538,-0.367168,0.258666,0.202781,0.422598,0.045864,0.251716,-0.291522,-0.071522,-0.405565,0.346781', '10466639', '1296534', '1301686', '12965