INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10432181', '思维空间', '剧情', '约翰有能看到别人记忆的特殊能力，他的新案子调查对象是个聪颖却有精神问题的十六岁少女安娜。约翰必须解开谜团：安娜究竟是反社会还是神秘精神创伤的受害人……', '马克·斯特朗', '豪尔赫·多拉多', 6.8, 6845, 'tt1715336', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2215241113.jpg', 1.1, 7.5, 51.8, 31.6, 7.9, '0.008706,0.269126,-0.082266,0.256472,-0.496471,0.067673,0.454365,-0.221848,-0.773590,-0.647828,0.362805,0.456822,0.276113,0.436064,-0.029103,0.346397,-0.413812,-0.510900,0.461754,-0.039468,-0.531117,-0.879184,-0.653091,-0.104208,0.339874,-0.681357,0.577805,-0.007474,-0.311001,-0.344689,0.283446,0.563878,0.001737,0.544724,-0.122180,-0.307989,0.345722,-0.267532,-0.140193,-0.058892,0.202296,-0.239397,-0.241256,0.363207,-0.217104,0.572537,0.375953,-0.041608,-0.392507,0.116720,0.568366,0.109186,-0.184367,-0.094312,0.327764,-0.072408,0.116484,0.343273,0.323958,-0.297769,0.001751,0.191112,-0.624586,-0.237939,0.482204,0.555770,-0.259942,-0.162295,-0.249084,-0.195662,0.015743,-0.366729,-0.369653,0.119823,0.442550,0.358043,0.058583,0.259552,-0.184704,-0.176487,0.340398,0.067357,-0.441671,0.529618,-0.668566,-0.757208,-0.230842,-0.092298,-0.248658,0.523732,0.343035,0.207690,-0.382116,0.362440,-0.283306,-0.093631,-0.249264,0.205995,-0.193451,-0.230594,0.010197,-0.097114,-0.550288,-0.077807,-0.546820,-0.337851,0.213347,-0.291698,0.762152,-0.746721,-0.066276,0.923443,-0.011103,-0.760834,0.268398,0.119853,-0.123344,-0.975112,-0.401771,0.253741,-0.354891,0.148389,-0.480451,0.244462,0.398643,-0.471488,-0.485269,0.522721', '25834333', '1297689', '3263169', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10432911', '流感', '剧情', '一群东南亚偷渡客历经艰险来到韩国，但是整个集装箱内的偷渡客几乎全部死亡，只有一人拖着羸弱的身体侥幸逃入闹市之中。殊不知此人身上携带致命猪流感病毒，短短一天时间，病毒迅速蔓延城市的各个角落。许多人在不知不觉间被感染，进而将死亡的阴影引向周围所有的人。美丽的女医生金仁海（秀爱 饰）是一位单身妈妈，她不久前遭遇一场车祸，幸被消防队救援人员姜智久（张赫 饰）救出，却因丢失重要论文资料而备受上司苛责。值此期间，韩国蛇头的弟弟因流感送入仁海的医院治疗，经诊断终于发现流感的起因，死尸横陈的集装箱无疑成为查找病源的关键。未过多久，猪流感病毒成几何式爆发蔓延，坐享太平的民众面临前所未有的灾难……©豆瓣', '张赫', '金成洙', 7.8, 348110, 'tt2351310', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2029391129.jpg', 1.1, 3.6, 25.1, 47, 23.3, '-0.006970,-0.065749,-0.540192,0.052759,0.229632,0.228403,0.723056,-0.072152,-0.618368,-0.242131,0.525132,0.350333,-0.231446,0.032884,0.079963,-0.244390,0.095646,-0.526664,-0.334620,0.045210,-0.579826,0.126143,-0.321708,-0.033646,0.012836,-0.350021,0.607330,0.531774,0.001246,0.326378,-0.091271,0.557474,-0.419112,0.443806,-0.051482,-0.076554,0.006842,-0.240854,-0.143062,0.304849,-0.061669,-0.391259,0.104171,0.010945,-0.290986,0.199592,0.874959,-0.157789,-0.192182,-0.333199,0.627216,-0.376447,-0.187149,0.091809,0.482745,0.216358,0.240124,-0.028961,-0.266309,-0.003316,0.110584,-0.010321,-0.542576,-0.254830,0.066352,0.243551,-0.198975,0.425668,0.210613,0.125011,-0.006638,-0.018269,0.208167,0.201786,-0.053703,0.273938,-0.170548,0.104580,-0.432523,-0.057434,0.645435,-0.394528,-0.429875,0.122301,-0.221603,-0.373564,0.099981,-0.347287,-0.173901,0.130281,0.202701,0.181809,-0.323933,0.393994,-0.341784,0.149327,-0.463432,-0.462057,-0.058550,0.067827,-0.383648,-0.569943,-0.127441,-0.075001,-0.081025,0.079845,0.025684,-0.057026,0.546330,-0.292378,0.396785,0.386714,-0.095404,-0.354414,0.175618,-0.237462,0.356574,-0.062594,-0.148153,0.543348,0.227162,0.470309,0.061724,0.003932,-0.548673,-0.051321,-0.415622,0.289099', '25986180', '1309088', '21619567', '3148064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10437779', '新世界', '剧情', '金门集团会长、暴力组织在虎派大佬石东出遭遇车祸身亡，该事件在黑白两道引起不小震荡。为了遏制金门集团进一步向合法领域渗透并持续壮大，警方及时提出“新世界计划”，旨在干预金门集团继任大佬的选举。而围绕会长头衔，金门旗下三号人物华侨出身的丁青（黄正民 饰）和四号人物常务理事李仲久（朴圣雄 饰）展开一连串明争暗斗。在危机四伏的当下，警方姜科长（崔岷植 饰）命令卧底十年之久的李子成（李政宰 饰）左右选举结果。子成六年前和丁青结识，并且得到对方的器重和信任。早已厌倦黑道生活的子成无奈受命，却无疑将自己投入了凶险非常的黑色漩涡之中。充满鲜血与欲望的战场，新世界何日来临？©豆瓣', '李政宰', '朴勋政', 8.9, 378125, 'tt2625030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1903379979.jpg', 0.2, 0.5, 7.7, 37.8, 53.9, '-0.339167,0.362463,-0.463531,0.534726,0.283426,0.252026,0.259829,0.308841,-0.638894,-0.319304,0.261768,0.429132,-0.202040,-0.009989,0.337444,-0.301056,0.006104,-0.727560,-0.145098,-0.059794,-0.117502,-0.361037,-0.074484,-0.270433,-0.072250,-0.235982,0.909231,0.490506,-0.293855,0.270503,0.401413,0.601139,-0.457910,0.437581,0.292692,-0.213357,0.421758,0.112160,-0.670972,0.074106,-0.156021,-0.300385,0.101654,0.140830,0.141647,0.202858,0.214148,-0.149359,-0.225569,-0.361843,0.294420,-0.360310,-0.122617,0.040378,0.864633,0.274127,0.113299,0.510093,-0.188009,-0.164368,-0.128126,-0.197258,-0.758404,-0.072120,0.447326,0.084998,-0.450127,0.273963,-0.123316,-0.047225,-0.103032,-0.150814,0.020016,0.755186,0.212836,0.067387,-0.137929,0.383340,-0.323829,0.087903,0.576087,-0.142496,-0.365568,-0.224570,0.129339,-0.413274,-0.304208,-0.244142,-0.069374,-0.115097,0.300961,0.049247,0.189886,0.513197,-0.350508,-0.082857,-0.161880,-0.233508,0.360051,-0.198169,0.054291,-0.718950,-0.352203,-0.028509,0.013567,0.009178,0.051732,0.008644,0.352254,-0.796388,0.114072,0.280913,0.225858,-0.575358,0.401756,0.115366,-0.010412,-0.675363,-0.137809,0.108873,0.282680,0.251876,-0.015020,-0.011686,-0.172256,-0.294962,-0.041463,-0.041894', '3861846', '26691320', '1307914', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10438426', '浮城谜事', '剧情', '警察童明松（祖锋 饰）负责调查一起车祸，大学生蚊子（常方源 饰） 意外惨死，童明松决定同哥们儿——喜欢蚊子的修车工秦枫（朱亚文 饰）一起调查事件真相。两人追查真相时牵扯出了中产阶级夫妻乔永照（秦昊 饰）和陆洁（郝蕾 饰），陆洁因为女儿在幼儿园的玩伴宇航，认识了她的妈妈桑琪（齐溪 饰），却在与其交往的过程中发现了丈夫的外遇……随着蛛丝马迹的层层披露，事情越来越蹊跷，童、秦二人发现乔永照、陆洁、桑琪都藏有不可告人的秘密。©豆瓣', '郝蕾', '娄烨', 7.5, 149191, 'tt2369127', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1722545381.jpg', 0.5, 2.8, 32, 50, 14.7, '0.210507,-0.375276,-0.478128,0.191407,0.252738,-0.122324,0.715973,0.136465,-0.563009,-0.434418,0.055656,0.244415,-0.336828,0.055278,0.167493,-0.146134,-0.400971,-0.688071,0.246417,-0.263501,-0.287447,-0.561393,-0.162655,-0.345405,-0.019322,-0.040751,0.304492,0.139203,-0.186966,0.467342,0.546396,0.101019,-0.691861,0.380830,0.036161,0.086651,0.178803,0.418050,-0.326493,-0.270952,0.103647,-0.116561,0.072169,-0.162064,0.177444,0.477520,0.495272,0.083272,-0.096383,0.002830,0.251389,0.099288,0.017333,-0.041143,0.502002,0.130581,0.357484,0.378135,-0.217486,-0.066476,0.288161,0.259747,-0.225554,0.036030,0.461934,0.494957,-0.374845,0.141706,0.055107,0.075792,0.228623,-0.115622,0.310626,0.355721,0.256304,0.127070,-0.123253,0.161233,-0.559788,0.387240,0.365525,-0.101176,0.402476,0.275538,-0.102286,-0.480152,-0.212522,0.275081,-0.308963,0.281306,0.261311,-0.175381,-0.397982,0.317403,-0.314884,-0.507604,0.118755,0.305325,-0.178193,-0.243524,0.145370,-0.523327,-0.186051,-0.388504,-0.328285,0.215030,-0.136862,-0.129854,0.357669,-0.534347,0.088838,0.421064,0.155255,-0.626301,0.521071,0.166864,0.074001,-0.563901,0.010243,0.010608,0.037842,-0.082579,0.232250,0.304770,0.139504,-0.448978,-0.192611,-0.273055', '3263169', '1299667', '1303269', '1301928');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10438581', '芭芭拉', '剧情', '女医生Babara（尼娜·霍斯 Nina Hoss 饰）因为企图从民主德国逃到联邦德国未遂，而被从柏林调遣到一所乡村医院工作，一开始她根本不和周围的人来往，直到医生Andre（隆纳德·泽荷菲德 Ronald Zehrfeld 饰）主动和她接近。医院里新送来一名女孩Stella，得的是脑膜炎，在Babara的细心呵护下逐渐康复。女孩却又因为怀孕了而被送去东德的劳教所。而另一方面，Babara在男友的帮助下积极准备下一次逃亡计划。虽然她还要不时地遭到东德警察的搜查，但是她隐藏得无懈可击。医院里又送来一名自杀未遂的男病人，Babara认为他需要动手术。Andre决定在周六晚上对这名病人进行手术，需要Babara的协助，而周六晚上正是Babara要进行逃亡计划的时间。正在她准备离开家的时候，Stella从劳教所逃出来找到了她.......导演Christian Petzold凭借此片获得2012柏林电影节最佳导演银熊奖。', '尼娜·霍斯', '克里斯蒂安·佩措尔德', 7.5, 6297, 'tt2178941', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2207092375.jpg', 0.4, 2.4, 32.2, 51.2, 13.8, '0.071810,0.089058,-0.805403,0.474969,-0.198646,-0.284647,0.649437,0.129578,-0.403726,-0.347981,0.241173,0.493797,0.046025,0.288660,0.449318,0.037017,-0.524598,-0.642128,0.024552,-0.136057,-0.636016,-0.346943,-0.103816,-0.232292,0.061415,-0.389979,0.477531,0.119351,-0.108878,0.307989,0.067857,0.147260,0.122101,0.747950,-0.255547,-0.272691,0.104906,-0.291841,-0.208935,0.794201,0.686079,-0.427922,-0.442843,0.273883,0.158216,0.606799,0.790518,0.002572,-0.176420,-0.089327,0.434949,-0.226138,-0.009841,0.164017,0.394160,0.117952,0.305370,0.176428,-0.288783,0.195059,0.051288,-0.274216,-0.564503,0.199267,0.116054,0.192215,-0.728732,0.168695,-0.262853,0.208337,0.156357,-0.631044,0.101196,0.535365,-0.087974,0.516969,-0.201268,-0.085378,-0.580788,0.164395,0.700419,-0.232141,0.012802,0.512763,0.117126,-0.441973,0.192863,-0.089220,-0.440351,0.006097,0.218027,-0.027831,-0.307846,-0.307623,-0.384807,-0.017728,-0.461217,-0.506456,-0.185732,-0.133528,-0.059007,-0.752088,0.153319,0.002019,-0.306716,0.183447,0.114705,-0.123704,0.588669,-0.920900,0.325082,0.726485,0.466461,-0.727115,0.570184,0.011404,0.163558,-0.276020,-0.191864,-0.010237,0.079580,0.658062,0.172144,0.434493,-0.233927,-0.386504,-0.581141,0.234101', '2079017', '1301022', '2990737', '35270213');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10438691', '副作用', '剧情', '四年前，丈夫Martin（查宁·塔图姆 Channing Tatum 饰）的入狱让Emily（鲁妮·玛拉 Rooney Mara 饰）陷入了忧郁之中。如今Martin出狱了，Emily的忧郁并没有减少，反而企图在停车场开车自杀。自杀未遂后，医生Jon（裘德·洛 Jude Law 饰）开始对她进行治疗。Jon了解到Emily以前的医生是Siebert，便找Siebert了解了一些情况。Jon给Emily开了几种治忧郁症的药，似乎都没作用。Emily提出让她服用一种叫Ablixa的药，是她的同事Julia向她推荐的。服用了这种新药之后，Emily病情有所好转，却开始梦游。Jon告诉她，梦游是服用这种药的副作用。一天晚上，Martin回到家中，发现Emily在厨房梦游，Emily更拿着刀刺中了Martin。Martin死亡，法院判处Emily无罪，但她必须在一个精神病院接受治疗。Jon因为此事也陷入漩涡之中，他开始调查起整个杀人事件的前因后果，发现此事并非只是Emily服用了药产生副作用那么简单，还有更多人牵涉其中......', '裘德·洛', '史蒂文·索德伯格', 7.4, 49423, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1927063194.jpg', 0.3, 2.6, 35.5, 51.1, 10.6, '0.206890,0.107168,-0.386388,0.327878,-0.317217,-0.038190,0.924052,0.073235,-0.560249,-0.477298,0.009883,0.354218,-0.160853,0.228558,0.116469,-0.067208,-0.346015,-0.496096,0.320595,-0.081180,-0.753690,-0.472872,-0.112226,-0.185060,-0.047516,-0.522777,0.271332,0.172876,-0.462674,0.230515,-0.110971,0.374402,0.461940,0.754075,0.063389,0.115229,-0.224104,-0.133547,-0.114363,0.644848,0.674225,-0.693788,-0.044430,0.574144,0.240555,0.575896,0.489122,-0.049142,-0.701790,-0.081511,0.507345,-0.243325,-0.127357,0.069843,0.301426,0.330763,0.091872,0.077377,-0.495370,0.147256,-0.201867,0.293106,-0.557633,-0.022060,-0.056347,0.311042,-0.549958,0.102667,-0.197888,0.109033,-0.248871,-0.228352,0.299008,0.477049,0.082526,0.333088,-0.292231,-0.217510,-0.848658,0.042683,0.594630,-0.267612,-0.160171,0.634264,-0.144172,-0.586877,0.168582,0.024319,0.058582,0.134912,0.195221,0.379160,-0.364904,0.128819,-0.176348,-0.047504,-0.254725,-0.475032,-0.152972,-0.013686,0.090071,-0.369489,-0.148321,-0.023842,-0.565625,-0.257838,0.167208,-0.365906,0.308943,-0.658121,0.441816,0.326835,0.306940,-0.784958,0.348116,-0.039582,-0.034833,0.046599,0.017598,0.222445,0.134994,0.329