INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10439235', '创可贴', '剧情', '消防员与医生，两种不同的职业，性质却是一样的，都是救人于水火之中。但同样的，身处这两种职业的人们也需要被治愈，需要创口贴来愈合伤口。作为消防员的姜一（高修 饰）整日穿梭于大街小巷，拯救他人生命，可却挽救不了妻子的生命；大大咧咧，看似没心没肺的女医生美秀（韩孝珠 饰）内心却因为一次医疗事故而封闭了自己。二位满身伤口的人相遇于一次救助行动，美秀被姜一所吸引，大胆展开了追求，熊熊烈火，冰山也会渐渐融化。每日都与死亡打交道，但也见证生命的力量和奇迹的诞生，让二人更加体会到生存的意义和眼前人的珍贵，在一来一往中，互相抚慰了内心的伤痛，成为了彼此伤口的创口贴。©豆瓣', '高修', '郑基训', 7.4, 39880, 'tt2592808', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1768410538.jpg', 0.8, 4.5, 37.1, 41.7, 15.9, '0.203571,-0.010930,-0.464458,0.504558,-0.254035,-0.104483,0.988434,0.183995,-0.496460,-0.027974,0.381359,0.667791,-0.290302,0.119366,0.022417,-0.229760,0.206670,-0.812810,-0.011456,0.128320,-0.618220,-0.355187,-0.490060,-0.367713,-0.148871,-0.592152,0.770603,0.343831,-0.305078,0.456019,0.082758,0.189461,-0.158512,0.737689,-0.288588,-0.305668,-0.352097,0.102658,-0.280064,-0.011656,0.143283,-0.279112,-0.032522,0.385563,-0.344025,0.473341,0.965862,-0.269006,-0.064308,-0.042248,0.394889,-0.431746,0.139634,0.173472,0.048253,0.007001,0.278540,0.148627,0.031029,0.089357,0.154844,0.140762,-0.984441,-0.169679,0.299562,0.248467,-0.670471,0.631547,0.082789,-0.217127,-0.266744,-0.343569,0.315216,0.074815,0.152115,0.593992,-0.415505,-0.286446,-0.413996,0.105871,0.689591,0.009378,-0.544969,0.526974,-0.687362,-0.567911,-0.248714,-0.343613,-0.346903,-0.077702,-0.058286,0.388696,-0.310493,0.356235,-0.855323,0.236244,-0.298083,-0.209320,-0.042475,-0.365718,0.057645,-0.555682,-0.449304,-0.465565,-0.492365,0.089691,0.248299,-0.342993,0.855392,-0.776641,-0.000063,0.422792,0.117113,-0.509234,0.767943,0.291539,0.120912,-0.176947,-0.155432,0.356613,0.137077,0.389733,0.179642,0.403733,-0.227465,0.489968,-0.524777,0.628085', '26667010', '3005387', '25774050', '6021916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10439245', '人类灭亡报告书', '剧情', '《美丽新世界》相貌平平的研究院尹石宇（柳承范 饰）从未想到，他的一个无心之举竟然引发了前所未有的灾难。在和女友用餐过后，他被一种神秘病毒感染，随即变得情绪极不稳定，破坏力惊人。在很短的时间内，病毒以极快速度蔓延，城市的街头被恐怖丧尸所占领……《天工开物》原本生产出来用 于清洁工作的RU-4机器人，在寺院服务一段时间后竟突然有了自己的意识，它了悟空性，超然解脱，令未来社会里过度依赖机器人的人类恐慌不已。机器人修理工朴道远（金康宇 饰）不愿相信眼前的事实，可是他的内心也悄悄发生着转变……《生日快乐》小女孩不慎打破了父亲收藏的黑8台球，惶恐的她打算在败露前网购一枚新的台球。两年后，一颗黑8模样的小行星向地球撞来，世界灭亡在即。©豆瓣', '金康宇', '金知云', 6.2, 6270, 'tt2297164', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173863906.jpg', 4.8, 17.8, 46.6, 23, 7.9, '0.046862,0.359848,-0.878664,0.502311,-0.123865,0.008602,0.820450,0.098112,-0.470377,-0.207611,0.203871,0.571668,-0.461709,0.173705,0.105780,-0.098176,0.055427,-0.346312,-0.353111,-0.257605,-0.337692,-0.159495,-0.564988,-0.320953,-0.052174,-0.466141,0.505015,0.169505,-0.294927,0.217931,-0.068881,0.257135,0.048786,0.656917,-0.057999,-0.231413,-0.108546,-0.101066,-0.085700,-0.047454,0.159922,-0.382458,0.109209,0.385068,-0.428434,0.087493,0.849687,-0.301353,-0.487322,-0.313183,0.589469,-0.047234,-0.116143,-0.109145,0.376045,0.106808,-0.068343,-0.064306,-0.235086,0.125845,0.281713,0.002649,-0.553743,0.132282,-0.142465,0.198460,-0.331066,0.470292,-0.204917,-0.139958,0.083559,-0.492927,0.028484,0.278904,0.380930,0.416897,-0.294711,0.068620,-0.425621,0.127195,0.539280,0.055020,-0.679280,0.553229,-0.415139,-0.443139,-0.240998,-0.154229,-0.427887,-0.168718,0.422580,0.176142,-0.377531,0.482614,-0.555022,0.058360,-0.292067,-0.182045,-0.178528,-0.149395,-0.339080,-0.367393,-0.144749,-0.438513,-0.251691,-0.171596,0.059937,-0.101311,0.664712,-0.810254,0.223665,0.565323,0.189098,-0.338508,0.329248,-0.263686,-0.102987,-0.157011,-0.037336,0.235846,-0.110762,0.584223,0.135971,0.382282,-0.125353,-0.050727,-0.407809,0.741237', '35115642', '3005387', '20515070', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10439358', '狼狈', '剧情', '影片改编自漫画家冈崎京子的同名漫画，由日本摄影大师蜷川实花执导。成为2012年日本YAHOO网站搜索第一的电影，荣获日本GRP Award 2012年度最优秀电影奖！又肥又丑的莉莉子（泽尻英龙华 饰）原本在专供有“肥妹廦”人士寻欢的夜店内工作。进行了风险极高的全身整容手术，脱胎换骨后的莉莉子，凭着人造天使脸孔以及魔鬼身材，火速成为各大顶尖时装杂志，以及国际名牌的御用model，实现了一直以来的梦想。正当莉莉子享受着五光十色的美好之时，不知不觉中，整形手术的后遗症开始侵袭她那具那经过精心雕琢一触即碎的身体。而她的生活与事业也不同程度遭受挫折，原本约定好的结婚对象毁弃婚约，与别的女人出双入对；拥有更加可人容貌的新人模特则虎视眈眈奋起直追，时刻觊觎莉莉子好不容易到手的时尚女王宝座。终极之美土崩瓦解的一刹那，恰是从天堂跌落地狱的恐怖时刻……©豆瓣', '泽尻英龙华', '蜷川实花', 7.2, 82886, 'tt2147319', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1628688457.jpg', 1, 6.5, 40.1, 37.9, 14.5, '-0.009504,0.165135,-0.724863,0.451823,0.232094,-0.189070,0.439609,0.279649,-0.215119,-0.329251,0.376842,0.709025,-0.389792,0.141953,0.350906,0.083931,-0.057246,-0.697637,-0.205373,-0.110926,-0.123165,0.133831,-0.414859,0.199588,-0.177961,-0.525946,0.924881,-0.094639,-0.263808,0.293132,0.341661,0.124838,0.014253,0.041324,-0.061833,-0.271441,0.119382,0.111663,-0.319106,0.243249,-0.013737,-0.137853,0.097708,-0.101275,-0.199570,-0.002149,0.679184,-0.307908,-0.038693,-0.367427,0.664603,-0.069216,-0.223938,0.240131,0.222469,0.088504,0.360554,0.089556,-0.209011,-0.047896,0.260315,-0.189769,-0.586921,-0.189642,0.189174,0.137230,-0.355637,0.283937,-0.038547,0.091723,0.260009,-0.242469,0.100646,0.147947,0.228870,0.327395,0.071138,0.160242,-0.365146,0.451567,0.355553,0.250275,-0.379872,0.345305,-0.103710,-0.432283,0.035354,-0.514996,-0.202403,0.059913,0.194404,0.077278,-0.020348,0.287663,-0.800378,0.210595,-0.141010,-0.148536,0.110787,-0.245230,-0.229408,-0.899069,-0.257418,-0.292248,-0.068362,-0.197903,0.211686,-0.363345,1.013478,-0.778935,0.226031,0.514601,0.159656,-0.400060,0.541195,0.009669,-0.041980,-0.087379,-0.352054,0.313517,-0.165525,0.405907,-0.177742,0.243817,-0.228741,-0.089964,-0.304566,0.685533', '25863940', '1322847', '3811356', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10439805', '波西·杰克逊与魔兽之海', '动作', '电影《波西·杰克逊与魔兽之海》由《小屁孩日记》导演托尔·弗洛伊德桑尔执导，讲述波西·杰克逊在混血人集中营平静的度过七年级后，忽然日子就变的纷乱了起来，原本和同学间的躲避球竞赛，阴错阳差的变成了一场死亡游戏，丑陋的食人族巨无霸也跟着搅和其中，波西无意中发现，他们的家园和族人正遭遇空前的灾难，必须找到“金羊毛”，才能拯救众人，为了解除灾难，波西奋不顾身带着伙伴们共同踏上冒险的旅程，他们要到魔兽之海完成任务，才能取得金羊毛并拯救面临毁灭的混血人集中营，在这趟危机重重的冒险之旅中，他们将会遇到哪些惊人的意外难关?他们真的能够顺利的突破困难，并且让所有族人和希腊众神们幸免于难吗?', '罗根·勒曼', '托尔·弗罗伊登塔尔', 5.9, 20688, 'tt1854564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2011597123.jpg', 4.5, 22.6, 52.5, 14.7, 5.6, '-0.009174,0.012381,-0.482405,0.439654,0.272679,-0.289519,0.665400,-0.190722,-0.355265,-0.013241,0.129375,0.703014,-0.085861,0.061194,0.524692,-0.221949,-0.359940,-0.588828,-0.222509,0.024104,-0.452791,-0.192155,-0.474383,-0.281458,0.011513,-0.497904,0.737998,0.423011,-0.178748,0.317979,0.149564,0.341954,-0.453177,0.285121,-0.033340,-0.047128,0.049980,0.302618,-0.529452,0.174161,0.001022,-0.017397,-0.371911,0.261034,0.240140,-0.014795,0.577419,-0.422904,-0.122893,-0.079606,0.105595,-0.481827,-0.180992,-0.004710,0.236806,-0.098755,0.273229,0.263489,0.287853,0.134690,0.104746,-0.437443,-1.029191,0.170542,0.061820,0.188276,-0.291279,0.144666,0.400999,0.181532,0.362124,-0.165491,-0.063273,0.746027,0.523471,0.307091,-0.189109,-0.104896,-0.464364,0.196819,0.927420,-0.442348,-0.335749,-0.003717,-0.050743,-0.519592,0.063308,-0.265875,-0.351253,0.307381,0.549029,0.179993,-0.189318,0.479992,-0.844221,-0.096776,-0.359295,-0.551320,-0.100224,-0.252798,0.096337,-0.599197,-0.028738,0.141316,-0.224524,0.343688,0.058988,-0.391326,0.596965,-0.708637,0.366950,0.488349,0.136932,-0.420062,0.343936,-0.135431,0.366581,-0.392772,0.025851,0.280032,-0.020443,0.586784,0.197829,0.071167,-0.029509,0.077696,-0.396768,0.492144', '25828589', '26678784', '2032339', '35377026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10440069', '丹尼·科林斯', '剧情', '1970年代传奇摇滚乐手丹尼柯林斯（阿尔·帕西诺 Al Pacino 饰）在经历人生低潮时，经纪人（克里斯托弗·普卢默 Christopher Plummer 饰）发现了一封40年来从未送达的信，这封信居然来自披头士主唱约翰·列侬，在40年前写给当时19岁的他，这让他再度受到启发，毅然决然地离开现在奢华的生活，踏上寻找生命意义的旅程，而他也在这段旅程中收获了真爱和消失已久的创作灵感……', '阿尔·帕西诺', '丹·福格尔曼', 7.6, 6898, 'tt1772288', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2266030418.jpg', 0.4, 2.5, 30.3, 49.1, 17.6, '0.113954,0.088834,-0.815940,0.644593,-0.018997,-0.386789,0.807604,-0.186845,-0.641341,-0.463870,0.162517,0.907094,-0.207728,0.191967,0.655680,-0.128613,-0.266226,-0.600763,0.336944,-0.472334,-0.093063,-0.493842,-0.261601,-0.128557,0.145648,-0.757431,0.659800,0.284537,-0.090380,0.773231,0.173804,0.177712,0.133389,0.387030,-0.284921,0.406822,0.351142,0.358644,-0.270432,0.322670,0.173341,-0.289457,-0.102428,0.201602,-0.172462,0.048656,0.595414,-0.310502,-0.112554,0.281998,0.611922,-0.185815,-0.070841,0.003339,0.026554,0.099209,0.133628,0.408365,-0.239170,0.099927,-0.160012,-0.321988,-0.750943,-0.091261,-0.211970,0.217807,-0.507300,0.372077,-0.170900,0.033554,-0.095529,-0.325071,0.353554,0.449304,0.452921,0.376236,-0.071390,0.056058,-0.247936,0.322156,0.589629,-0.247042,-0.217773,0.535981,-0.261584,-0.434357,-0.280875,-0.003949,-0.718661,0.294997,0.317187,0.309298,-0.199928,0.144762,-0.723421,0.188570,-0.191022,-0.152195,0.167538,-0.364148,-0.420385,-0.468802,-0.223536,-0.362583,-0.163791,-0.095256,-0.002772,-0.403548,0.592200,-0.415362,0.549423,0.589627,0.208465,-0.150811,0.886912,0.238309,-0.144136,-0.298349,0.122619,0.801761,-0.097792,0.405462,-0.066939,-0.009707,0.062855,-0.114937,-0.592397,0.813891', '1460341', '1299663', '1297598', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10440076', '最后的巫师猎人', '动作', '考尔德（范·迪塞尔 Vin Diesel 饰）是一名女巫猎人，在黒巫后的诅咒之下，他得到了不灭的灵魂和不朽的躯体。永生带来的痛苦远远大于欢愉，在孤独和绝望之中，考尔德度过了漫长的时光，然而，他却从未放弃过身为一名巫师猎人所应尽的职责，他知道，女巫并没有绝迹，一个巨大的阴谋正在阴影里缓慢酝酿。果不其然，黒巫后得到了能够使自己复活的秘术，与此同时，各地的女巫们亦按耐不住，纷纷蠢蠢欲动，妄图实现消灭人类统治世界的野心。考尔德和助手多兰（伊利亚·伍德 Elijah Wood 饰）想要面对繁杂而又强大的对手，必须得到善良女巫克洛伊（萝斯·莱斯利 Rose Leslie 饰）的帮助。一场恶战即将拉开序幕。©豆瓣', '范·迪塞尔', '布瑞克·埃斯纳尔', 5.9, 55311, 'tt1618442', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2305094811.jpg', 4.4, 23, 52.4, 15.2, 5.1, '-0.069795,0.250868,-0.505866,0.556231,-0.137655,-0.066668,0.874784,-0.080660,-0.306540,-0.361754,0.198161,0.523129,0.255890,0.105979,0.266899,-0.138211,-0.162368,-0.534644,0.158724,-0.034951,-0.151830,-0.331271,-0.699255,-0.134557,-0.199444,-0.779730,0.964429,0.269688,-0.115683,0.312459,0.311486,0.552473,-0.018806,0.383582,-0.114922,-0.121776,0.217729,-0.066304,-0.235121,0.341440,-0.009282,-0.112838,-0.273872,0.264204,-0.181892,0.187128,0.361165,-0.599439,0.098273,-0.247209,0.330129,-0.398102,-0.108340,0.381198,0.173889,0.080376,0.021194,0.232325,-0.015824,0.053519,0.180415,-0.095225,-1.188816,-0.235032,0.241258,0.166389,-0.440963,0.322127,0.228392,-0.072485,0.166041,-0.209312,-0.070075,0.149311,0.337383,0.488448,-0.201276,-0.102002,-0.466114,0.172839,0.604553,-0.120417,-0.461792,0.249306,-0.200956,-0.491791,-0.162456,-0.443748,-0.536187,-0.068220,0.371579,0.371637,-0.002198,0.467583,-0.513690,-0.013883,-0.506666,-0.244058,-0.212850,-0.360473,-0.173643,-0.439829,-0.207169,-0.080786,-0.191184,0.085983,0.118297,-0.348412,0.816497,-1.002742,0.534845,0.529263,0.365358,-0.274449,0.385521,0.141889,0.223658,-0.230647,-0.025578,0.559855,0.025914,0.405314,0.057282,0.101368,0.005853,0.096406,-0.375411,0.782415', '1793491', '26667010', '3769423', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10440138', '侏罗纪世界', '动作', '21世纪，曾经诞生过第一只恐龙的努布拉岛，在经历了一系列的惨剧之后迎来新的时代，如今这里经马斯拉尼之手建成了规模宏大的主题公园“侏罗纪世界”，数量繁多的远古生物每天都吸引数以万计的游客前来一饱眼福。为了吸引更多的游客，公司授意创意实验室采用不同动物的基因创造了集力量、速度和智慧于一体的暴虐霸王龙。作为负责人的克莱尔（布莱丝·达拉斯·霍华德 Bryce Dallas Howard 饰）原打算请专门负责迅猛龙的欧文·格雷迪（克里斯·普拉特 Chris Pratt 饰）评估暴虐霸王龙的防护设施，谁知这头可怕的怪物竟然骗过了精密仪器的监视和人类的眼睛，以迅雷不及掩耳的速度逃到了外面，随后对所见的一切生物展开了无差别的血腥屠杀。原本快乐祥和的公园乱作一团，克莱尔必须深入危险之地救出两个被困的外甥，而欧文则不可避免地带着他的迅猛龙猎人团队迎战史无前例的的可怕对手……', '克里斯·帕拉特', '科林·特莱沃若', 7.7, 406508, 'tt0369610', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2246217861.jpg', 0.3, 2.1, 27.6, 50.2, 19.8, '0.185966,-0.004744,-0.687335,0.738444,-0.028124,0.119642,0.755319,-0.012371,-0.349253,-0.231338,0.194725,0.559536,-0.086367,-0.020758,0.122538,-0.258711,-0.076757,-0.229338,-0.362633,0.033354,-0.281696,-0.257008,-0.669796,-0.448721,0.263484,-0.519338,0.520403,0.153477,-0.159390,0.418508,0.004691,0.340488,-0.283415,0.418269,-0.126785,-0.298112,0.099780,-0.006138,-0.287899,0.235020,-0.218201,-0.032420,-0.066078,0.277589,-0.128311,0.113445,0.726066,-0.576184,-0.154631,-0.448187,0.426241,-0.206090,0.189959,0.070588,0.576704,-0.219313,0.197321,0.013708,0.070068,0.191272,0.039971,-0.216882,-1.147515,-0.099835,0.159634,-0.121165,-0.445296,0.309257,0.021907,-0.022396,0.049802,-0.327085,0.081417,0.357561,0.252541,0.417911,0.050571,0.084611,-0.268879,-0.016181,0.674333,-0.200457,-0.446699,0.241519,-0.204884,-0.551612,-0.277645,-0.405123,-0.216973,-0.008465,0.424379,0.270021,-0.082405,0.441972,-0.995917,-0.030922,-0.295604,-0.404273,-0.146426,-0.221432,-0.274062,-0.852913,0.112684,-0.318057,0.133036,0.234576,0.058108,-0.055741,0.666723,-0.561828,0.121077,0.536250,0.278119,-0.513212,0.532443,-0.472133,0.034082,-0.207933,-0.281979,0.265300,0.177506,0.517230,0.128542,0.444365,0.182536,-0.238873,-0.368552,0.835603', '1308784', '1308585', '26667010', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10441064', '亨利四世：第一部分', '剧情', 'BBC2历史电视电影系列《空王冠》（The Hollow Crown）4部经典莎士比亚作品的新演绎，分别是：《理查二世》（Richard II）、《亨利四世：第一部》（Henry IV, Part 1）、《亨利四世：第二部》（Henry IV, Part 2）和《亨利五 世》（Henry V）。在2012年伦敦奥运会期间，为了向全世界展现英国文化，这四部电视电影将作为伦敦文化奥运的重点推荐剧目向全世界推行，在2012年6月播出。《亨利四世》是该系列的第二部。夺取理查二世权势的亨利四世，将由奥斯卡影帝杰瑞米·艾恩斯 Jeremy Irons饰演，将由《丑闻纪事》的导演理查德·艾尔掌镜，在《复仇者联盟》中雷神弟弟“洛基”汤姆·希德勒斯顿 Tom Hiddleston将饰演Prince Hal，西蒙·拉塞尔·比尔 Simon Russell Beale饰演约翰·福斯塔夫爵士，艾伦·阿姆斯特朗 Alun Armstrong饰演诺森伯兰伯爵。《亨利四世》展现了英国中世纪时期迷人的历史，并将演绎出近年来最野心勃勃的一部莎士比亚改编作品。《亨利四世》是莎士比亚历史剧中最成功、最受欢迎的一部，被看成莎士比亚历史剧的代表作。这部作品的主要内容是反映亨利四世和他的王子们与反叛的诸侯贵族进行殊死斗争的过程。莎士比亚突破传统历史剧多条线索交织发展的网状结构，采用了两条线索平行发展的结构——以亨利四世为代表的宫廷生活线索和以福斯塔夫为代表的市井生活线索。', '杰瑞米·艾恩斯', '理查德·艾尔', 8.7, 10465, 'tt2120771', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2096730708.jpg', 0.3, 0.6, 10.8, 42.4, 45.9, '0.102472,-0.080979,-0.409775,1.042409,0.574039,-0.041815,0.451072,0.034231,-0.323356,-0.345851,0.168325,1.002511,-0.452331,-0.209693,0.379472,-0.088605,-0.637173,-0.783466,-0.099674,-0.051684,0.189039,-0.414767,-0.310663,-0.199306,-0.156229,-0.559155,1.057208,0.005890,-0.367602,0.125617,0.454816,0.384193,0.041627,-0.167611,0.000515,0.031598,0.204412,-0.320375,-0.468045,0.547308,0.079663,-0.174479,-0.213315,0.052336,-0.121087,0.152750,0.657794,-0.357524,0.392261,-0.056501,0.860517,-0.207733,-0.175666,-0.039898,0.260471,0.124348,0.049626,0.685194,0.133319,0.052271,-0.181298,-0.544908,-1.024145,-0.280767,0.190348,0.330876,-0.462778,0.486891,-0.433911,-0.018558,0.125144,-0.292933,0.383061,0.271315,0.566712,0.375824,0.098661,0.156429,-0.388003,0.592662,0.173594,0.063724,-0.467924,0.443161,-0.176164,-0.500613,-0.274654,-0.337948,-0.389946,0.121794,0.357719,-0.282457,0.240392,0.513831,-0.740272,-0.201091,-0.100980,-0.569629,0.366668,-0.355981,0.091017,-0.963003,-0.301013,-0.249749,0.284769,-0.536277,0.120848,-0.472586,0.944541,-0.343287,0.052754,0.352384,0.210181,-0.304103,0.877196,0.089673,0.079051,-0.362343,-0.134187,0.419881,0.085621,-0.117059,-0.178358,0.261452,0.178634,-0.532336,-0.440496,0.630846', '22265121', '10543906', '30397916', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10441161', '贝拉的魔法', '剧情', '坐在轮椅上，之后的人生只能靠它代步的蒙特（摩根•弗里曼 Morgan Freeman 饰）对人生不再抱有什么希望。曾经的知名作家因为妻子的离世而灵感不再，整日与酒为伴的蒙特让侄子对他放不下心来，于是为他找了一个僻静小镇的小木屋，让他在这里散心养生。搬到这来的蒙特起初对什么都没有的小镇很不满，终日酗酒。而隔壁奥尼尔家的三个小女孩及她们的母亲（维吉妮娅•马德森 Virginia Madsen 饰）引来了蒙特的注意，随着和她们接触的加深，蒙特喜欢上了这一家，从中也渐渐拾得了生的乐趣；而奥尼奥家的三姐妹从蒙特身上得到了父爱和关怀，而她们的母亲也再次感受到爱情。一切都在朝着好的方向发展着，哪怕当下仍是黑暗，但黎明终究会来到，在救赎与被救赎中，蒙特及奥尼尔一家得到了治愈。©豆瓣', '摩根·弗里曼', '罗伯·莱纳', 7.6, 7872, 'tt1839654', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1692976030.jpg', 0.3, 2.5, 33.5, 45.2, 18.5, '0.571789,0.022482,-0.728189,0.630941,-0.053898,-0.612657,0.870003,0.319331,-0.619708,-0.093601,-0.009738,0.893648,0.024202,0.189853,0.271837,0.192199,-0.400615,-0.679564,-0.038670,-0.259560,-0.373379,-0.633499,-0.119613,-0.198921,-0.241016,-0.250569,0.331748,0.089797,-0.035832,0.507673,0.208412,0.344258,0.122690,0.441247,-0.374328,0.036913,0.061139,0.018691,-0.231799,0.352250,0.451110,-0.152216,-0.333306,0.348165,0.059616,0.329946,0.719303,-0.388106,-0.069079,-0.101057,0.154338,-0.012706,0.216164,0.076909,0.031153,-0.185483,0.125815,0.123560,-0.215263,-0.068061,0.115038,0.028837,-0.698748,0.045389,0.008965,0.177876,-0.592482,0.422324,-0.028736,-0.487033,0.164171,-0.209639,0.437309,0.592862,-0.086837,0.445026,-0.498217,-0.009981,-0.578748,-0.160409,0.691571,0.003977,0.041873,0.549377,-0.437129,-0.343888,-0.048197,-0.077988,-0.480432,-0.379081,0.252463,0.307559,-0.122683,0.228586,-0.724355,0.174917,-0.178860,-0.315228,0.139116,-0.528718,-0.062291,-0.534086,-0.126399,-0.450114,-0.215359,-0.023887,0.132334,-0.122094,0.730837,-0.922388,0.574619,0.457284,0.411131,-0.299211,0.909487,-0.081014,0.191000,-0.184579,-0.026687,0.377927,0.002750,0.325439,0.254175,0.306714,-0.011391,-0.165932,-0.497869,0.709061', '3055049', '1783461', '3230121', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10441571', '朋友2', '动作', '电影《朋友2》是由前作《朋友》的导 演郭暻泽继续执掌导筒，继续前作的故 事，而主角从刘五性和张东健变成了他们 的儿子们。', '刘五性', '郭景泽', 6.7, 13404, 'tt3264494', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2154816416.jpg', 1.7, 10.4, 51.3, 26.7, 9.9, '0.137220,-0.483637,-0.079530,0.625725,0.372991,-0.354006,0.392586,0.704098,-0.356671,-0.352104,-0.125877,1.189729,-0.323558,0.076667,0.009615,-0.073391,-0.636903,-0.837988,-0.290504,0.017141,-0.129703,-0.287671,0.576886,-0.264332,-0.082841,-0.053364,1.061443,-0.295248,-0.027912,0.306352,0.776703,0.406179,-0.193954,0.054132,0.054728,0.163700,-0.397933,0.275759,-0.646637,0.303059,0.222240,-0.160070,-0.824343,0.033209,0.211850,0.225097,0.592537,0.043460,-0.162911,-0.070568,-0.004705,-0.529369,-0.239336,-0.034393,0.055119,0.199327,0.368073,0.427846,0.171623,0.022400,-0.061544,-0.286423,-0.803828,-0.020073,-0.171852,0.254957,-0.483452,0.409323,0.057445,-0.306847,0.208048,-0.205738,0.443878,0.130515,0.015483,0.298176,-0.479360,-0.106739,-0.288810,0.493084,0.569948,0.343462,0.194966,0.861774,0.215323,-0.677714,-0.509150,-0.242031,-0.675510,0.187533,0.020033,-0.106470,0.132080,0.448240,-0.711326,-0.412939,0.034163,-0.126649,0.034940,-0.403848,0.410986,-0.438165,0.144733,-0.259178,0.068362,-0.050256,-0.078854,-0.354665,1.016680,-0.865715,0.025788,0.375071,0.282347,-0.896540,0.747683,0.077172,0.370546,-0.450602,-0.184691,-0.481062,0.232386,0.071162,0.715116,0.079236,-0.012357,-0.351240,-0.285471,0.032037', '4301278', '25880986', '1908036', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10442182', '忘年恋曲', '剧情', '一個發生在澳洲海邊小鎮的私密情事，兩個從小一起長大的鄰居好友，長大後卻同時愛上了對方血氣方剛、年輕氣盛的兒子。原本不應該發展下去的關係，面對宛如浪潮來襲的情慾激發，終究掀起不可避免的巨大波瀾。娜歐蜜瓦茲與羅蘋萊特大膽投入心靈與身體的演出，將腳色複雜的情緒與充滿力量的身體慾望完整表達，皆是兩者從影以來的代表作。兩位來自澳洲的青澀小生，恣意展露在陽光海水下的完美身體，更成了女性觀眾不可抗拒此片的秀色誘因。透過導演安芳妲的鏡頭捕捉，如中毒般的赤裸情事，交叉激盪出愛情、家庭、道德、與激情的複雜性。©豆瓣', '罗宾·怀特', '安妮·芳婷', 6.7, 8924, 'tt2103267', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2103419860.jpg', 1.6, 9.4, 49.7, 29.5, 9.9, '0.238341,0.037449,-0.912916,0.584242,0.073447,0.181779,0.933044,0.404772,-0.091152,0.398794,0.369868,0.674894,-0.420621,0.321806,0.039077,0.120754,0.010232,-0.905519,-0.636615,0.125969,-0.047872,-0.380162,-0.473689,0.181894,0.108325,-0.352980,0.542808,-0.087562,-0.330620,0.470362,0.283110,-0.177879,-0.191347,0.305525,-0.121282,-0.132994,-0.395719,0.313173,-0.288807,-0.054083,0.029084,-0.488718,-0.052661,-0.125380,-0.216594,0.357625,0.847765,-0.723559,0.075383,-0.007706,0.808860,-0.189729,0.203076,0.128307,-0.121601,0.137806,0.093282,0.081210,-0.251026,0.100318,0.459554,-0.260777,-0.791880,-0.004786,0.192841,0.407420,-0.302788,0.846112,0.292007,-0.066005,0.052128,-0.005238,-0.326698,0.043409,-0.039118,0.481640,-0.269599,0.436061,-0.193508,0.411943,0.437159,0.495111,-0.628862,0.374383,-0.499466,-0.312395,-0.219856,-0.381483,-0.244445,-0.466912,0.378758,0.256667,-0.214847,0.675371,-0.735871,-0.163048,-0.202193,-0.163221,-0.256345,-0.096010,-0.500726,-0.659571,-0.369962,-0.658237,-0.226012,0.521906,0.389823,-0.205845,0.940572,-0.673153,0.015924,0.541433,0.199495,-0.248027,0.638546,-0.027751,-0.082586,0.395722,-0.352571,0.515305,-0.290381,0.370454,0.457884,0.547589,-0.374502,0.218919,-0.640651,0.579767', '1307146', '24839498', '25928048', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10450409', '赛德克·巴莱(上)：太阳旗', '剧情', '本片根据雾社事件史实改编。1895年，《马关条约》割让台湾之后，日本遂即武力接收台湾，宝岛各地纷纷被攻破。而台湾山区因道路不通，原住民生活尚暂未受影响，雾社地区的赛德克人之中，马赫坡年轻一代的莫那鲁道（游大庆 饰）英勇过人，率族群与甘卓万人争斗不休。日人垂涎雾社地区的 丰富资源，试图染指但遭到赛德克人强烈抵抗，伤亡惨重，然终于借原住民族群之间的互相仇杀侵入了雾社。莫那鲁道只得忍辱投降，但心中的火苗从未熄灭。时间推至1930年，日本对于雾社原住民的“文明改造”历经多年，日语等所谓文明并未给予原住民平等的生活，日人的欺压和繁重劳作侵蚀着赛德克人的传统和尊严，多年的愤怒累积，终于在这一年全面喷发！©豆瓣', '林庆台', '魏德圣', 8.9, 96578, 'tt2007993', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1520558918.jpg', 0.2, 0.6, 7.4, 36.6, 55.2, '0.041252,0.039362,-0.654602,0.575757,0.430078,-0.024134,0.235246,-0.330119,-0.527512,-0.036883,-0.139574,0.444590,-0.088817,-0.219336,0.188604,-0.361578,-0.304745,-0.568307,-0.118072,-0.161903,-0.172661,-0.248561,-0.197381,-0.524065,-0.350457,-0.284981,0.749048,0.446147,-0.483894,0.552745,-0.259123,0.348193,-0.179463,0.380868,0.140365,-0.154041,0.056960,-0.114485,-0.406924,-0.092732,-0.231076,-0.345478,-0.278137,-0.022091,0.236182,0.511461,0.533941,-0.374236,-0.002572,-0.353598,-0.016039,-0.437325,-0.180893,0.067051,0.587717,0.092654,0.139666,0.404510,-0.016928,-0.069312,-0.075718,-0.184797,-0.400514,-0.189623,0.224956,-0.144282,-0.213579,0.787987,0.019232,0.001307,-0.290598,-0.133460,-0.069726,0.476042,0.434768,0.207011,-0.019184,-0.003650,-0.214461,0.206857,0.854886,-0.209351,-0.466464,-0.333031,-0.393145,-0.653691,0.026413,-0.760782,-0.266657,-0.209324,0.035543,-0.030870,-0.012862,0.698610,-0.757845,0.154069,-0.416476,-0.603350,0.332125,-0.030181,-0.153411,-0.549212,-0.448023,-0.540743,-0.052338,0.246725,0.262985,0.101916,0.914829,-0.545714,0.227231,0.370830,0.597161,-0.713249,0.525684,0.057436,-0.016780,0.011428,-0.018876,0.487813,-0.040923,0.370240,0.218722,-0.141482,-0.250713,-0.118492,0.173449,0.328883', '1849026', '27040921', '3993588', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10450713', '摩纳哥王妃', '剧情', '1962年，格蕾丝（妮可·基德曼 Nicole Kidman 饰）大婚已经有六年，她的一颦一笑已经成为20世纪王妃的经典影像，但此时，她正在力图使自己的过去与现在和解。她渴望重返大银幕，却因如今身兼三职——两个孩子的母亲、欧洲公国的王妃、雷尼尔三世（蒂姆·罗斯 Tim Roth 饰）的妻子——而踌躇不前。希区柯克（罗杰·阿什顿-格里菲斯 Roger Ashton-Griffiths 饰）建议她重返好莱坞，这个提议令格蕾丝陷入苦恼。当时丈夫雷尼尔的现代化改革措施遭到了法国总统戴高乐的抵制，戴高乐要对摩纳哥课以重税，并推动武力以保证此项措施得以实行。逐渐膨胀的国际性危机和法国迫近的入侵脚步，不仅是格蕾丝家庭、婚姻、国家的危机，也是她个人生活的危机。这是一个远离美国家乡的银幕明星不得不做出艰难决定的时刻，是回去做那个受全球瞩目和万千影迷爱戴的大明星，还是拥抱她的新身份，拥抱她对于丈夫、子女，以及这个世界第二小却是她的家、她的王国的责任……', '妮可·基德曼', '奥利维埃·达昂', 6.8, 69928, 'tt2095649', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2185958530.jpg', 0.9, 7.7, 51.3, 31.4, 8.7, '0.002504,0.253815,-0.681173,0.660150,-0.037356,-0.172271,0.582288,0.203958,-0.491327,-0.338252,0.386480,0.910662,-0.074562,0.239196,0.214148,0.130319,-0.253623,-0.835329,-0.018299,0.116903,-0.046792,-0.399841,-0.350638,-0.374102,-0.322206,-0.287209,0.776962,0.195802,-0.253842,0.117004,0.411191,0.225424,0.245211,0.509219,-0.121270,-0.148425,0.124402,-0.139823,-0.563326,0.135549,0.114668,-0.223112,-0.251741,0.403304,-0.017808,0.305275,0.329659,-0.269259,-0.081799,-0.288062,0.491547,-0.338391,-0.109649,0.175884,0.207902,-0.129773,0.191616,0.210613,-0.119331,-0.157665,0.003380,-0.213118,-0.749745,0.114939,0.188275,0.018485,-0.536867,0.383983,-0.322296,-0.041163,0.032846,-0.283448,0.013596,0.601164,0.225142,0.543996,-0.338242,0.322562,-0.246875,0.009160,0.659393,0.161903,-0.506948,0.120267,-0.514727,-0.478843,-0.063483,-0.465745,-0.548642,0.004966,0.124680,0.029338,-0.027333,0.531351,-0.483741,0.038681,-0.566033,-0.440339,0.264606,-0.518405,0.129761,-0.522925,-0.228278,-0.578188,-0.155846,0.125218,0.271857,-0.195589,0.833318,-0.683662,0.118497,0.572819,0.508104,-0.763423,0.642557,0.280540,0.115921,-0.377100,-0.180100,0.498349,-0.481180,0.075195,-0.305036,0.081051,0.193946,-0.058749,-0.247866,0.458534', '4301278', '1303034', '30162520', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10453719', '大奥 永远 右卫门佐·纲吉篇', '剧情', '神秘绝症赤面疱疮的出现，彻底改变德川幕府的命运。男女逆转的格局形成已达三十年之久，第五代将军纲吉（菅野美穗 饰）坐镇幕府，指引着日本朝向未知的方向航行。大奥深宫，侧室传兵卫（要润 饰）凭借将军之父桂昌院（西天敏行 饰）的庇护和为将军生下独生女松姫的功劳而荣耀一时。与之对立的御台所信平（宫藤官九郎 饰）深表不满，从京都找来兼具美貌与才华的公家落魄子弟右卫门佐（堺雅人 饰），企图夺取将军的宠幸。右卫门佐机敏果敢，他的言行得到将军赏识，从此一跃成为执掌后宫大权的总取缔。此后的岁月里，为子嗣和政治心力交瘁的纲吉，以及在派系斗争中周旋往复的右卫门佐，彼此的命运深深扭结在一起……本片根据少女漫画家吉永富美原作改编。©豆瓣', '堺雅人', '金子文纪', 7.1, 9696, 'tt2290573', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1759577589.jpg', 1.1, 6.6, 44.1, 34.9, 13.3, '-0.204918,0.184558,-0.337116,0.565712,0.021258,-0.139298,0.347808,0.466825,-0.394134,-0.304478,0.355177,0.658607,0.046741,0.014177,0.446676,-0.050055,0.002780,-0.797886,-0.345068,-0.090786,0.090989,-0.404873,-0.237015,-0.077860,-0.243831,-0.467916,0.990545,0.256813,0.006640,0.272868,0.262358,0.438864,-0.355881,-0.056875,-0.045600,-0.008224,-0.060448,0.015967,-0.488913,0.037170,-0.397840,-0.466351,-0.072103,-0.076927,-0.208010,0.145381,0.391588,-0.639692,0.072579,-0.350797,0.320439,0.098551,-0.204927,0.137260,0.407767,0.226072,-0.100062,0.623207,-0.206349,0.000062,-0.026949,0.070498,-0.626853,-0.297635,0.307156,0.180016,-0.444855,0.504409,0.111871,-0.441541,0.082405,-0.200320,-0.008519,0.374790,0.111034,0.185355,-0.319265,0.319563,-0.140236,0.152476,0.378549,0.062832,-0.308762,-0.195601,0.039169,-0.287215,0.176122,-0.626627,-0.482521,-0.225142,0.070993,-0.025299,0.525257,0.481627,-0.297704,0.177692,-0.249540,0.239602,0.333082,-0.327086,0.218366,-0.450929,-0.203877,-0.531121,-0.237924,0.035586,0.545559,-0.200687,0.662245,-0.622276,0.007281,0.261160,0.358657,-0.534979,0.646537,0.077099,0.130980,-0.196071,-0.258023,0.224979,0.050119,0.324684,-0.121889,0.159241,-0.263759,-0.154509,-0.548847,0.087254', '25880986', '6101834', '1440164', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10453723', '人类清除计划', '科幻', '近未来的美国，全国失业率仅为1%，犯罪率则创下史上最低纪录，暴力几乎消失无踪。美利坚合众国仿佛进入宛如天堂的美好黄金时代，而促成这完美表象的则是前所未闻的大扫荡计划。国家为了有效释放公民心底的压抑和不满情绪，特别规定每年有一天的晚上7点之后举行长达十二小时的全国性大扫荡，届时人们将走上街头，展开完全不用承担法律责任的殴斗与杀戮。在这个畸形的时代，安保系统推销员詹姆斯·桑丁（伊森·霍克 Ethan Hawke 配音）大发其财，与妻子儿女过着养尊处优的幸福生活。又是一年大扫荡之夜到来，桑丁一家端坐固若金汤的豪华府邸，在屏幕前观赏杀戮之夜的表演。谁知这一晚，詹姆斯的儿子查理出手拯救了一名被追杀的流浪汉，桑丁一家不可避免被卷入血腥的漩涡之中……©豆瓣', '伊桑·霍克', '詹姆斯·德莫纳克', 6, 70945, 'tt2184339', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239278955.jpg', 6.8, 19.9, 46.8, 20, 6.5, '-0.023493,0.109896,-0.714690,0.262684,0.022758,0.024996,0.709264,0.086634,-0.263183,-0.118760,0.317005,0.561537,-0.399730,0.156000,0.653126,-0.321406,-0.161337,-0.625047,-0.499595,-0.236317,-0.044392,-0.240007,-0.234957,-0.146714,-0.028673,-0.277016,0.620879,0.296527,-0.119656,0.406368,0.150985,0.171560,-0.109930,0.301849,-0.136452,-0.311632,0.124479,-0.018018,-0.321801,0.289284,-0.211173,-0.316015,0.045741,0.019823,-0.147048,0.144109,0.719516,-0.337161,-0.094366,-0.355442,0.616363,-0.465906,-0.358468,0.158765,0.272594,0.195051,0.141701,0.266386,-0.053836,0.004618,0.122507,-0.425291,-0.727672,0.014922,-0.030838,-0.093326,-0.360140,0.433781,-0.067402,-0.099526,-0.063198,-0.120124,0.237133,0.338110,0.320270,0.438845,-0.066638,0.216839,-0.598565,0.220200,0.727199,-0.153484,-0.491678,-0.012741,-0.139548,-0.331251,0.075398,-0.484457,-0.233028,-0.197427,0.080540,0.043091,0.036439,0.394506,-0.650726,0.183992,-0.306517,-0.524457,0.051514,-0.110218,-0.402076,-0.822957,-0.112333,-0.182319,-0.137886,0.182601,0.084719,-0.176698,0.488215,-0.696186,0.397194,0.488031,0.406922,-0.196874,0.494697,0.092887,0.344808,-0.069619,-0.119348,0.221563,-0.020126,0.487190,0.034264,0.131469,-0.191717,0.040910,-0.191601,0.665851', '2159244', '11541282', '24751811', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10453731', '杀死汝爱', '剧情', '1944年，哥伦比亚大学，年轻的学生艾伦·金斯堡（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）因为一个叫卢西安·卡尔（戴恩·德哈恩 Dane DeHaan 饰）的帅气同学而改变人生轨迹。通过卡尔他认识了威廉·S·巴罗斯（本·福斯特 Ben Foster 饰）和杰克·凯鲁亚克（杰克·休斯顿 Jack Huston 饰）。在未来将写出《嚎叫》、《裸体午餐》和《在路上》等传世之作的垮掉文学巨匠们，当时还只是少不更事的年轻人。他们因为卡尔而热心开展名为“新视界”的文化运动，结成了一个亲密的四人世界。而在这个世界之外，一个叫大卫·卡默偌（迈克尔·C·豪尔 Michael C. Hall 饰）的中年男子正用贪恋爱慕的目光打量进来。他是卡尔的老师、监护人、尾随者和...爱人？某晚当卡默偌的尸体在校园附近的哈德森河被发现后，年轻人发现他们被卷入一桩充满情感湍流的谋杀案中，自由的世界被彻底碾碎，他们怀着沉重的心情各奔前程......本片根据真人真事改编，讲述未来文学巨匠们在成长年代经历的“小革命”，用黑色音符弹奏出“垮掉一代”诞生的初乐章。英国童星丹尼尔·雷德克利弗在片中饰演著名同志诗人金斯堡，成功洗去了哈利波特留下的痕迹。《杀死汝爱》入围第29届圣丹斯国际电影节美国主竞赛单元。', '丹尼尔·雷德克里夫', '约翰·克洛基达斯', 7.7, 40704, 'tt1311071', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2107622241.jpg', 0.4, 2.3, 29.2, 46.5, 21.6, '0.238528,-0.079195,-0.639147,0.504139,0.064543,-0.374169,0.645387,0.057915,-0.357031,-0.289739,-0.019498,0.758273,-0.281670,0.193525,0.595072,-0.116485,-0.261493,-0.698559,0.068549,-0.060878,-0.255256,-0.445137,-0.216095,-0.208639,-0.189613,-0.593028,0.590080,0.034916,-0.142855,0.582634,0.354755,0.396278,-0.018819,0.138770,-0.099039,0.165843,0.383678,-0.021088,-0.359216,0.217865,-0.074397,0.087968,-0.182577,-0.019018,-0.249036,0.173289,0.662592,-0.209795,0.123281,-0.123441,0.380517,-0.178436,-0.067834,0.017732,0.224478,0.000704,-0.004215,0.290319,0.019290,0.008465,0.012853,-0.194997,-0.406862,-0.103159,0.050864,0.365080,-0.447793,0.365258,-0.030603,-0.090325,0.068773,-0.281560,0.121272,0.084386,0.379328,0.441391,0.087919,0.125294,-0.351280,0.155644,0.297506,0.060294,-0.583435,0.258548,-0.229925,-0.177344,-0.061921,-0.071872,-0.411866,0.074171,0.295734,-0.105637,-0.034150,0.278851,-0.571697,-0.155901,-0.198078,-0.329076,0.021747,-0.314599,-0.249484,-0.774624,-0.140778,-0.239977,-0.180327,-0.206570,-0.003359,-0.313491,0.787817,-0.594035,0.254890,0.3