INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10456937', '深水', '剧情', '一对感情有问题的夫妻，双方达成协议：妻子Melinda在外面任找多少情人都可以，只要她不抛弃家人。而随后，丈夫Vic开始抑制不住自己的嫉妒，想要赢回妻子，为此最终卷入了犯罪。', '本·阿弗莱克', '阿德里安·莱恩', 5.5, 10015, 'tt2180339', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2869361485.jpg', 8.1, 31.8, 43.4, 11.8, 5, '0.068456,0.079012,-0.712249,0.348457,-0.253143,-0.450340,0.766440,0.078788,-0.390427,0.003590,0.079091,0.424714,0.108098,0.216316,-0.213099,-0.006721,-0.200371,-0.778120,0.209909,-0.238658,-0.166551,-0.638237,0.034251,-0.455383,-0.171319,-0.114995,0.979099,-0.020739,0.122338,0.013350,0.421229,0.231187,-0.040863,0.417834,-0.227885,0.111007,0.095182,0.170972,-0.632432,0.142186,0.190854,0.188695,-0.049356,0.509997,-0.372356,0.397009,0.537900,-0.199888,-0.230735,-0.212388,-0.016210,-0.185990,0.118108,0.335723,0.007772,-0.298481,0.516265,0.214625,-0.214189,-0.106221,0.413936,0.590264,-0.518869,-0.136690,0.445798,0.078582,-0.706325,0.530412,-0.035807,0.069524,0.130540,0.105293,-0.012376,0.815190,0.138872,0.287968,-0.840792,-0.009914,-0.717958,0.338520,1.247880,-0.170449,0.267915,0.387018,-0.407073,-0.054918,-0.059277,-0.111119,-0.895529,-0.207571,0.322727,0.433619,-0.312423,0.684690,-0.381618,-0.122598,0.099911,0.366734,0.164126,-1.005211,0.580591,0.096325,-0.593226,-0.259250,-0.143753,-0.234505,0.078522,-0.319777,0.533203,-0.856301,0.265575,0.533029,0.519703,-0.933159,0.509929,0.679789,0.135068,-0.597033,-0.095342,0.207476,-0.309131,-0.053129,0.220998,-0.246265,0.204517,0.224485,0.039810,0.427272', '4145476', '1309033', '1949320', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10456963', '天生爱情狂', '喜剧', '富家子张泰林（张智霖 饰）在偶然之下结识了俏护士邝美宝（刘心悠 饰），两人堕入爱河，但其后泰林却逐渐发现美宝的另一面：多疑、善妒、控制欲强兼有轻微的暴力倾向。泰林难以忍受提出分手，但依然受到美宝的跟踪。美宝在医院偶遇泰林前女友慧欣（苟芸慧 饰），得知泰林不为人知的秘密，而此时泰林与母亲介绍相亲的女孩晴晴（叶熙祺 饰）的关系越加亲密。一次巧遇，美宝与泰林公开对质他的秘密，原来这场疯狂爱情才刚刚开始……©豆瓣', '张智霖', '叶念琛', 5.8, 22705, 'tt2372584', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1771314358.jpg', 6.1, 23.3, 50.5, 15.7, 4.3, '0.466425,0.028027,-0.605356,0.305476,0.148660,0.086911,0.695726,0.331146,-0.682950,-0.395456,0.294454,0.413647,-0.261506,0.158355,0.103391,0.026874,-0.053212,-0.540564,0.312005,-0.027454,-0.133318,-0.669416,-0.179133,-0.002627,0.042859,-0.364301,0.399054,0.055443,-0.286684,0.732094,0.479219,0.218229,-0.417080,0.321078,0.050813,-0.020386,0.432367,0.297144,-0.594060,0.080040,0.199438,-0.161834,-0.250752,0.203762,-0.171665,0.518793,0.442377,-0.226793,-0.310914,-0.041194,0.467668,-0.126939,-0.247109,0.118480,0.149642,0.048671,0.383547,0.479116,-0.300903,0.022838,0.121805,0.447036,-0.172721,0.502119,0.346613,0.122282,0.066065,0.267484,-0.062347,0.007684,0.082106,-0.357252,-0.019440,0.334078,0.312109,0.122222,-0.167987,0.044905,-0.034997,-0.111720,0.601213,0.127091,-0.084946,0.412743,-0.094994,-0.172488,0.145924,0.022904,-0.492627,0.156106,0.131474,0.129806,-0.367493,0.372468,-0.496166,-0.101915,-0.344213,0.458118,-0.036439,-0.174251,-0.118279,-0.657194,-0.665395,-0.425752,-0.226734,0.041131,-0.103171,-0.375306,0.189984,-0.911470,0.171830,0.441575,0.300560,-0.538792,0.315426,0.274521,-0.105330,-0.455787,-0.111134,0.405971,-0.040024,-0.327362,-0.170201,0.057973,-0.227204,0.028193,-0.364960,-0.083881', '1291856', '1293265', '1307186', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10460270', 'JOJO的奇妙冒险：不灭钻石 第一章', '动作', '碧海蓝天、安逸舒适的港口城市杜王町，在过去三年里相继发生离奇诡异的死亡事件。一时间天堂变成地狱，人人自危。废柴男生广濑康一（神木隆之介 饰）上学路上遭到不良少年刁难，不过却由此结识了同班同学东方仗助（山崎贤人 饰）。留着飞机头的东方仗助拥有神秘的“替身”，这让他和他人截然不同。他通过“替身”制止了一场便利店抢劫案，结果反被连续杀人事件的制造者安杰洛——片桐安十郎（山田孝之 饰）盯上。不久后，名叫空条承太郎（伊势谷友介 饰）的男子来到杜王町，东方由此知道了自己的身世。与此同时，名叫虹村形兆（冈田将生 饰）且拥有替身能力的男人露出了他的爪牙，一场大战在所难免……本片根据荒木飞吕彦的同名漫画改编。©豆瓣', '山崎贤人', '三池崇史', 6, 8036, 'tt6105880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2461817818.jpg', 6.4, 20.7, 48.3, 17.8, 6.7, '0.191932,0.056815,-0.524630,0.231484,-0.036030,-0.112816,0.715710,0.071326,-0.410378,-0.340105,0.437732,0.679511,-0.401270,0.085455,0.551782,0.028800,-0.139928,-0.425938,0.031155,-0.212229,-0.172250,-0.232664,-0.334014,-0.115069,-0.057963,-0.315247,0.585348,0.151041,-0.099493,0.377042,0.332986,0.511246,-0.322486,0.252660,0.069687,0.288154,-0.028439,0.128022,-0.064005,0.330978,-0.403364,-0.327390,-0.130025,0.164458,-0.150049,0.359872,0.738928,-0.354505,-0.170043,-0.340243,0.417393,-0.254995,-0.388435,0.219336,0.435707,0.082504,0.160798,0.141886,-0.253563,-0.141707,0.182344,0.038026,-0.374343,0.040392,0.159945,0.116698,-0.188534,0.333594,-0.087126,-0.324081,0.235602,-0.177596,0.106743,0.074274,0.551954,0.130554,-0.086837,0.080150,-0.204315,0.174531,0.508918,0.034912,-0.148203,0.318493,-0.082307,-0.447965,-0.267216,-0.419499,-0.118695,0.122841,0.302706,-0.167109,-0.092825,0.185559,-0.455015,-0.316751,-0.163123,0.066856,-0.067602,-0.037157,-0.187282,-0.578637,-0.011100,-0.366637,-0.238725,0.028727,0.309068,-0.272716,0.441350,-0.831014,0.036317,0.480797,0.201950,-0.026053,0.115078,-0.101348,-0.044845,-0.164714,0.029318,0.104125,0.336662,0.529645,0.113626,0.397326,-0.095451,-0.105333,-0.359052,0.287929', '1309194', '1436998', '10174444', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10461368', '犀利人妻', '爱情', '谢安真（隋棠 饰），离婚四年，单身四年，身兼职业OL与家庭主妇两种身分的她，将生活中的一切都打理得井然有序。女儿眼中的好妈妈、同事眼中的好上司、朋友眼中的好姐妹，但，她又会是谁的“好情人”呢？ 虽然对爱情仍然有些渴望，安真总用自己的生活很充实、很满足、很幸福来当藉口，因此，她与天蔚（宥胜 饰）还是一直维持着“好朋友”的关系。但，连安真自己也没发现，她只是没有勇气，没有勇气再次投入一段“甜蜜却随时可能破碎的爱情” 。在安真苦恼于是否该接受天蔚的感情时，前夫瑞凡（温升豪 饰）却在此时出现，再次对她展开追求。 在“亲情”与“爱情”、“安心”与“开心”、“习惯”与“改变”之间，安真是否能够把握当下的幸福，勇敢走向能让她发自内心微笑的那个人呢？ 幸福，真有么困难吗？©豆瓣', '隋棠', '王珮华', 5.5, 6819, 'tt2455730', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1625336618.jpg', 9.1, 28.3, 45.4, 13.1, 4, '0.166392,-0.030628,-0.707905,0.531783,-0.232380,-0.255018,0.851119,-0.075539,-0.465296,-0.138519,-0.057629,0.616880,-0.045677,0.390761,0.028410,0.187599,-0.202592,-0.777954,0.134708,-0.156442,-0.096130,-0.383423,-0.437004,-0.148661,-0.364427,-0.268773,0.728243,0.209329,0.207741,0.385963,0.197052,0.005700,0.069227,0.754942,-0.132885,-0.250439,-0.281213,0.382057,-0.498314,-0.121012,0.387574,-0.016630,-0.252599,0.432034,0.093408,0.053311,0.550510,-0.175086,-0.505129,0.314112,0.160878,-0.221206,0.068282,0.278276,-0.225391,-0.104907,0.238488,0.314049,-0.098214,-0.150893,-0.059848,0.039611,-0.919283,-0.035834,0.129554,0.080404,-0.603573,0.611336,-0.083421,-0.139276,0.289747,-0.324345,0.117878,0.448614,0.373610,0.639113,-0.562762,0.132480,-0.437063,0.269057,0.979987,0.229223,-0.319216,0.502236,-0.510535,-0.426638,-0.160318,-0.056875,-0.805802,0.014840,-0.159981,0.329863,-0.058638,0.276529,-0.444000,0.313731,0.069305,0.328768,0.057471,-0.934839,0.298930,-0.204013,-0.236621,-0.759420,-0.645462,0.043327,0.013291,-0.604761,0.789306,-1.208004,0.234725,0.295057,0.528337,-0.643091,0.777267,0.696240,-0.087171,-0.367152,-0.167230,0.311222,-0.401202,-0.200445,0.263808,0.212351,0.102951,0.194705,-0.322583,0.619301', '35030151', '1296370', '1308755', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10461726', '得买新鞋了', '剧情', '小有名气的日本摄影师八神千（向井理 饰）被妹妹铃爱（桐谷美铃 饰）硬拉到浪漫之都法国巴黎，谁知刚刚抵达没多久，千便被妹妹独自扔在塞纳河畔。正在焦虑之际，千的护照又意外被一名日裔女子踩破，而对方也因此折断了高跟鞋的后跟。对方名叫敕使河原葵（中山美穗 饰），是当地一份日文免费报纸的编辑。在葵的帮助下，千找到了大使馆和所住的酒店。与此同时，铃爱也见到久违的恋人——为了梦想独自在巴黎打拼的画家阿汉（绫野刚 饰）。短短三天的异国旅行，千与葵相识相知，彼此产生好感；铃爱在久别的欢愉过后，亦将面对远距离爱情的诸多考验。仿佛恒久不变的埃菲尔铁塔，默默注视着这两对男女的相见与离别……©豆瓣', '中山美穗', '北川悦吏子', 7.1, 6495, 'tt2330723', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1984836754.jpg', 1.1, 7.1, 43, 35.3, 13.4, '0.251845,0.126745,-0.619076,0.459880,0.279584,-0.224047,0.560106,0.069108,-0.275969,-0.263380,0.173101,0.812076,-0.482369,0.306603,0.476701,-0.132077,-0.052304,-0.837319,-0.191832,-0.227788,-0.216954,-0.237773,-0.236728,0.196795,-0.231124,-0.167829,0.436562,0.184451,0.074265,0.734862,0.272788,0.429987,-0.490947,0.391472,-0.272464,0.021141,0.096802,0.194430,-0.319841,0.100920,-0.104330,-0.441791,0.090854,0.080592,-0.070903,0.200002,0.913319,-0.223140,-0.195108,0.012722,0.268602,0.032475,-0.064907,0.159695,0.132502,0.052782,0.260509,0.151742,-0.269592,0.039098,0.217731,0.059615,-0.474216,0.039343,-0.005001,-0.066113,-0.628796,0.648882,-0.087723,-0.113049,0.072871,-0.185478,0.261074,0.503030,0.195301,0.325029,-0.228426,0.052935,-0.293877,0.273084,0.589407,0.040240,-0.036237,0.470834,-0.099660,-0.492029,0.015238,0.037075,-0.242945,-0.153734,0.342150,0.111563,0.020517,-0.241761,-0.687588,-0.009599,-0.180659,-0.085491,0.085337,-0.455342,-0.161683,-0.692075,0.073041,-0.481040,-0.365741,0.233358,0.289178,-0.047055,0.613478,-0.708516,0.418305,0.424400,0.270875,-0.186796,0.698274,0.042911,0.022780,-0.080488,-0.256341,0.431592,0.070106,0.345429,0.121146,0.325358,-0.285081,0.010098,-0.582875,0.264993', '3811356', '3155839', '1309194', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10462705', '白金数据', '科幻', '未来世界，秘密系统“白金数据”得到开发，日本全国人民的DNA数据被存储其中，进而借此构建了一个检举率100%、冤案率0%的理想社会。可即便如此尖端的系统，也被代号为“NF13”的连环杀人案所难住，凶手犯案累累，且至今下落不明，甚至连“白金数据”的开发者蓼科兄妹也惨遭杀害。此后不久，特殊解析研究所的天才科学家神乐龙平（二宫和也 饰）对蓼科早树（水原希子 饰）尸体上提取的嫌疑人基因进行解析，竟发现真凶的矛头指向自己。凭借同事白鸟理沙（杏 饰）的帮助，神乐连忙逃脱，而以刑警浅间玲司（丰川悦司 饰）为代表的搜查一课早已在这座城市内部下天罗地网。在此过程中，神乐自身的秘密逐渐付出水面，真相更是出乎所有人意料……本片根据著名推理小说作家东野圭吾的同名原作改编。©豆瓣', '二宫和也', '大友启史', 6.9, 18890, 'tt2282917', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1853506080.jpg', 1.1, 9.5, 47.1, 30, 12.2, '0.012788,0.219018,-0.433209,0.552129,0.128031,0.079676,0.099566,-0.159186,-0.480402,-0.356089,0.245075,0.411279,-0.101530,-0.159738,-0.018369,-0.132462,-0.338100,-0.631180,-0.066328,-0.326321,-0.349650,-0.613725,-0.368253,-0.265890,-0.108075,-0.346209,0.947519,0.215827,-0.263561,0.110559,-0.001180,0.437209,-0.396375,0.114136,0.119926,0.011053,0.291570,-0.079486,-0.175083,0.277673,-0.379177,-0.373747,0.129401,0.148762,-0.258405,0.382247,0.823143,-0.440472,-0.180908,-0.215237,0.477586,-0.157276,0.001609,-0.081940,0.519704,0.135929,0.172366,0.389229,-0.277386,0.012795,0.115154,-0.096339,-1.031141,-0.524489,0.540699,0.152153,-0.152015,0.128000,-0.333762,-0.006842,0.099547,-0.111278,0.055557,0.178532,0.604411,0.227362,-0.362921,0.037592,-0.172085,0.234293,0.084986,-0.239466,-0.311196,0.151054,-0.223244,-0.597116,-0.451981,-0.101464,-0.047128,0.147084,0.143860,0.301843,0.108247,0.294794,-0.502157,-0.064700,-0.289386,-0.111964,0.146512,-0.179665,0.040549,-0.733648,-0.205756,0.017076,-0.150867,-0.169934,0.266278,-0.392311,0.707333,-0.509293,-0.065827,0.311728,0.036379,-0.372214,0.322237,-0.093450,0.088799,-0.411154,-0.297848,0.114091,0.387643,0.519393,-0.178108,0.199595,0.123176,-0.438148,-0.487116,0.089821', '26759820', '25880986', '2369613', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10462800', '黑金杀机', '剧情', '由迈克尔·法斯宾德饰演的律师顾问被哈维尔·巴登饰演的毒贩拉下水，卷入了一宗高达2000万美元的毒品交易。两位美人（克鲁兹与迪亚茨）轮番登场与顾问周旋，而另一长发神秘男子（布拉德·皮特）的加入更令这场智力游戏扑朔迷离，为保全身而退，顾问决定用尽一切办法。', '迈克尔·法斯宾德', '雷德利·斯科特', 5.2, 9137, 'tt2193215', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2131742084.jpg', 12.8, 35.6, 35.1, 11.5, 5, '-0.096570,-0.020396,-0.295646,0.503625,-0.110237,-0.353039,0.587987,0.590807,-0.353016,-0.383008,0.363092,0.913190,-0.315590,-0.350850,0.932548,-0.064938,-0.339452,-0.513981,-0.545199,0.049089,0.011218,-0.687759,-0.090840,-0.315785,-0.143732,-0.272381,0.910718,-0.224255,-0.440518,0.526340,0.710361,0.620104,-0.291473,-0.080880,0.408810,-0.256164,0.422214,-0.132950,-0.732464,0.331454,-0.095747,-0.035330,-0.078658,-0.176637,-0.060110,0.345093,0.503996,-0.175576,0.289431,-0.015677,0.299312,-0.487544,0.083011,-0.059263,0.122744,0.015957,0.114847,0.320644,-0.102896,-0.191981,0.330009,-0.348488,-1.030031,0.121823,0.111358,0.051875,-0.393949,0.190748,-0.204244,0.222806,0.184649,0.095017,-0.235352,0.116665,0.279344,-0.128286,0.135732,0.147842,-0.434706,0.342827,0.460672,0.152170,-0.210827,0.092450,0.222712,-0.324412,-0.156499,-0.285414,-0.138183,0.009585,0.338706,-0.129853,0.335021,0.556620,-0.652165,-0.123161,-0.670730,-0.028288,-0.042969,-0.259287,0.132143,-0.810743,-0.504210,0.160846,0.175327,-0.006042,0.373657,-0.155696,0.605616,-0.467909,-0.246736,0.535318,0.061292,-0.208049,0.475588,0.266984,0.522530,-0.582354,-0.305205,-0.119154,0.296122,-0.113605,0.172067,0.131668,-0.041407,-0.222926,-0.234058,-0.319856', '27073234', '7051375', '5910040', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10462924', '推理要在晚餐后SP', '悬疑', '世界知名画家松下庆山在自己的画室身亡，现场尸体被烧焦难辨，价值数十亿的画作也随大火付诸一炬。是自杀？他杀？风祭（椎名桔平饰）警部和其助手丽子（北川景子饰）虽仔细勘查，多方取证，也未能挖掘出真相。回家后，丽子习惯性地向管家影山（樱井翔饰）讲述案件的经过，出人意料的是，丽子心中的推理天才这次竟然表示无能为力。丽子失望地讲述起自己在旅游时遇到的另一段奇怪经历，而影山的反应和其他人一样，也认为是丽子的幻觉。难道连影山都无法看破这重重迷雾，始终看好他的大小姐丽子这次要失望了吗？©豆瓣', '北川景子', '土方政人', 7, 7264, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1483719733.jpg', 0.8, 5.4, 47.9, 34, 11.9, '0.148883,-0.039397,-0.541168,0.178832,0.062360,-0.217147,0.558777,-0.199750,-0.611604,-0.511224,0.112515,0.585654,-0.190319,0.250704,0.114227,0.032569,-0.283146,-0.554971,-0.253437,-0.246052,-0.272611,-0.589590,-0.235675,-0.315018,0.119379,-0.139990,0.457937,0.316335,-0.156306,0.432363,0.246182,0.220980,-0.146298,0.264367,0.041777,0.307563,-0.044566,0.233620,-0.194187,0.013749,0.074344,-0.267783,-0.263942,0.357426,-0.074471,0.359488,0.470061,-0.015192,-0.484472,0.170180,0.417733,-0.395589,0.110459,0.222669,0.256887,0.017122,0.021449,0.264996,0.018789,-0.048041,0.150314,0.232637,-0.669222,-0.008508,0.243624,0.277847,-0.402662,0.261233,-0.029684,-0.061525,-0.000973,-0.200469,0.014166,0.202972,0.439969,0.188743,-0.246081,0.000178,-0.094877,0.136193,0.501459,-0.018409,-0.123172,0.193205,-0.249347,-0.352202,-0.127546,-0.002879,-0.212203,0.369604,0.102461,0.451147,-0.276544,0.121045,-0.121118,-0.125203,-0.265100,-0.177390,-0.200632,-0.184183,-0.093081,-0.496504,-0.119933,-0.217888,-0.436372,-0.194952,0.049286,-0.255648,0.407350,-0.537072,0.048746,0.410746,-0.032098,-0.244332,0.181855,0.114775,-0.459973,-0.155787,-0.135255,0.085306,0.072939,0.413083,0.055099,0.256951,0.301181,-0.456327,-0.593779,-0.012513', '26908280', '1299195', '25928048', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10462973', '雷霆万钧', '剧情', '本片是由篮球明星凯文·杜兰特亲自主演，影片讲述篮球巨星凯文·杜兰特和一个16岁的小球迷布莱恩(Taylor Gray 饰)交换了天赋。当布莱恩从一个肢体不协调的年轻球迷变成他崇拜的篮球英雄凯文·杜兰特时，他的生活也随之改变。布莱恩一跃成为高中校队的明星，而凯文·杜兰特却失去了打篮球的技能，甚至连一记篮球也投不进去。这时季后赛即将来临，他们两人会怎样面对这一切呢？', '布兰登·T·杰克逊', '约翰·怀特塞尔', 6.3, 5738, 'tt2041488', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2670933754.jpg', 3.6, 17.2, 49.9, 18.9, 10.3, '0.292848,-0.285921,-0.406025,0.509233,-0.457975,-0.538563,0.498009,0.235748,0.026267,-0.090586,0.344686,1.125980,-0.559746,-0.024027,0.141556,-0.264682,0.028261,-1.015934,-0.002382,0.161342,-0.318606,-0.227096,-0.413273,-0.292596,0.029310,-0.031453,0.829443,-0.305092,-0.115221,0.517206,0.294636,-0.004657,0.660560,0.328179,0.184507,0.282245,0.269949,0.048883,-0.160002,0.456158,0.133837,-0.212805,-0.366326,0.068291,-0.089898,0.150322,0.458181,-0.028654,0.256847,-0.165607,0.468790,-0.243688,-0.208633,0.176291,0.103386,-0.151892,-0.079417,-0.210075,0.337270,0.192367,-0.300265,-0.183332,-0.602491,0.182114,-0.170098,0.269548,-0.561131,0.470893,-0.280749,0.098753,0.123472,-0.178696,-0.119324,0.030051,-0.049010,0.124872,-0.412989,0.074167,-0.201824,0.426201,0.565455,0.186924,-0.722874,0.147672,-0.456581,-0.481481,-0.155635,-0.045071,-0.638341,0.211844,0.429626,-0.038695,0.329546,0.200531,-0.331118,0.041957,-0.034546,-0.120377,-0.209788,-0.671346,-0.160618,-0.599297,-0.098454,-0.276550,-0.349080,-0.415799,-0.055105,-0.053568,0.957280,-0.902874,-0.233539,0.547774,-0.010887,-0.004824,0.829784,-0.090266,0.144440,-0.316151,-0.074002,0.106924,-0.139350,0.152043,-0.105553,0.626982,0.223252,-0.111722,-0.229386,0.696031', '30162520', '1870681', '1292720', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10463953', '模仿游戏', '剧情', '二战期间，盟军苦于德国的秘密系统“英格玛”无法破译，政府召集了一批民间数学家、逻辑学家进行秘密破解工作，图灵（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）就是其中之一。计划刚开始图灵遭到了以休（马修·古迪 Matthew Goode）为首的组员和 领导的排斥，幸好军情处部长孟席斯（马克·斯特朗 Mark Strong 饰）帮助他立项研究破译密码的机器，而图灵则变成了负责人，招收了新的成员琼（凯拉·奈特莉 Keira Knightley）开始了艰难的工作。琼很快就迷上了图灵，由于她的帮助所有组员空前的团结，并于两年后成功破解德军的密码。图灵一度与琼订婚，但实际上他隐瞒了一个秘密，因为这个秘密他也遭受了非人的待遇……本片改编自安德鲁·霍奇斯编著的《艾伦·图灵传》，上映后获得了第87届奥斯卡最佳改编剧本奖。©豆瓣', '本尼迪克特·康伯巴奇', '莫滕·泰杜姆', 8.8, 600515, 'tt2084970', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2255040492.jpg', 0.1, 0.5, 9.3, 41.7, 48.4, '0.230686,-0.039458,-0.722714,0.572964,0.082725,-0.237625,0.169182,-0.184398,-0.414820,-0.243204,-0.055096,0.660283,-0.158189,0.059881,0.329671,-0.119048,-0.512812,-0.693173,0.083093,-0.415580,-0.278237,-0.557759,-0.153651,-0.321495,-0.019050,-0.452187,0.808299,-0.031042,-0.312332,0.098018,0.136872,0.472982,-0.106822,0.286247,0.288374,-0.015325,0.746754,-0.386707,-0.136519,0.286617,-0.152796,-0.278971,0.025121,0.275141,0.145055,0.606961,0.348140,-0.449642,-0.152005,-0.135727,0.224465,-0.321139,-0.269801,-0.062637,0.431543,0.244280,0.097921,0.367077,-0.172434,0.144316,-0.178991,-0.334536,-0.973245,-0.399610,0.079231,0.180587,-0.374728,0.272902,-0.414577,0.157537,-0.215344,-0.285819,0.101155,0.686251,0.170383,0.000291,-0.046379,-0.042325,-0.219119,0.315713,0.159844,-0.311620,-0.361718,0.225300,-0.159605,-0.575047,0.050435,-0.099635,-0.107216,0.098479,0.385672,0.156933,0.136821,0.071818,-0.442884,-0.082709,-0.494636,-0.257127,-0.249381,-0.145504,0.098863,-1.034447,-0.171938,-0.073563,-0.163908,-0.157818,0.036927,-0.241460,0.745630,-0.650284,0.206321,0.469310,0.163738,-0.511868,0.181201,0.220113,0.314392,-0.431015,0.035331,0.066384,-0.045186,0.399886,0.174175,0.299496,0.334914,-0.510205,-0.129016,0.263669', '2369613', '2028645', '27073234', '1305096');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10463991', '私奔B计划', '喜剧', '伊莎贝尔（黛安·克鲁格 Diane Kruger 饰）和男友之间维系了一段长达十年的恋情，如今，依旧浓情蜜意的两人决定结婚。可是，在伊莎贝尔的家族里，所有女性都遭受着一个“诅咒”的困扰，那就是她们的第一次婚姻注定会以失败收场，而第二段婚姻才是真正的幸福所在。面对不容乐观的局面，伊莎贝尔想出了一个妙招，她决定远赴异国，找一个老实的倒霉蛋，闪电结婚后闪电离婚，如此方能和男友幸福的踏入婚姻的殿堂。计划不如变化，一个重大意外的发生让伊莎贝尔的计划几乎泡汤，幸运的是，一个名叫约翰（丹尼·伯恩 Dany Boon 饰）的男人及时的出现在了她的面前，成为了她的“救命稻草”。©豆瓣', '黛安·克鲁格', '帕斯卡尔·舒梅', 7.3, 21212, 'tt1986843', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2153192509.jpg', 0.8, 3.8, 37.4, 43.3, 14.8, '0.337840,0.019953,-0.651459,0.547267,-0.136938,-0.397993,0.728523,0.025920,-0.224085,-0.252875,0.279411,0.878750,-0.341573,0.243704,0.352601,-0.063922,0.046554,-0.846771,-0.045530,-0.158895,-0.247489,-0.468646,-0.354753,-0.058255,-0.073258,-0.133873,0.753432,0.220986,-0.035677,0.436405,0.571919,0.138349,-0.042426,0.394484,-0.095409,-0.038763,0.212703,0.114046,-0.421082,0.241536,0.099575,-0.078298,0.147509,0.420791,-0.275718,0.360001,0.535589,-0.377481,-0.335334,0.050017,0.617784,-0.437211,-0.178873,0.253492,0.364681,-0.173682,0.037857,0.281270,-0.386109,-0.321843,0.191659,-0.217643,-1.032931,0.168391,0.037454,0.170382,-0.524269,0.528938,0.107048,-0.206264,0.251199,-0.349856,0.267611,0.702559,0.583888,0.426113,-0.579489,0.161641,-0.488120,-0.046681,0.890953,0.008416,-0.478497,0.340746,-0.227935,-0.331428,-0.163478,-0.261136,-0.570586,0.076787,0.219960,-0.038410,-0.173877,0.198647,-0.410024,-0.026494,-0.556007,0.044934,0.078892,-0.576985,-0.086727,-0.394216,-0.134847,-0.333731,-0.645396,0.259306,-0.076549,-0.384670,0.581261,-0.625573,0.230017,0.513775,0.279397,-0.582711,0.781594,0.430031,0.384222,-0.282660,0.173129,0.390902,-0.322944,0.031640,-0.008366,0.244716,0.132388,0.119641,-0.439643,0.541667', '26678784', '30163500', '4301278', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10466341', '鬼打墙', '剧情', '三个互相不认识的年轻人, 不约而同在林间迷路, 相聚在一个林间小屋中, 三个人怎麽走都走不出去, 困了许多天....渐渐的水与食物都已耗尽, 他们想办法一直要逃出这片树林, 终於发现了这间屋子藏着许多诡异的事件, 究竟这片树林与小屋藏着什麽神秘的力量呢？ 他们是否能得救?', '萨拉·帕克斯顿', '杰克·海勒', 7.4, 19364, 'tt1631707', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2612489884.jpg', 0.5, 3.5, 33.9, 47.7, 14.4, '0.255171,-0.050596,-0.666001,0.412353,0.087378,-0.214592,0.905032,-0.116571,-0.158803,-0.551751,-0.010330,0.475077,0.008045,0.218632,-0.270846,0.069905,-0.522641,-0.272489,-0.146080,-0.379358,-0.694501,-0.259078,-0.366935,-0.175436,-0.021504,0.129223,0.265272,0.489280,0.121148,0.155522,-0.041267,-0.292594,-0.972876,0.700472,-0.450669,0.070597,0.249144,0.118880,-0.012500,0.041219,-0.405554,-0.402904,-0.610436,-0.122532,0.060937,-0.022225,0.727236,0.078639,-0.232871,0.326799,-0.122321,-0.113183,-0.052639,0.208522,0.515272,-0.480905,0.329557,0.242304,-0.171135,0.150905,-0.133743,0.043897,-0.378987,0.157627,0.027691,0.284589,-0.603654,0.197504,0.504237,-0.595889,0.011380,-0.413322,0.289369,0.322648,-0.004202,0.314286,-0.273405,-0.312830,-1.176084,-0.544750,0.857020,-0.435137,0.042236,0.416710,0.278629,-0.477053,-0.299311,0.608116,-0.515046,-0.386135,0.345628,0.309393,-0.339260,-0.138148,-0.799215,0.438067,-0.003701,-0.248172,-0.234505,-0.528255,-0.132690,-0.171839,-0.219435,-0.132316,-0.362080,0.498004,-0.319113,0.097790,0.344545,-0.277778,0.306031,0.570941,0.059170,-0.339667,0.767921,0.015532,0.170212,0.038794,-0.188098,0.118070,0.157287,0.445388,0.509825,0.701825,-0.189462,0.223665,-0.754590,0.040920', '1394470', '21619567', '1293515', '1301996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10466617', '双重人格', '剧情', '西蒙（杰西·艾森伯格 Jesse Eisenberg 饰）是一个彻头彻尾的失败者，他个性懦弱，做事畏畏缩缩，总是成为人群里被遗忘的那个人。面对自己心爱的女孩汉娜（米娅·华希科沃斯卡 Mia Wasikowska 饰），他自然也是没有勇气表白的，只能整天躲在暗处，从望远镜偷窥她的一举一动。某一日，一个名为杰姆斯（杰西·艾森伯格 Jesse Eisenberg 饰）的男人出现在了西蒙的生命里，杰姆斯仿佛就是西蒙的镜像面，他充满自信，风趣健谈，无论走到哪里都能够成为众人中的焦点，甚至就连汉娜也对他刮目相看，渐渐的，西蒙找到了和杰姆斯友好共存的方式。但随着时间的推移，西蒙发现，杰姆斯正在一点一点的从他这里抢走他仅剩的生存空间，甚至想要取而代之。©豆瓣', '杰西·艾森伯格', '理查德·艾欧阿德', 7.3, 16894, 'tt1825157', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2154753212.jpg', 1.3, 5.6, 34.9, 41.3, 16.9, '0.237253,0.104777,-0.702494,0.627059,-0.536326,-0.225693,0.868961,0.020073,-0.378215,-0.156486,0.270519,0.759176,0.002258,0.336767,0.174481,0.208968,-0.382499,-0.830931,-0.155141,-0.206240,-0.163039,-0.405632,-0.555174,-0.354736,-0.092866,-0.147663,0.505325,-0.010502,-0.209277,0.246342,0.402084,0.186700,0.057874,0.723442,-0.143227,-0.016975,0.267326,-0.224133,0.028585,0.019038,0.082813,-0.195579,-0.318916,0.316909,-0.189855,0.343918,0.477862,-0.302819,0.097217,0.175367,0.282287,-0.319375,-0.035840,0.293093,0.024744,-0.228068,0.139644,0.039730,-0.123344,0.002581,0.154610,0.301623,-0.712623,0.130813,-0.314048,0.481871,-0.502446,0.400281,0.150454,-0.158927,0.202110,-0.385446,0.134453,-0.175756,0.057342,0.207960,-0.317873,-0.152908,-0.377477,-0.160548,0.382745,0.078951,-0.532967,0.316128,-0.179057,-0.337369,0.033599,-0.090057,-0.653868,-0.435824,0.287590,0.064486,-0.022476,0.381880,-0.514212,0.206117,-0.216942,-0.194012,-0.041632,-0.446964,-0.210698,-0.590280,-0.285878,-0.728896,-0.357847,0.135738,-0.226939,-0.294814,0.747007,-0.638841,0.292288,0.593987,0.151885,-0.320883,0.673507,0.115463,-0.027724,-0.123882,-0.343677,0.523545,0.148211,0.196072,0.015834,0.445444,0.154918,-0.018833,-0.366976,0.832532', '24756472', '30162520', '35158375', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10466639', '致命录像带', '惊悚', '盖里（Calvin Reeder 饰）、扎克（Lane Hughes 饰）等人是一伙无恶不作的不法之徒，某天他们接到委托，要闯入某户人家偷取一盒神秘的录像带。空空荡荡的大房子里，只有一个死去的老人坐在电视机前。他们无所顾忌，播放了那盘录像带：第一段视频中，一群年轻人带着针头摄像头去夜店狂欢把妹，却遭遇一名夺命妖妹；一对旅行中的情侣入住Motel，期间他们偶遇一名请求搭车的女子，夜晚更有人潜入他们的房间，厄运降临；两男两女驱车去林区度假，却遭遇凶残的杀手；一对网络情侣通过视频聊天，女子声称经常在家中听到奇怪的声响。镜头前，一幕幕恐怖画面接连上演。万圣节，几名男子以外遭遇了神秘而残酷的仪式，他们介入其中，自己的命运也发生改变。录像带结束，恐怖故事却刚刚来开序幕……©豆瓣', 'Calvin Reeder', '格勒恩·马奎德', 6.6, 11244, 'tt2105044', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1744740661.jpg', 3.8, 12.7, 45.2, 27.8, 10.5, '0.267647,0.033757,-0.567426,0.291482,-0.060125,0.335885,1.181348,-0.025360,-0.417366,-0.288771,0.536152,0.629454,-0.415463,0.247923,0.403073,-0.087062,-0.455011,-0.580231,0.068101,-0.302628,-0.287119,0.071831,-0.203298,-0.212839,0.284881,-0.016722,0.255060,0.154505,-0.263425,0.554265,0.186594,-0.041364,-0.743629,0.418113,-0.134771,-0.168017,0.283076,0.183973,-0.039978,0.236803,-0.264447,-0.227568,-0.128359,-0.043777,-0.079067,0.152641,0.823501,-0.215112,-0.117218,-0.036757,0.266990,0.133083,-0.343711,0.215378,0.484167,0.234363,0.409356,0.098059,-0.092214,-0.044041,-0.153083,-0.070646,-0.499841,0.228440,-0.220434,0.300806,-0.163882,0.373208,-0.055475,0.214893,0.186572,-0.171601,0.361250,0.007227,0.521484,0.405731,0.110295,-0.203052,-0.388368,0.177641,0.727764,-0.111419,-0.112388,0.328478,0.076487,-0.164742,0.072905,0.131386,-0.469980,0.175297,0.436041,-0.316923,-0.131347,0.056128,-0.653191,0.107985,-0.173909,-0.106112,-0.046969,-0.073396,-0.597662,-1.222116,-0.044204,0.010823,-0.192716,0.264820,-0.046852,-0.077370,0.583055,-0.390287,0.264882,0.482903,0.226807,-0.195237,0.723155,-0.086947,0.235220,-0.206595,-0.277456,0.088851,0.265403,0.301608,-0.089345,0.192908,-0.396617,0.013098,-0.371368,0.163343', '2269893', '1316693', '4706257', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10466836', '维克多·弗兰肯斯坦', '剧情', '正驻扎于伦敦的马戏团内，生活着自幼驼背的青年（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）。他的丑样子只能供人家取乐，而青年独独热爱医学，尤其擅长解剖学。在某次演出事故中，青年用自己的学识救下了摔成骨折命悬一线的女演员罗蕾莱（杰西卡·布朗·芬德利 Jessica Brown Findlay 饰）。他的学问得到疯狂科学家维克多·弗兰肯斯坦（詹姆斯·麦卡沃伊 James McAvoy 饰）的赏识，于是后者想方设法将其劫了出来，还为其起名伊戈尔。在此之前，弗兰肯斯坦曾经做出盗取动物园死亡动物尸体的事情，而他这一系列的做法只为进行一项疯狂大胆的实验，那就是缝缝补补创造出来人造的生物。疯狂之旅就此展开……©豆瓣', '詹姆斯·麦卡沃伊', '保罗·麦圭根', 6.2, 14301, 'tt1976009', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2263543773.jpg', 2, 15.8, 57.5, 18.9, 5.8, '0.077590,0.030922,-0.609914,0.620914,-0.259246,-0.343761,0.605975,-0.094305,-0.271130,-0.238809,0.352502,0.620067,0.038234,0.168479,0.202135,0.157994,-0.421834,-0.505916,-0.146225,0.143003,-0.291171,-0.355412,-0.244062,-0.484763,-0.115716,-0.417030,0.411970,-0.063620,-0.314011,0.186942,0.310217,0.490415,0.068509,0.228692,-0.124688,0.000542,0.093937,-0.283533,-0.165572,0.094569,0.124909,-0.244058,-0.162547,0.181549,-0.190517,0.292522,0.785036,-0.433070,0.016819,-0.413287,0.454967,-0.222071,0.166686,0.114625,0.169534,0.083814,0.218631,-0.087577,0.012919,0.070705,0.301430,-0.143997,-0.659575,-0.247907,-0.041162,0.245802,-0.511117,0.330872,-0.074319,0.054926,0.024204,-0.447239,-0.294627,0.000103,0.297898,0.231972,-0.095877,-0.117512,-0.453023,0.273527,0.347862,0.091042,-0.308190,0.257295,-0.353727,-0.531186,0.080744,-0.410056,-0.299437,-0.174948,0.352024,-0.204439,-0.059521,0.426799,-0.504385,-0.018075,-0.323796,-0.071816,-0.112376,0.040844,-0.176429,-0.771772,0.171794,-0.164659,-0.338092,-0.248084,0.168383,-0.403197,0.613600,-0.557310,0.213892,0.659347,0.026219,-0.206243,0.307566,-0.116269,0.222405,-0.103854,-0.511809,0.247566,0.061800,0.300676,0.120609,0.413898,0.240178,-0.296276,-0.265553,0.700765', '25928048', '6874567', '3811356', '4924694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10467098', '无畏之心', '剧情', '在充满了音乐和欢乐人群的加尔各答，一个怀着7个月身孕的女人孤独的站在灯火阑珊处，这个女人名叫薇迪亚（薇迪雅·巴兰 Vidya Balan 饰），瘦弱的她孤身来到这座陌生的城市，她的目标只有一个——找到失踪已久的丈夫。对于丈夫的失踪，所有的人都深信不疑，就连她自己也没有丈夫依然健在的确切的证据，可是在内心深处，薇迪亚不相信丈夫已经不在的事实，更不相信那些负责处理丈夫失踪事件的人员，凭借着手上零碎的证据，她决定靠自己的力量寻找丈夫。然而，随着调查的渐渐深入，薇迪亚发现自己似乎成为了那个被蒙在鼓里的人，而真相是这样的遥远又残酷。©豆瓣', '薇迪亚·巴兰', '苏乔伊·高什', 7.6, 7249, 'tt1821480', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1723093899.jpg', 0.7, 2.7, 28.4, 50.9, 17.3, '0.532965,-0.150088,-0.882897,0.652877,-0.491924,0.076285,1.000770,-0.035288,-0.599917,-0.278355,0.404268,0.932601,0.124286,0.335728,0.029076,0.213581,-0.407390,-0.807182,0.071874,-0.383757,-0.234231,-0.890153,-0.019754,-0.096070,-0.113490,-0.082527,0.943344,0.145387,0.118461,0.234761,0.152479,0.300246,-0.019581,0.694073,-0.328522,0.181201,0.242516,-0.106756,0.148109,0.247547,0.202771,-0.118977,-0.214736,0.605290,-0.350414,0.475975,0.507323,-0.469467,-0.232070,0.122117,0.529933,-0.447272,0.086332,0.153013,0.150717,-0.306051,0.233257,0.242977,-0.505618,-0.223876,0.102996,-0.026155,-0.929604,0.264004,0.286811,0.366343,-0.740571,0.399420,-0.288420,0.053146,0.105089,-0.223766,0.311351,0.579869,-0.110451,0.509429,-0.405071,0.085904,-0.552667,-0.106879,0.640377,0.067828,-0.474344,0.681898,-0.066685,-0.260222,-0.216390,-0.185846,-0.829905,-0.065535,0.111941,0.272177,-0.376947,0.155132,-0.337213,0.196018,-0.202387,-0.392980,0.100972,-0.240986,-0.500179,-0.194591,-0.470058,-0.437687,-0.445000,0.002835,-0.095725,-0.404661,0.712997,-0.959903,0.244080,0.553830,0.245551,-0.798341,0.763156,0.082452,0.020998,-0.236296,-0.241442,0.709345,0.060186,0.108363,0.109810,0.232489,-0.045934,-0.135031,-0.607329,0.617403', '4275444', '1783461', '1303034', '35287908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10467125', '海贼王剧场版Z', '动作', '在樱花烂漫的季节里，无忧无虑的草帽海贼团尽情享受快乐时光。途中乔巴救上了一个魁梧健硕的家伙，最引人注目的是他的右腕装配了用海楼石做成的机械手腕，凡是触碰过手腕的人均能力尽失。原来此人便是曾经培养出无数优秀弟子的原海军大将Z（大冢芳忠 配音）。苏醒后的Z得知路飞（田中真弓 配音）等人的身份后反目成仇，与随后赶来的下属艾伊（筱原凉子 配音）和宾兹（香川照之 配音）对草帽海贼团予以残酷无情的重创。原来Z因某件往事而对海贼极度憎恨，此时他正酝酿一项恐怖计划，势要带领“NEO海军”将新世界的海贼一举歼灭。他的行动引起海军本部的忌惮，而惨败的路飞等人也将向这个前所未有的敌人展开新的挑战……本片为同名漫画改编的剧场版动画，原著作者尾田荣一郎担任制作总指挥，艾薇儿演唱主题歌《How You Remind Me》和《Bad Reputation》。©豆瓣', '田中真弓', '长峰达也', 8.6, 35398, 'tt2375379', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2300520390.jpg', 0.3, 1.1, 12.6, 37.9, 48.1, '0.078107,-0.137881,-0.541558,0.750694,-0.037716,-0.185846,0.642206,0.158838,-0.399308,-0.098150,0.393703,0.591599,-0.016844,0.068990,0.511816,-0.011097,-0.262627,-0.803238,-0.391247,-0.003835,-0.259007,-0.161261,-0.332124,-0.141544,-0.129727,-0.340670,0.970570,0.157101,-0.270611,0.600600,0.268616,0.338682,-0.104039,0.279350,-0.005028,-0.039137,0.135474,-0.144284,-0.039981,0.170228,-0.104992,-0.389172,-0.145531,0.182825,-0.248559,0.400015,0.913373,-0.330934,-0.115811,-0.294744,0.243366,-0.479942,0.039595,0.116744,0.294874,0.217106,-0.026663,0.045513,-0.180379,-0.050655,-0.142928,-0.189723,-0.911204,-0.185303,0.061214,-0.002113,-0.281939,0.349233,-0.222968,-0.047505,0.463567,-0.193966,0.054617,0.233706,0.400655,0.227374,-0.091641,0.265784,-0.172104,0.335796,0.377288,-0.126223,-0.248522,0.098512,-0.038604,-0.266310,-0.247827,-0.374869,-0.253276,-0.135313,0.370451,0.019827,0.176953,0.119426,-0.636293,-0.012277,-0.231104,-0.352145,0.110577,-0.330250,-0.180024,-0.786241,-0.002014,-0.282108,-0.040921,0.047559,0.402835,-0.191931,0.950753,-0.664502,-0.043680,0.458607,0.040839,-0.250411,0.364555,-0.018672,0.076682,-0.202810,-0.149362,0.116332,0.268672,0.293999,0.150673,0.408108,-0.003024,-0.163481,-0.507742,0.441507', '25880986', '3811356', '5403927', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10467174', '海豹六队：突袭奥萨马本拉登', '剧情', '自9·11事件以来，美国政府和老对手奥萨马·本·拉登展开了旷日持久的追逐战。历经两届小布什政府，本·拉登依然逍遥法外，有如幽灵一般神秘出没于中东的崇山峻岭和沙漠荒原之中。随着奥巴马政府上台，针对塔利班基地组织的新一轮歼击战旋即展开。CIA追逐前基地组织的联络员“信使”，一步步逼近狡猾警觉的本·拉登。与此同时，骡子、万人迷、樱桃等海豹六队成员押解两名恐怖分子行走在阿富汗的山间，结果遭到突如其来的袭击。不久之后，这群在袭击中痛失战友的血性男儿接到一项绝密任务，迅速启程围剿一个基地组织重要人物。此时他们还不知道，那个人就是美国苦苦追剿的本·拉登……©豆瓣', '凯姆·吉甘戴', '约翰·斯托克韦尔', 6.4, 6898, 'tt2095605', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1831597309.jpg', 2.7, 13.6, 54.1, 21.6, 8, '0.261955,-0.067691,-0.995622,0.638147,0.266265,0.143360,0.422145,-0.175737,-0.263842,-0.145661,0.295828,0.628999,0.108331,-0.240236,0.282343,-0.417419,-0.373601,-0.620135,-0.607963,-0.219806,-0.100590,-0.253140,-0.537630,-0.444190,0.311391,-0.172590,0.658014,0.237022,-0.379339,0.734603,0.301965,0.565997,-0.481808,0.398943,-0.100881,-0.198324,0.568150,-0.192896,-0.322359,0.294115,-0.316323,-0.191901,-0.089954,-0.147269,-0.008261,0.379616,0.506579,-0.548868,-0.212629,-0.775456,-0.041695,-0.516993,-0.082850,-0.060099,0.889813,-0.070416,0.078312,0.365752,0.112204,0.181825,-0.241958,-0.290163,-0.466976,-0.078202,-0.058792,0.163153,-0.375942,0.091380,-0.056558,0.337866,0.191412,-0.230664,0.256210,0.751976,0.293961,-0.057899,0.069458,0.237054,-0.528593,0.067885,0.784263,-0.067177,-0.367163,-0.196105,0.395818,-0.343816,0.200751,-0.056091,-0.043891,-0.205595,0.351095,-0.252800,-0.196599,0.314905,-0.610026,0.219933,-0.238743,-0.335016,-0.246681,-0.242170,-0.348827,-0.984881,-0.011899,-0.216943,-0.059060,0.518837,-0.145055,0.304060,0.561232,-0.630894,0.367256,0.564042,0.103790,-0.501218,0.105501,0.187354,0.170320,-0.157554,-0.174020,0.195392,0.356491,0.646407,0.102385,0.041440,-0.214381,-0.341419,-0.074978,-0.011480', '3871833', '1301283', '2059276', '1306983');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10467774', '孙子从美国来', '剧情', '老杨头（罗京民 饰）是陕西华县一名独居老艺人，家中珍藏着表演皮影戏的全套行当。一天，离家多年的儿子突然领回了洋女友和洋孙子布鲁克斯（丁佳明 饰）。观念受到冲击的老杨头还未回过神来，儿子和女友又因要远赴可可西里工作而匆忙将布鲁克斯托付给了自己。措手不及的老杨头只得生涩的充当起洋孙子的看护人，爷孙俩时常因东西方文化差异和语言不通发生冲突。为了让布鲁克斯喝到鲜牛奶，老杨头找上了养奶牛的乡文化站王站长（刘天佐 饰）。正酝酿开班传承皮影戏的王站长借机力邀老杨头复出。在王站长不懈的游说和布鲁克斯的影响下，老杨头的皮影班终于成功开授，他与布鲁克斯之间也因为皮影戏这种独特温馨的沟通方式变得亲密无间。©豆瓣', '罗京民', '曲江涛', 8.5, 85009, 'tt2759302', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2157878128.jpg', 0.1, 0.8, 12.6, 48.2, 38.3, '0.236092,-0.148092,-0.514111,0.320167,-0.119702,-0.717020,0.368404,0.174817,-0.542799,-0.511235,-0.083096,0.403294,-0.088262,0.372368,0.090098,-0.347907,-0.203438,-0.395373,-0.272644,0.222718,-0.126159,-0.144060,-0.149420,-0.123104,-0.168969,-0.111485,0.131079,-0.119237,-0.154673,0.391289,0.406862,0.210410,0.021705,0.075963,-0.263090,0.276307,0.079134,0.169606,-0.279744,-0.224984,0.294386,-0.086713,-0.286992,-0.349418,0.315569,0.341640,0.513995,-0.213742,-0.201771,0.036170,0.093799,-0.226823,-0.075059,0.018624,0.433337,0.174167,0.323204,0.084344,-0.279672,-0.138706,-0.185413,-0.132891,-0.276522,0.496539,0.018515,0.133888,-0.641505,0.308702,0.056519,-0.026586,-0.028392,-0.626368,0.361870,0.436226,0.064003,0.647142,-0.255980,0.130359,-0.212435,0.361417,0.507686,0.120876,-0.098538,-0.017288,-0.045071,-0.343187,0.191920,-0.231983,-0.345465,-0.158052,0.275251,-0.162694,0.156059,0.136287,-0.653451,-0.130319,-0.248956,0.074664,0.394278,-0.349297,0.028430,-0.558879,-0.033481,-0.443968,0.182415,0.049380,0.334126,-0.123797,0.507973,-0.432101,0.258948,0.448383,0.028664,-0.379691,0.583438,0.109146,0.158239,-0.472920,-0.217507,-0.237975,-0.040765,0.352116,0.421163,0.568855,-0.212558,-0.183042,-0.094282,0.352916', '1876765', '25785314', '1300202', '1794435');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10467779', '大野狼和小绵羊的爱情', '剧情', '阿东（柯震东 饰）来补习班寻找离开的女友小颖，却糊里糊涂的在南阳街找到一份影印店的工作。期待着某一天在这个补习一条街找回失去爱情的他对这份工作越做越起劲，负责着整条街补习班的考卷影印。偶然的机会阿东发现了某个考卷上连载的叫做南方小羊牧场的插画，玩性大起的他在卷子上花了一只大野狼来回应图上这只孤独小羊的自言自语，没想到意外传播出去，在考生中引起强烈的反响，让一直不溫不火的小羊插画在脸书上成为热门。就这样，阿东认识了插画的作者，补习班助教小羊（简嫚书 饰）。梦想成为插画家的小羊对感情有过一段悲伤的回忆，小羊插图是她对过往爱情的倒计时，所以面对阿东寻爱的迷茫，她决定伸出援助之手。二人在不知不觉中渐生感情，然而却都未能意识到原来期待的爱情一直就在他们的身边。终于，在小羊的好友泡泡（郭书瑶 饰）的点拨下，阿东茅塞顿开…©豆瓣', '柯震东', '侯季然', 6.5, 12483, 'tt2636362', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1712347347.jpg', 2.9, 11.4, 50.2, 26.8, 8.7, '0.311523,0.017509,-0.707377,0.621696,0.207466,-0.290185,0.762392,0.041812,-0.209909,-0.055442,0.226994,0.466000,-0.294601,0.492701,0.150903,-0.019121,-0.196951,-0.721204,0.006059,-0.154834,-0.121171,-0.364398,-0.406723,0.054488,-0.098525,0.014453,0.675496,0.139860,-0.150234,0.684543,0.192503,-0.189973,-0.029311,0.485393,-0.197133,0.256569,0.095996,0.132952,0.026569,-0.073587,0.215465,-0.242348,-0.206263,0.134930,-0.025027,0.121221,0.914863,-0.169600,-0.365297,0.382142,0.467998,-0.282820,0.032161,0.020359,0.276728,0.303712,0.063848,-0.095212,-0.334281,0.074449,-0.028153,-0.072785,-0.639496,-0.203609,-0.170681,0.507160,-0.672832,0.512620,0.004951,-0.028571,0.269743,-0.457039,0.145476,0.107345,0.181028,0.571824,-0.146452,0.180490,-0.377040,0.298351,0.250908,-0.153678,-0.082302,0.461792,-0.148232,-0.247426,0.034715,0.113307,-0.373139,-0.131806,0.287386,0.037817,-0.418470,-0.004624,-0.667357,0.110027,0.085493,-0.232045,0.089406,-0.438889,-0.253365,-0.563242,-0.163999,-0.193699,-0.272132,0.123928,0.216539,-0.482170,0.812314,-0.866789,0.347065,0.676981,0.150401,-0.235951,0.762689,0.226780,-0.118421,-0.146488,-0.065656,0.200817,-0.102017,0.359273,0.185344,0.211349,0.088371,-0.100214,-0.575640,0.670422', '3811356', '3041753', '1307146', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10468424', '应许之地', '剧情', 'GLOBAL公司派遣员工Steve Butler（马特·达蒙 Matt Damon 饰）和Sue Thomason（弗兰西斯·麦克多蒙德 Frances McDormand 饰）到一个以农业为经济支柱却蕴含丰富天然气资源的小镇，试图说服当地居民和GLOBAL公司合作，一起开采天然气，此举也将振兴当地的经济。Steve本以为这是水到渠成的事情，却遭到了当地高中的一名教科学的老师Frank（哈尔·霍尔布鲁克 Hal Holbrook 饰）的反对，Frank提出要整个镇上的人进行投票，以决定是否开始天然气的开采。而一名来自环保组织“雅典娜”的年轻人Dustin Noble（约翰·卡拉辛斯基 John Krasinski 饰）的突然出现，他以自己家乡因为开采石油气而遭到破坏为证据，更加剧了当地人民对开采天然气的抵触。Steve在当地认识的一名颇有好感的女性Alice（罗丝玛丽·德薇特 Rosemarie DeWitt 饰）似乎也对他失去了信任。Steve能否顺利完成公司的任务？', '马特·达蒙', '格斯·范·桑特', 6.9, 7802, 'tt2091473', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1883451902.jpg', 0.7, 5.4, 49.7, 36.1, 8, '0.338438,0.146769,-0.773661,0.603302,-0.087716,-0.313291,0.429238,0.152477,-0.387573,-0.257702,0.126868,0.713295,0.200424,-0.136300,0.197359,-0.071677,-0.310891,-0.524721,0.013600,-0.101582,-0.239194,-0.564027,-0.202824,-0.394387,-0.274759,-0.358103,0.551883,0.241041,-0.392852,0.428243,0.066516,0.503055,0.267106,0.530642,0.153827,-0.409378,0.279217,-0.085605,-0.377540,0.125556,-0.092173,-0.010727,-0.085103,0.186447,0.199205,0.663464,0.182666,-0.019064,-0.177952,-0.209863,0.371799,-0.312051,0.330606,0.032196,0.464280,0.119599,-0.012314,0.330339,-0.470389,0.067009,0.239721,-0.227892,-1.025482,-0.157237,0.229822,0.172127,-0.604309,0.266129,-0.038633,-0.193121,-0.176460,-0.332183,-0.011201,0.671162,0.290438,0.316311,-0.143987,-0.017832,-0.543521,0.040190,0.550599,-0.274134,-0.297024,0.016885,-0.418629,-0.535014,-0.065328,-0.139472,-0.357929,-0.281703,0.079120,-0.016416,0.145352,0.179672,-0.941516,-0.147210,-0.136300,-0.502094,0.221381,-0.226443,0.081654,-0.848878,-0.084848,-0.287841,-0.208778,-0.012397,0.491344,-0.213440,0.897457,-0.852410,-0.114506,0.502419,0.680613,-0.840411,0.381837,0.016720,0.137227,-0.475465,-0.527139,0.086054,0.108381,0.287621,-0.172682,0.1