INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10478207', '凶间雪山', '惊悚', '一对情侣与登山队队友攀登雪山，不料中途天气突变,但队员们执意要上山，于是男友（吴卓羲 饰）留下女友（邓丽欣 饰）看守营地。上山三天后登山队员依旧没有任何音讯。七天后，大家都回来了，唯独她男友没有回来。队员们说，在攻峰的第一天遇到雪崩，她的男友就不幸遇难！ 他们赶在头七前回来，心想死去男友可能会还魂回来找她。半夜，男友浑身是血的出现了，一把抓住她就跑，并告诉她第一天登山就发生了山难！其余的人都死了，只有他还活着。他们究竟谁是人？谁是鬼？《凶间雪山》根据超人气鬼故事《相信谁》改编。©豆瓣', '吴卓羲', '周耀武', 3.8, 5733, 'tt5559338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1801425378.jpg', 43, 33.9, 17.3, 3.5, 2.3, '-0.084456,-0.383779,-0.642945,0.122523,-0.176202,-0.075284,0.418784,-0.369565,-0.421485,-0.152612,0.076639,0.564750,-0.213358,0.136603,0.013741,0.033451,-0.251007,-0.636707,0.128520,-0.186094,-0.467081,0.084443,0.007752,-0.131028,0.304576,-0.169508,0.363390,-0.046722,0.148040,0.453841,0.321164,-0.228636,-0.245721,0.660158,-0.285804,0.386586,-0.115603,0.153615,0.054935,0.259048,-0.083105,-0.105048,-0.372698,0.046270,0.141715,0.469228,0.348257,0.068532,-0.273652,0.128627,0.137817,-0.399649,0.172022,0.087782,0.533858,-0.441389,0.399564,0.421021,0.223434,0.054557,-0.164024,0.089926,-0.155159,0.535887,-0.058979,0.308742,-0.674785,0.139679,-0.180667,0.084171,0.014682,-0.434122,0.386335,0.355972,0.031104,0.061365,-0.024257,-0.279705,-0.819713,0.328028,0.855040,-0.267136,0.110066,0.149281,0.264394,-0.421084,-0.083105,-0.022512,-0.369164,0.389882,0.185616,0.114458,-0.522063,-0.297493,-0.214552,0.047828,-0.209835,-0.246836,-0.180060,-0.219512,0.093400,-0.461765,0.446870,0.039271,-0.398615,0.214914,0.025692,-0.177723,0.390984,-0.582122,0.370340,0.656507,0.379572,-0.686977,0.524416,0.107244,-0.221830,-0.069182,0.233319,0.120575,0.113914,0.435372,0.312577,0.231580,0.068923,0.006000,-0.150374,0.072425', '1297710', '26718282', '25908042', '1759975');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10480973', '圣斗士星矢：圣域传说', '动画', '16年前，射手座黄金圣斗士艾欧洛斯怀抱真正的女神转世雅典娜逃出圣域，途中遭到双子座撒卡和摩羯座修拉的阻击身负重伤。命运的趋势下，垂危一线的艾欧洛斯将女神托付给刚好来喜马拉雅山脉探险的日本城户财团总裁城户光政（大杉涟 配音）。知晓前因后果的光政将女神带回日本，并为之起名沙织，以孙女的名义将其抚养长大。接受命运和女神的感召，经过艰苦训练的星矢（石川界人 配音）、紫龙（赤羽根健治 配音）、冰河（小野贤章 配音）、瞬（冈本信彦 配音）等少年相继回到日本，如今他们已成长为足以独当一面的圣斗士。与此同时，奉教皇之命的刺客接二连三从圣域来到日本，一场足以载入史册的正邪之战就此拉开序幕……©豆瓣', '石川界人', '佐藤敬一', 6.4, 19347, 'tt2231489', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321634376.jpg', 4.6, 15.1, 45.4, 24.7, 10.2, '-0.234232,0.259404,-0.505913,0.504850,0.085823,-0.189267,0.319956,0.097661,-0.182885,-0.418673,0.507982,1.030062,-0.010204,0.161366,0.655170,-0.037704,-0.172847,-0.631150,-0.157218,-0.082324,-0.058105,-0.276788,-0.184061,0.185889,-0.267757,-0.494247,0.954029,-0.126763,0.103356,0.246754,0.218918,0.352816,-0.282223,-0.002829,0.083688,0.106917,-0.028489,-0.275629,-0.364387,0.365024,-0.413059,-0.127618,0.093569,0.303773,-0.073374,-0.042470,0.596016,-0.670170,0.459591,-0.490767,0.391413,-0.316326,-0.169275,0.247606,0.367921,-0.093813,-0.260116,0.560692,0.021874,-0.219241,-0.031419,-0.298873,-0.860493,-0.042693,0.100991,0.220334,-0.405009,0.183737,-0.035160,0.133782,0.351046,-0.248608,-0.017690,0.384697,0.335224,0.344210,-0.226985,0.270747,-0.028482,0.283765,0.636876,-0.188587,-0.070503,0.023168,0.364398,-0.399002,0.065573,-0.403212,-0.257839,0.071767,0.159451,0.244144,0.207068,0.475183,-0.642580,-0.457047,-0.525881,-0.408289,0.164886,-0.389640,0.152871,-0.612432,-0.198783,-0.307924,-0.070067,0.150360,0.257310,-0.146795,0.744315,-0.742560,0.098212,0.497652,0.139929,-0.195933,0.375099,-0.038118,0.290348,-0.271671,0.041540,0.536559,0.260930,0.501304,0.073954,0.041937,0.012554,0.003972,-0.330903,0.019762', '3861846', '26759819', '7051375', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10482125', '唐璜', '剧情', '在Jon（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）的人生里他只在乎这几件事：健身、飙车、去教堂、泡妞和看色情录像。虽然Jon的周围并不缺少和他上床的漂亮姑娘，可是Jon从来没有从与这些女孩的关系中得到满足感。相反，只有在看色情录像的时候Jon才能感受到“忘我的快感”。Jon不知不觉间将这样的矛盾带入了与新女友芭芭拉（斯嘉丽·约翰逊 Scarlett Johansson 饰）的关系中。虽然Jon不可自拔疯狂地爱上了芭芭拉，可是芭芭拉不能接受男友背着自己看色情录像这个事实。而这时熟女艾斯特（朱丽安·摩尔 Julianne Moore 饰）的出现令Jon对男女关系产生了新的认识。当面对美丽的女友和令人不能自拔的色情录像，Jon将做出怎样的选择？而这两个女性又将给Jon在对待男女关系的态度上带来怎样的改变？本片是约瑟夫·高登-莱维特首次执导的影片。', '约瑟夫·高登-莱维特', '约瑟夫·高登-莱维特', 6.3, 46834, 'tt2229499', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2163472540.jpg', 2, 14.6, 55.8, 22.1, 5.5, '0.549769,0.064980,-0.781282,0.748803,-0.204278,-0.282003,1.039832,-0.051456,-0.511445,-0.157965,-0.056294,0.789528,-0.366643,0.171585,0.353590,0.063626,-0.513764,-1.008513,-0.267545,-0.076396,-0.380851,-0.601972,-0.252904,-0.045465,0.019238,-0.324370,0.615822,-0.027767,-0.392126,0.415854,0.590178,0.365871,-0.016412,0.652453,-0.145131,0.026789,0.198199,0.253642,-0.330994,0.446421,0.441370,-0.262639,-0.070824,0.422761,-0.169832,0.289716,0.745740,-0.452512,-0.243968,0.105484,0.581799,0.007457,-0.043762,0.198186,-0.040129,-0.061497,0.083628,0.020467,-0.351343,0.052644,0.090168,0.036304,-0.920383,-0.059483,0.030572,0.434497,-0.542551,0.310887,-0.219305,-0.345263,0.316124,-0.203533,0.148852,0.197448,0.390156,0.626145,-0.187672,-0.112989,-0.501655,-0.061198,0.632611,0.292642,-0.199585,0.590857,-0.385687,-0.431306,-0.037779,-0.169395,-0.497206,-0.005558,0.151703,0.189308,-0.022853,0.227928,-0.710762,0.031603,-0.034091,-0.218090,-0.059028,-0.761261,-0.211311,-0.652621,-0.400900,-0.680039,-0.381529,-0.090140,0.069637,-0.461508,0.551019,-0.997201,0.225042,0.412639,0.391687,-0.395058,0.859896,0.336602,-0.220295,-0.253393,-0.416564,0.229269,0.228651,0.199394,0.162967,0.504791,0.117381,-0.257105,-0.481015,0.740677',