INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10484041', '横道世之介', '剧情', '在20世纪80年代末，出生在海港小镇的青年横道世之介（高良健吾 饰）一脸懵懂地出现在东京街头。正如他那个有些奇怪的名字一样，世之介仿佛与现代化大都会有着天然的差距，不过这个天生乐观且迂直的大男孩很快融入到新生活之中。在喧闹的校园里，他最先与仓持（池松壮亮 饰）、阿久津唯（朝仓亚纪 饰）相识，又和藏有秘密的加藤雄介（绫野刚 饰）短暂交往，与纯真无邪的富家千金与谢野祥子（吉高由里子 饰）谱写了一段浪漫恋情，也似乎曾对有着丰富人生阅历的千春姐（伊藤步 饰）心怀好感。此去经年，这些人偶尔停下脚步，摹地便想起那个曾给他们的生命留下美好回忆的世之介，心中会涌起怎样的情感？本片根据吉田修一的同名原作改编。©豆瓣', '高良健吾', '冲田修一', 8.8, 145041, 'tt2151915', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1826486066.jpg', 0.3, 0.9, 9.3, 36, 53.6, '0.256182,0.076440,-0.815804,0.636690,0.101761,-0.249534,1.052135,-0.056697,-0.562882,-0.419283,0.106038,1.005939,-0.293587,0.251600,0.414635,-0.088775,-0.338750,-0.588522,-0.153766,-0.334915,-0.028648,-0.390240,-0.311895,0.083495,-0.118574,-0.262299,0.753960,0.230327,-0.254077,0.713015,0.258236,0.456206,-0.332699,0.209430,-0.379175,0.120422,-0.221659,0.476013,-0.279336,-0.214048,-0.124333,-0.143711,-0.326892,-0.081855,-0.170459,0.313115,0.684292,-0.291545,-0.399233,0.224753,0.455738,0.137783,-0.151977,0.007550,0.183507,0.080080,0.200678,0.076735,-0.250085,0.053015,0.040020,-0.122997,-0.493365,-0.207906,0.273545,0.349648,-0.488336,0.224848,0.178211,-0.396925,0.230931,-0.030187,-0.000958,0.241156,0.578551,0.512691,-0.042700,0.005857,-0.301839,0.143925,0.576422,0.130340,-0.393251,0.500064,-0.389620,-0.557004,-0.227977,0.023530,-0.377340,-0.056115,0.149255,0.009395,-0.153497,0.250573,-0.662878,0.218810,0.260494,0.115660,0.209671,-0.273183,-0.263871,-0.455945,-0.249499,-0.969208,-0.321567,0.114229,0.306462,-0.101190,0.798117,-0.950059,0.226327,0.235982,0.136282,-0.234256,0.489759,0.204439,-0.204773,-0.277223,-0.056179,0.411249,-0.193749,0.201629,-0.176089,0.361853,-0.159614,-0.065249,-0.585739,0.459778', '1296534', '4275444', '1291877', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10484117', '天空之眼', '剧情', '凯瑟琳上校（海伦·米伦 Helen Mirren 饰）率英国情报单位追捕一名女性恐怖分子长达六年，经由美军加入高空监视行动，好不容易在秘密基地找到疑似她的身影，特种部队准备活捉她时，高空侦查人员却意外发现该名恐怖分子正与其他人密谋自杀炸弹攻击，为了防止伤害，凯瑟琳下令轰炸秘密基地将敌人歼灭。当无人战斗机的驾驶员史蒂夫（亚伦·保尔 Aaron Paul 饰）瞄准目标后，却发现这个“秘密基地”竟然是普通的民居，而一名女孩更是跑进他的攻击范围玩耍，原本单纯的跨国逮捕行动瞬间变成复杂难解的反恐任务……', '海伦·米伦', '加文·胡德', 7.8, 96332, 'tt2057392', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2306322545.jpg', 1.2, 2.5, 23.3, 53.3, 19.7, '0.006887,-0.071611,-0.658006,0.398278,-0.048913,0.188772,0.622170,-0.192944,-0.215228,-0.447208,0.512503,0.389803,0.228474,-0.290746,-0.042263,-0.022895,-0.470705,-0.536182,-0.166576,-0.449303,-0.379225,-0.495724,-0.501325,-0.644143,0.513662,-0.420536,0.737007,0.051141,-0.459329,0.203987,0.196657,0.396464,-0.337799,0.685484,-0.039904,-0.405938,0.459303,-0.493215,-0.157374,0.293568,-0.625280,-0.237189,-0.003023,0.079548,-0.035999,0.498111,0.928504,-0.159877,-0.148985,-0.391636,-0.129757,-0.458653,0.181892,-0.086857,0.588045,-0.159783,0.052880,-0.132994,0.118703,0.117173,0.042569,-0.126417,-0.552278,0.160563,-0.027931,0.063953,-0.053952,-0.228142,-0.537967,0.497449,0.285485,-0.186011,-0.019300,0.451914,0.137461,-0.066085,-0.504976,0.500348,-0.536577,-0.114536,0.528097,-0.407513,-0.200482,-0.081545,0.052471,-0.379076,0.044781,0.010779,0.168611,-0.171886,0.439120,0.104998,0.003160,0.074047,-0.380569,-0.234860,-0.698702,-0.061317,-0.049377,-0.340808,-0.309764,-0.977659,0.340587,0.266943,-0.415898,0.275663,-0.172536,0.209547,0.504124,-0.439794,0.177928,0.833664,0.265019,-0.620418,0.348199,-0.031294,0.068638,-0.323736,-0.095986,0.380236,0.216861,0.501196,-0.112922,0.111928,-0.233094,-0.421338,-0.260379,-0.117207', '2369613', '1306809', '1293013', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10484601', '一切尽失', '剧情', '距苏门答腊海峡1700海里，一名远赴印度洋独自航行的男子（罗伯特·雷德福 Robert Redford 饰）绝望地喃喃自语，在这里，似乎一切尽失。8天前。仍在睡梦中的他遭逢连番劫难，先是驾驶的帆船与一个掉入海里的集装箱相撞，再是船舱无法遏止地进水，无以修复。随之而来的厄运，如海上的暴风雨般席卷了他的一切生机。导航和无线电报废，失去所有对外联络的装备；暴雨倾盆，惊涛骇浪肆无忌惮的侵袭着他赖以生存的轮船。这位原本足智多谋的老水手只得弃船求生，而皮筏周围紧紧围困着他的鲨鱼们，更虎视眈眈地伺机觅食。不仅如此，极度的饥饿感正时刻折磨着他的肠胃，消磨着他的意志。死亡的脚步一步步的向他逼近，直到结束。本片荣获2014年第86届奥斯卡金像奖最佳音效剪辑提名，并荣获2014年第71届金球奖最佳电影配乐及剧情类最佳男主角提名。©豆瓣', '罗伯特·雷德福', 'J·C·尚多尔', 7.7, 20637, 'tt2017038', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2153382561.jpg', 0.9, 2.9, 26.9, 48.3, 21, '-0.009565,0.021395,-0.826851,0.733004,0.275538,-0.219901,0.933972,0.085325,-0.184294,-0.040305,0.269894,0.569349,-0.160589,0.221685,0.154610,-0.146002,-0.279895,-0.734815,-0.600071,0.190267,-0.230514,-0.104386,-0.392395,0.154431,0.062032,-0.330317,0.837688,0.227637,-0.150105,0.449755,0.241452,0.062977,-0.006949,0.599396,-0.244392,-0.024116,-0.214222,-0.163914,-0.113656,0.359849,-0.051682,-0.563365,-0.212578,0.074076,-0.175660,0.278894,0.900439,-0.316782,0.091641,0.056571,0.306342,-0.623699,0.026104,0.074060,0.349186,0.032330,-0.167067,0.085924,-0.230977,0.164311,0.152515,0.181975,-0.558356,-0.289352,-0.220091,0.219381,-0.332470,0.152000,-0.017318,0.249139,-0.095374,-0.221212,0.028177,0.083994,-0.072253,0.419379,-0.587213,-0.008585,-0.565002,0.397245,0.492893,0.012089,-0.576019,0.151671,-0.003674,-0.445615,-0.125190,-0.237296,-0.524130,-0.564819,0.697205,0.420816,-0.217229,0.415292,-0.522290,0.255467,-0.215261,-0.697630,-0.467507,-0.112328,-0.166490,-0.929947,0.113841,-0.406405,0.071885,0.145545,0.043277,-0.117923,0.466881,-0.161697,0.294940,0.811689,-0.043654,0.052458,0.399396,0.106566,0.131243,0.035060,-0.104090,0.347136,-0.332776,0.579694,0.229067,0.385565,-0.317577,0.213348,-0.639824,0.576476', '2159244', '1316693', '2269893', '14