INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10485526', '潜伏2', '惊悚', '经历了上一集令人难以置信的变故后，莱姆波特家的长子达尔顿（Ty Simpkins 饰）暂时摆脱恶灵的纠缠，而灵媒伊莉丝（林·沙烨 Lin Shaye 饰）则惨死室中，达尔顿的父亲乔什（帕特里克·威尔森 Patrick Wilson 饰）蒙受杀人嫌疑。由于警方需要继续调查他们的房子，乔什只得带着妻子兰妮（罗丝·拜恩 Rose Byrne 饰）和三个孩子暂时回到母亲劳瑞安（芭芭拉·赫希 Barbara Hershey 饰）家居中。本以为一切回归正常，但是兰妮和孩子们似乎仍在饱受恶灵的纠缠。劳瑞安意识到事态的严重性，于是请来仅次于伊莉丝的灵媒师卡尔（Steve Coulter 饰），试图将一切恢复正常，然而事态却朝着不可预测的方向发展……©豆瓣', '帕特里克·威尔森', '温子仁', 8.2, 108584, 'tt2226417', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2044151740.jpg', 0.2, 1.4, 18.2, 49.2, 31, '0.330772,0.013532,-0.453041,0.170489,0.024686,-0.327213,0.583361,0.297946,-0.770641,-0.615790,0.153616,0.281135,-0.018857,0.131177,0.269055,-0.026376,-0.529941,-0.457563,0.021292,-0.232091,-0.199427,-0.477450,-0.162916,-0.224820,-0.201285,-0.314013,0.320345,-0.016485,0.061997,0.398510,0.265491,0.475205,-0.148153,0.272691,0.356038,0.062873,0.160386,-0.225876,-0.381741,0.182501,0.392527,-0.007802,-0.116064,0.086039,0.158554,0.291249,0.677967,-0.530640,0.015466,-0.239967,0.136768,-0.105589,0.231086,0.365118,0.063630,-0.013228,0.006258,0.313076,-0.371594,-0.057956,0.211110,0.088302,-0.687223,0.317775,0.163996,0.375989,-0.442984,-0.108389,-0.280300,-0.169616,0.111894,-0.368314,-0.096488,0.505940,0.358328,0.313471,-0.357751,-0.132831,-0.393020,-0.157911,0.327823,0.025908,-0.220631,-0.000876,-0.026117,-0.206216,-0.369944,-0.022013,-0.468203,-0.031943,0.213511,0.375494,-0.034568,0.585452,-0.405858,-0.367070,-0.510462,-0.316622,-0.157889,-0.293329,-0.032102,-0.709806,0.311396,-0.230352,-0.227518,-0.216146,0.131876,-0.223181,0.296795,-0.368988,0.152168,0.232857,0.430482,-0.247417,0.251735,-0.209444,0.552924,-0.318648,-0.112730,0.354813,0.115297,0.357381,0.244185,0.099818,-0.031977,-0.053897,-0.239768,0.355742', '4817901', '5384590', '1485185', '25995508');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10485647', 'X战警：逆转未来', '剧情', '故事的设定发生在当下，变种人族群遭到了前所未有的毁灭性打击，而这一切的根源是“魔形女”瑞文（詹妮弗·劳伦斯 Jennifer Lawrence 饰）在1973年刺杀了玻利瓦尔·特拉斯克（彼特·丁拉基 Peter Dinklage 饰）。在得知“幻影猫”（艾伦·佩吉 E llen Page 饰）利用穿越时空的能力帮助Blink（范冰冰 饰）等战友逃脱巨型机器人“哨兵”的追杀后，X教授（帕特里克·斯图尔特 Patrick Stewart 饰）和万磁王（伊恩·麦克莱恩 Ian McKellen 饰）达成认同，决定让金刚狼（休·杰克曼 Hugh Jackman 饰）穿越回1973年，找到年轻的X教授（詹姆斯·麦卡沃伊 James McAvoy 饰）和年轻的万磁王（迈克尔·法斯宾德 Michael Fassbender 饰）并说服他们一起阻止魔形女的行动。于是，金刚狼踏上了回到过去的旅程，但是命运会不会发生逆转，任何人都无从知晓。', '休·杰克曼', '布莱恩·辛格', 8.2, 429965, 'tt1877832', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2181156848.jpg', 0.3, 1.3, 17.7, 48.8, 32, '0.089521,-0.313436,-0.535082,0.353954,0.057759,-0.224556,0.544946,-0.095301,-0.292519,-0.568272,0.163505,0.565645,-0.189551,0.007152,0.508271,-0.184199,-0.372659,-0.363153,0.192880,-0.002705,-0.357918,-0.497378,-0.155772,-0.517550,0.246042,-0.633155,0.564723,-0.035836,-0.215372,0.445675,0.340126,0.570370,-0.119396,0.227685,0.134952,0.349569,0.100560,-0.165750,-0.298158,0.268312,0.070021,0.087326,0.044339,0.215656,0.017050,0.230973,0.725439,-0.847213,-0.025604,-0.049968,0.302816,-0.299386,0.158305,0.067552,0.205974,-0.134572,-0.213154,0.335434,0.074674,0.153269,0.167714,0.070457,-0.439470,0.107414,0.115712,0.345509,-0.429286,0.250929,-0.066058,0.322336,-0.077802,-0.286653,-0.041607,0.286676,0.462405,0.144387,0.127750,0.136953,-0.663196,-0.136351,0.634056,-0.047547,-0.272367,0.149224,-0.084795,-0.369511,-0.387327,-0.092440,-0.335786,0.012064,0.365109,0.274105,-0.079780,0.382512,-0.428929,-0.513650,-0.528058,0.147844,0.029396,-0.330374,0.040322,-0.758262,0.045058,-0.260851,-0.226640,0.153232,-0.107283,-0.256118,0.444386,-0.758431,0.236653,0.395748,0.301472,-0.376603,0.541532,-0.259469,0.168346,-0.410861,0.203508,0.459902,0.278288,0.109873,0.200662,0.172240,0.235932,-0.337061,-0.12