INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10486471', '怒火保镖', '剧情', '故事的男主人公原是一名赌徒，戒毒后从事保镖的工作赚钱还债，对方敌人的时候他从不用枪，只是依靠自己的拳头和锋利的武器。在帮助一位遭受疯狂赌徒伤害的女性朋友复仇后，他陷入了更大的危险之中。', '杰森·斯坦森', '西蒙·韦斯特', 5.6, 14371, 'tt2231253', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2232111071.jpg', 7.9, 28.3, 44.3, 13.4, 6.1, '-0.075184,-0.370579,-0.409331,0.365624,-0.490671,-0.038620,1.196317,0.042178,-0.166765,-0.104297,0.769514,0.901209,0.319002,0.021117,0.162995,-0.119555,0.020686,-1.009507,-0.155725,0.146838,-0.412764,-0.332942,-0.242434,-0.383503,-0.134346,-0.355091,0.521579,0.159780,-0.628300,0.092897,0.162079,0.229400,0.252525,0.612288,-0.056825,-0.460473,0.128156,-0.198438,-0.059257,0.314892,0.287253,-0.465455,-0.158371,0.474130,-0.085753,0.464422,0.862569,-0.063074,0.038755,-0.254559,0.145852,-0.050132,-0.227769,0.066987,0.028076,-0.086974,0.277595,-0.257111,-0.045509,0.076863,0.153226,-0.340525,-1.113008,-0.305544,-0.122921,0.077114,-0.737591,0.455460,-0.204776,0.113062,0.120008,-0.108033,0.321316,0.332477,0.097478,-0.140462,-0.630231,-0.027043,-0.354111,0.536143,0.826957,-0.070264,-0.291719,0.235511,-0.472003,-0.529870,-0.430654,-0.204504,-0.700781,-0.347699,0.657940,0.141308,-0.584022,0.270507,-0.622746,0.072668,-0.043370,-0.093455,-0.209792,-0.270044,-0.348936,-0.436366,0.048470,-0.197464,-0.115666,0.171058,0.205017,-0.361343,1.120217,-0.712328,0.130937,0.766532,0.391891,-0.569807,0.834701,-0.114334,0.197015,-0.064776,-0.267019,0.114538,0.045529,0.502333,0.375070,0.148700,-0.096391,-0.075239,-0.073985,0.645474', '2028634', '30162520', '3005387', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10487226', '圣殇', '剧情', '本片荣获第69届威尼斯电影节最高奖金狮奖，是金基德的第18部电影。李江道（李廷镇 饰）是一个十恶不赦的高利贷收账者，他没有家人，也没有恋人，生活的重心就是每天上门向欠债人讨债。他生性冷酷，手段残忍，常常用暴力威胁对方，甚至还把欠债人人打成残废。那些被江道追讨过债务的家庭，从此都过上了丧失尊严的破碎生活。可是突然有一天，一个名叫江美善（赵敏秀 饰）的中年妇女来到了江道的面前，并声称自己就是他的亲生母亲，而江道就是自己那个走失已久的儿子。渴望亲情的江道在半信半疑之下和这个女人开始了一段特殊的“母子关系”。渐渐品尝到亲情温暖的江道却不知道，一场阴谋正等待着他......©豆瓣', '李廷镇', '金基德', 7.8, 61561, 'tt2299842', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1699450600.jpg', 0.9, 2.9, 25.5, 47.9, 22.8, '0.236380,-0.078781,-0.565639,0.846226,-0.383215,-0.340000,0.954714,0.092284,-0.516027,-0.001539,0.239645,0.680157,0.147208,0.482778,0.033503,0.119628,-0.070960,-0.844486,-0.139758,-0.152477,-0.171780,-0.452619,-0.391755,0.083159,-0.266931,-0.220037,0.510531,-0.009226,-0.304153,0.396333,0.559179,0.192709,0.070469,0.622547,-0.382724,0.336946,-0.008732,0.235459,-0.248084,0.015401,0.124205,-0.389776,-0.139723,0.381977,-0.098140,0.572475,0.636235,-0.252575,-0.183440,-0.142224,0.433204,-0.484084,-0.048769,0.335369,0.382539,-0.232881,0.364346,0.327176,-0.118832,0.085740,0.093831,0.067921,-0.821245,-0.083733,0.015347,0.202599,-0.645275,0.483098,-0.081604,-0.184194,-0.062683,-0.330508,0.207942,0.039815,0.296760,0.370676,-0.359101,-0.130428,-0.532637,0.365312,0.807174,0.043946,-0.283948,0.382807,-0.236857,-0.387995,-0.056133,-0.438229,-0.561969,-0.107526,0.425206,-0.285379,-0.207594,0.248734,-0.499727,0.141391,-0.052116,-0.160842,0.083094,-0.320494,0.058351,-0.237684,-0.098142,-0.689046,-0.489838,0.127873,0.113185,-0.544104,0.672859,-0.725450,0.333938,0.658799,0.378463,-0.616803,0.712225,0.324597,-0.065320,-0.150388,0.098493,0.076876,0.077448,0.338397,0.164611,0.254853,-0.017661,0.243753,-0.011007,0.781069', '24756472', '6874741', '30162520', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10487238', '争钱斗爱ATM', '喜剧', '苏（波莉雀娅·彭娜妮可 Preechaya Pongthananikorn 饰）和吉（德·辰塔维 塔纳西维 Chantawit Thanasewee 饰）是一对相恋五年的恋人，两人之间感情十分要好，但是，这五年来，他们的恋情一直躲藏在“地下”，因为除了恋人的身份外，他们还是在同一家银行就职的同事，根据银行的规章制度，同事之间，是不被允许发展友情以上的关系的。深深相爱的两人决心步入婚姻的殿堂，但这也意味着，他们中的一方，必须主动放弃稳定而又高薪的职位，为了这个问题，两人几度争执不下。就在这个节骨眼上，一台自助取款机由于故障而令银行损失了巨额财产，苏和吉决定将此当做一个千载难逢的好机会，两人约定，谁能够先追回这笔巨款，另一方就要主动辞职，一时间，两人从恋人转变成为了竞争对手。©豆瓣', '辰塔维·塔纳西维', '梅兹·塔拉', 7, 7012, 'tt2191394', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1416813860.jpg', 0.9, 5.9, 45.1, 38, 10.1, '0.431102,0.204215,-0.762249,0.710629,0.073410,-0.403755,0.541935,0.159241,-0.431248,-0.224116,-0.044508,0.870737,-0.248327,0.132937,0.239022,-0.140273,-0.135931,-0.847948,0.012358,-0.535538,-0.384741,-0.718124,-0.146065,-0.243334,-0.370122,0.218928,0.800522,0.056122,-0.136380,0.280898,0.500761,0.128260,-0.155402,0.483818,-0.005720,-0.346739,0.182688,0.151155,-0.578928,0.312005,-0.024363,-0.067000,0.094756,0.227747,0.220943,0.359177,0.527875,-0.145128,-0.339078,0.169776,0.290620,-0.126198,-0.107595,0.057670,0.511002,-0.214411,0.289502,0.575858,-0.310545,-0.061422,0.135347,-0.270949,-0.796153,-0.114891,0.014208,0.053621,-0.704354,0.467769,0.038616,-0.045035,-0.108657,-0.198054,0.124955,0.779105,0.419281,0.244067,-0.322030,-0.235795,-0.602123,-0.030692,0.824418,-0.006080,-0.147203,0.473393,-0.326232,-0.587454,-0.405718,0.014612,-0.388183,-0.092807,0.273416,0.153412,0.012233,0.077351,-0.689942,-0.072925,-0.294990,0.114704,0.017830,-0.571470,0.326068,-0.541916,-0.317882,-0.487721,-0.479418,0.407955,0.011365,-0.223029,0.510321,-0.811091,-0.091028,0.560944,0.600637,-0.700091,0.854662,0.392549,0.385593,-0.577862,-0.101118,-0.145533,-0.102034,0.131113,0.148671,-0.084004,0.244810,0.084609,-0.108235,0.287497', '4301278', '25908042', '1418613', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10487240', '神通乡巴佬', '剧情', '长得不帅、单纯可爱的男人楚中天（王宝强 饰）从乡村到城市寻找自己爱情的故事。一个是有洁癖的都市中产（曾志伟 饰），一个是邋遢的乡下毛头小子（王宝强 饰），当楞头楞脑的“傻根”遭遇老谋深算的“琛哥”， 改变是必须的。朱哥宝训第一条：要追女仔，先要会败家，上万元的西装是一定要 上身的。朱哥宝训第二条：即使对方是个盲人，谎也是要编的，“相貌英俊，酷似金城武，年轻多金，一分钟十几万上下”。朱哥宝训第三条：如果有人跟你借钱，跟他讲“穷去跟你妈说，跟我有什么关系。”朱哥宝训第四条：上面一条是对外人的，对待你的“恩人”，一定要知恩图报。在朱月坡的精心调教下，楚中天能否胜利出师？老实巴交的他真的能兑现之前的承诺，不惜一切代价去报答“恩人”朱月坡吗？©豆瓣', '王宝强', '皮建鑫', 4.2, 3587, 'tt2458022', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1441605450.jpg', 36.8, 31.6, 22.1, 5.9, 3.5, '0.088475,-0.196590,-0.285200,0.455509,-0.700097,-0.158040,0.307110,-0.071946,-0.224029,0.019093,0.104981,0.753207,0.017315,0.018764,-0.027171,0.388175,0.020673,-0.429506,-0.086448,-0.050656,-0.235028,-0.566858,-0.171433,-0.046049,0.006203,-0.178761,0.244470,-0.114660,-0.274840,0.011273,0.680965,-0.040589,0.156307,0.104467,-0.612481,-0.203937,-0.278850,0.243543,-0.057787,0.113931,-0.017238,0.053694,0.058629,0.086997,0.012937,0.435407,0.114660,0.071703,-0.489900,0.200295,0.417607,-0.093852,0.004337,0.015475,0.092780,-0.369802,0.473331,0.453696,0.138192,-0.129521,-0.080422,-0.462406,-0.658191,-0.322489,0.156770,0.080297,-0.775275,0.231359,0.089649,-0.236344,0.255888,-0.271573,0.127837,0.183046,0.254490,0.303572,0.006708,-0.043583,-0.705828,0.318882,0.628811,0.383162,-0.083523,0.255364,-0.160561,-0.258658,0.089675,-0.118712,-0.656211,0.418835,0.094963,-0.618786,-0.350320,-0.432896,-0.361229,-0.110677,-0.177397,0.127520,-0.133907,-0.429511,-0.029418,0.173097,-0.017553,-0.722437,-0.135054,0.194250,0.206393,-0.342157,0.801581,-0.658596,0.010268,0.508611,0.363053,-0.782401,0.741778,0.529874,-0.162777,-0.276152,0.075320,-0.124266,0.067170,0.002604,-0.047517,0.347680,0.445328,-0.291317,-0.337548,0.436596', '1877596', '1306755', '1308805', '10831449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10487568', '蜂鸟特攻', '剧情', '一年前，作为特种部队一员的约瑟夫·史密斯中士（杰森·斯坦森 Jason Statham 饰）在阿富汗战场经历了常人难以想象的血雨腥风。因某起事件他被军事法庭指控，并被诊断患有攻击压力症。之后约瑟夫从医院逃出，混迹在流浪汉中间艰苦求生。他化名乔伊，与名叫伊莎贝尔（维多利亚·贝维克 Victoria Bewick 饰）的女孩结伴。在一次被歹徒袭击之后，慌不择路的乔伊意外闯入一幢无人房间，适逢主人赴美公干，他放心享用主人的一切物品。饱受精神困扰的他，似乎只能从善良的修女克里斯蒂娜（阿嘉塔·布泽克 Agata Buzek 饰）那里得到些许帮助。偶然机会，乔伊涉足中国黑道，在刀头舔血赚取营生的同时，他意外听到关于伊莎贝尔的消息……©豆瓣', '杰森·斯坦森', '斯蒂文·奈特', 6.4, 40259, 'tt1893256', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2180344882.jpg', 1.9, 13, 53.9, 23.2, 7.9, '-0.115468,0.132099,-0.654086,0.212927,-0.021241,-0.107060,0.741215,-0.040337,-0.758859,-0.373613,0.322528,0.651173,-0.100742,0.022315,0.251051,-0.130826,-0.148241,-0.413268,0.144043,-0.261462,-0.455437,-0.304104,-0.205770,-0.485069,-0.017562,-0.506550,0.421464,0.150414,-0.385248,0.501252,0.196474,0.500241,-0.154777,0.495669,-0.231354,-0.123817,0.351263,0.012540,-0.285793,0.186194,0.069184,-0.425014,-0.100634,0.230253,0.149176,0.243793,0.670360,-0.221606,-0.170984,-0.060997,0.053716,-0.024619,0.172874,0.101773,0.333390,0.028741,0.172962,0.168193,-0.161454,0.008399,0.087814,-0.048244,-0.576960,-0.198128,-0.058566,0.297796,-0.503397,0.476451,-0.200032,0.062148,-0.043144,-0.088364,0.042103,0.388974,0.280841,0.210097,-0.128478,0.218884,-0.240924,0.045921,0.577497,-0.228063,-0.068164,0.339703,-0.302350,-0.585883,0.138811,-0.034737,-0.303000,0.219186,0.351088,-0.123289,-0.415997,0.308732,-0.411049,-0.092571,-0.463251,-0.176027,-0.189369,0.067861,-0.305459,-0.696332,-0.050337,0.039704,-0.254367,-0.027848,-0.086668,-0.018426,0.391803,-0.662612,0.380777,0.590645,0.119989,-0.344906,0.430971,-0.098737,0.180018,-0.240881,-0.057259,0.657033,0.291476,0.314345,0.176083,0.173743,-0.140063,-0.083738,-0.139478,0.264076', '1465415', '30137576', '4817901', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10491641', '我的P.S.搭档', '喜剧', '这里的PS并不是指观众所熟悉的“Photoshop”，而是很隐晦的“Phone Sex”。一心想要成为一名创作歌手贤胜（池城 饰），得知前女友找到了高帅富新男友后，大受刺激，夜夜不能眠。自卑寂寞感马上爆发，在翻来覆去睡不着觉的某个晚上，他接到一通奇怪的“色情”电话。外貌号称完美的允静（金雅中 饰）却总是个觉得缺乏男友爱护的女子，于是某一天她为了企图挽回交往了5年的男友的心，使用“性趣”准备了小惊喜，用暧昧的语调和对方说出刺激感官的诱人台词，哪知道按错了号码，电话接听的那头正是陌生人贤胜。两个内心受伤的男女在互相恶作剧中逐渐敞开心扉……©豆瓣', '金雅中', '卞成贤', 7.1, 55842, 'tt2592336', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1742748250.jpg', 0.8, 5.8, 42.4, 37.8, 13.1, '0.375132,0.259602,-0.465474,0.508542,-0.057622,-0.029624,0.791671,0.048281,-0.450715,-0.306290,-0.158090,0.479392,-0.297514,0.482092,0.290656,0.007129,-0.132331,-0.607304,0.156615,0.073743,-0.018871,-0.241811,-0.174086,-0.071885,0.088569,-0.236986,0.240838,-0.028064,-0.449818,0.413305,0.213659,0.255574,0.117530,0.478593,0.114186,-0.178181,-0.197627,0.027701,-0.027697,0.055669,0.205863,-0.146427,0.066393,0.370363,-0.206468,0.445154,0.380173,-0.156671,-0.546687,0.152030,0.653171,0.135481,-0.228044,0.005217,0.031368,0.231485,0.494114,-0.209149,-0.239993,0.109277,0.171779,0.181377,-0.710360,0.058979,-0.129721,0.178845,-0.047249,0.285806,-0.244589,-0.081094,0.111750,-0.340119,0.206918,0.098436,0.218315,0.602810,-0.330255,0.173852,-0.055421,0.007395,0.422697,0.156019,-0.114038,0.555412,-0.105280,-0.441539,0.261168,0.107893,-0.455994,-0.023338,0.172020,0.091946,-0.156991,-0.230711,-0.423529,0.103406,-0.038052,-0.035218,-0.141534,-0.509036,-0.275741,-0.199259,-0.297762,-0.186628,-0.167544,0.226611,0.228018,-0.046666,0.589207,-1.110195,0.160702,0.635788,0.183779,-0.430282,0.373145,0.348163,-0.386691,-0.184060,0.016845,0.241331,-0.195524,-0.035661,-0.002397,0.320852,-0.271938,-0.064872,-0.559616,0.285605', '1937946', '2052978', '1308755', '1389971');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10508874', '布拉芙夫人', '爱情', '大学教授学奎（郑雨盛 饰）因为一场性丑闻而失去了一切，被贬值到十分偏远的小镇任职。在那里，学奎遇见了美丽的少女德伊（李絮 饰），两人坠入爱河。然而，不久之后，学奎官复原职，即将回到大都市首尔，为了自己的前途，学奎残忍的抛弃了德伊。一晃眼八年过去，此时的学奎已经成为了小有名气的作家，事业走上的巅峰，前途一片光明。可是，就在这个节骨眼上，他却患上了不治的眼疾，视力一天一天的退化下去。某日，学奎的隔壁搬来了一位名为世静的女子，世静待学奎十分亲切，在生活中对他无微不至。随着时间的推移，学奎觉得自己已经离不开世静了。然而，目不能视的学奎并不知道，世静的真正身份，正是曾被自己抛弃的德伊。©豆瓣', '郑雨盛', '任弼星', 5.9, 19112, 'tt3958014', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2202212337.jpg', 3.9, 23.2, 52.5, 15.5, 5, '0.164033,0.408284,-0.562668,0.402338,-0.325723,-0.442392,0.733559,0.270790,-0.588721,-0.389195,0.172525,0.814265,-0.324134,0.409754,0.536169,0.194304,0.127026,-0.786439,-0.059971,-0.423858,-0.388952,-0.397094,-0.347583,-0.044016,-0.241797,-0.344360,0.839230,0.289856,-0.190058,0.336841,0.203620,0.196123,0.239256,0.577814,-0.415767,-0.040558,-0.083123,0.060813,-0.091429,0.156395,0.204375,-0.423703,0.004813,0.157639,-0.213885,0.139263,0.581640,-0.147407,-0.368839,-0.081707,0.641198,-0.445391,-0.200569,0.139582,0.517403,-0.158997,0.064433,0.067542,-0.417618,-0.250173,-0.102498,-0.203528,-0.615878,0.002334,-0.113190,0.133855,-0.717357,0.431437,0.069655,-0.233183,-0.010158,-0.437928,0.177082,0.291469,0.085534,0.666437,-0.225392,-0.083857,-0.476968,0.077078,0.721844,0.160707,-0.416078,0.637131,0.034836,-0.360501,-0.223567,-0.371800,-0.499095,-0.019622,0.275520,0.094126,-0.271070,0.390453,-0.307943,0.134966,-0.426396,-0.262559,-0.018578,-0.300871,-0.165554,-0.192146,-0.248658,-0.457561,-0.346162,0.239670,0.080733,-0.355428,0.675026,-1.005443,0.395527,0.378621,0.223177,-0.427688,0.608743,0.181862,0.201099,-0.140790,0.095144,0.481271,-0.026465,0.389414,0.079715,0.186358,-0.486481,-0.089395,-0.521102,0.723741', '35030151', '30345227', '1937946', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10508876', '邻居', '剧情', '城中发生连环凶杀案，每隔十天就有一人被杀，凶手将尸体装入旅行箱抛弃于荒郊。江山公寓202号的女孩就是第一个受害者，某日放学后突降暴雨，女孩搭乘邻居的车回家，岂料邻居竟然心怀不轨虐杀了小女孩。女孩的继母（金允珍 饰）为此十分内疚，经常幻觉女孩回到家中。为了掩盖自己的犯罪事实，凶手不放过任何一个对他有怀疑的人，事件演变为连环杀人案。这时，令凶手最为惶恐的是另一个女孩的出现，这个女孩竟与之前遇害的女孩长相极为相似，凶手一边计划着杀掉她，一边陷入心魔无法自拔……电影《邻居》是韩国由人气网络漫画作家姜夫的同名网络漫画改编而成的作品。©豆瓣', '金允珍', '金辉', 7.5, 60430, 'tt2195490', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1600144202.jpg', 0.6, 3.2, 33.5, 46.7, 16, '-0.078170,-0.336483,-0.425978,0.434219,-0.089887,0.151732,0.898876,-0.004603,-0.612011,-0.521101,0.474937,0.674428,-0.279132,0.385882,0.402198,-0.110452,-0.289075,-0.566251,-0.148288,-0.235208,-0.375517,-0.147106,-0.006388,-0.364312,0.090127,-0.223659,0.700907,0.160146,-0.318657,0.176799,0.306759,0.375650,-0.496403,0.402085,-0.207964,0.126192,-0.217445,-0.206986,-0.256869,0.371907,-0.150098,-0.187732,0.074048,-0.019745,-0.508922,0.204278,1.035728,-0.114887,-0.352608,-0.310113,0.656920,-0.267410,-0.276514,-0.096197,0.550529,-0.022032,0.405599,0.118784,-0.110903,-0.277611,0.405565,-0.123849,-0.570460,0.185155,0.210935,0.133109,-0.267606,0.184469,-0.361395,0.140635,0.183505,-0.189739,0.227698,0.098683,0.485179,0.270240,-0.092727,0.022740,-0.650708,0.153021,0.357952,0.047526,0.086168,0.397396,-0.157335,-0.330505,-0.046562,-0.199515,-0.364032,0.417048,0.262173,-0.125833,-0.286791,0.204182,-0.396055,-0.232610,-0.242933,0.054523,0.160139,-0.412961,-0.560718,-0.425104,-0.005226,0.208578,-0.171770,-0.208217,0.004859,-0.145078,0.647416,-0.729765,0.218474,0.619397,0.203584,-0.538141,0.560837,0.005383,-0.077661,-0.391957,-0.104225,0.257594,0.321781,0.174985,-0.214772,0.132836,-0.237445,-0.150632,-0.394574,0.278991', '21619567', '1467779', '1417036', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10508878', '偷心贼', '喜剧', '李浩泰（周元 饰）是众人眼中的成功警探，无论多么扑朔迷离的案件，只要落入他的手中，皆能被调查得水落石出，他也因此被同事们赋予了“专门分析器”的光荣称号。近日，一位专门盗窃艺术品的女贼尹珍淑（金雅中 饰）浮出了水面，她以“完美无缺的犯罪”著称，所到之处，误会留下任何蛛丝马迹。一个无案不破的警探，一个无往不利的女贼，当这两个人碰到一起，会碰撞出怎样的火花呢？让李浩泰感到震惊的是，尹珍淑的真实身份竟然是自己的初恋情人，曾经，他们有过一段无疾而终恋情，让李浩泰久久无法释怀，如今，十年过去，当曾经的眷恋再度出现在自己的面前，李浩泰会做出怎样的选择呢？©豆瓣', '金雅中', '李贤中', 6.4, 11285, 'tt3694790', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2185139480.jpg', 2.8, 13.9, 51.8, 23.7, 7.8, '0.484053,0.154551,-0.628456,0.622246,-0.305897,-0.225149,0.758471,-0.180225,-0.760703,-0.298735,0.329669,0.691254,-0.461592,0.147006,0.041378,-0.115128,0.033971,-0.926778,-0.098692,-0.407765,-0.249488,-0.314660,-0.602384,0.073969,-0.022456,0.053656,0.520952,0.067457,-0.044587,0.336026,0.606879,0.460056,-0.198605,0.305907,-0.260846,-0.048303,-0.259384,0.052154,-0.252809,0.034027,0.195902,-0.424738,-0.109904,0.387414,-0.480655,0.171614,0.639314,-0.220331,-0.425785,-0.085131,0.671738,-0.265936,0.175390,0.255934,0.081839,0.008936,0.084103,0.336970,-0.276862,-0.092154,0.344236,0.355626,-1.098950,0.027810,0.050531,0.378989,-0.601625,-0.027479,-0.004784,-0.236326,0.031096,-0.171236,0.401239,0.458410,0.365739,0.359029,-0.499200,-0.116578,-0.525782,0.244548,0.737245,0.081478,-0.421484,0.083371,-0.218684,-0.376418,-0.070031,-0.390541,-0.278638,0.282888,0.322947,0.226038,-0.101985,0.293111,-0.384164,-0.205071,-0.279745,-0.008236,-0.141143,-0.379936,-0.146618,-0.417467,-0.138251,-0.488353,-0.638589,0.069864,-0.139773,-0.390340,0.549753,-0.832827,0.095890,0.413172,0.043516,-0.477557,0.658512,0.418643,-0.139603,0.016482,-0.285701,0.131337,0.193049,0.165127,-0.032923,0.275943,0.175921,-0.093947,-0.330407,0.335125', '1793491', '1874704', '4301278', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10508879', '青魇', '剧情', '郝冬（黄轩 饰）在收听午夜电台节目时，谈到了自己失眠的痛苦经历。郝冬的女友——电台DJ依凡（薛凯琪 饰）开始对他进行心理辅导。而郝冬却对她讲述了自己的梦魇：一个白衣飘飘的长发女子（周楚楚 饰）从高楼坠落，这令他难以安眠。而更令人恐惧的是，他那些关于九里村的童年记忆，虽然支离破碎，却令人不寒而栗。当时，建国初期，一对夫妇来到了九里村，支援村里农业生产建设，丈夫叫建国，是杂交水稻专家，他的妻子名叫骆晓月。来到村子没多久，建国因下河触电身亡，而晓月则被村长的智障弟弟骚扰。后来，晓月竟然在夜间被人用柴刀杀死。警察调查中，发现智障弟弟为最大嫌疑人，但是由于其为精神病，故未受惩罚。20年过去了，郝冬再度回到九里村，住在舅舅家中，又遭遇了一连串令人毛骨悚然的诡异景象。当他在一步步揭开真相的时候，同时也陷入了对于凶手杀人的回忆中，陈年往事如疮疤被揭开，真相令人瞠目结舌……', '黄轩', '邱礼涛', 6.1, 13693, 'tt2303104', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1594175844.jpg', 4.3, 17.4, 51.6, 20.2, 6.6, '0.162568,-0.139883,-0.541341,0.163538,-0.054269,-0.255124,0.843438,0.041446,-0.939064,-0.431111,0.257945,0.502426,-0.326243,0.371281,0.121682,-0.053607,-0.060892,-0.542512,0.082166,-0.198914,-0.256892,-0.149640,0.075623,-0.195746,0.137551,-0.109219,0.324260,0.121319,-0.298356,0.439095,0.082205,0.491652,-0.253364,0.542668,-0.173433,0.053369,0.033847,-0.071218,-0.146552,-0.041615,0.032297,-0.493972,-0.104716,0.288099,-0.422009,0.433792,0.866182,-0.207814,-0.447524,-0.105484,0.315528,-0.219646,-0.149012,0.227090,0.299511,0.076166,0.074450,0.247484,-0.219672,-0.102809,0.047773,0.004434,-0.510556,0.283388,0.156836,0.188412,-0.469948,0.204798,-0.138309,0.140943,0.204050,-0.218448,0.436340,0.235733,0.217383,0.775622,-0.384343,-0.011670,-0.381822,0.406520,0.655161,-0.075257,0.042058,0.304565,-0.207238,-0.219726,0.080672,-0.026409,-0.231142,0.115422,0.264236,0.127347,-0.422746,0.363758,-0.505423,-0.023034,-0.218290,-0.195173,-0.215913,-0.194242,-0.394550,-0.343354,-0.139513,-0.208116,-0.218507,0.004018,0.023993,-0.229634,0.513772,-0.546887,0.215755,0.365257,0.194588,-0.217460,0.268576,-0.059663,-0.035816,-0.205962,0.007571,0.453227,0.027946,0.462659,0.048586,0.231837,-0.241695,-0.238415,-0.438887,0.342372', '2365260', '21619567',