INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10508907', '切尔诺贝利日记', '恐怖', '克里斯（杰西·麦卡尼 Jesse McCartney 饰）、娜塔莉（奥莉维娅·达德利 Olivia Dudley 饰）、阿曼达（蒂温·凯利 Devin Kelley 饰）等来自美国的青年男女正在进行一段快乐有趣的欧洲之旅，当他们抵达乌克兰时，经当地好友保罗（乔纳森·萨多 斯基 Jonathan Sadowski 饰）的介绍，他们和另外两名客人组团，跟随当地向导尤里（Dimitri Diatchenko 饰）展开了一段极限旅游。所谓极限旅游竟是走入在1986年因核泄漏事故而沦为鬼城的切尔诺贝利。寻求刺激的年轻人们一拍即合，携手踏入了这个至今仍为核辐射的乌云笼罩的废城。当地颓败、死亡、神秘的氛围给了这群人前所未有的末世体验，可是他们同时发现，自己并非是这座死城中的唯一生物。随着夜幕降临，死神之手渐渐向这群胆大妄为的年轻人逼近……©豆瓣', '杰西·麦卡尼', '布莱德利·帕克', 5.7, 10028, 'tt1991245', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1727072001.jpg', 8, 26.7, 45.3, 15.1, 5, '0.426531,-0.153449,-0.649998,0.353505,-0.046970,-0.148058,0.622964,0.148064,-0.490110,-0.410393,0.302823,0.597153,-0.277546,0.157561,0.434268,-0.039757,-0.395955,-0.495401,-0.112066,-0.201437,-0.250277,-0.086039,-0.423141,-0.188985,-0.146675,-0.284611,0.511989,0.294608,-0.153266,0.574322,0.136578,0.625658,-0.375487,0.386135,-0.139936,-0.057487,0.363583,-0.144603,-0.362237,0.232736,-0.392568,-0.181707,-0.082547,-0.004223,-0.205734,0.291427,0.818295,-0.215699,-0.082941,-0.200398,0.375321,-0.295338,-0.064899,0.212428,0.182038,0.014823,0.035070,0.040924,-0.011441,-0.014129,-0.096545,-0.275358,-0.458098,0.241248,-0.144586,0.096797,-0.240703,0.277499,0.084379,-0.247500,0.163584,-0.257458,0.171268,0.499479,0.081126,0.395388,-0.034386,-0.054762,-0.371889,0.226924,0.799156,-0.017167,-0.305287,0.132688,-0.221213,-0.516444,-0.030867,0.021466,-0.262087,-0.179305,0.238602,0.215560,0.101516,0.306917,-0.707155,0.154234,-0.373858,-0.367585,-0.009819,-0.165907,-0.245815,-1.035848,-0.177280,-0.363780,-0.131722,0.074376,-0.066943,-0.053948,0.512279,-0.374095,0.361883,0.570752,0.231165,-0.312080,0.593243,-0.225375,0.096929,-0.289552,-0.196810,0.463131,0.137074,0.366635,0.036145,0.203391,-0.120552,-0.013541,-0.297292,0.450687', '2159244', '3147969', '3871833', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10508921', '弗兰肯斯坦', '剧情', '由导演丹尼-波尔(Danny Boyle)担纲执导的剧作《弗兰肯斯坦(Frankenstein)》将于2011年在伦敦西区正式挂牌上演。英国演员本尼迪克特-康伯巴奇(Benedict Cumberbatch)、男星约翰尼-李-米勒(Jonny Lee Miller)将担任剧中主人公亮相英国国家剧院(National Theater)。改编自由英国诗人雪莱的妻子玛丽-雪莱于1818年创作的同名科幻小说，由编剧尼克-蒂尔改编之后，舞台剧《弗兰肯斯坦》将从“怪物”的角度来讲述这个在西方世界家喻户晓的科幻故事。BBC版“福尔摩斯”康伯巴奇将在其中饰演剧中“弗兰肯斯坦博士”，约翰尼-李-米勒则饰演由博士造出来的“怪物”。本尼迪克特-康伯巴奇在戏剧舞台的表现赢得了剧迷与业内人气的广泛好评，由其主演的作品主要包括《城市》、《纵火犯》、《犀牛》、《调整时期(Period Of Adjustment)》、《海边来的女人(The Lady From The Sea)》、《罗密欧与朱丽叶》以及《多么可爱的战争(Oh! What a Lovely War)》等，凭借正在奥利维尔剧场挂牌上演的《舞蹈之后(After The Dance)》，康伯巴奇获得伦敦晚间标准奖最佳男主角的提名。在荧屏作品方面，出演BBC版热播英剧《福尔摩斯》为康伯巴奇赢得了奥利维亚大奖提名，不仅如此，他还参演了由史蒂文-斯皮尔伯格执导的影片《战马(War Horse)》。对于著名影星约翰尼-李-米勒来说，《弗兰肯斯坦》并不是他与导演丹尼-波尔的首次合作，两人首度“牵手”要追溯到1996年版的电影《迷幻列车(Trainspottin', '本尼迪克特·康伯巴奇', '丹尼·博伊尔', 9.4, 8578, 'tt1795369', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2252273146.jpg', 0.3, 0.4, 3.7, 22.3, 73.4, '0.060297,-0.131502,-0.477360,0.735783,0.452506,-0.315317,0.682169,0.092530,-0.320007,-0.172032,0.285847,0.981830,-0.523482,-0.051057,0.726073,-0.183506,-0.734114,-0.582368,-0.280246,0.017947,0.204563,-0.478098,-0.304326,-0.207843,-0.241448,-0.472756,0.964127,-0.238251,-0.340552,0.368039,0.604289,0.253877,0.058875,-0.114213,0.208749,0.100006,0.422823,-0.108412,-0.588344,0.463744,0.114062,-0.159497,-0.261979,-0.173599,0.043602,0.067660,0.621921,-0.314952,0.284065,0.020833,0.610765,-0.259548,0.117517,-0.291621,0.108698,-0.077161,0.348367,0.082697,0.073853,0.061156,-0.086951,-0.530445,-0.674383,0.009267,0.297284,0.314101,-0.472126,0.275693,-0.415222,0.048543,0.147016,-0.230281,-0.056467,0.059309,0.612872,0.359389,0.206422,0.162150,-0.244155,0.717538,0.094178,0.152510,-0.378020,0.248353,-0.152465,-0.688274,-0.236492,-0.187543,-0.447182,0.207988,0.334962,-0.359773,0.232313,0.281476,-0.574703,-0.320679,-0.091710,-0.431996,0.145788,-0.193522,0.047301,-1.360455,-0.138810,-0.135620,0.391791,-0.647955,0.201087,-0.382462,0.760535,-0.615311,0.136629,0.476976,0.158233,-0.023078,0.796082,0.011543,0.103864,-0.395774,-0.170251,0.238804,-0.014835,0.045429,0.166019,0.480530,0.163949,-0.452409,-0.289491,0.682562', '34961898', '30397916', '26275494', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10511636', '极地大冒险2', '剧情', '小驯鹿尼柯（埃里克·卡尔森 Erik Carlson 配音）的爸爸是圣诞老人团队中的一名成员，但是由于常年在外，以致于和妻子的关系日趋冷淡，处于分居状态。尼柯志愿加入圣诞团队，并且在父亲的指导下展开训练。虽然他期盼父母能够重归于好，可是事与愿违，母亲结交了新男友兰尼（里库·涅米宁 Riku Nieminen 配音），兰尼还给尼柯带来一个小弟弟强尼（尤哈娜·瓦伊蒂宁 Juhana Vaittinen 配音）。尼柯无法接受眼前的事实，他对强尼恶言恶语。结果在野外玩耍的时候，强尼遭到白狼集团的绑架。心怀愧疚的尼柯无法放任不管，他独自踏上凶险的征途。尼柯和强尼的命运将会如何……©豆瓣', '卡里·希耶塔拉赫蒂', '卡里·尤索宁', 6.1, 19234, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2164199913.jpg', 6.3, 16, 53.3, 17, 7.5, '0.067573,0.011994,-0.641453,0.628957,0.017006,-0.314548,0.584753,0.128657,-0.583174,-0.349331,0.072672,0.551307,0.125109,0.486373,0.256074,-0.122336,-0.325403,-0.431286,0.084325,-0.022255,-0.262552,-0.563413,-0.175515,-0.289104,-0.168790,-0.348847,0.748380,-0.157618,-0.140689,0.306950,0.336696,0.587964,-0.164037,0.439404,0.024856,-0.009098,0.413715,0.025603,-0.580561,0.284332,-0.040039,0.050813,-0.056426,0.102322,0.295515,0.295825,0.731789,-0.300551,-0.130348,-0.108904,0.279794,-0.125602,0.151578,0.114813,0.449465,0.011189,0.308185,0.070368,-0.013062,-0.032814,-0.153181,-0.275588,-0.938556,0.006369,0.155666,0.217919,-0.472752,0.396780,-0.155025,0.106689,0.143952,-0.331276,-0.048931,0.574098,0.523607,0.471711,-0.193975,0.202558,-0.265174,-0.180992,0.848742,-0.038088,-0.257502,0.276999,-0.430120,-0.226563,0.175736,-0.330862,-0.955281,-0.090855,0.159905,0.112151,-0.182819,0.385822,-0.388588,-0.059066,-0.280966,-0.163064,-0.207478,-0.374989,0.143293,-0.466794,-0.065184,-0.465343,-0.291115,0.088815,0.081821,-0.350384,0.582121,-1.007343,0.363686,0.411991,0.288430,-0.261232,0.572606,0.376918,0.285313,-0.399094,0.018302,0.399672,-0.072909,-0.078043,0.175918,0.127829,0.121229,-0.116109,-0.299674,0.367779', '35030151', '1308836', '1793491', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10512661', '银翼杀手2049', '剧情', '故事发生在大断电30年后。复制人K（瑞恩·高斯林 Ryan Gosling 饰）是新一代的银翼杀手，在如今的世界里，人类和复制人之间的界限划分的更加明确，复制人从刚一制造出来就被灌输了服务于人类的思想，绝对不被允许产生人类的感情。某日，一具女性复制人的遗骨被挖掘了出来 ，令陆军中尉乔什（罗宾·怀特 Robin Wright 饰）感到震惊的是，这名女性复制人生前不仅怀过孕，还将孩子生了下来，这个孩子的存在将会彻底破坏政府苦心经营的规则和秩序。乔什命令K找出这个孩子，并将他杀死。在一间废弃的农场里，K发现了一些线索，然而，这些线索竟然和他被植入的过去的记忆有着千丝万缕的关联。与此同时，尼安德（杰瑞德·莱托 Jared Leto 饰）和他的手下拉芙（西尔维娅·侯克斯 Sylvia Hoeks 饰）也在寻找着这个孩子的下落。©豆瓣', '瑞恩·高斯林', '丹尼斯·维伦纽瓦', 8.3, 454921, 'tt1856101', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2501864539.jpg', 0.6, 2.2, 16.1, 42.5, 38.6, '0.239150,0.046249,-0.825634,0.604717,-0.413808,-0.169820,0.793841,-0.152767,-0.679318,-0.315578,-0.050738,0.727780,-0.109724,0.108863,0.311869,-0.046081,-0.356694,-0.473527,-0.166019,-0.210648,-0.563177,-0.561109,-0.477766,-0.414728,0.087636,-0.634241,0.681873,-0.033243,-0.470461,0.097671,0.112664,0.224868,-0.288430,0.439672,-0.107769,0.337102,-0.095845,-0.234439,0.027495,0.131384,-0.130938,-0.139005,0.183546,0.180918,-0.179208,0.500465,0.752449,-0.621148,-0.031615,-0.221869,0.378875,-0.149414,-0.116835,0.126212,0.172007,0.072114,-0.078046,0.426764,-0.247101,0.051135,0.369504,-0.124442,-1.041215,-0.090980,0.009080,0.449835,-0.597689,0.519117,-0.139347,0.050640,-0.200084,-0.361516,0.366266,0.234027,0.124958,0.423114,-0.304521,-0.116910,-0.686353,0.010053,0.467956,-0.175537,-0.467418,0.260783,-0.341557,-0.604765,-0.501996,-0.054735,-0.390826,-0.087174,0.427905,0.420212,-0.339001,0.362268,-0.742274,-0.131230,-0.278880,-0.113718,0.002535,-0.437909,-0.041926,-0.483738,-0.194235,-0.219368,-0.506428,0.050843,0.064577,-0.371579,0.966608,-0.760525,0.112107,0.504971,0.527212,-0.540796,0.527520,-0.198439,0.225634,-0.255336,-0.135843,0.342498,0.394113,0.370505,0.199146,0.548658,-0.147093,-0.117046,-0.385831,0.559187', '1793491', '3769423', '24284209', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10519331', '远山恋人', '剧情', '本（伊德瑞斯·艾尔巴 Idris Elba 饰）是一名医术高明的外科医生，深受患者和领导的信赖。业余时间，本喜欢攀山，这是他唯一的，也是最执着的兴趣爱好。某日，本乘坐飞机打算回到工作的城市，一场规模不小的手术在等待着他。和本搭乘同一班飞机的，还有一位名叫艾许莉（凯特·温丝莱特 Kate Winslet 饰）的记者，她迫不及待的想要抵达目的地，因为第二天，将在那里举行她期待已久的婚礼。突然降临的暴风雪打乱了两人的计划，他们准备搭乘的航班取消了。无论如何也一定要准时回城的本和艾许莉决定搭乘私人飞机，哪知道驾驶员飞了一半心脏病突发去世，两人所乘坐的飞机坠毁在了深山老林之中。©豆瓣', '伊德里斯·艾尔巴', '汉尼·阿布-阿萨德', 6, 5316, 'tt2226597', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2462943902.jpg', 2.3, 20.2, 57.7, 15.6, 4.2, '0.325937,0.072315,-1.104413,0.311771,0.002872,-0.077903,0.375655,0.257878,-0.253121,-0.368292,0.336418,0.898625,-0.121203,0.126089,0.781603,-0.046248,-0.596685,-0.416910,-0.027732,-0.325046,-0.436714,-0.705460,-0.015814,-0.280240,0.315436,-0.300888,0.366425,0.166024,-0.050439,0.673347,0.367028,0.235105,0.119981,0.462718,-0.427204,-0.425114,0.030491,-0.089031,-0.088793,0.439673,0.173616,-0.205374,0.034511,-0.060637,0.256987,0.438538,0.551311,-0.079559,-0.226103,-0.030862,0.089584,-0.475620,0.267488,-0.011905,0.395461,-0.145240,-0.111588,0.078881,-0.257454,0.317146,0.095954,-0.109568,-0.569676,-0.091228,-0.198094,-0.197405,-0.689508,0.473093,-0.189817,-0.204990,0.117122,-0.468415,0.407576,0.773017,-0.069560,0.220069,-0.022847,0.047513,-0.671304,0.008544,0.781793,0.139988,0.100825,0.419753,0.048425,-0.573982,-0.068355,-0.085041,-0.395627,-0.045531,0.477757,-0.022725,-0.099948,-0.074161,-0.345382,-0.036347,-0.318315,-0.492649,-0.222310,-0.352081,0.000555,-0.789663,0.357415,-0.258360,-0.093252,0.119547,0.147979,-0.020439,0.701970,-0.902560,0.484728,0.374530,0.366109,-0.436043,0.636274,0.250071,0.343002,-0.210276,-0.013050,-0.018235,-0.028747,0.693845,-0.063468,0.345738,0.148894,-0.118461,-0.538173,0.410859', '1309051', '1302987', '35287558', '2079017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10521712', '她爱上了我的谎', '剧情', '超人气乐团CRUDE PLAY如日中天，虽得益于名制作人高树总一郎（反町隆史 饰）的精心打造，而乐团的影子成员小笠原秋（佐藤健 饰）更是功不可没。秋在出道前是乐团的贝司手，但是他厌烦商业气息极浓的音乐圈和潜规则而选择隐居幕后，与名歌姬茉莉（相武纱季 饰）、高树制作人之间的感情纠葛更令他身心疲惫。偶然的机会，他邂逅了一个相貌平平的女高中生小枝理子（大原樱子 饰）。以谎言为开端，两个人走到一起。秋隐藏着真实的身份，热爱唱歌的理子则无奈在男朋友面前封印歌喉。直到某一天，理子和同学组建的乐团被高树发掘，命运推动她们走向音乐舞台的中央，她和秋之间由谎言维系的爱恋也面临着考验……本片根据青木琴美的同名漫画改编。©豆瓣', '佐藤健', '小泉德宏', 7.3, 19175, 'tt2281309', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2136834419.jpg', 0.9, 6.4, 37.7, 37.9, 17.1, '0.002854,0.053143,-0.510419,0.710683,0.073997,-0.035604,0.409698,0.274660,-0.437580,-0.405940,0.156305,0.546225,-0.095536,0.382086,0.302529,-0.086523,-0.236257,-0.843808,-0.200953,-0.194081,-0.140021,-0.285962,-0.050716,-0.108033,-0.294802,-0.227844,0.936288,0.066792,-0.255722,0.562476,0.481510,0.269164,-0.401517,-0.014296,-0.032377,-0.198941,0.188489,0.057922,-0.310054,0.123836,-0.405424,-0.377319,-0.250969,-0.013620,-0.133008,0.163087,0.772767,-0.199279,0.092694,-0.176010,0.315724,-0.283812,-0.094825,-0.129818,0.427602,0.182299,0.341351,0.306909,-0.269078,-0.015521,-0.006956,-0.335204,-0.765068,0.124507,0.312681,0.313803,-0.324586,0.487838,-0.023384,-0.141016,0.162463,-0.106336,0.161290,-0.065157,0.437275,0.243006,-0.203247,0.209856,-0.139641,0.180430,0.512364,0.197447,-0.096872,0.319331,-0.352575,-0.320956,-0.408753,-0.186068,-0.341396,-0.145070,-0.025681,-0.014779,0.339200,-0.175814,-0.688937,-0.100656,0.126907,0.264963,0.068885,-0.492107,0.105621,-0.742451,-0.149625,-0.348872,-0.199617,0.084143,0.165403,-0.380018,0.944943,-0.797776,0.026836,0.490171,0.206983,-0.148166,0.474498,0.082884,0.008739,-0.358122,-0.334084,0.341832,-0.180692,-0.111221,0.024758,0.457984,-0.204073,-0.072929,-0.607154,0.299339', '3811356', '25880986', '5403927', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10521893', '山之外', '剧情', '影片改编自记者塔蒂亚娜•尼古列斯库•布恩的报告文学。该报告文学讲述了一个在2005年驱魔仪式之后去世的老修女的故事。在影片中，有两个主角，一个叫做阿丽娜，另一个叫做维克琪雅。她们在同一个孤儿院长大。成年之后，维克琪雅觉得修道院是自己心灵的庇护所，于是便去做了一个修女； 而阿丽娜则去了德国。她们已经很久没有联系了，但是她们的命运却因为一桩意外而重新连结到了一起。', '考斯米娜·斯特拉坦', '克里斯蒂安·蒙吉', 7.9, 5570, 'tt2258281', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1717932845.jpg', 0.7, 2.4, 22.4, 51.8, 22.6, '0.545572,-0.079929,-0.639539,0.662719,0.006850,-0.626574,0.964610,0.101606,-0.401188,-0.426252,0.155439,1.083393,-0.081133,0.374317,0.369903,0.266082,-0.523751,-0.694695,0.258843,-0.505805,-0.704163,-0.531035,0.015548,-0.323012,-0.115826,-0.263240,0.373001,-0.093711,0.287609,0.340616,0.517663,0.259729,0.013170,0.271613,-0.216572,0.426705,0.474484,-0.125956,0.003596,0.396488,0.150280,0.041599,-0.295486,0.285642,-0.076711,0.355443,0.593513,-0.259124,-0.017856,-0.116724,0.320321,-0.028800,-0.077008,0.188930,0.361084,-0.092826,0.212692,0.075211,-0.362048,0.140205,-0.057217,-0.031122,-0.670734,0.206248,-0.019617,0.337282,-0.599103,0.468307,0.255866,-0.172549,-0.002137,-0.415075,0.146169,0.558608,0.319068,0.555408,-0.115327,-0.076854,-0.405514,0.196634,0.828113,-0.023381,-0.232334,0.508394,-0.125914,-0.457555,-0.144677,0.185623,-0.539527,0.083400,0.292467,-0.007018,-0.453621,0.267350,-0.795013,-0.194113,-0.340756,-0.187315,-0.047106,-0.456744,-0.006666,-0.589533,-0.279907,-0.158306,-0.298539,0.064304,0.009708,-0.042386,1.059172,-0.818872,0.575480,0.674251,0.017456,-0.425654,0.730130,0.182592,0.456534,-0.057076,0.386261,0.267528,-0.123258,0.400966,0.398384,0.565322,0.012251,-0.105586,-0.510499,0.480113', '30162520', '1292219', '1292720', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10521937', '起名风波', '喜剧', '四十岁的文森即将首次成为父亲，某次在受邀参加姐姐伊丽莎白和姐夫皮埃尔的家庭晚餐时，他遇到了儿时的朋友克劳德。在等待文森那总是迟到的妻子安娜的过程中，大家兴致勃勃的就他将来的父亲生活提问不断，但是当提到即将出生孩子的取名问题时，文森的回答令全家陷入混乱。', '帕特里克·布鲁尔', '亚历山大·德·拉·巴特里耶', 7.8, 6619, 'tt2179121', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1460180611.jpg', 0.6, 2.9, 23.5, 50.9, 22.2, '0.006574,0.232428,-0.625215,0.338032,-0.210634,-0.459268,0.536469,0.161787,-0.633982,-0.489110,0.192966,1.076539,-0.349383,0.782667,0.679096,0.032698,-0.421811,-0.651636,0.036252,0.217306,-0.223211,-0.458121,0.290293,-0.180310,0.031382,-0.407458,0.557679,-0.235551,0.014549,0.381173,-0.090522,0.315484,0.150532,0.602458,-0.221424,0.058942,0.224031,0.168503,-0.476239,0.128190,0.030776,-0.102924,-0.066618,0.093210,0.216265,0.405453,0.730907,-0.276213,-0.173190,-0.040626,0.490156,-0.274341,-0.073085,0.214682,0.209289,0.026527,0.369328,0.081557,-0.061234,-0.154638,-0.245572,-0.378962,-0.567671,0.064580,0.000254,0.089827,-0.409052,0.315182,0.152072,0.141332,0.524981,-0.183198,0.401379,0.788434,0.106685,0.412355,-0.394441,0.028312,-0.211364,0.195072,0.845596,-0.102564,-0.115577,0.357777,-0.138499,-0.356534,0.246736,-0.044998,-0.764682,0.240360,0.029307,0.267229,-0.491985,0.529787,-0.321070,-0.248709,-0.101220,-0.253650,0.385681,-0.510764,-0.373899,-0.596797,0.115894,-0.259755,-0.313393,-0.101633,-0.121531,-0.314472,0.690512,-0.999511,0.518733,0.356093,0.247662,-0.325175,0.718757,0.365366,0.214408,-0.453664,0.014878,0.192041,0.030183,-0.092088,-0.130047,0.091300,0.137831,0.080674,-0.352154,0.708292', '1292720', '1292219', '30345227', '27042738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10522066', '待绽蔷薇', '剧情', '简（德丽·海明威 Dree Hemingway 饰）是一名二十一岁的妙龄少女，心中怀揣着成为演员的梦想，她来到了位于加州的圣费尔南多谷。可是，成为演员哪里是这么简单的事？没过多久，简便和大多数来此打拼的女孩一样，默默无名并且身无分文。在简的生活圈里来往的，大多数是不靠谱的朋友们，而其中最值得信赖的，竟然是她那只名叫斯嘉丽的吉娃娃狗。在老太太桑迪（贝塞德卡·约翰森 Besedka Johnson 饰）家举办的跳蚤市场上，简偶然发现了一个塞着一大捆钞票的老古董，这巨额的财产让囊中羞涩的简无法不在意，她打起了这笔巨款的主意，为此她开始特意的接近桑迪。没想到，简的这一举动彻底的改变了她的生活。©豆瓣', '德丽·海明威', '肖恩·贝克', 7.5, 8811, 'tt2035630', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1902182383.jpg', 0.9, 3.8, 32.8, 44.7, 17.7, '0.516485,0.006735,-0.796428,0.720553,-0.222053,-0.355622,0.682211,-0.053750,-0.537977,-0.409638,-0.072870,0.925749,-0.119273,0.430400,0.206663,0.050871,0.140973,-0.478418,-0.358566,-0.322100,-0.378966,-0.369664,-0.334153,-0.394712,-0.273927,-0.083879,0.227627,0.244195,-0.228631,0.273671,0.709895,0.450342,0.211925,0.272350,-0.456424,0.156135,0.012333,0.180421,0.009388,0.119673,-0.146979,-0.164999,-0.085046,0.349844,0.265377,0.451423,0.552773,-0.201211,-0.093644,0.037847,0.321573,-0.321796,-0.146404,-0.055166,0.234674,-0.002570,0.268218,-0.138878,-0.266305,-0.118108,0.278007,-0.245817,-0.846039,-0.173390,0.253803,0.214145,-0.798824,0.365545,0.031065,0.055333,-0.268765,-0.426689,0.139036,0.212487,0.003174,0.167933,0.164421,0.025608,-0.879405,0.416192,0.780186,0.118456,-0.280193,0.409804,-0.394449,-0.400451,-0.033826,-0.286828,-0.539077,-0.144130,0.362994,-0.053763,0.060212,0.043406,-0.499809,-0.001815,-0.223789,-0.146958,0.185716,-0.519839,-0.229149,-0.335777,-0.124151,-0.707993,-0.502985,0.244588,0.016384,-0.451906,0.909066,-0.866724,0.105650,0.441542,0.045354,-0.416624,0.794484,0.107030,0.155509,-0.134481,-0.134219,0.121400,0.128387,0.218237,0.210637,0.163859,-0.114880,-0.401407,-0.383973,0.707612', '1783461', '1456503', '1306755', '1303112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10527288', '百万巨鳄', '喜剧', '阿毛是一只长八米重二吨的鳄鱼的花名。鳄鱼乐园主光头刘（石兆琪 饰）因没钱给它买肉吃，把鳄鱼阿毛卖了。没想到买阿毛的是开鳄鱼餐厅的赵大嘴（林雪 饰）。餐厅师傅砍杀死阿毛前，它怒了，挣脱了绳索。它跑了！八米长的鳄鱼跑了。阿毛逃窜到茶园，与刚被男朋友（蒲巴甲 饰）飞掉的温燕（大S 饰）狭路相逢。饥肠辘辘的鳄鱼阿毛吞掉了温燕随身携带的皮包。皮包里没它要吃的肉，装的是温燕在意大利做了八年皮鞋攒下的十万欧元，那可是她的命钱啊。失神落魄的温燕去派出所报案，那曾想，负责办案的是史上最不靠谱的警察——王不准（郭涛 饰）！更想不到的是，王不准的儿子王小星（丁嘉力 饰）竟然还是鳄鱼的密友。养鳄鱼的、吃鳄鱼的、抓鳄鱼的还有鳄鱼阿毛混战出一部：2012最让你惊喜的怪兽电影！©豆瓣', '徐熙媛', '林黎胜', 5, 21190, 'tt2354196', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1579831235.jpg', 16.4, 34.4, 37.4, 8.3, 3.6, '0.223719,-0.201715,-0.263593,0.327933,-0.225283,-0.490116,0.798106,0.215334,0.131973,0.117492,0.168912,0.210379,-0.142695,0.082283,-0.298089,-0.078845,0.231785,-0.205743,0.042499,-0.100890,-0.318333,0.049932,-0.482014,-0.096699,0.039051,0.143609,0.214736,-0.213185,-0.169976,0.162365,0.613493,-0.121540,0.231328,0.282935,-0.641382,0.250619,-0.261156,-0.077010,0.386488,0.029594,0.030599,-0.457938,0.167137,0.171139,0.248905,0.408227,0.577310,-0.150980,0.075368,-0.216425,0.229910,-0.115088,-0.092497,-0.054565,0.349592,-0.280823,0.140134,-0.386481,-0.127216,0.017818,0.599427,-0.002091,-0.744019,-0.080989,-0.277444,0.196335,-0.922217,0.221981,-0.365003,0.149324,0.244895,-0.357718,0.260972,0.019774,-0.033823,0.290938,0.173378,0.060658,-0.975282,0.436505,0.345253,-0.385578,0.275518,0.120891,0.023843,-0.681383,0.104722,-0.208646,-0.108762,-0.102188,0.662598,-0.253807,-0.518622,-0.205352,-0.698471,-0.075460,-0.101940,-0.325802,-0.027954,-0.166694,-0.492394,-0.021006,0.118338,-0.636503,-0.057182,0.209929,0.209460,-0.023847,0.514520,-0.377477,-0.120261,0.369973,0.252416,-0.194345,0.834368,-0.307990,-0.159840,0.131816,0.161447,-0.262746,0.290080,0.352470,0.799795,0.650238,0.155799,-0.402518,-0.377703,0.613289', '1301996', '1294037', '1306505', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10533913', '头脑特工队', '喜剧', '可爱的小女孩莱莉（凯特林·迪亚斯 Kaitlyn Dias 配音）出生在明尼苏达州一个平凡的家庭中，从小她在父母的呵护下长大，脑海中保存着无数美好甜蜜的回忆。当然这些记忆还与几个莱莉未曾谋面的伙伴息息相关，他们就是人类的五种主要情绪：乐乐（艾米·波勒 Amy Poehl er 配音）、忧忧（菲利丝·史密斯 Phyllis Smith 配音）、怕怕（比尔·哈德尔 Bill Hader 配音）、厌厌（敏迪·卡灵 Mindy Kaling 配音）和怒怒（刘易斯·布莱克 Lewis Black 配音）。乐乐作为团队的领导，她协同其他伙伴致力于为小主人营造更多美好的珍贵回忆。某天，莱莉随同父母搬到了旧金山，肮脏逼仄的公寓、陌生的校园环境、逐渐失落的友情都让莱莉无所适从，她的负面情绪逐渐累积，内心美好的世界渐次崩塌。为了保护这一切，乐乐只有行动起来……©豆瓣', '艾米·波勒', '彼特·道格特', 8.8, 565327, 'tt2096673', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2266293606.jpg', 0.2, 0.8, 10.7, 37, 51.3, '0.341736,-0.005691,-0.643935,0.400045,-0.073816,-0.505144,0.934580,0.131281,-0.438281,-0.226237,0.002151,0.427735,-0.139180,0.598837,0.065604,0.169637,-0.471489,-0.432074,-0.217687,0.068479,0.139269,-0.344650,-0.393234,-0.285450,-0.094601,-0.554678,0.627310,-0.003216,0.038986,0.340762,-0.017001,-0.001633,-0.272356,0.158643,0.035452,0.066257,0.169935,-0.128290,-0.352711,-0.344512,-0.126671,0.117725,0.009760,0.164168,0.028589,0.083551,0.742095,-0.213111,-0.169554,-0.076421,0.322247,-0.093657,-0.162281,0.022270,-0.130826,0.081444,0.264248,0.007977,-0.230012,0.134768,0.023627,-0.072669,-0.837751,0.038693,0.136780,0.227438,-0.274040,0.417724,0.060446,-0.085738,0.390811,-0.434117,0.028913,0.137817,0.115950,0.625726,-0.340687,0.326705,0.114881,0.312064,0.566293,-0.186449,-0.249534,0.283416,-0.655303,-0.166206,0.024746,-0.040286,-0.777780,-0.124770,0.225858,-0.000246,-0.010249,0.606547,-0.662960,0.184090,-0.097827,-0.231911,-0.117867,-0.453524,-0.047755,-0.487674,-0.385719,-0.242357,-0.205971,-0.364058,0.205617,-0.295500,1.038846,-0.789078,0.320129,0.518565,0.154349,-0.234793,0.159412,0.211102,0.170935,-0.199824,-0.095953,0.527907,-0.237228,0.063215,-0.132876,0.342291,-0.055693,0.306275,-0.467316,0.608559', '26348103', '4181031', '3005387', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10535447', '不是任何人女儿的海媛', '剧情', '渴望有朝一日成为万人瞩目明星的大学生海媛（郑恩彩 饰），她的妈妈即将移民加拿大。母子最后的相处时光，充满喜悦和感伤。平淡而短暂的几个小时后，海媛孑然一身。心情低落的她找来了断断续续交往一年的恋人李成俊（李善均 饰），同时也是海媛所在电影学校的教授兼导演。对于已经成家的李导演，他们的交往从一开始就注定只能藏在黑暗里，永远上不了台面，无论那个男人曾说出怎样刻骨铭心的甜言蜜语。学校里风言风语，女学生与教授的不伦之恋传言甚嚣尘上，他们之间也难免出现矛盾，争吵过后干脆避而不见。如何面对？如何抉择？如何放弃？©豆瓣', '李善均', '洪常秀', 7.1, 7876, 'tt2576522', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1848869380.jpg', 1.1, 6.9, 39.1, 39.8, 13.1, '0.118365,-0.041689,-0.557881,0.378544,0.164753,-0.500431,0.686392,-0.040857,-0.518783,-0.283175,0.076492,0.341902,-0.386695,0.469794,0.102251,-0.319719,-0.436812,-0.692117,0.095437,-0.370047,-0.106320,-0.387446,-0.095591,-0.119851,-0.035156,0.111927,0.687614,0.103955,-0.057403,0.418847,0.551367,0.218637,-0.172097,0.491309,0.088102,-0.178129,0.084483,0.410469,-0.614461,-0.256232,0.222918,-0.182283,-0.238050,-0.210094,-0.057036,0.313994,0.529906,-0.015949,-0.085884,0.190887,0.565487,-0.142400,-0.418466,0.107882,0.306642,0.054646,0.336452,0.135966,-0.219495,-0.283727,-0.260972,0.176679,-0.429691,0.153406,0.093857,0.255572,-0.274710,0.303287,0.187496,-0.080990,0.213729,-0.063832,0.094301,0.311635,0.405755,0.481013,-0.334366,-0.013918,-0.122864,0.353332,1.065805,0.187223,-0.262943,0.166173,-0.091581,-0.452727,0.087790,-0.345834,-0.754219,-0.003487,-0.116793,0.039601,-0.119776,0.424024,-0.279526,0.075608,-0.118958,0.068321,0.409526,-0.631332,0.092226,-0.509946,-0.213693,-0.444336,-0.377468,-0.132282,0.265317,-0.157663,0.982175,-0.875686,0.214702,0.118443,0.407879,-0.458628,0.648589,0.259182,0.137510,-0.240840,0.043155,0.430514,-0.280185,0.154794,0.054984,0.201818,0.030445,0.094571,-0.239989,0.374097', '6963575', '26790961', '25721544', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10535562', '突袭2：暴徒', '剧情', '罪恶横生的雅加达，警察和恶棍沆瀣一气，不分黑白。为了捣毁这根充满恶臭的利益链条，布纳瓦（Cok Simbara 饰）授意刚刚经历了一场血腥恶战的拉玛（伊科·乌艾斯 Iko Uwais 饰）潜入黑帮大佬班坤（Tio Pakusodewo 饰）的巢穴。此时班坤的儿子尤科（Arifin Putra 饰）正在监狱服刑，化名尤达的拉玛“获罪”入狱，并在连翻拼杀中博得尤科的信任。两年后，拉玛出狱加入班坤的组织，此时班坤与日本黑道后藤（远藤宪一 饰）相互勾结，城市另一边又有新崛起的贝乔（Alex Abbad 饰）一派野心勃勃。为了取得霸主地位，暴徒们在城市接连点燃战火，而心高气傲的尤科也试图建立超越父亲的霸业。血与火的修罗场，拉玛披荆斩棘……©豆瓣', '伊科·乌艾斯', '加雷斯·埃文斯', 8.1, 64478, 'tt2265171', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2178368429.jpg', 0.6, 2.7, 20.2, 45, 31.5, '-0.122310,-0.014780,-0.427952,0.460447,0.160840,-0.101654,0.471639,0.164642,-0.615918,-0.184377,0.197419,0.574285,-0.251009,-0.072304,0.274169,-0.389950,-0.210149,-0.764872,-0.155871,-0.116952,-0.054489,-0.398825,-0.531760,-0.355890,-0.047591,-0.151531,0.719945,0.323155,-0.240535,0.515805,0.440079,0.518974,-0.309186,0.105956,-0.173193,-0.247035,0.008503,0.074643,-0.578091,-0.069047,-0.336847,-0.144561,-0.178602,-0.158582,-0.080907,0.283844,0.479917,-0.370278,0.416095,-0.618837,0.237424,-0.231484,-0.159344,0.052871,0.590609,-0.056396,0.016765,0.432765,-0.059593,-0.196775,0.140454,-0.271218,-0.705299,-0.055476,0.290982,0.179469,-0.367060,0.597008,-0.160404,0.118217,0.130656,0.087296,0.052014,0.527844,0.265948,0.335449,0.061828,-0.040562,-0.663410,0.063649,0.637612,-0.375919,0.071204,0.011606,-0.021251,-0.349174,-0.053684,-0.565562,-0.289156,-0.295125,0.344064,-0.189154,0.139878,0.549539,-0.768888,-0.023268,-0.251072,-0.158695,0.417948,-0.103050,-0.181822,-0.645985,-0.549881,-0.287316,-0.061526,0.198291,0.021261,-0.046655,0.574386,-0.780621,0.068636,0.179575,0.234928,-0.432115,0.400272,0.130043,0.121003,-0.322293,-0.422148,0.462070,0.488123,0.382486,0.032930,0.009867,-0.322819,-0.439024,-0.184477,0.138475', '26615753', '5308201', '1308837', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10535568', '阿黛尔的生活', '剧情', '故事主角是15岁女孩阿黛尔（阿黛尔·艾克萨勒霍布洛斯 Adèle Exarchopoulos 饰），她有一个帅气的同学男友托马斯（热雷米·拉厄尔特 Jeremie Laheurte 饰），但托马斯并没能走进她的心。她在街头意外遇到一个美丽的蓝发女孩艾玛（蕾雅·赛杜 Léa Seydoux 饰）后，第一次体验到小鹿乱撞般的怦然心动。而当某晚阿黛尔忐忑不安的走进一家同志酒吧，发现艾玛就在那儿等着她呢。女孩们的彼此靠近让阿黛尔的青春期变得复杂起来…...《阿黛尔的生活》改编自法国女作家朱莉·马洛的情欲漫画《蓝色是最温暖的颜色》（即英文片名），讲述了女孩阿黛尔一段如火如荼的同性爱情。3个小时的片长长而不闷，充满各种情趣元素，而在性爱内容上又惊人的大胆。影片最可贵之处，是没有将同性恋做为热点话题加以投机，而是以同性之爱作为承载，寄托人类最美好也最伤感的初恋情怀。主角从发现自己的性取向，到一步步找到真爱，又一步步失去爱人，整个过程就如繁花盛放又归于荼蘼，让观众看得如痴如醉。导演阿布戴·柯西胥出生于突尼斯，曾三次入围威尼斯金狮奖，其中《谷子和鲻鱼》获得了评委会大奖。他热衷于表现法国外裔青少年的生活和对身份认同的自我寻找，是一位一直维持着较高水准的创作型导演。2013年是他首次入围戛纳。《阿黛尔的生活》获得第66届戛纳电影节金棕榈大奖和影评人费比西奖。', '阿黛尔·艾克萨勒霍布洛斯', '阿布戴·柯西胥', 8.4, 236942, 'tt2278871', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162563238.jpg', 0.3, 1.3, 15.1, 44.5, 38.8, '0.102237,-0.153255,-0.487514,0.670467,0.008012,-0.259798,0.841902,0.010657,-0.320608,-0.079801,0.119907,0.785293,-0.423517,0.249488,0.413180,0.082209,-0.362539,-0.610143,0.106027,-0.088635,-0.060261,-0.251600,-0.273923,0.125366,-0.217978,-0.407770,0.657918,-0.087009,-0.194865,0.403366,0.416720,0.158136,0.102379,0.228414,-0.200337,0.010354,0.175268,0.195986,-0.211584,0.289617,0.037987,-0.232770,-0.380749,0.174713,-0.104070,0.144434,0.779721,-0.277659,-0.116424,0.051757,0.506581,-0.321106,-0.159394,-0.116749,0.027110,-0.130692,0.291493,-0.035718,-0.023109,0.108529,0.172540,-0.190536,-0.523370,0.117638,0.098065,0.233363,-0.349385,0.293058,0.048596,-0.005377,0.243920,-0.310015,0.017041,0.033791,0.156035,0.440947,-0.055705,-0.067831,-0.365488,0.396341,0.476513,0.139696,-0.427159,0.681024,-0.515327,-0.647629,-0.001000,-0.154729,-0.595447,-0.022122,0.254669,0.006027,0.024590,0.133802,-0.559885,0.119697,0.039500,-0.316462,0.116856,-0.365005,-0.055608,-0.588263,-0.217310,-0.423532,-0.202338,-0.083474,0.067645,-0.474955,0.805701,-0.733417,0.226176,0.468874,0.038726,-0.336318,0.753760,0.168176,-0.145416,-0.144678,-0.191646,0.451119,-0.110370,-0.094995,-0.169202,0.445541,-0.204324,-0.093344,-0.520415,0.567974', '3811356', '5416009', '30401849', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10536969', '记忆提取', '剧情', '汤姆（萨沙·罗伊茨 Sasha Roiz 饰）是一名拥有超高智商的科学家，发明出了一种能够提取他人记忆的技术。警方将这门技术应用于审讯犯人，在各方的协助之下，汤姆进入了一位名叫安东尼（多米尼克·博加特 Dominic Bogart 饰）的男人的记忆之中，他被指控犯有一级谋杀，汤姆的任务是找到能够为他定罪的证据。哪知道在实验的过程中发生了意外，汤姆竟然无法从安东尼的记忆中离开了，就这样，他被困长达四年之久。在这漫长的四年里，汤姆和安东尼渐渐熟悉起来，后者最终同意将汤姆放回现实之中，但有一个交换条件，那就是汤姆必须帮助他调查案件的真相。©豆瓣', '萨沙·罗伊茨', '尼尔·帕尼瑞', 7.1, 7986, 'tt1757746', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2042152600.jpg', 1.4, 7, 39, 39.1, 13.4, '0.333538,0.375991,-0.549587,0.583879,-0.429143,-0.272699,0.528209,-0.257439,-0.670539,-0.570538,0.066956,0.690966,-0.082560,0.118629,0.022876,-0.122272,-0.319720,-0.765117,-0.071351,-0.476683,-0.394539,-0.873525,-0.416241,-0.281289,-0.108277,-0.343462,0.627965,0.184063,-0.293933,0.029231,0.172519,0.531851,0.037026,0.329361,-0.167929,0.029450,0.308949,-0.276691,-0.191671,0.420436,0.231766,-0.424462,0.069252,0.106315,0.061484,0.255433,0.664213,-0.336806,-0.151068,0.134296,0.474294,-0.267671,-0.277760,0.263803,0.195046,0.186919,-0.133410,0.405631,-0.338816,0.044391,0.082875,-0.023251,-1.068126,-0.235206,-0.183173,0.307153,-0.519838,0.069823,-0.210517,0.072649,-0.043198,-0.351689,0.217807,0.279680,0.277810,0.356447,-0.163238,-0.029363,-0.600385,0.090774,0.544368,-0.268957,-0.287753,0.317300,-0.322585,-0.797003,-0.318154,-0.202358,-0.141090,0.025754,0.457042,0.160782,-0.244451,0.339327,-0.496679,-0.071173,-0.458999,-0.078509,-0.300033,-0.190355,-0.021365,-0.504751,-0.151789,-0.222561,-0.380998,-0.043286,0.029218,-0.633707,0.639361,-0.757827,0.209627,0.556410,0.232472,-0.281399,0.544007,0.115514,0.256521,-0.194337,0.080728,0.225389,0.159410,0.279824,0.153025,0.481528,0.292665,-0.265055,-0.676615,0.480466', '1793491', '26848640', '3785918', '3006783');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10537853', '万箭穿心', '剧情', '90年代的武汉，一个普通家庭里丈夫马学武（焦刚 饰）是一家国企的厂办主任，妻子李宝莉（颜丙燕 饰）是汉正街的一名小贩，二人还有一个儿子小宝（李现 饰）。一次企业分房让这个家庭住进了新房，岂料从搬家那天起一系列让人始料未及的变故接踵而来：丈夫马学武提出离婚、妻子发现丈夫出轨、无家可归 的婆婆要入住新家，终于马学武在一系列打击下走向了自杀之路。宝莉的好友小景（赵倩 饰）把一切厄运归结于新房的风水不好，称之“万箭穿心”，个性倔强的李宝莉不愿妥协，决意撑起这个家……电影《万箭穿心》根据武汉籍著名作家方方的同名小说改编，入围第25届东京国际电影节主竞赛单元。©豆瓣', '颜丙燕', '王竞', 8.6, 219229, 'tt2513344', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1759644668.jpg', 0.3, 0.8, 9.8, 44.8, 44.3, '0.108623,-0.184898,-0.554609,0.541905,-0.075940,-0.527848,0.473450,0.318335,-0.445942,-0.478418,0.341850,0.821900,-0.077063,0.369645,0.223146,-0.056226,0.132184,-0.459158,-0.190556,-0.044203,-0.108212,-0.299680,0.052899,-0.007396,-0.172413,0.107486,0.480878,-0.027110,-0.087725,0.410894,0.582353,0.215965,-0.101034,-0.030190,-0.054919,0.233508,-0.081444,0.165441,-0.491500,0.211743,-0.064055,0.062315,-0.128558,0.013893,0.031398,0.189402,0.681919,-0.097687,-0.202424,-0.328448,0.827990,-0.122719,-0.302045,0.124511,0.358030,0.094374,0.131646,0.244519,-0.353801,0.076222,0.177491,0.040057,-0.317935,-0.103351,0.264823,-0.023921,-0.718105,0.227289,-0.110354,0.104140,-0.038758,-0.547244,0.245177,0.306904,0.285023,0.596557,-0.172091,0.227277,-0.334466,0.236163,0.608568,0.036341,0.075721,0.242808,-0.147001,-0.128145,0.392262,-0.163165,-0.604589,0.215590,0.284132,-0.193094,-0.179523,0.106934,-0.327869,-0.262071,-0.205892,-0.008295,0.068223,-0.226258,0.129721,-0.391796,0.086168,0.053705,-0.050435,0.142300,0.178749,-0.224630,0.618223,-0.548331,0.066551,0.312170,0.243450,-0.639392,0.483201,0.074471,0.330235,-0.184080,0.309104,-0.093385,-0.037787,0.303243,-0.281943,0.405066,-0.170985,-0.303532,-0.288454,0.335807', '24879820', '30353869', '2080130', '1309226');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10537949', '恶之教典', '惊悚', '私立晨光学院町田高中，群体作弊事件严重，校园暴力引发胡搅蛮缠的家长与教师的连锁冲突，体育教师柴原彻郎（山田孝之 饰）和美术教师久米刚毅（平岳大 饰）的不端行为又令这一神圣职业蒙羞。在这片无序的混乱中，二年4班班主任莲实圣司（伊藤英明 饰）继续他那完美纯然的教师神话。举止优雅，谦和可亲，天使一般的外表下竟是一颗冷冰冰的恶魔之心。他潜心经营，布下一个又一个不易察觉的圈套，悄无声息抹除那些威胁他存在的人们。物理教师钓井（吹越满 饰）暗中调查莲实的过去和背景，并与他的学生圭介（染谷将太 饰）等人尝试揭穿莲实的真面目，此举全引来连番血腥杀戮。充满欢乐的校园祭前夜，血流成河……本片根据作家贵志祐介的同名原著改编。©豆瓣', '伊藤英明', '三池崇史', 7.1, 29440, 'tt2294473', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1636939310.jpg', 1.7, 7, 39.6, 38.2, 13.5, '0.313671,0.011289,-0.275324,0.624005,-0.073651,0.023556,0.723888,0.183448,-0.296374,-0.359166,0.267425,0.573917,-0.239639,0.140802,0.382732,-0.307477,-0.163056,-0.501305,-0.221448,-0.050063,0.032449,-0.205804,-0.146723,0.015374,-0.113686,-0.271804,0.725861,0.137195,-0.314639,0.619698,0.142771,0.378862,-0.143674,0.115666,0.101972,-0.129802,-0.115197,0.131471,-0.043578,-0.052663,-0.234997,-0.285941,-0.214698,0.271362,-0.200565,0.337593,0.747916,-0.182786,-0.213621,-0.348528,0.736670,-0.264319,-0.192318,0.354815,0.517381,-0.108899,-0.034549,0.251723,0.070176,0.089169,0.024752,-0.127294,-0.764140,-0.231030,0.179912,0.100039,-0.094452,0.540066,0.253286,-0.089033,0.050244,0.063997,-0.151738,-0.211424,0.301291,0.183866,-0.119839,0.116598,0.003025,0.306735,0.202232,-0.129387,-0.324028,0.205127,-0.411747,-0.478102,-0.140034,-0.291918,-0.515759,-0.051246,0.131691,-0.093641,0.144619,0.243331,-0.656170,-0.208457,-0.116664,0.097932,-0.018317,-0.207080,-0.097878,-0.662795,-0.053068,-0.383100,-0.409124,-0.043307,0.279284,-0.008724,0.612411,-0.722888,-0.015812,0.428921,0.073575,-0.334358,0.317811,0.169483,0.017554,-0.099216,-0.464276,0.106587,0.377466,0.596437,-0.186584,0.725939,0.087834,-0.133576,-0.237063,0.274167', '3811356', '10467125', '25880986', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10539139', 'HOLD住爱', '喜剧', '80后小夫妻周静（杨幂 饰）和陶小磊（刘恺威 饰）闪电离婚后，意外中奖获得三亚蜜月行的机会，二人互不相让，约好到三亚后各自玩耍。一夜宿醉后，陶小磊发现周静遭到绑架，绑匪向他索要巨额赎金。为筹赎金，陶晓磊想尽办法，结果在赌局中输的只剩一条内裤。可实际上，周静似乎并未被绑架，而是迷失在一片热带丛林中，这到底是什么原因？当所有的一切都在向着未知方向发展时，陶晓磊和周静真的被绑架了！意外重遇的两人发现，这一切仿佛都被人掌控，种种蹊跷背后还隐藏着更大的阴谋……这一刻，生与死，亲情和爱情，都在戏谑中面临着最严峻、最真实的考验。©豆瓣', '杨幂', '张琦', 3.6, 24577, 'tt2457206', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1669766073.jpg', 51.5, 28.4, 13.6, 2.5, 3.9, '0.233410,-0.084740,-0.972547,0.365472,0.112141,-0.128214,0.843589,-0.118958,-0.505793,-0.189892,0.168815,0.467530,-0.313535,0.064421,0.387226,-0.093618,-0.386755,-0.803792,-0.216117,-0.334924,-0.562513,-0.550690,-0.209115,0.157182,0.013750,0.055130,0.367060,0.392375,-0.183876,0.479099,0.445689,0.055213,-0.411773,0.708896,-0.058883,0.178354,0.069123,0.336215,-0.288389,0.171779,0.182980,-0.277069,-0.319433,0.355645,-0.169991,0.533220,0.671766,-0.425642,-0.296653,-0.087312,0.154629,-0.354829,-0.170541,0.266756,0.094997,0.005755,0.448748,0.226557,-0.231661,0.087956,0.270516,-0.064538,-0.735837,-0.007154,-0.054279,0.178664,-0.428717,0.404333,0.196279,-0.115161,0.275858,-0.308770,0.300176,0.662597,0.407909,0.266991,-0.438855,-0.145624,-0.656644,0.030430,0.727441,-0.075145,-0.007335,0.530022,0.081294,-0.366319,-0.057015,0.035841,-0.288173,0.186566,0.520267,0.365331,-0.191322,0.268124,-0.534011,0.057300,0.006360,-0.179305,-0.295226,-0.653896,-0.125610,-0.451122,-0.271615,-0.347224,-0.300757,0.442217,0.063495,-0.237050,0.175614,-0.525859,0.247122,0.429466,0.360456,-0.404408,0.447124,0.101778,0.146216,-0.307985,-0.215526,-0.016338,0.153540,0.238660,0.161645,0.116216,-0.005416,-0.032450,-0.411165,0.362642', '1947080', '3011051', '25839662', '10733357');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10540066', '大上海', '剧情', '本是水果店小伙计的成大器（黄晓明 饰），在上海投向权倾一时的巡捕房探长洪寿亭（洪金宝 饰）旗下，任职赌场打手，被洪寿亭的妻子凌沪生（袁莉 饰）慧眼赏识，造就大器迅速出人头地。成大器颇具江湖手腕，不仅敢打敢拼，还擅于各方谈判，愿意利益共享，往往能化干戈为玉帛，令他终于成为 上海一代枭雄之首。成大器少年得志，交上了上海第一美人“溢春园阿宝”（莫小棋 饰），阿宝对王公巨贾都不假辞色，但对大器却一往情深，可惜她发现了无论大器如何疼她宠她，她在大器的心目中永远都只能是第二位，第一位始终是青梅竹马、音讯全无的叶知秋（袁泉 饰）。多年后，人到中年的成大器（周润发 饰），已是一方之雄，声誉与地位已超越了师父洪寿亭。在上海几乎已无人匹敌，但外敌蠢动的野心与霸道，成为他的最大难题。此时，当年救他一命的茅载（吴镇宇 饰）已成为大特务头子，野心勃勃，以权谋私，令成大器不得不计划好“杀出一条血路”。而就在这时，他竟重遇了多年不见的叶知秋，同时发现原来她已作人妇……', '周润发', '王晶', 6.7, 86207, 'tt2458314', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1753617325.jpg', 2.7, 11.3, 45.4, 30.1, 10.5, '-0.242057,0.164444,-0.628452,0.395443,-0.060396,-0.258568,0.163550,0.166819,-0.699543,-0.141196,0.242437,0.754240,-0.007361,0.095166,0.061558,-0.058850,0.278531,-0.756075,0.012569,-0.136705,0.095099,-0.195055,-0.475333,0.198063,-0.258799,-0.123604,0.681527,0.236311,-0.104228,0.319681,0.370165,0.057319,0.020048,0.428963,-0.354470,-0.152608,-0.007719,0.137546,-0.404500,-0.046384,-0.247782,-0.280062,-0.269099,0.159852,-0.221460,0.242352,0.180954,-0.148372,-0.083107,-0.003177,0.375196,-0.296559,-0.043762,0.005150,0.236234,-0.134378,0.222105,0.326038,-0.116290,-0.170025,0.124451,0.034625,-0.724708,-0.138231,0.248374,-0.081474,-0.512465,0.349843,-0.151579,-0.269667,-0.186639,-0.143898,0.144784,0.105210,0.057672,0.047023,-0.202146,0.133023,-0.667573,0.236152,0.447272,0.182844,-0.299168,0.104357,0.242984,-0.508565,0.166727,-0.707478,-0.287204,-0.204272,0.195563,0.136461,0.065872,0.218706,-0.089928,0.035640,-0.277302,0.318321,0.213028,-0.362690,0.157585,-0.166110,-0.374279,-0.523329,-0.277943,0.245569,0.251927,-0.337717,0.782290,-0.733927,-0.056284,0.199891,-0.009816,-0.690429,0.663856,0.279807,0.185179,-0.134163,-0.342480,0.219855,0.087826,0.084324,0.055471,0.062654,-0.260075,-0.394607,-0.357218,0.177839', '4301278', '1438924', '1877596', '3319776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10543906', '亨利四世：第二部分', '剧情', 'BBC2历史电视电影系列《空王冠》（The Hollow Crown）4部经典莎士比亚作品的新演绎，分别是：《理查二世》（Richard II）、《亨利四世：第一部》（Henry IV, Part 1）、《亨利四世：第二部》（Henry IV, Part 2）和《亨利五 世》（Henry V）。在2012年伦敦奥运会期间，为了向全世界展现英国文化，这四部电视电影将作为伦敦文化奥运的重点推荐剧目向全世界推行，在2012年6月播出。夺取理查二世权势的亨利四世，将由奥斯卡影帝杰瑞米·艾恩斯 Jeremy Irons饰演，将由《丑闻纪事》的导演理查德·艾尔掌镜，在《复仇者联盟》中雷神弟弟“洛基”汤姆·希德勒斯顿 Tom Hiddleston将饰演Prince Hal，西蒙·拉塞尔·比尔 Simon Russell Beale饰演约翰·福斯塔夫爵士，艾伦·阿姆斯特朗 Alun Armstrong饰演诺森伯兰伯爵。《亨利四世》展现了英国中世纪时期迷人的历史，并将演绎出近年来最野心勃勃的一部莎士比亚改编作品。《亨利四世》是莎士比亚历史剧中最成功、最受欢迎的一部，被看成莎士比亚历史剧的代表作。这部作品的主要内容是反映亨利四世和他的王子们与反叛的诸侯贵族进行殊死斗争的过程。莎士比亚突破传统历史剧多条线索交织发展的网状结构，采用了两条线索平行发展的结构——以亨利四世为代表的宫廷生活线索和以福斯塔夫为代表的市井生活线索。', '杰瑞米·艾恩斯', '理查德·艾尔', 8.6, 8516, 'tt2120772', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2096732226.jpg', 0.2, 0.6, 11.1, 43.7, 44.5, '0.107780,-0.087690,-0.409988,1.062101,0.563806,-0.045647,0.459561,0.040236,-0.327759,-0.351079,0.169227,1.000910,-0.456126,-0.216043,0.387541,-0.125460,-0.649289,-0.795867,-0.094380,-0.044765,0.196605,-0.410327,-0.301819,-0.209050,-0.166643,-0.578765,1.052477,-0.003096,-0.369011,0.159939,0.413374,0.373149,0.038894,-0.172314,0.006484,0.027277,0.216927,-0.303582,-0.478240,0.538686,0.069466,-0.176839,-0.207647,0.048157,-0.120550,0.146733,0.644469,-0.373819,0.406756,-0.063905,0.835982,-0.218662,-0.160418,-0.033001,0.257736,0.133802,0.056059,0.681016,0.122253,0.042966,-0.176884,-0.548696,-1.025324,-0.282994,0.179839,0.321501,-0.442440,0.501300,-0.423443,-0.004853,0.107969,-0.285160,0.379012,0.254550,0.566876,0.350818,0.081773,0.182964,-0.377120,0.567095,0.161590,0.052441,-0.470680,0.417169,-0.194653,-0.497661,-0.260052,-0.339963,-0.373701,0.122272,0.365152,-0.301290,0.240880,0.511328,-0.747098,-0.193430,-0.102463,-0.568698,0.379326,-0.347788,0.082626,-0.984760,-0.295739,-0.234514,0.288964,-0.539146,0.108701,-0.477065,0.952372,-0.321357,0.039518,0.357082,0.220461,-0.304975,0.886163,0.070076,0.088172,-0.383424,-0.152211,0.437812,0.117235,-0.097502,-0.171949,0.254594,0.140501,-0.504602,-0.435154,0.632639', '22265121', '10441064', '3318306', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10543907', '亨利五世', '剧情', 'BBC2历史电视电影系列《空王冠》（The Hollow Crown）4部经典莎士比亚作品的新演绎，分别是：《理查二世》Richard II、《亨利四世：第一部》Henry IV, Part 1、《亨利四世：第二部》Henry IV, Part 2和《亨利五世》Henry V。在2012年伦敦奥运会期间，为了向全世界展现英国文化，这四部电视电影将作为伦敦文化奥运的重点推荐剧目向全世界推行，在2012年6月播出。《亨利五世》是该系列的最后一部，也是莎士比亚被翻拍的作品中绝不容小觑的一部。汤姆·希德勒斯顿 Tom Hiddleston将登上王位，饰演亨利五世。而为这部掌镜的则是非常著名舞台剧导演Thea Sharrock。在《亨利五世》中，年轻的王子成长为成熟男人，致力于征服法国。莎士比亚基于英格兰亨利五世国王生平，于1599年创作了这部著名历史剧，着重描写百年战争期间的阿金库尔战役。年轻的亨利五世长于谋略，善于用兵，深得部属爱戴。由于不甘法国王子的侮辱，他出兵法国，远征艾吉宫战场。凭着过人的勇气，他率领王公贵族及市井小民在大战中击溃法军，逼法王签下和约并娶得法国公主凯萨琳为妻，成为法国王位继承人。', '汤姆·希德勒斯顿', '西娅·夏罗克', 8.7, 10222, 'tt2150275', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2096735303.jpg', 0.4, 0.8, 10.4, 38.3, 50.1, '-0.195349,0.143326,-0.624628,0.997362,0.402707,-0.311586,0.223439,-0.143765,-0.312005,-0.393452,0.248635,0.935846,-0.323764,-0.129199,0.567422,-0.059755,-0.312619,-0.724918,-0.164165,-0.025882,0.168233,-0.256119,-0.345280,-0.215741,-0.364280,-0.550852,0.999545,0.047786,-0.204454,0.237250,0.393305,0.364951,0.392885,-0.012504,0.077743,0.063123,0.057405,-0.408797,-0.482641,0.489732,-0.001192,-0.289294,-0.354752,-0.030355,-0.016186,0.067527,0.457601,-0.373645,0.385567,-0.240131,0.742547,-0.186441,-0.166866,0.022868,0.223561,0.201371,0.158018,0.693810,0.144108,0.035276,-0.233548,-0.333449,-0.684311,-0.102306,0.200175,0.041185,-0.548577,0.556213,-0.596631,0.015675,0.092833,-0.215784,0.149960,0.206624,0.420373,0.580066,0.175701,0.217873,-0.341681,0.632427,0.305060,0.183583,-0.445601,0.025717,0.024195,-0.460987,0.147638,-0.496393,-0.448721,0.286165,0.290805,-0.366084,0.360759,0.494821,-0.466060,-0.071410,-0.276256,-0.322302,0.403421,-0.412661,0.081052,-0.866838,-0.177442,-0.317334,0.317807,-0.399566,0.311295,-0.369476,0.934955,-0.355320,0.027587,0.322679,0.382979,-0.260344,0.983178,0.229795,-0.120299,-0.117083,-0.184287,0.638745,-0.060097,-0.235498,-0.317660,0.112802,0.144692,-0.511804,-0.340126,0.593217', '22265121', '1870681', '10543906', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10545939', '黄金时代', '剧情', '20世纪30年代，20岁的张乃莹（汤唯 饰）逃婚求学，却惨遭抛弃。投靠未婚夫汪恩甲（袁文康 饰）后的张乃莹依然躲不开被抛弃的命运，好在遇到了在报社工作的进步青年萧军（冯绍峰 饰），两人相知相爱。通过萧军张乃莹认识了女编辑白朗（田原 饰）、罗峰（祖峰 饰）夫妻以及聂绀弩（王千源 饰）等文学作家，改名“萧红”后的她得到了鲁迅（王志文 饰）、许广平（丁嘉丽 饰）夫妇的首肯，随后又结识了了胡风（冯雷 饰）、梅志（袁泉 饰）夫妇、蒋锡金（张译 饰）、丁玲（郝蕾 饰）、端木蕻良（朱亚文 饰）等人，在同时代作家的互相鼓励之下，虽然战事不断、颠沛流离，萧红却逐步走向了创作的“黄金时代”。©豆瓣', '汤唯', '许鞍华', 7.4, 175502, 'tt3696086', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167320927.jpg', 1.4, 5.6, 33.8, 42.4, 16.8, '0.087737,0.044832,-0.358525,0.402756,0.312035,-0.439937,0.480988,0.460482,-0.403143,-0.143433,0.291187,0.562170,-0.218176,0.164567,0.201823,-0.209532,-0.323273,-0.696003,0.160892,-0.098707,-0.093305,-0.289451,-0.158668,0.087466,-0.214483,-0.154138,0.545354,0.090074,-0.043088,0.775776,0.397360,0.192894,-0.165279,0.385115,-0.123985,0.404905,0.324822,0.132744,-0.449644,0.088005,-0.137655,-0.290124,-0.015838,-0.144594,-0.229424,0.227027,0.646628,-0.106692,0.077626,-0.075919,0.404830,0.093260,-0.069307,0.118794,0.279695,0.033358,0.409360,0.392867,-0.176373,0.100707,0.101845,0.130813,-0.239488,0.135827,0.470088,0.259168,-0.669034,0.566201,-0.171921,0.052939,-0.026615,-0.250777,0.063669,0.390609,0.382702,0.324326,-0.152525,0.111679,-0.192775,0.725224,0.239062,0.020768,0.043510,0.390706,-0.096201,-0.454670,-0.211554,0.129957,-0.540028,-0.109546,0.450815,0.014813,0.030618,-0.053938,-0.530874,-0.295339,-0.054870,0.335629,0.157828,-0.336987,-0.093174,-0.616586,-0.267680,-0.582659,-0.234787,0.185147,0.089278,-0.337267,0.936890,-0.537433,0.087266,-0.027802,0.230488,-0.464303,0.511090,0.082678,-0.050519,-0.268009,0.235220,0.458491,-0.151976,0.116408,0.139925,0.385375,-0.141305,-0.249731,-0.141716,0.153781', '3811356', '1908036', '25922902', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10546436', '第一滴血5：最后的血', '动作', '西尔维斯特·史泰龙回归[第一滴血5]，并有望执导。除主演外，据悉史泰龙将操刀剧本，故事围绕兰博为营救朋友之女与墨西哥毒枭展开殊死搏斗展开。制片艾威·勒纳([敢死队]系列)。该系列首部于1982年上映，2008年史泰龙曾自导自演[第一滴血4]。[第一滴血5]将在本届戛纳电影节预售，9月开拍。', '西尔维斯特·史泰龙', '阿德里安·格鲁伯格', 7.6, 47094, 'tt1206885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2564519086.jpg', 1, 4.6, 31.3, 41.2, 22, '-0.411192,-0.424689,-0.484848,0.237514,0.979942,-0.102357,0.064504,-0.544766,-0.269210,-0.329417,-0.013547,1.059120,-1.140809,-0.224515,0.699475,-0.187108,-0.159210,-0.836685,-0.307675,-0.443181,0.513209,-0.409735,-0.592089,0.316198,0.034858,-0.282585,1.290327,-0.208945,0.191029,0.551318,0.909526,-0.166080,-0.219453,-0.065070,0.321122,-0.063054,0.036880,-0.356255,-1.034344,0.542463,-0.228152,-0.275321,-0.003013,-0.309866,0.222919,0.191081,0.607669,-0.603760,0.516612,-0.276745,0.669725,-0.537045,-0.288524,-0.208547,0.087243,0.420486,0.252780,0.497003,-0.041864,-0.018726,-0.267316,-1.064030,-0.456428,0.052509,0.354956,0.191610,-0.738322,0.001673,-0.510736,0.578260,-0.002927,-0.265185,0.120153,0.404767,0.427170,0.264843,0.112215,-0.024588,-0.061129,0.894304,0.252731,0.066587,0.171780,0.219895,0.831966,-0.561137,-0.256120,-0.273515,-0.188280,0.376631,0.095595,0.262108,0.092477,0.104750,-0.258116,-0.307738,-0.151202,-0.615275,0.242110,-0.105126,-0.011263,-1.261431,0.168942,0.434858,0.482252,-0.324657,0.416400,-0.477677,0.516679,-0.655788,0.340333,0.072078,0.353666,-0.202957,0.543981,0.479740,-0.076466,-0.320514,-0.215149,0.457234,0.097136,-0.064215,0.059331,0.096320,-0.266526,-0.280097,-0.245717,0.328030', '30397916', '3275168', '26990609', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10546666', '龙虎少年队2', '喜剧', '故事紧接着上一部继续发展。延科（查宁·塔图姆 Channing Tatum 饰）和施密特（乔纳·希尔 Jonah Hill 饰）好不容易从高中“顺利毕业”，等待着他们的，却是又一轮卧底行动，这一次，他们要挑战的对象是“大学”。和高中相比，大学里人际关系的复杂程度和课业难度都要更上一层楼，这一次，兄弟两人能够顺利完成任务吗？在学园中，延科加入了校足球队，结识了一帮志同道合的好友，与此同时，施密特选择就读艺术系，与古灵精怪的玛雅（安珀·史蒂芬斯 Amber Stevens 饰）发生了一段浪漫轶事。然而，丰富精彩的大学生活令密不可分的延科和施密特之间产生了裂痕，这裂痕之巨大很可能导致患难与共的两人最终分道扬镳。©豆瓣', '乔纳·希尔', '菲尔·罗德', 6.9, 24717, 'tt2294449', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177364785.jpg', 1.1, 7.8, 47.6, 32.5, 10.9, '0.420776,-0.180595,-0.767896,0.878739,0.161420,-0.316883,0.609535,0.010726,-0.444520,-0.146936,-0.124995,0.931903,-0.544646,0.328543,0.245198,-0.436595,-0.190650,-0.894401,0.268344,-0.586980,-0.388545,-0.554855,-0.305860,-0.030031,-0.074966,-0.323871,0.701497,0.195970,-0.107307,0.858977,0.205087,0.223473,0.004499,0.248249,-0.047905,-0.076962,0.255908,0.452633,-0.311201,-0.009335,0.179245,-0.031688,-0.082281,0.009643,0.431408,0.249973,0.710802,-0.004776,-0.001053,0.035748,0.335302,-0.177518,-0.105658,0.164256,0.441338,0.146107,0.209143,0.472494,-0.082259,-0.077366,-0.145498,-0.570478,-0.655642,-0.054991,0.117629,0.185964,-0.465504,0.605029,0.076195,-0.201893,0.163635,-0.130788,-0.016774,0.794920,0.686434,0.406749,-0.044786,-0.003250,-0.183537,0.210519,0.944233,-0.092954,-0.430303,0.307402,-0.159567,-0.455417,-0.149559,-0.179385,-0.287568,0.142526,0.377622,0.091419,-0.084660,0.394596,-0.658201,0.132543,-0.098473,0.083010,-0.008803,-0.471651,0.141278,-0.905908,-0.158950,-0.458007,-0.448260,0.294323,-0.098042,-0.424580,0.806329,-0.926249,-0.069349,0.350324,0.357616,-0.203413,0.628004,0.266194,0.408828,-0.253816,0.101408,-0.058436,-0.103512,0.292122,-0.038891,0.622102,0.153573,-0.320734,-0.443465,0.445000', '26365262', '34429100', '3811356', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10546747', '法官老爹', '剧情', '汉克（小罗伯特·唐尼 Robert Downey Jr. 饰）是一名经验丰富的律师，专门帮有钱人收拾他们惹出的烂摊子，在汉克的眼里，没有所谓的正义，有的只是永恒的利益。母亲的意外去世让汉克不得不回到了印第安纳老家，那里是他的故乡，却有着他最不愿意回忆起的往事。在老家，汉克见到了久违的父亲约瑟夫（罗伯特·杜瓦尔 Robert Duvall 饰），一位当了一辈子地方法官的固执老人，父子两人之间紧张的关系并没有因为岁月的变迁而发生任何改变。让一心想要离开的汉克没有想到的是，一场交通事故让约瑟夫卷进了一宗案情复杂的官司中，而自己在为父亲辩护的同时，真相亦渐渐浮出水面。©豆瓣', '小罗伯特·唐尼', '大卫·道金', 8, 61543, 'tt1872194', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2197746452.jpg', 0.2, 1.4, 22.1, 51.4, 24.8, '0.470383,-0.035431,-0.805152,0.541990,-0.322370,-0.536195,1.124075,0.008202,-0.784675,-0.426551,0.142751,0.893905,0.050120,0.296979,0.017670,0.011169,-0.235080,-0.604452,0.018650,-0.172959,-0.218732,-0.814351,-0.270361,-0.273933,-0.270067,-0.182366,0.506669,0.117416,-0.043314,0.446100,0.441152,0.240019,-0.024632,0.609993,-0.176532,0.051912,0.011083,0.288863,-0.332255,-0.018319,0.372401,-0.362844,-0.287866,0.409409,-0.015625,0.516595,0.400496,-0.127623,-0.239332,0.037377,0.185332,-0.375708,0.032184,0.009989,0.276625,-0.198348,-0.042087,0.416220,-0.254040,-0.101414,0.258401,0.051724,-0.854126,0.104610,0.111052,0.626973,-0.657405,0.490860,-0.110659,-0.261693,0.101837,-0.348099,0.495592,0.449826,0.433778,0.401374,-0.251821,-0.042500,-0.524494,0.281590,0.893582,0.157524,-0.076509,0.471044,-0.468876,-0.236287,0.007347,-0.176417,-0.544944,0.118299,0.274736,0.041154,-0.173090,0.443344,-0.411732,-0.234290,-0.237687,-0.300144,-0.095544,-0.444732,-0.027841,-0.222334,-0.285255,-0.513388,-0.413921,0.085431,-0.069202,-0.313102,0.569957,-1.047601,0.166121,0.362228,0.102905,-0.458510,0.737430,0.194274,0.167684,-0.196931,0.146191,0.105660,-0.013975,0.237618,0.034698,0.229202,0.116181,-0.273816,-0.152972,0.339899', '1308755', '1296370', '4275444', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10546762', '魔法黑森林', '喜剧', '黑森林有一个村庄，三个经典童话按照既定脉络展开：饱受压迫的灰姑娘（安娜·肯德里克 Anna Kendrick 饰）想参加国王的舞会，但是坏心眼的继母和姐妹们想尽办法折磨她；杰克（丹尼尔·赫特斯通 Daniel Huttlestone 饰）将那头不再产奶的白色乳牛当做朋友，而妈妈却命令他将牛卖掉；小红帽（莉拉·克劳馥 Lilla Crawford 饰）装满好吃的面包，一蹦一跳朝着外婆所在的黑森林深处走去。小红帽刚刚离开，邪恶的女巫（梅丽尔·斯特里普 Meryl Streep 饰）突然出现，她对面包师（詹姆斯·柯登 James Corden 饰）施以可怕的诅咒，除非他在三天后能准备好四样东西：白色乳牛、红色斗篷、金黄色头发以及黄金鞋。在命运的驱使下，童话人物聚首黑森林……©豆瓣', '安娜·肯德里克', '罗伯·马歇尔', 5.9, 27482, 'tt2180411', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2213538065.jpg', 4.8, 23, 48.6, 17.6, 6, '0.300773,-0.005676,-0.338318,0.601959,0.122926,-0.086317,0.796996,0.391509,0.132777,-0.203059,0.315740,0.565664,-0.117367,0.043257,0.120988,0.303779,-0.377048,-0.473589,0.053132,-0.092821,-0.375983,-0.145743,-0.159611,-0.272441,0.095106,-0.269285,0.310970,-0.144729,-0.054665,0.377677,0.436789,0.160806,-0.077859,0.005231,-0.248900,-0.015335,0.082550,-0.135720,-0.190434,0.310581,0.101995,0.145390,0.135484,0.190764,0.129881,0.045033,0.662099,-0.716705,0.197504,0.080328,0.212404,-0.091116,0.010260,0.224655,0.149660,-0.094706,-0.046124,-0.031804,-0.082259,0.175138,0.381351,-0.268796,-0.297658,-0.188476,-0.186026,0.232352,-0.564496,0.100642,-0.039803,0.047334,0.518294,-0.456693,-0.100816,-0.128037,0.125067,0.380652,0.128872,0.204116,-0.420246,0.378495,0.316458,-0.034064,0.090169,0.104167,-0.326771,-0.175516,0.172457,-0.025769,-0.382241,-0.138901,0.586617,-0.026962,-0.037334,0.180988,-0.718089,-0.216487,-0.242212,-0.321195,0.136280,-0.430737,-0.361178,-0.388933,-0.091851,-0.061717,-0.076177,0.229563,-0.110292,0.022819,0.465441,-0.358344,0.586864,0.305752,0.123609,-0.197649,0.331137,-0.378542,0.123974,-0.095769,0.031983,0.414755,0.198984,0.094857,0.270592,0.451313,0.037585,0.069832,-0.429957,0.331052', '1467779', '21619567', '3012819', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10546813', '花样厨神', '剧情', '知名的电视制作人怡珊（杨紫琼 饰），继挖掘了国际厨神翰伟（黄经汉 饰）后，展开下一届新厨神的寻找工作，为此特别举办 “国际食神争霸赛”。从小与爷爷学做家常菜的一晗（刘宪华 饰）为保住自家即将倒闭的餐厅，贸然前去参赛。这个烹饪手法古怪的小子一路过关斩将，连续击败各国顶级米其林主厨，最终站到了挑战国际厨神翰伟的舞台上。就在此时，怡珊发现了一晗的神秘身份……', '刘宪华', '金镇雅', 5.9, 4208, 'tt1977755', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2374046139.jpg', 9.3, 24.4, 41, 14.2, 11.1, '-0.051346,0.268224,-0.612113,0.603624,0.248279,-0.045538,-0.166071,0.375573,-0.306933,-0.209088,0.502417,0.898604,-0.459001,0.241486,0.392427,-0.164648,0.049281,-0.651978,-0.076409,-0.247948,-0.342744,-0.097269,-0.344297,0.041733,-0.100882,-0.039750,0.625396,-0.024403,-0.328720,0.641760,0.429330,-0.021804,0.067815,0.161982,-0.278055,-0.115456,0.358703,0.062011,-0.354956,0.249002,-0.063554,-0.199676,-0.124725,-0.080649,0.272361,0.352215,0.431052,-0.246189,0.082188,-0.150293,0.400507,-0.368492,-0.200507,-0.077452,0.472590,0.217715,-0.061876,0.198513,-0.234179,0.220924,-0.227664,-0.237041,-0.738073,-0.051426,0.184768,-0.069893,-0.699205,0.329983,-0.129548,-0.073982,0.009028,-0.270863,0.292163,0.350050,0.242285,0.161875,0.319707,0.300152,-0.337178,0.283404,0.482653,0.155387,0.208234,0.334576,0.290938,-0.384895,0.110071,-0.458842,-0.241942,0.092097,0.212969,0.021901,0.336534,-0.176344,-0.608013,-0.168709,-0.019555,-0.268792,0.476779,-0.014632,-0.126912,-1.053011,0.185692,-0.109895,-0.031396,-0.232833,-0.191982,-0.305544,0.689878,-0.732807,0.145780,0.165296,0.209309,-0.384265,0.544061,-0.197234,0.233852,0.039435,-0.667580,-0.234532,-0.017932,0.425508,-0.269134,0.538195,0.084318,-0.374044,-0.316254,0.237840', '24751811', '2369613', '25723905', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10548265', '坚不可摧', '剧情', '赞佩里尼（杰克·奥康奈尔 Jack O''Connell 饰）是一位长跑运动员，他热爱这项运动，并且有幸参加了1936年的柏林奥运会。1939年，第二次世界大战爆发，踌躇满志的赞佩里尼加入军队，为祖国报效，他成为了一名空军投弹手。一次任务中，一场意外让赞佩里尼所驾驶的战斗机于海上坠毁，他和战友们在一艘小小的救生筏上度过了艰苦而又漫长的47天，然而，当他们获救之时，噩梦才刚刚开始。赞佩里尼成为了敌对国日本的俘虏，并且在集中营里结识了名叫渡边睦弘（石原贵雅 饰）的军官，在这里，赞佩里尼遭受到了非人的折磨和拷打，尽管幸存，但这一段经历在他的心灵上留下了不可磨灭的伤痕。战争结束了，可赞佩里尼的噩梦并没有终结。©豆瓣', '杰克·奥康奈尔', '安吉丽娜·朱莉', 6.9, 27604, 'tt1809398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2222056402.jpg', 1.5, 8.7, 44.1, 32.4, 13.4, '0.136525,-0.005917,-0.764766,0.481224,0.126658,-0.578096,0.663541,-0.308001,-0.569706,-0.050135,0.444877,0.840947,-0.165103,0.261070,0.327175,-0.237976,-0.437977,-0.767106,-0.007424,-0.117459,-0.539670,-0.504521,-0.367404,-0.180098,-0.145087,-0.441677,0.780049,0.432333,-0.059634,0.768966,0.272335,0.240011,0.400993,0.467107,-0.095182,-0.017040,0.314649,0.248641,-0.367108,-0.054031,-0.360127,-0.534237,-0.284711,0.167680,-0.071956,0.415245,0.584817,-0.459711,0.016177,-0.257831,0.128304,-0.541860,0.053265,0.246691,0.041813,0.239398,0.016588,0.082656,-0.032909,-0.088900,-0.093466,-0.081340,-0.644928,-0.222612,-0.177439,-0.095416,-0.523198,0.894657,-0.240728,-0.012166,0.012413,-0.291351,0.124052,0.456180,0.151682,0.352236,-0.368462,-0.059220,-0.357301,0.320799,1.094807,-0.264813,-0.328456,0.169197,-0.033577,-0.672758,0.059103,-0.574596,-0.346084,0.158058,0.109091,-0.131492,-0.104740,0.482021,-0.769320,0.324015,-0.484418,-0.337123,-0.262645,-0.013365,-0.113770,-0.543265,0.037058,-0.268293,-0.426957,0.287985,0.121042,-0.297188,0.845534,-0.762376,0.660058,0.535179,-0.005270,-0.441057,0.555550,0.107387,0.267312,-0.069694,0.021431,0.317376,-0.146206,0.255703,0.115346,0.511021,-0.175912,-0.087544,-0.245969,0.536345', '25721544', '35030151', '1870682', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10549480', '你眼中的世界', '剧情', '让人有些意外的欧美小清新爱情电影，影片讲述了两个美国大陆东西两端完全没有交集的陌生人之间的故事，两人不知为何被不可思议的力量联系在一起共享视觉听觉嗅觉等，当然最后相爱在一起了的爱情故事。', '迈克尔·斯塔尔-大卫', '布林·希尔', 7.6, 61065, 'tt2101569', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2203563258.jpg', 0.7, 4, 30.5, 43.7, 21.1, '0.317756,0.154147,-0.863520,0.904396,0.376599,-0.040266,0.735961,0.195087,-0.618859,-0.121752,-0.298979,0.695214,-0.367931,0.019076,-0.321509,-0.287176,-0.066220,-0.943705,-0.028014,-0.230444,-0.667765,-0.531829,-0.124471,-0.165443,-0.178878,-0.235480,0.395483,-0.214757,-0.491517,0.649586,0.123924,-0.561376,-0.529978,0.452620,-0.259024,-0.115134,0.477262,0.321055,-0.763660,-0.085856,-0.176805,0.193745,0.073493,0.334077,-0.340465,-0.050898,0.836965,-0.102583,-0.119736,0.139695,0.148352,0.388765,0.065086,-0.048572,0.229808,0.101227,0.462348,0.179040,-0.059150,-0.056067,0.262119,0.298149,-0.959107,0.370408,0.004531,0.446142,-0.184688,0.541620,0.234416,-0.307786,0.147333,0.000452,0.507343,0.351172,1.069984,0.577266,0.178888,0.123908,-0.117061,-0.025754,1.041831,0.032731,-0.428180,0.802432,-0.665818,-0.419137,-0.560716,0.002665,-0.276011,0.372035,0.207792,0.014796,-0.435839,0.708292,-0.944039,0.283585,0.236083,-0.001447,-0.095480,-0.724974,0.393298,-0.821084,-0.724954,-0.730973,-0.096724,0.414768,0.476946,-0.045399,1.059821,-0.454525,-0.055432,0.939515,0.426116,-0.579142,1.077564,0.498021,-0.250298,-0.234015,0.241720,0.142742,-0.031525,-0.188589,0.414578,0.534045,-0.085518,0.558350,-0.665265,0.476297', '2053515', '30162520', '19965431', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10551890', '猎头召唤', '剧情', '杰拉德扮演猎头专员Dane Jensen，他为家庭拼搏，经常忙到不可开交，即使过节也没法陪孩子。终于等到上司Ed Blackridge（威廉·达福扮演）宣布退休，Dane有望击败头号竞争对手接管公司。然而就在这时，他的十岁儿子却被诊断出患上血癌。突如其来的坏消息乱了阵脚。要追逐梦想，还是陪伴家人？他不得不做出选择。', '爱丽森·布里', '马克·威廉姆斯', 7.5, 4847, 'tt1718924', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2460288868.jpg', 0.8, 4.3, 34.1, 41.3, 19.6, '-0.334562,-0.172871,-0.670925,-0.063396,-0.370765,-0.413364,0.212141,0.300917,-0.458423,-0.410064,0.343024,0.475661,-0.039712,0.441455,0.593870,-0.369505,-0.069772,-0.646011,0.452798,0.203676,0.119645,-0.280041,-0.128676,-0.290434,-0.197570,-0.341793,0.650120,-0.203478,0.056482,0.108623,0.306075,0.377427,0.086793,0.410110,0.007313,-0.035804,0.205301,0.015132,-0.697884,0.297918,0.171888,-0.239981,-0.248232,-0.070502,0.258518,0.426396,0.224995,0.043547,-0.120390,-0.096018,0.251500,-0.648869,-0.090449,-0.047967,0.494896,0.092648,0.240507,0.244265,-0.183933,-0.050908,-0.354530,-0.198767,-0.787198,0.455561,0.429240,0.140667,-0.564535,0.062191,-0.160104,0.105133,0.179420,-0.306763,0.057646,0.413735,0.075346,0.547349,-0.358917,0.575842,-0.376131,0.138091,0.980542,-0.228314,-0.128712,0.247503,0.109704,0.158404,0.357052,-0.786675,-0.514449,0.105640,-0.215189,-0.031018,-0.369519,0.071367,0.414779,-0.246671,-0.563048,-0.351289,0.257016,-0.469740,0.297873,-0.326534,0.030989,0.292125,-0.073979,0.374073,0.249551,-0.356396,0.507037,-0.697175,0.081567,0.490293,0.314746,-0.806383,0.489976,0.305059,0.297011,-0.767174,0.374337,0.304581,0.127567,0.050901,-0.252103,-0.386094,-0.020758,-0.150451,-0.361345,0.198228', '1877596', '1484760', '5985887', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10554990', '致命呼叫', '惊悚', '特纳（哈莉·贝瑞 Halle Berry 饰）是一名911报案中心的接线员，一天她接到一个小女孩的电话，声称有陌生人闯入家中，特纳随即让她躲起来，然而此时通话突然断线，特纳焦急地回拨，不料却因此暴露了女孩的躲藏地，令其不幸被入侵者杀害。从此特纳陷入愧疚的深渊，无法再担任接线员的工作。半年后，特纳当了一名接线员导师。这天，一个新手接到一通报案电话，另一端的女孩凯西（阿比盖尔·布蕾斯琳 Abigail Breslin 饰）被绑匪困在汽车后备箱中，情况十分危急。经过侦查，特纳竟然发现歹徒就是当年杀死那个小女孩的凶手，出于愤慨和赎罪，她立即下定决心要亲自将歹徒捉拿归案。一场惊心动魄的电话缉凶即将展开，然而令众人意想不到的是，一个隐藏多年的秘密也渐渐浮出水面……©豆瓣', '哈莉·贝瑞', '布拉德·安德森', 7.4, 24092, 'tt1911644', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2016228486.jpg', 0.5, 3.3, 35.8, 47.5, 12.8, '0.374483,0.117296,-0.535878,0.544248,-0.272677,-0.208051,0.765066,-0.152912,-0.535829,-0.390706,0.287595,0.729454,-0.261409,0.273937,0.298570,-0.044171,-0.358915,-0.685479,-0.047880,-0.118563,-0.251473,-0.416947,-0.328206,-0.315983,0.160793,-0.086004,0.406860,0.101672,-0.118996,0.436734,0.184623,0.431463,-0.307945,0.684727,0.128107,0.034014,0.331700,-0.306822,-0.009878,0.274887,0.041608,-0.424084,-0.000796,0.318757,-0.185905,0.658691,0.392513,-0.112198,-0.300569,-0.083800,0.362140,-0.398902,-0.160703,-0.032852,0.506040,0.028898,0.016617,0.006615,-0.423108,-0.032744,0.225868,0.048747,-0.455727,0.097299,-0.247797,0.139811,-0.364323,-0.105667,-0.308150,0.222344,0.125275,-0.302294,0.116519,0.236816,0.135377,0.317653,-0.179354,0.070585,-0.271187,-0.001119,0.437427,-0.032462,-0.140619,0.112510,0.080411,-0.564606,0.320221,0.046349,-0.406585,0.042854,0.727507,0.225916,-0.372975,-0.045792,-0.156797,-0.186063,-0.775286,-0.217186,-0.274918,-0.326482,-0.615733,-0.458820,-0.035052,0.141306,-0.393681,0.191316,-0.212578,0.177253,0.377251,-0.681503,0.243221,0.519866,-0.126721,-0.303577,0.209213,0.020824,0.139829,-0.200166,0.280547,0.200015,0.223701,0.573782,0.086337,0.070881,-0.301825,-0.178962,-0.404957,0.052017', '1316693', '1326208', '21348112', '1304665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10555084', '穿越火线', '剧情', '一场毫无征兆的现代战争一触即发，无数大兵、先进武器聚集一地，战事愈演愈烈，导弹在天空中呼啸而过，子弹像雨点般的肆意飞散，形成了一道不可逾越的战争火线，而这道火线恰好阻隔了一对母子。年轻貌美的母亲不顾一切、试图只身穿越火线，救出年幼的儿子，但无奈于敌方火力封锁严密，而且她心中的机器怪物也是万般阻隔，这个冒险之旅对于一个女人来说就像一场噩梦，幸有一队勇敢的大兵舍身保护，但她能否克服千难万险，打败心魔，营救出儿子……', '斯维特兰娜·伊万诺娃', '贾尼克·法伊济耶夫', 6.8, 11156, 'tt2094767', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2119349476.jpg', 3.3, 10.4, 40.9, 34, 11.4, '-0.061973,-0.045325,-0.801687,0.644219,-0.004680,0.299411,0.892076,-0.216340,-0.100240,0.095358,0.642213,0.408296,-0.017087,-0.249092,0.014140,-0.302388,0.172144,-0.634856,-0.171222,0.109163,-0.422617,-0.208617,-0.494806,-0.244788,0.070414,-0.343684,1.018778,0.352623,-0.133663,0.410253,0.165599,0.241716,-0.332490,0.632248,-0.123412,-0.222272,-0.371656,0.125761,-0.294927,0.170038,-0.333159,-0.326740,-0.075512,0.307521,-0.454564,0.342220,0.684970,-0.503042,0.137491,-0.136607,0.208804,-0.574018,0.037285,0.322138,0.303236,0.198492,-0.104144,-0.524478,0.118834,-0.049568,0.030323,-0.158694,-0.301193,-0.309361,-0.041260,-0.163017,-0.466367,0.309783,-0.021732,0.036426,0.082106,-0.294084,-0.034549,0.094437,0.151361,0.413738,-0.974100,0.032945,-0.625176,-0.087639,0.899852,-0.106968,-0.661160,0.048058,-0.380411,0.075204,0.066999,-0.265404,-0.520232,-0.168371,0.609787,-0.014263,-0.383787,0.656808,-0.561291,0.279203,-0.633716,-0.047729,-0.545453,-0.381051,-0.105087,-0.391500,-0.067363,-0.173876,-0.252906,0.463141,-0.167632,-0.098835,0.754444,-0.567453,0.219350,0.670949,0.156476,-0.142599,0.346386,0.226888,0.204655,0.143861,0.287892,0.051332,0.025035,0.202786,0.121472,0.411842,-0.185920,0.227679,-0.047816,0.235313', '20497633', '21619567', '3011058', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10555085', '在我入睡前', '悬疑', '每一天对于克里斯汀（妮可·基德曼 Nicole Kidman 饰）来说都是完完全全崭新的一天，20年前的一场可怕的车祸让她的记忆定格在了那一天，脑部受到的严重损害令她的记忆只有24个小时，对于克里斯汀来说，每一天，她都在一张陌生的床上醒来，身边躺着一个陌生的男人，而这个陌生的男人是她的丈夫本（科林·费斯 Colin Firth 饰）。每一天，克里斯汀都会和负责治疗自己的医生纳什（马克·斯特朗 Mark Strong 饰）通电话，在纳什医生的帮助下，克里斯汀渐渐拼凑出了自己的历史，原来，每一天即将结束之时，克里斯汀都会将这一天发生的事情写进日记本，但渐渐的，克里斯汀发现，日记本上所记录的内容，和本告诉自己的大相径庭。而某一日，当克里斯汀再次打开日记本时发现日记本里写了一句话：不要相信本。©豆瓣', '妮可·基德曼', '罗温·乔夫', 6.5, 23744, 'tt1726592', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195916228.jpg', 1.1, 10.3, 57.6, 25.7, 5.3, '0.303385,0.180250,-0.584215,0.484542,-0.015852,-0.055088,0.791934,-0.228269,-0.791965,-0.452990,0.265397,0.883963,-0.303085,0.520023,0.438543,0.317073,-0.598059,-0.790424,-0.069953,-0.481996,-0.766805,-0.702820,-0.052723,-0.217349,0.226563,-0.483491,0.221497,0.086594,-0.037181,0.213562,-0.021786,0.074676,0.329649,0.341480,0.339460,0.188217,-0.057297,-0.113406,0.281551,0.272982,0.376034,-0.235358,-0.173564,0.310452,-0.029042,0.310940,0.552485,-0.345526,-0.436284,-0.028469,0.607267,-0.174987,-0.187009,0.034459,-0.060014,0.007539,0.419278,0.298366,-0.266526,-0.162063,0.288576,-0.020717,-0.764573,0.152631,-0.317732,0.481285,-0.560016,0.594712,-0.213136,0.323084,0.023592,-0.160197,0.219322,0.374889,0.196973,0.306393,-0.296321,0.048368,-0.302377,-0.020933,0.337631,0.196275,-0.336562,0.553807,-0.183702,-0.272832,-0.120313,0.097542,-0.460803,0.255316,0.137236,0.284647,-0.253356,0.142492,-0.434683,0.144470,-0.351051,-0.333247,-0.050860,-0.198929,-0.381460,-0.503934,-0.098997,-0.432531,-0.487260,0.223386,-0.056195,-0.362182,0.782037,-0.550499,0.510780,0.403411,0.009086,0.064869,0.547729,0.056596,0.074086,-0.126264,0.143394,0.413093,0.090461,0.409318,0.183412,0.252812,0.108420,0.192207,-0.529813,0.907431', '1307146', '30162520', '1293399', '1310176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10558252', '身份窃贼', '喜剧', '在外人眼里，戴安娜（梅丽莎·麦卡西 Melissa McCarthy 饰）是一个挥金如土的富婆，无论是多么贵重的奢侈品，戴安娜都能连眼睛都不眨一下的刷卡将它收入囊中。对于自己的挥霍，戴安娜并不感动心疼，因为她刷卡后产生的账单，都将被寄到一个名为桑迪（杰森·贝特曼 Jason Bateman 饰）的男人那里。原来，戴安娜是一个信用卡大盗，她所使用的钱，全都是桑迪辛辛苦苦赚来的积蓄。当警察找到桑迪时，他才发现自己的信用卡被盗刷了，愤怒的桑迪决定亲自前往戴安娜所在的迈阿密，发誓要将这个懒惰的蛀虫捉拿归案。而当桑迪顺利的找到了戴安娜并准备将她带回丹佛时，这个可怜男人的好运用光了，这件看似简单的事情渐渐的脱离的桑迪的控制。©豆瓣', '杰森·贝特曼', '赛斯·戈登', 6.1, 8707, 'tt2024432', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1856984240.jpg', 3.2, 15.8, 56.8, 19.9, 4.2, '0.526272,0.271338,-0.556367,0.441307,-0.371907,-0.408718,0.702661,-0.137363,-0.125252,-0.269578,-0.042597,0.641163,-0.096311,0.220177,0.164183,0.456411,-0.173191,-0.595921,-0.157679,-0.376267,-0.335292,-0.536389,-0.308493,-0.196786,-0.181568,-0.068115,0.375644,0.047723,-0.046144,0.246138,0.475679,0.179523,0.355653,0.612472,-0.227555,0.058066,-0.021552,-0.240616,0.196469,0.251811,0.242248,-0.198428,0.215248,0.542873,0.213293,0.428421,0.709503,-0.300430,-0.136259,0.128057,0.311950,-0.312367,-0.121732,0.200253,-0.218144,0.009642,-0.234667,-0.135354,-0.505974,0.039214,0.415282,-0.072610,-1.020801,-0.359384,0.112132,-0.029874,-0.694060,0.378607,-0.251902,0.076637,-0.029649,-0.409934,0.183728,0.196837,-0.054713,0.397924,-0.245330,-0.017706,-0.653858,0.258719,0.298243,-0.109335,-0.173629,0.465674,-0.357196,-0.438599,0.130565,-0.126547,-0.479575,-0.033244,0.477684,0.237019,0.041764,0.144873,-0.534562,-0.284804,-0.342931,-0.412099,-0.031556,-0.558483,-0.216978,-0.250650,-0.286946,-0.419430,-0.292876,-0.020379,0.102811,-0.279050,0.601333,-0.638920,0.120509,0.668165,0.288341,-0.367032,0.489547,-0.162217,0.145033,-0.015563,-0.415027,0.047230,0.473742,0.516423,0.289628,0.391714,0.184666,-0.260461,-0.145467,0.706841', '1793491', '1299932', '30163500', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10558405', '古畑任三郎完结篇 重生之死', '悬疑', '为自然风光所环抱的鬼切村，正经历一场惊心动魄的变革。当地大企业社长堀部伍平在野外遭到黑熊的袭击身亡，其身为副社长的外甥大吉（千叶哲也 饰）随即扶正，并力主将对很多人都至为重要的后山卖给他人。大吉的弟弟音弥（藤原龙也 饰）虽身为专务，但调皮顽劣，无心商界，加上性格的不同，因此与大吉一向不和。包括音弥和当地民俗资料馆馆长天马恭介（石坂浩二 饰）在内的许多人都反对这一决定，但大吉刚愎自用，拒不退让。此举令音弥极度不满，因此精心策划了一起完美谋杀案，并且具有强有力的不在场证明。古畑任三郎（田村正和 饰）、今泉慎太郎（西村雅彦 饰）与西园寺这一全新组合登场，迎战音弥送上的超完美谋杀案……本片为新春完结篇第一部。©豆瓣', '田村正和', '星護', 9.1, 10381, '古畑任三郎之复苏之死', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155138409.jpg', 0.2, 0.6, 7.1, 30.5, 61.6, '0.163101,0.009149,-0.582322,0.409927,0.180381,0.065352,0.347474,0.188542,-0.424759,-0.457216,0.187979,0.556955,-0.079312,-0.145724,0.196061,-0.033174,-0.102475,-0.313901,-0.311348,0.244147,-0.072328,-0.420546,-0.213929,-0.015510,-0.364383,-0.145320,0.529922,0.160818,-0.324032,0.576296,0.358829,0.569650,-0.064657,0.105629,0.246945,0.056218,-0.145528,0.094711,-0.292008,0.056181,-0.283438,-0.254125,-0.271031,0.486409,0.099164,0.393075,0.534743,-0.465345,-0.336179,-0.393129,0.393112,-0.233367,-0.148152,0.318994,0.280712,-0.009974,0.333359,0.479861,-0.148072,0.204704,0.130838,-0.016381,-0.822289,0.079312,0.447819,0.116706,-0.224800,0.479397,-0.187830,-0.259314,0.047538,-0.200675,-0.074295,0.343763,0.271797,0.050655,-0.176596,0.270744,-0.211557,0.008861,0.768997,0.142966,0.008086,0.189714,-0.221711,-0.375305,-0.199915,-0.472459,-0.216746,0.066521,-0.167161,0.242501,0.190187,0.248227,-0.387177,-0.097523,-0.067083,0.126413,0.107357,-0.236991,-0.001386,-0.597443,0.133755,-0.576962,-0.219374,-0.024950,0.364101,-0.226771,0.622322,-0.636705,-0.025212,0.047605,0.162229,-0.276729,0.365851,0.144795,0.029064,-0.220106,-0.384159,-0.251849,0.360462,0.015530,-0.044218,0.242111,0.140968,-0.452385,-0.133948,0.182362', '1874704', '26678784', '1793491', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10558440', '乐园追放', '科幻', '四百年后的未来，一曾蔚蓝的地球黄沙遍野，自然环境极度恶劣。与之相伴，旧有的人类文明凋零殆尽，早先绝大多数幸存者迁往靠近地球的外太空，在名为迪瓦的设施中安顿下来。他们抛弃肉体，将自己的精神和灵魂投入迪瓦所构建的虚拟空间中，尽情享受没有丝毫痛苦的快乐。但是自称弗隆提亚·赛塔（神谷浩史 配音）的骇客让维护迪瓦网络安全的中央保安局坐立不安，为了彻底揪出这个神秘敌人，保安局派出三等官安吉拉•巴尔扎克（钉宫理惠 配音）回到地球调查。操纵先进机甲的安吉拉率先打败蜂拥而至的沙地巨虫，随后和前来接应的丁格（三木真一郎 配音）见面。两个性格全然不同的搭档一同上路，来到了弗隆提亚可能藏身的杰德小镇。安吉拉在那里得知令人惊讶的事实，而她曾经所坚持的信念也开始动摇……©豆瓣', '钉宫理惠', '水岛精二', 8.2, 8266, 'tt2859246', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2163672942.jpg', 0.4, 2.2, 17.7, 46.6, 33, '0.254099,0.160829,-0.904512,0.638766,-0.228433,-0.088555,0.689594,0.132266,-0.444563,-0.258771,0.145168,0.770751,0.047291,0.218882,0.245507,0.137158,-0.298311,-0.506031,-0.251048,-0.127035,-0.195070,-0.547836,-0.414687,-0.180871,-0.116586,-0.492185,0.772983,0.191542,-0.048853,0.601568,-0.089974,0.275371,-0.307612,0.219566,-0.045024,-0.090231,0.227581,-0.334745,-0.377526,0.070707,-0.308318,-0.070773,0.108472,0.288423,-0.120606,0.209650,0.593444,-0.259345,-0.047340,-0.059899,0.271009,-0.384619,0.047411,0.251886,0.258802,-0.095877,-0.093906,0.062745,-0.196542,0.110574,0.025468,0.130144,-0.782892,-0.026650,-0.080422,0.099452,-0.431438,0.406142,-0.023713,-0.204155,0.111508,-0.177903,0.203164,0.422742,0.235624,0.463817,-0.258573,0.095682,-0.188131,-0.088803,0.579672,-0.207773,-0.423617,0.064275,-0.027683,-0.228533,0.029424,-0.236036,-0.261611,-0.321718,0.287987,0.262119,-0.108126,0.388095,-0.769963,0.150137,-0.270077,-0.266212,-0.011296,-0.284046,-0.080366,-0.954106,-0.271174,-0.359996,-0.172117,-0.075080,0.159689,-0.165550,0.673287,-0.636481,0.321911,0.402564,0.283059,-0.461954,0.377397,0.084614,0.159396,-0.027691,0.071175,0.527943,0.283261,0.626659,-0.014730,0.288087,-0.012862,0.075111,-0.685779,0.512154', '20274039', '2369613', '25928048', '3606973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10558447', '啪嗒啪嗒', '动画', '一条生活在海洋里的马鲛鱼被渔网捕捉，而后被困在了一家海鲜餐馆的水箱里。从那以后她不屈不挠地寻找逃脱的方法。跟水箱里其他来自渔场的鱼不同，悲观的怀疑论者“老比目鱼”也生长在大海。作为水箱里幸存时间最长的一条鱼，他凭借其生存之道控制着其他的鱼。对他而言，马鲛鱼试图逃出水箱的举动已经对他的统治构成了威胁。', '金贤智', '李大喜', 8, 15920, 'tt2164058', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1644911676.jpg', 0.5, 1.6, 19.5, 53.1, 25.3, '0.444109,-0.027150,-0.650287,0.843619,-0.058863,0.016167,1.074942,0.188612,-0.475217,0.083691,0.099829,0.571855,0.278023,0.046165,-0.352180,-0.127967,-0.313093,-0.489420,-0.320216,-0.235485,-0.518173,-0.229949,-0.749319,-0.175742,-0.075674,-0.108676,0.420640,0.159586,-0.377158,0.320893,-0.002220,-0.155988,-0.137929,0.527977,-0.367135,-0.137416,-0.143655,-0.114088,-0.069359,0.365412,-0.127304,-0.222850,0.210509,0.344240,0.091873,0.603026,0.985359,-0.770329,-0.046677,-0.096898,-0.165435,-0.300704,-0.181837,0.155552,0.416611,-0.042613,0.094900,0.120678,-0.516102,0.298184,0.148664,0.058228,-0.933003,-0.569436,-0.198024,0.326360,-0.720475,0.428221,0.407202,-0.300510,-0.156912,-0.443013,0.192728,-0.231975,-0.103021,0.659608,-0.212369,0.173150,-0.720301,-0.008795,0.613225,-0.348966,-0.275179,0.057132,-0.287028,-0.437598,-0.132734,-0.236413,-0.289996,-0.480402,0.354088,0.103796,-0.680808,0.313173,-0.993495,0.543506,-0.065730,-0.416407,-0.036818,-0.236841,-0.428405,-0.569064,0.265816,-0.425534,0.033109,0.101151,0.067705,-0.217965,0.635249,-0.549275,0.123750,0.373272,0.407216,-0.275271,1.021137,-0.075633,0.281082,-0.284786,-0.082715,0.390835,0.153221,0.513296,0.262568,0.447634,0.123340,-0.103900,-0.747383,0.571142', '1293515', '21619567', '3055049', '1306666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10561880', '扎职', '犯罪', '1997年，用功读书且孝敬寡母的阿霆（陈伟霆 饰）和早早便混社会的阿祥（曾国祥 饰）、阿栋（徐伟栋 饰）是自幼长大的好朋友。因做小生意的霆母被人欺负，阿祥等人叫来大哥耀文（谭耀文 饰）相助。文哥是黑道响当当的人物，当年曾一夜之间横扫油麻地，但却甘心经营一家小水果摊。见识了文哥的义气，阿霆决心拜入其门下，希望早日赚大钱孝敬父母。经过多年的打拼历练，阿霆逐渐成长为足以独当一面的少壮派人物。他代大老板王波（卢海鹏 饰）收账，由此与富家千金Michelle （诗雅 饰）相识相恋。风光无限的阿霆惹到同门前辈火爆明（林利 饰），不仅遭到残酷毒打，连恋情也出现转机。这一事件促使他的内心世界以及黑道格局发生天翻地覆的变化……©豆瓣', '陈伟霆', '陈翊恒', 6.4, 14958, 'tt2354525', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1755106338.jpg', 4.1, 15.7, 48, 21.8, 10.4, '-0.131235,-0.127781,-0.403572,0.256369,0.020686,-0.250870,0.080209,0.266043,-0.773933,-0.296363,0.141633,0.574606,-0.203674,0.194947,0.339869,-0.254983,0.094947,-0.662389,0.247102,0.021725,0.095456,-0.101738,-0.299658,-0.072294,-0.147703,-0.072913,0.344034,0.090788,-0.066919,0.526414,0.229253,0.166862,-0.181496,0.083665,-0.360625,0.026754,-0.015557,0.361843,-0.546798,-0.309317,-0.354711,-0.377708,-0.036412,-0.290402,0.225228,0.137644,0.305596,0.053753,-0.251661,-0.160135,0.267356,-0.039750,-0.120676,-0.044034,0.220249,0.035707,0.120055,0.488944,-0.187115,-0.098135,-0.123539,-0.294411,-0.515264,-0.034065,0.382700,0.007487,-0.708424,0.372967,-0.006926,-0.261811,-0.228753,-0.082067,0.029017,0.325779,0.154760,0.232656,0.106846,0.371259,-0.320608,0.222097,0.702338,-0.068404,-0.069982,0.175559,0.131031,-0.153721,0.144270,-0.573273,-0.447464,0.146632,0.036929,-0.270763,-0.242903,0.492932,-0.323869,-0.074536,-0.269989,0.146249,0.165416,-0.121085,-0.032041,-0.418164,-0.447453,-0.556854,-0.238975,0.066428,-0.043703,-0.290699,0.839821,-0.652448,0.076015,-0.072135,0.204598,-0.727211,0.563209,-0.062521,0.129715,-0.236028,-0.231749,0.013764,0.055677,-0.111666,0.002083,0.070073,-0.058446,-0.266795,0.112744,-0.037619', '1877596', '1480318', '1308424', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10562986', '宿敌', '剧情', 'Adam（杰克·吉伦哈尔 Jake Gyllenhaal 饰）是一所大学的历史系副教授，和女朋友生活在一起，每天上班下班，过着平静的生活。直到一天，他在一部电影里发现了一个长得和他一模一样的演员。他利用互联网找到了该演员的资料，并联系上了他。和Adam长得一模一样的演员叫Anthony，有一个怀孕的妻子，他一开始只把Adam当成一个疯狂的影迷，直到上网搜索了Adam的资料，终于下决心和Adam见面。两人约定在一个旅馆见面，Adam见到一个长得和自己一模一样的Anthony，心生恐惧，告知对方此后不要再见便匆匆离开。然而几天后，Anthony却出现在Adam家中，并提出了一个奇怪的要求......©豆瓣', '杰克·吉伦哈尔', '丹尼斯·维伦纽瓦', 7, 29840, 'tt2316411', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2145705774.jpg', 1.3, 6.6, 42.4, 39.8, 9.8, '0.493631,-0.112083,-0.862976,0.753672,-0.082734,-0.654415,0.915363,-0.072413,-0.352694,-0.466634,-0.177288,1.072919,-0.533450,0.673398,0.160031,0.015779,-0.336377,-0.875372,0.067204,-0.206318,-0.251581,-0.437312,-0.102605,-0.050035,0.152008,-0.311129,0.482540,-0.319080,0.084152,0.798157,0.279838,-0.417034,-0.030503,0.617751,-0.391954,0.047967,0.046072,0.212249,-0.164054,0.454617,0.145467,0.009351,0.000870,0.011194,0.163963,0.490547,0.637030,0.195753,-0.540064,0.275409,0.496049,-0.046481,-0.305580,0.219767,0.439552,-0.020013,0.164405,-0.035797,-0.502649,0.259598,-0.234397,-0.204128,-0.651031,-0.033402,-0.131591,0.301434,-0.858106,0.591117,-0.031290,-0.089472,-0.039733,-0.555889,0.379814,0.324920,0.058616,0.577205,-0.141288,0.110499,-0.532420,0.311158,0.793306,-0.003760,-0.073365,0.552338,0.115094,-0.404435,-0.121503,0.222854,-0.639194,0.121214,0.194585,-0.072922,-0.496024,-0.286092,-0.800108,-0.038840,-0.066287,-0.164905,0.161545,-0.556993,-0.021466,-0.615213,-0.186483,-0.331444,-0.563384,0.293939,-0.036389,-0.415591,0.779235,-1.021188,0.170560,0.400206,0.427764,-0.625883,0.874843,0.348460,0.092296,-0.175528,0.381918,0.160168,0.234683,0.335003,0.035196,0.596204,-0.030849,-0.108287,-0.725225,0.512718', '1292219', '1361252', '3111650', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10562987', '美女与野兽', '爱情', '在回家的途中，一位商人（安德烈·杜索里埃 André Dussollier 饰）遭遇了罕见的暴风雪，昏天黑地之中，商人误打误撞来到了一幢豪华神秘的城堡前。商人在城堡中受到了贵宾般的优厚待遇，但直到最后，商人仍然不知道城堡的主人究竟是谁。暴风雪停歇了，商人准备离开，临走之前，他决定在花园中摘一朵玫瑰送给自己最喜爱的小女儿贝儿（蕾雅·赛杜 Léa Seydoux 饰），而令他没有想到的是，长相狰狞的野兽（文森·卡索 Vincent Cassel 饰）出现在了他的面前向他索命。商人失魂落魄的回到了家，将自己的遭遇告诉了六个儿女，爱父心切的贝儿决定代替父亲，只身来到了城堡。然而，等待着贝儿的却并非死亡，而是更加盛情的款待，野兽对她唯一的要求，就是不要离开城堡半步。贝儿并不惧怕野兽，随着时间的推移，两人之间的关系越来越近。©豆瓣', '文森特·卡索', '克里斯多夫·甘斯', 6.8, 44045, 'tt2316801', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199308961.jpg', 1.5, 9.8, 46, 30.6, 12.2, '0.411982,0.186114,-0.829528,0.614696,0.074784,-0.232826,1.050300,0.163047,-0.498158,-0.313096,0.459655,0.772215,-0.130755,0.136942,0.255052,0.098310,-0.174251,-0.329478,-0.249379,-0.489560,-0.213290,-0.476964,-0.035043,-0.107225,0.008735,-0.311403,0.514551,0.243467,-0.068719,0.429418,0.303693,0.154889,-0.100027,0.616731,-0.251776,-0.127090,0.200540,0.008835,-0.217754,0.256793,0.024883,-0.207623,-0.131899,0.383593,0.204001,0.258090,0.653680,-0.588696,-0.185074,0.082144,0.164434,-0.171343,0.164323,0.213476,0.305978,-0.269755,0.176905,0.155348,-0.183307,0.156780,0.116299,-0.302966,-0.538002,0.167232,0.041649,0.161216,-0.822051,0.426615,-0.033688,-0.156899,0.167480,-0.480389,0.360908,0.329986,0.020358,0.381533,-0.168425,0.019566,-0.688284,-0.116310,0.747855,0.105360,0.012010,0.466846,-0.400514,-0.512753,-0.070559,-0.213142,-0.531940,-0.120310,0.329320,0.190932,-0.301484,0.115236,-0.563270,-0.182688,-0.300008,-0.303088,0.069288,-0.417477,-0.340152,-0.505191,0.167691,-0.401752,-0.225854,0.353769,-0.182660,-0.149434,0.534347,-0.952954,0.330370,0.600704,0.587063,-0.379378,0.740278,-0.245199,-0.006294,-0.003150,-0.031308,0.364817,0.232787,0.312955,0.146423,0.117010,-0.001401,-0.211803,-0.232171,0.546068', '1302384', '3055049', '1308755', 