INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10563779', '嫌疑人', '动作', '韩国闹市街头，生活着一名沉默寡言、逆来顺受的男人池东哲（孔侑 饰）。他从事代驾工作，见惯了他人的白眼和凌辱。真正的他是从北朝鲜逃过来的前特殊部队成员，为了追查害死妻儿的凶手而甘愿抛弃一切。在朝鲜他得到了德高望重的朴会长的器重，谁知会长在某个夜晚被人杀害，老人临死前将自己 的眼镜交给东哲。成为此案重要嫌疑人的东哲卷入了一连串充满杀戮和阴谋的漩涡，更不知道那副眼镜中竟然隐藏着天大的秘密。朝鲜秘密部门蠢蠢欲动，空军特殊部队CCT的训练教官闵世勋大校（朴熙顺 饰）也对东哲紧追不舍。站在风口浪尖的东哲，被迫凭借一己之力周旋在各方势力之中……©豆瓣', '孔刘', '元新渊', 7.5, 37715, 'tt3404158', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2159702691.jpg', 0.5, 3.3, 33, 45.1, 18.1, '0.041325,-0.020374,-0.662736,0.618742,-0.329102,0.154653,0.632660,0.307336,-0.523547,-0.212098,0.395130,0.681836,0.290015,0.103145,0.337901,-0.174644,-0.183296,-0.860312,-0.433505,-0.061976,-0.376927,-0.666576,-0.322595,-0.207065,-0.090826,-0.239043,0.763729,0.303518,-0.314674,0.157275,0.445791,0.427370,-0.251600,0.575038,-0.201820,-0.074096,0.179692,-0.285530,-0.093991,0.021217,-0.116550,-0.344034,-0.152780,0.176543,-0.150727,0.156730,0.628215,-0.273765,-0.055973,-0.369061,0.292080,-0.547954,-0.181379,0.053545,0.593352,0.015288,-0.018241,0.262869,-0.185315,-0.068209,0.169043,0.001698,-0.844762,-0.210331,0.132102,0.140919,-0.615543,0.418223,0.038873,0.032610,0.178922,-0.242140,0.272812,0.386561,-0.066128,0.211076,-0.031786,0.117892,-0.716802,0.251736,0.470450,-0.133512,-0.107950,-0.128780,-0.211780,-0.232592,-0.140890,-0.452387,-0.549975,-0.089577,0.389145,-0.169752,-0.202403,0.236117,-0.315253,-0.054793,-0.093676,-0.010080,-0.094068,-0.511240,-0.227346,-0.454339,-0.280100,-0.217760,-0.133332,0.226272,0.180748,-0.150945,0.778028,-0.844505,0.027017,0.703902,0.202891,-0.649697,0.593183,0.100511,0.228095,-0.223743,-0.318260,0.140779,0.366695,0.355951,0.223547,0.318791,0.005596,-0.192311,-0.218838,-0.020945', '30163500', '1877596', '1301022', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10563780', '观相', '剧情', '本片以朝鲜初期时代为背景，戏说了朝鲜世祖篡位的历史。乱臣后代金乃敬（宋康昊 饰）拥有看面相识人的技能，但却由于身份卑微只能和妹夫（赵郑锡 饰）还有儿子镇衡（李钟硕 饰）隐居于荒野。汉阳最大妓院的老板娘（金惠秀 饰）专程来拜访了金乃敬，并游说他前去汉阳靠看相赚钱，但却遭到了镇衡的不理解。来到汉阳后的金乃敬步步为营，赚到了大钱并得到了忠臣金宗瑞（白允植 饰）的赏识，甚至获得了国王的信赖。可是由于出色的才能金乃敬不得不卷入了国王的亲弟弟首阳大君（李政宰 饰）争夺王位的争斗中，并且还连累了已经改名换姓中了状元的儿子镇衡。金乃敬决定帮助金宗瑞和小国王破坏首阳大君的阴谋，可是他能看透人心却不能决定人的命运。历史的洪流还是不停地流逝着。©豆瓣', '宋康昊', '韩在林', 7.4, 38154, 'tt3008014', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2112449528.jpg', 0.5, 3.2, 38, 43.2, 15.1, '-0.152300,0.243914,-0.552224,0.826562,-0.111529,-0.316847,0.367900,0.441033,-0.580805,-0.116799,0.276790,0.578211,0.088919,-0.027779,0.242261,0.084794,-0.161946,-0.604863,0.099667,-0.108180,-0.140722,-0.448252,-0.518900,-0.301053,-0.359016,-0.172837,0.761678,0.298243,-0.203050,0.181243,0.254976,-0.020684,0.099807,0.476696,-0.324471,0.067357,-0.110352,0.029854,-0.359562,0.089388,0.080485,-0.302886,-0.210889,0.116386,0.167147,0.324918,0.472459,-0.645951,0.127416,-0.164379,0.196833,-0.318562,-0.087689,0.146159,0.165352,0.081031,0.279755,0.397451,0.013935,0.053938,0.195663,-0.090415,-0.883470,-0.003783,0.242162,0.011976,-0.563840,0.646861,-0.062049,-0.275211,-0.119909,-0.290438,0.165803,0.335424,0.175132,0.369256,-0.375134,-0.027977,-0.566730,0.264087,0.443872,0.006344,-0.233952,0.246643,-0.173454,-0.470109,0.056708,-0.648258,-0.310168,0.076358,0.278135,0.130862,-0.097044,0.405187,-0.319802,-0.236900,-0.405107,0.043237,0.234090,-0.432289,0.130967,-0.294119,-0.231499,-0.481688,-0.132230,0.018097,0.360881,-0.311556,0.716648,-0.761276,-0.045212,0.577829,0.539089,-0.657715,0.623823,0.167882,0.025829,-0.096186,-0.307693,0.067188,-0.094648,0.276599,0.085320,0.080185,-0.089280,-0.420515,-0.133438,0.394072', '1793491', '3670447', '25932086', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10566662', '共犯', '惊悚', '美丽女孩郑多恩（孙艺珍 饰）自幼和父亲顺满（金甲洙 饰）相依为命，无论周遭如何变化，父亲依然是她最亲近的人。在多恩求职期间，15年前一起轰动全国的绑架案重新被人提起。当年名叫韩采进的儿童遭人绑架并杀害，而绑架者却始终下落不明。眼看追诉期将过，一部根据该事件改编的影片全国公映，影片结尾更公开了嫌疑犯当年的电话录音。和朋友结伴观影的多恩惊恐地发现，那被称作“恶魔的低语”的声音经和父亲的声音如此相像。她尝试调查父亲的过去，却始终没有收获。某天，一名沈姓男子出现在父女的生活中，他似乎知晓关于顺满不可告人的过去，也将黑暗带到这个看似普通的家庭之中……©豆瓣', '孙艺珍', '国东锡', 6.7, 9994, 'tt3271700', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155399263.jpg', 1.1, 9.2, 51.6, 29.5, 8.6, '0.287413,-0.095619,-0.768963,0.671270,0.177988,-0.040991,1.032086,0.002551,-0.619889,-0.520700,0.081299,0.608706,-0.180241,0.235820,0.308735,0.004830,-0.277415,-0.731121,-0.198315,-0.256262,-0.341684,-0.399603,-0.385311,-0.044677,-0.081551,-0.118711,0.616406,0.152648,-0.273678,0.600006,0.293564,0.155300,-0.327289,0.483766,-0.159018,0.085070,0.048965,0.255950,-0.295504,0.095936,0.011272,-0.338203,-0.142576,0.099489,-0.221708,0.524062,0.519035,-0.255223,-0.058926,0.083428,0.397790,-0.106930,-0.104924,0.077462,0.416689,-0.018356,0.385765,0.389546,-0.191596,-0.099599,-0.171700,-0.046572,-0.648242,0.160250,0.292979,0.369095,-0.422985,0.302973,0.078196,0.172325,0.008180,-0.299189,0.187703,0.265108,0.228155,0.498433,-0.191855,0.063390,-0.351081,0.257840,0.665877,-0.011040,-0.168442,0.206889,-0.187455,-0.543200,-0.209255,-0.332300,-0.421399,0.304701,0.057951,0.147648,-0.278139,0.404276,-0.433284,-0.119988,-0.033874,0.026749,-0.107477,-0.507959,-0.154425,-0.536079,-0.218886,-0.524517,-0.420561,-0.011434,0.154610,-0.404400,0.663747,-0.726101,0.189024,0.301728,0.347899,-0.466918,0.564607,0.259669,0.142974,-0.245812,-0.293932,0.473286,0.307288,0.080878,-0.165594,-0.002561,-0.000648,-0.176495,-0.366766,0.213135', '3111650', '2131640', '1296534', '1307748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10567506', '甜心巧克力', '爱情', '国际大都会上海，美丽女孩林月（林志玲 饰）在街角经营着一家全手工制作的巧克力店。她的日本人好友木场总一郎（池内博之 饰）来华十年，此前曾是北海道夕张的滑雪场救助员，如今在异国他乡进行绘画创作。总算成功举办个人画展的木场，一直渴望和林月走入婚礼殿堂，但是曾经的一段往事成为二人间难以逾越的藩篱。当年心怀画家梦想的林月以留学生身份来到北海道学习，她先后结识了木场及其同事兼好友星野守（福地佑介 饰）。喜欢做巧克力送给同乡的星野热情开朗，他主动出击，与林月越走越近。浪漫美好的异国在银白的北国悄然上演，但命运却将这三个男女无情捉弄……©豆瓣', '林志玲', '筱原哲雄', 5.2, 4931, 'tt2351385', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2156485969.jpg', 13.7, 31.9, 41.1, 9.4, 3.9, '0.004128,0.006632,-0.508128,0.501424,0.133613,-0.265969,0.439731,0.173800,-0.608492,-0.118982,0.053395,0.635652,-0.242793,0.450603,0.513626,-0.018122,-0.206004,-0.558136,0.019459,-0.443113,-0.047028,-0.250905,-0.045211,-0.125343,-0.193156,-0.149228,0.677758,0.394603,0.234234,0.361766,0.355471,0.184209,-0.337383,0.280355,-0.065399,-0.159995,0.168532,0.220183,-0.557025,0.168871,-0.313849,-0.247812,-0.254152,-0.164437,0.208070,0.010565,0.775216,-0.066534,-0.243614,-0.119839,0.610069,-0.163249,-0.034553,-0.178686,0.259242,0.275760,0.158480,0.082803,-0.258509,-0.333199,0.079139,-0.596130,-0.052535,0.176465,0.203664,-0.205335,-0.634267,0.425936,0.054497,0.026767,0.293725,-0.249975,0.087879,0.370149,0.332642,0.237213,0.072573,0.326196,-0.218878,0.518643,0.713500,0.172563,-0.001630,0.094151,-0.223949,-0.331158,-0.110233,-0.210435,-0.361400,-0.019527,0.080430,-0.048445,0.105602,-0.028910,-0.352908,0.033031,0.051449,0.126731,0.610458,-0.385880,-0.165624,-0.961192,-0.023364,-0.552350,0.023756,0.015530,0.150369,-0.252033,0.770497,-0.804181,0.111551,0.307835,0.338507,-0.232800,0.776265,0.070997,-0.166175,-0.207255,-0.286004,0.525843,-0.167639,0.172862,-0.074748,0.390703,-0.057019,0.246009,-0.336499,0.258138', '3811356', '24751811', '5403927', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10567515', '小好、小麻、佐和子', '剧情', '交往长达十年的三名女性：森本好子（柴崎幸 饰）、冈村麻子（真木阳子 饰）、林佐和子（寺岛忍 饰）时常相约外出野餐，享受纯洁友谊和快乐时光的她们，现实生活中有着各自的烦恼。好子供职于一家咖啡厅，心中有着心仪的男子，却无可奈何错过；某大型公司OL麻子虽然要强干练，可是内心厌烦了周遭的一切，渐渐感到疲惫不堪；身为网站设计师的佐和子与母亲和外婆相伴度日，即使渴望结婚，但并非没有后顾之忧。种种现实问题摆在眼前，让这三个身处大都会繁华中心的女子百感交集……本片根据益田米莉（益田ミリ）的人气四格漫画《小好（すーちゃん）》改编。©豆瓣', '柴崎幸', '御法川修', 7.7, 11217, 'tt2339675', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1746423742.jpg', 0.2, 1.8, 28.2, 51.3, 18.5, '0.122473,0.020794,-0.431182,0.258725,0.256890,-0.335070,0.717259,0.272869,-0.575189,-0.626604,-0.022231,0.602936,-0.179780,0.599466,0.120555,-0.234011,-0.261568,-0.401490,-0.078466,-0.079097,0.411400,-0.265783,-0.162054,-0.185956,-0.411834,-0.175173,0.938190,0.112476,0.066702,0.670875,0.242061,0.336090,-0.334289,0.335775,-0.141849,-0.206333,-0.004955,0.092041,-0.520362,-0.166466,-0.234699,0.084832,0.025210,-0.043499,0.025574,0.239603,0.597883,0.076642,-0.595148,0.025643,0.544755,0.032867,-0.227592,0.151247,0.113127,-0.075998,0.276091,-0.046382,-0.295057,-0.083945,0.048757,-0.077228,-0.670673,-0.038179,0.490302,0.203363,-0.226198,0.524242,-0.069483,-0.483082,0.229935,-0.152944,0.004077,0.024815,0.582712,0.260881,-0.035773,0.258361,-0.113133,0.163704,0.795404,0.229173,-0.304946,0.422503,-0.427198,-0.140909,-0.154696,-0.367807,-0.439356,0.088001,-0.322907,0.191490,0.059356,0.203886,-0.581109,0.297978,-0.023422,0.024537,0.219962,-0.331085,-0.079700,-0.583787,-0.270110,-0.696323,-0.577112,-0.058320,0.335826,-0.137017,0.818864,-0.690418,0.061388,0.191124,0.160300,-0.310004,0.869963,0.314706,0.008949,-0.319453,-0.083802,0.466306,-0.279748,0.057886,-0.255647,0.217287,-0.357525,-0.028767,-0.555031,0.258283', '25880986', '3667102', '3811356', '25962735');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10568385', '地心营救', '剧情', '影片改编自智利著名矿难事件，讲述33个男人在一场突如其来的灾难中被困地心深处，出路被塌陷的岩石全部封死，是坐以待毙，还是绝境求生？整整69天，兄弟同心，一路冲关，最终全部生还，创造了人类营救史上的最大奇迹。', '安东尼奥·班德拉斯', '派翠西亚·里根', 7.5, 26386, 'tt2006295', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2316133145.jpg', 0.4, 2.7, 34, 47.6, 15.4, '-0.540262,-0.101122,-0.579321,0.395498,0.444845,0.142542,0.633797,-0.511080,-0.379176,-0.056368,0.495423,0.543610,-0.346930,-0.089053,0.370044,-0.308214,-0.187868,-0.701782,-0.389957,0.044322,-0.601654,-0.137604,-0.379300,-0.045462,-0.157140,-0.021069,1.099706,0.735218,-0.384004,0.076448,0.108610,0.373049,-0.244821,0.207917,0.008129,0.113123,-0.063848,-0.246547,-0.409115,0.405856,-0.447129,-0.255229,-0.183606,0.283446,-0.371435,0.228540,0.519897,-0.716384,0.194059,-0.087422,0.275548,-0.789392,-0.458780,0.172064,0.263713,-0.110283,0.310674,0.425110,-0.205965,-0.252343,0.460803,-0.187422,-0.760602,-0.327863,0.056598,-0.042796,-0.438121,0.183133,0.618674,0.187064,-0.029668,-0.263104,0.214702,-0.136037,0.704158,0.388472,-0.537134,-0.055630,-0.215917,-0.070139,0.979910,-0.449910,-0.311729,0.159491,-0.007440,-0.366478,-0.122986,-0.413777,-0.404566,0.265976,0.397525,0.346280,-0.254806,0.731780,-0.547839,0.214029,-0.614226,-0.373196,-0.241644,-0.246413,-0.417449,-0.200561,-0.212352,0.363037,0.006188,0.260126,-0.169124,-0.316748,0.555904,-0.090866,0.068393,0.815092,-0.217283,-0.148368,0.604977,0.110571,0.264034,-0.151547,0.253314,0.406935,-0.345366,0.562904,-0.126365,0.251282,-0.333769,0.004059,-0.356815,0.384526', '7051375', '25828589', '3001114', '25827286');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10569022', '愤怒的小孩', '喜剧', '孙小傲（王一鸣 饰）是个古灵精怪的淘气包。爸爸孙建业（张嘉译 饰）和妈妈（江珊 饰）在俄罗斯工作，小傲一直由耳聋寡言的爷爷（范伟 饰）照顾。假期将至，爷爷生病住进医院。一直渴望父母关爱的小傲的生日聚会再次被爸爸以工作为由爽约，愤怒的小傲忍无可忍离家出走。半路上小傲意外地发现搬家车里藏着的小女孩兰兰（肖逾榛 饰）。小傲用弹弓将兰兰从追踪她的笨贼手中救出，得知兰兰原来是被犯罪团伙利用的小乞丐。兰兰想要逃离犯罪团伙，回到家乡去寻找宝藏、闯荡世界。无处可去的小傲顿时来了兴致，执意与她同行。兰兰勉强答应，两个愤怒的小孩踏上了离家和归家的旅途……©豆瓣', '王一鸣', '黄雷', 6.3, 9959, 'tt6447462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1850828493.jpg', 4.8, 15.2, 49.7, 22.1, 8.2, '0.201294,-0.106495,-0.510798,0.062840,-0.216944,-0.552930,0.379113,0.149507,-0.595911,-0.349505,-0.022804,0.401732,-0.039341,0.620588,0.092375,0.124657,-0.039628,-0.454633,-0.050121,0.071652,-0.071676,-0.390030,0.144551,0.085508,0.008396,-0.017995,0.228774,-0.172013,0.030917,0.773411,0.322568,0.274279,-0.236712,0.554931,-0.283177,0.050118,-0.143770,0.035705,-0.244827,0.129305,0.273532,-0.048875,0.014368,-0.066374,0.267015,0.122269,0.778640,0.031874,-0.014439,-0.150425,0.255098,-0.301487,-0.099324,0.049380,0.179756,0.180288,0.249943,0.003466,-0.398980,0.277581,0.366236,-0.285131,-0.127343,0.233303,0.106023,-0.085389,-0.690394,0.137823,-0.188910,-0.079303,0.412800,-0.635872,0.425766,0.453641,-0.189948,0.526755,-0.281083,0.358870,-0.383055,0.017037,0.439927,-0.429366,0.481961,0.198268,0.148317,-0.059189,0.425163,-0.033494,-0.534398,0.134311,0.234331,-0.214542,-0.350968,-0.097614,-0.650629,-0.251236,-0.249193,0.042828,0.065674,-0.331395,-0.281080,-0.194539,0.073482,-0.128661,-0.175676,-0.075066,-0.172933,-0.134154,0.651489,-0.748562,0.233020,0.416460,0.442329,-0.507016,0.554381,-0.011804,0.020867,-0.353122,0.206276,0.250061,0.022916,0.319255,0.104181,0.164832,0.033162,-0.035750,-0.494763,0.124277', '3445516', '5977789', '1292219', '1292642');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10569150', '剧场版魔法少女小圆 后篇 永远的故事', '动画', '抱持着帮助他人而化身魔法少女，与此同时却必须背负着残酷的命运。在接二连三的战斗中，善良的美树沙耶加（喜多村英梨 配音）彻底耗尽自己的生命。当她的尸体被晓美焰（斋藤千和 配音）和佐仓杏子（野中蓝 配音）带回时，令她的好友鹿目圆（悠木碧 配音）感受到前所未有的悲伤与痛苦。而从丘比（加藤英美里 配音）那里听说到魔法少女的宿命之说，不禁让她受到前所未有的触动。在杏子的建议下，小圆决定救助沙耶加，而她们即将与最强的魔女之夜（水桥香织 配音）碰面。有关魔女的前途与生命，她们走上一条凶险非常的道路……本片为魔法少女的剧场版，分三部上映，由TV版12话重新编集而成。©豆瓣', '悠木碧', '新房昭之', 9.2, 6495, 'tt2194724', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1957621170.jpg', 0.5, 0.5, 5.8, 24.8, 68.4, '-0.122652,0.116104,-0.370458,0.661858,0.097965,-0.183076,0.784680,0.112417,-0.285762,-0.166898,0.252454,0.701902,-0.281028,0.218807,0.559837,-0.101647,-0.068432,-0.580890,-0.224848,-0.071667,-0.336764,-0.463999,-0.038764,0.009736,-0.356317,-0.492123,1.048385,0.170146,-0.227342,0.306146,0.228877,0.444576,-0.418866,0.364271,0.236520,-0.112776,-0.051521,0.061173,-0.155117,0.244721,0.006358,-0.470937,-0.215618,0.340838,-0.187132,0.214911,0.828499,-0.574510,-0.003933,-0.124108,0.395565,-0.290169,-0.068318,0.091197,0.159261,0.003538,0.301924,0.008471,-0.251542,-0.156584,0.115216,-0.292163,-0.789234,-0.051681,0.046133,0.252716,-0.365505,0.264384,0.034136,0.217487,0.554840,-0.182151,0.046396,-0.003508,0.417304,0.421288,-0.499898,0.010689,0.067581,0.067640,0.597264,-0.011253,-0.021485,0.334834,-0.195227,-0.368042,-0.237918,-0.136722,-0.421489,0.056992,0.226843,0.382969,-0.077496,0.371879,-0.744545,-0.128603,-0.205001,-0.130323,0.055171,-0.392261,0.084985,-0.687888,-0.044831,-0.447787,-0.176141,0.242632,0.547489,-0.358301,0.946104,-0.997144,0.149881,0.309199,0.111112,-0.157834,0.261550,-0.009861,0.178098,-0.351396,-0.070448,0.383941,-0.027674,0.397565,0.236770,0.322437,-0.083867,0.294027,-0.585648,0.488252', '10174444', '25880986', '26759820', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10569151', '剧场版魔法少女小圆 新篇 叛逆的故事', '动画', '宁静祥和的见泷原市，全靠魔法少女鹿目圆（悠木碧 配音）、美树沙耶香（喜多村英梨 配音）、巴麻美（水桥香织 配音）以及佐仓杏子（野中蓝 配音）守护，一次次击败了人类灵魂深处产生的“梦魇”，全力包围着她们最为珍惜的城市、家人和朋友。这一天，美丽女孩晓美焰（斋藤千和 配音）作为转校生来到小圆的班级，小圆她们意外发现，晓美竟然也是魔法少女中的一员。在此之后，五位魔法少女同心携手，解决了梦魇接二连三带来的危机。她们的友情笃深，相处分外融洽，但是晓美却对周遭无时不在的违和感隐隐感到不安。某天，她要求杏子和她去风见野一探究竟，然而两人大费周章，竟然怎么也无法走出见泷原。晓美终于意识到，她和朋友们似乎被某人封在了魔女的结界中。无休止的轮回以及爱欲滋生的幻象，让少女们陷入无休止的混乱深渊……©豆瓣', '悠木碧', '宫本幸裕', 9.2, 17744, 'tt2457282', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151582333.jpg', 0.4, 0.7, 5.8, 23.1, 69.9, '0.068462,0.076921,-0.408908,0.426403,0.074996,-0.056579,0.703186,0.090399,-0.415316,-0.342917,0.224797,0.423021,-0.309670,0.265975,0.479195,-0.059497,-0.171288,-0.624688,-0.183337,-0.164723,-0.261163,-0.302845,-0.143387,0.002547,-0.065615,-0.376451,0.801647,0.040614,-0.122604,0.310341,0.036385,0.365874,-0.580320,0.487508,0.107932,0.088957,0.177558,0.000101,-0.217336,0.123846,-0.269562,-0.277634,-0.329038,0.301250,0.020787,0.090784,0.797163,-0.495335,-0.172610,-0.123222,0.227025,-0.205203,-0.171055,0.170276,0.087607,-0.058347,0.327273,-0.032048,-0.244719,-0.068640,0.073239,-0.162178,-0.536292,0.429198,0.050697,0.265845,-0.193755,0.286069,0.359788,-0.196108,0.307972,-0.180398,-0.026104,0.104171,0.440374,0.388244,-0.549863,0.158798,-0.137601,-0.213099,0.806423,-0.047120,-0.250187,0.306787,-0.280232,-0.401518,-0.299549,0.044098,-0.526297,-0.080352,0.187667,0.465940,-0.109254,0.318990,-0.695899,-0.053843,-0.172086,-0.051366,-0.058921,-0.446628,-0.100215,-0.485641,-0.164828,-0.388059,-0.482449,0.106739,0.216878,-0.199798,0.932023,-1.023476,0.224286,0.452050,0.254722,-0.163103,0.387844,0.180314,-0.063453,-0.250551,-0.259159,0.195942,-0.063685,0.345446,0.396613,0.428876,-0.311649,0.357610,-0.279263,0.162420', '10174444', '1826173', '3811356', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10571509', '如父如子', '剧情', '普通上班族野野宫良多（福山雅治 饰）和妻子野野宫绿（尾野真千子 饰）结婚多年，感情十分要好，两人共同养育着聪明乖巧的儿子野野宫庆多（二宫庆多 饰），生活宁静中处处透露着幸福。令本以为平静生活将一直持续的三人没有想到的是，一通来自庆多出生的医院的电话将这个小家庭卷入了风口 浪尖之上。原来，庆多并非良多和绿的儿子，而是由斋木雄大（利利·弗兰克 饰）和尤加利（真木阳子 饰）的爱情结晶。是朝夕相处的感情珍贵，还是血脉相连的羁绊重要？面对多年前一个小小误会所酿成的后果，良多和绿不知该何去何从。而对于雄大、尤加利和两人亦非亲生的孩子斋木琉晴（黄升炫 饰）来说，他们亦站在了人生的十字路口之前。©豆瓣', '福山雅治', '是枝裕和', 8.7, 140794, 'tt2331143', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2154079590.jpg', 0.1, 0.4, 8.5, 46.6, 44.5, '0.155165,-0.049294,-0.651009,0.667820,-0.091238,-0.226949,0.824748,0.053643,-0.540776,-0.286199,-0.093692,0.848763,-0.121583,0.346860,0.018469,0.100094,-0.035991,-0.697274,-0.224876,-0.057773,-0.059884,-0.701366,-0.266914,0.147069,-0.332850,-0.179617,0.554911,0.099375,0.261811,0.448196,0.372544,0.402667,-0.343130,0.191990,0.007950,-0.042783,-0.087022,0.595153,-0.522571,-0.113833,0.021357,0.027413,-0.064287,0.201460,0.230151,0.097841,0.530078,-0.437905,-0.414814,-0.248120,0.370825,-0.275690,-0.101882,0.140335,0.305679,0.124624,0.464506,0.396003,-0.258784,0.063399,0.311166,-0.127237,-0.630344,0.022033,0.295122,0.014729,-0.648239,0.739140,0.013858,-0.500317,0.173931,-0.240533,0.352347,0.459715,0.247246,0.413334,-0.368309,0.066552,-0.171017,0.013040,0.739248,-0.118861,-0.158845,0.424396,-0.255073,-0.182427,-0.025918,-0.249566,-0.621191,-0.078560,-0.010550,0.292749,-0.087309,0.208507,-0.265710,0.344456,-0.095171,-0.002517,0.266732,-0.525379,-0.228063,0.027149,-0.254339,-0.978001,-0.663168,0.268999,0.084882,-0.372631,0.776304,-0.857297,0.071621,0.089268,0.196580,-0.382381,0.511347,0.177643,-0.089875,-0.278036,-0.134960,0.256879,-0.286646,-0.065477,0.172876,0.041161,-0.070027,0.196276,-0.287447,0.333469', '26354526', '1292219', '24756472', '6425147');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10573695', '太极2：英雄崛起', '喜剧', '在帮助陈家沟成功阻击特洛伊后，痴痴傻傻地杨露禅（袁晓超 饰）和陈玉娘（杨颖 饰）喜结连理。可就在大喜的日子里，陈家大哥栽秧（冯绍峰 饰）携妻子允儿（谢欣颖 饰）回到家中。家人团聚，自是一番旧情重叙，独掌门人陈长兴（梁家辉 饰）对长子的到来心存顾虑，反对天资聪慧的露禅寄予厚望。在此之后，接二连三的不安定悄悄在陈家沟滋生。栽秧向族人说起了铜钟夜响和拳法不传外姓人的渊源，致令全村人视露禅有如洪水猛兽，势将其赶出陈家沟。在栽秧种种险恶用心之后，怀着一颗复仇之心的方子敬（彭于晏 饰）的身影时隐时现。在东西方文明剧烈碰撞的世纪之交，露禅和陈家沟的人们面临着前所未有的生死考验……©豆瓣', '梁家辉', '冯德伦', 5.9, 63420, 'tt2296404', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1743944910.jpg', 6.2, 20.5, 51.5, 17, 4.9, '-0.043996,-0.121571,-0.813602,0.612734,0.071144,-0.075686,0.405664,0.316870,-0.728652,-0.274090,0.215777,0.589183,-0.158771,0.216886,0.106586,-0.185747,0.002884,-0.571330,0.009796,-0.064030,-0.034137,-0.206798,0.132494,-0.061667,-0.086692,-0.324032,0.276601,0.215095,-0.233624,0.567167,0.201454,0.298491,-0.218263,0.276842,-0.189738,0.252177,-0.321592,0.328208,-0.557808,-0.024386,-0.037439,-0.395156,-0.366155,0.044074,-0.139991,0.272851,0.623072,-0.292900,0.020477,-0.150447,0.048104,-0.198195,-0.066533,0.206094,0.208432,0.104117,0.072740,0.474347,-0.229499,0.147090,0.020914,-0.129071,-0.284925,-0.047858,0.287605,0.112744,-0.781711,0.561358,-0.082202,-0.098724,-0.114514,-0.295215,0.251094,0.345069,-0.077980,0.455748,-0.318666,0.037261,-0.423007,0.112983,0.506382,-0.186623,0.120501,0.092256,-0.027707,-0.356920,0.088293,-0.055529,-0.496164,-0.363597,0.488503,0.133698,0.149988,0.466206,-0.362124,-0.081501,-0.074317,0.178414,0.334851,-0.352189,0.061855,-0.467656,-0.173473,-0.552796,-0.223138,0.062492,0.186088,-0.173618,0.837039,-0.761761,0.366426,-0.132627,0.097076,-0.451660,0.356197,0.089100,0.088692,-0.231509,-0.008928,0.005832,0.008503,0.070968,0.024835,0.285229,-0.138376,0.075317,-0.064040,0.211027', '1480318', '35030151', '3445516', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10574468', '北京遇上西雅图', '喜剧', '“败金女”文佳佳（汤唯 饰）曾经是美食杂志编辑，对爱情充满了像电影《西雅图夜未眠》一样的浪漫幻想。而在现实中，为了给自己的孩子一个“美利坚公民”的身份，她不远万里只身来到西雅图的月子中心待产生子。在月子中心，文佳佳炫富的作风引发了房东（金燕玲 饰）和其他孕妇周逸（海清 饰）、陈悦（买红妹 饰）的反感，倍感孤独的她只能向司机郝志Frank（吴秀波 饰）倾诉心声。而看上去木讷老实的“落魄叔”Frank并不是一个平庸的男子，他在中国曾是一位一流的心血管疾病方面的名医。在相处中，Frank的体贴包容渐渐融化着文佳佳的刁蛮任性。当文佳佳的富豪男友突然失踪后，一夜之间变成穷人的文佳佳得到了Frank无微不至的照顾，跟Frank和他的女儿Julie（宋美曼 & 宋美慧 饰）一起生活的这段日子，让文佳佳找到了家的温暖。当经历了变故的文佳佳，生下了孩子，就要结束她在西雅图的颠沛之旅时，她与Frank之间已经产生了微妙的化学变化，这时的她才发现自己真正追求的爱情是什么。离开西雅图并不代表结束，离开是下一次相遇的开始……', '汤唯', '薛晓路', 7.3, 564579, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1878328589.jpg', 1.1, 4.9, 37.2, 41.9, 14.9, '0.387135,0.032943,-0.644136,0.464501,-0.133900,-0.311034,0.875174,0.147216,-0.575754,-0.309942,0.139863,0.800919,-0.290792,0.373563,0.237515,0.224506,-0.118582,-0.798964,-0.136935,-0.066555,-0.256329,-0.334698,-0.062492,0.048021,-0.077354,-0.214604,0.530415,0.039381,-0.216119,0.551094,0.180742,0.188419,0.043380,0.602644,-0.288060,0.156290,-0.164123,0.160573,-0.422589,0.021148,0.312990,-0.269167,-0.174517,0.213796,0.020118,0.205645,0.791057,-0.157001,-0.296472,-0.041109,0.488022,-0.252473,-0.182360,-0.185661,0.014017,0.048546,0.250970,0.077856,-0.125113,0.091515,-0.009060,-0.169829,-0.522826,0.066024,0.171929,0.304336,-0.514705,0.524505,-0.050897,-0.148752,0.129124,-0.333151,0.259900,0.293954,0.060421,0.725760,-0.360628,0.179211,-0.478762,0.331295,0.776383,0.149272,-0.361850,0.560888,-0.276426,-0.365967,0.075600,-0.100168,-0.806742,0.000255,0.097749,-0.058185,-0.301004,0.271200,-0.659335,0.163880,-0.153145,-0.031836,0.124932,-0.392551,-0.124975,-0.438087,-0.174592,-0.664894,-0.260926,-0.042659,-0.030908,-0.377384,0.843718,-1.081219,0.428565,0.341899,0.434181,-0.697834,0.671791,0.173818,-0.019967,-0.164425,0.120457,0.339862,-0.228258,0.188665,0.053417,0.376565,-0.125999,-0.037487,-0.394004,0.448236', '3445516', '1292219', '1308755', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10574474', '勿忘蛛', '剧情', '边见瑞纪（下田麻美 配音）的爷爷拥有一家古书店并且将它出租给了学者砚周（土田大 配音）。一日，瑞记偶然打开了一本名叫《蜘蛛怪异闻》的古书，没想到，一只娇小可爱的蜘蛛娘（金田朋子 配音）从中掉了出来。蜘蛛娘告诉瑞纪自己曾被一个阴阳师所救抚养长大，后又被封印在书中，而砚周就是那位阴阳师的转世。砚周很同情蜘蛛娘的遭遇，收留了她。但一名古籍师告诉砚周，蜘蛛娘是非常危险的生物，只要接近她就会在不知不觉中被迷惑从而丧生。不听劝告的砚周决定将蜘蛛娘送回到她的母亲所在的地方，那是一幢阴森的古宅，里面有一只巨大的蜘蛛正匍匐在黑暗中等待着它的猎物。©豆瓣', '土田大', '海谷敏久', 7.5, 13418, 'tt2345761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1572882137.jpg', 1.1, 3.6, 30.4, 48.4, 16.6, '0.270051,-0.088003,-0.526545,0.670925,-0.232988,-0.144990,0.953941,-0.166335,-0.385553,-0.278854,0.144834,0.644178,-0.132908,0.368709,-0.168015,0.341005,0.217528,-0.312237,-0.240044,-0.267874,-0.425245,-0.187013,-0.411696,-0.210751,0.020527,-0.164467,0.474939,0.161363,-0.216860,0.088418,0.024477,0.295062,-0.275387,0.263822,-0.453650,0.215138,-0.215076,0.041208,0.466171,0.140596,0.115613,-0.382116,0.135819,0.084143,-0.039571,0.047986,0.852622,-0.533838,-0.119651,-0.229214,0.271084,-0.136438,0.089256,0.344329,0.469298,0.106495,0.131853,-0.117778,-0.410345,0.108017,0.067202,-0.299868,-0.778355,-0.056020,-0.050355,0.242555,-0.729537,0.443198,0.120797,0.216822,0.153636,-0.257990,0.395461,-0.016169,0.179729,0.419336,-0.037509,0.159718,-0.426356,0.096808,0.202569,-0.221857,0.028814,0.237244,-0.086842,-0.562224,0.213497,-0.039643,-0.447256,0.057810,0.524202,0.161437,-0.446941,-0.028904,-0.711984,-0.096429,-0.343085,-0.054199,-0.184291,-0.276016,-0.272647,-0.033582,-0.018703,-0.178624,-0.107557,0.242938,-0.035846,-0.360416,0.833225,-0.749784,0.360362,0.423096,0.265637,-0.055845,0.509506,-0.357134,0.068888,-0.050922,0.212211,-0.004906,0.267041,0.354057,0.627010,0.489725,0.133966,-0.212184,-0.444600,0.480603', '21619567', '1467779', '3005387', '21350559');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10574622', '人再囧途之泰囧', '喜剧', '商业成功人士徐朗（徐峥 饰）用了五年时间发明了一种叫“油霸”的神奇产品——每次汽车加油只需加到三分之二，再滴入2滴“油霸”，油箱的汽油就会变成满满一箱。徐朗的同学，兼商业竞争对手高博（黄渤 饰）想把这个发明一次性卖给法国人。但徐朗坚决不同意，他希望深入开发研究， 把“油霸”发扬光大，得到更远的收益。两个人各抒己见，争论不休，一直无果。由于两人股份相同，唯有得到公司最大股东周扬的授权书，方可达到各自目的。当得知周扬在泰国后，徐朗立刻启程寻找。而高博获悉后将一枚跟踪器放在徐朗身上一起去了泰国。飞机上，徐朗遇到了王宝（王宝强 饰），别有心机地想利用他来摆脱对手高博的追赶，可他不仅没甩掉王宝，还成了他的“贴身保姆”……究竟徐朗和高博谁会最终拿到周扬的授权书？而三个各怀目的的人，又将带来一段如何爆笑的泰国神奇之旅？©豆瓣', '徐峥', '徐峥', 7.5, 740975, 'tt2459022', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1793720172.jpg', 1.2, 4.4, 32.6, 43.1, 18.6, '0.178628,0.167347,-0.554829,0.443960,-0.129672,-0.324210,0.286196,-0.112704,-0.326636,-0.095977,0.052843,0.603695,0.004388,0.016772,0.074522,-0.053770,-0.168934,-0.539318,0.108972,-0.237020,-0.231762,-0.499388,-0.152825,-0.223986,-0.091829,0.121059,0.475423,-0.036863,-0.167871,0.253551,0.386751,0.035798,-0.115364,0.399607,-0.218406,0.036832,0.033640,-0.062678,-0.170542,0.448671,0.210243,-0.244564,-0.126090,0.104016,0.172377,0.247510,0.543308,0.037513,-0.111940,0.202932,0.250991,-0.311156,-0.047302,-0.106426,0.022511,0.162968,0.111452,0.164192,-0.434038,0.049761,0.192078,0.139731,-0.665219,-0.134197,-0.068987,-0.206745,-0.602062,0.245450,-0.085555,-0.102391,0.033869,-0.512512,0.339782,0.513084,0.309672,0.194665,-0.142917,-0.201341,-0.632531,0.302370,0.487720,-0.295225,0.123542,0.285502,0.118750,-0.369291,-0.129720,-0.218632,-0.088320,0.022375,0.490054,0.282852,-0.130222,-0.222011,-0.665007,-0.094332,-0.230548,-0.264781,0.296144,-0.295873,0.085420,-0.386859,-0.116640,-0.134250,-0.281907,0.075653,0.193880,-0.323065,0.718081,-0.522750,-0.116354,0.400357,0.165342,-0.579873,0.423589,-0.035840,-0.036891,-0.341593,-0.074338,-0.232522,0.240488,0.192444,0.210104,0.457670,0.017339,-0.260376,-0.302983,0.117451', '1302661', '26678784', '4301278', '301