INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10576419', '蓝色茉莉', '剧情', 'Jasmine(凯特·布兰切特 Cate Blanchett 饰）的丈夫Hal因为商业诈骗罪被捕入狱并在狱中结束了自己的生命，一贫如洗的她只能离开纽约来到旧金山投靠她的妹妹Ginger（莎莉·霍金斯 Sally Hawkins 饰）。从挥金如土的生活瞬间回到普通人的世界，Jasmine精神崩溃了，她经常自言自语，并沉浸在对往日的回忆中，和周围的人格格不入。她不喜欢Ginger的前夫Aguie，更不喜欢Ginger现在的男朋友Chill。Jasmine在一个牙医诊所找到了份工作，同时回到学校上课，但她的生活仍旧一团糟。直到在一个派对上，她邂逅了一个公务员，他风趣英俊又有钱，很快就赢得了Jasmine的心。Jasmine的生活似乎回到了正轨，就在他们准备购买结婚戒指的时候，Ginger前夫Augie的出现又让她的世界昏天暗地......©豆瓣', '凯特·布兰切特', '伍迪·艾伦', 8, 147209, 'tt2334873', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1978807112.jpg', 0.2, 1, 20, 54.8, 24, '0.312424,0.247420,-0.850105,0.513554,-0.560188,-0.391761,0.990043,0.410380,-0.507367,-0.124640,0.172160,0.969750,-0.108171,0.557302,0.350197,0.188282,-0.389976,-0.740144,0.242458,-0.239089,-0.268449,-0.432961,-0.111894,-0.273122,-0.102956,-0.378204,0.542348,0.150728,-0.021989,0.360127,-0.074038,-0.087327,0.180087,0.868934,-0.472565,0.059756,-0.033282,0.281491,-0.045142,0.236295,0.193870,-0.181264,-0.088076,0.224713,0.143739,0.164359,0.928670,0.051447,-0.212786,0.111262,0.402291,-0.224778,-0.291043,0.218753,0.218051,-0.196467,-0.007171,0.073481,-0.388824,0.232989,-0.059545,-0.112688,-0.614212,0.157546,-0.100397,0.188438,-0.715819,0.786418,-0.182676,-0.076080,-0.082167,-0.407646,0.339092,0.468154,-0.017939,0.628535,-0.166369,0.005506,-0.599791,0.364901,0.794408,0.106303,-0.183039,0.720109,-0.267215,-0.418444,-0.220547,0.039184,-0.537518,-0.216954,0.279541,-0.092184,-0.387045,0.125978,-0.778381,0.080908,-0.001252,-0.392093,0.018259,-0.581534,-0.179532,-0.584140,-0.240905,-0.321323,-0.286927,0.178767,-0.021524,-0.235412,0.665626,-1.144943,0.260773,0.615095,0.375708,-0.622660,0.711272,0.135509,0.093616,-0.294715,-0.016953,0.511521,0.111860,0.609410,0.089663,0.368947,-0.184728,-0.012755,-0.537097,0.914007', '1308755', '1309172', '217