INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10577681', '长大成人2', '喜剧', '本片为《长大成人》的续集。为了追忆曾经的美好时光，莱尼（亚当·桑德勒 Adam Sandler 饰）和妻子罗克茜（萨尔玛·海耶克 Salma Hayek 饰）带着孩子们，与朋友们一同回到了曾经生活过的恬静小镇，可抵达目的地后，莱尼才发现，这个小镇早已经不再是他记忆中的模样了。一连串的波折接踵而至，莱尼和朋友们不断的遭受着打击，癫狂的麋鹿、莫名其妙的警察弗卢佐（沙奎尔·奥尼尔 Shaquille O''Neal 饰）、后起之秀安迪（泰勒·洛特纳 Taylor Lautner 饰）等人的出现都标志着莱尼一行人曾经在小镇上的主宰地位不复存在。面对意料之外的剧变，莱尼能够坦然接受吗？在笑容和泪水背后，长大成人的不再仅仅是孩子们。©豆瓣', '亚当·桑德勒', '丹尼斯·杜根', 6.4, 9938, 'tt2191701', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1981955105.jpg', 3.2, 14.7, 48.4, 23.6, 10, '0.261665,-0.102836,-0.688920,0.481429,-0.175355,-0.291516,0.924821,0.184602,-0.790350,-0.174427,0.176186,0.899562,-0.261632,0.721990,0.353036,0.069931,-0.516055,-0.835738,-0.106320,-0.441032,-0.228595,-0.485593,-0.193741,-0.320116,-0.070792,-0.522306,0.550423,0.132828,0.177359,0.637730,0.421926,0.237415,-0.192604,0.404277,-0.326944,0.135818,0.162625,0.052431,-0.383475,0.077728,-0.099099,-0.044642,-0.369467,0.254694,0.013978,0.174835,0.822136,-0.402313,0.018065,-0.085246,-0.079642,-0.386203,0.289582,0.313307,0.205264,0.046874,0.371204,0.319957,-0.079351,0.048002,0.010878,-0.239061,-0.767953,0.207238,0.032853,0.248404,-0.694867,0.459528,-0.063594,-0.243589,0.176730,-0.427928,0.368857,0.442311,0.253675,0.501349,-0.391649,0.072860,-0.489836,0.097696,0.561507,0.092849,-0.135706,0.382029,-0.121158,-0.376481,-0.211466,-0.327245,-0.729115,0.151940,0.190760,0.281182,-0.149120,0.528565,-0.502826,0.056535,-0.266356,-0.453595,-0.036349,-0.344879,-0.268038,-0.747534,-0.206563,-0.574610,-0.478625,0.151897,-0.193523,0.072652,0.884625,-0.846125,0.467998,0.189077,0.183964,-0.379959,0.546388,0.078376,0.072407,-0.126767,-0.174520,0.466407,-0.006857,0.149365,0.294586,0.230023,-0.306640,-0.003294,-0.171005,0.689574', '3111650', '1307146', '3811356', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10577854', '阿呆与阿瓜2', '喜剧', '《阿呆与阿瓜2》讲述了夏利得知自己竟然已经做了父亲，于是与莱特一起踏上一段“寻子之旅”。事实上，那个孩子是一个女儿，这个女儿魅力十足，足以抚慰莱特那可怜的缺少亲情已久的内心。', '金·凯瑞', '博比·法雷里', 6.6, 11783, 'tt2096672', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2188955424.jpg', 3, 13.4, 47.1, 24.8, 11.6, '0.558104,0.016134,-0.752956,0.805366,-0.382915,-0.607633,0.787095,-0.128874,-0.679400,-0.321735,0.017444,0.907598,0.068764,0.639158,0.316933,0.093005,-0.246228,-0.706738,-0.055936,-0.206227,0.106588,-0.528381,-0.299647,0.271480,-0.061737,-0.193163,0.676734,-0.048858,0.265671,0.701732,0.456795,0.279018,0.101407,0.283950,-0.360210,0.570222,0.182458,-0.023629,-0.124763,-0.141520,0.130722,-0.094126,0.206406,0.233133,-0.218200,0.377402,0.635346,-0.326508,-0.060494,-0.506458,0.317192,-0.223417,0.151658,0.152073,-0.097986,-0.001104,0.634012,0.127010,-0.208447,-0.236568,0.149370,-0.057182,-0.941199,-0.098544,-0.038477,-0.237946,-0.836728,0.174463,-0.131561,-0.223634,0.454579,-0.563937,0.546245,0.564526,0.126825,0.643112,-0.544082,-0.175546,-0.255571,0.013291,0.864860,-0.116278,-0.137328,0.437979,-0.034830,-0.240168,0.324079,-0.273135,-0.627325,0.119957,0.227584,0.189959,-0.298777,0.178365,-0.354591,0.064879,-0.351509,-0.099346,0.272502,-0.628721,0.132647,-0.190894,-0.535785,-0.683570,-0.411952,-0.071941,0.045970,-0.282191,0.846591,-0.747505,0.245042,0.254436,0.154612,-0.670672,0.557423,0.343600,0.367855,-0.225036,0.445850,0.483074,-0.290098,0.020720,-0.049456,0.402103,0.129798,0.085699,-0.556758,0.574734', '26283288', '1296569', '26021055', '1850797');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10577869', '时空恋旅人', '喜剧', 'Tim（多姆纳尔·格利森 Domhnall Gleeson 饰）21岁了，他的老爸（比尔·奈伊 Bill Nighy 饰）告诉他，他们家族的男人都有时光旅行的超能力，可以回到过去。于是Tim将信就疑地试了一下，回到了夏天，在那里他试图改变和暗恋对象的关系，却发现怎么穿越时空都不能让不爱你的人爱上你。之后Tim来到了伦敦，成为了一个律师。他爱上了一个漂亮的姑娘Mary（瑞秋·麦克亚当斯 Rachel McAdams 饰），他通过几次时空旅行，努力地想成为Mary的男朋友。再后来，他又试图通过时光旅行，去挽回一场失败的话剧，去改善妹妹的生活，去更好地和亲人、朋友相处，度过生命中的每一天。©豆瓣', '多姆纳尔·格里森', '理查德·柯蒂斯', 8.8, 607646, 'tt2194499', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2070153774.jpg', 0.2, 0.7, 10.1, 37.1, 51.9, '0.064498,0.062920,-0.537770,0.570083,-0.352116,-0.709422,0.717161,-0.048302,-0.343419,-0.014862,-0.160891,0.784469,-0.004728,0.316899,0.278080,0.288727,-0.651140,-0.770927,0.304763,-0.229600,-0.411638,-0.394235,-0.185320,-0.089852,0.146201,-0.305839,0.490497,-0.066182,-0.024564,0.258591,0.059470,-0.024687,0.269478,0.529661,-0.234627,0.259505,-0.006478,0.120677,-0.452128,0.473878,0.295498,-0.084732,-0.118163,0.123406,0.068164,0.072350,0.638000,-0.073755,-0.003477,0.024054,0.174303,-0.136894,-0.037860,0.119031,0.024097,-0.022848,0.154857,0.247446,-0.300864,-0.102462,-0.083580,0.076684,-0.696424,0.126909,0.045783,0.164436,-0.717265,0.583595,-0.176339,-0.129233,0.006097,-0.636023,0.153792,0.429167,0.302635,0.256557,-0.370706,0.064185,-0.627542,0.218147,1.113754,0.106142,-0.061314,0.374890,-0.044388,-0.306697,-0.104176,-0.194510,-0.547740,0.008220,0.294320,-0.176167,-0.355802,0.229401,-0.760817,-0.034282,-0.366097,-0.184924,0.158296,-0.586729,0.175975,-0.328065,-0.000836,-0.150389,-0.475608,-0.013364,-0.105953,-0.699332,0.681793,-0.889171,0.256169,0.855497,0.616892,-0.466127,0.946801,0.199574,0.168011,-0.265673,0.294272,0.327147,0.070658,0.543102,0.127992,0.346900,0.254715,0.011419,-0.517801,0.588163', '4604803', '2124718', '3055049', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10581450', '我爱灰太狼', '喜剧', '阳光明媚的日子里，青青草原上灰太狼（张琳 配音）和喜羊羊（祖丽晴 配音）他们围绕被抓获的懒羊羊（梁颖 配音）又你来我往展开斗智斗勇的对决。正在关键时刻，狼堡发生剧烈震动，接着莫名其妙便被传送到了人类世界某个游乐场内。为了保护灰太郎一家的安全，村长利用看看机将它们变成人类的模样。陌生的人类世界让他们既觉新奇又感慌乱，也由此闹出无数的笑话。可是他们发现一个严重的问题，宝贝儿子小灰灰似乎和他们走失了。另一方面，图谋将狼堡弄来人类世界的邪恶商人皮总正在酝酿一系列充满野心的罪恶计划。灰太郎一家和懒羊羊最终能否重返家园呢？©豆瓣', '赵娜', '朱枫', 4.6, 4619, 'tt11502658', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1643819694.jpg', 40.8, 20.8, 19.3, 7.2, 11.9, '0.081062,0.113908,-0.586986,0.194721,-0.015561,-0.060581,0.683417,0.156723,-0.346444,-0.047048,0.068602,0.534949,-0.450469,0.204077,0.001834,0.026619,-0.294312,-0.512755,-0.034592,-0.214245,-0.160778,-0.207177,-0.479177,-0.434325,0.168327,-0.224237,0.456909,0.230505,-0.238968,0.051102,0.209547,0.030689,-0.381139,0.596884,-0.143238,0.110945,-0.003907,0.088253,0.027609,-0.065275,-0.104366,0.076182,-0.059232,0.140444,-0.112972,0.280437,0.919027,-0.352562,-0.238931,-0.292389,0.276210,-0.267073,-0.153918,0.177888,0.235389,0.055663,0.071490,-0.051228,-0.037308,-0.122275,0.170087,0.009208,-0.702299,0.246555,0.074810,0.108834,-0.054368,0.199518,0.243722,-0.154097,0.263808,-0.194450,0.376170,0.385777,0.666265,0.513630,-0.180880,0.222663,-0.160355,-0.148789,0.663674,-0.243607,-0.169497,0.289135,-0.171260,-0.210874,-0.075230,-0.160135,-0.206320,-0.215332,0.366671,-0.026898,-0.207431,0.187775,-0.881808,0.052509,-0.214070,-0.327527,-0.087680,-0.392327,-0.050048,-0.408183,-0.142954,-0.202745,-0.160462,0.074778,0.138803,-0.155178,0.669018,-0.531150,0.056811,0.731357,0.153949,-0.424468,0.172174,-0.087096,-0.045327,-0.265479,-0.157775,-0.062547,0.132761,0.455660,0.108248,0.315352,-0.032129,0.069784,-0.277784,0.332119', '25774050', '4181031', '26290398', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10581884', '黑海夺金', '惊悚', '《黑海夺金》由裘德·洛主演，讲述了一个潜艇的船长带着自己的队伍奔赴海底，寻找沉没的宝藏的故事。裘德·洛在片中饰演的是一位具有小混混气质的船长。在幽闭的潜艇内部，船长和他的船员都由于压力导致“精神恍惚”。最终，寻宝之旅变成了不是你死就是我亡的生存游戏。', '裘德·洛', '凯文·麦克唐纳', 6.9, 10197, 'tt2261331', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2375734726.jpg', 0.9, 6.7, 47.6, 34.5, 10.4, '-0.036378,-0.349082,-0.469489,0.741499,-0.230508,-0.121945,1.129288,0.074132,-0.287323,0.049563,0.400726,1.034380,0.161253,0.129824,0.357262,0.151835,-0.537912,-0.238614,-0.486680,0.128531,-0.310496,-0.528055,-0.104992,-0.238003,0.255885,-0.478008,0.979235,0.263880,-0.468649,0.449112,0.357005,0.282216,-0.143451,0.523625,-0.244347,-0.099112,-0.019597,-0.147481,0.073252,0.138828,-0.070486,-0.210152,0.217218,0.233295,0.050536,0.437085,0.923358,-0.499415,0.243741,0.086741,0.042247,-0.566579,-0.018941,-0.338567,0.334958,-0.156649,-0.263228,0.154959,0.037128,-0.050646,0.041081,-0.106958,-0.954999,-0.186734,0.189191,0.392619,-0.181249,0.400011,0.041056,0.142271,-0.078769,0.017838,0.336948,0.251771,0.333674,0.254233,0.018843,0.185392,-0.742151,0.481308,0.612213,-0.157908,0.011248,0.446840,-0.191720,-0.788031,-0.242583,-0.520114,-0.501314,-0.207144,0.509927,-0.305923,-0.346464,0.075563,-0.741097,0.270356,-0.083765,-0.577860,-0.344730,-0.291863,-0.141335,-0.525708,0.023072,-0.272108,0.352691,0.190062,-0.169749,-0.290839,0.750999,-0.552862,0.197114,0.960112,-0.104247,-0.708581,0.832430,0.161714,0.027899,-0.309733,0.159217,0.492538,0.004256,0.325256,-0.051145,0.478440,0.121257,-0.062395,-0.431327,0.307531', '2028634', '24879819', '1467779', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10581908', '黄铜茶壶', '喜剧', '学生时代的爱丽丝（朱诺·坦普尔 Juno Temple 饰）是同龄人羡慕的对象，她的相貌和才华让长辈和朋友们有理由相信，充满了美好和成功的未来正等待着她。然而，直到踏入了现实社会，爱丽丝才发现了自己的天真，和约翰（迈克尔·安格拉诺 Michael Angarano 饰）结婚之后，两人的生活质量急转直下，连及格线都难以触及，幸福美满更是无从谈起。就在爱丽丝陷入窘境之时，一只神秘的黄铜茶壶的出现彻底改变了她和约翰的生活，他们发现，这只茶壶能将两人的痛苦转化为源源不断的钞票。想要感到痛苦还不简单，就这样，爱丽丝和约翰在变身富翁之时亦开始了漫漫“求苦”之旅，可是随着时间的推移，两人发现，事件的发展逐渐脱离了他们的掌控。©豆瓣', '阿丽克西斯·布莱德尔', '拉玛·莫斯利', 6.5, 7546, 'tt1935902', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1926968270.jpg', 1.8, 10.1, 57.1, 24.5, 6.5, '0.261593,0.186827,-0.702194,0.510789,-0.211429,-0.320205,0.922068,0.131081,-0.550925,-0.109129,-0.125652,0.898147,-0.420946,0.197397,0.310220,-0.009854,-0.256181,-1.054211,-0.101922,-0.203774,-0.242634,-0.526866,-0.308943,-0.313625,-0.206883,-0.406702,0.670325,0.076882,-0.150255,0.386489,0.063363,0.110609,-0.055741,0.740852,-0.283629,0.102973,-0.010126,0.086819,-0.198307,-0.007709,0.290026,-0.216467,-0.047994,0.328691,-0.060364,0.208347,0.808759,-0.222458,-0.201886,0.066053,0.434666,-0.306553,-0.187090,0.258406,0.188976,-0.088844,0.030706,0.041016,-0.064258,0.003334,-0.021394,-0.082691,-0.831277,0.131376,-0.092952,0.115815,-0.693388,0.510077,0.040405,-0.217212,0.117131,-0.378353,0.206300,0.550272,0.312092,0.425191,-0.216742,-0.213013,-0.581429,0.158929,0.717833,0.094923,-0.522204,0.625799,-0.255183,-0.624034,-0.432551,-0.138670,-0.605924,-0.197272,0.443293,0.497678,-0.235706,0.338326,-0.734481,0.068248,-0.268105,-0.360883,0.055721,-0.477108,-0.058232,-0.424758,-0.338104,-0.659138,-0.591051,0.078754,-0.079995,-0.449342,0.890031,-0.953454,0.218620,0.471619,0.316005,-0.422297,0.829674,-0.060974,0.167507,-0.159581,-0.118095,0.206324,-0.128689,0.350263,0.339209,0.542401,-0.103611,0.011662,-0.393749,0.658778', '30162520', '3230462', '1291577', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10583098', '十二怒汉（电视版）', '剧情', 'This production of ''Twelve Angry Men'', written especially for Studio One, is shorter than the film version and leaves a few twists and turns of plot undeveloped, but it is fifty minutes of class nevertheless. For many years this episode was thought to have been lost. The Museum of Television and Radio (now the Paley Center) had only the first 30 minutes of the hour-long program on a kinescope provided by CBS - the only version CBS had. After nearly 30 years of searching, a copy of the complete program was found in 2003 by filmmaker Joseph Consentino, who was working on a documentary about noted defense attorney Robert Leibowitz (Leibowitz reported on the Charles A. Lindbergh baby kidnapping ', '罗伯特·卡明斯', '富兰克林·沙夫纳', 9.5, 22946, 'tt0122737', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2689773446.jpg', 0.2, 0.2, 2.8, 19.7, 77.2, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000