INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10594958', '爱情不NG', '喜剧', '风头正劲的影帝郑直（信 饰）受邀出演电影《小城往事》的男主演，与急速走红的女星苏妮娜（钟欣桐 饰）上演一段小龙套追求白富美的爱情故事。在参演过程中，早已过惯大明星生活的郑直，对穷小子生活的把握和表现始终得不到好莱坞新晋女导演曼迪·吴（李小冉 饰）的满意。更为糟糕的是，他的表演竟屡被导演批评为不如群演。而一个叫作川子（余少群 饰）的群演，来剧组是为了找回他青梅竹马的恋人三妮。凭借着一张童年照与珍贵的记忆，川子认定当红女星苏妮娜就是他的三妮，小心呵护之余，他用自己的方式向已经有了高富帅男朋友Peter（袁成杰 饰）的苏妮娜表达着爱意。于是，四个不同背景的人在片场发生了一连串的争吵、矛盾，更有不少欢乐与热闹。原来，郑直与导演吴迪曾是恋人，《小城往事》正是那段爱情的纪念。在经历了各种争吵和误会后，两人终于解开心结。在吴迪的点醒下，郑直下决心体验穷小子的生活，与川子等群演混在一起。随着电影拍摄临近结尾，郑直和吴迪，川子和苏妮娜两对恋人都迎来了他们爱情的新开始……', '信', '朱时茂', 5.2, 4451, 'tt3293714', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1852163134.jpg', 17.7, 33, 31.4, 9.8, 8.1, '0.169537,-0.230017,-0.499670,0.647842,0.143747,-0.303846,0.850779,0.004709,-0.317903,-0.196322,0.184382,0.536849,-0.566221,0.399644,0.470558,-0.337515,-0.163528,-0.812114,0.015321,0.050875,-0.085379,-0.424237,-0.291851,-0.031433,-0.197349,-0.149795,0.729148,0.061795,-0.372258,0.343627,0.641692,-0.048899,-0.136180,0.344535,-0.062645,0.227963,-0.006766,0.248212,-0.623926,0.023903,0.213297,-0.224288,-0.264818,0.085563,0.023925,0.227267,0.713823,-0.081658,-0.096650,0.231615,0.476860,-0.142687,-0.012701,-0.116009,0.138314,0.043547,0.403079,-0.034875,-0.053537,-0.010510,0.060892,-0.261634,-0.534507,0.226706,0.277452,0.075095,-0.492014,0.395658,0.068967,0.033967,0.272123,-0.161572,0.154252,0.232502,0.384052,0.306638,0.003971,0.125228,-0.201426,0.617964,0.623341,0.264036,-0.160317,0.633066,-0.302312,-0.417397,-0.342879,-0.056286,-0.677505,0.116809,0.328189,-0.194680,-0.123315,0.158899,-0.540320,-0.093582,0.047546,-0.046296,0.279711,-0.399240,0.066339,-0.793476,-0.510771,-0.599437,-0.166658,-0.096248,0.130358,-0.453249,0.808326,-0.836906,-0.002608,0.244187,0.046411,-0.618235,0.640575,0.220726,-0.052009,-0.288269,0.004174,0.257963,-0.191248,-0.069845,0.164278,0.283681,-0.204783,-0.053989,-0.490643,0.474435', '3811356', '4301278', '25777330', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10594965', '实习生', '喜剧', '年近七十的本（罗伯特·德尼罗 Robert De Niro 饰）曾经是一位精明强干，事业有成的商人，最终，他还是和大部分老年人一样开始了平淡的退休生活。本对忙碌而又充实的过去无比怀念，孤独与内心里蠢蠢欲动的渴望让他做出了重回职场的决定，成为了年轻的朱尔斯（安妮·海瑟薇 Anne Hathaway 饰）手下的一名小小员工。朱利安年纪虽轻却是一家著名时尚购物网站的创办人，为了事业，她牺牲了自己全部的业余时间和感情生活，这份事业带给了朱利安荣耀，却也成为了她肩上沉重的负担，更糟的是，公司董事会已经开始怀疑，朱利安是否能够胜任她目前的职位了。起初，朱利安并没有将年迈又落伍的本放在眼里，然而，随着时间的推移，这位慈祥的长者渐渐成为了她生活中最真挚的友人。©豆瓣', '罗伯特·德尼罗', '南希·迈耶斯', 8, 289968, 'tt2361509', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2260497287.jpg', 0.2, 1.5, 22.5, 49.7, 26.1, '0.170196,0.322585,-0.691990,0.502206,-0.397540,-0.474811,0.817617,0.212509,-0.557734,-0.349748,0.060934,0.758077,0.073392,0.511087,0.312227,0.015986,-0.161378,-0.740692,-0.242348,-0.134426,-0.071399,-0.421370,-0.444066,-0.278753,-0.380350,-0.246615,0.769859,0.292618,0.004916,0.550024,0.294529,0.273988,0.508673,0.616389,-0.351508,-0.101389,0.174694,-0.020012,-0.073119,-0.126937,0.122419,-0.275666,-0.099759,0.305718,0.039641,0.495235,0.381556,-0.021865,-0.257413,-0.100609,0.481669,-0.045300,-0.121175,0.107997,0.209242,0.156967,0.067825,0.165654,-0.351408,0.036211,-0.205211,-0.275569,-1.106960,0.060814,0.036623,0.101441,-0.762628,0.512603,-0.083396,-0.180012,0.121134,-0.272733,0.082404,0.244670,0.160093,0.433984,-0.192883,0.284180,-0.310247,0.388391,0.647535,0.308800,-0.540156,0.348651,-0.563088,-0.372778,-0.065774,-0.474601,-0.406403,-0.215854,0.245926,0.257385,0.086488,0.407450,-0.519932,0.146728,-0.204556,-0.382564,0.091325,-0.529509,0.009856,-0.411573,-0.284018,-0.727400,-0.324142,-0.260684,0.186500,-0.496858,1.039060,-0.855694,0.140369,0.367104,0.216765,-0.625868,0.672150,0.199730,0.294266,-0.085334,-0.155295,0.370392,-0.233585,0.340778,0.140565,0.277598,-0.120753,-0.283342,-0.284818,0.681832', '27602116', '24284209', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10598440', '空中营救', '动作', 'Bill Marks（利亚姆·尼森 Liam Neeson 饰）是一名空警，奉命在一架飞往伦敦的飞机上执行安保任务。在飞行途中，他收到一个未知号码发来的短信，发短信的人对他的一切举动了如指掌，并且要求他向一个秘密账户转账1.5亿美元，否则就会每隔20分钟杀死一名航班上的乘客。Bill意识到事态的严重性，在空姐Nancy（米歇尔·道克瑞 Michelle Dockery 饰）、乘客Jen（朱丽安·摩尔 Julianne Moore 饰）的协助下，试图找出这个发短信的人。但是事情的进展却远远超出了他的意料，本来想拯救众人的Bill，却意外导致了几个人的死亡，他也被其他乘客当作一个劫机犯。Bill是否能够力挽狂澜，即拯救机上的乘客，又洗脱自己身上的罪名？©豆瓣', '连姆·尼森', '佐米·希尔拉', 7.6, 131756, 'tt2024469', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199638985.jpg', 0.2, 1.8, 31.8, 51.4, 14.8, '0.443769,0.207869,-0.556222,0.763578,-0.258590,-0.041014,0.592394,-0.049153,-0.398862,-0.182205,0.348226,0.756151,-0.034168,0.009651,0.448790,0.126264,-0.527609,-0.628029,0.067990,-0.251068,-0.651956,-0.495267,-0.306227,-0.435649,0.133966,-0.212214,0.499459,0.242913,-0.199512,0.442381,0.186204,0.045129,-0.120261,0.776016,-0.076458,0.129710,0.225499,-0.201041,0.195125,0.347849,-0.138267,-0.597498,0.158703,0.506888,-0.013796,0.731562,0.697320,-0.043463,-0.477000,0.194029,0.138458,-0.544785,0.242371,0.087794,0.303485,0.092369,0.026378,0.071340,-0.263228,0.062064,0.146717,0.256663,-0.943330,-0.208029,-0.333692,0.303452,-0.387312,0.199055,-0.631912,0.201881,-0.185558,-0.490951,0.061754,0.337463,-0.100964,0.216939,-0.339387,-0.206493,-0.726418,0.114038,0.611114,0.047385,-0.147998,0.338126,-0.073297,-0.539774,-0.413358,0.002254,-0.466255,0.073560,0.537766,0.096581,-0.134708,-0.116990,-0.362115,-0.073368,-0.349940,-0.524426,-0.396503,-0.479825,-0.082408,-0.598204,0.237454,-0.155441,-0.486477,0.238428,0.311190,-0.137848,0.717406,-0.538040,0.034741,0.830507,0.301359,-0.548754,0.529985,0.128327,0.172710,-0.270292,-0.020049,-0.122211,0.283199,0.571701,-0.107133,0.233222,-0.152902,-0.256061,-0.412519,0.288928', '3785918', '30163500', '25932086', '1293045');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10600271', '圣诞玫瑰', '剧情', '律师陈志天（郭富城 饰）为了追求心中的良知而成为了一名检控官，他接手的第一个案件是一起性侵案：下肢残疾的钢琴女教师李静（桂纶镁 饰）声称在做身体检查的时候遭到了医生周文瑄（张震 饰）的性侵，而李静同时也是周文瑄女儿婷婷的钢琴老师。陈志天坚信李静受到了侵犯，竭尽全力为她讨回公道。而周文瑄也声称自己无罪，并找来了陈志天的前同事薛肇文（夏雨 饰）担任他的辩护律师。这起性侵案在社会上引起了很大的反响，原被告双方原本的生活都受到了严重干扰。然而原告与被告之间有什么不可告人的秘密，这起性侵案背后又有多少不为人知的隐情？徐克监制，香港演员杨采妮执导的首部电影。©豆瓣', '郭富城', '杨采妮', 6.1, 35506, 'tt2928084', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1962923729.jpg', 2.5, 16, 58.6, 18.9, 3.9, '0.241281,-0.166066,-0.479406,0.427156,-0.087188,-0.071962,0.795122,0.471022,-0.574871,-0.263793,0.370246,0.628630,-0.024700,0.117142,0.266188,-0.010231,-0.118289,-0.710320,0.149522,-0.021854,-0.234925,-0.553485,-0.154329,-0.147497,-0.281903,-0.217260,0.626288,-0.229184,-0.326997,0.316609,0.545933,0.096092,0.104769,0.376642,0.207559,0.111607,0.229014,0.094750,-0.230251,0.254714,0.295160,-0.421492,-0.136196,0.185823,-0.215010,0.580041,0.395458,0.167688,-0.253453,-0.217421,0.519252,-0.454300,0.222921,0.316181,0.174292,0.203846,0.382878,0.417783,-0.217780,0.055454,0.280666,0.042030,-0.769737,-0.058953,0.365566,0.284368,-0.297508,0.430020,-0.284030,-0.399459,0.135357,-0.153405,0.247600,0.417293,0.332591,0.126367,-0.355635,-0.101917,-0.439475,0.216396,0.575562,0.084771,-0.007788,0.028463,-0.337058,-0.634208,-0.199815,-0.047569,-0.517144,0.102068,0.056479,-0.072658,-0.252484,0.099582,-0.419108,0.020809,-0.115592,-0.033357,-0.213100,-0.268142,0.274034,-0.581141,-0.195586,-0.354652,-0.319125,-0.167617,0.289492,-0.399584,0.815542,-0.932647,0.264557,0.540639,0.393914,-0.621767,0.504204,0.268544,-0.022424,-0.032247,-0.069841,-0.041887,-0.049822,0.360075,-0.028580,0.200351,0.122692,-0.411104,-0.074186,0.102857', '4301278', '35030151', '1301022', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10604486', '不二神探', '喜剧', '短短几天内，电影明星、舞蹈演员、跳水冠军，三个没有任何关联的知名人士面带微笑意外死亡，在社会上引起不小的轰动。与此同时，擅长搞怪耍宝的热血青年警察王不二（文章 饰）与深藏不露的警队老油条黄飞红（李连杰 饰）搭档破案，惹出不少的乱子，令他们的上司Angela（陈妍希 饰）郁闷不已。某天，地产项目经理王峰（佟大为 饰）微笑死亡，案子交到Angela一组手中。为了尽快扭转警局中的不利局面，Angela、王不二和黄飞红展开全力追查，他们率先从与几名死者都有过交往的女演员刘金水（刘诗诗 饰）入手。而在这一过程中，妖艳鬼魅的戴依依（柳岩 饰）出现，无疑令案情朝向更为扑朔迷离的方向发展。最终真相如何，王不二能否立下奇功？©豆瓣', '文章', '王子鸣', 4.8, 151660, 'tt2644714', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2006870496.jpg', 19.1, 36.4, 34.2, 7.1, 3.3, '-0.030737,0.054558,-0.467078,0.553230,0.219867,-0.071164,0.566365,0.032703,-0.649307,-0.395532,0.045710,0.237316,-0.463196,-0.023801,0.144037,-0.585823,-0.159198,-0.647822,-0.240896,-0.059068,-0.242815,-0.388538,-0.256225,-0.215942,-0.247727,-0.042189,0.405850,0.063577,-0.455806,0.563926,0.605382,0.400476,-0.383559,0.355385,0.209614,-0.010577,0.227725,0.289090,-0.340715,0.130244,0.136107,-0.375214,-0.184914,0.159143,0.057956,0.242144,0.595342,-0.288135,-0.284725,-0.134745,0.477549,-0.274647,-0.081710,0.083529,0.424948,-0.037692,0.067858,0.078280,-0.247929,-0.145070,0.204966,-0.170213,-0.672879,0.115155,0.350323,0.329806,-0.420169,0.033975,-0.224055,0.029088,0.299376,-0.298651,0.267415,0.552824,0.602046,-0.209769,-0.023008,0.144292,-0.341547,0.348527,0.489074,0.428690,-0.214237,-0.245045,-0.131665,-0.514848,-0.305555,0.092231,-0.110762,0.095920,0.547716,0.009505,0.390616,0.026347,-0.154397,-0.126587,-0.013556,-0.050299,-0.068690,-0.301687,-0.127863,-0.569119,-0.073526,-0.597681,-0.318299,-0.029779,0.044772,-0.174866,0.561964,-0.578825,-0.135937,0.003125,-0.105108,-0.408841,0.392967,0.070379,0.149850,-0.469634,-0.455518,-0.127193,0.162546,0.378486,0.139168,0.273483,-0.257812,-0.370769,0.025639,0.115759', '1301022', '1305016', '1432699', '26341750');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10604554', '躲藏', '惊悚', '不知曾几何时，世界上发生了前所未有的灾难。雷（亚历山大·斯卡斯加德 Alexander Skarsgård 饰）带着妻子克莱尔（安德丽亚·瑞斯波罗格 Andrea Riseborough 饰）以及年仅七岁的女儿佐伊（艾米丽·阿琳·林德 Emily Alyn Lind 饰）千辛万苦找到一个避难场所，那里有着充足的食物和能源，简直是可遇不可求的福地。三口人从此躲在地下，时间长达301天，正如雷所说，他们可能是地球上唯一的幸存者。“呼吸怪”是被禁止提及的词汇，它仿佛随时可能出现的恶魔，将一家人的避难所崔毁于一旦。然而不稳定的情绪时刻在三口人之间蔓延，意外状况接二连三出现。在这个隔绝的窒息场所，他们有着永世无法回避的可怕宿命……©豆瓣', '亚历山大·斯卡斯加德', 'Matt Duffer', 6.8, 13303, 'tt2131532', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2280765998.jpg', 1.8, 8.2, 47.5, 33.9, 8.6, '0.156846,0.051104,-0.928457,0.300156,0.020703,0.271021,0.764225,0.092514,-0.758114,-0.199039,0.063626,0.684357,-0.275298,0.187066,0.189756,0.005097,-0.263943,-0.447743,-0.117263,-0.259448,-0.319348,-0.329651,-0.155437,-0.306340,-0.013974,-0.530776,0.423166,0.245032,0.020492,0.170535,0.058070,0.632875,-0.198089,0.529862,-0.142389,-0.144434,0.024132,-0.100761,-0.239670,0.190309,-0.169622,0.023491,0.022912,0.171829,-0.048473,0.146593,0.319829,-0.465504,-0.011071,-0.038388,0.288130,-0.237140,-0.118296,0.094284,0.074005,-0.488406,0.099101,0.063373,-0.297029,-0.024887,0.520119,-0.095179,-0.700782,0.092372,0.284467,0.331364,-0.511754,0.377186,-0.001664,-0.162128,0.065212,-0.415960,0.384833,0.393799,0.287736,0.201487,-0.238897,-0.024274,-0.673173,-0.179185,0.653686,-0.150780,-0.611825,0.151458,-0.453614,-0.386670,-0.368671,-0.320346,-0.597815,-0.192002,0.141627,0.453885,-0.211291,0.428558,-0.379339,-0.090481,-0.170701,-0.262352,-0.055904,-0.254802,-0.491886,-0.625433,-0.078630,-0.391287,-0.269204,0.247370,0.056267,-0.374273,0.531174,-0.607256,0.325644,0.538644,0.218770,-0.199804,0.919929,-0.111449,0.006022,-0.234489,-0.108909,0.404132,0.091938,0.219318,0.154625,0.118307,-0.104346,0.311978,-0.193455,0.623421', '3055049', '1292211', '1296538', '25728612');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10604851', '恶战', '剧情', '上海滩十里洋场，是无数人追梦的乐园……天生神力的青年马永贞（伍允龙 饰）从家乡来到上海谋生，在当时占有上海一半势力范围的老帮派斧头帮治下谋得一份苦工，岂料因同伴窃取斧头帮的鸦片，在后者发难之际与同住贫民区的老铁（洪金宝 饰）将工友救下，为了追踪那批鸦片的下落，马永贞与上海另一半势力范围的主人——新近崛起的龙七（安志杰 饰）不打不相识，并因为受到斧头帮排挤，不得不与同伴们投奔龙七。因秉持母亲的教诲，马永贞无意加入龙七的帮会，但龙七不以为意，反与之结为知交。不久，那批鸦片的真正主人——日本人为了介入上海，利用斧头帮和龙七的矛盾欲置龙七与老铁等人于死地，马永贞忍无可忍，誓要复仇……©豆瓣', '伍允龙', '黄精甫', 6.5, 8941, 'tt2290567', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2163966572.jpg', 3.7, 14.3, 47.3, 24.5, 10.2, '0.050181,-0.005223,-0.412855,0.480667,0.027002,-0.216348,0.598069,0.122226,-0.568270,-0.180003,-0.022755,0.933146,-0.020279,0.256000,0.237911,-0.226953,0.035949,-0.620576,-0.302761,0.026300,0.188658,-0.240775,-0.360836,-0.294277,-0.240402,-0.073948,0.633726,0.500872,-0.369883,0.562426,0.341493,0.614640,-0.665037,0.245556,-0.231397,-0.054949,-0.183771,-0.013394,-0.498311,0.101586,-0.283937,-0.499824,-0.069307,0.185683,0.046124,0.411225,0.615824,-0.233232,0.082731,-0.580877,0.039336,-0.245253,-0.129345,-0.079730,0.507369,-0.150152,0.254742,0.555141,-0.044631,0.027922,-0.041752,-0.145866,-0.923820,-0.055604,0.200716,-0.032246,-0.655583,0.455901,-0.084356,0.135216,0.013055,-0.111237,0.170862,0.645881,0.023194,0.122157,-0.287457,0.062433,-0.540119,0.116550,0.829503,-0.264585,0.218539,-0.225035,0.482602,-0.448186,0.079185,-0.129722,-0.010045,-0.286483,0.376656,0.075736,0.012715,0.012318,-0.847496,-0.277837,-0.110379,-0.028658,0.252384,-0.234711,0.090416,-0.529072,-0.155130,-0.479297,0.113248,0.134664,0.384983,0.054718,0.518504,-0.812049,0.058918,0.363849,0.370930,-1.106321,0.311733,0.074968,0.169268,-0.476725,-0.343793,0.071094,0.501524,0.230590,0.302085,-0.064166,-0.184556,-0.185660,-0.251338,0.033078', '26678784', '1295746', '35151297', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10604892', '四大名捕2', '动作', '多事的追命（郑中基 饰）、铁手（邹兆龙 饰）耍花招，撮合冷血（邓超 饰）、无情（刘亦菲 饰）这对小情人，神侯府上下正其乐融融，空气却传来浓烈的血腥味道，三里之外的城郊老宅，杀人凶案正在发生！四大名捕前往现场，奋力追凶。六扇门接获消息，捕神（成泰燊 饰）也带同姬摇花（ 江一燕 饰）等前来了解案情，双方合并追查，发现此案与六扇门早前追查的几宗灭门案有牵连。悬案未决，六扇门却在碑林发现了捕神的尸体，而此前正是诸葛先生（黄秋生 饰）约捕神在碑林见面，一切线索都指向了诸葛先生。为探明真相，诸葛正我回到碑林查看，没想到却碰到了一位绝迹江湖多年的老朋友。双方对峙之时，四大名捕和六扇门也相继赶到，再生枝节。六扇门将诸葛先生和无情收押天牢。四大名捕群龙无首，名存实亡。此时，王爷（李子雄 饰）忽访天牢，奉皇上旨意要即刻治无情死罪。铁血大牢之内，一场权力、仇恨、爱情、友情的角力就此展开……', '邓超', '陈嘉上', 5.3, 72935, 'tt3341084', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2158164038.jpg', 12.6, 31.1, 41.5, 9.7, 5.1, '-0.114501,0.060807,-0.389358,0.088029,0.218699,-0.006492,0.602353,0.350940,-0.536940,-0.455361,0.265674,0.240815,-0.252947,-0.157147,0.225204,-0.160716,-0.076059,-0.699940,-0.275666,-0.319999,-0.060253,-0.100585,-0.097559,-0.205306,0.104157,-0.000682,0.376250,0.309191,-0.186513,0.474745,0.293076,0.140954,-0.685687,0.287174,-0.011233,-0.075096,0.237358,0.321408,-0.610722,-0.001155,-0.275681,-0.272839,-0.319807,-0.275920,-0.120684,0.410291,0.228234,-0.171745,-0.278497,0.206645,0.034529,-0.282999,0.023788,0.270877,0.449780,0.104068,-0.003459,0.624220,-0.227146,-0.263195,-0.212832,-0.045328,-0.225696,0.125390,0.197202,0.237090,-0.270656,0.381985,-0.527319,-0.045856,-0.070041,-0.371071,0.394148,0.252590,0.338091,-0.180116,-0.079127,-0.179208,-0.447565,0.122548,0.490556,-0.233096,0.144608,-0.200046,0.512019,-0.379279,0.039247,0.041231,0.077829,-0.054934,0.503302,-0.174293,0.215103,0.332359,-0.176211,-0.308943,-0.424017,0.206721,-0.052782,-0.200931,0.147451,-0.573839,-0.432689,-0.045738,-0.315113,0.209403,0.355130,0.066104,0.136384,-0.405650,0.255256,0.118983,-0.035143,-0.595816,0.425830,0.123561,-0.093082,-0.124125,-0.152937,0.028569,0.520541,0.587910,0.134942,0.379618,-0.127207,-0.253026,-0.399401,-0.271390', '26826398', '1433736', '1473074', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10604893', '四大名捕大结局', '动作', '杀害捕神的女杀手在姬摇花（江一燕 饰）的协助下， 利用易容术从六扇门的大牢中逃脱。宋徽宗（苏有朋 饰）为此震怒不已，命令六扇门尽快将其捉拿归案。冷血（邓超 饰）无法坐视不管，执意回到六扇门追查真相，在他的眼中摇花的秘密似乎昭然若揭。与此同时，适逢重阳庙会，宋徽宗以体察民情为名执意微服出巡，群臣劝诫无数，眼睁睁看着皇上出宫，最终宋徽宗突然消失，下落不明。在此期间，冷血遇到了此前决然离去的无情（刘亦菲 饰），两人的关系跌至冰点。为了找到皇帝的下落，冷血和铁手（邹兆龙 饰）、追命（郑中基 饰）相继出动，一连串的纷争搏杀再起……本片根据温瑞安同名武侠小说改编。©豆瓣', '邓超', '陈嘉上', 5.2, 58381, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194662832.jpg', 15.5, 31.1, 39.1, 8.9, 5.4, '0.015366,0.291321,-0.545416,0.469798,0.185426,-0.006491,0.492601,0.221702,-0.330650,-0.418196,0.479291,0.543863,-0.227766,-0.182913,0.218679,-0.352669,-0.129785,-0.476268,-0.418928,-0.399257,0.034572,-0.273203,0.013744,-0.137877,-0.032657,0.021794,0.768858,0.174776,-0.303055,0.640680,0.565107,0.425929,-0.520505,0.430191,-0.145850,-0.052618,-0.063335,0.056456,-0.286883,0.089320,-0.054888,-0.451761,-0.308331,-0.036226,-0.303605,0.200124,0.323798,-0.546059,-0.085580,0.020924,0.272235,-0.260138,-0.182550,0.139869,0.224191,0.305653,-0.119326,0.629352,-0.372184,-0.037205,-0.073494,0.096925,-0.569930,0.044769,0.250418,0.063772,-0.417718,-0.026363,-0.422766,0.076403,0.188001,-0.397996,0.348658,0.241980,0.311081,0.153793,-0.186969,-0.025886,-0.537930,0.253895,0.499973,-0.119613,0.062607,-0.109953,0.354056,-0.110396,0.277226,-0.237154,0.053155,-0.044478,0.538871,-0.012939,0.118007,0.362782,-0.071605,-0.463928,-0.363490,0.042235,-0.088286,-0.169476,0.016609,-0.574558,-0.189015,0.009330,-0.210194,0.042053,0.008487,-0.155450,0.387958,-0.564708,0.225423,0.241068,0.190822,-0.723879,0.353107,0.108608,0.098466,-0.071486,-0.309681,0.237650,0.520500,0.374390,0.032517,0.217711,-0.087359,-0.240838,-0.432826,-0.059991', '1295746', '1297710', '1294693', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10605978', '私人订制', '喜剧', '愿望规划师杨重（葛优 饰）、情境设计师小白（白百何 饰）、梦境重建师小璐（李小璐 饰）与心灵麻醉师马青（郑恺 饰）四人组成的公司“私人订制”，以“替他人圆梦”为自身业务，专门为不同客户量身订制“圆梦方案”，无论客户的白日梦多奇葩、要求多严格，“圆梦四人组”统统来者不拒，甘愿满足客户的任何需求，正如同“私人订制”公司的口号——“成全别人，恶心自己”。一时间，许多怀揣着“奇葩梦”的客户纷纷找上门，私人订制公司也接连面临各种挑战：一心想过“烈士瘾”的陕西女青年（苗圃 饰）、立志追求高雅跟俗“一刀两断”的全球最“俗”导演（李诚儒 饰）、想要当清官“自愿”接受钱色诱惑的司机师傅（范伟 饰）、生日愿望是想变成“有钱人”的河道清洁工人丹姐（宋丹丹 饰）……“寻梦者”络绎不绝，“圆梦四人组”也绞尽脑汁为每一位客户私人订制圆梦方案，过程中发生了许许多多令人捧腹的荒诞事儿，每一位客户也都在最后“梦想成真”。', '葛优', '冯小刚', 5.9, 313060, 'tt2992152', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2159261731.jpg', 7.1, 22.1, 46.4, 18.2, 6.2, '-0.161048,0.047428,-0.260643,0.283264,0.017125,-0.113874,0.297239,0.059006,-0.469904,-0.348929,0.246946,0.612449,-0.121985,0.152719,0.388459,-0.076858,-0.172559,-0.295821,-0.022897,0.063392,-0.021670,-0.291006,-0.004065,-0.297887,-0.147499,0.020878,0.449422,-0.095496,-0.064257,-0.034085,0.748460,0.249775,-0.159906,0.031517,-0.106444,-0.314808,0.183750,0.112399,-0.669657,-0.098338,-0.445548,0.075754,-0.008257,0.058914,-0.072675,0.185864,0.360217,-0.001756,-0.315052,-0.199315,0.593358,0.072760,0.203601,-0.132122,-0.177115,0.329662,0.561201,0.035172,0.004847,0.055389,0.312111,-0.175453,-0.827212,-0.144897,0.492562,-0.121694,-0.339446,0.094123,-0.117428,0.039534,0.105355,-0.267456,-0.077492,-0.048124,0.629468,0.210550,-0.047569,0.138579,-0.288616,0.741760,0.481903,0.223228,-0.038342,0.411202,-0.370519,-0.293228,0.120765,-0.187284,-0.295333,0.069666,-0.128878,-0.089140,0.191537,-0.027877,-0.701140,-0.109509,0.049127,-0.135771,0.221928,-0.192064,0.034027,-0.586558,0.261870,0.056614,-0.034030,-0.002800,0.411981,-0.094074,0.543186,-0.588706,-0.143200,0.484837,0.153309,-0.661827,0.640772,-0.003403,0.209817,-0.335102,-0.186834,-0.247429,-0.075351,0.196370,-0.368685,0.056001,0.166521,-0.222184,-0.085452,0.133917', '25918677', '4301278', '26984538', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10606939', '男人如衣服', '喜剧', '相依为命的母女俩余春天（毛舜筠 饰）和任秋水（吴千语 饰）同为品牌内裤公司擎天的设计师，虽然她们的设计颇受欢迎，但是这家秋水舅舅Hugo（黄百鸣 饰）的公司在运营上出现了问题。关键时刻，他找到了4年前分手的女友——现为某时尚女装品牌的老板缪斯（海清 饰）。缪斯不计前嫌，同意帮Hugo摆脱困境，但条件是擎天必须设计一款名字为“男人如衣服”的女装。为了实现翻盘，Hugo在全体动员的同时，还请来了名设计师Jojo（熊黛林 饰）。Jojo傲慢的态度令秋水母女大为光火，她们提议和Jojo分别设计，最后由缪斯定夺。在这一过程中，秋水此前结识的临时演员阿费（郑中基 饰）和伙伴奥文（林峰 饰）加入进来，令这场对决变得妙趣横生……©豆瓣', '黄百鸣', '谷德昭', 5, 9360, 'tt2255398', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1690508139.jpg', 14.4, 34.2, 39.5, 8.5, 3.3, '-0.070658,0.081277,-0.382231,0.385574,0.044031,-0.431139,0.125368,0.316955,-0.598539,-0.349739,0.268261,0.701044,-0.234187,-0.018172,0.437606,0.057069,-0.345491,-0.654447,-0.070451,-0.096454,0.071205,-0.454382,0.092185,0.064628,0.034895,-0.186712,0.532480,-0.118056,-0.076246,0.591596,0.459641,0.264262,-0.093420,0.149968,0.071770,-0.239133,0.010486,0.200141,-0.707475,0.272405,-0.323549,0.041417,-0.041368,0.102935,0.067231,0.442543,0.411161,-0.086780,-0.102517,-0.096717,0.312745,0.037241,0.099411,-0.029466,0.149813,0.134229,0.369472,0.242330,-0.426419,0.005255,0.227902,-0.282012,-0.679400,0.190606,0.462630,-0.042948,-0.510272,0.182326,-0.363758,-0.003378,0.065505,-0.289352,0.076934,0.226262,0.511060,0.261889,-0.068065,0.323451,-0.612682,0.436491,0.496094,0.238266,0.228556,0.273307,-0.080304,-0.193411,-0.272119,-0.052270,-0.211134,0.127834,0.072930,0.106412,0.211931,-0.037549,-0.807247,-0.302126,-0.043309,-0.014743,0.145923,-0.383961,-0.045345,-0.558816,-0.074140,-0.215137,-0.180021,-0.116314,0.249225,-0.241627,0.603526,-0.923717,-0.245663,0.044253,0.535083,-0.370374,0.669197,0.132979,0.237710,-0.317247,-0.357400,-0.301000,-0.118574,-0.067842,-0.017946,0.324669,0.105990,-0.297654,-0.402791,-0.078614', '4301278', '6858739', '1308237', '1498811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10608242', '女尸谜案', '悬疑', '西班牙的深夜，一名中年男子惊慌失措奔跑在丛林间，最终被一辆公路上飞驰的汽车撞成重伤。警方初步探查得知，此人是某停尸房警卫，他在出事前肯定见过什么恐怖景象。经过进一步调查发现，原来当晚停尸房丢了一具尸体。尸体名叫玛卡·维拉芙尔德（贝伦·鲁艾达 Belén Rueda 饰），是一位呼风唤雨的企业女强人，当天下午乘飞机从洛杉矶回来后不久即因心脏病去世。警方联系上玛卡的丈夫，此时正陪伴情人的亚历克斯（雨果·席尔瓦 Hugo Silva 饰）。他谈论妻子时的冷漠不得不让人对他们夫妻间的关系产生质疑。伴随着诡异肃杀的气氛，真相渐渐浮出水面……©豆瓣', '何塞·科罗纳多', '奥里奥尔·保罗', 7.6, 41623, 'tt1937149', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1725734834.jpg', 0.4, 2.4, 29.6, 50.4, 17.3, '0.202947,0.157670,-0.798184,0.275576,0.089537,0.003253,0.902236,0.246248,-0.782902,-0.410695,0.550331,0.563204,-0.439787,0.051386,0.301762,-0.010782,-0.426512,-0.598249,-0.049889,-0.082759,-0.337322,-0.392263,-0.267703,-0.125520,0.167397,-0.335314,0.362345,0.196187,0.077082,0.623355,-0.005642,0.376450,-0.474901,0.510627,-0.080883,-0.029833,0.424845,0.025350,-0.139507,0.079968,-0.131902,-0.400984,-0.018075,-0.126609,-0.236367,0.447379,0.669607,0.217267,-0.408343,-0.057384,0.384622,-0.032997,0.159415,0.137222,0.594193,-0.054073,0.108127,0.434880,-0.370122,-0.249469,-0.274043,0.301684,-0.348460,0.291661,-0.295869,0.296761,-0.412125,0.169842,-0.280018,-0.046930,0.209176,-0.234811,0.299847,0.338256,-0.239496,0.346117,0.009923,0.250094,-0.530810,-0.052181,0.631708,-0.014892,-0.166302,0.311272,-0.007241,-0.147722,0.027384,-0.010847,-0.169477,-0.112035,0.319485,0.066471,-0.280683,0.121145,-0.338611,-0.212409,-0.428803,-0.152567,-0.097874,0.073215,-0.392904,-0.707121,-0.179020,-0.170461,-0.250932,0.027620,-0.243792,0.054257,0.285469,-0.524230,0.384347,0.278657,0.013966,-0.246370,0.337087,-0.210353,0.095239,-0.291132,0.000821,0.350031,0.293756,0.260657,-0.018097,0.174875,-0.145584,-0.059620,-0.265544,0.242124', '3011051', '10466639', '4724373', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10617163', '杀戒', '爱情', '有“小城普希金”之称的马匹配种站副站长肖立昆（刘烨 饰）出身杀猪世家却有一颗爱好诗歌的心；小城里最美的音乐老师江月娥（倪妮 饰）刚刚结束了一段失败的感情，在这时，她与立昆相遇了。仿若一见钟情的二人迅速步入婚姻殿堂，并有了儿子，看似美满的家庭却是堆积在谎言和秘密之上。婚后的立昆和月娥矛盾日益加剧，而这时，立昆发现了月娥似乎有事情隐瞒着自己且确认了月娥出轨的事实。无法再忍耐和谦让的二人离了婚，开始了争夺儿子的大战。事情的真相随着这场战斗被渐渐揭晓，自己的儿子可能不是自己亲生的，这让童年颇有阴影的立昆无法忍受，在爱与谎言间，他的抉择是……©豆瓣', '刘烨', '章家瑞', 5.4, 11157, 'tt3104228', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1973515273.jpg', 11.3, 29.8, 40.7, 12.9, 5.3, '0.312807,0.040088,-0.802491,0.565657,0.105591,-0.111023,0.873348,0.247554,-0.693532,-0.086609,0.258513,0.651372,-0.250043,0.240089,0.009217,-0.107612,-0.379900,-0.923312,0.096175,-0.357231,-0.214405,-0.478284,0.095851,0.014750,-0.129864,-0.244291,0.635850,0.102084,-0.194930,0.414820,0.311065,0.149109,-0.027901,0.449345,0.008120,0.249498,-0.078418,0.308659,-0.405171,-0.123164,0.162029,-0.173095,-0.291261,0.302552,-0.020961,0.478895,0.638725,-0.469601,-0.262022,-0.032178,0.374808,-0.270850,-0.060346,0.119853,0.169438,-0.010245,0.259516,0.569730,-0.241506,-0.305723,0.101088,-0.179145,-0.515978,0.201019,0.069105,0.197735,-0.715530,0.578533,-0.027649,-0.122510,0.178778,-0.223675,0.274624,0.387496,0.120167,0.539264,-0.369610,-0.045484,-0.642393,0.303611,0.939886,0.165617,-0.258438,0.613180,-0.032891,-0.566992,-0.335301,-0.290264,-0.296085,0.019215,0.299763,0.262909,-0.321322,0.339765,-0.457202,0.122976,-0.134983,0.044935,0.128653,-0.657279,-0.181745,-0.102152,-0.430145,-0.595265,-0.572666,0.058803,-0.082458,-0.307433,0.826780,-1.018389,0.121143,0.367226,0.301465,-0.453094,0.691753,0.346303,0.082732,-0.296193,0.069467,0.217323,-0.515903,0.058407,0.194875,0.246646,-0.047310,0.053393,-0.523131,0.446564', '25721544', '35030151', '1301022', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10617168', '同谋', '剧情', '三十年前双亲遭人杀害，凶手真实身份和行凶动机均是个谜，私家侦探陈强（郭富城 饰）辗转追踪到马来西亚，只为弄清父母的死因。然而与他父母曾有交往的关系人回忆所述前后矛盾，且劝阻他不要继续追查。在此期间，陈强的家也被人入室翻检。在孤立无援的情况下，他求助于当地的私家侦探郑风喜（张家辉 饰），请他协助查找关系人的背景和某些重要人物的下落。郑此刻正为弟弟的事情焦头烂额，但他耐不住陈的激将法，毅然接受委托。但从着手调查的那一天起，各种危险便如影随形。交织着毒品与欲望的罪恶阴影，命悬一线的两位侦探逐渐向当年的真相逼近……©豆瓣', '郭富城', '彭顺', 5.1, 18951, 'tt2927068', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1943448253.jpg', 11.6, 36.6, 41.8, 7.4, 2.5, '0.304025,-0.107903,-0.609839,0.630705,-0.068390,-0.111754,0.575500,0.054013,-0.549992,-0.495070,0.167405,0.507214,0.025985,0.308250,0.076185,-0.124735,-0.227125,-0.770380,0.026406,-0.123896,-0.310630,-0.695251,-0.343713,-0.392749,-0.107922,0.056314,0.471441,0.451351,-0.358563,0.169761,0.315543,0.445594,-0.537497,0.501010,-0.149755,-0.131985,0.017283,0.214560,-0.434536,-0.079678,0.272811,-0.594732,-0.262686,0.194313,-0.043215,0.662615,0.480686,-0.165720,-0.322416,0.045053,0.275993,-0.432034,0.141108,0.236575,0.352142,0.050045,-0.003953,0.488204,-0.298112,-0.141377,-0.115574,0.183469,-0.909549,-0.115761,0.276994,0.175966,-0.657498,-0.160156,-0.454728,0.071566,-0.029695,-0.367814,0.273376,0.453522,-0.022593,0.075516,-0.240112,-0.092854,-0.506851,0.353984,0.674493,0.331316,0.097784,-0.006652,-0.076102,-0.449869,-0.245975,-0.112161,-0.277318,-0.051291,0.293439,0.182363,-0.339196,0.203855,-0.378363,-0.307122,-0.223650,-0.088288,-0.219906,-0.421181,0.009267,-0.440993,-0.306919,-0.313802,-0.230069,0.026662,0.253746,-0.343532,0.486093,-0.541700,0.153766,0.632010,0.112919,-0.863329,0.587436,0.264437,-0.017393,-0.371309,-0.180627,0.190966,0.487875,0.112174,0.112567,0.037773,0.026225,-0.150709,-0.358387,0.010178', '26678784', '1297862', '3670447', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10726941', '窃听风云3', '动作', '本片讲述了香港新界围村陆氏家族在房产开发交易黑幕后的故事。故事开始于村民罗永就（古天乐 饰）醉酒撞死了异姓兄弟陆永远（钱嘉乐 饰），陆永远之妻月华（周迅 饰）从此与他势不两立。罗永就5年后出狱，发现陆氏家族大家长陆瀚涛（曾江 饰）和其女陆永瑜（叶璇 饰），以及女婿（黄磊 饰）已经坐拥新界最大房产公司，而陆家兄弟陆金强（刘青云 饰）、陆永富（方中信 饰）等人则疯狂扩张势力。不久香港房产巨鳄邀请罗永就“共商大事”。同时，神秘人阿祖（吴彦祖 饰）透露给月华一个通过窃听得到的秘密消息，他告诉月华要想在这场欺天阴谋中复仇，就必须按照他的指示去做…… 于是几方势力都开始暗自行动。本片是《窃听风云》系列的第三部，但是除了“窃听”这一核心创意外，故事内容与前两部无关。©豆瓣', '刘青云', '麦兆辉', 6.4, 158457, 'tt3121442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2182457355.jpg', 2.1, 13.8, 54.1, 23.3, 6.6, '-0.106299,-0.040902,-0.512386,0.565621,0.421267,-0.098091,0.230776,0.169475,-0.622703,-0.259393,-0.020951,0.443033,-0.036913,0.087797,0.186934,-0.059664,-0.516871,-0.664152,-0.005535,-0.272252,-0.103237,-0.539758,-0.001948,-0.393383,-0.042702,0.001247,0.591281,0.200718,-0.282303,0.147880,0.460049,0.056341,-0.580579,0.201216,0.054535,0.012185,0.189014,0.190516,-0.697232,0.141584,-0.132084,-0.228197,-0.125570,0.082143,0.114720,0.330325,0.266105,-0.218778,0.003071,-0.183218,0.169496,0.067156,-0.072562,-0.047819,0.349253,0.095708,0.532654,0.591807,-0.302816,-0.023592,0.089234,-0.092408,-0.537861,0.032226,0.400692,0.249977,-0.262742,0.212227,-0.141209,0.070045,0.132502,-0.286127,0.238988,0.246730,0.527450,0.111353,-0.031201,0.027339,-0.343343,0.477990,0.436724,0.015629,0.207110,0.107980,0.325517,-0.222099,-0.273848,0.166974,-0.137309,0.029580,0.348981,0.216247,0.164986,0.398686,-0.539968,-0.185847,0.039023,-0.158502,0.167104,-0.246050,0.315415,-0.706367,-0.360722,-0.010785,-0.012499,0.172836,0.406263,-0.093815,0.550353,-0.535889,0.085635,0.104748,0.361280,-0.815276,0.411368,-0.114827,0.260019,-0.401871,0.124736,-0.165306,0.115546,0.103555,0.101671,0.178114,0.037237,-0.481490,-0.062966,0.138244', '4301278', '26984538', '25918677', '3412882');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10727641', '碟中谍5：神秘国度', '动作', '资深特工伊森·亨特（汤姆·克鲁斯 Tom Cruise 饰）也有百密一疏时刻，他在接收最新任务时遭到神秘组织“辛迪加”的暗算落入对方手中。辛迪加是一支由全球各地前特工组成的秘密组织，此前一直被CIA视为空穴来风。在对方成员伊莎·福斯特（丽贝卡·弗格森 Rebecca Ferguson 饰）的帮助下，伊森逃出生天，并及时向威廉•布莱德（杰瑞米·雷纳 Jeremy Renner 饰）汇报了辛迪加确切存在的消息。然而此时布莱德的日子并不好过，他负责的IMF机构因俄罗斯核弹头等事件遭到CIA指控并责令解散。在得知该组织密谋刺杀奥地利总统时，伊森联系上了老搭档班吉·邓恩（西蒙·佩吉 Simon Pegg 饰）展开行动，并于谜样女郎伊莎再度相会。接下来的一连串事件中，辛迪加的真面目逐渐揭开，而他们也终于显露出真实的目的……©豆瓣', '汤姆·克鲁斯', '克里斯托弗·麦奎里', 7.9, 310989, 'tt2381249', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2263582212.jpg', 0.2, 1.4, 24.9, 52.4, 21.1, '0.092066,0.198654,-0.619193,0.381714,0.158521,0.021498,0.452175,-0.075174,-0.708479,-0.333739,0.067997,0.545661,-0.016099,-0.109826,0.409180,-0.059517,-0.524485,-0.666552,0.058380,-0.325607,-0.179824,-0.610398,-0.369089,-0.382721,0.039284,-0.254187,0.588877,0.003782,-0.252602,0.403152,0.551811,0.567321,-0.275930,0.525569,0.366964,-0.136446,0.436260,-0.305618,-0.438163,0.393863,-0.036920,-0.271467,-0.077983,0.206993,-0.045380,0.519304,0.263750,-0.496838,-0.005533,-0.273545,0.132690,-0.293030,0.179640,0.219131,0.541351,0.173310,-0.012848,0.400658,-0.171665,0.120836,0.012532,-0.099627,-0.701952,-0.008958,0.180782,0.320259,-0.188367,0.148548,-0.503153,0.234788,0.055616,-0.322987,0.067698,0.548343,0.412684,-0.165170,0.007758,0.084748,-0.255985,-0.113500,0.332680,-0.055061,-0.187424,-0.054652,-0.028050,-0.403753,-0.199178,-0.000165,-0.024565,0.109428,0.312867,0.230891,-0.013907,0.451139,-0.345659,-0.191957,-0.484522,-0.253252,-0.146048,-0.196308,0.039565,-0.968751,-0.119057,-0.044228,-0.345991,0.080542,-0.133919,0.022778,0.235717,-0.740171,0.399078,0.622583,0.071542,-0.224782,0.019885,0.078737,0.303257,-0.225601,-0.305162,0.447392,0.495354,0.256243,0.003539,0.029815,0.205319,-0.547408,0.022917,0.088622', '25723905', '2028645', '