INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10727845', '赤足', '剧情', '由埃文•蕾切尔•伍德主演的电影《赤足》，讲述了一个整日游手好闲的公子哥，四处欠债，直至仇家找上门，突然一个精灵般习惯光着脚的女孩的出现，使他的生活发生巨变，开始正视自己对的人生.....', '埃文·蕾切尔·伍德', '安德鲁·弗莱明', 6.8, 5645, 'tt2355495', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2181212816.jpg', 2.3, 11.3, 45.6, 27, 13.8, '0.560912,-0.181726,-0.421370,0.310963,-0.279685,-0.519573,0.901181,0.349563,-0.403339,-0.117903,0.440430,0.858552,-0.257910,0.032782,0.489816,0.106720,-0.177833,-0.901658,0.019465,-0.054830,0.163450,-0.043403,-0.065116,-0.228378,-0.246215,-0.286036,0.522073,-0.147226,0.056318,0.407786,0.103772,0.157650,0.476877,0.101685,-0.023915,0.036207,-0.012189,0.067606,0.139925,0.151667,-0.042729,-0.223901,-0.146449,0.054002,-0.246136,0.304240,1.003065,-0.437912,0.042734,-0.224441,0.615049,-0.182428,-0.209478,-0.087468,0.438101,-0.033603,0.123906,-0.254871,0.108001,-0.150451,0.031880,-0.270086,-0.282294,-0.021981,-0.211718,0.494490,-0.552745,-0.035647,0.197285,0.091231,0.013380,-0.346657,-0.200377,0.148116,0.342265,0.518957,-0.008041,0.244413,-0.105561,0.397651,0.307062,0.193253,-0.357203,0.701035,-0.445253,-0.032509,-0.190628,-0.123066,-0.917181,-0.634207,0.337812,-0.408571,-0.481129,0.326816,-0.507618,0.289305,-0.223526,-0.407285,0.043213,-0.337109,-0.474211,-0.548126,-0.318115,-0.281900,0.034996,-0.096752,-0.026933,-0.150508,0.444504,-0.681455,0.302175,0.877957,0.080134,-0.529154,0.576533,-0.242581,0.116269,0.035032,-0.069206,0.570553,0.263119,0.297221,-0.188566,0.347651,-0.215955,0.326107,-0.134987,0.320007', '4233625', '1309194', '1299248', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10733357', '两个月亮', '恐怖', '在一个黑暗逼仄的空间内，恐怖小说家李素熙（朴寒星 饰）、大学毕业的无业人员崔植浩（金基石 饰）、高二女学生朴仁贞（朴真珠 饰）从昏迷中醒来，他们彼此间互不相识，也不知道何时来到此地。最初的惶恐过后，三人摸索着从这间地下室出来，进入附近的一幢房屋内。屋里设施齐全，极具生活气息，但是却不见其他的人影。他们试图从这片森林中逃脱，然而始终找不到出口。与此同时，诡异的事件相继在他们周围发生，莫名的恐慌席卷每一个人的心头，黑暗中仿佛存在一个杀人犯随时准备夺取他们的性命。在相互提醒之下，他们失落的记忆渐渐复苏，可是那似乎是难以正视的恐怖真相……©豆瓣', '朴寒星', '金东斌', 6.8, 17776, 'tt3037322', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1641715477.jpg', 1.5, 9, 47.7, 33, 8.7, '0.276098,0.328895,-1.133389,0.388235,0.147608,0.096650,1.131622,-0.129403,-0.717253,-0.502893,0.050524,0.438048,-0.270421,0.277213,-0.108683,-0.124587,-0.290042,-0.558291,-0.394157,-0.408699,-0.500853,-0.187200,-0.429232,-0.225563,-0.160927,-0.037203,0.553266,0.743171,-0.158097,0.422504,0.027723,0.251951,-0.589939,0.711321,0.016674,0.006599,0.108208,0.143194,-0.113119,0.075549,-0.134338,-0.368821,-0.141001,0.318581,-0.077423,0.502327,0.663839,-0.257294,-0.077751,0.307747,0.272724,-0.063839,-0.261441,0.288747,0.232098,0.117646,0.167027,-0.180738,-0.262624,0.141252,-0.171567,0.021769,-0.621908,0.142829,0.068170,0.378006,-0.288905,0.162082,0.243155,-0.248160,0.100470,-0.152705,0.342950,0.030803,0.140354,0.360050,-0.251160,0.106208,-0.620823,-0.225024,0.790624,-0.075816,-0.492811,0.161716,-0.259176,-0.504298,-0.252447,0.127797,-0.324187,-0.212409,0.441065,0.585517,-0.049679,-0.038708,-0.671216,0.085588,0.034980,-0.104157,-0.236260,-0.238761,-0.360401,-0.464758,-0.250746,-0.310543,-0.272177,0.263704,-0.308511,0.015230,0.348909,-0.697422,0.405896,0.221459,0.246553,-0.064906,0.612937,-0.307115,0.276281,-0.059478,0.020295,0.288934,0.217704,0.530824,0.215146,0.317246,-0.256710,0.207200,-0.631747,0.302443', '3011051', '26715845', '4724373', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10733376', '逆光飞翔', '剧情', '音乐天分超凡的男孩裕翔（黄裕翔饰）弹得一手好琴，却天生失明。他坚持不参加任何比赛，只希望能拥有像普通人一样的生活。他第一次离家北上念书，遇见热爱跳舞却因故被迫放弃梦想的女孩小洁（张榕容饰）。裕翔能“看见”世界上不被旁人看见的美丽，从未放弃过这个世界。他就像一缕温暖的逆光照进了小洁冰冷的内心，而小洁则带领着裕翔经历了他从未尝试过的冒险。两个看似永不会相交的灵魂，却成为彼此遗失的那份力量。两人身后的那道耀眼的逆光，正温暖着、鼓舞着他们向梦想展翅飞翔。本片改编自真人真事，男主人公黄裕翔本色演出。女主角则由台北电影节、亚太影展双料影后张榕容饰演，两人延续前作的绝佳默契，演绎了一段好友之间互相鼓励、勇敢逐梦的历程。导演张荣吉凭借此片荣获2012年第49届台湾电影金马奖最佳新导演奖，女主角张榕容荣获2012年第49届台湾电影金马奖最佳女主角提名，男主角黄裕翔荣获2013年第7届亚洲电影大奖最佳新演员提名。', '张榕容', '张荣吉', 8.2, 90706, 'tt2368920', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1598751480.jpg', 0.2, 1.3, 19, 49.1, 30.5, '-0.314525,0.093815,-0.666827,0.738098,0.199637,-0.215841,0.563899,0.039607,-0.277909,0.062098,0.225208,0.817873,-0.219426,0.189783,0.249046,-0.101823,-0.170906,-0.791821,-0.219038,0.009866,0.138000,0.079123,-0.427896,0.362918,-0.282065,-0.259302,1.048215,-0.098789,-0.264130,0.523710,0.649921,-0.138524,-0.092853,0.081711,-0.178023,-0.123933,0.232982,0.439809,-0.574039,0.505764,-0.111571,-0.230352,-0.484648,-0.059941,-0.143276,0.026491,0.647433,-0.133736,-0.011501,-0.110261,0.639758,-0.186683,-0.271068,-0.130618,0.036003,0.282387,0.391989,0.168184,0.301967,0.143455,-0.242798,-0.279507,-0.721524,0.079542,0.242930,0.251928,-0.285468,0.262692,0.052193,0.049465,0.071380,-0.118550,0.039133,-0.109689,0.396366,0.179227,-0.237943,0.255713,-0.168949,0.790288,0.681623,0.044037,-0.658003,0.539247,-0.309228,-0.527630,-0.046529,-0.376947,-0.661052,0.291292,0.224649,0.096087,0.070509,0.041277,-0.373130,0.118400,0.065490,0.030765,0.043208,-0.321811,0.326511,-0.655978,-0.107891,-0.221107,-0.232139,-0.077297,-0.115354,-0.539943,0.846422,-0.622450,0.309610,0.514711,0.297527,-0.173946,0.837319,0.328909,-0.074957,-0.274733,0.105390,0.593368,-0.356222,0.083554,-0.077968,0.340852,-0.205896,0.040341,-0.414565,0.638250', '3034