INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10733558', '想爱就爱2', '剧情', 'kim（蒂娜•吉塔勒拉 Tina Jittaleela 饰）和pie（奥密兹•苏查拉特 Aomiz Suchar 饰）跨越了同性恋爱禁忌后，成为了伴侣。一周年后，二人面临着分隔两地实习的境况。Kim去了自己喜欢的山区学习农业，认识了有着同样爱好农业的实习生Yam。Pie去了一直向往的海边学习渔业，被猥琐男热情求爱。距离和思念不断折磨着这对热恋中的情侣，电话成了二人最主要的沟通工具。分别的日子久了，距离的拉锯战让二人中渐生矛盾。Pie的霸道任性和Yam的温柔体贴之间的对比让Tina心境产生微妙的变化，而此时Tina误以为Pie忘记了自己的生日，实习的不顺利更是让她内心对Pie的愤懑情绪不断扩大，二人开始争吵不断，难得走到一起的这份感情因为异地恋面临巨大的挑战…泰国首部女版同性题材爱情电影《yes or no-想爱就爱》剧组原班人马演绎的续集《yes or no2-爱的选择》。', '苏查·玛娜英', '萨拉萨瓦蒂·翁索姆佩奇', 6.2, 30846, 'tt2589640', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1806703157.jpg', 3.2, 17.1, 51.9, 20.1, 7.7, '0.394570,-0.129667,-0.865432,0.746648,0.178941,-0.200581,0.770006,0.240445,-0.371911,-0.009587,-0.134084,0.575061,-0.313648,0.216574,0.244296,-0.084907,-0.213636,-0.927631,-0.271118,-0.033802,-0.263600,-0.410780,-0.078011,-0.104042,-0.231242,-0.312000,0.501509,0.100135,-0.230306,0.666729,0.177090,0.221895,-0.136191,0.548367,-0.004126,-0.132597,0.179633,0.184579,-0.582919,0.144058,0.208104,-0.045044,0.108549,0.302635,-0.022723,0.362890,0.819134,-0.166147,-0.185215,0.132348,0.476059,-0.210690,-0.200574,0.158893,0.231411,0.148942,0.298305,-0.034906,-0.401343,0.042711,0.014084,-0.237000,-0.782814,0.136183,-0.024143,-0.027441,-0.505776,0.685499,0.125233,-0.299243,0.348603,-0.202405,0.224677,0.437039,0.436386,0.589854,-0.199438,-0.060626,-0.130960,0.109257,0.960597,-0.084792,-0.205786,0.524406,-0.580227,-0.242774,-0.154478,-0.360559,-0.474320,-0.362923,0.214436,0.209797,-0.205802,0.264881,-0.753099,0.143447,0.062051,0.048575,0.158282,-0.731434,0.002642,-0.533554,-0.436129,-0.822007,-0.290178,-0.013005,0.092297,-0.324339,0.798960,-0.854956,0.271532,0.680271,0.432966,-0.744452,0.907880,0.457080,-0.016442,-0.325807,0.111742,0.364041,-0.474985,0.240828,0.165094,0.347541,-0.007569,0.152987,-0.480553,0.654829', '1309177', '25777330', '1292338', '10876425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10735399', '弗鲁特韦尔车站', '剧情', 'Oscar Grant（迈克尔·B·乔丹 Michael B. Jordan 饰）和女友Sophina（梅罗妮·迪亚兹 Melonie Diaz 饰）还有四岁的女儿一起生活在奥克兰。2008年12月31日，是Oscar母亲的生日。早上，他像往常一样送女儿上幼儿园，送女友上班。Oscar卖过大麻、入过狱，因为经常迟到被炒了鱿鱼，但他准备在新的一年到来之际努力开始一段新的人生。晚上，大家欢聚一堂，庆祝他母亲的生日，同时庆祝新年的到来。结束和家人的聚会，Oscar带着Sophina还有一群好友，搭上地铁前往旧金山看烟花。2009年1月1日，新年的第一个早晨，狂欢了一夜的他们搭上回家的地铁，Oscar却在地铁上遇到了以前一起呆过监狱的“故人”，他的出现，改变了所有人.....本片根据真实故事改编。©豆瓣', '迈克尔·B·乔丹', '瑞恩·库格勒', 7.4, 7660, 'tt2334649', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2163537343.jpg', 0.6, 3, 33.8, 48.7, 13.9, '0.278032,-0.191080,-0.625691,0.079140,0.040782,-0.255760,0.421981,0.200373,-0.535194,-0.037611,0.034458,0.573961,-0.577699,0.848072,0.583435,-0.144229,-0.527932,-0.625074,0.214616,-0.196606,-0.377256,-0.192713,0.102325,-0.014197,0.322132,-0.066570,0.245646,-0.195199,0.613698,0.821426,0.158960,-0.312624,0.091300,0.406304,-0.434115,0.059231,-0.135732,0.388574,-0.372096,0.333502,-0.107223,-0.312921,-0.185331,-0.210602,0.391973,0.360967,0.532905,0.045319,-0.169043,-0.171278,0.639176,-0.111419,-0.263700,0.040853,0.420139,0.357991,0.262046,0.343899,-0.017555,-0.132235,-0.319605,-0.549807,-0.062746,0.215043,-0.032064,-0.096362,-0.594605,0.719353,-0.010893,0.247582,0.182668,-0.460368,0.383890,0.574292,-0.108675,0.503054,0.082398,0.006488,-0.464887,0.631541,0.826880,-0.329020,0.199581,0.304123,0.133228,-0.010815,0.129106,-0.056461,-0.467416,0.295843,-0.001445,-0.099529,-0.292881,0.077020,-0.609808,0.072881,0.057237,-0.519500,0.448098,-0.149242,-0.267343,-0.873037,0.169377,-0.477922,-0.277765,0.173852,0.203305,-0.273688,0.421775,-0.848192,0.557541,0.494203,0.508016,-0.267022,1.021833,0.027286,0.000046,-0.127839,0.271722,0.083166,-0.142504,0.177519,0.090115,0.365634,-0.068197,0.338520,-0.597030,0.532297', '26687241', '3139191', '1306544', '1296339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10738134', '困在爱中', '剧情', '威廉（格雷戈·金尼尔 Greg Kinnear 饰）是一名作家，他的著作曾经霸占了畅销榜，但现如今，遭遇了写作瓶颈期的威廉脑袋里一个灵感都没有。2年前，威廉和妻子艾丽卡（詹妮弗·康纳利 Jennifer Connelly 饰）离了婚，这段婚姻堪称灾难，但威廉却一直无法从中走出来。但很显然，艾丽卡已经摆脱了过去的阴影，开启了全新的生活。威廉和艾丽卡有两个孩子萨曼莎（莉莉·科林斯 Lily Collins 饰）、鲁斯地（罗根·勒曼 Logan Lerman 饰），父母两人恶劣的关系给两个孩子带来了很大的伤害，在潜移默化之中改变了他们的爱情观。鲁斯地爱上了一个名叫凯特（丽亚娜·莱伯拉托 Liana Liberato 饰）的女孩，虽然知道她已经有了男友却还是抑制不住自己的感情。而萨曼莎则拒绝相信一切稳定正常的亲密关系。©豆瓣', '莉莉·柯林斯', '约什·布恩', 7.5, 13241, 'tt2205697', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1955989032.jpg', 0.6, 3.7, 35.5, 42.4, 17.9, '0.391403,0.152120,-0.629189,0.644931,-0.193562,-0.459939,0.960156,0.005749,-0.478401,-0.431626,0.122672,0.688259,-0.100615,0.233995,0.193352,0.241944,-0.255464,-0.645800,0.203994,-0.276168,-0.530467,-0.577345,-0.513575,0.145309,-0.324428,-0.350928,0.534550,-0.123368,-0.203568,0.435951,0.392865,0.228508,0.255811,0.523697,0.019898,0.368090,0.146960,-0.197431,-0.086223,0.023997,0.135397,-0.040363,-0.074646,0.393022,0.195758,0.463655,0.388489,-0.407276,-0.127637,0.162603,0.333505,-0.114334,-0.146405,0.316968,0.218126,-0.104873,0.238290,0.150620,-0.128631,-0.144438,0.187136,0.022603,-0.805588,0.212213,0.033349,0.246553,-0.637821,0.603022,-0.108494,-0.274755,-0.087069,-0.308138,-0.065320,0.414413,0.252854,0.421079,-0.441452,-0.003357,-0.612946,-0.013822,0.482574,0.100413,-0.478586,0.391315,-0.659732,-0.246377,-0.414594,-0.170907,-0.700670,0.026965,0.372872,0.183626,-0.345564,0.406737,-0.407076,0.105953,-0.436122,-0.079720,-0.204826,-0.485625,0.057994,-0.421957,-0.354201,-0.595391,-0.558309,-0.157382,-0.136781,-0.414558,0.836542,-0.826907,0.277828,0.481877,0.310131,-0.400420,0.686750,0.338348,0.169969,-0.167481,0.065009,0.463199,-0.259021,-0.018521,0.224884,0.597303,0.106341,-0.119297,-0.225862,0.775571', '35158375', '1292062', '24756472',