INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10739401', '红酒烩鸡2', '喜剧', '影片为《红酒烩鸡》的续集，故事发生在上一集结束后的两年，逐渐步出了混乱生活的亨利（蒂尔·施威格 Til Schweiger 饰）和女友卡特琳娜（雅斯明·格拉特 Jasmin Gerat 饰）过上了平静和谐的生活。随着卡特琳娜的怀孕，危机再次来临。工作上，亨利要应付难缠的合作伙伴，在生活上，亨利还得想方设法抚慰女友敏感的心，两头忙活的他感到身心俱疲。可即便如此，卡特琳娜还是离开了亨利，她需要亨利好好的想一想，究竟什么才是生命当中真正重要的东西。与此同时，古灵精怪的玛格达琳娜（爱玛·施威格 Emma Schweiger 饰）和养父特里斯坦（塞缪尔·菲尼茨 Samuel Fintzi 饰）也来到了各自的生活瓶颈处。©豆瓣', '蒂尔·施威格', '托尔斯滕·孔斯特勒', 6.9, 5691, 'tt2194599', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2098906363.jpg', 1.4, 10.5, 43.7, 30.4, 14, '0.379328,0.109696,-0.504391,0.227046,0.098816,-0.488616,0.615436,0.362931,-0.428751,-0.208055,0.179369,0.457402,-0.156419,0.008162,0.448599,0.215610,-0.550713,-0.702560,0.355131,0.025054,-0.183456,-0.365101,-0.496313,-0.174920,-0.088796,-0.474860,0.183784,-0.081867,0.227300,0.195420,0.185081,0.384471,0.156291,0.156906,0.224376,0.088901,0.135959,-0.133689,-0.474053,0.168181,0.107281,-0.080260,-0.220999,0.014217,0.354090,0.272017,0.444464,-0.161242,-0.060196,0.143403,0.330296,-0.268339,0.068807,0.104722,0.025686,-0.206703,0.090004,0.182584,-0.409402,0.216646,-0.229501,-0.209730,-0.699791,0.195300,0.019029,0.310288,-0.560079,0.427659,-0.246964,-0.118429,0.180756,-0.449936,0.013604,0.660735,0.149887,0.388035,-0.130323,0.095377,-0.306562,-0.115168,0.591844,0.281390,-0.229824,0.321864,-0.145942,-0.290315,-0.257795,-0.161254,-0.416907,-0.154760,0.325961,0.344509,-0.041479,0.510342,-0.608268,-0.006366,-0.487415,-0.294212,-0.103884,-0.321601,-0.102586,-0.734791,-0.116025,-0.506565,-0.319661,-0.206132,0.031756,-0.332312,0.479778,-0.754767,0.429717,0.607206,0.023406,-0.090079,0.329514,0.138065,0.264480,-0.254861,0.036066,0.434029,-0.145553,-0.113361,-0.016978,0.389726,0.114865,-0.054086,-0.302007,0.732192', '11541282', '1306723', '3178770', '20277433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10740243', '做次有钱人', '喜剧', '社会底层的年轻人李孟（喻恩泰 饰）长相与房地产大亨唐耀（喻恩泰 饰）极为相似。在唐耀因病住院无法主持公司的情况下，李孟被唐耀的秘书林培（戚薇 饰）找到。李孟打台球被人陷害，凭空有了十万元的赌债。台球厅老板皮蛋（杜海涛 饰）雇佣民工大李（王双宝 饰）、小李（巴多 饰）追债。在前有追兵，后无退路的情况下，李孟只好答应了林培成为唐耀的“替身”，做起了“影子富豪”。但这个替身并没有那么好当，李孟在学习怎样做个有钱人的过程中，发生了一系列的囧事，还充分见识了林培这个魔鬼教官的厉害。同时，李孟还要对付唐耀的妻子秦雨薇（胡蝶 饰）不断的离婚威胁，以及公司二号人物闻鹏飞（曹炳琨 饰）的咄咄逼人。在以唐耀的身份做了一系列的助学、捐车的善举之后，李孟不知道，闻鹏飞所撒下的一张大网，正在向他慢慢张开……©豆瓣', '喻恩泰', '万里', 5.3, 5981, 'tt6964100', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1667032097.jpg', 10.1, 30.7, 45.2, 9.9, 4.1, '0.379010,-0.083938,-0.491605,0.361000,-0.181687,-0.255049,0.579563,0.277384,-0.616613,-0.261241,0.231905,0.598222,-0.119849,0.017842,0.011080,0.017563,-0.224077,-0.596080,-0.059681,-0.116099,-0.206105,-0.519547,-0.113689,-0.069353,-0.103476,0.043267,0.302899,-0.184417,-0.075531,0.154331,0.381113,0.112709,0.077305,0.416956,-0.272202,0.196193,0.128031,0.018928,-0.320129,0.136235,0.146086,-0.379599,-0.245623,0.102370,0.075469,0.420636,0.416889,-0.054901,-0.278072,-0.023864,0.300352,-0.144626,-0.017298,0.018713,0.245293,0.135012,0.200086,0.157366,-0.384376,-0.029007,0.217229,-0.040326,-0.762990,-0.034497,0.185156,0.232798,-0.537206,0.227478,-0.185504,-0.128006,0.072785,-0.517866,0.194894,0.324620,0.164510,0.155766,-0.191630,0.078743,-0.632793,0.422279,0.467332,0.344978,-0.158649,0.338513,-0.176358,-0.467666,-0.110048,-0.159754,-0.355001,0.004320,0.303084,-0.012698,-0.274657,-0.114007,-0.463253,-0.176595,-0.139520,0.032517,-0.244767,-0.267189,-0.292905,-0.396662,-0.357835,-0.472355,-0.150024,0.141177,0.080181,-0.209982,0.469664,-0.796667,-0.090894,0.345984,0.308537,-0.377149,0.411347,-0.039672,0.032633,-0.019791,-0.152277,-0.357697,0.115383,0.392739,0.269618,0.457078,0.179099,-0.444651,-0.012536,0.131044', '1793491', '1783461', '1301022', '1308050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10741220', '布鲁克林', '剧情', '艾莉丝（西尔莎·罗南 Saoirse Ronan 饰）离开了故乡，离开了母亲和姐姐，前往美国寻找更多的机会和更广阔的未来。在神父弗雷德（吉姆·布劳德本特 Jim Broadbent 饰）的帮助下，艾莉丝成为了一名售货员，出色的表现和不懈的努力让她成功获得了主管弗蒂尼（杰西卡·派尔 Jessica Paré 饰）的认可和肯定。之后，艾莉丝结识了名为托尼（艾莫里·科恩 Emory Cohen 饰）男孩，两人之间碰擦出了爱情的火花。一场意外让艾莉丝重回故乡，很快，母亲的种种举动使她察觉，母亲希望自己留在这里，留在她的身边。在母亲的介绍之下，艾莉丝结识了善良的吉姆（多姆纳尔·格里森 Domhnall Gleeson 饰），并且得到了一个很好的工作机会，站在人生的十字路口前，艾莉丝会做出怎样的选择？©豆瓣', '西尔莎·罗南', '约翰·克劳利', 7.9, 113072, 'tt2381111', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2266027536.jpg', 0.2, 1.6, 24, 51.5, 22.7, '-0.029226,0.085831,-0.621750,0.645729,-0.256790,-0.514145,0.554094,0.143592,-0.479498,-0.139314,0.152899,0.925645,-0.074640,0.182497,0.442791,-0.017597,-0.626695,-0.577619,0.252433,-0.139976,-0.313412,-0.602279,-0.301276,-0.151231,-0.137585,-0.380830,0.481272,-0.063797,0.016487,0.451335,0.065006,0.250562,0.136615,0.441421,-0.051318,0.107550,0.283890,0.002072,-0.401718,0.551194,0.258068,-0.039135,-0.101311,0.279566,0.155833,0.219386,0.559034,-0.355903,-0.178528,-0.044477,0.272821,-0.090875,0.411741,0.195686,-0.165286,-0.183658,0.246157,0.062036,-0.378292,-0.105306,0.186834,-0.027571,-0.735962,0.070731,0.194030,0.176073,-0.835701,0.381033,-0.063186,-0.217169,0.357639,-0.435724,0.122738,0.700371,0.381756,0.136799,-0.336411,0.058666,-0.357046,-0.135000,0.656877,0.000655,-0.085529,0.303794,-0.180690,-0.429649,-0.044254,0.223459,-0.505848,-0.069036,0.483392,0.054518,0.174625,0.212652,-0.617355,-0.317728,-0.388162,-0.088869,0.078908,-0.532565,0.107707,-0.606140,0.031878,-0.251218,-0.445403,-0.172058,-0.134673,-0.505235,0.719898,-0.894211,0.286394,0.345384,0.546878,-0.369725,0.709529,-0.011086,0.476000,-0.257899,0.094552,0.593124,0.102591,0.081604,0.017094,0.294966,0.041320,-0.078382,-0.387630,0.488661', '35048413', '26971054', '1292720', '26387939');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10741643', '我的个神啊', '喜剧', '贾古（安努舒卡·莎玛 Anushka Sharma 饰）意外邂逅了名为萨弗拉兹（苏翔特·辛·拉哈普特 Sushant Singh Rajput 饰）的男子，趣味相投的两人很快走到了一起。然而，萨弗拉兹是巴基斯坦人，他的国籍和信仰令这段恋情遭到了贾古家人的极力反对。不仅如此，贾古父亲信仰的教主塔帕斯维（沙鲁巴·舒克拉 Saurabh Shukla 饰）更是预言萨弗拉兹注定要欺骗和抛弃贾古。为了证明预言的荒谬，贾古决定同萨弗拉兹闪婚，然而，婚礼当天，贾古等到的却是一封分手信。心碎的贾古回到了家乡，成为了一名记者。一次偶然中，贾古遇见了名为PK（阿米尔·汗 Aamir Khan 饰）的男子，让贾古感到惊讶的是，PK竟然声称自己是一名外星人，因为宇宙飞船的钥匙被人抢走，所以流落至地球。刚开始，贾古以为PK在胡言乱语，不过，之后发生的种种令贾古开始相信PK所言，贾古甚至决定帮助PK寻找返回他的星球的方法。', '阿米尔·汗', '拉吉库马尔·希拉尼', 8.4, 351422, 'tt2338151', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2243803873.jpg', 0.3, 1.3, 14, 45.7, 38.8, '0.300629,0.025101,-0.799950,0.470471,0.173536,-0.284247,0.414660,0.102724,-0.429634,-0.392270,-0.041294,0.736197,-0.299197,0.086402,0.674364,0.031578,-0.242318,-0.666660,0.217572,-0.432738,-0.242353,-0.775311,-0.011060,-0.194340,-0.135893,-0.731019,0.241595,0.326890,-0.157870,0.551225,0.396769,0.637412,0.065824,0.308274,-0.051195,-0.012469,0.116753,0.020713,-0.232295,-0.082082,0.131392,0.071292,0.075031,0.417001,-0.021907,0.426309,0.322905,-0.515456,0.047435,-0.029249,0.338324,-0.330025,0.092113,0.111860,0.124832,-0.069693,-0.022984,0.147392,-0.322267,-0.134034,0.388335,0.031501,-0.597656,0.152132,0.000740,0.034524,-0.504559,0.167671,-0.217238,-0.027930,0.121546,-0.119433,0.398604,0.423705,0.360564,0.180718,0.066980,-0.074869,-0.328907,-0.052257,0.778169,0.108024,-0.182428,0.322606,-0.135752,-0.372337,-0.090398,-0.064484,-0.336054,0.441314,0.342384,0.133446,0.005504,0.364007,-0.385697,-0.463879,-0.619906,0.012610,0.282335,-0.358243,-0.150471,-0.518844,-0.158278,-0.052892,-0.145503,0.129653,0.040113,-0.347975,0.455564,-0.644505,0.106014,0.300896,0.288078,-0.557690,0.470266,-0.099108,0.081066,-0.264914,0.179011,0.346438,0.437973,0.058807,0.010382,0.120581,0.050521,-0.097937,-0.304640,0.319490', '1302987', '25908042', '1916995', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10741834', '复仇者联盟2：奥创纪元', '动作', '托尼·斯塔克（小罗伯特·唐尼 Robert Downey Jr. 饰）试图重启一个已经废弃的维和项目，不料该项目却成为危机导火索。世上最强大的超级英雄——钢铁侠、美国队长（克里斯·埃文斯 Chris Evans 饰）、雷神（克里斯·海姆斯沃斯 Chris Hemsworth 饰）、绿巨人（马克·鲁弗洛 Mark Ruffalo 饰）、黑寡妇（斯嘉丽·约翰逊 Scarlett Johansson 饰）和鹰眼（杰瑞米·雷纳 Jeremy Renner 饰），不得不接受终极考验，拯救危在旦夕的地球。神秘反派奥创（詹姆斯·斯派德 James Spader 配音）逐渐崛起，超级英雄们必须重新集结，竭力阻止奥创实施人类灭绝计划。战斗中，复仇者联盟成员们还遇到了两个新人物——旺达·马克西莫夫（伊丽莎白·奥尔森 Elizabeth Olsen 饰）和皮特罗·马克西莫夫（亚伦·泰勒-约翰逊 Aaron Taylor-Johnson 饰），以及以全新面目归来的老朋友——幻视（保罗·贝坦尼 Paul Bettany 饰）。世界秩序濒临崩溃，复仇者联盟必须阻止奥创的阴谋。强敌不断出现，一场空前绝后的全球浩战即将展开……', '小罗伯特·唐尼', '乔斯·韦登', 7.5, 480674, 'tt2395427', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2237747953.jpg', 0.9, 4.3, 33.3, 41.8, 19.8, '-0.075428,0.271111,-0.343325,0.220827,0.389513,-0.234575,0.358698,0.081608,-0.142573,-0.511096,0.265260,0.522749,-0.135081,-0.094276,0.301660,-0.249434,-0.551994,-0.410435,0.124711,0.133521,-0.270714,-0.433744,-0.707713,-0.287180,0.031670,-0.464505,0.660596,-0.000969,-0.190915,0.121730,0.532063,0.699258,-0.089268,0.149544,0.308352,-0.181205,0.558095,-0.456884,-0.606588,0.269020,-0.328656,0.264196,-0.101411,0.394305,-0.185917,0.211921,0.200487,-0.629736,0.455062,-0.521021,0.168152,-0.276259,-0.038817,0.019988,0.232709,-0.242843,-0.054987,0.155804,0.277174,0.109156,0.147811,-0.373603,-0.691579,0.107203,0.094911,0.230705,-0.362406,-0.128533,-0.248110,0.377379,0.192138,-0.107532,-0.189745,0.326100,0.643886,0.046497,-0.001843,0.232710,-0.387187,-0.048471,0.328515,-0.024920,-0.457830,-0.059643,0.135987,-0.334815,-0.205226,-0.311550,-0.349647,0.082508,0.371107,-0.103556,0.371970,0.671952,-0.854572,-0.256905,-0.690948,-0.145506,-0.188277,-0.115656,0.145995,-1.036630,-0.111012,0.114228,0.093962,0.215417,-0.179333,-0.004510,0.658071,-0.623717,0.260780,0.262115,0.030304,-0.150050,-0.000099,0.059046,0.373556,-0.708686,-0.100504,0.334776,0.058490,0.014094,-0.038710,0.062740,0.090126,-0.196459,0.056318,0.450424', '4014397', '6517421', '2369613', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10742456', '雷诺阿', '剧情', '故事发生在1915年的法国，著名的印象派艺术家雷诺瓦（米歇尔·布盖 Michel Bouquet 饰）已经步入了人生的晚年，妻子的去世，身体上的病痛，加上儿子让雷诺瓦（樊尚·罗蒂埃 Vincent Rottiers 饰）在战争中身负重伤，这一连串的打击让年迈的雷诺瓦日渐消沉，一蹶不振。就在此时，一位名为安蝶尔（克丽丝塔·泰瑞特 Christa Theret 饰）的模特出现在了雷诺瓦的生命之中，安蝶尔的年轻和美丽让雷诺瓦的生命再度轮转到了春天。之后，让雷诺瓦回家养伤，他震惊于安蝶尔的美貌，对其一见钟情，然而，让雷诺瓦没有想到的是，他炙热而强烈的感情却令父亲再度坠入了痛苦和焦灼之中，雷诺瓦将这份痛苦转化成为了创作的动力，一幅幅美轮美奂价值连城的艺术精品从他颤抖的手下诞生了。©豆瓣', '米歇尔·布凯', '吉尔·布尔多', 7, 7251, 'tt2150332', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1949191880.jpg', 0.7, 6.3, 46.6, 33.8, 12.6, '0.058468,0.200897,-0.998532,0.704957,-0.156242,-0.401514,1.258348,0.216525,-0.627848,-0.101185,0.272893,0.930590,-0.408183,0.398229,0.317741,0.045830,0.049318,-0.801487,-0.298712,-0.043956,-0.391798,-0.380468,-0.293101,-0.107949,-0.170515,-0.723836,0.667761,0.286910,-0.128127,0.586599,0.164915,0.450457,0.167226,0.489788,-0.230180,0.038084,-0.013563,0.150128,-0.059686,0.217227,0.194599,-0.559652,-0.008732,0.395855,-0.335345,0.197262,0.757787,-0.295295,-0.131899,0.101196,0.652690,-0.219387,-0.163658,0.211283,0.085997,0.166153,-0.117382,0.076087,-0.624994,-0.090900,0.011907,-0.148038,-0.952783,-0.058174,0.074112,0.215595,-0.817815,0.714869,-0.015004,-0.271729,0.133577,-0.261637,0.507226,0.267692,0.085241,0.776882,-0.208512,0.150765,-0.358158,0.393919,0.578845,-0.084478,-0.583356,0.541467,-0.348289,-0.278887,-0.117975,-0.384666,-0.540886,-0.059683,0.356600,0.329877,-0.076428,0.318469,-0.642078,-0.042368,-0.328525,-0.377454,-0.188658,-0.266404,-0.239113,-0.294427,-0.471480,-0.506371,-0.352421,0.090742,0.129685,-0.294551,1.002971,-0.677243,0.522552,0.501293,0.217548,-0.222381,0.762671,-0.077716,0.047782,0.140367,-0.017117,0.569608,-0.161272,0.197206,0.149575,0.469589,-0.094873,0.093998,-0.584519,0.878355', '26884422', '4724586', '1303077', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10743974', '奥林匹斯的陷落', '动作', '白宫，特情局秘密代号为“奥林匹斯”，目前正处在危机之中，一伙恐怖分子先用重型的飞机和机枪袭击了这里，随后便派入了一群敢死队进入，他们彻底占领了美国总统府，劫持了美国总统，并以此为要挟，妄图控制世界格局。坐在文员办公室的迈克·班宁（杰拉德·巴特勒 Gerard Butler 饰）从这次袭击中活了下来。班宁原先是一个特种兵，负责第一夫人和美国总统（艾伦·艾克哈特 Aaron Eckhart 饰）的安危。但是在一个圣诞节的例行任务中，他的工作出了错，造成了第一夫人的死亡。后来，班宁就被调整到了文职工作上。临时政府迅速派遣美国突击队登陆白宫，企图营救总统，却被恐怖分子控制的白宫防御系统击退，营救计划几度失败。眼看恐怖分子的阴谋即将得逞。因为意外，班宁活了下来，他与临时政府取得联系，并孤身一人营救总统，班宁成为了整个美国的最后一丝希望。这位前特工依靠自己过硬的身手，在危机密布的白宫只身力挽狂澜，率先拯救了总统的儿子，让总统摆脱后顾之忧，恐怖分子获得地狱犬密码的阴谋被延迟。经过艰苦的鏖战和激烈的厮杀，班宁拯救了被劫持的总统，并粉碎了恐怖分子企图利用核弹毁灭美国的阴谋……', '杰拉德·巴特勒', '安东尼·福奎阿', 6.5, 70807, 'tt2302755', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162364777.jpg', 2.2, 11.2, 53.9, 25.8, 6.9, '0.113367,0.319171,-0.650184,0.483777,-0.069258,-0.122854,0.486440,0.037403,-0.420809,-0.218632,0.275454,0.692615,0.018163,-0.087851,0.385823,-0.040414,-0.503614,-0.731262,-0.327451,0.045334,-0.498416,-0.431811,-0.441303,-0.319796,0.093783,-0.222307,0.785385,0.356479,-0.305373,0.338001,0.215536,0.302590,-0.066524,0.565765,0.169409,-0.184506,0.362961,-0.335669,-0.367355,0.539737,-0.119997,-0.467377,0.130810,0.424688,-0.070768,0.624892,0.529242,-0.336254,-0.027655,-0.382210,-0.014473,-0.561390,-0.082686,0.209209,0.433116,0.008702,-0.233075,0.258216,-0.111735,0.114137,0.072999,-0.068441,-0.829614,-0.029453,-0.173839,-0.075202,-0.479832,0.339908,-0.383119,0.351206,0.003124,-0.092972,0.297903,0.664114,0.052938,0.266067,-0.337234,0.297415,-0.483163,0.023890,0.684702,-0.289487,-0.298507,-0.126975,-0.011600,-0.364445,0.101912,-0.417241,0.034339,-0.198859,0.455887,-0.161225,-0.036957,0.195080,-0.561743,-0.086959,-0.707906,-0.254138,-0.293987,-0.379856,0.274161,-0.813986,-0.047778,0.192968,-0.062430,0.164552,0.047328,0.032740,0.359270,-0.582630,0.178588,0.799577,0.323470,-0.494655,0.299704,0.248770,0.248065,-0.240833,0.075344,0.147032,0.187540,0.787159,0.098068,0.252808,0.043570,-0.416132,-0.193893,0.124905', '5157137', '5151890', '6532822', '1309112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10744976', '附身', '悬疑', '1985年，浓雾笼罩的郊外，周日早晨少女丽莎·约翰逊（阿比盖尔·布蕾斯琳 Abigail Breslin 饰）被弟弟罗比（Peter DaCunha 饰）吵醒。她颇感烦恼地起床，按照妈妈（米歇尔·诺尔顿 Michelle Nolden 饰）的指示洗衣服，爸爸布鲁斯（彼德·奥德博拉治 Peter Outerbridge 饰）则在地下室修着汽车。看似平凡无奇的普通人家，却弥漫着诡异神秘的气息。不知曾几何时，丽莎发现每天重复着同样的内容，家人反复干着同样的事、说着同样的话、度过同一个浓雾笼罩的周末。她尝试改变这一切，然而无从下手，此外更有带着死神气息的男子警告丽莎不要破坏当前的一切。无法忍受折磨的丽莎，不可避免落入过去、现在和未来的夹缝中，局势完全失控……©豆瓣', '阿比盖尔·布雷斯林', '文森佐·纳塔利', 6.8, 7986, 'tt2345567', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2067626806.jpg', 2.1, 9.5, 45, 32.6, 10.7, '0.325752,-0.067491,-0.579341,0.395375,-0.035101,-0.095610,0.894886,0.359795,-0.474016,-0.599253,0.362680,0.177631,-0.171825,0.173731,0.352163,0.196781,-0.558319,-0.417546,0.018574,0.115667,-0.163315,-0.452275,-0.026005,-0.035994,0.223157,-0.391980,0.256340,-0.128475,0.059343,0.406135,-0.106337,0.206083,-0.022921,0.407862,0.228484,-0.082054,-0.069806,-0.137500,-0.335115,0.113594,0.123930,-0.038230,-0.175381,0.121264,-0.048715,0.223256,0.578248,-0.348757,0.060874,0.126467,0.441643,-0.264396,0.002608,0.135162,-0.076988,0.009028,0.149288,0.025836,-0.393872,-0.042041,0.141822,0.258624,-0.467755,0.280715,0.116819,0.439407,-0.284728,0.256362,-0.017889,0.022364,0.111797,-0.497114,-0.029778,-0.013687,-0.020234,0.471116,-0.080868,0.016079,-0.592224,-0.199285,0.411407,-0.154021,-0.301991,0.136208,-0.413671,0.204768,-0.015408,0.039951,-0.700580,-0.029870,0.033470,0.232021,-0.300056,0.581172,-0.444502,-0.086456,-0.141671,-0.458957,-0.158177,-0.380527,-0.472750,-0.490698,-0.210021,-0.243240,-0.271658,-0.017298,-0.087231,-0.083134,0.265563,-0.664942,0.360669,0.499932,0.219069,0.089113,0.343566,0.150223,0.140880,-0.230987,-0.249650,0.446023,-0.010749,0.281808,0.216405,0.357098,0.012439,0.129476,-0.417378,0.549238', '1305666', '1292528', '1419992', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10745397', '已经开始想你', '剧情', '杰西（德鲁·巴里摩尔 Drew Barrymore 饰）和米莉（托妮·科莱特 Toni Collette 饰）是从小玩到大的亲密好友，两人有着共同的童年回忆，彼此早已经成为了对方的一部分，密不可分。长大后，两人的友谊依然继续，米莉结了婚，有了两个可爱的孩子，生活在幸福和美满之中，这令杰西十分羡慕。杰西也想和丈夫共同养育他们的孩子，只是一直不能如愿，在米莉的鼓励和陪伴之下，勇敢的杰西终于在经历了多次失败之后顺利怀孕，圆了自己做母亲的心愿，然而这时，米莉却被确诊患上了癌症。无法接受这一事实的米莉陷入了绝望之中，开始自暴自弃，杰西及时挺身而出，成为了好友最坚实的后盾。©豆瓣', '德鲁·巴里摩尔', '凯瑟琳·哈德威克', 7.7, 12335, 'tt2245003', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2272962818.jpg', 0.4, 2.6, 29.6, 46.2, 21.1, '0.229210,-0.024875,-0.832926,0.327839,-0.143464,-0.610399,0.826059,0.129919,-0.784062,0.065887,-0.025260,0.799049,-0.155181,0.495436,0.220464,-0.076734,-0.455589,-0.766845,0.260344,-0.102128,-0.202523,-0.632679,-0.266721,-0.102339,-0.368371,-0.511014,0.569848,-0.240189,0.380229,0.522099,0.198139,0.420545,-0.090825,0.443771,-0.108976,0.299455,0.438996,-0.010340,-0.550725,0.083651,0.226082,0.109479,-0.162484,0.260580,-0.082939,0.153109,0.390586,-0.341968,-0.187665,-0.098660,0.119985,-0.242464,-0.122936,0.459724,0.125637,-0.042218,0.611680,0.123276,-0.366444,-0.221799,0.137407,-0.045524,-0.929642,-0.147721,0.327311,0.138869,-0.663471,0.581174,-0.156539,-0.479013,0.334907,-0.519123,-0.013032,0.904913,0.399358,0.535585,-0.567473,0.103408,-0.269870,-0.100683,0.948663,-0.013351,-0.549674,0.508513,-0.325439,-0.218430,0.075992,-0.229224,-0.656330,0.087156,0.487936,0.316259,-0.385245,0.513005,-0.503588,0.021521,-0.569586,-0.152059,-0.017813,-0.591281,0.075778,-0.369155,-0.289675,-0.638992,-0.690043,-0.086074,-0.192998,-0.460839,1.016449,-1.105915,0.442606,0.223990,0.465475,-0.139653,0.640672,0.234800,0.459851,-0.163053,0.167701,0.396126,-0.225840,0.055233,0.503402,0.458805,-0.094123,0.372255,-0.500851,0.556621', '35030151', '1292219', '1296569', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10745399', '迷途知返', '剧情', '一个夏天，14岁的少年Duncan（连姆·詹姆斯 Liam James 饰）跟着妈妈Pam、妈妈的男朋友Trent还有Trent的女儿一起去Trent在海边的小屋度假。像大部分离异家庭儿女一样，Duncan不喜欢妈妈的男朋友。Duncan发现自己和Trent的朋友们格格不入，原本就沉默寡言的他变得更加郁郁寡欢。直到他在一次单车出游中遇见了Owen（山姆·洛克威尔 Sam Rockwell 饰）。Owen是当地水上乐园的工作人员，在Owen的介绍下，Duncan成了水上乐园的一个兼职员工。在那里，他认识了新的朋友，度过了欢乐的时光，同时也和邻居家同样遭受家庭问题困恼的女孩Susanna（安娜·索菲亚·罗伯 Anna Sophia Robb 饰）越走越近。在一个夜里，Duncan发现了Trent的秘密，他和家庭的矛盾也越来越深.....©豆瓣', '连姆·詹姆斯', '奈特·法松', 7.6, 8513, 'tt1727388', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1979072628.jpg', 0.7, 3.1, 29.9, 48.6, 17.7, '0.513215,-0.388926,-0.688224,0.407505,-0.266868,-0.363583,0.907432,0.355139,-0.513155,-0.156776,0.168198,1.070814,-0.090147,0.561039,0.351584,0.082126,-0.440822,-0.526148,-0.037823,-0.147118,-0.294404,-0.519717,-0.213853,-0.096205,0.001191,-0.268815,0.410780,-0.140485,0.192012,0.526451,0.217649,0.050229,-0.089413,0.596984,-0.299757,0.096876,0.305717,0.117258,-0.122117,0.179810,-0.142897,-0.002411,-0.017644,-0.063547,0.128162,0.166062,0.665728,-0.007766,-0.238719,-0.022166,0.375049,0.130734,-0.131636,-0.064989,0.448935,-0.055008,0.372041,0.038911,-0.203354,-0.045170,0.019898,-0.127858,-0.332172,0.312964,0.199112,0.334857,-0.790755,0.576656,0.248238,-0.356007,0.322592,-0.610506,0.215255,0.328708,-0.023404,0.600161,-0.285702,0.077151,-0.619334,0.261859,0.833252,0.205065,0.002994,0.542015,-0.404642,-0.221152,-0.161492,0.032188,-0.795815,-0.176182,0.262388,-0.269825,-0.429070,0.244587,-0.746119,0.216204,0.009174,-0.175288,-0.085805,-0.454886,-0.138138,-0.540047,0.001188,-0.546528,-0.274424,0.110085,-0.130505,-0.253722,0.856066,-0.995070,0.333725,0.609829,0.389098,-0.383735,0.740753,0.245251,0.186676,-0.232360,0.050746,0.254677,-0.115096,0.277358,0.091869,0.466211,-0.177957,-0.108954,-0.559620,0.494384', '1292219', '1292720', '1