INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10745405', '冒牌家庭', '喜剧', 'David（杰森·苏戴奇斯 Jason Sudeikis 饰）是丹佛的毒贩子，生活过得有滋有味。一个夜里，和David住在同一个公寓的十八岁男孩Kenny（威尔·保尔特 Will Poulter 饰）看见一个流浪女孩正被人勒索，便出手相助。David不忍心看到Kenny被小混混们欺负，也加入战局，无奈寡不敌众，救人不成反而全副身家被抢走。原本已负债累累的David只能接受他的老板交给他的一个任务——去墨西哥运一批大麻回美国。为了掩人耳目，David找来同住同一座公寓的脱衣女郎Rose（詹妮弗·安妮斯顿 Jennifer Aniston 饰）、Kenny还有那个流浪女孩Casey（艾玛·罗伯茨 Emma Roberts 饰）假冒米勒一家，开着一辆房车直奔墨西哥而去。这冒牌家庭在一路上历经艰辛，能否顺利将毒品运输回国？©豆瓣', '詹妮弗·安妮斯顿', '罗森·马歇尔·瑟伯', 7.4, 64509, 'tt1723121', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1996365758.jpg', 0.5, 3.5, 35.2, 45.4, 15.5, '0.370874,-0.107776,-0.450837,0.125282,-0.378559,-0.405972,0.647449,0.065732,-0.234169,-0.271450,0.128691,0.875251,0.186156,0.206937,0.311166,0.175617,-0.180914,-0.292707,0.020068,-0.173144,-0.182135,-0.379630,-0.131788,-0.283605,0.098876,-0.061924,0.398630,-0.004502,0.049477,0.564786,0.511643,0.447319,-0.300927,0.209090,-0.450255,-0.042791,0.057171,-0.117679,-0.052371,0.402180,-0.351870,-0.211502,0.059826,-0.045407,0.276925,0.147748,0.681555,0.074428,0.030658,-0.027853,0.048810,-0.278989,-0.121382,0.124487,0.194557,-0.045194,0.160139,-0.120640,-0.346730,0.118037,0.187312,-0.207239,-0.498772,0.200736,0.008875,-0.055483,-0.738457,0.262401,-0.113818,-0.135573,-0.065269,-0.479275,0.190780,0.445436,0.093990,0.423692,0.019075,0.214143,-0.774640,0.085937,0.710817,-0.124554,0.211263,0.277805,0.017374,-0.087214,0.223580,-0.273230,-0.634952,-0.091149,0.419805,-0.328826,-0.115443,-0.305436,-0.621446,0.060875,-0.492092,-0.246765,-0.026272,-0.232898,-0.088336,-0.637918,0.119532,-0.011960,-0.177450,0.283771,0.087655,-0.172669,0.453009,-0.464036,0.164104,0.582213,0.444534,-0.536350,0.537264,0.044766,0.332459,0.011296,-0.148170,0.396137,0.430228,0.338757,0.027107,0.218188,-0.188729,-0.191524,-0.294341,0.130489', '1293908', '26678509', '1295324', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10745412', '狼溪2', '惊悚', '浩瀚无垠的澳洲大陆，壮观绝美的自然风光吸引无数旅者和背包客来到此地一游。可是当他们快乐自在和大自然融为一体的时候，却全然没有意识到危险也在悄然逼近。晴朗明媚的一天，德国小伙鲁特格尔（Philippe Klaus 饰）和女友凯瑟琳娜（Shannon Ashlyn 饰）徒步行走在漫长无边的公路上，他们正前往国家公园，期间扬手搭车，尽享背包客的乐趣。两人你侬我侬，在国家公园的野外支起帐篷，谁知却被冷空无情的米克·泰勒（约翰·贾瑞特 John Jarratt 饰）盯上了。一轮紧张的对话过后，米克出手杀害鲁特格尔，弄晕凯瑟琳娜。当惊恐的女孩从昏迷中醒来时，发现不远处的米克宛如魔鬼一般悠然自得地肢解着她的男友。凯瑟琳屏住呼吸落荒而逃，但是残忍的死神怎能容得他的猎物轻易逃脱……©豆瓣', '约翰·贾瑞特', '克瑞格·麦克林恩', 6.6, 7364, 'tt2004432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2112925948.jpg', 2.4, 11.1, 49.7, 27.5, 9.2, '0.259231,0.106541,-0.859841,0.394774,0.035088,-0.020529,0.887893,0.018249,-0.221826,0.174956,0.250523,0.518280,-0.370842,0.178600,0.438536,0.386860,-0.325841,-0.684243,-0.146190,-0.020751,-0.182814,-0.321701,-0.448889,-0.103313,0.237014,-0.332862,0.335016,0.121013,-0.094201,0.664706,-0.125524,0.038600,-0.365361,0.712234,-0.156833,-0.040367,0.257036,0.027354,-0.057610,0.136344,-0.305122,-0.221294,-0.297133,0.048909,-0.151390,0.256479,0.690963,-0.320166,-0.170338,0.057204,0.150114,-0.370995,0.092744,0.086533,0.247973,-0.454895,0.083469,-0.166409,0.019661,-0.058569,0.129472,-0.025245,-0.358354,0.392470,-0.104743,0.066675,-0.523846,0.580746,-0.012735,-0.024989,0.156265,-0.248523,0.313423,0.170131,-0.000091,0.458561,0.069828,0.036219,-0.577610,0.159073,0.635513,0.097010,-0.324374,0.397785,-0.215651,-0.308804,-0.078127,-0.064821,-0.479812,-0.375225,0.560941,-0.042107,-0.272303,0.187681,-0.501105,0.088156,-0.276698,-0.116089,-0.218123,-0.337095,-0.482993,-0.520756,0.116921,-0.367241,-0.191877,0.330598,-0.146295,-0.188083,0.451560,-0.379480,0.298787,0.608552,0.150654,0.086169,0.717321,-0.274203,-0.038583,0.038553,-0.252100,0.588861,0.205140,0.419965,0.377064,0.373690,-0.385480,0.423234,-0.434448,0.481509', '3011051', '2269893', '26882457', '4832825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10746175', '惊天危机', '动作', '年轻的凯尔（查宁·塔图姆 Channing Tatum 饰）从阿富汗前线退伍后在国会安保部门工作，他的终极梦想是保护美国总统索亚（杰米·福克斯 Jamie Foxx 饰）。凯尔与离婚的妻子育有一个正在上小学的女儿艾米莉（乔伊·金 Joey King 饰），她因为父亲入伍的经历变成了一个政治迷，尤其对索亚总统和白宫极其崇拜。凯尔为了让女儿高兴承诺带她参加白宫内部一日游，顺便在当天去应征由卡罗（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）领导的特勤部门的工作。可是就在同一天，一伙身份不明的武装分子乔装潜入白宫并对索亚总统进行搜捕，一场腥风血雨蓄势待发。正在陪女儿参观的凯尔能否临危不惧解救总统？凯尔是否能同时保护女儿？而这场动机不明的暴力背后是否掩盖着不为人知的肮脏秘密？©豆瓣', '查宁·塔图姆', '罗兰·艾默里奇', 7.3, 123103, 'tt2334879', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2039109399.jpg', 0.8, 3.9, 37.1, 45.1, 13.1, '-0.053528,-0.121270,-0.683562,0.439817,-0.292277,-0.153989,0.481566,0.305300,-0.459444,-0.299432,0.403105,0.762752,0.117210,0.156698,0.477220,0.076363,-0.634192,-0.558019,-0.118393,-0.122791,-0.204743,-0.623657,-0.262622,-0.333330,0.067542,-0.284556,0.486620,-0.047717,-0.096509,0.327675,0.502480,0.435884,-0.307203,0.292082,0.177746,-0.501306,0.532293,0.044838,-0.456801,0.141059,0.049827,-0.021394,-0.094830,0.066621,0.319088,0.386029,0.399081,-0.206117,0.266077,-0.280027,0.121649,-0.290804,0.159125,0.325326,0.260519,0.126976,0.053524,0.222306,-0.117896,-0.184620,0.067689,-0.300752,-0.708829,-0.074140,0.124696,0.182081,-0.437323,0.199306,-0.337998,0.009457,0.349429,-0.141431,0.061845,0.626769,0.080571,0.406649,0.027448,0.240667,-0.253511,0.087351,0.393971,-0.092074,0.029259,-0.147529,-0.172139,-0.401661,0.092876,-0.039069,-0.504830,-0.067750,0.243799,-0.313533,-0.024656,0.296963,-0.473426,-0.191501,-0.491446,-0.219729,0.146405,-0.389350,0.144814,-0.808603,-0.033250,-0.244520,-0.061197,-0.076899,0.308490,-0.128392,0.574866,-0.787461,0.253375,0.623592,0.247226,-0.623922,0.376449,0.466402,0.272172,-0.376858,-0.054697,0.245423,0.242978,0.257518,-0.152658,0.222510,0.319774,-0.254366,-0.065540,0.208983', '3178770', '1305096', '1293656', '30229667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10746430', '阿修罗', '动画', '平安时代末，天灾人祸，世道离乱，横尸遍野。在这个人吃人的恐怖时代，一条受到诅咒的生命降临人间。年幼的他（野泽雅子 配音）自幼以人肉为食，成为令人闻风丧胆的食人魔。直到与慈悲的法师（北大路欣也 配音），他才终于有了名字“阿修罗”，一句“南无阿弥陀佛”更在阿修罗的心中种下人性复苏的种子。在被人追杀的绝望途中，阿修罗得到美丽少女若狭（林原惠美 配音）给他无微不至的关怀与照顾，野兽般少年的心底善良的花朵绽放。可是在兵荒马乱、人性沦丧的时代。他的美好期望相继落空，留给阿修罗的究竟是什么？本片根据漫画家乔治·秋山（本名：秋山勇二）的同名原著改编。©豆瓣', '野泽雅子', '佐藤敬一', 8.2, 24179, 'tt2328505', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1610184632.jpg', 0.6, 2.1, 17.6, 46.2, 33.5, '-0.113524,0.143280,-0.635442,0.557810,-0.058705,-0.206072,0.737167,0.006333,-0.272969,-0.031662,0.238717,0.539436,-0.194625,0.115102,0.236604,-0.041956,0.041358,-0.397565,-0.116145,-0.000416,0.016047,-0.158028,-0.367550,-0.101735,0.012241,-0.488538,0.812646,0.378056,-0.118744,0.075035,0.112049,0.205686,-0.118494,0.246453,-0.448477,0.060017,-0.211728,0.137021,-0.094581,-0.064726,-0.202434,-0.316082,-0.262373,0.186539,-0.561540,0.125110,0.564884,-0.543073,-0.249181,-0.296202,0.633334,-0.320001,-0.090436,-0.072577,0.169005,-0.129706,0.146564,0.070000,0.143705,-0.001907,-0.069872,-0.060036,-0.898730,-0.240101,0.185932,0.162392,-0.427982,0.414032,0.070059,-0.054410,0.295398,-0.326317,0.117991,-0.142114,0.394338,0.658991,-0.271874,0.074964,-0.211209,0.227349,0.565551,-0.233182,-0.553286,0.315329,-0.282563,-0.583621,-0.021271,-0.137553,-0.700011,0.051672,0.231420,0.056161,-0.259557,0.609557,-0.565878,-0.050519,-0.062307,-0.135120,-0.047096,-0.245135,-0.247188,-0.203873,-0.216022,-0.311583,-0.222341,0.014181,0.644839,-0.069507,1.135415,-0.717826,0.524923,0.435985,0.059857,-0.334909,0.446185,0.185277,-0.067083,-0.139778,-0.229358,0.647480,0.053176,0.185649,-0.097945,0.035543,-0.130565,0.106573,-0.366888,0.522882', '24284209', '27602116', '26348103', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10747855', '白虎', '动作', '1940年代早期，第二次世界大战即将结束。激烈的持久战使苏联军队和德国军队都日渐疲惫。德军一辆极具攻击性和破坏性的巨型坦克“白虎”，屡屡将苏军的坦克轰炸得机毁人亡。而这辆势不可挡的强大武器，总是从战场的硝烟中幽幽出现继而转瞬消失，没人能够确认它的真实存在，当然也无人否认。苏军指挥官决定建造一辆超级坦克T-34坦克的变种，与之抗衡。操纵该辆坦克的车长伊凡·纳季亚诺夫（阿列克谢·沃特考夫 Alexei Vertkov饰）是一位传奇人物。他曾在操纵坦克时，被“白虎”轰炸得体无完肤。死里逃生的伊凡不但活了下来，更拥有一种读懂“坦克语言”的特异功能。他坚信神秘的德军坦克“白虎”确实存在，并决心摧毁它。由俄罗斯导演卡伦·沙赫纳扎罗夫执导的战争影片《白虎》，入围2012年第15届上海国际电影节金爵奖-最佳影片，并入围2013年第3届北京国际电影节国外展映单元-俄罗斯影展。', '阿列克谢·沃特考夫', '卡连·沙赫纳扎罗夫', 6.5, 5246, 'tt2318405', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1587399673.jpg', 2.8, 15, 47.3, 25.7, 9.1, '-0.047330,0.092137,-0.838799,0.774931,0.329685,0.118994,0.487469,-0.133334,-0.295538,-0.030056,0.482607,0.595848,-0.029804,-0.367438,0.136216,-0.249182,-0.102120,-0.301576,-0.017868,0.080407,-0.109082,-0.426770,-0.620950,-0.107798,0.200688,-0.351733,0.872397,0.157637,-0.286896,0.329301,0.197570,0.174032,0.249330,0.350892,0.029626,-0.197914,-0.017068,-0.185325,-0.236915,0.163343,-0.302211,-0.188322,0.012062,-0.045056,-0.168008,0.020694,0.593248,-0.328842,0.209490,-0.221873,0.114133,-0.292237,0.023747,-0.098097,0.377652,0.028292,-0.083313,0.067964,0.264038,0.132934,-0.145156,0.397269,-0.494519,-0.047298,-0.374715,-0.094099,-0.224550,0.345773,-0.382287,0.329440,-0.194997,0.010936,0.264630,0.220389,0.189588,0.172374,-0.224234,0.162206,-0.623232,0.200105,0.528997,-0.265661,-0.755201,0.302782,-0.023654,-0.549089,-0.257434,-0.750549,-0.297899,0.044197,0.343370,-0.121677,0.116744,0.351237,-0.668039,0.046761,-0.495607,-0.376433,-0.113332,-0.005228,0.219566,-0.913338,0.118157,-0.333517,-0.038492,0.204489,0.024429,0.035884,0.737224,-0.560012,0.137250,0.404183,0.332818,-0.034373,0.381374,-0.034168,-0.019335,-0.177794,-0.132283,0.539151,-0.173715,0.189265,-0.042245,0.350070,0.042094,-0.169602,0.006728,0.470985', '1293433', '1298911', '10439358', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10748193', '笔仙惊魂', '悬疑', '某艺术院校学生小武（翟文斌 饰）、慕凡（王一 饰）、柳丝丝（何杜鹃 饰）、凌菲儿（柴碧云 饰）驱车来到位于郊外，租住了当地的四合院。这是一座古色古香但是颇为阴森的老宅，周围的住户似乎对此也多有忌惮，欲言又止。夜深人静，四合院突然断电。四个青年男女无聊至极，决定玩传说中的禁忌游戏笔仙。但是无所畏惧懵懂无知的小武竟然问起了笔仙的死因，之后也未将笔仙送走。在此之后，诡异的事情接连发生，半夜从远处传来的戏曲念白，挂满死猫的树，柳丝丝深更半夜的恐怖举止……如是种种，无一不在搅扰着年轻人们的神经。恐怖的究竟是这个院落还是毫无形状的笔仙，抑或是……©豆瓣', '何杜娟', '关尔', 3.4, 6507, 'tt5080208', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1593749506.jpg', 52.2, 28.9, 15.3, 2, 1.6, '0.528263,-0.099015,-0.692957,0.310242,0.072534,0.042774,0.943062,0.131080,-0.643418,-0.503641,0.426480,0.374667,-0.476293,0.460351,0.062173,0.070535,-0.085841,-0.149140,-0.221269,-0.197421,-0.170698,-0.291157,-0.138685,-0.082080,0.095243,0.037274,0.237870,0.216246,-0.245549,0.477694,0.289925,0.407873,-0.478886,0.475847,-0.293271,-0.005943,0.045061,0.280547,0.160756,-0.156339,-0.007358,-0.291466,-0.421873,0.050108,-0.085194,0.451299,0.622461,-0.233393,-0.515950,0.325520,0.411425,0.048488,-0.202922,0.187892,0.348637,-0.108545,0.100317,-0.123792,-0.231853,0.135859,0.032048,0.006688,-0.269086,0.220807,0.088347,0.256037,-0.264899,0.302239,0.114965,-0.279280,0.119643,-0.331975,0.444147,-0.053578,0.255982,0.445428,0.108364,-0.087812,-0.670755,-0.025111,0.341520,0.180451,-0.233617,0.350461,-0.374901,-0.397453,-0.133520,-0.024858,-0.239036,-0.035633,0.312678,-0.035357,-0.200878,0.073810,-0.619334,-0.006413,0.046204,-0.038284,-0.142158,-0.216578,-0.514244,-0.526328,-0.002018,-0.570024,-0.181540,0.133356,0.112203,0.187442,0.584739,-0.839526,0.248356,0.224414,0.016158,-0.084815,0.502037,-0.134225,-0.054664,0.103685,-0.266274,0.010910,-0.097762,0.220113,0.065840,0.576243,-0.088876,-0.297003,-0.508213,0.259607', '1296332', '1296534', '35073565', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10748492', '逆转王牌', '剧情', '瑞奇（贾斯汀·丁伯莱克 Justin Timberlake 饰）是普林斯顿大学的高材生，生来就拥有超高智商的他在赌博上有着过人的天赋，从很小的时候起，他就懂得利用自己的这一优势来挣取学费和零花钱，并因此而过着吃穿不愁的富裕生活。可是，常在河边走哪有不湿鞋，终于，瑞奇在一场十分重要的赌局中马失前蹄，几乎失去了全部。高傲的他深信是有人给自己下套出千，于是，瑞奇千里迢迢来到了哥斯达黎加，寻找赌王伊万（本·阿弗莱克 Ben Affleck 饰）。伊万利用高额的奖金诱惑瑞奇同他参加一场十分危险的网络赌局，与此同时，联邦调查局亦找到了瑞奇，希望他能够帮助警方捉拿伊万。©豆瓣', '贾斯汀·汀布莱克', '布拉德·福尔曼', 5.3, 6316, 'tt2364841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2010544596.jpg', 6.4, 35.9, 47.3, 7.7, 2.6, '0.096749,0.063275,-0.685886,0.577442,-0.402439,-0.365732,0.520496,0.124613,-0.346631,0.009005,0.164241,0.697855,0.218729,0.033699,0.320942,-0.018184,-0.219584,-0.353618,0.164078,-0.195776,-0.313781,-0.556732,-0.484790,-0.040432,-0.221335,-0.306897,0.209374,-0.042008,-0.459385,0.501874,0.431376,0.131707,0.303771,0.625539,-0.146325,-0.139981,0.074289,0.049722,-0.121534,0.425765,0.117979,-0.175285,-0.238253,0.125880,0.271837,0.327313,0.307524,-0.314058,-0.025528,0.010988,0.234097,-0.241889,-0.050006,0.102504,0.013329,-0.204077,0.095490,0.107160,-0.343071,0.154929,0.256301,-0.180972,-0.914345,-0.181274,0.020535,0.134405,-0.586766,0.291899,-0.111368,-0.267572,-0.135152,-0.399804,0.003720,0.285764,0.066236,0.106156,-0.200086,-0.184182,-0.857995,0.089131,0.523101,-0.090314,-0.098207,0.267470,-0.233611,-0.447947,0.150946,-0.353739,-0.370823,-0.067151,0.500900,-0.038763,-0.122518,0.001010,-0.457299,0.304242,-0.131638,-0.347013,-0.161277,-0.444579,-0.096675,-0.499250,-0.174420,-0.476740,-0.374705,0.077805,0.165927,-0.579199,0.651629,-0.898854,0.085324,0.704044,0.295695,-0.257419,0.504305,-0.046833,0.134931,-0.020702,-0.336122,-0.006434,-0.012363,0.378012,0.191287,0.313848,0.189788,-0.379578,0.008713,0.803563', '1793491', '1783461', '1298299', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10748498', '汉娜·阿伦特', '剧情', '1960年，以色列宣布抓捕到前纳粹德国高官、素有“死刑执行者”之称的阿道夫·艾希曼，并于1961年在耶路撒冷进行审判。已在美国居住多年的著名犹太女哲学家汉娜·阿伦特（巴巴拉·苏科瓦 Barbara Sukowa 饰）受《纽约人》邀请为此次审判撰稿。当汉娜·阿伦特前往耶路撒冷观看审判后，却在艾希曼的阐述、民意和自己的哲学思考之间发现了分歧。当阿伦特将艾希曼当年的行为提高到哲学的高度，她的文章不出所料地引发了社会上的恶评和抨击，一些汉娜·阿伦特的老友甚至和她绝交反目。这个当年海德格尔门下最得意的女学生在急风骤雨中想全身而退，却发现一切都已经不像自己预计的那样简单。©豆瓣', '芭芭拉·苏科瓦', '玛加蕾特·冯·特罗塔', 8.2, 15576, 'tt1674773', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1865907521.jpg', 0.3, 1.4, 17.5, 49.9, 31, '0.427461,-0.044886,-0.874904,0.700190,0.065026,-0.392390,0.535502,0.060715,-0.304150,-0.336345,0.176286,0.718306,-0.356251,0.244410,0.454085,-0.305647,-0.517348,-0.881689,-0.301511,-0.219770,-0.424243,-0.830820,-0.078312,-0.299658,-0.334063,-0.262558,0.404208,0.125155,-0.368146,0.243875,0.174025,0.295763,0.241478,0.273260,-0.037301,-0.062162,0.339701,0.208291,-0.306117,0.256325,0.085340,-0.214942,-0.209759,0.235360,-0.244351,0.379563,0.361794,-0.514906,-0.034018,-0.101193,0.563620,-0.403787,0.073793,0.268392,0.620189,0.017012,-0.141584,0.314520,-0.149226,0.102097,-0.134650,-0.157751,-0.501086,-0.251396,-0.074744,0.204998,-0.437123,0.636309,0.001807,0.198845,-0.121296,-0.294559,0.025800,0.371088,0.138863,0.490685,0.087664,-0.037096,-0.281645,0.088227,0.523500,0.105998,-0.365123,-0.045565,-0.262428,-0.562531,-0.000399,-0.167840,-0.256779,-0.283152,0.250533,-0.205365,-0.053843,0.581354,-0.505979,-0.253301,-0.242102,-0.129470,0.055557,-0.196264,0.086548,-0.692127,-0.315986,-0.336868,-0.137492,0.115071,0.234161,-0.335157,0.713520,-0.769499,0.453317,0.510815,0.287256,-0.378436,0.618627,0.035653,-0.020450,-0.169081,-0.193264,0.468740,0.350311,0.310758,-0.084134,0.303479,0.228989,-0.207531,-0.283806,0.499224', '1301172', '1303449', '1302589', '1298880');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10752547', '夜色人生', '剧情', '《以夜为生》（Live By Night）根据美国当代著名作家丹尼斯·勒翰（Dennis Lehane）2012年同名小说改编，故事设定在上世纪20、30年代，讲述了一个出身于警察世家的年轻人乔·考夫林（Joe Coughlin）加入黑帮、越陷越深、走上不归路的故事。该书是丹尼斯·勒翰2008年小说《命运之日》（The Given Day）的续篇，共分三部：第一部“波士顿”讲述乔初入黑帮，爱上黑帮老大亚伯·怀特的情妇，结果入狱，成为狱中黑老大马索的心腹；第二部“伊波”讲述乔出狱后，与马索一起扳倒亚伯，在坦帕市自立门户逐渐崛起；第三部“所有暴力的孩子”讲述马索与乔翻脸，双方决战。据悉，西耶娜·米勒（Sienna Miller）在片中将扮演黑帮老大的情妇艾玛（Emma）；佐伊·萨尔达娜（Zoe Saldana）则将饰演乔在坦帕自立门户时遇到的女子格瑞西耶拉·苏亚雷兹（Graciella Suarez）；艾尔·范宁（Elle Fanning）饰演一名野心勃勃的女演员洛瑞塔·菲吉斯（Loretta Figgis），不幸惹上了麻烦。', '本·阿弗莱克', '本·阿弗莱克', 6.6, 8349, 'tt2361317', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2378933938.jpg', 1.7, 12.9, 49.4, 27.6, 8.4, '0.192561,-0.309081,-0.129623,0.500060,0.347321,-0.124315,0.379180,0.005574,-0.360306,-0.505196,-0.207163,0.992748,-0.264290,0.313987,0.555973,-0.099513,-0.580135,-0.748096,-0.037521,-0.037634,0.051297,-0.640510,-0.102078,-0.200599,0.032463,-0.319022,0.619891,0.014317,-0.329718,0.416115,0.457670,0.589785,-0.367859,-0.117898,0.078321,0.272002,0.383303,-0.252562,-0.346016,0.174477,-0.055346,-0.159230,-0.015456,-0.170250,0.288001,0.113327,0.463217,-0.240220,0.423531,-0.207952,0.626901,-0.346153,-0.136699,-0.322226,0.599349,-0.070093,0.108927,0.523060,0.043047,-0.347588,0.047732,-0.536283,-0.639991,0.054126,0.140203,-0.044942,-0.518255,0.065411,-0.031027,0.408298,0.032677,-0.020190,0.171073,0.275607,0.514150,0.125666,0.258643,0.039582,-0.279961,0.329474,0.557493,0.151347,-0.072787,-0.010171,0.299542,-0.299079,-0.254188,-0.416254,-0.497002,0.125016,0.499055,-0.403020,-0.020987,0.560054,-0.233454,-0.432336,-0.272102,-0.017207,0.276616,-0.078625,-0.229515,-0.695324,-0.436402,0.040468,0.213472,-0.042081,0.007490,-0.532976,0.684792,-0.509735,0.111737,0.362271,0.084486,-0.571655,0.588238,-0.128065,0.319459,-0.262648,0.178091,0.681834,0.420819,-0.365389,0.085270,0.143936,-0.351753,-0.066197,-0.041834,0.370740', '1829654', '1482099', '26990609', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10754780', '无人引航', '剧情', '山姆（比利·克鲁德普 Billy Crudup 饰）是一位事业有成的广告公司总裁，一场意外夺取了他的儿子乔什（迈尔斯·赫尔泽 Miles Heizer 饰）的生命，这突如其来的打击让山姆陷入了绝望之中，他放弃了所拥有的一切，躲在自己的帆船里，每日靠酗酒过活。一次偶然中，山姆意外发现了乔什生前写的几首歌曲，歌曲让山姆仿佛重新回到了父子两人共同为音乐而狂的美好时代。山姆决定让乔什的生命在音乐中延续，他学会了儿子创作的歌曲，于酒吧之中自弹自唱。山姆真挚的歌声吸引了一位名叫昆汀（安东·尤金 Anton Yelchin 饰）的年轻人，两人一拍即合组成了乐队，专门表演乔什所谱的歌曲。©豆瓣', '比利·克鲁德普', '威廉姆·H·梅西', 8.1, 20197, 'tt1798243', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2194962310.jpg', 0.3, 1.3, 18.5, 52.2, 27.7, '0.204315,0.077414,-0.639009,0.818338,-0.136096,-0.341549,0.815451,0.121684,-0.597247,-0.136540,0.108801,0.855904,-0.115129,0.319890,0.424940,0.157769,-0.377319,-0.783530,-0.113521,0.023749,-0.027243,-0.469259,-0.284958,-0.298102,-0.175109,-0.357525,0.511057,0.064473,-0.073195,0.506116,0.288581,0.220878,0.044196,0.215771,0.160569,0.200984,0.324384,-0.129668,-0.240952,0.188892,0.015562,-0.309448,-0.158265,0.299459,-0.193375,0.193178,0.937694,-0.377509,0.131571,-0.043664,0.331324,-0.127245,-0.114446,-0.137144,-0.082036,0.171559,0.291190,0.173454,-0.323838,-0.045291,-0.015464,0.073825,-0.824725,0.010896,-0.009058,0.114071,-0.545583,0.526379,-0.068755,-0.031241,0.154028,-0.215574,0.339677,0.027006,0.630860,0.532811,-0.196626,-0.062306,-0.231676,0.379625,0.724173,-0.122420,-0.346709,0.580095,-0.419044,-0.333594,-0.218340,-0.152481,-0.634727,-0.076739,0.444146,0.015757,0.052520,0.137575,-0.605260,-0.185142,-0.151639,-0.301159,-0.225251,-0.470529,-0.161463,-0.726091,-0.141777,-0.079691,0.032302,-0.092683,0.023585,-0.301524,0.885172,-0.611460,0.216884,0.601026,-0.174434,-0.072419,0.538665,-0.034095,0.294963,-0.028454,0.009601,0.169877,-0.126195,-0.078115,0.236231,0.501405,-0.138040,0.042411,-0.546526,0.755331', '3811356', '30162520', '25928048', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10755367', '寂静人生', '剧情', '第70届威尼斯电影节(2013)地平线单元最佳导演奖获奖作品，乌贝托·帕索里尼导演。约翰是一个普通的社会服务员，他的工作是为孤单死去的逝者寻找相关亲人，而当他被告知即将被政府裁员后，他决定将最后一位死者的亲友全部找齐……', '埃迪·马森', '乌贝托·帕索里尼', 9, 41934, 'tt2395417', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204300672.jpg', 0.1, 0.4, 6.1, 34.9, 58.6, '0.222221,0.103929,-0.532342,0.520850,-0.148860,-0.433144,0.652639,0.262100,-0.461564,-0.079128,0.238708,1.249344,-0.008211,0.524388,0.125049,-0.025740,-0.109114,-0.926726,-0.259045,-0.132763,-0.452290,-0.352908,-0.213091,-0.005913,-0.464842,-0.058391,0.973881,0.081929,0.307132,0.340118,0.677399,0.287896,0.168118,0.492621,-0.247865,0.097819,0.536993,-0.327148,-0.401949,0.470855,-0.138562,-0.132036,0.041920,0.280370,-0.199544,0.557862,0.851390,0.087821,0.063339,-0.259284,0.860852,-0.638670,0.117548,0.279396,0.363708,0.192489,-0.167400,0.431379,-0.292873,0.102230,0.048648,0.061689,-0.923973,-0.254163,0.083957,0.172955,-0.816280,0.274997,-0.200354,0.140159,0.124541,-0.306745,0.493874,0.115255,0.238050,-0.002356,0.085534,-0.291595,-0.195570,0.683387,0.627311,-0.217568,-0.324340,0.198577,-0.371809,-0.500621,0.455491,-0.304322,-0.289365,0.210446,0.457746,0.019305,0.052878,0.002863,-0.479915,-0.327921,-0.294826,-0.623772,-0.137802,-0.252451,-0.113005,-0.549858,0.012245,0.112582,-0.245882,-0.171267,0.091527,-0.126881,0.861294,-0.338205,0.372766,0.713170,0.199507,-0.636257,0.946426,0.038783,0.489316,-0.276197,0.302321,0.099221,-0.018688,0.603078,-0.142668,0.067935,-0.028085,-0.098307,-0.437214,0.438847', '34890458', '30162520', '1297368', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10755525', '包法利夫人', '剧情', '故事发生在风景如画的法国乡村，农家姑娘艾玛（米娅·华希科沃斯卡 Mia Wasikowska 饰）相貌清纯，天资聪慧。一次偶然中，艾玛结识了名为查尔斯（亨利·劳埃德-休斯 Henry Lloyd-Hughes 饰）的乡村医生，查尔斯爱上了善良单纯的艾玛，门当户对的两人很快就结为了人人羡慕的爱侣。随着时间的推移，一生不变的婚后生活让艾玛开始感到厌倦，就在此时，一位名叫雷翁（埃兹拉·米勒 Ezra Miller 饰）英俊男子出现在了艾玛的身边，两人之间擦出了激情的火花。在目睹过上流社会纸醉金迷的种种之后，艾玛再也无法平静的回归自己平凡的生活之中去，为了得到本不属于她的一切，艾玛迷失了。©豆瓣', '米娅·华希科沃斯卡', '索菲·巴尔特', 6.6, 10315, 'tt2334733', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2224825296.jpg', 1.6, 10.3, 52.5, 27.9, 7.6, '0.424313,0.260415,-0.702882,0.393134,-0.217315,-0.490444,0.863028,-0.010723,-0.565057,-0.125545,-0.031121,0.688201,-0.510754,0.360481,0.517422,0.365620,-0.382005,-0.712705,0.040376,-0.281690,-0.010520,-0.323972,-0.213427,-0.066304,-0.133338,-0.585405,0.411244,0.018067,0.002656,0.574385,0.208347,0.249935,-0.055466,0.324694,-0.384522,0.112928,0.035437,0.050853,-0.301974,0.132823,-0.029447,-0.022643,0.029626,0.075947,-0.116319,-0.008872,0.629390,-0.227688,0.050961,-0.031622,0.418984,0.150011,0.019617,0.122884,0.202658,-0.300704,0.145307,-0.004363,-0.289755,-0.022483,-0.013017,-0.010834,-0.559525,0.128872,0.051384,0.346596,-0.636839,0.532445,0.118318,-0.496318,0.138677,-0.406539,0.056672,0.191310,0.414702,0.304942,0.065411,0.095508,-0.209302,0.062572,0.861302,0.321568,-0.360000,0.592925,-0.400311,-0.432010,-0.011710,-0.000287,-0.582082,0.044183,0.236427,0.089890,-0.107574,0.452807,-0.627282,0.044671,-0.270935,-0.111275,0.068215,-0.293964,-0.381125,-0.588939,-0.354150,-0.620183,-0.349268,-0.170122,-0.139962,-0.247502,0.714947,-0.934560,0.274446,0.361660,0.015760,-0.188927,0.667490,0.169786,0.134747,-0.011223,-0.023588,0.636526,-0.028547,0.209222,0.016875,0.443752,-0.299697,0.084087,-0.279087,0.755839', '5977789', '1308755', '26687241', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10755584', '生死倒数', '剧情', '2005年8月29日，威力巨大的强台风卡特里娜即将袭击新奥尔良。在当地一家医院，男子诺兰·海斯（保罗·沃克 Paul Walker 饰）却迎来了人生的悲喜时刻。他刚刚迎来新出世的宝贝女儿，但美丽的妻子阿比盖尔（珍尼希斯·罗德里格兹 Genesis Rodriguez 饰）却在分娩过后撒手人寰。娇嫩的宝宝还无法适应全新的环境，只能被放在暖箱中依靠机器辅助求生。面对眼前完全陌生的小生命，诺兰和妻子一幕幕美好的回忆相继浮现眼前，令这个经历了重大悲喜变故的男人百感交集。暴风雨渐趋强烈，医院人手不足，医患被迫紧急疏散，而垮塌的大坝更将灾难推向顶点。孤独的诺兰必须与时间和命运赛跑，用一己之力保护他在这个世上最后的亲人……©豆瓣', '保罗·沃克', '埃里克·海瑟尔', 6.9, 6348, 'tt2094018', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2154616348.jpg', 1.4, 8, 46.7, 31.9, 11.9, '-0.160278,0.182685,-0.640189,0.268353,0.070145,-0.119795,0.812496,0.222425,-0.620070,-0.277666,0.256155,0.707193,-0.160599,0.454411,0.324279,-0.159470,-0.179581,-0.654803,-0.074986,0.095211,-0.379507,-0.243450,-0.362802,-0.190987,0.224314,-0.508561,0.595821,0.332554,0.128264,0.225838,0.141001,0.321559,-0.190824,0.560474,-0.045894,-0.122390,0.015544,-0.058438,-0.488295,0.145572,0.042987,-0.222493,-0.116622,0.316641,-0.305409,0.279418,0.772882,-0.317206,-0.246458,-0.272152,0.461013,-0.237666,-0.105597,0.136465,0.017545,-0.074410,-0.042427,-0.010606,-0.247893,-0.222711,0.129753,-0.216635,-0.557904,0.173422,-0.015094,-0.008516,-0.383632,0.315764,-0.045999,-0.013164,0.205132,-0.292500,0.132867,0.327399,0.233760,0.590577,-0.551689,-0.000347,-0.104731,0.122944,0.486929,-0.156662,-0.641691,0.571210,-0.432407,-0.248276,-0.213891,-0.357791,-0.598588,0.059316,0.265483,0.476435,-0.206206,0.565873,-0.474887,0.119900,-0.544237,-0.234925,-0.148728,-0.257210,-0.384533,-0.518771,-0.135924,-0.156022,-0.321087,0.209998,0.199637,-0.079156,0.589542,-0.474493,0.320952,0.552893,0.247388,0.034064,0.397615,0.071862,0.308160,-0.253774,0.095359,0.659541,-0.413292,0.351357,-0.138686,0.018275,-0.233818,0.455884,-0.397015,0.850233', '1305666', '3001149', '1309172', '10742456');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10756499', '挨饿游戏', '喜剧', '曾经一手打造出《惊声尖笑》（Scary Movie）系列的杰森·弗里德贝格（Jason Friedberg）与艾伦·舒尔茨（Aaron Seltzer）把最近票房大卖的《饥饿游戏》作为恶搞对象，拍摄一部名为《挨饿游戏》（The Starving Games）的喜剧。', '玛依亚拉·沃尔什', '贾森·弗莱德伯格', 5.5, 6565, 'tt2403029', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1994841822.jpg', 11.6, 27.6, 42.5, 12.9, 5.4, '-0.102449,-0.279306,-0.353472,0.158379,0.536651,0.119862,0.521495,-0.001253,-0.211798,-0.534903,0.215231,0.793941,-0.768639,0.176859,0.294877,0.023899,-0.202729,-0.566348,-0.307773,0.140974,0.409498,0.111734,-0.870723,0.001244,-0.142962,-0.439703,0.854858,-0.309264,-0.681931,0.452439,0.554685,0.639960,-0.057702,-0.095436,0.107263,-0.033879,0.241256,-0.198323,-0.645218,0.432977,0.076781,0.197739,-0.054877,-0.162715,0.105681,0.095174,0.475743,-0.295825,-0.061192,0.148517,0.551679,-0.277063,-0.265923,-0.644680,-0.282485,0.261602,0.618525,-0.071602,-0.122876,0.101733,-0.061861,-0.599191,-1.308602,0.238235,-0.082294,-0.058188,-0.014719,0.087861,-0.648667,-0.031274,0.273167,0.094598,0.053179,0.163076,0.939552,0.342037,-0.094470,0.384775,-0.073620,0.721560,-0.033493,-0.043579,-0.259197,0.642615,0.172309,-0.218014,-0.150399,-0.611774,-0.637699,0.179376,0.166647,-0.166664,-0.132330,0.229371,-0.746259,0.193009,-0.063901,-0.701759,0.197319,-0.011568,-0.160295,-1.070522,0.072324,0.046509,0.086322,-0.598006,0.461200,-0.575451,0.532752,-0.410464,0.184559,0.291876,-0.090598,-0.057619,0.364938,-0.118497,0.123515,-0.086257,-0.059478,0.419789,0.304836,-0.207296,0.159878,0.019344,0.370896,-0.415320,-0.604931,0.879123', '3318306', '26275494', '6844861', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10756518', '大梦想家', '剧情', '华特（汤姆·汉克斯 Tom Hanks 饰）是一名制片人，因为女儿莉莉安（丹德里·泰勒 Dendrie Taylor 饰）格外喜爱一本名为《欢乐满人间》的小说，华特答应莉莉安，会将这本小说中的美妙故事搬上屏幕，让更多的人领略其中的快乐与美好。为了购买小说的版权，华特找到了小说原作者特拉弗斯（艾玛·汤普森 Emma Thompson 饰），令华特没有想到的是，自己好话说尽，也未能打动这位个性固执又倔强的女作家，最终，是小说销量的下滑让特拉弗斯勉强答应了华特的请求，然而，对于华特来说，得到改编权仅仅是巨大困难的开端，当《欢乐满人间》的电影终于出炉之时，时间已然过去20年。©豆瓣', '艾玛·汤普森', '约翰·李·汉考克', 7.7, 21303, 'tt2140373', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2172238826.jpg', 0.5, 2.1, 29, 48.2, 20.1, '0.292157,0.054334,-0.358836,0.708107,0.406826,-0.384076,0.772433,0.015707,-0.642506,-0.128539,-0.240632,0.787093,-0.379473,0.120734,0.287587,0.341110,-0.391703,-0.304258,-0.019718,-0.321885,0.200831,-0.508696,-0.333018,-0.091439,-0.153478,-0.458475,0.596902,0.198279,-0.030241,0.424186,0.487159,0.253418,0.027896,0.195702,0.230449,0.149827,0.029659,-0.027498,-0.266433,0.320957,0.175629,-0.123027,-0.238139,0.310549,0.098745,0.181158,0.500537,-0.277088,-0.235085,0.018762,0.670490,-0.055013,-0.025084,-0.276092,-0.280104,0.068942,0.504873,0.131175,-0.178549,0.223009,0.155884,-0.240031,-0.985810,0.059488,0.288499,0.107316,-0.192072,0.299478,-0.126509,0.085418,0.075032,-0.449412,-0.005233,0.135230,0.490756,0.273894,0.037085,0.195643,-0.385600,0.378217,0.254111,0.172709,-0.247320,0.713555,-0.355797,-0.306426,0.086826,-0.538807,-0.700804,0.328198,0.424281,0.360643,0.005286,0.276937,-0.456411,0.171797,-0.226175,-0.308820,0.071729,-0.531292,-0.123824,-0.517065,-0.266499,-0.163496,-0.155050,-0.404271,0.208340,-0.628738,1.215596,-0.448624,0.215798,0.387819,0.015991,-0.145838,0.661030,0.092675,-0.193833,0.136076,0.031259,0.421325,0.018551,0.084356,0.055343,-0.005612,0.199099,-0.563479,-0.319199,0.814645', '27602116', '24284209', '26348103', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10756744', '史前怪兽', '动作', '故事发生在一个无名湖泊之中，近日来，在湖泊附近接二连三的发生了数起死亡事件，犯罪现场十分血腥可怕，犯罪手段十分凶残，通过一些残留的影像和证据不难发现，袭击者并非人类，而很可能是隐藏在湖底的某种野兽。塔维斯（斯科特·阿金斯 Scott Adkins 饰）是专门研究神秘怪物的专家，为了搞清楚凶手的真实面目，人们找到了塔维斯。塔维斯告诉大家，凶手正是个性及其凶残的史前怪兽，以袭击人类为乐，为了保护人类的安全以及消灭怪兽，人们又找来了英明神武的怪兽杀手哈克（杜夫·龙格尔 Dolph Lundgren 饰）。塔维斯和哈克强强联手，最终能否成功消灭史前怪兽呢？©豆瓣', '斯科特·阿金斯', '埃里克·斯泰尔斯', 3, 4522, 'tt2369041', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2163449169.jpg', 67.7, 20.8, 7.7, 1.9, 2, '0.241468,-0.256891,-0.435519,0.485942,-0.092973,0.505453,0.944958,-0.348593,-0.778728,-0.475987,0.377629,0.359740,0.013991,-0.263072,0.050625,-0.264726,-0.167372,-0.077238,0.116504,-0.271473,-0.288287,-0.571405,-0.782387,-0.463614,0.193353,-0.467506,0.520942,0.275039,-0.339712,0.015414,-0.091653,0.732094,-0.548454,0.113945,-0.144454,-0.397986,-0.136712,-0.236908,-0.195131,0.209695,-0.173454,-0.113695,-0.008405,0.299718,-0.382146,0.170296,0.714436,-0.800228,-0.341812,-0.271209,0.202373,-0.412911,0.073799,0.215296,0.528655,-0.437824,0.160771,0.221625,0.094134,-0.181549,0.034736,0.017394,-0.979497,-0.092681,0.088879,0.591661,-0.094333,-0.086165,0.118922,0.199200,0.282019,-0.332573,0.116790,0.137527,0.467976,0.225129,0.187669,-0.070798,-0.641636,-0.200163,0.618910,-0.241534,-0.134345,0.168000,-0.167790,-0.575244,-0.070999,-0.342825,-0.201638,0.221247,0.373612,0.287882,-0.520524,0.401357,-0.934624,-0.138109,-0.497634,-0.108563,-0.298853,-0.298884,-0.249593,-0.609730,-0.238475,-0.123557,0.126118,-0.056142,-0.201251,-0.419024,0.551387,-0.812188,0.077883,0.739758,0.072719,-0.333110,0.205606,-0.195317,-0.207563,-0.125703,-0.125233,0.002066,0.636489,0.066769,-0.165836,0.103780,0.321527,-0.335647,-0.167062,0.200339', '1308784', '2988294', '3213270', '1305071');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10756870', '永远的0', '战争', '2004年的一天，司法浪人佐伯健太郎（三浦春马 饰）在外婆的葬礼上得知，他和外公贤一郎（夏八木勋 饰）没有任何血缘关系，其真正的外公宫部久藏（冈田准一 饰）早已在二战末期死于神风特攻行动中。此后不久，健太郎被姐姐庆子（吹石一惠 饰）叫上去调查宫部的事迹，他们走访了宫部当年的战友，谁知许多人都将外公斥为“帝国海军第一懦夫”，其执行任务时即使看着战友牺牲也绝不卷入战局。老兵们的评价让姐弟俩颇受打击，但随着调查的深入，他们发现宫部拥有最高超的飞行技巧，他深爱着妻子（井上真央 饰）及女儿，并发誓无论如何要回到家人身边。坚定着这一信念，宫部不惜放弃帝国男儿的尊严，而他的处事方式也不知不觉影响着各期的战友们。伴随着老兵们的讲述，健太郎注视着外公迎来了最后的时刻……本片根据百田尚树的同名小说改编。©豆瓣', '冈田准一', '山崎贵', 7.3, 12059, 'tt2404217', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2211690471.jpg', 11.1, 4.3, 20.8, 37.9, 25.8, '-0.092099,-0.114583,-0.443580,0.657185,0.099436,-0.268778,0.244295,0.076536,-0.481154,-0.559487,0.311463,0.707426,0.162446,0.159411,0.262852,-0.325728,-0.229552,-0.705334,-0.271183,0.013878,-0.233119,-0.563078,0.053016,-0.327646,-0.295878,-0.259465,0.799764,0.026111,-0.256906,0.445331,0.225662,0.368674,-0.068834,0.235521,0.008063,0.186720,0.044160,-0.019609,-0.268776,0.105705,-0.103152,-0.186236,-0.170522,0.267524,0.060048,0.187939,0.694220,-0.467213,-0.198933,-0.322657,0.241272,-0.297650,-0.057417,0.183453,0.447041,0.109240,0.052037,0.592212,-0.111399,-0.091075,-0.005148,0.024921,-0.570370,-0.207415,0.177936,0.201735,-0.560376,0.459710,-0.131787,0.099636,0.142850,-0.121040,0.078191,0.439217,0.010262,0.043465,-0.442519,0.063370,-0.190524,0.394639,0.676823,-0.161954,0.100829,-0.047945,-0.241528,-0.206048,-0.173430,-0.464704,-0.507326,-0.029962,0.104502,0.197432,-0.140696,0.182913,-0.292540,-0.218715,-0.145184,-0.211410,0.178028,-0.390441,0.114973,-0.608972,0.132710,-0.626785,-0.518061,0.307580,0.000355,-0.287013,1.003349,-0.845970,-0.017834,0.409294,0.345536,-0.338278,0.438656,0.009554,-0.199419,-0.176654,-0.122532,0.364935,0.158685,0.167318,0.145143,0.153959,-0.058446,-0.143006,-0.173774,0.320357', '3811356', '25922902', '1826173', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10757577', '卡罗尔', '剧情', '50年代的美国，年轻女子特芮丝（鲁妮·玛拉 饰）在纽约百货公司担任售货员，但心中向往的却是摄影师工作。某日，一位美丽优雅的金发贵妇卡罗尔（凯特·布兰切特 饰）来到百货公司购买圣诞节礼物，结果和特芮丝一见投缘。两人相识后特芮丝得知原来卡罗尔有一个女儿，而且正和丈夫哈吉（凯尔·钱德勒 饰）办理离婚手续。通过书信来往、约会相处以及公路旅行，特芮丝和卡罗尔发现彼此就是自己的真爱，然而在当时社会这是不被允许的。特芮丝的男友认为她只是一时迷惑，卡罗尔的丈夫则请私家侦探调查取证，希望在离婚诉讼中让她一无所有。考验两位女性的时刻终于到来了：在社会压力下她们能否坚守内心、不计代价的把感情路走到底？《卡罗尔》是美国著名独立导演托德·海恩斯的新作，入围第68届戛纳电影节主竞赛单元，获得最佳女主角奖。电影根据派翠西亚·海史密斯在1952年匿名发表的中篇女同小说《盐的代价》改编，由于题材敏感，最初出版社还拒绝发行。之所以叫“盐的代价”，因为在17世纪“盐”还有另一个意思表示女性的情欲。而在本书中它隐喻了女主们的处境：没有爱情就像没有盐的肉；那么为了这份爱，你愿意付出多少代价?', '凯特·布兰切特', '托德·海因斯', 8.4, 264006, 'tt2402927', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2312679154.jpg', 0.2, 1.1, 15.7, 44.5, 38.5, '0.097436,0.069340,-0.633203,0.562582,-0.075419,-0.382017,0.559504,0.074828,-0.158326,-0.321585,0.171631,0.722281,0.032516,0.168225,0.333765,-0.069736,-0.364920,-0.501509,-0.004655,-0.235550,-0.155938,-0.533647,-0.187661,-0.162606,-0.133355,-0.402411,0.620917,0.000775,-0.051721,0.345696,0.595598,0.118717,-0.090729,0.321426,-0.105456,-0.044324,0.361283,0.232577,-0.562384,0.329061,0.085496,-0.116096,-0.186525,0.207465,0.241872,0.372037,0.437418,-0.113431,-0.144408,0.160740,0.529636,-0.039764,0.079030,0.035904,0.190420,-0.091602,0.367363,0.260081,-0.189561,0.157798,0.067729,-0.211840,-0.578818,-0.074360,0.087698,0.312745,-0.504883,0.353737,-0.293561,-0.121059,0.151992,-0.223871,0.044646,0.307011,0.425608,0.331117,0.012281,0.196099,-0.356408,0.248201,0.640362,0.062557,-0.125359,0.418156,-0.451710,-0.515473,0.008650,-0.136616,-0.418466,0.246523,0.157135,-0.032301,-0.031830,0.179833,-0.503669,-0.096879,-0.076439,-0.192145,0.157465,-0.282197,-0.099805,-0.599304,-0.224093,-0.321475,-0.141828,-0.056924,0.248420,-0.413641,0.772279,-0.635173,0.137660,0.560033,0.366963,-0.652322,0.919589,0.382652,-0.077803,-0.356148,0.001285,0.324570,-0.032605,-0.057902,-0.123243,0.225025,0.088663,-0.176557,-0.225682,0.453328', '4301278', '1456503', '30162520', '1917323');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10759740', '滴答屋', '喜剧', '路易斯（欧文·瓦卡罗 Owen Vaccaro 饰）的父母在一场可怕的事故中双双离他而去，无依无靠的路易斯只得收拾行囊投奔他多年未见的舅舅乔纳森（杰克·布莱克 Jack Black 饰）。让路易斯没有想到的是，看上去平平无奇的乔纳森，他的真实身份竟然是一位拥有强大法力的魔法师。就这样，路易斯在舅舅那栋到处都发生着超自然现象的屋子里安了家，并且结识了舅舅的好友齐默尔曼夫人（凯特·布兰切特 Cate Blanchett 饰）。屋子里总有一种奇怪的嘀嗒声，乔纳森和齐默尔曼夫人企图找到这种声音的源头却无果，而这一切的始作俑者，是邪恶的黑魔法夫妻艾萨克（凯尔·麦克拉克伦 Kyle MacLachlan 饰）和赛琳娜（芮妮·戈兹贝里 Renee Goldsberry 饰）。©豆瓣', '杰克·布莱克', '伊莱·罗斯', 5.4, 18374, 'tt2119543', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537306831.jpg', 6, 31.4, 50.9, 9.4, 2.2, '0.506245,-0.063617,-0.662759,0.569439,-0.228860,-0.362499,0.888560,0.256083,-0.426486,-0.560362,0.214691,0.749881,-0.150658,0.136570,-0.012471,0.218724,-0.335712,-0.418367,-0.018055,-0.125851,-0.220436,-0.667807,-0.362806,-0.355163,-0.040322,-0.346098,0.111515,-0.033041,-0.019201,0.324214,0.174761,0.444300,0.006546,0.420940,-0.152935,0.248046,0.298413,-0.028714,-0.082901,0.074762,0.178079,0.027828,-0.189180,0.412195,0.104207,0.346419,0.410810,-0.335416,0.275522,0.193521,0.298142,-0.037402,0.169532,0.153654,0.346264,-0.270113,0.125307,0.056693,-0.035434,-0.266043,0.307261,0.142082,-0.598150,0.255104,0.223785,0.368417,-0.534104,0.348331,-0.383964,-0.248314,0.230449,-0.491631,0.147391,0.139120,0.102276,0.399993,-0.036353,-0.094351,-0.511531,-0.064935,0.549747,0.085480,-0.273107,0.274945,-0.466368,-0.488217,-0.130167,-0.065465,-0.748611,-0.111742,0.401291,-0.053996,0.241514,0.306931,-0.552108,-0.201094,-0.502715,0.041771,-0.233920,-0.314024,0.024017,-0.531000,-0.247244,-0.515867,-0.195073,-0.022788,0.037103,-0.229023,0.413210,-0.638706,0.330050,0.524731,0.092835,-0.015993,0.357110,-0.051642,0.237760,-0.028545,-0.252601,0.134703,0.186087,0.114510,0.129318,0.550199,0.376044,-0.037372,-0.145869,0.526846', '1296534', '1422912', '1309172', '1421976');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10759926', '全城高考', '剧情', '这是一所百年老校，市示范校之一。高三九班班主任“范义本”（方中信 饰）带领全班同学在高考冲刺的最后阶段中发生的一系列的故事。剧中以当代社会最为典型的真实题材为基础，集中体现了来自四个不同家庭发生种种的情况。真实反映社会普遍的几组家庭中的故事。以四名学生备战高考的紧张倒计时阶段作为主线。任雪（陆翊 饰）班长，被父亲逼迫到海外留学，和父亲（吴刚 饰）反目导致离家出走。林叶（乔乔 饰）任雪的闺蜜，因为父母离异导致对高考的放弃，贺帆（吴俊余 饰）学习委员。因为家里筹备大学的学费被奸商诈骗。父亲贺江海（大秦 饰）为保护儿子打伤人被拘留，导致生活压力的加大。秦鹏（谭杰希 饰）偏科大王。对阳光自信，喜欢搞一些恶作剧，由于作文跑题导致高考成绩面临危机。在这四位学面临放弃高考的边缘时，“范义本”老师独特的教育手段和同学自身的努力最终解决了来自家庭和自身的各种问题。同时本片不乏正处于青春期情感萌芽的同学们之间的情感，以及青春期叛逆萌芽的同学们和老师之间的“矛盾”和“斗争”。充分写实当代各个家庭中的普遍的问题，同时也反映了可怜天下父母心和以及当今学生与家长之间存在的隔膜。也诠释了“范义本”老师的独特教育方式。', '方中信', '钟少雄', 5.5, 22486, 'tt3311014', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1841092784.jpg', 14.8, 23.8, 38.8, 15.4, 7.3, '0.492955,-0.177903,-0.501685,0.642362,0.062949,0.105768,0.270642,0.152152,-0.522390,-0.617481,0.044800,0.460850,-0.173993,0.459966,0.388882,-0.635964,-0.007206,-0.881150,-0.051525,0.059362,-0.420319,-0.596565,-0.074339,0.053307,-0.334056,-0.425310,0.806308,-0.033615,-0.484585,0.506696,0.076292,0.438166,0.007097,0.169724,0.171131,-0.193799,0.107349,0.136853,-0.411486,-0.032972,0.150491,-0.108966,-0.007671,0.103227,0.190997,0.423918,0.800437,-0.086121,-0.208327,-0.115049,0.616352,-0.206540,-0.472409,0.257873,0.614279,0.156059,0.332551,0.343570,0.004728,0.251889,-0.143894,-0.315522,-0.788988,-0.298827,0.338289,-0.057917,-0.369959,0.504580,0.294943,-0.258110,0.371128,-0.154108,0.064715,0.474566,0.349056,0.741742,-0.347488,-0.012081,0.018597,0.250510,0.663573,-0.201687,-0.398741,0.202737,-0.504307,-0.322875,-0.081060,-0.402347,-0.464332,0.127048,-0.083015,0.227057,-0.186025,0.430600,-0.510682,-0.122951,0.074558,-0.148267,0.046497,-0.518993,-0.051844,-0.559894,-0.172939,-0.527021,-0.249056,0.008151,0.107234,-0.316224,1.114751,-1.013098,-0.009117,0.220860,0.297305,-0.724763,0.504794,0.350818,0.274080,-0.418612,-0.264592,0.066553,-0.207101,-0.011687,-0.417607,0.187798,-0.030183,-0.308302,-0.184548,0.393031', '25922902', '27602116', '6963575', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10760030', '绝美之城', '剧情', '罗马，夏日，一队穿梭其中的游客。这座美得令人窒息的古老城池，正以一种神秘而冷艳的姿态诱惑着他们，让人心甘情愿地被这份精致得令人绝望的美丽所俘获，沉醉其中。然而在捷普·甘巴尔代拉（托尼·瑟维洛 Toni Servillo 饰）眼中，罗马却是一座寂寞之都。65岁的捷普是一名成功记者，风度翩翩、魅力十足。年轻时代撰写的一本文学作品让他在早年就名利双收。他辗转在各样肆意妄为的奢靡与觥筹交错的社交之中，用一双冷酷到几近麻木的双眼，目睹这座绝美之城背后的空虚与隐秘。当女高音的咏叹调再次响起，游走在平民生活与上层社会之间的捷普，开始重拾那些逝去的青春记忆，只有罗马之城仍依旧着她的冷漠与华美，不曾改变。本片斩获2014年第86届奥斯卡金像奖最佳外语片及2014年第71届金球奖最佳外语片两项大奖，并入围2013年第66届戛纳电影节主竞赛单元-金棕榈奖。©豆瓣', '托尼·塞尔维洛', '保罗·索伦蒂诺', 8.2, 49693, 'tt2358891', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1955988617.jpg', 1, 2.9, 17, 41.6, 37.6, '0.090986,0.252550,-0.850517,0.847435,0.120996,-0.168054,0.851406,-0.005152,-0.437312,-0.084726,0.124256,0.751700,-0.299335,0.495161,0.532415,-0.109229,0.040178,-0.800335,-0.536286,-0.349023,0.232599,-0.087995,-0.456957,0.167165,-0.150808,-0.455639,0.820482,0.380705,-0.099244,0.709129,0.407891,0.159268,-0.220479,0.245470,-0.299624,-0.454150,0.146676,0.061407,-0.256546,0.115710,-0.249060,-0.551154,-0.361402,0.171379,-0.302683,0.091607,0.849556,-0.302668,-0.058085,0.230844,0.621496,-0.087380,-0.166320,0.139078,0.083379,-0.062319,0.052128,0.259933,-0.064003,0.238445,-0.083608,-0.200588,-0.694428,-0.038945,0.118412,0.258689,-0.268068,0.477237,-0.007744,0.081268,-0.013482,-0.090728,0.183315,-0.082590,0.243179,0.440062,-0.037238,0.128508,-0.452760,0.427311,0.477112,0.287683,-0.771661,0.049032,-0.355808,-0.739494,0.032823,-0.568089,-0.612962,0.096863,0.370920,0.112313,0.346790,0.352951,-0.775017,0.217479,-0.065448,-0.260578,-0.032368,-0.235964,-0.130491,-0.728090,-0.210808,-0.362558,-0.222122,0.233741,0.169835,-0.183959,0.638596,-0.451005,0.569051,0.459296,0.051126,0.008101,0.622419,-0.002755,0.049853,0.075558,-0.520096,0.529384,-0.109278,0.353096,-0.288096,0.420559,-0.411502,-0.073216,-0.575820,0.678445', '1299663', '1294434', '1299261', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10763157', '逃出生天', '剧情', '广州一个炎热的夏日，高耸入云的摩天大楼内，不同行业的人们各自忙碌，经营着自己的人生。曾在消防队服役的阿强（古天乐 饰）开办的消防系统公司是日开张，另外一层的诊所内，消防特勤队大队长大军（刘青云 饰）的妻子思乐（李心洁 饰）正做着孕前检查。与此同时，大厦空调系统出现问题，防范意识较差的维修人员更引起不可遏制的火情。经验丰富的阿强迅速组织疏散，然而火势迅速蔓延到各个楼层，受灾民众的安全受到极大威胁。接到报警后，大军带领战友迅速赶赴现场。史无前例的灾害，让大军和阿强这对失和多年的兄弟再度联系起来。危急时刻，人的生命和人性经受着最严峻的考验……©豆瓣', '古天乐', '彭发', 6.7, 46018, 'tt2957680', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2147894527.jpg', 1.8, 8.8, 48.1, 32.8, 8.4, '0.223495,-0.025636,-0.773472,0.418725,0.198056,0.216310,0.694119,0.302469,-0.631423,-0.254578,0.481848,0.269440,0.060035,0.185641,0.122564,-0.346482,-0.266928,-0.635350,-0.299502,0.033081,-0.452148,-0.249197,-0.244856,-0.327789,0.017896,-0.431094,0.389430,0.323412,-0.072754,0.390142,-0.006518,0.018401,-0.207136,0.560124,-0.103716,-0.223093,0.140110,-0.269130,-0.423016,0.126491,-0.095152,-0.145832,-0.130040,0.087340,0.061390,0.488471,0.676490,-0.082682,-0.431915,-0.126120,0.539097,-0.213331,0.141974,-0.079326,0.638399,0.169111,-0.080191,0.124570,-0.381310,0.110825,-0.131755,-0.111294,-0.673764,-0.070908,0.163327,0.183542,-0.609499,0.377734,-0.167362,-0.030251,0.091426,-0.249158,0.181595,0.631058,-0.052026,0.448110,-0.360794,0.089702,-0.359701,0.051962,0.629404,-0.277877,-0.230701,-0.047436,-0.305831,-0.353008,-0.031792,-0.088665,-0.515542,-0.325786,0.063560,0.080465,0.092651,0.044945,-0.547587,0.226635,-0.045903,-0.625344,-0.041732,0.003296,-0.125227,-0.968433,-0.009130,-0.118636,-0.124000,0.449463,0.017082,0.097367,0.669921,-0.672164,-0.074101,0.453354,0.467448,-0.479490,0.375142,-0.261326,0.192855,-0.211778,-0.156984,0.119148,-0.022269,0.598125,0.102275,0.335409,-0.390560,-0.156694,-0.162865,0.127838', '1307897', '2159244', '1431694', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10763164', '扫毒', '剧情', '从小一起长大的好兄弟马昊天（刘青云 饰）、张子伟（张家辉 饰）和 苏建秋（古天乐 饰）共同效力于警队扫毒科。在一次临时改变计划的行动后，建秋因为卧底身份不能与妻子（袁泉 饰）过正常生活而心生退意，但在阿天与子伟的劝说下，三人决定进行最后一搏。建秋跟着毒贩老大黑柴（林国斌 饰）前往泰国与毒贩Bobby（卢惠光 饰）进行对接，目的是见到行动的最大目标“八面佛”（卢海鹏 饰），阿天则和子伟以及同事阿益（吴廷烨 饰）进行跟进。由于泰国警方的配合不力导致建秋身份暴露，虽然建秋答应阿天继续把交易完成，但失败的导火索已经埋下。交易当天警方几乎全军覆没，危急之时阿天挟持了八面佛的女儿缅娜（宝儿 饰）准备逃命，八面佛承诺只要还回缅娜阿天可以带走建秋和子伟中的一个，没被选中的则要被推进鳄鱼池，面对抉择阿天及进退两难……©豆瓣', '古天乐', '陈木胜', 7.6, 257651, 'tt2957774', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2157480930.jpg', 1, 4.5, 30.3, 44.3, 20, '0.097251,-0.041665,-0.529897,0.370057,0.212953,-0.257133,0.383419,0.195012,-0.378649,-0.277674,0.242557,0.337167,0.074503,-0.088580,0.251713,-0.311865,-0.282379,-0.540441,-0.093626,0.023863,-0.182166,-0.581233,-0.083047,-0.074533,-0.207347,0.012641,0.677208,-0.102573,-0.124268,0.583843,0.455865,0.344937,-0.246302,0.184547,0.141777,-0.204954,-0.139734,-0.047781,-0.801900,0.252492,0.158695,-0.005811,-0.007164,0.077985,0.246604,0.325201,0.626798,-0.418204,-0.138558,-0.188248,-0.023708,-0.403316,-0.015894,0.170376,0.152688,0.055241,0.286453,0.388629,-0.195500,0.210308,0.101923,-0.037975,-0.626048,-0.031255,0.381273,-0.052082,-0.518672,0.245618,-0.150042,0.194882,0.018638,-0.514066,0.130403,0.565297,0.415035,0.136563,-0.337493,0.007770,-0.409404,-0.026595,0.656226,-0.033364,0.177321,-0.038553,0.241419,-0.232702,-0.050026,-0.060231,-0.061948,0.111793,0.113715,0.233761,-0.159862,0.041507,-0.412636,-0.344362,-0.371252,-0.040119,-0.008702,-0.409959,0.274855,-0.568784,0.066176,-0.236531,-0.201421,0.284309,0.043987,-0.092800,0.332401,-0.721287,0.139947,0.144011,0.454765,-0.618195,0.296538,0.256640,0.335736,-0.510316,-0.009383,0.047008,-0.055713,0.254616,0.229987,0.086551,0.038529,-0.206743,-0.249314,-0.210646', '1293265', '30345227', '11776289', '6225992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10763928', '弗兰克', '剧情', '乔恩（多姆纳尔·格利森 Domhnall Gleeson 饰）是一个热爱音乐的年轻人，某天误打误撞加入了一支有点神经质的地下乐队，乐队的主唱兼灵魂人物是弗兰克（迈克尔·法斯宾德 Michael Fassbender 饰）——既是才华横溢的天才、又是终日戴着一个硕大头套的 怪人。乔恩跟着乐队到爱尔兰某个偏僻的小木屋里录制专辑，他们在此过上几近与世隔绝的生活。这一年来，乔恩一直私自将他们的生活以视频的形式发布在社交网络上。终于，乐队的奇特经历引起了某个音乐节主办方的关注，乔恩说服成员们远赴美国参加这个叫西南偏南（SXSW）的音乐节，藉此成名。本片根据乔恩·强森的回忆录改编。片中的乐队领袖弗兰克以Chris Sievey为原型。Chris Sievey在七八十年代红极一时，他同时是个风趣演员，以喜剧形象“Frank Sidebottom”驰誉。在弗兰克身上还能看到Daniel Johnston、Captain Beefheart等特立独行的音乐人的影子。', '多姆纳尔·格里森', '伦尼·阿伯拉罕森', 7.9, 48418, 'tt1605717', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195768476.jpg', 0.5, 2.6, 24.2, 47.7, 25.1, '0.313759,0.066193,-0.500970,0.745614,0.036863,-0.104313,0.689376,0.095671,-0.579319,-0.266619,0.276994,0.941572,-0.366694,0.295050,0.369422,-0.052658,-0.439852,-0.666684,-0.237130,-0.219460,-0.184667,-0.301993,-0.289785,-0.044448,-0.130643,-0.261410,0.625127,-0.038614,-0.236725,0.472939,0.426318,0.212734,-0.089377,0.054815,-0.272882,-0.104324,0.255585,-0.098734,0.025437,0.172915,-0.202010,-0.260431,-0.171783,-0.027416,0.003838,0.302657,0.605417,-0.116556,0.039877,0.055810,0.529511,-0.209741,-0.164758,-0.099049,0.297889,-0.057625,0.291208,0.042826,-0.097026,0.213348,-0.296233,-0.242614,-0.951350,0.106879,0.054984,0.410756,-0.564570,0.565628,-0.094665,-0.375688,0.061115,-0.350172,0.187777,0.049189,0.194935,0.264675,0.057096,0.111249,-0.344769,0.331982,0.602484,0.174826,-0.550590,0.174036,-0.116478,-0.545323,-0.211265,-0.159399,-0.556371,-0.104857,0.154923,-0.360251,0.173930,-0.061854,-0.739312,-0.013408,-0.050795,-0.332855,0.061527,-0.273682,-0.248585,-0.969694,-0.151472,-0.387661,-0.004101,-0.051734,-0.079960,-0.293595,0.880349,-0.906153,0.157893,0.615225,-0.099873,-0.122079,0.693358,0.092201,0.116758,-0.014251,-0.235775,0.102461,0.049453,0.210275,-0.106118,0.5092