INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10765742', '过往', '剧情', '经过四年分居生活后，Ahmad（阿里·莫沙法 Ali Mosaffa 饰）在法国妻子Marie（贝热尼丝·贝乔 Bérénice Bejo 饰）的要求下，从德黑兰来到巴黎正式办理离婚。从短暂的巴黎之行中，Ahmad看到了妻子与女儿之间冲突不断。Ahmad试图帮助其改善关系，结果发现了一段过去的秘密。', '贝热尼丝·贝乔', '阿斯哈·法哈蒂', 7.3, 6328, 'tt2404461', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1943391181.jpg', 0.8, 4, 37, 45.6, 12.5, '0.057206,0.427948,-0.949678,0.520290,0.279517,-0.382108,0.570912,-0.136173,-0.591918,-0.304545,-0.058029,0.762696,-0.374365,0.149665,0.572512,-0.373774,-0.557588,-1.128762,0.351993,-0.531927,-0.598661,-0.642701,-0.051923,-0.078045,-0.263010,-0.551997,0.548676,0.097143,0.146680,0.754949,0.126082,0.041250,-0.713509,0.360009,0.000649,-0.141896,0.270926,0.518962,-1.093143,0.635071,0.152939,-0.306721,-0.079252,-0.258635,0.305337,0.321953,0.770993,-0.182816,-0.197761,-0.041157,0.361092,0.549455,-0.153202,0.191711,0.423955,0.466225,0.487284,0.674704,-0.660651,-0.166719,-0.049527,-0.458323,-0.037518,0.132360,-0.007033,0.133754,-0.767292,0.315167,-0.109226,-0.006579,0.327231,-0.536272,0.239200,1.172817,0.413848,0.640687,-0.401771,0.417589,-0.162652,-0.080629,1.015950,-0.278202,0.113871,0.241561,0.079932,-0.280425,0.122294,0.205128,-0.051879,-0.109308,0.215670,0.145371,-0.231897,0.402192,-0.733395,-0.177449,-0.377394,-0.094893,0.397986,-0.265742,0.333528,-0.697167,-0.488090,-0.301721,-0.295419,0.302182,-0.030196,-0.292614,0.269939,-0.989343,0.407048,0.251347,0.804422,-0.518794,0.531898,0.143709,0.461321,-0.435154,0.261121,0.496345,0.050042,0.219189,-0.073511,0.153844,0.014805,-0.107992,-0.387318,0.369028', '1302987', '25978126', '1306209', '30481973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10766178', '我的男男男男朋友', '喜剧', '经过自己多年的努力打拼，谢雯婷（谢娜 饰）终于如愿在北京拥有了一家自己的咖啡店，与此同时，她和男友之间的婚事也提上了日程，日子可谓是越过越顺畅。可是，就在这个节骨眼上，男友劈腿的消息犹如晴天霹雳打在了谢雯婷的头顶，就这样，几乎是在瞬间，谢雯婷成为了剩女。感情上遭受了挫折的谢雯婷开始钻起了牛角尖，她惊觉自己曾经那种“在一棵树上吊死”的恋爱方式实在是傻的可以，在如今这个讲求效率的时代，“分散投资”才是上策。就这样，郑浩（汪东城 饰）、王永成（胡兵 饰）、陈翰（刘令飞 饰）和许博文（李承铉 饰）着四个男人同时走入了谢雯婷的生命。©豆瓣', '汪东城', '赵崇基', 3.7, 4587, 'tt5364390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2157175556.jpg', 47.7, 29.5, 17.7, 2.9, 2.3, '0.368544,0.139303,-0.753078,0.460435,-0.202617,-0.400500,0.530534,0.278188,-0.447057,0.107316,0.357343,0.574756,-0.312944,0.257060,0.149841,0.044544,0.015724,-0.988977,-0.005702,-0.279618,-0.315064,-0.340328,-0.155333,-0.034868,-0.051178,-0.278299,0.485470,0.030872,-0.207778,0.194903,0.543001,0.065947,0.173446,0.595751,-0.363348,0.182370,-0.007508,0.282169,-0.040955,0.039522,0.111375,-0.449596,0.054079,0.146195,-0.072508,0.268666,0.548673,-0.142755,-0.199036,0.242640,0.385195,-0.286105,-0.174060,0.101240,0.434307,-0.218725,0.230518,0.147051,-0.284182,0.127245,0.173084,-0.055237,-0.609115,-0.039478,-0.093012,-0.027389,-0.953309,0.484350,-0.016887,-0.241398,-0.065054,-0.389872,0.192160,0.354155,0.204476,0.416869,-0.489222,-0.040296,-0.407756,0.419483,0.588282,0.158491,-0.316973,0.581478,-0.107936,-0.374826,-0.369064,-0.182232,-0.373098,-0.394689,0.391001,-0.036516,-0.279910,0.238308,-0.417508,0.155816,-0.089381,-0.168994,0.066484,-0.328180,0.011753,-0.195452,-0.260050,-0.730582,-0.326057,0.295106,-0.074054,-0.254871,0.641971,-0.726556,0.030042,0.484240,0.207049,-0.354392,0.658093,0.118888,0.070360,-0.045952,0.231258,-0.054682,-0.298106,0.341168,0.237393,0.508796,-0.063816,-0.141432,-0.414346,0.849185', '1850797', '4301274', '21360412', '26773744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10766459', '别惹我', '喜剧', '法国一个宁静的小镇，某个夜晚搬来了布莱克一家：男主人弗莱德（罗伯特·德尼罗 Robert De Niro 饰）、妻子麦姬（米歇尔·菲佛 Michelle Pfeiffer 饰）以及他们的儿女瓦伦（约翰·德利奥  John D''Leo 饰）和贝尔（迪安娜·阿格隆 Dianna Agron 饰）。他们看似与其他的美国人没什么两样，然而一系列出格的举止却不得不让人对他们刮目相看。原来弗莱德的真实身份是历史悠久的黑手党家族曼佐尼的一员，为躲避追杀他在FBI探员罗伯特·斯坦菲尔德（汤米·李·琼斯 Tommy Lee Jones 饰）的安排下多次搬家。看似惬意舒适的隐居生活危机四伏，背负着背叛家族罪名的弗莱德终将迎来夺命杀手的拜访……©豆瓣', '罗伯特·德尼罗', '吕克·贝松', 7.2, 87743, 'tt2404311', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171003423.jpg', 0.7, 4.6, 40.9, 41, 12.9, '0.519695,-0.181389,-0.603677,0.650109,-0.077304,-0.327629,0.746608,0.476995,-0.746758,-0.632447,0.328592,0.712046,-0.028178,0.134309,0.423690,0.144790,-0.470007,-0.497485,-0.030904,-0.091043,-0.030160,-0.617709,-0.349052,-0.683154,-0.054899,-0.248754,0.315143,0.044487,-0.112867,0.420494,0.235362,0.652812,0.004462,0.187324,-0.079416,0.016098,0.341009,-0.116385,-0.477300,0.026440,-0.212808,-0.063121,-0.171295,0.187163,0.280572,0.521012,0.322454,-0.350313,0.035115,-0.156570,0.098139,-0.340973,0.043031,0.025666,0.252946,-0.485543,0.034599,0.425090,0.002075,-0.368966,0.163461,-0.174515,-0.768406,0.226011,0.289390,0.377636,-0.559188,0.602939,-0.328298,0.060114,-0.142927,-0.336525,0.060126,0.267374,0.315312,0.194260,0.320752,0.174390,-0.499423,0.022028,0.836914,0.095774,-0.186808,-0.013631,-0.551383,-0.283545,-0.038560,-0.290978,-0.707390,-0.055866,0.316195,-0.236268,0.284815,0.422571,-0.485248,-0.155849,-0.539523,-0.154415,-0.083223,-0.437392,0.078944,-0.973384,0.049576,-0.461795,-0.373871,-0.047544,0.057766,-0.054116,0.399092,-0.601363,0.293193,0.237148,0.135022,-0.157714,0.489360,-0.096047,0.315767,-0.192896,-0.317906,0.501664,0.428295,-0.163784,0.007175,0.218311,0.055329,-0.074111,-0.089782,0.325974', '3147969', '3749947', '6517421', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10771216', '郊游', '剧情', '小康是无用之人，在车水马龙中高举广告招牌维生，即便狂风暴雨亦屹立不摇。他举牌、点烟、尿尿，再举牌、点烟、尿尿，任车阵喧嚣从身旁呼啸而过。小康的生命中只有两个孩子，他们一起吃饭、一起刷牙、一起更衣，一起蜷曲着入睡。他们缺乏水电，总是在同一张破旧床垫上，伴着一颗高丽菜相拥而眠。整座城市彷佛都成了野狗咆哮游荡的废墟，河流也更遥远了。一个暴雨交加的夜晚，小康决定带上两个孩子，一同出航。', '李康生', '蔡明亮', 7.3, 11116, 'tt3119416', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169400587.jpg', 3.2, 7, 31.8, 39.2, 18.7, '0.503689,0.035110,-0.723795,0.097881,-0.006621,-0.297961,0.722754,0.342511,-0.056017,0.001651,0.463382,0.423626,-0.052163,0.521001,-0.125039,-0.467215,-0.148468,-0.812588,-0.374447,0.120294,-0.342371,-0.224953,0.005430,0.209830,-0.221246,0.005737,0.189879,-0.235132,0.351561,0.486686,0.194646,-0.580383,-0.473209,0.393997,-0.257795,-0.386688,-0.331709,0.066002,-0.136533,0.123408,-0.418227,-0.181368,0.181085,-0.311312,0.195984,0.022056,0.561219,-0.194310,0.121259,-0.042781,0.084723,0.091993,-0.032573,0.110892,0.149535,-0.144481,0.577959,-0.002325,0.004629,0.035759,0.049073,0.193290,-0.100826,0.315261,-0.095139,0.322148,-0.513395,0.416548,0.393304,0.132560,0.181088,-0.303066,0.498915,-0.149900,-0.028400,0.816844,-0.378826,0.097553,-0.671935,0.218647,0.455758,0.015539,0.299996,0.044130,-0.331593,0.094372,0.274325,-0.040074,-0.590161,-0.481526,0.123357,-0.121385,-0.382024,0.155222,-0.801796,0.421662,0.135178,-0.129140,-0.225348,0.261455,0.030263,-0.733649,0.180237,-0.130326,-0.112817,0.564447,0.135797,-0.172892,0.377467,0.093263,0.112448,0.417958,0.325642,0.372822,0.556060,-0.311219,0.337569,0.205195,0.406450,0.262536,0.129083,0.342043,0.213154,0.359038,-0.396160,0.550388,-0.768087,0.366624', '30136177', '1394176', '10466639', '1297659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10772258', '麦兜·当当伴我心', '喜剧', '麦兜电影版的第五部作品，春田花花幼稚园出现了史无前例的经济困难。即使校长（黄秋生 配音）和陈老师（许飞 配音）以及麦太（吴君如 配音）等家长使出浑身解数也没法解决。于是学校召开了一次校友筹款晚会，但是长大成人的校友们都没什么出息，欣慰的是校长无意之中发现了麦兜等小朋友的音乐天赋。经过挫折，校长终于找到了胶牌经理人（郑中基 配音）为小朋友合唱团打理事宜，演出大获成功通告不断。可惜最后关头经理人失踪，合唱团并没有为学校带来大收益。可校长在最后一场演出中发现了惊喜，春田花花幼稚园也还有成功的校友存在，众校友再一次感到了人生的真谛。©豆瓣', '黄秋生', '谢立文', 8.5, 106513, 'tt2275080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2454027095.jpg', 0.5, 1.4, 14.2, 40.3, 43.6, '-0.041980,-0.259487,-0.372050,0.331050,0.122857,-0.363320,0.191250,0.021249,-0.494151,-0.317607,-0.029618,0.389348,-0.491215,0.448229,0.149761,-0.513844,-0.230504,-0.664569,0.246546,-0.102108,-0.095587,-0.246823,0.168710,0.051925,-0.149956,-0.183708,0.542924,0.052560,-0.025647,0.642988,0.454754,-0.206371,0.095373,0.236315,0.172793,0.099705,0.530799,0.251765,-0.188218,0.209355,0.310937,-0.084590,-0.308212,0.011119,0.467503,0.222376,0.633077,0.288390,-0.226350,0.094606,0.582062,-0.324105,-0.040518,0.029151,0.274033,0.289535,0.358583,0.029120,0.192595,0.094143,-0.227149,-0.351649,-0.654745,0.187632,0.101092,-0.042959,-0.317548,0.529912,0.147055,-0.052766,0.076162,-0.393323,0.167215,0.170974,0.514289,0.332160,-0.334631,0.551436,-0.077999,0.338915,0.553820,-0.262969,-0.014839,0.458360,-0.008807,-0.506022,0.265544,-0.173484,-0.369189,0.520112,-0.026905,0.059760,-0.076345,0.091474,-0.516950,-0.196869,-0.274687,-0.413034,0.016359,-0.371287,0.164645,-0.763437,0.002387,0.089242,-0.151667,0.034205,0.195646,-0.431215,1.054539,-0.930778,-0.032625,0.338452,0.258730,-0.245787,0.780436,0.140948,0.271033,-0.166898,-0.009868,-0.442395,-0.213320,0.403286,0.271159,0.335036,0.104903,-0.740797,-0.232618,0.146972', '25922902', '1316589', '3811356', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10773181', '暗之光', '剧情', '一段跨界之爱，照亮两个年轻的生命。青涩的巴勒斯坦大学生尼莫（尼古拉斯·雅各布 Nicholas Jacob 饰）暗中潜入以色列，在特拉维夫的同志酒吧邂逅了帅气逼人的律师罗伊（迈克尔·阿洛尼 Michael Aloni 饰）。当尼莫取得学生签证可以合法出入以色列后，他和罗伊迅速陷入一段难以自拔的热恋中。然 而随着感情升温，阻力也随之而来。对尼莫来说，巴勒斯坦不耻他的性取向，以色列不承认他的身份；由于有一个激进暴力的哥哥，他更被以色列特工部门列入黑名单，签证也因此被吊销。罗伊倾尽所能为尼莫奔走，却遭到来自官方的恐吓；而尼莫的秘密也似乎被家人窥破，生命陷入空前危险中。这份暗夜中的爱情最终能否冲破阻碍、拥抱光明？©豆瓣', '尼古拉斯·雅各布', '迈克尔·迈耶', 8.2, 9049, 'tt2318625', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2070286097.jpg', 0.4, 1.5, 19.1, 43.9, 35.1, '0.542828,0.386279,-0.581775,0.791590,-0.254552,-0.294813,0.886344,0.156085,-0.443718,-0.161087,0.101215,0.605331,0.011698,-0.174712,0.259470,-0.013087,-0.268001,-0.815431,-0.027304,-0.200862,-0.027857,-0.684695,-0.347141,-0.021016,-0.330259,-0.292067,0.676926,0.190812,-0.286463,0.360454,0.247380,0.499255,-0.038810,0.507802,0.148010,-0.171738,0.362768,-0.096392,-0.424335,0.114062,0.066609,-0.159949,0.218287,0.345434,-0.291614,0.396826,0.631429,-0.183667,-0.141978,-0.352144,0.466614,-0.400467,-0.077359,0.338935,0.290454,0.125311,0.138366,0.101222,-0.177691,0.147312,0.049153,0.112544,-0.705611,-0.032434,0.177681,0.106625,-0.214703,0.310712,-0.158030,-0.098563,0.053750,-0.099747,-0.023110,0.404587,0.335284,0.309365,-0.215524,0.133085,-0.304211,-0.007124,0.691339,-0.216279,-0.458800,0.197084,-0.585727,-0.527169,0.131179,-0.002673,-0.496358,-0.183720,0.505937,-0.048200,-0.020474,0.474886,-0.704472,0.083463,-0.255664,-0.270527,-0.337202,-0.542865,0.084060,-0.579161,-0.389278,-0.298306,-0.181510,0.077864,0.163216,-0.127687,0.644491,-0.594655,0.267682,0.597286,0.386737,-0.347641,0.539454,0.266166,0.140305,-0.215248,-0.134925,0.627238,0.119287,0.198057,-0.077028,0.125375,0.119640,-0.151741,-0.220704,0.392991', '25828589', '2053515', '1296992', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10773239', '小男孩', '剧情', '故事发生在二战时期的一个美国沿海小镇，八岁小男孩Pepper（雅各布·萨尔瓦提 Jakob Salvati 饰）天生矮小瘦弱，为此没少受同龄人欺负，还被取绰号为“小男孩”（little boy）。他最好的朋友兼搭档，就是自己高大魁梧的父亲詹姆斯（迈克尔·拉帕波特 Michael Rapaport 饰）。在父亲的教导陪伴下，Pepper渡过了一段美好的时光。直到父亲应召入伍，投入到第二次世界大战的战场中去。就在Pepper期待父亲回家时，噩耗传来，他的父亲在菲律宾被日军虏为战俘，生死未卜。而此同时，Pepper和他哥哥London（大卫·亨瑞 David Henrie 饰）将战争仇恨发泄在镇上的一个日本人桥本身上，为此兄弟俩都接受了相应的惩罚。神父为了教育Pepper，将一个“古老的清单”交给他，只要他把清单上的任务都完成，他就能拥有可以移动大山的信念和力量，从而就能把他的父亲从二战战场中带回来。这个清单的其中一项，就是和日本人桥本成为朋友……', '雅各布·萨尔瓦提', '亚历杭德罗·戈麦斯·蒙特维尔德', 8.3, 59154, 'tt1810683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230105606.jpg', 0.3, 1.4, 15.6, 47.9, 34.8, '0.137227,0.036839,-0.695775,0.653899,-0.539744,-0.401764,0.596534,0.049847,-0.438243,-0.003575,0.289443,0.982968,0.152515,0.278568,0.142028,0.107920,-0.193172,-0.808337,-0.111336,-0.039282,-0.451555,-0.457167,-0.243073,-0.302825,-0.132149,-0.430583,0.567697,-0.006152,-0.134962,0.218712,0.165828,0.233009,0.057047,0.449675,-0.508837,0.077740,-0.072225,-0.190741,-0.238241,0.225263,0.008304,-0.238046,0.098500,0.287496,0.052643,0.172516,0.959624,-0.084675,0.020185,-0.143850,0.165625,-0.123899,0.096298,0.237222,0.047878,0.058724,0.076143,0.361453,-0.401935,0.061200,-0.047354,-0.203894,-0.805032,-0.111212,-0.002847,0.061342,-0.825091,0.664866,-0.165145,-0.001976,0.309566,-0.329425,0.166643,0.390655,0.022284,0.581607,-0.323231,0.039664,-0.423671,0.338116,0.569537,-0.414939,-0.018259,0.176178,-0.219259,-0.300514,0.027488,-0.355479,-0.435628,0.060143,0.377436,-0.291306,-0.325390,0.123275,-0.572807,-0.095837,-0.300349,-0.250735,0.094750,-0.478909,-0.110418,-0.407599,-0.029359,-0.240113,-0.376565,0.200900,0.288438,-0.205416,0.978211,-0.518781,0.328898,0.811543,0.395680,-0.327002,0.664342,0.225564,0.231973,-0.215327,0.210609,0.241882,0.151300,0.334604,0.144153,0.301113,0.