INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10774066', '辣手警花', '喜剧', '飞扬跋扈的FBI特工莎拉（桑德拉·布洛克 Sandra Bullock 饰）总是料事如神，屡建奇功，然而她强悍孤高的工作态度却令很多同事受不了，怨声载道的状况又再次阻碍了她的升职，莎拉的上司决定将其派到波士顿，并安排了一名新搭档穆林斯（梅丽莎·麦卡西 Melissa McCarthy 饰），共同追捕一个俄罗斯毒品集团，一方面发挥莎拉的机智，一方面则是考验她是否拥有与人协作的能力。然而这位新搭档偏偏也不是省油的灯，而是波士顿一名特立独行满口脏话的女警察，两个从未合作过的彪悍女性，开始了令人捧腹的磨合期，然而她们通力合作追捕罪犯的好戏才刚刚开始……©豆瓣', '桑德拉·布洛克', '保罗·费格', 6.7, 20618, 'tt2404463', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1976902189.jpg', 1.3, 8.2, 51.7, 29.5, 9.3, '0.276346,-0.084017,-0.454935,0.782732,-0.374068,-0.382158,0.468691,0.175046,-0.527121,-0.420405,0.277892,0.521126,-0.004720,0.094014,0.303119,-0.195576,-0.049332,-0.598063,-0.038407,-0.012872,-0.224492,-0.412483,-0.482479,-0.258310,-0.061856,-0.253425,0.535364,-0.160659,-0.291949,0.303858,0.582315,0.358613,0.016539,0.536053,0.035417,-0.308512,0.491307,-0.036113,-0.300872,0.104937,-0.040414,-0.142370,-0.313765,0.425589,0.057031,0.551941,0.397855,-0.282543,-0.229969,-0.174655,0.400475,-0.195306,0.237547,0.099652,0.501326,0.012208,0.030991,0.117226,0.021707,0.084442,-0.096630,-0.041177,-0.945488,0.118934,0.111105,-0.115391,-0.438468,0.254496,-0.076506,-0.033649,-0.087982,-0.154567,-0.232046,0.490345,0.296811,0.238989,-0.039923,0.105461,-0.400732,0.126615,0.791086,0.212036,-0.523684,0.405240,-0.106317,-0.533225,-0.023167,-0.411450,-0.454228,0.017798,0.278591,-0.078262,0.104109,0.125107,-0.594658,0.139177,-0.447205,-0.003896,-0.235064,-0.416804,0.312879,-0.793834,-0.159644,-0.386260,-0.364637,0.055403,0.076061,-0.150853,0.796020,-0.767517,-0.115339,0.724600,0.037938,-0.786501,0.296994,0.270958,0.165808,-0.413834,-0.417891,0.235738,0.202454,0.065719,0.025033,0.351349,-0.032838,-0.381123,-0.181120,0.392932', '4301278', '1793491', '30163500', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10774104', '德惠翁主', '剧情', '影片讲述朝鲜高宗的女儿德惠翁主作为末代公主的坎坷人生，导演许秦豪执导，孙艺珍饰演成年德惠翁主，朴海日饰演独立运动家，金所炫饰演少女时期的德惠翁主，金材昱饰演德惠翁主的日本丈夫宗武志。', '孙艺珍', '许秦豪', 7.6, 15675, 'tt5947416', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2359023575.jpg', 0.5, 2.8, 33.1, 43.7, 19.9, '-0.247841,0.178034,-0.076808,0.853907,0.464732,-0.118895,0.335875,0.488592,-0.144487,-0.618839,0.672786,0.637869,-0.202536,-0.257199,0.272952,-0.063751,-0.295139,-0.229150,-0.268024,0.362628,0.615486,0.099625,0.314394,0.113535,0.039552,-0.560860,1.036270,-0.720820,-0.137790,0.552126,0.729517,-0.023457,-0.217279,-0.366081,0.075346,0.692283,0.158238,-0.165430,-0.492294,0.534152,-0.160317,-0.139342,-0.032024,-0.193905,-0.113768,0.382613,0.253397,-0.218316,0.562539,-0.564350,0.989211,0.097500,0.293001,0.110582,0.237207,0.019639,0.573680,0.037337,0.009402,0.026822,-0.210950,-0.419766,-0.272826,-0.342197,0.708672,0.002553,-0.347882,-0.063261,0.199114,-0.206052,0.533133,0.034859,0.154964,0.128033,0.081451,0.277282,-0.389888,0.649081,0.008003,0.833496,0.136025,-0.005317,-0.037435,0.430927,0.084423,-0.720617,0.296471,-0.430539,-0.913922,0.500643,-0.339420,-0.568967,0.318449,0.318588,0.395061,-0.399937,-0.318970,0.245966,0.847371,-0.038117,0.450600,-0.460653,-0.318503,-0.607820,0.522441,-0.718940,0.390107,-0.442829,0.587195,-0.415412,-0.204078,0.237428,0.251337,-0.401025,0.436442,0.512608,-0.078366,-0.514643,0.166171,0.441365,-0.297253,-0.361252,-0.473417,0.214750,-0.654509,-0.480814,-0.611497,0.020914', '30488003', '1388176', '24499012', '26980827');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10774184', '豪勇七蛟龙', '动作', '故事发生在位于罗斯克里克的一座矿业小镇上，艾玛（海莉·贝内特 Haley Bennett 饰）和丈夫马修（马特·波莫 Matt Bomer 饰）在这里过着与世无争的生活，某日，镇里的恶霸鲍勃（彼得·萨斯加德 Peter Sarsgaard 饰）枪杀了马修，没有人敢追究他的责任，只有幸存的艾玛在心里默默的发誓，一定要让鲍勃血债血偿。艾玛雇佣了名为山姆（丹泽尔·华盛顿 Denzel Washington 饰）的赏金猎手，虽然她并没有多少钱能够付给她，但艾玛不幸的遭遇唤起了山姆内心里的正义感。为了对抗鲍勃和他的自卫队，山姆集结了一帮和他一样的边缘人士，他们不是恶棍就是赌徒，有的甚至还是杀人犯，但就是这样一帮怪咖，他们决定为了捍卫小镇的和平奋勇战斗。©豆瓣', '丹泽尔·华盛顿', '安东尼·福奎阿', 7.7, 43748, 'tt2404435', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2408769639.jpg', 0.4, 2.5, 29.2, 48.5, 19.3, '0.217394,-0.147857,-0.762915,0.453135,-0.232901,-0.271705,0.825841,0.009540,-0.473216,-0.041057,0.238994,0.784922,0.113971,0.217070,0.090458,0.126613,-0.353703,-0.605426,-0.055218,-0.241175,-0.092861,-0.610633,-0.297367,-0.343809,-0.253775,-0.233567,0.467453,0.097774,-0.066507,0.220537,0.357403,0.357423,0.275680,0.380712,-0.306720,0.074829,0.168004,-0.151657,-0.213288,0.043834,-0.019977,-0.044829,-0.147521,0.367426,0.303656,0.464394,0.376430,-0.400950,0.036344,0.033412,-0.067897,-0.293237,0.082931,0.123517,0.094927,-0.383032,0.157560,0.197241,-0.070087,-0.245774,0.235673,0.019350,-0.818808,-0.013861,0.034649,0.357831,-0.797973,0.520622,-0.240571,-0.104823,0.078744,-0.077041,0.197644,0.218330,0.256199,0.167378,-0.009866,-0.098552,-0.742381,0.142328,0.797520,0.053988,-0.110936,0.134225,-0.419121,-0.410736,-0.144259,-0.160081,-0.601481,-0.085174,0.215921,-0.332926,-0.216441,0.206022,-0.735538,0.023897,-0.294544,-0.332640,-0.063985,-0.272074,0.017049,-0.584902,-0.048480,-0.521063,-0.345760,0.142646,0.035320,-0.219338,0.655890,-0.973812,0.236713,0.857756,0.506341,-0.439934,0.552206,0.344379,0.092374,-0.035721,-0.017067,0.262823,0.191889,0.317538,0.262345,0.087409,0.226377,-0.291738,0.058880,0.731720', '1783461', '1292000', '1308755', '1949005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10774980', '致命弯道5：血族', '恐怖', '新的一年万圣节将至，位于西弗吉尼亚美人湖附近的格林小镇，一年一度的盛典山地狂欢节即将举行，全国各地青年男女云集于此，伴着音乐美食尽情享乐。传说在两百年前，小镇曾发生过与食人族有关的大屠杀。可是到了今天，这样血腥残酷的故事只会让胆大妄为的年轻人们更加好奇。比利（西蒙·金迪 Simon Ginty 饰）、朱利安（奥利弗·霍尔 Oliver Hoare 饰）、克鲁兹（艾米·列诺克斯 Amy Lennox 饰）、丽塔（洛克丝安·麦琪 Roxanne McKee 饰）、盖斯（保罗·鲁布科 Paul Luebke 饰）等5名年轻人便是这群狂欢者中的一分子。可是在行车途中，他们意外撞到了藏匿小镇多年且杀人无数的变态魔王梅纳德（Doug Bradley 饰）。夜幕降临，听命于梅纳德的爪牙们失去控制，开始了属于魔鬼们的血腥万圣节……©豆瓣', '道格·布拉德利', '德克兰·奥布莱恩', 5.4, 14898, 'tt2375779', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1751805110.jpg', 13, 28.6, 39.7, 11.4, 7.4, '0.257830,-0.038884,-0.751928,0.209325,-0.039083,-0.023732,0.664565,-0.088229,-0.637437,-0.197679,0.363676,0.514279,-0.409832,0.215495,0.648397,-0.038103,-0.286609,-0.498315,-0.086681,-0.286139,-0.174798,-0.176527,-0.356537,-0.301019,-0.142067,-0.416618,0.276702,0.224427,-0.064754,0.526875,0.284092,0.369168,-0.245973,0.174506,-0.375284,-0.222505,0.486896,-0.129955,-0.269061,0.067864,-0.394069,-0.197015,-0.333501,0.010001,-0.006174,-0.005034,0.685815,-0.473325,-0.032039,-0.257369,0.356767,-0.080306,-0.083898,0.251351,0.378120,-0.109139,0.116630,0.107547,0.033893,0.053477,0.015018,-0.180548,-0.357815,0.139253,-0.130257,0.238667,-0.370810,0.337643,-0.054367,-0.151510,0.152429,-0.191328,0.106758,0.158979,0.223774,0.176393,0.264254,-0.167848,-0.242721,0.278789,0.651089,-0.011975,-0.384879,0.012474,-0.027344,-0.425730,-0.028086,-0.158114,-0.306116,-0.030165,0.376927,-0.245700,-0.015618,0.561636,-0.721298,-0.159219,-0.177847,-0.452707,0.120280,0.184533,-0.534501,-0.948055,0.025029,-0.262448,-0.024026,0.113356,0.176674,0.078016,0.587019,-0.717776,0.589702,0.558965,-0.028009,-0.128631,0.271830,-0.089472,0.245094,0.178993,-0.241968,0.302350,0.302761,0.221731,-0.088862,0.413987,-0.076831,-0.146890,-0.187540,0.559082', '2159244', '2269893', '10466639', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10777687', '7号房的礼物', '剧情', '1997年，只有6岁儿童智商的智障男子李龙久（柳成龙 饰）和可爱的女儿艺胜（葛素媛 饰）相依为命，生活虽然简单清贫，却充满幸福。某天，执着为女儿买美少女战士书包的龙久意外卷入一起幼童诱拐奸杀案，而死者竟是警察局长的女儿。龙久懵懂无知，搞不清状况，昏头昏脑就被投入监狱。在7号牢房中，聚集着走私犯蘇杨浩（吴达洙 饰）、诈骗犯崔春浩（朴元尚 饰）、通奸犯姜万范（金正泰 饰）、恐吓犯老徐（金基灿 饰）和抢劫犯申奉植（郑万植 饰）等五毒俱全的“社会渣滓”。龙久孩子般纯洁的心渐渐感动了这几个“大坏蛋”，他们甚至不惜冒险将艺胜带入牢房与父亲相会。黑暗冰冷的监牢内，7号牢房阳光满满……©豆瓣', '柳承龙', '李焕庆', 8.9, 516806, 'tt2659414', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1816276065.jpg', 0.2, 0.8, 8, 33.7, 57.4, '0.040743,-0.020291,-0.295012,0.154423,-0.196971,-0.072134,0.962615,0.342977,-0.321283,-0.134645,0.260317,0.174114,-0.048171,0.387585,0.115235,0.138100,-0.213322,-0.616257,-0.437836,-0.141584,-0.195576,-0.288922,-0.022042,-0.265458,-0.013113,-0.232030,0.415488,0.063748,0.143570,0.383439,0.475802,0.211767,-0.403851,0.110581,-0.289329,-0.010501,0.157273,0.241794,-0.041290,-0.280915,-0.367173,-0.026660,0.115233,-0.183436,0.046111,0.117865,0.884989,-0.222677,-0.130712,-0.327451,0.404467,-0.019453,-0.431651,0.262760,0.173873,0.017497,0.269238,-0.132922,0.076504,-0.134605,0.426230,-0.174262,-0.411329,0.117460,0.220052,-0.122151,-0.319990,0.214280,0.090236,0.064563,0.329968,0.088467,-0.039988,-0.199411,0.180943,0.602882,-0.149285,0.069171,-0.324282,0.466444,0.197665,-0.239488,-0.073597,0.108949,-0.419047,-0.372734,0.196101,-0.197363,-0.463656,-0.032505,0.217734,-0.276205,-0.165002,0.318426,-0.293697,-0.053923,-0.124950,0.164407,0.128612,-0.275428,-0.295210,-0.134624,-0.177958,-0.308330,-0.290835,0.291761,0.074305,-0.017966,0.588295,-0.395476,0.279259,0.399094,0.107369,-0.429276,0.608396,-0.111061,-0.104837,-0.189280,-0.014035,0.390422,0.106942,-0.007494,0.233590,0.287726,-0.527651,0.147844,-0.145878,0.097297', '21619567', '1467779', '24839498', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10777780', '遗忘', '剧情', '迷你剧/电视电影《遗忘》由李晓苹编剧、连奕琦执导，是专门为台湾金钟奖而制作的。该剧是林心如工作室投资的第一部电视电影类的作品。新加坡男演员李铭顺担任男主角，这是他第一次来台湾拍戏，也是与林心如的首次合作。何薇安（林心如 饰）和罗品中（李铭顺 饰）因为生活观念的不同，面临离婚的地步，已经开始分居的生活。但是一场突如其来的车祸，让一段岌岌可危的破碎婚姻，有了重新开始的契机。在妻子因此何薇安受伤失忆后，分居的夫妻两人，竟开始发觉彼此心中最真、最初的情感。他们婚姻的命运，因这场意外而改变，他们是会牵手过一生？或是放开彼此的手呢？©豆瓣', '林心如', '连奕琦', 8, 11180, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2453758057.jpg', 0.4, 1.8, 22.2, 45.9, 29.6, '0.182931,0.026388,-0.690179,0.579868,0.272543,-0.010694,0.793336,0.161072,-0.490163,-0.205406,0.193568,1.033263,-0.373545,0.255458,0.171905,0.028571,-0.091058,-0.911165,-0.086921,0.022136,-0.131722,-0.204398,-0.229822,-0.125639,-0.265766,-0.131762,1.089834,0.193865,-0.335373,0.529087,0.565240,0.058993,-0.159049,0.343620,0.216566,0.186387,-0.226764,0.221934,-0.621066,0.105394,0.235591,-0.298889,-0.172082,0.278067,-0.082575,0.490767,0.668392,0.040006,-0.226761,-0.058530,0.711725,-0.273673,-0.246464,-0.063688,0.332356,0.255612,0.517879,0.315487,-0.167458,0.140215,-0.021932,0.014512,-0.815283,0.122805,0.221759,0.078096,-0.574125,0.370390,-0.076074,-0.113763,0.119789,-0.247840,0.347186,0.546359,0.784762,0.424538,-0.240709,-0.128319,-0.347961,0.540079,0.914658,-0.068323,-0.203906,0.871762,-0.205793,-0.530152,-0.404816,-0.314190,-0.577572,0.241134,0.002652,0.023571,-0.216476,0.282887,-0.586869,-0.020813,-0.021246,-0.102941,0.054195,-0.500949,0.306344,-0.735200,-0.448876,-0.613847,-0.335770,-0.207411,0.000187,-0.551312,0.565141,-0.816333,0.125161,0.448950,0.174650,-0.464464,0.747427,0.429627,0.172904,-0.207531,0.224320,0.062045,-0.427891,-0.029498,0.088727,0.081751,0.244832,0.029947,-0.380319,0.532878', '4301278', '25880986', '1780122', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10777783', '推理要在晚餐后 电影版', '悬疑', '带薪休假的宝生家族千金小姐丽子（北川景子 饰），好不容易和管家影山（櫻井翔 饰）乘直升飞机赶上了开往新加坡的公主丽子号豪华游轮。她在船上意外见到上司——警视厅国立署警部风祭京一郎（椎名桔平 饰），原来风祭奉市长之命护送纯金打造的K狮前往狮城。豪华一流的配套服务，让游客们乐享其中。可就在燃放烟火的夜晚，一名男子的尸体落入海中，引起不小的恐慌。在此之后，风祭、丽子、影山联合起来展开调查，而犯罪分子也以全体船员的性命相要挟禁止与外界联系。接二连三有人遇害，时间则一分一秒地流逝，影山他们能否解开凶险的谜题？©豆瓣', '樱井翔', '土方政人', 6.8, 7301, 'tt2188560', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1989955766.jpg', 1.4, 7.5, 50.6, 29.8, 10.7, '-0.050916,0.057487,-0.453465,0.346632,0.232070,-0.078419,0.436453,0.181005,-0.515303,-0.249752,0.494381,0.568060,0.031286,0.161793,0.501159,0.028595,-0.403226,-0.427684,-0.045676,-0.201937,-0.245671,-0.183881,0.014462,-0.332496,0.114984,-0.226177,0.604680,0.266729,-0.055310,0.659269,0.179186,0.141450,-0.373806,0.190288,-0.195223,-0.156457,0.171193,0.091510,-0.118388,0.298543,-0.516516,-0.319850,-0.151988,0.158928,0.511954,0.346601,0.590751,-0.342454,-0.093212,-0.040407,0.045487,-0.343011,0.185192,0.102848,0.451056,0.182104,-0.018697,0.299183,-0.353770,0.063675,0.005738,0.036384,-0.393844,0.235331,0.097282,-0.007589,-0.354219,0.334707,-0.221878,-0.223891,0.082029,-0.181637,0.182275,0.278381,-0.039945,0.104708,-0.168277,0.177948,-0.244920,0.058520,0.596231,-0.038314,-0.041424,-0.159417,-0.064714,-0.243156,-0.158362,-0.184716,-0.237606,-0.300211,0.280200,0.042024,0.237654,0.097184,-0.520907,-0.134543,-0.305973,-0.170104,-0.010907,-0.004885,-0.192690,-0.891850,0.343506,-0.312875,-0.082159,0.163903,0.471621,0.188038,0.623860,-0.509273,-0.032081,0.190585,0.248870,-0.292496,0.403960,-0.104641,-0.114460,-0.199575,-0.325979,-0.177855,0.154522,0.624378,0.013316,0.182182,-0.201526,-0.126594,-0.364775,-0.076873', '2369613', '20274039', '26365262', '26094129');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10786241', '印度有嘻哈', '剧情', '生於孟買貧民區的青年，除了要應付大學生涯的最後一年，還要兼職養家和承受家庭壓力。幸好他有青梅竹馬的女友支持，以及藉著饒舌音樂抒發冤屈，讓HipHop打開了他的世界。主角和友人的歌曲得到靚女歌手Sky的注意，繼而合作新曲，並迅即成為網上熱話。他的歌詞，精闢「貼地」，道盡年輕人面對的社會問題。但初嚐成功的他，又能否再進一步，將夢想化為現實？本片風靡印度和全球各地觀眾，延續「打死不離」的印度熱血精神。', '兰维尔·辛格', '卓娅·阿赫塔尔', 7.5, 6233, 'tt2395469', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2590043725.jpg', 0.7, 3.3, 31.8, 46.7, 17.5, '-0.071017,-0.131299,-0.377728,0.898466,0.036403,-0.278865,0.452149,0.060618,-0.371645,0.021907,-0.034400,0.885900,-0.149840,0.212291,0.439054,0.010334,0.073729,-0.823027,-0.147154,0.031309,-0.251267,-0.241870,-0.240967,-0.084228,-0.298562,-0.431781,0.921880,0.126094,-0.083477,0.424616,0.289447,0.109803,0.237337,0.333127,-0.218833,-0.035208,-0.058782,-0.007747,-0.332027,0.248232,0.222288,-0.492096,-0.361732,0.198518,-0.158236,0.331631,0.694002,-0.080378,-0.058045,-0.010000,0.689608,-0.150492,-0.143530,-0.110475,0.277037,-0.154977,0.272931,0.620872,-0.040287,-0.018710,0.137302,-0.028920,-0.845139,-0.022687,0.308642,-0.039511,-0.624076,0.597782,-0.106766,0.057476,0.001912,-0.122012,0.081166,0.565455,-0.068993,0.547756,-0.393366,-0.037990,-0.490636,0.359645,0.579000,-0.025674,-0.369659,0.354332,-0.224217,-0.761947,-0.383779,-0.324661,-0.599509,0.120004,0.204028,0.162086,-0.442298,0.141241,-0.698159,-0.082081,0.079508,-0.398770,0.239728,-0.428642,0.054756,-0.646937,-0.346452,-0.586599,-0.202691,-0.089532,0.422078,-0.358537,1.187073,-0.838239,0.048873,0.694896,0.370441,-0.471589,0.938248,0.265788,0.230054,-0.151512,-0.185076,-0.007251,-0.243543,0.079860,0.133116,0.469803,-0.099808,-0.331774,-0.186662,0.422381', '27602116', '3811356', '25880986', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10788846', '我老公不靠谱', '喜剧', '十年前，念高中的YOYO（蔡卓妍 饰）应父母的要求到英国与指腹为婚的张十三（郑伊健 饰）完婚，两人商议假结婚却在这期间产生了真感情，并走过十年婚姻。经过十年磨砺，如今YOYO与十三的婚姻生活又是怎样的呢？ 年龄的差距让已到而立之年的十三越发渴望安定的生活，他与YOYO之间的摩擦不断升级。每到争吵时， YOYO便扬言要离婚，而十三对“离婚”这个词也渐渐习惯。 在十三和YOYO的一次吵架中，两人分居了，十三遇到女学生董怡（张歆艺 饰），YOYO遇到了青梅竹马的富家子林书浩（徐正曦 饰）……他们十年的爱情最终是否会继续下去呢？©豆瓣', '蔡卓妍', '阮世生', 6.5, 42006, 'tt2458040', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1896346879.jpg', 2.7, 13.1, 50.3, 26.2, 7.8, '0.200010,-0.065541,-0.827697,0.563960,-0.020670,-0.584843,0.757543,-0.005346,-0.481433,-0.235989,0.073719,0.644535,-0.594785,0.385714,0.229263,-0.565095,0.053806,-0.849879,0.250310,-0.370528,-0.222432,-0.555929,-0.067591,0.344604,-0.286700,-0.246184,0.696018,0.083461,-0.073582,0.440581,0.245978,0.059959,-0.190238,0.204377,-0.286368,-0.044825,-0.076214,0.665683,-0.495874,-0.159141,0.023149,-0.279937,-0.163783,-0.200011,0.022905,0.414133,0.669851,-0.120480,-0.084865,0.043365,0.364505,0.044916,-0.449185,0.204154,0.396406,-0.025439,0.246185,0.803698,-0.237208,0.013084,-0.450130,-0.050740,-0.330105,0.266940,-0.099689,0.010569,-0.834580,0.444690,0.060756,-0.202029,0.183482,-0.189436,-0.008567,0.799217,0.250185,0.491811,-0.411182,0.006070,-0.382550,0.063105,0.850174,0.154493,-0.334969,0.382084,0.170502,-0.457497,-0.251708,-0.119408,-0.520644,-0.023115,0.011707,0.163165,-0.332604,0.328010,-0.773693,0.092712,-0.206614,-0.009873,0.391704,-0.340001,0.136275,-0.595865,-0.347534,-1.053511,-0.575266,0.162061,0.348272,-0.495504,0.571694,-0.856003,0.252369,0.117861,0.385976,-0.843093,0.378419,0.756724,0.092399,-0.394297,0.065644,0.109358,-0.365179,0.013825,0.125456,0.270310,-0.015962,0.164855,-0.533079,0.575636', '24325798', '26354526', '1301022', '1306465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10791575', '猎神：冬日之战', '动作', '冰雪女王弗雷亚（艾米莉·布朗特 Emily Blunt 饰）本性温柔善良，却因为痛失爱女的绝望而变得残暴和疯狂，她和邪恶的姐姐瑞文娜（查理兹·塞隆 Charlize Theron 饰）一起建立了寒冷彻骨的冰雪王国，利用冷酷和无情的规则维持她们的统治，更立下了不许相爱的规矩，违者将要受到可怕的惩罚。猎神埃里克（克里斯·海姆斯沃斯 Chris Hemsworth 饰）遇见了勇士莎拉（杰西卡·查斯坦 Jessica Chastain 饰），两人不可自持的坠入了爱河，触犯了大忌。为了能够和所爱之人双宿双飞，埃里克和莎拉决定联手推翻两位女王的暴政。这小小的反叛逐渐壮大变为了两个阵营的对抗，当得知女儿死亡的真相之后，冰雪女王弗雷迪会做出怎样的选择呢？©豆瓣', '克里斯·海姆斯沃斯', '塞德里克·萨科', 5.6, 36913, 'tt2381991', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2326492532.jpg', 5.6, 28.7, 49.2, 12.1, 4.4, '0.111070,0.268993,-0.692185,0.772324,-0.014433,-0.125143,0.806366,0.446502,-0.258774,-0.021385,0.133094,0.722131,-0.148709,-0.062912,0.409732,0.152350,-0.452868,-0.698356,-0.213972,-0.163987,-0.122817,-0.427392,-0.212770,-0.244085,-0.006727,-0.485168,0.613282,-0.020679,-0.217867,0.448903,0.365766,0.589928,0.000646,0.280897,0.078983,-0.141125,0.040676,-0.174657,-0.428538,0.070530,-0.054164,0.215924,-0.049875,0.382400,-0.018778,0.342765,0.498187,-0.794833,0.017436,-0.582256,0.385834,-0.433988,0.208230,0.397527,0.088104,-0.400240,0.093476,0.402305,0.017346,-0.123809,0.278571,-0.213605,-0.955620,0.208601,-0.067703,0.085859,-0.367304,0.263847,-0.147763,-0.110100,0.206610,-0.064710,0.055345,0.369316,0.346586,0.401490,-0.071617,-0.267414,-0.223031,-0.098009,0.815900,-0.065550,-0.463607,0.117004,-0.353316,-0.326936,-0.022463,-0.608842,-0.579444,-0.147754,0.422916,0.133890,0.101149,0.788594,-0.700679,-0.511956,-0.555309,0.024055,0.011531,-0.643663,-0.101172,-0.342492,-0.421167,-0.385224,-0.261830,0.206419,0.009960,-0.151707,0.669574,-1.048329,0.441797,0.372044,0.636211,-0.724776,0.243145,0.338512,0.052789,-0.110563,-0.010455,0.685806,0.222465,0.140380,0.238646,0.156453,0.165937,0.415878,-0.209558,0.470790', '1308837', '10440076', '26667010', '1458902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10792320', '谍影特工', '动作', '彼得（皮尔斯·布鲁斯南 Pierce Brosnan 饰）曾是一名CIA的特工，人称“十一月杀手”，他个性沉稳技艺高超，深受上司和同僚们的信赖。然而，彼得厌倦了整日打打杀杀东躲西藏的日子，他费了好大一番工夫，总算得以金盆洗手，只希望能够隐姓埋名，找一个谁也不认识他的地方，在平静中度过余生。然而天不遂人愿，一位名为爱丽丝（欧嘉·柯瑞兰寇 Olga Kurylenko 饰）女子出现在了彼得的生活中。爱丽丝手中掌握某些证据，直指数十年前的一个阴谋，此时她的生命正受到CIA的威胁，而曾经的这起阴谋，和彼得有着千丝万缕的关联。为了保护爱丽丝，彼得成为了老东家的对手，而CIA也不示弱，派出彼得过去的徒弟大卫（卢克·布雷西 Luke Bracey 饰）狙击两人。©豆瓣', '皮尔斯·布鲁斯南', '罗杰·唐纳森', 6.5, 15546, 'tt2402157', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2322146824.jpg', 1.2, 10.9, 58.1, 23.6, 6.2, '0.157330,-0.021806,-0.545407,0.573356,-0.102337,-0.313509,0.724648,0.081291,-0.650075,-0.520232,0.191825,0.595867,0.110574,0.047343,0.336505,-0.110634,-0.312880,-0.789334,-0.068189,-0.278634,-0.181859,-0.464386,-0.410326,-0.272517,-0.240013,-0.360509,0.476004,0.141248,0.027076,0.460002,0.444156,0.476089,0.053827,0.359938,-0.121312,-0.156984,0.262453,-0.006516,-0.334184,0.213791,0.124877,-0.238124,-0.242206,0.197831,-0.158054,0.272365,0.324173,-0.289157,-0.129383,-0.263868,0.008595,-0.200961,0.060352,0.253192,0.221283,-0.138396,0.203826,0.344366,-0.121449,0.071975,0.028270,-0.130460,-0.763326,0.065954,-0.008671,0.351893,-0.491597,0.456668,-0.135462,-0.071516,-0.155837,-0.320525,0.200310,0.319767,0.318063,-0.009810,-0.159185,0.127495,-0.583391,0.047312,0.740771,0.015545,-0.263767,0.278078,-0.118131,-0.216334,-0.164992,-0.337885,-0.668094,-0.105419,0.308044,-0.105197,-0.197319,0.288523,-0.430661,0.115768,-0.411404,0.013736,-0.063582,-0.330143,0.075214,-0.482119,-0.198030,-0.571787,-0.385539,0.081813,0.034912,-0.334509,0.734473,-0.851260,0.332777,0.485433,0.089486,-0.277364,0.704986,0.244013,0.161558,-0.227139,-0.081251,0.318035,0.137229,0.120299,0.093855,0.109699,-0.091637,-0.239368,-0.234258,0.275333', '35030151', '4301278', '1301022', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10792633', '金衣女人', '剧情', '犹太裔美国妇女玛丽亚（海伦·米伦 Helen Mirren 饰）为讨回在第二次世界大战中被纳粹掠走的传家宝——《艾蒂儿肖像一号》，向年轻律师兰迪（瑞恩·雷诺兹 Ryan Reynolds 饰）求助，兰迪被名画不凡的价值与传奇的经历所吸引，决定陪玛丽亚追讨名画，这本是正义行为，但他们却发现奥地利当局使出种种手段，只为留住被视为“奥地利蒙娜丽莎”的国宝画作，玛丽亚与政府机器不屈不挠地抗争的同时，重回维也纳故地，掩埋超过半个世纪的痛苦记忆再度浮上她的脑海……', '瑞安·雷诺兹', '西蒙·柯蒂斯', 7.8, 10067, 'tt2404425', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2231410371.jpg', 0.3, 1.8, 26.6, 50.6, 20.7, '0.184277,0.208725,-0.487800,0.572208,0.078763,-0.517318,0.669921,-0.247369,-0.452256,-0.324934,0.302303,0.872411,-0.262713,0.056226,0.293896,0.255503,-0.249715,-0.943905,-0.202441,-0.010237,0.081930,-0.466007,-0.468293,-0.072660,-0.162274,-0.552957,0.620555,0.070548,-0.216768,0.496999,0.285843,0.588047,-0.120709,0.037723,-0.041060,-0.071778,0.086064,-0.263276,-0.505731,0.236028,0.069985,-0.230275,-0.224827,0.219748,-0.457800,0.173382,0.598969,-0.246394,0.107059,-0.105835,0.367230,-0.268409,-0.084217,0.403266,-0.011723,0.327439,-0.128249,0.292126,-0.447872,0.122835,0.452016,0.150063,-0.521844,-0.231767,0.215919,0.201749,-0.538238,0.315751,-0.346974,0.183737,0.153193,-0.326056,0.051650,0.029164,0.172433,0.480329,-0.048904,0.101664,-0.592342,0.304185,0.382165,0.007249,-0.287365,0.067550,-0.345235,-0.278684,0.124156,-0.551070,-0.264055,0.045189,0.353327,-0.023456,0.225530,0.449274,-0.766979,-0.357099,-0.646543,-0.323917,0.000761,-0.364945,-0.121423,-0.773143,-0.493930,-0.310975,-0.169619,-0.194835,0.213926,-0.224530,0.828334,-0.495529,0.310413,0.485326,0.074336,-0.228369,0.645285,0.022706,-0.089176,0.017478,-0.176244,0.488320,0.227815,0.193952,-0.383370,-0.189698,0.144042,-0.216962,-0.345200,0.566446', '30162520', '1307146', '3811356', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10792650', '女性瘾者：第二部', '剧情', '故事紧接着上一部，乔伊（夏洛特·甘斯布 Charlotte Gainsbourg 饰）徐徐讲述，从来不知情欲为何物的赛里格曼（斯特兰·斯卡斯加德 Stellan Skarsgård 饰）亦深深着迷。乔伊和杰罗姆（希亚·拉博夫 Shia LaBeouf 饰）有了孩子，但这颗爱情的结晶却并没有让在欲海中越陷越深的乔伊感到快乐，生活的重负让原本相爱的杰罗姆和乔伊渐行渐远。之后，乔伊加入了一家SM俱乐部，羞辱和鞭打为乔伊打开了新世界的大门，同时也将她引向了毁灭的边缘。在L（威廉·达福 Willem Dafoe 饰）的手下，乔伊找到了一份讨债人的工作，精于此道的乔伊很快就爬上了事业的顶峰。眼看着乔伊的年龄越来越大，L为她物色了名叫P（米娅·戈特 Mia Goth 饰）的接班人。就这样，乔伊成为了P的养母，两人之间的关系日渐亲密，直到某一天，乔伊发现杰罗姆成为了自己的下一个讨债对象。', '夏洛特·甘斯布', '拉斯·冯·提尔', 7.9, 71697, 'tt2382009', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165465692.jpg', 0.7, 3, 24.4, 44.5, 27.4, '0.451966,0.200067,-0.674030,0.646250,-0.039782,-0.651471,0.815163,0.247585,-0.336420,-0.088299,-0.106845,0.960045,-0.303009,0.173353,0.341174,0.170346,-0.254041,-0.828678,-0.226746,-0.327414,-0.410423,-0.532869,-0.409501,-0.014463,-0.028507,-0.290132,0.544572,-0.032189,-0.090416,0.474001,0.163658,0.240448,0.181743,0.403071,-0.110538,0.129314,0.329478,0.067016,-0.027018,0.062593,0.052280,-0.302414,-0.063942,0.186954,-0.097040,0.507856,0.544370,-0.457942,0.104174,-0.114258,0.253733,-0.192200,0.112976,-0.015720,0.071701,-0.008184,-0.062899,0.202024,-0.422481,-0.015571,0.165303,-0.082909,-0.970112,0.118850,0.015840,0.125091,-0.676001,0.587141,-0.125324,-0.157834,0.090544,-0.337437,0.189992,0.386232,0.100298,0.395600,-0.265656,0.073601,-0.368274,0.038193,0.616880,0.143111,-0.177338,0.360828,-0.327916,-0.388206,-0.063833,-0.087159,-0.533431,-0.415501,0.524603,0.308565,-0.009012,0.312036,-0.664099,0.017764,-0.490861,-0.097956,-0.073686,-0.454392,0.066094,-0.618503,-0.336285,-0.452615,-0.414132,-0.067313,-0.097346,-0.382709,0.761229,-0.674474,0.389977,0.496256,0.279834,-0.287227,0.713586,0.178692,0.263279,-0.030289,-0.068673,0.372378,-0.031833,0.198325,0.300995,0.443758,0.036273,-0.047167,-0.340516,0.698135', '30162520', '3119246', '1793491', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10793610', '法老与众神', '剧情', '摩西（克里斯蒂安·贝尔 Christian Bale 饰）和法老拉美西斯二世（乔尔·埃哲顿 Joel Edgerton 饰）是情同手足的好兄弟，彼此之间感情十分要好。摩西得到了神的旨意，决心将成千上万的犹太人民从水深火热的生活之中解救出来，他向拉美西斯寻求帮助，然而，这位好友却十分坚决地拒绝了他。不仅如此，拉美西斯还对犹太人进行了惨无人道的屠杀。为了惩罚拉美西斯的暴行，神在埃及降下了“十灾”，一时间，埃及陷入了混乱与死亡的阴影之中，然而，拉美西斯并没有因此而有所醒悟，最终，他和摩西成为了宿敌。摩西知道何为自己的使命，他带领着四十万希伯来人踏上了漫漫旅途，寻找一片属于他们的家园。©豆瓣', '克里斯蒂安·贝尔', '雷德利·斯科特', 6.7, 27972, 'tt1528100', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2210708091.jpg', 1.6, 9.8, 50.8, 29.5, 8.4, '0.266441,0.113803,-0.550321,0.672987,0.094392,-0.432240,0.753321,0.115417,-0.557410,-0.207624,0.265526,1.008203,0.029577,-0.015652,0.379014,0.232380,-0.659513,-0.695846,-0.151315,-0.004941,-0.068699,-0.604607,-0.199196,-0.052842,-0.327937,-0.565887,0.445671,0.230515,-0.052423,0.375882,0.143126,0.554618,0.148994,0.476860,0.048182,0.060532,0.148414,-0.277954,-0.244564,0.161864,-0.015897,-0.097351,-0.376307,0.709057,-0.037429,0.335806,0.546522,-0.783413,0.311781,-0.087428,0.067718,-0.650914,0.013306,0.514231,-0.100415,-0.075298,-0.016541,0.378726,-0.021681,-0.185895,0.147059,-0.261932,-0.792192,-0.152283,-0.222229,0.251713,-0.740648,0.484702,-0.221062,-0.156525,0.219217,-0.146699,0.159290,0.684292,0.409931,0.433910,-0.209256,-0.343976,-0.551185,-0.024605,0.705409,-0.208171,-0.313282,0.111098,-0.414867,-0.772556,0.005165,-0.028782,-0.323506,-0.458989,0.568260,0.212723,-0.139097,0.661076,-0.756538,-0.077647,-0.506094,-0.563150,-0.097142,-0.614988,-0.046473,-0.493163,-0.454410,-0.527702,-0.197509,-0.023271,-0.098412,-0.118225,0.587369,-0.866654,0.391904,0.455466,0.454536,-0.311485,0.708922,0.156762,-0.031165,-0.104072,-0.196475,0.691353,0.212684,0.379954,0.308337,-0.115482,0.171502,-0.024062,-0.290149,0.521991', '2032339', '1308837', '1458902', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10794042', '叶问：终极一战', '剧情', '1950年，咏春派一代宗师叶问（黄秋生 饰）与妻子张永成（袁咏仪 饰）带同儿子叶准到澳门生活，继而到香港谋生。一次较量，梁双（洪天明 饰）甘拜下风，并拜叶问为师。其后，叶问先后收了李琼（蒋路霞 饰）、陈四妹（钟欣桐 饰）、邓声（陈小春 饰）、汪东（周定宇 饰）、吴赞等人为徒。但最瞩目是与红颜知己珍妮（周楚楚 饰）一段鲜为人知的事迹。汪东与吴赞好斗，四处与其他门派“讲手”，经常需要叶问调解。某夜，工友们与梁双在天台开会起冲突，叶问出手制伏众人。另一方面，邓声沉迷名利，与贪污警员同流合污。叶问向邓声晓以大义，邓声终暗中协助因引发警民冲突而被捕的李琼获释。1959年，九龙城寨由江湖中人地头龙（熊欣欣 饰）统领，经营不良勾当。邓声答应暗助魏霸天（卢伟光 饰）的狮队胜出，好让地头龙操控比赛结果。比赛当天，魏霸天偷袭吴忠（曾志伟 饰），叶问出手救助吴忠，击败魏霸天。叶问与吴忠成了莫逆之交。', '黄秋生', '邱礼涛', 6.2, 25131, 'tt2495118', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1891558983.jpg', 3.3, 15.4, 54, 20.2, 7.1, '0.006361,-0.201327,-0.161270,0.275836,0.022696,-0.229841,0.213129,0.200013,-0.550846,-0.449539,0.226898,0.292248,-0.221147,0.147695,0.328733,-0.517642,-0.064159,-0.636826,0.144119,-0.021882,-0.083480,-0.285807,-0.011490,-0.170308,-0.396796,-0.117032,0.371015,0.233385,-0.286032,0.706393,0.536913,0.410266,-0.413574,0.269536,0.085621,0.003345,-0.213430,0.316463,-0.693850,0.002968,-0.351563,-0.487838,-0.549224,-0.135754,0.054199,0.314183,0.547792,-0.051168,-0.007992,-0.549586,-0.022912,-0.326266,0.088172,0.067040,0.284790,0.155418,0.334939,0.321360,-0.079604,0.242531,-0.056603,0.059401,-0.108172,0.061809,0.406427,-0.044609,-0.229135,0.296191,-0.234082,-0.044970,-0.088542,-0.085114,0.077570,0.389837,0.150627,-0.047279,-0.012249,-0.209263,-0.301107,0.484961,0.344865,-0.034287,0.309769,-0.129846,0.443475,-0.539580,0.085258,-0.151540,0.068784,-0.015857,0.322289,-0.137676,0.252383,0.293699,-0.561622,-0.080285,-0.036100,0.160837,-0.029729,-0.239232,0.456724,-0.784910,-0.071511,-0.256389,-0.103017,0.039044,0.147179,-0.237731,0.556369,-0.549263,-0.046754,-0.017021,0.398940,-0.607777,0.343423,0.062875,0.115057,-0.270669,-0.033159,-0.060976,0.260336,0.088681,0.055852,0.204292,-0.091349,-0.061898,-0.191317,-0.210402', '1