INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10796578', '自由之丘', '剧情', '电影讲述的是加濑亮出演的日本男人前往首尔，试图与他心爱的女人复合的故事。', '加濑亮', '洪常秀', 7.3, 13481, 'tt3732252', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2193382662.jpg', 0.9, 4, 35.2, 47.3, 12.7, '0.234266,-0.354219,-0.465362,0.962417,-0.267790,-0.071733,0.884662,-0.027341,-0.252918,0.098200,0.321183,0.827728,-0.065366,0.282488,0.156746,0.207252,-0.455327,-1.154736,-0.144311,0.223174,0.192030,-0.364426,-0.078622,-0.357377,0.222524,-0.458974,0.997676,-0.313042,-0.831558,-0.034468,0.842726,0.387251,-0.416977,0.228480,-0.485376,0.057480,-0.284340,0.243848,-0.625101,0.370103,-0.045296,-0.365191,0.050315,0.153905,-0.319323,0.283804,0.972449,-0.222547,0.211527,0.007523,0.583295,-0.443975,-0.365982,0.041343,-0.171473,0.366144,0.468243,0.304950,0.050709,-0.340681,-0.113561,-0.215883,-0.615378,-0.012475,0.435985,0.129611,-0.675740,0.077785,-0.239230,0.216272,0.621667,-0.503829,0.401718,0.002291,0.583671,0.414633,0.169654,0.068353,-0.397736,0.634664,0.748416,0.190022,0.028022,0.448062,-0.034807,-0.262874,-0.341678,-0.223144,-0.748426,0.135432,0.088089,-0.568160,-0.326232,-0.052886,-0.684718,-0.159689,-0.083993,-0.178404,0.688134,-0.570248,-0.195692,-0.863636,-0.157176,-0.602398,-0.100153,-0.420406,0.066380,-0.505996,1.134174,-0.723775,0.007365,1.056094,0.494747,-0.797861,1.088745,0.483748,-0.235192,-0.327472,0.068631,0.435113,-0.056862,-0.084167,-0.478428,0.347350,-0.127446,0.088258,-0.858823,0.674232', '3811356', '1908036', '4301278', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10796594', '脑男', '悬疑', '接二连三的爆炸案让生活在东京的人们陷入恐慌之中，行事莽撞的资深刑警茶屋（江口洋介 饰）带领下属追查真凶，结果在某个偏远所在遭遇爆炸事件，随后于现场发现了自称铃木一郎（生田斗真 饰）的神秘男子。铃木举止冷静异常，茶屋随后拜托有过一面之缘的精神科医师鹫谷真梨子（松雪泰子 饰）对铃木精神状况进行判断。通过极其严格缜密的鉴定，真梨子发现铃木其人全无痛感，各项指标罕见般地平均，行住坐卧极为规律，有如一台精密的仪器。她和茶屋尝试调查铃木的身世，解开陈列在眼前的谜题。与此同时，绿川（二阶堂富美 饰）和由利亚（太田莉菜 饰）两个疯狂女子监视着铃木、茶屋和真梨子等人的行踪，将事件推向难以控制的地步……本片根据首藤瓜於的同名原作改编。©豆瓣', '生田斗真', '泷本智行', 7.1, 30768, 'tt2208020', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2120479859.jpg', 1.2, 6.7, 41.9, 38.1, 12.1, '0.094366,-0.067425,-0.391341,0.375902,-0.173749,0.101125,0.541954,0.186245,-0.627164,-0.535355,0.363034,0.347705,-0.332992,-0.067589,0.400234,-0.227066,-0.284483,-0.511474,-0.206248,-0.026476,-0.204473,-0.552812,-0.219280,-0.320217,-0.032464,-0.320620,0.595370,0.085956,-0.465298,0.333209,0.005004,0.633893,-0.488313,0.000877,0.056147,-0.177256,0.224700,-0.085358,-0.179133,0.247692,-0.254152,-0.263858,0.030386,0.198703,0.024811,0.464852,0.761946,-0.444644,-0.522457,-0.053288,0.254823,0.077631,-0.149774,0.305007,0.270613,0.158280,0.001447,0.190736,-0.610349,0.023843,0.147874,0.020896,-0.592884,-0.111753,0.355652,0.457366,-0.177577,0.120861,-0.269597,-0.231725,0.265304,-0.131313,-0.137107,0.334649,0.507613,0.152272,-0.039393,0.086991,-0.029138,-0.071312,0.231207,0.079467,-0.095254,0.217017,-0.132650,-0.625338,-0.309083,-0.056990,-0.193045,-0.022539,-0.013358,0.255401,-0.201230,0.153590,-0.414542,-0.027439,0.034174,-0.097513,0.022912,-0.183834,-0.124018,-0.993346,-0.048549,-0.458824,-0.289830,-0.071142,0.037482,-0.135382,0.614757,-0.674590,-0.119532,0.349424,-0.113385,-0.125605,0.174020,-0.016108,-0.424210,-0.292679,-0.124072,0.029695,0.426272,0.399183,0.097619,0.501442,-0.233868,-0.233189,-0.367910,0.170940', '2369613', '25723905', '1306809', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10806395', '啊，男孩', '剧情', '黑白画面，慵懒的爵士乐，不求上进的主人公和无伤大雅的小笑话，影片一开拥有某种伍迪·艾伦电影的气氛。这部来自德国导演杨·奥雷·格斯特的处女作叙述了一名普普通通的柏林年轻人生活中的琐事。成名于《希特勒的男孩》的汤姆·希林已经是而立之年但依旧长相天真，他饰演主人公尼克·菲舍(Niko Fischer)是一名法律大学的辍学生。尼克瞒着自己的父亲，每月依旧从父亲哪儿领取生活费。除此而外，他的生活可以称得上是无所事事。为此女朋友和他分手，之后尼克搬到了新住处，在那里遇到了深陷中年危机的新邻居(尤斯特斯·范·多诺尼)。诚然，尼克时常感到无聊得很，他却不愿意做出任何改变。直到被父亲发现了辍学的事实，尼克的生活来源就此中断。尽管如此，观众却对银幕上无所事事的尼克充满了同情心。尼克有位死党马特泽(马可·豪斯曼)是一名不太成功的演员，他正在演出一部二战题材的煽情剧。影片的男主角是一名纳粹分子(安德·克拉维特)，没想到，在片场这名演员却给尼克带来了一次意想不到的经历。', '汤姆·希林', '扬-奥勒·格斯特', 7.9, 6941, 'tt1954701', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206183838.jpg', 0.4, 2.1, 23.9, 49, 24.7, '0.434194,-0.088960,-0.544875,0.574003,-0.187025,-0.384138,0.903652,0.117398,-0.574683,-0.429474,0.279391,0.847247,-0.288443,0.357096,0.387244,-0.050052,-0.409070,-0.433123,-0.061455,0.035168,-0.061705,-0.447536,-0.309504,-0.090024,-0.453830,-0.245388,0.745857,-0.123176,-0.229335,0.434012,0.349810,0.344614,0.392852,0.379177,-0.083428,0.218521,0.167889,-0.140434,-0.081408,0.170602,0.291071,-0.165468,-0.266542,0.187927,-0.004251,0.341463,0.487609,0.018265,-0.016304,0.160887,0.513136,-0.227355,-0.104025,0.063770,0.141004,0.022603,0.107834,0.028846,-0.132480,-0.079338,-0.039830,-0.100551,-0.602181,0.047855,0.006897,0.485829,-0.372492,0.277334,-0.188511,0.070368,0.068998,-0.277651,-0.067731,0.189611,0.365402,0.398412,-0.022053,0.163036,-0.552540,0.218159,0.652894,0.126143,-0.503195,0.475233,-0.503542,-0.456660,-0.095025,-0.346852,-0.755399,0.241756,0.170740,-0.283014,-0.128666,0.219431,-0.469993,-0.034044,-0.136697,-0.204566,-0.147617,-0.270870,-0.041082,-0.810505,-0.203334,-0.540294,-0.309095,-0.169328,0.100105,-0.284375,0.754551,-0.724880,0.145901,0.524198,0.119358,-0.105909,0.751284,0.221043,0.023110,-0.115488,-0.040490,0.340116,0.107020,0.160900,0.047261,0.448079,0.133904,-0.385255,-0.260738,0.558947', '30162520', '1292062', '4275444', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10807892', '忘了去懂你', '剧情', '重庆白沙镇，陈雪松（陶虹 饰）与蔡伟航（郭晓冬 饰）的婚姻像略显乏味的小镇生活一样晾晒在误会和琐事中，他们为孩子的接送、亲属的埋怨，以及定时出现在陈雪松杂货店柜台前兑换零钱的出租车司机吴俊彦（王紫逸 饰）而陷入龃龉。蔡伟航所在的家具厂停产，为自谋生路，他开始联系老同学试图制作贴牌家具并盘下工厂。在这段迷茫焦灼的日子里，陈雪松与房地产商杨九城（张一白 饰）相恋的过往以及吴俊彦持续的示好不断侵入两人的关系，蔡伟航在流言的侵扰中不断爆发，却始终不能深入到妻子的内心。陈雪松向杨九城借来盘下工厂的启动资金，蔡伟航的事业似乎将踏上正轨，此时他决定带女儿做亲子鉴定……©豆瓣', '陶虹', '权聆', 6.7, 7536, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196750997.jpg', 1, 9.2, 51.7, 30.4, 7.6, '0.221699,0.376297,-0.607184,0.492709,0.049418,-0.420303,0.863234,0.240433,-0.626452,-0.473508,-0.120478,0.112383,-0.298509,0.304746,0.032811,-0.457250,-0.223920,-0.617664,-0.200657,-0.004383,-0.299837,-0.355617,-0.107874,-0.429787,-0.422543,0.144406,0.526131,0.261572,-0.172929,0.532647,0.345739,0.289198,-0.135999,0.580622,-0.157456,0.131868,-0.158633,0.375408,-0.683860,-0.275659,0.305643,-0.525134,-0.053096,-0.192755,0.572907,0.411674,0.931359,0.135715,-0.033752,0.061991,0.115750,0.176751,0.092133,0.111689,0.303915,0.346635,0.020314,-0.086619,-0.540557,0.158923,0.150298,0.092612,-0.437520,-0.277035,0.257166,0.277482,-0.796097,0.017500,-0.078837,0.171031,0.126082,-0.554222,0.339182,0.275519,0.385206,0.497642,-0.080688,0.113359,-0.586425,0.422272,0.568065,0.256729,0.013882,0.032854,-0.432902,-0.389020,-0.046087,0.267119,-0.502616,-0.316928,0.279562,-0.301234,0.211453,0.132924,-0.554941,-0.346170,0.262042,-0.347543,0.123525,-0.333711,-0.099320,-0.646639,-0.051808,-0.647855,0.144563,0.050351,0.138286,-0.186709,0.258024,-0.652711,0.196415,-0.127710,0.436409,-0.410134,0.570945,-0.040637,0.358265,-0.460861,-0.003825,0.086604,-0.042492,0.469576,0.371082,0.223443,-0.256355,-0.010465,-0.233348,0.483210', '21619567', '21348112', '1310167', '26951746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10807909', '智取威虎山', '剧情', '1947年冬，为了从土匪手中夺取控制东北九岭上万先遣军的分布图，东北民主联军203小分队队长少剑波（林更新 饰）委派侦查员杨子荣（张涵予 饰）卧底潜入最大的土匪山头“威虎山”。杨子荣凭借自己的机智应变获得了匪首座山雕（梁家辉 饰）和座下八大金刚的赏识，被封为威虎山“老九”。座山雕天生多疑，多次派人试探杨子荣，杨子荣一面与土匪多方周旋，一面涉险为山下战友传出情报。一波未平一波又起，被203小分队生擒的土匪联络副官栾平（杜奕衡 饰）趁乱逃脱，知道杨子荣卧底详情的他竟出现在威虎寨中与杨子荣当面对质，杨子荣腹背受敌陷入全面危机......©豆瓣', '张涵予', '徐克', 7.7, 374597, 'tt3950078', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2215164906.jpg', 0.8, 2.7, 26.2, 50.8, 19.6, '-0.145839,0.020286,-0.644880,0.636224,0.045839,0.170562,0.399224,0.159056,-0.542627,-0.037050,0.472449,0.381906,0.079249,-0.310875,0.206202,-0.307899,-0.213708,-0.711563,-0.312979,0.011272,0.096293,-0.104721,-0.531213,-0.165007,0.213902,-0.147083,0.528993,0.321089,-0.549755,0.420219,0.375876,0.304024,-0.288600,0.110430,0.097404,0.215926,-0.012675,-0.359097,-0.235663,0.130917,-0.280926,-0.148150,-0.335407,-0.071574,-0.020922,0.286276,0.761553,-0.524875,-0.177863,-0.137174,-0.203114,-0.282939,0.067766,-0.047175,0.459805,0.095737,-0.121371,0.210460,-0.020431,0.016910,-0.167800,-0.037937,-0.594030,-0.108438,0.118556,0.046104,-0.591463,0.033154,-0.180830,0.388924,0.201886,-0.233560,-0.072273,0.565631,0.236757,-0.095132,-0.174202,-0.169638,-0.435164,0.423534,0.395377,-0.123445,0.122208,-0.587885,0.343085,-0.317624,0.157584,-0.247366,0.120879,0.051176,0.459444,-0.442816,0.190730,-0.018053,-0.335760,-0.224834,-0.353459,0.185553,-0.198411,-0.168196,-0.064202,-0.746169,-0.165321,0.133099,0.030078,0.217167,0.162272,-0.005549,0.422190,-0.524737,-0.047052,0.403064,0.066645,-0.474137,0.201988,0.153177,-0.090097,-0.447747,0.017757,0.027251,0.479646,0.452282,0.480624,0.067523,-0.629775,-0.506723,-0.256006,-0.214485', '1916282', '25723905', '4014397', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10807916', '白发魔女传之明月天国', '动作', '川陕总督卓仲廉的孙子卓一航（黄晓明 饰）刚刚成为武当派的新掌门人，藉此良机，他奉紫阳道长之命前往京城进奉红丸。谁知巨阉魏忠贤（倪大红 饰）从中作梗，用假红丸毒死登基不久的明光宗，之后把持朝政，派出锦衣卫追杀卓一航。与此同时，川陕副将金独异（赵文卓 饰）图谋害死卓仲廉，栽赃救助灾民的魔教女子玉罗刹（范冰冰 饰）。混战中有过一面之缘的玉罗刹和卓一凡再度相逢，并坠入爱河。然而好景不长，锦衣卫的魔爪分别伸向玉罗刹所在的明月寨以及武当山，有情之人被迫分离。为免除武当覆灭之难，卓一航只得忍辱负重归顺阉党。得知卓一航娶妻消息，玉罗刹一夜白头。乱世之秋，男女传奇千古流传……©豆瓣', '范冰冰', '张之亮', 3.8, 77196, 'tt3465456', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190764206.jpg', 40.8, 36.7, 17.8, 2.7, 2.1, '-0.331523,0.217565,-0.337881,0.421512,0.187804,-0.124061,0.257387,0.333916,-0.494200,-0.183411,0.181576,0.277269,-0.196801,-0.150797,0.509602,0.000290,0.201159,-0.695120,-0.246954,-0.304271,0.038236,-0.088662,-0.118362,-0.000561,-0.133497,-0.212726,0.774967,0.380559,-0.035526,0.421722,0.396854,0.228568,-0.678136,0.140623,-0.113571,0.114097,-0.035894,0.132509,-0.504266,0.149665,-0.404780,-0.484876,-0.056448,-0.021655,-0.250583,0.335627,0.239983,-0.619045,0.173115,-0.587530,-0.036106,-0.049541,-0.249185,-0.229958,0.483036,0.076727,0.085389,0.619084,-0.057188,-0.252348,-0.204195,-0.029951,-0.140368,0.217651,0.392879,0.014113,-0.197349,0.224863,-0.235511,0.462720,-0.431772,-0.114532,0.098546,0.371355,0.196115,-0.117257,0.013478,0.056129,-0.455380,0.585355,0.464062,-0.193565,0.279025,-0.267117,0.526074,-0.174927,0.432076,-0.256126,0.041239,0.041401,0.523031,-0.081305,0.136078,0.319376,-0.014980,-0.265836,-0.620796,0.534871,0.263577,0.170418,0.042670,-0.439309,-0.146070,-0.038120,-0.052514,-0.170205,0.404431,-0.028577,0.350016,-0.400588,0.133448,-0.150766,0.195079,-0.663110,0.286548,0.096869,0.164413,-0.325538,-0.393920,0.396068,0.355694,0.174045,0.031359,-0.232189,-0.262841,-0.263496,-0.276891,-0.230502', '1294564', '1307023', '1292506', '1295987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10808442', '爱在午夜降临前', '剧情', '被影迷奉为爱情圭臬的《爱在黎明破晓前》、《爱在日落黄昏时》终于迎来了第三部《爱在午夜降临前》。第一部中美国青年杰西（伊桑·霍克 Ethan Hawke 饰）坐火车邂逅法国女孩赛琳（朱莉·德尔佩 Julie Delpy 饰），两人在维也纳度过难忘一晚；9年后的第二部，杰西已成 为作家，他的小说让他和赛琳在巴黎重逢，两人于日落前再续前缘。如今又一个9年过去了，杰西与赛琳已经一起生活并有了一对双胞胎女儿，对人生和爱情也有了更多感悟。《爱在午夜降临前》就是撷取他们在希腊伯罗奔尼撒南部小岛度假的最后一天。导演理查德·林克莱特和两位主演就像与影迷在赴一个每9年的约会，尽管三部曲的制作跨度长达18年，但故事情节几乎可以写在一张纸的背面。电影惯于只用人与人的对话讲述故事，两位主人公或行走在静谧的村落，或悠然坐在露台和餐桌前，不断的讨论着文学、爱情、生活、两性等话题。然而与前两部不同的是，随着他们终于走到一起，爱情的浪漫也开始被生活的日常琐碎和彼此相处的实用性取代，吵架拌嘴也随之而来。如何在“婚姻”的面纱下维持爱情？电影将18年的感情铺开，再徐徐化解那些小小的怨念，呈现爱情最真实动人一面。', '伊桑·霍克', '理查德·林克莱特', 8.9, 362814, 'tt2209418', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2074715729.jpg', 0.3, 0.9, 9.1, 35.3, 54.4, '0.135169,-0.120299,-0.639488,0.618491,0.369217,-0.455670,0.982145,0.112910,-0.314171,-0.101497,0.064810,0.791433,-0.418524,0.419973,0.576056,-0.173491,-0.528803,-0.879786,-0.000909,-0.213400,-0.217930,-0.303295,-0.114028,0.061722,-0.193423,-0.243417,0.751044,0.103553,0.067496,0.480735,0.198039,-0.028795,-0.259856,0.381563,-0.231221,-0.052041,-0.001898,0.298799,-0.646630,0.173637,0.120293,-0.244071,-0.239875,-0.216919,-0.092323,-0.005683,0.830454,-0.319254,-0.114970,0.085198,0.448199,-0.088593,-0.047642,0.125066,0.205709,0.042934,0.289598,0.412337,-0.198282,0.056104,-0.148915,-0.286896,-0.643651,0.156538,-0.134641,0.148470,-0.496248,0.829746,-0.028648,-0.098592,0.247407,-0.384663,0.274315,0.442439,0.354300,0.456339,-0.117412,-0.203873,-0.400049,0.284239,0.657040,0.312835,-0.215915,0.719755,-0.219885,-0.242835,-0.244271,-0.074519,-0.458248,-0.092740,0.127302,-0.018926,-0.135044,0.330550,-0.872326,0.155066,0.092506,-0.238129,0.363721,-0.472121,-0.220677,-0.698452,-0.329779,-0.576690,-0.379973,0.108610,0.223491,-0.356373,0.899907,-0.721296,0.436562,0.477775,0.331132,-0.116988,1.003984,0.304358,0.056951,-0.134194,0.202098,0.486364,-0.217173,0.336896,0.132252,0.330450,-0.110246,0.268229,-0.652830,0.663139', '30162520', '3055049', '2334814', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10810745', '超验骇客', '动作', '近未来，天才科学家威尔·卡斯特（约翰尼·德普 Johnny Depp 饰）开发出最接近人类的人工智能机器人“品（Pin）”，他在收获来自科学界的美誉同时，也遭到无数反对者的诟病与抨击。在某次会议之后，威尔遭到激进组织成员的枪击，虽然当时侥幸逃生，但涂抹了放射性物质的子弹还是慢慢销蚀了威尔的生命。威尔的妻子兼研究伙伴伊芙琳（丽贝卡·豪尔 Rebecca Hall 饰）自然痛不欲生，但她却和丈夫的好友马克斯（保罗·贝坦尼 Paul Bettany 饰）设法，将威尔的意识数据化上传到智能电脑中。奇妙而幸运的是，威尔成功在虚拟世界中复生。他的天才头脑和先进科技完美融合，只是没人能够想到，这种局面对人类来说究竟是幸运还是灾难……©豆瓣', '约翰尼·德普', '沃利·菲斯特', 6.6, 90447, 'tt2209764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178116605.jpg', 2.3, 12.3, 47, 28.1, 10.3, '0.058857,0.125857,-0.583748,0.386152,-0.214698,-0.106984,0.802114,-0.049931,-0.549766,-0.153316,0.355696,0.671072,-0.022968,-0.248985,0.369918,-0.048699,-0.214249,-0.436960,0.221742,0.010188,-0.326152,-0.801387,-0.575900,-0.422267,-0.012174,-0.603060,0.664267,0.276521,-0.559099,0.124998,-0.024357,0.563243,-0.064732,0.548284,0.155669,-0.173118,0.281722,-0.257358,-0.123463,0.100493,-0.021568,-0.216844,0.050923,0.281745,-0.075050,0.233775,0.469563,-0.346014,0.118807,0.021151,0.163857,-0.257320,-0.154784,-0.050600,0.098757,-0.003206,0.261279,0.089308,0.299553,-0.239653,0.080712,0.061860,-1.117931,-0.059826,-0.123861,0.159725,-0.417879,0.360434,-0.270803,-0.069883,0.078081,-0.355851,0.214474,0.308613,0.369443,0.336322,-0.365585,0.057191,-0.358475,0.129167,0.262372,0.049746,-0.598229,0.391515,-0.258723,-0.836152,-0.353031,-0.379683,-0.337153,-0.022769,0.428806,0.208478,-0.100108,0.666502,-0.606666,0.103457,-0.299474,-0.340200,0.121835,-0.183668,0.100967,-0.548963,-0.175512,-0.371363,-0.729848,-0.153035,0.049086,-0.426727,0.792715,-0.919416,0.240914,0.564286,-0.029993,-0.418901,0.666034,0.005976,0.112360,-0.127601,-0.262352,0.589143,0.010248,0.275785,0.005287,0.354279,0.315137,-0.438161,-0.434324,0.426335', '1793491', '24284209', '25932086', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10827168', '大叔，我爱你', '喜剧', '十八岁的“红星社二代”乐队主唱沈绮（付梦妮 饰），在一起事故中，与刚从香港归来的风度翩翩中年男子方家成（张智霖 饰）一眼投缘。方家成为了在母亲面前隐瞒在香港失业无奈回到上海的秘密，瞬念之间“绑架”了沈绮当自己女友。情窦初开不识风情的沈绮，就此一发不可收拾，酒吧买醉，江边狂呼，现场邀唱，死乞白赖，萝莉不善爱情，只能真情呼唤。方家成似乎有所回应，却又犹豫不决，毕竟一段二十年前的回忆不断困扰，无法释怀，情何以堪。就在沈绮死了念想决然去澳洲念书的时候，一个从黄浦江里捞上来的旧箱子，揭开了一段非凡时空的秘密……©豆瓣', '张智霖', '胡崇曦', 5.4, 8908, 'tt7361540', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1816934635.jpg', 13.6, 28.1, 40.4, 12.1, 5.9, '0.329317,0.283590,-0.673324,0.262938,-0.039561,-0.355132,0.847641,0.000920,-0.466880,0.073058,-0.188574,0.496431,-0.111511,0.704513,0.057463,-0.155020,-0.290274,-0.727132,0.029554,-0.411827,-0.123902,-0.260973,-0.138344,0.142172,-0.180829,-0.003514,0.381683,0.219101,-0.267977,0.586684,0.540993,0.258165,-0.538506,0.437094,-0.224806,0.162127,0.218739,0.426522,-0.256381,0.016511,0.055059,-0.469038,-0.129935,0.122571,0.097885,0.183189,0.659584,0.045255,-0.038958,-0.050569,0.312338,0.180427,-0.213181,0.064622,0.313548,0.109300,0.191593,-0.002609,-0.373336,-0.210446,-0.081311,0.015741,-0.272767,0.131222,0.050591,0.216243,-0.661735,0.318436,0.007797,-0.079947,0.154239,-0.239323,0.096943,0.203600,0.402544,0.257974,-0.312499,0.219175,-0.493185,0.446341,0.671585,0.313499,-0.056214,0.221172,0.166345,-0.199256,-0.017725,0.061568,-0.515456,-0.137120,0.288904,0.007621,-0.120447,0.085700,-0.306497,-0.207800,-0.129049,0.191385,0.146012,-0.356029,-0.068023,-0.285100,-0.317579,-0.203715,-0.092995,0.094708,0.081192,-0.135232,0.437260,-0.476621,0.333180,0.251933,0.090496,-0.493520,0.483129,0.113587,0.081867,-0.227664,0.313434,0.249655,-0.217428,0.189289,0.196710,0.393844,-0.118731,-0.039467,-0.332194,0.337166', '1773217', '3111650', '2365260', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10827341', '疯狂外星人', '喜剧', '远在宇宙另一端的波波星人因为不堪忍受瓜星人的侵掠，于是举族远迁，将蔚蓝的地球视为他们新的定居点。在颟顸的领袖的指挥下，波波星人将人类驱逐到澳大利亚一处专门修建的定居点，还美其名曰与人类和平共处。绰号“小费”的女孩格莱图蒂•图奇是城市中唯一的落网者，她思念被抓走的母亲，于是带着爱猫驱车寻找母亲的下落。半路上小费遭遇了一名波波星人小欧，小欧是一个令同族人唯恐避之不及的麻烦所在，他不久前用手中的仪器发送了乔迁派对的邀请，谁知其中一条群发给了瓜星人，他由此被同类视作叛徒遭到追捕。类似的遭遇让小费和小欧坐上同一辆车，他们由此踏上惊险的旅程，期间则得知瓜星人追逐波波星人的原因……©豆瓣', '吉姆·帕森斯', '提姆·约翰森', 7.4, 73983, 'tt2224026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2235609577.jpg', 0.8, 4.2, 35.4, 42.5, 17.1, '0.584053,0.107280,-0.651691,0.645614,-0.238066,0.214897,0.605297,0.068577,-0.474350,0.075437,0.158133,0.713664,0.013072,0.095657,0.381823,0.130172,-0.254416,-0.457578,-0.141853,-0.172632,-0.414864,-0.158144,-0.167355,-0.322179,-0.045877,-0.349951,0.520330,0.192022,-0.235580,0.485148,0.037602,0.554144,-0.389280,0.551877,-0.285352,0.093014,-0.016286,-0.131892,0.086797,0.250224,-0.275244,-0.317229,0.161916,0.267211,-0.305331,0.556063,0.763435,-0.329493,-0.033392,-0.452830,0.172568,-0.368580,0.282562,0.006132,0.400775,-0.036182,0.255817,0.074384,-0.142898,-0.116019,0.279440,0.000655,-0.730040,-0.044240,0.123184,-0.093188,-0.587320,0.461450,-0.106250,0.127229,0.207428,-0.140143,0.258732,0.422514,-0.014729,0.390956,0.021811,-0.083735,-0.410006,0.071604,0.740814,-0.210973,-0.203680,-0.012126,-0.036625,-0.362021,0.160946,-0.265641,-0.480508,-0.203621,0.425262,0.143780,-0.097689,0.160680,-0.893898,0.251151,-0.415592,-0.257140,0.197321,-0.416188,-0.297520,-0.618167,0.205476,-0.110710,-0.067581,0.226073,0.134695,-0.233500,0.702046,-0.422182,0.173197,0.742995,0.407607,-0.513079,0.859585,-0.186482,0.081883,-0.209143,0.062400,0.186852,0.419163,0.434471,0.166145,0.041781,-0.199016,0.062854,-0.255254,0.453492', '3147969', '26290398', '19965431', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10828426', '绝色武器', '动作', '国际刑警龙志强（洪金宝 饰）因侦破一宗逾亿元的犯罪交易，而被以“玫瑰夫人”为首的犯罪集团报复灭门，并截去其女小凤。龙志强幸逃过大难，他深信女儿仍在生。小凤（谢婷婷 饰）被玫瑰夫人洗脑后训练成一代超级杀手。十五年后，小凤出道与其他同门在黑道大开杀戒。由于小凤武艺高强，每次均能完成任务，玫瑰夫人更因 此将犯罪集团扩大，任务遍及世界各地。在一次执行任务时，小凤因放人一条生路，反而受伤流血。经基因测试，警方发现小凤的基因与龙志强当年失踪的女儿完全一样。龙志强决心重新调查，对玫瑰夫人集团对决，然而龙志强却没有意料到自己已成为亲生女儿追杀的目标……©豆瓣', '谢婷婷', '麦子善', 4.1, 7179, 'tt1857797', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1609903887.jpg', 34.4, 36.6, 22.4, 4, 2.6, '-0.192203,-0.000903,-0.238385,0.430812,-0.003443,-0.401204,0.237382,-0.017860,-0.636832,-0.331409,0.589538,0.580036,-0.060224,0.119134,-0.041844,-0.221434,0.021450,-0.564472,0.150318,0.046799,0.039756,-0.290656,-0.001619,0.093651,0.119196,-0.114558,0.619805,-0.035654,0.066819,0.534659,0.095785,0.305460,-0.373845,0.198311,-0.088463,0.021819,0.210600,-0.071284,-0.502489,0.232027,0.094736,0.003365,0.038790,0.262167,-0.040947,0.382826,0.594917,-0.489177,-0.139559,-0.673701,0.505169,-0.518011,0.126248,0.148814,0.615494,0.137307,0.271680,0.497814,-0.080534,0.019220,0.122234,0.082783,-0.754987,-0.067353,0.369472,0.271085,-0.433628,0.442484,-0.481343,0.109629,-0.196123,-0.194995,0.109427,0.440795,0.065890,-0.016207,-0.492001,0.119781,-0.596158,0.149806,0.413396,-0.436601,0.116001,0.113742,0.491538,-0.428334,0.191180,-0.326693,0.085164,0.289094,0.234135,0.227079,-0.112354,0.502422,-0.517084,-0.137174,-0.568253,0.168555,-0.176144,-0.332309,-0.220158,-0.469688,-0.051262,-0.027924,-0.071460,0.164595,0.206247,-0.285645,0.323288,-0.697557,-0.175751,-0.064904,0.342198,-0.840844,0.099005,-0.032481,0.154933,-0.499215,-0.254956,0.031916,0.131792,0.344371,0.262317,0.146309,0.189967,-0.205193,0.007258,0.056562', '10604851', '26678784', '1307106', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10831445', '百鸟朝凤', '剧情', '老一代唢呐艺人焦三爷（陶泽如 饰）是个外冷内热的老人，看起来严肃古板，其实心怀热血。影片表现了在社会变革、民心浮躁的年代里，新老两代唢呐艺人为了信念的坚守所产生的真挚的师徒情、父子情、兄弟情。本片改编自肖江虹同名小说。', '陶泽如', '吴天明', 8.3, 286627, 'tt3214392', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2332714135.jpg', 0.5, 1.9, 16.4, 44.5, 36.6, '0.070740,-0.066621,-0.481302,0.655584,0.380072,-0.005401,0.777205,0.354280,-0.527588,-0.231833,0.173212,0.485497,0.187134,0.115549,-0.082850,-0.475724,-0.159361,-0.374702,-0.693716,0.066646,0.505920,-0.173111,-0.116085,0.031059,-0.685619,-0.429535,0.726212,0.371689,-0.263398,0.209272,0.663687,0.298606,-0.004373,-0.090698,0.197490,-0.139610,0.024949,-0.034970,-0.536870,-0.259340,-0.013576,0.215002,-0.152637,0.082222,-0.096943,0.519327,0.425479,-0.137492,-0.220186,0.173920,0.593782,0.241776,-0.264779,-0.001518,-0.037734,0.361831,0.464025,0.354651,0.242753,0.072336,-0.268523,-0.222913,-0.633074,0.176286,0.212653,0.337348,-0.458404,0.917321,-0.020836,-0.283921,-0.093703,0.082196,0.264246,-0.485207,0.677752,0.331553,-0.121395,0.288783,0.002263,0.262070,0.715948,0.136585,-0.513157,0.425976,-0.807497,-0.293123,0.029827,-0.199545,-0.699470,-0.314157,0.235016,-0.324015,0.164302,0.380840,-0.466023,0.162878,0.326852,0.451179,-0.054650,-0.457966,0.032921,-0.268624,-0.445285,-0.412315,0.020607,-0.400907,0.413735,-0.347869,1.175048,-0.631886,0.021921,0.233146,-0.074323,-0.741102,0.585353,0.253137,-0.356986,-0.112960,-0.345160,0.533908,-0.329237,-0.158669,0.030846,0.143322,-0.514757,-0.190514,0.017250,0.320297', '26348103', '27602116', '25882279', '26790961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10831449', '搞定岳父大人', '喜剧', '范坚强(徐峥 饰)是一名国家二级咨询师，开着一家普通的心理诊所，挣着一月四千的工资，无房无车，却有着一个性感美丽的空姐女友苏茜(林鹏 饰)。中秋节是他和女友约定好拜见岳父岳母的日子，在紧急结束了对病人掉坑男（仁龙 饰）的心理治疗后，和女友开着向死党吴奋丹(郭明翔 饰)借的车从上海开往苏茜父母杭州的家。一到苏茜家，范坚强就被眼前别墅的规模震撼的瞠目结舌，而更他吃惊的是，苏茜的父亲，竟然是自己的病人风衣大叔苏伯虎(许绍雄 饰)。苏伯虎是一名很有名望的经济学教授，分外看重名声的他不相信范坚强的职业操守，担心着自己不为人知的秘密被范坚强所泄露，令自己身败名裂，所以一心想要把范坚强赶走。而范坚强事先准备的应对岳父岳母的考题也无法骗过先前为自己出谋划策的苏伯虎，只得坦诚相待。知根知底的二人一见面就冲突不断，笑料百出。一穷二白的范坚强到底能否获得岳父的认可，最终搞定岳父大人？', '徐峥', '李海蜀', 6.4, 57646, 'tt2459282', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1650860828.jpg', 2.5, 12.7, 52.8, 25.3, 6.7, '-0.013413,0.104099,-0.435744,0.464738,-0.470301,-0.268280,0.589619,0.131935,-0.348680,-0.443688,0.184848,0.540694,0.010951,0.395222,0.315116,-0.059342,0.067363,-0.403878,-0.140030,-0.007849,-0.321025,-0.548739,-0.280045,-0.414619,-0.135048,-0.164622,0.369515,0.183433,-0.229417,0.185889,0.595847,0.193836,0.143562,0.398059,-0.376144,-0.160997,0.015421,0.119449,-0.225049,0.013110,0.208324,-0.193673,-0.005287,0.346937,0.240379,0.478316,0.400649,0.220632,-0.456755,0.126773,0.456913,-0.066549,0.207762,0.147309,0.349867,-0.026999,0.014633,-0.003348,-0.211546,-0.049240,0.142250,-0.055480,-0.720594,-0.021202,0.344128,-0.164603,-0.732258,0.256623,-0.122764,-0.010976,0.107726,-0.296017,0.053397,0.378030,0.117689,0.444537,-0.036373,0.265622,-0.468450,0.316511,0.583356,0.144674,-0.148221,0.303817,-0.350843,-0.402619,0.000765,-0.293398,-0.798327,-0.008196,0.242574,-0.017498,0.135122,-0.104082,-0.206618,-0.274613,-0.173727,0.111046,-0.074357,-0.378016,0.071464,-0.241974,-0.020680,-0.535461,-0.250647,0.216699,0.142676,-0.238064,0.851015,-0.548883,-0.055482,0.227912,0.285037,-0.768735,0.821412,0.292301,-0.006899,-0.221307,0.119805,0.109310,0.155363,0.018776,0.018673,0.408683,-0.090571,-0.336945,-0.219314,0.431552', '26348103', '24