INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10833867', '清须会议', '喜剧', '天正十年，爆发了左右日本战国史的最重要事件——本能寺之变，第六天魔王织田信长（筱井英介 饰）霸业梦断。他的属下在继承信长遗志的同时，也展开了关于继承者的明争暗斗。丹羽长秀（小日向文世 饰）和笔头家老柴田胜家（役所广司 饰）主推信长的三子信孝（坂东巳之助 饰）；另一方是讨伐光秀而声名鹊起的猴子羽柴秀吉（大泉洋 饰），他在军师黑田官兵卫（寺岛进 饰）辅佐下力推信长的次子信雄（妻夫木聪 饰）。双方各自争取信长的妹妹阿市（铃木京香 饰）的支持，同时争取一切可以争取到的力量。决定历史走向的清须会议召开在即，谁才是最终的胜者？©豆瓣', '役所广司', '三谷幸喜', 7.2, 6542, 'tt2245884', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2018581855.jpg', 0.8, 4.4, 40.6, 41.7, 12.4, '-0.287514,0.020695,-0.446241,0.393747,0.274564,-0.269391,0.031394,0.390786,-0.162022,-0.401757,0.466454,0.483998,0.004198,0.068646,0.334954,0.084984,-0.077925,-0.824214,-0.080892,-0.126521,-0.061198,-0.428377,-0.046517,-0.171153,-0.212645,0.061599,0.933389,0.177463,0.084821,0.175015,0.527892,0.266320,0.008997,0.215639,0.083034,0.168507,-0.135270,-0.216823,-0.225678,0.185828,-0.237313,-0.384060,-0.406342,0.169992,0.189163,0.207483,0.680526,-0.641329,0.150577,-0.149814,0.313718,-0.154562,-0.257668,0.322568,0.576784,0.151732,-0.055623,0.603141,-0.089663,-0.169880,-0.070931,0.017782,-0.545697,-0.288709,0.178907,0.220618,-0.453920,0.706470,-0.147049,-0.280233,0.332363,-0.361211,0.037501,0.618299,0.079130,0.002309,-0.390418,0.050360,-0.242829,0.197113,0.296019,-0.050714,0.093845,-0.023088,0.109929,-0.359807,-0.450530,-0.261188,-0.163878,-0.278624,0.489514,0.015547,0.414800,0.227072,-0.347859,-0.311612,-0.130492,-0.103750,0.485309,-0.000738,0.174740,-0.482592,-0.004853,-0.489258,-0.121220,0.381630,0.395406,-0.115568,0.880162,-0.732900,-0.287275,0.353222,0.117955,-0.371526,0.291303,0.154176,-0.017883,-0.365878,0.039184,-0.064666,0.199908,0.302052,0.305692,0.222066,0.032915,-0.238709,-0.433333,0.103068', '1826173', '26615753', '25880986', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10833919', '美姐', '剧情', '铁蛋的爱情开始得早，八岁就恋上了邻家巧妇美姐（叶兰 饰 成年美姐）。文革禁唱地方戏曲二人台，也驱离了美姐一家人。辗转十多年，铁蛋（冯四 饰）俨然已是条汉子。随着美姐（杜焕荣 饰 中年美姐）与三个女儿返乡，看似忘不掉美姐，铁蛋先与其大女儿（叶兰 饰）私恋未果，却被迫娶了二女儿（葛夏 饰）作为“补偿”。最后决定跟着戏班子流浪，随他出门的却是美姐家的老三（叶兰 饰）……有道是二人台不是天天有，情歌永远唱不完。©豆瓣', '叶兰', '郝杰', 7.8, 25618, 'tt2930988', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2073776576.jpg', 0.7, 2.5, 24.4, 49.4, 22.9, '-0.023717,-0.260486,-0.191516,0.009039,-0.307602,-0.673672,0.363519,0.301043,-0.368545,-0.011609,0.077026,0.295132,-0.081894,0.233230,0.057773,0.166073,-0.267278,-0.438945,-0.044467,-0.021219,0.264757,-0.178918,0.163725,0.251521,-0.159491,0.015920,0.369236,-0.197568,0.235660,0.477337,0.472443,0.039671,-0.311104,-0.092611,-0.034488,0.208732,-0.158332,0.095813,-0.244196,-0.035151,-0.188923,-0.203366,-0.020789,-0.116987,0.017463,0.230320,0.461280,-0.003950,0.092818,-0.289246,0.169038,0.278021,-0.282977,-0.005432,0.250946,-0.229159,0.632099,0.207952,-0.275656,-0.049493,0.135515,-0.148055,0.242613,0.428858,0.560707,0.101823,-0.569172,0.243010,-0.281435,-0.243673,0.171083,-0.546424,0.134458,0.021226,0.159124,0.550207,-0.145031,-0.005813,-0.402592,0.482614,0.358897,0.335720,0.030496,0.197429,0.377791,-0.332565,0.124733,0.053690,-0.322655,0.299686,0.178959,0.051499,-0.251701,-0.069682,-0.388297,-0.022464,-0.041771,0.054754,0.354707,-0.458660,0.172415,-0.297859,0.008260,-0.416327,-0.324231,0.279336,0.141191,0.078574,0.752048,-0.442481,0.485194,0.201873,-0.084782,-0.450559,0.506930,0.141957,0.179819,-0.093282,0.507370,-0.038266,-0.654463,0.064629,0.276916,0.405726,-0.266087,-0.386734,-0.301994,0.293485', '1307320', '1908036', '26348103', '1437857');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10833923', '等风来', '喜剧', '时尚杂志小编辑程羽蒙（倪妮 饰）准备了几个月的意大利托斯卡纳之行被主编（刘孜 饰）无情改成了尼泊尔旅行团，无奈的她只好跟着由几个大妈组成的“大姐团”、没礼貌的富二代王灿（井柏然 饰）、失恋的职场新人“李热血”（刘雅瑟 饰）一起开启了尼泊尔之行。程羽蒙这次行程被要求完成一个有关于幸福的稿子，但是问题不断的她基本上写不出来，而她的团友们也有着各式各样的问题，尤其是富二代王灿，总干着令人生厌的事情。随着旅行的深入两人愈发势不两立，可在经历了许多遭遇之后两人的关系得以缓和，在旅行结束前的最后一天王灿邀请她进行了人生第一次的滑翔，在等着风起的时候，程羽蒙的内心终于得到了平静。本片改编自鲍鲸鲸的小说《游记，或是指南》，片名来自于小说中滑翔教练的话。©豆瓣', '倪妮', '滕华涛', 5.7, 130493, 'tt3467440', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2163861862.jpg', 7.9, 26.2, 46.1, 15.1, 4.8, '0.363107,-0.034155,-0.601086,0.794322,0.143243,-0.331786,0.605627,0.013348,-0.416372,-0.234229,0.003349,0.515417,-0.424990,0.347389,0.352962,-0.135528,-0.338558,-0.606532,-0.113309,-0.344462,-0.271827,-0.400979,-0.078217,-0.012510,-0.264375,-0.084027,0.485940,-0.001935,-0.102666,0.447912,0.416915,0.115661,0.005690,0.566408,-0.079793,0.108152,0.119850,0.090689,-0.183393,0.263843,0.336496,-0.150746,-0.233006,0.065227,0.208626,0.391829,0.740453,-0.266065,-0.198322,0.103218,0.349752,-0.169782,-0.100992,-0.015577,0.334042,0.379273,0.320534,0.202353,0.066496,0.083692,0.123297,-0.092696,-0.507831,0.055292,0.089198,0.144451,-0.485703,0.583267,-0.110220,-0.146111,-0.049856,-0.462074,0.243557,0.345278,0.514104,0.217794,-0.043991,0.161806,-0.318265,0.465382,0.598017,0.235897,-0.189155,0.433231,-0.211286,-0.466041,-0.055466,-0.009499,-0.441500,0.112680,0.456826,0.014119,-0.215767,0.159755,-0.639452,-0.099258,0.165547,-0.298979,-0.130547,-0.314960,-0.016278,-0.592212,-0.164740,-0.442073,-0.204629,0.169287,0.141593,-0.110533,0.704979,-0.757380,0.190222,0.231171,0.063791,-0.413425,0.445824,0.160040,0.037097,-0.005100,0.060357,-0.015245,-0.167532,0.481417,0.474579,0.556155,-0.097214,-0.369520,-0.270739,0.388601', '1292219', '3811356', '1301022', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10833924', '天台爱情', '喜剧', '在漫画般繁华的加利利市住着一群“天台人”，他们居住在城市建筑的天台上过着清贫快乐的生活。浪子膏（周杰伦 饰）、黑轮（柯有伦 饰）、蛋花（宋健彰 饰）、花椰菜（黄俊郎 饰）就是其中几个爱耍帅善良的天台少年，他们从小被茉莉姐（徐帆 饰）养大，在波爷（曾志伟 饰）的医药馆里打工。由于黑轮在黑社会性质的“市居会”帮助雷哥（王学圻饰）收租得罪了同僚红毛（黄怀晨 饰），至此牵连了几个好友。同时浪子膏巧遇了心仪已久的女明星心艾（李心艾 饰）并与之日久生情，而心艾的老板威少（邱凯伟 饰）因为嫉妒从中挑拨，并与红毛联手对付浪子膏一伙，引发了一场腥风血雨的争斗。关键时刻面对爱人和朋友浪子膏做出了一个重大的抉择。本片是周杰伦自《不能说的秘密》之后自导自演自编的第二部电影。©豆瓣', '周杰伦', '周杰伦', 6.7, 143356, 'tt2901548', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2006855292.jpg', 4, 13.1, 41.5, 26, 15.3, '0.085305,-0.147290,-0.387874,0.507684,-0.026198,0.064066,0.700805,0.492810,-0.230791,-0.075316,0.094649,0.516542,-0.138990,0.184125,0.143494,-0.150712,0.007453,-0.554801,0.012255,-0.105254,-0.132585,-0.119623,-0.131041,-0.160653,-0.240393,-0.183102,0.459068,0.120152,-0.162707,0.397874,0.574862,0.144952,-0.268353,0.049025,-0.093156,-0.135774,0.201286,0.261345,-0.359515,0.200558,-0.173195,-0.300913,0.016704,0.096870,-0.013948,0.177625,0.799218,-0.268287,-0.031120,-0.126926,0.226824,-0.033637,0.115882,-0.202661,0.244363,-0.191935,0.355118,0.048231,-0.146821,0.075628,0.282454,-0.180573,-0.448835,-0.101054,0.280126,0.165904,-0.488690,0.696709,0.069373,-0.234830,-0.086707,-0.019291,0.325459,0.142991,0.333137,0.257020,-0.010534,-0.027031,-0.475717,0.532693,0.439495,0.317552,0.119050,0.344236,-0.108901,-0.307628,-0.078411,-0.138938,-0.397980,-0.025315,0.367816,-0.444420,-0.104702,0.232723,-0.669905,0.214619,-0.011905,0.236029,0.122076,-0.276548,0.048866,-0.652775,-0.091215,-0.374206,-0.166762,0.214372,0.182248,-0.115677,0.756209,-0.747609,0.175025,0.447217,0.212406,-0.469751,0.523699,0.201287,-0.108023,-0.171999,-0.152861,0.184456,0.119034,0.029113,0.210762,0.347221,0.033333,-0.253596,-0.095922,0.217335', '3811356', '1418179', '24839498', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10833970', '变身超人', '喜剧', '红极一时的超人剧男主角铁男（陈柏霖 饰）由于收视率下滑严重，和他的怪兽搭挡（邱彦翔 饰）一起，遭新任电视台董事长苏盈盈（郭雪芙 饰）换角，歌手FACE（敖犬 饰）成为新世代超人，而铁男则瞬间变成下岗屌丝，就连送到自己面前的女神化妆师静芬（陈庭萱 饰），他都丧失了推倒的勇气。为改变现状，他不仅接了一堆类似路人乙的角色，甚至连超人主题AV都来者不拒，终于在转战电视购物时，铁男下岗再就业打开了事业第二春，当然，就推倒女神这件事，这位失业超人还需要更多勇气来实现……©豆瓣', '陈柏霖', '张时霖', 6.6, 19714, 'tt2927080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1892617767.jpg', 3.3, 12.2, 44.6, 30, 9.8, '-0.246008,0.019559,-0.392969,0.216049,-0.002131,-0.287235,0.459859,0.192818,0.141533,-0.032181,0.102517,0.460006,-0.324176,0.296239,0.459402,-0.073832,-0.285418,-0.792230,-0.012882,0.091785,-0.386069,-0.083848,-0.085954,-0.026749,-0.100917,0.063144,0.765557,-0.409277,-0.334035,0.090103,0.702759,-0.008367,0.019048,0.207131,0.093927,0.232627,-0.133497,0.086440,-0.118975,0.152105,0.071534,-0.005367,0.039758,0.109985,0.065682,0.122777,0.293362,-0.145319,-0.020391,-0.081626,0.538638,-0.219949,0.074592,-0.014458,0.219458,-0.104357,0.254381,0.038202,0.040769,0.062110,0.358632,-0.021434,-0.502531,0.151040,0.178412,-0.116819,-0.370265,0.329678,0.056360,0.178139,0.076688,-0.119519,-0.060683,-0.009694,0.171099,0.169293,-0.168061,0.134238,-0.246669,0.744899,0.234274,0.286931,-0.316261,0.332892,0.388417,-0.241123,-0.235194,-0.141446,-0.401100,0.016368,0.132997,0.020202,0.091725,0.202177,-0.608109,-0.136351,-0.116436,0.143432,0.100990,0.183232,0.126304,-0.629768,0.051100,-0.101293,0.004109,0.057820,0.343132,-0.310725,0.698601,-0.401924,-0.051421,0.130026,0.299055,-0.499024,0.392319,-0.198197,0.088396,-0.094644,-0.315522,0.024362,0.114569,0.310668,0.153291,0.132541,-0.266108,-0.377859,-0.075287,0.334793', '1322847', '1908036', '6101834', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10833971', '初恋未满', '剧情', '1997年，高三班花董啾啾（张含韵 饰）外表是懂事乖乖女，内心却叛逆乖张。她的好姐妹韩霞非常喜欢时装设计，平日里心直口快、敢做敢为，却因为魁梧的身材、平凡的外表和爷们儿的性格经常受到周围男生的嘲笑。忧郁校草夏静寒（冉旭 饰）、校霸罗凡（代旭 饰），以及吃货胖子小强（张政 饰）、运动少年大伟（李现 饰）是全校公认的损友拍档。面对即将来临的高考，他们各自憧憬着未来的人生。啾啾的父亲在她十八岁生日那天突然离世，但留给她的生日礼物成了她永久的精神寄托。静寒为人仗义，由于幼年父母离异，他与奶奶相依为命。罗凡是静寒最好的哥们儿，他们互相欣赏对方身上的侠义气质，但靜寒和啾啾的恋爱却造成了兄弟间反目。长相平凡的韩霞一直生活在好姐妹啾啾的阴影中，平时老师和同学对她和啾啾态度的巨大反差，造成了她们友情的巨大危机......©豆瓣', '张含韵', '刘娟', 6.4, 10939, 'tt6449270', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2015805096.jpg', 5.5, 16, 44.2, 23.3, 11, '0.026759,-0.252830,-0.683574,0.612055,-0.183250,-0.192689,0.717652,0.424118,-0.493646,-0.108588,0.061604,0.486036,-0.266271,0.420353,0.222097,0.086847,0.011417,-0.550707,-0.101085,0.280954,0.070013,-0.245085,-0.173066,0.067458,-0.263948,-0.384728,0.477880,-0.298023,-0.000925,0.779992,0.128765,-0.025308,0.190327,0.415884,-0.083248,0.144755,-0.181830,0.176200,-0.209084,-0.318050,-0.170106,-0.250944,0.159175,0.071880,0.112091,0.393792,0.822603,-0.267703,-0.215365,-0.257540,0.491694,0.031233,-0.337203,0.339375,0.254716,-0.208894,0.538337,0.107360,0.382972,-0.255320,-0.049660,-0.260807,-0.170369,0.070913,0.288345,0.143793,-0.194878,0.726914,-0.121899,-0.207307,0.389385,-0.112078,-0.135005,-0.213062,0.031720,0.453203,-0.305200,0.391181,-0.120098,0.305245,0.629090,0.108188,-0.312475,0.483558,-0.710509,-0.327120,-0.110451,-0.280889,-0.640309,0.038153,0.139670,-0.032359,-0.138885,0.350742,-0.402149,0.264628,0.240402,0.180391,-0.045797,-0.483008,-0.177511,-0.457690,-0.212582,-1.038774,-0.752306,-0.118108,-0.026138,-0.131651,0.940776,-0.935175,0.002195,0.205317,0.324083,-0.215347,0.574773,0.177977,0.078059,-0.290523,-0.171576,0.105002,0.062850,-0.250922,-0.064023,0.216706,-0.116553,0.072313,-0.257047,0.238835', '1390020', '26354526', '24839498', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10864706', '我只是还没有全力以赴', '喜剧', '年过四十的男人大黑静雄（堤真一 饰）突发奇想，辞去原本还算安稳的工作，决心寻找真实的自我。早年离异的静雄一直和父亲志郎（石桥莲司 饰）以及17岁的女儿铃子（桥本爱 饰）生活在一起，辞职后他散漫度日，从没画过画的他突然决定以漫画家身份出道。只不过无趣的题材接连遭到退稿，在打工的快餐店又经常被比自己年轻的前辈训斥。日常里，同样离异的上班族好友宫田修（生濑胜久 饰）以及同在快餐店打工的问题青年市野泽秀一（山田孝之 饰）是陪他共同买醉的朋友。看不到未来的静雄，今朝有酒今朝醉，确实可以期盼出道的那一天……本片根据漫画家青野春秋的同名原作改编。©豆瓣', '堤真一', '福田雄一', 7.4, 11151, 'tt2401037', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1891641781.jpg', 0.6, 3.5, 36.6, 44.4, 14.9, '0.073047,-0.334058,-0.475924,0.545860,-0.192009,-0.524401,0.497820,0.236842,-0.404110,-0.453505,0.242686,0.730621,-0.136535,0.659498,0.432811,-0.167064,-0.121977,-0.543829,-0.045633,-0.202752,-0.046065,-0.498627,-0.309934,-0.130063,-0.347402,-0.217486,0.579088,-0.183919,0.149036,0.386372,0.357216,0.175805,-0.101757,0.337047,-0.286975,-0.056201,-0.142399,0.297666,-0.295557,-0.053852,0.024283,-0.359032,-0.053759,-0.072277,0.130820,0.479829,0.594847,-0.261540,-0.145003,0.010646,0.414110,0.153686,-0.258415,0.049625,0.332564,-0.009177,0.355897,0.270237,-0.239036,0.061686,-0.104429,-0.242578,-0.488019,-0.130832,0.227459,0.136008,-0.410611,0.415972,-0.096228,-0.188151,0.228488,-0.243613,-0.059771,0.333334,0.218256,0.516146,-0.134523,0.254711,-0.221437,0.640794,0.422594,0.204310,-0.122174,0.511741,-0.296084,-0.147919,-0.048159,-0.317574,-0.486561,0.002485,-0.089045,-0.137322,-0.256926,-0.014067,-0.598788,0.027622,0.161961,-0.004150,0.211065,-0.128889,-0.238538,-0.479116,0.022005,-0.511047,-0.199001,0.073304,0.192853,-0.228246,0.695548,-0.992825,0.049449,0.356288,0.290697,-0.488402,0.670269,0.181514,-0.042378,-0.149442,-0.025973,0.205632,-0.041402,0.315343,0.007084,0.230025,0.060425,-0.178347,-0.445981,0.432450', '1292219', '3445516', '1306544', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10876425', '印式英语', '剧情', '莎希（希里黛玉 Sridevi 饰）是一名喜欢做拉杜球的印度家庭主妇，因为终日把照顾家人生活作为自己生活的全部中心，和时代有些脱节。不懂英语的莎希在生活中受到了丈夫和女儿的嘲笑，和家人共同话题的减少让她感觉到了危机的存在。意外的机会，远在美国的亲人邀请莎希去帮他们料理结 婚事宜。为了促进和家人的沟通，赢得他们的尊重和关注，莎希决定在纽约的四个星期报名参加英语培训班来克服自己的语言障碍。在这个培训班里，莎希也告别了以往沉寂如水的生活，结识了各式各样的朋友，为了学好英语这一共同的目的，大家相互鼓励共同进步。功夫不负有心人，日夜苦学英语的莎希由零基础到在婚礼宴会上大放光芒，一席对新人用英语讲述的祝福不仅为她赢得了众人的刮目相看，更是让她重新赢得了家人的爱和尊重…该片曾在第37届多伦多电影节上作为开幕影片上映。©豆瓣', '诗丽黛玮', '高里·辛蒂', 8.2, 20147, 'tt2181931', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1829342305.jpg', 0.2, 1.3, 17.7, 49.5, 31.3, '0.110328,-0.038290,-0.606149,0.686002,-0.082626,-0.128539,0.315502,-0.003760,-0.339240,-0.234716,0.072549,0.915876,-0.136952,0.200911,0.283189,-0.312157,-0.156954,-0.863616,-0.050676,-0.122073,-0.334613,-0.684011,0.044882,-0.169865,-0.362772,-0.367783,0.451422,-0.043070,-0.208385,0.715532,0.189245,0.046777,0.240055,0.362343,-0.211905,-0.066057,-0.084356,0.201206,-0.591491,0.169481,0.149090,-0.037483,-0.265029,0.215677,0.319033,0.316026,0.734626,0.098406,-0.110445,0.058195,0.272601,-0.459693,-0.016557,0.199300,0.122976,0.067221,0.374207,0.344290,-0.172769,0.163607,-0.169584,-0.221810,-0.851531,-0.029807,0.352343,-0.005526,-0.584248,0.783760,0.017590,-0.191195,0.024521,-0.204387,0.320472,0.641611,0.101804,0.612618,-0.116432,0.165592,-0.243492,0.311141,0.951355,-0.062006,-0.140569,0.378824,-0.351843,-0.229992,-0.003797,-0.254907,-0.428196,-0.041190,0.071935,0.029867,-0.119002,0.187089,-0.775650,-0.049244,0.061484,-0.393807,0.408470,-0.782049,0.259867,-0.831523,-0.044411,-0.489802,-0.310589,-0.049544,0.175181,-0.581644,1.056296,-1.137194,0.193553,0.488878,0.547614,-0.665442,0.918142,0.370314,0.263724,-0.375420,-0.117359,0.091280,-0.021664,0.181659,-0.115811,0.257267,0.024129,-0.035649,-0.641625,0.361914', '35048413', '4127270', '1292219', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('10877413', '老千2：神之手', '剧情', '因在老家伤人而跑路的咸大吉（崔胜铉 饰），来到江南道投奔相熟的查理哥。经查理引荐，大吉在开设赌场的高章社长那里谋得一份差使。大吉凭借天赋般的老千技巧、帅气的容貌和伶俐的口才，很快成为高社长最为器重的手下。在此期间，他结识了美艳妇人于智妍（李荷妮 饰），却因帮助智妍摆脱高社长设下的陷阱而把自己置身凶险之地。不久他重逢跟随牌友张东植而来的初恋女孩许美娜（申世京 饰），结果在那场赌局中遭遇了人生最惨痛的败局。从天上跌落谷底的大吉，经美娜帮助他离开了暗潮汹涌的江南道，并在途中遇见隐姓埋名的老千高手（柳海真 饰）。决心复仇的大吉向高手拜师，他用生命孤注一掷……©豆瓣', '崔胜铉', '姜炯哲', 7.2, 48052, 'tt3402110', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195672548.jpg', 0.8, 5.4, 40.5, 37.8, 15.5, '-0.102423,0.022048,-0.358264,0.557093,-0.292800,-0.130874,0.408449,0.321986,-0.391379,0.000491,0.458274,0.759703,-0.053210,0.001951,0.344907,-0.251509,-0.021337,-0.438645,0.141731,-0.138181,-0.067443,-0.224416,-0.240798,-0.022648,-0.132709,-0.272193,0.446876,0.373795,-0.149321,0.557582,0.116635,0.118456,-0.189609,0.218408,-0.114581,-0.099160,-0.044126,0.115924,-0.411626,0.297703,-0.134518,-0.399384,-0.262190,-0.020529,0.081012,0.312632,0.526938,-0.139296,-0.192709,0.009336,0.414661,-0.298823,0.006784,0.119975,0.340858,-0.003495,0.064147,0.238677,-0.116259,-0.020831,0.068359,-0.260589,-0.655039,0.050220,0.258575,-0.140844,-0.472928,0.269765,-0.040402,-0.119584,0.028262,-0.343687,0.112108,0.291321,0.154068,0.128942,-0.050793,0.225251,-0.360169,0.243076,0.690948,-0.113603,0.054843,0.201902,0.181782,-0.446704,0.113367,-0.152632,-0.328519,0.016035,0.459685,-0.085012,0.038459,0.002197,-0.370117,0.075684,-0.278140,0.163407,-0.115124,-0.192267,-0.317523,-0.393449,-0.147157,-0.214002,-0.160750,-0.059901,0.101639,-0.224067,0.740606,-0.637320,0.056094,0.531125,0.310427,-0.301733,0.707084,-0.139467,0.118109,-0.243022,-0.128795,0.316012,-0.024729,0.270541,0.017975,0.228110,-0.340727,-0.233573,-0.242956,0.278282', '27602116', '30162520', '3811356', '26711487');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11026735', '超能陆战队', '喜剧', '未来世界的超级都市旧京山（San Fransokyo），热爱发明创造的天才少年小宏，在哥哥泰迪的鼓励下参加了罗伯特·卡拉汉教授主持的理工学院机器人专业的入学大赛。他凭借神奇的微型磁力机器人赢得观众、参赛者以及考官的一致好评，谁知突如其来的灾难却将小宏的梦想和人生毁于一旦。大火烧毁了展示会场，而哥哥为了救出受困的卡拉汉教授命丧火场。身心饱受创伤的小宏闭门不出，哥哥生前留下的治疗型机器人大白则成为安慰他的唯一伙伴。原以为微型机器人也毁于火灾，谁知小宏和大白竟意外发现有人在某座废弃工厂内大批量地生产他的发明。稍后哥哥的朋友们弗雷德等人也加入进来，他们穿上小宏发明的超级战士战斗装备，和怀有险恶阴谋的神秘对手展开较量……©豆瓣', '斯科特·安第斯', '唐·霍尔', 8.7, 944031, 'tt2245084', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614500883.jpg', 0.1, 0.6, 10.1, 41, 48.2, '0.038972,-0.197833,-0.427907,0.324996,-0.078729,-0.098866,0.570991,-0.097184,-0.325620,-0.209205,0.554393,0.564052,-0.113934,0.153754,0.227169,-0.359663,-0.371380,-0.412980,-0.220401,0.054254,-0.347497,-0.344803,-0.291986,-0.362565,0.203186,-0.622755,0.792965,-0.038965,-0.318726,0.422394,0.045859,0.254399,-0.137777,0.337058,-0.057640,-0.073178,-0.067346,0.116021,-0.456691,0.196661,-0.315894,0.025566,0.121418,0.004528,-0.029316,0.047646,0.716489,-0.487476,0.021219,-0.242042,0.416637,-0.308673,0.144253,-0.031486,0.171018,0.270708,0.099665,0.028123,0.094808,-0.059123,0.084384,-0.077560,-0.611954,-0.022811,0.334648,-0.092933,-0.405635,0.597599,0.089993,0.128279,0.185730,-0.147474,0.129304,0.225838,0.330192,0.451672,-0.205055,0.325019,-0.365355,0.198176,0.449458,-0.508044,-0.128049,0.044883,-0.115593,-0.488395,0.170796,-0.371655,-0.407158,0.120853,0.130504,-0.036394,0.036271,0.222673,-0.578548,0.043369,-0.097950,-0.287809,0.043798,-0.339403,-0.048524,-0.781009,0.169662,0.086181,-0.220537,-0.067233,0.085453,-0.412086,0.933661,-0.759229,0.167762,0.331662,0.322400,-0.370696,0.646163,-0.210474,0.175881,-0.357018,-0.486906,0.216563,0.095549,0.460795,0.019022,0.346134,0.074312,-0.210338,-0.335974,0.321710', '3811356', '10174444', '1322847', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11443314', '里约大冒险2', '喜剧', '在亚马逊丛林腹地，探险科学家图里奥（罗德里格·桑托罗 Rodrigo Santoro 配音）和琳达（莱斯利·曼恩 Leslie Mann 配音）发现几近灭绝的野生蓝色斯皮克斯金刚鹦鹉。夫妻俩通过电视向全世界宣布这一惊人消息，看到这一幕的珠儿（Anne Hathaway 配音）劝说丈夫布鲁（Jesse Eisenberg 配音），打算带着三个调皮可爱并且已经习惯了人类文明世界生活的鹦鹉小宝宝，回到它们生长千百年的故乡寻找同类。鹦鹉一家说走就走，和它们的好朋友踏上充满惊险和乐趣的空中旅程。与此同时，某非法砍伐团体看到新闻，为防止图里奥夫妻阻挠他们的罪行，他们也悄悄采取行动。另一方面，与布鲁积怨已久的葵花凤头鹦鹉奈杰发现布鲁的踪迹，也愤然采取行动。布鲁一家最不平凡的假期，正朝着意想不到的方向发展……©豆瓣', '安妮·海瑟薇', '卡洛斯·沙尔丹哈', 7.7, 126422, 'tt2357291', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2177142678.jpg', 0.3, 2.1, 29.3, 47.7, 20.6, '0.207098,-0.293857,-0.596118,0.611378,0.270257,-0.211254,0.583570,0.079890,-0.273168,-0.174464,-0.011579,0.524148,-0.207835,0.038119,0.264429,0.028558,-0.498997,-0.463191,0.015320,-0.128920,-0.079503,-0.083019,-0.222224,-0.349268,0.048898,-0.235547,0.603608,0.078645,-0.094985,0.659824,-0.012096,0.102242,-0.420820,0.146358,0.013167,0.148177,0.240781,-0.010029,-0.324628,0.164678,-0.071951,0.135579,-0.140372,0.054575,-0.117195,0.072824,0.690532,-0.482017,-0.053463,-0.312533,0.183067,-0.352941,0.274901,0.088328,0.404462,-0.329878,0.228341,-0.126845,-0.090918,-0.054222,-0.081355,-0.271389,-0.492967,0.118426,-0.135093,0.399600,-0.247603,0.137475,-0.015872,0.038259,0.215480,-0.405925,-0.015227,0.377658,0.295120,0.372693,-0.089319,0.262997,-0.430400,-0.181030,0.275981,-0.060661,-0.058341,0.261396,-0.167027,-0.296310,0.053367,0.049291,-0.307071,-0.322110,0.518226,0.068640,-0.196417,0.303247,-0.817217,0.097254,-0.257453,-0.367535,0.111850,-0.308749,-0.211193,-0.929559,0.095010,-0.257095,-0.219919,0.101939,0.012854,-0.182992,0.555596,-0.585380,0.294421,0.518564,0.359846,-0.226198,0.632294,-0.371535,0.115879,-0.548069,-0.071104,0.374832,0.154610,0.166875,0.166521,0.159236,0.215552,-0.161499,-0.538903,0.493134', '20274039', '2159244', '1294917', '4706257');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11443316', '龙之谷：破晓奇兵', '动画', '不务正业的流浪少年兰伯特意外听到了邪恶的大黑龙手下魔族准备攻占阿尔特里亚大陆的情况，为了保护家乡他与魔物周旋被困，却被游侠巴尔纳救下，加入到了游侠杰兰特、阿尔杰塔（景甜 配音）的队伍中。精灵一族中的法师首领卡拉秋（夏梓桐 配音）也带着公主内尔文与弓箭手随从莉亚（徐娇 配音）前来邀请人类国王参战，面对魔物的入侵，他们和游侠队伍以及人类骑士贝斯柯德（胡歌 配音）组成了对付大黑龙的联盟。众人历经困难来到了大黑龙的巢穴，兰伯特与莉亚日久生情，但是他们却不知道杰兰特和阿尔杰塔，以及贝斯柯德各自带着不为人知的秘密……本片是人气网游《龙之谷》改编的动画大电影，由盛大游戏公司推出，计划是拍摄三部曲，故事的主线围绕《龙之谷》游戏前传。©豆瓣', '胡歌', '宋岳峰', 7.7, 29895, 'tt2911342', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2575693162.jpg', 1.6, 4, 27, 42.3, 25.1, '0.133688,-0.073070,-0.474632,0.691406,0.379660,0.116660,0.581503,-0.094700,-0.311091,-0.320171,0.283416,0.686602,-0.123623,0.039749,0.318152,-0.140003,-0.585502,-0.433437,-0.162491,-0.100455,-0.090967,-0.058132,-0.182383,-0.570558,-0.090333,-0.522321,0.704866,0.079784,-0.285303,0.291389,0.279544,0.452321,-0.734246,0.200963,0.169470,0.135999,0.331219,-0.356341,-0.226017,0.245531,-0.232759,0.215768,-0.371928,0.177979,0.324625,0.320204,0.625847,-0.588839,0.436277,-0.212840,-0.030052,-0.502121,-0.007864,-0.345484,0.448034,-0.155078,0.375831,0.203855,0.470271,0.155729,-0.426663,-0.529648,-0.845816,0.245512,0.207392,0.377110,-0.463452,0.399908,-0.238528,0.106204,0.216334,-0.101278,0.101270,0.202613,0.456254,0.124553,0.198591,0.056758,-0.513559,0.212328,0.426531,-0.154308,-0.227243,-0.047728,-0.091828,-0.755834,-0.381948,-0.231185,-0.391430,-0.171469,0.361251,-0.080109,0.057060,0.491674,-0.812557,-0.128340,-0.216531,-0.225298,-0.002400,-0.430670,-0.112230,-0.875486,0.051192,-0.203766,0.091912,0.077092,0.139307,-0.056831,0.775265,-0.908025,-0.019402,0.433017,0.572781,-0.368819,0.570837,-0.466770,0.140192,-0.221736,-0.033560,0.147516,0.023397,0.063818,0.479837,0.201125,0.204086,-0.357940,-0.250817,0.417418', '1420088', '2369613', '1294917', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11443807', '蝙蝠侠：黑暗骑士归来(上)', '动作', '阴云密布的高谭市，自蝙蝠侠消失的十年里，变种人团伙为非作歹，变本加厉，将这座繁华城市变成充满恐怖和凶杀的罪恶王国。嫉恶如仇的吉姆·戈登探长（大卫·塞尔比 David Selby 配音）行将退休，却不免成为变种人下一个袭击的目标。随着双面人哈维·登特（韦德·威廉姆斯 Wade Williams 配音）走出精神病院，高谭市被带入更加阴冷的黑暗之中。与此同时，富翁布鲁斯·韦恩（彼得·威勒 Peter Weller 配音）置身事外，享受着养尊处优的上流生活。而旧日记忆的复苏，一步步引导着他再次拿起搁置已久的战斗服。夜幕降临，老态龙钟的蝙蝠侠穿梭城市的阴暗角落，以无情的手段惩治恶徒。正义战士归来，正邪之争日趋白热化……©豆瓣', '彼得·威勒', '杰伊·欧力瓦', 8.4, 26221, 'tt2313197', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2162824852.jpg', 0.2, 1, 15.6, 43.4, 39.8, '0.305314,0.123187,-0.311325,0.388097,-0.184605,-0.189374,0.873730,0.227064,-0.395358,-0.135072,0.353235,0.684936,-0.144573,0.021741,0.283714,-0.085750,-0.451202,-0.583593,-0.442146,-0.055798,0.055480,-0.511782,-0.495094,-0.187144,0.077570,-0.309529,0.642674,0.297702,-0.233612,0.325059,0.239040,0.391497,-0.276975,0.269013,-0.084105,-0.233917,0.046495,-0.301571,-0.278854,0.221250,-0.170121,-0.068781,-0.137273,-0.026133,-0.237340,0.167935,0.585545,-0.288370,0.132092,-0.376549,0.624180,-0.272207,-0.398184,0.059323,0.283240,0.051670,-0.192800,0.151523,-0.127095,-0.073343,-0.182628,-0.320193,-0.579367,0.154987,-0.022347,0.150867,-0.334028,0.339239,0.056507,0.021115,0.225805,-0.230890,0.090067,-0.213395,0.259284,0.477896,0.039503,0.163367,-0.492392,0.055996,0.412432,0.108717,-0.652083,-0.264097,-0.073152,-0.244588,0.108026,-0.448086,-0.491408,-0.645941,0.344336,-0.084045,0.054504,0.739737,-0.600416,0.299980,-0.351836,-0.232861,-0.107504,-0.160545,-0.507978,-0.703949,-0.330923,-0.115319,0.161271,-0.029761,-0.179350,-0.259655,0.514966,-0.627108,0.491692,0.507213,0.236175,-0.010787,0.364902,-0.404251,0.271705,-0.213736,-0.357072,0.674803,0.088561,0.512792,0.147086,0.121793,-0.531499,-0.076294,-0.313199,0.708961', '1316693', '25884436', '1292528', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11443810', '蝙蝠侠：黑暗骑士归来(下)', '动作', '曾经罪恶横行的高谭市，自布鲁斯·韦恩（彼得·威勒 Peter Weller 配音）决定以蝙蝠侠的身份归来后，仿佛终于发生了新的变化。变种人头目双面人被除掉，然而原变种人团伙摇身变成蝙蝠狂热者，以暴力的方式执行着对善恶之行的裁断。因此，蝙蝠侠的法外行为引起广泛争论，甚至惊动白宫，而高谭的新任探长对其存在颇有微词。正值美苏交恶的危机时刻，超人（马克·瓦雷 Mark Valley 配音）卷入战火，蝙蝠侠和这位昔日的战友因理念不同分道扬镳。在此期间，小丑（迈克尔·爱默生 Michael Emerson 配音）高调复出，受邀参加某电视节目访问，实则暗藏新的阴谋。为了阻止小丑的破坏，蝙蝠侠和新一代的罗宾突破重重阻隔，杀向对手……©豆瓣', '彼得·威勒', '杰伊·欧力瓦', 8.9, 28446, 'tt2166834', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2432294601.jpg', 0.3, 0.6, 9.1, 34, 55.9, '0.199112,0.036797,-0.468578,0.464356,0.102516,0.118885,0.503734,0.183987,-0.354585,-0.463632,0.342168,0.596281,-0.353604,-0.237494,0.508013,-0.470868,-0.253017,-0.586756,-0.173330,0.032511,-0.157670,-0.474125,-0.379432,-0.343114,0.106267,-0.284539,0.697768,0.220141,-0.628547,0.316750,0.460378,0.527567,-0.259986,0.412587,0.130891,-0.163112,0.023557,0.055511,-0.434143,0.131080,-0.054615,-0.033439,-0.148162,0.068915,-0.204505,0.494426,0.371445,-0.599726,-0.229300,-0.314382,0.491716,-0.401298,0.120582,0.205557,0.364899,0.091666,0.019564,0.303910,0.247169,0.037493,-0.055215,-0.283861,-0.748928,0.114420,0.028431,0.137838,-0.132068,0.264369,-0.030864,0.177703,0.056307,-0.005743,-0.027121,0.140158,0.550702,0.189945,0.124889,0.313554,-0.354729,-0.087390,0.708621,0.161699,-0.665347,-0.197828,-0.009845,-0.221779,-0.127166,-0.510941,-0.202659,-0.110055,0.337852,0.005105,-0.002830,0.527707,-0.516315,-0.244984,-0.200816,0.031065,0.076993,-0.225621,-0.011925,-0.910340,-0.165842,-0.144427,0.062944,-0.244838,0.124222,-0.439333,0.653784,-0.840464,0.229088,0.449090,0.246126,-0.580737,0.512938,0.049195,0.074697,-0.467377,-0.359473,0.303969,0.264564,0.189591,0.025464,-0.155313,-0.068915,-0.370769,-0.050522,0.145471', '2369613', '25723905', '27073234', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11499033', '功夫小蝇', '喜剧', '该片在印度国内以3D形式上映。烟火工纳尼（纳尼 Nani 饰）暗恋对楼的女孩缤杜（萨曼莎·鲁斯·帕布 Samantha Ruth Prabhu 饰）两年，虽然从未获得缤杜肯定，依然对她如痴如醉。赞助缤杜工作的建筑公司老板苏迪普（苏迪普 Sudeep 饰）也看上了她，这个看似腰缠万贯、有权有势的男人实则是个心狠手辣的黑帮老大。他用尽手段欲引诱缤杜，但他发现缤杜爱的是纳尼。正当缤杜与纳尼度过一个甜蜜的夜晚，缤杜决定鼓起勇气想向他表明心意时，纳尼却被嫉妒的苏迪普所谋杀。然而死去的纳尼死而复生，灵魂变成一只苍蝇而重生。它努力尝试破坏苏迪普接近缤杜的一切计划，并终于让缤杜相信它就是纳尼。于是这对情侣开始联手实施一系列不同寻常的报复行动......©豆瓣', '纳尼', 'S·S·拉贾穆里', 7.5, 40348, 'tt2258337', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1815642806.jpg', 1.1, 4.5, 31.9, 44.3, 18.2, '0.211638,-0.037874,-0.620621,0.564707,-0.127498,-0.252866,0.626589,0.017494,-0.429242,-0.128155,0.150077,0.542313,-0.262664,0.025740,0.079055,0.150374,-0.107872,-0.627733,0.100163,0.072107,0.026745,-0.399781,-0.367811,-0.124709,0.014277,-0.145167,0.741913,0.253772,-0.136465,0.334214,0.410716,0.141992,0.276167,0.529372,0.075598,-0.198401,-0.049429,-0.021764,-0.272763,0.170375,0.097829,-0.405816,-0.213695,0.401347,-0.211365,0.398741,0.487905,-0.250285,-0.230990,-0.036073,0.407065,-0.526956,0.023696,0.350962,0.107392,0.003952,0.118648,-0.031879,-0.202990,-0.093580,-0.039485,-0.027573,-0.818895,0.058037,0.126634,-0.058462,-0.473055,0.179571,-0.118930,0.203586,-0.035459,-0.429647,-0.037019,0.257623,0.450755,0.413575,-0.358616,-0.004205,-0.650247,-0.130619,0.553863,0.185614,-0.251930,0.403959,-0.009042,-0.428882,-0.112891,-0.197871,-0.273637,0.002770,0.144209,0.166226,-0.261387,0.175815,-0.614706,0.010550,-0.361647,-0.119314,-0.071118,-0.683418,-0.015339,-0.562886,-0.327826,-0.239859,-0.309234,-0.007652,0.227915,-0.435885,0.557213,-0.835439,0.105018,0.641597,0.279156,-0.693031,0.537981,0.085595,-0.268530,-0.350829,-0.143634,0.395709,0.105360,-0.057019,-0.028969,0.306916,0.240838,-0.181685,-0.364549,0.592623', '1793491', '4301278', '30163500', '26834930');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11499092', '空之境界 未来福音', '动画', '1998年夏季，拥有预测型未来视的女孩濑尾静音（井口裕香 配音）邂逅伽蓝之堂的黑桐干也（铃村健一 配音）。从对方口中，她了解到未来视的真相，心中的疑惑和焦虑也烟消云散，但同时也看到了干也悲剧性的未来。另一方面，拥有测定型未来视的职业炸弹狂魔仓密目琉夏，利用自己构建的未来制造一系列恐怖袭击事件，直到他遭遇冷静干练的两仪式（坂本真绫 配音），命运的齿轮开始转动。转眼来到2010年，失去了未来视能力的瓶仓光瑠（石田彰 配音）转行做了绘本画家，命运安排他和两仪式及其女儿未那（金元寿子 配音）相逢，此后他和崇拜自己的未那拜访了传奇占卜师观布子之母……本片根据奈须蘑菇以及武内崇创作的同名原作改编。©豆瓣', '坂本真绫', '须藤友德', 9.1, 10298, 'tt2983564', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2037135869.jpg', 0.4, 0.7, 6.5, 26.9, 65.4, '0.023027,0.045111,-0.499534,0.430708,0.089898,-0.066912,0.395018,0.112132,-0.013858,-0.390518,0.189691,0.677350,-0.281437,0.073512,0.249843,-0.082895,-0.286575,-0.668912,-0.075934,-0.175038,-0.132616,-0.428904,-0.167722,-0.146666,-0.018204,-0.223244,0.897649,-0.124133,-0.190367,0.255201,0.108415,0.308334,-0.016567,0.090890,0.038547,0.159769,0.124116,0.296207,-0.188092,0.083160,-0.064962,-0.244020,-0.123126,0.215876,-0.090896,0.462062,0.638277,-0.377777,-0.220420,-0.331341,0.441286,-0.225706,-0.123133,0.061635,0.189756,0.262937,-0.132348,0.346837,-0.141253,-0.071743,-0.165956,-0.056488,-0.793786,-0.114542,0.003118,-0.033132,-0.346367,0.175274,-0.073016,-0.175654,0.335151,-0.216176,0.257573,0.310851,0.610204,0.513637,-0.262353,0.196900,-0.179927,0.502618,0.549300,0.019403,-0.554538,0.518445,-0.101830,-0.402266,-0.163339,-0.268481,-0.361281,0.058207,0.196973,0.404879,0.237578,0.363615,-0.340922,-0.128199,-0.029764,-0.170226,0.321637,-0.274218,-0.231791,-0.620282,-0.326626,-0.612451,-0.311313,-0.287848,0.296801,-0.606814,0.904600,-0.730296,-0.040289,0.366577,0.033237,-0.568007,0.659551,0.103420,0.095649,-0.450675,0.091628,0.219965,-0.227214,0.187063,0.108496,0.305790,0.151814,0.006231,-0.425143,0.300752', '27602116', '25880986', '26759820', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11500954', '编舟记', '剧情', '玄武书房拟定出版一部面向当代人的中型国语辞典《大渡海》，阅历颇丰且行事一丝不苟的国语学者松本朋佑（加藤刚 饰）作为监修主持工作，谁知他最为器重的编辑荒木公平（小林薰 饰）却到了退休的年龄，选择回家照顾病中的妻子。此时编辑部中仅有做事浮躁的西冈正志（小田切让 饰）和临时工佐佐木熏（伊佐山博子 饰）。荒木和西冈多方物色，终于相中了营业部内不善于和人交往却对词语有着敏锐认知度以及做事极为认真投入的青年马缔光也（松田龙平 饰）。浩瀚的词语海洋，马缔与同事们用长达十五年的时间编制一艘驶向彼岸的小船。他们甘于寂寞，却也收获着弥足珍贵的幸福……本片根据三浦紫苑的同名原作改编。©豆瓣', '松田龙平', '石井裕也', 8.6, 70311, 'tt2315226', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2045744896.jpg', 0.1, 0.6, 11.2, 46.2, 41.9, '-0.082887,-0.123628,-0.382811,0.618629,-0.171795,-0.324887,0.507152,0.217068,-0.564360,-0.380168,0.149793,0.429403,0.059886,0.033317,0.419615,0.043562,-0.356948,-0.510299,-0.220981,-0.114452,0.054712,-0.580326,-0.201896,-0.062650,-0.236968,-0.106358,0.664823,-0.000010,-0.198990,0.438114,0.004364,0.301905,-0.082195,0.286060,0.035759,-0.047266,0.117824,0.125322,-0.044018,-0.086669,-0.209923,-0.077852,-0.279975,-0.070179,0.155768,0.510736,0.482068,-0.086248,-0.362120,-0.008506,0.275206,-0.001702,-0.170232,-0.027270,0.300596,0.174601,0.244672,0.243107,-0.302674,0.125866,-0.287207,-0.163448,-0.645643,-0.016122,0.129346,0.184209,-0.271416,0.348424,-0.137207,-0.380327,0.068749,-0.387666,-0.219394,0.083875,0.242918,0.304888,-0.056112,0.375467,-0.023600,0.297141,0.274014,0.133579,-0.213206,0.243190,-0.346972,-0.459047,-0.097606,-0.383640,-0.364576,-0.242207,0.029231,0.064153,0.223522,-0.158425,-0.527805,0.082086,0.077110,-0.258785,0.128020,-0.251019,0.062032,-0.731125,0.045330,-0.638913,-0.366635,-0.038369,0.396204,-0.221444,1.062306,-0.580441,-0.073651,0.200209,0.115372,-0.288140,0.653046,0.104252,-0.094156,-0.349765,0.010764,0.140860,-0.072678,0.302472,0.066536,0.300068,-0.015892,-0.317496,-0.472573,0.324192', '27602116', '3811356', '25863940', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11501396', '边境风云', '剧情', '中缅边境云南小镇，叛逆女学生（高叶 饰）无意中因为家中的狗狗异常暴动，而关注起了新搬来的陌生男子（杨坤 饰），陌生男子其实是一名职业杀手，女学生险些陷入危险，好在身为缉毒警察的哥哥（张默 饰）及时出现制止了杀手。缉毒警逮捕了杀手，无意中查到了一条重大的毒品犯罪线索，继而引出了大毒枭（孙红雷 饰），还引出了十几年前的一宗疑案——牙医（倪大红 饰）无端卷入了毒贩争斗，混乱中幼女被年轻毒贩抓走。如今，因为内部斗争失败的毒贩带着成年的失踪幼女（王珞丹 饰）回到云南小镇进行人生中最后一次毒品交易。警察、毒贩、杀手、牙医父女被命运交织在一起，展开了一场殊死搏斗。©豆瓣', '孙红雷', '程耳', 7.8, 106493, 'tt2385138', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1645229293.jpg', 0.6, 2.4, 23.8, 51.7, 21.5, '0.344093,-0.049748,-0.472959,0.265561,0.008819,-0.068851,0.853351,-0.059248,-0.858269,-0.117471,0.449182,0.398704,-0.148281,0.070065,0.430362,-0.031143,-0.259238,-0.621665,-0.217469,-0.173707,-0.530276,-0.211772,-0.314807,-0.141128,-0.048619,-0.189943,0.455436,0.328314,-0.272245,0.506917,0.331622,0.275046,-0.587166,0.381110,-0.041640,0.050399,0.453902,-0.119114,-0.184328,0.184163,-0.112806,-0.502932,0.076649,-0.059478,-0.066033,0.547412,0.829037,-0.318331,-0.006796,-0.404392,0.361398,-0.180819,-0.336958,-0.009082,0.663856,0.226844,0.191957,-0.042145,-0.136600,-0.255652,0.020844,-0.108271,-0.231224,0.189892,0.180991,0.273749,-0.336815,0.389066,0.020666,0.240282,0.092802,0.067475,0.294163,0.223379,0.455507,-0.017258,0.129511,0.021708,-0.319674,0.399776,0.633447,-0.155639,-0.095232,-0.113384,-0.121807,-0.566542,0.066320,-0.240603,-0.199429,0.103346,0.704147,-0.314832,-0.334613,0.402418,-0.529768,-0.167439,-0.251061,0.241437,-0.109866,-0.006003,-0.376971,-0.400633,-0.144273,-0.039924,-0.183426,0.278109,-0.015954,0.104552,0.346485,-0.755609,0.153472,0.670919,0.251705,-0.261177,0.284868,-0.161681,0.350981,-0.297329,-0.228285,-0.002971,0.310283,0.526259,0.351268,0.193477,-0.508893,-0.309851,-0.084614,-0.192670', '30219670', '3263169', '1773217', '3148877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11502889', '光晕4：航向黎明号', '动作', '在未来的约500年后，人类社会高度发展，并已实现向外太空的殖民。而在这一过程中，新的危机威胁着人类的存在。此时此刻，托马斯·拉斯基（汤姆·格兰 Tom Green 饰）还只是一名殖民星球军事学院的学生，他与迪娜（Kat de Lieva 饰）、Sully（Masam Holden 饰）每日进行艰苦严苛的训练，在此期间他一面饱受神秘疱疹的困扰，一面又对战争的本质产生之一。日常与身为地狱伞兵的哥哥通话给他仅有的安慰。直到某天，哥哥战死沙场，托马斯的去留也到了决断时刻。这一夜，未知的外星生物入侵学院，造成巨大的伤亡。危难时刻，战场之神士官长降临……本片根据同名电子游戏改编。©豆瓣', '汤姆·格林', '斯特瓦特·亨德尔', 6.8, 17835, 'tt2262308', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1782488252.jpg', 3.1, 11.1, 41.8, 29.3, 14.7, '-0.137610,0.147964,-0.795498,0.563952,0.128120,-0.026545,0.689738,0.024693,-0.384489,-0.211345,0.442383,0.633191,-0.039518,0.142208,0.598144,-0.122164,-0.322289,-0.512761,-0.261638,-0.110509,-0.553579,-0.434475,-0.475068,-0.191597,-0.124387,-0.662017,0.680300,0.197029,-0.367164,0.241415,-0.002897,0.360251,-0.009243,0.621842,-0.106189,-0.168666,-0.003212,0.209344,-0.371077,0.133294,0.026872,-0.009622,-0.266203,0.210926,-0.193926,0.348877,0.676259,-0.610390,-0.100738,-0.280137,0.436507,-0.403902,-0.046026,-0.083518,0.573392,-0.087620,-0.184305,0.260655,0.120764,0.116702,-0.158335,-0.194003,-0.872112,-0.358519,-0.136996,0.107520,-0.380886,0.511526,-0.054777,-0.066266,0.068705,-0.221320,0.019660,0.629098,0.342852,0.469026,-0.374475,0.016379,-0.203601,0.245132,0.511648,-0.014285,-0.616080,0.129449,-0.345776,-0.669918,-0.167372,-0.407878,-0.486588,-0.140257,0.136410,0.081260,-0.183183,0.511322,-0.784294,0.352628,-0.154030,-0.533525,0.208782,-0.392239,-0.095652,-0.649932,-0.162046,-0.458885,-0.458530,0.241837,0.271540,-0.109948,0.985179,-0.827726,0.351989,0.732884,0.372265,-0.317831,0.668973,0.249806,0.213575,-0.318109,-0.106596,0.483999,-0.154004,0.555869,-0.274676,0.189039,0.216703,0.007564,-0.286203,0.449696', '24284209', '3769423', '27602116', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11502912', '星图', '剧情', '桑福德（约翰·库萨克 John Cusack 饰）是一名精神病医生，在治愈他人疾病的同时，桑福德自己的家庭却伤痕累累。儿子本杰（伊万·伯德 Evan Bird 饰）年纪轻轻却因为吸毒而被关进了戒毒所，女儿阿加莎（米娅·华希科沃斯卡 Mia Wasikowska 饰）更糟，她竟然因为纵火而被关入了精神病院。不仅家庭生活陷入了困境，桑福德的事业亦走到了瓶颈，哈瓦那（朱丽安·摩尔 Julianne Moore 饰）是桑福德的病人，亦是一名演员，她生活在同为著名演员的母亲的阴影之下，甚至连做梦也被母亲的幻影所纠缠。阿加莎出院了，本杰亦回归了家庭之中，孩子们的归来带给桑福德的是更大的麻烦，和更混乱的生活。©豆瓣', '朱丽安·摩尔', '大卫·柯南伯格', 6.4, 7899, 'tt2172584', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2200754657.jpg', 2.9, 15.5, 49.1, 25.7, 6.9, '0.087437,-0.205846,-0.470836,0.413243,-0.314826,-0.372343,0.962311,0.519502,-0.630284,-0.388946,0.378219,0.923128,0.083891,0.394172,0.247344,0.032346,-0.199707,-0.647245,0.118690,0.044126,-0.430914,-0.345534,-0.370525,-0.096978,-0.005853,-0.554080,0.563194,0.054346,-0.208958,0.034570,0.136814,0.433925,0.018065,0.550108,-0.239084,0.169702,0.019792,-0.037674,-0.075426,0.071206,0.108837,-0.305959,-0.037265,0.257935,-0.007141,0.259311,0.622648,-0.133687,-0.065226,-0.332236,0.444891,-0.333986,-0.006474,0.290850,0.205183,-0.305610,0.418381,0.217622,-0.220790,0.236241,0.206699,-0.016482,-0.793885,0.263706,0.156852,0.181192,-0.711140,0.434790,-0.061695,-0.209449,-0.095293,-0.088105,0.192949,0.329943,-0.043682,0.541999,-0.493247,-0.190143,-0.628614,0.142028,0.468067,-0.041297,-0.358773,0.366488,-0.476295,-0.432183,-0.146399,-0.190636,-0.697652,-0.047001,0.347256,0.100731,-0.322725,0.554212,-0.385393,-0.023417,-0.487115,-0.217414,-0.406455,-0.338643,-0.123671,-0.435505,0.006062,-0.285158,-0.464125,-0.198625,0.213669,-0.249116,0.680472,-0.607212,0.255480,0.371021,0.204324,-0.580369,0.479160,0.114233,0.365944,0.136944,-0.064742,0.698386,0.032188,0.362486,0.133524,0.295665,-0.142131,-0.108687,-0.252796,0.653504', '4301215', '25763555', '6745433', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11502973', '星际特工：千星之城', '动作', '人类和众多外星种族共同生活在一个名为千星之城阿尔法的繁华星际大都市，数百年来，千星之城阿尔法成为各族群和平共处的美妙天堂，它繁荣昌盛。韦勒瑞恩（戴恩·德哈恩 Dane DeHaan 饰）和洛瑞琳（卡拉·迪瓦伊 Cara Delevingne 饰）被选择成为阿尔法的守护者，他们俩是警卫部的执行人员，被任命去拦截一种稀有物品的交易。这种稀有物品与一个本该在数十年前就消失的稀有族群存在神秘的关联。然后他们来到了巨大的千星之城阿尔法城，这时他们的指挥官Arun Filitt（克里夫·欧文饰）在指挥中心遭到绑架，这对搭档开始意识到手中物品的不寻常价值。二人追寻凶手，发现自己身陷一场正在发酵的星际事件中……', '戴恩·德哈恩', '吕克·贝松', 6.9, 176969, 'tt2239822', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2504520028.jpg', 1.5, 8.3, 43.9, 36, 10.4, '0.520643,0.557453,-1.001526,0.668378,-0.013125,0.318392,0.731182,-0.164810,-0.326536,-0.383471,0.278891,1.043373,-0.099852,0.045468,0.387438,0.087333,-0.166967,-0.494532,-0.296011,-0.400504,-0.419692,-0.276029,-0.514284,-0.266546,-0.160058,-0.313439,0.745536,0.157668,-0.338382,0.461062,0.101083,0.628976,-0.542959,0.265459,-0.303942,-0.164119,0.563933,-0.168914,-0.313027,0.160048,-0.536717,0.150387,0.177895,0.182817,0.054139,0.014300,0.733025,-0.554959,-0.024820,-0.168333,0.154855,-0.429443,0.039560,-0.047191,0.524492,-0.003246,-0.213891,0.172398,-0.145158,0.137790,0.005175,-0.220853,-0.968028,-0.223075,0.174477,0.368506,-0.451985,0.419385,-0.098362,-0.239907,-0.006989,-0.267092,0.400732,0.537392,0.315820,0.368146,0.268890,-0.075674,-0.493289,-0.011732,0.949946,-0.253228,-0.492226,0.066473,0.094696,-0.768142,-0.387494,-0.198811,-0.322448,-0.344796,0.351000,-0.052530,0.302531,0.416904,-1.314669,0.239298,-0.322355,-0.339395,0.182233,-0.151567,-0.090168,-0.832251,-0.041061,-0.413640,-0.551905,0.500139,-0.014492,-0.205016,0.647928,-0.774076,0.300429,0.560408,0.402520,-0.490503,0.497570,-0.124200,0.289825,-0.358728,-0.066944,0.340076,0.481391,0.530381,-0.088948,0.057238,0.091211,-0.027665,-0.468934,0.405568', '26290398', '6982558', '7056398', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11503382', '龙珠Z：神与神', '动画', '在宇宙的神秘角落，令界王神都闻风丧胆的可怕神明悠悠苏醒。他是破坏之神比鲁斯（山寺宏一 配音），漫长的39年沉睡中，比鲁斯梦见与传说中的赛亚人之神对决，而弗利萨被消灭的消息也引起了他对赛亚人的兴趣。为此，他和随从维斯（森田成一 配音）来到了界王星，寻找打败弗利萨的孙悟空（野泽雅子 配音）。孙君不顾界王（八奈见乘儿 配音）的劝阻，斗胆向比鲁斯发起挑战，结果遭遇实力悬殊的惨败。为求赛亚人之神的真相，比鲁斯再度造访地球。此时Z战士们正齐聚西部城市为布玛（鹤ひろみ 配音）庆生，派对上的美味食物引起比鲁斯和维斯的极大兴趣。事先知情的贝吉塔（堀川りょう 配音）小心应付，以防破坏之神毁灭地球，但是意外与战斗还是不可避免地发生了……传说中的赛亚人之神是否真的存在？地球的命运将会如何？©豆瓣', '野泽雅子', '细田雅弘', 7.3, 13808, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1858174664.jpg', 1.8, 6, 37.6, 35.1, 19.4, '0.263572,0.391978,-0.629374,0.527859,0.223560,0.134752,0.560647,-0.183590,-0.102832,-0.268143,0.246009,0.809442,-0.260801,-0.068102,0.474073,-0.103698,-0.150092,-0.460769,0.045524,0.073687,-0.179956,-0.247963,-0.575660,-0.114439,-0.008129,-0.648420,0.584033,0.189393,-0.585974,0.287010,0.083119,0.307394,-0.284800,0.488486,0.144785,0.169472,0.193319,0.003887,-0.191645,0.225708,-0.097193,-0.078353,-0.133050,0.582672,-0.082071,0.112978,0.415336,-0.747601,-0.105883,-0.139353,0.293170,-0.579286,-0.019093,0.074472,0.521217,-0.177370,-0.064152,0.245434,0.290961,-0.046807,0.047804,0.010140,-0.930163,0.037511,0.113225,0.176077,-0.167928,0.308012,0.066143,0.098220,-0.017274,0.031471,0.372560,0.438370,0.497538,0.465663,0.012025,-0.181820,-0.193165,0.167621,0.772636,-0.012951,-0.442404,0.013740,-0.037878,-0.541451,-0.233271,-0.467611,-0.494135,-0.056447,0.258127,0.196020,0.109738,0.705291,-0.667956,0.017044,-0.376531,-0.258020,-0.081482,-0.197706,-0.069802,-0.622436,-0.163301,-0.187796,-0.067899,-0.035492,0.242429,-0.283620,0.689095,-0.718166,0.329515,0.565847,0.448107,-0.318529,0.663916,-0.167559,-0.088063,-0.323472,-0.055675,0.206913,-0.036497,0.234141,-0.023378,0.161680,0.195054,-0.018279,-0.403151,0.424763', '3769423', '35377026', '26667010', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11510624', '全民目击', '剧情', '林泰（孙红雷 饰）是当地名噪一方的富豪，近来正筹备自己人生中的另一件大事，与钟爱多年的女友结婚。不料此时传来噩耗，准新娘被人杀死在公寓的地下停车场，林泰闻讯如雷击顶。警方把怀疑的目光瞄向了他的独女林萌萌（邓家佳 饰），检方提起诉讼后，林泰花重金聘请著名律师周莉（余男 饰）为其女辩护，周莉曾为诸多有名的案件做过代理人，对打赢这场官司信心满满，庭审前，做了大量案头工作。公诉方派出的则是大名鼎鼎的检察官童涛（郭富城 饰），他的公诉犀利坚锐、一语中的。庭审开始后，控辩双方剑拔驽张，火药味十足，但随着审理的进一步深入，罪案越发扑朔迷离，似进入一条看不到边际的死穴......©豆瓣', '孙红雷', '非行', 7.8, 331025, 'tt3204696', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2091289138.jpg', 0.8, 2.9, 24.2, 49.2, 22.9, '0.127631,-0.004450,-0.533709,0.398242,0.121576,0.087909,0.758313,0.090112,-0.623062,-0.279532,0.199418,0.560629,-0.335938,-0.002758,0.397504,-0.102087,-0.135873,-0.790293,-0.263913,-0.039880,-0.012915,-0.687868,-0.234193,-0.028703,-0.135940,0.003733,0.433425,0.151009,-0.244008,0.367607,0.529674,0.427931,-0.182814,0.355487,0.137222,-0.256122,0.274932,0.169474,-0.360634,0.220142,-0.058207,-0.296519,-0.357324,0.099015,-0.130924,0.591413,0.431316,0.069377,-0.222617,-0.148177,0.616972,-0.152033,-0.023015,0.297977,0.327268,0.412997,0.178512,0.359319,-0.372149,-0.156989,0.058865,-0.084077,-0.599794,-0.029293,0.103895,0.016151,-0.364442,0.293546,-0.193054,0.007584,0.029806,-0.223283,0.292441,0.132310,0.099917,0.143412,0.026874,0.158070,-0.283180,0.353966,0.567369,0.214257,0.094603,-0.000610,0.160141,-0.472253,0.050005,-0.041872,-0.209683,-0.087806,0.348534,0.119043,0.129847,0.174956,-0.308279,-0.030653,-0.194164,-0.135113,0.040016,-0.054722,-0.299841,-0.476175,-0.073497,-0.191440,-0.184889,0.211946,0.135506,-0.250508,0.422767,-0.645202,-0.074399,0.138028,0.138967,-0.367803,0.587377,0.116359,0.246374,-0.281429,-0.309741,-0.056791,0.177217,0.179622,0.081618,0.181737,-0.109551,-0.427823,-0.191060,0.029547', '3263169', '1301022', '1293145', '26331839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11520649', '麦克法兰', '剧情', '《麦克法兰》根据1987年的真实故事改编，科斯特纳扮演的教练来到一个穷困无比，尘土飞扬，居民多为拉美裔的农业小镇，将那里的高中生们变成越野赛跑健将，给自己，也给小镇带来希望。', '凯文·科斯特纳', '妮琪·卡罗', 8.4, 25921, 'tt2097298', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2222667000.jpg', 0.1, 0.7, 13.9, 51.2, 34.1, '0.309879,-0.218940,-0.374709,0.679783,0.040175,-0.126427,0.355299,-0.101286,-0.322868,-0.628372,-0.150640,0.904975,0.067564,0.264318,0.643536,-0.228544,-0.337136,-0.442597,-0.312965,-0.358550,-0.244102,-0.397838,-0.112361,-0.289330,-0.367996,-0.415036,0.607693,0.051780,-0.239462,0.631295,-0.019316,0.688647,0.183636,-0.144857,-0.352159,0.131927,0.226991,-0.187837,-0.160512,0.214747,-0.260136,0.216177,-0.209106,-0.168203,0.142378,0.055820,1.143555,-0.139199,-0.084082,-0.023625,0.609227,-0.324746,0.178857,-0.378772,0.204378,-0.046304,-0.055353,-0.004034,-0.297151,0.179567,0.079942,-0.776990,-0.639779,-0.111303,0.381727,0.259686,-0.746912,0.087163,-0.060467,-0.156813,0.173341,-0.080332,0.169678,0.198577,0.304922,0.749125,0.015843,0.171663,-0.453480,0.214725,0.617385,0.023380,-0.375874,-0.195977,-0.671086,-0.578117,0.213468,-0.369938,-0.398877,0.116804,-0.089730,-0.334417,-0.146478,0.160651,-0.624308,-0.232340,-0.324182,-0.768405,0.384954,-0.334773,-0.422418,-0.505987,0.000887,0.184495,0.006400,0.055625,-0.033421,-0.157544,1.017971,-0.597403,0.377278,0.512669,-0.020501,-0.131190,0.496711,-0.026798,0.174644,-0.349276,-0.274737,0.334770,0.584030,0.243647,-0.130037,0.193156,-0.455128,-0.611486,-0.486883,0.413295', '3811356', '10174444', '4181031', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11523504', '神汉流氓', '喜剧', '粗暴鲁莽的朴光浩（朴信阳 饰）是某黑帮组织的得力干将，为了组织利益他出生入死，果敢非常。谁知在一次行动受伤后，光浩大睡三天，随即发现自己的身边充满各种各样奇怪状况，比如随手将勺子立住、能听懂鱼说话、看见卖鱼大婶拖着鱼尾巴。原来手上的伤口改变了他本该横死的命运，但也同时令他变成了通灵体质。按照巫女的说法，他不得不按命运的安排成为一名为人排忧解难的巫师。虽然一度拒绝，可是接二连三的危机迫使光浩向命运低头。在此之后，光浩一会儿是西装革履黑墨镜的黑帮分子，一会儿是涂脂抹粉身穿长袍跳舞的驱邪巫师，别样的人生就此展开……©豆瓣', '朴新阳', '赵真奎', 7.1, 9766, 'tt2630028', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1848987578.jpg', 0.9, 4.9, 44.4, 38.3, 11.5, '0.120774,0.201960,-0.273725,0.324829,-0.193799,-0.039800,0.513817,0.295054,-0.527596,-0.313670,0.368679,0.436216,0.002324,0.087561,0.317576,-0.242783,-0.153377,-0.646981,-0.054618,0.294380,-0.468973,-0.142797,-0.036495,-0.124156,0.008259,-0.440312,0.483944,0.090682,-0.115506,0.361929,0.451933,0.307971,-0.009760,0.383280,-0.304205,-0.243707,-0.092555,-0.220562,0.023294,0.174842,-0.013041,-0.358288,0.023698,0.388871,-0.269834,0.294963,0.535735,-0.351242,-0.302874,-0.346313,0.456109,-0.199843,-0.195921,0.006337,0.396302,0.279038,-0.003239,0.045443,-0.000815,0.057185,0.246522,0.078794,-0.612645,-0.051239,-0.020689,0.281663,-0.666266,0.163454,0.116091,-0.111722,-0.052812,-0.422047,0.015733,0.137992,0.387120,0.183761,0.053244,0.332994,-0.566123,0.043398,0.601616,0.061446,-0.112815,0.140332,-0.221597,-0.393663,0.069471,-0.254091,-0.017671,-0.072275,0.252116,0.008738,-0.082807,0.067784,-0.499005,-0.012616,-0.178722,-0.167125,0.225310,-0.375859,-0.141190,-0.248089,-0.130755,-0.221740,-0.204692,0.246518,-0.089288,-0.152944,0.428076,-0.714483,-0.050130,0.397081,0.095773,-0.273208,0.512214,0.153091,0.127842,-0.051958,-0.028234,0.228708,0.196534,0.121150,0.254492,0.221143,-0.078450,-0.094235,-0.176642,0.117939', '1301022', '35030151', '1793491', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11524958', '快乐王子', '剧情', '奥斯卡·王尔德传记片，鲁伯特·艾弗雷特自编自导自演，该片在圣丹斯电影节及英国上映好评如潮，被赞为鲁伯特·艾弗雷特职业生涯最佳，主演还有科林·费尔斯、科林·摩根、艾米丽·沃森和汤姆·威尔金森等。本片讲述奥斯卡·王尔德（鲁伯特·艾弗雷特 饰）在人世间最后的日子里鲜为人知的悲剧。他以旁观者的角度冷眼审视着自己的失败，以超然而幽默的方式看待着自己人生中的不幸。', '鲁伯特·艾弗雷特', '鲁伯特·艾弗雷特', 7.3, 6401, 'tt2404639', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510857223.jpg', 0.6, 4.4, 39.8, 40.8, 14.3, '0.064389,-0.142770,-0.581040,0.797069,0.439895,-0.283903,0.645989,0.129640,-0.283402,-0.055969,0.085438,0.723954,-0.574088,0.272027,0.815736,0.124387,-0.834921,-0.769226,-0.288579,-0.204735,-0.093014,-0.703956,-0.459725,-0.463493,-0.274037,-0.312866,0.358846,-0.009254,-0.162623,0.350360,0.811287,0.545046,0.347041,0.143446,0.056070,0.408288,0.407495,-0.231938,-0.330988,0.701328,0.509708,-0.087777,-0.334821,0.525723,0.031628,0.275600,0.677072,-0.493171,0.339692,0.145590,0.528412,-0.388439,0.461148,0.059556,0.171099,-0.348261,0.061287,0.080448,0.077032,0.200922,0.312746,-0.247985,-0.533399,-0.203440,-0.246028,0.365655,-0.431100,0.233474,0.107955,0.136283,0.139417,0.090103,-0.044304,0.030326,0.421820,0.382430,0.153363,0.058779,-0.149771,0.532943,-0.161182,0.101754,-0.434493,0.266276,-0.617096,-0.609039,0.066434,-0.389297,-0.659481,-0.270019,0.620322,-0.196849,0.423791,0.645045,-0.267239,-0.030505,-0.184414,-0.157419,-0.442463,-0.279627,0.083475,-0.998299,-0.031181,-0.369939,-0.019065,-0.333639,-0.282367,-0.548427,0.386264,-0.327932,0.276007,0.574653,0.147794,0.427370,0.598770,-0.039345,0.341823,-0.419590,-0.253110,0.421193,0.129813,-0.064041,0.473952,0.248419,0.457901,-0.021751,-0.240140,0.807417', '34961898', '1298616', '2364001', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11524967', '海底总动员2：多莉去哪儿', '喜剧', '患有短期健忘症的多莉（艾伦·德杰尼勒斯 Ellen DeGeneres 配音）曾经也拥有美好的家庭，然而一连串的意外让她与和蔼可亲的父母失散。此去经年，多莉邂逅了小丑鱼父子马林（艾伯特·布鲁克斯 Albert Brooks 配音）和尼莫（海登·罗兰斯 Hayden Rolence 配音），与他们经历了前所未有的大冒险。平静的日子里，童年时期的片段记忆突然闯入多莉的脑海，于是她再度踏上寻找父母的旅程。这一次，她来到了海洋生物博物馆，遇到了不打算回到大海的章鱼汉克（艾德·奥尼尔 Ed O''Neill 配音）以及童年时的朋友鲸鲨运儿（凯特琳·奥尔森 Kaitlin Olson 配音）。循着记忆中的蛛丝马迹，她离父母越来越近。然而在这一过程中，她又和马林父子失散了。对友情、亲情的执着，让这群小家伙无论千难万险也要坚持到底……©豆瓣', '艾伦·德杰尼勒斯', '安德鲁·斯坦顿', 7.6, 118965, 'tt2277860', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2356015154.jpg', 0.5, 3, 31.4, 45.4, 19.7, '0.463511,-0.150667,-0.693720,0.691895,0.360580,-0.690373,0.962389,-0.191232,-0.633656,-0.340685,0.008388,0.887611,-0.158095,0.257258,0.311025,0.131256,-0.543829,-0.658401,0.049876,-0.151263,-0.319291,-0.542543,-0.182173,-0.245475,0.041134,-0.208870,0.556766,0.014363,-0.005129,0.735876,0.020054,0.143323,-0.224341,0.441273,-0.221805,0.428027,0.150286,0.273195,-0.270130,0.003473,0.351349,-0.117358,-0.207824,0.209389,-0.060223,0.338789,0.709388,-0.220408,-0.062765,0.195368,0.155891,-0.287442,-0.004475,0.045154,0.080856,-0.103041,0.265241,0.342294,-0.142695,-0.106090,-0.132566,-0.269830,-0.517309,-0.019644,-0.146659,0.252989,-0.379527,0.310901,0.071138,0.131956,0.410290,-0.192655,0.259936,0.386733,0.426953,0.440736,-0.301547,0.008347,-0.079186,0.167785,0.743393,-0.147314,-0.247347,0.512406,-0.414539,-0.521063,-0.152090,-0.125253,-0.653552,0.118374,0.456724,0.292352,-0.408893,0.580562,-0.724466,0.053563,-0.246076,-0.154351,-0.169962,-0.270472,-0.139991,-0.576322,-0.323630,-0.480681,-0.391776,0.027391,-0.189926,-0.436107,0.631560,-0.850151,0.250797,0.553999,0.083758,-0.178551,0.670833,0.036472,0.214744,-0.249452,0.256948,0.459724,-0.038210,0.174618,0.085965,0.271940,0.059422,0.143401,-0.586951,0.593189', '1296534', '1309172'