INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11525673', '布达佩斯大饭店', '剧情', '故事要从一位无名作家（裘德·洛 Jude Law 饰）说起，为了专心创作，他来到了名为“布达佩斯”的饭店，在这里，作家遇见了饭店的主人穆斯塔法（F·莫里·亚伯拉罕 F. Murray Abraham 饰），穆斯塔法邀请作家共进晚餐，席间，他向作家讲述了这座饱经风雨的大饭店的前世今生。饭店曾经的主人名叫古斯塔沃（拉尔夫·费因斯 Ralph Fiennes 饰），而年轻的穆斯塔法（托尼·雷沃罗利 Tony Revolori 饰）在当时不过是追随着他的一介小小门童。古斯塔沃为人正直，精明能干，在他的经营和组织之下，布达佩斯大饭店成为了当时首屈一指的度假胜地。古斯塔沃和年迈的D夫人（蒂尔达·斯文顿 Tilda Swinton 饰）情投意合，D夫人去世后，在遗嘱中将一副价值连城的名画留给了古斯塔沃，这一举动惹恼了她的儿子迪米特里（阿德里安·布洛迪 Adrien Brody 饰），布达佩斯大饭店和古斯塔沃的厄运就此拉开了帷幕。', '拉尔夫·费因斯', '韦斯·安德森', 8.9, 857491, 'tt2278388', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2178872593.jpg', 0.2, 0.7, 8.3, 36.4, 54.5, '0.361481,0.066091,-0.471658,0.554228,-0.095455,-0.424557,0.704646,0.536652,-0.590692,-0.355687,0.132808,1.152988,-0.257480,0.272948,0.698587,0.333402,-0.289670,-0.544937,0.082790,-0.324459,0.020989,-0.625947,-0.219670,-0.205143,-0.065488,-0.296796,0.172374,-0.046680,-0.023546,0.333074,0.476602,0.573993,0.137416,0.093658,-0.193446,0.126734,0.296680,-0.180779,-0.310708,0.317953,-0.040965,-0.159112,-0.097706,0.091959,0.178019,0.354911,0.482123,-0.307711,0.125781,0.115701,0.210072,-0.154932,0.383943,0.004976,0.200345,-0.316512,0.140621,0.176151,-0.362909,-0.191051,0.129111,-0.330238,-0.472777,-0.013683,0.191248,0.178711,-0.873021,0.418336,-0.294410,-0.050362,0.019026,-0.333988,0.237774,0.480841,0.080536,0.254973,0.324095,0.086862,-0.616734,0.141053,0.379062,0.239525,-0.113555,0.320066,-0.092311,-0.382660,-0.026884,-0.160934,-0.526093,-0.025877,0.285972,-0.069802,0.231114,0.163109,-0.476776,-0.407032,-0.334611,-0.096885,0.182231,-0.166721,-0.323969,-0.550522,-0.134437,-0.330432,0.061399,-0.143762,-0.142352,0.007785,0.533061,-0.596040,0.116994,0.283735,0.124833,-0.044664,0.898089,-0.152755,0.203194,0.034309,-0.076037,0.404337,0.304666,0.085212,0.082022,0.530478,0.148767,-0.383647,-0.2