INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11525705', '同窗', '剧情', '李明勋（崔胜贤 饰）的父亲是一名南派间谍，因为受人陷害而死在了冤屈之中。身为他的子女，李明勋和妹妹惠仁（金裕贞 饰）遭到了当局的粗暴对待，被怀疑通敌的两人身陷囹圄之中，处境十分糟糕。为了保护心爱的妹妹，善良正直的李明勋被迫接替了父亲的工作，成为冷酷无情的间谍，他接收了残酷而又艰苦的训练，之后乔装打扮成为高中生的模样潜入南韩，只为了刺杀名为北斗星的技术者。在学校里，李明勋结识了名为慧仁（韩艺璃 饰）的女孩，让李明勋没有想到的是，两人竟然渐渐坠入了爱河。可是，李明勋自知身份特殊，两人的感情亦不会有好的结果，不仅如此，他的存在甚至会给慧仁引来杀身之祸。©豆瓣', '崔胜铉', 'Hong-soo Park', 6.7, 16770, 'tt3144098', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2153607678.jpg', 1.7, 10.9, 51.3, 24.4, 11.7, '0.275529,-0.010128,-0.699532,0.716323,-0.430681,-0.166499,0.595063,0.144485,-0.809562,-0.274263,0.403532,0.876127,0.159315,0.121654,0.243056,0.051451,-0.015586,-0.803592,-0.271036,-0.192618,-0.312931,-0.460669,-0.390692,-0.209030,-0.155386,-0.431024,0.559041,0.124747,-0.441081,0.285109,0.338275,0.545727,-0.014146,0.551529,-0.228481,-0.067973,0.100684,0.127157,-0.120370,0.251419,0.026939,-0.337879,0.012623,0.417601,-0.160790,0.547912,0.656120,-0.356434,-0.355835,-0.311916,0.464255,-0.489342,-0.058782,0.361148,0.363063,-0.030431,0.332181,0.274253,-0.348089,0.034728,0.131974,-0.049587,-0.968195,0.028090,0.343257,-0.028438,-0.589592,0.447917,-0.125502,-0.300161,0.107148,-0.187999,0.397100,0.336236,0.413022,0.490200,-0.216068,-0.109828,-0.313414,0.072038,0.708283,0.032680,-0.218608,0.252984,-0.286461,-0.357262,0.253662,-0.626089,-0.429604,0.102005,0.299945,0.036990,-0.101173,0.350233,-0.402048,-0.088935,-0.307550,0.086947,-0.101862,-0.506569,-0.102542,-0.231291,-0.077207,-0.499317,-0.421972,0.091764,-0.057813,-0.395973,0.771324,-1.054897,0.221775,0.434074,0.296563,-0.880828,0.574463,0.252281,-0.009351,-0.112599,-0.010441,0.174748,0.019389,0.061285,0.108256,0.097835,-0.186410,-0.290635,-0.120606,0.153138', '1877596', '1301022', '26678784', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11526817', '刺客信条', '动作', '卡勒姆·林奇（迈克尔·法斯宾德 饰）在死刑即将执行之前清醒过来，发现他被索菲娅（玛丽昂·歌迪亚 饰）选中，来参加一个能让人类摆脱暴力冲动的计划。虚拟现实机器Animus能让用户体验祖先的记忆，被绑在机器上之后，卡勒姆·林奇意识到他是生活在西班牙宗教法庭时期一位刺客阿圭拉的后裔，他们寻找的是可以控制自由意志的伊甸园苹果。索菲娅在父亲艾伦（杰瑞米·艾恩斯 饰）施加的压力下不情愿地操纵着卡勒姆·林奇回到过去寻找伊甸园苹果在现代世界的下落，威胁着他身体和心理的健康。但在杀手同行穆萨（迈克尔·威廉姆斯 饰）暗示了卡勒姆·林奇，提醒他艾伦有可能动机不纯之后，卡勒姆·林奇开始重新考虑他的行为和动机，而人类自由意志的命运也变得悬而未决……', '迈克尔·法斯宾德', '贾斯汀·库泽尔', 5.3, 103927, 'tt2094766', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2432597986.jpg', 9, 34.4, 41.6, 11.8, 3.2, '0.246606,0.555509,-0.704503,0.630484,-0.080448,-0.280737,0.733670,0.309285,-0.340701,-0.091122,0.249353,0.647981,-0.039021,-0.067509,0.459904,0.289580,-0.440397,-0.481886,0.159413,0.051084,-0.486040,-0.633752,-0.321212,-0.393043,-0.219413,-0.801213,0.530317,-0.144984,-0.421096,0.005074,0.207434,0.441496,-0.003670,0.192413,0.160037,-0.128969,0.318727,-0.279457,-0.294971,0.314855,0.164025,-0.050451,-0.063733,0.486168,0.048361,0.240399,0.575120,-0.369209,0.133522,0.068070,0.152766,-0.232867,-0.048953,0.171251,0.042523,-0.157734,-0.215672,0.130343,0.205775,0.357241,0.229620,-0.104743,-0.772607,-0.221023,-0.236496,0.477576,-0.434739,0.455305,-0.371157,0.268687,-0.229709,-0.421805,-0.040178,0.189946,0.226384,0.255876,-0.002628,-0.009763,-0.489921,-0.091089,0.473923,-0.160636,-0.445264,0.301757,-0.576232,-0.387771,-0.293669,0.003452,-0.675465,-0.334445,0.474100,0.387299,-0.413179,0.241500,-0.521657,0.024218,-0.469319,-0.055626,-0.050018,-0.345251,0.026314,-0.468637,-0.313104,-0.486974,-0.273450,-0.209216,0.021029,-0.473222,0.450553,-0.746189,0.231438,0.939696,0.281470,-0.097579,0.406945,0.210590,0.036127,-0.189561,0.021634,0.388634,0.148239,0.330561,0.122792,0.103566,0.039869,0.125754,-0.282398,0.670368', '4126925', '3824339', '10774184', '27039358');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11527487', '弗兰西丝·哈', '剧情', '索菲（米凯·萨姆纳 Mickey Sumner 饰）是弗朗西斯（格蕾塔·葛韦格 Greta Gerwig 饰）最要好的朋友兼室友，两人整日里出双入对，关系俨然比情侣要亲密的多。然而某日，索菲忽然告诉弗朗西斯，自己要搬到城中和另一个女孩同住。虽然索菲万般保证两人还是朋友，但弗朗西斯的内心依旧十分失落。无法独自负担房租的弗朗西斯只得另觅住处，索菲的朋友列夫（亚当·德赖弗 Adam Driver 饰）在关键时刻助了弗朗西斯一臂之力，就这样，弗朗西斯开始了和列夫以及列夫的室友本吉（迈克尔·泽根 Michael Zegen 饰）一起的同居生活，并承诺会在圣诞节的舞蹈演出后付齐房租。糟糕的是，没过多久，弗朗西斯便丢掉了工作。一时之间，她不知道自己究竟该何去何从。©豆瓣', '格蕾塔·葛韦格', '诺亚·鲍姆巴赫', 8.4, 51974, 'tt2347569', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1927054388.jpg', 0.3, 1.3, 13.9, 46.4, 38.1, '0.414566,-0.259412,-0.400096,0.304535,0.011736,-0.510496,0.517654,0.293644,-0.405165,-0.287544,-0.055906,0.791499,-0.078070,0.467511,0.324884,0.168616,-0.507657,-0.686177,0.117439,-0.234713,-0.286781,-0.669944,-0.062565,-0.345051,-0.242536,-0.013960,0.398691,-0.130195,0.215006,0.247547,0.454389,0.277741,-0.183874,0.608693,-0.204501,0.046328,0.077323,0.161642,-0.430445,0.012423,0.152581,-0.059074,-0.119914,0.149014,0.498876,0.372103,0.325660,0.004308,-0.078611,0.288434,0.155417,0.136768,0.175757,0.086636,0.146628,-0.197136,0.331815,0.100566,-0.167693,-0.012949,-0.018667,-0.184524,-0.438605,0.222862,0.151498,0.066606,-0.649746,0.530012,-0.112787,0.001978,0.280097,-0.114954,0.136190,0.476537,0.116001,0.334520,-0.057079,-0.149212,-0.278951,0.105417,0.732214,0.222215,0.049824,0.459936,-0.423537,-0.345447,-0.128988,0.021713,-0.489965,-0.094750,0.018573,0.306948,0.096049,0.213418,-0.485192,-0.074302,-0.146023,0.283411,-0.109740,-0.551942,0.210346,-0.491327,-0.028080,-0.478723,-0.328696,0.250035,0.059790,-0.171299,0.571491,-0.909412,0.060423,0.282134,0.489540,-0.228514,0.517354,0.377876,0.313700,-0.272778,0.028186,0.224368,-0.028963,0.041366,0.240200,0.260048,0.238129,-0.003573,-0.347657,0.428313', '1292219', '35048413', '1308755', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11528271', '一曲倾情', '剧情', '安妮·海瑟薇饰演的年轻女子因为弟弟的意外而回到纽约担负起照顾他的责任。不料却和弟弟最喜欢的音乐人之间发展出一段情缘。本片集合了爱情、音乐等年轻人喜闻乐见的元素，是一部偏文艺向的爱情片。', '安妮·海瑟薇', '凯特·巴克佛洛兰', 5.9, 5347, 'tt2182972', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2210994074.jpg', 4, 23.8, 49.2, 17, 6, '0.369897,-0.272253,-0.792986,0.666958,-0.188567,-0.345700,0.965249,0.288814,-0.432601,-0.289954,0.256307,0.710719,0.044138,0.123549,0.706277,0.145261,-0.211557,-0.593158,0.036441,0.006783,-0.205537,-0.315095,-0.129658,-0.117886,-0.066564,-0.584254,0.812294,0.129029,-0.305353,0.483740,0.486169,0.005673,-0.182052,0.276256,0.167059,-0.091299,-0.135204,0.007311,-0.334184,0.258486,0.271219,-0.357904,-0.331986,-0.183136,-0.328649,0.201765,0.745836,0.014821,-0.023030,-0.026068,0.666672,-0.323327,-0.059336,-0.401413,0.107474,0.140959,0.336813,-0.040413,-0.052875,-0.173853,-0.261935,-0.466830,-0.603093,0.381462,0.034140,0.295197,-0.613128,0.768820,0.029255,-0.206867,0.320118,-0.503667,0.144079,0.040698,0.452911,0.853868,-0.414057,0.359740,-0.071491,0.071619,0.799596,0.097798,-0.294078,0.750920,-0.276639,-0.376726,-0.202132,-0.254787,-0.766150,0.182528,0.140529,0.003593,0.217951,0.137517,-0.620416,0.247652,0.145150,-0.099798,0.183851,-0.698321,0.030756,-0.645921,-0.083273,-0.261690,0.051272,0.014435,0.203253,-0.347266,1.323299,-0.856289,-0.064252,0.683804,0.298774,-0.801417,0.962384,0.241332,0.294592,-0.378020,-0.050344,0.322557,-0.049283,-0.184585,-0.104921,0.286389,-0.017351,-0.217129,-0.533982,0.156742', '6963575', '25738406', '1908036', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11529526', '中国合伙人', '剧情', '20世纪80年代，三个怀有热情和梦想的年轻人在高等学府燕京大学的校园内相遇，从此展开了他们长达三十年的友谊和梦想征途。出生于留学世家的孟晓骏（邓超 饰）渴望站在美国的土地上改变世界，浪漫自由的王阳（佟大为 饰）尽情享受改革开放初期那蓬勃激昂的青春气息，曾两次高考落榜的农村青年成冬青（黄晓明 饰）以晓骏为目标努力求学，并收获了美好的爱情。然而三个好友最终只有晓骏获得美国签证，现实和梦想的巨大差距让冬青和王阳倍受打击。偶然机缘，被开除公职的冬青在王阳的帮助下办起了英语培训学校，开始品尝到成功的喜悦。在美国发展不顺的晓骏回国，并加入学校，无疑推动三个好友朝着梦想迈进了一大步。只是随着成功的降临，他们的友情也开始承受严峻的考验……©豆瓣', '黄晓明', '陈可辛', 7.6, 604626, 'tt2278392', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1959304567.jpg', 0.7, 3, 29.7, 48.3, 18.4, '0.278626,0.220051,-0.722881,0.580265,-0.017172,-0.336241,0.582603,0.119508,-0.355943,-0.044185,0.152348,0.560929,-0.211771,0.339578,0.313410,-0.436031,0.097262,-0.695897,0.131458,-0.058706,-0.127256,-0.276364,-0.202744,-0.075198,-0.242922,-0.481700,0.868096,0.327278,-0.201072,0.805196,0.289917,0.202876,-0.023764,0.281714,-0.358559,-0.096769,0.166530,0.346892,-0.709999,0.201988,-0.092938,-0.282410,-0.028359,0.103346,-0.121690,0.026902,0.658205,0.117929,-0.213592,0.036702,0.589074,-0.141768,-0.327506,0.103877,0.303280,0.177145,0.021187,0.352305,0.088406,0.034152,-0.156162,-0.435803,-0.812386,-0.033656,0.159392,0.009510,-0.637925,0.720694,0.276130,-0.277077,0.086668,-0.171688,-0.105799,0.623019,0.254938,0.615085,-0.448275,0.265203,-0.459157,0.305964,0.878420,-0.217425,-0.383939,0.365954,-0.291204,-0.383422,-0.090569,-0.179734,-0.364175,-0.009729,0.274334,0.203279,-0.165816,0.181026,-0.798750,0.330659,-0.183296,-0.170358,0.299479,-0.536722,-0.123792,-0.662684,-0.247674,-0.377104,-0.449491,0.133112,0.090070,-0.608048,0.959251,-0.873446,0.205902,0.497819,0.409962,-0.515693,0.805240,0.089590,0.070608,-0.462775,-0.080680,0.554268,-0.352957,0.316552,-0.150743,0.345509,-0.303241,0.102803,-0.398603,0.632962', '26021055', '3811356', '4127270', '10876425');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11531725', '悬赏', '剧情', '阿曹（杜汶泽 饰）是一名“赏金猎手”，即依靠不错的伸手拿悬赏生活的人。这次阿曹要拿到警方的四十万悬赏，就需要抓到抢劫犯李见辉（王子义饰）。按照情报，他来到了一座神秘的旅馆，消息称这是李见辉最后出现的地方。旅店老板（万梓良 饰）是一个古怪的人，平日疑神疑鬼，还张贴出一张悬赏要找回自己的女儿，赏金过亿，更古怪的是店中的服务员孙朗清（薛凯琪 饰）却多次声称自己就是孙老板的女儿，孙老板却矢口否认。不只有奇怪的老板店员，酒店的旅客也疑点重重，驼背龅牙的椰子佬（王子义 饰）整日行踪诡秘，更传说酒店常有人自杀……阿曹能成功拿到悬赏吗？旅店内秘密能否被揭开。©豆瓣', '杜汶泽 Chapman To', '冯志强', 5.9, 11856, 'tt2168166', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1529198416.jpg', 4.8, 22.1, 52.5, 16.9, 3.7, '0.165614,0.247544,-0.208294,0.310667,-0.227892,-0.189116,0.668890,0.125732,-0.517012,-0.207287,0.420270,0.276531,-0.047928,0.157993,0.208769,0.376735,-0.119904,-0.167911,-0.047854,-0.552766,-0.198519,-0.311165,-0.282565,-0.541735,-0.106458,-0.069183,0.170581,0.139520,-0.163264,0.067652,0.489623,0.275396,-0.075294,0.458392,-0.440159,0.104546,0.131866,0.045200,-0.103780,0.142735,-0.030981,-0.255121,-0.014034,-0.000195,0.240551,0.481799,0.459471,-0.121909,-0.361465,0.235305,0.288506,-0.106717,-0.141071,-0.140780,0.356265,-0.271607,0.314542,-0.170150,-0.128410,-0.077173,0.146400,-0.083661,-0.604226,0.084884,0.431756,0.209209,-0.423962,0.099156,-0.484439,0.189420,0.035930,-0.390827,0.173989,0.024209,0.254276,0.095095,0.250681,0.028725,-0.751644,0.302987,0.404126,-0.154313,0.210297,-0.003572,-0.235821,-0.780964,-0.066612,-0.108533,-0.362024,0.303134,0.428508,-0.294608,0.218049,-0.339553,-0.559928,-0.114975,-0.151899,-0.005798,0.202294,-0.209044,-0.188939,-0.437008,0.028702,-0.038629,-0.088600,0.226178,0.240215,-0.181367,0.351077,-0.417850,0.094432,0.542980,0.352693,-0.281518,0.653015,-0.259812,-0.106671,-0.358655,-0.291024,-0.305617,0.612796,0.326263,0.088145,0.276847,0.022897,-0.419420,0.011554,0.296931', '1309101', '1308842', '10527288', '30387441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11534824', '稻草之盾', '惊悚', '谁也没有想到，一起惨无人道的女童虐杀案件竟会让全日本上下陷入疯狂。遇害者的爷爷蜷川隆兴（山崎努 饰）是在经济领域执牛耳的大人物，这名悲痛至极的老人在发行量最大的报纸上刊登悬赏启示，凡能杀死嫌疑人清丸国秀（藤原龙也 饰）的人，将得到10亿日元的酬金。这则前所未有的启示很快发生了作用，担心自身安全的清丸在福冈县投案自首，但为了将其押送回东京送检，还将跋涉一千多公里的路程。此时此刻，日本国民已经相继化身为为了金钱不惜动武杀人的阿修罗。危急关头，SP铭苅一基（大泽隆夫 饰）、白岩笃子（松岛菜菜子 饰）、奥村武（岸谷五朗 饰）、神箸正贵（永山绚斗 饰）以及关谷贤示（伊武雅刀 饰）等五名精英承担了押送的任务。交杂着人性和法律的抗争，恶魔清丸和保护他的警察踏上漫长而凶险的旅途……本片根据木内一裕的同名原作改编。©豆瓣', '大泽隆夫', '三池崇史', 6.7, 7442, 'tt2347144', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1884287960.jpg', 3.5, 10.5, 43.7, 32, 10.4, '-0.022642,0.005424,-0.531188,0.425259,0.102975,-0.187517,0.478017,0.204745,-0.220521,-0.212172,0.379442,0.560643,-0.033929,-0.066376,0.288855,-0.221676,-0.188044,-0.645428,-0.172405,-0.232203,-0.240999,-0.410656,-0.054083,-0.255326,-0.188104,-0.309342,0.509614,0.235642,-0.125689,0.449137,0.406042,0.346648,-0.328370,0.316336,-0.089943,0.017511,0.124918,-0.137386,-0.055857,0.175299,-0.100084,-0.408727,-0.038303,0.361530,0.068623,0.321697,0.723028,-0.339502,-0.142858,-0.003045,0.236449,-0.453622,-0.145516,-0.007193,0.274393,-0.073322,-0.014041,0.271500,-0.463886,0.033161,0.252114,-0.049302,-0.860094,-0.237948,0.122570,0.326206,-0.264741,0.427531,-0.178070,-0.056329,0.058635,-0.106413,0.157478,0.409540,0.130826,0.213100,-0.219681,-0.063974,-0.332175,0.338112,0.507278,-0.232256,0.031223,-0.050092,-0.274818,-0.567044,-0.257467,-0.367806,-0.158349,-0.071836,0.236053,0.033495,-0.026171,-0.010713,-0.547936,-0.181661,-0.174507,-0.261306,0.030483,-0.069942,-0.064806,-0.607537,0.002634,-0.453971,-0.185438,0.174048,0.428851,-0.165402,0.817640,-0.486939,-0.004205,0.470944,0.221113,-0.412685,0.353861,-0.089824,-0.123643,-0.103208,-0.218986,0.142462,0.363890,0.514566,0.157594,0.148026,-0.047686,-0.078732,-0.225542,0.267338', '27602116', '25928048', '3811356', 