INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11537964', '有人赞美聪慧，有人则不', '剧情', '故事发生在山西某地。城里孩子杨晋（李书晨 饰）小学毕业了，他天资聪颖，能清楚地背诵全省地名，自感已经长大，为庆祝自己的这一发现，他写信告诉父母自己要去奶奶家，真实的情况是他跑到了山里好朋友王小波（王琛 饰）家。王小波学习成绩平平，平日里调皮捣蛋，他即能炸黄河里的鱼，又能捉山里的螃蟹，是小伙伴中的“混世魔王”。杨晋的奶奶有严重的重男轻女思想，她爱孙子胜过爱孙女，而常受爸爸批评的小波并没觉得自己做错什么，在俩孩子眼中，成年人的世界是不可理喻的，只有他们看到的才是真正的世界。两个城乡不同环境长大的孩子，在这个属于自己的夏天里，度过了一段无法无天的美好时光……©豆瓣', '李书晨', '杨瑾', 7.8, 6353, 'tt2750834', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1913736665.jpg', 0.7, 2.5, 25.7, 50.5, 20.6, '0.359136,-0.179867,-0.838962,0.483749,-0.502265,-0.206997,0.632463,-0.037394,-0.716549,0.067660,-0.010057,0.655678,0.015347,0.595691,-0.142351,0.248435,-0.074962,-0.510395,0.132472,-0.289019,-0.288383,-0.491266,-0.256636,-0.208849,-0.104664,-0.062508,0.131413,0.010875,-0.080938,0.041734,0.168123,-0.296252,0.106648,0.465699,-0.514442,0.362406,-0.245602,0.093678,-0.004325,-0.075789,0.121196,0.133173,-0.173993,0.230521,0.250333,0.278707,0.728428,-0.025436,-0.276223,-0.073794,0.411524,-0.022796,-0.327129,0.141286,0.444607,-0.264953,0.319536,0.023553,0.173493,-0.053679,-0.175561,-0.074234,-0.420250,-0.152725,0.169335,0.184786,-0.691409,0.471017,0.128396,-0.295667,0.190173,-0.430627,0.320604,0.183007,0.001876,0.913842,-0.126605,-0.078423,-0.502091,0.288656,0.741777,-0.301259,-0.174617,0.418935,-0.433613,-0.377779,0.030390,-0.299213,-0.529182,0.176099,0.121496,-0.107644,-0.731057,0.268268,-0.179775,0.172140,0.035475,-0.138389,-0.036044,-0.531222,-0.255923,0.134282,-0.060835,-0.773348,-0.360507,0.033408,-0.018109,-0.332788,0.859773,-0.883273,0.028411,0.631583,0.276475,-0.432728,0.828148,0.271018,0.016197,-0.204657,0.190663,-0.058578,-0.165336,0.210263,0.022746,0.482296,0.085069,-0.125793,-0.526467,0.549393', '26354526', '4066127', '1292720', '1438708');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11537965', '家在水草丰茂的地方', '剧情', '阿迪克尔（汤龙 饰）和巴特尔（郭嵩涛 饰）虽为血脉相连的亲兄弟，却因为幼年时聚少离多，使得兄弟之间的情谊十分淡漠，甚至彼此之间只有冷眼和沉默。到了上学的年龄，父母决定将兄弟两人送进同一所学校，并且一同寄养在爷爷家，可即便生活在同一屋檐下，两人之间尴尬的气氛仍然没有缓解。一晃眼，暑假来临，与此同时，年迈的爷爷不幸去世，只留下兄弟两独守空房，左等右等也等不来父亲的两人决定，依靠他们自己的力量，穿越茫茫五百公里的大草原，找到回家的路。就这样，两个孩子踏上了旅途，一路上，有无穷无尽的困境和麻烦在等待着他们。©豆瓣', '汤龙', '李睿珺', 8, 15489, 'tt4131150', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2275274380.jpg', 0.4, 1.8, 21.7, 50.8, 25.2, '0.231268,-0.201809,-0.835987,0.395248,0.232340,-0.658419,0.721860,0.373231,-0.558447,-0.459829,-0.018478,0.719928,0.035918,0.405019,0.140370,-0.393237,-0.323042,-0.557251,-0.045971,-0.132744,-0.437318,-0.503001,-0.044966,0.051249,-0.235225,-0.127097,0.582392,0.126013,0.056223,0.759987,-0.016652,0.017173,-0.326033,0.549861,-0.579836,-0.009659,-0.144073,0.398200,-0.623850,-0.005383,0.133291,0.101966,-0.175625,-0.043208,0.282348,0.298078,0.792435,-0.313122,-0.177564,0.179690,-0.098985,-0.211181,-0.059363,0.139233,0.340753,-0.126277,0.381056,0.191134,-0.201658,0.038139,-0.216614,0.087424,-0.401082,0.357877,-0.035454,-0.033471,-0.785482,0.640234,0.194708,-0.497000,0.269181,-0.462024,0.236866,0.706512,0.013677,0.656320,-0.434449,-0.011281,-0.405779,-0.213427,0.968173,-0.100366,-0.114441,0.297995,-0.121605,-0.253969,-0.021406,-0.169411,-0.479722,-0.136527,0.165207,0.260061,-0.120206,0.329336,-0.494421,0.065324,0.002538,0.028541,0.207299,-0.858380,0.065675,-0.466929,-0.065241,-0.469250,-0.351087,0.510548,0.261761,-0.159376,0.482630,-0.570622,0.405906,0.141459,0.469634,-0.468680,0.971548,0.252979,0.457202,-0.329659,0.174897,0.102408,0.057551,0.192635,0.433780,0.119713,-0.178438,0.367963,-0.486955,0.314851', '2990737', '26687241', '1300202', '2080130');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11538048', '图书馆战争', '剧情', '进入正化年间（始自1989年），为了改善混乱堕落的社会风气，日本政府颁布《媒体良化法》，并成立特殊部门对所有可能影响世人身心健康的书籍进行查封与销毁。可与此同时，言论自由也遭到粗暴遏制和打压。为了捍卫自由思想，名为“图书馆自卫组织图书队”的组织应运而生，他们为了保护书籍拿起武器，许多人为此献出生命。高中时代曾被视为“王子大人”的图书队员相助，热血女孩笠原郁（荣仓奈奈 饰）决意加入图书队，可是负责训练她的二等图书正堂上笃（冈田准一 饰）似乎总有意刁难笠原，而女孩依旧凭借自己的努力成为一名图书特殊部队成员。在接下来的日子里，笠原和堂上教官、同期手冢光（福士苍汰 饰）的友情和信任日益加深。未过多久，左右言论自由的重大事件到来，图书队和媒体良化队宿命的战争拉开大幕……本片根据有川浩的“图书馆系列”的第一部改编。©豆瓣', '冈田准一', '佐藤信介', 7, 10244, 'tt2315236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1980601664.jpg', 2.3, 8.5, 39.4, 35.8, 13.9, '0.114796,0.048556,-0.354733,0.378197,0.198313,0.169848,0.327936,0.010832,-0.484993,-0.448631,0.297787,0.345355,0.201177,-0.067656,0.364651,-0.411664,-0.504360,-0.719340,-0.216831,-0.094683,-0.131708,-0.267120,-0.169315,-0.225435,-0.192384,-0.545741,0.962399,0.194800,-0.406972,0.482828,0.221946,0.366209,-0.205689,0.202459,0.291187,-0.210507,0.140726,-0.080740,-0.369807,-0.039995,-0.231167,-0.153640,-0.332591,0.041024,0.273429,0.196311,0.453329,-0.409870,-0.096373,-0.326029,0.426556,-0.327034,-0.037277,0.139741,0.484122,0.538582,0.376536,0.530297,-0.046779,0.153283,-0.183342,-0.338600,-0.677315,-0.186189,0.266065,0.003069,-0.262402,0.495335,-0.142535,0.251891,0.062006,0.007538,-0.071991,0.427416,0.368937,0.211732,-0.286658,0.026430,-0.356295,0.186985,0.467649,-0.286943,-0.154265,-0.220662,-0.145195,-0.283404,-0.095457,-0.327069,-0.223436,-0.213417,-0.008840,-0.014391,0.370961,0.152547,-0.721172,0.041630,0.002476,-0.302922,0.307338,-0.424756,0.080957,-0.758633,0.052451,-0.034077,0.052126,-0.011693,0.322098,-0.327642,0.943878,-0.772645,0.266148,0.358977,0.357428,-0.851741,0.481436,0.160176,0.126621,-0.165350,-0.419356,0.246176,0.205581,0.339057,-0.135877,0.025004,0.013540,-0.343511,-0.039033,0.126594', '2369613', '25863940', '1316589', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11540651', '许三观', '剧情', '故事发生在20世纪60年代的韩国，居住在某个乡村的贫穷青年许三观（河正宇 饰）喜欢上了同村最美丽的姑娘许玉兰（河智苑 饰）。传闻玉兰是小混混何小勇的女朋友，但是三观凭借锲而不舍的精神和憨皮赖脸的劲头说服了未来的老丈人，如愿抱得美人归。婚后数年，夫妻二人先后育有一乐、二乐、三乐三个机灵调皮的儿子，一家人的生活也有滋有味。但是一乐越来越像何小勇，引来村里人议论纷纷，这让许三观坐立不安，而他对玉兰、一乐的感情似乎也由此发生了变化。在那个卖血成风的年代，三观曾经用自己的血换来了钱。令他想不到的是，在接下来的人生里，他将不得不为了家人们一次次卖血，苍白羸弱，命在旦夕……本片根据余华的小说《许三观卖血记》改编。©豆瓣', '河正宇', '河正宇', 7.4, 43885, 'tt3797004', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2216130110.jpg', 0.5, 4.2, 36.3, 43.5, 15.5, '0.206195,-0.078984,-0.641221,0.390683,-0.048874,-0.305272,0.722159,0.183237,-0.649379,-0.067213,-0.033166,0.506859,-0.351102,0.418303,0.300646,-0.102300,0.049839,-0.417222,0.047390,-0.135506,-0.105918,-0.312284,-0.090090,-0.302126,-0.231358,-0.344846,0.359962,0.053525,-0.085094,0.321445,0.324476,0.004142,0.001447,0.196256,-0.312900,0.388360,-0.065979,0.295765,-0.197211,-0.126974,0.126901,-0.185399,-0.188792,0.220565,-0.158189,0.316302,0.760417,-0.157944,-0.353171,-0.044566,0.517829,-0.199489,-0.293358,0.279575,0.305137,-0.139827,0.309704,-0.148421,0.061638,-0.115681,0.133867,-0.069138,-0.611633,0.101353,0.176346,-0.014501,-0.550456,0.465660,0.174582,-0.129383,-0.125302,-0.242375,0.388257,0.451222,0.447699,0.482392,-0.265067,0.272235,-0.502981,0.355486,0.602325,0.199827,-0.281287,0.675550,-0.424000,-0.251420,-0.173351,-0.276748,-0.691608,-0.000708,0.246840,-0.082133,-0.332392,0.139470,-0.475342,0.244572,0.081945,-0.002885,-0.027574,-0.283333,-0.334936,-0.129134,-0.437920,-0.777328,-0.072767,-0.065783,0.111794,-0.405790,0.973109,-0.621751,-0.081510,0.212408,0.151488,-0.677212,0.522041,0.404415,0.038226,-0.081836,-0.096988,0.208054,-0.031352,0.029225,0.179422,0.444234,-0.146677,-0.147623,-0.148544,0.558447', '26348103', '26283288', '25882279', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11541282', '魔力麦克2', '剧情', '麦克（查宁·塔图姆 Channing Tatum 饰）在脱衣舞男生涯的颠峰之时，急流勇退，远离了舞男的生活。后来，其他的舞男同伴也准备洗手不干。不过在收山之前，他们想要在美特尔海滩，展开一场盛大的告别秀，并邀请“魔力麦克”重出江湖。麦克与伙伴们上路，中途在小镇杰克逊维尔及萨凡纳短暂停留，与老友重聚，也结识了许多新朋友，还学到新的舞技。在他们的最后一场大秀中，绝对会有让人大开眼界的劲爆演出……', '查宁·塔图姆', '格里高利·雅各布', 5.9, 10340, 'tt2268016', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2251269074.jpg', 5.7, 24.6, 47.1, 16.1, 6.6, '-0.023365,-0.322156,-0.601177,0.379442,-0.151988,-0.407776,0.718476,0.221804,-0.374800,-0.096895,0.236318,1.029269,-0.504645,0.134868,0.550366,-0.314149,-0.472009,-0.808774,0.186863,-0.182159,-0.007376,-0.261749,-0.321463,-0.015833,-0.241740,-0.527762,0.442370,-0.000667,-0.035598,0.631618,0.297785,-0.247399,-0.055322,0.503793,-0.266944,0.062227,0.251779,0.055616,-0.637783,0.233256,-0.002152,-0.112037,-0.277715,-0.022143,0.243703,0.147922,0.705286,-0.036449,0.129423,0.167745,0.082629,-0.028666,0.141803,0.094434,0.203015,-0.246632,0.281763,0.152591,-0.001341,0.159569,-0.054296,-0.178042,-0.738774,0.426293,0.084640,-0.073518,-0.488800,0.699451,0.186636,0.014177,-0.101761,-0.266328,0.077897,0.522347,0.324530,0.079654,0.005416,0.048682,-0.178128,0.294691,1.026541,0.270578,-0.136739,0.417796,0.210629,-0.476068,-0.241331,-0.035310,-0.418679,-0.045485,0.505810,0.050515,-0.274925,0.038524,-0.864305,-0.005262,-0.264539,-0.065725,0.112863,-0.379186,0.084196,-1.176723,0.010914,-0.206182,-0.280985,0.038388,0.217452,-0.168927,0.705393,-0.939616,0.187570,0.653017,0.185483,-0.317385,0.569718,0.116446,0.229421,0.046731,-0.266205,0.123665,0.031561,0.419852,0.187929,0.535221,-0.091922,-0.115218,-0.467084,0.478729', '3147969', '3178770', '1303333', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11577177', '实习大叔', '喜剧', '比利（文斯·沃恩 Vince Vaughn 饰）和尼克（欧文·威尔逊 Owen Wilson 饰）是相识多年的同事兼好友，两人勤勤恳恳的工作，为公司立下了诸多的汗马功劳。然而，某一天，两人却突然被告知，公司倒闭了，就这样，在毫无征兆的情况下，两人中年男人失业了。一次偶然中，比利和尼克得到了一个在谷歌公司做实习生的机会，迫于现实的无奈和压力，两人只得“重新来过”。然而，这份实习生的工作也并非万无一失，在经过了一段时间的学习之后，比利和尼克必须参加一个通过率仅为5%的考试，合格后才能够留下成为正式工。面对从未接触过的全新领域，一对难兄难弟能够化险为夷吗？©豆瓣', '欧文·威尔逊', '肖恩·利维', 6.5, 11257, 'tt2234155', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1921688843.jpg', 2.5, 11.9, 50.5, 27.4, 7.8, '0.243046,-0.040323,-0.620044,0.562934,-0.128240,-0.672880,0.457669,0.141440,-0.752571,-0.395916,0.080644,0.888925,-0.313524,0.324600,0.304753,-0.377583,-0.220944,-0.883680,-0.039941,-0.247946,-0.302629,-0.512066,-0.338434,-0.187499,-0.255546,-0.240327,0.707465,-0.101647,0.031373,0.493148,0.244737,0.191852,0.085484,0.595102,-0.198779,-0.120799,0.447266,0.174445,-0.597103,0.362783,0.158295,-0.200874,-0.249213,0.035199,0.323492,0.337899,0.345089,-0.110298,-0.393818,-0.033231,0.327726,-0.045249,-0.030380,0.029068,0.469798,0.178450,0.414340,0.508271,-0.283789,-0.006092,0.034568,-0.246579,-0.922047,-0.099029,-0.090965,0.047036,-0.621208,0.595598,-0.014778,-0.210611,-0.053072,-0.403784,0.034712,0.691989,0.495408,0.278716,-0.247005,0.106196,-0.384292,0.167780,0.669657,0.030516,-0.479755,0.438835,0.014820,-0.422474,-0.041298,-0.200500,-0.288712,0.178136,0.358454,0.246307,-0.247452,-0.007930,-0.567197,-0.020837,-0.557553,-0.410682,-0.122310,-0.560710,-0.004542,-0.710118,-0.043566,-0.278076,-0.586044,0.227062,0.095454,-0.421523,0.483161,-1.131579,0.147337,0.361854,0.258352,-0.384270,0.683981,0.093495,0.362076,-0.186158,0.227715,-0.166609,-0.054460,0.431401,0.263044,0.344581,0.113366,-0.022576,-0.218668,0.335361', '30345227', '1793491', '1986338', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11580479', '危机解密', '剧情', '本尼迪克特·康伯巴奇饰演“维基解密”创始人朱利安·保罗·阿桑奇（Julian Paul Assange）。维基解密是一个大型文档泄露及分析网站，曾经在2010年公开了多达9.2万份的驻阿美军秘密文件而引起轩然大波。康伯巴奇将要饰演的朱利安·保罗·阿桑奇是网站的董事与发言人，曾主修过物理、数学，做过程序员和黑客。阿桑奇本人和网站一样都备受争议，他曾经因为解密工作获得过多项荣誉，也曾收到过国际刑警组织的逮捕令。2010年阿桑奇因涉嫌在瑞典强奸及性侵犯2名女性被通缉，2010年12月7日他向伦敦警方自首，随即被押送到威斯敏斯特地方法院出席引渡聆讯，保释申请被驳回。2012年8月16日，阿桑奇获厄瓜多尔政治庇护。', '本尼迪克特·康伯巴奇', '比尔·康顿', 6.5, 8484, 'tt1837703', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2097787328.jpg', 1.6, 10.9, 53.5, 26.7, 7.4, '0.156898,-0.346990,-0.402296,0.536271,0.067328,0.150735,0.144098,-0.160341,-0.878582,-0.225487,-0.038070,0.582722,-0.543645,0.495259,0.695307,-0.111674,-0.300404,-0.904157,-0.067277,-0.681334,-0.170745,-0.746942,-0.088824,-0.338952,-0.012133,-0.673552,0.767822,-0.301877,-0.165180,0.315871,0.220197,0.344949,-0.150442,0.313299,-0.028689,-0.063674,0.338788,-0.153608,-0.406294,0.391654,-0.119089,-0.517550,-0.222739,-0.247922,0.206893,0.572170,0.148088,-0.265299,-0.163289,-0.218063,0.633743,-0.492277,-0.088910,0.057743,0.532829,0.379517,0.134578,0.944367,-0.215031,-0.201673,0.025203,-0.430961,-0.509239,-0.189475,-0.127660,0.184081,-0.324381,0.415825,-0.877841,0.398527,-0.324173,-0.174979,-0.057497,0.194777,-0.213439,0.363790,0.127758,0.064288,-0.321458,0.737062,0.390379,-0.002108,-0.349236,-0.310379,0.041614,-0.518771,0.116233,-0.418411,-0.086580,0.401194,0.194531,-0.080023,-0.068303,0.363454,-0.441374,-0.182353,-0.374931,-0.541197,0.250901,-0.226412,-0.086356,-1.003810,-0.377644,0.032655,-0.090079,0.177338,0.239274,-0.248383,0.542769,-0.788746,0.582363,0.569289,0.482544,-0.640722,0.676458,0.287384,-0.253448,-0.059844,-0.161588,0.331359,0.460957,0.489215,-0.008422,-0.171286,0.404643,-0.657211,0.097504,0.018045', '3003137', '26990609', '25723905', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11584016', '与神同行：罪与罚', '剧情', '阴间有法，所有亡者在死后的49天内都要经过七次审判——分别在杀人狱、懒惰狱、欺骗狱、不义狱、背叛狱、暴力狱、天伦狱中进行，只有通过了七次审判宣告无罪的亡者，才有获得新生的机会。消防员金子洪在一场火灾当中为了救一名女孩而不幸牺牲。地狱使者解怨脉和德春出现在了金子洪的面前。尽管金子洪无法相信自己的死亡，却被德春一脸严肃地告知自己既是亡者、又是贵人。在通往地狱的入口，金子洪遇到了在初军门等着自己的另一位使者江林。他掌管着解怨脉和德春两位使者，同时也将在子洪即将接受的七次审判中为子洪进行辩护。原来倘若阎罗大王在1000年内令49位亡者得以往生，三位使者也可以重新投胎至凡间。他们相信第48位亡者——19年来出现的这位贵人金子洪是可以顺利重获新生的。然而在各地狱里，金子洪的过去接二连三地出现，原来这位贵人也依然有“不能说的秘密”。', '河正宇', '金容华', 7.8, 225586, 'tt7160070', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2500130777.jpg', 0.8, 3.5, 25.2, 45.1, 25.3, '-0.139467,0.271285,-0.673598,0.392470,-0.294494,-0.176780,0.601894,0.071667,-0.434109,0.006113,0.426886,0.604163,-0.123942,0.198973,0.523156,-0.284739,-0.121464,-0.466726,-0.367358,-0.273764,-0.669076,-0.263366,-0.082022,-0.067437,-0.154989,-0.328862,0.346599,0.294143,0.049962,-0.017376,0.361644,0.484834,-0.262974,0.387719,-0.447162,-0.027656,-0.110723,0.273279,-0.221126,0.364726,-0.029241,-0.410043,-0.339688,0.178165,0.001800,0.242783,0.294768,-0.755845,-0.105896,0.015418,0.288879,-0.354074,-0.174954,0.312507,0.401194,0.039671,-0.041332,0.507498,-0.048136,0.275388,-0.036670,-0.077696,-0.975536,-0.213384,0.098443,0.262031,-0.476687,0.398042,0.202267,0.130035,-0.018887,-0.134116,0.399808,0.284819,0.117664,0.316932,-0.428516,-0.217795,-0.707330,0.101847,0.610007,0.001672,-0.253577,-0.187313,0.211857,-0.653630,0.080421,-0.037921,-0.284142,0.185340,0.475009,0.099655,-0.096976,0.392701,-0.511979,-0.235753,-0.520686,-0.043073,-0.290642,0.008884,-0.044002,-0.368325,0.135463,-0.148576,-0.065127,0.327083,0.300780,-0.440040,0.592228,-0.684064,0.337490,0.404987,0.464685,-0.388555,0.671714,0.244831,0.113550,-0.229038,-0.162488,0.101438,0.375321,0.634496,0.317237,0.313259,-0.046323,0.084086,-0.242921,0.236401', '1793491', '30163500', '3755531', '19975090');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11584019', '海洋之歌', '动画', '在一个风景如画的海中小岛，小男孩本（大卫·罗尔 David Rawle 配音）和怀有身孕的母亲布罗娜（丽莎·汉尼根 Lisa Hannigan 配音）渡过了最后一个快乐而难忘的夜晚。不久后，妹妹西尔莎（露西·奥康奈尔 Lucy O''Connell 配音）出生，而母亲却撒手人寰。转眼过了六年，他们的父亲康纳（布莱丹·格里森 Brendan Gleeson 配音）始终未从丧妻之痛中走出，而充满幻想的西尔莎偶然发现妈妈留下的贝笛，结果险些溺毙大海，最终导致奶奶强制性地将两个孩子带离这座小岛。兄妹俩无法适应城市的生活，他们在街道游走的时候，意外遭遇了三个奇怪的小精灵。他们希望借助“海豹女”西尔莎的歌声回到故乡，神奇的冒险就此展开……本片根据爱尔兰的民间传说改编。©豆瓣', '大卫·罗尔', '汤姆·摩尔', 8.8, 161974, 'tt1865505', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2360910487.jpg', 0.2, 0.7, 9.6, 37.8, 51.7, '0.009039,-0.012884,-0.701037,0.540931,-0.157450,-0.288446,0.844361,0.022288,-0.658869,-0.221489,0.247658,1.040669,-0.078026,0.409998,0.374018,0.189833,-0.464055,-0.431359,0.207484,-0.171457,-0.292847,-0.400346,-0.075310,-0.212561,0.055316,-0.419194,0.541621,0.005122,0.081342,0.588997,-0.192891,-0.072519,-0.394251,0.340425,0.069903,0.498951,0.091032,0.031602,-0.228637,0.307209,0.037841,0.161411,-0.325794,-0.071603,0.184288,0.318385,0.995546,-0.489919,0.093897,-0.132136,0.264159,-0.069155,-0.030188,0.160771,-0.137510,-0.163677,0.266112,0.053471,-0.288945,-0.243238,0.097736,-0.142180,-0.450663,0.332736,0.005264,0.138867,-0.317382,0.332370,0.003145,-0.024305,0.218590,-0.459127,-0.022340,0.586666,0.366423,0.519275,-0.348653,0.056525,-0.349679,0.070166,0.638659,-0.281547,-0.493797,0.485643,-0.226739,-0.330491,0.079149,0.063690,-0.556115,0.077589,0.540900,0.194581,-0.537181,0.352141,-0.691686,-0.093756,-0.448178,-0.173486,-0.019417,-0.317152,-0.419629,-0.485931,0.135707,-0.111096,-0.228991,-0.164227,-0.314506,-0.116293,0.650347,-0.756545,0.537547,0.487031,0.283959,-0.119349,0.606482,0.008392,0.392341,-0.105300,0.050617,0.974294,-0.023212,0.255020,0.203764,0.310455,-0.319367,0.073316,-0.677209,0.300113', '1309194', '1299433', '35161768', '1844413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11584024', '我们仍未知道那天所看见的花的名字 剧场版', '动画', '童年时期的一个盛夏，女孩子面码（茅野爱衣 配音）死于意外。这件突如其来的死亡事件，深深刺痛了她的五个儿时玩伴——仁太、安鸣、雪集、鹤见子以及波波。六人组成的秘密基地“超和平Busters”就此解散，活着的五人带着无法弥补的创伤各自疏远各自长大。十年后，面码居然以一种只有仁太能看见的形式，带着一个想要实现的愿望回来了。本剧场版从面码已经在五个伙伴的帮助下“成佛”讲起，在面码完成心愿消失一年后，仁太他们五人重聚，各自给面码写信，回忆去年夏天发生在“超和平Busters”六人身上的奇迹。©豆瓣', '入野自由', '长井龙雪', 8.6, 37591, 'tt2323836', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1971347181.jpg', 0.5, 1.7, 12.5, 35.7, 49.6, '0.086493,0.146386,-0.589047,0.384042,-0.079872,-0.388267,0.684090,0.010034,-0.235701,-0.292578,0.114673,0.806390,-0.173441,0.475410,0.361047,-0.304143,-0.194580,-0.547297,-0.171764,-0.288785,-0.307162,-0.387962,0.024468,-0.007259,-0.199351,-0.268880,0.736394,0.215286,0.021218,0.401731,0.265624,0.256044,-0.495927,0.163097,-0.226027,0.208359,-0.162546,0.121135,-0.447554,0.182933,-0.098682,-0.100013,-0.142013,0.129600,-0.292821,-0.001806,0.952605,-0.285687,-0.332965,-0.135339,0.192353,-0.240784,-0.336109,0.003368,0.100577,0.114719,0.187000,0.219377,-0.188999,0.042100,0.022306,-0.026649,-0.638931,0.025154,-0.003141,0.276923,-0.436413,0.507553,-0.067954,-0.028164,0.419004,-0.395782,0.096500,0.734912,-0.012239,0.524636,-0.775107,0.320137,-0.486501,0.051874,0.823622,-0.281110,-0.287841,0.212899,-0.060625,-0.287491,-0.090806,0.049448,-0.204500,0.138196,0.344954,0.330841,-0.195910,0.157641,-0.692708,-0.144523,-0.060167,-0.262188,0.186342,-0.493570,-0.046383,-0.629247,-0.041851,0.048392,-0.403637,0.402345,0.067009,-0.455464,0.764540,-0.656898,0.428393,0.264642,0.035100,-0.285580,0.332072,0.123872,0.366318,-0.247666,0.286273,0.272649,-0.081379,0.266904,0.399046,0.317102,-0.150779,0.297551,-0.578944,0.400956', '3811356', '5364978', '21619567', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11589036', '功夫熊猫3', '喜剧', '当熊猫阿宝（杰克·布莱克 Jack Black 配音）为成为真正的神龙大侠做准备的时候，他的生父——熊猫李山（布莱恩·科兰斯顿 Bryan Cranston 配音）突然到访。与此同时，拥有神秘力量的反派天煞（J·K·西蒙斯 J.K. Simmons 配音）登场，妄图制服 所有高手，统治武林。相传在与世隔绝的熊猫村有着对抗天煞的力量，为了拯救苍生，阿宝与父亲踏上了归途，而阿宝的好伙伴悍娇虎（安吉丽娜·朱莉 Angelina Jolie 配音）、金猴（成龙 配音）、灵蛇（刘玉玲 Lucy Liu 配音）、螳螂（塞斯·罗根 Seth Rogen 配音）则一同拖延天煞，阿宝不仅肩负着成为真正的熊猫大侠的使命，还要让村民美美（凯特·哈德森 Kate Hudson 配音）等新伙伴练就新功夫，继承乌龟大师（兰德尔·杜克·金 Randall Duk Kim 配音）的遗志，共同抵挡天煞。', '杰克·布莱克', '吕寅荣', 7.7, 343031, 'tt2267968', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2306653420.jpg', 0.4, 2.4, 28.2, 47.7, 21.4, '-0.182427,-0.154351,-0.110747,0.392002,0.017698,-0.549669,0.172892,0.223170,-0.195391,-0.510093,0.506859,0.612072,0.061961,-0.062309,0.270196,-0.204452,-0.134650,-0.409339,0.095254,0.106073,0.116608,-0.067279,-0.394399,-0.023138,0.066587,-0.406900,0.679590,-0.362838,-0.058956,0.219264,0.243501,0.206255,-0.212841,-0.103517,-0.063059,0.057379,0.262896,-0.201185,-0.403892,0.275374,-0.050940,0.184566,0.136475,0.191198,-0.156280,0.018203,0.281956,-0.547989,0.294472,-0.482696,0.059190,-0.102512,-0.032769,-0.137382,0.122479,0.035795,0.165498,0.142085,0.248568,-0.072433,-0.087948,-0.297571,-0.851609,0.091171,0.085061,0.334885,-0.119107,0.128410,-0.059782,0.094801,0.397812,-0.490339,-0.078820,0.206676,0.470365,0.349978,-0.063531,0.441734,-0.077909,0.357399,0.442539,-0.276360,0.124137,0.183576,0.096891,-0.214007,0.150593,-0.268990,-0.295847,-0.205292,0.404354,0.062607,0.235179,0.307355,-0.580564,-0.272549,-0.121584,0.022317,0.021522,-0.171325,0.123804,-0.793076,-0.028716,0.019596,0.348056,-0.290261,0.249275,-0.387066,0.909677,-0.940269,0.252272,0.381928,0.253479,-0.219469,0.296780,-0.245094,0.391021,-0.261116,-0.075001,0.145743,0.213164,0.500824,0.219053,0.100224,0.075559,0.000924,-0.159318,0.262834', '2369613', '27