INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11594933', '一座城池', '剧情', '因宿舍电脑中毒瘫痪，身为大学生的“我”（房祖名 饰）结识了擅长修电脑的学长健叔（王太利 饰）。在此之后我们萌生创业念头，只不过剑走偏锋干起歪门邪道的勾当，最终遭到学校开除的惩罚。我和健叔游手好闲，在尝试过各种赚钱方法后都碰壁收场，接着我们受雇小学同学帮打群架，双方混战期间一人血染沙场。这个场面令我们吓破了胆，两人夺路狂奔，担心惹上命案干脆逃往另一个城市躲避风头。在那里，健叔接二连三受伤，像一个半残疾。我们还认识了人有点儿“二”却很仗义的王超以及艺术专业神经病阿雄；我在梦中经常被受到政府审讯的噩梦惊扰。一年的逃亡生涯，恍若一场幻梦……本片根据韩寒的同名原作改编。©豆瓣', '房祖名', '孙渤涵', 5.4, 26940, 'tt12059898', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2131540282.jpg', 13.3, 29.3, 38.5, 13.2, 5.7, '0.103314,-0.412365,-0.337559,0.044072,-0.047680,-0.069073,0.339897,0.125046,-0.332484,-0.289096,0.107339,0.639317,-0.150062,0.122544,0.022263,-0.476754,-0.192490,-0.486597,-0.003653,0.043560,-0.106229,-0.179286,0.042341,-0.134579,-0.113276,-0.138669,0.218441,0.033146,-0.452396,0.526629,0.218879,0.209282,-0.312736,0.194561,0.083711,0.089598,0.027113,0.245408,-0.146843,0.066755,-0.173791,-0.331549,-0.095834,-0.024416,0.145122,0.342055,0.541606,0.250322,-0.066157,-0.162422,0.294862,-0.312123,-0.337253,-0.032072,0.361082,-0.001070,0.173075,0.089234,0.003511,0.073804,-0.064320,-0.026795,-0.588628,0.013746,0.091331,-0.159825,-0.568313,0.369715,0.155997,0.080092,-0.075551,-0.036557,0.108705,0.171720,0.301933,0.177347,-0.082931,0.085566,-0.395638,0.331606,0.692006,-0.084922,-0.251842,0.222034,0.223360,-0.251626,-0.080956,-0.367141,-0.231350,-0.018030,0.229302,-0.440844,-0.376181,0.085984,-0.465428,0.014593,-0.102293,-0.018606,-0.290993,-0.114870,-0.055653,-0.529828,0.191521,-0.072404,-0.377500,-0.076797,-0.073905,-0.110577,0.337150,-0.609601,0.132439,0.613441,0.125606,-0.665685,0.423059,0.289793,0.037018,-0.004846,-0.019221,0.024688,0.147928,0.355707,0.090810,0.113174,-0.048141,-0.111816,-0.415888,0.153674', '25908042', '26678784', '1308035', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11598977', '叶问3', '剧情', '已在香港立足开馆的叶问（甄子丹 饰）与太太张永成（熊黛林 饰）平静地生活，不料小儿子叶正就读的小学发生了流氓滋扰事件，参与闹事的正是田傲山（梁家仁 饰）昔日的徒弟马鲸笙（谭耀文 饰）。于是叶问带领徒弟徐力（张继聪 饰）等人保护了黄老师（吴千语 饰）、校长（刘以达 饰）以及众小学生，并结识了同样是永春传人的车夫张天志（张晋 饰），二人惺惺相惜。可是事件却没有止步于此，马鲸笙的老板（迈克.泰森 饰）才是幕后黑手，探长肥波（郑则仕 饰）也卷入了其中，与此同时，张天志向叶问发起了谁是“正宗永春”的挑战，叶问该如何应战？©豆瓣', '甄子丹', '叶伟信', 6.7, 157192, 'tt2888046', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2322954776.jpg', 1.9, 10.6, 49.9, 27.2, 10.3, '0.164217,-0.151794,-0.257559,0.272538,-0.038616,-0.328333,0.136550,0.475449,-0.566221,-0.392238,0.544244,0.320122,0.002023,0.008059,0.080428,-0.229865,-0.138389,-0.645750,0.079455,-0.005716,-0.045834,-0.266122,-0.018048,-0.016786,-0.083857,-0.107297,0.311526,0.042368,-0.266668,0.407337,0.636451,0.442401,-0.284729,0.340984,-0.154444,0.065809,0.225000,0.233012,-0.488644,-0.024122,-0.195444,-0.423358,-0.496621,0.052841,0.083111,0.450233,0.341498,-0.067731,-0.204135,-0.189667,0.111156,-0.228662,-0.147195,0.084369,0.412442,0.024758,0.223516,0.294630,-0.003846,0.169251,0.024981,0.118719,-0.174458,0.168954,0.468188,0.284249,-0.316965,0.361506,-0.151940,-0.322027,-0.215524,-0.177321,0.099309,0.157087,0.077419,0.031532,0.220770,-0.066106,-0.329598,0.348041,0.437423,-0.019145,0.298863,0.129587,0.274939,-0.506693,-0.038298,-0.007425,-0.294653,0.155215,0.252873,-0.166734,0.139640,0.126148,-0.437959,0.009532,-0.223293,0.189841,-0.118780,-0.209417,0.152705,-0.636281,0.127747,-0.412763,-0.050283,-0.100325,0.134234,-0.110353,0.615262,-0.701631,0.025435,-0.043012,0.250965,-0.241802,0.442050,0.066657,-0.103598,-0.283880,-0.074691,-0.083747,0.055053,0.059660,-0.125494,0.266248,0.206812,-0.452852,0.073107,0.014471', '1316589', '25723905', '3230460', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11599155', '阿嬷的梦中情人', '喜剧', '台语片曾经有过风光的年代，当时的电影几乎都在台北北投取景，所以人称北投为“台湾好莱坞”。八年级生小婕（李亦捷 饰），始终不相信台语片有过这么美好的时期，但阿公刘奇生（龙劭华 饰）总是一脸骄傲的说：“阿公我可是当时最红的王牌大编剧”……对于这件事，小婕始终存疑。小婕有个 得了失智症的阿嬷（沈海蓉 饰），病情日益严重，竟宣称自己是万宝龙的太太……“万宝龙”是当年台语片时代最红的小生。小婕不解阿嬷为何总是对此人念念不忘，于是，阿公开始跟她讲起一段当年发生在“台湾好莱坞”的Love Story……1969年，电影《七号间谍》上映。观众大排长龙，争睹随片登台的万宝龙（王柏杰 饰）风釆；当时正陷入创作低潮的奇生（蓝正龙 饰），在后台邂逅了一个翻墙进来偷看电影的女孩——蒋美月（安心亚 饰）。美月为了追星，跷家北上，一个因缘际会进入剧组，当起了临时演员；没多久，奇生便被女孩古灵精怪的个性所吸引；另一方面，他却无法回避高傲女明星金月凤（天心 饰）不停付出的浓烈情感……《七号间谍》全台湾大卖，续集趁胜追击，没料开拍没多久，导演竟在片场猝逝！老板遂要怀有导演梦的奇生救火，而他与美月的感情也有了进一步的发展；这时，金月凤却宣称自己有了奇生的小孩……面对一部多灾多难的电影，以及宛如电影情节般的曲折恋情，奇生究竟能否力挽狂澜？而阿嬷的梦中情人倒底是万宝龙，还是阿公？数十年后的小婕即将从阿公口中，得到一个埋藏已久的动人答案……', '蓝正龙', '萧力修', 7.2, 6639, 'tt3068650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1858380963.jpg', 1.7, 6.9, 36.8, 39.3, 15.3, '-0.020247,-0.019261,-0.455491,0.452219,0.189429,-0.161856,0.506074,-0.006331,-0.469878,-0.343073,0.198194,0.551056,-0.358598,0.225970,0.155579,0.170912,-0.191921,-0.521041,-0.068354,-0.076376,0.195572,-0.145199,-0.278939,0.038511,-0.085511,-0.124483,0.625489,0.249053,-0.284384,0.224301,0.316836,0.153632,-0.135947,0.303296,0.028984,0.165461,-0.009149,0.312129,-0.331957,0.164728,0.129799,-0.394414,-0.319465,0.179297,-0.069227,0.392657,0.382650,-0.296208,-0.217461,0.134900,0.560109,-0.132717,-0.187383,-0.012449,0.228847,0.092992,0.322350,0.189217,-0.120642,0.113499,-0.127001,-0.141542,-0.557579,0.155884,0.196441,0.288498,-0.354756,0.270946,-0.171190,0.110947,0.185754,-0.219100,0.188529,0.150838,0.274452,0.260292,-0.284420,0.180853,-0.430600,0.454814,0.655018,0.172549,-0.061284,0.420691,-0.044705,-0.398433,-0.095868,-0.147896,-0.473680,0.238371,0.158779,-0.101582,-0.100871,0.110125,-0.330589,-0.017661,-0.035574,-0.070112,0.007335,-0.219405,-0.201807,-0.425670,-0.102009,-0.478814,0.043788,-0.162314,0.104108,-0.253075,0.778471,-0.668400,0.151726,0.375923,0.190699,-0.475693,0.610771,0.154213,-0.225488,-0.141417,-0.158296,0.187824,-0.220515,0.037384,0.001353,0.190671,0.037868,-0.355436,-0.169058,0.280202', '27602116', '1908036', '4301278', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11599239', '黑暗天际', '科幻', '美国一处理想中的郊外社区，贝瑞特一家生活于此。女主人莱丝（凯丽·拉塞尔 Keri Russell 饰）美丽端庄，是一名干练的地产中介；男主人丹尼尔（乔什·汉弥尔顿 Josh Hamilton 饰）则正处在事业的瓶颈期，心中充满焦灼和不安。两个儿子杰西（达科塔·高尤 Dakota Goyo 饰）和山姆（卡丹·洛吉特 Kadan Rockett 饰）顽皮可爱，感情笃深。某个夜晚，贝瑞特家通往院子的拉门被打开，冰箱内的食物被人弄得乱七八糟。似乎从这一天起，种种异状便接连在这户人家出现。小山姆声称有外星人来到家中，但贝瑞特夫妇以及保全人员似乎却将家中一系列事件当作孩子的恶作剧。怪事愈演愈烈，远远超出孩子所能操控的范畴，真相究竟如何……©豆瓣', '凯丽·拉塞尔', '斯科特·查尔斯·斯图瓦特', 6, 5904, 'tt2387433', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1872382389.jpg', 4.2, 18.7, 53.1, 19.1, 4.8, '0.314527,0.110315,-0.578408,0.342002,0.001857,-0.170807,0.736061,0.163012,-0.655551,-0.491438,0.089835,0.517259,-0.300013,0.500810,0.131796,0.028863,-0.267409,-0.455690,-0.078373,-0.269271,-0.161975,-0.356514,-0.400201,-0.301964,-0.084935,-0.155676,0.227419,0.108601,-0.104044,0.240776,0.172284,0.433861,-0.480696,0.344437,-0.124170,0.106158,0.323021,-0.031022,-0.206858,-0.090108,-0.011450,0.037811,-0.143876,0.078707,0.121475,0.235277,0.683487,-0.251300,-0.252773,-0.056847,0.327529,0.233865,0.057165,0.254454,0.371014,-0.128775,0.161406,-0.011381,-0.240368,-0.010363,0.249159,-0.217972,-0.372489,-0.016400,0.034788,-0.057948,-0.349847,0.141645,-0.031294,-0.079274,0.122460,-0.361815,0.078465,0.186286,0.248179,0.628280,-0.144434,0.150685,-0.725470,-0.139307,0.410576,0.169158,-0.057391,0.267640,-0.382363,-0.392675,-0.157588,-0.131498,-0.531534,-0.125441,0.439783,0.085043,0.114347,0.370214,-0.343572,0.058487,-0.407296,0.009534,0.018114,-0.101023,-0.347753,-0.615113,0.087153,-0.267944,-0.292408,0.114854,0.046649,-0.099003,0.471909,-0.518146,0.279976,0.209033,0.065561,-0.229879,0.502207,-0.308902,0.360631,-0.231558,-0.279299,0.283437,0.073414,-0.051155,-0.028781,0.260320,-0.410286,-0.148120,-0.315289,0.412050', '10466639', '1296534', '1428054', '1295674');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11600078', '目击者之追凶', '悬疑', '冲劲十足、富有野心的社会线记者小齐，在报导一则事故车还魂新闻时，意外发现9年前一宗肇事逃逸命案并不单纯，虽然提案不被长官邱哥重视，但相信直觉的小齐找上菜鸟警员阿纬帮忙，并说服女主管Maggie连手调查当年的真相。当小齐、Maggie 好不容易找到命案中唯一生还的受害者徐爱婷，并取得采访同意后 ，徐爱婷却无故失踪了…到底九年前被隐瞒的真相是什么？', '庄凯勋', '程伟豪', 8.2, 172962, 'tt5576318', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494647817.jpg', 0.4, 1.3, 15.2, 52.4, 30.7, '0.290958,0.044391,-0.468929,0.044242,-0.045340,-0.000867,0.295490,-0.310661,-0.811164,-0.576884,-0.182257,0.358474,-0.183403,-0.077173,-0.009847,-0.046804,-0.347037,-0.452767,0.359941,-0.111667,-0.330785,-0.717302,0.009957,-0.262173,0.045944,0.163240,0.586750,0.447535,-0.308920,0.458333,0.353409,0.199475,-0.247696,0.602053,0.281142,-0.014177,0.357247,0.353098,-0.072123,0.111773,0.040056,-0.462472,0.131370,0.448573,0.069369,0.657382,-0.029912,-0.133125,-0.598958,0.124862,0.330339,-0.474828,0.008902,0.075335,0.551073,0.175449,0.229951,0.587231,0.065324,-0.164400,-0.259144,0.209670,-0.615125,-0.084788,0.123286,0.341711,-0.440372,0.201533,-0.209040,-0.099296,-0.192739,0.007133,0.407534,0.481178,0.285918,-0.141775,-0.122008,0.087897,-0.523330,0.013078,0.613678,-0.069044,0.014872,0.437669,-0.057363,-0.617815,-0.063984,-0.078955,-0.061048,0.823785,-0.025704,0.154561,-0.412014,0.151552,0.107846,-0.287487,-0.419721,0.270728,-0.262493,-0.409986,-0.010989,-0.275829,-0.142716,0.172498,-0.336973,-0.228821,0.069931,-0.319759,0.227445,-0.650257,0.121415,0.630140,0.235692,-0.670767,0.469149,0.257175,-0.213211,-0.428646,-0.142099,0.153623,0.349938,0.283107,-0.317764,-0.196984,0.269266,-0.936170,-0.093955,-0.162013', '1451895', '1308655', '35073886', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11601131', '家园防线', '动作', '布洛克（杰森·斯坦森 Jason Statham 饰）的灰暗过往令他不得不携家带口过起了离群索居隐姓埋名的生活，和从前经历的大风大浪相比，如今和家人待在一起的平静日子显得尤为可贵。然而，现实却不愿轻易放过布洛克，一场意外的冲突让毒枭盖特（詹姆斯·弗兰科 James Franco 饰）在无意之中发现了布洛克的真实身份，布洛克好不容易构筑起的安稳即将毁于一旦。盖瑞找来了前女友雪莉（薇诺娜·瑞德 Winona Ryder 饰），在小镇之中散布着搅乱人心的流言蜚语，一时间，矛头全部指向了布洛克一家人，此时唯一信任和支持布洛克的，只有布洛克的女儿和她的老师。与此同时，盖瑞此举亦将自己推上了一条不归路。©豆瓣', '杰森·斯坦森', '加里·弗莱德', 6.5, 44995, 'tt2312718', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2172920443.jpg', 1.4, 11.7, 55.2, 23.4, 8.3, '0.155502,0.028983,-0.761694,0.461567,0.017149,-0.369559,0.846682,0.279946,-0.800026,-0.041605,0.063104,0.695471,-0.000638,0.017743,0.446270,-0.019036,-0.387264,-0.536877,-0.073765,-0.242351,-0.022942,-0.623453,-0.496869,-0.300454,-0.202605,-0.491741,0.446973,-0.039082,-0.090356,0.667649,0.355698,0.354964,-0.048436,0.436722,-0.006776,0.129876,-0.008037,0.225606,-0.662759,0.068697,0.001666,-0.227530,-0.333786,0.425734,0.057766,0.360200,0.556898,-0.250395,-0.261028,0.161056,0.267959,-0.197018,-0.004532,0.111645,0.158067,-0.116311,0.082985,0.330859,-0.357332,-0.046481,0.293121,-0.001000,-0.650547,0.111717,0.228139,0.173815,-0.636836,0.668117,-0.109796,-0.190956,-0.011541,-0.278154,0.370263,0.424094,0.230485,0.205151,-0.041413,0.036695,-0.334726,0.220684,0.785944,0.032205,-0.252789,0.256646,-0.334736,-0.010169,-0.123982,-0.295113,-0.815101,-0.036735,0.396858,0.144954,-0.143507,0.774127,-0.482025,-0.069080,-0.372335,-0.002718,-0.029014,-0.559893,-0.045369,-0.262113,-0.289180,-0.406872,-0.155162,-0.118862,-0.199619,-0.179867,0.529499,-0.685492,0.411918,0.210647,0.186473,-0.159426,0.538348,0.120219,0.336795,-0.097907,-0.035849,0.301750,0.156351,0.416586,0.260005,0.190320,-0.106806,-0.171770,-0.326303,0.534062', '26245360', '3014557', '3111650', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11601132', '旗鼓相当', '剧情', '20世纪80年代初，来自匹兹堡的瑞泽·夏普（西尔维斯特·史泰龙 Sylvester Stallone 饰）和基德·麦克唐（罗伯特·德尼罗 Robert De Niro 饰）上演了两场倾倒世人的经典拳击比赛。但在1984年的赛后不久，如日中天的瑞泽突然宣布退役，并很快花光所有财产，重新变回为了生计而出卖劳动力的普通工人。与之相对，基德也持续下滑，代言各种不入流的广告，靠卖嘴皮子打发时光。2014年的某天，瑞泽当年的经纪人之子小但丁（Mason Mackie 饰）找上门来，邀请他参与某款游戏的制作。谁知在制作现场，瑞泽和不请自来的基德大打出手，二人乱斗的视频在网络上疯传，他们的三十周年纪念之战也重新提上日程。只不过早已过了巅峰状态的二人，能否应对时光的消蚀，并放下心中芥蒂，完成这场迟到的对决……©豆瓣', '罗伯特·德尼罗', '彼得·西格尔', 7.2, 5223, 'tt1661382', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2154445374.jpg', 0.5, 4.7, 42.9, 38.9, 12.9, '0.274060,0.160730,-0.441940,0.257146,0.071507,-0.392752,0.342267,0.133807,-0.204737,-0.240890,0.099129,0.761466,-0.503885,0.062130,0.463052,-0.250053,-0.355376,-0.885972,0.051888,-0.224639,-0.011172,-0.382552,-0.204674,-0.046425,-0.078106,-0.168865,0.693840,-0.189812,-0.136578,0.697123,0.372308,-0.073822,0.090298,0.311951,0.121738,-0.092227,-0.202390,0.127990,-0.496532,0.073260,-0.087189,-0.282774,-0.255792,-0.151207,0.277538,0.408999,0.463133,-0.155003,0.114715,0.065841,0.534758,-0.265705,-0.177840,-0.098508,0.237782,0.113215,0.166265,0.347031,-0.229798,-0.028282,-0.086757,-0.218612,-0.612794,0.068563,-0.069285,0.049350,-0.410434,0.760825,-0.009705,0.339230,-0.222955,-0.221485,0.027641,0.526179,0.227056,0.191245,-0.003629,-0.203693,-0.303273,0.465396,0.344811,-0.042502,-0.234242,0.433077,0.318605,-0.302387,-0.187047,-0.281287,-0.182823,-0.009828,0.272479,0.072742,0.084397,0.364980,-0.823254,0.091290,-0.284353,-0.376277,0.253056,-0.288855,-0.161241,-0.904087,-0.219560,-0.330187,-0.228782,-0.105112,0.362872,-0.376485,0.417957,-0.739405,0.097250,0.279523,0.058961,-0.194858,0.351308,0.076739,0.203821,-0.051250,-0.354192,0.054443,-0.098328,0.415712,-0.024369,0.198877,0.010555,-0.234422,-0.323115,0.473134', '26365262', '25723905', '11541282', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11604102', '暗恋99天', '喜剧', '香港闹市街头，青年秋炳（黄宗泽 饰）和好友大啤（森美 饰）共同经营一辆流动雪糕车，二人耍酷卖帅，无奈生活无比现实，爱神迟迟不曾眷顾生意清淡毫无前途的草根阶级，他们只能望着美女兀自哀叹。楼下小卖铺的女孩菁菁（赵柯 饰）暗恋秋炳，三番五次大献殷勤，只不过对方呆头呆脑，全然不知。某个瓢泼大雨之夜，秋炳来自广州的干妹朱蒂（邓丽欣 饰）前来投奔，谁知却被干哥当作推销人员拍在门外。机灵精怪的朱蒂利用大啤混入房间，从此展开了一女二男的同栖生活。在此过程中，充满了阴差阳错、奇妙有趣的青春故事和爱情小品渐次上演……©豆瓣', '黄宗泽', '火火', 5.7, 9723, 'tt3376596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1832197925.jpg', 7.1, 25.7, 48.8, 13.8, 4.6, '0.061209,0.019221,-0.421563,0.229630,0.087356,0.055695,0.643472,0.558328,-0.340753,-0.009297,0.317076,0.595940,-0.240184,0.084771,0.285292,-0.045011,-0.359486,-0.465835,-0.119163,0.132835,-0.051427,-0.031918,-0.174616,-0.064251,-0.226933,0.052195,0.227087,-0.030661,-0.190602,0.604566,0.376188,0.089365,-0.655553,0.141373,-0.309315,0.157807,0.306016,0.348088,-0.285027,-0.143165,-0.288411,-0.226658,-0.215789,-0.269403,-0.079007,0.189587,0.529379,-0.108601,-0.095013,-0.151683,0.207467,-0.016194,-0.202950,-0.082348,0.196394,0.031126,0.312990,-0.265189,0.099995,-0.293931,0.143254,-0.086909,-0.143867,0.163507,0.046903,-0.078384,-0.187378,0.527942,0.287435,-0.149581,0.163473,-0.217747,-0.065876,-0.107948,0.347589,0.227011,0.007623,0.138655,-0.465931,0.380911,0.168856,0.229047,0.071548,0.556563,-0.261260,-0.144988,0.021065,-0.053037,-0.695158,-0.227688,0.400067,0.002426,-0.200754,0.276850,-0.587315,0.239831,-0.081040,0.008660,0.344666,-0.090869,-0.357954,-0.716780,0.037453,-0.271514,-0.055590,0.309146,0.149160,0.030479,0.638753,-0.604979,0.125510,0.296164,0.102538,-0.255401,0.660500,0.110067,0.044914,-0.072366,-0.312143,0.086582,-0.139649,0.060633,0.107237,0.239419,-0.489283,0.117215,-0.446593,0.054233', '10466639', '1418179', '1394176', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11606328', '霍比特人2：史矛革之战', '动作', '距离孤山越来越近，矮人远征军的道路却变得异常艰险。他们躲过了苍白半兽人的不懈追杀，在幽暗密林前和甘道夫（伊恩·麦凯伦 Ian McKellen 饰）兵分两路，后者前往多尔哥多探寻索伦的动向，而霍比特人比尔博·巴金斯（马丁·弗里曼 Martin John C. Freeman 饰）和矮人们先是遭到巨大蜘蛛的袭击，随后又被精灵王子莱戈拉斯（奥兰多·布鲁姆 Orlando Bloom 饰）及其木精灵同伴捕获。比尔博急中生智，利用魔戒救出伙伴，继而引发了木精灵、半兽人和矮人远征军之间精彩纷呈的三方会战。借助巴德（卢克·伊万斯 Luke Evans 饰）的帮助，疲惫的矮人们暂时落脚长湖镇。近在咫尺的孤山城堡，沉睡在财宝中的巨龙即将醒来……本片根据J.R.R·托尔金的同名原著改编。©豆瓣', '伊恩·麦克莱恩', '彼得·杰克逊', 8.4, 346970, 'tt1170358', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2166784595.jpg', 0.3, 1.2, 14.1, 44.8, 39.6, '0.253433,-0.256463,-0.668085,0.538970,0.564328,-0.378663,0.677966,-0.024644,-0.248123,-0.251291,0.318634,0.592676,-0.079384,-0.284396,0.329499,-0.145003,-0.696208,-0.162502,-0.225154,-0.134116,-0.317557,-0.323537,-0.521370,-0.475645,-0.080399,-0.536951,0.743684,0.175293,-0.057497,0.631901,-0.073737,0.614810,-0.165854,0.043619,0.049066,0.232920,0.204591,-0.450276,-0.159435,0.206441,-0.228646,0.119207,-0.381423,0.144337,0.015907,0.506050,0.825632,-0.717841,0.289899,-0.039949,-0.147597,-0.356603,0.286846,-0.061211,0.593985,-0.334800,-0.180042,0.070037,-0.115451,-0.175279,-0.031430,-0.186918,-0.193191,0.293713,0.114518,0.393435,-0.413765,0.265967,0.020458,0.400560,0.390326,-0.133443,-0.105858,0.401418,0.221132,0.063758,0.342749,-0.126373,-0.195848,-0.208035,0.382461,0.092002,-0.302539,-0.173352,-0.462365,-0.568989,-0.217808,0.043889,-0.311399,-0.270462,0.831371,-0.020868,0.271152,0.751499,-0.969511,-0.092309,-0.543931,-0.077572,-0.117999,-0.105276,-0.312766,-1.022147,0.041337,-0.107588,0.276154,0.226976,0.042146,0.083034,0.425411,-0.456336,0.163327,0.400218,0.486867,0.159471,0.291566,-0.560025,0.176423,-0.120716,-0.100897,0.576928,0.518300,0.145226,0.297741,0.030412,-0.146173,0.057233,-0.416541,0.430135', '21349734', '4706257', '1306809', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11606408', '四月一日灵异事件簿·笼：徒梦', '动画', '这是一家可以实现任何愿望的店，只要委托人愿意付出对等的代价。在命运的安排下，有缘人必然会走进这家店里进行委托。高中生四月一日君寻（福山润 配音），有着异于常人的体质，他可以看到并且吸引各种鬼怪。他身边的好友百目鬼（中井和哉 配音）和小葵（伊藤静 配音）都是特殊能力者。原店主壹原侑子消失后，四月一日君寻便接管了这家店，成为新店主，日复一日地等着侑子回来。 某夜，百目鬼的爷爷出现在店里，委托四月一日帮他实现愿望。四月一日接受委托后，进入了百目鬼的梦境中。在梦境中，四月一日看到百目鬼和自己的种种过往，正面临着黑暗的吞噬。梦境与现实，前世与未来，他看到了自己和身边人之间息息相关的命运。最后，回到现实的四月一日，发现百目鬼静居然来到店里拜访……©豆瓣', '福山润', '水岛努', 9.4, 7173, '四月一日灵异记事簿·笼：徒梦', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2228426934.jpg', 0.2, 0.3, 4.6, 20.5, 74.4, '0.018416,0.354248,-0.422877,0.212703,-0.208603,-0.169492,0.581814,0.138778,-0.442471,-0.433644,-0.111479,0.723280,-0.154257,0.427107,0.462395,0.110793,-0.219745,-0.702627,-0.310880,-0.369835,-0.306465,-0.262716,-0.203578,-0.113868,-0.037608,-0.169799,0.525585,0.318315,0.084108,0.336352,0.118446,0.100481,-0.332800,0.321146,-0.239987,-0.018941,0.093890,0.291556,-0.523485,0.416023,0.047261,-0.169557,-0.209768,0.002814,-0.109252,-0.002808,0.669644,-0.381726,-0.513285,-0.157978,0.317750,-0.080462,-0.123950,0.106763,0.198344,0.225924,0.328671,0.352715,-0.195191,0.011128,-0.158005,0.052849,-0.757696,-0.018640,0.168954,0.073678,-0.300644,0.068833,0.225287,0.218304,0.083340,-0.582865,0.182010,0.386417,0.501378,0.451365,-0.166835,-0.091793,-0.574120,0.016771,0.677935,-0.349404,-0.062268,0.396342,0.112603,-0.355114,-0.005161,0.187288,-0.281414,0.197015,-0.005522,0.540644,-0.336235,0.228835,-0.586488,-0.052712,-0.182716,-0.147675,0.160420,-0.130364,-0.114861,-0.728080,-0.002096,-0.211183,-0.167391,0.184949,0.399020,-0.493044,0.410679,-0.940692,0.505108,0.475390,0.567851,-0.300509,0.858189,-0.118597,0.304974,-0.340071,0.122987,0.081715,0.021103,0.520540,-0.042710,0.171211,0.141395,0.211404,-0.524385,0.489069', '3055049', '2124718', '4301278', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11610281', '敢死队3', '动作', '影片开场，巴尼·罗斯（西尔维斯特·史泰龙 Sylvester Stallone 饰）带领敢死队的老伙计李（杰森·斯坦森 Jason Statham 饰）、贡纳（杜夫·龙格尔 Dolph Lundgren 饰）等人驾驶直升机劫持火车，救出了被囚禁的用刀高手医生（韦斯利·斯奈普斯 Wesley Snipes 饰）。经过短暂的休整，他们奔赴索马里潜入某倒卖军火组织的老巢中执行任务，谁知巴尼发现该组织老大竟然是当年本该死去的敢死队战友康拉德·斯通班克（梅尔·吉布森 Mel Gibson 饰）。一番激烈的交火过后，斯通班克成功逃脱，而敢死队方面则损失惨重。此役过后，不仅军方和敢死队藏着一股怒火，连斯通班克也被彻底激怒，最强的硬汉迎来生死对决……©豆瓣', '西尔维斯特·史泰龙', '帕特里克·休斯', 6.9, 120493, 'tt2333784', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2196328516.jpg', 1.2, 8.1, 48.4, 30.4, 11.8, '-0.084087,-0.061425,-0.724366,0.349015,0.226790,-0.168870,0.469064,-0.135135,-0.416989,-0.244191,0.528589,0.340108,-0.179565,-0.220763,0.534939,-0.195501,-0.389038,-0.658073,-0.130573,0.044471,-0.272595,-0.200587,-0.313886,-0.207055,0.310573,-0.298340,0.589722,0.093283,-0.118696,0.484811,0.294381,0.540256,-0.046037,0.199263,0.218721,0.050613,0.413697,-0.475547,-0.293938,0.192634,-0.224021,-0.082566,-0.056767,-0.143634,0.184350,0.400283,0.574397,-0.190763,0.189125,-0.145160,-0.221189,-0.503226,0.031537,0.017360,0.373868,-0.011452,0.127541,0.122225,0.068542,0.002475,-0.133649,0.016989,-0.577235,0.094343,0.051212,-0.056371,-0.441477,0.164311,-0.347179,0.375629,0.074526,-0.126700,0.112984,0.409233,0.357894,0.151270,0.067078,-0.032183,-0.608286,0.090644,0.606547,-0.501340,0.017460,-0.313206,0.308922,-0.419515,0.196545,-0.442314,0.044810,-0.050486,0.503295,-0.164388,0.223965,0.284008,-0.562032,-0.101232,-0.539197,-0.205625,-0.116794,-0.305891,0.042553,-1.078685,-0.054740,0.062005,-0.030738,0.326671,-0.037289,0.194893,0.373841,-0.442664,0.106615,0.350810,0.048628,-0.175791,0.004733,0.110321,0.201282,-0.095688,-0.017081,0.361057,0.468566,0.239136,0.293946,0.226618,-0.127258,-0.241992,-0.162528,-0.030634', '6517421', '4014397', '2369613', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11610693', '快乐到家', '喜剧', '受众人追捧却独爱宠物狗乐乐“爱狗不爱人”的富家千金乖乖（吴昕 饰），想利用“全球名犬选美大赛”让乐乐扬名立万，请到担任本次大赛评委的知名训犬大师“狗博士”何马（何炅 饰）和宠物美容师韦加斯（李维嘉 饰）出马，将“屌丝狗”乐乐一番包装打造终于麻雀变凤凰，终于在大赛中胜出的乐乐一夜暴富身价飞涨，却不料遭到经常掉链子的两位忍者神偷坡姐（谢娜 饰）和萨嘟嘟（杜海涛 饰）的觊觎。于是五位古灵精怪的爱狗达人赴异国展开一段惊险刺激的夺狗大冒险……©豆瓣', '何炅', '傅华阳', 3.3, 52183, 'tt2764834', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1833981381.jpg', 59.4, 23.1, 12.7, 2, 2.7, '-0.053184,-0.071691,-0.264622,0.326148,0.060896,-0.216068,0.109340,-0.021828,-0.272065,0.017356,0.236928,0.555765,-0.706611,0.228010,0.424646,-0.063612,0.117351,-0.518103,0.083164,0.107336,0.205598,-0.012207,-0.225197,0.096138,0.046468,0.104737,0.388252,-0.166267,-0.197848,0.750585,0.559953,0.052471,-0.002393,-0.032378,-0.161194,0.077808,0.318561,-0.048704,-0.243865,-0.025018,-0.009766,-0.106905,0.067562,-0.038641,0.276268,-0.237815,0.651358,-0.706714,0.203429,-0.169478,0.111699,-0.189722,0.066661,0.022713,0.243903,0.059815,0.316977,-0.071369,0.044849,0.453049,0.344597,-0.243288,-0.199155,0.172365,0.200645,0.126734,-0.108852,0.258986,-0.202106,0.101749,0.113492,-0.108314,-0.080056,-0.054835,0.167417,0.244738,0.124402,0.212145,-0.508159,0.527941,0.325579,0.097036,0.200595,-0.095387,0.122046,-0.640687,0.405540,-0.530714,-0.399409,-0.045990,0.472637,-0.188802,-0.052575,-0.039530,-0.651571,-0.115709,0.075184,-0.153925,0.051202,-0.189319,-0.000638,-0.695212,0.297111,-0.121840,0.169101,-0.015064,0.328088,-0.373139,0.811431,-0.766317,0.246892,0.064912,0.026096,-0.326706,0.531131,-0.159984,0.173594,0.068382,-0.153740,-0.138053,0.146664,0.016799,0.051341,0.258316,0.040895,-0.526609,-0.295953,0.245373', '26365262', '3811356', '25922902', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11610998', '鬼三惊', '恐怖', '《发如血》经营假发店的小美、小蜜两姐妹一向不睦。某夜，小蜜带朋友回店饮酒作乐，放荡不羁的年轻人不仅大讲鬼故事，还拿着小美新收了的一束头发取乐。殊不知头发的主人来自某死者，无畏的青年引火烧身。《阴阳棺》新婚仅一周的年轻夫妻意外死亡，他们的棺木停在位于郊外的豪华别墅内。一名在医院工作的青年应征为死者守灵。青年偶然打开棺木，不觉位女主人的美丽容颜所慑服，而他无意中发现的秘密，无疑引领他走向禁忌的底线和黑暗恐怖。《打卡终》某公司员工白天泡钟点，夜晚赶工骗加班费。为了教训他们，上司凯仁、阿迪扮鬼吓人。整蛊一波接一波，终于发现连异界众生也加入其中……©豆瓣', '阿萍雅·萨库尔加伦苏', '伊萨拉·纳迪', 6.5, 13250, 'tt2563548', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173981092.jpg', 2.2, 11.4, 53.7, 24.7, 8, '0.070293,-0.059817,-0.350342,0.170865,-0.281268,-0.110637,0.831667,0.441393,-0.268504,-0.441526,0.589166,0.306756,-0.117260,0.158559,0.533972,0.024993,-0.062221,-0.279953,-0.189763,-0.123962,-0.265453,0.059445,-0.233188,-0.175863,0.132271,-0.083607,0.399780,0.024363,-0.038888,0.201438,0.192919,0.063491,-0.382286,0.069223,-0.334458,-0.276314,0.047007,-0.001861,-0.047392,0.002455,-0.319081,-0.357919,-0.111086,-0.038217,-0.138700,0.248310,0.686272,-0.111128,-0.312094,-0.002102,0.407225,-0.091048,-0.131698,-0.134721,0.225454,-0.022203,0.413216,0.140444,0.039132,-0.157685,0.069613,-0.146627,-0.389329,0.088047,0.037579,0.018700,-0.128035,0.613194,0.049285,-0.080697,0.199984,-0.138067,0.225793,-0.049476,0.112797,0.417489,0.005738,0.042692,-0.483981,0.198849,0.028767,-0.040572,0.043355,0.329793,-0.219090,-0.172573,0.298151,0.065500,-0.491400,-0.093320,0.175845,-0.008407,0.007385,0.064091,-0.663459,-0.096619,-0.186032,0.057764,-0.014294,-0.091036,-0.383561,-0.587691,-0.152125,-0.029112,-0.121908,0.112993,0.197865,0.165083,0.362951,-0.474758,0.263725,0.504560,0.094810,-0.273211,0.644837,-0.148098,0.174895,-0.189734,-0.327611,0.196709,0.240473,0.454565,0.066763,0.242184,-0.316466,-0.015649,-0.392054,0.135672', '10466639', '21619567', '20451118', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11611021', '在这世界的角落', '剧情', '小铃（能年玲奈 配音）是一个整日里慢慢腾腾迷迷糊糊的姑娘，最大的爱好就是画画。眼看着到了嫁人的年纪，在父母的安排下，小铃来到了吴市，嫁给了名为北条周作（细谷佳正 配音）的男子，成为了北条家的媳妇。径子（尾身美词 配音）是周作的姐姐，带着女儿晴美（稻叶菜月 配音）住回了娘家。和贤惠老实的小铃不同，径子性格张扬而泼辣，虽然她常常对唯唯诺诺的小铃感到不满，但两人之间的感情其实十分要好。战争开始了，越来越多的战斗机飞过天空，刺耳的防空警报声常常划破夜晚的宁静，战争的阴影一点一点的覆盖着北条一家人的生活。在一场空袭中，晴美不幸遇难，小铃亦失去了右手再也无法作画，然而，在如此残酷的时局下，一家人依然没有放弃对生存的渴望。©豆瓣', '能年玲奈', '片渊须直', 7.5, 31189, 'tt4769824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2384601603.jpg', 8, 3.9, 19.9, 40.4, 27.8, '0.300559,-0.005306,-0.601762,0.533790,-0.294730,-0.232309,0.811388,0.360141,-0.420622,-0.193483,0.332595,0.575879,-0.010126,0.286318,0.147949,0.028406,-0.126489,-0.496397,-0.128195,-0.097723,-0.067119,-0.525616,0.070584,0.027660,-0.172653,-0.154802,0.585673,0.045876,-0.044843,0.455789,0.025002,-0.072105,-0.033265,0.537743,-0.282315,0.112407,-0.247543,-0.038705,-0.222211,0.171799,0.111293,-0.227207,-0.203507,0.143598,-0.032126,0.250198,0.762271,-0.437797,-0.065777,0.025986,0.370429,-0.168550,-0.136146,0.262759,0.305221,0.010583,0.164094,-0.059074,-0.256707,-0.059847,0.011153,-0.140599,-0.354468,0.260748,0.058853,0.218959,-0.630961,0.552212,0.008886,-0.305047,0.167417,-0.497531,0.169879,0.242850,0.005374,0.582622,-0.634577,0.426334,-0.404057,0.034830,0.634034,0.107201,-0.062627,0.501933,-0.185332,-0.313729,-0.017043,-0.486938,-0.723770,-0.386893,0.184489,-0.012015,-0.174385,0.297853,-0.513411,0.280359,0.186389,-0.324658,0.055823,-0.507946,-0.168344,-0.416177,-0.208655,-0.789801,-0.316432,0.323249,0.114316,-0.260611,0.833048,-1.120864,0.222509,0.435988,0.167357,-0.046104,0.462532,0.308164,0.054666,0.072807,0.035619,0.140138,-0.241228,0.208970,0.263827,0.397673,-0.147333,-0.068733,-0.426219,0.481326', '1292219', '21766698', '3445516', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11614603', '整容日记', '喜剧', '大学生郭晶（白百何 饰）相恋几年的男友（郭京飞 饰）不光从不承认这段恋情，毕业时还因为她长得太丑而提出分手。大受打击的郭晶连哭的时间都没有就马上加入了找工作的大军。因为相貌的平庸，郭晶在找工作过程中屡屡碰壁，但却意外在一次面试中被高管雷蒙（郑中基 饰）看中她的才华而获得工作。雷蒙是公司里精英级的人物，被公司的美女们奉为男神，而且身边不乏各路美女相伴。但高高在上的他却一直对平凡的郭晶另眼相看。郭晶为了雷蒙决定放手一搏，存钱整容。功夫不负有心人，在扔了大把的金钱后，郭晶最终变成了人人羡慕的美女，而且公司也没人发现她的整容秘密。郭晶如愿以偿地和雷蒙走到了一起，但意外得知雷蒙其实最讨厌人造美女。天有不测风云，郭晶整容的秘密瞬间在公司曝光，她跟雷蒙的恋情将要经受最大考验……©豆瓣', '白百何', '林爱华', 4.7, 99685, 'tt3644610', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2174794423.jpg', 17.7, 38.8, 35.9, 5.6, 2.1, '0.195013,-0.072093,-0.745661,0.528181,-0.386458,-0.337923,0.479948,-0.019065,-0.582937,-0.328626,0.073444,0.724259,-0.387693,0.362806,0.224325,0.000138,-0.051522,-0.679385,0.095419,-0.295229,-0.175307,-0.353172,-0.144296,-0.171785,-0.323531,-0.188671,0.765346,0.037054,-0.150263,0.427498,0.568407,0.005079,0.103767,0.581737,-0.157885,-0.133993,0.167864,0.255026,-0.119349,0.257375,0.068450,-0.286580,-0.188494,0.211792,0.181097,0.301940,0.352112,0.016735,-0.212310,0.024943,0.562361,-0.401292,-0.136671,0.081415,0.419496,-0.075280,0.347420,0.142932,-0.182386,-0.060273,0.242257,-0.039262,-0.760447,0.067805,0.145445,0.013004,-0.653309,0.508908,-0.106197,-0.053957,0.024053,-0.153927,0.096641,0.372600,0.302168,0.113142,-0.193816,0.160022,-0.487628,0.382444,0.603260,0.087718,-0.204761,0.412442,-0.056372,-0.471910,-0.024206,-0.336956,-0.484222,0.190518,-0.106039,0.061783,-0.316972,0.040906,-0.419729,-0.061937,-0.137908,-0.067374,-0.107629,-0.454531,-0.172284,-0.536918,-0.221644,-0.401743,-0.341612,0.073854,0.061968,-0.358474,0.774543,-0.784979,0.017279,0.368863,0.372815,-0.828343,0.842937,0.219920,0.033678,-0.199773,-0.230194,0.107956,0.063824,0.172291,0.152375,0.235631,-0.130105,-0.542790,-0.384808,0.313226', '4301278', '5985887', '6101834', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11615927', '银魂剧场版：完结篇 直到永远的万事屋', '剧情', '银魂完结篇即将上演，坂田银时（杉田智和 配音）在影院抓住一个盗录的电影小偷，谁知刺眼的白光之后，他却被带到一个颇有些陌生的世界。不远处的江户，曾经的繁华早已不再，高楼大厦已变成没有人居住的废墟。原来此刻银时正身处五年后的未来，过去的岁月里，名为“白诅”的神秘病毒恣意蔓延，导致世界濒临毁灭边缘。他在荒芜的街道见到了飒爽英姿的志村新八（阪口大助 配音）和武功高强的神乐（钉宫理惠 配音）。似乎未来世界的银时当初为调查白诅而意外死亡，新八与神乐继承了他和万事屋的遗址，与一切恶徒作战。化名阿珍的银时回到破败的街道和朋友们身边，此时他仿佛背负起改变黑色未来的重大使命……©豆瓣', '杉田智和', '藤田阳一', 9.3, 34293, 'tt2374144', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2258024316.jpg', 0.3, 0.6, 6.5, 19.6, 72.9, '0.093151,0.212078,-0.852501,0.392121,-0.048180,-0.176088,1.094426,0.114413,-0.359847,-0.406217,0.272721,0.767623,-0.118866,0.392764,0.358805,0.195732,-0.177831,-0.847705,-0.485505,-0.212724,-0.382619,-0.251109,-0.520434,-0.145295,-0.173835,-0.311777,1.067172,0.352291,-0.205440,0.327331,-0.034933,0.298859,-0.405139,0.372084,-0.360407,0.034795,0.056442,0.238655,-0.183032,0.007534,-0.173615,-0.301680,-0.231400,0.298353,-0.304473,0.372492,0.782133,-0.466090,-0.288186,-0.230255,0.441142,-0.220295,-0.161484,0.056353,0.309978,-0.149071,0.160242,0.120431,-0.042079,-0.259543,-0.045843,-0.118928,-0.659055,-0.027713,0.000864,0.270442,-0.342921,0.545649,0.038158,-0.339560,0.233360,-0.385139,0.409002,0.140339,0.436965,0.322555,-0.362093,0.081284,-0.374169,-0.036686,0.607841,0.107216,-0.321448,0.462625,-0.195337,-0.145409,-0.308214,-0.077342,-0.388642,-0.016435,0.322065,0.159687,-0.199723,0.381361,-0.622050,-0.040884,0.055678,-0.228657,0.045584,-0.267531,-0.486427,-0.676027,-0.177577,-0.327338,-0.168052,0.068027,-0.061602,-0.073132,0.480395,-0.827271,0.380984,0.137786,0.070739,-0.220956,0.634631,-0.133559,0.113102,-0.133638,0.033757,0.312649,-0.039579,0.654393,0.163697,0.206941,-0.306459,0.086714,-0.743885,0.759162', '1467779', '21619567', '1417036', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11620560', '007：幽灵党', '动作', '一个来自过去的加密信息让詹姆斯·邦德开始了一个神秘任务，从墨西哥城到最终的罗马，在那儿他邂逅了美艳的露琪亚·斯琪拉（莫妮卡·贝鲁奇 Monica Bellucci 饰），而她则是一名臭名昭著的意大利黑手党寡妇。邦德潜入到了一个密会中，揭开了一个名叫“幽灵党”的邪恶组织背后的秘密。然而，远在伦敦的国家安全中心的新任负责人马克思·登彼（安德鲁·斯考特 Andrew Scott 饰）怀疑邦德这次行动的目的，并挑战M（拉尔夫·费恩斯 Ralph Fiennes 饰）掌权的军情六处的地位。邦德暗中召集了钱班霓（奈奥米·哈莉斯 Naomi Harries 饰）和Q博士（本·威肖 Ben Whishaw 饰），协助他寻找他宿敌的女儿——玛德琳·斯旺（蕾雅·赛杜 Léa Seydoux 饰）的下落，玛德琳·斯旺手里握有解开幽灵党秘密的线索。作为一名杀手的女儿，斯旺比绝大多数人更了解邦德。正当邦德冒险潜入“幽灵党”中心时，他得知自己与他寻找的敌人（克里斯托弗·沃尔兹 Christoph Waltz 饰）之间有着骇人的联系……', '丹尼尔·克雷格', '萨姆·门德斯', 6.5, 186923, 'tt2379713', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2276234635.jpg', 2.3, 12.8, 51.1, 25.7, 8.1, '0.436194,0.103078,-0.571386,0.633495,-0.071650,-0.153422,0.604010,0.107691,-0.324613,-0.356894,0.204263,0.675346,0.101140,-0.076932,0.372112,0.201783,-0.469084,-0.649279,0.123400,-0.458235,-0.267775,-0.687148,-0.551255,-0.348678,0.070257,-0.309799,0.405254,0.038613,-0.208848,0.487558,0.435278,0.535600,-0.204260,0.265296,-0.050852,-0.261885,0.503481,-0.264717,-0.051850,0.308669,-0.054286,-0.170864,-0.107902,0.390199,0.151140,0.608135,0.402256,-0.393648,0.185863,-0.122389,0.116716,-0.270108,0.065433,-0.084823,0.365557,-0.105174,-0.074620,0.331069,-0.185064,0.133476,0.057261,-0.237875,-0.824405,-0.044684,0.227984,0.366695,-0.410834,0.115864,-0.359486,0.059381,0.232403,-0.334687,0.254455,0.284659,-0.064750,0.035936,-0.015831,0.029844,-0.447386,-0.021959,0.353392,-0.076910,-0.034015,-0.046932,-0.075997,-0.385902,-0.122852,0.087141,-0.264876,-0.154160,0.531664,-0.029057,0.097228,0.176338,-0.686916,-0.193216,-0.355836,0.065352,-0.048541,-0.305604,0.038192,-0.688494,-0.178116,-0.246932,-0.119327,0.049061,-0.098849,-0.170669,0.608967,-0.607855,0.077066,0.757900,0.260772,-0.508720,0.519576,0.086324,0.303646,-0.414438,-0.306894,0.333245,0.402