INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11623346', '心战', '悬疑', '相貌平平的中年人李良（任达华 饰）行走在熙熙攘攘的闹市街头，平凡无奇的外表无法引起任何人的注意，然而他的内心却深藏着鲜为人知的黑暗的秘密。李良来到警局自首，他坦承自己是一个连环杀人犯，只不过他杀人的理由和动机引人深思。对他来说，杀人并非残忍剥夺他人的生命和生存的权力，而是给他们以救赎。当年李良的老婆为血癌所折磨，极度痛苦之际选择自杀结束生命。这一事件令李良倍受打击，在此之后他有意关注网络上各种自杀新闻。既然自杀会令绝望的人落入永远无法解脱的无间地狱，那么为何自己不伸出援助之手帮他们一把？这样想着，李良开始行动。他接受各类受困之人的委托，带他们跨过生与死的界限。他从没想过，如此极端乖张的做法会将自己和他人带向何方……©豆瓣', '任达华', '陈翊恒', 4.4, 6084, 'tt1700439', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2141091025.jpg', 23.1, 41.6, 28.7, 5, 1.5, '0.263749,0.077677,-0.724802,0.525059,-0.430937,0.096573,0.830080,0.019918,-0.575728,-0.073005,0.349008,0.755592,0.053471,0.064285,0.118397,-0.103876,-0.148797,-0.447230,-0.130477,0.043957,-0.251974,-0.407845,-0.137156,-0.354135,-0.154354,0.038567,0.851680,0.275499,-0.450157,0.229977,0.265120,0.613428,-0.091820,0.732746,-0.126394,-0.300897,-0.251647,0.003053,-0.322327,0.112316,0.143326,-0.368610,-0.137917,0.753728,-0.661755,0.361932,0.630362,-0.322519,-0.259221,-0.169453,0.563486,-0.632187,-0.048469,0.259759,-0.169423,-0.143167,0.009700,0.367342,-0.084221,0.037633,0.149710,0.025898,-1.040624,-0.192386,0.017583,0.227170,-0.418463,0.112261,-0.110295,0.175539,0.079808,-0.216003,0.086066,0.115661,0.347157,0.114211,-0.437522,-0.361173,-0.557643,0.173188,0.842409,-0.138441,-0.301419,0.180520,-0.332614,-0.417822,-0.018453,-0.441543,-0.592711,-0.036246,0.152680,0.182237,-0.462162,0.251423,-0.284918,-0.179928,-0.228402,0.028946,-0.089671,-0.613792,-0.161373,-0.350617,-0.150201,-0.362674,-0.503302,-0.135848,0.103503,-0.422170,0.444145,-0.731622,0.127320,0.497682,0.360486,-0.670148,0.586572,0.182186,-0.044600,-0.282046,-0.182378,0.566960,0.244508,0.251522,-0.031057,-0.090905,0.230504,0.155889,-0.346835,0.554202', '25828589', '30163500', '26692652', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11624706', '小黄人大眼萌', '喜剧', '从地球诞生之初，一种奇怪的生物便出现在这颗蓝色的星球上。他们不断进化、蜕变，终于成为我们所熟悉的小黄人的模样。小黄人们毕生寻找邪恶的老大，以成为他的部属为荣，但是千百万年来的努力最终化成一场空。经历了一段长久的沉寂，名叫凯文的小黄人决定再度上路，他带着热爱音乐的斯图尔特、成事不足败事有余的鲍勃，漂洋过海来到了1968年的美国。三个小家伙偶然听说奥兰多即将召开“恶人大会”，于是忙不迭地赶了过去，并且阴差阳错成为女魔头斯嘉丽·杀人狂（桑德拉·布洛克 Sandra Bullock 配音）的随从。很快斯嘉丽交给他们一个任务，那就是窃取英国女王的王冠。不知轻重的小家伙们笑嘻嘻地出征，等待他们的将是前所未有的大冒险……©豆瓣', '桑德拉·布洛克', '凯尔·巴尔达', 7.7, 273202, 'tt2293640', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2265761240.jpg', 0.6, 3.4, 28.6, 43.9, 23.5, '0.083183,0.252278,-0.548749,0.582464,-0.338144,-0.251228,0.494761,-0.011116,-0.363855,-0.074779,0.255219,0.878817,-0.282333,0.252739,0.358035,0.031748,-0.125661,-0.564968,-0.187126,-0.267033,-0.268947,-0.182516,-0.369294,-0.203729,0.016871,-0.114752,0.726847,0.096381,-0.005369,0.499412,0.474748,0.284413,-0.102891,0.395265,-0.368773,0.086710,0.083487,-0.162937,-0.051054,0.047638,0.013583,-0.119642,-0.008906,-0.072692,-0.129514,0.008818,0.788319,-0.654225,-0.003339,-0.256825,0.431364,-0.489207,-0.196428,-0.019060,0.236679,0.398612,0.080860,0.080770,-0.149512,-0.104393,0.082534,-0.332767,-0.731942,0.110402,-0.116758,0.253890,-0.482983,0.243553,0.251270,-0.126824,0.349767,-0.435702,0.116255,0.449026,0.182863,0.409111,-0.085345,0.084522,-0.273251,0.156897,0.615136,-0.143262,-0.418354,0.229769,0.202050,-0.457257,0.094566,-0.255587,-0.457232,-0.014897,0.383012,0.110425,-0.146998,0.255685,-0.794419,-0.040842,-0.333536,-0.364505,0.269220,-0.391358,-0.150299,-0.556873,-0.117278,-0.135979,-0.216128,0.042433,-0.126305,-0.147453,0.905614,-0.749693,0.376967,0.583449,-0.059382,-0.475684,0.425331,-0.208605,0.209063,-0.407390,-0.089942,0.229339,0.018873,0.528917,0.177603,0.418072,0.040210,0.090059,-0.451623,0.515754', '3811356', '25928048', '27602116', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11625097', '澳门风云', '喜剧', '闻名中外，曾担任美国赌场保安总顾问的魔术手石一坚（周润发 饰），终回流澳门退休，更宴请各方朋友到来庆祝生日宴。其中好友Benz哥（许绍雄 饰）与他的儿子晒冷（谢霆锋 饰）以及外甥牛必胜（杜汶泽 饰），更特别由香港来到澳门到贺。翌日，大陆、香港以及澳门三地警方，竟不相约 而同找上石一坚，希望他能够重出江湖帮忙对付DOA组织集团的高先生（高虎 饰），但坚却以退休为由婉拒了事。另一边厢，冷竟与牛必胜一起找上门，希望坚收他俩为徙弟，坚哥虽欣赏小冷，但奈何经已退休，只好拒绝，但看在Benz哥份上，就招待他一夜。谁不知，当晚竟遇上了杀手（张晋 饰），杀手们不问原因直接追击小冷以及坚哥爱女阿彩（童菲 饰）。期间虽有中国公安洛欣（景甜 饰）相救，但阿彩终难逃一劫，被害至失忆。明查暗访下才知道，幕后的黑手竟是高先生。事情又岂会是无缘无故发生，坚与小冷二人连手，加上女公安洛欣三人，布下奇谋妙计对付高先生，斗智斗力，誓要查个水落石出，将他绳之于法……', '周润发', '王晶', 5.8, 165650, 'tt3444184', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2167451620.jpg', 8.6, 22.9, 46.4, 16.1, 6, '-0.170046,-0.135552,-0.363442,0.172310,0.199308,-0.036701,0.003331,0.146596,-0.369477,-0.393700,0.127171,0.310256,0.062874,0.161139,0.179476,-0.230143,-0.092449,-0.508675,0.130114,0.043391,-0.238496,-0.380288,-0.180646,0.029427,-0.042700,0.116933,0.090647,0.149149,-0.022183,0.407149,0.477834,0.253332,-0.203133,0.398238,0.056266,-0.268018,-0.024903,0.354081,-0.443544,0.162348,0.011809,-0.244026,-0.262417,-0.137040,0.315048,0.357353,0.072136,0.034911,-0.205960,-0.210410,0.145889,-0.351284,0.103848,-0.035102,0.424031,0.016923,0.279620,0.319496,-0.174825,-0.157379,0.040341,-0.021650,-0.350304,0.344389,0.435422,-0.157555,-0.345749,-0.076449,-0.210302,0.036642,-0.301423,-0.239149,0.154149,0.292862,0.136018,-0.043894,0.169777,0.084154,-0.380333,0.115415,0.687748,0.090720,0.178846,-0.301420,0.343797,-0.173208,0.200147,-0.256835,-0.022953,0.174392,0.018881,-0.108517,0.146206,-0.039109,-0.093453,-0.248740,-0.297462,0.225862,0.016181,-0.201540,0.281250,-0.384914,0.067437,-0.056697,-0.048715,0.214695,0.477546,-0.292547,0.343956,-0.591539,0.010264,0.035487,0.431020,-0.561493,0.599335,0.221906,-0.003006,-0.291437,-0.171587,-0.124750,0.234988,-0.152367,0.012903,-0.022502,0.041607,-0.465953,-0.11658