INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11625312', '刑警兄弟', '喜剧', '陈飞和尊尼都是来自单亲家庭的年青警员，处事也都不成熟，加上性格迥然不同，相处中产生许多矛盾。偏偏陈飞的父亲和尊尼的母亲相恋，使两人关系更形紧张，闹出许多笑话。后来，两人通过侦查罪案增进了解、冰释前嫌。', '黄宗泽', '戚家基', 5.4, 7910, 'tt5617254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2328683485.jpg', 10.6, 30.4, 42.7, 10.9, 5.4, '0.648574,-0.621433,-0.624328,0.548247,-0.103319,-0.384140,0.820965,-0.053647,-0.748851,-0.358582,-0.233758,0.317512,-0.439540,-0.021078,-0.001768,-0.663620,-0.214832,-0.625559,-0.046750,-0.097611,0.117468,-0.714848,-0.317559,0.270675,-0.293434,-0.410075,0.324044,-0.101476,-0.593832,0.480846,0.091669,0.092668,-0.388741,0.666662,0.061381,0.010313,0.040017,0.313549,-0.376901,-0.497282,0.235264,0.099346,0.071465,-0.056379,0.171885,0.681943,0.469421,-0.081806,-0.368408,-0.126373,0.388513,0.394463,-0.210674,-0.089006,0.626964,0.408177,0.382865,0.419922,-0.289720,-0.015482,-0.502376,0.342923,-0.300897,0.606828,0.488184,0.087159,-0.378411,0.362598,0.202604,-0.452002,0.083238,-0.035438,0.182535,0.607407,0.534264,0.614490,0.183081,0.072999,-0.292020,-0.530668,1.433131,0.214114,-0.326617,0.213829,-0.822373,-0.301323,-0.011007,-0.498182,-0.225645,0.048625,-0.041063,-0.281184,0.211732,0.643565,-0.126491,0.234895,0.213309,0.405366,0.091642,-0.566435,0.301066,-0.704333,-0.571107,-1.061766,-0.603139,-0.282833,0.072478,-0.475760,0.794716,-0.805489,-0.273655,0.053112,0.351080,-0.805290,0.349896,0.353359,0.011345,-0.675230,-0.171447,0.354252,0.074013,-0.185384,0.105329,0.285779,0.081454,0.040675,-0.043081,0.072573', '25721544', '26320029', '1305084', '27000061');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11627068', '大明劫', '剧情', '明朝崇祯15年，全国内忧外患，大将孙传庭（戴立忍 饰）临危受命带着妻子冯氏（冯波 饰）来到潼关抵抗李自成的军队。与此同时游医吴又可（冯远征 饰）怀着济世救人之心来到潼关拜访师傅——药局提领赵川（钱学格 饰）。大敌当前，孙传庭军中士兵染上怪病，同时还要面对崇祯皇帝（余少群 饰）的催促出兵和潼关豪绅顾清远（马精武 饰）等人的自私敛财。赵川因施救不力以身殉职，吴又可在危难之时挺身而出，靠着不同寻常的治疗方法与孙传庭惺惺相惜。最后瘟疫终于被控制住，但是国家的病症能否被战争治好吴又可和孙传庭都无法预料。本片主题曲由BossaNova女王小野丽莎演唱，这是小野丽莎首次用中文演绎自己的歌曲作品。©豆瓣', '冯远征', '王竞', 8.1, 84017, 'tt3336934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2154039514.jpg', 0.4, 1.8, 18.2, 49.3, 30.3, '-0.326687,-0.048288,-0.306178,0.563639,0.321037,-0.147747,0.447541,0.326537,-0.590976,-0.341825,0.074483,0.083464,-0.054283,0.000539,0.113871,-0.431193,-0.227661,-0.609859,0.076585,0.176232,-0.108564,-0.184341,0.050561,-0.374523,-0.456296,-0.063309,0.641655,0.344591,-0.197707,0.248252,0.522842,0.460079,0.014973,0.568570,0.043596,-0.062503,-0.207248,-0.116625,-0.378177,0.104341,0.415148,-0.695649,-0.400105,0.152157,-0.059475,0.180661,0.454109,-0.249250,0.171517,-0.025358,0.018105,-0.180631,0.209105,0.109471,0.055471,0.196610,0.013123,-0.046037,0.009455,0.079956,-0.154815,-0.124746,-0.349355,-0.060201,0.220746,-0.140125,-0.412703,0.104536,-0.116119,0.112994,-0.043941,-0.488743,0.185800,0.509411,0.344462,0.341380,-0.226629,0.050476,-0.486309,0.341023,0.233862,-0.186931,-0.223027,-0.023609,-0.132535,-0.746722,0.206588,-0.426877,-0.399120,0.362966,0.052334,-0.026926,0.199089,0.047778,-0.293418,-0.293138,-0.280185,0.107828,0.090394,0.044731,0.250834,-0.453645,-0.053661,-0.159827,-0.118989,0.242186,0.506366,0.069856,0.419589,-0.584274,-0.093889,-0.059152,0.182488,-0.765707,0.300979,0.128604,0.013434,-0.005497,-0.086444,0.328304,-0.094083,0.387623,0.343663,0.134664,-0.227224,-0.162408,-0.221462,0.218060', '1295746', '1294693', '1292287', '1305143');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11632586', '爱情银行', '剧情', '爱情如果能够储存，是活期还是定期？利息又是什么？何沐阳（夏雨 饰）开设了一家名为“爱情银行”的咖啡馆，恋人们可以来这把对彼此的告白储存一年，如果一年以后分手，没有来取回视频，视频就会被销毁，押金就归爱情银行所有，这也是爱情银行特殊的经营之道。一个名叫余小鱼（周泓 饰）的女孩为拿回男朋友存在这的爱情视频，与何沐阳展开了旷日持久的拉锯战。在这场妙趣横生的“战斗”中，一种特殊的情感在两人之间慢慢滋生，何沐阳开设爱情银行的真正来由，一段十年情感的秘密也随之被揭开……©豆瓣', '夏雨', '曲江涛', 6, 7895, 'tt7010144', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1890839961.jpg', 5.8, 18.7, 51, 18.9, 5.6, '0.303508,0.301225,-0.299522,0.393752,-0.238411,-0.117795,0.679291,-0.289596,-0.624511,-0.170964,-0.108681,0.587740,-0.165757,0.054936,0.000873,-0.000151,-0.058396,-0.532720,-0.118260,-0.416953,-0.404923,-0.403830,-0.127508,-0.090825,0.150362,0.073895,0.677137,0.154785,-0.226398,0.255479,0.378796,0.088180,-0.236892,0.218493,-0.257838,0.118279,-0.106316,0.302905,-0.502893,0.152344,0.217970,-0.246893,-0.003152,0.141616,0.112958,0.205002,0.665480,0.077629,-0.247464,0.323688,0.508830,-0.170512,-0.039836,0.148019,0.075542,0.201116,0.278721,0.373171,-0.579278,0.080535,0.069273,0.103717,-1.080160,-0.302463,-0.131982,0.175807,-0.369451,0.574938,-0.057151,-0.176667,0.075734,-0.134369,0.020169,0.607547,0.497548,0.249823,-0.260814,-0.386029,-0.585219,0.395660,0.597873,-0.242146,-0.051572,0.680307,-0.222505,-0.387006,-0.318446,0.198039,-0.403638,-0.170432,0.349997,0.153693,-0.049498,0.060056,-0.953728,0.028186,-0.084073,-0.176159,0.460417,-0.524528,-0.123563,-0.425353,-0.309513,-0.439789,-0.336213,0.039719,0.604410,-0.251058,0.756354,-0.875364,0.159186,0.584114,0.482174,-0.383606,0.579981,0.300985,-0.049905,-0.414359,0.274175,0.073131,-0.016182,0.434948,-0.012188,0.241511,0.423133,0.043243,-0.300474,0.636323', '1793491', '26678784', '24879858', '27009869');
