INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11639159', '早见，晚爱', '剧情', '年轻创业美女老板周挺带领三姐妹与腹黑男展开一场斗智斗勇的收购反击战。曾经的校园初恋为了各自立场不得不近场搏杀，不可退让——然而旧情难消，余情未了，新欢作祟，恶棍搅局，更有屌丝财主阳奉阴违，暗度陈仓，白富美强爱上位，骑虎难下……在这部充斥阳谋与初恋的商战危情中，且看美女老板究竟是以身抵债，名利双煞，还以情破局、重归原点？一切悬念尽在一天的9小时中悉数道来……', '周渝民', '刘国昌', 4.4, 5585, 'tt3814496', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2049165428.jpg', 28.2, 37.9, 24.9, 4.9, 4.1, '-0.155319,-0.192500,-0.377972,0.329231,-0.042250,-0.325995,0.378913,-0.022002,-0.294073,0.046849,0.253201,0.387388,-0.160277,-0.024630,0.429012,-0.256201,-0.089377,-0.584878,-0.215611,-0.134930,0.287623,-0.400719,-0.203655,0.139020,-0.145855,0.065079,0.682565,0.306068,-0.072348,0.086895,0.815060,-0.089296,-0.263398,0.192329,0.130223,-0.243884,-0.096334,0.128734,-0.883221,0.026684,-0.006918,-0.249074,-0.449868,-0.046144,-0.193994,0.109276,0.583577,-0.159520,0.108528,-0.330541,0.429332,-0.162658,-0.278298,0.013115,0.199865,-0.186036,0.535087,0.293688,0.255591,-0.299666,0.047473,0.088532,-0.336075,-0.071774,0.320852,-0.127999,-0.265446,0.365610,0.126207,0.130586,0.096340,0.105053,-0.225638,0.032401,0.572703,0.193162,0.122648,-0.100408,-0.398472,0.079445,0.767287,0.214240,0.012353,0.282057,0.351302,-0.228158,0.110231,-0.424852,-0.519552,-0.274077,0.079118,-0.173790,0.148562,0.405400,-0.557506,0.072699,-0.028000,0.197993,0.126761,-0.465162,0.076298,-0.331172,-0.487450,-0.123372,0.289549,0.407665,0.452168,-0.241666,0.458800,-0.717321,-0.019689,0.300366,0.402481,-0.414458,0.498522,0.577605,0.036822,-0.451277,-0.384505,-0.016848,-0.270954,-0.001181,0.132000,-0.057253,-0.188450,0.083382,-0.312230,0.157293', '1293265', '4301278', '1296978', '6225992');
