INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11776289', '华丽上班族', '剧情', '清晨，职场菜鸟李想（王紫逸 饰）踏入众信贸易集团大楼，开始第一天工作。公司里，想结识应聘助理的年轻女孩何琪（郎月婷 饰）。但何琪真正身份是董事长何仲平（周润发 饰）的女儿，更引起同事猜疑，幸得CEO张威（张艾嘉 饰）帮忙渡过难关。张威忙于公司上市，却得知何仲平欲让女儿接手众信，心死之下决定为自身利益盘算，因而联手公司副总王大伟（陈奕迅 饰），实施神秘计划，想更在不知不觉间卷入其中。就在张威逐步推动计划时，王大伟却因沉迷股权交易负债累累，被迫利用情场失意的财务总监苏菲（汤唯 饰），陷张威等人为被动。更意想不到的是，何仲平从头到尾都在掌控一切，一段职场残酷对决，即将上演……©豆瓣', '周润发', '杜琪峰', 6, 53833, 'tt4392726', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2263695980.jpg', 6.5, 20.9, 46.5, 20.3, 5.9, '-0.183463,0.356593,-0.539646,0.006064,0.134351,-0.225137,0.084149,0.432237,-0.634957,-0.541242,0.223319,0.260973,-0.134369,0.131144,0.248487,-0.350439,-0.182681,-0.466633,0.115414,0.150832,0.161114,-0.247091,-0.134206,-0.093476,-0.174544,-0.125390,0.721997,0.255850,-0.323151,0.048735,0.250625,0.105116,-0.289332,0.403946,0.370240,-0.183142,0.301402,0.084895,-0.849021,-0.001626,-0.161551,-0.175272,-0.215901,-0.038388,0.224157,0.196460,0.374729,0.212069,-0.242154,-0.329465,0.459737,-0.286970,-0.045403,-0.159610,0.422447,0.252330,0.378994,0.315119,-0.431880,-0.117184,0.022463,-0.169987,-0.899796,0.216023,0.262602,0.053359,-0.390304,-0.108539,-0.225381,0.165857,0.182334,-0.300540,-0.011705,0.517639,0.487152,0.063519,0.046266,0.176528,-0.343370,0.348640,0.640163,-0.010410,0.134150,0.337979,0.166012,-0.066782,-0.056002,-0.018686,-0.170261,-0.070959,0.071364,0.198309,0.171535,0.279112,-0.353041,-0.098209,-0.165892,0.082603,0.248565,-0.525031,0.036132,-0.552656,-0.272412,0.132605,0.001229,-0.033523,0.318263,-0.213148,0.342602,-0.765647,-0.092658,0.318837,0.434216,-0.683400,0.367298,-0.061753,0.165295,-0.654101,-0.155241,0.003390,-0.175666,-0.078060,-0.211961,0.007997,-0.110031,-0.410397,-0.022629,-0.033782', '26984538', '26678784', '1293265', '1484760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11803087', '异形：契约', '科幻', '故事发生在一艘名为“契约”的殖民太空船之上，飞船上搭载了两千名进入沉睡的殖民者，他们的目的地是遥远的欧米伽六号行星，希望能够在那里建立新的家园。一场意外的发生令契约号的能量收集帆遭到了破坏，船长布兰森（詹姆斯·弗兰科 James Franco 饰）亦不幸身亡。作为代理船长的欧朗（比利·克鲁德普 Billy Crudup 饰）带领着惊恐而又悲伤的船员们降落到了一颗未知的神秘星球上。在这里，他们遇见了仿生人大卫（迈克尔·法斯宾德 Michael Fassbender 饰），大卫热情的接纳了人类的到来，并讲述了他和已故的肖博士（劳米·拉佩斯 Noomi Rapace 饰）在这里生活的经历。就在大卫渐渐赢得了船员们的信任的同时，大家已经一步一步的走入了前者为他们精心打造的地狱之中。©豆瓣', '迈克尔·法斯宾德', '雷德利·斯科特', 7.4, 242013, 'tt2316204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459944375.jpg', 1, 4.3, 33.6, 46.7, 14.4, '0.395012,0.137911,-0.780212,0.557743,0.023875,-0.294022,0.790730,0.164565,-0.218642,0.030770,0.284821,0.755120,-0.130449,0.153748,0.433781,0.239560,-0.483674,-0.492132,-0.162943,-0.276202,-0.494049,-0.550010,-0.343626,-0.357208,0.014811,-0.459239,0.639968,0.179789,-0.053042,0.514413,0.247444,0.395258,-0.053292,0.341132,-0.219225,0.067087,0.229900,-0.159130,-0.206698,0.090362,-0.455739,-0.148299,0.047999,0.185866,0.134753,0.357747,0.778825,-0.476624,-0.016253,-0.040005,0.097408,-0.234400,0.367595,0.004080,0.357118,0.131521,-0.321168,0.222920,-0.205003,0.050125,0.076643,-0.111652,-0.901739,0.020935,-0.062359,0.330907,-0.465523,0.472403,-0.070672,0.061374,0.041076,-0.181475,0.310610,0.399644,0.102510,0.303533,-0.110535,0.040055,-0.444913,0.072414,0.727765,-0.127417,-0.345218,0.279166,-0.156446,-0.503082,-0.363969,-0.021784,-0.654874,-0.142034,0.510649,0.262425,0.036814,0.373074,-0.842899,0.189953,-0.426607,-0.374640,-0.088119,-0.273788,0.039513,-0.920704,-0.113160,-0.281428,-0.193995,0.100628,-0.086849,-0.197515,0.712663,-0.526829,0.404502,0.406874,0.305286,-0.164704,0.619628,-0.096193,0.204303,-0.134924,0.066116,0.390720,0.078494,0.425541,0.045119,0.424241,0.015998,0.114450,-0.354279,0.499942', '1294917', '3318306', '19965431', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11808948', '海绵宝宝', '喜剧', '围绕蟹黄堡的神秘配方，痞老板和蟹老板展开了新一轮的战争。虽然海绵宝宝成功挫败痞老板的猛烈攻势，但是却依然中了对方的诡计。关键时刻，配方凭空消失，直接后果便是导致没人能再做出蟹黄堡。对于日常极度依赖蟹黄堡的比奇堡的居民来说，这一消息无异于晴天霹雳。小镇的宁静荡然无存，海底世界陷入末世般的混乱与动荡之中。由于搭救了痞老板，海绵宝宝被大家当作叛徒对待。危机时刻，海绵宝宝、派大星、痞老板、蟹老板、松鼠珊蒂、章鱼哥得以穿越时空，并顺着蟹黄堡的香味来到了人头攒动的沙滩上。 在那里他们遇见了利用诡计偷走秘方的胡子海盗（安东尼奥·班德拉斯 Antonio Banderas 饰），于是一场蟹黄堡的攻防战由此展开……©豆瓣', '安东尼奥·班德拉斯', '保罗·提比特', 7.6, 44690, 'tt2279373', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2282934200.jpg', 0.8, 4.3, 31.3, 40.6, 23.1, '0.333201,0.314642,-0.364215,0.292989,0.263220,0.096370,0.464711,0.457214,-0.555420,0.152308,0.194719,0.480844,-0.205432,0.039420,0.030018,0.049578,-0.193419,-0.483912,-0.178587,-0.235236,-0.054598,0.106627,-0.218954,-0.178638,0.223132,-0.409196,0.364892,0.430689,-0.366626,0.208506,0.083015,0.217335,-0.205731,0.636210,0.192393,0.001843,0.085337,-0.047190,-0.524928,0.145635,-0.174898,-0.153131,0.206628,0.286450,0.255263,0.142885,0.805984,-0.630713,-0.411693,-0.292368,-0.035273,-0.182649,-0.048439,0.112920,0.512861,-0.208884,0.372925,0.095081,-0.012324,-0.072667,-0.018883,-0.297794,-0.522725,-0.043597,0.238336,0.044583,-0.253526,0.083841,0.115696,0.228175,-0.113551,-0.223336,0.256848,0.114211,0.389440,0.424141,-0.278931,0.148462,-0.479028,-0.078353,0.427101,-0.073137,-0.246075,-0.010302,-0.058335,-0.265644,0.123530,-0.236720,0.023231,-0.009250,0.476418,-0.031964,-0.307463,0.599133,-0.858934,0.232624,-0.380736,-0.289823,0.245434,-0.121097,-0.354298,-0.591105,0.103047,-0.011353,0.012995,0.248149,0.092025,0.210636,0.430397,-0.596921,0.245561,0.369171,0.044246,0.122113,0.104522,-0.294970,-0.190296,-0.514089,-0.071627,0.167339,0.178327,0.326461,0.316624,0.332295,-0.048944,-0.249110,-0.149816,0.469325', '26290398', '7056398', '10581450', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('11810348', '马达加斯加的企鹅', '喜剧', '为了给最疼爱的小老弟菜鸟（克里斯多夫·奈茨 Christopher Knights 配音）庆生，老大（汤姆·麦格拉思 Tom McGrath 配音）带领菜鸟以及好搭档科斯基（克里斯·米勒 Chris Miller 配音）、瑞哥闯入了防守最严密的美国黄金储备中心，只为找到金库尽头仅有的那台销售炸薯条的自动贩卖机。谁知他们刚刚完成任务没多久，便被长着触角的贩卖机吞了进去，随后被运到一个神秘的所在。在全封闭的设施内，四只企鹅见到了伪装成基因遗传科学家的章鱼戴夫（约翰·马尔科维奇 John Malkovich 配音）。原来戴夫曾是动物园一只明星章鱼，但随着萌态十足的企鹅们的到来，他便跌入了绝望的深谷。因此戴夫潜心研制了可怕的血清，发誓要向所有他曾待过的动物园中的企鹅展开报复。老大和伙伴们在逃亡途中得到北风特工队的救助，而他们和这些高傲的特工队员将分别阻止戴夫的阴谋……', '汤姆·麦格拉思', '埃里克·达尼尔', 7.7, 140463, 'tt1911658', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2208592166.jpg', 0.4, 2.5, 29.1, 46.9, 21.1, '0.423044,-0.157192,-0.551952,0.523704,-0.047475,-0.473987,0.752093,0.021968,-0.265284,-0.135571,0.100177,0.535149,-0.208987,0.019109,0.119510,-0.032303,-0.136231,-0.453770,-0.450356,-0.253600,-0.270396,-0.290478,-0.442637,-0.249856,0.149635,-0.321134,0.625960,-0.190353,-0.104836,0.301167,0.310154,0.313362,-0.171507,0.197962,-0.167744,0.142463,0.278240,-0.187412,-0.073765,0.213978,-0.102667,-0.006711,0.004191,0.020304,0.145834,0.151293,0.673188,-0.422915,-0.030097,-0.258293,0.202580,-0.240887,0.114464,0.147384,0.300909,0.056867,0.063686,-0.000978,-0.103052,0.231681,-0.006624,-0.204641,-0.908258,-0.238296,-0.199706,0.122476,-0.646366,0.074255,-0.108318,0.048164,0.221490,-0.352623,0.275767,0.183468,0.001720,0.336695,-0.127731,0.236510,-0.476056,0.036548,0.452052,-0.140324,-0.094188,0.113368,0.060806,-0.483557,0.127930,-0.097615,-0.406959,-0.109833,0.462251,0.094648,-0.152927,0.092163,-0.838692,-0.013521,-0.345421,-0.393733,-0.044945,-0.234637,-0.186783,-0.870168,0.138428,-0.161503,-0.013129,0.177158,-0.040394,-0.223084,0.771825,-0.914399,0.292185,0.665267,0.131200,-0.280960,0.526245,-0.219673,0.162909,-0.213811,-0.025238,0.093654,0.341599,0.560740,0.237639,0.512261,0.024575,-0.453810,-0.442331,0.440346', '