INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('12012475', '行过死荫之地', '剧情', '影片改编自劳伦斯·布洛克1992年出版的同名犯罪小说，尼森饰演的马修·斯卡德（Matthew Scudder）曾是一位纽约警察，如今则是无证行业的私家侦探。纽约发生了一系列针对毒贩妻子的绑架案，受害人均惨遭杀害。斯卡德答应了其中一人（丹·史蒂文斯），以及自己弟弟的要求，在前任同事及一名17岁的街头艺术家帮助下，找出幕后的两名凶手。', '连姆·尼森', '斯科特·弗兰克', 6.4, 9578, 'tt0365907', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2185337913.jpg', 1.3, 11.5, 56.2, 25.5, 5.5, '0.524202,-0.239552,-0.402519,0.667381,0.082101,-0.264820,0.450066,-0.162368,-0.612671,-0.844541,0.543710,0.917968,-0.112046,0.400436,0.432077,-0.137016,-0.230147,-0.700891,-0.230204,-0.439405,-0.288881,-0.595295,-0.289184,-0.210524,-0.160222,-0.409758,0.539518,-0.099376,0.142095,0.275146,0.399506,0.747080,0.039932,-0.362739,0.093230,0.118030,0.597255,-0.325278,-0.511995,0.467504,0.072274,-0.221804,-0.018996,-0.101525,0.043453,0.500095,0.479532,0.027843,-0.079703,-0.211561,0.660102,-0.107699,0.305515,-0.115598,0.736501,-0.147808,0.257503,0.646808,-0.271231,-0.308302,0.037878,-0.064075,-0.779456,-0.229815,0.215427,0.299962,-0.247753,-0.056683,-0.354247,0.343899,-0.028734,-0.097260,-0.030597,0.273451,0.315661,0.270635,0.219436,0.031140,-0.418219,0.437206,0.548929,0.246777,-0.081182,0.113347,-0.364545,-0.476932,-0.232303,-0.393990,-0.512200,0.396479,0.413697,-0.229286,-0.060281,0.340815,-0.177825,-0.385375,-0.338050,0.133871,0.000805,0.017246,-0.132774,-0.850291,-0.030627,0.102418,0.114996,-0.061394,0.209266,-0.389617,0.650930,-0.432201,0.055461,0.635173,0.060757,-0.418603,0.685495,-0.022604,0.049096,-0.198333,-0.186037,0.287035,0.555652,-0.188917,-0.087851,0.168056,-0.047529,-0.387660,-0.071314,-0.078558', '26389148', '26990609', '25723905', '25921830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291543', '功夫', '喜剧', '1940年代的上海，自小受尽欺辱的街头混混阿星（周星驰）为了能出人头地，可谓窥见机会的缝隙就往里钻，今次他盯上行动日益猖獗的黑道势力“斧头帮”，想借之大名成就大业。阿星假冒“斧头帮”成员试图在一个叫“猪笼城寨”的地方对居民敲诈，不想引来真的“斧头帮”与“猪笼城寨”居民的恩怨。“猪笼城寨”原是藏龙卧虎之处，居民中有许多身怀绝技者（元华、梁小龙等），他们隐藏于此本是为远离江湖恩怨，不想麻烦自动上身，躲都躲不及。而在观战正邪两派的斗争中，阿星逐渐领悟功夫的真谛。©豆瓣', '周星驰', '周星驰', 8.8, 1019326, 'tt0373074', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2219011938.jpg', 0.2, 0.9, 11.3, 35.6, 52, '0.309018,-0.251777,-0.640712,0.456598,-0.032387,0.085452,0.485917,0.151606,-0.672162,-0.032174,0.058425,0.333754,0.051473,0.031377,0.188659,-0.473829,-0.007355,-0.768698,-0.008281,-0.488611,-0.082693,-0.027565,-0.310411,-0.169572,-0.525778,-0.186582,0.673699,0.357953,-0.482219,0.136846,0.056934,0.190870,-0.626437,0.282512,-0.343855,-0.273234,0.059006,-0.065857,-0.533442,-0.050873,-0.498307,-0.463301,-0.164032,-0.134306,-0.075871,0.266165,0.479771,0.044537,0.069427,-0.240235,-0.104528,-0.172738,-0.191798,0.085033,0.611814,-0.473731,0.387620,0.352892,0.102500,0.050697,0.049577,-0.108342,-0.689116,-0.121471,0.473684,0.109035,-0.368184,0.346697,0.040598,-0.394084,-0.204820,-0.208730,0.105577,0.090571,0.382141,0.010464,0.098896,-0.108848,-0.644367,-0.112405,0.723643,-0.228773,0.160108,0.037210,0.226632,-0.160703,0.211163,-0.501551,-0.080839,-0.282882,0.369361,-0.411308,-0.309749,0.532875,-0.358842,0.101746,-0.062575,-0.127618,0.128512,-0.173404,-0.018538,-0.200702,-0.385238,-0.114262,0.126581,0.211406,0.218803,-0.007786,0.522375,-0.736360,-0.099007,0.553738,0.240613,-0.846330,0.691932,0.098775,0.238316,-0.073836,-0.221966,-0.198579,0.384075,0.381562,-0.104174,0.179836,-0.101778,-0.464385,-0.104501,-0.048556', '1293265', '3811342', '1294713', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291544', '哈利·波特与阿兹卡班的囚徒', '奇幻', '哈利（丹尼尔·雷德克里夫）即将在霍格沃兹渡过第三个年头，此时在阿兹塔班却传出恶棍小天狼星（加里·奥德曼）越狱的消息。据说小天狼星正是背叛哈利父母的好友，他的教父，而这次小天狼星越狱似乎正是为了找他。哈利的心里悄悄的滋生了为父母报仇的想法，期待着小天狼星的出现。新来的魔法老师卢平（大卫·休里斯）有着桀骜不驯的个性，与哈利关系很好，教了哈利许多实用的黑魔法防御知识。而此时在他的魔法地图上却出现了一个神秘人物，虫尾巴。偶然的机会下，在尖叫棚屋里集齐了哈利父亲当年的所有好友，卢平、虫尾巴、小天狼星，哈利的魔杖直指向小天狼星，但他发现那罪犯看他的眼神里充满了疼爱……©豆瓣', '丹尼尔·雷德克里夫', '阿方索·卡隆', 8.9, 655073, 'tt0304141', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910812549.jpg', 0.1, 0.4, 8.6, 36.1, 54.7, '0.345326,-0.167015,-0.442666,0.650915,-0.072271,-0.304069,1.030297,-0.015793,-0.463996,-0.345142,0.174150,0.797823,-0.025227,0.560116,0.002936,0.180859,-0.410695,-0.534368,0.091298,-0.269710,-0.223170,-0.380776,-0.374608,-0.440331,-0.023756,-0.548474,0.365800,-0.050392,-0.065788,0.242776,0.099976,0.335382,0.169016,0.404209,-0.050959,0.026478,0.313897,-0.244755,0.040717,0.052314,0.306734,-0.184676,-0.209633,0.390482,-0.147075,0.498821,0.557136,-0.343378,0.076029,-0.035934,0.377446,-0.344412,-0.021101,0.337209,0.297712,0.045443,0.109686,0.056197,0.179448,-0.167696,0.089223,0.032444,-0.536431,0.040299,-0.147295,0.426747,-0.406659,0.452390,-0.229599,0.200077,0.263387,-0.551397,0.048032,-0.104836,0.017761,0.154068,-0.345306,0.180428,-0.478555,-0.278890,0.315958,-0.230557,-0.079881,0.075058,-0.499547,-0.350289,0.083187,0.146633,-0.490590,-0.199703,0.757297,-0.145599,-0.220296,0.596266,-0.581323,-0.156018,-0.304434,0.021021,-0.130467,-0.360992,-0.323071,-0.704166,-0.084949,-0.335476,-0.443123,-0.285522,-0.011846,-0.428042,0.573176,-0.861217,0.195235,0.524967,0.120696,0.000292,0.495336,-0.069463,0.159698,-0.210138,-0.209271,0.235906,0.126880,0.398275,0.122835,0.301284,0.452313,-0.190137,-0.446980,0.870275', '1302133', '1309172', '1292062', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291545', '大鱼', '剧情', '爱德华（伊万·麦克格雷格 Ewan McGregor 饰）生性热爱自由，成年之后，他选择离开家乡，踏上了环游世界的旅程。一路上，爱德华遇见了各种各样稀奇古怪的角色，经历了无数精彩绝伦的的冒险，而他日后最大的兴趣，就是向他人喋喋不休的重复讲述他的这一段奇幻旅程。威尔（比利·克鲁德普 Billy Crudup 饰）是爱德华的儿子，他并不相信父亲所讲述的那些光怪陆离的故事，甚至对此感到无比厌烦。婚后，他同父亲中断了联系，一晃眼就是数年过去。当再次得到爱德华的消息之时，威尔才知道父亲即将不久于人世，他决定去见爱德华最后一面。然而，这一次，威尔终于发现了隐藏在这些故事背后的奥秘和真相。©豆瓣', '伊万·麦克格雷格', '蒂姆·波顿', 8.8, 535647, 'tt0319061', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p692813374.jpg', 0.2, 0.8, 9.7, 37.4, 51.8, '0.142534,-0.060615,-0.690660,0.534965,-0.012039,-0.530554,0.816276,-0.251294,-0.732924,-0.417214,-0.074133,0.793483,-0.241276,0.171531,0.515313,0.037035,-0.417475,-0.512201,0.197920,-0.214959,-0.050241,-0.567930,-0.240534,-0.177794,-0.080427,-0.221633,0.551370,0.186918,-0.325375,0.452399,0.359579,0.353461,0.019517,0.494815,-0.033201,0.216509,0.042112,0.105298,-0.371108,-0.076762,0.221815,-0.247542,-0.300382,0.342840,-0.195754,0.199877,0.521523,-0.302539,-0.267253,-0.071953,0.334858,-0.261842,0.086371,0.099538,-0.060159,0.232182,0.301793,0.455332,-0.030220,-0.191024,-0.179898,-0.065149,-0.574995,0.075168,-0.230692,0.321670,-0.492470,-0.037283,-0.182486,-0.061296,0.135670,-0.674925,0.164433,0.410386,0.479079,0.283455,-0.204866,-0.141880,-0.214916,0.129083,0.722799,-0.009575,-0.244238,0.548249,0.126341,-0.399171,-0.056254,0.049423,-0.491272,0.147836,0.402663,0.402177,-0.316249,0.432664,-0.476171,0.005378,-0.341053,-0.411942,0.242518,-0.426002,0.010499,-0.626320,-0.172846,-0.408013,-0.499695,-0.197623,-0.062610,-0.398543,0.481149,-0.746836,0.501437,0.543137,0.048164,-0.475881,0.475847,0.212340,0.232557,-0.115216,0.288823,0.632215,0.071360,0.229718,-0.148264,0.252105,0.409473,-0.329079,-0.578471,0.683478', '1309172', '2075721', '3014557', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291546', '霸王别姬', '剧情', '段小楼（张丰毅）与程蝶衣（张国荣）是一对打小一起长大的师兄弟，两人一个演生，一个饰旦，一向配合天衣无缝，尤其一出《霸王别姬》，更是誉满京城，为此，两人约定合演一辈子《霸王别姬》。但两人对戏剧与人生关系的理解有本质不同，段小楼深知戏非人生，程蝶衣则是人戏不分。段小楼在认为该成家立业之时迎娶了名妓菊仙（巩俐），致使程蝶衣认定菊仙是可耻的第三者，使段小楼做了叛徒，自此，三人围绕一出《霸王别姬》生出的爱恨情仇战开始随着时代风云的变迁不断升级，终酿成悲剧。©豆瓣', '张国荣', '陈凯歌', 9.6, 1996850, 'tt0106332', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2561716440.jpg', 0.1, 0.1, 1.9, 15.4, 82.4, '0.280658,-0.153297,-0.610983,0.403439,0.362002,-0.130996,0.478766,0.038380,-0.558129,-0.055837,0.120980,0.747214,-0.545982,0.001148,0.386230,-0.386139,0.226427,-0.825439,-0.195746,-0.047841,0.310302,-0.530403,0.082557,0.091582,-0.357509,-0.092493,0.699484,-0.045296,-0.138578,0.496934,0.580162,0.132156,-0.470557,-0.040605,0.076313,0.126094,-0.043784,0.323107,-0.628342,-0.060129,-0.027152,0.082397,-0.050619,-0.131941,-0.322150,0.095346,0.628790,-0.367919,-0.227949,-0.036800,0.470438,-0.092168,-0.330663,0.131551,0.284934,-0.083468,0.289228,0.410543,-0.030515,0.029560,-0.019335,0.044884,-0.491947,-0.031757,0.415088,0.009899,-0.250405,0.327783,0.276528,-0.460724,-0.106971,-0.053193,0.330802,0.374922,0.853390,0.498148,-0.200368,-0.251326,-0.270306,0.111165,1.027196,0.186587,0.014277,0.530199,-0.011662,-0.161057,-0.223615,-0.181622,-0.253810,0.011268,0.011240,0.202851,0.007261,0.586212,-0.331111,0.027845,0.218993,0.265044,0.311183,-0.626292,0.086677,-0.361062,-0.302053,-0.561542,-0.300626,0.080278,0.087863,-0.418685,0.843109,-0.885572,0.040022,-0.062012,-0.058320,-0.588193,0.561429,0.418811,0.389038,-0.297129,0.106208,0.254776,-0.168281,-0.330248,0.113979,0.214735,-0.198384,0.153291,-0.169272,0.240544', '1293265', '35030151', '35048413', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291548', '死亡诗社', '剧情', '威尔顿预备学院以其沉稳凝重的教学风格和较高的升学率闻名，作为其毕业班的学生，理想就是升入名校。新学期文学老师约翰·基汀（罗宾·威廉姆斯 饰）的到来如同一阵春风，一反传统名校的严肃刻板。基汀带学生们在校史楼内聆听死亡的声音，反思生的意义 ；让男生们在绿茵场上宣读自己的理想；鼓励学生站在课桌上，用新的视角俯瞰世界。老师自由发散式的哲学思维让学生内心产生强烈的共鸣，他们渐渐学会自己思考与求索，勇敢的追问人生的路途，甚至违反门禁，成立死亡诗社，在山洞里击节而歌！基汀教授、基汀老师、基汀队长，他的教育宛若春风化雨，润物无声的留在每个人心里…©豆瓣', '罗宾·威廉姆斯', '彼得·威尔', 9.1, 662188, 'tt0097165', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2575465690.jpg', 0.2, 0.5, 5.9, 28.7, 64.8, '0.200084,-0.132133,-0.456457,0.714419,-0.223457,0.108811,0.526046,0.254669,-0.457675,-0.163735,0.162911,0.476829,-0.110054,0.437761,0.219232,-0.474407,-0.363220,-0.786042,-0.176396,0.024138,-0.077115,-0.454305,0.097003,-0.155596,-0.171736,-0.471377,0.671690,-0.232100,-0.130711,0.657193,-0.103574,0.292099,0.226533,0.065278,-0.267559,-0.319243,0.063313,0.084953,-0.096639,-0.143480,0.096032,0.051401,-0.450890,-0.129824,0.032460,0.210276,0.708712,-0.043574,0.007907,0.238876,0.527234,-0.276962,-0.088673,0.164176,0.197219,0.287934,0.001660,0.317647,0.161795,0.257441,-0.391869,-0.334160,-0.541889,-0.116725,0.074814,0.294531,-0.284520,0.469653,0.027378,-0.243264,0.142364,0.017339,-0.199056,-0.245147,0.110535,0.670515,-0.105856,0.149637,0.139496,0.025232,0.325313,-0.098238,-0.689856,-0.043715,-0.493254,-0.414706,0.141943,-0.074829,-0.563878,-0.276738,0.009918,0.150660,0.262847,0.245680,-0.642217,-0.001796,-0.050653,-0.277968,-0.118694,-0.494244,-0.374444,-0.714885,0.039611,-0.200225,-0.123775,-0.190806,0.074106,-0.302039,1.047129,-0.952682,0.128694,0.256338,0.090754,-0.221752,0.637401,-0.101573,0.037212,-0.173320,-0.301177,0.221119,-0.025859,0.524867,-0.241575,0.678748,-0.175401,-0.015095,-0.277629,0.549945', '25922902', '3811356', '4127270', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291549', '放牛班的春天', '剧情', '1949年的法国乡村，音乐家克莱门特（热拉尔·朱尼奥 饰）到了一间外号叫“塘低”的男子寄宿学校当助理教师。学校里的学生大部分都是难缠的问题儿童，体罚在这里司空见惯，学校的校长（弗朗索瓦·贝莱昂 饰）只顾自己的前途，残暴高压。性格沉静的克莱门特尝试用自己的方法改善这种状况，他重新创作音乐作品，组织合唱团，决定用音乐的方法来打开学生们封闭的心灵。然而，事情并不顺利，克莱门特发现学生皮埃尔·莫安琦（让-巴蒂斯特·莫尼耶 饰）拥有非同一般的音乐天赋，但是单亲家庭长大的他，性格异常敏感孤僻，怎样释放皮埃尔的音乐才能，让克莱门特头痛不已；同时，他与皮埃尔母亲的感情也渐渐微妙起来。©豆瓣', '让-巴蒂斯特·莫尼耶', '克里斯托夫·巴拉蒂', 9.3, 1221807, 'tt0372824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910824951.jpg', 0.1, 0.2, 3.5, 25.6, 70.7, '0.266778,-0.026738,-0.362317,0.640896,-0.395661,-0.038048,0.568181,0.127633,-0.715596,-0.457206,-0.180361,0.556211,-0.068958,0.405514,0.234179,-0.032244,-0.323080,-0.508690,0.156448,0.014302,-0.288217,-0.524009,-0.081215,-0.556505,-0.155345,-0.412295,0.383289,-0.068976,-0.258951,0.206237,0.112914,0.467610,0.259326,0.315785,-0.023328,-0.156519,0.166769,-0.038133,0.091301,-0.001727,0.223292,-0.135170,-0.288317,0.273552,0.237635,0.287875,0.644611,0.008350,-0.173058,0.014343,0.374025,-0.043616,-0.194665,0.109749,0.344536,0.049891,0.150087,0.018608,-0.046838,0.064242,-0.248935,-0.096252,-0.472911,-0.029453,0.221318,-0.140239,-0.367857,0.149837,0.029205,-0.067052,0.053048,-0.372994,-0.095467,-0.077229,0.243671,0.532557,-0.144028,0.022270,-0.092532,0.048325,0.494794,-0.036388,-0.595476,0.329578,-0.777451,-0.628841,-0.131533,-0.296349,-0.575717,-0.067138,0.140042,0.061524,-0.034558,0.077905,-0.443968,-0.199023,0.061721,-0.105793,-0.213869,-0.365220,0.066494,-0.604168,-0.146600,-0.411808,-0.303682,-0.224962,-0.012386,-0.118767,0.921724,-0.764078,0.060738,0.508258,-0.002897,-0.381734,0.519895,-0.140536,0.113501,-0.244661,-0.401379,0.229913,-0.030686,0.081940,-0.068428,0.568035,0.109282,-0.205265,-0.290273,0.599661', '1303010', '26348103', '25882279', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291550', '天下无贼', '剧情', '王薄（刘德华 饰）和王丽（刘若英 饰）本是一对最佳贼拍档，但因怀了王薄的孩子，王丽决定收手赎罪，两人产生分歧。在火车站遇到刚刚从城市里挣了一笔钱准备回老家用它盖房子娶媳妇的农村娃子傻根（王宝强 饰）后，王丽被他的单纯打动，决定暗中保护不使他的辛苦钱失窃，王薄却寻思找合适机会下手，但 最终因为“夫妻情深”归入了王丽的阵营。 不料傻根的钱早被以黎叔（葛优 饰）为头目的另一著名扒窃团伙盯上，于是一系列围绕傻根书包里的钞票、在王薄、王丽和黎叔团伙之间展开的强强斗争上演。©豆瓣', '刘德华', '冯小刚', 8.1, 478642, 'tt0439884', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2191934463.jpg', 0.2, 1.2, 19.5, 52.3, 26.9, '0.276391,0.025949,-0.613323,0.063598,-0.205903,-0.262805,0.560793,0.281292,-0.240212,0.010223,0.075676,0.278668,0.106428,0.052893,0.056491,-0.079752,-0.193487,-0.515148,0.243225,0.016113,0.005352,-0.358921,-0.252269,-0.059675,-0.292986,0.191698,0.179883,0.072596,0.067703,0.510588,0.479522,-0.167703,-0.176683,0.259064,0.206825,0.171331,-0.014317,0.051743,-0.197171,0.305452,0.037133,-0.202596,-0.205449,0.002415,0.131014,0.621509,0.727926,0.000605,0.144222,-0.030392,0.272754,-0.210843,-0.337346,0.110754,0.135731,0.105795,0.373347,-0.041973,-0.333770,0.028715,0.320070,-0.137459,-0.410035,0.068179,0.238438,-0.202407,-0.732371,0.431427,0.026653,0.078589,0.078649,-0.456379,0.236783,0.417659,0.410670,0.224484,-0.177791,-0.044116,-0.400703,0.323458,0.314089,-0.206167,0.496691,0.212209,0.083084,-0.398106,0.068125,-0.049321,-0.138803,-0.124115,0.657733,-0.201356,-0.343803,-0.207831,-0.636741,-0.135652,-0.127320,0.089894,0.000150,-0.391109,0.018058,-0.268764,-0.296350,-0.272415,-0.358078,0.313439,0.028819,-0.172288,0.481535,-0.489803,-0.036652,0.551903,0.278584,-0.574868,0.409454,0.048929,0.284600,-0.153704,0.055984,-0.151286,0.042483,0.240662,0.401218,0.218530,-0.229940,-0.292021,-0.113310,0.253686', '1947080', '21619567', '1316560', '1310167');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291552', '指环王3：王者无敌', '剧情', '魔幻战争逐渐进入高潮阶段。霍比特人佛罗多（伊利亚·伍德 Elijah Wood 饰）携带着魔戒，与伙伴山姆（西恩·奥斯汀 Sean Astin 饰）以及狡猾阴暗的咕噜等前往末日山，一路上艰难险阻不断，魔君索伦为阻止魔戒被销毁用尽全力阻挠。另一方面，白袍巫师甘道夫（伊恩·麦克莱恩 Ian McKellen 饰）率中土勇士们镇守刚铎首都——白城米那斯提里斯。魔兽大军压境，黑暗与光明的决战即将来临……本片是“指环王三部曲”的终结篇，根据英国作家J.R.R.托尔金（J.R.R. Tolkien）同名魔幻巨著《指环王》（The Lord of the Rings）改编，并荣获2004年第76届奥斯卡最佳影片、最佳导演、最佳改编剧本、最佳剪辑、最佳艺术指导、最佳服装设计、最佳化妆、最佳视觉效果、最佳音效、最佳配乐和最佳歌曲等11项大奖。©豆瓣', '伊利亚·伍德', '彼得·杰克逊', 9.3, 748987, 'tt0167260', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2642829472.jpg', 0.2, 0.4, 5.1, 24.2, 70.1, '-0.386915,0.002309,-0.403349,0.652887,0.735363,0.079303,0.265904,-0.204015,-0.237065,-0.468941,0.336598,0.701606,-0.071052,-0.379930,0.537873,-0.242508,-0.599578,-0.592861,-0.078393,-0.029979,0.010360,-0.193092,-0.545761,0.347964,-0.242354,-0.498922,0.950682,-0.027578,-0.292019,0.465150,0.459429,0.110129,-0.264634,-0.126147,0.061241,-0.025225,0.450864,-0.591894,-0.678887,0.723502,-0.123405,-0.119041,-0.284348,-0.023215,0.038268,0.132274,0.760849,-0.559141,0.358205,0.245583,0.571255,-0.486005,-0.253770,0.085216,0.112159,-0.274892,0.111107,0.135752,0.292641,0.460600,-0.311334,-0.517946,-0.848108,0.086843,0.052828,0.152676,-0.199662,0.040987,0.015162,0.277218,0.357368,0.160552,0.162545,0.188629,0.752811,0.020748,-0.035172,-0.084447,0.153639,0.765189,-0.019208,-0.116573,-0.257347,0.078835,0.167183,-0.892332,-0.103185,-0.160702,-0.450999,0.124313,0.556503,0.273651,0.430394,0.200604,-0.785288,-0.073769,-0.173286,-0.506078,-0.005404,0.079219,0.145503,-1.294215,0.062164,0.134356,0.238199,-0.156017,0.113124,-0.185203,0.555313,-0.205536,0.381129,0.306353,0.039117,-0.055034,0.425617,-0.083024,0.294563,-0.455520,-0.182425,0.484278,0.002724,0.297845,0.022827,0.246018,0.158352,-0.228432,-0.424765,0.435173', '34961898', '2369613', '401