INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291553', '青木瓜之味', '剧情', '十岁时，梅（阮如琼 饰）被邻居送到西贡一大户人家当女佣。因为长得很像女主人死去的女儿，梅深受女主人的疼爱，但女主人并没因此看到生活的亮色，她的音乐家丈夫时不时就会不做交代外出数日，后来更是消失得再无踪迹。女主人的三个儿子因为整日无所事事，常拿梅寻开心，但慢慢地，他们发现家里的生气，全是由温和善良的梅带来。十年转眼而过，梅（陈女燕溪 饰）出落得更具“古典美”，女主人因支持不住家里的开销开始变卖家产，并忍痛将梅送到另一户人家当佣人。新东家是位年轻的钢琴家，他是女主人儿子的朋友，梅在年少初见他时，就曾投下过爱慕的目光，而钢琴家也在同梅的接触中，逐渐感受到她的款款温情。©豆瓣', '陈女燕溪', '陈英雄', 7.8, 66025, 'tt0107617', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p477906875.jpg', 0.4, 2.2, 25.9, 49.4, 22.1, '0.163096,-0.078399,-0.619312,0.450969,-0.383320,-0.353834,0.908577,0.064136,-0.723921,-0.612391,-0.018706,0.765780,-0.231541,0.768675,0.286899,0.126732,0.161492,-0.528604,-0.099725,-0.164614,-0.147168,-0.250816,0.193304,-0.386641,-0.204510,-0.202727,0.369881,0.112064,-0.062886,0.414488,0.249876,0.125831,-0.102258,0.430701,-0.409029,0.097784,-0.327864,0.139728,-0.103029,0.164451,0.014880,-0.350873,-0.173642,0.007656,0.206863,0.502003,0.656069,-0.073314,-0.186368,-0.165652,0.510476,0.153417,0.103811,0.003170,0.388772,-0.189336,0.123941,-0.072356,-0.260485,-0.085629,-0.155351,-0.410699,-0.339574,0.281303,0.140626,0.130257,-0.733928,0.399540,0.132437,-0.110066,-0.129268,-0.149466,0.426434,-0.109835,-0.185833,0.512072,-0.157649,0.391359,-0.584592,0.318129,0.490438,0.186531,-0.041361,0.642015,-0.325953,-0.364621,0.345014,-0.574293,-0.470296,0.106230,0.114520,0.245623,-0.023506,0.015849,-0.343443,-0.037523,-0.171255,0.047323,0.289312,-0.347300,-0.164755,-0.446602,0.017081,-0.608885,-0.448314,0.315433,-0.202282,-0.311490,0.580084,-0.942089,0.291560,0.227060,0.247762,-0.676494,0.702135,0.031124,0.036400,-0.007079,-0.014590,0.468293,0.201022,-0.072076,0.305519,-0.011250,-0.375766,-0.191551,0.005270,0.396295', '1302384', '1308755', '3111650', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291554', '歌剧魅影', '剧情', '巴黎歌剧院合唱团的新人克莉斯汀（艾米•罗苏姆 Emmy Rossum 饰）最近进步神速，全因剧院内的一间古老房间内每晚都会传出一把优美的男声向她传授歌唱技巧。这个良师益友其实是一个人称“剧院魅影”（杰拉德•巴特勒 Gerard Butler 饰）的人，此人因样貌丑陋，自小便被父母抛弃，戴着面具隐居在剧院的地下室。“剧院魅影”内心其实深爱着克莉斯汀。一次偶然的机会，克莉斯汀有幸担当一部歌剧的主角。凭借从“剧院魅影”那里学得的丰富的歌唱技巧，克莉斯汀一炮而红，并被年轻英俊的剧院赞助人拉乌尔（帕特里克•威尔逊 Patrick Wilson 饰）看上了。两个年轻人很快堕入了爱河。“剧院魅影”伤透了心，认为是拉乌尔抢走了克莉斯汀，准备上演一出爱情复仇的大戏……©豆瓣', '杰拉德·巴特勒', '乔·舒马赫', 8.5, 153633, 'tt0293508', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1910825990.jpg', 0.2, 1.2, 13.8, 42, 42.7, '0.261088,0.126121,-0.443779,0.325295,-0.014800,-0.142143,0.934600,0.048329,-0.402159,-0.180740,0.404337,0.714322,-0.163705,0.223624,0.454296,0.117969,-0.526440,-0.640713,-0.023747,-0.273151,0.013004,-0.146949,0.049705,-0.072367,0.028923,-0.673157,0.354676,0.080384,-0.139599,0.594487,0.436390,0.051370,-0.058197,-0.094630,0.049648,-0.091553,0.361817,-0.091812,0.122107,0.424321,-0.255223,-0.284819,-0.089862,0.206055,-0.156218,0.206097,0.527058,-0.028865,0.051666,-0.081236,0.558805,0.124652,-0.077825,0.092794,0.193078,-0.360453,0.072448,0.147093,-0.205971,-0.186520,-0.117663,-0.377020,-0.763089,0.186411,0.214382,0.168130,-0.353236,0.294464,-0.080952,0.053953,-0.126004,-0.040004,-0.081124,-0.295666,0.256069,0.395840,0.018671,0.325109,-0.204916,0.237943,0.395193,0.093720,-0.040217,0.371708,-0.333206,-0.496670,-0.056747,0.044789,-0.552099,0.006057,0.549236,-0.296211,0.116834,-0.096467,-0.318082,-0.063743,-0.261591,0.057287,0.002157,-0.299815,-0.214383,-0.851862,-0.040026,-0.272873,-0.006222,-0.119884,-0.133391,-0.240183,0.599953,-0.636638,0.261095,0.403732,0.020581,0.202904,0.754120,-0.156383,0.113136,-0.002406,-0.034733,0.567631,-0.035818,-0.197507,-0.165779,0.431352,0.135501,-0.243131,-0.510913,0.476334', '1316693', '10466639', '1301686', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291555', '2046', '剧情', '1966年，从新加坡返回香港想忘掉过去的周慕云（梁朝伟 饰）住进东方酒店的、同他曾经熟悉的数字2046只差一号的2047号房，开始了他的卖文生涯。眼前、曾经在他身边出现过的一个个女人（章子怡、王菲、张曼玉、刘嘉玲等 饰）经过他大脑的过影后，令他对时空产生疑惑，不但忘不了过去，一幕幕往事反而更加挥之不去。为了与过去作更好的告别，他将生活的点点滴滴化为文字，写下小说《2046》（说只要搭上了前往2046的列车，人们就可以找回失去的记忆）。©豆瓣', '梁朝伟', '王家卫', 7.7, 219008, 'tt0212712', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359293069.jpg', 0.7, 3.5, 30, 43.4, 22.5, '0.229948,0.178398,-0.797398,0.677664,0.143188,-0.461421,1.060769,-0.206225,-0.621439,-0.151980,-0.078894,0.700225,-0.210877,0.557739,0.414539,0.053894,-0.299568,-0.900250,0.008434,-0.332254,-0.187253,-0.266520,-0.141752,-0.130198,-0.212380,-0.377000,0.605117,0.163299,-0.085679,0.557353,0.228657,0.045992,-0.179236,0.497559,-0.302126,0.355732,-0.349170,0.322752,-0.614633,0.082372,0.368953,-0.261823,-0.020768,0.032908,-0.086048,-0.096201,0.786290,-0.102898,-0.253751,0.181057,0.345951,-0.090901,-0.252886,0.079007,0.007469,0.524520,0.246386,0.199625,-0.304322,0.244055,-0.226128,-0.046255,-0.463655,0.088732,0.028421,0.165579,-0.647674,0.224960,-0.198576,0.062899,0.140469,-0.615791,0.220617,-0.047302,0.376858,0.288776,-0.351433,-0.030081,-0.352368,0.566507,0.707020,0.048744,-0.214105,0.501273,0.170790,-0.261354,-0.447377,0.108928,-0.162337,0.355234,0.155954,0.154575,-0.406797,0.271822,-0.567881,-0.198383,-0.156757,-0.512231,0.288133,-0.373483,-0.158442,-0.484069,-0.442150,-0.281067,-0.282000,-0.004632,-0.117716,-0.405494,0.609024,-0.822381,0.380468,0.503651,0.392190,-0.503915,0.536364,0.098889,-0.161961,-0.141742,0.144229,0.610564,0.025151,0.590459,0.003897,0.149266,-0.333306,0.115660,-0.544350,0.714828', '1296534', '3111650', '21348112', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291556', '乡愁', '剧情', '俄国诗人安德烈（奥列格·扬科夫斯基 Oleg Yankovsky 饰）在美丽的女翻译尤金伲亚（多美兹亚娜·佐丹奴 Domiziana Giordano 饰）的陪同下，一同前往意大利寻访一位十八世纪俄国作曲家的生活。他们一起走访充满宗教意象的乡村教堂，在一座有天然温泉的古老小镇停留。 此时他遇见了不被世人理解的疯人多米尼克（厄兰·约瑟夫森 Erland Josephson 饰），村民因为他早些年囚禁家人而认为他神经失常。可安德烈看到了多米尼克疯狂下的深意，并被他所吸引。同时他拒绝了性感的尤金伲亚的示爱。此时的安德烈，游走在支离破碎的现实与超现实的梦境中不能自拔。他对祖国的思念、与家人的分离……种种情愫混杂在一起，彼此纠缠，化为终生的乡愁。本片获1983年戛纳电影节最佳导演奖，普通评审团奖，国际影评人费比西奖。©豆瓣', '奥列格·扬科夫斯基', '安德烈·塔可夫斯基', 9.1, 35135, 'tt0086022', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2594191712.jpg', 0.7, 1.1, 6.5, 26.2, 65.6, '0.363414,-0.039729,-0.687175,0.603023,0.164021,-0.104047,0.838286,0.124316,-0.373325,-0.072709,0.150477,0.918293,-0.353574,0.166169,0.144360,0.104400,-0.507463,-0.722798,-0.099026,-0.159860,-0.080452,-0.509623,-0.071792,-0.018570,-0.288764,-0.267713,0.599129,0.100786,0.029647,0.590083,0.195433,0.357244,-0.150550,0.368637,-0.092843,0.077577,0.274172,-0.032236,-0.365824,0.151448,-0.013483,-0.249963,-0.164361,0.116367,-0.107730,0.150610,0.634882,-0.294902,0.275253,0.046579,0.401859,-0.270514,0.129544,0.104255,0.033624,-0.156587,-0.003726,0.199653,-0.319719,-0.057076,0.042828,0.032095,-0.444800,0.041752,0.194738,0.123025,-0.495153,0.598044,0.286628,0.008655,-0.125816,-0.158986,0.213785,0.078164,0.230400,0.256475,0.104269,0.030652,-0.395800,0.346343,0.651067,-0.000265,-0.297368,0.103837,-0.668253,-0.546324,-0.266625,-0.036410,-0.624666,-0.093380,0.393033,-0.065792,-0.062663,0.386920,-0.644871,-0.164658,-0.216889,-0.167550,-0.054197,-0.230301,-0.173641,-0.654317,-0.205631,-0.438296,-0.334948,-0.181692,0.203000,-0.072660,0.588457,-0.625847,0.352198,0.734029,0.395891,-0.162195,0.921315,0.041896,-0.070611,0.014583,-0.379569,0.660785,-0.034436,0.042448,0.139097,0.430891,-0.073854,0.177189,-0.368637,0.529664', '30162520', '3055049', '1309172', '3154392');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291557', '花样年华', '剧情', '1960年代的香港，报馆编辑周慕云（梁朝伟 饰）与太太搬进一间住户多是上海人的公寓，和某家日资公司的贸易代表陈先生与太太苏丽珍（张曼玉 饰）成了邻居。因为发现各自在外工作的配偶背着他们有了婚外情，周慕云和苏丽珍开始见面商讨未来可能发生的事情以及相应对策。起初两人是君子之交淡如水就事谈事，可是日子一日接一日过去后，在周围一帮上海邻居的闲言碎语中，他们发现配偶的事早空出了他们的脑袋，彼此眼里只剩下了对方，而刻意回避已生出的感情的结果，是更加刻骨的相思。©豆瓣', '梁朝伟', '王家卫', 8.7, 555719, 'tt0118694', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910828286.jpg', 0.2, 0.6, 9.8, 41.3, 48.1, '0.595293,-0.313560,-0.561644,0.144180,0.259950,-0.177180,0.665425,0.191801,-0.835733,-0.401602,-0.079662,0.621977,-0.237850,0.462850,0.113076,-0.105459,-0.341362,-0.826265,0.116856,-0.352132,-0.059304,-0.362385,0.096806,-0.392121,0.087774,-0.012372,0.354584,0.204314,0.050926,0.459386,0.203088,0.080336,-0.321354,0.624490,-0.012633,0.075668,0.075950,0.331957,-0.598280,0.056898,0.201599,-0.144848,-0.376825,-0.076894,0.078361,0.647905,0.411327,0.088994,-0.323359,0.039455,0.136107,-0.050893,0.029214,0.203689,0.570085,0.045587,0.608728,0.485373,-0.366823,0.026127,0.028296,0.198889,-0.235186,0.072257,0.139146,0.243244,-0.574086,0.385279,-0.032912,-0.187002,0.066692,-0.457612,0.408423,0.198235,0.135583,0.283502,-0.109203,-0.134858,-0.640070,0.100054,0.702966,-0.093679,-0.038221,0.475640,0.003496,-0.386792,-0.247369,-0.091517,-0.255583,-0.154086,0.054009,0.113715,-0.077895,0.183254,-0.742587,-0.123902,0.037040,-0.289879,0.097123,-0.509235,0.153246,-0.623182,-0.297994,-0.600317,-0.370986,0.114061,0.398300,-0.024887,0.459344,-0.877711,-0.061640,0.345751,0.455496,-0.681878,0.888899,0.067739,0.313881,-0.211657,0.084640,-0.509642,-0.232769,0.168216,0.204992,0.166939,-0.003842,-0.053263,-0.234750,0.179684', '1308755', '1302384', '3055049', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291558', '云上的日子', '剧情', '1，费拿拉小镇，工程师斯瓦诺（Kim Rossi Stuart 饰）邂逅了女教师卡门（Inés Sastre 饰），他们一见钟情，卡门却拒绝了斯瓦诺的吻。当他们三年后再次相遇时，斯瓦诺则在肉欲面前止步；2，海滨小城，某导演（John Malkovich 饰）信步游荡时遇到了美丽的女子（Sophie Marceau 苏菲•玛索 饰）。她向导演坦白曾亲手杀害自己的父亲。他们并未因此疏远，反而缱绻缠绵；3，巴黎，妻子离开不忠的丈夫，寻找租房时遇到了失去妻子的卡罗（Jean Reno 让•雷诺 饰），他们似乎找到了共通的心绪；4，英俊的男孩爱上了一个姑娘（Irène Jacob 饰），他尾随、表白，却得知她将要把自己献给上帝。本片荣获1996年意大利电影新闻记者协会银丝带奖最佳编曲、1995年威尼斯电影节费比西奖。©豆瓣', '苏菲·玛索', '米开朗基罗·安东尼奥尼', 7.6, 66739, 'tt0114086', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504035234.jpg', 0.7, 3.6, 30.4, 44, 21.3, '0.040126,0.062582,-0.451713,0.464061,-0.032311,-0.478668,0.683865,0.168120,-0.376747,-0.198845,0.287353,0.759846,-0.278576,0.152023,0.429838,0.231028,-0.390537,-0.787368,0.079228,-0.263429,0.000866,-0.131443,-0.204361,0.101939,-0.063804,-0.234208,0.610231,0.026372,-0.092564,0.523636,0.353191,0.146404,-0.003543,0.299134,-0.090729,0.179214,0.345118,0.141845,-0.259957,0.268523,-0.132473,-0.352025,-0.306155,0.071499,-0.086209,0.311633,0.775440,-0.059578,-0.039142,-0.267577,0.505659,-0.184423,0.233571,0.055282,0.029728,0.011027,0.218043,0.234852,-0.307719,-0.134561,0.149935,-0.057778,-0.256504,0.277201,0.147576,-0.077015,-0.495204,0.238255,-0.184150,0.204707,0.095176,-0.292169,0.126952,0.156891,0.327595,0.066997,0.076456,0.066670,-0.328611,0.525339,0.556360,0.136960,-0.030824,0.210546,-0.108505,-0.476573,0.096287,-0.023420,-0.519093,0.318314,0.340947,0.130156,-0.073793,0.100076,-0.407469,-0.442738,-0.368047,0.049889,0.285222,-0.328277,-0.263222,-0.726853,-0.105214,-0.169027,-0.277961,-0.183077,-0.228470,0.036682,0.521243,-0.702902,0.276903,0.717359,0.547917,-0.365141,0.903002,0.046242,-0.161950,-0.198964,-0.032039,0.630208,-0.201316,0.139098,0.053622,0.111225,-0.101086,-0.035090,-0.188247,0.442228', '3326747', '1307200', '1294565', '25785124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291559', '新桥恋人', '剧情', '米歇尔（朱丽叶·比诺什 Juliette Binoche 饰）是个富家女，心里却并不幸福。她失恋，患上眼疾，情绪低落之下决定到外面的世界去流浪。她喜欢画画，在街头遇到断了腿的埃里克斯（德尼·拉旺 Denis Lavant 饰），画下了他抽搐的脸。克劳斯是个一无所有的流浪汉，却爱上了米歇尔。两人开始了热恋，流浪中互相取暖互相疗伤。米歇尔的视力慢慢模糊，她的心愿是在失明前看看博物馆的画。满街都贴着米歇尔家人的寻人启事，埃里克斯感到米歇尔即将离他而去，悲伤不已。他用枪打碎自己的手指以宣泄痛苦，疯狂的烧掉寻人通知，却没有留得住一段即将幻灭的感情。然而，米歇尔最后还是提出分手，重新回到她原来生活的世界。后来米希尔终于在飘雪的圣诞夜跟埃里克斯在烟花灿烂的塞纳河上重逢。©豆瓣', '朱丽叶·比诺什', '莱奥·卡拉克斯', 8.1, 49056, 'tt0101318', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p581792602.jpg', 0.6, 2.2, 19.2, 46, 32, '0.275531,0.078787,-0.747934,0.445033,-0.008748,-0.603556,0.916751,-0.066496,-0.072484,-0.091738,0.312537,0.674097,-0.298366,0.603618,0.027754,0.237372,-0.386732,-0.756828,0.127426,-0.183459,-0.331582,-0.362810,-0.277202,-0.154979,-0.174501,-0.063241,0.518031,0.098141,0.050559,0.369851,0.144133,0.169952,0.009750,0.384914,-0.366393,0.045415,-0.141621,-0.028023,-0.209134,-0.026343,0.273360,-0.115639,-0.233303,0.171792,-0.003577,0.369201,0.631908,-0.250774,0.047389,0.103631,0.282458,-0.316484,0.004132,0.152039,0.029376,-0.008890,0.044414,-0.311411,-0.284892,-0.092653,0.060246,0.054586,-0.338390,0.115194,0.017928,0.381349,-0.304489,0.495499,-0.149881,0.033218,0.132056,-0.521524,0.264424,0.113839,0.152046,0.524231,-0.222266,0.090825,-0.292129,0.088651,0.724980,0.153000,-0.256484,0.502727,-0.455219,-0.050563,-0.039339,-0.067725,-0.555970,-0.162671,0.317489,0.011765,-0.222283,0.289742,-0.542379,-0.075636,-0.311093,-0.108287,-0.099387,-0.200331,-0.085519,-0.458909,-0.252177,-0.308180,-0.334111,0.062734,-0.035818,-0.429921,0.313883,-0.681630,0.274819,0.628656,0.129639,-0.100228,0.470580,0.206545,-0.173651,0.021941,0.057239,0.634326,0.017020,0.352810,0.175761,0.290076,-0.010089,0.359390,-0.622003,0.810830', '1309172', '1296534', '1297598', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291560', '龙猫', '动画', '小月的母亲生病住院了，父亲带着她与四岁的妹妹小梅到乡间的居住。她们对那里的环境都感到十分新奇，也发现了很多有趣的事情。她们遇到了很多小精灵，她们来到属于她们的环境中，看到了她们世界中很多的奇怪事物，更与一只大大胖胖的龙猫成为了朋友。龙猫与小精灵们利用他们的神奇力量，为小月与妹妹带来了很多神奇的景观，令她们大开眼界。妹妹小梅常常挂念生病中的母亲，嚷着要姐姐带着她去看母亲，但小月拒绝了。小梅竟然自己前往，不料途中迷路了，小月只好寻找她的龙猫及小精灵朋友们帮助。©豆瓣', '日高法子', '宫崎骏', 9.2, 1185485, 'tt0096283', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540924496.jpg', 0.1, 0.2, 5.8, 29.5, 64.3, '0.219222,-0.277035,-0.669042,0.529115,-0.315804,-0.119543,0.726612,-0.207158,-0.944293,-0.393917,0.113895,0.832770,-0.305567,0.634117,0.125686,0.012265,-0.396034,-0.278098,0.167757,-0.180996,-0.377708,-0.076480,-0.233115,-0.147237,-0.323897,-0.178097,0.171403,-0.061185,0.110207,0.498467,-0.183060,0.009188,-0.341580,0.553748,-0.273725,0.379875,-0.139951,0.038199,-0.158167,0.042658,0.258228,0.139458,-0.213037,0.090966,0.147533,-0.019678,0.883908,-0.709118,-0.377040,-0.419344,0.271969,-0.289568,0.216492,0.127678,0.015402,0.185610,0.525450,-0.274800,-0.272959,0.048396,0.045340,-0.284630,-0.367600,0.463251,0.294979,0.143630,-0.559294,0.088156,0.081322,-0.097497,0.371008,-0.629393,0.242478,0.295275,-0.167449,0.550262,-0.426167,-0.027584,-0.515893,-0.162056,0.728858,-0.105943,0.184330,0.341381,-0.228594,-0.388917,0.259669,-0.094751,-0.445506,0.310054,0.119090,0.206261,-0.320012,0.187174,-0.699790,0.124707,0.052538,-0.273099,-0.046657,-0.626557,0.017769,-0.517524,0.203695,-0.671619,-0.209862,0.083035,0.189421,-0.295017,0.876669,-0.996899,0.182498,0.322768,0.626454,-0.626651,0.662934,-0.217796,0.243857,-0.042793,-0.271910,0.037866,-0.202285,0.226819,0.301500,0.390449,0.055834,-0.022319,-0.494786,0.247995', '1292219', '3445516', '27191431', '1292900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291561', '千与千寻', '剧情', '千寻和爸爸妈妈一同驱车前往新家，在郊外的小路上不慎进入了神秘的隧道——他们去到了另外一个诡异世界—一个中世纪的小镇。远处飘来食物的香味，爸爸妈妈大快朵颐，孰料之后变成了猪！这时小镇上渐渐来了许多样子古怪、半透明的人。千寻仓皇逃出，一个叫小白的人救了他，喂了她阻止身体消 失的药，并且告诉她怎样去找锅炉爷爷以及汤婆婆，而且必须获得一份工作才能不被魔法变成别的东西。千寻在小白的帮助下幸运地获得了一份在浴池打杂的工作。渐渐她不再被那些怪模怪样的人吓倒，并从小玲那儿知道了小白是凶恶的汤婆婆的弟子。一次，千寻发现小白被一群白色飞舞的纸人打伤，为了救受伤的小白，她用河神送给她的药丸驱出了小白身体内的封印以及守封印的小妖精，但小白还是没有醒过来。为了救小白，千寻又踏上了她的冒险之旅。©豆瓣', '柊瑠美', '宫崎骏', 9.4, 2097939, 'tt0245429', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2557573348.jpg', 0.1, 0.2, 3.3, 23.2, 73.2, '0.326584,0.207651,-0.562722,0.443830,-0.450011,-0.200994,0.648742,0.246430,-0.324691,0.032815,0.254958,0.782963,0.257154,0.150000,-0.000480,0.299181,-0.095034,-0.378714,-0.015572,-0.343744,-0.602177,-0.155988,-0.192434,-0.016695,0.068359,-0.352384,0.472151,-0.083910,-0.038852,0.384923,0.036565,-0.084431,-0.081150,0.596910,-0.401712,0.266806,0.008295,-0.221940,0.190816,0.376487,0.149802,-0.332888,-0.108905,0.244546,0.066508,0.286484,0.773351,-0.279823,-0.160157,-0.301056,0.120209,-0.238892,-0.057479,-0.043148,0.098462,-0.015733,0.212786,-0.079182,-0.421218,-0.055414,0.083400,-0.030515,-0.502733,0.152200,0.007846,0.191667,-0.632405,0.386720,0.106496,0.029546,0.208422,-0.568904,0.206178,0.161386,-0.056306,0.435736,-0.290015,0.031999,-0.736862,-0.004631,0.581592,-0.162521,0.113519,0.425826,0.006549,-0.090907,0.192701,-0.149837,-0.217979,-0.056465,0.525108,0.138561,-0.567803,-0.100982,-0.746601,-0.052271,-0.309517,-0.291550,-0.052947,-0.338960,-0.397887,-0.218529,-0.008906,0.032494,-0.085972,0.002949,-0.110652,-0.149538,0.626184,-0.631896,0.370759,0.582300,0.204416,-0.473308,0.495052,-0.228553,0.087347,0.003645,-0.048490,0.016351,0.078998,0.755097,0.523900,0.527355,0.029907,0.025213,-0.620455,0.253687', '21619567', '1316560', '26678509', '1294037');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291562', '黑暗中的舞者', '剧情', '在美国某个乡村工厂做工的捷克移民塞尔玛（比约克）天性善良，因患有先天性疾病，她的视线正日趋模糊。为了不让遗传了该病的儿子也将宿命继承，塞尔玛每日做工都很辛苦，不知情的好友兼同事林达（凯萨琳•丹妮芙）因心疼而好言相劝时，她总是报一微笑，因为她还有另一个纯粹属于音乐的世界，其间的美好与安静，足以抵挡现实的心酸与艰难。令她欣慰的是，在眼睛要彻底变瞎之前，基本筹齐了儿子手术所需的费用，然而就在此时，意外发生，她的命运被加速推向复杂悲惨的境地。©豆瓣', '比约克', '拉斯·冯·提尔', 8.2, 79771, 'tt0168629', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910831341.jpg', 1.7, 3.6, 16.4, 38.1, 40.1, '0.164298,0.216524,-0.742487,0.304551,-0.137966,-0.110513,0.901786,0.254759,-0.491098,-0.220313,0.189738,0.644159,0.167947,0.241744,0.081945,0.120713,-0.114817,-0.437910,-0.117200,-0.019164,-0.236225,-0.410762,-0.110431,-0.363268,-0.147093,-0.575244,0.563084,0.169117,0.008218,0.341646,0.103098,0.475081,-0.062165,0.408507,-0.232765,-0.139191,-0.168353,0.008858,-0.111083,-0.127878,0.187603,-0.178696,-0.115558,0.422636,-0.169170,0.320568,0.734141,-0.006695,-0.341330,-0.039063,0.384929,-0.177130,-0.082515,0.131541,0.053685,-0.046069,0.175073,-0.034130,-0.256968,-0.138417,0.216416,0.138338,-1.056615,0.061806,0.305527,0.120240,-0.458410,0.559708,-0.098723,-0.206441,0.163136,-0.290012,0.148362,0.372726,0.334880,0.668869,-0.155385,0.208055,-0.281528,0.192311,0.573131,0.059035,-0.439811,0.646726,-0.586183,-0.328044,0.110257,-0.476989,-0.501270,0.177096,0.298173,0.202452,-0.240136,0.533861,-0.283120,0.284464,-0.128483,-0.207546,-0.119030,-0.524355,-0.200808,-0.210870,-0.083336,-0.450575,-0.440737,-0.089416,0.032193,-0.269132,0.727819,-0.671712,0.275448,0.588994,0.079284,-0.451607,0.590709,0.164306,0.259978,-0.154542,-0.140731,0.338597,-0.149359,0.259185,0.192064,0.202756,-0.120356,0.232740,-0.428210,0.575091', '6745433', '26678784', '1303077', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291563', '十分钟年华老去：小号篇', '剧情', '《十分钟年华老去 大提琴篇》的姊妹篇，由七位知名导演各自执导摄制而成，共同讲述发生在短暂十分钟里的人情冷暖。《狗没有地狱》里刑满出狱的男人带着女友一起远走故乡莫斯科，是坚贞的爱情与灵魂的回归；《生命线》中由呱呱坠地的新生儿讲起，平静安详；《几千年前》讲述的是现代文明带给原始部落的冲击跟入侵；《国际组织·拖车·夜晚》借休息的女演员视角，透视着大千世界里的形形色色；《距离托那12英里》是挣扎在生死线上的宝贵十分钟；《我们将被掠夺》发生在戈尔竞选总统失败的最后十分钟里；《百花深处》向我们讲述一段“模拟搬家”的荒唐闹剧。©豆瓣', '冯远征', '陈凯歌', 8.5, 25655, 'tt0304808', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p642799654.jpg', 0.3, 0.8, 12.4, 45.7, 40.8, '0.267707,0.171143,-0.620225,0.455467,-0.021601,0.009545,0.753441,-0.451361,-0.444039,-0.144429,-0.008819,0.658568,-0.362292,0.400141,0.347979,-0.025375,-0.311107,-0.836000,-0.345753,-0.231514,-0.087889,-0.499188,-0.493267,0.245145,0.106269,-0.261070,0.508459,0.243698,-0.064387,0.534059,0.119057,-0.074129,-0.361022,0.042119,-0.205315,-0.015632,-0.121289,0.113322,-0.444265,0.357549,0.110578,-0.464623,0.088586,-0.157461,-0.070156,0.306017,0.788798,-0.434383,0.121697,-0.036493,0.498330,-0.208615,-0.258375,0.077409,0.380855,0.572374,0.101311,0.615683,-0.439045,0.087170,-0.131236,-0.207656,-0.549215,-0.142788,-0.099005,0.452615,-0.531366,0.523422,0.184033,-0.018949,0.406659,-0.142879,0.360811,0.254701,0.275700,0.708645,0.014431,0.017249,-0.296500,0.310839,0.761883,-0.127024,-0.337740,0.089605,-0.006146,-0.250730,0.022314,-0.299292,-0.547108,-0.234440,0.018069,0.112446,-0.284316,0.278359,-0.684827,0.414459,-0.136337,-0.419613,0.006211,-0.212365,-0.078530,-0.989500,-0.111145,-0.440361,0.096360,0.138999,0.053588,-0.289170,0.597012,-0.448156,0.487582,0.436400,0.579451,0.024060,0.870984,0.056469,0.262048,-0.149730,0.453250,0.382593,-0.291108,0.441524,0.116750,0.345997,-0.191982,0.255619,-0.734093,0.447719', '10466639', '24751811', '1306860', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291564', '十分钟年华老去：大提琴篇', '剧情', '大师们的命题作文，八位电影大师用各自的手法为我们解读了时间的含义。贝纳多•贝托鲁奇在印度寓言中寻找答案，10分钟恋爱、结婚、生子，生活如水；迈克尔•菲吉斯将屏幕分成四块，让灵魂回望10分钟，把楼梯作为生死通道；伊利•曼佐的镜头下，老去的电影明星回顾黑白电影的片段，10分钟，已是好几个人生；......最后，让•吕克•戈达尔选择了10个“最后的几分钟”，试图告诉人们时间的真相，也让人思索，时间的几分钟会是什么样子？©豆瓣', '瓦莱丽亚·布鲁尼·泰德斯基', '贝纳尔多·贝托鲁奇', 8.2, 14676, 'tt0318742', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910831868.jpg', 0.3, 1.5, 17.4, 47.8, 33, '0.061963,0.091229,0.025935,0.579757,0.050544,-0.323556,0.444354,-0.113209,-0.350574,-0.365083,-0.196381,0.710998,-0.587198,0.166779,0.230852,0.031953,-0.540371,-1.052748,-0.004813,-0.311419,-0.228551,-0.470886,0.104048,-0.221110,0.174729,-0.306229,0.636045,0.237756,0.234705,0.056351,0.120588,-0.110444,0.028165,-0.095455,0.031782,0.136952,0.119896,-0.417031,-0.268444,0.234486,0.141803,-0.376848,-0.111805,0.236340,-0.206900,0.535852,0.951901,0.036897,-0.069622,0.425032,0.250902,-0.244428,-0.158398,-0.003292,0.180636,-0.131526,0.394763,0.476240,-0.227517,0.128297,-0.091226,0.140152,-0.792174,-0.033036,-0.159420,0.249939,-0.295753,0.137147,-0.079825,0.013326,0.218095,-0.118118,0.179249,0.425348,0.706314,0.365249,-0.356443,-0.434230,-0.371508,0.310984,0.407636,0.050302,-0.196857,0.638655,-0.035936,-0.514740,-0.411232,-0.155422,-0.199535,0.083920,0.466542,0.406849,-0.379828,0.221796,-0.616552,-0.024628,-0.213687,-0.487231,0.167924,-0.766204,-0.080528,-0.726167,-0.118081,-0.178130,-0.326066,-0.252822,0.065116,-0.100629,0.826833,-0.223066,0.084597,0.333866,0.235770,-0.185069,1.314073,0.050711,-0.058113,-0.115996,0.762233,0.094249,-0.169606,0.280698,0.078290,0.567373,0.095499,-0.039388,-0.674385,0.577105', '30135942', '2027945', '6537486', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291565', '疯狂约会美丽都', '喜剧', '查宾是一个孤独的孩子，从小失去双亲的他每天跟苏沙婆婆相依为命。男孩有点自闭，喜欢跟小狗布鲁诺说话，喜欢独自骑单车。美丽都三姊妹的歌声陪伴他们过着平静日子。终于，婆婆看出了查宾单车方面的天分，要把他培养成才，于是风雨不改的陪孩子训练。查宾终于可以参加环法自行车大赛了。然而却因为黑手党要控制赛果而出了意外，查宾和其他两个选手被歹徒挟持到了美丽都。婆婆奋不顾身，带着布鲁诺坐上颠簸的小船，前往搭救她的孙子。在流落他乡的街头，婆婆遇上了美丽都三姐妹，她们一起投入到拯救小查宾的队伍当中。©豆瓣', '比阿特丽斯·博尼法西', '希尔万·肖默', 8.7, 82155, 'tt0286244', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2333703827.jpg', 0.3, 0.9, 10.9, 38.5, 49.3, '0.076512,-0.221947,-0.715074,0.415046,-0.284796,-0.514506,0.671188,0.085780,-0.509158,0.115852,0.207263,0.626667,-0.022582,0.559858,0.400775,0.000655,-0.190686,-0.601772,-0.166502,0.209202,-0.372964,-0.353818,0.055770,-0.034684,-0.120185,-0.308688,0.315616,-0.125388,0.163686,0.765061,0.059338,-0.197129,-0.274965,0.223529,-0.378400,0.030307,-0.044356,0.175492,-0.165568,0.095328,0.036907,0.044848,-0.194834,-0.110889,0.245954,0.104074,0.644477,-0.216516,0.116489,-0.095309,-0.076783,-0.173473,-0.070605,0.095583,0.277250,-0.068759,0.316760,0.088679,0.093155,0.024187,-0.072685,-0.134015,-0.331841,0.361503,0.078156,0.081157,-1.001494,0.473658,0.107396,-0.263628,0.206938,-0.406290,0.237723,0.138455,-0.142981,0.491921,-0.278074,0.219510,-0.575889,0.234326,0.836323,-0.185984,-0.140314,0.241407,-0.062627,-0.130307,0.165180,-0.678384,-0.577196,0.157587,0.224493,-0.018212,-0.381121,0.042418,-0.427190,0.230971,-0.028890,-0.223826,-0.013519,-0.539829,0.096954,-0.373256,0.248571,-0.495473,-0.221348,0.368014,-0.002756,-0.247663,1.001493,-0.658566,0.444457,0.598153,0.354327,-0.576278,0.717951,0.177387,0.282405,-0.094033,0.001391,0.080670,-0.120197,0.165264,0.179087,0.442163,-0.247596,0.110136,-0.435890,0.264555', '1877596', '5262027', '3445516', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291566', '攻壳机动队2：无罪', '剧情', '草薙素子之后，巴特与侦探出身的陀古萨结为搭档。近期发生多起机器人偶杀害主人继而自杀的事件，由于受害者家属均无公诉，且死者中有政客与公安官员，于是公安9课派出巴特小组调查此案。杀人人偶皆为荒凉地带公司出品的哈德莉机型，应部分顾客要求，该机型同时具备异性玩伴的功能，巴特从荒凉地带公司出货官遇害入手，卷入与黑帮的战斗，期间有人入侵他的大脑，使其自残。巴特决定直奔荒凉地带总部，他与陀古萨拜访了择捉岛上的黑客基姆，后者布下系统陷阱，幸有素子提出警告避免陀古萨陷入控制。依靠基姆这条线索，巴特登上了荒凉地带公司设立在海上的工厂船，素子再次降临他的身边，与其并肩作战。©豆瓣', '田中敦子', '押井守', 9.2, 63059, 'tt0347246', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910832189.jpg', 0.2, 0.6, 6.3, 27, 65.8, '0.394348,-0.250501,-0.408484,0.354699,0.235747,-0.120296,0.513404,0.156439,-0.339577,-0.133750,0.414174,0.293063,0.019230,-0.140470,0.492995,-0.092261,-0.546266,-0.411248,-0.031979,-0.175146,-0.153043,-0.587172,-0.196607,-0.328248,-0.043581,-0.411161,0.659866,0.038176,-0.219519,0.150222,-0.104967,0.531309,-0.503190,0.297644,0.365562,-0.146002,0.238654,-0.229625,-0.508071,0.173673,-0.319920,-0.065282,0.007461,-0.067686,-0.040522,0.568379,0.636819,-0.274322,-0.107753,-0.390976,0.232533,-0.235718,0.153620,-0.246916,0.423933,0.044592,0.065403,0.410200,-0.061710,0.009076,0.006588,0.175961,-0.371420,-0.057328,0.224251,0.035900,-0.183039,-0.045303,-0.265082,0.033357,-0.201264,-0.402774,0.079372,0.384916,0.251025,0.152010,0.069084,0.269758,-0.135109,-0.148625,0.430970,-0.172250,-0.173866,-0.293798,-0.127346,-0.616034,0.113940,-0.268488,-0.095142,-0.122862,0.239456,-0.059049,-0.025705,0.343774,-0.648822,-0.231252,-0.228257,-0.362802,0.113865,0.058899,-0.023166,-0.913081,0.111713,0.066589,-0.063709,-0.141073,0.270174,-0.132401,0.214595,-0.554781,0.024184,0.555029,0.379100,-0.390527,0.463653,-0.086140,0.313625,-0.294810,-0.062431,0.027042,0.224840,0.488751,0.151569,-0.033747,0.071274,-0.147959,-0.247497,-0.014958', '1306809', '2369613', '20274039', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291568', '东京物语', '剧情', '儿女们都大了，各自成家。父亲周吉（笠智众饰）和老伴（东山千荣子饰）要去东京看望他们，老两口带着愉快心情上路。可另一边，还没等他们到大儿子家，孙子就因为爷爷奶奶到来腾地方哭闹不停。老人开始觉得尴尬，大儿子幸一（山村聪饰）在东京当医生，二女儿繁（杉村春子饰）在东京开美容店，二儿媳纪子（原节子饰），小女儿京子（香川京子饰）外，大阪还有三子敬三。东京让老人陌生，在儿女家也好不到哪去。大儿子工作繁忙，没时间带他们出去玩。搬到女儿家，依旧每日困守且有矛盾。老两口渐渐也明白儿女们的处境，他们在东京的老友也过得不好。只有守寡的儿媳纪子对老人很是孝顺。之后老人踏上回家的路，前后不过十天……©豆瓣', '笠智众', '小津安二郎', 9.1, 128562, 'tt0046438', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1925331564.jpg', 1.3, 0.4, 4.8, 27, 66.4, '-0.038742,-0.323738,-0.731337,0.008168,-0.050208,-0.588581,0.395524,0.434267,-0.851221,-0.338090,0.119509,0.415468,0.127996,0.657671,0.112856,0.039035,-0.539813,-0.089808,0.035531,-0.182348,-0.198284,-0.251851,0.428963,-0.208830,-0.260464,0.033657,-0.003601,-0.097325,0.525001,0.381045,-0.004828,-0.131087,-0.225614,0.388910,-0.314476,0.464907,-0.212191,0.164814,-0.318760,0.003558,0.201576,0.186231,-0.592622,-0.096550,0.646744,0.425609,0.574893,0.218148,-0.172610,-0.076126,-0.168662,0.096980,-0.222571,0.298228,0.502951,-0.203409,0.477921,0.090045,-0.185458,-0.239243,-0.157462,-0.090927,0.037398,0.640404,0.195332,0.135561,-0.688674,0.460302,-0.052425,-0.465600,0.203806,-0.680368,0.293715,0.429748,-0.293775,0.469015,-0.291456,0.283038,-0.315966,0.191542,0.787045,-0.068463,0.148086,0.174038,-0.136339,0.053743,0.154343,-0.419523,-0.645442,-0.086412,0.099889,-0.006407,-0.164058,0.003534,-0.004277,0.077004,-0.021631,-0.241567,0.375314,-0.330279,0.130645,-0.490126,0.307246,-0.537258,-0.255548,0.362588,0.177430,-0.002421,0.787770,-0.487368,0.179875,0.382858,0.419539,-0.553153,0.598443,0.088495,0.223502,-0.309033,0.155378,-0.308742,-0.135310,0.234860,0.406907,0.109602,-0.338769,-0.047987,-0.124378,0.139732', '1303485', '1291565', '2042219', '1300202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291569', '大都会', '科幻', '大都市梅陀宝丽斯，被称之为本时代进步象征的超级摩天大厦正在举行落成典礼。手握本市实权的RED先生（石田太郎 配音）台上演讲正酣，台下一名黑衣青年男子ROCK（冈田浩晖 配音）却在警备重重下公然拔枪杀人，群众一阵哗然骚乱。目睹此事的日本侦探伴俊作，携外甥剑一（小林桂 配音），开始进行全市的追凶调查。但是ROCK被判明只是射杀了机器人，凶手若无其事的离去了。梅陀宝丽斯由先进的地上部分和颓败的地下部分构成二重结构的都市体系，在这个城市生存的人类中间，有从高度发达的机器人世界中受益，享受文明技术优越性的人，也有反之被机器人夺走工作无以糊口的人，还有要求让机器人同样享有人权自由的群众团体。随着调查的深入，实施的真相渐渐浮出水面，机器人和人类最终是一起平等生存，还是一起毁灭……本片改编自手冢治虫出版于1949年的同名漫画。©豆瓣', '井元由香', '林太郎', 8.1, 31620, 'tt0293416', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1910832560.jpg', 0.4, 1.7, 21, 46.5, 30.4, '0.263227,0.169813,-0.580529,0.345663,-0.018545,0.031136,0.579350,0.082366,-0.152595,-0.068308,0.440524,0.606053,-0.077477,-0.063671,0.235008,-0.306020,-0.385848,-0.558840,-0.344187,0.019255,-0.343982,-0.580383,-0.338190,-0.310446,-0.326239,-0.294291,0.870169,0.080220,-0.319679,0.269386,0.144711,0.273420,-0.200859,0.236709,-0.092084,-0.255887,0.281825,-0.275862,-0.289865,0.255591,-0.423796,-0.186804,-0.096877,0.022991,-0.230426,0.163836,0.580824,-0.106104,0.143851,-0.397328,0.400277,-0.114778,-0.240022,-0.090128,0.316298,0.072578,-0.161724,0.253074,0.012925,0.049339,0.105000,-0.201716,-0.675530,-0.073724,0.284651,0.257484,-0.270044,0.219257,-0.065085,-0.153752,0.030962,-0.025685,0.202461,0.210108,0.440150,0.514776,-0.108887,0.275977,-0.333736,0.259914,0.417067,0.079278,-0.503905,-0.030248,-0.210362,-0.605068,-0.240673,-0.398849,-0.058547,-0.396040,-0.000790,0.090670,-0.108767,0.267167,-0.658791,0.277457,-0.041176,-0.421260,-0.067730,-0.281080,-0.103252,-0.842491,-0.006023,-0.326169,-0.124259,0.041638,0.231026,-0.388140,1.052833,-0.657867,-0.015508,0.375686,0.435925,-0.239859,0.654812,0.021821,0.115557,-0.072705,-0.215994,0.060198,0.078757,0.515692,-0.090814,0.311797,-0.105087,-0.228977,-0.292191,0.360742', '1322847', '27602116', '25863940', 