INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291571', '指环王1：护戒使者', '剧情', '比尔博·巴金斯是100多岁的霍比特人，住在故乡夏尔，生性喜欢冒险，在年轻时的一次探险经历中，他从怪物咕噜手中得到了至尊魔戒，这枚戒指是黑暗魔君索伦打造的至尊魔戒，拥有奴役世界的邪恶力量，能够统领其他几枚力量之戒，在3000年前的人类联盟和半兽人大军的战役中，联盟取得了胜利 ，并得到了至尊魔戒，数千年的辗转后，魔戒落到咕噜手中，被比尔博碰巧得到。因为和魔戒的朝夕相处，比尔博的心性也受到了影响，在他111岁的生日宴会上，他决定把一切都留给侄子佛罗多（伊利亚‧伍德 饰)，继续冒险。比尔博的好朋友灰袍巫师甘道夫（伊恩·麦克莱恩 饰）知道至尊魔戒的秘密，同时，黑暗魔君索伦已经知道他的魔戒落在哈比族的手中。索伦正在重新建造要塞巴拉多，集结无数的半兽人，准备以大军 夺取魔戒，并且征服全世界。甘道夫说服佛罗多将魔戒护送到精灵王国瑞文希尔，佛罗多在好朋友山姆、皮平和梅利的陪同下，在跃马旅店得到了刚铎王子阿拉贡的帮助，历经艰难，终于到达了精灵王国。然而，精灵族并不愿意保管这个邪恶的至尊魔戒，中土各国代表开会讨论，达成意见，准备将至尊魔戒送到末日山脉的烈焰中彻底销毁，佛罗多挺身而出接受了这个任务，这次，陪伴他的除了三个好朋友，还有甘道夫、阿拉贡、精灵莱戈拉斯（奥兰多‧布鲁姆 饰）、人类博罗米尔、侏儒金利。一路上，魔戒远征军除了要逃避索伦爪牙黑骑士和半兽人的追杀之外，更要抵抗至尊魔戒本身的邪恶诱惑，前途困难重重。', '伊利亚·伍德', '彼得·杰克逊', 9.1, 790179, 'tt0120737', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2373910134.jpg', 0.2, 0.5, 6.9, 29.4, 62.9, '0.157907,0.436378,-0.661127,0.526288,0.015339,-0.187433,0.516546,-0.122373,-0.283942,-0.305971,0.254430,0.715600,0.225463,0.028326,0.351657,0.028933,-0.334337,-0.360357,-0.002347,-0.236183,-0.335101,-0.274832,-0.390266,-0.124298,-0.187881,-0.797704,0.835461,0.248876,-0.006396,0.139805,0.278134,0.379944,-0.079652,0.289537,-0.284338,-0.156714,0.182754,-0.248305,-0.486937,0.486467,-0.127159,0.166882,-0.152200,0.504501,0.156449,0.127962,0.502795,-0.684573,0.230828,-0.077275,0.163933,-0.336313,-0.057577,-0.117056,0.325220,-0.004638,-0.089842,0.276341,0.040263,-0.006744,0.014627,-0.285741,-0.799269,-0.083975,0.009151,0.273479,-0.530819,0.247269,-0.131322,0.214226,0.134416,-0.180442,0.268880,0.380325,0.068627,0.102940,0.025587,-0.041582,-0.455830,0.170768,0.432553,-0.326556,-0.177668,0.010843,-0.017290,-0.791988,-0.282654,-0.274213,-0.502464,0.033689,0.535903,0.211999,0.152080,0.586758,-0.916134,-0.110842,-0.322034,-0.340393,0.280206,-0.392871,-0.034455,-0.563359,-0.258297,0.033554,-0.050708,0.134203,0.170103,-0.153264,0.642555,-0.622191,0.349078,0.488774,0.455006,-0.246154,0.546409,-0.202274,0.216240,-0.206411,-0.037291,0.541645,0.417357,0.258950,0.207375,0.140303,0.266786,-0.114729,-0.408615,0.493573', '26759819', '26290398', '24750460', '25890017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291572', '指环王2：双塔奇兵', '剧情', '第二部在延续第一部风格的同时，故事呈现出多线发展的格局，情节有了更高的观赏性。第一部结尾，博罗米尔被强兽人杀死之后，两个霍比特人皮平和梅利也被强兽人绑架，阿拉贡、精灵莱戈拉斯（奥兰多·布鲁姆 饰）、侏儒金利一路追踪强兽人，营救皮平和梅利，遇到了“复活”的白袍巫师甘道夫 （伊恩·麦克莱恩 饰）。此时，投降索伦的白袍巫师萨鲁曼控制了人类洛汉王国的国王，并派出大量的强兽人军队，准备消灭人类。阿拉贡、莱戈拉斯和金利在甘道夫的带领下，帮助洛汉王国对抗邪恶力量的入侵。幸运的皮平和梅利被会说话的树精救了出来，并且遇到“复活”的甘道夫，在甘道夫的授意下，树精保护了两人的安全，并且带他们参加树精大会，大会上，树精们讨论对待中土大战的态度：是继续当中立者，逆来顺受，还是奋起反抗？身负重任的佛罗多（伊利亚·伍德 饰）和山姆继续向末日山脉前进，一路上被咕噜跟踪，弗罗多依靠至尊魔戒的力量，成为了咕噜的主人，在咕噜的带领下，他们到了末日山脉的入口，黑门。就在他们准备进入之时，博罗米尔的弟弟法莫尔出现，将他们带回了刚铎。弗罗多又遇上了新的危机：法莫尔想利用至尊魔戒的力量对抗萨鲁曼的攻击……', '伊利亚·伍德', '彼得·杰克逊', 9.2, 699979, 'tt0167261', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2640236255.jpg', 0.1, 0.4, 5.8, 27.9, 65.7, '0.299168,0.123912,-0.645792,0.478731,-0.088721,-0.225315,0.626580,0.125129,-0.260147,-0.136395,0.368596,0.673387,-0.000397,-0.270107,0.285612,-0.100365,-0.408204,-0.369710,0.018192,0.040126,-0.492615,-0.138253,-0.453033,-0.253954,-0.090284,-0.691126,0.477587,0.213605,-0.246509,0.369142,0.166360,0.383442,-0.072129,0.432837,-0.081793,0.019381,0.228884,-0.371680,-0.152678,0.465849,-0.328708,0.045294,-0.203087,0.330843,-0.093773,0.371906,0.584286,-0.527298,0.291827,-0.159431,-0.010281,-0.515996,0.054070,0.088553,0.547536,-0.079835,-0.031543,0.260777,-0.000647,-0.056134,-0.136847,-0.068069,-0.766181,0.196897,-0.082874,0.309195,-0.643370,0.334458,0.050713,0.107920,0.165836,-0.297366,0.149720,0.478841,0.301533,0.260020,0.144454,-0.147007,-0.588071,-0.240454,0.610826,-0.088749,-0.373413,-0.149045,-0.066939,-0.615310,-0.100082,-0.313224,-0.250229,-0.174966,0.596540,0.115895,0.000508,0.391112,-0.911179,-0.101470,-0.466952,-0.281221,-0.081408,-0.367906,-0.073335,-0.840483,-0.099088,-0.122750,-0.128583,0.103859,0.122614,-0.156729,0.610752,-0.567431,0.272642,0.542930,0.545551,-0.302134,0.449782,-0.135412,0.135395,-0.000808,-0.066657,0.424650,0.260145,0.391853,0.261682,0.349093,0.019615,-0.077483,-0.386313,0.579988', '1294917', '24750460', '6982558', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291573', '虫虫危机', '喜剧', '菲力在蚂蚁王国里并不怎么受欢迎，尽管他发明了先进的收割机，然而阴差阳错，他竟然惹了大祸，公主妹妹小不点因此被蝗虫敌人捉去，而且蚂蚁的粮食也受到了蝗虫的威胁。即使菲力救出了小不点，但还是被赶出蚂蚁王国。只有他在外面的世界找到了对付蝗虫的办法，才有可能回到家园。菲力在城市中遇到了马戏团的一队昆虫。爬虫、蝴蝶、瓢虫、臭虫，他们都似乎身怀绝技，令菲力十分兴奋，于是菲力把他们请回蚂蚁王国对付蝗虫。一场恶战即将开始，昆虫们愈战愈勇，和菲力一同投入到斗争中。智勇双全的菲力也终于回到了蚂蚁王国中，受到大伙儿的赞赏。©豆瓣', '大卫·弗利', '约翰·拉塞特', 8, 92697, 'tt0120623', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1910833170.jpg', 0.1, 1.1, 24.1, 50.3, 24.4, '0.363768,0.010731,-0.852520,0.222007,-0.064986,-0.134222,0.760159,-0.001816,-0.409461,0.141043,0.369124,0.475105,0.001141,0.040688,-0.023537,-0.306597,-0.270493,-0.400571,0.109232,-0.204093,-0.184221,-0.056643,-0.362832,-0.386345,0.109854,-0.215850,0.397705,0.235213,0.026643,0.243558,-0.148289,0.039979,-0.166905,0.689621,-0.287058,0.167208,0.231750,0.233609,0.042048,0.189392,-0.154604,-0.015128,-0.193914,0.222494,0.044681,0.167990,0.626734,-0.830728,0.063456,-0.450864,-0.061533,-0.503681,0.214915,0.339233,0.604229,-0.155632,0.054762,-0.179255,0.109854,0.356696,-0.008652,-0.275805,-0.497175,0.011964,-0.004728,0.196012,-0.625503,0.291733,0.257188,0.106234,-0.025349,-0.157420,0.439897,0.181323,0.425521,0.509405,-0.097467,0.117424,-0.925742,-0.241016,0.709392,0.028452,-0.281143,-0.067727,-0.021626,-0.632761,0.137447,-0.498412,-0.071682,-0.160568,0.632608,-0.054949,-0.652919,0.332255,-0.936512,0.056696,-0.241932,-0.396598,-0.083188,-0.452398,0.080163,-0.450540,0.296621,-0.298337,-0.133078,0.344490,0.349284,-0.221906,0.771748,-0.655549,0.165996,0.690334,0.445666,-0.331050,0.264123,-0.520987,-0.274723,0.062074,0.176165,0.119705,0.267334,0.481342,0.709227,0.285908,-0.130474,-0.450853,-0.141114,0.437859', '21619567', '1294037', '1458910', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291574', '玩具总动员2', '喜剧', '自从上一集牛仔伍迪救回巴斯光年之后，他一直和其他玩具一起快乐的生活在小主人家。一次，小主人参加夏令营去了，伍迪因为破旧而没被带去。留在家里的伍迪恰巧被一个玩具收藏家发现了，认为他是近代最具代表性的玩具。于是将伍迪被偷了出来放在颇富盛名的文化博物馆内展览。在家里所有的玩具 都很担心伍迪，因此巴斯光年自告奋勇去寻找伍迪，但是当他们发现伍迪在展览馆时， 伍迪却似乎不再愿意回去过那平凡的生活……©豆瓣', '汤姆·汉克斯', '约翰·拉塞特', 8.5, 224507, 'tt0120363', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1283688673.jpg', 0.1, 0.5, 13.4, 48.5, 37.5, '0.365839,-0.170022,-1.040887,0.356100,-0.365678,-0.376248,0.979970,0.075497,-0.568726,-0.457043,-0.171428,1.061940,0.002956,0.266974,-0.098268,0.144194,-0.282079,-0.371759,-0.206113,-0.313071,-0.314356,-0.256861,-0.137065,0.000959,-0.330163,-0.143849,0.376462,-0.277819,-0.234010,0.728741,0.162879,0.161097,-0.069280,0.547343,-0.387050,0.134968,0.117956,-0.063224,-0.175337,0.399356,0.186959,0.021723,-0.135888,0.042041,0.276024,-0.027332,0.574270,-0.366902,0.040492,0.070720,0.200460,0.041221,-0.159190,0.019853,-0.043266,0.134961,0.523800,-0.243755,-0.430698,0.269866,0.448655,-0.234228,-0.343090,0.032248,0.124331,0.327283,-0.820817,0.631543,-0.043266,-0.255540,0.085482,-0.789910,0.510027,0.113518,0.143438,0.273103,0.006938,0.291540,-0.743340,0.157272,0.614096,-0.075061,0.164535,0.339894,0.190133,-0.207847,-0.027067,-0.477503,-0.426142,0.362353,0.321499,-0.065965,-0.290249,0.104183,-0.825011,-0.011855,-0.088131,-0.543880,-0.009225,-0.509274,-0.026519,-0.658573,0.419362,-0.260495,-0.149808,-0.020986,-0.018328,-0.244253,0.598769,-0.840654,0.408404,0.715180,0.240777,-0.299818,0.822936,-0.084152,0.233876,0.127999,-0.007299,0.207879,0.342533,0.594901,0.301870,0.489392,0.115907,-0.413928,-0.430692,0.463282', '3055049', '26678509', '1296538', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291575', '玩具总动员', '喜剧', '小主人家境富裕，拥有一屋的玩具。其中他最爱的是牛仔玩偶胡迪，胡迪因此成为众玩具的“老大”。当小主人出门在外时，一屋的玩具自成世界，过着自己的生活。一天，小主人带回了一个新的玩意：太空战警巴斯光年。巴斯光年长相新奇，功能先进，令小主人爱不释手，威胁到了胡迪的地位。胡迪千方百计要赶走巴斯，一不小心二人一起掉出了房间窗口外，邻居的恶狗在狂吠，邻居的小孩是一个玩具虐待狂，胡迪巴斯能不能化敌为友，消灾解难？©豆瓣', '汤姆·汉克斯', '约翰·拉塞特', 8.5, 339169, 'tt0114709', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2565956404.jpg', 0.1, 0.5, 12.4, 45.8, 41.2, '0.170642,-0.014839,-0.380115,0.238609,-0.730798,-0.086151,0.655583,0.261169,-0.553301,-0.130614,0.206531,0.562617,0.138346,0.473415,-0.185273,0.370964,-0.299148,-0.204096,-0.192487,-0.399092,-0.156402,-0.175774,-0.323593,-0.333822,-0.155594,-0.293896,0.090889,-0.316078,0.047005,-0.023366,0.247861,-0.098920,-0.221714,-0.015884,-0.527688,0.125504,0.030960,-0.036766,-0.333289,0.178946,-0.501872,0.489837,0.012790,-0.014034,-0.124525,-0.153249,0.712691,-0.454126,0.022800,-0.270412,0.152561,0.124421,-0.029153,-0.077586,0.090345,-0.102213,0.413216,-0.407710,-0.161845,0.322500,0.384550,-0.074970,-0.197484,0.017680,-0.101366,0.132319,-0.405290,0.548394,-0.188887,-0.093463,0.399362,-0.376468,0.140327,-0.165163,0.100896,0.681659,-0.091720,0.360502,-0.872125,-0.042711,0.368753,-0.089607,-0.191835,0.258382,-0.269630,-0.263953,0.022199,-0.463677,-0.622699,-0.026181,0.660982,-0.232031,-0.230152,0.539708,-0.884977,0.193806,-0.142982,-0.073510,0.166900,-0.315574,-0.095727,-0.410986,0.261269,-0.317392,-0.002988,0.054255,0.272516,-0.329310,0.989597,-0.604991,0.103646,0.668159,0.243182,-0.171343,0.646837,-0.173542,0.440271,-0.165417,0.195946,-0.147032,0.385177,0.320936,0.071610,0.347766,0.007081,-0.204957,-0.401151,0.533072', '1309101', '4181031', '1302661', '3262050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291576', '蒸汽男孩', '科幻', '十九世纪中叶，维多利亚时代的大英帝国，工业革命方兴未艾，理性与进步似乎凌驾一切，标志了人类文明昂首进步的无限可能。就在第一次万国博览会揭幕前夕，住在伦敦的13岁少年雷•史汀（铃木杏 Anne Suzuki 配音）突然收到发明家祖父（中村嘉葎雄 Katsuo Nakamura 配音）从美国寄来，称之为“蒸气球”（Steam Ball）的神秘动力装置。同时间，英国情报组织，以及一个名为奥哈拉基金会的黑暗组织，都觊觎“蒸气球”所蕴含的惊人力量。雷因此而突遭一伙身份不明的人的袭击，雷只好带着金属球，踏上逃亡之路。为寻求真相雷来到美国，从父亲艾迪（津嘉山正种 Masatane Tsukayama 配音）口中雷得知“蒸气球”依据全新机械理论所设计，可以产生一种划时代的庞大能源，足以供应整个国家所需。路途中，雷邂逅了美丽的富家千金斯嘉丽（小西真奈美 Manami Konishi 配音）。从小娇生惯养，却偏偏爱上了雷，自愿跟随孤独的雷一起踏上了冒险之旅……所谓的科学，究竟是人们的希望？还是将会毁灭一切。本片的制作经历了整整9年，总制作费高达24亿日元。', '铃木杏', '大友克洋', 7.8, 25807, 'tt0348121', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p454040918.jpg', 0.4, 2.7, 27.6, 46.7, 22.6, '-0.249659,0.182736,-0.571341,0.484020,0.198766,-0.015047,0.286559,-0.018448,-0.308960,-0.540861,-0.159955,0.535508,-0.019159,0.109653,0.473460,-0.087839,0.058987,-0.376745,-0.216989,-0.083060,-0.420666,-0.458090,-0.217461,-0.265290,0.056059,-0.388210,0.535982,0.451728,-0.456202,0.255775,0.118801,0.519927,-0.346966,0.398761,-0.151836,-0.192118,0.073341,0.105646,-0.199317,0.078557,-0.230806,-0.175454,0.050422,0.124839,0.142817,0.120465,0.487744,-0.467954,0.169136,-0.403830,0.528512,-0.057480,-0.048775,-0.272739,0.080329,0.207689,0.110330,0.152914,0.109234,-0.015186,0.122119,-0.483016,-0.779864,-0.170472,0.073436,-0.080715,-0.400377,0.176952,0.096338,0.062771,-0.149124,-0.106826,0.007609,0.097630,0.284490,0.461322,-0.222023,0.283958,-0.191935,0.082153,0.657855,-0.085347,-0.574098,0.303211,-0.291131,-0.275160,-0.330287,-0.167973,-0.263064,0.026676,0.389271,0.278115,0.209794,0.338003,-0.571680,-0.139603,-0.214789,-0.072799,0.273726,-0.220266,-0.080766,-0.569543,-0.001147,-0.284952,-0.030249,0.196741,0.210727,-0.139141,0.721083,-0.573332,0.149919,0.525449,0.150648,-0.300810,0.442344,-0.205935,-0.073428,-0.501192,-0.016860,0.311968,0.1