INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291577', '超人总动员', '喜剧', '鲍勃是一个超人特工，他惩恶扬善，深受街坊邻里的爱戴。“不可思议”先生就是他的光荣外号。他和另一个超人特工“弹力女超人”相爱，两人结婚后过上平静的生活。15年过去了，鲍勃已经像普通人一样生活，当上了保险公司的理赔员。然而他心中还是有着技痒之时。当他知道有发明家要展开攻击超人特工队、毁灭人类的计划，鲍勃终于按捺不住了。他要重出江湖，挽救人类护卫地球。但中年的超人已经大腹便便，他和敌人的斗争充满了悬念。鲍勃的妻子也跟丈夫一起投入到这场艰巨的战争中。©豆瓣', '格雷格·T·尼尔森', '布拉德·伯德', 8.2, 283112, 'tt0317705', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167017148.jpg', 0.1, 0.9, 18.7, 50.4, 29.9, '0.135268,-0.103737,-0.559201,0.396890,-0.233538,-0.396321,0.958837,-0.095236,-0.417336,-0.044007,0.289856,0.886681,-0.014117,0.212207,0.356506,0.181362,-0.293347,-0.901780,-0.186467,-0.015028,-0.289088,-0.403351,-0.394064,-0.214506,-0.057503,-0.135337,0.756635,-0.122395,-0.068058,0.510004,0.454297,0.183243,0.201805,0.656622,-0.287310,0.054914,0.071726,-0.089697,-0.453519,0.013231,0.092228,0.082608,-0.035854,0.237624,-0.157955,0.278463,0.287836,-0.191175,-0.121266,-0.272462,0.183225,-0.301535,-0.127310,0.198978,0.276633,0.001645,-0.003950,-0.022242,0.349706,-0.227489,-0.047937,-0.088028,-0.874228,-0.074739,0.040318,0.101083,-0.496909,0.512654,0.024619,0.114802,0.068155,-0.256227,0.045220,0.229301,0.325476,0.416586,-0.105656,0.027471,-0.443039,0.331328,0.881076,0.107704,-0.635949,0.393353,-0.328421,-0.568116,-0.182655,-0.545515,-0.595722,-0.019806,0.236328,-0.011376,-0.282642,0.336247,-0.574660,0.122914,-0.226895,0.079895,-0.281446,-0.375837,0.077616,-0.368622,-0.285196,-0.645707,-0.494302,0.138948,0.066432,-0.437569,0.927489,-0.959886,0.146712,0.659070,0.215650,-0.350412,0.641982,0.139589,0.104933,-0.383868,0.143011,0.198779,-0.144341,0.416221,0.082525,0.303945,-0.000700,0.024493,-0.204841,0.590162', '30162520', '35030151', '25721544', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291578', '冰川时代', '喜剧', '冰河时期降至，动物们都急着迁徙到温暖的地方及储存食物。长毛象曼弗瑞德、树獭希德、剑齿虎迪亚戈为了帮助一个人类的婴儿回到父母身边，因而也掉了动物们迁徙的队伍。三只性格各异的动物，觉得集合力量帮助婴儿。一路上，善良的曼弗瑞德总觉得迪亚戈心怀鬼胎，想吃掉婴儿，互相猜疑。他们一起经历了无数艰难险阻，终于能够真诚相对。当剑齿虎迪亚戈的同伴知道它身边正有一个婴儿，饥寒交迫的它们就想迪亚戈把婴儿交给它们当食物，迪亚戈已对可爱的小婴儿产生了感情，无法下手，而迪亚戈该如何选择呢？小婴儿又能否安全回到家中？©豆瓣', '雷·罗马诺', '卡洛斯·沙尔丹哈', 8.6, 575228, 'tt0268380', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910895719.jpg', 0.1, 0.5, 10.9, 45.4, 43.2, '0.136076,0.042812,-0.487259,0.359817,-0.036382,-0.287223,0.679326,0.079105,-0.173951,-0.137747,0.009925,0.547346,0.147491,0.389419,-0.294042,-0.162321,-0.359266,-0.304070,-0.189711,-0.112449,-0.341203,-0.187018,-0.221801,-0.376699,0.023022,-0.265770,0.440625,-0.084412,0.212871,0.163223,0.194185,0.149284,-0.288183,0.322792,-0.268990,-0.030639,-0.209982,-0.097495,-0.250140,-0.080230,0.029688,0.307975,-0.036306,0.039417,0.085076,-0.051835,0.976804,-0.671379,-0.196427,-0.470675,0.006470,0.054556,0.272313,0.262033,0.557091,-0.028802,0.288099,-0.462614,0.032322,0.449150,0.231323,0.008628,-0.625905,0.078390,-0.205893,0.352603,-0.372278,-0.015065,0.308174,0.342105,0.279501,-0.525856,0.073677,0.323665,0.013734,0.553972,-0.240105,0.131628,-0.344209,-0.410529,0.578927,-0.222392,-0.261861,0.199339,-0.575934,-0.706650,0.250906,-0.208549,-0.426501,-0.056879,0.330365,0.420189,-0.524893,0.259411,-0.683933,0.053782,-0.254895,-0.176770,-0.057364,-0.312244,0.040193,-0.125614,0.156572,-0.199335,-0.151550,0.127113,0.260832,0.026352,1.064428,-0.430078,0.189486,0.741607,0.361138,-0.377174,0.291430,-0.296018,0.202774,-0.098520,0.027883,0.407243,-0.164779,0.053896,0.373420,0.253308,-0.136859,-0.026376,-0.343127,0.228723', '4181031', '2977870', '25882279', '27069070');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291579', '怪兽电力公司', '喜剧', '我们不知道，在那样的世界里住着那样一群怪物。他们长相滑稽，却必须装作狰狞。因为，在夜深的时候，他们要悄悄的出现在孩子的衣橱里，吓唬刚刚甜美睡去的宝宝。一切，只因为他们是怪物电力公司的员工，而孩子的尖叫，则是怪物王国发电的全部能量。怪物们害怕孩子，却又必须让孩子尖叫。在怪物的国度里，他们都是为全民造福的英雄。毛怪苏利文（约翰•古德曼）是怪物公司最出色的员工，业绩总是摇摇领先，他吓哭的小孩儿不计其数。他与搭档大眼怪麦克（比利•克里斯托）很受大家的爱戴。一次偶然，毛怪不小心把一个两岁的小女孩阿布（玛丽•吉布斯）带回了怪物世界，引起了极大的恐慌，调皮可爱的阿布把这些可怕的怪物吓的人仰马翻。警方在追捕阿布，而坏蛋亨利（詹姆斯•柯博）也计划利用阿布进行他改革工厂的邪恶计划。另一方面，在与阿布相处的过程中，毛怪渐渐对她产生莫名的情愫，甚至因此被放逐野外。可是一切都不能抵挡毛怪拯救女孩的信念，为了阿布，毛怪踏上了艰险的旅程……', '约翰·古德曼', '彼特·道格特', 8.8, 620854, 'tt0198781', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2513247938.jpg', 0.1, 0.4, 9.4, 41.7, 48.4, '0.046655,-0.222236,-0.621773,0.294620,-0.432709,-0.093049,0.877883,-0.022787,-0.549572,0.019498,0.300673,0.478026,-0.116014,0.245830,-0.129825,0.010962,-0.197958,-0.402460,-0.187806,-0.042853,-0.142270,-0.280501,-0.313593,-0.481020,-0.021025,-0.535984,0.589059,0.127832,-0.125843,0.040559,0.021617,0.180127,-0.155246,0.653005,-0.078065,0.015086,0.165582,-0.210627,0.022300,0.035721,-0.026591,-0.124308,-0.150044,0.346233,-0.075800,0.206868,0.787040,-0.618356,-0.107129,-0.231504,0.222729,-0.397359,-0.009894,0.217642,0.355479,-0.375804,0.281229,-0.035801,0.090767,-0.019072,0.150390,-0.061058,-0.693975,0.239515,0.035376,0.263982,-0.728599,0.562137,-0.069792,0.210182,0.381115,-0.290950,0.168017,0.173530,0.307454,0.487210,-0.252222,0.090628,-0.522564,-0.097123,0.549532,-0.075156,-0.243359,0.342036,-0.510645,-0.456944,-0.122258,-0.219544,-0.642765,-0.017140,0.405596,-0.033129,-0.538231,0.486787,-0.566291,0.008861,-0.243648,-0.318082,-0.239828,-0.603970,-0.140259,-0.338989,0.044191,-0.264127,-0.158242,0.040297,0.113202,-0.212692,0.894735,-0.739186,0.041831,0.869440,0.288299,-0.366161,0.484007,-0.123424,0.063878,-0.206021,-0.088943,0.062995,0.149563,0.305556,0.375418,0.486483,-0.039683,0.013079,