INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291580', '杀死比尔', '动作', '这是一部令人眼花缭乱，绝对能带给您感官刺激的动作电影。一个新娘（乌玛•瑟曼Uma Thurman饰）在自己的婚礼上遭到了暗杀，婚礼瞬间变成了一片狼籍的红色。幸运的是，新娘并没有就此消失，而是在四年后苏醒过来，并且接受了高强度的各种各样的武术训练，开始踏上了自己的复仇之路，在世界各地寻找给自己带来灾难的人。当然，她也遇到了许多阻碍。日本杀手（刘玉玲饰）就是其中之一。这场红色的复仇之路究竟伸向何处，又有多曲折呢？©豆瓣', '乌玛·瑟曼', '昆汀·塔伦蒂诺', 8.3, 479513, 'tt0266697', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2454638445.jpg', 0.5, 1.9, 15.8, 44.5, 37.3, '0.172669,0.127509,-0.715173,0.630396,-0.026151,-0.191638,0.791334,-0.021007,-0.231724,-0.073556,0.361433,0.731350,-0.112548,0.008442,0.220476,0.010314,-0.169474,-0.756594,0.011652,-0.134328,-0.536865,-0.216564,-0.419737,-0.078549,0.209939,-0.249576,0.664374,0.444798,-0.252855,0.328223,0.492982,0.091130,0.032533,0.549466,-0.149493,-0.006004,-0.010125,0.105774,-0.079451,0.120299,-0.044810,-0.548573,-0.071622,0.577971,-0.350213,0.403856,0.759582,-0.361242,-0.109835,-0.118120,0.491171,-0.448892,0.163953,-0.025039,-0.051109,0.070114,0.216211,0.128843,-0.091342,0.115459,0.095510,0.002153,-0.845945,0.099248,0.120791,0.248818,-0.577160,0.252961,0.065118,-0.238903,0.011222,-0.398624,0.225041,0.328191,0.350883,0.236877,-0.179495,-0.111161,-0.430495,0.270357,0.884537,-0.112481,-0.265614,0.420672,-0.222820,-0.459783,0.087496,-0.248622,-0.187110,0.079813,0.575435,0.087015,-0.088701,0.215872,-0.640029,0.283626,-0.213064,-0.551699,-0.161390,-0.375030,-0.005351,-0.578771,0.056824,-0.205425,-0.354677,0.077597,0.103111,-0.459268,0.567631,-0.688104,0.393590,0.581577,-0.029337,-0.640689,0.535732,0.022483,0.125074,0.260873,-0.065844,0.172670,-0.068850,0.460830,-0.050172,0.339051,0.096571,-0.009065,-0.441378,0.699923', '25828589', '2032339', '25928048', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291581', '怪物史瑞克', '喜剧', '史莱克生活在平凡的世界中——他本身是一个其貌不扬的怪物，绿色的身体，古怪的脾气，不爱干净的懒散生活。这天他家里来了几个不速之客，他们告诉史莱克，自己来自一个残暴国王统治下的王国，现在已经无家可归了。而且，那个残暴的国王还掠夺了一个美丽非凡的公主，打算强占为妻。史莱克虽说丑陋，却心内善良。在领主的威逼下，无奈下他只能前去搭救公主，同时心想一睹公主芳容。路上，他遇到了一个话痨骡子，骡子知道了史莱克的事迹，决定忠心耿耿为之效劳。前路有喷火恶龙等着和他们搏斗呢，他们能不能闯过难关，上演完美的英雄救美童话？©豆瓣', '麦克·梅尔斯', '安德鲁·亚当森', 7.9, 183871, 'tt0126029', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910896706.jpg', 0.2, 1.1, 23.2, 52.6, 22.8, '0.108622,0.380642,-0.547074,0.703421,-0.359843,-0.019884,0.966078,-0.019001,-0.382279,-0.106940,0.421821,0.617846,0.040510,0.151527,0.020186,0.034816,-0.134619,-0.263827,-0.055998,-0.083753,-0.142213,-0.193410,-0.511523,-0.183903,-0.074732,-0.256987,0.458396,0.155593,0.189299,0.452924,0.333668,0.138825,0.130388,0.388055,-0.586727,0.011733,-0.082317,0.109655,0.033394,0.305987,-0.017037,-0.138202,-0.104152,0.384667,-0.233782,0.279066,0.398057,-0.548957,0.050528,-0.272934,0.272264,-0.290744,-0.002565,0.406255,0.388958,-0.388555,0.141252,-0.016124,0.024350,-0.211153,-0.001467,-0.047078,-0.900619,-0.038188,-0.116816,0.254982,-0.828474,0.263976,0.041716,-0.065727,0.041927,-0.341860,0.114130,0.085124,0.398991,0.367447,0.159914,0.337901,-0.592337,0.113245,0.932173,0.135818,-0.255632,0.117208,-0.210862,-0.405460,0.234151,-0.501723,-0.696079,-0.057284,0.205865,-0.219639,-0.245555,0.074174,-0.537446,0.157321,-0.429593,-0.079868,-0.060213,-0.569162,-0.131585,0.000757,-0.109282,-0.488765,-0.215342,0.254124,0.264626,-0.133825,0.859896,-0.846223,-0.020856,0.605582,0.424072,-0.719614,0.598276,0.409513,0.072870,0.066893,-0.205643,0.072626,-0.024854,0.512207,0.086330,0.566428,0.047531,-0.062460,-0.655345,0.566576', '1877596', '6874741', '25767747', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291582', '怪物史瑞克2', '喜剧', '延续了第一部的风格，继续对经典童话进行善意的颠覆。史莱克和费奥娜公主度完浪漫的蜜月后，回到沼泽地。受费奥娜的父母哈沃尔德国王和莉莲王后的邀请，怪物夫妻带着他们的驴子，浩浩荡荡赶往“遥远国”。国王和皇后见到分别多日的女儿和乘龙快婿，惊喜变成惊吓，灾难似乎也从此开始。公主从前的仙女教母，很早前就曾叫自己的儿子“魅力王子”去城堡里屠龙救美，可惜让史莱克抢先了一步，她找到了童话中鼎鼎大名的怪物杀手穿靴子的猫，准备抢回自己心目中的媳妇。©豆瓣', '麦克·梅尔斯', 'Andrew Adamson', 7.6, 101721, 'tt0298148', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910896984.jpg', 0.2, 1.8, 31, 49.8, 17.2, '0.077164,0.002473,-0.484786,0.767319,0.171785,-0.168686,0.705909,-0.058583,-0.395358,-0.191322,0.312738,0.745548,-0.289114,0.304131,0.524007,0.422269,-0.704900,-0.486818,-0.085442,-0.259877,-0.098896,-0.170672,-0.167446,-0.178625,0.131415,-0.412825,0.464737,-0.106231,0.064826,0.777991,0.207000,-0.211793,-0.062253,0.379209,-0.238772,0.427503,0.058215,0.094488,-0.349248,0.252848,0.117296,0.077656,0.051750,0.310821,0.092556,0.148737,0.515237,-0.862726,0.333736,-0.269515,0.400009,-0.165687,0.061162,0.428263,0.243943,-0.187836,0.193050,0.048044,0.180024,-0.252252,-0.155179,-0.482956,-0.488613,0.262175,0.025376,-0.096171,-0.645795,0.580185,-0.048373,0.219402,0.559958,-0.149578,0.259767,-0.012656,0.232875,0.522029,-0.179551,0.310267,-0.499685,0.260659,0.592080,-0.100185,0.052963,0.203122,0.158127,-0.577884,0.020267,-0.233568,-0.550090,0.020383,0.233130,-0.019449,-0.087747,0.357612,-0.602049,-0.119708,-0.446479,-0.078403,0.282120,-0.607310,-0.216428,-0.390829,0.081948,-0.322487,0.144623,0.021627,0.144371,-0.126442,0.538901,-0.566764,0.319722,0.373064,0.334449,-0.518338,0.726287,-0.203876,0.160128,-0.231097,-0.060254,0.199000,-0.001416,0.430502,0.299388,0.355521,-0.176364,-0.049449,-0.386460,0.438949', '1361252', '1414808', '1308366', '5938000');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291583', '天空之城', '动画', '古老帝国拉比达是一座漂浮在空中的巨大的机器岛，传说那里已经无人居住，蕴藏着巨大的财富。因此，无论军方还是海盗，都在找寻着这座传说中的飞行岛。矿工帕克这天偶遇拉比达继承人希达，两人一见如故。因为希达身上有找寻拉比达帝国的重要物件飞行石，军方和海盗两帮人马都在追杀希达。帕克带着希达一起逃亡，最终都没有逃出军方的手中，希达被军队掳走了。为救朋友，帕克只能选择与海盗合作。帕克与海盗成功救出了希达，同时，他们也发现了军方的邪恶计划。为了阻止军方邪恶计划的实施，他们和海盗一起踏上了寻找拉比达之旅。©豆瓣', '田中真弓', '宫崎骏', 9.1, 768970, 'tt0092067', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1446261379.jpg', 0.1, 0.3, 5.5, 30.4, 63.7, '0.207052,-0.122942,-0.809467,0.683960,0.410577,-0.035619,0.627892,-0.016106,-0.319207,-0.116834,0.283153,0.590209,0.273254,0.053009,0.265444,0.036569,-0.693590,-0.501181,-0.272818,-0.042054,-0.439044,-0.623383,-0.537259,-0.318966,-0.143712,-0.363827,0.817333,0.235807,-0.284379,0.501791,0.209201,0.274313,-0.519350,0.267463,-0.305984,-0.284226,0.272547,0.002893,-0.347910,0.328692,-0.440588,-0.055030,-0.009245,0.048737,0.404265,0.406026,0.507944,-0.472308,0.484733,-0.160782,-0.495954,-0.574132,0.196424,-0.352527,0.647055,-0.207408,-0.010143,0.111191,-0.063153,-0.367051,0.133837,-0.223084,-0.783168,0.047437,0.316215,0.043748,-0.468584,0.329344,-0.006647,0.058111,0.152788,-0.346925,0.278893,0.599946,0.128669,0.018606,-0.008473,0.185530,-0.750563,0.009775,0.640636,-0.373092,0.206950,-0.234361,-0.160872,-0.462304,-0.260649,-0.481046,-0.161529,-0.187263,0.511811,0.239017,-0.091987,0.496260,-0.694612,0.128254,-0.358294,-0.204627,0.246449,-0.524477,0.012000,-0.654883,0.022044,-0.047434,-0.120762,0.342143,-0.011001,0.104691,0.446691,-0.550347,0.238790,0.657872,0.577213,-0.371201,0.723914,-0.136875,0.153281,-0.247103,0.014572,0.193130,0.217795,0.537150,0.324725,0.093139,0.142404,-0.164626,-0.244636,0.215074', '6532822', '1294917', '26598021', '3610047');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291584', '杀死比尔2', '动作', '“黑蛇”（乌玛•瑟曼 Uma Thurman 饰）继续上一集未完的复仇之旅。探听得知，前比尔的贴身保镖“响尾蛇”洗手不干后住在得克萨斯州的奥斯汀。当她晚上悄悄溜到“响尾蛇”住的拖车上时，却中了埋伏，被“响尾蛇”用枪击中胸部并被麻醉了。“响尾蛇”将“黑蛇”装到棺材里填埋 了。此时，“黑蛇”苏醒过来，运用她的师傅白眉老道所传授的功夫从棺材里脱身。当她回到“响尾蛇”所住的拖车时，发现“响尾蛇”和另一个追杀目标“加利福尼亚蛇”正在交易她随身携带的宝刀。打斗中，“加利福尼亚蛇”放出的巴曼蛇咬死了“响尾蛇”。“黑蛇”终于见到比尔了，并揭开了自己满门被杀的真相。©豆瓣', '乌玛·瑟曼', '昆汀·塔伦蒂诺', 8.1, 284626, 'tt0378194', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910897532.jpg', 0.4, 1.9, 20.2, 47.3, 30.1, '0.409106,-0.067028,-0.684987,0.403033,-0.073576,-0.458797,0.995140,-0.311391,-0.421006,0.020557,0.260391,0.468797,-0.161368,0.344419,-0.068160,0.075912,-0.385632,-0.580418,-0.079085,-0.250816,-0.514228,-0.022548,-0.423770,0.175235,0.106203,-0.003891,0.453201,0.017356,-0.018536,0.458735,0.181721,0.157621,-0.190147,0.509843,-0.231747,0.230793,-0.045760,-0.404708,0.208323,0.436589,0.044304,-0.419399,0.180650,0.295244,-0.060872,0.708142,0.615385,-0.696487,0.195076,-0.257333,-0.109635,-0.138989,-0.027749,0.364856,0.300698,0.174322,0.163423,-0.037383,-0.465645,0.367374,-0.070712,0.086835,-0.403870,0.005456,-0.362223,0.229790,-0.620933,0.189571,-0.110604,0.275210,0.016457,-0.483608,0.338262,-0.135981,0.098292,0.099152,-0.273124,0.121413,-0.753523,-0.010608,0.329952,-0.446436,0.191083,0.181621,0.492515,-0.436130,0.258032,0.001798,0.391142,-0.378277,0.845767,0.274478,-0.541517,0.004794,-0.580012,-0.145081,-0.402902,-0.063634,-0.166870,-0.019224,-0.503469,-0.590017,0.047713,-0.184281,0.017281,0.076155,-0.102193,-0.159500,0.160544,-0.524697,0.237926,0.388840,0.177007,0.146592,0.400922,-0.438992,0.333467,0.111777,-0.040785,0.177219,0.429282,0.681691,0.495419,0.527377,0.003244,-0.282248,-0.601222,0.625280', '1578663', '21619567', '1303462', '1306670');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291585', '风之谷', '动画', '工业文明的高度发展，却最终带来灾难，一场为期7天的虫族毁灭战争摧毁了人类文明。一千年后，工业文明遗留下来的症结仍在困扰这个星球。带有强烈毒性的植物组成了令人望而却步的“腐海”森林，随着时间的推移，腐海有条不紊地向四周蔓延，蚕食周边世界。在一片腐海森林的旁边，居住着一群御风而行的人类。女主角娜乌茜卡和族人依靠海风的力量抵御着有毒孢子的侵蚀，过着平静祥和的生活。直到某一天，战火烧到了这里。西方强国特洛梅意欲重新建立人类霸权，他们计划统一周边诸国，然后向虫族发起总攻。另一方面，一千年前曾主导摧毁人类的上古怪兽“猛怪”重现人间。毁灭战争一触即发，人类的命运将会如何……本片根据宫崎骏同名漫画改编，并分获1985年罗马奇幻电影节和1985年电影旬报最佳影片奖、1985年每日电影大藤信郎奖。©豆瓣', '岛本须美', '宫崎骏', 8.9, 336255, 'tt0087544', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1917567652.jpg', 0.2, 0.5, 8.8, 35.9, 54.7, '-0.434941,0.365804,-0.577413,0.708194,0.596758,0.214247,0.609712,-0.139963,-0.269705,-0.220512,0.001194,0.283238,-0.090144,0.037887,0.319415,-0.138814,-0.421204,-0.355609,-0.397153,-0.030221,-0.374647,0.079712,-0.662972,-0.262247,0.024110,-0.550788,1.073218,0.449848,-0.400095,0.234435,-0.318782,0.092356,-0.319973,0.262438,-0.012474,-0.052382,-0.025415,-0.078542,-0.592262,0.276286,-0.233164,-0.151732,-0.239450,0.056800,-0.281387,0.032065,0.721341,-0.699972,0.108080,-0.581462,0.510649,-0.540167,-0.181485,-0.145451,0.641539,-0.159335,-0.066309,0.311443,0.062754,0.083024,-0.117314,-0.249156,-0.713463,-0.105022,-0.089582,0.119854,-0.190365,0.529073,0.518082,0.155872,-0.265568,-0.143621,0.095206,0.561710,0.400261,0.396241,-0.123643,0.083117,-0.388764,0.203873,0.729492,-0.243983,-0.686864,0.198826,-0.354906,-0.565813,-0.563537,-0.501755,-0.550509,-0.211202,0.175687,0.281162,-0.003901,0.793152,-1.089727,0.237278,-0.074527,-0.672885,0.395974,-0.098794,-0.035726,-0.675892,-0.282545,-0.206868,-0.106481,0.025531,0.090297,-0.141606,0.810362,-0.426843,0.309202,0.775482,0.451047,-0.332045,0.447985,-0.149419,-0.021533,-0.174682,-0.180108,0.678745,-0.220953,0.690039,0.004618,0.180114,0.094203,0.169567,-0.155601,0.683081', '26290398', '24879819', '25890017', '26873582');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291586', '海底总动员', '喜剧', '在澳洲大堡礁的深海中，小丑鱼爸爸玛林和儿子尼莫简单幸福的生活着，可是爸爸做事常常畏首畏尾，是个胆小鬼，尼莫觉得爸爸很不勇敢，甚至有点看不起自己的爸爸。小尼莫却天不怕地不怕，跟同伴们去水面玩耍的时候，竟然被渔网捞了起来，辗转被卖到一家牙医诊所。玛林对儿子的生死未卜感到十分的担忧，就算平时不能大胆行事，为了儿子也要勇敢豁出去了。可是在路上遇到了很多艰难与恐惧，令他十分胆怯。幸好他遇到了好心的多瑞，一路与他作伴。父子俩都遇到了很多热心的帮助，最终都能重逢，玛林也从此成为儿子以及大家心中的英雄。©豆瓣', '艾伯特·布鲁克斯', '安德鲁·斯坦顿', 8.5, 362198, 'tt0266543', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1755893801.jpg', 0.1, 0.5, 13, 49.1, 37.4, '0.174634,-0.308194,-0.775172,0.560546,-0.408735,-0.476852,0.687320,0.027999,-0.673647,-0.103528,-0.086175,0.916117,-0.015810,0.370486,0.049923,0.028887,-0.151064,-0.275212,0.008270,-0.025218,-0.117934,-0.295322,-0.277890,-0.234646,-0.398065,-0.181975,0.289581,0.011140,0.003044,0.381543,0.199364,0.187473,-0.032458,0.502089,-0.494149,0.016917,-0.079204,0.112364,0.042333,-0.126946,0.213223,0.124893,-0.165122,0.444196,0.382343,0.191954,0.489005,-0.109806,-0.380709,-0.077040,0.141459,-0.261072,0.145232,0.184434,0.111891,-0.147396,0.394849,0.043289,-0.062994,0.010784,0.259472,0.034964,-0.813495,0.335411,0.131032,0.028091,-0.815900,0.118585,0.069362,-0.207955,0.210034,-0.568687,0.292877,0.370831,0.171938,0.378486,-0.411202,0.092470,-0.778184,-0.217148,0.965506,0.099856,0.092182,0.262981,-0.121173,-0.075762,0.523393,-0.365791,-0.738323,0.059771,0.145220,-0.079982,-0.536802,0.317177,-0.546297,0.125888,-0.172834,-0.215492,-0.166861,-0.558522,0.024074,-0.016216,0.078012,-0.659380,-0.324004,0.090912,-0.084659,-0.322054,0.840788,-0.942578,0.221633,0.560503,0.359790,-0.527309,0.599693,0.352244,-0.145569,0.052753,0.073653,0.035938,0.046954,0.077041,0.277198,0.293999,-0.016692,-0.289386,-0.115957,0.443706', '1877596', '25721544', '1308805', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291587', '埃及王子', '剧情', '法老发现自己的王国内希伯来人日益增多，开始感到不安，对希伯来人总是无端猜疑，于是命令所有的希伯来人都去当奴隶，并吩咐讲所有希伯来人生的男孩扔到河里。这天，一个希伯来妇女生了一个漂亮的男孩，为了自己的孩子能够幸免于难，她将他放到一个草箱中放进了尼罗河。皇后在河边捡到了这个漂亮的男孩，将他带回宫殿抚养，取名摩西。摩西和王子兰姆蒂斯一起长大，两人成了最好的朋友。摩西十分反对法老对希伯来人的暴政，一次他为了阻止一名埃及人残害希伯来人而将失手将他打死。为了逃避法老的惩罚，摩西逃到了米甸地。不久法老去世，兰姆蒂斯成了新法老。摩西原本以为兰姆蒂斯会一改以往法老对希伯来人的暴政，没想到兰姆蒂斯反而变本加厉。在神的指示下，摩西知道了自己的身世，于是他决定要带领希伯来人走出困境。©豆瓣', '方·基默', '布兰达∙查普曼', 8.1, 40137, 'tt0120794', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910899200.jpg', 0.4, 1.6, 21.8, 47, 29.2, '0.370321,0.191608,-0.671853,0.580277,-0.454094,-0.438327,0.722133,-0.034373,-0.513505,-0.140503,0.205104,0.902352,0.066983,0.037502,0.412193,0.111204,-0.489539,-0.417315,-0.148996,-0.189336,-0.182834,-0.434998,-0.014863,-0.292352,-0.327955,-0.483200,0.242602,-0.434768,0.068534,0.189590,0.316408,0.384786,0.105838,0.191789,-0.255618,0.251773,-0.024447,-0.300542,0.023932,0.431993,-0.076233,-0.169241,-0.107715,0.361625,-0.055261,0.298397,0.528946,-0.618727,0.218747,-0.344427,0.360292,-0.477445,-0.173612,0.450127,0.259302,-0.168016,-0.202458,0.139940,-0.141060,-0.068935,0.304661,-0.175221,-0.524136,-0.064228,-0.197579,0.219803,-0.800723,0.170401,-0.057351,0.070516,0.294555,-0.509738,0.319972,0.364618,0.062612,0.365073,-0.190135,-0.209156,-0.498390,-0.006255,0.656361,-0.285823,-0.015912,0.022564,-0.120312,-0.396372,0.245164,0.078127,-0.444239,-0.093136,0.614031,0.059986,-0.167266,0.435681,-0.539300,-0.393104,-0.483383,-0.368214,0.059361,-0.608018,-0.101692,-0.148435,-0.153583,-0.115592,-0.032130,-0.152173,0.063580,-0.127880,0.641682,-0.641531,0.511077,0.433080,0.450545,-0.331207,0.159381,0.184098,0.202247,-0.129918,-0.049439,0.405859,0.299135,0.368378,-0.023509,0.240512,-0.067741,-0.171387,-0.334214,0.207904', '1309069', '1299965', '26393561', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291588', '岁月的童话', '剧情', '妙子今年27岁了，她向公司请了十天的假，到乡间享受向往已久的乡村生活。自此，她便常常想起了她五年级那一年的往事。一路上不断回想五年级时发生的往事，到达目的地后，迎接她的是一名乡村小伙子，比她小2岁的俊雄。她开始了农民的生活，并乐在其中，向俊雄分享她小时候的点点滴滴，在乡间看到的景色都能勾起美好的回忆。两人相处甚欢，一起感受岁月流逝的痕迹。正在她要离开的前一天晚上，俊雄的奶奶竟向妙子建议与俊雄结婚，顿时又牵起了妙子的回忆……©豆瓣', '今井美树', '高畑勋', 8.6, 132424, 'tt0102587', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453886709.jpg', 0.2, 0.8, 12.2, 41.1, 45.7, '0.372492,-0.116387,-0.620356,0.229749,-0.076678,-0.520098,0.796017,0.114029,-0.492598,-0.055074,0.179168,0.629963,-0.417066,0.821701,0.402077,0.062819,-0.399033,-0.751257,0.170370,-0.367236,-0.074658,-0.139165,0.048949,-0.020026,0.020029,-0.330198,0.228107,0.101314,0.191358,0.637169,-0.231527,-0.197871,-0.032012,0.439182,-0.531294,0.181524,-0.014533,0.378730,-0.300881,-0.050091,0.133178,-0.390803,-0.310929,-0.164808,0.018239,0.405715,0.983743,0.193526,-0.293097,0.156663,0.290786,0.080669,-0.061521,0.202335,0.342373,0.223969,-0.099350,0.252516,-0.229098,-0.150859,-0.348493,-0.215394,-0.207754,0.200974,-0.010586,0.175298,-0.517842,0.466335,0.282815,0.079984,0.468059,-0.377043,0.104253,0.578463,-0.082972,0.530230,-0.187850,0.044017,-0.435518,0.635802,0.854913,-0.157051,-0.104258,0.866423,-0.289870,-0.217817,-0.145088,0.033415,-0.427982,0.097700,-0.007474,0.129568,-0.499576,0.389980,-0.565840,0.056936,-0.058255,-0.350771,0.216855,-0.271641,-0.360966,-0.704751,-0.256536,-0.655693,-0.261175,0.132679,0.063996,-0.349859,0.612262,-0.792987,0.144977,0.635684,0.326368,-0.193182,0.781589,0.117856,-0.193924,-0.094451,0.280596,0.375594,-0.299422,0.371517,0.074099,0.586035,-0.204207,0.066711,-0.609719,0.640968', '26687241', '2365260', '3041753', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291818', '饮食男女', '剧情', '台湾中国菜硕果仅存的大师老朱（郎雄）退休后，渐尝老年生活的诸多尴尬：每周日费心做出的一桌丰盛菜肴，并无将三个女儿（杨贵媚、吴倩莲、王渝文）齐齐拉到饭桌的吸引力，已经长大成人的她们，心里藏了许多比陪父亲吃饭更重要的事；多年老友的突然离世，令他在友情这块也有了缺口；而对厨师来讲最重要的味觉的丧失，则将其彻底推到人生的低谷。三个女儿虽各忙各事，却也操心着老朱的晚年生活，计划着为其找个老伴，但她们没料到老朱早已悄无声息地谈起了“黄昏恋”。吃惊过后，老朱最看重的继承了他做菜天赋的二女儿家倩因为自身的生活经历，对父亲、她与父亲的关系有了新的认识，而对老朱来讲更大的惊喜，还在后面。©豆瓣', '郎雄', '李安', 9.2, 572166, 'tt0111797', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910899751.jpg', 0.1, 0.3, 4.8, 31.3, 63.6, '0.308421,-0.086824,-0.808392,0.606463,-0.213762,-0.544962,0.823132,0.278626,-0.487018,-0.366532,0.009497,0.698698,0.034617,0.456927,0.200957,-0.318308,0.002999,-0.539947,-0.032870,-0.091097,-0.432652,-0.453883,-0.064780,-0.303761,-0.453553,-0.098019,0.308480,-0.021847,-0.025293,0.409906,0.270969,-0.141317,0.293520,0.638147,-0.299914,0.142784,-0.109714,0.216248,-0.362043,-0.135301,0.240746,-0.274336,-0.130920,0.311755,0.158729,0.343230,0.457799,-0.082297,-0.434157,0.024791,0.368889,-0.350728,0.003729,0.101127,0.496178,0.048751,-0.030732,0.148861,-0.332287,0.065017,0.024915,-0.184090,-0.946520,0.017665,0.115594,-0.169692,-0.727364,0.511474,0.129089,-0.238203,-0.003803,-0.495687,0.339973,0.429120,0.015534,0.473727,-0.185339,0.174860,-0.302304,0.198908,0.629830,-0.083713,0.004318,0.426158,-0.135679,-0.411949,0.059675,-0.401928,-0.307245,0.031857,0.203948,0.236807,-0.056599,0.243170,-0.326629,0.109328,0.112513,-0.331762,0.161415,-0.519480,0.037910,-0.325310,-0.310835,-0.580426,-0.407009,0.090093,0.277128,-0.263139,0.958031,-0.567586,0.197743,0.128030,0.149785,-0.729939,0.649219,0.122299,0.324954,-0.313386,-0.167719,0.141611,-0.115566,0.040532,0.165035,0.355687,-0.075043,-0.097963,-0.316293,0.381967', '30163500', '26678784', '26283288', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291822', '卢旺达饭店', '剧情', '1994年卢旺达宣布独立后，胡图族与图西族两部族之间矛盾重重，多次发生冲突，战事持续不断。胡图族大肆屠杀图西族人，在这种背景下，卢旺达饭店经理保罗一直四面奔走，最终成功挽救了饭店里一千多名图西族和胡图族难民。©豆瓣', '唐·钱德尔', '特瑞·乔治', 8.9, 305314, 'tt0395169', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p470419493.jpg', 0.1, 0.3, 6.5, 38.2, 54.8, '0.193771,0.286710,-0.451984,0.182036,0.727902,0.337308,0.545418,-0.223403,-0.788093,0.004304,-0.105276,0.304364,-0.359421,-0.017196,0.246728,-0.407913,-0.394970,-1.022312,-0.334939,-0.013555,-0.153091,-0.297958,-0.300366,-0.343360,-0.363724,-0.062370,0.201654,0.534222,0.243092,0.710719,-0.319700,0.245605,-0.437451,0.466642,0.005659,0.099268,0.490232,-0.282257,-0.715502,0.369088,-0.378282,-0.065470,-0.427690,-0.034545,0.273519,0.539351,0.593183,-0.446602,0.244123,-0.324069,-0.148053,0.092376,-0.240730,0.344329,0.886274,-0.059324,0.687390,0.341047,0.037327,-0.383218,-0.208807,0.195504,-0.055998,0.076025,-0.239139,-0.048408,-0.483441,0.598387,0.202060,0.229585,0.222166,-0.202510,-0.135026,0.803524,0.370705,0.151105,-0.097850,-0.285157,-0.682078,-0.113312,1.338438,0.004037,-0.525024,-0.219705,-0.168995,-0.307264,0.084720,-0.277669,0.040657,-0.404568,-0.165889,-0.330344,0.342782,0.450120,-0.995882,0.060000,-0.437019,-0.381217,0.103956,0.147904,0.020303,-0.503862,-0.392811,-0.262670,-0.189666,0.116707,-0.138848,0.354262,0.333709,-0.587454,0.325945,0.350414,0.717812,-0.613212,0.158688,0.199653,0.344572,0.266154,-0.063786,0.076117,0.313790,0.174228,0.335163,0.108879,-0.355336,-0.317680,0.329187,-0.100412', '2084048', '1294713', '25856453', '25978126');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291823', '翻译风波', '悬疑', '希尔维亚（妮可·基德曼 Nicole Kidman饰）是非洲籍的联合国翻译员。无意间她听到一桩政治阴谋，联合国大会上他们策划谋杀一名非洲元首。他们用非洲土话来交谈，不料被掌握这门语言的希尔维亚窃听机密。希尔维亚因此成为别人急于除掉的眼中钉。FBI派探员托宾（西恩·潘 Sean Penn饰）做希尔维亚的临时保镖。性格迥异的两人在相处中渐渐了解对方的身世和背景，这时托宾怀疑希尔维亚可能藏着一段不为人知的秘密，希尔维亚和这个卷入谋杀计划的非洲元首之间，似乎有着深仇大恨。这令到托宾心生疑窦：希尔维亚到底是事件的受害者，还是阴谋的参与者？托宾既心存怀疑，又要坚定地履行职责，保护希尔维亚。二人在猜忌中互相吸引着。在越来越危险的境地下，他们必须尽快查出真相。©豆瓣', '妮可·基德曼', '西德尼·波拉克', 6.6, 17759, 'tt0373926', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1910900170.jpg', 0.7, 8.3, 55.4, 29.3, 6.3, '0.733424,0.094951,-0.602980,0.565724,-0.077245,0.096028,0.698423,-0.156853,-0.573946,-0.151589,0.452540,0.605462,-0.001826,-0.060321,0.313865,0.116286,-0.756818,-0.660580,0.289754,-0.197986,0.150446,-1.075360,-0.689679,-0.227986,-0.151397,-0.282512,0.340066,0.000897,-0.407736,0.135800,0.124511,0.643800,-0.194522,0.410066,0.512959,-0.030099,0.550563,-0.312083,-0.229821,0.153348,0.078675,-0.088193,-0.429192,0.172508,0.072859,0.606978,0.224549,-0.279416,0.022900,-0.126767,0.305063,-0.322630,0.338947,0.108854,0.329848,-0.128731,0.113318,0.492695,-0.203543,-0.038652,0.214228,0.145393,-0.644456,0.204236,0.218615,0.407077,-0.467959,0.025856,-0.304630,-0.042005,0.081234,-0.155883,0.158102,0.679455,0.604079,0.242528,-0.054287,0.107148,-0.518023,-0.349753,0.517466,-0.074227,-0.232377,-0.310845,-0.290945,-0.452785,-0.074771,0.041056,-0.306888,-0.402961,0.541066,0.007184,-0.024522,0.757888,-0.370372,-0.336097,-0.292946,-0.029751,0.030442,-0.560604,0.132158,-0.554022,-0.147608,-0.418211,-0.399616,-0.260666,0.279244,-0.191257,0.456072,-0.522416,0.169321,0.426906,0.191460,-0.346985,0.391832,0.051375,0.216666,-0.434216,-0.222814,0.318454,0.202118,-0.226417,0.161564,0.324280,0.533318,-0.186514,-0.239815,0.302744', '25789402', '1296217', '1298981', '30318116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291824', '黑鹰坠落', '动作', '1992年，连年的部落战争令东非国家索马里山河破败，民不聊生，由此引发的大饥荒更造成三十万人死亡。掌控首都摩加迪休的独裁者默罕默德•法拉•艾迪德抢走国际组织的救援物资，此举引起世人公愤。丧心病狂的艾迪德向国际维和组织宣战，美国方面派出160名特种部队成员前往摩加迪休以推翻艾迪德政权。这群满腔热血的战士信心十足，然而却因情报搜集不足而使战事陷入胶着状态。在一次追捕艾迪德政权两大高官的行动中，特种部队受到索马里民兵的顽强抵抗。双方在市中心展开激烈对峙，美军一架黑鹰直升机受到攻击坠落市区，机组人员危在旦夕。为了营救同伴，一小队特种部队士兵深入虎穴。在接下来的15小时里，他们经历了人间最难以想象的修罗场……©豆瓣', '乔什·哈奈特', '雷德利·斯科特', 8.7, 270062, 'tt0265086', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1910900710.jpg', 0.2, 0.7, 10.3, 41.8, 46.9, '0.044499,-0.056234,-0.802373,0.336953,0.349195,0.368201,0.420250,-0.127812,-0.636459,-0.063110,0.530054,0.447419,0.093922,-0.422000,0.327324,-0.512136,-0.349492,-0.586911,-0.293129,-0.078294,-0.167427,-0.365322,-0.322364,-0.407072,0.039992,-0.377642,0.846694,0.385012,-0.469836,0.488161,-0.069683,0.347628,-0.109898,0.432695,0.260455,-0.164460,0.223967,-0.457806,-0.457702,0.209272,-0.493486,-0.236620,-0.359362,0.298948,-0.106513,0.239837,0.732802,-0.404156,0.105957,-0.669494,0.129853,-0.725022,-0.168732,-0.168994,0.831564,-0.004789,-0.112157,0.094311,0.050003,0.031412,-0.134775,0.002061,-0.493814,0.064135,0.020558,0.039444,-0.338478,0.458976,-0.301644,0.340305,0.130766,0.035300,0.078363,1.133028,0.264279,0.180845,-0.172187,-0.132895,-0.634713,0.009890,1.089522,-0.342160,-0.485923,-0.514461,-0.144642,-0.445797,-0.048360,-0.710314,-0.191054,-0.199602,0.237380,-0.397834,0.180394,0.680597,-0.606449,0.289061,-0.372906,-0.686063,-0.073998,-0.115356,-0.085773,-1.024115,-0.078758,-0.128957,-0.014410,0.433703,0.190058,0.402454,0.813824,-0.586413,-0.010444,0.458340,0.608836,-0.544716,0.077190,0.031477,0.188732,-0.090038,-0.205056,0.400706,0.234065,0.428430,0.099274,-0.303881,-0.325649,-0.263987,0.096820,-0.230319', '6007281', '3871833', '3074408', '26718836');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291828', '天堂电影院', '剧情', '意大利南部小镇，古灵精怪的小男孩托托（萨瓦特利·卡西欧 饰）喜欢看电影，更喜欢看放映师阿尔弗雷多（菲利浦·诺瓦雷 饰）放电影，他和阿尔弗雷多成为了忘年之交，在胶片中找到了童年生活的乐趣。好心的阿尔弗雷多为了让更多的观众看到电影，搞了一次露天电影，结果胶片着火了，托托把阿尔弗雷多从火海中救了出来，但阿尔弗雷多双目失明。托托成了小镇唯一会放电影的人，他接替阿尔弗雷多成了小镇的电影放映师。托托（马克·莱昂纳蒂 饰）渐渐长大，他爱上了银行家的女儿艾莲娜（阿格妮丝·那诺  饰）。初恋的纯洁情愫美如天堂，但是一对小情侣的海誓山盟被艾莲娜父亲的阻挠给隔断了，托托去服兵役，而艾莲娜去念大学。伤心的托托在阿尔弗雷多的鼓励下，离开小镇，追寻自己生命中的梦想……30年后，阿尔弗雷多去世，此时的托托已经是功成名就的导演，他回到了家乡，看到残破的天堂电影院，追忆往昔，唏嘘不已。', '菲利普·努瓦雷', '朱塞佩·托纳多雷', 9.2, 642915, 'tt0095765', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2653054340.jpg', 0.1, 0.4, 5.3, 28, 66.3, '0.267829,-0.073524,-0.751927,0.264244,-0.366112,-0.713831,0.953099,0.089450,-0.334316,0.330053,-0.092041,1.089163,-0.249014,0.305145,0.075024,0.256704,-0.647779,-0.534205,0.134926,-0.359961,-0.043239,-0.440344,-0.140800,-0.210817,-0.009692,-0.409471,0.324492,0.173162,0.209323,0.163750,0.304782,-0.141286,0.040247,0.323644,-0.052038,0.258278,0.270335,0.272647,-0.102016,0.271965,0.039678,0.217488,-0.304007,0.028579,0.100032,0.093379,0.563546,-0.144802,0.030680,0.023530,0.713256,-0.178237,0.248647,-0.074713,-0.055168,-0.069243,0.035359,-0.474287,-0.191764,0.059381,-0.139684,-0.046130,-0.406778,0.090242,0.112878,-0.029561,-0.873795,0.493862,-0.064699,-0.327275,0.400941,-0.436761,0.249920,0.104171,0.405418,0.410889,-0.272695,-0.214073,-0.467552,0.392892,0.347877,-0.009297,-0.058149,0.420107,-0.441611,-0.508118,0.022227,-0.117891,-0.259291,-0.157429,0.817486,-0.431680,-0.272488,0.575490,-0.493561,0.028967,-0.369065,-0.334517,-0.265920,-0.324960,-0.113727,-0.468321,-0.122801,-0.477630,-0.129611,-0.012438,0.146936,-0.290770,0.812676,-0.643080,0.443924,0.681536,0.562841,0.068712,0.718056,0.127019,-0.029601,0.059706,0.169999,0.787955,-0.032149,0.337703,0.273958,0.276220,-0.102128,-0.294607,-0.436888,0.550740', '1309069', '1292207', '6128003', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291831', '灿烂人生', '剧情', '马里奥（阿莱西奥•博尼 Alessio Boni 饰）和尼古拉（卢伊吉洛•肖卡 Luigi Lo Cascio 饰）是亲密无间的两兄弟，但是酷爱诗歌的马里奥却在考试中因为与教授意见相左而不及格，相反尼古拉投其所好的表现赢得了医学教授的好评拿到了高分。他们几个朋友相约去毕 业旅行，但是马里奥却带来了另外一个不速之客——他从精神病院搭救出来受伤的女孩佐珍（杰丝敏•特丽卡 Jasmine Trinca 饰）。于是，兄弟俩决定陪她寻找亲人。在一片革命洪流之中，马里奥弃笔从戎，选择做警察，而尼古拉则漂泊异乡成为了精神科医生。佛罗伦萨的大水，让兄弟俩重逢，此时尼古拉已经和钢琴师朱莉安成为伉俪。而马里奥则对摄影师米雷拉一见钟情。他们的感情同样经受着社会动荡的考验……本片片长6个小时，通过讲述意大利一家人的悲欢离合，反映了意大利从1966年至2000年的社会巨变。', '路易吉·洛·卡肖', '马可·图利奥·吉奥达纳', 9.4, 63791, 'tt0346336', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1161132422.jpg', 0.3, 0.5, 4.1, 20.3, 74.8, '0.200475,-0.271537,-0.433235,0.452486,0.066738,-0.557456,0.660372,0.086838,-0.387386,-0.207040,0.170396,0.653872,-0.256666,0.242349,0.567458,-0.333459,-0.345868,-0.620897,0.083775,-0.186960,-0.217426,-0.518372,-0.059645,-0.356868,-0.136512,-0.214750,0.521524,-0.088036,-0.039423,0.625067,0.100083,0.262707,0.114061,0.324981,0.025809,0.073282,0.148796,0.095344,-0.615719,0.405754,0.244211,-0.076215,-0.369133,0.174290,0.106320,0.312195,0.619894,-0.292631,0.065462,0.036132,0.249813,-0.262592,-0.083745,-0.033450,0.176422,0.085037,0.124134,0.207454,0.059048,-0.027680,-0.051225,-0.225642,-0.400480,0.160951,0.021709,0.248818,-0.470719,0.604183,-0.134480,-0.228200,-0.038747,-0.225845,0.090483,0.362393,0.177367,0.500512,-0.236040,0.048905,-0.508048,0.199247,0.651831,-0.026321,-0.155449,0.225553,-0.395605,-0.490575,0.080366,-0.092115,-0.447758,-0.135830,0.186100,-0.051407,0.047326,0.318900,-0.537382,-0.019799,-0.281267,-0.145110,-0.067537,-0.400800,0.258754,-0.598563,-0.183261,-0.095497,-0.224515,0.119722,0.092289,-0.244968,0.891946,-0.545831,0.162136,0.415073,0.371043,-0.276319,0.972550,0.057585,0.042330,-0.412474,-0.092204,0.292625,0.037307,-0.000268,0.171666,0.429508,0.067027,-0.158569,-0.228350,0.388438', '1306860', '38