INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291832', '低俗小说', '剧情', '《低俗小说》由“文森特和马沙的妻子”、“金表”、“邦妮的处境”三个故事以及影片首尾的序幕和尾声五个部分组成。看似独立的小故事里面，却又有环环相扣的人和事。盗贼“小南瓜”和“小兔子”在早餐店里打劫，却遇上了天大的麻烦——黑社会成员朱尔斯（塞缪尔•杰克逊Samuel L. Jackson饰）和文森特（约翰•特拉沃尔塔John Travolta饰）在店内用餐，可谓天外有天。二人是否会放过两名小盗贼？而文森特是黑社会大哥马沙•华莱士（文•瑞姆斯Ving Rhames饰）的手下，马沙下命令让他陪妻子一个晚上，明知如有雷池必死无疑，但面对马沙妻子美艳诱惑，文森特该怎么办。文森特的故事还没完，拳击手布奇（布鲁斯•威利斯Bruce Willis饰）的出现将令他的人生从此改变。布奇有一块祖传金表，就是因为这块金表，他和马沙分享了一个耻辱的秘密。故事环状结构，回到开端。朱尔斯在小盗贼面前诵读圣经，表示对杀人的厌倦和感悟。什么事件令他如此转变？“邦妮的处境”中就有答案。', '约翰·特拉沃尔塔', '昆汀·塔伦蒂诺', 8.9, 777213, 'tt0110912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910902213.jpg', 0.3, 0.8, 8.8, 35, 55.1, '0.158202,-0.152945,-0.407012,0.478495,-0.041196,-0.085132,0.722385,0.319739,-0.434275,-0.308880,0.073956,0.722295,-0.190488,0.007840,0.242022,0.069393,-0.398148,-0.531908,0.040371,-0.107823,-0.195764,-0.546958,-0.211397,-0.321966,-0.010329,-0.173107,0.412032,0.020955,-0.347584,0.194749,0.452471,0.166612,-0.123501,0.284198,-0.033380,0.063848,0.188650,0.019394,-0.236537,-0.002439,0.040225,0.029311,-0.127827,0.235059,0.156291,0.213112,0.506587,-0.398419,-0.054746,0.000586,0.067767,-0.258702,-0.039790,0.054976,0.072985,-0.079346,0.199657,0.112880,-0.088902,-0.050064,0.194307,-0.282620,-0.614762,0.048759,0.210170,0.305622,-0.424611,0.101613,-0.300556,-0.066350,0.184582,-0.328826,0.064651,0.349379,0.307083,0.435744,0.029146,-0.101849,-0.648160,-0.097866,0.441692,0.168528,-0.110656,0.078217,-0.064649,-0.423948,-0.192299,-0.016394,-0.391918,0.073437,0.248849,-0.184241,-0.027523,0.320421,-0.709062,-0.056659,-0.278012,0.045808,-0.046765,-0.510329,-0.091036,-0.649316,0.033068,-0.321439,-0.345009,0.169006,0.128960,-0.151375,0.698381,-0.653411,0.376267,0.307444,0.261472,-0.286799,0.601785,0.264959,0.215542,-0.325574,0.111491,0.077373,0.185416,-0.209824,0.179274,0.335991,0.033522,-0.218903,-0.171387,0.466201', '4301278', '1309101', '6858739', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291833', '杯酒人生', '剧情', '迈尔斯（保罗•吉亚玛提 Paul Giamatti 饰）和杰克（托马斯•哈登•丘奇 Thomas Haden Church 饰）是老朋友了，看着杰克即将踏入婚姻殿堂，迈尔斯更加感叹起自己失败的生活：婚姻失败、作家梦遥不可及、干着无聊枯燥的职业、不再年轻的岁数。迈尔斯对葡萄酒的研究颇为深厚，于是两个人决定前往加州的葡萄酒生产基地狂欢一次，如果遇上一夜情当然是最好不过了。果然二人在酒香浓郁的加州遇上了女招待和她的亚裔朋友，迈尔斯和杰克的艳遇让两人都兴奋不已。然而接下来的事情却大扫兴致。他们的狂欢计划充满了障碍。©豆瓣', '保罗·吉亚玛提', '亚历山大·佩恩', 7.9, 54589, 'tt0375063', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910902469.jpg', 0.3, 1.8, 23.1, 50.7, 24, '0.323564,-0.330912,-0.635343,0.442761,-0.181475,-0.491289,0.857774,0.182130,-0.605830,-0.271545,0.103444,0.881401,-0.375646,0.124351,0.455796,-0.175432,-0.355796,-0.532407,-0.023460,-0.157652,-0.185079,-0.565241,-0.028135,-0.374704,-0.053610,-0.362628,0.584970,0.081443,-0.081766,0.392306,0.336950,0.201423,-0.003214,0.530322,-0.278520,-0.101297,0.403278,0.215989,-0.634340,0.210401,0.212178,0.063620,-0.286526,0.237418,0.208698,0.033670,0.552378,-0.046486,-0.364579,0.021975,0.136972,-0.442686,-0.072446,0.072556,0.170470,0.006491,0.162950,0.278767,0.002934,-0.086636,-0.147645,-0.173553,-0.608405,0.323939,0.014960,-0.113369,-0.499806,0.609262,0.080952,-0.171820,0.166360,-0.222230,0.266385,0.341764,0.579875,0.333043,0.019781,0.040043,-0.599667,0.123124,0.672679,0.269764,-0.134112,0.613198,-0.297826,-0.431983,-0.190471,0.001432,-0.410437,0.077973,0.311160,-0.022579,-0.074120,0.324520,-0.795210,0.080363,-0.085950,-0.372017,0.125268,-0.341317,-0.092937,-0.645707,-0.101108,-0.304475,-0.570829,0.101340,0.115465,-0.215302,0.618145,-0.872075,0.028776,0.499947,-0.023794,-0.411571,0.709221,0.179242,0.091451,-0.444659,0.009428,0.156460,-0.318437,-0.007808,0.162019,0.512100,0.000339,-0.181097,-0.276757,0.518987', '6858739', '11541282', '1308755', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291835', '迷失东京', '剧情', '一切源自于无处不在的寂寞。当寂寞蔓延到头顶无法呼吸，过气电视明星鲍勃·哈里斯(比尔·默瑞 Bill Murray 饰)，已为人妻的夏洛特(斯嘉丽·约翰逊 Scarlett Johansson 饰)，年轻貌美的电影女演员凯莉(安娜·法瑞丝 Anna Faris 饰)在机缘巧合下在东京相遇。在这个不是故乡的陌生城市里，他们在豪华旅馆邂逅，不约而同的失眠，互相 陪伴，生活一方面仿佛变的缤纷起来，另一面却逐渐走向迷失，过气明星和为人妻的夏洛特能迎接他们二人思想和关系变化的挑战吗？冲破迷失或者身陷其中，让我们一起找寻答案。©豆瓣', '斯嘉丽·约翰逊', '索菲亚·科波拉', 7.8, 208523, 'tt0335266', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p492754135.jpg', 0.4, 2.9, 28.1, 45.9, 22.8, '0.242873,-0.000745,-0.818772,0.493627,-0.009370,-0.227783,1.046688,0.343327,-0.414056,-0.166101,0.035538,0.749391,-0.364045,0.361239,0.187411,0.007537,-0.370406,-0.694290,-0.010822,-0.110634,0.023331,-0.386249,-0.360471,-0.268062,-0.018215,-0.486129,0.758582,0.214833,-0.120133,0.401936,0.301402,0.056109,-0.325030,0.476045,-0.205878,0.019266,0.101011,0.115470,-0.607663,0.179289,-0.180505,-0.198910,-0.012648,0.140048,0.044464,0.052323,0.691870,-0.208558,-0.005029,0.038711,0.314361,0.028500,-0.079850,0.183859,0.138491,-0.002372,0.343143,-0.091032,-0.088974,0.140728,-0.045284,0.121646,-0.631085,0.243788,0.413489,0.336344,-0.490318,0.265619,0.029626,-0.373934,0.010495,-0.302148,0.245733,0.110669,0.262955,0.435018,-0.131251,0.119911,-0.436031,0.069058,0.946943,0.186951,-0.307221,0.475182,-0.384887,-0.121822,-0.232699,0.142261,-0.672338,-0.213136,0.145125,-0.039296,-0.016742,0.301613,-0.590113,0.015205,-0.010954,-0.143597,-0.113819,-0.501659,-0.212548,-0.645817,-0.231379,-0.280412,-0.026470,0.087080,-0.049425,-0.232755,0.515904,-0.912141,0.296877,0.510203,0.309186,-0.376194,0.765593,0.192369,0.072183,-0.200474,-0.053415,0.575221,-0.181989,0.208619,-0.003127,0.243915,-0.216291,0.373513,-0.803337,0.526925', '1296534', '4275444', '1308755', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291836', '戴珍珠耳环的少女', '剧情', '少女葛利叶（斯嘉丽•约翰逊 Scarlett Johansson 饰）家境贫寒，于是来到画家维梅尔（科林•费尔斯 Colin Firth 饰）家做女佣。维梅尔和妻子、岳母一起生活，她们常常摆出颐指气使的神情，妻子对正当青春的葛利叶更是戒心重重。在非常苛刻和压抑的氛围下，葛利叶在维梅尔家过得卑躬屈膝。维梅尔的画带给了她一点生活的乐趣。她收拾主人画室的时候，流露出了对艺术的天分。她跟维梅尔谈论对画的理解，二人的交心让彼此的情意慢慢滋长。葛利叶知道不可能与维梅尔修得正果，但她愿意做模特奉献给维梅尔作画。她默默地，忍受着维梅尔给她的耳朵打上洞，戴上他妻子的珍珠耳环，画出这一刻的窒息的美丽。©豆瓣', '科林·费尔斯', '彼得·韦柏', 7.8, 159126, 'tt0335119', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p478284105.jpg', 0.2, 1.4, 26.5, 52.3, 19.7, '0.276848,-0.069082,-0.767164,0.707499,-0.309118,-0.311180,0.911128,0.316940,-0.363261,0.042443,0.242401,0.673555,-0.290319,0.343180,0.222502,0.017707,-0.311052,-0.862376,-0.014710,-0.060214,0.033627,-0.302816,-0.042992,-0.234000,-0.184196,-0.424579,0.366208,0.011156,0.029305,0.384015,0.131726,0.052225,0.264080,0.367189,-0.220608,-0.059004,-0.375083,0.236879,-0.370329,-0.124978,0.291836,-0.030099,-0.233072,0.099743,0.052441,0.138319,0.679175,-0.250710,-0.346302,0.222093,0.256699,-0.091628,0.081605,0.215097,-0.220151,-0.003954,0.096325,0.053187,-0.320006,0.072478,0.232142,-0.082217,-0.578535,0.065941,0.169583,0.131579,-0.726174,0.593496,-0.086267,-0.040452,0.102998,-0.452302,0.128093,0.057392,0.230967,0.588109,-0.125633,0.213323,-0.592788,0.298729,0.506256,0.167599,-0.071678,0.462982,-0.698724,-0.242470,-0.168611,-0.305443,-0.549746,-0.278858,0.028629,0.113234,-0.212964,0.063436,-0.556861,-0.192554,-0.012690,-0.142756,0.189902,-0.889421,-0.042233,-0.427808,-0.366786,-0.678378,-0.374329,-0.076167,0.199277,-0.429867,0.702138,-0.814897,0.290746,0.400180,0.187801,-0.400312,0.841778,0.283662,-0.100893,-0.141553,-0.332211,0.236331,-0.113004,0.110181,0.197746,0.524327,-0.009509,0.272928,-0.564490,0.514377', '1292211', '3629232', '3230462', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291838', '红猪', '喜剧', '罗森是一战中意大利空军的王牌飞行员，但却被施了魔法变了一头猪。虽然变了猪，但罗森还是继续他的老本行，成了一位赏金猎人，专门打击在亚地里亚海空域作恶的空中劫匪。红猪侠一时威名远扬，令劫匪们闻风丧胆。匪徒们为了对付罗森，请来了超级飞行员卡基斯。卡基斯在于罗森对决中趁他发动机故障将其击落。罗森把飞机送到老朋友比克罗处修理时，遇上了比克罗的孙女菲欧。菲欧帮罗森修好了飞机，两人一起再度翱翔蓝天对付空中劫匪。这时，卡基斯出现了，他对菲欧一见钟情。为了争夺菲欧的爱，卡基斯向罗森提出决斗。于是两人再次浴血蓝空。©豆瓣', '森山周一郎', '宫崎骏', 8.6, 185443, 'tt0104652', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1637195728.jpg', 0.2, 0.7, 13.5, 42.4, 43.2, '0.309169,-0.040702,-0.401615,0.462758,0.090676,-0.493231,0.481524,0.037387,-0.158747,-0.171048,0.324128,0.703427,-0.147939,0.015870,0.321333,-0.049860,-0.278013,-0.676698,0.037498,-0.088146,-0.287775,-0.373146,-0.377949,-0.010997,-0.048474,-0.345553,0.315608,-0.166402,-0.145457,0.234430,0.240238,0.227066,-0.024113,0.439421,-0.119349,-0.081091,0.098099,-0.362117,-0.105958,0.242392,-0.290598,0.137079,-0.059377,-0.017105,0.190595,0.286118,0.361094,-0.326749,0.177655,-0.452886,-0.040886,-0.216172,0.127165,0.007151,0.377575,-0.074618,-0.024102,-0.297641,-0.093480,0.015238,0.174700,0.072950,-0.378573,0.214006,-0.246341,-0.171435,-0.703498,0.151447,-0.198108,0.222669,0.035438,0.030562,0.301794,0.125932,0.141657,0.063522,0.023264,-0.067435,-0.458383,-0.048353,0.514926,-0.108702,-0.300422,-0.043993,0.198908,-0.294546,0.019810,-0.387776,0.001024,-0.188694,0.599606,0.000656,0.014211,0.346150,-0.665837,-0.220245,-0.576408,-0.207777,-0.413428,-0.161944,-0.265258,-0.529333,0.225363,-0.082539,-0.083947,0.144001,-0.079730,-0.083390,0.523665,-0.815191,-0.109635,0.484327,0.254152,0.210645,0.346612,-0.025116,0.105356,0.003241,-0.108079,-0.133911,0.365250,0.366956,0.368127,0.260971,-0.051623,-0.207720,0.108976,0.526283', '1309069', '1299556', '30345227', '1292829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291839', '银翼杀手', '科幻', '2019年11月，刀锋跑者霍顿（Morgan Paull 饰）在泰瑞尔公司对新员工进行沃伊特-坎普夫测试时，被技师里昂·科瓦尔斯基（Brion James 饰）枪击。警监布莱恩特（M. Emmet Walsh 饰）不得不命老牌刀锋跑者戴克（Harrison Ford 饰）出马，猎杀复制人里昂、罗伊·巴蒂（Rutger Hauer 饰）、佐拉（Joanna Cassidy 饰）、普里斯（Daryl Hannah 饰）。戴克来到泰瑞尔公司调查，在艾登·泰瑞尔博士（Joe Turkel 饰）的请求下，对员工瑞秋（Sean Young 饰）进行了测试。百余问题之后，戴克判断瑞秋为复制人。而瑞秋本人对此真相竟一无所知……©豆瓣', '哈里森·福特', '雷德利·斯科特', 8.5, 233812, 'tt0083658', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p868550285.jpg', 0.4, 1.7, 13.5, 39, 45.4, '0.053169,-0.168381,-0.257331,0.114025,0.229485,-0.204836,-0.127026,0.300384,-0.697887,-0.360755,0.300515,0.343457,-0.402821,-0.295257,0.414855,-0.031466,-0.831223,-0.452071,0.378615,-0.469757,-0.369956,-0.874751,-0.099445,-0.388046,0.121416,-0.743901,0.163995,-0.283718,0.158537,0.386763,0.012301,0.861064,0.341551,0.052389,0.552447,0.144959,0.627322,-0.401310,-0.417468,0.140966,-0.094175,0.176735,-0.223130,0.010160,0.321871,0.396277,0.456173,-0.388954,0.429569,-0.141029,-0.010635,-0.118935,0.361648,-0.055563,0.334832,-0.045964,-0.132135,0.537916,-0.268001,0.037680,0.078942,-0.275145,-0.317285,0.096970,-0.091227,0.373189,-0.476627,0.205910,-0.821023,0.408130,0.014511,-0.021375,-0.328565,0.215356,0.293718,0.073312,0.209434,0.020312,-0.045680,0.162698,0.018835,0.143875,-0.329584,-0.092540,-0.049287,-0.336777,-0.277978,0.065278,-0.088042,-0.053867,0.227993,0.111334,0.453536,0.307011,-0.503292,-0.356951,-0.715976,-0.201286,-0.085657,-0.103037,-0.138154,-0.929849,0.067248,0.131543,-0.312344,-0.151303,0.116922,0.075567,0.233535,-0.759434,0.111619,0.230084,0.500182,0.037969,0.480911,-0.560275,0.232595,-0.667700,-0.363020,0.348701,0.297034,0.044838,0.096786,0.328578,0.423403,-0.509721,-0.054698,0.108288', '2369549', '1293572', '1293544', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291840', '走出非洲', '剧情', '凯伦（梅丽尔·斯特里普 Meryl Streep 饰）是一个爱慕虚荣的富家女，为了得到一个男爵夫人的称号她离开故土丹麦远嫁东非肯尼亚，然而男爵夫人的称号并没有给凯伦带来美满的婚姻生活。幸运的是在那片广袤的土地上，凯伦可以经常外出打猎、探险，她渐渐的爱上了这片神奇的土地。 在一次打猎遇险时，凯伦邂逅了年青的英国贵族邓尼斯（罗伯特·雷德福 Robert Redford 饰）。在遭遇婚姻的破裂和丈夫出走之后，凯伦独立承担起经营庄园的任务，在劳动的过程中，凯伦渐渐的与种植园里的仆人们产生了深厚友谊，而她与邓尼斯的关系似乎也有了进展。然尔命运之神并没有从此让凯伦一帆风顺，一次大火让她不得不出卖庄园从而缓解经济的拮据，后来邓尼斯驾机意外身亡又一次给了她沉重的打击。在经历了生命的磨炼之后，凯伦最终告别了那片她洒下青春和热情的土地……该片在1986年的第58届奥斯卡上荣获了包括最佳影片、最佳导演、最佳改编剧本在内7项大奖。', '梅丽尔·斯特里普', '西德尼·波拉克', 8.6, 84893, 'tt0089755', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910907281.jpg', 0.2, 0.9, 11.7, 42, 45.2, '0.107731,0.036095,-0.896481,0.738639,-0.044926,-0.455036,0.785226,0.064239,-0.523906,0.012095,0.177138,1.076459,-0.027860,0.168031,0.313325,0.030693,-0.299200,-0.671465,-0.065622,-0.240986,-0.314507,-0.583021,-0.450889,-0.129103,-0.313166,-0.484055,0.572344,0.156233,-0.239313,0.702914,0.241412,0.021883,0.178667,0.422780,-0.202341,0.250574,0.348609,0.182296,-0.407966,0.198860,0.053076,-0.312752,-0.212948,0.366277,0.181290,0.454731,0.670879,-0.288158,-0.054339,-0.091077,0.432674,-0.208184,0.164201,0.001314,0.101885,-0.112082,0.125881,0.351364,-0.309109,0.025881,0.183878,-0.302360,-0.789807,0.000750,0.005930,0.073450,-0.727780,0.776015,0.050380,-0.073732,-0.000774,-0.108535,0.168859,0.523170,0.232566,0.288948,-0.204273,0.044189,-0.287818,0.458294,0.737519,-0.074423,-0.385404,0.476635,-0.584356,-0.462789,-0.047968,-0.221226,-0.645786,-0.063769,0.646638,0.112311,-0.139712,0.451606,-0.689879,-0.009257,-0.381410,-0.385505,0.051671,-0.134620,-0.053569,-0.615788,-0.220594,-0.516219,-0.356052,-0.114280,-0.004839,-0.292546,0.629060,-0.820253,0.392243,0.521927,0.262221,-0.519037,0.651084,0.160728,0.335890,0.006933,0.060862,0.387587,-0.061552,0.381994,0.259014,0.283220,-0.112448,-0.074607,-0.412500,