INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291841', '教父', '剧情', '40年代的美国，“教父”维托·柯里昂（马龙·白兰度 饰）是黑手党柯里昂家族的首领，带领家族从事非法的勾当，但同时他也是许多弱小平民的保护神，深得人们爱戴。因为拒绝了毒枭索洛索的毒品交易要求，柯里昂家族和纽约其他几个黑手党家族的矛盾激化。圣诞前夕，索洛索劫持了“教父”的参谋汤姆，并派人暗杀“教父”；因为内奸的出卖，“教父”的大儿子逊尼被仇家杀害；小儿子麦克（阿尔·帕西诺 饰）也被卷了进来，失去爱妻。黑手党家族之间的矛盾越来越白热化。年老的“教父”面对丧子之痛怎样统领全局？黑手党之间的仇杀如何落幕？谁是家族的内奸？谁又能够成为新一代的“教父”？血雨腥风和温情脉脉，在这部里程碑式的黑帮史诗巨片里真实上演。©豆瓣', '马龙·白兰度', '弗朗西斯·福特·科波拉', 9.3, 896062, 'tt0068646', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p616779645.jpg', 0.2, 0.4, 4.5, 23, 72, '0.409712,0.176967,-0.443202,0.491222,0.050073,-0.128360,0.521355,0.116110,-0.716529,-0.349123,0.151236,0.886342,0.101495,0.239310,0.294908,-0.151755,-0.243382,-0.742750,-0.286084,-0.175155,-0.231015,-0.526040,-0.233684,-0.359284,-0.101735,-0.045726,0.690984,0.241294,-0.331697,0.183431,0.669375,0.663073,-0.284911,0.226020,-0.004689,-0.128840,0.619553,-0.318983,-0.546254,0.042932,-0.101258,-0.041502,-0.076912,0.357873,-0.016536,0.348946,0.148114,-0.329298,0.225048,-0.476770,0.276903,-0.506980,-0.109189,-0.019185,0.901923,-0.221644,0.015960,0.568502,0.246183,-0.331093,-0.225833,0.149312,-1.030943,0.002083,0.399314,0.290973,-0.642335,0.366271,-0.053443,0.019617,0.020044,0.301225,0.336287,0.480568,0.342213,0.153430,0.080448,0.180175,-0.632038,0.206605,0.827307,-0.108119,-0.194840,-0.270630,-0.078791,-0.415773,-0.107107,-0.807127,-0.585717,0.061588,0.465654,-0.388531,0.111732,0.790169,-0.565094,-0.162138,-0.413110,-0.077504,0.140310,-0.483750,0.056950,-0.675800,-0.341451,-0.454112,-0.011537,-0.082094,0.215849,-0.227180,0.665199,-0.650375,-0.033415,0.380205,0.222105,-0.518036,0.331266,0.078950,0.166746,-0.365767,-0.411279,0.326522,0.645345,-0.107456,0.059058,-0.005695,0.131591,-0.252572,0.328072,0.189742', '1793491', '1482099', '26678784', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291842', '当哈利遇到莎莉', '剧情', '莎莉（梅格·瑞恩 饰）开车载哈利（比利·克里斯托 饰）前往纽约，两人就此相识。途中二人言语相左，不欢而散，并留下经典的问题：“排除‘性’的介入，男人和女人可以成为真正的朋友么？”五年后。两人在机场不期而遇。此时，莎莉沉浸于新恋情的甜蜜，而哈利即将步入正式的婚姻生活。哈利告诉莎莉：“在两人各有所爱的时候，男人和女人或许可以成为朋友，但很快他们会质疑为什么要与只能做朋友的人交往。”莎莉佛袖而去。十年后。失恋中的莎莉再次偶遇刚刚离婚的哈利。哈利对莎莉说：“我们要成为朋友了么？你或许是我不想带上床的第一位迷人女性。”临睡前的通话，共度圣诞，为彼此的感情出谋划策，哈利与莎莉有着不可言喻的默契。然而，这真的是一段美丽友谊的开始么？又或者这悄然来临的是错认了的感情呢……©豆瓣', '比利·克里斯托', '罗伯·莱纳', 8.3, 138495, 'tt0098635', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2172960925.jpg', 0.2, 0.9, 16.4, 48.2, 34.3, '0.339861,0.029314,-0.572897,0.419331,-0.047813,-0.388920,0.758624,0.037316,-0.387479,-0.060163,-0.091074,0.821479,-0.247197,0.301621,0.437609,0.037923,-0.533279,-0.848939,0.286002,-0.414525,-0.265382,-0.577931,0.102237,-0.209517,0.007615,-0.166722,0.646441,0.011483,-0.026362,0.520114,0.302649,0.132606,-0.138386,0.572614,-0.076578,-0.129160,0.033981,0.291613,-0.804499,0.173746,0.197161,0.023992,-0.112720,0.020459,-0.053145,0.240606,0.404131,-0.246964,-0.112832,0.126691,0.181664,-0.157725,0.094203,0.138781,0.080083,-0.074892,0.495690,0.379741,-0.023247,-0.197063,0.044245,-0.058201,-0.556687,0.309277,-0.234667,0.014060,-0.226249,0.526378,0.203005,-0.089916,0.528174,-0.153411,0.164366,0.534341,0.553601,0.156520,-0.096873,-0.043723,-0.375693,0.019777,0.775568,0.125646,-0.108273,0.646354,-0.140719,-0.366675,-0.084062,0.039005,-0.442094,0.099411,0.144282,0.206105,-0.175767,0.300747,-0.605231,-0.186341,-0.109096,0.182383,0.244890,-0.643255,0.175076,-0.548408,-0.151854,-0.425019,-0.335155,-0.030459,0.109265,-0.350837,0.583325,-1.089646,0.246963,0.490282,0.436997,-0.654275,0.785494,0.385000,0.110112,-0.476458,-0.032713,0.291790,-0.177814,0.026185,0.195693,0.342357,0.302323,0.312013,-0.420840,0.428665', '30345227', '1308755', '1299556', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291843', '黑客帝国', '动作', '不久的将来，网络黑客尼奥（基奴李维斯 饰）对这个看似正常的现实世界产生了怀疑。他结识了黑客崔妮蒂（凯莉·安·摩丝 饰），并见到了黑客组织的首领墨菲斯（劳伦斯·菲什伯恩 饰）。墨菲斯告诉他，现实世界其实是由一个名叫“母体”的计算机人工智能系统控制，人们就像他们饲养的动物，没有自由和思想，而尼奥就是能够拯救人类的救世主。可是，救赎之路从来都不会一帆风顺，到底哪里才是真实的世界？如何才能打败那些超人一样的特勤？尼奥是不是人类的希望？这是黑客的帝国，程序和代码欢迎大家的到来。.©豆瓣', '基努·里维斯', '莉莉·沃卓斯基', 9.1, 785464, 'tt0133093', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p451926968.jpg', 0.1, 0.5, 6.6, 30.4, 62.4, '0.201315,0.251792,-0.329808,0.551035,-0.319512,-0.196395,0.315489,-0.119612,-0.403259,-0.235416,-0.012915,0.706896,-0.005897,-0.053443,0.237200,0.221928,-0.429948,-0.677815,-0.017681,-0.342462,-0.368921,-0.502804,-0.448207,-0.437630,0.182594,-0.459837,0.728362,0.116687,-0.247460,0.024890,0.149301,0.434383,-0.098132,0.413638,-0.048370,-0.239133,0.266182,0.079679,-0.534255,-0.169282,-0.132781,0.175474,0.012862,0.489989,-0.187023,0.009445,0.192076,-0.693533,-0.174311,-0.310380,0.502852,-0.410957,0.003067,-0.321262,0.375694,-0.462906,0.124316,0.047411,0.526717,0.040525,-0.088173,-0.112311,-1.168692,-0.281333,0.054213,0.461522,-0.215867,0.006455,-0.235264,-0.031361,-0.079672,-0.008902,0.289946,0.372587,0.640529,0.342147,-0.032542,-0.138215,-0.517258,0.080131,0.385247,0.128380,-0.763877,0.384983,-0.433327,-0.639764,-0.348109,-0.097240,-0.594157,0.098512,0.071862,0.047066,-0.474752,0.225374,-0.431208,0.032019,-0.310528,-0.358330,0.066478,-0.531566,0.140723,-0.579850,-0.005200,-0.643315,-0.221211,-0.145420,0.196404,-0.345683,0.862293,-1.147427,0.277287,0.791698,0.235079,-0.693431,0.527803,0.052665,-0.156543,-0.468529,-0.000313,0.212849,0.051633,0.236434,-0.198389,0.377498,0.350096,-0.160028,-0.219533,0.619500', '24284209', '1793491', '27009869', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291844', '终结者2：审判日', '动作', '上一部中，超级电脑“天网”阻止人类抵抗领袖约翰·康纳诞生的行动失败，时隔13年后，在“审判日”到来之前，“天网”派出了更加先进的生化机器人T-1000（罗伯特·帕特里克 饰）从公元2029年回到洛杉矶追杀已经长大的约翰，与此同时，约翰也派出了机器人T-800（阿诺· 施瓦辛格 饰）回去保护年幼的自己。此时，萨拉·康纳（琳达·汉密尔顿 饰）因为怪异的言行而住进了精神疗养院，约翰则和养父母住在一起，行为叛逆。T-800找到他们，在逃避T-1000追杀过程中，获得了二人的信任。为了改变未来的历史，挽救人类的命运，萨拉、约翰和T-800 Model 101找到了“天网”之父，迈尔斯·戴森（乔·莫顿 饰），说服他销毁一切有关“天网”的资料，此时，警察和T-1000同时赶来，他们陷入了多方争斗中。©豆瓣', '阿诺·施瓦辛格', '詹姆斯·卡梅隆', 8.8, 319295, 'tt0103064', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910909085.jpg', 0.1, 0.5, 10.1, 39.4, 49.9, '0.062105,0.093061,-0.718671,0.386628,-0.057030,-0.377099,0.668123,-0.072435,-0.596383,-0.469766,0.079534,0.487513,0.041995,0.220705,0.393104,-0.156251,-0.740056,-0.579866,-0.064807,-0.163431,-0.426324,-0.492195,-0.383997,-0.406448,0.128263,-0.475345,0.763551,0.002748,-0.117399,0.549681,-0.090820,0.397210,-0.184962,0.350369,0.273970,0.095479,0.142710,-0.234126,-0.414013,0.363017,0.006346,0.013957,-0.101944,0.191769,-0.046669,0.375414,0.582098,-0.543315,0.068932,-0.366991,0.165463,-0.438531,-0.185528,0.126834,0.304014,0.137737,-0.152941,0.235401,-0.252334,0.226418,-0.195648,0.054642,-0.783003,-0.008988,-0.150940,0.102017,-0.625981,0.154843,-0.297006,0.299811,-0.001117,-0.625391,0.174970,0.557039,0.297543,0.376610,-0.150124,0.079799,-0.456446,-0.108899,0.676586,-0.251643,-0.198491,-0.004733,-0.062150,-0.403037,-0.170384,-0.267286,-0.355999,-0.082263,0.422746,0.133064,0.072796,0.463008,-0.587843,-0.327073,-0.336595,-0.196244,0.014620,-0.260021,0.108488,-0.887587,-0.254055,-0.216634,-0.334158,-0.170618,-0.168608,-0.353602,0.633402,-0.720127,0.352631,0.456749,0.369879,-0.483331,0.546751,-0.035748,0.317464,-0.265301,0.119122,0.467014,0.325390,0.367428,0.098611,-0.012192,0.143264,-0.143330,-0.349529,0.292621', '2369613', '1293656', '20274039', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291846', '大门', '剧情', '本片忠实地记述了1960年代美国迷幻摇滚代表乐队——大门乐队的灵魂主唱吉姆·莫里森（方·基默 Val Kilmer饰）从成名到自我毁灭的一生。在电影学校，莫里森结识了喜欢弹钢琴的键盘手雷·曼札克，两人一拍即合，决定组建一支令世界震惊的摇滚乐队：The Doors。很快，莫里森在这里找到了其他两位乐队成员：鼓手约翰·丹斯莫和吉他手罗比·克雷格。不久，大门乐队因《Light My Fire》一跃成名，万千乐迷为之疯狂。在拥有金钱名利诸多光环后的莫里森，却始终无法被任何人真正了解，有人认为他是诗人、艺术家，也有人把他当做疯子、瘾君子。27岁的莫里森最终选择了死亡来结束这段无以伦比的个人传奇。©豆瓣', '方·基默', '奥利佛·斯通', 8, 8664, 'tt0101761', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910909382.jpg', 1, 2.5, 21.8, 44.8, 30, '0.096822,0.140361,-0.777400,0.438588,-0.285890,-0.149138,0.645719,0.093122,-0.569255,-0.330864,0.050070,0.856187,-0.319905,0.227684,0.320084,-0.413600,0.043506,-0.726014,-0.015894,-0.318514,-0.097894,-0.300677,-0.045150,-0.220835,-0.234657,-0.278746,0.785101,0.133248,-0.126656,0.422003,0.295681,0.354619,0.083077,0.204149,-0.072678,0.095068,0.374324,-0.216781,-0.367491,0.147005,-0.178969,-0.192493,-0.049864,0.141726,-0.274390,-0.105283,0.610250,-0.284810,0.298971,0.012115,0.349972,-0.184035,-0.030143,-0.110856,0.358124,0.087255,0.028703,0.161375,0.120435,0.142530,-0.294630,-0.097177,-0.844795,-0.070441,0.082415,0.010021,-0.654982,0.408418,-0.250065,-0.145275,0.014771,-0.097394,0.149110,0.017883,0.530692,0.263076,-0.112265,0.094630,-0.450198,0.362783,0.583616,0.053730,-0.499923,0.364478,-0.142387,-0.611239,-0.404383,-0.131962,-0.444946,-0.000723,0.584653,-0.001478,0.123568,-0.003460,-0.486918,-0.149495,0.073570,-0.172115,0.209509,-0.490304,-0.077086,-0.841464,-0.074257,-0.054705,0.103582,-0.122823,0.039387,-0.116180,1.001708,-0.787375,0.254410,0.598339,-0.102331,-0.313260,0.621996,-0.143280,0.191421,-0.159292,0.125905,0.401440,0.315818,0.361185,0.264674,0.292685,0.024181,0.064117,-0.314366,0.356667', '27602116', '3811356', '25928048', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291847', '十七岁的单车', '剧情', '十七岁的农村少年阿贵（崔林）在北京找到一份送快递的工作，因为得到许诺，当他赚到六百块时可以拥有公司暂借他用的银色变速越野车，他每日工作都很勤恳，可是就在梦想即将成真时，单车丢了，阿贵陷入绝望。小坚（李滨）是和阿贵同岁的北京少年，但因家庭的贫困，他在维系骄傲时又常自卑。 父亲屡次三番将许下他一辆单车的承诺食言后，小坚为在同伴面前挣面子和泡马子（高园园），从家里偷来钱买了一辆二手车，不想此车正是阿贵所丢。阿贵发现他赖以生存的单车被小坚“盗”去后，开始不计代价拼命讨回，两个少年为守护自己的简单梦想发生争斗。©豆瓣', '崔林', '王小帅', 7.8, 108848, 'tt0276501', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1457108531.jpg', 0.4, 2, 24.2, 52.9, 20.5, '0.053171,0.237720,-0.539983,0.308553,-0.534155,-0.560286,0.560835,0.201859,-0.258513,-0.130244,0.313613,0.724944,0.363185,0.246947,0.299972,0.068991,-0.015613,-0.405980,0.204973,-0.130413,-0.174646,-0.330295,0.056824,-0.169410,-0.311992,-0.164256,0.507755,0.052213,0.024691,0.375359,0.304348,0.042704,-0.005842,0.428488,-0.558316,0.083516,-0.252803,0.051699,-0.116017,0.099443,-0.098577,-0.278224,0.039245,0.079766,0.173830,0.142802,0.704292,0.144612,-0.332089,-0.070308,0.327818,0.040996,0.027722,-0.094856,-0.002922,0.303464,0.018952,0.028559,-0.349456,-0.036301,0.284100,-0.040775,-0.639908,-0.115863,-0.171922,-0.108424,-1.010000,0.504873,-0.117631,-0.038414,0.478802,-0.473868,0.080930,0.323930,0.179146,0.305157,-0.208570,0.121280,-0.580870,0.468885,0.757377,-0.410259,0.238214,0.603222,-0.196339,-0.202056,0.301595,-0.212180,-0.607658,0.027740,0.294305,-0.007661,-0.205700,-0.054789,-0.446857,0.005702,-0.130527,-0.319442,0.135916,-0.371299,-0.228307,-0.083985,-0.022507,-0.407597,-0.196524,0.171584,0.109331,-0.311011,0.597900,-0.636328,0.343087,0.634822,0.363147,-0.474502,0.748197,-0.194392,0.155146,-0.159661,0.142896,-0.070611,0.207115,0.516898,0.096034,-0.107086,-0.100091,0.072019,-0.104989,0.693079', '1299965', '1297606', '1306505', '26769480');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291850', '站台', '剧情', '崔明亮（王宏伟）、尹瑞娟（赵涛）、张军（梁景东）、钟萍（杨天乙）是山西汾阳县文工团的演员，改革开放初期，他们过的虽是普普通通的日子，却拥有相对丰盈的精神世界。改革开放的不断深入令他们见识到了各种新鲜事物，也使他们对自身有了更多的认识，走上了不同的人生道路。然而当时间来到 1980年末时，他们发现虽然各自早已面目全非，却仍然一无所有。相比如广州那样的沿海城市，如汾阳这样的中国内陆小县城改革开放的步伐总是迟缓凝重的，可是崔明亮他们并没认识到这点。而他们为挣钱不断将自己的底线降低，则造成了他们的精神世界彻底断层。©豆瓣', '王宏伟', '贾樟柯', 8.4, 62852, 'tt0258885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910910474.jpg', 0.3, 1.2, 14.2, 47.8, 36.5, '0.328075,0.207361,-0.810737,0.647712,-0.250209,-0.116420,0.751564,0.261480,-0.810251,-0.202276,-0.150008,0.558372,-0.236144,0.157399,-0.077200,-0.424244,-0.114438,-0.497728,0.029604,-0.264051,-0.380468,-0.433646,-0.372820,-0.070345,-0.409216,-0.093811,0.543530,0.444753,-0.182577,0.479908,-0.009441,-0.206851,0.236715,0.814648,-0.313831,0.176181,-0.186293,0.044914,-0.116805,-0.124739,0.116950,-0.305620,-0.326840,0.280933,-0.075201,0.495458,0.561146,0.088651,-0.406425,-0.063015,0.313029,-0.143197,-0.115114,-0.030795,0.478192,0.031835,-0.091050,0.006147,-0.005509,0.178041,-0.151986,-0.166960,-0.601865,0.338948,0.229416,0.107545,-0.484071,0.143029,0.177976,-0.215139,-0.231117,-0.317014,0.114190,0.469154,0.198962,0.373331,-0.281786,0.033539,-0.629630,0.245262,0.745727,0.179960,-0.682605,0.475287,-0.492685,-0.617028,-0.351849,-0.260303,-0.185402,-0.002186,0.189415,0.179763,-0.134824,0.255366,-0.588556,0.193390,0.058054,-0.382859,-0.073712,-0.261412,0.087314,-0.552262,-0.127479,-1.014581,-0.310696,0.217083,-0.013837,-0.270448,0.854523,-0.798861,-0.021751,0.350031,0.504778,-0.615811,0.544354,-0.185159,0.135874,-0.119104,-0.128183,0.387946,0.026987,0.469771,0.140541,0.429512,-0.274926,-0.081246,-0.297987,0.893486', '25828521', '26354526', '24756472', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291851', '小武', '剧情', '小武（王宏伟）是山西汾阳一个屡教不改的“惯偷”，即使公安部门在搞严打活动，他仍要想方设法下手。但是抛开所谓的“小偷”身份，他是个十分恋旧十分传统的人，亲情、友情在他心中都有沉甸甸的分量。但昔日亲朋好友早将他看作瘟神，惟恐躲避不及。无形之中，小武只能去做边缘人，换回某些满足和安慰。某天在歌厅唱歌时，小武结识了陪唱小姐胡梅梅（左百韬），相似的心境让两人建立了某种暧昧的情感。然而胡梅梅明白，小武并非她的彼岸，她需要找到一个更有力的“臂膀”改变自己的命运。对此小武虽也明白，却在事情发生时仍无法抑制失落。面对自己的未来，处境更加尴尬窘迫的小武愈发茫然无措。©豆瓣', '王宏伟', '贾樟柯', 8.5, 124229, 'tt0144020', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2274317161.jpg', 0.2, 0.9, 11.7, 46.4, 40.8, '0.444922,0.024405,-0.703841,0.400837,-0.026215,0.046551,0.691674,0.109960,-0.563497,-0.286310,0.204892,0.553031,-0.021124,0.163507,-0.015057,-0.064205,-0.099239,-0.387731,0.350156,-0.017517,0.075195,-0.418571,-0.328105,-0.208585,-0.307507,-0.072583,0.480741,0.171225,-0.308639,0.331116,0.190381,0.133963,0.046261,0.755805,-0.240752,-0.180505,-0.234456,0.049165,-0.043999,-0.204554,0.322921,-0.319719,-0.257047,0.424677,-0.162475,0.526522,0.346780,-0.108618,-0.395152,0.326291,0.226735,-0.377108,-0.055669,0.177085,-0.049750,-0.036543,-0.130480,0.071921,-0.275883,0.113283,0.252852,0.198412,-0.748032,0.188097,0.307690,0.227728,-0.569674,0.345767,0.002071,0.068666,0.093193,-0.419572,0.207263,0.266327,0.208713,0.291258,-0.298708,-0.034094,-0.579103,-0.014888,0.824397,0.159957,-0.177804,0.378308,-0.557993,-0.326856,-0.056363,-0.242726,-0.465980,-0.115833,-0.013208,0.189655,-0.271249,0.212883,-0.226415,-0.065419,0.023102,0.042142,-0.328168,-0.785300,0.171182,-0.125436,-0.424922,-0.544234,-0.300969,-0.132648,0.225505,-0.460536,0.669934,-0.821780,-0.028334,0.544414,0.170041,-0.541217,0.498816,0.416849,-0.037167,-0.293001,-0.213914,0.238705,-0.148132,-0.063265,-0.016997,0.277076,-0.095839,-0.005424,-0.231917,0.483245', '1303112', '1296370', '1308206', '6874741');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291852', '弗里达', '剧情', '弗里达（salma hayek 饰）是墨西哥著名的女画家，18岁之前她是一个快乐活泼的少女，跟其他人一样，享受着爱情的甜蜜。然而18岁的车祸让她遭遇重创，死里逃生的她从此跟病痛伴随一生。原来的小情人也离她而去。躺在病床18个月的她整日与画为伴，她的画充满了不可思议的活力与激情。那时候她也真正开始考虑卖画养活自己，她前去请求画家里维拉指导自己的画，对方激赏她的天分。他们也从师生转变成一生的伴侣，他们结婚了。婚后他们经历了墨西哥最动荡的革命时期，他们狂热地追随着共产主义的脚步，甚至当托洛斯基被斯大林逐出苏联后，他们不畏风险地予以热情接待。弗里达与托洛斯基朦胧的爱恋，以及她的女同性恋情结让她的感情史一样绚烂。1954年，弗里达离开了这个充满了病痛的世界，但愿离去是幸。©豆瓣', '萨尔玛·海耶克', '朱丽·泰莫', 8.7, 66437, 'tt0120679', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p729625029.jpg', 0.1, 0.6, 9.5, 41.3, 48.4, '0.122207,-0.157961,-0.829485,0.604136,-0.338855,-0.297500,0.901430,0.193522,-0.410454,0.000231,0.326138,0.935927,-0.169411,0.417061,0.169613,0.098277,-0.207611,-0.861456,0.097816,-0.183876,-0.057135,-0.283404,-0.186331,-0.197723,-0.122572,-0.276729,0.537399,0.072058,0.115742,0.547312,0.090639,0.150993,0.303565,0.611338,-0.169141,0.063261,-0.104274,0.010570,-0.092269,-0.086366,0.136869,-0.155894,-0.126647,0.018964,-0.213026,0.140192,0.737129,-0.290894,0.072685,-0.105911,0.295906,-0.321205,-0.052092,0.402883,-0.068280,-0.147511,-0.039289,0.308769,-0.173063,-0.331097,-0.075470,0.015138,-0.703702,-0.013928,-0.143002,0.209721,-0.675362,0.622700,-0.066511,0.011054,0.292068,-0.052239,0.060047,0.392747,-0.012406,0.511165,-0.254046,-0.004504,-0.586862,0.294640,0.581358,0.055950,-0.299775,0.435681,-0.568702,-0.397158,-0.190923,-0.222795,-0.564557,-0.107215,0.200051,-0.100453,-0.296394,0.367317,-0.660876,0.006645,-0.194538,-0.039615,0.042087,-0.384583,-0.092158,-0.584287,-0.141267,-0.813578,-0.621819,-0.208667,0.088510,-0.363366,0.855796,-0.500286,0.195325,0.611689,0.276470,-0.388650,0.926002,0.159712,-0.129568,-0.084944,-0.124868,0.836490,-0.344692,0.333724,0.144383,0.380251,0.121185,0.442175,-0.255819,0.708132', '30162520', '3154392', '3055049', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291853', '英国病人', '剧情', '一架英国飞机在飞越撒哈拉沙漠时被德军击落，机师由于受伤，想不起自己是谁，因此被叫做“英国病人”。汉娜是战地医院的一名护士，她决定独身留下来照顾那个英国病人。他们停留的地方是意大利的一个废弃的修道院，远离战争的喧嚣，显得宁静而闲逸，“英国病人”静静的躺在房间的木床上，窗头 的一本旧书渐渐唤起了他的思绪……一段爱情，在战火中燃烧，逾越了道德，改变了战局。考古学家艾马殊伯爵（拉尔夫•费因斯 Ralph Fiennes 饰）跟随探险家来到撒哈拉沙漠考察，结识了绘制地图的飞机师杰佛和他妻子凯瑟琳（克里斯汀•斯科特•托马斯 Kristin Scott Thomas 饰）。凯瑟琳的才气和美丽让艾马殊深深着迷，两人在沙漠一个幽深洞穴参观壁画时，更加发现彼此志趣相投。 道德最终战胜了激情。凯瑟琳和艾马殊分手后，杰弗发现了妻子的外遇。伤心的杰弗开着飞机企图与妻子和艾马殊同归于尽，艾马殊幸运躲过一劫，却造成凯瑟琳身受重伤、自己命丧黄泉。艾马殊赶到深爱的人身边，把她安置到山洞里，承诺一定会走出沙漠，找到援助。但是，事情却不像想象中容易。他为了救人，担当了卖国罪名，惹来了杀身之祸，最终他没有违背诺言，可是，凯瑟琳已在寒冷中永远地离开了他……艾马殊将凯瑟琳的遗体放上飞机，在飞越撒哈拉沙漠时被德军击落，于是发生了影片开头的一幕。在照顾“英国病人”的日子里，汉娜结识了印度籍的拆弹手基普，两人互生情愫。即使战争已然结束，但拆弹手基普必然仍要无数次面对死亡。最终，应英国病人的要求，汉娜给他注射了大剂量的吗啡......', '拉尔夫·费因斯', '安东尼·明格拉', 8.5, 261759, 'tt0116209', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2408623752.jpg', 0.3, 1.1, 13.5, 43.5, 41.6, '0.262122,0.159892,-0.820267,0.406784,0.000158,-0.224253,0.839385,0.045585,-0.438451,-0.195980,0.372385,0.793257,0.014772,0.148410,0.171274,0.109467,-0.386166,-0.759846,-0.014869,-0.004930,-0.514116,-0.437907,-0.217148,-0.221548,0.003272,-0.349734,0.506769,0.246997,-0.158204,0.376956,-0.070224,0.200486,-0.037839,0.562962,-0.150609,-0.088194,0.133184,-0.045493,-0.217513,0.325387,0.101693,-0.423176,-0.181583,0.107414,0.009291,0.350886,0.646376,-0.132438,-0.194004,-0.125805,0.137959,-0.446017,0.105726,0.207817,0.150993,-0.068442,0.023657,0.145529,-0.154224,-0.106367,0.167636,0.070821,-0.230594,0.097957,-0.149190,0.195018,-0.602788,0.475549,-0.221538,0.048730,0.003713,-0.151048,0.314434,0.112802,0.081661,0.208409,-0.250660,-0.010245,-0.526706,0.005363,0.577820,-0.122481,-0.191346,0.268477,-0.237124,-0.426013,0.021517,-0.163148,-0.398276,-0.046140,0.437799,0.038134,-0.356374,0.173986,-0.456771,-0.101388,-0.463552,-0.235572,-0.328167,-0.335743,-0.019658,-0.544142,-0.098326,-0.225664,-0.392327,0.046832,-0.093898,-0.122974,0.564712,-0.554101,0.278518,0.529374,0.365705,-0.307567,0.641321,0.139719,0.160508,-0.030706,0.250395,0.553486,-0.108237,0.313742,0.242076,0.219986,-0.162279,0.227805,-0.477324,0.353895', '1292217', '25723780', '3111650', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291856', '戏梦巴黎', '剧情', '1968年法国学运前夕，孪生姐弟伊莎贝拉（伊娃•格林）和雷奥（路易斯•加瑞尔）因为电影，与来自美国的留学生马休（迈克尔•皮特）成为好朋友。姐弟两人将马休带到家中做客时，马休得到两人同是大学教授的父母的喜爱，住进他们家中，慢慢地，他喜欢上伊莎贝拉。学运开始后大学停课，三个年轻人因无所事事在房间里玩起有关电影导演和台词的游戏，游戏进行当中，伊莎贝拉知晓马休对她有意思，联合雷奥要求马休与她做爱，自此，由于父母出门度假，三人开始了如伊甸园般的日子，马休也慢慢发现伊莎贝拉和雷奥有不伦恋情，三人关系开始发生微妙的变化，而外面正如火如荼进行着的学运，似乎与他们无关。©豆瓣', '迈克尔·皮特', '贝纳尔多·贝托鲁奇', 8.1, 194804, 'tt0309987', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1374017596.jpg', 0.3, 1.7, 19.7, 47.2, 31.1, '0.679075,-0.065744,-0.815617,0.391836,0.393903,-0.230067,0.734709,0.101860,-0.779423,-0.259805,-0.028156,0.674648,-0.350581,0.625306,0.268073,0.083049,-0.801217,-0.922863,-0.129935,-0.193399,0.055209,-0.728664,0.099995,-0.102594,-0.152963,-0.369311,0.258054,-0.338674,0.043418,0.843199,0.150969,0.254175,-0.255342,0.316748,0.184563,0.072600,0.069205,0.172529,-0.757538,0.251847,0.246295,0.196413,-0.291124,-0.162502,0.347545,0.321432,0.598147,-0.141793,-0.078923,-0.256702,0.217279,-0.084327,-0.185363,0.179909,0.447298,0.263301,0.450367,0.269450,0.067262,0.012145,-0.176051,-0.262346,-0.162841,0.298737,0.045703,0.155296,-0.287911,0.506269,-0.083658,0.023824,0.346042,-0.371983,0.116334,0.410926,0.376060,0.376303,-0.132188,-0.016569,-0.279355,0.135626,0.916426,-0.012401,-0.064438,0.231996,-0.014466,-0.133842,-0.058412,-0.002797,-0.323425,-0.006107,0.172528,0.121605,-0.022241,0.396687,-0.634146,0.033313,-0.047714,-0.158961,0.308517,-0.374818,0.122926,-0.980178,-0.164260,-0.616021,-0.335350,-0.161547,-0.051432,-0.363115,0.547975,-0.960371,0.278026,0.317995,0.476079,-0.458479,0.619475,-0.044522,0.322017,-0.280997,-0.062340,0.067570,-0.082370,-0.024040,0.360910,0.222287,-0.153009,0.081665,-0.326585,0.293017', '1296339', '1292050', '1302987', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291858', '鬼子来了', '剧情', '第二次世界大战期间，中国河北挂甲台村的农民马大三（姜文饰）在日本人的统治下过着平静的生活。一个晚上，游击队绑架了日军陆军士兵花屋小三郎（香川照之饰）和翻译董汉臣，把他们捆绑塞入麻袋放在马大三家里，并吩咐马好好看管，几天后的大年三十来带人。马大三和村民战战兢兢地看守两人，花屋小三郎和董汉臣数次发出求救信号，皆被村民化解。半年过去了，村民们担心事情暴露，却又不敢把花屋等放了。马大三最终被董汉臣说动，把花屋和董送到了日军宪兵队驻地，以换取粮食。日军宪兵军官酒冢猪吉是花屋的同乡。他表面上对马等人客气，但背后指责花屋让皇军蒙耻并殴打了他。宪兵队整队去马的村子里和村民联欢送粮，酒到酣时却乍露杀机。©豆瓣', '姜文', '姜文', 9.3, 581629, 'tt0245929', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553104888.jpg', 0.2, 0.3, 4.4, 24.6, 70.4, '0.246511,-0.246980,-0.478098,0.433241,-0.128785,-0.145366,0.563564,0.034851,-0.506299,-0.127518,-0.101519,0.211190,0.033319,0.216143,0.149111,-0.370708,-0.450525,-0.648746,-0.163742,-0.054495,-0.467448,-0.152891,0.400265,-0.538130,-0.191620,0.043554,0.126692,0.254874,0.020580,0.740299,0.166530,-0.030461,0.042598,0.517856,-0.062837,0.242212,-0.051447,-0.361101,-0.060049,-0.039502,-0.087948,-0.500972,-0.171157,0.035821,0.616119,0.370352,0.686014,-0.073097,0.064485,-0.040786,-0.284398,-0.288624,0.138926,0.289707,0.615348,-0.043736,-0.133433,-0.040736,-0.074360,0.016107,-0.089875,-0.035361,-0.022111,0.013318,-0.090452,-0.116141,-0.856863,0.620353,0.026305,0.455434,-0.075365,-0.155207,0.137547,0.202101,-0.086135,0.236029,0.112973,-0.065252,-0.553786,0.231773,0.403310,-0.499159,0.215024,-0.237022,-0.167668,-0.444367,0.089045,-0.026732,-0.192637,-0.130802,0.380512,-0.184977,-0.175778,-0.045920,-0.484090,-0.256530,-0.092035,-0.343930,0.049931,-0.351663,-0.065580,-0.598708,0.396436,-0.408666,-0.149472,0.591119,0.283118,0.342157,0.585392,-0.309443,-0.078670,0.304551,0.477903,-0.343273,0.279527,-0.124266,0.299748,-0.023142,-0.024136,-0.174260,0.453136,0.763394,0.814605,0.523457,-0.494191,-0.013954,-0.153267,0.147341', '1466273', '1394968', '1451563', '1296636');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291859', '布拉格之恋', '剧情', '本片根据米兰·昆德拉的同名小说改编。1968年，布拉格外科手术医生托马斯（丹尼尔·戴-刘易斯 Daniel Day-Lewis 饰）生活在对女人追逐的快乐中，享受着性的快感。画家萨比娜（莉娜·奥琳 Lena Olin 饰）是托马斯的红颜知己，但在一次去温泉疗养院出诊的过程中，托马斯结识了女招待特蕾莎（朱丽叶·比诺什Juliette Binoche 饰）。不久，特蕾莎只身来到布拉格，二人结婚。托马斯在婚后依然不改与萨比娜或其他女人偷情的恶习，特蕾莎无法忍受托马斯的不忠，深夜出走，却碰上苏联武装入侵捷克。三人先后逃亡至瑞士日内瓦，萨比娜认识了当地大学教授弗兰茨（德雷克·德·林特 Derek de Lint 饰），特蕾莎失去工作终日闷闷不乐，带着小狗卡列宁孤身重返布拉格。在自由与束缚之间，托马斯究竟该如何选择呢？本片是1988年美国十佳影片之一，获1989年奥斯卡最佳摄影、最佳改编剧本提名，金球奖最佳剧情片和最佳女配角（莉娜·奥琳）提名，并获英国电影电视协会最佳改编剧本奖，美国影评人协会最佳导演和最佳影片奖。', '丹尼尔·戴-刘易斯', '菲利普·考夫曼', 8.2, 63737, 'tt0096332', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910915447.jpg', 0.3, 1.5, 18, 48.4, 31.8, '-0.115227,-0.155823,-0.298191,0.459491,0.437709,-0.268680,0.480269,0.094230,-0.401664,-0.235934,0.080130,0.908009,-0.172841,0.194980,0.542569,0.217515,-0.807289,-0.645645,0.133798,-0.166104,-0.021499,-0.534286,-0.381759,0.013776,-0.111325,-0.367923,0.693815,-0.378142,-0.079295,0.617799,0.524729,0.166952,-0.070393,0.125114,0.116600,0.148245,0.494247,-0.289051,-0.716056,0.492616,0.159600,-0.100216,-0.480006,-0.134089,0.338488,0.102255,0.617032,-0.161723,0.351718,-0.052659,0.583001,-0.168936,-0.012330,-0.084062,0.036635,-0.249763,0.329337,0.272980,0.010272,0.187650,0.139471,-0.309506,-0.308706,0.263589,0.144226,0.222300,-0.293065,0.468209,-0.241120,0.217098,0.058056,-0.100287,-0.003094,0.254750,0.266922,0.120557,0.004006,-0.001943,-0.247344,0.525031,0.332074,0.031814,-0.311879,0.379715,-0.079417,-0.552201,-0.054846,-0.159976,-0.512675,-0.016512,0.345412,0.017373,0.120735,0.092815,-0.402117,-0.062407,-0.235921,-0.082690,0.083808,-0.134596,0.028003,-1.079090,-0.076184,-0.200366,-0.189254,-0.230445,-0.015439,-0.188682,0.460566,-0.559059,0.229681,0.604715,0.060311,-0.274822,0.761667,0.164165,0.168833,-0.403043,-0.183817,0.660598,0.033114,-0.032310,-0.023940,0.180357,0.022256,-0.109198,-0.278644,0.499610', '3275168', '1298616', '2075345', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291860', '瓦尔特保卫萨拉热窝', '战争', '1944年，纳粹发起的第二次世界大战接近尾声，为了能体面地结束战争，纳粹集结巴尔干半岛的A军团北调，妄图阻挡苏联红军南下。同时纳粹推出了“劳费尔计划”，即掠夺萨拉热窝丰富的燃油资源供应装甲部队。纳粹为实现劳费尔计划，将党卫军上校芬迪特里士派往萨拉热窝，全力消灭瓦尔特（Velimir ''Bata'' Zivojinovic 饰）领导的当地游击队。芬迪特里士令间谍假冒瓦尔特，在叛徒的内应下，假瓦尔特与几名真正的游击队员组成抵抗委员会，并得到游击队员名单，诱杀了众多抵抗组织成员。真正的瓦尔特由于作战需要无法公开身份，但凭借个人出色的谋略与众多英勇的游击队员终于让间谍现出了原形。为了阻止劳费尔计划，清除了内奸的游击队员们再次出击。©豆瓣', '韦利米尔·巴塔·日沃伊诺维奇', '哈伊鲁丁·克尔瓦瓦茨', 8.7, 14316, 'tt0069452', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2556873379.jpg', 0.2, 0.6, 10.4, 39.7, 49.1, '0.085935,0.187861,-0.457912,0.496143,-0.056394,-0.037685,0.253531,-0.321653,-0.340445,-0.124188,0.133578,0.368004,0.407019,-0.521805,0.183364,-0.451173,-0.429136,-0.841016,-0.339777,0.004347,-0.188612,-0.402547,-0.451671,-0.582545,-0.053660,-0.544203,0.987091,0.313650,-0.299011,0.142815,0.253326,0.412875,-0.040511,0.022994,0.166639,-0.234704,0.274160,-0.681083,-0.553771,0.395930,-0.312905,-0.068591,-0.308397,0.140838,0.016828,0.339851,0.594258,-0.414640,0.229649,-0.323342,-0.023991,-0.433951,0.208221,0.181116,0.382834,0.122831,-0.028616,0.375449,0.106627,0.118720,-0.148217,-0.134190,-0.921030,-0.161757,0.159388,-0.080235,-0.440173,0.143271,-0.344083,0.328541,0.151143,-0.281558,-0.132284,0.920498,0.057556,0.082203,-0.124524,0.056716,-0.627276,0.161096,0.545526,-0.329163,-0.184507,-0.286994,-0.173944,-0.277607,0.055994,-0.507903,0.184538,-0.139491,0.238553,-0.048391,0.236661,0.397136,-0.715586,-0.229534,-0.429221,-0.372832,0.105244,-0.215959,0.047289,-0.920260,-0.121074,0.208573,-0.032892,0.368958,0.208623,0.197868,0.818310,-0.778731,0.032585,0.562996,0.231223,-0.450570,0.068497,0.085857,0.137767,-0.205052,-0.068151,0.207134,0.210801,0.438125,0.164924,0.138782,-0.127090,-0.517831,-0.052854,-0.010588', '2369613', '3861846', '3266509', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291861', '人证', '剧情', '死于东京皇家饭店电梯里的美国黑人青年被人发现后，警方展开调查，从死者遗物中，知晓其名叫焦尼，并推断其来日目的是为找寻生母。根据种种线索，警方来到某温泉，发现知情人已被杀害，但还是知晓了知名服装设计师八杉恭子（冈田茉莉子）当年曾与一美国黑人士兵在此同居之事，遂派警官栋居（松田优作）前去美国向纽约警察肖夫坦（乔治•肯尼迪）求证。求证过程中，栋居陷入历史记忆与民族情结中，几欲将眼前的美国人尤其肖夫坦与当年在日本犯下罪行的刽子手混为一谈，但终回复理智完成了任务，将八杉恭子圈定为凶手，而八杉恭子不过也是历史的受害者。©豆瓣', '冈田茉莉子', '佐藤纯弥', 8.2, 9306, 'tt0076460', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1733454018.jpg', 0.4, 1.3, 17.7, 50, 30.6, '0.182354,0.172717,-0.440680,0.402251,0.160025,-0.149861,0.468396,-0.208391,-0.912080,-0.615932,-0.032008,0.722521,-0.023868,0.306565,0.563642,-0.008433,-0.304829,-0.773636,-0.193353,-0.443967,-0.268166,-0.545707,0.060691,-0.335778,-0.041152,-0.198545,0.603693,0.331267,-0.214680,0.396446,0.164805,0.489442,-0.540184,0.278268,0.097053,0.005284,0.216812,-0.267772,-0.587029,0.227816,0.035678,-0.454869,0.008320,0.180176,-0.232441,0.406101,0.656438,-0.278225,-0.255968,-0.318583,0.305998,-0.176821,-0.059626,0.270972,0.570229,0.195701,0.140295,0.790324,-0.148429,-0.035378,0.124008,-0.051468,-0.488857,-0.125296,0.211703,0.222135,-0.390473,0.152156,-0.347451,0.097181,-0.084084,-0.128389,0.409730,0.121597,0.406306,0.159454,0.050377,-0.251785,-0.306450,0.022655,0.575840,-0.069771,0.222427,-0.004548,-0.125609,-0.561786,0.149764,-0.111567,0.204320,0.317815,0.103021,0.149197,-0.266846,0.237970,-0.380623,-0.246852,-0.424591,-0.080849,-0.044544,-0.247919,-0.200526,-0.505714,-0.203350,0.007495,-0.197469,-0.082806,0.189004,-0.174216,0.302859,-0.721220,-0.000755,0.433168,0.259445,-0.534319,0.733397,-0.196475,0.121301,-0.305382,0.087828,0.149815,0.325074,0.357692,-0.250600,-0.008891,-0.208141,-0.571957,-0.470708,-0.085346', '3263169', '1307456', '5384590', '1296252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291863', '追捕', '剧情', '为人正直的检查官杜丘（高仓健 饰）被人控告犯有抢劫、强奸罪，自知清白的他为了洗清冤屈，开始了一边躲避警察追捕、一边查找事实真相的逃亡。途中，杜丘于山中冒险救下牧场主的女儿真由美（中野良子 饰），两人生出真情。在真由美及其父亲的帮助下，历尽艰险的杜丘终于拨开重重迷雾，在一家精神 病院，他找到了诬告自己的横路进二，但对方已神智不清。为了将其中隐情一一揭出，杜丘装病住进这家医院，开始小心翼翼的调查求证，巨大的政治阴谋遂即浮出水面。©豆瓣', '高仓健', '佐藤纯弥', 8.3, 26700, 'tt0327002', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2198650728.jpg', 0.2, 1.1, 16.7, 49.6, 32.4, '0.109213,-0.013575,-0.317571,0.284445,-0.032650,-0.117479,0.520738,0.121458,-0.335078,-0.125297,0.452521,0.401407,0.028552,0.311646,0.172318,0.050371,-0.282395,-0.503768,0.005047,-0.071488,-0.175747,-0.492330,-0.384080,-0.197837,-0.110328,0.043189,0.385999,0.459779,-0.072630,0.204513,0.232458,0.299680,-0.432295,0.078077,-0.154612,0.126497,-0.063766,0.023707,-0.204692,0.179208,0.162031,-0.593211,-0.177031,0.227305,-0.125140,0.561357,0.541159,-0.167394,-0.118865,-0.210155,0.387159,-0.386755,0.172580,0.245045,0.229011,0.000457,0.070253,0.347632,-0.302409,-0.217003,0.228674,0.187360,-0.625398,-0.151891,0.168525,0.182002,-0.409055,-0.134003,-0.243773,0.036628,0.149107,-0.133446,-0.132735,0.287709,0.126329,0.080111,-0.406945,0.059501,-0.545868,-0.029274,0.420950,-0.125229,0.331255,-0.027201,-0.174504,-0.153328,0.353347,-0.148599,0.084931,-0.397642,0.501850,0.010352,-0.296125,-0.103415,-0.235351,-0.258409,-0.443355,0.018669,-0.132889,-0.257905,-0.127596,-0.261925,-0.131017,0.029543,-0.258996,0.012092,0.066966,-0.381832,0.204526,-0.426139,0.039713,0.792129,-0.026081,-0.574644,0.155465,0.131191,0.067484,0.066340,-0.069850,0.165408,0.233104,0.638960,0.262915,0.209882,-0.186334,-0.183917,-0.445217,-0.048375', '1293045', '1297229', '27018354', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291864', '天云山传奇', '剧情', '1978年冬天，地委组织部副部长宋薇（王馥荔 饰）和丈夫、部长吴遥（仲星火 饰）正在对文革期间的冤假错案进行拨乱反正。从天云山赶回的周瑜贞（洪学敏 饰）向宋薇汇报工作，声称在天云山调查期间拜访了一对儿特殊的夫妻：丈夫罗群（石维坚 饰）是个靠赶车维生的老右派，有多部没有发表的著述；妻子冯晴岚（施建岚 饰）是有病在身的小学教员。这对儿夫妻凄凉的境遇令周瑜贞同情，而且她通过了解，知道罗群是当年宋薇在天云山的恋人……原来二十年前宋薇与冯晴岚一起加入考察队驻扎天云山，吴遥和罗群是前后两任政治委员，吴遥暗恋宋薇，于是陷害罗群是反党分子。罗群的遭遇令宋薇吃惊和愤怒，然而在为罗群平反的问题上，吴遥再次出面阻挠……©豆瓣', '石维坚', '谢晋', 8.1, 7950, 'tt0081632', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910917031.jpg', 0.4, 1.4, 18.6, 51.6, 28, '0.144513,-0.338811,-0.598086,0.489902,0.091725,-0.237706,0.424304,0.182862,-0.772993,-0.274913,0.184750,0.387592,-0.143226,0.156920,0.149229,-0.107730,-0.171574,-0.620269,-0.198577,-0.016992,-0.241605,-0.773495,0.063540,-0.037127,0.015592,-0.277793,0.424860,-0.069313,-0.244539,0.652658,0.483863,0.329868,-0.099655,0.216630,-0.158008,0.112565,0.045507,0.244599,-0.361388,-0.027539,0.201742,-0.229796,-0.314510,-0.112106,0.150670,0.457442,0.417138,-0.071801,-0.211878,0.105348,0.265363,-0.115605,-0.053052,0.134312,0.623798,0.125685,0.185238,0.470087,-0.364986,-0.049096,0.111068,-0.071857,-0.290138,0.167966,0.224390,0.219677,-0.600430,0.442108,-0.131816,-0.001424,0.046540,-0.325382,0.473436,0.726118,-0.103131,0.530825,-0.115994,-0.001993,-0.263211,0.422903,0.538500,0.170176,0.099808,0.036435,-0.191487,-0.198982,0.047606,-0.063380,-0.253911,-0.003976,-0.045819,-0.207331,0.122042,-0.008696,-0.336131,-0.151122,-0.116905,0.240439,0.173138,-0.242909,-0.173799,-0.385349,-0.217446,-0.538730,-0.301046,-0.037222,0.083064,-0.463031,0.463684,-0.864693,0.149336,0.035955,0.213632,-0.620160,0.858226,0.199746,0.032919,-0.489053,0.121974,-0.076872,-0.031226,0.061899,0.170712,0.214191,-0.112315,-0.316478,-0.137931,-0.094594', '22964524', '1306544', '1302384', '25907086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291866', '佐罗', '喜剧', '西班牙人在南美洲殖民统治时代，苛捐杂税民不聊生。新总督米格尔在上任途中被杀，临死时把官印交与好友“欧洲第一剑士”唐迭戈（阿兰·德龙 Alain Delon 饰），要其承继遗志。三个月后，新总督突然出现，不过他似乎是一个贵族的纨绔子弟，一切事物均假手他人。与此同时，民传说一位蒙面黑侠从天而降，警恶惩奸，锄强扶弱，"佐罗"的英名不径而走，令殖民者大为头痛，而新总督的身份更令人怀疑。身兼总督和侠客双重身份的迭戈与残暴的韦尔塔上校斗志斗勇，终于在韦尔塔强娶奥顿西娅的婚礼上结果了这个恶棍的性命，为当地百姓除了大害。佐罗告别了好姑娘奥顿西娅，告别了新阿拉贡。这个主持公道、追求自由的义侠佐罗又跨上枣红马去行侠仗义了……©豆瓣', '阿兰·德龙', '杜奇奥·泰萨利', 8.1, 17547, 'tt0072448', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199261563.jpg', 0.2, 1, 18.5, 52.6, 27.8, '0.033201,-0.004561,-0.337290,0.384471,0.008407,-0.597866,0.237427,0.337117,-0.595065,-0.330110,0.077473,1.000573,-0.008378,-0.045059,0.467196,0.071998,-0.279848,-0.683598,-0.226650,-0.136281,-0.224833,-0.407234,-0.097428,-0.164908,-0.144925,-0.274851,0.527786,-0.096086,0.169103,0.446355,0.507750,0.228572,0.097523,0.428357,-0.439520,0.117834,0.324104,-0.254637,-0.390456,0.137297,-0.096357,-0.192530,-0.134289,0.333812,-0.183839,0.124382,0.379706,-0.418762,0.019773,-0.245325,0.398993,-0.212186,0.127257,0.101625,0.171474,-0.057780,-0.007169,0.206693,-0.010651,-0.131079,0.026272,-0.087756,-0.370808,0.150923,0.000924,0.076615,-0.515116,0.450101,-0.261488,-0.036608,0.158562,-0.260656,0.324237,0.397133,0.105193,0.277362,0.001802,0.014379,-0.365816,0.230017,0.483157,0.056639,-0.096275,-0.104841,-0.057710,-0.141756,0.235060,-0.186216,-0.259689,-0.222470,0.336102,-0.112031,0.175761,0.408323,-0.638458,-0.134678,-0.538660,0.065525,-0.073514,-0.116792,-0.241909,-0.267559,-0.098650,-0.178234,-0.012704,-0.151643,0.410545,0.019567,0.644675,-0.690690,-0.047606,0.352237,0.228583,-0.559506,0.378764,0.079912,0.241356,-0.070241,-0.265704,0.204103,0.318243,0.418335,-0.127859,0.228107,-0.041567,-0.262012,-0.083380,0.388488', '30345227', '3148748', '1309069', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291867', '暴劫梨花', '剧情', '一次意外中，莎拉（朱迪·福斯特 Jodie Foster 饰）在酒吧被人强暴，在一旁围观的男人们非但没有出手制止这可怕的暴行，反而幸灾乐祸的加入了其中。事后，身心都受到了巨大创伤的莎拉将这些可恶的男人告上了法庭，没想到社会舆论却反过来指责她的放荡和品行不端。凯瑟琳（凯莉·麦吉利斯 Kelly McGillis 饰）是负责为莎拉辩护的检察官，身为女人，她对莎拉的不幸遭遇有着更深的理解和同情。审判的结果公布了，犯下罪行的男人们只被判了九个月的有期徒刑，本用来惩奸除恶的法律最后却沦为了犯罪者的保护伞，愤怒的凯瑟琳决不能坐视不管。在凯瑟琳和莎拉的不懈努力下，恶人终于受到了应有的惩罚，两个女人通过她们的行动，挽回了身为女人的勇气和尊严。©豆瓣', '朱迪·福斯特', '乔纳森·卡普兰', 7.9, 7531, 'tt0094608', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1910917302.jpg', 0.3, 1.2, 22, 54.3, 22.1, '0.260301,0.117164,-0.724747,0.489931,-0.423328,-0.071207,0.859557,0.186486,-0.408997,0.127587,0.479647,0.715881,-0.454218,0.108257,0.178378,-0.084651,-0.280238,-0.726891,-0.186652,-0.210554,-0.350406,-0.615843,-0.129282,-0.364730,-0.214255,-0.352079,0.429859,-0.048799,-0.389877,0.304586,0.645746,0.387654,0.268313,0.569880,-0.080354,0.235654,0.169573,-0.204595,0.002890,0.057198,0.117239,-0.432369,-0.185073,0.479819,-0.173899,0.541838,0.625058,-0.522089,-0.319472,-0.374875,0.463521,-0.550057,0.121822,0.445029,0.135164,-0.267086,0.088539,0.357696,-0.198639,-0.167502,0.511877,0.048430,-0.966405,-0.057647,0.035826,0.139613,-0.610985,0.593566,-0.202651,0.090399,0.194086,0.028553,0.045918,0.112402,0.072032,0.496969,-0.164229,-0.014215,-0.557184,0.038474,0.610308,0.131403,-0.392274,-0.019588,-0.573983,-0.327031,-0.123076,-0.492010,-0.421829,-0.188912,0.357873,0.006120,-0.198995,0.311079,-0.437292,-0.322856,-0.382810,-0.089208,-0.221469,-0.574002,-0.157914,-0.500423,-0.078591,-0.352410,-0.465434,0.182262,0.126926,-0.239076,0.802505,-0.799812,0.312000,0.571745,0.533735,-0.766047,0.544039,0.497260,0.098733,0.066876,-0.456495,0.224909,0.207932,0.351445,0.383050,0.206943,0.004430,-0.062614,-0.176804,0.411491', '26678784', '30163500', '4820775', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291868', '情人', '剧情', '1929年的越南是法国殖民地，一个15岁的法国少女（珍·玛奇 饰）在西贡女子寄宿学校读书。每逢假期她便回家，母亲办了一所很小的学校，收入甚少。她有两个哥哥，大哥比尔吸毒成瘾且横行霸道，二哥保罗生性懦弱，常受大哥的欺负。一天少女一如往常一样告别母亲乘上渡船回学校，在船上遇到一个坐黑色大轿车的中国阔少爷（梁家辉 饰），他是华侨富翁的独生子。中国男人喜欢这名白人少女便去搭讪，两人便搭上了。 少女在寄宿学校里知道有的女生在外卖淫，她也想找个有钱人试试，因此很主动地与男人交谈。上岸后两人逛了西贡，还一起上馆子吃中国饭菜，男人用汽车送她回学校。第二天刚放学，黑色汽车就等在校门口了。 两人很快就坠入爱河。男人把少女带到他的公馆，这是中国富人们常用来金屋藏娇的地方。他俩在这里幽会、洗澡、玩耍。有时晚上也不回学校，校方只好通知她的母亲，然而……©豆瓣', '珍·玛奇', '让-雅克·阿诺', 8.2, 227646, 'tt0101316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1674536431.jpg', 0.2, 1.1, 17.1, 50, 31.7, '0.512011,-0.157141,-0.509806,0.104139,-0.347681,-0.484217,0.577122,0.274167,-0.216617,-0.088212,0.079415,0.745491,0.076188,0.605655,0.334609,0.223317,-0.533666,-0.382778,0.079388,-0.308353,-0.197549,-0.078963,0.216884,-0.071375,0.085149,0.050634,0.195576,-0.279043,-0.043166,0.440807,0.091580,-0.149748,-0.066038,0.580872,-0.609823,-0.077065,-0.163060,0.259304,0.078951,0.325344,-0.009682,-0.242883,-0.085656,-0.430786,0.349025,0.171536,0.567279,0.234670,0.019274,-0.158012,0.158673,0.102897,-0.186180,-0.004619,0.448451,-0.253406,0.279296,-0.022808,-0.131402,-0.011195,-0.095886,-0.037924,0.284999,0.242623,-0.063612,-0.024516,-0.557981,0.441067,0.067172,0.071362,0.067693,-0.507394,0.137079,0.065406,-0.174691,0.281388,0.274669,0.076754,-0.501431,0.368793,0.584557,-0.009738,0.081347,0.156463,-0.098869,-0.189809,0.287788,-0.020659,-0.517823,-0.119955,0.072912,-0.460316,-0.426279,-0.158334,-0.511653,0.066296,-0.102776,-0.021456,0.156222,-0.158464,-0.117429,-0.730723,0.232406,-0.256002,-0.219316,0.202382,0.256913,0.168666,0.644528,-0.717820,0.185000,0.710513,0.640915,-0.409267,0.821989,-0.152621,0.120097,-0.212087,0.288603,-0.018637,0.024013,0.260794,-0.128191,0.645021,-0.147236,0.072096,-0.294811,0.285878', '3055049', '26687241', '6024430', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291869', '本能', '剧情', '退休摇滚明星强尼·博兹（Bill Cable 饰）在性行为的过程中被人用白丝巾捆绑双手后用冰锥残忍刺死。其女友凯瑟琳·特拉梅尔（Sharon Stone 饰）是一名作家，去年出版的小说中就有双手被白丝巾捆绑的退休摇滚明星被女友用冰锥刺死的情节。虽然特拉梅尔通过了谎言测试，但曾枪杀两位游客却被判无罪的尼克·柯兰警探（Michael Douglas 饰）坚持认为特拉梅尔在说谎。因为他自己也曾接受过谎言测试，并且通过了……©豆瓣', '迈克尔·道格拉斯', '保罗·范霍文', 7.9, 151964, 'tt0103772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2580938083.jpg', 0.3, 1.7, 24.9, 50.5, 22.5, '0.394224,0.020167,-0.050354,0.399408,-0.028443,-0.036780,0.748388,-0.165795,-0.310287,-0.147415,0.295379,0.504305,-0.590365,0.171406,0.166941,-0.108584,-0.238387,-0.950460,0.162555,0.103388,-0.580335,-0.417696,0.047635,-0.100711,-0.178767,-0.473511,0.638836,-0.022255,-0.062502,0.201675,0.390266,0.522807,-0.028393,0.322899,-0.163132,-0.049352,0.061790,-0.049822,-0.106808,0.186273,-0.043275,-0.342883,0.316319,0.243073,-0.149307,0.464583,0.315539,-0.218931,0.249478,-0.112812,0.322283,-0.268024,0.015716,0.253549,0.268153,0.146450,0.475807,0.048515,-0.033231,0.133534,-0.033248,-0.174492,-0.523013,-0.144081,-0.035121,0.214409,-0.747202,0.185462,-0.351455,0.172948,-0.303097,-0.090003,0.045226,-0.286517,0.180475,0.154032,0.022819,-0.025347,-0.387553,0.613843,0.020847,0.035265,-0.372333,0.023420,-0.430202,-0.350351,0.059060,-0.150214,-0.100779,0.103264,0.368121,-0.254166,-0.112533,0.077310,-0.642632,-0.378180,-0.307051,0.093689,-0.072428,-0.362727,-0.353843,-0.488402,0.211967,-0.338492,-0.234853,-0.116606,0.306353,-0.493571,0.332046,-0.911771,0.136978,0.260278,0.345363,-0.010182,0.478188,0.255276,-0.096572,-0.084352,-0.178472,0.353954,0.225212,0.059667,0.459547,0.404700,0.307673,-0.343793,-0.253585,0.720531', '1986338', '30345227', '4202326', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291870', '雨人', '剧情', '查理（汤姆·克鲁斯 Tom Cruise 饰）父亲去世，留下了300万美元的遗产。然而令他意外的是，遗产全部给了一个他不认识的哥哥雷蒙（达斯汀·霍夫曼 Dustin Hoffman 饰）。雷蒙的名字查理从没听过，这个事件让他气愤不已。他决定前去寻找哥哥。谁知雷蒙的住处就在一个精神病院里，原来他自幼患有自闭症，母亲去世后就被送到精神病院治疗。查理心中有了算计，他把雷蒙带出精神病院，企图骗他出让遗产。雷蒙的生活习惯奇异，活在自己的幻想世界里，有很多离奇古怪的行为。并且，查理在共处中发现了雷蒙惊人的记忆能力，他试着利用哥哥过目不忘的本领去赌场上试一下身手，赢得了一大笔奖金，使查理足以摆脱穷困生活。而令查理收获更大的是，他还获得了慢慢升温的亲情，这种手足情远远胜过了他原先图谋的300万的遗产。©豆瓣', '达斯汀·霍夫曼', '巴瑞·莱文森', 8.7, 380281, 'tt0095953', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2353324612.jpg', 0.1, 0.4, 8.9, 43.5, 47, '-0.002867,0.228848,-0.745544,0.652289,-0.467426,-0.417024,0.680773,-0.085407,-0.642828,-0.297067,0.073416,0.861790,0.055386,0.270555,0.130578,0.189006,-0.197663,-0.527225,0.010129,-0.121196,-0.272995,-0.628414,-0.445085,-0.275674,-0.251107,-0.315601,0.312492,-0.054074,-0.262150,0.310050,0.048931,0.300930,0.221644,0.483265,-0.268478,0.398050,0.106588,-0.002811,-0.098228,0.151558,0.267458,-0.285092,0.099574,0.481006,-0.025569,0.376902,0.608228,-0.093361,-0.243669,-0.006897,0.443663,-0.097284,-0.151917,0.049168,-0.006514,0.125040,0.051933,0.208553,-0.436981,0.058819,0.154241,0.126694,-0.834338,-0.030246,0.058571,0.054949,-0.696763,0.206510,-0.368583,0.009747,0.088364,-0.350386,0.219289,0.089567,0.157178,0.366399,-0.315411,-0.032920,-0.674238,0.199205,0.568588,-0.436300,-0.056116,0.283329,-0.414431,-0.369692,0.070800,-0.147375,-0.337694,0.040508,0.447012,0.024993,-0.353202,0.189911,-0.370462,-0.131746,-0.305768,-0.233684,-0.080322,-0.369497,0.003316,-0.333829,-0.434615,-0.297092,-0.491044,-0.184316,0.036005,-0.534278,0.654148,-0.621353,0.160063,0.667754,0.291498,-0.541690,0.667180,-0.009004,0.044016,0.124901,0.105511,0.345521,0.151653,0.112733,0.128262,0.245585,0.242889,-0.236876,-0.255623,0.774617', '25763555', '1783461', '1309069', '5323380');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291872', '苔丝', '剧情', '苔丝（娜塔莎·金斯基 Nastassja Kinski 饰）出生于英国乡村的一个小农家庭，一天她的父亲听说自家是古老贵族德伯维尔的后裔。这个传闻，让苔丝的一生发生了剧变。因为有一个姓德伯维尔的有钱人家就住在不远，父母让苔丝前去攀亲。苔丝的美貌让德伯维尔家的少爷阿雷克（利·劳森 Leigh Lawson 饰）心生邪念，他夺走了苔丝的贞洁，让苔丝怀上了孩子，然而孩子却在出生后不久就夭折了。在德伯维尔家的这段悲惨经历，让苔丝失去了当时社会最看重的贞操，当她在牛奶厂遇上安吉尔（彼得·弗斯 Peter Firth饰），以为安吉尔是她的终生伴侣时，却在新婚一夜因为告知安吉尔自己的过往而遭到抛弃。对爱情对生活已经绝望的苔丝，此时又遇上了家庭的变故。面对阿雷克的再次追求，苔丝别无选择。然而，苔丝的命运仍然急泻直下……©豆瓣', '娜塔莎·金斯基', '罗曼·波兰斯基', 8.2, 32900, 'tt0080009', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1758842078.jpg', 0.2, 1, 16.6, 53.3, 28.9, '0.444860,0.007739,-0.777954,0.247185,-0.374356,-0.626036,0.951868,0.116990,-0.689372,-0.316028,0.375513,0.978928,-0.094096,0.393035,0.295538,0.384913,-0.238499,-0.550101,0.308339,-0.102281,-0.087005,-0.321942,-0.141343,-0.098918,-0.004407,-0.638327,0.548279,-0.006875,-0.006935,0.276622,0.172332,0.481343,0.294957,0.339953,-0.218508,0.443665,0.044872,0.147299,-0.210722,0.269902,0.037471,-0.034110,-0.249561,0.112094,0.054585,0.392335,0.342138,-0.216296,-0.136972,-0.170776,0.617557,-0.196296,0.010764,0.253207,0.360270,-0.386819,-0.010054,0.201448,-0.526178,-0.063505,0.278131,0.112315,-0.768220,0.141382,0.146918,0.158043,-0.802259,0.539802,-0.184128,-0.404236,0.194330,-0.370223,0.086418,0.560750,0.214756,0.580395,-0.456358,0.070595,-0.707984,-0.069671,0.820655,0.009698,-0.426876,0.365401,-0.389817,-0.190912,-0.033276,-0.233551,-0.830664,-0.006390,0.380736,0.158416,-0.511632,0.523308,-0.498461,-0.181773,-0.438472,-0.103625,0.335313,-0.451095,-0.341791,-0.246279,-0.212140,-0.359842,-0.544213,-0.137394,0.219842,-0.240458,0.753800,-0.669818,0.377441,0.534085,0.266105,-0.526052,0.576082,0.359193,0.213236,0.189816,0.194829,0.697849,0.168311,0.169969,-0.130770,0.228633,0.064540,-0.010746,-0.143070,0.692119', '25721544', '1460341', '26245360', '2576355