INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291875', '阳光灿烂的日子', '剧情', '20世纪70年代初的北京，忙着“闹革命”大人无空理会小孩，加上学校停课无事可做，以军队大院男孩为突出代表的少年人便自找乐子，靠起哄、打架、闹事、拍婆子等方式挥霍过量的荷尔蒙。马小军（夏雨 饰）就是这样的少年，他的嗜好之一是趁别人家无人用万能钥匙将其锁打开，溜进去耍玩一番，正是用这样的方式，少女米兰（宁静 饰）的照片先于其人入了马小军的双眼。通过院里的“头儿”刘忆苦（耿乐 饰），马小军又见到之前在炮局偶然瞥见过一眼的米兰，开始正式将其当作梦中情人，然而在米兰眼中，马小军不过是毛孩一个，她中意的人是成熟、稳重、帅气的刘忆苦。自此，马小军迎来五味混杂的青春期生活。本片改编自王朔短篇小说《动物凶猛》。夏雨凭此片获得第51届威尼斯国际电影节最佳男演员（银狮奖）。©豆瓣', '夏雨', '姜文', 8.9, 576486, 'tt0111786', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2564685215.jpg', 0.2, 0.5, 8.4, 38.3, 52.6, '0.440601,0.075109,-0.512543,0.447285,-0.329712,-0.295376,0.570044,0.113183,-0.456865,0.047470,0.032061,0.318548,-0.200361,0.255259,0.257671,-0.204493,-0.153940,-0.467296,-0.149521,-0.043277,0.042133,-0.231198,-0.092135,-0.068324,-0.011597,-0.357375,0.446074,-0.106772,-0.242913,0.325907,0.434341,0.115515,0.013920,0.200777,-0.115972,-0.165381,-0.103177,0.082528,-0.307963,0.280167,0.061144,-0.238741,-0.367611,-0.125045,-0.111410,0.150800,0.655300,-0.160370,-0.000900,-0.130133,0.548440,0.070493,-0.252179,0.012978,0.258805,-0.119469,0.219365,-0.141192,-0.003009,0.283166,0.004695,-0.074131,-0.159998,0.063554,0.164151,0.024639,-0.478170,0.252837,0.030041,-0.105462,0.159308,-0.351213,0.141145,0.111716,0.356536,0.399761,0.106408,0.020335,-0.358019,0.312230,0.361386,0.092947,-0.229896,0.295413,-0.120235,-0.383267,0.283198,-0.332763,-0.319483,0.096516,0.264027,-0.267953,-0.084867,-0.154577,-0.335302,0.057586,0.072840,-0.176349,0.237542,-0.194619,-0.151319,-0.642530,-0.020279,-0.288318,-0.165756,0.087414,0.210636,-0.287488,0.510042,-0.672534,0.082698,0.451830,0.006439,-0.188536,0.623290,-0.148200,-0.008394,-0.289921,-0.208277,-0.072573,0.066322,0.290971,0.065424,0.436223,-0.223410,-0.215650,0.027116,0.229225', '1418179', '3811356', '1292272', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291876', '黄土地', '剧情', '陕北黄土高原上的贫苦女孩翠巧（薛白饰），自小由父亲（谭托饰）作主定下娃娃亲。八路军文工团团员顾青（王学圻饰），为采集民歌来到翠巧家，一段时间后，与翠巧家彼此仿佛自家人般。顾青讲述起延安妇女婚姻自主的情况，翠巧听后，心生向往。父亲虽善良，可又愚昧，他要翠巧在四月里完婚。顾青行将离去，翠巧要随去延安，顾青有心无力。翠巧弟弟憨憨（刘强饰）跟着顾大哥，送了一程又一程。翻过一座山梁，顾青看见翠巧站在峰顶上，她用甜美歌喉唱歌送别，顾青深受感动。四月，翠巧在完婚之日，心有不甘决然逃出夫家，划船渡河去追求新的生活……©豆瓣', '薛白', '陈凯歌', 7.9, 32641, 'tt0087433', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2457752524.jpg', 0.4, 1.6, 21.8, 53.1, 23, '0.024952,-0.028743,-0.638372,0.439050,-0.045754,-0.544288,0.476116,0.212738,-0.337227,0.076887,0.060132,0.384644,-0.014697,0.443747,0.273380,-0.114714,-0.304293,-0.240003,0.067006,-0.215598,0.059344,-0.125946,0.475247,-0.047440,0.001677,0.153964,0.343273,0.066446,0.105426,0.629636,0.253850,-0.003920,-0.379129,0.338248,-0.174277,0.069277,-0.459872,0.123056,-0.465323,-0.032658,0.052629,-0.108116,-0.348308,-0.539219,0.065600,0.204715,0.614720,-0.153080,0.015462,-0.228652,0.198148,0.172742,0.304151,0.261614,0.120436,0.278925,-0.134148,0.053247,-0.355557,-0.118452,-0.207697,-0.287028,0.348751,0.207970,-0.023148,-0.102504,-0.512560,0.207353,0.103836,0.092432,0.050021,-0.728945,0.195803,0.203081,-0.031790,0.452695,-0.256078,0.267614,-0.085991,0.036232,0.680399,-0.064842,0.306551,0.009542,0.026187,-0.341718,0.388969,0.241796,-0.509763,0.002763,-0.064171,-0.045388,0.002909,-0.022447,-0.286662,-0.118649,-0.151836,0.153083,0.068024,-0.383451,-0.073590,-0.199064,0.043608,-0.226293,-0.369602,0.157602,0.296082,-0.135822,0.614672,-0.364977,0.141958,-0.022240,0.406680,-0.309492,0.298415,-0.196413,0.251039,-0.230819,0.336309,0.598144,-0.251136,0.276849,0.240579,0.371753,-0.370752,0.248708,-0.188985,0.250469', '1300945', '1451563', '1300202', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291877', '两生花', '剧情', '两个少女，一个生在波兰，一个生在法国，同样的相貌，同样的年龄，她们也有一样的名字：薇罗尼卡。她们都那样喜欢音乐，嗓音甜美。波兰的薇罗尼卡非常喜欢唱歌，唱高音特别出众。她觉得自己并不是独自一人生活在这个世界上，没想到一天她真的遇到一个样子跟她一模一样的女孩，可是她自己却在一次表演中心脏病发暴毙在舞台上。此时身在法国的薇罗尼卡正沉醉在与男友的欢愉中，突然她觉得特别的空虚难过。此后她的生活中便常常响起一段极其哀怨的曲子，她爱上了一个儿童读物作家。一次与男友聊天的过程中，她发现了在波兰拍的照片中，出现了一个与自己极为相似的女子，此时她才深深相信，世界上还有另外一个自己存在。©豆瓣', '伊莲娜·雅各布', '克日什托夫·基耶斯洛夫斯基', 8.4, 74574, 'tt0101765', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910919834.jpg', 0.3, 1.6, 16, 43.3, 38.8, '0.475386,0.029333,-0.884095,0.966549,-0.435341,-0.058254,1.299367,-0.082950,-0.553725,-0.142903,0.307989,1.220682,-0.276208,0.608417,0.172440,0.062646,-0.155593,-0.809402,0.196342,-0.335842,-0.154600,-0.395458,-0.123607,0.268637,-0.288010,-0.278354,0.701319,-0.277440,-0.154577,0.630577,0.137090,0.018199,0.025741,0.640436,-0.345369,-0.155735,0.004464,0.118116,0.263912,0.077520,0.164290,-0.046641,-0.076344,0.361750,-0.495215,0.142242,0.675718,-0.377949,-0.097194,0.088260,0.539029,0.057678,-0.107115,0.068968,0.184494,-0.240548,0.349721,-0.216051,-0.418750,-0.111712,-0.107846,0.050563,-0.606646,0.209840,-0.019407,0.373770,-0.466112,0.429485,0.003325,-0.080184,0.082098,-0.267017,0.201135,0.262209,0.502596,0.634788,-0.444317,0.099086,-0.415718,-0.033880,0.822844,0.262125,-0.346591,0.781256,-0.382672,-0.464712,-0.185637,-0.075387,-0.854247,0.056465,0.041718,-0.279779,-0.191373,-0.072226,-0.575149,0.524204,0.047788,-0.231655,-0.213369,-0.246472,-0.309498,-0.298691,-0.239288,-0.523940,-0.497367,-0.123374,-0.029231,-0.414124,0.882044,-0.968480,0.266696,0.590486,0.207300,-0.301012,0.713564,0.448199,-0.046683,-0.147686,-0.218101,0.511979,-0.085056,-0.365437,-0.096639,0.634535,-0.166854,0.185967,-0.651626,0.893062', '1296534', '4275444', '24756472', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291878', '不良教育', '剧情', '恩里克（费雷•马丁内兹 饰）和伊格莱西奥（弗朗西斯科•拜奥拉 饰）是教会学校的同学，更是一对同性恋人。学校的莫雷神父以留下恩里克为诱饵占有了伊格莱西奥，但最终恩里克还是离开了教会学校。这对同性恋人也就劳燕分飞。成年后的恩里克已是一名大有前途的导演。一天，伊格莱西奥带着剧本找到了恩里克，希望自己能出演男主角。剧本描写的就是他们的成长经历加上想象的成年经历，恩里克对剧本十分感兴趣，但却不同意由伊格莱西奥出演。当恩里克来到伊格莱西奥的家乡时，秘密一幕幕揭开……©豆瓣', '盖尔·加西亚·贝纳尔', '佩德罗·阿莫多瓦', 8.3, 38621, 'tt0275491', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910921856.jpg', 0.3, 1.1, 14.8, 50.2, 33.6, '0.297899,-0.233934,-0.344625,0.693065,0.078342,-0.684431,0.633244,0.104116,-0.358406,-0.512511,0.010183,0.772517,-0.308348,0.063736,0.629229,0.206457,-0.684946,-0.516235,0.237651,-0.150755,-0.169858,-0.916454,-0.204538,-0.091460,-0.114698,-0.358867,0.581115,-0.012108,-0.302185,0.159494,0.291556,0.511752,0.312981,0.068358,0.016985,0.178623,0.278159,-0.139233,-0.386488,0.262437,0.182337,0.456950,-0.398510,0.128114,0.181433,0.252572,0.429450,-0.313828,-0.145814,0.023716,0.295205,-0.145693,0.259187,0.040875,-0.065774,-0.172227,0.305523,0.210465,0.079502,-0.014674,0.191599,-0.482434,-0.371288,0.151793,-0.086715,0.114518,-0.613646,0.428820,-0.174047,0.227330,0.204910,-0.085275,0.062711,0.511711,0.338021,0.287598,0.207188,-0.032340,-0.598498,0.032996,0.392917,0.060324,-0.466962,0.368148,-0.389309,-0.702916,-0.349312,0.152477,-0.510902,0.274996,0.184888,0.092804,0.085496,0.647512,-0.293108,-0.153416,-0.563812,-0.077290,0.091501,-0.392367,0.122304,-0.574957,-0.176546,-0.022322,-0.328343,0.091621,-0.034575,-0.363967,0.570401,-0.354844,0.195221,0.439355,0.225758,-0.181270,0.808169,0.072475,0.115120,-0.455654,-0.118739,0.546079,0.257062,-0.336863,0.166312,0.271723,0.378673,-0.376519,-0.330993,0.773810', '11525673', '3179698', '2132932', '35258381');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291879', '罗生门', '剧情', '罗生门，日本京都的正南门。云游和尚、砍柴人和乞丐在城门底下避雨，三人闲聊，话题开始，故事的序幕拉开：一个武士和他妻子路过荒山，遭遇了不测。妻子被侮辱，而武士惨遭杀害。惨案如何酿成？凶手、妻子、借武士亡魂来做证的女巫，都各有说法。真相只得一个，但是各人提供证词的目的却各有不同。为了美化自己的道德，减轻自己的罪恶，掩饰自己的过失，人人都开始叙述一个美化自己的故事版本。荒山上的惨案，成了一团拨不开看不清的迷雾。谈论完毕，雨过天晴。砍柴人在罗生门旁发现一个哭泣的弃婴。他决定收养下来，抱着婴孩往夕阳深处走去。©豆瓣', '三船敏郎', '黑泽明', 8.8, 292034, 'tt0042876', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1598883511.jpg', 0.3, 0.7, 9, 38.2, 51.8, '0.590500,-0.156646,-0.336174,0.476765,-0.111051,0.011534,0.879667,0.154868,-0.344718,-0.260419,0.485441,0.685031,0.038001,0.269833,0.062523,0.015675,-0.379487,-0.587895,-0.061551,-0.263065,-0.342664,-0.419701,0.029903,-0.373895,-0.109663,0.064752,0.483017,0.184864,-0.166680,0.159794,0.334681,-0.025228,-0.402758,0.450391,-0.245576,0.114562,-0.299820,-0.027345,0.008336,0.037839,-0.402649,-0.455285,-0.353154,0.173516,-0.486886,0.514392,0.867001,-0.362023,0.073993,-0.021205,0.205654,-0.377651,0.121224,0.229880,0.382592,-0.119843,0.207456,0.017570,0.137020,-0.124989,-0.058761,0.005596,-0.371514,-0.112863,0.196281,0.337141,-0.608465,0.431700,0.010437,0.118697,0.216198,-0.427024,0.086717,-0.033246,0.202183,0.495900,-0.217109,-0.149264,-0.694209,0.203603,0.670419,-0.155853,0.089493,0.182274,-0.176491,-0.156698,-0.007169,-0.108000,-0.260639,-0.256523,0.312541,-0.127292,-0.289773,0.197013,-0.532089,-0.059293,-0.261860,-0.173785,-0.124106,-0.251325,-0.171383,-0.318515,-0.012945,0.185532,-0.149105,0.076871,0.134156,-0.282628,0.598468,-0.336027,0.142150,0.592688,0.076642,-0.353972,0.537195,-0.095256,0.372011,-0.275725,-0.200453,0.293153,0.091401,0.685799,0.103941,0.155121,-0.265715,0.158987,-0.379544,0.189343', '21619567', '1394470', '1467779', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291936', '攻壳机动队', '动作', '公元2029年，未来世界是高科技与信息化的世界。人类生活水平的提高伴随着犯罪活动的高科技化，于是，专门镇压高科技犯罪的特殊部队——公安9课成立了。队长草薙素子，作为一位全身“义体化”的女警，带领公安9课不断展开行动。是次，公安9课帮助公安6课秘密解决了一位程序员外逃他国的麻烦琐事，又卷入传说中的黑客“傀儡师”的犯罪事件。当行动陷入僵局之际，傀儡师竟然不请自来，出现在公安9课！素子与她的战友们，不知不觉地被卷入了一场涉及政府的阴谋之中。©豆瓣', '田中敦子', '押井守', 9.1, 129200, 'tt0113568', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2446408045.jpg', 0.2, 0.6, 6.9, 30.5, 61.8, '0.258344,-0.057208,-0.387269,0.379616,-0.085845,0.298403,0.131211,-0.036157,-0.497299,-0.462923,0.323077,0.188709,0.087511,0.117737,0.421418,-0.584494,-0.155268,-0.785747,0.121699,-0.155141,-0.470856,-0.357701,-0.401323,-0.507515,0.036847,-0.777597,0.791546,0.097597,-0.600625,0.255835,0.028077,0.369323,-0.222675,0.373368,-0.084370,-0.282656,0.592976,-0.107639,-0.249663,0.077576,-0.227653,-0.160098,0.004535,-0.386019,-0.101992,0.039457,0.689563,-0.245917,-0.041672,-0.513990,0.292561,-0.508765,-0.214555,-0.137322,0.809138,0.288620,0.024911,0.544003,0.163330,0.082868,-0.105874,-0.196110,-0.850910,-0.327745,0.185770,0.014076,-0.328299,0.252962,-0.031533,0.227134,-0.181783,-0.053898,0.255634,0.485574,0.476521,0.519686,0.042023,-0.015731,-0.234306,0.341152,0.464797,-0.239920,-0.372341,0.048038,-0.147647,-0.428117,-0.199635,-0.194504,-0.082064,0.099761,0.219356,-0.229200,-0.152256,0.571942,-0.818370,-0.104524,-0.149205,-0.349326,0.122160,-0.242294,-0.153688,-0.701625,0.077498,0.040652,-0.205280,0.148907,0.075083,-0.087037,0.883094,-0.865856,-0.013014,0.714062,0.184907,-0.564851,0.738704,0.113985,0.521758,-0.337127,-0.260369,-0.275919,-0.071653,0.739795,-0.008791,0.352278,-0.055887,-0.173088,-0.044741,0.004424', '3142101', '25912924', '7155241', '1920765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291937', '关于我母亲的一切', '剧情', '玛努埃拉（丝莉亚 洛芙　饰）的丈夫在儿子出生前就离开了妻子，玛努埃拉成为了单身妈妈，带着儿子埃斯特班来到马德里生活。儿子从不知道爸爸的事情，玛努埃拉只好对儿子说父亲已经过世。然而，儿子终究不相信。他在日记本里悄悄写下对父亲的想念。车祸来得那么突然，儿子被一辆迎面撞来的汽车夺走了生命。母亲悲伤不已，决定去找孩子的父亲洛拉，完成儿子心愿。然而她却得知，洛拉已经换装成女人，当了妓女，而且染上了艾滋病。更不幸的是，修女罗萨（佩内洛普 饰）怀上了洛拉的孩子。玛努埃拉留在罗萨身边照顾她，罗萨诞下的婴儿也取自己儿子埃斯特班的名字，苦难的日子终于有了希望--这个新生儿竟然逃过了艾滋的噩运。©豆瓣', '塞西莉亚·罗特', '佩德罗·阿莫多瓦', 8.6, 62847, 'tt0185125', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167231837.jpg', 0.2, 1, 11.6, 45.1, 42.2, '-0.278734,-0.279647,-0.548182,0.359030,-0.297139,-0.679768,0.752151,0.085292,-0.493576,-0.265600,0.128504,0.886917,0.063246,0.454958,0.385614,0.248463,-0.266474,-0.522384,0.288688,-0.209832,-0.406557,-0.418657,0.093148,-0.315734,0.219856,-0.370662,0.423508,-0.071421,0.369891,0.259243,0.315461,0.197483,-0.043504,0.431354,-0.430333,0.405779,-0.139476,0.082426,-0.189552,0.229012,0.322039,-0.039418,-0.039119,0.027802,0.145401,0.284196,0.590924,-0.282399,0.095810,-0.310575,0.302205,-0.253610,0.054136,0.193165,0.158796,-0.098246,0.286475,0.059817,-0.253624,-0.253053,0.100536,-0.243060,-0.283924,0.321364,0.117895,-0.058171,-0.873328,0.357863,-0.442077,0.014057,0.250067,-0.431267,0.402787,0.149462,-0.219925,0.709811,-0.456062,0.176112,-0.487228,-0.086947,0.362158,-0.433001,0.115051,0.565548,-0.161230,-0.360354,0.226099,-0.283071,-0.633914,0.248758,0.047555,0.115022,-0.372191,0.308973,-0.038510,-0.375906,-0.357325,-0.003875,0.230657,-0.419913,0.006534,0.236436,-0.092827,0.065587,-0.409546,0.112990,-0.138398,-0.251450,0.638232,-0.697961,0.394578,0.355924,0.427564,-0.656795,0.622742,0.123898,0.339686,-0.208721,0.224629,0.703033,-0.073641,0.101537,0.142016,0.041406,0.029957,-0.317181,-0.128316,0.505275', '1299965', '1292720', '1292207', '3036465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291976', '狗脸的岁月', '剧情', '20世纪50年代，小男孩英格玛（Anton Glanzelius 饰）和体弱多病的妈妈（Anki Lidén 饰）、经常欺负自己的哥哥以及心爱的小狗，住在瑞典某个平静的小镇上。他的父亲离家而去，母亲又长年为疾病所困扰。两个小男孩根本不能融洽相处，经常在家里打得沸反盈天。 不堪其扰的母亲决定将他们分别送到亲戚家寄养。如小狗一样被赶出家的英格玛，却由此见到了另一片广阔的天空……本片荣获1987年丹麦影评人奖最佳欧洲影片奖、1988年波士顿影评人社团奖最佳外语片奖、1988年金球奖最佳外语片奖、1987年西雅图国际电影节最佳影片奖、1986年瑞典金像奖最佳男主角（Anton Glanzelius）和最佳影片。©豆瓣', '安东·格兰泽柳斯', '拉斯·霍尔斯道姆', 8.5, 16320, 'tt0089606', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193057444.jpg', 0.3, 0.8, 12.5, 47.3, 39.2, '-0.206992,-0.305722,-0.534423,0.547777,0.194555,-0.261109,0.285214,0.076026,-0.591227,-0.109270,-0.020567,1.135566,-0.154956,0.553707,0.257539,0.003625,-0.355784,-0.731619,-0.284848,-0.359361,-0.033245,-0.146810,-0.348633,0.026550,-0.184968,-0.347167,0.643528,-0.246429,0.106498,0.522272,0.515875,-0.005552,-0.191063,-0.016366,-0.370223,0.092394,0.118444,0.126774,-0.579898,0.502635,-0.041075,-0.320899,-0.380541,-0.107023,0.255461,0.173267,0.607710,-0.191656,0.050099,-0.077138,0.756708,-0.349154,-0.303557,0.004317,0.416783,-0.281264,0.418699,0.016152,-0.174143,0.189826,0.164777,-0.524160,-0.315508,0.363869,0.215558,0.097922,-0.595968,0.524466,0.084884,0.170390,-0.172812,-0.122571,0.347225,0.193872,-0.042157,0.410005,-0.344176,0.110726,-0.236537,0.823360,0.529771,-0.287394,-0.314927,0.183836,-0.191014,-0.505234,0.182312,-0.598406,-0.593292,0.197810,0.461318,-0.112332,-0.107968,0.142164,-0.316755,0.114251,0.050799,-0.272470,0.006742,-0.199920,-0.089675,-0.557479,0.215626,-0.317656,-0.165840,-0.059448,0.010901,-0.050071,0.668860,-0.382065,0.679703,0.630888,0.180013,-0.229616,0.896577,0.009341,0.101640,-0.214632,-0.150767,0.314708,-0.258380,0.014621,0.008120,0.013506,-0.193904,-0.239142,-0.236589,0.359489', '1297368', '1302279', '1780122', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291990', '爱在日落黄昏时', '剧情', '九年前，杰西（伊桑·霍克 Ethan Hawke 饰）与席琳（朱莉·德尔佩 Julie Delpy 饰）在火车上不期而遇，怦然心动。在维也纳渡过疯狂而又浪漫的一夜后，他们在日出前分手，并相约在维也纳重逢。九年之后，杰西已成为畅销书作家，而席琳则是法国环保组织成员。杰西在新书里娓娓道来的，正是九年前的浪漫夜晚。在巴黎促销新书时，杰西与席琳在书店相遇，然而他们只有一下午的时光相处，日落之前，杰西要乘飞机赶回美国。两人在午后的巴黎街头散步，在美丽的护城河上泛舟，无所不谈，兴致勃勃。可是就像命运的捉弄，快乐的时光像烟花一样醉人却短暂。杰西对席琳一送再送，难以忘情；席琳用吉他和歌声，怀念着内心深处的爱恋。太阳就快落下去了，杰西就要误了飞机，又或许他更不想错过的，是命里注定的缘分。©豆瓣', '伊桑·霍克', '理查德·林克莱特', 8.9, 511996, 'tt0381681', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561542458.jpg', 0.3, 0.9, 8.8, 34.4, 55.7, '0.228482,0.026442,-0.903048,0.351331,0.359090,-0.614211,0.849030,0.148854,-0.314038,0.152598,0.154821,0.512603,-0.424869,0.583062,0.599715,0.212271,-0.637601,-0.858734,0.231138,-0.436580,-0.147390,-0.304822,-0.069600,0.075162,0.195719,-0.278375,0.341843,0.274755,0.180868,0.776035,0.238771,-0.135764,-0.284353,0.576498,-0.443211,-0.088296,0.278731,0.318044,-0.615068,0.290155,0.092702,-0.305066,-0.244657,-0.144046,0.031330,-0.001875,0.589114,-0.146313,-0.145771,0.109601,0.340740,-0.101464,-0.034828,0.091591,0.329387,0.012919,0.386365,0.080786,-0.212332,0.025155,0.049407,-0.123055,-0.346538,0.517701,-0.305920,0.101434,-0.478803,0.777343,0.041103,-0.051279,0.326873,-0.547204,0.176117,0.248764,0.237253,0.434448,-0.012908,-0.209569,-0.400018,0.382689,0.803212,0.098474,-0.246090,0.685632,-0.079443,-0.093769,0.096409,-0.052566,-0.411277,-0.024255,0.406911,-0.085836,-0.130441,0.385299,-0.657399,0.273333,-0.172250,-0.091266,0.075678,-0.133694,-0.153456,-0.790925,0.085021,-0.412529,-0.363771,0.188240,0.287638,-0.203145,0.500792,-0.793893,0.644286,0.728124,0.341825,0.054447,0.726131,0.200531,-0.171834,0.047966,0.303885,0.428850,-0.227708,0.371573,0.160755,0.523280,-0.010931,0.210173,-0.738435,0.810804', '26687241', '1309172', '11541282', '3401409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291992', '末路狂花', '剧情', '该片被认为是向男权社会发出抗争的女性主义电影代表作。生活在沉闷与琐碎家务中的家庭主妇赛尔玛（Geena Davis）与在某间咖啡厅做女侍应生的闺中密友路易丝（Susan Sarandon）对平凡的生活与工作产生厌倦后，结伴一起外出旅游散心。路上，在某家酒吧外的停车厂， 赛尔玛险遭无名男子强暴，幸好路易丝及时赶到，拔枪将该男子射杀。惊慌失措的两人掉头逃亡，自此踏上不归路，过程中两人性格均有了很重大的改变。©豆瓣', '吉娜·戴维斯', '雷德利·斯科特', 8.9, 221739, 'tt0103074', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1910924635.jpg', 0.2, 0.6, 8.3, 37.4, 53.6, '0.402475,-0.297347,-0.593674,0.210070,0.255723,-0.168841,0.817238,0.133483,-0.455014,-0.293081,0.129741,0.879257,-0.284526,0.055346,0.782456,-0.126546,-0.471990,-0.633628,-0.167327,-0.040505,-0.175105,-0.257117,0.243721,-0.257059,-0.421150,-0.382719,0.550515,-0.115586,-0.231136,0.700377,0.256658,0.331396,-0.465963,0.340361,-0.090771,0.002502,-0.025036,0.031330,-0.488349,0.176358,0.058251,-0.170989,-0.105873,-0.219793,0.269379,0.199623,0.781433,-0.104613,-0.077023,0.036846,0.286819,-0.043299,0.010959,0.184116,0.146719,0.086947,0.044733,0.338979,-0.173379,0.014618,0.065790,-0.117290,-0.184152,0.135745,0.027616,-0.031345,-0.690281,0.292230,0.216132,-0.223816,0.294397,-0.393714,0.183622,0.296285,0.374171,0.273054,0.097696,0.039623,-0.483641,0.058830,0.999032,0.388665,-0.260422,0.281367,-0.292415,-0.270338,0.005043,-0.178337,-0.560635,-0.378177,0.102038,-0.110466,-0.256801,0.365427,-0.491871,0.018743,-0.028296,-0.057803,0.126995,-0.235909,-0.365518,-0.977579,0.116550,-0.371197,-0.318679,-0.018656,-0.013363,-0.040757,0.419647,-0.999772,0.277627,0.463696,0.354106,-0.465457,0.886930,-0.208306,0.471141,-0.085134,0.086489,0.228065,0.180005,0.423245,-0.167768,0.266435,-0.406360,0.052380,-0.530475,0.266498', '26687241', '11541282', '3147969', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1291999', '重庆森林', '剧情', '编号为223的警察（金城武）失恋后患上失恋综合症，在与金发女杀手（林青霞）擦肩而过又离奇相遇并有了一晚温情后，原本以为包括“爱情”在内的所有东西都有保质期的他意外地迎来心灵的短暂温暖。可是，他们的爱情还是结束了。快餐店新来的女招待阿菲（王菲）爱上了时常光顾快餐店的编号 为663的警察（梁朝伟），因拆了他的女友（周嘉玲）留在快餐店给他的“分手” 信，阿菲知晓了他的心情，偷拿到他的钥匙趁他不在时常潜入他家，一边梦游一边悄悄地改变他的生活，终在被他撞见时令其感受到情感的回归。然而，这才是他们爱情的开始。©豆瓣', '林青霞', '王家卫', 8.8, 752767, 'tt0109424', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p792381411.jpg', 0.3, 0.8, 9.8, 38.2, 50.9, '0.520411,0.110832,-0.774226,0.368343,-0.339811,-0.321650,0.883686,0.118502,-0.330825,-0.213996,0.265162,0.654297,-0.319333,0.368564,0.334712,0.112981,-0.305292,-0.704308,0.029128,0.019310,-0.314790,-0.198536,-0.096903,-0.051214,-0.074719,-0.117636,0.538033,0.147656,-0.207593,0.321550,0.164091,0.055721,-0.019955,0.694142,-0.322609,0.374129,-0.126952,0.031912,-0.244249,0.177982,0.213135,-0.479553,-0.033653,0.236920,-0.084958,0.399847,0.806327,-0.053868,-0.212818,0.272033,0.434812,-0.199533,-0.089801,0.018155,0.149173,0.170165,0.043428,0.054416,-0.311465,0.213964,0.131173,0.135903,-0.614484,-0.041809,-0.023750,0.261661,-0.381960,0.646809,-0.207149,0.070063,0.252863,-0.330108,0.273114,0.186589,0.214370,0.431343,-0.140417,-0.073626,-0.626185,0.131945,0.803266,-0.109615,-0.004675,0.600802,-0.218979,-0.441693,-0.015931,0.016758,-0.436039,0.046182,0.292419,0.217897,-0.306537,0.152706,-0.668150,-0.089630,0.046495,-0.223570,0.043052,-0.446841,-0.132890,-0.593711,-0.253597,-0.451180,-0.425232,0.007763,0.121608,-0.302855,0.489480,-0.811456,0.406862,0.692897,0.240082,-0.521575,0.767013,0.235672,-0.035440,-0.110536,-0.207677,0.356950,0.134718,0.373876,0.224516,0.340766,-0.118713,0.062212,-0.527338,0.468750', '3055049', '1308755', '26687241', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292000', '搏击俱乐部', '剧情', '杰克（爱德华•诺顿 饰）是一个大汽车公司的职员，患有严重的失眠症，对周围的一切充满危机和憎恨。一个偶然的机会，杰克遇上了卖肥皂的商人泰勒（布拉德•皮特），一个浑身充满叛逆、残酷和暴烈的痞子英雄，并因为自己公寓失火而住进了泰勒破旧不堪的家中。两人因缘际会地成为了好朋友，并创立了“搏击俱乐部”：一个让人们不戴护具而徒手搏击，宗旨在于发泄情绪的地下组织。俱乐部吸引了越来越多的人，逐渐发展成为一个全国性的地下组织，而泰勒也以自己个人的魅力，吸引着那些盲目的信徒。俱乐部的成员们到处滋事打架、大肆破坏，泰勒本人的行为也越来越疯狂。杰克对于“搏击俱乐部”的现况及泰勒的行为越来越无法忍受，和泰勒发生争执，泰勒离开了他。然而，杰克发现，他走到何处都无法摆脱泰勒的影子，他开始思考：我到底是谁？©豆瓣', '爱德华·诺顿', '大卫·芬奇', 9, 793849, 'tt0137523', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1910926158.jpg', 0.3, 0.7, 7.1, 30.2, 61.6, '0.604779,-0.174239,-0.593811,0.475903,-0.267330,-0.233815,0.829487,0.140501,-0.429355,-0.238879,0.075718,0.915165,-0.147182,0.264090,0.252942,-0.140658,-0.143320,-0.590067,-0.127879,-0.043587,-0.094210,-0.469854,-0.251133,-0.512178,-0.090531,-0.145090,0.649148,0.148845,-0.370107,0.412639,0.405269,0.294711,0.174288,0.603623,-0.054522,-0.149125,0.205215,-0.187134,-0.003318,0.253850,0.035828,-0.177093,-0.102573,0.400635,-0.156140,0.316585,0.425200,-0.258566,-0.073939,-0.192026,0.420562,-0.295824,0.021797,0.194993,0.275230,-0.151390,-0.020196,0.061108,-0.062374,0.085067,0.019627,0.062616,-0.919041,0.045237,0.007150,0.163453,-0.572478,0.442275,0.056623,-0.133112,0.015680,-0.356222,0.130258,0.084792,0.110377,0.196721,-0.224506,-0.052088,-0.603702,-0.010600,0.709536,-0.087184,-0.237435,0.141204,-0.419349,-0.359832,-0.096254,-0.199208,-0.568279,-0.281921,0.463170,-0.003409,-0.145109,0.216515,-0.726777,0.136958,-0.207446,-0.496231,-0.187635,-0.436387,0.020240,-0.739607,-0.214607,-0.469887,-0.208733,-0.059369,0.047444,-0.207794,0.681891,-0.994910,0.002463,0.784299,0.200768,-0.543958,0.399560,-0.031653,0.148009,-0.023162,-0.486906,0.290591,0.250504,0.302723,0.169048,0.521162,-0.032362,-0.083809,-0.079009,0.539723', '1793491', '3769423', '25828589', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292001', '海上钢琴师', '剧情', '本片讲述了一个钢琴天才传奇的一生。1900年，Virginian号豪华邮轮上，一个孤儿被遗弃在头等舱，由船上的水手抚养长大，取名1900（蒂姆•罗斯 饰）。1900慢慢长大，显示出了无师自通的非凡钢琴天赋，在船上的乐队表演钢琴，每个听过他演奏的人，都被深深打动。爵士乐鼻祖杰尼听说了1900的高超技艺，专门上船和他比赛，最后自叹弗如，黯然离去。可惜，这一切的事情都发生在海上，1900从来不愿踏上陆地，直到有一天，他爱上了一个女孩，情愫在琴键上流淌。他会不会为了爱情，踏上陆地开始新的生活，用他的琴声惊艳世界？他将怎样谱写自己非凡的人生。©豆瓣', '蒂姆·罗斯', '朱塞佩·托纳多雷', 9.3, 1575259, 'tt0120731', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2574551676.jpg', 0.2, 0.4, 4.4, 24.3, 70.7, '0.206876,0.215279,-0.746208,0.719308,-0.209233,-0.229358,0.680592,-0.126940,-0.507383,-0.172130,0.470608,0.941572,0.028105,0.306577,0.289069,0.061607,-0.259909,-0.759603,0.206792,-0.211114,-0.329007,-0.368766,-0.042315,-0.047931,0.019004,-0.335663,0.577872,0.037240,0.059680,0.519259,0.237180,-0.042664,0.069499,-0.001527,-0.501208,0.023045,0.071192,0.270387,0.110333,-0.199864,-0.427280,-0.420909,0.028429,-0.111481,-0.260135,-0.146436,0.884527,-0.138611,0.078898,-0.031940,0.250681,-0.243197,0.088598,-0.021986,0.052947,0.203738,-0.106048,0.337398,-0.195516,-0.173235,-0.267485,0.088235,-0.755388,-0.298240,-0.060880,0.107512,-0.666281,0.452826,-0.105559,-0.258410,-0.208810,-0.274403,0.185696,-0.130877,0.408262,0.400796,-0.073771,0.181401,-0.384658,0.397075,0.822555,0.032114,-0.185577,0.452198,-0.112863,-0.425954,-0.124513,-0.521742,-0.510577,0.104084,0.199431,0.022757,-0.186871,0.049932,-0.600217,0.289556,-0.022597,-0.448436,0.073337,-0.497782,-0.250030,-0.492791,0.018815,-0.400027,-0.404031,-0.028703,-0.040472,-0.393708,1.187082,-0.773528,0.356878,0.486392,-0.120689,-0.186302,0.925551,0.030068,-0.056809,-0.198305,0.054047,0.497224,-0.202420,0.209093,-0.127613,0.490761,-0.119941,0.357595,-0.648302,0.765839', '30162520', '3811356', '27602116', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292047', '蓝白红三部曲之红', '剧情', '女学生瓦伦丁（伊莲娜·雅各布 Irène Jacob饰）是个兼职模特，男朋友远在英国。尽管她非常珍惜这段感情，却无法阻止男友对自己的猜忌。退休法官（简-路易斯·特林提格南特 Jean-Louis Trintignant饰）年轻时经历过铭心刻骨的情伤，爱人的背叛让他不再相信这个世界。唯一的乐趣，就是窃听邻居的电话，看人与人之间是如何充满欺骗。认识瓦伦丁之后，他冰封多年的情感开始融化。法律系学生奥古斯特（简·皮埃尔·洛里 Jean-Pierre Lorit饰）前程锦绣，却不得不面对恋人感情的出轨。他决定前往英国一段时间，以摆脱痛苦的心情，在客轮上遇到了同往英国寻找男友的瓦伦丁。轮船遇到强对流天气，暴风雨过后电视新闻上播放着轮船遇险的消息。一百多人罹难的同时，瓦伦丁和奥古斯丁双双幸存，他们觉得对方似曾相识……©豆瓣', '伊莲娜·雅各布', '克日什托夫·基耶斯洛夫斯基', 8.7, 110942, 'tt0111495', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173726043.jpg', 0.2, 0.7, 10, 40.2, 48.9, '0.252395,-0.183990,-0.665066,0.574286,-0.216990,-0.259928,0.815915,-0.096074,-0.740950,-0.407572,0.012652,0.720204,-0.349490,0.428856,0.288924,0.025068,-0.325948,-0.643422,0.060414,-0.032580,-0.259521,-0.579486,-0.314680,-0.215738,0.031520,-0.333499,0.529449,0.202300,-0.131304,0.380527,0.191187,0.338081,-0.007586,0.604574,-0.007375,-0.038841,0.069674,0.249986,-0.527736,-0.073999,0.068207,-0.105943,-0.102865,0.111897,0.005399,0.346381,0.424999,-0.012028,-0.223751,-0.042973,0.186303,-0.288653,0.003972,0.029805,0.231289,0.039011,0.106086,0.194667,-0.102349,-0.243981,-0.060999,0.149631,-0.320451,0.162460,0.011783,0.166785,-0.284868,0.418887,-0.331232,0.075588,-0.105836,-0.452125,0.033852,0.090628,0.267540,0.432432,-0.206223,0.124301,-0.455008,0.154390,0.988849,0.160837,-0.271064,0.218057,-0.276659,-0.368829,-0.006725,-0.197016,-0.580019,0.073622,0.169940,0.028505,-0.231319,0.243126,-0.363255,-0.122274,-0.305401,-0.071309,-0.023765,-0.418615,-0.020329,-0.638356,-0.146533,-0.553598,-0.441380,0.076344,0.100407,-0.375085,0.631376,-0.837861,0.320765,0.600045,0.410513,-0.472358,0.697922,0.395020,-0.058048,-0.424922,0.004505,0.584816,-0.175232,0.000802,0.131776,0.040123,-0.057864,-0.002387,-0.270509,0.577779', '25721544', '1308755', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292048', '蓝白红三部曲之蓝', '剧情', '这么多年来，朱莉（朱丽叶·比诺什 Juliette Binoche饰）一直默默支持丈夫的创作事业，照顾5岁的孩子，平静的生活由一场车祸打破。丈夫和女儿的过世，令刚刚在病床上醒来的朱莉大为悲痛。她曾经想一死了之，出院后又生归隐之心，她把丈夫的曲谱付之一炬，以明隔离过往的决心。人间生活对于万念俱灰的朱莉来说，已经无关紧要。然而，现实却防不胜防地进入她的生活，让她开始思考自己对待生活的态度。同时，丈夫的朋友把丈夫留下的残稿发表在媒体上，声称要为这首曲续完。这件事意外地让朱莉得知，曲子原来跟一个女人有关。这个女人，肚中已怀有丈夫的骨肉。朱莉终于获得了心灵的自由，有勇气迎接新的生活和新的感情，她的人生开始转变。©豆瓣', '朱丽叶·比诺什', '克日什托夫·基耶斯洛夫斯基', 8.5, 123948, 'tt0108394', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1978408096.jpg', 0.2, 1, 12.9, 45.6, 40.2, '0.134458,0.009240,-0.694720,0.732243,-0.357859,-0.413228,0.762858,0.102564,-0.695403,-0.381780,0.145380,0.799148,-0.135203,0.615561,0.271025,0.010608,-0.371878,-0.922240,0.003651,0.118003,-0.208635,-0.379480,0.035905,-0.262904,-0.215858,-0.156184,0.796379,-0.005032,0.059339,0.310240,0.143130,0.287169,0.232334,0.448554,-0.192843,0.057885,-0.223914,0.360139,-0.493749,0.004498,0.202311,-0.155541,-0.054829,0.475688,-0.081897,0.250782,0.765924,-0.160035,-0.316333,-0.135089,0.674268,-0.198652,0.020429,0.211030,0.022271,0.246395,0.174546,0.275511,-0.342733,-0.197563,-0.013480,-0.098304,-0.697192,-0.180778,0.092024,-0.065252,-0.686562,0.462213,-0.136473,0.166062,0.142638,-0.246285,0.275187,0.615340,0.214314,0.738153,-0.385291,0.119027,-0.237452,0.179011,0.836777,-0.293382,-0.061566,0.535424,-0.340440,-0.263666,0.113770,-0.136760,-0.657862,-0.074080,-0.145269,0.251584,-0.414110,0.481960,-0.451011,0.027110,-0.225968,-0.100468,0.250240,-0.617733,-0.081756,-0.252156,-0.383823,-0.272232,-0.365902,-0.104251,0.050637,-0.557983,0.899872,-0.820370,0.292591,0.222341,0.229290,-0.812350,0.681364,0.412048,0.177489,-0.369679,0.207943,0.673462,-0.331135,0.098193,-0.102175,0.053917,0.105896,0.175846,-0.498119,0.599844', '1296569', '4861627', '35287908', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292049', '蓝白红三部曲之白', '剧情', '卡罗尔（泽比纽·扎马洲斯基 Zbigniew Zamachowski饰）藏在妻子多明尼（朱丽·德尔比 Julie Delpy饰）的行李箱中，从波兰偷渡到了法国。天堂般的生活并没有如愿展开，换来的是卡罗尔心中巨大的生活压力。他甚至失去了性能力，被多明尼赶出家门。带着妻子有了外遇的惨痛心情，还有一张美发师证书。卡罗尔决心回到波兰经营事业，再卷土重来。历尽波折的卡罗尔终于回到自己的国土。他积极上进，忙于谋生，竟在房地产生意中打了漂亮的翻身仗，一举成为百万富翁。此时的他，以为可以让多明尼回到身边，然而妻子的拒绝却令他的自尊大为受伤。于是，卡罗尔决定用一场阴险的计谋，狠狠给妻子一个报复。然而当卡罗尔得逞后，他又能换来什么呢？©豆瓣', '泽比纽·扎马洲斯基', '克日什托夫·基耶斯洛夫斯基', 8.4, 97291, 'tt0111507', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1604838524.jpg', 0.2, 0.8, 13.6, 49.6, 35.8, '-0.036075,0.131310,-0.717302,0.506065,-0.146647,-0.646599,0.738700,0.116801,-0.504799,-0.073323,0.054753,0.715245,-0.083353,0.209351,0.150624,-0.066442,-0.282702,-0.681546,0.136131,-0.165037,-0.099263,-0.336648,-0.377495,-0.128084,-0.194795,-0.176851,0.554682,0.130995,-0.141492,0.267178,0.257015,0.194716,0.221153,0.560949,-0.280313,0.163431,-0.147717,-0.040072,-0.348980,0.450541,0.219431,-0.112364,-0.175575,0.273055,0.044946,0.194164,0.608502,-0.193430,-0.097126,-0.162949,0.308835,-0.172853,-0.143956,0.397377,-0.052805,0.135074,0.072065,-0.033233,-0.455421,0.147068,0.403877,-0.289331,-0.710993,-0.089617,-0.246676,0.006440,-0.845216,0.371625,-0.230783,-0.007661,0.132237,-0.331665,0.108191,0.336417,0.148828,0.535509,-0.299477,0.405897,-0.500514,-0.091740,0.694955,-0.148815,0.042347,0.310789,-0.056177,-0.222861,0.207341,-0.461835,-0.327913,-0.149710,0.431852,0.004735,-0.026457,0.225093,-0.529375,0.022895,-0.530693,-0.173372,0.047125,-0.423942,-0.030661,-0.303896,-0.215220,-0.213396,-0.290102,0.259102,0.052581,-0.373065,0.492934,-0.872236,0.215959,0.379705,0.464185,-0.393408,0.230402,0.183829,0.331214,0.169053,-0.039509,0.426556,-0.052684,0.357744,0.053557,0.195030,-0.011865,-0.223559,-0.068260,0.604468', '1299965', '1301022', '30345227', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292050', '洛基恐怖秀', '喜剧', '布莱德（Barry Bostwick 饰）和珍妮（苏珊·萨兰登 Susan Sarandon 饰）是一对儿互相爱慕的年轻人，生性羞涩的两人，借着参加一场朋友的婚礼，终于互诉衷肠，约定了终身。为了表示对连接起两人缘分的授业教授的感谢，二人驱车前往拜访，不料半路遭遇暴风雨 ，湿透的两人在夜色中无处落脚，只好向路边一座荒僻古堡求助。谁知古堡中正上演着一场异色的狂欢表演！古堡主人——福特博士（Tim Curry 饰）是一名自称来自变性星球的异装癖，他和仆人与支持者们纵情狂欢，在布莱德二人面前展示了唤醒人造人洛基的奇迹。当天夜里，被分开的布莱德和珍妮各自经历了性的体验，二人的思想起了细微变化，在后续的一系列事件中和福特博士的关系愈发复杂……©豆瓣', '蒂姆·克里', '吉姆·沙曼', 8.1, 22891, 'tt0073629', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p470502950.jpg', 1.3, 3.7, 20.1, 38.6, 36.2, '0.467948,-0.170708,-0.689438,0.496239,0.146101,-0.191156,0.816514,0.099740,-0.498513,-0.183395,0.286456,0.827401,-0.542685,0.224546,0.574931,-0.032554,-0.464450,-0.735657,-0.182538,-0.135635,-0.061465,-0.520168,-0.195988,-0.032103,0.032549,-0.441881,0.384824,0.009394,-0.155711,1.012631,0.392962,0.169830,-0.530878,0.407527,-0.114999,-0.135895,0.235432,0.182511,-0.646063,0.178308,-0.088151,-0.237572,-0.209360,0.076089,-0.052610,0.334588,0.841823,-0.435478,-0.067205,-0.009436,0.161492,-0.142322,0.171076,0.353045,0.342595,0.107438,0.265184,0.327170,-0.091903,-0.067945,0.061653,-0.082183,-0.346291,0.184418,0.146235,0.203852,-0.571909,0.611513,0.121747,-0.267222,0.098301,-0.314500,0.300844,0.198159,0.253352,0.464625,-0.112123,-0.136167,-0.338453,-0.025630,0.683299,0.192399,0.078679,0.229219,-0.207258,-0.393049,-0.020217,0.175436,-0.515086,-0.161741,0.391849,-0.029341,-0.159772,0.397727,-0.913065,0.010640,-0.317811,-0.180120,0.052615,-0.477673,-0.004337,-1.105898,-0.053686,-0.269261,-0.254695,0.097859,0.031373,-0.069948,0.480903,-0.782453,0.200645,0.342323,0.200891,-0.133110,0.763321,0.030368,0.156960,-0.237889,0.019749,-0.056543,-0.070084,0.218796,0.231601,0.553168,-0.156241,0.226093,-0.527154,0.380731', '11541282', '3147969', '10466639', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292052', '肖申克的救赎', '剧情', '一场谋杀案使银行家安迪（蒂姆•罗宾斯 Tim Robbins 饰）蒙冤入狱，谋杀妻子及其情人的指控将囚禁他终生。在肖申克监狱的首次现身就让监狱“大哥”瑞德（摩根•弗里曼 Morgan Freeman 饰）对他另眼相看。瑞德帮助他搞到一把石锤和一幅女明星海报，两人渐成患难 之交。很快，安迪在监狱里大显其才，担当监狱图书管理员，并利用自己的金融知识帮助监狱官避税，引起了典狱长的注意，被招致麾下帮助典狱长洗黑钱。偶然一次，他得知一名新入狱的小偷能够作证帮他洗脱谋杀罪。燃起一丝希望的安迪找到了典狱长，希望他能帮自己翻案。阴险伪善的狱长假装答应安迪，背后却派人杀死小偷，让他唯一能合法出狱的希望泯灭。沮丧的安迪并没有绝望，在一个电闪雷鸣的风雨夜，一场暗藏几十年的越狱计划让他自我救赎，重获自由！老朋友瑞德在他的鼓舞和帮助下，也勇敢地奔向自由。本片获得1995年奥斯卡10项提名，以及金球奖、土星奖等多项提名。', '蒂姆·罗宾斯', '弗兰克·德拉邦特', 9.7, 2692570, 'tt0111161', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p480747492.jpg', 0.1, 0.1, 1.2, 12.8, 85.8, '-0.171123,0.063917,-0.402223,0.542473,-0.246657,-0.266285,0.554107,0.035886,-0.304339,-0.201004,0.217725,0.740058,-0.100616,0.217417,0.164226,-0.134472,-0.368481,-0.608006,0.010253,-0.050355,-0.150352,-0.511139,-0.324395,-0.192853,-0.159232,-0.402811,0.648615,0.179077,-0.108447,0.427023,0.320762,0.230932,0.074435,0.365048,-0.091148,-0.065436,0.357872,0.089167,-0.467392,0.370354,0.064269,-0.251522,-0.188191,0.261215,-0.014776,0.186804,0.372364,-0.179198,-0.190117,0.039686,0.372041,-0.500553,0.112519,0.117946,0.014157,-0.195816,-0.071658,0.491960,-0.255209,-0.029812,0.157517,-0.058223,-0.822248,-0.204147,0.052598,-0.062977,-0.431439,0.200663,-0.230873,0.347803,0.064599,0.097539,0.044146,0.240662,0.123091,0.399757,-0.286667,0.123705,-0.595113,0.357898,0.375672,-0.433481,-0.142494,0.063794,-0.086029,-0.321207,0.155623,-0.035412,-0.273686,-0.051272,0.603406,-0.257509,-0.179503,0.188124,-0.246360,-0.326142,-0.601045,-0.015962,0.033963,-0.462795,0.181444,-0.571422,-0.237886,0.301352,-0.164478,-0.146274,0.102376,-0.619601,0.350728,-0.505805,0.304725,0.575571,0.284429,-0.509318,0.578004,0.244990,0.171076,-0.307987,-0.082265,0.147644,0.571463,0.284179,0.213447,0.133315,0.099932,-0.103813,-0.285978,0.275402', '4206468', '27073234', '3785918', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292055', '再见列宁', '剧情', '克里斯蒂娜（凯萨琳·萨斯 Kathrin Sass 饰）衷心拥护着社会主义东德，她的丈夫已经逃往西德，剩下她一人抚养一对儿女阿丽安娜（玛丽亚·西蒙 Maria Simon 饰）和阿历克斯（丹尼尔·布鲁赫 Daniel Brühl 饰）。1989年，阿历克斯上街游行被捕，母亲目睹了这一幕，心脏病发晕倒过去，不省人事了好一段时间。 当她醒来，她熟悉的国家已经改变——柏林墙推倒，民主德国的社会主义也随之瓦解。医生说，克里斯蒂娜不能再受刺激了。于是儿子想方设法营造一个过往的世界给母亲。母亲因此得以活在过去的民主德国里：包括邻居的衣饰，电视的新闻，换成苏联食品的罐头。然而，阿历克斯用心良苦不可能掩饰庞大的现实世界。终于，儿子以自己的方式去和母亲讲述东德的变迁。©豆瓣', '丹尼尔·布鲁赫', '沃尔夫冈·贝克', 8.8, 80178, 'tt0301357', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p478546260.jpg', 0.1, 0.5, 8.5, 41, 49.9, '0.002325,0.094971,-0.643054,0.572269,-0.062765,-0.596095,0.712649,0.101496,-0.370207,-0.176648,0.115311,0.505763,0.180061,0.258799,0.405666,0.149710,-0.575083,-0.624146,0.029236,-0.076862,-0.279757,-0.372082,-0.198437,-0.531967,-0.100495,-0.369694,0.424032,-0.305317,-0.067669,0.183948,0.294352,0.219674,0.187492,0.334647,0.065709,0.357359,-0.003669,-0.175121,-0.480033,-0.078990,0.163677,-0.081324,-0.135558,0.346660,-0.010110,0.029948,0.624267,-0.352267,0.090211,-0.262030,0.512860,-0.018274,-0.062881,0.154541,0.177531,-0.116693,0.153463,0.017856,-0.162884,-0.210684,0.071445,0.146648,-0.269663,-0.030132,-0.073569,0.098375,-0.638661,0.421273,-0.253280,0.034664,0.051831,-0.403644,0.063863,0.472089,0.162807,0.678419,-0.127231,0.040612,-0.487928,0.332416,0.451611,-0.148747,-0.353313,0.416674,-0.350353,-0.130719,-0.129728,-0.136239,-0.679334,-0.064138,0.373530,-0.221227,-0.380626,0.525661,-0.294217,-0.261301,-0.440031,-0.431380,0.183137,-0.217675,0.064295,-0.326586,-0.273959,-0.221046,-0.330816,-0.094475,-0.048158,-0.099419,0.733519,-0.240075,0.124635,0.525255,0.317343,-0.325034,0.617485,-0.102926,0.213265,-0.264011,0.004524,0.420774,0.007293,0.167631,0.293584,0.332650,0.181291,0.179859,-0.375127,0.422976', '26348103', '1292831', '4066127', '1310167');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292056', '蝴蝶', '剧情', '丽莎（柯莱儿布翁尼许Claire Bouanich 饰），今年8岁，单亲，喜欢提问，各种各样童稚的问题。邻居的爷爷（米歇尔•塞罗 Michel Serrault 饰 ），儿子已经去世，脾气古怪，有收集蝴蝶标本的癖好。一天，丽莎闯进了爷爷的密室，发现了五彩斑斓的蝴蝶标本。爷爷还说，他要到山上去采集一个叫“伊莎贝拉”的蝴蝶，丽莎大喜，要跟爷爷一起去探险，她多么希望跟着爷爷去看满天飞的蝴蝶。一路上，丽莎给爷爷添了不少麻烦，因为她有问不完的问题，还放走了爷爷采来的蝴蝶。丽莎掉进了一个山洞，爷爷着急，找来了救生人员。两人的友谊、亲情，与美丽的大自然融为一体。©豆瓣', '米歇尔·塞罗尔', '费利普·弥勒', 8.6, 114611, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2464686077.jpg', 0.1, 0.5, 11.2, 45.4, 42.8, '0.257353,-0.202338,-0.499825,0.263458,-0.348137,-0.561774,0.732597,0.121993,-0.394792,-0.106771,-0.004721,0.566033,-0.116034,0.108981,0.023648,0.518627,-0.271461,-0.195250,0.327237,-0.197572,-0.200579,-0.562418,-0.003368,0.015264,0.320180,-0.344670,-0.036775,-0.354931,0.198746,0.636425,0.082544,0.032281,-0.134606,0.282248,-0.279927,0.323228,0.047677,0.181630,-0.112762,0.121726,0.202433,0.169153,-0.016195,-0.023997,0.198369,0.115468,0.471492,-0.005996,-0.034318,-0.004078,0.241317,-0.020880,0.208882,0.220044,0.490274,-0.093195,0.290181,0.014844,-0.326251,0.131592,-0.050667,-0.003875,-0.262179,0.154382,0.090243,0.341313,-0.746948,0.224813,0.065109,-0.302355,0.394633,-0.598771,0.317652,0.204199,-0.049945,0.489140,-0.100530,-0.044683,-0.461119,0.121282,0.478139,-0.330834,0.369748,0.443991,-0.132859,-0.028008,0.111610,0.136170,-0.331034,0.199764,0.373614,-0.158283,-0.524132,-0.034028,-0.865730,-0.087069,-0.216759,-0.255841,-0.027876,-0.365824,-0.165976,-0.122354,-0.014188,-0.204814,-0.239506,-0.043772,0.134588,-0.070143,0.815860,-0.456216,0.403120,0.523088,0.286630,-0.305619,0.486146,-0.035825,-0.236503,-0.196067,0.038036,-0.265190,0.052779,0.445623,0.241022,0.422385,0.357061,-0.440734,-0.438405,-0.126531', '1293175', '25731805', '1309101', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292060', '米勒的十字路口', '剧情', '美国一个小城市，当地的黑帮老大利奥和他的好朋友兼助手汤姆（加布里埃尔•伯恩 Gabriel Byrne 饰）同时爱上了黑道中人伯尼（约翰•特托罗 John Turturro 饰）的妹妹维娜（马西娅•盖伊•哈登 Marcia Gay Harden 饰），两个好朋友甚至为争夺维娜的爱的而反目。同时，当地的另一个黑帮老大卡斯帕极力拉拢汤姆，答应帮他偿还赌债，条件就是干掉伯尼。汤姆为了讨维娜的欢心，暗中帮助伯尼藏了起来，对卡斯帕却宣称自己已经杀死了伯尼。不料伯尼反咬一口，以此威胁汤姆帮他干掉卡斯帕，不然就重新露面。局面霎时变得混乱起来。©豆瓣', '加布里埃尔·伯恩', '乔尔·科恩', 7.8, 10945, 'tt0100150', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363356206.jpg', 0.5, 2.5, 24.9, 49.7, 22.4, '0.068923,0.057466,-0.266409,0.562502,-0.385721,-0.628872,0.440149,0.404018,-0.199430,-0.030919,0.044444,0.725562,0.219336,0.179905,0.227280,0.284573,-0.374797,-0.665151,0.172829,0.037109,-0.213244,-0.581187,-0.382516,-0.575032,-0.144930,-0.309248,0.275956,-0.214396,-0.058035,0.291656,0.487966,0.317253,0.291196,0.244060,0.053597,0.108077,0.199041,-0.472748,-0.560628,0.177777,-0.124376,0.035734,-0.176511,0.346802,0.188653,0.443806,0.279737,0.048696,0.142705,-0.221028,0.111844,-0.351528,0.133558,-0.091025,0.128873,-0.274609,0.441744,0.140957,-0.333947,-0.283589,0.199324,0.005953,-0.747220,0.414814,0.051872,0.009515,-0.530199,0.140957,-0.374918,0.061243,0.149266,-0.078093,-0.052436,0.502316,0.071501,0.101224,-0.236972,0.109624,-0.440623,-0.077826,0.510365,-0.148302,0.094984,-0.066263,-0.095490,-0.124618,0.133294,-0.151156,-0.170752,-0.302451,0.430635,-0.509923,0.060588,0.295529,-0.459373,-0.479912,-0.553456,0.044843,0.045518,-0.542490,0.089932,-0.430875,-0.240349,0.171860,-0.074182,0.004613,0.127938,-0.053267,0.720077,-0.637452,0.180476,0.717845,0.373827,-0.478863,0.337248,0.347653,0.206938,-0.242544,-0.227256,-0.014215,0.350406,-0.051242,0.326605,0.023769,0.217630,-0.256465,-0.119156,0.438904', '5973984', '26678784', '3785918', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292062', '美国丽人', '剧情', '莱斯特（凯文·史派西 Kevin Spacey 饰）跟许多中年男人一样，遇到了各种各样的人生难题。他在一个广告公司工作，成绩平平，但是妻子却比他混得出色，一派女强人作风。这个平凡的男人还有一个未成年的女儿珍妮（索拉·伯奇 Thora Birch饰）。珍妮性格叛逆，被邻居偷拍裸照还觉得很好玩，满不在乎。她有一个要好的同学安吉拉（米娜·苏瓦丽 Mena Suvari 饰），当莱斯特在拉拉队的人群中看到了充满青春活力的安吉拉，一切都改变了。莱斯特陷入了阿安吉拉年轻鲜活的气息当中。他死气沉沉的心境有了燃烧的感觉。而此时，他的妻子，也和另外一个富商有了私情。当莱斯特得到了他心目中的年轻女神，枪声也随之响起……©豆瓣', '凯文·史派西', '萨姆·门德斯', 8.5, 315926, 'tt0169547', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1309847196.jpg', 0.2, 0.8, 12.8, 44.5, 41.7, '0.355883,-0.026224,-0.530630,0.662254,-0.431421,-0.362593,1.148439,0.298445,-0.429658,-0.334601,0.053166,0.944681,-0.276085,0.220577,0.193059,0.142104,-0.326088,-0.654289,-0.068802,-0.008269,-0.005392,-0.282510,-0.315598,-0.161245,-0.178559,-0.335474,0.529680,-0.262283,-0.087536,0.482481,0.306563,0.110425,0.274932,0.542410,-0.320648,0.162150,0.137291,-0.026873,0.178395,0.097825,0.024938,-0.010182,-0.050271,0.249489,-0.085987,0.395656,0.636981,-0.027329,-0.075039,0.116242,0.461776,0.072973,-0.048111,0.296446,0.230202,-0.153293,0.014293,-0.125489,-0.173553,-0.317048,0.072130,-0.060935,-0.682499,0.003755,-0.011722,0.429575,-0.395167,0.484616,-0.024653,-0.136342,0.338414,-0.221774,0.186351,0.036120,0.147731,0.404918,-0.103381,0.022055,-0.676336,0.021848,0.632477,0.256602,-0.437556,0.614175,-0.700998,-0.523598,-0.007500,-0.091685,-0.701835,-0.051141,0.388952,-0.255883,-0.126838,0.217891,-0.561841,0.141470,-0.097179,-0.059844,-0.423045,-0.458598,-0.298963,-0.430646,-0.430538,-0.642150,-0.508728,0.007175,-0.092249,-0.100937,0.992469,-1.100324,0.037339,0.602069,0.127569,-0.271274,0.684736,0.211306,0.079861,-0.099871,-0.216069,0.218981,-0.041751,0.080601,0.026663,0.608539,-0.210952,-0.378917,-0.422827,0.685896', '4275444', '1309161', '24756472', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292063', '美丽人生', '剧情', '犹太青年圭多（罗伯托·贝尼尼）邂逅美丽的女教师多拉（尼可莱塔·布拉斯基），他彬彬有礼的向多拉鞠躬：“早安！公主！”。历经诸多令人啼笑皆非的周折后，天遂人愿，两人幸福美满的生活在一起。然而好景不长，法西斯政权下，圭多和儿子被强行送往犹太人集中营。多拉虽没有犹太血统，毅然同行，与丈夫儿子分开关押在一个集中营里。聪明乐天的圭多哄骗儿子这只是一场游戏，奖品就是一辆大坦克，儿子快乐、天真的生活在纳粹的阴霾之中。尽管集中营的生活艰苦寂寞，圭多仍然带给他人很多快乐，他还趁机在纳粹的广播里问候妻子：“早安！公主！”法西斯政权即将倾覆，纳粹的集中营很快就要接受最后的清理，圭多编给儿子的游戏该怎么结束？他们一家能否平安的度过这黑暗的年代呢？©豆瓣', '罗伯托·贝尼尼', '罗伯托·贝尼尼', 9.6, 1241058, 'tt0118799', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2578474613.jpg', 0.1, 0.2, 2.2, 17, 80.6, '-0.028868,0.111842,-0.480182,0.336102,-0.084903,-0.392825,0.663707,0.111128,-0.401427,-0.076077,0.433029,0.605315,-0.000120,0.138788,0.294810,0.074443,-0.569249,-0.407063,-0.197705,0.047507,-0.210700,-0.311040,-0.176695,-0.085784,-0.021698,-0.164778,0.495366,0.081671,0.201601,0.276648,0.140888,0.141819,-0.228030,0.234515,-0.311752,0.198125,0.326271,0.001432,-0.519606,0.103787,-0.165003,0.059794,-0.182483,-0.087727,-0.042905,-0.002437,0.530163,-0.328103,0.223160,-0.266449,0.195352,-0.199217,-0.215254,0.300682,0.024992,-0.087003,0.324297,0.193432,-0.019986,-0.162121,-0.100927,-0.158490,-0.501836,0.074269,0.003571,0.031120,-0.369032,0.602810,-0.045007,-0.017268,0.200752,-0.256110,-0.012901,0.400236,0.231258,0.630517,-0.198214,0.202443,-0.348916,0.214509,0.692865,-0.070624,-0.362008,0.261689,-0.324304,-0.215449,0.305059,-0.307767,-0.651502,-0.134358,0.251195,-0.218588,-0.292397,0.586330,-0.594744,0.072456,-0.431269,-0.088755,0.323609,-0.360444,-0.112357,-0.447708,-0.101455,-0.198123,-0.194905,0.061729,0.200042,-0.101851,0.780564,-0.669041,0.358504,0.539072,0.242623,-0.259550,0.457919,0.349210,0.288167,0.040808,-0.006219,0.465824,0.019559,0.397919,-0.065882,0.334130,-0.145039,-0.165515,-0.249611,0.385362', '27040921', '10533913', '1292720', '1460341');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292064', '楚门的世界', '剧情', '楚门（金•凯瑞 Jim Carrey 饰）是一个平凡得不能再平凡的人，除了一些有些稀奇的经历之外——初恋女友突然失踪、溺水身亡的父亲忽然似乎又出现在眼前，他和绝大多数30多岁的美国男人绝无异样。这令他倍感失落。他也曾试过离开自己生活了多年的地方，但总因种种理由而不能成行。直到有一天，他忽然发觉自己似乎一直在被人跟踪，无论他走到哪里，干什么事情。这种感觉愈来愈强烈。楚门决定不惜一切代价逃离这个他生活了30多年的地方，去寻找他的初恋女友。但他却发现自己怎样也逃不出去。真相其实很残忍。©豆瓣', '金·凯瑞', '彼得·威尔', 9.3, 1556361, 'tt0120382', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p479682972.jpg', 0.1, 0.2, 3.4, 25, 71.4, '0.219138,-0.123408,-1.014610,0.417523,-0.326161,-0.227962,0.845637,-0.278888,-0.799101,-0.648658,0.167714,0.978288,-0.078386,0.360764,-0.139872,0.352513,-0.066055,-0.532888,0.224659,-0.297315,-0.454627,-0.238688,-0.379564,-0.299829,0.015055,-0.013015,0.530739,0.330832,-0.102925,0.162691,0.270724,0.177591,0.024391,1.071745,-0.141588,-0.023053,-0.022035,0.324287,0.122888,-0.046582,0.299760,-0.570335,-0.455045,0.458505,-0.292586,0.426067,0.291750,-0.051891,-0.605914,0.294144,0.353572,-0.362514,-0.259891,0.010271,-0.035075,-0.284258,0.039638,0.173482,-0.322580,-0.069129,-0.098518,0.165776,-0.694238,0.164505,-0.024000,0.356767,-0.645750,0.095450,-0.163561,-0.029845,0.025599,-0.486690,0.228044,0.249807,0.334671,0.258358,-0.403046,-0.162574,-0.504720,0.062211,1.265077,0.053895,-0.293187,0.285321,-0.224948,-0.359350,-0.271405,-0.235957,-0.359042,0.133351,0.036471,0.205758,-0.655149,0.191211,-0.237741,0.292586,-0.240376,-0.108070,-0.200992,-0.323891,-0.043946,-0.047162,-0.192344,-0.561329,-0.516511,0.103483,-0.091612,-0.503916,0.396267,-0.819283,0.294734,0.665227,0.305537,-0.741844,0.628142,0.256171,-0.311843,-0.169517,-0.035890,0.500228,-0.144364,0.288408,0.186834,0.103312,0.055167,0.003460,-0.290551,0.608612', '26718282', '25721544', '1309116', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292065', '疤面煞星', '剧情', '古巴难民青年托尼（阿尔•帕西诺 Al Pacino 饰）逃难来到了美国的迈阿密，成了一个典型的天不怕、地不怕的美国街头小混混。托尼在当地的一个毒枭手下干活，因其心狠手辣、胆大心细，十分出色地帮老大完成了几件任务而迅速受到赏识，成为毒枭的第一得力助手。然而托尼并没有就此满足，他先是从委内瑞拉的毒枭那里接下了大单子，接着将自己的眼中钉一颗颗除去，势力不断扩大。当他的老大感受到威胁时已经太晚了，托尼将老大干掉然后一统了迈阿密毒品市场的天下。托尼得势后他的性格开始变得疑神疑鬼，对周围的人甚至至亲的家人、好兄弟都充满怀疑。疑心使他逐渐走上了不归路！©豆瓣', '阿尔·帕西诺', '布莱恩·德·帕尔玛', 8.3, 73742, 'tt0086250', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198951636.jpg', 0.3, 1.3, 15.2, 47.2, 36, '0.358284,0.116032,-0.610656,0.444864,-0.363510,-0.394023,0.518437,0.238435,-0.571117,0.229296,0.220201,0.896927,-0.002191,-0.053835,0.236226,-0.043043,-0.102483,-0.735790,-0.269896,-0.150779,-0.259174,-0.350722,-0.371717,-0.378695,-0.222025,-0.225424,0.477009,0.139901,-0.069660,0.443337,0.222961,0.096531,0.350444,0.619806,-0.259058,0.111034,0.144451,-0.299163,-0.159324,0.240745,0.014426,-0.299317,0.001284,0.438766,-0.072798,0.376687,0.631455,-0.233461,-0.015163,-0.384174,0.394768,-0.392531,-0.086203,0.137091,0.378549,0.033602,-0.028901,0.182393,-0.182352,-0.143766,0.198056,-0.068009,-0.687779,0.007584,0.036669,0.063347,-0.613728,0.348265,-0.211224,-0.058573,-0.036863,-0.314011,0.298608,0.326994,0.069725,0.173548,0.000437,0.182468,-0.510770,0.056341,0.493140,-0.102301,-0.241064,0.014367,0.066253,-0.266658,0.094831,-0.443518,-0.236972,-0.218890,0.649566,-0.090313,-0.166867,0.255881,-0.590043,-0.039686,-0.259223,-0.318410,0.028694,-0.437212,-0.172272,-0.419169,-0.207646,-0.217820,-0.052048,0.028903,0.019087,-0.040818,0.717268,-0.682496,-0.026962,0.594575,0.283988,-0.510131,0.337144,-0.230962,0.178987,-0.216064,-0.208129,0.032260,0.310848,0.481734,0.415445,0.423531,-0.269165,-0.261647,0.026830,0.396144', '1309069', '30162520', '25928048', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292067', '冰血暴', '剧情', '汽车经理谢利（威廉姆·H·梅西 William H. Macy 饰）有一个完美的兴建停车场的计划，他多次找他的有钱岳父威利借钱，可是一毛不拔的威利始终没答应。无奈之下，谢利只有找到卡奥（史蒂夫·布西密 Steve Buscemi 饰）和基亚（彼得·斯特曼 Peter Stormare 饰），请他们绑架自己的妻子以勒索威利100万，事成后给他两4万酬金。3人一拍即合。当谢利回到家时，威利告诉他可以考虑一下他的计划了。喜出望外的谢利马上找到了威利，然而威利并不是要借钱，而是想自己投资。失望的谢利回到家时发现妻子已经被绑架了。卡奥和基亚在绑票得手后逃跑时，又意外打死了一名警察和两名路人，事情开始闹得越来越大……©豆瓣', '威廉姆·H·梅西', '乔尔·科恩', 8, 84328, 'tt0116282', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2178583078.jpg', 0.3, 1.5, 20.4, 52.6, 25.2, '0.222588,0.014720,-0.691326,0.324175,-0.161063,-0.722950,0.593996,0.049130,-0.365590,-0.301383,-0.129753,0.715407,0.009836,0.020832,0.324805,0.355267,-0.492290,-0.560162,0.322371,-0.249324,-0.287496,-0.651837,0.011946,-0.477270,-0.022879,-0.144312,-0.059686,0.038962,-0.045232,0.377671,0.332066,0.257244,0.319811,0.509134,-0.233150,0.427928,0.163877,-0.029011,-0.207498,0.277240,0.014386,0.051604,-0.392825,0.159944,0.352432,0.670957,0.027928,-0.022619,-0.216071,0.111714,0.102243,-0.258443,0.135015,0.086635,0.099077,-0.150105,0.205945,0.062961,-0.481322,-0.271058,0.232182,-0.101657,-0.633609,0.156151,-0.255686,-0.050253,-0.776231,0.063509,-0.175465,0.158602,0.207004,-0.374598,0.057581,0.380355,0.039248,0.104745,-0.005232,0.017902,-0.663253,0.022121,0.656139,0.030087,0.066726,0.080831,0.129158,-0.320936,0.132586,-0.156886,-0.377251,0.090774,0.619492,-0.015440,-0.213356,-0.185681,-0.444551,-0.408767,-0.532662,-0.125426,-0.341996,-0.356465,0.095951,-0.300217,-0.049420,-0.144083,-0.374749,0.202843,-0.075888,-0.292103,0.246635,-0.557953,0.259185,0.409134,0.481846,-0.641501,0.618192,0.172429,0.011515,-0.208418,-0.002971,-0.166100,0.308629,0.313466,0.487903,0.312829,0.190380,-0.375203,-0.231706,0.378825', '1292584', '1292646', '25908042', '35461732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292206', '地下', '剧情', '影片通过三位主人公——知识分子和投机商马高、他的朋友黑仔、他们共同的爱人娜塔莉——传奇般的人生展现了导演对南斯拉夫这个民族的理解与复杂情感。©豆瓣', '米基·马诺伊洛维奇', '埃米尔·库斯图里卡', 9.2, 57581, 'tt0114787', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1833776334.jpg', 0.5, 1, 5.5, 22.8, 70.1, '0.496410,-0.281934,-0.267753,1.060986,0.054940,-0.082492,0.829424,-0.059959,-0.352051,-0.017279,-0.005852,1.167027,-0.308090,0.361559,0.362224,-0.242257,-0.407565,-0.872672,-0.242468,0.306068,0.242365,-0.513946,-0.430916,-0.184127,-0.197820,-0.291350,1.117825,-0.153421,-0.412972,0.522169,0.198223,0.261549,-0.231062,0.043518,0.140257,0.146365,0.220265,0.205655,-0.984571,-0.109481,0.121634,0.325475,0.016734,0.368066,-0.489610,0.242984,0.461766,-0.502095,-0.289914,0.210627,0.503663,-0.210384,0.034640,0.251235,-0.146491,-0.108054,0.139098,0.313389,0.390976,-0.303882,-0.269016,0.071244,-1.052100,-0.366222,0.187983,0.073410,-0.457552,0.632321,0.036652,-0.191471,0.532545,0.143381,0.039144,0.282110,0.429186,0.606375,-0.319640,-0.063232,-0.160454,0.709156,0.552399,0.181010,-0.558402,0.485366,-0.561465,-0.718670,-0.230903,-0.010765,-0.695182,0.073247,0.130698,-0.036111,-0.186909,0.420046,-0.951725,-0.160813,0.289275,-0.032983,0.172686,-0.723729,0.349080,-0.685867,-0.657342,-0.705377,-0.275369,-0.389366,0.329866,-0.424469,1.467550,-0.828861,-0.116352,0.363443,0.298330,-0.587293,1.200694,0.124826,0.062956,-0.641056,-0.191511,0.255803,-0.198148,-0.253638,-0.032426,0.672775,0.074849,0.317572,-0.283407,0.520054', '27602116', '22265121', '25880986', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292207', '铁皮鼓', '剧情', '奥斯卡（大卫·本奈特 David Bennent 饰）的家庭有些荒诞。他的母亲和自己的表弟相恋，由于近亲不能结婚，所以被迫嫁给了一位商人。奥斯卡是谁的孩子只有他母亲知道。在他三岁生日那天，母亲送了他一面铁皮鼓。奥斯卡十分喜欢，整天挂在脖子上敲。一天，奥斯卡躲到桌子底 下玩的时候发现了母亲与舅舅的秘密，他认为成人世界充满了欺骗，于是决定不再长大。当奥斯卡从楼上跳下时，奇迹发生了，他从此不再长高，身高永远只有三岁的水平！奥斯卡还意外获得了一种神秘的能力――高分贝的尖叫。当看到母亲与舅舅幽会时，他会爬上钟楼，用尖叫震碎所有玻璃；当老师责骂他时，他的尖叫震坏了老师的眼镜。奥斯卡维持着三岁的身高水平慢慢长大。©豆瓣', '马里奥·阿多夫', '沃尔克·施隆多夫', 8.3, 53596, 'tt0078875', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1792296798.jpg', 0.5, 1.5, 14.7, 47.5, 35.8, '-0.054925,0.052105,-0.671570,0.318833,-0.538111,-0.146521,0.683883,0.208248,-0.283900,-0.058862,0.114528,1.061091,-0.330455,0.591900,0.014782,-0.072539,-0.162857,-0.728900,0.115619,-0.218765,-0.329120,-0.348481,-0.050316,0.054369,-0.158094,-0.395374,0.397084,-0.311089,-0.132292,0.269547,0.409431,-0.138090,0.110383,0.261139,-0.343465,0.125246,-0.035202,0.168783,-0.102953,0.127163,0.060888,-0.081660,0.042988,-0.150330,-0.109211,0.137112,0.431376,-0.276476,-0.112935,-0.172639,0.371785,-0.114276,-0.188133,0.348856,0.129449,-0.082127,0.080997,0.192525,-0.004428,-0.025234,0.206582,-0.020016,-0.176545,0.080359,-0.026072,-0.078181,-0.656457,0.272745,-0.193711,0.124992,0.207666,-0.341412,0.272869,0.190186,-0.250753,0.433053,-0.364004,0.182206,-0.505004,0.098495,0.475037,0.094859,-0.073774,0.426930,-0.120327,-0.300827,-0.087777,-0.320866,-0.611533,0.160508,0.302089,0.019640,-0.440752,0.026492,-0.112244,-0.114214,-0.026723,-0.144980,0.144684,-0.365058,-0.191852,-0.047324,-0.164624,-0.572844,-0.174835,-0.187098,-0.176407,-0.489977,0.652072,-0.575712,0.244373,0.271773,0.344611,0.024062,0.734551,0.112888,-0.056069,-0.187259,0.190740,0.115528,-0.197451,0.184350,0.023410,0.186870,0.069702,-0.121199,-0.431195,0.604674', '30162520', '1292720', '30167633', '30140107');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292208', '上帝之城', '剧情', '巴西里约热内卢的贫民窟，这里是“上帝之城”，更是魔鬼也会叹息着转身的地方。阿炮（Alexandre Rodrigues 饰）带着我们到了这里，他见证了这里二十多年来被残暴、贪婪、复仇、野心、背叛、掠夺所裹挟的混乱生活以及最终导致的一场灾难性的黑帮争斗。虽然从小就要 辗转于匪徒间求生存，但胆小怕事的性格与自我保护的本能却使他一直能平安度日。60年代初，阿毛、阿夹和阿呆是这里的“少年三侠”，在抢劫完旅馆之后，他们三人分道扬镳，阿夹重回上帝的怀抱，而阿呆和阿毛纷纷付出了生命的代价。70年，当年“少年三侠”手下的小弟小豆子（Douglas Silva 饰）靠着自己的心狠手辣，不停地吞并别人的地盘，成为了贫民区的“小霸王”，生意也从抢劫升级到了更为暴利的毒品买卖，和他一起飞黄腾达的还有班尼（Phellipe Haagensen 饰）。班尼认识了美丽的安迪丽卡（Alice Braga 饰），准备归隐，在送别的晚会上，他意外被对头杀害，悲痛之下，“小霸王”集合人手给班尼报仇，帮派之间的厮杀就此开始。此时的阿炮，机缘巧合下成为了杂志社的见习摄影师，他的相机，照下的却是孩子们持枪荷弹的狰狞，和帮派间无休无止的仇杀。', '亚历桑德雷·罗德里格斯', '费尔南多·梅里尔斯', 9, 284261, 'tt0317248', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p455677490.jpg', 0.2, 0.5, 7, 34.6, 57.7, '0.248729,0.148688,-0.629199,0.403950,-0.062845,-0.338605,0.702131,0.181037,-0.393743,0.051494,0.187294,0.670065,-0.006633,0.360049,0.131364,-0.137891,-0.235339,-0.768811,-0.444873,-0.179712,-0.275555,-0.201894,-0.307505,-0.196687,-0.257160,-0.161736,0.479030,0.196001,-0.198916,0.507783,0.311490,0.216245,-0.164362,0.443350,-0.359117,-0.060846,0.019653,0.055630,-0.374171,0.037355,0.032105,-0.389080,-0.073758,0.146741,0.017210,0.257690,0.764630,-0.246737,0.025889,-0.325770,0.069181,-0.272603,-0.169798,-0.015716,0.268134,-0.179159,0.241381,0.209361,-0.062063,-0.098389,0.206688,-0.096254,-0.653205,-0.163830,0.190959,0.053472,-0.685344,0.416912,0.126752,0.069095,0.074601,-0.334240,0.316788,0.383412,0.206991,0.319297,-0.098648,-0.040444,-0.562044,0.320836,0.815083,-0.210774,0.008432,0.036385,-0.198903,-0.517246,0.002827,-0.314077,-0.491249,-0.231299,0.444588,-0.179340,-0.064997,0.323355,-0.712729,-0.048948,-0.072014,-0.056726,0.048959,-0.440622,-0.059218,-0.475091,-0.037988,-0.443832,-0.189442,0.384814,0.130652,0.001714,0.590129,-0.765855,0.143873,0.735741,0.389564,-0.405331,0.549840,-0.092654,0.149147,0.052954,-0.116882,0.128518,0.118532,0.419962,0.330491,0.245986,-0.108920,0.087991,-0.225006,0.474541', '2032339', '1301022', '3055049', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292211', '对她说', '剧情', '马克（达里奥 葛兰帝内提Darío Grandinetti饰）和贝尼诺（加维埃尔·卡马拉Javier Cámara饰）在一场表演前都被深深感动。马克眼里泪光点点，坐在旁边的贝尼诺看到，心里被某种柔软的感情击到。本以为是萍水相逢，却不料这两个同病相怜的男人日后还有交集。马克的女友莉迪亚（罗萨里奥·福罗雷斯Rosario Flores饰）本是一个职业斗牛士，比赛场上的意外令她变成了植物人。现在莉迪亚就躺在贝尼诺的诊所里接受治疗。马克每天来到这里，盼望莉迪亚能苏醒过来。其实，贝尼诺也在这里守着他的爱情，一守就是四年。女孩阿里西亚（蕾欧诺·瓦特林 Leonor Watling饰）是一个芭蕾舞女生，贝尼诺曾经住在她的舞蹈室的对面，每天对翩翩倩影暗暗心动。当女孩遇到车祸变成植物人之后，贝尼诺每天都对她说话，相信她能听到的信念在他心中从未动摇。两个男人，此刻都有相同的孤独，相同的处境，友谊在酝酿积聚。然而没想到，离开不多时的马克却接连收到噩耗，就连贝尼诺，也陷入了命运的漩涡。', '哈维尔·卡马拉', '佩德罗·阿莫多瓦', 8.5, 85078, 'tt0287467', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1108397218.jpg', 0.5, 1.2, 12.9, 44, 41.4, '0.269083,0.053392,-0.952044,0.398932,-0.152664,-0.314636,0.996808,0.041724,-0.446943,-0.219212,0.266767,0.612478,-0.485388,0.257295,0.241227,-0.163690,-0.321858,-0.706662,-0.102664,-0.210759,-0.181174,-0.404954,-0.167701,-0.208391,-0.053807,-0.327518,0.477100,0.067634,0.061181,0.558611,0.287518,0.211540,0.098839,0.479317,-0.081886,-0.007817,0.040336,0.104747,-0.035921,0.127821,0.143590,-0.158770,-0.105409,0.052540,-0.010507,0.209278,0.517300,-0.321928,-0.082691,0.099530,0.028760,-0.132390,0.100947,0.118824,0.172112,-0.160771,0.314414,-0.118643,-0.242836,0.038082,0.210747,0.095211,-0.532141,0.250373,0.018832,0.299264,-0.588473,0.561173,-0.062481,-0.138730,0.074395,-0.336873,0.229848,0.182726,0.348657,0.488668,-0.169400,0.005053,-0.564748,-0.194637,0.682538,0.081011,-0.338435,0.334035,-0.395012,-0.334524,-0.108443,0.095982,-0.370847,-0.006346,-0.003062,0.030454,-0.027339,0.062814,-0.426903,0.315813,-0.125295,-0.002393,-0.052512,-0.526683,-0.227586,-0.386742,-0.149949,-0.215700,-0.543119,0.336184,0.003882,-0.219588,0.573374,-0.879925,0.444667,0.306777,0.353060,-0.228744,0.834700,0.149844,-0.002396,-0.102842,-0.073218,0.538190,-0.136561,0.040989,0.064346,0.425314,