INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292212', '天使之城', '剧情', '天使塞斯（尼古拉斯•凯奇 饰）拥有天使应该拥有的一切法力，还能永生。他的使命就是每天游荡在医院里将已去的人们带到另外一个世界，他却爱上了医院的医生梅姬（梅格•瑞恩 饰），为了能够和心爱的人在一起，塞斯放弃了天使的身份，放弃永生，坠入了凡间。然而，他却并不明白，等待他的，除了动人的爱情，还有弄人的命运。©豆瓣', '尼古拉斯·凯奇', '布拉德·塞伯宁', 7.9, 145020, 'tt0120632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p480503066.jpg', 0.3, 2.2, 24.6, 47.8, 25, '0.126097,0.362610,-0.679555,0.556828,-0.482309,-0.298123,0.904055,0.269248,-0.491566,-0.012924,0.145307,0.783313,0.351857,0.098458,0.299772,0.455360,-0.591921,-0.640054,0.104060,-0.095367,-0.263696,-0.426415,-0.266508,-0.418009,-0.002443,-0.383541,0.727307,0.011756,0.211142,0.065211,0.322678,0.099584,-0.164331,0.618191,-0.387847,-0.023316,-0.028924,-0.199749,-0.302633,0.369402,0.073698,-0.094310,0.005069,0.409259,-0.301121,-0.036067,0.420362,-0.540111,0.149356,-0.224017,0.130091,-0.303680,-0.020238,0.143768,-0.085598,-0.371481,0.212776,0.307286,-0.045077,0.088920,0.396116,0.065164,-1.166711,-0.235007,0.150213,0.445602,-0.594787,0.608372,-0.016449,0.063992,0.220114,-0.366210,0.199686,0.002597,0.064225,0.660546,-0.160828,-0.351468,-0.712576,0.238884,0.629767,-0.135700,-0.270130,0.631641,-0.431185,-0.529553,-0.458315,-0.226386,-0.660027,0.058406,0.204041,0.374606,-0.255600,0.144862,-0.445809,0.096639,-0.289906,-0.284111,-0.140808,-0.752974,-0.080465,-0.361070,-0.038034,-0.318356,-0.397166,0.029592,0.232843,-0.319838,0.827864,-0.850621,0.244185,0.920518,0.463223,-0.402200,0.952700,0.214431,0.156423,-0.095142,0.026351,0.585275,-0.099391,0.657499,-0.026666,0.186299,0.127980,0.259627,-0.530633,0.678591', '1793491', '30163500', '3785918', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292213', '大话西游之大圣娶亲', '喜剧', '至尊宝（周星驰 饰）被月光宝盒带回到五百年前，遇见紫霞仙子（朱茵 饰），被对方打上烙印成为对方的人，并发觉自己已变成孙悟空。紫霞与青霞（朱茵 饰）本是如来佛祖座前日月神灯的灯芯（白天是紫霞，晚上是青霞），二人虽然同一肉身却仇恨颇深，因此紫霞立下誓言，谁能拔出她手中的紫青宝剑，谁就是她的意中人。紫青宝剑被至尊宝于不经意间拔出，紫霞决定以身相许，却遭一心记挂白晶晶（莫文蔚 饰）的至尊宝拒绝。后牛魔王救下迷失在沙漠中的紫霞，并逼紫霞与他成婚，关键时刻，至尊宝现身。©豆瓣', '周星驰', '刘镇伟', 9.2, 1437198, 'tt0114996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2455050536.jpg', 0.2, 0.5, 5.8, 26.5, 67, '0.040247,0.370089,-0.748766,0.250726,-0.119510,-0.397956,0.378212,-0.177670,-0.495035,-0.069344,0.367980,0.543630,-0.449470,0.155893,-0.087721,0.282359,0.046876,-0.824875,0.062961,-0.078754,0.178761,-0.063994,-0.150003,0.719210,-0.284516,0.018691,0.629886,-0.068774,-0.088123,0.407647,0.300314,0.179403,-0.249906,0.441704,-0.190976,0.290879,-0.529642,0.019946,-0.168947,0.263168,0.050329,-0.311082,-0.048553,0.184804,-0.346257,0.401755,0.131410,-0.231940,0.031100,-0.496957,0.153521,0.072945,-0.289302,0.289489,0.052447,0.086700,0.155303,0.027363,-0.250715,0.142460,0.031470,-0.179386,-0.239759,0.131345,0.090603,0.090545,-0.238296,0.240674,-0.160687,0.044073,-0.159550,-0.497986,0.071478,-0.327018,0.252093,-0.092877,-0.575844,-0.405005,-0.550870,0.122287,0.385100,-0.377053,0.333030,0.335574,0.263415,-0.020700,-0.276032,0.170993,-0.041275,0.079052,0.547600,0.306866,0.133885,0.104875,-0.311457,-0.336104,-0.338831,0.336398,-0.154849,-0.121397,-0.203028,-0.240524,0.113267,-0.457432,-0.606650,-0.341088,0.289436,-0.097669,0.411976,-0.780070,0.494507,-0.038579,0.262658,-0.058320,0.463492,0.142048,0.306810,-0.073746,-0.200497,0.473855,0.164989,0.443628,0.137964,0.007464,-0.092950,0.308867,-0.432621,0.161190', '1301022', '30345227', '1307755', '4845414');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292214', '非常嫌疑犯', '悬疑', '美国加州的圣佩雷罗港一艘货轮爆炸，死亡27人，9000万美元失踪。事故发生以后，联邦调查局探员白基奇在医院等待昏迷不醒的幸存者；海关特派员大卫（查兹•帕明特里 饰）则对另外一名拿到特赦令的幸存者金特（凯文•史派西 饰）进行了审问。金特供认，在事故中丧生的基顿（加布里埃尔•伯恩 饰）、法特（本尼西奥•德托罗 饰）、麦曼诺（斯蒂芬•鲍尔文 饰）和杜学尼（凯文•波拉克 饰），以及他本人，六个月前被警察局作为卡车抢劫案的疑犯带到警局过了一夜，五人因此结成了一个犯罪团伙，狼狈为奸，狠捞了好几笔。好景不长，某天，律师小林（皮特•波斯尔思韦特 饰）找到他们，让他们替神秘头目凯撒•苏尔烧掉货轮上的毒品。法特第一个退出，随即遭到杀害，剩下四人不得不接受了这个任务。在货轮上，麦曼诺、法特、基顿都没有找到毒品，也因此相继被凯撒杀害，船也被炸毁，金特因为留在岸上接应而侥幸生还。另一边，在医院抢救的幸存者，拼出了凯撒的头像，结果让所有人大吃一惊……', '史蒂芬·鲍德温', '布莱恩·辛格', 8.6, 240954, 'tt0114814', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2455372830.jpg', 0.3, 0.8, 10.8, 43.1, 45.1, '0.258830,-0.191894,-0.703539,0.159727,0.100531,-0.402805,0.778339,0.124218,-0.477168,-0.118327,0.365924,0.619968,-0.050546,-0.056747,0.480114,0.095078,-0.773097,-0.434098,0.071416,-0.291730,-0.498125,-0.653152,-0.219810,-0.248067,0.190689,-0.216214,0.324353,0.072565,0.177620,0.612164,0.205418,0.472189,-0.159164,0.178773,0.075878,0.408646,0.500650,-0.474855,-0.199536,0.459997,-0.186801,-0.203209,-0.026690,0.055378,0.090590,0.519761,0.552020,-0.043488,0.121118,-0.089187,-0.064731,-0.485727,0.164121,0.023019,0.303180,-0.103968,0.033505,0.289973,-0.469136,-0.172510,0.283678,0.296634,-0.596349,0.144923,-0.071030,0.334292,-0.484098,0.272410,-0.410313,0.225957,-0.049152,-0.239517,0.269721,0.424034,0.085193,0.140234,-0.054067,0.112134,-0.839265,-0.024539,0.588131,-0.233038,-0.096044,-0.016798,0.157460,-0.312501,-0.035424,-0.163445,-0.152436,0.063919,0.648479,-0.228436,0.084555,-0.012117,-0.469354,-0.138816,-0.578468,-0.372671,-0.166284,0.103688,-0.150066,-0.835468,0.024673,0.084884,-0.421191,0.147394,-0.068166,0.137377,0.306818,-0.326539,0.337095,0.512076,0.258618,-0.259389,0.420472,0.026619,0.251053,-0.128805,0.039337,0.177960,0.562687,0.571799,0.271957,0.155689,-0.011745,-0.409734,-0.258838,0.015413', '1301345', '1297260', '21349734', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292215', '天使爱美丽', '剧情', '艾米莉（奥黛丽·塔图 Audrey Tautou 饰）有着别人看来不幸的童年——父亲给她做健康检查时，发现她心跳过快，便断定她患上心脏病，从此艾米莉与学校绝缘。随后因为一桩意外，母亲在她眼前突然死去。这一切都毫不影响艾米莉对生活的豁达乐观。1997年，戴安娜王妃的去世让她倍感人生的孤独脆弱，艾米莉从此开始了一系列助人计划，包括自闭忧郁的邻居老人，被老板刻薄的菜摊伙计、遗失了童年器物的旧房东、爱情失意的咖啡店同事。但她万万想不到，成人录象带商店店员尼诺（马修·卡索维 Mathieu Kassovitz 饰），竟成为她的棘手对象，艾米莉开始了令人哭笑不得的另类计划……©豆瓣', '奥黛丽·塔图', '让-皮埃尔·热内', 8.7, 919597, 'tt0211915', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2447590313.jpg', 0.3, 1.1, 11.6, 36.8, 50.2, '0.334732,0.053888,-0.562823,0.201549,-0.362664,-0.498638,0.889439,0.148521,-0.835219,-0.337371,0.304728,0.737169,-0.292903,0.395531,0.273676,0.152633,-0.118134,-0.332449,0.044644,0.085263,-0.092057,-0.169406,-0.031915,-0.487484,-0.101148,-0.501371,0.382371,-0.011351,0.215678,0.407211,-0.109429,0.273557,0.022996,0.500230,-0.066307,0.421888,0.152624,0.105071,-0.123734,-0.294939,0.073199,-0.139350,-0.052577,0.417454,-0.262660,0.356656,0.514558,0.056951,-0.597477,-0.107285,0.663888,-0.019318,0.045892,0.163639,0.194374,0.087472,0.179767,0.046346,-0.228188,-0.300782,0.381535,0.118340,-0.481081,0.021684,0.128834,0.050071,-0.264076,0.330874,-0.363549,0.017063,0.121867,-0.415756,-0.056373,0.161849,0.629900,0.413221,-0.256437,-0.052528,-0.288988,0.343463,0.580161,-0.201972,-0.463203,0.633552,-0.501707,-0.190605,0.201854,-0.161620,-0.668137,0.347003,0.285530,0.063376,-0.253807,0.538396,-0.455075,-0.173588,-0.226421,-0.060937,-0.060007,-0.308738,-0.209151,-0.343564,-0.223342,-0.177684,-0.529739,-0.230939,-0.002232,-0.225036,0.524811,-0.640092,0.408126,0.543513,0.070701,-0.385047,0.475894,-0.127122,0.186310,-0.122917,-0.107111,0.552542,-0.191942,0.109187,0.138238,0.285293,0.019772,0.117937,-0.175408,0.467404', '1309172', '1291877', '1292528', '2075721');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292216', '爱情是狗娘', '剧情', '三个与狗有关的故事，三段令人唏嘘的人生。奥克塔瓦（Gael Garcia Bernal 饰）和母亲、兄嫂住在一起，哥哥阿米罗（Marco Perez 饰）和女人鬼混，白天在超市上班，晚上抢劫超市，对妻子苏珊娜（Vanessa Bauche 饰）和小孩十分粗暴，奥克塔瓦慢慢爱上了苏珊娜，为了和苏珊娜私奔，他带自己的狗“高飞”参加地下斗狗比赛，赢了不少钱。谁知，快到约定私奔的日子，阿米罗和苏珊娜带着小孩离开了，还带走了他辛苦攒下的钱，气急败坏的奥克塔瓦约老对手做最后一场比赛，对方输红了眼，开枪打伤“高飞”，奥克塔瓦刺伤对手，开车逃亡，发生车祸。他和家人的生活，就此转折。和奥克塔瓦撞车的是名模瓦雷里亚（Goya Toledo 饰），她的情人丹尼尔（Alvaro Guerrero 饰）刚刚离开妻子，二人开始同居。车祸使她的职业生涯受到了很大的影响，相依为命的宠物狗“米奇”掉到地板下，更是严重打击了她的精神，生活陷入困境。车祸现场，流浪汉玛汀捡走了“高飞”，玛汀早年为了追求理想，抛妻弃女参加游击队，出狱后成为职业杀手，但是仍然心怀平凡父亲的梦想，希望得到女儿的原谅，机缘巧合之下，他和女儿有了见面的机会，他却无法面对。', '盖尔·加西亚·贝纳尔', '亚历杭德罗·冈萨雷斯·伊纳里图', 8.2, 48098, 'tt0245712', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p627345397.jpg', 0.3, 1.2, 15.7, 52.4, 30.4, '-0.034514,-0.341701,-0.479154,0.153060,-0.318536,-0.500346,0.716494,0.082009,-0.187073,-0.121657,0.238252,0.822191,-0.316164,0.161497,0.289161,-0.188618,-0.315890,-0.553684,0.159912,0.162157,-0.303001,-0.511362,0.092372,-0.183619,-0.127534,-0.097146,0.270310,-0.062991,-0.065143,0.617345,0.250854,0.220722,-0.165465,0.284091,-0.289726,0.175695,-0.130083,0.239806,-0.233835,0.284175,0.135430,0.116543,-0.093841,0.012621,0.239411,0.296678,0.374793,0.109325,0.101212,-0.285934,0.167735,-0.069140,-0.022098,0.276170,0.184024,-0.094203,0.191811,0.051267,-0.173858,-0.237649,0.196574,-0.025281,-0.386719,0.218623,0.093062,-0.131665,-0.698193,0.418927,-0.192728,0.213694,0.406892,-0.097099,0.063461,0.437336,0.127513,0.312395,-0.026687,0.138238,-0.668556,-0.006153,0.734586,-0.211259,0.020941,0.185817,-0.115567,-0.235796,0.024200,-0.157324,-0.294303,0.130594,0.423719,-0.085466,-0.217161,0.314407,-0.409150,-0.130174,-0.271860,-0.019170,-0.071662,-0.333312,-0.071396,-0.343604,-0.024770,-0.470795,-0.476176,0.055564,-0.046790,-0.302631,0.361048,-0.515849,0.353943,0.560373,0.446750,-0.437809,0.590635,0.119098,0.071965,-0.167545,0.091616,0.393554,0.014754,0.260345,0.310720,0.126468,-0.010977,-0.064659,-0.157573,0.490820', '1297239', '1292584', '1293908', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292217', '穆赫兰道', '剧情', '深夜的穆赫兰道发生一桩车祸，女子丽塔（劳拉·赫利 Laura Harring 饰）在车祸中失了忆。她跌跌撞撞来到一个公寓里藏身。一名男子说他常常梦见一个叫云奇的地方，那里有个恶魔盯着他。于是就来到云奇，果真见到墙后有怪物出现，男子当场晕死。另有一名杀手杀死了他面前 的男人，然而蹩脚的他却惹来了不少一连串的麻烦。故事回到一个刚到好莱坞“寻梦”的女子贝蒂（娜奥米·沃茨 Naomi Watts 饰），她的姨父姨母在电影圈有广泛人缘，让贝蒂的发展如虎添翼，试镜大受好评。同时，她所住的公寓，正好是丽塔藏身之地。贝蒂收留了丽塔，二人感情融洽。面对记不起自己是谁的丽塔，贝蒂决定帮助她寻找回自己的记忆。一名导演想自己决定新戏的女主角，却被他人强行安排人选。工作不顺意的他还发现妻子和清洁工睡在一起。这些看似松散的事件，就像一个迷宫，引向一个让人猜不透的世界……', '娜奥米·沃茨', '大卫·林奇', 8.4, 413284, 'tt0166924', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p792248233.jpg', 1.2, 2.4, 14.3, 39.2, 42.9, '0.316311,-0.091618,-0.727336,0.537596,-0.227468,-0.179900,1.015180,0.089393,-0.339110,-0.352308,0.419247,0.894975,-0.246146,0.363394,0.346857,0.099459,-0.158596,-0.556678,0.164377,-0.121120,-0.260652,-0.330481,-0.214228,-0.198077,-0.073105,-0.206692,0.472333,-0.026626,-0.179422,0.078765,0.189482,0.212886,-0.281969,0.560262,-0.254661,0.138282,0.217560,-0.026816,0.118611,0.433313,-0.076803,-0.375948,-0.239391,0.223392,-0.197806,0.270557,0.565378,-0.089414,-0.293659,0.191438,0.367260,-0.294164,-0.010861,0.103240,0.322438,-0.286382,0.108696,-0.096120,-0.372980,-0.028714,0.082473,-0.164398,-0.538278,0.168608,0.062530,0.210655,-0.587343,0.332859,0.002994,-0.021268,0.019545,-0.386177,0.198616,0.160607,0.216961,0.266085,-0.122572,0.180972,-0.466524,0.028623,0.747546,0.021662,-0.078323,0.416886,0.013629,-0.329385,-0.032281,0.130176,-0.556309,0.020637,0.330436,-0.236251,-0.247129,-0.103807,-0.315217,-0.097681,-0.472021,0.000281,-0.236517,-0.376547,-0.151244,-0.413483,-0.153268,-0.077559,-0.257525,0.114428,-0.040202,-0.183246,0.616652,-0.610506,0.146019,0.677636,0.228392,-0.551308,0.672280,-0.089968,0.225382,-0.083478,-0.007583,0.348174,0.088386,0.096211,0.092827,0.409201,-0.136042,-0.112590,-0.435172,0.263030', '1296534', '4275444', '1783772', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292218', '中央车站', '剧情', '里约热内卢的中央车站，朵拉（费尔南达-蒙特内格罗Fernanda Montenegro饰）在这里帮人写信。但她会把看不顺眼的信统统撕掉不寄，甚至公开读信里的内容取乐。朵拉生活拮据，年纪不小却还未嫁，或许在她内心，人与人之间的真情根本就不值得信赖。小男孩约书亚（文尼西斯•狄•奥利维拉Vinícius de Oliveira 饰）的出现令她开始了一段重新认识人生的旅程——约书亚很想见到远方素未谋面的父亲，不断写信给他。男孩母亲意外的车祸让朵拉决定陪伴约书亚前往东北部寻找父亲。在约书亚眼中，即使父亲很陌生，却总是骄傲地谈起父亲。而朵拉，也同样有着一段和父亲的痛苦往事。在约书亚寻父的过程中，朵拉因为往事而冰冻的内心慢慢回暖。©豆瓣', '费尔南达·蒙特内格罗', '沃尔特·塞勒斯', 8.7, 100473, 'tt0140888', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239441575.jpg', 0.1, 0.5, 9.4, 44.2, 45.8, '0.201716,0.052313,-0.519550,0.489543,-0.062663,-0.209147,0.811870,0.011264,-0.621063,-0.131296,-0.032408,0.596356,-0.241510,0.380930,0.264264,0.212614,-0.497186,-0.558227,0.142890,0.047599,-0.294129,-0.408173,-0.195883,-0.417487,-0.177560,-0.213485,0.671597,-0.023899,-0.128899,0.626281,0.170349,0.475008,-0.237035,0.569634,-0.365576,-0.085930,-0.151896,0.265060,-0.133398,-0.146479,0.275836,-0.331693,-0.173633,0.199218,0.050011,0.362441,0.623928,-0.311788,0.069828,0.274259,0.071451,-0.203347,0.076872,-0.008266,-0.010582,-0.066770,0.210285,0.230327,-0.201861,-0.158297,-0.003644,-0.200072,-0.307951,0.227615,0.349323,0.149986,-0.441033,0.478060,-0.121445,0.096627,0.296283,-0.296626,0.001703,0.361970,0.003540,0.424860,-0.291482,0.076275,-0.280030,0.021855,0.626387,-0.256889,0.016568,0.321141,-0.574487,-0.173221,-0.251214,0.079699,-0.600602,0.178790,0.015233,0.208051,-0.130599,0.398999,-0.407630,-0.121864,-0.268555,-0.023778,0.124586,-0.557428,-0.109271,-0.162012,-0.269775,-0.364792,-0.334960,-0.159278,0.147092,-0.182038,0.436309,-0.392917,0.415406,0.277558,0.294102,-0.289536,0.678990,0.250765,-0.091008,-0.296310,0.080220,0.647971,0.000712,0.098837,0.107621,0.116549,-0.030814,-0.096458,-0.267326,0.640492', '25723780', '26245360', '1305666', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292219', '关于莉莉周的一切', '剧情', '莲见雄一（市原隼人 饰）与母亲、继父、弟弟生活在一个幽静的小城里。他跟同班同学星野修介（忍成修吾 饰）同在剑道部，两人成为好朋友。星野本来是一个品学兼优的学生，却遭到了同学的嫉妒。当暑假时一群同学自冲绳回来以后，星野变了一个人似的。接着星野开始以欺负同学为乐，而且手段残忍，雄一也不能幸免。雄一性格孤僻，喜欢歌手莉莉周，在自己建立的莉莉周论坛上他认识了一个叫“青猫”的人。雄一与青猫都过着不容易的生活，两人互相鼓励，并约定在莉莉周的演唱会上见面，“青猫”的出现令雄一十分惊讶。©豆瓣', '市原隼人', '岩井俊二', 7.9, 160861, 'tt0297721', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p649141235.jpg', 1.2, 3.7, 24.9, 41.9, 28.3, '0.356970,-0.346497,-0.546393,0.631409,-0.150565,-0.527263,0.616057,0.261620,-0.273112,-0.205528,-0.059024,0.963909,-0.301515,0.578465,0.151305,0.044627,-0.067378,-0.570289,-0.011352,-0.197477,-0.167785,-0.403816,0.202618,-0.125327,-0.076440,-0.258031,0.326254,-0.327839,-0.114952,0.737398,0.367849,0.073148,-0.032896,0.443174,0.004747,0.057252,0.005056,0.135453,-0.177532,0.078052,-0.253672,-0.041476,-0.224442,0.162017,0.205960,0.190500,0.796992,0.006040,-0.281283,-0.168407,0.028105,-0.126286,-0.178138,0.163257,0.533549,-0.291024,0.381948,0.031710,0.018050,0.046404,-0.096303,-0.114355,-0.440362,0.226198,0.062020,0.083465,-0.484050,0.690278,-0.017477,-0.130225,0.105816,-0.395777,0.086537,0.334524,0.072421,0.348296,-0.271451,0.287833,-0.180485,0.160040,0.876013,0.109208,-0.258398,0.337176,-0.094222,-0.317845,-0.235341,-0.098185,-0.491936,-0.030668,0.130214,-0.424996,-0.358715,0.048984,-0.632648,-0.036710,0.122322,0.201446,0.075576,-0.460793,-0.140970,-0.342249,0.065353,-0.578461,-0.490196,0.181637,-0.084510,-0.326094,1.028388,-1.196727,0.008680,0.380730,0.334782,-0.284846,0.577381,0.288992,-0.106868,-0.067571,-0.030901,-0.156028,0.220622,0.266412,0.423899,0.496117,-0.073834,-0.065302,-0.220956,0.283904', '3445516', '1292720', '35030151', '3091208');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292220', '情书', '剧情', '日本神户某个飘雪的冬日，渡边博子（中山美穗）在前未婚夫藤井树的两周年祭日上又一次悲痛到不能自已。正因为无法抑制住对已逝恋人的思念，渡边博子在其中学同学录里发现“藤井树” 在小樽市读书时的地址时，依循着寄发了一封本以为是发往天国的情书。不想不久渡边博子竟然收到署名为“藤井树（酒井美纪）”的回信，经过进一步了解，她知晓此藤井树是一个同她年纪相仿的女孩，且还是男友藤井树（柏原崇）少年时代的同班同学。为了多了解一些昔日恋人在中学时代的情况，渡边博子开始与女性藤井树书信往来。而藤井树在不断的回忆中，渐渐发现少年时代与她同名同姓的那个藤井树曾对自己藏了一腔柔情。©豆瓣', '中山美穗', '岩井俊二', 8.9, 1017344, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2648230660.jpg', 0.2, 0.8, 8.9, 33.1, 56.9, '0.344919,0.022322,-0.805410,0.707078,-0.075849,-0.268124,0.784934,-0.068116,-0.666479,-0.530839,0.046630,0.728033,-0.225790,0.777695,0.110073,-0.055214,-0.184456,-0.659660,-0.050605,-0.490872,-0.185481,-0.621253,-0.344557,0.122140,-0.272892,-0.296207,0.703501,0.116967,-0.169166,0.534133,0.294482,0.286772,-0.295664,0.408400,-0.235394,0.021348,0.062363,0.182048,-0.192971,0.219709,0.047470,-0.391308,-0.199883,0.049114,-0.073388,0.316263,0.580558,-0.091267,-0.183364,0.087868,0.541186,0.012453,-0.166885,0.290184,0.404257,0.044607,0.352278,0.019531,-0.483447,-0.069139,-0.156514,0.038698,-0.138934,-0.052783,0.134490,0.395677,-0.478298,0.526203,-0.240961,-0.200625,0.477775,-0.359441,0.028168,0.418178,0.212503,0.180531,-0.434809,-0.009703,0.090848,0.134725,0.589360,0.109863,0.261406,0.508611,-0.047221,-0.461939,-0.062491,0.002410,-0.585296,0.185784,-0.041297,0.178363,-0.193504,0.226704,-0.388083,-0.169525,-0.070572,0.046896,0.220774,-0.348425,-0.276498,-0.561183,-0.195171,-0.532833,-0.220493,-0.004191,0.327320,-0.399463,0.999280,-0.918630,0.314248,0.599312,0.060079,-0.201011,0.452291,0.418199,-0.340017,-0.075697,-0.004470,0.332230,0.161899,0.312025,-0.048185,0.217578,-0.267063,-0.125175,-0.575254,0.405772', '25922902', '1306544', '1292219', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292222', '出租车司机', '剧情', '特拉维斯（罗伯特·德尼罗 Robert De Niro 饰）从越战中退伍回来后一直在纽约以开出租车为生。战争后的他多少有些失落，加上开出租车目睹了纽约夜幕下的种种罪恶，令他变得愤世嫉俗、痛恨社会。在追求总统候选人帕兰坦竞选办公室的秘书贝西失败后，特拉维斯决定去刺杀帕兰坦 以证明自己。在准备刺杀行动的过程中，特拉维斯遇上了被逼卖淫的雏妓艾瑞斯。在企图救艾瑞斯出火坑未果后，特拉维斯手持武器闯进淫窝，将里面的一干人等通通干掉了！本以为即将收到法律的惩罚，然而媒体却将特拉维斯描述成了一个拯救少女的英雄……©豆瓣', '罗伯特·德尼罗', '马丁·斯科塞斯', 8.5, 190019, 'tt0075314', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p792510233.jpg', 0.3, 1, 12.7, 43.9, 42.1, '0.325846,0.306538,-0.703213,0.338457,0.045161,-0.416712,0.344072,0.124385,-0.562086,0.028132,0.205969,0.675978,-0.167784,0.252554,0.760033,-0.087759,-0.441225,-0.714482,-0.310657,-0.211197,-0.489462,-0.479141,-0.195860,-0.139287,0.036303,-0.464697,0.470091,0.087060,-0.061617,0.344906,0.416824,0.560936,0.143847,0.389571,0.043103,0.145032,0.226523,-0.159878,-0.264361,0.498976,0.117921,-0.231781,-0.167796,0.166063,0.045459,0.272315,0.490125,-0.380146,0.166976,-0.258142,0.458963,-0.245815,0.031332,0.202448,0.212995,-0.093447,-0.087109,0.171254,-0.399358,0.247432,0.020506,-0.020529,-0.702737,-0.052536,-0.293760,0.074184,-1.053317,0.119972,-0.204447,0.066714,0.125163,-0.166563,0.246323,0.317394,0.269677,0.260059,0.069483,-0.210628,-0.569332,0.029160,0.418555,-0.048535,-0.066196,0.183754,-0.030901,-0.118584,0.216834,-0.192959,-0.330996,-0.195124,0.599965,-0.179336,-0.113859,0.225346,-0.601721,-0.339027,-0.672938,-0.218242,-0.087260,-0.227707,-0.361813,-0.548073,-0.001321,0.104189,-0.091718,-0.024545,-0.043740,0.022747,0.175051,-0.888468,0.172710,0.528457,0.244981,-0.084233,0.316241,0.014387,0.179113,0.014101,-0.167324,0.196222,0.432495,0.572261,0.076993,0.201067,0.062891,-0.374864,-0.316193,0.484825', '1986338', '1299965', '1309069', '1291838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292223', '七宗罪', '剧情', '“暴食”、“贪婪”、“懒惰”、“嫉妒”、“骄傲”、“淫欲”、“愤怒”，这是天主教教义所指的人性七宗罪。城市中发生的连坏杀人案，死者恰好都是犯有这些教义的人。凶手故弄玄虚的作案手法，令资深冷静的警员沙摩塞（摩根•弗里曼 Morgan Freeman 饰）和血气方刚的新扎警员米尔斯（布拉德•皮特 Brad Pitt 饰）都陷入了破案的谜团中。他们去图书馆研读但丁的《神曲》，企图从人间地狱的描绘中找到线索，最后从宗教文学哲学的世界中找到了凶手作案计划和手段的蛛丝马迹。凶手前来投案自首，这令众人都松了一口气，以为案件就此结束，怎料还是逃不出七宗罪的杀人逻辑，这次凶手瞄准的目标，是那个犯了“愤怒”罪的人……©豆瓣', '摩根·弗里曼', '大卫·芬奇', 8.8, 890862, 'tt0114369', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2219586434.jpg', 0.2, 0.6, 8.9, 39.5, 50.9, '0.222649,-0.165623,-0.416892,0.452139,-0.169892,-0.100829,0.805638,-0.290365,-0.501010,-0.209350,0.248064,0.361534,-0.141232,0.002273,0.282314,0.032293,-0.647675,-0.785557,0.002981,-0.481550,-0.170354,-0.672686,-0.267415,-0.566005,0.303856,-0.265193,0.373333,0.361795,-0.389196,0.124584,0.444663,0.485721,-0.190507,0.272312,-0.092984,-0.151902,0.248519,-0.377472,-0.092136,-0.071202,0.088577,-0.382294,-0.122973,0.443572,-0.369970,0.599274,0.704592,-0.319800,-0.052063,-0.145777,0.224686,-0.430742,-0.193682,0.309358,0.439472,-0.153624,0.025159,0.589814,0.213825,0.098545,-0.069419,-0.070155,-1.124022,-0.158432,0.307355,0.400635,-0.159271,0.213030,-0.301634,0.018891,-0.046462,-0.063838,0.464680,-0.075651,0.603515,0.363336,0.097829,-0.171538,-0.356495,-0.039217,0.240855,-0.185161,-0.191375,-0.006935,-0.509739,-0.709511,0.008903,-0.018816,0.008616,-0.099887,0.524118,0.056285,-0.403100,0.372967,-0.436898,-0.278500,-0.084419,0.020571,-0.301170,-0.291173,-0.333993,-0.491071,-0.161799,-0.176039,-0.176048,-0.155069,0.093691,-0.220093,0.418505,-0.426988,0.016416,0.529028,-0.023112,-0.402565,0.641679,-0.111236,-0.177914,-0.207028,-0.392289,0.299036,0.214936,0.514328,0.032520,0.227819,0.023160,-0.472508,-0.256629,0.348248', '1293989', '1307442', '2988294', '1297689');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292224', '飞越疯人院', '剧情', '麦克墨菲（杰克·尼科尔森 Jack Nicholson 饰）为了逃避监狱里的强制劳动，装作精神异常，被送进了精神病院，他的到来，给死气沉沉的精神病院带来了剧烈的冲击。 麦克要求看棒球比赛的电视转播，挑战了医院严格的管理制度，受到护士长拉契特（路易丝·弗莱彻 Louise Fletcher 饰）的百般阻挠；麦克带领病人出海捕鱼，振奋了他们的精神，却让院方头痛不已。院方为了惩处麦克胆大妄为、屡犯院规，决定将他永远留在疯人院。生性自由的麦克再也无法忍受疯人院的生活，他联合病友，高大的印第安人“酋长”，开始自己的计划：飞越疯人院。 本片获1975年第48届奥斯卡最佳影片，最佳男、女主角，最佳导演和最佳改编剧本五项大奖。主人公“不自由，毋宁死”的精神在当今社会仍有很大的现实意义。©豆瓣', '杰克·尼科尔森', '米洛斯·福尔曼', 9.1, 518398, 'tt0073486', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792238287.jpg', 0.2, 0.5, 6, 30.1, 63.2, '-0.021868,-0.125325,-0.601811,0.451724,-0.085800,-0.176063,0.545049,0.293410,-0.470075,0.031112,0.260696,0.725715,-0.101637,0.083209,0.315367,-0.142211,-0.396597,-0.459903,-0.246913,0.137139,-0.149890,-0.321055,-0.054612,-0.224248,-0.003035,-0.258126,0.570894,-0.215507,-0.162216,0.436852,0.291775,0.238940,0.306978,0.261512,0.046179,0.060321,0.356375,-0.259267,-0.177633,0.385062,0.323289,-0.198139,-0.156789,0.382212,0.190185,0.345100,0.574096,-0.123645,-0.149128,-0.008259,0.581669,-0.366704,-0.214985,0.188078,-0.070556,-0.070816,-0.125602,0.246636,-0.107816,0.294465,0.018713,-0.179484,-0.691050,0.062167,0.149117,0.137393,-0.349137,0.486391,-0.281472,0.255041,0.020012,0.058428,-0.123395,0.156354,0.192949,0.287412,-0.172530,0.012000,-0.293009,0.354073,0.338142,-0.256818,-0.488181,-0.014416,-0.449121,-0.574669,0.179498,-0.181718,-0.522205,-0.086880,0.608369,-0.016881,-0.273611,-0.077085,-0.327898,-0.080122,-0.222414,-0.454116,-0.314405,-0.290224,0.041453,-0.735431,-0.096995,0.014701,-0.128256,-0.206725,-0.046834,-0.141598,0.524293,-0.482445,0.204781,0.575533,0.129468,-0.529423,0.500921,0.237039,0.157849,-0.130040,-0.069095,0.295483,0.119272,0.712152,0.155913,0.305531,0.055518,-0.105008,-0.338766,0.548448', '4135443', '2159244', '26259202', '2028634');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292225', '闪灵', '恐怖', '杰克（杰克•尼科尔森 Jack Nicholson 饰）是一个作家。一个冬天，他得到了一个看管山顶酒店的差事。这正合杰克的意思，他正好可以有一个幽静的地方写作。于是杰克带着妻儿搬进了酒店。冬天大雪封路，山顶酒店只有杰克一家三口。从他们一搬进来，杰克的妻子温蒂（谢莉·杜瓦尔 Shelley Duvall 饰）就发现这里气氛诡异，杰克的儿子丹尼（丹尼·劳埃德 Danny Lloyd 饰）经常看到一些他不认识的人，但这里除了他们一家别无他人。而杰克除了一整天闷头写作外，脾气亦变得越来越古怪。直到有一天，温蒂发现丈夫这些天来一直写就只有一句话：杰克发疯了！©豆瓣', '杰克·尼科尔森', '斯坦利·库布里克', 8.3, 463866, 'tt0081505', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461253191.jpg', 0.6, 1.9, 16.1, 44.5, 36.8, '0.395529,-0.257933,-0.515030,0.494928,-0.161206,-0.462163,0.890775,0.396942,-0.489365,-0.392999,0.172020,0.757450,-0.260714,0.441246,0.129935,0.285019,-0.521189,-0.134401,0.161074,-0.253106,-0.212139,-0.461061,-0.024046,-0.558536,-0.033608,-0.003374,-0.034281,0.037050,0.251974,0.371798,0.131128,-0.137598,0.006229,0.683154,-0.259633,0.018873,0.178635,-0.112855,0.060270,0.248313,0.005507,0.145657,-0.342131,0.121468,0.127056,0.288803,0.453284,0.152203,-0.208441,0.143576,0.050942,-0.035186,-0.095316,-0.074318,0.416539,-0.528482,0.374221,0.100487,-0.205169,-0.005184,-0.009564,0.034554,-0.372754,0.361822,-0.222958,0.215248,-0.245220,0.267918,-0.171873,-0.239210,-0.146065,-0.608330,0.265909,-0.002064,0.115418,0.386956,-0.113683,-0.079172,-0.627070,-0.057689,0.555681,-0.331739,0.063492,0.485907,-0.194400,-0.184617,0.146113,0.167174,-0.401165,-0.118572,0.221649,-0.138445,-0.263185,-0.417483,-0.581098,0.039405,-0.106500,-0.440216,-0.072765,-0.306391,-0.066972,-0.583153,0.076934,-0.164624,-0.276893,0.192805,-0.051443,0.094428,0.506142,-0.567912,0.246126,0.435122,0.279429,-0.158805,0.634398,-0.105108,0.141558,0.061970,0.033775,0.052690,-0.057388,0.249142,0.366598,0.494854,0.024382,-0.211410,-0.132542,0.481972', '1309172', '1296534', '3055049', '1296500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292226', '2001太空漫游', '科幻', '这部影片是库布里克花了四年时间制作的充满哲学命题的鸿篇巨制。一块大黑石树立在史前人类的面前，他们刚刚开始认识工具，进入到进化的里程碑。同样的黑石还在宇宙多处出现，它们矗立在月球上，漂浮在太空中，带着某种神秘的寓意。现在的时间是2001年，为了寻找黑石的根源，人类开展一项木星登陆计划。飞船上有冬眠的三名宇航员，大卫船长（凯尔·杜拉 Keir Dullea饰）、富兰克飞行员（加里·洛克伍德 Gary Lockwood饰），还有一部叫“HAL9000”的高智能电脑。HAL在宇宙飞行过程中发生错乱，令到富兰克和三名冬眠人员相继丧命，剩下波曼和这台电脑作战。从死亡线上回来的大卫一气之下关掉主脑系统，HAL彻底失效。现在，茫茫宇宙中只剩大卫一人，向木星进发。穿越瑰异壮观的星门，大卫仿佛去到一个奇特的时空，那里有人类无尽的生死轮回和宇宙的终极知识……©豆瓣', '凯尔·杜拉', '斯坦利·库布里克', 8.9, 291963, 'tt0062622', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560717825.jpg', 0.9, 1.7, 9.3, 28.9, 59.1, '0.190842,0.307668,-0.850931,0.519948,0.037299,-0.098290,0.746271,-0.207215,-0.349369,-0.043566,0.225999,0.722973,-0.118678,0.002973,0.216705,-0.038937,-0.648072,-0.352701,-0.294230,-0.251451,-0.640930,-0.529176,-0.486258,0.023096,0.105723,-0.574100,0.756105,0.065533,-0.200190,0.161187,-0.172607,0.243691,-0.389309,0.267142,-0.205375,0.062946,0.102155,-0.090352,-0.292529,0.315444,-0.286386,0.068063,0.011385,-0.205385,-0.208344,0.057851,0.675610,-0.313737,0.085970,-0.129922,0.348809,-0.158454,-0.185848,-0.288696,0.394294,0.105393,-0.293284,-0.138625,-0.123802,0.243270,0.045015,-0.182109,-0.900883,-0.379948,-0.202621,0.381723,-0.168430,0.263887,-0.092625,-0.079089,0.080228,-0.451258,0.194336,0.259305,0.321323,0.377573,-0.067728,0.034786,-0.605202,0.081262,0.288197,-0.204272,-0.496110,0.258867,0.056594,-0.587481,-0.553691,-0.127287,-0.443534,-0.293391,0.466981,0.146700,-0.162577,0.337465,-0.902146,0.498308,-0.118576,-0.639801,-0.039935,-0.106714,-0.264007,-0.844843,-0.075659,-0.299874,-0.175581,0.147119,0.076952,-0.348703,0.665531,-0.473847,0.586779,0.559690,0.258370,0.193919,0.839214,-0.205880,0.177894,-0.372142,0.058027,0.177570,0.056427,0.619135,-0.036289,0.352436,0.134777,0.206276,-0.675125,0.524674', '1293433', '26577354', '26290398', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292228', '不准掉头', '剧情', '曾是网球选手的博比（西恩•潘 Sean Penn 饰）最近霉运缠身，先是欠下赌债被债主砍去手指，继而在前往拉斯维加斯还债途中汽车竟然在一个偏僻的小镇苏必略抛锚了。然而，倒霉透顶的博比怎么也没有想到，他的恶运其实刚刚开始。在苏必略，博比先是被修车工敲诈，强行扣下了他的车；然后，他在商店又遭到了抢劫，最后，万分郁闷的他甚至在酒吧喝闷酒都被一个不明所以的青年纠缠，硬是说他和自己女友有染，两人甚至大打出手。就在此时，博比遇到了一位神秘美女格雷斯（詹妮弗•洛佩兹 Jennifer Lopez 饰）。当他们正在进行好事时，撞见了格雷斯的丈夫杰克。出人意料的是，杰克竟然要求博比干掉格雷斯！怪事一桩接一桩，完全摸不着头脑的博比最终何去何从？©豆瓣', '西恩·潘', '奥利佛·斯通', 8, 13980, 'tt0120399', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2574398367.jpg', 0.5, 2.1, 19.5, 51.1, 26.8, '0.365706,-0.082648,-0.853490,0.351715,-0.312002,-0.589038,0.771910,0.177359,-0.324048,-0.255353,0.456522,0.649032,-0.259085,0.053605,0.387572,-0.065011,0.004273,-0.515909,0.236188,-0.120809,-0.585387,-0.426698,-0.124276,-0.232568,0.075401,-0.102285,0.037537,0.147390,-0.199013,0.271429,0.528807,0.350492,-0.036147,0.622022,-0.448694,0.401948,0.345889,0.119657,0.217367,0.133285,-0.013685,-0.408216,-0.148579,0.110921,-0.015465,0.548068,0.476726,0.132566,-0.147941,0.181934,0.156742,-0.260427,0.006385,0.108922,0.318987,-0.254630,0.163470,-0.091921,-0.243817,-0.070592,0.539332,0.173665,-0.534886,0.359762,-0.338129,-0.024288,-0.662621,0.440848,-0.158330,0.040831,0.001498,-0.246731,0.190432,0.371904,0.309151,0.240202,-0.005663,-0.028982,-0.654815,0.202056,0.674949,0.072528,0.022846,0.404672,0.070181,-0.182910,0.008241,-0.038837,-0.332649,-0.042149,0.638635,-0.304082,-0.178334,0.194670,-0.356379,-0.169099,-0.371761,-0.112409,-0.116069,-0.306084,-0.240999,-0.542795,0.157299,-0.161971,-0.190716,0.262564,-0.016728,-0.097073,0.229993,-0.585033,0.153032,0.694311,0.122919,-0.448182,0.490118,0.147916,0.071683,0.073909,-0.186487,0.036928,0.376066,0.395782,0.442939,0.304858,-0.008823,-0.157994,-0.105217,0.395696', '1303462', '1947080', '3011051', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292229', '天生杀人狂', '剧情', '米基（伍迪·哈里森 Woody Harrelson 饰）和梅乐丽（朱丽叶特·刘易斯 Juliette Lewis饰）有着同样残缺的家庭，深种在他们内心暴力的种子在渐渐萌芽成长。梅乐丽从小就备受父亲虐待，她决定和只有一面之缘的米基一同出走，出走前把父母都杀死。米基要梅乐丽从今起开始新生活，他们举行婚礼后，便开始了一边逃亡一边杀人的疯狂旅程。在途中，死于二人手下的人无数。道德和法律已经完全被他们的观念清空。他们疯狂地杀人，疯狂地相爱，手上染满各种人的鲜血。这个离奇的事件，被电视当作肥皂剧来娱乐大众。他们成为青少年崇拜的偶像的同时，也成为了阶下囚。然而，监狱对于他们来说，不过是一个新的杀人场所。他们点燃了监狱里犯人们的凶暴欲念，一场登峰造极的混战轰烈上演。©豆瓣', '伍迪·哈里森', '奥利佛·斯通', 7.9, 108477, 'tt0110632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1640827366.jpg', 2.2, 4.5, 20.5, 39.5, 33.3, '0.454024,0.015482,-0.740232,0.465471,-0.006928,-0.102028,0.784739,0.010221,-0.419844,-0.058097,0.239811,0.829174,-0.314661,0.417243,0.302620,-0.397812,-0.339983,-0.935511,-0.273891,-0.163881,-0.310911,-0.340919,-0.178114,-0.339437,-0.140387,-0.105076,0.768594,0.100400,-0.189317,0.602637,0.399892,0.416999,-0.051741,0.481731,-0.320281,0.161984,0.046792,-0.150325,-0.327505,-0.044558,0.029647,-0.139789,0.031956,0.151288,-0.029510,0.167003,0.904306,-0.325813,-0.062775,-0.389501,0.473009,-0.496256,-0.289513,0.389189,0.245719,0.132783,0.256047,0.102997,-0.042407,-0.022065,0.007084,-0.199954,-0.897522,-0.179347,-0.054909,0.057781,-0.439229,0.461477,0.035753,0.028923,0.139110,-0.201845,0.166713,0.166929,0.320303,0.443190,-0.398329,-0.300740,-0.648193,0.230111,0.840215,0.018321,-0.153498,0.183387,-0.185595,-0.304044,-0.152827,-0.326694,-0.357098,-0.288752,0.373325,-0.027516,-0.317319,0.622459,-0.701648,-0.087152,-0.119581,-0.259217,0.227731,-0.395571,-0.251679,-0.625154,-0.191163,-0.420379,-0.391682,0.048867,0.021704,-0.276358,0.788623,-0.686185,0.348233,0.412753,0.247977,-0.596547,0.543474,0.019888,0.237554,0.007138,-0.261137,0.397420,0.108841,0.425217,0.290332,0.426834,-0.012114,0.211961,-0.413262,0.622673', '25928048', '30162520', '25828589', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292230', '刺杀肯尼迪', '剧情', '肯尼迪的遇刺成为了一桩美国历史上的悬案，电影重新审视了那一段历史，到底杀手是一个普通人，还是整个庞大的政治阴谋，真相和幻象，都在调查中渐渐露出端倪。总统遇刺的两小时内，官方认定的凶手即被逮捕，他就是里·哈威·奥斯瓦多。然而巧合的是，在随后的一个小时，这个嫌疑犯却火速被 一名流氓杀死。经过调查，官方还是认定里·哈威·奥斯瓦多为真凶。但是，三年后的一个美国地方检察官吉姆·加里森（凯文·科斯特纳 Kevin Costner 饰），却发现肯尼迪中弹的蹊跷，从而推测当年官方的误判，接下来，他的侦查牵连着一个历史上的惊天阴谋。©豆瓣', '凯文·科斯特纳', '奥利佛·斯通', 8.8, 34175, 'tt0102138', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2185846004.jpg', 0.3, 0.9, 9.4, 35.6, 53.8, '0.468486,0.147237,-0.634839,0.650288,-0.085583,-0.103768,0.832260,-0.415927,-0.687193,-0.337260,0.308702,0.913382,-0.328141,0.125365,0.237174,0.074928,-0.447060,-0.888341,0.011457,-0.761611,-0.357014,-0.750842,-0.777980,-0.318066,0.153075,0.140060,0.451203,0.475690,-0.157374,0.281038,0.448165,0.303220,-0.153539,0.368930,0.085129,0.003714,0.403376,-0.264618,0.093820,0.257648,0.074661,-0.539232,0.053571,0.279686,-0.384527,0.746256,0.426875,-0.364183,-0.328199,-0.252105,0.586261,-0.498649,-0.282322,0.053670,0.663778,0.250551,0.153913,0.574774,-0.319989,-0.231083,-0.018765,0.050031,-0.957081,-0.139630,-0.022589,0.520579,-0.451412,0.388754,-0.160227,0.022716,-0.134133,0.025904,0.337847,0.537695,0.285678,0.320010,-0.069730,0.096134,-0.436000,0.165988,0.578082,-0.004584,-0.408068,0.129803,0.029704,-0.531253,0.042439,-0.261017,0.020948,0.072937,0.405413,-0.100151,-0.188630,0.275028,-0.271995,0.117602,-0.609874,0.004517,-0.412121,-0.200629,0.000203,-0.553967,-0.259894,-0.219356,-0.252767,0.005492,0.151118,-0.241264,0.443085,-0.514668,0.093234,0.541964,0.054542,-0.393148,0.459072,0.216274,0.171879,-0.145592,-0.027408,0.069502,0.173051,0.322367,-0.067869,0.505532,0.245717,-0.643675,-0.446757,0.264389', '1307442', '3119246', '1920730', '30216729');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292233', '发条橙', '剧情', '阿利斯（马尔科姆•麦克道尔）是一位无恶不作的少年，他的特殊喜好是边听贝多芬的交响曲边奸淫女性，某次他进入一所别墅抢劫一番后，打残了该别墅的主人——一名小说家，并用特殊喜好蹂躏了其妻子。后来因为杀了一名单身女子，阿利斯入狱并接受了特殊的人格治疗，出狱后，他对淫乐之事产生彻底的厌倦。但当阿利斯回到家时，周围人群没改变对他的旧看法，在种种歧视的重压下，他跑到郊外一所别墅想喘口气，不想这所别墅正是他以前抢劫过的小说家的那所。而作为反政府组织首领的该小说家为了达到某种目的，软禁了阿利斯。当这件事暴露小说家被捕时，其手下为了对抗政府，扬言要把阿利斯恢复原来的性情，完全不理一旁的阿利斯大叫“我完全好了”。©豆瓣', '马尔科姆·麦克道威尔', '斯坦利·库布里克', 8.6, 342649, 'tt0066921', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p529908155.jpg', 0.6, 1.4, 11.8, 38.9, 47.3, '0.506683,0.066192,-0.476108,0.435621,-0.252063,-0.303898,0.757448,0.046096,-0.638148,-0.456600,0.270824,0.612187,0.010239,0.259385,0.236010,0.080538,-0.355057,-0.493399,-0.074201,-0.179951,-0.308975,-0.501349,-0.039730,-0.127076,-0.216736,-0.244691,0.326984,-0.007069,-0.531266,0.129507,0.217131,0.471686,0.153147,0.263550,-0.054255,-0.018984,0.029370,-0.075108,-0.156482,0.170813,0.071891,-0.268712,-0.113499,0.266856,-0.151447,0.324502,0.420945,-0.210030,-0.246149,-0.260985,0.209377,-0.158805,0.005418,0.461687,0.257741,-0.129158,0.264121,0.247470,-0.075210,-0.092772,-0.116966,0.059747,-0.599955,-0.238053,-0.181705,-0.074424,-0.417515,0.263898,-0.208995,-0.021624,0.076343,-0.345956,-0.001154,0.280753,0.026579,0.471829,-0.142803,-0.009262,-0.531710,0.145109,0.760802,-0.028542,-0.146867,0.204946,-0.219268,-0.413863,-0.100270,-0.206748,-0.316584,-0.152806,0.185832,0.155118,-0.201265,0.058595,-0.361183,-0.447576,-0.285084,-0.178193,-0.066170,-0.282291,-0.120107,-0.264026,-0.150708,-0.213708,-0.126976,-0.053686,0.075293,-0.197571,0.375818,-0.890426,0.336601,0.530609,0.178922,-0.732302,0.246708,0.037830,0.154358,-0.113843,-0.158388,0.259647,0.277052,0.565854,0.111921,0.280501,0.253060,-0.424950,-0.453245,0.405385', '1308755', '1293265', '25721544', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292234', '漫长的婚约', '剧情', '法国女孩马蒂尔达（奥黛丽·托图 饰）因为小儿麻痹而落下残疾，同村的男孩马涅克（加斯帕德·尤利尔 饰）是她青梅竹马的情人，二人已定下婚约，但是，随着一战的爆发，马涅克应征入伍，婚约也变得遥遥无期。战争持久而残酷，但是马蒂尔达认为自己和马涅克之间有奇妙的感应，她坚信马涅克还活着。1920年，马蒂尔达收到噩耗：五名法国士兵因自残罪名被本国军事委员会判处死刑，扔到敌方的“黄昏宾果”战壕前等死，其中最年轻的一个就是马涅克。马蒂尔达开始艰难的寻找真相，她找私家侦探调查，托人查看军方的相关文件，锲而不舍察访“黄昏宾果”战壕的幸存者，为此不惜耗尽了父母留下的遗产。寻找的过程痛苦而漫长，马蒂尔达仿佛亲身经历了战争的恐怖，也知道了“黄昏宾果”战壕更多不为人知的秘密……©豆瓣', '奥黛丽·塔图', '让-皮埃尔·热内', 8.1, 66428, 'tt0344510', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p803957472.jpg', 0.2, 1.4, 19.6, 49.3, 29.5, '0.080037,-0.236776,-0.517474,0.489539,0.160493,-0.341510,0.542021,-0.055020,-0.482274,-0.394848,0.273103,0.498558,-0.211582,-0.153825,0.307843,-0.244022,-0.277705,-0.694271,-0.018359,-0.002803,-0.438034,-0.636871,-0.250270,-0.231068,-0.247059,-0.204139,0.439706,0.232844,-0.002085,0.321572,0.261370,0.474316,-0.089326,0.341860,-0.029876,-0.167557,0.138109,-0.144476,-0.205031,-0.061442,0.112235,-0.036564,0.086425,-0.155787,-0.104788,0.424241,0.551995,-0.093570,0.057583,-0.289512,0.368723,-0.174764,0.110322,0.086222,0.378406,0.140577,-0.086702,0.312987,-0.068618,-0.362664,0.039076,-0.054711,-0.621253,0.296349,-0.008043,0.138826,-0.367699,0.186800,-0.265228,0.227486,0.346752,-0.120666,0.086138,0.577864,0.189927,0.089584,-0.223653,-0.076647,-0.715588,0.014037,0.451757,-0.358080,-0.195839,0.153868,-0.242119,-0.626215,-0.032662,-0.293114,-0.188628,0.120094,0.185584,0.197398,-0.153866,0.408475,-0.431927,-0.025609,-0.530164,-0.162581,-0.106078,-0.205721,-0.293245,-0.612542,-0.222530,-0.249918,-0.376877,0.108865,0.076722,-0.108451,0.650769,-0.175493,0.386903,0.559216,0.416879,-0.290039,0.624152,-0.042956,0.116008,-0.197936,0.102236,0.676491,0.031141,0.106012,0.224877,0.019824,-0.120426,-0.034593,-0.162819,0.599778', '26636537', '1307442', '1291852', '2147874');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292238', '甘地传', '剧情', '本片记录了印度圣雄甘地史诗般传奇伟大的一生。1893年，24岁的甘地（本•金斯利 Ben Kingsley 饰）受邀前往南非任律师职，决心在当地带领印度移民开展非暴力不合作的抗议活动，并因此入狱。出狱后甘地回到祖国，在三八朗地区建立了高僧修行所，加入了国大党领导的印度独立运动，宣传非暴力不合作的斗争理念。运动中甘地曾四次入狱；在其不懈努力及国大党的带领下，印度独立终于提上议事日程，甘地也于1931年赴伦敦参加商讨独立的圆桌会议。然而随着独立的临近，印度国内穆斯林与印度教人民之间的宗教矛盾日益突出，甘地的非暴力不合作理念又面临着更为严峻的新挑战……本片获1982年奥斯卡最佳影片，最佳导演（理查德•阿滕伯勒Richard Attenborough），最佳男演员（本•金斯利），最佳原创剧本，最佳艺术指导，最佳摄影，最佳服装设计和最佳剪辑共八项大奖，并获奥斯卡最佳化妆，最佳电影音乐和最佳音效三项提名。', '本·金斯利', '理查德·阿滕伯勒', 8.5, 34402, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2193944770.jpg', 0.4, 1, 12, 44.2, 42.4, '0.089879,-0.005821,-0.604805,0.483034,0.446960,-0.325471,-0.158919,0.156595,-0.249460,-0.378570,0.099781,0.726819,-0.098163,-0.206228,0.414707,-0.368836,-0.486291,-0.874528,-0.338198,-0.061057,0.098272,-0.609418,-0.264741,-0.023274,-0.312776,-0.215923,0.897463,-0.019510,-0.396362,0.638091,0.610320,0.030882,-0.007533,-0.054654,0.080292,-0.317827,0.466764,-0.055821,-0.775898,0.393322,-0.038007,-0.365597,-0.224714,-0.175277,0.290987,0.339627,0.276150,-0.439426,0.130089,-0.077450,0.584884,-0.111197,-0.372018,0.252186,0.231465,0.035019,0.229538,0.576936,-0.070999,0.247983,-0.252079,-0.584767,-0.656826,-0.168300,0.111164,0.051495,-0.395424,0.582527,0.028449,0.101198,-0.087927,0.195974,-0.042108,0.673678,0.338764,0.226626,-0.037037,0.078724,0.026789,0.699615,0.272206,0.130548,-0.318473,-0.051769,-0.247196,-0.778935,-0.081861,-0.515052,-0.099878,-0.293239,0.249178,0.147498,0.116675,0.091514,-0.647829,0.050063,-0.140426,-0.243618,0.088982,-0.005083,0.443409,-1.138683,-0.054439,-0.129397,0.194862,-0.074337,0.084770,-0.337603,0.782254,-0.633054,0.204425,0.344509,0.276752,-0.567258,0.657579,0.355692,0.387814,-0.547668,-0.201818,0.358932,-0.209085,0.283538,-0.290485,0.108463,0.080546,-0.208404,-0.319474,0.157143', '24