INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292260', '现代启示录', '剧情', '越战后期，美军上尉威拉德（马丁•辛 Martin Sheen 饰）奉命沿湄公河而上，搜寻脱离美军在柬埔寨建立了自己的王国的科茨（马龙•白兰度 Marlon Brando 饰）上校，将他带回或杀死。科茨上尉曾经是美军在越战中的英雄，战功赫赫。然而，忽然有一天，他失踪了。随 后，情报指出他在柬埔扎建立了自己的王国，自己的军队，专门反对美军。威拉德与几名士兵一路沿河而上，途中他们目睹了种种暴行、杀戮，目睹了无论美军士兵还是当地人在长期的战争中精神扭曲，做出的种种非正常的行为，威拉德感到了极大的震撼。威拉德最后在柬埔寨科茨的王国中被当地人捉住，见到了科茨。然而，科茨竟欲求一死，叫威拉德将这里炸为平地……©豆瓣', '马丁·辛', '弗朗西斯·福特·科波拉', 8.5, 99443, 'tt0078788', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2501047088.jpg', 0.5, 1.6, 13.3, 41.2, 43.4, '0.388514,0.029034,-0.852033,0.572991,0.171677,-0.101551,0.430359,0.009581,-0.553063,-0.059068,0.387523,0.695744,-0.102096,-0.225236,0.238243,0.011196,-0.548054,-0.696806,-0.137348,-0.027393,-0.273688,-0.525692,-0.687148,-0.364735,-0.077082,-0.634119,0.493416,0.222256,-0.263882,0.629667,-0.029235,0.513210,0.031269,0.542012,-0.064514,0.239747,0.251809,-0.288450,-0.103310,0.160803,-0.097751,-0.577421,-0.222452,0.391859,-0.073030,0.542453,0.593566,-0.596923,0.343195,-0.078149,0.063182,-0.502577,0.237505,0.056685,0.146733,-0.122423,0.123130,0.133748,-0.256177,-0.046612,0.097643,-0.022704,-0.552915,-0.057096,-0.100671,0.121567,-0.532545,0.431128,-0.338765,0.132795,0.000523,-0.257618,0.067907,0.500858,0.047401,0.215710,-0.282593,-0.272185,-0.547329,-0.104422,0.739734,-0.128619,-0.333690,-0.262783,-0.284610,-0.410832,-0.027525,-0.534424,-0.238546,-0.186462,0.247159,0.041776,0.064687,0.417122,-0.801510,0.082347,-0.671087,-0.222674,-0.267638,-0.066217,-0.363027,-0.698966,-0.110400,-0.324164,-0.287349,0.032542,0.062388,-0.028851,0.479956,-0.697188,0.202713,0.400871,0.409749,-0.178310,0.606895,-0.228690,0.102831,0.210629,-0.003964,0.225670,0.239868,0.389360,0.376970,0.366528,-0.245140,-0.135261,-0.078048,0.701028', '34461680', '1302987', '6982558', '26316956');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292262', '美国往事', '剧情', '1933年，纽约流氓Noodles（罗伯特·德·尼罗 饰）因向哈洛伦警司（布鲁斯·巴伦堡 饰）通风报信害死了三名同伙而被追杀。逃亡之前，他打开了存放帮派基金的手提箱，里面却只有报纸。 1968年，已改名换姓的Noodles收到一封犹太会堂通知迁葬亲友的信。Noodles联系拉比，得知信是八个月前寄出的，他的三名同伙已被迁葬至一所豪华公墓。Noodles回到纽约，找老友莫（拉里·拉普 饰）了解情况，却一无所获。闲谈中，Noodles问起莫的妹妹黛博拉（伊丽莎白·麦戈文 饰）的情况，得知其已成名角。 原来，两人少时互有好感，但黛博拉（詹妮弗·康纳利 饰）志向高远脚踏实地，理智地将街头混混Noodles（斯科特·提勒 饰）拒于门外。 Noodles在公墓发现了一把钥匙，并用钥匙打开了当年存放手提箱的储物柜。这一次，箱子里有满满的百元钞，还有写着“下一份工作的预付款”的纸条……', '罗伯特·德尼罗', '赛尔乔·莱昂内', 9.2, 386154, 'tt0087843', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p477229647.jpg', 0.2, 0.5, 5.7, 27.5, 66, '0.356552,0.088797,-0.538657,0.425479,0.057611,-0.345560,0.800244,0.062116,-0.465502,-0.390798,0.009748,0.293692,-0.071729,0.317445,0.458064,0.034519,-0.402373,-0.594686,0.006993,-0.563733,-0.343927,-0.311103,-0.402626,-0.220997,0.026599,-0.199415,0.138756,-0.007512,0.146713,0.528331,0.198803,0.381060,-0.361699,0.201848,0.134878,0.161110,0.179841,0.000880,-0.222715,0.102263,-0.113938,-0.222103,-0.004887,-0.034634,0.406040,0.399560,0.641899,-0.142456,0.102560,0.083100,0.314091,0.183223,-0.131290,0.108873,0.295831,0.369515,-0.097718,0.288456,-0.429678,-0.026986,0.195122,-0.239237,-0.245678,0.059497,0.014872,0.247184,-0.545361,0.459267,-0.538733,0.329115,-0.312299,-0.314921,0.167299,0.092921,-0.005065,0.207420,0.173248,-0.098607,-0.765819,-0.096245,0.013478,-0.267986,0.186384,-0.065818,0.098445,-0.399204,0.102347,0.248132,-0.152920,0.094496,0.539137,-0.134532,-0.015697,-0.072915,-0.495143,-0.281541,-0.593906,-0.063825,0.163397,-0.108925,-0.284992,-0.682555,-0.140876,0.003935,-0.210088,0.097072,0.084161,0.044592,0.570958,-0.266292,0.051646,0.324282,0.262146,-0.198450,0.537130,-0.157580,0.173359,-0.010147,-0.034779,0.282090,0.435252,0.486012,0.232394,0.176676,-0.178187,-0.443914,-0.190867,0.159743', '1578663', '10466639', '1297659', '1401900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292264', '逃狱三王', '喜剧', '影片由家喻户晓的科恩兄弟导演，电影原声大碟获得第44届格莱美最佳年度专辑大奖。30年代初，密西西比州荒野的监狱里，唠唠叨叨、油嘴滑舌的艾弗瑞特（乔治·克鲁尼 George Clooney 饰）整天打着各种逃跑的鬼主意。在成功说服了狱友——头脑简单的德尔玛（蒂姆·布雷克 ·尼尔森 Tim Blake Nelson 饰）和贼大胆的皮特（约翰·特托罗 John Turturro 饰）之后，艾弗瑞特的越狱大计终于得以实现，三个穿着犯人服、拖着手铐、脚镣的罪犯叮叮当当地踏上了通往自由之路。据艾弗瑞特说，在密西西比河边还埋藏有一大笔赃款赃物。逃亡途中，他们不仅要对付各种各样令人棘手的突发事件，还要与追捕他们的执法官库利斗智斗勇。这个锲而不舍的家伙发誓要把这三个“脱网之鱼”送回监狱。这一路上意外不断，状况百出，究竟他们能否获得真正的自由？©豆瓣', '乔治·克鲁尼', '乔尔·科恩', 7.9, 57780, 'tt0190590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p794606009.jpg', 0.5, 2.5, 23.9, 49.6, 23.5, '-0.131592,-0.103566,-0.458162,0.607245,0.244987,-0.325416,0.394864,0.024278,-0.375955,-0.040373,0.058136,0.500182,-0.226433,-0.104841,0.197194,-0.053943,-0.585818,-0.573170,-0.018007,-0.111309,-0.217832,-0.433071,-0.359990,-0.123682,-0.058033,-0.206863,0.343443,0.120327,-0.069640,0.391660,0.572955,0.232331,-0.218673,0.068864,-0.321509,0.113050,0.527033,-0.047244,-0.236248,0.299150,0.052769,-0.120523,-0.186513,-0.062031,0.217857,0.281644,0.665234,-0.361666,0.062235,0.325165,0.384493,-0.354678,-0.200992,0.076943,0.016892,-0.188191,0.222271,0.255027,0.042928,0.135161,0.175031,-0.186465,-0.742908,-0.199341,-0.032922,0.010312,-0.542359,0.073145,-0.122159,0.308934,0.165129,-0.258409,0.122398,0.410259,0.205867,0.248949,0.016852,-0.245385,-0.664423,0.125806,0.330272,-0.072733,-0.148143,0.135346,0.033085,-0.375287,-0.005830,-0.223063,-0.418396,-0.121874,0.617003,-0.209580,-0.110912,0.017522,-0.456527,0.060750,-0.200728,-0.161813,0.006136,-0.177776,-0.120678,-0.644248,0.122350,-0.181253,-0.122108,0.052342,-0.030447,-0.207335,0.375139,-0.484910,0.210661,0.698831,-0.047882,-0.327438,0.339676,0.208934,0.194895,-0.149656,-0.321929,-0.058409,0.267060,0.470008,0.117063,0.490553,-0.043695,-0.326931,-0.463917,0.292879', '1300324', '1301345', '1307442', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292267', '银河系漫游指南', '喜剧', '每个人都曾经历过懊恼糟糕的早晨。懒床睡过了点，起床弄伤了脚趾，下楼磕了头，早餐烤焦了面包，阿瑟· 登特(马丁·弗里曼饰)的这个早上可谓衰运当头，而且还远不止这些。政府已经决定拆掉他的房子，好友福特·普里弗克特(摩斯·德夫饰)承认自己是个外星人，正在地球上寻找新版《银河系漫游指南》。最耸人听闻的是，外星人正在建造银河系高速公路，而地球是阻挡工程进展的障碍物，外星人即将摧毁地球。在福特的帮助下，阿瑟·登特在地球被毁灭前的最后一刻搭上了一艘路过地球的外星人的太空船，远离这个即将毁灭的伤心地，开始了一段充满惊奇的星河探险。在太空之旅中，阿瑟发现毛巾是宇宙里最有用的东西，并体会到了生命的精确含义，更发现所有他需要知道的一切居然都写在一本名叫《银河系漫游指南》的电子图书里……©豆瓣', '比尔·贝利', '加斯·詹宁斯', 8.1, 113339, 'tt0371724', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1985335323.jpg', 0.8, 3, 19.8, 43, 33.5, '0.309036,0.078221,-0.872808,0.397875,-0.066313,-0.287594,0.668261,-0.106045,-0.294235,-0.035166,0.214609,0.547186,-0.197302,0.149944,0.407705,0.229544,-0.413579,-0.342386,0.059024,-0.268750,-0.600340,-0.550746,-0.507848,-0.024207,0.103903,-0.283937,0.437714,0.140390,-0.090560,0.146437,-0.063547,-0.019300,0.112969,0.628278,-0.404657,0.209242,-0.014085,-0.073109,-0.056723,-0.035778,-0.250219,-0.005267,0.082378,0.374172,-0.116136,0.275725,0.379098,-0.263649,-0.039098,-0.054992,0.406356,-0.190207,-0.126337,-0.011734,0.465046,0.005232,-0.222414,-0.031906,0.078659,0.218230,0.075485,0.096684,-0.826560,-0.384660,-0.154888,0.139584,-0.516736,0.385087,-0.153634,0.044052,-0.100981,-0.501948,0.407765,0.268642,0.169074,0.598708,0.033550,-0.012290,-0.578309,0.126931,0.332676,-0.100601,-0.222243,0.623948,-0.068922,-0.278917,-0.094942,0.010174,-0.313869,0.000278,0.156571,-0.005347,-0.296363,0.378249,-0.762299,0.239731,-0.233517,-0.677165,-0.000106,-0.270840,-0.281685,-0.626018,-0.091095,-0.324454,-0.195663,0.144052,0.054411,-0.242207,0.500595,-0.509859,0.332151,0.788358,0.137126,-0.063878,0.489109,-0.016624,0.045864,0.007290,0.071239,0.449015,0.122086,0.702050,-0.084250,0.516089,0.191251,-0.101418,-0.481662,0.679882', '1295292', '1308784', '26839466', '1907966');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292268', '好家伙', '剧情', '本片根据真实故事改编，讲述了纽约黑手党血腥的江湖恩怨，把所谓的“江湖道义”还原为人性的丑陋与贪婪。亨利•希尔（雷•李欧塔 饰）从小不学无术，跟着老大保利，靠收取保护费、走私、抢劫，他娶了美丽的妻子凯伦，有可爱的女儿，迷人的情妇，名车豪宅，生活优渥。吉米•康维（罗伯特•德尼罗 饰）和汤米（乔•佩西 饰）是亨利的好朋友，三人一起经历和很多事情：杀死羞辱汤米的意大利黑手党头领比利•贝兹；策划德航劫案，并干掉同伙，私吞赃款；甚至背着老大保利贩毒。当然，他们的生活，除了享受金钱带来的权势之外，更多的，是朝不保夕的动荡：汤米因为比利•贝兹的死，被人枪杀；亨利自己因为贩毒被警方逮捕，其他人也受到牵连。凯伦想尽办法将亨利保释出来，此时他们已经一无所有，被人孤立，危机四伏。他们要想尽办法活下去，无论以怎样的方式，付出怎样的代价……©豆瓣', '罗伯特·德尼罗', '马丁·斯科塞斯', 8.5, 106721, 'tt0099685', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1403069323.jpg', 0.2, 0.8, 12.2, 48.7, 38.2, '0.173385,-0.257592,-0.400732,0.300798,-0.364221,-0.190422,0.738585,0.062388,-0.465072,-0.204173,0.081947,0.696618,0.107245,0.097090,0.177540,0.058262,-0.268321,-0.627962,-0.005543,0.083088,-0.043099,-0.652261,-0.218366,-0.475761,-0.012562,-0.127363,0.432498,-0.013277,-0.085890,0.384937,0.368876,0.286334,-0.133544,0.156563,-0.088270,0.049293,0.078825,-0.099409,-0.584330,-0.158970,-0.153931,-0.171839,-0.051063,0.080475,0.006408,0.223390,0.378723,-0.071837,-0.069397,-0.224790,0.272168,-0.453557,0.026382,0.121760,0.099883,-0.255168,0.243109,0.491484,-0.132594,-0.185893,0.179575,0.073277,-1.018634,-0.113080,0.198193,0.011160,-0.630887,0.316209,-0.101347,0.084893,0.152985,-0.040800,0.200554,0.284451,0.286144,0.085340,-0.063939,0.037667,-0.687701,0.187010,0.751394,-0.215370,-0.009363,-0.048888,-0.280204,-0.201484,-0.041402,-0.466890,-0.444537,0.150963,0.366098,-0.214343,-0.139471,0.436653,-0.464697,-0.224055,-0.139161,-0.114389,-0.084800,-0.483909,-0.180187,-0.510929,-0.367972,-0.377509,-0.287525,-0.113523,0.109038,-0.314831,0.586453,-0.457661,-0.015356,0.512377,0.416585,-0.775308,0.456279,0.000234,0.106464,-0.171866,-0.417581,0.320535,0.507900,0.062336,0.227614,0.061716,0.070355,-0.102170,0.012278,0.495178', '26678784', '30163500', '1299799', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292269', '骗中骗', '剧情', '卢克领导着一个诈骗集团在芝加哥附近的约里埃特行骗。这天，手下人向他交了一大笔刚刚骗了的钱。不久，卢克就遭到了谋杀。原来，这笔钱是芝加哥的黑社会头目朗尼根（罗伯特•肖 Robert Shaw 饰）刚刚收回的赌款，正是这笔钱令卢克引火烧身。胡克（罗伯特•雷德福 Robert Redford 饰）是卢克的一个手下，卢克平日待他如亲生儿子一般，生前就想把他介绍到芝加哥的好友骗术大师冈多夫（保罗•纽曼 Paul Newman 饰）处学艺。胡克发誓要给卢克报仇，于是前往芝加哥寻找冈多夫。胡克顺利找到了冈多夫，听闻这次的对头是朗尼根，冈多夫马上摩拳擦掌。于是，一个天衣无缝的行骗计划开始了！©豆瓣', '保罗·纽曼', '乔治·罗伊·希尔', 8.7, 50681, 'tt0070735', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1227416748.jpg', 0.1, 0.5, 8.9, 44.1, 46.4, '0.133387,-0.104896,-0.603599,0.459405,-0.398700,-0.662001,0.348683,0.100611,-0.243650,-0.131757,-0.044623,0.738766,0.086508,0.142089,0.314622,0.342221,-0.489251,-0.557968,-0.115114,-0.349815,0.040506,-0.714293,-0.085467,-0.032982,-0.205766,-0.213838,-0.164268,-0.096586,0.026497,0.353820,0.329219,0.521456,0.325322,0.045393,0.025220,0.296656,0.315545,-0.235886,-0.060593,0.450921,0.153312,0.069517,-0.173090,0.026546,0.294819,0.673229,0.257488,0.046805,0.164209,-0.102103,0.205255,-0.238774,0.171416,0.097215,0.299144,-0.285523,0.110527,0.320856,-0.490545,-0.180555,0.114742,-0.150131,-0.566521,-0.097152,-0.096112,0.052900,-0.836748,-0.078802,-0.287454,-0.008795,-0.015268,-0.251510,0.254995,0.449925,0.190539,0.046236,0.187303,-0.113003,-0.505557,0.222508,0.561936,-0.068933,0.308511,0.002376,0.217100,-0.174115,0.290875,0.168650,-0.417795,-0.105961,0.715500,-0.327902,-0.009791,0.023914,-0.236323,-0.374036,-0.576525,-0.064209,0.069852,-0.102364,-0.128375,-0.620862,-0.143671,-0.050976,-0.233278,0.009215,-0.060296,-0.032743,0.310034,-0.334242,0.133377,0.659177,0.193714,-0.079011,0.392655,-0.270346,0.134673,-0.119106,0.020364,-0.213951,0.509126,0.331899,0.331053,0.440125,0.313573,-0.390663,0.072001,0.405664', '1292646', '1309069', '1293511', '1295684');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292270', '梦之安魂曲', '剧情', '哈瑞（杰瑞德·莱托 Jared Leto 饰）和玛丽安（詹妮弗·康纳利 Jennifer Connelly 饰）彼此相爱，梦想着开个服装店，梦想着有个美好的明天。然而他们都离不开毒品，并想着以销毒赚得第一桶金。哈瑞的母亲是个彻底的电视迷，最大的梦想是上电视，为此不顾年迈吞食减肥药。由于药品里的毒品成分，她渐渐上了瘾。哈瑞的朋友狄龙（马龙·韦恩斯 Marlon Wayans 饰）同样是个瘾君子，为了挣大钱加入了黑社会。为了梦想，他们努力着，却一步步深陷毒品难以自拔。 哈瑞的胳膊因注射毒品感染而被割去；玛丽安为了毒品出卖肉体和自尊；哈瑞的母亲最终住进了精神病院受尽折磨；狄龙锒铛入狱。当视线变得模糊，梦在遥远处呼唤，迷失的人该以怎样的姿态安抚自己的灵魂。©豆瓣', '艾伦·伯斯汀', '达伦·阿伦诺夫斯基', 8.8, 186299, 'tt0180093', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2328516855.jpg', 0.5, 1.2, 10.2, 36.1, 52, '0.111924,0.087264,-0.411554,0.440561,-0.141186,-0.539715,0.943116,0.169983,-0.397976,-0.316005,0.079620,0.632759,0.197478,0.291003,0.081773,0.210988,-0.269145,-0.546084,-0.129290,0.004612,-0.373097,-0.357372,-0.362659,-0.159376,-0.116529,-0.170228,0.455406,0.147104,-0.183061,0.256104,0.374941,0.373533,0.163286,0.078727,-0.096256,0.029848,-0.059425,-0.126392,-0.371651,0.093484,0.173794,-0.335872,0.049355,0.149797,-0.062591,0.291989,0.678614,-0.149361,0.096898,-0.139047,0.165289,-0.347800,-0.011921,0.157326,-0.165854,0.018690,0.105984,-0.003393,-0.488431,-0.119818,0.316044,-0.005786,-1.026269,-0.273365,0.030116,0.280799,-0.404926,0.455368,0.009540,0.257245,0.080911,-0.216250,0.095294,0.174613,0.168791,0.414034,-0.347919,0.037039,-0.625870,0.316012,0.762982,0.020521,-0.019898,0.471543,-0.512688,-0.364616,-0.078376,-0.207471,-0.585024,-0.159306,0.414199,0.282390,-0.412824,0.400289,-0.473224,-0.037893,-0.022646,-0.100419,0.002797,-0.236010,0.016590,-0.326540,-0.346715,-0.373465,-0.072297,-0.045880,-0.109998,-0.372850,0.468795,-0.525522,0.237100,0.825561,0.124670,-0.473283,0.630839,0.106675,0.004920,-0.168355,-0.291062,0.525588,0.064338,0.204974,0.351450,0.159245,-0.087573,0.120693,-0.278952,0.662590', '30368448', '25828589', '30387441', '1296757');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292271', '毕业生', '剧情', '刚刚走出大学校门的本恩（达斯汀•霍夫曼 Dustin Hoffman 饰）对前途十分茫然，偏偏在这时遇上了风流的鲁滨逊太太（安妮•班克罗夫特 Anne Bancroft 饰 ）。虽然不再年轻，但鲁滨逊太太却一再勾引本恩，二人发生了关系。他们在约会过程中，本恩遇上了太太的女儿伊莱恩（凯瑟琳•罗斯Katharine Ross 饰 ），被她的纯真青春深深吸引。本恩吐露了爱意，与伊莱恩开始了正常的恋爱关系，却遭到了鲁滨逊太太的剧烈反对。母亲的震怒使伊莱恩觉察到了一些内情。伊莱恩非常伤心，仓促同意了另一个人的求婚。本恩冲向伊莱恩结婚的教堂，他要力挽狂澜……©豆瓣', '安妮·班克罗夫特', '迈克·尼科尔斯', 8, 175248, 'tt0061722', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517731298.jpg', 0.4, 1.8, 21.3, 49.4, 27.1, '0.416236,0.009446,-0.685723,0.232825,-0.066494,-0.392928,0.861582,0.239131,-0.261482,-0.333810,0.021726,0.751052,-0.503796,0.489673,0.284172,0.119582,-0.221904,-0.398083,0.073390,0.008002,0.029055,-0.688237,0.277533,-0.331594,-0.039340,-0.377784,0.247726,-0.119385,-0.107885,0.512209,0.279377,0.284433,-0.044111,0.733833,-0.056901,0.390080,0.500883,-0.268399,-0.319426,-0.005642,0.141673,0.047806,0.123955,0.617457,0.167361,0.565197,0.424927,-0.082023,0.048037,0.237033,0.379579,0.183119,0.195472,0.224054,0.315543,-0.225598,-0.092816,0.169331,0.025304,-0.357491,-0.023808,-0.042940,-0.148370,0.203816,0.215397,0.541445,-0.501697,0.358495,-0.271659,-0.231908,0.025826,-0.081578,-0.109388,0.207351,0.212977,0.116706,-0.029897,0.218698,-0.588462,-0.266861,0.581908,-0.049275,-0.057300,0.527645,-0.442675,-0.258637,0.092804,0.037996,-0.525892,-0.095597,0.515964,-0.149965,0.033301,0.593310,-0.323205,-0.342639,-0.348612,0.192528,-0.105791,-0.631697,-0.213471,-0.315090,0.039112,-0.610500,-0.612837,-0.026017,-0.072049,0.009378,0.397704,-0.949804,0.090135,0.599792,0.443431,-0.186066,0.458532,0.219051,0.158579,-0.129081,0.178087,0.457482,-0.088091,0.060412,0.335647,0.524677,0.211114,-0.249971,-0.213117,0.552524', '1308755', '3059036', '4275444', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292272', '大象', '剧情', '美国一所普通高中普通的一日，逃课未果的John（John Robinson），在父亲的逼迫下回到校园；喜欢摄影的Elias（Elias McConnell），在校园内外拍过一些人物和风景后，来到学校暗房冲洗照片；新交了女朋友的Jordan，正被与他有过关系的女孩纷纷议论着；被人冷落情绪异常低落的Michelle，来到学校图书馆帮助做工……校园高墙之外，时常受人欺负的“患难兄弟”Eric（Eric Deulen）和Alex（Alex Frost）正在家里午睡，他们对纳粹形象和暴力游戏非常迷恋，曾在互联网上订购了枪支。午睡过后，两人进行一番简单的策划，身穿美军野战装、手持冲锋枪走进校园，开始大开杀戒。©豆瓣', '阿里克斯·弗罗斯特', '格斯·范·桑特', 7.8, 68799, 'tt0363589', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1156027521.jpg', 0.9, 2.9, 24.3, 46.8, 25.1, '0.667727,-0.271816,-0.733698,0.397264,0.100740,0.020070,0.847649,0.273542,-0.685001,-0.297965,0.174605,0.596322,-0.442956,0.611277,0.250301,-0.389682,-0.493254,-0.714291,-0.206696,-0.144320,-0.219382,-0.321126,0.024147,-0.129758,-0.045731,-0.421012,0.543321,-0.085864,-0.247119,0.613163,0.076564,0.186998,-0.293472,0.436420,-0.401253,-0.249916,0.089087,0.294603,-0.321186,0.159006,-0.071123,-0.329708,-0.189861,-0.232194,0.320144,0.011471,1.026069,0.151022,-0.343323,0.145435,0.345304,-0.016110,-0.162568,0.234896,0.532635,0.145855,0.320921,0.095025,0.141440,0.262982,-0.147061,-0.385584,-0.080195,-0.018417,0.074283,-0.163409,-0.724151,0.682656,-0.122108,-0.108416,0.150416,-0.407199,0.226875,0.298858,0.091326,0.507697,0.008267,0.225003,-0.617251,0.232282,0.638759,0.001521,0.019697,0.283779,-0.034802,-0.170323,-0.011259,-0.135926,-0.478791,-0.237640,0.338448,-0.432431,-0.148875,-0.148056,-0.739519,0.177703,0.158538,-0.397999,0.244191,-0.351897,-0.320884,-1.047219,-0.037438,-0.452672,-0.353246,0.197024,-0.073678,-0.025910,0.588504,-1.150852,0.317335,0.325288,0.380902,-0.500942,0.757225,-0.014284,0.056984,0.101342,-0.263300,0.091231,0.149972,0.454545,0.005956,0.480309,-0.317538,-0.108298,-0.570666,0.147317', '26687241', '3041753', '3155839', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292274', '幸福终点站', '剧情', '为了完成父亲的心愿，维克多（汤姆•汉克斯 Tom Hanks 饰）从故国乘坐飞机前往美国肯尼迪机场，但戏剧性的事情发生了：他被告知祖国发生政变，而他的身份证护照一一失效，同时他的签证也无法再使用。进退两难的维克多只有在机场滞留，等待新证件的办理。但是，他在机场等待了整整9个月。在这9个月里面，他用机场的洗手间洗漱，在候机室睡觉，他已经学懂因地制宜，在机场照料自己的生活，甚至还找了一份建筑工地工作。然而维克多的邋遢晦气却招来了机场负责人弗兰克（史坦利•图齐 Stanley Tucci 饰）的不满，而恐怕更令他气愤妒忌的是，美丽的空姐艾米利亚（凯瑟琳•泽塔-琼斯 Catherine Zeta-Jones 饰）竟然爱上了维克多。处在甜蜜中的维克多，也在慢慢观察机场的人生百态，自得其乐。©豆瓣', '汤姆·汉克斯', '史蒂文·斯皮尔伯格', 8.8, 526323, 'tt0362227', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p854757687.jpg', 0.1, 0.5, 8.5, 39.2, 51.7, '0.340062,0.111870,-0.833019,0.376165,-0.113699,-0.326115,0.587107,0.235313,-0.354421,-0.185656,0.349965,0.759657,-0.089825,0.254928,0.361880,0.014941,-0.660266,-0.585069,0.350328,-0.281460,-0.443485,-0.500124,-0.114592,-0.412504,0.126966,-0.145298,0.366791,0.263029,0.284724,0.380472,0.255993,0.050309,-0.111652,0.808384,-0.326092,-0.021354,0.196452,0.008792,0.032036,0.176236,0.215891,-0.436066,-0.125775,0.234891,0.142041,0.439956,0.778071,0.114783,-0.327085,0.096301,0.328779,-0.384465,0.088410,0.112161,0.170067,0.019706,-0.148904,0.038155,-0.367714,-0.008092,0.172675,0.081884,-0.708859,0.200133,-0.304389,0.096676,-0.482829,0.563607,-0.360820,0.046871,0.120299,-0.404197,0.349760,0.549042,0.057738,0.424662,-0.147003,0.013062,-0.519251,0.299382,0.315340,-0.041917,-0.098459,0.584416,-0.169085,-0.337944,-0.004467,-0.044583,-0.535574,-0.179248,0.193054,0.008152,-0.268749,-0.251740,-0.353045,-0.130829,-0.334787,-0.492692,-0.123632,-0.399528,-0.173913,-0.913334,-0.146336,-0.311846,-0.313201,0.030132,0.126203,0.122434,0.409684,-0.604121,0.166327,0.507510,0.218035,-0.599688,0.724963,-0.015965,0.139006,-0.079197,-0.039423,0.499209,-0.005493,0.650601,0.191643,0.504858,0.041867,-0.033027,-0.491028,0.414317', '3178770', '2159244', '3735015', '2257732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292275', '罗拉快跑', '动作', '罗拉（弗兰卡•波滕特 饰）和曼尼（莫里兹•克雷多 饰）是一对年轻的恋人，其中曼尼是一个不务正业的小混混，而罗拉则是相信“天大的事情有爱情顶着”的爱情至上主义者。一天，曼尼为老大完成一项钻石交易，带着装有10万马克的钱袋等候罗拉的接应，然而罗拉的自行车被人抢走，耽误了约定的接应时间，曼尼只好乘地铁回去。在地铁车厢里，曼尼扶起身边的乞丐，同时，看见两名警察向他走来。慌乱中，曼尼下了车，竟然把钱袋忘在了车厢里。显然，钱袋被乞丐拿走了。此时距离曼尼和老大约定见面交钱的时间只剩下20分钟，如果20分钟之内筹集不到10万马克，曼尼就会被老大杀死。走投无路的曼尼打电话向罗拉求救，如果罗拉20分钟之内不能赶到，曼尼只能铤而走险抢劫电话亭对面的超市。考验罗拉爱情的时候到了，为了在20分钟内筹到10万马克，救出曼尼，她狂奔在向银行家父亲求助的路上。©豆瓣', '弗朗卡·波滕特', '汤姆·提克威', 8.1, 223875, 'tt0130827', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2574867081.jpg', 0.4, 1.7, 18.8, 50.2, 28.9, '0.393808,0.021537,-0.572225,0.206339,-0.310011,-0.546609,0.681727,0.005910,-0.205371,-0.165510,0.246542,0.391098,-0.155000,0.046932,0.541963,0.065768,-0.296002,-0.688919,-0.341674,-0.513749,-0.540897,-0.460718,-0.049284,-0.232679,0.001807,-0.203368,0.226674,0.048255,0.196351,0.639449,0.339305,0.069205,-0.106122,0.233547,-0.280679,0.086597,0.254952,-0.261681,-0.031208,0.552585,0.136707,-0.062100,0.147413,-0.029181,0.168916,0.408729,0.642259,-0.201595,0.113284,0.244594,-0.057977,-0.268189,0.117117,0.087932,0.259726,-0.169720,0.357435,-0.022675,-0.473849,0.086927,0.272058,0.101640,-0.512513,0.055745,-0.442359,0.194306,-0.861265,0.400525,-0.144703,-0.030478,0.454593,-0.459012,0.211478,0.117343,0.122366,0.463893,-0.328590,-0.228105,-0.962985,-0.018832,0.419138,-0.082187,0.341879,0.204463,0.204232,-0.252101,0.085750,-0.011713,-0.350254,-0.072473,0.621509,-0.078456,-0.010007,0.005353,-0.378943,0.046461,-0.371045,-0.317225,0.066467,-0.514759,-0.152939,-0.613871,0.224354,-0.096698,-0.156729,0.501188,0.191381,-0.137180,0.466160,-0.417686,0.230529,0.599428,0.645269,-0.136818,0.934406,-0.166277,0.215161,-0.213645,0.262372,-0.055370,0.246316,0.498693,0.404427,0.328667,-0.099094,-0.251587,-0.499624,0.371210', '1293511', '1293908', '1295324', '1294252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292276', '双面情人', '剧情', '身为公关经理的海伦（Gwyneth Paltrow 饰）却在某天早上遭遇了失业的打击，她满怀失落地走向地铁，命运就在滑动门的左右发生变化。赶上地铁的海伦回到家发现男友的奸情，使得劳燕分飞。为了迎接新的生活，海伦改变了发型，在电梯间邂逅了富有魅力的男子詹姆斯（John Hannah 饰）。新的恋情悄然开始……错过地铁的海伦也错过了男友与情人欢愉的场面，他们的恋情仍在继续。男友小心周旋在两个女人之间，却难免有败露的一天……滑动门机械地一开一关，命运随之悄然改变。©豆瓣', '格温妮斯·帕特洛', '彼得·休伊特', 7.4, 13022, 'tt0120148', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1079337390.jpg', 0.4, 3.7, 34.5, 47.4, 14, '0.377903,0.276300,-0.803761,0.158277,-0.014457,-0.476527,0.890271,0.477689,-0.261282,-0.031860,0.499618,0.588509,-0.528691,0.259997,0.559221,-0.314774,-0.245660,-0.735688,0.119191,-0.092028,-0.305108,-0.195057,-0.080965,-0.099294,0.184446,-0.384765,0.808150,0.152923,-0.210299,0.438253,0.377319,-0.075645,-0.217104,0.519186,-0.146101,0.109131,0.164064,0.271422,-0.325201,0.164592,0.004455,-0.331980,-0.075296,-0.032553,-0.288641,0.266413,0.742243,-0.287667,-0.313803,0.328803,0.611163,-0.004373,-0.142891,-0.039130,0.511149,0.105909,-0.298056,0.163833,-0.347508,0.047661,0.103859,0.326215,-0.448408,0.168764,-0.079548,0.298522,-0.635914,0.529926,0.058094,-0.055028,0.222039,-0.492502,0.071872,0.588713,0.346796,0.551896,-0.157381,0.340446,-0.487933,-0.146844,0.598084,0.235154,-0.185361,0.536447,-0.233121,-0.130562,-0.101021,0.044676,-0.624423,-0.330895,0.491555,-0.003343,-0.126931,0.413199,-0.819920,0.075044,-0.351550,-0.006334,0.101637,-0.470830,-0.126542,-0.821726,-0.024191,-0.339565,-0.287425,0.273359,-0.047546,-0.299885,0.498812,-0.970595,0.329908,0.813860,0.280536,-0.570687,0.684941,0.168977,0.229376,-0.269089,0.015732,0.449156,-0.293159,0.397466,-0.082946,0.462443,-0.167798,0.058562,-0.441755,0.487356', '3326747', '11541282', '26967920', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292277', '偷香', '剧情', '年轻的露西（丽芙·泰勒 Liv Tyler 饰）带着她母亲自杀后留下的日记，来到了一个小镇上探访母亲往昔的好友，并住在雕塑家格雷森的家中。其实四年前，露西就和母亲来过这里，还认识了一个叫尼古拉的男孩。她曾经被他送上的一封信深深感动，并和他有过美好的初恋时光。如今，格雷斯家中异常热闹，聚集了各路人物，露西美丽的魅力让这里的男人们纷纷动心，其中患有白血病的作家亚历克斯更是难以自拔。尼古拉从国外回来，露西却发现他是个花花公子，枉费当年动了情。此时寻找生父成了露西的心结。她在这段历程中慢慢成熟，并寻获心爱那人。©豆瓣', '丽芙·泰勒', '贝纳尔多·贝托鲁奇', 7.6, 29902, 'tt0117737', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1081151273.jpg', 0.4, 3, 30.3, 46.2, 20.1, '0.377049,0.123382,-0.737169,0.478526,-0.167466,-0.511672,1.099217,-0.097724,-0.543930,-0.201797,-0.088370,0.843133,-0.188312,0.844544,0.255892,0.326986,-0.554480,-0.727228,0.040316,-0.308047,-0.339119,-0.288550,-0.225152,0.045841,-0.139359,-0.268158,0.326967,-0.141015,0.138080,0.618452,0.293590,0.225582,-0.117119,0.553235,-0.292096,0.355572,0.103211,0.071127,-0.136685,0.050581,0.037892,-0.282041,-0.060547,0.331603,-0.046455,0.274079,0.406786,-0.121536,-0.017773,-0.231403,0.280722,0.076741,0.004499,0.121177,0.161987,-0.122795,0.217455,0.167385,-0.231562,-0.044277,-0.050282,-0.074769,-0.635487,0.115834,0.040302,0.190866,-0.723581,0.423751,-0.000776,-0.109234,-0.086017,-0.387715,0.287018,0.192687,-0.154808,0.125343,-0.145442,0.063164,-0.411795,0.300633,0.428536,0.032881,-0.167714,0.491807,-0.323724,-0.404243,0.131631,-0.032032,-0.546884,0.217118,0.225636,0.060382,-0.174813,0.040227,-0.544113,0.044146,-0.373055,-0.057697,-0.016771,-0.253869,-0.264851,-0.508411,-0.218789,-0.600395,-0.660627,-0.077638,-0.151466,-0.200734,0.744396,-0.618734,0.293636,0.596500,0.228924,-0.411904,0.616947,0.238991,0.007156,0.060794,-0.198158,0.668374,0.006967,0.239993,0.129383,0.311820,-0.151013,0.024879,-0.660729,0.686646', '1309172', '1291877', '1302133', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292278', '巴贝特之宴', '剧情', '19世纪70年代，与世隔绝的丹麦北部的小村庄。一对督信路德教的姐妹花玛蒂娜（比尔吉特·费德施皮尔 Birgitte Federspiel 饰）和菲丽帕（博迪尔·吉尔 Bodil Kjer 饰）平日里深居简出，在做牧师的父亲的引导下，不惜牺牲爱情，全身心地献身于宗教事业。好心的姐妹二人收留了一个由巴黎避乱而来的女子巴贝特（斯蒂芬妮·奥德安 Stéphane Audran 饰）。身世神秘的巴贝特原来是法国餐厅的名厨。巴贝特幸运地获得了法国巨额彩金一万法郎，为了回报这对好心的姐妹，巴贝特决定在两姐妹父亲的忌辰时亲自掌厨，为村民奉上一桌正宗丰盛的法国大餐。本片根据丹麦女作家伊萨克·迪纳森的小说改编而成，荣获1988年第60届奥斯卡金像奖最佳外语片大奖，并获得1987年第40届戛纳电影节天主教人道奖，以及1989年第46届金球奖最佳外语片提名。©豆瓣', '斯特凡·奥德朗', '加布里埃尔·阿克谢', 8.4, 10931, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2185363996.jpg', 0.3, 0.9, 13.4, 48.2, 37.2, '0.132424,-0.048924,-0.519595,0.646211,0.442021,-0.598245,0.215164,0.157079,-0.484281,-0.039328,0.039079,0.872779,-0.208948,0.050203,0.640655,0.099736,-0.535004,-0.568371,-0.260483,-0.335709,-0.056192,-0.351794,-0.247222,-0.182306,-0.247846,-0.482722,0.239063,-0.145773,0.255873,0.449486,0.620273,0.335088,0.169235,-0.257662,0.061736,0.133362,0.658942,-0.064597,-0.768331,0.515015,-0.226514,-0.053380,-0.304228,-0.172570,0.393294,0.253715,0.648860,-0.499237,0.228883,-0.094344,0.542479,-0.088438,-0.087985,-0.087457,0.132444,-0.160962,0.329807,0.195903,0.008487,0.214853,0.176275,-0.530542,-0.450457,-0.236362,0.317094,-0.027738,-0.560538,0.361369,-0.122020,0.231657,0.061281,-0.286009,0.035887,0.361641,0.368723,0.230086,0.136828,0.065848,-0.267444,0.490645,0.448271,0.083047,-0.096893,-0.010830,-0.488495,-0.641695,0.142982,-0.232574,-0.451393,0.013126,0.371372,-0.132248,0.421432,0.421431,-0.556142,-0.103874,-0.321306,-0.285360,0.272665,-0.257546,0.048910,-0.764237,-0.006780,-0.263106,0.068731,0.015464,0.267718,-0.056206,0.724762,-0.290904,0.543133,0.402693,0.298494,0.049966,0.823887,0.104724,0.162914,-0.364675,-0.377095,0.293802,-0.081045,-0.094612,-0.056607,0.243605,0.071397,-0.057009,-0.137949,0.312257', '1829654', '3275168', '1780122', '1302279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292279', '成为约翰·马尔科维奇', '剧情', '戈尔（约翰•库萨克 John Cusack 饰倒的木偶艺人，善于操作舞台上傀儡木偶。生活所迫，他进入了一间纽约一间公司从事文件管理工作。这间公司在办公大厦的七楼半，由于它只有半层楼高，所以职员们都只能拱着腰工作。正是由于这样，戈尔偶然发现了公司的文件柜后面有一扇门。好奇心驱使下，戈尔进入了这扇门。当戈尔一进入门内，马上便被吸入了其中，并飞越时空进入了著名演员约翰.马尔科维奇的大脑中。他发现现在自己能随意控制约翰.马尔科维奇的目光，并窥探到一切约翰.马尔科维奇的私隐。十五分钟后戈尔自动被弹回了现实中。这一发现令戈尔兴奋不已，他决定利用这扇门做一笔大生意。©豆瓣', '约翰·库萨克', '斯派克·琼斯', 8.3, 60915, 'tt0120601', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1087658057.jpg', 0.4, 1.7, 16, 47.9, 33.9, '0.525763,0.373314,-0.721717,0.236763,-0.101161,-0.323358,0.719469,0.357036,-0.553468,-0.234970,0.248490,0.690504,-0.154769,0.079112,0.041135,0.078566,-0.483651,-0.509467,-0.277718,-0.355114,-0.329018,-0.346392,-0.315287,-0.195068,-0.129709,-0.158285,0.365543,0.071935,-0.041918,0.243788,0.025091,-0.128436,0.043823,0.406668,0.172261,0.103645,0.333312,-0.241523,0.028501,0.312161,-0.202468,-0.083686,-0.139477,0.088655,0.151181,0.327369,0.366769,-0.189774,-0.287160,-0.034350,0.220931,0.064447,-0.190542,-0.120295,0.362447,0.229164,0.257782,0.146539,-0.512387,0.386645,0.037400,-0.073330,-0.607238,-0.183937,-0.313949,0.098769,-0.557802,-0.012699,0.012352,-0.060947,-0.187678,-0.451073,-0.136624,0.155729,0.319148,0.235169,-0.317784,0.106952,-0.490184,-0.239827,0.154529,-0.114493,-0.431810,0.396824,-0.026685,-0.367848,-0.173247,0.176226,-0.012910,-0.426257,0.631879,0.262210,-0.073920,-0.142209,-0.472614,0.162097,-0.408790,-0.234347,-0.445116,-0.392248,-0.008838,-0.721450,-0.117623,0.129874,-0.154315,-0.090490,-0.060459,-0.223190,0.318397,-0.581990,0.411904,0.683217,0.369288,0.101756,0.599487,-0.214799,0.386596,-0.109577,-0.064471,0.250943,0.063766,0.786510,0.078501,0.634344,-0.001554,-0.311287,-0.372665,0.459616', '1297659', '1301345', '3735015', '1308842');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292280', '第25小时', '剧情', 'Monty（爱德华·诺顿 Edward Norton 饰）牵着他的狗在纽约散步，白天，他去了他以前就读的学校拜访了他的老友Jacob（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰），Jacob在里面当英语老师，课上他的女学生Mary（安娜·帕奎 因 Anna Paquin 饰）非常活跃。而Monty和Jacob的另一个好友Frank（巴里·佩珀 Barry Pepper 饰）则在公司忙碌地工作着。事情的起因是某天的下午，Monty回到家，发现女友Naturalle（罗莎里奥·道森 Rosario Dawson 饰）在家门口等待许久。两人正在浴缸里调情的时候，警察突然来敲他们的家门。Monty藏在沙发里的毒品被发现。因此他被起诉，被判入狱7年。Monty离进监狱只剩下几个小时的时间了，他开始怀疑是不是女友出卖了他。Monty去找了他的老爸，两人谈了很多很多，之后他们一群人去到酒吧，却意外地遇到了Jacob的女学生Mary。24小时过去了，下一个小时开始，Monty就要开始他的监狱生涯......', '爱德华·诺顿', '斯派克·李', 7.8, 22830, 'tt0307901', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2188222223.jpg', 0.6, 2.8, 23.6, 49.7, 23.4, '0.594342,0.031517,-0.783197,0.147068,-0.280691,-0.476519,0.861718,0.245084,-0.672957,-0.321578,0.292427,0.578346,-0.331970,0.560889,0.381622,0.114500,-0.669910,-0.803461,0.023030,-0.500908,-0.465767,-0.329965,0.001434,-0.218753,0.119309,-0.018958,0.135465,-0.069958,0.275341,0.459043,0.117124,0.165262,0.142076,0.635802,-0.199463,0.303468,0.291614,-0.100856,0.163392,0.177747,0.241873,-0.341157,-0.359337,-0.004941,0.227089,0.424664,0.759351,0.179397,-0.083792,-0.129288,0.331521,-0.193084,-0.153502,-0.036016,0.736418,0.143405,0.350480,0.195023,-0.151877,-0.006817,0.092133,-0.046336,-0.262331,0.206012,-0.238506,0.204359,-0.640602,0.596898,-0.189075,0.115287,0.275289,-0.469648,0.016443,0.324235,-0.159149,0.463568,-0.077890,-0.065294,-0.600875,0.323569,0.443506,-0.104252,0.203989,0.361922,0.147094,-0.399755,-0.138715,0.006837,-0.394399,-0.303973,0.532348,-0.099278,-0.419865,-0.077332,-0.534357,-0.039248,-0.139233,-0.271810,0.044199,-0.368602,-0.318392,-0.819078,0.238139,-0.210719,-0.279339,0.273012,-0.158957,-0.068177,0.390807,-0.785763,0.220132,0.803693,0.367821,-0.281510,0.873720,-0.177268,0.086936,0.041335,0.077740,0.011470,-0.019343,0