INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292286', '我的野蛮女友', '剧情', '牵牛（车太贤饰）第一次与她（全智贤饰）邂逅，就毫无浪漫感可言。在地铁上她就语出惊人，喝的醉醺醺的她大声训斥不自觉给老人让座的人，吐完之后就软趴趴地倒了下来。善良的牵牛上前接住，于是就只好背着她到旅馆投宿了。但是好心不一定有好报，牵牛正在好好洗澡时就被冲进来的警察带走了。然而这两个人却从此开始约会了。她很霸道很任性，然而当她用那张可爱的面孔对着你笑时，你也忍不住心软。于是牵牛也心甘情愿地被她折磨。渐渐的，牵牛感觉到她的内心受伤了，他用尽全力去呵护去保护，她仍然缺乏安全感。虽然在一起很快乐也很感动，她却仍然提出了一个难以接受的约定：让我们先分开吧……©豆瓣', '全智贤', '郭在容', 8.2, 432217, 'tt0293715', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p489336497.jpg', 0.2, 1.2, 18.8, 45.9, 33.9, '0.298128,0.085306,-0.814883,0.413987,-0.421534,-0.453692,0.849789,0.208736,-0.113899,0.222438,0.070343,0.540668,-0.110403,0.468501,0.203602,0.292706,-0.363377,-0.396800,0.080226,0.124207,-0.411756,0.007271,0.191503,-0.071181,-0.086122,0.050367,0.248179,-0.222369,-0.222303,0.333011,0.169458,-0.014331,0.223213,1.042526,-0.424770,0.183789,-0.322257,0.025607,0.314817,-0.001754,0.392194,-0.449737,-0.252158,0.467515,0.030091,0.332725,0.319694,-0.204019,-0.409774,0.270456,0.022646,-0.471979,0.098532,0.226896,-0.175343,-0.081769,0.220702,-0.041303,-0.406876,0.155140,0.149349,0.078848,-0.570850,0.462470,-0.008593,-0.004726,-0.842041,0.610972,0.009320,0.067641,0.026956,-0.546995,-0.020669,0.127811,-0.005751,0.311186,-0.274913,-0.034931,-0.648512,0.060172,0.678595,0.097944,-0.129718,0.378543,-0.175491,-0.371358,0.280506,-0.084983,-0.306360,-0.288615,0.268489,0.019980,-0.456781,-0.361391,-0.542026,0.048426,-0.156165,-0.094939,-0.300130,-0.609733,0.241291,-0.189642,-0.055299,-0.319091,-0.470869,0.152384,0.104918,-0.171986,0.684372,-0.596769,0.177001,0.646357,0.401778,-0.365549,0.419678,0.439477,-0.274368,0.009814,0.069485,0.173571,-0.093847,0.371459,0.578509,0.593738,-0.052268,0.204270,-0.375269,0.645546', '26718282', '1306801', '1866424', '21447058');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292287', '新龙门客栈', '动作', '宦官专权的明朝中叶，东厂曹少钦（甄子丹）假造圣旨杀害了忠良杨宇轩，并想斩草除根杀死其后代。侠女邱莫言（林青霞）、江湖义士贺虎等人冒死救出忠良后代后，逃至边关沙漠里的龙门客栈，与杨宇轩部下周淮安（梁家辉）会合。龙门客栈实则黑店，老板娘金镶玉（张曼玉）利用乱世，以美貌和风骚 作诱饵杀人越货聚敛钱财，但她却为英俊潇洒的周淮安动了真心。为了摸清潜藏于龙门客栈中的出关暗道，周淮安将计就计，答应与金镶玉成亲。洞房花烛夜，楼上的周淮安与金镶玉各怀心事暗中较劲，楼下的邱莫言、贺虎等人也与东厂一众“走狗”展开了明争暗斗，战事一触即发。©豆瓣', '张曼玉', '李惠民', 8.7, 413038, 'tt0105859', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1421018669.jpg', 0.1, 0.5, 10.3, 44.5, 44.6, '0.134125,0.026325,-0.285752,0.578756,0.003244,-0.296059,0.516408,0.152664,-0.654826,-0.330899,-0.146780,0.347984,-0.209433,0.145849,0.251592,-0.242424,-0.247391,-0.715351,-0.262215,0.018263,0.173714,-0.373553,-0.047177,-0.413249,-0.286814,0.453987,0.446832,0.437287,-0.035639,0.530845,0.639192,-0.021181,-0.473725,0.630621,-0.023141,0.182722,-0.209467,-0.184617,-0.552302,-0.058401,-0.028123,-0.438347,-0.254846,0.141642,0.096617,0.223171,0.247078,-0.248997,0.205579,-0.308204,0.124964,-0.154192,0.145409,0.101356,0.425799,-0.087904,0.016085,0.116687,-0.097998,0.018007,-0.172391,-0.044937,-0.238908,0.039006,0.180599,-0.394459,-0.271773,0.121366,0.132031,0.241000,-0.131716,-0.048357,0.344358,0.281555,0.451679,-0.166260,-0.035661,-0.159318,-0.623700,0.305875,0.134960,-0.016747,0.115080,-0.304222,0.409843,-0.585727,0.168378,-0.145967,-0.135193,-0.187560,0.371134,-0.064209,0.078751,0.027678,-0.213154,-0.191157,-0.217638,0.516230,0.047688,-0.269326,0.039760,-0.534936,-0.258735,-0.449105,-0.118014,0.024759,0.308520,-0.039032,0.219571,-0.515811,-0.295279,0.045005,0.287195,-0.867421,0.383638,0.072709,0.322275,0.022693,-0.090059,-0.029429,0.447049,0.201082,0.427532,0.172980,-0.338359,-0.031965,-0.113379,0.119384', '1297497', '1424746', '1302110', '1303269');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292288', '公民凯恩', '剧情', '美国报业大亨凯恩（奥森•韦尔斯）在桑拿都庄园中留下“玫瑰花蕾”的“遗言”死去后，一位青年记者受媒体的委托调查这四个字的含义，遂即，他走访了凯恩生前的同事好友，从报社董事长伯恩斯坦的口中，了解到凯恩的发迹历程以及如何制造舆论使美国卷入1897年的战争中的往事，从利兰的讲述中，凯恩与美国总统的侄女爱米丽的婚姻、与第二任妻子（歌手）苏珊的复杂关系及在总统竞选中的失败等等也被他一一所知。听过大量的讲述后，该记者又去图书馆查阅了有关凯恩的详尽资料，凯恩更多的一面，青年时代的经历及与母亲的关系也被他知晓，然而，“玫瑰花蕾”四字的含义，他仍不得而知。©豆瓣', '奥逊·威尔斯', '奥逊·威尔斯', 8.8, 105588, 'tt0033467', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1474928139.jpg', 0.3, 1, 9.9, 37.2, 51.6, '0.501270,-0.058562,-0.572910,0.733851,0.109626,-0.346554,0.726175,-0.092793,-0.659844,-0.212306,0.180158,0.659995,-0.310214,0.428443,0.405504,-0.027192,-0.220781,-0.735064,-0.076722,-0.309224,-0.127877,-0.790954,-0.264568,-0.092276,-0.051588,-0.124817,0.451998,0.133934,-0.036785,0.348133,0.150227,0.157600,-0.189610,0.364517,0.097306,0.200090,0.334013,0.147315,-0.364642,0.024582,0.330914,-0.300391,-0.098634,0.106334,-0.047865,0.419464,0.451481,-0.240098,0.188361,-0.118738,0.488209,0.086824,0.193033,0.193082,0.579353,0.356708,0.258296,0.640510,-0.188555,-0.000442,-0.164303,0.049479,-0.776925,-0.167037,0.165089,0.518782,-0.592375,0.526823,-0.152118,0.076573,-0.095385,-0.189742,0.353931,0.285012,0.125822,0.385175,-0.041314,-0.059290,-0.311107,0.486422,0.656112,-0.062647,-0.180563,0.151869,-0.276821,-0.331273,-0.075958,-0.081542,-0.319771,0.137478,0.177401,0.118622,-0.218463,0.441264,-0.573397,-0.181606,-0.279847,-0.322474,-0.003157,-0.286181,-0.021571,-0.663539,-0.453360,-0.376708,-0.116365,-0.243427,0.293145,-0.151264,0.872112,-0.683984,0.112344,0.348178,0.347923,-0.410249,0.638009,0.179710,0.314999,-0.195182,-0.272217,0.464580,0.316588,0.142579,-0.045925,0.251299,0.207376,-0.502212,-0.227878,0.074806', '27602116', '1303449', '30162520', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292289', '心动', '爱情', '女导演Cheryl（张艾嘉 饰）跟编剧商量准备开拍一部关于初恋的爱情故事，她决定把故事时间订在1977年，那时候的女主角小柔（梁咏琪 饰）只有17岁，在舞会上遇到了男主角浩君（金城武 饰）二人一见钟情，很快他们便陷入了热恋之中。小柔有一个好朋友叫陈莉（莫文蔚 饰），小柔除了跟她诉说心事以为，更是逃过妈妈追问出外过夜的好借口。浩君与小柔的家人很快知道了他们的事，两方家长都要求他们分手了断，伤心欲绝的小柔找到陈莉，原来陈莉一直喜欢小柔，令小柔惊吓不已。多年后，浩君与小柔在日本重逢，就算他们各自都有了另一半，但还是阻止不了他们再次走进对方的生活。©豆瓣', '金城武', '张艾嘉', 8.2, 83745, 'tt0215240', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p482119068.jpg', 0.3, 1.5, 19.4, 47, 31.8, '0.283672,-0.352542,-0.584768,0.279682,0.078356,-0.412730,0.570417,-0.049131,-0.442465,-0.301163,-0.072480,0.692586,-0.342352,0.532102,0.219724,-0.184221,-0.573027,-0.793552,0.149113,-0.276467,-0.113403,-0.331830,0.103234,0.068774,0.003463,-0.126038,0.316461,-0.253386,0.019091,0.580913,0.420751,-0.067492,-0.207932,0.579411,0.062713,0.248362,0.036176,0.344107,-0.578730,0.205027,0.079818,-0.012975,-0.153006,-0.052190,0.121799,0.313818,0.435893,-0.125803,-0.182357,0.262592,0.085171,-0.139245,-0.080514,0.136274,0.133751,-0.089313,0.621896,0.219036,-0.339956,0.042446,-0.049857,0.082148,-0.265608,0.251855,0.107375,0.005921,-0.460901,0.398947,-0.042855,0.011740,0.181453,-0.532210,0.424515,0.441996,0.325468,0.207532,-0.221322,-0.076514,-0.353861,0.408784,0.851837,0.142558,0.192281,0.370634,0.190093,-0.393198,-0.006416,0.086251,-0.386931,0.274146,0.099414,0.006084,-0.345343,-0.118227,-0.443588,-0.188360,-0.044662,-0.165827,-0.002393,-0.518422,0.074985,-0.327188,-0.311364,-0.338151,-0.407794,0.135689,-0.102286,-0.100537,0.796219,-0.783406,0.284864,0.212192,0.417300,-0.723661,0.716655,0.299297,0.004752,-0.311613,0.250139,0.003309,-0.395680,0.071645,0.311658,0.210438,0.087471,-0.061438,-0.489831,0.145839', '3212120', '1292219', '25721544', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292326', '暴力街区', '动作', '近未来，法国巴黎黑势力横行，以大毒枭塔哈（Bibi Naceri 饰）为首的黑帮更是横行无忌，连当地警方都惧怕三分。软弱的警方无法对抗势力强悍的黑帮，只能用围墙和工事将不法分子所在的区域隔离。在这个被称为“13区”的地方，鱼龙混杂，暗流涌动。年轻的小混混雷托（David Belle 饰）拒绝塔哈的毒品生意，双方发生激烈冲突。雷托原本将塔哈扭送警察局，结果遭到腐败警察的算计。塔哈不仅逍遥法外，雷托的妹妹罗拉（Dany Verissimo 饰）也被大毒枭带走。6个月后，身手敏捷的高级督察达米埃（Cyril Raffaelli 饰）接到一宗棘手案件。一个威力强大的中子炸弹在运输途中遭到劫持，落到了塔哈的手里。为了阻止炸弹爆炸，达米埃必须在24小时之内将炸弹追回。他不得不求助于伺机救回妹妹的雷托……©豆瓣', '塞瑞尔·拉菲利', '皮埃尔·莫瑞尔', 8.1, 118333, 'tt0414852', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p642981690.jpg', 0.2, 1.4, 19.5, 52.8, 26.2, '0.268393,-0.121725,-0.795369,0.315939,-0.107968,0.275445,0.635704,0.132307,-0.424980,-0.123047,0.279237,0.527121,-0.236420,-0.425677,0.064594,-0.184746,-0.208159,-0.639461,-0.089517,-0.251924,-0.199759,-0.655944,-0.579472,-0.417796,0.133458,-0.335445,0.268788,0.153971,-0.167437,0.266457,0.163940,0.518124,-0.315621,0.307383,-0.099434,-0.255202,0.077436,-0.392441,-0.213046,0.413976,-0.208587,-0.180289,0.258303,0.006328,0.071538,0.456032,0.556081,-0.081998,0.133018,-0.121094,0.196230,-0.378530,-0.017661,0.064426,0.691119,-0.073925,-0.031534,0.004060,-0.410376,-0.136796,0.448612,-0.137750,-0.634146,0.046764,0.366532,-0.087897,-0.561112,0.257384,-0.175747,0.009989,-0.046500,-0.065150,0.180552,0.392790,-0.026440,0.229747,-0.087654,0.151302,-0.711653,-0.243813,0.505775,-0.278869,-0.276010,-0.430584,0.079847,-0.301688,-0.127549,-0.754939,0.014500,-0.121887,0.565024,-0.182777,0.013605,0.282220,-0.471606,-0.149445,-0.438461,-0.151639,-0.031042,-0.045209,-0.179319,-0.553667,-0.020946,-0.178640,-0.124170,0.296584,0.175750,0.163517,0.693615,-0.424168,0.119863,0.739306,0.417342,-0.471706,0.234315,0.045534,0.297281,0.053889,-0.458849,0.207036,0.471214,0.546798,0.313295,0.245638,-0.171757,-0.513206,0.154351,0.011291', '26747274', '1294181', '1947080', '26892558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292328', '东邪西毒', '剧情', '在恋人（张曼玉）负气嫁给兄长的当晚，欧阳锋（张国荣）黯然离开白陀山，走进沙漠某个小镇，成为一名杀手中介人。他的朋友、风流剑客黄药师（梁家辉）每年都来小镇与他畅饮，酒话里有关白陀山的消息令他忘却往事的念想渐次演变成自欺行为。黄药师只是表面风流。他迷恋好友“盲武士”（梁朝伟）的妻子桃花（刘嘉玲），后者在丈夫死后，永远地离开了他；而对迷恋他的女人慕容嫣（林青霞），他又不愿兑现曾经随口说出的承诺，这使得慕容嫣迷失于自己的身份中。与欧阳锋构成短暂“买凶杀人”关系的洪七（张学友）、村姑（杨采妮）等人，也都有一段只有他们自己才知、不愿回首的痛苦过往。©豆瓣', '张国荣', '王家卫', 8.6, 542478, 'tt0109688', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1982176012.jpg', 0.4, 1.3, 11.8, 38.5, 48, '0.224823,0.042385,-0.736072,0.657024,-0.338543,-0.248727,1.021137,-0.109740,-0.601026,-0.146182,0.376626,0.891558,-0.090052,0.343134,0.213476,0.171383,-0.016166,-0.781758,0.159052,-0.479175,0.123486,-0.359936,-0.145026,-0.324119,-0.313086,-0.002801,0.660946,0.147188,-0.151706,0.436867,0.289580,0.074970,-0.255839,0.726701,-0.212203,0.307622,-0.161012,0.256289,-0.391411,-0.041514,0.130407,-0.370558,-0.310966,0.096758,-0.262925,0.303320,0.640014,-0.179260,-0.137720,-0.136267,-0.010341,-0.338021,-0.014238,0.103408,0.049942,-0.174873,0.339097,0.212458,-0.197942,-0.204796,-0.174974,0.203023,-0.190506,0.128452,0.194918,0.215261,-0.398121,0.573190,-0.400001,-0.025070,0.065451,-0.180318,0.064776,-0.151096,0.458633,0.215696,-0.106327,-0.235653,-0.324416,0.444544,0.653748,0.285428,-0.103339,0.359045,-0.164475,-0.354616,0.028417,-0.123067,-0.501811,0.134460,0.175287,0.029215,-0.301717,0.370801,-0.347194,-0.162889,0.017278,0.212992,-0.023061,-0.449234,-0.064288,-0.345200,-0.228122,-0.494138,-0.156827,-0.113189,0.123911,-0.297715,0.627641,-0.756436,0.091972,0.230871,0.486095,-0.727732,0.589644,0.073909,0.107573,-0.212796,0.010724,0.670763,-0.172263,0.068766,0.171443,0.148693,-0.042226,0.292351,-0.317086,0.372076', '4275444', '3111650', '1308755', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292329', '牯岭街少年杀人事件', '剧情', '结识小明（杨静怡）前，小四（张震）是典型的乖仔，是父母的希望和兄妹的骄傲（一家人指望他考上名牌大学将来提升全家的社会地位），他有一个喜欢摇滚乐的自称“小猫王（王启赞）”的好友，两人虽会去树林看人幽会，但过的是与周围诸多在“小公园”混的少年人完全两样的生活。喜欢上小明后 ，小四便像跌进一个无底深渊，开始被外界的各种力量牵着鼻子走。新识仰慕对象honey（林鸿铭）意外身亡，一向敬重的父亲的自尊与精神因为某次事件严重受损，加上将一次次“欺骗玩弄”他感情的小明“看透”，血气方刚又有很强道德感的小四终于走上犯罪的道路，期望用自己的刀结束事件的根源。但小四不知的是，他眼中的根源只是这条食物链中微不足道的一环。©豆瓣', '张震', '杨德昌', 8.9, 267436, 'tt0101985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p848381236.jpg', 0.4, 1.1, 8.8, 32.7, 57, '0.439396,-0.031884,-0.795953,0.759560,-0.316932,-0.136014,0.937124,0.047281,-0.467900,-0.106878,0.134616,0.718494,-0.029200,0.390689,-0.138875,-0.143618,0.080739,-0.654848,-0.257395,-0.125320,-0.268971,-0.421005,-0.408849,0.107332,-0.383763,-0.211782,0.681372,0.162624,-0.439177,0.451319,0.290138,0.161805,0.166314,0.373899,-0.326578,-0.042448,-0.190968,0.254911,-0.223354,-0.063795,0.072558,-0.015243,-0.001606,0.216067,0.010426,0.313563,0.683881,-0.135084,-0.339168,-0.121112,0.553951,-0.333151,-0.139195,0.156411,0.261240,0.100222,0.197826,0.101715,0.040515,-0.015972,0.060213,-0.096752,-0.777040,-0.209241,0.098723,-0.024744,-0.579759,0.579254,0.167189,-0.473334,0.025947,-0.308820,0.179045,0.042545,0.146403,0.471488,-0.197197,0.098055,-0.428878,-0.165737,0.874521,-0.107936,-0.499475,0.370175,-0.267521,-0.324624,0.047185,-0.374974,-0.369064,-0.031427,0.221545,-0.023620,-0.404260,0.442556,-0.387421,0.210257,-0.099099,0.035357,-0.056656,-0.481448,-0.109418,-0.261092,-0.284715,-0.869171,-0.373332,0.032050,0.166204,-0.528734,0.819330,-0.893711,0.242793,0.490207,0.176271,-0.677653,0.752906,0.294556,0.109988,-0.139037,-0.205820,0.179288,-0.005615,0.029381,-0.016949,0.317434,-0.096167,-0.154685,-0.507738,0.450610', '26354526', '26283288', '24756472', '1308076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292330', '恋恋风尘', '剧情', '初中毕业后，因家境不许，15岁的农村少年阿远（王晶文）放弃学业来台北做事，初尝人生的辛苦，却仍为自己的理想努力着。一年后，阿远青梅竹马的恋人阿云（辛树芬）也来到台北，了解到现实的台北同阿远信里所描述的，是两个世界。可是困顿的环境并没减少他们的快乐，因为他们拥有彼此。阿远服兵役时，因为有每日抵达的书信，孤身在台北的阿云起初并没感到有多孤独。然而日子久了，遥远恋人的纸上诉情总比不过现实生活中鲜活男孩的低声耳语，加上对未来怀有的恐慌，阿云在阿远退伍前选择了嫁作他人妇。伤心虽有，阿远也只能选择抑压。©豆瓣', '李天禄', '侯孝贤', 8.7, 80755, 'tt0091406', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p743473590.jpg', 0.1, 0.6, 9.5, 45.2, 44.6, '0.260092,-0.005656,-0.826959,0.455404,-0.193078,-0.428777,0.796907,0.074433,-0.641353,-0.243659,0.031648,0.696189,0.160858,0.588229,-0.056086,0.037550,-0.175402,-0.583106,-0.006378,-0.247504,-0.189721,-0.469104,0.000548,-0.000117,-0.406302,-0.292860,0.635506,0.296859,0.012817,0.457502,-0.028225,-0.094352,0.015420,0.555993,-0.223190,-0.036868,-0.040873,0.556515,-0.442531,-0.014426,0.237685,-0.085753,-0.217739,-0.029158,0.181056,0.375302,0.743971,0.010459,-0.446151,0.255809,0.590403,-0.148903,-0.217091,-0.120112,0.230560,0.041330,0.119652,0.098757,-0.159638,-0.041804,-0.436339,-0.085506,-0.610513,0.046447,0.174109,-0.127454,-0.521436,0.720192,-0.027961,-0.246765,0.221800,-0.379915,0.028436,0.447412,0.140558,0.373078,-0.214117,0.207961,-0.335134,0.230238,0.838438,0.082614,-0.488688,0.419040,-0.454611,-0.594422,0.081126,-0.335049,-0.512296,0.190025,-0.021921,0.207229,-0.510877,0.180073,-0.264071,0.253784,-0.044979,-0.100713,0.274045,-0.466479,-0.201658,-0.196163,-0.085218,-0.724805,-0.533629,-0.015738,0.133011,-0.308013,0.745265,-0.930627,0.496488,0.576834,0.337855,-0.619326,0.809803,0.387017,0.172951,-0.153992,0.099374,0.632483,-0.416972,0.162572,0.192883,-0.106834,-0.177102,0.093145,-0.573123,0.511031', '26354526', '25721544', '35030151', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292332', '移魂都市', '科幻', '似乎永无止境的黑夜，笼罩着破败冰冷的现代化大都市，空气中弥漫着不祥的气息。约翰·默多（卢夫斯·塞维尔 Rufus Sewell 饰）在某旅馆的浴缸中醒来，对于之前发生的一切毫无印象，甚至忘记了自己的身份和姓名。神秘的电话、冰冷的尸体以及不明身份的追杀者，这一切都令他无所适从。他凭借仅有的线索开始追查自己的身份以及这一切混乱的肇因。关于这个黑暗世界离奇的一面，也在他的调查中慢慢揭开面纱……本片荣获1998年美国科幻恐怖电影学院最佳科幻电影奖、1998年阿姆斯特丹奇幻电影节银屏奖、1999年布鲁塞尔国际奇幻电影节佩格萨斯观众奖、1999年澳大利亚影评人协会最佳原创剧本奖。©豆瓣', '卢夫斯·塞维尔', '亚历克斯·普罗亚斯', 7.9, 59550, 'tt0118929', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2423352488.jpg', 0.5, 2.5, 23.1, 49.6, 24.3, '0.117662,0.173790,-0.678986,0.747947,0.325210,0.170070,0.653503,-0.168700,-0.690242,-0.548709,0.157319,0.649167,-0.375157,0.233180,0.302035,0.096690,-0.689230,-0.971508,-0.471615,-0.361693,-0.247172,-0.254094,-0.575269,-0.089486,-0.065366,-0.283453,0.603326,0.335803,-0.342639,0.337589,0.333285,0.323365,-0.252199,0.317808,-0.017330,-0.019797,0.308610,-0.019524,-0.369532,-0.093482,0.093492,-0.470331,-0.282147,0.302054,0.185718,0.305238,0.560015,-0.180960,-0.303788,0.135415,0.610991,-0.270306,-0.184579,-0.069956,0.168126,0.007210,0.089411,0.400618,0.033792,0.002641,-0.047276,-0.177499,-0.937278,0.116525,0.146282,0.442012,-0.091911,0.286435,-0.146618,0.153346,-0.106662,-0.116975,0.358887,-0.156271,0.272867,0.220319,-0.021385,0.063829,-0.515132,0.584097,0.271425,0.078225,-0.626381,0.206313,-0.341824,-0.499959,-0.274815,-0.090033,-0.319628,0.299644,0.362929,0.200431,-0.055102,0.492380,-0.560167,-0.148503,0.145731,-0.736564,-0.089780,-0.074544,-0.342891,-0.668107,-0.502603,-0.315116,-0.299023,-0.231744,0.021331,-0.113870,0.390924,-0.434193,0.418097,0.482460,0.004991,-0.017625,0.557463,-0.291385,-0.052011,0.078917,-0.419769,0.388659,0.030669,0.266573,-0.098943,0.291845,-0.071049,-0.142954,-0.338685,0.566037', '1297503', '26577354', '1299663', '25837262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292335', '危险关系', '剧情', '表面看来，杰奇（帕姆·格里尔 Pam Grier 饰）是一名普通的空姐，然而，在暗地里，她一直利用职务之便，帮助军火商奥德尔（塞缪尔·杰克逊 Samuel L. Jackson 饰）运送赃款，并从中获取暴利。一次意外中，杰奇的“生意”曝光了，她本人亦遭到了逮捕。得知此事，奥德尔派出了马克斯（罗伯特·福斯特 Robert Forster 饰），想要杀人灭口。让奥德尔没有想到的是，马克斯竟然疯狂的爱上了杰奇，两人一拍即合，策划了一场阴谋将奥德尔耍得团团转，甚至派出了心腹梅兰妮（布里吉特·芳达 Bridget Fonda 饰）和路易斯（罗伯特·德尼罗 Robert De Niro 饰）助其一臂之力。然而，当奥德尔发现自己受骗之时，他才发现，事态的发展早已经脱离了他的掌控。©豆瓣', '帕姆·格里尔', '昆汀·塔伦蒂诺', 7.5, 30508, 'tt0119396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1628107924.jpg', 0.6, 3.5, 34.4, 44.8, 16.7, '0.486032,0.105744,-0.704489,0.565217,-0.039124,-0.672360,0.508696,0.202334,-0.281195,-0.379393,0.054216,0.348940,-0.294646,-0.296869,0.390469,0.290560,-0.674801,-0.741356,0.348521,-0.449478,0.238979,-0.788013,-0.492749,-0.275642,-0.226336,-0.506214,0.303667,0.061936,-0.160995,0.429298,0.192442,0.558263,0.106358,0.489600,0.470587,0.002191,0.718226,-0.422134,-0.175912,0.299633,0.085918,-0.169478,0.007480,0.497953,0.087700,0.673626,0.376817,-0.505736,0.082990,-0.152605,0.159266,-0.252374,0.339532,0.159050,0.357447,-0.011220,0.124083,0.168511,-0.291349,-0.037754,0.554426,-0.071947,-0.568897,0.055935,0.021247,0.111774,-0.580733,0.080694,-0.438749,0.030490,-0.253027,-0.298776,0.130751,0.672553,0.451936,0.060349,0.236001,-0.013965,-0.643732,-0.165090,0.585484,-0.033771,-0.114267,0.137675,0.008574,-0.440835,0.135652,-0.212722,-0.176340,-0.089386,0.578326,-0.122765,0.226370,0.451007,-0.287253,0.026354,-0.765220,0.038203,-0.244222,-0.121553,0.352865,-0.742690,-0.294533,-0.064828,-0.381852,-0.164772,0.050546,-0.193347,0.146001,-0.567419,0.397200,0.544262,0.289583,-0.269414,0.323446,-0.056963,0.047953,-0.099430,-0.205438,-0.018992,0.219805,0.037695,0.335054,0.371997,0.305367,-0.420377,0.066611,0.353776', '1307442', '2369549', '2973528', '1418190');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292337', '无人知晓', '剧情', '新搬来的公寓这家人是母亲惠子（You饰）带着四个孩子：明（柳乐优弥饰）、京子、茂、雪。但母亲却得对周围的人们撒谎说丈夫去海外工作，自己与长子两个人在一起生活。事实是其它三名弟妹是“黑孩子”，因为四个孩子有着各自不同的父亲。他们一直呆在家中，没有去学校上学。在母亲去百货商店工作时，年纪尚小的明就在家中代替母亲行使家长的职责。突然有一天母亲不见了，她把手中仅有的20万日元现金和一张短短的便条留给了孩子们，把弟妹托付给明看管后，就悄然地离家出走。无亲无故，对外面几乎一无所知的四个孩子们，要开始面对新的生活，那实在不是件容易的事情……©豆瓣', '柳乐优弥', '是枝裕和', 9.1, 294054, 'tt0408664', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p661160053.jpg', 0.2, 0.4, 4.9, 32, 62.6, '0.221685,-0.117777,-0.768286,0.425777,-0.420093,-0.365616,0.805559,0.267053,-0.569947,-0.588837,0.133846,0.881048,0.249627,0.618728,-0.321953,0.118579,-0.349591,-0.573931,-0.335702,-0.279935,-0.533546,-0.403762,0.346512,-0.242302,-0.187844,-0.025052,0.317212,-0.119349,0.201644,0.205694,0.307557,0.050320,-0.294161,0.358632,-0.557997,0.095380,-0.117695,0.115038,-0.064377,0.065599,0.186097,0.061328,-0.369284,0.056449,0.553989,0.365043,0.825611,-0.015527,-0.187723,-0.081965,0.093087,-0.067084,-0.260797,0.158634,0.439090,-0.147857,0.361148,0.140629,-0.389602,-0.049955,-0.179754,-0.101773,-0.561062,0.112158,0.211336,0.040443,-0.925840,0.602265,-0.141368,-0.308230,0.094541,-0.527769,0.335628,0.369634,-0.387463,0.580190,-0.074586,-0.023659,-0.601479,0.047586,0.874521,-0.137567,0.188554,0.422964,-0.237097,-0.044904,-0.210975,-0.142241,-0.570503,0.102768,0.044735,-0.008128,-0.341526,0.012988,-0.514282,0.083766,-0.228554,-0.244764,0.172941,-0.648060,-0.116832,-0.192382,0.255193,-0.557829,-0.561851,0.187617,0.241709,-0.113370,1.078948,-0.743004,0.179374,0.319147,0.426431,-0.857647,0.877501,0.143026,0.404278,-0.204748,0.182562,-0.240032,0.165116,0.188676,0.305708,0.285054,-0.058206,0.062709,-0.331094,0.407375', '25731805', '1296770', '1291565', '3706859');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292338', '祖与占', '剧情', '一战前，德国人祖（奥斯卡·威内尔 Oskar Werner 饰）和法国人占（亨利·赛尔 Henri Serre饰）在巴黎结识。他们意趣相投，对诗歌和小说都有强烈而共同的兴趣，甚至二人为着同一个雕塑也着迷。顺理成章地，祖与占都爱上了同一个女子：聪明貌美的凯瑟琳（让娜·莫罗 Jeanne Moreau饰）。在这样的关系中，占选择了成全温柔单纯的祖。他们一起到乡间度假，度过了美妙时光。然而一战的爆发，却让他们失去了联系，在自己国家服役期间，他们多么担心会在战场上杀死自己的好友。而祖，从不间断地给妻子凯瑟琳写信。战争结束，祖与占再次相遇，占觉察到祖和凯瑟琳的关系很糟糕——她对婚姻以外的感情从没停止过追逐，喜欢在各种爱情关系中享受自由。占在祖家中住下，凯瑟琳毫不掩饰对占的爱，这段三角关系平衡而快乐的维系着，旁人完全看不透。当占要离去时，凯瑟琳直率锐利的性格让事情起了变化……', '让娜·莫罗', '弗朗索瓦·特吕弗', 8.4, 45087, 'tt0055032', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p555160366.jpg', 0.5, 1.4, 14.3, 45.8, 38.1, '0.360154,0.059234,-1.092815,0.797352,-0.077339,-0.213251,0.762178,-0.113524,-0.486013,-0.123337,-0.115248,0.780265,-0.415605,0.230001,0.211997,0.057829,0.068792,-0.845282,0.053046,-0.087394,-0.105901,-0.892719,-0.295186,-0.233708,-0.008682,-0.515145,0.468125,0.075037,-0.386223,0.741840,0.223245,-0.022537,0.086107,0.704282,-0.052398,-0.017490,-0.373912,0.198127,-0.237255,-0.048726,-0.008161,-0.004565,-0.100185,0.264470,0.287715,0.230685,0.840573,-0.479879,-0.100986,0.022786,0.156980,-0.029040,0.121632,0.339239,0.147935,-0.180702,0.223235,0.557585,-0.239131,-0.020536,0.021583,0.029297,-0.783025,0.130646,0.020752,-0.001277,-0.662417,0.928968,0.107358,-0.227945,0.094279,-0.143656,0.355015,0.552201,0.181607,0.461825,-0.182943,0.006884,-0.412663,-0.031306,1.037181,0.056924,-0.164949,0.307284,-0.600232,-0.167375,-0.451019,-0.333288,-0.296609,-0.245167,0.150259,0.109778,0.067735,0.371846,-0.534766,-0.005084,0.174969,0.212980,0.189837,-0.785588,0.115683,-0.528068,-0.317989,-0.735156,-0.395326,0.116751,-0.052607,-0.379097,0.789112,-0.756705,0.090951,0.649280,0.643316,-0.468414,1.048908,0.505778,0.127523,-0.284224,-0.313523,0.397643,-0.159677,-0.063048,0.381009,0.144997,-0.122800,0.320875,-0.412141,0.523887', '1917323', 