INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292339', '十七岁的天空', '喜剧', '17岁的优质处男周小天（杨佑宁）时常会在梦中与一健壮男子缠绵，为寻梦中情人，他千里迢迢从台南来到台北。通过好友小宇（金勤）的介绍，周小天开始在一家健身房打工，因此结识众同志眼中的头号单身型男白铁男（Duncan），疑惑其就是自己的梦中人，对其心生好感，然而因为不离白铁男半步的男孩俊（张大镛），周小天怀疑有关白铁男花心不负责任的传言属实。当周小天尝试与白铁男交往时，仍不时出没的俊引发一场误会，令他对白铁男的好感度迅速降低。一帮好友为帮周小天走出心情的低谷，企图揪出白铁男替他报仇，却发现白铁男的秘密。©豆瓣', '杨祐宁', '陈映蓉', 6.7, 18946, 'tt0420627', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187205476.jpg', 2.6, 11, 45.1, 29.6, 11.8, '-0.160305,-0.200333,-0.412620,0.169123,-0.056453,-0.206284,0.820799,0.050891,-0.498007,-0.242469,0.091483,0.389291,-0.403476,0.345832,0.535835,-0.137049,-0.109777,-0.421916,-0.319986,-0.222617,-0.048616,-0.211989,-0.330268,0.000370,-0.499016,-0.302752,0.612170,-0.301819,-0.365231,0.430378,0.492539,0.362961,-0.286810,0.141587,-0.145863,-0.229538,0.025559,0.017152,-0.298701,0.384082,-0.165929,-0.234553,-0.117753,0.028026,-0.415288,0.526532,0.942756,0.080316,-0.386041,-0.136181,0.413718,0.009691,-0.079682,0.118927,0.321128,0.023091,0.349829,-0.093254,-0.008541,-0.192301,0.235787,0.019591,-0.090938,0.213607,0.316813,0.197941,-0.223999,0.180267,-0.027530,-0.077786,0.458382,-0.266958,0.068516,0.036476,0.280843,0.277953,-0.127380,0.247329,0.042412,0.107736,0.664505,0.342472,0.134303,0.132793,0.213563,-0.385505,0.067998,0.322594,-0.682201,-0.008683,0.095490,0.222237,-0.034202,0.196395,-0.296983,0.093652,-0.056934,0.352756,0.027758,0.114637,-0.177290,-0.547844,-0.135651,-0.301511,0.061150,0.118141,0.191869,-0.493143,0.639004,-0.790706,-0.073786,0.376925,0.485095,-0.607351,0.676610,0.087239,-0.032603,-0.304188,-0.299521,-0.078103,0.301588,-0.104455,-0.274522,0.321185,-0.389542,-0.282963,-0.069837,-0.007062', '3445516', '1418179', '24839498', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292340', '宛如阿修罗', '剧情', '因为一件大事，让四个原本不怎么来往的姐妹聚在了一起。三女儿泷子（深津绘里 饰）请来私家侦探调查到自己70岁的父亲有外遇了，更生下了孩子。姐妹们都十分震惊，另一方面又要向母亲保守秘密。可事实上，四姐妹都有各自的生活问题。大姐网子（大竹忍 饰）是一名守寡的妇人，却与有妇之夫恋上，更被对方的妻子发现了；次女卷子（黑木瞳 饰）婚姻生活也不太幸福，她一直怀疑自己的丈夫有外遇；三女泷子则一直未婚，虽然有恋人，但两人的感情并没有进展；至于四女咲子（深田恭子 饰）与一个毫无名气的拳击手同居，对方要赢得比赛才与之结婚。四名女儿都各有心事，努力向母亲隐瞒真相，不料母亲还是知道了，受刺激后晕倒在地。©豆瓣', '大竹忍', '森田芳光', 8.1, 8035, 'tt0397317', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2451076258.jpg', 0.4, 1.6, 17.9, 52.4, 27.7, '0.139011,-0.481607,-0.714680,0.425856,-0.096754,-0.458353,1.018273,-0.014461,-0.486905,-0.498266,0.231740,0.670201,-0.261221,0.226119,0.166026,-0.043087,-0.152124,-0.840234,0.167947,-0.175880,-0.219220,-0.490646,0.055469,-0.015768,-0.393697,-0.062292,0.662943,-0.157598,-0.003595,0.212670,0.451342,0.122192,-0.111505,0.554911,-0.198237,0.119373,-0.116404,0.257224,-0.046923,0.066486,0.187795,-0.227162,-0.295687,0.381498,0.189151,0.556422,0.627487,-0.002613,-0.286703,0.021155,0.034809,-0.023225,-0.067844,0.318020,0.528582,-0.224685,0.320635,0.338328,-0.123989,-0.093161,0.134467,0.152493,-0.637935,0.204477,0.356667,0.215085,-0.788006,0.413441,-0.148579,-0.288191,-0.040952,-0.299369,0.208330,0.633123,0.088066,0.352058,-0.508575,0.078378,-0.645452,0.111056,0.789237,0.259352,0.229474,0.461805,-0.274809,-0.492053,-0.139301,-0.201790,-0.625018,0.151866,0.185811,0.252425,-0.152585,0.252888,-0.397943,-0.033717,-0.010385,-0.053325,0.047556,-0.748500,0.378106,-0.167549,-0.191487,-0.589584,-0.709934,0.131870,0.252892,-0.329855,0.847333,-0.897858,0.052165,0.250454,0.328322,-0.919844,0.693716,0.557112,0.246534,-0.373992,-0.054366,-0.005014,-0.140237,-0.069936,0.075630,0.333893,0.095777,-0.197383,-0.310775,0.192001', '1301022', '1949320', '1418613', '1309033');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292341', '性、谎言和录像带', '剧情', '格雷厄姆（詹姆斯•斯派德 James Spader 饰）有一个特殊的癖好，就是为各种各样的女人录影，这些女人在他的摄像机面前都毫不遮掩地谈论自己的性经验和其中细节。当格雷厄姆回到阔别多年的家乡时，他除了一辆汽车和这些录像带，一无所有。所以他只能暂时借住在同学约翰家。约翰（彼得•盖勒 Peter Gallagher 饰）是一名成功人士，他和妻子安（安迪•麦克道威尔 Andie MacDowell 饰）的妹妹辛西娅一直都在偷情，对妻子总是爱理不理。安陪着格雷厄姆去找租住的房子时，两人在餐厅进行了一次关于性的长谈，安坦言自己并不怎么重视性生活，而格雷厄姆则道出了自己的秘密：他性无能。安偶然发现了格雷厄姆为各色女人拍的录影带，因丈夫冷淡而内心苦闷的她决定也来录影。©豆瓣', '安迪·麦克道威尔', '史蒂文·索德伯格', 7.7, 38971, 'tt0098724', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p919743828.jpg', 0.6, 2.7, 28.5, 48.2, 20, '0.396849,-0.099713,-0.662192,0.740138,-0.315732,-0.477861,0.990394,0.222402,-0.510415,-0.467089,0.145405,0.859402,-0.203925,0.510609,0.175335,0.257491,-0.530109,-0.711639,-0.091342,-0.195446,-0.252170,-0.698367,0.012280,-0.461239,-0.063111,-0.076114,0.222004,-0.031242,-0.169822,0.070243,0.459348,0.295256,0.015803,0.623828,-0.225135,-0.101494,-0.199187,-0.148442,-0.219377,-0.063195,0.218825,-0.335866,-0.230478,0.326488,0.178394,0.424700,0.725266,-0.275303,-0.191408,0.080342,0.227074,0.024786,0.196687,-0.029567,0.076295,-0.163376,0.217406,0.196594,-0.046782,0.133014,0.192176,0.076374,-0.607472,0.020031,-0.165516,0.167504,-0.539077,0.543306,-0.226628,0.061103,0.059756,-0.454195,0.161451,0.321773,0.026108,0.293433,-0.248709,0.116047,-0.487275,0.070878,0.307784,0.311195,0.199428,0.491007,-0.348777,-0.428617,-0.076928,0.026897,-0.736076,-0.157477,0.241267,-0.043981,-0.113480,0.100332,-0.598760,-0.108667,-0.094788,-0.218713,0.065771,-0.457981,0.049776,-0.741880,0.092803,-0.445987,-0.389649,-0.083112,0.029355,-0.312629,0.618580,-0.819153,0.367160,0.594417,0.168744,-0.511952,0.643538,0.035240,0.043429,-0.296019,-0.270317,0.235439,0.149253,0.284070,0.151858,0.448330,0.259234,-0.100639,-0.241957,0.602750', '1309172', '3230121', '1296534', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292343', '蝴蝶效应', '剧情', '伊万（艾什顿·库奇 Ashton Kutcher 饰）曾经有一个糟糕的童年，因为他行为闯下了大祸，令他童年充满不堪回忆的往事。而事实上，他确实只是依稀记得一点可怕的情景，这些情景一直纠缠着他的正常生活。伊万接受心理学家建议，把琐碎生活记在记事本里，却偶然发现通过记事本回到过去。这时他才清楚记起，童年时候的自己做了那么多的错事。他幻想着用现在的意识，潜入童年的身体，去弥补种种过失给人们带来的伤害，尤其是希望与当年暗恋的凯西最终走回一起。然而他一次次的跨越时空的更改，只能越来越招致现实世界的不可救药。一切就像蝴蝶效应般，牵一发而动全身。©豆瓣', '阿什顿·库彻', '埃里克·布雷斯', 8.9, 874785, 'tt0289879', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209066019.jpg', 0.1, 0.6, 8.3, 38.2, 52.7, '0.327938,0.168939,-0.602423,0.501078,-0.256204,-0.316411,1.071752,-0.093823,-0.614785,-0.440803,0.018803,0.678031,-0.027999,0.323889,0.121903,0.023567,-0.347993,-0.617766,0.314849,-0.154311,-0.100138,-0.588527,-0.267867,-0.029987,-0.120462,-0.356113,0.523554,0.312165,-0.400687,0.083465,0.047040,0.104547,0.029321,0.665950,-0.027203,0.160204,-0.353597,0.418364,-0.309830,-0.181311,0.260473,-0.211534,-0.060548,0.435781,-0.048959,-0.029359,0.582620,-0.551979,-0.656272,0.058793,0.624432,-0.166431,-0.226618,0.098442,0.020350,0.307676,-0.028325,0.049114,-0.224501,0.014033,-0.044517,0.034176,-0.714702,-0.203154,-0.037644,0.148112,-0.633712,0.116830,-0.035557,0.184941,0.096124,-0.323288,0.075093,0.258716,0.570499,0.475019,-0.461630,-0.108984,-0.298110,0.226697,0.785846,-0.074174,-0.321235,0.410092,-0.499757,0.017442,-0.148069,-0.072415,-0.440166,0.245445,0.004005,0.154794,-0.656203,0.695730,-0.239996,0.075232,-0.220938,-0.370483,0.014425,-0.604480,-0.269346,-0.308798,-0.325618,-0.264453,-0.429338,-0.130505,-0.076852,-0.562321,0.552937,-0.699297,0.374929,0.807857,0.296316,-0.283946,0.483011,0.191166,0.064231,-0.067028,0.217497,0.679544,-0.158238,0.141899,0.109814,0.074895,-0.112562,-0.099195,-0.372971,0.643814', '1305666', '2377539', '25909236', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292344', '十二罗汉', '惊悚', '在赌城盗窃案三年之后，重归于好的丹尼（乔治-克鲁尼饰 George Clooney 饰）与泰丝（朱莉娅·罗伯茨 Julia Roberts 饰）二人的闲适生活戛然而止，因为赌场大亨班奈狄（安迪•加西亚 Andy Garcia 饰）突然将丹尼和十名同伙全部找到，并限定他们在两周内筹钱，连本带利偿还他当年被盗的一亿六千万。罗斯（布拉德•皮特 Brad Pitt 饰）、莱纳斯（马特·达蒙 Matt Damon 饰）等人齐聚，他们因无力偿还只得选择前往欧洲作案。然而丹尼等人的欧洲之行困难重重，法国神偷“夜狐”（文森特·卡索 Vincent Cassel 饰）在暗中作梗，罗斯的前任警探女友伊莎贝（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 饰）则率警方严密盯防他们。这次，丹尼的团伙还能顺利脱身么？©豆瓣', '乔治·克鲁尼', '史蒂文·索德伯格', 7.3, 109748, 'tt0349903', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p677457211.jpg', 0.5, 4.7, 40, 41.1, 13.6, '0.038142,0.024912,-0.629289,0.234643,0.057341,-0.450187,0.537299,0.136040,-0.442528,-0.273812,0.229809,0.768555,-0.152527,-0.093800,0.399943,0.136751,-0.539344,-0.699615,0.200707,-0.312504,-0.080562,-0.638799,-0.158688,-0.365433,-0.162124,-0.223143,0.112173,-0.048538,0.362914,0.630428,0.239184,0.314063,-0.033573,0.097376,0.074926,0.054136,0.441473,-0.301901,-0.409168,0.238404,0.062926,-0.125734,-0.109688,-0.067337,0.454208,0.344056,0.427375,-0.083190,0.337318,0.203719,-0.139348,-0.205156,0.072393,0.142803,0.006046,-0.442790,0.221931,0.455368,-0.378726,-0.077671,0.327858,-0.016179,-0.511314,0.296806,-0.029816,0.224231,-0.348334,0.275092,-0.493611,0.167590,0.004100,-0.325230,-0.135035,0.566982,0.278264,-0.098541,0.129113,-0.065871,-0.465605,0.224491,0.225333,-0.197153,0.015719,-0.181899,0.123694,-0.530585,-0.118920,0.019841,-0.360636,-0.079225,0.770377,-0.166302,0.349007,0.061500,-0.543689,-0.196331,-0.478951,-0.223392,-0.111755,-0.241121,0.196807,-1.075231,-0.068463,-0.200714,-0.216569,0.217511,0.131239,-0.143210,0.088360,-0.394464,0.198029,0.488247,0.319270,-0.325104,0.259595,-0.167260,0.357752,-0.205549,-0.263071,0.463139,0.341713,0.177931,0.286734,0.235406,0.203234,-0.058985,-0.086665,0.266385', '6517421', '2075345', '34961898', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292345', '沙漠妖姬', '剧情', '异装癖表演者班丽娜（Terence Stamp 饰）、米芝（Hugo Weaving 饰）因一位好友去世而再度聚首，米芝得到澳洲中部城市的表演机会邀请班丽娜同往，同行费莉茜（Guy Pearce 饰）为圆“沙漠女王”之梦要求搭伙，并借来了经改装的大巴作为代步工具。三人风风火火的踏上旅程，上了年纪的班丽娜于路对往事讳莫如深，与年轻躁动的费莉茜生出不少琐碎口角，米芝则不时陷入对自己那场婚姻的回忆。他们在沿途经过的小镇大秀妖冶，得到了不少惊愕的目光，当然也有赞许。因为一次抛锚，对班丽娜昔日表演难以忘怀的修理工老巴得以加入他们的旅程。众人终于抵达目的地，虽然观众不甚热情，但米芝终于见到了儿子，而班丽娜决定和老巴在一起……本片获1995年奥斯卡最佳服装设计奖等多项褒奖。©豆瓣', '雨果·维文', '斯蒂芬·埃利奥特', 8.3, 7370, 'tt0109045', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1196536905.jpg', 0.4, 1.2, 15.7, 47.4, 35.2, '0.026809,-0.002446,-0.632385,0.490128,0.265333,-0.464553,0.669504,-0.121000,-0.539638,-0.270541,0.204255,0.695543,-0.483399,0.152182,0.447058,-0.474492,-0.464089,-0.416877,0.099417,-0.203072,-0.218745,-0.284636,-0.005287,-0.023578,-0.117844,-0.368781,0.649594,0.272185,-0.029879,0.931117,0.379005,0.167835,-0.153498,0.319204,-0.315344,-0.213845,0.044465,0.252338,-0.513339,0.076502,-0.326910,-0.205982,-0.298444,-0.043402,0.102186,0.190889,0.904465,-0.054779,-0.385416,0.059182,0.139657,-0.134998,0.319169,0.022940,0.185368,0.274352,0.317558,0.162356,-0.199570,0.032653,-0.164138,-0.116083,-0.523563,0.224555,0.106234,0.013789,-0.458044,0.452108,0.118979,-0.264963,-0.011972,-0.248469,0.209385,0.349838,0.453054,0.333166,-0.118588,0.208262,-0.181536,0.112851,0.664224,0.139009,0.121965,0.495902,-0.118016,-0.627518,0.105679,-0.081542,-0.225866,0.097130,0.366596,0.157471,0.083307,0.235254,-0.469933,-0.048784,-0.118582,-0.491322,0.310418,-0.348511,0.027041,-0.834156,0.054828,-0.285300,-0.183808,0.214211,0.149566,-0.142631,0.672020,-0.735336,0.220947,0.253730,0.100670,-0.616764,0.670480,-0.007014,0.109425,-0.377113,-0.036425,0.192522,-0.108427,0.127550,-0.012436,0.134959,-0.328315,-0.262671,-0.373028,0.330060', '3811356', '26365262', '2159244', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292347', '黑客帝国动画版', '剧情', '《黑客帝国动画版》由9段以《黑客帝国》系列电影世界观为基础生发出的短片组成，各篇的角度与风格各异，制作班底汇聚了日本、美国、韩国三地的动画精英。《机器复兴》讲述了MATRIX的历史。机器人不堪人类恶劣对待，终于反抗并将人类化为能源。《少年故事》讲述一名少年突然收到来自网络的召唤，而大批黑衣人开始对他展开围捕。《虚拟程序》展示了一对男女在虚拟训练程序中的片断。《世界纪录》描写一位短跑运动员在接近突破人类极限时终被系统牢牢控制。《超越极限》叙述因为系统错误，平静的街区中出现了一片超常区域。《侦探故事》描写一位侦探被步步引领着试图摆脱系统的桎梏。《矩阵化》讲述一只机器人被人类捕获并驯化的故事。《终极战役》记录了一艘飞船毁灭的经过。©豆瓣', '大塚明夫', '钟彼得', 8.8, 47326, 'tt0328832', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2264262299.jpg', 0.4, 1, 10.4, 34.2, 54, '0.247694,0.237082,-0.206463,0.786760,0.196970,0.223227,0.558040,-0.274434,-0.201818,-0.176263,0.222416,0.646169,-0.401171,-0.088271,0.218333,-0.431485,-0.076811,-0.587452,-0.163045,-0.074694,-0.253916,-0.361538,-0.293986,-0.258553,0.031699,-0.660446,1.166458,-0.046477,-0.695134,0.092190,-0.057819,0.173898,-0.461850,0.073898,-0.043082,-0.138784,0.164605,-0.208848,-0.111374,0.185471,-0.583415,-0.100046,0.397508,0.141128,-0.646305,0.108171,1.177238,-0.580497,0.002346,-0.246287,0.724701,-0.211512,-0.189742,-0.184068,0.458621,0.548690,-0.161398,0.172791,0.204277,0.260194,-0.194107,-0.475428,-1.027218,-0.449730,0.017558,-0.000193,-0.305866,0.019325,-0.193223,0.039568,0.047062,-0.118127,-0.132927,0.064329,0.715518,0.614068,-0.115620,0.077608,-0.245990,0.509807,0.033270,-0.171265,-0.857866,0.526035,-0.132948,-0.711027,-0.523735,-0.386378,-0.262649,-0.067761,0.074058,0.219040,-0.265880,0.406120,-0.807352,0.149441,-0.203450,-0.584233,-0.016959,-0.391357,-0.319796,-0.928542,-0.288753,0.135781,0.114507,0.017017,0.030750,-0.247572,0.965689,-0.669532,0.088838,0.499735,0.090682,-0.323411,0.389959,-0.138012,0.109526,-0.535849,0.163148,0.267602,0.045922,0.443630,0.005744,0.340379,-0.190487,-0.006067,-0.630161,0.720287', '26759820', '1322847', '25880986', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292348', '洛城机密', '剧情', '此片根据詹姆斯·艾罗瑞(James Ellroy)的小说改编，描写了1950年代，警界腐败、犯罪纵横的洛杉矶。杰克·文森（凯文·斯派西 饰）是警界名人，常常出现在电视媒体中，与《嘘嘘报》的八卦记者狼狈为奸，靠制造和揭发明星的桃色新闻，赚取外快。艾德·艾斯力（盖·皮尔斯 饰 ）子承父业进入警局，野心勃勃，做事严谨，因为出卖同事而升职，受到大家的排挤；巴德·怀特（罗素·克劳 饰） 铁面无私，但是个性冲动，容易遭人利用。一桩疑似抢劫的餐厅命案将这三个人联系起来。艾德·艾斯力找到了三个黑人嫌疑犯，并被判死刑结案，还因此收到上级嘉奖，但是他却在进一步的调查中发现案子并没有那么简单，他说服了杰克·文森和他一起继续追查；巴德·怀特对餐厅命案一直心存怀疑，他找到的线索也显示，案子根本没有想象中那么简单。三个人迅速被卷入一个色情、毒品、谋杀、背叛、贪污、阴谋交织的网中，惊人的内幕......', '凯文·史派西', '柯蒂斯·汉森', 8.8, 136644, 'tt0119488', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2268612099.jpg', 0.1, 0.4, 8.3, 42.2, 49, '0.474204,-0.200795,-0.404915,0.397184,-0.135213,0.063535,0.747658,0.127764,-0.553454,-0.249374,-0.024402,0.569140,-0.291210,-0.165364,0.227249,-0.111496,-0.460291,-0.747632,0.396534,-0.045302,-0.016764,-0.844018,-0.208639,-0.492252,-0.092875,-0.148208,0.341175,0.179955,-0.372424,0.406938,0.260989,0.158009,-0.218779,0.501274,0.034576,0.068020,0.354758,-0.020890,-0.073532,0.264579,0.046936,-0.196464,-0.056661,0.242598,0.122684,0.562133,0.113175,-0.162582,-0.283885,0.096511,0.517897,-0.390401,-0.163432,0.093558,0.408518,0.023330,0.133651,0.493786,-0.180905,-0.047173,0.133711,0.192031,-0.728802,-0.137782,0.055314,0.244794,-0.343493,0.165709,-0.115315,0.106769,-0.118513,-0.022812,0.147532,0.238626,0.212829,0.006205,0.110945,-0.067744,-0.622674,0.211343,0.355373,-0.211298,-0.206608,0.017646,-0.106549,-0.254378,-0.078376,-0.130628,-0.131265,0.058183,0.287681,-0.241456,-0.134458,0.223318,-0.412789,-0.132964,-0.260029,-0.099256,-0.216260,-0.414179,-0.139561,-0.865297,-0.382955,0.014438,-0.476124,-0.122620,-0.070625,-0.417034,0.254680,-0.547689,0.118298,0.700776,0.276441,-0.656611,0.560441,0.161098,-0.035394,-0.150738,-0.401715,0.122605,0.533942,0.156359,0.131001,0.148834,0.057111,-0.532836,-0.167613,0.162883', '1307442', '26703844', '3006781', '25862560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292349', '阿拉伯的劳伦斯', '剧情', '1916年，阿拉伯大起义爆发。 英军中尉 Lawrence（Peter O''Toole 饰）受命登上阿拉伯半岛之后，决定带领阿拉伯人夺取亚喀巴。在穿越沙漠的过程中， Lawrence 力排众议孤身返回搭救了失踪的 Gasim（I.S. Johar 饰）。此举赢得了众人的尊敬，Ali ibn el Kharish（Omar Sharif 饰）沙里夫甚至让 Lawrence 换上了沙里夫的长袍，而 Lawrence 也欣然接受。可是阿拉伯部落间并不和睦，Harith 部的 Gasim 杀了 Howeitat 部的人，双方剑拔弩张。为了平息争端，Lawrence 亲手处决了 Gasim，而杀人的快感却让 Lawrence 感到不安。成功夺取亚喀巴之后，Lawrence 驼不停蹄地穿越西奈半岛回到开罗。Allenby（Jack Hawkins 饰）将军大喜过望，升 Lawrence 为少校，对其寄予厚望……', '彼得·奥图尔', '大卫·里恩', 8.7, 46441, 'tt0056172', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1697190295.jpg', 0.3, 1.1, 10.6, 38.1, 49.9, '0.091915,0.224063,-0.761602,0.605118,0.105131,-0.306717,0.283181,0.138418,-0.600781,-0.090565,0.120649,0.747834,-0.166649,-0.258384,0.542416,0.143114,-0.379781,-0.762835,-0.257133,-0.139320,-0.232897,-0.304117,-0.175001,-0.399726,-0.138933,-0.573069,0.610072,0.495053,-0.350573,0.824461,0.355180,0.342681,0.242964,0.555851,0.173847,-0.268099,-0.016784,0.008874,-0.207708,0.252989,-0.284023,-0.262697,-0.126976,0.356017,-0.067846,0.480307,0.702758,-0.439551,0.107120,-0.257664,0.129491,-0.601995,0.043828,0.086591,0.161695,0.313027,-0.220122,0.304677,-0.166246,0.106284,-0.018038,-0.089432,-0.525425,0.215535,0.030716,-0.231767,-0.658461,0.447030,-0.154638,-0.018501,0.218775,-0.125617,0.057220,0.743439,0.286237,0.268697,-0.097676,-0.049856,-0.526740,0.059110,0.851767,-0.413819,-0.106365,-0.126079,0.041317,-0.456770,0.385285,-0.205197,-0.018134,-0.219080,0.113706,0.239735,0.252725,0.209401,-0.672407,-0.069379,-0.745425,-0.308206,0.077968,-0.285766,-0.116571,-0.390421,-0.274350,-0.096940,-0.106075,0.060457,0.153988,0.058972,0.435191,-0.595485,0.313006,0.227776,0.330503,-0.587493,0.454168,0.079889,-0.018680,-0.247647,-0.025036,0.184344,0.100933,0.423113,0.155028,0.010190,-0.481941,-0.426387,-0.356246,0.132337', '1302987', '25908042', '3078390', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292365', '活着', '剧情', '根据余华同名小说改编。富少福贵（葛优）嗜赌成性，妻子家珍（巩俐）屡劝无果后带着女儿凤霞离开了他，当夜，福贵输光所有家产气死父亲，被迫靠变卖母亲首饰租间破屋过活。一年后，家珍手拉凤霞怀抱刚出世的儿子有庆回到家中，福贵痛改前非，开始靠演皮影戏过起安份守己的日子。但好景不常，内战时期，福贵被国民党抓去当劳工，一番辗转终回到家乡与一家人团圆后，凤霞因病变成哑巴，而在后来的大跃进运动和文化大革命中，他虽获某些小福，逆境却也一直与他如影相随。©豆瓣', '葛优', '张艺谋', 9.3, 776429, 'tt0110081', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2597919477.jpg', 0.1, 0.3, 4, 26.1, 69.6, '-0.230381,0.046203,-0.586277,0.196862,0.064522,-0.638149,0.619683,0.183495,-0.579397,-0.208842,-0.066664,0.703264,-0.084992,0.500172,0.203174,0.124468,-0.320921,-0.532143,-0.095951,0.103978,0.155844,0.004297,0.240383,0.201630,-0.255427,-0.027891,0.472339,0.122405,0.169912,0.390420,0.264931,0.099946,-0.205988,0.108799,-0.359015,0.509146,-0.331399,0.193080,-0.492289,0.144572,0.191932,-0.177842,-0.437821,-0.262866,0.142757,0.067063,0.593954,-0.061557,0.088769,-0.316350,0.198861,-0.004763,-0.425483,0.209276,0.180473,0.188203,0.457952,0.308946,-0.248066,0.113741,-0.121420,-0.053049,-0.032968,-0.080041,0.011648,-0.101316,-0.638150,0.185336,0.036602,0.359693,-0.210571,-0.365182,0.174590,0.389783,-0.032565,0.397078,-0.374677,0.088554,-0.521860,0.497400,0.512212,-0.294985,0.106975,0.359788,0.251814,-0.209089,0.467737,-0.321090,-0.413789,-0.135560,0.268498,0.083587,-0.279578,0.242756,-0.401033,-0.143533,-0.165670,-0.016859,0.312705,-0.206670,-0.124978,-0.330463,-0.122210,-0.281403,-0.235462,0.065243,0.047200,-0.197008,0.398606,-0.432250,0.391940,0.135657,0.113002,-0.556111,0.251252,0.070798,0.458846,-0.058130,0.185143,0.315675,0.066704,0.342310,0.236633,-0.110980,-0.211171,-0.042829,-0.240373,0.467983', '1306505', '1294038', '25909389', '1309226');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292370', '剪刀手爱德华', '剧情', '爱德华（约翰尼•戴普 饰）是一个机器人，他拥有人的心智，却有一双剪刀手，孤独地生活在古堡里，闯入古堡的化妆品推销员佩格把他带回家，让他走进了人类的世界。单纯的爱德华爱上了佩格的女儿金（薇诺娜•瑞德 饰），金也慢慢的被爱德华的善良所吸引。但是，一连串的意外事情让周围的人邻居对爱德华的态度从喜欢变成无法接受，爱德华痛苦地发现，他总是好心办坏事，连自己的爱人都不能拥抱，或许，他注定就不属于这个世界。©豆瓣', '约翰尼·德普', '蒂姆·波顿', 8.7, 985652, 'tt0099487', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p480956937.jpg', 0.2, 0.8, 10.6, 39.9, 48.5, '0.329681,0.264704,-0.799076,0.678286,-0.755154,-0.109967,1.015698,0.066886,-0.385420,-0.102270,0.140050,0.926402,0.029885,0.271160,0.120577,0.512221,-0.118564,-0.669397,-0.077751,-0.020048,-0.322816,-0.419463,-0.316147,-0.742186,-0.101842,-0.304101,0.545376,0.257978,-0.280654,0.121447,0.346207,0.284771,0.300534,0.626892,-0.171399,0.091243,0.146469,0.160654,0.093931,0.116980,-0.060139,-0.057582,-0.005098,0.605195,-0.192951,0.231481,0.664556,-0.455166,-0.146256,-0.031740,0.189247,-0.353201,-0.003392,0.098550,-0.032274,-0.131022,-0.052909,0.096537,-0.188041,0.022240,0.336185,0.159006,-0.796019,-0.035868,0.162037,0.221339,-0.647386,0.421228,-0.137200,-0.068920,0.086891,-0.328617,0.037972,-0.076169,0.429484,0.559941,-0.081200,0.129086,-0.514789,0.051846,0.648709,0.114799,-0.492264,0.562951,-0.785008,-0.421761,-0.207449,-0.191482,-0.747408,0.005750,0.343732,-0.097966,-0.315435,0.420189,-0.566434,-0.188034,-0.179258,-0.202170,-0.100415,-0.597163,-0.160704,-0.297129,-0.139964,-0.511522,-0.489018,-0.022733,-0.186652,-0.290725,0.783804,-0.741962,0.253668,0.656653,0.315015,-0.470035,0.900913,0.103438,-0.165782,-0.274516,-0.011526,0.480720,0.023386,0.166773,0.248084,0.287473,0.103628,0.027696,-0.435080,0.841099', '26884422', '35158375', '1300754', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292371', '四月物语', '爱情', '17岁少女榆野卯月（松隆子 饰）从北海道独自来到东京的武藏野大学读书。她需要独自面对新的城市，新的生活，新的环境，她到了学校也非常羞涩，同学们纷纷讨论为何会来武藏野读书，其实她来到这里的一个重要原因是因为她一直暗恋一个名叫山崎的男孩子。来到这里后，她发现原来他在一间书店里做兼职售货员，榆野卯月开始频繁的光顾这间书店，渐渐的开始交谈……©豆瓣', '松隆子', '岩井俊二', 8.2, 179400, 'tt0146271', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2107289058.jpg', 0.2, 1.3, 18.4, 47, 33.1, '0.627851,0.058207,-0.862271,0.252064,-0.152580,-0.190556,0.629727,0.115985,-0.514288,-0.570550,0.222920,0.902181,-0.041479,0.868727,0.274751,-0.010143,-0.230463,-0.433801,0.092759,-0.504077,-0.452409,-0.069163,-0.093879,-0.232664,-0.241622,0.029490,0.306555,0.148821,0.197044,0.372196,0.222375,0.360363,-0.021270,0.435280,-0.116863,-0.193643,0.475703,0.208355,0.197463,0.270377,-0.269788,-0.250627,-0.329273,-0.089190,0.350865,0.323349,0.875603,0.265107,-0.272634,0.005638,0.459455,0.075327,-0.267684,0.021540,0.537388,-0.088143,0.230344,-0.050205,-0.304536,0.176705,-0.511793,-0.412779,-0.156190,0.154921,0.119798,0.221440,-0.377983,0.223069,0.271727,-0.368902,0.359266,-0.628199,0.048132,0.471640,0.080098,0.355427,-0.129294,0.230288,-0.136774,0.203906,0.715839,-0.171374,0.023352,0.542015,-0.073724,-0.291330,0.150250,0.033076,-0.499379,-0.167000,-0.277518,-0.012336,-0.165954,-0.286757,-0.696621,0.122604,0.155633,-0.255133,0.400598,-0.138920,-0.391337,-0.764618,0.097392,-0.433386,-0.152131,0.188229,-0.089843,-0.145957,0.890481,-1.135536,0.042038,0.571587,0.250812,-0.560613,0.530378,-0.134758,0.119392,-0.108508,0.026923,0.257327,-0.135817,0.583448,-0.280072,0.420901,-0.025762,-0.110894,-0.527701,0.432930', '1292219', '30205667', '25922902', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292396', '香港制造', '剧情', '有惨淡家境的香港街头小混混中秋（李灿森）虽对未来迷茫，为人却很豪爽讲义气，将总被人欺负的弱智男孩阿龙（李栋泉）当作自己的亲人“罩”着，可是在他被仇家捅成重伤躺在医院时，老大派去运毒的阿龙被人打死。而另外两个与他的生命有过交叉的少女——留下两封遗书跳楼自杀的女中学生 阿珊（谭嘉荃）、他爱上的等不到合适肾源医治绝症的濒死少女阿屏（严栩慈）——的“命中注定”，则加重了他青春的绝望。他能走的路，似乎只有听天由命。©豆瓣', '李灿森', '陈果', 8.2, 41616, 'tt0123328', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2354808571.jpg', 0.3, 1.5, 16.9, 49.5, 31.8, '0.324592,-0.184682,-0.500456,0.332683,-0.455567,-0.243985,0.920178,0.204893,-0.470180,0.127917,0.351545,0.641882,0.201610,0.481081,0.152964,0.173154,-0.009842,-0.633408,-0.054209,-0.032795,-0.501724,-0.374820,0.057295,-0.141950,-0.127473,-0.125622,0.410213,-0.110723,-0.072349,0.322109,0.224285,0.351008,-0.110121,0.571739,-0.507821,0.289042,-0.222560,-0.152886,-0.004681,0.156703,0.160448,-0.223156,-0.019771,0.085661,-0.324005,0.589173,0.660586,0.042661,-0.171038,-0.101514,0.372895,-0.379241,-0.109012,0.245355,0.150507,-0.106128,0.240497,0.008235,-0.137770,-0.291860,0.195328,0.183079,-0.789159,0.097297,0.086514,0.184721,-0.769872,0.840606,-0.060252,-0.049043,0.125211,-0.253447,0.398558,0.131727,-0.129610,0.288429,-0.131739,-0.005392,-0.651607,0.373953,0.643727,0.099264,-0.239281,0.277626,-0.226480,-0.246126,0.123364,-0.363845,-0.476542,0.033512,0.602637,-0.175902,-0.565678,-0.137353,-0.300671,-0.036800,-0.035683,0.099788,-0.280465,-0.507605,-0.299356,-0.155274,0.071431,-0.251203,-0.413659,0.296140,0.222332,-0.267385,0.678008,-0.453221,0.154377,0.683217,0.286783,-0.309723,0.882833,0.168742,-0.003485,-0.032443,-0.297609,0.301077,0.133682,0.365463,0.577973,0.173709,-0.364602,0.271654,-0.487283,0.465735', '1783772', '26884422', '10486471', '25799331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292401', '真爱至上', '剧情', '这是一出10个爱情故事串成的喜剧杂烩：失去母亲的小男孩终日郁郁寡欢，继父不知该如何安慰。当他得知继子喜欢上学校里最美的女孩，便热烈地鼓励儿子去追。小男孩为了赢得小女孩的关注，废寝忘食地练习架子鼓，只为了在圣诞节的晚会上能与她同台演出。勇敢的他，甚至为了最后的一记道别潇 洒地突破机场的安检区。两个孩子的母亲面对了婚姻危机。丈夫感情出轨，把项链送给了别的女人，给她的，则仅是一张她热爱的女歌手的CD。她找了借口仓皇躲入卧室，在歌声中隐忍啜泣。转个身，又夸张地大笑着，迎向娇女爱子欢喜的面容。 丈夫最终幡然醒悟。……如此的小故事共有十出，温暖你我的心。©豆瓣', '休·格兰特', '理查德·柯蒂斯', 8.6, 683296, 'tt0314331', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p475600770.jpg', 0.4, 1.4, 13.8, 38.3, 46.2, '0.125675,0.084066,-0.594799,0.668887,-0.213569,-0.408620,0.729217,0.089462,-0.122220,0.081089,0.324379,0.668021,-0.174400,0.492348,0.210771,0.121952,-0.142264,-0.758897,-0.320978,-0.147849,-0.170576,-0.203466,-0.161949,-0.097647,-0.131687,-0.091864,0.358696,0.042940,-0.196283,0.209849,0.603422,0.023056,0.052592,0.275634,-0.189592,0.007457,-0.375608,0.187773,-0.116598,0.119299,0.221440,-0.387005,-0.282108,0.207674,-0.059189,0.167283,0.930767,-0.224268,0.312124,-0.089996,0.376348,-0.109143,0.041686,0.122579,-0.051736,0.100068,0.369856,0.031279,-0.210877,-0.070561,0.179734,-0.131927,-0.552285,0.157263,0.063812,-0.016674,-0.549677,0.410914,-0.175536,0.044988,0.419467,-0.345229,0.149154,0.204907,0.023239,0.795723,-0.378990,0.278217,-0.229486,0.375607,0.465974,0.091209,0.145709,0.395898,-0.298588,-0.352555,0.146672,-0.305089,-0.537390,-0.113250,0.326940,0.024185,-0.150257,0.077015,-0.421421,-0.008943,-0.210036,-0.068968,0.060071,-0.551577,-0.252161,-0.251244,0.200837,-0.137780,-0.222984,-0.047841,-0.019744,-0.232425,0.855023,-0.633387,0.081054,0.524545,0.269408,-0.358721,0.732088,0.307151,0.028374,-0.245918,-0.023696,0.462590,-0.211058,0.120127,0.012108,0.225261,-0.233182,0.104446,-0.582760,0.479018', '1307146', '1945253', '2081098', '1292001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292402', '西西里的美丽传说', '剧情', '当我还只是十三岁时，1941年春末的那一天，我初次见到了她那一天，墨索里尼向英法宣战，而我，得到了生命里的第一辆脚踏车。她，撩著波浪状黑亮的秀发，穿著最时髦的短裙和丝袜，踏著充满情欲诱惑的高跟鞋，来到了西西里岛上宁静的阳光小镇。她的一举一动都引人瞩目、勾人遐想，她的一颦一笑都教男人心醉、女人羡妒。玛莲娜，像个女神一般，征服了这个海滨的天堂乐园。年仅十三岁的雷纳多也不由自主地掉进了玛莲娜所掀起的漩涡之中，他不仅跟著其他年纪较大的青少年们一起骑著单车，穿梭在小镇的各个角落，搜寻著玛莲娜的诱人丰姿与万种风情，还悄悄地成为她不知情的小跟班，如影随形地跟监、窥视她的生活。她摇曳的倩影、她聆听的音乐、她贴身的衣物都成为这个被荷尔蒙淹没的少年，最真实、最美好的情欲幻想。然而，透过雷纳多的眼，我们也看到了玛莲娜掉进了越来越黑暗的处境之中，她变成了寡妇，而在镇民们的眼中，她也成了不折不扣的祸水，带来了淫欲、嫉妒与忿怒，而一股夹杂著情欲与激愤的风暴，开始袭卷这个连战争都未曾侵扰的小镇。玛莲娜一步步地沉沦，与父亲断绝了关系、被送上法院，更失去了所有的财产，这使得向来天真、不经世事的雷纳多，被迫面对这纯朴小镇中，人心的残暴无情，看著已经一无所有的玛莲娜，雷纳多竟鼓起了他所不曾有过的勇气，决定靠著他自己的力量，以一种教人难以料想的方式，来帮助玛莲娜走出生命的泥沼……', '莫妮卡·贝鲁奇', '朱塞佩·托纳多雷', 8.9, 913140, 'tt0213847', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2441988159.jpg', 0.1, 0.4, 7.4, 37.1, 55, '0.449528,0.096860,-0.975022,0.708653,-0.343263,-0.360130,0.891596,0.164681,-0.293799,0.009260,0.042026,0.698762,-0.108706,0.278878,0.306224,0.273906,-0.327829,-0.816652,-0.239506,-0.116009,-0.262341,-0.306586,-0.185766,-0.034078,-0.029550,-0.326769,0.571335,0.122618,-0.189894,0.392892,0.402834,0.133321,0.101998,0.508081,-0.295210,-0.067207,-0.118445,-0.031370,0.124070,0.089388,-0.084188,-0.303215,-0.140320,0.265871,-0.353656,0.166534,0.742208,-0.417677,0.111171,-0.206705,0.300376,-0.357231,0.073134,0.352819,-0.067556,-0.129815,0.113531,-0.024996,-0.261331,0.029562,0.152732,0.063059,-0.664331,-0.032436,-0.005008,0.062651,-0.454605,0.292660,0.213692,-0.172727,0.224250,-0.286117,0.063512,-0.063503,-0.158631,0.433110,-0.338976,-0.115630,-0.659043,0.027898,0.526229,0.113437,-0.373015,0.384176,-0.373987,-0.412935,-0.130176,-0.213517,-0.539149,-0.191408,0.354162,0.185686,-0.209970,0.488941,-0.831297,0.199753,-0.238460,-0.344735,-0.292586,-0.471002,-0.206808,-0.395652,-0.443761,-0.707132,-0.338487,0.194420,0.143577,-0.071507,0.685038,-0.651797,0.285941,0.609736,0.250492,-0.289840,0.640719,0.041480,0.156373,0.103777,-0.328088,0.545254,-0.022504,0.444765,0.094287,0.524680,-0.260336,0.179112,-0.546797,0.591799', '34461680', '24756472', '21619567', '3431336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292403', '猎鹿人', '剧情', '越战期间，美国克莱顿镇5个经常一起打猎野鹿的好朋友中的三人尼克（克里斯托弗•沃肯 Christopher Walken 饰）、史蒂芬（约翰•萨维奇 John Savage 饰）和迈克尔（罗伯特•德尼罗 Robert De Niro 饰）即将奔赴前线。离开前夕，史蒂芬和另一个好友兼女友安吉拉结了婚，婚礼就是他们的告别会。三个年轻人在战场上被越军俘虏了，残忍的越军逼他们玩“俄罗斯轮盘”游戏，迈克尔乘机夺了越军士兵的枪。虽然顺利三个好友逃了出来，但在逃亡过程中他们失散了。迈克尔和史蒂芬最终顺利回到了美国，但史蒂芬终身残废了，住在疗养院不愿回家拖累家人。越战结束前夕，迈克尔从史蒂芬处得知他经常受到从西贡寄来的匿名的汇款，迈克尔断定一定是尼克。为了找回好兄弟，迈克尔决定再次冒险闯荡越南。©豆瓣', '罗伯特·德尼罗', '迈克尔·西米诺', 8.4, 35105, 'tt0077416', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1322206300.jpg', 0.6, 1.6, 14.5, 46.4, 37, '0.279119,-0.189568,-0.516742,0.328803,-0.044077,-0.482357,0.341220,0.094138,-0.475655,-0.057616,0.141647,1.010652,0.019176,0.231416,0.256781,-0.060334,-0.400510,-0.530914,0.016159,-0.127068,-0.322815,-0.472199,-0.128760,-0.204924,-0.098715,-0.217231,0.412655,-0.083308,0.046657,0.743830,0.293026,0.115747,-0.087184,0.288951,0.057614,0.239193,0.283985,-0.186859,-0.547538,0.452137,0.175131,-0.040689,-0.152882,-0.147805,0.344868,0.315219,0.602836,-0.035117,0.182870,0.000991,0.193467,-0.202652,-0.107883,0.156529,0.203619,-0.072037,0.322655,0.154504,-0.241718,-0.075679,-0.072718,-0.198434,-0.332299,0.340030,-0.164155,-0.044291,-0.708111,0.515160,-0.206370,0.292798,0.212288,-0.334498,0.128987,0.530227,0.169047,0.038610,-0.108431,-0.046692,-0.290318,0.090411,0.818610,-0.292022,-0.011347,-0.038612,0.133223,-0.161792,0.038945,-0.217521,-0.552858,0.129388,0.695269,-0.173700,-0.264576,0.095921,-0.491764,-0.130708,-0.409178,-0.058811,-0.073569,-0.149890,-0.010645,-0.794839,-0.021412,-0.215876,-0.233037,0.035473,-0.227990,-0.066261,0.372830,-0.655140,0.408393,0.579185,0.232600,-0.389754,0.685753,0.188660,0.315461,-0.224467,0.181095,0.301964,0.377918,0.224891,0.370917,0.336459,-0.110741,-0.160342,-0.173627,0.343292', '1829654', '11541282', '1297239', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292434', '一一', '剧情', 'NJ（吴念真）是个很有原则的生意人，同妻子敏敏（金燕玲）、女儿婷婷（李凯莉）、儿子洋洋（张杨洋）以及外婆住在台北某所普通公寓里。小舅子的一场麻烦婚礼过后，因为外婆突然中风昏迷，他迎来更加混乱的日子。敏敏公司、家里两头跑，时常感觉自己要被耗空；婷婷一直为外婆的中风内疚，恋爱谈到中途发现自己不过是替代品；NJ更是麻烦重重，公司面临破产，他又不愿放下别人眼里一文不值的自尊。一家人里，似乎只有洋洋没有烦恼，他平静地用照相机拍着各种人的背面，帮他们长出另一双眼睛，然而，洋洋简简单单的一句话，道出更深的悲凉。©豆瓣', '吴念真', '杨德昌', 9.1, 351911, 'tt0244316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2567845803.jpg', 0.3, 0.8, 7.1, 26.9, 64.8, '0.303374,0.000697,-0.571105,0.230416,0.029268,-0.345268,0.885507,0.197442,-0.584163,-0.334237,0.065177,0.505820,-0.117248,0.522125,-0.023085,0.141935,-0.238954,-0.374441,0.073175,-0.003888,0.033078,-0.412734,-0.054669,-0.002077,-0.264546,0.076524,0.232605,-0.121317,-0.037353,0.349536,0.065142,0.383745,0.165007,0.466524,-0.120003,0.067897,-0.411559,0.178884,-0.195422,-0.002844,0.554731,0.105846,-0.167706,0.251294,-0.117163,0.297717,0.367145,0.253904,-0.222953,-0.049413,0.416970,-0.244837,-0.225681,-0.046473,0.183196,0.018626,0.520641,-0.007919,-0.350566,-0.147932,0.267170,0.004217,-0.246324,0.061166,-0.028137,0.121648,-0.427024,0.496656,-0.098191,-0.022478,0.280920,-0.352832,0.370334,0.320151,0.069101,0.529371,-0.403184,0.173170,-0.487660,0.103239,0.577653,-0.120399,0.150880,0.390858,-0.274814,-0.014981,0.407363,-0.336325,-0.467747,0.233749,-0.091166,-0.019420,-0.284947,0.325966,-0.290433,0.178965,-0.023534,-0.121854,-0.147063,-0.461538,-0.214608,-0.032358,-0.100370,-0.274768,-0.408964,-0.045431,0.028562,-0.131449,0.379584,-0.778252,0.159920,0.166386,0.396567,-0.063464,0.433775,0.201448,0.139120,-0.174418,-0.122667,-0.085891,-0.457184,0.203848,0.342423,-0.026830,-0.051899,-0.132986,-0.120797,0.370125', '1308755', '1302384', '1296370', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292440', '一条叫旺达的鱼', '喜剧', '一部令人忍俊不禁的喜剧。四个贼人在策划一桩钻石盗窃案，成员有患有口吃的肯（麦克·帕林 Michael Palin饰）、乔治（汤姆·乔治森Tom Georgeson饰）、乔治的女友旺达（杰米·李·柯蒂斯 Jamie Lee Curtis饰）——碰巧肯把他最爱吃的鱼也称为“旺达”、奥托（凯文·克莱恩 Kevin Kline饰）。尽管盗窃过程发生了小插曲，几人还是得到了价值连城的宝贝，怎料麻烦事却一桩接一桩。旺达和奥托出卖乔治向警察告密，乔治被捕，钻石却被他藏了起来。为了打听钻石下落，旺达色诱乔治的律师利奇（约翰·克立斯 John Cleese饰），险些被利奇自己捉奸在床。慌乱逃脱的旺达遗留了一条项链在利奇家，上面有打开钻石宝盒的钥匙。旺达沮丧万分，千方百计问利奇要回项链，欲速不达的她闹出了幕幕笑话，那边厢凶神恶煞的肯又即将杀到……©豆瓣', '约翰·克里斯', '查尔斯·克莱顿', 7.6, 25900, 'tt0095159', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1259577248.jpg', 0.5, 2.7, 29.2, 50.1, 17.5, '0.214369,0.028501,-0.385099,0.267153,0.084925,-0.465470,0.910235,0.097109,-0.322395,-0.177036,0.281988,0.447488,-0.560315,-0.005063,0.119126,0.364643,-0.399909,-0.404981,0.432787,-0.361674,-0.150148,-0.315248,-0.329947,-0.314792,-0.041724,-0.141836,0.157688,-0.026938,-0.000363,0.128520,0.597374,0.408004,0.225172,0.243537,-0.048996,0.232960,0.136012,-0.166481,-0.024137,0.079100,0.113291,-0.216337,-0.006188,0.257040,0.152088,0.290547,0.309957,-0.248778,0.254246,0.173551,0.250341,-0.204413,0.046470,-0.084037,0.164273,-0.179997,-0.300845,0.006384,-0.497836,-0.160094,0.633898,0.027892,-0.658862,0.116762,-0.112429,0.499627,-0.451939,0.112132,-0.397933,0.419945,0.136712,-0.426228,0.163293,0.192030,0.013102,0.151845,0.147528,0.059217,-0.751273,0.207114,0.237732,-0.135355,0.241175,0.079283,-0.222577,-0.344032,0.156284,-0.072828,-0.327491,0.084840,0.951367,-0.345873,0.107734,0.136705,-0.546841,-0.380949,-0.408650,-0.089434,-0.005654,-0.346774,-0.104920,-0.403428,0.108074,-0.022888,-0.231145,0.022203,-0.099801,-0.233932,0.506863,-0.184692,-0.005269,0.547973,-0.132202,-0.104385,0.462893,-0.134825,-0.047929,-0.231993,-0.103669,0.157077,0.449039,0.188094,0.439274,0.452122,0.346916,-0.336910,-0.223393,0.150694', '1301345', '1578663', '1301686', '1296718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292444', '大逃杀', '剧情', '为了培养出忠实效忠于成人、在逆境中坚忍不拔的青少年一代，日本政府出台《BR》法案。每年都从全国学校随机抽出一个班级的同学，前往荒岛进行生存极限挑战——老师发给学生地图、粮食和各式武器，令他们自相残杀，直到存活下来的最后一个，才能离开荒岛。接下来，残酷的游戏规则和令人绝望的生存条件，使班级里的年轻人开始了相互杀戮。善良或者凶残，主动出击或者被动防守， 同学们开始了各自的计划，人性的丑恶在血腥的死亡中暴露无遗。大逃杀的游戏在荒岛上壮烈上演。究竟学生们的宿命如何，谁才是最后的存活者。©豆瓣', '藤原龙也', '深作欣二', 8, 203552, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1071682909.jpg', 0.9, 3, 21, 45.8, 29.3, '-0.063585,0.215839,-0.502623,0.561918,-0.227975,-0.035175,0.325485,-0.233202,-0.199326,0.132144,0.399737,0.586627,-0.000552,0.261845,0.180564,-0.529531,-0.379374,-0.626478,-0.514128,-0.233809,-0.594095,-0.236495,-0.223848,-0.214468,-0.003609,-0.025880,0.987253,0.243449,-0.089353,0.196301,0.270399,0.269969,-0.253487,0.103463,-0.113542,-0.504796,0.107655,-0.018678,-0.531473,0.028496,-0.171864,-0.173032,-0.417825,-0.014791,0.130556,0.104258,1.042670,-0.382041,-0.048181,-0.140105,0.541878,-0.243508,-0.299650,0.234896,0.368630,0.023270,0.189020,0.296764,0.320154,0.318976,-0.201955,-0.029184,-1.026266,-0.250354,0.007234,0.013300,-0.309597,0.549297,0.184122,-0.071465,0.087700,-0.328954,0.066334,0.375120,0.504278,0.410268,-0.325910,-0.131395,-0.148124,0.048613,0.619926,-0.272149,-0.481308,-0.179822,-0.231494,-0.646867,0.138682,-0.611849,-0.386545,-0.227378,0.256837,0.135441,-0.292829,0.381144,-0.910434,0.099659,0.003960,-0.373797,0.173175,-0.432089,-0.470925,-0.699903,0.041916,0.059446,-0.131984,0.140666,0.197448,-0.275334,1.275292,-0.692811,0.032442,0.537570,0.200046,-0.521347,0.414809,0.190239,0.308961,-0.073426,-0.196255,0.164022,0.171863,0.629045,0.009892,0.311125,-0.253472,0.174273,-0.258493,0.568787', '27602116', '4181031', '24284209', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292445', '天涯沦落女', '剧情', '一天清晨某村庄的沟壕里出现了一具僵死的女尸。在警察的调查下，死者莫娜（桑德里娜•伯奈尔 Sandrine Bonnaire 饰）的流浪岁月由此被揭开。她身背大包四处露营，与落魄的流浪汉同居在一处房子里，一起抽烟睡觉。一个老妇人的女仆尤兰德满心羡慕莫娜和流浪汉的自在状态，不满男友保罗的简单粗暴。某夜保罗入室行窃打昏流浪汉，莫娜随即不辞而别。接下来她遇到了一对放牧的夫妇，他们给了她土地和住所，期望她能努力过上平静踏实的日子。莫娜不以为然重新上路，在路上搭便车结识了以研究树木为职业的兰迪尔，兰迪尔给予了莫娜短暂的帮助后两人便分道扬镳。此后莫娜又在途中结识了剪葡萄树枝的工人阿兹，无人知晓莫娜的流浪将把她引向何处……©豆瓣', '桑德里娜·博内尔', '阿涅斯·瓦尔达', 8.3, 6878, 'tt0089960', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2188708884.jpg', 0.3, 1, 14.3, 50.2, 34.2, '0.471025,-0.116236,-0.467206,0.185344,-0.079069,-0.403325,0.752841,0.106902,-0.323213,-0.080429,0.281309,0.592614,-0.077555,0.419161,0.247885,0.153489,-0.603939,-0.597361,-0.015318,-0.173238,-0.421333,-0.407456,-0.348942,-0.282990,-0.027804,-0.366537,0.252015,0.123443,0.183751,0.487878,0.059680,0.163377,-0.216564,0.440077,-0.345317,0.221729,0.188523,-0.068188,-0.079082,0.184807,-0.101540,-0.322213,-0.108298,-0.094725,0.086070,0.471680,0.808563,-0.047857,-0.045957,0.082247,0.244860,-0.049569,0.186953,0.233058,0.456503,-0.118519,0.112782,0.073148,-0.299931,-0.099010,0.213376,-0.090897,-0.316223,0.105397,-0.094700,0.155793,-0.780070,0.683913,0.027364,-0.019799,0.039580,-0.331522,0.236122,0.350207,0.216406,0.227729,0.043613,-0.107666,-0.271068,0.306799,0.380829,0.035986,-0.063212,0.245145,-0.248532,-0.257625,0.188437,0.045734,-0.424604,-0.432930,0.549863,-0.179118,-0.412194,0.041629,-0.657049,-0.073631,-0.526658,-0.007656,-0.112400,-0.192730,-0.364718,-0.587071,-0.012900,-0.271493,-0.321163,-0.068899,0.136349,-0.203762,0.422170,-0.675282,0.364483,0.615136,0.382403,-0.046293,0.549361,-0.311440,0.372791,0.023461,0.122133,0.315858,0.153340,0.457552,0.482184,0.550858,-0.220945,0.228894,-0.595598,0.353747', '21619567', '1578663', '1316560', '3155839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292450', '暗花', '剧情', '澳门两大黑帮洪兴帮和义英帮为争夺赌场利益火并数月后决定言和，不想这时江湖上传出洪兴帮老大崩牙华已出五百万高价聘请外来杀手，准备不日刺杀义英帮大哥高佬忠。为保证高佬忠的安全以免天下再次大乱，崩牙华派出手下得力干将也是腐败警察的阿琛（梁朝伟）去阻止事情发生。光头杀手耀东（ 刘青云）和神秘女子阿凤（邵美琪）常在阿琛左右出没，不断给他制造麻烦。原来，耀东是黑帮幕后老大洪先生派来的粉碎洪兴帮和义英帮的超级杀手，他的杀人手段十分精妙狠绝。经过一番安排，耀东制造出崩牙华与高佬忠均死于阿琛手中的局面，然而他的命运亦不掌控在自己手中。©豆瓣', '刘青云', '游达志', 8.4, 95948, 'tt0168043', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2159683290.jpg', 0.2, 1.1, 14.7, 47.8, 36.1, '-0.092143,0.019408,-0.414565,0.119372,0.058886,0.015063,0.207548,0.108181,-0.402037,-0.453385,0.215613,0.361738,0.281894,-0.175429,0.266986,-0.249585,-0.191574,-0.731071,-0.193147,-0.132502,-0.087404,-0.301793,-0.097979,-0.289451,-0.014152,-0.019171,0.258058,0.019360,-0.361801,0.278820,0.349584,0.448938,-0.358013,0.280091,-0.097713,-0.175626,0.027962,-0.171887,-0.617481,0.164115,-0.128911,-0.389660,-0.147291,0.199619,0.115083,0.369688,0.213128,-0.093797,-0.090681,-0.378139,0.085910,-0.412342,-0.090312,-0.322378,0.387329,0.071533,0.190209,0.460618,-0.261495,-0.104119,0.011859,-0.115553,-0.855061,-0.139187,0.321026,-0.097679,-0.568537,-0.010079,-0.149834,-0.044364,-0.036217,-0.112213,0.261720,0.271828,0.276674,-0.219276,0.114646,0.047029,-0.411371,0.012523,0.685177,-0.090658,0.343481,-0.217391,0.447935,-0.248930,-0.010708,-0.502175,-0.090561,0.068266,0.279077,-0.377428,0.148939,0.175397,-0.109742,-0.334663,-0.250423,0.126270,-0.117042,-0.141043,0.040854,-0.392519,-0.209757,-0.006597,-0.122246,0.140495,0.203671,-0.060807,0.506801,-0.567575,-0.018769,0.362069,0.334997,-0.527319,0.168753,0.055273,0.247215,-0.453406,-0.287210,-0.565267,0.516176,0.091716,0.177256,-0.084471,-0.077091,-0.337528,0.074171,-0.267666', '26678784', '1297862', '1877596', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292453', '疯狂的麦克斯2', '动作', '在未来，因为战争和资源的枯竭，建立在石油之上的工业社会陷入崩溃，人们为了汽油展开生死争夺，这是恐怖如地狱的末世景象。失去了朋友和亲人的麦克斯（梅尔·吉布森 Mel Gibson 饰）以车为家，继续和公路骑士们无休无止的战斗。然而因为他的V8失去燃料，麦克斯只得离开公路，在一个陷阱猎手的指引下，前往一处石油钻井寻找燃料。荒漠中的人们，为了保卫钻井，建立了防御设施对抗骑士休曼格斯一伙，麦克斯从骑士们手中救出了一位奄奄一息的钻井保卫者，结果反被钻井守卫者们扣留，而此时，休曼格斯率领手下将钻井团团包围，危急关头，麦克斯设计对抗休曼格斯……©豆瓣', '梅尔·吉布森', '乔治·米勒', 7.3, 18488, 'tt0082694', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192562008.jpg', 0.8, 4.4, 38.2, 42.9, 13.8, '0.236944,-0.188398,-0.597066,0.339082,0.022032,-0.198332,0.891848,0.032946,-0.256871,-0.235045,0.666443,0.573450,0.188170,-0.167974,0.216151,-0.255069,-0.531662,-0.663539,-0.299644,0.172802,-0.329258,-0.433554,-0.313218,-0.173000,-0.111763,-0.629909,1.071787,0.149197,-0.121563,0.260240,-0.122231,0.426612,-0.154830,0.213000,-0.015806,-0.229552,0.093822,-0.512725,-0.351558,0.350555,-0.558370,0.014339,-0.114497,0.012576,0.142187,0.268092,0.646526,-0.497149,0.413973,-0.436103,0.002998,-0.581630,0.180876,0.284118,0.232878,-0.011263,-0.104520,0.126889,-0.244369,0.049242,0.215491,-0.245568,-0.837318,-0.094801,-0.122676,0.032552,-0.666773,0.169378,0.002237,-0.153586,0.019115,-0.314867,0.291207,0.336167,0.206917,0.370221,-0.442733,-0.070127,-0.714111,-0.202818,0.775043,-0.289239,-0.205527,-0.092057,0.049115,-0.224508,-0.288916,-0.221727,-0.366096,-0.474486,0.308001,0.105510,0.035866,0.526271,-1.178602,0.131853,-0.273124,-0.597788,-0.046988,-0.154118,-0.399192,-0.850562,0.107554,0.066154,0.038579,0.255343,-0.080275,-0.098654,0.676952,-0.582426,0.166936,0.393745,0.399656,-0.419162,0.496493,-0.173302,0.383851,-0.252508,-0.070232,0.438847,0.146943,0.603779,0.169612,0.058842,-0.318613,0.192958,-0.332515,0.368089', '26290398', '1294917', '1578502', '25881615');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292454', '龙卷风', '动作', '龙卷风的暴戾和神秘吸引了大批科学家的深入研究，深入风暴中间是最危险的行为，但亦是探索龙卷风最有效的方法。乔（海伦·亨特 Helen Hunt饰）和离婚的丈夫比尔（比尔·帕克斯顿 Bill Paxton饰）就是这类“与龙共舞”的科学家，即使他们感情已经破裂，比尔也已找到新的恋人，但出于对龙卷风研究的痴迷，他们还是决定共同追逐一场俄克拉何马州的飓风，并把新研制成功的探测仪“多萝西”放到龙卷风中心收集数据。他们驾驶着破旧的货车，带领着追风队，向最危险的地方进发。同时，另一队装备精良的人马也朝着这个方向驶去，由裘纳（加利·艾尔维斯 Cary Elwes饰）领队，在追风行动中和乔激励较劲。一边是志同道合的乔，一边是畏惧惊险生活的新女友，比尔在追风过程中如何重新抉择自己的感情道路？更重要的是，面对实力雄厚的对手，和随时葬身其中的龙卷风，乔和比尔如何实现自己的追风梦想？', '海伦·亨特', '扬·德·邦特', 7.3, 29151, 'tt0117998', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2237849016.jpg', 0.4, 2.7, 39.8, 45.4, 11.6, '0.258019,-0.427546,-0.563271,0.816220,-0.065421,-0.092776,0.905228,-0.005966,-0.300421,-0.255842,0.262434,0.579934,0.229857,0.201349,0.108025,0.008773,-0.209904,-0.719765,-0.080215,-0.045642,-0.444063,-0.710517,-0.372522,-0.363717,0.316326,-0.152188,0.753008,0.227725,-0.316831,0.283894,0.332226,0.303168,-0.417146,0.678154,-0.268438,-0.165333,-0.071040,-0.038511,-0.487413,0.010098,0.006912,-0.091513,-0.130094,0.295263,-0.003506,0.369302,0.612304,-0.478784,0.142566,0.061238,0.109145,-0.504208,0.256281,0.124993,0.394714,-0.000998,-0.042452,-0.076453,-0.008910,0.145984,-0.242731,-0.146022,-0.958707,-0.126001,0.125948,0.130901,-0.674219,0.218760,0.016801,-0.143341,0.305742,-0.157985,0.074185,0.383255,0.295320,0.216415,-0.264791,0.020995,-0.311628,-0.163394,0.600918,0.158394,-0.316983,0.207284,-0.233838,-0.482201,-0.202772,0.032368,-0.260710,-0.442208,0.471573,0.400474,0.245272,0.173197,-0.847605,0.318636,-0.056022,-0.195817,-0.031266,-0.457402,-0.027799,-0.841695,0.088539,-0.731190,-0.176909,0.022545,-0.044372,-0.309278,0.646538,-0.655693,-0.019514,0.571203,0.177154,-0.479067,0.512487,-0.167601,0.114600,-0.346630,-0.039741,0.341376,-0.054724,0.307348,0.040577,0.373538,0.226199,-0.113316,-0.241936,0.549721', '25828589', '1294917', '25774050', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292465', '愤怒的葡萄', '剧情', '刚从监狱释放出来的Tom Joad （亨利·方达 Henry Fonda饰）回到俄克拉荷马的家的时候却发现原来的家里已经空无一人，打听之下才从农民Jim Casy（约翰·卡拉丁 John Carradine饰）口中得知，随着工业的发展，当地的农民们都被迫离开该地。Tom和Jim在Tom的叔父家里找到了Tom的家人，一家人决定到加利福尼亚去寻找新的工作。一家人把所有的行李都放在一辆卡车上便出发了。路上，Tom的祖母去世了。他们发现了一个地方，专门召集像他们这样的人在那里工作，他们在那里安顿了下来。然而Jim却意外死亡，Tom为了给他报仇也杀了人，只能匆匆逃亡。一家人只能离开，去寻找下一个安身的地方，无家可归的农民们到底路在何方.....本片改编自斯坦贝克的同名小说，获1941年奥斯卡最佳导演奖。©豆瓣', '亨利·方达', '约翰·福特', 8.5, 9690, 'tt0032551', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p797727996.jpg', 0.4, 0.7, 11.8, 48.1, 39, '0.502072,-0.128736,-0.697647,0.326076,-0.089673,-0.539361,0.595552,0.120674,-0.336472,-0.412157,0.122990,0.910466,0.185086,0.408038,0.200543,0.015358,-0.648075,-0.626639,-0.120223,-0.382700,-0.471712,-0.318948,-0.270589,-0.201688,-0.006944,0.119371,0.402025,0.217671,0.185346,0.569792,0.155646,0.138851,-0.223415,0.493210,-0.348402,0.281483,0.008004,0.127622,-0.220787,0.303753,-0.012848,-0.374093,-0.378099,0.051722,0.507726,0.370164,0.596267,-0.055193,0.018263,0.034309,0.156212,-0.046029,0.047387,0.072576,0.380732,-0.116749,0.213981,0.201137,-0.398340,0.205891,-0.150676,-0.004781,-0.654509,0.093948,0.026921,-0.003542,-0.902046,0.182401,0.174024,-0.038782,-0.063084,-0.829513,0.587932,0.489638,-0.097000,0.530647,-0.346989,0.037967,-0.693666,0.129500,0.735653,-0.260837,0.145477,0.119144,0.192487,-0.337892,0.086010,-0.045388,-0.450267,-0.220602,0.351270,0.331809,-0.315290,-0.225174,-0.639657,-0.206674,-0.148153,-0.586208,0.093550,-0.269300,-0.054908,-0.668458,0.175132,0.018489,-0.213878,0.332021,0.058133,-0.088770,0.671754,-0.448189,0.321017,0.513438,0.261535,-0.724437,0.654351,-0.274101,0.453427,-0.068289,0.012423,0.098234,0.243027,0.798192,0.263334,0.270139,-0.321698,-0.265994,-0.588900,0.494992', '26678509', '6538833', '1316560', '26682880');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292466', '往日情怀', '剧情', '本片以美国50年代美苏冷战时期为背景，围绕女主人公凯蒂·莫若斯凯（芭芭拉·史翠珊 Barbra Streisand饰）与男主人公哈贝尔·加德纳（罗伯特·雷德福 Robert Redford饰）讲述了一段由相识到相知相恋，却因彼此间个性和政治立场的差异而分手的爱情故事。凯蒂，性格倔强浓烈的左翼女生，在校担任青年政党联盟主席；而主张明哲保身的哈贝尔则是学校有名的运动和写作才子。两人顺理成章地走到一起，也不可避免地分道扬镳。许多年以后，哈贝尔在街头与凯蒂重逢，往日情怀，不禁涌上心头。由著名导演西德尼·波拉克执导的影片《往日情怀》，根据阿琴·劳伦茨的小说改编而成。导演波拉克十分擅长反映当今社会的政治问题和揭露一些社会现实，而这部具有浓厚政治意味的好莱坞爱情片，更成为当时具有知识分子味道的代表作。波拉克一生导演了19部影片，共获得46项奥斯卡提名。本片则荣获1974年第46届奥斯卡金像奖最佳原创歌曲、剧情类最佳配乐及最佳女主角提名等多项大奖与提名。', '芭芭拉·史翠珊', '西德尼·波拉克', 8.2, 5968, 'tt0070903', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1278821905.jpg', 0.3, 1.7, 17.8, 48.2, 32.1, '0.133549,-0.170597,-0.565260,0.829902,0.425056,-0.160522,0.538782,0.150609,-0.280097,-0.112761,-0.041473,0.987540,-0.527133,0.072430,0.705246,-0.361546,-0.376506,-0.647936,-0.165334,-0.070543,0.165922,-0.479718,-0.182365,-0.021213,-0.414450,-0.450653,1.054700,-0.069649,-0.348615,0.630506,0.538940,0.301098,-0.171730,-0.050376,0.275270,0.009296,0.261457,0.031788,-0.577542,0.282828,0.223423,-0.039025,-0.291771,-0.148947,0.024321,0.055926,0.558522,-0.106723,0.166362,0.151871,0.721172,-0.172948,-0.063481,-0.233553,0.251979,-0.014801,0.522556,0.554245,0.166088,0.105469,-0.111022,-0.267534,-0.586703,0.052340,0.258635,0.195732,-0.239987,0.317436,-0.168713,-0.176347,0.142991,-0.088308,-0.075681,0.151172,0.586720,0.235348,0.169104,0.036911,0.038071,0.426935,0.289541,0.117068,-0.539740,0.336354,-0.193353,-0.614299,-0.224416,-0.300391,-0.407543,0.069991,0.217726,-0.088606,0.242288,0.323214,-0.551238,-0.034277,0.115523,-0.121461,0.263348,-0.281182,0.250395,-0.915110,-0.351248,-0.386094,0.151150,-0.349558,0.333751,-0.321062,0.769296,-0.528076,0.034975,0.337117,-0.067729,-0.389491,0.711525,0.212192,0.181644,-0.401728,-0.162143,0.222615,-0.160795,-0.238483,-0.161131,0.435440,0.002482,-0.200625,-0.373624,0.336882', '1780122', '1322847', '22265121', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292467', '地下铁', '剧情', '海琳娜（伊莎贝尔•阿佳妮 Isabelle Adjani）的丈夫是法国的一个黑帮头目。一天，当他携带一个装着重要文件的文件箱走在大街上时，被法国混混弗莱德抢走了。弗莱德凭借法国庞大的地铁系统逃走了。弗莱德（克里斯多夫•兰伯特 Christopher Lambert）将抢来的重要文件藏在地铁上，此时他发现地铁里的世界原来也多姿多彩。在这里他结识了吉他手、轮滑小子、鼓手等人。警察和黑帮此时都在寻找弗莱德。弗莱德向海琳娜索要文件的赎金的过程中，海琳娜逐渐爱上了他，而越来越憎恨她的丈夫和她所在的阶层。弗莱德一直有个梦想，就是组建一支乐队。他在地铁上认识的伙伴们帮他实现了这个梦想。弗莱德利用抢劫得来的钱在地铁上举办了一个音乐会。但就在此时，黑帮和警察同时找上门了。©豆瓣', '伊莎贝尔·阿佳妮', '吕克·贝松', 7.8, 8208, 'tt0090095', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2315568768.jpg', 0.5, 3.1, 26.6, 45.7, 24.1, '0.553916,0.141332,-0.791349,0.414856,-0.212862,-0.428141,0.795403,0.040204,-0.396421,0.031704,0.312522,0.872148,0.157093,0.217335,0.160746,0.180396,-0.467755,-0.718870,0.010097,-0.265257,-0.431207,-0.462124,-0.366104,-0.229221,-0.172313,-0.251921,0.442086,-0.137391,-0.037425,0.518132,0.356887,0.059906,0.087488,0.533627,-0.281523,0.110704,0.472909,-0.037937,0.087470,0.370884,-0.130521,-0.229099,-0.119502,0.068225,0.145343,0.268047,0.593717,0.009765,0.280778,-0.003467,0.142706,-0.406536,-0.087363,-0.201211,0.374889,-0.124735,-0.064685,0.018861,-0.443562,-0.128254,0.076140,0.020268,-0.652046,-0.173933,-0.137163,0.239591,-0.714262,0.423101,-0.189586,-0.061041,0.107063,-0.373496,0.249482,0.288362,-0.138502,0.285820,-0.142866,-0.088283,-0.808537,0.327594,0.552659,-0.001141,0.052416,0.174301,-0.113503,-0.382608,-0.284449,-0.066897,-0.546361,-0.289402,0.592193,-0.327284,-0.305717,-0.053792,-0.707993,0.025135,-0.117499,-0.225663,-0.038904,-0.497985,-0.318564,-0.704888,-0.068607,-0.157599,-0.063542,0.075806,-0.023651,-0.154859,0.766547,-0.699898,0.193921,0.874905,0.272525,-0.319171,0.888083,-0.041521,0.100752,-0.169680,-0.110549,0.061353,0.336560,0.448542,0.149554,0.416379,-0.060035,0.008599,-0.398180,0.593177', '3055049', '3326747', '30162520', '1308842');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292468', '破浪', '剧情', '上世纪70年代的苏格兰，一个略带神经质的女子贝丝（艾米丽·沃森 Emily Watson 饰）不顾宗教束缚嫁给了石油工人亚恩（斯特兰·斯卡斯加德 Stellan Skarsgård 饰）。恩爱生活并不长久，亚恩在一次石油作业中身负重伤，沦为瘫痪。贝丝非常难受，甚至觉得是自己的欲望导致了这个悲剧。为了唤醒丈夫的生命力，贝丝挑逗不同的男人，和他们发生关系，让亚恩的病情可以被情欲的力量征服。丈夫的病情竟然有了好转，然而，村里的人都对贝丝投以唾弃的目光，贝丝亦被送进精神病院。为爱牺牲的信念在贝丝心中强烈燃烧，将再一次把她逼入绝境。©豆瓣', '艾米丽·沃森', '拉斯·冯·提尔', 8.1, 15979, 'tt0115751', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p762255833.jpg', 1, 2.8, 17.9, 45.1, 33.1, '0.170989,-0.033764,-0.721992,0.494552,-0.325319,-0.225451,1.048133,0.129081,-0.516867,-0.081637,0.069404,0.692076,-0.116384,0.262702,0.124584,0.151418,-0.121678,-0.810287,0.012988,0.083943,-0.274717,-0.498282,-0.103788,-0.363714,-0.086520,-0.660237,0.579393,0.122721,-0.393176,0.246205,0.121594,0.364009,0.257692,0.666118,-0.118484,-0.053689,0.063630,-0.306548,-0.140289,0.256614,0.250660,-0.249576,0.133910,0.437534,-0.152675,0.283994,0.686463,-0.122905,0.039970,-0.248755,0.388828,-0.242086,-0.024478,0.308690,-0.062437,-0.111786,-0.033355,0.190368,-0.250159,-0.164276,0.453372,0.105887,-0.867171,0.188480,0.069333,0.176574,-0.567236,0.597014,-0.041924,-0.024346,-0.123639,-0.193490,0.156898,0.029533,0.347097,0.689163,-0.382373,0.046418,-0.481679,-0.134449,0.727353,-0.192016,-0.213204,0.459782,-0.592570,-0.354634,-0.095365,-0.321778,-0.557774,-0.221725,0.227063,0.356968,-0.277089,0.656417,-0.535286,-0.074754,-0.233737,-0.172940,-0.158024,-0.489817,-0.041817,-0.307460,-0.336599,-0.372013,-0.276365,0.103235,0.272777,-0.341276,0.599063,-0.473733,0.348714,0.601761,0.599704,-0.610331,0.541613,0.298733,-0.019408,-0.035652,-0.071798,0.675500,-0.000619,-0.041319,0.229000,0.249236,-0.093046,0.273813,-0.349302,0.651706', '1307311', '25828589', '26245360', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292474', '乌鸦', '动作', '相传，乌鸦能带领人的灵魂穿越阴阳。于是，一个传奇故事就此展开。一个不详的夜晚，摇滚歌手埃里克（李国豪 饰）和他的未婚妻在街头遭到当地的恶棍杀害。整整一年后，凭借着乌鸦的指引，埃里克的灵魂从阴曹地府回到了人间，他又重新复活了！复活后的埃里克拥有着超自然的力量，而他的身边总是出没着一只黑乌鸦。埃里克开始了他的漫长的复仇之路！©豆瓣', '李国豪', '亚历克斯·普罗亚斯', 7.4, 9700, 'tt0109506', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1328970308.jpg', 1, 4.8, 36.4, 40.6, 17.1, '0.169720,0.181807,-0.708245,0.950285,-0.163753,-0.364536,0.861829,0.148605,-0.342341,-0.028177,0.225661,0.893541,0.014104,0.484920,0.392059,0.111508,-0.283750,-0.628822,-0.046770,-0.179503,-0.419009,-0.182262,-0.616397,-0.094553,0.049513,-0.513069,0.504224,0.236010,0.005663,0.428045,0.219194,0.239427,-0.139659,0.406876,-0.552869,0.185800,0.141595,0.041942,0.220210,0.334447,0.064542,-0.247312,0.063148,0.195159,-0.567463,0.161105,0.922437,-0.606774,0.030060,-0.536588,0.575881,-0.355058,-0.137419,-0.087588,0.408669,0.174490,0.145004,0.115651,-0.094670,0.078679,0.013848,0.067115,-0.872337,-0.082743,-0.339285,0.276350,-0.572229,0.302853,0.152309,0.062676,0.146344,-0.363442,0.130785,0.197312,0.171543,0.428969,-0.206776,-0.207138,-0.667767,0.164928,0.645453,-0.133297,-0.479648,0.458548,0.001050,-0.591925,-0.124003,-0.010515,-0.438318,-0.378838,0.753212,0.295209,-0.406438,0.219347,-1.057928,0.062660,-0.296544,0.079226,-0.222260,-0.297915,-0.259643,-0.458761,-0.103468,-0.197133,-0.126310,0.118944,0.098761,-0.246471,0.750551,-0.669245,0.504016,0.816453,0.255806,-0.241353,0.538529,-0.227603,0.301198,-0.044086,0.285786,0.378363,0.154683,0.950627,0.323755,0.371244,-0.155318,0.240807,-0.540844,0.970744', '1308784', '2357162', '24733428', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292484', '碟中谍', '动作', '中情局获得情报，得知他们的特工中出了一个叛徒，准备将中情局布置在东欧的特工名单出卖给外国特工组织。在特工头目吉姆（乔恩•沃伊特 Jon Voight 饰）的策划下，伊森（汤姆•克鲁斯 Tom Cruise 饰）所住的一组特工赶往了他们交易的地点。岂料，当他们按计划赶到 时，却中了埋伏，一组人中除了伊森和吉姆的妻子克莱尔，其他队员都被杀害。这时，伊森的账户无端端多出了12万美金。伊森成了内鬼的最大的嫌疑犯。无奈之下，伊森只能凭个人之力独闯龙潭虎穴去找出出卖他们的内奸。他和外国间谍组织的接头人麦克斯取得联系后，答应帮麦克斯偷出中情局的间谍名单以交换中情局内鬼的名字。©豆瓣', '汤姆·克鲁斯', '布莱恩·德·帕尔玛', 8.2, 243986, 'tt0117060', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1660124103.jpg', 0.1, 0.7, 16.3, 54.1, 28.8, '0.398431,-0.172345,-0.628076,0.540383,-0.460945,-0.165072,0.423083,-0.020163,-0.668011,-0.117741,0.385626,0.646035,0.169341,-0.090513,0.479104,-0.106282,-0.557043,-0.770184,-0.299945,-0.713074,-0.438073,-0.692006,-0.422705,-0.500497,0.124467,-0.005453,0.450519,-0.061825,-0.084728,0.210681,0.258779,0.348251,-0.332057,0.203819,0.012740,0.004143,0.560301,-0.636626,-0.288701,0.422835,-0.068525,-0.057160,0.032919,-0.082294,0.157429,0.714788,0.597811,-0.301271,0.250132,-0.233277,0.037291,-0.351636,-0.066756,-0.070220,0.303152,0.065034,-0.030708,0.142660,-0.287951,0.023237,0.090642,-0.013299,-0.948997,-0.092250,0.190191,0.180542,-0.497271,0.238245,-0.506876,0.299056,0.282154,-0.262082,0.295555,0.459208,0.323009,0.131843,0.236202,0.022778,-0.556897,-0.059164,0.411147,-0.062573,0.261775,-0.366294,0.001021,-0.544582,0.028503,-0.119163,0.157689,0.083727,0.695088,-0.220680,0.005135,-0.039287,-0.607892,-0.434529,-0.199195,-0.148713,-0.019183,-0.556509,-0.137158,-1.097004,-0.095707,0.268791,-0.036836,0.321325,0.108533,0.047471,0.542362,-0.756323,0.118495,0.752685,0.342279,-0.393569,0.384953,-0.110355,0.288488,-0.309025,-0.196752,0.019870,0.785420,0.761560,0.271435,0.249693,0.011825,-0.553592,-0.134783,-0.308117', '2028645', '1865012', '1307442', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292493', '王牌大贱谍', '喜剧', '20世纪60年代最杰出的特工奥斯汀（麦克·迈尔斯饰）是一次次打败“邪恶博士”（麦克·迈尔斯饰）拯救世界的超级英雄。邪恶博士把自己冷冻在外太空，以求来日再战。奥斯汀便也如法炮制，冷冻了自己。30年过去了，美国太空局发现不明飞行物正向地球飞来。邪恶博士回来了。美国特工局马上把斯汀解冻，把战胜邪恶的希望全寄托在他的身上。可是，30年的变化让这位特工措手不及。科技的发展，潮流的变化，奥斯汀的行为全都变成了笑料。美女助手凡妮莎·肯辛顿（伊丽莎白·赫莉饰）挺身而出，帮助奥斯汀完成任务，但怎知越帮越乱。迟到30年的决战变成了无厘头的演出，奥斯汀还能否像30年前打败邪恶博士，拯救地球呢？©豆瓣', '麦克·梅尔斯', '杰伊·罗奇', 6.2, 7533, 'tt0118655', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167466475.jpg', 5.1, 15.4, 49.9, 22.1, 7.4, '0.050621,0.180282,-0.172891,0.174254,-0.161407,-0.306490,0.122572,-0.295549,-0.224497,-0.077609,0.228358,0.341563,-0.013228,-0.076750,0.441875,0.313804,-0.355478,-0.604914,0.019752,-0.141837,-0.316024,-0.377913,-0.512159,-0.315965,0.259732,-0.549929,0.561118,0.107974,-0.049787,0.395527,0.057290,0.347852,0.027131,0.509144,0.014449,0.008038,0.292010,-0.208251,-0.314001,0.260603,-0.067394,-0.016200,0.009017,0.240626,-0.150689,0.066460,0.433909,-0.190920,0.123689,-0.272634,0.405367,-0.469743,-0.155297,-0.117726,0.344449,0.108210,-0.324028,0.155699,0.155321,-0.005618,0.071455,-0.117324,-0.704548,0.137163,-0.137477,-0.059346,-0.416819,0.136820,-0.196367,0.095359,0.148234,-0.198613,0.126348,0.121522,0.509360,0.474439,-0.116335,0.281329,-0.458085,0.280400,0.359049,-0.158725,-0.540628,0.062470,0.101330,-0.291152,-0.140352,-0.366450,-0.300126,0.175539,0.174542,-0.105453,-0.207365,0.555964,-0.737087,-0.100284,-0.541726,-0.114825,0.144799,-0.383656,-0.092391,-0.441596,-0.111557,0.253170,-0.271556,-0.106885,0.131076,-0.251037,0.876878,-0.582430,0.136269,0.786013,0.355443,-0.263628,0.563067,0.050668,-0.058912,-0.347267,-0.140586,0.338269,0.013722,0.586739,-0.030934,0.385053,0.062794,-0.330305,-0.116427,0.481385', '24284209', '27602116', '7155241', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292501', '鬼玩人', '恐怖', '五个年轻人艾什（布鲁斯•坎贝尔 Bruce Campbell 饰）、雪莉（Ellen Sandweiss 埃伦•桑德维斯饰）等相约一起自驾游，他们预订了一座坐落于深山里房子作为野外落脚点，他们翻山越岭终于找到了这间小木屋。晚上，他们发现了这间屋子主人留下来的一本封面吓人的古怪的书和一部老式录音机。屋子主人在录音留言里说他在研究远古流传的丧礼和一些咒语，而那本古怪的书名字就叫“死亡之书”；根据书上说人死了其实只是保持睡眠状态，并没有真正死去，通过咒语可以重新活过来。接着录音机里就播放了一段令人毛骨悚然的咒文。随后，恐怖的事情开始陆续发生。©豆瓣', '布鲁斯·坎贝尔', '山姆·雷米', 7.1, 13761, 'tt0083907', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2073163069.jpg', 2, 6.9, 38.4, 37.9, 14.8, '0.458135,-0.065294,-0.503724,0.511674,0.073503,0.009946,0.943210,-0.046993,-0.522648,-0.443467,0.057431,0.712568,-0.314708,0.272120,-0.160525,0.157735,-0.710450,-0.520004,0.251260,-0.439765,-0.486662,-0.289701,-0.245129,-0.308601,0.104556,-0.255763,0.108815,0.144095,-0.036477,0.323504,-0.269805,-0.048976,-0.290157,0.203740,-0.282112,-0.009363,-0.044843,0.093377,0.143051,0.033293,-0.039059,-0.093756,-0.272496,0.115621,0.344843,0.274444,0.547724,-0.222006,-0.251726,0.172012,0.068866,0.306761,-0.421532,0.095647,0.194074,0.264846,0.532710,0.223252,-0.460763,0.014872,-0.261396,-0.038214,-0.488442,0.107961,-0.221485,0.381431,-0.264696,0.373287,-0.263975,-0.018373,0.147961,-0.376244,0.414985,-0.110289,0.461262,0.564744,0.124822,-0.339049,-0.407754,0.041548,-0.043919,-0.436998,-0.301044,0.519263,0.109741,-0.356281,0.019480,0.419206,-0.265886,0.005869,0.273096,0.055838,-0.184771,-0.264129,-0.807853,0.111710,-0.114091,-0.307071,-0.249203,-0.315454,-0.328776,-0.712626,-0.148052,0.218362,0.051827,-0.000353,-0.084812,-0.095010,0.762314,-0.315501,0.377330,0.148407,0.107575,-0.244436,0.296133,-0.156919,0.188124,-0.048655,0.337969,-0.016970,0.034584,0.547325,0.355066,0.472843,0.246601,-0.137343,-0.642930,0.726653', '1394176', '1302133', '1467779', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292504', '柏林苍穹下', '剧情', '柏林由两位天使守护着，一个是对人世疾苦冷眼旁观的卡西尔，另一个是常常感怀于人类疾苦的丹密尔（布鲁诺•甘茨 Bruno Ganz  饰）。二人穿着宽大的天使袍，在城市各处游荡，倾听人们的祈祷，默默观察人们的内心世界。马戏团玛瑞安（苏韦戈•多马丁Solveig Dommartin 饰）的心事引来了丹密尔的同情，因为马戏团经营不善，面临倒闭，玛瑞安满心烦恼。这个马戏团的天使演员令丹密尔动了凡心，他决定化作凡人，追求一段美满感情。本片荣获1987年第40届戛纳国际电影节最佳导演奖。©豆瓣', '布鲁诺·冈茨', '维姆·文德斯', 8.6, 40436, 'tt0093191', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792520149.jpg', 0.5, 1.4, 11.6, 39.4, 47.1, '0.160783,-0.169124,-0.544047,0.351948,0.305783,-0.030383,0.639062,0.343799,-0.298431,-0.218753,0.325476,0.907530,-0.306443,0.323882,0.340640,-0.085993,-0.500381,-0.485874,-0.047421,-0.006152,0.140507,-0.157310,-0.398294,-0.290632,-0.381941,-0.423274,0.613700,0.179137,0.252592,0.427686,0.609150,0.475482,-0.131506,-0.003651,-0.182120,-0.128314,0.353876,0.057070,-0.289909,0.154349,-0.251578,-0.057040,-0.225939,0.173161,-0.208239,0.070864,0.847999,-0.343666,0.023382,-0.087649,0.655300,-0.540793,0.063133,-0.010972,0.164318,-0.234275,-0.237224,0.021297,-0.055707,0.283952,0.054617,-0.083914,-0.609054,-0.373776,0.127890,0.408933,-0.500394,0.485503,0.201500,-0.021839,0.067842,-0.115634,0.049483,0.025158,0.158277,0.373142,0.109854,-0.075449,-0.278368,0.481334,0.533136,0.174662,-0.347272,0.387594,-0.556576,-0.412190,-0.202601,-0.147391,-0.751799,-0.343474,0.115641,-0.158021,0.185177,0.350005,-0.660939,0.074157,-0.213172,-0.353136,0.130784,-0.250561,-0.188019,-0.612197,0.047417,-0.457032,-0.219693,-0.117858,0.161429,-0.129024,0.863493,-0.673101,0.363309,0.572114,0.067187,-0.466047,0.913824,0.154180,0.311405,-0.140959,-0.007183,0.446401,-0.342209,0.123177,-0.263371,0.071334,-0.120127,0.047190,-0.311302,0.229786', '3811356', '2338019', '1908036', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292506', '赌神2', '喜剧', '赌神高进（周润发 饰）自从血洗江湖后，无心恋战，遂携新妻温柔（张敏 饰）隐居法国，生活平静，以画为伴。 台湾黑帮掌门人仇笑痴（吴兴国 饰）野心勃勃，要与高进一较高下，激他重出江湖，借高进会友之际带人潜入屋中将其妻其仆全部杀死。 悲痛欲绝的高进一人回大陆散心。途中偶遇台湾黑帮头目（柯受良 饰）与他女儿（邱淑贞 饰），二人结为至交却不料头目遭人暗算身亡，进碰巧救下其年幼的儿子，展开逃亡。而此时游手好闲的大陆汉（梁家辉 饰）与妹妹（吴倩莲 饰）碰巧遇上逃亡的进，而大陆公安队长（徐锦江 饰）也尾随而至，一场猫捉老鼠的游戏即将展开，而幕后操纵的仇笑痴又有什么阴谋呢……©豆瓣', '周润发', '王晶', 8, 116394, 'tt0109683', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167117242.jpg', 0.3, 1.6, 22, 50.9, 25.3, '-0.128155,-0.070157,-0.519576,0.315683,0.128960,-0.106983,0.565261,0.245233,-0.347366,-0.109336,0.316919,0.661123,-0.025233,0.194901,0.370278,0.001651,-0.035198,-0.683534,0.158782,-0.290709,0.111065,0.032306,-0.346513,-0.059857,-0.111316,-0.083649,0.544624,0.161594,-0.177947,0.786666,0.487950,0.370141,-0.725752,0.377243,-0.098732,0.105959,-0.050190,0.352409,-0.423575,0.082696,-0.260084,-0.092023,-0.309649,-0.312946,-0.125464,0.215474,0.654828,-0.179598,0.153154,-0.450998,-0.006923,-0.292461,-0.101007,-0.021142,0.466814,-0.005556,0.274006,0.125931,-0.043291,-0.075648,0.043404,0.002911,-0.261425,0.220746,0.280613,0.066644,-0.320363,0.179122,-0.157715,0.216478,-0.095817,0.071514,0.157568,0.417037,0.381543,0.062786,0.126695,0.026846,-0.369449,0.326031,0.566338,-0.204571,0.252903,0.066412,0.491241,-0.170758,0.306847,-0.274458,-0.166762,-0.144213,0.226301,-0.284427,-0.083459,0.239206,-0.398120,-0.124922,-0.286051,0.509852,-0.026812,-0.098876,0.062035,-0.607887,-0.023826,-0.238749,0.007139,0.134416,0.277644,0.001202,0.317324,-0.543328,0.165974,0.141500,0.105909,-0.609700,0.392759,-0.052519,0.075577,-0.326685,0.001176,0.310705,0.356362,0.037750,0.055180,0.089651,-0.209640,-0.210877,-0.248512,-0.100674', '3621404', '26365262', '1303333', '35256235');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292515', '用心棒', '剧情', '外表落魄邋遢的浪人武士三十郎（三船敏郎 饰）来到一个小镇，清兵卫（河津清三郎 饰）和新田丑寅（山茶花究 饰）两家恶霸在那里为争夺地盘，招兵买马经常争斗，弄得民不聊生。三十郎决定从中设计，引诱双方雇佣自己，再加入不同方造成两边拼斗，由此坐收渔利，消灭对方。 但随着丑寅弟弟卯之助（仲代达矢 饰）的加入，情况又发生了不同，他手里握有短枪，占得优势，清兵卫的势力被打败，三十郎甚至也受伤不轻。但是决战在所难免，椿三十郎独对丑寅、亥之吉等众人，身处劣势的他如何能剿灭对方呢？©豆瓣', '三船敏郎', '黑泽明', 9, 45086, 'tt0055630', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2163659004.jpg', 0.2, 0.4, 5.8, 37.5, 56.1, '-0.099464,-0.025653,-0.358529,0.142341,-0.044500,-0.071905,0.287305,0.042751,-0.163558,-0.301816,0.218023,0.232563,-0.049914,0.026161,0.122023,-0.535752,0.282990,-0.700853,0.288058,0.055841,-0.148325,-0.290134,-0.244716,-0.220662,-0.352614,0.076833,0.712957,0.304595,-0.439971,0.238393,0.298726,0.354588,-0.059170,0.414931,-0.048096,-0.177930,-0.189925,-0.297915,0.135794,0.214911,-0.549230,-0.583443,-0.164815,0.029239,0.325901,0.709967,1.016549,-0.270994,-0.126569,0.054703,0.054747,0.160452,-0.096302,0.310855,0.580815,-0.209227,-0.094975,-0.117098,-0.031532,-0.173302,-0.088225,0.024770,-0.365066,0.029211,0.308386,0.090899,-0.472106,0.397628,-0.006810,-0.111992,-0.083919,0.094685,-0.022155,0.669797,0.420969,-0.069101,-0.114738,-0.328724,-0.886175,-0.084772,0.720143,-0.028020,-0.082871,-0.275445,0.004612,-0.505469,-0.351212,-0.622405,-0.088889,0.000835,0.258539,-0.145503,0.501331,0.087056,-0.525225,-0.011829,-0.148240,0.279524,0.023187,-0.129136,0.255452,-0.361638,-0.207285,-0.474698,-0.227149,0.449620,0.276681,-0.115350,0.441963,-0.529171,-0.237856,0.179067,0.557648,-0.518018,0.337912,0.257733,0.211933,-0.373134,-0.079401,0.048159,0.335045,-0.105832,0.379618,0.180069,-0.086408,-0.382565,-0.167613,-0.134244', '30299515', '26852888', '26418093', '35058077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292516', '碧血金沙', '剧情', '弗雷德（亨弗莱·鲍嘉 Humphrey Bogart 饰）和鲍勃（提姆·霍尔特 Tim Holt 饰）是两名穷困潦倒的流浪汉，一日，在酒吧中，他们从精明智慧的霍华德（沃尔特·休斯顿 Walter Huston 饰）口中听闻了有关金矿的消息，走投无路的两人打起了淘金的主意，他们谎称是猎人，驻扎在了山上。经历了种种苦难的挫折，幸运的三人找到了金矿。然而，随着金砂数量的增加，原本相互信任的三人之间出现了裂痕。在一次下山采购的过程中，名叫科迪（布鲁斯·班尼特 Bruce Bennett 饰）的年轻人发现了他们秘密，跟随而来的科迪表示想要从中分一杯羹，三人决定杀之而后快。就在这个节骨眼上，一群土匪开始向山上进发，他们想要的是这三个“猎人”狩猎得到的“兽皮”。在种种阴谋和贪婪本性的趋势下，本来有着美好前景的三人走向的破灭的结局。©豆瓣', '亨弗莱·鲍嘉', '约翰·休斯顿', 8.6, 8168, 'tt0040897', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1729769888.jpg', 0.3, 0.8, 9.6, 46.5, 42.9, '0.427121,-0.056792,-0.777638,0.486137,-0.052160,-0.151245,0.840204,0.009769,-0.606196,-0.027812,0.085082,0.798942,-0.200392,0.174700,0.294907,-0.149307,-0.271133,-0.648573,-0.104417,-0.462626,-0.259912,-0.636971,-0.441918,-0.260323,-0.067674,-0.390656,0.535247,0.343827,-0.094368,0.655981,0.452379,0.322538,-0.169502,0.426698,-0.337207,0.088239,0.282594,-0.103294,-0.210852,0.318447,-0.086093,-0.229098,-0.316503,0.140481,0.045624,0.453833,0.647371,-0.255223,-0.003390,0.068708,0.038467,-0.249628,-0.014352,0.218386,0.516550,-0.103138,0.136945,0.294763,-0.147191,0.057150,-0.021577,0.019591,-0.670007,-0.095673,0.130363,0.322091,-0.896966,0.361402,0.105702,-0.142707,0.067872,-0.404394,0.242194,0.402589,0.174809,0.238484,-0.009757,-0.213943,-0.680172,-0.135694,0.780678,-0.124147,-0.100862,0.154892,-0.047648,-0.311700,-0.240757,0.085117,-0.156658,-0.184691,0.742986,-0.031565,-0.205866,0.191029,-0.824631,0.065678,-0.212814,-0.281042,-0.070055,-0.220613,-0.318778,-0.701351,-0.170135,-0.372427,-0.399174,0.321786,0.011731,-0.134037,0.681565,-0.760307,0.114699,0.487376,0.172373,-0.404709,0.600010,-0.146206,0.189045,-0.199901,-0.007878,-0.032110,0.129261,0.230417,0.098020,0.400177,-0.070821,-0.269716,-0.476768,0.484815', '3111650', '3055049', '2032339', '1316560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292518', '挑战星期天', '剧情', '威利（杰米·福克斯 Jamie Foxx 饰）本是一位名不见经传的橄榄球运动员，在一次极为艰巨的比赛中，他临危受命上场征战。威利出色的表现吸引了球队老板克里斯蒂娜（卡梅隆·迪亚茨 Cameron Diaz 饰）的注意，她看出威利是一名可塑之才，而威利之后的表现也并没有让克里斯蒂娜失望。一夜成名让威利的自我开始膨胀，骄傲与自满逐渐占据了他的内心，作为球队的教练，经验丰富的托尼（阿尔·帕西诺 Al Pacino 饰）知道威利正处在一个非常危险的状态之下，然而对于托尼的忠告，威利置若罔闻。威利离开了旧日女友，和队员们的关系也越来越差，与此同时，他所效忠的球队也正在面临着前所未有的重大危机。©豆瓣', '阿尔·帕西诺', '奥利佛·斯通', 7.9, 5727, 'tt0146838', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2099039441.jpg', 0.4, 2.1, 24.7, 48.5, 24.3, '0.253724,-0.004152,-0.544518,0.643906,-0.109322,-0.414657,0.796760,0.239214,-0.688094,-0.354772,0.329474,0.802977,-0.245433,0.110462,0.353415,-0.284459,-0.178541,-0.673900,-0.211191,0.201129,-0.027867,-0.641572,-0.398240,-0.143071,-0.139213,-0.521037,0.835362,-0.023357,-0.234383,0.606318,0.264680,0.420309,0.600115,0.670714,0.088140,-0.060276,0.229766,-0.076644,-0.179748,0.228057,0.197432,-0.022879,-0.367623,0.434352,0.192301,0.421394,0.411247,-0.368886,-0.168363,-0.051609,0.408123,-0.099618,0.140379,0.173509,0.193586,-0.114893,0.034671,0.188690,-0.019128,0.343016,-0.119952,-0.078061,-0.971833,0.185287,0.164685,0.272781,-0.574370,0.566415,-0.121626,-0.104907,0.259380,-0.180138,0.026867,0.309269,0.167335,0.203162,-0.155865,0.075445,-0.328744,-0.170950,0.619538,0.049093,-0.498378,0.125814,-0.418710,-0.605207,-0.094985,-0.356373,-0.571975,-0.086848,0.215318,0.307038,0.177097,0.199568,-0.380185,0.196565,-0.236040,-0.345084,-0.392643,-0.573694,0.184399,-0.600426,-0.226965,-0.534045,-0.430726,0.041595,-0.188284,-0.281418,0.761733,-0.911741,0.039059,0.498357,-0.053548,-0.152646,0.513950,0.204285,0.113929,-0.364415,-0.410785,0.501084,-0.172108,-0.116789,-0.025298,0.462886,-0.037478,-0.340256,-0.088157,0.661156', '1793491', '35030151', '25932086', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292521', '码头风云', '剧情', '纽约港的码头上，以约翰尼为首的黑社会势力无情地压迫着码头工人们。曾经是拳击手的特里（马龙·白兰度 Marlon Brando 饰）来到码头为约翰尼工作。他的朋友乔伊因为向犯罪委员会揭发约翰尼等人的罪行，被其手下，也是特里的哥哥查理从楼顶上推下摔死。乔伊的妹妹伊迪（爱娃·玛丽·森特 Eva Marie Saint 饰）发誓要为哥哥复仇，与教区牧师巴里神父一起展开调查。知情人都不敢出面告发。特里也目睹了乔伊被害的经过，虽然同情伊迪的遭遇，想要帮她逃离黑社会的迫害，但他没有告发哥哥的罪行。在与伊迪的接触中，两人渐渐产生感情。当伊迪得知他是杀害哥哥的帮凶，她拒绝了他。之后哥哥也为了救特里而被约翰尼杀害。无数罪恶的事件让特里决心去揭发约翰尼的罪行。在码头上他被约翰尼的手下打成重伤，神父和伊迪赶来支持他，一直沉默的码头工人们也觉醒了，他们团结在一起，为了正义抗争。本片获第27届奥斯卡最佳影片、最佳导演、最佳故事剧本、最佳男主角等8项大奖。', '马龙·白兰度', '伊利亚·卡赞', 7.9, 13345, 'tt0047296', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1212684554.jpg', 0.3, 1.6, 23.8, 52.9, 21.4, '0.120278,-0.258838,-0.648017,0.565560,-0.202422,-0.402747,0.863343,0.157775,-0.504018,-0.048583,0.359659,0.825701,-0.046745,0.170175,0.334154,-0.084299,-0.505895,-0.872649,-0.231198,-0.060061,-0.190619,-0.658725,-0.052952,-0.226218,-0.195043,-0.246811,0.543410,-0.222803,-0.142917,0.406452,0.659011,0.397759,-0.014268,0.422437,-0.027296,0.193930,0.237373,-0.328425,-0.498566,0.313917,0.091881,-0.390316,-0.127249,0.241751,0.093900,0.328968,0.406418,-0.116332,0.136271,-0.171546,0.105387,-0.550637,0.332256,0.279750,0.322773,-0.134434,0.234330,0.460800,-0.051557,-0.139658,0.011772,0.043490,-0.780901,0.007800,0.190550,0.250557,-0.783613,0.351068,-0.204547,0.082946,0.088767,-0.082944,0.172931,0.381793,0.201432,0.161288,-0.207193,-0.018435,-0.400017,0.022709,0.633244,-0.131431,0.115060,-0.074110,-0.089240,-0.261709,0.113234,-0.224525,-0.440479,0.005819,0.372911,-0.063097,-0.124980,0.368786,-0.388517,-0.432827,-0.296528,-0.196419,-0.218815,-0.362169,0.135036,-0.685863,-0.199419,-0.198169,-0.173722,0.008550,0.028080,-0.383627,0.431848,-0.522034,0.246729,0.570999,0.418637,-0.521919,0.596992,0.230251,0.033599,-0.154276,-0.116844,0.239615,0.280932,0.373401,0.279571,0.173586,0.301645,-0.236471,-0.221624,0.324268', '1299799', '3119246', '34890458', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292523', '侏罗纪公园', '科幻', '哈蒙德（理查德•阿滕伯勒 Richard Attenborough  饰）立志要建立一个非同寻常的公园：恐龙将是这个公园的主角。他把众多科学家收归旗下，利用琥珀里面困住的远古蚊子体内的血液，提取出恐龙的基因信息，利用这些信息培育繁殖恐龙。结果如愿以偿，他把怒布拉岛建立成了一个恐龙公园，坚信可以从中赚取大钱。然而，科学家们则忧心忡忡。不幸的事情果然发生了。虽然公园有电脑系统管理，但却因为被员工破坏而造成了无法挽救的失控：所有的恐龙逃出了控制区，人们纷纷逃窜却逃不过恐龙的魔爪。恐龙自相残杀，人们亦死难无数，最后幸存者寥寥，只得四人逃出生天。怒布拉岛上空弥漫着恐怖的气息。©豆瓣', '山姆·尼尔', '史蒂文·斯皮尔伯格', 8.2, 301789, 'tt0107290', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2076443176.jpg', 0.2, 1, 16.8, 50.8, 31.2, '0.295240,0.058974,-0.537810,0.403885,0.079892,0.048664,0.865168,-0.112911,-0.363116,-0.003772,0.039031,0.435215,-0.199783,0.116376,-0.213035,-0.097764,-0.097048,-0.243985,-0.075342,-0.035128,-0.065880,-0.109654,-0.651380,-0.314562,-0.028227,-0.332408,0.754783,0.239391,-0.171591,0.321475,0.053855,0.461296,-0.204461,0.275975,-0.095245,0.049683,0.097128,-0.195472,0.233983,0.164647,-0.394399,-0.219584,0.142725,0.187163,-0.076743,0.248739,0.682891,-0.418381,-0.064145,-0.491485,0.485721,-0.421129,-0.036025,0.310964,0.451160,-0.051492,0.131301,-0.068169,-0.111871,-0.042260,0.226670,0.113292,-1.016924,-0.272110,0.125286,0.142172,-0.571822,0.057466,0.129504,-0.008835,-0.001687,-0.159027,0.231335,0.104007,0.059971,0.310436,-0.070594,0.077168,-0.782254,-0.069517,0.607876,-0.428478,-0.270842,0.011121,-0.268084,-0.663197,-0.059847,-0.295515,-0.058509,-0.118390,0.488059,0.215513,-0.299047,0.283402,-0.776152,-0.042673,-0.375281,-0.648176,-0.064868,-0.166595,-0.306819,-0.524365,-0.162437,0.122891,-0.120883,0.083851,0.125887,-0.184525,0.919626,-0.504894,0.049987,0.618347,0.137471,-0.595066,0.428264,-0.403881,0.251789,-0.027128,-0.020371,0.184140,0.291697,0.719377,0.228778,0.239062,0.018856,-0.382118,-0.378632,0.388534', '1308784', '3005387', '26667010', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292528', '猜火车', '剧情', '苏格兰爱丁堡，雷登（伊万·麦克格雷格 Ewan McGregor 饰）、土豆（艾文·布莱纳 Ewen Bremner 饰）和病仔（约翰尼·李·米勒 Jonny Lee Miller 饰）三个青年过着混沌糜烂的生活，他们吸毒、滥交、诈骗无所不作，而在如此肆无忌惮挥霍青春的过程中，毒品成为一切万恶之源。雷登对之亦爱亦恨，试图戒毒却最终重蹈覆辙。在一次纵情狂欢后，他们三个不知谁和少女爱丽森（Susan Vidler 饰）所生的婴儿死去。以此为开端，噩梦真正降临。土豆抢劫时锒铛入狱，雷登吸食毒品过量被送往医院抢救，后被强制戒毒。恐怖的幻觉和心底生气的恐惧迫使他不得不和毒品一刀两断。看似美好的新生活，但往日狐朋狗友贝格比（罗伯特·卡莱尔 Robert Carlyle 饰）等找上门来，再度给他带来无限的烦恼……本片根据欧文·威尔士（Irvine Welsh）的同名小说改编，', '伊万·麦克格雷格', '丹尼·博伊尔', 8.6, 390347, 'tt0117951', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p513567548.jpg', 0.4, 1.3, 13.1, 40.5, 44.7, '-0.055161,0.059775,-0.648074,0.385405,-0.116233,-0.380390,1.095949,0.133906,-0.502932,-0.230471,-0.049443,0.540979,-0.203060,0.288150,0.231469,-0.141630,-0.336869,-0.598025,-0.063674,0.103230,-0.149308,-0.257111,-0.345725,-0.173270,-0.117333,-0.316346,0.462824,0.077587,-0.112516,0.440172,0.255687,0.452565,-0.043597,0.294588,-0.088250,0.001532,0.126772,0.049776,-0.429026,0.149060,0.211921,-0.260283,-0.079236,0.188408,-0.155201,0.207437,0.731730,-0.190851,-0.072516,-0.411831,0.360206,-0.205710,-0.128056,0.184458,-0.047826,0.006004,0.166591,0.057531,-0.272723,0.024249,0.222792,0.036150,-0.730864,-0.028861,0.006801,0.085981,-0.329210,0.285485,-0.190471,0.087175,0.100793,-0.145146,-0.063179,0.163648,0.588831,0.424607,-0.170510,-0.183146,-0.479735,0.278607,0.595544,-0.109209,-0.277797,0.325721,-0.305700,-0.235861,0.216334,-0.190639,-0.570671,0.034541,0.357457,-0.013959,-0.056405,0.582993,-0.625992,-0.134088,-0.365720,-0.170199,-0.088315,-0.161922,-0.212708,-0.555011,-0.163987,-0.188520,-0.286229,-0.051476,0.227235,-0.135154,0.310871,-0.661906,0.462837,0.514796,0.070092,-0.534583,0.084628,0.176874,0.070931,-0.185288,-0.093439,0.523059,0.431307,0.169449,0.184692,0.218352,-0.041015,0.161751,-0.411995,0.508820', '21619567', '1428054', '1316693', '25909236');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292529', '机器管家', '剧情', '机器人安德鲁（罗宾·威廉斯 Robin Williams 饰）是尼尔家四代人的管家。原本尼尔一家只是当他一部机器来使用，但大家渐渐发现安德鲁不只是一个家务机器这么简单，他在日常还会和他们一起欢笑，懂得人类的习俗，体会人类的情感。安德鲁在尼尔家的女儿很小的时候就喜欢上她了，但由于他没有安装感觉模块，他任由她嫁给了一个错误的人。由于没有感觉，安德鲁可以在海边独自一人盖一栋房子生活。直到某天，他遇上了机械专家、科学狂人，为他安装上了感觉模块。至此，安德鲁才体会到什么是吃醋、什么是恋爱。经过一番努力，安德鲁终于完全融入了人类社会。最终，他和自己相爱的人得以长厢厮守，并在垂垂老矣时幸福死去……©豆瓣', '罗宾·威廉姆斯', '克里斯·哥伦布', 8.6, 97452, 'tt0182789', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2195410751.jpg', 0.2, 1.1, 12.6, 42.4, 43.6, '0.269297,0.091324,-0.661638,0.402579,-0.404223,-0.290024,0.918551,-0.026924,-0.676938,-0.337028,0.215603,0.811562,0.058449,0.161448,-0.041549,0.366738,-0.433100,-0.436901,0.213735,-0.014826,-0.472104,-0.590981,-0.187566,-0.459327,-0.148875,-0.181142,0.537055,-0.028645,-0.094525,0.104062,-0.094323,-0.008372,0.135294,0.697091,-0.237550,0.122381,0.158327,-0.134384,-0.052409,-0.140068,-0.205265,-0.005663,-0.130316,0.259724,-0.072698,0.211569,0.592342,-0.151391,-0.087662,-0.073328,0.112348,0.076973,-0.135032,0.075376,0.086476,-0.163709,0.091826,0.172861,0.031235,-0.153934,0.063571,0.047201,-0.783926,-0.153868,-0.250883,0.208357,-0.439949,0.577525,-0.225118,-0.172495,-0.113709,-0.488047,0.162837,0.302015,0.402130,0.425759,-0.393833,-0.143773,-0.588251,0.232129,0.830186,0.062731,-0.316850,0.801920,-0.393499,-0.587764,-0.354446,-0.297550,-0.474355,-0.182717,0.035793,0.249754,-0.648144,0.097333,-0.502781,0.029864,-0.138129,-0.179700,0.062496,-0.505808,0.066579,-0.575518,-0.187964,-0.587046,-0.495676,-0.085243,-0.188573,-0.556752,0.699533,-1.038619,0.268531,0.758016,0.308352,-0.277278,0.844657,0.075170,-0.123174,-0.143359,0.082814,0.250325,-0.192149,0.280226,0.377630,0.491653,0.129632,0.148492,-0.147198,0.712134', '1296370', '1308755', '3230462', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292531', '华尔街', '剧情', '美国华尔街股市大亨戈登·盖柯（迈克尔·道格拉斯 Michael Douglas 饰）在金融界叱咤风云，人人敬畏。在随时随地上演的金融大战中，他总能百战百胜。初出茅庐的纽约大学毕业生巴德·福克斯（查理·辛 Charlie Sheen 饰）野心勃勃，却空有满腔热血而投报无门。 一个偶然的机会，他接触到盖柯，用一个股市内幕情报帮其赚了笔大钱而受到重用，成为盖柯的合伙人之一。在对金钱、美女、上流社会的渴求下，巴德开始利用身边所有的人来刺探一切有利的商业情报，为自己获利。直到在一场收购他父亲所工作的蓝星航空公司的过程中，贪得无厌的盖柯出尔反尔想要解散并卖掉它，这让尚有良知的巴德幡然醒悟。他利用盖柯教会他的一切股市战术，狠狠地反击了大亨盖柯，帮助父亲拯救了蓝星航空。然而，因为违法操控股票内线交易，巴德不得不面临着冰冷的铁窗……©豆瓣', '查理·辛', '奥利佛·斯通', 8.2, 53667, 'tt0094291', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2215746342.jpg', 0.1, 0.7, 16.4, 55.2, 27.6, '-0.070721,0.251633,-0.726824,0.587626,-0.140872,-0.304317,0.432815,0.074297,-0.360944,-0.202789,0.281458,0.588081,0.106186,0.091517,0.222859,0.104312,-0.139968,-0.706767,0.054618,-0.085578,-0.109656,-0.498013,-0.532544,-0.390710,-0.310185,-0.080148,0.594642,0.328532,-0.321216,0.050884,0.217928,0.344210,0.215313,0.428519,-0.083970,-0.137474,0.146548,-0.098165,-0.560679,0.289628,0.020437,-0.303080,-0.189074,0.350458,0.136451,0.257988,0.328866,-0.372487,0.152518,-0.164170,0.464250,-0.413232,0.077920,-0.063382,0.267810,0.047089,0.054784,0.151780,-0.235008,0.020135,0.189333,-0.067155,-0.986943,-0.411527,-0.032554,0.207257,-0.644354,0.400550,-0.215949,0.357123,-0.254651,-0.118110,-0.103628,0.379062,0.199638,0.140305,-0.155966,0.145674,-0.503755,0.162633,0.411075,-0.092979,-0.238942,0.256321,-0.101309,-0.290225,0.057772,-0.377864,-0.318872,-0.278678,0.575046,-0.201858,-0.023498,0.474312,-0.526338,0.077098,-0.041790,-0.246371,0.040440,-0.335053,-0.040822,-0.686273,-0.261995,-0.209680,-0.140231,-0.022945,0.302698,-0.324380,0.671306,-0.656380,-0.050323,0.790697,0.283183,-0.376889,0.400913,-0.042229,0.151063,-0.125562,-0.410469,0.276413,0.303981,0.266584,0.058420,0.068638,0.092374,-0.169458,0.033010,0.506390', '1793491', '25928048', '30163500', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292532', '铁面无私', '剧情', '30年代的芝加哥充满了混乱，黑道横行官商勾结，其中，要数掌握着私酒市场命脉的黑帮老大卡彭（罗伯特·德尼罗 Robert De Niro 饰）的势力最为强大。即使在这样黑暗的环境中，联邦探员纳斯（凯文·科斯特纳 Kevin Costner 饰）也依然怀抱着惩奸除恶的理想， 可是很快，现实便教会了他，在这个世界里，谁才是老大。在老警探马龙（肖恩·康纳利 Sean Connery 饰）的帮助下，纳斯重拾了自信，他组织了一个专案小组，专门调查和打击卡彭的犯罪事业。在纳斯的努力下，小组的行动初显成效，可随之而来的，就是来自卡彭的威胁和迫害。组员被杀，马龙受伤，这一切的一切都不能使纳斯消沉，反而更加坚定了他除掉卡彭的决心，一场激烈的较量在正义和邪恶之间拉开了帷幕。©豆瓣', '凯文·科斯特纳', '布莱恩·德·帕尔玛', 7.7, 18855, 'tt0094226', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1153928911.jpg', 0.4, 2.3, 27.4, 50.3, 19.5, '0.169028,0.320234,-0.758212,0.704386,-0.093115,-0.116561,0.733271,0.267313,-0.234630,-0.195368,0.138112,0.480508,-0.001311,0.164644,0.319516,-0.166424,-0.304327,-0.798096,-0.340243,-0.045582,-0.297338,-0.509919,-0.530607,-0.290680,-0.045585,-0.263821,0.598276,0.448162,-0.555897,0.107277,0.398904,0.362675,-0.009535,0.560699,0.041572,-0.031681,0.290829,-0.207890,-0.394420,-0.046432,0.211730,-0.290533,-0.112098,0.452301,0.160233,0.301195,0.426666,-0.463337,-0.035302,0.192048,0.332547,-0.402113,-0.076555,-0.110098,0.477310,-0.233732,-0.110428,0.292277,-0.118377,-0.062116,0.107242,-0.209243,-1.117406,-0.206027,0.072676,0.074944,-0.637915,0.541377,-0.012825,0.118229,-0.034325,0.041711,0.279464,0.422076,0.301048,0.279334,0.008123,0.093392,-0.585947,0.064103,0.559700,0.015404,-0.366304,-0.027548,-0.332962,-0.576204,-0.470285,-0.344026,-0.471827,-0.252839,0.738983,-0.171658,-0.155222,0.427452,-0.576877,-0.021197,-0.167657,-0.164014,-0.103506,-0.475315,0.211247,-0.493757,-0.354167,-0.425641,-0.167501,0.165983,0.003708,-0.159047,0.761810,-0.818102,0.020226,0.612847,0.176728,-0.219803,0.438009,0.215253,0.143528,-0.250035,-0.253239,0.329343,0.354104,0.360757,0.503029,0.411043,-0.049455,-0.051058,-0.025538,0.698331', '1793491', '30163500', '25932086', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292533', '狂人皮埃罗', '剧情', '费迪南德（让-保罗·贝尔蒙多 Jean Paul Belmondo 饰）经受着一段糟糕的婚姻，又不幸被公司开除。他在一个无趣的聚会上遇见前女友玛丽安娜（安娜·卡里娜 Anna Karina 饰），重燃旧情。厌烦一切的他决定抛妻弃子同她一起逃离。他跟着玛丽安娜去了她的公寓 ，发现一具尸体，接着很快发现她正在被黑帮追杀。在相处期间，玛丽安娜给费迪南德取了个昵称：皮埃罗。他们开车奔向南方，一路上疯狂抢杀。当他们到了法国，两人关系开始紧张。皮埃罗不再读书、思考、写日记，玛丽安娜也厌倦了这种生活，坚持要回城里。他们在一个夜店里遇到黑帮，混乱中两人失散了。皮埃罗疯狂寻找玛丽安娜，两人最终重聚。玛丽安娜利用皮埃罗得到一箱钱，之后逃走去找自己真正的男友——之前她多次提到的哥哥。皮埃罗开枪打死玛丽安娜和她的男友，将自己的脸涂成蓝色，身上绑上炸药。最后一秒，他后悔了，试图摁灭导火索，但是失败了，炸药砰地一声爆炸了。本片获得1965年威尼斯电影节金狮奖提名。', '让-保罗·贝尔蒙多', '让-吕克·戈达尔', 8.4, 31161, 'tt0059592', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1283677964.jpg', 0.6, 2, 14.3, 42.7, 40.5, '0.471131,0.172892,-0.689639,0.227621,-0.000721,-0.422195,0.827115,-0.088849,-0.129065,-0.064053,0.228094,0.783561,-0.262069,0.231862,0.255428,0.288518,-0.566937,-0.830186,0.340922,-0.049063,-0.343379,-0.359951,-0.108088,-0.078087,-0.045850,-0.147883,0.318651,-0.175061,-0.038910,0.664725,0.264938,0.111273,0.105081,0.486636,-0.002564,0.342507,0.181923,-0.250289,-0.131246,0.304125,0.140612,-0.230026,-0.126448,0.197207,0.289135,0.255984,0.538447,-0.069866,0.083134,-0.110431,0.217119,-0.352243,-0.074009,0.166770,0.087906,0.000652,0.141092,-0.003134,-0.303906,-0.165012,0.153991,0.090443,-0.285145,0.264334,-0.256748,0.026279,-0.742042,0.329722,-0.197297,0.209169,0.145714,-0.431025,0.099424,0.298104,0.156327,0.088459,-0.182092,-0.023676,-0.429253,0.081991,0.845371,-0.302880,-0.026207,0.189213,0.130145,-0.016969,0.005019,-0.045666,-0.452515,-0.059472,0.721259,-0.090208,-0.247852,0.159804,-0.544468,-0.173142,-0.387459,-0.119884,-0.020316,-0.287356,-0.084149,-0.439251,-0.237300,-0.042352,-0.369574,-0.165611,-0.260701,-0.177574,0.330385,-0.445254,0.285043,0.652957,0.491075,-0.365612,0.320028,0.081443,0.062177,-0.020294,0.220668,0.249286,0.079523,0.355697,0.425846,0.302821,0.113508,0.183618,-0.348289,0.364545', '3111650', '1306454', '1303462', '1297347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292547', '卡里加里博士的小屋', '悬疑', '德国小镇，面目狰狞的卡里加里博士（沃纳·克劳斯 Werner Krauss饰）终于获准表演催眠术。大学生弗朗西斯（弗里德里希·费赫尔 Friedrich Feher饰）和艾伦（汉斯·海因里希 Hans Heinrich von Twardowski饰）也来观看。疯狂的卡里加里博士向众人展示他是如何催眠和控制他的搭档凯撒（康拉德·韦特 Conrad Veidt饰），并向众人宣布：凯撒可以回答大家提出的所有问题。好奇的艾伦问道：我能活多久？病态的凯撒回答：活到明天凌晨。弗朗西斯并不相信，可艾伦却是满脸惊恐。随之，艾伦真的被杀害了。弗朗西斯把消息告诉了好朋友珍妮（丽尔·达戈沃 Lil Dagover饰）和她的医生父亲。他们展开了多方追捕，可惊人的秘密却丝丝入扣，到底谁才是真正的凶手？本片是世界电影史上被谈论得最多的影片之一，是德国表现主义电影的里程碑之作。影片以其怪诞的表现主义风格，成为以后西方恐怖片为之效仿的鼻祖。1958年本片在比利时布鲁塞尔由26个国家117位电影史家评选为“世界电影12佳作”的第12名。', '维尔纳·克劳斯', '罗伯特·维内', 8.9, 24718, 'tt0010323', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191024349.jpg', 0.3, 0.5, 7.4, 37.3, 54.6, '-0.061919,-0.086600,-0.489699,0.548331,0.019786,-0.408366,0.506332,-0.171711,-0.342010,-0.194025,0.112022,0.770779,-0.182444,0.044235,0.387308,0.287012,-0.515284,-0.624520,0.015875,-0.308681,-0.143600,-0.501137,-0.141267,-0.172942,-0.031047,-0.223619,0.451182,-0.120565,-0.222998,0.158316,0.442563,0.368845,0.255969,0.230200,0.092325,-0.137768,0.187284,-0.341792,-0.301686,0.230106,0.088577,-0.070384,-0.409692,0.378820,-0.057459,0.083791,0.437631,-0.247111,0.016973,0.005854,0.379686,-0.336057,0.153371,0.133423,-0.017595,-0.111773,0.152969,0.345562,0.102592,0.007656,-0.163523,0.006853,-0.858129,0.130467,0.082985,0.310194,-0.404276,0.223341,-0.314559,-0.208638,-0.044317,-0.302537,0.190682,0.307592,0.339125,0.393075,-0.099652,-0.074499,-0.477018,0.119498,0.081714,0.239669,-0.329830,0.216679,-0.024916,-0.545347,-0.086951,-0.168252,-0.347858,0.218687,0.372968,-0.029759,0.035545,0.255466,-0.525416,-0.309489,-0.238395,-0.549533,-0.057570,-0.470645,0.042975,-0.668139,-0.082902,-0.167965,-0.307250,-0.309649,0.172899,-0.243964,0.806986,-0.615968,0.066555,0.576270,0.263090,-0.271599,0.474761,0.021343,-0.095169,-0.247505,-0.171052,0.137588,0.243197,0.271706,0.101486,0.403224,0.284607,-0.376303,-0.249220,0.466467', '27602116', '3318306', '25928048', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292550', '埃及艳后', '剧情', '52岁的凯撒（雷克斯•哈里森 Rex Harrison 饰）以罗马执行官的身份驾临埃及，为了解决王室姐弟争位的事端。皇姐克里奥佩特拉（伊丽莎白•泰勒 Elizabeth Taylor 饰）美艳绝伦，凭借自身的魅力和政治手腕，迅速让凯撒拜倒在她的石榴裙下，不但获得了对埃及的统治权，而且还以美貌征服了罗马。克氏与凯撒完婚后，为其产下一子，深得凯撒喜欢，被立为继承人。但此事引起了凯撒手下大将安东尼（理查德•伯顿 Richard Burton 饰）与屋大维（罗迪•麦克道尔 Roddy McDowall 饰）的不满。在凯撒遇刺驾崩之后，安东尼接掌了罗马的统治权，但他同样无法抵挡克氏的绝世美貌。当安东尼彻底沉溺于暴风雨般爱情的时候，身在罗马的屋大维已经吹响了夺权的号角……©豆瓣', '伊丽莎白·泰勒', '约瑟夫·L·曼凯维奇', 7.9, 47110, 'tt0056937', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2496023539.jpg', 0.3, 1.8, 25.2, 49.5, 23.3, '0.194321,0.477165,-0.735806,0.700137,-0.074738,-0.477447,0.471936,0.367880,-0.422903,-0.297342,0.295231,0.941316,-0.147551,-0.109402,0.388875,0.172175,-0.388288,-0.774053,0.038582,-0.027840,-0.155847,-0.377975,-0.276433,-0.309566,-0.148029,-0.499560,0.664859,-0.104336,-0.047002,0.561553,0.299746,0.404977,0.377025,0.228576,-0.115556,0.026363,0.120206,-0.237267,-0.332375,0.439146,-0.061364,-0.222209,-0.221273,0.441323,-0.071685,0.219727,0.285730,-0.694220,0.322942,-0.370664,0.259614,-0.201827,0.087382,0.408280,0.247991,-0.200610,-0.124818,0.403761,-0.202567,-0.087610,0.196114,-0.100519,-0.735663,0.079090,-0.174848,0.076118,-0.473066,0.374421,-0.418463,-0.230324,0.258884,-0.108290,-0.017475,0.507859,0.162693,0.303003,-0.221850,0.097127,-0.549568,-0.096069,0.438145,0.035894,-0.410662,-0.040736,-0.076802,-0.454942,-0.049986,-0.306621,-0.377387,-0.309036,0.508178,0.133270,0.420125,0.508459,-0.492082,-0.340705,-0.560980,-0.164776,0.202853,-0.344164,0.075888,-0.468907,-0.435155,-0.405096,-0.276136,-0.217495,0.432200,-0.000011,0.521904,-0.806826,0.181673,0.311807,0.271360,-0.495571,0.320411,0.094868,0.229633,0.051611,-0.323390,0.284697,0.160331,0.034268,0.057563,0.281513,-0.038526,-0.326248,-0.387491,0.419642', '1303034', '3148748', '1299556', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292552', '玩尽杀绝', '悬疑', '这是一局环环紧扣的阴谋游戏。小镇上的中学教师萨姆（马特•狄龙 Matt Dillon 饰）这天为学生作完性主题的犯罪演讲后，女学生凯莉就溜进了他的房间，面对青春迷人的凯莉（丹妮丝•理查兹 Denise Richards 饰），萨姆惊得目瞪口呆。这一幕被凯莉的母亲桑德拉（泰莉莎•拉塞尔 Theresa Russell 饰）撞见了，她此前曾和萨姆有过风流的一夜。醋意大发的桑德拉以学校捐助人的身份要求校长将萨姆解职，萨姆因此糊里糊涂丢掉了工作。屋漏偏逢连夜雨，小镇上的一名女学生苏茜（内芙•坎贝尔 Neve Campbell 饰）突然控告萨姆强奸了自己，桑德拉出资聘请了有名的大律师状告萨姆。身无分文的萨姆请不起律师，虽然有贪财的保险人博登在庭上帮他辩护，但面对对方的资深律师，法庭的形势对萨姆十分不利。然而此时，事态有了新的转折！©豆瓣', '凯文·贝肯', '约翰·麦克诺顿', 7, 14496, 'tt0120890', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1266487848.jpg', 1, 5.9, 43, 40.3, 9.7, '0.414796,0.026055,-0.517410,0.297047,-0.052774,-0.344312,0.596005,0.455635,-0.394537,-0.176484,0.407663,0.571943,-0.324963,0.262023,0.474641,0.199407,-0.463983,-0.571631,0.012215,-0.175084,-0.065863,-0.683665,-0.129786,-0.107797,-0.046052,-0.213338,0.209866,-0.256356,-0.040723,0.402114,0.426998,0.376634,0.267469,0.316331,0.044633,0.042568,0.358891,-0.028951,-0.186821,0.108370,0.124050,-0.128296,-0.318546,0.044556,0.086157,0.560225,0.495491,-0.096933,-0.120093,-0.123657,0.496782,-0.357073,0.056693,0.104969,0.412477,-0.124657,0.237991,0.108899,-0.198092,-0.205625,0.081397,-0.158288,-0.490462,0.227323,0.099812,0.117035,-0.471453,0.325372,-0.378337,0.078942,0.015573,-0.257046,-0.171042,0.089552,0.194254,0.331049,0.099105,-0.016084,-0.344909,0.222306,0.374508,0.163095,-0.213525,0.260848,-0.331781,-0.456938,0.110140,-0.188734,-0.552741,0.055887,0.373460,-0.163510,-0.084239,0.107867,-0.354528,-0.255244,-0.485370,-0.010749,-0.222863,-0.132929,-0.321560,-0.561037,-0.139873,-0.128527,-0.418913,-0.032422,0.116359,0.024730,0.547120,-0.746817,-0.065759,0.473648,0.150827,-0.317777,0.569191,0.160493,0.213317,0.040408,-0.301102,-0.127226,0.098670,0.397071,0.277406,0.523601,0.027286,-0.363474,-0.132056,0.376623', '1293145', '3326747', '2297262', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292553', '真实的谎言', '喜剧', '哈里（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）是美国FBI的高级特工，他正在奉命调查一起跨国核武器走私案件。出于安全考虑，哈里连结婚15年的妻子海伦（杰米•李•柯蒂斯 Jamie Lee Curtis 饰）都没有告诉他的真实身份。海伦是一名普通白领，平凡的生活已令她心生厌倦。一次，汽车商西蒙假扮FBI特工，溜到海伦家谎称自己被人追杀。紧张刺激的经历很快令海伦着迷。这一切都没有逃过真正的FBI特工哈里眼睛。哈里利用间谍侦查手段令到西蒙洋相百出，并化妆成法国人正欲调戏海伦时，被恐怖分子突然袭击，两人被挟持到一个热带小岛。哈里和海伦最终能否逃出生天，挫败恐怖分子阴谋？©豆瓣', '阿诺·施瓦辛格', '詹姆斯·卡梅隆', 8.2, 148583, 'tt0111503', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2408831888.jpg', 0.2, 0.9, 17, 50.4, 31.6, '0.391076,-0.171862,-0.718737,0.391458,-0.245046,-0.121048,0.663770,-0.207880,-0.562385,-0.526942,0.272937,0.476300,-0.258074,0.004703,0.220484,0.196470,-0.416848,-0.601888,-0.008261,-0.130810,-0.245762,-0.387654,-0.332464,-0.271605,-0.126906,-0.256073,0.350834,-0.076525,-0.210035,0.395322,0.247642,0.294820,-0.132751,0.365037,0.000463,-0.108621,0.568232,-0.231828,-0.250501,0.119074,-0.108643,-0.219369,-0.068561,0.342495,-0.045707,0.365968,0.445063,-0.144668,0.001076,-0.218377,0.052134,-0.299225,-0.006433,0.160286,0.389961,-0.273049,-0.188001,-0.147942,0.062065,0.069752,0.198626,0.254396,-0.831007,0.088639,0.099819,0.030635,-0.351501,0.044893,-0.386368,0.148683,0.193361,-0.197726,0.089768,0.208167,0.308188,0.185984,0.180215,0.338854,-0.514693,0.230616,0.858104,0.042066,-0.244039,-0.004578,-0.343547,-0.325240,0.209548,-0.361005,-0.322206,0.257253,0.358081,-0.011770,-0.373063,0.208458,-0.334616,-0.196507,-0.553566,-0.113132,-0.092718,-0.280141,0.017395,-0.649127,-0.132618,-0.514941,-0.304082,-0.129234,-0.199749,-0.244700,0.322390,-0.642486,0.177248,0.768394,0.241956,-0.553738,0.376999,0.179216,-0.113354,-0.181588,-0.074943,0.374959,0.251288,0.383203,0.181584,0.240681,0.185673,-0.059179,0.054693,0.021873', '1309116', '1307442', '35073886', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292555', '逃出亚卡拉', '剧情', '亚卡拉监狱位于美国旧金山海湾，是当时防卫密度最高的监狱，里面关押的都是十恶不赦的罪犯。这座监狱被称为是史上最难逃脱的监狱。弗兰克（克林特·伊斯特伍德 Clint Eastwood 饰）因为抢劫银行的罪名而被关进了亚卡拉监狱，在这里，他结识了擅长驯养老鼠的利姆图斯（弗兰克·罗茨 Frank Ronzio 饰）以及拥有卓越的艺术细胞的天才画家“医生”（罗伯茨·布洛瑟姆 Roberts Blossom 饰）。因为良好的表现和高超的智商，弗兰克被典狱长派往监狱的图书馆工作，在那里，他遇见了囚犯领袖英格理士（保罗·本杰明 Paul Benjamin 饰）。典狱长专治而粗暴的统治让囚犯们渐渐心生怨怼，在一系列过激事件发生后，弗兰克决定带领大家越狱。©豆瓣', '克林特·伊斯特伍德', '唐·希格尔', 8.1, 11936, 'tt0079116', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2474446034.jpg', 0.2, 0.9, 18.8, 54.2, 26, '0.478037,-0.123820,-0.601825,0.477069,-0.022855,-0.001496,0.755964,0.218985,-0.683819,-0.361654,0.351955,0.658877,-0.118435,0.161464,0.136760,0.169543,-0.493321,-0.545414,-0.302679,-0.317453,-0.452421,-0.613269,-0.217180,-0.335473,0.050108,-0.352312,0.408817,-0.007421,-0.194086,0.193418,0.235056,0.802897,0.104397,0.054858,-0.107938,-0.135398,0.603780,-0.423589,0.004736,0.127777,-0.167413,-0.066714,0.123837,0.230480,0.351824,0.266029,0.405792,-0.206296,-0.034388,-0.076518,0.277334,-0.469285,-0.093752,0.125231,0.387487,-0.317731,0.057801,0.467457,-0.102105,-0.023223,0.211821,-0.149772,-0.836131,-0.055354,0.134425,-0.039834,-0.476454,0.297081,-0.135683,0.116885,0.077311,-0.050414,0.173919,0.198816,0.150696,0.423010,0.146060,-0.009729,-0.636385,0.077512,0.409148,-0.420013,-0.328261,-0.043944,-0.296900,-0.696783,-0.031209,-0.517345,-0.319045,-0.165816,0.319624,-0.269822,-0.201489,0.356490,-0.406416,-0.209560,-0.464010,-0.176375,-0.073977,-0.104517,-0.226492,-0.727274,-0.093850,-0.364251,-0.344520,-0.147406,-0.162530,-0.043918,0.404762,-0.706367,0.353664,0.709554,0.025942,-0.379797,0.685885,-0.053001,0.140506,0.196880,-0.083991,0.341209,0.560589,0.468685,0.084661,0.380115,0.025602,-0.449273,-0.321309,0.432908', '1793491', '1307442', '24753477', '1299851');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292557', '远大前程', '剧情', '根据狄更斯的小说《远大前程》改编而成。费因是个贫苦的孤儿，在极其偶然的情况下，他进入神秘的Paradiso Perduto庄园——那是州上最富有的女人丁斯默尔（Anne Bancroft饰）的家，成为她和她的侄女艾丝黛拉的座上客。许多年过去了，费因（Ethan Hawke饰）每周都到庄园跳舞，他一往情深地爱慕着成年后的艾丝黛拉（Gwyneth Paltrow饰），可艾丝黛拉绝美的脸庞下却是一颗高傲而冷酷的心：她并不爱费因，却极尽其挑逗之能事，将可怜的小伙子玩弄于股掌之中，最后她就不告而别去了国外留学。受到沉重打击的费因终于看清自己和艾丝黛拉的距离，可就在他放弃之际，他又突然得到神秘人的赞助来到纽约，在这里他尽情施展自己的艺术才华，事业上就要闯出一片天，此时，性感尤物艾丝黛拉又在他面前出现了……©豆瓣', '伊桑·霍克', '阿方索·卡隆', 7.5, 17819, 'tt0119223', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p827531145.jpg', 0.5, 3.9, 32.8, 43.6, 19.2, '0.355043,0.279311,-0.931620,0.695845,-0.251097,-0.312014,1.003798,0.082153,-0.293196,0.103040,0.331904,0.702749,-0.206863,0.460725,0.283426,0.405300,-0.234776,-0.791341,-0.164284,-0.263161,-0.208507,-0.260010,-0.428247,0.173230,-0.054056,-0.231803,0.527724,0.201364,-0.269020,0.319946,0.238337,0.243061,0.128016,0.575484,-0.497961,0.089104,-0.221375,0.163253,0.147642,0.210411,0.050432,-0.598954,-0.278480,0.229677,-0.216386,0.168384,0.761394,-0.287241,-0.063381,-0.018596,0.480643,-0.091363,0.008745,0.228754,0.112783,-0.176832,0.317206,0.069770,-0.440644,0.005314,0.195139,-0.108017,-0.694738,0.011997,-0.024086,0.088817,-0.772819,0.534776,-0.067900,-0.150588,0.030724,-0.595823,0.095201,0.009159,-0.052333,0.453606,-0.317686,-0.001155,-0.523355,0.163394,0.457042,0.344925,-0.363060,0.141510,-0.201300,-0.503227,0.020241,-0.477792,-0.448324,-0.253046,0.308994,-0.039792,-0.030699,0.138395,-0.575716,0.122084,-0.277449,-0.203022,-0.048986,-0.456672,-0.265567,-0.497894,-0.257762,-0.506946,-0.565901,0.243054,0.136607,-0.343546,0.725182,-0.963437,0.265234,0.741521,0.282779,-0.372651,0.652215,-0.103395,-0.090835,0.066460,-0.359354,0.356002,0.070955,0.361180,0.035326,0.527343,-0.159867,0.001105,-0.432963,0.850664', '1292211', '24756472', '1783772', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292573', '007之黎明生机', '动作', '东西双方处于针锋相对的奇妙情势。KGB内部有些人为了自己的私利，搞出了一系列的阴谋，首先是科斯柯夫假向西方"投诚"，并道出KGB准备进行一项名为"特务飞龙"的计划，目的是消灭00组的特工，007怀疑其动机，伪装刺杀，并查出科斯柯夫与军火贩子一起用购买军火的货款走私毒品，007得到反政府武装的支持，终于炸毁了毒品，科斯柯夫的计划彻底破产。', '提摩西·道尔顿', '约翰·格兰', 7.2, 8970, 'tt0093428', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1727497215.jpg', 0.5, 3.8, 43.1, 39.4, 13.2, '0.322418,0.024464,-0.626251,0.363851,-0.071749,-0.133808,0.342306,-0.027317,-0.482034,-0.197264,0.236198,0.262877,0.200159,-0.544627,0.366561,0.105583,-0.730572,-0.657533,-0.205520,-0.101842,-0.117089,-0.848828,-0.319113,-0.477974,-0.001121,-0.349704,0.641171,0.292669,-0.447774,0.001994,0.182237,0.588468,-0.186779,0.148433,0.374940,-0.426605,0.243217,-0.523565,-0.629774,0.155745,-0.163173,-0.095880,-0.262968,0.228363,0.009897,0.655420,0.327128,-0.296595,-0.061452,-0.160408,0.202119,-0.535854,0.119521,0.001129,0.272484,0.072025,0.017140,0.353072,-0.335340,0.072165,0.289097,-0.052123,-1.208297,-0.193341,0.082738,0.061752,-0.150928,0.129104,-0.223189,0.416701,-0.213347,-0.420788,0.187893,0.725287,0.493605,0.126749,-0.113605,-0.169121,-0.712159,-0.178449,0.486977,-0.385296,-0.076338,-0.244423,-0.197642,-0.322382,-0.001287,-0.388396,0.423682,-0.087647,0.538779,0.041939,0.105845,0.429077,-0.831448,-0.042356,-0.468760,-0.217960,0.156848,-0.223800,0.234105,-0.961633,-0.379959,0.049326,-0.037184,0.162630,0.337295,-0.198712,0.234928,-0.694088,-0.136044,0.884550,0.348801,-0.797671,-0.170735,-0.023529,-0.094157,-0.473372,-0.436327,-0.252694,0.215755,0.275552,0.059496,0.212045,0.563507,-0.558655,0.280914,-0.055607', '1307442', '3428500', '1401535', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292574', '热情如火', '喜剧', '1930年代，动荡的芝加哥时常被强盗集团骚扰。乔（托尼•柯蒂斯）和杰利（杰克•莱蒙）本是乐团成员，两人因偶然目睹盗匪史巴克的手下在车库内射杀告密者而被穷追不舍。走投无路之下，他们男扮女装加入一女性乐团，并随该团来到迈阿密。该团中有位名叫秀珈（玛丽莲•梦露）的异常美丽性感女郎，乔晓得她一心想钓有钱人时，便化身石油王的公子企图得到她的芳心；另一面，杰利也对秀珈情有独钟，可是他却得到一位不知他是男儿身的富翁的不断纠缠，笑话迭生。不久，乔和杰利又遇史巴克一伙，只得再次逃亡，场面更加逗笑。©豆瓣', '玛丽莲·梦露', '比利·怀尔德', 8.9, 57878, 'tt0053291', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p860250155.jpg', 0.1, 0.5, 7.2, 37.1, 55, '0.174104,-0.124799,-0.631026,0.476993,0.094223,-0.298053,0.797992,-0.027372,-0.544039,-0.245578,0.111852,0.699112,-0.346579,0.409597,0.479861,-0.051264,-0.076961,-0.359910,-0.097185,-0.087341,0.055966,-0.248964,-0.248616,-0.359352,-0.023507,-0.130783,0.469781,0.111546,-0.329614,0.399296,0.530857,0.313817,-0.176977,0.640794,-0.108732,0.233935,0.211752,-0.078747,-0.061544,0.080725,-0.085491,-0.417877,-0.245231,0.057975,-0.021313,0.206490,0.506184,-0.383944,0.298614,-0.285842,0.173316,-0.290086,0.147912,-0.040475,0.536886,-0.328397,0.204646,-0.078674,-0.162176,-0.141302,0.199938,-0.102510,-0.360124,0.267919,0.092932,-0.026865,-0.479595,-0.028394,-0.110207,0.177892,0.041670,-0.100657,0.238006,0.284813,0.400158,0.067989,0.105276,-0.102816,-0.530114,0.175285,0.720171,0.172309,-0.206710,0.083903,-0.146728,-0.494172,0.034170,-0.214437,-0.348827,-0.136160,0.376521,-0.047944,-0.002564,0.123995,-0.342919,-0.112432,-0.345553,-0.097237,-0.131116,-0.312817,-0.184757,-0.550216,-0.055002,-0.135850,0.047354,0.215831,-0.007566,-0.046184,0.481001,-0.758680,-0.035695,0.371413,0.162759,-0.445682,0.397234,-0.044108,0.101171,-0.056859,-0.268446,0.323435,0.341374,0.098557,0.229962,0.324725,-0.212797,-0.234038,0.016334,0.151255', '1308755', '25721544', '25870679', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292577', '安娜·卡列尼娜', '剧情', '这是一部根据托尔斯泰的《安娜卡列尼娜》改编的小说。卡列宁(詹姆斯福克斯饰)和安娜(苏菲玛索饰)是十九世纪俄国上流社会的一对夫妻。安娜拥有非凡的美貌，万种风情。后来，安娜和风流倜傥的渥伦斯(西恩•宾饰)邂逅了。渥伦斯的炙热爱情点燃了安娜心中沉睡已久的激情，两人不顾一切的相爱了。卡列宁当然无法容忍安娜的这种行为，但是安娜为了这段爱情，选择了奋不顾身，不惜一切代价。于是，她的命运被彻底改写，走向了另外一个轨迹。©豆瓣', '苏菲·玛索', '伯纳德·罗斯', 7.5, 32080, 'tt0118623', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p452625577.jpg', 0.3, 3, 34.6, 46.6, 15.4, '0.547482,0.134621,-0.569958,0.715896,0.113607,-0.471447,0.858016,-0.017803,-0.305216,0.063005,0.574880,1.133343,-0.208664,0.051816,0.483261,0.525019,-0.730763,-0.862408,0.085599,-0.154885,-0.014853,-0.658450,-0.199544,0.178643,-0.038738,-0.204387,0.767856,-0.405875,-0.062922,0.706906,0.232219,0.515738,0.178753,0.075863,0.310521,0.353149,0.436249,-0.556068,-0.404087,0.126150,0.210275,0.068366,0.074702,0.417379,-0.178026,0.094932,0.543615,-0.748185,0.078890,-0.090059,0.622923,-0.365537,0.092023,0.272458,-0.201275,-0.000653,0.396486,0.250523,-0.327241,-0.147590,0.191193,0.041890,-1.039218,0.119445,0.047492,0.182402,-0.472885,0.578816,-0.255827,-0.269834,0.438885,-0.326440,-0.127788,0.452496,0.603637,0.318080,-0.389571,-0.248411,-0.525703,-0.029498,0.654913,0.110757,-0.521798,0.603667,-0.424803,0.010516,-0.275043,0.006962,-0.727360,0.034269,0.701678,0.237716,-0.072015,0.596639,-0.651452,-0.177747,-0.716747,0.057836,0.225816,-0.507736,-0.358107,-0.568091,-0.660276,-0.617567,-0.325197,-0.497527,0.137899,-0.231162,0.928695,-0.704439,0.040342,0.580931,0.313332,-0.117851,0.523374,0.316778,-0.037794,-0.170067,0.093458,0.770286,-0.155919,0.344219,0.251899,0.426192,0.198598,0.336021,-0.370982,0.819319', '27602116', '1303034', '30162520', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292584', '上海小姐', '剧情', '曾在西班牙杀过人的水手Michael O''Hara（奥逊·威尔斯 Orson Welles 饰）回到了纽约，一天夜里他在路上救了遭到打劫的美女Elsa（丽塔·海华斯 Rita Hayworth 饰），于是Elsa让她的丈夫，律师Arthur Bannister（埃弗雷特·斯隆 Everett Sloane 饰）找到Michael，让他来船上当水手。Bannister一家刚从上海回到纽约，正要坐船前往旧金山。在海上航行的时候，Michael和Elsa情愫暗生。而Michael也认识了Arthur的朋友George Grisby（Glenn Anders 饰）。George知道Michael曾经杀过人后，想让Michael再杀一个人，并承诺给他五千美元的佣金，而他想让Michael杀的人，就是George自己。原来George想制造自己已经死了的假象，然后从现在的生活和他的妻子身边逃走。两人的计划看起来天衣无缝，George却失手杀死了Arthur的管家，随后George也真的被杀。Michael被认为是两个死者的凶手，法庭上，为Michael辩论的却是他的情敌Arthur，到底谁才是杀死George的真正凶手？', '丽塔·海华斯', '奥逊·威尔斯', 8, 6830, 'tt0040525', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p900360009.jpg', 0.4, 1.8, 18.7, 54.7, 24.4, '0.074486,-0.133158,-0.666240,0.584861,-0.384682,-0.607146,0.856257,-0.099542,-0.515542,-0.061166,0.125478,1.086627,0.093208,0.225391,0.352455,0.237622,-0.305639,-0.775037,0.061389,-0.301726,-0.482691,-0.467674,-0.121320,-0.254227,0.299585,-0.170747,0.459418,0.222598,-0.112294,0.391528,0.389445,0.204883,0.056023,0.765186,-0.386959,-0.024057,-0.039785,-0.067342,-0.121471,0.309321,-0.092487,-0.480513,-0.137291,0.273506,-0.102111,0.583967,0.611047,-0.211868,-0.119204,-0.005334,0.009608,-0.508306,0.171812,0.057656,0.234242,-0.245612,0.165888,0.214370,-0.202087,-0.061377,0.068671,0.136743,-0.939212,0.154599,-0.066812,-0.178596,-0.911937,0.288881,-0.199404,0.106325,0.068259,-0.090257,0.448424,0.378585,0.102669,0.334762,-0.037435,-0.162397,-0.811302,0.138043,0.867226,-0.133255,0.295896,0.317380,0.093006,-0.481637,0.059842,-0.266362,-0.181818,0.117780,0.344231,-0.107220,-0.377948,-0.180933,-0.662367,-0.029972,-0.445471,-0.069057,-0.182773,-0.577573,-0.075314,-0.146704,0.000545,-0.107709,-0.378691,0.105622,0.063342,-0.202069,0.416663,-0.796990,0.243421,0.761657,0.509186,-0.766774,0.751081,0.267197,-