INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292585', '边缘日记', '剧情', '吉姆（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）是一所天主教学校的高中生，同时他也是纽约最棒的高中球队中的一员。他与球队另外三名球员整天厮混在一起，逃课，嗑药，偷窃，斗殴，他们的青春在纽约街头肆意挥霍。吉姆把自己的生活都记录在“篮球日记”里。随后，吉姆最好的朋友鲍比因白血病而死去，此事给吉姆极大的打击。因为纽琼的一个“惊喜”，吉姆开始接触迷幻药，不久他就沉溺于毒品中。与母亲的缺乏交流，学校教父简单粗暴的教育，球队教练的性骚扰，这一切都让吉姆在自暴自弃中越陷越深。每一次毒瘾发作，他们都会用尽手段搞来买毒品的钱，吉姆跌入堕落的深渊……本片根据作家兼音乐家吉姆·卡罗的自传体小说改编。©豆瓣', '莱昂纳多·迪卡普里奥', '斯科特·卡尔维特', 8.2, 41457, 'tt0112461', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p737108256.jpg', 0.1, 1, 17.1, 49.8, 31.9, '0.328734,-0.321379,-0.381819,0.570623,-0.264637,-0.470845,0.738200,0.003413,-0.392337,-0.121236,0.143145,0.808812,-0.023241,0.233009,0.148333,-0.164892,-0.385807,-0.794386,-0.032797,-0.095639,-0.232781,-0.480995,-0.235868,-0.329476,0.038051,-0.211640,0.545392,-0.104362,-0.293691,0.376105,0.264176,0.357430,0.175415,0.174707,-0.064641,0.208556,0.324481,-0.124022,-0.163859,0.176974,0.250297,-0.172141,-0.045827,0.158795,0.460243,0.260747,0.601081,-0.018136,0.131842,-0.138256,0.393107,-0.102284,-0.096176,0.137236,0.228902,-0.012265,0.328238,0.088609,-0.073567,0.209801,-0.108506,0.054109,-0.820093,-0.203306,-0.048833,0.163670,-0.471558,0.627356,0.051987,0.167100,0.077511,0.006352,0.101208,0.222276,0.286885,0.307478,-0.041158,-0.159751,-0.383292,0.418165,0.515838,-0.242414,-0.300575,0.178871,-0.536018,-0.387471,0.172582,-0.229249,-0.555488,-0.036353,0.314744,-0.183756,-0.258837,0.493945,-0.556411,0.216563,0.016484,-0.220006,-0.087663,-0.212327,-0.075956,-0.741454,-0.086212,-0.189744,-0.294719,-0.135367,0.049759,-0.114079,0.708358,-0.571867,0.222956,0.759911,0.166201,-0.232079,0.651281,0.067485,0.219202,-0.084986,-0.161995,0.465967,0.200165,0.328775,0.045601,0.526199,0.274611,0.083735,-0.298400,0.667751', '30162520', '25928048', '3811356', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292586', '再见，孩子们', '剧情', '二战末期，德国的反犹政策还在坚定不移地推行着。来自马赛的犹太孩子波奈特（拉法艾丽·弗托Raphael Fejtö 饰）因此家破人亡，被送到法国的学校念书。在这里，他一直小心翼翼的保守着他的秘密，但还是因为新生的关系常常遭到同学戏弄。其中就有法国有钱家庭出身的朱利安（加斯帕尔·马奈斯Gaspard Manesse 饰）。朱利安和波奈特成为了室友，在共同相处的日子里，朱利安发现，这个经常被欺负的男孩有着跟自己志趣相投的一面。两人的关系渐渐融洽，成了童年要好的伙伴。当朱利安从种种迹象猜测出波奈特的犹太人背景时，他没有疏远波奈特，而且还帮忙隐藏这个秘密。也许在孩子的心中，政治世界在真挚的友谊面前显得太过渺小。然而，大人的魔掌还是侵入了波奈特的人生，保护犹太孩子的神父和波奈特都被出卖了……©豆瓣', '加斯帕·曼尼斯', '路易·马勒', 8.6, 13882, 'tt0092593', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1095874762.jpg', 0.1, 0.6, 11.4, 47, 40.8, '0.578990,-0.085417,-0.605298,0.590315,-0.375938,-0.176331,0.751489,0.336021,-0.587173,-0.197549,-0.044986,0.848376,-0.206797,0.321440,0.162111,0.129767,-0.505074,-0.787143,0.113799,-0.036837,0.031521,-0.686628,-0.257826,-0.205386,-0.143701,-0.598864,0.605512,0.102422,-0.249570,0.303991,0.080370,0.359676,-0.077735,0.460014,-0.306843,0.068587,0.055717,-0.047341,-0.178479,0.133046,0.223671,-0.157555,-0.117559,0.164667,0.143857,0.550692,0.541311,-0.140628,0.032904,0.359727,0.393335,-0.268787,-0.004008,0.291750,0.512862,-0.148554,0.229516,0.230598,0.002202,-0.022299,0.262095,-0.049264,-0.484435,0.110168,0.239344,0.102047,-0.764861,0.656512,-0.027677,-0.190674,0.094563,-0.030673,0.178333,0.517888,-0.042840,0.596156,-0.247563,0.126076,-0.424804,-0.120554,0.588237,0.004405,-0.407135,0.093837,-0.343412,-0.438979,-0.058836,-0.283345,-0.353198,-0.098482,0.488450,-0.019165,-0.301146,0.635501,-1.001866,0.191459,-0.255697,-0.038566,-0.044679,-0.460340,-0.069905,-0.608785,-0.179648,-0.668208,-0.476911,0.155751,0.006491,-0.165203,0.812047,-0.940539,0.298098,0.705732,0.401036,-0.334124,0.722893,0.353104,0.115607,-0.182180,-0.089074,0.236903,-0.063296,-0.013973,0.298411,0.409354,0.008780,-0.018104,-0.015520,0.655690', '30162520', '1292219', '25777634', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292589', '纽伦堡的审判', '剧情', '讲述二战后在纽伦堡提审德国纳粹计划的法律关系者，三个被告提审的原因是给犹太人施行断种手术。担任主审判长的是美国人赫鲁特，他主张其中两个被告无罪；而德国司法部长亚林克竟对此事保持沉默，但检查官罗森上校却激烈的指责被告，因此三个人展开激烈的辩论。审讯继续进行下去。而美国的高级官员们希望能在审判中获提德国所犯罪行的良好证明，因此对审判施以极大的压力，但赫鲁特坚守法律的正义立场，给予了最公正的判决。在宣布判决结果时，只有亚林对赫鲁特审判长的态度表示赞赏。', '斯宾塞·屈塞', '斯坦利·克雷默', 9.1, 7524, 'tt0055031', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2462065580.jpg', 0.4, 0.4, 5.6, 30.1, 63.4, '0.154905,0.025992,-0.528633,0.704188,-0.093189,-0.013308,0.455732,0.359957,-0.574759,-0.193279,0.413442,0.538276,0.117526,-0.197020,0.249634,-0.244034,-0.392934,-0.817977,-0.043987,0.028954,-0.362730,-1.084098,0.317433,-0.487362,-0.335515,-0.315586,0.615016,0.082466,-0.477599,0.174375,0.433799,0.250287,0.277418,0.400498,0.066028,-0.486321,0.412766,-0.114315,-0.794889,0.387301,0.211390,-0.181476,-0.431558,0.488712,0.036900,0.620882,0.258161,-0.505056,-0.545209,-0.178910,0.529930,-0.839635,0.007823,0.616403,0.462689,0.308861,-0.020901,0.583315,-0.028026,0.090881,-0.073083,0.002688,-0.689035,-0.266252,-0.237984,0.412703,-0.338377,0.622546,-0.192288,0.140816,-0.102926,0.131040,-0.051087,0.490960,0.139364,0.382215,-0.184757,-0.046241,-0.338682,-0.172704,0.544423,-0.218878,-0.443585,0.077352,-0.356319,-0.597475,0.143911,-0.346895,-0.049223,-0.231481,-0.088952,0.032612,-0.030831,0.061003,-0.373324,-0.238727,-0.298873,-0.231691,-0.045806,-0.588180,0.229467,-0.767384,-0.126697,-0.212391,-0.441495,0.209543,0.236720,-0.260721,0.861512,-0.775751,0.181034,0.426111,0.405689,-0.822792,0.537918,0.959972,0.164130,-0.338654,-0.019975,0.028317,0.287448,0.133166,-0.058949,0.032776,0.284110,-0.317129,0.022180,0.099823', '1293182', '2027899', '1949812', '1293989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292590', '天崩地裂', '动作', '哈利·道尔顿博士（皮尔斯·布鲁斯南 Pierce Brosnan 饰）是美国地质勘探中心的一名火山学专家，这次他被派到但丁峰上的一个小城镇视察，而小城镇所在的但丁峰正是华盛顿附近的一座休眠火山。哈利来到镇上，恰逢市长蕾切尔（琳达·汉密尔顿 Linda Hamilton 饰）在主持庆祝活动，因为小镇刚刚获得了全美最佳居住环境第二名的大奖。蕾切尔与她的两个孩子带哈利四处参观，路过温泉湖畔，哈利注意到湖水酸度过高，并发现了两具煮熟的浮尸。哈利顿感情况不妙，火山极有可能喷发，并建议蕾切尔发布预警，然而与哈利同行的上司保罗却认为他是反应过度，并打算在一周的勘探任务完成后打道回府，镇委会也出于种种利益目的，拒绝发布预警。然而就在一天夜里，镇上的水突然被硫磺污染，而这正是火山喷发的前兆，蕾切尔立即启动了全民撤离计划，然而她的母亲却在山腰上拒绝撤离。就在此时，火山已不可遏止地喷发了……', '皮尔斯·布鲁斯南', '罗杰·唐纳森', 6.9, 9652, 'tt0118928', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p686557342.jpg', 0.7, 4.9, 51.3, 34.6, 8.4, '0.434030,0.045852,-0.888389,0.368625,0.109247,-0.181522,0.718460,0.260743,-0.399790,-0.128270,0.286355,0.776450,-0.351940,0.133073,0.235090,0.112884,-0.284394,-0.366039,0.021673,-0.419541,-0.108157,-0.433767,-0.035567,-0.021935,0.119986,-0.384568,0.459966,0.066810,-0.187182,0.475700,0.067259,0.185722,0.023855,0.903107,0.109050,-0.261410,0.273083,-0.261173,-0.006344,0.437026,-0.010257,-0.247148,-0.172554,0.229927,0.419236,0.716255,0.543443,-0.255533,-0.167535,0.069484,0.128494,-0.520693,0.261707,0.064542,0.524842,-0.469107,0.080911,0.167540,-0.090684,0.181810,-0.013701,-0.353174,-0.210354,0.208835,-0.160165,0.266516,-0.549518,0.162202,0.070621,-0.217296,-0.093625,-0.374298,0.166093,0.407884,-0.094384,0.371954,-0.358272,-0.087033,-0.454093,-0.093481,0.483038,-0.307789,-0.304198,0.342217,-0.185935,-0.518813,0.154507,0.243607,-0.138894,-0.164074,0.374500,0.210989,-0.126552,-0.039442,-0.586820,0.023785,-0.630131,-0.572053,-0.224467,-0.191279,-0.224354,-0.995447,-0.016050,0.217656,-0.227552,-0.123475,0.004445,-0.191669,0.107759,-0.649277,0.253629,0.587748,0.228489,-0.389636,0.296537,-0.132429,0.010197,-0.305749,-0.030855,0.367119,0.056096,0.529462,-0.202398,0.349330,0.126012,-0.337744,-0.337072,0.354877', '3735015', '3011051', '2159244', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292597', '兰闺惊变', '剧情', '宝贝·珍妮·汉德森（贝蒂·戴维斯 Bette Davis 饰）曾是风靡一时的童星，整个汉德森家都依靠她的收入过活，这使她的性格变得日益扭曲和跋扈。比起珍妮，作为姐姐的布兰奇·汉德森（琼·克劳馥 Joan Crawford 饰）不过是一只不足挂齿的丑小鸭，不仅妹妹对自己视若无睹，就连父亲对她都大呼小叫态度恶劣，忍气吞声的布兰奇在心中埋下了仇恨的种子。成年后的姐妹两地位发生了逆转，珍妮的愚蠢和怪癖让她逐渐过气，而颇有姿色的布兰奇倒是在演艺圈获得了空前的成功，尽管布兰奇处处提携珍妮，但珍妮无法平衡内心的落差，总是想方设法和姐姐作对。一场突如其来的车祸使得布兰奇永远失去了双腿，珍妮也因此变得疯疯癫癫，布兰奇想把珍妮送进医院，珍妮却想消抹布兰奇的存在，彻底的取代她的位置。最亲近的两个女人在一处隐秘的别墅里开始了相互折磨的生活，而在这生活之下，似乎还隐藏着什么不可告人的秘密。', '贝蒂·戴维斯', '罗伯特·奥尔德里奇', 8.2, 8487, 'tt0056687', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1956457506.jpg', 0.5, 1.2, 15.8, 53.9, 28.6, '0.350064,-0.062421,-0.729603,0.653511,-0.215395,-0.366342,0.824777,0.296981,-0.620636,-0.112809,0.132628,0.654844,-0.345082,0.206436,0.127434,0.116808,-0.162792,-0.691227,-0.083580,-0.019335,-0.027395,-0.562013,-0.394500,-0.339798,-0.240969,-0.660846,0.431978,-0.047388,-0.306496,0.236141,0.170250,0.263214,0.117917,0.465327,-0.176436,0.108722,-0.031152,0.225859,-0.035215,-0.003744,0.111760,-0.125420,-0.094245,0.263218,0.143210,0.357186,0.496098,-0.279664,-0.278749,-0.071133,0.230547,-0.169805,-0.220285,0.287376,0.118266,-0.214734,0.216529,0.009991,-0.371145,0.061983,0.309155,0.033698,-0.791310,0.145575,0.205017,0.068338,-0.620073,0.519201,-0.113368,-0.239848,0.185535,-0.426296,0.202583,0.291722,0.081381,0.335678,-0.282643,-0.087921,-0.549955,-0.130519,0.714877,0.003051,-0.223315,0.422330,-0.536376,-0.291054,-0.222674,-0.295166,-0.539838,-0.218505,0.172337,-0.040872,-0.067988,0.489012,-0.579009,-0.100356,-0.288737,-0.180365,-0.181822,-0.538922,0.100762,-0.173305,-0.423287,-0.595187,-0.272266,0.043548,0.043436,-0.464420,0.752807,-0.901163,0.351623,0.473680,0.170144,-0.528134,0.273757,0.248302,0.148298,-0.063737,-0.360551,0.227431,-0.041267,0.029735,0.094807,0.426656,0.008769,-0.019419,-0.315183,0.596727', '130