INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292599', '异形魔怪', '喜剧', '在一个名为“完美”的宁静小镇上，米奇（凯文·贝肯 Kevin Bacon 饰）和死党巴斯特（弗莱德·沃德 Fred Ward 饰）又度过了属于他们的平静一天。对于在这个无趣的小镇里从事着一份又一份没有前途，仅能糊口的工作这一事实，两个血气方刚的年轻人感到十分无奈和困扰。终于，他们决定要走出完美镇，开始他们多姿多彩的新生活，而就在此时，通向镇外的唯一一条公路莫名塌陷了，某些不详的征兆开始显现。早在数星期之前，镇上发生了家畜神秘失踪的恐怖事件，同时，地质系学生蕾贝卡（ 芬妮·卡特 Finn Carter 饰）发现小镇的地壳运动十分异常。现在，众人终于将这些纷乱的线索拼凑到了一起，在大家的脚下，黑不见光的地底，究竟是什么在蠢蠢欲动？©豆瓣', '凯文·贝肯', '罗恩·安德伍德', 7.2, 11337, 'tt0100814', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2504182152.jpg', 0.9, 4.4, 40.6, 42, 12.2, '0.489269,-0.048378,-0.812793,0.463259,0.071408,-0.303240,0.935963,0.140607,-0.717710,-0.227742,0.123481,0.657891,-0.344044,0.281559,0.262428,-0.052114,-0.601040,-0.509077,-0.023319,-0.517255,-0.350771,-0.467533,-0.368753,-0.119082,-0.257299,-0.164204,0.534750,0.346885,0.077512,0.414390,0.172724,0.361013,-0.158486,0.469514,-0.364992,-0.031611,0.136565,-0.229944,-0.036289,0.015387,0.047859,-0.125558,-0.230286,0.330226,0.151110,0.428534,0.843173,-0.263306,-0.447106,0.217400,0.261164,-0.128364,-0.157911,0.039430,0.159541,-0.091309,0.173016,0.081073,-0.361743,-0.233157,-0.034647,-0.165539,-0.517305,0.198561,-0.001710,0.660491,-0.560830,0.448398,0.024489,-0.340005,0.090812,-0.665942,0.247627,0.580011,0.135914,0.435959,-0.107888,0.040584,-0.386979,-0.108790,0.800407,0.048451,-0.381556,0.421496,-0.338434,-0.276062,-0.092582,0.114960,-0.354423,-0.193669,0.328020,0.222962,-0.083651,0.303092,-0.886589,0.292460,-0.199915,-0.426171,-0.264673,-0.305596,-0.382023,-0.429269,-0.108738,-0.208654,-0.315982,0.322234,-0.131041,-0.084378,0.526887,-0.912530,0.367929,0.256461,0.122762,-0.122010,0.401846,-0.121800,0.154033,-0.320822,-0.029681,0.181446,0.016818,0.533628,0.051833,0.517660,-0.074853,-0.160514,-0.582733,0.693400', '21619567', '1467779', '2032339', '1807495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292600', '中途岛之战', '剧情', '七十年代出品的大型战争片之一，焦点是美国与日本海军对垒的中途岛战役。在当年的一批同类电影之中，本片不算是突出之作，导演杰克．斯米特的处理手法相对比较平庸，但超级明星阵容却可以令今天的观众重睹上一代巨星风采，而海战的场面也实在拍得逼真，使本片仍维持了相当的趣味性。主演的巨星包括：查尔顿．赫斯登、亨利．方达、格伦．福特、罗伯特．米彻姆、克里夫．罗布森、詹姆斯．科伯恩、三船敏郎。当时还是新人的汤姆．塞莱克也露脸演了一个小角色。', '查尔顿·赫斯顿', '杰克·斯迈特', 7.6, 7182, 'tt0074899', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2123614985.jpg', 0.4, 2.3, 31.1, 49.9, 16.3, '0.329900,-0.150203,-0.414529,0.703748,0.197438,-0.468948,0.584468,0.105650,-0.471066,-0.249623,0.454002,0.916769,-0.533500,-0.199284,0.344360,-0.253117,-0.307170,-0.396333,-0.218278,-0.029313,0.095064,-0.393847,-0.675394,-0.210984,-0.348231,-0.225877,0.738013,-0.109874,-0.243355,0.174003,0.425875,0.103621,0.441670,0.108374,0.079132,-0.089046,0.004551,-0.261856,-0.293283,0.282387,-0.007437,-0.147789,-0.140563,0.159249,0.237382,0.368050,0.394740,-0.258583,0.330955,0.187174,0.289602,-0.393037,-0.043333,-0.241604,0.205007,-0.346495,0.204684,-0.018860,0.133827,0.041538,-0.047488,-0.017230,-0.795741,0.189566,0.219318,0.241322,-0.202450,0.445074,-0.175226,0.011093,-0.218761,-0.073783,-0.013302,-0.001674,0.461756,0.141832,0.134740,0.173893,-0.290445,0.331972,0.454354,0.140617,-0.355729,0.180314,-0.427165,-0.817624,-0.173092,-0.833799,-0.499688,0.210922,0.277402,-0.487398,0.455734,0.432901,-0.570525,0.039338,-0.315345,-0.321866,-0.284859,-0.168538,0.264372,-0.921009,0.030635,-0.517140,-0.095786,-0.229770,0.279265,-0.229712,0.826577,-0.415502,-0.216782,0.437682,-0.118210,0.286083,0.584590,0.077625,0.098398,0.037740,-0.373140,0.255793,0.061035,-0.193726,-0.033832,0.621977,0.015340,-0.644655,-0.081634,0.528217', '1293433', '3318306', '3072064', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292601', '败家仔', '喜剧', '梁赞（元彪 饰）是梁家九代单传的独子，自小热爱习武。为了发展儿子的爱好，梁赞的父亲从江湖上重金聘请了各路名师与梁赞过招。然而，这些老师们早就被梁赞的父亲收买，在比武之时他们假装战败，使得梁赞自认为功夫天下无敌。某日，梁赞遇见了梁二娣，在比试的过程中，梁赞输得一败涂地， 才知道自己的真实水平，遂拜梁二娣为师，习得了短桥泳春，之后又受梁二娣师兄的真传，领悟了长桥泳春。一番勤学苦练之后，梁赞的武功果然大大提高，他返回了佛山，开设医馆施药济贫，某日，王爷的义子倪飞拜访想要同梁赞过招，王爷害怕义子受伤，竟然率先派出了刺客暗杀梁赞。©豆瓣', '元彪', '洪金宝', 7.7, 7610, 'tt0085211', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2002431401.jpg', 0.3, 1.9, 29.3, 48.7, 19.8, '0.090017,-0.058622,-0.493037,0.507330,-0.286797,-0.534929,-0.104464,0.075504,-0.593827,-0.404169,0.472560,0.865001,0.066920,0.207610,0.144437,-0.280153,0.169958,-0.625819,-0.138776,-0.365184,-0.056323,-0.406707,0.122404,0.087234,-0.241206,-0.359709,0.151571,0.134604,-0.376264,0.385044,0.098699,0.129872,0.147958,0.200700,-0.170343,0.061141,0.152377,0.080189,-0.254891,0.232222,-0.036316,-0.361923,-0.208679,-0.134288,-0.076837,0.358470,0.383696,0.003931,-0.004883,-0.410993,0.158215,-0.071307,0.101937,0.100467,0.487641,0.236990,0.274145,0.259297,0.177307,-0.201066,-0.247121,-0.030926,-0.590615,0.062094,0.396592,-0.374332,-0.670566,0.401357,-0.168008,-0.359244,-0.427770,-0.405006,0.241005,0.566795,0.173700,-0.049620,-0.222484,-0.117579,-0.279534,0.326918,0.621882,-0.215875,0.138792,0.184558,0.375987,-0.458119,0.543787,-0.643148,-0.099522,0.112921,0.397553,-0.099795,0.010853,0.172703,-0.118636,-0.108946,-0.308764,0.149208,-0.145411,-0.104309,0.142189,-0.428122,-0.145983,-0.310222,-0.265391,-0.287063,0.236587,-0.335221,0.723903,-0.953920,0.355215,0.218070,0.117730,-0.600044,0.508151,-0.031058,0.044693,-0.005317,-0.216031,-0.077944,0.260579,0.440385,0.067287,0.412860,0.021664,-0.309116,-0.256340,0.184717', '1877596', '1419416', '22964524', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292619', '圆月映花都', '剧情', '和导演埃里克·侯麦往常的影片一样，该片讲述了一个女孩徘徊在多个男人之间企图寻找自我的故事，通过人物之间的大量对话细腻而又真实的展现了男人和女人之间充满了变数的感情世界，虽为喜剧，亦展现了情感的无奈和多变，发人深思。路易斯（帕斯卡·欧吉尔 Pascale Ogier 饰）天性活泼善变，从艺术院校毕业之后，她同对她忠心耿耿的男友订了婚。然而，平静的感情生活让喜欢追求刺激的路易斯感到十分空虚，拥有着姣好面容的她深信自己在异性之中的魅力不减，因此，她义无反顾的决定结束和未婚夫的同居生活，返回巴黎。在那里，珍娜先后邂逅了数个不同的男人，在一连串的矛盾和波折面前，她终于领悟到了什么才是生命中最珍贵的东西。©豆瓣', '帕斯卡·欧吉尔', '埃里克·侯麦', 7.9, 6613, 'tt0087821', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233674197.jpg', 0.3, 1.5, 23, 53.4, 21.8, '0.416993,0.027796,-0.774457,0.925786,-0.125714,-0.233260,1.028190,0.118966,-0.465919,-0.068425,0.099096,0.752603,-0.374134,0.193076,0.367983,-0.230175,-0.263094,-0.769519,-0.178377,-0.117700,-0.131366,-0.559249,-0.298194,0.001350,-0.088561,-0.434901,0.791041,0.030301,-0.316708,0.456694,0.447345,0.075364,-0.177599,0.599386,-0.200250,-0.127086,0.062782,0.391228,-0.277289,0.097935,0.183577,-0.326221,-0.066907,0.305643,-0.330339,0.333071,0.766462,-0.319080,-0.247455,0.145588,0.528645,0.032606,-0.114857,0.147995,0.029244,0.090736,0.253808,0.198173,-0.211206,-0.034093,0.011979,-0.053278,-0.776585,-0.109014,0.246259,0.206385,-0.539664,0.603422,0.143103,-0.186178,0.226521,-0.293275,0.240460,0.200033,0.352788,0.527725,-0.200549,-0.045659,-0.307429,0.064878,0.589195,0.151402,-0.368758,0.612296,-0.515573,-0.465801,-0.140921,-0.242969,-0.610392,-0.096622,0.037331,0.179852,-0.204424,0.424910,-0.784950,0.033428,0.006449,0.024410,-0.021334,-0.738638,-0.086347,-0.497072,-0.513042,-0.780074,-0.319229,0.035753,0.031733,-0.337739,0.937046,-1.050484,0.222272,0.532432,0.301059,-0.486241,0.719328,0.238737,0.000832,-0.480212,-0.012144,0.466490,-0.169357,-0.139121,-0.059188,0.545402,-0.252585,0.091741,-0.578652,0.828756', '24756472', '2053515', '1301272', '4817024');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292624', '尖峰时刻', '喜剧', '韩大使（Tzi Ma 饰）驻派美国之前曾主持破获了中涛犯罪集团的走私活动，他因此受到仇家愤恨。在美国，中涛指示手下绑架了韩大使的女儿素洋（Julia Hsu 饰），并勒索赎金5千万美元。FBI闻讯展开全面调查，韩大使担心美方办事效率，执意要求调派香港的老搭档李督察（成龙 饰）前来协助。为了阻挠李抢先破案，FBI派出洛杉矶警察局状况不断的问题警探卡特（克里斯•塔克Chris Tucker 饰）作为李的搭档。卡特作风张扬高调，李则身手不凡、低调谨慎，这对临时组合的东西搭档闹出不少误会和笑话。但随着一次次危机发生，两人渐渐培养出默契。他们的营救行动最终能否成功？本片荣获1999年拉丁媒体艺术奖最佳女主角奖（Elizabeth Peña）、1999年MTV电影奖最佳银幕秀。©豆瓣', '成龙', '布莱特·拉特纳', 7.3, 99677, 'tt0120812', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2514033487.jpg', 0.4, 2.9, 40.6, 42.8, 13.3, '-0.223804,0.053581,-0.578776,0.416858,0.180112,-0.223903,0.173385,0.068650,-0.474320,-0.487881,0.024105,0.132061,-0.252733,-0.208928,0.465397,-0.545007,-0.429721,-0.655788,0.029991,0.038561,0.125119,-0.471161,-0.152354,-0.479724,-0.120905,-0.159130,0.217312,0.019456,-0.174764,0.492655,0.670111,0.501560,-0.223639,0.281973,0.390101,-0.138520,0.491790,-0.071861,-0.640790,0.170996,0.018670,-0.544407,-0.189915,-0.039797,0.584206,0.500330,0.456204,-0.011447,-0.252516,-0.098620,0.246887,-0.395489,0.190718,0.035249,0.542009,0.126753,0.148811,0.134486,-0.028015,-0.199520,-0.045197,-0.420325,-0.599272,0.265374,0.230313,0.093127,-0.346340,-0.177497,-0.238737,0.400173,-0.218242,-0.092482,0.142047,0.567579,0.524200,-0.204763,0.092067,0.407493,-0.227070,0.449118,0.562947,0.082159,-0.087957,-0.309581,-0.236252,-0.530182,0.032943,-0.331385,-0.102158,0.320795,0.568895,-0.349357,0.334622,0.028904,-0.151634,-0.393733,-0.190386,-0.043955,-0.084512,-0.219867,0.513292,-1.009884,0.031280,-0.220533,-0.020549,-0.146633,-0.060400,-0.099891,0.335827,-0.385278,-0.027154,0.540093,0.272579,-0.876430,0.292710,0.200767,-0.049777,-0.384293,-0.169689,-0.170715,0.265687,0.077990,0.193001,0.069780,0.210068,-0.515965,0.224061,-0.196951', '1309028', '3003137', '1293572', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292625', '绿野仙踪', '歌舞', '小女孩桃乐丝·盖尔（Judy Garland 饰）随叔叔、婶婶住在堪萨斯州中部的农场。某天，龙卷风袭来，为找到心爱的小狗，桃乐丝没能及时躲藏。强大的龙卷风将桃乐丝藏身的小木屋卷入空中。不知经过多久，小木屋终于落到地面，而且把一个邪恶的女巫也给压死了。在善良的北方女巫的指点下，桃乐丝和小狗启程前往魔法师奥兹（Frank Morgan 饰）所居住的翡翠城，祈求他能帮助自己回家。路上，桃乐丝遇见了没有脑子的稻草人（Ray Bolger 饰）、缺少心脏的铁皮人（Jack Haley 饰）以及胆小如鼠的狮子（Bert Lahr 饰），为了实现各自的愿望，他们随桃乐丝一同前行。一路上经历千难万险，更有邪恶的西方女巫处处阻挠，他们的愿望最终能否实现呢？本片根据美国同名童话改编。©豆瓣', '朱迪·加兰', '维克多·弗莱明', 8.2, 45935, 'tt0032138', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2192059845.jpg', 0.3, 1.2, 18.1, 49.7, 30.7, '0.210650,0.009594,-0.543232,0.477165,-0.027373,-0.132704,0.639899,0.066313,-0.121704,-0.188860,0.281068,0.606298,0.091229,0.029938,0.149861,0.151502,-0.239348,-0.404389,-0.042078,-0.073865,-0.426397,-0.309108,-0.310721,-0.116248,0.143248,-0.367564,0.610584,0.223578,0.107472,0.299171,0.116444,0.224041,-0.326707,0.185958,-0.530629,0.053714,-0.046110,0.144289,-0.159752,0.343736,-0.199966,-0.014039,0.035233,0.063004,-0.088504,0.155139,0.619264,-0.443794,0.069766,-0.135660,0.228318,-0.251373,0.333261,0.157319,0.232532,-0.155698,0.157337,-0.021435,-0.148506,0.073415,0.256881,-0.289916,-0.562144,0.028931,0.173635,-0.002368,-0.799591,0.048974,0.157581,-0.036580,0.281205,-0.385764,0.141641,0.344451,0.162553,0.234597,-0.246808,0.095398,-0.510763,0.086882,0.618308,-0.234926,-0.258779,0.026667,-0.157177,-0.264214,0.155983,-0.091683,-0.294141,-0.134340,0.486462,0.216161,-0.315154,-0.064737,-0.688832,-0.117217,-0.317847,-0.100937,0.164993,-0.504199,-0.254188,-0.548709,0.067659,-0.084271,0.109278,-0.013515,0.047985,-0.143218,0.611134,-0.680857,0.339036,0.696419,0.434025,-0.183257,0.715624,-0.200634,0.018900,-0.043983,0.080829,0.281360,0.128428,0.430201,0.129300,0.284077,-0.003174,-0.089353,-0.537811,0.365189', '3055049', '21619567', '1294917', '3755531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292626', '过关斩将', '动作', '该片延续了施瓦辛格一贯的英雄风格。在2019年，美国已经成为了一个独裁国家，在这里，不容许有不同的声音出现。本（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）是一名警察，因对当局的命令不满，拒不执行命令而被判有罪遭到逮捕。现在只有一个机会能让本重获自由，那就是参加电视台的“过关斩将”节目并最终获胜。这个节目肆意歪曲事实，误导观众，节目里的有识之士被扭曲形象，遭到杀害。本千辛万苦从电视台逃出来后，联合了一班正义之士，准备杀回电视台拆穿这个节目的骗局！©豆瓣', '阿诺·施瓦辛格', '保罗·迈克尔·格拉泽', 6.8, 5479, 'tt0093894', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1965546522.jpg', 1.2, 7.8, 50.1, 31.9, 9.1, '-0.074098,0.306437,-0.494192,0.592698,-0.126703,0.170259,0.276955,0.280814,-0.418319,-0.098870,0.102388,0.826217,-0.311977,0.123278,0.366079,-0.291722,-0.443369,-0.719755,-0.244403,-0.300881,-0.058790,-0.344928,0.059049,-0.348606,-0.023102,-0.228131,0.782983,0.185895,-0.521829,0.515334,0.723642,0.103832,0.290905,0.351396,-0.042504,-0.305195,0.322717,-0.193570,-0.112455,0.463580,-0.270670,-0.312105,-0.127665,0.166973,-0.228637,0.485209,0.414813,-0.159535,-0.098725,-0.268059,0.555998,-0.411190,-0.157051,0.321704,0.354927,-0.129159,0.089651,0.340699,-0.034711,0.213314,-0.027047,-0.272244,-1.009826,-0.037298,-0.203849,0.161396,-0.222164,0.423203,-0.002795,0.096713,-0.116370,-0.067099,0.248799,0.406563,0.419036,0.152161,-0.098520,0.227448,-0.597823,0.160635,0.835935,-0.076851,-0.331929,0.099298,-0.016521,-0.443185,0.141346,-0.412150,-0.193044,-0.001002,0.157990,-0.239099,-0.112781,-0.005314,-0.657381,-0.159114,-0.165628,-0.205102,-0.135982,-0.495819,-0.127317,-0.633975,-0.236428,0.169513,-0.105063,0.185370,-0.090405,-0.211572,0.865028,-0.875331,0.178732,0.466739,0.404705,-0.859944,0.700576,0.605719,0.048784,-0.003654,-0.137229,0.049715,0.266622,0.421722,-0.056355,0.058851,-0.024921,-0.678437,-0.181335,0.138703', '4301278', '26678784', '27602116', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292633', '冲锋队之怒火街头', '动作', '本来是重案组沙展的朱华标（刘青云 饰）因殴打上司被处分调往冲锋队。成为麦兜（张达明 饰）、Apple（李绮红 饰）、大丹、饭焦（陈小春 饰）几人的上司，但朱标华却与饭焦常常发生矛盾。此时，重犯教授与小鸟成功从狱中逃脱，更想在闹市中枪杀译名国际刑警，标华不管上司及同事的 反对而奋力追捕，就算最后他们一组人成功将教授抓获。一天他们在巡逻时，标华收到消息这群罪犯要到国际刑警的总部偷取九千万的赃款，标华正欲前往，但他们本身就有任务在身，饭焦便极力反对标华的行动……©豆瓣', '刘青云', '陈木胜', 7.9, 17097, 'tt0126839', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2230371203.jpg', 0.2, 1.2, 23.8, 53.2, 21.6, '0.160736,-0.083448,-0.633656,0.300468,0.075800,0.129347,0.406934,0.223885,-0.700865,-0.259005,0.217427,0.477302,-0.033440,-0.068209,0.308159,-0.331067,-0.192472,-0.546734,0.254034,-0.163579,-0.112784,-0.463182,0.042366,-0.178606,-0.092682,-0.144619,0.534981,0.125301,-0.089685,0.480042,0.355713,0.302838,-0.298788,0.520544,0.014276,-0.051652,0.428952,-0.192022,-0.152020,0.201167,0.018488,-0.380365,-0.207136,-0.054109,0.265173,0.502176,0.506614,-0.127173,-0.261085,0.040119,0.058533,-0.500719,-0.075143,0.266846,0.506872,0.170032,0.289509,0.375036,-0.169477,0.147330,0.049625,-0.005639,-0.563826,0.014129,0.069788,0.241093,-0.370711,0.224599,-0.241751,0.263447,0.054650,-0.177385,0.254656,0.362574,-0.157890,0.176457,-0.124002,-0.091836,-0.857027,0.117181,0.666182,-0.089485,0.209805,-0.182902,-0.032294,-0.378944,-0.005825,-0.247471,-0.080337,-0.067005,0.284008,0.123040,-0.287943,0.071097,-0.493978,-0.180947,-0.321802,0.120041,-0.124763,-0.307928,0.008690,-0.668548,0.190863,-0.072874,-0.182049,0.220830,0.218013,-0.120805,0.453397,-0.733850,0.183544,0.288594,0.333801,-0.673165,0.408093,0.302492,0.135711,-0.208020,-0.180054,-0.128875,0.613170,0.335110,0.390165,0.123214,-0.086232,-0.521961,-0.256343,-0.179448', '1296947', '1293265', '1297710', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292638', '007之霹雳弹', '动作', '007邦德（肖恩·康纳利 Sean Connery 饰）这次的行动将会惊险万分，因为英国军方将派他完成一项关系到英国各大城市人民安危的行动。当然，邦德随身配备的各式各样的武器将会大大增加他的胜算。这次任务起因于一个世界性的恐怖组织——魔鬼党，他们通过卧底获得了美国准备运输两枚原子弹前往英国的计划，于是在半路上拦截了美国军方的运输队，抢走了原子弹。得手后魔鬼党向英国政府勒索1亿英镑，否则英国随时会在原子弹的袭击下毁于一旦。形势万分危急，邦德只能在魔鬼党最后通牒的时间内潜入它总部，阻止它的阴谋。这简直就是一项不可能完成的任务，幸好有魔鬼党的内应，美丽的邦女郎杜明娜（克劳迪娜·奥格尔 Claudine Auger 饰）的帮助，邦德才屡屡躲过敌人的跟踪和追杀，离成功越来越近。©豆瓣', '肖恩·康纳利', '特伦斯·杨', 6.9, 8980, 'tt0059800', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2306651129.jpg', 0.7, 5.8, 51.2, 31.7, 10.6, '0.053599,0.093025,-0.609598,0.650420,0.137204,0.039592,0.265401,-0.088110,-0.165996,-0.100605,0.367578,0.484707,0.158048,-0.311867,0.335052,-0.098909,-0.493894,-0.493905,-0.244743,-0.226623,-0.427167,-0.432373,-0.495624,-0.639207,0.083302,-0.215516,0.759202,0.282929,-0.366045,0.240874,0.288945,0.390184,0.016903,0.314470,-0.093943,-0.273688,0.368922,-0.424245,-0.374364,0.585509,0.084912,-0.203376,0.078082,0.388381,0.140899,0.418672,0.444777,-0.388675,-0.055910,-0.345380,0.234366,-0.570073,0.067985,0.035687,0.390567,-0.104966,-0.090598,0.348002,-0.231141,0.247998,0.272945,-0.200972,-0.906206,0.053862,0.085164,0.042854,-0.329648,0.155915,-0.372419,0.369764,0.012367,-0.252250,0.187619,0.793398,0.290061,0.020765,-0.248682,0.192039,-0.722594,0.022228,0.773636,-0.409934,-0.103629,-0.156537,0.171848,-0.412833,-0.039886,-0.205771,0.017131,0.024010,0.593775,-0.156445,0.024126,0.277462,-0.724418,-0.066746,-0.614477,-0.318667,-0.082002,-0.325152,0.107711,-0.973765,0.247698,-0.102473,-0.278399,0.525941,0.206277,-0.037517,0.643762,-0.594869,-0.049273,0.831514,0.373422,-0.612285,0.254179,0.080378,0.163160,-0.356572,-0.093790,0.095436,0.330572,0.480530,0.083886,0.137386,0.267253,-0.507303,0.060447,0.200240', '2369613', '4014397', '1291860', '1309112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292640', '怒犯天条', '喜剧', '枢密主教为改善天主教予人的刻板印象，锐意改革，宣称在百年庆典时走进新泽西教堂大门即得豁免所有罪行。遭贬斥的死亡天使卢克（Matt Damon 饰）与守护天使巴特比（Ben Affleck 饰）认为可借此机会返回天堂。遂前往新泽西，沿路惩罚人类罪行大开杀戒。与此同时，天使长曼德川下界找到耶稣后人——堕胎医生贝瑟尼（Linda Fiorentino 饰），授意她阻止两名天使进入教堂，因为天使的行为会使上帝旨意自相矛盾引发世界毁灭。贝瑟尼在两名好色先知、黑人门徒以及缪斯（Salma Hayek 饰）的陪同下踏上拯救世界之旅。而地狱方面，恶魔艾兹瑞携三名仆从、屎魔等沿途设障，并控制上帝肉身以毁灭世界。一场决定世界命运的三界之战，在新泽西拉开了荒诞疯狂的帷幕……©豆瓣', '本·阿弗莱克', '凯文·史密斯', 7.2, 8171, 'tt0120655', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2494190541.jpg', 1.4, 6.4, 37.8, 40, 14.3, '-0.207942,0.435249,-0.308473,0.359458,-0.170993,0.294569,0.638981,0.474018,-0.257247,-0.124911,0.453066,0.610786,0.028094,-0.139717,0.745128,-0.301856,-0.410977,-0.414130,-0.027542,-0.187225,-0.291964,-0.236363,-0.110426,-0.358871,-0.114226,-1.053418,0.800493,0.277740,-0.123668,0.137085,0.127012,0.402134,-0.380960,0.073152,-0.153140,-0.343896,0.126615,0.001343,-0.452845,0.336917,-0.600794,0.043971,-0.052372,0.228397,-0.538219,-0.140010,0.448704,-0.888288,-0.009341,-0.649972,0.358667,-0.335803,-0.130602,0.251980,0.421468,0.007952,-0.164980,0.631453,0.257835,0.188799,0.177169,-0.245651,-0.637950,-0.191885,0.102217,-0.007338,-0.336021,0.147792,0.097354,0.282888,0.040577,-0.092383,0.070557,0.011026,0.523151,0.621283,0.012177,-0.082053,-0.387099,-0.041659,0.728549,-0.280642,-0.134455,-0.084932,-0.058092,-0.283372,-0.137587,-0.118911,-0.335738,0.208020,0.124998,-0.042423,0.250011,0.470821,-0.523030,-0.384951,-0.482794,-0.155843,0.069941,-0.386887,-0.023324,-0.858400,-0.012309,0.467722,0.229106,0.007047,0.255946,0.089549,0.497869,-0.586547,0.546951,0.443435,0.404770,-0.718479,0.785450,0.092813,0.184546,-0.419007,0.077188,0.733599,0.444338,0.409726,-0.395537,-0.131338,-0.210975,0.188870,0.016289,0.350965', '30181079', '1293656', '1295955', '3212221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292642', '伴你高飞', '剧情', '13岁的艾米（安娜·帕奎因 Anna Paquin 饰）在一场交通事故中失去了母亲，只好被送到与母亲离异多年的父亲（杰夫·丹尼尔斯 Jeff Daniels 饰）身边。父亲经营着一座农场，整日琢磨各种稀奇古怪的发明，面对已经长大的艾米难免不知所措，二人最初的相处生疏而隔阂。艾米收拾好丧母之痛，也努力适应农场生活，一日在一片树丛发现一窝被遗弃的大雁蛋，她小心将它们捧回家里，并成功孵出一窝小雁，但是出于政府野雁不可以家养的规定，艾米必须要令这些小雁放归自然。父亲想出了奇妙的主意帮助艾米，他动手为她制作了一架滑翔机，让她带着小雁学会飞翔，然后在迁徙季节一路护送“雁妈妈”艾米带领小雁们飞向安大略湖，在这个过程中，一对父女的心也开始紧紧连在一起……©豆瓣', '安娜·帕奎因', '卡罗尔·巴拉德', 8.9, 49439, 'tt0116329', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1378705974.jpg', 0.1, 0.5, 7.8, 38.4, 53.3, '0.327027,0.055799,-0.636767,0.289506,-0.042286,-0.347133,0.448017,0.100732,-0.426514,-0.201952,0.152412,0.641446,-0.013741,0.206696,-0.043966,0.050722,-0.462031,-0.408735,0.058302,0.023230,-0.135461,-0.409707,-0.173181,-0.284055,-0.108101,-0.050817,0.386046,-0.214709,0.111529,0.583801,-0.046486,0.005175,-0.238278,0.230397,-0.285604,0.051230,0.018677,-0.034467,-0.306756,0.090861,0.057252,-0.039952,-0.105846,-0.022362,0.277491,0.205944,0.983971,-0.363847,-0.159117,-0.077501,0.056159,-0.319090,0.057109,0.122010,0.277833,0.241650,0.032802,-0.070359,-0.383577,0.309154,0.095699,-0.216579,-0.300003,0.001852,0.102773,0.044728,-0.725690,0.226341,0.147102,-0.032033,0.158365,-0.469510,0.148764,0.347380,0.080471,0.635976,-0.281043,0.196285,-0.396495,0.009866,0.570880,-0.411726,0.097593,0.295679,-0.175542,-0.308476,0.135234,0.002387,-0.554588,-0.365311,0.310970,-0.018800,-0.364973,0.281115,-0.592768,0.176949,-0.390933,-0.204213,-0.023865,-0.456298,-0.006390,-0.256173,-0.023283,-0.335859,-0.360534,0.031794,0.004725,-0.156621,0.422527,-0.614978,0.520335,0.232452,0.161467,-0.246329,0.228167,0.037497,0.276840,-0.292538,-0.053164,0.320938,-0.113589,0.082280,0.111340,0.208311,0.142913,0.202164,-0.495171,0.349622', '21619567', '3155839', '2365260', '1299433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292646', '情枭的黎明', '剧情', '卡利多（阿尔•帕西诺 Al Pacino 饰）因贩毒而被判入狱30年，在他入狱的第五年，律师大卫（西恩•潘 Sean Penn  饰）将他从监狱救了出来。卡利多出狱后的理想就是赚够7万5千美元离开这里和还清欠大卫的人情。决心洗心革面的卡利多却摆脱不了命运的捉弄，当他勉为其难地答应表弟作为旁观者参加一次毒品交易，他卷入了一场黑吃黑的勾当。当他保住了毒品后，他从毒贩那里获得了2万5千美元作为酬劳。卡利多将这笔钱入股到一家名为天堂乐园的夜总会后，他开始寻找他的女人，凯尔。当卡利多找到凯尔后，两人的关系在微妙中回旋。这时，大卫收了一位黑手党首领的钱，答应帮助他的伙伴越狱。于是，大卫找来了卡利多帮忙。虽然凯尔苦苦哀求，为了报恩，卡利多还是答应了去执行这一危险任务……©豆瓣', '阿尔·帕西诺', '布莱恩·德·帕尔玛', 8.7, 39874, 'tt0106519', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1365185044.jpg', 0.1, 0.6, 9.2, 42.5, 47.6, '0.066475,0.075036,-0.628449,0.251969,-0.460455,-0.703216,0.702275,0.183398,-0.124535,0.092772,0.095927,0.893479,0.112186,0.005721,0.364417,0.192562,-0.435848,-0.370769,0.239542,-0.332678,-0.152077,-0.740247,-0.267229,-0.146395,-0.235353,-0.059899,0.306926,0.200094,0.081856,0.490764,0.496195,0.138031,0.056768,0.344114,-0.024081,-0.014904,0.283746,-0.045751,-0.438423,0.291774,0.127712,-0.040976,-0.355034,-0.001850,0.399822,0.461889,0.163221,-0.056483,-0.005024,-0.068933,0.150981,-0.209670,0.132295,-0.080372,-0.264151,-0.183347,0.229514,0.318897,-0.460140,-0.048504,-0.093419,-0.121679,-0.790327,-0.075038,-0.099519,-0.067691,-0.821660,0.144448,-0.383087,0.168724,0.006694,-0.271135,-0.169179,0.481199,0.160238,0.171584,-0.112549,0.151197,-0.549357,0.121717,0.670546,-0.266586,-0.056781,0.104935,0.187731,-0.387261,-0.029978,-0.153495,-0.089958,-0.016715,0.825933,-0.067789,-0.279772,0.141966,-0.602249,-0.135793,-0.587715,-0.239475,0.031582,-0.231864,-0.059818,-0.278207,-0.117368,-0.002323,-0.358743,-0.058592,0.204594,-0.483013,0.438571,-0.489103,0.253682,0.816485,0.647712,-0.454713,0.312011,0.044308,0.352176,-0.148414,0.069703,0.036521,0.302085,0.686548,0.560119,0.100142,0.376567,-0.265433,-0.021139,0.496462', '1309069', '5973984', '1293908', '1309121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292649', '骗徒臭事多', '喜剧', '弗莱迪（史蒂夫·马丁 Steve Martin 饰）和劳伦斯（迈克尔·凯恩 Michael Caine 饰）是两个在“江湖”上漂泊了多年的花花公子，他们的目标是寂寞多金的单身女子，靠欺骗她们的感情从中获利。从某种意义上来说，弗莱迪和劳伦斯也算是老同行了，因此，他们之间的明争暗斗也从未停息。一个名叫珍妮特（格伦妮·海德利 Glenne Headly 饰）的姑娘出现在了两个爱情骗子的面前，她的漂亮和性感很快吸引了两人的注意。以珍妮特为目标，弗莱迪和劳伦斯打了一个赌，谁先获取了珍妮特的芳心，谁就是当之无愧的女性杀手，两人随即展开了行动。然而，令两人万万没有想到的是，在这场游戏中，事态的发展逐渐脱离了他们的掌控。©豆瓣', '史蒂夫·马丁', '弗兰克·奥兹', 8.2, 6582, 'tt0095031', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1096752980.jpg', 0.2, 1.3, 16.9, 50.3, 31.3, '0.531783,0.033654,-0.737632,0.680918,-0.407495,-0.487506,0.770309,-0.002139,-0.530370,-0.005279,0.190856,0.851752,-0.275438,0.030713,0.203270,0.075019,-0.269229,-0.837301,-0.212742,-0.145790,-0.311847,-0.428048,-0.401337,-0.103908,-0.211785,-0.167739,0.592204,-0.104824,-0.290560,0.556532,0.637751,0.194152,-0.089044,0.418131,-0.203690,0.007660,0.205632,0.007977,-0.398547,0.377627,-0.080032,-0.280810,-0.128848,0.185057,-0.154043,0.458065,0.551441,-0.382046,-0.084560,0.052444,0.181463,-0.362732,-0.220985,-0.043177,0.401419,-0.329307,0.165879,0.216465,-0.184771,-0.204935,0.119248,0.084615,-0.875953,0.099394,0.051349,0.200081,-0.707975,0.494296,-0.031498,-0.381780,-0.090599,-0.101404,0.260303,0.330274,0.234443,-0.000610,-0.133535,-0.106392,-0.548599,0.038481,0.768498,0.233519,-0.484097,0.390167,-0.162540,-0.477162,-0.355019,-0.194443,-0.364538,-0.175145,0.426385,0.013614,-0.152224,0.273855,-0.674692,0.162325,-0.224579,-0.124915,0.101264,-0.623282,-0.183583,-0.508604,-0.443228,-0.782640,-0.502238,0.031307,-0.001584,-0.285786,0.882572,-0.966177,-0.071948,0.499329,0.066156,-0.451472,0.849046,0.187737,0.161088,-0.129857,-0.095208,-0.108826,0.076854,0.119787,0.264225,0.439708,-0.086650,-0.018079,-0.291267,0.569843', '4301278', '30162520', '1783461', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292656', '心灵捕手', '剧情', '麻省理工学院的数学教授蓝波在席上公布了一道困难的数学题，却被年轻的清洁工威尔（马特·戴蒙 饰）解了出来。可是威尔却是个问题少年，成天和好朋友查克（本·阿弗莱特 饰）等人四处闲逛，打架滋事。当蓝波找到这个天才的时候，他正因为打架袭警被法庭宣判送进看守所。蓝波向法官求情保释，才使他免于牢狱之灾。蓝波为了让威尔找到自己的人生目标，不浪费他的数学天赋，请了很多心理学专家为威尔做辅导，但是威尔十分抗拒，专家们都束手无策。无计可施之下，蓝波求助于他大学的好友，心理学教授尚恩（罗宾·威廉姆斯 饰），希望能够帮助威尔打开心房。经过蓝波和尚恩的不懈努力，威尔渐渐敞开心胸，而好友查克的一席话，更是让他豁然开朗。©豆瓣', '马特·达蒙', '格斯·范·桑特', 8.9, 661473, 'tt0119217', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p480965695.jpg', 0.1, 0.5, 7.3, 36.7, 55.4, '0.228131,-0.283332,-0.316084,0.188977,-0.534100,-0.518194,0.597473,0.120661,-0.391086,-0.412954,0.037681,0.510952,-0.233345,0.253803,0.467084,0.058382,-0.236070,-0.597194,0.283040,-0.029592,-0.045308,-0.685873,-0.192932,-0.346249,-0.223585,-0.234485,0.417807,-0.062559,-0.195794,0.245541,0.035080,0.326319,0.395655,0.396587,0.173730,-0.248754,0.284655,-0.281527,0.167914,0.042869,0.116655,-0.184241,-0.144704,0.245083,0.150377,0.169804,0.273076,-0.080667,0.070698,-0.021140,-0.016560,-0.359387,0.178646,0.181156,-0.047639,-0.046946,0.365666,0.195684,0.237412,-0.246652,-0.034914,-0.054921,-0.373477,0.074385,-0.215740,0.124270,-0.541029,0.148561,-0.266285,0.008698,0.207289,-0.459255,-0.086799,0.154948,0.106554,0.326549,-0.424482,0.025721,-0.260206,0.065739,-0.025356,0.036213,-0.056043,0.108615,-0.158375,-0.413900,0.504085,-0.017780,-0.291946,-0.097508,0.360295,-0.155363,-0.162276,0.161631,-0.254429,-0.183415,-0.310365,-0.347540,-0.228032,-0.316335,0.141257,-0.559957,0.150359,0.138194,-0.561316,-0.267002,0.035521,-0.314614,0.658378,-0.685611,0.251136,0.542636,-0.083142,-0.269268,0.690217,0.213859,0.094605,0.059225,-0.339541,0.077306,0.191694,0.619424,0.124927,0.536247,0.389526,-0.407701,-0.503880,0.363624', '1951163', '1302384', '1308842', '4727962');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292659', '变脸', '动作', '凯斯特（尼古拉斯•凯奇 Nicolas Cage 饰）是一个恐怖分子，他本想杀死探员西恩（约翰•特拉沃塔 John Travolta 饰），却误杀了西恩的儿子，西恩更与凯斯特结下不共戴天之仇。在逮捕凯斯特归案之后，他以为可以划上句号，却得知凯斯特已经把一枚毒气炸弹投放在某个人群密集的角落。为了查出炸弹地点，西恩决定利用整形手术，将昏迷中的凯斯特的脸换在自己身上，去假扮凯斯特身份套出他弟弟说出真相。这件事属于FBI高度机密，只有寥寥几人知情。凯斯特醒来，此时他有着西恩的面相。于是他决定将计就计，将知情人杀掉之后，他就变成了西恩……©豆瓣', '约翰·特拉沃尔塔', '吴宇森', 8.5, 364831, 'tt0119094', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173855883.jpg', 0.1, 0.7, 12.4, 46.9, 39.9, '0.538190,-0.010363,-0.411503,0.411163,0.142162,-0.192197,0.689019,-0.123632,-0.411727,-0.110050,0.139211,0.781950,-0.343172,0.138722,0.438251,0.281152,-0.679927,-0.666012,0.120448,-0.547388,-0.230800,-0.904471,-0.293404,-0.416381,0.114344,-0.356461,0.517124,-0.227453,0.060672,0.205040,0.380753,0.737921,0.125629,0.442578,-0.056438,0.028110,-0.100183,-0.889986,-0.195064,0.310831,0.031746,-0.094847,0.189815,0.397764,0.111197,0.457412,0.551925,-0.294567,0.237052,-0.117625,0.076145,-0.269275,0.203993,0.116883,0.047952,-0.336769,0.247701,0.426762,-0.146388,-0.083482,0.170608,0.071893,-0.612125,-0.152888,-0.066388,0.485363,-0.581547,0.063910,-0.485154,0.026597,0.314468,-0.429053,0.173231,0.524350,0.085671,0.063959,-0.111282,-0.367486,-0.795152,-0.079385,0.330158,-0.147233,0.010988,0.110047,0.093690,-0.243530,0.180326,0.158636,0.279549,-0.257081,0.679902,-0.007111,0.065651,0.335698,-0.227078,-0.500060,-0.615257,0.058765,0.074284,-0.552018,-0.206415,-0.335000,-0.119643,0.215141,-0.493564,0.002641,-0.139393,-0.191624,0.110072,-0.696342,0.162285,0.545342,0.257373,0.085444,0.183696,0.090613,0.117754,-0.369937,-0.074390,0.254116,0.616078,0.195193,0.299288,0.248295,0.357364,-0.203616,-0.263675,0.246457', '25789402', '25944714', '1307442', '25862560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292660', '惊曝内幕', '剧情', '劳埃尔-伯格曼(艾尔-帕西诺饰)是CBS电视台“60分钟”节目的王牌制作人，和德高望重的节目主持人迈克-华莱士(克里斯托弗-普拉默饰)向来合作无间。乔佛瑞-维根(罗素-克罗饰)刚被大烟草公司解雇，他的人生似乎瞬间坠入谷底。伯格曼收到一份显示烟草公司制造的香烟对人体有害的报告，找到维根来翻译。然而从这个时候开始，维根便感觉到有人在跟踪监视自己，并给家人带来极大的威胁。烟草公司提醒维根与自己签署的保密协议，他将不能公开任何有关香烟制造的研究给公众。维根不想失去医疗保险等等对家人生活的保障，然而又在备受良心拷问。他最终决定向外界宣布这一切，即使违反保密协议。他先和伯格曼录制了一集“60分钟”栏目，然后前往密西西比州出庭作证控告烟草公司。然而，烟草公司比他更快一步申请了言论禁制令，他妻子带着两名女儿离去，“60分”栏目又遭到CBS禁播。这一切巨大的代价让人压不过气。维根和伯格曼成了单打独斗的勇士，他们面对内心的正义、勇敢，并一直坚持。', '阿尔·帕西诺', '迈克尔·曼', 8.2, 23634, 'tt0140352', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p827331728.jpg', 0.2, 1.2, 17.3, 51, 30.3, '0.142376,0.031266,-0.554086,0.594123,-0.140013,-0.249085,0.469443,0.330204,-0.408530,-0.075635,0.043178,0.798375,-0.136711,-0.079173,0.229753,-0.103460,-0.397777,-0.716187,-0.015833,-0.138350,-0.168869,-0.577175,0.096871,-0.130934,-0.071284,-0.141866,0.550979,-0.001007,-0.339287,0.196336,0.205517,0.206755,0.123509,0.481543,-0.007309,-0.073540,0.155708,-0.212424,-0.420795,0.271743,0.317362,-0.115707,-0.213842,0.258785,0.265784,0.459455,0.325316,-0.130709,-0.420580,-0.053169,0.480565,-0.379038,0.169112,0.051217,0.033277,0.274804,0.193797,0.395175,-0.409009,0.138123,-0.031926,-0.117459,-0.790369,0.044095,-0.118373,0.145941,-0.423147,0.391036,-0.384793,0.175060,0.184089,-0.168208,0.104063,0.345523,0.331577,0.181349,-0.197038,-0.085330,-0.538336,0.000183,0.451211,-0.309184,-0.168228,0.184840,-0.122768,-0.269903,-0.138168,-0.131821,-0.462738,0.030001,0.184754,0.254556,-0.111836,-0.032437,-0.498230,-0.138586,-0.172184,-0.550625,0.129499,-0.681835,0.059060,-0.761724,-0.357145,-0.039729,-0.153048,0.191827,0.481529,-0.150108,0.520927,-0.465242,0.234218,0.524761,0.369719,-0.509366,0.356349,0.171579,-0.000961,-0.305681,-0.025064,0.102675,0.343092,0.485486,0.287438,0.273598,0.374645,-0.216062,-