INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292664', '魔女嘉莉', '剧情', '外表平凡性格内向的嘉利·怀特（茜茜·斯派塞克 Sissy Spacek 饰）一直都是班上默默无闻的丑小鸭，她古怪的性格和沉迷于宗教崇拜的母亲更为她遭受同学的欺凌创造了得天独厚的条件。尽管现实残酷，但在校园里，依然有人默默的关心着嘉利，这使得嘉利树立了信心想要融入校园生活中去 。三年一度的毕业晚会要开始了，尽管母亲玛格丽特·怀特（派珀·劳瑞 Piper Laurie 饰）极力反对，但嘉利下定决心要在舞会上夺得“舞会王后”的头筹一改往日抑郁的形象。可是，一些人总是不愿意放过她，舞会当晚，头戴王冠的嘉利在众目睽睽之下全身淋满了猪血，愤怒激活了她体内的女巫血统，她要使用她的能力，将整个会场变成人间地狱。本片改编自史蒂芬·金（Stephen King）的同名小说，不仅成为了青春校园恐怖小说的鼻祖，也为日后层出不穷的同类题材电影开出了一条道路。©豆瓣', '茜茜·斯派塞克', '布莱恩·德·帕尔玛', 7.5, 31649, 'tt0074285', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1996522359.jpg', 0.7, 3.3, 32.3, 47.4, 16.3, '0.210291,0.364964,-0.557364,0.684145,-0.089347,-0.206943,0.576795,0.192982,-0.498895,-0.163913,0.235173,0.809976,-0.227421,0.242956,0.159663,0.109151,-0.206196,-0.482978,-0.120880,-0.065412,-0.016342,-0.381325,-0.295482,-0.153655,-0.040947,-0.555406,0.629156,0.120005,-0.309151,0.393149,0.372476,0.260303,0.246516,0.323787,-0.091283,-0.140676,-0.143357,-0.060153,0.030460,0.128953,0.086733,-0.269524,-0.082791,0.457260,0.198110,0.167244,0.659718,-0.145914,-0.155000,-0.096334,0.697148,-0.171290,-0.046079,0.249038,0.180513,0.031944,0.179792,0.270515,0.025713,0.144882,0.110656,-0.244702,-0.768014,-0.065121,0.139322,0.176787,-0.649836,0.552284,-0.024711,-0.142350,0.059935,-0.288859,-0.041970,0.024783,0.249027,0.304363,-0.013602,-0.035794,-0.503942,0.392258,0.653028,0.066910,-0.415419,0.412714,-0.451793,-0.263472,-0.216558,-0.416497,-0.656530,-0.055846,0.257210,0.044059,-0.290020,0.336490,-0.566988,-0.052187,-0.118135,-0.084124,-0.085610,-0.240428,-0.034881,-0.425330,-0.248839,-0.329583,-0.116713,-0.192513,-0.095321,-0.319856,0.757086,-0.825876,0.263495,0.506410,0.248221,-0.338748,0.597770,0.173886,-0.009560,0.106766,-0.061377,0.325102,-0.055120,0.149664,-0.031086,0.423355,0.104166,-0.181180,-0.457013,0.702645', '27602116', '1