INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292668', '搜索者', '剧情', '曾参加过美国内战的退伍老兵埃森·爱德华兹（约翰·韦恩 John Wayne 饰）战争结束后返回家乡德克萨斯州，来到哥哥的农场希望与亲人重聚团圆。埃森一直暗恋着自己的嫂子，只把这份感情放在心底。然而一场科曼奇族的突袭，让埃森的心愿彻底粉碎。在这次印地安人的袭击中，埃森的哥嫂双双被杀，侄女黛比（娜塔利·伍德 Natalie Wood 饰）被掠，生死未卜。为了给自己心爱的嫂子复仇，也为了找到黛比的下落，埃森在哥哥养子马丁（杰弗里·亨特 Jeffrey Hunter 饰）的陪伴下，开始了艰难的搜寻岁月。埃森不惜耗时五年和花费千元赏金来寻找酋长斯卡的下落，然而埃森对印第安人彻骨的仇恨和几近疯狂的举动，让马丁开始怀疑叔叔搜索黛比的真正原因，马丁甚至担心，埃森会杀死已被印第安人同化的黛比。©豆瓣', '约翰·韦恩', '约翰·福特', 7.9, 8181, 'tt0049730', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2382744102.jpg', 0.5, 2.2, 24.2, 50, 23.1, '0.071443,-0.071809,-0.606349,0.427383,-0.111965,-0.550381,0.544884,-0.192144,-0.489241,-0.329751,-0.006676,0.824981,-0.059307,0.131447,0.313800,0.213059,-0.178043,-0.704756,-0.145396,-0.027400,-0.164157,-0.602320,-0.258999,-0.289856,0.014285,-0.368491,0.491378,0.122855,0.079554,0.661524,0.179750,0.488672,0.011419,0.388615,-0.148020,0.174512,0.099028,-0.074247,-0.516540,0.274728,0.152583,-0.047172,0.008985,0.163008,0.069465,0.271611,0.636600,-0.183482,0.226578,-0.211931,0.077623,-0.426115,0.294572,0.197445,0.196686,0.006071,0.336645,0.364411,-0.326717,-0.080456,0.141489,-0.128726,-0.619818,0.179553,0.088096,-0.023196,-0.791427,0.407831,-0.359064,0.058495,0.312108,-0.131670,0.391769,0.621045,0.160367,0.393859,-0.317145,-0.019197,-0.408918,-0.035142,0.822862,-0.545385,0.140655,0.046514,0.137025,-0.160618,0.256710,-0.228399,-0.319755,-0.025110,0.325429,0.153504,-0.069572,0.362116,-0.793787,-0.186645,-0.560937,-0.479677,0.086745,-0.440724,-0.107190,-0.399954,-0.167979,-0.092511,-0.248853,0.094487,0.058000,-0.291970,0.548445,-0.739801,0.529720,0.482667,0.355449,-0.374098,0.435776,0.078364,0.200756,-0.221386,-0.027247,0.607047,0.257924,0.136232,0.134504,0.069869,0.104729,-0.038574,-0.359736,0.477505', '26393561', '30345227', '26971054', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292676', '双重危机', '剧情', '莉比（艾什莉·贾德 Ashley Judd 饰）和丈夫尼克（布鲁斯·格林伍德 Bruce Greenwood 饰）之间的感情十分要好，两人共同养育乖巧可爱的儿子马蒂（本杰明·韦弗 Benjamin Weaver 饰），幸福生活堪称典范。可是，在忽然之间，尼克神秘失踪留下大量血迹，莉比则沦为嫌犯最终锒铛入狱。莉比将马蒂托付给了好友安吉（安娜贝丝·吉什 Annabeth Gish 饰），自己则在狱友玛格丽特（罗马·玛菲娅 Roma Maffia 饰）和伊芙琳（达文尼亚·麦克法登 Davenia McFadden 饰）的帮助下为了洗清罪名而做着不断的努力。一晃眼六年过去，塔维斯警官（汤米·李·琼斯 Tommy Lee Jones 饰）成为了获得了假释的莉比的监护人，而此时的莉比发现，尼克不仅没有死亡，甚至改头换面带着儿子和安吉过着隐姓埋名的生活。经历了双重背叛的莉比决定反击，而尼克也绝不会坐以待毙，一场充满了阴谋与危险的恶战即将拉开帷幕。', '汤米·李·琼斯', '布鲁斯·贝尔斯福德', 7.2, 7398, 'tt0150377', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2536713244.jpg', 0.3, 3.2, 42.2, 43.2, 11.1, '0.137992,-0.078108,-0.639519,0.503713,-0.087470,-0.637974,0.902467,0.200212,-0.320323,-0.225794,0.129529,0.539970,-0.207323,0.137994,0.463383,-0.095883,-0.553830,-0.768437,0.165150,-0.214084,-0.313242,-0.834920,-0.178814,-0.071856,-0.069191,-0.525403,0.394415,-0.200319,0.239700,0.586924,0.324090,0.466679,0.017629,0.259333,0.071199,0.096586,0.252981,-0.084864,-0.393419,0.311605,0.279607,0.000112,-0.185241,0.093899,0.063042,0.332374,0.665556,-0.522393,0.135895,-0.194449,0.123493,-0.287425,0.234723,0.240639,0.207768,-0.046753,0.182385,0.236878,-0.289298,-0.214212,0.550839,-0.129807,-0.697244,0.070227,0.131112,0.244665,-0.579395,0.216346,-0.221863,-0.045752,0.358936,-0.440334,-0.015774,0.533326,0.380805,0.187837,-0.305423,0.225325,-0.591284,-0.133293,0.401622,0.032427,-0.007294,0.009175,-0.197828,-0.274019,0.091278,-0.257249,-0.622108,-0.156688,0.443843,-0.021256,0.113327,0.510516,-0.533062,-0.219381,-0.489553,-0.126897,-0.029774,-0.363337,0.090374,-0.534160,-0.252393,-0.514504,-0.317876,0.084004,-0.074630,-0.317415,0.456451,-0.741915,0.403968,0.395533,0.233720,-0.219462,0.324863,0.297554,0.284146,-0.135386,-0.199273,0.531448,0.128088,0.031953,0.331041,0.280850,0.159342,0.063