INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292677', '007之黄金眼', '动作', '我们的邦德（皮尔斯•布鲁斯南 Pierce Brosnan 饰）又回来了!这次的任务是找回被苏联偷走的黄金眼——黄金眼是一种新式的电磁波武器。007经过缜密调查，发现背后的黑手是曾经和他一起出生入死的好兄弟——006艾利克（肖恩•宾 Sean Bean 饰）。艾利克夺取黄金眼，意图从伦敦银行的系统中转出巨款，并利用黄金眼将证据毁灭。007在行动中遇到了美艳女郎西娜，西娜是一位变态歹徒，想尽一切办法对付007。面对昔日的好兄弟006，007最终将如何完成这项艰巨的任务？©豆瓣', '皮尔斯·布鲁斯南', '马丁·坎贝尔', 7.6, 45728, 'tt0113189', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1720407604.jpg', 0.3, 2, 31.9, 49.9, 15.9, '0.218549,0.075229,-0.358356,0.524581,-0.491657,-0.195025,0.447361,-0.439098,-0.325862,-0.308177,0.319091,0.601914,0.053890,-0.085554,0.230180,0.193570,-0.138492,-0.664562,0.049270,-0.091987,-0.313078,-0.741840,-0.485667,-0.037500,0.120947,-0.346150,0.613382,0.205303,-0.113717,0.126423,0.571882,0.385796,-0.263478,0.295637,-0.091148,-0.177496,0.089646,-0.272415,-0.316454,0.383784,0.239454,-0.371738,-0.096578,0.297534,0.063250,0.309013,0.496476,-0.203330,-0.042317,-0.033471,0.204623,-0.327263,-0.036382,0.046955,0.054814,0.210492,-0.199806,0.418785,-0.286995,-0.079718,0.140927,-0.175644,-0.957467,-0.210654,0.193314,-0.060809,-0.538117,0.033790,-0.344354,0.227651,-0.014010,-0.360258,0.297215,0.249465,0.373082,0.239861,-0.125909,0.183986,-0.535200,0.104869,0.578190,-0.253908,-0.029249,0.026541,0.157030,-0.530473,0.064742,-0.301310,-0.045224,0.246285,0.413351,0.145838,-0.144552,0.123458,-0.693297,-0.070813,-0.571334,-0.078832,0.097424,-0.416976,0.061455,-0.749059,-0.169212,-0.239131,-0.355704,0.273330,0.074728,-0.497445,0.609327,-0.895231,-0.217508,0.676842,0.342036,-0.408670,0.369310,-0.187849,0.105351,-0.289638,-0.092312,-0.178778,0.341275,0.227205,0.171802,0.228066,0.223611,-0.289803,-0.356873,0.369540', '1793491', '27073234', '1307442', '3006783');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292679', '春光乍泄', '剧情', '黎耀辉（梁朝伟）与何宝荣（张国荣）是一对同性恋人，为了有新的开始，他们怀着美丽的梦想（去看南美洲大瀑布）离开香港来到阿根廷，却在布宜诺斯艾利斯迷了路。黎耀辉想安下心来过日子，无奈何宝荣于夜夜笙歌中放纵着自己的生命，以期找寻更多的刺激，只当黎耀辉是他受伤后的港湾，两人分歧 、争吵越来越多，心的距离越来越远。黎耀辉明白过去的日子不可能再复返时，决定离开何宝荣，而正是在他离开后，绝望的意味（对黎耀辉的爱）才在何宝荣的脑海中完整地浮现。©豆瓣', '张国荣', '王家卫', 9, 588257, 'tt0118845', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p465939041.jpg', 0.2, 0.6, 7.6, 33.9, 57.8, '0.147389,-0.005366,-1.086482,0.403988,0.210018,-0.458847,1.042307,0.080458,-0.475656,-0.006490,0.001013,0.859840,-0.154837,0.449852,0.082943,-0.059399,-0.372600,-0.662293,-0.133641,-0.377281,-0.133213,-0.383147,-0.106977,-0.137081,-0.008652,-0.109389,0.568827,0.445615,-0.148784,0.345367,0.366774,-0.073152,-0.050665,0.722349,-0.320758,-0.014638,-0.280797,0.259271,-0.307751,0.157104,0.518369,-0.229325,-0.577721,0.158929,-0.064336,0.161196,0.720532,-0.079789,-0.263391,0.104774,0.314651,-0.235902,-0.048645,0.037635,-0.020226,0.121839,0.202141,0.099276,-0.532438,0.319457,-0.190974,0.107380,-0.440938,0.400272,-0.116023,0.316598,-0.682592,0.422547,0.034724,-0.473271,0.410647,-0.557050,0.330865,0.287047,-0.058960,0.424553,-0.344216,0.102893,-0.427034,-0.123717,0.883812,0.063241,-0.020929,0.615059,0.042446,-0.465750,-0.237474,-0.022987,-0.236811,-0.377229,0.338294,0.235366,-0.364059,0.227154,-0.519422,0.270088,-0.224668,-0.227442,-0.159120,-0.426074,-0.141555,-0.202929,-0.081949,-0.459611,-0.238801,0.268957,0.016088,-0.318985,0.616625,-0.852963,0.320498,0.795236,0.456818,-0.571607,0.575366,0.248805,-0.050320,-0.196802,-0.043693,0.627033,-0.369314,0.341217,0.000559,0.194392,-0.223391,0.094729,-0.551505,0.586015', '4275444', '1292211', '1309125', '25858759');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292680', '深海狂鲨', '动作', '生化制药厂的老板Franklin（塞缪尔·杰克逊 Samuel L. Jackson 饰）提供大量资金供让Susan McAlester博士（萨弗蓉·布罗斯 Saffron Burrows 饰）研究抗老年痴呆症的药物。Susan和研究小组在设备精良的海底研究中心，提取鲨鱼脑中蛋白质，注入坏死的人类脑细胞。为了可以提取到萃取更多的鲨鱼脑蛋白，Susan也同时加大了鲨鱼们的脑容量。这一举动让本来作为试验品的鲨鱼们变得更为强壮和聪明。鲨鱼专家Carter（托马斯·简 Thomas Jane 饰）因和鲨鱼们朝夕相处时发现了鲨鱼们的异样，并向Susan提出了警告，却得到了Susan的无视。终于，在最后一次验中，那些曾经沦为人类试验品的凶残鲨鱼们向人类展开报复……©豆瓣', '萨弗蓉·布罗斯', '雷尼·哈林', 7.2, 18551, 'tt0149261', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2263908016.jpg', 0.5, 3.7, 40.9, 42.6, 12.1, '0.121947,-0.182991,-0.359153,0.462220,-0.086161,-0.432086,0.888263,-0.264600,-0.396337,-0.095553,-0.134348,0.359417,-0.156226,-0.077746,-0.212389,-0.410363,-0.278472,-0.366906,-0.259872,0.074752,-0.531263,-0.435654,-0.482634,-0.502464,0.158351,-0.646408,0.516256,-0.150695,-0.368121,0.226485,0.068984,0.476086,0.126133,0.231134,-0.073687,-0.209399,0.033887,-0.226441,0.044799,0.185652,0.090595,-0.056780,-0.057434,0.129907,0.118788,0.289557,0.848936,-0.422956,-0.234464,-0.587263,0.156996,-0.156998,0.098735,0.094879,0.143420,0.261328,0.069331,-0.019497,-0.142753,0.390791,0.099663,0.237520,-0.996227,-0.402678,-0.074275,0.107282,-0.490918,-0.153011,0.179518,0.160731,0.054377,-0.374006,0.033853,0.133920,0.093813,0.404958,-0.229553,0.265788,-0.361627,0.201771,0.394110,-0.045358,-0.348956,0.164628,-0.345036,-0.609188,0.017166,-0.043326,0.252088,-0.245170,0.534950,0.280602,-0.271689,0.433402,-1.178981,-0.065572,-0.120463,-0.665848,0.123843,0.060756,-0.176065,-0.943951,0.058189,-0.304252,-0.038876,0.216621,0.286912,-0.309299,0.975077,-0.535726,-0.064684,0.576440,0.155943,-0.519761,0.309469,-0.318036,-0.102873,-0.011163,-0.304611,-0.130454,0.310730,0.434597,0.213157,0.453155,0.192227,-0.306618,-0.547026,0.397600', '4181031', '26290398', '25774050', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292697', '虎胆龙威', '动作', '警探约翰•麦卡伦（布鲁斯•威利斯 饰）从纽约来到洛杉矶，见他分别已有半年之久的妻子霍莉（邦尼•彼地丽娅 饰）。他被邀请参加在一栋大厦的30层举行的圣诞晚会。然而一群匪徒却打起了大厦金库中存有的六亿多元公债券的主意。他们封锁了大楼，将参加晚会的人扣作人质。麦卡伦侥幸逃脱，只身与匪徒们展开了激烈的斗争©豆瓣', '布鲁斯·威利斯', '约翰·麦克蒂尔南', 8.2, 78611, 'tt0095016', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1617429340.jpg', 0.2, 0.8, 16.5, 53.7, 28.8, '0.211153,-0.010133,-0.811431,0.249837,0.061465,-0.074440,0.786534,0.040858,-0.386052,0.087787,0.532473,0.772767,-0.578588,0.203232,0.342282,-0.180513,-0.241792,-0.691014,-0.183818,-0.316190,-0.130069,-0.255291,-0.086127,-0.265212,0.179486,-0.065256,0.438858,0.339047,0.186427,0.563654,0.523082,0.103049,-0.271502,0.471076,0.038608,-0.153403,0.593916,0.006280,-0.111767,0.363109,-0.443204,-0.395605,-0.293285,-0.050965,0.193195,0.557708,0.823737,-0.124136,0.148110,-0.093677,0.124293,-0.201836,-0.177456,0.305178,0.447233,0.211557,-0.087465,0.433878,-0.229540,-0.151947,0.144837,-0.410023,-0.420463,0.245981,-0.059442,-0.026976,-0.657001,0.628445,-0.244865,0.061260,-0.192491,-0.101384,0.199404,0.436197,-0.250837,0.025312,0.024956,-0.129339,-0.776571,0.254440,0.698937,-0.288446,-0.144917,-0.134038,0.152857,-0.432243,-0.022290,-0.128826,-0.281217,-0.162648,0.605726,-0.317518,-0.026582,-0.248033,-0.737150,-0.302296,-0.394666,-0.486756,0.094200,-0.289091,-0.130311,-1.112477,0.083093,0.051975,-0.208812,0.198698,0.048614,-0.028193,0.378226,-0.862388,0.362951,0.451343,0.417699,-0.350622,0.814559,-0.209698,0.287420,0.060948,-0.206094,0.024938,0.016701,0.519743,0.413989,0.597727,-0.333073,-0.339323,-0.331096,0.269119', '25833539', '2159244', '10466639', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292699', '东方快车谋杀案', '剧情', '1930年，纽约发生了一起骇人听闻的绑票撕票案，主谋卡塞蒂携赎金逍遥法外。 5年后，侦探赫丘里·波罗（艾伯特·芬尼 饰）乘船渡过博斯普鲁斯海峡，并在朋友比安奇（马丁·鲍尔萨姆 饰）的安排下登上东方快车，去往伦敦。一日凌晨，波罗被隔壁10号包间的叫声惊醒。随后，因雪堆掩埋铁轨，列车被迫停于南斯拉夫境内。波罗再次睡下不久，又被吵嚷声惊醒。贵妇哈里特·贝琳达·哈伯德（劳伦·巴考尔 饰）声称10号包间的富翁雷切特（理查德·威德马克 饰）潜入了自己的11号包间。天亮后，雷切特的管家贝多斯（约翰·吉尔古德 饰）端来了饮料，却敲不开10号包间的门。列车员皮埃尔·保罗·米歇尔（让-皮埃尔·卡塞尔 饰）用钥匙开了锁，但是里面挂了门链。波罗与皮埃尔合力扳开门，发现雷切特口角流血死不瞑目。经医生康斯坦丁（乔治·库鲁里斯 饰）检查，雷切特被下了药，身中12刀，死亡时间为0点至2点间……', '阿尔伯特·芬尼', '西德尼·吕美特', 8.5, 123497, 'tt0071877', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1948648367.jpg', 0.1, 0.6, 11.5, 49.6, 38.2, '0.220315,0.212050,-0.353702,0.097112,0.468485,-0.308483,0.648304,0.459617,-0.119749,-0.292447,-0.112359,0.267936,-0.436983,0.130657,0.720182,0.158498,-0.619791,-0.645267,0.224904,-0.179515,-0.656242,-0.245110,0.119728,-0.152266,0.131025,-0.274824,-0.259475,0.054528,0.268220,0.397620,0.112305,0.349349,0.043073,0.316632,0.156134,0.311557,0.446176,-0.392004,0.018788,0.279304,-0.113160,-0.178022,-0.064388,-0.246184,0.318464,0.408859,0.227938,-0.135471,0.445605,-0.078648,-0.084160,0.081319,-0.006817,-0.129812,0.241448,-0.064273,-0.125088,0.338839,-0.279892,-0.112163,0.187775,0.012327,-0.072863,0.190384,-0.225017,0.018624,-0.467247,0.140746,-0.577608,0.497509,-0.275546,-0.100311,0.032265,0.103073,0.111812,0.214834,0.151457,-0.091405,-0.573004,-0.329571,0.126046,-0.151275,-0.054824,0.084806,0.085510,-0.405569,0.069543,0.170706,-0.222634,-0.124210,0.688806,-0.035473,0.246335,-0.074902,-0.436075,-0.520829,-0.789919,-0.213839,-0.168172,0.145502,-0.276527,-0.899470,0.082990,0.044169,-0.052959,0.064262,-0.078549,0.280047,0.162208,-0.049015,0.344757,0.385821,0.252037,0.309495,0.530412,-0.269995,0.219342,-0.111487,0.074871,0.299006,0.470676,0.429470,0.415192,0.449394,-0.221442,-0.231316,-0.218117,0.173127', '6517421', '25790761', '2075345', '3068206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292701', '大地雄心', '剧情', '19世纪的爱尔兰，英俊健硕的佃户青年约瑟·多尼利（汤姆·克鲁斯 Tom Cruise 饰）遭遇丧父之痛。为给父亲报仇，这个莽撞的青年决心杀死地主丹尼尔·克里斯迪（Robert Prosky 饰）。阴差阳错让他功败垂成，不过却因此邂逅了地主美丽的女儿夏莲（妮可·基德曼 Nicole Kidman 饰）。与保守的父母不同，个性张扬却又娇贵单纯的夏莲一心离开故土，到外面闯荡天地。偶然机缘，夏莲和约瑟结伴而逃，登上了开往美国的轮船。但是他们的旅途从一开始便充满了不幸，夏莲的家当被人或骗或抢，口袋空空。两人暂住波士顿大亨凯利管辖的破旧公寓里，娇傲的夏莲放下身段进工厂打工，而健壮的约瑟则靠打拳赚取营生。在此过程中，他们经历了人生的大起大落，彼此的心间也渐渐埋下爱情的种子……©豆瓣', '汤姆·克鲁斯', '朗·霍华德', 7.9, 11234, 'tt0104231', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2175156032.jpg', 0.2, 1.5, 24.3, 50.6, 23.5, '0.299530,0.036371,-0.546763,0.395860,-0.246549,-0.579403,0.823718,0.196039,-0.366028,-0.024918,0.172337,0.824457,0.148632,0.294118,0.292824,0.277505,-0.315495,-0.443711,-0.025568,-0.049912,-0.093742,-0.315548,-0.245190,-0.294054,-0.037447,-0.066043,0.601158,0.150403,-0.037111,0.648222,0.161994,0.162898,-0.139136,0.316110,-0.305533,0.167795,-0.029050,0.082030,-0.156638,0.091224,-0.087092,-0.270363,-0.290861,0.044461,0.069329,0.450503,0.687566,-0.046191,0.117803,-0.043479,0.289496,-0.020799,-0.117539,0.108635,0.041139,-0.076756,0.092912,0.100915,-0.220410,0.032852,0.244472,-0.085142,-0.426180,0.009367,0.071250,-0.076488,-0.610940,0.524637,0.047849,0.047595,0.021643,-0.210797,0.117461,0.154564,0.139597,0.183774,-0.113683,0.026250,-0.377340,0.245300,0.503517,-0.180116,-0.127763,0.272480,-0.449979,-0.345920,0.133870,-0.337664,-0.608723,-0.266218,0.422805,-0.036263,-0.061419,0.240355,-0.555808,0.010332,-0.338131,-0.048820,-0.147041,-0.170881,-0.215670,-0.367868,-0.219557,-0.435770,-0.372049,-0.017290,0.116004,-0.065832,0.543511,-0.470154,0.074716,0.597078,0.223337,-0.311216,0.690497,-0.228584,0.380070,-0.075223,-0.203560,0.403695,-0.065698,0.206921,0.056202,0.333001,-0.311500,0.095267,-0.323255,0.455727', '21619567', '1361252', '3111650', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292703', '死囚漫步', '剧情', '修女海伦（苏珊·萨兰登 Susan Sarandon 饰）受死刑犯马修·庞斯莱（西恩·潘 Sean Penn 饰）之托，前往监狱探望他。马修否认残杀年轻情侣被判死刑，提出上诉。海伦一路走访，深入村庄调查真相。一方面是被虐杀而死的无辜情侣，一方面是即将被处决的罪犯的精神依托， 海伦使尽各种办法帮助马修，但当她面对受害者双亲的痛诉以及公众的愤怒时，海伦的内心也陷入纠结的道德审判中。海伦最终感化了马修。行刑前，马修承认自己的罪行并祈求得到受害者家人的宽恕，安心而有尊严的走完人生的最后168小时。本片改编自修女海伦·普雷金的真实故事，苏珊·萨兰登因本片荣获第68届奥斯卡最佳女主角。©豆瓣', '苏珊·萨兰登', '蒂姆·罗宾斯', 7.9, 8191, 'tt0112818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503473591.jpg', 0.6, 1.8, 22.3, 52.1, 23.2, '0.113996,-0.006373,-0.332994,0.357827,0.111729,-0.184863,0.634687,0.094120,-0.368090,-0.199334,0.478136,0.609316,-0.215641,0.370348,0.390392,-0.112491,-0.534298,-0.465146,0.026194,-0.035739,-0.084804,-0.682258,0.016810,-0.262692,-0.077486,-0.263863,0.618357,0.097359,0.011289,0.347372,0.477824,0.418225,-0.087896,0.176510,0.304885,0.130897,0.282381,-0.319760,-0.452492,0.166211,0.146950,-0.257821,-0.089966,0.371750,-0.184292,0.506529,0.550971,-0.348800,-0.178759,-0.050168,0.636307,-0.543998,-0.007405,0.389105,0.006296,-0.000618,0.038701,0.416543,0.072907,0.076148,0.203448,0.125499,-0.700109,-0.141698,0.209717,0.118063,-0.266030,0.290887,-0.087004,0.380109,0.215591,0.136269,0.017844,0.131106,0.240619,0.377955,-0.232053,0.045790,-0.267320,0.224842,0.469535,-0.175902,-0.235828,-0.131194,-0.506215,-0.500891,0.328716,-0.359543,-0.424747,0.054165,0.106252,0.254489,-0.148300,0.250405,-0.252088,-0.408187,-0.508428,-0.112054,-0.050662,-0.391533,0.059723,-0.671947,-0.094489,-0.132690,-0.124410,-0.358028,-0.007930,-0.413586,0.363807,-0.392366,0.393879,0.517726,0.244489,-0.604727,0.514771,0.356203,0.147150,-0.160848,-0.176066,0.821406,0.111745,0.121469,0.031346,-0.236840,0.086400,0.015842,-0.304190,0.180179', '1293989', '25921830', '26649687', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292704', '黄飞鸿之三：狮王争霸', '剧情', '晚清末年，大清帝国摇摇欲倒。面对外敌来袭，慈禧太后鼓励民间习武抗敌。李鸿章为了逢迎太后，举办起一年一届的“狮王争霸”大赛。“狮王争霸”其实就是各们各派舞起狮子头，以武力争夺锦标。“狮王争霸”的消息一传出，各大门派纷纷摩拳擦掌，暗中招兵买马。一时，京城门派冲突四起。黄飞鸿（李连杰 饰）上书李鸿章欲取消“狮王争霸”，无奈李鸿章没有理会。无奈之下，黄飞鸿只好亲自参加“狮王争霸”，阻止各门派的自相残杀。“狮王争霸”终于开锣了！这天校场上尘土飞扬，各门派自造的形象各异、杀伤力极强的“狮子头”粉墨登场。黄飞鸿亲自率领鬼脚七等徒弟也赶到了……©豆瓣', '李连杰', '徐克', 8.1, 140645, 'tt0108592', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2047653768.jpg', 0.1, 0.7, 18.9, 53.1, 27.1, '0.070634,0.240971,-0.592178,0.538886,0.854479,-0.026245,-0.046746,0.136925,-0.267649,-0.099976,0.242300,0.280785,-0.028929,-0.062990,0.093740,-0.615494,0.094980,-0.407282,-0.235502,0.160716,0.320206,-0.119222,-0.126482,0.051969,-0.360549,0.066567,0.678851,0.060101,-0.329391,0.984893,0.581944,0.040995,0.114000,0.312569,0.123785,-0.302215,0.030322,-0.115343,-0.441650,-0.024968,-0.177053,-0.445945,-0.613682,0.282411,0.047444,0.171538,0.017382,-0.540110,0.449645,-0.443625,0.201860,-0.238055,-0.220551,0.180377,0.547871,0.250911,-0.040248,0.277562,0.180070,0.218696,-0.199137,-0.088879,-0.168188,0.181429,0.198102,0.098301,-0.364604,0.519478,-0.054059,0.045624,-0.101169,-0.055695,0.055847,0.650012,0.236593,-0.017373,0.063794,0.157706,-0.334750,0.275410,0.587862,-0.111443,0.083492,-0.628159,0.617735,-0.302022,0.225722,-0.564212,-0.030491,-0.399447,0.387512,-0.185108,0.398916,0.151723,-0.293787,-0.078790,-0.125717,-0.625298,0.222584,0.133462,0.253676,-0.718471,-0.027305,0.181312,-0.096417,-0.182256,0.445438,0.103497,0.446104,-0.621742,0.037653,0.040778,0.255900,-0.451941,0.242808,-0.063545,0.208210,0.029967,-0.322355,-0.306913,-0.088742,0.239736,-0.077694,0.065016,0.259859,-0.388549,-0.025248,0.146738', '3230460', '26365262', '1301283', '35256235');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292718', '大河恋', '剧情', '两兄弟经常跟父亲一起钓鱼。潺潺河水，静静午后，成了父子间最难忘的时刻。父亲是一个老牧师，常常在镇上布道，大儿子诺曼（克莱格•谢佛 Craig Sheffer 饰）正是继承了父亲的事业——他擅长讲课，大学毕业后回到家乡传道授业。小儿子保罗（布拉德•皮特 Brad Pitt 饰）却有着迥异的性格——他热爱自由，有一套奇特的钓鱼方法。然而，令人担心的是他迷上了赌博，并因此欠钱遭打。诺曼结婚后收到一封芝加哥大学的聘用书，他离家前往芝加哥之前，和父亲、弟弟一同在大河边再次享受钓鱼时光。他劝保罗跟他一起离开这里，然而保罗痴迷钓鱼，不愿离去。怎料，这竟是最后的相聚。©豆瓣', '克莱格·谢佛', '罗伯特·雷德福', 8.5, 71034, 'tt0105265', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503828232.jpg', 0.1, 0.7, 12.7, 46.4, 40.1, '0.269621,-0.245444,-0.809058,0.550655,-0.146335,-0.697391,0.560319,0.229257,-0.594962,-0.342836,-0.054776,0.861432,0.147423,0.570745,0.227972,0.070700,-0.391092,-0.541690,0.042911,-0.023648,-0.041857,-0.546264,-0.058286,-0.066187,-0.057883,-0.204088,0.251404,0.040710,-0.013942,0.732135,0.191846,0.053576,-0.115176,0.446515,-0.255128,0.038268,0.059620,0.274444,-0.492863,0.079761,0.341150,-0.001533,-0.159830,-0.155002,0.349948,0.141742,0.350712,-0.046656,-0.073374,-0.224379,0.223350,-0.044695,-0.076552,0.117906,0.200210,0.112278,0.354766,0.217641,-0.109830,-0.193858,-0.114036,-0.304031,-0.259256,0.240912,-0.121618,0.015339,-0.494677,0.407980,0.027031,-0.195594,0.003758,-0.639663,0.189514,0.194964,0.235176,0.292187,-0.139645,-0.029571,-0.245750,0.257622,0.780057,-0.143443,0.099608,0.306062,-0.140978,0.009303,0.477186,-0.380339,-0.322823,-0.022781,0.081983,0.050277,-0.128487,0.031271,-0.397782,0.077989,-0.120634,0.063522,0.201106,-0.265383,-0.146106,-0.625591,0.170870,-0.475802,-0.328965,0.179596,-0.013502,-0.389007,0.605841,-0.638228,0.421406,0.453802,0.349054,-0.404092,0.841230,0.155321,0.277649,-0.240208,0.196008,0.353956,0.022059,0.082146,0.107313,0.106904,0.131322,0.002725,-0.509237,0.540691', '1297239', '1303333', '1292720', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292719', '大路', '剧情', '由于生活所迫，母亲把女孩杰索米娜（茱莉艾塔·玛西娜 Giulietta Masina 饰）卖给了江湖艺人藏巴诺（安东尼·奎恩 Anthony Quinn 饰）。在相处中，女孩却发现这个空有一身蛮力的家伙，根本不懂得照顾女人，他买她只是为了让她做牛做马，在他演出的时候扮演小丑，平时给他做饭，陪他睡觉。这种粗暴蛮横的家伙，让她萌生逃离的念头，然而，几次出逃，均告失败。在一次观看高空走钢丝表演的时候，杰索米娜认识了绰号“傻瓜”的马戏团艺人——玛托（理查德·贝斯哈特 Richard Basehart 饰演），并且在他的引导下学会了演奏乐器。她非常感激，对这个男人产生了依恋。然而，但是藏巴诺的出现，再次打破了她的一切幻想，毁掉了来之不易的幸福……©豆瓣', '安东尼·奎恩', '费德里科·费里尼', 8.9, 41020, 'tt0047528', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1137199702.jpg', 0.2, 0.7, 7.6, 34.8, 56.7, '0.202485,-0.007053,-0.668296,0.436910,-0.694467,-0.063334,0.570935,0.053425,-0.431151,-0.189884,0.334539,0.749593,-0.135746,-0.013677,0.196888,-0.001985,-0.173004,-0.688431,0.268652,0.101150,-0.048656,-0.201922,-0.216813,-0.335192,-0.069537,-0.405093,0.480394,-0.046281,-0.148117,0.194484,0.162903,-0.070916,0.251503,0.667251,-0.190781,0.057290,-0.040835,-0.015403,0.130546,0.318810,0.068759,-0.371744,-0.133311,0.227925,-0.124924,0.289383,0.657918,-0.294681,-0.081679,-0.075629,0.345264,-0.293031,-0.070474,-0.079885,-0.303282,-0.138732,0.077773,-0.168445,-0.226687,-0.141863,0.065035,-0.107445,-0.543737,0.139497,0.005888,-0.064984,-0.860916,0.458037,-0.130708,0.075460,0.048244,-0.273847,0.051861,0.018478,0.498208,0.350600,-0.167751,0.008965,-0.490543,0.290301,0.609492,-0.037507,-0.216410,0.657187,-0.406095,-0.144678,-0.008428,-0.324449,-0.688510,-0.100111,0.065851,-0.105147,-0.519570,-0.069333,-0.406941,-0.168492,-0.089128,-0.053166,-0.030735,-0.726548,-0.304881,-0.381499,-0.238827,-0.179903,-0.324272,-0.295324,-0.072345,-0.572241,0.691857,-1.021549,0.228073,0.761756,0.302186,-0.391879,0.812400,0.063248,-0.152599,-0.133230,-0.071101,0.216116,0.056384,0.052540,0.208754,0.490639,-0.062080,0.040859,-0.409409,0.701924', '3230462', '2124718', '2052978', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292720', '阿甘正传', '剧情', '阿甘（汤姆·汉克斯 饰）于二战结束后不久出生在美国南方阿拉巴马州一个闭塞的小镇，他先天弱智，智商只有75，然而他的妈妈是一个性格坚强的女性，她常常鼓励阿甘“傻人有傻福”，要他自强不息。阿甘像普通孩子一样上学，并且认识了一生的朋友和至爱珍妮（罗宾·莱特·潘 饰），在珍妮 和妈妈的爱护下，阿甘凭着上帝赐予的“飞毛腿”开始了一生不停的奔跑。阿甘成为橄榄球巨星、越战英雄、乒乓球外交使者、亿万富翁，但是，他始终忘不了珍妮，几次匆匆的相聚和离别，更是加深了阿甘的思念。有一天，阿甘收到珍妮的信，他们终于又要见面……©豆瓣', '汤姆·汉克斯', '罗伯特·泽米吉斯', 9.5, 2021484, 'tt0109830', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2372307693.jpg', 0.1, 0.2, 2.6, 19.9, 77.2, '0.155275,-0.107452,-0.517094,0.480369,-0.190031,-0.513251,0.483970,0.035115,-0.383317,-0.270326,0.207741,1.033200,-0.140105,0.332832,0.110174,-0.021422,-0.095723,-0.570692,0.144144,0.044427,-0.124385,-0.514242,-0.181801,-0.120482,-0.079674,-0.254130,0.376239,-0.098528,0.115379,0.694158,0.316951,0.157043,0.216116,0.335280,-0.490236,0.243730,0.020601,0.072988,-0.415170,0.272061,0.294599,0.189344,-0.044965,0.076422,-0.194176,0.133819,0.433933,-0.140141,0.031731,-0.025048,0.473518,-0.115781,-0.153420,-0.014939,0.248255,-0.007814,0.227226,0.019362,0.087420,-0.064535,0.023305,-0.021342,-0.333259,-0.029967,0.039561,0.175922,-0.641960,0.492710,-0.107021,-0.029469,0.344297,-0.348692,0.066718,0.259550,0.069470,0.506656,-0.180619,-0.055879,-0.277714,0.273617,0.675423,-0.042274,-0.448279,0.386781,-0.187948,-0.383777,0.137713,-0.213672,-0.745681,0.186718,0.242845,-0.038538,-0.459008,0.313501,-0.499830,0.153167,-0.199043,0.001798,0.161685,-0.345303,0.010136,-0.403475,-0.115554,-0.596811,-0.407158,-0.000217,-0.097552,-0.308880,1.082516,-1.049421,0.377090,0.473503,0.189576,-0.374616,0.886920,0.240999,-0.095444,-0.286422,0.305861,0.541271,-0.128866,0.109708,0.040320,0.275602,0.008848,-0.010383,-0.294252,0.598166', '1292219', '3445516', '35048413', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292722', '泰坦尼克号', '剧情', '1912年4月10日，号称 “世界工业史上的奇迹”的豪华客轮泰坦尼克号开始了自己的处女航，从英国的南安普顿出发驶往美国纽约。富家少女罗丝（凯特•温丝莱特）与母亲及未婚夫卡尔坐上了头等舱；另一边，放荡不羁的少年画家杰克（莱昂纳多·迪卡普里奥）也在码头的一场赌博中赢得了下等舱的船票。罗丝厌倦了上流社会虚伪的生活，不愿嫁给卡尔，打算投海自尽，被杰克救起。很快，美丽活泼的罗丝与英俊开朗的杰克相爱，杰克带罗丝参加下等舱的舞会、为她画像，二人的感情逐渐升温。1912年4月14日，星期天晚上，一个风平浪静的夜晚。泰坦尼克号撞上了冰山，“永不沉没的”泰坦尼克号面临沉船的命运，罗丝和杰克刚萌芽的爱情也将经历生死的考验。©豆瓣', '莱昂纳多·迪卡普里奥', '詹姆斯·卡梅隆', 9.4, 1980956, 'tt0120338', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p457760035.jpg', 0.1, 0.2, 3, 20.7, 76, '0.229882,0.245188,-0.638543,0.275903,0.008742,-0.464700,0.883722,0.124948,-0.349219,0.110859,0.218791,0.904574,-0.355623,0.361015,0.779894,0.252454,-0.695887,-0.639565,-0.159164,-0.145768,-0.343877,-0.457749,-0.089610,-0.022981,0.080207,-0.309163,0.677246,0.226600,0.377666,0.646406,0.107199,0.107163,0.082041,0.387092,-0.211606,-0.121191,0.141509,-0.004491,-0.400744,0.315949,-0.145053,-0.147274,0.007633,-0.024492,-0.038275,0.229881,0.772976,-0.289410,0.260674,-0.275277,0.401685,-0.122130,-0.035079,0.059171,0.321691,-0.131855,-0.261730,0.327173,-0.093801,-0.359796,0.064798,-0.321724,-0.330584,0.047482,-0.150437,-0.077045,-0.466808,0.524851,-0.166065,0.174277,0.077538,-0.118002,0.111544,0.295846,0.391013,0.331056,0.001711,0.243300,-0.356076,0.277010,0.671212,0.271345,-0.419084,0.422836,-0.081416,-0.430227,-0.075291,-0.342054,-0.490563,-0.101950,0.511561,-0.050197,-0.259902,0.336598,-0.638661,0.116956,-0.433087,-0.338706,0.008894,-0.169061,-0.343850,-0.847049,-0.248651,-0.399471,0.026274,-0.002627,0.041019,-0.040473,0.633356,-0.539786,0.405904,0.472555,0.238084,-0.056700,0.792766,0.067302,0.071226,-0.231742,0.207069,0.496704,-0.299528,0.210737,-0.062753,0.407101,-0.138805,0.311046,-0.266101,0.737484', '26687241', '10466639', '11541282', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292728', '勇闯夺命岛', '动作', '美国海军陆战队法兰（艾德•哈里斯 Ed Harris 饰）将军因不满政府对退伍、战死军人及其家属的补偿和福利不满，率领部下将美军最新研制的生化武器――VX毒气弹――偷运到罗克岛，劫持了81名正在该岛观光的游客，控制了该岛。要挟美国政府48小时内支付1亿元赎金否则将杀死人质并用毒气弹袭击旧金山。罗克岛之前曾是美国防卫最严密的监狱，易守难攻。美国政府偶然从档案中发现前英国特工梅森（肖恩•康纳利 Sean Connery 饰）曾顺利从该监狱出逃，于是他们请来了梅森，要求他30小时之内带领特种部队攻占这座“魔鬼岛”……©豆瓣', '肖恩·康纳利', '迈克尔·贝', 8.6, 238615, 'tt0117500', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p636048104.jpg', 0.2, 0.7, 11.5, 43.5, 44.1, '-0.235582,-0.069867,-0.528566,0.348817,0.127293,0.144527,0.071491,-0.373935,-0.603377,-0.112834,0.277722,0.511140,0.414758,-0.107144,0.399037,0.178603,-0.674444,-0.434021,-0.250582,-0.650060,-0.612043,-0.529616,-0.125350,-0.645381,0.208529,-0.252179,0.330861,0.168440,-0.096423,0.365975,0.213872,0.576163,-0.118933,0.192004,0.097235,-0.183350,0.560699,-0.462893,-0.306794,0.416487,-0.386539,-0.220925,0.163094,0.081107,0.424751,0.591225,0.635644,-0.058309,-0.116421,-0.426312,-0.061346,-0.242328,0.007952,-0.012131,0.443898,0.234154,0.052789,0.342037,-0.296247,-0.039890,0.016661,-0.190062,-0.293381,-0.134243,-0.074649,-0.298076,-0.509404,-0.029388,-0.370012,0.566918,0.177628,0.047373,0.105883,0.805060,-0.129436,0.105365,0.017504,0.180439,-0.496098,0.525211,0.456135,-0.542146,0.120383,-0.316688,-0.000260,-0.607862,0.303466,-0.381366,0.023861,-0.048447,0.203277,-0.094852,0.097893,0.040467,-0.341479,-0.343532,-0.437330,-0.112887,0.043381,-0.174152,0.053876,-0.910029,0.142130,0.205545,0.118182,0.300128,0.101375,0.393475,0.447239,-0.374618,0.205017,0.465283,0.654101,-0.539320,0.341427,0.033422,-0.041681,-0.121130,0.103419,0.267312,0.390955,0.630065,0.057332,-0.048863,0.208789,-0.648597,-0.103799,-0.071068', '1293572', '1293537', '3036464', '25900819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292736', '时空急转弯', '喜剧', '故事发生在十二世纪的法国，一种神奇且危险的时光穿梭魔力药水令戈德弗鲁瓦骑士（让·雷诺 Jean Reno 饰）和其仆人拉弗里普伊（克里斯汀·克拉维尔 Christian Clavier 饰）一同穿越到了二十一世纪的美国芝加哥。翻天覆地的变化和车水马龙的大街让这两个“老古董”既好奇又恐惧，就在此时，一位名为茱莉亚（瓦莱丽·勒梅西埃 Pierre Aussedat 饰）的美丽女子出现在了两人的面前。巧合的是，这位茱莉亚不是别人，竟然就是戈德弗鲁瓦骑士的后代。很快，戈德弗鲁瓦骑士和拉弗里普伊便明白了他们的处境，与此同时，一个严重的问题浮出了水面——如果他们无法返回属于自己的时代，那也就意味着，他们的后代，也就是茱莉亚也将不复存在。十万火急之下，戈德弗鲁瓦骑士一行人开始寻找起了回到过去的方法。©豆瓣', '让·雷诺', '让-马里·普瓦雷', 7.2, 7298, 'tt0108500', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194735114.jpg', 0.9, 4.9, 40.1, 40.4, 13.7, '0.478753,0.033165,-0.762106,0.632994,-0.251367,-0.136999,1.040669,-0.125768,-0.594122,-0.104907,0.332214,0.995117,-0.117657,0.188541,0.498729,0.311040,-0.334167,-0.698158,0.130634,-0.463913,-0.312193,-0.450078,-0.492643,-0.270809,0.030137,-0.628972,0.304142,0.201823,-0.084470,0.451682,0.235814,0.291252,-0.205455,0.391596,-0.122912,0.098956,0.160598,-0.081711,-0.040764,0.253899,0.058238,-0.226431,-0.014160,0.353730,-0.084621,0.186161,0.664212,-0.511927,0.073878,0.077716,0.342663,-0.221285,-0.079539,0.204027,0.364950,-0.228681,0.029567,0.065093,-0.080468,-0.049378,-0.027648,0.122179,-0.810388,0.263514,-0.110035,0.495075,-0.801251,0.505685,-0.030996,-0.448245,-0.000084,-0.330043,0.260017,0.129672,0.287942,0.461097,-0.131212,-0.279743,-0.603172,-0.022237,0.675925,0.259957,-0.528380,0.386577,-0.194976,-0.406365,-0.401488,-0.074306,-0.323891,-0.130244,0.414986,0.193414,-0.080298,0.442759,-0.537945,0.274554,-0.380052,-0.280460,-0.161470,-0.287682,-0.107888,-0.440098,0.091769,-0.416968,-0.371389,0.176402,0.161749,-0.197754,0.701912,-0.560660,0.218983,0.556783,0.314030,-0.237615,0.592956,-0.216904,0.137955,-0.221653,-0.034656,0.125572,-0.080396,0.377410,0.178137,0.628675,-0.018653,-0.060460,-0.375551,0.753371', '30162520', '25763555', '1481233', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292737', '小公主', '剧情', '故事发生在英国19世纪的维多利亚时期。小主人公莎拉（秀兰·邓波儿 Shirley Temple饰）出生在贵族家庭中，但就在她刚出生的时候母亲就去世了。父亲克鲁上尉（理查德·格林尼 Richard Greene饰）因为要前往南非作战而把莎拉送到一所女子贵族学校寄读。当得知莎拉的贵族身份后，校长把她当做公主一般对待。可就在莎拉生日的当天，前线传来父亲阵亡失踪的消息。从此莎拉的境遇就发生了天壤之别，校长赶她出原来漂亮的房间，并把她当做低贱的小佣人使唤。但是坚强的莎拉并没有放弃希望，她一方面依旧在帮助着别人，一方面到处寻找着“阵亡”的父亲，她坚信父亲是不会离他而去的。终于，奇迹发生了……本片改编自世界著名儿童文学作家 F·H·伯内特夫人的经典名作《小公主》。©豆瓣', '秀兰·邓波儿', '沃尔特·朗', 8.4, 12633, 'tt0031580', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2520092725.jpg', 0.1, 0.7, 13.9, 49.4, 35.9, '0.182044,0.189277,-0.845440,0.628789,-0.258223,-0.203211,0.804858,0.070256,-0.366150,-0.465013,0.395953,0.809522,0.085876,0.365565,0.457614,0.244402,-0.322670,-0.542220,0.113639,-0.348387,-0.140225,-0.589207,-0.052702,-0.295116,0.015627,-0.503843,0.459559,-0.277004,-0.193910,0.166526,0.266973,0.052306,-0.058483,0.279843,-0.303780,0.169554,0.108015,0.157267,-0.245981,0.307930,0.326309,-0.036859,-0.142166,0.029533,0.247383,0.117331,0.589570,-0.614345,0.078419,0.017566,0.372901,-0.199838,0.126619,0.182230,0.452344,-0.129562,0.197461,0.206778,-0.152173,-0.021500,0.212920,-0.186495,-0.324523,0.316833,0.143415,0.342501,-0.610221,0.394154,-0.228074,0.024204,0.348086,-0.470057,0.362481,0.301810,0.015413,0.431457,-0.170365,0.148551,-0.559322,0.234198,0.716819,-0.149738,-0.264531,0.206404,-0.270229,-0.303816,0.133037,-0.344155,-0.795257,0.336001,0.188881,-0.162611,-0.436664,0.420986,-0.197758,-0.175587,-0.487921,-0.282275,0.299780,-0.255217,-0.074989,-0.395340,0.107702,-0.231937,-0.256381,-0.067896,0.162003,-0.283522,0.936395,-0.771751,0.393531,0.544811,0.235169,-0.499864,0.568303,0.014135,0.191138,-0.056680,0.120378,0.393536,0.131698,0.271415,-0.045480,0.166294,-0.007908,-0.362604,-0.182282,0.474240', '26348103', '1292720', '26593587', '25882279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292738', '早安越南', '剧情', '1965年西贡越战，死气沉沉的军方广播电台由于新DJ艾德里安·克绕劳尔（罗宾·威廉姆斯 Robin Williams饰）的到来，而突然变得生气勃勃。艾德里安每天以妙语如珠的风格主持早晨广播节目，幽默风趣。他的节目得到了士兵们的热烈欢迎。后来他还深入到了越南的民间生活，渐渐喜欢上了这个国家。然而他在节目中发表的跟军方宣传相抵触的言论，却使艾德里安遭到黯然下台的命运。由知名奥斯卡获奖导演巴里·莱文森执导的影片《早安越南》，根据一位电台主持人当年在越南的亲身经历撰写而成。影片以黑色幽默的轻喜剧形式，来反映越战这场残酷的战争。影片更以多首六十年代经典的流行歌曲，唤起了观众深深的共鸣与怀旧情绪。罗宾·威廉斯凭借本片一举获得1988年第60届奥斯卡金像奖最佳男主角提名及1988年第45届金球奖电影类-音乐喜剧类最佳男主角等多项大奖。©豆瓣', '罗宾·威廉姆斯', '巴瑞·莱文森', 8, 7914, 'tt0093105', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p613337449.jpg', 0.5, 1.6, 21.7, 51.7, 24.5, '0.117484,0.040263,-0.587746,0.749833,0.557413,-0.162300,0.314810,0.113646,-0.323605,-0.102376,-0.046871,0.701063,-0.532189,0.061159,0.463517,-0.310632,-0.456452,-0.719697,-0.279085,0.092718,0.094425,-0.292192,-0.273776,-0.172358,-0.082096,-0.425956,0.530108,0.121917,-0.341436,0.496735,0.656861,0.290252,0.208905,0.223765,0.283414,-0.016676,0.202040,-0.051005,-0.396088,0.246459,0.079259,-0.363254,-0.373410,-0.050391,0.101971,0.262198,0.641432,-0.252245,0.102193,0.133195,0.835657,-0.132697,-0.060463,-0.082739,0.175416,0.097224,0.124576,0.044798,0.095242,0.444612,-0.233143,-0.373998,-0.713673,-0.003413,0.009931,0.150136,-0.206195,0.327442,-0.127629,0.234432,-0.179192,-0.149496,0.111797,0.225376,0.429381,0.220722,0.041698,-0.020227,-0.017494,0.518232,0.408903,0.200775,-0.655583,0.189310,-0.398088,-0.765643,-0.135293,-0.398112,-0.529216,0.128646,0.447498,-0.164260,0.229221,0.153791,-0.638307,-0.139133,-0.012948,-0.489758,-0.052268,-0.092253,0.250669,-1.164853,-0.289802,-0.221863,0.175097,-0.341546,0.063513,-0.416423,0.858309,-0.585173,0.451671,0.395411,0.090677,-0.294017,0.553309,0.128644,0.084050,-0.113571,-0.254818,0.307483,-0.057816,0.027028,0.069482,0.334547,-0.080371,-0.452606,-0.105683,0.484167', '3318306', '24751811', '26275494',