INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292739', '恐怖幽灵', '喜剧', '一场严重的车祸夺去黛布拉（Angela Bloomfield 饰）的生命，而身负重伤的建筑师弗兰克（Michael J. Fox 饰）也在车祸后获得可与幽灵交流的能力。出院之后，弗兰克辞去工作，以通灵者的身份向镇上居民提供驱魂的服务。某天，弗兰克所在的小镇接连发生神秘死亡事件，之后他更目睹了一个幽灵杀人的场面。与此同时，警方介入调查，弗兰克则因经常出现在死亡现场而成为重要嫌疑犯。他必须尽快为自己洗脱罪名，找出幽灵杀人背后的秘密……本片荣获1996年Sitges – Catalonian国际电影节最佳特效奖。©豆瓣', '迈克尔·J·福克斯', '彼得·杰克逊', 7.2, 5857, 'tt0116365', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2388048040.jpg', 1.1, 4.8, 40.3, 42.9, 10.9, '-0.114111,-0.027622,-0.505124,0.362045,0.075309,0.048582,0.567443,0.037275,-0.255197,-0.378697,0.394928,0.767240,-0.068815,-0.051199,0.536657,-0.223206,-0.282407,-0.764866,0.063109,-0.234907,-0.390918,-0.518136,-0.367542,-0.417789,0.142966,-0.531728,0.673721,0.208002,-0.207837,0.400820,0.263773,0.566929,-0.281916,0.244729,0.058289,-0.317087,0.223894,0.109713,-0.431856,0.495976,0.130739,-0.410392,0.040754,0.253393,0.023321,0.339150,0.634297,-0.461408,-0.352495,-0.342271,0.691089,-0.705518,0.114286,-0.100855,0.427463,-0.010452,0.133865,0.419279,-0.320162,0.009169,-0.000618,-0.044869,-1.046461,-0.087943,0.193286,0.202333,-0.237839,0.155325,-0.143662,0.186915,0.140988,-0.182484,0.338607,0.427501,0.365522,0.123571,-0.249804,0.076474,-0.405022,0.239113,0.687254,-0.089452,-0.179321,0.145166,-0.057930,-0.470642,-0.126333,-0.132601,-0.036538,0.232496,0.399165,0.111370,-0.011698,0.254549,-0.338413,-0.365416,-0.400587,-0.356083,-0.136694,-0.143479,-0.176610,-0.933596,-0.073311,0.157120,-0.116632,-0.138736,0.080445,-0.373078,0.419146,-0.670865,0.346231,0.834247,0.245811,-0.708206,0.378906,-0.001560,0.532381,-0.207688,-0.312741,0.173185,0.337152,0.514691,-0.150913,-0.160521,-0.004120,-0.245737,-0.206974,0.246178', '27073234', '2369613', '25921830', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292754', '007之杀人执照', '动作', '007邦德（提摩西•道尔顿 Timothy Dalton 饰）和好友赖特在南美洲追踪毒品大王桑切斯，不但被狡猾的桑切斯逃脱了，而且赖特还掉进了桑切斯的陷阱――一个鲨鱼池。虽然最终赖特保住了性命，但他却失去了一双腿。上司要求邦德停止追查，然而报仇心切的邦德执意要追查到底，被没收了他间谍独有的“杀人执照”。没了情报机关的支持，邦德决心一个人独干。当邦德赶往巴拿马的一家夜总会准备将在这里聚会的桑切斯逮捕归案时，被一名香港的特工抓住了并被送到到与英国情报机关接头的地方。狡猾的桑切斯对后派出武装人员将他们接头的地方炸毁了。幸亏邦德大难不死，他发誓一定要桑切斯血债血偿！©豆瓣', '提摩西·道尔顿', '约翰·格兰', 7, 8466, 'tt0097742', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1019030573.jpg', 0.7, 4.9, 48.9, 34, 11.4, '0.267655,0.072238,-0.572966,0.417977,-0.203585,-0.509554,0.573838,0.065437,-0.295039,0.019715,0.088730,0.749291,0.007376,-0.174382,0.107361,0.061216,-0.171795,-0.574444,-0.115584,-0.288679,-0.482126,-0.587467,-0.354622,-0.303791,0.010901,-0.255017,0.347306,0.132314,-0.051955,0.372947,0.318112,0.323533,0.043355,0.489400,-0.307568,0.005098,0.504950,-0.474400,-0.121089,0.476312,0.154812,-0.308417,0.092537,0.291394,0.135114,0.598311,0.403754,-0.170340,0.011763,-0.066225,-0.071190,-0.442785,0.149241,0.337621,0.409961,-0.138711,-0.276162,0.493526,-0.472188,0.017682,0.367524,-0.099015,-0.827977,-0.192633,-0.034414,0.080438,-0.706089,0.043011,-0.432645,0.239079,-0.136399,-0.443296,0.394819,0.235619,0.107274,-0.037263,-0.086768,0.019320,-0.802464,-0.028961,0.494168,-0.381493,0.147425,-0.095904,0.092423,-0.542997,0.130833,-0.062121,0.012056,-0.043852,0.782274,-0.147509,-0.408980,-0.120378,-0.543460,-0.353480,-0.611912,-0.085040,-0.376444,-0.412001,-0.131442,-0.590986,0.034692,0.128926,-0.141905,0.290738,0.002437,0.097373,0.496979,-0.538951,0.058009,0.993121,0.183902,-0.639014,0.510934,0.089291,0.209416,-0.075901,0.023120,0.013907,0.663770,0.539065,0.419984,0.478645,-0.033132,-0.523233,-0.278548,0.226462', '5973984', '1300324', '1301345', '6753166');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292757', '木偶奇遇记', '剧情', '孤独的木匠爷爷这晚亲手制作了一个木偶男孩——皮诺曹。可能上天眷顾爷爷，午夜，蓝仙女显灵了，她让这个木偶男孩具有了意识，能像其他男孩那样跑跑跳跳了。获得了生命的皮诺曹兴奋不已，很快和屋子里的小动物交上了朋友。早上爷爷起来见到皮诺曹惊讶不已，他十分感激上天赐给他的礼物。然而，皮诺曹很快就发现了自己和其他男孩子还是不一样，他没有肉体，不会疼痛，只有冰冷了木制躯体。他开始不满足于现状，梦想着找到蓝仙女让她将自己彻底变为一个真正的男孩子。于是，他踏上了旅程。©豆瓣', '梅尔·布兰科', '汉密尔顿·卢斯科', 8.4, 48303, 'tt0032910', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1958894020.jpg', 0.1, 0.5, 13.7, 50.8, 34.9, '0.224063,0.276313,-0.600702,0.546769,-0.497036,-0.512636,0.858001,0.176168,-0.649073,-0.149085,-0.193316,0.964679,-0.279496,0.521506,-0.214603,0.263842,-0.304415,-0.448571,-0.284186,0.088262,-0.407602,-0.524515,-0.049443,-0.345646,-0.076038,-0.086449,0.356601,-0.038455,0.173825,0.458476,0.220461,-0.076212,0.369952,0.814761,-0.436066,0.346526,0.032188,-0.039184,0.136577,0.096445,0.142338,-0.036335,0.273923,0.539909,-0.287224,0.058366,0.512533,-0.360815,-0.210498,-0.381925,0.400358,-0.090075,0.155715,0.132121,-0.079037,-0.056344,0.114707,-0.356189,-0.098037,-0.105913,0.270945,-0.139552,-0.467508,0.137958,0.082169,0.277621,-0.737147,0.375750,0.046913,0.282462,0.182133,-0.437629,0.369498,0.141274,0.274629,0.269138,-0.255505,-0.128238,-0.704193,0.296837,0.702699,0.016323,-0.184577,0.513002,-0.399345,-0.588803,-0.034043,-0.055164,-0.275473,0.168973,0.612537,0.216746,-0.249910,-0.015026,-0.556359,-0.288560,-0.023819,0.096783,-0.237295,-0.460929,0.126281,-0.046165,0.038772,-0.450620,-0.524603,-0.188148,-0.159955,-0.508223,1.010484,-0.905404,0.253867,0.478946,0.282049,-0.273631,0.603161,-0.173249,-0.128221,-0.261750,0.595051,0.236668,-0.074992,0.436700,0.666775,0.425969,-0.287082,0.166179,-0.213895,0.851108', '1292720', '1292219', '30162520', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292759', '机智问答', '剧情', '20世纪50年代，“21点大满贯”是美国最叫座的电视益智游戏节目，成千上万的观众被它吸引。常胜冠军赫伯·斯坦普尔（约翰·特托罗 John Turturro饰）已经连续多次夺魁，但是电视台老板觉得他已经失去了新鲜感，下令节目制片人丹·恩莱特（大卫·佩默 David Paymer饰）寻找新人顶替。哥伦比亚大学优等生查尔斯·范·多伦（拉尔夫·费因斯 Ralph Fiennes饰）被丹相中，而查尔斯顺理成章地成为新一届的卫冕者。当观众们都被他博学多闻的机智回答所迷倒时，国会议员迪克·古德温（罗伯·莫洛 Rob Morrow饰）怀疑节目中存在着舞弊行为。经过详细调查取证后，惊天黑幕也正在慢慢浮出水面。由知名奥斯卡获奖导演罗伯特·雷德福执导的影片《机智问答》，取材自20世纪50年代美国电视圈的真实事件。导演深刻地描绘了这宗当年最大的电视丑闻案，荣获1995年第67届奥斯卡金像奖最佳影片提名、最佳导演提名及最佳男配角提名。', '拉尔夫·费因斯', '罗伯特·雷德福', 8, 8317, 'tt0110932', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1883551035.jpg', 0.3, 1.1, 20.9, 54, 23.7, '-0.159757,0.045198,-0.370343,0.562380,0.287018,0.008507,0.193137,-0.004316,-0.453262,-0.128119,0.094405,0.834578,-0.635395,0.104460,0.435796,-0.083542,-0.401458,-0.768452,-0.030599,-0.272769,0.087801,-0.419387,-0.326318,-0.029564,-0.105785,-0.255901,0.706999,-0.049772,-0.061177,0.320016,0.636055,0.083753,0.328292,0.068595,0.251326,0.239291,0.563069,-0.096342,-0.453171,0.373126,0.024910,-0.169125,-0.351145,0.087806,0.084783,0.139278,0.463337,-0.172673,0.118536,0.025597,0.838715,-0.379266,-0.028130,-0.155817,0.348748,0.233565,0.250035,0.213434,0.135642,0.103439,0.003003,-0.121659,-0.401937,0.047990,0.064232,0.282756,-0.098712,0.127356,-0.159462,0.233597,-0.060051,0.184588,0.029246,-0.057719,0.497640,-0.037695,0.164149,0.099301,-0.077882,0.734949,0.131944,0.052781,-0.465492,0.476783,-0.111635,-0.666503,-0.069555,-0.331229,-0.258811,0.354202,0.497443,-0.036473,0.292954,0.214785,-0.029415,-0.189708,-0.135478,-0.371924,-0.025273,-0.087910,-0.031376,-0.999045,-0.249899,0.081117,0.043343,-0.395965,-0.130177,-0.278475,0.494314,-0.286108,0.157220,0.436695,-0.159600,0.062555,0.616296,-0.002510,-0.104572,-0.414665,-0.275339,0.114256,-0.216917,-0.028917,-0.096950,0.247989,0.066569,-0.675548,-0.166565,0