INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292760', '贵妇失踪记', '喜剧', '正要赶往伦敦完婚的凯莉（Margaret Lockwood）因雪崩被困在山下的小旅馆里，偶遇摄影记者康德（Michael Redgrave），两个人因小事发生争执，第二天大家各自赶路，却登上了同一列火车。在车上凯莉与一名老妇人佛洛伊（Dame May Whitty）结伴，彼此照料。然而凯莉因头部被撞，恍惚中沉沉睡去，待她醒来，老妇人不见了。四处寻找佛洛伊，却不见她的踪影，凯莉只好报警。出乎意料的是同车厢的每个人都说没见过什么老妇人，陷入困惑的凯莉再次遇到康德。康德相信凯莉，也感到事有蹊跷，两人渐渐和好，一起展开了调查。©豆瓣', '玛格丽特·洛克伍德', '阿尔弗雷德·希区柯克', 8, 24941, 'tt0030341', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155703968.jpg', 0.2, 1.3, 19.7, 53.6, 25.2, '0.705883,-0.070348,-0.768119,-0.066021,0.381268,-0.535375,0.906024,0.263296,-0.584584,-0.543473,0.169569,0.520015,-0.397724,0.082882,0.105754,0.029877,-0.552269,-0.541738,0.176578,-0.079127,-0.318621,-0.283279,0.030945,-0.002497,-0.287173,0.017713,-0.000203,-0.234553,0.205822,1.053409,0.163619,0.021924,-0.422134,0.758920,-0.210264,0.214070,0.189645,0.095870,-0.154280,0.025398,0.043165,-0.146227,-0.324602,-0.289869,0.020051,0.486266,0.277279,0.055051,0.024879,0.076300,-0.062775,-0.324914,0.000840,0.306770,0.407298,0.145262,0.045300,-0.022947,-0.313536,0.016481,-0.153546,0.521933,-0.260139,0.426411,-0.023427,0.351910,-0.624212,0.332368,0.057129,-0.312938,0.053517,-0.437289,0.393689,0.360079,-0.076309,0.241550,0.282693,-0.115897,-0.366818,-0.254819,0.552098,0.035846,-0.167585,0.351404,0.177787,-0.326920,0.209753,0.229850,-0.313189,-0.118222,0.258267,0.078638,-0.180189,0.042903,-0.255124,0.053754,-0.490256,-0.249836,-0.406501,-0.103901,-0.054647,-0.631108,0.009977,-0.233119,-0.406263,0.184855,-0.241592,0.220702,0.234178,-0.673829,0.445714,0.302545,0.364582,-0.125232,0.683009,0.125932,0.288482,-0.085705,0.209783,0.135607,-0.096388,0.358382,0.225707,0.371033,-0.144224,0.292809,-0.670782,0.091958', '1451563', '4896894', '3267195', '1773217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292764', '汉娜姐妹', '剧情', '在一个演员家庭中，大姐汉娜（米亚·法罗 Mia Farrow 饰）的丈夫——经济人埃利奥特（迈克尔·凯恩 Michael Caine 饰）正为小姨子莉（芭芭拉·赫希 Barbara Hershey 饰）神魂颠倒。二姐霍莉（黛安娜·维斯特 Dianne Wiest 饰）戒 掉了毒品，如今为经济拮据苦恼正考虑赚钱的生意，而汉娜的前夫——电视台编导米基（伍迪·艾伦 Woody Allen 饰）终日幻觉自己得了脑肿瘤，四处求医痛苦不堪。小妹莉与孤僻的画家情人弗雷德里克（马克斯·冯·西多 Max von Sydow 饰）相处，是后者唯一的倾诉对象。埃利奥特难耐情欲，终于与莉发生了关系，霍莉在一连串打击后意外的获得了事业和爱情的拯救……围绕在这个演员家庭周围的所有人，经历着情感和事业的重新洗牌。©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 8, 13072, 'tt0091167', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2181713471.jpg', 0.3, 1.1, 20, 53.5, 25.1, '0.005011,-0.119191,-0.542509,0.392353,0.135982,-0.509102,0.663555,0.305949,-0.341639,-0.498125,-0.069788,0.536168,-0.334263,0.262425,0.333864,0.189190,-0.348073,-0.731669,0.088428,0.102187,-0.177985,-0.459064,-0.319581,-0.480014,-0.211064,-0.284607,0.457805,-0.091859,-0.055139,0.190550,0.211214,0.320509,0.056436,0.265825,0.071448,0.204487,0.286428,0.026964,-0.445610,-0.006916,0.080698,-0.081007,0.043261,0.228133,0.042900,0.350118,0.711518,-0.189383,0.162146,0.003711,0.387446,-0.102196,0.043764,-0.023490,0.195185,-0.226835,0.188953,-0.182427,-0.267368,-0.221467,0.338620,-0.125554,-0.670380,-0.178619,0.203468,0.270037,-0.561336,0.470676,-0.177003,-0.004736,0.026625,-0.181293,0.205806,0.384786,0.146762,0.494771,-0.218062,0.149068,-0.146291,0.383046,0.521057,0.299289,-0.008099,0.452513,-0.708997,-0.297312,-0.084461,-0.223810,-0.669332,-0.154319,0.394991,-0.156780,0.069285,0.608707,-0.479968,-0.170092,-0.164633,-0.055515,0.022103,-0.338243,0.161246,-0.580642,-0.277285,-0.453956,-0.267619,-0.165989,-0.039601,-0.341190,0.605818,-0.662595,-0.007008,0.791283,0.090828,-0.417596,0.565207,0.092909,0.450350,-0.242839,-0.187978,0.297987,-0.257520,-0.029418,0.058893,0.228829,0.097507,-0.034006,-0.022747,0.325616', '3154392', '1302776', '4233625', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292765', '小猪宝贝', '剧情', '猪麦最初作为游乐节目里的礼品来到了霍吉特的农场。这里的动物各司其职，坚守自己的岗位，猪麦只是其中不起眼的一员。猪麦虽然显得笨头笨脑，却是心地善良，待人友善，渐渐受到各种动物的欢迎，高贵的牧羊犬更是对它关爱有加。牧羊犬夫妻Rex和Fly专司农场的羊群放养，Rex习惯用粗暴的方式对待它眼中愚蠢的羊群。猪麦为了证明自己的价值，向牧羊犬专心学起牧羊技术，不料从Rex那里学来的强硬招数却在羊群面前失了灵。幸好猪麦渐渐掌握了门道，技术进步迅速。猪麦僭越本职的行为遭到了其他动物的不满，Rex也因为猪麦受到主人称赞而倍感生气。猪麦要去参加牧羊大赛啦！这事引来了众人嘲笑，却给了猪麦一个证明自己的机会。©豆瓣', '克里斯汀·凯文诺', '克里斯·努安', 8.2, 15233, 'tt0112431', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503827571.jpg', 0.2, 0.8, 18.6, 51.1, 29.4, '0.330883,0.156505,-0.451185,0.770565,-0.041148,-0.027240,0.510180,0.088492,-0.548631,-0.077227,0.065064,0.494364,0.173597,-0.095939,0.010570,-0.148746,-0.198017,-0.393939,-0.182505,0.018116,-0.188072,-0.147608,-0.135071,-0.356363,-0.270381,-0.390870,0.265133,0.043712,-0.343394,0.620551,0.262421,0.179537,0.165611,0.272653,-0.070414,-0.183912,-0.157989,0.071541,0.030930,0.013137,0.069070,-0.074540,-0.222032,0.358786,0.065003,0.272396,0.702179,-0.323969,-0.522686,-0.286579,0.381434,-0.105081,0.314494,0.231460,0.376352,-0.028908,0.135628,-0.164607,-0.022518,0.410867,0.081396,-0.159257,-0.902600,-0.242292,-0.023532,-0.001056,-0.638761,0.399566,0.110944,-0.084994,0.024614,-0.404710,0.060531,-0.099729,0.170459,0.437010,-0.161267,0.046012,-0.453614,-0.112412,0.330084,0.038014,-0.186539,0.337623,-0.507400,-0.588147,0.135691,-0.381610,-0.193778,-0.222182,0.172352,0.077151,-0.181430,0.216327,-0.724603,0.050828,0.121265,-0.278974,-0.051550,-0.457321,0.010026,-0.508280,0.182096,-0.553475,-0.200529,0.052767,0.055088,-0.236548,0.786718,-0.905087,0.194401,0.536536,0.255109,-0.527798,0.458509,-0.130384,0.083414,-0.135041,-0.326068,-0.042639,0.131300,0.236659,0.303411,0.303322,0.026599,-0.491684,-0.252985,0.564336', '1420088', '1793491', '35144311', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292766', '陆军野战医院', '剧情', '影片故事发生在朝鲜战场上，美军的一间野战医院，军医们整日不物正业，不是跟护士们大情骂悄，就是相互挖苦陷害。在种种笑料和喋喋不休的斗嘴中，影片懒散地展示着朝鲜战争中的美国军人，最终这场闹剧在一声“操他妈的军队”的恶骂中结束……', '唐纳德·萨瑟兰', '罗伯特·奥特曼', 7.9, 8836, 'tt0066026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1212093289.jpg', 0.8, 3.3, 23.3, 46.3, 26.2, '0.522758,-0.010616,-0.523852,0.427709,0.124340,-0.099877,0.909678,-0.284823,-0.404950,0.102171,0.228023,0.459635,-0.387535,0.308288,0.002544,-0.453340,-0.589163,-1.211368,-0.433660,0.338208,0.115565,-0.606556,-0.075576,-0.095988,-0.154980,-0.198987,0.246052,-0.013162,-0.553467,0.312046,0.407930,0.210640,-0.300174,0.186233,-0.086918,0.117538,0.159182,-0.137747,-0.387213,-0.240050,-0.020802,-0.417241,-0.612828,-0.135619,0.172687,-0.035074,0.595023,-0.523127,0.258200,-0.206166,0.339312,-0.320882,-0.126039,0.234300,0.293549,0.144731,0.582058,0.286129,0.172217,0.162154,-0.078391,0.043513,-0.380039,-0.075849,-0.216572,0.326961,-0.379286,0.816934,0.170623,0.180961,0.320067,0.057655,0.461392,0.292732,0.262923,0.558202,-0.307157,-0.074276,-0.715024,0.291770,0.689161,0.069106,-0.066750,0.129532,0.209381,0.001021,0.048988,-0.303950,-0.518945,-0.443943,0.047143,-0.642542,-0.158189,0.166407,-0.542086,0.224060,0.165648,-0.552458,-0.097558,-0.154041,-0.278278,-0.938518,-0.138796,-0.553021,-0.206851,0.191488,0.017627,-0.006940,0.726467,-0.725787,0.095830,0.440719,-0.002319,-0.275263,0.471502,0.483345,0.352154,0.181252,-0.042149,-0.269911,0.011320,0.164434,0.245131,0.408157,-0.208214,-0.146270,-0.357791,0.279685', '1307146', '1394176', '1306449', '1432699');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292769', '世界末日', '科幻', '发现一颗巨大的陨石正朝地球方向奔来，并将于十八日内撞上地球时，美国太空总署想出阻止该陨石与地球相撞造成人类毁灭的办法：派人登陆陨石的表面，钻洞贯穿至陨石的地心，放入核弹引爆。但这一切必须要在十八日内完成。钻油井工头（布鲁斯•威利斯）被委以重任，而他的下属（本•阿弗莱特）恰也是其女儿（丽芙•泰勒）的男朋友，此次任务能否成功完成，关系到女儿下半辈子的幸福。为此，他和下属接受了太空总署的高强度的训练，以期一夜之间从打井工人变成救世英雄。©豆瓣', '布鲁斯·威利斯', '迈克尔·贝', 7.8, 74103, 'tt0120591', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p686635022.jpg', 0.5, 2.4, 26.1, 48.6, 22.4, '-0.098369,0.289303,-0.805428,0.517432,-0.142797,-0.002133,0.514089,-0.040525,-0.169602,0.211021,0.143140,0.497612,-0.123094,-0.124145,0.345084,0.348586,-0.261496,-0.339512,-0.072045,-0.257388,-0.568750,-0.494313,-0.151934,-0.268016,0.055547,-0.386918,0.806441,0.094221,0.117841,0.085635,0.066972,0.341818,-0.120536,0.618242,0.040216,-0.067522,-0.239266,-0.016844,-0.416534,0.391077,-0.162526,-0.026936,0.073000,0.105180,-0.121302,0.193265,0.521134,-0.271303,0.160915,-0.491913,0.175559,-0.356051,0.178531,-0.005426,0.342940,0.126545,-0.329093,0.085737,-0.115773,0.249952,0.459868,-0.282925,-0.473768,-0.308085,-0.179883,-0.049769,-0.512136,0.150399,-0.080362,0.197026,-0.196610,-0.399818,0.096600,0.375060,0.050318,0.303437,-0.586397,0.093398,-0.514175,0.122967,0.723054,-0.192678,-0.490144,0.083335,-0.045605,-0.395850,0.029996,-0.143130,-0.152567,0.038583,0.360157,0.243895,-0.196620,0.328628,-0.562224,0.137620,-0.543047,-0.305510,-0.106313,-0.391006,-0.064669,-0.675060,0.075479,-0.049440,-0.254082,0.040926,0.021688,-0.162023,0.544127,-0.562268,0.004629,0.681899,0.406274,-0.211847,0.416834,0.017036,0.190429,-0.396397,0.028311,0.041245,0.189384,0.671332,-0.014660,0.289997,0.141133,-0.111792,-0.210906,0.304747', '34461680', '6532822', '26825482', '30220799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292772', '喜剧之王', '剧情', '痴迷脱口秀笑话表演的鲁帕（Robert De Niro 饰）梦想自己也能站在舞台上享受观众的欢呼，借疯狂粉丝玛莎（Sandra Bernhard 饰）创造的机会，鲁帕得以和脱口秀明星杰瑞交谈，鲁帕踌躇满志的自我介绍，虽然杰瑞敷衍了事，但鲁帕仍视自己为杰瑞的好友。为了能在心爱的丽塔面前出人头地，鲁帕不惜一些代价要获得与杰瑞同台表演的机会，另一方面杰瑞被鲁帕的纠缠搞到忍无可忍，将鲁帕与并不知情的丽塔赶出家门。杰瑞的行为激怒了鲁帕，他与玛莎合作绑架杰瑞，威胁电视台播放自己的表演，鲁帕终于如愿以偿，掀起一场轩然大波……本片获1984年英国电影学院奖最佳剧本奖，1984年伦敦影评人协会奖年度电影奖，1984年全美影评人协会奖最佳女配角奖。©豆瓣', '罗伯特·德尼罗', '马丁·斯科塞斯', 8.5, 15255, 'tt0085794', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1498074468.jpg', 0.4, 0.8, 10.5, 51.3, 37.1, '-0.238530,-0.010921,-0.326914,0.560811,0.368659,-0.299960,0.367047,-0.135852,-0.121633,-0.082427,0.118936,0.962857,-0.705322,0.288195,0.366256,-0.146397,-0.540220,-1.065124,0.070695,0.073109,0.218984,-0.122010,-0.171878,-0.646525,-0.300532,-0.225169,0.686167,-0.042378,-0.497922,0.610640,1.039559,-0.024757,0.128377,0.297591,0.100547,0.105553,0.537965,0.008604,-0.564939,0.312555,-0.138259,-0.425018,-0.225868,0.347601,0.264800,-0.036765,0.621808,-0.080781,0.071264,0.089533,0.499352,-0.498517,0.238870,0.040231,0.083003,0.023110,0.467187,0.063018,0.175141,-0.043429,0.024041,-0.444194,-0.769680,0.111927,0.307849,0.029689,-0.248844,0.415564,0.230087,0.383752,-0.082240,0.124284,0.033172,-0.033969,0.391422,0.156058,-0.072797,0.183873,-0.238761,0.835566,0.325456,-0.233379,0.107343,0.517795,0.006969,-0.589816,-0.080256,-0.460306,-0.548251,0.133644,0.315962,-0.166270,0.169890,0.073122,-0.516442,-0.169923,-0.139647,-0.220959,0.165013,-0.362376,0.309509,-0.974604,-0.092167,-0.084111,-0.092504,-0.111865,-0.050594,-0.461779,0.835912,-0.576617,-0.001619,0.700706,0.183741,-0.388938,0.757290,0.324288,-0.109502,-0.235184,-0.340042,0.139968,-0.155925,-0.001822,0.004548,0.098326,0.151902,-0.252611,-0.297581,0.626443', '4301278', '3318306', '34795703', '10833970');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292778', '将军号', '剧情', '1861年，Johnnie Gray（巴斯特·基顿 Buster Keaton 饰）是西部大西洋火车公司的一名员工，深爱着他的火车“将军号”，还有他的未婚妻（Marion Mack 饰）。南北战争爆发了，他的未婚妻让他去从军，军方却拒绝了他，认为让他开火车更有价值。他的未婚妻很生气，发誓除非看见他穿军装的样子，不然再也不和他说话。北军正在计划一个阴谋，准备劫走“将军号”，给南军来一次突袭。Johnnie发现了北军的诡计，更意外的在北军的阵营里解救了他的未婚妻。他必须将北军要突袭的情报带回南军的阵地，他一路上驾驶着“将军号”，遭遇重重追击。南北军大战一触即发......©豆瓣', '巴斯特·基顿', '巴斯特·基顿', 9.1, 25885, 'tt0017925', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2248676081.jpg', 0.2, 0.5, 5.7, 31.6, 62.1, '0.012390,0.005675,-0.776087,0.752476,-0.022127,-0.151939,0.539712,0.143707,-0.282729,-0.154856,0.403066,0.695177,0.349610,-0.255985,0.245785,0.060989,-0.198009,-0.705756,0.162930,-0.228610,-0.178530,-0.144913,-0.261792,-0.192187,0.368788,-0.362988,0.575588,0.124044,-0.233430,0.440163,0.296766,0.066320,0.328750,1.006221,-0.183386,0.004930,0.027327,-0.365433,0.114684,0.344544,-0.227329,-0.310623,-0.145710,0.425347,0.091798,0.451099,0.659973,-0.193468,-0.116573,0.108168,0.072543,-0.427772,0.351446,-0.017962,0.551526,-0.047167,-0.063974,0.312113,-0.118042,0.143055,-0.006880,0.142723,-0.542448,-0.109352,-0.262521,0.149558,-0.930922,0.563021,-0.532582,0.208264,0.237843,-0.409556,0.369970,0.663589,0.080465,0.021697,-0.281696,-0.084569,-1.028402,0.106679,0.752805,-0.068297,0.238681,-0.017591,0.065391,-0.241842,0.002884,-0.256546,-0.602750,0.085337,0.462893,-0.397260,-0.161383,0.147712,-0.487844,-0.120236,-0.305554,-0.110801,-0.228950,-0.420853,0.137634,-0.378197,-0.062007,-0.183719,-0.146103,0.308834,0.063564,0.198182,0.478473,-0.725371,-0.129718,0.671666,0.571375,-0.696589,0.607164,0.636867,-0.193781,-0.056222,0.138596,-0.008765,0.017595,0.456194,0.129104,0.585980,0.083208,-0.381394,-0.279683,0.395310', '26718282', '25908042', '1292584', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292779', '我知道你去年夏天干了什么', '悬疑', '朱莉（詹妮弗•洛夫•休伊特 Jennifer Love Hewitt  ）和其他三个中学生在毕业之际来到一个美丽的海滨城市, 开始了一次狂欢式的度假。怎料乐极生悲，四人在黑夜的公路上飚车撞死了一个路人。慌乱中他们决定把尸体抛入大海，并约定对此事守口如瓶。一个快乐的旅程以阴霾结束。本以为一切都成为秘密。朱莉开始了她全新的大学生活。但是一封来信却打破了她的平静。里面赫然写着“我知道你去年夏天干了什么”，朱莉惊恐万分。果然，恐怖异样的事件开始发生在几个年轻人身上，他们推测凶手是谁，猜疑纷纷，然而血腥的结局早已在等待着他们……©豆瓣', '詹妮弗·洛芙·休伊特', '吉姆·格莱斯皮', 6.3, 17671, 'tt0119345', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2178451760.jpg', 2.1, 12.8, 59.1, 21, 5.1, '0.371300,0.054361,-0.894903,0.474964,-0.123810,-0.154330,0.794276,-0.038507,-0.448104,-0.191591,0.175896,0.617319,-0.328114,0.362913,0.194743,-0.079050,-0.384299,-0.643292,0.110003,-0.331535,-0.259809,-0.348973,-0.086287,-0.170766,0.216809,-0.092740,0.386326,0.301120,0.106676,0.594715,0.280301,-0.049594,-0.250836,0.608718,-0.207927,-0.039750,0.164889,-0.063540,-0.215465,0.051747,-0.172876,-0.263621,-0.304072,0.187358,-0.041056,0.361517,0.723583,-0.091821,-0.425554,0.219133,0.314684,-0.453194,-0.031638,0.298662,0.278262,-0.075081,-0.007239,0.243798,-0.000021,-0.026155,-0.072513,-0.057067,-0.468247,0.153403,-0.317670,0.434715,-0.492643,0.554663,-0.007440,-0.136237,0.051382,-0.321538,0.321891,0.213432,0.201670,0.365649,-0.212689,0.006419,-0.629168,0.050142,0.862056,-0.070968,-0.134447,0.447077,0.121017,-0.225901,-0.123455,0.284248,-0.376385,0.073315,0.450926,0.000910,-0.489583,0.166606,-0.517137,0.026870,-0.095530,-0.431839,-0.242081,-0.426662,-0.343197,-0.373234,-0.010641,-0.160121,-0.456000,0.093331,-0.088725,-0.181058,0.652979,-0.582101,0.293947,0.353285,0.052452,-0.477772,0.396701,0.122150,0.117774,-0.096296,0.085104,0.176491,0.084500,0.461112,0.206997,0.531355,-0.115320,0.092424,-0.453961,0.662131', '3626364', '3011051', '26687241', '26418093');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292780', '时光倒流七十年', '剧情', '大学生理查德（克里斯托弗·里夫 饰）在毕业典礼上遇到了一个老妇人，老妇人送给他一只金表，并表示等他回来。虽然他感到非常奇怪，但事情也不了了之了。8年后他成为一个著名的剧本作家，他为了寻找灵感来到了一家酒店度假，酒店历史悠久，在历史陈列室内他被一张女明星Elise（简·西摩尔 饰）的照片深深吸引住了，并认得她就是送金表的老妇人。原来老妇人在送于他金表的晚上已经离世了。而他通过梦境，回到时光倒流的70年前，发现自己竟与这名女明星又有一段美丽的爱情故事©豆瓣', '克里斯托弗·里夫', '吉诺特·兹瓦克', 7.8, 42782, 'tt0081534', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1443640545.jpg', 0.5, 3.4, 28.4, 43.1, 24.6, '0.223511,0.137300,-0.549214,0.407589,-0.103344,-0.334997,0.909799,-0.021170,-0.542704,-0.555020,0.163155,1.123906,-0.304196,0.462655,0.421283,0.167139,-0.172184,-0.499224,0.295372,-0.428723,-0.229995,-0.210739,-0.241134,-0.167794,0.158329,-0.139747,0.456495,0.060774,-0.078842,0.507057,0.185239,0.082841,-0.001022,0.542688,-0.381094,0.084411,0.083709,0.177760,-0.073243,0.176625,0.100097,-0.459970,-0.064062,0.166190,-0.187229,0.149259,0.598206,-0.141633,-0.249251,0.136690,0.397107,-0.147018,-0.237933,-0.022460,0.115781,0.126820,0.180148,0.034641,-0.407816,0.090528,0.258849,-0.281837,-0.335080,0.153839,-0.016780,0.292455,-0.535556,0.720205,-0.221198,0.006059,-0.160352,-0.677474,0.245567,-0.029888,0.145388,0.317667,0.018114,-0.026534,-0.564953,0.428807,0.349969,0.053234,0.029868,0.573550,-0.098134,-0.573764,-0.034166,0.125788,-0.368238,0.349677,0.444626,-0.034704,-0.165812,-0.247360,-0.623377,-0.194699,-0.307909,-0.289941,0.085176,-0.348877,-0.228852,-0.479217,-0.106558,-0.200096,-0.357135,-0.088957,0.062815,-0.214556,0.503338,-0.611641,0.238064,0.518173,0.041461,-0.353260,0.752980,-0.073440,-0.043671,-0.182257,-0.052373,0.218752,0.045156,0.345462,0.070853,0.340011,-0.168794,-0.268574,-0.393231,0.579969', '1361252', '30162520', '1309172', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292781', '细细的红线', '剧情', '1942年，第二次世界大战已进入白热化阶段。南太平洋上，日美双方展开激烈角逐，人性的底线在炮火声中被彻底摧毁。隶属美军的“查理步兵连”接到一项艰巨的任务，他们受命登陆瓜达康纳尔岛（Guadalcanal），夺回日军占领的210阵地。日军占尽地利优势，防守固若金汤。然军令 如山，即使刀山火海查理步兵连的将士们也要奋勇向前。这群年轻的小伙子为了所谓的正义投入这个残酷的血肉战场……本片根据美国作家詹姆斯·琼斯（James Jones）1962年的同名小说改编，并荣获1999年柏林国际电影节金熊奖和荣誉提及；1999年芝加哥影评人协会最佳摄影奖；2000年澳大利亚影评人协会最佳外语片奖；2000年电影旬报最佳外语片导演奖。©豆瓣', '西恩·潘', '泰伦斯·马力克', 7.8, 31321, 'tt0120863', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2511261922.jpg', 0.9, 3.5, 24.5, 46.5, 24.6, '-0.033759,0.053496,-0.575098,0.662003,0.525570,-0.028745,0.024513,-0.278711,-0.292178,0.075063,0.171152,0.713695,-0.047526,-0.378669,0.385509,-0.281480,-0.396432,-0.972669,-0.275077,-0.286251,0.067339,-0.291792,-0.470722,-0.190657,-0.100741,-0.366354,1.099275,0.173162,-0.261268,0.389678,0.425901,-0.017958,0.165835,0.016847,0.356897,-0.011489,0.321123,-0.524438,-0.668100,0.538616,-0.439548,-0.194346,-0.476314,-0.117541,0.283374,0.322866,0.836288,-0.209663,0.063253,-0.053573,0.567049,-0.614720,-0.104458,0.057211,0.574988,-0.115822,-0.053738,0.364816,0.190377,0.367253,-0.231261,-0.515169,-0.608191,-0.136073,0.163294,-0.106253,0.000689,0.636228,-0.214035,0.573087,-0.373707,-0.079112,0.039719,0.443008,0.156544,0.120444,-0.255039,0.028996,-0.174453,0.633685,0.511885,-0.291012,-0.471344,-0.295827,0.055567,-0.597521,-0.032669,-0.754892,-0.245907,0.048132,0.333804,0.014918,0.237685,0.224154,-0.671605,0.217143,-0.009032,-0.569438,-0.123597,-0.134004,0.023755,-0.857958,-0.060606,-0.236222,-0.170793,0.191507,-0.011432,0.166888,0.889677,-0.328156,0.144737,0.572475,0.161161,-0.107587,0.572434,0.258931,0.107045,-0.270912,-0.074659,0.525735,-0.225160,0.181035,0.058757,-0.105531,-0.336763,-0.540761,0.007357,0.286463', '1780122', '1298911', '1322847', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292784', '芬妮与亚历山大', '剧情', '1907年圣诞，艾柯达家族两代人共享圣诞晚宴，其乐融融。可好景不长，小主人公亚历山大（伯特·格福Bertil Guve饰）和芬妮（妮拉·艾尔温Pernilla Allwin饰）的父亲奥斯卡（艾伦·艾德沃 Allan Edwall饰）在排练《哈姆雷特》时突然中风，弥留之际把苦心经营的大剧院托付给妻子艾米莉（艾娃·弗洛灵 Ewa Froling饰）。一年后艾米莉带着一双儿女改嫁冷酷残暴的青年主教爱德华。爱德华的母亲和姐姐专横刻薄，亚历山大与继父的矛盾日益尖锐，却只能默默忍受。当老祖母海伦娜（古娜·沃根Gunn Wallgren饰）得知此事后，暗中请老友帮忙，终让孩子们重获自由。艾米莉也逃离了主教家，从此一家人再次团聚享受着天伦之乐。本片获得第56届奥斯卡最佳摄影、最佳艺术指导、最佳服装设计和最佳外语片等多项大奖。©豆瓣', '克里斯蒂娜·阿道夫森', '英格玛·伯格曼', 8.7, 17560, 'tt0083922', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1172714598.jpg', 0.5, 1.2, 10.7, 36.9, 50.7, '-0.279181,0.023003,-0.419393,0.290012,0.155619,-0.730509,0.459176,0.255910,-0.436313,-0.244055,0.059180,0.758790,-0.386685,0.527148,0.504723,0.120213,-0.679130,-0.596990,-0.053988,0.009076,0.000219,-0.321932,0.084196,-0.137317,-0.166450,-0.393907,0.437026,-0.299206,0.185423,0.588143,0.403996,0.156007,-0.079684,0.104145,-0.258130,-0.003091,0.398566,0.100674,-0.575627,0.274303,0.091059,0.093925,-0.446283,-0.171883,0.326564,0.091946,0.453342,-0.413480,0.234270,-0.175109,0.294758,-0.042825,-0.003098,0.192623,0.038402,-0.148984,0.283929,0.240433,-0.214039,-0.120432,0.129858,-0.383368,-0.417849,0.056171,0.000522,-0.037009,-0.428126,0.352349,-0.143176,-0.020781,0.347925,-0.084968,0.024087,0.372532,0.079154,0.276068,-0.112491,0.179481,-0.106251,0.456692,0.210772,-0.064508,-0.180894,0.103340,-0.160408,-0.399204,0.262822,-0.182358,-0.645581,-0.100912,0.509506,0.167860,0.208711,0.376784,-0.314950,-0.402260,-0.427459,-0.037734,0.232917,-0.465590,0.088978,-0.853811,-0.058979,-0.162708,-0.129149,0.092393,0.193795,-0.095088,0.633352,-0.515539,0.534477,0.159119,0.222953,-0.077934,0.509499,0.096674,0.526358,-0.500283,-0.333909,0.262168,-0.065754,0.039242,0.283664,0.247019,-0.043575,0.043043,-0.233083,0.322354', '2075345', '1298616', '3563200', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292785', '空前绝后满天飞', '喜剧', '前飞行员Ted Striker （罗伯特·海斯 Robert Hays 饰）在一场战争中有了心理阴影，对飞行有恐惧。他的女友Elaine Dickinson （朱丽·哈基提 Julie Hagerty饰）却是个空姐。这天，Elaine跟Ted提出了分手，之后便上飞机上班 去了。Ted为了挽回女友的心，也费尽心思上了飞机。然而，飞机上发生了无数令人啼笑皆非的事情。先是乘客们相继发生食物中毒，连机长也不能幸免于难。无奈之下，唯一有驾驶飞机经历的Ted只能和女友一起坐在驾驶舱操纵飞机。他打开了自动驾驶，飞机能够自行运转，但无法正常降落。于是一场惊心动魄的迫降之旅开始了，而Ted是否能重新赢回女友的心呢？本片各种无厘头桥段让人捧腹大笑，成为好莱坞经典喜剧。©豆瓣', '卡里姆·阿卜杜尔-贾巴尔', '大卫·扎克', 7.5, 16783, 'tt0080339', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2404954511.jpg', 1, 4.7, 32.1, 43.7, 18.5, '0.364483,0.171573,-0.847727,0.466863,0.264288,-0.198412,0.481554,0.086829,-0.525873,0.074004,0.274647,0.642277,-0.424159,0.167908,0.428401,-0.135467,-0.757908,-0.623377,0.122414,0.002653,-0.642275,-0.317272,0.008683,-0.290199,0.021200,-0.190656,0.588081,0.155162,0.109315,0.517253,0.379217,0.221690,0.107208,0.441477,-0.097609,-0.006400,-0.217723,0.216653,-0.134854,0.170184,0.149477,-0.377973,0.105696,0.072857,0.102057,0.210896,0.755981,-0.074684,-0.260072,-0.002602,0.049764,-0.267727,0.087705,0.146018,0.060491,0.215741,0.068505,-0.104614,-0.104137,0.087018,0.220620,0.430538,-0.468973,0.119277,-0.411300,-0.237391,-0.338426,0.140663,-0.323389,-0.003416,0.037488,-0.281240,0.336570,0.333002,0.391191,0.272096,-0.278672,0.014803,-0.369742,0.151853,0.834631,0.289138,-0.348667,0.692004,0.015196,-0.319126,-0.246367,-0.382015,-0.284447,0.041247,0.328977,0.148836,-0.172542,0.137265,-0.478143,0.042173,-0.425354,-0.456882,-0.200994,-0.324046,0.127362,-0.561973,-0.015540,-0.133577,-0.126538,0.046646,0.002331,-0.316388,0.626298,-0.788898,0.162485,0.422530,0.086955,-0.363852,0.532962,0.010704,0.155100,-0.007030,0.259460,-0.007565,-0.454361,0.589895,-0.024167,0.295425,-0.116785,0.049093,-0.123258,0.137031', '1458900', '1438591', '26418093', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292792', '我自己的爱达荷', '剧情', '麦克（瑞凡•菲尼克斯）和斯考特（基努•里维斯）同为沦落街头的男妓，然而因为相差巨大的家庭背景，“同为天涯沦落人”的他们并非表面般“心照不宣”。时常昏厥的麦克脑海中一直充满着有关童年的破碎片段，爱达荷的诗意田园也常常入他梦境，他一心想找回失散多年的母亲，将斯考特视为知己和爱人。斯考特本是波特兰市长的儿子，“自甘堕落”只为体会放荡青春的快感，他清楚地知道，虽然现在陪着麦克一路从波特兰到西雅图，又从爱达荷到意大利，麦克却成不了他最终的温暖归宿，他能回归的，是权势、荣华与姑娘。©豆瓣', '瑞凡·菲尼克斯', '格斯·范·桑特', 8.3, 61230, 'tt0102494', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p906164091.jpg', 0.3, 1.6, 16.9, 44.7, 36.4, '0.264053,0.142342,-0.821538,0.649574,-0.116900,-0.488094,0.908104,0.245865,-0.661675,-0.131020,0.147559,0.980833,-0.185826,0.532797,0.239244,0.400310,-0.130652,-0.752997,0.064596,-0.187028,0.087093,-0.639324,-0.454383,0.070328,-0.043006,-0.254474,0.428657,0.072787,-0.145764,0.485806,0.169184,0.317312,0.024277,0.477432,-0.268098,0.196460,-0.205507,0.124965,-0.565770,-0.112076,0.425319,0.053703,-0.302127,0.047461,-0.074599,0.442410,0.562740,-0.258696,0.262453,0.110228,0.232923,-0.025199,-0.064686,0.029873,0.027254,-0.171849,0.019337,0.350372,-0.176618,-0.076481,0.112014,0.022188,-0.765291,0.045337,0.075773,0.316206,-0.408973,0.464781,-0.165336,-0.169189,0.317243,-0.140972,0.120455,0.061050,-0.062615,0.790339,-0.232201,0.071653,-0.505542,0.251006,0.893792,0.277626,-0.208922,0.409638,-0.410303,-0.290301,-0.098405,-0.321969,-0.595798,-0.214970,0.116077,0.202929,-0.145674,0.509307,-0.499299,0.166304,-0.233180,-0.014591,-0.059254,-0.653297,0.005072,-0.264874,-0.299654,-0.438807,-0.262974,-0.012420,0.058987,-0.373830,0.566767,-0.753879,0.157585,0.718130,0.108123,-0.172823,0.692441,0.239357,0.013111,-0.311485,-0.121951,0.593930,0.111782,0.147689,0.235350,0.201025,-0.050805,0.006950,-0.641934,0.596585', '3014557', '1296534', '4275444', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292798', '铁面人', '剧情', '公元17世纪中叶，法国宫廷改朝换代，年轻俊朗的路易十四（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）继位，却是个荒淫无道、暴虐成性的君主。举国上下怨声载道，暴乱不断，路易却从未有半点反省与收敛。此时此刻，曾经风光一时的三剑客们尘埃落定，可是路易设计害死了阿多斯（约翰·马尔科维奇 John Malkovich 饰）的儿子拉乌尔，霸占了拉乌尔的未婚妻，这迫使阿拉密斯（杰里米·艾恩斯 Jeremy Irons 饰）、波尔朵斯（杰拉尔·德帕迪约 Gérard Depardieu 饰）、阿多斯重新拿起搁置多年的剑，密谋推翻路易的暴政。在曾经的好友——皇家侍卫长达尔大尼央（加布里埃尔•伯恩 Gabriel Byrne 饰）缺席的情况下，三剑客从牢里找来了戴着铁制面具的犯人菲利普（莱昂纳多•迪卡普里奥 Leonardo DiCaprio 饰），其真实身份竟然是路易的双胞胎兄弟！他们试图用菲利普取代路易，一着前所未有的险棋，攸关千万人的命运……', '莱昂纳多·迪卡普里奥', '兰道尔·华莱士', 7.2, 22936, 'tt0120744', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190591704.jpg', 0.4, 4, 42.7, 39.4, 13.5, '0.022191,-0.097310,-0.476397,0.566265,-0.091501,-0.625152,0.698267,0.202333,-0.424459,-0.347931,0.232565,0.473251,-0.120139,0.076928,0.551748,0.232869,-0.658955,-0.508757,0.096168,-0.142493,0.053853,-0.496647,-0.478452,-0.165646,-0.077050,-0.481485,0.322523,-0.271908,0.006607,0.283380,0.634588,0.394236,0.281450,0.075430,0.042703,0.071802,0.220597,-0.391220,-0.277384,0.107514,-0.101585,-0.005824,-0.424099,0.234938,0.115217,0.423081,0.302692,-0.675318,0.430930,-0.021722,0.496345,-0.052722,0.063437,0.142156,0.156348,-0.104817,-0.278465,0.300939,0.024925,-0.266853,0.381413,-0.151911,-0.392053,0.093628,0.045759,0.168715,-0.508127,0.270702,-0.386258,0.130798,0.033907,-0.172767,0.017712,0.403125,0.223805,0.298971,0.101994,-0.069146,-0.397592,0.036883,0.294374,0.081311,-0.381994,-0.301276,-0.336614,-0.333366,-0.051254,-0.117277,-0.591085,-0.357183,0.493995,-0.322596,0.255036,0.705332,-0.346204,-0.286749,-0.572854,0.013527,0.249421,-0.083804,-0.008694,-0.301421,-0.372253,-0.362893,-0.192698,0.004589,-0.103011,0.084024,0.199600,-0.398833,0.418565,0.441422,0.141750,0.033016,0.364622,0.149040,-0.070694,-0.087538,-0.361804,0.422767,0.329694,0.077498,0.152873,0.441992,0.297683,-0