INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292812', '哈洛与慕德', '剧情', '20岁的上流社会男孩哈洛（Bud Cort 巴德•库特 饰）对死亡异常迷恋，喜欢伪装自杀吓唬母亲，热衷参加葬礼，甚至购买了一辆灵车。母亲习以为常，却也不堪忍受，因此催促哈洛早日成家，成熟起来。在他人的葬礼上，哈洛认识了79岁的穆德（Ruth Gordon 露丝•高登 饰），一个与他有着相同爱好的老妇人，从此走入慕德奇妙多彩的世界。开朗搞怪的慕德使阴郁的哈洛逐渐开朗，并最终向她展开心扉。哈洛的死亡游戏接连吓跑多个应征女孩，忍无可忍的母亲决定让他参军，他和慕德却设计摆脱了兵役困扰。两个忘年交的朋友越走越近……©豆瓣', '鲁思·戈登', '哈尔·阿什贝', 8.2, 6978, 'tt0067185', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1850335086.jpg', 0.9, 2.7, 17.9, 41.6, 36.8, '0.292948,-0.009132,-0.383657,0.322829,-0.341563,-0.237360,1.010410,0.135805,-0.303445,-0.087325,0.031850,0.936465,-0.157235,0.424975,0.339495,-0.049479,-0.198306,-0.285863,0.161402,0.011085,-0.052820,-0.299437,-0.230228,-0.341683,-0.048146,-0.361288,0.447258,0.153733,0.025969,0.886140,0.281717,0.191514,0.035165,0.471805,-0.071074,-0.055942,0.085999,0.027067,-0.273297,-0.051116,-0.199820,0.065279,-0.133522,0.291032,-0.252717,0.333850,0.634700,-0.136379,-0.288580,-0.074977,0.532678,-0.218645,-0.224521,0.186140,0.041229,0.037440,-0.108691,-0.048366,-0.093134,-0.095386,-0.285741,0.086880,-0.385706,0.188184,0.065034,-0.094345,-0.605490,0.456212,-0.048873,-0.081589,-0.046459,-0.481045,0.129970,0.188983,-0.007596,0.379661,-0.220340,0.143851,-0.367187,0.283919,0.644498,0.111988,-0.430708,0.439378,-0.566650,-0.284469,0.099852,-0.375132,-0.502559,-0.231538,0.110240,-0.105928,-0.052915,0.008812,-0.374987,-0.097399,-0.340726,-0.033633,0.093344,-0.450690,-0.021308,-0.431118,-0.516375,-0.318269,-0.317172,-0.081291,-0.188842,-0.214810,0.627774,-0.537228,0.415375,0.443928,0.409068,-0.511166,0.462792,0.218309,0.152118,-0.410034,-0.096079,0.668737,-0.107341,0.066244,-0.136652,0.474238,0.005984,-0.033359,-0.419665,0.602182', '4896894', '1296534', '1309172', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292822', '燃眉追击', '剧情', '美国中情局干员杰克·雷恩（哈里森·福特 Harrison Ford 饰）再次卷入一场错综复杂的贩毒战争之中。因前任陆军上将罹患癌症，雷恩被任命为CIA副局长一职，奉命调查美国总统友人遭毒贩谋杀事件。总统好友及其家人在睡梦中惨遭贩毒集团毒害，为查明真相，雷恩开始追查。然而，雷恩发现其好友居然与哥伦比亚贩毒团有染，不仅如此，总统也派出了一支秘密突击小组对付毒贩集团，并已前往消灭贩毒集团。不明真相的雷恩，不仅置身于利益纷争的国际政治阴谋之中，更陷入敌友难辨的两难之境。事态演变得愈发扑朔迷离，被蒙在鼓里的雷恩势要以身试险，一探究竟。本片根据汤姆·克兰西的畅销小说改编而成，是《爱国者游戏》的续集。©豆瓣', '哈里森·福特', '菲利普·诺伊斯', 7.1, 5329, 'tt0109444', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1285227765.jpg', 0.6, 3.8, 44.2, 41.5, 10, '0.125349,-0.093548,-0.473553,0.422282,0.285680,-0.024421,0.333969,0.120531,-0.596276,-0.433935,0.212049,0.521175,-0.118749,-0.167333,0.495629,-0.162608,-0.372650,-0.707298,-0.209668,0.058691,-0.001892,-0.768309,-0.555790,-0.276315,0.160124,-0.128561,0.928699,0.276748,-0.337621,0.065645,0.332471,0.717475,-0.403611,0.254791,0.339947,-0.004281,0.490336,-0.415214,-0.597693,0.138359,-0.133027,-0.357396,-0.057059,-0.031132,-0.110117,0.359707,0.460806,-0.347803,0.098109,-0.481403,0.331042,-0.484539,-0.003062,-0.103642,0.706947,0.285472,0.066352,0.439807,-0.209820,0.032591,0.127450,0.007183,-0.694247,0.228514,0.217283,0.293093,-0.057531,-0.275285,-0.427404,0.266878,-0.011216,0.127727,0.149993,0.773504,0.440372,0.090013,0.009884,0.060198,-0.537340,0.041441,0.665588,-0.119781,-0.234682,-0.258021,0.119613,-0.273415,0.120266,-0.441876,-0.007542,-0.032269,0.333182,-0.209274,0.150245,0.861488,-0.318676,-0.283653,-0.573868,-0.183652,-0.185934,-0.234114,0.083115,-0.687255,-0.395566,0.253403,0.046448,-0.129657,0.255771,-0.111002,0.043986,-0.510997,-0.007176,0.442336,-0.058932,-0.577573,0.171228,0.260926,0.118745,-0.201968,-0.383838,0.270892,0.514206,0.150865,0.024018,-0.138684,0.075645,-0.422167,-0.039219,-0.281238', '10437779', '2028647', '3562446', '1305096');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292827', '肥佬教授', '喜剧', '超级大胖子金斯教授（艾迪•墨菲 Eddie Murphy 饰演）虽然学术高明，心地善良，但因为体型问题一直成为大家的笑柄。直到有一天，金斯教授发现自己研制的新药成功了，这种药水能改变小白鼠的DNA，使其体重减轻，似乎金斯教授就要迎来自己的新生活了。金斯教授一直钟情于化学教员的卡洛小姐（贾达•萍克•史密斯 Jada Pinkett Smith 饰），一次约她到俱乐部吃饭时，金斯教授又因为体型问题被主持人瑞基嘲笑而令他在女伴面前抬不起头。回去以后，金斯教授决定喝下自己研制的新药。喝下药水后，奇迹发生了，金斯教授变成了放荡无耻、阴险狡猾的瘦子毕地。幸好药水时效有限，一定时间后毕地又变回了金斯教授。为了在卡洛面前抬得起头，金斯教授一次又一次的喝下了药水……©豆瓣', '艾迪·墨菲', '汤姆·沙迪亚克', 6.3, 8126, 'tt0117218', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2324580300.jpg', 2.1, 10, 62.9, 20.7, 4.3, '0.187687,0.047765,-0.032218,0.036647,0.046523,-0.657609,0.490867,-0.027347,-0.390970,-0.491749,0.046982,0.444407,-0.417239,-0.069756,0.197696,-0.048981,-0.175097,-0.466004,0.287080,-0.215567,-0.230017,-0.392757,-0.216187,-0.288144,0.148954,-0.582534,0.227277,-0.502167,-0.068418,0.395111,-0.109301,0.054616,0.615582,0.253106,0.275352,0.098780,0.394244,-0.312152,-0.111183,0.359711,0.760151,-0.049651,-0.135618,0.002834,0.297595,0.074485,0.402141,-0.176628,-0.418427,-0.170424,0.270107,-0.147435,-0.060834,0.039451,0.258169,-0.136217,0.106651,0.232905,0.019991,-0.185617,0.047662,0.126219,-0.499017,0.091439,-0.308050,0.242810,-0.576998,0.333527,-0.131997,0.173054,-0.233104,-0.429963,-0.180481,0.012790,0.466319,0.288602,-0.040636,0.153763,-0.334679,0.041567,0.424204,0.173199,-0.323165,0.436270,-0.079966,-0.556229,0.025323,-0.460953,-0.481205,0.225914,0.141171,0.114073,-0.029438,0.332985,-0.350764,-0.219327,-0.814055,-0.028290,0.157055,0.067165,-0.273738,-0.245147,-0.099173,-0.053150,-0.137531,-0.243563,0.133298,-0.377883,0.572050,-0.677643,0.286621,0.497015,-0.048485,-0.006448,0.291303,0.098106,0.041547,-0.367974,-0.130430,-0.270555,-0.051870,0.526553,0.221412,0.504222,0.351233,-0.380059,-0.230420,0.318262', '26593587', '1858678', '1877596', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292829', '神探飞机头', '喜剧', '王牌•威龙（金•凯瑞 饰）是一位专与动物打交道的宠物侦探，以帮人寻找丢失的宠物为生。在橄榄球大赛即将来临时，迈阿密海豚队的吉祥物——海豚“雪花”遭到了绑架。这无疑会大大影响到队员们的士气。无奈之下，球队经济人麦提莎小姐找来了王牌•威龙以找回失去的海豚。王牌•威龙用自己的方式对事件展开了彻底的调查，虽然期间笑料不断，时时受到女警官艾露丝的阻挠，但也找到了很多的线索，麦提莎小姐也逐渐被他的风趣与机敏所打动，开始对他刮目相看。就在王牌侦查工作慢慢接近事实真相的时候，海豚队的另一个经纪人普罗杰在家中跳楼自杀，队员马连奴又被绑架了，好不容易锁定的犯罪嫌疑人也神秘失踪了，案情更加的扑朔迷离。©豆瓣', '金·凯瑞', '汤姆·沙迪亚克', 7.4, 40112, 'tt0109040', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2134987523.jpg', 0.7, 3.8, 36.8, 43.4, 15.3, '0.202500,0.120932,-0.443309,0.621271,0.031152,-0.138775,0.572071,-0.029301,-0.527767,-0.186752,0.319916,0.592927,-0.130467,0.052880,0.246818,-0.186835,-0.218180,-0.773998,-0.018901,0.043623,-0.344704,-0.495821,-0.335189,-0.122529,0.105105,-0.343129,0.549720,0.105129,-0.381218,0.449920,0.342050,0.456863,0.101154,0.413025,-0.092935,0.089027,0.272050,-0.171486,0.043028,0.214609,0.122170,-0.313399,0.038325,0.225728,0.097286,0.319606,0.916360,-0.416743,-0.265798,-0.111509,0.252203,-0.408650,0.163645,-0.022651,0.588649,0.033461,0.044707,0.078215,-0.215620,0.082016,-0.020024,0.113420,-0.850485,-0.039338,0.195862,0.172229,-0.645331,0.201359,-0.134624,0.072186,0.190320,-0.140402,0.180620,0.256443,0.053951,0.122767,-0.122114,0.065738,-0.489801,0.066775,0.568286,-0.014744,-0.182230,0.141065,-0.230946,-0.486815,0.057777,-0.438788,-0.218902,-0.062611,0.480229,-0.069961,-0.057131,0.212330,-0.813750,-0.112259,-0.327797,-0.365291,-0.201692,-0.577945,-0.001210,-0.655600,-0.010840,-0.249550,-0.067788,0.248682,0.063498,-0.300748,0.868079,-1.061238,0.197682,0.750389,-0.062123,-0.533610,0.254381,-0.133717,0.090906,-0.319952,-0.297359,-0.085445,0.267062,0.472855,0.275438,0.279894,-0.052433,-0.450653,-0.268720,0.400649', '1420088', '4127270', '25774050', '3044878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292831', '巧克力情人', '剧情', '拉丁美洲的作品常常带着魔幻荒诞的色彩，影片故事正是发生在这里的墨西哥。艾莲娜是一个抚养三个女儿的寡妇，她的小女儿蒂娜（卢米·卡范佐斯 Lumi Cavazos饰）和青年佩德罗（马克·莱昂纳蒂 Marco Leonardi饰）相爱，但母亲却按照家族规矩，要把大女儿柔沙嫁给佩德罗，同时声明蒂娜要照顾自己直到归西。佩德罗和柔沙结婚了。婚礼上，他向蒂娜吐露爱意，让蒂娜更加心伤。她的眼泪簌簌掉下，落到正在制作的菜肴上，于是，客人们竟然尝出了苦味。从此，蒂娜把自己压抑的爱意都融合在烹饪中，一家人的情绪竟随着她的烹饪心情或情欲高涨，或压抑阴沉。当蒂娜终于等来和佩德罗相守的日子，压抑已久的感情却化成了熊熊燃烧的烈火。©豆瓣', '马克·莱昂纳蒂', '阿方索·阿雷奥', 7.5, 5033, 'tt0103994', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2387037811.jpg', 1.1, 3.3, 33.9, 44.1, 17.6, '0.180973,0.208055,-0.616654,0.650626,-0.017178,-0.609626,0.946827,0.222925,-0.310490,0.079271,0.069559,0.481442,-0.340730,0.439878,0.125850,0.143712,-0.497356,-0.929715,-0.083471,-0.073651,-0.085549,-0.305347,0.007405,-0.062693,-0.042398,-0.211338,0.500057,-0.078669,0.042406,0.234377,0.368430,0.176326,-0.146088,0.445441,-0.057543,0.010221,0.036603,-0.064000,-0.277305,-0.015846,0.331897,-0.144290,-0.177978,0.083504,0.030369,0.402456,0.554878,-0.231987,0.187993,-0.038884,0.158074,-0.101801,0.297329,0.334650,-0.358724,-0.113223,0.153485,0.180841,-0.280358,0.036501,0.060105,0.016955,-0.598324,0.212011,0.094620,0.234598,-0.678470,0.375802,-0.155814,-0.063658,0.149623,-0.331937,0.052542,0.063186,0.098642,0.661688,-0.219366,0.098736,-0.384612,0.119340,0.521146,-0.112080,-0.094141,0.286003,-0.498796,-0.246730,0.017393,-0.014871,-0.596767,-0.222396,0.360737,0.314247,-0.010882,0.569240,-0.708518,-0.230966,-0.202573,-0.309387,0.109550,-0.230411,-0.063773,-0.500563,-0.118405,-0.210810,-0.471726,-0.187586,0.249509,-0.046350,0.794276,-0.432259,0.370416,0.322393,0.249648,-0.241920,0.367267,0.107237,-0.013199,0.081652,-0.104249,0.426340,-0.268548,-0.125934,0.256017,0.590092,-0.093105,0.280156,-0.440543,0.833866', '1307146', '26677495', '1293399', '1301464');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292834', '十万火急', '动作', '这天无数往来于曼哈顿与新泽西州的海底隧道的美国民众像往常一样在隧道内抱怨着交通堵塞，岂料死神正在步步逼近。隧道内一辆装满化学物品的卡车意外发生了爆炸，强大的冲击力使得隧道坍塌了，出入口都被堵死了。此时，隧道内一片火海，弥漫着有毒烟雾，河水也在不断涌进，无数无辜的市民们能做似乎只有等死。救援队其实早到了，然而隧道被封，里面的有毒烟雾肆虐，救援人员迟迟不敢贸然动手。十万火急之际，出租车司机、前救援队队员骆查（西尔维斯特•史泰龙 Sylvester Stallone 饰）挺身而出了。他从通风口爬进了隧道，他稳定住了隧道内众人的情绪，带领大家开始了生死逃亡。©豆瓣', '西尔维斯特·史泰龙', '罗伯·科恩', 7.3, 6067, 'tt0116040', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2320452962.jpg', 0.6, 2.6, 41, 43.6, 12.3, '0.197832,0.075609,-0.893772,0.172193,0.464253,0.207233,0.987497,0.116981,-0.682719,0.071606,0.175764,0.336190,-0.372023,-0.136044,-0.155324,-0.284377,-0.419703,-0.476249,-0.519750,-0.372442,-0.464261,-0.116330,-0.092538,-0.067688,0.038506,-0.366948,0.411868,0.502598,0.056487,0.261095,-0.021201,-0.040190,-0.378284,0.663887,-0.090208,-0.076796,0.100436,-0.282945,0.011007,-0.019260,-0.354413,-0.366895,0.182565,0.018304,0.129590,0.518173,0.653588,-0.251869,0.044261,0.194330,0.047987,-0.475339,0.083889,0.293839,0.307384,0.122695,0.023236,-0.180786,-0.105887,0.186618,-0.064218,-0.043264,-0.094206,-0.048076,-0.408473,0.207094,-0.555417,0.104902,0.137487,-0.172497,-0.004050,-0.334713,0.315761,-0.170666,-0.033653,0.208541,-0.386271,-0.175282,-0.745718,-0.144809,0.707036,-0.178791,-0.487113,0.334934,-0.275481,-0.263588,-0.174342,0.284377,-0.388625,-0.350831,0.825205,0.213403,-0.342428,0.167498,-0.438519,0.098646,-0.263840,-0.453869,-0.475604,0.021951,-0.580796,-0.716935,0.141763,0.023474,0.179799,0.407069,-0.468800,0.387583,0.079227,-0.281497,0.321465,0.525177,0.189201,-0.162774,0.537122,-0.320331,0.162128,0.257884,0.153292,0.118627,0.097409,1.003687,0.355014,0.544915,-0.384713,-0.208900,-0.505693,-0.104482', '3011051', '20451118', '1304129', '3268171');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292836', '我仍然知道你去年夏天干了什么', '悬疑', '本片为1997年《我知道你去年夏天乾了什么》(I Know What You Did Last Summer)的续集，制作人采用原班人马。 本片延续了第一集的故事结尾，两年前茱莉（詹妮弗·洛夫·休伊特 Jennifer Love Hewitt 饰）和朋友们开车撞死了一个 路人后众人遭到“铁钩杀手”的报复。最后茱莉虽然得以生还，但这团阴影却始终笼罩着她。 两年后，茱莉的好友卡拉赢得了电台的猜奖，卡拉及其男友泰洛要请茱莉与同班同学维尔，四人一同前往巴哈马的塔湾岛度假。就在享受阳光沙滩的同时，一连串的离奇事件也在这个孤岛上展开，旅馆里的工作人员也不明原因的接二连三死亡。茱莉收到“I Still Know What You Did Last Summer”的警告，众人惊恐万分。难道是“铁钩杀手”死而复生？这一次凶手是谁？冷酷的杀手正在等待着他们……©豆瓣', '詹妮弗·洛芙·休伊特', 'Danny Cannon', 5.9, 6821, 'tt0130018', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178451936.jpg', 4.1, 19.3, 57.8, 14.3, 4.5, '0.183895,-0.264803,-0.652842,0.670552,-0.009087,-0.117621,0.674348,0.095318,-0.606013,-0.110958,0.475043,0.752813,-0.372431,0.205068,0.354970,0.193832,-0.419276,-0.561532,-0.027315,-0.230144,-0.278646,-0.336182,-0.287389,-0.060012,0.117180,-0.086043,0.503388,0.163962,0.060907,0.557431,0.421529,0.152955,-0.192579,0.452009,0.059613,0.139860,0.122232,-0.152045,-0.136911,0.162948,-0.041047,-0.447059,-0.251074,0.182392,0.014868,0.527065,0.591145,-0.205023,-0.051600,0.073512,0.242323,-0.551786,-0.118856,0.112579,0.311461,-0.234467,0.253966,0.354879,-0.053905,-0.201138,-0.158131,0.083114,-0.680159,0.175808,-0.161103,0.210061,-0.591320,0.525121,-0.128631,0.006849,0.042382,-0.166718,0.212194,0.269298,0.115168,0.227084,-0.331356,-0.192602,-0.369778,0.220608,0.595632,-0.018749,-0.181945,0.231072,-0.043923,-0.463648,-0.222717,-0.007299,-0.495433,0.087740,0.395432,0.074097,-0.373253,0.075683,-0.648891,-0.092589,-0.238896,-0.301795,-0.101486,-0.370620,-0.304170,-0.805713,0.059851,-0.210465,-0.280123,0.009263,-0.002344,-0.148256,0.606692,-0.768408,0.290599,0.447344,0.212161,-0.257143,0.511236,0.075578,0.103706,-0.032695,-0.176509,0.020388,0.193148,0.267403,0.205455,0.393561,0.042669,-0.157646,-0.366084,0.308517', 