INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292840', '费城故事', '喜剧', '费城的富家千金Tracy Samantha（凯瑟琳·赫本 Katharine Hepburn饰）和丈夫C. K. Dexter Haven（加里·格兰特 Cary Grant饰）离婚了。最近，她准备嫁给一个德高望重的人George Kittredge（John Howard饰）。为了报道这场盛大的婚礼，SPY杂志的记者Macaulay "Mike" Connor (詹姆斯·斯图尔特 James Stewart饰）和摄影师Liz Imbrie（露丝·赫希 Ruth Hussey饰）费尽心思混入Tracy家中。此时，Dexter也来到了Tracy家中要来参加她的婚礼，受到了Tracy妹妹的极大欢迎。在相处中，Tracy也和记者Mike发生了不同寻常的情愫。她发现自己处在三个男人之间，这场婚礼也陷入了悬念。到底Tracy最后到底会嫁给谁，是她的未婚夫，是她的前夫，还是那名记者呢？本片获1940年奥斯卡六项提名，其中，詹姆斯·斯图尔特获最佳男主角奖，编剧Donald Ogden Stewart 获最佳剧本奖。', '加里·格兰特', '乔治·库克', 7.5, 7449, 'tt0032904', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p740274403.jpg', 0.6, 3.3, 34.5, 44.9, 16.7, '-0.036190,-0.137253,-0.584780,0.291481,-0.002983,-0.028777,0.655912,0.007140,-0.558240,-0.245969,0.209233,0.942365,-0.519093,0.270209,0.551923,0.006358,-0.428061,-0.830068,-0.057724,-0.050796,-0.109392,-0.381912,-0.209402,-0.093555,0.076401,-0.217231,0.442625,-0.100151,0.027559,0.446115,0.788150,0.160584,0.072717,0.280795,0.137002,0.214561,0.335272,0.003311,-0.279497,0.445554,0.059078,-0.262536,-0.275867,0.276551,0.241168,0.318831,0.513772,0.102471,0.155048,0.014297,0.438530,-0.207737,0.094698,0.211465,0.258743,-0.195022,0.373391,0.309880,-0.028323,-0.016303,0.175583,-0.183922,-0.385105,0.375880,0.298603,0.281949,-0.587140,0.602717,-0.182236,-0.024561,-0.131978,-0.086877,0.275091,0.392100,0.194232,0.039256,0.048288,-0.033340,-0.406119,0.513982,0.779417,0.173256,0.173343,0.216649,-0.309612,-0.588780,-0.167823,-0.231021,-0.712024,0.300325,0.402743,0.040164,0.072453,0.205249,-0.253135,-0.201700,-0.075546,-0.025909,-0.079924,-0.446725,0.133657,-0.561825,-0.168091,-0.135647,-0.219559,-0.023340,0.019233,-0.186457,0.640310,-0.635324,0.218730,0.532766,0.414973,-0.484026,0.789634,0.396839,0.178949,-0.142734,-0.154195,-0.236378,-0.264216,-0.111857,-0.146727,0.218376,0.197342,-0.425399,-0.153388,0.229684', '30162520', '30353869', '1829654', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292843', '黄飞鸿之西域雄狮', '动作', '黄飞鸿（李连杰 饰），十三姨（关之琳 饰）和鬼脚七（熊欣欣 饰）三人远赴美国旧金山，只因一年前牙擦苏（陈国邦 饰）在美国开设宝芝林至今终于扎下了脚跟。黄飞鸿于路搭救了落难的美国快枪手比利（Jeff Wolfe 饰），不想他们的旅队被林中埋伏的印第安人冲散，黄飞鸿为救十三姨落入湍急河流，头部受撞击后下落不明。十三姨和鬼脚七被人救起送至宝芝林，牙擦苏得见二人大喜过望，为这华工颇受镇长欺侮的小镇生活增添了生机。比利因出众的枪法受雇为助理治安官，对华人颇有好感的比利凭一己之力予以华工帮助。失去记忆的黄飞鸿被印第安人部落收留，因十三姨坚持不懈的寻找二人终于团聚。与此同时，镇长与匪帮勾结为自己牟取暴利，事发后撇开匪帮导致后者大举报复，被镇长栽赃的黄飞鸿挺身而出，大战西部群匪……©豆瓣', '李连杰', '洪金宝', 7, 42028, 'tt0120530', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2221508135.jpg', 0.5, 5, 47.8, 35.4, 11.4, '0.059771,-0.188174,-0.465544,0.404506,0.169447,-0.347204,0.517138,0.204891,-0.398715,-0.264534,0.172936,0.521933,-0.063250,-0.153643,0.081479,-0.237405,0.062729,-0.658663,-0.027876,0.114296,-0.187365,-0.110798,-0.192822,-0.150364,-0.341855,-0.269423,0.341497,0.187743,-0.294603,0.648823,0.156705,0.455962,-0.163641,0.075726,-0.249613,0.250814,-0.094925,-0.126545,-0.340660,0.178681,-0.103751,-0.420687,0.026354,-0.020950,-0.176104,0.566453,0.654903,0.075947,0.055408,-0.534105,0.045541,-0.327750,0.138049,0.093697,0.361601,-0.041017,0.098577,0.065617,-0.220795,-0.112803,0.270539,-0.097911,-0.536336,0.158941,0.183725,-0.146591,-0.645294,0.261524,-0.111986,-0.084385,-0.095428,-0.177328,0.144532,0.402620,0.208617,0.152363,0.066385,0.171441,-0.455089,0.065008,0.499675,-0.330419,0.202801,-0.076125,0.059622,-0.339523,0.256994,-0.283683,-0.047529,-0.085921,0.315744,-0.131988,-0.053213,0.069675,-0.433141,-0.227059,-0.442750,-0.089607,-0.077290,-0.116524,-0.099368,-0.432895,-0.166750,-0.181769,0.050045,0.065102,0.218492,0.037773,0.326627,-0.594235,0.193809,0.287153,0.323745,-0.548996,0.396724,0.116014,0.046577,-0.154946,-0.058490,0.188647,0.229056,0.287938,0.430150,-0.017167,-0.295446,-0.235094,-0.236000,0.069407', '1301022', '25908042', '1451563', '3621404');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292845', '007之雷霆杀机', '动作', '这次，007（罗杰•摩尔 Roger Moore 饰）在西伯利亚死亡的英国特工身上找到了科技秘密“微晶硒”之后，发现这个样品与英国的样品一样，证明克格勃的间谍肯定混进了英国的高科技研究秘密领域。于是，007奉命去调查在进行高科技研究的富商佐林（克里斯托弗•沃肯 Chri stopher Walken 饰）。不料他的身份被人识破，007被锁入车中沉进湖底。幸亏命运之神帮了007一个大忙，他得以侥幸逃脱。随后，007跟踪佐林来到了美国。007从苏联女间谍口中套出佐林正计划炸毁位于旧金山的硒矿的计划。为了阻止佐林的阴谋得逞，007行动开始了！©豆瓣', '罗杰·摩尔', '约翰·格兰', 6.9, 7563, 'tt0090264', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1729394637.jpg', 0.9, 5, 53.3, 30.5, 10.3, '0.321474,0.192136,-0.672413,0.358849,-0.190445,-0.185592,0.265307,-0.164259,-0.578089,-0.231464,0.167456,0.523139,0.065953,-0.149991,0.158736,0.146339,-0.683628,-0.513232,0.038581,-0.364271,-0.442915,-0.491030,-0.535510,-0.242778,0.213804,-0.338210,0.545425,0.398781,-0.352722,0.115816,0.210310,0.339379,-0.247382,0.377713,-0.128722,-0.122468,0.386610,-0.406333,-0.296640,0.532392,-0.026138,-0.405046,0.037135,0.234603,-0.029380,0.474198,0.427743,-0.220142,0.081540,-0.236443,0.156628,-0.478624,-0.029064,0.097678,0.228120,0.237724,-0.217243,0.209754,-0.315072,0.171947,0.344757,0.001821,-0.744412,0.005859,0.049297,0.122785,-0.533994,-0.055450,-0.322434,0.097709,-0.195249,-0.393025,0.326600,0.516004,0.311368,0.158800,-0.098019,0.395015,-0.748933,0.005704,0.391488,-0.440744,0.160749,0.074763,0.191450,-0.354538,0.119296,-0.107805,0.216990,-0.097477,0.590613,-0.050148,-0.331288,-0.007368,-0.670407,-0.243177,-0.538908,-0.106647,0.028466,-0.243846,-0.025129,-0.803795,-0.290122,0.187210,-0.132110,0.123995,0.034667,-0.212161,0.288235,-0.577275,0.054597,0.690793,0.267037,-0.396393,0.234423,-0.090669,-0.016864,-0.352703,-0.038470,0.186735,0.236072,0.607941,-0.032700,0.444487,0.177732,-0.602218,-0.321751,-0.143061', '1292573', '2973528', '1307442', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292846', '省港旗兵', '动作', '何耀东（林威 饰）是文革后偷渡香港的新移民，在港期间他犯下多宗刑事案件，为全港警方所通缉。大东返回大陆，召集打靶仔（蓝湘森 饰）、乌蝇头（方烈 饰）、八中（江龙 饰）、生鸡（陈敬 饰）、肥姑（黄健 饰）等一干穷哥们，商议赴港抢劫银楼。然而他们出师不利，打靶仔在穿越边境时 被巡逻兵击毙。余下五人按原计划行事，到达目的地时却发现银楼铁门关闭。原来此前早有一独行大盗光顾此地，被警方现场拿下。大东等人心存不甘，驱车在周围逡巡，引起警方察觉。一番激烈追逐，大东等方脱离险境。为了一夜暴富的梦想，他们决定继续留港，伺机行动，却因此走上一条不归途……©豆瓣', '陈敬', '麦当雄', 7.9, 16777, 'tt0088107', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2222923960.jpg', 0.4, 1.5, 22.9, 52, 23.1, '0.057790,-0.023550,-0.740361,0.047646,0.450565,-0.031904,0.181203,-0.000421,-0.555954,-0.245475,0.185934,0.363210,-0.408006,-0.078962,0.181017,-0.176787,-0.596046,-0.494300,0.103617,-0.185639,-0.046801,-0.116091,-0.058040,-0.099623,-0.092531,0.115229,0.368512,0.599502,-0.137959,0.670866,0.121382,0.051266,-0.455728,0.430697,0.008066,-0.183423,0.310069,-0.096328,-0.263751,0.223358,-0.363096,-0.265072,-0.220036,-0.057964,0.066885,0.425204,0.809638,0.073892,-0.198970,-0.097331,-0.106498,-0.424100,0.021397,-0.012491,0.538109,0.100679,-0.024731,0.291518,-0.435267,-0.104302,-0.223070,0.028047,-0.123397,0.071208,0.090466,0.004598,-0.315539,-0.056031,-0.304635,0.299866,-0.008276,-0.303889,0.112950,0.616877,0.393784,-0.035615,0.262637,0.091947,-0.385775,0.142485,0.812209,-0.261820,0.192310,-0.298559,0.317183,-0.276807,0.206674,0.131180,0.126314,-0.277246,0.356529,-0.013055,-0.017176,-0.158435,-0.310676,-0.091640,-0.564258,-0.225531,0.066265,-0.048703,-0.260254,-0.948306,0.290035,-0.026292,-0.170688,0.440892,0.143734,0.128340,0.084284,-0.488076,0.169407,0.457747,0.340124,-0.620459,0.463820,-0.180127,0.019887,-0.327762,0.026826,0.015289,0.231937,0.439272,0.136232,-0.055796,-0.186985,-0.407027,-0.205778,-0.019446', '1305179', '3871833', '35287558', '6007281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292849', '拯救大兵瑞恩', '剧情', '瑞恩（马特•达蒙 Matt Damon饰 ）是二战期间的美国伞兵，被困在了敌人后方。更不幸的是，他的三个兄弟全部在战争中死亡，如果他也遇难，家中的老母亲将无依无靠。美国作战总指挥部知道了这个情况，毅然决定组织一个小分队前往救援，其中包括米勒上尉（汤姆•汉克斯 Tom Hanks 饰 ）和翻译厄本（杰里米.戴维斯 Jererry Davies饰）。然而，敌方危险重重，他们一路上随时与死亡打交道。他们非常怀疑，到底值不值得冒着八个人的生命危险，去搭救一个人。大家一路辗转寻找瑞恩，对于这次搭救行动，有人不满，有人热忱，有人好奇。大家一次次闻到死神的气息，瑞恩的获救付出了沉重的代价。©豆瓣', '汤姆·汉克斯', '史蒂文·斯皮尔伯格', 9.1, 605319, 'tt0120815', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1014542496.jpg', 0.2, 0.4, 6.2, 33.1, 60.2, '0.156703,-0.118620,-0.828956,0.316405,0.034259,-0.090099,0.614596,-0.252931,-0.533468,-0.264416,0.434425,0.859696,0.237906,0.087509,0.045949,-0.017148,-0.320569,-0.443938,-0.104568,0.013504,-0.438452,-0.432303,-0.308643,-0.530616,-0.110804,-0.261738,0.367173,0.211843,-0.099464,0.649639,0.360417,0.448295,-0.171406,0.707003,0.058408,0.011142,0.291869,-0.411826,-0.192407,0.180089,-0.052760,-0.169811,-0.242899,0.177905,0.028052,0.477194,0.504169,-0.262094,-0.053598,0.030952,0.074631,-0.500534,0.184067,0.246545,0.374356,-0.076811,0.062552,0.341248,-0.057615,0.059038,-0.203341,0.096975,-0.763185,-0.010747,-0.021541,0.411612,-0.710780,0.039199,-0.105467,0.099682,0.196632,-0.189069,0.124073,0.452679,0.056628,-0.067709,-0.272414,-0.260789,-0.563456,-0.106542,0.919534,-0.311311,-0.061834,-0.052008,-0.149621,-0.374183,-0.103809,0.023370,-0.531601,0.238297,0.368921,-0.010680,-0.085004,0.084718,-0.548013,0.236462,-0.298853,-0.292929,-0.394762,-0.260186,0.034738,-0.755514,-0.047459,-0.131242,-0.441742,0.141473,0.045914,0.017555,0.745005,-0.508235,0.076878,0.844544,0.197516,-0.501961,0.463254,0.118089,0.028652,-0.260912,0.002721,0.316420,0.131743,0.092917,0.231764,0.258341,0.105617,-0.053332,-0.103622,0.084162', '1294941', '3147969', '1306723', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292850', '危情十日', '剧情', '畅销书作家保罗•谢尔顿（詹姆斯•凯恩 James Caan 饰）带着他的最新作品《米瑟莉》驱车走在回家的路上。途中他遭遇了可怕的暴风雪，轿车发生侧翻事故，保罗的双腿严重受伤，幸好被独居在附近山顶的护士安妮•威尔克斯（凯西•贝茨 Kathy Bates 饰）及时相救。安妮是保罗的头号书迷，在她的悉心照顾下，保罗的伤势日渐好转。但当她获悉喜爱的女主人公在保罗的新书中已经死亡，却难以遏制心中的怒火，通过各种手段向保罗施加报复，逐渐将作家逼向了绝望……影片根据恐怖小说大师斯蒂芬•金的同名小说改编，女主角凯西•贝茨凭借此片中的疯狂又反复无常的表演，成功斩获了第63届奥斯卡的最佳女演员奖。©豆瓣', '詹姆斯·肯恩', '罗伯·莱纳', 8.4, 68626, 'tt0100157', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1217959104.jpg', 0.2, 0.6, 11.7, 52, 35.5, '0.141497,0.036669,-0.617300,0.527167,0.254420,-0.196002,0.680582,0.192802,-0.342561,-0.021913,0.494391,0.640468,-0.374057,0.188825,0.253117,-0.025463,-0.307776,-0.546577,-0.104598,0.077314,-0.254072,-0.272434,-0.506468,-0.063230,0.095658,-0.609182,0.489820,0.108661,-0.290490,0.472195,0.314689,0.352544,0.069455,0.410464,0.034029,0.379336,0.223067,-0.345167,-0.116926,0.408238,0.376469,-0.616240,-0.059341,0.218532,0.000362,0.406381,0.725532,-0.109236,-0.122078,0.191730,0.733560,-0.244247,0.170493,0.131187,0.213112,0.018705,0.100676,-0.016531,0.004293,0.111961,-0.125666,0.042030,-0.784852,0.084798,0.126032,0.178630,-0.732916,0.335653,-0.406528,0.229053,0.085354,-0.229100,-0.018942,0.086632,0.058818,0.147044,-0.052603,0.087142,-0.220440,0.300744,0.197989,0.099910,-0.349645,0.208183,-0.329570,-0.269820,0.080019,-0.122251,-0.507478,-0.036754,0.830461,0.113503,-0.145136,0.234386,-0.212047,-0.073538,-0.374310,-0.232962,-0.357843,-0.060004,-0.114084,-0.890383,-0.080397,-0.121897,-0.013661,-0.351700,-0.021537,-0.298864,0.760850,-0.402186,0.414425,0.716383,0.159677,-0.119646,0.481063,-0.034981,-0.017644,0.205660,-0.223213,0.292493,-0.171146,0.386542,0.286916,0.487287,0.068625,-0.244640,-0.391623,0.688558', '3318306', '6874567', '2027945', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292864', '初吻2', '喜剧', '由《初吻》的原班人马拍摄的续集。小薇长大了两岁，较前成熟，她在旅游返家途中因调换护照而认识了一个中学生，两人逐渐发生了感情。与此同时，小薇的父母各自发展事业，曾祖母也有了第二春，婷婷玉立的小薇面临是否要初尝禁果的抉择……', '苏菲·玛索', '克洛德·皮诺托', 7.7, 31316, 'tt0083686', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p860227390.jpg', 0.3, 2.4, 31.2, 45.2, 21, '0.215814,-0.265435,-0.743445,0.237515,0.107842,-0.402606,0.386372,0.519381,-0.242176,-0.261922,0.074122,0.550058,-0.102967,0.267399,0.209435,-0.237018,-0.101218,-0.716936,0.145567,-0.057177,-0.237829,-0.154960,0.111714,0.293046,0.051887,-0.054930,0.684294,-0.031673,0.109436,0.478176,0.244938,-0.296784,-0.115586,0.121405,-0.100892,0.241646,0.098038,0.365609,-0.427848,0.404550,0.137372,-0.311178,0.240709,-0.259665,0.072075,0.699428,1.011407,0.124381,-0.276981,-0.122073,0.669281,-0.021899,-0.195095,0.259060,0.364055,0.180379,-0.327168,0.016801,-0.277138,-0.038503,-0.224357,-0.243001,-0.551721,-0.054118,0.245748,0.224019,-0.682214,0.556147,-0.084398,-0.098417,0.210992,-0.229523,0.177799,1.053132,0.083778,0.340778,0.066623,-0.093142,-0.303654,0.367976,0.850776,0.038293,-0.132213,0.767028,-0.426450,-0.329695,-0.089906,-0.087041,-0.448726,0.199927,0.289410,0.120587,-0.349795,0.306558,-0.441290,-0.073920,-0.205895,-0.101923,0.043601,-0.469253,0.074180,-0.563348,-0.386264,-0.613937,-0.195183,-0.096577,-0.018176,-0.147514,0.980328,-0.787727,0.002038,0.614054,0.336014,-0.930579,0.440051,0.324724,0.255133,-0.527487,0.570040,0.306656,-0.538310,-0.050355,0.027944,0.214108,0.016170,0.059403,-0.516423,0.108974', '3811356', '3078390', '25922902', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292867', '快餐车', '喜剧', '无比（洪金宝 饰）是巴塞罗那一间侦探社的打手，这天，他的侦探社接到了一单大生意：客人委托他们14天内找到一名叫歌利亚的女子和她的女儿施维亚。因为侦探社的社长侦探在外躲债，而无比又不想眼白白丢了一单生意，于是，他找来在当地经营快餐车的华人青年托马斯（成龙 饰）与大卫（元彪 饰）一起进行调查。通过调查，他们发现歌利亚原来是当地一名富豪伯爵的千金，伯爵已经去世，如果找不到她或者她女儿的话巨额的遗产将落入她的堂兄的口袋，而他们幕后雇主正是这位心怀叵测的堂兄！于是，一幕英雄救美的好戏上演了！©豆瓣', '成龙', '洪金宝', 7.8, 67106, 'tt0087578', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1417360174.jpg', 0.2, 1.5, 26.2, 49.8, 22.2, '0.203777,-0.262899,-0.379398,0.557309,-0.172076,-0.421672,0.568155,0.238356,-0.647822,-0.310764,0.247439,0.938663,-0.052394,0.374515,0.420343,0.424025,-0.156051,-0.535175,-0.069985,-0.177511,0.075345,-0.407946,-0.265304,-0.269107,0.008158,-0.034447,0.344245,-0.035187,-0.079605,0.327925,0.419218,0.248400,0.053486,0.376773,-0.125036,0.110123,0.182384,-0.123962,-0.218884,0.394697,0.198020,-0.187464,-0.281829,0.144424,0.150507,0.539984,0.471203,-0.088997,0.030301,-0.263372,0.264702,-0.285917,0.122424,-0.123535,0.321608,-0.060875,0.462802,0.250273,-0.502681,-0.236385,0.201927,-0.020456,-0.588393,0.245793,0.124120,0.201142,-0.615942,0.247698,-0.317341,-0.001189,-0.096781,-0.436639,0.175246,0.309803,0.083365,0.098656,-0.047405,0.054369,-0.711158,0.317408,0.464815,-0.014883,0.181218,0.353847,0.075116,-0.425979,-0.038908,-0.244103,-0.523689,0.081406,0.529614,-0.244868,-0.024392,-0.048207,-0.531959,-0.340396,-0.418246,-0.332284,0.045241,-0.308396,-0.186495,-0.738056,-0.156875,0.049069,-0.145071,0.024001,0.301242,-0.080701,0.456247,-0.632111,-0.220324,0.527334,0.157271,-0.504814,0.599948,-0.214964,0.114678,-0.235810,-0.321796,-0.386747,0.351541,0.360436,0.291374,0.143993,0.138224,-0.390426,-0.041176,0.175083', '26678509', '1829654', '1297418', '3718493');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292869', '月色撩人', '剧情', '纽约布鲁克林，有一个意大利家庭，每到月圆之夜，他们仿佛被施了魔法，会做出一些莫名其妙的举动。洛丽塔·卡斯托里尼（雪儿 Cher 饰）是家里的独女，年轻貌美，是公司里的会计师。因为前夫遭遇车祸，而成了寡妇。某晚，在酒馆里，洛丽塔目睹了邻桌分手的惨 剧，仿佛受了刺激，决定跟41岁的单身汉强尼结婚。她让强尼用尾戒求婚，于是众目睽睽之下喜结连理。不过，因为母亲病重，强尼离开了纽约，临走时让她邀请弟弟罗尼（尼古拉斯·凯奇 Nicolas Cage 饰）参加婚礼。她去面包房见到罗尼，后者听到婚事异常激动，并讲述了反对的理由。她据理力争，他根本不听。后来，她邀请他到家里做客，希望兄弟俩冰释前嫌，却没想到在一番激烈的争吵后，他们之间的关系发生了微妙的变化……©豆瓣', '雪儿', '诺曼·杰威森', 7.5, 8311, 'tt0093565', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2618029861.jpg', 0.7, 3.6, 33.5, 45.7, 16.6, '0.467486,0.091331,-0.946346,0.286251,0.052349,-0.216056,0.645560,0.131436,-0.622118,-0.264062,0.171230,0.850425,-0.635640,0.439909,0.300047,-0.007698,-0.210961,-0.567249,0.288599,0.045125,-0.200929,-0.555114,0.151992,-0.138718,-0.016302,-0.277691,0.006516,0.026395,-0.041369,0.567576,0.365133,0.140178,-0.019639,0.664719,0.184710,0.188699,0.215774,0.286878,-0.303861,0.232116,0.171844,-0.005833,-0.119864,0.286657,0.223086,0.561597,0.273505,-0.003403,-0.160631,-0.091975,0.354320,0.011156,0.010791,0.234139,0.336184,-0.020985,0.372137,0.257891,-0.345826,-0.033378,0.050721,0.042076,-0.197812,0.487170,0.107461,0.171585,-0.535664,0.447771,-0.068892,-0.049208,0.118274,-0.319166,0.285515,0.319782,0.339307,0.276797,-0.070925,-0.084016,-0.450430,0.069218,0.946864,-0.131848,-0.135475,0.320264,-0.261270,-0.102321,0.159884,-0.155997,-0.279349,0.291430,0.042438,0.065973,-0.325227,0.240162,-0.274085,-0.270391,-0.311025,0.060658,0.002904,-0.429851,0.039595,-0.562674,-0.082392,-0.324818,-0.349368,-0.042207,-0.109974,-0.130134,0.274981,-0.726067,0.112238,0.415788,0.665956,-0.406401,0.473579,0.212959,0.088456,-0.115617,0.101287,0.141690,-0.152008,-0.039982,0.145311,0.088515,0.295811,-0.052702,-0.094745,0.341633', '25721544', '1292064', '26687241', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292874', '生于七月四日', '剧情', '朗（汤姆•克鲁斯 Tom 饰）自幼就是一个争强好胜的男孩，向往男子汉的生活。年轻的朗被总统那潘那番充满煽动性的越战演说彻底征服，一种挑战和为国牺牲的冲动在朗的内心渐渐滋长。一次摔跤比赛的失利，令一向要强的他毅然告别了恋人唐娜和大学生活，踏上了从军参战之路。然而，来到了越南的朗并没有在这里找到向往已久的英雄气概，反而目睹一出出反人类的悲剧。朗的好友威尔逊也在一次混战中死于朗的子弹，不久，朗中弹瘫痪被送回了美国。坐在轮椅上的朗仍然坚持着对美国发动的战争的信仰，但女友唐娜重遇了朗之后，痛心的认为朗的悲剧都是战争的错。噩梦缠绕着朗，朗去拜祭了战友威尔逊，反战呼声中，朗终于觉醒。©豆瓣', '汤姆·克鲁斯', '奥利佛·斯通', 7.8, 12865, 'tt0096969', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1178250655.jpg', 0.4, 1.8, 26, 53, 18.9, '0.114100,0.344688,-0.873341,0.738616,-0.096470,-0.653626,0.854171,0.061199,-0.001136,-0.403826,0.507373,0.806354,-0.259854,0.530499,0.792629,-0.082339,0.143174,-0.876097,-0.404939,0.149471,-0.177782,-0.429636,-0.030682,-0.018906,-0.070868,-0.456422,0.715156,0.291570,-0.303148,1.063010,0.545884,0.339419,0.257179,0.620076,-0.460047,0.004387,-0.161173,0.392395,-0.292740,-0.183873,0.179423,-0.172656,-0.103180,-0.051455,-0.154005,0.206392,0.537703,-0.356807,-0.016031,-0.174954,0.416109,-0.169532,0.069775,0.325270,0.536720,-0.116328,-0.557148,0.419862,-0.142295,0.473011,-0.214169,0.190461,-0.619634,0.125612,-0.109738,-0.079417,-0.629145,0.974199,0.020841,-0.075475,-0.246570,0.299184,0.447325,0.365509,-0.026644,0.430291,0.084310,0.009247,-0.327805,-0.161706,0.476276,-0.083316,-0.206553,0.257651,-0.429374,-0.331588,-0.149657,-0.396492,-0.346040,-0.028285,0.195542,-0.127243,-0.348335,0.312434,-0.858876,-0.080740,-0.136587,-0.157982,0.047825,-0.236335,-0.098588,-0.654006,0.086358,-0.047681,-0.353481,0.579460,-0.456855,-0.468012,0.857565,-1.000530,-0.168527,0.438042,0.348203,-0.654672,0.427205,0.134141,-0.152887,-0.259563,0.149360,0.680489,0.085373,0.424350,0.213138,0.648474,-0.357139,-0.183828,-0.474231,0.735716', '26365262', '1301562', '3139191', '25723081');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292881', '万世魔星', '喜剧', '本片是英国著名的喜剧团体Monty Python的成员特里琼斯 (Terry Jones)导演的一部荒诞不经的调侃宗教的电影,故事的发生地在巴勒斯坦,讲述了一个普通的男人被世人误认为是弥赛亚(犹太人企盼的复国救主)，由此引发了许多啼笑皆非的故事，一如Monty Python所有的电影那般，特里琼斯在这部电影中也使用了大量荒诞无厘头的笑料，电影以圣经为原型，由头至尾都充斥着颠覆，嘲讽的意味，对于虔诚的宗教人士来说，这部电影确实是场巨大的灾难。©豆瓣', '格雷厄姆·查普曼', '特瑞·琼斯', 8, 10436, 'tt0079470', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1425774362.jpg', 1.4, 3.2, 21.8, 42.2, 31.5, '0.501249,0.037842,-0.436646,0.954666,0.312232,0.045179,1.114622,0.020161,-0.562462,-0.147060,0.338725,0.753858,-0.444444,-0.037236,0.202280,-0.154273,-0.427617,-0.598343,-0.537983,-0.167993,0.270355,-0.313408,-0.463001,-0.184821,-0.261068,-0.541422,0.638804,0.201836,-0.796594,0.077024,0.449157,0.498415,0.086902,0.163499,0.087924,0.088125,-0.224781,-0.088760,-0.258151,0.076348,-0.038129,-0.270484,-0.308119,0.361873,-0.565562,0.351393,0.668525,-0.344343,-0.162283,-0.059049,0.823259,-0.435182,-0.216757,0.131612,0.124016,0.336353,0.365326,0.204880,0.261995,0.189398,-0.002959,-0.181203,-1.339756,-0.105504,0.145595,0.418041,-0.345862,0.720712,-0.048914,-0.032790,0.076139,-0.073761,0.222192,-0.150265,0.554635,0.743875,0.093184,0.026848,-0.461919,0.624282,0.482569,0.290102,-0.627498,0.560951,-0.536951,-0.406429,-0.258318,-0.255610,-0.654994,0.179260,0.404072,-0.593676,0.059806,0.683639,-0.789799,-0.036014,0.158097,-0.435489,0.036290,-0.357374,0.157361,-1.051702,-0.177724,-0.367173,0.083258,-0.511627,0.453827,-0.362829,1.118058,-0.526743,0.128015,0.607315,-0.199701,-0.216656,0.650263,-0.109119,-0.090670,-0.111323,-0.110169,0.273134,0.009068,0.127548,-0.016953,0.497863,0.300566,-0.351501,-0.248010,0.809606', '3318306', '27602116', '22265121', '4267948');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292889', '基督最后的诱惑', '剧情', '本片不以《圣经》为依据，而是以故事为线索展示心灵内在的信仰冲突。当以色列处于罗马统治下的时候，木匠耶稣（威廉·达福 Willem Dafoe 饰）为罗马军队制作十字架，他为冥冥中似乎来自上帝的召唤而困扰。耶稣动身探求真相，于路邂逅起义者犹大（Harvey Keitel 饰）和昔日的朋友妓女抹大拉，他们指责耶稣的懦弱，使其坚定了信仰，越来越多的信徒加入了耶稣的队伍，施洗者约翰指点耶稣前往沙漠。耶稣抵御了诱惑，获得更大的力量，他带人围攻耶路撒冷神殿，令犹大去罗马当局告发自己，在十字架上的耶稣得到天使的信息，他走下十字架，过上了平凡的生活，直到多年以后，耶稣发现了事情的真相，重新回到了自己命运中……本片根据卡赞察斯基的同名小说改编，自从1983年斯科塞斯第一次筹划将本片搬上银幕，宗教团体的反对声便喧嚣尘上，致使拍片计划一再拖延。©豆瓣', '威廉·达福', '马丁·斯科塞斯', 7.8, 7038, 'tt0095497', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2100470563.jpg', 1.1, 2.9, 23.4, 47.8, 24.7, '0.058852,0.197523,-0.426486,0.701283,-0.039748,-0.183394,0.608287,0.208367,-0.304624,-0.103072,0.296412,0.812115,0.098122,0.003360,0.213191,0.096537,-0.725099,-0.540824,0.047187,-0.052449,-0.280007,-0.356958,-0.190040,-0.421584,-0.200543,-0.461953,0.753113,0.159856,-0.230441,0.081664,0.045363,0.368965,-0.091098,0.274489,-0.235533,0.066558,0.050611,0.090074,-0.294734,0.166824,-0.129013,-0.355577,-0.213150,0.479462,-0.391419,0.223748,0.492981,-0.568023,-0.046875,-0.383402,0.382040,-0.239023,0.104755,0.065523,0.032547,0.213050,0.029809,0.448428,0.042258,0.094301,-0.113249,-0.180099,-0.891612,-0.206419,0.095215,0.109538,-0.563861,0.329610,-0.123120,0.170670,0.198174,-0.265320,0.153441,0.263926,0.390725,0.391548,-0.057956,-0.245527,-0.367364,0.233313,0.452306,-0.222571,-0.258296,0.142390,-0.494183,-0.271711,0.097453,-0.075089,-0.308667,-0.069458,0.268347,0.018135,0.105442,0.482325,-0.688830,-0.394842,-0.249090,-0.164095,0.171559,-0.438800,0.071778,-0.742780,-0.347329,0.047122,0.147388,-0.092031,0.254234,-0.096245,0.775691,-0.490598,0.457912,0.736528,0.223663,-0.606087,0.557839,-0.021408,-0.054704,-0.383399,0.078644,0.507945,0.070823,0.532265,0.028895,-0.104151,0.171556,0.004290,-0.285286,0.627389', '25928048', '3769423', '4820775', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292894', '无线电时代', '喜剧', '画外音中，一个中年男子带领观众回到他童年时生活的洛格威小镇，那里有太多围绕着收音机广播的有趣故事……两名小偷潜入一户人家作案，恰巧广播中的电话竞答节目选中了这里，小偷答中了所有问题，第二天男主人返家，发现钱物丢失但竞答节目的奖品却堆满了门口。碧姨妈与别人相亲时广播中传来火星人进攻地球的消息，对方抛下姨妈落荒而逃。广播明星罗杰与一名夜总会女郎莎莉（Mia Farrow 饰）纠缠不清，莎莉没有如愿得到广播的工作机会却在战时节目中大展拳脚。蒙面游侠的连续广播吸引了无数少年，但主人公始终无法得到一枚游侠戒指……1944年的新年广播中，所有这些经典时代的记忆落下了帷幕。本片获1988英国电影学院奖最佳服装、最佳美工奖。©豆瓣', '米娅·法罗', '伍迪·艾伦', 8.4, 7349, 'tt0093818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2359633584.jpg', 0.2, 0.8, 14.2, 50.2, 34.6, '0.195987,0.311888,-0.329124,0.447213,0.058373,0.060618,0.714877,-0.176862,-0.499308,-0.345401,0.036215,0.627372,-0.416650,0.316558,0.254256,0.075575,-0.470063,-0.735763,0.021086,-0.152099,-0.139775,-0.075304,-0.096546,-0.062106,-0.209996,-0.098219,0.500967,0.161614,-0.199625,0.472061,0.311817,-0.175336,-0.317825,0.439337,-0.240719,0.050751,0.468070,-0.098994,-0.065119,0.436005,-0.309371,-0.239755,-0.332471,0.121066,0.037388,0.268575,0.744658,-0.120011,0.182313,0.138246,0.606755,0.105655,-0.213299,-0.109451,0.289470,0.281963,0.520666,0.040751,0.056726,0.074861,-0.178204,-0.039684,-0.248715,-0.010779,-0.112938,0.149792,-0.172922,0.072446,-0.208907,0.350217,-0.070353,-0.159016,0.422226,-0.173932,0.384448,0.086260,-0.147127,-0.017454,-0.253580,0.584099,0.477935,-0.118449,-0.088663,0.398337,-0.119563,-0.562406,0.010007,0.112267,-0.553040,0.185459,0.503094,0.001930,-0.078320,0.022751,-0.361811,0.014568,-0.005561,-0.384244,-0.005410,-0.173751,-0.547601,-1.170612,-0.035641,0.190662,-0.280325,0.168709,0.013843,0.095771,0.783018,-0.728769,0.156514,0.469543,-0.060327,0.122369,0.741351,-0.098619,0.358697,-0.187546,-0.148624,-0.083117,0.074285,0.298480,-0.175651,0.177742,-0.405710,-0.571829,-0.538448,0.356349', '24751811', '3003137', '34961898', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292895', '精武英雄', '剧情', '20年代末，为完成师父的志愿，陈真（李连杰 饰）到东洋学先进技术，他喜欢着日本女孩山田光子（中山忍 饰）。因为师父霍元甲之死，陈真回到中国，协助师父之子霍廷恩（钱小豪 饰）主持精武门的业务，不料却引起了他的妒忌，师兄弟之间引发权力之争。另一方面，陈真追查师父死因，怀疑是日军 军官藤田刚（周比利 饰）暗中使用慢性毒药杀死霍元甲。陈真请医生验尸，证实师父确系中毒而死。藤田刚恐阴谋败露，杀人嫁祸，展开了连场恶斗。不久，藤田刚挑战精武门，他诱使日本黑龙会总教头船越文夫向精武馆挑战。比武之日，双方开展了一场惊心动魄的决战。©豆瓣', '李连杰', '陈嘉上', 8.6, 127435, 'tt0110200', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2431081842.jpg', 0.1, 0.5, 11.9, 45.7, 41.8, '-0.214831,-0.119269,-0.500090,0.292105,-0.081829,-0.170717,0.119541,0.001415,-0.273425,-0.320848,0.458872,0.349115,0.020435,-0.050926,-0.039892,-0.265533,0.024728,-0.424063,0.128405,0.022201,-0.121775,-0.345763,0.034771,-0.331591,-0.139915,-0.281152,0.505750,0.229121,-0.492208,0.439071,0.279099,0.197160,-0.086462,0.100864,0.388779,-0.111840,0.076492,-0.180707,-0.559635,0.296292,-0.096683,-0.420756,-0.194784,0.130863,-0.153350,0.399352,0.442636,-0.012135,-0.111587,-0.500251,0.365204,-0.472543,-0.187092,0.099356,0.412273,0.267497,-0.164928,0.365055,0.037620,-0.193222,-0.170484,0.202021,-0.297470,0.084535,0.251693,0.059707,-0.303443,0.185009,-0.388703,0.187327,-0.135293,-0.146621,-0.050153,0.353692,0.393803,-0.092994,-0.049963,-0.105169,-0.254639,0.398989,0.754265,-0.351823,0.214428,-0.197240,0.512682,-0.266699,0.410716,-0.453485,0.007943,0.164290,0.269690,-0.496452,0.055407,0.170628,-0.118824,-0.276028,-0.215531,0.159581,-0.015969,0.088514,0.547086,-0.720527,-0.137628,-0.060237,-0.282417,-0.302838,0.305551,-0.468117,0.677978,-0.600734,0.065533,0.541405,0.273761,-0.489240,0.176157,0.244919,-0.163384,-0.266626,-0.205449,-0.068355,0.188404,0.158173,0.063316,0.179482,0.217432,-0.251545,-0.177645,-0.218899', '2369613', '1316589', '3811356', '25983044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292897', '从军记', '喜剧', '查理在新兵营里是个插科打诨的乌合之众，但在法国参加战斗时，却立下了赫赫战功：他先是冲到最前线俘获了13个德国佬，然后扮成大树桩一步步逼近德军防线，最后又在一个法国女孩的协助下，俘获了德国皇帝和他的皇太子。所向披靡的查理回到家乡纽约后得到了人们的夹道欢迎……就在查理被荣耀所包围，兴奋得无以复加时，眼前的一切都突然消失了——原来，这只是一场梦。《从军记》大肆戏谑战争的格局与构想，后被影评界认为是十二年后《大独裁者》的前哨作品。本片拍摄时正值第一次世界大战烽火连天之时，痛恨战争的卓别林适时拍出这部以梦境为叙事主体的电影，无论从创作出发点还是从内容的构架来讲，都不失为一次大胆的创新——借一个协约国小人物的离奇经历，讽刺德军将领及德国皇室。尽管从客观上说，本片的喜剧张力不及卓别林其他平民喜剧来得从容，令观众容易产生昏昏欲睡之感，但笑点设计却依旧保持了卓别林惯有的水准，如片中男主人公戴着防毒面具啃林堡干酪、拿干酪当武器打击敌军、扮成树型冲上火线等等，均带有浓烈的搞笑因子。《从军记》取得了十分惊艳的票房成绩，但在当时却有观众认为本片存在着致命的瑕疵——结尾部分的梦醒设置相当令人扫兴，这也就是为何《从军记》未能成为像《大独裁者》一样经典的原因之一。当然，这也不排除卓别林在早期创作中难以规避某种“妥协”的可能。', '查理·卓别林', '查理·卓别林', 8.9, 7430, 'tt0009611', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p905332012.jpg', 0.2, 0.4, 8.8, 37, 53.7, '0.140443,0.037911,-0.651053,0.671114,0.078992,-0.152404,0.745016,-0.016722,-0.341453,-0.072062,0.316829,0.818129,-0.329019,-0.059117,0.187518,-0.233460,-0.374942,-0.493451,-0.276580,-0.187225,-0.061680,-0.168811,-0.347437,-0.094449,-0.191262,-0.365050,0.721240,0.221175,-0.584138,0.331330,0.254924,0.233233,0.166305,0.477156,-0.033890,-0.116214,-0.074448,-0.020017,-0.128070,0.149158,-0.029505,-0.331460,-0.268418,0.247053,-0.300361,0.369681,0.643243,-0.492731,-0.169406,0.100682,0.560761,-0.309368,-0.136341,0.150724,0.124739,0.184222,0.065954,-0.059701,0.027944,0.156196,-0.012958,-0.097046,-0.974631,-0.069823,0.092538,0.093480,-0.378404,0.531789,0.005247,0.044901,0.124675,-0.238902,0.209213,0.233185,0.458329,0.341994,-0.141075,0.139597,-0.488365,0.268906,0.578250,0.045744,-0.593846,0.380394,-0.321059,-0.537855,0.045801,-0.395415,-0.228220,0.098396,0.217145,-0.021161,0.053022,0.251116,-0.499548,0.045427,-0.166907,-0.242481,-0.128796,-0.370167,-0.177402,-0.605046,-0.227432,-0.422138,-0.160181,0.071711,0.195302,-0.211997,0.811829,-0.699612,0.061993,0.495201,0.007983,-0.222003,0.533112,0.186295,-0.125597,-0.008591,-0.152815,0.182433,-0.059113,0.166498,0.056103,0.550618,-0.131690,-0.442476,-0.268937,0.584238', '27602116', '25928048', '26667010', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292898', '势不两立', '剧情', '查尔斯（安东尼·霍普金斯 Anthony Hopkins 饰）是一个腰缠万贯的百万富翁，对于他来说，金钱、权利和女人不过是生活的基本配置而已。但是，在为查尔斯打工的摄影师罗伯特（亚历克·鲍德温 Alec Baldwin 饰）眼里，老板所拥有的一切，尤其是他年轻的妻子米琪（艾拉·麦克弗森 Elle Macpherson 饰）都让他感到十分眼红，但是，罗伯特不知道的是，敏感又细心的查尔斯早就开始怀疑起了他和米琪之间的清白。在一次工作中，众人乘坐的飞机发生了事故，一行人流落到了阿拉斯加的荒原之上。匮乏的资源，恶劣的天气，凶恶的野生动物，一切的一切都威胁着大家的性命，但最最可怕的，其实是每个人深藏在心底的黑暗面。©豆瓣', '安东尼·霍普金斯', '李·塔玛霍瑞', 7.9, 7927, 'tt0119051', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1899171406.jpg', 0.2, 1.5, 23.5, 51.6, 23.1, '0.500345,-0.159907,-0.940357,0.745075,-0.381822,-0.176434,0.911439,-0.037554,-0.747473,-0.279458,0.336328,0.776944,-0.026472,0.207243,0.135481,0.317151,-0.157279,-0.521049,-0.188380,-0.243760,-0.247559,-0.630441,-0.367359,-0.370577,-0.369837,-0.395007,0.508932,0.272255,-0.058335,0.225282,0.319913,0.262511,0.197472,0.720143,-0.201660,-0.225181,0.009052,-0.140378,-0.135237,-0.002799,0.020780,-0.227998,-0.127274,0.677725,0.108828,0.520872,0.499930,-0.330068,-0.358289,0.110157,0.467324,-0.517616,-0.018111,0.188698,0.287397,-0.127281,0.168643,0.140549,-0.193716,0.133120,0.148747,0.172044,-0.989532,-0.175350,0.073451,0.207103,-0.799359,0.703484,-0.177316,-0.277300,-0.005874,-0.434419,0.435004,0.081814,0.025706,0.518930,0.016878,-0.091106,-0.717900,0.020619,0.807611,0.185680,-0.380659,0.467179,-0.530215,-0.552319,-0.278573,-0.243223,-0.647128,0.027804,0.069751,-0.010256,-0.168416,0.447098,-0.500925,0.269127,0.024814,-0.477295,-0.169122,-0.556208,-0.191946,-0.443828,-0.251422,-0.909133,-0.565633,-0.051786,0.238994,-0.505596,0.889341,-0.985297,0.004073,0.626430,0.058268,-0.483750,0.620947,0.028621,0.081227,-0.073972,-0.329567,0.073301,0.075009,0.063244,0.108204,0.393871,0.059238,-0.167760,-0.112932,0.747313', '1303112', '24756472', '26981174', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292900', '摇啊摇，摇到外婆桥', '剧情', '1930年代，乡村少年唐水生来到上海投靠六叔（李雪健），在他的引荐下，做了歌舞皇后小金宝（巩俐）的贴身佣人。小金宝是上海滩一霸唐老爷（李保田）的女人，但与其手下宋二爷有染，而宋二爷已经觊觎唐老爷的位子良久。六叔的猝死使唐老爷心生警觉，带着小金宝、水生等人来到一个只有寡 妇翠花和她一双儿女在的小岛避难，并下令对上岛的生熟面孔格杀无论。小金宝在同翠花的相处中对生活有了另一番理解，渐渐对唐老爷的残忍非常不满，然而她的命运亦掌控在唐老爷手中。©豆瓣', '巩俐', '张艺谋', 7.4, 36812, 'tt0115012', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2614141720.jpg', 0.6, 3.8, 35, 44.8, 15.8, '0.039158,0.003557,-0.576638,0.533416,-0.224548,-0.233685,0.617872,0.282687,-0.798454,-0.037311,0.198157,0.621904,-0.141008,0.418423,0.189072,0.061225,0.042604,-0.393749,-0.168664,-0.136052,-0.200867,-0.335744,-0.058688,-0.322364,-0.191296,-0.045570,0.253968,0.026653,0.042529,0.377650,0.412472,-0.034174,-0.061592,0.492909,-0.370080,0.259909,-0.267943,-0.027466,-0.293688,0.011125,0.018722,-0.205118,-0.130471,-0.054629,0.250595,0.129413,0.756069,-0.379546,-0.116655,-0.209700,0.114763,-0.134552,0.040438,0.066087,0.294663,0.013679,-0.185877,0.129711,-0.274398,-0.121506,0.139489,-0.023213,-0.271633,0.163041,0.139497,0.056506,-0.613364,0.372575,0.189755,-0.001648,-0.255742,-0.338382,0.400617,0.150111,-0.034922,0.312254,-0.158052,0.184904,-0.380621,0.085543,0.326547,0.023829,0.059318,0.091768,-0.190912,-0.512019,-0.004119,-0.111002,-0.687778,-0.383581,0.351164,-0.000486,-0.194161,0.109866,-0.191081,0.090658,0.034005,0.121237,0.099466,-0.553571,-0.067062,-0.363897,-0.306882,-0.584444,-0.148513,0.191120,0.222446,-0.254280,0.769940,-0.753715,0.139243,0.033530,0.190843,-0.587039,0.588990,0.013040,0.103997,-0.334290,-0.192385,0.358208,0.101434,0.239437,0.207921,0.267412,-0.459055,0.067791,-0.158541,0.270483', '3445516', '1301221', '26348103', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292906', '美人鱼', '喜剧', '当艾伦·鲍尔（汤姆·汉克斯 Tom Hanks 饰）还是孩童时，曾在科德角的波涛中看见过传说中的美人鱼，这段经历在他的脑海中深深扎根。20年后，艾伦已成长为英俊的帅小伙，他终日奔波忙碌，真爱却始终未曾到来。某天，艾伦重返科德角，并且在此不慎落水。就在危急之时，一个美丽的美人鱼（达丽尔·汉纳 Daryl Hannah 饰）出现，拯救了他的性命。未过多久，美人鱼隐去鱼尾，来到纽约寻找艾伦，两人由此坠入爱河。一场现代的都市传奇爱情就此展开，但在这物欲横流的都市里，他们的爱情将何去何从……本片荣获1985年美国科幻与恐怖电影学院最佳女主角奖（Daryl Hannah）、1985年美国国家影评人协会最佳剧本奖。©豆瓣', '汤姆·汉克斯', '朗·霍华德', 7.4, 13435, 'tt0088161', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2159203093.jpg', 0.2, 2.4, 38.2, 44, 15.3, '-0.063858,0.076126,-0.754823,0.377570,0.240296,-0.426879,0.692743,-0.214484,-0.487156,-0.202251,0.359743,0.741175,-0.350179,0.378858,0.551728,0.024234,-0.500431,-0.812341,-0.122336,-0.274599,-0.249424,-0.037596,-0.591945,0.123910,-0.143426,-0.310015,0.770342,0.219635,0.083072,0.534546,0.258434,0.126716,-0.348679,0.332831,-0.160983,0.135634,0.161840,0.124718,-0.371434,0.205598,-0.066652,-0.422186,-0.322362,0.001843,-0.036122,0.128538,0.637927,-0.373155,0.057915,-0.059900,0.525580,-0.284005,-0.190651,0.093862,0.319337,-0.238200,0.049478,0.200175,-0.146921,-0.009590,-0.141637,-0.171673,-0.563574,0.029973,-0.138457,0.286583,-0.542317,0.287304,0.015921,0.099702,-0.078310,-0.151728,0.044348,0.166537,0.308125,0.264064,-0.100230,0.159544,-0.266282,0.611955,0.653605,0.256887,-0.579309,0.158585,0.015273,-0.571675,-0.168513,-0.123421,-0.472752,-0.099240,0.397788,0.163897,-0.240800,0.416704,-0.643345,0.186081,-0.371649,-0.160645,0.149224,-0.029931,-0.501874,-0.619172,-0.124722,-0.462725,-0.351605,-0.062128,0.057322,-0.218829,0.678460,-0.739187,0.425935,0.573363,0.075541,-0.159165,0.902966,0.008826,0.250291,-0.030961,-0.108062,0.600858,-0.139558,0.338359,-0.167953,0.140732,-0.141667,-0.127754,-0.537908,0.502598', '1299663', '30162520', '1302050', '25785124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292908', '家宴', '剧情', '一场在丹麦地方富绅海吉豪宅中举行的周末家庭聚会，是为了庆祝他六十岁大寿而筹办的。他的儿子与媳妇、女友与男友，还有几位亲友齐聚一堂为他庆生。不过原来该是融洽的热闹的晚宴，却笼罩着诡异的气氛，仿佛海吉两周前自杀身亡的女儿阴魂犹在。岂知早逝女孩的双胞兄弟击杯起身发言，控诉父亲乱伦并谋杀亲生女儿，引爆了席间的争议对立。而在此状况下，这群人不得不采取先发制人的手段……', '乌尔里奇·汤姆森', '托马斯·温特伯格', 8.3, 6214, 'tt0154420', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2499986751.jpg', 0.5, 1.5, 13.1, 49.8, 35, '0.059977,-0.262653,-0.674108,0.459894,-0.060337,-0.087665,0.823489,0.446332,-0.575043,-0.145350,0.619331,0.645973,-0.470581,0.477117,0.652962,-0.065558,-0.082617,-0.656274,-0.138673,0.097134,0.082900,-0.462227,-0.094438,-0.322248,0.085943,-0.293427,0.196142,0.184339,0.080582,0.389817,0.532411,-0.028536,-0.183649,0.506727,-0.098435,-0.335249,-0.196348,0.345517,-0.735471,-0.011600,-0.148893,-0.429340,-0.383076,0.331024,0.115196,0.572540,0.518092,-0.185282,0.049523,-0.219960,0.212466,-0.166133,-0.060655,0.322853,0.432423,-0.080721,0.638328,0.240128,0.029926,-0.128100,-0.029482,-0.224990,-0.377872,0.430968,0.203025,-0.195008,-0.241616,0.743616,-0.005492,-0.115502,-0.114741,-0.260635,0.436370,0.466510,-0.094835,0.487009,-0.284228,-0.138669,-0.298091,0.177921,0.785527,0.002032,-0.100345,0.257347,-0.340890,-0.338709,0.162230,-0.388372,-0.385249,-0.076373,0.083397,-0.048145,-0.015184,0.354095,-0.488562,-0.266296,-0.243537,-0.122765,0.113013,-0.513725,0.003560,-0.549671,0.036322,-0.159606,-0.148917,0.029770,0.297130,-0.252753,0.487533,-0.725873,0.149970,0.410757,0.307755,-0.470976,0.555737,0.288210,0.260045,-0.337101,-0.440532,-0.256756,-0.169089,-0.021451,0.010107,0.042809,-0.247329,0.068713,-0.496303,0.283273', '26687241', '1308755', '25721544', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292925', '伴我同行', '剧情', '这是一部关于成长的电影。著名作家戈迪（理查德•德莱福斯 Richard Dreyfuss 饰）回忆起他12岁时的一次冒险活动：当时，年少的戈迪（威尔•惠顿 Wil Wheaton 饰）与他的三个小伙伴克里斯（瑞凡•菲尼克斯 River Phoenix 饰）、泰迪（科里•费尔德曼 Corey Feldman 饰）和维恩为了当一回“英雄”去河的对岸的森林里寻找一具12岁男孩的尸体。4个少年家庭各有问题，他们都有自己的心事。在旅程中每个人的性格都被体现得淋漓尽致：四个男孩性格中的软弱和坚强，在闪火车，翻铁门，越森林等一系列的行动中被最大限度的放大；每个人都有自己可望而不可及的梦想……1987年金球奖最佳电影、最佳导演提名，1987年奥斯卡奖最佳编剧提名©豆瓣', '瑞凡·菲尼克斯', '罗伯·莱纳', 8.9, 103271, 'tt0092005', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1979379460.jpg', 0.1, 0.4, 7.3, 36.5, 55.7, '0.115515,-0.238275,-0.617907,0.625969,-0.016135,-0.323226,0.775571,-0.072937,-0.398171,-0.218043,0.157607,1.005028,-0.331060,0.279943,0.383499,-0.031553,-0.293388,-0.693605,-0.098938,-0.178452,-0.172144,-0.340120,-0.506765,-0.028456,-0.147877,-0.296893,0.719599,-0.039124,-0.085440,0.334439,0.425551,-0.000817,0.137139,0.153944,-0.091833,0.082336,0.336075,-0.145813,0.135706,0.275465,-0.075831,-0.153526,-0.282844,0.060497,0.013529,0.412288,0.915386,-0.463297,-0.016558,-0.025191,0.357486,-0.144916,-0.224745,0.014786,0.245436,-0.234259,0.258817,0.279399,-0.067595,-0.042105,-0.100581,-0.171721,-0.912462,-0.161335,0.199927,0.158294,-0.639870,0.414528,0.061252,0.006007,0.288540,-0.150536,0.048125,0.091337,0.162030,0.290754,-0.296594,-0.246394,-0.320147,0.423582,0.416646,0.171955,-0.359022,0.439180,-0.350134,-0.524013,-0.204733,-0.250656,-0.608286,0.156964,0.436934,-0.147714,-0.230953,0.201258,-0.542442,0.231103,-0.214283,-0.313699,-0.190664,-0.356762,-0.166188,-0.608557,-0.133010,-0.319295,-0.218305,-0.007315,-0.080285,-0.248449,0.807839,-0.501675,0.057439,0.474895,-0.151511,-0.246742,0.942334,0.011793,0.126092,-0.363680,-0.069883,0.252572,-0.083067,0.046288,-0.217151,0.520712,-0.097764,-0.301945,-0.545286,0.654103', '30162520', '25928048', '2027945', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292930', '王牌大贱谍2', '喜剧', '邪恶博士使用了一种时间机器来到的1969年，在这里他偷走了奥斯汀的毛九(MOJO)——奥斯汀的力量之源，使其威力尽失。幸运的是，英国智力机构发明了一种更先进的时光机器，奥斯汀告别1999年的美好物质生活，回到他生龙活虎的时代，追回他的MOJO。同时邪恶博士酝酿了一个毁灭世界的邪恶计划：在月球上按照炮弹进而毁灭地球。奥斯汀一定要在1969年阻止邪恶博士的计划，不然，他将失去1999年所拥有的美女与吃喝玩乐。不正经的特工再次出动，只是为了自己，顺便拯救一下世界。©豆瓣', '麦克·梅尔斯', '杰伊·罗奇', 6.3, 5416, 'tt0145660', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2212659369.jpg', 4.3, 15.1, 50.1, 22.2, 8.4, '0.041670,0.425835,-0.514704,0.437535,-0.461306,-0.212471,0.630320,-0.269425,-0.282361,-0.044860,0.064418,0.547323,-0.011891,0.154965,0.272666,0.161111,-0.228494,-0.485517,0.008762,-0.214920,-0.365235,-0.503856,-0.517532,-0.420784,0.159533,-0.796558,0.708924,0.146984,-0.042834,0.094880,-0.257758,0.297835,0.123939,0.440513,-0.373818,-0.090040,-0.068821,-0.116625,-0.320504,0.258908,0.151584,-0.143369,-0.014577,0.172200,-0.407440,-0.219618,0.675813,-0.450299,-0.091493,-0.342692,0.509794,-0.419070,-0.336352,-0.167929,0.181223,0.064676,-0.412383,0.268300,-0.107273,0.034170,0.320779,-0.221587,-0.966949,-0.341467,-0.100286,-0.145696,-0.374198,0.332900,-0.108055,0.241629,-0.021734,-0.453546,0.161403,0.238837,0.379277,0.548414,-0.303171,0.194985,-0.331796,0.344941,0.603247,-0.247900,-0.609802,0.250504,-0.281996,-0.245744,-0.419938,-0.277983,-0.404245,-0.074302,0.340867,0.065149,-0.101280,0.482448,-0.968356,-0.147418,-0.278581,-0.242637,0.145677,-0.380804,-0.145678,-0.436146,-0.335775,-0.063794,-0.155120,-0.070474,0.363657,-0.343937,0.958781,-0.895870,0.377817,0.813488,0.383039,-0.607275,0.501266,-0.267801,-0.113804,-0.421341,-0.002820,0.296581,-0.055360,0.584959,0.042192,0.517377,0.166184,0.020079,-0.356100,0.785241', '24284209', '3769423', '1308585', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292938', '007之海底城', '动作', '近日，英国、苏联两国核子潜艇竟然相继离奇失踪了！这一现象引起了英国军方的高度重视，当然又到了王牌特工007邦德（罗杰•摩尔 Roger Moore 饰）的出场时间。邦德经过调查终于发现幕后的黑手原来就是世界巨富航运业大亨史登堡，他为实现自己征服世界的野心，建立了一座海底 城。史登堡高薪聘请科学家研发出了潜水艇跟踪系统，把把英、苏核子动力潜艇占为己有，他计划利用核子飞弹将纽约和莫斯科炸毁，实现一次毁灭两个超级强国的野心。007即将进入海底城阻止这个狂人的疯狂计划。©豆瓣', '罗杰·摩尔', '刘易斯·吉尔伯特', 7.2, 8719, 'tt0076752', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p458800509.jpg', 0.6, 4.3, 44.3, 38.5, 12.3, '-0.140662,0.400398,-0.898037,0.729350,0.173811,-0.201043,0.250420,-0.328173,-0.365833,-0.146684,0.034932,0.534943,-0.124348,0.131302,0.532920,0.128111,-0.341682,-0.657218,-0.055103,-0.272905,-0.445868,-0.434559,-0.546822,-0.516970,0.154881,-0.363549,0.730493,0.515000,-0.403517,-0.074970,0.176758,0.294680,0.045446,0.488308,0.017759,-0.049548,0.624499,-0.311917,-0.429826,0.237342,-0.278275,-0.225150,0.089712,0.372969,-0.017118,0.213761,0.402397,-0.337945,0.015255,-0.469710,0.358559,-0.614666,-0.121745,-0.204525,0.590375,-0.040452,-0.502035,0.342214,-0.320895,-0.035545,0.141512,-0.084150,-0.806561,0.039568,-0.054679,-0.261850,-0.474032,-0.157485,-0.483061,0.087940,-0.339281,-0.010309,0.289324,0.598140,0.521434,0.074690,-0.161997,0.519317,-0.558443,0.110855,0.588937,-0.389063,-0.276275,0.023187,0.317998,-0.491968,-0.083606,-0.273819,0.108858,-0.223968,0.415987,-0.385215,-0.067436,0.321201,-0.669399,-0.195947,-0.755773,-0.522783,0.270764,-0.175554,-0.058680,-0.808142,-0.202485,0.192543,0.067463,0.103673,0.082496,-0.075393,0.750036,-0.495601,-0.143683,0.696671,0.300052,-0.651372,0.403199,-0.101627,-0.039763,-0.480933,0.167812,0.070079,0.356432,0.384550,-0.116155,0.256023,0.179735,-0.359569,-0.010589,0.434694', '5157137', '1309112', '7155241', '10463953');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292943', '光辉岁月', '剧情', '该片是根据真人真事改编。1971年，一间黑人中学和一间白人中学合并，学校的橄榄球队必须重新组成一支混合球队“太阳神队”。一向以白人为主的小镇，迎来这些黑人后，对当地居民造成不小的震撼。黑人教练布恩（丹泽尔·华盛顿 Denzel Washington 饰）成了该队的主教 练。而白人教练比尔（威尔·帕顿 Will Patton 饰）却成了布恩的助手。比尔从敌视到逐渐发现除橄榄球之外，两人的共通。两人都极富正义感和荣誉感，有很强的职业道德，对工作兢兢业业，一丝不苟。布恩从一开始遭到所有人的排斥到凭著自己的信念，并在比尔的的配合之下，将一群脾气恶劣、注意力不集中的孩子调教成了一支富有活力、专打胜仗的橄榄球队，成功地将这一只长败军的黑白混合美式足球队伍推至冠军宝座。自从黑白教头并肩作战后，胜利的消息便不断传回......©豆瓣', '丹泽尔·华盛顿', '鲍兹·亚金', 8.6, 27366, 'tt0210945', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p858717623.jpg', 0.2, 0.6, 10.9, 45.1, 43.3, '0.231983,-0.129102,-0.615593,0.542967,-0.255615,-0.222794,0.569515,0.064244,-0.451923,0.003386,0.255795,0.863136,-0.094768,0.047318,0.424567,-0.254407,0.019544,-0.840205,-0.351433,-0.075596,-0.271436,-0.635108,-0.281387,-0.216357,-0.138987,-0.477519,0.611935,-0.065761,-0.251560,0.544656,0.299458,0.280898,0.210058,0.172416,-0.164250,0.012372,0.156253,-0.275005,-0.064524,0.198455,0.029886,-0.015049,-0.312109,-0.086542,0.091508,0.249635,0.869746,-0.192927,-0.020422,-0.111938,0.317910,0.009420,-0.218395,0.101395,0.525694,0.171770,0.074722,0.256887,-0.065829,0.212540,-0.141726,-0.227560,-0.627831,0.004389,0.139551,0.216694,-0.476239,0.744730,0.031135,-0.249097,0.216662,-0.226966,-0.030067,0.227301,0.188028,0.381521,0.089461,0.113583,-0.308445,-0.088249,0.558237,-0.106808,-0.470648,-0.024830,-0.326863,-0.333085,-0.120596,-0.183159,-0.313476,-0.191833,0.353863,0.131111,0.192445,0.020082,-0.800337,0.054043,-0.030655,-0.334672,0.119096,-0.358906,-0.030612,-0.681799,-0.102654,-0.410814,-0.134449,0.128327,-0.014060,0.062310,0.990129,-0.892906,-0.005687,0.356923,-0.012761,-0.234764,0.299488,-0.168279,0.324600,-0.167596,-0.345178,0.117034,0.310430,0.339944,0.222380,0.787261,-0.209577,-0.301844,-0.264575,0.499202', '1826173', '3811356', '4127270',