INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292950', '新不了情', '剧情', '阿杰（刘青云 饰）是一个怀才不遇的年轻音乐人，生活潦倒不得不独自住进了一个破旧的单位内，终日都沉默寡言。此时他也遇到了在庙街街头艺人的女儿阿敏（袁咏仪 饰），阿敏虽然自小便患有骨癌，但她还是乐观开朗的面对自己的人生，她对生命充满希望的态度感染了阿杰，令他找回了失去的自信，在事业上也看到了曙光。两人渐渐情愫互生，就当一切看来都十分顺利之际，阿敏的病情却日渐恶化，使她失去了往日的勇敢及坚强，变得暴躁起来。最后阿敏得到了阿杰与亲戚朋友的鼓励，可是阿敏体内的病魔还是不肯放手。©豆瓣', '刘青云', '尔冬升', 8.3, 56871, 'tt0111770', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2250690647.jpg', 0.1, 0.7, 15, 51.6, 32.7, '0.028884,0.159936,-0.640110,0.536116,-0.354373,-0.493327,0.888985,0.248514,-0.626779,0.049303,0.191021,0.720183,0.020073,0.504400,0.052847,-0.064872,-0.282093,-0.725708,-0.172576,0.229346,-0.068985,-0.279353,-0.271146,-0.142759,-0.323188,-0.393725,0.659177,0.270755,-0.127808,0.469036,0.160594,0.053364,0.304551,0.785965,-0.190253,0.082515,-0.192556,0.073762,0.074941,-0.197729,0.418748,-0.401722,-0.196684,0.522373,0.106773,0.523034,0.590574,-0.127768,-0.450814,0.047695,0.395687,-0.081337,-0.170907,0.171931,0.127552,0.017872,0.090798,0.115839,-0.338279,0.000052,-0.208609,0.191583,-0.610201,0.118589,0.145256,0.076429,-0.619456,0.576614,0.016194,-0.090113,0.079292,-0.438204,0.048384,0.124020,0.096031,0.472460,-0.395462,-0.069265,-0.422682,0.110299,0.848552,0.120472,-0.583654,0.531704,-0.620484,-0.471020,-0.010402,-0.354286,-0.561149,-0.117729,0.209369,0.156432,-0.255680,0.277007,-0.402135,0.150083,-0.176699,-0.084974,-0.155868,-0.431959,0.081715,-0.232496,-0.314621,-0.661362,-0.467399,0.114864,-0.114916,-0.282982,0.945623,-0.863544,0.195000,0.387836,0.195988,-0.627798,0.422392,0.155624,0.098633,-0.021429,0.032814,0.437824,-0.325561,0.242926,0.206748,0.278239,-0.367543,0.011377,-0.444439,0.785316', '35030151', '4724586', '1292062', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292962', '黑金', '剧情', '调查局机动组组长方国辉（刘德华）为人干练嫉恶如仇，与手下对周朝先（梁家辉）经营的电玩场进行监拍时，拿到其经营地下赌场的证据，将其告上法庭，岂料法官被收买，周朝先被判无罪当庭释放。与黑金挂勾的侯部长（李立群）暗中施压，调查局勒令方国辉休假，停止对周朝先的调查。周朝先为进一步控制台湾的政治，在记者会上公开声明要退党参选立法委员，欲与代表党竞选的黑帮老大丁宗树对着干。方国辉沮丧之际，得电视台女记者凌飞（吴辰君）和法务部冯部长的鼓励重回工作岗位，却被丁宗树盯上，欲将他杀死后再嫁祸周朝先，好一石二鸟。©豆瓣', '刘德华', '麦当杰', 7.8, 82674, 'tt0156588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2463618493.jpg', 0.4, 2.5, 26.1, 48.7, 22.3, '0.139988,0.326405,-0.432722,0.530465,0.022229,-0.125660,0.298783,0.496303,-0.295232,0.075086,0.052125,0.381409,-0.155819,-0.002883,0.355018,-0.128205,-0.588250,-0.887520,-0.272718,0.174744,-0.143312,-0.651298,0.139422,-0.201918,-0.286325,0.023878,0.670188,0.013772,-0.323560,0.277030,0.355465,0.176426,0.094969,0.469561,0.160243,-0.208294,0.032653,-0.398227,-0.626414,0.330329,0.271838,-0.523051,-0.098301,0.085292,0.352617,0.297439,0.334900,0.040186,0.013545,-0.472122,0.368072,-0.438883,0.001111,0.247325,0.528730,0.385213,-0.089722,0.645026,-0.423875,-0.337274,0.188105,-0.188955,-0.686902,-0.095320,0.227684,-0.033274,-0.448587,0.254273,-0.361329,0.341288,0.106608,-0.100224,0.178465,0.415925,0.109641,-0.009679,0.144190,0.159660,-0.223960,0.236002,0.425704,0.021337,0.077254,-0.480374,0.373275,-0.478533,0.043651,-0.208397,0.104273,-0.279088,0.165575,-0.123743,0.007807,-0.122360,-0.326677,-0.525594,-0.155983,-0.078027,-0.081858,-0.624599,0.234376,-0.687984,-0.077070,0.073213,-0.039992,0.090233,0.426456,0.043356,0.304402,-0.548455,0.035216,0.572183,0.514241,-0.858171,0.524904,0.276507,0.285794,-0.245756,-0.287518,-0.623569,0.527858,0.717470,0.350328,0.224665,0.104503,-0.437998,-0.099474,-0.060092', '1302110', '1307914', '26996640', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292965', '不羁夜', '剧情', '故事发生在上世纪70年代，17岁的夜店服务生艾迪（马克·沃尔伯格 Mark Wahlberg 饰）天生拥有巨大的秘密武器，一次偶然机会，他被色情片导演杰克（伯特·雷诺兹 Burt Reynolds 饰）看中。于是，艾迪改艺名为德克，在杰克的栽培下在色情电影界大放异彩，成 了该行业的天皇巨星。因为所拍影片都很卖座，杰克和德克名利双收，过着豪华无度的生活。然而进入80年代以后，色情电影工业发生了重大变化，过去辉煌的历史一去不返，德克和杰克这对色情电影业的最佳拍档也分道扬镳……©豆瓣', '路易斯·古兹曼', '保罗·托马斯·安德森', 7.6, 21927, 'tt0118749', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2188465923.jpg', 0.8, 3.6, 30.8, 46.5, 18.3, '0.209404,0.092967,-0.797618,0.330555,0.179517,-0.235062,0.849390,0.150537,-0.423039,-0.247771,0.127456,0.703697,-0.579271,-0.068416,0.660684,0.164085,-0.439976,-0.511251,0.120215,-0.325265,-0.013991,-0.452498,-0.471580,-0.131501,-0.117937,-0.384437,0.511651,-0.198313,-0.238042,0.129140,0.399398,0.313783,0.346720,-0.057725,-0.147928,0.349018,0.148705,-0.085677,-0.607047,0.353898,0.180319,-0.073957,-0.102073,-0.029456,0.019356,-0.008473,0.339383,-0.228235,-0.122748,-0.017965,0.437059,0.075373,-0.120787,-0.039519,0.326607,-0.047285,0.121673,0.297070,-0.024955,0.051657,0.107470,-0.193347,-0.662274,0.243079,-0.103833,0.335160,-0.602304,0.513069,-0.186463,-0.198588,-0.098315,-0.398240,0.088621,0.403991,0.652732,0.124335,-0.010219,0.243631,-0.602530,0.285494,0.668148,0.263864,-0.391010,0.478634,-0.137952,-0.374315,-0.446117,-0.357145,-0.684087,0.146907,0.398205,-0.184240,-0.137716,0.277397,-0.485790,0.103709,-0.090322,-0.315171,0.028153,-0.061829,-0.202564,-0.851215,-0.245553,-0.388787,-0.344501,-0.202040,0.018237,-0.362419,0.528130,-0.774159,0.172811,0.345627,0.162208,-0.127173,0.706383,-0.016366,0.079803,-0.220288,-0.267909,0.379628,0.006363,0.175928,-0.038532,0.268937,0.226890,-0.434085,0.029598,0.739167', '11541282', '1301686', '30229667', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292969', '光荣之路', '剧情', '1916年，第一次世界大战期间的法国，德法两军的战争如火如荼。值此关键时刻，法国陆军将军布洛拉德（Adolphe Menjou 饰）向陆军上尉达克斯（柯克·道格拉斯 Kirk Douglas 饰）率领的部队下了一道命令：不惜一切代价攻下德军占领的安特山。军令如山，即使前方刀山火海，战士们仍拼死向前冲去。结局可想而知，在敌人密集的炮火下，法军冲锋失败，伤亡惨重。为了掩盖自己的指挥失误，布洛拉德抓捕三名无辜士兵作代罪羔羊，以临阵脱逃等罪名将他们判处死刑。为了士兵的利益，达克斯上尉奋力争取，却在这一过程中渐渐看清军官和战争的丑恶……本片根据汉弗雷·科比（Humphrey Cobb）1935年的小说《光荣之路》改编荣获1959年意大利国家影评人协会银带奖最佳外语片导演奖、1958年芬兰影艺学院奖最佳导演奖。©豆瓣', '柯克·道格拉斯', '斯坦利·库布里克', 9.1, 48324, 'tt0050825', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p955392372.jpg', 0.2, 0.3, 5, 32.4, 62.1, '-0.170233,-0.170958,-0.425308,0.471678,0.388010,-0.060831,0.392591,-0.128763,-0.132343,0.075048,0.585457,0.581720,0.321702,-0.620522,0.620637,-0.347070,-0.576581,-0.812811,-0.216178,-0.079817,-0.165027,-0.298494,-0.478441,-0.447372,-0.027443,-0.557132,0.867358,0.178114,0.061750,0.493451,0.402768,0.320172,0.176367,0.185492,0.425512,0.149161,0.291558,-0.707906,-0.541302,0.392478,-0.232748,-0.528981,-0.559605,-0.057117,0.030543,0.334147,0.665474,-0.463700,0.364967,-0.202231,0.098719,-0.553680,0.158105,0.195227,0.394277,-0.171158,-0.013986,0.265208,0.183018,0.043555,-0.267247,-0.050017,-0.705214,-0.100999,0.027312,0.112074,-0.421299,0.326325,-0.303552,0.532467,0.165664,-0.178698,-0.209670,0.518008,0.201754,-0.023382,-0.510853,0.004412,-0.399092,0.362011,0.528264,-0.165272,-0.280926,-0.383245,-0.187482,-0.322281,0.087404,-0.516925,-0.446168,-0.152620,0.467891,-0.169384,0.306420,0.332745,-0.491150,-0.009381,-0.444809,-0.612083,-0.245560,-0.055878,-0.040611,-0.456209,0.247820,0.003737,-0.226277,0.354275,-0.042861,0.328809,0.668529,-0.246503,0.006322,0.667330,0.384995,-0.106126,0.496615,0.164218,0.337152,0.066577,-0.011529,0.280681,-0.019913,0.377897,0.236899,0.260388,-0.090883,-0.232057,0.065536,0.267528', '1478066', '1780122', '10467125', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292973', '小鸡快跑', '喜剧', '英格兰一个叫特维迪的养鸡场里，一出奴隶们的悲剧正在上演。养鸡场的主人特维迪太太贪得无厌，一心只想着让母鸡们多下蛋，而特维迪先生则带着两条狼狗在整天监视母鸡们的一举一动。要是哪知母鸡下的蛋少了，那她随时就会召来末顶之灾。母鸡们整天生活得提心吊胆，生怕哪天厄运就会降临到自己的头上。母鸡金婕聪明而且有胆识，她绝不屈服于这种奴隶般的生活，于是，她决心带领大家一起逃出养鸡场！©豆瓣', '菲尔·丹尼尔斯', '彼得·洛伊德', 7.6, 92767, 'tt0120630', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220719154.jpg', 0.2, 1.9, 32, 47.9, 18, '0.074765,-0.174308,-0.525419,0.239989,-0.133554,0.046034,0.417443,0.360351,-0.136181,0.220108,0.366661,0.451711,-0.073399,0.422863,-0.220961,-0.046176,-0.216236,-0.406054,-0.344208,0.174358,-0.166082,0.298100,-0.284159,-0.477017,-0.031516,0.140351,-0.039484,-0.061188,0.287272,0.089371,0.341365,0.209896,-0.104793,0.021954,-0.498601,-0.055593,0.003717,0.045909,0.130033,0.075182,0.028581,0.393083,-0.250865,-0.148472,0.216467,-0.189249,0.502074,-0.871510,-0.098945,-0.416150,0.114798,-0.287594,0.246917,0.433065,0.287289,-0.350327,0.319533,-0.142232,-0.163718,0.465616,0.049157,0.041207,-0.521264,-0.208573,-0.183093,0.320005,-0.504612,-0.273501,0.514994,0.223753,0.204408,-0.005080,-0.009555,0.147874,0.048700,0.441009,-0.003224,0.209568,-0.630079,-0.126073,0.667547,-0.153429,-0.027721,-0.087363,0.059967,0.153755,0.307018,-0.094902,-0.635365,-0.310494,0.104362,-0.338134,-0.396283,0.295361,-0.438385,0.449449,-0.101370,-0.119516,-0.036075,-0.336859,-0.303111,-0.369452,0.384226,-0.397555,-0.202196,0.414375,0.515737,-0.016380,0.651920,-0.326069,0.360073,0.460909,-0.052412,-0.499094,0.389030,-0.001475,0.103990,0.077622,-0.061436,-0.131233,0.031327,0.322139,0.380696,0.154967,-0.048910,-0.235654,0.085938,0.585693', '1428068', '1458910', '1305071', '34875369');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292977', '神探飞机头2', '喜剧', '浣熊行动的失败，使得艾斯·文图拉（金·凯瑞 Jim Carrey 饰）决定前往喜马拉雅山深处进行修行，锻炼自己避免再出现浣熊行动这样的事情出现。时间过得很快，一天艾斯突然收到邀请。非洲瓦查蒂族的神物——一只白色大蝙蝠不知所踪。他们希望艾斯重出江湖，帮他们找回这只白蝙蝠。一踏上非洲大陆，艾斯就立马展开了侦查工作。首先，艾斯将怀疑对象锁定在了野生动物园园长身上，可是却苦苦无法找到证据，只好作罢。接着他又怀疑是部落巫师偷走的，但是也是毫无头绪。在笑料百出的调查过程中，艾斯发现白蝙蝠原来在两个盗猎者手上，而其幕后首脑居然是大使。原来，为了独占蝙蝠粪这一稀有资源，他不惜挑起部族之间的矛盾，以此来从中渔利。最终，艾斯借助动物们的帮助，将白蝙蝠完璧归赵。©豆瓣', '金·凯瑞', '史蒂夫·欧德科克', 7.2, 18292, 'tt0112281', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2135598626.jpg', 0.9, 5.8, 42.4, 36, 14.8, '0.146902,0.214591,-0.494849,0.396356,0.168154,-0.302588,0.465155,-0.291337,-0.352793,-0.166428,-0.065744,0.568953,-0.066326,-0.039829,-0.031085,-0.011542,-0.341697,-0.562896,-0.113854,-0.067827,-0.347334,-0.359974,-0.465649,-0.471043,0.089650,-0.142007,0.543228,0.288572,-0.127304,0.388995,0.348220,0.192645,-0.313684,0.426318,-0.175164,-0.114908,-0.031008,0.105859,-0.051896,0.363520,0.107664,-0.178889,-0.023151,0.335349,0.112350,0.456629,0.489064,-0.548950,-0.213449,-0.371618,0.050678,-0.499014,0.042382,0.009983,0.700912,-0.027144,0.094001,-0.107958,-0.242855,0.051770,0.091076,-0.060429,-0.699773,-0.033982,-0.107460,0.281302,-0.412504,-0.103701,0.057368,0.061554,0.124646,-0.457949,0.068717,0.365234,0.536785,-0.192145,-0.167132,0.188826,-0.383655,-0.128936,0.576513,-0.271419,-0.003703,0.043585,-0.043923,-0.498532,0.078155,-0.238352,0.213846,-0.384191,0.463146,0.229872,-0.074397,0.042326,-0.873222,-0.211759,-0.372680,-0.267625,-0.094926,-0.301602,-0.107417,-0.171472,0.034382,-0.030979,-0.317303,0.209837,0.233360,-0.412184,0.413081,-0.755407,0.273227,0.526915,0.191744,-0.353366,0.401021,-0.228502,0.145083,-0.185697,-0.114594,0.017279,0.276900,0.457212,0.357953,0.035610,0.182503,-0.366152,-0.335107,0.197806', '25774050', '26290398', '2032339', '1292829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292981', '婚姻生活', '剧情', '律师玛丽安（丽芙•乌曼Liv Ullmann 饰）与精神学讲师约翰（厄兰•约瑟夫森Erland Josephson 饰）结婚十余载，育有两名女儿，生活幸福平稳。朋友皮特（金•玛思索Jan Malmsjö饰）与卡特里娜（毕比•安德森Bibi Andersson 饰）的婚姻生活却濒于解体。感慨万千的玛丽安发现自己怀孕，没曾想约翰竟倾向于打胎。有一天约翰突然向玛丽安提出自己爱上了一名叫宝拉的女子，二人痛苦分居。在协议离婚的过程中，二人的愤懑不满纷纷爆发，直到多年后，玛丽安与约翰才终于体会到爱情是什么。电视版本分六集，295分钟；电影版168分钟，获1975年金球奖最佳外语片奖，丽芙•乌曼提名金球奖及英国电影电视艺术学院奖最佳女主角。©豆瓣', '丽芙·乌曼', '英格玛·伯格曼', 9.1, 21940, 'tt0070644', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2037298187.jpg', 0.4, 0.6, 6.5, 30.8, 61.7, '-0.176123,-0.127142,-0.575604,0.401394,0.434070,-0.650137,0.558039,-0.109747,-0.207951,-0.416357,0.055451,0.783499,-0.664285,0.193866,0.459502,0.227125,-0.430400,-0.915565,0.228025,-0.106921,-0.121960,-0.648011,-0.067044,-0.207723,-0.035388,-0.451797,0.518605,-0.308303,0.173768,0.486732,0.634221,0.353544,-0.089011,0.022665,0.209802,0.415713,0.498449,-0.042493,-0.616003,0.069453,0.257034,-0.215209,-0.472785,0.007348,0.274906,0.149913,0.709689,-0.068777,-0.059004,0.296585,0.515481,0.031334,-0.264745,0.059716,0.258057,-0.180164,0.236282,0.176993,-0.166160,-0.058814,0.003357,-0.074174,-0.184128,0.205580,-0.080216,0.046803,-0.221866,0.186201,-0.175222,0.219351,-0.031634,-0.004174,-0.178301,0.329580,0.146828,0.378283,-0.293483,0.000967,-0.066578,0.432841,0.315026,0.133003,-0.454552,0.573746,0.026941,-0.489131,-0.256108,-0.058804,-0.593431,0.121590,0.481887,0.146552,0.076528,0.271143,-0.368145,-0.175710,-0.375842,-0.126637,0.320549,-0.055706,0.020092,-0.452934,-0.299152,-0.152923,-0.402187,-0.129847,-0.083218,-0.116697,0.665239,-0.535335,0.390076,0.084979,-0.029085,-0.401835,0.600446,0.129750,0.066086,-0.247312,0.167969,0.256621,-0.403666,-0.316889,0.242101,0.199938,0.016334,-0.049914,-0.278766,0.377082', '1307146', '1780122', '5262339', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1292994', '开罗紫玫瑰', '喜剧', '三十年代美国经济大萧条，市面上一片荒芜。家庭主妇Cecilia（米亚·法罗 Mia Farrow 饰）白天应对沉闷的服务生工作（由于经济崩溃 ，很快也失去这份工作），晚上面对毫无情趣的丈夫。身为狂热影迷的她日日走进影院观看一部叫《开罗紫罗兰》的电影，熟习到连台词表情都能记住，电影里没有经济萧条，电影里是上流社会的宴席与取乐。这日奇怪的事发生了，戏里面的男主角Tom（杰夫·丹尼尔斯 Jeff Daniels 饰）从荧幕上走了下来！直接走到Cecilia面前，和她私奔。而电影里的人物也跟着议论纷纷，剧情不按剧情走，而变成了讨论会。Cecilia与Tom去游乐园，互诉衷情，虽然一开始很浪漫，但后来发现这并不能填饱肚子，男主角Tom在现实中的扮演者Gil（杰夫·丹尼尔斯 Jeff Daniels 饰）也出现了 ，同样为了夺得Cecilia芳心与Tom展开比拼决斗。这个荒谬的闹剧将会如何结束？走进戏院观看电影的确会让人暂时忘怀现实世界的不快。', '米娅·法罗', '伍迪·艾伦', 8.7, 44932, 'tt0089853', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2218755965.jpg', 0.1, 0.6, 8.7, 43, 47.7, '0.413258,0.214257,-0.666386,0.314686,0.214371,-0.244483,0.875878,0.191520,-0.365999,-0.208378,0.136889,0.755140,-0.512404,0.162553,0.283665,-0.111241,-0.644797,-0.722145,-0.233226,0.006885,-0.142926,-0.247136,-0.257099,-0.189909,-0.177520,-0.033555,0.561335,0.297589,-0.394361,0.495270,0.299593,-0.106844,-0.099624,0.456680,0.172206,-0.137121,-0.067164,0.193757,-0.274145,0.234840,0.165692,-0.250520,-0.342027,0.157196,0.165182,0.249768,0.558845,-0.277095,-0.160019,0.169324,0.506879,-0.184388,-0.408254,0.096053,0.002085,-0.062397,0.228521,0.018403,-0.135191,0.266710,-0.174156,-0.250406,-0.600384,0.321335,-0.085936,0.439030,-0.434258,0.390185,-0.068075,-0.210906,0.018601,-0.202064,0.356600,0.189185,0.512002,0.496014,-0.123751,-0.070389,-0.554121,0.184309,0.666749,0.186306,-0.243595,0.512776,-0.114781,-0.407643,-0.189014,-0.333157,-0.319591,0.055915,0.027627,-0.050359,-0.016090,0.223798,-0.495170,0.305182,0.104890,-0.549967,-0.123617,-0.376907,-0.141344,-0.822336,-0.218996,-0.344559,-0.317530,-0.042120,0.107254,-0.185832,0.706918,-0.727933,0.002252,0.171115,0.219389,-0.420766,0.717808,0.035022,0.059345,-0.152218,-0.050402,0.124601,-0.309661,0.400396,0.023249,0.261351,-0.070399,-0.416977,-0.620588,0.562099', '3055049', '30162520', '1296534', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293004', '告别有情天', '剧情', '史蒂芬斯先生（安东尼·霍普金斯 Anthony Hopkins饰）是一个忠实的仆人，他曾经当过英国著名爵侯的管家。目前正一心一意打理新主人达林顿勋爵的公馆，成为这里的大管家。这里来了一个女管家基顿（艾玛·汤普森 Emma Thompson饰），她精明能干，操持起家务来比史蒂芬斯更灵活，起初斯蒂芬斯常常与她有些小矛盾。但是随着相处日子渐长，善良的基顿还是暗暗打动了史蒂芬斯。尽管基顿一再流露真情，举手投足间泄露了爱意。但是每到动情关头，史蒂芬斯都隐忍着自己的情感，对基顿的爱化作一段埋没在静默中的故事。基顿忍痛告别这段无果之爱，远走他乡嫁为人妇。当时光荏苒，二人再次会面，心里的爱意仍然说不出口，浓浓思念化作车站道别的一句祝福。©豆瓣', '安东尼·霍普金斯', '詹姆斯·伊沃里', 8.3, 21713, 'tt0107943', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1056237302.jpg', 0.2, 0.8, 15.5, 52, 31.5, '0.289873,0.084221,-0.699609,0.695977,-0.019396,-0.611057,0.655902,-0.151097,-0.390653,-0.489892,0.210173,0.883323,-0.410091,0.508162,-0.075128,0.042644,-0.104926,-0.448931,0.046827,-0.443237,0.159215,-0.559971,-0.114330,-0.105713,-0.378144,0.098963,0.443391,-0.052047,0.249893,0.520062,0.263799,0.239930,0.373058,0.309876,0.025560,0.184250,-0.008271,-0.011329,-0.404382,-0.141859,0.292988,0.072202,-0.304740,0.032858,0.157733,0.357034,0.458181,-0.346612,0.038209,0.063886,0.421030,-0.127431,0.287065,0.098435,0.045148,0.051899,0.090379,0.240266,-0.508301,-0.153429,-0.035927,-0.084185,-0.368043,-0.033985,0.014790,0.138612,-0.408170,-0.020676,-0.170064,-0.035057,0.147814,-0.353811,-0.041593,-0.063757,0.256509,0.494197,-0.123033,0.191027,-0.096793,0.156128,0.550191,0.062686,-0.275690,0.335280,-0.401597,-0.105807,0.289966,-0.167707,-0.695613,-0.234728,-0.067338,0.109488,0.213161,0.605034,-0.348106,-0.041344,-0.328591,0.208977,0.157748,-0.584379,-0.043280,-0.474059,-0.333168,-0.379524,-0.195292,0.173456,0.061855,0.036934,0.596289,-0.666410,0.232528,0.422348,0.253318,-0.257950,0.518089,0.357779,0.081009,-0.053794,-0.030341,0.812423,-0.037316,-0.171758,0.194376,0.334862,0.037926,0.214914,-0.313200,0.291958', '1292720', '1460341', '1293868', '1296824');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293013', '独立日', '动作', '未来某年的7月2日，美国各地的监视站发现一艘直径达数百英里的巨大飞船接近了地球。飞船发出的无线电信号干扰了地球的通信卫星信号，并放出了多艘直径达15英里的子飞船飞抵地球上各大城市的上空。外星飞船敌友未明，人们陷入了恐慌和迷惑。电脑工程师戴维（杰夫•戈德布拉姆 饰）破译出外星人发出的无线电信号，其实是攻击的倒计时信号，他设法通知了前妻，总统的助理康妮，但是为时已晚，7月3日，外星人的飞船开始攻击地球，人类文明瞬间遭到巨大的打击和灾难。总统（比尔•普尔曼 饰）等人撤离到军事基地，指挥空军反击，却犹如以卵击石，毫无作用，军事基地也被摧毁，唯有飞行员史蒂文（威尔•史密斯 饰）设法诱使一架外星人战斗飞艇坠毁。幸存者们逃到了秘密军事基地，在那里，科学家们一直在研究一艘50多年前坠毁的外星飞艇，致力于找出对付外星人的办法，那里也是人类最后的希望……©豆瓣', '威尔·史密斯', '罗兰·艾默里奇', 8.1, 273394, 'tt0116629', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453518655.jpg', 0.4, 1.8, 19.9, 49.1, 28.8, '0.035650,-0.011378,-0.895391,0.577329,0.068468,0.113716,0.413571,-0.107861,-0.397190,0.094657,0.218736,0.511904,-0.128258,-0.065874,0.119468,0.143334,-0.665227,-0.341572,-0.120639,-0.314892,-0.499849,-0.493666,-0.327082,-0.551913,0.375297,-0.378779,0.507021,0.292712,-0.122961,0.176100,-0.239393,0.259228,-0.209907,0.547261,0.062006,-0.249673,-0.016600,-0.478672,-0.189165,0.088420,-0.474020,-0.011052,0.267162,0.105685,-0.104629,0.484330,0.621048,-0.431835,0.133481,-0.318192,-0.089575,-0.378057,0.171951,-0.057959,0.555139,-0.002779,-0.414165,-0.215234,-0.013711,0.014966,0.094710,0.193656,-0.371102,0.104270,-0.488784,0.043021,-0.073305,0.030685,-0.590366,0.239444,-0.127667,-0.130718,0.225977,0.475417,-0.078762,0.206947,-0.448390,0.422134,-0.652723,-0.078919,0.325360,-0.011762,-0.714080,-0.039634,0.130161,-0.509096,-0.439687,-0.295022,-0.137112,-0.322421,0.474475,0.034738,-0.200483,0.151837,-0.698954,0.222737,-0.539918,-0.572698,-0.044281,-0.324856,-0.290643,-1.272709,0.360387,-0.118637,-0.115702,0.405886,0.105934,0.196908,0.747116,-0.415379,0.130917,0.782015,0.427859,-0.123692,0.619993,-0.215553,-0.254931,-0.249831,0.220179,0.175777,-0.106030,0.717157,-0.019303,0.045538,0.197399,-0.173121,-0.136170,0.115668', '1300868', '349