INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293019', '海滩', '剧情', 'Richard（Leonardo DiCaprio）是位酷爱网上冲浪和冒险的美国年轻人，一天，他来到泰国曼谷，欲找寻在网络上得知的人间天堂海滩。在投宿的廉价旅馆里，他遇到法国女孩Franoise（Virginie Ledoyen）和其男友，三人成了朋友，不久Richard爱上Franoise。Richard从诡异的光头佬那里得到一些听来奇怪的秘密，随后光头佬留下一张神秘地图意外死去，这激起Richard的好奇心，按图索骥一番追踪，他确信海滩的确存在，开始说服Franoise和其男友同他一起去找寻海滩，并复制了一份地图供另外认识的美国朋友前去探险。克服了种种困难，Richard三人来到疑似海滩乐园的地方，可是呈现在他们眼前的只有大片大片的大麻地和持枪的泰国农人，逃命之际，他们终于走进梦想中的天堂，那里的人们在Sal（Tilda Swinton）的带领下，过着无忧单纯的近似原始社会的生活。Richard三人的到来令泰国农人对Sal发出警告：海滩不准再添人。这句话随后成谶语。', '莱昂纳多·迪卡普里奥', '丹尼·博伊尔', 7.7, 31147, 'tt0163978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p461627296.jpg', 0.3, 2.8, 30.7, 46.6, 19.7, '0.453759,-0.007652,-0.927491,0.575222,-0.165091,-0.078259,0.748538,-0.184466,-0.444841,0.086111,0.151711,0.876632,-0.174672,0.378444,0.473788,0.115351,-0.433158,-0.522513,-0.023939,-0.359027,-0.306352,-0.368209,-0.398688,-0.330577,-0.114079,-0.206501,0.483515,0.316197,-0.227543,0.692005,0.137205,0.206499,-0.431277,0.494543,-0.449510,0.058931,-0.052627,0.123255,-0.353999,0.305846,0.004874,-0.181584,-0.104758,0.112617,0.004278,0.211746,0.746861,-0.154714,-0.249992,0.045762,0.152868,-0.101898,-0.050824,0.064918,0.337538,0.067221,0.240779,0.162185,-0.073933,0.073273,-0.025679,0.039228,-0.433075,-0.032141,0.054851,0.253784,-0.489093,0.234667,-0.042871,-0.172306,0.108784,-0.338529,0.431386,0.264078,0.118787,0.410017,0.004601,0.093682,-0.515177,0.158484,0.673090,0.126940,0.006342,0.115417,-0.007091,-0.275390,0.200781,0.140414,-0.161976,-0.086426,0.216215,0.088810,-0.451509,-0.215034,-0.802477,0.216985,-0.008578,-0.244260,0.165276,-0.200624,-0.289271,-0.837110,-0.052555,-0.222284,-0.031384,0.257158,-0.078852,-0.072936,0.628536,-0.642059,0.159087,0.597220,0.560331,-0.317297,0.698944,-0.035521,0.048304,-0.245487,-0.197161,0.209861,0.081019,0.574123,-0.039020,0.257360,-0.105294,-0.035983,-0.581684,0.328821', '34461680', '1303333', '3055049', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293028', '稻草狗', '剧情', '为了静下心来研究学问，老实木讷的数学家大卫•萨莫（Dustin Hoffman 达斯汀•霍夫曼 饰）协同妻子艾米（Susan George 苏珊•乔治 饰）回到位于英国乡村的老房子。艾米性感大胆的穿着引来村中男人们粗鄙的目光，而大卫看似懦弱的外表更让他们有恃无恐。某日，他们借打猎之名将大卫引出家门，随后对艾米进行轮奸，面对这种种羞辱，大卫只能强颜欢笑。某晚，低能儿尼尔斯误杀心仪的女孩，仓皇中他逃入大卫的房子。愤怒的村民要求大卫交出尼尔斯，在被拒绝之后，他们试图强行进入。愤怒的大卫忍无可忍，大开杀戒……©豆瓣', '达斯汀·霍夫曼', '萨姆·佩金帕', 7.6, 9628, 'tt0067800', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2196478070.jpg', 1, 3.7, 29.5, 48.3, 17.5, '0.328584,-0.143888,-0.629962,0.253778,-0.319483,-0.365987,0.657022,0.114054,-0.475024,-0.261766,0.374048,0.619476,-0.189940,0.119590,0.068719,0.032478,-0.528452,-0.295576,0.041638,-0.108432,0.168083,-0.470969,0.101904,-0.408212,0.076996,-0.251315,0.298486,-0.138193,-0.354218,0.499984,0.275312,0.701749,0.151331,0.270654,-0.030443,0.027282,0.265378,-0.360766,-0.324994,0.097918,-0.046187,0.116242,-0.209842,0.294983,-0.229240,0.317964,0.663830,-0.138051,-0.191206,-0.086698,0.298145,-0.118819,0.031674,0.456509,0.018505,-0.130249,0.147416,0.071988,-0.048682,-0.114328,0.250010,0.083300,-0.330732,0.287079,0.043403,0.090939,-0.327528,0.132927,-0.163929,0.143061,0.192294,-0.356049,-0.263354,-0.006110,0.232688,0.244889,0.036130,0.119123,-0.231215,-0.064104,0.295509,0.001114,0.004511,-0.003542,-0.258193,-0.201496,0.616254,-0.387145,-0.746535,-0.083277,0.515469,-0.234602,0.011011,0.145639,-0.451603,-0.183551,-0.397572,0.058978,-0.047201,-0.245256,-0.261620,-0.747512,-0.106802,-0.191609,-0.213952,-0.212526,-0.025654,-0.088399,0.446610,-0.433385,0.201031,0.518972,0.498693,-0.234399,0.212055,-0.078046,0.036602,-0.062666,-0.361390,0.468575,0.296212,0.241457,-0.031524,0.337252,-0.045052,-0.192311,-0.243294,0.309085', '1316693', '10466639', '2269893', '2364001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293030', '苏姗娜的故事', '剧情', 'Bertrand（Philippe Beuzen 饰）和Guillaume（Christian Charrière 饰）是巴黎医学院的同学，前者是个勤奋的穷学生，后者则是个父母经常不在家留下豪宅供儿子玩乐的富家公子。一次在咖啡店他们遇到女孩Suzanne（Catheri ne Sée 饰），他们都对Suzanne倾心，但Bertrand因为自己的身世并没有展开主动的追求，反而是一直看着Guillaume如何把Suzanne骗到手打得火热。花花公子很快便玩厌了，与Suzanne分手，Suzanne开始主动约Bertrand出来游玩挥霍，很快便花光了钱。而Bertrand的钱却被偷了……Suzanne是复仇女郎吗？©豆瓣', 'Catherine Sée', '埃里克·侯麦', 7.2, 11129, 'tt0056910', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2202641383.jpg', 0.3, 2.7, 43.9, 42.7, 10.4, '0.434467,-0.268848,-0.516459,0.440757,-0.771362,-0.545314,0.640749,-0.079404,-0.401987,-0.227418,-0.118458,0.791211,-0.126102,0.331296,0.004426,0.108927,-0.165158,-0.621614,0.065414,-0.164456,-0.106893,-0.416051,0.094540,-0.025775,-0.108583,-0.032454,0.315511,-0.130380,0.010579,0.651274,0.466974,0.195656,0.036231,0.672220,-0.396674,-0.019112,-0.187530,0.315154,0.022391,0.392575,0.141334,-0.323817,-0.178831,0.126467,0.243154,0.422193,0.676637,0.054984,-0.204802,-0.044658,0.289533,-0.150209,0.054122,0.112092,0.251777,-0.209738,0.467735,0.036323,-0.233241,0.101748,0.277681,-0.120005,-0.622091,0.005562,0.321624,-0.052827,-0.697136,0.660648,-0.073510,-0.289255,-0.070322,-0.379737,0.202384,0.326001,0.199183,0.247822,-0.203361,-0.093322,-0.911410,0.381816,0.657279,0.202069,0.143383,0.609826,-0.089642,-0.230915,0.318594,-0.191627,-0.497140,0.074977,0.170485,0.092125,-0.068511,-0.062684,-0.576261,0.054942,-0.110218,-0.163116,0.355795,-0.727795,-0.076868,-0.388662,-0.036242,-0.517303,-0.328835,0.112768,0.179997,-0.226285,0.672641,-1.042046,-0.004206,0.683493,0.540022,-0.841256,0.909303,0.043776,-0.227711,0.031122,0.005407,-0.222728,0.265128,0.164916,0.187135,0.260593,0.222467,-0.313949,-0.076923,0.586262', '1853752', '1308755', '2124718', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293031', '曼哈顿谋杀疑案', '喜剧', '豪斯夫人（林·科恩 Lynn Cohen 饰）的死让目击者拉里（伍迪·艾伦 Woody Allen 饰）起了疑心，因为作为死者的丈夫，保罗（杰里·阿德勒 Jerry Adler 饰）不仅没有表现出一丝的伤心，更是和一名叫海伦（Melanie Norris 饰）的美丽女子 来往密切。在好友特德（阿伦·阿尔达 Alan Alda 饰）的帮助下，拉里开始了对于保罗的跟踪调查，但很快拉里便发现，特德和自己的妻子卡罗尔（黛安·基顿 Diane Keaton 饰）似乎有着暧昧的关系。随着调查的深入，事件的真相逐渐浮出了水面，为了掩盖自己所犯下的罪行，保罗绑架了卡罗尔，以此威胁拉里。在众人的搀和下，事情变得越来越复杂，而拉里唯一要做的，就是救出妻子。©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 8.2, 9022, 'tt0107507', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2083734431.jpg', 0.4, 1.4, 17.7, 50.4, 30.1, '0.242870,-0.142760,-0.676178,0.664733,-0.094347,-0.541840,1.011991,0.144896,-0.517127,-0.300430,0.034344,0.690189,-0.203452,0.170432,0.222281,0.064557,-0.466891,-0.727151,-0.009260,-0.263683,-0.079277,-0.846336,-0.325168,-0.516305,0.076125,-0.550152,0.473627,-0.103743,-0.161026,0.402497,0.462342,0.495511,0.114278,0.458731,0.193863,0.113918,0.122446,-0.092330,-0.340650,0.033702,0.302688,-0.332841,-0.171118,0.264036,0.009263,0.693542,0.394761,-0.549712,-0.289700,0.012397,0.405651,-0.240940,0.328320,0.080084,0.182138,-0.157013,0.098941,0.365838,-0.377699,-0.294373,0.294186,0.008894,-0.716330,0.234125,0.249447,0.526512,-0.494463,0.053158,-0.388402,-0.143569,0.228486,-0.242152,0.147507,0.319239,0.149602,0.120551,-0.351313,-0.059202,-0.378097,0.005153,0.452614,0.220502,0.001581,0.112255,-0.507413,-0.201106,-0.085628,-0.026405,-0.314956,-0.065946,0.520523,0.099524,0.202935,0.578681,-0.255563,-0.391703,-0.368252,-0.289574,-0.227633,-0.369125,0.064304,-0.472263,-0.282076,-0.374139,-0.419443,-0.095333,0.055691,-0.328841,0.358440,-0.814323,0.213375,0.488743,0.045232,-0.388167,0.292465,0.035008,0.157486,-0.112134,-0.315613,0.280419,-0.040746,0.029866,0.215422,0.457019,0.161813,-0.224977,-0.134373,0.511721', '10546747', '1307748', '26930375', '1293145');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293034', '遮蔽的天空', '剧情', '作曲家波特（约翰·马尔科维奇 John Malkovich 饰）和作家妻子姬特（德博拉·温格 Debra Winger 饰）在二战后携两人的朋友雷纳（坎贝尔·斯科特 Campbell Scott 饰）一起来到北非撒哈拉旅行。在神秘而捉摸不定的沙漠中，波特和姬特的婚姻危机似乎也因此得到了异样 的缓和——波特流连于和当地的妓女寻欢，而姬特却和雷纳发生了关系。在夫妻关系的断裂中，波特和姬特重新意识到对方对自己的重要性。然而此时波特不幸染上霍乱，姬特带着他辗转奔袭在撒哈拉，严酷的沙漠吞噬了希望，最终波特还是离姬特而去。姬特在悲痛中阴差阳错跟随一支驼队继续在沙漠中踯躅，并成为驼队的女人，在无尽的沙漠中渐行渐远……©豆瓣', '德博拉·温格', '贝纳尔多·贝托鲁奇', 7.9, 6442, 'tt0100594', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2480929112.jpg', 0.5, 2.6, 23.5, 47.5, 25.8, '0.310409,0.164270,-0.931863,0.702725,0.271150,-0.537325,1.077468,-0.008804,-0.330056,-0.131420,0.281925,0.870033,-0.132594,-0.008195,0.398423,0.089576,-0.450002,-0.901326,0.160933,-0.117722,-0.438822,-0.851552,-0.840726,-0.261738,-0.051603,-0.539967,0.642827,0.346166,-0.235286,0.762315,0.158310,0.602809,-0.373951,0.588024,-0.294709,0.171756,0.118133,0.172607,-0.561491,0.120678,0.217165,-0.181351,-0.505590,-0.089498,0.173964,0.364078,0.777903,-0.473697,0.063980,0.193272,0.047818,-0.209660,-0.086447,0.163445,0.244833,-0.356201,0.067179,0.247861,-0.160645,0.178643,-0.249746,0.151148,-0.577808,0.218655,-0.024140,0.555205,-0.618438,0.879957,-0.042085,-0.297060,0.330354,-0.193800,0.423570,0.214906,0.030309,0.276541,-0.317682,0.109934,-0.504554,-0.214717,0.459499,-0.087171,-0.242417,0.232879,-0.320274,-0.491955,-0.139945,0.065679,-0.422039,-0.121094,0.403977,0.131968,-0.263399,0.609856,-0.944744,-0.084718,-0.335819,-0.313398,-0.071041,-0.268527,-0.130470,-0.525604,-0.032703,-0.619607,-0.232251,0.224893,0.042889,-0.257226,0.376453,-0.957852,0.256703,0.317246,0.194197,0.016889,0.552226,-0.187942,0.315439,-0.219117,-0.170335,0.540485,0.078827,0.251210,0.291391,0.261171,0.149506,0.166732,-0.309643,0.744606', '3111650', '6827727', '21442760', '2971730');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293035', '鬼娃新娘', '惊悚', '在查尔斯·李·雷伊将灵魂注入公仔十年后，他当年的女友蒂芬妮（珍妮佛·提莉 Jennifer Tilly 饰）多年不懈寻找他的下落，终于买通警察将玩偶“楚其”的残体带出，蒂芬妮凭借不熟练的伏都仪式，将缝合的楚其再次唤醒。然而觉醒的楚其对蒂芬妮并无爱意，伤心的蒂芬妮将楚其禁锢，不想却被楚其把她的灵魂移入了另一个女玩偶的体内。两个玩偶要恢复人类身体，就必须找到埋藏在查尔斯·李·雷伊坟墓中的护身符。于是他们盯上了一对儿被长辈阻挠的恋人杰德（凯瑟琳·海格尔 Katherine Heig 饰）与杰西。两个玩偶委托后者驾车将它们送去埋葬雷的坟场，同时一路大开杀戒，私奔的杰德与杰西惊觉自己陷入了玩偶情侣的掌控……©豆瓣', '詹妮弗·提莉', '于仁泰', 6.8, 9747, 'tt0144120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1688600995.jpg', 1.5, 8.5, 48.1, 30.6, 11.3, '0.283732,0.194158,-0.456932,0.670557,-0.234889,-0.464872,1.101125,-0.154591,-0.368374,-0.269728,-0.110828,0.526269,-0.392190,0.404049,0.036946,0.218038,-0.161810,-0.788304,-0.328537,0.117799,-0.710299,-0.399515,-0.267270,-0.428493,-0.331100,-0.289471,0.449546,-0.116842,-0.165894,0.013829,0.291896,0.305917,-0.271025,0.463125,-0.122087,0.243987,-0.131422,-0.090425,-0.041268,0.242905,0.260017,-0.185883,0.200044,0.227298,0.179562,0.218119,0.976380,-0.414415,0.475173,-0.184452,0.253818,-0.356912,0.062246,0.090063,-0.022615,-0.051645,-0.150451,-0.242356,-0.308247,-0.200045,0.490405,-0.292788,-0.595225,-0.186484,-0.010447,-0.011226,-0.591608,0.077759,-0.122316,0.467843,0.016392,-0.445248,0.029063,0.361046,0.031094,0.171024,-0.042607,-0.155990,-0.520278,0.112492,0.353795,-0.022550,-0.202006,0.108659,-0.477193,-0.635811,-0.193338,0.173020,-0.272678,-0.356970,0.991184,0.272189,0.104044,0.233090,-0.512463,-0.838704,-0.426350,-0.026670,0.102396,-0.552000,0.088065,-0.528917,-0.085250,-0.355581,-0.088213,0.174381,0.210178,-0.273204,0.413405,-0.611606,0.435065,0.500315,0.117676,-0.232973,0.362741,-0.438472,0.265593,-0.267538,0.196091,0.598238,0.424488,0.309303,0.702175,0.459624,-0.049850,0.457061,-0.646998,0.641531', '1578663', '21619567', '1467779', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293045', '肮脏的哈里', '动作', '哈里（克林特·伊斯特伍德 Clint Eastwood 饰）是美国旧金山的一名资深警察，警局总是把一些难以解决的案件抛给他，而他为了破案也不惜使用一些非法的手段，因此他得到了一个绰号——“肮脏的哈里”。旧金山出现了一个无差别射杀魔，在第一个受害者遇难的同时，凶手留下了一封恐吓信，要求获得10万美元的现金，否则，每过2小时，他将射杀一个市民。随着受害者的增加，无能的政府决定向凶手妥协，但哈里不能接受这样的妥协，他擅自行动逮捕了凶手，却也导致了人质的死亡。令他意想不到的是，好不容易捉拿归案的凶手，竟然因为精神方面的疾病逃脱了法网，之后变本加厉劫持了一辆载满儿童的校车。这次，愤怒的哈里再也不能忍耐了，他展开了同凶手的周旋，并在最后时刻射出了那颗代表着正义的子弹。©豆瓣', '克林特·伊斯特伍德', '唐·希格尔', 7.7, 6102, 'tt0066999', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1341966214.jpg', 0.3, 1.8, 28.7, 51.1, 18.2, '0.316441,0.088605,-0.466046,0.683853,-0.461728,-0.213913,0.757008,0.027733,-0.340768,-0.048618,0.438210,0.791823,-0.009806,-0.079955,0.094816,-0.109796,-0.152715,-0.608007,0.017227,-0.280820,-0.443928,-0.542428,-0.234198,-0.391888,-0.092141,-0.059086,0.485958,0.159991,-0.136094,0.343503,0.412927,0.348598,0.172533,0.536216,-0.105053,-0.118629,-0.015469,-0.400910,-0.062821,0.488021,0.257154,-0.464416,0.173784,0.531518,-0.277672,0.581543,0.737658,-0.146316,-0.238376,-0.184477,0.410364,-0.611665,0.058194,0.115661,0.243583,-0.032312,-0.062092,0.253561,-0.357029,-0.082587,0.255124,0.340191,-1.068996,-0.117788,-0.065306,0.078646,-0.532633,0.385307,-0.418112,0.193904,-0.009646,-0.264788,0.094348,0.512793,0.170814,0.054982,-0.421676,-0.193457,-0.698957,0.116070,0.501987,-0.412334,-0.244513,0.113970,-0.320313,-0.535743,0.103703,-0.414297,-0.255401,-0.095567,0.708323,0.064171,-0.400303,0.130242,-0.503044,-0.341344,-0.578647,-0.219218,-0.193676,-0.439956,-0.064679,-0.403020,0.112323,-0.039625,-0.373364,0.095096,0.124421,-0.159964,0.754793,-0.612242,0.150793,0.967397,0.398931,-0.547342,0.442400,0.174881,0.064362,-0.012709,-0.066570,0.090640,0.493764,0.678409,0.218327,0.169241,0.156048,-0.286371,-0.195676,0.336133', '3785918', '5973984', '4820775', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293046', '热泪伤痕', '剧情', '疗养院的老太太薇拉连人带轮椅滚下了楼梯，当场毙命。护理她的保姆桃乐丝（凯西•贝茨 Kathy Bates 饰）手持凶器站在旁边。桃乐丝是唯一的嫌疑人。原来，桃乐丝是薇拉雇佣了40年的女佣，由于她饱受主人的责骂和变态要求，所以这起案件很容易被导向怀恨在心、伺机报复的谋杀。警方一直想把她定罪，判处她20年徒刑。这个案子惊动了桃乐丝远在纽约做记者的女儿莎琳娜（詹妮弗•杰森•李 Jennifer Jason Leigh 饰）。她亲自参与案件的追踪，再度与离散多年的母亲重逢，共同生活了几日。这令她不得不回首阴暗往事，而桃乐丝也总是恍然回忆起女儿小时候的样子。与此同时，一个恶魔般的身影也随之被记忆唤醒。那是她的丈夫，经常对她实施暴力。在忍无可忍之际，她做出了最后的反击……©豆瓣', '凯西·贝茨', '泰勒·海克福德', 8.6, 15427, 'tt0109642', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2151462240.jpg', 0.2, 0.6, 10.3, 45.3, 43.5, '0.298316,-0.129302,-0.603703,0.322512,-0.428593,-0.068687,0.798153,0.141741,-0.632189,-0.147698,0.518992,0.745967,-0.280287,0.393884,0.173191,0.132783,-0.244228,-0.814916,0.096464,-0.021830,-0.364930,-0.389110,0.063587,-0.308708,0.015881,-0.299395,0.311441,-0.269323,0.069895,0.400146,0.276156,0.385214,-0.022033,0.548064,-0.000787,0.130047,0.086109,-0.123391,0.024629,0.128908,0.277171,-0.619762,-0.172719,0.181168,-0.086396,0.451553,0.546783,-0.202602,-0.060427,-0.025399,0.255774,-0.588624,0.047996,0.117841,0.397582,-0.257566,-0.043273,0.300647,-0.410018,-0.369072,0.183864,0.060255,-0.473153,0.169695,0.041609,-0.072769,-0.636646,0.249288,-0.275252,0.440647,0.067766,-0.208064,0.066052,0.297042,0.115642,0.326475,-0.171809,-0.067615,-0.345519,0.335574,0.462891,-0.060165,-0.154797,0.321223,-0.368452,-0.265483,-0.098607,-0.143456,-0.326214,-0.154622,0.467337,-0.081526,-0.362084,0.210005,-0.290758,-0.174397,-0.361012,-0.096010,-0.007638,-0.372186,-0.320334,-0.251742,-0.204197,-0.313529,-0.305172,-0.168695,-0.308355,-0.167074,0.460431,-0.650101,0.266045,0.566372,0.312119,-0.559914,0.667533,-0.008797,0.048494,0.012522,0.076038,0.308833,0.087868,0.265668,0.345339,0.168435,0.096456,-0.002739,-0.280938,0.350388', '3111650', '1293142', '1302384', '1292217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293050', '永不妥协', '剧情', '埃琳•布罗克维奇（朱莉娅•罗伯茨 Julia Roberts 饰）是倒霉鬼中的典型。她结过两次婚，但每次婚姻都没有给她带来幸福，反而令她成了一个拖着三个孩子的单身母亲。倒霉的她在遭到一场交通事故后，连志在必得的赔偿官司到最后都输掉了。为她辩护的律师埃德（阿尔伯特•芬尼 Albert Finney 饰）半是同情埃琳半是因为帮她打输了官司心感内疚，收留了埃琳在他的律师楼里打杂。埃琳的生活算是有了一点保障。在调查一单污水申诉案时，埃琳偶然发现了污水中含剧毒物质，而供水公司确对此敷衍了事。弱女子埃琳决定用她柔弱的肩膀担负起为受污染的数百名居民讨回公道的重担！©豆瓣', '朱莉娅·罗伯茨', '史蒂文·索德伯格', 8.4, 86114, 'tt0195685', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217301518.jpg', 0.1, 0.6, 12.9, 50.2, 36.3, '-0.050628,0.019694,-0.590876,0.317295,-0.457805,-0.253180,0.676732,0.151089,-0.392828,-0.001581,0.340346,0.551455,0.019165,0.120531,0.150671,-0.060186,-0.058480,-0.476690,0.062080,0.045698,-0.434655,-0.560336,-0.054115,-0.353401,-0.337591,-0.222900,0.226017,0.067683,0.040356,0.256022,0.347106,0.291869,0.310045,0.585547,-0.101032,0.249997,-0.000030,-0.017827,-0.074403,0.297582,0.171662,-0.176544,-0.152349,0.245904,0.180928,0.689555,0.462016,-0.098667,-0.042591,-0.132253,0.375662,-0.372757,0.130497,0.159820,0.283148,-0.016292,0.266865,0.207018,-0.453667,-0.068335,0.630319,0.015064,-0.580937,-0.095089,0.141495,0.101758,-0.741195,0.713721,-0.189425,-0.071223,-0.118463,-0.120283,0.093576,0.143884,0.092267,0.290976,-0.174274,0.117781,-0.653937,0.239890,0.437389,-0.040513,-0.068737,0.302062,-0.398271,-0.207524,0.177148,-0.415052,-0.478768,0.133549,0.313383,-0.277954,-0.118350,0.304139,-0.536201,-0.281638,-0.348922,-0.233012,-0.210364,-0.475649,-0.049088,-0.272379,-0.058734,-0.180946,-0.385859,0.031699,0.175260,-0.425640,0.243586,-0.728905,0.129482,0.518645,0.123601,-0.507624,0.533577,0.304232,0.395636,0.030161,-0.014161,0.166113,-0.029401,0.252558,0.509887,0.291449,0.156046,-0.004706,-0.079857,0.335374', '1299965', '1306801', '1308755', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293071', '野草莓', '剧情', '伊萨克（维克多·斯约斯特洛姆 Victor Sjöström饰）从医50年，现年已是将近八十岁的高龄，正准备在儿媳的陪伴下返回母校接受荣誉学位颁发。路上伊萨克顺道重游旧地，追忆往事。伊萨克曾经和堂妹萨拉（毕比·安德森 Bibi Andersson饰）有过美好的初恋，却因性格冷酷孤僻，以致他的兄弟乘虚而入。如今伊萨克坐在草坪上，忆起往昔，眼前浮现萨拉白衣飘飘的美丽模样。他与生俱来的冷漠理智的性格，注定了婚姻的失败。伊萨克的妻子无法忍受冰冷的婚姻，寻求外遇。这样的家庭气氛，加上遗传下来的冷漠秉性，使得伊萨克的儿子不愿生小孩，和儿媳关系决裂。伊萨克获得了光荣的学位荣誉，然而他仍然沉浸在对过往沉重的自省中，对于生命将尽的老人，这仿佛是一次心灵救赎之旅。©豆瓣', '维克多·斯约斯特洛姆', '英格玛·伯格曼', 8.8, 61329, 'tt0050986', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p540202708.jpg', 0.2, 0.7, 8.6, 39.7, 50.8, '0.094755,0.137709,-0.600210,0.697064,-0.402074,-0.553636,0.951738,0.287951,-0.714605,-0.275167,0.232180,0.616646,-0.009236,0.457460,0.461123,-0.123691,-0.078205,-0.640165,-0.316836,-0.043697,-0.134304,-0.540351,-0.262751,0.045602,-0.113702,-0.602416,0.813965,0.031257,0.053188,0.601433,0.169593,0.416118,0.073793,0.284163,-0.142303,-0.114737,-0.074781,0.253831,-0.467439,-0.086428,0.236535,-0.016862,-0.009419,0.129540,-0.176229,0.307170,0.736925,-0.236689,-0.127177,-0.266888,0.483002,0.083144,-0.132661,0.355709,0.070864,0.163142,0.010394,0.540271,-0.081474,-0.270472,-0.014808,-0.089939,-0.598152,0.072705,0.033445,0.254844,-0.616728,0.756253,-0.247571,-0.006415,0.066080,-0.180779,-0.043235,0.084657,0.401784,0.524166,-0.226651,0.210201,-0.167097,0.139906,0.712998,0.128638,-0.323194,0.519630,-0.700507,-0.176436,0.114739,-0.419146,-0.668597,-0.046416,0.033340,0.060224,0.036436,0.606781,-0.326796,-0.112608,-0.264203,0.036566,0.042830,-0.478086,-0.277868,-0.193544,-0.352444,-0.558832,-0.464266,0.161933,0.036354,-0.315059,0.598734,-0.667139,0.473895,0.292795,0.127187,-0.179583,0.647739,0.272048,0.126532,-0.411236,-0.089971,0.853621,-0.176398,0.012797,-0.118010,-0.096686,-0.306578,0.112780,-0.337746,0.854893', '1296992', '1305666', '26245360', '2131640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293072', '007之诺博士', '动作', '英国政府派007邦德（肖恩·康纳利 Sean Connery 饰）前往加勒比海调查一桩情报人员被杀案件，007几经调查，推测死者应该与蟹礁岛上的诺博士有关。诺博士在这个神秘的小岛上正进行着不为人知的阴谋计划，紧锣密鼓进行一项将要统治世界的科学实验。双方开始了斗智斗勇的战 争，诺博士派来了女间谍，企图监测007的一举一动乘机将其制服，不料反被007识破诡计。而渔民库洛及潜水员莱特（乌苏拉·安德丝 Ursula Andress 饰）成为了007的得力助手，然而，诺博士对007此行早有准备，007与美女助手陷入重重困境。眼看007就要葬身荒岛，事情却来了惊天逆转。©豆瓣', '肖恩·康纳利', '特伦斯·杨', 7, 14535, 'tt0055928', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1747561073.jpg', 0.9, 5.6, 48, 33.9, 11.6, '0.338892,0.052707,-0.567716,0.329853,0.194961,0.060670,0.181927,0.104827,-0.356402,-0.285486,0.162945,0.545042,-0.285623,-0.090656,0.339125,0.138546,-0.557211,-1.001017,-0.317965,-0.177573,-0.438004,-0.640380,-0.003265,-0.002209,0.063401,-0.186594,0.465512,0.074350,-0.062105,0.351128,0.181415,0.699143,-0.406197,0.596968,-0.025802,-0.152885,0.411933,-0.594215,-0.515662,0.334047,0.137124,-0.250512,0.029318,0.266491,-0.124330,0.295949,0.745454,-0.543398,0.032990,-0.214524,0.266861,-0.438140,0.172606,0.193057,0.636595,0.129618,-0.519094,0.441509,-0.226313,-0.164640,0.296964,-0.336807,-0.797667,-0.164526,0.103247,0.131682,-0.542524,-0.094804,0.058071,0.396158,-0.237148,0.059011,0.186991,0.573558,0.403106,0.102167,0.310561,0.116601,-0.359573,-0.109096,0.493530,-0.158070,0.287416,-0.113972,0.293748,-0.289820,0.028647,-0.000898,-0.135335,-0.026536,0.476546,-0.137418,-0.079988,0.288475,-0.460645,-0.003215,-0.716890,-0.156038,0.056825,-0.319062,-0.403292,-0.886899,-0.240387,0.183759,-0.102809,0.177225,0.135293,-0.055850,0.382747,-0.770381,0.092123,0.682733,0.184241,-0.297158,0.467450,-0.154983,0.105970,-0.625859,-0.176651,0.013594,0.095213,0.293139,0.257176,0.148883,0.142081,-0.426416,-0.210002,-0.067725', '25723905', '1307442', '27126336', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293073', '变蝇人', '科幻', '年轻的科学家塞斯（杰夫•高布伦 Jeff Goldblum 饰）刚刚发明一台能传送物体的“电动传送机”，这台机器能将物体分解，传送完成后再自动合成还原。兴奋不已的塞斯决定亲自体验一下电动传送，于是，他进入了传送仓。不幸的是，一只苍蝇这时也飞进了传送仓，于是，在机器将分解 后的塞斯的分子再合成时，将苍蝇的分子也合成到了塞斯的体内。塞斯成了拥有一半苍蝇基因的蝇人。起初，塞斯的身体就像蜘蛛侠一样变得强壮和精力旺盛，他的女友维罗尼卡（吉娜•戴维斯 Geena Davis 饰）根本不相信男友的鬼话。但是，随着塞斯的身体迅速的渐渐老去，身体开始长毛，牙齿脱落，浑身冒浆，维罗尼卡渐渐接受了这个事实。她并没有遗弃男友，而是和他一起平静的接受了这个事实，即使他变得血肉模糊，她还是和他一起相拥而眠。©豆瓣', '杰夫·高布伦', '大卫·柯南伯格', 7.4, 38508, 'tt0091064', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2503648785.jpg', 0.9, 3.9, 35.5, 45.4, 14.2, '0.598307,0.264729,-0.554691,0.367643,-0.349449,-0.180857,0.828564,0.317245,-0.347120,0.216832,0.032528,0.855514,-0.378892,0.080803,0.027091,0.302968,-0.448124,-0.690115,-0.160652,-0.063338,-0.520724,-0.439109,-0.091902,-0.222542,0.126972,-0.488042,0.769993,-0.185816,0.168187,0.360448,-0.146487,0.134773,0.088728,0.408636,-0.062697,0.066936,-0.025762,-0.206933,0.240834,0.059638,-0.004212,0.026444,0.420471,0.105378,-0.081688,0.213267,0.513871,-0.391944,0.016829,-0.241913,0.159881,-0.020442,-0.155609,0.177583,-0.002809,0.154163,0.113759,-0.209231,-0.206532,0.279727,0.327690,0.205833,-0.592466,-0.059017,-0.271615,0.276000,-0.470623,0.076857,-0.227736,-0.041385,-0.101048,-0.486087,0.211403,0.243837,0.084947,0.412592,-0.410721,-0.132061,-0.577154,0.032962,0.387828,0.049066,-0.729830,0.419223,-0.220778,-0.504881,-0.248205,-0.030126,-0.093410,-0.270782,0.417934,0.494538,-0.409192,0.262007,-0.755842,-0.059881,-0.308425,-0.167567,-0.140941,-0.196875,-0.095623,-0.561468,-0.263482,-0.297780,-0.083662,0.028401,-0.175526,-0.291020,0.455841,-0.634901,0.205170,0.669338,0.276352,-0.125873,0.148530,-0.280024,0.035500,-0.141302,0.299397,0.185513,0.108704,0.631741,0.427516,0.778063,0.225524,-0.097039,-0.530376,0.786484', '1467779', '1307800', '3431336', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293077', '苏菲的抉择', '剧情', '一位来自美国南部的年轻作家斯汀戈（彼特·麦尼科 Peter MacNicol 饰）为求生计来到布鲁克林，认识了居住在楼上的苏菲（梅丽尔·斯特里普 Meryl Streep 饰）和内森（凯文·克莱恩 Kevin Kline 饰）。他们很热情的表达希望和这位年轻的作家交朋友 ，斯汀戈欣然接受他们的邀请。逐渐地交往之后，他们之间相互建立了亲密友好的感情。在这个过程中斯汀戈了解到，苏菲常因内森的猜疑和暴怒伤心哭泣，但她非常的爱内森，最让她担心是：内森没有她以后的生活将不可想象。苏菲是波兰人，二战后来到美国，在这里认识了内森并和他相依为命，战时苏菲曾被关进纳粹集中营，而她的父亲、丈夫、儿女全部在这场战争中罹难。对于自己的受难和亲人一个个的悲惨命运，和这场战争中人间地狱般的种族大灭绝，苏菲的精神和肉体该如何抉择……©豆瓣', '梅丽尔·斯特里普', '艾伦·J·帕库拉', 8.4, 20179, 'tt0084707', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1217019930.jpg', 0.3, 1.1, 14.5, 48, 36.1, '0.407695,-0.062396,-0.949683,0.638997,-0.079887,-0.364218,0.919905,-0.024940,-0.636561,-0.209216,0.031674,1.047009,-0.090231,0.275174,0.299810,-0.031805,-0.373492,-0.763793,-0.094666,-0.111098,-0.341706,-0.632792,-0.187142,-0.220434,-0.342556,-0.209798,0.489112,-0.100379,-0.165435,0.675783,0.256378,0.539453,-0.012893,0.508442,-0.023563,0.062607,0.210206,0.079217,-0.516796,-0.002440,-0.001653,0.173698,-0.218974,0.398513,0.081850,0.343694,0.386315,-0.285210,0.069788,-0.030078,0.142291,-0.333390,0.082262,0.404832,0.272642,-0.285941,0.242012,0.177401,-0.198829,-0.102474,-0.122864,-0.103154,-0.815839,0.051734,0.030704,0.323155,-0.626665,0.434540,-0.161074,-0.157897,0.104541,-0.188831,0.134068,0.658917,0.272338,0.397838,-0.132062,-0.083741,-0.313772,0.023152,0.858687,0.073621,-0.417775,0.360339,-0.422558,-0.377703,-0.209928,-0.201211,-0.851828,-0.119507,0.280499,0.007106,-0.234748,0.643015,-0.612761,-0.073110,-0.268502,-0.132370,0.128926,-0.353538,-0.019487,-0.688831,-0.443372,-0.926457,-0.396925,-0.144864,-0.016337,-0.356450,0.863338,-0.980787,0.065159,0.444599,0.480879,-0.382873,0.560691,0.470458,0.196378,-0.199325,-0.053628,0.605823,0.065984,0.003742,0.051725,0.220165,0.160181,0.103611,-0.421245,0.566752', '24325798', '1292720', '1299556', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293088', '小鬼当家', '喜剧', '一年一度的圣诞节又到了。全家忙着外出欢度圣诞假期，不料忙中出错，将家里最小的成员——8岁的凯文（麦考利•卡尔金 Macaulay Culkin　饰）留在了家里。爸爸妈妈急坏了，可此时他们已经身在外地，一时亦无可奈何。倒是凯文乐坏了，难得一个人在家，凯文将家里布置成了“游乐场”。两个刚出狱的窃贼将目光瞄向了凯文家。当他们鬼鬼祟祟的踏入凯文家时，凯文凭借自己的醒目和家里的“游乐场机关”，和两个笨贼玩起了“游戏”，笑料百出。凯文最后能否这场“游戏”的胜利？©豆瓣', '麦考利·卡尔金', '克里斯·哥伦布', 8.4, 361299, 'tt0099785', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1529668801.jpg', 0.1, 0.6, 14.6, 51, 33.7, '0.388931,0.061211,-0.648171,0.111135,-0.171813,-0.565338,0.482543,0.277023,-0.383722,-0.144780,0.118618,0.700928,-0.290126,0.614653,0.374303,0.036657,-0.505033,-0.628631,-0.094158,-0.268559,-0.227191,-0.321487,-0.136205,0.070287,0.026665,0.129664,-0.044689,-0.137806,0.231551,0.546536,0.398341,0.030675,-0.073889,0.352348,-0.151984,0.228413,0.378336,-0.240418,0.011158,0.245958,-0.038364,-0.136936,-0.443197,0.213838,0.457235,0.262778,0.876711,0.023801,-0.170279,-0.054152,0.312452,-0.241228,-0.306684,0.039178,0.287891,-0.138480,0.230723,0.005078,-0.062536,0.127387,0.217050,-0.191415,-0.610736,0.451931,-0.018376,-0.198297,-0.503391,0.449642,0.025505,-0.069791,-0.075814,-0.408514,0.339037,0.514337,-0.025548,0.346941,-0.141494,0.098850,-0.598468,0.336751,0.406740,-0.184740,-0.053668,0.202627,0.108761,-0.023908,0.169258,-0.222690,-0.566290,0.045391,0.557398,0.099930,-0.225872,0.090569,-0.721604,0.166516,-0.236775,-0.361989,0.012783,-0.478207,-0.252321,-0.664935,0.097139,-0.213673,-0.623254,0.136634,0.045403,0.168094,0.609418,-0.629232,0.108860,0.475816,0.160672,-0.118241,0.810988,0.000781,0.379043,-0.113258,0.066250,-0.469297,0.098988,0.530546,0.429205,0.559843,-0.194092,-0.271128,-0.718281,0.388264', '1309194', '3155839', '3055049', '5960606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293090', '赌王之王', '剧情', '迈克（马特•达蒙 Matt Damon 饰）是一个法律系二年级的学生，但他却因为一次跟赌场老板泰迪（约翰•马尔科维奇 John Malkovich 饰）的赌博输掉了所有的积蓄。在朋友克尼什（约翰•特托罗 John Turturro 饰）劝慰下，迈克立下誓言，从此不碰赌博。不过，他还是在教授的牌局上露了一手，技惊四座。在接老朋友虫子（爱德华•诺顿 Edward Norton 饰）出狱的时候，迈克违背了自己的誓言，重出江湖。为了帮助虫子，他甚至延误了模拟法庭的实习。此后，女友乔发现了迈克涉赌的证据，与他分手，这令他非常沮丧。迈克在虫子的怂恿下，接连参与赌局。事后，却发现自己被虫子摆了一道，欠下了巨款。他找到虫子，后者在被逼之下吐露了实情：原来虫子被凶悍的债主逼得走投无路。为了友情，他接受了债主苛刻的条件，但是却陷入了更加艰难的困境……©豆瓣', '马特·达蒙', '约翰·达尔', 7.4, 28495, 'tt0128442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p769894916.jpg', 0.4, 2.7, 36.2, 45.7, 15.1, '0.206893,-0.002435,-0.471017,0.397879,-0.237049,-0.311434,0.686698,0.165551,-0.360288,0.111164,0.412464,0.665084,-0.351082,0.100597,0.107800,-0.116785,-0.125806,-0.579539,0.290643,-0.018396,-0.085690,-0.462570,-0.022479,-0.299641,-0.212230,-0.186663,0.485164,0.110118,-0.108406,0.227857,0.191887,0.225966,0.312227,0.460987,0.072981,0.145757,0.254275,-0.047320,0.018084,0.073232,0.195609,-0.450393,-0.081167,0.366767,0.088275,0.577800,0.379687,-0.275177,-0.116351,0.016024,0.235502,-0.454921,-0.070034,0.233485,0.250173,-0.183470,0.101392,0.220965,-0.160911,-0.070995,0.228105,0.013324,-0.606312,-0.139707,-0.101470,0.061242,-0.793891,0.617050,-0.348636,0.352875,-0.212059,-0.194814,-0.056002,0.131005,0.226015,0.074296,-0.044500,-0.071299,-0.590118,0.193460,0.474215,-0.133405,-0.099124,0.232664,-0.429087,-0.454467,-0.017764,-0.157904,-0.373833,0.055684,0.640457,-0.104452,-0.293456,0.069607,-0.591273,-0.334752,-0.325858,-0.010983,-0.294319,-0.548101,-0.256193,-0.286460,-0.192542,-0.103688,-0.304274,0.002158,-0.004751,-0.211024,0.289793,-0.655063,0.032927,0.597624,0.277621,-0.238979,0.603259,0.174673,-0.045399,-0.169847,-0.046072,0.100795,0.237526,0.409551,0.679622,0.289369,0.265150,-0.230858,-0.122647,0.484976', '1306801', '1309069', '1292584', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293092', '沙丘', '动作', '故事发生在遥远的未来时代，沙丹四世（何塞·费勒 José Ferrer 饰）是宇宙之王，他靠着自己的强权和武力控制着整个帝国。尽管手握大权，但沙丹四世还是没有安全感，他认为自己的表弟亚崔迪公爵（尤尔根·普洛斯诺 Jürgen Prochnow 饰）企图谋权篡位，因此将他发配到了遥远的凯勒丹行星上。沙丹四世对于亚崔迪公爵的迫害并没有停止，最后，公爵战败自杀，留下妻子和儿子保罗（凯尔·麦克拉克伦 Kyle MacLachlan 饰）流离失所，两人逃到了广袤的沙漠之中，向当地的土著求助。土著们将保罗当做了他们的救世主顶礼膜拜，保罗最终成为了土著领袖，并和名为佳妮（肖恩·杨 Sean Young 饰）的当地女子结为夫妻，然而，复仇的火焰从未在他的心中熄灭过。©豆瓣', '肖恩·杨', '大卫·林奇', 6, 6838, 'tt0087182', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1430340819.jpg', 5.8, 22.8, 45.9, 18.2, 7.3, '0.250345,0.417096,-0.877613,0.821262,0.138620,-0.069507,0.778197,0.078028,-0.392351,-0.331473,-0.025076,0.756365,0.017636,0.166983,0.357810,0.164821,-0.350928,-0.786922,-0.091123,0.012383,-0.265364,-0.715764,-0.339459,-0.307112,-0.486183,-0.417825,0.709548,0.056896,-0.133669,0.084619,0.277531,0.475413,0.182816,0.560963,-0.138917,0.216110,0.232197,-0.171250,-0.429851,0.189715,0.044234,-0.212884,-0.134958,0.571952,0.099547,0.399738,0.360952,-0.920608,0.345162,-0.157735,0.082125,-0.406389,0.037978,0.087875,0.273037,-0.340154,-0.072881,0.285784,0.229841,-0.283386,0.234301,0.021971,-0.669082,-0.060918,0.074989,0.132379,-0.608887,0.510448,-0.156958,0.177340,-0.058701,-0.230713,0.458522,0.285652,0.026867,0.319528,-0.178510,0.003171,-0.586112,0.045393,0.774256,0.216444,-0.445028,-0.172090,-0.597236,-0.572424,-0.237874,-0.367288,-0.592370,-0.302054,0.450074,0.021705,0.197211,0.681899,-0.470643,-0.299860,-0.427290,-0.229749,0.314791,-0.349939,0.156211,-0.150431,-0.035800,-0.459343,-0.308821,0.054011,-0.011316,-0.352233,0.484067,-0.625350,0.281236,0.529509,0.504030,-0.281569,0.733112,-0.072179,0.175164,-0.242001,-0.266398,0.563652,0.224576,0.124805,0.366729,-0.007269,0.084706,-0.060085,-0.071896,0.594347', '1307311', '1309115', '6511042', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293098', '小倩', '喜剧', '故事出自连拍三集的《倩女幽魂》，徐克二维人物动作结合三维背景电脑处理，成为卡通漫画版。电影制作历时四年，糅合了日本动画和中国传统中国板画风格。宁采臣（林海峰 配音）在鬼城郭北县遇上了一个令他一见钟情的女鬼小倩（袁咏仪 配音），可惜小倩只想吸取宁的阳气给姥姥（陈慧琳 配音），却意外地救了宁一命。这时道士燕赤霞（黄沾 配音）来到，鬼怪们逃命，宁舍命救了小倩。为免小倩为难，自愿与小倩去见姥姥。当姥姥要吸宁的阳气时，小倩改变了初衷，救了宁。宁与小倩海誓山盟，愿来世再续缘。当他们投胎时，遇到了来报复的黑山老妖，后来被跟来的燕杀死。但是以扫除一切妖魔鬼怪为目标捉鬼大师白云（黄敏民 配音）和十方（葛民辉 配音）却要消灭所有投胎的妖怪，燕不得不与他们斗法，最后两败俱伤。经历了种种磨练，宁终于得以与小倩重逢，再也不分离……©豆瓣', '林海峰', '陈伟文', 8.3, 21339, 'tt0125037', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2354806655.jpg', 0.4, 1.7, 16.9, 43.9, 37.1, '-0.005318,-0.135249,-0.217502,0.333416,0.094177,-0.510038,0.306589,-0.096737,-0.171350,-0.473143,-0.392618,0.678444,-0.350669,-0.000243,-0.050182,-0.299788,-0.002277,-0.659880,-0.062348,0.044337,-0.201721,-0.102769,0.020000,-0.183359,-0.060268,0.143346,0.623567,0.076340,-0.443949,0.337371,0.390745,0.009294,-0.448706,0.105350,-0.230229,0.288940,-0.393634,0.007137,-0.300851,0.129706,0.085049,-0.298290,-0.037890,0.122188,-0.123356,0.266006,0.645432,-0.179880,-0.164474,-0.019704,0.202623,-0.331288,0.044562,-0.009953,-0.091647,-0.142486,0.284909,0.200585,0.036087,-0.130928,-0.105036,-0.211846,-0.667759,0.227901,0.222198,-0.005074,-0.423769,0.113596,0.104710,0.328353,-0.108513,-0.069129,0.288587,0.387660,0.430143,0.313234,-0.108934,-0.106693,-0.318262,0.402461,0.727409,-0.052659,0.109959,0.654746,0.189753,-0.243039,-0.157238,-0.184597,-0.184452,0.335403,0.143896,0.019847,-0.162854,0.061691,-0.707875,-0.453053,-0.162576,0.414859,-0.064809,-0.118615,0.061309,-0.582326,-0.214486,-0.233146,-0.211061,-0.079191,-0.018202,-0.278993,0.716855,-0.734911,0.009272,0.218554,0.276650,-0.650696,0.652738,0.065161,-0.036115,-0.184511,0.398352,0.080619,0.044299,0.372691,0.393467,0.068586,0.032649,-0.041932,-0.498873,0.094174', '4301278', '3811356', '25880986', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293105', '蚀', '剧情', '天空微白，已是黎明时分。可对于里卡多（弗朗西斯科·拉瓦尔 Francisco Rabal饰）来说，这却是痛苦而残酷的一夜。无论里卡多怎样苦苦哀求维多利亚（莫尼卡·维蒂 Monica Vitti饰）回心转意，她已然心意已决，执意离去。维多利亚来到罗马证券交易所找她的母亲，远远地就看见母亲与经纪人皮耶罗（阿兰·德龙 Alain Delon饰）兴奋地聊着股票。皮耶罗年轻潇洒，风度翩翩，很会讨女人欢心，而这对维多利亚来说毫无兴趣。但一种莫名的强大吸引力在两人之间慢慢滋生，然而两人谁也未曾踏出第一步。当她再次来到交易所时，却遇到股票狂跌，维多利亚的母亲也亏了很多钱。不安的维多利亚，觉得皮耶罗可以成为自己可靠的保护人。然而当两人终于在一起时，隐藏在他们背后的复杂关系又使他们彼此疏远。由意大利现代主义电影导演米开朗基罗·安东尼奥尼执导的《蚀》，与《夜》、《奇遇》共同构筑了安东尼奥尼的《现代爱情三部曲》。安东尼奥尼的作品一直关注着人类精神状态的病态与疏离，本片的背后依旧是他所要传达出的人文道德危机和精神的空虚。本片荣获1962年第15届戛纳电影节评审团特别奖，入围1962年第15届戛纳电影节金棕榈奖。', '阿兰·德龙', '米开朗基罗·安东尼奥尼', 8.4, 18026, 'tt0056736', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1926937856.jpg', 0.4, 1.6, 14, 45.3, 38.7, '0.059380,0.073493,-0.934774,0.629403,0.344224,-0.452648,0.689174,0.188617,-0.462993,-0.228615,0.146443,0.743873,-0.155535,0.238632,0.392045,-0.003330,-0.337982,-0.563384,-0.068199,-0.160124,-0.004132,-0.416769,-0.352046,-0.124477,-0.252194,-0.244137,0.602707,0.210039,-0.090619,0.545783,0.565318,0.236037,0.020077,0.499330,-0.066961,-0.104819,0.245405,0.121254,-0.528657,0.174791,0.230690,-0.078740,-0.527018,0.125362,-0.019090,0.265549,0.354665,-0.229863,-0.135390,0.107052,0.433320,-0.144100,0.062437,0.059606,0.046470,0.004789,0.100006,0.125010,-0.144770,0.136305,-0.164201,-0.153515,-0.630563,0.220858,-0.057537,0.177632,-0.416535,0.376448,-0.094064,0.115612,0.015470,-0.225833,0.123117,0.179127,0.231633,0.288545,-0.124442,0.074904,-0.379418,-0.218027,0.526419,0.159661,-0.495454,0.368171,-0.308486,-0.357721,-0.142581,-0.182779,-0.425037,0.053813,0.212382,0.239836,0.119492,0.371052,-0.581438,0.051183,-0.073488,-0.030156,-0.069972,-0.408036,0.196982,-0.558376,-0.269738,-0.448950,-0.293103,0.024054,0.069854,-0.209495,0.664873,-0.481575,0.361240,0.439073,0.408144,-0.351493,0.649123,-0.034609,-0.023328,-0.317737,-0.363464,0.554582,-0.268101,-0.065595,0.047426,0.338532,0.081691,-0.006979,-0.204555,0.496709', '34461680', '30162520', '3606973', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293107', '野良犬', '剧情', '炎热夏天，身心疲惫的青年刑警村上（三船敏郎 饰）结束了射击练习后，登上拥挤难闻的公车回家，途中突然发现配枪被人盗走。他奋力追赶，却最终跟丢了目标。村上垂头丧气找到佐藤课长（志村乔 饰），请求解除他的职务，善良的课长则指点他拜托扒手课的资深刑警市川（河村黎吉 饰）寻求帮助。经市川提醒，村上想起公车上身边站着的一个女人，正是女惯犯阿银（岸辉子 饰）。耐不住村上的死缠烂打，阿银透露了手枪贩子的信息。在此之后，村上深入这座城市最黑暗的角落，寻找关于手枪的蛛丝马迹。与此同时，有人用他的手枪犯案，形势日渐紧迫。二战后日本都市的芸芸众生相，通过村上野狗一般锐利的双目交替呈现……©豆瓣', '三船敏郎', '黑泽明', 8.4, 13883, 'tt0041699', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2205344466.jpg', 0.3, 0.8, 12.6, 52.9, 33.4, '0.179122,-0.143954,-0.404880,0.258065,-0.166557,-0.149381,0.511431,0.085864,-0.277842,-0.319124,0.330106,0.314321,0.008265,0.358097,0.206121,-0.026200,-0.402438,-0.573683,-0.021201,0.070401,-0.253146,-0.248075,-0.133727,-0.194937,-0.130722,-0.139421,0.563248,0.230131,-0.302103,0.470741,0.173203,0.344770,-0.077553,0.306950,-0.045374,-0.195082,0.114600,-0.210728,0.130252,0.121828,-0.251790,-0.452824,-0.111703,0.053576,0.152274,0.556681,0.666576,0.098705,-0.174448,-0.155447,0.243515,-0.040146,-0.032651,0.087177,0.455895,0.164496,-0.030192,-0.099616,-0.154978,-0.201831,-0.074378,0.080252,-0.240419,0.105630,0.019141,0.142063,-0.405878,0.077269,-0.070457,-0.092461,0.393156,-0.329712,0.236489,0.050157,0.249960,-0.056415,-0.127637,0.102739,-0.086396,0.127775,0.055692,-0.316939,-0.124517,0.029467,-0.093850,-0.442309,0.079983,0.017708,-0.103254,-0.322527,0.373978,0.019064,-0.248260,-0.070331,-0.387028,0.081664,0.074978,-0.090889,0.019537,-0.119494,-0.307323,-0.728503,0.128270,-0.295042,-0.201606,0.368351,-0.008385,0.030346,0.613346,-0.359769,0.099629,0.646620,0.095868,-0.153154,0.437286,-0.162641,-0.121414,-0.334647,0.010627,0.278976,0.373088,0.616931,0.155112,0.234406,-0.464207,-0.070911,-0.389151,0.198107', '20274039', '5403927', '6984051', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293118', '龙争虎斗', '动作', '少林叛徒韩先生（石坚 饰）背叛少林后，斥资买下一座小岛将其改造成私人王国，韩先生及一干手下在岛上制贩毒品，强迫女性卖淫，警方欲将其绳之以法却苦无证据。少林高徒李（李小龙 饰）的功夫已经超越有形境界，他受师傅与政府请托，准备参加三年一度由韩先生主办的比武大会。比武大会期间，是登陆孤岛搜集证据的唯一机会。同时韩先生的私人保镖熬加达曾经杀害了李的姐姐，是李恨之入骨的仇人。比武大会的邀请发出，世界各地选手纷纷聚集，有债务缠身的鲁柏、勇于对抗不公的威廉士等人与李一同登岛决一雌雄。李找到了政府在岛上安插的情报员美玲，在后者的帮助下，李与各路选手以及韩先生展开了一场龙争虎斗。©豆瓣', '李小龙', '罗伯特·高洛斯', 8.3, 26945, 'tt0070034', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p581902469.jpg', 0.4, 1.4, 15.8, 46.4, 36, '-0.236967,0.100380,-0.605025,0.688170,-0.105334,-0.075619,0.208297,-0.040528,-0.447300,-0.181063,0.255815,0.454015,-0.057974,0.220738,0.342024,-0.455884,-0.012513,-0.778862,-0.295455,-0.295908,-0.356654,-0.460226,-0.190965,-0.280465,-0.274838,-0.203481,0.493036,0.122976,-0.522039,0.262190,0.380180,0.136997,-0.076264,0.304733,-0.122102,-0.184900,0.262908,0.142704,-0.588208,0.145561,-0.183995,-0.373897,-0.072149,-0.103280,0.209954,0.396991,0.541687,-0.151834,0.051668,-0.432522,0.029859,-0.264152,0.143266,0.013532,0.591112,0.086309,0.077813,0.316727,-0.253065,-0.368343,0.122258,-0.219877,-0.497279,-0.111099,0.492268,-0.106290,-0.404688,0.242573,-0.361207,0.151091,-0.283887,-0.192762,0.182345,0.588401,0.139034,-0.007901,0.349531,-0.110171,-0.408079,0.512798,0.911314,0.007629,0.090475,-0.509255,0.144813,-0.596913,0.158318,-0.385387,-0.044913,0.050809,0.394358,-0.430655,0.261782,0.183932,-0.420693,-0.363758,-0.133706,-0.221562,0.207410,-0.164753,0.342231,-0.994782,-0.001674,0.044995,0.092529,0.024034,0.332116,-0.234681,0.705271,-0.752458,0.284784,0.157116,0.328751,-0.533216,0.709433,-0.139343,0.265580,-0.211374,-0.223750,-0.146008,0.300689,0.499733,0.237857,0.261139,0.116756,-0.222920,-0.182259,-0.015395', '24751811', '1307762', '25723905', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293120', '小美人鱼', '爱情', '爱丽儿是海中一条自由自在的小美人鱼，她向往自由，海底的世界似乎她看得有点厌了。这天，她突发奇想，想冲出海底，看看陆上精彩的世界。于是，她就真的冲破了美人鱼的限制，浮上了海面。当她看到了英俊的王子时，她彻底被征服了。为了能和王子相爱，小美人鱼爱丽儿决定以自己美丽的歌声为代价，换取一双平常人类女子的腿。在好朋友的支持和鼓励下，爱丽儿不顾一切向着自己的梦想出发！©豆瓣', '勒内·奥贝尔若努瓦', '罗恩·克莱蒙兹', 8.4, 90240, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p827079407.jpg', 0.2, 0.7, 14, 47.4, 37.7, '0.073153,0.339354,-0.652529,0.835409,-0.336313,-0.224074,0.738504,-0.073250,-0.157129,0.527820,0.221634,0.871683,-0.049832,0.364255,0.232548,0.369356,-0.394120,-0.684192,-0.159642,-0.242981,-0.339697,-0.276964,-0.576867,-0.189288,-0.028874,-0.553693,0.674692,0.185696,0.094716,0.300147,0.179501,-0.429508,0.171201,0.555536,-0.472287,-0.144585,-0.333912,0.162080,-0.124266,0.237727,0.068329,-0.040645,-0.171537,0.305420,-0.287616,0.156078,0.793502,-0.635030,-0.016074,-0.306899,0.208911,-0.362117,0.285813,0.170278,-0.065315,-0.110733,0.173385,-0.207224,-0.256777,-0.306504,0.260812,-0.175009,-0.635203,0.052709,-0.054865,0.062520,-0.471497,0.269683,0.029277,-0.171448,0.547688,-0.353299,-0.033166,0.157847,0.405810,0.510394,-0.268049,0.204637,-0.357333,0.403960,0.870876,0.205694,-0.292051,0.465718,-0.396646,-0.362893,-0.024274,-0.206749,-0.229823,-0.244348,0.723040,0.021857,-0.476653,0.309232,-0.694575,0.112749,-0.271202,-0.317177,-0.299991,-0.726777,-0.295545,0.036615,-0.068696,-0.315200,0.286710,0.195450,0.186209,-0.424950,0.956611,-0.926102,0.040472,0.710197,0.671875,-0.532751,1.031389,-0.007907,-0.217966,-0.121775,0.070381,0.260702,-0.330435,0.478863,0.194045,0.508638,-0.104422,0.199548,-0.781699,0.876879', '3055049', '24733428', '1292001', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293124', '惊情四百年', '爱情', '这是一部阴森诡异的吸血鬼传说,同时也是一个凄美感伤的爱情故事。 公元1462年，土耳其人入侵君士坦丁堡，并威胁到整个基督教。罗马尼亚大将军德古拉伯爵(加里•奥德曼 饰)临危受命征讨，不料就在他获胜之时，城内谣言四起， 盛传他已战死沙场。他的妻子伊丽莎白（薇诺娜•赖德 饰）因悲痛欲绝而投河自杀，班师回朝的德古拉看到的只是妻子的尸体。由此他迁怒于上帝，从而化身投入邪恶势力，以吸食鲜血延续生命，成了一个不死的吸血僵尸。 四百年后，故事辗转到了1897年的伦敦，年轻律师强•纳生（基努•里维斯 饰）受命到罗马尼亚特兰斯瓦尼亚属地的德古拉家族城堡去办理这位贵族后裔在伦敦的地产手续。为此，他将与未婚妻——美丽的美娜（薇诺娜•赖德 饰）分离。德古拉城堡的主人公正是已化为吸血鬼的德古拉伯爵，他发现美娜与伊丽莎白惊人相象，认为美娜就是莉莎的转世再生。他决定找到美娜，找回那一份遗失了四百年的真爱。他将约拿囚禁在城堡之中，带上成箱子的故乡泥土：这是他力量的源泉，乘船一路呼风唤雨来到伦敦。他的到来复苏了伦敦的黑暗力量。伦敦处于一种神秘的恐怖之中。而美娜却总在冥冥之中听到一种心灵的神秘的召唤，在恐惧中又带有一种强烈的向往······', '加里·奥德曼', '弗朗西斯·福特·科波拉', 7.7, 152899, 'tt0103874', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1541485065.jpg', 0.6, 3.3, 27.5, 45.6, 23, '0.054150,0.291331,-0.725730,0.542022,-0.047604,-0.248181,0.973177,0.034081,-0.351597,-0.316413,0.261950,0.896325,-0.173694,0.257286,0.406026,0.303205,-0.162630,-0.481227,-0.039065,-0.188397,-0.195528,-0.281738,-0.428065,-0.272243,0.036672,-0.615444,0.665117,0.283808,-0.156869,0.340839,0.088680,0.661182,-0.244086,0.385393,-0.212432,0.027009,-0.068942,-0.075600,-0.243983,0.152937,0.102907,-0.117259,-0.101337,0.209914,-0.256535,0.296016,0.544299,-0.377530,0.155079,-0.104294,0.509414,-0.262472,-0.075724,0.130762,0.208024,-0.083180,-0.054831,0.245297,-0.137567,-0.214665,0.016331,-0.080200,-0.813362,-0.104180,-0.026864,0.267166,-0.320820,0.488144,-0.040251,-0.082087,0.165932,-0.298191,0.178878,0.252607,-0.070194,0.545244,-0.148143,-0.007845,-0.582041,0.079927,0.552395,-0.264524,-0.488186,0.183693,-0.136711,-0.488871,0.022962,-0.173624,-0.456060,-0.151382,0.305422,0.135437,0.142604,0.507669,-0.862080,-0.333492,-0.576631,-0.038910,0.087388,-0.144632,-0.200440,-0.347427,-0.373488,-0.163585,-0.057975,0.165871,0.314659,-0.108529,0.482024,-0.627641,0.331098,0.664914,0.329029,-0.265853,0.419903,-0.163244,0.006567,-0.101760,-0.158545,0.742620,0.256698,0.254780,0.198949,0.193799,0.024502,0.038854,-0.492926,0.633038', '25828589', '1307311', '3005387', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293131', '天地大冲撞', '科幻', '“毕德曼慧星”正朝着地球飞奔而来，给人类致命一击。当局紧急行动，研究出一个最佳方案——由宇航员坦纳（罗伯特·杜瓦尔 Robert Duvall饰）驾驶“弥赛号”飞船飞往慧星，把预先准备好的核弹放置到慧星上面引爆，以令它化成碎片或是改变轨道。坦纳英勇地完成了任务，却发现并没有取得预期效果。慧星碎成了一大一小两部分，向地球步步逼近。当局迅速采取最后的行动，用“诺亚方舟”计划保住包括人类在内的一些地球物种。这是一个秘密的地下庇护所，只有少数的人可以在这里避开大劫难，等灾难散尽后方重建世界。较小的那部分慧星已经撞向地球，引发山崩地裂，一片世界末日的景象。而跟随其后的大慧星给地球带来的毁灭程度，将远远超乎人们想象，力挽狂澜的人类进入了倒数时刻。©豆瓣', '伊利亚·伍德', '米密·莱德', 7.2, 41410, 'tt0120647', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2172256449.jpg', 0.5, 3.9, 42.6, 40.9, 12.1, '-0.014952,0.346684,-0.714847,0.494778,-0.053232,0.110256,0.625211,0.033492,-0.004449,0.031935,0.273826,0.634613,-0.304157,-0.471993,0.230484,-0.150826,-0.245521,-0.464812,-0.168657,-0.294865,-0.661062,-0.393496,-0.494431,-0.133025,-0.089534,-0.405913,0.769689,0.230879,-0.214708,0.235062,-0.167602,0.257795,-0.138741,0.371873,-0.213866,0.018865,-0.354920,-0.189617,-0.516599,0.541887,-0.219681,-0.037110,0.140633,0.206499,-0.305724,0.181303,0.840462,-0.494090,-0.124413,-0.518636,0.250204,-0.450618,-0.031066,0.024216,0.381769,0.083243,-0.314240,-0.108063,-0.037475,0.289233,0.368940,-0.104193,-0.679501,-0.190982,-0.044072,0.095203,-0.342307,0.176525,-0.116480,0.087844,-0.009759,-0.373331,0.259355,0.432884,0.331515,0.351135,-0.433039,0.161516,-0.566436,-0.205371,0.378049,-0.061172,-0.557474,0.332458,-0.108091,-0.224414,-0.274987,-0.201311,0.163104,-0.115635,0.407895,0.324440,-0.088617,0.340728,-0.619310,0.122980,-0.383277,-0.652187,-0.089843,-0.387822,-0.222514,-0.806622,0.188711,0.063566,-0.094906,0.243366,0.066082,-0.060507,0.899977,-0.187337,0.107137,0.487351,0.443735,-0.157723,0.416130,-0.256178,0.138663,-0.222016,0.286728,0.027624,0.158673,0.651373,-0.140605,0.245508,-0.086596,-0.198538,-0.490571,0.359207', '3318306', '2977870', '4181031', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293133', '惊声尖叫3', '惊悚', '经历了常人难以想象的痛苦与折磨，威兹堡温莎大学杀人案的幸存者悉妮·普利斯科特（内维·坎贝尔 Neve Campbell 饰），如今隐居在山中，通过电话对有着生活危机的女性们进行心理辅导。与此同时，她的事迹被改编成系列恐怖电影“血腥刺杀”（Stab），第3部《Stab》的主角卡顿却被当街杀害。这一事件让悉妮、戴维（David Arquette 饰）以及盖尔（Courteney Cox 饰）重新聚首。而鬼脸杀手更是阴魂不散，在好莱坞引发了新一轮的血腥屠杀……本片系“惊声尖叫”系列第3部，荣获2000年青年选择奖最具化学作用的组合奖（Courteney Cox & David Arquette）、2001年大热门娱乐奖最佳男主角（David Arquette）和最佳女主角奖（Neve Campbell）。©豆瓣', '内芙·坎贝尔', '韦斯·克雷文', 6.3, 17274, 'tt0134084', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2178430161.jpg', 2.2, 13.6, 57.9, 19.5, 6.8, '-0.099026,-0.234964,-0.519914,0.516984,0.433712,-0.025198,0.549661,-0.076637,-0.466529,-0.214927,0.164181,0.793390,-0.543416,-0.023362,0.412775,-0.338742,-0.087154,-0.727685,-0.292545,-0.117388,-0.078195,-0.093988,-0.377838,-0.017114,0.039208,-0.632063,0.535598,-0.127229,-0.411771,0.472511,0.843928,0.627417,-0.240390,0.143801,0.126154,0.050139,0.462590,-0.051426,-0.442669,0.267170,-0.216082,-0.470344,-0.157479,-0.061965,-0.099794,0.101500,0.851186,-0.336575,-0.047591,-0.300362,0.629244,-0.374175,-0.494608,-0.029963,0.508839,0.041047,0.171108,0.306192,0.061965,0.140360,0.165014,-0.264776,-0.881587,0.039490,0.337544,0.074647,-0.448902,0.258773,-0.081269,0.202920,0.157081,0.185485,-0.032798,0.174338,0.598591,0.320729,0.116464,0.042282,-0.096516,0.582514,0.539528,0.055793,-0.396108,0.187472,-0.212185,-0.588216,-0.127325,-0.622614,-0.361925,0.229747,0.416240,-0.033388,0.039277,0.531081,-0.663749,-0.096707,-0.206037,-0.417198,0.044156,-0.135810,-0.339408,-1.106015,-0.265282,-0.074641,-0.113936,-0.001353,0.105779,-0.430440,0.615568,-0.586236,0.252722,0.396663,-0.062999,-0.473428,0.350483,0.156263,0.209333,-0.014351,-0.238896,0.188055,-0.071065,0.232269,-0.033162,0.270504,-0.313050,-0.355453,-0.371204,0.282491', '3318306', '24751811', '25723905', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293135', '101真狗', '喜剧', '一天，罗杰（杰夫•丹尼尔斯 Jeff Daniels 饰）和安妮（朱莉•理查德森 Joely Richardson 饰）塔所养的斑点狗在和主人散步时一见钟情，罗杰和安妮塔也因此走到了一起。不久，两只斑点狗就生了一窝小狗。一家人生活得十分开心。这时，安妮塔的变态老板想用斑点狗皮做一件皮衣，在遭到了罗杰和安妮塔的拒绝后，她派人掳走了这窝小狗。罗杰夫妇一早醒来发现小狗不见了，急切里四出寻找，然而音讯全无。两人的爱犬这时按捺不住，在动物朋友们的帮助下，独自前往了虎穴……©豆瓣', '格伦·克洛斯', '斯蒂芬·赫瑞克', 7.4, 90805, 'tt0115433', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1686474657.jpg', 0.3, 2.7, 37.8, 44.3, 14.9, '0.531812,-0.249320,-0.743993,0.126325,-0.096591,-0.267178,0.727695,0.297373,-0.561658,-0.095233,0.034521,0.841736,-0.475802,0.435757,0.177430,0.061437,-0.560781,-0.494532,0.140675,-0.118027,-0.157557,-0.188885,0.026305,-0.316370,0.067248,-0.238161,0.180569,-0.197401,0.413812,0.880025,0.272146,0.206410,-0.137867,0.429825,-0.084021,0.343434,0.304472,0.072858,0.140527,0.483777,0.159732,0.200197,-0.090249,-0.019759,0.101629,0.174724,0.509726,-0.588776,-0.204908,-0.128724,-0.016645,-0.267986,0.090994,0.328748,0.426384,-0.221203,0.330060,-0.094628,-0.200591,0.067309,0.231336,0.033249,-0.214624,0.166374,-0.204570,0.154442,-0.832373,0.375328,-0.085018,0.113788,0.296822,-0.683791,0.311700,0.571020,-0.124558,0.319824,0.165353,0.229389,-0.729700,-0.048594,0.613378,-0.064671,0.194950,0.322873,0.179142,-0.232305,0.226071,0.108603,-0.365809,-0.180184,0.528781,0.127686,-0.451615,-0.145963,-0.705247,-0.046024,-0.204590,-0.081522,-0.175111,-0.378351,-0.332653,-0.395350,0.005197,-0.461656,-0.204337,0.171794,-0.156583,-0.123378,0.377705,-0.872112,0.367487,0.178419,0.210421,-0.223332,0.731188,-0.453745,0.138211,-0.104479,0.264528,-0.011226,0.159099,0.198505,0.734989,0.454771,0.004647,-0.107735,-0.609145,0.196059', '1296538', '1302384', '1926007', '1291574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293142', '新上海滩', '动作', '年轻军官许文强（张国荣）逃往路上被日本特务伏击堕海，漂浮到外滩岸上时身体不支晕倒，丁力（刘德华）路过欲将其救却遭其下意识的武力，两人一番打斗后结为好友。丁力偶然救下上海大亨冯敬尧（吴兴国）的千金冯程程（宁静）后，许下心愿要娶其为妻，但襄王有梦神女却心另有所属，冯程程只把他当好朋友，爱的恰是某次旅途中在火车上结识的他的好兄弟许文强，而许文强也因她的勇敢善良机智对她产生了好感。许文强再次遇上冯程程时，激情没能控制，与丁力的交情画上句号。而当许文强与冯程程谈婚论嫁时，许文强意外发现冯敬尧正是追杀他和同僚的幕后黑手，他的身份也被对方认出，火药味顿时弥漫房间。©豆瓣', '张国荣', '潘文杰', 7.7, 52367, 'tt0117619', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167125527.jpg', 0.4, 2.9, 30.1, 45.3, 21.3, '0.286048,0.091937,-0.752377,0.429860,-0.079004,-0.430531,0.763172,0.128043,-0.533279,-0.180188,0.143345,0.798932,-0.254374,0.405914,0.219101,-0.023207,-0.153389,-0.786119,-0.139879,0.110919,-0.151395,-0.337047,-0.110614,-0.196779,-0.255736,-0.042364,0.406740,0.217084,-0.214851,0.541912,0.327576,0.214652,-0.185459,0.759454,-0.259297,0.322767,0.017145,0.088317,-0.301485,0.110465,0.044438,-0.472229,-0.123404,0.117507,-0.193703,0.480774,0.636508,0.020080,-0.130245,-0.269187,0.236194,-0.207895,0.263647,0.138369,0.233692,0.017748,0.280889,-0.082149,-0.005717,-0.343408,-0.025422,0.010846,-0.335417,0.122627,0.118027,-0.154422,-0.462535,0.178089,-0.119006,0.039973,0.158672,-0.071946,0.254287,0.242182,0.361671,0.043112,-0.204403,0.046967,-0.395428,0.229254,0.879903,0.158871,-0.047874,0.440958,-0.132571,-0.525279,0.216814,-0.096481,-0.134217,-0.019052,0.576936,0.071575,-0.001172,-0.105072,-0.303184,-0.320410,-0.187024,0.395014,-0.186412,-0.328753,-0.125826,-0.232015,-0.391573,-0.363179,-0.217567,0.061222,0.006418,-0.224139,0.491172,-0.731888,0.100291,0.527452,0.220812,-0.478076,0.730856,0.132021,-0.024798,-0.097419,0.147671,0.125414,0.008213,0.168783,0.214835,0.096293,-0.442152,0.082899,-0.296172,0.189336', '1301022', '1309297', '1308755', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293143', '十三号星期五', '悬疑', '1958年，水晶湖营地发生一起两人死亡的命案，而这只是陆续发生在水晶湖旁的一系列凶案和怪事之一，多年以来，附近居民视营地为不祥之地，有意无意敬而远之。水晶湖营地的老板史蒂夫为重整营地，雇佣六名辅导员一起将营地翻新，爱丽丝、杰克（凯文•贝肯 Kevin Bacon 饰）等六人性格活跃，不时用恶作剧缓解无聊的营地生活。另一方面，厨师安妮奔赴营地而来，却在临近村落受到了“疯子”劳夫的警告，结果安妮未到营地，便被害死在路上。水晶湖营地的怪事频现，蛇和劳夫先后拜访辅导员们，为当地的传言更增添了注脚。当夜大雨倾盆，各行其是的辅导员们先后被杀害，而凶手，就潜藏在他们的周围。©豆瓣', '贝丝蒂·帕尔默', '肖恩·S·坎宁安', 6.4, 6998, 'tt0080761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209366658.jpg', 2.5, 14, 54.1, 20.4, 9, '0.414721,-0.171772,-0.663859,0.296623,0.246840,0.045287,0.816262,0.201792,-0.631243,-0.181565,0.286951,0.504890,-0.288813,0.129207,0.101140,-0.270080,-0.311973,-0.467368,-0.152388,-0.434003,-0.520688,-0.241886,-0.046292,-0.430317,-0.075321,-0.436568,0.187260,0.223051,0.124836,0.537218,0.092622,0.504173,-0.322968,0.328801,-0.076731,-0.054339,0.323997,0.049907,-0.209817,0.235002,-0.534028,-0.186520,-0.398562,0.172449,0.159365,0.275873,1.061809,-0.022054,-0.387715,-0.273466,0.022965,-0.433215,0.227364,0.035784,0.951425,-0.029669,0.239819,0.240190,-0.205900,-0.085494,-0.098355,0.005916,-0.372907,0.236037,0.146515,0.012718,-0.432154,0.163811,0.333427,-0.142926,0.249091,-0.175876,0.286041,0.448658,0.272346,0.092547,-0.042225,-0.322730,-0.451870,0.154299,0.673832,-0.180339,-0.056074,0.031401,-0.148166,-0.267024,0.218048,0.116035,-0.337871,-0.081902,0.246552,-0.137285,-0.096093,0.154168,-0.747575,-0.024245,-0.390187,-0.566470,0.025586,-0.303090,-0.351804,-0.978220,0.069158,0.067680,-0.142759,0.320268,-0.023241,0.367621,0.413201,-0.645990,0.480413,0.751744,0.127049,-0.616523,0.503377,-0.263287,0.136525,-0.037646,0.022329,-0.043655,0.310950,0.548454,0.207701,0.144576,-0.353414,-0.245212,-0.574384,0.262402', '10466639', '1914923', '1306809', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293145', '费城故事', '剧情', '安德鲁（汤姆•汉克斯 Tom Hanks 饰）和米勒（丹泽尔•华盛顿 Denzel Washington 饰）认识于法庭上，两人都是年轻有为的律师，各为其主。然而，年轻的安德鲁不久后因为同性恋和身染艾滋病被老板发现，以莫须有理由解雇了。遭解雇后的安德鲁四处寻找律师为他讨回公道。当安德鲁找到米勒时，米勒一开始拒绝了他。因为米勒像普通人一样憎恨同性恋和惧怕艾滋病，但当他看到安德鲁在图书馆搜索“艾滋病歧视”时遭到管理员的白眼，听着妻子缓慢而平静地说出他们的姨妈、朋友有很多也是同性恋时，他决定受理安德鲁的案件。在最后的法庭上，病危的安德鲁毅然出庭……©豆瓣', '汤姆·汉克斯', '乔纳森·戴米', 8.7, 95487, 'tt0107818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p750348993.jpg', 0.1, 0.5, 9.3, 44.2, 45.8, '0.399946,-0.032266,-0.696982,0.391518,-0.225365,-0.452203,0.922319,0.206024,-0.625748,-0.176897,0.036064,1.165546,-0.390298,0.240053,0.402858,0.045003,-0.414240,-0.661604,0.033369,-0.110340,-0.246251,-0.975475,0.006342,-0.392072,-0.146960,-0.245899,0.250932,-0.113347,-0.159404,0.432165,0.411235,0.444219,0.281072,0.610389,-0.050453,0.083333,0.147915,-0.059368,-0.336202,0.256543,0.246238,-0.064201,-0.021214,0.154183,-0.119962,0.599322,0.261772,-0.059916,-0.265521,-0.179811,0.476359,-0.358466,0.040390,0.376983,0.386639,0.153167,0.196238,0.301188,-0.106390,-0.225042,0.079862,0.134894,-0.537030,0.035688,-0.116180,0.370434,-0.469598,0.411606,-0.287054,0.043435,0.095807,-0.304453,0.253791,0.095956,0.132512,0.285617,-0.039818,-0.035605,-0.488065,-0.007340,0.446213,0.246835,-0.280159,0.136693,-0.208502,-0.413649,0.336158,-0.060905,-0.440024,0.062660,0.200270,0.080745,-0.417683,0.002519,-0.309173,-0.332210,-0.223987,-0.082862,-0.274860,-0.444498,-0.268528,-0.641772,-0.028941,-0.327332,-0.406870,-0.065109,-0.153014,-0.301666,0.459467,-0.872764,0.375608,0.519427,0.338281,-0.532761,0.695578,0.213951,-0.031169,-0.123606,-0.131238,0.171012,0.271678,0.386655,0.373591,0.135517,0.165645,-0.250167,-0.077817,0.401400', '1297239', '1302384', '10546747', '26420626');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293146', '豹', '剧情', '影片以1860年意大利的西西里岛为背景，通过萨里纳亲王这个中心人物的心路历程，反映出面对风起云涌崭新时代的到来，身处翻天覆地的社会变革的浩荡潮流当中，原有权贵和贵族因此而没落这一无奈而必然的命运。萨利纳亲王一家原本过着平静的生活。但随着局势的急剧变化，亲王的外甥唐克雷迪投奔正在西西里登陆的青年意大利党人加里波军队。返回故里，唐克雷迪对市长塞达拉的女儿安杰莉卡一见钟情，两人情投意合，不久便订婚了。塞达拉答应给女儿一份丰富的嫁妆，这样便挽救了萨利纳即将衰败的家族，而塞达拉也因能跟大贵族攀亲而沾沾自喜。此后，西西里岛进行了全民投票，结果一致赞成归并意大利。都灵派来了使者，邀请萨利纳作为名门贵族的代表，参加议会工作，但被萨利纳拒绝了。新政府没有给这个沉睡了两千多年的岛屿带来任何变化，特别是加里波在战败后，巴勒莫上流社会的生活又恢复了旧貌，贵族们频频举行舞会，庆幸劫后余生。', '伯特·兰卡斯特', '卢基诺·维斯康蒂', 8.8, 13746, 'tt0057091', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2195195471.jpg', 0.3, 1.1, 10.1, 37.5, 51, '0.197935,0.215083,-0.581621,0.675809,0.064763,-0.233547,0.442625,0.333445,-0.711178,-0.316052,0.053549,0.842214,-0.038219,0.038505,0.623892,-0.106611,-0.378788,-0.495749,0.008881,-0.022348,-0.060615,-0.441154,-0.209415,-0.247098,-0.052997,-0.403701,0.613277,0.059401,-0.062053,0.675594,0.118684,0.350508,0.024517,0.369716,-0.067765,0.055077,0.095310,0.074464,-0.411993,0.277896,-0.130972,-0.135089,-0.204911,0.254362,0.233599,0.587366,0.320569,-0.388344,0.183699,-0.186454,0.523363,-0.247416,-0.319568,0.478582,0.364111,0.084512,-0.022244,0.192214,-0.029027,-0.280408,-0.121067,-0.227907,-0.425150,0.075390,0.120369,0.154637,-0.549753,0.485885,-0.061290,-0.388180,-0.174881,-0.214109,0.310491,0.841534,0.205583,0.350582,-0.088790,0.051321,-0.522093,0.055377,0.827129,0.038412,-0.391189,-0.129675,-0.350900,-0.433898,0.165121,-0.507082,-0.455350,-0.049516,0.073738,0.218291,0.280969,0.601528,-0.526528,0.023382,-0.470076,-0.522331,0.370904,-0.462621,-0.094355,-0.628344,-0.337500,-0.191949,-0.118740,-0.029005,0.112541,0.012498,0.614443,-0.638840,0.258080,0.325265,0.411566,-0.646826,0.505548,0.002476,0.278519,-0.163585,-0.103915,0.088421,-0.025723,0.240975,-0.113103,0.190837,-0.143748,-0.472960,0.036838,0.340696', '25721544', '1302987', '27042738', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293147', '辣手神探', '剧情', '袁浩云（周润发 饰）是警署侦探，为人正直但行事火爆。他的好友在一次捕匪行动中不幸遇难，令他更加急于报仇。袁正侦探一桩非法军火集团的重案，但为了案件侦破顺利，袁的上司决定让他不再负责此案。此时，袁的女友也离他而去，并对他的敌人产生了感情。这个敌人，正是军火集团里面的头号马仔江浪（梁朝伟 饰）。江郎行事拼命，千方百计博得集团头目信任。袁在追捕中与江相遇，眼看大难临头却发现江放他一马，原来另有内情。©豆瓣', '周润发', '吴宇森', 7.9, 37355, 'tt0104684', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2606098518.jpg', 0.3, 2, 23.7, 50.9, 23, '0.044586,0.127908,-0.555353,0.592720,0.069762,-0.073666,0.528617,-0.000347,-0.625818,-0.498032,0.144408,0.551233,0.255061,-0.024196,0.026878,-0.139549,0.058502,-0.554636,-0.104527,-0.048207,0.113552,-0.558684,-0.184214,-0.481028,-0.155647,0.317436,0.562094,0.410276,-0.139107,0.456302,0.518704,0.263493,-0.091875,0.856587,0.335985,-0.148235,0.273930,-0.041845,-0.365073,0.081212,0.279891,-0.482481,-0.079085,0.340772,-0.030422,0.541650,0.330994,-0.051354,-0.490013,-0.237667,0.432153,-0.506538,0.263778,-0.084868,0.602323,-0.004154,-0.065299,0.295178,-0.295403,-0.151027,-0.151834,-0.052257,-0.750282,0.059167,0.275231,0.031216,-0.349131,0.062534,-0.419248,0.303551,-0.078207,-0.203764,0.060077,0.404039,0.565408,-0.211832,-0.235530,0.227711,-0.644787,0.098794,0.758780,0.086139,0.316706,0.122522,-0.043203,-0.486492,-0.149773,-0.354741,-0.219071,-0.142013,0.411421,-0.143172,0.031782,0.074828,-0.292636,-0.376964,-0.236766,0.230983,-0.110104,-0.535052,0.247796,-0.384961,-0.177628,-0.289525,-0.204122,0.059090,0.021124,-0.679762,0.494363,-0.748335,-0.348470,0.792731,0.246629,-0.963389,0.570650,0.186513,0.134698,-0.419839,-0.215848,0.167414,0.467745,0.108008,0.146835,0.093996,0.048202,-0.440194,-0.083504,-0.026957', '35073886', '1308206', '1293265', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293150', '宾虚', '剧情', '故事发生在古罗马时期，护民官米撒拉(史蒂芬•博伊德 Stephen Boyd 饰)回到了故乡，重遇了儿时的好友宾虚(查尔登•海斯顿 Charlton Heston 饰)。宾虚家是犹太人的豪门，在犹太人中享有相当高的待遇，为了控制犹太人，使他们安份的臣服于古罗马帝国的统治之下，米撒拉希望宾虚帮忙。但宾虚不肯出卖自己的民族，于是两个好友决裂了。随后，米撒拉找了借口治了宾虚一家谋反罪，宾虚被卖到一艘军舰上当奴隶，而他也失去家人们的信息。一次偶然机会，宾虚立了战功，得到了古罗马的皇帝接见，他回到了故乡，也开始了他的复仇之旅!©豆瓣', '查尔顿·赫斯顿', '威廉·惠勒', 8.7, 33080, 'tt0052618', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2201168652.jpg', 0.3, 0.8, 10.8, 40, 48.1, '0.183591,0.107903,-0.600980,0.557849,-0.137558,-0.316616,0.424211,0.238253,-0.726297,-0.047968,0.000028,0.824755,0.064288,0.006465,0.422283,-0.037614,-0.405460,-0.597303,0.284768,-0.415954,-0.139991,-0.486817,-0.311175,-0.403847,-0.320399,-0.410844,0.242924,0.060152,-0.161779,0.215044,0.131181,0.173834,0.309440,0.215751,-0.228959,0.106399,-0.043539,-0.195985,-0.291723,0.471380,-0.205045,-0.126197,-0.160951,0.236905,0.124681,0.398819,0.456217,-0.305889,-0.004475,-0.238852,0.181633,-0.184454,0.019655,0.059546,0.158016,-0.061341,-0.008462,0.258920,-0.063265,-0.070654,0.331810,-0.031462,-0.529138,-0.094128,-0.047383,0.041553,-0.714320,0.620297,-0.178945,-0.044405,-0.110561,-0.319255,0.230908,0.423447,0.333524,0.283392,-0.155712,-0.056389,-0.683723,0.222092,0.664963,-0.077990,-0.140498,-0.002011,-0.135357,-0.496044,0.042079,-0.225645,-0.352320,-0.121059,0.701258,-0.081711,-0.071332,0.514011,-0.712371,-0.526306,-0.505973,-0.221670,0.072573,-0.449634,0.135927,-0.240285,-0.205390,-0.045801,0.052354,0.059769,0.133512,-0.319290,0.566494,-0.621514,0.455992,0.629968,0.591644,-0.554509,0.545284,-0.162742,0.160183,0.011114,0.273591,0.396764,0.267775,0.315024,0.163482,0.088755,-0.039317,-0.305477,-0.240700,0.389960', '1309069', '26393561', '25721544', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293153', '德意志零年', '剧情', '影片主要讲述战争给给人民带来的灾难，战争不仅使人民陷入饥饿贫困，还是儿童的心理产生畸形。影片中的主角是个儿童，他把他那卧床不起、患有心脏病的父亲毒死，因为他认为父亲对社会豪无用处。事后，他又因内心不安而自杀。影片表面上把这个儿童产生杀父和自杀的心理归咎于一个老师的教育错误，实际上则是在揭露德国的纳粹主义，认为他们才是这一切罪恶的根源。', '埃德蒙·默施克', '罗伯托·罗西里尼', 8.4, 6535, 'tt0039417', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2326121296.jpg', 0.3, 0.5, 11.3, 55.6, 32.4, '0.017818,-0.144861,-0.686297,0.711711,-0.272631,0.035269,1.034225,-0.044471,-0.455015,-0.454194,0.400504,0.926051,0.046416,0.192047,0.165207,-0.074951,-0.274217,-0.585253,-0.210666,0.301833,-0.309160,-0.338381,-0.198706,-0.427706,-0.268119,-0.260865,0.887751,0.163157,-0.698937,0.241200,0.232035,0.764648,0.496695,0.344700,0.032064,0.163242,-0.440490,-0.220524,-0.245439,0.014849,0.484172,-0.509927,0.266465,0.842891,-0.337938,0.500361,0.897082,-0.463083,-0.541948,-0.325759,0.999760,-0.854070,-0.205345,0.313629,0.205760,0.161837,-0.005836,0.158072,-0.255910,0.051512,0.193761,0.124015,-1.163473,-0.411421,0.080804,0.130664,-0.365831,0.554006,0.056730,-0.209264,-0.011218,0.134110,0.222468,0.294653,0.470604,0.646629,-0.437681,-0.128632,-0.422730,-0.032661,0.792623,-0.342687,-0.215844,0.261076,-0.887593,-0.332493,0.371980,-0.548462,-0.437817,0.170530,0.043430,-0.179620,-0.598675,0.530614,-0.307692,0.011669,-0.090177,-0.518724,-0.048916,-0.394339,0.015509,-0.146836,-0.367912,-0.461423,-0.405503,-0.468920,0.232208,-0.363346,0.888518,-0.674512,0.237963,0.894185,0.259069,-1.051183,0.465182,0.427375,-0.098316,-0.218431,-0.127710,0.407805,-0.029730,0.207790,-0.102784,0.062905,0.396331,-0.050188,-0.170092,0.620344', '26678784', '4820775', '26667010', '25921830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293155', '愤怒的公牛', '剧情', '杰克•拉莫塔（罗伯特•德尼罗 Robert De Niro 饰）出身于纽约的布鲁克林区。自小便进行拳击训练的杰克很快就在拳击界崭露头角，他因在比赛中出拳迅猛，打击对手毫不留情，表现得就像一头公牛，被称为“愤怒的公牛”。虽然杰克表现出色，但因为他为人耿直，不肯屈服于黑手党的安排，所以在当时他一直无缘于挑战拳王金腰带。在多次失意后，杰克终于向黑手党屈服，听从安排输掉了一场比赛。之后杰克如愿挑战了拳王并顺利加冕。加冕后的杰克不仅没有体会到预想中的兴奋，反而看透了拳击界的种种黑幕，决意退出。©豆瓣', '罗伯特·德尼罗', '马丁·斯科塞斯', 8.4, 51110, 'tt0081398', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2427118378.jpg', 0.3, 1.1, 13.7, 45.5, 39.4, '0.011768,0.237385,-0.793392,0.625691,-0.249658,-0.265108,0.429255,0.095929,-0.278235,0.028722,0.396297,0.747799,-0.340884,-0.003632,0.370671,-0.355243,-0.263637,-0.790492,-0.141374,0.104493,-0.119450,-0.343236,-0.126716,-0.175827,0.041883,-0.379087,0.733441,0.051274,-0.529698,0.680850,0.211325,0.312123,0.203357,0.520100,-0.124894,-0.041545,0.173924,0.162996,-0.341994,0.320194,0.106065,-0.209312,-0.221780,0.456702,0.247598,0.308627,0.435690,-0.462360,-0.107053,-0.081208,0.302586,-0.209084,-0.041724,0.356186,0.541794,-0.114894,0.065505,0.081252,0.076095,0.325744,0.029965,-0.094947,-0.734635,0.141634,0.088408,0.026900,-0.583835,0.858384,-0.100890,0.167614,-0.199667,-0.055130,-0.126721,0.149362,0.193271,0.193766,-0.014039,-0.009331,-0.239059,0.197479,0.852275,-0.218822,-0.367654,-0.005817,0.319126,-0.393747,0.053096,-0.368118,-0.140911,-0.015759,0.695880,0.161028,-0.261293,0.355582,-0.146361,-0.039319,-0.394795,-0.348388,-0.274543,-0.514717,0.174042,-0.775709,0.037711,-0.252048,-0.165539,-0.027722,-0.072620,-0.218348,0.231247,-1.005218,0.486826,0.341613,0.191050,-0.194962,0.437554,0.044491,0.105697,-0.136611,0.053265,0.346817,0.144461,0.255792,0.245546,0.560566,0.083032,-0.339998,-0.102247,0.881243', '4202326', '35030151', '1652618', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293156', '处女泉', '剧情', '早上，虔诚的农场主陶尔（Max von Sydow 饰）夫妻做过了祷告，随后安排女儿卡琳骑马为教堂送一些蜡烛，卡琳穿上了新制的盛装，邀请家里的养女英格丽同行。有孕在身的英格丽性格放纵，并一直嫉妒卡琳的明媚人生，出行前，英格丽在食物中塞进了一只蛤蟆。行至一片森林前，英格丽让卡琳独自上路而自己尾随观察。林中的三个牧羊人看到孤身一人的卡琳顿起歹意，他们奸污后又打死了卡琳，掳走她的外套。傍晚，三名牧羊人投宿陶尔家中，向陶尔妻子兜售卡琳的衣物，惊慌的英格丽亦同时回到家中，她向陶尔忏悔了自己诅咒卡琳的罪行。陶尔沐浴更衣，以白桦树枝抽打自己后，决意用很双手为女儿报仇……本片获1961年奥斯卡最佳外语片奖，1960年戛纳电影节特别推荐奖。©豆瓣', '马克斯·冯·叙多夫', '英格玛·伯格曼', 8.6, 34156, 'tt0053976', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2186774515.jpg', 0.2, 0.7, 10.6, 46.6, 41.8, '0.009425,-0.277457,-0.499330,0.433948,-0.156778,-0.524052,0.788282,0.358529,-0.256887,-0.103367,0.520839,0.863024,-0.092372,0.221582,0.610145,0.218108,-0.673785,-0.637681,-0.057054,-0.245829,-0.248620,-0.049021,-0.071313,-0.141812,-0.194231,-0.301797,0.203079,-0.424753,0.164389,0.654655,0.404746,0.076787,-0.087677,0.242528,-0.066156,0.007759,0.162325,0.069417,-0.095709,0.306974,-0.260902,-0.312027,-0.267600,0.129740,0.182408,0.380650,0.760285,-0.242369,0.120726,-0.389193,0.495108,-0.122345,0.451172,0.342960,0.224581,0.008511,0.214555,-0.052068,-0.172602,0.074750,0.100872,-0.192572,-0.323424,0.144621,0.120160,-0.150521,-0.672355,0.285617,-0.140906,0.024463,0.159666,-0.391431,0.160265,0.342447,-0.031034,0.285470,-0.088078,-0.203975,-0.326905,0.141003,0.047330,-0.122884,0.339524,0.168839,-0.287100,-0.219493,0.439751,0.304801,-0.477291,-0.388852,0.342149,0.177762,-0.019788,0.233701,-0.424761,-0.246991,-0.290466,-0.336316,0.098464,-0.187680,-0.174666,-0.516165,0.094793,-0.185837,-0.338702,-0.238701,0.228076,-0.000699,0.235869,-0.310344,0.556398,0.484724,0.195928,-0.176420,0.459854,-0.206343,0.276309,0.198967,0.019302,0.566866,-0.059666,0.182514,0.109470,0.422554,-0.093151,-0.043786,-0.526640,0.362187', '2301242', '1309194', '2968813', '4319218');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293158', '甜心先生', '剧情', '杰里（汤姆·克鲁斯 Tom Cruise饰）待人和善，仪表不凡，是个出色的体育界经纪人。也许连天都妒嫉这个完美的男人，决定给他一个打击，杰里因为一篇流畅出色的发言稿而招来上司不满，导致被炒鱿鱼。漂亮女友离他而去，职业前景也陷入一片迷茫，从巅峰跌入谷底的杰克在临走前奋起疾呼，动员同事们跟他离开公司一起创业。结果，杰克只带走了一条鱼，还有愿意和他干一番事业的会计多萝西（芮妮·齐薇格 Renée Zellweger饰）。现在，杰克的客户只剩下一名二流的黑人橄榄球员罗德（小库珀·古丁 Cuba Gooding Jr饰）。万事开头难，杰克和多萝西还没有完全搞清楚要如何开始创业生涯。看来，要想迎来事业的第二春，杰克还要狠狠摸爬滚打一番；也正是在逆境中，他得以实践自己的职业信念，并寻获一生中的最爱。©豆瓣', '汤姆·克鲁斯', '卡梅伦·克罗', 7.5, 38910, 'tt0116695', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p494586571.jpg', 0.4, 3.1, 35.6, 44.2, 16.6, '0.052893,0.038038,-0.564966,0.641750,-0.364072,-0.649146,0.598333,0.111045,-0.268001,-0.258808,0.143861,0.755014,0.077782,0.244454,0.254882,-0.025475,-0.205148,-0.748183,0.058474,-0.008766,-0.094366,-0.554704,-0.293929,-0.068662,-0.111107,-0.189413,0.533780,-0.074513,-0.229422,0.305773,0.470395,0.142018,0.192412,0.428273,-0.149808,0.002584,0.176753,-0.182206,-0.369067,0.150949,0.135598,-0.002496,-0.272285,0.081404,0.052746,0.226360,0.404804,0.042031,-0.182892,0.048343,0.413227,-0.245325,-0.065943,0.267901,0.323853,-0.193412,0.228134,0.041808,0.004725,0.194942,0.083364,-0.206129,-0.982608,-0.080616,-0.084188,0.041128,-0.673242,0.414640,-0.007430,-0.106662,0.166472,-0.276149,-0.056010,0.162372,0.298412,0.392961,-0.237981,0.192279,-0.325147,0.332307,0.617912,0.201224,-0.126016,0.371115,-0.094338,-0.352553,-0.010025,-0.239580,-0.452849,-0.135876,0.412391,0.055543,-0.189974,0.040959,-0.504228,0.130803,-0.228201,-0.407390,-0.246476,-0.376953,-0.080439,-0.256220,-0.156479,-0.411773,-0.348519,0.006972,0.033167,-0.303151,0.836582,-0.698778,0.196172,0.478545,0.066950,-0.510081,0.560382,0.287367,0.243275,-0.204802,-0.220694,0.170500,0.042517,0.166340,-0.013055,0.375877,-0.051649,-0.334065,-0.399184,0.475483', '27602116', '30163500', '1793491', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293167', '生死时速', '动作', '退休炸弹专家佩恩（丹尼斯•霍珀 Dennis Hopper  饰）因不满政府的退休政策，产生了报复社会的念头。他先是在电梯里安装炸弹，劫持人质勒索100万美元赎金，但被特警杰克（基努•李维斯 Keanu Reeves 饰）拆除了炸弹，救出了人质。佩恩趁乱逃脱。一计不成，佩恩并没有放弃，他继续他疯狂的计划。这次他炸毁了一辆公车，并在另一辆公车上安装了炸弹，只要该公车的时速超过了50英里就不能再减速，否则就会引起爆炸。当杰克赶上这辆公车时，公车已经满载乘客行驶在高速公路上，时速也早已过了50英里。杰克是俗称的“胆生毛”，他冒险上了公车，和佩恩之间的生死时速开始了。©豆瓣', '基努·里维斯', '扬·德·邦特', 8.2, 116164, 'tt0111257', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2182085556.jpg', 0.2, 0.9, 17.2, 54.1, 27.6, '0.275350,0.127378,-0.682694,0.155867,0.006603,-0.166424,0.796552,0.047168,-0.244273,0.298582,0.339321,0.484008,-0.273470,-0.095875,0.121000,0.031780,-0.650618,-0.278862,0.075606,-0.273054,-0.511586,-0.608294,-0.014983,-0.314616,0.154397,0.060096,0.602079,0.033801,-0.086305,0.261934,0.173785,-0.090835,0.262638,0.721317,-0.221523,0.276905,-0.023050,-0.359361,0.249782,0.236976,-0.233562,-0.581364,0.429764,0.079212,-0.043191,0.666905,0.614011,0.150566,-0.119151,0.130722,-0.160559,-0.305825,0.098512,-0.142718,0.330333,-0.000033,-0.051904,0.049134,-0.098205,0.246378,0.287377,0.274869,-0.284562,0.017161,-0.726962,-0.255624,-0.619399,0.368481,-0.644873,0.046695,-0.042469,-0.253129,0.207601,0.085819,0.137878,-0.033722,-0.589010,-0.134107,-0.723810,0.183124,0.493565,-0.118522,-0.210666,0.477182,-0.133375,-0.511337,-0.254250,-0.203903,-0.224160,-0.370253,0.763458,-0.091816,-0.335276,0.125684,-0.286977,-0.031651,-0.611795,-0.248759,-0.307322,-0.002493,0.065199,-0.596010,0.431660,-0.142464,-0.087669,0.438415,0.091158,-0.078856,0.301723,-0.448470,0.150270,0.663478,0.428649,-0.457162,0.486680,-0.169230,-0.012328,-0.079937,0.236414,-0.120669,-0.196051,0.813100,0.208033,0.351248,0.191054,-0.334841,-0.100771,0.421190', '1301345', '1303462', '1292834', '1304129');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293171', '入侵脑细胞', '科幻', '儿童临床医学家凯瑟琳•迪恩（珍妮弗•洛佩斯 Jennifer Lopez 饰）供职于一家研究大脑的医疗研究机构，她的任务是通过高技术手段陷入幼年患者的梦境中，治愈她们幼小心灵中的疮疤。警方接到报案，说当地有很多幼女失踪。负责此案的FBI探员（文斯•沃恩 Vince Vaughn 饰）断定，此举为一个连环作案的变态凶手所为。经过调查，警方锁定了犯罪嫌疑人——卡尔•斯塔格（文森特•德奥诺费奥 Vincent D''Onofrio 饰），但是苦于他守口如瓶，无法救出被他囚禁的女孩。这时，警方联系了凯瑟琳，希望她可以通过梦境的方法，潜入犯人的大脑，找到受害者的所在位置。然而，事情远比想象得更加险象环生……©豆瓣', '詹妮弗·洛佩兹', '塔西姆·辛', 7.6, 51977, 'tt0209958', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1685867307.jpg', 0.6, 3.3, 30.7, 45.9, 19.3, '0.324263,-0.128936,-0.407344,0.579238,-0.039347,-0.066171,0.537676,-0.205772,-0.700975,-0.787752,0.193249,0.363257,-0.003430,-0.011308,0.066004,-0.079416,-0.446971,-0.542321,0.160747,-0.124248,-0.456275,-0.801549,-0.202207,-0.467829,-0.001694,-0.372678,0.558156,0.152209,-0.390929,-0.060201,-0.202741,0.745855,-0.089957,0.165366,0.136866,-0.256801,0.283066,-0.398337,-0.546997,0.437637,0.257947,-0.096589,0.181125,0.279185,-0.114110,0.398282,0.578541,-0.288865,-0.125108,-0.151753,0.410094,-0.341000,0.003973,0.086733,0.364528,0.176189,0.043689,0.166019,-0.480121,-0.078037,0.082430,-0.028655,-0.872193,-0.313158,0.358092,0.333601,-0.049933,-0.289202,-0.404791,0.484128,-0.070260,-0.106511,0.031619,0.314094,0.328973,0.311093,0.006344,0.047666,-0.465080,-0.067219,0.491042,-0.203120,-0.299367,0.169563,-0.418599,-0.649153,-0.005579,-0.132137,-0.045790,0.210359,0.246666,0.122110,-0.418818,0.440182,-0.177121,-0.335087,-0.532000,-0.021296,-0.268858,-0.214989,-0.057602,-0.869318,-0.203676,0.087089,-0.251183,-0.015174,0.117822,-0.392587,0.320125,-0.719628,-0.001208,0.562239,0.068160,-0.383853,0.391215,0.066504,0.177346,-0.427634,-0.183497,0.361871,0.553962,0.245419,-0.039531,0.038582,0.007353,-0.302963,-0.592640,0.058854', '2369613', '3006781', '2028645', '3541415');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293172', '末代皇帝', '剧情', '溥仪（尊龙 饰）的一生在电影中娓娓道来。他从三岁起登基，年幼的眼光中只有大臣身上的一只蝈蝈，江山在他心中只是一个不明所以的名词。长大了，他以为可以变革，却被太监一把火烧了朝廷账本。他以为自己是大清江山的主人，却做了日本人的傀儡。解放后，他坐上了从苏联回来的火车，身边是押送监视他的解放军。他猜测自己难逃一死，便躲在狭小的卫生间里，割脉自杀。然而他没有死在火车上，命运的嘲笑还在等着他。文革的风风雨雨，在他身上留下了斑斑伤痕。©豆瓣', '尊龙', '贝纳尔多·贝托鲁奇', 9.3, 806023, 'tt0093389', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p452089833.jpg', 0.1, 0.3, 4, 25.6, 70.1, '0.226358,0.190321,-0.999369,0.593858,-0.363005,-0.335884,1.085416,0.153860,-0.565388,0.109759,0.586657,0.828506,-0.029607,0.287068,-0.229895,0.285081,-0.403977,-0.838482,-0.216587,-0.160231,-0.475866,-0.252184,-0.311903,-0.154679,-0.397649,-0.179275,0.572637,0.217172,-0.112056,0.183992,0.407596,-0.260651,0.112312,0.759648,-0.627198,0.228915,-0.288914,-0.251527,0.375716,0.014411,0.135882,-0.856223,-0.264218,0.387000,-0.157222,0.368911,0.638306,-0.340285,0.204393,-0.101730,0.227379,-0.354252,-0.129701,0.310026,0.224840,0.058924,0.042511,0.150428,-0.166785,-0.058299,0.037403,0.272021,-0.665155,-0.199724,-0.411422,0.491853,-0.906186,0.791330,-0.343097,0.058763,0.068083,-0.547558,0.606672,-0.013992,-0.159228,0.489837,-0.381774,-0.125214,-0.940308,0.401638,0.433694,-0.147795,-0.102472,0.300838,-0.146264,-0.373078,-0.152045,-0.108929,-0.429520,-0.353467,0.522788,-0.290767,-0.529014,0.123551,-0.242666,0.258564,-0.171631,-0.224748,-0.155166,-0.286794,-0.160722,-0.001173,-0.247706,-0.527958,-0.615936,0.105862,0.094170,-0.324155,0.645133,-0.657837,0.132168,0.759457,0.370931,-0.199846,0.819909,0.049001,0.074600,0.275558,0.166904,0.009791,-0.061007,0.447592,0.431201,0.603685,-0.104240,-0.009918,-0.526747,0.649660', '1783772', '1306801', '21619567', '1421570');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293173', '古墓丽影', '动作', '20年前罗拉（安吉丽娜•朱莉 饰）的父亲（乔恩•沃伊特 饰）挖掘古墓得到的一个箱子里收藏了一个神秘的钟。罗拉从父亲那里知道，这个钟与一个神秘组织有关。这个叫光明会的组织相信当他们找到这个古钟后，便有了把时间与空间打开的钥匙，一把三角形的金属钥匙。多年来该组织一直在苦苦寻觅。 光明会希望通过这把钥匙让他们的组织始祖复活。但首先要找到钥匙。而且时间紧迫，两天后将出现日全蚀。这个时候三角钥匙内在的力量便会达到最大。光明会不想错过这个大好机会。罗拉扛上了这个艰巨的任务，在重重困难中寻找拯救宇宙的三角钥匙。©豆瓣', '安吉丽娜·朱莉', '西蒙·韦斯特', 7.1, 132313, 'tt0146316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p743262532.jpg', 0.7, 4.7, 43.5, 40, 11.1, '0.169744,0.723991,-0.729504,0.619552,-0.360314,-0.118324,0.746897,-0.311501,-0.345925,-0.532178,-0.091864,0.754426,0.133040,0.365834,0.128953,0.271385,-0.319036,-0.673875,-0.045099,-0.458330,-0.939860,-0.335198,-0.526842,-0.135958,0.059521,-0.028419,0.453824,0.234764,-0.000089,0.166301,0.249158,0.235267,-0.127076,0.247175,-0.285015,-0.178725,0.194754,0.007882,0.037996,0.655550,0.070550,-0.055412,0.269075,0.465663,-0.095823,0.231123,0.386300,-0.300452,0.005691,0.078915,0.442298,-0.086960,-0.294965,-0.141256,0.076344,0.048137,-0.218554,-0.080358,-0.622705,0.041099,0.072969,-0.363771,-1.124731,-0.137885,-0.290887,0.162504,-0.811581,0.104660,-0.072452,-0.133885,0.108319,-0.527448,0.630345,0.809113,0.428189,0.175763,-0.381294,-0.121213,-0.482049,-0.100962,0.332202,-0.556930,0.111721,0.182132,-0.042542,-0.524685,-0.101764,0.121780,-0.352750,-0.065423,0.630221,0.401963,0.011398,0.044132,-0.867587,-0.027757,-0.302596,0.009488,0.283867,-0.332565,-0.179580,-0.379461,-0.251304,-0.060324,-0.266538,0.374085,-0.151427,-0.273781,0.948837,-0.680250,0.355799,0.663403,0.407806,-0.378259,0.947079,0.066448,0.281264,-0.445770,0.373309,0.030407,0.263668,0.674171,0.117910,0.473669,0.338517,-0.462774,-0.732916,0.293425', '3785918', '1308585', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293174', '007之黑日危机', '动作', '这次007（皮尔斯•布鲁斯南 Pierce Brosnan 饰）对手是臭名昭著的国际恐怖分子雷纳德（罗伯特•卡莱尔 Robert Carlyle 饰）。为了垄断石油供给权，雷纳德杀害了石油大亨罗伯爵士，当然他也不会放过罗伯爵士的继承人——美丽的依蕾克屈（苏菲•玛索 Sophie Marceau 饰），这个狂人甚至威胁说要在土耳其巨大的输油管道里引发核爆炸。于是007必须驾着高速快艇从西班牙比尔堡的奈维河岸到伦敦的泰晤士河边，再穿越苏格兰的高地，冒着几乎不可能生还的危险去保护罗伯爵士队唯一继承人、粉碎雷纳德的阴谋。连场大战一触即发！©豆瓣', '皮尔斯·布鲁斯南', '迈克尔·艾普特', 7.6, 48054, 'tt0143145', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1545351100.jpg', 0.3, 1.9, 32.9, 49.4, 15.6, '-0.116799,0.211001,-0.801233,0.605247,0.131443,-0.139292,0.375860,0.077130,-0.265647,-0.086050,0.237264,0.831425,0.015771,-0.316686,0.312407,0.171568,-0.203700,-0.372901,-0.193590,-0.152813,-0.403686,-0.509754,-0.347862,-0.549283,-0.016450,-0.258946,0.404262,0.398845,-0.643406,0.037946,0.468857,0.391291,0.191102,0.393250,0.070842,-0.108006,0.149849,-0.149652,-0.337036,0.452854,-0.002465,0.033006,0.087742,0.009282,0.300647,0.394246,0.326689,-0.363068,0.521681,-0.063105,-0.013892,-0.392909,0.236270,0.043835,0.579730,-0.425114,-0.022592,0.218015,-0.033250,-0.246552,0.394462,-0.041965,-0.732073,-0.057006,-0.087166,0.245226,-0.374215,0.356161,-0.239051,-0.075376,0.064072,0.184030,0.376378,0.414526,0.082913,-0.048553,-0.071367,0.256428,-0.704849,0.179184,0.532541,0.144052,-0.092212,-0.171034,-0.114881,-0.299231,-0.202921,-0.489052,-0.393625,-0.272023,0.615820,-0.148220,0.079135,0.493402,-0.472658,-0.117927,-0.303971,-0.138634,0.055256,-0.107507,0.021425,-0.709532,0.364015,-0.256382,0.233897,0.332624,0.081980,-0.061751,0.382733,-0.417883,0.085100,0.535977,0.364641,-0.141187,0.324362,-0.053708,0.182884,-0.427663,-0.385308,0.503713,0.132878,0.348709,0.195307,0.244545,0.338515,-0.359643,0.166208,0.445415', '30216729', '1309069', '1759849', '26598021');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293175', '人生七部曲', '喜剧', '关于宗教的故事——失业的天主教徒唱着“每颗精子都是神圣的”，把一屋四五十个孩子送去做医学实验，因为再也负担不起他们，而对门的新教夫妇一面幸灾乐祸，一面感叹自己“只性交两次，有两个孩子”；关于性的故事——教授在课堂上向学生讲解“性”是什么，但是学生总不得要领，无奈之下，教授把自己太太拉过来当堂向学生示范；关于死亡的故事——死神来到一个农舍，声言要带走所有人，但这里聚集了许多美国朋友，不但毫不在意，还热情地邀请他喝酒聊天，让死神忍无可忍……人生七部曲，七个沉重的话题却放入足够荒诞的故事，嬉笑怒骂讽刺世间百态。©豆瓣', '格雷厄姆·查普曼', '特瑞·琼斯', 8.3, 7784, 'tt0085959', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2632964298.jpg', 1, 2.6, 16.7, 42, 37.8, '0.281350,-0.329531,-0.150332,0.444428,-0.154425,-0.255572,0.720592,0.001594,-0.591981,-0.181316,-0.041248,0.406094,-0.176154,0.333592,0.134282,-0.043138,-0.156007,-0.497470,0.030564,0.001401,-0.098095,-0.708541,0.165403,-0.300355,-0.187875,-0.369075,0.084810,-0.177614,-0.351808,0.265948,0.370783,0.073846,-0.309465,0.500344,-0.228326,0.020660,-0.000794,0.009895,-0.183138,-0.081806,0.128707,-0.158434,-0.367894,0.250460,-0.013277,0.137063,0.610617,-0.094370,-0.359172,0.187713,0.424275,-0.316581,-0.133255,0.279560,0.232407,0.292306,0.264154,0.336505,0.246451,-0.050691,-0.084805,-0.021594,-0.534913,-0.078285,-0.054393,0.143569,-0.667194,0.512442,0.038940,0.089592,0.047880,-0.230414,0.259411,-0.068893,0.253570,0.622937,-0.233345,-0.168114,-0.272104,0.360725,0.547038,0.139796,-0.077004,0.281460,-0.238217,-0.223339,-0.110156,0.045932,-0.583288,0.197256,-0.014828,-0.085244,0.051827,0.225485,-0.749856,0.007326,-0.040069,-0.224696,0.234106,-0.647748,0.036822,-0.463023,0.153667,0.142853,-0.433773,-0.089659,0.404208,-0.174943,1.135152,-0.427154,0.278060,0.581942,0.240476,-0.302999,0.605763,0.167562,0.184410,-0.197729,-0.032179,0.014169,0.163508,0.260496,0.089881,0.499628,0.067493,-0.131806,-0.366041,0.201608', '26348103', '26790961', '4181031', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293177', '桃色血案', '剧情', '律师贝克正在追查一桩凶杀案，当事人梅森中尉和他那自称被死者强暴的太太对真相有所隐瞒，死者邦尼和他们夫妻俩到底有何秘密？贝克能查到线索，找出事实的真相吗？', '詹姆斯·斯图尔特', '奥托·普雷明格', 8.2, 6280, 'tt0052561', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1986324385.jpg', 0.4, 0.8, 16.6, 53.8, 28.3, '0.354778,-0.499906,-0.495229,-0.057887,-0.409868,-0.035001,0.687355,-0.232321,-0.587727,-0.668259,0.030766,0.617484,-0.318284,-0.145547,0.221694,0.423189,-0.747753,-0.584588,0.812462,-0.532839,0.036695,-1.319623,-0.144185,-0.529791,0.456528,0.245126,0.119604,-0.071604,-0.061223,-0.380563,0.284444,0.819238,-0.663751,0.419614,0.117703,0.533322,0.557490,0.030025,-0.538187,-0.109554,0.596934,-0.417954,-0.012661,0.227544,-0.183445,0.895104,0.263075,-0.453855,-0.485794,0.453545,0.013223,-0.603236,0.321134,0.376222,0.589096,-0.329100,-0.095180,1.276349,-0.041237,-0.865525,-0.017195,0.500821,-0.742925,-0.190295,0.439769,0.686109,-0.036760,-0.121878,-0.700125,0.128699,0.323426,-0.497246,0.467163,0.706262,0.169899,-0.337605,0.000190,-0.265693,-1.176522,-0.192041,0.637725,0.047394,0.393798,-0.051245,-0.064125,-0.508800,-0.058486,0.010707,-0.136483,0.422145,0.277284,0.107342,-0.350091,0.267803,0.219484,-0.585959,-0.495535,-0.041888,-0.107292,-0.635239,-0.101675,-0.069358,-0.460958,-0.058892,-0.216727,-0.572616,0.504560,-0.447823,0.256603,-0.320126,-0.012170,0.507905,-0.094194,-0.793751,0.386511,0.350818,0.246717,-0.669742,-0.393124,-0.163084,0.681832,0.447530,-0.021253,-0.103305,0.698899,-0.120951,-0.281361,-0.327091', '1296217', '30318116', '25862560', '25789402');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293179', '美梦成真', '剧情', '克里斯（罗宾·威廉姆斯 Robin Williams 饰）与安妮（安娜贝拉·莎拉 Annabella Sciorra 饰）深爱着彼此，这对让人艳羡的夫妻有个美满的家庭，聪明可爱的孩子们，坚贞不移的爱情。可是一切都在孩子们意外死亡后打碎了。自从孩子们逝世后，克里斯与安妮每天都活在痛苦之中，他们心里惦记的始终是死去的孩子，他们的生活彻底失去了快乐的根源，都变得郁郁寡欢，但两人依然互相依靠着生活。可是，厄运并没有就此停止。安妮最心爱的克里斯也在意外当中逝世，死后的克里斯在天堂上看到了自己的孩子，仿佛生活又回到了当初快乐的样子，但他的心里仍记挂着尚在人间的妻子。丈夫的逝世，使安妮心痛不已，生活变得更加难熬了。终于，她还是无法忍受独自生活的寂寥，自杀了。生前的她经常凭想象画出天堂的样子。可是由于自杀，她只能堕入地狱。克里斯誓要留在妻子身边，不让她继续受折磨。于是，他到地狱去了……', '罗宾·威廉姆斯', '文森特·沃德', 7.9, 11988, 'tt0120889', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1421685562.jpg', 0.7, 3.2, 24.7, 42.7, 28.7, '0.051723,-0.051732,-0.870307,0.459181,-0.229877,-0.624837,0.965625,0.180392,-0.518382,-0.042405,0.281023,0.691890,-0.058752,0.507459,0.008841,0.132719,-0.471467,-0.613382,-0.022564,-0.063542,-0.188039,-0.288411,-0.108199,-0.382567,-0.133791,-0.266208,0.764176,0.028431,0.321671,0.374729,0.133406,0.277317,0.067096,0.596117,-0.332644,0.196056,-0.190039,0.190534,-0.258594,-0.066351,0.248638,-0.049536,-0.350269,0.314467,0.150906,0.006125,0.760791,-0.550048,-0.284132,-0.176320,0.185256,-0.282058,-0.211146,0.258364,-0.076361,-0.207418,0.292124,0.087506,-0.295804,0.157049,0.225834,0.070981,-0.688604,0.205772,0.066322,0.065165,-0.568937,0.525672,0.020388,-0.033046,0.322597,-0.453757,0.359531,0.281531,0.146663,0.754692,-0.563257,0.062853,-0.409794,0.070867,0.976333,-0.071906,-0.565911,0.498239,-0.463802,-0.201312,-0.152876,-0.311308,-0.881127,0.043747,0.172063,0.382137,-0.423493,0.637384,-0.416063,0.197166,-0.330460,-0.116645,-0.183092,-0.678661,-0.013866,-0.312549,-0.217290,-0.473439,-0.553574,-0.173158,-0.186584,-0.436208,0.753895,-0.753145,0.583597,0.492992,0.143223,-0.619522,0.543870,0.533988,0.182631,-0.082539,-0.143011,0.940176,-0.106237,0.244616,0.175677,0.045125,-0.245319,0.482740,-0.272045,0.831317', '1305666', '26245360', '2075721', '3001149');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293181', '惊魂记', '悬疑', '年轻的马里恩·克兰（珍妮特·利 饰）在Phoenix工作，深受老板洛厄里（沃恩·泰勒 饰）信任。男友萨姆·卢米斯（约翰·加文 饰）在Fairvale经营一家五金店，因要替亡父还债又要支付前妻赡养费而无力再婚，只能借出差的机会偶尔来与马里恩幽会。马里恩对此感到不满，于是在周五下午趁机携四万美元公款驾车潜逃。可是马里恩的潜逃之路并不顺利：先是在出城的时候被洛厄里目击，周六一大早又被警察怀疑。花了七百美元以旧车换新车之后，马里恩继续忐忑地行驶。入夜后，天降大雨，视线模糊，无法行驶，马里恩只得将车泊入路边的贝茨汽车旅馆投宿。老板诺尔曼（安东尼·珀金斯 饰）十分友善，试图邀请马里恩到家里共进晚餐，可惜被凶恶的母亲粗暴阻止，只得将晚餐端至旅馆客厅。马里恩在客厅一边进餐一边与诺尔曼交谈，终于决定周日返回Phoenix。用餐完毕，马里恩回房沐浴。这时，一个老妇的身影突然出现在卫生间……', '安东尼·博金斯', '阿尔弗雷德·希区柯克', 9, 261512, 'tt0054215', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1021883305.jpg', 0.2, 0.4, 6.1, 34.8, 58.5, '0.356007,0.091724,-0.539415,0.255190,-0.018037,-0.624539,0.517071,0.549932,-0.252228,-0.435590,0.059837,0.594037,-0.050787,0.303920,0.565499,-0.025219,-0.491396,-0.364011,0.161347,-0.041926,-0.237046,-0.725304,0.290547,-0.346478,0.097285,0.014397,-0.130757,0.056780,0.262712,0.758496,0.304651,0.188911,-0.052448,0.678892,-0.222782,-0.078470,0.288784,-0.045884,-0.152683,0.381080,0.057467,-0.189874,-0.244848,-0.083534,0.462524,0.298932,0.508592,0.065319,0.024543,0.270562,0.215725,0.060642,0.319324,0.218128,0.422078,0.014826,0.192389,-0.087082,-0.383813,0.101925,0.064568,-0.111844,-0.290069,0.318328,-0.223735,-0.155566,-0.665254,0.312709,-0.398758,0.053761,0.201443,-0.434814,0.011538,0.336839,0.177421,0.324353,0.157553,-0.060538,-0.462789,-0.136217,0.242077,0.071508,0.248297,0.300168,-0.057517,-0.248155,0.253369,0.157185,-0.374965,-0.302390,0.457254,0.183167,0.128020,-0.145596,-0.430108,-0.276102,-0.456701,-0.347698,-0.015081,-0.105977,-0.234910,-0.749154,0.146811,0.087715,-0.013715,0.246823,0.059285,0.144538,-0.043613,-0.481681,0.331265,0.508423,0.418430,-0.248095,0.535204,-0.135164,0.204588,-0.179336,-0.034543,0.203053,0.234276,0.421981,0.284464,0.144269,-0.170271,0.028860,-0.412810,0.106167', '2075345', '1