INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293182', '十二怒汉', '剧情', '一个在贫民窟长大的18岁少年因为涉嫌杀害自己的父亲被告上法庭，证人言之凿凿，各方面的证据都对他极为不利。十二个不同职业的人组成了这个案件的陪审团，他们要在休息室达成一致的意见，裁定少年是否有罪，如果罪名成立，少年将会被判处死刑。十二个陪审团成员各有不同，除了8号陪审员（H enry Fonda 饰）之外，其他人对这个犯罪事实如此清晰的案子不屑一顾，还没有开始讨论就认定了少年有罪。8号陪审员提出了自己的“合理疑点”，耐心地说服其他的陪审员，在这个过程中，他们每个人不同的人生观也在冲突和较量……©豆瓣', '亨利·方达', '西德尼·吕美特', 9.4, 448877, 'tt0050083', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173577632.jpg', 0.1, 0.2, 3, 21, 75.7, '0.451851,-0.018621,-0.788615,0.726218,-0.392633,0.144022,0.937600,0.094431,-0.581326,-0.090056,0.469873,0.747402,-0.073117,0.292876,0.255239,-0.181811,-0.462832,-0.902394,-0.187574,-0.264016,-0.572104,-1.273481,0.141788,-0.597751,-0.150688,-0.134737,0.599708,-0.083346,-0.283917,0.196989,0.448657,0.056724,-0.127181,0.499024,-0.238758,-0.066356,0.362245,0.009609,-0.127337,0.126881,-0.221583,-0.160455,-0.093937,0.372580,-0.210063,0.848112,0.672393,-0.344667,-0.509810,0.107527,0.401557,-0.461124,-0.110545,0.628681,0.638909,-0.108582,0.134782,0.644045,-0.004180,-0.091539,-0.330718,0.131883,-1.014966,-0.281490,0.270029,0.445643,-0.598415,0.746697,-0.145732,0.016571,-0.243265,-0.086740,-0.060034,0.330031,0.104368,0.411965,-0.142774,-0.273941,-0.727892,0.024107,0.633541,0.209549,-0.353502,-0.074916,-0.384296,-0.788442,-0.447841,-0.099186,-0.087102,-0.035813,0.108296,-0.017597,-0.093831,0.126397,-0.584402,0.100670,0.046737,-0.278326,-0.176771,-0.515041,0.203920,-0.454568,-0.127048,-0.251203,-0.725088,0.213982,0.226482,-0.279118,0.963531,-0.786520,-0.055450,0.413621,0.480370,-0.921106,0.790074,0.622063,0.235907,-0.551360,-0.408246,-0.227828,0.320345,0.131657,0.036566,0.460670,0.314299,-0.223863,-0.348722,0.146541', '2027899', '26678784', '3785918', '6557030');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293191', '亚利桑那之梦', '剧情', '在纽约打工的青年阿克塞（Johnny Depp 饰）梦中看到一位因纽特人昏倒在冰原上，雪橇犬将其救回，一只红气球在空中不停飘荡……阿克塞痴迷表演的朋友保罗（Vincent Gallo 饰）来访，邀请他远赴亚利桑那为伯父里奥伴婚，里奥在亚利桑那经营汽车生意打拼多年，遂留下阿克塞与保罗二人在车行中工作。不久阿克塞结识了性格不合的艾琳娜（Faye Dunaway 饰）与格蕾丝母女，为帮助艾琳娜圆一个飞行梦，阿克塞滞留这对母女家中，尝试制作各种飞行器，在不断的失败中从头再来，这对神经质母女的吵闹一直伴随着他。阿克塞的梦里，一只鱼在空中穿梭飞升……艾琳娜终于得到了一架小飞机，在庆祝的聚会上，阿克塞向格蕾丝示爱引发了意外的结局。本片获1993年柏林电影节银熊奖。©豆瓣', '约翰尼·德普', '埃米尔·库斯图里卡', 8, 12529, 'tt0106307', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1398203397.jpg', 0.5, 3.1, 21.7, 45.8, 29, '0.091937,0.053423,-0.507027,0.670755,0.102805,-0.391116,0.570743,0.204387,0.077514,0.124829,0.232027,0.769447,-0.326945,-0.062618,0.354953,-0.019939,-0.634861,-0.552979,0.221533,-0.117413,-0.166990,-0.463409,-0.441128,-0.444059,-0.215044,-0.310798,0.064781,-0.344926,-0.050152,0.703584,0.207448,0.034734,-0.357810,0.074110,-0.307361,0.148753,0.175623,0.332283,-0.301706,0.491838,-0.144667,-0.162214,0.044882,-0.029377,0.359637,0.350886,0.751090,-0.268630,0.338904,-0.033262,0.050931,-0.305411,0.224074,-0.182074,0.162038,0.140887,0.107789,-0.401617,-0.499609,-0.164990,0.316605,-0.154876,-0.281008,-0.131296,0.254113,0.277961,-0.494277,0.452413,-0.174707,0.137528,0.089005,-0.305288,-0.051544,0.484692,0.139686,0.371154,0.121472,0.258104,-0.545300,0.226120,0.485391,-0.175298,-0.026634,0.171686,-0.076685,-0.394297,0.222174,0.213451,-0.561315,-0.533180,0.504207,-0.270756,0.030106,0.534939,-0.554048,-0.022902,-0.467199,-0.297328,0.095596,-0.070033,-0.154800,-0.589050,0.068920,-0.278427,-0.257894,0.090557,-0.022649,0.052688,0.365254,-0.485116,0.731067,0.602897,0.237431,0.446063,0.736057,0.068587,0.355476,-0.181732,-0.120969,0.303961,0.145988,0.056923,0.100914,0.302338,-0.163162,0.191125,-0.614066,0.485769', '4319218', '1309194', '2131291', '3645150');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293200', '象人', '剧情', '象人（约翰•赫特 John Hurt 饰）是一个天生的畸形症患者，他的脸长得就像大象的脸，因此而得名。象人一直被利欲昏心的马戏团老板利用，带到世界各地去巡回演出，受尽了非人的虐待。象人所经受的遭遇社会名流们都会感到不可思议，然而乐观坚强的象人却承担了下来。直到有一次，象人遇上了年轻的英国医生（安东尼•霍普金斯 Anthony Hopkins 饰），出于怜悯和医生的操守，他与马戏团老板签订了“领养”协议后，将象人带回了医院作研究。在医院里，象人重新感受到了人间的温暖，而医生也在和象人的交往中结下了深深的友谊，他已经舍不得这位“上帝的弃儿”。但利欲昏心的马戏团老板带人又将象人抢了回去，象人的新生活是否就此终结？©豆瓣', '安东尼·霍普金斯', '大卫·林奇', 8.3, 27986, 'tt0080678', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1474924253.jpg', 0.2, 1.1, 15.9, 50.7, 32.1, '0.305240,-0.165782,-0.571156,0.250037,-0.252639,-0.255731,0.691862,0.246575,-0.462094,0.077082,0.203672,0.835373,-0.096991,0.325185,0.246822,0.292623,-0.227948,-0.631266,-0.188604,-0.101038,-0.357771,-0.297819,-0.247046,-0.410949,0.133727,-0.369895,0.364546,-0.046437,-0.200196,0.466362,0.167167,0.240944,0.045625,0.470686,-0.346379,0.212902,0.024504,0.162869,-0.121295,0.080758,0.279147,-0.102994,-0.129572,0.098584,-0.045733,0.491439,0.425797,-0.300946,-0.344406,-0.326037,0.311836,-0.281032,-0.118260,0.211729,0.094038,0.134040,0.169700,0.158989,-0.205866,0.203327,0.250136,-0.034077,-0.738050,0.028227,0.114700,0.170403,-0.774370,0.691849,0.083625,-0.027655,0.003452,-0.185260,0.284408,0.003423,0.053731,0.682516,0.086236,-0.154668,-0.621783,0.205042,0.838620,0.001169,-0.568043,0.226989,-0.374774,-0.551112,0.068676,-0.467084,-0.421879,-0.009883,0.280196,0.007018,-0.613126,0.067747,-0.644177,-0.110369,-0.279120,0.011117,-0.179926,-0.448694,0.078359,-0.464564,-0.191423,-0.583889,-0.205968,-0.027274,0.234577,-0.226669,0.797637,-0.742134,0.278066,0.541002,0.302712,-0.515502,0.717415,0.067625,-0.095034,0.117050,0.074036,0.201566,0.157853,0.524023,0.362910,0.218581,-0.053574,0.037808,-0.173326,0.392587', '30162520', '25721544', '35144311', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293203', '人鬼情未了', '剧情', '年轻的银行职员萨姆（帕特里克•斯威兹）与未婚妻美莉（黛咪•摩尔）相爱极深，在朋友卡尔（托尼•戈德温）的热情帮助下，他们搬进一幢漂亮的公寓，做着结婚前的准备。某晚看戏归来时，他们遭遇持枪歹徒，与歹徒搏斗时，萨姆不幸中枪身亡，美莉悲痛欲绝。萨姆变作幽灵，发现卡尔是导致他死亡的幕后策划，而为了窃取银行里的巨款，他又对美莉展开追求，以便获得萨姆所掌握的密码。为了保护美莉，萨姆常常游荡于她的周围，并渐渐地学会了如何使用力量，但他苦于无法同美莉交流。在能与幽灵沟通的灵媒奥塔的帮助下，他与美莉取得联系，但美莉起初并不相信，直到事实令她感受到萨姆的存在，可是，深深相爱的两人仍无法直接接触和交流。©豆瓣', '帕特里克·斯威兹', '杰瑞·扎克', 8.3, 203058, 'tt0099653', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p544574893.jpg', 0.1, 0.9, 16.7, 50.6, 31.8, '0.432657,-0.107340,-0.685192,0.447716,-0.080413,-0.353733,0.939942,-0.194133,-0.327517,-0.368751,0.153259,0.724363,-0.084292,0.179999,0.083456,-0.012614,-0.342815,-0.762826,0.006153,-0.142249,-0.211695,-0.694547,-0.472846,-0.171644,-0.177445,-0.289096,0.590714,0.061948,-0.236256,0.424653,0.249494,0.269019,-0.227682,0.529489,-0.085140,-0.156227,0.070076,0.048937,-0.484571,0.287906,0.132246,-0.007675,-0.100937,0.278073,-0.010682,0.369381,0.593964,-0.484709,0.076322,-0.186449,0.134113,-0.048709,0.172505,0.269437,0.021744,0.118227,0.157466,0.174798,-0.269538,-0.033316,0.093453,0.101564,-0.799704,0.059124,-0.003404,0.189257,-0.388429,0.226345,-0.189725,0.051667,0.179229,-0.285750,0.106751,0.475709,0.373765,0.230659,-0.312211,-0.160041,-0.573329,-0.290989,0.740752,-0.086198,-0.201664,0.386922,-0.388559,-0.514533,-0.094385,-0.125330,-0.399858,-0.125929,0.119119,0.543104,-0.257466,0.271318,-0.454455,-0.049739,-0.286144,0.046420,-0.141820,-0.428917,-0.005730,-0.828498,-0.207798,-0.555768,-0.449937,0.037937,-0.031932,-0.425006,0.531691,-0.940938,0.261751,0.451901,0.618377,-0.307191,0.679576,0.282745,0.079625,-0.216732,-0.198100,0.454934,0.230989,0.269351,0.297253,0.100651,0.005650,0.052202,-0.401003,0.430863', '1296370', '1308755', '3055049', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293204', '为黛西小姐开车', '剧情', '戴茜（杰西卡·坦尼Jessica Tandy 饰）小时候在贫民地方长大，丈夫生意的崛起才让他们家过上富足日子，所以戴茜非常节俭。现在她年事已高，不能自己开车了，儿子为她请来黑人司机霍克（摩根·弗里曼 Morgan Freeman饰），但是戴茜却十分不喜欢。她起初逃避出行 ，因为不想让霍克当上司机，后来她才觉得，儿子付了钱却不用他干活，似乎太不划算，于是终于给了霍克第一次为自己开车的机会。霍克是一个非常善良淳朴的男人，他知道自己不被接受，并没有把不快放在心里。相反地，他处处关心戴茜的生活，也慢慢了解戴茜坚守原则的执著性格。戴茜对霍克的排斥开始慢慢消融，直至几年间她终于发现，霍克是一个很值得信赖的朋友。于是，戴茜教会不识字的霍克传授认字，霍克也成为了戴茜晚年最贴心的朋友。©豆瓣', '摩根·弗里曼', '布鲁斯·贝尔斯福德', 8.3, 35500, 'tt0097239', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p861513408.jpg', 0.1, 0.7, 14.9, 54.1, 30.1, '0.406668,-0.106934,-0.660116,0.539199,-0.578120,-0.618397,0.731531,0.030772,-0.555466,-0.540600,-0.007699,0.805064,0.302384,0.142331,0.247200,0.327254,-0.310534,-0.336448,0.164742,-0.059971,-0.247802,-0.534667,0.006946,-0.317184,-0.509338,-0.068397,0.287872,0.144120,-0.076406,0.163529,0.121100,0.128433,0.646889,0.680079,-0.243766,-0.090017,-0.011743,0.041205,0.060121,-0.119341,0.168844,-0.254761,-0.278885,0.534301,0.314664,0.366943,0.354561,0.022162,-0.259514,-0.180888,0.007067,-0.215982,0.184799,-0.122192,-0.037432,-0.231194,0.357614,0.034653,-0.139256,-0.193142,-0.110386,-0.085533,-0.564673,0.247664,0.072090,-0.091319,-0.759733,0.340368,-0.274082,-0.178220,-0.066802,-0.654375,0.075415,0.238500,0.374136,0.200948,-0.122147,0.054140,-0.426701,0.107628,0.721905,0.168427,-0.110606,0.583642,-0.610567,-0.368148,0.233211,-0.310706,-0.800548,-0.190145,0.099438,0.154926,-0.220661,0.268195,-0.200147,0.011885,-0.230451,-0.231499,-0.020149,-0.568150,0.207343,-0.117608,-0.149685,-0.785216,-0.496322,-0.224610,-0.123758,-0.452296,0.679842,-0.919266,0.352323,0.410049,0.338397,-0.631791,0.773977,0.442791,-0.050653,-0.431780,0.020493,0.234901,0.118467,-0.063596,0.264179,0.161161,0.096309,-0.367559,-0.000089,0.902213', '1303112', '1308805', '3443074', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293212', '长大', '喜剧', '12岁的乔什（汤姆·汉克斯 Tom Hanks 饰）似乎对自己的年龄有些意见：个子太矮而无法坐绕环滑车，年纪太小追不到心仪女孩……于是他向游乐场里的一个古旧许愿机投了25美分，许愿变成一个大人。不料第二天起床，乔什竟发现自己一夜之间长大了近20岁，现在他是一个不折不扣的大人了，连母亲都认为他是绑架儿子的陌生人而将他赶了出去。乔什只好自谋生计，在一家玩具公司找到了职位。在一次偶然的机会，乔什孩子般的天真与热情给玩具公司老板留下了深刻印象，他的点子也使他在工作中频获嘉奖，很快住进了宽敞的公寓，并与年轻同事苏珊（伊丽莎白·帕金斯 Elizabeth Perkins 饰）展开了浪漫恋情。然而随着工作、生活、爱情这些成人世界的压力开始向乔什逼近，乔什那颗刚满13岁的心渐渐感到困倦失落，他开始回想，这是否就是自己想要的成长……本片曾获提名奥斯卡最佳男主角及最佳原创剧本。', '汤姆·汉克斯', '潘妮·马歇尔', 8.1, 19838, 'tt0094737', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554096254.jpg', 0.2, 1, 18.9, 52.5, 27.5, '0.080038,0.061586,-0.700712,0.376207,-0.453197,-0.412572,0.706613,0.298439,-0.394374,-0.190072,-0.068994,0.787918,-0.148210,0.527143,0.147504,-0.020410,-0.230595,-0.517424,0.037443,-0.250395,-0.064624,-0.456323,-0.120208,-0.263364,-0.047167,-0.344245,0.521848,-0.145599,0.104717,0.474972,0.447044,0.015615,0.212006,0.475266,-0.321038,0.180025,0.130217,-0.015847,-0.080486,0.370408,0.011998,-0.106394,-0.078111,0.152804,-0.083092,0.427099,0.733213,-0.109088,-0.434570,-0.021512,0.498063,-0.090020,-0.155628,0.172402,0.274088,0.134324,0.160036,-0.142682,-0.185391,0.124411,-0.001301,-0.293404,-0.444900,0.157581,0.090334,0.056458,-0.651803,0.310488,-0.179556,-0.042620,-0.026656,-0.414339,0.101333,0.186272,0.007406,0.383922,-0.340716,0.193015,-0.416971,0.197460,0.510891,0.006134,-0.252161,0.663980,-0.201857,-0.373790,-0.068528,-0.122191,-0.486775,0.037369,0.400626,0.034525,-0.079672,-0.145379,-0.375745,-0.062606,-0.275691,-0.145393,0.046012,-0.481987,-0.025975,-0.167959,-0.080601,-0.307697,-0.224588,-0.062963,0.009604,-0.378744,0.676429,-0.554754,0.075587,0.736348,0.189526,-0.368323,0.787399,-0.008395,0.094044,-0.200774,0.149578,0.128747,-0.314020,0.230746,0.062439,0.280241,-0.066407,-0.214058,-0.494262,0.467535', '1297606', '