INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293213', '恶魔', '剧情', '德拉萨尔寄宿学校里，女教师克里斯蒂娜和丈夫、校长米歇尔·德拉萨尔感情不偕，德拉萨尔对待他妻子也很粗暴。克里斯蒂娜经过长时间考虑，决定摆脱丈夫，在另一个教师、女友尼古尔的劝说下，她们决定实施一个谋杀计划……', '西蒙·西涅莱', '亨利-乔治·克鲁佐', 8.4, 16163, 'tt0046911', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p773231320.jpg', 0.3, 0.9, 11.8, 50.5, 36.4, '0.445026,-0.282918,-0.401878,0.729182,0.047621,-0.412627,0.475099,0.058777,-0.308960,-1.166682,0.051029,0.325111,0.006527,0.418947,0.485126,0.057908,-0.784998,-0.187108,0.298472,0.382325,-0.352724,-0.810988,0.034806,-0.484910,-0.218060,-0.117321,0.587700,-0.346442,0.083768,-0.061518,0.237744,0.724829,0.120643,0.197651,0.437330,0.185010,0.584424,-0.119861,-0.446285,0.428288,0.350722,0.181060,-0.213345,0.029182,0.218432,0.601461,0.546031,-0.015658,0.035423,-0.322326,0.105174,-0.395417,-0.094287,0.419119,0.075327,-0.353318,0.111802,1.090099,-0.071229,-0.078860,-0.262459,-0.322962,-0.177132,-0.024496,0.091723,0.184359,-0.599812,0.316435,-0.311963,0.414597,-0.209434,-0.264554,-0.615302,0.394138,0.006305,0.412729,-0.278999,0.384700,-0.136920,-0.164524,0.880387,0.170752,-0.083321,0.198043,-0.070737,-0.135866,0.459384,0.042753,-0.788346,-0.273172,-0.369832,0.100266,-0.115040,0.200965,-0.437403,-0.553416,-0.779765,0.555016,0.251744,-0.415369,0.129127,-0.613918,0.129225,0.239716,-0.728011,-0.095692,-0.298746,-0.122082,0.614071,-0.704910,-0.238051,0.044862,0.824122,-0.617675,0.587647,0.435404,0.317184,-0.899309,0.110057,0.221419,0.067340,-0.239330,0.058707,0.253637,-0.043496,-0.138267,-0.076610,0.401960', '3541415', '3329192', '10756870', '1419976');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293219', '雾都孤儿', '剧情', '奥利弗（马克·莱斯特 Mark Lester 饰）是一名孤儿，从小在教会中长大。九岁时，奥利弗被派遣到工厂做工，之后又来到殡仪馆成为了学徒。奥利弗的聪慧和机敏让他很快就在殡仪馆里站稳了脚跟，但与此同时，他亦遭到了同伴们的妒忌，他们故意挑衅激怒奥利弗，最终奥利弗离开了殡仪馆。无家可归的奥利弗过起了四处流浪的生活，经过漫长的旅途，他来到了伦敦。一个名叫道奇（杰克·瓦尔德 Jack Wild 饰）的扒手将奥利弗带到了匪首费金（朗·穆迪 Ron Moody 饰）的面前，就这样，奥利弗成为了他们中的一员。一次意外中，奥利弗被警察逮捕了，但随后，他被证实是无辜的，当事人布朗罗先生（Joseph O''Conor 饰）对奥利弗感到十分愧疚，于是收留了他，奥利弗的生活能够从此走上正轨吗？©豆瓣', '朗·穆迪', '卡罗尔·里德', 8.3, 7606, 'tt0063385', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2418457069.jpg', 0.4, 1.3, 14.5, 50.7, 33.1, '0.504518,0.158299,-0.682043,0.332663,-0.352649,-0.546292,0.863778,0.024417,-0.734294,-0.114048,0.219707,0.939948,-0.195096,0.446858,0.401790,0.177992,-0.331868,-0.685511,-0.076329,-0.436670,-0.279577,-0.410526,-0.095402,-0.294044,-0.225845,-0.294865,0.370311,0.114418,0.057643,0.656130,0.139994,0.387272,0.147928,0.490767,-0.363436,0.394535,0.439011,-0.268122,0.089142,0.361956,-0.050575,-0.279647,-0.086071,0.230887,0.040090,0.337770,0.723598,-0.139503,-0.101547,-0.229741,0.115234,-0.318787,-0.088169,0.429705,0.373301,0.087287,-0.029187,0.175813,-0.327179,0.273131,0.056723,0.007074,-0.670260,0.126262,-0.162481,0.001190,-0.942686,0.442172,0.015846,-0.209287,0.040519,-0.322555,0.342220,0.204912,0.247100,0.307152,0.012859,0.033024,-0.575473,-0.009709,0.648562,-0.078184,-0.207508,0.196626,-0.200520,-0.431965,0.114386,-0.139706,-0.388416,-0.182105,0.622709,0.006332,-0.269524,0.177545,-0.568526,-0.135041,-0.432773,-0.192954,-0.331190,-0.377155,-0.075970,-0.530519,0.001538,-0.403026,-0.394159,0.023955,-0.219036,-0.239964,0.579466,-0.820118,0.269440,0.369488,0.318251,-0.325324,0.460685,-0.089364,0.251427,-0.006051,0.115168,0.335824,0.275595,0.500381,0.441617,0.469494,-0.148714,-0.333291,-0.273031,0.420522', '3111650', '1309069', '1299965', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293226', '双重赔偿', '剧情', 'Walter Neff（弗莱德·麦克莫瑞 Fred MacMurray 饰）是一个成功的保险代理人，他在夜里回到办公室，开始在一个录音机上诉说他的故事......Neff为了取得Dietrichson先生的保险代理权，来到了他的家中，Dietrichson先生不在，Neff遇到了Dietrichson先生的新妻子Phyllis Dietrichson（芭芭拉·斯坦威克 Barbara Stanwyck 饰）。美丽的Phyllis让Neff感到不自然，而她也开始说起她的丈夫的诸多不好之处。在第二次拜访中，Neff终于控制不住自己的欲望，愿意参与Phyllis的杀夫计划。Neff计划在Dietrichson先生坐火车的时候制造他失足摔下的假象，以骗取“双重保险”。一切进行的非常顺利，Dietrichson先生死掉了，Neff和Phyllis两人的爱情和金钱似乎都有了保障。然而，Neff的好友保险调查员Barton Keyes （爱德华·罗宾逊 Edward G. Robinson 饰）却觉得事有蹊跷，开始调查整个事件......本片改编自James M. Cain于1943年出版的同名小说，由导演比利·怀尔德和侦探小说作家雷蒙德·钱德勒共同编剧，获第17届奥斯卡最佳影片等7项提名。', '弗莱德·麦克莫瑞', '比利·怀尔德', 8.5, 34923, 'tt0036775', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1675680930.jpg', 0.1, 0.4, 10.2, 51.9, 37.3, '0.410213,0.021028,-0.677546,0.562262,-0.098105,-0.401827,0.573686,0.108150,-0.468159,-0.314649,0.288444,0.921789,-0.188406,0.168952,0.219945,-0.061916,-0.317844,-0.535070,-0.007874,-0.196232,-0.141975,-0.657753,-0.289636,-0.222922,-0.221765,-0.351910,0.561336,0.012912,-0.183307,0.260676,0.183419,0.355651,0.102769,0.504920,0.007611,0.028210,0.185125,0.073464,-0.492363,0.376953,0.311233,-0.250407,-0.223113,0.308681,0.112398,0.520204,0.436902,-0.349936,-0.220695,0.206393,0.545324,-0.345180,0.118085,0.029571,0.040210,0.222700,0.159406,0.361229,-0.307464,0.005007,0.105960,-0.140953,-0.789207,-0.049401,0.247773,0.266682,-0.557906,0.356009,-0.439038,0.005556,0.108133,-0.396254,0.132112,0.361899,0.379409,0.188216,-0.162744,0.024442,-0.452047,0.332658,0.713915,-0.129580,-0.200255,0.375051,-0.034636,-0.481260,0.091967,-0.022833,-0.531890,0.041302,0.470647,-0.080117,0.050689,0.138088,-0.670696,-0.072146,-0.263899,-0.314249,-0.064548,-0.334910,0.147963,-0.447171,-0.264230,-0.175197,-0.100233,-0.055678,0.171742,-0.507675,0.610311,-0.934646,0.226865,0.632263,0.059180,-0.401769,0.593342,0.235297,0.156874,-0.231733,0.003662,-0.104160,-0.049800,0.303727,0.183497,0.410239,0.210109,-0.249251,-0.407888,0.355995', '1793491', '1783461', '1309069', '3592853');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293227', '替身杀手', '剧情', '来自大陆的杀手李强（周润发 饰）只身来到了美国，为了将还在家乡的母亲和妹妹接来美国一家团聚，无奈之下他只好向纽约曼哈顿唐人街的黑帮老大魏先生借钱。此时，魏先生的儿子因为在毒品交易中逃避警察而意外坠楼身亡，李强正好成了魏先生复仇的棋子。李强被派去杀害执行这次缉毒行动的负责人斯坦警官和他的家人，当他发现斯坦警官的儿子年仅7岁时，对家人的牵挂令他怎么也下不了手。行动失败后，不仅李强的生命受到了威胁，连他原在大陆的家人也面临杀身之祸。为了逃回家乡拯救家人，李强和魏先生派来的杀手展开了一场角力！©豆瓣', '周润发', '安东尼·福奎阿', 5.9, 6046, 'tt0120008', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203984083.jpg', 3.6, 20.3, 56.2, 15, 4.9, '0.137440,-0.069425,-0.781664,0.399317,-0.278996,-0.472146,0.460394,0.216855,-0.701033,-0.000682,0.441934,0.996116,0.258661,0.155698,0.378138,0.062267,-0.216440,-0.643143,-0.118903,-0.145900,-0.270880,-0.382449,-0.062781,-0.188958,-0.025309,-0.172049,0.350703,0.104359,-0.161870,0.582262,0.269053,0.330539,-0.210631,0.599291,-0.055869,0.094203,0.163681,-0.153646,-0.597860,0.529677,0.330484,-0.207062,-0.031643,0.399183,-0.064818,0.481861,0.592628,-0.041840,-0.059949,-0.400045,0.123530,-0.506846,0.032158,0.061850,0.396267,-0.150030,0.145788,0.332387,-0.225230,-0.112808,0.147991,0.037409,-0.811432,0.150780,0.144534,0.035678,-0.785115,0.285812,-0.259520,-0.062568,-0.077164,-0.498916,0.557975,0.666699,0.160967,0.223612,-0.403191,0.002411,-0.378813,0.175812,0.892978,-0.119100,0.186638,-0.105251,0.100168,-0.189039,0.196027,-0.306014,-0.492866,0.254545,0.339949,-0.171829,-0.160736,0.170954,-0.574317,-0.219255,-0.397449,-0.208384,0.035560,-0.495407,-0.002831,-0.430078,0.041931,-0.029646,-0.249225,0.029763,0.257288,-0.085617,0.487484,-0.860227,0.226017,0.702412,0.610294,-0.443231,0.472936,0.129908,0.059642,-0.473604,-0.193593,0.069759,0.180592,0.738126,0.234076,-0.177786,0.146971,-0.242396,-0.057140,0.054634', '25908042', '30345227', '1309069', '35461732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293232', '天堂之日', '剧情', '20世纪初，Bill（理查·基尔 Richard Gere 饰）本来是工厂里的一名工人，因为打架他只能离开了工厂，带着女友Abby（布鲁克·亚当斯 Brooke Adams 饰）和妹妹Linda离开了芝加哥，在德克萨斯州的一个麦田上找到了一份收割麦子的工作。Bill和Abby伪装成兄妹。一位年轻的农民（山姆·夏普德 Sam Shepard 饰），也是农场的主人被Abby吸引，同时，他发现自己患了绝症。为了窃取农场主的财产，Bill让Abby嫁给了那农场主。不料在日复一日的相处中，Abby也对农场主产生了爱情。另一方面，Abby和Bill不寻常的来往也让农场主极为不快。于是Bill离开了麦田。过了一段时间，Bill又回来了，农场主终于忍无可忍，端着枪走向了Bill......本片获奥斯卡最佳摄影奖，并获最佳服装、最佳原声等提名。©豆瓣', '理查·基尔', '泰伦斯·马力克', 7.9, 13568, 'tt0077405', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1612319609.jpg', 0.3, 2.1, 23.3, 51, 23.2, '0.321940,-0.193816,-0.534254,0.477836,-0.297064,-0.561990,0.926741,0.095693,-0.401865,-0.088516,0.003079,1.091231,-0.148262,0.238422,0.158701,0.098513,-0.388490,-0.416966,-0.256735,-0.238008,-0.301279,-0.378340,-0.265076,-0.014348,-0.212681,-0.261669,0.542854,-0.095478,0.063077,0.756015,0.329107,-0.015363,0.193366,0.569685,-0.362584,0.262033,0.197080,-0.049844,-0.217309,0.471441,0.129103,-0.466289,-0.100556,0.124504,0.138028,0.529945,0.708146,-0.146962,0.074458,-0.038147,0.237857,-0.272636,0.030838,0.143773,0.288757,-0.004898,0.065530,0.225883,-0.465841,0.231880,0.075652,-0.160066,-0.620653,0.143345,-0.019105,0.073381,-0.930724,0.459232,-0.013966,-0.202522,0.049788,-0.305172,0.518835,0.317692,0.028950,0.512924,-0.124809,-0.031230,-0.890959,0.410668,0.594530,-0.146111,-0.005219,0.453818,-0.193584,-0.539414,0.034055,-0.202857,-0.493820,-0.375904,0.556249,0.013151,-0.170407,-0.109197,-0.644281,0.122830,-0.090074,-0.410665,0.040480,-0.422928,0.026838,-0.551793,0.108904,-0.393213,-0.288740,0.236015,0.124442,-0.254202,0.670807,-0.826610,0.088814,0.479235,0.488621,-0.425109,0.652958,0.013431,0.263546,-0.164438,-0.053974,0.118796,0.062635,0.554619,0.483138,0.497752,-0.049487,-0.407118,-0.355920,0.487132', '1361252', '26678509', '3111650', '6879185');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293234', '第七封印', '剧情', '海滩边，巨浪滔天，英武的骑士布洛克（马克斯•冯•西多 Max von Sydow 饰）与黑衣死神（本特•埃切罗特 Bengt Ekerot 饰）摆下了一盘生死棋局。在下棋的过程中，骑士在回顾自己的人生，所见所闻暗合圣经的图景。十四世纪十字军东征后期，欧洲大陆瘟疫蔓延，民不聊生。布洛克曾遇到过马戏团的一对夫妻，丈夫笃信神明，无比虔诚，妻子则更加现实，唯命是从。他们的相濡以沫让幸福唾手可得。骑士在树林中邂逅了铁匠夫妇。铁匠非常粗鲁，他的妻子很是风骚，他们在树林里对着路人演出双簧，仿佛一对可笑的傀儡。最后，在经历过集体膜拜的祭奠仪式后，武士和他的朋友们再次遇到了死神，曾经的无助与恐惧，愤怒与怀疑，都化作了人生的诘问……本片获第10届戛纳电影节评委会大奖。©豆瓣', '古纳尔·布约恩施特兰德', '英格玛·伯格曼', 8.5, 49511, 'tt0050976', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2021642865.jpg', 0.8, 1.7, 13.1, 40.4, 44, '-0.146391,-0.367859,-0.623644,0.774817,0.097500,-0.279675,1.024146,0.072895,-0.416976,-0.013066,0.459602,0.815752,-0.321610,0.273304,0.554507,-0.292941,-0.284353,-0.663650,-0.290001,-0.122305,-0.095257,-0.104975,-0.284016,-0.156198,-0.169450,-0.453205,0.604749,0.168827,0.022641,0.430680,0.257958,0.228743,-0.233223,0.240716,-0.436690,0.160712,0.203738,0.334228,-0.632961,-0.125862,-0.167366,-0.002760,-0.371970,0.283805,-0.190724,-0.094989,0.768201,-0.536246,0.065140,-0.040436,0.330945,-0.140347,0.093877,0.143016,0.346524,0.042425,0.157391,0.111643,0.409412,-0.132690,-0.013933,-0.204005,-0.683010,0.039013,-0.020116,0.164336,-0.554065,0.689505,0.057141,0.131424,0.189711,-0.024074,0.265807,0.054522,0.372473,0.326854,-0.012800,-0.272619,-0.570338,0.513735,0.659867,0.246584,-0.397455,0.228845,-0.372360,-0.592949,-0.127644,-0.250220,-0.537054,0.012531,0.395199,-0.143906,0.003834,0.581123,-0.630539,0.117623,-0.049126,-0.098632,-0.081589,-0.223794,-0.145937,-0.537957,0.033998,-0.539424,-0.241835,0.016243,-0.027458,-0.056679,0.624860,-0.614454,0.409430,0.372095,0.232103,-0.072338,0.802904,0.154354,0.041057,-0.295959,-0.099746,0.410760,-0.105345,0.261165,0.282385,0.381012,-0.248290,0.290249,-0.266224,0.767159', '3055049', '30162520', '21619567', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293236', '黑猫白猫', '喜剧', '这是一部有些荒诞的电影。吉普赛人马特高（布赖恩•斯维登 Bajram Severdzan 饰）为了摆脱贫穷潦倒的生活，决心抓住眼前的一个发财良机，那就是在伊斯坦布尔和巴格达之间的列车上走私汽油，虽然要冒风险，但利润相当可观。为了凑足本钱，马特高和儿子去向当地的“教父”皮泰借了款。但马特高出师不利，被年轻的抢匪达丹（瑟丹•托德诺维奇Srdjan Todorovic 饰）抢了生意，这下本钱泡了汤。债务缠身，无奈之下马特高只好去请求达丹借钱。达丹满口应承了，条件就是马特高的儿子扎拉必须和他的妹妹结婚。扎拉虽然早已有心爱的恋人，但为了父亲他只能和达丹的妹妹举行婚礼。婚礼上，达丹的妹妹忽然逃跑了……©豆瓣', '斯尔詹·托多罗维奇', '埃米尔·库斯图里卡', 8.5, 20538, 'tt0118843', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2176669838.jpg', 0.4, 1.5, 12.5, 43.1, 42.5, '0.121619,0.031165,-0.514312,0.482752,-0.300743,-0.662897,0.510245,0.122092,-0.170479,-0.211080,0.131471,0.832837,0.183709,0.115166,0.327645,0.048299,-0.194394,-0.422412,0.088285,-0.053659,-0.226319,-0.447714,-0.128413,-0.125107,-0.266263,0.031648,0.339934,-0.021085,0.018346,0.516252,0.661359,0.081852,0.275764,0.230462,-0.330127,-0.102475,-0.053257,-0.195006,-0.422118,0.047401,0.056103,-0.114259,0.001497,0.071247,0.423538,0.387952,0.218358,-0.182322,0.049536,-0.135734,0.117985,-0.293930,0.244792,0.151981,0.031374,-0.056353,0.188209,0.040869,-0.335736,-0.308046,0.249329,-0.239753,-0.541251,0.148746,0.179812,-0.144908,-0.694001,0.280742,-0.135466,-0.101337,0.146003,-0.528194,0.119641,0.330536,0.155049,0.481285,-0.221895,-0.001350,-0.775733,0.063758,0.496345,0.093291,0.353089,0.303719,-0.293005,-0.561565,0.205951,-0.413653,-0.204646,0.012119,0.410767,-0.197135,-0.235122,0.189084,-0.644773,-0.146845,-0.220635,-0.136657,-0.033857,-0.255706,0.171699,-0.204616,0.013641,-0.444192,-0.227487,0.139956,0.293117,-0.139518,0.530546,-0.373594,-0.067386,0.608909,0.437287,-0.474445,0.517599,0.314748,0.112142,-0.029652,0.026368,-0.034071,-0.041076,0.229942,0.152667,0.225346,0.178609,-0.319337,-0.210893,0.611425', '1292584', '1299799', '30167633', '1293908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293237', '变脸', '剧情', '江湖艺人变脸王（朱旭 饰）孑然一身，以船为家，因恪守传男不传女、传内不传外之祖规，一手绝活面临失传。在活观音梁素兰（赵志刚 饰）惜才提点下，变脸王终生传承衣钵之愿。他用五枚大洋买下机灵的狗娃（周任莹 饰）。初时祖孙相处融洽，一场出街意外却令狗娃女儿身暴露。恼怒的变脸王意欲赶走狗娃，拗不过其苦苦相求，遂改自称“老板”，两人依旧搭伙卖艺。朝夕相处间，变脸王虽欣慰于狗娃孝顺懂事，碍于其女娃身份并不传授变脸绝活。按捺不住好奇的狗娃夜半偷看脸谱，失手引发船火，两人栖身之所烧毁殆尽。狗娃自感无颜，悄然离去，但心中始终感念变脸王的恩情。却不知，这份恩情有一日需要她以命相报，变脸绝活也终因此得以流传……本片曾获第16届金鸡奖最佳导演奖，第9届东京国际电影节最佳导演奖、最佳男演员奖等多项国内外奖项。©豆瓣', '朱旭', '吴天明', 9, 43801, 'tt0115669', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2440233036.jpg', 0.1, 0.3, 5.8, 35.9, 57.9, '-0.330583,0.139335,-0.531791,0.339173,0.280626,-0.041221,0.048530,-0.062737,-0.444212,-0.187735,0.215981,0.614769,-0.116073,-0.073789,0.109843,-0.288912,0.132597,-0.279607,0.116973,-0.229378,0.396713,-0.008200,-0.317267,0.272851,-0.647672,-0.104219,0.269877,-0.132091,-0.035547,0.544449,0.471725,0.069555,-0.311101,-0.115443,-0.053854,0.120608,-0.171154,0.312874,-0.431936,-0.056777,-0.025533,-0.292506,-0.302113,-0.045648,-0.010899,0.266704,0.381446,-0.065176,-0.344574,-0.200494,0.411974,-0.043131,-0.308788,-0.015955,0.139306,-0.023732,0.194206,0.191119,0.066275,0.199655,0.085340,0.111673,-0.441304,0.076515,0.523366,-0.029293,-0.384819,0.160113,-0.190402,-0.048011,-0.615897,-0.239837,-0.042599,0.049650,0.387310,0.046399,0.057791,0.211468,-0.246180,0.291534,0.135212,-0.143911,-0.160354,0.238209,0.004396,-0.356638,0.709673,-0.379953,-0.353505,0.158143,0.176411,0.262218,0.218329,0.096026,-0.039996,-0.125885,-0.317262,0.353906,0.162040,-0.275104,0.093805,-0.299128,-0.080710,-0.189175,-0.209069,-0.109569,0.278925,-0.373316,0.566638,-0.307049,0.304225,-0.051943,-0.113355,-0.319524,0.414583,0.332042,0.278288,-0.360280,-0.382516,0.168266,-0.229283,0.059512,-0.012253,-0.009055,-0.057180,-0.195463,-0.101015,-0.043175', '27602116', '1891179', '1305441', '4173583');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293258', '霹雳娇娃', '动作', '查理先生手下有三名女打手，她们才貌双全拥有一身好功夫，专门接受查理先生的命令为他人伸张正义。她们分别是：娜塔莉（卡梅伦•迪亚兹 饰）、戴兰（茱莉•巴里摩尔 饰）与艾利克斯（刘玉玲 饰）。她们最近接受了一个任务：艾瑞克•克诺斯（萨姆•罗克韦尔 饰）先生设计了一款高科技的声音辨别系统。艾瑞克却不幸被绑架了，这三名“天使”需要从不法分子手中拯救艾瑞克。因为这套由艾瑞克设计的高科技系统，一旦被不法分子利用的话后果堪虞。三位“天使”得知情况后，很快联想到了艾瑞克公司的对手，该负责人罗格成为了最大的嫌疑。三人于是日夜调查罗格的行踪，也掌握了重要的线索。正在她们有把握拯救艾瑞克的时候，一通电话打破了她们三人的全盘计划。©豆瓣', '卡梅隆·迪亚兹', '约瑟夫·麦克金提·尼彻', 6.9, 85118, 'tt0160127', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1664314074.jpg', 0.9, 5.8, 50, 33.6, 9.7, '0.252203,0.122202,-0.309691,0.388166,-0.157575,-0.223806,0.237166,0.009271,-0.414126,-0.501645,0.328568,0.737632,0.092776,-0.139171,0.418487,0.107635,-0.746260,-0.478138,0.118490,-0.357162,-0.295984,-0.602612,-0.150469,-0.460238,0.062456,-0.432338,0.280118,-0.178168,-0.207815,0.212170,0.273659,0.424650,-0.064277,0.156054,0.248981,-0.064952,0.624613,-0.497677,-0.342131,0.449740,-0.016667,0.094085,0.067952,0.362825,0.026236,0.343890,0.298953,-0.477208,-0.087308,-0.042033,0.112919,-0.217755,0.292444,0.073725,0.276604,-0.202552,0.181978,0.269543,-0.269571,-0.116626,0.195245,-0.023744,-0.911082,0.026240,0.063902,0.108721,-0.164272,-0.153204,-0.497055,0.050436,0.098015,-0.327812,0.097700,0.365109,0.500613,0.178153,0.038455,-0.000767,-0.352585,0.052876,0.497118,-0.201953,-0.187730,0.185932,0.046576,-0.380529,-0.149129,-0.137633,-0.162365,0.127318,0.604876,0.294417,0.127664,0.106916,-0.376392,-0.250953,-0.413258,-0.189452,-0.137924,-0.321626,0.028902,-0.608303,-0.151470,0.039043,-0.292191,-0.036322,0.180734,-0.037477,0.618802,-0.772724,0.075663,0.340485,0.190215,-0.547572,0.306864,-0.131679,0.283121,-0.325552,-0.117282,-0.124449,0.232925,0.224678,0.257431,0.360083,0.200836,-0.421445,-0.132465,-0.014494', '26678784', '1793491', '3006783', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293265', '97古惑仔战无不胜', '剧情', '黑社会洪兴社的屯门区话事人恐龙被东星社的耀扬杀害后，龙头蒋天养（万梓良）决定从山鸡（陈小春）和生蕃中选出一个填补该空缺，铜锣湾的话事人浩南（郑伊健）深知该职的压力，力劝山鸡放弃与人争权夺位，但苦劝无效。生蕃为打压山鸡，勾结耀扬设下诡计，令山鸡好友大天二死于非命。另一方面，屯门区某中学教师欣欣（李嘉欣）一向反感黑社会，但在结识浩南后，对黑社会的以往印象有所改变，更在短短时间内对浩南产生倾慕之情，两人发生一夜情。然而因为生活于两个完全不同的世界，加上浩南始终无法对前女友（黎姿）忘情，他们的感情注定只能是无疾而终。©豆瓣', '郑伊健', '刘伟强', 7.6, 71141, 'tt0128907', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2607350060.jpg', 0.5, 2.5, 32.6, 45.4, 18.9, '0.165598,-0.140483,-0.596239,0.425090,0.115519,0.047139,0.678054,0.320846,-0.736922,-0.268282,-0.007490,0.547997,-0.086450,0.059843,-0.014906,-0.603870,-0.036924,-0.622279,0.080435,-0.027503,0.140087,-0.560185,-0.019740,-0.172154,-0.301999,0.023444,0.759883,0.102363,-0.354596,0.396532,0.397550,0.256589,-0.188704,0.395965,0.111040,-0.009178,0.063600,0.151935,-0.580119,0.106249,0.111786,-0.027745,0.027491,0.266494,-0.162315,0.341907,0.699127,-0.289520,-0.412519,-0.344605,0.152008,-0.289270,-0.297966,0.036065,0.460820,-0.008275,0.182848,0.394931,-0.067978,0.058278,0.121315,0.157047,-0.628231,0.127342,-0.015433,0.161327,-0.340087,0.349817,0.085072,-0.153066,-0.159970,-0.211495,0.118009,0.238872,0.489333,0.010948,-0.290835,0.152820,-0.350119,-0.187758,0.922410,0.097246,-0.196061,0.233841,0.032534,-0.326948,0.007733,-0.379841,-0.070278,-0.042435,0.026550,0.142344,-0.294683,0.302121,-0.455910,-0.140434,-0.076896,0.095138,0.123908,-0.433377,0.035308,-0.389152,-0.443655,-0.457957,-0.250821,-0.107354,0.289835,-0.235769,0.610871,-1.080313,0.072512,0.166108,0.266747,-0.950887,0.528044,0.420604,0.041622,-0.348628,-0.107714,0.246270,0.078762,-0.152182,0.075594,-0.070253,-0.182140,-0.232639,-0.050820,-0.006196', '35030151', '30345227', '1301022', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293270', '寻子遇仙记', '剧情', '影片讲述玻璃匠夏尔洛（查理·卓别林 Charles Chaplin饰）和弃婴（杰基·考甘 Jackie Coogan饰）之间一段笑中有泪的感人故事。夏尔洛在垃圾箱旁发现了一个弃婴并收养了他。等到孩子长到四五岁的时候，就已经非常懂事。两父子合演双簧，儿子打碎玻璃，父亲就上 前更换玻璃从而养家糊口。夏尔洛带着“儿子”躲避警察的追捕，以免他被送入孤儿院。可孩子的母亲后来有了钱，悬赏找回孩子。有人为钱把孩子从夏尔洛身边偷走，他四处追查也没有找到。疲惫的夏尔洛在梦中来到了天堂。一觉醒来的他，居然发现“儿子”跟他的母亲就站在自己的眼前……本片在1978年巴西《标题》杂志评选的100部最佳影片中名列67。©豆瓣', '查理·卓别林', '查理·卓别林', 9.2, 40816, 'tt0012349', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2506524685.jpg', 0.1, 0.2, 4.2, 30.5, 65, '0.086786,-0.096344,-0.677438,0.310351,-0.291644,-0.577308,0.948313,-0.080621,-0.336781,0.057388,0.084505,0.789959,-0.286768,0.521296,0.149913,0.313013,-0.408547,-0.781151,-0.190743,-0.301865,-0.399440,-0.388831,-0.251437,-0.156073,-0.180596,-0.240997,0.482335,-0.180297,-0.028542,0.308293,0.201322,-0.244961,-0.183260,0.368522,-0.324631,0.342940,-0.124667,0.194548,0.180521,0.131964,0.015708,-0.328356,-0.154285,-0.092137,0.100576,0.361235,0.735833,-0.301015,0.217560,-0.049869,0.216165,-0.160626,-0.293080,0.049118,0.353361,0.167044,0.326587,0.191150,-0.305518,-0.142480,0.009266,-0.216634,-0.457689,0.009112,0.075317,0.119721,-0.791134,0.447637,-0.076098,0.070025,0.303688,-0.462803,0.391771,0.158538,0.018413,0.666736,-0.419099,-0.086827,-0.551931,0.289925,0.181903,-0.381196,0.080564,0.443803,-0.072342,-0.288392,0.120013,-0.145251,-0.393731,-0.004806,0.442178,-0.053176,-0.315653,0.091493,-0.305696,-0.077797,-0.290968,-0.161359,0.047481,-0.270133,-0.256988,-0.288950,-0.079418,-0.067605,-0.283556,0.193038,-0.018851,-0.378917,0.700298,-0.390076,0.442084,0.566277,0.188155,-0.137065,0.746900,-0.091333,0.150012,-0.115682,-0.074065,0.070537,0.205124,0.295204,0.176676,0.224652,-0.294423,-0.126437,-0.258513,0.446849', '21619567', '1307146', '26884422', '1292207');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293271', '甜蜜的生活', '剧情', '马切罗（马塞洛•马斯楚安尼 Marcello Mastroianni 饰）是某杂志的专栏记者，他曾试图成为一名作家但是事与愿违，只得终日为明星绯闻奔忙。马切罗经常出席一些社会名流的交际酒会，于是他暗自和摄影师勾搭，设计拍摄明星隐私然后公诸于众。马切罗有一个女友元玛，在送 她回家的途中，搭乘了一位妓院老鸨，后者对他讲述了很多风月场中的轶事，这让他对名利场更加厌恶。在基督教的某个仪式上，一位从美国来的名模总是对着媒体搔首弄姿，后来马切罗的批评家朋友斯泰纳一针见血指出了她的虚伪之处，这让他逐渐认清了上流社会的腐朽，并开始重新审视自己的生活。他发现自己并不热衷奢华的生活，而且对于那个自以为是的元玛也并不满意，并进行了我行我素的反抗……', '马塞洛·马斯楚安尼', '费德里科·费里尼', 8.6, 27983, 'tt0053779', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204676857.jpg', 0.5, 1.4, 11.4, 38.8, 47.9, '0.597023,0.121391,-0.530334,0.705200,-0.141103,-0.337550,0.785871,0.099466,-0.530109,-0.403169,0.037259,0.826091,-0.459161,0.263571,0.182289,-0.043738,-0.278738,-0.717103,-0.012317,-0.029758,-0.216067,-0.293443,-0.155679,-0.360680,-0.345852,0.012345,0.308930,0.121560,-0.413085,0.312956,0.515025,0.227302,0.276817,0.820491,-0.339154,-0.043323,0.075362,0.188891,-0.017115,0.086204,0.054158,-0.523465,-0.123800,0.312826,0.003150,0.364510,0.519989,-0.154615,-0.217875,0.077244,0.610621,-0.254547,0.168261,0.273982,0.145827,-0.088965,0.040810,-0.013227,-0.089182,0.152600,-0.096564,-0.028890,-0.751578,-0.100248,-0.020425,0.278482,-0.636219,0.576661,-0.140706,0.113570,-0.201053,-0.159319,0.133934,0.240032,0.108475,0.057615,0.130446,0.167719,-0.353851,0.535191,0.386986,0.490149,-0.117340,0.470831,-0.520226,-0.481799,-0.044353,-0.103489,-0.595185,-0.323396,0.332171,-0.194847,-0.094253,0.262602,-0.681309,-0.051549,0.084375,-0.259255,0.059626,-0.477452,0.102034,-0.781794,-0.157861,-0.561767,-0.221659,-0.181032,0.109374,-0.253156,0.821932,-0.821370,0.132563,0.802407,0.183201,-0.693218,0.727543,0.211720,-0.040196,-0.097138,-0.269384,0.347249,0.245853,0.340477,-0.218580,0.650174,0.247625,-0.485001,-0.281343,0.531662', '30162520', '3230462', '1292000', '3154392');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293276', '抚养亚利桑纳', '喜剧', '前科累累的惯犯嗨（尼古拉斯·凯奇 Nicolas Cage 饰）同狱警艾德（霍利·亨特 Holly Hunter 饰）一见钟情，两人喜结连理。之后，嗨决定为了爱妻痛改前非做个好人。非常喜欢孩子的艾德发现自己居然无法生育，终日郁郁寡欢，嗨看在眼里十分痛心。镇上的大亨亚利桑纳（特雷·威尔逊 Trey Wilson 饰）家诞下了五胞胎，听闻此事，艾德和嗨甘愿冒险，从大亨处偷了一个名叫尼尔森二世的婴儿。终于有了孩子艾德十分幸福，嗨却逐渐感到了作为一名父亲的压力。丢失了孩子的大亨十分焦急，报案之后警察却对案件毫不上心，此时，一名自称“地狱使者”的壮汉找到大亨，打包票能帮他寻回儿子。嗨的家里也是一团糟，两名囚犯越狱前来投奔嗨，他们发现婴儿身价不菲将其劫走。与此同时，嗨得罪过的上司也发现了婴儿的秘密，并以此要挟嗨对他百依百顺。千钧一发之际，为了妻儿，为了保护他所爱的人们，嗨不得不重出江湖。', '尼古拉斯·凯奇', '伊桑·科恩', 7.4, 11017, 'tt0093822', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203813792.jpg', 0.4, 3.2, 35.1, 47.9, 13.4, '0.021673,-0.431442,-0.438559,0.114978,-0.381343,-0.357829,0.567653,0.187866,-0.722377,-0.254966,0.082372,0.812447,-0.178087,0.344461,0.291810,0.108947,-0.193667,-0.324010,-0.047563,-0.118078,-0.022121,-0.331248,-0.316842,-0.243059,-0.346521,-0.453737,0.250940,0.026792,0.118851,0.473750,0.560635,0.485899,-0.078516,0.448510,-0.154765,-0.072761,0.240772,-0.013288,-0.319739,0.126784,0.111227,-0.003218,0.138594,0.377645,-0.043682,0.315197,0.325098,-0.438446,-0.112645,-0.322899,0.175047,-0.198976,-0.010182,0.078000,0.216483,-0.118302,0.157329,0.175384,-0.099134,-0.236605,0.139501,-0.143632,-0.517714,0.135678,0.109448,-0.010314,-0.447222,0.148135,-0.309853,0.146821,0.067637,-0.320826,0.253043,0.154481,0.006914,0.205381,-0.220048,0.228331,-0.408171,0.103677,0.516533,0.002733,0.165523,0.293274,-0.169253,-0.390354,0.397220,-0.343442,-0.562967,0.166245,0.246343,0.147286,-0.053688,-0.003850,-0.095390,-0.212198,-0.469903,0.043700,0.023425,-0.474969,-0.053452,-0.107401,-0.154048,-0.063132,-0.140364,0.076516,-0.004765,-0.180688,0.518232,-0.789685,0.085634,0.371106,0.106661,-0.414555,0.377493,0.270968,0.059101,-0.292806,-0.313742,0.099187,0.284422,0.086704,0.192371,0.029664,-0.048425,-0.366390,-0.104194,0.082952', '3