INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293285', '印度支那', '剧情', '法国占领越南的最后年代里，法国贵妇艾丽亚娜（凯瑟琳·德纳芙 Catherine Deneuve 饰）在越南南部经营橡胶园，她收养了父母双亡的越南公主卡米尔（范林丹 Linh Dan Pham 饰），两人相依生活。艾丽亚娜爱上年轻的越南殖民军海军军官詹·巴普蒂斯（文森特·佩雷斯 Vincent Perez 饰），但后来詹却与卡米尔陷入爱河。卡米尔誓死要嫁于詹，并离家出走追随詹去越南北方的龙岛。路途中，卡米尔因误杀一名法国军官遭到追杀，两人开始逃亡。途中，他们生下了儿子艾蒂安纳，最终两人被捕，儿子交予外祖母艾丽亚娜抚养。詹拒绝回国受审，愤慨自尽；卡米尔因大赦出狱，当艾丽亚娜前去接她回家时，卡米尔义无反顾地离开了这个家，成为一名坚定的越南民族独立共产党人。数年后，当艾蒂安纳再次见到作为越南代表团成员参加日内瓦谈判的母亲时，两人已然淡漠生分。本片获第65届奥斯卡金像奖最佳外语片。', '凯瑟琳·德纳芙', '雷吉斯·瓦格涅', 8, 8167, 'tt0104507', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2387304695.jpg', 0.6, 2.4, 22.5, 47.6, 26.9, '0.015153,0.104687,-0.449283,0.319728,0.152086,-0.475320,0.551209,0.074577,-0.513286,-0.250153,0.092488,0.942316,0.135748,0.162829,0.745195,0.359520,-0.537085,-0.715452,0.102284,-0.040732,0.038341,-0.563395,-0.056907,-0.147952,-0.222619,0.029550,0.721990,0.046690,0.125060,0.892714,0.171922,0.427022,-0.276499,0.350197,0.079362,0.231589,0.364959,-0.190101,-0.556765,0.307563,-0.102820,0.031136,-0.298799,-0.045123,0.199603,0.402576,0.257195,0.075674,0.465468,-0.543751,0.206553,-0.107383,-0.076342,0.229639,0.314730,-0.158888,0.195599,0.232506,-0.111763,0.039303,0.003687,-0.096367,0.083029,0.239527,0.190234,-0.044943,-0.491054,0.205177,-0.212853,0.329873,0.140452,-0.103654,-0.246799,0.725187,-0.076585,0.378030,-0.159425,0.305624,-0.299515,0.074645,0.568230,-0.297310,-0.239235,-0.408222,0.070710,-0.469648,0.320692,-0.392174,-0.499569,0.017441,0.217115,0.156603,0.047628,0.402727,-0.543815,-0.391542,-0.569171,-0.049255,0.133905,0.031795,-0.041611,-0.540450,0.199395,-0.402021,-0.347747,-0.063601,-0.171188,0.133799,0.450560,-0.424773,0.269460,0.248905,0.466652,-0.686018,0.400237,0.356876,0.560071,-0.229894,0.248591,0.733624,-0.039422,0.058605,0.026798,-0.000804,-0.131616,0.037549,-0.074082,0.051204', '1780122', '1307200', '1303333', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293293', '辣身舞', '剧情', '弗朗西丝（詹妮弗•格雷 饰）与家人到了凯勒曼山区度假。17岁的弗朗西丝对男孩子、舞蹈和家庭游戏都不感兴趣。一次偶然，她来到了一家旅馆，里面的男男女女非常缠绵地在一起跳舞。弗朗西丝马上觉得这样的舞蹈不堪入目。舞蹈教练约翰尼（帕特里克•斯威兹 饰）来到了她跟前，他为弗朗西丝解开顾虑，并教她舞蹈的基本步。学习过程中，弗朗西丝也发现自己爱上了约翰尼。因为害怕被解雇，约翰尼不敢与弗朗西丝发展下去。这时约翰尼的舞伴怀上了大学生罗比的孩子，弗朗西丝让自己的医生父亲帮忙检查，但弗朗西丝的父亲误以为孩子是约翰尼的，继而阻止女儿与约翰尼交往，他们俩只好暗中见面。因为被诬陷，约翰尼失业了。©豆瓣', '詹妮弗·格雷', '埃米利·阿朵里诺', 7.8, 6903, 'tt0092890', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2447845374.jpg', 0.4, 2.1, 28.6, 45.4, 23.5, '0.622994,-0.389884,-0.512367,0.338869,-0.291198,-0.548739,0.815056,0.124681,-0.632865,-0.411517,-0.005222,0.761113,-0.437302,0.370781,0.292815,0.072240,-0.376740,-0.665477,-0.098368,-0.061762,-0.272090,-0.357970,0.296749,-0.216093,-0.258360,-0.503243,0.216778,-0.038674,-0.136050,0.716767,0.292062,0.164300,0.250437,0.385879,0.109530,0.274484,0.186041,-0.200168,-0.146494,0.477391,0.231312,-0.004796,-0.281412,0.044051,0.257445,0.408944,0.707622,0.170951,0.245222,-0.041178,0.246532,-0.012955,0.250682,-0.120979,0.330213,-0.130801,0.338440,0.162637,-0.186075,-0.071226,0.303385,-0.049943,-0.309733,0.272607,0.203014,-0.002653,-0.395173,0.322314,-0.100990,0.120962,-0.007459,-0.368096,0.166330,0.024147,0.260093,0.183759,-0.115606,-0.083885,-0.737691,0.142884,0.667666,0.179076,0.106866,0.291666,-0.523498,-0.165736,-0.279883,-0.129711,-0.585031,0.158363,0.255480,0.024873,-0.197253,0.478237,-0.485623,-0.279032,-0.477783,0.032529,-0.189197,-0.439236,0.068004,-0.531175,-0.016437,-0.134136,-0.277784,0.039360,-0.111870,-0.355885,0.459891,-0.775251,0.084574,0.486176,0.403736,-0.200865,0.637379,0.181014,0.132053,-0.190557,-0.036037,0.531426,0.091011,-0.171126,0.238247,0.656234,0.057753,-0.159374,-0.520018,0.396341', '1309172', '1296534', '1308755', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293299', '日以作夜', '剧情', '日以作夜是一个电影技术术语，意思是指在白天拍摄夜景，本片讲的就是一个电影拍摄过程中的故事。电影《Meet Pamela》正在如火如荼的拍摄中，导演Ferrand（弗朗索瓦•特吕弗 François Truffaut饰）不仅要处理电影拍摄的事情，还要忙于照顾演员们的情绪。其中就有脆弱敏感的男主角Alphonse（让-皮埃尔•利奥德 Jean-Pierre Léaud 饰）的感情问题，还有精神受挫的女星Julie Baker（杰奎琳•比塞特 Jacqueline Bisset 饰）。电影还要赶在约定的时间之前完成，拍摄的进展也不甚顺利，一切看起来如此糟糕，《Meet Pamela》还能拍完吗……本片精彩地以“戏中戏”的结构展现了一部电影拍摄的过程。本片获1974年奥斯卡最佳外语片奖。©豆瓣', '杰奎琳·比塞特', '弗朗索瓦·特吕弗', 8.5, 11208, 'tt0070460', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2191797180.jpg', 0.2, 1, 12.1, 48.5, 38.1, '-0.218853,-0.306430,-0.407969,0.648861,0.601692,-0.132530,0.545308,0.121608,-0.124458,-0.328105,0.214420,0.284503,-0.578898,-0.150773,0.304489,-0.087037,-0.966391,-0.697069,-0.207564,0.408268,0.065569,-0.337240,-0.363266,-0.252937,-0.028060,-0.580230,0.675822,0.045051,-0.405560,0.009967,0.169716,-0.244756,-0.091776,0.054185,0.250012,-0.155336,0.046122,0.013870,-0.397280,0.500835,0.376077,-0.198057,-0.355812,0.061330,0.266406,0.553611,0.606793,0.177045,-0.357715,0.414842,0.772724,-0.170500,-0.082138,-0.142057,0.068139,-0.005119,0.486186,0.213190,-0.077558,0.463718,-0.222664,-0.650008,-1.231848,0.050923,0.346733,0.381392,-0.360823,0.364384,-0.187289,0.052625,0.044968,-0.348431,0.124354,0.203944,0.580299,0.510093,0.174630,-0.133077,-0.237011,0.726485,0.453544,0.026720,-0.270285,1.095380,0.001501,-0.515722,-0.431339,-0.196150,-0.303585,0.548035,0.212887,-0.253869,0.095180,0.170555,-0.325069,0.058701,0.059222,-0.496513,-0.182730,-0.194406,0.203993,-1.159457,-0.081338,-0.323903,-0.167826,-0.345818,0.185651,-0.481452,0.875392,-0.343262,0.109617,0.511165,-0.023188,-0.393879,0.711442,0.293573,-0.030663,-0.147589,-0.014168,-0.136777,-0.382242,-0.223359,-0.014050,0.265249,0.089774,-0.803097,-0.433131,0.538178', '26275494', '3318306', '6844861', '1468527');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293303', '与魔鬼共骑', '剧情', '美国南北战争时期，Jake Roedel（托比·马奎尔 Tobey Maguire 饰）是南方一个德国人的儿子，和他支持北方的父亲不同，他支持的是南方。他和好友Jack Bull Chiles（斯基特·乌尔里奇 Skeet Ulrich 饰）一起加入了南方的游击部队。他们又结识了George Clyde和George的之前的黑奴Daniel Holt（杰弗里·怀特 Jeffrey Wright 饰）。四人都在John Black的部队下效力。驻扎在山上的时候，村里的寡妇Sue Lee Shelley（珠儿 Jewel Kilcher 饰）和Jack Bull相爱了，在后来的战争中，Jack战死，而Jake则与部队里的一个叫Pitt（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰）的人产生了矛盾，Pitt更是开枪打伤了Jake和Holt。后来，Jake又娶了Sue，在他们去往另一个城市的路上，Jake和Holt又与Pitt相遇了......', '托比·马奎尔', '李安', 7.6, 7945, 'tt0134154', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2029607526.jpg', 0.4, 2.4, 29.5, 50.4, 17.3, '0.571866,-0.271441,-0.892514,0.976553,-0.006105,-0.448270,0.889616,0.265156,-0.376967,0.063865,0.070026,1.176772,0.142297,0.167102,0.175747,0.035350,-0.547438,-0.917909,-0.045173,-0.247358,-0.493669,-0.537407,-0.473125,-0.323442,0.025594,-0.284317,0.454101,0.111614,-0.038822,0.949399,0.264403,0.373458,-0.036642,0.642764,-0.290096,0.316499,0.247330,0.015645,-0.114136,0.234679,-0.094549,-0.266782,-0.094234,0.163776,0.228653,0.615360,0.583109,-0.265283,0.297282,-0.243806,-0.155556,-0.202114,0.111632,0.098412,0.547581,-0.340011,0.409074,0.324951,-0.232745,-0.042829,-0.068267,0.097539,-0.677112,0.110547,0.158978,0.076881,-0.997882,0.735942,-0.011039,-0.109257,0.136550,-0.281778,0.443653,0.797523,0.056949,0.350044,-0.155325,-0.296585,-0.722499,0.118342,0.820088,-0.121198,-0.084616,-0.055239,-0.126552,-0.458478,-0.172423,-0.159498,-0.518093,-0.202246,0.397940,-0.237527,-0.070429,0.194224,-0.957955,0.200912,-0.225247,-0.145216,-0.102398,-0.385292,0.043718,-0.643043,-0.011100,-0.847974,-0.392493,0.310869,0.110306,0.116669,0.818566,-0.833566,0.027034,0.470150,0.682319,-0.619100,0.914130,0.260888,0.342388,-0.142177,0.143241,-0.059360,0.012036,0.320157,0.362698,0.504746,-0.0484