INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293306', '爱丽丝城市漫游记', '剧情', '德国摄影记者菲力浦过着流浪式的生活，有一次被派到美国完成一项采访，但他并没有完成任务。途中与一个神秘的美国女子邂逅之后，无意中成了她那九岁的小女孩的监护人。菲力浦必须带着小爱丽丝穿越德国、帮她寻找奶奶的过程中，互相有了意想不到的了解，故事回避单刀直入，发展充满惊喜，主题的显现极其优雅，让观众慢慢体会美国大众文化对战后欧洲的影响。', '吕迪格·福格勒', '维姆·文德斯', 8.7, 6353, 'tt0069687', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187692526.jpg', 0.2, 0.7, 8.6, 45.1, 45.3, '0.376608,0.093600,-0.550043,0.842873,-0.293404,-0.128291,0.614413,-0.133760,-0.479025,-0.064092,0.065001,0.759759,-0.168683,0.291364,0.190100,0.069043,-0.381246,-0.452215,-0.052421,0.062711,-0.321668,-0.494028,-0.162195,-0.004255,-0.255991,-0.205206,0.520186,0.102677,-0.478689,0.598801,0.046232,0.229484,0.008456,0.735537,-0.254074,-0.073112,0.297874,0.179020,-0.234332,0.462371,0.344738,-0.201274,-0.226313,0.284809,-0.259839,0.391623,0.719632,-0.135585,-0.128712,-0.161957,0.558765,-0.270337,-0.105006,-0.014696,0.159844,0.397744,-0.050329,0.184976,-0.002885,-0.323945,-0.106008,-0.170359,-0.695770,0.052775,0.149513,0.220157,-0.551518,0.413577,0.032131,0.016530,0.236632,-0.220014,0.178100,0.633636,0.524572,0.055927,-0.129623,0.086011,-0.519787,0.455373,0.609552,-0.164698,-0.424172,0.433601,-0.361607,-0.619770,0.436322,-0.409744,-0.207834,0.228839,0.065461,-0.032959,-0.426793,0.206555,-0.482431,0.068201,-0.390090,-0.547981,-0.049378,-0.640876,-0.075788,-0.883078,-0.284221,-0.533990,-0.418683,0.030459,0.019856,-0.182764,0.847625,-0.799354,0.409684,0.956760,0.436910,-0.403207,0.881192,0.020163,0.075954,-0.584198,-0.000320,0.196188,-0.262794,0.133187,0.025949,0.488859,-0.060939,-0.055548,-0.522207,0.498810', '3811356', '26259202', '2053515', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293310', '椿三十郎', '剧情', '郊外神社的神殿里，九位年轻武士在秘密开会，城代家老的外甥井坂（加山雄三饰）准备向大目付菊井求助整治内部问题。但外貌邋遢的武士椿三十郎（三船敏郎饰）出现，告诉他们菊井才是背后的黑手。果然，神殿很快被大目付手下团团围住，三十郎出手替年轻人解危，而室户半兵卫（仲代达矢饰）却欣赏三十郎的身手，欢迎他加入。之后，三十郎与九人组去找城代家老，却发现晚了一步已被绑架。他们到了武士寺田家中再谋营救，隔壁就是敌人所在的黑藤府。菊井一边监禁了城代家老，另一边又想着引出年轻武士们出洞，幸得三十郎所救。在精妙计谋下，解救成功。但室户半兵卫却不放过三十郎，较量的胜负就在一瞬间。©豆瓣', '三船敏郎', '黑泽明', 8.8, 27759, 'tt0056443', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2346574759.jpg', 0.3, 0.4, 7.1, 42.4, 49.9, '0.126796,-0.159874,-0.239876,0.105976,-0.177591,-0.311458,0.358573,-0.070936,-0.167011,-0.412209,0.409730,0.406070,0.087421,0.506652,0.284700,-0.272938,0.084035,-0.499227,-0.265946,-0.210889,-0.231863,-0.216259,-0.061852,-0.041232,-0.100497,-0.222065,0.249902,0.203057,-0.145392,0.327528,0.528237,0.302204,-0.169043,0.237760,-0.153570,-0.004134,0.225973,-0.246757,0.118375,0.292581,-0.554593,-0.409207,-0.344771,-0.116890,0.203965,0.702057,0.570670,-0.116672,-0.216285,0.125350,0.171665,0.063643,-0.156865,0.300777,0.818526,0.034780,0.047937,0.111274,0.012428,-0.316091,-0.311528,0.001560,-0.395216,0.294438,0.316424,-0.007642,-0.615626,0.140447,0.045925,0.034705,0.046815,-0.016258,0.026282,0.056922,0.122798,0.051502,-0.146006,-0.078435,-0.458068,-0.012545,0.492791,0.034220,-0.066022,-0.300856,0.323218,-0.465260,0.136418,-0.320308,0.105385,-0.069092,0.311719,-0.018040,0.222435,0.023121,-0.346998,0.117568,-0.419621,0.141420,-0.008531,-0.220879,0.017075,-0.408305,-0.034005,-0.047768,-0.328842,0.645576,0.297457,-0.041992,0.466785,-0.187694,0.047999,0.420195,0.382287,-0.244260,0.741240,-0.016563,-0.033928,-0.148719,-0.086802,-0.329370,0.260312,0.402725,0.239479,0.554320,-0.308714,-0.466702,-0.653241,0.025294', '25876760', '1815487', '1291564', '5386987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293315', '阿郎的故事', '剧情', '阿郎（周润发 饰）年轻时作为出色的赛车手很是放荡不羁，却不妨碍富家女波波（张艾嘉 饰）对其一往情深。波波不顾家人反对，同他结婚并怀下身孕后，发现阿郎背着她还有其它女人，于是愤然离去。波波临盆之际，阿郎参加非法赛车撞死警察入狱。波波被母亲和医生欺骗婴儿夭折，后去了美国生活。出狱后，阿郎为以前行为愧疚，从孤儿院找回儿子取名“波仔”（黄坤玄 饰）。父子二人开始相依为命过日子。十年后，已有未婚夫的波波回港又遇阿郎，得知波仔是自己的儿子后，想将其带去美国。内心仍深爱波波的阿郎为了证明自己已有彻底改变，决定不顾年纪和身体状况再战赛场。©豆瓣', '周润发', '杜琪峰', 8.6, 108988, 'tt0098694', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p763776246.jpg', 0.2, 0.7, 12.1, 45.3, 41.8, '-0.023823,-0.014040,-0.568361,0.232622,-0.353471,-0.245713,0.801385,0.073583,-0.732517,-0.288331,-0.075659,0.558875,0.067918,0.296856,-0.111375,0.143231,-0.286348,-0.709666,0.112853,0.099866,-0.045739,-0.205910,0.337286,0.025858,-0.257260,-0.182328,0.616802,-0.270377,0.024468,0.634281,0.205219,0.458604,-0.103960,0.408324,-0.366193,0.253540,-0.232818,0.173102,-0.498194,0.141128,0.557269,-0.041386,-0.012295,0.100151,-0.076599,0.352147,0.559864,0.173417,-0.088086,-0.422961,0.498968,0.121540,0.030908,0.286317,0.351874,0.097657,0.253836,0.200629,-0.033220,-0.047964,0.041857,0.084930,-0.017462,0.274989,0.252470,-0.236352,-0.808301,0.237034,-0.230479,-0.170650,0.364283,-0.088394,0.004066,0.368893,-0.138492,0.316713,-0.210103,0.182066,-0.309731,0.186707,0.690971,-0.152901,0.168180,0.245233,0.161845,-0.230501,0.575754,-0.222938,-0.271353,0.184685,-0.121466,0.292399,-0.206725,0.173092,-0.216382,0.091026,-0.462675,0.081002,0.207624,-0.455407,-0.027562,-0.344949,-0.142074,-0.246303,-0.293478,-0.002500,0.121032,-0.470789,0.443010,-0.725020,0.213867,0.210626,0.465037,-0.867448,0.595102,0.123662,0.093288,-0.429867,0.333922,0.355960,-0.150797,-0.083023,0.023837,-0.116582,0.067921,0.096421,0.030182,0.368600', '1304091', '1293265', '1301022', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293316', '星际旅行2：可汗怒吼', '动作', '邪恶的可汗逃脱十五年前被寇克船长拘禁的星球，他本人是一位智勇双全的领袖，但此刻已变成一个邪恶的狂人，他誓言要向寇克船长讨回血仇。于是他先劫持了一艘联邦战舰，后又偷取了寇克船长的儿子和旧情人制造的毁灭性武器。并引诱企业号投入他精心设计的圈套……', '威廉·夏特纳', '尼古拉斯·迈耶', 7.7, 13022, 'tt0084726', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453475066.jpg', 0.4, 2.4, 28.2, 47.5, 21.5, '-0.195006,0.188152,-0.447750,0.826807,-0.146728,-0.210843,0.982114,0.049121,-0.333467,0.216487,0.423020,0.807490,0.387279,0.009036,0.471800,0.615263,-0.389809,-0.461072,-0.259332,-0.228061,-0.294491,-0.497804,-0.344237,-0.442840,0.121962,-0.415521,0.963987,-0.065021,-0.288113,0.032506,0.339796,0.363622,0.223466,0.757554,-0.066450,-0.097555,0.042878,-0.330782,0.078822,0.269075,-0.250398,-0.250427,0.080036,0.270568,-0.439586,0.570121,0.646925,-0.397431,0.041965,-0.589476,0.064524,-0.409231,0.144511,-0.070148,0.396614,0.010742,-0.353836,0.387340,0.081312,-0.372996,0.272855,-0.035411,-0.906517,-0.204225,-0.122227,-0.285490,-0.526026,0.427919,-0.233978,0.467283,-0.130389,-0.016282,0.142264,0.246877,0.271304,0.089719,-0.212029,0.079049,-0.622622,0.318380,0.389550,-0.270589,-0.254503,0.217695,-0.003199,-0.599455,-0.115955,-0.610270,-0.594129,-0.037375,0.578974,-0.118012,-0.089194,0.405741,-0.763430,-0.089193,-0.629701,0.087462,-0.083837,-0.573524,0.053211,-0.347574,-0.083271,0.059749,-0.182902,0.275456,0.144834,0.031276,0.706378,-0.461528,-0.011499,0.852718,0.186828,-0.589103,0.537604,0.047527,0.017998,-0.348113,0.036815,0.184567,0.215784,0.594326,0.240553,0.308101,0.358248,-0.021386,-0.121463,0.317415', '10581884', '2028634', '24879819', '25731059');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293317', '断箭', '动作', '飞行员迪克斯（约翰•特拉沃塔 John Travolta 饰）和希尔上教（克里斯汀•史莱特 Christian Slater 饰）搭档多年，虽然表现出色，但一直没有获得晋升。心中不服气的迪克斯决定用自己的手段向政府讨回他应得的一切。于是，在一次飞行任务中，迪克斯为了劫持隐形飞机上的两枚核弹，将希尔打出了机舱，幸亏希尔携带有降落伞，才幸免于难。迪克斯取得核弹后，向政府要挟巨额赎金，不然就将在城市中引爆核弹。另一方面，希尔和美丽女警泰丽（萨曼莎•玛西丝 Samantha Mathis 饰）正在极力追寻迪克斯，抢回核弹！©豆瓣', '克里斯蒂安·史莱特', '吴宇森', 7.3, 44109, 'tt0115759', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2372798569.jpg', 0.4, 3.2, 38.9, 45.3, 12.2, '0.032674,0.235250,-0.594498,0.748636,-0.207388,-0.206850,0.444733,-0.263021,-0.370878,0.063678,0.288192,0.775071,-0.055093,-0.083648,0.223264,0.309194,-0.646719,-0.415261,0.144091,-0.172670,-0.520575,-0.879382,-0.600042,-0.209899,-0.236759,-0.502719,0.617523,-0.338559,-0.012812,0.127771,0.300110,0.611406,0.151405,0.201842,0.316385,-0.104004,0.103476,-0.202467,-0.273753,0.480817,0.049662,-0.262349,-0.042290,0.341370,0.443450,0.277343,0.480176,-0.280833,0.339651,-0.104216,-0.089071,-0.268561,0.272610,0.235565,-0.123609,-0.040457,-0.135947,0.084966,-0.474835,0.069861,0.383532,-0.031846,-0.669920,-0.104826,-0.062562,0.013033,-0.541843,0.080521,-0.664305,0.029041,0.173343,-0.339464,-0.055852,0.459647,0.336865,0.233230,-0.550242,-0.046464,-0.517508,-0.104085,0.228966,-0.032623,-0.207772,0.075718,-0.058392,-0.182252,-0.071376,-0.061573,-0.358736,-0.197709,0.571669,0.030130,0.334393,0.334938,-0.449531,-0.147023,-0.725093,-0.492139,0.271453,-0.231854,-0.174723,-0.686942,0.349903,-0.155619,-0.489003,0.164465,0.231892,-0.360717,0.582602,-0.572345,0.088469,0.526995,0.353438,0.123837,0.242083,-0.360265,0.205269,-0.331276,0.056069,-0.019608,0.288712,0.399535,0.370030,-0.082970,0.136464,-0.255725,0.028266,0.524404', '26268602', '1550450', '1307442', '1296720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293318', '萤火虫之墓', '剧情', '美日战争爆发，14岁的清太带着年幼的妹妹到处逃命，当他们到达防空洞的时候，母亲已身受重伤，没过多久便不久人世。两兄妹自此过着相依为命的日子。他们只好投靠了母亲的姐妹，纵使他们把家里所有的家当都送给了阿姨，但当食物吃完，他们就越感到了寄人篱下的感觉，清太决定带着妹妹离开独自生活。火灾硝烟中的生活并不好过，清太为了妹妹四处偷取食物，但妹妹还是严重营养不良……©豆瓣', '辰己努', '高畑勋', 8.7, 386297, 'tt0095327', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2237136718.jpg', 1.7, 1.7, 10, 32.7, 53.9, '0.088454,-0.315681,-0.607854,0.256889,-0.103937,-0.608962,0.491548,0.174537,-0.658449,-0.361233,0.042899,0.809285,0.072873,0.660810,0.025049,-0.041923,-0.360708,-0.361493,-0.197499,-0.208269,-0.165082,-0.086229,0.159089,-0.064274,-0.216706,-0.297216,0.455114,0.169184,0.156994,0.462112,0.025547,-0.237607,-0.297481,0.671798,-0.244456,0.255346,-0.451935,0.093927,-0.696388,0.048881,0.264034,-0.118141,-0.074028,0.203801,0.356990,0.218353,0.837556,-0.251273,-0.127120,-0.347735,0.090980,-0.267167,-0.014135,0.225353,0.388932,0.167859,0.485753,0.075897,-0.190727,0.050433,-0.209776,-0.087767,-0.273887,0.153441,0.122745,-0.265601,-0.713931,0.377681,0.082118,0.022747,0.104849,-0.351724,0.534378,0.366751,-0.138959,0.577881,-0.651110,-0.013500,-0.800551,0.171458,0.969693,-0.440957,0.158545,0.256396,-0.088309,-0.191959,0.215946,-0.522311,-0.625173,0.086142,0.017665,0.294647,-0.432954,0.357281,-0.439091,0.161842,-0.189563,-0.355547,0.248019,-0.251482,0.156027,-0.176732,0.050013,-0.375043,-0.524014,0.215119,0.002553,-0.007411,0.715748,-0.461452,0.432251,0.396745,0.674785,-0.552468,0.305997,0.172746,0.374874,0.029796,-0.088808,0.379018,-0.218803,0.208877,0.583895,0.110976,-0.112446,-0.076417,-0.293543,0.373860', '25721544', '1306505', '1300202', '1296978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293320', '金玉盟', '剧情', 'Nickie Ferrante（加里·格兰特 Cary Grant 饰）是一个游手好闲的有钱人，在一艘游轮上邂逅了Terry McKay （黛博拉·蔻儿 Deborah Kerr饰）。两人相谈甚欢，Nickie更是船临时靠岸的时候带着Terry去了一个乡镇上看望了他的奶奶，Terry发现了Nickie在油画上的天赋。两人间情愫暗生。船到了终点站纽约，两人要分开了，约定半年后在纽约帝国大厦顶层重聚。半年后，Nickie独自一人在帝国大厦从白天等到天黑，未见Terry的踪影，失望而去。而另一边，Terry却在赶来的路上发生了车祸而无法到达。不能走路的Terry不愿再去寻找Nickie，却偶然在半年后的一场舞会上又见到了Nickie，此时的Nickie已经是小有名气的画家。Nickie费尽心思终于找到了Terry的住所，准备再次追求Terry的芳心。到底这段波澜不断的爱情结果会如何？', '加里·格兰特', '莱奥·麦卡雷', 8.2, 9739, 'tt0050105', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p848574092.jpg', 0.2, 1.5, 17.9, 47.1, 33.2, '0.285610,0.172977,-0.995828,0.396267,0.085362,-0.764083,0.835433,0.149093,-0.658520,0.010249,0.137835,0.821580,-0.356700,0.446464,0.311404,0.081772,-0.496504,-0.556112,0.106989,-0.684947,-0.629460,-0.381861,-0.221085,0.011517,0.193107,-0.248560,0.374120,0.262434,0.161955,0.785564,0.347831,-0.199502,-0.152019,0.737698,-0.437330,-0.063879,0.064389,0.328481,-0.041176,0.406766,0.031607,-0.663838,-0.275884,0.012267,0.123708,0.361009,0.895570,0.010440,-0.008864,0.126550,0.218336,-0.154258,0.084479,0.067706,0.458288,-0.224673,0.013913,0.063201,-0.529100,-0.211751,-0.109688,-0.016207,-0.409044,0.127173,-0.169169,0.263797,-1.039204,0.677478,0.028559,-0.282268,-0.038154,-0.619511,0.413353,0.601735,-0.159958,0.326160,-0.178762,-0.174738,-0.722429,0.190470,0.875135,0.109224,0.096690,0.655509,0.172816,-0.401466,-0.205357,-0.189937,-0.319696,-0.248745,0.457639,0.115916,-0.417003,-0.147693,-0.653696,0.023308,-0.402874,-0.270993,-0.160952,-0.351620,-0.022659,-0.754348,0.007494,-0.574668,-0.268394,0.451851,0.006375,-0.032221,0.456513,-0.902325,0.416696,0.794956,0.159117,-0.381847,0.922539,0.046091,0.123990,-0.002531,0.260354,0.041780,-0.294552,0.717138,0.167973,0.629216,-0.083666,-0.118639,-0.747121,0.486248', '25837175',