INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293323', '大红灯笼高高挂', '剧情', '大学刚读半年的颂莲（巩俐）被贪钱的母亲逼迫着嫁进陈家大院，成了老爷的第四房姨太。陈府有老规矩，姨太太们傍晚时分要站在自已的屋子前，等待下人送来的意味被老爷“临幸”的大红灯笼。起初因为“新人”身份，颂莲得到老爷最多宠幸，但也因此被其它三位姨太太尤其笑里藏刀的二姨太（曹翠芬）挤兑得叫苦不迭。因为涉世不深，生性反叛好强的颂莲急欲争一口气，使计又成老爷身边红人，不想计被看穿，终败于二姨太手下酿成悲剧。而三姨太（何赛飞）的经历虽与颂莲迥异，却也殊途同归逃不出宿命。©豆瓣', '巩俐', '张艺谋', 8.7, 240064, 'tt0101640', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1254404823.jpg', 0.1, 0.5, 8.8, 45.4, 45.2, '0.296599,0.028632,-0.604283,0.445312,-0.175552,-0.447175,0.871601,0.270617,-0.665650,-0.324290,0.362274,0.640561,-0.455487,0.387491,0.016727,-0.041639,0.175944,-0.304209,-0.363893,-0.138646,0.131891,-0.324817,0.363235,-0.004245,0.041477,0.039903,0.089236,0.192513,0.068388,0.091087,0.482935,0.145369,0.118735,0.159089,-0.052069,0.393855,-0.300769,-0.186970,-0.174012,0.007253,0.153667,-0.099773,-0.314908,-0.176808,0.168836,0.233592,0.445540,-0.298320,0.031700,-0.264303,0.339107,-0.293383,-0.145610,0.439353,0.605299,-0.057345,0.362590,0.327019,0.021206,-0.165978,0.065133,0.053312,-0.640953,0.649427,0.468893,-0.143255,-0.521019,0.200550,-0.135737,-0.241404,-0.306492,-0.283304,0.294299,0.161569,0.028136,0.063786,-0.443767,-0.042459,-0.710666,0.056167,0.575562,-0.039029,0.019161,0.144237,0.204373,-0.218449,0.378186,-0.924873,-0.441414,0.178440,0.220312,0.066208,-0.103331,0.326665,-0.217023,-0.120615,-0.253143,-0.105977,0.152577,-0.511022,-0.227225,-0.158102,-0.211906,-0.295697,-0.234255,0.370270,0.504248,-0.077240,0.484309,-0.547694,0.334237,-0.095490,0.380818,-0.731951,0.652726,0.125311,0.226137,0.195841,-0.226638,-0.321442,-0.127862,0.284020,0.336016,0.362420,-0.642736,-0.401316,-0.348326,0.092897', '1877596', '2137060', '25767747', '26961821');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293325', '星际旅行4：抢救未来', '喜剧', '一艘巨大的外星无人探测器向地球航来，它不断地发出奇特的电波信号：功率强大的信号煮沸了海水，干扰了附近的星舰并造成了广泛的破坏。此时，詹姆斯·柯克中将与他的船员们在完成了让斯波克上校复活的任务后，驾驶着从克林贡人那抢来的猛禽舰（被改名为“赏金号”）从瓦肯星返航，尽管他们已经知道了将面临军事法庭的指控：他们被指控盗窃了联邦星舰进取号，并对她的毁坏负有责任。在此关头，尚在恢复中的斯波克发现这艘外星探测器正尝试与地球上的座头鲸建立联系；但不幸的是，早在3个世纪前座头鲸就因过度的捕猎而灭绝了。柯克命令“赏金号”进入引力弹射状态，利用太阳的万有引力而穿越时空来到20世纪后期。星舰于1986年抵达了美国加利福尼亚州的旧金山市，船员们将星舰藏在金门公园的一处草坪上。此后，他们开始寻找能与外星探测器沟通的鲸鱼、能将鲸鱼装在星舰上的容器，以及能让猛禽舰恢复能源供应的物质——在星舰穿越时空的旅途中能源几乎被耗尽。柯克与斯波克最终获得了一位鲸类专家吉莉安·泰勒博士的协助，她在索萨利托市鲸鱼协会照料两头座头鲸。在经历了许多的困难后——包括让泰勒相信他们的确来自未来——进取号的船员们成功地营救了两头座头鲸，并将它们带到未来，及时地拯救了地球。然后船员们被带到了联邦委员会的面前，接受众多的指控。没有被作为被告的斯波克也与其他船员们站在了一起。最后，鉴于他们新近的英勇表现，除了对柯克中将的控告外，针对其余被告的所有控告都被撤销。柯克以作为一名上级军官却违背命令的罪行被判有罪，并象征性地被降职为上校以示惩戒；但作为对他英勇行为的表彰，他被任命为联邦星舰进取号-A的舰长。与进取号船员一同来到23世纪的泰勒博士，决', '威廉·夏特纳', '伦纳德·尼莫伊', 8.2, 10474, 'tt0092007', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209381378.jpg', 0.4, 1.4, 17.5, 47.9, 32.7, '0.333290,0.235295,-0.709303,0.654621,-0.141848,-0.072585,0.696440,0.065338,-0.381334,0.077065,0.164142,0.822479,0.066113,0.100794,0.225683,-0.034949,-0.386595,-0.546593,-0.259468,-0.137759,-0.581866,-0.549936,-0.100848,-0.202833,-0.138320,-0.480721,0.765403,0.056553,-0.219627,0.406006,0.070486,0.339996,0.127533,0.534570,-0.339710,-0.131179,0.099213,-0.314598,0.055529,0.245236,-0.215470,-0.254056,0.231868,0.162185,0.042105,0.351718,0.891110,-0.575545,-0.052289,-0.219309,0.092719,-0.374940,0.315505,0.179628,0.484798,0.223663,-0.371250,0.256314,-0.177305,0.188114,0.195852,0.085477,-0.912795,-0.290954,-0.229381,-0.023810,-0.479731,0.267600,-0.185647,0.058385,-0.099466,-0.069155,0.255559,0.398217,-0.104218,0.404053,-0.295544,0.190871,-0.500281,-0.014159,0.513132,-0.019610,-0.445715,0.039783,-0.108842,-0.721424,-0.181993,-0.340560,-0.154200,-0.262053,0.468793,0.225025,-0.170050,0.295698,-0.812403,0.179396,-0.494899,-0.607153,-0.221683,-0.303761,-0.149211,-0.957491,0.172433,-0.284777,-0.168037,0.317133,0.124119,-0.135789,0.735732,-0.738496,0.258643,0.587207,0.371320,-0.418961,0.745137,0.119039,0.209639,-0.143693,0.043895,0.071961,0.240974,0.769573,0.239674,0.297147,0.085363,-0.123546,-0.386203,0.266455', '1294917', '25774050', '2159244', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293330', 'X档案：征服未来', '科幻', '五年的追逐化为泡影，随着X档案的关闭，福克斯·穆德（大卫·杜楚尼 David Duchovny 饰）和丹娜·斯科莉（吉莲·安德森 Gillian Anderson 饰）被迫调任处理一些平常的案件。某天，美国得州达拉斯市发生一起爆炸案。虽然穆德和斯科莉极力疏散写字楼内的人群，但爆炸还是夺取了4名无辜者的性命，他们也因此受到上级的指摘。然而事后不久，穆德便得知4名牺牲者早在爆炸之前便已死亡，所谓爆炸案不过是某个神秘部门为了掩盖证据而实施的骗局。该部门据说多年来一直从事外星人的研究，并且他们的研究足以导致人类的毁灭。两名搭档决定彻查此事，但是神秘且难以抗拒的力量无时无刻不在阻挠他们追寻真相的脚步……本片为同名美剧的第一部剧场版。©豆瓣', '大卫·杜楚尼', '罗伯·鲍曼', 6.9, 8067, 'tt0120902', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2196902962.jpg', 0.9, 6.8, 48.7, 32.3, 11.3, '0.331738,0.012138,-0.701102,0.386382,-0.048827,-0.116757,0.501689,-0.021744,-0.418644,-0.623382,0.182671,0.516177,-0.094025,-0.126207,0.103008,-0.098426,-0.397561,-0.705642,0.080734,-0.261240,-0.210267,-0.442057,-0.322630,-0.394638,-0.126773,-0.204530,0.727006,0.430419,-0.147926,0.143395,0.340081,0.474565,-0.347328,0.368693,0.093707,-0.210857,0.125099,-0.159460,-0.415180,0.163665,0.069672,-0.489917,-0.188373,0.158459,0.017935,0.467674,0.386057,-0.158725,-0.214297,-0.084516,0.435738,-0.544918,0.018145,0.149202,0.472338,0.294442,0.132226,0.581530,-0.366633,-0.040217,0.054405,-0.029871,-0.793094,-0.042954,0.168536,0.255569,-0.317739,0.116263,-0.103205,0.093467,-0.119269,-0.195676,0.214391,0.505190,0.284354,0.174476,-0.205231,0.004039,-0.433677,0.080135,0.676374,-0.126907,-0.390273,0.043588,0.032433,-0.486710,-0.323520,-0.248097,-0.351825,0.123523,0.158611,0.285542,-0.150548,0.448808,-0.433310,-0.185030,-0.423650,-0.279842,-0.167574,-0.240058,0.016913,-0.815094,-0.295093,-0.226364,-0.167994,-0.057698,0.261817,-0.126815,0.385186,-0.570501,0.337979,0.516263,0.120478,-0.772482,0.318017,0.138653,0.195371,-0.128009,-0.039653,0.159518,0.124624,0.301259,-0.090909,0.053853,0.198293,-0.425891,-0.284319,0.292008', '2369613', '4193254', '5157137', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293341', '母女情深', '剧情', '女儿艾玛（德博拉•温格 Debra Winger 饰）是妈妈奥罗拉（雪莉•麦克雷恩 Shirley MacLaine 饰）的心肝宝贝，自小开始，奥罗拉就帮艾玛安排好一切，艾玛的言谈举止、修饰打扮、学习、玩耍、交朋友等等都必须经过奥罗拉同意。在丈夫早逝后，奥罗拉操持起家里的一切，对艾玛更加“专制”。艾玛虽然表明很温柔、软弱，但是内心却十分倔强。两母女也因此多次吵架。奥罗拉一直没再接受其他男人的追求，艾玛也在和母亲相依相偎、磕磕绊绊中长大。长大后的艾玛开始极力摆脱母亲的“专制”：她不顾母亲的反对，嫁给了一个工作不稳定的研究生……她花了三十年去摆脱母亲的“专制”，到头来却发现自己对母亲的始终不忘的依依亲情。©豆瓣', '雪莉·麦克雷恩', '詹姆斯·L·布鲁克斯', 8, 7512, 'tt0086425', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2257329470.jpg', 0.5, 2, 22, 48.4, 27.1, '0.380561,-0.102461,-0.770145,0.514169,-0.229558,-0.687373,0.534361,0.000868,-0.337383,-0.567189,-0.120585,0.396992,-0.158713,0.166202,0.094080,0.278195,-0.591641,-0.430051,0.106620,0.108980,-0.050118,-0.609067,0.124132,-0.080047,-0.359686,-0.173705,0.451797,-0.291394,-0.104373,0.290706,0.178721,0.133308,0.332547,0.461550,0.023503,0.276887,-0.010655,-0.127630,-0.129821,0.009683,0.613654,0.218488,-0.059129,0.446284,0.354920,0.366716,0.583677,-0.465560,0.160040,0.017956,0.351434,0.065193,0.020168,0.225256,0.110461,-0.281957,0.087385,0.300775,-0.175851,-0.049536,0.085074,-0.122812,-0.233682,0.024624,0.330113,0.118468,-0.834893,0.412869,-0.051714,0.167947,0.028027,-0.483591,-0.056960,0.431898,0.042949,0.658880,-0.231153,0.163674,-0.466417,-0.013356,0.673489,0.097908,0.050329,0.391363,-0.574967,-0.415579,0.080898,-0.278022,-0.699209,-0.153138,-0.166771,-0.105048,-0.111772,0.681228,-0.415237,-0.089655,-0.267520,0.033890,0.075465,-0.701661,0.238612,-0.351400,-0.184346,-0.480792,-0.384017,0.195169,-0.340608,-0.417922,0.674749,-0.939657,0.399652,0.248963,0.544811,-0.573993,0.528030,0.451853,0.277808,-0.388105,0.064170,0.644483,0.124770,-0.402805,0.277185,0.257881,0.242122,0.129083,-0.181919,0.535420', '1299965', '1308047', '1301221', '1306861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293345', '007之女王密使', '动作', '这次，阴谋家贝洛福（特利•萨瓦拉斯Telly Savalas 饰）在瑞士山区建立一个疗养院，表面上这是一个普通的高级疗养院，风景秀丽、服务一流，但实际上却是贝洛福进行的一项旨在控制全球的计划的重要基地。在这个疗养院里，贝洛福开发出一种新型病毒，他企图将病毒注射到来这里疗养的女患者身上，然后通过她们传播到世界各地，达到掌握世界主权的目的。贝洛福的阴谋行动引起了英国情报部门的注意，于是007邦德（乔治•拉扎贝 George Lazenby 饰）奉命出动。邦德乔装打扮成家谱学的专家混进了这座疗养院，他必须及时查处贝洛福的阴谋，并阻止他！©豆瓣', '乔治·拉扎贝', '彼特·R·亨特', 6.7, 8797, 'tt0064757', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p737007688.jpg', 1.8, 8.6, 50.6, 28.9, 10.2, '0.443225,0.464358,-0.690695,0.522503,-0.133754,0.180201,0.486666,-0.169866,-0.418732,-0.253830,0.143224,0.423455,0.038955,-0.091973,0.152808,0.171139,-0.424137,-0.347472,-0.000112,-0.252662,-0.262223,-0.442983,-0.740507,-0.344852,-0.030211,-0.338111,0.330516,0.242552,-0.443055,0.218976,0.084151,0.493830,0.054808,0.241092,0.143133,-0.457596,0.239073,-0.557987,-0.203106,0.577149,0.013344,-0.069533,0.090475,0.261713,0.252095,0.522798,0.507051,-0.106084,-0.115837,-0.258066,0.449031,-0.390976,0.010378,0.023692,0.388978,-0.047963,-0.193056,0.279722,-0.206972,0.069687,0.052523,-0.260000,-1.009721,-0.354879,0.267369,0.091295,-0.283863,0.044721,-0.149692,-0.046775,-0.345034,-0.341149,0.280183,0.494820,0.128907,0.163779,-0.068798,0.290063,-0.817851,0.050491,0.429378,-0.383027,-0.301818,-0.089278,-0.402644,-0.585121,0.002823,-0.358635,0.068886,-0.149336,0.124819,-0.125551,-0.121647,-0.153026,-0.478863,-0.014930,-0.299767,-0.393090,-0.035784,-0.148220,0.164022,-1.020902,-0.083136,-0.085834,-0.225917,-0.164069,0.073704,-0.214182,0.494093,-0.562729,-0.004135,0.739308,0.191386,-0.485511,0.354227,-0.141565,0.351462,-0.299162,-0.349221,0.343989,0.255001,0.644062,-0.178162,0.511945,0.228314,-0.426033,-0.433504,0.326596', '4014397', '1293433', '2369613', '1298574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293346', '四个房间', '喜剧', '在一家古旧的旅馆内，员工们都去欢度新年假期，只有一个小侍应生（Tim Roth 蒂姆•罗素 饰）留守。当夜，光怪陆离的事件轮番上演：1，	一群女巫准备在当晚复活他们的女神，而她们却弄丢了至关重要的精液，小侍应生临时客串，勇敢献身……2，	善妒的丈夫怀疑妻子与他人有染，遂将妻子绑在椅子上，倒霉的侍应生则被当作奸夫，手枪抵头，命悬一线……3，	富翁夫妻参加新年宴会，将子女留在房间中。两个淘气的小家伙展开了一场大战，却看到了恐怖的一幕……4，	几名好莱坞演员凑在房间中玩打火机游戏，每人打十下，十下连续打着就会赢得一部跑车，反之有一下不着便要切掉一根手指。侍应生被临时找来充当刽子手……©豆瓣', '安东尼奥·班德拉斯', '阿利森·安德斯', 7.1, 13572, 'tt0113101', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p948748740.jpg', 1.5, 6.6, 39.4, 38.1, 14.4, '0.245399,0.126887,-0.401278,0.251454,-0.277801,-0.150351,0.786505,0.229550,-0.106692,0.031508,0.591782,0.701251,-0.410936,0.289579,0.339147,-0.216785,-0.243664,-0.799770,-0.283575,-0.065547,-0.475806,-0.104422,-0.051676,-0.262833,0.102425,-0.010904,0.193559,-0.361231,-0.012351,0.304986,0.543940,-0.199631,-0.394324,0.227042,-0.323474,0.044592,0.127524,-0.137985,-0.180191,0.291267,-0.274635,-0.287770,-0.135109,-0.171092,0.072904,0.170088,0.916241,-0.202302,0.110957,-0.157359,0.237778,-0.134461,-0.180482,0.109974,0.357454,0.229261,0.264211,-0.026178,-0.178626,0.097183,0.417079,-0.306240,-0.568510,0.324189,-0.145592,0.073571,-0.614935,0.557159,-0.030490,0.053636,0.208598,-0.190541,0.305169,0.115945,0.150690,0.331287,0.084756,0.037666,-0.347882,0.405171,0.504788,-0.071753,0.155522,0.226777,0.079080,-0.113890,0.202517,-0.058448,-0.435958,-0.221311,0.544637,-0.224357,0.084365,-0.061011,-0.602148,-0.034984,-0.315697,-0.330633,0.325382,-0.227886,-0.138855,-0.777041,0.110057,0.120675,-0.267735,0.327016,0.320686,0.070321,0.603297,-0.399018,0.217085,0.572195,0.134991,-0.259648,0.720635,0.045958,0.317208,-0.030451,0.000230,-0.190509,0.197279,0.450338,0.380326,0.365946,-0.555715,-0.076039,-0.467771,0.184829', '10466639', '21619567', '1309194', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293350', '两杆大烟枪', '剧情', '艾迪（尼克·莫伦）思维敏捷，是个玩牌高手。在三个好友的支持下，艾迪携巨资参加了黑社会的高额赌局，不想落入圈套，欠下50万的赌债。为了还清赌债，艾迪和朋友们绞尽脑汁，最终算计到一群毒贩身上，并为打劫购买了两杆老式烟枪。不想这群不安分的毒贩，正惦念着他们毒品供应商的钱，并在同一天实施了打劫。在毒贩们费尽周折，把毒品供应商熨的整整齐齐的钱款拿到手后，艾迪他们幸运的坐享其成。可是他们不知道，这看似简单的抢劫案背后，更有厉害的角色参与其中。他们手里的两杆破烟枪也隐藏着不少故事。在无知与莽撞中置身漩涡的他们能侥幸脱身么？笑料迭出的偶发事件里，穿插着小人物与大人物的辛酸幽默。©豆瓣', '杰森·弗莱明', '盖·里奇', 9.1, 560153, 'tt0120735', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792443418.jpg', 0.2, 0.5, 5.9, 29.7, 63.7, '0.513061,-0.107623,-0.546134,0.216869,-0.347827,-0.226659,0.890682,-0.100379,-0.453341,-0.145787,0.300454,0.481380,0.067269,-0.044069,0.007460,-0.311145,-0.252102,-0.556246,-0.122052,-0.070790,-0.204022,-0.504747,-0.534332,-0.176911,-0.371253,-0.011177,0.351861,0.276190,0.036199,0.398036,0.460988,0.142152,-0.273758,0.134596,-0.462762,-0.073559,0.113906,0.081980,-0.145424,0.286426,-0.162118,-0.163411,-0.251222,0.109702,0.310489,0.444393,0.523409,-0.203588,0.137373,0.139874,0.094870,-0.271951,-0.168703,0.013943,0.161766,0.086331,0.429822,0.059447,-0.282834,0.111975,0.315933,-0.121021,-1.043899,-0.139887,-0.108553,0.164345,-0.794962,0.202075,-0.046982,0.079318,-0.148384,-0.167526,-0.004735,0.275874,0.328626,0.151216,-0.188262,-0.108225,-0.765585,0.174659,0.652961,-0.154848,-0.010876,0.151357,-0.243281,-0.268587,-0.042036,-0.445815,-0.276934,-0.175462,0.608971,-0.226069,-0.064182,0.184230,-0.554209,0.179815,0.024289,-0.069811,-0.070853,-0.431335,-0.235620,-0.389003,-0.252482,-0.149660,-0.335145,0.242325,0.249495,-0.236453,0.635231,-0.576256,-0.026079,0.817163,0.215886,-0.438474,0.581467,0.210111,0.061592,0.027257,-0.490714,-0.317873,0.445308,0.180532,0.374518,0.361651,-0.095021,-0.436636,-0.047408,0.201471', '1793491', '1299932', '3785918', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293351', '食神', '喜剧', '史提芬周（周星驰 饰）在饮食界是享誉盛名的食神，但一直骄傲自大，惟利是图。被身边得力助手陷害，一夜间一无所有。他在庙街认识了早已对他倾心的大姐大火鸡（莫文蔚 饰）及一众老大，靠着史提芬周的商业头脑，他们决定推出“爆浆癞尿牛丸”，史提芬周重出江湖的道路也越来越顺利。为了重新夺得食神的位置，他回到大陆寻找“中国厨艺学院”受训。火鸡一路跟着他想对他表白，史提芬被对手追杀，火鸡不顾生命为他档了一枪，生死未卜。学成归来的史提芬如期到达食神的比赛场地，没想到评判却被对手收买了……©豆瓣', '周星驰', '李力持', 8.1, 387954, 'tt0116426', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2179639845.jpg', 0.2, 1.2, 20.1, 49.6, 29, '-0.121373,0.001908,-0.583153,0.760187,-0.093123,-0.175100,0.140465,0.175309,-0.501609,-0.352507,-0.208613,0.714320,-0.271933,0.338977,0.309107,-0.218313,0.312623,-0.491759,0.051694,-0.141736,-0.310134,-0.318673,-0.174070,-0.322540,-0.345804,-0.052306,0.369478,0.164276,-0.367137,0.501298,0.588620,0.157912,0.189769,0.584799,-0.209028,0.207734,0.234973,-0.093322,-0.233288,0.091484,0.132559,-0.392200,0.105042,0.227506,0.002551,-0.063200,0.436556,0.030191,0.016181,-0.210719,0.348966,-0.434166,0.202020,-0.047439,0.798975,-0.325358,-0.143554,0.100151,0.053538,0.098598,0.212206,-0.130933,-0.791482,-0.016364,0.156391,-0.162364,-0.778358,0.412821,-0.165145,0.004868,-0.261726,-0.053618,0.250064,0.335675,0.408467,0.205063,0.158214,0.074124,-0.509332,0.259678,0.467291,-0.049174,-0.069187,0.295675,0.180920,-0.448956,0.022536,-0.328427,-0.124457,-0.170708,0.337815,-0.254964,-0.015585,0.106559,-0.115217,-0.148065,-0.121822,-0.258252,0.129853,-0.257845,0.124501,-0.513836,-0.175207,-0.359759,-0.000392,0.068696,-0.203056,-0.309028,0.555120,-0.731751,0.093190,0.384491,0.234740,-0.510035,0.878687,0.029585,-0.029738,-0.228749,-0.048410,0.455256,0.442470,0.246247,0.446713,0.396947,-0.082387,-0.220124,-0.219968,0.404495', '1793491', '1299649', '1308499', '35505100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293353', '小鬼当家2', '喜剧', '又一年圣诞节来临，上集因被遗忘在家而没有去成圣诞旅游的凯文（麦考利·卡尔金 Macaulay Culkin 饰）今年和家人准备到佛罗里达去享受他们的圣诞假期。粗心的爸爸妈妈这次当然不会再忘记带上凯文，但他们丢三落四的性格没有改变。眼看飞机准备起飞了，一家子才急冲冲的赶到机场。这次凯文没被忘在家里，却在登记时被忘在了机场，阴差阳错的登上了飞往纽约的航班！第一次来到这个完全陌生的大城市，聪明捣蛋的凯文也不禁暗暗害怕。更糟糕的是，他竟然遇上了上一集在他家里被他修理得很惨的那两个笨贼。两人刚刚越狱出来，碰上了凯文，这次自然要一雪前耻。于是，凯文的战场从上一集的家里搬到了纽约的中央公园酒店和玩具反斗城！©豆瓣', '麦考利·卡尔金', '克里斯·哥伦布', 8.1, 148208, 'tt0104431', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2442677226.jpg', 0.1, 1, 20.5, 52.1, 26.3, '0.630963,0.074116,-1.063143,0.106442,-0.109122,-0.581211,0.606258,0.080406,-0.275622,-0.118810,0.077263,0.812121,-0.343795,0.270251,0.395580,0.111652,-0.489070,-0.388209,0.139977,-0.296330,-0.428314,-0.280870,-0.100882,0.229352,0.095907,0.088054,0.191571,0.050768,0.033506,0.741102,0.255544,-0.009386,0.324083,0.704098,-0.395416,0.298643,0.053768,0.016226,0.152657,0.424772,0.296234,-0.235910,-0.249736,0.250736,0.321787,0.371153,0.729068,0.113897,-0.386820,0.135886,0.406023,-0.364471,-0.112006,0.202499,0.383626,-0.172844,-0.017338,-0.048360,-0.259531,0.014297,0.096793,-0.023807,-0.512057,0.404380,-0.133295,-0.108041,-0.647371,0.525393,-0.199374,0.006241,0.007201,-0.702103,0.387845,0.602555,-0.065715,0.479894,0.012960,-0.036647,-0.708955,0.263824,0.904792,-0.051209,-0.027990,0.355121,0.282706,-0.106249,0.074335,-0.265930,-0.540857,0.193519,0.568791,-0.134436,-0.362361,-0.036741,-0.518662,-0.025167,-0.254609,-0.499216,-0.083341,-0.310081,-0.232991,-0.723467,0.143488,-0.294644,-0.387950,0.203965,0.010100,0.078274,0.275164,-0.921035,0.446949,0.533249,0.305160,-0.553163,0.727155,0.081674,0.049448,0.038269,0.267137,-0.184338,0.124220,0.647317,0.421671,0.505221,0.070356,-0.318928,-0.561855,0.525096', '26687241', '2079017', '1296538', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293359', '菊次郎的夏天', '剧情', '暑假到来，自幼丧父的小学三年级学生正男（关口雄介饰），如今和奶奶生活在一起，暑假特别无聊。他拿出母亲从外地寄回的信，准备自己一个人去爱知县丰桥市看望母亲。邻居阿姨（岸本加世子饰）发现后，决定帮正男完成心愿。她拿出一笔钱做为旅费，还安排游手好闲的老公菊次郎（北野武饰）陪伴正男一起踏上寻母之途。可是在第一天，菊次郎就把老婆给的钱全部输光，于是两个人只好步行前往爱知。一路搭顺风车，惹了不少麻烦后，菊次郎终于带着正男到了他母亲的家，但小男孩却十分沮丧。归途中，菊次郎努力安慰他，二人过得十分愉快，夏天就这么过去了。©豆瓣', '北野武', '北野武', 8.9, 553662, 'tt0199683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2620392435.jpg', 0.2, 0.8, 8.7, 36.4, 54, '-0.155570,-0.139817,-0.093556,0.032272,-0.106267,-0.621554,0.130964,0.277733,-0.381502,-0.158060,-0.112282,0.289704,0.162172,0.655578,0.634815,0.156475,-0.571901,-0.351347,0.331974,-0.160681,-0.207723,-0.168971,0.427749,0.034872,-0.418893,-0.030110,0.468015,-0.033456,0.435026,0.575113,-0.004785,0.018546,-0.147480,0.298042,-0.371892,0.312551,-0.045434,0.044946,-0.057001,0.178870,0.057095,-0.047155,-0.315752,-0.005968,0.600007,0.221935,0.857667,0.200950,-0.027170,-0.123245,0.158548,0.031667,-0.147889,0.044282,0.220329,0.185280,0.386654,-0.064178,-0.218499,-0.097512,0.231576,-0.295589,-0.029981,0.217336,-0.035796,-0.161209,-0.629697,0.201663,-0.064412,0.108301,0.361648,-0.621833,0.074331,0.418499,0.014407,0.151196,-0.452948,0.242968,-0.152334,0.331336,0.657231,-0.211984,0.584248,0.390514,0.130331,0.058791,0.262398,-0.099052,-0.535977,-0.030872,-0.009933,-0.116145,-0.095269,-0.243044,-0.247429,0.004658,-0.110610,-0.016367,0.415299,-0.388938,0.007373,-0.481205,0.256397,-0.169728,-0.311451,0.234439,0.235428,0.016287,0.627322,-0.473184,0.118818,0.389223,0.356862,-0.227777,0.484713,-0.089311,0.077878,-0.227075,0.229596,-0.275948,0.148032,0.379556,0.120809,0.340448,-0.291119,-0.198508,-0.177352,0.240782', '5403927', '34869495', '2045259', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293364', '飙风战警', '喜剧', '一位是作风矫健、机智幽默的联邦特工威斯特（威尔·史密斯 Will Smith 饰），一位是爱耍聪明的易容大师高登（凯文·克莱恩 Kevin Kline 饰），这两个看似一山不容二虎的狠角色却被总统同时召见了，原因是授命他们一同追捕一名神秘毒辣的科学家连环杀手。威斯特和高登只好在摩擦碰撞中培养默契，竟然很快成为一对绝配拍档。经过调查，两人发现原来幕后黑手竟然是曾经的天才博士勒弗里斯（肯尼思·布拉纳 Kenneth Branagh 饰），他因在一次实验中失去双腿，只好永久呆在轮椅上，然而残缺的个性与对社会的怨恨让他开始到处作乱，甚至发明了一架巨型的蜘蛛机器滥杀无辜，并企图谋杀总统，统治美国。危机迫在眉睫，威斯特和高登分头来到新奥尔良，驾驶着一列布满机关的火车迎战蜘蛛博士，一场古怪武器间的斗智斗勇已悄然展开……©豆瓣', '威尔·史密斯', '巴里·索南菲尔德', 6.8, 13522, 'tt0120891', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495305314.jpg', 1.4, 8, 49.5, 32.5, 8.6, '0.294114,-0.113182,-0.691516,0.536826,-0.155464,-0.137575,0.713989,0.031509,-0.467878,-0.256974,0.570579,0.687669,-0.169709,-0.199798,0.234490,-0.034100,-0.178681,-0.647470,-0.007134,0.016549,-0.218663,-0.563215,-0.523295,-0.291900,0.098408,-0.390628,0.516744,0.033545,-0.257714,0.534767,0.438966,0.301151,-0.167212,0.197492,-0.099842,-0.347020,0.489855,-0.277786,-0.223627,0.125797,-0.216028,-0.217487,-0.009798,0.005680,-0.225739,0.349261,0.422500,-0.479078,0.130807,-0.181941,0.141540,-0.256663,-0.094443,0.186100,0.623436,0.062966,0.147960,0.230272,-0.160883,-0.079465,0.145619,0.003561,-0.716793,0.033619,-0.024133,0.192871,-0.535720,0.260334,-0.168677,-0.124374,-0.092390,-0.226406,0.174944,0.143083,0.355614,0.243237,0.165886,0.089030,-0.186129,-0.119951,0.473186,0.020085,-0.271681,0.133475,0.201572,-0.406460,-0.085627,-0.252359,-0.266766,-0.365936,0.401552,-0.312192,0.006570,0.310374,-0.617977,0.173289,-0.550779,0.079160,-0.081388,-0.247592,0.011593,-0.632276,-0.020550,-0.357384,-0.220022,0.225751,0.007239,-0.076582,0.441453,-0.761817,0.191601,0.329182,-0.078617,-0.295879,0.497121,0.220823,0.010080,-0.124448,-0.148529,0.178026,0.299443,0.079759,0.110085,0.515263,0.177975,-0.227089,-0.275867,0.335760', '3006892', '1793491', '3775167', '24753477');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293372', '同窗的爱', '剧情', '瑞典小镇，两名情窦初开的花季少女。影片开始在安妮（瑞贝卡·里尔杰伯格 Rebecka Liljeberg饰）写下的生日愿望中展开，内向自闭的她把这个秘密一直封存在自己的电脑中。在学校里，她也觉得自己没有真正的朋友，直到她转校来到伊琳（亚历桑德拉·达尔斯托姆 Alexandra Dahlström饰）的班上。外向叛逆的伊琳美丽早熟，身边总是围绕着一群讨好她的女生跟一堆追求她的男生。安妮一直默默的注视着她，暗暗把伊琳作为自己的爱恋对象。在生日聚会当天，大家发现了安妮的秘密——希望伊琳可以爱上她。伊琳因为一个赌注真的亲吻了安妮，两人的关系发生了微妙的变化。她们之间这纯真的爱情，是否能够抵过父母的质问与同学的嘲弄，终可挽着双手、昂首挺胸地走出人群呢……©豆瓣', '亚历桑德拉·达尔斯托姆', '鲁卡斯·穆迪森', 7.7, 8218, 'tt0150662', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2448230021.jpg', 0.3, 2.8, 29.2, 46.7, 21, '0.707919,0.036482,-0.896298,0.665276,-0.292674,-0.206377,0.953686,0.067908,-0.393983,-0.100517,0.311710,0.696941,-0.342585,0.676833,0.311933,0.217937,-0.338775,-0.953840,-0.167868,-0.159314,-0.138269,-0.520168,-0.332622,-0.095851,-0.178735,-0.175711,0.458619,-0.315885,0.108250,0.567550,0.357076,0.113764,-0.101361,0.483430,-0.208381,0.116613,0.228970,-0.139623,-0.116788,0.140665,0.143357,-0.157712,-0.214369,0.353755,-0.004999,0.362213,0.915135,-0.308361,0.040934,0.087166,0.246917,-0.238699,-0.048696,0.277565,0.111945,0.016568,0.267132,0.111415,-0.030333,0.206943,0.120600,-0.076913,-0.350170,-0.047365,0.005341,0.406767,-0.544113,0.622366,-0.123069,-0.086760,0.356673,-0.385744,0.079369,0.317076,-0.012793,0.388928,-0.342249,0.082328,-0.366774,0.115780,0.373129,-0.046926,-0.168055,0.542691,-0.436603,-0.231229,-0.168604,0.232195,-0.856160,-0.097388,0.293536,0.059891,-0.178238,0.339492,-0.688357,-0.056688,-0.031798,-0.019420,0.104951,-0.495683,-0.278484,-0.424246,-0.143430,-0.555969,-0.615489,-0.074952,-0.299517,-0.275103,0.756147,-0.979950,0.142175,0.720802,0.493200,-0.166771,0.629020,0.274389,0.137025,-0.119042,-0.252386,0.324502,-0.411459,0.207252,0.114987,0.562209,-0.021047,0.029208,-0.535020,0.652947', '3155839', '1307146', '24839498', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293373', '一级谋杀', '剧情', '1938年，犯人亨利（Kevin Bacon 饰）试图从著名的阿尔卡特兹监狱逃出，但最终失败。典狱长格伦对威胁自己地位的亨利恨之入骨，将其抛入封闭的地牢中长达三年，期间伴有不计其数的殴打行为。亨利终于得以离开地牢，但他所做的第一件事是用勺子杀死背叛自己的犯人，于是被控一级谋杀。刚离开校门的律师詹姆斯（Christian Slater 饰）受命为亨利辩护，长年的折磨让后者几乎丧失沟通能力，詹姆斯不放弃任何机会，逐渐拉近了两人的距离。初次开庭，詹姆斯将矛头对准非人道的狱方，引发媒体关注，也招惹来各方阻碍，女友与亲兄在压力下先后背离他而去。詹姆斯唯一仰仗的只剩下对正义的执着，但最后关头，亨利却表示自己宁愿被判死……©豆瓣', '克里斯蒂安·史莱特', '马可·罗科', 8.6, 8766, 'tt0113870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199907428.jpg', 0.3, 0.9, 12.2, 42.8, 43.9, '0.076795,0.174375,-0.490206,0.468214,-0.151218,-0.192119,0.667933,0.190392,-0.382096,-0.222429,0.267637,0.622650,-0.125121,-0.121975,0.055246,-0.219583,-0.062352,-0.833289,0.033706,-0.156823,-0.369468,-0.749125,-0.063217,-0.362754,-0.132792,-0.106510,0.636349,0.046023,-0.361427,0.162377,0.313054,0.363480,0.199185,0.606366,0.046372,-0.123863,0.072987,-0.266256,-0.402133,0.262068,0.187924,-0.373030,-0.174011,0.363314,-0.042439,0.499609,0.536347,-0.376322,-0.169333,-0.137309,0.339009,-0.616015,-0.076517,0.421966,0.174806,0.051359,-0.015888,0.421128,-0.224304,0.066634,0.102158,0.033477,-0.686782,0.044610,-0.098534,-0.199400,-0.507737,0.290984,-0.174451,0.237655,0.118467,-0.198365,0.007510,0.332335,0.137997,0.149409,-0.465040,-0.031929,-0.405342,-0.080559,0.728619,-0.327649,-0.227000,0.011641,-0.022103,-0.320015,-0.116364,-0.305698,-0.236742,-0.282280,0.176461,0.330331,-0.204796,0.287549,-0.375371,-0.320552,-0.542441,-0.039608,0.048752,-0.477335,0.033253,-0.498178,-0.053219,-0.045520,-0.368237,-0.085390,0.051449,-0.438854,0.377910,-0.433497,0.310223,0.662584,0.448377,-0.571634,0.682279,0.115600,0.294437,-0.088329,-0.148616,0.634984,0.335160,0.382612,0.206602,0.015600,0.089126,-0.168360,-0.132513,0.377172', '25908042', '4604803', '1309116', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293374', '热天午后', '剧情', '根据真实故事改编，美国历史上最不完善的银行抢案。本该是10分钟完成的银行抢劫犯罪，却变成了12小时的拉锯战。桑尼（阿尔·帕西诺饰）算是美国历史上最倒霉的银行抢劫犯了。一个盛夏的下午，桑尼与同伴塞勒（约翰·卡扎雷饰）闯入纽约市布鲁克林银行，准备实施抢劫。怎奈银行刚刚完成交易，金库内根本没有现钱。倒霉的桑尼与塞勒转而劫持人质，与警方对峙提出要求。但4小时后，劫案现场被围观群众和手忙脚乱的警察弄得像游乐园一样热闹。桑尼走出银行对警察的质问居然赢得了群众的喝彩。8小时后，银行劫案登上了电视节目的实况转播，大家仿佛拍电影一样高兴。而这时夜色降临，人质亦出现了斯德哥尔摩症候群，究竟这场闹剧将以什么方式结束？©豆瓣', '阿尔·帕西诺', '西德尼·吕美特', 8.7, 86268, 'tt0072890', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2100141196.jpg', 0.1, 0.6, 9.5, 43.5, 46.2, '0.525737,0.028063,-0.443101,0.103239,0.159789,-0.321413,0.427996,-0.070842,-0.394388,-0.113774,0.167758,0.360255,-0.433135,-0.067711,0.467642,-0.072550,-0.721268,-0.695062,-0.254427,-0.301883,-0.174609,-0.562141,-0.146691,-0.246655,0.046573,0.089692,0.306335,0.227477,0.126546,0.407006,0.325085,0.149756,-0.112108,0.384173,0.253223,-0.011047,0.382255,0.008054,-0.281906,0.235667,-0.072033,-0.180078,-0.071546,-0.009518,0.101452,0.430171,0.478122,-0.121929,-0.120974,-0.145686,0.583890,-0.405734,-0.275250,0.038510,0.256862,0.048530,0.353729,0.168034,-0.064133,-0.260419,0.083681,-0.148139,-0.414909,0.244374,-0.212256,0.118574,-0.272228,0.201577,-0.275602,0.349832,0.041069,-0.164248,0.252480,0.485249,0.388507,0.398158,-0.024273,-0.280241,-0.682301,0.314761,0.592104,-0.065805,-0.233039,0.217554,-0.041081,-0.570683,-0.014917,-0.294112,0.002609,-0.006777,0.321029,-0.111962,-0.062250,0.092624,-0.434629,-0.099816,-0.257953,-0.454116,0.001404,-0.327878,-0.259010,-1.037525,-0.013840,-0.013120,-0.084116,0.094584,0.106235,-0.018990,0.471867,-0.643490,-0.034881,0.545322,0.474977,-0.076799,0.503657,-0.146244,0.015272,-0.180796,-0.007694,-0.094397,0.105491,0.577653,0.155747,-0.049653,-0.091138,-0.318313,-0.242411,0.316983', '3003137', '3178770', '34961898', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293377', '芳芳', '喜剧', '亚历（文森特•佩雷斯 Vincent Perez 饰）快要结婚了。在他的观念中，一上床就意味着爱的结束。这都是因为小时候他看见妈妈不停更换性伴侣造成的阴影。当他看到舞姿动人的芳芳（苏菲•玛索 Sophie Marceau饰），心里燃起了真爱的火焰。亚历决定，他要追求芳芳，但不去涉及情欲。芳芳也爱上了亚历，然而亚历和她完全是精神恋爱，令芳芳非常苦恼。亚历为了接近芳芳，住在她房间隔壁，装上单面玻璃观察芳芳每天的生活。看着她换上舞服、抬起舞步，做各种鬼怪的表情，却没有勇气打破二人的界限。这面玻璃，成了亚历的一堵心墙。到底还要等多久，才能有情人终成眷属？芳芳终于发现了亚历的秘密，然而亚历能不能消解心结？©豆瓣', '苏菲·玛索', '亚历山大·雅丁', 8.1, 85800, 'tt0106866', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493678188.jpg', 0.3, 1.4, 20.1, 48.2, 30, '0.154234,0.085938,-0.820617,0.298840,-0.173943,-0.332744,0.973093,0.136267,-0.255393,-0.073834,-0.128314,0.455786,-0.257500,0.600222,0.087215,0.243099,-0.524970,-0.589842,0.066166,-0.208990,-0.356955,-0.402735,-0.162133,-0.103558,-0.003097,-0.246221,0.475473,-0.101451,-0.030594,0.074719,0.422738,-0.020900,0.209446,0.591417,0.041806,0.045910,0.054182,0.046327,-0.126358,0.063885,0.119492,-0.153813,-0.126549,0.274739,-0.101869,0.175064,0.444565,-0.177360,-0.028630,0.129891,0.213838,-0.071363,0.096976,0.227721,-0.158657,-0.036326,0.167640,-0.050792,-0.129269,0.030344,0.172857,-0.009942,-0.451098,0.172294,0.022818,0.286987,-0.584807,0.312370,-0.227786,0.010851,0.063423,-0.489708,0.077751,0.221676,0.376337,0.576538,-0.476625,-0.073758,-0.629570,-0.101662,0.475008,0.042449,-0.234434,0.695833,-0.358751,-0.140748,-0.059105,0.099243,-0.404257,-0.278609,0.178386,0.300730,-0.232680,-0.013005,-0.498365,-0.084092,-0.065303,-0.128669,-0.224886,-0.447785,-0.019290,-0.126559,-0.302584,-0.623749,-0.452134,0.219173,-0.143775,-0.440609,0.312956,-0.658349,0.361737,0.254631,0.464077,-0.128660,0.688391,0.338808,-0.096077,0.047649,0.090263,0.391840,-0.358525,0.157046,0.205576,0.533014,0.252398,-0.105694,-0.506199,0.684515', '1292211', '3742987', '4275444', '1304862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293381', 'M就是凶手', '剧情', '一名针对小女孩作案的连环杀手（Peter Lorre 饰）出没，城中人心惶惶。警察全体出动，频繁突击检查。黑帮首领（Gustaf Gründgens 饰）因生意受到严重影响，决定利用乞丐的隐蔽性布下天罗地网。卖气球的盲丐（Georg John 饰）通过《在妖王宫中》的口哨声辨出了杀手，他的同伙（Carl Balhaus 饰）趁机将“Mörder”的首字母“M”标记在其背上。虽然警方锁定了杀手的住处，但杀手被乞丐围困于商业大厦，成了瓮中之鳖。深夜，在黑帮私设的法庭上，杀手会为自己作出怎样的辩护？©豆瓣', '彼得·洛', '弗里茨·朗', 8.3, 27229, 'tt0022100', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p935420710.jpg', 0.5, 1.8, 16.2, 47.7, 33.8, '0.402027,-0.021815,-0.377750,0.327747,-0.089948,0.548148,0.480890,0.162621,-0.639928,-0.062551,0.802779,0.369404,-0.088284,-0.251333,0.291415,-0.261524,0.046894,-0.712759,-0.044271,-0.235187,-0.303886,-0.274644,-0.417805,-0.546056,-0.044480,-0.233796,0.516889,0.266316,-0.249836,0.155814,0.247806,0.416611,-0.387093,0.021192,-0.042784,-0.215790,0.099135,-0.406930,-0.117488,0.436482,-0.546896,-0.552010,0.324190,0.070686,-0.196627,0.604576,0.901230,-0.407074,-0.181584,-0.198544,0.374365,-0.426721,-0.048630,0.197140,0.882215,0.012039,0.029548,0.079810,-0.271219,-0.082781,-0.046924,0.059665,-0.694350,-0.172272,0.611083,0.131254,-0.580127,0.479468,-0.270460,0.172290,-0.285079,-0.073723,0.189284,0.165643,0.245479,0.072553,0.161564,0.125889,-0.603062,0.079594,0.390049,-0.026170,-0.043341,-0.341866,-0.039334,-0.456576,-0.161025,-0.559466,0.069372,-0.234897,0.488272,-0.363788,-0.331370,-0.004962,-0.561010,-0.327192,-0.388222,-0.032621,-0.207039,-0.272199,-0.349937,-0.815315,0.140708,-0.002987,0.074358,0.274626,0.065672,0.252559,0.394641,-1.050881,0.116163,0.744423,0.331870,-0.362970,0.269774,-0.336451,0.205917,-0.053993,-0.404900,-0.160577,0.753652,0.556401,0.298898,0.077416,-0.326670,-0.396150,0.053662,-0.175618', '1292829', '25723905', '3804656', '25912924');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293387', '马文的房间', '剧情', '中年妇女贝西（黛安·基顿 Diane Keaton 饰）的大半生都用来照顾两位年老的亲人：患中风的父亲马文和脾气古怪的姑妈鲁思。现在，贝西自己也患上了血癌，唯一生存的希望是近亲中有人提供骨髓。无奈的贝西只好与20年来没有联系的妹妹李（梅丽尔·斯特里普 Meryl Streep 饰）联络。李是个单身母亲，她并不想与贝西见面，但想到能借此暂时撇开儿子汉克（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）在家里纵火引起的烦恼，还是带着儿子回到佛罗里达的老家。姐妹刚见面时情绪还不错，但时间一久，过去的种种不快又开始作祟。而且住过精神病院的汉克不愿做骨髓化验，伤了贝西的心。后来，汉克与贝西的关系奇迹般地好了起来，并且使两姐妹之间的亲情得以恢复……©豆瓣', '梅丽尔·斯特里普', '杰瑞·扎克斯', 7.8, 14237, 'tt0116999', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2158366606.jpg', 0.2, 1.4, 25.9, 50.9, 21.5, '0.159750,-0.108399,-0.542318,0.573510,-0.147060,-0.794768,0.844986,0.020425,-0.697224,-0.321896,-0.280034,0.521968,-0.061304,0.492462,-0.053251,0.051149,-0.412011,-0.576571,0.091050,-0.120539,-0.370120,-0.400292,-0.176087,-0.173656,-0.244453,-0.415289,0.337828,-0.085302,0.067494,0.406820,0.040281,0.213121,0.135623,0.476724,-0.158925,0.231926,-0.153263,-0.007024,-0.386352,0.137314,0.656893,0.129420,-0.240702,0.254573,0.563194,0.611206,0.335559,-0.105702,-0.036023,0.046133,0.071070,0.248832,0.190699,0.182449,0.326944,-0.091250,0.385683,0.100303,-0.395673,-0.033240,0.063412,0.137735,-0.539500,0.186171,0.121235,0.038874,-0.561001,0.265279,-0.252563,-0.203091,-0.077907,-0.298551,0.275978,0.593308,0.283710,0.406008,-0.347457,0.040056,-0.408239,-0.006351,0.897160,-0.082909,-0.188317,0.357568,-0.311181,-0.383937,0.070008,-0.069102,-0.537072,-0.098084,0.318119,0.095505,-0.092095,0.443148,-0.514194,-0.110829,-0.314826,0.063382,-0.022016,-0.426958,0.160787,-0.338396,-0.383802,-0.395887,-0.304362,0.008335,0.207032,-0.303566,0.500939,-0.792736,0.209631,0.332283,0.256098,-0.417501,0.555870,0.071925,0.321388,-0.055467,-0.043454,0.395942,0.141463,0.130780,0.410517,0.318180,0.030929,-0.018714,-0.345963,0.256014', '1308755', '25721544', '3014557', '10546747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293388', '冬天的故事', '剧情', '侯麦著名系列作品“四季的故事”之一。菲利茜（夏洛特·海瑞 Charlotte Véry饰）和查理（费德瑞克·范丹狄德夏 Frédéric van den Driessche饰）在海边浪漫相恋之后，因为一时不留神留下了写错的地址，而导致了二人再也找不到彼此。菲利茜生下了查理的孩子，但5年来却再也没有查理的音讯。生活还在继续，菲利茜遇上了喜欢她的一些男子，他们也不失为好男人，足够爱自己。比如成熟体贴的马桑（迈克尔·瓦雷蒂 Michael Voletti饰）和才华横溢的路易（Hervé Furic饰）。然而，在菲利茜的心中，查理却仍旧是个挥之不去的至爱之人。她不是不爱他们，只是无法爱到能和他们一起生活。她和路易一起看莎士比亚的歌剧《冬天的故事》，为里面的人物悄然落泪，也许她和剧中人一样，也在坚守着一个信念。终于某个冬天，菲利茜和查理竟然在公车上重遇，执着的梦想等来了实现的一天。', '夏洛特·韦里', '埃里克·侯麦', 8.5, 34489, 'tt0104008', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1665123572.jpg', 0.3, 0.8, 12.8, 47.1, 39.1, '0.363622,-0.029402,-0.866861,0.631294,-0.243360,-0.672353,0.937313,0.058710,-0.520600,-0.145326,-0.017200,0.831612,-0.163676,0.117320,0.210219,0.154033,-0.527727,-0.808575,0.228966,-0.320446,-0.166373,-0.535322,-0.064045,-0.124522,-0.145839,-0.286671,0.554024,-0.083770,0.159313,0.370366,0.247052,0.207861,0.009726,0.424290,-0.275754,0.105275,0.104880,-0.086541,-0.222602,0.178257,0.193447,-0.094285,-0.439866,0.365186,-0.127618,0.294036,0.587955,-0.365220,-0.018894,0.119495,0.231744,-0.149896,0.080544,-0.064432,-0.129151,-0.418270,0.459814,0.116659,-0.145194,-0.081625,0.094702,0.037691,-0.654863,0.132576,0.082963,0.396135,-0.672034,0.698216,-0.248493,-0.256467,0.057775,-0.456830,0.179925,0.297013,0.264882,0.439136,-0.237469,-0.140560,-0.554583,0.203622,0.792157,0.161048,-0.282324,0.557039,-0.206413,-0.365548,-0.217178,-0.166461,-0.856049,-0.000077,0.226556,0.100948,-0.284952,0.015101,-0.731220,0.118441,-0.293210,-0.150667,0.156314,-0.409897,0.037792,-0.504720,-0.236602,-0.733846,-0.400232,0.028672,0.014789,-0.440296,0.684400,-0.910688,0.340795,0.606857,0.361012,-0.423415,0.808277,0.247895,-0.034738,0.104561,0.017933,0.469599,-0.216556,0.019381,0.328869,0.518413,0.164985,-0.029968,-0.515238,0.668978', '3230121', '4275444', '3055049', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293390', '瘦到死', '惊悚', '律师比利（罗伯特·约翰·伯克 Robert John Burke 饰）是一个体型硕大的胖子，他一直都在减肥，但从来没有成功。作为一名颠倒黑白的律师，他和检察官及法官的暗地勾结让他获得了不小的成功。一次交通意外中，比利撞死了一个吉普赛老妇人。在法庭上，借由职务之便，比利通过非法的渠道获得了无罪判决，对受害者亲人的愤怒和悲痛视若无睹。从此之后，好运似乎降临在了比利的身上，一直以来令他困扰的体重居然开始下降，同时，他还可以毫无顾忌的敞开肚子品尝人间美食。事态的发展逐渐超出了可控制的范围，短短几天之内，比利已变成一个骨瘦嶙峋的苍老男子，并且他的体重仍然在持续的下降，而参与不公正审判的同僚们也都出现了不同的病变，这令他明白，吉普赛人的诅咒并非空穴来风，而为了求生，他必须找到下诅咒的那个吉普赛人，并且请求他的原谅。©豆瓣', 'Robert John Burke', '汤姆 霍兰 (Tom Holland)', 6.5, 7909, 'tt0117894', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1393956100.jpg', 1.5, 10, 55.6, 26, 6.8, '0.251862,0.168481,-0.777934,0.668206,-0.276915,-0.334902,0.952045,0.140517,-0.393856,-0.002139,0.278185,0.669816,-0.196973,0.134895,0.120084,-0.102534,-0.127796,-0.693639,-0.097552,-0.117763,-0.288892,-0.661085,-0.435956,-0.275631,-0.370250,-0.377323,0.603412,0.080058,-0.243460,0.373686,0.252056,0.113918,0.286627,0.752211,-0.310436,-0.057098,0.206351,-0.120629,0.007720,0.216942,0.281646,-0.329832,0.157374,0.467804,-0.227201,0.461355,0.520209,-0.431389,-0.353299,-0.065966,0.380027,-0.270478,0.077961,0.293798,0.318662,-0.011244,0.064539,0.275008,-0.311068,0.024377,0.094565,0.118618,-0.930972,-0.086539,0.019761,0.250519,-0.538113,0.500628,-0.032535,-0.073259,-0.101832,-0.342198,-0.004280,0.314921,0.137536,0.382503,-0.416326,-0.035320,-0.655711,0.010180,0.620925,-0.034824,-0.639563,0.170107,-0.314380,-0.537956,-0.066484,-0.206790,-0.400334,-0.110637,0.180376,0.230188,-0.267068,0.223977,-0.430489,0.012771,-0.496399,-0.319950,-0.237699,-0.410746,-0.185839,-0.356489,-0.164366,-0.391988,-0.279889,-0.005551,0.128762,-0.463214,0.634161,-0.814096,0.238315,0.626732,0.336208,-0.456749,0.642195,0.173199,0.164281,-0.038105,-0.344071,0.194532,0.116590,0.465209,0.184699,0.303663,0.174032,-0.112460,-0.319689,0.559349', '1867335', '1851857', '25932086', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293394', '西部往事', '剧情', '意大利西部片宗师瑟吉欧·莱昂的传世经典之作，继与克林伊斯威特合作「镖客三系列」之后，瑟吉欧·莱昂这部近三个小时的长篇钜作，被称之为影史上最伟大的西部片。故事叙述一名神秘客（查理士布朗逊）来到小镇上，被卷入一名寡妇（克劳蒂雅卡迪奈尔）与铁路大亨的土地抢夺战，此片最有趣的角色，是由一向形象正义的亨利方达，难得在此片中扮演一名冷面的残酷杀手，从头到尾几乎没有表情，只有嘴角偶尔小有动作，让人不寒而栗... 当年影片在美国上映时，曾因为片长过长而被片商修剪，导致故事架构含混不清，语焉不详。', '亨利·方达', '赛尔乔·莱昂内', 8.7, 48853, 'tt0064116', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792368479.jpg', 0.4, 1.1, 10.4, 38.3, 49.8, '0.175561,-0.174055,-0.466256,0.661640,0.321093,-0.266994,0.724104,0.060056,-0.440197,-0.500260,0.143642,0.840104,-0.459576,-0.143221,0.416905,-0.199411,-0.093810,-0.438921,-0.428681,-0.282969,-0.043841,-0.363549,-0.285512,-0.106577,-0.196331,-0.350068,0.735247,0.062718,-0.460209,0.262168,0.370867,0.393103,-0.142513,0.089720,-0.160222,-0.015017,0.266608,-0.218677,-0.257947,0.298829,-0.294165,-0.060731,-0.265355,0.021832,-0.306462,0.388195,0.407709,-0.235013,-0.059644,-0.024556,0.475252,-0.165537,-0.138892,-0.181008,0.299725,-0.194871,0.559624,0.347112,0.038254,-0.078996,0.024919,-0.355656,-0.934815,0.208125,-0.037030,0.260337,-0.465026,0.259455,-0.241329,-0.078919,-0.033514,-0.190724,0.316550,0.001137,0.623961,0.159175,0.245697,0.229641,-0.269357,0.337533,0.401039,0.277637,-0.419799,0.428853,0.162597,-0.422826,-0.145164,-0.664660,-0.361754,0.176024,0.216962,-0.332547,0.293680,0.224491,-0.626266,0.000542,-0.139355,-0.191647,0.130523,-0.026773,-0.169100,-0.782899,-0.110811,-0.309991,-0.038421,-0.113573,0.029559,-0.256496,0.779368,-0.501814,0.289806,0.181812,0.018023,-0.034789,0.694728,0.316878,0.175644,-0.143879,-0.193411,0.501285,0.269538,-0.114397,0.107941,0.227519,-0.206544,-0.394167,-0.166819,0.381376', '3318306', '27602116', '25880986', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293396', '野战排', '剧情', '泰勒（查理•辛 Charlie Sheen 饰）是越战期间的一名美国大学生，他前往越南前线去服兵役，被分到了一个步兵部队。部队里有两个人一直对他影响颇大——伊莱亚斯（威廉•达福 Willem Dafoe 饰）和巴恩斯（汤姆•贝伦杰 Tom Berenger 饰）。他们两人对战争的看法截然不同，前者不忍残杀无辜，而后者却杀人如麻，泰勒心里非常迷惑，到底谁对战争的看法才是正确。巴恩斯展开了一场残忍的屠杀，越南整条村落都流血成河。伊莱亚斯力劝好友不要如此残暴，却遭致二人关系的裂缝。巴恩斯更怀疑伊莱亚斯向上司打小报告，友谊变为妒恨。于是，在一次丛林战争中，他背着所有人，向伊莱亚斯扣下了扳机。泰勒却洞察了这一切，他心里终于有了答案。©豆瓣', '威廉·达福', '奥利佛·斯通', 8.2, 41763, 'tt0091763', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1596877271.jpg', 0.3, 0.9, 15.7, 53.4, 29.6, '0.248250,-0.188783,-0.766951,0.556399,0.088830,-0.458166,1.048074,-0.078417,-0.489986,0.076400,0.332715,0.572707,-0.217438,-0.231294,0.113855,0.099197,-0.530219,-0.663656,-0.033115,-0.181344,-0.228330,-0.550255,-0.562392,-0.314006,-0.046550,-0.124842,0.355510,-0.020009,-0.318073,0.523587,0.349918,0.402900,0.276352,0.663335,0.139549,0.121487,0.158620,-0.327591,-0.106369,-0.128369,0.032332,-0.101794,-0.560595,0.379873,-0.012945,0.558301,0.556328,-0.262493,0.062290,-0.158703,0.050192,-0.366760,0.120760,0.276713,0.271971,-0.162937,0.171563,0.109315,0.184033,-0.070809,-0.050684,0.206970,-0.572054,0.067453,-0.196033,0.394589,-0.534488,0.399519,-0.319914,-0.119604,0.065372,-0.292086,-0.048543,0.303428,0.449052,0.145294,-0.384264,-0.357203,-0.325332,-0.327677,0.697476,0.008407,-0.190889,-0.044125,-0.536665,-0.369507,-0.114962,-0.015720,-0.537550,-0.051898,0.468539,-0.190667,0.045879,0.671769,-0.513415,-0.080361,-0.279015,-0.281292,-0.220447,-0.317259,0.110670,-0.481730,-0.146447,-0.529415,-0.583715,-0.084030,-0.028991,0.040265,0.648748,-0.674958,-0.002282,0.344904,0.474332,-0.459752,0.422367,0.420301,0.025926,-0.179564,0.066436,0.307158,0.126016,0.043828,0.209870,0.407647,0.325166,-0.136543,-0.051906,0.596578', '1307748', '3111650', '2131640', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293398', '恐惧与欲望', '剧情', '这是斯坦利·库布里克的第一部故事片。剧本出自他的高中同学、诗人Howard Sackler之手，拍摄资金也是库布里克自己筹措，大部分是向父亲、叔叔和朋友们借的。这部作品和库布里克以后的影片一样充满了超现实主义象征性，因此只有一家艺术片商愿意发行和放映，而库布里克认为此片只是一部实习作品，他只答应私下放映，并多次想将拷贝销毁。尽管如此，本片还是赢得了一些评论家的好评，尤其是在摄影方面。', '弗兰克·斯尔维拉', '斯坦利·库布里克', 7, 12462, 'tt0045758', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522354373.jpg', 0.9, 6.4, 49.7, 28.3, 14.7, '0.313969,-0.312811,-0.417494,0.534210,0.309194,-0.237447,0.428423,-0.131535,-0.431673,-0.336136,-0.064299,1.159260,-0.095142,0.030899,-0.111339,-0.023160,-0.641614,-0.562241,-0.293821,-0.376604,0.247665,-0.547790,-0.303445,-0.087483,-0.326229,-0.374435,0.849529,-0.034877,-0.470642,0.318534,0.481915,0.268682,0.015946,0.251576,0.021381,0.165570,-0.068570,-0.261721,-0.528845,0.311488,0.403418,-0.153935,-0.379725,-0.174328,0.558811,0.471733,0.474002,0.015847,-0.153070,0.536797,0.497088,-0.392044,0.123101,-0.019272,-0.076435,0.271133,0.494590,0.198533,-0.364749,0.237231,-0.203423,-0.363927,-1.147741,-0.411678,0.451732,0.130965,-0.872382,0.317575,-0.111025,0.176826,-0.178689,-0.396027,0.164931,0.100338,0.307868,0.262078,0.119357,-0.116506,-0.380760,0.730064,0.360577,0.138314,-0.079577,0.540487,-0.226426,-0.525095,-0.160894,-0.208403,-0.572428,0.474632,0.255044,-0.055241,0.294037,-0.122556,-0.568234,-0.150975,-0.115015,-0.680269,0.045082,-0.608512,0.354152,-0.998879,-0.049275,-0.135526,0.037979,-0.272798,0.346479,-0.496549,1.015921,-0.759785,0.180581,0.536827,0.591923,-0.318776,0.794516,0.168105,-0.233402,-0.091579,0.058970,-0.062560,0.390584,-0.157789,0.205538,0.206308,0.795938,-0.872900,-0.433672,0.504918', '27602116', '3318306', '1870681', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293399', '莫扎特传', '剧情', '本片从一个宫廷乐师萨里埃利的角度，为我们呈现了天才莫扎特的一生。萨里埃利（F·莫里·亚伯拉罕 F. Murray Abraham饰）是维也纳音乐界里有名的人物，自视甚高的他自从遇到了莫扎特（汤姆·休斯克 Tom Hulce饰），心里的妒嫉之火便熊熊燃烧不能平息。莫扎特总能以他超乎常人的音乐作品赢得全场惊叹，他的《费加罗的婚礼》等歌剧，都成了传颂千古的经典。萨里埃利对莫扎特又羡慕又嫉恨的心理已经发展到几乎扭曲的地步。他在莫扎特的事业上一次次的从中作梗——故意缩短歌剧的上演周期，恶意删改莫扎特的作品，在莫扎特承受着丧父之痛时给他无情的精神折磨。贫穷虚弱的莫扎特在生命最后的几年里，写就遗作《安魂曲》，一代大师35岁就与世长辞，留下不朽作品。而萨里埃利，早有等待他的宿命般的结局。©豆瓣', 'F·默里·亚伯拉罕', '米洛斯·福尔曼', 8.7, 92603, 'tt0086879', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p595764767.jpg', 0.2, 0.8, 10.8, 41.2, 47, '0.111336,0.059183,-0.649443,0.732642,-0.153872,-0.353906,0.863626,0.224736,-0.421159,0.070850,0.372408,0.793541,-0.383968,0.239084,0.314274,0.153208,-0.375064,-0.785974,0.158817,-0.064507,0.011950,-0.293657,-0.458367,-0.174923,-0.150320,-0.533899,0.345284,0.031088,-0.180521,0.272702,0.286502,0.281494,0.281832,0.185735,-0.147488,0.067572,0.003366,-0.179201,-0.002070,0.130156,0.140384,-0.254392,-0.188366,0.195023,-0.428855,0.162301,0.510206,-0.125347,0.241693,0.166504,0.572205,-0.353412,0.043576,0.233511,0.120731,-0.101418,0.063780,0.263211,-0.311948,0.061975,-0.202808,0.039007,-1.000100,-0.035359,0.100231,0.220269,-0.570322,0.757840,-0.202978,-0.173941,0.084774,-0.150617,0.107795,0.003796,0.341411,0.689376,-0.228295,-0.350169,-0.393941,0.146770,0.381457,-0.033580,-0.616564,0.219967,-0.270877,-0.406895,-0.131349,-0.385498,-0.606351,-0.117693,0.318783,0.050307,-0.045232,0.534559,-0.471967,-0.079877,-0.271643,-0.205196,-0.066367,-0.321922,-0.141944,-0.609475,-0.306966,-0.310730,-0.091549,-0.057752,0.361442,-0.380994,0.865490,-0.303231,0.430069,0.484446,-0.205641,-0.001111,0.639623,0.045387,0.042580,0.098032,-0.165063,0.389009,-0.291762,0.236654,0.049708,0.485407,0.166440,-0.137500,-0.449566,1.028442', '1303263', '27666513', '35158375', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293400', '怒海潜将', '剧情', '一直以来，黑人青年卡尔（小库珀·古丁 Cuba Gooding Jr. 饰）都将成为美国海军中的一员当做自己的毕生理想，然而，当他真的加入到了海军队伍中去之后，卡尔才发现，现实远不如想象中美好。在种族歧视之风盛行的军队里，卡尔理所当然的成为了众人伤害和排挤的对象，但个性坚韧的卡尔却并没有因此而退缩和气馁，正相反，他通过比别人多百倍的努力和出色的成绩证明了一个人的成功和失败与肤色无关。比尔（罗伯特·德尼罗 Robert De Niro 饰）的出现让卡尔坚定了想要进入潜水艇搜救队的信念，然而，这支秉性白人至上主义的团队中，还未曾有过黑人加入的先例。通过近两年的不懈努力，卡尔终于加入了潜艇队的训练计划之中并最终成为了其中的一员。同时，他和比尔之间的紧张关系也因为一次不幸的事故而产生了质的改变。©豆瓣', '罗伯特·德尼罗', '小乔治·提尔曼', 8.3, 13348, 'tt0203019', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p854347722.jpg', 0.3, 1.3, 16.2, 48.9, 33.4, '0.287329,0.260206,-0.886195,0.839662,-0.253143,-0.445418,0.860672,-0.179456,-0.671418,-0.174104,-0.009265,0.847117,0.127817,0.005534,0.334132,-0.184389,-0.203860,-0.881489,-0.107036,-0.205544,-0.345880,-0.678952,-0.440892,-0.162345,-0.357458,-0.417096,1.028286,0.226701,-0.513647,0.655867,0.249644,0.186659,0.195826,0.632495,0.129139,-0.118545,0.281555,0.041452,-0.316341,0.226207,-0.060143,-0.109043,-0.241543,0.420858,0.034590,0.478005,0.510063,-0.549313,-0.241231,-0.043400,0.252109,-0.225284,-0.176874,0.185361,0.354279,0.202664,0.221124,0.270921,0.001630,0.082747,-0.230505,-0.107604,-1.133000,-0.020638,0.168044,0.098358,-0.748268,0.529053,0.008638,-0.257278,0.201413,-0.090554,0.151824,0.376284,0.470492,0.207890,-0.408926,0.020975,-0.527912,0.002172,0.804236,-0.021698,-0.609122,0.102578,-0.267753,-0.457850,-0.153100,-0.400894,-0.373941,0.014936,0.162767,0.302402,-0.187328,0.422157,-0.700974,0.265385,-0.332561,-0.168136,-0.194091,-0.462519,0.164712,-0.587927,-0.126187,-0.596844,-0.390992,0.106632,-0.128517,-0.460714,0.778475,-1.024426,0.240539,0.451109,0.295368,-0.581293,0.573141,0.177873,0.256798,-0.176458,-0.225765,0.340354,0.085506,0.101061,0.117200,0.414605,0.033430,-0.383627,-0.226123,0.601437', '1793491', '35030151', '1301022', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293412', '飞狗巴迪', '喜剧', '男孩乔治·菲姆的父亲在一次试飞中因事故身亡，从此爱打篮球的乔治性格变得内向寡言，在学校经常被同学嘲讽和取笑。在搬家的路上他遇见了金毛猎犬巴迪，它刚刚摆脱主人的虐待。乔治回家以后，在后院的篮球场上打篮球的时候再次遇见巴迪，并发现巴迪也喜欢玩篮球。后来他将巴迪带回家，开始了新的生活。他的性格开始发生了转变。偶然的一次交谈中，他发现和自己一起打扫卫生的黑人大叔居然是曾经的著名球星阿瑟。阿瑟使他的球技蒸蒸日上，并教会了他很多做人的道理。在一次比赛中，巴迪的主人在电视上看到了这只会打篮球的狗原来就是他的，于是前往领取。乔治把巴迪救回以后将它放生到荒岛上，防止主人再次寻找到它。由于失去了巴迪，乔治在比赛中节节失利，后来巴迪意外出场使全队取得胜利。最后巴迪被法官公正地判给了乔治，这对好朋友从此以后再也不会分开……', '迈克尔·杰特', '查尔斯·马丁·史密斯', 8.2, 5617, 'tt0118570', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2238394111.jpg', 0.5, 1.5, 19.3, 46.7, 32.1, '0.338029,-0.055383,-0.694659,0.394328,-0.456062,-0.596696,0.714513,-0.048153,-0.476876,-0.003133,0.052280,0.834261,-0.276760,0.419391,0.265598,-0.004178,-0.261718,-0.691188,-0.015376,0.008072,-0.391932,-0.431398,-0.195807,-0.136774,0.034942,-0.536086,0.356882,-0.073285,-0.147509,0.551334,0.213559,-0.018841,0.295574,0.559420,-0.087024,0.230145,-0.002273,-0.028038,0.007908,0.333105,0.290347,-0.216574,-0.114227,0.155503,0.222976,0.270059,0.600597,-0.300111,-0.053344,-0.148317,0.334140,-0.166852,0.069545,0.152468,0.262242,0.036693,0.165390,0.248432,-0.175450,0.012371,-0.214108,-0.005067,-0.378172,0.128459,-0.260362,0.181752,-0.649666,0.617843,-0.092626,0.021761,0.281302,-0.358331,0.131423,0.318595,0.267988,0.128189,-0.220461,-0.010603,-0.435057,-0.176249,0.784140,-0.207739,-0.166634,0.233837,0.075940,-0.156964,0.230811,-0.293209,-0.322153,0.099260,0.461970,-0.216724,-0.331657,0.012262,-0.599948,-0.041506,-0.077430,-0.220420,-0.150329,-0.393668,-0.077142,-0.588971,0.036337,-0.328499,-0.315909,-0.097657,-0.242885,-0.315450,0.506667,-1.001725,0.438355,0.743893,0.304509,-0.202222,0.502205,0.014280,0.085552,-0.079924,-0.038523,0.247461,0.330919,0.402716,0.069545,0.431952,0.250664,-0.178572,-0.450101,0.747424', '1308755', '1292219', '1309172', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293414', '阮玲玉', '剧情', '十六岁入行的阮玲玉（张曼玉 饰）1929年进入联华影片公司后，出演了许多严肃影片。与此同时，阮玲玉厌倦了幼稚的赌鬼男友张达民（吴启华 饰），倾心于成熟的已婚富商唐季珊（秦汉 饰）。张达民起诉阮唐通奸，记者的围堵对阮玲玉造成了巨大的精神压力。在最光辉灿烂的二十五岁，阮玲玉自杀身亡……©豆瓣', '张曼玉', '关锦鹏', 8.6, 102784, 'tt0102816', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p768817927.jpg', 0.1, 0.6, 9.9, 46.4, 42.9, '0.083037,-0.114814,-0.457763,0.216446,-0.013683,-0.157571,0.820989,0.479856,-0.434067,-0.136181,0.459460,0.674545,-0.524684,0.317475,0.315794,-0.194490,0.049845,-0.545216,-0.149204,-0.219932,0.120622,-0.357832,-0.228115,0.069413,-0.214771,-0.438125,0.612119,0.057216,-0.289973,0.514850,0.641526,0.110490,-0.028146,0.146090,0.123819,0.284182,0.059776,0.055872,-0.565931,0.090068,-0.350929,-0.345905,0.208927,-0.321982,-0.250818,0.313363,0.666209,0.060325,-0.228327,-0.261276,1.080634,-0.113602,-0.587174,0.323776,0.316609,0.225436,0.352092,0.113711,-0.349868,-0.014318,-0.142178,-0.148754,-0.432601,0.147950,0.110583,0.274975,-0.435654,0.572554,-0.291157,0.149443,0.109722,-0.186601,0.027844,0.226870,-0.080074,0.279015,-0.160409,0.335006,-0.213411,0.784819,0.345030,0.336251,0.003064,0.582530,-0.255258,-0.576759,-0.259894,-0.178069,-0.570456,0.132945,0.364141,-0.365904,-0.273684,0.236873,-0.359862,-0.350456,-0.024828,0.076734,0.153106,-0.132262,-0.327667,-0.514552,-0.478876,-0.519657,-0.073033,-0.143784,0.045318,-0.190397,0.906886,-0.497486,0.298935,0.352697,0.395567,-0.560696,0.493015,-0.125668,-0.200814,-0.035207,-0.186026,0.517211,-0.307280,0.028579,-0.066278,0.413451,-0.196036,-0.469251,-0.052427,0.166505', '2027945', '7161707', '30465068', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293422', '监狱风云', '剧情', '年轻有为的广告设计师卢家耀（梁家辉 饰）在一次阻止不良分子寻衅滋事中失手伤人，被判服刑三年，在狱中，他因个性憨直得罪了黑帮老大，受尽欺辱，老囚犯钟天正（周润发 饰）看不过仗义相助，两人结为患难之交。钟天正原本有完好家庭，只因嗜赌成性才误杀妻子，身陷囹圄的他追忆往事时后悔不已， 决心走出高墙后重新做人。然而，因为替卢家耀出头，他得罪了狐假虎威心狠手辣的典狱长（张耀扬 饰），自此卷入狱中恶势力的漩涡，走投无路之际，他放弃了“能忍则忍”的处世哲学，决意以暴施暴。©豆瓣', '周润发', '林岭东', 8.4, 115433, 'tt0093304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2347371309.jpg', 0.1, 0.7, 13.1, 51.3, 34.9, '-0.188778,0.070546,-0.337830,-0.081506,-0.206377,-0.257102,0.627457,0.265863,-0.363616,0.051508,0.374872,0.436832,-0.004002,0.268237,0.192031,-0.198226,0.154776,-0.484899,0.052926,0.002733,0.018616,-0.362518,-0.025005,-0.070177,-0.141215,-0.163634,0.489358,0.188412,-0.023765,0.211563,0.450913,0.144078,0.038904,0.292207,-0.057177,-0.106587,-0.039015,0.141131,-0.263007,0.015189,0.018325,-0.458336,-0.210366,0.063931,-0.097694,0.504773,0.416212,-0.292380,-0.143450,-0.506558,0.499239,-0.449258,-0.323238,0.249199,0.195462,-0.048689,0.040664,0.288238,-0.313163,-0.075874,0.028041,0.088509,-0.288108,-0.021047,0.102200,-0.306327,-0.568129,0.377298,-0.074069,0.090644,-0.235356,-0.054669,-0.139253,-0.022080,0.230691,0.050298,-0.177467,-0.092627,-0.404719,0.281521,0.735784,0.063625,-0.034855,-0.125946,0.336343,-0.165927,0.430769,-0.636600,-0.403895,-0.303461,0.470253,-0.276024,-0.322821,0.060293,-0.108457,-0.177070,-0.386698,0.547291,-0.084693,-0.260091,-0.271046,-0.161469,-0.499561,-0.042771,-0.064339,0.199389,-0.099964,-0.382957,0.210061,-0.556391,0.124053,0.226844,0.261353,-0.732088,0.742530,0.479298,0.026637,0.089390,0.041556,0.294136,0.234327,0.051001,0.235588,-0.113699,-0.085525,-0.286198,0.092017,-0.135715', '1305915', '35295405', '1296978', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293426', '森林王子', '动画', '从小被印第安丛林里的狼群抚养长大的莫格利（布鲁斯·雷德曼 Bruce Reitherman配音），一直快乐的生活在丛林里。在森林中，他结识了忠厚老实的黑豹巴布拉（塞巴斯蒂安·卡伯特 Sebastian Cabot配音）和乐天开朗的黑熊巴洛（菲尔·哈里斯 Phil Harris配音）以及其他动物朋友。然而邪恶的老虎希瑞·坎（乔治·桑德斯 George Sanders配音）重返森林，打破了幸福祥和的生活。为了确保莫格利的安全，动物朋友们决定把莫格利送回到人类村落才能躲避开希瑞的追杀。但莫格利却想继续留在丛林里生活，与他的动物朋友们在一起。迪斯尼公司创始人沃尔特·迪斯尼生前监督制作的最后一部动画片《森林王子》，根据Rudyard Kiplings所写的小说《墨格利》改编而成。充满着童趣的故事情节和精彩的配乐对白都为本片增色不少。本片荣获1968年第40届奥斯卡金像奖最佳原创歌曲提名，收录在“白金典藏系列”动画片中。', '菲尔·哈里斯', '沃夫冈·雷瑟曼', 7.9, 4965, 'tt0061852', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1833188027.jpg', 0.3, 1.7, 25.4, 48.8, 23.8, '0.159679,-0.185171,-0.446038,0.867460,0.259288,-0.460551,0.822238,0.049034,-0.252446,-0.301887,-0.145946,0.626063,-0.058037,0.303601,0.229919,-0.119872,-0.700266,-0.238695,-0.237964,-0.163483,0.098860,-0.372319,-0.389361,-0.456875,-0.045933,-0.459140,0.782445,-0.049533,-0.118199,0.436967,0.130839,0.227135,-0.264936,0.070434,-0.065379,0.061041,0.223944,-0.073438,-0.383295,0.243603,-0.101758,0.157922,-0.379728,-0.183606,0.492054,-0.015392,0.923607,-0.518707,0.180878,0.045000,0.408429,-0.256501,0.135324,-0.185925,0.219820,-0.075123,0.320877,0.229141,-0.021008,0.364568,-0.180815,-0.426459,-0.734763,-0.104556,0.133172,0.175791,-0.420488,0.349318,0.122172,0.051400,0.234182,-0.238972,0.270847,-0.010234,0.545415,0.107442,0.020001,0.460385,-0.406740,0.222936,0.526441,-0.059606,-0.150916,0.000078,-0.255747,-0.682315,-0.160310,-0.088212,-0.632740,-0.198082,0.416884,-0.241275,-0.096079,0.341952,-0.731846,-0.221665,-0.113494,-0.559627,-0.097940,-0.383381,-0.151743,-0.823426,0.090069,-0.357125,0.056911,-0.304011,0.036575,-0.429440,0.833985,-0.587286,0.513204,0.457852,-0.040530,-0.122141,0.777548,-0.067392,0.317395,-0.012287,-0.242636,0.553990,0.222238,0.190941,0.260944,0.340967,-0.088603,-0.030641,-0