INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293433', '深海圆疑', '科幻', '南太平洋1000尺的深海海底，美国政府发现了一艘已有300年历史的神秘太空船。当局立刻组成了一队由心理学家诺曼·古德曼（达斯汀·霍夫曼 Dustin Hoffman饰）、生物化学家贝丝·哈波琳（莎朗·斯通 Sharon Stone饰）和数学家哈瑞·亚当斯（塞缪尔·杰克逊 Samuel L. Jackson饰）这三位顶尖科学家组成的科学小组前往当地调查。他们利用高科技的实验艇深入海底进行探测。然而船体内部的一个巨大而怪异的球状体，拥有着洞悉每个人的内心世界的强大魔力，它似乎能控制每个人的思想和行为。更糟的是，一个不明海底生物也向实验艇发起了攻击。由美国著名导演、编剧巴瑞·莱文森执导的科幻悬疑电影《深海圆疑》，改编自迈克尔·克莱顿于1987年出版的同名小说。本片巨星云集，达斯汀·霍夫曼、莎朗·斯通 、塞缪尔·杰克逊等大牌明星联袂演出这部惊悚科幻影片。©豆瓣', '达斯汀·霍夫曼', '巴瑞·莱文森', 7.1, 11405, 'tt0120184', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1636317368.jpg', 1.1, 6, 43.6, 37.6, 11.8, '0.176225,-0.293356,-0.704929,0.821982,0.321933,0.135154,0.736592,-0.089951,-0.329188,-0.290207,0.148213,0.866853,-0.272954,-0.097936,0.122884,0.144058,-0.476482,-0.410601,-0.293716,0.016037,-0.216300,-0.397950,-0.797844,-0.437134,0.134075,-0.380224,0.672245,0.199874,-0.295190,0.302250,0.200778,0.405178,-0.141088,0.097173,0.174875,-0.053975,0.462301,-0.310440,-0.264264,0.238645,-0.215389,0.131592,-0.007918,0.025284,-0.057305,0.310854,0.409716,-0.384434,0.075230,-0.167746,0.409578,-0.293673,0.027224,-0.167832,0.306780,0.155216,-0.145753,-0.123853,0.050400,0.173643,-0.026355,-0.018304,-0.883459,-0.098409,0.020737,0.278450,-0.266329,0.042360,-0.211797,-0.028395,-0.268234,-0.186141,-0.031271,-0.158320,0.290493,0.197827,0.123282,0.079595,-0.250531,0.424143,0.262736,0.127961,-0.687317,0.060285,-0.263637,-0.604087,-0.378999,-0.284783,-0.316706,0.002383,0.492898,-0.071806,-0.029377,0.274025,-0.714493,0.101010,-0.248464,-0.343610,-0.283979,-0.252196,-0.023644,-1.139424,-0.032964,-0.234348,0.003270,-0.093232,0.078472,-0.170329,0.782362,-0.326800,0.107230,0.681955,0.093943,-0.188301,0.757927,-0.347576,-0.108194,-0.208847,-0.049500,0.233552,-0.015223,0.257749,-0.029098,0.640456,0.414442,-0.220098,-0.170873,0.134310', '3318306', '1293656', '26577354', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293434', '王牌对王牌', '剧情', '丹尼（塞缪尔·杰克逊 Samuel L. Jackson 饰）是一名出色的谈判专家，屡立战功。当他的人生顺风顺水时，刹那间的转折让他措手不及。他的搭档发现警局内有人私吞公款，却在打算告诉丹尼实情时惨遭杀害，第一时间赶到现场的丹尼自然最大嫌疑人。当他确信是警局内有人要找他做替死鬼，百口莫辩之际，他铤而走险绑架了内务监察部检察官和其助手等人，想通过与警方的对话为自己洗刷罪名。丹尼要求另一分局派出谈判专家来和自己对话，因为他清楚要谋害自己的人就在自己的局里。于是邻局的谈判专家史宾恩（凯文·史派西 Kevin Spacey 饰）奉命前来和丹尼谈判，史宾恩相信了丹尼，开始为他搜集证据。©豆瓣', '塞缪尔·杰克逊', 'F·加里·格雷', 8.5, 110735, 'tt0120768', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1971419890.jpg', 0.1, 0.5, 11.5, 49.5, 38.4, '0.062632,-0.059989,-0.847784,0.472313,-0.158237,-0.358324,0.483259,0.081639,-0.762551,-0.243857,0.058798,0.677169,-0.036730,0.001449,0.368432,0.142889,-0.673767,-0.914725,0.035576,-0.305204,-0.383686,-0.667063,-0.072902,-0.537113,0.094538,0.061945,0.202277,-0.055797,-0.317662,0.343059,0.389534,0.159724,0.067387,0.577397,0.088590,-0.061225,0.353179,-0.202596,-0.341476,0.147192,0.167499,-0.151995,-0.433090,0.261447,0.027637,0.568770,0.227534,0.012648,-0.101503,0.005276,0.004534,-0.584443,0.258379,-0.008636,0.289720,0.018975,0.294118,0.402639,-0.243825,-0.105268,-0.056845,-0.009450,-1.037728,0.120267,-0.224825,0.114759,-0.375773,0.006570,-0.433159,0.193303,0.234035,-0.343395,0.151347,0.506462,0.158819,0.073812,-0.087441,-0.197670,-0.384552,0.336294,0.743296,0.014780,0.072460,0.083507,-0.026138,-0.324276,0.253693,-0.149561,-0.033696,0.000080,0.370183,-0.054206,-0.045822,-0.077247,-0.148340,-0.280847,-0.501467,-0.051247,-0.181670,-0.345084,0.184268,-0.428689,-0.174989,-0.023862,-0.407916,-0.048302,0.170911,-0.128299,0.365463,-0.699494,-0.089597,0.817891,0.317493,-0.595158,0.712519,0.148374,0.132923,-0.475267,-0.154319,-0.363798,0.399819,0.634141,0.199934,0.216610,0.368806,-0.420217,-0.511632,-0.003173', '1307442', '35073886', '3811342', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293442', '异种', '动作', '自20世纪70年代开始，美国政府实施了名为SETI的计划，30年来不间断的用射电望远镜扫描宇宙空间，旨在寻找外星生物和相关文明。在犹他州的德威市，有一所隶属政府的实验室，这里正在进行一项秘密试验。在此之前，人类曾受到外星文明发回的信息，其中包括外星生物的DNA组成和生命重组的方法。犹他州实验室的科学家们利用外星人提供的资料培养出拥有外星人DNA的新人类“塞尔”。出于某种原因，政府决定中止这项实验，但其中一个塞尔却逃出实验室。她将给人类带来怎样的影响？本片荣获1996年MTV电影奖最佳银幕之吻奖、1995年科环宇宙杂志最佳化妆奖、1995年Sitges-Catalonian国际电影节最佳特效奖。©豆瓣', '本·金斯利', '罗杰·唐纳森', 6.5, 17709, 'tt0114508', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2357515285.jpg', 1.7, 10.8, 56.8, 24.2, 6.4, '-0.011946,0.255058,-0.507098,0.693497,0.035683,0.296268,0.147861,-0.407013,-0.448899,-0.388795,0.127984,0.476311,0.166472,-0.086382,0.046498,-0.085129,-0.569726,-0.403259,-0.046506,-0.141535,-0.391792,-0.446611,-0.627258,-0.281543,0.040652,-0.623068,0.861250,-0.146257,-0.488867,-0.033181,-0.092874,0.459597,-0.137814,0.062695,0.004329,-0.291169,0.411625,-0.190848,-0.542566,0.391556,-0.017301,-0.122081,-0.207005,0.072037,-0.033854,0.141296,0.744382,-0.314187,-0.055261,-0.559092,0.693479,-0.299075,-0.181695,-0.372409,0.419863,0.280076,-0.130250,0.215984,0.086142,0.149409,0.166696,-0.140267,-0.933181,-0.488174,0.221697,-0.002908,-0.159363,0.022376,-0.203601,0.358429,-0.204993,-0.263285,0.188924,0.516781,0.579267,0.354383,-0.071499,0.194172,-0.331261,0.501312,0.173671,-0.198128,-0.615438,0.098288,-0.359701,-1.022268,-0.261749,-0.349423,-0.141570,0.159928,0.200913,0.195347,-0.186469,0.424001,-1.053130,0.219475,-0.146749,-0.735503,0.511134,-0.292230,-0.166166,-1.228843,-0.091540,0.093927,-0.274271,-0.097647,0.098444,-0.466221,0.891695,-0.578574,0.173625,0.762203,0.232760,-0.545943,0.822037,-0.185406,-0.039671,-0.386278,-0.085924,0.115301,-0.014318,0.595132,-0.476152,-0.010370,0.336167,-0.211785,-0.249136,0.316380', '2369613', '22265121', '3318306', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293448', '鬼玩人2', '喜剧', '青年艾许（布鲁斯·坎贝尔 Bruce Campbell 饰）开车载着女友琳达（丹尼丝·比克斯勒 Denise Bixler 饰）外出游玩，途中他们因故落脚于一间无人居住的林中木屋。艾许在书房内发现一本书和录音设备，其间记录了古代史教授诺比（约翰·皮克斯 John Peakes 饰）造访康达城堡并发现失踪长达上千年的《死者之书》的全过程。当录音带中教授念起召唤邪灵的咒语时，似乎沉睡已久的恶魔就此苏醒。琳达遭到攻击后化身恶魔，艾许被迫杀死女友自己也无法避免被侵蚀的命运。当他从昏迷中醒来后，意识到自己已被邪灵困入绝地，无法逃开。夜幕降临，魔鬼的狂欢拉开帷幕，艾许的难忘之夜就此开始……©豆瓣', '布鲁斯·坎贝尔', '山姆·雷米', 7.3, 9798, 'tt0092991', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1380498829.jpg', 1.5, 5.5, 36.4, 39.9, 16.8, '0.251336,0.069762,-0.501414,0.195164,0.154928,-0.298620,0.938799,-0.076511,-0.477399,-0.504874,0.136142,0.606541,-0.313419,0.399130,0.324776,0.023606,-0.321512,-0.553351,-0.035953,-0.211524,-0.296748,-0.146661,-0.266233,0.060672,-0.006725,-0.524774,0.465656,0.112030,-0.049207,0.383454,-0.177073,0.307596,-0.334301,0.452929,-0.027589,0.089587,0.153323,-0.264215,-0.133195,0.337599,-0.006320,-0.304599,-0.064969,0.130350,-0.186521,0.154422,0.846392,-0.549927,0.168199,-0.356780,0.261697,-0.080879,-0.188427,0.212886,0.475749,0.217285,0.232362,0.214148,-0.205483,0.116924,0.057483,-0.021563,-0.389112,0.194819,-0.176132,0.275512,-0.194947,0.197453,-0.114605,0.379480,0.022196,-0.454290,0.179195,0.015583,0.255795,0.245261,-0.081264,-0.131742,-0.586153,-0.025649,0.280092,-0.388748,-0.231539,0.346477,0.044564,-0.455163,0.080591,0.032534,-0.315752,-0.124096,0.466948,0.518418,-0.265660,0.299825,-0.579591,-0.128909,-0.666551,-0.080001,-0.213038,-0.084942,-0.464674,-0.755457,-0.194511,0.212955,0.026465,0.120425,-0.070163,-0.073535,0.176815,-0.660312,0.598815,0.438694,0.182976,0.184186,0.480037,-0.141854,0.175997,-0.008522,0.066288,0.552834,-0.035018,0.706345,0.191193,0.168130,0.105968,-0.145516,-0.503871,0.409887', '10466639', '1316693', '1309194', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293452', '妖兽都市', '动作', '故事发生在未来世界，阿龙（黎明 饰）和阿强（张学友 饰）都是抓捕妖兽的特警队警员，但是上司（袁和平 饰）非常器重阿龙，而对阿强就戒心重重。阿强气不过在酒吧买醉，得到了女友（李若彤 饰）的支持宽慰。然而，他心头总是笼罩着阴影——原来阿强的母亲也是妖兽，后来他把这个隐秘告诉了阿龙。阿龙也坦白了自己跟妖兽幻姬（李嘉欣 饰）的一段感情……此后，阿龙在一次抓捕元大宗（仲代达矢 饰）的行动中，重逢了现已成为元妻的幻姬，情急之下却要引出重重误会。其实，元大宗是要跟人类合作的妖兽，但是另有一股液态妖兽正在肆虐地侵袭这个城市。在对抗液态妖兽的过程中，阿龙与幻姬的感情经历了生死的考验，但是元大宗的儿子鬼众道（张耀扬 饰）却设计离间意图消灭人类，与此同时阿强也发现了特警队的叛徒……©豆瓣', '黎明', '麦大杰', 6.2, 16004, 'tt0105869', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1798078756.jpg', 3.4, 17, 52.9, 19.9, 6.8, '0.170806,-0.111089,-0.611885,0.742976,-0.087054,-0.030249,0.815560,0.016900,-0.660648,-0.118944,0.233824,0.278377,-0.119375,0.180440,0.080080,-0.022863,0.194114,-0.539497,0.117064,-0.056245,-0.082405,-0.367288,-0.468919,-0.153938,-0.094176,-0.422630,0.588827,0.199874,-0.250743,0.208298,0.206989,0.258154,-0.249773,0.556825,0.003599,-0.044144,0.041874,0.129761,-0.224232,0.011889,0.112458,-0.243985,-0.007522,0.414242,-0.096930,0.451090,0.593276,-0.269093,-0.125250,0.094874,0.060892,-0.572698,0.057643,0.001202,0.465399,0.035217,0.288149,0.382412,0.099489,0.080978,-0.056525,0.185594,-0.524494,0.115210,0.106309,0.110657,-0.529362,0.620926,0.000661,0.247738,0.080396,-0.090555,0.197974,0.394165,0.226016,0.369989,-0.188979,-0.045461,-0.527358,0.002928,0.717604,-0.222087,-0.020154,0.433873,-0.158137,-0.614955,-0.408988,0.008530,-0.144497,-0.135038,0.107010,0.091457,-0.318400,0.422068,-0.739660,-0.134767,-0.119479,0.036573,0.009552,-0.322645,0.181027,-0.207198,-0.349783,-0.447221,-0.378547,0.014372,0.229146,-0.238824,0.771059,-0.727755,0.086098,0.579327,0.389076,-0.615800,0.655444,0.011347,-0.024955,-0.184275,0.181956,-0.053967,-0.010586,0.204562,0.164718,0.393385,0.101340,-0.234480,-0.269963,0.176817', '25721544', '3005387', '2053515', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293455', '永恒和一日', '剧情', '患有癌症晚期的诗人亚历山大（Bruno Ganz）在进医院等待死亡的前一天，想将一直陪伴其左右的狗交托自己的亲生女儿，遭到对方拒绝。女儿对自己处境的不了解，以及女婿打算将自己的祖屋卖掉，令亚历山大神伤不已黯然离开。在亚历山大孤独地面对自己生命的最后一天时，太太安娜在世时的诸多生活片段、探望独自生活在疗养院中的年迈衰弱母亲的情形、花费大半生心血研究的19世纪诗人所罗穆斯等，一一以或真实或梦幻的形态与他会面，来助他解除对“明天会持续多久”的困惑。©豆瓣', '布鲁诺·冈茨', '西奥·安哲罗普洛斯', 9.1, 32866, 'tt0156794', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1391839595.jpg', 0.3, 0.7, 6.6, 28.2, 64.1, '-0.179247,0.193734,-0.779494,0.384252,-0.064774,-0.266581,0.829157,0.067311,-0.722961,-0.416124,0.429387,0.900070,-0.041052,0.540483,0.283598,0.028112,-0.310524,-0.626258,0.020323,-0.019029,-0.437659,-0.478614,-0.090633,-0.393169,-0.226853,-0.336777,0.560161,0.140264,0.088800,0.341297,-0.200666,0.470885,0.056140,0.596027,-0.325736,0.009567,-0.121114,-0.030334,-0.387966,0.210996,0.477771,-0.176867,-0.105802,0.212158,-0.061207,0.177090,0.737485,-0.191399,-0.280017,-0.169640,0.427076,-0.121141,-0.123903,0.339673,0.186605,0.033121,0.111371,0.208630,-0.426175,0.025006,-0.160825,0.113872,-0.791033,-0.188850,0.097094,0.111302,-0.748154,0.353916,-0.151965,-0.072946,0.214100,-0.372478,0.192874,0.595654,0.112291,0.600718,-0.269122,-0.062941,-0.276312,0.298159,0.615122,-0.228345,-0.170725,0.339939,-0.296281,-0.181049,-0.007930,-0.276075,-0.651829,-0.015331,0.072748,0.376162,-0.319261,0.353389,-0.419008,-0.192182,-0.361843,-0.267497,0.091433,-0.456373,-0.326018,-0.408390,-0.111444,-0.407354,-0.254635,-0.197818,0.215230,-0.322015,0.663519,-0.623488,0.447790,0.375522,0.443632,-0.486377,0.764258,0.106648,0.117039,-0.227191,0.196394,0.631676,-0.081329,0.314656,0.084442,-0.000667,0.133663,0.287054,-0.599138,0.536041', '3036465', '21354767', '25723780', '1949369');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293456', '莫里斯', '剧情', '少年莫里斯·霍尔（奥兰多·威尔斯 饰）在海滩接受了性教育之后，却宣称自己不会结婚。1909年，在剑桥读大二的霍尔（詹姆斯·威尔比 饰）结识了大三的克莱夫·达勒姆（休·格兰特 饰）。1910年，两人的感情突飞猛进，而霍尔也因此被康沃利斯院长（巴里·福斯特 饰）赶出了学院。1911年，眼看着朋友里斯利（马克·坦迪 饰）子爵被判刑，达勒姆承受了巨大的精神压力。1912年，经过一个半月的深思熟虑，达勒姆结束了与霍尔的恋情。1913年，达勒姆邀请霍尔作为傧相参加自己的婚礼，但他没有想到，他的猎场看守亚历克·斯卡德尔（鲁伯特·格雷夫斯 饰）将会与霍尔相爱……©豆瓣', '詹姆斯·维尔比', '詹姆斯·伊沃里', 8.9, 75897, 'tt0093512', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2455549510.jpg', 0.1, 0.5, 8.5, 37.8, 53.1, '0.387017,-0.396790,-0.633239,0.274005,-0.119956,-0.576880,0.633922,0.217265,-0.517512,-0.409007,-0.049564,0.477857,-0.474713,0.097461,0.671969,0.202357,-0.411932,-0.666876,0.356598,-0.439892,-0.138360,-0.786859,-0.173260,-0.174612,0.003286,-0.766195,0.322680,-0.187463,0.179406,0.778473,0.227285,0.346266,0.628566,0.250169,0.159770,0.110919,0.724815,0.062239,-0.256147,0.294660,-0.216267,-0.093346,-0.287498,-0.216870,0.299953,0.441861,0.208406,-0.060661,0.435963,0.032993,0.241100,-0.264593,0.072497,0.438217,0.291538,-0.152632,0.019357,0.527600,-0.428464,-0.060665,0.152169,-0.412927,-0.001898,0.206033,-0.025307,0.092633,-0.632009,0.822798,-0.497060,0.003762,-0.425928,-0.315583,-0.357156,0.370703,0.150532,0.299637,0.112785,-0.225086,-0.358155,0.125024,0.529537,-0.172269,-0.395131,-0.302974,-0.201601,-0.488947,0.065089,-0.256768,-0.504012,-0.044144,0.418738,-0.099903,-0.143739,0.663386,-0.239063,-0.165093,-0.719127,-0.339629,0.022674,-0.324008,-0.103824,-0.898026,-0.140901,-0.483832,-0.445670,-0.217484,0.091917,-0.130188,0.514137,-0.794392,0.486097,0.510007,0.477843,-0.025591,0.615627,0.006230,0.399126,-0.033218,0.090493,0.381360,0.053321,0.153624,0.523441,0.486643,0.324221,-0.225760,0.090400,0.714273', '3139191', '2034997', '2372389', '1305068');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293460', '雨中曲', '喜剧', '1927年，由唐·洛克伍德（吉恩·凯利 饰）和丽娜·雷蒙德（简·哈根 饰）主演的《皇家流氓》在好莱坞首映。由于丽娜刺耳的嗓音无法匹配其夺目的外貌，为了维护明星形象，宣传部只得安排唐一人讲话。首映后，由于钢琴师科斯莫·布朗（唐纳德·奥康纳 饰）的汽车爆胎，为了躲避疯狂的影迷，唐意外结识了能歌善舞的凯西·塞尔登（黛比·雷诺斯 饰），并被其深深吸引。数周后，首部有声电影《爵士歌手》爆红，唐与丽娜的新片《决斗骑士》不得不临时改变拍摄方式，而凯西也成为歌舞片演员。因预映口碑极差，科斯莫提议将《决斗骑士》改为歌舞片，由凯西为丽娜配音，凯西积极附议。与凯西吻别后，唐心花怒放，在雨中载歌载舞。科斯莫的计划能否奏效？幕后的凯西能否走到台前接受观众的掌声？©豆瓣', '吉恩·凯利', '斯坦利·多南', 9.1, 203202, 'tt0045152', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1612355875.jpg', 0.1, 0.4, 6.1, 31.6, 61.8, '0.076702,0.062286,-0.390183,0.668406,0.089934,-0.562095,0.491428,0.306784,-0.343169,-0.336828,0.058856,0.485311,-0.478088,-0.003227,0.599606,-0.129808,-0.503421,-0.512997,-0.242193,0.168874,0.040474,-0.498293,0.108695,-0.630076,-0.207098,-0.284229,0.415549,-0.038332,-0.206252,0.320916,0.694872,0.265393,0.009060,0.205334,0.557947,-0.039350,0.252606,-0.203569,-0.516019,0.382058,0.100294,-0.113588,-0.208774,0.071886,0.275239,0.285072,0.373389,-0.392682,0.342921,0.102569,0.518345,-0.237984,0.446329,0.127662,0.186862,0.076611,0.032619,-0.220517,-0.138335,0.030178,-0.000999,-0.220669,-0.455477,0.194136,0.117423,0.078367,-0.265768,0.395790,-0.363817,0.168430,-0.036237,-0.165670,-0.062519,0.058505,0.690830,-0.034702,0.067898,0.190088,-0.033960,0.178226,0.464338,0.439580,-0.274768,-0.009882,-0.421895,-0.694263,-0.312750,-0.130730,-0.546129,-0.071180,0.666765,-0.027449,0.428782,0.209372,-0.208340,-0.558773,-0.276990,-0.277104,-0.331134,-0.269359,0.189601,-1.088268,0.103856,-0.236250,0.245552,-0.300501,0.072559,-0.092195,0.532296,-0.698192,0.097059,0.236309,0.168764,0.003218,0.238507,-0.160594,0.080273,-0.114881,-0.221296,0.419596,0.202275,-0.045678,0.202641,0.293526,0.066117,-0.276318,-0.102016,0.510366', '6517421', '34961898', '2364001', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293466', '卡蜜儿·克劳岱尔', '剧情', '罗丹（杰拉尔•德帕迪约 Gérard Depardieu  饰）是一个名满世界的雕塑家，众所周知的“思想者”就是他的作品。实际上，除了他自己的艺术天才外，还有一个人在罗丹的艺术和感情生命中有举足轻重的地位，那就是他的情人卡蜜尔（伊莎贝尔•阿佳妮 Isabelle Adjani饰） 。卡蜜尔也是一位极具艺术天份的美少女，与罗丹忘年相恋。但是，大凡和大师的恋情总是充满折磨和坎坷一样，卡蜜尔也一样。他们之间疯狂而充满激情的爱情，会带给卡蜜尔怎样的命运呢？©豆瓣', '伊莎贝尔·阿佳妮', '布鲁诺·努坦', 8.2, 27665, 'tt0094828', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2388254938.jpg', 0.2, 1.2, 18, 50.2, 30.3, '0.171123,-0.217251,-0.592243,0.882384,-0.249974,-0.229371,0.966700,0.098529,-0.467608,-0.163757,0.226135,0.944326,-0.116028,0.283432,0.210749,-0.080816,-0.061666,-0.662214,-0.105090,-0.278185,-0.164005,-0.465121,-0.386266,0.185183,0.000537,-0.404889,0.780594,-0.088639,-0.379605,0.415598,0.452807,0.289254,0.019850,0.406875,-0.259640,-0.111230,0.296446,0.414427,-0.357968,-0.069804,0.087359,0.178994,-0.119977,0.061371,-0.547101,0.056816,0.311123,-0.404391,0.021605,0.029440,0.450876,-0.258360,-0.156154,0.137175,0.134187,-0.158327,0.272298,0.286176,-0.038706,0.099474,0.218195,-0.016466,-1.104083,-0.209368,0.487548,0.320294,-0.535958,0.835661,0.282051,-0.327561,0.189416,-0.071209,0.224216,-0.018446,0.305089,0.667129,-0.118166,-0.318363,-0.613653,0.242233,0.486593,0.221494,-0.215218,0.441741,-0.601055,-0.441177,-0.202821,-0.336751,-0.753294,-0.123311,0.119315,-0.192942,-0.105676,0.464932,-0.745952,0.309721,0.068541,-0.007612,0.140134,-0.605886,0.155964,-0.624886,-0.286581,-1.056870,-0.347642,0.087285,0.479719,-0.499969,1.155161,-0.928500,0.290145,0.443767,0.040345,-0.371347,0.929046,0.425266,-0.234184,-0.258784,-0.498745,0.395328,-0.198488,-0.042929,-0.296644,0.536315,0.297051,-0.008142,-0.302207,0.900494', '1303542', '26283288', '27602116', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293470', '透明人', '科幻', '隶属于美国军方的某神秘机构，正在进行着一项隐形技术的研究。科学家塞巴斯蒂安·凯恩（凯文·培根 Kevin Bacon 饰）是这支小组的主要负责人，经过多年的努力，他们的研究在动物身上已经初见成效。急功近利的塞巴斯蒂安无视药物的不稳定性，执意在自己身上尝试。该药物的隐形效果非常出色，但是塞巴斯蒂安却无法恢复正常。为此，他的搭档琳达·福斯特（伊莉莎白·舒尔 Elisabeth Shue 饰）和马特·肯辛顿（乔希·布鲁林 Josh Brolin饰）抓紧解药的开发，而塞巴斯蒂安却越来越喜欢隐形的感觉，透明的状态让他可以为所欲为。为了保持现有状态，他变得丧心病狂……本片荣获2001年美国科幻恐怖电影学院最佳特效奖、2000年洛迦诺国际电影节观众奖。©豆瓣', '伊丽莎白·苏', '保罗·范霍文', 6.8, 58594, 'tt0164052', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p593948317.jpg', 0.8, 6.7, 52.4, 32.7, 7.4, '0.024347,0.146254,-0.514440,0.713834,0.007070,-0.125202,0.410087,0.045725,-0.605395,-0.362910,0.171259,0.547380,-0.104503,-0.024742,-0.011179,0.106130,-0.404992,-0.501593,-0.141446,0.057690,-0.237957,-0.467364,-0.610129,-0.345540,-0.168080,-0.468177,0.827569,-0.153124,-0.332740,0.130587,0.256055,0.290708,0.235283,0.249153,0.114981,-0.512135,0.381305,-0.410186,-0.336016,0.413047,0.331988,-0.215134,-0.190466,0.297614,0.263979,0.141526,0.659873,-0.164640,-0.158508,-0.041611,0.468485,-0.248416,-0.079874,-0.074569,0.292443,0.149306,0.039779,0.066215,-0.051963,0.163303,-0.020981,-0.069130,-0.952363,-0.048596,0.195926,0.219213,-0.388632,0.421985,-0.317139,0.183948,-0.061155,-0.473012,0.015472,0.244077,0.318310,0.280445,-0.106215,0.065757,-0.384258,0.302655,0.214513,-0.041480,-0.632950,0.451695,-0.539412,-0.657609,-0.271795,-0.437298,-0.166701,-0.124686,0.147851,0.151206,-0.083849,0.199628,-0.518293,0.204652,-0.158476,-0.480410,-0.210651,-0.103276,0.159855,-0.870879,-0.078871,-0.508844,-0.262795,-0.076559,-0.009934,-0.402586,0.606666,-0.780372,0.140466,0.666514,0.138492,-0.365211,0.449362,0.005314,-0.133774,-0.245826,-0.637412,0.234836,-0.197848,0.178701,0.139015,0.385049,0.313189,-0.213076,-0.305761,0.432548', '2369613', '1793491', '27073234', '20388224');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293471', '夺宝奇兵3', '剧情', '传说用耶稣在最后的晚餐中用到的圣杯喝水，便能长生不老。在一次掘金活动中，记载圣杯的碑石被发现，圣杯存在的可能吸引着大批的疯狂的人展开寻找。印第安纳琼斯博士（Harrison Ford饰）也是他们中的一员，甚至连他的父亲老琼斯（Sean Connery饰）也陷入其中——但他给琼斯留下圣杯的笔记后便不知所踪。踏上威尼斯的土地，琼斯和事先约好的史奈达博士（Alison Doody饰）会面，他们在图书馆里凭线索找到圣盾后，却开始遭到莫名的来自十字剑兄弟的追杀。一番波折后，琼斯终于找到了老琼斯，同时，史奈达的纳粹身份暴露，笔记被抢走。圣杯随时都有可能落入纳粹的手中。于是，琼斯父子俩开始联袂上演拯救圣杯的精彩大戏！©豆瓣', '哈里森·福特', '史蒂文·斯皮尔伯格', 8.2, 64392, 'tt0097576', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1703183716.jpg', 0.2, 0.9, 16.2, 51.6, 31, '0.269640,0.162655,-0.751135,0.509813,-0.007831,-0.291843,0.668201,-0.226100,-0.370740,-0.105659,0.241992,0.867326,-0.250518,0.097918,0.217451,-0.007175,-0.491419,-0.914629,-0.080946,-0.262933,-0.532334,-0.401943,-0.417896,-0.067372,0.041440,-0.458778,0.460621,0.208646,-0.217758,0.327447,0.241938,0.247284,-0.153763,0.438130,-0.121983,0.146038,0.171495,-0.091174,-0.309619,0.367424,0.209085,-0.145053,-0.254157,0.222918,0.020737,0.411763,0.647963,-0.506188,0.153602,-0.030490,0.287649,-0.214643,-0.151331,0.261272,0.309110,0.418079,0.121344,0.176164,-0.168786,0.086543,0.173897,0.014447,-0.854661,0.008811,0.026357,0.411013,-0.406772,0.337717,0.094691,0.037246,0.102982,-0.260998,0.593537,0.243705,0.437890,0.056066,-0.037673,-0.249587,-0.608630,0.121020,0.535873,-0.402144,-0.013306,0.000890,0.067125,-0.467140,0.101543,-0.046908,-0.136956,-0.074963,0.613292,0.290966,0.049915,0.244765,-0.752085,0.040400,-0.313600,-0.228687,0.036303,-0.331680,-0.229227,-0.795018,-0.089327,-0.107009,-0.093160,0.138452,0.040990,-0.326637,0.602084,-0.561903,0.535216,0.354673,0.049132,-0.033959,0.602904,0.088856,0.067567,-0.160944,-0.267141,0.161502,0.279738,0.456135,0.302015,0.094745,0.184998,-0.170979,-0.397963,0.546493', '25928048', '26577354', '30162520', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293475', '黄飞鸿之二：男儿当自强', '剧情', '白莲教徒接下满清大臣纳兰元述（甄子丹）所下的对付革命党人的命令后，在广州街头借“扶清灭洋”的口号大肆捣乱洋人的使馆、教堂等地盘，甚至连小学生也不放过，他们的举动令黄飞鸿（李连杰）、十三姨（关之琳）与梁宽（莫少聪）异常气愤。在某个医学会议上，黄飞鸿与革命党领袖孙文（张铁林）一见如故，发现革命党人对救国更具远见时，他决定帮助革命党人逃过厄运。随后，他直捣白莲教总坛决胜九宫真人，揭开迷信假像，又因奋慨国运衰竭民智末开，不惜与纳兰元述决一死战。©豆瓣', '李连杰', '徐克', 8.2, 126305, 'tt0105839', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2585646640.jpg', 0.1, 0.6, 17.3, 52.8, 29.2, '0.091669,-0.190705,-0.538833,0.623893,0.227976,0.080282,0.222689,0.234366,-0.544971,-0.076718,0.217160,0.653605,-0.164835,-0.088336,0.018325,-0.341155,-0.297978,-0.631724,-0.276039,0.055712,-0.059397,-0.315957,0.023010,-0.364507,-0.354035,-0.077586,0.448908,0.345933,-0.422621,0.456502,0.454235,-0.108279,-0.078880,0.509711,0.028380,0.034613,-0.019872,-0.070969,-0.359753,0.007023,0.095263,-0.453545,-0.303595,0.298603,-0.258827,0.448383,0.092299,-0.345918,0.066700,-0.270714,0.130763,-0.341847,-0.137982,0.481608,0.384155,-0.008294,0.105232,0.237485,0.154324,-0.074640,-0.056746,0.033937,-0.245037,0.027344,0.215860,-0.084513,-0.409186,0.374838,-0.084039,0.257280,-0.019874,-0.386672,0.128614,0.477765,0.152274,0.040539,-0.007016,-0.179252,-0.408555,0.277602,0.478355,-0.074756,-0.016115,-0.209283,-0.024290,-0.322420,0.003680,-0.298016,0.057225,-0.084724,0.262535,-0.521215,0.092449,0.165136,-0.454815,-0.364891,-0.120592,0.239751,0.009817,0.062225,0.068951,-0.648156,-0.141570,-0.090993,-0.080811,0.051641,0.215264,0.052332,0.566001,-0.629954,-0.002619,0.268915,0.413572,-0.537917,0.497543,0.051618,-0.224106,-0.217293,-0.290895,0.098667,0.257634,0.647407,0.109580,0.179029,-0.086380,-0.246966,0.127280,0.016746', '1308866', '26365262', '25833539', '1431694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293482', '电子世界争霸战', '动作', '凯文·弗林（杰夫·布里吉斯 Jeff Bridges 饰）是个天才程序员，然而曾经开发的一款游戏软件被前同事盗取，为了证实那是自己的作品，凯文试图进入前同事公司的主控程序MCP，却发现其已经强大到随意控制其他程序。凯文求助于同事艾伦（布鲁斯·巴克林纳 Bruce Boxleitner 饰），后者设计了一款钳制MCP的程序Tron，不想MCP察觉了凯文的动作，将他吸进程序空间，变成一个掌控之下的小程序。在MCP空间内，凯文需要保住性命，更要找到破解方法回到现实……《电子世界争霸战》是史上第一部赛博空间题材电影。©豆瓣', '杰夫·布里吉斯', '史蒂文·利斯伯吉尔', 7.4, 7401, 'tt0084827', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p676731255.jpg', 1.1, 5.1, 32.5, 43.7, 17.5, '0.262917,0.553259,-0.462129,0.541558,-0.128861,-0.280530,0.598469,-0.026570,-0.437339,-0.427625,0.304576,0.415980,-0.105289,-0.061758,0.146264,0.168824,-0.568592,-0.382932,0.074488,-0.407007,-0.362243,-0.426694,-0.488808,-0.177934,-0.121376,-0.610033,0.974537,-0.207686,-0.480471,-0.282235,-0.079686,0.126446,-0.281856,0.150480,0.316769,0.158017,0.288081,-0.547008,-0.626081,0.406298,-0.094257,0.184018,0.032017,0.215561,0.076497,0.291789,0.599726,-0.267010,0.033177,-0.133029,0.652411,-0.082369,-0.100729,-0.303353,-0.126655,0.391736,0.171573,0.034019,-0.183481,0.235153,0.295793,-0.301183,-0.920349,-0.097954,0.088101,0.194334,-0.219909,-0.111786,-0.604809,0.155410,-0.261776,-0.817761,-0.019694,-0.034577,0.536149,0.300703,-0.001939,0.311150,-0.457511,0.043316,0.249046,-0.243564,-0.510618,0.568304,-0.086904,-0.344367,-0.449921,-0.233264,-0.345381,-0.027707,0.363387,0.315882,-0.027962,0.215921,-0.462322,-0.104329,-0.174986,-0.160062,0.081855,-0.192775,0.052517,-0.789798,-0.159024,0.305243,-0.224697,-0.339047,-0.006320,-0.495081,0.427202,-0.738951,0.071144,0.687677,0.366175,-0.154774,0.615985,-0.107282,0.239722,-0.319747,0.083105,-0.005070,0.181735,0.515206,0.102252,0.410816,0.065047,-0.496306,-0.589399,0.455814', '26759820', '2369613', '26275494', '6844861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293485', '青春珊瑚岛', '剧情', '一次意外中，艾米丽（波姬·小丝 Brooke Shields 饰）和理查德（克里斯托弗斯·阿特金斯 Christopher Atkins 饰）流落到了一座孤岛上，面对凶险的大自然，他们必须为自己开拓一片赖以生存的环境。好在岛上的物资十分的丰饶，两人的生活上不成问题，只是在偌大的天地间，茕茕独立的孤独只有两人自己清楚。获救之日遥遥无期，艾米丽和理查德却早已习惯了岛上闲散安逸的生活。孤男寡女，奇妙的感情慢慢的拉近了两人的距离，不久之后，艾米丽生下了一名男婴，为两人的生活又增加了一份快乐。救援队的不期而至打破了这世外桃源般的生活，在和救援人员进行了交流后，两人发现，他们早已不适合再生活在文明社会之中，两人决定留在此地，永远的生活在他们的伊甸园之中。©豆瓣', '波姬·小丝', '兰德尔·克莱泽', 7.8, 8967, 'tt0080453', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1246529686.jpg', 0.5, 2.6, 27.8, 45.8, 23.2, '0.407959,0.201763,-0.950399,0.674381,-0.000538,-0.284376,0.844909,0.133441,-0.635140,-0.156347,0.219282,0.856703,0.031781,0.250133,0.242272,-0.103859,-0.520647,-0.678207,-0.032114,-0.402615,-0.436504,-0.358998,-0.328361,-0.212454,-0.433622,-0.286050,0.777819,0.212845,0.024683,0.329469,-0.351034,0.104617,-0.192258,0.493160,-0.398063,-0.011895,0.052208,0.157022,-0.562677,0.230171,-0.171084,-0.148892,-0.297720,0.128085,0.139982,0.266082,0.857832,-0.430442,-0.329139,0.046852,0.181371,-0.232947,-0.180946,-0.001982,0.218937,-0.311590,0.230003,0.126170,-0.531449,0.024009,-0.104506,-0.312271,-0.514985,-0.040362,-0.017207,0.259352,-0.403886,0.702411,0.343395,-0.423457,0.075981,-0.459468,0.149146,0.672663,0.318851,0.540608,-0.063793,-0.127067,-0.266762,0.173955,1.015098,0.015057,-0.590170,0.563267,-0.368564,-0.496229,-0.312832,-0.222319,-0.639478,-0.352640,0.278097,0.225980,-0.242693,0.447789,-0.898484,0.380645,-0.301574,-0.280456,-0.085245,-0.451437,0.013267,-0.718145,-0.190613,-0.626214,-0.433690,0.307966,0.030045,-0.320776,0.544679,-0.970421,0.320632,0.367075,0.285166,-0.308192,0.635572,-0.032005,0.376522,-0.260893,0.218463,0.347700,-0.115786,0.433402,0.329095,0.385558,-0.239994,0.331635,-0.680358,0.451614', '1291835', '25721544', '11541282', '26316956');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293492', '战舰波将金号', '剧情', '影片发生在1905年，一艘名为波将金号的战舰上，原本这是一艘沙皇海军的骄傲，可是因为连续数月的伙食太差，导致了一场哗变。沙皇海军波将金号战舰上，水兵的生活环境非常差，受着非人的待遇。一连数月，水兵的伙食很差，供应的牛肉甚至长满了蛆，引起了战舰上水兵们的极度不满。部分水兵策动起义，却受到了军官的镇压。指挥官下令枪杀叛乱者，但是由于起义之火在众人心中燃烧。行刑队拒绝开枪，起义者们拿起武器将军官丢入大海。波将金号被起义者们夺取，并驶入敖德萨石阶进行补给。敖德萨的群众对水兵们的遭遇非常同情，义愤填膺，纷纷声援起义的水兵。而群众的声援却遭致沙皇军队的镇压，一场血腥的屠杀就此展开……©豆瓣', '亚历山大·安东诺夫', '谢尔盖·爱森斯坦', 8.7, 26936, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2173021177.jpg', 0.3, 0.7, 10, 42.7, 46.3, '0.215513,-0.269003,-0.547754,0.488567,0.309586,0.175695,0.843709,-0.000953,-0.580996,0.139082,0.409128,0.369193,0.011229,-0.186200,0.251591,-0.410264,-0.313066,-0.502177,-0.194146,0.274801,-0.201720,-0.163015,0.033131,-0.266176,-0.207788,-0.702551,0.840507,0.264824,-0.181029,0.415305,0.123131,0.116222,0.529915,0.570771,0.055645,0.046774,-0.115460,-0.468298,0.031795,-0.057952,-0.302523,-0.490684,-0.113576,0.118838,0.016095,0.377920,0.871218,-0.535833,-0.033247,-0.314765,0.120248,-0.607405,0.169912,0.280532,0.498404,0.392503,-0.331731,-0.116339,-0.013483,0.143763,0.081318,0.156040,-0.348895,-0.102095,-0.201059,-0.117341,-0.337062,0.563990,-0.072216,0.325539,-0.256834,0.034034,-0.012593,0.403004,-0.154351,0.223905,-0.473475,0.079245,-0.661207,0.152462,0.876583,-0.045943,-0.236588,-0.204354,-0.520115,-0.416100,-0.223415,-0.524802,-0.322566,-0.217551,0.298915,-0.064528,0.114313,0.563592,-0.918999,0.134243,-0.413517,-0.905156,-0.023518,-0.007185,-0.361965,-1.017579,0.285233,-0.066713,-0.185419,0.341053,0.170280,0.175077,0.830580,-0.558761,-0.089487,0.238621,0.296798,-0.381074,0.192894,0.086397,-0.036000,0.312150,-0.268627,0.246894,0.154836,0.418850,0.449955,0.153046,-0.326793,-0.369349,0.197729,0.218732', '1307897', '2159244', '1294917', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293506', '末日戒备', '动作', '偏僻的俄罗斯驻防军区，两列火车相撞爆炸。随即发生了一场匪夷所思的核爆炸，俄罗斯境内造成重大伤亡。美国白宫反核走私情报部门的朱莉亚·凯利（妮可·基德曼 Nicole Kidman饰）博士怀疑这起核意外并非偶然发生的事故。为了追查这起爆炸的始末，查明背后的真相，朱莉亚与陆军特种部队的少尉托马斯·威尔（乔治·克鲁尼 George Clooney饰）受命展开调查。他们在艰苦的调查中，竟发现了一个惊天大阴谋。一名冒充政客的核恐怖分子已携带核弹头进入美国本土，欲炸毁设在纽约的联合国总部。女导演咪咪·莱德的电影处女作《末日戒备》，根据资深调查记者安德鲁·科伯恩和莱斯利·科伯恩的文章改编而成，其中素材源于科伯恩夫妇收集的解密情报和真实新闻事件。©豆瓣', '乔治·克鲁尼', '米密·莱德', 6.6, 5046, 'tt0119874', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2725192707.jpg', 1.2, 8.9, 56.7, 26.4, 6.9, '0.353295,-0.298109,-0.737814,0.286028,0.310246,0.326687,0.578572,-0.086276,-0.306511,-0.402219,0.416260,0.555712,-0.274544,-0.351895,0.405195,-0.040499,-0.590808,-0.516814,-0.120070,-0.132471,-0.012362,-0.692776,-0.628744,-0.351052,0.152182,-0.227710,0.376408,0.302895,-0.459906,0.398916,0.273493,0.639408,-0.268631,0.106997,0.419004,-0.056492,0.501983,-0.168469,-0.278149,0.092518,-0.172275,-0.363685,0.193157,0.082355,0.118864,0.480994,0.449333,-0.273093,-0.132437,-0.253741,0.546995,-0.415281,0.106436,-0.016849,0.571777,0.515199,0.079890,0.357347,-0.130421,-0.107609,0.190924,0.069664,-0.663295,-0.098145,0.171887,0.498223,0.015198,0.092583,-0.353960,0.161130,0.087536,-0.056367,0.349743,0.670112,0.263978,0.002360,0.138857,0.153171,-0.297066,0.214608,0.517880,-0.223185,-0.215479,-0.136967,0.027677,-0.465742,-0.038323,-0.048312,-0.079498,0.408330,0.383443,-0.272758,0.066897,0.541236,-0.420731,-0.217550,-0.482070,-0.268955,-0.224526,0.092206,-0.094900,-1.239092,-0.224544,-0.018919,-0.238644,-0.183651,0.065725,0.046502,0.425688,-0.221020,0.023335,0.676080,0.013012,-0.349100,0.082697,-0.064398,0.125006,-0.318039,-0.093996,0.201560,0.313587,0.315612,-0.278665,0.324544,0.368034,-0.590152,-0.173571,-0.198517', '6517421', '1293572', '34961898', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293511', '穷街陋巷', '剧情', '查理（哈威·凯特尔 Harvey Keitel 饰）和意大利移民朋友们混迹在纽约曼哈顿的下东区，没有固定职业，靠着替黑手党卖命混口饭吃。查理的好友乔尼（罗伯特·德尼罗 Robert De Niro 饰）欠了黑市商人迈克尔的钱，却无力偿还，整日被追债。查理与乔尼的表妹特丽莎真心相爱，但是特丽莎希望他能离开这种不稳定的生活，去寻找新生活。迈克尔因为找乔尼要不到钱而恼羞成怒，查理为了帮乔尼摆平此事，承诺他会尽早还钱。在酒吧里，迈克尔发现乔尼已经穷到极致，根本就不可能还钱时，两人扭打在一起。失控的乔尼拔枪瞄准迈克尔，逼退了迈克尔。为了躲避迈克尔的报复，查理、乔尼、特丽莎三人决定躲到乡下去，他们在开车去看电影的路上，一辆汽车从后面追上来。车里正是迈克尔，他拔出手枪向三人的车子开火。汽车被撞翻了，受伤的三人，艰难地从车中爬出，面对茫茫黑夜，他们发出了无望的哭喊。', '罗伯特·德尼罗', '马丁·斯科塞斯', 7.6, 9781, 'tt0070379', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1347693967.jpg', 0.6, 2.5, 30.7, 49.7, 16.4, '0.338563,-0.099796,-0.494165,0.230553,-0.076956,-0.635092,0.683859,0.130623,-0.132147,0.013997,0.226188,0.718287,0.193331,-0.009731,0.263591,0.085919,-0.613488,-0.630861,0.060169,0.057993,-0.308154,-0.546180,0.013943,-0.466412,-0.155600,0.054449,0.280902,-0.172302,-0.174366,0.596041,0.227331,0.311622,-0.092961,0.391868,-0.183828,0.159508,0.062029,-0.115558,-0.336232,0.318929,0.119916,-0.229154,-0.181097,-0.026320,0.338454,0.365478,0.391651,0.123133,0.197030,0.100801,-0.069206,-0.190367,0.091609,0.105538,0.038820,-0.326508,0.049796,-0.013044,-0.206333,0.231070,-0.021143,0.238399,-0.530575,0.204878,-0.399189,0.058756,-0.894239,0.302764,-0.280319,0.049750,0.202447,-0.452802,0.330205,0.316178,-0.016315,0.216373,-0.198756,0.037370,-0.782946,-0.005726,0.555515,-0.072531,0.034113,0.324304,-0.068213,-0.152918,-0.084082,0.139668,-0.547166,-0.493075,0.645966,0.036183,-0.187513,-0.037432,-0.453924,-0.078102,-0.269686,-0.379680,-0.108360,-0.265271,-0.220180,-0.630311,0.004456,-0.269580,-0.104440,0.031921,-0.185953,-0.156276,0.145980,-0.514727,0.083108,0.639016,0.484142,-0.155194,0.801270,-0.056657,0.041648,-0.121878,-0.131076,0.230916,0.242800,0.506569,0.348473,0.137496,0.020028,-0.099022,-0.269309,0.394097', '1301345', '1295324', '1293908', '1292467');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293515', '极度深寒', '动作', '一艘豪华的邮轮“阿尔戈号”航行在茫茫的大海之上，穿上搭载的除了身价万千的贵妇和富豪外，还有价值无可估量的珍贵货物，然而，在这纸醉金迷的海上生活背后，却隐藏了一个邪恶的阴谋，一群穷凶极恶之徒受到委托，要将这艘邮轮洗劫一空。但是，一种外表可怖的神秘海怪却提前一步袭击了邮轮，富丽堂皇的装潢在霎时间被鲜血淹没。姗姗来迟的强盗们眼前展现的是一副人间地狱的惨状，幸存者崔莉安（法米克·詹森 Famke Janssen 饰）和西蒙（安东尼·希尔德 Anthony Heald 饰）向他们诉说了事情的经过。现在的情况是，阿尔戈号孤立无援，又有嗜血的怪兽潜伏在黑暗之中，本来敌对的双方现在唯有联起手来，共同杀出一条逃生之路。©豆瓣', '特里特·威廉斯', '斯蒂芬·索莫斯', 7.6, 61427, 'tt0118956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1261755612.jpg', 0.5, 3, 32.6, 46.4, 17.6, '0.356532,-0.055105,-0.774256,0.633158,0.117035,-0.016067,1.259407,-0.002952,-0.388252,-0.043369,0.517235,0.536922,-0.094273,0.011443,0.193662,0.118910,-0.283270,-0.483952,-0.245325,-0.320654,-0.151567,-0.293924,-0.618471,-0.179243,0.128778,-0.181433,0.695756,0.443532,-0.167946,0.382533,0.309580,0.308443,-0.210640,0.460653,-0.439491,-0.309410,0.020568,-0.132269,0.000625,0.075748,-0.518706,-0.224947,-0.065494,0.203563,-0.107368,0.497663,0.814903,-0.443731,-0.062369,0.089370,0.145534,-0.250557,0.209726,0.297301,0.289231,-0.170371,-0.096642,-0.101150,-0.209179,-0.075544,0.121886,0.091612,-0.838209,-0.319587,-0.088792,0.122412,-0.501151,0.488828,0.032590,-0.140125,-0.085560,-0.263950,0.180397,-0.046407,0.045290,0.359075,0.084970,0.094814,-0.852538,-0.139868,0.764412,0.197686,-0.318555,0.229045,-0.288909,-0.366447,-0.404592,-0.452878,-0.374668,-0.327010,0.580198,0.008392,-0.093879,0.265259,-1.028181,0.244944,-0.262779,-0.344918,-0.460207,-0.333419,-0.456938,-0.583922,-0.112444,-0.469074,-0.177091,0.362543,0.149314,-0.106333,0.631722,-0.447253,0.024411,0.517468,0.125077,-0.301150,0.728841,-0.086947,0.053457,0.104716,-0.165614,0.015036,0.226822,0.525995,0.060642,0.480603,-0.105644,-0.064945,-0.364707,0.500590', '21619567', '1578663', '1309101', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293516', '战狼传说', '剧情', '青年阿Ben（梁汉文 饰）通过网络试图寻找最著名的杀手战狼，终于得到战狼搭档威叔（黄子华 饰）的引见，在熟睡的战狼面前，威叔向阿Ben讲述他们年轻时的故事——战乱年代，阿威生活的小村中闯入了一个失忆陌生人冯文轩（甄子丹 饰），阿威为冯文轩引路，半途遇上山贼，冯文轩大开杀戒，令阿威折服，拜其为师。山贼一伙并未善罢甘休，对冯文轩展开连番追杀，冯文轩伤重之时，因阿威而与旧日恋人惠怡（李若彤 饰）重逢，冯文轩寻回了失去了记忆，发现自己曾经竟也是山贼的一员，而越来越严酷的杀伐令他与恋人深陷险境……阿Ben听了二人的讲述后，并未改变心意，并揭露了自己寻找冯文轩的真正目的……©豆瓣', '甄子丹', '甄子丹', 6.4, 5174, 'tt0172711', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2354805456.jpg', 3.6, 14, 50.1, 22.8, 9.4, '0.205662,-0.185315,-0.374925,0.680354,0.182938,-0.436866,0.794409,-0.104286,-0.514466,-0.482737,0.279397,0.391430,0.003213,0.052616,0.383097,-0.345227,-0.134976,-0.759615,-0.060400,-0.050515,-0.248138,-0.286495,-0.215306,-0.123413,-0.320981,-0.310602,0.823266,0.071301,-0.510877,0.518885,0.388524,0.278764,-0.199959,0.372704,-0.071350,0.033982,0.028474,0.258075,-0.472686,0.127995,-0.181577,-0.489068,-0.158489,0.139462,-0.377309,0.345702,0.881787,-0.541985,-0.132469,-0.361870,0.260900,-0.230203,0.106233,-0.074946,0.308031,0.021589,0.147962,0.155838,0.060769,-0.129205,-0.169680,0.003452,-0.549568,-0.033644,0.281686,0.064285,-0.429040,0.025536,0.036041,0.147826,0.149815,-0.093308,0.248127,0.413423,0.517864,0.135057,-0.027744,-0.068507,-0.258149,0.236178,0.595516,-0.079839,0.066410,0.319069,-0.150820,-0.564906,0.151540,-0.008674,-0.389682,0.125697,0.162655,0.192133,-0.085863,0.420840,-0.401232,-0.173938,-0.271578,0.056442,-0.001428,-0.486402,-0.031058,-0.526058,-0.462201,-0.161100,-0.135609,0.092134,-0.142803,-0.115430,0.543858,-0.776889,0.198637,0.365541,0.269184,-0.414821,0.524821,-0.001077,0.072751,-0.442882,0.003607,0.412669,0.214182,0.060220,0.128355,0.074416,-0.228919,0.015752,-0.371615,0.128264', '1417036', '10467125', '30345227', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293518', '火云传奇', '喜剧', '当朝六王爷（单立文 饰）勾连土番，意图不轨。陇北节度使截获六王爷通外密信一封，遭六王爷座下两大宠幸刺客之一的“火云邪神”映霞（林青霞 饰）追杀，节度使遇刺前将密信、虎符交托亲弟玄明（莫少聪 饰），玄明避难一杂技班中，班主莲容（吴君如 饰）癫狂泼辣，爱慕玄明却不见容，只得藏起虎符强留。莲容之兄阿镇（巫刚 饰）身为相国护卫，武艺高强。火云邪神行刺相国却不敌玄明阿镇联手，火云邪神为取回密信遂乔装普通民女混入戏班，潜伏日久，被戏班内平和亲切的氛围打动，但六王爷与另一刺客映雪（叶全真 饰）的耐心已到达了极限……©豆瓣', '林青霞', '袁和平', 6.4, 6543, 'tt0109803', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2299464976.jpg', 1.7, 10.9, 59.5, 20.9, 7, '-0.151184,0.116194,-0.133804,0.552856,0.093372,0.110196,0.565027,0.462600,-0.581476,-0.207962,0.647861,0.158206,-0.111784,-0.398894,0.187959,0.081151,0.095899,-0.397067,-0.295090,-0.327349,0.211679,-0.330234,-0.258361,-0.090670,-0.059394,-0.286386,0.179291,-0.006005,-0.026074,0.497751,0.183855,0.088311,-0.593471,0.197433,0.092673,0.018742,0.047584,-0.300011,-0.126586,0.112504,-0.413394,-0.330807,-0.183777,0.237326,-0.041996,0.421530,0.235135,-0.547459,0.425867,-0.330831,-0.049001,0.220080,-0.041785,0.107451,0.135063,0.160179,-0.005433,0.334788,-0.221719,-0.044984,-0.085168,0.003642,-0.461125,0.470270,0.126638,0.137853,-0.002241,0.149429,-0.426478,-0.047647,-0.210868,-0.285619,0.147470,0.111720,-0.014172,-0.246271,-0.083005,0.251177,-0.199082,0.325491,0.168998,-0.145253,0.082906,-0.264403,0.468283,-0.289404,0.340560,-0.259130,-0.042950,-0.005067,0.303665,0.012259,0.540120,0.222827,-0.140388,-0.398478,-0.571166,0.674818,0.063321,0.126918,0.000714,-0.123713,-0.101905,-0.120140,-0.203740,-0.327536,0.780545,0.265603,0.435186,-0.299037,0.206682,-0.007675,0.194270,-0.730886,0.217645,0.269327,-0.024246,0.073310,-0.276781,-0.127400,0.349300,0.331662,0.206402,0.160698,-0.363636,-0.411303,-0.337284,-0.187905', '3412830', '3804746', '1461031', '3189969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293527', '美国X档案', '剧情', '德瑞克（爱德华•诺顿 Edward Norton 饰）的父亲在他很小的时候就被一名黑人毒贩射杀，从此给他幼小的心灵埋下了仇恨的种子。原来德瑞克功课很好，是老师眼中的好学生。但自从父亲遇难后，他就将一切心机都放在了对付有色人种上面。他积极组织起一帮白人青年混混，到处和有色人种对着干。一次，他射杀了两名黑人，因此入狱。入狱后，德瑞克加入了一伙新纳粹的白人。后来，因工作关系他和一名黑人成了好友，他开始反思自己的过去。当他意欲脱离狱中新纳粹组织时，遭到了拳打脚踢。德瑞克出狱后，决心和以前自己组织的帮会脱离关系，带着弟弟远走他乡开始新的生活。©豆瓣', '爱德华·诺顿', '托尼·凯耶', 8.5, 92229, 'tt0120586', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792437057.jpg', 0.2, 0.9, 12.9, 47.2, 38.7, '0.350860,-0.053147,-0.793382,0.560579,-0.317043,-0.535763,0.754191,0.142785,-0.606926,-0.226238,0.119099,0.665349,0.065143,0.463990,0.192370,0.003679,-0.595870,-0.855187,-0.203528,-0.241292,-0.491409,-0.397561,-0.218138,-0.287617,-0.288029,-0.374234,0.520807,-0.182617,-0.039410,0.336799,0.390393,0.545614,0.295147,0.416750,-0.152096,0.127929,0.287082,-0.464184,-0.243399,0.054497,0.161294,-0.270056,-0.188461,0.215896,-0.097906,0.541665,0.748924,0.023754,0.077059,-0.534041,0.052291,-0.316887,-0.008380,0.343747,0.405717,0.043290,0.218930,0.433912,0.072587,-0.023925,-0.226646,-0.098844,-0.383996,-0.019434,0.119810,0.088799,-0.775823,0.624208,-0.173568,0.178727,0.089786,-0.129772,-0.099123,0.322859,0.066491,0.264794,-0.092062,0.082058,-0.537556,0.039039,0.853290,-0.185708,-0.135866,0.164782,0.055207,-0.251449,-0.153973,0.045812,-0.287605,-0.080792,0.552720,-0.273562,-0.387564,0.441629,-0.684089,-0.219074,-0.398668,0.088173,0.025237,-0.169347,-0.111080,-0.467487,-0.078541,-0.249013,-0.541600,0.126087,-0.141400,0.060884,0.879243,-0.761526,0.149830,0.473015,0.371570,-0.635404,0.281602,-0.014703,0.190336,-0.264963,-0.080020,-0.015825,0.415346,0.340020,0.531896,0.338783,-0.131785,-0.184486,-0.034839,0.485699', '1301022', '1292219', '1307146', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293530', '角斗士', '剧情', '马克西·蒙斯（罗素·克劳 饰）是罗马帝国战功显赫，受人拥戴的大将军。老国王马库斯·奥利利乌斯（理查德·哈里斯 饰）对大将军赏识有加，有意加冕于他。老国王对将军这种超越亲情的宠爱自然招来太子康莫迪乌斯的妒忌与不安，太子伺机杀害父亲，抢先登上王位，并马上下令诛杀大将军一家。马克西蒙斯死里逃生躲过暴君的魔爪，可是他所有的家人都未能幸免于难，返回家园，他只看到满目疮痍的破败景象。走投无路的马克西蒙斯只能投身为奴，从昔日的大将军沦为一名角斗士，在血腥厮杀中苟且求生。凭借英勇的气魄和高超的武艺，马克西蒙斯渐渐脱颖而出，晋级到罗马的大角斗场。这一次，他的剑直指暴君康莫迪乌斯，失去亲人的痛苦，沦为奴隶的屈辱，在马克西蒙斯的内心燃起了熊熊怒火。©豆瓣', '罗素·克劳', '雷德利·斯科特', 8.5, 208440, 'tt0172495', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1601948450.jpg', 0.1, 0.7, 12.4, 45.1, 41.7, '-0.056216,0.191304,-0.687236,0.569909,-0.068104,-0.514656,0.725669,0.295649,-0.458932,-0.105617,0.689094,0.896071,0.046431,0.060963,0.253152,0.030104,-0.067119,-0.606797,-0.047514,0.020935,0.150637,-0.456395,-0.414987,-0.285450,-0.279091,-0.582437,0.750740,-0.006602,-0.133705,0.443386,0.433421,0.320503,0.320068,0.459078,-0.220521,0.177507,0.218808,-0.391642,-0.546886,0.036815,-0.104112,-0.126649,-0.379873,0.188832,-0.184357,0.087523,0.307505,-0.471915,0.142702,-0.273865,0.282727,-0.366256,0.105732,0.580819,0.069104,-0.077039,-0.163844,0.246662,0.117463,-0.056830,-0.087455,0.092441,-0.795384,-0.035500,-0.134083,0.141150,-0.547747,0.610674,-0.310837,-0.062719,0.209696,-0.314996,0.111865,0.007488,-0.236734,0.362338,-0.437605,0.070527,-0.616493,-0.024279,0.688338,-0.097079,-0.398606,-0.205005,0.085346,-0.171017,0.328622,-0.530269,-0.572424,-0.211388,0.520201,-0.027939,0.229193,0.811546,-0.412847,-0.253677,-0.791171,-0.065879,0.050856,-0.330155,-0.052974,-0.336498,-0.375528,-0.174743,-0.170724,0.018804,0.311393,-0.275568,0.580654,-0.547552,0.387872,0.126759,0.127099,-0.367598,0.306928,0.118742,0.182827,0.078833,-0.461187,0.584312,0.397420,0.285188,0.045014,0.097792,-0.132270,-0.174517,-0.319780,0.507229', '1482099', '1303034', '25828589', '1293945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293531', '第五元素', '动作', '一头红发，perfect的“第五元素”莉露(Milla Jovovich饰)受命来到地球，她要协助人类与每隔五千年降临一次的邪恶力量对抗，联合风、火、水、土四块神石击退敌人。在实验室被复制出来后，言语不通的莉露在躲避人类的追捕中搭上了退役特工科本（Bruce Will is饰）的出租车。科本带莉露找到了负责接头的神父，两人也渐渐的产生了好感。莉露与科本一同前往一个叫“失落天堂”的星球找寻另外四种元素的神石。但是，在战斗中莉露受伤昏迷，而且由于人类的暴行和无知杀戮，莉露陷入了内心的迷惘。大敌当前，科本究竟用什么力量才能唤醒莉露呢？©豆瓣', '布鲁斯·威利斯', '吕克·贝松', 8, 192183, 'tt0119116', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2217639745.jpg', 0.4, 2, 21.9, 48.6, 27.1, '0.189634,0.290045,-0.680553,0.540948,0.221435,-0.073115,0.587314,-0.011364,0.009388,-0.249853,-0.077410,0.666170,-0.061335,0.277609,0.146074,-0.020897,-0.155028,-0.403916,0.076094,-0.076424,-0.706527,-0.341908,-0.519225,-0.305921,0.067022,-0.790985,0.664152,0.178845,-0.264788,0.265343,0.039721,0.440268,-0.305698,0.344528,-0.205527,-0.256274,-0.046358,0.103923,-0.181027,0.363788,-0.152777,-0.150732,0.152883,0.170957,-0.197187,0.345788,0.869520,-0.444231,0.144286,-0.029103,0.208804,-0.520539,-0.133401,-0.168160,0.429329,0.094718,-0.222697,-0.114933,-0.051161,0.253454,0.148552,-0.021954,-0.844758,-0.140582,-0.124294,0.057977,-0.628012,0.341205,0.225191,-0.004487,-0.035273,-0.226476,0.110841,0.420450,-0.081180,0.334486,-0.312801,-0.158858,-0.479795,-0.256425,0.552745,-0.327416,-0.171816,0.302731,-0.259321,-0.548687,-0.192090,-0.277603,-0.068273,-0.310695,0.344058,0.220042,-0.037979,0.069733,-1.174610,-0.160789,-0.249535,-0.044495,-0.237733,-0.355793,0.001183,-0.456162,-0.325865,-0.234913,-0.237614,0.190657,0.445478,0.093879,0.543142,-0.813891,0.256138,0.503612,0.465563,-0.509796,0.329926,0.044505,-0.124619,-0.147486,-0.068903,0.419804,0.175390,0.515169,0.273155,0.435104,0.065702,0.411522,-0.488457,0.316053', '26290398', '25774050', '7056398', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293537', '空军一号', '剧情', '俄美两国策划一起反恐行动，派出特种部队擒获了掌握核武器的哈萨克王国独裁者伊万•雷迪克将军（Jurgen Prochnow 饰）。数周后的庆功宴上，曾为越战老兵的美国总统詹姆斯•马舍尔（哈里森•福特Harrison Ford 饰）针对恐怖分子和独裁政权发表了强硬而精彩的演说。莫斯科之旅圆满结束，总统一家及其政要乘空军一号返回美国，同行的还有艾格（加里•奥德曼 Gary Oldman 饰）带队的俄罗斯媒体工作人员。安全人员百密一疏，艾格的真实身份是效忠于雷迪克将军的恐怖分子。飞机起飞后，艾格和同伴们劫持飞机，绑架美国政要及总统家人，只有詹姆斯侥幸逃脱。恐怖分子要求俄美释放雷迪克将军，而藏身空军一号中的詹姆斯则和这群匪徒展开殊死决斗……©豆瓣', '哈里森·福特', '沃尔夫冈·彼德森', 7.5, 71414, 'tt0118571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2143835793.jpg', 0.5, 2.6, 32.6, 48.8, 15.5, '0.229737,-0.297218,-0.538294,0.636847,0.209760,-0.153506,0.321648,0.029975,-0.382123,-0.221483,0.480415,0.759212,0.049728,-0.251972,0.687144,0.071253,-0.902554,-0.717476,-0.110339,0.184741,-0.074842,-0.808810,-0.269519,-0.600432,0.057411,-0.263732,0.469112,0.240431,-0.173564,0.696045,0.410500,0.305555,-0.140018,0.184940,0.147213,-0.264171,0.480066,-0.543175,-0.614078,0.204419,-0.125573,0.120396,-0.116249,-0.039956,0.435876,0.531235,0.354801,-0.315657,0.441521,-0.453788,0.096764,-0.571327,0.255887,0.122608,0.436794,0.123191,0.091695,0.186611,0.280547,-0.037900,-0.042470,0.078391,-0.378388,0.251617,-0.209732,0.036696,-0.345550,0.325632,-0.598663,0.457580,0.058426,0.111847,0.167425,0.529825,-0.003000,-0.108452,0.261039,0.030216,-0.413795,-0.031067,0.608129,-0.118323,-0.246296,-0.427636,-0.077755,-0.343912,0.206102,-0.386186,-0.182794,-0.124305,0.364738,-0.350294,0.244650,0.424290,-0.508077,-0.199373,-0.575934,-0.173469,-0.083801,-0.170343,0.131048,-1.334870,0.041135,-0.076584,0.002292,-0.075520,0.213123,0.158373,0.575293,-0.447180,0.054695,0.311731,0.398205,-0.467488,0.494269,0.224746,0.216890,-0.233848,-0.211398,0.043623,0.315189,0.184120,-0.061677,0.096166,0.082438,-0.350868,0.175198,-0.124138', '6517421', '1293572', '2075345', '3036464');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293540', '007之最高机密', '动作', '英国军方一艘绝密的间谍船在希腊发生了爆炸，船上有一个威力无比的发射机（据说它可以使整个北极星飞弹系统全部报废）沉入了海底。这下，不仅英国军方，还有世界各地的间谍、恐怖分子都开始蠢蠢欲动。于是，007邦德（罗杰•摩尔 Roger Moore 饰）出动了，他的任务就是尽快毁掉这台发射机。同一时候，哈维洛克先生在寻找这项装置时不幸被人刺杀身亡，他的女儿美琳娜（卡洛尔•布盖 Carole Bouquet 饰）试图千方百计想帮父亲报仇。邦德说服了美琳娜协助他潜入海底从沉船里取出了发射机。不幸的是，两人浮出水面被敌人抓住了……©豆瓣', '罗杰·摩尔', '约翰·格兰', 7.1, 8382, 'tt0082398', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1733417268.jpg', 0.6, 3.9, 48.1, 35.3, 12.1, '0.103104,0.142012,-0.648861,0.372648,-0.135497,-0.006628,0.510360,-0.133543,-0.447884,0.195546,0.288735,0.688772,0.106212,-0.265351,-0.146831,0.288790,-0.659632,-0.586699,0.054065,-0.218998,-0.431011,-0.521426,-0.578186,-0.233638,0.175060,-0.457722,0.397774,-0.042668,-0.078499,0.144141,0.072631,0.530990,-0.066660,0.517080,-0.085631,-0.059454,0.191821,-0.447354,-0.049087,0.418758,-0.315837,-0.271847,0.391011,0.216148,-0.080742,0.445376,0.586742,-0.159174,0.264710,-0.195899,0.038337,-0.457866,0.023588,0.127449,0.346752,0.095805,-0.314905,-0.026306,-0.507495,-0.099963,0.571841,0.194523,-0.607537,-0.102681,0.074707,0.021608,-0.361593,-0.057308,-0.503680,0.254877,0.039407,-0.180850,0.480063,0.333963,0.136651,-0.041884,-0.126295,0.211778,-0.596159,0.171520,0.605326,-0.305493,-0.168946,0.023903,0.130688,-0.377713,0.015471,-0.121698,0.073128,-0.149904,0.919503,-0.083896,-0.136388,0.186485,-0.632278,-0.091406,-0.541524,-0.347532,-0.261874,-0.261299,-0.210138,-0.605428,-0.037028,0.029762,-0.081533,0.065134,-0.138971,-0.012935,0.700783,-0.499456,0.186862,0.774870,-0.008554,-0.269803,0.378139,-0.102870,0.179608,-0.166404,0.115437,-0.156742,0.133685,0.648615,0.078657,0.340997,0.162964,-0.249652,-0.491704,0.157212', '1300324', '1410557', '1301345', '26665875');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293544', '沉默的羔羊', '剧情', '联调局学院学员 Clarice M. Starling（乔迪·福斯特 饰）受行为科学组的 Jack Crawford（斯科特·格伦 饰）指派，前往州立巴尔的摩法医院访问被监禁的精神科医生 Hannibal Lecter（安东尼·霍普金斯 饰）。Lecter要求转到条件较 好的联邦机构，远离常常折磨他的 Frederick Chilton 医生（安东尼·希尔德 饰），并愿意为此提供持续作案的连环杀手水牛比尔（泰德·莱文 饰）的心理分析……©豆瓣', '朱迪·福斯特', '乔纳森·戴米', 8.9, 821557, 'tt0102926', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1593414327.jpg', 0.1, 0.4, 7.7, 37.9, 53.8, '0.303371,-0.396615,-0.144922,0.509179,0.000067,-0.249415,0.095533,0.382900,-0.634370,-0.211147,0.333990,0.216265,-0.015137,0.004448,0.460010,-0.042447,-0.625674,-0.227268,0.184625,-0.137008,-0.223998,-0.780337,-0.060985,-0.454956,0.059111,-0.618870,0.290832,-0.274016,0.021234,0.205281,0.130493,0.801640,0.165322,0.044790,0.422685,-0.095386,0.645947,-0.451568,-0.404242,0.431493,0.085782,0.178482,0.036529,-0.199240,0.426433,0.419947,0.536261,0.014156,0.061784,-0.265784,0.224444,-0.062099,0.050356,0.148546,0.339887,0.183282,0.052485,0.479828,-0.175832,0.374344,0.095420,-0.195865,-0.355151,0.156336,0.456214,0.081964,-0.303753,0.396600,-0.516354,0.399302,-0.350499,-0.144426,-0.288398,0.131423,0.269394,0.152541,0.199679,-0.002153,-0.126088,0.237757,0.110019,-0.322374,-0.411780,-0.203461,-0.386820,-0.603170,-0.090676,-0.118739,-0.035804,-0.116886,0.295753,-0.414337,0.118343,0.093512,-0.217645,-0.233354,-0.666368,-0.330518,-0.272001,-0.148869,0.284005,-1.088642,0.492191,0.053675,-0.242595,0.015068,0.118958,0.034293,0.123741,-0.684246,0.183745,0.742279,0.221053,-0.297478,0.366341,-0.013419,0.265043,-0.397015,-0.348482,0.467204,0.333580,0.522344,-0.057505,0.329388,0.153375,-0.390524,-0.060678,-0.009335', '1293572', '2369549', '6517421', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293555', '电子情书', '喜剧', '乔（汤姆•汉克斯 Tom Hanks 饰）和凯瑟琳（梅格•瑞安 Meg Ryan 饰）是生意上的竞争对手。凯瑟琳经营着母亲留下来的小书店，那里温馨宜人，已有40年历史，为街坊所熟知。乔却是同街一间大书店的老板，凭着自身优势，一开业就搞低折扣、服务佳的策略。凯瑟琳十分排斥他的入侵，白天二人展开斗法。不料晚上却在互联网的虚拟时间中结为挚友，不知道彼此身份的夜谈，让他们感情迅速升温。虽然他们都有自己的情侣，但网络中倾心的交往令他们决定要出来见见面。然而就在此时，乔却意外知道了这个网上知己的真实身份，从此对凯瑟琳有了全新的认识，暗暗忖度该如何接近佳人……©豆瓣', '汤姆·汉克斯', '诺拉·艾芙隆', 7.8, 98547, 'tt0128853', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p469986867.jpg', 0.2, 1.5, 26.7, 49.2, 22.4, '0.358359,0.198655,-0.741429,0.626688,0.158628,-0.219337,0.612479,0.005593,-0.541077,-0.342011,-0.055346,0.747129,-0.369745,0.446486,0.082496,0.072341,-0.306585,-0.666934,0.027877,-0.338572,-0.079585,-0.596895,-0.494948,-0.251725,-0.184405,0.235598,0.227848,0.207153,-0.270016,0.499471,0.221033,-0.103679,-0.068932,0.729024,0.031871,-0.018704,0.027565,0.125417,-0.458573,-0.063733,0.261577,-0.073055,-0.143620,0.125737,0.220107,0.464720,0.425084,-0.208839,-0.332874,0.197590,0.460021,0.017851,0.067446,0.073301,0.440572,0.005567,0.180792,-0.142221,-0.251823,0.116655,-0.074852,0.026178,-0.695927,0.251531,0.166181,-0.019945,-0.492601,0.502269,-0.069998,-0.067095,-0.109478,-0.238136,0.022735,0.442774,0.399478,0.301068,-0.026343,-0.046178,-0.499748,0.056677,0.647164,0.341656,-0.178241,0.486194,-0.599852,-0.538926,-0.255300,-0.213800,-0.324814,-0.329754,0.186776,0.266039,0.067534,0.170351,-0.403318,-0.004832,-0.065335,0.022200,0.075979,-0.443191,0.125798,-0.631811,-0.503188,-0.717725,-0.330889,0.132314,0.169748,-0.461533,0.809121,-1.044285,-0.143991,0.414540,0.495459,-0.647906,0.803631,0.187236,0.189447,-0.231707,-0.198171,0.006263,-0.211688,-0.003285,0.167001,0.298075,0.172512,-0.118528,-0.426285,0.444636', '1303112', '1292219', '1438708', '1297052');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293564', '木兰花', '剧情', '汤姆·克鲁斯凭此片获金球奖最佳男配角奖。主持吉米（菲利浦·贝克·霍尔 Philip Baker Hall 饰）患癌症时日无多，女儿陷入对邻居的狂热迷恋，妻子对此无能为力，吉米不知如何将自己的情况告诉女儿。吉米节目的嘉宾斯坦利（杰瑞米·布莱克曼 Jeremy Blackm an 饰）马上就能打破由唐尼（威廉姆·H·梅西 William H. Macy 饰）30年前创下的纪录，却不知唐尼只能在电器店打工。帕特里奇爵士（杰森·罗巴兹 Jason Robards 饰）病入膏肓，年轻的妻子琳达（朱丽安·摩尔 Julianne Moore 饰）当初为钱嫁给他如今却真心爱上老人，悔不当初。护理医生菲尔（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）把老人离家出走多年的爱子弗兰克（汤姆·克鲁斯 Tom Cruise 饰）带到家希望他谅解父亲......', '朱丽安·摩尔', '保罗·托马斯·安德森', 8.2, 29345, 'tt0175880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189098969.jpg', 0.8, 2.5, 17.7, 43.9, 35.1, '-0.256628,0.010686,-0.289563,0.209270,-0.226403,-0.736050,0.474236,0.106023,-0.423936,-0.557544,0.226632,0.694017,-0.107397,0.361377,0.379453,0.268302,-0.479741,-0.374906,0.323253,-0.010945,0.114118,-0.734793,-0.242206,-0.541329,-0.098694,-0.444650,0.260430,-0.194776,0.243365,0.133006,0.652169,0.645935,0.282202,0.054998,0.237279,0.348170,0.364853,-0.172204,-0.660053,0.227351,0.127101,0.103791,-0.121939,0.057387,0.262668,0.268415,0.377618,-0.258849,0.237973,-0.065133,0.290456,0.079868,0.139116,0.151172,0.036637,-0.236123,0.055726,-0.009904,-0.257743,-0.142869,0.181619,-0.052765,-0.300272,0.230118,0.059863,0.329859,-0.374954,0.038892,-0.710821,0.174361,0.024463,-0.200099,-0.154781,0.037974,0.234839,0.289424,0.095103,0.170666,-0.248885,0.146917,0.315645,0.003692,0.047682,0.165549,-0.444807,-0.320208,0.221098,-0.213841,-0.781835,0.242439,0.277947,-0.063185,0.282394,0.482397,0.228287,-0.492708,-0.417928,0.040362,0.005641,-0.197383,0.011034,-0.339032,0.027931,0.109032,0.051814,-0.208531,-0.084007,-0.298780,0.447542,-0.364125,0.290646,0.141655,0.111597,-0.215004,0.577999,0.095509,0.177505,-0.556001,-0.365636,0.636092,-0.006868,-0.242452,0.264288,-0.089187,0.311415,-0.304976,0.003029,0.284299', '26856202', '3147941', '2213591', '2255476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293566', '不可饶恕', '剧情', '堪萨斯的农民威廉（克林特·伊斯特伍德 Clint Eastwood ）年轻时曾是出名的杀手和劫匪，然而当遇上了克劳迪亚后，他的生活开始彻底改变。威廉和克劳迪亚结婚生子后，洗手不干，一家人过着幸福的生活。好景不长，克劳迪亚不久故去，威廉独立带着两个孩子过着清贫宁静的生活。这时，该地区发生了一起牛仔醉酒殴打妓女并将其毁容的恶性事件，坏蛋警长达格特（吉恩·哈克曼 Gene Hackman 饰）只将此事草草了结，凶手仍逍遥法外。当地妓女纷纷捐钱，要求悬红1000美金请杀手来伸张正义。“思科菲尔德小子”找到威廉，要求合伙干这票买卖。为了给孩子们一个幸福富足的家庭，威廉终于答应再次出山。©豆瓣', '克林特·伊斯特伍德', '克林特·伊斯特伍德', 8.5, 68413, 'tt0105695', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1083392613.jpg', 0.2, 0.8, 11.8, 47.6, 39.6, '0.269096,-0.090598,-0.313874,0.121401,-0.331340,-0.710149,0.546548,0.085461,-0.462223,-0.417422,-0.069468,0.736425,-0.006035,0.379576,0.366208,0.226214,-0.518716,-0.590804,-0.055820,-0.127905,-0.096030,-0.454895,0.129310,-0.281774,-0.292413,-0.130761,0.177695,-0.125434,0.362034,0.394201,0.409962,0.260072,-0.060919,0.210982,-0.297665,0.103410,0.155573,-0.216172,-0.790398,0.055151,-0.106653,0.107449,-0.127782,-0.107067,0.259398,0.100604,0.368884,-0.175029,0.026371,-0.322461,0.152099,0.000153,0.016114,0.107343,0.150607,-0.064568,0.238189,0.377117,-0.106195,-0.157226,0.118257,-0.340981,-0.304240,0.172843,-0.085150,-0.030492,-0.521851,0.119367,-0.149918,0.142763,0.130240,-0.188166,-0.034449,0.421833,0.166851,0.343288,-0.125600,0.400490,-0.592501,0.314965,0.801774,0.034791,-0.115416,-0.031501,-0.191173,-0.421488,0.269739,-0.388348,-0.491838,0.222644,0.371433,-0.124427,-0.267516,0.506807,-0.467045,-0.182616,-0.580311,-0.024870,0.102393,-0.059593,-0.183329,-0.504792,-0.077921,-0.019610,-0.548533,0.100455,-0.085558,-0.133538,0.380882,-0.604216,0.373968,0.535002,0.423548,-0.263528,0.415300,0.232794,0.349652,-0.060051,-0.103890,0.316940,0.260608,0.290007,0.284598,0.042068,-0.063525,-0.140871,0.142040,0.389570', '1297239', '1308035', '1907467', '26393561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293572', '2010', '科幻', '《2001太空漫游》后9年，前国家航天委员会主任弗洛伊德博士（罗伊•谢德 Roy Scheider 饰）接受苏美合作计划，带领发现号航天站设计者科脑博士（约翰•利思戈 John Lithgow 饰）和HAL9000电脑的创始人钱德拉博士（鲍勃•巴拉班 Bob Balaban 饰）登录木星附近的苏联航空站，与苏联宇航员卡布珂（海伦•米伦 Helen Mirren 饰）等合作，空中接轨美国发现号航天站，调查九年前的事故原因，探索木卫二的神秘黑石，并查明宇航员大卫•伯曼（凯尔•杜拉 Keir Dullea 饰）缘何神秘失踪。然而任务执行尚未过半，美苏关系愈发紧张，战争一触即发；与此同时，大卫•伯曼竟突然现身对弗洛伊德博士发出神秘警告。本片改编自亚瑟•克拉克的小说《2010太空漫游》，获第59界奥斯卡最佳艺术指导—布景，最佳服装设计，最佳视觉效果，最佳化妆和最佳声效五项提名。', '罗伊·谢德', '彼得·海姆斯', 8, 14889, 'tt0086837', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1209728783.jpg', 0.5, 2.5, 21.6, 48.6, 26.8, '0.086744,-0.057448,-0.596770,0.433501,0.452543,-0.332049,0.074617,-0.027083,-0.293081,-0.434717,0.160028,0.501123,-0.201809,-0.176193,0.378553,0.178606,-0.795109,-0.382042,-0.029519,-0.264498,-0.153838,-0.722752,-0.165412,0.106624,-0.033365,-0.404907,0.664502,-0.329997,-0.105222,0.789148,0.235525,0.412958,-0.187792,0.113659,0.350759,-0.264123,0.882082,-0.230337,-0.604661,0.408461,-0.135011,0.130123,0.107716,-0.011760,0.152714,0.234815,0.413434,-0.251840,0.153274,-0.127660,0.421006,-0.119298,-0.018272,-0.070242,0.405395,0.105025,-0.065376,0.297191,-0.037225,0.078975,-0.115907,-0.088171,-0.312337,0.064654,0.073731,0.210922,0.009546,0.022856,-0.435723,0.194110,0.090780,0.048664,0.207634,0.520077,0.552935,0.076283,0.086708,0.247875,0.162790,0.232359,-0.120779,-0.200092,-0.346316,0.092380,0.308799,-0.528663,0.056197,0.138582,-0.188058,0.122134,0.057892,0.014032,0.234714,0.316644,-0.542386,0.228179,-0.496110,-0.254125,0.030967,0.094413,-0.016645,-1.340658,-0.146712,0.045936,-0.185493,-0.185969,-0.124208,-0.164214,0.321292,-0.389415,0.370819,0.398248,0.112975,0.001336,0.378276,-0.015071,0.155476,-0.733547,-0.089777,0.293395,0.033864,0.429334,-0.529762,0.213440,0.348684,-0.471998,-0.156081,-0.052891', '2075345', '6517421', '34961898', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293582', '猎人之夜', '惊悚', '约翰（比利·查平 Billy Chapin 饰）和佩尔（萨莉·简·布鲁斯 Sally Jane Bruce 饰）是一对苦命的兄妹，他们的父亲本（彼得·格雷夫斯 Peter Graves 饰）因抢劫和被判处绞刑。在被逮捕前，本把赃款藏在了佩尔的布娃娃里，并让他们承诺永远不泄露这个秘密。本的狱友哈利（罗伯特·米彻姆 Robert Mitchum 饰）是一个败絮其中的牧师，偶然间他得知了这笔赃款的去向，出狱后，哈利找到了本的妻子薇拉（谢利·温特斯 Shelley Winters 饰），他想方设法得到了薇拉的芳心成为了约翰和佩尔的继父，就此，哈利的阴谋开始了。哈利杀死了对于他来说毫无价值的薇拉，将他弃尸河底，又对兄妹两人威逼利诱想要套出赃款的秘密。在所有努力都没有成果之际，恼羞成怒的哈利露出的本来面目。约翰和佩尔划着小船逃离了哈利，他们一路流浪来到了一个陌生的小镇，专门收养弃婴的善良妇人理查德（丽莲·吉许 Lillian Gish 饰）收留了兄妹两，然而平静的生活没过多久，哈利罪恶的脚步也踏上了这块纯洁的土地。', '罗伯特·米彻姆', '查尔斯·劳顿', 8, 8381, 'tt0048424', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2364119369.jpg', 0.6, 2.6, 21.9, 48.1, 27, '0.428257,-0.076075,-0.613311,0.394732,-0.374709,-0.376518,0.836934,0.152240,-0.259158,-0.018085,0.104169,0.897602,-0.167882,0.028386,0.268154,0.363418,-0.607152,-0.800896,0.006831,-0.441962,-0.101360,-0.637148,-0.095859,-0.314233,-0.226685,-0.184016,0.341820,0.001379,0.018823,0.556332,0.263737,0.410319,-0.015821,0.281814,-0.314894,0.325003,0.137581,-0.219578,-0.007536,0.289621,0.074491,-0.153154,-0.057418,0.268007,-0.065936,0.584124,0.768927,-0.615155,0.122919,0.046903,0.076277,-0.433585,0.114976,0.202614,0.129547,-0.218335,-0.017608,0.357812,-0.437950,0.012536,0.520598,-0.180107,-0.628339,0.026935,-0.095829,0.079875,-0.762385,0.491557,-0.168945,0.132513,0.177879,-0.287153,0.263171,0.408801,0.001558,0.219634,-0.166600,0.132800,-0.651945,-0.020314,0.330454,-0.169355,-0.014720,0.309252,-0.309511,-0.406952,0.033761,-0.150256,-0.411588,-0.170786,0.810786,0.043525,-0.284069,0.164188,-0.709507,-0.331829,-0.542244,-0.071241,-0.010131,-0.451385,-0.269638,-0.380092,-0.112784,-0.460133,-0.324635,-0.189718,-0.126831,-0.220703,0.638023,-0.549408,0.297825,0.432044,0.231128,-0.478792,0.566776,0.046454,0.317358,0.051939,-0.081397,0.270606,0.297935,0.588002,0