INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293590', '欲望号街车', '剧情', '本片改编自著名剧作家田纳西·威廉斯的同名戏剧。徐娘半老风味犹存的“南部美女”白兰芝（费雯丽）因“不适当”的行为被解除家庭教师职务后，来到新奥尔良投靠妹妹。妹妹家在一栋肮脏的公寓内，其丈夫斯坦利（马龙·白兰度）是波兰移民的儿子，性格粗鲁莽撞，且酗酒嗜赌。因为从小娇生惯养 ，受过旧式的南方教育，白兰芝多少有些神经质，她认为斯坦利是个很没教养的人，而斯坦利也正因为她所表现出的娇弱敏感，认为她会带坏自己的妻子，甚至威胁到他作为家中主人的地位，对她时常加以言语侮辱以示憎恶。在这样的环境中，白兰芝的悲剧一点点展开。©豆瓣', '费雯·丽', '伊利亚·卡赞', 8.4, 43161, 'tt0044081', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177784348.jpg', 0.3, 1.1, 13.9, 47, 37.7, '0.352436,0.163402,-0.683805,0.649724,-0.380509,-0.041496,0.745895,0.170561,-0.744704,-0.286432,0.290919,0.881878,-0.030307,0.189439,0.106646,0.142884,-0.020546,-0.356280,-0.327204,-0.011766,-0.102604,-0.391524,-0.029538,-0.326545,-0.184799,-0.365807,0.416473,-0.112283,-0.373408,0.043131,0.196066,0.442931,0.074474,0.322441,-0.204775,0.125890,0.009731,0.039512,-0.144012,0.200188,0.179899,0.006384,0.046601,0.225778,-0.032011,0.350857,0.598650,-0.292255,-0.295233,-0.381612,0.571417,-0.171688,-0.000872,0.331496,0.319804,-0.323893,0.395149,0.050609,-0.345012,0.224242,-0.083328,-0.153376,-0.428369,-0.047367,0.205154,0.128412,-0.636277,0.544209,-0.017375,-0.297041,-0.063317,-0.323770,0.012274,-0.060869,0.090035,0.388357,-0.138226,0.128927,-0.351413,-0.010185,0.475507,0.064082,-0.182132,0.158656,-0.499007,-0.219026,0.379428,-0.638508,-0.656478,-0.211537,0.058068,-0.185668,-0.061926,0.169776,-0.318788,-0.106513,-0.179941,0.098663,-0.078579,-0.534454,-0.082568,-0.247197,-0.151493,-0.832395,-0.182976,-0.251814,0.255131,-0.423609,0.534338,-0.965948,0.091111,0.400261,0.361948,-0.634194,0.303965,0.288120,-0.002070,-0.143950,-0.337046,0.641086,0.015881,-0.171610,-0.022834,0.350524,0.049364,-0.335345,0.181094,0.551714', '1308635', '1308314', '2251924', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293596', '离开拉斯维加斯', '剧情', '本（尼古拉斯•凯奇 Nicolas Cage  饰 ）一个是贫困潦倒的编剧，终日借酒消愁，被公司开除后，郁郁不得志的他变卖了所有的家当，前去拉斯维加斯开始了他慢性自杀的计划。他打算在几周的时间内，喝酒至死。在光怪陆离的拉斯维加斯，醉醺醺的他遇见了妓女莎拉（伊丽莎白•苏 Elisabeth Shue  饰）。莎拉过着同样不幸的生活：被皮条客控制自由，屡次出逃不遂。本和莎拉共度了一夜，这夜他们互相倾诉，同是天涯沦落人。二人很快同居，但莎拉并不阻止本继续狂饮。本在自己的世界里沉溺得越来越深，直到有一天和另一个女人躺在莎拉床上，莎拉怒不可遏，将本赶出家门。本在酒精的折磨下奄奄一息，他打电话给莎拉，能否让生命和感情重生。©豆瓣', '尼古拉斯·凯奇', '迈克·菲吉斯', 8.1, 35155, 'tt0113627', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494188239.jpg', 0.5, 2.5, 20.5, 46, 30.6, '0.071968,0.370385,-0.914059,0.223511,-0.326580,-0.249462,0.763935,0.087826,-0.426560,-0.215679,0.005097,0.778927,-0.274852,0.454932,0.482844,0.068251,-0.419822,-0.707530,-0.047884,-0.144457,-0.356529,-0.539060,-0.094674,-0.270821,-0.119026,-0.129563,0.322505,-0.029457,-0.050924,0.295157,0.169883,0.233816,-0.018782,0.700054,-0.252055,0.311963,0.070426,-0.123986,-0.106464,0.233344,0.295549,-0.412625,-0.118141,0.015795,0.076679,0.182305,0.549051,-0.302388,-0.153224,-0.209063,0.173065,-0.266399,-0.209979,0.168223,0.018782,-0.244613,0.169305,0.142784,-0.423911,0.034888,0.299050,0.188510,-0.523150,0.086757,-0.156333,0.002247,-0.609574,0.666579,-0.047123,0.089772,0.092452,-0.209812,0.078181,0.522195,0.008235,0.219100,-0.183099,0.026375,-0.843648,0.317797,0.804115,0.201369,-0.085527,0.437384,-0.105089,-0.126828,-0.011685,0.018813,-0.385325,-0.374459,0.545229,0.023153,-0.475445,0.236296,-0.642683,-0.020398,-0.258477,-0.074232,-0.155793,-0.341583,-0.054311,-0.500285,-0.162356,-0.332340,-0.312280,-0.091554,0.130719,-0.272096,0.487723,-0.632269,0.416844,0.489393,0.245917,-0.560132,0.594062,0.574436,0.288081,0.356222,0.042278,0.473727,0.102687,0.457044,0.407273,0.356712,-0.032389,0.275702,-0.729261,0.412895', '2365079', '1866424', '27053945', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293603', '法国中尉的女人', '剧情', '维多利亚时代的英国小镇莱姆，年轻的绅士查尔斯（杰里米艾恩斯 Jeremy Irons 饰）在海边的悬崖上邂逅了一个神秘黑衣女子（梅丽尔斯特里普 Meryl Streep 饰）。听当地人说，黑衣女子名叫萨拉，因为曾与一名法国中尉有染，所以遭众人非议，被称为“法国中尉的女人”。不过，查尔斯却对这位遗世独立的女人颇感兴趣，尽管他已经有了一个贤淑的未婚妻，并拟定了婚期，但他还是抑制不住萨拉的诱惑。两个人在几次试探后，终于开始幽会。萨拉对查尔斯讲述了她的遭遇和经历，但这一幕却被他人窥视，于是偷偷摸摸的私情面临公诸于众的危机……无独有偶，这段故事被改编成了同名电影，女主角萨拉的扮演者安娜与男主角查尔斯的扮演者迈克，也给戏中人一样，保持着若即若离的情人关系，只是结局却出人意料……©豆瓣', '梅丽尔·斯特里普', '卡雷尔·赖兹', 7.9, 18793, 'tt0082416', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1189962412.jpg', 0.3, 1.4, 23.9, 53.4, 21, '0.443085,0.059035,-0.683762,0.765271,-0.100571,-0.384725,1.059890,0.074664,-0.537776,-0.249035,0.392182,0.895671,-0.519472,0.093741,0.418898,0.251167,-0.324635,-0.734004,0.014225,-0.204724,-0.204067,-0.486740,-0.320215,-0.070806,-0.155669,-0.343862,0.460892,-0.051982,-0.203659,0.424301,0.540876,0.319707,0.086865,0.594653,-0.248315,0.068080,0.271787,-0.147517,-0.149762,0.221426,0.091453,-0.291211,-0.278081,0.249375,-0.297196,0.553962,0.356555,-0.328280,-0.136511,0.000005,0.308532,-0.141502,0.227151,0.243738,0.405185,-0.250067,0.143618,0.143504,-0.158565,-0.308303,0.100896,0.150965,-0.511557,0.299099,0.061757,0.330890,-0.600718,0.485646,-0.060005,-0.012889,0.076234,-0.087823,0.013015,0.178275,0.605618,0.295856,-0.007732,0.043970,-0.441775,0.102386,0.471194,0.226331,-0.379905,0.437030,-0.210080,-0.468671,-0.194324,-0.002445,-0.700636,0.044991,0.267011,-0.239164,-0.209150,0.324540,-0.595165,-0.013557,-0.398361,0.038337,-0.201442,-0.459687,-0.197122,-0.703071,-0.322155,-0.494157,-0.373885,-0.003504,0.141059,-0.065586,0.733021,-0.680379,0.232854,0.696940,0.158306,-0.471564,0.612464,0.445232,0.034307,-0.235521,-0.139646,0.468430,0.040931,-0.107288,0.189561,0.620679,-0.058880,-0.139295,-0.305806,0.585539', '30162520', '1309172', '1296534', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293605', '007之金枪人', '动作', '世界上又多了一个杀人不眨眼的冷血杀手，注定又将引起一场惊涛骇浪。绰号金枪人的职业杀手几乎百发百中，没有他完成不了的任务，由此成为世界各恐怖组织争相高酬聘请的对象。同一时间，英国军方为了取回可将太阳能95%转化的高效率太阳能转化器（万一这种厉害的武器落入恐怖分子手中后果不堪设想），007邦德（罗杰•摩尔 Roger Moore 饰）奉命出动了。恐怖组织为了阻止007的行动，高薪聘请了金枪人来对付007。最终鹿死谁手，007又能否顺利完成任务？©豆瓣', '罗杰·摩尔', '盖伊·汉弥尔顿', 6.7, 8583, 'tt0071807', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1741216684.jpg', 1.5, 7.3, 53.4, 28.4, 9.4, '0.042526,0.351370,-0.317357,0.346763,-0.394114,0.070743,0.337966,-0.318297,-0.153192,0.121682,0.208117,0.775096,0.149814,-0.570924,0.076192,-0.223895,-0.069284,-0.477844,-0.297227,-0.288498,-0.360112,-0.388452,-0.512944,-0.270585,0.146912,-0.261749,0.717762,0.070189,-0.183048,-0.096590,0.548611,0.512109,-0.029683,0.236780,-0.018659,-0.360097,0.056888,-0.035632,-0.271949,0.632240,-0.077481,-0.177653,0.123448,0.510768,-0.037434,0.261905,0.430289,-0.277871,0.083380,-0.510259,0.304649,-0.574574,0.060858,-0.023466,0.318916,0.241814,-0.092798,0.132165,-0.122787,-0.151447,0.360334,-0.079260,-1.326240,-0.150264,0.298533,-0.250016,-0.236517,-0.152037,-0.518570,0.080511,-0.389937,-0.105054,0.215856,0.399713,0.627768,0.083616,-0.167669,0.038787,-0.456206,0.350107,0.743299,-0.215163,-0.363634,0.092001,0.277179,-0.443463,0.008849,-0.690307,-0.083746,-0.063965,0.600370,0.122652,0.101362,0.270929,-0.536974,-0.009508,-0.522135,-0.197445,-0.016478,-0.182012,-0.026411,-0.472872,0.084268,0.282859,-0.185661,0.154943,0.312190,-0.159322,0.810334,-0.785702,-0.173550,0.808312,0.209052,-0.481645,0.157914,0.061482,0.217388,-0.288442,-0.049656,-0.174936,0.304291,0.749156,0.272183,0.205814,0.064892,-0.355550,0.145157,0.361775', '3718665', '27073234', '26678784', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293607', '算死草', '剧情', '著名状师陈梦吉（周星驰 饰）与徒弟何欢（葛民辉 饰）认识了女子水莲花（邱淑贞 饰），师徒两人都对水莲花有意思，刚好水莲花也欣赏陈梦吉的才华。这时陈梦吉的老婆吕忍（莫文蔚 饰）从国外读书归来，遇到了尴尬的场面。当何欢知道了师父的计谋后与陈梦吉反目成仇，独自到香港发展。陈梦吉找到了去香港的机会，却得知了何欢因为谋杀被囚禁，梦吉决定为徒弟打官司。法庭上的陈梦吉态度嚣张，被收监两天，他要求在外国学习法律的妻子帮忙，妻子才告诉他自己学习的是时装设计……©豆瓣', '周星驰', '马伟豪', 7, 95569, 'tt0133059', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2354806772.jpg', 0.9, 6.6, 46.5, 32.9, 13.1, '0.096372,0.050978,-0.688625,0.536555,-0.240263,-0.241416,0.356479,0.245091,-0.534107,-0.185461,0.063061,0.787354,-0.135330,0.146941,0.229857,0.090296,-0.079172,-0.872401,0.061256,-0.215087,-0.305022,-0.415815,-0.141031,-0.007958,-0.080317,-0.305379,0.203575,0.098490,-0.094838,0.512063,0.318029,-0.079921,-0.109481,0.377318,-0.150099,-0.087986,0.039372,0.359361,-0.258497,0.212930,0.030347,-0.391568,-0.051311,-0.068779,0.233564,0.342027,0.555894,0.186657,-0.215723,-0.028903,0.320377,-0.249845,0.023442,0.187444,0.335436,-0.081650,0.174288,0.238753,-0.339360,-0.073087,-0.076096,-0.193346,-0.491840,0.289797,0.078938,-0.070951,-0.858758,0.575278,-0.180655,-0.237279,-0.100198,-0.506355,0.230370,0.118926,0.202959,0.403069,-0.095448,0.090933,-0.438998,0.373267,0.542431,0.046581,0.310146,0.393946,0.090994,-0.391367,0.019219,-0.188198,-0.083466,0.089475,0.315349,-0.106931,-0.362502,-0.106209,-0.424294,-0.345187,-0.172042,0.161830,0.032402,-0.430614,0.062760,-0.351621,-0.091206,-0.215298,-0.367202,-0.077105,0.071794,-0.214133,0.842387,-0.721373,0.174035,0.535645,0.412368,-0.769555,0.852629,0.195137,-0.002006,-0.366125,-0.081213,-0.023280,0.157754,0.064922,0.171552,0.372073,0.150151,-0.244653,-0.280093,0.030225', '35048413', '1308609', '26958479', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293619', '赎金', '动作', '美国协力航空公司的总裁汤姆（梅尔·吉布森 Mel Gibson 饰）打拼多年获得令人瞩目的成绩，但最近却被一宗行贿工会案卷入，所幸美满的家庭总能及时给予他安慰。是日，汤姆一家三口参加一次儿童科学园游会，在纷乱的人流中，儿子肖恩被人掳走。劫匪很快打来了电话，向汤姆勒索两百万美金，同时绑架案处理专家朗尼带同FBI介入此案，劫匪头目是纽约警察吉米（Gary Sinise 饰），他高强的反侦破手段让警方一时无从下手，约翰配合警方安排却导致步步被动。心急如焚的约翰决定放手一搏，在媒体公开将赎金变为抓捕绑匪的悬赏，吉米针锋相对，双方展开了走钢丝般的心理较量。吉米团伙抵不过约翰强大的心理攻势出现了分裂，但是吉米又想出了新的对策，两名强硬男人之间的对决，究竟谁生谁负？©豆瓣', '梅尔·吉布森', '朗·霍华德', 7.3, 6656, 'tt0117438', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2208250260.jpg', 0.7, 2.3, 39.8, 46.4, 10.8, '0.284916,-0.079804,-0.385803,0.327479,-0.032906,-0.081082,0.361723,0.084395,-0.477201,-0.020755,0.364849,0.402255,-0.125377,-0.007082,0.230712,-0.285000,-0.202385,-0.793943,0.124899,0.044789,-0.042717,-0.523455,-0.357625,-0.372416,0.077291,0.015719,0.339972,0.081474,-0.141790,0.362033,0.375702,0.431230,-0.191389,0.330691,0.229374,-0.019087,0.442309,-0.212274,-0.332337,0.234017,0.129562,-0.339294,-0.233128,0.118497,0.098154,0.589495,0.396548,-0.006042,-0.147430,0.031006,0.432719,-0.371926,-0.170432,0.138164,0.453467,0.230071,-0.026754,0.283209,-0.212743,-0.148584,0.070628,0.106606,-0.663852,0.195276,-0.009995,0.043056,-0.542670,0.203397,-0.315927,0.216147,-0.153130,-0.289414,-0.047682,0.396772,0.270237,0.179400,0.098170,-0.047382,-0.424945,0.082726,0.667678,-0.019163,-0.229665,-0.201425,-0.223094,-0.436807,-0.081574,-0.465467,-0.168690,-0.052150,0.643463,-0.215348,-0.077466,0.226028,-0.344738,-0.121960,-0.560091,-0.061605,-0.189222,-0.404296,0.070499,-0.760287,-0.115413,0.125998,-0.300711,0.149145,0.077084,-0.216413,0.535699,-0.639881,-0.168514,0.819251,0.286958,-0.485832,0.384147,0.046559,0.063211,-0.125318,-0.100097,-0.160381,0.279398,0.162606,0.270264,0.164105,0.070798,-0.216774,0.066354,0.046392', '1307442', '1294181', '25723905', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293626', '最长的一天', '剧情', '影片描绘的是登陆诺曼底的第一天所发生的事件，所谓最长的一天是该片分别从盟军和德军双方面的角度同时描述诺曼第登陆这一历史战役的来龙去脉，以及双方在此期间的重要反应，手法平实，场面逼真，让整个事件在观众眼前重现。并且粗中有细，无论是决策的将军还是登陆的士兵都写得栩栩如生：英军战机低空飞过攻击；美国特种部队遭德军射击；一群法国修女冒着枪林弹雨抢救联军伤兵……', '理查德·伯顿', '肯·安纳金', 8.5, 12079, 'tt0056197', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204586557.jpg', 0.2, 0.8, 11.9, 45.8, 41.4, '0.127563,-0.218385,-0.741293,0.739659,0.553014,0.293890,0.424250,-0.493994,-0.343341,-0.090965,0.747921,0.544121,-0.359030,-0.177957,0.208341,-0.219991,-0.239091,-0.859959,-0.255452,0.185984,-0.363193,-0.438230,-0.386306,-0.436942,0.207621,-0.399976,0.636529,0.236839,-0.489986,0.249967,-0.056710,0.032697,-0.136690,0.213648,0.166650,-0.321486,-0.014411,-0.278506,-0.271458,0.039094,-0.160710,-0.414214,-0.261175,0.130648,-0.104270,0.455445,1.082511,-0.506097,-0.167603,0.106071,0.313809,-0.483493,0.070103,0.116240,0.545061,0.216218,0.143073,0.064115,0.331532,-0.028770,-0.306621,0.148374,-0.595687,-0.266594,0.023034,0.115452,-0.411684,0.283256,-0.479391,0.443370,0.222550,-0.250350,0.143323,0.501479,0.189242,0.426659,0.007725,0.130092,-0.382212,0.222397,0.617902,-0.010126,-0.513539,0.147263,-0.222310,-0.519452,-0.144546,-0.421833,0.038996,0.310193,0.404647,-0.422665,0.074335,0.410696,-0.522644,0.428191,-0.362459,-0.937337,-0.247848,-0.051375,-0.272225,-0.990987,-0.106527,-0.586275,-0.268710,0.212755,0.056413,0.293275,0.995647,-0.402640,-0.134963,0.411796,-0.303527,-0.178761,0.405586,0.405315,-0.061271,0.032920,-0.022248,0.136519,0.024265,0.351033,-0.183835,0.336477,-0.155334,-0.397936,-0.424190,0.254380', '5403927', '3811356', '25863940', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293632', '春天的故事', '剧情', '珍妮（Anne Teyssèdre 饰）是一名哲学老师，一日在宴会上，她与娜塔莎（Florence Dare 饰）相识，也许是因为寂寞，两个本无交集的人成为了朋友。娜塔莎邀请珍妮到自己家里做客，后者欣然前往。娜塔莎有一个奇怪的家庭，父亲离婚，交往了一个年龄和自己相差无几的漂亮女朋友伊芙（Eloïse Bennett 饰），这一点令娜塔莎无法接受，同时，一条项链的失踪也加深了她与“后妈”的隔阂。珍妮的介入让这个家庭里的关系发生了改变，娜塔莎的父亲显然对知性的珍妮抱有好感，而娜塔莎也渴望能和喜欢的珍妮组成新的家庭。对于娜塔莎的热情撮合，珍妮显得有些被动，她坚持听从自己内心的感情，不愿掺和到这个复杂的家庭中去。一次四人的乡村度假中，酝酿已久的矛盾终于激发了，娜塔莎同伊芙发生了争吵，而她吃惊的发现自己一直信任的珍妮居然站在敌人的那一边。她该怎么办？在这个春天里，友谊和爱情能否同时播下可以成长的种子呢？', '安娜·特塞德雷', '埃里克·侯麦', 8.4, 53588, 'tt0097106', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1715325088.jpg', 0.1, 0.5, 11.9, 54.6, 32.9, '0.633145,0.102870,-0.959805,0.667178,-0.292024,-0.251073,0.859615,0.067033,-0.439720,-0.134172,0.191928,0.799600,-0.216178,0.468311,0.171603,0.051757,-0.191346,-0.706998,0.212385,-0.092767,-0.317369,-0.680936,-0.300075,-0.237567,-0.152670,-0.188200,0.655360,-0.087555,-0.130541,0.732782,0.396654,0.295569,0.020409,0.592390,-0.080382,0.040696,0.110103,0.174417,-0.338757,0.121898,0.200035,0.100686,0.037410,0.395403,0.093376,0.500318,0.570745,-0.212126,-0.265534,0.093020,0.398283,-0.049567,-0.006357,0.234432,0.228715,0.016436,0.064505,0.122480,-0.350399,-0.048266,-0.071952,0.067495,-0.829080,0.128631,0.113254,0.257287,-0.618813,0.602157,0.041096,-0.427648,0.170164,-0.254618,0.151781,0.623494,0.212559,0.430894,-0.302209,0.048549,-0.426255,-0.080487,0.936596,-0.004210,-0.337289,0.561466,-0.521894,-0.173464,-0.169276,-0.060771,-0.721788,-0.017994,0.138630,0.122732,-0.218763,0.227664,-0.628266,0.036515,-0.255641,0.136040,0.103077,-0.634340,0.075398,-0.217857,-0.431093,-0.816029,-0.567707,-0.114674,0.017041,-0.355525,0.813485,-1.068916,0.087374,0.453388,0.498533,-0.719425,0.711100,0.515808,0.143396,-0.217499,-0.132104,0.324233,-0.357467,-0.090029,0.079728,0.445397,0.328169,0.098650,-0.428910,0.286839', '35030151', '1301022', '1292219', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293643', '蝴蝶君', '剧情', '1964年，法国驻华大使馆会计高仁尼（杰瑞米·艾恩斯）在观看歌剧时，被舞台上的蝴蝶夫人迷住了。戏毕，他主动向蝴蝶夫人的扮演者、京剧演员宋丽玲示好。一次次的接触，使两颗孤独的心相爱了。然而好景不长，文化大革命爆发，宋丽玲音信全无。1968年，宋丽玲来到法国，与高仁尼重聚。多年后，当高仁尼因间谍身份被指控时，站在证人席上的，是西装革履的宋丽玲。指男为女的高仁尼成为了全法国的笑柄。这两个男人将如何面对对方，如何面对他们的爱情？©豆瓣', '杰瑞米·艾恩斯', '大卫·柯南伯格', 8.4, 66055, 'tt0107468', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p770583467.jpg', 0.2, 1.2, 14.5, 45, 39.2, '0.318070,0.032843,-0.510032,0.592263,-0.038281,-0.402961,0.537164,0.090876,-0.489059,-0.006396,0.154396,0.856664,-0.601254,0.278471,0.386201,-0.043870,-0.189866,-1.054165,-0.259824,-0.068322,-0.367663,-0.250502,-0.075059,-0.114135,-0.187878,-0.223016,0.689554,0.091503,-0.049509,0.388553,0.617500,0.400785,0.003707,0.309581,-0.078582,-0.138878,0.434555,0.011868,-0.273641,0.449658,-0.038662,-0.636245,-0.267799,-0.032401,-0.398373,0.017905,0.723402,-0.151358,0.099696,-0.289167,0.515643,-0.441533,-0.019751,0.406386,0.115442,0.164326,-0.186668,0.191942,-0.294889,-0.208420,0.032766,-0.123244,-0.557590,0.067759,-0.090838,0.295320,-0.664991,0.577627,-0.164501,0.005275,-0.048090,-0.201873,0.207513,0.384852,0.252007,0.371157,-0.163229,0.105777,-0.376789,0.132482,0.970150,0.313893,-0.469559,0.223766,-0.045675,-0.491143,0.001773,-0.306529,-0.468117,-0.047353,0.225299,-0.038421,-0.011143,0.218020,-0.649871,-0.070861,-0.377059,-0.148081,0.186810,-0.457953,-0.398171,-0.554877,-0.473294,-0.480155,-0.262822,0.050132,0.045611,-0.216925,0.929107,-0.747288,0.294503,0.476545,0.339067,-0.216269,0.950741,-0.000393,-0.070352,-0.228900,-0.096581,0.262072,0.227849,0.190228,0.129484,0.333782,-0.307668,0.145137,-0.239114,0.407231', '30162520', '4301278', '1307146', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293647', '呼啸山庄', '剧情', '电影《呼啸山庄》改编自艾米莉·勃朗特同名小说。此版在第12届奥斯卡奖评选中获得最佳摄影（黑白片）奖。迪恩先生把一个叫希斯克利夫（劳伦斯·奥利弗 Laurence Olivier 饰）的吉普赛男孩带回呼啸山庄。女儿凯西（梅尔·奥勃朗 Merle Oberon 饰）爱上了他，但又不愿放弃优裕的生活。希斯克利夫得知后悄然离去，凯西则嫁给了邻居艾德加（大卫·尼文 David Niven 饰）。几年后希斯克利夫风度翩翩地回来了，买下了呼啸山庄。艾德加的妹妹伊贝拉爱上了他，他与伊莎贝拉结婚却对她冷淡无情。凯西也因为悲伤过度而濒临死亡。希斯克利夫心神错乱，在哀悼凯西、期待死亡中捱过了20年。他对周围一切人都极端轻蔑、百般折磨，直到凯西的幽灵在一个严冬的雪夜把他召唤到他们最喜爱的荒原上某个地方，在死亡中重新聚会……©豆瓣', '梅尔·奥勃朗', '威廉·惠勒', 7.8, 9173, 'tt0032145', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2185401138.jpg', 0.6, 2.4, 26, 49.4, 21.7, '0.133261,0.030865,-0.731331,0.513565,0.008388,-0.594412,0.861479,0.001140,-0.108319,-0.180825,0.097236,0.793110,-0.237926,0.359834,0.368461,0.376267,-0.428319,-0.509253,-0.209264,-0.355522,-0.270711,-0.509979,-0.125871,-0.167350,-0.052903,-0.319203,0.375594,-0.037902,0.011288,0.439351,0.334841,0.365766,0.033523,0.449105,0.061083,0.327167,0.310977,-0.129694,-0.228458,0.402582,0.100502,-0.103476,-0.255462,0.448186,0.044901,0.261591,0.890282,-0.356985,0.149578,-0.078795,0.406244,-0.163103,-0.020186,0.032686,0.195739,-0.233133,-0.064618,0.156978,-0.212054,0.074462,-0.024423,0.003917,-0.265360,0.001515,-0.019649,0.248044,-0.492927,0.451877,-0.144250,0.076553,0.022006,-0.321901,0.129510,-0.077005,0.383371,0.350611,0.010191,-0.059173,-0.335655,0.160475,0.478487,0.026304,-0.326438,0.397506,-0.338997,-0.458809,-0.021805,0.037770,-0.825772,0.011827,0.502984,-0.150245,-0.093160,0.631125,-0.413534,-0.266416,-0.273540,0.008744,-0.266243,-0.301793,-0.037707,-0.476072,-0.139413,-0.215642,-0.136993,-0.178384,-0.102690,-0.289208,0.495574,-0.542118,0.655780,0.542997,0.415353,0.015845,0.377837,0.139950,0.181950,-0.133530,0.065631,0.667669,0.164945,-0.023145,0.336984,0.217911,0.085071,0.050077,-0.377808,0.777667', '1305666', '6827727', '1309172', '1844413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293648', '小猪宝贝2：小猪进城', '喜剧', '描述当小猪「宝贝」像英雄般地凯旋回诈到何氏农庄后，这只热心过度的小猪不小心造成意外，害主人何先生卧病在床，由于他无法工作，加上银行威胁要沉没收他们的农庄，于是何太太为了拯救这座农庄，就决定接受一笔很高的酬劳，带着小猪到大城市表演那手令人目瞪口呆的牧羊本领，展开一场精彩逗趣的冒险故事。', '玛格达·苏班斯基', '乔治·米勒', 7.9, 4513, 'tt0120595', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2397234693.jpg', 0.3, 1.8, 24.2, 47.7, 26.1, '-0.040931,0.103128,-0.628795,0.318986,-0.136929,-0.151849,0.518359,0.160853,-0.393473,0.035378,0.420654,0.401545,-0.005135,0.251621,0.191332,0.190765,-0.238385,0.051997,-0.128605,0.035878,-0.035216,-0.303876,-0.030698,-0.270412,-0.123304,-0.121234,0.050038,0.047367,-0.375242,0.221166,0.172036,-0.037600,-0.085721,0.280054,-0.114715,0.118606,0.005759,0.462419,-0.300987,0.024583,0.391353,0.000101,-0.234218,0.271364,0.191757,0.085100,0.626811,-0.300326,-0.582151,-0.062022,0.335816,-0.228181,0.155525,-0.014017,0.180773,0.032031,0.206877,-0.185224,-0.103080,0.160901,0.055757,-0.210935,-0.620690,0.117923,0.400648,0.011359,-0.571471,0.257165,-0.162848,0.142862,0.043491,-0.341833,-0.126246,0.293906,0.386285,0.327007,-0.072202,0.348492,-0.540881,0.324947,0.431435,-0.145529,-0.178478,0.325163,-0.217892,-0.384400,0.379586,-0.444772,-0.427227,0.218015,0.364291,-0.049494,-0.159655,0.034535,-0.392719,-0.150565,-0.262968,-0.361131,-0.110073,-0.350794,-0.160954,-0.277216,0.136551,-0.272964,-0.022705,0.034689,0.377874,-0.234181,0.563691,-0.411627,0.097914,0.566094,0.143531,-0.247345,0.220565,0.015513,0.070350,-0.249590,-0.068581,-0.230151,-0.044456,0.456492,0.496813,0.005336,0.057048,-0.366449,-0.272465,0.540625', '21619567', '25928048', '35262994', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293651', '绿卡', '喜剧', '音乐家乔治（杰拉尔·德帕迪约 Gérard Depardieu饰）和园林爱好者布朗蒂（安迪·麦克道威尔 Andie MacDowell饰）的结合，完全是出自各自的私心：乔治来自法国，想得到一张美国的绿卡，从而在这里发展事业；布朗蒂看中了一套公寓，却被告知只有夫妻才能入住。于是，两人一拍即合，各取所需，结婚后很快就过回各不相干的生活。美国移民局的怀疑随之而来。为了一张绿卡而假结婚的案例他们见得多了，乔治和布朗蒂的婚姻自然也逃不过他们的法眼。严谨认真的调查介入了这对“夫妻”的生活。现在，乔治和布朗蒂必须策划出一个完美的恋爱和结婚过程，摆造出一起生活的种种细节证据。为了能让婚姻变得更加可信，乔治甚至住进了布朗蒂的家，两人却渐渐戏假情真。©豆瓣', '热拉尔·德帕迪约', '彼得·威尔', 7.5, 6829, 'tt0099699', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1464613872.jpg', 0.3, 1.6, 33.4, 50.2, 14.5, '0.504396,-0.244564,-0.579749,0.720364,0.010514,-0.645661,0.594777,0.188765,-0.436630,-0.369154,-0.429617,0.785162,-0.284100,0.233547,0.403467,-0.206996,-0.542281,-0.698884,-0.042417,-0.375320,-0.201734,-0.762432,0.043483,-0.529337,-0.100740,-0.087047,0.377680,0.062760,0.000221,0.383331,0.321588,0.367213,-0.084302,0.184085,0.084345,-0.243252,0.034290,0.055062,-0.723883,0.157466,0.167306,0.380430,0.102059,0.206576,0.277774,0.413187,0.401082,-0.370380,0.100134,0.171187,0.334996,-0.008960,0.011955,0.236105,0.262992,-0.134905,0.182680,0.443510,-0.373211,-0.191737,0.012740,-0.219076,-1.138363,0.052175,-0.091033,-0.007934,-0.395888,0.231265,-0.066661,0.090252,-0.059238,-0.294632,0.388395,0.853034,0.507270,0.192016,-0.019427,0.122103,-0.429809,0.038253,0.644234,0.120414,-0.026302,0.377761,-0.562796,-0.423580,-0.163269,-0.109920,-0.391632,-0.181802,0.364538,0.004626,0.101461,0.081111,-0.524350,-0.245393,-0.337697,-0.270530,0.286883,-0.635498,0.328719,-0.674605,-0.372360,-0.505664,-0.457772,0.041062,0.061120,-0.161594,0.538632,-0.706624,-0.052807,0.496396,0.252924,-0.513664,0.649258,0.168164,0.330708,-0.245903,-0.199004,0.473507,0.247974,0.149369,0.027144,0.442814,0.360248,0.017946,-0.109303,0.443295', '26678784', '1793491', '1307442', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293656', '惊爆银河系', '喜剧', '《银河探险》是一套二十年前讲述太空NSEA保护者故事的电视科幻剧集，1982年停播，接近二十年后，饰演指挥官的贾森（蒂姆•艾伦 Tim Allen 饰），饰演博士的亚历山大（艾伦•瑞克曼 Alan Rickman 饰），以及格温（西格妮•韦弗 Sigourney Weaver 饰）等几位演员再度聚首，参加一系列粉丝见面会和商业活动。期间，一群自称塞米安人的怪诞粉丝跟随贾森到他的家里，疲惫的贾森发现这群塞米安人并非疯狂粉丝，而是真正的外星人！没有欺骗能力的塞米安人在收看《银河探险》后以为贾森等人是真正的太空英雄，他们在和宇宙恶徒萨里斯的对决中节节败退，于是远赴地球寻求保护者们的帮助，贾森和亚历山大等船员假戏真做，帮助塞米安人对抗宇宙邪恶势力……©豆瓣', '山姆·洛克威尔', '迪恩·帕里索', 7.8, 8218, 'tt0177789', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1929128940.jpg', 0.7, 2.2, 26.4, 48.4, 22.3, '0.232484,-0.165071,-0.725364,0.568743,0.255109,-0.206385,0.465633,-0.046955,-0.461252,-0.322591,0.099631,0.679954,-0.322877,0.017574,0.419522,-0.314639,-0.644991,-0.696667,-0.368234,-0.062189,-0.234748,-0.370751,-0.349880,-0.276315,0.004783,-0.669431,0.656445,-0.044889,-0.080318,0.710693,0.168940,0.389774,-0.014436,0.090871,0.091030,-0.023753,0.551640,0.065578,-0.440426,0.295110,-0.293034,0.085959,-0.099010,0.001462,0.094527,0.173725,0.412913,-0.436964,0.172062,0.011866,0.243593,-0.466388,0.177454,-0.136243,0.425371,-0.272984,0.176345,0.093174,0.144581,0.086438,-0.183053,-0.119024,-0.804149,-0.085455,0.007698,0.286952,-0.331077,0.318767,-0.069075,-0.041255,0.155812,0.088607,0.178381,0.353644,0.350927,0.207223,0.190238,-0.032185,-0.204480,0.420257,0.450798,0.125800,-0.272473,0.178239,-0.083053,-0.302945,-0.165887,-0.164586,-0.600628,0.004121,0.099428,-0.191275,0.075449,0.430252,-0.595975,-0.104660,-0.208717,-0.266705,0.049548,-0.280531,0.011229,-1.195378,-0.036454,-0.209033,0.159825,-0.046392,0.152645,-0.181392,0.689552,-0.675426,0.308566,0.536340,0.202764,-0.292516,0.887545,-0.096217,0.008723,-0.318612,0.141567,0.165867,0.144175,0.080431,-0.060329,0.242633,0.138702,-0.096339,-0.305228,0.282595', '24751811', '2369613', '3318306', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293658', '奇谋妙计五福星', '喜剧', '狱中5个素不相识的人成了好兄弟——五福星。茶壶（洪金宝 饰）、死气喉（吴耀汉 饰）、卷毛积（岑建勋 饰）、凡士林（秦祥林 饰）和鲁奇（冯淬帆 饰）五人皆因小偷小摸或跑龙套成了冤大头，他们决心出狱后重新做人，光明正大挣钱。五人同一天出狱了，出狱后他们合股成立了一间清洁公司 ，专门帮公司或家居进行清洁。一天，黑帮在交易制贩假炒的电版时，被当地一个愣警察撞见了。慌乱之下，他们将电版藏进了五福星的清洁车的清洁箱内。毫不知情的五福星就这样又无端卷入了江湖是非中：一方面，警察怀疑他们是黑帮同伙，在四处通缉他们；另一方面，黑帮也在追寻他们，想杀人灭口取回电版。五福星在进退两难的境地如何运用他们的奇谋妙计脱险？©豆瓣', '洪金宝', '洪金宝', 7.8, 38409, 'tt0086605', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1956316774.jpg', 0.3, 1.5, 26.3, 49.3, 22.6, '0.036773,-0.056482,-0.462849,0.182137,-0.233187,-0.098725,0.489959,0.275001,-0.298948,-0.042558,0.229376,0.626140,-0.143031,-0.012862,0.143625,-0.140966,-0.266375,-0.607624,-0.040335,-0.283474,-0.234220,-0.303398,-0.317493,-0.452115,0.033358,0.231481,0.094154,0.221410,0.060466,0.376312,0.345325,0.136816,-0.309130,0.035746,-0.148241,0.122847,-0.027046,0.007903,-0.218392,0.002678,-0.271394,-0.334173,-0.049251,0.109216,0.134541,0.383228,0.640918,0.052978,-0.029744,-0.261540,0.124935,-0.237809,-0.117485,0.040285,0.385967,-0.113769,0.317440,0.212443,-0.288455,-0.081828,0.218413,0.147390,-0.798746,0.037060,0.026048,-0.033913,-0.712275,0.362623,-0.091913,-0.037821,-0.189071,-0.097457,0.092840,0.431397,0.299527,0.206723,0.062155,-0.074318,-0.633217,0.387332,0.390553,-0.122324,0.184659,0.046040,0.326477,-0.226084,0.128431,-0.213570,-0.125878,-0.299535,0.544440,-0.263051,-0.076477,-0.096619,-0.503882,-0.249344,-0.242379,0.066902,-0.155478,-0.206442,0.048582,-0.558330,0.052738,-0.129677,-0.278064,0.143769,0.194842,-0.135247,0.416317,-0.591085,-0.030095,0.545705,0.146693,-0.844233,0.507347,0.080967,0.340303,-0.214367,-0.190280,-0.472447,0.288541,0.368919,0.537834,0.444549,-0.171428,-0.136991,-0.095622,-0.281917', '1302110', '26678784', '1300857', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293683', '艾德·伍德', '剧情', '这是一部关于奋斗的个人自传电影。1951年，心怀大志的艾德•伍德（约翰尼•德普 Johnny Depp 饰）终于等来机会上演一出自导自演的电影，但是，这个计划不久就夭折了。艾德并没有气馁，而是接着又一个一个的找投资商，找演员，甚至连他的女友也被拉进剧组参加演出。每次总是准备工作进行得大半时，电影合同最终还是没有拿到，梦想一次次的破灭，女友也离他而去。我们的艾德虽然自此住进了医院一阵子，但他还没有放弃自己的追梦之旅：还是到处跑着找投资人，苦苦跪求那些著名演员加入自己的剧组，在电影院里被观众的臭鸡蛋烂番茄打得抱头鼠窜。场面热闹而搞笑……©豆瓣', '约翰尼·德普', '蒂姆·波顿', 8.2, 25519, 'tt0109707', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1704315869.jpg', 0.3, 1.6, 17.4, 49.4, 31.3, '0.173676,-0.017216,-0.699692,0.448481,-0.023546,-0.602187,0.669682,0.090050,-0.246696,-0.221017,-0.226450,0.695521,-0.340523,0.285156,0.084277,-0.042279,-0.378988,-0.786371,0.105479,0.048961,0.031914,-0.147898,-0.205091,-0.264195,-0.118861,0.009488,0.698147,0.177471,-0.147992,0.212972,0.496756,-0.207353,0.203998,0.563231,-0.035660,0.237502,0.060567,-0.002342,-0.141035,0.527310,0.336701,-0.354597,-0.431639,0.148746,0.192704,0.630186,0.474581,-0.033822,-0.176365,0.237057,0.445799,-0.465749,-0.252203,0.107590,0.112807,-0.052002,0.440064,0.007275,-0.053912,0.053134,0.117330,-0.289939,-0.996294,0.311590,0.044783,0.093099,-0.527054,0.533516,-0.120938,0.262436,-0.135393,-0.307121,0.306678,0.189263,0.351677,0.322191,-0.356274,0.123366,-0.419539,0.542503,0.730890,0.072477,0.090613,0.462397,0.134052,-0.289332,0.036347,-0.244073,-0.699766,0.206705,0.404188,-0.141067,-0.278397,-0.250561,-0.634740,0.161791,-0.348967,-0.523126,0.055152,-0.334858,0.107852,-0.837810,0.049594,-0.027517,-0.259379,-0.111661,0.036918,-0.172368,0.644998,-0.574911,0.190786,0.584271,0.181218,-0.705872,0.769432,0.104439,-0.090603,0.176715,0.038151,0.023118,-0.051918,0.430129,0.410137,0.300032,0.223524,-0.501208,-0.344483,0.522134', '4301278', '3318306', '25928048', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293692', '十诫', '剧情', '电影《十诫》在影史上有着不可动摇地位，取材自《旧约圣经》的《出埃及记》，讲述了犹太先知摩西（查尔登·海斯顿饰）的一生。在经历各种苦难考验后，上帝耶和华将“十诫”授予摩西，并赐予力量于摩西。摩西领导饱受苦难的希伯来人出走埃及，穿越红海，重新建立新的生活。1956年 由派 拉蒙电影公司制作，由打造好莱坞黄金时代的导演塞西尔·B·戴米尔执导的史诗电影《十诫》，荣获1957年第29届奥斯卡金像奖最佳音效、最佳剪辑、最佳服装设计、最佳摄影、最佳艺术指导、最佳影片、及最佳特效等多项提名。本片被美国国家电影保护局列为政府收藏作品，是一部不可错过的影史经典之作。©豆瓣', '查尔顿·赫斯顿', '塞西尔·B·戴米尔', 8.3, 9923, 'tt0049833', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1183679825.jpg', 0.7, 1.6, 15.8, 45.3, 36.6, '-0.276581,-0.152675,-0.320466,0.777290,0.587480,-0.259475,0.124573,0.008709,-0.399914,-0.297386,0.338343,0.932207,-0.172630,-0.141157,0.360644,0.033658,-0.737981,-0.672827,-0.057348,-0.239648,0.161556,-0.258320,-0.341880,0.227451,-0.196954,-0.695251,0.910479,-0.350641,-0.393130,0.043101,0.476826,0.240168,0.087838,-0.478002,-0.128563,-0.020223,0.420463,-0.150588,-0.827071,0.665259,-0.116219,-0.350580,-0.178899,-0.026642,0.016077,-0.106459,0.341991,-0.309776,0.179618,0.010610,1.039888,-0.507544,-0.259762,-0.105091,0.060669,0.231791,0.020605,0.567392,0.093400,0.314868,-0.054897,-0.488718,-1.130263,-0.295340,0.089972,0.185452,-0.436026,0.361485,-0.235271,0.209268,-0.095354,0.054668,0.197473,0.063610,0.720039,0.245928,0.110315,-0.029239,-0.036949,0.954838,-0.041688,-0.269425,-0.371692,0.284450,-0.187518,-0.635961,0.031337,-0.325398,-0.519676,0.173520,0.416857,-0.001694,0.314537,0.299883,-0.532451,-0.175218,-0.074707,-0.662927,0.147434,-0.181564,0.072067,-1.209065,-0.321537,-0.123226,0.033110,-0.524820,0.355105,-0.490065,0.825321,-0.240167,0.484384,0.303230,-0.009924,-0.218977,0.942681,-0.001058,0.033140,-0.302155,0.070395,0.513913,-0.006573,0.383199,-0.169956,0.062268,0.234565,-0.338253,-0.325606,0.552383', '22265121', '30397916', '26275494', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293702', '侏罗纪公园2：失落的世界', '动作', '当年在努布拉岛营建侏罗纪公园时，约翰•哈蒙德（理查德•阿滕伯勒 Richard Attenborough 饰）曾把附近的索纳岛作为恐龙的制造工场。侏罗纪公园沦陷后，索纳岛上的恐龙在完全隔绝且缺少必要合成元素的情况下生存了4年时间。哈蒙德对此颇感好奇，他重新找到马科姆博士（杰夫•高布伦 Jeff Goldblum 饰），邀请他前往小岛考察。4年前经历让马科姆心有余悸，他断然拒绝哈蒙德的提议，但当得知女友莎拉（朱丽安•摩尔 Julianne Moore 饰）已前往小岛之时，只得跟随探险队整装出发。在索纳岛上，另一组野蛮的探险队已经先期到达，他们抓捕恐龙将其卖到外国。利欲熏心使得这些贪婪之徒全然不顾危险，竟然打起暴龙的主意。索纳岛旋即变成恐怖的屠杀地狱……©豆瓣', '杰夫·高布伦', '史蒂文·斯皮尔伯格', 7.6, 144487, 'tt0119567', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1259571118.jpg', 0.6, 3, 30.4, 48, 18.1, '0.110166,0.018861,-0.864277,0.401283,-0.000286,-0.081886,0.381066,0.015087,-0.451819,-0.072207,0.120159,0.449392,-0.016805,0.178440,0.327454,-0.024345,-0.527347,-0.207622,-0.011935,-0.085579,-0.217946,-0.440019,-0.464305,-0.351081,0.153412,-0.522860,0.273642,0.168050,-0.051817,0.564890,0.079585,0.467948,-0.260015,0.443205,-0.044102,-0.007914,0.398323,-0.166213,-0.223343,0.217863,-0.294483,0.188402,-0.056088,-0.024131,0.183992,0.386821,0.571638,-0.272710,-0.190272,-0.324559,0.085544,-0.127488,0.195277,-0.010234,0.376763,-0.108121,-0.081665,0.076028,-0.297303,0.079879,0.126062,-0.072088,-0.230476,0.205235,0.021402,-0.080112,-0.485443,0.050352,-0.014945,-0.033359,-0.106960,-0.434413,0.072686,0.319062,0.224589,0.125254,0.384210,0.002710,-0.361067,0.119671,0.615290,-0.093136,-0.115453,-0.077579,0.161782,-0.453234,0.057070,-0.109367,-0.162255,-0.006573,0.260315,0.079638,-0.213868,0.212346,-0.720732,-0.268168,-0.527199,-0.353756,0.106028,-0.134859,-0.080856,-0.759977,0.064811,0.044655,-0.075652,-0.083847,0.120182,0.043227,0.228819,-0.474580,0.379589,0.444928,0.289015,-0.365254,0.384483,-0.366598,0.021909,-0.172500,-0.011913,0.482290,0.318675,0.505322,-0.033529,0.147151,0.072787,-0.502069,-0.483437,0.492278', '3871833', '2159244', '21349734', '35287558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293706', '霍华德庄园', '剧情', '一次偶然中，海伦（海伦娜·伯翰·卡特 Helena Bonham Carter 饰）和玛格丽特（艾玛·汤普森 Emma Thompson 饰）两姐妹结识了威尔克斯一家人。在威尔克斯家所拥有的霍华德庄园中，玛格丽特和威尔克斯太太（瓦妮莎·雷德格瑞夫 Vanessa Red grave 饰）的感情最为要好，海伦却在和保罗（Joseph Bennett 饰）的一段短暂恋情结束后离开了威尔克斯家。威尔克斯太太死前将整个霍华德庄园留给了玛格丽特，亨利（安东尼·霍普金斯 Anthony Hopkins 饰）隐瞒了这一事实，转而向玛格丽特求婚。离开了霍华德庄园的海伦遇见了名叫巴斯特（Samuel West 饰）的男子，两人相处融洽。玛格丽特再度见到海伦之时，她震惊的发现，尚未成家的海伦已有身孕，这样的海伦遭到了威尔克斯家大儿子查尔斯（詹姆斯·维尔拜 James Wilby 饰）的厌恶和驱逐。', '瓦妮莎·雷德格雷夫', '詹姆斯·伊沃里', 7.5, 10201, 'tt0104454', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493284617.jpg', 0.5, 3.3, 32.3, 47.4, 16.5, '0.512246,-0.002562,-0.727712,0.400861,0.092060,-0.811342,0.900373,0.122890,-0.526978,-0.305058,0.135687,0.997746,-0.462676,0.390052,0.482021,0.359802,-0.588583,-0.553383,0.100046,-0.323299,-0.186323,-0.676744,-0.020037,-0.114545,0.013224,-0.463245,0.078250,-0.182027,0.176895,0.744960,0.176295,0.331088,0.057640,0.286945,0.017325,0.513853,0.456721,-0.243555,-0.509734,0.227208,0.183459,0.081331,-0.235136,0.336502,0.255773,0.410765,0.553224,-0.328682,0.189426,-0.092250,0.029783,0.096890,0.161406,0.427853,0.226883,-0.230610,0.182613,0.413640,-0.344034,-0.208478,0.128007,-0.030330,-0.329746,0.458897,0.077545,0.186555,-0.608876,0.439230,-0.300227,-0.101950,0.004620,-0.339370,-0.024495,0.520075,0.149211,0.144728,-0.114790,0.092509,-0.371897,-0.113479,0.422979,-0.061715,-0.224784,0.428079,-0.068434,-0.143486,0.069607,0.157259,-0.531690,-0.194035,0.579304,0.160489,0.118175,0.515918,-0.720419,-0.396719,-0.712184,0.012620,0.048023,-0.418686,-0.156312,-0.721227,-0.251126,-0.424517,-0.541816,-0.167453,-0.101016,-0.041824,0.392687,-0.683858,0.346097,0.084335,0.369801,-0.003532,0.424671,-0.067453,0.464769,-0.093221,0.045970,0.477348,0.096362,-0.005185,0.258770,0.621932,0.126705,-0.107795,-0.432981,0.529555', '1297239', '2034997', '4319218', '6128003');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293708', '她比烟花寂寞', '剧情', '希拉莉（瑞切尔•格里菲斯 饰）与积琪琳（艾米丽•沃森 饰）是一对感情深厚的姐妹。姐姐希拉莉很有吹长笛的天分，积琪琳看着姐姐拿到了许多荣耀也不甘落后，经过艰苦练习后，积琪琳的大提琴也有了很大的进步。在一次比赛中，两人分别获得了第一，但希拉莉开始嫉妒妹妹，纵使两人的感情没有受到影响，可是希拉莉的音乐之路开始触礁。长大后的希拉莉成家了，搬到了偏远地区，这时也同样结婚了的积琪琳十分羡慕姐姐过着平常但幸福的生活，她开始厌倦到处表演。她逃到了姐姐的家中，却要求与姐夫发生关系，为了迁就妹妹，希拉莉只好妥协。终于一天，积琪琳发现姐夫爱的依然是姐姐时，她离开了，回到了丈夫的身边，正当一切进展顺利之际，她发现自己患上了不治之症。©豆瓣', '艾米丽·沃森', '安南德·图克尔', 8.3, 116938, 'tt0150915', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2564835945.jpg', 0.5, 1.5, 16.3, 47.1, 34.6, '0.222407,-0.076660,-0.879402,0.492620,0.205225,-0.642087,0.878102,0.062323,-0.257478,-0.303952,-0.106509,0.478239,-0.240482,0.245231,0.347815,0.111752,-0.278906,-0.701077,0.322728,-0.305753,-0.379654,-0.526608,0.117959,-0.079720,-0.396757,-0.553932,0.382010,-0.252725,0.201408,0.581906,0.029288,-0.021903,0.139146,0.770053,-0.059418,0.162068,0.064964,0.169692,-0.264840,0.187223,0.467940,-0.101402,-0.097046,0.249992,0.197856,0.298373,0.788475,-0.255558,-0.032495,0.123648,0.298903,-0.277447,-0.137564,0.010400,0.530079,-0.167048,0.020697,-0.011575,-0.173683,-0.239544,-0.141580,-0.127914,-0.443648,-0.084961,0.227627,0.015110,-0.540333,0.446244,0.010509,-0.141169,0.029303,-0.636293,0.456386,0.425966,0.024136,0.340373,-0.334566,0.133706,-0.492705,-0.153533,0.926186,0.035525,0.183737,0.566293,-0.412196,-0.517936,0.263757,-0.435470,-0.542185,0.132337,0.224118,0.174823,-0.070968,0.227270,-0.377433,-0.169937,-0.346394,-0.051296,-0.042280,-0.804934,0.313235,-0.382865,-0.187417,-0.751396,-0.378942,0.157028,-0.263442,-0.693005,0.805920,-1.136524,0.280633,0.361082,0.419855,-0.373826,0.674346,0.062225,0.325225,0.118252,-0.017149,0.309085,-0.510429,0.029055,0.259648,0.369605,0.225185,-0.052662,-0.162842,0.456845', '1292219', '1308755', '21766698', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293714', '光荣战役', '剧情', '美国南北战争，白人军官罗伯特·古尔德萧（马修·布罗德里克 Matthew Broderick饰）在战斗中负伤，被一位名叫约翰·罗林斯（摩根·弗里曼 Morgan Freeman饰）的掘墓人发现送进了野战医院。在波士顿养病期间，罗伯特自愿接下了全部由黑人组成的“麻州第五十四兵团”指挥官的职务。然而面对种族歧视的严重偏见和白人同僚的冷嘲热讽，以及新兵瑞普（丹泽尔·华盛顿 Denzel Washington饰）的种种质疑，他毅然将一群从南方黑奴制度中脱逃至北方的乌合之众训练成一支纪律严明的部队。由他率领的黑人兵团“麻州第五十四兵团”，在南方的查尔斯坦战役中写下光辉的一页。然而罗伯特自己却在上战场攻坚时壮烈牺牲。由知名奥斯卡获奖导演爱德华·兹维克执导的史诗战争影片《光荣》，根据美国南北战争中的真实事件改编而成。本片以对作战场面触目惊心地描写和对黑人受虐惨况催人泪下地刻画，赢得1990年第62届奥斯卡金像奖最佳男配角、最佳摄影、最佳音响等多项大奖。尚未成名的丹泽尔·华盛顿更凭借此片一同收获1990年第47届金球奖最佳男配角。', '马修·布罗德里克', '爱德华·兹威克', 8.1, 10460, 'tt0097441', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1340405798.jpg', 0.2, 1.1, 19.2, 53, 26.5, '0.135077,-0.126381,-0.640808,0.680503,0.296814,-0.265861,0.511224,-0.090849,-0.387229,-0.099726,0.342894,0.807472,-0.031494,-0.015967,0.521972,-0.291039,-0.367723,-0.870778,-0.410363,-0.153316,-0.152339,-0.615283,-0.497862,-0.123855,-0.061137,-0.454239,0.803787,0.051758,-0.132598,0.560074,0.508777,0.507135,0.134072,0.109003,0.023359,-0.058933,0.377662,-0.258579,-0.459822,0.350708,-0.065919,-0.332893,-0.230976,0.006374,0.069292,0.316807,0.920543,-0.464525,0.391900,-0.058163,0.406573,-0.247360,-0.183387,0.031520,0.458954,0.070542,-0.012010,0.295868,0.064482,0.344065,-0.255929,-0.194808,-0.621938,-0.116297,0.055046,0.288707,-0.477132,0.421543,-0.255313,0.314897,0.133637,0.106960,0.094926,0.233630,0.276941,0.241709,0.077652,-0.042074,-0.092430,0.476679,0.182055,-0.064510,-0.472489,-0.104116,-0.228511,-0.574049,0.049165,-0.458322,-0.215125,0.029018,0.249924,-0.236304,0.308933,0.196375,-0.650021,-0.151738,-0.299428,-0.418670,-0.252662,0.010373,-0.060538,-0.928681,0.011542,-0.153046,-0.113596,0.030311,0.023217,0.057958,0.626975,-0.486415,0.144588,0.218209,0.002989,-0.130395,0.408533,0.120473,0.328140,-0.288016,-0.110376,0.353483,0.132916,0