INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293715', '总统班底', '剧情', '根据水门事件揭发人Carl Bernstein和Bob Woodward所写自传改编的电影。二人是《华盛顿邮报》的记者，在水门事件里，他们历尽艰辛揭开政治黑幕，人物和事件一同成为美国一段家喻户晓的历史。故事由五名盗贼开始，他们潜入水门大度行窃。本来是一桩不甚重大的刑事案件，却在Bernstein（达斯汀·霍夫曼Dustin Hoffman 饰）和Woodward（罗伯特·雷德福Robert Redford  饰）的追查下，最终撕开了一条大裂缝，矛头直指总统尼克松。从1972年到1974年，从尼克松竞选总统到尼克松连任上台，华盛顿邮报受到的压力越来越大，甚至被威胁。主编本·布莱德利站在了新闻自由和相信自己记者的这边，Bernstein和Woodward得以继续追寻事件真相，得到了重要线人“深喉”的帮助，经历了难以想象的曲折艰辛后，水门事件最终导致尼克松总统下台。', '达斯汀·霍夫曼', '艾伦·J·帕库拉', 8, 8569, 'tt0074119', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1376946644.jpg', 0.3, 1.7, 20.8, 53.7, 23.5, '0.181998,-0.283330,-0.677967,0.583993,0.110866,0.015204,0.666539,0.125840,-0.596922,-0.146746,0.211382,0.918426,-0.600492,-0.029249,0.447676,-0.163544,-0.480667,-0.783554,0.026860,-0.183984,-0.236529,-0.754058,-0.389617,-0.407565,-0.041366,-0.339790,0.790600,0.430180,-0.510388,0.314777,0.296611,0.282108,-0.089926,0.424705,0.007446,0.087140,0.219862,0.041590,-0.306048,0.261354,0.153872,-0.627346,-0.372518,0.130926,0.014975,0.339081,0.248726,-0.516377,-0.196578,0.192155,0.484709,-0.636897,-0.146567,0.230626,0.455868,0.156027,0.122614,0.737852,-0.283708,-0.029547,0.039094,-0.391011,-0.579237,0.021694,-0.194493,0.385160,-0.499123,0.500615,-0.324881,0.046528,0.087728,-0.420611,0.190697,0.358360,0.094708,0.101850,-0.121167,0.086616,-0.484360,0.209389,0.825800,0.120082,-0.261438,0.039409,0.064072,-0.309332,-0.277212,-0.400867,-0.105420,0.125162,0.610681,-0.066141,-0.221477,0.482485,-0.426801,-0.195799,-0.343018,-0.365955,-0.006154,-0.415362,-0.069389,-0.609055,-0.377835,-0.153402,0.001228,-0.002371,-0.050762,-0.367805,0.781813,-0.418831,0.289157,0.338627,0.055165,-0.516721,0.768107,-0.057961,0.251917,-0.144417,-0.121627,0.023119,0.240196,0.464750,0.250129,0.212407,0.003607,-0.443476,-0.108037,0.019154', '30162520', '2