INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293718', '亚当斯一家', '喜剧', '亚当斯庄园里住着一个典型哥特式家庭。戈梅斯（劳尔·朱力亚 Raul Julia饰）和妻子（安杰丽卡·休斯顿 Anjelica Huston饰）终年生活在这里，到处弥漫阴郁腐败的气息。二人感情如蜜，有一双喜欢玩谋杀游戏的儿女。戈梅斯的心里，却埋藏着一个伤疤。那就是他曾经和哥哥费斯特失和，费斯特已经失踪25年，戈梅特仍然放不下对哥哥的惦念。一心要夺取亚当斯庄园和这里的财富的母亲有一个儿子戈登（克里斯托弗·洛伊德 Christopher Lloyd饰），貌相跟费斯特相向。于是，一场阴谋上演了，她教唆戈登佯装费斯特潜入亚当斯庄园，利用戈梅斯的兄弟情一步一步地夺取庄园。果然，戈登的到来不仅使戈梅斯大为惊喜，他渐渐融入这里的家庭生活，戈梅斯一家也随之陷入危险的泥沼中。当他们被夺走家产，凄苦沦落时，事情又有了峰回路转的变化。©豆瓣', '安杰丽卡·休斯顿', '巴里·索南菲尔德', 8.5, 68732, 'tt0101272', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1219939183.jpg', 0.2, 1, 13.2, 43.4, 42.1, '0.162598,-0.109809,-0.553072,0.504121,0.017753,-0.640975,0.944677,0.315048,-0.314774,-0.264394,0.218546,0.800394,-0.137890,0.021829,0.160419,0.167818,-0.424040,-0.640405,-0.182830,-0.238521,0.202348,-0.461108,-0.470724,-0.110390,-0.012925,-0.426619,0.395077,0.225900,-0.013672,0.459257,0.178595,0.475118,-0.055837,0.438807,0.180002,0.046658,0.308571,-0.044928,-0.351949,-0.022203,0.023144,0.119383,-0.177526,0.033347,0.101108,0.296385,0.544661,-0.217159,-0.052802,-0.289286,0.133403,-0.105080,-0.076296,0.002084,0.242577,-0.244293,0.185335,0.343108,-0.466596,-0.201218,0.196785,-0.228770,-0.542192,-0.065641,0.199490,-0.019182,-0.408651,0.290119,-0.051378,-0.218765,-0.022298,-0.342507,0.289191,0.431457,0.156323,0.454837,-0.297012,-0.043477,-0.596988,-0.168704,0.626875,-0.213625,-0.028421,0.102358,-0.401066,-0.153766,0.048017,-0.299871,-0.623835,-0.247986,0.307733,-0.055663,-0.168457,0.487293,-0.529872,-0.054388,-0.294205,0.012021,0.051701,-0.709549,-0.152864,-0.357546,-0.303186,-0.131511,-0.251750,0.032702,-0.069574,-0.052465,0.364317,-0.423651,0.541309,0.443071,0.234255,-0.244379,0.684548,0.007517,-0.040861,-0.052516,-0.191255,0.430516,-0.094045,0.055393,0.186772,0.207012,-0.024301,0.025277,-0.283651,0.623416', '1305666', '1309172', '12