INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293726', '周末夜狂热', '剧情', 'Tony Manero（约翰·特拉沃尔塔 John Travolta 饰）是纽约布鲁克林区一个19岁的青年，白天在一个五金店打工，看起来是一个平凡的少年。然而到了周六晚上，Tony就是当地迪斯科舞厅光芒四射的“舞王”。Annette是Tony的舞伴，两人本来计划参加舞厅将要举办的跳舞比赛。然而当Tony遇见了Stephanie Mangano（凯伦·琳恩·高妮 Karen Lynn Gorney 饰）后，被她的舞技所打动。Tony向Stephanie求爱遭拒，但是Stephanie同意当Tony的舞伴，和他一起参加比赛。两人每天勤加练习。在比赛的时候两人奉献了精彩的表演，获得了第一名。然而Tony认为有一对搭档舞技更好，只是因为他们是西班牙人而只能获二等奖。于是Tony把第一名让给了他们。比赛结束，Tony再次向Stephanie求爱......本片带动了当时的迪斯科热潮，Bee Gees的歌也风靡全球。', '约翰·特拉沃尔塔', '约翰·班德汉姆', 8, 7330, 'tt0076666', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p785443767.jpg', 0.3, 2, 23, 48.4, 26.3, '0.171344,-0.131653,-0.577672,0.429898,-0.125226,-0.390627,0.462722,0.076884,-0.181321,0.020654,0.207572,0.973019,-0.489461,0.351876,0.598432,-0.067742,-0.067129,-0.850183,-0.144670,0.039026,-0.151426,-0.446953,0.168094,-0.040573,0.078234,-0.356283,0.570381,0.081652,-0.158378,0.903539,0.603536,-0.059465,0.186278,0.345049,-0.193795,-0.379260,0.234589,0.076146,-0.271665,0.647995,-0.033125,-0.321615,-0.481023,0.098893,0.226766,0.388347,0.700142,-0.039956,-0.013665,0.122395,0.485383,-0.259499,-0.203969,0.181832,0.246787,-0.012396,0.378270,-0.076723,-0.002154,0.067443,0.009263,-0.422667,-0.532456,0.288850,0.155142,0.068286,-0.458418,0.644469,-0.012481,-0.210781,0.214938,-0.175873,0.310001,0.236444,0.236925,0.220636,-0.106524,-0.125188,-0.609230,0.353192,0.889929,0.119739,-0.290237,0.461780,0.047320,-0.544372,-0.084732,-0.315775,-0.359572,0.289752,0.288345,-0.107988,0.083734,-0.353096,-0.582496,-0.149753,-0.073829,-0.518765,0.055309,-0.485316,0.008555,-0.836604,0.024934,-0.161077,-0.344454,-0.031004,-0.066541,-0.473807,0.761665,-1.074372,0.178686,0.726821,0.169756,-0.341967,0.888438,-0.010800,0.181404,0.048348,-0.015247,-0.237232,-0.026459,0.047363,-0.024657,0.608521,0.107113,-0.395041,-0.477376,0.6