INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293729', '急冻奇侠', '喜剧', '故事开始于明朝，凤三（元华 饰）心肠歹毒，无恶不作，身为锦衣卫，同时又是凤三的师弟，方守正（元彪 饰）发誓要将凤三绳之于法。然而，凤三此人诡计多端，甚至想要偷取能够扭转时空的黑玉佛，借此逃脱法网，几番争斗之后，两人双双跌落山崖。时光荏苒，转眼已是现代，考古队在雪地中挖掘出了凤三和方守正被冰封住的尸体，将两人运往美国研究，然而，途中一场意外却令两人死而复生。方守正于机缘巧合之下遇见了名为阿玉（张曼玉 饰）的不良少女，阴差阳错的成为了她的保镖，而凤三不改奸邪本性，加入了黑社会，继续为非作歹。当方守正得知凤三依旧作恶多端后，他决定继续自己未完成的使命。©豆瓣', '元彪', '霍耀良', 6.6, 5446, 'tt0097618', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2607935948.jpg', 1.2, 8.2, 56.7, 25.8, 8, '0.115726,0.216280,-0.545524,0.321502,0.029288,-0.271158,0.369745,0.008557,-0.658033,-0.044927,0.284195,0.483815,-0.310349,0.107302,0.032709,-0.095573,-0.161002,-0.770650,-0.292751,-0.144473,-0.323821,-0.366059,-0.426739,0.004828,-0.275958,-0.218227,0.766816,0.276160,-0.206903,0.361298,0.306697,0.336251,-0.458478,0.404177,-0.405230,-0.021672,0.031469,0.021527,-0.323784,0.237477,0.078795,-0.552522,-0.207630,0.085520,-0.195788,0.220658,0.691619,-0.308159,-0.051177,-0.379457,0.226077,-0.178996,-0.171688,0.146846,0.221712,0.111106,0.135356,0.286499,-0.128305,-0.194332,0.376651,-0.029511,-0.383623,0.013294,0.148090,0.056111,-0.483049,0.237768,-0.006703,0.055698,-0.014311,-0.321605,0.113023,0.342173,0.551772,0.087112,-0.132632,-0.151265,-0.551898,0.217521,0.459073,-0.063159,-0.114197,0.421578,0.301936,-0.404376,0.196114,-0.180487,0.020608,-0.076015,0.468848,0.267827,-0.249135,0.216526,-0.304517,-0.131482,-0.542314,0.219551,-0.176813,-0.242878,-0.232268,-0.257774,-0.204826,-0.118077,-0.148373,0.083256,-0.060255,-0.208984,0.411115,-0.740011,0.207139,0.458683,0.010413,-0.343007,0.304155,-0.041734,0.257167,0.064510,0.044749,-0.072508,0.015154,0.446498,0.349036,0.345427,-0.229503,-0.135799,-0.283905,0.146362', '30345227', '1301022', '35030151', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293731', '忠奸人', '剧情', '为了对付黑社会，联邦调查局的探员皮斯顿（约翰尼•戴普 饰）不得不告别妻子和三个女儿，化名唐尼•布拉斯科打入黑帮鲁吉罗家族卧底。为了取得帮派内部成员的信任，唐尼在头目“老左”（阿尔•帕西诺 饰）的带领下，参加了一系列的犯罪活动，也逐渐掌握了他们的犯罪证据。然而，长时间的相处中，“老左”对唐尼信任有加，唐尼也见识到“老左”温情的一面，慢慢地对他产生了敬佩之情，傍徨不定，不再向上级及时汇报情况；同时，由于卧底工作的特殊性，唐尼极少和妻女见面，家庭生活濒临崩溃。此时，帮派内部的仇杀开始了，“老左”的上级黑桑铲除异己，掀起了一场腥风血雨。唐尼也将面对或“忠”或“奸”的抉择。©豆瓣', '阿尔·帕西诺', '迈克·内威尔', 8.1, 46669, 'tt0119008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2212201036.jpg', 0.2, 1.2, 18.9, 50.7, 29, '0.178036,0.023922,-0.485606,0.609833,-0.019245,-0.189766,0.597084,0.223260,-0.461316,-0.270681,0.095915,0.587627,-0.071568,0.319368,0.119401,-0.412856,-0.472459,-0.805514,-0.457833,-0.051847,-0.286921,-0.605588,-0.412620,-0.430606,-0.148019,-0.256811,0.414309,0.095352,-0.212227,0.534682,0.404813,0.353468,0.027766,0.380875,0.177128,0.028093,0.278935,0.018180,-0.735957,0.094610,0.199697,-0.139399,-0.116598,0.065237,0.197294,0.579309,0.533970,-0.384004,-0.008193,-0.269409,0.182820,-0.260067,0.032902,0.102223,0.606185,0.121314,0.052842,0.434539,-0.256740,0.084415,-0.057587,0.059837,-0.799344,0.063492,0.117394,0.070888,-0.603198,0.294497,-0.100329,0.082104,-0.008263,-0.337265,0.094374,0.259846,0.240674,0.294834,-0.148432,0.195960,-0.239151,-0.056543,0.851906,0.164947,-0.123888,-0.222510,-0.071781,-0.462370,-0.066895,-0.431271,-0.126789,-0.297570,0.476236,-0.203417,0.112167,0.479053,-0.394645,-0.159210,-0.214597,-0.123051,-0.030643,-0.381305,0.388594,-0.815429,-0.405543,-0.339100,-0.189439,0.054297,0.169886,-0.308841,0.475980,-0.771239,0.204208,0.331658,0.184771,-0.695156,0.586687,0.392941,0.155309,-0.423100,-0.256153,0.251875,0.362263,0.273694,0.317371,0.162616,-0.247967,-0.301243,0.177197,0.113024', '4301278', '1293265', '26678784', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293732', '福星高照', '喜剧', '警界败类三哥（林正英 饰）席卷价值近一亿元的珠宝逃往日本，虽有鸡骨草（成龙 饰）和独角金（元彪 饰）两位干探跟踪追捕，但三哥仍为日本黑社会头目松本所救，鸡骨草二人也陷入危机。迫于公众形象限制，香港警方不愿动用本土警力。曹警司（曹达华 饰）找到正在服刑的罪犯鹧鸪菜（洪金宝 饰），希望借助他的力量将三哥引渡回港。鹧鸪菜随后集结孤儿院的好友花旗参（秦祥林 饰）、犀牛皮（冯淬帆 饰）、大生地（吴耀汉 饰）和罗汉果（曾志伟 饰）。在曹警司的威逼利诱下，五个笑料不断的和女警探霸王花踏上前往日本的旅程……©豆瓣', '洪金宝', '洪金宝', 7.5, 26949, 'tt0089177', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2548038400.jpg', 0.4, 2.6, 35.8, 43.1, 18, '-0.168370,-0.120240,-0.398096,0.484723,0.240981,-0.032994,0.454013,0.310213,-0.314985,-0.259140,0.170069,0.455838,-0.047139,-0.034177,0.193744,-0.259899,-0.132161,-0.493901,-0.075532,0.058658,0.028530,-0.292392,-0.454004,-0.059330,0.018678,-0.117407,0.584837,0.377518,-0.287477,0.662121,0.499663,0.444010,-0.340495,0.186753,-0.086204,0.103740,0.200090,-0.020009,-0.401242,0.128390,-0.154277,-0.366351,0.225734,-0.150473,0.138951,0.269571,0.604253,-0.107536,0.212452,-0.210084,0.049102,-0.248644,0.009232,-0.112234,0.265017,0.132932,0.140466,0.159859,-0.334100,0.262143,0.348582,0.088150,-0.503829,-0.050615,0.338356,0.052220,-0.516996,0.136023,-0.124285,0.074085,-0.042595,-0.208565,-0.167758,0.333896,0.002721,0.121378,0.129361,0.224319,-0.451583,0.389347,0.393911,-0.041983,0.220658,-0.318283,0.078981,-0.481467,-0.230465,-0.040973,-0.131798,-0.292926,0.410956,-0.175692,0.156218,-0.183083,-0.808771,-0.231649,-0.126610,-0.036664,-0.007447,-0.004200,0.210247,-0.789891,0.106007,-0.451878,-0.162079,0.147976,0.423462,-0.058433,0.499595,-0.378357,0.144807,0.257737,0.305144,-0.694330,0.514336,0.174054,0.021768,-0.414280,-0.191000,0.096424,0.323319,0.370423,0.235099,0.100322,-0.297837,-0.423922,-0.114802,-0.289843', '1294917', '20274039', '1307762', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293748', '甜蜜与卑微', '喜剧', '故事发生在20世纪的30年代，雷（西恩·潘 Sean Penn 饰）是当时红极一时的爵士乐传奇人物。由于早年生活困顿，成名后雷养成了挥金如土的恶习，压抑许久的他放纵自己迷失在由金钱和美女组成的奢侈世界里。一位名叫海蒂（萨曼莎·莫顿 Samantha Morton 饰）的普通洗衣女工深深的爱上了雷，愿意为雷付出一切，而雷亦对单纯的海蒂抱有好感。可是，此时的雷并不想过早的走入安定的家庭生活，更何况，雷可是一位艺术家啊，对于艺术家来说，婚姻难道不正是灵感的坟墓吗？就这样，雷和海蒂渐行渐远。之后，雷娶了性感妖娆的作家布兰奇（乌玛·瑟曼 Uma Thurman 饰），却发现布兰奇是比自己还要放浪形骸的“交际花”。直到此时，雷才想起了海蒂的好，可是雷没有把握，这个单纯可爱的女孩如今还会一如既往的包容他，接纳他吗？©豆瓣', '西恩·潘', '伍迪·艾伦', 7.8, 5778, 'tt0158371', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1261996807.jpg', 0.3, 1.8, 26.3, 50.4, 21.3, '0.337085,0.201114,-0.648496,0.454673,-0.167327,-0.226806,0.907870,-0.008583,-0.531214,-0.534348,-0.261854,0.521779,-0.025126,0.300393,0.417509,0.138338,-0.148650,-0.637963,-0.047613,0.030820,-0.175659,-0.542200,-0.409624,-0.246846,-0.205102,-0.600916,0.467389,0.464135,-0.302490,0.181528,0.299956,0.360717,0.227693,0.427331,-0.253853,-0.110889,-0.032486,0.524555,-0.002178,0.022613,-0.002994,-0.030858,-0.052858,0.140884,0.157295,0.301610,0.238377,-0.444753,-0.385518,-0.044652,0.501483,-0.119928,-0.106870,-0.080097,0.028028,-0.274035,0.189968,-0.045840,0.051823,-0.003916,0.076518,-0.256656,-0.756735,0.008775,0.230794,-0.083572,-0.614407,0.650036,0.056321,-0.182879,-0.106922,-0.116421,0.123406,0.146681,0.322150,0.388705,-0.201872,0.112605,-0.306255,0.307521,0.742340,0.407569,-0.450600,0.574819,-0.663888,-0.519801,-0.356320,-0.310618,-0.573586,0.081437,0.148118,0.161171,0.018551,0.258930,-0.333647,-0.114764,-0.032224,0.123662,-0.002632,-0.341806,-0.236144,-0.325360,-0.139426,-0.692350,-0.141067,0.224141,0.018380,-0.450080,0.823221,-0.971645,0.319556,0.246214,0.111039,-0.612198,0.747676,0.150778,-0.245393,-0.266606,-0.143617,0.597908,-0.005780,-0.195735,0.092909,0.278440,-0.161174,-0.173399,-0.135733,0.711120', '1303112', '26283288', '26354526', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293749', '生活多美好', '剧情', '乔治（詹姆斯•斯图尔特 James Stewart 饰）在圣诞节前准备自杀，这时上帝传来旨意，派天使拯救他，并让他了解到自己一生的使命——拯救那些不幸的人。乔治小时候左耳有疾，在贝德福德镇上的一家药店帮工。他很机灵，深得老板器重，同时也很招女孩喜欢。某日，老板接到爱子死亡的电报，悲痛欲绝，配错了药，幸亏乔治才化险为夷。乔治从小嫉恶如仇，尤其看不惯富人专横跋扈。长大后，乔治一表人才，准备去读大学。这时，他的父亲去世了，他子承父业，协助叔父料理公司事务。然而公司经营状况不佳，在董事会会议上面临破产。如果公司破产，小镇将会有很多家庭陷入困境。乔治力排众议，说服了董事会，但是条件是他要担任董事会秘书长。这与他的大学梦相去甚远。而且，此时他还陷入了对一个女孩的爱恋之中……©豆瓣', '詹姆斯·斯图尔特', '弗兰克·卡普拉', 9.3, 88263, 'tt0038650', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p771490367.jpg', 0.2, 0.4, 4.7, 24.7, 70.1, '-0.137125,0.071137,-0.583772,0.382491,-0.137326,-0.381482,0.392061,0.559867,-0.612891,-0.444047,0.173557,0.804014,0.099035,0.389735,0.411890,0.066718,-0.242633,-0.379868,0.127057,-0.085200,-0.222960,-0.379917,0.160137,-0.501035,-0.138757,-0.215846,0.382767,0.111147,0.079915,0.347687,0.132622,0.405171,0.304884,0.512658,-0.180737,0.106649,0.252656,-0.004076,-0.365631,0.198592,0.226631,-0.068042,-0.014704,0.127957,0.297001,0.276949,0.245548,0.080550,-0.232739,-0.278266,0.388628,-0.271622,-0.096115,0.036038,0.545706,0.056807,0.013895,0.371691,-0.375738,-0.254894,-0.288840,-0.201544,-0.630475,-0.125420,0.052400,-0.063216,-0.680220,0.308050,-0.179845,0.317231,-0.027892,-0.349740,0.114520,0.491854,-0.022105,0.287155,-0.008376,0.247064,-0.602114,0.136892,0.813818,-0.124627,0.053044,0.275179,-0.255286,-0.422184,0.172342,-0.246203,-0.425524,0.310527,0.160439,-0.139321,-0.085667,0.071163,-0.144565,-0.198456,-0.086298,-0.126617,0.236592,-0.427799,-0.128407,-0.521123,-0.127751,-0.069178,-0.347430,-0.160296,-0.028680,0.008716,0.661552,-0.806858,0.119779,0.455614,0.283456,-0.568515,0.863737,0.131209,0.007970,-0.454434,-0.082354,0.310322,0.171573,0.172472,-0.103347,-0.012665,0.141609,-0.488116,-0.237632,0.340868', '25721544', '2990737', '1302384', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293750', '斯大林格勒战役', '剧情', '斯大林格勒战役是二次大战中德国遭到的史无前例惨败的一役，也是欧洲战场的一个重大转折点。苏联红军用自己的血肉之躯挡住了德国炮弹和飞机的轰炸，但被战争涂炭的不仅仅是一个国家。这部影片从德军的独特角度深刻探讨了战争对人性与生命的摧残。', '多米尼克·霍卫兹', '约瑟夫·维尔斯麦尔', 8.2, 12211, 'tt0108211', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1715755311.jpg', 0.4, 1.5, 17.7, 48.4, 31.9, '0.211364,0.038660,-0.801776,1.015218,0.138430,0.075843,0.847925,-0.474551,-0.280512,0.351825,0.583811,1.075008,-0.066693,-0.326425,0.101886,-0.108769,0.134016,-0.961332,-0.315844,0.398415,-0.787366,-0.629743,-0.793988,-0.268898,-0.021724,-0.415411,1.028300,0.590156,-0.901266,0.355640,0.190446,0.468925,0.362904,0.683972,-0.250894,-0.070350,-0.329163,-0.041893,-0.380321,0.340855,-0.098236,-0.466831,-0.280008,0.668776,-0.554474,0.622762,0.790254,-0.385184,-0.067404,-0.352279,0.454887,-0.696438,-0.175706,0.375197,0.581606,0.046164,-0.053976,0.352569,0.049300,0.044470,-0.113497,-0.059925,-1.071669,-0.354864,-0.102215,-0.229679,-0.480160,1.085593,-0.186829,0.073668,0.101645,0.031800,0.497022,0.755447,0.442360,0.452044,-0.607112,-0.015716,-0.521268,0.416399,0.665957,-0.307928,-0.709208,0.433924,-0.382341,-0.523995,-0.116724,-0.879274,-0.337748,0.198849,0.394587,-0.504778,-0.192556,0.516132,-1.084776,0.446955,-0.618144,-0.915800,-0.177373,-0.353668,-0.004259,-0.789941,-0.532488,-1.031602,-0.638913,0.296762,0.174432,0.289750,1.202869,-0.683957,-0.249702,0.676927,0.127885,-0.325627,0.814746,0.340484,-0.080511,-0.076274,0.352662,0.441840,-0.193328,0.144732,-0.161325,0.435443,0.314273,0.025233,-0.325413,0.838852', '27602116', '1303542', '1478066', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293753', '十月的天空', '剧情', '本片根据真实故事改编。1957年，苏联卫星发射成功，美国民众萌发了危机意识。一个矿井小镇的普通高中生霍默（杰克·吉伦哈尔 Jake Gyllenhaal 饰）此刻却为自己的未来忧虑，他在球队选拔中落选，而体魄强健的哥哥一直更受父亲约翰（克里斯·库珀 Chris Cooper 饰）认可，不甘于平庸的霍默萌生了制作火箭的想法，在老师和朋友们的支持下，霍默全身心投入了研究，老师更带来了他可以通过火箭制作进入大学学习的机会。而另一方面，身为矿井负责人的约翰希望儿子继承矿井，对他的研究加以阻扰，同时警方也为山林失火事件终止了霍默的活动，这个年轻人还能获得自己想要的成功么？©豆瓣', '杰克·吉伦哈尔', '乔·庄斯顿', 8.7, 39552, 'tt0132477', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p452602741.jpg', 0.1, 0.4, 8.7, 43.4, 47.3, '-0.025057,-0.030174,-0.502373,0.703882,-0.174108,-0.261224,0.340548,-0.043438,-0.512435,-0.201023,0.131106,0.712051,-0.004677,0.097884,-0.053052,-0.180436,-0.430977,-0.482814,0.058325,-0.072626,-0.161532,-0.613893,-0.330672,-0.587746,-0.235912,-0.393186,0.907969,0.012366,-0.204874,0.319370,0.068826,0.331723,0.348548,0.233317,-0.161358,-0.038570,0.202351,-0.014904,-0.384113,0.300638,0.006394,-0.042635,-0.137187,0.116141,0.165548,0.304648,0.619530,-0.022378,-0.194092,-0.244364,0.377950,-0.146938,0.198124,0.038942,0.203676,0.143049,0.103835,0.226686,-0.064396,0.126279,-0.084315,-0.233771,-0.839909,-0.249857,0.097426,0.081015,-0.501211,0.297482,-0.175613,-0.009756,0.126290,-0.232899,-0.081748,0.368657,0.198676,0.286755,-0.467718,-0.014931,-0.209954,0.351457,0.539797,-0.215922,-0.222111,0.408912,-0.491053,-0.503385,0.034006,-0.173121,-0.477396,-0.034772,0.306447,0.093978,-0.021292,0.294383,-0.450697,-0.081035,-0.195362,-0.345123,-0.010541,-0.439633,0.202061,-0.624844,-0.083610,-0.002791,-0.258546,-0.202691,0.107081,-0.433968,0.949634,-0.841315,0.215398,0.619229,0.247451,-0.607611,0.428231,-0.000001,0.054896,-0.460033,-0.248438,0.173112,-0.117629,0.278398,-0.089832,0.351083,0.108128,-0.422661,-0.406052,0.468824', '27602116', '25880986', '35262731', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293755', '驱魔人', '恐怖', '愁云惨淡的华盛顿市，一幢普通公寓内，单身妈妈克莉丝（艾伦·鲍斯汀 Ellen Burstyn 饰）和女儿芮根生活于此。然而近一段时间，克莉丝却被女儿种种怪异的举止折磨得烦躁不堪。芮根的行为举止怪异，迥异常人。克莉丝带她求医问卜，终无所获，甚至精神科医生也束手无策。万般无 奈之下，几近绝望的母亲求助于莫林神父（马克斯·冯·西多 Max von Sydow 饰），一个有着丰富驱魔经验的老者。恐怖的夜晚，神父与藏身少女体内的恶魔展开连番较量。这是一个注定让无数人永生难忘的恶魔之夜……本片由William Batty根据1949年一起真实的驱魔事件创作的小说改编，荣获奥斯卡金像奖最佳混音奖和最佳改编剧本奖。©豆瓣', '艾伦·伯斯汀', '威廉·弗莱德金', 7.6, 71442, 'tt0070047', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1495239725.jpg', 0.8, 3.4, 29.1, 45.8, 20.8, '0.052462,-0.228736,-0.310191,0.652600,0.299196,-0.106050,0.826527,-0.081567,-0.579927,-0.295301,0.113760,0.628577,-0.245923,0.205044,0.269357,-0.164796,-0.151974,-0.509762,-0.302347,0.081926,-0.080420,-0.359435,-0.441275,-0.346325,-0.163801,-0.323714,0.556408,0.108865,-0.000530,0.636152,0.212379,0.401459,-0.390341,0.072086,0.138170,-0.121480,0.155995,0.054071,-0.265476,0.078824,0.244879,-0.074241,-0.246577,0.130775,0.007508,0.299945,0.621690,-0.332486,-0.387126,-0.130450,0.597137,0.080916,-0.245215,0.204358,-0.124918,-0.037174,0.348930,-0.072414,-0.095709,-0.091454,0.034802,-0.036555,-0.783050,0.038627,0.282737,-0.011415,-0.276357,0.285175,-0.092131,0.068677,0.061480,-0.093393,0.041789,-0.056583,0.411609,0.443053,0.056325,-0.208125,-0.152842,0.382914,0.470859,0.206831,-0.588740,0.163488,-0.627607,-0.428989,-0.089456,-0.459739,-0.587281,0.203336,0.098673,0.001020,0.141946,0.227528,-0.308144,-0.153197,-0.384167,0.000443,-0.304540,-0.119985,-0.047884,-0.686695,-0.086152,-0.218576,-0.241970,-0.112788,0.229348,-0.369739,0.684785,-0.537435,0.397451,0.257127,0.065782,-0.167739,0.547518,-0.006724,0.196649,-0.176071,-0.297387,0.576611,-0.046448,0.090106,0.118247,0.244651,-0.055729,0.208100,-0.468860,0.509424', '2133337', '1307884', '2027945', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293759', '英雄本色3：夕阳之歌', '动作', 'Mark哥（周润发 饰）和志民（梁家辉 饰）是堂兄弟，两人是越南华侨，现正在香港发展。岂料越战打响，两人都十分担心仍然居住在越南西贡的志民的父亲松叔的安危，为了凑足钱将志民父亲接到香港，两人决定帮当地黑帮走私军火到越南。岂料他们在越南遭到了丧邦的伏击，关键时刻幸亏香港黑帮老大的女友英杰（梅艳芳 饰）及时相救，两人才幸免于难。逃过一劫的三人在西贡渡过了一段快乐时光后，英杰辞别了两人。随后Mark哥和志民将松叔顺利接回了香港。回港后，两人过着安稳平静的生活，只是一直都没有打听到恩人英杰的消息。突然有一天，英杰出现了，重逢令三人都十分开心。只是，一场祸事也在悄悄逼近……©豆瓣', '周润发', '徐克', 7.5, 54401, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2348693150.jpg', 0.6, 4.1, 34.3, 40.1, 20.8, '0.110539,-0.217302,-0.788765,0.045699,0.305125,-0.417212,0.193548,0.154058,-0.657249,0.095430,0.423118,0.723649,-0.020894,0.002927,0.270271,-0.056661,-0.381537,-0.641278,0.133150,-0.080044,0.012942,-0.181544,-0.210612,0.034613,-0.179626,-0.316929,0.156035,0.067823,0.105997,0.912697,0.010854,0.031463,-0.351675,0.649796,-0.348306,0.284048,0.191391,0.181759,-0.843185,0.316616,0.137773,-0.377111,-0.337589,0.017680,0.216707,0.267942,0.523224,0.093580,-0.182502,0.252586,-0.105621,-0.427751,-0.270679,-0.126225,0.530532,-0.113477,0.317560,0.376824,-0.446947,0.029335,-0.048962,0.135508,-0.470760,0.208715,0.147767,0.201559,-0.676274,0.553470,-0.114255,-0.137960,0.063303,-0.682099,0.343220,0.759410,0.017336,0.096181,-0.323870,0.197792,-0.523040,0.351821,0.839101,-0.237238,0.097004,0.165646,0.300945,-0.253622,0.114063,-0.229508,-0.318552,-0.019581,0.386012,-0.156385,-0.249129,0.103745,-0.551879,0.066663,-0.364800,-0.320577,0.045640,-0.273979,-0.053114,-0.573456,-0.278367,-0.349902,-0.251867,0.104687,0.074984,-0.086103,0.653211,-0.735040,0.148926,0.407202,0.505337,-0.285512,0.437243,0.212446,0.164064,-0.262467,-0.091010,-0.307885,0.056360,0.359240,0.279474,0.183205,-0.284227,-0.320361,-0.048212,-0.133670', '1451563', '1302987', '2209368', '25856453');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293760', '捉鬼敢死队', '喜剧', '三名大学教授彼得·温克曼（比尔·默瑞 Bill Murray饰）、雷蒙德·斯坦兹（丹·艾克罗伊德 Dan Aykroyd饰）和艾根·斯宾格勒（哈罗德·雷米斯 Harold Ramis饰）专门研究鬼怪灵异之事。他们决定离开校园实验室，组成“捉鬼大队”。他们用最新的科学仪器，对付在纽约市出没的无数大鬼小鬼，取得成功。可政府部门却将他们视为江湖骗术。直到有一天，一群邪恶的魔鬼包围了整座纽约市，并附身于美女德纳（西格妮·韦弗 Sigourney Weaver饰）身上时，众人终于意识到了事态的严重。这只“捉鬼大队”是否能够拯救纽约，让魔鬼无所遁形呢？本片荣获1985年第57届奥斯卡金像奖，最佳视觉效果、最佳原创歌曲提名，被誉为影史上最受欢迎、最好笑的喜剧之一。©豆瓣', '比尔·默瑞', '伊万·雷特曼', 6.7, 15376, 'tt0087332', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2250091060.jpg', 1.4, 8.9, 50.1, 30.9, 8.6, '0.111162,-0.226156,-0.616009,0.474881,0.440700,-0.168337,0.429357,-0.091606,-0.309469,-0.256260,-0.014638,0.332289,-0.368452,0.069416,0.342512,0.060806,-0.403515,-0.585481,-0.090891,-0.377881,-0.311195,-0.040359,-0.562522,-0.247020,0.053693,-0.246004,0.432153,-0.054134,-0.205601,0.257146,0.515200,0.601756,-0.022428,0.006950,-0.007617,-0.070660,0.456994,-0.282045,-0.162517,0.354038,-0.293295,-0.107513,-0.286573,-0.069738,0.106840,-0.003418,0.577545,-0.448781,-0.002599,-0.064141,0.239496,-0.436730,-0.107462,-0.026101,0.149255,-0.498509,0.208154,0.156037,0.039075,0.152917,0.039393,-0.155904,-0.709102,-0.086870,0.017269,0.219009,-0.149620,-0.124528,-0.064273,0.270021,-0.044979,-0.079309,0.147852,0.089145,0.183837,0.175669,0.222681,-0.066510,-0.368857,0.199917,0.265983,-0.105957,-0.462742,0.010535,0.103006,-0.547883,-0.253720,-0.203252,-0.036124,-0.034163,0.388880,-0.035392,0.181587,0.294823,-0.558876,-0.286346,-0.182085,-0.085009,-0.130870,-0.085656,0.097458,-0.852984,0.081202,-0.095396,-0.045284,0.131463,0.155746,-0.155469,0.561951,-0.271167,0.400320,0.537977,-0.160883,-0.106512,0.424865,-0.064627,0.117270,-0.237625,-0.345534,0.154541,0.296723,0.405129,0.151740,0.390312,0.086703,-0.275191,-0.210743,0.389241', '3318306', '1293433', '4014397', '30143331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293764', '与狼共舞', '剧情', '邓巴中尉（凯文•科斯特纳 Kevin Costner 饰）在南北战争中立了大功，政府为了褒奖他，给了他任意选择驻地的特权。邓巴渴望着一种全新的生活，于是选择了遥远偏僻的西部哨所塞克威克。这里住着大量的印第安苏族人。一开始苏族人把他的到来有着抗拒，当邓巴主动接近和了解他们的生活，并搭救了一个从小在苏族长大的白人少女后，族人和他之间的关系开始回暖。他得到了一个印第安名字：与狼共舞。邓巴的骑术让族人惊叹，他的善良被大家称赞，和白人少女也日久生情。一次对抗外族入侵的战争中，邓巴更是被封为了苏族人的民族英雄。然而马背文化的没落已成必然，白人士兵来到这片土地，驱赶苏族人，捕捉“叛徒”邓巴，这片朴实的土地慢慢改变了容颜……©豆瓣', '凯文·科斯特纳', '凯文·科斯特纳', 8.9, 78240, 'tt0099348', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p499158228.jpg', 0.2, 0.4, 7.7, 35.4, 56.4, '0.205060,0.129194,-0.751052,1.031672,-0.251811,-0.160118,0.626165,-0.067393,-0.421897,-0.209069,-0.012068,0.830705,0.146405,0.300386,0.495900,0.032997,-0.143522,-0.499283,-0.174421,-0.226495,-0.521584,-0.510633,-0.239346,-0.628862,-0.321694,-0.112493,0.592644,0.341925,-0.422080,0.462713,0.228065,0.045275,-0.039242,0.509531,-0.180321,-0.066917,-0.065044,-0.344944,-0.310301,0.074930,-0.074751,0.026491,-0.110105,0.367415,-0.051865,0.277166,0.523942,-0.563874,0.079496,-0.173051,0.126999,-0.236603,0.288799,0.043699,0.435814,-0.141504,0.073325,0.022397,-0.002199,-0.115662,0.091727,-0.199947,-0.407714,0.056498,-0.037513,0.031149,-0.602723,0.621457,0.238932,0.068338,-0.084266,-0.175740,-0.017854,0.467289,0.336950,0.320540,-0.048076,0.029185,-0.397859,0.089882,0.587578,-0.202543,-0.381233,-0.058026,-0.484649,-0.715095,-0.086591,-0.280455,-0.615000,-0.257470,0.518511,-0.005117,-0.085788,0.433547,-0.701771,-0.089253,-0.206222,-0.151204,0.160804,-0.320423,-0.022755,-0.338278,-0.141145,-0.159269,-0.233687,0.237250,-0.002771,-0.119847,0.974968,-0.776092,0.083783,0.394828,0.492217,-0.686474,0.466595,-0.136952,0.340967,-0.074286,-0.171063,0.729181,0.315625,0.326236,0.411942,0.211332,-0.300969,0.117552,-0.135764,0.408038', '26348103', '1426819', '1870681', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293765', '白发魔女传', '动作', '明末年间，中原与金国边境战火硝烟四起，姬无双（吴镇宇 饰）的魔教大行肆虐。朝廷与武林联合抗敌。武当派首徒卓一航（张国荣 饰）自幼桀骜不驯，但天资过人，极受掌门紫阳真人看重。卓一航幼年奇遇不断，先后结识了当时还只是武官的吴三桂（高雄 饰）与神秘的狼女（林青霞 饰）。成年后的卓一航为人正直，但浪子本性不改，不愿受礼教束缚，仗义行侠却屡屡受指。大师姐（蓝洁瑛 饰）对其倾心，卓一航却毫不动心。再次偶遇狼女，卓一航心生爱意，狼女亦为之倾心。然后正邪不两立，有情人面对诸般艰难险阻，终是黯然收场……©豆瓣', '张国荣', '于仁泰', 7.7, 78279, 'tt0106342', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p958927779.jpg', 0.3, 2.2, 28.6, 48, 20.9, '-0.056041,0.120260,-0.477209,0.624688,0.299958,-0.149867,0.363990,0.142771,-0.576455,-0.208165,0.134596,0.553513,-0.134345,0.121279,-0.051780,0.008208,0.281123,-0.652520,-0.209810,-0.003335,0.253430,-0.162372,-0.171654,0.141064,-0.483191,-0.058865,0.613594,0.285005,-0.223138,0.669383,0.400437,0.232881,-0.316848,0.585009,-0.186741,-0.087013,-0.154486,0.283356,-0.367546,-0.253177,-0.247810,-0.418004,-0.400630,0.058385,-0.415690,0.404120,0.324657,-0.288083,-0.175822,-0.524579,0.219820,0.028231,0.016843,0.199720,0.173057,-0.072534,0.398237,0.420659,0.404789,-0.073359,-0.144689,0.076318,0.014193,0.031424,0.355864,-0.110745,-0.190347,0.628084,-0.250475,-0.225045,-0.303808,-0.122195,-0.315303,0.205369,0.459684,-0.123253,-0.057902,-0.120804,-0.225089,0.254891,0.529997,0.195660,-0.137208,0.111279,0.160824,-0.449548,0.283448,-0.509215,-0.434133,0.004108,0.284612,0.053842,0.136991,0.739537,-0.268642,0.008202,-0.349747,0.599375,0.031031,-0.123436,0.125052,-0.290624,-0.341491,-0.739382,-0.424487,-0.076299,0.539245,-0.093201,0.820630,-0.803869,-0.114907,-0.022139,0.126655,-0.596366,0.339347,0.230076,-0.090127,0.182286,-0.354501,0.369916,-0.087179,0.085275,0.030249,0.219880,-0.026051,-0.127450,-0.029151,-0.148096', '1480318', '35030151', '25922902', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293767', '金色池塘', '剧情', '由厄内斯特·汤普森编剧的本片，描述退休的老教授与老伴在新英伦湖畔的度假屋中度假，在平静的日子里却面临年老的各种危机。他的女儿刚离了婚，正处于徘徊的心境。一向关系不佳的两父女，终于因为十三岁的孙子跟祖父母同居了一段日子而解开了各种心结……本片曾获最佳改编剧本、最佳男主角、最佳女主角三项金像奖，使凯瑟琳·赫本成为影史上唯一的四届金像奖影后，亨利·方达也在病床上如愿地获得了他渴望已久的奥斯卡奖。©豆瓣', '凯瑟琳·赫本', '马克·雷戴尔', 8.8, 25792, 'tt0082846', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1211238404.jpg', 0.2, 0.5, 9, 40.4, 49.9, '0.103105,-0.061047,-0.548603,0.588853,0.177742,-0.551809,0.546143,0.220574,-0.587757,-0.292078,0.295885,0.965833,-0.249594,0.568600,0.439198,-0.171497,-0.353377,-0.783764,-0.120493,-0.073156,-0.172622,-0.387973,-0.602892,0.240684,-0.180702,-0.293540,1.030699,-0.026938,-0.041291,0.432608,0.384324,0.095758,0.010924,0.169109,-0.321216,0.257037,0.182106,0.174968,-0.521384,0.282842,0.183743,-0.379312,-0.296003,0.034269,0.220668,0.323996,0.659146,-0.318541,-0.012993,0.304755,0.550239,-0.251974,-0.216901,0.014125,0.274588,-0.017649,0.424542,0.294213,-0.290552,-0.134226,-0.081024,-0.253167,-0.556614,0.086602,-0.036977,0.248494,-0.574973,0.474203,-0.034042,0.043710,0.065402,-0.077012,0.224219,0.513930,0.116281,0.561574,-0.392771,0.052190,-0.142321,0.468575,0.388639,-0.075423,-0.235525,0.402624,-0.117305,-0.413781,0.001621,-0.350888,-0.599510,-0.159887,0.323364,0.190764,-0.107568,0.246955,-0.411864,0.154929,-0.213194,-0.017212,0.051408,-0.273860,-0.002975,-0.844619,-0.190467,-0.305939,-0.021115,-0.231222,0.112511,-0.434028,0.664987,-0.597548,0.480954,0.134549,0.026300,-0.189248,0.728670,0.182119,0.421806,-0.567896,-0.209528,0.282595,-0.445714,0.114182,0.199088,0.383123,-0.240562,-0.095165,-0.560481,0.774708', '1780122', '1299663', '34795703', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293770', '猎杀U-571', '剧情', '1942年4月，二战期间，大西洋上，德军战舰采取“狼群”战术，令盟军损失惨重。美国海军上尉泰勒（马修•麦康纳 Matthew McConaughey 饰）因抗敌表现出色，曾被许诺晋升艇长，但是却因故不能如愿。这时突然传来敌情，泰勒临危受命，登上S-33老爷级潜艇执行秘密任务，指挥官为上尉迈克（比尔•帕克斯顿 Bill Paxton 饰），同行的还有哈什（哈威•凯特尔 Harvey Keitel 饰）上尉和库南少校等。经过勘察，一艘德军受创潜艇U-571，正在发出求救信号。S-33的任务是伪装成一艘德军的维修舰，以维修作掩护，从U-571上获取德国最先进的译码设备。不过，由于S-33年久失修，水箱等装备已到服役期，若潜入200米以下恐有危险，但是为了完成任务，泰勒等人还是小心驾驶，偷袭了德国军舰，但正在此时，德军的鱼雷也逼近了U-571，他们命悬一线，生死未卜……', '马修·麦康纳', '乔纳森·莫斯托', 8.1, 50202, 'tt0141926', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p734370021.jpg', 0.3, 1.2, 18.3, 52.9, 27.2, '-0.058990,-0.213697,-0.547230,0.460918,0.175019,-0.398696,0.404649,-0.123159,-0.421366,-0.089512,0.365151,0.426489,0.251370,-0.401613,0.302197,-0.123209,-0.750675,-0.244295,0.207152,-0.205659,-0.451348,-0.664815,-0.235762,-0.308662,0.192648,-0.365426,0.838990,0.070735,-0.156156,0.296210,0.046360,0.345910,0.066964,0.516531,0.058215,-0.451590,0.321284,-0.512485,-0.196918,0.188821,-0.277368,-0.215396,0.063711,-0.357290,0.270120,0.600313,0.549924,-0.235767,-0.028726,-0.093084,-0.273342,-0.312446,0.504066,-0.205309,0.380259,0.170973,-0.311762,0.040333,-0.008149,0.208028,-0.218186,0.028275,-0.397677,-0.012127,-0.136265,-0.157203,0.083781,-0.032833,-0.818020,0.512319,0.067685,-0.186533,0.061918,0.701761,0.102526,0.090517,-0.466942,0.340457,-0.507423,-0.057863,0.290288,-0.194338,-0.129632,-0.019948,0.316068,-0.526186,0.171090,-0.486300,-0.131902,-0.029103,0.142051,0.091052,0.289201,0.083775,-0.455167,0.264006,-0.673636,-0.598090,-0.264710,0.109812,-0.096051,-1.015908,0.336966,-0.105725,-0.331112,0.561389,0.147642,0.054606,0.454461,-0.406707,0.129753,0.480965,0.322962,-0.049144,0.336958,0.025913,0.256365,-0.345260,0.164510,0.189517,-0.130607,0.402706,0.067868,0.242333,0.105539,-0.457395,-0.225763,-0.140795', '1293572', '1301444', '1305524', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293776', '女友的男友', '喜剧', '一次偶然之中，布莱莎（Emmanuelle Chaulet 饰）结识了名为莉亚（Sophie Renoir 饰）的女子，志趣相投的两人很快成为了朋友。莉亚年轻开朗，向往炙热燃烧的爱情，显然她那木讷的男友费宾（Eric Viellard 饰）并不能够使她满意。而布莱莎苦苦暗恋着风流倜傥的亚历山大（François-Eric Gendron 饰），可亚历山大已经有了一个个性古怪的女友。看出了布莱莎的心思，莉亚制造了种种的机会让布莱莎和亚历山大独处，可布莱莎总是在重要关头胆怯退缩，但当她和费宾在一起相处时，两人却又有着说不完的话，彼此之间感到十分自在。终于，布莱莎和费宾有了肉体关系，当布莱莎被愧疚困扰之时，却发现莉亚对她隐瞒了一个秘密。©豆瓣', '艾玛奴艾蕾肖莱', '埃里克·侯麦', 8.4, 29096, 'tt0092550', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2201354776.jpg', 0.2, 0.8, 12.2, 50.6, 36.2, '0.338874,0.131313,-1.015435,0.668853,-0.196731,-0.302137,1.044524,-0.028575,-0.691882,-0.276243,-0.019110,0.894104,-0.393600,0.217258,0.065131,-0.045607,-0.086721,-0.744523,0.249857,-0.177058,-0.215524,-0.496765,-0.323039,-0.149931,-0.345922,-0.383355,0.449601,0.119605,-0.154529,0.655176,0.302886,0.257033,0.062956,1.023692,-0.135481,-0.135482,0.208521,0.220703,-0.026614,-0.005672,0.028307,-0.145390,-0.124295,0.416110,-0.097943,0.714348,0.622621,-0.312561,-0.420840,0.202995,0.100754,0.022553,0.077966,0.076148,0.064343,-0.016021,0.184682,0.006504,-0.273456,0.016201,0.031148,0.086502,-0.735567,0.240568,0.083791,0.229225,-0.579771,0.606007,0.193606,-0.440107,0.031768,-0.108680,0.206137,0.379992,0.462786,0.085957,-0.163203,0.064025,-0.371104,-0.077448,0.499669,0.318724,-0.375062,0.842048,-0.525868,-0.462549,0.052589,-0.050607,-0.488787,-0.090917,0.281216,0.320957,-0.170222,0.311855,-0.622180,-0.060842,-0.120180,0.510320,-0.088459,-0.867211,0.104329,-0.284763,-0.450494,-0.724228,-0.710520,0.174640,0.014186,-0.307474,0.721520,-1.032975,0.165461,0.308463,0.286919,-0.487739,0.700142,0.348126,-0.223991,-0.215446,-0.020091,0.437405,-0.276098,-0.107847,0.280254,0.530018,-0.028855,-0.126264,-0.446881,0.547166', '3059036', '34433857', '24756472', '1302054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293778', '科学怪人', '剧情', '奄奄一息的维克多.弗兰肯斯坦（肯尼思·布拉纳 Kenneth Branagh 饰）被北极探险船救起，他告诉了船长沃尔顿（艾丹·奎因 Aidan Quinn 饰）一个令人难以置信的故事。年轻的维克多与父母收养的妹妹伊丽莎白（海伦娜·邦汉·卡特 Helena Bonham Carter 饰）生活在一起，一次他偷取了一本使死人复活试验的医学笔记，并用偷来的尸体创造出了一个全新的生命“创造物”（罗伯特·德尼罗 Robert De Niro 饰）。可是“创造物”并不乐意这样生活，他逃走了企图开始新生，但是他失败了，经历了种种羞辱后他恨透了维克多。在维克多准备与伊丽莎白结婚时，“创造物”回来了，他残忍的杀死了新娘。悲痛欲绝的维克多故技重施，用伊丽莎白的尸体创造了一个再生人，“创造物”认为再生的新娘与自己是一样的，企图占有她，再生新娘以死相抗最后引火自焚。失去一切的维克多抛下一切追逐“创造物”，一直来到北极圈……', '罗伯特·德尼罗', '肯尼思·布拉纳', 7.7, 12971, 'tt0109836', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1413537601.jpg', 0.6, 2.5, 27, 49.2, 20.6, '0.048246,-0.097593,-0.525234,0.528517,-0.393037,-0.477371,0.799264,-0.153760,-0.276561,-0.188760,0.188522,1.011320,-0.029201,0.272633,0.195684,0.256141,-0.335409,-0.499074,0.206507,0.067305,-0.342655,-0.472851,-0.046688,-0.375356,0.070284,-0.365288,0.653488,-0.103141,-0.117631,0.351690,0.209190,0.222521,0.097503,0.291661,-0.354662,0.257866,-0.104417,-0.243274,-0.117594,0.225596,-0.041635,-0.133958,-0.108081,0.345650,-0.253317,0.251681,0.572376,-0.383475,0.078375,-0.360765,0.412654,-0.436435,0.045516,0.299025,-0.042432,-0.026105,-0.151748,0.193607,-0.177452,-0.182093,0.405196,-0.007261,-0.847227,-0.056769,-0.196922,0.009530,-0.847162,0.319077,-0.093254,0.300979,0.136720,-0.164222,0.203324,0.262545,0.176177,0.309721,-0.135516,-0.053559,-0.608695,0.198972,0.554218,-0.267366,-0.253358,0.238526,-0.101477,-0.290491,-0.068681,-0.166397,-0.460130,-0.034211,0.468157,0.005204,-0.291916,0.332638,-0.561602,-0.336325,-0.580655,-0.116299,0.010722,-0.360618,-0.175364,-0.411353,-0.174588,-0.043353,-0.456870,-0.125739,-0.065637,-0.399490,0.511486,-0.578823,0.331847,0.574331,0.333486,-0.419662,0.469665,0.161845,0.107713,-0.178895,0.058160,0.515673,0.182984,0.242510,0.306319,0.327359,0.272977,0.316234,-0.50915