INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293783', '圣女贞德蒙难记', '剧情', '影片聚焦法国民族女英雄圣女贞德（玛利亚·法奥康涅蒂 Maria Falconetti饰）生命的最后时刻，再现了她被出卖落入勃艮第叛军手中后，在英格兰监狱和法庭上，从受审到处死的全过程。被英格兰当局严密控制的天主教会，指控贞德为异端和女巫。法庭上，法官更伪造证据，以信仰问题不断对她施以精神上和肉体上的折磨。面对惨无人道的酷刑与子虚乌有的诬陷，贞德正气凛然、坚贞不屈。最后，贞德被押赴鲁昂市广场，被绑在火刑柱上活活烧死。由一代电影大师卡尔·西奥多·德莱叶执导拍摄的影片《圣女贞德蒙难记》，被称为世界十大最佳影片之一。影片以极具震撼力的艺术表现手法，再现了这段受到天主教会和英国占领军折磨的民族英雄短暂生命中的最后时刻。©豆瓣', '玛利亚·法奥康涅蒂', '卡尔·西奥多·德莱叶', 8.7, 11167, 'tt0019254', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2502229820.jpg', 0.5, 1.2, 10.4, 36.9, 51, '-0.131981,0.295791,-0.603015,0.758665,0.255312,0.073187,0.937220,0.143325,-0.393046,0.168035,0.470086,0.981326,-0.514116,0.058008,0.567730,0.094372,-0.391585,-0.924111,-0.240199,0.028631,-0.311259,-0.557338,-0.095797,0.101186,-0.234127,-0.508399,0.775119,0.030829,-0.426809,0.092330,0.371882,0.635082,0.186564,0.207076,0.037430,-0.013361,0.203899,-0.335503,-0.248851,0.259594,0.180840,-0.534888,-0.043974,0.281229,-0.456505,0.074935,0.562201,-0.499444,0.077225,-0.520222,0.518221,-0.619111,-0.188496,0.420623,0.280724,-0.049182,0.144802,0.562572,0.061688,-0.273335,0.266320,-0.105392,-0.755737,-0.231115,0.051636,-0.040556,-0.480181,0.666307,-0.128682,0.435127,0.155776,-0.062717,0.470494,0.075430,0.379288,0.468062,-0.196079,-0.358394,-0.445779,0.213064,0.314748,-0.165159,-0.425260,0.027481,-0.301147,-0.306781,0.046134,-0.586496,-0.217388,0.017626,0.372216,-0.135258,-0.055004,0.423089,-0.570718,-0.398510,-0.199690,-0.419961,0.017901,-0.446395,-0.005629,-0.848532,-0.264399,-0.283205,-0.151894,-0.038090,0.180738,0.036882,0.694455,-0.370325,0.471424,0.507506,0.263447,-0.210189,0.624091,0.175111,0.059203,0.129018,-0.267584,0.410563,0.269858,0.420163,0.192053,0.139579,-0.072695,0.096261,-0.368288,0.645665', '25837262', '1299663', '30162520', '3597344');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293785', '阿波罗13号', '剧情', '1969年7月20日，乘坐着阿波罗11号的美国人尼尔·阿姆斯特朗成功登陆月球，迈出对人类来说具有重要意义的一大步。与此同时，资深宇航员吉姆·洛维尔（汤姆·汉克斯 Tom Hanks 饰）和亲人好友们通过电视密切关注着这历史性的一刻。吉姆曾乘坐阿波罗8号飞到月球附近，他同样希望在有生之年实现登陆月球的梦想。这个时刻很快来临，就在3个月后，吉姆被任命为阿波罗13号的指挥官，他将连同伙伴佛瑞·德汉斯（比尔·帕克斯顿 Bill Paxton 饰）、杰克·史威吉特（凯文·贝肯 Kevin Bacon 饰）再次升空前往月球。他们满怀着希望，却没想到有无限的磨难等在前方……本片根据真实事件改编，并荣获包括1996年奥斯卡金像奖最佳剪辑和最佳音效奖在内的20多个奖项。©豆瓣', '汤姆·汉克斯', '朗·霍华德', 8.1, 34278, 'tt0112384', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p839197747.jpg', 0.2, 1.1, 19.4, 53.2, 26.1, '-0.027683,0.029494,-0.929570,0.626791,0.256832,-0.154365,0.580314,-0.246690,-0.404661,-0.025117,0.167161,0.753264,-0.416543,0.154095,0.598295,0.008718,-0.694990,-0.501994,0.085158,-0.409715,-0.287993,-0.665163,-0.451701,-0.151897,-0.030454,-0.496361,0.654948,0.053201,0.305201,0.537935,0.343717,0.161875,0.026765,0.399150,0.029036,0.205158,0.363088,-0.201783,-0.456520,0.477205,-0.251178,-0.023181,-0.126182,0.005555,0.066358,0.090253,0.618862,-0.635728,-0.049345,-0.000906,0.276023,-0.336943,0.223347,-0.036310,0.261906,0.117455,-0.250903,0.404816,-0.108573,0.133481,0.102187,-0.253873,-0.635443,0.064896,-0.066266,0.052619,-0.536213,0.373446,-0.520915,0.249472,0.079462,-0.141220,0.116401,0.445754,0.202136,0.292186,-0.213649,0.358599,-0.164191,0.205699,0.498312,0.140661,-0.465225,0.122088,0.115571,-0.407170,-0.309130,0.003457,-0.283904,-0.086564,0.553868,0.315069,0.151949,0.164921,-0.396835,0.181010,-0.184593,-0.488251,0.200588,-0.298716,-0.032017,-1.096102,0.183775,-0.226953,-0.167455,0.000741,-0.164015,-0.425692,0.876007,-0.586143,0.438445,0.550887,0.374296,-0.145870,0.835391,-0.065619,0.170319,-0.526581,-0.129214,0.507805,0.130474,0.243055,-0.048156,0.284785,-0.057110,-0.104948,-0.193644,0.457127', '1293656', '2075345', '3318306', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293792', '异形2', '动作', '蕾普莉（西格妮•韦弗 Sigourney Weaver　饰）是首次探险任务遇到异形后的唯一生还者，她一直冬眠直到被救援队救回地球。当她睁开眼睛后，才发现自己已经冬眠了57年！期间，人类已经移居到了异形所在的星球。蕾普莉知道后，马上向当局报局该星球上异形的情况，但却被当局认为要么精神不正常，要么谎话连篇。蕾普莉见当局对她的说话不予理睬，便决心不再涉足和异形有关的任何事。果不其然，在那个异形所在的那个星球上定居的人忽然和地球中断了联系。这时当局才注意到蕾普莉之前汇报的情况，决定派出军队去营救。蕾普莉被说服参与营救行动。又一场腥风血雨的战斗展开了！©豆瓣', '西格妮·韦弗', '詹姆斯·卡梅隆', 8.1, 139673, 'tt0090605', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2243611590.jpg', 0.3, 1.4, 20, 50.6, 27.7, '0.367743,0.127123,-1.013712,0.451653,0.132984,-0.293937,0.614232,-0.049848,-0.274934,-0.095614,-0.031571,0.517032,-0.207316,-0.260434,0.407523,0.003648,-0.595242,-0.718696,0.101882,-0.322872,-0.620671,-0.395869,-0.164938,-0.326476,0.170859,-0.385735,0.531357,-0.044360,-0.346899,0.472042,0.134769,0.344630,-0.018196,0.710843,0.219131,-0.239484,0.247772,-0.206769,-0.064188,0.368143,0.101915,-0.284358,-0.210829,0.566241,0.142044,0.647934,0.682579,-0.741283,-0.069931,-0.116803,-0.131162,-0.425877,0.090020,0.138157,0.732167,-0.330768,-0.033656,0.196793,-0.047338,0.038822,-0.079824,-0.074586,-0.441402,0.033956,-0.383825,0.264375,-0.389066,0.039492,-0.174253,-0.006384,-0.075406,-0.507167,0.375227,0.909854,0.091897,0.187996,-0.204025,-0.031917,-0.389713,-0.073661,0.787992,0.013842,-0.310793,0.501973,0.142957,-0.747241,-0.187014,-0.195360,-0.222304,-0.030487,0.215821,0.095325,-0.570327,0.156702,-0.612391,-0.241610,-0.522995,-0.542577,-0.176668,-0.231968,0.092511,-0.614268,-0.413731,-0.192887,-0.198943,0.244150,-0.147140,-0.160986,0.540140,-0.796594,0.347455,0.592440,0.447829,-0.764474,0.523604,-0.160512,0.116607,-0.089552,0.330781,0.399343,0.094071,0.554060,0.072736,0.082884,0.413927,-0.393778,-0.238230,0.313053', '1296947', '1419918', '5157137', '2024935');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293798', '鬼娃回魂2', '惊悚', '公仔杀人事件经媒体报道后，引发制作“楚其”的玩具公司对市场前景的担忧，玩具公司将楚其的残骸收回并加以修复，试图向股东证明杀人玩具不过是谣言一场，然而在修复完成时，楚其随即复活，它引发混乱，并最终逃脱。另一方面，安迪（艾力克斯·文森特 Alex Vincent 饰）和母亲分别接受心理治疗，一对好心夫妇暂时照顾安迪。根据灵魂转移的符咒要求，楚其如果要避免与公仔一同人格化的命运，就必须寄宿到第一个知晓它秘密的人——也就是安迪身上，楚其剩下的时间已经不多，它再度找到安迪准备侵占其身体。安迪为了躲避找上门的楚其，用尽办法得到的却是周围大人的不理解与训斥，和安迪一起被收养的少女凯莉也卷入了这场公仔夺取安迪身体的非常事件……©豆瓣', '艾力克斯·文森特', '约翰·拉菲亚', 6.7, 8064, 'tt0099253', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2210573820.jpg', 1.7, 9, 51.2, 27.6, 10.4, '0.175816,0.184753,-0.373478,0.315970,-0.064404,-0.248103,0.668689,-0.141737,-0.318646,-0.357190,-0.035974,0.374974,-0.134505,0.189975,0.197656,0.022896,-0.343608,-0.459420,0.013558,0.217777,-0.392445,-0.562933,-0.185514,-0.398621,-0.103865,-0.400202,0.746763,0.014192,-0.351792,0.220685,0.098576,0.225368,-0.255638,0.629721,0.239162,-0.045673,-0.389695,0.016054,-0.457098,0.426906,0.353062,-0.190540,0.060125,0.329558,0.046079,0.347856,0.660157,-0.378460,0.006610,-0.290419,0.255538,-0.356702,0.095858,-0.017080,0.044451,0.184633,0.186300,0.121152,-0.332659,0.134898,0.324957,-0.040798,-0.720999,-0.205665,0.242094,-0.006923,-0.275031,0.011074,-0.096780,0.279498,-0.037443,-0.438365,0.135739,0.391745,0.303904,0.228892,-0.444509,0.080031,-0.512756,-0.170019,0.429083,-0.163427,-0.133617,0.233996,-0.218653,-0.349613,-0.055806,-0.149120,-0.022150,0.036922,0.371149,0.508043,-0.075615,0.325351,-0.447734,-0.537548,-0.336297,-0.337607,0.128265,-0.500809,0.418263,-0.587820,-0.035412,0.163913,-0.133369,-0.197642,0.268068,-0.491781,0.490536,-0.653284,0.180107,0.494821,0.417283,-0.346801,0.163708,-0.132713,0.391228,-0.342462,-0.114989,0.114184,0.333685,0.224896,0.086691,0.095241,0.452029,-0.238256,-0.409772,0.407353', '26759819', '2369613', '25774050', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293799', '壮志凌云', '剧情', '“独行侠”皮特·米切尔（汤姆•克鲁斯 Tom Cruise 饰）的父亲是个战功显赫的老飞行员，他决心也要成为父亲那样的英雄。终于机会来了，他与军官“笨鹅”尼克·布拉德肖（安东尼•爱德华兹 Anthony Edwards 饰）一起被派到了Top Gun训练基地接受最严格的飞行训练。可是，“独行侠”的训练并不像预想中顺利，他的成绩一直不令人满意，一起训练的”冰人”汤姆·卡赞斯基（方·基默 Val Kilmer 饰）也对他也颇有微词。与此同时，“独行侠”遇到了美丽的女教官查莉（凯莉•麦吉利斯 Kelly McGillis 饰），两人对彼此暗生情愫，这令本来有些心灰意冷的“独行侠”重拾信心。在毕业前的一次训练中，“独行侠”搭档“笨鹅”再次同驾一机，但由于马达发生故障，“独行侠”与“笨鹅”被迫跳海，结果“笨鹅”不幸身亡。这次事件给“独行侠”带来了沉重的打击，本来因学业不顺就郁郁寡欢的他更加消沉了，甚至想要彻底放弃成为飞行员的梦想。“独行侠”最终能否克服心障重回蓝天？', '汤姆·克鲁斯', '托尼·斯科特', 7.7, 89732, 'tt0092099', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1871745733.jpg', 0.4, 2.4, 30.5, 47.3, 19.5, '0.089217,-0.118381,-0.568375,0.528211,-0.004012,-0.479545,0.425861,-0.063385,-0.573179,-0.356246,0.206309,0.674885,-0.090380,0.158624,0.198558,-0.411022,-0.308376,-0.561261,-0.003027,0.004625,-0.219499,-0.498470,-0.149150,-0.241338,-0.203184,-0.165189,0.803502,0.082833,-0.154148,0.496069,0.199576,0.217290,0.363301,0.524337,-0.011377,-0.104192,0.190544,0.132551,-0.172540,0.059218,0.231796,0.034453,-0.099540,0.172820,0.316569,0.383168,0.434755,-0.274456,-0.261666,-0.076857,0.108754,-0.257212,0.050363,0.103600,0.281163,0.042617,-0.034018,0.154685,0.125763,0.099366,-0.191159,-0.068044,-0.579245,-0.004725,0.200650,-0.045686,-0.518078,0.435314,-0.096814,0.072379,0.074146,-0.071585,-0.046209,0.310193,0.458214,0.197638,-0.202510,0.227851,-0.383422,0.216193,0.664853,0.125939,-0.438541,0.286797,-0.348919,-0.595510,0.039480,-0.371456,-0.453395,0.026738,0.288936,0.096198,-0.100924,0.342360,-0.399592,0.033254,-0.332336,0.083326,-0.302253,-0.411654,0.236403,-0.447543,0.095643,-0.394791,-0.335138,0.128108,0.048690,-0.277151,0.615085,-0.941169,0.231453,0.383963,0.134242,-0.443866,0.368863,0.170844,0.141934,-0.222217,0.043144,0.301832,-0.177242,0.219817,0.221013,0.286664,0.001055,-0.382646,-0.067570,0.438035', '35030151', '1301022', '30345227', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293815', '完美风暴', '剧情', '五位船员在茫茫大海中和狂风巨浪搏斗的故事。其中，船长是一个叫比利（乔治·克鲁尼 George Clooney饰）的男人。他刚刚结识了新女友，急需钱来过上新生活。然而附近海域的捕鱼量却一直不景气。除了船长，其余4名船员眼下都需要钱来维持个人的生活。于是，他们决定开往一个相距甚远的海域，就冲着那里丰富的鱼资源。富贵险中求，尽管比利知道前方可能有风暴，比利还是坚决的往前行使。然而，真实情况比他想象的还要糟糕：风暴异常狂暴，他们正在面临出海生涯以来最为严峻的考验。友情和爱情，在这场风暴中愈磨愈坚。©豆瓣', '乔治·克鲁尼', '沃尔夫冈·彼德森', 7.6, 34056, 'tt0177971', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2164583922.jpg', 0.4, 2.2, 30.7, 49.5, 17.2, '0.099793,-0.223102,-0.728809,0.524670,0.235684,-0.227270,0.913170,0.004052,-0.426747,-0.110172,0.149881,0.462587,0.353692,0.067916,0.310438,-0.240623,-0.411652,-0.310644,-0.260006,0.127565,-0.394604,-0.480295,-0.546658,-0.010231,-0.202932,-0.193434,0.533450,0.293692,-0.120207,0.403191,0.164331,0.178380,-0.018146,0.674950,-0.181424,-0.257278,0.052472,0.231358,-0.507643,-0.038773,-0.280740,0.030722,-0.117664,0.182674,0.317936,0.396999,0.382043,-0.187926,-0.077325,0.105598,0.025883,-0.062630,0.009664,-0.093076,0.428277,-0.078312,0.200218,-0.011515,-0.038717,-0.094708,-0.280835,-0.225135,-0.711997,0.030909,0.012187,0.217066,-0.368283,0.216085,0.113211,-0.162144,0.002523,-0.255651,-0.034047,0.334090,0.231589,0.324640,-0.064926,0.137829,-0.477709,0.245460,0.798588,0.009247,-0.333828,0.269421,-0.226307,-0.383128,-0.267748,-0.396321,-0.486331,-0.177604,0.256616,0.173254,-0.180453,0.317486,-0.647115,0.644382,-0.140184,-0.360569,-0.040372,-0.335291,-0.342948,-0.671729,-0.038678,-0.348031,-0.089518,0.231552,0.166966,-0.300781,0.811484,-0.596722,0.080386,0.602641,0.311316,-0.414254,0.523568,0.292868,0.247699,-0.326768,-0.061609,0.244677,0.068839,0.248907,-0.125312,0.179362,0.163326,-0.141357,-0.178690,0.539342', '3005387', '25828589', '1308784', '1308831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293816', '蚁哥正传', '喜剧', '蚂蚁Z对蚂蚁王国的现状十分不满，但天生胆小的他也只能在一边唠唠叨叨，幸好友兵蚁威的保护，瘦弱的Z才不会被欺负。一次偶然机会，Z遇上了逃跑出皇宫的公主宝拉，宝拉因为被母后安排即将与曼将军结婚而不满才离家出走的。在俱乐部里，宝拉主动邀请不起眼的Z跳舞；Z无意中得知了宝拉的身份，跑去和威调换了身份假扮士兵为了能在阅兵中和公主见面。曼将军不仅是个战争狂人，对蚂蚁王国还有着不可告人的阴谋。Z被派上了战场，靠躲在坑内逃过了一劫，被曼将军奉为英雄。但曼将军看出了Z暗恋公主，想把他杀害。情急之下，Z绑架公主逃了出去……©豆瓣', '伍迪·艾伦', '埃里克·达尼尔', 7, 6643, 'tt0120587', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2419081585.jpg', 0.7, 4.6, 47.6, 37.3, 9.7, '0.268391,0.155509,-0.550355,0.694550,0.024849,-0.097161,0.566776,-0.100087,-0.288099,-0.334959,0.307436,0.657148,-0.290581,0.049976,0.130818,-0.117656,-0.069641,-0.428456,-0.190950,-0.200876,-0.324586,-0.444610,-0.295376,-0.275625,-0.090375,-0.471481,0.426056,-0.111397,-0.285995,0.454731,0.460613,0.312896,-0.083322,0.523372,-0.401166,0.054291,0.051440,0.005940,-0.114679,0.346985,0.193295,-0.409172,0.078245,0.315806,0.228773,0.262459,0.716902,-0.842337,0.224279,-0.114472,0.127858,-0.443508,0.202986,0.292412,0.663687,-0.381670,0.318230,0.164188,-0.163964,-0.049924,0.123736,-0.186861,-0.650595,0.139935,0.164053,0.170578,-0.771019,0.409903,-0.162008,0.012850,0.109580,-0.206764,0.608751,0.604294,0.089327,0.193883,-0.146498,0.006496,-0.777601,-0.300114,0.778642,-0.004265,0.240765,0.068074,0.042547,-0.353943,0.441907,-0.536416,-0.257132,0.093575,0.192305,-0.408939,-0.363018,0.157586,-0.330055,-0.194114,-0.569150,0.162972,0.067791,-0.810313,-0.012033,-0.047894,0.089566,-0.033406,-0.111139,0.357394,0.160309,-0.222806,0.458696,-0.898276,0.051136,0.638721,0.533267,-0.624735,0.851681,-0.090504,-0.163738,-0.085784,0.069590,-0.162104,0.284712,0.283941,0.443790,0.481190,-0.116747,-0.597796,-0.213429,0.019342', '1877596', '2990737', '1302384', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293817', '辣手摧花', '剧情', '小镇沉闷的空气令受过高等教育的Charlie（Teresa Wright）十分压抑，她渴望在外谋大事、自己喜爱和崇敬的Uncle Charlie（Joseph Cotten）能突然出现，为自己的生活注入一缕新风。Charlie欲发电报邀请舅舅来做客时，竟先收到他发来的要来的报文，惊喜之外，她对舅舅的爱又加深一层。Uncle Charlie的到来令Charlie及父母非常兴奋，但酷爱读书的妹妹无动于衷。不久Charlie如沐春风变作无忧无虑的少女。两个自称报社记者的陌生人有心将Charlie一家当作典型美国家庭采访，Uncle Charlie为此事大发雷霆相当失态，令Charlie和母亲大为不解。而同其中之一Herbie Hawkins（Hume Cronyn）交谈中，Charlie震惊地听闻有关舅舅的骇人秘密。©豆瓣', '特雷莎·怀特', '阿尔弗雷德·希区柯克', 7.6, 25058, 'tt0036342', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1762386614.jpg', 0.3, 2.1, 33, 48.6, 16.1, '0.108850,-0.082436,-0.785378,0.983755,-0.047938,-0.150311,0.781520,0.193747,-0.888333,-0.400146,-0.104206,0.791563,-0.306130,0.333268,0.262019,-0.034798,0.128958,-0.367035,-0.319610,-0.205534,0.091098,-0.278711,-0.120133,-0.277295,-0.334873,-0.357960,0.276157,-0.020198,-0.176551,0.762578,0.286377,0.542384,-0.140371,0.836166,-0.253370,-0.124949,-0.055843,0.199066,-0.287995,-0.109541,0.024216,0.044782,-0.094508,0.499695,-0.212211,0.345919,0.526193,0.063925,-0.534794,-0.258228,0.571173,0.018401,0.107709,0.192158,0.202759,0.342256,0.293215,0.105885,-0.363222,0.024535,-0.041318,-0.122367,-0.701943,0.109978,0.246142,-0.028510,-0.590221,0.273504,-0.078511,-0.192323,0.294996,-0.160053,0.402197,0.347933,-0.026712,0.717613,-0.041233,0.302162,-0.183934,0.086951,0.693146,-0.192666,-0.150253,0.095989,-0.611718,-0.109984,0.574031,-0.243866,-0.567835,0.223398,-0.055029,0.345593,-0.073202,0.350363,-0.295305,-0.175079,-0.062163,0.033428,0.056238,-0.732893,-0.299333,-0.511957,-0.171096,-0.246323,-0.231533,-0.036949,0.242776,-0.247120,0.637342,-0.889349,0.136742,0.158398,0.180073,-0.534280,0.643378,0.406196,-0.070749,-0.399824,-0.330181,0.076792,0.063117,0.025561,-0.104836,0.128216,-0.082997,-0.003794,-0.295775,0.265894', '1308745', '26253737', '1301022', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293818', '钢琴课', '剧情', '苏格兰单身母亲艾达·麦格拉斯（霍利·亨特 饰）自六岁起就放弃了讲话，只通过钢琴倾诉满腔情感。1852年，麦格拉斯远嫁新西兰的斯图尔特（山姆·尼尔 饰），将钢琴也一并带了去。可是斯图尔特人手不够，只得将笨重的钢琴遗弃海滩。斯图尔特之友乔治·贝恩斯（哈维·凯特尔 饰）爱上了麦格拉斯，用八十英亩土地与斯图尔特交易。斯图尔特转让了钢琴，并命麦格拉斯教贝恩斯奏琴。钢琴课上，贝恩斯提议，如果麦格拉斯在教琴的时候允许某些出格的事情发生，一次课便可换回一个琴键……©豆瓣', '霍利·亨特', '简·坎皮恩', 8.1, 88493, 'tt0107822', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p764799071.jpg', 0.5, 2.1, 19.5, 49, 28.8, '0.446007,-0.118201,-0.555248,0.406240,-0.229373,-0.275682,0.452047,0.194898,-0.254688,-0.228660,-0.187703,0.844074,-0.097640,0.539265,0.371328,0.428381,-0.235370,-0.601338,0.506660,-0.184605,-0.212620,-0.799716,0.100216,-0.298726,-0.070683,-0.264855,0.275484,-0.366100,-0.092284,0.474172,0.287366,0.155457,0.385865,0.113558,-0.053424,-0.039276,0.423762,-0.023843,-0.019938,0.058365,-0.090342,-0.108469,-0.099418,-0.162686,0.297734,0.244545,0.590526,-0.183668,0.452282,-0.004116,0.103462,0.150604,0.331554,0.254139,-0.064218,-0.088445,-0.418192,0.425705,-0.500212,0.157248,0.209445,0.012611,-0.118901,0.154000,-0.608093,0.029691,-0.730225,0.174963,-0.530033,0.113548,-0.033298,-0.299387,0.046153,0.005655,0.104917,0.077171,-0.075809,-0.122150,-0.434348,0.018886,0.196075,0.084317,-0.214294,0.022509,-0.299842,-0.381640,0.139375,-0.126214,-0.213104,-0.151956,0.338451,-0.184465,0.132118,0.217345,-0.431788,-0.449890,-0.552156,-0.388741,0.160089,-0.291050,0.024360,-0.661557,0.179000,0.049661,-0.280515,-0.111421,0.237626,-0.187112,0.506950,-0.398083,0.429648,0.653235,0.228673,0.061322,0.483885,0.194813,0.465979,-0.110731,0.067545,0.501643,0.031273,-0.013321,0.424088,0.409629,0.504964,-0.237641,-0.012140,0.556856', '4319218', '1298468', '3285622', '11525673');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293820', '巴比龙', '剧情', '绰号巴比龙的亨利·查理尔（史蒂夫·麦奎因 Steve McQueen饰）正要被流放到圭亚那一个名为“魔鬼岛”的苦役营终身服刑。查理尔因被控杀害一名皮条客而被捕入狱，可他始终认为自己是冤枉的。在押运船上，身强力壮的查理尔保护了一个带着眼镜狡猾的知识分子路易斯·德加（达斯汀·霍夫曼 Dustin Hoffman饰）。为了洗刷自己的罪名，查理尔从他踏上“魔鬼岛”的第一天起，就开始在德加的帮助下策划越狱逃跑。然而“魔鬼岛”地处荒蛮之地，四面环水，并且到处流行着可怕的疾病。查理尔一次又一次地逃狱，又一次再一次地被捉回。十多年来，他仍孤注一掷地抱着一袋椰壳跳下大海逃生。美国经典越狱冒险剧情片《巴比龙》，根据法国囚犯亨利·查理尔于1969年发表的同名畅销书籍《巴比龙》改编而成。巴比龙是亨利·查理尔的绰号，绰号得名于他胸前蝴蝶形的纹身。本片荣获1974年第46届奥斯卡金像奖剧情类最佳原创配乐提名，并获得1974年第31届金球奖电影类-剧情类最佳男主角提名。', '史蒂夫·麦奎因', '富兰克林·沙夫纳', 8.7, 10881, 'tt0070511', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2575050412.jpg', 0.2, 1, 10, 41.1, 47.7, '-0.003171,0.058513,-0.464467,0.689203,0.116129,-0.186264,0.579162,-0.171557,-0.169130,-0.176850,0.201433,0.787030,-0.112461,0.325144,0.296278,0.235263,-0.484992,-0.384809,0.089050,-0.050961,-0.150770,-0.206973,-0.459934,-0.274413,0.002237,-0.284619,0.567485,-0.067888,-0.151271,0.393134,0.507515,0.310337,0.090400,-0.015688,-0.070764,0.111672,0.210221,-0.244175,-0.208271,0.317177,-0.157217,-0.384376,-0.315696,0.128683,0.139195,0.241888,0.813128,-0.625875,0.260437,-0.220243,0.517755,-0.518597,-0.000593,-0.133669,0.181817,-0.001665,0.073926,0.405356,-0.015932,0.320943,0.122582,-0.415960,-0.526309,-0.034162,0.029248,0.240441,-0.230359,0.229968,-0.418396,0.400144,-0.091356,-0.267913,-0.177990,-0.114916,0.252319,0.362364,-0.021288,0.019980,-0.502381,0.288493,0.336943,-0.102231,-0.382941,-0.280215,0.243038,-0.775526,0.117342,-0.202643,-0.191663,-0.022400,0.657929,-0.213845,-0.158266,0.251097,-0.666697,-0.085384,-0.377635,-0.114090,-0.234220,0.068979,-0.209812,-0.613295,0.333522,-0.100900,-0.037977,-0.056235,-0.008459,-0.285170,0.231576,-0.226405,0.415690,0.654397,-0.122346,-0.282173,0.506587,0.051510,0.065919,-0.080024,-0.104879,0.549566,0.131555,0.227168,0.357630,0.372019,0.10494