INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293823', '妙想天开', '剧情', '未来，英国进入一个资讯管控的时代，每个人的一举一动都遭到监视。因为被认定为恐怖分子，巴托在家中被捕，而且逮捕过程严格按照流程。这个案件引起了档案局职员山姆•劳伊（乔纳森•普雷斯 Jonathan Pryce 饰）的兴趣。随后，他遵从母命，进入资讯管理局工作，得以进一步调查此事。山姆家的空调坏了，在他求助无望之际，电气修理工达脱（罗伯特•德尼罗 Robert De Niro 饰）不请自来。他那一身武器装备，让山姆感到如临大敌。原来，达脱是资讯管理局通缉的要犯，他被指控的理由便是不遵守作业程序。随后，山姆发现资讯管理局对巴托案件存在不可告人的疑点，同事杰克（迈克尔•帕林 Michael Palin 饰）对此闪烁其词。于是，山姆决定一探究竟，其间他邂逅了梦中情人——吉尔•莱顿（金•格雷斯特 Kim Greist 饰），两个人并肩作战，发现了一个巨大的阴谋……', '乔纳森·普雷斯', '特瑞·吉列姆', 8.2, 16360, 'tt0088846', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2284182735.jpg', 1, 3.2, 18.4, 41.9, 35.5, '0.402661,0.113038,-0.644587,0.417450,-0.002217,0.047026,0.455076,0.068740,-0.818388,-0.494447,0.197303,0.554382,-0.111867,-0.025665,0.173305,0.082727,-0.559757,-0.537239,-0.110411,-0.203749,-0.474723,-0.630568,-0.020836,-0.443476,-0.054613,-0.322567,0.276284,0.073811,-0.069987,0.188506,0.242050,0.520347,-0.158877,0.413726,0.188783,-0.031598,0.606659,-0.299792,-0.281526,0.137927,-0.101896,-0.070432,-0.075520,0.283002,-0.100235,0.580574,0.352499,-0.130881,-0.184928,-0.201016,0.276683,-0.381523,-0.007765,0.092536,0.369277,0.114027,-0.282179,0.352810,-0.297788,0.131732,0.091432,0.004656,-0.643793,-0.240385,0.085179,0.456970,-0.299544,-0.010798,-0.320386,0.089706,-0.065787,-0.189770,-0.010810,0.203373,0.437913,0.163691,0.218565,0.270613,-0.516225,-0.047117,0.401500,-0.090139,-0.122887,0.158486,-0.281783,-0.469798,-0.210315,0.129215,-0.258096,-0.039924,0.326649,-0.134849,-0.090645,0.343665,-0.563869,-0.250239,-0.194652,-0.178298,-0.330086,-0.340772,-0.060789,-0.667559,0.017434,-0.088119,-0.393040,0.055782,-0.033948,-0.168394,0.311163,-0.657469,0.008015,0.657474,0.188479,-0.588393,0.549681,0.175142,0.122685,-0.517810,-0.083210,0.080786,0.496432,0.169519,0.041051,0.110957,0.211827,-0.476423,-0.211999,0.089895', '1307442', '