INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293824', '蝴蝶梦', '剧情', '年轻女子（琼·芳登 Joan Fontaine 饰）初遇曼德利主人德文特（劳伦斯·奥利弗 Laurence Olivier 饰）是在海边的悬崖边上。她以为德文特要跳海自尽，大叫一声，让德文特生气不已。然而，接下来的二人相识继而相知的经历让他们堕入爱河，结为伉俪，女子成为了曼德利庄园的女主人。幸福的生活眼看就要铺开，这个新婚妻子却遭遇到了阴森的“寒流”。她发现这个庄园到处可见德文特前妻丽贝卡的影子，她的名字，在家具留下痕迹，更令新婚妻子不安的是，管家丹佛斯太太，更是念念不忘丽贝卡，对这个新来的主人充满仇恨。就连丈夫德文特，也不愿意解释这一切，仿佛他的内心还有旧情。丽贝卡犹如梦魇般弥漫在曼德利庄园，事情开始变得越来越复杂。©豆瓣', '劳伦斯·奥利弗', '阿尔弗雷德·希区柯克', 8.3, 85039, 'tt0032976', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1071757804.jpg', 0.1, 0.7, 14, 51.8, 33.3, '0.291893,-0.177745,-0.797270,0.431938,0.207475,-0.516343,0.816846,0.092697,-0.690934,-0.070473,0.425989,0.781110,-0.339624,0.298193,0.204145,0.341504,-0.272238,-0.474294,-0.073383,-0.238385,-0.015971,-0.331131,0.039406,-0.132769,0.150524,-0.413772,0.359906,-0.145200,0.173245,0.467523,0.085195,0.486905,0.059124,0.480250,-0.214489,0.378402,0.070979,-0.042531,-0.460606,-0.108260,0.071572,0.218132,-0.177456,0.093828,-0.066996,0.272230,0.567658,-0.192411,-0.240865,-0.032605,0.302427,-0.184708,0.027615,0.312436,0.047683,-0.375658,-0.032664,0.239181,-0.273217,-0.183370,-0.018260,0.084843,-0.339270,0.222626,0.063212,0.588809,-0.614788,0.100337,-0.278611,-0.149743,0.077882,-0.249966,0.261185,-0.036949,-0.226824,0.573199,-0.107928,-0.109075,-0.668850,-0.048423,0.516857,0.112294,-0.162460,0.513132,-0.468700,-0.045039,0.102771,0.176945,-0.615393,-0.239002,0.135735,-0.013028,0.010448,0.428551,-0.665149,-0.159701,-0.258433,-0.004688,-0.124543,-0.539324,-0.491402,-0.309670,-0.319521,-0.342605,-0.241102,-0.109545,-0.092590,-0.146037,0.330077,-0.845078,0.240717,0.353725,0.396224,-0.080256,0.331545,0.292001,-0.030705,-0.339183,-0.271563,0.343010,0.005147,-0.003279,0.164400,0.283248,0.134819,-0.027445,-0.407519,0.589470', '25723780', '1296534', '3111650', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293825', '漂亮女人', '喜剧', '爱德华•刘易斯（李察•基尔 饰）是一个拥有百万身家的企业家。他潇洒迷人，但总是无法处理好与女人之间关系，他跟女友分手了。他到洛杉矶出差，晚上开着一辆借来的高级轿车进入了红灯区。由于迷失了方向，他向一名年轻漂亮的妓女薇薇安（茱丽娅•罗伯茨 饰）问路，薇薇安的活泼美丽吸引了他，他把薇薇安带到了酒店。爱德华爱上了薇薇安并极力想留下她，但碍于情面只能用钱做掩饰，让她在一周内充当爱德华的交际活动女伴。宴会上，薇薇安的魅力让爱德华醋意大发。此时薇薇安也发现自己爱上了爱德华，可是一周的时间马上要过去了，两个相爱的人又该何去何从？©豆瓣', '理查·基尔', '盖瑞·马歇尔', 7.9, 129804, 'tt0100405', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205839719.jpg', 0.3, 1.5, 23.5, 49.9, 24.8, '0.473414,0.209615,-0.567099,0.370924,-0.364237,-0.476467,0.899583,0.063208,-0.249477,-0.130079,0.082305,0.669103,-0.155418,0.346490,0.406664,0.392621,-0.352120,-0.701650,0.322284,-0.169175,-0.199934,-0.396734,-0.112247,-0.270431,0.024830,-0.097752,0.268125,-0.014665,0.028140,0.361183,0.419853,-0.060436,0.057919,0.566856,-0.098825,-0.040905,0.149855,-0.151066,0.023477,0.498628,0.130498,-0.299359,-0.161744,0.275644,0.032132,0.437976,0.552460,0.258555,-0.130432,0.159306,0.192279,-0.161444,-0.009220,0.118088,0.013515,-0.058004,0.009157,0.000693,-0.238455,-0.075214,0.194750,0.090994,-0.381508,0.242332,-0.245759,-0.001239,-0.629278,0.452827,-0.205055,-0.222305,0.106403,-0.514829,0.106275,0.065410,-0.018733,0.186144,-0.012793,0.186848,-0.629312,0.150884,0.756286,0.342696,-0.088122,0.413819,-0.343340,-0.389055,-0.163256,-0.185065,-0.577874,-0.129071,0.375166,-0.042822,-0.083963,-0.020224,-0.608669,-0.108362,-0.302099,-0.183487,-0.248862,-0.468608,0.116892,-0.434288,-0.243234,-0.498972,-0.373738,0.017179,0.008901,-0.125201,0.555060,-0.798694,0.072798,0.812588,0.448837,-0.633773,0.838740,0.183718,0.054642,-0.010186,0.094773,0.192373,-0.077726,0.154936,0.169301,0.441750,-0.086645,-0.080869,-0.563209,0.543171', '3055049', '1308755', '1302384', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293828', '007之金手指', '动作', '世界各国突然出现黄金大量流失的现象，而黄金的黑市交易却十分兴盛。英国情报部怀疑世界巨富金手指参与了黑市黄金交易，他在日内瓦拥有一座大银行，各国都有大量黄金储备在那里。007邦德（肖恩•康纳利 Sean Connery 饰）开始展开对金手指的调查。邦德一路跟踪金手指到了日内瓦，发现了他往外运黄金的秘密，他通过用黄金造车身的方法重熔得到金块。邦德被金手指的手下发现了，他们抓住了邦德。邦德在意外中还得知了金手指即将实施的一个惊天计划：他策划用飞机撒播毒气使银行的驻军死亡，然后炸开银行，利用一枚小型核弹致使世界各国保存的黄金受到辐射污染而不能进入流通，这样黑市的黄金交易将获得十倍以上的巨额利润！邦德虽然得知了金手指的全盘计划，可是人在牢中，无法通知外界。最终金手指的阴谋能否得逞？©豆瓣', '肖恩·康纳利', '盖伊·汉弥尔顿', 7.1, 15980, 'tt0058150', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2263013025.jpg', 0.7, 4.3, 43.8, 39.3, 11.9, '-0.080553,0.507830,-0.726650,0.472068,-0.018592,0.140292,0.550837,0.057632,-0.357451,0.013316,0.391321,0.575477,-0.315838,-0.382020,0.114429,0.036225,-0.186492,-0.374311,0.022582,-0.356858,-0.430885,-0.488738,-0.663815,-0.361871,-0.177633,-0.431722,0.598860,0.309735,-0.340298,0.007506,0.131824,0.168712,-0.055517,0.423181,-0.301458,-0.231133,0.228192,-0.126151,-0.239759,0.456828,-0.180115,-0.272657,0.136597,0.223825,0.032075,0.304647,0.477335,-0.363999,-0.069263,-0.076717,0.367653,-0.206870,-0.082288,-0.117842,0.306744,0.295521,-0.119146,0.117777,-0.360552,0.115206,0.377235,-0.002606,-0.801103,-0.389817,-0.040552,0.253493,-0.531643,0.075820,-0.142904,0.019352,-0.208720,-0.341387,0.175061,0.458299,0.425048,0.096817,-0.301155,-0.030488,-0.825118,0.130191,0.260957,-0.589701,-0.381130,0.453808,-0.081601,-0.518957,-0.318029,-0.119563,-0.110064,-0.075129,0.520438,0.167907,-0.149848,0.304723,-0.858699,-0.090946,-0.303176,-0.520350,-0.013267,-0.100538,-0.146221,-0.877718,-0.282279,0.013835,-0.154127,0.283484,0.261147,-0.161370,0.562549,-0.563119,-0.008767,0.719193,0.577662,-0.549535,0.316140,-0.339937,-0.076473,-0.445219,-0.191328,-0.028226,0.437433,0.537283,0.016447,0.130904,0.150073,-0.395842,-0.199687,0.546945', '1309112', '1307897', '4014397', '3401684'