INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293829', '炮弹专家', '动作', '美国中央情报局的特种兵炸弹专家雷（西尔维斯特•史泰龙 Sylvester Stallone 饰）因为过失引咎辞职，辞职后的他靠当职业杀手为生。这天他接到了神秘女子美（莎朗•斯通 Sharon Stone 饰）的生意，美要他杀死当地的黑社会头子。其实美就是那个黑社会头子的情妇，因他早前曾杀害了美的父母，所以美不惜一切要报父母之仇。美甚至以身体作为引诱，雷接下了这单生意，两人也暗暗互生情愫。雷在准备行动中，发现了黑社会头子的贴身保镖就是自己当年在特种兵部队里的死对头立特，旧恨新仇交织在一起，于是一场生死大战在两个前特种兵之间展开了！©豆瓣', '西尔维斯特·史泰龙', '路易斯·罗沙', 6.5, 5594, 'tt0111255', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1253071483.jpg', 1.4, 9.6, 57.1, 25.2, 6.8, '0.111064,-0.142986,-0.793580,0.515221,-0.117836,-0.193064,0.631454,0.002963,-0.461583,-0.263197,0.071814,0.665324,-0.001060,0.211357,0.307923,0.013052,0.005945,-0.972857,-0.497517,-0.063440,-0.146498,-0.295721,-0.322047,-0.178702,-0.027688,-0.199996,0.459273,-0.030351,-0.030540,0.415051,0.502993,0.365707,-0.211825,0.167421,-0.074282,-0.035512,0.250572,-0.122467,-0.492453,0.092844,-0.151033,-0.187033,0.273208,-0.019096,0.127131,0.480644,0.356296,-0.266469,-0.201129,-0.287724,0.112067,-0.317764,-0.166719,0.071299,0.470330,-0.064766,0.376136,0.066413,-0.034063,-0.243466,0.053158,0.008743,-0.627794,-0.067250,0.203663,-0.162662,-0.827370,0.265081,-0.225531,0.229061,-0.037509,0.023181,0.259749,0.233313,0.243915,0.173896,0.172691,0.172154,-0.336275,0.298088,0.834400,0.222536,0.114636,0.068337,-0.218069,-0.178258,-0.102242,-0.030834,-0.050539,-0.010439,0.459434,-0.474267,-0.010807,0.155781,-0.570269,-0.318568,-0.199723,0.514079,-0.155130,-0.215578,-0.227273,-0.440148,-0.121374,-0.363479,-0.356414,0.304561,0.166176,-0.092088,0.482493,-0.863657,0.137358,0.778313,0.163139,-0.580925,0.256814,0.250185,0.123965,-0.095265,-0.147340,-0.035483,0.284988,0.182446,0.266840,0.368737,-0.146256,-0.352062,-0.074531,0.148821', '30345227', '1301022', '25908042', '27202765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293830', '猎杀红色十月', '动作', '本片根据汤姆·克兰西畅销名著改编。1984年11月，苏联正处于戈尔巴乔夫上台前夕，也是美、苏两个超级大国明争暗斗的冷战高潮时期。苏联研制了一艘新型核潜艇“红十月号”，并派老练的雷米斯负责该艇的首次试航演习。此时，美国中央情报局也获取了有关“红十月”号的情报。途中，艇长雷米斯杀死了发现他隐私的专横政委并命令潜艇改变航向。他向全体官兵声称此举是要利用该艇先进的无声推进系统去通过美国海军的监视网并纵情游览美国的海岸线。一个苏联高级将领秘密挟带一艘超级军用潜艇“红月十月号”，究竟是想投奔美国，还是制造一场核战争？苏联国防部大为震动，遣派军队追捕，美国中央情报局亦派出精英部队拦截，一场联系美苏两国军事平衡的追击行动由此展开。©豆瓣', '肖恩·康纳利', '约翰·麦克蒂尔南', 7.7, 17136, 'tt0099810', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162655199.jpg', 0.8, 2.7, 26.1, 50.7, 19.7, '-0.129237,-0.041141,-0.633968,0.807281,0.355804,-0.027371,0.094309,-0.243811,-0.279019,-0.098744,-0.005092,0.359752,0.149203,-0.241945,0.274037,0.041187,-0.544218,-0.495696,-0.106431,-0.014417,-0.174559,-0.597579,-0.352625,-0.414340,0.309504,-0.286159,0.715655,0.150606,-0.525288,0.369773,0.294457,0.284207,-0.130451,0.593039,0.233511,-0.517172,0.317806,-0.365547,-0.328725,0.162976,-0.486545,-0.175145,-0.013807,0.075926,0.206215,0.576884,0.418677,-0.239348,0.003662,-0.220272,0.142186,-0.320816,0.004662,-0.284543,0.796534,0.236586,-0.475624,0.091594,-0.030661,0.154946,-0.269067,0.069253,-0.370948,0.034179,0.028042,-0.245359,-0.063346,-0.001149,-0.529998,0.511547,-0.224399,-0.062094,0.149617,0.941733,0.136744,0.249608,-0.080197,0.353249,-0.379629,0.285211,0.542137,-0.107641,-0.353775,-0.086099,0.149856,-0.407096,-0.029042,-0.444942,0.080958,-0.145979,0.386655,-0.301290,0.216237,0.328974,-0.654216,0.189428,-0.420183,-0.610219,0.069326,-0.125163,0.300830,-1.129941,0.044138,-0.213971,-0.051738,0.335668,0.296302,0.069154,0.631575,-0.290338,-0.009207,0.604374,0.127059,-0.594354,0.391819,0.350767,-0.201078,-0.368667,0.147015,0.239516,0.032741,0.290326,-0.214786,0.202331,0.204308,-0.306011,-0.130368,-0.092443', '2973528', '3871833', '1293572', '26718836');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293838', '星球大战', '动作', 'Vader 达斯（大卫•普劳斯 饰）秘密捕获了奥德兰公主 Leia（凯莉•费舍尔 饰）的星际飞船。危急时刻，Leia 命机器人 R2-D2（肯尼•贝克 饰）携带重要信息向隐居的绝地武士 Obi-Wan Kenobi（亚历克•吉尼斯 饰）求援。R2 成功逃离飞船，却在寻找 Obi-Wan 的途中被贾瓦人捕获，卖给了农夫 Owen（菲尔•布朗 饰），R2 只得再次逃跑。第二天，Owen 的侄儿 Luke（马克•哈米尔 饰）找到 R2 后，遭到了3名沙人的袭击，幸而 Obi-Wan 及时出现吓跑了沙人。Luke 回到家，发现 Owen 叔叔和 Beru 婶婶（谢拉格•弗雷泽 饰）已被追捕 R2 的帝国冲锋队杀害，于是决定跟随 Obi-Wan 学习原力之道，成为绝地。Obi-Wan 以高价雇了走私者 Han Solo（哈里森•福特 饰）的千年隼号，向奥德兰进发……', '哈里森·福特', '乔治·卢卡斯', 8.5, 128839, 'tt0076759', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2500865872.jpg', 0.3, 1, 14, 45.3, 39.4, '0.187085,0.089520,-0.386481,0.438862,0.243759,-0.498117,0.331573,0.099217,-0.125114,-0.281578,0.221596,0.420613,0.112414,-0.365532,0.568687,0.237571,-0.516556,-0.266288,0.351144,-0.210200,-0.252865,-0.556252,-0.243050,-0.194613,0.178033,-0.760719,0.135870,0.100965,-0.070572,0.434102,0.075071,0.765504,-0.073179,0.327400,0.004955,0.095154,0.468498,-0.502099,-0.377498,0.571208,-0.360829,0.022910,0.131561,-0.076530,0.150682,0.394258,0.465144,-0.395399,0.311094,-0.271023,0.106666,-0.182405,0.315492,0.011609,0.348783,-0.011195,-0.052496,0.014156,-0.172184,0.176905,0.291342,-0.064800,-0.409406,0.128852,0.195482,-0.058806,-0.636984,-0.128236,-0.474853,0.118315,0.149440,-0.408310,0.147206,0.437857,0.212091,0.002776,0.227496,0.259055,-0.620340,-0.187317,0.243403,-0.423798,-0.028906,-0.224652,0.466281,-0.389906,0.373668,-0.141964,-0.240994,-0.103082,0.674921,0.062220,0.082404,0.344561,-0.747980,-0.215263,-0.661685,-0.414320,0.216518,-0.252174,-0.145809,-0.836363,0.253295,0.147314,-0.014229,0.300549,-0.002480,0.133990,0.340717,-0.314489,0.493998,0.398466,0.395397,-0.257940,0.558449,-0.311858,0.178264,-0.094817,0.103090,0.282955,0.507468,0.561484,0.161466,0.045493,0.203394,-0.381303,-0.210990,0.202721', '1927369', '1296528', '6517421', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293839', '罗马假日', '剧情', '欧洲某国的安妮公主（奥黛丽·赫本 Audrey Hepburn 饰）到访罗马，国务烦身，但她又厌倦繁文缛节。一天晚上，身心俱疲的她偷偷来到民间欣赏夜景，巧遇报社记者乔（格里高利·派克 Gregory Peck 饰）。二人把手同游，相当快乐。公主更是到乔的家中作客并在那过夜。不料乔无意中发现了公主的真实身份，他决定炮制一个独家新闻，于是乔和朋友、摄影师欧文（埃迪·艾伯特 Eddie Albert 饰）一起带公主同游罗马，并且偷拍了公主的很多生活照。然而，在接下来与公主的相处中，乔不知不觉恋上了公主。为了保护公主的形象，乔只能忍痛抛弃功成名就的良机，将照片送予了公主。安妮公主在经历了罗马一日假期后，反而体验了自己对国家的责任，毅然返回了大使馆，为了本身的责任而果断抛弃了爱情。©豆瓣', '奥黛丽·赫本', '威廉·惠勒', 9.1, 896341, 'tt0046250', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189265085.jpg', 0.1, 0.3, 6.4, 32.9, 60.4, '0.140494,0.236381,-0.376856,0.768982,0.192298,-0.410089,0.708323,0.176082,-0.507769,-0.510023,0.113610,0.536544,-0.291954,0.505724,0.810751,-0.025999,-0.462663,-0.545992,0.084810,-0.123927,-0.374221,-0.384064,0.247826,-0.562093,-0.123938,-0.141061,0.454254,0.193245,0.117130,0.517715,0.310253,-0.152837,-0.119493,0.830139,-0.164267,0.086251,0.053485,0.126156,-0.289267,0.389278,0.356891,-0.358962,0.034892,0.384274,0.274829,0.107315,0.547909,-0.605930,0.155677,-0.095767,0.426397,-0.119409,0.383069,0.265632,0.261967,-0.143067,0.184561,-0.345665,-0.292559,-0.208050,0.467711,-0.311445,-0.069207,0.135585,-0.187991,-0.206387,-0.581773,0.333708,-0.131932,0.247695,0.051608,-0.211003,0.362754,0.455967,0.240491,-0.079388,-0.052662,0.047217,-0.493104,0.298195,0.525373,-0.004850,0.107596,0.269471,-0.236815,-0.623257,0.022930,-0.375066,-0.441372,-0.109621,0.365387,-0.221305,0.098569,0.324749,-0.464246,-0.347590,-0.308907,0.114422,0.184413,-0.715237,0.370097,-0.362157,-0.121329,-0.360978,0.004442,0.038679,0.269702,-0.366847,0.549122,-0.794676,0.030615,0.396487,0.119047,-0.761117,0.652488,0.012890,0.137333,-0.051352,0.146893,0.644648,0.102768,0.225463,0.065186,0.330578,-0.079293,-0.015046,-0.305325,0.368987', '1308755', '1301022', '1302384', '27042738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293841', '倒扣的王牌', '剧情', '身无分文的记者丘克（Kirk Douglas 饰）流落一座新墨西哥州的小城，他舌如巧簧向当地报馆的主编推销自己，宣称自己有制造新闻的天才。波澜不惊的小城生活让曾经供职纽约的丘克倍感无聊。这天，主编令丘克外出采访，丘克于路却意外遭遇一名小镇店主里奥被困山洞。丘克敏感的意识到这件事情背后的新闻价值，他迅速联系州长、工程队与医生。随着丘克的一篇篇报道，观看施救过程的民众陆续赶来，本欲离开的里奥妻子因为看到有利可图而选择留下，并与丘克站到了同一阵营，丘克安排采用费时的营救方式来维持事件的新闻热度。几天内人群不断涌入，营救现场俨然成为游乐场。丘克与纽约的老上司讨价还价之时，洞中的里奥却走到了生命的尽头……本片获1952年奥斯卡最佳编剧奖。©豆瓣', '柯克·道格拉斯', '比利·怀尔德', 8.7, 13750, 'tt0043338', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2171823995.jpg', 0.2, 0.5, 7.3, 46.8, 45.2, '0.187076,-0.043538,-0.585240,0.457784,0.307828,-0.057572,0.662876,0.288661,-0.484596,-0.215327,0.262148,0.635892,-0.300476,0.119179,0.568868,-0.109143,-0.355922,-0.726188,0.147690,-0.236724,-0.194982,-0.222100,-0.181800,-0.264677,0.007162,-0.303512,0.481166,0.232600,-0.222859,0.540028,0.064760,0.245313,-0.220175,0.611436,-0.012081,-0.076190,0.406898,-0.051462,-0.330707,0.275708,-0.186506,-0.153447,-0.310532,0.181984,0.268452,0.322732,0.704257,0.013469,-0.166076,0.109884,0.515209,-0.321255,0.183002,0.033076,0.395298,0.078539,0.286584,0.147275,-0.236560,-0.021045,-0.205511,-0.140483,-0.652229,0.139691,-0.052553,0.301999,-0.360558,0.091773,-0.028944,-0.037103,0.014669,-0.405081,0.270129,0.371929,0.102425,0.245590,-0.138546,-0.198730,-0.421748,0.080126,0.564637,-0.124886,-0.280256,0.218886,-0.067793,-0.332955,0.122419,-0.034271,-0.433427,-0.029776,0.206024,0.002583,-0.147072,0.184756,-0.427595,-0.114995,-0.222839,-0.503766,0.166616,-0.191531,-0.230534,-1.030717,0.012781,-0.010425,-0.080516,0.040680,-0.001857,0.011662,0.472411,-0.379763,0.051558,0.804390,0.282130,-0.426696,0.772132,-0.197544,0.135664,-0.281157,0.003917,0.307592,0.155285,0.450956,-0.027764,0.115477,-0.128550,-0.380917,-0.522910,0.384722', '2159244', '10466639', '1484091', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293846', '西力传', '喜剧', '故事发生在三十年代的美国，随着经济和文化的蓬勃发展，一个名叫西力（伍迪·艾伦 Woody Allen 饰）的男人横空出现在了人们的面前。这个神奇的犹太人被发现混迹于各种各样相去甚远的交际圈里，不同阶级的，甚至是不同种族的，而每当他进入了一个新的环境中，他的身上就会迅速体现出这个环境的特征，有时是心理的同化，有时是生理的变异。曼哈顿医院的精神科医生们对这个怪异的病人产生了浓厚的兴趣，普罗大众亦然，他们亲切的称西力为“变色龙”，一大批以他为主题的文化和商品应运而生，一时间，西力成为了这个时代最炙手可热的巨星。可是，真正将西力当做一个病人来关心的只有尤朵拉医生（米亚·法罗 Mia Farrow 饰），年轻又执着的她致力于治愈他的疾病。长此以往，西力和尤朵拉之间建立了深厚而又真诚的感情，这对立场特殊的爱人能否终成眷属呢？导演伍迪•艾伦自导自演，以伪文献伪记录的方式，生动又真实的重现了本为虚构的西力的一生。', '伍迪·艾伦', '伍迪·艾伦', 9, 23461, 'tt0086637', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2119299252.jpg', 0.2, 0.6, 6.8, 34, 58.4, '0.628904,0.179577,-0.690518,0.784065,-0.243390,-0.018940,0.845341,0.023446,-0.553931,-0.254789,0.167035,0.875395,-0.122542,0.203171,0.242186,0.047656,-0.087313,-0.709762,-0.150338,0.015105,-0.485903,-0.385786,-0.695613,-0.188132,-0.265601,-0.379876,0.492479,-0.017033,-0.479793,0.414865,0.255240,0.520228,0.119738,0.392857,-0.376732,0.034454,-0.076890,-0.042521,-0.161041,0.122638,0.076644,-0.184402,-0.034921,0.318173,-0.361959,0.404060,0.625705,-0.299071,-0.283318,-0.065603,0.807409,-0.213394,-0.205580,0.093217,0.191601,0.095570,0.042639,-0.004655,-0.207588,-0.067505,-0.032668,0.055825,-1.158799,-0.140557,0.113082,0.422593,-0.572372,0.496855,0.104248,-0.653305,0.056044,-0.269857,0.259032,0.316957,0.242355,0.667660,-0.145656,-0.131368,-0.371390,0.074024,0.506884,0.056369,-0.700377,0.516462,-0.626088,-0.635692,-0.116931,-0.330447,-0.460150,-0.183989,0.044847,-0.065531,-0.174145,0.361826,-0.876273,0.197830,-0.106501,-0.193104,0.017742,-0.326082,-0.042946,-0.491901,-0.367958,-0.810917,-0.311396,-0.146554,0.124559,-0.264538,1.097750,-0.945051,0.069706,0.542471,0.281337,-0.593053,0.721417,0.166750,0.096184,-0.141008,-0.370000,0.200515,-0.035075,0.403750,-0.191880,0.584869,0.192223,-0.066705,-0.410124,0.673821', '24284209', '27602116', '1303542', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293847', '生之欲', '剧情', '市政府市民科科长渡边勘治（志村乔饰）是名近三十年全勤的模范公务员，然而他和同事们每天忙碌却人浮于事，不知道自己在忙些什么。一帮妇女联合到市政府申请填平社区附近的臭水池，在上面建造个小公园。市民科的接待人员告诉她们要把问题反映到土木课，公园课把她们推到建设科……，申请书转 了一圈后，又被踢回市民科。一个月后，渡边因身体不适，去医院被查出胃癌，时日无多。渡边回到家，感到孤独无助，儿子（金子信雄饰）只想着用老人的退休金及储蓄，到外面另辟小家庭。绝望中的渡边没有去上班，借酒浇愁。之后，请辞的女科员小田（小田切美善饰）给了渡边以启示。他打起精神，亲自督促建设社区公园。几个月后……©豆瓣', '志村乔', '黑泽明', 9.2, 35641, 'tt0044741', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2215888214.jpg', 0.2, 0.4, 4.7, 26.5, 68.2, '0.222485,-0.167244,-0.529839,0.129809,-0.222244,-0.419981,0.396835,0.265932,-0.526875,-0.304872,0.032613,0.219935,-0.068606,0.669413,0.046318,-0.135072,-0.432868,-0.470413,-0.079877,-0.315371,-0.392463,-0.451247,0.324942,-0.249015,-0.278324,-0.060578,0.293069,-0.014978,0.250728,0.156377,-0.014847,0.216227,0.084618,0.403411,0.005457,0.126557,0.312659,-0.117356,0.164102,0.346946,0.224909,-0.225306,-0.469505,-0.246202,0.494563,0.329518,0.613500,0.379561,-0.066245,-0.169494,0.326342,-0.107313,-0.097905,0.265081,0.643693,0.076727,-0.062297,0.062297,-0.638323,0.099012,0.012901,-0.305270,-0.179825,-0.064067,-0.103024,0.239386,-0.769522,0.425699,-0.087729,-0.157376,0.287075,-0.505777,0.139004,0.263536,-0.114781,0.529259,-0.131273,0.188693,-0.303002,0.259833,0.585221,-0.098716,0.041280,-0.052183,-0.022916,-0.363457,0.022223,-0.002046,-0.047022,-0.224544,0.073194,-0.072790,-0.152712,-0.231672,-0.423484,-0.246562,-0.117684,-0.506264,0.028361,-0.176791,-0.190385,-0.706233,0.498427,0.158813,-0.098041,0.182575,0.295925,-0.070265,0.498547,-0.671234,0.006389,0.622215,0.125137,-0.470172,0.725935,-0.168171,0.112753,-0.233373,-0.048147,-0.262308,0.334479,0.974354,0.318146,0.404989,-0.386270,-0.195033,-0.345400,0.128333', '1408130', '1309184', '35286583', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293849', '女人就是女人', '剧情', '美艳性感的脱衣舞娘安吉拉（安娜·卡里娜 Anna Karina 饰）与男友埃米尔（让-克劳德·布里亚利 Jean-Claude Brialy 饰）同居很久。安吉拉非常想要一个孩子与埃米尔长相厮守，可埃米尔非常享受二人世界的自由，不想结婚更不用说生儿育女，争吵在所难免。在屡次遭到埃米尔的拒绝后，安吉拉一气之下找到了埃米尔的好友阿尔弗雷德（让-保罗·贝尔蒙多 Jean Paul Belmondo 饰）并与之发生了关系。由法国新浪潮奠基者之一让-吕克·戈达尔执导编剧的彩色宽银幕电影《女人就是女人》，是他向好莱坞音乐歌舞片的致敬之作。影片颠覆传统歌舞片模式，是一部“新现实主义歌舞片”。本片荣获1961年第11届柏林国际电影节银熊奖最佳女演员和特别奖两项殊荣，并入围金熊奖。©豆瓣', '让-克洛德·布里亚利', '让-吕克·戈达尔', 8.1, 9462, 'tt0055572', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199159082.jpg', 0.5, 1.9, 18, 49.6, 30, '-0.046164,-0.245773,-0.662457,0.757044,0.301134,-0.300364,0.694219,0.049633,-0.425336,-0.084731,-0.129711,1.154267,-0.506372,0.023723,0.541070,0.199979,-0.472636,-0.688414,0.083152,-0.157731,0.197116,-0.428478,-0.113551,0.019816,-0.302248,-0.564383,0.894064,-0.264481,-0.141810,0.316478,0.768428,0.011478,0.012574,0.214422,0.159030,0.028760,0.317188,-0.114222,-0.667215,0.419217,0.119955,0.072743,-0.226900,0.064283,0.043094,-0.078020,0.454758,-0.383178,0.096641,-0.087527,0.509645,-0.173478,-0.107952,-0.091575,-0.098806,-0.213423,0.541980,0.393551,0.056130,0.193668,0.143522,-0.231675,-0.575191,0.431538,0.271579,0.066143,-0.402344,0.480687,-0.326577,-0.055807,0.007279,-0.236328,0.161581,0.231377,0.612473,0.161726,-0.013635,0.082004,-0.318652,0.270444,0.506238,0.239669,-0.265817,0.561349,-0.348939,-0.560952,-0.183270,-0.284430,-0.546531,0.246693,0.378259,-0.138435,0.158950,0.220495,-0.591237,-0.077381,-0.275231,-0.187239,0.092621,-0.409175,0.343073,-0.798813,-0.144572,-0.366447,-0.157404,-0.196386,0.213714,-0.386505,0.657898,-0.643129,0.114986,0.370506,0.398709,-0.275281,0.758013,0.212483,0.034371,-0.304400,-0.130788,0.348096,-0.017985,-0.322154,-0.060037,0.345094,0.013986,-0.310531,-0.071339,0.404877', '1780122', '1829654', '34795703', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293852', '罗斯玛丽的婴儿', '剧情', '凯（约翰·卡萨维兹 John Cassavetes 饰）有着一个外表单薄脆弱的妻子罗斯玛丽（米亚·法罗 Mia Farrow 饰），自从他们搬到新公寓后，凯就和邻居一对老夫妇相谈甚欢。而罗斯玛丽却并不特别喜欢这对邻居，令她感到不适的，还有接下来的一连串怪事。罗斯玛丽看 到了自杀的女人，在日渐诡异的生活气氛下，她还做着毛骨悚然的梦。梦中，有一个长毛怪物侵犯自己，罗斯玛丽从噩梦中醒来不久，竟得知自己已有身孕的消息。邻居老太前来照顾罗斯玛丽和腹中婴儿，然而，罗斯玛丽却渐渐怀疑，一切的古怪事情，都来自于这个表面和善慈祥的邻居，甚至还有自己的丈夫！他们正在合谋计算罗斯玛丽的婴孩。到底是罗斯玛丽的幻觉还是确有其事？当她看到出生的婴儿眼中竟无瞳孔时，罗斯玛丽知道，魔鬼的气息近在眼前。©豆瓣', '米娅·法罗', '罗曼·波兰斯基', 8.2, 57340, 'tt0063522', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517730337.jpg', 0.7, 1.8, 17.1, 49.9, 30.4, '0.047438,-0.082397,-0.831603,0.360705,-0.055021,-0.499641,1.046773,0.141506,-0.721777,-0.782191,0.440366,0.807429,-0.403717,0.144671,0.122994,0.731077,-0.171554,-0.546742,-0.182188,-0.092660,-0.047366,-0.383332,-0.356315,-0.367766,0.008847,-0.532569,0.113067,0.069461,-0.044390,0.313229,0.117809,0.217895,0.043750,0.529104,-0.141849,-0.035161,0.130979,-0.024288,-0.089581,-0.367617,0.216375,-0.033824,-0.219784,0.355100,-0.082067,0.440055,0.569724,-0.309122,-0.155653,0.037688,-0.007349,0.004418,-0.151396,0.331006,0.198890,-0.455916,0.360521,-0.050780,-0.255264,-0.283932,-0.019643,0.326184,-0.633302,0.364435,-0.048539,0.624528,-0.282635,0.319212,-0.387028,0.031821,0.366519,-0.492533,0.205431,0.297893,-0.008072,0.633257,-0.195438,0.180169,-0.421182,-0.274147,0.558471,0.132601,-0.288407,0.277158,-0.594712,-0.314749,0.289400,0.103835,-0.433888,0.123289,0.300641,0.064159,-0.287144,0.530596,-0.685739,-0.108122,-0.354982,-0.103567,-0.022201,-0.378572,-0.318104,-0.640447,-0.225919,-0.463000,-0.257039,0.055181,-0.043983,-0.271320,0.485462,-0.797288,0.542740,0.415132,0.024014,-0.365179,0.404643,0.186355,0.047045,-0.212416,-0.350056,0.490536,-0.070581,0.005888,-0.035578,0.334441,0.134310,-0.071883,-0.377480,0.548505', '1296534', '30137576', '1309172', '25909236');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293854', '老虎出更', '剧情', '警界老油条阿辉（周润发 饰）生性风流，凭借自己父亲昔日手下沾叔（黄沾 饰）的维护，阿辉在警局虽然得不到升迁，但也落得清闲。新进警员曹里昂（李元霸 饰）的到来打破了这一切，曹大胆甚至莽撞的办案方式连累阿辉大出洋相，阿辉虽恨曹里昂，但碍于上司命令，不得不与曹搭档。与此同时，毒枭罗茂森（徐少强 饰）的手下毒蛇炳将其交易的毒品调包私自出售，毒蛇炳之妹当娜（利智 饰）配合售毒。兄妹二人非法入港相依为命，希望藉由毒品生意改善生活。罗茂森团伙杀人引起警方注意，阿辉与曹里昂两人接手此案，他们很快从当娜身上得到了线索。而罗茂森亦发现毒蛇炳偷梁换柱的所为，一时间阿辉与罗茂森展开了对当娜的争夺……©豆瓣', '周润发', '刘家良', 6.9, 10418, 'tt0095491', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2227086799.jpg', 0.8, 5.2, 51.1, 32.7, 10.2, '-0.019814,-0.015390,-0.351946,0.403032,-0.039893,-0.251313,0.285026,0.145551,-0.622657,-0.402010,0.014513,0.336518,-0.407705,-0.133002,0.130078,-0.240289,-0.278728,-0.572659,-0.187614,0.076324,0.003091,-0.646402,-0.120390,-0.366625,-0.189783,0.194058,0.376015,0.220393,-0.315199,0.591634,0.433661,0.194980,-0.332971,0.421108,0.035257,0.021197,0.001023,-0.125684,-0.380247,-0.289488,0.175316,-0.460042,0.053301,0.129249,0.351881,0.563572,0.453234,-0.139797,-0.217088,-0.137683,0.098074,-0.291408,0.297311,-0.018718,0.440360,-0.105702,-0.024194,0.229079,-0.209122,-0.051847,0.184877,0.056508,-0.640777,0.005331,0.199226,-0.009017,-0.277874,0.151610,-0.245557,0.340737,-0.175016,0.023374,0.240989,0.369509,0.319344,-0.027636,0.051575,0.121337,-0.422236,0.154886,0.506320,-0.108445,0.239368,-0.017298,-0.163529,-0.475867,-0.000749,-0.272383,-0.007275,-0.104023,0.526000,-0.018245,0.102369,0.154394,-0.453066,-0.528298,-0.043098,0.365901,0.070034,-0.211775,0.108788,-0.697249,-0.005630,-0.421294,-0.316726,0.280399,0.077822,-0.297290,0.345907,-0.610597,-0.114164,0.120084,0.274642,-0.760639,0.323156,-0.078698,0.328820,-0.259983,-0.220700,-0.026417,0.794343,0.010030,0.593317,-0.019810,-0.275839,-0.286031,0.084561,-0.095911', '26996640', '1300299', '1428602', '1299335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293861', '油炸绿番茄', '剧情', '一次偶然中，失意的艾弗林（凯西·贝茨 Kathy Bates 饰）在养老院里结识了老人妮妮（杰西卡·坦迪 Jessica Tandy 饰），为了开导艾弗林，妮妮为她讲了一个关于女孩爱姬（玛丽·斯图尔特·马斯特森 Mary Stuart Masterson 饰）的故事。爱姬从小生活在歧视和排挤的环境中，只有哥哥巴迪（克里斯·奥唐纳 Chris O''Donnell 饰）能给她带来短暂的快乐。可是，巴迪在一场车祸中失去了生命，这一巨大的打击让爱姬彻底陷入了自闭之中。这时，善良的露丝（玛丽·露易斯·帕克 Mary-Louise Parker 饰）出现在了爱姬的身边，她的陪伴和爱护让爱姬逐渐走出了阴影，但不久之后，露丝自己却在病痛中去世了。露丝的死让爱姬感触良多，她开始明白坦然接受生命里的发生的一切，努力帮助他人才是获得幸福的最佳途径。©豆瓣', '凯西·贝茨', '乔恩·阿维奈', 8.7, 10308, 'tt0101921', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1452662468.jpg', 0.2, 0.7, 10.8, 42.7, 45.6, '0.188868,0.261035,-0.655080,0.600967,-0.291405,-0.462957,1.016175,0.032029,-0.662551,-0.254175,0.168362,0.786800,-0.098280,0.410632,0.341691,0.252383,-0.453558,-0.656348,0.073096,-0.086906,-0.356464,-0.551222,-0.369709,-0.233897,-0.278380,-0.621738,0.375213,0.158945,-0.015738,0.548237,0.122660,0.401056,0.066885,0.537107,0.113848,0.332100,0.210815,-0.080037,-0.290989,0.218421,0.131097,-0.343446,0.006167,0.363281,0.007099,0.158916,0.771025,-0.632836,-0.032316,-0.141863,0.317229,-0.159565,0.003556,0.094650,-0.009902,0.004318,0.402738,0.067944,-0.530096,0.103172,0.129662,-0.127269,-0.588355,-0.080340,0.056693,0.198710,-0.729593,0.540245,0.046088,-0.194189,0.445475,-0.207325,0.304764,0.323942,0.334665,0.522611,-0.393805,0.029242,-0.274723,0.131911,0.716727,-0.277599,-0.276365,0.466638,-0.523483,-0.315434,0.213897,-0.140679,-0.573058,0.039998,0.332308,0.112826,-0.298571,0.468021,-0.377550,0.025140,-0.402107,-0.150808,-0.336422,-0.520611,-0.174498,-0.301297,-0.326013,-0.383090,-0.219080,-0.059086,-0.320829,-0.439861,0.723693,-0.911060,0.572398,0.282306,0.224481,-0.231614,0.628195,0.171449,0.371155,0.027427,0.135756,0.483216,-0.143470,0.001179,0.170634,0.264443,-0.063657,0.077647,-0.480538,0.620287', '3111650', '1308755', '26245360', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293863', '钢铁巨人', '喜剧', '往日平静的洛克威小镇，近来怪事不断，先是农家被毁、车子损坏等。一天晚上，发电厂也遭到了破坏，导致全镇停电，引起了全镇居民的恐慌。小男孩霍加斯（艾力·马伦斯奥 Eli Marienthal 配音）觉得迹象很可疑，于是沿着电缆线走到了建在森林中的发电厂，发现了凶手——钢铁巨人（范·迪塞尔 Vin Diesel 配音）。开始霍加斯被钢铁巨人巨大的身躯吓坏了，但发现他被高压电缆线缠住，无法脱身。霍加斯没有打算将此事向大人们报告，而是打算救他出来，在多日的交往过程中，霍加斯发现他其实有颗善良的心，两人成了好朋友。钢铁巨人以铁为食，每天要消耗大量的铁，供不应求，霍加斯只好带他去狄恩（小哈里·康尼克 Harry Connick Jr.）旧车厂。 另一方面，政府派来了肯特（克里斯托弗·麦克唐纳 Christopher McDonald 配音），追查铁巨人的下落，并到处散播谣言。最后巨人被肯特发现，派出大量的军队来摧毁他，完全不顾小镇居民的安危，错误的将原子弹的发射了出去，钢铁巨人在危机关头将会如何解决危机……', '艾力·马伦斯奥', '布拉德·伯德', 8.6, 25594, 'tt0129167', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453506001.jpg', 0.2, 0.8, 11, 43.8, 44.3, '0.106969,-0.002926,-0.855462,0.130780,0.109752,-0.168703,0.894879,0.012815,-0.435535,-0.289487,0.129931,0.342011,-0.183225,-0.084002,-0.035584,-0.152799,-0.290540,-0.268592,-0.033025,-0.051770,-0.505722,-0.316634,-0.126486,-0.398281,-0.091569,-0.415703,0.373593,0.298095,-0.180644,0.067771,-0.051225,0.307326,0.029662,0.528707,0.023066,0.153352,-0.026284,-0.406000,0.027493,0.379216,-0.003551,-0.147765,-0.023597,0.463507,0.016633,0.503528,0.617729,-0.295420,-0.044720,-0.070844,0.205938,-0.297468,0.316299,0.191469,0.568149,0.017634,-0.177151,-0.017766,-0.280672,-0.033363,0.415918,-0.189152,-0.142659,-0.048026,-0.037751,0.181953,-0.602279,0.330011,-0.005852,0.023175,-0.155837,-0.486740,0.146019,0.191680,0.307112,0.193596,-0.096164,0.150074,-0.558610,-0.128765,0.644069,-0.202436,-0.246732,0.130018,-0.099230,-0.212915,-0.173318,-0.297693,-0.240177,-0.147433,0.603969,0.189918,-0.254892,0.382805,-0.517778,-0.244059,-0.532561,-0.272786,-0.298499,-0.110582,-0.164784,-0.574066,0.154187,0.016184,-0.028101,0.313972,-0.111518,0.002805,0.314002,-0.501001,0.225147,0.657857,0.421944,-0.128593,0.241076,-0.369136,-0.123306,-0.034138,0.101468,0.051390,0.382793,0.524243,0.530724,0.056431,-0.077702,-0.339320,-0.198027,0.386175', '3011051', '21619567', '20497633', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293864', '偷龙转凤', '喜剧', '妮可·伯纳特（奥黛丽·赫本 Audrey Hepburn饰），富有的收藏家查尔斯·伯纳特（休·格里夫斯 Hugh Griffith饰）之女。妮可不仅美丽漂亮更非常聪明智慧。一日，法国巴黎一所博物馆即将举行一次艺术品展览，喜好临摹名作制造赝品的父亲竟受邀参加美术展。然而这件被视为伟大杰作的维纳斯雕像，其实是她祖父制造的赝品，而父亲不仅答应让博物馆将它展出，还在保险公司发现是膺品前为它买下一百万美元的保险。事情一旦水落石出，家族势必名誉扫地、毁于一旦。为助父亲渡过难关，妮可聘请了一位高明的神偷西蒙·德莫特（彼德·奥图 Peter O''Toole饰）去把雕塑偷走。一位风度翩翩的雅贼，一位机智美丽的尤物，在偷窃行动中，两人破天荒地相爱了。然而西蒙的真实身份，却让妮可大为震惊。美国著名导演威廉·惠勒继《罗马假日》大获成功之后，与著名影星奥黛丽·赫本再度合作，拍摄了本部带有轻喜剧和浪漫色彩的犯罪影片《偷龙转凤》。精巧周密的剧情设计，惠勒标志性的高超镜头调度，为本片增添了几分黑色与讽刺的意味。', '奥黛丽·赫本', '威廉·惠勒', 8.1, 10651, 'tt0060522', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1077594334.jpg', 0.2, 1.1, 20.4, 50.7, 27.6, '-0.121576,0.090603,-0.577822,0.688114,0.005724,-0.231860,0.658266,0.000496,-0.341348,-0.370770,0.289264,0.831614,-0.342272,-0.009476,0.327046,0.249572,-0.279523,-0.426569,-0.023203,-0.055303,0.056082,-0.414782,-0.413534,-0.132605,0.019356,-0.341491,0.480623,0.061977,-0.326241,0.437101,0.294837,0.292389,-0.049094,-0.047533,-0.156667,-0.304415,0.273192,0.064918,-0.313557,0.277801,-0.043294,-0.178611,-0.177986,0.191627,-0.153828,0.145127,0.469187,-0.142562,-0.138634,-0.079854,0.632247,-0.172958,0.135527,0.038680,-0.041193,0.123298,0.036082,0.334253,-0.434487,-0.053465,0.477468,-0.253892,-0.723355,0.075823,0.289252,-0.065874,-0.360821,0.336711,-0.234425,-0.031769,0.138146,-0.216246,0.185424,-0.083665,0.364118,0.074994,0.369427,0.339265,-0.467633,0.373689,0.277134,0.004392,-0.171592,0.291740,-0.125672,-0.326664,0.109221,-0.392887,-0.237780,0.325507,0.402407,-0.260487,0.449233,0.204633,-0.571687,-0.440928,-0.550796,0.019198,-0.034265,-0.226467,0.063797,-0.832089,-0.146062,-0.207591,-0.223203,-0.345426,0.184377,-0.327681,0.679512,-0.448508,0.058051,0.388561,0.018655,-0.322727,0.482435,0.022988,0.089043,-0.097476,-0.346316,0.011872,0.239189,-0.165872,-0.190347,0.340928,0.159369,-0.316061,-0.309683,0.434975', '3318306', '2027945', '22265121', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293867', '和平饭店', '动作', '江湖杀手阿平（周润发 饰）是和平饭店的老板，传闻他武功了得，曾经一口气杀了二百多个马贼，并且他宣称和平饭店是一个“避难所”，只要进来住宿的人，无论他得罪了什么帮派，都不许前来挑衅生事，但不保证离开后的安全。歌女阿曼（叶童  饰）的到来打破了这个江湖规矩。阿曼被人追杀，逃至和平饭店。她风情万千，令阿平心生爱意并设法保护她离开饭店，躲避追杀。然而，阿平的用情换来了一个早已布下的陷阱：原来阿曼正是这个陷阱的诱饵！愤怒的阿平决定拿起武器重出江湖，一场腥风血雨的厮杀大肆铺开。©豆瓣', '周润发', '韦家辉', 7.7, 62688, 'tt0113292', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1863974996.jpg', 0.4, 2.8, 28.6, 49.5, 18.8, '0.253506,0.020360,-0.447629,0.569633,-0.364084,-0.071942,0.539824,0.058608,-0.385211,-0.231315,0.477303,0.585229,0.051253,-0.036833,-0.022327,0.031431,-0.080945,-0.527566,-0.138658,-0.299164,-0.076847,-0.162203,-0.110110,-0.349381,-0.002897,0.106209,0.356768,0.271579,-0.172229,0.398543,0.157793,-0.029799,-0.259943,0.504907,-0.152871,-0.089940,0.034968,-0.117922,-0.333015,0.167118,-0.373464,-0.386680,-0.340825,0.479546,-0.008866,0.514904,0.389893,-0.090666,-0.144832,-0.024423,0.216121,-0.658906,0.131559,0.094824,0.310445,-0.320407,0.248293,0.138394,-0.147895,0.218098,-0.040729,0.052265,-0.607048,0.096659,0.001670,-0.252549,-0.624458,0.479418,-0.216924,-0.082387,-0.263642,-0.079115,0.359265,0.200440,0.314042,0.033646,-0.090170,0.083676,-0.845023,-0.072789,0.734867,-0.342933,0.248459,-0.024040,-0.012723,-0.482710,0.082565,-0.259522,-0.467876,-0.209961,0.483884,-0.315732,-0.236577,-0.130477,-0.638457,-0.283478,-0.297548,0.017897,-0.023157,-0.435035,-0.254802,-0.419022,-0.188325,-0.024548,-0.245456,0.095338,0.150022,0.090270,0.575182,-0.703367,0.152920,0.643215,0.172686,-0.883541,0.482898,0.200135,0.055714,0.170653,-0.110566,0.304490,0.194205,0.377295,-0.028693,0.190151,0.105955,-0.247912,-0.204275,0.184580', '1877596', '25908042', '1297710', '3998385');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293868', '龙凤配', '剧情', '萨宾娜（奥黛丽·赫本 Audrey Hepburn 饰）出生在富有的拉若比庄园，但她并非千金贵族，而是该庄园一介小小司机的女儿。可悲的是，萨宾娜看上了庄园里风流成性的公子哥戴维（威廉·霍尔登 William Holden 饰），而后者从来没有将她放在眼里。萨宾娜遵循父亲的旨意前往巴黎学习厨艺，在此期间，逐渐成熟起来的萨宾娜散发出了惊人的魅力。与此同时，为了促进家族企业的发展，戴维与伊丽莎白（玛莎·海尔 Martha Hyer 饰）的婚事正在如火如荼的进行中。就在这个节骨眼上，学有所成的萨宾娜回到了庄园，她的归来立刻吸引了戴维的眼球，两人不顾长辈的反对感情迅速升温。为了维护弟弟的婚事，哥哥莱纳斯（亨弗莱·鲍嘉 Humphrey Bogart 饰）决定主动接近萨宾娜，以此来削弱她对戴维的依恋。在相处中，莱纳斯和萨宾娜之间产生了异样的感情，戴维得知此事同莱纳斯大打出手，而萨宾娜也误以为莱纳斯的感情只是一个阴谋。伤心的她逃亡巴黎，不久之后，莱纳斯也踏上了追随她的路途。', '亨弗莱·鲍嘉', '比利·怀尔德', 7.8, 33649, 'tt0047437', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1229587917.jpg', 0.2, 2.2, 28.6, 47.5, 21.5, '0.586921,0.146629,-0.929477,0.799504,-0.179991,-0.471661,0.749127,0.130952,-0.437234,-0.304821,0.249385,0.879792,-0.239358,0.071580,0.247270,0.190431,-0.369872,-0.638727,-0.068017,-0.209032,-0.095195,-0.690145,-0.122372,-0.274906,-0.232292,-0.327515,0.418528,-0.155003,-0.090461,0.716818,0.180107,0.219694,0.248794,0.413500,0.006168,0.075745,0.099366,0.139723,-0.268868,0.160974,0.161379,0.055546,-0.098234,0.198273,0.129088,0.500220,0.420774,-0.277094,0.291172,-0.141572,0.329097,-0.175782,0.409615,0.218076,0.454241,-0.132567,-0.118504,0.238323,-0.446539,-0.157633,0.050131,-0.228210,-0.473978,0.148093,0.111478,0.126903,-0.546751,0.425654,-0.120336,-0.270496,0.122249,-0.227709,-0.068803,0.328188,0.107046,0.314385,-0.069737,0.037858,-0.386721,-0.089802,0.584970,0.054690,-0.206892,0.334280,-0.413904,-0.312777,0.130766,-0.373374,-0.643531,-0.365874,0.438086,0.066985,-0.007108,0.725473,-0.352384,-0.232501,-0.477891,-0.055148,0.140163,-0.440677,0.078223,-0.601025,-0.273825,-0.489470,-0.159230,-0.027015,0.007230,-0.272434,0.523800,-0.947033,0.170782,0.434367,0.436952,-0.499833,0.598631,-0.046369,0.195562,-0.121632,-0.326000,0.519614,0.031611,-0.016313,0.003233,0.262715,0.0