INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293870', '阿黛尔·雨果的故事', '剧情', '美国内战时期，法国大作家Victor Hugo的二女儿Adele Hugo（伊莎贝尔·阿佳妮 Isabelle Adjani饰）漂洋过海来到加拿大的Halifax寻找自己的爱人——英国军官Pinson（布鲁斯·罗宾逊 Bruce Robinson）。然而Pinson却已移情别恋，对Adele异常冷漠。Adele想尽一切方法想挽回Pinson皆告失败。而另一方面，当地高昂的生活费也让Adele难以承受，只能一次又一次要求父亲汇钱。此时的Hugo正流亡在一个小岛上，妻子病重，两人多次希望Adele能返回家中，但Adele坚持留在加拿大。恋情的失败让Adele经常想起她溺水身亡的姐姐，她的精神开始变得错乱。之后，Pinson跟着部队离开Halifax前往另一个小岛Barbados，Adele也跟随而去，在那里，她的病情日益恶化，最终被送回法国，在休养院里度过余生，最终于一战时期悄然离世。本片是关于雨果二女儿Adele的传记片，扮演Adele的伊莎贝尔·阿佳妮获当年奥斯卡最佳女主角提名。', '伊莎贝尔·阿佳妮', '弗朗索瓦·特吕弗', 8, 18807, 'tt0073114', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1483320569.jpg', 0.3, 1.7, 21.8, 50.3, 25.8, '-0.136356,0.139144,-0.871412,0.670279,0.052197,-0.473471,0.672363,0.046736,-0.590317,-0.322442,0.179305,0.992358,0.203422,0.412428,0.276835,-0.150658,-0.271892,-0.503271,0.115816,0.024483,-0.307035,-0.505462,-0.181938,-0.205778,-0.218910,-0.383637,0.782899,0.242143,-0.111741,0.574753,0.268297,0.299334,-0.024238,0.407281,-0.102927,-0.054743,-0.020932,0.046434,-0.497007,0.486825,0.472494,-0.367191,-0.284994,0.303114,0.131582,0.289810,0.693440,-0.042272,-0.104483,0.000654,0.418241,-0.296802,-0.239611,0.108445,0.233646,0.055412,0.206045,0.195639,-0.423213,-0.121488,-0.053675,-0.057760,-0.475553,0.187756,0.147569,0.132787,-0.597893,0.285123,-0.154338,0.108617,0.045183,-0.387328,0.246999,0.683748,0.217072,0.340333,-0.330255,0.130411,-0.211452,0.092833,0.912658,-0.130482,-0.211008,0.251252,-0.076696,-0.227237,0.247789,-0.399295,-0.384240,0.201397,0.081293,0.024395,-0.222082,0.211677,-0.306120,0.026882,-0.564092,-0.332196,-0.021192,-0.150170,0.010380,-0.538559,0.049307,-0.034208,-0.118257,0.104032,0.062105,-0.247011,0.553826,-0.659595,0.356128,0.427094,0.322955,-0.773397,0.501478,0.218856,0.339847,-0.177301,0.163420,0.573238,-0.085084,0.194934,-0.089687,-0.202348,-0.138140,-0.074538,-0.556486,0.323998', '25721544', '6890343', '1303333', '4728584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293871', '欢乐谷', '剧情', '一次意外，内向的哥哥大卫（托比·马奎尔 Tobey Maguire饰）和火辣的妹妹珍妮弗（瑞茜·威瑟斯彭 Reese Witherspoon饰）来到了一片黑白的世界：欢乐谷。这里正是大卫喜爱已久的电视剧场景：没有彩色，人们过着没有波澜和惊险的平静生活。居民的人生像极了一套既定程序，每一天都过得规规矩矩毫无意外。夫妻相敬如宾，孩子乖巧听话，没有投不进篮框的篮球，没有写着故事的图书，没有误点的晚餐。兄妹的到来渐渐改变着这个黑白的世界。特别是在珍妮弗热情奔放的性格下，人们开始惊讶的发现，他们竟然看到了彩色。彩色在欢乐谷里弥散开来，看得见的人遭到看不见的人攻击。保守派们不能接受彩色的出现，不能看到人们打开欲望和本能这个潘多拉盒子，然而，欢乐谷还是轰烈的推进着彩色浪潮。©豆瓣', '托比·马奎尔', '盖瑞·罗斯', 8.3, 7156, 'tt0120789', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p893797071.jpg', 0.2, 1, 15, 52.2, 31.7, '0.440947,-0.072651,-0.971114,0.812684,-0.229750,0.044390,1.157741,0.193352,-0.500479,-0.318627,0.164825,0.529299,-0.516135,0.174311,0.004452,0.009153,-0.440612,-0.658269,-0.373432,0.046857,-0.125560,-0.375470,-0.306693,-0.267060,-0.084119,-0.388232,0.535375,0.177409,-0.019900,0.588253,0.218238,-0.076425,-0.171540,0.543631,-0.364785,0.258110,-0.151687,0.219950,-0.198168,0.036763,0.100364,-0.110085,-0.327137,0.369565,-0.010142,0.301657,0.778964,-0.690580,-0.272857,0.235162,0.431265,-0.107167,-0.098594,0.147568,0.217250,-0.006947,0.312159,-0.331801,0.032020,-0.092355,0.252879,-0.128393,-0.407596,0.244743,0.128091,0.662611,-0.508067,0.619833,-0.293944,-0.235731,0.095761,-0.491867,0.187562,0.072103,0.391394,0.434909,-0.218909,0.171614,-0.646466,0.107289,0.745295,0.215038,-0.690671,0.505942,-0.582079,-0.204246,-0.125010,-0.321502,-0.684769,0.155242,0.472544,0.276964,-0.262898,0.340040,-0.617392,0.110940,0.145814,-0.502667,-0.073349,-0.381612,-0.328581,-0.587035,-0.101074,-0.507469,-0.536044,0.338423,-0.429596,-0.118121,0.718979,-0.999263,0.372606,0.166547,0.118389,-0.176210,1.011980,-0.098529,-0.280638,-0.049773,-0.065118,0.017519,-0.038835,0.175378,0.289325,0.721832,-0.206261,0.021245,-0.346576,0.636560', '1292211', '1304862', '3055049', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293878', '超人2', '动作', '三名被囚禁在外层空间的克利顿星球大坏蛋逃了出来，来到地球上的一个小镇扬威肆虐。当时超人正与女友在冰宫卿卿我我，并且已经丧失了超人的全部本领而变成了平凡人。在这种不利的情况下，美国总统不得不向这三个大坏蛋求饶。后来超人振作起来，与三个坏蛋展开了殊死搏斗，最终战胜了三个大坏蛋。本片在特技效果上维持水准之外，导演理查德．莱斯特在这部续集加强了超人的人性描写，喜剧效果也较强，部分情节颇具讽刺效果。', '吉恩·哈克曼', '理查德·唐纳', 7, 9651, 'tt0081573', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2209377144.jpg', 0.9, 5.5, 49.6, 32.4, 11.6, '0.166845,0.225461,-0.548332,0.684727,0.019113,-0.254061,0.804560,0.164029,-0.217952,0.000130,0.154927,0.616544,-0.329341,-0.227094,0.014599,-0.343705,-0.399917,-0.543901,-0.283655,-0.070808,-0.382489,-0.419944,-0.622341,-0.034657,-0.209121,-0.516445,0.561271,-0.060583,-0.573689,0.169188,0.367354,0.088979,-0.107373,0.198313,-0.280833,0.136313,0.096538,-0.239733,-0.254839,0.759781,0.115812,-0.083861,-0.031808,0.181526,-0.277974,0.043032,0.779913,-0.177038,-0.386777,-0.123388,0.314488,-0.296999,-0.397995,0.196737,0.368467,-0.406276,0.219833,0.035347,0.147890,0.227708,-0.041310,0.059900,-0.843087,-0.060310,0.048291,-0.093619,-0.706428,0.492999,-0.156489,-0.021803,0.001853,-0.277301,0.038392,0.229368,-0.050008,0.530484,-0.205456,-0.032778,-0.667840,-0.004619,0.519279,0.251161,-0.614747,0.265379,0.311573,-0.400898,-0.523816,-0.308214,-0.220113,-0.054415,0.319084,-0.269006,-0.309303,0.095632,-0.867856,0.033067,-0.281514,-0.117375,-0.343600,-0.441744,-0.022248,-0.696581,-0.174818,-0.248318,-0.147806,0.018068,0.083999,-0.288484,0.880257,-0.840895,0.241564,0.541883,0.154579,-0.403000,0.352836,0.096916,0.048124,-0.050634,-0.045841,0.095360,0.142174,0.418565,0.196888,0.465093,-0.029344,-0.219937,-0.574343,0.595820', '1308585', '3005387', '24284209', '11810348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293889', '唐人街', '剧情', '1937年的洛山矶唐人街，警员杰克（杰克•尼科尔森 Jack Nicholson 饰）因不满这里的黑暗，辞职当起了私家侦探。这天，一个自称莫拉雷太太的女子请杰克调查丈夫的外遇，杰克欣然接受。杰克发现莫拉雷原来是当地水利总工程师，正在为兴建水坝问题和当地农民争执。随后有人给 了杰克一些证明莫拉雷偷情的照片，隔天早上真正的莫拉雷太太却找上门来要求杰克停止调查莫拉雷。事情变得越来越迷离，杰克决心追查下去……©豆瓣', '杰克·尼科尔森', '罗曼·波兰斯基', 8.4, 56191, 'tt0071315', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p774377097.jpg', 0.3, 0.9, 12.9, 49.5, 36.4, '0.189204,-0.193447,-0.339783,0.148179,-0.208538,-0.508001,0.840223,0.485185,-0.662294,-0.405068,0.084542,0.170911,-0.188830,-0.007036,0.443790,0.029968,-0.810909,-0.326045,0.239172,0.006936,-0.087858,-0.597229,-0.077095,-0.448521,0.112996,-0.202854,-0.053183,-0.087124,0.022550,0.257943,0.325001,0.301767,0.116061,0.400573,0.110554,-0.147279,0.455368,-0.380032,-0.357913,0.318218,-0.015813,0.061150,-0.183393,0.055184,0.104012,0.501690,-0.128850,0.390834,-0.207656,-0.301483,0.199598,0.137508,0.132620,0.227253,0.620599,0.136232,0.214475,0.076794,-0.371281,-0.402783,-0.094401,0.167397,-0.467781,0.567219,0.099991,0.346855,-0.490892,-0.306439,-0.577973,-0.046962,-0.190841,-0.496620,0.100605,0.380326,0.138936,0.242648,0.091813,0.096766,-0.450811,0.078352,0.280688,-0.140941,0.313852,0.087963,0.082661,-0.301880,0.187932,0.331337,-0.576500,0.065715,0.166816,-0.204091,-0.196378,0.332989,-0.537423,-0.468709,-0.412621,-0.358706,-0.188856,-0.274335,-0.398742,-0.638058,-0.254534,0.023546,0.095681,-0.335945,0.104129,0.097955,0.224401,-0.546810,0.386452,0.504873,0.149986,-0.069659,0.282455,0.083740,0.290093,-0.317690,-0.129844,-0.165506,0.112155,0.320192,-0.235810,0.082430,0.298489,-0.452167,-0.036660,0.302795', '4132395', '2369549', '26611804', '1299080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293896', '一吻定江山', '剧情', '裘西（德鲁•巴里摩尔 饰）的职业是一名编辑，可是她最想做的是记者。相貌平平的她从未与别人亲吻过，因此她也期盼着属于自己的真爱出现。报社为了增加销量，决定让裘西假扮高中生到校园调查，做一个年轻人言行的报导。这次机会成就了裘西的梦。但进入校园后她受到了同学们的嘲弄，取笑她是丑小鸭。既然当上记者了，裘西就力求把任务做到最好，于是她一改平日的风格，通过打扮要与高中生们拉近距离。可是事情并没有顺利发展，也因为遭到排挤，让她做出来的报道也未能满足老板的要求。事情还是出现了转机，她的同学们终于接受了她。但令她矛盾的事又发生了，裘西与校内的老师森（迈克尔•瓦尔坦 饰）相爱了，老板却要她转为报道校内师生恋的情况……©豆瓣', '德鲁·巴里摩尔', '拉加·高斯内尔', 6.5, 6085, 'tt0151738', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p809858580.jpg', 2, 11.6, 54.9, 24, 7.5, '0.357642,-0.046860,-0.439206,0.648048,-0.192107,-0.262744,0.681030,0.119052,-0.512908,-0.199275,0.051192,0.608590,-0.317597,0.205052,0.176388,0.008573,-0.421138,-0.833374,0.264280,-0.267032,-0.081487,-0.347147,-0.037608,-0.273830,-0.080936,-0.249610,0.504624,-0.021877,-0.419304,0.193580,0.420957,0.118541,0.281824,0.616773,-0.044228,-0.196139,0.121977,0.241407,-0.137369,0.167275,0.111348,-0.248639,-0.402314,0.403490,0.221273,0.490910,0.502136,-0.019843,-0.470889,0.150542,0.252655,-0.369307,0.272069,0.312196,0.226414,-0.060519,0.311595,0.285524,-0.032550,0.000251,-0.014505,-0.014333,-0.746417,0.161193,0.017895,0.163312,-0.538121,0.301346,-0.184073,-0.055624,0.069263,-0.375811,0.031283,0.294612,0.399070,0.061384,-0.089764,-0.065553,-0.605119,0.178714,0.805088,0.138822,-0.356593,0.454820,-0.344326,-0.474474,-0.172030,-0.284170,-0.484271,0.254359,0.000674,-0.054543,-0.223227,0.243463,-0.402642,-0.248892,-0.325450,-0.359819,-0.132788,-0.515975,0.076952,-0.482769,-0.107111,-0.249198,-0.698644,-0.154788,0.055612,-0.493373,0.829264,-1.004350,-0.019980,0.733023,0.325522,-0.800886,0.744194,0.242147,-0.005996,-0.210422,-0.051473,-0.162437,-0.090953,0.289215,0.080585,0.403942,0.175027,-0.448983,-0.198552,0.589078', '1877596', '4301278', '3230462', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293899', '一个头两个大', '喜剧', '查理（金•凯瑞 饰）是一名善良的巡警，他的妻子与别人偷情生下三个儿子后与情人私奔了。可是查理仍把三个儿子视为己出，儿子们也十分尊敬这个老爸。镇上的人们都欺负查理的善良，终于隐藏在查理体内的另一个狠角色——阿庆出现了。阿庆与查理截然不同，他到处捣乱，到处生事。警方为查理检查，发现他患上了精神分裂，需要用药物治疗。这时查理要护送美女伊莲（芮妮•齐薇格 饰）回去纽约，可是伊莲的前老板狄克所做的不法事情被举报了，他认为举报者就是伊莲，于是狄克买通了警察等人，誓要杀死伊莲。伊莲求助与查理，于是两人还有阿庆一起开展了一段亡命之旅。查理的药却丢在了旅馆里，于是一路上查理与阿庆毫无预兆的更换着，更复杂的是查理与阿庆都爱上了伊莲，查理与阿庆争风吃醋，争斗不断。而警察与狄克一直穷追不舍查理他们……©豆瓣', '金·凯瑞', '博比·法雷里', 7.3, 34948, 'tt0183505', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p853041170.jpg', 0.5, 4.3, 40.8, 40.2, 14.2, '0.134998,-0.256600,-0.469557,0.460921,-0.320964,-0.527519,0.803168,0.029521,-0.545279,-0.064211,0.139283,0.790732,-0.061252,0.256711,0.309563,0.109361,-0.667536,-0.708851,-0.090707,-0.013701,-0.298604,-0.501570,-0.062597,-0.383535,-0.133084,-0.042495,0.123077,-0.482198,-0.183733,0.441939,0.375561,0.380565,-0.137787,0.413160,-0.090003,0.250561,0.235135,-0.307892,-0.249583,0.181326,0.182303,-0.120434,-0.150999,0.225032,0.117870,0.478020,0.470215,-0.237965,-0.166967,-0.322998,0.197417,-0.234641,0.087233,0.174464,0.246868,-0.044871,0.383818,0.132126,-0.237069,-0.007489,0.152226,0.174682,-0.664641,0.160848,-0.070171,0.200149,-0.628625,0.300798,-0.009170,0.045381,0.173677,-0.430363,0.475921,0.209472,0.012573,0.287268,-0.166564,-0.247479,-0.507907,-0.010761,0.450745,0.029474,0.074910,0.187856,-0.039699,-0.246859,0.249133,0.109363,-0.603378,-0.174094,0.424827,-0.021852,-0.234318,0.174820,-0.485015,-0.217547,-0.299495,-0.130162,-0.157517,-0.290744,0.002264,-0.572412,0.034000,-0.594944,-0.485189,-0.068408,0.101631,-0.108871,0.524231,-0.690109,0.275632,0.654298,0.255770,-0.623154,0.575963,0.177818,0.199307,-0.040198,-0.154366,0.012776,0.258343,0.234556,0.427012,0.413002,0.002663,-0.164693,-0.254814,0.364185', '1297418', '1299799', '3111650', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293904', '星际旅行7：斗转星移', '动作', '寇克等人作为嘉宾乘新企业号试航，途中收到救援任务……而在另一时空，索伦博士正阴谋毁灭星球，攻击企业号。唯一能够帮助新船长皮卡特来阻止索伦的，只有销声匿迹了78年的寇克船长。', '帕特里克·斯图尔特', '大卫·卡森', 7.2, 6524, 'tt0111280', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209408643.jpg', 1, 5.4, 40.3, 38.2, 15.1, '-0.573815,0.183919,-0.421550,0.284719,0.296694,-0.128218,0.274396,0.328961,-0.406564,-0.258024,0.133040,0.595270,0.475203,-0.021108,0.812679,0.082704,-0.567939,-0.131587,-0.018641,-0.203766,-0.810698,-0.520807,-0.020260,-0.714177,0.381508,-0.688173,0.798163,0.137897,0.146849,0.122662,0.416942,0.480899,-0.201217,0.745344,-0.279640,-0.223188,0.625819,-0.394260,-0.506243,0.617092,-0.492939,0.153898,-0.066463,0.193184,-0.220215,0.420165,0.298472,-0.404420,0.337673,-0.416803,-0.168501,-0.297972,0.160870,-0.664355,0.599449,-0.057189,-0.005309,0.253276,0.058235,-0.197954,0.066003,-0.402074,-0.821540,-0.089894,-0.194008,0.269495,-0.071920,-0.048349,-0.277053,0.406292,-0.149990,-0.157088,0.127866,0.544648,0.492963,0.046315,-0.203119,0.564965,-0.272634,0.078358,0.414917,-0.175254,-0.190801,0.221427,0.187805,-0.457673,-0.069737,-0.516717,-0.047670,0.251787,0.277365,0.422294,-0.077689,0.199006,-0.734431,-0.069861,-0.622822,-0.340380,0.307360,-0.512027,-0.333091,-0.931747,0.246586,0.689231,0.037380,0.382077,0.253713,-0.001282,0.689087,-0.805486,0.252385,0.884309,0.331863,-0.425182,0.869477,0.016729,0.198823,-0.665734,0.215651,0.144730,0.044013,0.622649,-0.055428,-0.036758,0.176018,-0.381900,-0.015467,0.176916', '2369613', '3861846', '1309112', '1293656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293908', '城市之光', '剧情', '他是一个流浪汉（查理·卓别林 Charles Chaplin 饰），身无分文，遇上了双目失明的卖花女，却不忍袖手旁观。他想尽办法去凑够费用，供卖花女治病。一天，他搭救了一个富翁，富翁当晚和他称兄道弟，第二天却翻脸不认人。本来打算向他求助的主意行不通了。流浪汉去参加拳击比 赛，以图获得奖金，却输得一败涂地。谁知这时重遇富翁，二人不计前嫌，富翁答应出钱资助卖花女。在交给流浪汉1000元后，富翁遭到偷袭，身上剩下的钱被强盗抢走。流浪汉奋不顾身去追赶，却因为误会被警察押回警局坐牢。另一方面，卖花女凭借流浪汉的资助重获光明，开了一家体面的花店。©豆瓣', '查理·卓别林', '查理·卓别林', 9.3, 133265, 'tt0021749', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2170238828.jpg', 0.1, 0.2, 3.8, 25.2, 70.7, '-0.024483,0.038114,-0.384783,-0.140168,-0.587885,-0.531518,0.593574,0.112433,-0.121763,-0.170939,0.105272,0.812456,0.035167,0.005655,0.240962,-0.259471,-0.049527,-0.251458,0.263586,-0.035838,0.008698,-0.260588,0.035506,-0.175438,-0.162069,0.012035,0.231245,0.185955,-0.168467,0.650111,0.323163,0.230686,-0.015615,0.299167,-0.351653,0.026138,-0.033210,-0.013732,-0.159047,0.530489,-0.053262,-0.261355,-0.107482,-0.041752,0.126105,0.475874,0.425494,0.261882,0.088397,-0.191088,0.167361,-0.311298,-0.125745,0.168699,0.102154,0.001811,0.111630,-0.299851,-0.191207,-0.237732,0.259550,-0.058978,-0.492125,0.096769,0.190856,0.040797,-0.863917,0.363321,-0.191550,0.318294,-0.092283,-0.233334,0.130130,0.095131,-0.082640,0.241906,0.035709,0.137770,-1.016900,0.366490,0.822117,0.047667,0.283527,0.086973,0.099357,-0.128872,0.595670,-0.373504,-0.209349,0.079329,0.649580,-0.297254,-0.232118,-0.289484,-0.366102,-0.281085,-0.463133,-0.002719,-0.036163,-0.469834,-0.012407,-0.245616,0.169945,0.404702,-0.108542,0.260489,0.190649,-0.346081,0.338792,-0.414812,0.059543,0.764200,0.765322,-0.612474,0.646146,-0.018347,0.108543,-0.032119,-0.103267,-0.173507,0.578429,0.607445,0.352375,-0.279545,-0.095203,-0.341882,0.065398,0.268995', '1306505', '1292584', '10745405', '1292216');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293909', '从海底出击', '剧情', '二次世界大战期间，德国发明了一艘出没无踪的潜艇，在海战中无往不利。一次，这艘潜水艇奉命出击，执行对英国船队的袭击任务，当他们完成任务返航途中，却遭遇上前所未见的危机。潜在的重重危机随时威胁着舰艇上官兵的生命安全，这个貌似强大而冷冰冰的庞然大物完全不能自保，一切 只能听天由命......影片改编自战地记者布克海姆的畅销自传，荣获1982年第54届奥斯卡金奖六项提名。 沃尔夫冈·彼得森成为第一位凭着德语电影获得最佳导演提名的人。©豆瓣', '尤尔根·普洛斯诺', '沃尔夫冈·彼德森', 9.1, 38994, 'tt0082096', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2088879323.jpg', 0.2, 0.6, 6.8, 30.5, 61.9, '-0.000509,0.072989,-0.714765,0.842472,0.334553,-0.076928,0.418459,-0.198973,-0.417401,0.024227,0.422070,0.901369,0.159352,-0.201767,0.344549,-0.093179,-0.433495,-0.538011,-0.217547,-0.083906,-0.373797,-0.458860,-0.577167,-0.055428,0.091157,-0.355842,0.860900,0.457955,-0.367293,0.480324,0.374728,0.227263,-0.043258,0.459561,-0.083039,-0.225786,0.311581,-0.192926,-0.250831,0.492783,-0.307973,-0.307558,-0.270289,0.043688,-0.025968,0.335071,0.587346,-0.374757,-0.134877,-0.169384,0.336820,-0.726473,0.016678,-0.189851,0.242182,0.067003,-0.045140,0.052537,0.081626,-0.026116,-0.146307,-0.059446,-0.819066,-0.273748,-0.196316,0.178435,-0.251536,0.109604,-0.501943,0.577694,-0.301164,-0.087348,0.039371,0.228188,0.156489,0.047286,-0.340292,0.419560,-0.584728,0.402846,0.563046,-0.209511,-0.718492,-0.035452,0.240087,-0.282518,-0.016207,-0.802462,-0.250302,0.210078,0.229885,0.078403,-0.042891,0.066976,-0.382048,0.217880,-0.403737,-0.599629,-0.292173,-0.021329,-0.011985,-1.065156,0.318492,-0.021960,-0.275908,0.178349,0.250992,-0.193327,0.667807,-0.332811,0.376926,0.783936,0.067879,0.014392,0.607048,0.167483,0.117903,-0.480260,0.019618,0.031000,-0.257453,0.217814,0.086116,0.252539,0.194618,-0.376169,-0.036661,0.601350', '1293433', '1298911', '26275494', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293917', '尽善尽美', '剧情', '作家梅尔文（杰克•尼科尔森 饰）是一个脾气古怪的强迫症老头，没有家庭也没有朋友，整天关在屋里写他的第六十二部小说，生活如时钟般精准，受不了一点的打扰。梅尔文的邻居西蒙（格雷戈•金尼尔 饰）是年轻的同性恋画家，养了一条可爱的小狗，生性活泼，脾气温和，经常受到梅尔文的侮辱。梅尔文每天只出门一次，到同一家餐厅吃饭，餐厅女招待卡罗尔•康奈莉（海伦•亨特 饰）是唯一愿意而且能够为他服务的人。离了婚的卡罗尔与儿子斯潘塞住在一起，斯潘塞患有严重的哮喘病，这使得许多对卡罗尔有意思的男子知难而退。一天，西蒙的住所遭到抢劫，西蒙身受重伤，住院前，将小狗托付给梅尔文照料，梅尔文渐渐喜欢上了这个小家伙，心理也发生了变化，开始关注周边的世界，主动帮助别人，认真审视自己对卡罗尔的好感……©豆瓣', '杰克·尼科尔森', '詹姆斯·L·布鲁克斯', 8.2, 30173, 'tt0119822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p643387266.jpg', 0.3, 1.3, 17.6, 48.8, 32, '0.370318,-0.220193,-0.654737,0.384415,-0.424519,-0.175391,0.766823,0.323463,-0.664278,-0.181320,0.122655,0.737735,-0.148220,0.352798,0.138343,0.106908,-0.084858,-0.390885,-0.043334,0.109902,-0.200976,-0.466845,-0.224019,-0.400739,-0.194304,-0.618626,0.019740,-0.162818,-0.017607,0.482328,0.298407,0.205159,0.188232,0.318117,-0.206175,0.032234,0.042544,0.051490,-0.042237,0.150060,0.148267,0.180263,0.052591,0.159232,0.184110,0.382676,0.590888,0.002036,-0.602448,-0.200144,0.485553,0.035335,-0.003701,0.176009,0.547343,-0.072128,0.395852,-0.005622,-0.080153,0.029057,-0.120727,-0.157792,-0.414194,0.006991,0.186714,0.219306,-0.469893,0.489572,-0.159890,-0.147190,-0.066423,-0.254835,0.118081,0.135017,0.183126,0.393292,0.105972,0.228221,-0.313870,-0.108024,0.496050,0.056063,-0.314545,0.507369,-0.530413,-0.006444,0.040194,-0.382269,-0.714289,0.179910,0.135072,-0.195728,-0.325314,0.011117,-0.414090,0.072778,-0.090034,-0.097794,-0.045861,-0.335377,-0.138555,-0.475658,-0.045492,-0.610675,-0.245749,0.040788,-0.046893,-0.252958,0.674428,-0.711914,0.363140,0.505614,0.262224,-0.548003,0.735053,0.106424,0.029327,-0.110385,0.089200,0.238277,0.263547,-0.072579,0.033876,0.351879,0.131015,-0.072379,-0.274560,0.368219', '27191173', '1292720', '1309161', '1308314');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293925', '橡皮头', '恐怖', '阴暗压抑的工业小镇，刺耳的机器轰鸣噪音。亨利•斯班瑟（杰克·南斯饰）初次拜访女友家，然而目睹到的却是一个怪异扭曲的家庭，霸道的母亲、无能的父亲、植物人似的祖母以及笨拙的女儿。而更令亨利感到无助的是，他被迫与女友结婚。一夜之间，亨利成为一个畸形儿的父亲。相貌丑陋恶心的婴儿让亨利异常恐惧焦虑，也让新婚妻子因忍受不了婴儿的啼哭而半夜出逃。亨利再也忍受不了如此不堪的生活和夜夜噩梦，他最终亲手用剪刀肢解掉了这个畸形的早产儿。由美国电影新浪潮运动旗手大卫·林奇创作的长片处女作《橡皮头》，历时五年完成。一经公映，便以强烈的前卫诡异风格挑战了当时还相当传统和保守的电影界。在情绪化的摇晃镜头与随处可见的阴暗腐败中，大卫·林奇构筑出了一幅扭曲病态的家庭人物关系，赤裸裸地破开人性的阴暗面。这种运用弗洛伊德心理分析，来剖析人类精神世界中焦灼郁闷的手法，加上极具视觉冲击力的影像，让大卫·林奇在影坛独树一帜。', '杰克·南斯', '大卫·林奇', 7.9, 15508, 'tt0074486', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1334208717.jpg', 1.5, 3.4, 21.4, 44.3, 29.4, '0.102432,-0.032088,-0.645818,0.657535,-0.089308,-0.137218,0.897097,0.309227,-0.598567,-0.278566,0.276794,0.640491,-0.273118,0.224540,0.050458,-0.097802,0.030917,-0.550777,-0.244079,0.125892,-0.182076,-0.274494,-0.189176,-0.505049,-0.087038,-0.535863,0.660664,0.056211,-0.318398,0.377154,0.235649,0.236870,0.074644,0.365779,-0.166487,-0.128881,-0.136073,0.080922,-0.208338,-0.109349,0.177773,-0.103964,0.158369,0.448139,-0.525048,0.398246,0.667096,-0.268103,-0.165556,-0.115493,0.636345,0.030928,-0.396218,0.331066,0.091914,-0.131281,0.081284,-0.078500,-0.275217,0.087552,0.046288,0.150570,-0.919815,0.214642,0.070104,-0.009610,-0.395341,0.306859,-0.087457,0.025346,0.084112,-0.309511,0.103151,-0.031254,0.249733,0.852514,-0.289926,0.218767,-0.061385,0.228563,0.369472,0.015403,-0.725492,0.294104,-0.623052,-0.294915,-0.024388,-0.622155,-0.638304,-0.021706,0.197999,-0.020141,-0.386164,0.426985,-0.703930,0.003201,-0.270909,-0.058642,-0.213438,-0.302667,-0.134528,-0.547523,-0.302731,-0.348768,-0.112642,-0.193636,0.066835,-0.211970,0.488043,-0.503518,0.166328,0.496260,0.029548,-0.067290,0.240578,0.055944,-0.079014,-0.136783,-0.240628,0.488502,-0.131332,0.071692,-0.019262,0.474617,-0.052298,0.176213,-0.391500,0.657207', '2133337', '1294434', '26667010', '1299261');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293926', '看得见风景的房间', '剧情', '19世纪的英国，阶级隔阂还十分分明。这天，英国上层出身的露西（海伦娜•邦汉•卡特 Helena Bonham Carter 饰）和表姐夏洛特一起佛罗伦撒度假，不巧，露西住的酒店的房间看不到风景。同时来住店的英国父子两乔治（朱利安•桑兹 Julian Sands 饰）和他父亲见状，热心的父亲要和露西换一间房，因为他的房里能看到风景。露西开始不同意，在好心的店主的劝说下最终她同意了。乔治和露西很快堕入了爱河，然而下等阶层出身的乔治身上有着很多露西看不惯的“陋习”，夏洛特也不甚喜欢乔治，双方在交往中闹了不少“笑话”。一次，乔治“越轨”吻了露西一下，露西认为乔治太过“不合礼仪”，于是独自回了英国。乔治很快也回了国，然而，这时露西已经订了婚……©豆瓣', '玛吉·史密斯', '詹姆斯·伊沃里', 7.7, 50130, 'tt0091867', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2237899275.jpg', 0.3, 2.1, 29.4, 48.2, 19.9, '0.770577,0.058151,-0.656471,0.479294,-0.104076,-0.506022,0.735455,0.366711,-0.437252,-0.218530,-0.275876,0.908758,-0.357195,0.347125,0.352727,0.164405,-0.702251,-0.365548,0.043907,-0.258859,-0.271985,-0.645535,0.100233,-0.213021,-0.346986,-0.044540,0.088100,-0.171610,0.155396,0.430420,0.455698,0.366399,0.072091,0.533164,-0.108578,0.088840,0.191372,-0.146780,-0.288588,0.243826,0.261480,0.079400,-0.176295,0.209530,0.309004,0.286843,0.242977,-0.085087,0.275614,-0.030292,0.215333,0.069374,0.082024,0.281947,0.469595,-0.317375,0.255651,0.151864,-0.071751,-0.104071,0.171423,0.102876,-0.301582,0.298693,0.058247,0.105564,-0.724106,0.495434,-0.170847,-0.140663,-0.037377,-0.417166,0.175679,0.658419,0.121236,0.242816,0.034431,0.051817,-0.666209,-0.275459,0.686536,0.368619,-0.033060,0.425279,-0.286874,-0.336474,0.116448,-0.034930,-0.459159,-0.146522,0.428149,0.021904,-0.025202,-0.118999,-0.522380,-0.296036,-0.185645,-0.285110,-0.053486,-0.447651,0.151210,-0.794412,-0.266698,-0.737385,-0.477902,-0.181093,-0.076624,0.135644,0.325398,-0.894025,0.016895,0.265884,0.579045,-0.238335,0.723993,0.305582,0.127365,0.098927,-0.011213,0.143545,0.001084,0.161634,0.282732,0.600991,0.238159,-0.249612,-0.177377,0.346310', '1297239', '1302384', '26809592', '1296538');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293929', '廊桥遗梦', '剧情', '弗朗西斯卡·约翰逊（Meryl Streep 饰）去世了，留下的遗嘱要求孩子们将自己的骨灰撒在罗斯曼桥。困惑的孩子们翻看母亲的遗物，揭开了母亲生前的一段动人感情。 1965年夏季的一天，主妇弗朗西斯卡送走了丈夫理查德（Jim Haynie 饰）和孩子们，独自做着家务。摄影师罗伯特·金凯德（Clint Eastwood 饰）误打误撞来到这里，向她打听罗斯曼桥的所在。她平静的心起了波澜，于是带他来到桥头。当天的工作结束后，他送她一把野花致谢，并接受她的邀请，与她共进晚餐。第二天凌晨他走后，恋恋不舍的她回到罗斯曼桥，将一张字条钉在桥头，邀请他再次共进晚餐。他再次接受了邀请。两人在罗斯曼桥相会，爱情的火焰在两人心中熊熊燃烧。他请求她随他一起远走，但她割舍不下现有的家人和世俗的幸福。他黯然离开。 十多年后，深爱弗朗西斯卡的理查德去世。又过三年，她收到了罗伯特的死讯。他把大部分的东西留给了她，并要求将自己的骨灰撒在罗斯曼桥。', '克林特·伊斯特伍德', '克林特·伊斯特伍德', 8.7, 206615, 'tt0112579', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190558219.jpg', 0.4, 0.9, 10.4, 39.1, 49.2, '0.339925,0.311350,-0.795287,0.560562,-0.286125,-0.401930,0.739050,0.178015,-0.336249,-0.198572,0.272038,1.034270,-0.137971,0.590623,0.266655,0.309094,-0.330020,-0.879281,0.167157,-0.230328,-0.246285,-0.548141,0.053992,-0.245625,-0.151616,-0.303147,0.303976,-0.047633,0.284378,0.488074,0.232398,-0.040835,-0.050382,0.564622,-0.288519,0.227684,-0.073355,-0.077821,-0.300209,0.059615,0.182562,-0.382696,-0.191201,0.154321,0.258828,0.293225,0.732250,-0.082625,0.049098,0.226380,0.049489,-0.288674,0.049148,0.423036,-0.086335,0.012060,-0.021058,0.292978,-0.454212,-0.130305,0.093072,0.051855,-0.295572,0.062079,-0.376402,0.132769,-0.908474,0.723561,-0.353665,0.200223,0.070580,-0.493945,0.235467,0.386740,-0.283668,0.242574,-0.267787,0.023973,-0.328135,0.377365,0.549927,-0.189045,0.188920,0.133559,-0.197097,-0.260407,0.130196,0.144398,-0.426264,-0.017500,0.637323,0.236333,-0.191000,0.130806,-0.733138,-0.309175,-0.375538,-0.332639,0.168100,-0.514651,-0.110662,-0.651464,-0.066995,-0.215460,-0.529879,0.036939,0.024209,-0.287578,0.681927,-0.373226,0.539128,0.334727,0.285519,-0.497650,0.736669,0.156660,0.176998,-0.094299,0.183555,0.571767,0.035119,0.423742,0.515191,0.315857,-0.052932,0.228556,-0.502564,0.451162', '30162520', '1895119', '1307146', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293934', '爱国者', '剧情', '故事发生在美国独立战争时。本杰明（梅尔•吉布森 Mel Gibson 饰）是法国裔美国人，他曾参加过法国人与印第安人的战争，身经百战。残酷的战争令他失去了心爱的妻子，他发誓要永远远离战争。所以当英国殖民者将战争烧到本杰明的家园时，他首先选择的不是奋起反抗，而是躲避。当他看到他的大儿子参加了当地组织的爱国者军队时，也没有跟着挺身而出。但是，当他的大儿子被敌军俘虏，小儿子挺身去救哥哥而被打死时，本杰明再也按捺不住了。他这时才清楚意识到，只有反抗才能解救家园于水火。©豆瓣', '梅尔·吉布森', '罗兰·艾默里奇', 8.2, 34783, 'tt0187393', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247135266.jpg', 0.3, 1.4, 18.8, 49.5, 30.1, '0.099548,0.103162,-0.905515,0.237222,-0.154236,-0.481927,0.561912,-0.210302,-0.543928,-0.034727,0.047711,0.936160,0.286657,0.022145,0.106185,0.040061,-0.100062,-0.875245,-0.093568,0.264481,-0.324740,-0.240606,-0.015568,-0.393865,-0.135727,-0.377613,0.770526,0.116684,-0.456593,0.364228,0.328970,0.375225,0.281505,0.771732,0.033999,-0.058282,0.044205,-0.143629,-0.490835,0.290726,-0.131370,-0.393014,-0.455525,0.458655,-0.043102,0.345927,0.437179,-0.402517,0.016322,-0.395436,0.261426,-0.549466,-0.017993,0.276462,0.095726,-0.145516,-0.063127,0.263504,0.180311,-0.222284,0.140902,0.024481,-0.632885,0.055119,-0.062521,-0.105613,-0.790553,0.329012,-0.270556,0.105425,0.185835,-0.274290,0.561643,0.564109,0.069659,-0.006127,-0.418177,-0.197292,-0.743132,0.407986,1.037866,-0.199081,-0.241299,0.003315,-0.079949,-0.420763,0.093786,-0.619579,-0.379351,0.222080,0.322761,0.034828,-0.521259,0.139058,-0.426684,-0.346771,-0.394320,-0.390307,0.089295,-0.334774,-0.079803,-0.289281,-0.118427,-0.210862,-0.364069,0.124853,-0.226190,-0.075265,0.680426,-0.890649,0.382769,0.868254,0.548040,-0.539192,0.736983,0.183033,0.046146,-0.096257,0.226058,0.508721,0.163041,0.230912,0.168532,-0.058583,0.114801,0.025649,-0.058810,0.573457', '25908042', '25721544', '1870682', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293935', '名人百态', '剧情', '故事讲述一名记者，为融入上流社会，不惜趋炎附势，放弃尊严，看尽名人百态的他，最后也只落得一场空。', '肯尼思·布拉纳', '伍迪·艾伦', 7.5, 6726, 'tt0120533', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191049149.jpg', 0.7, 3.1, 34.4, 45.7, 16.1, '-0.386887,0.023651,0.506423,0.293949,0.038422,-0.425673,0.300098,0.007549,-0.576947,-0.410479,0.293209,1.049228,-0.005301,-0.253012,0.410287,-0.408263,-0.284266,-0.950900,0.176063,0.371738,0.457530,-0.482126,0.131183,-0.177673,-0.641855,0.515091,0.754932,0.673291,-0.753552,-0.239893,0.871274,-0.089850,-0.256817,0.292314,-0.561230,0.163095,-0.029520,0.117156,-0.218334,-0.266612,-0.322370,-0.520125,-0.311532,0.296328,-0.627158,-0.161277,0.773873,-0.022063,0.294535,-0.332915,0.899726,-0.406724,-0.125616,0.339959,-0.068885,0.410145,0.606299,0.485624,0.207859,0.044555,0.217220,0.207071,-1.244742,-0.478467,0.375180,0.046687,-0.350519,0.449042,0.346789,-0.042831,0.110292,0.024891,-0.043205,-0.328971,0.775467,0.227584,-0.168354,-0.130202,-0.310394,0.952214,1.040758,0.308039,-0.205304,0.544936,-0.091522,-0.258029,-0.229765,-0.958610,-0.512521,-0.454763,-0.409705,0.397908,0.115294,1.050479,-0.616463,-0.296166,-0.423742,-0.212581,0.390546,-0.537776,-0.384611,0.065335,-0.326763,0.428335,-0.547493,0.165536,0.166492,-0.489661,1.356914,-0.275775,0.407192,0.675700,-0.324153,-0.993335,0.948679,0.207522,0.376708,-0.126498,-0.131837,1.247626,0.128261,0.417662,-0.323903,-0.370175,-0.426040,-0.590339,0.018946,0.011660', '27602116', '26647163', '26678784', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293936', '杀手', '惊悚', '在监狱服刑的5年期间，乔尼·科雷（Sterling Hayden 饰）想出一条绝妙的抢劫计划。出狱后，他集结一帮非法之徒，共同策划抢劫赛马场的两百万美元巨资，并且做到“无一人伤亡”。然而智者千虑，必有一失。乔尼天衣无缝的计划得以顺利实施，却被同伙乔治（Elisha Co ok Jr. 饰）的老婆谢莉（Marie Windsor 饰）打乱。她得知丈夫的计划后，联合情夫沃尔（Vince Edwards 饰）向巨款伸出贪婪之手……本片根据里昂努·怀特（Lionel White）的小说《Clean Break》改编的，库布里克担任编剧，并请来著名小说家吉姆·汤普森修改了对白部分。©豆瓣', '斯特林·海登', '斯坦利·库布里克', 8.6, 28589, 'tt0049406', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2192213954.jpg', 0.2, 0.4, 8.5, 49.3, 41.5, '0.007112,-0.040276,-0.528270,0.506103,0.170953,-0.337988,0.336055,-0.076260,-0.228961,-0.206459,0.095944,0.202703,-0.164286,-0.154040,0.315783,-0.019185,-0.424820,-0.750550,-0.247212,-0.154045,0.039502,-0.584778,-0.365313,-0.383270,-0.019212,-0.347118,0.435599,0.211231,-0.006075,0.252501,0.370079,0.380996,-0.144027,-0.185660,0.163475,0.136896,0.382829,-0.339920,-0.370412,0.354699,-0.114417,-0.104639,-0.150287,-0.003336,0.081863,0.624709,0.744870,-0.235851,0.010575,0.039239,0.277971,-0.214302,0.068092,0.119416,0.299032,0.172337,0.027419,0.411432,-0.354073,0.014585,-0.046527,-0.332819,-0.972718,-0.238570,0.048559,-0.104785,-0.430483,0.006450,-0.383237,0.366228,-0.074651,-0.458621,-0.337226,0.566591,0.587743,0.071162,0.015775,0.215741,-0.440351,0.399063,0.323655,-0.309130,0.097525,0.162679,0.026346,-0.480873,0.001760,-0.111169,-0.176977,0.049992,0.528902,-0.197547,0.154050,0.096773,-0.414421,-0.261614,-0.580955,-0.124671,0.004792,-0.188904,0.035816,-0.873308,-0.007419,0.198577,-0.133772,0.059173,0.148125,-0.188336,0.390310,-0.431518,-0.001513,0.565863,-0.009266,-0.493686,0.222273,-0.012360,0.096627,-0.110835,-0.140613,0.105477,0.430255,0.130219,0.193048,0.275442,0.169240,-0.614569,-0.209141,0.239512', '2028645', '1307442', '27073234', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293941', '奇迹', '剧情', '青年郭振华（成龙 饰）赴港谋求发展，路见不平之下卷入两派黑帮争斗，却阴差阳错做了帮派大哥，郭振华反思此一段奇遇，发觉是街边卖花的玫瑰夫人（归亚蕾 饰）将好运带给了自己，自此谈判、出门前总要购买玫瑰夫人的玫瑰以求心安。郭振华将帮派所属丽池饭店改为夜总会经营，饭店前任老板之女杨露明（梅艳芳 饰）出于还债在夜总会表演结果大红大紫，郭杨二人更发展出了一段恋情。觊觎夜总会生意多时的福建帮频频向郭振华发难，郭一如既往向玫瑰夫人求运，意外发现玫瑰夫人正身陷更大的麻烦，原来她为使外地的女儿安心读书编造了自己堂皇的身份，而眼下终于面临戳穿，郭出于感激帮助玫瑰夫人圆谎，由此引发了连环笑料……本片根据Frank Capra的作品《一日贵妇》改编，大量香港明星在本片中客串演出。©豆瓣', '成龙', '成龙', 8.1, 38135, 'tt0098019', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2803999452.jpg', 0.3, 1.4, 20.3, 49.9, 28.1, '0.058770,0.282813,-0.241223,0.208073,0.277204,-0.407607,0.272571,0.276903,-0.478404,-0.265495,0.368057,0.262498,-0.353100,0.093530,0.309125,-0.093341,0.005650,-0.375977,0.110628,-0.031939,0.116285,-0.335308,-0.101957,-0.236201,-0.138815,0.093852,0.227613,0.321455,-0.235648,0.295128,0.403903,0.231157,-0.148682,0.375533,0.268467,0.230847,0.198533,0.153569,-0.539196,0.086332,0.129283,-0.725365,-0.057209,-0.113054,0.214129,0.163783,0.553545,0.044435,-0.124157,-0.218278,0.539077,-0.004313,0.201018,-0.120824,0.414671,0.019791,0.123377,-0.074802,-0.357612,-0.254317,0.018894,-0.169333,-0.436118,0.086478,0.449281,0.116969,-0.709244,-0.075391,-0.004181,0.076582,-0.084562,-0.452614,0.243277,0.307962,0.447593,-0.077458,-0.091045,0.161686,-0.477042,0.507959,0.633147,-0.018691,0.233945,-0.129646,-0.267374,0.014123,0.264821,-0.165758,-0.282168,-0.056898,0.217093,-0.356482,0.441228,0.025957,-0.378191,-0.252737,-0.273617,-0.016125,0.394588,-0.225346,0.194104,-0.697312,-0.127552,0.054414,0.136816,-0.363967,0.323878,-0.216500,0.689009,-0.605498,-0.033683,0.395949,0.374699,-0.615798,0.544443,-0.095267,0.272821,-0.213813,-0.099366,-0.118817,0.065201,0.127260,0.090020,0.155391,-0.085032,-0.329449,0.089015,-0.175625', '26646649', '1308035', '1316589', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293945', '爱与死', '喜剧', '鲍里斯（伍迪·艾伦 Woody Allen 饰）成长于一个人丁兴旺的俄罗斯大家庭里，在诸多的兄弟之中，要数他的身板和胆识最为渺小。在鲍里斯的眼中，表姐索嘉（黛安·基顿 Diane Keaton 饰）一直都是缪斯般的存在。可是，索嘉宁愿嫁一个渔夫，也不愿选择鲍里斯。令鲍里斯深受打击的事情远远不止这一件，战争开始了，为了效忠国家，鲍里斯被迫拿起长枪走上了战场。一次偶然中，鲍里斯成为了战斗英雄，荣归故里的他几经波折，居然赢得了此时已成为寡妇的索嘉的芳心，两人组成了人人羡慕的幸福家庭。好景不长，战火再次袭来，拿破仑攻占了莫斯科，鲍里斯必须重回战场。无法忍受离别之苦的索嘉决定一劳永逸——刺杀拿破仑。于是，一对傻头傻脑的夫妻带上他们的猎枪，就这样出发了……©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 8.5, 12248, 'tt0073312', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2179608694.jpg', 0.2, 0.8, 12.9, 46.9, 39.1, '0.129558,-0.070651,-0.667961,0.492302,-0.210774,-0.494500,0.657388,-0.026283,-0.568461,-0.029315,0.235885,0.928433,-0.182794,0.268753,0.347423,0.008730,-0.086105,-0.655033,-0.149514,-0.244102,-0.135057,-0.302732,-0.417434,-0.293246,-0.134941,-0.142050,0.851206,0.221934,-0.012861,0.523718,0.465877,0.268115,0.221204,0.438692,-0.330239,0.039005,-0.000609,0.044925,-0.399732,0.199655,-0.090581,-0.230219,-0.096086,0.441347,-0.165016,0.086922,0.514883,-0.490759,0.080513,-0.188044,0.307760,-0.307570,-0.122442,0.157991,0.183404,-0.123140,0.160432,0.171005,-0.200573,-0.024483,0.128249,-0.042727,-0.555273,0.080646,0.011837,-0.029348,-0.790000,0.429796,-0.011921,-0.127170,0.122789,-0.113273,0.194945,0.353937,0.137961,0.283827,-0.358720,-0.095946,-0.532554,0.165226,0.743903,-0.017282,-0.182980,0.079388,-0.075680,-0.304545,0.228804,-0.358055,-0.382551,-0.114995,0.444363,-0.063306,0.037025,0.493807,-0.579928,0.152307,-0.434801,-0.096874,0.030311,-0.397985,0.012913,-0.344282,-0.125299,-0.390086,-0.244797,0.337644,0.045041,-0.054952,0.671924,-0.651828,0.054255,0.295556,0.092428,-0.307510,0.483354,0.230744,0.380739,-0.184944,0.143911,0.303498,-0.159922,0.200364,0.182821,0.269731,0.018923,-0.137362,-0.275580,0.552147', '25721544', '30162520', '1308837', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293952', '绝岭雄风', '动作', '加贝（西尔维斯特·史泰龙 Sylvester Stallone 饰）是一名高山抢险队队员，对于他来说，不断的征服一座又一座看似高不可攀的山巅就是人生的全部意义所在。然而，在一次行动中，由于加贝的疏忽导致了朋友意外坠山而亡，心中充满了愧疚与悔恨的他决心就此放弃攀登。一次偶然中，加贝接收到了一个神秘的求救信号，信号的发出地位于雪岭之巅，和朋友哈尔（迈克尔·鲁克 Michael Rooker 饰）、杰西（简宁·特纳 Janine Turner 饰）一起，加贝决心到那里一探究竟。让加贝没有想到的是，在雪岭等待着他的，竟然是一帮穷凶极恶的劫匪和一群手无寸铁的人质。比环境更险恶的，是人心，这一次，加贝能否逢凶化吉呢？©豆瓣', '西尔维斯特·史泰龙', '雷尼·哈林', 7.6, 8265, 'tt0106582', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1417389367.jpg', 0.2, 2, 30.1, 51.5, 16.2, '0.329917,-0.232423,-1.002151,0.872093,-0.137961,-0.278270,0.958699,0.016319,-0.583517,0.044222,0.406989,0.728812,-0.011753,0.150094,0.219642,-0.007529,-0.126194,-0.612723,0.023653,-0.349454,-0.206153,-0.575500,-0.505383,0.023569,-0.031376,-0.318687,0.640817,0.255269,-0.147026,0.551820,0.411894,0.464280,0.086813,0.577188,-0.143278,-0.116485,0.188686,-0.136934,-0.243423,0.201388,-0.121252,-0.199993,-0.299774,0.453932,-0.088419,0.413609,0.623305,-0.459863,-0.183909,0.041785,0.081276,-0.261972,0.181298,0.114587,0.231000,-0.222956,0.021675,0.240650,-0.321748,0.128436,0.289908,0.026374,-0.748235,-0.101926,0.150894,0.422420,-0.798653,0.417928,-0.020096,-0.394436,0.109971,-0.420687,0.101643,0.189743,0.327105,0.310689,-0.261251,-0.384585,-0.425997,-0.304834,0.921933,0.049222,-0.100320,0.273430,-0.015384,-0.508822,0.013790,-0.073083,-0.499884,0.049900,0.320586,0.010341,-0.154945,0.199717,-0.592765,0.254776,-0.382725,-0.278858,-0.291431,-0.408999,-0.236674,-0.495993,0.134732,-0.337637,-0.192092,0.149202,0.018575,-0.153816,0.627741,-0.808040,0.120382,0.696145,0.067943,-0.217198,0.455487,0.146573,-0.026625,-0.012454,-0.051792,0.103561,0.054957,0.353389,-0.076351,0.376520,-0.000601,-0.133403,-0.300283,0.534343', '34461680', '1866424', '1301022', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293958', '为所应为', '剧情', '纽约布鲁克林黑人社区生活着各个族群的人：黑人、意大利移民、韩国人.....意大利移民Sal（丹尼·爱罗 Danny Aiello 饰）和他的两个儿子在这里经营一家比萨店很久了，Mookie（斯派克·李 Spike Lee 饰）在店里负责送外卖，经常和Sal的儿子闹矛盾。 Radio Raheem（Bill Nunn 饰）是一个喜欢提着一个收音机大声放着音乐到处走的年轻人。炎热的一天，黑人小伙Buggin'' Out（吉安卡罗·埃斯波西托 Giancarlo Esposito 饰）发现比萨店墙上挂着的名人照片里没有一个黑人，十分不满；而Radio来到比萨店，却被Sal要求关掉收音机。心怀不满的Buggin'' Out和Radio决定找Sal讨个说法，三人在争执中，Sal把Radio的收音机砸烂了。Radio大怒，便和Sal打了起来。警察赶来了，围观的人也越来越多，一场种族间的暴乱即将到来......本片被提名62届奥斯卡最佳男配角、最佳改编剧本，本片的成功使黑人导演斯派克李在好莱坞大放异彩。', '丹尼·爱罗', '斯派克·李', 8.2, 13519, 'tt0097216', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2500861627.jpg', 0.5, 1.9, 16.1, 50.9, 30.6, '0.383702,-0.034702,-0.506887,0.541325,-0.090931,-0.317440,0.805259,0.301912,-0.434823,-0.047941,-0.034537,1.007703,-0.322091,0.240777,0.409241,-0.055229,-0.417215,-0.494598,-0.137720,-0.150625,-0.233636,-0.390733,-0.196156,-0.336832,-0.256088,-0.083930,0.243498,-0.136885,-0.063340,0.522276,0.456590,-0.058293,-0.060036,0.405619,-0.232109,0.101859,0.332545,-0.263707,-0.198341,0.362203,-0.048560,-0.257952,-0.256813,-0.021909,0.134126,0.251902,0.495779,0.045288,0.022034,-0.024662,0.335264,-0.172284,-0.241678,-0.045789,0.496376,-0.009374,0.274875,-0.088571,-0.229583,-0.003971,0.128400,-0.099301,-0.425280,0.322498,0.062884,0.220412,-0.763968,0.519545,-0.221852,0.050772,-0.031885,-0.340655,0.399170,0.126892,0.147878,0.400726,0.163787,-0.050897,-0.645951,0.276798,0.425112,-0.079194,-0.093727,-0.006207,-0.186777,-0.334097,0.023985,0.122419,-0.732783,-0.214911,0.579114,-0.459742,0.035351,-0.350967,-0.635858,0.183311,0.079793,-0.554453,0.106415,-0.166754,-0.200379,-0.890286,0.006866,-0.201558,-0.101725,0.054280,0.052278,0.181066,0.791825,-0.581653,0.049378,0.460193,0.357650,-0.163262,0.774031,-0.082682,0.208480,-0.209703,-0.257679,-0.154835,0.167101,0.115726,