INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293963', '午后之爱', '剧情', '本片是埃里克·侯麦《六个道德故事》的最后一部。弗雷德里克（贝尔纳·维尔莱 Bernard Verley饰）在经过了前五集的犹豫之后，终于跨进了婚姻的城门。此时的弗雷德里克已与妻子海伦娜（弗朗索瓦丝·韦尔莱 Françoise Verley饰）过着幸福的小资生活。弗雷德里克在法国巴黎一家小公司上班，海伦娜则是一名工作稳定的教师。海伦娜一直期待着他们第二个孩子的出生，而弗雷德里克却不安于现状。每到下午时分，就是他幻想和其他女性缠绵的时刻，即使他并没有付诸于行动。一日，他的旧情人克洛伊（祖祖 Zouzou饰）出现了。两人以老朋友身份见面聊天，然而面对克洛伊的诱惑，弗雷德里克动心了。由国际电影大师埃里克·侯麦执导的影片《午后之爱》，是侯麦《六个道德故事》的最后一部。《六个道德故事》是侯麦的成名作，包括《蒙索街的面包店女孩》、《苏姗的爱情经历》、《莫德家的一夜》、《收集男人的女人》、《克莱尔的膝盖》和《午后的爱情》，此系列作品奠定了他在世界影坛的地位。', '贝尔纳·维尔莱', '埃里克·侯麦', 8.4, 17296, 'tt0068205', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1623990115.jpg', 0.3, 0.8, 12.1, 53.3, 33.5, '0.269966,0.015547,-0.819540,0.618833,0.057874,-0.393154,0.875089,0.328978,-0.458357,-0.382047,0.308481,0.657691,-0.175328,0.450582,0.464145,0.026620,-0.431579,-0.634996,-0.009424,-0.127261,-0.045803,-0.361386,-0.203587,-0.122723,-0.197448,-0.345858,0.604437,0.081280,-0.149700,0.291219,0.456213,0.030296,-0.019233,0.389378,-0.101151,0.105149,0.302304,-0.003792,-0.441414,0.116127,0.094022,-0.099716,-0.265721,-0.016878,-0.049985,0.343879,0.522762,-0.200758,-0.045944,0.027945,0.290638,-0.132986,-0.047562,0.052145,0.299355,-0.085050,0.331777,0.387566,0.021531,-0.001284,-0.007953,-0.147350,-0.733467,0.063708,0.055427,0.250539,-0.549062,0.686885,-0.292418,-0.094708,-0.053511,-0.289464,0.124637,0.185847,0.267977,0.400043,-0.045240,-0.063832,-0.531844,0.335830,0.433545,0.033269,-0.379945,0.656414,-0.222576,-0.370227,-0.299453,-0.153102,-0.612592,0.025264,0.220675,-0.025556,-0.111219,0.256515,-0.622552,0.066505,-0.065380,-0.219889,0.159174,-0.439359,0.018131,-0.770886,-0.031202,-0.406511,-0.415961,-0.031122,0.129755,-0.164092,0.817696,-0.699007,0.205733,0.434235,0.304089,-0.272246,0.998254,0.164589,0.136720,-0.227103,0.080722,0.623876,-0.319228,-0.044278,-0.001828,0.393031,0.045644,0.008369,-0.388354,0.711222', '3055049', '3927750', '1292211', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293964', '魂断蓝桥', '剧情', '第一次世界大战期间，回国度假的陆军中尉罗伊（罗伯特·泰勒）在滑铁卢桥上邂逅了舞蹈演员玛拉（费雯·丽），两人彼此倾心，爱情迅速升温。就在两人决定结婚之时，罗伊应招回营地，两人被迫分离。由于错过剧团演出，玛拉被开除，只能和好友相依为命。不久玛拉得知罗伊阵亡的消息，几欲崩溃，备受打击。失去爱情的玛拉感到一切都失去了意义，为了生存，她和好友不得不沦为妓女。然而命运弄人，就在此时玛拉竟然再次遇到了罗伊。虽然为罗伊的生还兴奋不已，玛拉却因自己的失身陷入痛苦之中。感到一切难以挽回的玛拉潸然离开，独自来到两人最初相遇的地点——滑铁卢桥上…©豆瓣', '费雯·丽', '茂文·勒鲁瓦', 8.8, 259366, 'tt0033238', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2351134499.jpg', 0.1, 0.5, 8.6, 39.9, 50.9, '0.367474,0.137200,-0.848577,0.219433,0.043542,-0.711218,0.689194,0.058137,-0.477518,-0.205153,0.315398,0.791449,-0.534745,0.272671,0.616131,-0.160821,-0.509842,-0.853178,0.173382,-0.154921,-0.116642,-0.503689,0.107169,-0.008879,-0.159319,-0.362741,0.865733,0.087778,-0.101417,0.672709,0.199371,0.442615,-0.227387,0.551120,0.125873,0.367454,0.061985,-0.032185,-0.606192,0.107343,0.003428,-0.308377,-0.099391,0.185223,0.020933,0.167943,0.770992,-0.320059,-0.144163,-0.106228,0.342816,-0.499683,-0.070641,0.214242,0.160337,-0.076315,0.254931,0.084793,-0.408512,-0.084426,0.155135,0.189070,-0.348107,0.262064,0.165798,0.176768,-0.436983,0.488852,-0.051538,0.008454,0.083106,-0.536168,0.020683,0.493381,0.477445,0.493837,-0.436089,-0.112723,-0.361764,-0.042569,1.229106,-0.079249,-0.353192,0.224721,-0.032856,-0.420561,0.023795,0.030638,-0.384480,0.102063,0.384171,0.389726,-0.103064,0.607129,-0.483009,-0.183757,-0.642621,-0.365426,0.027442,-0.359746,-0.024333,-0.794930,-0.186762,-0.080156,-0.543402,0.157151,-0.129569,-0.231170,0.277288,-0.793055,0.477759,0.352969,0.410402,-0.118204,0.334298,0.080781,0.293546,-0.173064,0.214038,0.817710,-0.198103,0.184078,0.188832,-0.148935,-0.332763,0.346271,-0.501778,0.570526', '35287558', '26687241', '25721544', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293973', '爱德华大夫', '爱情', '精神病院的默奇逊院长即将退休，接手的是年轻有为的爱德华大夫（格利高里·派克 Gregory Peck 饰）。医院里年轻漂亮的女医生彼特森（英格丽·褒曼 Ingrid Bergman 饰）和他相爱，然而竟发现眼前的爱人不是爱德华大夫，而真实的爱德华的秘书，还前来指出这个冒牌人士是杀害爱德华的凶手。面对恋人扑朔迷离的身份，彼特森始终不相信他是杀人凶手，然而默奇逊院长却用精神分析法印证了“事实”。更为棘手的是，这个假爱德华也相信自己有罪，他甚至连自己是谁，经历过的事情也不知道。彼特森对自己的判断非常坚持，她决定要帮他找出事件真相。在警察的追捕下，她带他逃到了心理分析教授的家中，展开了一联串精彩的心理分析过程，他童年的阴影和爱德华大夫被杀的真相渐渐浮出水面。©豆瓣', '英格丽·褒曼', '阿尔弗雷德·希区柯克', 8.3, 57055, 'tt0038109', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1884306259.jpg', 0.2, 0.8, 14.8, 52.2, 32, '0.305527,-0.081466,-0.468597,0.402720,-0.358706,-0.219335,0.756646,-0.175075,-0.583168,-0.437708,0.290701,0.711914,-0.096891,0.246770,0.051016,0.449873,-0.378979,-0.563200,0.144482,0.022806,-0.260200,-0.701228,-0.316464,-0.429303,0.086497,-0.098023,0.436676,0.122306,-0.187329,0.261060,0.274018,0.367166,0.253673,0.533511,-0.118866,0.203216,0.106735,-0.148209,-0.187335,0.033332,0.566739,-0.300540,-0.229546,0.594145,-0.233419,0.710852,0.330928,-0.040379,-0.262735,0.210300,0.332017,-0.770038,-0.005520,0.287829,0.199570,-0.101645,-0.099681,0.480817,-0.024250,-0.170997,-0.166773,0.193520,-0.813998,0.029207,0.260584,0.449189,-0.564644,-0.004338,-0.482625,-0.111259,0.069293,-0.223111,0.216297,0.077677,0.046041,0.204463,-0.118885,-0.375963,-0.736114,0.132863,0.546023,0.044119,-0.250399,0.364516,-0.505066,-0.536520,0.027565,-0.280402,-0.320505,0.159924,0.011035,-0.090653,-0.344408,0.158007,-0.082063,-0.291053,-0.542915,-0.045500,-0.300557,-0.432464,-0.093649,-0.269339,-0.347294,-0.507205,-0.505242,-0.297709,-0.147404,-0.431873,0.513728,-0.762435,-0.040776,0.524360,0.245780,-0.409151,0.702320,0.197500,-0.203395,-0.342731,-0.072084,0.129990,0.207105,0.174857,0.073312,0.289278,0.408365,-0.228109,-0.410594,0.448979', '25862560', '1295318', '1299362', '1308762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293976', '杀人三步曲', '动作', '吉他手埃尔（安东尼奥•班德拉斯 Antonio Banderas 饰）靠在夜总会表演为生。一天，他的女友遭到了当地的一个大毒枭的枪杀，而埃尔的左手也遭到枪击，从此不能再弹吉他了。于是，埃尔的吉他盒子里放的不再是吉他，而是武器装备。他带着他的吉他盒子穿过一个又一个街头，为的是为女友报仇雪恨。大毒枭得知埃尔正在寻仇，于是派出手下前来暗杀他。危难关头，埃尔幸得美女卡罗琳娜（萨尔玛•海耶克 Salma Hayek 饰）相救。大难不死，更加坚定了埃尔报仇的决心。©豆瓣', '安东尼奥·班德拉斯', '罗伯特·罗德里格兹', 7.5, 19756, 'tt0112851', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p781912065.jpg', 0.7, 4, 33.8, 44.6, 16.9, '0.123630,-0.020322,-0.471746,0.581024,-0.295522,-0.251620,0.997878,0.315165,-0.107205,0.022091,0.445219,1.018315,0.137181,0.096278,0.331195,0.250188,-0.360774,-0.740829,0.121271,0.246726,-0.195802,-0.302531,-0.211941,-0.396765,-0.068253,-0.174073,-0.068484,-0.051800,-0.003786,0.536419,0.476486,0.184376,-0.012394,0.382574,-0.096261,-0.169533,0.243335,-0.523480,0.058565,0.414318,0.032562,-0.337330,-0.136192,0.336896,-0.318570,0.236358,0.844486,0.116720,0.520484,-0.300983,0.319761,-0.159434,0.036383,-0.404504,0.242903,0.142646,0.115330,-0.002722,-0.151605,-0.032021,0.367843,-0.214439,-0.566556,0.118730,-0.093481,0.024954,-0.605829,0.421259,-0.208773,0.257412,0.165483,-0.308748,0.000314,0.037529,0.079885,-0.138598,-0.236649,-0.065510,-0.725078,-0.012028,0.250653,-0.194704,0.542181,0.020000,0.081445,-0.529994,0.244753,-0.334557,-0.496440,-0.134140,0.693014,-0.519012,-0.093098,0.081700,-0.558958,-0.322656,-0.736685,-0.099616,0.175243,-0.211121,0.029530,-0.626099,0.297117,0.119260,-0.060355,0.218805,0.212389,-0.077911,0.677864,-0.601743,0.415228,0.762273,-0.187167,-0.189431,0.457680,0.144971,0.198228,0.080310,-0.100673,0.218913,-0.060467,0.362279,0.148986,0.174518,0.210415,-0.311920,-0.128362,0.340605', '1301686', '1309194', '21619567', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293980', '杀手之吻', '剧情', '拳击手大卫•科登（Jamie Smith 饰）独自住在一间简陋的公寓出租房内，窗户对面住着一个美丽的舞女格萝蕾拉（Irene Kane 饰），大卫渐渐为之所吸引。某晚大卫比赛归来，突然发现格萝蕾拉正要被人强暴，他冲进去拯救了心上人。原来强暴者是格萝蕾拉所在夜总会的老板（Frank Silvera 饰），为了生计不得不忍辱负重。两个失意之人情谊相合，遂约定离开伤心地，寻找他们的幸福。大卫外出筹集旅费，而夜总会老板在得知格萝蕾拉即将离开的消息时勃然大怒，派出打手绑架了她……本片荣获1959年洛迦诺国际电影节最佳导演奖。©豆瓣', '杰米·史密斯', '斯坦利·库布里克', 7.4, 15073, 'tt0048254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2454829754.jpg', 0.3, 2.6, 41.3, 40.7, 15.1, '0.036680,0.051227,-0.563931,0.132259,-0.088892,-0.302429,0.654728,0.320020,-0.164760,-0.295577,0.404173,0.755263,-0.271081,0.433201,0.616719,0.326943,-0.237268,-0.583929,-0.179171,-0.198033,-0.206398,-0.124242,-0.124923,-0.233011,0.019687,-0.148170,0.523019,-0.123758,-0.025457,0.743777,0.474093,0.292118,-0.525239,0.356060,-0.181980,-0.054048,0.327598,-0.139546,-0.493331,0.361901,-0.352001,-0.403704,-0.311394,-0.114237,-0.029387,0.256469,0.578416,-0.205528,0.049996,-0.016894,0.218034,-0.286990,-0.086682,-0.067022,0.047944,-0.199994,0.299791,0.110841,-0.386602,0.055006,0.220268,-0.349038,-0.381902,0.251983,0.266245,-0.108624,-0.418938,0.270119,-0.146539,0.088747,0.142019,-0.310059,0.170422,0.264540,0.027507,0.409208,-0.000742,0.189794,-0.383289,0.037818,0.648072,-0.490524,0.397346,0.295030,0.099683,-0.239222,0.389129,-0.135739,-0.534108,-0.002305,0.527253,0.101467,0.129148,-0.318197,-0.497300,-0.226739,-0.347504,0.078938,0.229736,-0.368919,-0.093051,-0.699282,-0.077586,0.235920,0.073187,0.191836,-0.074678,0.057730,0.274718,-0.472744,0.285945,0.539395,0.337530,-0.492259,0.701220,-0.277588,0.278471,-0.000420,-0.071119,0.269316,0.188812,0.654439,-0.046818,0.183702,-0.431575,-0.219014,-0.445589,0.182846', '1309194', '1303333', '3147969', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293981', '心灵点滴', '剧情', '亚当（罗宾•威廉斯 饰）想成为一名医生是在他的精神疾病痊愈之后，后来他进入了维吉尼亚医学院学习。可是院内的传统观念的限制使医生们开来都十分不近人情。他不屑于这种状态，于是他把欢笑看做是医治病人的一个重要处方。他总是穿着鲜艳的衣服，带着滑稽的装扮到学院去，为的就是能让每一位病人都开怀大笑。校方对亚当的行为十分不满，但他还是冒着被勒令退学的危险坚持着自己那套理念。亚当需要克服的东西众多，从医路上又将有不同的挑战与不同的人与事在等着他，亚当仍不懈的为着梦想前行。©豆瓣', '罗宾·威廉姆斯', '汤姆·沙迪亚克', 8.4, 11880, 'tt0129290', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p735865077.jpg', 0.4, 1.5, 15.1, 43, 39.9, '0.288450,0.005437,-0.504818,0.714522,-0.389782,-0.291849,0.904901,0.132205,-0.522080,-0.307658,0.337419,0.667165,0.055444,0.432044,-0.007459,0.111791,-0.285315,-0.611151,-0.153749,-0.071227,-0.618242,-0.384866,-0.123059,-0.187475,-0.259357,-0.519695,0.434179,0.012898,-0.486164,0.279287,0.252492,0.348867,0.288333,0.770458,-0.425459,-0.251375,-0.043241,-0.059700,0.023597,0.124601,0.434145,-0.251627,-0.478828,0.476356,0.007542,0.476740,0.697974,-0.230483,-0.256280,0.105376,0.377339,-0.306859,0.125002,0.404509,0.153916,0.232049,0.022331,0.211539,-0.149922,0.303009,0.117668,0.085614,-0.979066,-0.110343,0.135111,0.366329,-1.050228,0.681518,-0.138446,-0.280256,0.144343,-0.529937,0.016246,0.199090,-0.089883,0.577099,-0.198889,-0.006650,-0.905683,0.202106,0.657877,0.174229,-0.407305,0.296935,-0.621335,-0.491426,0.033891,-0.312218,-0.559463,-0.314475,0.181401,-0.059083,-0.206695,-0.011414,-0.451907,0.097570,-0.109456,-0.490896,-0.268978,-0.376359,0.061953,-0.465277,0.194956,-0.526051,-0.559781,0.058316,0.132463,-0.363628,0.925510,-0.936718,0.148559,0.671942,0.239472,-0.717518,0.778857,0.316312,0.215526,-0.087583,-0.468688,0.070715,0.009439,0.545806,0.317966,0.816816,0.175317,-0.031132,-0.537131,0.632366', '1877596', '1793491', '1303112', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293985', '摇尾狗', '剧情', '美国华盛顿特区，新一轮总统大选前两周。一桩耸人听闻的总统骚扰未成年少女的性丑闻事件，就在这切要关头被披露曝光，闹得沸沸扬扬。加上新闻媒体的大肆炒作，总统谋求连任的机会简直微乎其微。为了平息这场风波，总统紧急召见了老谋深算的政治顾问康拉德·布里恩博士（罗伯特·德尼罗 Robert De Niro 饰）。善于操纵公众舆论导向的布里恩，在紧要关头很快献出一条“妙计”。为了转移公众对性骚扰事件的注意力，布里恩凭空捏造出一场子虚乌有的爱国战争“阿尔巴尼亚战争”。为了让这场虚构出来的战争真实可信，布里恩专程拜访了大名鼎鼎的好莱坞著名制片人斯坦利·莫斯（达斯汀·霍夫曼 Dustin Hoffman 饰）。在他们“天衣无缝”的导演之下，公众果然信以为真，倍加关注。然而，这场所谓的爱国战争不久便破绽百出，不攻自破。本片改编自Larry Beinhart的小说《American Hero》。影片赢得1998年第48届柏林国际电影节银熊奖，并荣获奥斯卡奖-最佳改编剧本在内的7次提名。达斯汀·霍夫曼更凭借此片荣获1998年第70届奥斯卡奖-最佳男主角提名。', '达斯汀·霍夫曼', '巴瑞·莱文森', 8.1, 8300, 'tt0120885', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p828362267.jpg', 0.4, 1.6, 17.8, 52.8, 27.4, '-0.033096,0.011986,-0.724074,0.555787,0.266792,0.029791,0.091136,-0.088862,-0.428556,-0.138026,0.290964,0.788715,-0.786203,-0.327588,0.686011,-0.287497,-0.525111,-0.604174,-0.161334,-0.054608,0.284595,-0.416440,-0.441881,-0.026216,-0.225839,-0.368781,0.647141,0.156598,-0.489205,0.262193,0.758669,0.248229,0.240771,0.005885,0.443064,-0.112554,0.224483,-0.005906,-0.581586,0.584177,0.117869,-0.369318,-0.309254,0.184968,0.128838,0.180537,0.286124,-0.411564,0.033209,0.135276,0.908360,-0.682078,-0.082689,-0.041696,0.497681,-0.069782,0.262092,0.533139,-0.153424,-0.000201,-0.001771,-0.187573,-0.651432,0.021635,0.013685,0.287792,-0.029629,0.441621,-0.193564,0.308571,-0.114608,0.046966,0.018492,0.562671,0.388755,-0.266286,0.060661,0.125973,-0.160945,0.575033,0.437153,-0.111529,-0.445587,0.105205,0.130549,-0.301067,0.212471,-0.655945,-0.339562,0.267806,0.462898,-0.280297,0.028359,0.601171,-0.259940,-0.255413,-0.517774,-0.368805,0.164349,-0.125187,0.113643,-0.933447,-0.318955,0.013683,0.162506,-0.216686,0.125227,-0.377913,0.540257,-0.329199,0.143191,0.694002,-0.289627,-0.269284,0.465015,0.255223,0.223294,-0.315567,-0.325211,0.101859,-0.002094,0.442702,-0.256213,0.127194,0.173520,-0.728622,0.036835,0.046564', '1292759', '3077791', '26990609', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293989', '十二怒汉', '剧情', '根据1957年同名黑白电影改编而成的电影。名气不大，口碑也不如旧版。在1957年由悉尼．卢曼特执导的《十二怒汉》是探讨美国陪审员制度和法律正义的经典作，本片则是由威廉．弗里德金重新拍摄的电视版，由杰克．莱蒙取代亨利．方达演男主角，其他合演者包括金像奖影帝乔治．C．斯科 特。该片描述一名纽约青年被控杀父，将被判处一级谋杀的死刑。已经有十一名陪审员裁定疑犯有罪，只有一位觉得事态可疑，坚持已见提出异议，并且凭耐心与毅力逐一说服其他陪审员推翻原意，终于为这一宗几乎已成冤案的判决平反。全片大部分时间处于狭窄的房间内进行，但凭精彩的对白和演出，仍能创造出紧扣观众的剧力。', '考特尼·万斯', '威廉·弗莱德金', 9.2, 24718, 'tt0118528', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2337734157.jpg', 0.1, 0.3, 4.6, 27.5, 67.5, '0.058824,0.062941,-0.376524,0.626094,0.289008,-0.139806,0.579506,0.145447,-0.237151,-0.351920,0.217256,0.583323,-0.223715,0.087316,0.291066,-0.402620,-0.479048,-0.790024,-0.313577,-0.117574,-0.041413,-0.759516,-0.258371,-0.083243,-0.199285,-0.431243,0.812370,-0.088581,-0.179997,0.149812,0.627752,0.173345,-0.051317,-0.153566,0.125581,-0.264567,0.284850,-0.059104,-0.477002,0.313507,-0.083664,-0.224981,-0.165560,-0.188330,0.027815,0.532138,0.478885,-0.237278,-0.209471,0.098641,0.687049,-0.335353,-0.092401,0.130149,0.197982,0.098963,0.170919,0.365884,-0.103550,0.151212,-0.189953,-0.282802,-1.169795,-0.081505,0.227768,0.300978,-0.269137,0.346564,-0.142773,-0.099692,-0.203590,-0.061182,-0.002526,0.168523,0.480017,0.376677,0.046954,-0.054819,-0.418312,0.254237,0.498370,0.066294,-0.454677,0.112689,-0.098583,-0.576848,-0.193947,-0.481414,-0.112952,0.100931,0.101714,-0.017118,0.182735,0.068668,-0.315869,-0.209203,-0.096312,-0.308199,-0.030826,-0.285881,0.302795,-0.748789,-0.263716,-0.157815,-0.070046,-0.172135,0.211628,-0.472654,0.811223,-0.422089,0.048026,0.136773,0.211751,-0.555357,0.788150,0.308212,0.076972,-0.078047,-0.111213,0.011897,0.234176,0.091244,0.207459,0.301567,0.134833,-0.424446,-0.343085,0.194904', '27602116', '3318306', '27073234', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293993', '小公主', '剧情', '富有的克鲁上校和她的女儿萨拉（利塞尔•马修斯 Liesel Matthews 饰）在印度度过了一段幸福美好的时光。直到战争爆发，因为萨拉的母亲在她出生的时候就去世了，上战场前，克鲁上校不得不把萨拉送到了纽约著名的米切恩女子学校，将女儿委托给了米切恩夫人代为照顾，并留下了一笔不菲的报酬，以便自己走后女儿生活无忧。米切恩夫人看在这笔丰厚酬劳的面子上，给萨拉安排了最大最好的房间，即使是在违背校规的情况下也默许萨拉带着母亲留给她的项链。天真活泼的萨拉总是有一些奇思妙想的小故事，让她很快和其他孩子融洽的相处起来。在大家的簇拥下，萨拉俨然过着小公主一般的生活。但天有不测风云，就在她生日那天，前线却突然传来了她父亲阵亡的消息，萨拉成了孤儿，米切恩夫人开始暴露出她贪婪势利的本性，萨拉的生活轨迹开始发生变化…本片改编自弗朗西斯•霍奇森•伯内特同名小说《小公主》。©豆瓣', '利塞尔·马修斯', '阿方索·卡隆', 8.5, 31676, 'tt0113670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1237895913.jpg', 0.2, 1, 14, 42.5, 42.4, '0.135974,0.183689,-0.711071,0.764630,-0.243880,-0.556863,0.748592,0.281107,-0.530182,0.070086,0.307565,0.775680,0.058782,0.201806,0.457906,0.206452,-0.657420,-0.442332,-0.124790,-0.277446,-0.300055,-0.570615,-0.032492,-0.138558,-0.081608,-0.462177,0.246375,-0.300730,0.127683,0.308729,0.158806,0.125682,0.130769,0.304401,-0.348611,0.240275,-0.031036,-0.125751,-0.265470,0.217757,0.319324,-0.029015,-0.188624,-0.007766,0.341305,0.257194,0.686712,-0.398242,-0.117884,0.059724,0.406633,-0.186469,0.185395,0.088480,0.196086,-0.010464,0.264375,0.093760,-0.389747,-0.067233,0.017036,-0.143387,-0.377492,0.084500,-0.010479,0.084726,-0.737771,0.657132,-0.188255,-0.169185,0.275794,-0.612869,0.091115,0.462825,0.003818,0.167277,-0.320189,0.062723,-0.463191,0.195174,0.475160,0.033994,-0.143715,0.200290,-0.373667,-0.504315,0.037710,-0.171294,-0.648201,0.032016,0.475890,-0.166762,-0.188977,0.599098,-0.497934,-0.124919,-0.362146,-0.399722,0.155221,-0.555701,-0.112240,-0.347972,-0.275826,-0.261997,-0.384417,0.006479,0.216585,-0.128140,0.852781,-0.638483,0.515494,0.504923,0.267478,-0.169026,0.516615,0.080526,0.289260,0.004322,-0.027794,0.188653,0.147075,0.376345,0.271088,0.405181,0.095360,-0.128372,-0.357891,0.736224', '1298468', '26348103', '2