INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1293995', '凶暴的男人', '剧情', '作风粗暴的警官我妻谅介（北野武 饰）在警匪两界颇具名望，也因此结下不少仇家。在某次追查毒品贩子遇害事件时，顺藤摸瓜查到青年实业家仁藤（岸部一德 饰）为幕后指使。同时发现，其警局好友岩城（平泉城 饰）亦在毒品犯罪中占据重要位置。然调查才刚展开，岩城即被仁藤麾下杀手（白龙 饰）杀害，并伪装成自杀现场。杀手清弘为诱我妻上钩，绑架了我妻的智障妹妹（川上麻衣子 饰）加以轮暴，并使其沉溺毒品无法自拔。我妻辞去警局职务，持枪向仁藤和清弘展开报复……本片为日本喜剧明星北野武的导演处女作。©豆瓣', '北野武', '北野武', 7.9, 11422, 'tt0098360', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p939015718.jpg', 0.2, 1.6, 24, 53.2, 20.9, '0.104881,-0.044547,-0.305582,0.150610,0.006951,-0.047947,0.402130,0.239301,-0.365495,-0.222014,0.220686,0.492784,0.063297,-0.087807,0.291777,-0.064095,-0.180370,-0.607240,-0.121390,-0.179750,-0.058595,-0.341332,-0.149697,-0.024223,-0.164338,-0.123553,0.498346,0.165796,-0.266657,0.265541,0.538497,0.595128,-0.490369,0.094831,0.324063,-0.067849,0.163139,-0.245650,-0.422215,0.157451,-0.446316,-0.586920,0.058493,0.070010,-0.157196,0.423134,0.623604,-0.043734,-0.213853,-0.495070,0.453111,-0.404879,0.004648,-0.099482,0.556848,0.117579,0.151594,0.597522,-0.364169,0.017439,0.158362,0.179042,-0.607318,-0.092201,0.413747,0.130944,-0.100288,-0.067233,-0.143272,0.069129,-0.044265,-0.108841,0.209267,0.124063,0.245856,-0.290039,0.047995,0.050447,-0.281261,0.446693,0.374219,-0.113507,0.259367,-0.103666,0.305479,-0.444138,0.154753,-0.222812,-0.013443,0.048451,0.348714,-0.160245,0.032204,0.012826,-0.203650,-0.492651,-0.266606,0.341303,-0.075941,-0.131867,0.047098,-0.626457,-0.275091,0.096459,0.151144,-0.042736,0.329947,-0.200578,0.222692,-0.511247,0.044612,0.734590,0.106121,-0.619794,0.208391,0.104096,-0.027465,-0.326563,-0.460035,0.127083,0.537975,0.100735,-0.146476,-0.098443,-0.060063,-0.337746,-0.083534,-0.415048', '25723905', '25921830', '27126336', '3428500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294000', '我的左脚', '剧情', '本片改编自已故爱尔兰天才作家兼画家克里斯蒂•布朗的自传体小说。基提（丹尼尔•戴-刘易斯 Daniel Day-Lewis 饰）天生大脑麻痹身体残疾，只有左脚能灵活如常人。他没有生活自理能力，为家里带来了很大的负担，幼时总是遭到周围孩子的嘲弄，父亲险些放弃他，而母亲（布兰达•弗里克 Brenda Fricker 饰）却一直对他悉心照顾，不离不弃。基提心理苦闷却不能用语言来表达，试图用左脚写字作画，渐渐地凭借毅力和智慧，基提越来越得到认可。母亲悄悄地为基提买了轮椅，之后他又得到了艾莲医生的免费救助。在艾莲的锻炼引导下，基提的身体开始有了好转。此时基提已经爱上了艾莲。某日艾莲将基提的画推荐到了朋友的画廊展出。结束后基提向艾莲表达爱意，却被她拒绝......©豆瓣', '丹尼尔·戴-刘易斯', '吉姆·谢里丹', 8.3, 14613, 'tt0097937', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2502636053.jpg', 0.2, 0.8, 14.4, 51.3, 33.4, '0.052670,0.176159,-0.508319,0.445703,-0.200618,-0.392790,0.655010,0.238914,-0.486557,-0.174573,0.064621,0.598001,-0.086142,0.176170,0.012359,-0.136512,-0.234559,-0.622895,0.240173,0.173407,-0.330151,-0.424989,-0.278400,-0.204627,-0.369289,-0.521106,0.400921,-0.190486,-0.189655,0.289193,-0.022169,0.246446,0.531671,0.317983,-0.277189,0.214339,-0.290210,-0.283018,-0.049554,0.119995,0.378455,-0.284430,-0.265564,0.361368,0.004715,0.363012,0.746353,-0.027794,-0.094232,-0.133295,0.387888,-0.144610,0.203284,-0.053434,-0.102669,0.229573,0.167851,0.129476,-0.205980,-0.114042,0.064183,-0.101785,-0.590782,0.002661,0.087880,0.156042,-0.848434,0.255246,-0.244402,0.048628,0.079819,-0.306616,-0.184596,0.113128,0.003966,0.386006,-0.274821,0.111486,-0.182284,0.182042,0.343944,-0.050238,-0.241443,0.585525,-0.617535,-0.236502,0.212781,-0.211638,-0.309379,-0.247499,0.012817,0.333250,-0.145224,0.074054,-0.204308,-0.107755,-0.157511,-0.056849,-0.056267,-0.654072,0.113772,-0.511295,-0.265794,-0.309024,-0.061537,-0.136210,0.089427,-0.357069,0.826391,-0.757957,0.375821,0.600489,0.405356,-0.241969,0.696784,0.064423,-0.106833,-0.087506,0.023786,0.488340,-0.081974,0.027763,0.206425,0.210699,0.150636,0.087511,-0.408907,0.660009', '4058933', '1308609', '1316698', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294007', '我的父亲母亲', '剧情', '一个男子（孙红雷饰）得知父亲去世的消息后回到家乡，年迈的母亲说起和父亲的往事。30多年前，城市青年骆长余（郑昊饰）从师范学校毕业后自愿来到了三合屯当小学教师，方圆十几里出了名的美人招娣（章子怡饰）暗自喜欢上了他，从此少女的心便不再安宁。由于学校还未盖好，村里人给建学校的人送“公饭”，招娣换着样儿做好饭菜，特意用一个青瓷碗盛好送去，满心希望教师能吃上她做的饭菜。后来骆长余终于知道了青瓷碗，明白了姑娘的心事，二人由此迸出了爱情的火花。学校建好了，听到教室里的念书声，招娣觉得那是有生以来最好听的声音。到后来，村里已经没有人再听了，只有招娣还听，一听就是四十多年……©豆瓣', '章子怡', '张艺谋', 8.2, 130767, 'tt0235060', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p871456694.jpg', 0.2, 1.2, 18.3, 48.9, 31.3, '0.321225,0.058574,-0.505740,0.436772,-0.104082,-0.570965,0.561657,0.237829,-0.793236,-0.140873,-0.241556,0.715287,-0.133469,0.517660,0.219643,0.042439,-0.364117,-0.573335,-0.088975,-0.455836,-0.267019,-0.200318,0.353521,-0.123731,0.042840,-0.154738,-0.014612,-0.019298,0.138141,0.274198,0.033533,-0.162208,0.168887,0.332837,-0.293128,0.325813,-0.256109,0.121347,-0.256592,0.163548,0.226033,-0.222572,-0.377055,-0.068111,0.257411,0.272509,0.408840,0.235047,-0.246252,-0.068795,0.302178,0.098148,-0.066438,0.032994,0.110784,-0.004393,0.482269,0.109345,-0.359660,0.025021,0.112153,-0.106943,-0.154520,0.104400,-0.063516,-0.088396,-0.797560,0.387385,-0.108108,0.007437,0.321558,-0.351819,0.295649,0.000748,-0.017968,0.791570,-0.069997,0.102908,-0.503086,0.494089,0.611801,-0.275077,0.261695,0.292393,0.278479,-0.391527,0.269088,0.123402,-0.225607,0.112181,-0.093940,0.219284,-0.123010,-0.311305,-0.237538,-0.056634,-0.093395,-0.453352,0.580942,-0.174131,-0.573647,-0.069911,-0.223386,-0.178237,-0.522246,0.102981,0.065182,0.213401,0.638281,-0.661874,0.195782,0.074460,0.097298,-0.091981,0.595548,-0.162552,0.093425,-0.317095,0.213493,-0.174441,-0.282444,0.382223,0.448311,0.494335,-0.166841,-0.458859,-0.376782,0.180630', '1306505', '1299965', '1296266', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294009', '蒲公英', '喜剧', '单身妈妈蒲公英（宫本信子 饰）在丈夫去世后独自经营一家名为“来来轩”的拉面馆，但她的手艺实在欠佳，以致食客稀少，小店举步维艰。长途货运司机黑郎（山崎努 饰）和Gun（渡边谦 饰）暴雨之夜落脚来来轩，黑郎直言不讳指出了拉面存在的问题。学艺心切的蒲公英请求黑郎收她为徒，提升厨艺。出于对母子境遇的同情，黑郎对蒲公英展开魔鬼式训练，并带着她走访附近的拉面馆，学习吸取同行们的经验。在这一过程中，不断有业内的名师和热心的好友加入进来，共同协助蒲公英研制足以吸引万千食客的美味拉面……©豆瓣', '山崎努', '伊丹十三', 8.4, 10482, 'tt0092048', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1967178623.jpg', 0.2, 1.2, 13.9, 47.6, 37.2, '0.136335,-0.129683,-0.371439,0.633878,-0.021377,-0.138317,0.462903,0.311872,-0.611546,-0.211928,0.228277,0.559383,0.078335,0.107081,0.160872,-0.173137,-0.064154,-0.282099,0.012299,0.001848,-0.112320,-0.273396,-0.092659,-0.377595,-0.230341,-0.115850,0.210889,0.089683,-0.184560,0.698457,0.079064,0.218779,-0.165685,0.234332,-0.159732,0.024031,0.165310,0.100536,-0.389296,0.136728,-0.094687,-0.250114,-0.203102,-0.004440,0.281347,0.353498,0.653509,-0.094940,-0.316321,-0.148014,0.087275,-0.183798,0.160804,0.080802,0.418053,0.192835,0.323305,-0.101838,-0.219369,0.241746,-0.252584,-0.202322,-0.727068,-0.277419,0.390966,-0.192386,-0.598083,0.481607,0.074226,-0.247457,0.104901,-0.315435,-0.122197,0.222334,0.138162,0.348487,-0.159075,0.194982,-0.325316,0.272266,0.502325,-0.049002,0.042024,0.381000,-0.508958,-0.275678,0.065552,-0.104758,-0.227281,-0.261909,0.023681,0.236789,-0.075884,0.075343,-0.835138,0.065056,0.087126,-0.255321,0.177310,-0.061819,-0.208744,-0.871216,0.256959,-0.475864,-0.256475,0.018417,0.205486,-0.103735,0.910015,-0.768959,0.129030,0.365259,0.243649,-0.384088,0.685513,-0.115935,-0.047313,-0.206464,-0.442885,0.271090,0.007650,0.205590,0.148071,0.259703,-0.060180,-0.125697,-0.394575,0.071052', '3811356', '4181031', '19965431', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294011', '黄飞鸿之四：王者之风', '动作', '黄飞鸿（赵文卓 饰）夺得狮王争霸金牌后飘然而去，一时间广东会馆高朋云集纷纷做贺，八旗将军府副都统瓜鄂尔·成都（陈继铭 饰）大人登门拜访，原来八国联军欲使用各自的巨型赛狮挑战清廷，为维护国体，黄飞鸿决定出战与瓜鄂尔·成都将军共赴国难。梁宽（莫少聪 饰）再度惹下事端被黄飞鸿驱逐，无 奈只得与鬼脚七（熊欣欣 饰）等找到在北京办报的十四姨（王静莹 饰）求助，黄飞鸿亦赶到报馆，却与十四姨卷入了红灯照在租界内屠杀洋人的事端，黄飞鸿出手救人，与红灯照大师姐苗三娘（王菁华 饰）一同被德国兵士关押拷打。越狱而出的黄飞鸿从红灯照手中救出了众亲人，然而却因此错过了赛狮，瓜鄂尔·成都将军孤身战死。黄飞鸿为国为友，满腔豪情二次挑战八国巨狮……©豆瓣', '赵文卓', '元彬', 7.2, 26876, 'tt0107162', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2047660078.jpg', 0.5, 3.8, 44, 39.4, 12.3, '-0.129333,0.026015,-0.456769,0.220471,0.331643,-0.179172,0.242032,0.414313,-0.220088,-0.153942,0.268521,0.332530,-0.089957,-0.091823,0.127648,-0.292625,0.056997,-0.658365,-0.212060,0.145066,0.040081,-0.111661,0.142267,0.049442,-0.005470,0.008713,0.520067,0.092513,-0.027787,0.621199,0.365541,0.210233,-0.249014,0.211734,0.063536,0.054806,-0.101587,-0.027227,-0.270290,0.221419,-0.227939,-0.390891,-0.316275,0.022702,0.175891,0.289988,0.656361,-0.282137,0.208877,-0.203621,0.105653,-0.076429,0.041740,0.165473,0.172255,-0.056663,0.026708,0.295440,-0.026742,-0.003090,0.028595,0.072883,-0.122457,0.221937,0.067093,-0.135795,-0.591389,0.243895,-0.183654,-0.017918,0.054329,-0.191707,0.147356,0.196787,-0.022105,-0.025102,-0.169041,-0.152728,-0.455467,0.264432,0.350129,-0.025810,0.116872,-0.393091,0.472526,-0.249633,0.288932,-0.244905,-0.086623,-0.083698,0.380178,-0.249154,0.253035,0.085473,-0.322831,-0.399262,-0.506896,0.159000,0.098206,0.079827,0.140419,-0.472280,0.164320,0.159016,-0.081170,0.146768,0.406105,0.317961,0.335919,-0.299909,0.054911,0.081947,0.218261,-0.579180,0.506878,0.072758,0.007268,0.068131,-0.015099,-0.111267,0.247285,0.381566,0.092388,0.087688,-0.217403,-0.313337,-0.316979,-0.068704', '1451563', '1294227', '26365262', '1308973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294015', '星际旅行3：石破天惊', '动作', '2285年，在与可汗的战斗中损坏的联邦星舰进取号，返回了地球的太空港以进行维修。柯克还在为斯波克的死感到悲伤。麦科伊医生出现了种种异常的行为：如擅自闯入被封锁的斯波克原来的舱房、胡言乱语等，最后他被送进了医院进行精神检查。斯科提被另分派到了联邦星舰精进号。星际舰队指挥部 对新形成的创世星下达了禁入令。柯克被告知，进取号即将除役。斯波克的父亲沙瑞克找到柯克并告诉他，斯波克的遗体必须返回瓦肯星，否则他的灵魂就不得安息。沙瑞克要求柯克必须回到创世星，寻回斯波克的遗棺并将它带回瓦肯星——而斯波克临死前与麦科伊进行了心灵融合，因此带有斯波克灵魂的麦科伊也必须前往瓦肯星。可是，星际舰队拒绝让陈旧的进取号离开太空港。从医院出来后听闻消息的麦科伊，企图招募一艘飞船回到创世星。在与人争吵时他被逮捕，但这并没有影响到整个计划：在柯克、斯科特、苏鲁、乌乎拉和切科夫的帮助下麦科伊顺利逃脱，并一同登上了被废弃的进取号。为了避免被追击，斯科提还破坏了精进号的引擎。六名伙伴冒着毁掉毕生事业的风险，驾驶进取号航向创世星。其间，克林贡人得知了创世计划和创世星的消息。由于担心联邦将其改造为一种新式武器，克鲁格船长率领一艘克林贡猛禽战舰，去夺取或摧毁这一战略性的武器。在联邦星舰葛瑞森号上，戴维·马库斯博士与莎维可上尉在创世星的轨道上进行着科学观测。他们很快便在地面上发现了生命形式，出于好奇心的驱使，他们俩传送上了星球表面并发现了斯波克空荡的遗棺。循着生命形式的读数，他们发现了幼年斯波克的活体：成长速度奇快，但却没有意识或灵魂。克林贡人在此时也抵达了创世星，他们摧毁了葛瑞森号并抓获莎维可、马库斯和少年的斯波克作为人质', '威廉·夏特纳', '伦纳德·尼莫伊', 7.3, 8585, 'tt0088170', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2209381125.jpg', 0.6, 4.1, 39.3, 39.7, 16.4, '0.154415,0.468143,-0.907856,0.622017,0.075991,-0.216957,0.629229,0.207569,-0.305380,-0.100194,-0.094553,0.558797,0.122820,-0.041232,0.433835,0.220997,-0.619485,-0.346988,0.028849,-0.196514,-0.572265,-0.661355,-0.034430,-0.164808,-0.037854,-0.692303,0.648990,0.162135,-0.294499,0.207760,-0.015535,0.369284,0.016478,0.661368,-0.155273,-0.026620,0.159312,-0.311849,-0.089807,0.312667,-0.215255,-0.046233,0.238195,0.142528,-0.034169,0.419735,0.761931,-0.423774,0.043460,-0.163856,0.192566,-0.292216,0.208617,-0.122529,0.382180,0.174998,-0.567315,0.292377,-0.211825,0.256988,0.101094,-0.041422,-0.783940,-0.107495,-0.182631,-0.030814,-0.603123,0.257230,-0.374306,0.196595,-0.159932,-0.101073,0.330527,0.473385,0.016362,0.204799,-0.284011,-0.007802,-0.599069,-0.189593,0.500594,-0.206469,-0.386549,0.150073,0.107092,-0.621134,-0.254844,-0.200727,-0.163807,-0.231412,0.481824,0.214365,0.045952,0.341056,-0.653545,0.0