INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294019', '监狱风云2：逃犯', '剧情', '《监狱风云》的续作，资深囚犯阿正（周润发 饰）因为与前任科长（张耀扬 饰）的过节而延长刑期，服刑期间母亲病逝，儿子良仔被送到孤儿院甚至对父亲产生怨恨。阿正一心想申请外出看望儿子却遭到狱警头子“鬼见愁”（徐锦江 饰）的诸多刁难。“鬼见愁”因收买狱中大陆帮首领大圈龙（陈松勇 饰）不果 ，把其视为眼中钉，并且从中唆使挑拨使得大陆帮与阿正之间产生隔阂。一次陷害使得大圈龙不得不出逃，被误会陷害大圈龙的阿正也被迫逃走，逃跑途中两人相遇并产生了一段“难兄难弟”般的友情。最后阿正被再次抓回狱中，在暴乱中阿正终于得到机会和”鬼见愁“短兵相接。©豆瓣', '周润发', '林岭东', 7.9, 39126, 'tt0103044', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190472258.jpg', 0.2, 1.4, 25.1, 50.5, 22.7, '-0.147643,-0.037771,-0.598416,0.583814,0.146012,-0.134007,0.516592,-0.030116,-0.615659,-0.252029,0.019500,0.446653,-0.345917,0.282091,0.253025,-0.397432,-0.004611,-0.709072,0.134581,0.020248,-0.282817,-0.265044,-0.369590,-0.182865,-0.260811,-0.306902,0.565884,0.179864,-0.346056,0.466750,0.306258,0.589176,-0.515356,0.451881,-0.065565,0.183873,0.052622,0.119250,-0.489974,0.040207,0.096453,-0.257052,0.120787,0.157829,0.007331,0.288646,0.691223,-0.178898,-0.086132,-0.630633,0.304600,-0.465911,-0.034741,0.025919,0.595112,0.183373,0.390294,0.591609,-0.230998,0.179406,0.194339,-0.108447,-0.340032,0.207815,0.277641,-0.272491,-0.517586,0.200392,-0.016496,0.004654,0.066909,0.191428,0.318668,0.498329,0.393771,0.238788,-0.320181,-0.087305,-0.329188,-0.001494,0.728386,-0.518909,0.086562,-0.184547,0.323143,-0.126393,0.289498,-0.087085,0.137294,0.099110,0.286779,0.013976,-0.189226,0.408081,-0.526602,-0.437140,-0.517724,0.296962,0.175841,-0.482342,0.085872,-0.482843,-0.100528,-0.010369,-0.082009,0.183230,0.246697,-0.155674,0.135464,-0.581061,0.333231,0.242135,0.580196,-0.899618,0.262234,0.061747,0.117195,-0.443159,0.018448,0.098304,0.472011,0.129331,0.334911,-0.265354,-0.118850,-0.203100,-0.014332,-0.105578', '1293265', '10604851', '1484760', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294037', '未来水世界', '动作', '公元2500年，地球两极冰川大量消融，地球成了一片汪洋。人们只能在水上生存，建起了水上浮岛，泥土成了稀有之物。一天，来了一个孤独的海行者（凯文•科斯特纳 Kevin Costner 饰），他用了一罐泥土换了淡水和番茄苗。正当他要离开时，当地人发现他竟然长着鳃和蹼，认为他是怪物，把他关了起来，准备过两天将他处死。时日，海盗袭击了浮岛，海伦（珍妮•特里普里霍恩 Jeanne Tripplehorn 饰）和她的养女伊萝娜（蒂娜•米乔里诺 Tina Majorino  饰）没能赶上出逃的救生船，她们救出了海行者。海行者凭着过人的机智和勇敢，带着海伦和依蒙娜逃了出来。原来，海盗的目标只是伊萝娜，依蒙娜的身世藏着一个惊人的秘密……©豆瓣', '凯文·科斯特纳', '凯文·雷诺兹', 7.5, 75891, 'tt0114898', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2159099238.jpg', 0.8, 4.3, 32.6, 43.9, 18.4, '0.119704,0.052720,-0.746856,0.587048,-0.128991,-0.293497,0.775054,0.001557,-0.383113,-0.070609,-0.064270,0.535381,-0.038486,-0.040959,0.106908,0.199604,-0.371482,-0.400323,-0.214227,-0.354044,-0.582459,-0.352306,-0.510385,-0.145311,-0.067298,-0.354315,0.375023,0.121744,-0.005416,0.313786,0.120825,0.001729,-0.089011,0.500039,-0.386409,0.288463,-0.076074,-0.106122,-0.010668,0.347278,-0.049487,-0.101328,-0.098525,0.073388,0.178594,0.500234,0.715293,-0.419023,0.125114,-0.026018,0.080394,-0.447543,0.136881,-0.024568,0.606382,-0.201020,-0.119969,-0.002860,-0.215150,0.017534,0.376420,-0.128084,-0.424012,-0.172112,-0.084858,0.071387,-0.823967,0.302781,-0.086012,0.016495,-0.077192,-0.535146,0.110612,0.105782,-0.129546,0.382723,0.000532,-0.164588,-0.820599,0.497787,0.610695,-0.058481,-0.129690,0.242245,-0.025159,-0.641859,-0.255587,-0.276224,-0.251745,-0.263820,0.792819,-0.021458,-0.388215,0.256122,-0.876436,-0.140487,-0.365424,-0.158382,-0.015550,-0.209359,-0.320398,-0.125682,0.065474,-0.325930,-0.257200,0.080403,-0.122912,-0.104676,0.714956,-0.758812,0.273647,0.639223,0.261037,-0.102731,0.642193,-0.267945,0.054141,0.101938,0.267224,0.064511,0.094438,0.568289,0.564131,0.623276,0.067719,-0.073273,-0.431053,0.260328', '21619567', '1309101', '1805685', '1316560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294038', '流星语', '剧情', '少君（琦琦）产下儿子明仔（叶靖岚）后被丈夫抛弃，为了不让明仔跟着自己过苦日子，她把明仔遗弃在了一艘豪华游船上，期望好心有钱的人士捡去，但自己从此落下心病。证券经纪人李兆荣（张国荣）见到明仔时虽已是因金融风暴而破产的穷光蛋，还是决定收养他，两人住进养老院天台的一间木屋，李兆荣开始靠骑单车为别人送货挣生活费。四年后李兆荣和明仔成为一对外人看来亲密无间的父子，少君则成了某慈善基金会的主席，因为一次资助养老院的兰姐（吴家丽）开设一家照料街童的托儿所事件，李兆荣与少君结识，悲情故事就此展开。©豆瓣', '张国荣', '张之亮', 8.6, 14783, 'tt0223603', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p939431341.jpg', 0.3, 0.8, 13.8, 39, 46.1, '0.127671,-0.060207,-0.459452,0.150852,-0.105398,-0.623721,0.556824,0.168555,-0.496514,-0.182678,0.182864,0.812987,0.028177,0.613531,0.325170,0.197016,-0.003392,-0.457360,-0.017710,-0.086857,-0.075130,-0.258361,0.140159,-0.213708,-0.155225,-0.013699,0.464619,0.102344,-0.012940,0.439309,0.365252,0.092868,-0.165325,0.057426,-0.232865,0.091884,-0.056423,0.237403,-0.551574,0.128992,-0.196515,-0.168151,-0.050148,-0.173344,0.094343,0.345619,0.523579,-0.017541,-0.090163,-0.429071,0.195204,-0.159512,-0.131046,0.020203,0.312921,0.143137,0.437012,0.399224,-0.461086,0.041311,0.184348,-0.194861,-0.375750,0.035222,0.085842,-0.091047,-0.625157,0.518080,-0.044998,-0.050719,-0.096852,-0.277055,0.121545,0.369994,0.077812,0.449681,-0.340767,0.425505,-0.436023,0.214519,0.747291,-0.169016,0.079053,0.402316,0.081487,-0.194412,0.538286,-0.318544,-0.334791,0.040744,0.146281,-0.126742,-0.276080,0.080173,-0.401799,-0.144604,-0.214835,-0.192016,0.204614,-0.435566,-0.052322,-0.247798,-0.022773,0.030766,-0.144569,0.125900,0.101708,-0.351341,0.439464,-0.686585,0.155848,0.211724,0.437267,-0.696937,0.693880,-0.057869,0.330458,-0.119115,0.034507,0.034416,0.068801,0.365355,0.239485,-0.171420,-0.138016,-0.208021,-0.105624,0.178917', '1308035', '25721544', '1296978', '2080130');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294039', '绿光', '剧情', '夏天快要来临的时候，巴黎女子戴尔芬（玛丽·瑞莱 Marie Rivière 饰）却陷入了忧伤与烦闷中。刚刚和前男友结束恋爱关系，本来约好与她一同度假的女友也放了她鸽子。尽管其它许多好心的亲友邀请她一同度假，但是她却一一拒绝了。每个人都有了自己的度假计划，只有她看似要独身 一人困在巴黎过冗长的夏天。她寻寻觅觅，终日游荡在各处，希望能够找到自己的情人，但是所遇之人皆不能触动她心。在马赛海边，她听说了关于绿光的传说：谁能看到绿光，谁就能得到幸福。落寞的她打算返回巴黎，在车站，一个男子对着正在阅读小说《白痴》的她微笑，戴尔芬似乎觉察到了什么，她主动邀请男子去海边看日落。在灿烂的光辉中，男子对她表白，而她却固执地等到绿光才给出答案。本片获得第43届威尼斯电影节金狮奖。©豆瓣', '玛丽·里维埃', '埃里克·侯麦', 8.1, 31470, 'tt0091830', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536313627.jpg', 0.3, 1.8, 19.5, 49, 29.4, '0.155264,0.198206,-0.936504,0.573694,-0.164875,-0.327044,0.764556,0.099323,-0.339295,-0.026193,0.053631,0.819608,-0.340722,0.471569,0.163973,0.422342,-0.395386,-0.629625,0.074175,-0.348358,-0.099394,-0.270694,-0.256548,-0.082715,0.181179,-0.158988,0.388549,0.294310,0.092471,0.386883,0.161070,-0.143177,-0.107863,0.896070,-0.431271,-0.102477,0.070394,0.190784,-0.170990,0.239020,0.095909,-0.426319,-0.449368,0.314640,0.099283,0.346122,0.636644,-0.117979,-0.081492,0.332018,0.159527,-0.176643,0.114204,0.142557,0.081524,-0.228034,0.234755,0.052374,0.042944,-0.143555,-0.123847,-0.074703,-0.550683,0.183199,-0.090679,0.411003,-0.463985,0.596147,-0.111487,0.134654,0.063935,-0.339747,0.201443,0.139834,0.024317,0.250309,-0.069583,-0.138537,-0.489170,0.363302,0.766803,0.073285,-0.104302,0.536831,-0.362802,-0.339472,0.043675,0.157445,-0.424844,0.019561,0.419924,0.058493,-0.317738,0.016692,-0.468544,0.069617,-0.126059,-0.089117,-0.126857,-0.456591,-0.016906,-0.496753,0.036865,-0.312679,-0.509600,0.073407,0.119447,-0.167008,0.508295,-0.900225,0.383300,0.652443,0.425327,-0.443925,0.745886,0.088546,-0.200137,-0.188542,0.021531,0.303574,-0.151452,0.321072,0.117450,0.374642,0.039813,-0.059796,-0.457785,0.536418', '1308755', '1292211', '1309080', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294047', '凡尔杜先生', '剧情', '凡尔杜先生（查理·卓别林 Charles Chaplin 饰）曾经是一名银行的职员，跟妻子莫纳（Mady Correll 饰）和儿子皮特（Allison Roddan 饰）一同过着平静但是幸福的生活。经济大萧条的到来令凡尔杜先生失去了工作，有一个家庭要养活的他流落在街头无处容身，绝望之情溢于言表。一次偶然中，凡尔杜先生得到了一种神奇的毒药，它能够杀人于无形之中，拥有了这一“凶器”，一个绝妙的计划在他的脑海中诞生了。很快，塞尔玛（Helene Heigh 饰）、莉迪亚（Margaret Hoffman 饰）、格罗奈（伊索贝尔·埃尔索姆 Isobel Elsom 饰）等多金但无脑的女人们都成为了凡尔杜先生手下的冤魂，而她们的大笔财产，则都到了凡尔杜先生的口袋之中。©豆瓣', '查理·卓别林', '查理·卓别林', 8.8, 9189, 'tt0039631', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1819874418.jpg', 0.4, 0.7, 8.6, 40.6, 49.8, '0.021233,-0.105695,-0.544112,0.720966,-0.240863,-0.435752,0.905815,0.075237,-0.605299,-0.280062,-0.067986,0.781441,-0.036909,0.644628,0.576377,0.187105,-0.091882,-0.412585,-0.080190,-0.246978,-0.313802,-0.680805,-0.442837,-0.498412,-0.279595,-0.252410,0.287299,0.259783,0.115538,0.637617,0.209493,0.359700,0.117537,0.558076,-0.012129,0.064996,0.227863,-0.048692,-0.258588,0.207576,0.124809,-0.029226,-0.030698,0.221873,0.267940,0.227222,0.531332,-0.300566,0.045879,-0.044125,0.404890,0.057296,0.339641,0.179220,0.142918,-0.141549,0.144271,0.031433,-0.406669,0.034441,0.389165,-0.235108,-0.819882,-0.091054,0.016778,-0.018838,-0.562729,0.314102,-0.083707,-0.186173,-0.069646,-0.155028,0.291429,0.191001,0.453365,0.204156,-0.189286,0.009626,-0.674807,0.352404,0.398140,-0.032348,-0.345831,0.232242,-0.321927,-0.673788,-0.276942,-0.176659,-0.584229,-0.288854,0.481422,0.045327,-0.044578,0.201493,-0.565381,-0.143168,-0.257993,-0.009027,-0.119748,-0.244612,-0.137959,-0.318029,-0.322808,-0.445036,-0.236896,0.161690,0.261093,-0.222340,0.810521,-0.742015,0.249342,0.369279,0.167426,-0.350816,0.624051,-0.012801,0.280208,0.151938,-0.220181,0.397448,0.349631,0.274637,0.360600,0.405117,0.031221,0.035940,-0.068402,0.576658', '1783461', '24698878', '3119246', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294048', '卡拉瓦乔', '剧情', '影片是对性、犯罪行为和艺术的一种深思，导演成功地将影象和绘画这两件生命中重要的元素呈现出来，丰富地描绘出意大利传奇画家的一生。本片是一部传记体影片。英国的先锋派导演贾曼也是一名画家，他怀着对卡拉瓦乔这位伟大的艺术家的崇敬心理和对画家生活的浓厚兴趣，拍了这部关于艺术家生活片断的作品。本片的手法和题材不拘一格，从各角度都给人以新鲜感。本片获得1986年柏林国际电影节银熊奖，是英国1986年最卖座影片之一。', '尼吉尔·特瑞', '德里克·贾曼', 8.1, 6221, 'tt0090798', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2557156946.jpg', 0.5, 2.3, 20.1, 47.2, 29.9, '0.114164,-0.167409,-0.494988,1.184542,0.303119,-0.088210,0.820280,-0.249749,-0.411608,-0.189553,0.116911,1.155066,-0.337587,0.269989,0.557963,-0.029923,-0.355740,-0.795363,-0.348021,0.086236,-0.032736,-0.385225,-0.729430,-0.185931,-0.407678,-0.597296,0.973974,0.284368,-0.517295,0.327499,0.406463,0.485279,0.219638,-0.049924,-0.052779,-0.070534,0.018215,-0.041016,-0.564760,0.173634,0.439471,-0.291091,-0.186156,0.172615,-0.279284,-0.073233,0.688151,-0.113119,-0.008832,0.239245,0.914951,-0.413018,-0.180683,-0.122735,0.040056,0.226494,0.244391,0.366856,0.124416,0.201615,-0.155016,-0.356553,-1.138532,-0.328499,0.337491,0.065259,-0.434520,0.528446,-0.132191,-0.212957,-0.100565,-0.297229,0.320250,-0.160471,0.363505,0.617247,0.101236,0.200661,-0.298092,0.707712,0.190722,0.125829,-0.593448,0.546448,-0.640424,-0.874325,-0.351251,-0.688035,-0.383624,0.343579,0.299114,-0.021762,0.109516,0.001629,-0.834061,0.203156,0.151733,-0.450572,0.148533,-0.395567,0.148545,-0.895033,-0.273955,-0.809570,-0.084323,-0.604503,0.449550,-0.421012,1.323636,-0.504144,0.065010,0.275780,-0.047544,-0.372082,1.251705,0.041656,-0.263671,-0.165478,-0.129452,0.141997,-0.251836,-0.155156,-0.466994,0.519900,0.365368,-0.315692,-0.331759,0.751471', '22265121', '27602116', '2027945', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294092', '恐惧吞噬灵魂', '剧情', '艾米（布里奇特·米拉 Brigitte Mira 饰）是一名60岁的清洁女工，辛苦工作的她拿着微薄的工资，生活很是清贫。机缘巧合之下，她结识了40岁的阿里（El Hedi ben Salem 饰），他们一起跳了一支舞后阿里提出送艾米回家。夜深了，阿里错过了末班车，只得在艾米家留宿。两个孤独寂寞的人相见恨晚，秉烛夜谈，当艾米为此感到深深的疑虑时，阿里只是淡淡的安慰了她。果不其然，艾米留宿男人的事情很快传遍了大街小巷，邻居同事的指指戳戳教她如坐针毡，无奈的她只得编撰了一个谎言，她说阿里是她的未婚夫。这门婚事毫不意外的遭到了所有人的反对，大家尽己所能的排挤、诋毁这对夫妻，这使得他们决定外出旅行避避风头。回来后两人的境遇有所好转，并不是街坊邻居接纳了他们，而是因为他们有了新的排挤对象。没有了外界的压力，艾米和阿里的感情却又因为内部的矛盾而产生了裂痕。影片用写实的手法展现了一个冷漠、刻薄的社会，探讨了这个社会之中存在的各种歧视以及人性之中孤独又灰暗的一面。', '布里吉特·米拉', '赖纳·维尔纳·法斯宾德', 8.5, 14978, 'tt0071141', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553755181.jpg', 0.2, 0.7, 10.8, 51.6, 36.7, '0.587562,-0.152833,-0.748153,0.663271,-0.239334,-0.332528,0.924500,0.308281,-0.644831,-0.165940,0.238687,0.781872,-0.223215,0.358022,0.059588,-0.045606,-0.320442,-0.671930,0.080159,-0.209897,-0.148123,-0.385421,-0.027690,-0.312755,-0.388085,-0.159461,0.294288,0.100410,-0.207971,0.602485,0.185130,0.183006,0.174241,0.794719,-0.129576,0.123657,0.057104,0.083781,-0.063402,0.034678,0.071561,-0.241823,-0.164692,0.414295,-0.133312,0.678808,0.487119,-0.144618,-0.181733,0.004227,0.409169,-0.312058,-0.035183,0.247349,0.215613,-0.028471,0.202057,0.038276,-0.270903,-0.046778,-0.088263,0.153842,-0.727901,-0.004964,0.015507,0.062251,-0.734664,0.711883,-0.030555,-0.341660,-0.051932,-0.272936,0.234462,0.367390,0.190400,0.238451,-0.127240,-0.127995,-0.461275,0.163153,0.562956,-0.058227,-0.368586,0.363617,-0.616576,-0.416047,0.085782,-0.181946,-0.519097,-0.219504,0.283520,0.042238,-0.228970,0.254408,-0.659617,0.006001,-0.162349,-0.220207,-0.103968,-0.603173,0.115480,-0.548887,-0.316036,-0.659348,-0.616318,-0.127011,0.083943,-0.170845,0.662673,-0.881776,0.122042,0.548799,0.394369,-0.583704,0.668123,0.127910,0.025111,-0.024837,0.006918,0.057778,-0.306696,0.393537,0.342795,0.49634