INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294114', '冒险王', '动作', '电视剧编剧周世杰（李连杰）被妻子莫尼卡（关之琳）闹离婚，郁闷之下开始编写剧集《冒险王》的剧本，想象中他成了民国时代的冒险王卫亦信，莫妮卡变作日本特务美加子，借此宣泄郁闷。唐三藏当年西天取得、今下落不明的无字真经成为中国及日本政府争抢的目标，为免日本人捷足先登，中国政府邀请考古专家卫亦信及其徒弟包教晓（金城武）追查真经下落，得知线索在经盒表面，两人混入日本领事馆，结识身份神秘的美女美加子，后两人又追线索到某日报社，从编辑英叔（罗家英）口中知晓经盒下落，但消息亦被美加子得知。©豆瓣', '李连杰', '程小东', 6.8, 57340, 'tt0110463', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2352279222.jpg', 0.8, 6.7, 53.3, 30.9, 8.3, '0.056718,0.162695,-0.578354,0.421331,0.347659,-0.021040,-0.075300,-0.124668,-0.426818,-0.215357,-0.093519,0.462648,-0.288882,0.134153,0.106168,0.089949,-0.245775,-0.542815,0.184943,-0.232405,0.218901,-0.329030,-0.158186,-0.096231,-0.266357,-0.309794,0.645026,0.267857,-0.351707,0.161450,0.424385,0.237023,-0.433782,0.266572,-0.039241,0.327594,0.443084,0.068555,-0.220632,0.312331,0.013260,-0.272925,0.080733,0.170890,-0.152626,0.352312,0.400136,0.190353,-0.088972,-0.140486,0.535464,-0.049371,-0.330408,-0.029044,0.578502,0.327683,0.145474,0.348178,0.029096,-0.179148,-0.080984,0.131479,-0.255699,0.202578,0.434014,0.374912,-0.167673,-0.086862,-0.510686,0.285987,-0.029716,-0.280350,0.345588,0.218943,0.264184,0.038848,0.091900,0.185719,-0.372201,0.357215,0.250611,-0.204779,0.061180,0.060726,0.163855,-0.274146,0.289426,-0.063391,0.179861,0.160875,0.337410,-0.117791,-0.335629,0.119241,-0.147652,-0.261534,-0.259486,0.177848,-0.018518,-0.200333,0.007602,-0.818976,-0.299632,0.210192,-0.003485,-0.315028,0.124904,-0.379596,0.762966,-0.217656,-0.063403,0.303329,-0.050774,-0.505718,0.409189,0.072251,-0.028773,-0.507327,0.075562,0.260538,0.224513,0.206113,-0.102383,-0.157135,-0.149992,-0.448815,-0.234976,-0.199612', '25863940', '1322847', '2369613', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294131', '师弟出马', '剧情', '正风武馆在当地颇有名气，因为当地一年一度的舞狮大会正风武馆已经连续七年夺冠。今年，舞狮大会举办方为了吸引眼球，设了难度极高的采青大赛。阿昆和阿龙（成龙 饰）是正风武馆的师兄弟，每年都是阿昆代表武馆初赛。不料今年出赛前几天练习时阿昆失足扭伤了，馆长无奈之下只能 派出阿龙出赛。阿龙由于首次参赛，而且今年难度非常大，最终败下阵来。虽然受到了其他师兄弟的取笑，但阿龙丝毫没有放在心上，反而，他在比赛中发现的一个秘密却成了他的心头大石。©豆瓣', '成龙', '成龙', 7.2, 10957, 'tt0081499', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2179820635.jpg', 0.6, 3.3, 45.3, 37, 13.8, '0.107203,0.117632,-0.738619,0.245816,0.168022,-0.128754,0.166642,-0.150864,-0.648478,-0.299079,0.408907,0.630274,-0.460407,0.200082,0.073115,-0.597888,0.283988,-0.528396,-0.052765,-0.224337,-0.305320,-0.357278,0.077334,0.232507,-0.199104,-0.143386,0.441149,0.205884,-0.239987,1.033893,0.320013,0.021080,0.385284,0.268159,0.007755,-0.081604,0.413418,0.100082,0.027513,0.137140,-0.119855,-0.224493,-0.486010,0.175313,0.472964,0.670298,0.334571,0.153337,-0.344063,0.000150,0.240407,-0.273135,-0.112651,-0.140405,0.732657,0.092075,0.304815,0.333292,0.133395,0.197309,-0.179340,-0.279023,-0.538831,0.488738,0.539032,0.034172,-0.575787,0.944208,0.050673,-0.048097,-0.526627,-0.198930,0.071419,0.303679,0.164365,-0.002870,-0.038028,-0.071205,-0.488694,0.161187,0.807854,-0.148188,-0.086898,0.038178,0.045283,-0.446559,0.038140,-0.621275,0.135487,0.433115,0.352273,0.046108,-0.103413,-0.067035,-0.373182,0.170283,0.034059,-0.460439,-0.046660,-0.204692,0.307801,-0.760572,0.231443,-0.194035,-0.304406,-0.129542,0.103636,-0.261525,0.718783,-1.091150,0.164346,0.354718,0.143640,-0.299806,0.466901,0.142628,0.229444,0.049352,-0.454448,-0.510941,-0.095820,0.295855,-0.011616,0.415714,0.179914,-0.776093,-0.208816,0.162635', '3139191', '35030151', '3230460', '3091208');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294136', '天鹅绒金矿', '剧情', '摇滚史上最华丽的70年代，性感、妖艳、前卫、激进等各种大胆元素被融合成独特的摇滚流派。这场摇滚革命的代言人布莱德·斯莱德（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰）彼时倾倒众生。然而，1984年，他在一次演出中遭遇“暗杀”，巨星自此陨落。伦敦先 驱报 记者阿瑟（克里斯蒂安·贝尔 Christian Bale 饰）对自己的偶像展开调查。在回溯逝去岁月之中，却挖掘出布莱德与美国摇滚歌手库尔特·怀尔德（伊万·麦克格雷格 Ewan McGregor 饰）的一段冰火之恋。布莱德受库尔特音乐的感染，创造出自己的华丽风格，迅速走红。两人相互激发灵感、彼此迷恋，最终却因为性格冲突而决裂。风头正劲的布莱德在失去库尔特之后也开始自暴自弃，导演出一场“暗杀”剧……。阿瑟在酒吧邂逅消沉的库尔特，他仿佛被布莱德灵魂附体，他们共同沉浸在对布莱德的怀念中难以自拔，同时一种奇妙的情感在他们之间诞生。本片获得第71届奥斯卡金像奖最佳服装设计提名、第51届戛纳电影节最佳艺术贡献奖及金棕榈奖提名。', '伊万·麦克格雷格', '托德·海因斯', 8.4, 63351, 'tt0120879', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p580624079.jpg', 0.5, 1.8, 15.6, 40.8, 41.3, '0.199236,0.226297,-0.784039,0.629829,0.127442,-0.163546,0.676168,-0.027344,-0.375880,-0.133303,0.253400,0.787592,-0.529839,0.091064,0.561561,-0.116490,-0.350093,-0.840839,0.143148,0.057273,0.081963,-0.337722,-0.450099,0.166099,-0.122980,-0.654553,0.773638,0.017563,-0.331016,0.549674,0.488191,0.366253,-0.021643,0.099634,0.151442,0.121715,0.360465,0.013271,-0.538704,0.283064,0.112559,-0.257209,-0.233114,0.056110,-0.187106,0.070872,0.563629,-0.320102,0.283175,0.025066,0.707959,-0.223648,-0.189079,0.066463,0.167106,0.123816,0.115970,0.180010,-0.116995,0.072630,-0.061253,-0.000642,-0.679457,0.161301,0.043958,0.185692,-0.138896,0.424538,0.082460,-0.017543,0.000674,-0.074376,-0.079260,0.037300,0.754099,0.254387,0.004676,0.043357,-0.077082,0.234832,0.667734,-0.128337,-0.717114,0.249948,-0.331039,-0.425436,-0.238667,-0.427940,-0.482662,-0.087230,0.452444,0.003913,0.390365,0.574156,-0.769640,-0.072967,-0.178286,-0.169456,-0.046993,-0.145839,0.000659,-0.922140,-0.388523,-0.244496,-0.083440,-0.116294,0.077703,-0.325440,0.529613,-0.643295,0.505536,0.479152,0.016918,-0.161598,0.509387,0.142608,0.036766,-0.315270,-0.245660,0.602648,-0.099262,-0.053019,0.019803,0.395243,-0.044572,0.148735,-0.449500,0.578267', '1308069', '34795703', '11541282', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294139', '似水流年', '剧情', '在香港生活的珊珊（顾美华 饰）得知祖母在乡下过世，动身返回阔别20年的潮汕老家，为祖母奔丧，同时也是想借机逃离城市里的烦恼。与快节奏的城市生活相比，珊珊的老家依旧保持着记忆中朴实隽永的生活。珊珊与儿时的玩伴阿珍（斯琴高娃 饰）和孝松（谢伟雄 饰）重逢，此时的两人已结为夫妻，珊珊的到来打破了原本波澜不惊的乡间生活。而珊珊光鲜的城里人生活的背后是不为人知的艰辛和无奈：父亲的早逝、与妹妹的决裂、感情生活受挫……短暂的归乡旅程结束，故事中每个人的人生又会因这场久别重逢发生怎样的变化呢？《似水流年》获得第四届香港电影金像奖最佳影片、最佳导演、最佳剧本、最佳女演员 、最佳新人、最佳美术指导6项奖。©豆瓣', '斯琴高娃', '严浩', 8.2, 7417, 'tt0088126', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377219783.jpg', 0.3, 1.3, 15.9, 53.8, 28.8, '0.140783,0.035631,-0.566502,0.699967,0.215398,-0.183230,0.616662,0.033813,-0.637461,-0.294724,0.096194,0.873252,-0.170452,0.411792,0.267745,-0.233378,-0.372187,-0.796949,-0.014591,-0.150049,0.025546,-0.398546,-0.126996,0.249498,-0.188856,-0.395078,0.782682,-0.007326,0.020984,0.828640,0.148441,0.240825,-0.456752,0.230892,-0.119745,0.112263,-0.207840,0.339497,-0.821934,-0.016771,0.123194,-0.169173,-0.217801,0.031464,0.272498,0.338551,0.904655,-0.096360,-0.173730,0.021518,0.430478,-0.127006,-0.405533,-0.099449,0.268619,-0.239994,0.364144,0.400093,-0.247830,0.000992,-0.236563,-0.337008,-0.562087,0.167771,0.348373,0.145263,-0.505285,0.461845,0.226281,0.005208,-0.010010,-0.314538,0.561536,0.699964,0.174744,0.651433,-0.273859,0.069783,-0.286345,0.686834,0.998544,-0.040460,-0.088129,0.530247,-0.277900,-0.386807,-0.000487,-0.252405,-0.783036,0.068080,-0.124444,0.019851,-0.185844,0.239273,-0.539566,0.091746,-0.202462,-0.039759,0.313303,-0.549345,-0.159373,-0.685404,-0.221244,-0.632387,-0.285007,-0.110621,-0.063601,-0.590214,0.717602,-0.885107,0.133565,0.086757,0.305874,-0.427218,0.779186,-0.015495,0.422474,-0.295617,-0.069840,0.466309,-0.544762,-0.258856,-0.241581,0.074790,-0.263193,0.055490,-0.566329,0.504149', '3445516', '25721544', '10876425', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294140', '秋天的故事', '剧情', '侯麦《人间四季》的最后一部。马嘉利（碧翠丝·罗曼德 Béatrice Romand 饰）是一名大龄剩女，有一个儿子和一片葡萄园，过着自给自足的生活。伊莎贝拉（玛丽·瑞莱 Marie Rivière 饰）一直担心着马嘉利的终身大事，她不愿她的密友在孤独中度过晚年。伊莎贝拉以马嘉利的名义偷偷在报纸上登了交友广告，没想到来者热拉尔（阿兰·利博 Alain Libolt 饰）正是自己中意的类型，一个善意的举动使得两个好友落到了尴尬的境地。罗欣（Alexia Portal 饰）是马嘉利儿子的女友，但她真正喜欢的，却是和年长的马嘉利呆在一起。罗欣也想在马嘉利的爱情道路上出一份力，但她所做的，居然是将自己的前男友，一名年长的哲学教授介绍给马嘉利，但哲学教授显然仍对罗欣恋恋不忘。马嘉利孑然一身的生命里突然闯进了两个男人，秋天就快要结束了，但这一团剪不断理还乱的关系却还在继续着。', '玛丽·里维埃', '埃里克·侯麦', 8.5, 38895, 'tt0137439', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2248726990.jpg', 0.2, 0.6, 11.1, 49.5, 38.5, '0.370576,0.131556,-0.714282,0.787792,-0.314067,-0.447428,0.780969,0.115501,-0.355416,-0.324723,0.196844,0.769090,-0.077247,0.434356,0.188817,0.278384,-0.131505,-0.657059,-0.035545,-0.093518,-0.275243,-0.592297,-0.408482,0.034715,-0.259239,-0.250273,0.395188,-0.012945,-0.128566,0.268406,0.382777,-0.022458,-0.060207,0.611491,-0.369024,0.082287,0.066367,0.050487,-0.079386,0.046482,0.152169,-0.383270,-0.178901,0.191852,0.025554,0.429196,0.742052,-0.269395,-0.217413,0.200339,0.460311,-0.213610,-0.089297,0.290642,0.342944,-0.068737,0.239277,0.026205,-0.189307,0.126640,0.198848,-0.140821,-0.788644,0.059017,-0.060132,0.269348,-0.823936,0.817636,-0.101074,-0.393239,-0.011284,-0.447138,0.371440,0.206247,0.065051,0.520732,-0.305685,-0.102161,-0.384503,0.281892,0.598007,0.208713,-0.214489,0.564630,-0.387629,-0.224988,-0.128789,-0.148053,-0.794321,-0.186456,0.107015,-0.057822,-0.211667,0.128515,-0.624830,0.277273,-0.123667,-0.180001,-0.047265,-0.480951,-0.095031,-0.085021,-0.154416,-0.628778,-0.583575,0.147532,0.132932,-0.412372,0.793926,-0.740484,0.231164,0.610937,0.247395,-0.374217,0.877522,0.397426,0.198181,-0.029887,-0.280057,0.126268,-0.053267,0.077817,0.230958,0.591410,-0.002785,-0.202805,-0.396381,0.440619', '24756472', '1303077', '3230462', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294165', '我为玛丽狂', '喜剧', '泰德（本•斯蒂勒 饰）在十三年前认识了美丽的玛丽（卡梅隆•迪亚茨 饰）。当时他是个平凡的男孩，爱上的是众人的梦中情人玛丽，玛丽也因为泰德挺身而出救了玛丽患有精神病哥哥沃伦而对他产生了好感。可是因为阴差阳错，两人之间的恋情无法继续发展。泰德从未忘记过玛丽，即使当今他已个有名作家。终于他在朋友的建议下雇私家侦探帕特（马特•狄龙 饰）寻找玛丽。帕特很快在迈阿密找到了玛丽，她依然美丽，身为外科整形医生的她为了照顾哥哥，仍孑然一人。帕特见到美女便会神魂颠倒，他深深的被玛丽吸引了。他决定要欺骗泰德说如今的玛丽变得潦倒贫穷，风采不再，希望借此能让泰德退出。帕特也不忘不择手段的追求玛丽，就在他即将得手的时候，真相还是被泰德知道了。前往迈阿密的路上，泰德遇到一名变态杀人犯，泰德竟然被误以为是杀人凶手。同样的阴差阳错，他也在真凶落网的时候重遇了玛丽……©豆瓣', '卡梅隆·迪亚兹', '博比·法雷里', 6.9, 21087, 'tt0129387', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2629117015.jpg', 1.1, 7.2, 46.5, 34.6, 10.6, '0.296535,0.023782,-0.647693,0.318808,-0.409447,-0.474324,0.791917,-0.050375,-0.475801,-0.327381,0.242798,0.879875,-0.286496,0.178692,0.368164,0.260519,-0.271436,-0.566406,0.123790,-0.182135,-0.089837,-0.479079,-0.441311,-0.234782,-0.061411,-0.290751,0.386683,-0.041091,-0.123752,0.369601,0.368043,0.461093,0.164963,0.615619,-0.146666,0.136239,0.348271,-0.063890,-0.242095,0.329430,0.229061,-0.434284,-0.086594,0.395409,-0.150800,0.310261,0.398021,-0.276359,-0.046500,-0.101249,0.186708,-0.261663,0.135712,0.188932,0.149633,-0.294627,0.068495,0.339436,-0.177951,-0.264399,0.162339,0.010943,-0.759094,0.173526,0.069998,0.245603,-0.617379,0.200082,-0.320949,-0.137579,0.161115,-0.444303,0.134970,0.106984,0.264477,0.143632,-0.084824,-0.046393,-0.569527,0.125471,0.813325,0.138047,-0.172361,0.379121,-0.214838,-0.302196,0.239171,-0.172514,-0.602618,0.200546,0.317452,0.032846,-0.330139,0.221086,-0.287171,-0.250101,-0.545624,-0.076732,-0.114248,-0.267203,-0.066692,-0.157615,-0.178311,-0.326166,-0.318121,-0.105190,-0.296976,-0.372571,0.601091,-0.972965,0.339708,0.583031,0.289923,-0.487503,0.566393,0.372596,-0.205251,-0.161899,-0.074985,0.466474,-0.016510,0.161782,0.228561,0.314547,0.228911,-0.165587,-0.300273,0.544719', '1308755', '1783461', '25763555', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294181', '大佬', '剧情', '在黑帮争斗上失败了的山本（北野武饰），走投无路只能去找远在美国洛杉矶的弟弟阿键（真木藏人饰）。在言语不通的陌生城市里，山本找到了弟弟，但他已经成了不务正业的毒品贩子。必然地，他们卷入黑帮仇杀、势力争斗当中，山本凭着心狠手辣，冷静果断，再身边有忠诚的手下加藤（寺岛进饰）以及黑人丹尼（欧玛•艾普斯饰），剿灭墨西哥贩毒党，不断壮大自己的地盘，四处挑战其他帮会，还拉拢一大黑帮头领白濑（加藤雅也饰）的甘心加盟。但是黑手党已经将目标瞄准了他们，一场血雨腥风的恶斗在所难免。©豆瓣', '北野武', '北野武', 8.4, 37295, 'tt0222851', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1543377075.jpg', 0.3, 1.2, 13.9, 47.4, 37.2, '0.308313,0.109590,-0.571593,0.225562,-0.005456,-0.259734,0.307279,0.212709,-0.477106,0.085498,0.192319,0.549361,0.359062,0.008125,0.043255,-0.072077,-0.334638,-0.846549,-0.343448,-0.010800,-0.089045,-0.476957,-0.448429,-0.549178,-0.092597,0.116588,0.553748,0.369029,-0.514326,0.353305,0.468888,0.333299,-0.149427,0.338642,-0.000438,0.041134,0.139996,-0.317792,-0.269067,0.196212,-0.272598,-0.361873,-0.121904,0.063837,0.314842,0.571270,0.483763,-0.083877,0.090495,-0.194170,0.189933,-0.385576,-0.322146,0.116959,0.773071,-0.122882,0.093991,0.190760,-0.118579,-0.202985,-0.001065,0.057735,-0.650646,-0.034947,0.127112,0.247095,-0.562260,0.625841,0.182733,-0.199191,0.138217,-0.003026,0.095527,0.387775,0.309940,-0.186036,-0.129269,0.020374,-0.368045,0.088772,0.671908,0.006903,0.100821,-0.380496,0.093125,-0.401106,-0.301956,-0.877944,0.031627,-0.405846,0.551041,-0.328233,-0.265342,0.372797,-0.570593,0.024821,-0.061005,-0.059328,-0.079542,-0.176679,0.241594,-0.753872,-0.144959,-0.382961,-0.277493,0.177118,0.049103,-0.080627,0.762884,-0.614527,-0.025887,1.056244,0.433604,-0.496947,0.344426,0.111475,-0.019705,-0.120589,-0.289462,0.128549,0.350732,0.253601,0.363340,0.149758,-0.118783,-0.397585,0.071765,0.086400', '1293619', '26892558', '6984051', '26921827');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294183', '黑洞频率', '科幻', '约翰的父亲弗兰克(丹尼斯•奎德 Dennis Quaid 饰)死于30年前一次救火行动中。一次，翻看父亲的遗物时，约翰(詹姆斯•卡维泽 James Caviezel 饰)发现了30年前父亲使用过的一台老式无线电。在随手翻拨频段的时候，他竟然和一名年轻叫弗兰克的男子搭上了线。经过整夜长谈，约翰确定时空发生了错乱，这个弗兰克正是自己30年前的父亲。约翰兴奋异常，顺利帮助父亲躲过了30年前的那场灾难。当他一觉醒来，惊讶地发现了相框中白发苍苍的父亲，他知道自己成功了。然而让人意想不到的是，历史一切都改写。约翰的拯救了父亲，而他的母亲却死于了多年前的一起连环杀人案。当约翰通过无线电再次联系30年前的父亲，意图让父亲阻止母亲被杀时，父亲却又意外成了嫌疑犯！©豆瓣', '丹尼斯·奎德', '格里高利·霍布里特', 8.4, 106664, 'tt0186151', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p812857342.jpg', 0.1, 0.7, 13.8, 50.1, 35.3, '0.075815,0.148387,-0.792792,0.461932,-0.257127,-0.639121,0.727707,-0.319161,-0.677904,-0.321531,0.150109,0.881764,-0.163300,0.389849,0.264221,0.015826,-0.289266,-0.787970,0.043673,-0.058101,-0.619962,-0.435012,-0.431035,-0.287631,0.117882,-0.496872,0.278554,0.056415,-0.021100,0.545350,0.158381,0.254851,0.049776,0.558253,-0.020121,0.254422,0.110569,0.046129,-0.245374,0.171813,0.096855,-0.450081,-0.026241,0.428154,-0.145721,0.596477,0.443500,-0.313562,-0.127229,-0.091428,0.383620,-0.076192,-0.133514,0.104224,0.340009,0.280385,0.017340,0.268236,-0.284592,-0.211707,-0.101265,0.049714,-0.708809,0.061230,-0.190387,0.010189,-0.618047,0.224181,-0.406073,0.298230,0.029547,-0.471028,0.481418,0.426390,0.527354,0.478138,-0.324407,-0.185372,-0.347920,0.224430,0.680698,-0.277992,-0.142171,0.415865,-0.104581,-0.288295,-0.010200,-0.214320,-0.311605,0.464882,0.438820,0.025396,-0.267885,0.202377,-0.256627,-0.286598,-0.551844,0.059567,-0.145596,-0.273456,-0.320272,-0.247297,-0.157039,-0.235639,-0.345937,-0.032856,-0.191882,-0.377658,0.452109,-0.593099,0.367147,0.569786,0.149093,-0.285844,0.621485,0.028783,0.101791,-0.226064,0.222344,0.099376,0.199759,0.346679,0.230536,0.167096,0.173460,-0.203769,-0.290010,0.340428', '1292584', '1309069', '1293142', '1805685');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294194', '悲情城市', '剧情', '普通人的命运在轰轰烈烈的时代面前总是渺小到可以忽略不计。个人，如果勇敢地站出来想阻止时代洪流，多少像奋力扑向风车的唐吉坷德，往往只能当殉道者，而更多时候，个人甚至连选择当旁观者的权利也没有。可是普通人的悲剧，无疑能照出历史的荒谬与残忍。1945年日本无条件投降后台湾光复，基隆一户林姓人家眼见也要过上好日子，但人算不如天算，林家大小波折从此不断。“二•二八”事件发生后，家中的四兄弟更是只剩下老老实实开有一家照相馆的聋哑人老四林文清（梁朝伟）。然而悲剧并没到此终止，因为和进步人士有联系，林文清也没能逃脱被逮捕的命运，到此，林家男子只剩林文清和吴宽美（辛树芬）的幼儿——他尚呆在襁褓中咿呀咿呀地学语。©豆瓣', '梁朝伟', '侯孝贤', 8.9, 74789, 'tt0096908', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501579996.jpg', 0.2, 0.6, 7.8, 34.9, 56.5, '0.218084,0.102694,-0.759218,0.175112,-0.025657,-0.213248,0.688028,0.059381,-0.424451,-0.155505,-0.064404,0.592067,-0.144197,0.262226,0.053385,-0.306466,-0.034781,-0.691939,-0.133068,0.015706,-0.328519,-0.563982,-0.038192,-0.356956,-0.331891,0.168030,0.396114,0.252244,-0.044906,0.249097,0.326157,0.090237,-0.230807,0.383453,-0.380573,0.052725,-0.166772,0.509692,-0.297426,0.127517,0.037178,-0.118339,-0.204032,0.047863,-0.114596,0.321855,0.341808,-0.465666,-0.184305,-0.070661,0.276993,-0.128258,-0.323800,0.345729,0.276552,-0.183074,0.300452,0.065364,0.125852,0.014885,-0.016435,0.028397,-0.646928,0.072712,0.162905,0.117204,-0.510696,0.327090,0.130027,-0.086464,0.011570,-0.401207,0.061284,0.205719,0.267161,0.340567,-0.449536,0.082523,-0.577100,0.074134,0.662076,0.327296,-0.621931,0.275142,0.068345,-0.342986,-0.144778,-0.495322,-0.291632,0.073218,0.139618,0.242506,-0.214198,0.145040,-0.427286,0.182689,-0.169927,-0.019586,0.034536,-0.349524,-0.017043,-0.217683,0.155239,-0.350970,-0.530704,0.335571,0.203985,-0.340589,0.803272,-0.481000,0.155673,0.409871,0.427906,-0.337725,0.674290,0.157098,0.117012,0.086315,0.136447,0.105834,0.053661,0.333106,0.246083,0.051173,-0.136058,-0.256310,-0.083076,0.377706', '1306530', '30162520', '1291577', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294202', '夺金三王', '喜剧', '海湾战争终于结束了。三个好兄弟阿奇（乔治·克鲁尼 George Clooney 饰）、特洛伊（马克·沃尔伯格 Mark Wahlberg 饰）和埃尔金（艾斯·库珀 Ice Cube 饰）准备在退役前结结实实捞上一笔，那样他们退役后就能舒舒服服地享受人生了。可不要以为他们 在异想天开，其实他们早就在伊拉克听到坊间传闻：总统萨达姆暗中收藏了一批从科威特偷来的黄金在他的秘密碉堡内。恰巧兄弟三人从伊拉克的一名战俘的屁眼处发现了一张萨达姆秘密碉堡的地图，于是三人经过准备，往夺宝之路进发……©豆瓣', '乔治·克鲁尼', '大卫·O·拉塞尔', 7, 7375, 'tt0120188', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p734299273.jpg', 0.9, 5.5, 45, 39.7, 8.9, '0.253049,-0.012768,-0.757870,0.466413,0.124455,-0.696616,0.634036,0.026160,-0.431227,0.036695,0.096632,0.608374,-0.224198,-0.001175,0.374354,0.095170,-0.745937,-0.644025,-0.082605,-0.565403,-0.449346,-0.417396,-0.205182,-0.406414,-0.150456,-0.100004,0.472793,-0.073668,0.087409,0.215404,0.268491,0.218776,-0.009878,0.230641,-0.343482,0.003843,0.376913,-0.115391,-0.504927,0.216693,0.011142,-0.150348,-0.068593,-0.032569,0.307542,0.073749,0.558352,-0.374974,0.134959,0.177161,-0.161562,0.018795,0.057726,0.285888,0.291770,0.052882,0.289230,0.107607,-0.090050,0.171013,0.142071,-0.285295,-0.370903,-0.150821,-0.458701,0.143613,-0.506329,0.603943,-0.201027,0.354545,0.062615,-0.568337,0.216142,0.558982,0.069455,0.137115,-0.213914,-0.005461,-0.596128,0.076499,0.408666,-0.255419,0.209325,0.313052,0.435347,-0.440545,0.040531,0.365327,-0.146799,-0.199698,0.833095,-0.350331,-0.078869,0.101516,-0.670114,-0.036638,-0.339941,-0.324662,0.043488,-0.112602,-0.153001,-0.583718,-0.088616,-0.027925,-0.257694,0.419070,0.095308,0.168446,0.573367,-0.473091,0.309479,0.397969,-0.046274,-0.199984,0.339886,-0.172834,0.268989,-0.091694,0.008647,0.054113,0.246869,0.440174,0.450322,0.513334,-0.126644,-0.475539,-0.204430,0.385098', '1410557', '21349734', '1316560', '1296909');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294227', '龙在天涯', '动作', '中国武术队赴三藩市表演，武术冠军李国南（李连杰 饰）博得满堂喝彩，台下观众席上的阿友（周星驰 饰）大为敬佩。武术团成员王威（狄威 饰）自感年纪渐大，前途黯淡心中苦闷，在武术团登机回国之时，王威离队留美，国南出面挽留，反而也被滞留美国。王威在机场脱身时袭警，连累国南被警方逮捕，面临牢狱之灾。经亲戚阿平介绍，王威加入了黑帮华人头目马科一伙，而此时，国南趁警车遭遇车祸，奋力逃脱。国南想从阿平处打听王威下落，后者却因卷入帮派仇杀身亡，由越南赴美的阿平姐姐阿玲（利智 饰）自此失去依靠。王威在帮派中做大，独当一面，阿玲则为了生存做了马科的情人，此时国南寄宿在阿友的小店中谋生并寻找回国的机会。王威的毒品在混战中被阿友拾走，这群流落异乡的华人的命运，因此又联系到了一起……©豆瓣', '李连杰', '邓衍成', 6.5, 12825, 'tt0095542', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167152154.jpg', 1.3, 9.8, 58.8, 21.1, 9, '0.106652,0.041235,-0.599272,0.143359,0.044751,-0.221585,0.372577,0.174094,-0.326266,-0.238375,0.144284,0.624245,-0.034563,0.139703,0.100243,-0.568045,-0.196785,-0.636033,0.060595,-0.054106,-0.016639,-0.222228,0.008069,-0.077117,-0.204212,0.002643,0.553938,0.155780,-0.304930,0.809156,0.243657,0.302824,-0.293598,0.416622,0.088121,0.052499,0.132560,0.057578,-0.283118,0.215977,-0.217864,-0.450758,-0.114796,-0.140764,0.148744,0.332528,0.649191,0.170787,0.169119,-0.388014,0.110371,-0.234205,-0.053876,-0.035253,0.505239,0.044321,-0.055394,0.137379,-0.153383,-0.033274,0.004228,0.108865,-0.467636,0.318713,0.256742,0.049156,-0.556789,0.231312,-0.098197,-0.097239,-0.023917,-0.122088,0.388748,0.490080,0.196640,0.067756,0.052215,0.233990,-0.300257,0.238796,0.712139,-0.306273,0.241390,-0.327967,-0.035853,-0.302752,0.320082,-0.093794,-0.058946,-0.167014,0.395604,-0.141295,-0.020950,0.106218,-0.216378,0.084267,-0.186015,-0.084602,-0.176845,-0.155636,0.119235,-0.778538,-0.006298,0.153133,-0.092279,0.184274,0.188104,-0.075055,0.544297,-0.456401,0.020317,0.474565,0.411637,-0.582027,0.403241,0.183749,0.288350,-0.253433,-0.217689,0.370072,0.157797,0.212081,0.064379,-0.012487,-0.413187,-0.254095,-0.119158,-0.065723', '1451563', '26365262', '26991880', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294240', '教父3', '剧情', '转眼间已经是1979年，第二代教父麦克•柯里昂（阿尔•帕西诺 饰）到了垂暮之年，为了灵魂的救赎，麦克慢慢结束家族的黑道事业，转投正当生意。麦克的儿子托尼酷爱艺术，无意接手家族事业，迈克尔决定让大哥逊尼的私生子，火爆好色的文森（安迪•加西亚 饰）继承家业，当第三代教父。麦克的爱女玛丽（索菲娅•科波拉 饰）和文森相恋，遭到父亲的反对，父女渐渐疏远。为了使家族资产合法化，麦克通过在梵蒂冈教廷的关系网，准备投资“屹立”集团，却遭到敌人的暗中阻挠，教皇的去世也让事情更加扑朔迷离。麦克无奈之下，只能重新选择用暴力解决问题，他的亲人也被卷入了这场血雨腥风。©豆瓣', '阿尔·帕西诺', '弗朗西斯·福特·科波拉', 9, 343277, 'tt0099674', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2169664351.jpg', 0.2, 0.5, 7.5, 32.9, 58.9, '-0.061294,0.312468,-0.397439,0.502938,0.036002,-0.472450,0.237405,0.472263,-0.586924,-0.430196,0.112459,0.800307,0.165532,0.184144,0.402140,-0.073991,-0.396560,-0.707804,0.070347,0.093634,0.043582,-0.631013,-0.027137,-0.448000,-0.149830,-0.321616,0.666049,0.096798,-0.207148,0.370500,0.365329,0.535179,0.072499,0.218595,0.182282,0.005498,0.276103,-0.155600,-0.782149,0.032442,0.091669,-0.099471,-0.049322,0.195336,0.174059,0.410197,0.212000,-0.050220,0.253336,-0.250081,0.267003,-0.275950,-0.044030,0.036290,0.594222,-0.184905,-0.083980,0.591672,-0.224215,-0.290967,0.063879,-0.157196,-0.942294,0.074475,0.183560,0.008516,-0.539032,0.197133,-0.226846,0.076904,-0.003776,-0.125650,-0.021172,0.516025,0.417977,0.272918,-0.115571,0.457105,-0.336986,-0.064037,0.540401,-0.095909,-0.103308,0.083673,-0.062784,-0.156267,-0.050986,-0.614728,-0.463822,-0.225665,0.663224,-0.066412,0.212624,0.760645,-0.570462,-0.428865,-0.365068,-0.209320,0.518690,-0.505349,0.210553,-0.466518,-0.419899,0.054169,-0.062841,-0.022186,-0.121918,-0.312363,0.508884,-0.487708,0.201435,0.432620,0.224759,-0.532857,0.327794,-0.034607,0.264024,-0.469080,-0.266456,0.440196,0.324422,0.055074,0.241626,-0.129718,0.272401,-0.227063,0.084083,0.331496', '26678784', '1482099', '27056396', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294244', '绅士爱美人', '剧情', '罗丽拉（玛丽莲·梦露 Marilyn Monroe 饰）和桃乐西（简·拉塞尔 Jane Russell 饰）是舞台上的好搭档，生活中的好伙伴。艳光四射的两人走在一起，吸引了无数男人的目光，然而，她们并非空有一副好皮囊，论智商，罗丽拉和桃乐西可不输给任何人。某日，罗丽拉登上了驶往法国的轮船，前去和情人艾仕文（埃利奥特·里德 Elliott Reid 饰）结婚，在船上，两人遇见了一名为古斯（托米·努南 Tommy Noonan 饰）的男子。原来，古斯是艾仕文父亲派来的私家侦探，为的是考验罗丽拉对自己儿子的真心。随着时间的推移，桃乐西竟然慢慢爱上了善良的古斯，但罗丽拉很显然帮自己的好闺蜜相中了另一位“金龟婿”。©豆瓣', '简·拉塞尔', '霍华德·霍克斯', 7.9, 8004, 'tt0045810', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1656726239.jpg', 0.3, 2.1, 24.9, 47.9, 24.8, '0.303130,-0.126805,-0.554172,0.623452,-0.437258,-0.438684,0.769802,0.165802,-0.358745,-0.148581,0.070240,0.916816,-0.161214,0.063411,0.478446,0.264640,-0.332187,-0.809970,-0.160578,-0.207935,-0.379875,-0.401878,-0.382856,0.030568,-0.140007,-0.281249,0.561404,-0.177084,0.228714,0.613857,0.460599,0.229648,0.022625,0.335705,-0.371493,0.017370,0.104075,0.082080,-0.086712,0.200082,-0.080184,-0.039414,0.068443,0.045837,0.027015,0.056653,0.583497,-0.171242,0.111228,-0.137907,0.071339,-0.187747,0.253108,0.045831,0.127483,-0.111841,0.348844,0.180448,-0.176131,-0.159622,0.063764,-0.052757,-0.442602,0.174865,0.204154,-0.093122,-0.711375,0.428478,-0.102759,-0.335593,0.110706,-0.308682,0.205421,0.236913,0.137048,0.302560,-0.142515,0.014991,-0.561487,0.056855,0.568205,0.544289,-0.012811,0.284078,-0.013533,-0.289170,-0.040281,-0.080966,-0.472778,-0.019092,0.340455,-0.018622,0.018241,0.071645,-0.613659,-0.049425,-0.279920,0.066130,0.026326,-0.710871,-0.094169,-0.588943,-0.234296,-0.688718,-0.190506,-0.050273,-0.057723,-0.320015,0.822331,-0.810095,0.085636,0.253849,0.306216,-0.361661,0.803677,0.150964,0.157106,-0.294674,-0.225929,0.126560,0.052959,0.051224,0.061901,0.298321,-0.200111,-0.063931,-0.474952,0.547686', '30162520', '1292720', '35048413', '26958479');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294251', '龙的心', '喜剧', '阿泰（成龙 饰）自小就志愿当一名无拘无束的海员，可惜哥哥嘟嘟（洪金宝 饰）天生智力障碍，自幼就和嘟嘟相依为命的阿泰为了照顾哥哥，一直没有实现心中梦想，当上了一名普通的警察。可是阿泰在警局过得并不快乐，天性无拘无束的他极不受上司欢迎。终于在一次和上司顶撞后，阿泰愤然辞职，决定去当海员。看到阿泰辞职，嘟嘟以为弟弟准备抛弃他了，开始自己试着去自力更生。一天，他和邻家小孩玩游戏时，意外捡到了劫匪留下的珠宝。邻家小孩的哥哥贪财，将嘟嘟推下了山边，抢走了珠宝，岂料此时劫匪返回，将他杀了。这时，阿泰闻讯赶来，一番打斗后将劫匪杀了，在山边救回了嘟嘟。阿泰亦因杀了人免不了牢狱之灾……©豆瓣', '成龙', '洪金宝', 7.3, 18481, 'tt0091427', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204668229.jpg', 0.5, 3, 40, 41.7, 14.9, '0.109601,0.017362,-0.569916,0.237367,-0.456361,-0.541137,0.694406,0.253991,-0.345366,-0.011898,-0.006528,0.687095,0.002718,0.439618,0.310085,-0.053767,-0.172989,-0.451884,-0.025555,-0.151853,-0.144836,-0.326168,-0.037000,-0.061474,-0.124345,-0.322716,0.548440,-0.286167,-0.070570,0.591527,0.222543,0.036662,-0.020228,0.490708,-0.418984,0.248388,0.028935,0.152404,-0.183527,0.095156,0.089370,-0.077395,0.073460,0.065894,0.113560,0.238946,0.552285,-0.235760,-0.108223,-0.317391,0.181281,-0.279098,0.109538,0.167713,0.330594,-0.009180,0.272088,0.004245,-0.259696,0.105861,0.069338,-0.288814,-0.230440,-0.021082,0.091762,-0.217131,-0.636611,0.322380,-0.144789,0.095658,0.297954,-0.437252,0.259332,0.352875,-0.036334,0.447417,-0.199821,0.373941,-0.475520,0.155586,0.820007,-0.155834,0.388153,0.366258,0.230774,-0.204295,0.332030,-0.258473,-0.436680,-0.009291,0.496473,0.052501,-0.516639,-0.215002,-0.252053,-0.138388,-0.118054,0.053039,0.010117,-0.527680,-0.093617,-0.084430,0.225123,-0.209935,-0.146639,0.119779,-0.037598,-0.185570,0.667072,-0.890147,0.258830,0.530846,0.298251,-0.444866,0.530710,0.034887,0.135216,-0.119758,0.293847,0.046056,0.363108,0.378116,0.312003,0.299308,-0.147591,-0.153971,-0.074593,0.336747', '1292219', '35030151', '1308755', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294252', '雾中风景', '剧情', '为了寻找从未谋面但常常出现在梦中的爸爸，Alexandros（Michalis Zeke 饰）在与精神病人海鸥（Ilias Logothetis 饰）告别之后，跟着姐姐Voula（Tania Palaiologou 饰）混上了去德国的火车。他们被交给警察，在见了舅舅（Dimitris Kaberidis 饰）一面后，又趁着大雪从警局逃跑。他们看着一匹马在眼前死掉，Alexandros痛哭流涕。他们结识了演员Orestis（Stratos Tzortzoglou 饰）和他的剧团，度过了愉快的时光。在大雨中，他们搭上了一辆卡车，为此Voula付出了被司机（Vasilis Kolovos 饰）强奸的代价。重逢的Orestis将他们送至车站，Voula却不忍与其分离。但当看到Orestis与他人（Socrates Alafouzos 饰）勾搭时，Voula带着破碎的心离开了。在车站，Voula走向一名候车的士兵（Gerasimos Skiadaressis 饰），打算用最快捷的方式挣到385块……', '米哈利斯·齐克', '西奥·安哲罗普洛斯', 9, 40269, 'tt0096288', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1117765592.jpg', 0.4, 0.8, 7.4, 32, 59.4, '0.192075,-0.006539,-0.689320,0.452370,-0.172068,-0.591381,0.966255,0.234656,-0.396190,-0.023114,0.246542,0.855744,-0.240148,0.147610,0.384925,-0.271285,-0.436698,-0.673417,0.068349,-0.143010,-0.492196,-0.224889,0.031611,-0.140649,-0.056677,-0.264389,0.648055,0.202003,0.208228,0.792061,0.383471,0.054587,-0.310141,0.634562,-0.592074,-0.050629,-0.163184,0.199521,-0.276094,0.280347,0.043992,-0.529509,-0.123266,-0.239965,-0.077920,0.099380,1.005250,-0.280511,-0.012922,0.145168,0.002553,-0.361179,0.218708,0.186110,0.035421,0.200637,0.065209,0.060152,-0.489198,0.157418,0.273001,0.032804,-0.536757,0.177300,-0.113105,0.037852,-1.029835,0.537256,-0.150995,0.018017,0.328510,-0.463611,0.547924,0.364055,0.145985,0.430473,-0.347038,-0.109618,-0.751660,0.311659,0.729874,-0.224470,0.232003,0.537478,0.042184,-0.243461,0.031680,-0.087046,-0.337829,-0.140055,0.508230,-0.114573,-0.313429,-0.196253,-0.789477,-0.167729,-0.301166,-0.391048,-0.060770,-0.438824,-0.285894,-0.452140,0.148612,-0.384322,-0.281112,0.467684,-0.037822,-0.001347,0.523947,-0.747077,0.211060,0.435024,0.532275,-0.484453,0.996379,-0.107605,0.046927,-0.044372,0.043754,0.085125,0.080420,0.626666,0.349577,0.350239,-0.329442,0.039249,-0.482671,0.288886', '21619567', '1306505', '3055049', '1361252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294262', '的士速递', '喜剧', '丹尼尔（萨米·纳塞利）度过了披萨快递员的最后一天，做起了出租司机。然而在他看来，出租司机并不是他真正的职业，他是名真正的快车手。因为超车被罚，丹尼尔结识了警察艾米（佛瑞德瑞克·迪分索）。艾米考了八次驾照都没通过，工作里捅漏子，情场上没胆量，连烧水都能引起火灾，总之是个把一切都搞砸的笨蛋。此时艾米正为一伙德国劫匪头疼，丹尼尔为了要回驾照，只好帮艾米调查案件。事实证明他的快车天赋刚好派上用场，劫匪最终被他引入进退两难的陷阱。©豆瓣', '萨米·纳塞利', '吉拉尔·皮雷', 7.9, 78742, 'tt0152930', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529661798.jpg', 0.3, 1.7, 24.5, 52, 21.6, '0.487931,0.032018,-0.501200,0.114647,-0.413725,-0.372452,0.432940,-0.093716,-0.615223,-0.343320,0.221739,0.465710,0.048360,0.039259,0.309011,-0.005430,-0.323068,-0.350254,0.155993,-0.121696,-0.503805,-0.500650,-0.202925,0.002681,-0.279908,0.087113,0.141116,-0.058906,0.000907,-0.049823,0.273663,-0.058346,0.338855,0.468113,-0.136147,0.202451,0.267849,-0.425544,0.125455,0.217961,0.028724,-0.237489,-0.087712,0.205669,0.368899,0.408128,0.362890,0.031219,0.089392,-0.073707,0.029050,-0.374191,-0.135387,0.052300,0.086635,0.048179,0.229096,0.015060,-0.086436,-0.172753,0.262819,0.175365,-0.586790,0.110683,-0.361999,-0.091797,-0.548060,0.322078,-0.369946,0.134085,-0.158681,-0.316279,0.298544,0.102977,0.342306,0.225254,0.025795,-0.128037,-0.668589,0.095480,0.654795,0.130854,0.018030,0.437197,-0.056109,-0.288607,0.111529,-0.292750,-0.298791,0.226886,0.540884,-0.081459,-0.375448,-0.021108,-0.248646,-0.113854,-0.385277,-0.236427,-0.345687,-0.329686,-0.099741,-0.458586,0.253089,0.006536,-0.325375,-0.030272,0.071504,-0.187572,0.303897,-0.731988,0.011999,0.630056,0.074934,-0.235627,0.438853,0.089966,0.097452,-0.130162,-0.107595,-0.075402,0.165898,0.710024,0.251238,0.461094,0.151673,-0.550882,-0.038590,0.465523', '1301345', '1853752', '1308842', '1300359');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294276', '变种DNA', '剧情', '最近，在曼哈顿发生了一连串的离奇死亡事件，而这些事件的主要责任竟要归结到一对对此毫不知情的昆虫学家夫妇苏珊（米拉·索维诺 Mira Sorvino 饰）和皮特（杰瑞米·诺森 Jeremy Northam 饰）的身上。原来，为了抵抗曾经在曼哈顿肆虐的疫情，苏珊和皮特创造出了一种名为“犹大”的昆虫，这种人造昆虫没有繁殖的能力，却能够消灭病毒的携带体蟑螂。令两夫妇没有想到的是，在犹大的体内发生了未知的变异，使得它不仅拥有了繁殖后代的能力，甚至可以化身成人类的模样进行狩猎，而它们的猎物不是别人，正是人类本身。作为犹大的“父母”，苏珊和皮特义不容辞的担负起了消灭它们的责任，在地铁系统专家雷纳德（查尔斯·达顿 Charles S. Dutton 饰）的帮助下，一行人向着犹大在地下的老巢进发了。©豆瓣', '米拉·索维诺', '吉尔莫·德尔·托罗', 6.4, 6555, 'tt0119675', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1242448419.jpg', 1.9, 11, 56.2, 24.9, 6, '0.490683,-0.006078,-0.921658,0.614501,-0.292146,0.028606,0.869489,-0.021997,-0.470446,-0.322544,0.234996,0.612334,0.079836,-0.043000,0.033988,-0.227276,0.084737,-0.358380,-0.234216,0.001884,-0.485128,-0.538124,-0.563344,-0.413084,-0.036954,-0.602097,0.633434,0.147109,-0.315680,0.323779,0.277877,0.625725,-0.065924,0.332345,-0.321401,0.034938,-0.008023,-0.042573,-0.229323,0.440061,0.087476,-0.152576,0.039746,0.384584,-0.122879,0.212479,0.858937,-0.730880,-0.232693,-0.350967,0.327932,-0.525417,0.223835,0.063646,0.515503,-0.109894,0.165640,0.285841,0.011539,-0.061608,0.476355,0.161396,-1.256760,-0.271425,0.056680,0.461060,-0.526921,0.300190,-0.008714,-0.097819,0.135018,-0.464159,0.232032,0.477411,0.136599,0.554266,-0.145234,-0.078637,-0.804693,-0.080782,0.750424,-0.244394,-0.500957,0.447583,-0.450862,-0.471036,-0.314866,-0.242335,-0.279822,-0.036496,0.398020,0.369453,-0.274517,0.480451,-0.733308,-0.118537,-0.199548,-0.384089,-0.043849,-0.289130,-0.063549,-0.692385,-0.105778,-0.483298,-0.102237,0.034267,0.147012,-0.335247,0.615897,-1.022740,0.271809,0.624312,0.174494,-0.628774,0.372177,-0.045124,0.159138,-0.173228,-0.091073,0.169669,0.267993,0.347676,0.096068,0.342706,0.379277,-0.168232,-0.373594,0.540529', '1793491', '1308784', '3213270', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294279', '原振侠与卫斯理', '动作', '原振侠（钱小豪 饰）受警方所托，紧急介入一起人质绑架案件，女记者彩虹（张曼玉 饰）为得到第一手资料不惜打乱警方布置，幸而原振侠力挽狂澜，拯救行动圆满达成，但彩虹自此纠缠原振侠使其不胜厌烦。原振侠摆脱彩虹后在自己家中遇见一名泰国男子黑龙（狄威 饰），后者要求原振侠返回泰北，以解除他身上的血降。当夜原振侠身上血降爆发，他只得求助亦师亦友的卫斯理（周润发 饰）。原来一年前原振侠在泰国结识女子芭珠（崔秀丽 饰），芭珠所在蛊族的大巫师（徐锦江 饰）以芭珠作为祭神之礼，原振侠出面救出芭珠，两人终未能逃脱巫师魔掌，双双被下了降头，一年后降头发作，原振侠请求卫斯理和白素（胡慧中 饰）同赴泰国，芭珠男友黑龙亦出现相助原振侠解除降头之危……©豆瓣', '钱小豪', '蓝乃才', 6.4, 7279, 'tt0092273', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164764586.jpg', 2.3, 12, 55.4, 22.4, 7.9, '-0.019262,-0.036566,-0.266223,0.247006,0.181111,-0.059382,0.262548,-0.013831,-0.330589,-0.364270,0.460097,0.373698,-0.133761,0.128606,0.286686,-0.142704,-0.304004,-0.560662,0.236223,0.055645,-0.189373,-0.395149,-0.211431,0.071044,-0.237123,-0.255851,0.533966,0.042636,-0.218886,0.525331,0.342147,0.438013,-0.476495,0.175065,-0.031060,-0.027608,0.080978,0.031965,-0.431499,0.334000,-0.104266,-0.307906,-0.009718,0.200268,-0.112550,0.312477,0.375168,-0.379059,-0.062203,-0.356130,0.189529,-0.149615,0.017174,0.095558,0.168062,0.103132,0.085178,0.182659,-0.375898,-0.081261,0.146645,0.157154,-0.212659,0.301946,0.326757,-0.009728,-0.361162,-0.187876,-0.259715,0.135792,-0.137027,-0.378389,-0.155880,0.274146,0.364841,-0.095281,-0.144970,0.077844,-0.205816,0.278295,0.568463,-0.019853,0.022602,-0.267000,-0.143639,-0.542955,0.001065,0.068721,0.032055,0.172382,0.287996,0.202648,0.092336,0.139931,-0.268982,-0.660828,-0.654523,0.378947,0.034335,0.079330,0.064366,-0.711762,-0.095692,0.106994,-0.148929,-0.089866,0.305734,-0.283958,0.275086,-0.447769,0.211072,0.188914,0.341916,-0.320214,0.323253,0.117553,0.581212,-0.315963,-0.013571,0.279260,0.119531,0.224032,-0.043371,-0.191912,-0.113885,0.086075,-0.156667,-0.301723', '25723905', '2369613', '1293572', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294300', '曼哈顿', '剧情', '40岁的艾萨克·戴维斯（伍迪·艾伦 Woody Allen 饰）在写作上不算成功，在感情上更是一团糟。一方面，为了另一个女人而离开他的前妻吉尔（梅丽尔·斯特里普 Meryl Streep 饰）打算出版一本有关他们私密婚姻生活的书，另一方面，17岁的女孩翠西（玛瑞儿·海明 威 Mariel Hemingway 饰）对于这段他并不打算认真经营的感情投入了越来越多的热情。在这个节骨眼上，好友耶尔（迈克尔·莫菲Michael Murphy饰）的情人玛丽（黛安·基顿 Diane Keaton 饰）闯入了戴维斯的视线，风趣的谈吐，投机的话题，一切的一切都为两人的感情擦出了火花。3个男人，3个女人，在曼哈顿这个繁华又孤单的城市，这群成年人究竟该用何种方式来道德并公正的解决他们的感情问题呢？本片荣获1980年英国电影学院最佳影片奖。©豆瓣', '黛安·基顿', '伍迪·艾伦', 8.3, 36927, 'tt0079522', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1672087220.jpg', 0.2, 1, 14.4, 50.4, 34, '0.482482,0.134544,-0.671109,0.576235,-0.163572,-0.403209,0.745246,-0.014685,-0.276008,-0.393833,0.107795,0.661216,-0.118841,0.108933,0.203223,0.131166,-0.414654,-0.627563,0.054915,-0.300878,-0.188021,-0.736242,-0.447431,-0.173145,-0.283237,-0.101912,0.511541,-0.137508,0.039888,0.117610,0.399958,0.157426,0.155290,0.415202,0.035764,0.015778,0.060396,0.116808,-0.225314,0.028703,-0.012065,-0.224769,-0.193908,0.198174,-0.038084,0.225965,0.799409,-0.174600,-0.078501,0.244423,0.524169,-0.171198,0.008974,0.068096,0.222427,-0.330484,0.041794,0.168368,-0.250710,-0.123210,0.092644,-0.281627,-0.666623,0.008665,-0.132597,0.382851,-0.373075,0.609167,-0.268303,-0.099963,-0.090551,-0.434891,-0.151928,0.298017,0.284060,0.379679,-0.321400,0.055934,-0.112466,0.140698,0.464710,0.256251,-0.180885,0.488629,-0.538352,-0.523580,-0.286837,-0.192943,-0.454583,-0.171543,0.285307,-0.080048,-0.052362,0.349296,-0.538135,0.076171,-0.018737,0.049993,0.047695,-0.388285,-0.062510,-0.595630,-0.164094,-0.542943,-0.283787,-0.167752,0.115745,-0.126884,0.684355,-0.663426,-0.018618,0.609861,0.106686,-0.401975,0.598858,0.250172,0.114212,-0.319908,-0.515425,0.375049,0.018691,-0.061680,-0.070019,0.452217,0.136300,-0.075107,-0.147860,0.573697', '35158375', '1829230', '1309161', '