INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294315', '捆着我，绑着我', '剧情', '自三岁开始便在孤儿院生活的里奇（安东尼奥•班德拉斯），20几年来因为一直被困在精神病院和疗养院中，对外面的世界一无所知，十分单纯、直接、鲁莽。被精神病院的医生批准可以重返社会，过另一种生活后，里奇顿感生命火焰重新燃起，并在走出精神病院的大门后立即向自己一直钟爱的色情片女星玛丽亚（维托利亚•阿布里尔）示爱，他的示爱方式是将对方绑架起来，让对方在这段被囚禁的日子对他发生真正的感情，并要像“他爱她一样爱他”。©豆瓣', '维多利亚·阿夫里尔', '佩德罗·阿莫多瓦', 7.5, 24256, 'tt0101026', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1958677626.jpg', 0.6, 3.2, 32.2, 47.4, 16.5, '0.382661,0.250064,-0.848783,0.496124,-0.288251,0.078251,1.081661,-0.016228,-0.693148,-0.131221,-0.054435,0.982292,-0.165474,0.592779,0.158046,0.413490,-0.333032,-0.885151,-0.080713,-0.387457,-0.370897,-0.363670,0.156485,-0.241443,-0.124551,-0.443960,0.579114,-0.070324,-0.042555,0.193970,0.237318,0.376539,0.274755,0.710153,-0.290239,0.157703,-0.031967,0.053294,-0.355389,0.110427,0.267423,-0.225367,-0.239119,0.342421,-0.021387,-0.060091,0.584540,-0.166943,-0.095243,-0.208086,0.285831,-0.157579,-0.008761,0.185192,0.361394,-0.138536,0.098364,0.481491,-0.069458,0.313577,-0.033258,-0.214572,-0.580323,0.008297,-0.190328,0.007505,-0.560021,0.401876,0.045911,-0.044690,0.127207,-0.250406,-0.137741,0.232947,-0.020636,0.520404,-0.470539,-0.105519,-0.517258,0.146548,0.671494,-0.123854,-0.314936,0.686214,-0.318859,-0.433753,-0.180368,0.063126,-0.530381,-0.059054,0.371410,-0.008724,-0.565391,0.324889,-0.379528,0.101643,-0.259515,-0.268030,0.142584,-0.608751,-0.136525,-0.613889,-0.126490,-0.429363,-0.390378,-0.123830,-0.171226,-0.178012,0.421043,-1.003861,0.333590,0.671960,0.390206,-0.504439,0.616642,0.222549,-0.120298,-0.072870,0.083741,0.715161,0.193830,0.753846,0.233008,0.432407,0.257794,0.169485,-0.440264,0.742283', '1309172', '4275444', '1309080', '1908318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294323', '第一滴血', '剧情', '退伍军人兰博（西尔维斯特•史泰龙Sylvester Stallone 饰）从越南回国，他回到已显得陌生的原居小镇，当地警长（布莱恩•丹内利 Brian Dennehy 饰）看到这个退伍军人的第一眼起，就开始对兰博百般挑剔，甚至将他带回警局肆意侮辱，不堪忍受责打的兰博袭警之后逃跑。警长召集大批警察展开对兰博的追捕，兰博逃至荒山野林之中，不断用自己在越战中掌握的游击战术对警察展开反击，他抢劫了一辆武器运输车返回小镇烧毁了商店，法律和武器都不能阻止兰博了。兰博在越战时的长官上校（理查德•克里纳 Richard Crenna  饰）出现，劝说兰博放下枪械，愤懑已久的兰博吼出了自己的困惑与不甘……©豆瓣', '西尔维斯特·史泰龙', '特德·科特切夫', 8.3, 85660, 'tt0083944', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2485300934.jpg', 0.2, 0.9, 15.2, 50.4, 33.2, '0.521229,0.151012,-0.715331,0.385759,-0.075279,-0.251604,0.777670,-0.011753,-0.206713,-0.008228,0.598611,0.654062,-0.010617,0.020027,0.233253,-0.022320,-0.375903,-0.615316,0.003440,-0.183450,-0.189255,-0.420320,-0.306226,-0.340223,0.063658,-0.462041,0.413280,0.011172,-0.294668,0.582978,0.282014,0.239558,-0.064188,0.626206,-0.014583,0.026083,0.154660,-0.364269,-0.210824,0.122058,0.027530,-0.316761,-0.034780,0.092922,0.065483,0.385015,0.865573,-0.205522,0.006236,-0.023543,0.272491,-0.336448,-0.054432,0.128008,0.124388,-0.049859,-0.258634,-0.276915,-0.227708,0.245984,-0.071443,0.249117,-0.312211,0.031210,-0.407156,0.003537,-0.884495,0.297057,-0.571025,0.260733,0.061946,-0.430130,0.228831,0.040870,-0.133807,0.319064,-0.145179,-0.190414,-0.609760,0.127762,0.329226,-0.255120,-0.156493,-0.136758,-0.190168,-0.329358,0.114485,-0.168448,-0.411911,-0.549317,0.559308,-0.049012,-0.109054,0.060315,-0.562604,-0.143785,-0.355961,-0.117616,-0.130588,-0.118000,-0.427531,-0.777655,0.040598,-0.119851,-0.003402,0.150164,-0.006858,0.148544,0.358479,-0.624708,0.275826,0.233504,0.484235,-0.229549,0.262530,0.019371,0.121467,0.047485,-0.357431,0.162530,0.410162,0.725865,0.432221,0.358662,-0.190535,-0.349916,-0.035460,0.640191', '21619567', '3735015', '26951746', '1303462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294350', '最佳拍档4：千里救差婆', '喜剧', '纽西兰老科学家发明一个名为“天狼星”的三棱镜，它可将人的潜能激发，形成难以置信的超能力。但这项发明很快被当地一黑社会组织盯上，他们袭击实验室，杀害老科学家。危急时刻，天狼星被参加实验的青年金刚（许冠杰 饰）和科学家的女儿莎莉（叶倩文 饰）带出纽西兰，来到香港。返港后，金刚寻求侦探光头佬（麦嘉 饰）的帮助，谁知黑帮尾随而至，虏走光头佬的妻子贺警司（张艾嘉 饰）作人质。为救爱妻，光头佬带着儿子，协同金刚赶至纽西兰……©豆瓣', '许冠杰', '林岭东', 7, 10229, 'tt0092268', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2642861456.jpg', 0.8, 5.3, 48.1, 32.9, 12.9, '-0.131939,-0.412786,-0.386801,0.374607,-0.287951,-0.224752,0.426061,0.121457,-0.332989,-0.203810,0.392980,0.709837,-0.095371,0.090471,0.373658,0.029462,-0.109175,-0.406770,-0.163095,0.149963,-0.245339,-0.089416,-0.098542,-0.223683,-0.024728,-0.431886,0.457362,0.045584,-0.226878,0.567579,0.351288,0.403221,-0.228262,0.230216,-0.059448,0.092846,0.318960,-0.380391,-0.139343,0.340266,0.032655,-0.218771,0.158685,-0.110086,-0.469943,0.330985,0.549295,-0.301233,0.295032,-0.665639,0.263649,-0.429458,-0.193403,-0.008555,0.266325,0.193154,-0.055227,-0.032063,0.108948,-0.113382,0.302069,-0.159927,-0.495111,0.156680,0.250403,-0.092135,-0.480799,0.002270,-0.233421,0.215413,0.150872,-0.258388,0.171331,0.039660,0.184577,0.425459,0.045957,0.431691,-0.535247,0.241663,0.371982,-0.425452,0.026386,-0.115718,0.015479,-0.457536,0.065428,-0.397764,-0.119501,-0.125980,0.505790,-0.248677,-0.113218,-0.103275,-0.477621,-0.198891,-0.287289,0.228392,0.002604,-0.072858,-0.166495,-0.684357,0.166093,-0.167009,0.181950,0.150760,0.120265,0.080582,0.761121,-0.502025,0.143610,0.422447,0.287496,-0.385964,0.555845,-0.237247,-0.081959,-0.542205,-0.250515,0.025202,0.495193,0.403056,0.070891,0.242450,-0.133487,-0.370336,0.067190,-0.184062', '3811356', '2369613', '1302661', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294353', '兵人', '剧情', '未来世界，为了赢得星际战争，政府从新生儿中严格挑选一批人，从小就进行杀人训练，这些人没有家庭、感情，他们眼中只有杀戮，称为兵人。特德（库尔特•拉塞尔 Kurt Russell 饰）就是这群人中的佼佼者，他经历了数场星际大战，依然屹立不倒。这次政府采用新的基因技术，让婴儿在母体中就接受战争基因的改造，制造了一批改良后的兵人。为了测试效果，特德和另外两名伙伴被挑选和新兵人凯恩（贾森•斯科特•李 Jason Scott Lee 饰）进行一场较量，结果两名伙伴被打死，而特德因为昏迷被误认为死亡而逃过一劫。他和另外两个伙伴的尸体被扔到了一个垃圾星球。特德在那里遇到了被遗弃的平民，他麻木的心灵在这里滋生了友谊和爱情。当他准备在这里和心爱的女人幸福过活时，政府将这里当成了新兵人的训练场。新兵人们在这里的任务就是杀光所有生物。为心爱的人和伙伴们，特德毅然出战！©豆瓣', '库尔特·拉塞尔', '保罗·安德森', 7.1, 16691, 'tt0120157', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1659550365.jpg', 1.1, 6.6, 43.5, 35.4, 13.3, '0.107531,-0.127507,-0.695060,0.533377,-0.567735,-0.203617,0.826242,-0.173420,-0.493468,-0.216072,0.313690,0.871892,0.094163,0.141147,0.138287,-0.244844,-0.476560,-0.801516,-0.318133,-0.144288,-0.669626,-0.140554,-0.172757,-0.539915,-0.118761,-0.540469,0.982911,-0.039976,-0.260054,0.383219,0.068888,0.467994,-0.026799,0.335037,-0.304583,-0.034699,0.406685,-0.076082,-0.306106,0.277831,-0.363150,-0.080042,-0.156531,0.152526,0.012215,0.168558,0.848356,-0.389539,0.025414,-0.480384,0.000162,-0.518677,0.020736,0.106414,0.392438,-0.087902,0.226115,0.128917,0.044966,-0.005458,0.122014,-0.102253,-1.101719,-0.305093,-0.078047,-0.031499,-0.664989,0.641375,0.045080,0.119082,0.036553,-0.054565,0.416192,0.347097,0.278039,0.383205,-0.312591,-0.268142,-0.568973,0.360657,0.815810,-0.362117,-0.360636,0.165317,-0.377678,-0.599141,0.066152,-0.403289,-0.407670,-0.038764,0.482985,0.045636,-0.301084,0.257290,-0.836103,0.225898,-0.084336,-0.393179,0.005015,-0.441868,-0.031127,-0.724226,-0.087636,-0.265774,-0.455164,0.161105,0.061466,-0.191912,1.045340,-0.734416,0.190259,0.568552,0.405551,-0.642039,0.725142,-0.004584,0.362746,-0.244896,0.115538,-0.035564,0.183015,0.316619,0.311502,0.472825,-0.130218,0.285523,-0.362121,0.594827', '25928048', '2