INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294362', '星球大战前传1：幽灵的威胁', '动作', '作为星球大战前传系列的首部曲，这部电影诞生了一个重要的人物：阿纳金（杰克·洛伊德 Jake Lloyd  . 饰）。银河国会会议上出现了利益争执，纳布星的女王阿米达拉（娜塔丽·波特曼 Natalie Portman   饰）被贸易联盟绑架并威胁签署新的贸易协议。绝地武士奎刚（连姆·尼森 Liam Neeson 饰）及徒弟欧比-旺•肯诺比（伊万·麦克格雷格 Ewan McGregor  饰）受命前去解决纠纷，维护和平。他们的飞船在塔图因星意外降落的时候遇到了阿纳金并且带走了他。在奇异天才少年阿纳金等人的帮助下，奎刚及欧比-旺与贸易联盟的机器人部队和西斯武士展开了决斗.....©豆瓣', '连姆·尼森', '乔治·卢卡斯', 8.2, 115827, 'tt0120915', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2308392633.jpg', 0.3, 1.3, 17.6, 48.4, 32.3, '0.228654,0.212366,-0.664170,0.515546,0.293157,-0.023394,0.356052,0.398197,-0.051912,-0.213812,0.450394,0.775798,-0.094543,-0.326044,0.411111,0.083533,-0.734130,-0.475509,0.108832,-0.223173,-0.236856,-0.536416,-0.290241,-0.226541,-0.127112,-0.604662,0.668326,-0.097648,-0.139584,0.449241,0.312627,0.405620,-0.186957,0.278565,0.223499,0.146359,0.529142,-0.297078,-0.550164,0.361354,-0.338730,0.195841,-0.098082,0.066360,0.132273,0.512345,0.301853,-0.435769,0.157384,-0.413155,0.081708,-0.321034,0.158839,-0.096424,0.418101,-0.079929,-0.108867,0.361262,0.018724,-0.179527,0.050426,-0.228676,-0.713393,0.282320,0.061295,0.264314,-0.537995,0.312860,-0.512518,0.138117,0.038218,-0.041049,0.060069,0.744675,0.309965,0.073450,0.168830,0.202959,-0.456829,0.048447,0.276536,-0.097125,-0.309970,0.106702,0.021938,-0.600743,-0.269312,-0.154955,-0.205291,-0.104064,0.854177,-0.361005,0.249151,0.473098,-1.024845,-0.164385,-0.249825,-0.327492,0.235316,-0.109201,0.148005,-0.921851,0.033953,-0.054522,-0.279162,0.047990,0.001266,-0.023708,0.714732,-0.536087,0.177165,0.486903,0.604746,-0.259227,0.533713,-0.090124,0.193660,-0.278679,-0.090203,0.204101,0.281560,0.296023,0.346872,0.106290,0.265397,-0.261246,-0.085544,0.134641', '26290398', '20274039', '2075345', '1305096');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294364', '相见恨晚', '剧情', 'Laura（西莉亚·约翰逊 Celia Johnson 饰）的生活简单而幸福：有一个爱她的丈夫，一对可爱的儿女。每个周四她都习惯搭火车去附近的一个地方买东西。这天，在火车站旁的一间小餐厅，眼睛被吹进了沙子的她得到了医生Alec（特瑞沃·霍华德 Trevor Howard 饰）的帮助。几天后，她又在餐厅遇到了医生，由于桌子不够，两人便坐在一起吃饭，相谈甚欢。原来医生也已经结婚，每个星期二也来这里的本地医院帮忙。两人约定下星期再见面......频繁的见面和陪伴，让两个已经结了婚的人越来越渴望见到对方，他们知道，他们相爱了......但这样的爱情在那个年代注定无法长久，即使他们深爱着对方，最后也不得不分离。Alec告诉Laura，他即将去遥远的南非，留下了失魂落魄的Laura......本片改编自Noël Coward的独幕剧《Still Life》，获1946年戛纳电影节“金棕榈”大奖。', '西莉亚·约翰逊', '大卫·里恩', 8, 9038, 'tt0037558', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1089259330.jpg', 0.4, 1.5, 20.9, 51.8, 25.4, '0.349311,0.004417,-0.876091,0.378236,-0.166166,-0.364318,0.829229,0.247837,-0.151444,-0.126252,0.135396,0.929127,-0.113650,0.464241,0.089798,0.017964,-0.254256,-0.527375,0.279992,-0.284919,-0.422438,-0.280204,-0.086428,-0.148397,0.000380,0.087355,0.371084,0.043961,0.324933,0.745049,0.290502,-0.276380,0.050290,0.460683,-0.437728,-0.061757,0.139424,0.155734,-0.257582,0.215934,0.125834,0.049227,-0.177264,0.077514,0.126278,0.268131,0.537100,0.097654,-0.312091,0.200116,0.370933,-0.121052,-0.094893,0.186574,0.439449,-0.132423,0.252642,0.041454,-0.315759,-0.001800,-0.021988,0.194261,-0.642785,0.121134,-0.033920,0.028567,-0.648555,0.720197,0.152470,-0.157676,0.019487,-0.411165,0.367829,0.500712,0.086334,0.399793,-0.112299,-0.149439,-0.640954,0.034233,0.853466,-0.096946,-0.051557,0.554696,-0.254772,-0.407570,-0.014487,-0.125399,-0.594637,0.227294,0.231400,-0.150668,-0.417302,-0.137727,-0.490096,0.218934,-0.092345,-0.193178,0.061700,-0.473137,0.115534,-0.587565,-0.079258,-0.417022,-0.406741,0.320841,-0.010922,-0.149294,0.726559,-0.525391,0.272195,0.681278,0.507907,-0.527522,1.047220,0.313954,0.141034,-0.137354,0.048152,0.246794,-0.035007,0.326740,0.328645,0.549247,0.037255,0.375104,-0.558363,0.419263', '3055049'