INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294366', '霹雳五号', '喜剧', '《霹雳五号》是1986年由新力影业旗下子公司——三星影业所推出的科幻喜剧片。NOVA军火公司开发了五台战争用机器人，而其中一台机器人“No.5”有一天突然被雷打中，而之后便产生了自我意识，并且开始自称自己为“强尼五号”。它逃到了街上，却被人类视为一大威胁，而剩下四台机器人也在追杀它，它必须设法说服发明它的科学家“自己是一种生命，而不是战争用机器人”。在一次短路状况下闯入了热心保护动物的史蒂芬妮家中，并从与人交往的过程中学习到人类的智慧的人性，后来拒绝回到武器公司充当他们的杀人工具。©豆瓣', '艾丽·西蒂', '约翰·班德汉姆', 8.6, 13552, 'tt0091949', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1402862965.jpg', 0.3, 0.7, 12.3, 41.5, 45.2, '0.007008,0.239909,-0.606589,0.479480,-0.111915,-0.144141,0.676950,-0.063857,-0.428522,-0.296516,0.191141,0.502995,0.166718,0.120724,0.074642,-0.087697,-0.124558,-0.437384,-0.023970,0.010426,-0.510274,-0.276582,-0.225589,-0.602357,0.041530,-0.513772,0.772654,0.069856,-0.546492,0.021053,-0.064248,0.303866,-0.093021,0.477000,0.136617,-0.153954,0.071820,-0.098952,-0.315634,0.438854,-0.330245,-0.231903,-0.079747,0.203042,-0.297220,0.395181,0.601767,-0.420669,-0.030627,-0.464181,0.304936,-0.332206,-0.204461,-0.256321,0.347215,0.046177,0.056529,-0.120930,-0.172190,0.277274,0.128210,-0.067434,-1.010780,-0.266131,-0.380350,0.004770,-0.587975,0.251561,-0.118533,0.288886,-0.056427,-0.380056,0.174673,0.049127,0.328744,0.331782,-0.318811,0.105593,-0.639756,0.257689,0.669846,-0.358363,-0.448575,0.591328,0.022235,-0.443583,-0.282152,-0.398921,-0.180032,-0.262838,0.415293,0.250513,-0.262936,0.145814,-0.801088,0.062103,-0.259754,-0.265132,0.113431,-0.399464,0.201160,-0.704375,0.145715,-0.247589,-0.272666,-0.051716,0.391533,-0.271120,0.623761,-0.799180,0.048638,0.775308,0.303526,-0.517316,0.489973,-0.384613,-0.080585,-0.292477,-0.041300,0.022301,0.230224,0.409454,0.077806,0.154346,0.309092,-0.056279,-0.235208,0.457338', '1793491', '27009869', '1294893', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294371', '摩登时代', '剧情', '二十年代的美国处于经济萧条时期，失业率居高不下，工人受尽压榨，成为了大机器生产中的一颗螺丝钉。查理（查理·卓别林 Charles Chaplin 饰）就是一个底层市民，他在一个机器隆隆的厂房里日以继夜地工作，以赚取微薄的收入。重复繁重的工作压得他喘不过气，他把人们的鼻子当成螺丝钉来拧，卷入流水线机器的皮带里，令人苦笑不得。查理尽管贫穷，但却很善良。他在路上搭救了流浪女，和她一起生活，家里破烂却又温馨。每次身无分文的查理为了找到吃的，都会故意犯事，以便进入监牢。光景一时间有了好转，流浪女成了歌舞红星，然而好景太短暂了。©豆瓣', '查理·卓别林', '查理·卓别林', 9.3, 277816, 'tt0027977', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2263408369.jpg', 0.1, 0.2, 3.7, 25.3, 70.6, '0.078901,0.160213,-0.547159,0.306818,-0.215260,-0.412831,0.971782,0.230247,-0.478994,-0.064274,0.204543,0.505762,-0.107121,0.176288,0.064227,-0.022675,-0.367459,-0.458467,-0.052508,-0.054411,-0.127946,-0.065967,-0.290812,-0.325350,-0.350400,-0.149399,0.472908,0.110920,-0.179393,0.206102,-0.206727,0.054780,0.291385,0.358836,-0.373005,-0.074596,-0.025546,-0.113432,0.139423,-0.035572,-0.063509,-0.320795,0.035377,0.087400,0.197893,0.431161,0.611108,0.043737,-0.021322,-0.021221,0.328556,-0.150301,-0.346661,-0.014877,0.235450,0.171016,0.102684,-0.127150,-0.528749,0.255864,0.220796,-0.037414,-0.785990,-0.082310,-0.001393,0.142679,-0.602594,0.582099,0.033686,-0.052429,-0.192660,-0.357076,0.250860,0.054844,0.178068,0.695086,-0.184141,0.062087,-0.634225,0.434592,0.526974,-0.254466,-0.454035,0.311338,-0.403425,-0.329943,0.243167,-0.346551,-0.512346,-0.501257,0.153106,-0.079295,-0.456322,0.286474,-0.623614,0.227040,-0.165221,-0.472099,-0.103275,-0.279898,-0.316045,-0.574419,-0.006053,-0.655394,-0.071670,0.002143,0.087880,-0.308071,0.529285,-0.549917,-0.009056,0.553535,0.032514,-0.193931,0.490775,0.064272,0.294457,0.188759,0.005536,-0.059207,-0.183341,0.466560,0.307589,0.237577,-0.153777,-0.276464,-0.340728,0.430621', '21619567', '1293515', '1419992', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294379', '七年之痒', '喜剧', '妻子度假期间，丈夫理查德·沙尔曼（汤姆·伊威尔 Tom Ewell 饰）因为一次花盆事件，结识了三楼邻居、电视广告明星（玛丽莲·梦露 Marilyn Monroe 饰）。对方如洋娃娃般的美貌，令这个已婚男人为之倾倒，并且在一次酒会上，在她弹钢琴的时候，坐在她的 旁边，作出了不雅的举动。事后，汤姆陷入了深深的懊恼之中，他求教于心理医生，对方指出他的病症，引诱他付高价诊治。汤姆没有理会，开始自己的心理分析，并对此事做出了一系列添油加醋的幻想。他担心这个八卦会传到妻子耳中，这种担心逐渐转向了对后者出轨的怀疑。于是，汤姆在性幻想的左右下，约了这个女孩一起看电影，并请她来家中做客。后者因为家里的电扇不制冷而贪恋他家的空调，因此希望来这里过夜，结果闹出不少笑话……©豆瓣', '玛丽莲·梦露', '比利·怀尔德', 7.5, 25631, 'tt0048605', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p537551220.jpg', 0.5, 3.2, 34.6, 45.4, 16.2, '0.507011,0.118544,-0.723053,0.431916,-0.289846,-0.130319,0.787863,0.161840,-0.527241,-0.288694,0.184157,0.748682,-0.387128,0.367076,0.144523,0.058593,-0.263969,-0.735655,-0.044564,0.020902,-0.304232,-0.391081,-0.061849,-0.421250,-0.162437,-0.011483,0.142599,-0.142685,-0.358356,0.461134,0.214161,0.314028,0.273175,0.679339,0.060420,0.079868,-0.042245,0.022621,0.041131,0.385671,0.210090,-0.353128,0.042670,0.432372,-0.083876,0.531841,0.639072,-0.238107,-0.342297,-0.060747,0.457063,-0.122283,0.163321,0.193456,0.202803,-0.092684,0.282366,-0.098066,-0.331894,-0.085526,-0.001356,0.196884,-0.494806,0.006583,-0.164325,0.294032,-0.519604,0.332549,-0.203790,0.004664,0.048342,-0.150503,0.279989,0.212437,0.260729,0.205732,-0.278860,0.014677,-0.278984,0.184768,0.303751,0.303103,0.042121,0.575129,-0.353039,-0.169533,0.156449,-0.048859,-0.569682,-0.003714,0.271995,0.021761,-0.185385,0.110057,-0.203610,-0.283252,-0.145188,-0.219003,-0.044075,-0.316636,-0.125115,-0.526972,-0.066206,-0.284293,-0.333445,-0.331218,0.124450,-0.245568,0.313884,-0.759188,0.098938,0.656353,0.209800,-0.522022,0.701220,0.029922,0.012945,-0.053040,-0.117115,0.103618,-0.125132,0.154255,0.003487,0.370348,0.238114,-0.236614,-0.509246,0.323842', '1309172', '1309080', '3059036', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294383', '疯狂的麦克斯3', '动作', '麦斯抵达巴顿镇，凭着一身好本领，被女皇聘为雇佣兵，消灭操纵地下世界的智武者。麦斯却被女皇的左右手巴斯逐出沙漠。一群居住在世外桃源的野孩子奉麦斯为神，带领他们走出沙漠，几个孩子为了理想，毅然奔向巴顿镇，麦斯为救他们，再入虎穴。', '梅尔·吉布森', '乔治·米勒', 6.7, 14035, 'tt0089530', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2250241779.jpg', 1.7, 10, 49.5, 28.2, 10.5, '0.104456,0.279149,-0.591987,0.332834,-0.189030,-0.089719,0.503835,0.164206,-0.322806,-0.362199,0.405886,0.696947,0.296834,-0.199628,0.497101,-0.085406,-0.261105,-0.429412,-0.219114,-0.459977,-0.260910,0.166058,-0.062729,-0.432064,-0.157181,-0.554777,0.875459,0.317576,-0.087892,0.254590,0.027910,0.235025,-0.494622,-0.160220,-0.399224,0.074184,0.256298,-0.247568,-0.180257,0.770886,-0.624221,0.304855,-0.144444,-0.042769,0.038582,0.033274,0.617432,-0.450542,0.119932,-0.298113,-0.344537,-0.711602,-0.182408,0.044798,0.371860,-0.757145,-0.084030,0.175437,0.094895,-0.206153,-0.226322,-0.282570,-0.527244,-0.109067,0.215955,-0.193431,-0.819670,0.211527,0.068939,-0.229141,-0.137320,-0.061946,-0.064364,0.021153,-0.202844,0.708559,0.080946,0.117024,-0.480948,-0.146684,0.742370,-0.444461,-0.195223,-0.286973,0.184674,-0.201331,0.130879,-0.263465,-0.167515,-0.226024,0.647554,-0.281256,0.062787,0.063512,-0.528807,-0.066380,-0.879428,0.002661,0.069092,-0.377859,0.046434,-0.533143,0.422360,0.265990,-0.099772,0.185692,0.060409,0.139131,0.237561,-0.427644,0.429311,0.304469,0.440886,-0.433402,0.606294,-0.504362,0.261129,-0.612710,0.035843,0.705208,0.805451,0.750068,0.074365,0.249923,-0.440884,-0.162390,-0.482519,0.145524', '3929463', '7051375', '21619567', '30299515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294387', '疾走天堂', '剧情', '菲莉芭（凯特 布兰切特 Cate Blanchett 饰）为了替家人复仇，自制了定时炸弹，偷偷安放在毒贩的办公室内，并支开了不知情的女秘书。然而，不幸还是发生了。由于清洁工打扫，她并没有将仇人炸死，反而连累了4条无辜的生命。菲莉芭以为大仇得报，所以在被警方逮捕后，供认不 讳， 毫无悔意。由于她坚持用英文，所以警局的书记员菲利普（吉尔瓦尼 雷比西 Giovanni Ribisi 饰）自愿做了翻译。在警方的严厉审讯中，她才了解真相，为此痛苦不已。菲利普也从中了解了她的身世遭遇：她曾给意大利警局不断写信，然而却石沉大海，因此她怀疑警局内也有人参与贩毒，知情人甚至要将她灭口。这时，菲利普偷偷地帮助她逃离了警察局，两个人在患难中建立了真挚的感情，并肩作战……©豆瓣', '凯特·布兰切特', '汤姆·提克威', 7.7, 14792, 'tt0246677', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p545988743.jpg', 0.6, 3.1, 27.6, 46.6, 22.1, '0.305987,0.015332,-0.704294,0.392460,-0.075164,-0.271649,0.736942,-0.074628,-0.466872,-0.174596,0.076165,0.395425,-0.075429,0.083155,0.066116,-0.008424,-0.563012,-0.650573,0.097416,-0.214461,-0.306752,-0.810305,-0.189931,-0.448446,-0.096972,-0.142910,0.163253,0.047305,-0.105911,0.314217,0.152117,0.250140,-0.119875,0.656792,0.165106,0.062817,0.275793,-0.096575,-0.082936,0.017775,0.125286,-0.498537,-0.031136,0.418326,0.268117,0.679167,0.442795,-0.225638,-0.206969,-0.016500,0.196371,-0.433192,0.173511,0.248284,0.214405,-0.036063,0.009193,0.387197,-0.359981,-0.135671,0.148281,0.078577,-0.810062,0.035827,0.033163,0.078711,-0.518124,0.339815,-0.364323,0.315236,0.077224,-0.093338,0.372529,0.347658,0.212013,0.075058,-0.158612,-0.082885,-0.448147,0.120377,0.630067,-0.232696,0.041973,0.149848,-0.356840,-0.287855,0.114681,0.039029,-0.478120,0.100641,0.348711,0.112564,-0.287809,0.117007,-0.099909,-0.448031,-0.564530,-0.092845,-0.202950,-0.421768,-0.031268,-0.477193,-0.158809,-0.203335,-0.482895,-0.243284,-0.004219,-0.244376,0.365763,-0.582075,0.324159,0.836270,0.417595,-0.476190,0.478138,0.074849,0.133459,-0.049440,-0.101999,0.278699,0.384292,0.449579,0.440432,0.235176,0.068656,-0.255362,-0.261205,0.129055', '35073886', '1307442', '25862560', '1293434');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294395', '007之太空城', '动作', '从美国运送英国太空船半途失去了行踪，这引起了美英两国的高度重视，于是英国军方派出了007邦德（罗杰•摩尔 Roger Moore 饰）前去追查。经过调查，007发现了这件事背后后隐藏的另一个阴谋。世界上某个组织正在在制造一种神经麻痹气体，该气体是由一种极稀有的尼格拉兰花提取出来的；当邦德在这种兰花的产地详细调查后，一个足以震惊世界的大阴谋浮出了水面。原来，该组织已经在太空中建立了一个太空城，为了称霸世界，他们准备从太空城中发射50个自行研制毒气弹袭击地球上的50个大城市。邦德发现他们的阴谋后，准备飞上太空阻止他们这个疯狂的计划！©豆瓣', '罗杰·摩尔', '刘易斯·吉尔伯特', 7, 9796, 'tt0079574', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1735176215.jpg', 1, 5.6, 49.3, 32.8, 11.2, '0.371459,0.208661,-0.822562,0.641923,0.096207,0.063557,0.582252,-0.076526,-0.410126,-0.100254,0.079921,0.748071,-0.124753,-0.096067,0.099198,0.179667,-0.668552,-0.485070,-0.171243,-0.502850,-0.692733,-0.404170,-0.570002,-0.361118,0.101946,0.018379,0.488494,0.188904,-0.353723,0.383168,0.055756,0.528674,-0.018139,0.433429,-0.048378,-0.238983,0.285418,-0.210707,0.019717,0.324461,-0.149707,-0.136335,0.080098,0.254038,-0.127559,0.486000,0.618302,-0.230001,-0.041641,-0.464260,0.327063,-0.366425,0.214200,-0.162348,0.439898,0.166834,-0.384573,0.077705,-0.329104,-0.060847,0.123822,0.045943,-0.970598,-0.170623,-0.141350,0.236517,-0.406023,-0.144777,-0.112188,-0.009953,-0.036071,-0.311341,0.336680,0.891635,0.232835,-0.088226,-0.193446,0.156068,-0.646211,0.022577,0.572750,-0.361313,-0.321423,0.328603,-0.009966,-0.282467,-0.073692,0.124512,-0.045763,-0.417392,0.447783,0.012781,-0.202540,0.143628,-0.699557,0.022449,-0.329097,-0.423890,-0.079961,-0.080824,-0.181879,-0.701450,-0.517449,-0.087099,-0.359271,0.068166,0.042573,0.392356,0.606160,-0.524439,0.181594,0.714918,-0.083554,-0.486248,0.182606,-0.060481,-0.054356,-0.362223,-0.029664,-0.089807,0.185339,0.639249,-0.189525,0.600733,0.390856,-0.278982,-0.533295,0.091361', '1308585', '1300303', '25928048', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294408', '音乐之声', '剧情', '玛利亚（朱丽·安德鲁斯  饰）是一个年轻活泼的修女，喜欢在大自然下高声歌唱，所以她常常忘记了修道院里的规矩。院长认为玛利亚并不属于规矩严格的修道院。院长与众嬷嬷商量后，决定安排玛利亚到一位名叫特拉普（克里斯托弗·普卢默 饰）上校家当家庭教师。上校的妻子去世多年，留下7个孩子，他要求对孩子严格管教。他告诉玛利亚在他家的家庭教师都做不长久，都是因为孩子的恶作剧。玛利亚果然也遭到了恶作剧，可是这位善良的老师并没有告诉他们的父亲，而是像个母亲一样照顾孩子，很快跟孩子打成一片。上校也渐渐在玛利亚的引导下改变了对孩子们的态度。上校与玛利亚之间发生了感情，他们完婚后回到了已被纳粹占领的奥地利，上校并不想为纳粹办事，一家人准备逃跑……©豆瓣', '朱莉·安德鲁斯', '罗伯特·怀斯', 9.1, 560748, 'tt0059742', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453788577.jpg', 0.1, 0.3, 6.3, 31.7, 61.6, '0.410147,-0.233581,-0.653545,0.483509,-0.561868,-0.305933,0.755721,0.058362,-0.444328,-0.471585,0.138959,0.856240,0.070359,0.284782,0.287995,0.102971,-0.549869,-0.612458,-0.158838,-0.168725,-0.068219,-0.800080,0.248735,-0.113771,-0.029962,-0.523688,0.260054,-0.363243,0.163583,0.407682,0.199206,0.077837,0.219745,0.170933,-0.000370,0.126451,0.211080,-0.054799,-0.264098,0.090891,0.134957,0.154108,0.000188,0.018002,0.343201,0.382201,0.369721,-0.515376,-0.238959,-0.234754,0.051954,-0.150057,0.262113,0.485818,0.280707,-0.011319,0.127656,0.449219,-0.136850,0.175611,-0.118528,-0.286087,-0.435688,0.276150,0.182257,0.121110,-0.723470,0.428017,0.021709,-0.192157,0.077807,-0.517145,0.287013,0.258777,0.065145,0.580861,-0.288094,0.225879,-0.399540,0.037935,0.696007,-0.002283,-0.134407,0.271657,-0.283938,-0.181894,0.374469,-0.114913,-0.649805,0.225581,-0.179512,-0.038299,-0.250473,0.289144,-0.198802,-0.043399,-0.261985,-0.191963,0.003406,-0.638071,0.126144,-0.422338,0.024356,-0.314928,-0.393841,0.013122,-0.035265,0.022690,0.964237,-0.905457,0.425320,0.287379,0.320831,-0.824431,0.580789,0.382468,0.092284,-0.253057,0.179088,0.248888,0.231720,0.259080,0.189364,0.373422,0.208615,-0.361722,-0.007733,0.187601', '35048413', '1292720', '3445516', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294413', '下一站，天国', '剧情', '纯洁无瑕的天国，宁静祥和。逝者乘坐通往天国的列车，来到位于天国与人间的小站作短暂停留。在接下来的一周时间，他们将努力回忆一生中最幸福的时刻，然后由天国的工作人员拍成影片，放映留念。逝者们或娓娓道来，或情绪激动，或沉默不语，那一个个平凡温馨的小故事在天国宛若秋日午后的时光中缓缓流淌……本片荣获1999年Manaki兄弟国际电影节铜相机300奖、1999年布宜诺斯艾利斯国际独立电影节最佳影片和最佳剧本奖、2000年每日电影最佳艺术指导奖、1999年法国南特三大洲电影节最佳电影奖、1998年圣•塞巴斯蒂安国际电影节影评人费比西奖、1998年都灵国际青年人电影节最佳剧本奖。©豆瓣', '井浦新', '是枝裕和', 8.1, 13856, 'tt0165078', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1379361709.jpg', 0.3, 1.8, 18.8, 49.2, 29.9, '-0.652587,0.255105,-0.384009,0.674357,0.745566,-0.033150,0.312895,0.097916,-0.488439,0.074539,0.203081,0.630209,-0.455255,0.160409,0.656834,-0.177942,-0.707213,-0.892548,-0.228694,-0.344132,0.148068,-0.013736,-0.212908,0.120379,-0.323576,-0.405535,0.758270,0.150980,0.461348,0.691923,0.279384,-0.051684,-0.164948,-0.316090,-0.005295,-0.201653,0.357144,0.147956,-0.738477,0.355241,-0.092358,-0.459895,-0.637960,-0.228310,0.335602,-0.110453,0.882790,-0.176448,0.071071,-0.019106,0.661060,-0.456525,-0.308125,-0.337266,0.141407,0.102843,0.179200,0.543445,-0.022664,0.251596,0.112666,-0.614788,-0.507389,0.005601,0.026446,0.099530,-0.414379,0.591368,0.066511,0.396570,-0.020405,-0.263634,0.471681,0.014901,0.419752,0.311450,-0.035268,0.106483,-0.126025,1.071209,0.349144,0.203705,-0.432980,0.368019,-0.144169,-0.658989,-0.308462,-0.420136,-0.451851,0.190845,0.424073,-0.149647,0.291833,0.414830,-0.451506,0.136391,0.191505,-0.757886,0.261784,-0.165116,-0.136449,-1.065221,0.071112,-0.126086,0.044635,-0.221561,-0.064079,-0.106252,0.927568,-0.344067,0.464884,0.312014,0.192694,0.025037,1.131437,0.004118,-0.003262,0.010852,-0.129471,0.312817,-0.495878,0.284178,-0.317314,-0.026005,-0.575867,-0.028627,-0.469271,0.330497', '1302279', '30397916', '24751811', '1308476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294417', '笑傲江湖2：东方不败', '剧情', '令狐冲（李连杰饰）在按计划与日月神教的朋友会面后，将和小师妹岳灵珊（李嘉欣饰）等其他华山派师兄弟赴牛背山归隐退出江湖。路途中意外发现练就“葵花宝典”的东方不败（林青霞饰），但令狐冲不认识东方不败，误将对方当成一位美貌女子。后来几次相遇，还一道饮酒吟诗。在同任盈盈（关之琳饰）、蓝凤凰（袁洁莹饰）会合后，几个月来江湖不平，大事连连。任我行为东方不败所囚禁，他们商量着夺回日月神教，便乔装进入浪人营打探，救出任我行。另一边华山派弟子惨遭毒手，黑木崖上，令狐冲和一干人都想着报仇，他惊觉眼前人竟是东方不败……©豆瓣', '李连杰', '程小东', 8.5, 191185, 'tt0103295', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p838966341.jpg', 0.2, 0.8, 13, 46.4, 39.7, '0.172065,-0.174193,-0.453006,0.462569,0.089590,-0.472406,0.480607,-0.100306,-0.541744,-0.423065,0.298354,0.593063,-0.305437,0.289530,0.040995,-0.045449,-0.237007,-0.932717,-0.209881,-0.540758,-0.032436,-0.137576,0.088624,-0.040793,-0.321732,0.071439,0.468418,-0.082908,-0.137837,0.757640,0.272384,-0.299257,-0.545351,0.509843,-0.128263,0.220083,-0.009498,0.080503,-0.262113,0.116971,-0.153447,-0.354135,-0.325854,-0.236090,-0.199859,0.430905,0.599962,-0.022472,-0.092803,-0.304579,-0.142384,0.000085,0.168283,0.062421,0.330590,-0.098813,0.151506,0.232278,-0.146100,0.059259,-0.133764,-0.045648,0.021422,0.267838,0.318568,-0.094818,-0.536033,0.313357,-0.289967,0.004767,-0.137699,-0.499982,-0.008576,0.206895,0.411041,-0.151199,0.155162,-0.092253,-0.410909,0.471535,0.694284,-0.160388,0.651337,-0.045895,0.641320,-0.164341,0.132492,-0.037869,-0.043388,-0.120009,0.345835,-0.184752,0.061314,0.040051,-0.073092,-0.063595,-0.170718,0.332101,-0.142538,0.003151,0.199858,-0.830298,-0.099875,-0.051735,-0.289925,-0.078632,0.216735,-0.079208,0.689888,-0.524551,-0.040177,0.129228,0.009706,-0.594644,0.545028,-0.041968,0.424156,-0.152853,-0.286803,0.232630,0.128542,0.244034,0.240172,0.390538,-0.195370,0.060472,-0.374593,-0.322434', '26365262', '1451563', '25723905', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294421', '伊万的童年', '剧情', '残酷的战争摧毁了12岁男孩伊万（Nikolay Burlyaev 饰）的童年，母亲和姐姐早年被德国军队杀害，小小年纪的伊万也不得不走上战场，成为一名在战火和死亡中穿梭的侦察兵。由于年龄的关系，中尉戈克森甚至不敢相信伊万的身份，但从科赫林上尉（Valentin Zubk ov 饰）的口中，他得知眼前这瘦小的男孩竟如此果敢。科赫林上尉希望将伊万带离战场，送他到远方读书。然而伊万却拒绝离开，这个勇敢的男孩决心战斗到生命的最后一刻……本片荣获1962年旧金山国际电影节最佳导演奖和1962年威尼斯电影节金狮奖。©豆瓣', '尼古拉·布尔里亚耶夫', '安德烈·塔可夫斯基', 8.8, 37195, 'tt0056111', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2360167553.jpg', 0.2, 0.5, 7.4, 41.3, 50.5, '-0.074990,0.189655,-0.816839,0.642164,-0.223665,-0.414595,0.797688,-0.043506,-0.376308,-0.241783,0.334248,0.894810,-0.039795,0.252077,0.797384,-0.134191,-0.254606,-0.698392,-0.095030,-0.009348,-0.160491,-0.590710,-0.555431,-0.068444,-0.034961,-0.621411,0.986511,0.241219,-0.161789,0.836486,0.380876,0.155098,0.036297,0.534723,-0.433148,0.027467,0.334823,0.042790,-0.410082,0.336019,-0.071725,-0.315293,-0.233568,0.224484,-0.101284,0.289576,0.767113,-0.359104,0.067486,0.038684,0.447248,-0.573808,-0.126835,0.179277,0.483801,-0.146344,0.009984,0.172622,0.086237,0.094292,-0.151054,-0.201284,-0.429656,0.126062,0.084401,0.089294,-0.763317,0.114343,-0.240620,0.094329,-0.038300,-0.166587,0.133201,0.192402,0.071942,0.437516,-0.435600,0.126404,-0.625010,0.034762,0.685509,-0.290771,-0.392769,0.158049,-0.098630,-0.665774,-0.054517,-0.509985,-0.473017,0.162182,0.172802,-0.021716,-0.159004,0.310993,-0.563876,-0.132472,-0.327808,-0.212461,0.045512,-0.339895,-0.274907,-0.407223,-0.226871,-0.525214,-0.229285,-0.038035,-0.174036,-0.064212,0.773272,-0.514028,0.266516,0.332842,0.392186,-0.165132,0.748860,0.285692,0.269936,-0.277104,-0.105956,0.591204,-0.034684,0.031381,-0.267510,0.197397,-0.144147,-0.254932,-0.265469,0.571191', '1780122', '1299663', '1293945', '1303083');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294433', '秋刀鱼之味', '剧情', '妻子去世多年，寡言的山平（笠智众）已习惯被待嫁的女儿道子（岩下志麻）贴心照料的生活。道子表面看来也乐意将老父亲照料，从没流露嫁人的渴望。山平老年乐事是与中学时代的几个老友饮酒叙谈，席间友人每谈及道子的婚事、表示要同她介绍对象，山平总会含糊其辞地拒绝，但怕面对什么，他也并不能想清。不过每次饮酒他都会适可而止，以避免酒醉给道子带来太多麻烦。这日中学同窗聚会，山平得知老师当年漂亮的女儿为将他照顾至今未嫁，后送醉酒的老师归家，见漂亮人儿今已衰老憔悴，他心里一惊，想到道子。其后，他示意道子考虑婚姻大事，道子却理解为父亲在赶她出门悲伤不已，他好言相劝她方含泪点头。道子答应一刻，他又心生无限酸楚。©豆瓣', '笠智众', '小津安二郎', 8.7, 41234, 'tt0056444', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1995499987.jpg', 0.9, 0.6, 8.6, 43.7, 46.1, '-0.146757,0.039439,-0.359863,0.526752,-0.079578,-0.527218,0.458803,-0.084781,-0.590327,-0.374899,-0.012156,0.801707,-0.259457,0.695874,0.195873,-0.084854,0.139881,-0.252057,0.004197,0.197217,0.009169,-0.104296,0.335033,0.000365,-0.430048,-0.087089,0.201824,0.016182,0.205080,0.432913,0.134739,0.100645,0.029260,0.405250,-0.141134,-0.161896,-0.552721,0.332136,-0.350542,-0.319036,0.068039,-0.189212,-0.406271,0.038655,0.324378,0.373269,0.339058,-0.007100,-0.389027,-0.104294,0.433125,-0.328875,0.228367,0.177153,-0.017008,0.110578,0.167016,0.216607,-0.317227,-0.070418,-0.053621,0.001728,-0.128323,0.253760,0.197839,-0.079796,-0.692273,0.274009,-0.147206,-0.276431,-0.077799,-0.342878,-0.010001,0.213238,-0.023331,0.354345,0.052926,0.164857,-0.016261,0.210087,0.517330,-0.058423,0.045148,0.198465,-0.106642,-0.107359,0.516656,-0.323509,-0.310947,0.122336,-0.243112,0.117364,-0.187155,0.302813,0.086349,-0.237959,-0.148924,0.013140,0.291197,-0.561003,-0.193182,-0.184695,-0.126859,-0.269567,-0.638755,-0.009230,0.496586,-0.238280,0.501497,-0.733655,0.033319,0.122210,0.353438,-0.606906,0.562335,0.417070,-0.050349,-0.432836,0.072051,0.322762,-0.226141,-0.136588,0.098480,0.174811,-0.181719,-0.176466,-0.200114,0.108297', '1292219', '1292720', '1302384', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294434', '三轮车夫', '剧情', '该片荣获1995年第52届威尼斯电影节最佳影片金狮奖。越南天才导演陈英雄继《青木瓜之味》后第二部作品，也是梁朝伟在《悲情城市》之后再次受到全世界瞩目的电影。本片对越南底层社会的触目惊心的描述，对黑帮贩毒、杀人放火、变态的性的刻划，再现出一个充溢着堕落与罪恶的越南。一个几乎还是孩子的三轮车夫、一个诗人气质的黑帮分子（梁朝伟饰）、一个为生活所迫不惜卖身的妓女都在与这个城市一起腐烂。两个多小时的片子里，那鲜红的血哗地一声不知从何处淌了出来，也就是在那一刹那，触到了生命的质感。影片以坚硬的力度、残酷的美感、血腥的诗意构筑了一个辛辣而令人晕眩的世界......©豆瓣', '梁朝伟', '陈英雄', 7.6, 15672, 'tt0112767', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171890911.jpg', 0.6, 3.3, 28.5, 48.9, 18.7, '0.098796,0.240431,-0.662386,0.876287,0.103336,-0.268155,1.069704,0.084716,-0.234449,0.236259,0.282349,0.973779,-0.405165,0.074133,0.079688,-0.055238,0.059921,-0.881832,-0.471625,-0.235028,-0.281568,-0.086235,-0.508671,-0.062659,-0.047342,-0.270178,0.695770,0.446333,-0.238717,0.398229,0.617318,-0.017827,-0.091103,0.262051,-0.286761,-0.169703,0.064232,0.010288,-0.304849,0.053803,0.092148,-0.480513,-0.107856,0.065146,-0.451112,0.252579,0.835090,-0.152387,0.027179,-0.175430,0.813710,-0.264374,-0.319125,-0.053766,0.193286,-0.162561,0.212444,0.065475,0.008841,0.099698,0.151815,-0.097499,-1.043941,-0.239270,0.121329,0.276707,-0.571870,0.579321,-0.099774,-0.168172,-0.077830,-0.132763,0.251541,-0.105860,0.316918,0.793079,-0.176023,0.130306,-0.207625,0.536964,0.543559,0.026299,-0.528908,0.412761,-0.466964,-0.829512,-0.223327,-0.417809,-0.350797,-0.101176,0.316943,-0.224650,-0.293233,0.176222,-0.981391,0.155756,0.095874,-0.319660,-0.121699,-0.021862,-0.209375,-0.489767,-0.424927,-0.400422,-0.086753,0.098553,0.265321,-0.025068,0.863384,-0.413799,0.116210,0.682176,0.094503,-0.290112,0.680787,0.173553,-0.123513,0.121969,-0.235399,0.284539,0.039218,0.308885,0.088848,0.790755,-0.244145,-0.060364,-0.295190,0.660358', '27666513', '25837262', '30162520', '30334399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294457', '爱丽丝梦游仙境', '剧情', '一次偶然之中，天真单纯的少女爱丽丝（Charlotte Henry 饰）追随着一只匆匆忙忙的奇怪兔子（Richard Skeets Gallagher 饰），掉进了兔子洞，穿越到了一个光怪陆离的奇妙世界之中。在这里，邪恶的红王后（艾德娜·梅·奥立佛 Edna May Oliver 饰）手握大权，居住在这里的居民们无不遭受到她的迫害。这是一个人人都为之疯狂的世界，只有爱丽丝一人保持着清醒和理智，她先后遇见了渡渡鸟（波莉·莫兰 Polly Moran 饰）、柴郡猫（理查德·阿伦 Richard Arlen 饰）、和青蛙（斯特灵·哈洛威 Sterling Holloway 饰）等角色，帮助兔子找回了丢失的扇子和手套，勇敢的站出来，带领大家抵抗红王后的残暴统治。最终，爱丽丝才发现，这一切只不过是自己的一个梦罢了。©豆瓣', '理查德·阿伦', '诺曼·Z·麦克劳德', 8.2, 9248, 'tt0023753', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2168449150.jpg', 0.2, 0.8, 18.6, 49, 31.4, '0.199387,0.334165,-0.690708,0.536646,-0.240251,-0.128560,0.886654,0.101348,-0.267527,-0.217642,0.386788,0.705411,-0.322371,0.343450,0.179325,0.178875,-0.171263,-0.571455,-0.076677,-0.035846,-0.339997,-0.039463,-0.623751,-0.241433,-0.313134,-0.188130,0.342693,0.131279,0.053807,0.520890,0.264492,0.257422,-0.265605,0.306085,-0.221383,0.010481,0.054904,-0.096365,0.084887,0.072998,-0.165440,-0.001661,-0.045803,0.388240,-0.111470,0.270787,0.790076,-0.834552,-0.130720,-0.186379,0.131715,-0.284149,-0.133794,0.181962,0.345783,-0.142682,-0.025697,-0.290865,-0.130539,0.281955,0.210954,-0.116861,-0.652207,-0.039438,0.035517,0.424881,-0.549729,0.379407,0.086054,-0.060737,0.169848,-0.266179,0.112303,0.097320,0.245848,0.403973,-0.069957,-0.032586,-0.530636,0.095702,0.409325,-0.193389,-0.287362,0.437208,-0.115604,-0.510912,-0.129319,-0.103291,-0.405701,-0.115330,0.417900,-0.071023,-0.249724,0.201627,-0.823921,-0.100212,-0.203721,-0.060006,-0.049351,-0.448781,-0.208941,-0.178788,0.104160,-0.347583,-0.212203,0.270384,-0.074195,-0.141434,0.560025,-0.737099,0.299269,0.529634,-0.022478,-0.327896,0.420088,-0.218766,0.077871,0.059660,0.014978,0.421547,0.202371,0.292839,0.250147,0.427607,-0.201974,0.122957,-0.613092,0.537764', '21619567', '1467779', '25774050', '3731581');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294461', '仙履奇缘', '爱情', '一部经典的迪士尼动画片，取材于格林童话《灰姑娘》。母亲的早逝令灰姑娘仙德瑞拉再也感受不到母爱的温暖，失去了公主般的童年。后母和她的两个女儿，无时无刻不在想方设法折磨仙德瑞拉，给她糟糕的住处、做不完的家务。幸好得道多助、失道寡助，心地善良的仙德瑞拉结识了一大班朋友，老鼠 、鸟儿、小狗都是守护在她周围的老友记。王子要在全城寻找王妃，仙德瑞拉用破旧零碎的布料赶做了一件礼服，当然这远远比不上心花怒放的姐姐们穿得艳丽。然而，灰姑娘得到了魔法相助，在神奇的法术中她美得倾城，坐着南瓜车来到王子的宫殿，与王子翩翩起舞。她知道，法术会在12点之前统统消失，大钟敲响的那一刻，她慌忙逃离王子，情陷已深的王子拿着灰姑娘不小心遗下的玻璃鞋，誓要从百万女子中找到一生中的最爱：仙德瑞拉。©豆瓣', '艾琳·伍兹', '克莱德·杰洛尼米', 8.4, 62900, 'tt0042332', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1833051594.jpg', 0.1, 0.6, 14.7, 48.1, 36.4, '0.249455,-0.023424,-0.637298,0.663281,-0.094380,-0.165402,0.732763,0.053179,-0.307226,-0.288298,0.453147,0.624099,-0.172477,0.013404,0.261036,0.505736,-0.243001,-0.510024,0.023889,-0.219267,-0.227627,-0.052079,-0.194034,-0.057413,-0.227170,-0.428778,0.504451,-0.188437,0.055811,0.216186,0.294724,-0.013970,-0.006935,0.181957,-0.238242,0.107955,-0.044658,-0.013473,-0.020373,0.309077,0.122223,-0.180978,-0.031359,0.135449,-0.101618,-0.005445,0.508019,-0.681703,0.269760,0.082437,0.360026,-0.170362,0.048818,0.192095,0.042288,-0.113970,0.211027,-0.126091,-0.322702,0.030995,0.315971,-0.095750,-0.465034,0.007164,0.268252,0.204617,-0.795481,0.548773,-0.264778,-0.087914,0.502387,-0.490100,0.359177,-0.052157,0.096835,0.563151,-0.020332,0.019469,-0.648645,0.466089,0.518614,0.178165,-0.146062,0.570520,-0.240238,-0.210134,-0.024377,-0.268303,-0.685532,0.033875,0.274772,-0.018375,-0.083045,0.369776,-0.501789,-0.099510,-0.204599,-0.184386,0.127305,-0.536828,-0.336504,-0.294181,-0.142723,-0.319362,-0.091949,0.148930,0.148343,-0.160472,0.719777,-0.697965,0.359599,0.456708,0.104659,-0.138558,0.719464,-0.167580,0.103634,0.166494,-0.035356,0.196319,-0.062396,0.384163,0.275412,0.429309,-0.112069,-0.031712,-0.658653,0.398811', '26884422', '21619567', '1783772', '5938000');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294486', '人约巴黎', '喜剧', '三段发生在巴黎的爱情小故事，尽管启用的演员都很年轻，但看上去都有侯麦的味道。其一描述女孩怀疑男朋友欺骗她，于是打算在咖啡馆跟一名陌生人约会，岂料到达后发生了意想不到的情况；其二描写一对男女在公园相遇，迅速相恋拥吻，并打算假装游客住进旅馆，其实女孩已有男朋友，一个意外发生改变了两人的计划；其三描写一名小画家在咖啡馆约了一名瑞典来的游客，但偶然在博物馆门口遇上一名女子便一见钟情展开追求，不料她却是一名有夫之妇', 'Clara Bellar', '埃里克·侯麦', 8, 11713, 'tt0114266', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2499534383.jpg', 0.2, 0.9, 18.7, 57.7, 22.4, '0.541987,-0.333883,-0.701221,0.344832,0.029839,-0.149618,1.051499,0.126833,-0.125396,-0.532610,0.563950,0.680429,-0.322407,0.209379,0.693212,-0.429669,-0.127564,-0.355542,0.422660,-0.344639,-0.188637,-0.277942,-0.082830,-0.068112,-0.034438,-0.210339,0.590261,-0.070654,-0.477843,0.285731,0.413239,-0.152558,-0.455800,0.435708,-0.242770,-0.225594,0.434521,0.514091,-0.336640,0.237178,-0.342164,-0.166368,-0.157550,-0.227152,-0.127816,0.268291,0.806170,-0.116395,-0.652325,0.354744,0.300442,0.215257,0.084093,0.059901,0.464962,0.101604,0.153801,-0.093146,0.129534,-0.064067,0.048158,-0.248360,-0.242362,0.488610,0.134715,0.268892,-0.239168,0.480837,0.236904,-0.064696,0.060288,-0.458395,0.050830,0.363300,0.425885,0.005444,0.014614,0.124002,-0.715627,0.203005,0.841972,0.218872,-0.354662,0.880342,-0.154912,-0.516370,-0.151905,0.253347,-0.490383,0.393192,-0.040536,-0.260289,-0.459724,-0.064103,-0.360561,-0.094613,-0.099208,0.200819,0.109660,-0.216113,0.026124,-0.741457,-0.165484,0.002248,-0.296188,0.151141,0.108149,-0.050541,0.660099,-0.822556,0.167771,0.638847,0.221191,-0.689809,0.805328,0.254495,-0.027492,-0.335378,-0.283880,0.557115,0.096454,-0.060934,-0.317839,0.514108,-0.291652,-0.171015,-0.422093,-0.026394', '10466639', '26687241', '1296534', '1292217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294488', '少年黄飞鸿之铁马骝', '喜剧', '清朝末年，官吏贪腐，民不聊生，在浙江地方上，有一位蒙面侠士“铁猴子”，两年来劫富济贫，令卖官鬻爵的历任知府叫苦不迭。铁猴子在白天的身份是大夫杨天淳(于荣光 饰)，杨大夫妙手仁心，深得乡邻爱戴。知府为抓捕铁猴子，不惜拷打众多不相干群众，路经此地的黄麒英（甄子丹 饰）、黄飞鸿父子不慎卷入其中，知府见黄麒英身手过人，扣押飞鸿要挟其捉拿铁猴子，黄麒英与铁猴子交手后惺惺相惜。不久朝廷钦差抵浙，听闻铁猴子“作乱”之举后施展大力金刚掌将其击伤，原来这钦差的真实身份是少林叛徒衍空（任世官 饰），身为少林弟子的黄麒英联合铁猴子，誓为少林清理门户。©豆瓣', '甄子丹', '袁和平', 7.6, 22334, 'tt0108148', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204698976.jpg', 0.4, 2.1, 31.4, 48.2, 17.9, '-0.058816,-0.345161,-0.398704,0.218050,0.066931,0.057079,0.175664,0.418046,-0.731858,-0.457316,0.568589,0.609969,-0.209471,-0.266577,-0.078037,-0.219975,0.231020,-0.466302,-0.403186,-0.114637,0.010003,-0.009233,-0.073766,-0.259147,-0.292694,-0.175634,0.106062,0.057605,-0.410151,0.278875,0.434523,0.217365,-0.281915,-0.021242,-0.137511,0.139523,0.028679,-0.072480,-0.350505,-0.252650,-0.373505,-0.345823,-0.186906,-0.134177,-0.161665,0.496013,0.079201,-0.228388,-0.070191,-0.410269,-0.070508,-0.127787,-0.009226,-0.033878,0.539526,0.179027,0.221107,0.231692,0.165027,-0.193024,0.104933,-0.180247,-0.206479,0.140750,0.338110,-0.003090,-0.272657,0.442095,-0.192507,0.145981,-0.420354,-0.376086,-0.021165,-0.021048,-0.036307,0.015366,0.277756,-0.064009,-0.359832,0.635643,0.662014,-0.103291,0.165386,-0.441830,0.169175,-0.286191,0.252366,-0.667373,0.055712,-0.197145,0.565981,-0.318127,-0.281825,0.321671,-0.151915,-0.348506,-0.548672,0.795883,-0.056129,0.295343,0.121428,-0.409719,0.176983,-0.411880,-0.121272,-0.278951,0.654276,-0.065692,0.591228,-0.500499,-0.035100,0.124798,0.036324,-0.325728,0.412325,-0.120864,-0.042242,-0.019447,-0.289888,-0.314593,0.839344,0.519770,0.485469,0.119338,-0.293495,-0.389240,-0.057879,-0.029679', '1301946', '1297863', '1303497', '1303176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294490', '上帝也疯狂2', '喜剧', '在沙漠中生活的卡拉哈里人远离现代世界，在干旱的环境里自有一套谋生方式。卡拉哈里人奇哥（N!xau 饰）的两个幼子奇沙与奇尔在父亲寻找食物时被车厢的露水吸引，登上了偷猎者的卡车，却被不知情的偷猎者带走。奇哥自此踏上了追寻孩子的旅途……来自美国的法学博士安泰勒（Lena Farugia 饰）经一位心血来潮的飞行员邀请，登上了他的飞机，却为恶劣的天气影响，和动物学家马歇尔（Hans Strydom 饰）一同被困在沙漠的深处，两位博士术业有专攻，但野外生存肯定不是安泰勒的强项，女博士忙乱的表现为这次历险平添了轻松的气氛……古巴战士与非洲士兵为双方阵营而战，两个人一把枪传来传去，他们也先后做着对方的俘虏……这群人在沙漠深处的动物天堂穿插互动，上演了一出温馨轻松的喜剧。©豆瓣', '历苏', '加美·尤伊斯', 8.8, 55558, 'tt0097443', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2654309783.jpg', 0.2, 0.7, 10.1, 36.9, 52.1, '0.469117,-0.127092,-0.659987,0.746666,-0.028543,-0.076195,0.819475,0.212389,-0.423911,-0.022484,0.249582,0.786847,-0.136619,-0.030827,0.204616,-0.040564,-0.421087,-0.587960,-0.201678,-0.004847,-0.345887,-0.336165,-0.247605,-0.438941,-0.062429,-0.421516,0.558056,0.424998,-0.379791,0.498689,-0.008450,0.203841,-0.346391,0.532637,-0.199167,-0.211563,0.074791,0.102320,-0.207537,0.151961,-0.261677,-0.262006,-0.105349,-0.045438,0.150235,0.363706,0.899288,-0.236617,0.031049,0.096661,0.127560,-0.398559,0.013344,-0.130510,0.401124,-0.218626,-0.068943,0.029218,0.062063,0.213601,-0.008215,-0.151431,-0.757477,0.067319,-0.057354,0.071462,-0.556601,0.661516,0.146188,-0.111808,-0.041142,-0.094738,0.486063,0.293275,0.238998,0.486838,0.058166,-0.036914,-0.508955,0.123428,0.883298,-0.139477,-0.147708,0.210450,-0.475421,-0.660204,0.185177,-0.148064,-0.413221,-0.322392,0.535481,-0.147242,-0.314557,0.270889,-0.702435,0.357170,-0.181357,-0.355288,-0.164607,-0.413039,-0.214682,-0.557928,0.162675,-0.449239,-0.211918,0.170835,0.134188,-0.180103,0.769379,-0.696298,0.151417,0.565745,0.054128,-0.405224,0.760799,-0.194998,0.210304,-0.109327,-0.076184,0.274710,0.166542,0.309275,0.337941,0.416204,-0.350233,-0.034116,-0.435174,0.326058', '3055049', '2053515', '30162520', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294496', '似是故人来', '剧情', '7年前，杰克（理查•基尔 饰）丢下了自己已怀孕的妻子劳瑞（朱迪•福斯特 饰）参加了美国内战。7年来毫无音讯，劳瑞承担起照顾孩子照顾家庭的责任。7年后的某天，杰克突然出现了。而且这时候的杰克，已不再是粗鲁刻薄，简直像变了一个人似的。本来就是地主的他带着村民一起勤奋耕作，希望尽力提高大家的生活水平。可是劳瑞初感到这种幸福感不久，事情发生了变化。杰克被控告与一宗谋杀案有关，当局要拘捕杰克，沉默的杰克并没有反抗，他接受拘捕。事实上，这是假的杰克，他是真杰克的教师朋友，真正的杰克早已死去了。假杰克愿意承受罪名，是因为他要把杰克最美好的一面留在大家的心中……©豆瓣', '理查·基尔', '乔恩·阿米尔', 7.8, 7833, 'tt0108185', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2360651484.jpg', 0.2, 1.6, 25.2, 51.8, 21.1, '0.214182,-0.253901,-0.627472,0.149858,-0.271673,-0.346120,0.872370,0.195999,-0.652281,-0.278039,0.059854,0.515194,0.007431,0.185588,0.221248,0.082284,-0.521903,-0.572665,-0.020429,0.074531,-0.067436,-0.514824,0.016603,-0.348956,-0.277022,-0.286624,0.366534,-0.158504,0.033771,0.366756,0.303206,0.247508,0.329614,0.529594,-0.092778,0.124769,-0.011537,0.027116,-0.356075,0.214900,0.305719,0.135061,-0.020468,0.353282,0.075683,0.414867,0.255322,-0.209679,-0.231195,-0.108896,0.304747,-0.346679,-0.012715,0.221631,0.100446,-0.098542,0.110529,0.312002,-0.101130,-0.182725,0.256908,-0.032790,-0.652799,0.174401,0.079494,0.238356,-0.535827,0.296437,-0.285902,0.108857,-0.012222,-0.298438,0.154415,0.309893,0.225876,0.264631,-0.101919,-0.023305,-0.524212,0.202786,0.755894,-0.211294,-0.391965,0.232628,-0.387282,-0.293915,0.036400,-0.260500,-0.433392,0.202859,0.043346,0.053797,-0.207233,0.351485,-0.255994,-0.207715,-0.249605,-0.274309,-0.157471,-0.360500,-0.022871,-0.207779,-0.111199,-0.317736,-0.489648,-0.165722,-0.038943,-0.317561,0.538988,-0.867728,0.206433,0.482294,0.424561,-0.413707,0.428860,0.164716,0.096585,-0.089695,0.152322,0.268896,-0.015175,0.173420,0.260443,0.146923,0.346966,-0.115907,0.106755,0.542790', '1308755', '1296370', '10546747', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294497', '飓风', '剧情', '一个黑人毛头小伙莱斯（维斯罗斯•雷恩•香农 Vicellous Reon Shannon 饰）在旧书市无意中淘到了拳王“飓风”鲁本•卡特（丹泽尔•华盛顿 Denzel Washington 饰）在狱中写的自传，并开始了对他的故事产生了兴趣。鲁本出生于贫寒家庭，幼年时嫉恶如仇，因此与当地的白人警察结怨。后来，他因为出色的身手，名震拳坛，绰号“飓风”。此后，他参加了越战成为荣誉军官，并在某舞会偶然结识了后来的妻子。当生活进入美满轨道的时候，一次新泽西酒吧杀人案彻底毁掉了他美好希望。莱斯与鲁本通信，了解到他蒙受不白之冤，便说服了朋友们，一起查找证据，希望揭开真相，令他重获自由，然而种族歧视的恶势力却在暗中百般刁难，意图把飓风困死在牢房……©豆瓣', '丹泽尔·华盛顿', '诺曼·杰威森', 8.5, 12613, 'tt0174856', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1970425151.jpg', 0.2, 0.8, 11.9, 46.8, 40.3, '0.115420,0.109993,-0.636170,0.370587,-0.094824,-0.249271,0.612673,0.156402,-0.622170,-0.234784,0.116605,0.758443,-0.071671,0.197852,0.274184,0.058630,-0.288108,-0.810406,0.248344,-0.265916,-0.148045,-0.344504,-0.231413,-0.180334,-0.037297,-0.483684,0.430868,0.265154,-0.241527,0.453448,0.065846,0.246606,-0.078304,0.403677,-0.285173,0.050767,0.299137,0.124460,-0.553665,0.131901,-0.234616,-0.189968,-0.115632,0.062502,0.104169,0.164580,0.527024,-0.131512,-0.100362,-0.066851,0.288656,-0.052337,0.008731,0.184998,0.287660,0.002548,0.164839,0.255845,0.007999,-0.068310,-0.028688,-0.073267,-0.492434,0.100978,-0.054454,0.158278,-0.528580,0.511467,-0.222435,0.005238,-0.057196,-0.056512,0.020440,0.083014,0.180554,0.107360,-0.052687,0.236175,-0.377741,0.213550,0.721643,-0.066114,-0.315208,0.090110,-0.244715,-0.178523,0.004194,-0.085340,-0.142804,-0.073214,0.596550,-0.015767,-0.292615,0.332249,-0.469676,-0.138372,-0.321032,0.001694,0.030183,-0.290854,-0.089440,-0.570746,-0.287980,0.009378,-0.300747,-0.223969,-0.045607,-0.296867,0.592099,-0.723411,0.344678,0.813573,0.260286,-0.472411,0.536156,0.313879,0.198424,-0.160530,0.020303,0.307327,0.353737,0.377220,-0.019331,0.199456,-0.111764,-0.307969,-0.155751,0.549311', '1309069', '30162520', '11541282', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294506', '午夜凶铃2：贞子缠身', '恐怖', '在一口封闭了三十多年的枯井里，发现了高山龙司（真田広之 饰）以及失踪已久的贞子（伊野尾理枝 饰）的尸体。经法医鉴定，贞子死亡的时间不过1、2年时间，即她在枯井下存活了三十年之久。为了追究恋人的死因，高山的女友高野舞（中谷美紀 饰）四处寻找浅川玲子（松嶋菜々子 饰）的下落 。她遇到浅川的后辈冈崎（柳ユーレイ 饰），两人循着浅川当初调查“诅咒录像带”的线索一路追查，在这一过程中，录像带的牺牲者不断出现。恐怖的贞子似乎并未从世间消失，她的诅咒仿佛恶灵般如影随形……本片根据鈴木光司原作改编，是前作《午夜凶铃》的正宗续集。©豆瓣', '中谷美纪', '中田秀夫', 6.7, 21679, 'tt0218553', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p647988001.jpg', 1.8, 9.5, 51.7, 26.9, 10.1, '0.056227,0.108176,-0.607011,0.539099,0.088867,-0.083404,0.835222,-0.123114,-0.463726,-0.511065,0.277782,0.429577,-0.291534,0.214903,0.123653,-0.034829,-0.234595,-0.643063,-0.207815,-0.323504,-0.330005,-0.222454,-0.294181,-0.130980,-0.050807,-0.224331,0.660561,0.321347,0.000379,0.279585,0.108359,0.242373,-0.514718,0.093822,0.004567,0.308480,0.034390,0.199212,-0.051224,0.237733,0.058181,-0.584391,-0.041996,0.049185,-0.011821,0.480904,0.680497,-0.228799,-0.337358,0.050359,0.329594,-0.177334,-0.202895,-0.002679,0.520240,-0.080176,0.066753,0.397841,-0.379984,-0.184203,0.002943,-0.050244,-0.399256,-0.301818,0.086111,0.500815,-0.342556,0.396784,-0.052532,0.007523,-0.007012,-0.375051,0.097494,0.035765,0.361310,0.140724,-0.393915,-0.063807,-0.399413,0.472871,0.296931,-0.040395,-0.176902,0.289093,0.029982,-0.610577,-0.381473,0.028312,-0.135354,0.002954,0.577742,0.260283,-0.369920,0.247687,-0.561887,-0.261978,-0.052587,-0.101983,0.072100,-0.092253,-0.341549,-0.568695,-0.119117,-0.319501,-0.162693,0.133909,0.026191,-0.476127,0.532876,-0.579037,0.363197,0.581166,-0.266224,-0.052729,0.364988,-0.155999,-0.239628,-0.009663,0.192009,0.443199,0.059148,0.444397,0.372603,0.345931,-0.110159,-0.169087,-0.705496,0.369230', '1467779', '20451118', '21619567', '11615927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294519', '蝙蝠侠与罗宾', '动作', '蝙蝠侠（乔治•克鲁尼 George Clooney 饰）和罗宾（克里斯•奥唐纳 Chris O''Donnell 饰）这次遇到有生以来最大的挑战：“急冻人”（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）！“急冻人”原是一个科学奇才，但一次意外却令他只能靠急救机器为生。更为糟糕的是，除非他将整个高谭市的温度保持在零度以下，否则他心爱的妻子将永远不能醒来。“急冻人”开始一步步建立自己的冷冻王国，蝙蝠侠将是这个计划的最大阻碍，“急冻人”迫切需要除掉这个眼中钉。罗宾逐渐成为蝙蝠侠的得力助手，两人合力化解了“急冻人”的一次次阴谋。但美艳的“毒藤女”（乌玛•瑟曼 Uma Thurman 饰）的出现给罗宾和蝙蝠侠彼此之间的关系带来了危机：“毒藤女”利用罗宾对她的心意，一步步设下陷阱，诱使两人互相猜疑。蝙蝠侠和罗宾最终能否化解心结，战胜“急冻人”和“毒藤女”？', '阿诺·施瓦辛格', '乔·舒马赫', 6.1, 34121, 'tt0118688', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1502664663.jpg', 5.1, 18.1, 51.3, 18.7, 6.8, '0.195189,0.028681,-0.457037,0.684121,-0.266180,0.103124,0.623055,0.159243,-0.441226,-0.265820,0.348092,0.835410,-0.285747,-0.326061,0.048779,-0.003472,-0.193511,-0.720109,0.017175,0.139680,-0.501721,-0.441742,-0.614668,-0.378958,0.055472,-0.318664,0.616664,0.182361,-0.241003,0.145124,0.258651,0.434313,0.141605,0.611508,0.048841,-0.018103,-0.132883,-0.293186,-0.343873,0.581552,0.019978,-0.177657,-0.127048,0.573217,-0.194743,0.391219,0.510004,-0.473079,-0.177583,-0.157617,0.150594,-0.653167,-0.078131,0.097155,0.061243,-0.144758,0.016290,0.359036,-0.141680,-0.078130,0.322454,-0.076024,-0.876581,0.161124,0.104463,-0.209107,-0.553271,0.379839,-0.085120,0.094475,0.221359,-0.239214,0.048350,0.251516,0.605775,0.183760,-0.290963,-0.053468,-0.591961,-0.113548,0.686179,-0.103736,-0.435916,0.177603,-0.240618,-0.236211,-0.247451,-0.281642,-0.340704,-0.100285,0.409660,0.316474,-0.106432,0.301690,-0.553757,-0.243448,-0.473301,-0.068812,-0.078151,-0.588698,0.211427,-0.540455,-0.222229,-0.277276,-0.247335,0.027316,-0.138009,-0.490046,0.651262,-0.718268,0.128309,0.644470,0.266570,-0.329304,0.600976,0.196338,0.177161,-0.370140,-0.280814,0.216649,0.128761,0.063226,0.297520,0.366556,0.002142,0.211610,-0.247584,0.478623', '30163