INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294531', '牺牲', '剧情', '评论家亚历山大（厄兰·约瑟夫森 Erland Josephson 饰）在瑞典的家中庆祝自己的五十岁生日，年幼的小儿子刚做完咽喉手术不能发声。两人在静默中种下一株树苗期待它生出绿色的枝叶，然而就在当天晚上，电台广播了一则发射核导弹的消息，第三次世界大战即将爆发。绝望的亚历山大向上帝祈祷不要发生战争，甚至他愿意奉献自己的一切来阻止世界末日的来临。期待世界重生的亚历山大在心力交瘁的情况下，烧毁了自己的房子。在熊熊大火中，亚历山大被救护车送进了医院。小儿子来到岸边继续为他们共同栽种的树苗浇水，一切似乎又恢复了平静。苏联著名电影大师安德烈·塔科夫斯基生前执导的最后一部杰作《牺牲》，荣获1986年戛纳电影节天主教人道精神奖在内的四项大奖，并提名金棕榈奖最佳影片，于1988年荣获第41届英国电影和电视艺术学院奖最佳外语片。©豆瓣', '厄兰·约瑟夫森', '安德烈·塔可夫斯基', 8.9, 12438, 'tt0091670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456417673.jpg', 0.9, 1.4, 8.8, 31.7, 57.1, '-0.304041,0.146049,-0.921039,0.388669,0.116774,-0.165929,0.472165,0.055240,-0.159804,-0.010619,0.265981,0.752061,-0.504199,0.227997,0.129229,0.052202,-0.462985,-0.668537,-0.048515,-0.036271,-0.172175,-0.183448,-0.222598,-0.149361,0.002051,-0.420274,0.679806,0.232664,0.020434,0.299107,0.386473,-0.001712,0.174872,0.347427,-0.111982,0.137638,0.237115,-0.030580,-0.496777,0.351849,-0.027234,-0.462592,-0.392240,0.169539,0.123206,0.181502,0.570828,-0.146595,-0.081158,0.017470,0.539567,-0.313991,0.006139,0.177699,0.277291,0.178527,0.076434,0.220756,-0.077959,0.230416,-0.048449,-0.179354,-0.569270,-0.077454,-0.123470,0.164877,-0.535402,0.489870,-0.162118,0.289436,0.020450,-0.187926,0.358444,0.232961,0.224799,0.500462,-0.355260,-0.004999,-0.374304,0.370732,0.454752,-0.238279,-0.322840,0.472640,-0.152151,-0.406874,-0.106931,-0.026520,-0.440231,0.189727,0.505775,-0.071122,0.017150,0.272405,-0.257410,-0.226633,-0.166153,-0.712833,0.043756,-0.092828,-0.152757,-0.678031,0.152851,0.103427,-0.229752,-0.035914,0.226552,-0.194418,0.586228,-0.325770,0.540554,0.320401,0.088852,-0.100090,0.569954,-0.003569,-0.065651,-0.295834,-0.000424,0.336940,-0.269712,0.433134,0.179365,0.182196,0.034146,-0.053221,-0.536763,0.471417', '1298911', '25785124', '24849892', 