INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294540', '你那边几点', '剧情', '父亲离世后，来到天桥摆摊卖手表的小康（李康生）同母亲一样，虽自觉与其并无多少情感，却无法摆脱其在精神上的无处不在。因为一块可以显示出巴黎与台北时差的手表，小康结识要去巴黎的湘琪（陈湘琪 饰），自此，精神抑压的他以为同巴黎（湘琪 饰）取得了某种形式的关联，获得某种虚空的安慰。当小康通过把时钟调快7小时、观看电影《四百击》等形式来表达他对湘琪暧昧的思念时，远在巴黎的湘琪也并没能从生活中找到多少积极的意义。无论同性（叶童）还是异性，她均无法从他们身上得到想要的温暖。©豆瓣', '李康生', '蔡明亮', 8, 12248, 'tt0269746', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p658392140.jpg', 0.7, 2.3, 21.7, 48, 27.3, '0.124944,0.282232,-0.710129,0.543388,-0.069409,-0.233285,0.660601,-0.021660,-0.389174,-0.049522,-0.059893,0.571874,-0.222989,0.126674,0.001742,-0.074700,-0.185161,-0.732614,0.292049,-0.275379,-0.273974,-0.385226,-0.403298,0.127281,-0.288448,-0.038518,0.548432,0.125687,-0.173819,0.422442,0.124072,0.159572,-0.207240,0.538837,-0.343649,-0.170697,-0.366081,0.144719,-0.548984,0.199093,0.250160,-0.071286,-0.184220,0.232155,0.006032,0.386545,0.831193,-0.024019,-0.201725,0.366077,0.381410,0.344719,0.012870,0.115839,-0.058483,0.304487,0.107313,0.131432,-0.109128,0.331664,0.067138,0.182415,-0.797168,0.022877,0.001783,0.242129,-0.318642,0.648630,-0.079363,-0.313119,-0.052945,-0.420787,0.156519,0.370608,-0.085564,0.535279,-0.448071,-0.128687,-0.407420,0.189890,0.494253,-0.004800,-0.169945,0.562831,-0.386961,-0.476016,-0.027178,-0.046579,-0.344608,0.017373,0.293525,0.479101,-0.321815,-0.071585,-0.581547,0.050591,-0.112590,-0.185002,0.184680,-0.481167,0.271528,-0.678189,-0.141887,-0.565874,-0.111340,-0.003543,0.380082,-0.256787,0.498714,-0.770612,0.175900,0.533354,0.487111,-0.429088,0.678021,0.109307,-0.101714,-0.243491,-0.030963,0.347144,-0.208717,0.460006,0.049769,0.120386,0.153864,0.049933,-0.463780,0.541110', '1652618', '2334814', '25928048', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294548', '瓶装火箭', '剧情', '梦想成为了不起的罪犯的迪格南（欧文•威尔逊 Owen Wilson 饰）找来刚结束了精神病院治疗生活的好友安东尼（卢克•威尔逊 Luke Wilson 饰），以及能够充当司机的大麻爱好者鲍勃（Robert Musgrave 饰）组成了一个仓促上马的犯罪团伙。先用偷窃安东尼家来热身的这伙准罪犯们苦练枪法、设计路线，终于成功打劫了一家书店，兴高采烈进入罪犯行列的迪格南等人驾车逃窜，躲入了一家汽车旅馆，安东尼对旅馆的乌拉圭女服务员一见钟情，而鲍勃却因自己兄弟入狱的消息心神不定。在安东尼和服务员的恋情如火如荼之时，鲍勃丢下二人返家，迪格南和安东尼也终于散伙，各自回归了平静生活。然而迪格南仍然没有放弃犯罪之梦，他向自己的偶像——黑道人物亨利求助……©豆瓣', '欧文·威尔逊', '韦斯·安德森', 7.1, 8934, 'tt0115734', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456203607.jpg', 0.8, 4.6, 45.9, 37.4, 11.4, '0.320164,-0.106607,-0.488264,0.334053,-0.235041,-0.574033,0.549989,0.150607,-0.374442,-0.320695,0.249611,0.752378,-0.067280,0.109155,0.440691,-0.093300,-0.407018,-0.686003,0.080287,-0.184438,-0.173716,-0.259859,-0.134579,-0.367732,-0.101977,0.090920,0.402906,-0.019687,-0.113862,0.511247,0.351299,0.309903,-0.131586,0.336424,-0.299665,0.091049,0.472110,-0.161561,-0.531062,0.239025,-0.071749,-0.201556,-0.197557,0.021779,0.191496,0.304767,0.711430,-0.055457,0.021101,-0.083208,0.046161,-0.232127,-0.083046,0.149699,0.288182,-0.002481,0.126925,0.000606,0.061912,0.016321,-0.143915,-0.118773,-0.715610,0.095645,-0.037806,-0.045624,-0.476527,0.256694,-0.216302,0.130829,0.071154,-0.332219,0.111841,0.287092,0.191731,0.265293,0.005225,0.072915,-0.456986,0.220540,0.463422,-0.054153,-0.174829,0.323894,-0.044964,-0.416216,0.113088,-0.087544,-0.495472,-0.304264,0.594135,0.078764,-0.115671,-0.032396,-0.569205,-0.182385,-0.322972,-0.172233,0.029293,-0.321458,0.006273,-0.977099,0.179992,-0.079559,-0.196463,0.053566,-0.117084,0.034867,0.592916,-0.508990,0.079992,0.445089,0.088850,-0.650326,0.461580,-0.158647,0.299628,-0.137745,-0.073175,0.235463,0.210754,0.563981,0.183256,0.437085,-0.169741,-0.108942,-0.299646,0.403689', '11541282', '3147969', '2075345', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294549', '黄飞鸿''92之龙行天下', '动作', '武师陈厚德（元华 饰）远赴美国开设宝芝林，时常召唤国内的徒弟阿杰（李连杰 饰）来美国帮衬，但阿杰担忧在美的居留问题，迟迟未到。陈厚德曾经收下一名美国弟子尊尼（杰瑞•特林伯 饰），尊尼学成后却挑战师傅，意欲扬名立万扩张自己的武馆，陈厚德被尊尼打成重伤，宝芝林也被砸烂，幸好有少女安娜路过，将陈厚德救走。几乎同时，阿杰终于来美探望师傅，岂料一出机场便遭遇各种麻烦，先是莫名其妙收下三名落魄墨西哥少年为弟子，又与查封宝芝林的银行地产部经理阿美（郭锦恩 饰）不吵不相识。阿杰因语言不通，守候宝芝林寻找师傅下落，而尊尼也在四处打探陈厚德的去向，一中一外两名弟子，将为义与利的不同追求狭路相逢……©豆瓣', '李连杰', '徐克', 6.7, 15343, 'tt0097775', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2456289087.jpg', 1.2, 8, 55.6, 26.1, 9.1, '0.206747,-0.047036,-0.251272,0.340550,0.099379,-0.556574,0.301014,0.157457,-0.467172,-0.534148,0.094016,0.531111,-0.090438,0.265457,0.247405,-0.196619,0.178609,-0.366377,-0.064084,-0.087155,-0.234321,-0.351462,-0.008620,-0.151279,-0.209258,-0.131107,0.355249,0.151665,-0.289508,0.611696,0.291140,0.200404,-0.218064,0.496811,-0.144594,0.224354,0.405622,0.140081,-0.200771,0.091444,-0.011325,-0.639528,-0.060302,-0.210546,0.267640,0.448961,0.269025,0.252918,-0.020370,-0.096703,-0.003690,-0.002197,0.211069,0.093382,0.353205,-0.026580,0.238630,0.004933,-0.328741,-0.092604,-0.063955,0.001229,-0.351607,0.352616,0.540386,-0.044468,-0.688879,0.134164,-0.305964,-0.033912,-0.075588,-0.247249,0.202712,0.457635,0.054234,0.184989,0.166166,0.049025,-0.310245,0.221630,0.723984,-0.153052,0.313296,-0.397947,0.105051,-0.358155,0.143645,-0.053426,-0.230827,-0.023131,0.162263,-0.308507,0.433750,-0.300975,-0.160558,-0.187749,-0.362752,0.069728,-0.036543,-0.163687,0.067664,-0.531785,0.302706,-0.197612,-0.262735,0.013664,0.250229,-0.002408,0.533014,-0.406279,0.207784,0.106947,0.419054,-0.473386,0.721641,-0.226936,0.124686,-0.472303,-0.103154,0.154080,0.416346,0.390801,0.288957,0.206378,0.057339,-0.265005,0.014346,-0.062289', '25908042', '1304758', '25881781', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294559', '爱国者游戏', '剧情', '杰克（哈里森·福特 Harrison Ford 饰）曾是中情局的一名情报员，在一次度假中，他偶然目睹了一场以北爱尔兰国务大臣霍姆斯（詹姆斯·福克斯 James Fox 饰）为目标的恐怖活动，职业习惯让他无法对此坐视不管，在杰克的协助下，恐怖份子米勒（肖恩·宾 Sean Bean 饰）被捉拿归案，杰克也得到了赢得的奖赏。虽然行动失败了，但恐怖分子们并没就就此罢休，而是决定再干一票，此时已经越狱成功的米勒主动请缨加入行动，他的脑中只有一个念头，那就是向杰克寻仇。很快，敏感的杰克就发现自己和家人正处于极度危险之中，为了捍卫国家和平，更为了保护自己的家人，杰克回到中情局，重操旧业。©豆瓣', '哈里森·福特', '菲利普·诺伊斯', 6.7, 5542, 'tt0105112', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2324769533.jpg', 1.1, 6.8, 56.5, 29.4, 6.2, '0.366775,0.126967,-0.634374,0.440052,-0.234459,-0.380922,0.558210,-0.011468,-0.707103,-0.255008,0.292563,0.845309,0.035382,-0.046596,0.335209,-0.127913,-0.389836,-0.733883,-0.019007,-0.005981,-0.195694,-0.657038,-0.234493,-0.401071,-0.206322,-0.231575,0.690187,0.094272,-0.240873,0.423154,0.374565,0.353869,0.221549,0.577892,0.016415,-0.083257,0.194797,-0.346674,-0.398983,0.452171,0.203638,-0.274487,-0.185645,0.499512,0.093198,0.491375,0.481263,-0.469292,-0.127941,-0.126791,0.021342,-0.450596,0.040198,0.228691,0.254454,-0.139738,0.108945,0.257626,-0.183185,0.270940,0.066252,0.111173,-0.839606,0.195831,-0.056195,0.250267,-0.528446,0.152493,-0.252461,0.027171,0.138335,-0.238549,0.159097,0.436720,0.327247,0.099394,-0.287956,0.006547,-0.403883,0.047733,0.785550,0.104905,-0.129360,0.054038,-0.206051,-0.443968,0.140433,-0.192228,-0.220270,-0.120566,0.444188,0.064406,-0.060859,0.245318,-0.528168,-0.063836,-0.486671,-0.325846,-0.183364,-0.306478,0.228605,-0.649143,-0.013358,-0.028626,-0.305334,0.146612,-0.056696,-0.184958,0.345288,-0.971055,0.220193,0.618758,0.248866,-0.546809,0.440159,0.201212,0.218498,-0.263826,0.041105,0.119406,0.164052,0.344947,0.146368,0.090260,0.280897,-0.433241,-0.082423,0.406550', '30345227', '1301022', '25908042', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294561', '太极张三丰', '喜剧', '宦官弄权的明朝末年，苛税与暴政弄得民不聊生。张君宝（李连杰）与董天宝（钱小豪）是一对自幼在少林寺长大的师兄弟，但两人性格迥异，张君宝善良忠厚，董天宝则狡猾阴险，在争夺进入达摩院修行的资格时，两人因与师伯发生争执，被逐出少林。出寺后，两人因志向渐不同而分道扬镳，董天宝贪图荣华参军，张君宝则与一群仁人志士一起劫富济贫。为求高官，董天宝向大宦官刘瑾出卖大批旧友，一时间血流成河。为替义士报仇，也为帮民除害，张君宝在秋雪（杨紫琼）的帮助下，从其师傅的气功心法中悟出一套武林奇功“太极拳”，开始勤加练习，准备不日与敌手来场血战。©豆瓣', '李连杰', '袁和平', 8, 148280, 'tt0108281', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p722764652.jpg', 0.1, 1.1, 22.9, 50.7, 25.1, '0.143901,-0.109680,-0.507545,0.535156,-0.005966,-0.536011,0.304977,0.176032,-0.714257,-0.452963,-0.001542,0.640209,-0.105536,-0.035548,0.226558,-0.469745,0.090158,-0.748839,-0.276685,-0.101785,0.100870,-0.432139,0.120382,-0.054039,-0.505985,-0.145190,0.489178,0.197157,-0.232325,0.694675,0.270502,0.007225,-0.303569,0.153757,-0.035215,-0.056429,-0.211012,-0.011933,-0.559075,-0.026435,-0.107924,-0.421503,-0.435421,-0.262653,-0.252435,0.132194,0.372755,-0.185771,0.016584,-0.371925,0.135764,0.239617,-0.076904,0.283258,0.304385,0.079406,0.411461,0.321037,0.092363,0.157690,-0.140513,-0.113067,-0.422634,-0.005200,0.456380,-0.198228,-0.369666,0.499741,0.082583,-0.232599,-0.263707,-0.432106,0.050989,0.557710,0.235985,0.390374,-0.130236,-0.143494,-0.386935,0.150679,0.627428,0.084806,0.479221,-0.104412,0.315879,-0.159761,0.272005,-0.286164,-0.206123,-0.250880,0.491416,-0.374305,0.317901,0.453650,-0.526703,-0.036836,-0.175628,0.524051,-0.059085,0.132079,0.122598,-0.414073,-0.091815,-0.506355,-0.213710,-0.169430,0.421851,-0.289128,0.889159,-0.793207,0.088332,-0.209035,0.064913,-0.691262,0.567388,0.030762,0.428765,-0.088069,-0.375921,-0.032140,0.295071,0.362548,0.161292,0.197643,-0.177025,-0.119917,-0.134501,0.026203', '1480318', '3445516', '3230460', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294562', '虎！虎！虎！', '剧情', '这是一部真实的电影，真实展现了日军偷袭珍珠港的历史。美军插手太平洋战场，日军最高将领山本五十六（山村聪 Sô Yamamura 饰）认为美军实力强大，应速战速战，不宜和美国人打长久战。于是，由他一手策划的偷袭珍珠港行动正式启动了。虽然美军从此前截获的日军密电中得知了日军可能进行突袭的消息，但多数人都对此不屑一顾，密电的内容也没进行上报。即使在突袭当天美军一个士兵发现了雷达上不寻常的飞机群，美军将领仍然认为那是自己的飞机在执行巡逻任务。最终使得日军偷袭行动一举成功，美军损失惨重。山本五十六也成了美国人最大的眼中钉。©豆瓣', '马丁·鲍尔萨姆', '理查德·弗莱彻', 8.3, 24980, 'tt0066473', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1560626387.jpg', 0.2, 0.9, 13.7, 52.5, 32.8, '0.128573,-0.037258,-0.982610,0.734053,0.227097,0.341833,0.020031,-0.286169,-0.326447,0.092762,0.464213,0.552706,0.491753,-0.513206,0.110729,-0.311696,-0.505641,-0.552273,-0.099070,-0.203000,-0.307896,-0.456818,-0.357547,-0.434283,0.160389,-0.223564,0.706972,0.507577,-0.540365,0.258008,0.171099,0.157871,0.182354,0.647065,0.278920,-0.041950,0.242279,-0.506720,-0.065328,0.215340,-0.423836,-0.432445,-0.043745,0.232696,0.088345,0.778372,0.734282,-0.427622,-0.318092,-0.158587,0.005623,-0.565302,-0.028745,0.107658,0.732678,-0.001096,-0.088302,0.060328,0.063693,0.232984,-0.309116,0.224865,-0.708508,-0.134266,-0.007234,-0.141365,-0.021556,0.456517,-0.501785,0.439390,-0.044089,-0.116605,0.167792,0.796552,0.191293,-0.264316,-0.086471,0.149658,-0.504221,0.170085,0.470934,-0.111573,-0.326352,-0.046032,0.012928,-0.354063,-0.009693,-0.671383,0.085241,0.091324,0.322743,-0.066114,-0.156551,0.046489,-0.301475,0.130863,-0.358011,-0.317869,-0.267875,-0.274852,-0.126799,-1.033183,0.036596,-0.337095,-0.546517,0.352397,0.024321,0.178005,0.812330,-0.613303,-0.177895,0.536934,0.267265,-0.387139,0.328732,0.368446,-0.080660,-0.257118,0.228217,0.086818,0.050422,0.549242,0.304886,0.338761,-0.118461,-0.422038,-0.170102,0.053821', '2369613', '1293830', '6007281', '1293013');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294564', '白发魔女2', '动作', '自从邪教魔女练霓裳（林青霞饰）与武当首徒卓一航（张国荣饰）分道扬镳之后，从此销声匿迹。但数年之后魔女却已走火入魔，建立魔宫，并练得天下无敌奇功，四处杀戮正派人士。卓却独自呆守于雪峰顶，待奇花盛开之日再觅爱人芳踪，让昔日爱人重生黑发。适逢武当后人封俊杰（陈锦鸿饰）迎娶点苍派玉女虞琴（万绮雯饰）之夜，魔女再现，杀宾客掳新娘，杰为救虞琴不幸身负重伤。武当派除杰与小师弟绿痕之外，亦无人幸免。杰与绿痕遂联合各派小侠，准备向魔女的魔宫进攻，营救爱妻，誓杀魔女。©豆瓣', '林青霞', '胡大为', 6.6, 20158, 'tt0106343', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2332485913.jpg', 2, 13.1, 50, 24.3, 10.6, '-0.376734,0.203592,-0.069282,0.340665,0.418031,-0.279444,-0.017965,0.086956,-0.299424,-0.246393,0.053740,0.474242,-0.145592,0.202545,0.308861,0.050360,0.021367,-0.786190,0.160745,-0.409667,0.094375,0.235204,0.127078,0.140564,-0.149548,-0.228575,0.917563,0.097204,-0.126802,0.569703,0.094397,0.155565,-0.550144,0.141027,-0.131992,-0.173948,-0.126217,0.253053,-0.503344,0.314458,-0.295786,-0.498287,-0.233410,0.065488,-0.451610,0.239772,0.523933,-0.420108,0.050966,-0.622237,-0.098175,-0.127533,-0.122741,0.021601,0.398412,-0.386945,0.301083,0.426620,0.100590,-0.356388,-0.251755,-0.029752,0.051598,0.185741,0.784585,-0.197583,-0.092260,0.297390,-0.390825,0.283928,-0.234687,-0.173251,-0.031987,0.121545,0.281639,-0.046833,0.079797,-0.152616,-0.250904,0.431290,0.353512,0.038857,0.269755,-0.024155,0.637633,-0.116116,0.235939,-0.352652,-0.210811,0.040349,0.233062,-0.115713,0.423398,0.485366,-0.347931,-0.187079,-0.647079,0.603003,-0.030952,-0.040874,-0.027381,-0.543109,-0.038834,0.213124,-0.003462,-0.146489,0.381371,0.076311,0.615509,-0.534581,0.290842,-0.116805,0.012194,-0.563841,0.366277,-0.173737,0.252226,-0.111535,-0.249876,0.442028,0.019743,0.300157,0.056192,0.040056,-0.252088,0.152699,-0.263777,-0.442270', '1440164', '1780122', '1303390', '1295469');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294565', '五至七时的克莱奥', '剧情', '巴黎，下午五至七时。美丽的女歌手克莱奥（柯琳妮·玛钱德 Corinne Marchand饰）正游荡在巴黎街头。她一袭黑衣，摘掉假发，面无声色地穿越着内心中的恐惧与焦灼。一切都由一份体检报告引发，她担心自己会如占卜的人所言，患上胃癌。忐忑不安的克莱奥游走在巴黎街头、咖啡厅、或是家里，遇到了各类形形色色的男人，她的情人或是朋友，对他们诉说她生命中的每一个段落，但似乎没人真正理解她。直到最后，她遇见了即将远赴阿尔及利亚战场的年轻士兵。在与他的交谈下，克莱奥开始重新看到了世界，坦然地面对现实。由法国女导演阿涅斯·瓦尔达执导的成名作《五至七时的奇奥》，是新浪潮电影中一部举足轻重的作品。本片入围1962年第15届戛纳电影节金棕榈奖。©豆瓣', '科琳娜·马尔尚', '阿涅斯·瓦尔达', 8.7, 21509, 'tt0055852', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2173127960.jpg', 0.2, 0.7, 8, 46, 45.1, '0.064644,0.003370,-0.697420,0.600251,0.150193,-0.037305,0.666552,0.108241,-0.273660,-0.103718,0.335020,0.960302,-0.346460,0.364156,0.286524,0.016742,-0.464921,-0.842559,-0.191494,-0.232486,-0.157777,-0.228264,-0.388597,-0.061669,-0.096610,-0.279732,0.574892,0.330382,0.081464,0.469875,0.320470,0.112871,-0.101152,0.507271,-0.209069,-0.007630,0.212602,0.141804,-0.160549,0.218773,0.056603,-0.243871,-0.399819,0.166605,-0.108790,0.334488,0.710678,-0.218741,0.019005,0.072446,0.602424,-0.121347,0.035634,-0.009756,0.185640,0.088506,0.354228,0.153346,-0.087428,0.069214,-0.167626,0.118340,-0.377130,0.001424,0.091321,0.293533,-0.495479,0.526778,-0.137460,0.132259,0.205690,-0.146615,0.355199,0.052491,0.236453,0.328172,0.136592,-0.225151,-0.402238,0.506668,0.460031,0.292864,-0.436151,0.229981,-0.249444,-0.341906,-0.044780,-0.241706,-0.598719,0.115755,0.190133,0.111808,-0.208717,0.128320,-0.385492,0.066205,-0.005846,-0.247935,-0.083768,-0.218901,-0.193944,-0.770846,0.020032,-0.420509,-0.217288,-0.099779,0.059771,-0.056926,0.673442,-0.531946,0.357649,0.653363,0.238201,-0.166294,0.886735,0.021288,0.021810,-0.118994,-0.090889,0.294486,-0.353384,0.277109,0.034723,0.480240,-0.380308,0.087431,-0.466601,0.479887', '30162520', '25785124', '1299663', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294570', '爱情短片', '剧情', '影片讲述男孩汤马克（欧拉夫·鲁巴斯赞科 Olaf Lubaszenko饰）用天文望远镜偷窥住在对面公寓大厦的女人玛格达（格拉齐娜·扎波罗斯卡 Grazyna Szapolowska饰），不知不觉中迷恋上她的故事。她的一举一动都使汤马克魂牵梦绕，她的一颦一笑更是牵动他所有的神经。透过望远镜，汤马克看到玛格达和男人做爱的情景，迟迟不敢示爱。直到他看到她痛哭失意的时候，汤马克才鼓足勇气提出邀约。可玛格达拒绝了他的表白。汤马克纯真爱情的信念一下倒塌了，此时的他想用自杀来守住这份对爱情的忠贞。自杀没有成功，等他出院的时候，玛格达居然开始迷恋上了他。影片是导演基耶斯洛夫斯基从他的《十戒》中第六个故事发展扩充而成的作品，并荣1988年圣塞巴斯蒂安国际电影节多项大奖。©豆瓣', '格拉日娜·沙波沃夫斯卡', '克日什托夫·基耶斯洛夫斯基', 8.8, 25999, 'tt0095467', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189908788.jpg', 0.2, 0.7, 8.9, 37.2, 52.9, '0.011697,0.026077,-0.747681,0.608380,-0.042948,-0.299557,0.757346,0.150577,-0.150193,-0.065872,0.186843,0.555897,-0.353259,0.353042,0.325653,0.262178,-0.445756,-0.880963,0.059747,-0.067950,-0.237406,-0.393610,-0.138231,-0.234352,0.021736,-0.164557,0.271199,-0.217433,-0.275001,0.153932,0.292642,-0.096631,0.439370,0.520965,0.028029,0.178434,0.224101,-0.307216,-0.015243,0.093403,0.180736,-0.489621,-0.387445,0.314646,-0.080409,0.316638,0.472561,-0.330268,0.119711,0.043409,0.210978,-0.236392,0.145261,0.055156,-0.072008,-0.166471,0.015279,-0.006940,-0.311364,-0.190347,0.115649,-0.043179,-0.548971,-0.059778,-0.175826,0.075477,-0.418107,0.370476,-0.357120,0.399319,0.157972,-0.428134,0.008309,0.052128,0.389014,0.262796,-0.137152,-0.154454,-0.480169,0.149704,0.238294,0.119322,-0.114186,0.414582,-0.328318,-0.407812,-0.121419,-0.043576,-0.548261,0.048097,0.372118,0.043160,0.009759,0.325339,-0.432490,-0.291076,-0.286059,-0.291195,0.086859,-0.196202,-0.254976,-0.543098,-0.276936,-0.182684,-0.326882,-0.065022,-0.169739,-0.265666,0.648148,-0.395832,0.260980,0.556610,0.149950,-0.185599,0.915456,0.051390,-0.270253,-0.099968,-0.148922,0.694294,-0.084447,0.064361,0.238080,0.572503,-0.040653,0.144455,-0.418397,0.766731', '1307146', '26677495', '1293963', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294573', '尤里西斯的凝视', '剧情', '本片开始回顾了一战时第一部反映巴尔干半岛的默片，内容是描述纺织女工生活的场景。主人公（哈威·凯特尔 Harvey Keitel 饰）是个希腊裔美国人，在经历战争洗礼后，他怀着感慨的心情重归故里，寻找电影开始的地方。他跟同伴讲述着曾经在这里度过的岁月，怀旧而伤感。特别是看 到教徒手持火把游行的情景，勾起了他对残酷战争的回忆。最后，他决心逃离。大雪漫天，他要了辆出租车，并答应送一位老人回家乡看看。然而，满目疮痍的战争废墟，让老人无家可归。汽车在雪地里抛锚，他只能登上了列车继续前行。在萨拉热窝，他在电影馆馆长的陪同下，寻找那部默片未果，却和馆长的女儿一见钟情。他高调地进入社交圈，却发现这里已经被前苏联的文化浸染，到处吟唱着喀秋莎的旋律。他曾目睹列宁的雕像被卸开，内心涌动着复杂的感情……本片获得1995年戛纳电影节评委会大奖。©豆瓣', '哈威·凯特尔', '西奥·安哲罗普洛斯', 9.1, 9525, 'tt0114863', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2613245678.jpg', 0.5, 0.7, 6.5, 30.2, 62.2, '0.118198,0.012041,-0.718463,0.661554,0.283474,-0.358774,0.939393,0.034933,-0.498999,-0.135626,0.348839,0.690420,-0.218196,0.319054,0.267825,0.058249,-0.596640,-0.572022,-0.178771,0.083397,-0.123863,-0.185119,-0.110098,-0.147175,0.007001,-0.346772,0.662913,0.500448,-0.196356,0.533839,0.270742,0.034390,-0.104182,0.472359,-0.396025,0.030192,-0.017589,0.142941,-0.298830,0.106115,0.048144,-0.455889,-0.455174,0.026988,-0.040664,0.187230,0.813752,-0.068762,0.010992,0.200901,0.259625,-0.393000,0.036040,0.089005,0.207557,0.270965,0.044258,0.217026,-0.044049,-0.039289,-0.168842,-0.073378,-0.276977,0.126988,-0.212672,0.251987,-0.742026,0.572316,-0.021180,0.109834,-0.048128,-0.226432,0.498721,0.129496,0.215105,0.481914,-0.004276,-0.221309,-0.524926,0.518715,0.709071,-0.166740,-0.219430,0.532468,-0.316626,-0.401220,-0.206763,-0.153370,-0.481917,-0.077118,0.373367,-0.125746,-0.409378,0.186232,-0.624244,0.064233,-0.154552,-0.546099,-0.094589,-0.268271,-0.172884,-0.712176,-0.222472,-0.206675,-0.302534,-0.095598,-0.174748,-0.146818,0.630169,-0.649289,0.263633,0.532487,0.234689,-0.256443,0.810284,0.030709,-0.237176,-0.067599,0.057487,0.541804,-0.243778,0.409843,-0.019342,0.371093,-0.122893,-0.067423,-0.511369,0.519727', '21619567', '3055049', '1467779', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294580', '其后', '剧情', '20世纪初的日本，毕业于东京帝国大学的长井代助（松田优作 饰）家境优渥，全然不曾为金钱烦恼。他终日周游玩乐，过着悠闲自在的高等无业游民的生活。与之相对，和长井相交多年的好友平冈常次郎（小林薰 饰）生活拮据，妻子三千代（藤谷美和子 饰）孕期患上心脏病，未出生的孩子更不幸夭折。承受巨大压力的平冈破罐破摔，流连烟花场所。生计日益紧迫的同时，夫妻情分名存实亡。三千代是长井、平冈大学时代亡友菅沼（风间杜夫 饰）的妹妹，此去经年，始终未婚的长井依然对三千代持有深深的爱慕，他同情对方的境遇，但碍于道德的束缚只能将炽烈的情感深锁心底。深爱无缘，百千心结何处搁置……本片根据夏目漱石的同名原作改编。©豆瓣', '松田优作', '森田芳光', 8.6, 7053, 'tt0091989', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1859987414.jpg', 0.3, 0.9, 11.6, 44.5, 42.8, '0.077014,0.022829,-0.448678,0.372151,-0.108628,-0.211996,0.530420,0.330312,-0.415725,-0.478460,0.071079,0.510584,0.035063,0.426391,0.108192,-0.072394,0.179220,-0.624454,-0.086805,-0.147049,0.088366,-0.454580,-0.206774,-0.011691,-0.575362,-0.171845,0.875986,0.117017,0.127984,0.496027,0.089359,0.619766,-0.270246,0.213380,-0.275295,-0.079418,-0.332575,0.333108,-0.407293,-0.141182,-0.257649,-0.285510,0.018519,0.157316,0.077860,0.340724,0.738016,-0.098319,-0.171533,-0.183637,0.491571,0.149736,-0.207076,0.133618,0.286228,0.145214,0.063247,0.242965,-0.225600,0.015787,-0.047022,-0.036732,-0.367155,-0.183344,0.349397,0.129821,-0.339009,0.660676,-0.216658,-0.288433,0.001480,0.011916,-0.304414,0.218163,0.123450,0.486299,-0.463093,0.230711,-0.058705,0.434758,0.422881,-0.050314,-0.331149,0.152132,-0.453285,-0.235758,0.005021,-0.447783,-0.775997,-0.117708,-0.108979,0.271896,-0.095863,0.510381,-0.489678,0.214967,0.047950,0.144537,0.174074,-0.302572,0.058923,-0.389124,-0.135280,-0.752302,-0.486863,0.041927,0.582853,-0.299133,0.890528,-0.645822,0.115840,0.344286,0.387257,-0.434288,0.533757,0.393807,0.036920,0.031666,0.039500,0.747463,-0.180590,0.016396,-0.005757,0.068597,-0.131708,0.065435,-0.287263,0.603775', '26348103', '5975206', '3811356', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294584', '雌雄大盗', '动作', '本片根据美国历史上著名雌雄大盗邦妮•派克和克莱德•巴罗的真实经历拍摄。1930年大萧条中，邦妮•派克（費•唐娜薇 Faye Dunaway 饰）在得克萨斯州达拉斯市西小镇的母亲家中看到克莱德•巴罗（沃伦•比蒂 Warren Beatty）正在偷自己母亲的汽车。克莱德对 邦妮一见钟情，向她炫耀自己曾因持械抢劫入狱，并当着她的面抢劫了镇上的小超市。二人从此结伴浪迹天涯，以打劫为生，转战德克萨斯、路易斯安那、密西西比和奥克拉荷马州，并拉上了负责修车的莫斯（迈克尔•波拉德 Michael J. Pollard 饰）和克莱德的哥哥巴克•巴罗（吉恩•哈克曼 Gene Hackman 饰）及其妻布兰奇（埃斯特尔•帕森斯 Estelle Parsons 饰）结成巴罗帮，名噪一时。本片获1968年奥斯卡最佳男主角、女主角、男配角，最佳服装设计、最佳导演、最佳影片和最佳剧本八项提名，并获奥斯卡最佳女配角奖（埃斯特尔•帕森斯）和最佳摄影奖。', '沃伦·比蒂', '阿瑟·佩恩', 8.2, 44877, 'tt0061418', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2359309071.jpg', 0.3, 1.2, 16.1, 52.1, 30.3, '0.095091,-0.327855,-0.433238,0.505773,0.414756,-0.492652,0.559558,0.175508,-0.362572,-0.251196,-0.047529,0.989117,-0.290680,-0.184333,0.544367,0.418783,-0.924708,-0.516674,-0.022585,-0.223239,0.132268,-0.482750,-0.567571,-0.134982,-0.161384,-0.433833,0.174081,-0.388422,0.034547,0.675724,0.744084,0.366564,-0.128108,-0.160747,0.127676,0.280471,0.369498,-0.118881,-0.645458,0.357030,0.011763,0.015029,-0.414959,-0.141360,0.417084,0.445237,0.464776,-0.143186,0.329249,-0.224999,0.226196,-0.190873,0.061141,-0.064753,-0.053272,-0.456311,0.400529,0.265735,-0.118735,0.131659,0.311810,-0.277860,-0.330755,0.100271,0.033419,0.124486,-0.296195,0.159331,-0.470604,0.035353,0.174355,-0.100560,-0.060005,0.387222,0.083085,0.075756,0.006353,-0.189602,-0.303979,0.442531,0.258848,0.084305,-0.127419,-0.124419,0.076590,-0.601336,0.106858,-0.242387,-0.387811,-0.039099,0.522232,-0.156884,0.245963,0.314841,-0.401971,-0.188341,-0.351433,-0.175660,-0.087762,0.027873,0.099570,-1.077604,0.196872,-0.415416,-0.204716,-0.052637,0.052955,-0.254486,0.235700,-0.425970,0.335243,0.308851,0.422547,-0.032683,0.478297,-0.072875,0.293174,-0.556682,-0.520371,0.339925,0.164814,0.156633,0.120220,0.299194,0.074480,-0.371070,-0.247463,0.598748', '2075345', '1298616', '34961898', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294587', '致命诱惑', '剧情', '丹（迈克尔·道格拉斯 Michael Douglas 饰）拥有着人人羡慕的幸福家庭，他和妻子贝丝（安妮·阿彻 Anne Archer 饰）之间的感情稳固而又长久，女儿艾伦（Ellen Hamilton Latzen 饰）更是机灵可爱。一次偶然中，不只是鬼迷心窍还是怎地， 丹竟然和一个名叫艾利克斯（格伦·克洛斯 Glenn Close 饰）的女人有了一段露水情缘，回家后面对妻儿，丹的内心充满了愧疚，他暗暗发誓，绝不让背叛再度发生。可惜艾利克斯并不同意但的看法，表面上，她是一个成熟稳重的知性派，可骨子里，艾利克斯却拥有着超越常人的偏执和固执，为了满足自己的私欲，她不断的骚扰着丹及其家庭，很快，这种骚扰变升级成为了犯罪。面对来势汹汹的艾利克斯，丹会选择怎样的对策来保护他的家庭呢？©豆瓣', '迈克尔·道格拉斯', '阿德里安·莱恩', 7, 5797, 'tt0093010', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359577198.jpg', 1, 4.9, 45.6, 38.3, 10.2, '0.410411,0.332632,-0.739758,0.967081,-0.233679,-0.189234,0.497702,-0.061779,-0.429189,-0.313356,0.019528,0.766399,-0.132182,0.273858,-0.189083,0.118399,0.081230,-0.429106,0.072063,-0.093041,-0.288637,-0.427708,-0.249812,-0.138838,-0.271695,-0.331786,0.615779,0.070961,-0.023433,0.407925,0.293566,0.431940,0.438751,0.470287,0.072474,0.037557,0.023394,0.024503,0.031742,0.150097,0.437251,0.070330,0.068242,0.470409,-0.056927,0.382671,0.423501,-0.292755,-0.211321,-0.192049,0.495765,-0.213355,0.098305,0.180265,0.044471,-0.121182,0.005405,0.108027,-0.381807,-0.108582,0.192815,0.001474,-0.774115,-0.165584,0.128129,0.084826,-0.525238,0.286325,-0.069493,0.035133,0.139563,-0.018969,-0.153804,0.314506,0.271052,0.427202,-0.248729,-0.176110,-0.558681,-0.155758,0.771870,0.276186,-0.284791,0.392436,-0.608995,-0.301421,0.025263,-0.472565,-0.708558,-0.077655,0.013839,0.107668,0.009464,0.384816,-0.393511,0.130568,-0.367194,0.396809,0.095541,-0.627260,0.174795,-0.303027,-0.077540,-0.541394,-0.611971,0.077552,0.104222,-0.573542,0.768309,-0.784531,-0.032823,0.411197,0.362225,-0.567504,0.552610,0.151048,-0.195662,-0.240963,-0.166934,0.669034,0.041152,-0.284571,0.121529,0.233154,0.078998,0.087661,-0.272720,0.493909', '1309177', '30163500', '3318473', '26981174');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294588', '御法度', '剧情', '1865年夏的京都，德川幕府创建的法度森严的新撰组遴选新队员，下级武士田代彪蔵（浅野忠信）和美少年加纳惣三郎（松田龙平）因剑术出类拔萃被选中。初入队，加纳即出色地完成处决破坏法度的队员的命令。队中有人传言加纳和田代是一对，同时加纳与另一队员汤泽藤次郎也保有暧昧关系，不久，汤泽被杀，几番带加纳去欢场的山崎也遭人偷袭，新撰组正负组长近藤和土方（北野武）根据现场留下的短刀将田代定为凶手，并命加纳前去讨伐田代，然而实际上，一切死亡事件都系加纳精心策划，他的美貌已经使整个新撰组陷入混乱中。©豆瓣', '松田龙平', '大岛渚', 7.4, 25538, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1918779702.jpg', 0.7, 4, 36.6, 42, 16.8, '-0.092405,-0.041819,-0.299833,0.296727,-0.219760,-0.158383,0.245055,0.063579,-0.502647,-0.433722,0.289308,0.699270,-0.159333,-0.074978,0.745927,0.037262,-0.081164,-0.703522,-0.404079,-0.013440,-0.087879,-0.526824,-0.065648,-0.273789,-0.140041,-0.197497,0.829727,0.133067,-0.180132,0.542299,0.149126,0.467913,-0.243752,0.100046,0.417819,0.162122,0.309467,-0.382461,-0.296711,0.064279,-0.553027,-0.215588,-0.396455,-0.064301,0.158610,0.497251,0.530621,-0.333462,0.105393,-0.313155,0.190248,-0.324706,-0.242833,0.304855,0.677847,0.135035,-0.062701,0.404298,-0.032996,-0.051004,-0.227065,-0.121071,-0.512716,-0.161299,0.235471,-0.011871,-0.127670,0.394789,-0.288493,-0.093730,0.295168,-0.025340,-0.130071,0.216071,0.333965,0.074009,-0.024798,-0.033059,-0.084947,-0.129797,0.454722,-0.190806,-0.122436,-0.438527,0.029542,-0.625874,-0.195543,-0.318145,0.011673,-0.090774,0.258622,0.120724,0.182021,0.243757,-0.367323,-0.111678,-0.191754,-0.035514,0.066853,-0.060847,0.079191,-0.687600,0.188687,-0.198820,-0.419699,0.101116,0.248455,0.079235,0.609111,-0.668483,0.140925,0.341062,0.182800,-0.214374,-0.003440,0.194332,0.193741,-0.038039,-0.185460,0.069329,0.515158,0.526317,0.352977,0.473292,-0.238404,-0.319495,-0.281415,0.059950', '25723905', '26615753', '2369613', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294589', '弹簧刀', '剧情', '天生智能障碍的卡尔（比利•鲍伯•松顿 Billy Bob Thornton 饰）生于一个不幸的家庭：迷信宗教的父母总把他当作上天对他们的惩罚，因而十分厌恶他，老是虐打他。自小生活在阴影中的卡尔，8岁的某天撞见了母亲和一名拉皮条的人偷情，压抑的情绪瞬间爆发，他用弹簧刀将两人都刺死了。自此以后的25年岁月里，卡尔都在精神病院里度过。出院那天，无家可归的卡尔被精神病院的管理员收留了一个晚上，这是他第一次感到人间的温暖。出院后，人们都想躲瘟神般躲着卡尔，直至他遇上了好友弗兰克（卢卡斯•布莱克 Lucas Black 饰）。弗兰克将他当成自己最好的朋友，卡尔在生活里看到了阳光。然而最近，弗兰克一家被其母亲的酒鬼男友搞得鸡犬不宁。看到朋友受罪，忍无可忍的卡尔，决定挺身而出。©豆瓣', '比利·鲍伯·松顿', '比利·鲍伯·松顿', 8.1, 7730, 'tt0117666', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2320535786.jpg', 0.4, 1.8, 18.4, 51.2, 28.3, '0.451494,-0.138313,-0.635649,0.456774,-0.313182,-0.401373,0.837809,0.093542,-0.442060,-0.222090,0.270362,0.840887,-0.310124,0.668625,0.358035,0.160765,-0.257168,-0.647204,-0.015150,-0.143123,-0.182060,-0.123504,-0.239678,-0.304962,-0.124964,-0.174439,0.323552,-0.101456,0.050748,0.227568,0.067923,0.329072,0.274690,0.550340,-0.275096,0.087149,0.071921,-0.053845,0.031691,0.223419,0.093982,-0.147211,0.058857,0.305526,-0.075042,0.315179,0.528870,-0.273135,-0.060483,-0.236224,0.282096,-0.289612,-0.226378,0.325551,0.179388,-0.105773,0.157717,0.061642,-0.345453,-0.015244,0.134743,-0.020291,-0.532639,0.025242,-0.086917,0.015603,-0.636421,0.558508,0.016436,0.147415,0.140989,-0.241571,0.321513,-0.034730,0.074483,0.486655,-0.387422,0.043588,-0.466283,0.284554,0.749059,-0.441825,-0.311560,0.243300,-0.379993,-0.148032,0.262067,0.006172,-0.710367,-0.230022,0.423497,-0.208431,-0.466629,0.319734,-0.542452,-0.137739,-0.154698,0.048711,-0.351728,-0.523367,-0.109482,-0.274813,-0.181295,-0.390733,-0.417102,0.038777,-0.026627,-0.208707,0.388467,-0.537264,0.306781,0.629101,0.212786,-0.177811,0.797083,0.153576,0.202359,-0.069420,-0.022546,0.444693,0.199341,0.374133,0.265313,0.437993,-0.017691,0.106851,-0.261894,0.653429', '1297606', '30162520', '1309172', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294595', '红色小提琴', '剧情', '三百年来，一把红色小提琴在数个国家流浪，与数人的命运紧紧相牵。仿佛有某种魔咒，让人们为这把琴疯狂着迷。小提琴的制造者，是十七世纪意大利的乐器大师（卡路•施齐Carlo Cecchi 饰 ）。妻儿死去，难抑悲伤的他，把爱人的血涂在小提琴上，从此琴就辗转流落到了奥地利。一个练琴的小男孩为了这把琴痴迷，直至倒落在舞台上。小提琴的流浪从未间断，从盗墓者，到吉普赛人，到为之自杀的作曲家波普，再到文革期间上海的一位音乐老师。这期间，无论拥有者是否明白小提琴真正价值，都逃不出它的魔力。终于，有鉴别专家知道了小提琴的秘密——它的外壳染着三个世纪前一位大师的血和泪。©豆瓣', '卡洛·切基', '弗朗索瓦·吉拉德', 8.2, 16372, 'tt0120802', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1486350295.jpg', 0.3, 1.5, 18.1, 48.2, 32, '0.125477,0.246042,-0.703231,0.647507,-0.028715,-0.285496,0.849081,-0.067707,-0.201910,-0.208588,0.291627,0.836620,0.047321,0.504014,0.208544,0.005366,0.000730,-0.979491,0.003389,-0.259614,-0.559690,-0.244746,-0.146517,0.186507,-0.250990,-0.495377,0.506096,-0.073221,-0.066575,0.309401,0.278659,0.243740,-0.142985,0.030634,-0.486706,-0.121596,0.045314,0.094694,-0.083780,0.061444,0.156142,-0.570777,-0.072018,-0.059750,-0.423269,-0.027192,0.880691,-0.271514,0.322256,0.246074,0.353930,-0.261104,-0.040150,-0.019329,0.141620,0.232440,-0.133824,0.034844,-0.423722,0.050357,0.193006,-0.035115,-0.848990,0.014487,-0.096499,0.385067,-0.698121,0.555203,-0.142079,-0.137042,-0.137395,-0.458478,0.606561,0.108683,-0.032871,0.456740,-0.367550,-0.054152,-0.467678,0.468928,0.577447,-0.169884,-0.090989,0.290966,-0.048335,-0.599928,-0.175039,-0.508598,-0.509630,-0.017271,0.413832,0.016816,-0.272166,0.062492,-0.863121,-0.098478,-0.106927,-0.191997,0.098061,-0.227140,-0.083348,-0.339518,-0.176528,-0.357780,-0.128835,0.058879,0.285069,-0.363028,0.975991,-0.764251,0.414676,0.771577,-0.118241,-0.092435,0.603835,-0.144316,0.015633,0.092143,-0.309755,0.334576,0.131086,0.486415,0.178361,0.703480,0.254547,0.231062,-0.553601,0.630228', '1307146', '30162520', '25928048', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294605', '战地军魂', '剧情', '二战时期，一批美国战俘被关押在德军的监狱里，故事就发生在17号监狱（Stalag 17）。有两名囚犯想要越狱，却被德军所杀，监狱里的囚犯们开始怀疑他们其中有人出卖了他们。大家都把嫌疑集中在一个人身上——狡猾的Sefton（威廉·霍尔登 William Holden 饰）身上。Sefton虽然也是个囚犯，但他靠组织“赛马”、卖酒还有出租望远镜赚了不少钱。不久，一位美国中尉Dunbar（Don Taylor 饰）被抓进狱中。他在法兰克福火车站制造了爆炸案炸死了不少德军。然而此事随即被德军军官Oberst von Scherbach（奥托·普雷明格 Otto Preminger 饰）所获悉。Sefton被认为就是那个泄露了消息的内奸，挨了一顿揍。然而他依旧宣称自己是无辜的。Dunbar即将被纳粹军处死。到底谁才是真正的内奸？到底中尉Dunbar能否逃过一劫？本片主演威廉·霍尔登获1954年奥斯卡影帝，导演比利·怀尔德也获得最佳导演提名。', '威廉·霍尔登', '比利·怀尔德', 8.5, 6082, 'tt0046359', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2205714500.jpg', 0.2, 0.7, 11.5, 50.2, 37.4, '0.194959,-0.113198,-0.583215,0.252890,-0.235334,-0.083723,0.787702,-0.220662,-0.389854,-0.117071,0.403041,0.735249,-0.147298,0.086730,0.019549,0.120743,-0.352734,-0.588753,-0.069196,-0.397188,-0.242005,-0.389995,-0.486339,-0.172903,-0.004432,-0.197937,0.455492,0.080785,-0.127073,0.053701,0.564855,0.452289,0.156466,0.466297,-0.172982,0.251069,0.592413,-0.587315,0.185031,0.184911,-0.220814,-0.665461,-0.241986,0.196871,0.093308,0.498540,0.515216,0.002883,-0.098220,-0.019450,0.103264,-0.421791,-0.032438,0.324524,0.467003,0.040934,0.155961,0.413866,-0.102051,0.046824,0.108596,0.154496,-0.673989,-0.050489,0.084648,0.020650,-0.537464,0.330954,-0.289006,0.256741,-0.159209,0.012974,0.432687,0.286011,0.101263,0.166364,-0.089550,-0.088956,-0.870163,0.266839,0.686927,-0.394575,-0.158578,0.031374,0.077264,-0.426891,0.072726,-0.172720,-0.234014,0.212850,0.677322,-0.420431,-0.141556,0.134492,-0.262494,-0.032731,-0.541900,-0.322488,-0.416814,-0.211273,-0.136207,-0.428589,-0.165301,-0.131024,-0.316864,0.073113,0.129342,0.125107,0.601771,-0.418105,0.094381,0.727031,0.149586,-0.477618,0.446507,0.149352,0.006962,0.121910,-0.018016,-0.133980,0.500715,0.346119,0.394095,0.536332,-0.109255,-0.625067,-0.119590,0.257785', '1301345', '1294941', '1309116', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294616', '致命武器4', '动作', '马丁（梅尔·吉布森 Mel Gibson 饰）和罗杰（丹尼·格洛弗 Danny Glover 饰）是相识多年的老友兼同事，两人都是警察。一次在与共同的好友盖茨（乔·佩西 Joe Pesci 饰）相约出海的途中，三人偶遇了一艘非法偷渡的船只。身为警察的马丁自知绝不能对此坐视不管，于是展开了与黑道分子的激烈斗争。在这批偷渡客中，有一位名为阿洪（高雄 饰）的男子，善良的罗杰收留了他和他无处可去的家人，没想到正是这一举动激怒了危险的黑帮教头王（李连杰 饰），为了从罗杰的手里将洪抢走，王不惜干下了许多伤天害理的勾当。在阿洪的身上究竟隐藏了怎样的秘密？王千方百计的想要得到阿洪又究竟是为了什么？©豆瓣', '梅尔·吉布森', '理查德·唐纳', 6.5, 5791, 'tt0122151', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2397284423.jpg', 2, 9.9, 57.3, 24.4, 6.3, '0.366416,-0.146138,-0.638924,0.637408,-0.156372,-0.331334,0.763261,-0.055810,-0.815845,-0.353296,0.145086,0.853003,-0.156316,0.081847,0.292532,-0.009726,-0.194204,-0.726298,-0.266933,-0.059000,-0.260684,-0.558372,-0.483007,-0.299648,-0.097273,-0.062310,0.319489,0.156876,-0.233839,0.420418,0.676377,0.472446,-0.331075,0.456663,-0.168363,0.101888,0.154706,0.116832,-0.376280,-0.116978,0.133635,-0.461931,-0.152201,0.026960,0.175987,0.485163,0.534947,-0.305349,-0.060926,0.002462,-0.003950,-0.355807,0.268725,0.076061,0.373233,-0.150765,0.060587,0.251403,-0.203249,-0.152282,0.390698,0.167985,-0.855442,-0.091077,0.249030,0.162418,-0.755037,0.282683,-0.253251,-0.070820,0.079968,-0.289241,0.252032,0.622997,0.112359,0.071527,0.148407,-0.149378,-0.633993,0.240216,0.841435,0.190462,0.094698,-0.004041,-0.092603,-0.461871,-0.215663,-0.282929,-0.309049,-0.087040,0.647586,-0.234448,-0.035707,0.311600,-0.585424,-0.381312,-0.325439,0.071859,0.118705,-0.390762,-0.128949,-0.414935,0.088774,-0.582205,-0.021738,0.290173,0.098283,-0.171582,0.613128,-0.967256,0.169230,0.561714,0.039916,-0.557427,0.520737,0.113175,0.078028,-0.210949,-0.202668,-0.142859,0.390954,0.207760,0.252064,0.398747,0.152671,-0.277696,0.036868,0.084240', '1301022', '1783461', '25721544', '1297418');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294621', '神秘拼图', '剧情', '林肯（丹泽尔•华盛顿 饰）因为公务导致全身瘫痪，他曾是享誉一时的侦探，破案无数，但自从他瘫痪后他便把自己封闭起来。这次，他因为一宗神秘的杀人案，受到了纽约警察的邀请帮忙，刚开始林肯是拒绝邀请的，但看到案情后便对此案产生了情绪。纽约最近发生了神秘的碎尸案，凶手还故意留下证据挑战警方。巡逻警艾米利亚（安吉丽娜•茱莉 饰）在最后一次巡逻中发现了一具被肢解的尸体，可是当她做出一系列大胆的推测的时候，同僚们都不愿理她，认为她不过是名籍籍无名的巡警。可是艾米利亚的敏感与勇敢受到了林肯的赏识，他要求与这名新手一起突破案件。两人出奇的合作愉快，终于了解到了杀手是有暴力倾向的，而且杀人前都会周密的安排。经过他们的默契又能否成功捉拿变态杀人犯呢？©豆瓣', '丹泽尔·华盛顿', '菲利普·诺伊斯', 7.4, 59335, 'tt0145681', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2222701213.jpg', 0.4, 3.1, 35.8, 47.7, 13, '0.359040,-0.042450,-0.743063,0.491137,-0.199912,-0.060141,0.697890,-0.169834,-0.735162,-0.226163,0.326553,0.694520,-0.336662,0.113118,0.200087,0.019520,-0.309326,-0.969069,-0.005069,-0.087872,-0.463416,-0.591708,-0.285180,-0.286326,-0.011435,-0.231482,0.275523,0.256902,-0.297630,0.387717,0.278619,0.267334,-0.048754,0.743857,-0.140507,0.017243,0.343557,-0.037683,0.026322,0.204887,0.268458,-0.463083,-0.071019,0.380044,-0.029909,0.698619,0.435942,-0.158787,-0.611283,-0.006295,0.413649,-0.364107,0.055461,0.372583,0.564070,0.254479,0.189985,0.398463,-0.204952,0.000209,-0.040049,0.237442,-0.743408,0.070072,-0.040009,0.008777,-0.507484,0.190642,-0.104039,0.017251,-0.081591,-0.336913,0.302088,0.327914,0.348961,0.067831,-0.072022,-0.090040,-0.432453,-0.024509,0.754517,-0.036517,-0.380356,0.222251,-0.141446,-0.551462,0.038015,-0.257170,-0.065971,0.182056,0.222938,0.070803,-0.254601,0.092777,-0.399843,-0.222922,-0.440407,-0.124603,-0.380414,-0.123447,0.021080,-0.604089,-0.169737,-0.292737,-0.435240,0.029897,-0.067151,-0.333619,0.481118,-0.816957,0.195960,0.660770,0.287119,-0.693865,0.450170,0.132293,-0.009269,0.097685,-0.090943,-0.235200,0.174445,0.415847,0.311069,0.387638,0.189742,-0.439819,-0.223430,0.257402', '35073886', '1301022', '3263169', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294634', '玫瑰之名', '剧情', '中世纪，一个修道院发生了一起教士莫名死亡的事件，修道院的主教遂邀请了异地的名声极好的教士William von Baskerville（肖恩·康纳利 Sean Connery 饰）和他的助手Novize Adson von Melk（克里斯汀·史莱特 Christian Slater 饰）来到修道院调查案件。William在调查中，发现他遭到了许多无形的阻挠和他人的警告，他隐约感觉到这个修道院背后的许多阴谋。更可怕的是，又有几个修道院里的人纷纷遇害，案件变得越来越扑朔迷离。William在不断深入的调查中，也越来越接近真相......本片根据意大利作家安倍托·艾科的同名小说改编，获1988年英国学院奖最佳男演员和最佳化装奖。©豆瓣', '肖恩·康纳利', '让-雅克·阿诺', 7.8, 7141, 'tt0091605', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1798309781.jpg', 0.4, 1.9, 24.3, 51.9, 21.5, '0.568523,-0.356831,-0.546052,0.698244,0.225407,0.055405,1.012861,-0.013561,-0.644551,-0.476606,0.178470,1.034034,-0.501548,0.174468,0.382568,-0.045922,-0.444016,-0.808153,-0.144391,-0.379631,-0.251036,-0.583044,-0.536295,-0.195866,-0.264032,-0.356839,0.614122,0.301206,-0.202217,0.353136,0.236784,0.392776,-0.173725,0.427492,-0.056236,0.178239,0.447450,-0.115150,0.134390,0.263943,0.161299,-0.489415,-0.177537,0.285653,-0.047881,0.469670,0.584331,-0.226846,-0.167398,-0.037209,0.763215,-0.328758,-0.093550,0.198698,0.550150,0.046465,0.008957,0.387168,-0.430577,-0.049380,-0.189399,-0.057852,-0.686520,0.230141,0.434977,0.484632,-0.586038,0.013633,-0.056789,-0.062518,0.179866,-0.037261,0.336794,0.304283,0.050894,0.151629,0.042951,-0.230241,-0.538647,0.246271,0.478263,-0.099079,-0.232045,-0.005564,-0.239621,-0.531818,-0.172588,0.024707,-0.288020,0.011162,0.436585,-0.087539,-0.027311,0.416034,-0.603487,-0.163342,-0.212261,-0.285437,-0.283673,-0.263138,0.065685,-1.068992,-0.500080,-0.364448,-0.081540,0.007475,0.109073,-0.199792,0.450913,-0.696226,0.246197,0.541750,0.124864,-0.234676,0.474034,-0.046440,0.120582,-0.122825,-0.255935,0.186638,0.224179,0.243566,-0.055970,0.555402,0.112859,-0.361220,-0.309366,0.360331', '1316693', '10466639', '1293433', '26990609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294638', 'E.T.外星人', '剧情', '小埃利奥特（亨利托马斯）发现一个意外走失的小外星人，他悄悄的收留了小外星人，并把他介绍给自己的哥哥和妹妹。孩子们与外星人友好的相处，给他吃巧克力，带他去郊外寻找家人留下的痕迹，并为小外星人的种种特异功能兴奋不已。渐渐的埃利奥特与外星人之间形成了某种奇妙的联系，跨越了言语沟通的障碍。可是不久，外星人的存在被大人们知晓，无情的追捕行动展开了。ET被抓进实验室，小埃利奥特也一病不起。孩子们愤怒了，他们自发组织起来，营救外星人。埃利奥特也在心灵的感召下苏醒过来，加入营救行动。他们能成功么？©豆瓣', '亨利·托马斯', '史蒂文·斯皮尔伯格', 8.6, 312907, 'tt0083866', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p984732992.jpg', 0.2, 0.7, 11.6, 44.9, 42.6, '0.329162,-0.059561,-0.676924,0.387642,-0.301333,-0.142707,0.641480,-0.096142,-0.501297,-0.147890,-0.044202,0.814223,-0.246402,0.167835,-0.144291,-0.030721,-0.438412,-0.581898,0.033397,-0.236734,-0.449965,-0.426702,-0.344952,-0.349629,0.122214,-0.234389,0.286390,-0.157699,-0.445534,0.524599,0.154716,-0.146870,-0.120331,0.469389,-0.304443,0.263337,-0.148625,-0.151722,-0.206818,-0.044500,-0.047737,0.099634,-0.059893,0.084363,-0.048506,0.494778,0.788057,-0.489501,-0.157038,-0.333135,-0.024378,-0.405086,0.227630,0.298700,0.000382,0.294054,-0.029472,0.023462,-0.023515,-0.018589,0.055365,-0.060304,-0.656052,0.269277,-0.129911,0.139114,-0.451376,0.261304,0.230524,0.031367,0.226429,-0.475141,0.171929,0.490092,0.195593,0.362691,-0.315302,0.070511,-0.414613,-0.070892,0.640636,-0.159938,-0.158416,0.268438,-0.231668,-0.459956,-0.011076,-0.061867,-0.233927,0.036523,0.545293,0.171087,-0.537488,0.560607,-0.787109,-0.082441,-0.367124,-0.047622,-0.157519,-0.642438,0.161075,-0.839699,-0.115276,-0.149604,-0.269213,0.155821,0.139861,-0.107551,0.868924,-0.634600,0.416317,0.606516,0.598521,-0.664544,0.483890,0.139428,-0.053745,-0.202506,-0.086980,0.134408,0.258743,0.585623,0.502110,0.375038,-0.174316,0.190900,-0.510839,0.098446', '3811356', '3007297', '11541282', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294639', '勇敢的心', '剧情', '威廉•华莱士童年时，其父、苏格兰民族英雄马索•华莱士在与英军的斗争中牺牲，他开始接受父亲好友的指导，学习苏格兰文化和武术。青年华莱士（梅尔•吉布森）学成回到故乡，向美丽的少女梅伦求婚，不想梅伦被英军抢去且遭杀害。在广大村民“英雄之后”的呼声中，华莱士率众揭竿起义，并与苏格兰贵族罗伯结成联盟，但不久他发现，苏格兰贵族考虑的只是自身的利益。英王为缓和局势，派伊莎贝拉（苏菲•玛索）前去和华莱士谈判，由于英王只想收买华莱士，根本不顾苏格兰人民的自由和平等，谈判失败，但这一切并不为伊莎贝拉所知。伊莎贝拉归国后发现事情真相，且知晓英王正策划阴招，忙送信给华莱士，而两人的爱情，也在战争与阴谋中悄然滋生。©豆瓣', '梅尔·吉布森', '梅尔·吉布森', 8.9, 534575, 'tt0112573', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2004174709.jpg', 0.2, 0.7, 8.7, 34.2, 56.3, '0.342389,-0.057506,-0.580869,0.614146,0.097200,-0.395304,0.549791,-0.008487,-0.623754,-0.503991,-0.041656,0.882362,0.018186,0.020613,0.489991,-0.136156,-0.579935,-0.909061,0.045434,0.071378,-0.118143,-0.746407,-0.073256,-0.412469,-0.231823,-0.372632,0.791192,0.143627,-0.333440,0.626321,0.264430,0.206990,-0.038928,0.575636,0.183865,0.078847,0.115907,-0.153137,-0.671865,0.321757,0.120217,-0.187623,-0.378410,0.336529,0.062047,0.404353,0.332299,-0.499711,0.155072,-0.355610,0.158781,-0.312391,0.190397,0.323224,0.112347,0.026425,0.103176,0.323379,0.099114,0.115741,-0.181575,-0.157721,-0.354205,0.036974,-0.000237,0.173018,-0.415038,0.539034,-0.211608,-0.101080,0.013661,-0.232560,0.015966,0.586316,0.243906,0.145265,-0.125581,-0.064884,-0.467441,-0.068019,0.530382,-0.100985,-0.048446,0.123754,-0.186783,-0.489717,0.278748,-0.247206,-0.269953,-0.094624,0.172087,0.208297,0.101099,0.603434,-0.514231,-0.118413,-0.479830,-0.144106,-0.019244,-0.486205,0.111900,-0.616234,-0.328003,-0.377820,-0.197761,-0.105085,0.274251,-0.143797,0.412289,-0.823391,0.169158,0.453146,0.340896,-0.544017,0.323713,0.122253,0.326335,-0.213010,-0.337008,0.357952,0.147718,0.132418,-0.078926,-0.054780,0.032353,-0.286548,-0.255139,0.157026', '30345227', '1780122', '24325856', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294671', '中华英雄', '剧情', '1913年，钱无义（徐锦江饰）带了洋人来夺家传之宝，华家人惨遭灭门。华英雄（郑伊健饰）在怒火中杀光洋人。他忍痛与妻子洁瑜（杨恭如饰）暂别，远避美国当苦工谋生，却承受着种族歧视的不公待遇，华英雄反抗出走。洁瑜带着身孕赴美，得中华楼老板元武（元彪饰）相助，而英雄也被鬼仆救 出，夫妻相聚。洁瑜诞下龙凤双胞胎之夜，中华楼遭“五术人”纵火，洁瑜身亡，女婴被掳走，男婴被好友生奴（林晓峰饰）收养。华英雄为了报仇，苦练师父金傲（黄秋生饰）的《中华傲决》武功。十六年后，华英雄之子华剑雄（谢霆峰饰）欲寻生父，但华英雄以“天煞狐星”为由，不肯亲近儿子，最终在纽约自由女神像上，与仇人“五术人”的师父无敌（吴镇宇饰）决斗……©豆瓣', '郑伊健', '刘伟强', 6.5, 57250, 'tt0203672', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190247886.jpg', 1.8, 11, 55.6, 24.3, 7.2, '-0.322316,-0.056926,-0.439664,0.238996,0.184193,-0.308967,0.295368,0.186589,-0.502660,-0.238250,0.306536,0.581278,0.056316,0.217073,0.085411,0.107609,0.206457,-0.430011,0.010379,-0.101244,-0.037554,-0.182589,-0.063274,-0.092457,-0.268428,-0.162122,0.316007,-0.115377,0.090880,0.602673,0.508790,0.140757,-0.160301,-0.099653,-0.269826,0.137169,-0.209909,0.169507,-0.442591,0.107315,-0.200489,-0.320565,-0.211262,0.024208,-0.194358,0.375413,0.491521,-0.261579,0.354183,-0.580814,0.072634,-0.277961,-0.195392,0.180593,0.122534,-0.084186,0.188920,0.396393,-0.067806,-0.219792,0.252863,0.069105,-0.423921,0.267414,0.397836,-0.073411,-0.558041,0.600558,-0.375956,0.266185,-0.040912,-0.231980,0.180973,0.092149,0.096474,0.249954,-0.229310,0.004475,-0.514371,0.381685,0.536754,-0.403050,0.396992,-0.063055,0.048054,-0.228639,0.282827,-0.479856,-0.264255,-0.161661,0.330793,-0.160518,0.036283,0.187924,-0.453401,-0.382382,-0.313866,0.590987,-0.069487,-0.113977,0.141193,-0.276434,-0.038891,-0.135756,-0.198948,0.105935,0.185229,-0.196950,0.709167,-0.619651,0.187692,0.187084,0.377130,-0.767390,0.552192,0.127977,0.233490,-0.188128,-0.119937,0.300026,0.183368,0.053969,0.227485,-0.102883,-0.132466,0.054950,-0.009801,-0.079726', '1296770', '1305915', '3445516', '1419416');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294689', '中央舞台', '剧情', '12个满怀梦想的年轻人考入了美国芭蕾舞学院，一场关于青春与激情的“人生舞蹈剧”上演了。由于年终将有6人能有机会进入美国国家芭蕾舞剧团，年轻人都开始了精心准备决定他们的前途的那一场年终表演。舞蹈执导乔纳森（彼得•盖勒 Peter Gallagher  饰）和芭蕾舞演员库珀 （Ethan Stiefel 饰）因成为情敌而针锋相对，他们年终将各自执导一部芭蕾舞剧而令到气氛愈加紧张。乔纳森选中了优秀的莫瑞安（苏珊•梅•普拉特 Susan May Pratt  饰）和极具天赋的爱娃（佐伊•桑塔纳 Zoe Saldana  饰），他要将一出经典的芭蕾舞剧完美无暇的进行诠释；而库珀则选中了不够完美的朱迪（阿曼达•舒尔Amanda Schull 饰），他决定要上演一出完全颠覆全统的芭蕾舞剧。经典与颠覆之战将最终决定这3个女孩的归宿！©豆瓣', '彼得·盖勒', '尼古拉斯·希特纳', 8.2, 8458, 'tt0210616', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p783126245.jpg', 0.1, 1, 18.6, 49.4, 30.9, '0.095316,0.016606,-0.697646,0.702132,0.050859,-0.235291,0.568093,0.045496,-0.417009,-0.210165,0.061833,0.730186,-0.495278,0.134672,0.844561,-0.324609,-0.409780,-0.779836,-0.110818,-0.184503,0.049962,-0.333731,-0.162271,-0.170714,-0.091020,-0.351659,0.811617,-0.066000,-0.140674,0.422218,0.497549,0.203080,0.155714,-0.095267,0.258462,-0.047940,0.236018,0.046675,-0.381600,0.210449,0.129082,-0.058064,-0.168472,0.120755,-0.188259,0.170360,0.755347,-0.311068,0.139400,-0.117230,0.527844,-0.208763,0.064500,0.028943,0.067474,0.049409,0.076999,0.226699,0.005521,-0.025608,0.113448,-0.415195,-0.839283,0.155651,0.368530,-0.054765,-0.371714,0.665664,0.042476,0.035508,0.015126,-0.230126,-0.077380,0.143425,0.736109,0.363834,-0.017628,-0.010204,-0.360841,0.593541,0.723417,0.109723,-0.154592,0.348323,-0.156771,-0.481116,-0.156873,-0.401138,-0.449113,0.044693,0.404076,0.045395,0.176050,0.094398,-0.631882,-0.169364,-0.253048,-0.284350,0.086351,-0.484155,0.208444,-0.660188,-0.116572,-0.308009,-0.140780,0.055976,0.052431,-0.287114,0.974629,-0.735290,0.044958,0.365891,-0.058901,-0.370946,0.629884,0.036228,0.172954,-0.209962,-0.040734,0.231276,-0.267643,-0.052128,0.046731,0.529123,-0.029379,-0.175356,-0.259588,0.558673', '27602116', '3811356', '25880986', '