INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294693', '荆轲刺秦王', '剧情', '战国时代，秦王嬴政（李雪健饰）以统一天下为大业。当时燕国为嬴政的心头之患，为帮助他早日完成统一霸业，赵姬（巩俐饰）献策到燕国假意策动刺杀嬴政的计划，如此一来，秦便有出兵攻燕的名目，争取燕国不战而降的可能。赵姬与燕太子丹（孙周饰）同心谋划刺杀嬴政的行动。执行任务的人选是名剑客荆轲（张丰毅饰），大隐于市的他为此重出江湖。与荆轲接触后，赵姬十分倾慕他的为人。赵姬拒绝再去说服荆轲。太子丹恼怒，将赵姬关押起来。于是，荆轲找到太子丹，提出放了赵姬，他就答应去刺秦王。与此同时，嬴政发现了关于自己身世的秘密，他恼怒不堪，甚至挥兵攻打赵国，暴行难述。大殿之上，荆轲却失手……©豆瓣', '巩俐', '陈凯歌', 8.2, 62242, 'tt0162866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2457792306.jpg', 0.8, 2.2, 18.2, 44.7, 34.2, '-0.248646,0.448495,-0.589789,0.764428,0.249757,-0.057607,0.160420,0.193222,-0.379088,-0.267873,0.371354,0.455948,0.048338,-0.311001,0.287545,0.031376,-0.124118,-0.655722,0.012311,-0.080129,0.047041,-0.235724,-0.184603,-0.370679,-0.329883,-0.174892,0.832024,0.138186,-0.194501,0.380667,0.236428,0.231319,0.145216,0.745758,0.098387,0.007749,-0.368464,-0.163570,-0.306040,0.380883,-0.115940,-0.503650,-0.344950,0.353010,-0.185436,0.425138,0.200683,-0.155711,-0.004588,-0.351108,0.300358,-0.277253,-0.011856,0.058005,0.056760,0.144829,-0.133956,0.485721,-0.156121,-0.066422,0.016387,-0.070908,-0.707192,-0.100529,0.125637,-0.053478,-0.502359,0.386282,-0.420311,0.108312,0.019087,-0.526544,0.231027,0.590239,0.271933,-0.003786,-0.174437,-0.100445,-0.480513,0.347530,0.652000,-0.192477,0.236814,-0.259384,0.267434,-0.499781,0.253291,-0.164720,0.086902,-0.089108,0.193861,0.057362,0.053151,0.140036,-0.000890,-0.595584,-0.493940,0.316072,0.296448,-0.102865,0.254662,-0.175222,-0.023581,0.141081,-0.320191,-0.149173,0.362610,-0.427209,0.337530,-0.557361,-0.224414,0.277146,0.463605,-1.029587,0.269452,0.094028,0.186413,-0.132253,-0.116043,0.168506,0.004578,0.062751,-0.021377,-0.076307,0.065721,-0.234779,-0.562144,0.118386', '1395445', '1484760', '1295746', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294699', '午夜狂奔', '喜剧', '赏金猎人杰克•沃尔什（罗伯特•德尼罗 Robert De Niro 饰）为十万美元决定去纽约搜捕芝加哥黑帮头子吉米•瑟拉诺（丹尼斯•法里纳 Dennis Farina 饰）的会计乔纳森•马杜克斯（查尔斯•格罗丁 Charles Grodin 饰）。乔纳森贪污了吉米一千五百万美元，并将大部分钱捐给了慈善机构。杰克本打算带乔纳森乘飞机于周五午夜前抵达洛杉矶，但乔纳森患有飞行恐惧症，二人只好转乘火车。于此同时，FBI探员阿朗佐•莫斯利（亚菲特•卡托 Yaphet Kotto 饰）、吉米的黑帮手下及吉米的竞争对手，赏金猎人马文（约翰•阿什顿 John Ashton 饰）都在追踪二人。杰克与乔纳森险况横出爆笑风趣的旅程究竟能否顺利完成？本片获金球奖最佳喜剧/音乐剧提名及最佳男主角提名（罗伯特•德尼罗）。©豆瓣', '罗伯特·德尼罗', '马丁·布莱斯特', 8.5, 24216, 'tt0095631', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1483943303.jpg', 0.1, 0.6, 11.3, 47.7, 40.3, '-0.178767,-0.288387,-0.322059,0.176055,0.263346,-0.625021,0.435450,0.230640,-0.278480,-0.249985,0.058849,0.535847,-0.130070,-0.113712,0.810197,0.065346,-0.725380,-0.356414,0.069926,-0.169430,0.089385,-0.740160,-0.326537,-0.145396,-0.128640,-0.068812,0.122643,-0.197383,0.143056,0.600808,0.617630,0.517478,-0.031219,0.059755,0.270406,0.102870,0.663271,-0.476156,-0.536737,0.358659,-0.011142,0.067405,-0.136431,-0.217250,0.451866,0.381494,0.443338,-0.017704,0.434933,-0.078549,-0.097474,0.063597,0.165378,-0.096075,0.046751,-0.208667,0.264195,0.074597,-0.060681,0.125936,0.134107,-0.038472,-0.492514,0.230922,-0.189030,0.104325,-0.258184,0.126950,-0.577339,0.329893,-0.009513,-0.141685,-0.177472,0.205117,0.135031,-0.137463,0.140489,-0.056611,-0.365220,0.128535,-0.060434,0.008360,-0.165214,-0.011048,-0.129978,-0.711288,-0.167714,0.036297,-0.032156,-0.075540,0.626126,-0.190653,0.326227,0.245333,-0.464206,-0.258583,-0.483087,-0.265088,-0.409376,0.001853,0.098638,-0.993225,0.295175,0.020411,-0.082249,-0.270534,0.294085,-0.146363,0.121747,-0.259888,0.286906,0.423693,-0.009617,-0.041045,0.256037,0.050919,0.514119,-0.298221,-0.349756,0.380850,0.334556,0.187008,0.087405,0.168060,0.069432,-0.505179,-0.021815,0.375186', '6517421', '1293572', '2075345', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294713', 'O记三合会档案', '动作', '20世纪50年代末60年代初的香港，警匪勾结，乌烟瘴气。其中，九龙城寨更是一个龙蛇盘踞，令人闻风丧胆的混乱所在。无所事事的小青年阿豪（刘青云 饰）和阿乐（吴镇宇 饰）偶然混迹于此，为这里的乱世气氛所感染，乐不思蜀。他们合伙赌马诈钱，惹来庄家追杀，幸得当时城寨大哥肥宝出 手方保住性命，二人的命运也自此发生转变。阿豪拜入肥宝门下，后与肥宝的小姨子大胆英（彭丹 饰）相恋，他果敢勇猛，风头无两；阿乐当上警察，与曾和阿豪有染的女孩菲菲（朱茵 饰）结婚。为了让虚荣的妻子过上幸福生活，他不惜选择贪污堕落。两个分处黑白道的好兄弟，携手打拼出一个属于他们自己的天下……©豆瓣', '刘青云', '霍耀良', 7.1, 22610, 'tt0202383', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1946287538.jpg', 1, 5.9, 41, 39.5, 12.5, '0.075602,-0.114194,-0.666917,0.440217,-0.090957,-0.278165,0.560346,0.074247,-0.437844,-0.101843,0.109251,0.715923,-0.079209,0.234153,0.306116,-0.076117,0.025876,-0.812643,-0.275145,-0.118987,0.057174,-0.168166,-0.273299,-0.040885,-0.404908,0.052014,0.411710,0.100755,-0.214837,0.640428,0.415757,0.106439,-0.486041,0.083539,-0.248659,0.056463,-0.061477,0.242154,-0.673960,-0.256995,-0.380472,-0.182856,-0.099332,0.022881,0.029917,0.213025,0.500093,-0.162249,-0.146598,-0.316496,0.275734,-0.073841,-0.333046,-0.128806,0.224784,-0.186403,0.424625,0.285621,-0.078128,-0.232010,-0.003696,0.137818,-0.639808,0.138532,0.155795,-0.103435,-0.377636,0.239970,0.063823,-0.159050,0.054219,-0.216452,0.238020,0.397636,0.365065,0.149030,-0.039201,-0.064764,-0.409897,0.242039,0.981628,-0.179201,0.016112,-0.009489,0.130977,-0.236985,0.136014,-0.315900,-0.460408,-0.004171,0.187467,-0.375529,0.008775,0.386479,-0.451664,-0.012725,-0.204774,0.264473,0.128563,-0.098840,0.077227,-0.332113,-0.394511,-0.433936,-0.372556,0.026325,0.138187,-0.142371,0.530024,-0.707759,0.114692,0.228883,0.399558,-0.697457,0.561339,0.340163,0.229935,-0.135521,-0.285459,0.029002,0.179964,0.124974,-0.074094,0.150720,-0.200002,0.034022,-0.222189,0.006427', '25721544', '1296978', '4145476', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294732', '老师不是人', '科幻', '俄亥俄州赫灵顿高中，似乎就在一夜之间，学校的老师以及部分优等生就变得十分奇怪。原本态度和蔼的他们如今冷峻阴森，而这种情况似乎愈演愈烈。问题学生凯西（Elijah Wood 伊利亚•伍德 饰）和黛丽拉（Jordana Brewster 乔丹娜•布鲁斯特 饰）偶然机缘躲进了衣橱，并由此见证了护士罗莎（Salma Hayek 饰）被残忍杀害的场面。但未过多久，罗莎又完好无损地出现众人面前，表情却如其他老师一般阴森。凯西等人逐渐意识到，这一连串事件和他们发现的某种神秘生物有关，而今这种生物似乎正以令人难以想象的恐怖速度大肆蔓延。危险不断迫近……©豆瓣', '乔丹娜·布鲁斯特', '罗伯特·罗德里格兹', 6.9, 15562, 'tt0133751', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2209392026.jpg', 1.1, 6.8, 48.6, 34.3, 9.2, '0.350557,-0.117425,-0.571550,0.536790,0.009506,0.170307,0.967653,0.153756,-0.852712,-0.349275,0.177932,0.496968,-0.671019,0.176565,0.153799,-0.074980,-0.372427,-0.467547,-0.098288,-0.256060,-0.301693,-0.422461,-0.332737,-0.252060,0.182669,-0.467682,0.394052,0.177671,-0.108976,0.815648,-0.107056,0.353904,-0.210643,0.950151,0.171927,-0.073339,0.154672,0.081328,0.108847,-0.197284,0.161398,-0.081085,-0.237651,0.448482,-0.085031,0.321875,0.538956,-0.312781,-0.385291,0.001122,0.371821,-0.018355,0.058381,0.579223,0.449388,-0.163114,0.210496,0.082758,0.200567,-0.104418,-0.020444,0.109984,-0.563492,0.332387,-0.182644,0.336411,-0.158254,-0.006145,-0.045735,-0.106606,0.169753,-0.268512,0.105750,0.127704,0.268862,0.417405,-0.173784,-0.179568,-0.308278,-0.115846,0.418094,0.006509,-0.654243,0.558076,-0.298237,-0.472995,-0.330568,-0.006326,-0.197180,0.201583,0.174094,0.380389,-0.103075,0.525095,-0.499160,-0.064575,-0.217319,-0.063672,-0.408659,-0.264188,-0.447080,-0.735324,-0.165165,-0.398872,-0.279918,0.058472,-0.325899,-0.157230,0.426253,-0.659115,0.131181,0.374731,0.227792,-0.066559,0.086796,-0.321026,-0.107411,-0.116060,-0.674108,0.232688,0.028675,0.346945,0.188218,0.465571,0.073027,-0.053686,0.045940,0.649907', '21348112', '27617348', '1309172', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294735', '好男好女', '剧情', '作为演员，梁静（伊能静）更喜欢戏里的世界。戏里，她扮演蒋碧玉，那是一个见证创造了历史的，从娇生惯养的千金小姐一步步变成坚强的革命义士的，和钟浩东（林强）谈过轰轰烈烈恋爱的，天塌下来，也可以用柔弱肩膀顶回去的女人。一旦做回自己，她便成为一具沉浸在对死去的阿飞男友阿威（高捷）的回忆里不能自拔的，过去日记被人偷去又被不定期传真回来的，时常接到不发声骚扰电话的，抢了姐姐男人的，做演员之前是个舞小姐的，孤独、压抑、拼命想回到从前的干尸。历史并不能真正走进去，梁静当然明白。戏结束了，痛快地哭一场之后，仍要回到现实中来，继续过麻木的日子。©豆瓣', '伊能静', '侯孝贤', 7.6, 7155, 'tt0113256', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1622277843.jpg', 0.2, 2.5, 31.9, 49.9, 15.5, '0.208738,0.056781,-0.487503,0.375932,-0.464291,-0.265904,0.975185,-0.177338,-0.468470,-0.126420,0.063436,0.626218,-0.148353,0.437030,0.286579,0.127613,-0.264148,-0.753860,0.005503,0.011789,-0.088792,-0.088816,-0.076637,-0.077964,-0.029722,-0.121794,0.653881,-0.064190,-0.237672,0.356318,0.393076,0.032936,0.137668,0.562814,-0.175020,0.269525,-0.370309,0.237927,-0.265617,0.208742,0.397384,-0.174883,-0.151994,-0.040519,0.099821,0.053007,0.475792,-0.226500,0.055648,0.114221,0.519893,-0.210438,-0.264607,0.354456,0.034011,0.180642,0.137923,0.052865,-0.186957,0.127853,0.056968,-0.153023,-0.701375,0.006395,-0.009487,0.223098,-0.655298,0.495433,-0.011494,0.135456,0.080195,-0.291428,0.343960,0.142719,0.365751,0.496172,-0.261956,0.094886,-0.416360,0.490452,0.721254,0.232099,-0.067103,0.473145,0.086132,-0.410332,-0.018054,-0.389081,-0.465120,0.088782,0.142706,-0.195993,-0.455814,0.022307,-0.471681,-0.087773,0.011503,-0.279748,0.067971,-0.604530,-0.126961,-0.166222,-0.287213,-0.219569,-0.088347,-0.104651,-0.038866,-0.503685,0.717015,-0.728123,0.240146,0.554559,0.178824,-0.583380,0.579693,0.336821,-0.037318,-0.201215,0.320215,0.479426,-0.026702,0.495423,0.152296,0.437723,-0.090208,-0.002742,-0.440849,0.544896', '1309066', '3230462', '26884422', '1291577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294737', '楢山节考', '剧情', '信浓有一座楢山，附近山村的人到了七十岁就得进楢山。六十九岁的阿玲（田中绢代 饰）还有两件事放不下：一是四十五岁的儿子辰平（高桥贞二 饰）去年成了鳏夫；二是长孙袈裟吉（市川团子 饰）总是在村里人面前嘲笑自己牢固的牙齿。一年一度的祭祀日，等来了新儿媳阿玉（望月优子 饰）的阿玲狠下心在石臼上磕掉了两颗门牙。割稻子的时节，袈裟吉将怀着身孕的阿松（小笠原庆子 饰）领进了家门，并催促祖母早点进山。与袈裟吉不同，善良的辰平舍不得母亲进山。可是面对人口增加食物不足的状况，辰平别无选择，只得遵照母亲的意愿，在新年之前将母亲背上楢山……©豆瓣', '田中绢代', '木下惠介', 8.7, 9882, 'tt0051980', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521124496.jpg', 0.3, 0.8, 9.4, 42.2, 47.4, '0.033414,0.004415,-0.589758,0.355592,0.009404,-0.525446,0.239607,0.602430,-0.364816,-0.097613,0.247328,0.302954,0.015066,0.363013,-0.024008,0.149528,-0.035503,-0.189856,-0.020639,-0.143766,-0.634151,-0.234477,0.407772,0.003659,-0.228503,0.008143,0.410851,0.088318,0.123663,0.228657,0.268547,0.299464,0.092563,0.133406,-0.307172,0.169695,-0.367862,0.016802,0.019468,0.092783,-0.171235,-0.166463,0.002562,0.281090,0.320710,0.452358,0.740905,-0.310484,-0.116077,-0.205093,0.101311,0.125206,-0.118071,0.399710,0.556401,-0.068423,0.151526,0.134251,-0.373754,0.092270,0.103484,-0.305429,-0.066702,-0.172213,0.303700,-0.068949,-0.772042,0.596553,-0.003140,0.022729,0.026010,-0.589687,0.157109,0.190433,-0.289225,0.419271,-0.391084,-0.092469,-0.346414,0.206159,0.310373,-0.188234,0.435246,0.148193,-0.097927,-0.202188,0.030095,-0.226428,-0.182749,0.075914,0.176701,-0.007707,-0.289309,-0.020020,-0.409595,-0.177783,-0.424208,-0.024878,0.336699,-0.169783,-0.146827,-0.025785,0.266831,-0.411131,-0.264547,0.319643,0.337242,0.017521,0.480257,-0.327536,0.384525,0.396728,0.205543,-0.045020,0.266671,-0.078973,0.225463,-0.321840,0.038629,0.138811,-0.026017,0.247273,0.171971,0.053005,-0.167212,-0.153760,-0.354095,0.248348', '1296703', '1306505', '1292642', '4030411');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294753', '追梦赤子心', '剧情', '《Rudy》是改编自丹尼尔· 鲁迪的真人真事。鲁迪（西恩·奥斯汀 Sean Astin 饰）全家都对橄榄球赛非常狂热，也是圣母大学队的忠实拥护者。高中毕业本想去圣母大学的鲁迪却因为成绩不好而放弃，毕业后进入了钢铁厂工作。22岁生日，好友送了他一件印有圣母大学字样的外套，并鼓励他去实现自己的梦想。好友在钢铁厂的意外死亡打击了鲁迪，他抛下了本已谈婚论嫁的女友，踏上了前往圣母大学的火车。进入大学以后，他学习、锻炼都格外刻苦，凭借顽强的斗志，被教练选入了校队的替补阵营，但他一直没有机会上场比赛。 终于在一场重要比赛的关键时刻替补出场，帮助球队拿下了比赛。出现在现场的父母和家人也兴奋不已。1975年之后，圣母大学队再没有人被当场抬起。1976年，鲁迪从圣母大学毕业，他的5个弟弟也都上了大学，并顺利毕业。©豆瓣', '西恩·奥斯汀', '大卫·安斯鲍夫', 8.8, 55696, 'tt0108002', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p452578349.jpg', 0.2, 0.8, 10.1, 38, 50.9, '0.083574,-0.008353,-0.564459,0.689689,-0.289945,-0.568675,0.305112,0.096049,-0.407329,-0.085746,0.142921,0.873996,-0.274330,0.334623,0.176691,-0.088636,-0.079738,-0.738054,0.302867,-0.220165,-0.299223,-0.452336,0.085892,-0.172189,0.058955,-0.387758,0.773083,-0.091364,0.001979,0.699889,0.210897,-0.039903,0.612042,0.617533,-0.107035,0.190547,-0.025083,0.245335,0.020021,0.360850,0.118158,-0.172839,-0.238809,0.225147,0.476955,0.391234,0.731661,0.070219,-0.075454,0.058674,0.394013,-0.320279,-0.070737,0.371232,0.426426,-0.127005,0.054513,0.316391,0.117709,0.138663,-0.265941,-0.339168,-0.446947,-0.035781,-0.035074,-0.144535,-0.755438,1.111504,-0.113062,0.212570,0.119813,-0.312992,0.177240,0.487975,-0.085389,0.329296,-0.301816,0.004794,-0.332380,0.651333,0.695645,-0.206155,-0.036672,0.389415,-0.126641,-0.548652,-0.016170,-0.291505,-0.395516,0.286153,0.403665,0.100188,-0.133882,0.056542,-0.405927,-0.089373,-0.142566,-0.284563,-0.023500,-0.619766,0.275253,-0.461977,0.071359,0.031427,-0.506304,0.188484,-0.186256,-0.239999,0.820688,-0.940101,0.083812,0.597629,0.294732,-0.435421,0.940460,0.114359,0.184170,-0.219876,-0.122236,0.457469,-0.230714,0.590751,0.015899,0.483451,-0.023975,-0.415300,-0.241715,0.568602', '4202326', '22964524', '1826173', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294756', '历劫佳人', '惊悚', '缉毒官员Newlyweds Miguel "Mike" Vargas(查尔登·海斯顿 Charlton Heston 饰）和他的妻子Susie（珍妮特·利 Janet Leigh 饰）来到了美国和墨西哥的边界。马路上发生了一起汽车爆炸事件，Vargas认为这起案件跟毒贩子有关，遂和当地的警察们一起展开了调查。Hank Quinlan（奥逊·威尔斯 Orson Welles 饰）是警察队长，在当地名声甚响。当地警方把嫌疑集中在一个叫Sanchez的人身上，Vargas却在Sanchez的家中发现了证明他不是犯人的证据。然而Quinlan执意认为Sanchez就是犯人。Vargas研究了以前Quinlan办过的案件，对这个赫赫有名的警察队长产生了不少疑问。而Vargas的妻子Susie在旅馆里却被一帮人所绑架并陷害，Vargas怀疑这一切的背后都是Quinlan在操纵。Vargas在和Quinlan的对抗中会有怎样的结局？本片由执导了《公民凯恩》的奥逊·威尔斯自编自导自演，共有三个版本：1958年发行的版本，1976年的加长版，1998年发现的可能更符合威尔斯想法的版本。', '查尔顿·赫斯顿', '奥逊·威尔斯', 8.1, 10169, 'tt0052311', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2259429113.jpg', 0.5, 2, 18.6, 50.7, 28.2, '0.612134,-0.352245,-0.653205,0.483983,-0.046906,-0.020358,0.701273,-0.037621,-0.835334,-0.335826,0.189476,0.726349,-0.143261,0.027037,0.245916,-0.090062,-0.348851,-0.855149,-0.060708,-0.327153,-0.305438,-0.793362,-0.299768,-0.341542,0.024504,-0.335133,0.322987,0.071433,-0.133969,0.501081,0.432484,0.352751,-0.226516,0.337928,-0.111837,-0.005023,0.231927,-0.078655,-0.308630,0.246952,-0.036731,-0.439641,-0.019953,0.070800,0.112945,0.562297,0.517662,-0.174713,-0.238738,0.166040,0.398581,-0.429146,-0.060767,0.068021,0.621228,0.150174,0.020344,0.530602,-0.314497,-0.079446,0.067239,0.096671,-0.810190,-0.146440,0.192575,0.373464,-0.769505,0.403844,-0.162302,-0.089486,-0.175441,-0.090813,0.553724,0.234755,0.176749,0.404611,0.083840,-0.138497,-0.650251,0.136370,0.640912,-0.119941,-0.040509,0.107489,-0.142638,-0.381221,-0.339939,-0.110551,-0.220665,0.074664,0.103272,-0.111950,-0.315121,0.186031,-0.557436,-0.128517,-0.263424,-0.259344,-0.149285,-0.402219,-0.076320,-0.608887,-0.127552,-0.401177,-0.187413,0.169500,0.156973,-0.268583,0.527600,-0.931349,0.099201,0.649898,0.447326,-0.608258,0.588699,0.169520,0.059647,-0.195983,-0.146616,-0.249089,0.467768,0.066874,0.047336,0.312121,0.121055,-0.582221,-0.245848,0.166743', '3263169', '1783461', '1307442', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294766', '泰山', '剧情', '猿猴家族收养了一位特殊的孩子，一个自小被遗弃在森林深处的婴儿男孩。在猿猴们的悉心照料下，男孩快快乐乐的长大了，他们给他取名叫泰山。由于自小在猿猴家长大，泰山敏捷得跟猿猴一样，结交很多的森林朋友。直到有一天，深入到森林深处的探险家打破了泰山宁静的生活，这时他才发现自己原来是人类的一员。泰山爱上了探险家的女儿珍妮，但人类的所作所为又令他对回归人类还是继续在森林生活进退两难，泰山最终将如何抉择？©豆瓣', '布耐恩·布莱塞得', '克里斯·巴克', 7.7, 97179, 'tt0120855', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1833041570.jpg', 0.1, 1.3, 30.4, 49.7, 18.5, '0.165715,-0.051526,-0.696056,0.724444,-0.306149,-0.271276,0.822675,0.191654,-0.602559,-0.130715,0.545437,1.008662,0.021029,0.415055,-0.071912,-0.038827,-0.003431,-0.355274,-0.079517,-0.156642,-0.352863,-0.065106,-0.418778,-0.157674,0.145014,-0.323701,0.976496,0.077051,-0.076619,0.298164,-0.227822,0.091260,-0.110222,0.330992,-0.661271,0.103484,0.054016,0.313913,-0.227238,0.062093,-0.275459,-0.012223,-0.263454,0.061826,-0.051649,0.072460,0.704362,-0.584252,-0.486975,-0.329446,0.254503,-0.146218,-0.138097,-0.023756,0.689343,-0.485126,-0.000199,0.060312,0.055989,0.087486,-0.419893,-0.179802,-0.269581,-0.097443,0.084629,0.318070,-0.935153,0.431662,0.380270,-0.186841,0.022703,-0.585802,-0.185367,0.342033,0.030065,0.606458,-0.221330,0.210513,-0.528019,0.041509,0.887316,-0.056697,-0.373927,0.268299,-0.253918,-0.767308,-0.053201,-0.273660,-0.826447,-0.181574,0.316422,0.073213,-0.946423,0.459602,-0.621448,0.000151,-0.263828,-0.249833,-0.065091,-0.674694,-0.333658,-0.244325,0.137741,-0.420410,-0.132944,-0.041936,0.092692,-0.226779,1.065028,-0.938945,0.515307,0.755437,0.179129,-0.305507,0.708928,-0.259768,0.050924,-0.269225,0.233316,0.490684,0.237527,0.280124,0.217349,0.305669,-0.323311,0.078092,-0.581503,0.511472', '1292720', '26593587', '5938000', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294768', '爱情故事', '剧情', '洋溢着青春浪漫气息的哈佛大学校园中，富家子弟奥利弗（瑞安·奥尼尔 Ryan O''Neal 饰）遇见了聪敏可爱的女生詹妮弗（艾丽·麦古奥 Ali MacGraw 饰），他被女孩的机智俏丽深深吸引，两人迅速坠入爱河。然而，当有权有势的奥利弗家族得知——儿子的未婚妻竟然出身于一个烤甜饼的家庭，他们极力反对这桩婚姻。深爱着詹妮弗的奥利弗不顾家庭反对，毅然与爱人成婚，并不惜与家族断绝关系。婚后生活虽然拮据而艰难，但是充满了爱情的甜蜜。奥利弗在爱妻的支持下完成了硕士学业，顺利拿到律师执照。正当生活向着美好的未来走去时，病魔选中了詹妮弗。为了治疗爱妻的绝症，奥利弗低头向父亲求救。然而，一切哀求都无法阻止无情的病魔，詹妮弗最终离开了人世。然而，这段真挚的爱情故事却获得了永恒。本片获得第43届奥斯卡最佳配乐奖，以及其它6项目奥斯卡提名奖。©豆瓣', '艾丽·麦古奥', '阿瑟·希勒', 7.9, 13130, 'tt0066011', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1399778881.jpg', 0.4, 1.9, 25.4, 47.4, 24.9, '0.081856,0.082742,-0.470886,0.495722,-0.077366,-0.454261,0.599511,0.169697,-0.280491,-0.066546,0.038894,0.743489,-0.086020,0.399802,0.387652,-0.059398,-0.141052,-0.705422,-0.086417,-0.012639,-0.037252,-0.486258,0.058336,-0.029731,-0.209111,-0.267055,0.893965,-0.018619,0.064422,0.629709,0.384018,0.298134,-0.285442,0.370697,-0.087864,0.096780,0.313489,0.182417,-0.696491,0.312159,0.182201,-0.049700,-0.212343,0.169722,-0.049882,0.187880,0.574026,-0.171113,-0.071779,-0.087389,0.568802,-0.234676,-0.171428,0.271871,0.065319,-0.008276,-0.009857,0.353875,-0.021027,-0.129027,0.237785,-0.206527,-0.636718,-0.057367,0.169526,0.025350,-0.545154,0.482878,0.016918,-0.004209,0.240175,-0.232625,0.070263,0.133911,0.262675,0.448558,-0.278319,0.317830,-0.336010,0.399305,0.499149,0.104502,-0.397516,0.382500,-0.492263,-0.418386,0.129057,-0.357070,-0.822617,0.069418,0.459557,0.486531,-0.054816,0.432139,-0.275093,-0.161214,-0.283511,-0.147698,0.240516,-0.591789,-0.082009,-0.533983,-0.207986,-0.227538,-0.408700,0.037332,-0.069116,-0.465234,0.780577,-0.676812,0.234739,0.330498,0.348889,-0.452712,0.624712,0.294294,0.315022,-0.113394,-0.150437,0.666055,-0.023187,0.019687,0.031894,0.038147,-0.274092,0.046285,-0.304402,0.503922', '30349667', '1303034', '6973376', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294772', '爱上百分百英雄', '喜剧', '飞机（郑伊健 饰）本是个上进的警员，在一次行动中杀手天使（方中信 饰）杀死了证人以及飞机的女友后，飞机性情大变。新被调到CID的警察火鸡（陈小春 饰）被安排与飞机拍档，生性乐观的他积极鼓励颓废的飞机，两人友情大增。火鸡遇见了梦中情人小明星小婷（徐若萱 饰），却收到她的求救信息，原来小婷被高利贷抓走了。飞机更认识了小婷的朋友小曼（梁咏琪 饰），小曼跟飞机死去的女友样子几乎一模一样。火鸡为了能接近小婷，提出要保护两个女孩子。当他们4人都沉醉在爱情的甜蜜时，杀手天使计划要杀死四人……©豆瓣', '郑伊健', '王晶', 6.4, 4088, 'tt0185850', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2875087593.jpg', 1.7, 11.7, 57.6, 21, 7.9, '0.189674,-0.277778,-0.446187,0.599326,-0.220994,-0.151794,0.667003,0.098579,-0.400694,-0.035993,0.377873,0.523984,-0.231093,0.192597,0.564286,0.016814,-0.318921,-0.606098,0.029794,-0.063887,-0.373875,-0.271106,-0.137213,-0.239982,0.113625,-0.203079,0.639860,-0.126030,0.158510,0.731394,0.434525,-0.182507,-0.248394,0.374534,-0.115475,0.095056,0.184749,-0.005305,-0.264496,0.295827,-0.206694,0.047839,0.280838,0.167309,-0.112206,0.225787,0.736507,-0.108714,-0.046749,-0.311022,-0.039030,-0.213385,0.022764,0.074108,0.435751,-0.104798,0.478945,-0.077918,-0.100730,0.120500,0.092127,0.102277,-0.454515,0.293909,0.017984,-0.182486,-0.450905,0.296994,-0.314507,0.506461,0.293282,-0.167322,0.263708,0.092482,0.159497,0.546413,-0.117887,0.004357,-0.459066,0.240564,0.494293,0.062546,0.159099,0.513087,-0.078186,-0.312718,-0.080004,0.015132,-0.342445,0.406277,0.551119,-0.258279,-0.435956,0.165460,-0.583570,-0.375760,-0.170080,0.175916,-0.151330,-0.568435,-0.173977,-0.577558,0.089196,-0.109608,-0.067380,0.178246,0.020910,-0.076007,0.765382,-0.942459,0.037030,0.368109,0.310035,-0.606041,0.497501,0.130099,-0.053422,-0.446342,0.211834,-0.044605,0.030877,0.137690,0.096098,0.136625,-0.339489,-0.022244,-0.302148,0.050736', '25922902', '3445516', '4127270', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294781', '卡比利亚之夜', '剧情', '妓女卡比利亚（茱莉艾塔·玛西娜 Giulietta Masina 饰）一直梦想和自己的爱人过上甜蜜安稳的日子。然而，单纯善良的她在一开始就被男友骗光了钱，并被推入河中，差点丧命。即使遭遇如此羞辱，她还是对爱情充满希望。一次，她在街上偶遇一个刚和女友吵架的男演员，被他邀请 回家过夜。正当她受宠若惊、满心欢喜之际，男演员的女友上门求和，这让卡比利亚再次伤心欲绝。不久，她又在剧场遭遇到一位英俊男子的疯狂追求，起初她有点不自信，但最终还是接受了这位男子的求婚，并变卖所有家产，准备与未婚夫共赴美好新生活。然而，在途中她的未婚夫居然也露出骗子的本性，抢走了她的钱，并差点害死她。一无所有的卡比利亚疯狂痛哭，悲伤欲绝。她独自晃悠在路上，一群活泼的男女从身边经过，他们快乐地边走边唱，欢乐氛围让灰心的卡比利亚受到感染，她的脸上又露出了招牌式的笑容。本片获得第30届奥斯卡最佳外语片，第10届戛纳电影节最佳女演员奖。', '朱丽叶塔·马西纳', '费德里科·费里尼', 9.1, 35330, 'tt0050783', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204675868.jpg', 0.2, 0.4, 5.2, 30.7, 63.4, '0.058735,0.224726,-0.791084,0.586355,-0.159070,-0.497601,0.948989,-0.013051,-0.125502,0.083452,0.157026,0.910746,-0.343332,0.568086,0.517082,0.002620,-0.159381,-0.593066,0.114178,0.038083,-0.096530,0.033466,-0.103072,0.075012,-0.199336,-0.349949,0.520064,0.107432,-0.103009,0.572610,0.601310,0.065200,-0.194803,0.645644,-0.140056,0.272266,0.152654,0.193668,-0.133829,0.179367,-0.046612,-0.424407,-0.290742,0.274322,0.010596,0.284694,0.675814,-0.071943,-0.099119,0.318005,0.326466,-0.333139,-0.097278,0.249893,-0.000333,-0.285263,0.240344,-0.025356,-0.110668,0.190739,0.204995,-0.164396,-0.719398,0.020509,-0.124721,-0.108056,-0.488366,0.510374,-0.001402,0.400352,0.146792,-0.165335,0.130078,0.157687,0.130326,0.246298,-0.306552,0.104254,-0.498494,0.429654,0.640408,0.097583,-0.254123,0.479103,-0.192533,-0.316930,0.212818,-0.237493,-0.584500,0.167220,0.430992,0.004993,-0.198208,0.189008,-0.586265,0.117870,-0.298710,-0.028061,0.040116,-0.329351,-0.125412,-0.393419,-0.055169,-0.336040,-0.431409,-0.011243,-0.053443,-0.364593,0.469423,-0.614628,0.288433,0.658035,0.194516,-0.365304,0.494459,0.447649,-0.091337,0.003394,-0.329821,0.453129,0.007137,0.175703,0.085932,0.289130,-0.344570,0.098408,-0.298749,0.698028', '1309172', '34890458', '1291877', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294789', '第九道门', '剧情', '卡索(约翰尼·德普 Johnny Depp 饰)着迷于收藏离奇古怪的珍稀书籍。这种才华令富翁巴尔坎（弗兰克·兰格拉 Frank Langella 饰）大为赏识。他派给卡索一个艰巨的任务——寻找一本叫《第九道门》的古书，并鉴定他手中那本的真假。这本书在世界上仅存3本，剩下的两本，分别流落到了葡萄牙和法国。传说，只要通读此书，就可以召唤魔鬼的到来。卡索开始了曲折而又魔幻的寻找历程。他探访了书的原主人之妻、古籍修缮专家、遇上绿眼珠的神秘女人，期间他朋友的暴毙竟然跟书里的插图如出一辙，命案还在连连上演。原来，书中所带的咒语，恐怕会使得拥有者无一幸免。而如果三本书合在了一起，就会迎来邪恶的撒旦。而到底最终魔鬼的脸有没有出现？©豆瓣', '约翰尼·德普', '罗曼·波兰斯基', 7.3, 41895, 'tt0142688', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p581343062.jpg', 0.8, 5, 38.9, 41, 14.4, '0.163543,-0.195805,-0.442445,0.835473,0.147207,-0.348372,0.544399,0.023140,-0.333653,-0.199138,0.203053,0.678863,-0.194500,0.064672,0.330482,0.131725,-0.206318,-0.605293,-0.033310,-0.385343,-0.390397,-0.249955,-0.372369,-0.288580,0.151747,-0.432749,0.382570,0.289767,-0.225699,0.164508,0.289871,0.331036,-0.352336,-0.017622,-0.318051,-0.042351,-0.034139,0.192568,-0.013319,0.195044,0.070877,-0.210181,-0.171727,0.120448,-0.035644,0.078971,0.485313,-0.375520,-0.015821,0.081349,0.443460,-0.163699,-0.253450,-0.067018,0.017086,0.171983,0.211070,0.071906,-0.065594,0.022969,0.220254,-0.141603,-0.936192,-0.115594,-0.024353,0.319563,-0.490887,0.191855,-0.143356,0.053299,-0.030896,-0.254503,0.237122,0.157367,0.224739,0.319752,0.182030,-0.151290,-0.236254,0.376881,-0.155982,-0.180495,-0.198497,0.167206,0.027231,-0.508778,0.009710,-0.019274,-0.161838,0.291038,0.519333,0.174174,0.016634,0.222476,-0.773828,0.027148,-0.280709,-0.211929,0.087829,-0.233052,-0.320653,-0.651926,-0.240938,-0.006589,-0.149237,-0.022023,0.423849,-0.374009,0.903474,-0.382023,0.329143,0.325027,-0.183891,-0.515667,0.385484,0.218184,-0.176962,-0.098810,-0.166646,0.178072,0.278056,0.573026,0.096180,0.190583,0.319709,-0.295809,-0.451020,0.628995', '27602116', '3318306', '4267948', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294791', '机器战警', '剧情', '底特律是世界闻名的汽车城，这里的机械工业已经到了出神入化的地步。墨菲（彼得•威勒 Peter Weller 饰）是底特律的一个普通警察，既没有非凡身手、也没有高超技术。一次，他执行任务时被一伙暴徒暴打致死，从此他的人生轨迹改变了。底特律的科学家没能救活他的身体，却能将他的头脑和机械完美地合二为一。墨菲成了一个有着人类头脑和机械身体的机械警察！身上配备了各种武器、能应付各种各样的暴力活动的墨菲成了底特律警察的王牌。然而墨菲发生意外后他的家人却神秘失踪了，墨菲打击罪恶之余一直在竭力寻找家人。令人意外的是，墨菲的机械身体却是操控在一伙利益集团手中。他们一直都在利用墨菲干着各种罪恶勾当……©豆瓣', '彼得·威勒', '保罗·范霍文', 7.7, 42112, 'tt0093870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1445879319.jpg', 0.3, 1.9, 28.2, 50.1, 19.5, '0.311738,0.041139,-0.700460,0.635122,-0.439306,-0.257896,1.014381,0.119354,-0.712647,-0.248280,0.289642,0.661672,0.044897,-0.179324,-0.115791,-0.033796,-0.092928,-0.755548,-0.233004,0.116618,-0.578310,-0.491098,-0.526707,-0.399632,-0.047648,-0.294866,0.516931,0.001894,-0.322911,0.318276,0.078773,0.191221,0.144299,0.551679,-0.596466,-0.110025,0.400632,-0.346092,0.056953,0.150520,0.091690,-0.323233,-0.057891,0.594199,-0.295865,0.353219,0.811901,-0.242389,-0.011850,-0.140304,0.230943,-0.275689,-0.071078,0.097509,0.241651,-0.187741,-0.035111,0.080248,-0.125073,-0.138322,0.468203,0.178333,-1.341795,-0.217804,-0.176095,0.179119,-0.711532,0.309832,-0.353101,0.086262,-0.137009,-0.422768,0.308182,0.173454,0.187139,0.446228,-0.041787,-0.083075,-0.713911,0.292890,0.613939,-0.058873,-0.630439,0.350765,-0.552403,-0.568796,-0.451661,-0.506090,-0.336185,-0.343239,0.621396,0.195284,-0.409785,0.256711,-0.502855,0.196692,-0.342028,-0.180623,-0.397284,-0.429048,-0.053600,-0.593402,-0.077301,-0.589257,-0.477112,0.015690,0.058794,-0.047531,0.836244,-0.974337,0.003373,1.006590,0.190800,-0.260808,0.577130,0.185269,-0.024381,0.136582,-0.165657,-0.114547,0.020243,0.678716,0.330270,0.857589,0.330663,-0.033997,-0.242476,0.805553', '1793491', '3785918', '25932086', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294808', '大幻影', '剧情', '影片以第一次世界大战为背景，讲述三名法国俘虏在德国集中营越狱的故事。三名法国飞行员在一次任务执行中被德军击落，波迪奥、迈克和罗森塔尔三人被带到战俘集中营。波迪奥与德军监狱长罗芬斯坦都是贵族出身，有着共同的政治见解，二人在狱中成为朋友。三人随后发现狱友正进行越狱计划，他们挖出一条逃跑的通道。迈克和罗森塔尔也加入了挖掘行动。最后他们集体越狱，德军全力追捕，在逃亡中，波迪奥被罗芬斯坦击倒，两名法国俘虏迈克和罗森塔尔逃到一个德国农妇家中，在她的帮助下，二人经过种种波折逃到瑞士。本片是最早的越狱片之一，被评为最伟大的“越狱电影”之一，同时也是导演让·雷诺阿的反战杰作。©豆瓣', '让·迦本', '让·雷诺阿', 8.4, 10149, 'tt0028950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2205140341.jpg', 0.3, 1, 12.8, 49.9, 35.9, '0.273547,-0.359029,-0.564816,0.663361,0.056029,-0.180930,0.723233,-0.209621,-0.306395,-0.201420,0.348584,0.893936,-0.117784,0.036638,0.332025,-0.349641,-0.500745,-0.759990,-0.219076,-0.128063,-0.195740,-0.506227,-0.167464,-0.242053,0.032948,-0.504884,0.918783,0.019903,-0.476401,0.340131,0.308934,0.571470,-0.392896,0.298180,-0.159004,0.218471,0.476249,-0.456401,-0.420756,0.394277,-0.260835,-0.554437,-0.297224,0.097887,-0.086528,0.397749,0.730329,-0.172755,0.093389,-0.042487,0.157196,-0.539782,-0.135574,0.164042,0.637727,0.003489,0.249877,0.446525,0.095756,0.206870,-0.055931,-0.020236,-0.683407,-0.075983,0.092069,0.129762,-0.757070,0.193208,-0.047908,0.155057,0.173599,-0.166694,0.115024,0.447359,0.109335,0.389898,-0.146211,0.111130,-0.665427,0.149109,0.887955,-0.295540,-0.148438,-0.106631,0.158206,-0.469957,0.138625,-0.143159,-0.024926,-0.052169,0.637190,-0.199842,-0.051515,0.293999,-0.861301,0.129028,-0.454594,-0.397629,-0.212295,-0.318244,0.054858,-1.151959,-0.054973,-0.058250,-0.347145,0.312068,0.079239,-0.176242,0.748078,-0.537475,0.055691,0.527542,0.177917,-0.473770,0.608515,0.246329,0.305030,-0.138833,0.126810,0.109137,0.290904,0.160340,0.067255,0.507384,-0.103895,-0.203122,-0.291492,0.178816', '1294917', '20274039', '2369613', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294809', '卧底肥妈', '喜剧', 'FBI探员马刚（马丁•劳伦斯 Martin Lawrence 饰）聪明能干，屡破奇案，而他的破案法宝就是他那高超的伪装绝技，无论什么人，他都自信能扮得惟妙惟肖。新的案子摆在了马刚面前，乔治亚州一个银行抢劫犯身怀巨款逃亡了，马刚奉命前往缉拿，唯一的线索就是抢劫犯的女友雪梨（尼娅•朗 Nia Long 饰）。为了接近雪梨，马刚施展他的变身特技，化身成了雪梨久未碰头的姑母，一个超过两百磅的“老妈子”。马刚的特技堪称一绝，经过化身易容，成功接近了雪梨。然而相处久了，马刚却发现自己爱上了可能有份参与收藏赃款的雪梨，更要命的是，真正的姑母登场了。©豆瓣', '马丁·劳伦斯', '拉加·高斯内尔', 6.8, 13350, 'tt0208003', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2676014910.jpg', 0.9, 5.8, 54.9, 29.8, 8.7, '0.231583,-0.073811,-0.407399,0.415555,-0.351623,-0.202810,0.381584,-0.032248,-0.348644,-0.255778,0.465614,0.545430,-0.083476,-0.233698,0.081493,0.016377,0.106596,-0.602563,0.146746,-0.313325,-0.108290,-0.374563,-0.449774,-0.140621,0.091288,-0.229875,0.298288,-0.010743,-0.008277,0.244627,0.369823,-0.155322,0.157300,0.338994,-0.158928,0.095131,0.283361,-0.201513,0.061827,0.292648,0.024786,-0.225334,0.039354,0.162134,-0.068685,0.377742,0.475696,-0.135305,-0.287560,0.159018,0.468333,-0.151232,-0.024190,0.023868,0.276326,-0.101616,0.138217,-0.036771,-0.182924,-0.036167,0.057942,0.085919,-0.930861,0.005126,0.035917,-0.096914,-0.518895,0.249196,-0.323918,0.043468,0.011577,-0.283419,0.210426,0.245710,0.158312,0.248460,0.063660,-0.106907,-0.728198,0.484377,0.189795,-0.013688,-0.307189,0.435115,-0.106781,-0.571556,-0.122080,-0.604206,0.129759,0.058172,0.459423,0.015678,0.011554,-0.016675,-0.501770,-0.181053,-0.458667,0.194681,-0.127783,-0.122782,-0.283544,-0.274565,-0.087270,-0.300801,-0.389731,0.034823,0.005255,-0.400287,0.721835,-0.653456,0.103425,0.527639,0.214793,-0.432316,0.680505,0.054786,-0.067317,-0.271203,-0.153311,0.096403,0.094200,0.250497,0.325026,0.447786,0.086954,-0.269828,-0.474419,0.383130', '1793491', '24284209', '3785918', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294827', '蜘蛛巢城', '剧情', '一串悲凉的歌声诉说着蜘蛛城的历史预言。战国时期，处于密林围抱的蜘蛛城，地形复杂，敌军攻来此地，必然迷路，因此城主稳坐城楼，指挥若定，四面排出大将御敌，可保此城固若金汤。大将鹫津武时（三船敏郎 Toshiro Mifune 饰）和副将三木因为平叛得力，准备回城领赏。途中，二人阴错阳差走入了密林深处，偶遇一白发老妪弹琴吟唱。他们觉得此事蹊跷，怀疑是敌方故布疑阵，因此上前以武力逼其就范。但此人却预言鹫津将夺城主之位，三木之子也将继承大统，正当两人将信将疑之时，此人化作一道白光销声匿迹。此后，回到城中，鹫津做了北城城主，但念及预言，心有不甘，于是在妻子浅茅的怂恿下，弑君，自立为蜘蛛巢城城主，然而这才只是预言的开始……©豆瓣', '三船敏郎', '黑泽明', 8.5, 27386, 'tt0050613', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p647422117.jpg', 0.2, 0.7, 11, 49.5, 38.7, '0.004897,0.162838,-0.544447,0.513642,0.423380,0.237644,0.422678,0.350308,-0.448746,-0.335685,0.327907,0.672389,0.174772,-0.009021,0.070826,-0.143444,-0.123365,-0.438877,0.073474,-0.322447,0.049217,-0.208382,0.053276,-0.282599,-0.287114,-0.174824,0.815607,0.622674,-0.099276,0.402584,-0.059576,0.333673,-0.424602,0.532825,0.086344,-0.084205,-0.241874,-0.169443,-0.135703,0.200849,-0.373422,-0.254961,-0.307750,0.071368,-0.166802,0.343033,0.555893,-0.382180,-0.174269,-0.162171,-0.048086,-0.478765,0.135975,0.139100,0.426580,0.052301,-0.098549,0.142021,-0.157338,-0.186914,-0.267487,0.007620,-0.422372,0.068078,-0.017438,-0.107802,-0.452105,0.024097,-0.156349,-0.224939,0.073905,-0.377842,0.245943,0.424953,0.425343,-0.245405,-0.138550,0.060053,-0.278620,-0.106681,0.478418,-0.020648,-0.207429,-0.171131,0.471248,-0.295748,0.227418,-0.086106,-0.095307,-0.039197,0.197371,0.165331,0.205847,0.027877,-0.161774,-0.163108,-0.578830,0.240750,0.030868,-0.108204,-0.338739,-0.296991,0.162187,0.233800,-0.196671,0.067515,0.223620,0.333815,0.156511,-0.585353,-0.101941,0.253091,0.181109,-0.358004,0.388509,-0.163064,-0.016900,-0.106291,0.155012,0.260766,0.086675,0.350532,0.155393,0.083201,-0.239414,-0.218370,-0.458791,0.043947', '26759819', '1968790', '1303390', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294829', '拜见岳父大人', '喜剧', '格雷戈（Ben Stiller 本•斯蒂勒 饰）准备向相恋多年的女友潘米拉（Teri Polo特莉•保罗 饰）求婚时，意外获悉了求婚成功成功与否，不仅要过美人关，更要过岳父关。潘米拉的姐姐下个礼拜即将举行婚礼，届时格雷戈将和潘米拉一起回家参加婚礼。小伙子心想这次正是讨好未来岳父，搞定岳父那关的大好时机。格雷戈的名字在美语中很容易被理解成“同性恋•性交者”的意思，有着这么个稀奇古怪的名字，注定格雷戈拜见未来岳父之行不会如他所料那般顺利。果然，当他们来到了潘米拉家时，格雷戈虽然表现得文质彬彬，但当他总是插话时力图幽默却效果相反时，未来岳父（罗伯特•德尼罗 Robert De Niro 饰）的脸色越来越难看。©豆瓣', '罗伯特·德尼罗', '杰伊·罗奇', 7.1, 58179, 'tt0212338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1435970119.jpg', 0.5, 4.4, 45, 40.7, 9.4, '-0.049938,0.090132,-0.617887,0.374928,-0.250373,-0.367213,0.315321,0.067926,-0.513873,-0.352457,-0.302962,0.567401,-0.588893,0.227266,0.689568,-0.036592,-0.287643,-0.415062,-0.042583,-0.062004,-0.075318,-0.473752,-0.170703,-0.051271,-0.118127,-0.390572,0.141700,0.180942,-0.030759,0.250423,0.298892,0.164741,0.282646,0.313498,-0.063529,0.021393,0.184298,0.397520,-0.451277,0.236853,0.125804,0.252728,-0.025884,0.206643,0.219434,0.282226,0.029597,-0.313635,-0.268822,-0.080802,0.398562,0.061440,0.383291,0.304775,-0.003506,-0.067453,0.379623,0.252371,0.018854,-0.008265,0.138816,-0.536980,-0.389439,0.434066,0.115654,-0.173293,-0.483181,-0.145903,-0.179294,0.225209,0.076249,-0.366469,0.084481,0.498872,0.381436,0.303069,-0.013171,0.231947,-0.384429,0.118892,0.637769,0.125002,-0.075935,0.200149,0.014143,-0.442074,0.286124,-0.010732,-0.482564,0.358602,0.335670,0.002927,0.088219,0.170493,0.104932,-0.434542,-0.237499,0.216326,0.006424,-0.238953,0.254882,-0.463357,0.140983,-0.378208,-0.059840,-0.059297,-0.191647,-0.317031,0.345080,-0.640499,0.323659,-0.008125,0.158899,-0.481496,0.453855,0.492132,0.057054,-0.510788,0.084363,0.229305,0.174640,-0.157545,0.091364,0.207461,0.320342,-0.469082,0.037234,0.596722', '1308429', '1292869', '24325856', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294833', '花木兰', '剧情', '花木兰是家中的长女，性格爽朗率真，父母极力想帮女儿找到一个好归宿，可是多次努力未果。此时却收到了北方匈奴侵略的消息，朝廷召集各家各户的壮丁。木兰父亲也在名单之内，木兰不忍年迈残疾的父亲征战沙场，决定割掉长发，偷走父亲的盔甲，决定女扮男装代父从军。花家的祖先为了保护木兰，便派出了心地善良的木须从旁帮忙。从军的过程中，木兰凭着坚强意志，通过了一关又一关的艰苦训练，她的精神也感动了所有战友。就在战况告急的时候，她也被发现了女子的身份。她被遗留在雪地中，而最后也是她的及时出现，顺利协助大军击退了匈奴。©豆瓣', '温明娜', '巴里·库克', 7.9, 226911, 'tt0120762', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2443062814.jpg', 0.3, 1.6, 24.8, 48.6, 24.8, '-0.104487,0.242109,-0.763533,0.654077,-0.376889,-0.380789,0.347813,-0.041890,-0.712649,-0.146233,0.272076,0.666156,0.308597,0.150192,0.055179,0.147576,-0.201912,-0.822514,-0.057249,-0.044005,-0.352245,-0.213564,-0.149874,-0.227615,-0.031953,-0.516562,0.615134,0.069450,-0.005023,0.537399,0.102772,0.157556,-0.070155,0.589910,-0.270565,0.114043,-0.076676,-0.125450,-0.061378,0.189010,-0.083226,-0.497423,-0.289321,0.198968,0.018503,0.595675,0.566124,-0.127351,-0.068217,0.133677,0.114400,-0.317873,0.125034,0.298409,0.574211,0.149403,0.183203,0.262041,-0.240920,-0.118440,-0.204049,0.001622,-0.767096,-0.198889,0.209998,-0.034292,-0.966827,0.558643,-0.124913,0.031333,0.074935,-0.570144,0.162233,0.468166,0.109483,0.229527,-0.304955,0.063355,-0.310282,0.306306,0.728205,-0.270146,-0.041063,0.090048,-0.211050,-0.377811,0.496817,-0.336147,-0.408706,0.023166,0.397151,0.057621,-0.214672,0.003476,-0.397481,0.039886,-0.502031,-0.106427,-0.090969,-0.236388,-0.035079,-0.147066,-0.332541,-0.162910,-0.509559,0.087053,0.042215,-0.055777,0.781537,-0.695705,0.160584,0.530968,0.238221,-0.597639,0.457250,0.230565,0.256448,0.207479,0.181408,0.038941,0.080161,0.405179,0.239462,0.089278,-0.180295,-0.317791,-0.649689,0.380632', '35030151', '1301022', '35461732', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294857', '魅力四射', '喜剧', '蓝丘高中有一支著名的拉拉队名叫“托罗”，这支队伍已经连续六届称霸在全国的拉拉队比赛。多伦斯（克尔斯腾•邓斯特 饰）接手这支拉拉队成为新一任队长，她雄心勃勃的想要队伍在自己的带领下继续光辉的前程。就在她们正准备积极备战与全国比赛的时候，多伦斯才惊讶的发现，那套她们引以为豪的舞步原来是前任队长从对手那里学来的。这便使多伦斯与队友们着急不已，她们也只能重新编排一套新的舞步。可是这并不是件容易的事，她们都显得信心不足。与此同时，她们的强劲对手克罗佛高中的拉拉队也正陷入了经费问题的困难当中。可是时间并没有因为她们的努力而放慢脚步，比赛的时间还是如期而至，到底谁能得到最后的冠军呢？©豆瓣', '克斯汀·邓斯特', '佩顿·里德', 6.9, 5317, 'tt0204946', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1452331723.jpg', 1, 5.3, 52.1, 30.7, 11, '0.004197,-0.052004,-0.674055,0.522845,-0.145452,-0.535497,0.408250,-0.101780,-0.499247,-0.167849,0.264132,0.559619,0.121578,-0.027250,0.115837,-0.269122,-0.363614,-0.884755,0.082444,-0.183838,-0.243840,-0.440685,-0.276656,-0.189827,0.213449,-0.192475,0.570833,0.028472,-0.069653,0.560164,0.502824,0.019814,0.288964,0.383398,-0.028427,-0.110928,0.310856,0.021937,-0.083353,-0.032189,0.069794,-0.119996,-0.683797,0.183269,0.476746,0.216196,0.327182,-0.172114,-0.124732,0.149408,0.106525,-0.269691,0.168719,0.050577,0.316917,0.002095,0.382395,-0.036063,0.041547,0.294531,-0.410016,-0.124863,-1.128824,0.326796,0.103016,0.130029,-0.499915,0.591186,-0.233094,-0.272324,0.206979,-0.364661,0.032772,0.685227,0.325196,0.133221,-0.379959,-0.175202,-0.430990,0.066188,0.620144,-0.009192,-0.313789,0.252526,0.016333,-0.292735,-0.286369,-0.230142,-0.161614,0.002263,0.324616,0.275392,0.341660,0.066037,-0.477437,0.177375,-0.139793,-0.539178,-0.023285,-0.357535,0.013344,-0.397993,0.134571,-0.192279,-0.334865,0.146612,0.055666,-0.125639,0.813060,-0.925722,0.264081,0.519264,0.231515,-0.444072,0.311987,0.153007,0.340592,-0.086437,-0.473213,-0.147613,-0.242254,0.484062,0.186212,0.547397,0.105799,-0.521999,-0.290918,0.523601', '1793491', '25917239', '30163500', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294858', '临时特工', '喜剧', '身为中情局探员的，凯文（克里斯·洛克 Chris Rock 饰）目前正在执行一项危险的卧底任务并且已经得到了至关重要的线索。不幸的是，就在这个节骨眼上，凯文被杀害了，为了任务的顺利进行，中情局找到了凯文的孪生兄弟杰克（克里斯·洛克 Chris Rock 饰），希望他能够代替死去的哥哥。和凯文的精明强干不同，杰克只是一个普通的年轻人，为了让他更快的适应新的工作，经验丰富的老探员奥克斯（安东尼·霍普金斯 Anthony Hopkins 饰）成为了杰克的“教练”。没想到，脾气火爆的杰克对奥克斯的存在十分不感冒，两人关系紧张。时间紧迫，一旦杰克的伪装被识破，他将面临死亡的命运，在这样的危机时刻，杰克和奥克斯这一对冤家搭档能否顺利的完成任务呢？©豆瓣', '安东尼·霍普金斯', '乔·舒马赫', 6.5, 6012, 'tt0280486', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1501580581.jpg', 1, 8.8, 59.1, 25.8, 5.4, '0.438383,0.074361,-0.504252,0.520354,-0.456000,-0.406128,0.502650,0.149689,-0.431429,-0.271981,0.453187,0.778829,-0.099160,-0.216178,0.356054,0.085019,-0.399304,-0.594237,-0.017075,-0.090048,-0.413626,-0.739433,-0.621059,-0.349064,-0.020433,-0.252866,0.713350,0.078305,-0.010972,0.280845,0.294424,0.408536,0.294944,0.462067,-0.170444,-0.030437,0.463399,-0.388002,-0.217848,0.405450,0.335743,0.177558,0.044513,0.387466,0.084364,0.487717,0.498885,-0.335501,-0.322213,-0.072878,0.278334,-0.477805,0.150568,0.178453,0.307111,-0.272674,-0.032370,0.317063,-0.210611,-0.029085,0.071024,-0.066707,-1.312470,0.209755,0.094511,0.401915,-0.455281,0.342540,-0.419130,-0.119367,0.148628,-0.428017,0.040335,0.712106,0.384584,0.324335,-0.193776,0.026015,-0.457285,-0.016953,0.620869,-0.177349,-0.425500,0.376226,-0.229999,-0.343454,-0.138508,-0.296620,-0.459055,0.109925,0.521828,0.056975,-0.169463,0.160948,-0.504512,0.014185,-0.458804,-0.176208,-0.312246,-0.525720,-0.114558,-0.596851,-0.091135,-0.333218,-0.498437,-0.057340,0.021622,-0.379718,0.731159,-0.886548,0.152401,0.730663,0.157113,-0.408456,0.427481,0.453495,0.256885,-0.578411,-0.169748,0.032682,0.116249,0.471831,0.326867,0.433647,0.270450,-0.388929,-0.214325,0.499733', '1793491', '27009869', '26678784', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294859', '泥醉天使', '剧情', '战败后的日本，真田（志村乔饰）是名喜欢喝酒的贫民社区医生，他擅长治疗肺结核。一天黑社会头目松永（三船敏郎饰）由于手上受伤找他治疗，谁知被真田看出了肺结核的症状。他劝松永去照X光检查一下，可松永不愿接受自己生病的事实，反而大骂真田一通并争执起来。但是松永回去以后症状越来越严重，拍片后证实确实是肺结核，嘴上逞强的他还是接受了真田的治疗。然而，松永的黑社会大哥冈田（山本礼三郎饰）从监狱里出来，他逐渐取代松永在黑帮里的位置并拥有了一切，病入膏肓的松永只能孤注一掷……©豆瓣', '志村乔', '黑泽明', 8.1, 11278, 'tt0040979', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2346571516.jpg', 0.3, 1.2, 18.4, 54, 26.2, '0.187998,0.117753,-0.103690,-0.047060,-0.321206,-0.246386,0.396486,0.177949,-0.505993,-0.264014,-0.012536,0.469959,0.137430,0.348692,-0.121631,0.189465,-0.246303,-0.432889,0.110711,0.194536,-0.290122,-0.555855,-0.032345,-0.322523,-0.190530,-0.165295,0.521628,0.324931,-0.367694,0.233477,0.121915,0.151775,0.470191,0.392189,0.262210,0.051413,-0.170114,-0.238067,0.038576,0.386075,0.364786,-0.324390,-0.003737,0.513315,0.152711,0.502262,0.083969,-0.076749,-0.277016,-0.209129,0.316481,-0.195889,-0.315814,0.320205,0.359458,0.064639,0.184029,0.130979,-0.370893,-0.004676,-0.271724,0.413683,-0.342614,-0.144978,0.019993,0.344432,-0.298106,0.475916,-0.123480,-0.048615,0.031309,-0.202816,0.062774,-0.009172,0.070924,0.145623,-0.381167,-0.071225,-0.317917,-0.027434,0.455819,-0.154942,-0.155618,-0.002094,-0.214229,-0.369878,0.003418,-0.563349,-0.103679,0.076793,0.040961,0.080246,-0.661050,-0.120849,0.062081,-0.094730,-0.142829,-0.161008,-0.277165,0.179143,0.410996,-0.525932,0.146881,-0.243245,-0.421098,-0.208105,0.052464,-0.341393,0.494245,-0.749105,0.069370,0.578134,0.130187,-0.316901,0.022770,0.362945,-0.135449,0.027358,-0.039965,0.289495,0.204662,0.371372,0.314809,0.354392,0.028539,-0.117775,-0.292684,0.308752', '30255079', '35030151', '22964524', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294863', '狙击职业杀手', '动作', '一直以来，联邦调查局副局长卡特（西德尼·波蒂埃 Sidney Poitier 饰）和俄国情报官瓦伦蒂娜（戴安·维诺拉 Diane Venora 饰）都在追击一名十分危险的犯人，他手持高杀伤性化学武器，精通电脑和变装术，个性狡猾又残忍，是威胁到世界和平的重大隐患，他甚至连名字都没有，人送代号“豺狼”（布鲁斯·威利斯 Bruce Willis 饰）。在屡战屡败的不利立场之下，卡特和瓦伦蒂娜决定动用手上的“秘密武器”——一位曾经和豺狼交过手的被囚杀手莫昆（理查·基尔 Richard Gere 饰）。在经验丰富的莫昆的帮助下，卡特一行人能否顺利捕获豺狼呢？对于莫昆来说，前路上又有怎样的危险在等待着他呢？©豆瓣', '布鲁斯·威利斯', '迈克尔·卡顿-琼斯', 6.8, 7065, 'tt0119395', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2639574541.jpg', 0.9, 8.2, 49.7, 33.2, 7.9, '0.094427,-0.060530,-0.818675,0.689126,-0.110788,0.036145,0.679069,-0.002247,-0.466955,-0.172365,0.367060,0.574024,0.215669,-0.205514,0.325080,-0.059979,-0.530755,-0.737734,-0.017566,-0.116587,-0.414835,-0.845800,-0.669297,-0.251183,-0.045455,-0.470442,0.284542,0.028200,-0.228669,0.266751,0.296443,0.622032,-0.145340,0.463314,-0.194850,-0.181197,0.517428,-0.170457,-0.228675,0.233021,0.086762,0.001997,-0.145466,0.373777,0.196199,0.459238,0.329409,-0.634236,-0.186843,0.067803,-0.024204,-0.222617,0.195196,0.045043,0.419510,-0.232567,0.156484,0.341458,0.117722,0.050717,0.100080,-0.007590,-0.884046,0.029419,0.057814,0.283422,-0.716655,0.368761,-0.431485,0.065613,0.093145,-0.263326,0.046879,0.283363,0.274499,0.089281,0.029327,0.125665,-0.530698,-0.013691,0.500609,0.147737,-0.502928,-0.101234,0.006715,-0.405891,-0.283453,-0.318879,-0.493189,-0.044026,0.374518,-0.016502,0.023992,0.106369,-0.380686,0.105154,-0.206825,0.131491,0.041510,-0.135331,-0.178528,-0.640793,0.200283,-0.534285,-0.545565,0.045579,0.120449,-0.064027,0.677720,-0.746154,0.412890,0.488456,0.397083,-0.262086,0.410753,0.232792,0.009494,-0.213847,-0.434311,0.237308,0.274343,0.165924,0.267326,0.271816,0.222403,-0.204627,0.058229,0.504069', '1307442', '24753477', '3006892', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294893', '第六日', '动作', '克隆技术在不远的未来有了长足的进步，但复制人仍是法理上不可逾越的禁区，政府通过《第六天法》严格禁止克隆人。飞行员亚当（Arnold Schwarzenegger 饰）拥有幸福的家庭，他出于本能的厌恶那些违背自然规律的基因技术。亚当平时的工作是和搭档送游客上雪峰，这天他们为宠物克隆公司的老板恰克（Tony Goldwyn 饰）服务，搭档顶替亚当驾驶却发生了意外……回到家中的亚当发现居然有一个克隆人顶替了自己的位置参加他的生日宴，莫名惊恐之下他又被来路不明的杀手追杀，他很快明白自己成为了宠物克隆公司的人类复制试验品，做为母体，他面临被消灭的危险。在逃亡的过程中亚当与暴力反对克隆人计划的组织合作，成功潜入宠物克隆公司，并控制了克隆人技术的负责人威尔博士……©豆瓣', '阿诺·施瓦辛格', '罗杰·斯波蒂斯伍德', 7, 35647, 'tt0216216', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1437934412.jpg', 0.5, 4.9, 48.4, 37.4, 8.8, '0.277345,0.127282,-0.592938,0.419068,-0.343376,0.020696,0.399808,0.089448,-0.428917,-0.240752,0.358387,0.786370,0.236878,-0.081751,0.173758,-0.021962,-0.204818,-0.421656,0.013367,-0.052591,-0.330465,-0.458804,-0.198245,-0.392106,0.062672,-0.514900,0.806453,-0.152620,-0.419144,0.223347,0.090795,0.355733,-0.047547,0.388836,-0.031730,-0.038457,0.329312,-0.260915,-0.198650,0.274626,-0.256154,-0.002559,0.149391,0.116193,-0.097162,0.489781,0.508173,-0.209639,-0.267980,-0.339357,0.411055,-0.461032,0.002299,-0.048401,0.382078,0.162110,-0.164953,0.209188,0.028441,-0.062874,0.081736,0.009971,-1.249567,-0.194879,0.138531,0.094851,-0.566499,0.366381,-0.154212,0.143679,0.147731,-0.341530,0.176656,0.400162,0.268528,0.332104,-0.112748,0.274019,-0.545590,0.028184,0.526544,-0.184621,-0.498228,0.251386,-0.459433,-0.619307,-0.036552,-0.437276,-0.176859,-0.077521,0.208769,0.159616,-0.252375,0.254447,-0.631126,0.004601,-0.213142,-0.194046,0.041566,-0.469015,0.099599,-0.687955,0.015138,-0.135214,-0.434307,-0.089557,0.083613,-0.467051,0.600922,-0.928674,0.149508,0.825410,0.423227,-0.605201,0.738089,-0.052827,0.053678,-0.467464,-0.109641,0.047598,0.142472,0.467351,-0.042062,0.346705,0.267216,-0.073912,-0.394678,0.377042', '1793491', '27009869', '27073234', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294911', '茶花女', '剧情', '巴黎风尘女郎玛格丽特约见华维尔男爵却与青年亚芒认识。后俩人在书店相遇，玛得知亚芒每天送花探病，深受感动邀其参加生日宴会。亚芒见她强颜欢笑更加怜惜，遂对她示爱。当晚男爵回来亚芒吃了闭门羹，懊悔之余斥责她无情，请求父亲资助他出国旅行。玛赶去见他并互吐心意，玛同意和男爵分手随他到乡下调养身体。亚芒父亲劝玛放弃亚芒，玛因真心爱亚芒，为其着想，骗亚芒与其分手。几个月后亚芒与男爵及玛在赌场相遇，不料亚满大赢，叫玛随他走，玛拒绝，亚芒盛怒之下加以侮辱，并与男爵决斗，男爵受伤，亚芒畏罪潜逃。玛深爱亚芒，却拒绝任何资助，病情加重，待亚芒了解真相玛已撒手人寰。©豆瓣', '葛丽泰·嘉宝', '乔治·库克', 8.3, 14619, 'tt0028683', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p964256918.jpg', 0.2, 1, 16.1, 48.7, 34, '-0.243295,-0.000249,-0.559440,0.227319,0.125461,-0.556156,0.465970,0.126304,-0.178914,-0.408986,-0.366936,0.931394,-0.372945,0.344981,0.407126,-0.050171,-0.268348,-0.317624,0.366176,0.101611,0.070542,-0.713049,0.523172,-0.344710,-0.161622,-0.187635,-0.039792,0.128557,-0.155609,0.644974,0.472180,0.161071,-0.087539,0.505889,0.139066,-0.028980,-0.211205,0.157861,-0.499232,0.098826,0.167235,-0.022987,-0.457206,0.120029,0.474181,0.395306,0.234030,0.034275,-0.046846,-0.072403,0.315170,-0.368732,0.268819,0.205206,-0.020771,-0.140591,-0.019326,0.288230,-0.167784,-0.034168,-0.026421,-0.263086,0.091304,0.354455,-0.165792,-0.191442,-0.418218,0.190511,-0.258556,0.274798,0.044912,-0.125707,0.019121,0.380189,-0.277078,0.019448,0.003074,0.041336,-0.309585,-0.068352,0.825754,0.011161,0.237149,-0.009663,-0.135302,-0.341163,0.507948,-0.333431,-0.246357,0.250695,-0.108077,0.236758,-0.155042,0.063695,-0.124205,-0.518403,-0.558522,0.280233,0.383473,-0.663433,0.180723,-0.617046,-0.241993,-0.075226,-0.416674,-0.089301,0.104567,-0.371484,-0.080227,-0.645313,0.295448,0.282148,0.715123,-0.816570,0.395356,0.332461,-0.146127,-0.207442,0.029211,0.787543,0.496661,-0.090923,-0.007086,-0.190107,0.228652,0.307425,-0.417016,0.085947', '1292869', '1297239', '1857175', '26393561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294915', '克莱尔的膝盖', '剧情', '35岁的中年外交家杰罗姆（让-克劳德·布里亚利 Jean-Claude Brialy饰）是一个具有深刻洞察力和幽默感的男人。即将结婚的杰罗姆，以单身汉的身份参加了老朋友奥罗拉（奥罗拉·科努 Aurora Cornu饰）邀请的度假之旅。在美丽而宁静的乡村庄园，奥罗拉介绍了两位花季少女劳拉（碧翠丝·罗曼德 Béatrice Romand饰）和克莱尔（劳伦斯·莫纳亨 Laurence de Monaghan饰）与他认识。年轻美丽的克莱尔让杰罗姆不能自拔地心生欲望。当他看到克莱尔的男友抚摸她膝盖的动作，产生了也要摸一摸克莱尔膝盖的念头。由国际电影大师埃里克·侯麦执导的影片《克莱尔的膝盖》，是侯麦《六个道德故事》的系列影片之一。本片荣获1972年第29届金球奖电影类-最佳外语片提名等多项大奖。©豆瓣', '让-克洛德·布里亚利', '埃里克·侯麦', 7.8, 12222, 'tt0065772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554679911.jpg', 0.3, 1.6, 24.3, 53.3, 20.5, '0.069563,-0.034009,-0.665233,0.717143,0.068353,-0.417979,0.646673,0.326046,-0.158716,-0.306254,0.149106,0.995977,-0.550483,0.366574,0.570246,0.280548,-0.229286,-0.624017,-0.190146,-0.073903,-0.182411,-0.325509,-0.364836,-0.139648,-0.058186,-0.489775,0.552399,-0.287615,-0.406512,0.396177,0.597479,0.306686,0.318838,-0.019819,-0.195525,-0.022852,0.518493,-0.136976,-0.484054,0.238680,0.092747,-0.082635,-0.103326,0.162782,-0.075595,0.365503,0.786931,-0.133039,0.166222,0.139709,0.520145,-0.153848,0.038065,-0.052063,0.116177,-0.147743,0.021444,0.159615,0.233920,0.240472,0.307696,-0.449288,-0.663623,0.142560,0.195119,0.207512,-0.405581,0.324323,-0.297578,0.033790,0.100045,-0.119886,0.166974,-0.003190,0.216230,0.334541,0.242615,0.167017,-0.125897,0.452708,0.187781,0.165070,-0.207117,0.469115,-0.527812,-0.798650,-0.194538,-0.117724,-0.396522,0.079081,0.392814,-0.178339,0.095005,0.237554,-0.519780,-0.128606,-0.241937,-0.230674,0.030864,-0.361310,0.096237,-0.788196,-0.276268,-0.397771,-0.128565,-0.120409,0.102440,-0.196061,0.669997,-0.419335,0.216454,0.543977,0.152776,-0.118118,0.998994,0.108824,-0.132630,-0.301104,0.013213,0.375950,-0.065394,-0.314916,-0.010657,0.575896,0.023398,-0.185457,-0.320813,0.465106', '1292925', '2027945', '1829654', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294917', '巨蟒与圣杯', '喜剧', '带着敲椰子壳的仆人，亚瑟王（格雷厄姆·查普曼 Graham Chapman 饰）假装骑着马寻找骑士和城堡，一路看尽民不聊生的景象，和各种鸡同鸭讲的民众交流，最后招揽到一群圆桌骑士。他们一起假装骑着马，到了卡米洛特城堡，在城堡外，他们遇见天上浮现的上帝，要求他们去寻找圣杯。他们试图用“木獾记”攻陷一座法国人的城堡，但是却忘记藏身在木獾里，最终被法国人打得落花流水。经历失败的亚瑟王与骑士们开始分头行动，寻找圣杯的任务意义重大，更多不靠谱的人和事一路等待这群不靠谱的骑士们……本片是唯一一部进入IMDB前50排名的“无厘头”电影。片中“巨蟒团”六名核心成员每人出演了4-10个角色，包揽片中大部分角色。©豆瓣', '格雷厄姆·查普曼', '特瑞·吉列姆', 7.9, 19458, 'tt0071853', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1316883036.jpg', 1.8, 4.3, 21.9, 40.3, 31.7, '0.365918,-0.096288,-0.433041,0.715417,0.067529,0.020317,0.709434,-0.212406,-0.155135,-0.213424,0.416537,0.742568,-0.144494,0.097663,0.272330,-0.466549,-0.439423,-0.535683,-0.128386,-0.134022,-0.242684,-0.211216,-0.124037,-0.343309,-0.332423,-0.156710,0.862094,0.124976,-0.040984,0.227394,0.271886,0.238639,-0.430857,-0.076444,-0.092451,0.026897,0.243256,-0.096151,-0.065602,0.304058,-0.397364,-0.039557,-0.479612,-0.006503,0.158183,0.138414,0.806630,-0.506973,0.112181,0.003573,0.096037,-0.339561,-0.064642,0.175894,0.492442,0.056081,0.038588,0.115639,0.265110,0.014971,-0.018641,-0.256030,-0.742295,-0.074096,0.146324,0.312862,-0.791330,0.306041,0.145522,0.165321,0.210688,-0.096286,0.149267,0.154785,0.039361,0.217252,-0.001421,-0.130571,-0.654676,0.159260,0.573391,-0.144560,-0.246108,0.027044,-0.058947,-0.385414,-0.268844,-0.138117,-0.236370,-0.195513,0.360183,-0.118480,0.075692,0.001555,-0.902411,0.134577,-0.123014,-0.521893,0.094903,-0.366248,-0.001684,-1.088506,0.196289,-0.234535,-0.075783,0.291965,0.040590,-0.009482,0.692559,-0.523504,0.151724,0.397548,0.088778,-0.381579,0.667975,0.075014,0.085512,-0.134063,-0.113795,0.154220,0.230696,0.367948,0.268862,0.265951,-0.161472,-0.192176,-0.429864,0.400678', '1307897', '2369613', '1322847', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294927', '星愿', '剧情', '小时候因为脑膜炎使洋葱头（任贤齐 饰）失去视力及说话的能力，后来他一边在接受治疗一边在医院工作。他一直喜欢长期照顾他的护士秋男（张柏芝 饰），可是当时医院里的胡医生（苏永康 饰）也同时在追求秋男。洋葱头终于在一个晚上向秋男表白，秋男也接受了他的爱意。可是洋葱头在回家的路上被车撞死了，在天堂里的洋葱头祈求天使让他回到人间可以了结他与秋男的感情，可是只有5天的时间。洋葱头以保险调查员的身份接近秋男并大献殷勤，可是秋男还是无法忘记生前的洋葱头，洋葱头感动之余也使秋男逐渐发现了原来他就是洋葱头，而5天后的晚上，正是他们要再次分开的时候……©豆瓣', '任贤齐', '马楚成', 7.2, 98132, 'tt0213314', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554394952.jpg', 0.5, 3.7, 42.3, 40.5, 13, '-0.045541,0.177453,-0.323327,0.221290,-0.139761,-0.443189,0.579037,0.055376,-0.531134,-0.244264,-0.326984,0.276026,-0.134567,0.481947,0.192795,-0.091077,-0.272004,-0.612598,-0.179056,-0.212591,-0.641780,-0.282782,0.161826,-0.317432,-0.050169,-0.271745,0.452468,0.025575,-0.013208,0.264146,0.584607,-0.025932,-0.016546,0.710487,-0.281556,-0.217573,-0.273804,-0.073130,-0.231751,0.359115,0.549274,-0.177646,-0.198431,0.360834,0.114909,0.363013,0.636335,-0.295035,-0.334901,-0.041919,0.387570,-0.058107,-0.100288,-0.093432,0.461834,-0.275504,0.338670,-0.134131,0.075546,-0.065352,0.173964,-0.037183,-0.308801,0.105224,0.094364,0.088434,-0.550146,0.342890,0.147961,0.106412,0.118266,-0.273715,0.243500,-0.069754,-0.034244,0.487484,-0.410017,-0.175794,-0.360507,0.412743,0.619526,0.270129,0.150918,0.405074,-0.116592,-0.568439,-0.297413,0.052471,-0.719197,-0.004549,-0.003113,0.100001,-0.368156,-0.206374,-0.299849,-0.099747,-0.148383,0.174090,-0.158683,-0.395193,0.098900,-0.358308,0.207632,-0.425098,-0.172924,0.303606,0.083582,-0.327662,0.688656,-1.101224,0.299652,0.499859,0.503025,-0.521309,0.827677,0.136372,0.075830,-0.266217,-0.232348,0.410430,-0.079274,0.025292,0.166481,0.387438,-0.153706,-0.172308,-0.344326,0.389574', '2052978', '1306544', '3445516', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294929', '蝙蝠侠归来', '动作', '蝙蝠侠（迈克尔•基顿 Michael Keaton 饰）归来了！自从打败“小丑”后，高谭市获得片刻的宁静。然而，又一个强大的对手出现了！这次是脾气乖张暴戾的“企鹅”。“企鹅”因为是次子，所以自幼就被父母遗弃，落下残疾，导致“企鹅”对整个社会都心生不忿。长大后“企鹅”的企鹅决心杀回高谭市，将市内的长子都杀光，并控制整个高谭市。在迫使邪恶商人马克斯（克里斯托弗•沃肯 Christopher Walken 饰）帮忙后，“企鹅”顺利当上了高谭市长。同时，马克斯的秘书西莉娅（米歇尔•菲佛 Michelle Pfeiffer 饰）意外获知了他们的秘密，在遭受他们迫害时意外获得了超强能力，成为了亦正亦邪的猫女。蝙蝠侠这次将面临“企鹅”和猫女的双重挑战！©豆瓣', '迈克尔·基顿', '蒂姆·波顿', 7.4, 42764, 'tt0103776', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1502647347.jpg', 0.6, 3.6, 37.4, 43, 15.4, '0.008535,0.206608,-0.635620,0.511610,-0.181924,-0.019802,0.459823,0.281020,-0.489438,0.076928,0.168239,0.885245,-0.297707,0.104746,0.043474,-0.214883,-0.161910,-0.581994,-0.020604,-0.136706,-0.178186,-0.402779,-0.309419,-0.082405,0.147103,-0.490700,0.410003,0.054474,-0.245206,0.606722,0.448541,0.311958,-0.022651,0.364308,-0.016432,0.261000,0.131667,-0.063013,0.194552,0.341539,-0.084716,0.093246,0.189858,0.293440,0.132430,0.253056,0.431870,-0.472359,-0.339198,-0.495019,0.317123,-0.148472,-0.120263,0.307184,0.471786,-0.035266,0.048859,0.164493,-0.083726,0.122586,0.131118,0.046776,-0.797814,0.064798,-0.021415,-0.027382,-0.691200,0.299677,-0.122727,-0.121828,-0.014018,-0.080776,0.023448,0.184149,0.244148,0.474940,0.152024,0.439357,-0.388690,-0.073909,0.586132,0.037462,-0.475091,-0.015185,0.013269,-0.462033,-0.030357,-0.297156,-0.214026,-0.121349,0.723349,0.093740,-0.203839,0.391250,-0.503423,-0.086133,-0.317903,0.033270,-0.164161,-0.416530,-0.080255,-0.501835,-0.102639,-0.277047,0.070674,0.064432,0.075344,-0.440650,0.768278,-0.920958,0.513554,0.549250,0.372730,-0.560727,0.418549,-0.110904,0.129804,-0.015136,0.130699,0.218820,0.363496,0.508732,0.253971,-0.040241,-0.245014,-0.477004,-0.155339,0.515041', '1309069', '35144311', '1793491', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294934', '失陷猩球', '动作', '故事发生在1968年，一场意外中，泰勒（查尔登·海斯顿 Charlton Heston 饰）和诺娃（琳达·哈里逊 Linda Harrison 饰）的飞船穿越到了两千年后的时间线中，他们来到了一个被人猿统治的星球上，直到两人在沙滩上发现了自由女神像的残骸之后他们才恍然大悟，原来这里并不是什么外星球，而是人类唯一的家园——地球。地面上突然出现的巨大裂痕让泰勒和诺娃调入了庞大繁杂的地底世界之中，他们要面对的，是猿族首领佐斯博士（莫里斯·埃文斯 Maurice Evans 饰）的无情追杀。1970年，为了拯救泰勒一行人，救援飞船来到了地球，哪知道也穿越了时空，布伦特（詹姆斯·弗朗西斯 James Franciscus 饰）是飞船上唯一的幸存者，并且最终幸运的和诺娃成功会师。两人于无意之中得知了猿组要从地球上铲除所有人类的计划。©豆瓣', '詹姆斯·弗朗西斯科斯', '泰德·珀斯特', 6.5, 5585, 'tt0065462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2242995213.jpg', 2.2, 13.1, 49.5, 25.6, 9.6, '0.329159,0.311414,-0.869219,0.506263,0.004391,-0.246617,0.741690,-0.191463,-0.547535,0.058924,0.069029,0.807490,-0.240896,0.080660,0.388118,0.386192,-0.516768,-0.655577,-0.008584,-0.498567,-0.866928,-0.463855,-0.597042,-0.372889,0.038472,-0.467373,0.547572,0.282603,0.072656,0.497225,0.062492,0.181364,-0.219589,0.358613,-0.067317,0.192042,0.265404,0.115026,-0.180633,0.198354,-0.435376,-0.229070,0.001063,0.298701,-0.139199,0.310509,0.516378,-0.433783,0.061925,-0.233335,0.032653,-0.417062,0.027208,-0.067738,0.547696,-0.253015,0.077420,0.293985,-0.024165,-0.090909,0.190207,-0.083612,-0.608591,-0.084012,-0.245701,0.196074,-0.487817,0.489986,-0.038906,-0.166068,-0.086755,-0.383579,0.388286,0.547953,0.434273,0.322862,-0.155478,-0.212678,-0.346574,-0.038784,0.578464,-0.072674,-0.431137,0.163730,0.096251,-0.486097,-0.335192,-0.059078,-0.136506,-0.015314,0.357307,0.197997,-0.283232,0.382868,-0.773302,0.175232,-0.508113,-0.384102,-0.110374,-0.294545,-0.237362,-0.607072,-0.182815,-0.362252,-0.283609,0.201671,-0.095348,-0.163031,0.507610,-0.774668,0.411581,0.592368,0.389334,-0.168417,0.639732,-0.355867,0.164840,-0.271727,0.393506,0.097546,0.084040,0.488066,0.018097,0.314444,-0.038269,-0.059572,-0.359841,0.562711', '34461680', '1298405', '3055049', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294940', '复仇在我', '剧情', '警车上，落网的连续杀人犯槚津严（绪形拳 饰）神态轻松，并在后来的审讯中拒不交代杀死职员柴田与马场的经过……槚津严出身于信奉天主教的渔民家庭，由于宗教歧视，严家的小船被没收，年幼的严试图反抗却被父亲制止，由此父亲丧失了在严心目中的地位。青年严因偷窃美军设备出狱后与加津子奉子成婚，然而很快又因诈骗入狱。父亲为阻止加津子离婚登门拜访，谁知两人却发生了不伦的关系，再次出狱的严不齿妻子与父亲所为，离家出走，从此开始了伴随杀人与诈骗的流浪旅程。严乔装大学教授与旅馆中的暗娼交好，间歇时仍然犯下累累罪行，而此时与他共居的母子二人，并不知晓身边人是日本知名的通缉犯……本片获1979年日本《电影旬报》十佳电影第一名。©豆瓣', '绪形拳', '今村昌平', 8.5, 11279, 'tt0079182', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2874692838.jpg', 0.4, 1.3, 11.5, 47.3, 39.5, '0.316410,-0.018503,-0.612026,0.507551,0.174742,-0.277237,0.771179,0.062094,-0.699425,-0.608391,-0.161510,0.595945,-0.179809,0.223602,0.179702,-0.266265,-0.226871,-0.809996,-0.283529,-0.010980,-0.167821,-0.501152,0.052338,-0.161294,-0.322716,-0.062450,0.617052,0.219443,-0.395781,0.602795,0.464822,0.308262,-0.248672,0.356798,-0.106661,-0.001210,-0.002368,0.180576,-0.484220,-0.028249,-0.049369,-0.610889,0.021430,0.004887,0.073557,0.549636,0.554432,-0.098586,-0.250960,-0.363472,0.373045,-0.248192,-0.013188,0.183567,0.571837,0.109974,0.212937,0.512162,-0.104623,0.010887,-0.010469,-0.099441,-0.570711,-0.031234,0.323342,-0.127107,-0.449392,0.384508,-0.166547,0.166144,-0.144289,0.014643,0.216757,0.250965,0.201047,0.405837,-0.053062,0.065117,-0.521601,0.152388,0.643274,-0.011117,-0.086909,0.064679,-0.201735,-0.543367,0.017093,-0.475377,-0.227690,0.078130,0.230922,0.189997,-0.351686,0.285610,-0.083228,-0.217068,-0.265529,0.158027,0.058715,-0.424000,-0.052022,-0.609070,-0.016477,-0.466885,-0.350448,0.076223,0.071666,-0.210069,0.347633,-0.775632,0.233578,0.222155,0.415175,-0.656860,0.543304,0.185343,0.190621,-0.093300,0.046935,0.110997,0.467449,0.218586,0.194993,-0.080285,-0.207210,-0.167267,0.023326,0.220939', '3263169', '1301022', '1293265', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294941', '大白鲨', '剧情', '艾米蒂岛是一个旅游度假胜地，有大批的游客来这里游泳。然而，大白鲨的出现却改变了这一切。事故从一对情侣开始，他们下海游泳，女的不幸成为了第一个牺牲者，支离破碎的尸体令人惨不忍睹。当地官员却不愿意封场调查，他们怕影响旅游收入，于是请来了生物学家布朗（理查德•德莱福斯 Richard Dreyfuss　饰）。布朗断定，这是一只非比寻常的巨大白鲨。他的提醒并没有引起当局的足够重视，紧接着又有人死于非命，事态才变得越发严重。当地一个熟练捕鱼手、警察和布朗一共三人，决心要捕杀大白鲨，凶险重重的搏斗开始了，谁才是最后的胜者？要获得这场战斗的胜利，又要付出怎样的代价？©豆瓣', '罗伊·谢德', '史蒂文·斯皮尔伯格', 7.8, 92271, 'tt0073195', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p455723402.jpg', 0.3, 1.6, 26.5, 53.3, 18.4, '0.098997,-0.253108,-0.706532,0.274432,-0.019606,-0.237008,0.851039,-0.003777,-0.364586,0.045206,0.405651,0.816766,-0.121175,-0.154918,0.067153,-0.095502,-0.379465,-0.405517,-0.079808,0.057569,-0.430188,-0.251929,-0.255683,-0.309840,-0.039213,0.043429,0.463757,0.327400,-0.329417,0.514184,0.336283,0.210874,0.105021,0.595233,-0.129614,-0.103803,0.138210,0.025054,0.106646,0.197962,-0.023412,-0.262289,-0.265385,0.262931,-0.004535,0.481971,0.417018,-0.188841,-0.341370,-0.018179,0.328249,-0.536523,0.029141,0.230015,0.484030,-0.162026,0.016200,-0.088434,-0.218072,-0.101699,0.014741,-0.001208,-0.863890,-0.053820,0.044130,0.301342,-0.440166,0.130393,-0.058234,-0.021005,-0.088702,-0.050732,0.120681,0.648384,0.223038,-0.021378,-0.033033,-0.164760,-0.468099,0.149575,1.038245,-0.202942,-0.282454,0.077698,-0.345832,-0.633256,0.105463,-0.335583,-0.060166,0.057801,0.653868,0.122737,-0.168472,0.207650,-0.565130,-0.006636,-0.408724,-0.406495,-0.405590,-0.172621,-0.082060,-0.504921,-0.094347,-0.286744,-0.203537,-0.010626,0.046089,-0.177115,0.760273,-0.681823,0.023155,0.600607,0.119514,-0.437118,0.253856,-0.079045,0.119038,-0.156489,-0.048320,-0.092677,0.137533,0.318786,0.154983,0.281418,0.414818,-0.270795,-0.090470,0.312357', '25721544', '25828589', '1292849', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294947', '大逃亡', '剧情', '二战期间，德军的战俘营里，每个人都在渴望着自由。美国人希尔（史蒂夫•麦奎因 Steve McQueen 饰）在进入战俘营的第一天起，就一直计划着越狱。虽然他的十多次逃跑都以失败告终，但希尔从未放弃。这次，希尔和英国军官罗杰计划秘密挖掘隧道带领250人一起越狱。所有人都贡献出了自己的一分力配合这次计划，有人专门负责制作大家逃跑后需要穿着的平民服装、有人负责做假证件、还有人负责储备食品等等。然而就在他们的隧道大功告成那天，隧道却被德军发现了。逃跑计划的日期一天天临近，希尔他们又开始新一轮的挖掘工作。©豆瓣', '史蒂夫·麦奎因', '约翰·斯特奇斯', 8.3, 8850, 'tt0057115', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2247201530.jpg', 0.5, 1.3, 14.1, 49.9, 34.2, '-0.037856,0.055911,-0.865787,0.443450,-0.158764,-0.303896,0.328007,-0.186656,-0.528753,-0.291733,0.230088,0.470172,-0.031415,-0.096711,0.054120,-0.064813,-0.917496,-0.523867,-0.120484,-0.273381,-0.421615,-0.262436,-0.083420,-0.628283,0.023217,-0.390244,0.542926,0.319907,-0.040859,0.158033,0.179387,-0.167219,-0.056898,0.659304,0.228414,-0.009072,0.387720,-0.383464,-0.212222,0.181552,-0.162202,-0.395707,-0.363082,0.166613,0.243900,0.556096,0.760808,-0.169817,0.041966,0.034644,0.119853,-0.415261,0.029817,0.206774,0.414063,0.060670,0.100836,0.277432,-0.103013,0.172815,-0.069132,-0.218653,-0.803748,-0.156731,-0.116196,0.136605,-0.583843,0.262539,-0.303460,0.528380,0.135697,-0.634308,-0.107459,0.578885,0.372572,0.119489,-0.241808,-0.080020,-0.699705,0.205082,0.721764,-0.265829,-0.202865,0.015367,-0.236011,-0.558160,-0.054130,0.160572,-0.352459,-0.187011,0.411097,0.017926,-0.195419,0.099581,-0.632596,0.286883,-0.091169,-0.438420,-0.006795,-0.227290,-0.077456,-1.040104,0.216753,-0.005109,-0.438006,0.329077,-0.077602,-0.074018,0.523862,-0.658607,0.249118,0.811443,0.380657,-0.458367,0.549447,-0.163919,0.304049,-0.269328,-0.042108,-0.053697,-0.083670,0.601166,0.314875,0.489371,0.153280,-0.226434,-0.307492,0.512740', '3178770', '21349734', '2079017', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294948', '憨豆先生的大灾难', '喜剧', '我们疯狂的憨豆先生（罗温•艾金森 Rowan Atkinson 饰）又来了！这次，我们的憨豆先生在英国一间画廊工作。画廊里的一副传世珍品被美国国家博物馆买走了，憨豆先生所在博物馆要派出一名专家运送这副画到美国。阴差阳错之下，这个专家就由憨豆先生担任了。飞过古板的英国， 憨豆先生来到了美国。美国国家博物馆的馆长盛情接待了憨豆，在保险库里，憨豆得以独自一人欣赏名作。正当憨豆洋洋得意地近距离观赏名画之时，憨豆一个喷嚏把口水鼻涕都喷在了这副油画上！眼看油画的色彩开始随着自己的口水四处横流，憨豆慌忙之下拿起抹布想把自己的口水擦干。这一下，这副珍品彻底毁了！憨豆最后会否因为毁坏名画而被关进监狱？©豆瓣', '罗温·艾金森', '梅尔·史密斯', 8.2, 55457, 'tt0118689', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1419600207.jpg', 0.3, 1.5, 18.4, 48.4, 31.5, '0.481782,0.258865,-0.472949,0.274788,-0.038624,-0.766512,0.591565,0.072428,-0.166613,-0.064756,0.188092,1.058689,-0.386257,0.561738,0.382674,0.075519,-0.485240,-0.544971,-0.409314,-0.207906,-0.369752,-0.187249,-0.389382,0.033400,-0.194231,-0.159704,0.065449,0.208939,0.022864,0.474485,0.384445,0.191255,-0.152177,0.093478,-0.272792,0.044326,0.277678,-0.201843,0.087980,0.113511,0.345454,-0.581608,0.074325,0.072450,0.149504,-0.056662,0.610911,-0.139336,0.227665,0.059626,0.367029,-0.519956,0.120588,0.240417,0.023372,0.057208,0.074010,-0.140755,-0.505543,0.000580,0.298295,-0.168448,-0.586859,-0.039745,-0.057513,0.184235,-0.828534,0.543141,0.094947,-0.064616,-0.083178,-0.506556,0.462460,-0.020523,0.221598,0.365732,-0.108263,-0.074767,-0.551334,0.395604,0.043077,-0.182973,0.068797,0.191941,0.015085,-0.299460,0.401038,-0.442309,-0.090027,-0.022193,0.401797,-0.215417,0.115236,-0.232809,-0.901327,-0.124656,-0.378575,-0.307497,-0.295136,0.061941,-0.347721,-0.754274,-0.144406,-0.172553,0.352178,-0.168609,0.127535,-0.051366,0.546235,-0.196763,-0.148339,0.377481,0.022513,0.045350,0.830108,-0.041376,-0.211740,0.186381,-0.171853,-0.078117,0.522021,0.643385,0.259791,0.843917,0.157186,-0.323395,-0.376800,0.299513', '1829654', '1394176', '26858510', '6128003');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294950', '四个婚礼和一个葬礼', '剧情', '查尔斯（休•格兰特）虽是婚礼上的常客，却对结婚怀有莫名疑惧。某个乡村婚礼上，他对美国姑娘凯瑞（安迪•麦克道威尔）一见倾心，不顾朋友大嚼有关她的诸多是非，与她共度了美好的一夜，次日，凯莉不支一声回了美国，查尔斯被搞得心神不宁。两月过去，伦敦某个婚礼上，两人又遇，但凯瑞正准备结婚，不过在她的主动下，两人再次共度良宵。又一月，查尔斯收到凯瑞的结婚请柬，挑礼物时，他再与凯莉相遇，对方向他讲起自己的风流韵史，搞得查尔斯很想开口同她求婚。垂头丧气地参加完凯瑞的婚礼后，查尔斯接受了他并不爱的女孩的表白，而直到某次葬礼的来临，“爱你在心口难开”的他才决定鼓足勇气向又一次遇见的凯瑞表白爱意。©豆瓣', '休·格兰特', '迈克·内威尔', 7.4, 109785, 'tt0109831', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2423672584.jpg', 0.6, 3.7, 35.6, 44.5, 15.7, '0.328529,0.120577,-0.772471,0.452171,-0.010601,-0.606174,0.868630,-0.163726,-0.153698,0.087487,0.017014,0.888625,-0.552862,0.593916,0.356245,0.429482,-0.353195,-0.803456,0.224653,-0.027901,-0.151969,-0.545760,0.168887,0.040719,0.018090,0.176328,0.278174,-0.021131,0.038260,0.582401,0.453239,0.009426,0.305231,0.903351,-0.211928,0.024610,-0.153418,0.182867,-0.392865,0.139000,0.321339,-0.309335,-0.323105,0.357865,0.083854,0.235225,0.303859,-0.084392,0.004436,-0.147740,0.461124,-0.165765,0.033166,0.339351,0.047496,0.199584,0.019435,0.239269,-0.245956,-0.201775,0.026736,0.102147,-0.099559,0.335486,-0.303525,0.070313,-0.616812,0.611873,-0.152292,0.196280,0.082792,-0.564371,-0.040824,0.423839,0.147698,0.274725,-0.082304,-0.053909,-0.357700,0.046611,0.880443,0.295531,0.134411,0.404684,0.075563,-0.490547,0.334996,0.133630,-0.503178,0.018831,0.203732,-0.087096,-0.131789,0.183306,-0.296803,-0.149339,-0.135303,-0.133416,0.067180,-0.435320,-0.039888,-0.686814,-0.176299,-0.311407,-0.622326,-0.045179,0.223713,-0.256310,0.342902,-0.907430,0.319083,0.654693,0.428184,-0.511989,0.595108,0.523630,-0.036395,-0.140944,0.091952,0.355369,-0.236740,0.118097,0.150838,0.371552,0.260538,0.134349,-0.451631,0.599973', '2230893', '1309172', '1308755', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294958', '桂河大桥', '剧情', '二战期间，日军占领了缅甸边境的一个战俘营。出于战略需要，日军将在缅甸与泰国交界修建一条大桥，同时希望战俘营里战俘出力，但英军战俘代表尼科森上校（亚利克·基尼斯 Alec Guinness 饰）认为这违反日内瓦公约拒不执行。于是尼科森等人被关了禁闭，但是没了尼科森的带领， 战俘们表现消极，而且因日本设计方面的不足，建桥工作陷入了停滞。日军无奈只好放出了尼科森等人，获释后尼科森感到在破坏一切的战争里何不做点建设，于是开始投入到建桥的工作。与此同时，逃出去的美军俘虏希尔兹（威廉•霍尔登 William Holden 饰）接受盟军一个特别任务，就是大桥建成之日将它炸毁。©豆瓣', '威廉·霍尔登', '大卫·里恩', 8.4, 23551, 'tt0050212', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233749387.jpg', 0.3, 0.9, 12.7, 50, 36.2, '0.429719,-0.026231,-0.845694,0.509208,0.238805,-0.236276,0.224055,-0.070757,-0.359472,-0.220453,0.164170,0.424001,0.170011,-0.276090,0.099619,0.013269,-0.680337,-0.695027,-0.143120,-0.291234,-0.406875,-0.674140,0.146697,-0.443720,-0.100948,-0.257154,0.671383,0.476619,-0.113621,0.270635,-0.101454,0.489542,0.149104,0.447610,0.130368,0.020257,0.290014,-0.753959,-0.212752,0.059317,-0.149110,-0.090721,-0.042245,0.146514,0.363360,0.627965,0.666715,-0.516418,0.011278,-0.196938,-0.149241,-0.403863,-0.002957,0.141611,0.165856,0.067430,-0.141429,0.215396,-0.564625,0.139196,0.029746,-0.275050,-0.495118,-0.258507,-0.148715,0.072177,-0.346266,0.433593,-0.126228,0.117811,-0.021840,-0.214397,0.119534,0.736622,0.170933,0.166005,0.081454,0.075855,-0.469372,-0.095177,0.706998,-0.448966,-0.210185,-0.029172,-0.277058,-0.400985,0.207865,-0.283267,-0.006358,-0.071606,0.219897,-0.337852,0.155187,0.172995,-0.617341,-0.076996,-0.578204,-0.438484,-0.127927,-0.152699,-0.130408,-0.597690,0.150066,0.113477,-0.128032,0.280182,-0.161667,0.054349,0.333861,-0.642651,-0.141605,0.414956,0.440115,-0.281390,0.356389,-0.043433,0.271379,-0.141533,0.067185,0.331305,0.060932,0.435345,0.342011,0.162339,-0.089303,-0.264517,-0.141332,0.179048', '26316956', '5157137', '4861402', '1296909');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294963', '一个都不能少', '剧情', '水泉小学唯一的老师高老师因为家中有事，不得不暂时请假回家。村长不得不从隔壁的村子找来了一个十三四岁的女孩魏敏芝来代替高老师上课。高老师觉得她年纪小，可是无奈找人不容易，只好嘱咐魏敏之每天给他们抄课文，准确点清人数，一个都不能少。原本30多个学生，因为家里负担不起，所以只剩下了26个。学生都觉得这个老师太年轻了，没有老师的样子便开始欺负她，整个教室都乱哄哄的。张慧科家境贫穷，母亲又病卧在床，所以他不得不到城里打工挣钱。魏敏芝得知情况后，呼吁同学一起凑钱去找他回来。魏敏芝到达城里后，历经辛苦，在好心人的帮助下才找到了张慧科，而且这些山区的孩子得到了社会的很大关注。©豆瓣', '魏敏芝', '张艺谋', 7.7, 128443, 'tt0209189', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p907410217.jpg', 0.3, 1.9, 28.1, 50.7, 18.9, '0.349359,-0.171139,-0.620025,0.282585,-0.514049,-0.440368,0.268948,0.071854,-0.327140,-0.458254,0.014131,0.422437,0.359906,0.705086,-0.156247,-0.232346,-0.233927,-0.137770,0.134601,-0.327611,-0.537229,-0.478540,0.149685,-0.183786,-0.299237,-0.130548,0.031047,-0.021895,-0.020622,0.418524,-0.052156,-0.077315,0.353832,0.248846,-0.327845,0.086125,0.014888,0.157400,0.055183,0.191863,0.318327,0.110263,-0.307029,-0.008982,0.639764,0.290468,0.494453,0.226653,-0.523173,0.194900,0.350150,-0.164631,-0.071111,0.096581,0.482634,0.008785,0.595014,-0.161085,-0.150349,0.108339,-0.236110,-0.097303,-0.256987,0.273316,0.229006,-0.099031,-0.613656,0.458502,0.009339,-0.292677,0.035180,-0.597731,0.087080,0.309111,-0.127686,0.496307,-0.190049,0.133644,-0.456792,0.186723,0.728314,-0.108562,-0.031175,0.279053,-0.121650,-0.238465,0.361398,-0.278059,-0.482931,0.333469,-0.021787,-0.188082,-0.406331,-0.127084,-0.154039,-0.016251,-0.043741,-0.287439,0.076764,-0.390946,-0.055489,-0.071547,0.121228,-0.017218,-0.188278,0.142190,0.163251,-0.175147,1.023130,-0.630970,0.239799,0.614564,0.494117,-0.613309,0.597170,-0.084013,0.257766,0.132876,0.091912,-0.317674,0.076229,0.790422,0.339705,0.172372,-0.093346,-0.690484,-0.450931,0.133303', '1307741', '1467748', '1298754', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294990', '勇敢者的游戏', '动作', '“尤曼吉”是一种类似于大富翁的棋类游戏，然而，和大富翁不同的是，“尤曼吉”的棋子能自动移动，当你走到其中一格时，这格描述的东西就会真实出现在你面前，而且游戏一经开始便不能结束，只有游戏结束才一切复原！12岁的阿伦（罗宾•威廉斯 Robin Williams 饰）和好友萨拉（邦尼•亨特 Bonnie Hunt 饰）才刚一开始玩“尤曼吉”，就被棋盘里面飞出来的蝙蝠吓得魂不附体，冲进了“尤曼吉”的神奇世界里，没能继续玩下去，以致两人就这样困在了另一个世界里。26年后，阿伦当年住的房子又搬进了两个小客人――朱迪（克尔斯滕•邓斯特 Kirsten Dunst 饰）和皮特（布雷德利•皮尔斯 Bradley Pierce 饰）姐弟两。他们在“尤吉曼”的战鼓声指引下找到了当年阿伦还没玩完的“尤吉曼”。在熟悉规则后，他们继续了当年阿伦还没结束的游戏……©豆瓣', '罗宾·威廉姆斯', '乔·庄斯顿', 8.2, 124196, 'tt0113497', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493837209.jpg', 0.1, 1, 17.9, 51.1, 29.9, '0.532314,0.189544,-0.900318,0.311574,-0.368105,-0.435226,0.669054,-0.043968,-0.358624,-0.043602,-0.026772,0.708376,-0.548840,0.254421,0.115061,0.289057,-0.455402,-0.727416,-0.201298,-0.330867,-0.527303,-0.521635,-0.272115,-0.257976,-0.162751,-0.115430,0.178909,-0.053585,-0.143209,0.237629,0.093005,-0.124546,-0.134593,0.433157,-0.311894,0.329440,-0.011074,0.035364,-0.168842,0.322429,0.204502,-0.048689,-0.240757,0.126851,0.309703,0.140984,0.587797,-0.492986,0.192597,0.113215,0.010795,0.049502,-0.254031,-0.071692,0.291663,-0.215277,0.401982,-0.056140,-0.264718,0.242895,0.079119,-0.134658,-0.549376,0.199594,-0.281752,0.195990,-0.521198,0.305226,-0.096157,-0.175035,0.108038,-0.334586,0.208355,0.274413,0.536968,0.344532,-0.130396,-0.258565,-0.604700,0.110845,0.542053,-0.067585,-0.509232,0.513288,0.211497,-0.381883,-0.331159,-0.001169,-0.190935,-0.110393,0.663425,0.168512,-0.129051,0.067345,-0.653346,0.156500,-0.197861,-0.175151,-0.029422,-0.335222,-0.197102,-0.400040,-0.045039,-0.252369,-0.289046,0.339324,0.044061,-0.142554,0.520865,-0.807692,0.339141,0.318859,0.000450,-0.157262,0.530945,0.021970,0.177018,-0.054432,0.229436,-0.177256,-0.040613,0.430557,0.557570,0.595709,0.096038,-0.173172,-0.379687,0.580580', '1292211', '1805685', '1481233', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1294991', '精武门', '剧情', '大侠霍元甲头七之日，日本虹口武道场翻译胡恩（魏平澳 饰）受铃木宽（桥本力 饰）委派，带人上精武馆挑衅。霍元甲五弟子陈真（李小龙 饰）不堪其辱，孤身赴武道场应战，大败数十人。铃木宽大怒，派人打砸精武馆，并限三天交出陈真。为保陈真性命，大师兄（田丰 饰）命令陈真离开上海。当夜，陈真意外发现师父被毒害的线索，盛怒之下手刃凶手（黄宗迅 饰）及其内应（韩英杰 饰），并决定挖出幕后主使……', '李小龙', '罗维', 8.5, 39570, 'tt0068767', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2043671205.jpg', 0.3, 1, 12.8, 44.1, 41.8, '-0.435905,0.106451,-0.012936,0.104064,0.176230,0.103320,-0.369507,0.371027,-0.593714,-0.713558,0.189109,0.328240,0.149233,-0.054549,-0.117748,-0.325682,-0.139698,-0.221459,-0.201152,-0.094416,0.052521,-0.374460,0.455633,-0.418199,0.148233,-0.161486,-0.115656,0.391679,-0.278805,0.613191,0.542946,0.254626,-0.320954,-0.035705,0.320069,0.072623,0.080393,-0.047859,-0.269145,0.073929,-0.710989,-0.484389,0.098670,0.173804,-0.050061,0.417647,0.179496,0.230240,-0.104296,-0.492702,-0.021183,-0.220026,-0.154536,0.313430,0.406772,0.010384,0.083495,0.515647,-0.161777,0.006165,0.216555,-0.138895,-0.233616,0.035386,0.428602,-0.180476,-0.237836,0.147101,-0.439114,0.215985,-0.303869,-0.215871,-0.190689,0.027111,0.196270,-0.470425,0.258047,0.022318,-0.171818,0.253829,0.423807,-0.543008,0.576427,-0.756485,0.636413,-0.342344,0.191997,-0.531229,0.218620,0.186155,0.544409,-0.435180,0.252562,-0.281869,0.107064,-0.401062,-0.491555,0.391345,-0.247084,0.287625,0.238495,-0.576206,0.345175,0.278241,-0.076200,0.196523,0.273245,0.034518,0.325060,0.038361,0.171278,-0.007832,0.323069,-0.383796,0.196186,-0.100047,-0.325861,-0.406505,-0.129890,0.150385,0.620020,0.211161,0.118865,-0.150280,-0.549794,-0.324228,-0.175819,-0.524051', '1461031', '1301946', '1666889', '1459054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295006', '窈窕奶爸', '剧情', '丹尼尔•希拉德（罗宾•威廉斯 饰）因与同事产生摩擦而辞掉了配音员的工作。家中可爱的孩子给了他十足的快乐，于是丹尼尔在儿子生日的时候，与孩子们疯狂的玩耍起来。当妻子米兰（莎莉•菲尔德 饰）达看到家中一片狼藉后十分生气。面对不争气的丈夫，米兰达决定与之离婚，因为没有工作，丹尼尔也失去了孩子的抚养权。丹尼尔对孩子们无比思念，突发奇想乔装成一名老太太——道特菲尔太太应聘成为妻子家中的佣人。不懂家务的丹尼尔闹出了不少的笑话，却无形中为米兰达减轻了负担，孩子们也开始依赖这名“老太太”，“道特菲尔太太”成为了他们家中的重要一员，丹尼尔也因此改变了不少。但面对米兰达的新男友的恋情，“道特菲尔太太”暗中捣乱。米兰达生日当天，丹尼尔需要以真实身份与“道特菲尔太太”的身份周旋与电视台主管与米兰达之间，使他狼狈不看。匆忙间会否被米兰达识破身份呢？©豆瓣', '罗宾·威廉姆斯', '克里斯·哥伦布', 7.8, 15170, 'tt0107614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2177818413.jpg', 0.2, 1.3, 25, 53.6, 19.8, '0.253286,-0.046389,-0.568506,0.557517,-0.241888,-0.621419,0.904351,0.240654,-0.512700,-0.410727,0.074905,0.955814,-0.094756,0.506018,0.288099,-0.092713,-0.327142,-0.660509,0.037192,0.041996,0.052652,-0.485210,0.118111,-0.179100,-0.295690,-0.314018,0.213713,-0.388995,0.090599,0.423128,0.290846,0.353541,0.258658,0.427175,-0.090512,0.142824,0.098186,-0.071305,-0.295528,-0.097024,0.326388,0.051385,-0.300317,0.245853,0.179760,0.420440,0.562701,-0.233815,-0.142371,-0.412662,0.406561,-0.165728,0.245802,0.258281,0.273559,0.066984,0.221692,0.156514,-0.190646,-0.057277,0.123405,0.139696,-0.551062,0.283107,0.259085,0.036751,-0.581390,0.149373,-0.286144,-0.277321,0.168876,-0.459832,0.168289,0.491704,-0.120316,0.382649,-0.213338,0.221052,-0.419618,-0.050804,0.624678,-0.065577,-0.031852,0.258924,-0.334338,-0.089098,0.264013,-0.360494,-0.781077,-0.090536,0.075165,0.062232,0.054239,0.356424,-0.274174,-0.200028,-0.232838,-0.271670,-0.043798,-0.611923,-0.016970,-0.488713,-0.233072,-0.330248,-0.443052,-0.220391,0.215236,-0.140234,0.831792,-0.805771,0.182529,0.373452,0.484829,-0.641726,0.452664,0.261424,0.471993,-0.391506,-0.098427,-0.166502,-0.161171,0.066809,0.304279,0.221349,-0.005484,-0.203709,-0.084576,0.383002', '4847665', '1292219', '4301215', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295025', '艾美的世界', '剧情', '小女孩艾美和母亲搬到一座新城市生活，但是陌生的环境没有能令她开口，依旧沉默安静地活在自己的世界里。然而一天，男邻居发现艾美可以用歌声与人交流，这是个十分惊喜的发现。为了走进艾美的世界，大家都开始大声地唱歌，然而艾美始终心病难除。直到一天明白艾美把父亲的死怪罪于自己。原来艾美的父亲是一个摇滚歌手，几年前在一次滂沱大雨的露天演出上，艾美上台送花，父亲被电死，艾美一直活在自责的世界里。大家明白了这个原因之后十分痛心，因为这并非是事实的真相。©豆瓣', '艾拉娜·德·罗玛', '纳迪娅·塔斯', 8.6, 5968, 'tt0118614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p676443493.jpg', 0.1, 1, 12.3, 43.7, 42.9, '0.083518,0.094811,-0.921459,0.456788,-0.310420,-0.150867,0.879187,-0.174631,-0.765594,-0.487046,-0.166395,0.675532,-0.378337,0.590516,0.317061,0.043575,-0.338411,-0.376744,-0.061052,-0.285368,-0.189601,-0.433204,-0.061768,-0.511364,-0.275439,-0.185364,0.523478,0.249004,-0.087203,0.199581,0.281413,0.177442,0.181817,0.554840,-0.085166,-0.069168,-0.024058,0.117496,-0.120530,0.371092,0.072036,-0.155114,-0.253618,0.384075,-0.155374,0.034522,0.620302,-0.295047,-0.432515,0.236165,0.305553,-0.315733,-0.252886,-0.089373,0.175036,-0.326790,0.188718,0.109776,-0.231041,-0.287711,0.202288,-0.043196,-0.292172,0.245779,-0.035077,0.247293,-0.336285,0.464291,-0.026360,-0.066951,-0.207350,-0.428331,0.607002,0.265222,0.555327,0.582690,-0.190804,0.165965,-0.341706,-0.130631,0.793493,0.002345,-0.213574,0.612692,-0.330842,-0.563572,0.075038,-0.102106,-0.682604,0.146958,-0.232107,0.230563,-0.240462,-0.030275,-0.530681,0.097724,-0.161804,-0.248444,-0.118499,-0.481970,-0.379771,-0.067780,-0.180013,-0.255567,-0.331903,0.116564,-0.317415,-0.378323,0.600957,-0.808295,0.378293,0.198744,0.205439,-0.261095,0.894367,0.200924,-0.019877,-0.311112,0.018085,0.471360,0.100144,-0.016044,0.028437,0.157365,-0.156195,0.037182,-0.708320,0.471724', '1302384', '1292211', '3055049', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295038', '哈利·波特与魔法石', '奇幻', '哈利波特是一个孤儿，从小寄养在姨妈家，受尽欺凌。但就在哈利11岁生日的时候，他意外收到了霍格沃茨学院的入学通知书。哈利从该学院派来接他的巨人海格口中得知，这是一间魔法学院，并得知了自己的身世，原来哈利的父母都是伟大的魔法师，在对付伏地魔的战斗中双双献身，唯有哈利幸免于难。哈利进入霍格沃茨后，表现出了超乎想象的飞行天赋，得到麦格教授的推荐进入了格兰芬多的魁地奇球队。另一方面，哈利发现霍格沃茨学院内有一股黑暗势力似乎在暗暗滋长，揭开谜团的关键就在有凶恶的三头犬守护的房间内。哈利、罗恩和赫敏三个好朋友决定探个究竟。©豆瓣', '丹尼尔·雷德克里夫', '克里斯·哥伦布', 9.2, 1084783, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2614949805.jpg', 0.1, 0.3, 5.8, 29.3, 64.5, '0.488508,-0.202757,-0.465367,0.506905,0.107756,-0.290821,0.501524,-0.022538,-0.367417,-0.420447,0.247232,0.812432,-0.203732,0.706550,0.230720,-0.039757,-0.150169,-0.271157,0.166130,-0.426625,-0.310029,-0.482343,-0.272979,-0.435372,0.117563,-0.696209,0.539856,0.023126,-0.248499,0.156989,0.236961,0.320492,-0.023095,0.348384,-0.125137,0.029915,0.387219,0.232807,0.032505,0.303519,0.052739,0.139604,-0.282368,0.232740,0.361268,0.263218,0.483504,-0.343118,-0.116688,0.085691,0.479649,-0.155151,-0.202164,0.180088,0.590517,-0.029385,-0.070866,0.174190,0.111582,0.199312,-0.260977,-0.078166,-0.483783,-0.078235,0.316554,0.082099,-0.645662,0.567882,0.123166,-0.075983,0.497219,-0.354315,-0.123704,0.364425,-0.206834,0.417703,-0.147301,0.062706,-0.490305,-0.122892,0.471455,-0.446937,-0.383801,-0.114401,-0.357528,-0.606791,0.189715,-0.041262,-0.373466,-0.084238,0.234308,0.235843,-0.084166,0.349721,-0.519602,-0.338254,-0.438168,-0.147435,0.148685,-0.499427,-0.232831,-0.553771,-0.091966,-0.001239,-0.275771,-0.080722,-0.034624,-0.474374,0.648502,-0.782842,0.301088,0.484516,0.174442,-0.066406,0.696833,-0.218949,0.292124,-0.114922,-0.184549,0.431941,0.289027,0.341963,-0.266760,0.402691,0.365326,-0.204300,-0.444475,0.589402', '1870681', '1308609', '1292720', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295045', '天才瑞普利', '剧情', '年轻有钱又置身于意大利的艳阳下，这是汤姆·瑞普利（马特·达蒙 Matt Damon 饰）所渴望的生活，却是迪基·格林利（裘德·洛 Jude Law 饰）早已拥有的东西。瑞普利是个出身平凡，生活也毫无值得炫耀的年轻人，他受到一个富商之托，到意大利去游说他号荡不羁的儿子迪 基，重回他的家乡美国。但是当瑞普利一到那里，就深深地被迪基的生活形态所迷惑：美丽的别墅、高级浮华的度假饭店、一掷千金的奢靡生活，以及他美丽温柔的女友，都令他羡慕不已。由于瑞普利一心觊觎迪基的生活，最后这样的欲望竟扩张成想要将迪基取而代之，他缜密的心思不仅令人咋舌，而冷静的犯罪手法更教人措手不及。就在他陶醉于亲手打造的美梦中时，瑞普利因为一次意外的巧合害他露出了马脚，于是引起警方的注意并展开调查……本片改编自女作家派翠西亚·海史密斯写于1955年的同名小说，法国导演雷内·克莱芒曾于1960年拍摄过一部以该小说为蓝本的电影《太阳背面》，由法国影星阿兰·德隆主演。', '马特·达蒙', '安东尼·明格拉', 8.2, 147258, 'tt0134119', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1915065575.jpg', 0.2, 1.1, 15.6, 52, 31, '0.174711,-0.032729,-0.608592,0.642474,0.123987,-0.389922,0.595614,0.156537,-0.285506,-0.471675,-0.035048,0.693008,-0.153302,0.251937,0.348672,0.211432,-0.374864,-0.517396,-0.099894,-0.157134,0.104016,-0.298294,-0.366392,-0.289624,0.054419,-0.301922,0.505417,0.259546,-0.109852,0.337112,0.266444,0.492424,0.108081,0.280806,-0.047956,0.013256,-0.009717,0.013285,-0.314303,0.057872,-0.047643,-0.299473,-0.197535,0.366624,0.127235,0.251062,0.607024,-0.226646,-0.099830,-0.094072,0.381643,-0.028810,0.105723,-0.066306,0.053457,-0.170421,-0.074313,0.059355,-0.207224,0.115025,0.185865,-0.221357,-0.959350,0.045839,0.148926,-0.003761,-0.259029,0.428914,-0.005222,0.022445,-0.168612,-0.159950,0.031507,-0.043072,0.218364,0.274186,-0.004691,0.244982,-0.270167,0.338461,0.503636,0.207298,-0.272783,0.444225,-0.518700,-0.283294,0.048689,-0.407042,-0.598568,0.079391,0.206929,-0.091907,0.097497,0.377166,-0.460907,-0.084528,-0.485491,-0.080664,-0.042208,-0.154047,-0.182530,-0.661019,-0.094439,-0.383399,-0.219819,-0.180969,0.019896,-0.340813,0.449189,-0.658176,0.256354,0.557196,0.030245,-0.498117,0.594279,-0.090347,-0.166831,-0.085419,-0.338748,0.568217,0.159739,-0.084881,-0.094256,0.127028,0.020224,-0.169285,-0.144231,0.600205', '1793491', '25928048', '3769423', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295064', '城市猎人', '喜剧', '私家侦探孟波（成龙）与死去搭档的妹妹惠香（王祖贤）刚同报业大王今村商讨完寻找其失踪女儿清子（后藤久美子）下落的办法，就见清子与若干滑板少年在街道上左穿右插，一番穷追后，清子消失。惠香本想到孟波家后为孟波举办生日舞会，不想推门发现早已有七个美女正望穿秋水，一怒之下，惠香扬言会与表哥大脚板（单立文）在赌船“富贵号”上预支蜜月。孟波赶到码头欲向惠香解释，不想左找右找不见其踪影，此时“富贵号”启航在即，孟波混在鱼贯涌至的游客中上了船，清子以及装扮成性感女郎的香港警察芽子（邱淑贞）也在这条船上。三个女人一台戏，何况又加一个好斗、好色的孟波。©豆瓣', '成龙', '王晶', 7.7, 105818, 'tt0103950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557560791.jpg', 0.4, 2.8, 28.4, 46.3, 22.1, '0.007883,-0.079776,-0.353592,0.133361,0.178443,-0.480228,0.582017,0.227960,-0.220812,-0.098597,0.231313,0.383284,-0.180235,0.294043,0.297751,-0.010578,-0.369370,-0.561388,0.049648,-0.037183,-0.349278,-0.257815,0.172167,-0.111149,-0.123644,-0.149035,0.363411,-0.235875,0.076886,0.601226,0.555636,0.022259,-0.395847,0.294791,-0.372784,0.317116,-0.001121,0.125303,-0.346241,0.360545,-0.217525,-0.053703,-0.235211,-0.282979,-0.000030,0.354115,0.708626,0.039180,0.060569,-0.164430,-0.055998,0.143432,-0.110967,0.072855,0.462379,0.045229,0.088676,-0.025641,-0.366853,-0.162940,0.061689,0.236470,-0.016480,0.183949,-0.135021,0.145641,-0.348086,0.196877,-0.211410,-0.237006,0.025199,-0.561339,0.115054,0.128153,-0.071252,0.049930,0.024489,0.338868,-0.454354,0.134394,0.555241,0.396871,0.220520,0.364030,0.641566,-0.299811,0.068634,-0.103343,-0.132389,-0.144569,0.396812,-0.104476,-0.202656,-0.258630,-0.304948,-0.023320,-0.261932,-0.022975,0.144824,-0.038935,-0.154146,-0.576964,0.104334,-0.028159,-0.084053,0.307110,0.176958,-0.153254,0.328984,-0.644000,0.116976,0.150837,0.225778,-0.466375,0.726791,0.023164,0.051685,-0.140505,-0.181848,-0.053671,0.178841,0.399320,0.135722,0.237143,-0.314642,-0.408208,-0.472724,-0.146233', '1291992', '26687241', '2080130', '2976123');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295078', '偷听女人心', '喜剧', '尼克（梅尔·吉布森 Mel Gibson 饰）是芝加哥一间广告公司的小经理，是个典型的大男子主义者。对于新来的女人上司达西（海伦·亨特 Helen Hunt 饰），他更是满腹牢骚。达西要求尼克设计出女性用品的创意广告，令达西分外头痛，一不留神，尼克在自家浴室中触了电，这次事故让他获得了一个神奇的本领——读心术。有了这个意外的收获，尼克现在就能轻而易举的知道身边女人们的心事。他渐渐的沉迷于此，并惊奇地发现原来达西一直都对自己有好感。于是，尼克决定将计就计，利用达西的心事好好捉弄她一番，他千方百计接近达西，讨她欢心，却不知自己正在堕入情网。自从得知女人的内心世界，这个大男人终于领悟到她们的美丽，和水火不容的女上司共赴爱海。©豆瓣', '梅尔·吉布森', '南希·迈耶斯', 7.1, 36306, 'tt0207201', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2184916871.jpg', 0.4, 3.4, 47.9, 39.3, 9, '0.277119,0.159348,-0.786073,0.479883,-0.415703,-0.356523,0.763794,-0.033207,-0.615470,-0.310415,0.199298,0.753356,-0.428355,0.390368,0.334740,0.270908,-0.404960,-0.644137,0.151863,-0.141592,-0.094057,-0.616413,-0.511211,-0.342448,0.038052,-0.084177,0.156744,0.068573,-0.191513,0.241903,0.470025,0.298350,0.360218,0.662579,-0.022465,0.119132,0.168354,-0.083797,0.155189,-0.072091,0.124381,-0.054704,-0.292207,0.166800,0.039560,0.375678,0.433538,-0.236540,-0.258492,-0.052714,0.419188,0.016698,0.121456,0.067423,0.026597,-0.294811,0.098815,-0.041017,-0.240578,-0.071091,0.254775,0.092595,-0.690301,0.029067,-0.088111,-0.018159,-0.332255,0.051169,-0.017274,0.021745,0.011507,-0.477761,-0.228930,0.065095,0.432500,0.288388,-0.214947,0.222395,-0.410793,-0.161058,0.326742,0.242658,-0.128176,0.459009,-0.331597,-0.414613,0.086475,-0.110405,-0.328957,-0.114044,0.551025,0.116800,-0.012917,0.226558,-0.424796,-0.089717,-0.322584,0.054320,-0.179664,-0.445318,-0.047459,-0.452172,-0.238583,-0.337365,-0.386422,-0.165927,-0.018879,-0.309478,0.654147,-0.786941,0.171521,0.850709,0.026544,-0.605183,0.671098,0.366340,-0.077476,-0.256134,-0.431737,0.299479,-0.154263,0.055930,-0.040936,0.544850,0.222423,-0.284584,-0.277588,0.473966', '1947080', '3785918', '1309172', '1509868');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295086', '沉睡者', '剧情', '纽约街头，四名顽皮少年策划着一场好戏捉弄一下街边卖热狗的小贩以打发午后无聊的时光。不料玩笑开大了，他们误伤了路人，被判进入男童院监禁数月。在男童院里，每到半夜，他们都会被狱卒们叫出去，被殴打、鸡奸。当他们重获自由后，四个伙伴决定将这段屈辱永埋心底。多年后，其中两个 伙伴迈克尔（布拉德·皮特 Brad Pitt 饰）成了副检察官，洛伦左（杰森•帕特里克 Jason Patric 饰）成了记者，然而另外两个约翰（朗·埃达德 Ron Eldard 饰）和汤米（比利·克鲁德普 Billy Crudup 饰）却无法走出当年阴影，成了黑帮分子。当约翰和汤米在餐厅碰到当年鸡奸他们的狱卒之一肖恩（凯文·贝肯 Kevin Bacon 饰）时，毫不犹豫射杀了他。为了帮助伙伴，迈克尔想出了一个周全的计划：他们请来著名的糊涂律师为他们作辩护，而迈克尔为肖恩担任控方，努力要将官司打输；洛伦左则通过手段将肖恩卑劣的人品揭露……', '凯文·贝肯', '巴瑞·莱文森', 7.8, 10755, 'tt0117665', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2376962179.jpg', 0.2, 2.2, 25.7, 51.8, 20.1, '0.224631,0.081833,-0.308410,0.287785,-0.273402,-0.456021,0.782859,0.180537,-0.448505,-0.205915,0.163708,0.674801,-0.341581,0.355535,0.529560,0.054361,-0.503523,-0.735645,-0.131561,-0.154090,-0.193403,-0.589203,-0.136431,-0.485778,-0.205265,-0.270515,0.139627,-0.047487,0.088464,0.294227,0.476072,0.429191,-0.088398,0.059817,-0.018824,0.232612,0.378494,-0.463650,-0.382518,0.081838,-0.096276,-0.270535,-0.290143,0.042403,0.030006,0.281239,0.691014,-0.136692,0.029919,-0.309655,0.116916,-0.285212,0.106154,0.251516,0.229792,-0.008567,0.266175,0.236290,-0.134186,0.120474,0.202707,-0.058085,-0.488283,0.380446,-0.174768,-0.143900,-0.622537,0.264110,-0.076744,0.112568,0.110164,-0.351571,0.019684,0.118285,0.261658,0.246492,0.019476,-0.080432,-0.617593,0.066149,0.685686,-0.045955,-0.097230,0.110329,0.070788,-0.099032,0.105020,-0.256817,-0.144110,-0.073348,0.665679,-0.128968,-0.116065,0.032060,-0.363970,-0.204224,-0.386662,-0.017303,-0.076496,-0.340131,-0.137813,-0.630683,0.011744,0.061943,-0.325499,0.157681,-0.132417,-0.038546,0.470848,-0.545791,0.190758,0.531991,0.180486,-0.477476,0.643646,0.080077,0.329256,0.028095,0.112126,-0.073384,0.276896,0.334385,0.510404,0.406161,-0.205148,-0.174427,-0.124184,0.185487', '1301686', '3326747', '3147969', '1301345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295106', '鼠胆龙威', '喜剧', '爆破专家李杰（李连杰 饰）一次因执行任务判断失误，亲眼目睹妻儿被活活炸死，伤心欲绝辞去公职，一面寻找杀死妻儿的凶手，一面化名大胆，为天皇巨星龙威（张学友 饰）出任保镖及替身，不时为他演出亡命的镜头。除了记得凶手的声音之外，并无其它线索。电视台主持人乐慧贞（邱淑贞 饰）对龙威的表演有所怀疑，因此不惜日夜跟从。龙威受邀参加一个大型珠宝展览会，自称医生（王霄 饰）的匪徒正策划盗取展览会钻饰，并派助手朱菲（周嘉玲 饰）混入酒店当公关作卧底。钻饰展览当日，李杰护送龙威到场后就离开，回家途中偶然在车上认出了医生的声音，于是拼命返回狂追匪徒，演绎了一场生死混战……©豆瓣', '李连杰', '王晶', 7.4, 44655, 'tt0114437', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2241046568.jpg', 0.4, 2.6, 38, 44.7, 14.3, '-0.392575,-0.205886,-0.380959,0.334818,-0.081894,0.126164,0.370965,0.030144,-0.407245,-0.555492,0.486654,0.601044,-0.237762,0.041444,0.332627,-0.317587,-0.225353,-0.600213,-0.124544,0.055484,-0.164038,-0.277773,0.086194,-0.250746,0.095080,-0.221601,0.427523,0.078853,-0.319684,0.767671,0.482171,0.024997,-0.541516,0.188807,0.040433,-0.391739,0.298749,0.052514,-0.442023,0.239647,-0.234134,-0.361236,0.031808,-0.100625,-0.071310,0.427917,0.531725,-0.129844,0.072878,-0.125903,0.225513,-0.257527,0.247757,-0.013580,0.207790,0.222060,0.266566,0.171427,-0.145844,-0.051614,0.067785,0.004895,-0.687973,0.159837,0.170116,0.125297,-0.311838,0.066294,-0.404484,0.276269,0.047430,-0.067952,0.267206,0.022785,0.255728,0.109422,-0.008237,0.154423,-0.288676,0.416287,0.456652,-0.152192,0.319572,0.143895,0.325534,-0.297623,0.344048,-0.078398,0.080830,0.305500,0.275917,-0.035126,0.167587,-0.413579,-0.204894,-0.230501,-0.343437,-0.132001,0.023198,-0.162472,-0.115217,-1.008323,0.257649,0.456792,0.080021,-0.109257,0.128685,-0.047116,0.235279,-0.485468,0.137383,0.432632,0.224007,-0.689251,0.406048,-0.003358,0.037230,-0.273018,-0.103118,-0.017181,0.421372,0.297445,-0.179080,-0.055670,-0.063988,-0.548815,-0.225015,-0.351406', '2369613', '25723905', '24751811', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295116', '西线无战事', '剧情', '第一次世界大战期间，德国政府以漂亮的口号呼吁年轻热情的学生志愿者投身战场保家卫国。一腔热血的德国青年保罗·鲍曼（卢·艾尔斯 Lew Ayres饰）怀着英雄理想投身到一战之中。然而当保罗和他的同学们经过训练后，被派往西线参战时，他们目睹到的却是残酷的饥饿、血腥和死亡。战争的荒谬无情让保罗从迷恋战争到心灰意冷，因伤返乡。可是愚昧的乡民根本不知前线的危急，保罗义愤填膺地向学生陈述战争的无情，西线无战事。他提前结束休假返回前线，在战壕中伸手捕捉一支蝴蝶时，不幸被流弹击中。由好莱坞著名导演刘易斯·迈尔斯通执导的经典反战题材影片《西线无战事》，改编自德国作家雷马克的同名小说。这部堪称电影史上“最伟大的反战电影”之一的影片，一举荣获1930年第3届奥斯卡金像奖最佳影片、最佳导演和最佳编剧提名。导演用简明精练的镜头再现了惨绝人寰的战争实况，也以细腻流畅的手法写活了保罗爱国迷梦的幻灭。影片结尾处保罗捉蝴蝶被子弹击中的镜头，已成为电影史上的经典瞬间。', '路易斯·沃海姆', '刘易斯·迈尔斯通', 8.8, 18627, 'tt0020629', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209784767.jpg', 0.2, 0.6, 8.7, 38.3, 52.3, '0.156469,0.023024,-0.702114,0.659229,0.397823,-0.224895,0.574916,-0.115096,-0.187084,0.104067,0.387652,0.683757,-0.268739,-0.115988,0.507852,-0.153640,-0.246345,-0.874248,-0.390956,0.159629,-0.143563,-0.207159,-0.461534,-0.055082,-0.136161,-0.337837,0.866386,0.299303,-0.490252,0.465723,0.369003,0.366496,0.229473,0.244796,0.144583,0.069277,0.052478,-0.190691,-0.451637,0.253804,-0.052891,-0.364224,-0.362750,0.087248,-0.332161,0.286560,0.656989,-0.376036,0.203467,0.013595,0.802810,-0.386141,-0.170863,0.086210,0.209895,0.222889,0.061452,-0.015761,0.192447,0.274461,-0.272068,-0.290717,-0.770522,0.043273,-0.150252,0.123093,-0.396875,0.521625,-0.157890,0.211514,0.213383,-0.136946,0.129060,0.037578,0.266445,0.261492,-0.040115,0.110228,-0.061096,0.704897,0.566538,-0.043116,-0.648963,0.138866,-0.089830,-0.467116,0.128256,-0.621736,-0.320028,0.185212,0.453948,-0.245023,0.023125,0.257567,-0.466735,0.007842,-0.195394,-0.355024,-0.132892,-0.025782,-0.182278,-0.767643,-0.079444,-0.212062,-0.209495,-0.145319,0.060651,-0.036899,0.980777,-0.448685,0.060227,0.475789,-0.059142,-0.046623,0.711080,0.094480,0.042916,-0.004904,-0.153580,0.437608,0.101649,0.326012,0.139613,0.339073,-0.177472,-0.263044,-0.296104,0.439678', '27602116', '22265121', '26647163', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295120', '风语者', '动作', '这是一部以二战中的太平洋战争为背景题材的影片。风中的语言，在战争中，指的是传递着无数秘密的电波。每个风语者都背负着高级军事机密。本·亚齐(亚当·比奇 Adam Beach 饰)就是这样一个风语者。海军陆战队员乔·恩德斯(尼古拉斯·凯奇 Nicolas Cage 饰) 奉命去保护本·亚齐和电波中的秘密。在举足轻重的塞班岛战役中，乔·恩德斯将会如何保护自己的战友和国家机密？他将面临怎样的抉择？这部影片，或许能给我们带来一些关于战争的思考。©豆瓣', '尼古拉斯·凯奇', '吴宇森', 7.7, 78778, 'tt0245562', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p792496425.jpg', 0.4, 2.8, 28.4, 50.4, 17.9, '0.281730,0.128696,-0.638054,1.161797,0.132148,0.175055,0.441718,-0.244126,-0.285049,-0.513792,0.259469,1.026890,0.107005,0.023851,0.148263,-0.094097,-0.394237,-0.792220,-0.194513,-0.148867,-0.562602,-0.540900,-0.664830,-0.229592,0.005886,-0.220091,0.626371,0.282162,-0.541678,0.124792,0.201363,0.531011,-0.153216,0.242986,-0.031658,-0.130293,-0.132853,-0.231008,-0.364566,0.214954,0.142767,-0.256311,-0.030633,0.376950,0.017646,0.312626,0.496787,-0.887035,0.214740,-0.074235,0.337182,-0.364740,0.116250,0.089763,-0.032457,0.111602,0.163580,0.311789,-0.407462,0.304518,-0.114668,-0.199501,-1.195098,-0.586275,0.091681,0.424824,-0.500792,0.150212,-0.193123,-0.027171,0.358509,0.026779,0.298336,0.583558,0.330776,0.420802,-0.325051,-0.041971,-0.484656,0.119017,0.555606,-0.037864,-0.213970,-0.019302,-0.258220,-0.396960,-0.066889,-0.182902,-0.482383,0.039608,0.178688,-0.155105,0.238034,0.366216,-0.718036,0.007671,-0.031295,-0.414319,-0.152080,-0.413847,-0.066186,-0.814167,-0.255078,-0.667444,-0.123914,0.092854,0.315303,-0.267139,0.877984,-0.623481,0.011926,0.366010,0.081580,-0.512145,0.536601,0.338586,0.314189,-0.020359,-0.115396,0.328921,0.244613,0.014610,-0.058647,-0.020513,0.227010,-0.170547,-0.226782,0.487143', '27602116', '1308585', '30163500', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295124', '辛德勒的名单', '剧情', '1939年，波兰在纳粹德国的统治下，党卫军对犹太人进行了隔离统治。德国商人奥斯卡·辛德勒（连姆·尼森 Liam Neeson 饰）来到德军统治下的克拉科夫，开设了一间搪瓷厂，生产军需用品。凭着出众的社交能力和大量的金钱，辛德勒和德军建立了良好的关系，他的工厂雇用犹太人工作，大发战争财。1943年，克拉科夫的犹太人遭到了惨绝人寰的大屠杀，辛德勒目睹这一切，受到了极大的震撼，他贿赂军官，让自己的工厂成为集中营的附属劳役营，在那些疯狂屠杀的日子里，他的工厂也成为了犹太人的避难所。1944年，德国战败前夕，屠杀犹太人的行动越发疯狂，辛德勒向德军军官开出了1200人的名单，倾家荡产买下了这些犹太人的生命。在那些暗无天日的岁月里，拯救一个人，就是拯救全世界。©豆瓣', '连姆·尼森', '史蒂文·斯皮尔伯格', 9.6, 1035505, 'tt0108052', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p492406163.jpg', 0.1, 0.1, 2, 17.5, 80.3, '0.198992,-0.012663,-0.661450,0.352840,-0.052221,-0.133337,0.726707,-0.200028,-0.642820,0.005588,0.393213,0.762463,0.058723,0.069468,0.216072,-0.103647,-0.440025,-0.712697,-0.529529,-0.191541,-0.372589,-0.323022,-0.388158,-0.488370,-0.160851,-0.424277,0.793652,0.296939,-0.200387,0.160551,0.065309,0.358008,0.393046,0.269855,-0.318749,0.171081,0.261377,-0.348381,-0.333847,0.194634,-0.410204,-0.442294,-0.221473,0.058033,-0.007037,0.449105,0.547861,-0.350926,0.112135,-0.348183,0.418851,-0.536585,-0.294808,0.333153,0.247374,0.152518,-0.092929,0.323750,-0.400109,0.085310,0.022686,-0.255129,-0.824171,-0.353001,0.048911,-0.009317,-0.625799,0.781976,-0.051026,0.331208,-0.014651,-0.077240,0.130366,0.526403,0.004417,0.533625,-0.110256,0.015297,-0.680496,0.543381,0.798991,-0.394052,-0.376009,0.021243,-0.441422,-0.451027,0.073961,-0.534388,-0.378751,-0.229122,0.273419,-0.403492,0.039403,0.519129,-1.133371,0.077658,-0.262185,-0.774982,0.021342,-0.165158,-0.168801,-0.857959,-0.432862,-0.366880,-0.226448,0.297407,0.232751,-0.037942,0.957654,-0.651735,0.065861,0.559209,0.618792,-0.534973,0.518068,-0.205034,0.231350,0.110768,-0.037034,0.496443,0.235733,0.588053,-0.014562,0.228972,-0.094031,-0.249443,-0.061839,0.509439', '26290398', '6982558', '1849026', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295148', '小鹿斑比', '剧情', '这是一个关于成长的故事。小鹿斑比来到了这个世界上，和其他好朋友一起无忧无虑生活在森林里。一天，他见到了鹿群的领袖，妈妈这时才告诉他，这就是他的父亲。鹿妈妈不久就牺牲在猎人的枪下，斑比只能和父亲相依为命了。转眼间，斑比长大了。到了恋爱的季节，他为了争夺一头母鹿的爱而和另一头公鹿进行了决斗，他大获全胜；秋天来临，森林燃起了大火，在父亲的鼓励下，斑比勇敢地跃入了瀑布；春天又得到了，斑比真的长大了，成了鹿群的新领袖。©豆瓣', '哈迪·奥尔布赖特', '戴维·汉德', 8.6, 33162, 'tt0034492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2261878972.jpg', 0.1, 0.5, 12.5, 45.3, 41.5, '0.208366,0.054244,-0.764011,0.514845,-0.209818,-0.470781,0.717907,0.098452,-0.192904,0.187989,0.190387,0.837121,-0.066009,0.617404,0.130488,0.116652,-0.450976,-0.755924,-0.099704,-0.237732,-0.434273,-0.208011,-0.281091,-0.101078,0.137272,-0.103528,0.746448,0.131331,-0.005200,0.581940,0.125768,-0.051257,0.149145,0.435881,-0.550367,0.391044,0.034071,0.338215,-0.313368,0.352382,0.038341,-0.151917,-0.066417,0.107084,0.071534,0.077811,0.671298,-0.496132,-0.204759,-0.207954,0.259160,-0.426979,0.124467,0.036656,0.561518,-0.121163,0.207814,0.118664,-0.050412,-0.061562,-0.374109,-0.289587,-0.397867,0.071935,-0.246976,0.138517,-0.880843,0.465840,0.210380,-0.132471,0.403708,-0.447308,0.310379,0.459746,0.072911,0.628316,-0.419126,0.056432,-0.517004,0.217790,0.963780,-0.158629,0.013265,0.336162,-0.051992,-0.479351,0.087008,-0.048052,-0.333071,-0.192249,0.509813,-0.035286,-0.607959,0.267352,-0.823960,0.182082,-0.131729,-0.374878,-0.013470,-0.501843,-0.310186,-0.008198,-0.064188,-0.438702,-0.450346,0.228709,-0.076022,-0.425906,0.857226,-1.070527,0.527900,0.536460,0.381492,-0.303876,0.579127,-0.071970,0.175922,-0.249337,0.467618,0.314971,-0.198505,0.529294,0.380032,0.276621,-0.016942,0.055935,-0.867061,0.664657', '1292219', '1926007', '1850797', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295157', '神偷谍影', '剧情', '香港高科技商业间谍组织ATM的Jackal（金城武）、Cash（陈小春）、Titan（王合喜）以及他们从未谋过面的秘密首脑Sam（杨采妮）同时受到香港警局情报室主任Stanley（方中信）的邀请，原来Stanley以四人过往犯案的证据及冻结四人账户作要挟，要他们为警方偷取英镑伪钞电模版。四人找来聋哑怪人也是电子高手Phoenix（李绮虹），五人合力取得电模版后，按约定地点和Stanley交易，却不料只等来炸弹一枚， Phoenix被当场炸死，原来要挟他们的Stanley早已辞职，此时他们已被香港警局情报室及政府通缉。为了洗脱罪名，四人决意找回Stanley。©豆瓣', '金城武', '陈德森', 6.8, 10176, 'tt0156998', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1645210761.jpg', 0.8, 5.5, 52.7, 32.5, 8.5, '-0.057337,-0.079066,-0.537459,0.371176,-0.082760,0.036283,0.133513,0.023532,-0.471856,-0.186679,0.098794,0.592362,-0.008509,-0.064373,0.111526,-0.119221,-0.382642,-0.792432,-0.134642,-0.511263,-0.135987,-0.620094,-0.188450,-0.301844,0.033069,-0.003448,0.461583,-0.070802,-0.288672,0.254988,0.399009,0.323995,-0.596780,0.384169,0.034996,-0.108150,0.306881,-0.099824,-0.515053,0.297189,-0.104145,-0.377868,0.068164,0.191740,-0.052155,0.580882,0.367637,0.157727,-0.083896,-0.359197,0.023531,-0.417215,-0.021299,-0.160742,0.538742,0.085113,0.510865,0.413922,-0.310406,0.103077,0.331687,-0.006174,-0.934992,-0.094992,0.259905,-0.118957,-0.166862,0.048898,-0.565841,0.445218,-0.205865,-0.092223,0.362407,0.409010,0.322656,-0.028576,-0.067431,-0.107050,-0.475059,0.358818,0.399707,-0.275378,0.189167,-0.128431,0.183727,-0.425840,-0.008868,-0.077232,0.185714,0.186973,0.418313,0.147578,-0.106214,-0.009281,-0.402774,-0.431219,-0.361810,-0.017353,0.123337,-0.391968,0.104364,-0.887503,-0.189145,0.228470,-0.146361,0.241855,0.368387,0.147663,0.319288,-0.409008,-0.088515,0.391873,0.324402,-0.629986,0.279919,-0.121707,-0.003803,-0.324460,-0.090459,-0.456795,0.730942,0.610937,0.343268,-0.254892,0.082379,-0.301378,-0.149720,-0.252085', '1865012', '27126336', '26996640', '2363876');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295187', '谜中谜', '喜剧', '美国少妇瑞姬•蓝伯特（奥黛丽•赫本饰）在法国梅杰夫滑雪场偶遇一位自称皮特•乔舒亚（加里•格兰特 Gary Grant 饰）的男子。瑞姬返回巴黎，发现家中被洗劫一空，丈夫查尔斯遇害。瑞姬被美国使馆传召，结识了CIA特工汉密尔顿（华特•马修 Walter Matthau 饰），才发现原来查尔斯葬礼上出现的三名怪客是他二战时贪污黄金的同伴：泰克斯（詹姆士•柯本 James Coburn 饰），赫尔曼（乔治•肯尼迪 George Kennedy 饰）和利奥波德（奈德•格拉斯 Ned Glass 饰）。汉密尔顿要求瑞姬帮助政府寻找失踪的黄金，而三名怪客也对瑞姬紧追不放。危急时皮特突然现身救美。正当瑞姬陷入情网之际，三怪客纷纷遇害，矛头指向身份变幻莫测的皮特，瑞姬也陷入空前危机。加里•格兰特与奥黛丽•赫本因此片分获金球奖最佳男女主角提名。奥黛丽•赫本获英国电影电视艺术学院奖最佳女主角。', '加里·格兰特', '斯坦利·多南', 7.9, 11093, 'tt0056923', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1116200272.jpg', 0.3, 1.6, 23.4, 51.5, 23.2, '0.258169,-0.093781,-0.437577,0.234471,0.373462,-0.477825,0.790474,0.055899,-0.369696,-0.551558,0.421611,0.988157,-0.436448,0.207294,0.709498,0.248699,-0.549479,-0.630912,0.000356,0.088380,-0.079860,-0.445118,-0.291698,-0.209506,-0.036610,-0.431060,0.450822,-0.141711,-0.133705,0.606689,0.509046,0.607565,-0.153205,0.171455,0.200008,0.153233,0.632445,-0.409541,-0.263256,0.455342,-0.305383,-0.210243,-0.220777,0.107682,0.007905,0.256804,0.488800,-0.161220,0.209289,-0.026797,0.395778,-0.180699,0.065959,0.058035,0.388438,-0.364201,0.054442,0.052575,-0.081755,0.030484,0.214190,-0.014038,-0.093505,0.491324,-0.022879,0.357808,-0.229010,0.138102,-0.435598,0.088226,0.078264,-0.011444,0.001840,0.304671,0.269921,-0.205947,0.139332,-0.086889,-0.332168,0.179545,0.221965,-0.081854,-0.046051,0.017991,0.021996,-0.527379,-0.042928,-0.078863,-0.196616,-0.104656,0.670260,-0.042326,0.293238,0.197191,-0.233196,-0.324759,-0.545858,-0.016190,-0.224871,0.044110,-0.058432,-0.930119,-0.120693,-0.093281,-0.149525,-0.056949,0.007709,0.097485,0.405093,-0.273539,0.350886,0.235517,0.114991,-0.143871,0.530042,-0.126545,0.148221,-0.388261,-0.195560,0.513639,0.298566,-0.280282,-0.186204,0.032429,0.078748,-0.303889,-0.004954,0.161923', '2075345', '6517421', '1298616', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295204', '异种2', '动作', '未来某天，议员之子帕特里克·罗斯（贾斯汀·拉扎德 Justin Lazard 饰）乘坐远足号登陆火星，成为第一个踏足这个星球的地球人。一如当年的阿姆斯特朗，帕特里克成为全人类的英雄。然而始料未及的是，帕特里克将一种致命的DNA带回地球。人类开始面临新的灾难。另一方面，由于塞尔曾给地球带来莫大的灾难，军方以及科学家们利用赛尔的基因制作了复制品夏娃（娜塔莎·亨斯特里奇 Natasha Henstridge 饰），旨在通过各种实验找到外星生命体的弱点所在。新的异种降临地球，夏娃体内沉睡已久的基因开始苏醒。冥冥中，帕特里克和夏娃都感到来自对方体内原始欲望的野性呼唤……©豆瓣', '迈克尔·马德森', '彼得·梅达克', 6, 8032, 'tt0120841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2288316055.jpg', 3.3, 19.3, 58.5, 14, 4.8, '0.173252,0.333946,-0.798770,0.601887,-0.054991,0.165584,0.510446,-0.288371,-0.515104,-0.440615,0.076121,0.840525,0.027235,0.256091,0.448116,0.245309,-0.306882,-0.239378,0.063362,0.030706,-0.519112,-0.262726,-0.655154,-0.163091,0.065742,-0.649760,0.865431,-0.045989,-0.299251,0.370106,-0.039815,0.904354,0.021654,0.326866,-0.128550,0.029480,0.089554,-0.190713,-0.401503,0.253667,-0.127710,0.255716,0.372535,0.495845,-0.331676,0.068663,0.432151,-0.667070,0.269929,-0.625190,0.547622,-0.465268,0.096663,0.005263,0.194084,0.269616,-0.209574,0.135112,0.057128,0.123846,0.171142,-0.030175,-1.015497,-0.334301,-0.028627,0.031920,-0.110955,-0.149882,-0.054242,0.054876,-0.029387,-0.102776,0.194458,0.404253,0.365643,0.503367,-0.105300,0.122247,-0.312446,-0.321430,0.618989,-0.247146,-0.622512,0.147464,-0.260517,-0.424466,0.018201,-0.123188,-0.216778,-0.024128,0.320619,0.526942,0.038545,0.706465,-1.100843,0.032100,-0.312527,-0.276741,0.329111,-0.171004,-0.203221,-0.930600,-0.331997,-0.088999,0.085441,0.002484,0.335773,-0.425755,0.816412,-0.670798,0.326895,0.543963,0.258525,-0.458090,0.309813,-0.116146,0.118657,-0.624236,0.027444,0.735448,0.137800,0.389209,-0.398268,0.018637,0.091552,0.047271,-0.447343,0.564263', '35377026', '26667010', '1972732', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295225', '西区故事', '剧情', '曼哈顿西部贫民区里有两帮势不两立的流氓团伙，一个是由白人里弗领导的“火箭”帮，另一个是由波多黎各人贝尔纳尔多带头的“鲨鱼”帮。两帮相互仇视，经常斗殴生事。一次西区举行舞会，两个帮派相互拼舞，里弗的朋友托尼（理查德·贝梅尔 Richard Beymer 饰）与贝尔纳尔多的妹妹玛丽亚（娜塔利·伍德 Natalie Wood 饰）一见钟情。贝尔纳尔多发现两人的爱慕后，强行让手下带走了妹妹。夜里，托尼站在玛丽亚的窗前呼唤她，两人坚定地相爱了。第二天，玛丽亚听说“鲨鱼帮”将和“火箭帮”决斗，便让托尼前去阻止。托尼匆匆赶到现场，试图阻止斗殴的发生，在混乱中好友里弗被杀，他出于自卫失手杀死贝尔纳尔多。这让玛丽亚陷入矛盾和痛苦中，她忍受着家人的责骂与侮辱，但心中无法放下托尼。贝尔纳尔多的好友持枪寻找托尼算帐，得知消息的玛丽亚匆匆赶去报信，然而悲剧赶在她之前发生了……本片夺得1961年奥斯卡最佳影片、最佳导演、最佳男配角、最佳女配角等十项大奖。', '娜塔莉·伍德', '杰罗姆·罗宾斯', 7.5, 10807, 'tt0055614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453746512.jpg', 0.8, 3.8, 31.7, 45.6, 18.1, '0.287279,-0.110129,-0.534242,0.389670,0.133309,-0.378432,0.776056,0.071821,-0.352286,-0.055364,0.130711,0.817266,-0.231340,0.080025,0.437887,0.011306,-0.420128,-0.766346,-0.084844,-0.024694,-0.151470,-0.555392,-0.179378,-0.166863,-0.065065,-0.268976,0.415748,-0.160446,0.033839,0.792036,0.473391,0.546647,-0.092918,0.401282,0.075962,0.161605,0.312162,-0.163573,-0.530851,0.593831,0.023941,-0.155728,-0.250153,0.199090,0.120221,0.340198,0.510210,-0.161948,0.288559,0.023344,0.261972,-0.313317,0.140169,0.298577,0.345958,-0.124498,0.218575,0.121194,-0.263871,0.000307,0.017935,0.019844,-0.498870,0.285216,0.073923,0.001263,-0.707052,0.334690,-0.203450,-0.002295,0.384170,0.108412,0.418312,0.507915,0.317556,0.110125,-0.117877,-0.200843,-0.401053,-0.249923,0.645664,-0.227376,0.036531,-0.067643,0.047586,-0.253023,0.311195,-0.159858,-0.287214,0.022635,0.478585,0.023584,-0.013104,0.120908,-0.502621,-0.159693,-0.416120,-0.170078,-0.124422,-0.373316,-0.039518,-0.859152,-0.048987,-0.033249,-0.093004,-0.056482,-0.074517,0.046241,0.374246,-0.588765,0.247478,0.597887,0.299329,-0.387076,0.702094,0.133283,0.374925,-0.193664,0.027879,-0.019458,0.274971,0.187498,0.303492,0.352407,0.041544,-0.022401,-0.296883,0.206512', '3326747', '11541282', '3147969', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295227', '影子大亨', '剧情', '诺维尔（蒂姆·罗宾斯 Tim Robbins 饰）从大学毕业后便来到纽约街头找工作，缺乏经验的他只能在一家金融公司里担任一名收发室小职员。不久后总裁自杀身亡，公司的实权落入了老奸巨猾的董事会成员马斯伯（保罗·纽曼 Paul Newman 饰）手中，这本来没有诺维尔什么事，不料马斯伯为了达到他低价收购公司的目的，竟将看似愚蠢的诺维尔任命为他的傀儡总裁。而诺维尔此刻正在一门心思地研发他的新发明——呼啦圈，马斯伯想借此发明使公司的股票跌入冰点，不料呼啦圈推出后竟大肆流行，公司的股票直线上升。恼羞成怒的马斯伯开始在暗中大动手脚，将公司的局势搅得一落千丈，诺维尔也变成了众矢之的，甚至有可能被关进精神病院。绝望的他再次回到公司大楼的顶层，准备纵身一跃一了百了，然而就在此时，原已故去的前任总裁竟然出现了……©豆瓣', '蒂姆·罗宾斯', '伊桑·科恩', 7.5, 13391, 'tt0110074', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203787782.jpg', 0.6, 3.2, 31.4, 48.4, 16.4, '0.351859,0.315053,-0.868840,0.302229,-0.118358,-0.334264,0.380848,0.621032,-0.361312,-0.239303,0.311671,0.895324,-0.209258,0.261586,0.445949,0.143085,-0.293812,-0.871031,-0.245675,-0.491035,0.058647,-0.387745,-0.123859,-0.221524,0.064385,-0.054213,0.531045,0.177895,-0.043937,0.145938,0.305558,0.357489,0.139293,0.534919,0.160549,0.035997,0.286230,-0.250439,-0.109812,0.260297,0.128040,-0.307888,0.008509,0.068397,0.471611,0.302491,0.392818,-0.230831,0.067908,-0.182379,0.552578,-0.148328,0.183723,0.031796,0.483267,0.111420,-0.043392,0.214418,-0.582021,0.007603,0.247991,-0.356577,-1.120998,0.236629,-0.300415,-0.094011,-0.705188,0.158403,-0.305390,0.174114,-0.085802,-0.384933,0.046242,0.466373,0.093224,0.257124,-0.050606,0.457323,-0.617982,-0.005632,0.501491,-0.040469,-0.350690,0.226062,0.395594,-0.075438,-0.276297,-0.223158,0.027097,-0.457514,0.513426,0.092547,-0.054990,0.094123,-0.480825,-0.185304,-0.476898,-0.453019,0.203835,0.030119,-0.522787,-0.470013,0.201554,0.254715,0.017611,-0.167579,0.098010,0.039360,0.254997,-0.830411,0.106461,0.527619,0.406396,-0.545664,0.511354,-0.472731,0.154891,-0.123554,-0.333258,0.047948,0.196997,0.650815,0.306145,0.103064,0.019590,-0.462901,-0.154893,0.362950', '1793491', '1835843', '1307442', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295229', '木乃伊', '剧情', '埃及城市哈姆纳塔是历代法老墓地，相传此处拥有法老留下的大量珍奇异宝，源源不断的人前往掘金，但却生还者寥寥。哈姆纳塔因此成为谜样的所在，获名“亡灵之城”。图书管理员伊芙琳（Rachel Weisz 瑞切尔·薇茨饰）偶然得到一张哈姆纳塔的地图，大为兴奋的她决定和哥哥一起去那儿考古，他们找到曾经的幸存者欧康诺（Brendan Fraser 布兰登·弗雷泽饰），三人结伴前往。一段惊险旅途后，伊芙琳一行与其他人终于抵达哈姆纳塔，可是最恐怖的事情发生了：三千年前赛提一世的大祭司伊莫顿犯下罪行，受到最严厉的诅咒被做成木乃伊封缄在石棺里，他的灵魂却不慎被唤醒，拥有了无比法力的伊莫顿即将血洗埃及，给世界带来无边灾难……©豆瓣', '布兰登·费舍', '斯蒂芬·索莫斯', 7.9, 178105, 'tt0120616', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1376881286.jpg', 0.2, 1.4, 23.6, 53, 21.8, '0.062931,0.162781,-0.773125,0.574723,0.111098,-0.046421,0.847259,-0.200326,-0.519365,-0.288393,0.076320,0.908476,-0.246925,0.149526,0.270138,0.177640,-0.482339,-0.362603,0.209783,-0.438466,-0.427458,-0.475550,-0.081030,0.050346,0.032358,-0.624035,0.588348,0.047921,0.070912,0.336770,-0.137414,0.830085,-0.443756,0.422329,-0.095159,0.177043,0.182547,-0.251700,-0.124421,0.213470,-0.084622,0.177200,-0.221724,0.297796,0.083974,0.148384,0.530326,-0.574852,0.094454,-0.215988,0.167021,-0.219123,0.111886,0.047815,0.217560,-0.216495,0.128248,0.291292,-0.203767,-0.141875,0.233941,-0.190905,-0.633404,-0.122213,0.074449,0.200078,-0.461947,0.099513,0.035672,0.072648,0.124206,-0.265536,0.363274,0.372806,0.295282,0.144726,-0.042261,-0.342017,-0.461333,-0.382835,0.522389,-0.211875,-0.084896,0.129332,-0.200428,-0.479046,0.154243,-0.150085,-0.341326,0.247991,0.421628,0.095073,0.102692,0.344323,-0.655745,-0.296058,-0.504974,-0.327311,0.127484,-0.163526,-0.045279,-0.738059,-0.086873,0.057331,-0.177499,0.004861,0.060629,-0.234881,0.471530,-0.346539,0.455631,0.492898,0.271663,-0.151766,0.433879,-0.307146,0.329846,-0.067180,-0.017593,0.695308,0.445531,0.410586,0.190333,0.072327,-0.036784,-0.033585,-0.293270,0.607255', '1293124', '1316693', '3231742', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295242', '精灵鼠小弟', '喜剧', '9岁的乔治这天迎来了一个弟弟——小白鼠斯图亚特。这是他爸爸妈妈从孤儿院领回来的可爱精灵，会说话，有智慧，并且很希望有自己的家。然而，乔治却不喜欢斯图亚特，不愿意和他作伴。斯图亚特为此颇为犯愁。更令它处境不妙的是，它成为了肥猫眼中的佳肴，在虎视眈眈下过着冒险的生活。乔治参加了一个航模赛，但是他却一路遭到挫折，先是父亲没能帮他做好模型，当模型好不容易做成了，遥控器却在比赛那天被别人踩坏。在乔治每一次陷入困难的时候，正是斯图亚特机敏勇敢的出手相助，让乔治顺利过关。斯图亚特努力的付出，终于被小乔治接纳，这只小白鼠在乔治家中得到了温暖的归属。©豆瓣', '迈克尔·J·福克斯', '罗伯·明可夫', 7.7, 138465, 'tt0164912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1377980123.jpg', 0.2, 1.3, 28.8, 50.8, 18.9, '-0.001566,0.207592,-0.903572,0.367161,-0.333111,-0.452667,0.688047,0.009806,-0.485055,-0.147366,0.123729,0.781292,-0.025244,0.383904,-0.062200,0.140000,-0.231059,-0.438904,-0.021713,0.044569,-0.292994,-0.278161,-0.215707,-0.338534,-0.047366,-0.364163,0.504823,0.126075,-0.073334,0.374526,0.243743,0.195855,0.406231,0.700975,-0.404549,0.063683,0.131401,0.036360,0.024864,0.273310,0.152219,-0.103537,-0.218315,0.400874,0.268868,0.328358,0.538193,-0.319279,-0.244245,-0.045947,0.363000,-0.417380,-0.005396,0.185972,0.119279,0.043544,-0.009082,-0.117287,-0.121699,0.026165,0.081634,-0.174608,-0.959356,0.054870,-0.139175,0.202736,-0.816545,0.385248,-0.272491,0.143927,0.257533,-0.341396,0.241446,0.511733,0.218186,0.285945,-0.238411,0.117613,-0.668083,-0.005653,0.989367,-0.019635,-0.142131,0.352994,-0.462730,-0.510810,0.330159,-0.444171,-0.453415,0.064264,0.587855,0.064417,-0.110643,0.004589,-0.321928,0.019759,-0.224448,-0.266017,0.099368,-0.566892,-0.017206,-0.294281,-0.037741,-0.424733,-0.610603,0.002853,-0.232299,-0.600581,0.866633,-0.870205,0.315540,0.667710,0.256155,-0.168952,0.801272,0.236853,-0.048292,-0.043561,0.078506,0.119791,0.001393,0.176139,0.267954,0.362936,0.329785,-0.309257,-0.443560,0.483802', '3755531', '30163500', '1877596', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295250', 'X战警', '动作', '具有特殊能力的一群变种人组成了一个维护世界的小组——X战警小队。成员包括能吸收对方能力的淘气、双眼能放致命射线的镭射眼（詹姆斯·麦斯登（James Marsden饰）、能随意控制气候的暴风女（哈莉•贝瑞 Halle Berry 饰）、具有隔空取物和心电感应能力的琴葛蕾（法米克•詹森 Famke Janssen 饰）…… 不久，金刚狼（休•杰克曼 Hugh Jackman 饰）也出现了。不过金钢狼脾气暴躁、独来独往，X战警小队想极力拉拢他加入队伍，无奈孤傲的金钢狼一时也没有答应。与此同时，能控制一切金属的万磁王此时也在极力拉拢金钢狼，X战警小队不仅要费尽心思对付万磁王，还要小心亦正亦邪的金钢狼。他们能否取得最后的胜利？©豆瓣', '休·杰克曼', '布莱恩·辛格', 7.8, 266460, 'tt0120903', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2446530060.jpg', 0.2, 1.4, 26.9, 51.8, 19.7, '0.120452,0.062837,-0.406222,0.546052,-0.174691,0.122347,0.359942,0.067963,-0.270131,-0.375697,0.176700,0.305088,0.149116,-0.435974,-0.290030,-0.303130,-0.023098,-0.192957,-0.024396,0.213664,-0.164779,-0.232980,-0.377639,-0.456665,0.213194,-0.663380,0.479099,-0.183255,-0.223330,0.230420,0.381565,0.655929,-0.119302,0.041659,-0.146862,-0.204381,0.096620,-0.519370,-0.015285,0.365345,-0.072944,0.309162,0.015358,0.314079,0.003312,0.148064,0.864257,-0.381542,-0.052652,-0.244387,0.014972,-0.167419,0.044945,-0.001140,0.388126,-0.186066,0.087259,-0.015964,0.328595,0.210820,0.072882,0.142360,-0.898607,-0.099150,0.186299,0.059442,-0.369039,0.298664,-0.121858,0.176803,0.049549,-0.010006,-0.159835,0.099317,0.258151,0.189458,0.088527,0.110693,-0.674200,-0.097365,0.421425,-0.082766,-0.528570,0.084735,-0.356137,-0.574059,-0.411103,-0.347515,-0.120753,-0.249804,0.696434,0.216741,-0.088514,0.217661,-0.494915,-0.020948,-0.170166,0.279920,-0.143178,-0.523114,0.200878,-0.548154,0.063646,-0.288461,-0.130642,0.287346,-0.081873,0.043653,0.678743,-0.873816,0.050833,0.574580,0.226997,-0.241110,0.442054,-0.081010,0.064774,-0.298935,-0.038790,-0.105534,0.105221,0.198684,0.449508,0.463638,0.251817,-0.288298,-0.117572,0.216242', '1420088', '1401524', '1292829', '20388224');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295253', '美国派', '喜剧', '四个美国大男孩吉姆（贾森•比格斯 Jason Biggs 饰）、凯文（托马斯•伊恩•尼古拉斯 Thomas Ian Nicholas饰 ）、芬奇（艾迪•凯伊•托马斯 Eddie Kaye Thomas 饰）、奥兹（克里斯•克莱因 Chris Klein 饰）即将高中毕业，但四人都还是愣头青（处男）。四人因此遭人嘲笑，他们亦耿耿于怀，发誓在毕业前要告别处男。他们在毕业晚会前就举办了一场派对，企图在派队上找到自己的女孩，告别处男之身。谁知告别处男并没有想象中简单，也没有按设想进行，他们总是在最后关头因为这样那样的原因而失去机会。毕业晚会即将到来，这是他们毕业前的最后一次机会了，四人又开始加紧准备步伐。怀揣着父亲教授的一套性知识的吉姆，最喜欢看图书馆性爱“圣经”的凯文，最喜欢大龄女人的芬奇，还有多才多艺的奥兹，在这场派队中纷纷为自己的誓言而奋斗，于是有了笑料百出的一幕幕。', '贾森·比格斯', '克里斯·韦兹', 7.4, 87222, 'tt0163651', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1446184593.jpg', 0.7, 3.8, 37.3, 42.4, 15.8, '0.214981,-0.221851,-0.641530,0.387342,-0.113215,-0.621677,0.706206,-0.012652,-0.284043,-0.197824,0.295452,0.739934,-0.314444,0.246539,0.366200,-0.068988,-0.681419,-0.598161,0.093719,-0.302183,-0.267809,-0.507533,0.053802,-0.010178,-0.174187,-0.191441,0.591568,-0.149796,-0.040580,0.362326,0.428640,0.041101,0.210737,0.374589,-0.005522,-0.087570,0.229116,0.145339,-0.327959,0.226373,0.170185,-0.143040,-0.352466,0.166147,-0.039288,0.348333,0.620899,-0.178347,0.103531,-0.310199,0.256808,-0.090919,-0.057223,0.282312,0.312375,0.017700,0.351641,0.134985,0.017908,0.001599,0.128680,-0.206433,-0.228461,0.206727,0.032475,0.157395,-0.417700,0.508607,-0.079430,0.153581,0.345791,-0.516584,0.000719,0.267469,0.379945,0.022036,-0.104601,-0.211493,-0.229881,0.119509,0.579121,0.123235,-0.185111,0.364712,-0.004980,-0.360649,0.015207,0.093034,-0.600694,0.125280,0.249175,0.124481,-0.225891,0.124771,-0.270301,0.100068,-0.174763,-0.095931,-0.000221,-0.176359,-0.137514,-0.899443,0.194035,-0.144403,-0.375379,-0.041131,-0.007323,-0.273557,0.500996,-0.819617,0.312607,0.575626,0.271020,-0.181978,0.627627,0.229137,0.178790,-0.216565,-0.184110,0.166014,-0.167188,0.203763,-0.104148,0.525467,0.003093,-0.233750,-0.125511,0.684864', '3178770', '