INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295255', '圣血', '剧情', '一个全身赤裸的年轻男人蹲在室内靠窗的一株树干上，目光呆滞。他就是芬尼克斯（Axel Jodorowsky 饰），被关在精神病院的一位患者。从小体弱多病性格孤僻的芬尼克斯，童年是在马戏班里度过的。父亲奥高（盖伊·斯托克韦尔 Guy St ockwell 饰）是马戏班班主，母亲嘉西娅（布兰卡·格拉 Blanca Guerra 饰）是空中飞人的演员。嘉西娅信奉拜物教，她供的神是个被两个兄弟奸杀的断臂少女。在她流血的地方，人们挖池贮水建起教堂，取名“圣血”。当神父发现所谓的圣血不过是红油漆水时，同意当地政府拆毁教堂。嘉西娅带领教徒反抗。当嘉西娅发现奥高与人通奸时发起报复，奥高拿飞刀斩去嘉西娅双臂，割脉自杀。芬尼克斯进入精神病院。在嘉西娅的唆使下，芬尼克斯逃出精神病院，成为了嘉西娅的“魔手”。©豆瓣', '阿克塞尔·佐杜洛夫斯基', '亚历桑德罗·佐杜洛夫斯基', 8.6, 9617, 'tt0098253', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2389169523.jpg', 1.1, 1.9, 11.7, 38, 47.3, '0.261581,-0.025809,-0.578987,0.223253,-0.226803,-0.077618,0.825243,0.247350,-0.193466,-0.174998,0.464218,0.726608,-0.152175,0.363074,0.022114,0.137694,-0.027688,-0.695606,-0.295032,0.000320,-0.489405,-0.257139,0.089262,-0.180118,0.090533,-0.488789,0.482959,-0.059281,-0.059486,0.244381,0.291448,0.340470,0.130326,-0.129796,-0.317881,0.101786,0.032327,-0.293141,0.089042,0.243637,-0.112885,-0.270834,-0.179011,0.055217,0.051067,0.409900,0.602495,-0.255738,0.196456,-0.252411,0.163734,-0.237527,-0.282748,0.311180,0.345779,-0.321070,0.089593,0.081317,-0.108135,-0.151062,0.157740,-0.151286,-0.424668,-0.031387,0.093861,0.293220,-0.686187,0.358801,0.025089,0.041466,-0.174261,-0.326396,0.252500,-0.177106,-0.267408,0.561876,-0.024801,-0.168624,-0.531405,0.114254,0.384066,-0.104193,-0.033695,0.264051,-0.352259,-0.252503,0.083076,-0.097303,-0.420781,-0.287529,0.388090,-0.457257,0.024211,0.006329,-0.521591,-0.086322,-0.413735,-0.050921,0.042083,-0.103581,-0.315172,-0.373867,-0.231172,-0.089544,-0.204208,0.207063,-0.127670,-0.255184,0.403396,-0.623772,0.279597,0.523855,0.126112,-0.061451,0.690918,-0.129437,0.041871,-0.046718,-0.126011,0.436306,0.312589,0.107911,0.079434,0.280268,-0.232533,0.177814,-0.398812,0.292371', '21619567', '1578663', '3055049', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295260', '好人寥寥', '剧情', '在美国驻古巴关达那摩湾的海军基地，两名海军陆战队员道森和多尼被指控杀害了另一名士兵圣地亚哥。海军律师丹尼尔·卡菲（汤姆·克鲁斯 Tom Cruise 饰）和助手山姆被派接手此桩案件，他们调查到圣地亚哥曾希望调离基地，还举报过道森。卡菲本想进行庭外协调，争取两年刑期。然而 两名士兵坚持自己无罪，他们对圣地亚哥的行为是执行上级给他们下达的“红色条规”。所谓红色条规，就是一种军官默许的由士兵私下进行的训诫条规。卡菲、山姆以及另一名女律师盖洛维（黛米·摩尔 Demi Moore 饰）组成辩方律师进行调查，而基地指挥官杰塞普上校（杰克·尼科尔森 Jack Nicholson 饰）是本案的关键人物，他拒绝了圣地亚哥的调离申请，对他下达了“红色条规”，事后私自篡改了飞行记录。卡菲虽然知道真相，却苦于证据不足，这种情况下若是指证杰塞普上校还会给自己带来麻烦。这场关乎正义的诉讼案，会有一个怎样的结果？', '汤姆·克鲁斯', '罗伯·莱纳', 8, 13269, 'tt0104257', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2242713860.jpg', 0.2, 1.1, 20.8, 54.5, 23.3, '0.248713,-0.038485,-0.342809,0.678508,-0.277969,0.057381,0.466953,0.151646,-0.526476,-0.174937,0.426130,0.527035,0.113466,-0.201953,0.541466,0.160226,-0.577443,-0.683292,0.120814,-0.252910,-0.217585,-0.963124,-0.185668,-0.403777,0.179270,-0.382546,0.429855,-0.076850,-0.227457,0.225842,0.349878,0.562728,-0.039792,0.352873,0.004510,-0.124700,0.489872,-0.481840,-0.269241,0.196857,0.096407,-0.237911,-0.070738,-0.006103,0.123806,0.617460,0.387753,-0.143063,-0.130424,-0.234851,0.082138,-0.518836,0.320439,0.220661,0.587833,0.053779,-0.074917,0.618099,-0.207780,-0.048683,-0.005508,0.122071,-0.762481,-0.002925,-0.049389,0.390889,-0.510037,0.236925,-0.663134,0.257510,0.057337,-0.143553,-0.106587,0.413867,0.100519,0.129469,0.121677,-0.192642,-0.488335,0.087623,0.643509,-0.210888,-0.219853,-0.340466,-0.198769,-0.308883,0.116433,-0.141139,-0.294115,0.008299,0.176261,-0.146684,0.032845,-0.081061,-0.326902,-0.198536,-0.585005,-0.450090,-0.155683,-0.311116,0.067974,-0.706458,0.039102,-0.031768,-0.407870,0.026173,0.213282,0.109869,0.461016,-0.566791,0.224094,0.397254,0.428338,-0.670545,0.320724,0.417915,0.297464,-0.391395,0.020869,-0.154441,0.438930,0.497927,0.129680,0.165391,0.344626,-0.507611,0.024944,-0.155655', '1296217', '1307442', '3006781', '1299335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295273', '笑拳怪招', '喜剧', '清朝时，由岳飞创立的形意门一派勇于抗清，朝廷鹰犬任天化（任世官 饰）武功高强，四处搜寻形意门高手陈鹏飞（田俊 饰）。僻静的青龙镇上，隐姓埋名的陈鹏飞和孙子陈兴龙（成龙 饰）每日辛勤练功，陈鹏飞为了避免暴露身份严令兴龙惹是生非。这日，兴龙上街赌钱显露身手拆穿庄家骗局，当地富户随即邀请兴龙到自己的武馆中担任教头。兴龙将武馆改名为形意门，又隐藏幕后替馆主料理各方挑战者。青龙镇的形意门名声渐起，将任天化引来，懵然不知的兴龙将任天化一行引到家中，任天化将陈鹏飞杀害。幸有陈鹏飞好友八脚麒麟及时赶到，兴龙才免于一死，自此兴龙跟随八脚麒麟苦练武功，矢志为爷爷复仇……©豆瓣', '成龙', '成龙', 6.9, 7838, 'tt0079315', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199898167.jpg', 1, 5.2, 52.6, 29.4, 11.7, '0.217385,0.156577,-0.217303,0.323166,0.016870,-0.412501,-0.070940,0.166853,-0.630670,-0.582139,0.323294,0.295090,0.097953,0.056871,-0.018516,-0.331848,0.103500,-0.575107,-0.202432,-0.048290,0.008885,0.231848,0.048361,-0.160610,-0.367550,0.250066,0.132515,0.205742,-0.433971,0.574807,0.151922,0.213795,-0.250599,0.010118,0.024549,0.205855,0.002941,0.021211,-0.189356,0.024608,-0.127357,-0.763833,-0.320118,-0.186951,0.119555,0.281161,0.439480,-0.037580,0.045863,-0.548274,-0.081689,-0.080278,-0.193659,0.055058,0.418282,0.275626,0.024432,0.442640,-0.254676,-0.228262,-0.196458,-0.137504,-0.505675,-0.092945,0.534070,-0.141965,-0.420647,-0.131954,-0.401515,-0.133002,0.005421,-0.556905,0.052848,0.338019,0.045876,-0.028354,0.065701,0.113329,-0.602121,0.366073,0.471171,-0.320638,0.475571,-0.547017,0.311724,0.000621,0.567444,-0.392902,0.045577,-0.380510,0.350127,-0.408451,0.545242,-0.086348,-0.204830,-0.362094,-0.468816,0.126712,-0.081423,-0.104704,0.147573,-0.509191,-0.136289,-0.011159,0.106551,-0.211464,0.097362,-0.126473,0.476421,-0.813787,0.161969,-0.042230,0.210663,-0.445154,0.473928,-0.441567,0.388531,-0.236874,-0.157434,-0.206942,0.646248,0.522111,-0.083332,0.448555,-0.164895,-0.324896,-0.107819,-0.124551', '1308722', '1308228', '1306490', '1483577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295276', '录影带谋杀案', '科幻', '马克思（James Woods 饰）是一家小型电视台的台长，为提高收视率，马克思四处搜罗带有色情或暴力内容的剧集。马克思的下属哈兰盗用卫星信号，获取了一档名为影视场的节目，内容为写实粗糙的暴力虐待场面，马克思看过这套节目后无法忘怀，对其他剧集丧失了兴趣。电台主播尼奇（Deborah Harry 饰）与马克思相识不久，这名有受虐倾向的女子也被影视场吸引，奔赴节目可能的产地匹兹堡欲参与制作。马克思经人指点拜访影视场的创始人布莱恩教授却没有见到真人，教授寄来的以尼奇为主角的录像让马克思产生了幻觉，马克思再度拜访始知布莱恩早已被杀死，现在的影视场节目由惊人视力公司的巴里负责，马克思一步步落入了巴里设计好的圈套，在巴里与布莱恩两种力量间越陷越深……本片获1984年加拿大吉尼奖最佳导演奖。©豆瓣', '詹姆斯·伍兹', '大卫·柯南伯格', 7.4, 8491, 'tt0086541', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2187448671.jpg', 1.1, 4.9, 32.1, 45.8, 16.1, '0.197977,-0.006100,-0.543866,0.708203,0.153653,-0.123980,0.575018,0.149527,-0.417762,-0.286902,0.012446,0.715352,-0.434114,-0.164683,0.261372,-0.105508,-0.305073,-0.474834,-0.233545,0.001841,-0.017796,-0.385412,-0.387776,-0.177812,-0.061342,-0.528248,0.625026,0.089839,-0.618524,0.480302,0.320990,0.279317,0.064061,0.145364,0.182122,-0.051069,0.298729,-0.188984,-0.325229,0.432247,0.057707,-0.136189,-0.004733,0.004403,-0.085776,0.320465,0.696864,0.079948,-0.123289,0.005560,0.708345,-0.107107,0.038753,0.054489,0.422200,0.253760,0.129515,0.235297,-0.146990,0.040720,0.079429,-0.174362,-0.831712,-0.010579,0.263967,0.077765,-0.313385,0.292306,-0.343312,-0.024000,-0.185152,-0.059670,0.095570,0.110005,0.424733,0.298264,0.309944,-0.042958,-0.084471,0.562635,0.495718,-0.113576,-0.300389,0.233812,-0.184873,-0.501991,-0.040249,-0.303586,-0.119008,0.203391,0.358825,0.057672,0.025428,0.056472,-0.546695,-0.083921,-0.050628,-0.353708,0.031946,-0.260764,-0.088697,-1.095644,-0.275322,-0.035022,0.011199,-0.245225,0.297218,-0.206008,0.671678,-0.644075,0.269262,0.438563,0.189364,-0.329959,0.917332,-0.128678,-0.212899,-0.117529,-0.243948,-0.226338,0.005897,0.298132,0.076040,0.298742,0.342949,-0.660315,-0.260074,0.300095', '26275494', '3318306', '24751811', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295280', '黑衣人2', '喜剧', '故事发生在第一部的四年之后，此时特警K（汤姆•李•琼斯 饰）已经退休，成为一名普通的邮局局长，而J（威尔•史密斯 饰）则继续从事MIB的工作。卡洛瑟星邪恶女王蛇莲娜来到地球需找宇宙能量“萨塔之星”，占领了MIB的总部。而当年逃亡到地球的萨塔公主萝娜曾请求MIB把 “萨塔之星”藏在地球，全面负责这件事情的K为了地球的安全，拒绝了她。面对来势汹汹的蛇莲娜，MIB派J去寻找k，调查当年事件的真相，怎样说服失去记忆的K相信外星人的存在，成了J面临的第一个难题……©豆瓣', '威尔·史密斯', '巴里·索南菲尔德', 7.7, 207984, 'tt0120912', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p453515660.jpg', 0.2, 2.1, 28.2, 50.2, 19.3, '0.132122,0.341330,-0.755243,0.458258,-0.227696,-0.084837,0.559914,-0.188528,-0.240952,-0.516556,0.216938,0.583617,0.171104,-0.005816,0.439714,0.008259,-0.236628,-0.421224,0.263905,-0.246587,-0.402202,-0.609511,-0.248675,-0.229405,0.043839,-0.431812,0.856769,0.145352,-0.151266,0.270895,0.110669,0.755874,-0.047181,0.413984,0.105626,-0.093189,0.192691,0.055885,-0.490927,0.417177,0.038596,-0.051917,0.206687,0.320672,-0.021570,0.034148,0.480904,-0.388676,-0.113987,-0.166714,0.432593,-0.619720,0.047317,-0.069320,0.751768,-0.042748,-0.229189,0.161011,-0.275161,-0.177050,0.146047,-0.128714,-0.770177,-0.157787,0.078768,0.475696,-0.534485,-0.143222,-0.234451,0.154479,0.188179,-0.390834,0.267171,0.775081,0.220424,0.350592,0.062197,0.380548,-0.541927,0.175696,0.723503,-0.101229,-0.259687,0.136853,0.165517,-0.263592,-0.067214,-0.228123,-0.273460,0.246692,0.315865,0.005870,-0.284625,0.454185,-0.568053,-0.345479,-0.272855,-0.475115,0.319581,-0.427254,-0.086511,-0.645970,-0.138541,-0.130328,0.021075,-0.232287,0.184142,-0.228138,0.540433,-0.774554,0.447863,0.450903,0.077929,-0.843793,0.492998,0.068519,0.199546,-0.545497,0.226414,0.522842,0.336515,0.684872,-0.237879,0.040358,0.358903,-0.288707,-0.536006,0.277048', '3861846', '1295746', '5157137', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295283', '冒牌老爸', '剧情', '索尼（亚当•桑德勒 饰）今年已经32岁了，可是为人缺乏责任感，因为他由衷想逃避所有成年人应该承担的责任。正是因为这个原因，她的女友云妮决定要离开他。索尼感到很无奈，眼看自己的朋友也都全部成家立业了，自己的女友也离开了自己，他便觉得压力更大了。他突发奇想，要到收养5岁小孩朱利。天真的索尼认为这样便能让云妮回心转意，于是他向福利处撒谎说自己是朱利的生父并顺利的收养了朱利。但云妮心意已决，索尼终究没有赢回云妮的心，但面对已经收养了的朱利，他只好尝试与之相处了。但的确是一种责任，索尼必须每天都要面对索尼种种小孩子的行为，导致笑料百出。但渐渐，他似乎又习惯了这种责任，开始乐在其中……©豆瓣', '亚当·桑德勒', '丹尼斯·杜根', 7.3, 13242, 'tt0142342', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p995398305.jpg', 0.6, 4.2, 37.7, 43.7, 13.7, '0.137418,-0.028169,-0.902662,0.420961,-0.270513,-0.405957,0.553026,0.100345,-0.597526,-0.405243,0.041366,0.807682,0.135568,0.401950,0.156722,0.114578,-0.145084,-0.550595,0.136498,-0.173119,-0.326834,-0.491103,0.061661,-0.400154,-0.362854,0.024575,0.587460,0.022046,-0.029455,0.118462,0.388912,0.060481,0.641228,0.822118,-0.090391,0.037846,-0.196036,-0.052957,0.025340,-0.051942,0.402311,-0.299924,-0.215761,0.728688,0.036543,0.650933,0.495761,-0.351929,-0.382128,0.058620,0.289309,-0.644160,-0.040795,0.243317,0.084835,0.013054,0.186852,0.188858,-0.079359,-0.157035,-0.025544,0.050385,-0.723283,0.067692,-0.029945,-0.147428,-0.645526,0.265560,-0.025694,0.018568,0.001859,-0.370792,0.045753,0.271215,0.096864,0.384674,-0.511210,-0.084792,-0.344210,-0.042337,0.721176,0.010135,-0.208927,0.650507,-0.474271,-0.367440,0.020205,-0.333621,-0.522732,-0.024221,-0.017773,0.348800,-0.323716,0.225837,-0.247490,-0.110924,-0.242911,-0.149993,-0.114876,-0.698252,0.480420,0.148783,-0.290302,-0.445663,-0.471839,-0.011175,0.197426,-0.451431,0.678444,-0.864786,-0.051390,0.718216,0.362777,-0.870150,0.468280,0.297339,-0.005106,-0.219224,0.096775,0.367046,-0.331623,0.040388,0.163605,0.183366,0.528086,-0.266396,-0.158486,0.523676', '26718282', '35073886', '1308805', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295284', '星月童话', '剧情', '未婚夫达也（张国荣）在香港死于一场交通意外后，瞳（常盘贵子）以为自此失去幸福，生活质量开始大幅滑坡。为了兑现曾与达也在香港许下的承诺，她勉强收拾心情只身来到伤心城。同瞳一样，香港警察家宝（张国荣）也有一段伤心往事，他曾因工作狂热导致女友无法忍受冷落自杀身亡。女友死后，家宝选择做了卧底，想以更加狂热刺激的工作来麻醉和折磨自己。瞳遇到家宝后，因为家宝与达也长得一模一样，疑惑达也还在，内心又起美丽的憧憬，两个因爱受伤的人擦出烂漫火花。©豆瓣', '张国荣', '李仁港', 8.2, 39626, 'tt0202478', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2157774740.jpg', 0.3, 1.5, 20.9, 43.4, 34, '-0.188579,-0.102489,-0.648624,0.125800,0.147581,-0.472251,0.663110,0.132024,-0.413496,-0.218212,0.174961,0.648996,-0.228780,0.484571,0.181994,-0.241695,-0.287647,-0.585883,0.133902,-0.220180,0.148493,-0.281655,0.108621,0.060415,-0.026222,-0.440997,0.297049,-0.057907,-0.173928,0.659222,0.327425,0.181137,-0.034378,0.547340,-0.050781,-0.048347,-0.528052,0.202263,-0.393106,-0.262702,0.263504,-0.212497,0.178870,0.046351,-0.006084,0.091053,0.783631,0.037082,-0.642036,-0.199494,0.361690,-0.314628,0.041188,0.033758,0.322572,-0.049743,0.183293,0.062032,-0.418140,-0.049428,0.090116,-0.034605,-0.863909,0.237151,0.114419,0.116682,-0.400695,0.272110,-0.088998,0.036854,0.330596,-0.298121,0.069573,0.373516,0.266017,0.437426,-0.441663,0.162972,-0.181683,0.369093,0.961866,-0.025851,0.156009,0.178953,-0.170066,-0.062207,0.052433,-0.132358,-0.513093,0.334915,-0.069465,-0.025491,-0.244756,0.245832,-0.410707,0.035517,-0.295604,0.066173,0.167609,-0.236323,0.056905,-0.457720,-0.025030,-0.071555,-0.518949,-0.149902,-0.052322,-0.440364,0.329971,-0.703676,0.415388,0.418202,0.625198,-0.482586,0.422285,0.124787,-0.288179,-0.144337,-0.032786,0.688864,-0.307598,0.137148,0.094295,-0.003270,-0.027794,0.143656,-0.112107,0.219252', '26678784', '4728584', '34841067', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295287', '党同伐异', '剧情', '本片又译作《党同伐异》，是D．W．格里菲思最具创作野心的作品。由于受到《国家的诞生》惊人卖座的影响，格里菲思遂再接再励拍摄一部场面更大，内容更有深度的影片。他花了一年半的时间，动用了二百万美元的制作费，拍摄成片长220分的巨片（原版长480分）。可惜本片在1916年9月于纽约公映时，并没有受到预期的欢迎。本片所以卖座失败，原因很多，最主要是格里菲思在本片所采用的故事结构太复杂，导演手法已超越当时观众的接受能力。加上主题过于严肃，其中提倡的宽容和反对暴力的论调跟当时美国的高昂参战情绪引起冲突，因此未能受到普遍欢迎。不过，人们却不能否认这是一部电影艺术上的不朽杰作。《忍无可忍》由四段不同时代发生的故事组成：巴比伦的没落、耶稣基督的受难、法国的圣巴托罗米宗教大屠杀，以及二十世纪初美国的劳资冲突。格氏描述他自己的构想：“四个大循环故事好象四条河流，最初是分散而平静地流动着，最后却汇合成一条强大汹涌的急流"。本片一开始，是一个母亲推摇篮的镜头，插入惠特曼的诗句：“如今如同昨日，世间的人情变化循环无穷。摇篮摇动着，为人类带来同样的激情，同样的优乐悲欢。"这字幕之后，展开第一个作为全片基调的现代篇故事。随着剧情的进展，导演经常切入另外三段故事，成为四段平行发展。最后，画面仍回到母亲和摇篮，呈现出“人类从不容异已到宽容的进化"的主题。作为故事核心的现代篇“母与法"，内容描述四个失业的男女工人从小镇来到都市中找工作，有人误入歧途，有人渴望过正常的家庭生活。正派的男主角被诬陷为杀人凶手，被捕后判处死刑。行刑之日，真凶良心发现，在最危险的一刻将男主角救了出来。从这个故事中，可以看出二十世纪初期美国的', '丽莲·吉许', '大卫·格里菲斯', 8.8, 10435, 'tt0006864', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2497099880.jpg', 0.4, 0.8, 10.5, 37, 51.2, '0.247182,0.090049,-0.647632,0.601781,0.220177,-0.039523,0.698261,-0.022051,-0.397231,-0.255898,0.153064,0.551528,-0.259485,0.008205,0.248009,-0.395780,-0.193741,-0.428211,-0.201622,-0.050433,-0.108250,-0.477340,-0.232976,0.001398,-0.239449,-0.466445,0.738345,0.195780,-0.668647,0.209291,0.256512,0.302530,-0.051248,0.150641,0.077473,-0.140627,-0.131079,0.020477,-0.336583,0.188708,-0.074083,-0.169057,-0.087452,0.093704,-0.264042,0.297584,0.743764,-0.286082,-0.255897,0.068932,0.839958,-0.188806,-0.345881,-0.185035,0.313452,0.178047,0.245117,0.323274,0.028607,0.094510,-0.212441,-0.345836,-0.941894,-0.163335,0.119062,0.188930,-0.340213,0.275188,-0.041978,-0.154256,-0.011630,-0.216266,0.045570,0.314872,0.481753,0.455973,-0.140574,-0.021227,-0.359815,0.221969,0.590639,-0.009453,-0.614410,0.511397,-0.276645,-0.547039,-0.283530,-0.552927,-0.231936,0.212574,0.219771,0.077374,-0.093320,0.442214,-0.572686,-0.057317,-0.075770,-0.386889,0.085438,-0.219524,-0.092758,-0.611648,-0.156184,-0.288277,-0.116073,-0.096082,0.149650,-0.331377,0.888899,-0.544609,0.296951,0.371473,0.116084,-0.406146,0.638257,0.078927,0.037564,-0.297018,-0.132248,0.235646,-0.090637,0.062591,-0.066132,0.200798,-0.027768,-0.330175,-0.570132,0.523509', '27602116', '22265121', '24284209', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295292', '哥斯拉', '动作', '这天，美国纽约附近出现了一些异常现象：太平洋上的海浪速度超乎寻常地惊人、巴哈马巨大的原始森林里竟然出现了一个类似恐龙脚印的巨大痕迹、动物们都惊慌失措，仿佛一股巨大的力量正向纽约席卷而来。原来，世界上频繁的核试验引起的核辐射导致了气候异常和最终导致岛上蜥蜴变异。现在，它正以越来越快的步伐向纽约逼近。这下，所有的人都慌了神，美国全国的所有力量都联合了起来，目的只有一个，就是在它踏入纽约前将它干掉！©豆瓣', '马修·布罗德里克', '罗兰·艾默里奇', 7.2, 76532, 'tt0120685', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1583456026.jpg', 1, 5, 40.9, 39.6, 13.5, '0.274908,0.124746,-1.139871,0.703406,0.295673,0.055342,0.822480,0.054273,-0.364315,0.122399,0.138829,0.700055,-0.342556,-0.006789,-0.092559,-0.082180,-0.041527,-0.574862,-0.480664,-0.238326,-0.692428,0.072674,-0.772072,-0.172046,0.110833,-0.325560,0.294207,0.385438,-0.352580,0.522290,-0.049785,0.037613,-0.154151,0.617216,-0.176563,-0.020182,0.026804,-0.094376,0.288847,0.178519,-0.144625,-0.472789,0.300411,0.453932,-0.296863,0.199386,0.830811,-0.421070,-0.194091,-0.521074,0.274977,-0.409938,0.046145,0.226471,0.633490,0.057611,0.233099,-0.135465,-0.109320,0.011828,0.130991,-0.012524,-0.754476,0.080166,-0.133061,0.193719,-0.393460,0.071605,0.187657,-0.191230,-0.065219,-0.611086,0.335778,-0.037071,-0.007692,0.337745,-0.420714,0.105306,-0.412978,-0.330904,0.795001,-0.033765,-0.678011,-0.067955,-0.263398,-0.290111,-0.438404,-0.185572,0.106714,-0.269705,0.361124,0.366613,-0.272530,0.396343,-1.028817,0.283108,-0.340004,-0.647107,-0.561716,0.032371,-0.305066,-0.611779,-0.047601,-0.362739,-0.098398,0.279146,0.006537,0.048592,0.631232,-0.238287,0.403574,0.897684,0.420474,0.037456,0.286919,-0.590732,-0.120453,0.112802,-0.074745,-0.066792,0.107509,0.683076,0.024798,0.420143,-0.122009,-0.020727,-0.384343,0.944886', '34461680', '26309788', '10440138', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295295', '独领风骚', '喜剧', '故事发生在位于比弗利山庄的一所贵族学校中，能够进入此学校就读的学生们，非富即贵，所以，校园里奢侈和自由的风气和普通的学校是无法相比的。在这里，成绩和品行都不重要，重要的是五颜六色的名牌时装，是闪闪发光的珠宝配饰，是张扬奔放肆意挥洒的个性。我们的主人公雪儿（艾丽西亚·希尔维斯通 Alicia Silverstone 饰）就在这样的世界里生活成长着。一位转学生的到来吸引了雪儿的注意，在偌大的校园里，在同学朋友的眼中，这名转学生简直就是“怪胎”，穿着平庸打扮又土气，雪儿决定帮助她改头换面，“重新做人”。在雪儿的指导下，转学生果然有了焕然一新的面貌，甚至更胜雪儿一筹，这让雪儿的内心里十分不平。©豆瓣', '艾丽西亚·希尔维斯通', '艾米·海克林', 7.7, 32437, 'tt0112697', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1514976453.jpg', 0.5, 3.3, 29.2, 43.1, 23.9, '0.645222,-0.086935,-0.465326,0.443798,-0.433506,-0.075785,0.597836,0.116527,-0.499433,-0.183615,0.314666,0.752574,-0.270558,0.272446,0.135485,0.182969,-0.451801,-0.672909,-0.157361,-0.404997,0.051771,-0.516323,-0.327557,0.083782,-0.045103,-0.471273,0.502858,-0.015825,-0.222453,0.595305,0.147892,0.191141,-0.009923,0.163337,-0.357518,-0.288015,0.156834,0.298042,-0.000066,0.298499,-0.069362,-0.034565,-0.004452,0.142053,0.268736,0.059173,0.779378,-0.153162,-0.166816,0.096105,0.526362,0.119717,-0.205187,0.261458,0.265733,-0.050505,0.367509,0.164424,-0.171060,0.217834,0.030244,-0.133575,-0.484259,0.090330,0.603099,0.171446,-0.740994,0.746710,0.042357,-0.504093,0.263301,-0.247411,0.286275,0.041845,-0.016629,0.561758,0.249548,0.049612,-0.586373,0.167487,0.620485,0.159608,-0.320545,0.215637,-0.574713,-0.342922,-0.022209,-0.175614,-0.517861,-0.116816,-0.061504,-0.068939,0.032234,0.263126,-0.602408,0.467694,-0.026011,-0.208336,-0.134893,-0.310946,-0.406330,-0.476717,-0.088825,-0.653828,-0.346485,-0.076505,0.029561,-0.337146,1.115998,-1.251794,-0.133189,0.232143,0.373969,-0.367382,0.871646,-0.023234,0.257848,0.094313,-0.421157,-0.051829,-0.156223,0.402624,-0.287882,0.782476,-0.124668,-0.423382,-0.561877,0.605154', '3445516', '1292219', '6963575', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295316', '烈火战车', '剧情', '阿祖（刘德华 饰）母亲逝世后，父亲（秦沛 饰）管教方法不当，父子俩的关系疏离。阿祖离开家独自生活，生活状况并不如意，幸好有女友阿仪（梁咏琪 饰）在旁鼓励照顾。阿祖一向喜爱赛电单车，但他性格要强，一次与父亲车队中的大伟（吴大伟 饰）比赛，结果阿祖在比赛中受伤了，昏迷了十天。女友悉心照顾并劝他以后不要再赛车了，于是阿祖康复后便决定放弃赛车，好好经营修车店。可是好友嘉乐（钱嘉乐 饰）在一次与大伟的比赛中身亡，事件令阿祖的初衷改变了，阿仪却失望离去……©豆瓣', '刘德华', '尔冬升', 7.1, 15093, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2617731352.jpg', 0.6, 4.1, 47.4, 34, 14, '-0.289531,0.030549,-0.296184,0.283816,0.002885,-0.839257,0.328677,0.244832,-0.745525,-0.304774,0.048759,0.586463,0.012519,0.284096,0.179013,-0.114588,-0.342748,-0.559051,0.221112,0.094771,-0.261703,-0.430152,0.244619,-0.123983,0.033328,-0.226134,0.371805,-0.004477,-0.113006,0.824564,0.085778,-0.117639,-0.061939,0.481520,0.103222,0.022042,-0.041627,0.132264,-0.732940,0.059442,0.315441,-0.028699,-0.208400,0.000756,0.615403,0.263534,0.728797,-0.076391,-0.371713,-0.124698,0.018645,0.017681,0.074681,0.060680,0.224504,0.260389,0.412535,0.613642,-0.204099,0.189889,-0.330264,-0.101937,-0.101890,0.100078,-0.057109,-0.098966,-0.732739,0.544833,-0.073678,-0.054279,-0.106033,-0.195174,0.252123,0.265934,0.336879,0.126452,-0.432476,0.071763,-0.141074,0.152704,0.546480,-0.113526,0.222844,0.511244,0.045415,-0.217348,0.045383,-0.170428,-0.528748,0.241314,0.131166,0.016675,-0.246641,0.050531,-0.257144,-0.097862,-0.208928,-0.020690,-0.097254,-0.293853,0.272971,-0.552756,0.165697,-0.318406,-0.555473,-0.019671,-0.188376,-0.182983,0.428650,-0.909732,0.253746,0.125555,0.439996,-0.733496,0.491149,0.319165,0.425779,-0.256736,0.067858,0.310807,-0.334286,-0.134071,-0.062712,0.046196,0.064944,-0.425868,-0.309802,0.247248', '1306133', '27621189', '1301562', '22964524');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295318', '大话王', '喜剧', '弗莱切（金•凯瑞 Jim Carrey 饰）是个知名的大律师，为获得官司的胜利，他练就一身颠倒是非、扭转黑白的本领，那就是，谎话连连。说慌已经成为了弗莱切的本能反应，就连面对妻子和5岁的儿子麦克斯（Justin Cooper 饰）时都是如此。妻儿也早已习惯了他的作风。这天，是麦克斯的生日，弗莱切又因事不能来。弗莱切自然又满口谎言编造各种借口。失望的弗莱切许下了他的生日愿望：父亲有一天不能说谎了。神奇的事情发生了！弗莱切真的不能说谎了，他因此洋相连连：差点输掉官司、得罪上司……陷入空前混乱的弗莱切最终如何面对这一切？©豆瓣', '金·凯瑞', '汤姆·沙迪亚克', 7.7, 69891, 'tt0119528', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1308251107.jpg', 0.2, 1.6, 28.8, 51, 18.4, '-0.016266,0.048996,-0.544268,0.331177,-0.346243,-0.237959,0.350710,-0.104455,-0.461271,-0.271410,-0.001209,0.807594,-0.377749,0.037032,0.139539,-0.198757,-0.092339,-0.613194,0.093005,0.035324,0.004203,-0.575159,-0.109998,-0.139743,0.014570,-0.092227,0.149273,0.119262,-0.364732,0.113207,0.568700,0.303689,0.448413,0.472676,0.071916,0.044740,-0.256572,0.114420,-0.001444,-0.016271,0.114049,-0.250213,-0.070204,0.372675,-0.188552,0.399523,0.224447,-0.284303,-0.310596,-0.083074,0.524534,-0.569415,-0.066477,0.309871,0.032433,-0.228704,0.165430,0.003526,-0.110993,-0.038732,0.144260,0.147775,-1.026740,0.052217,0.073841,0.018666,-0.561426,0.297820,-0.279406,-0.235358,-0.060452,-0.221778,0.120347,0.191807,0.357622,0.287709,-0.106669,-0.090054,-0.492596,0.116535,0.730752,0.021591,-0.218859,0.450235,-0.227627,-0.331905,-0.033244,-0.384452,-0.373400,0.124079,0.034672,0.002891,-0.094304,0.198781,-0.060801,-0.306863,-0.276383,-0.234497,-0.087050,-0.290473,-0.022000,0.168782,-0.170068,-0.363995,-0.593454,0.030673,0.026856,-0.157771,0.418506,-0.663025,0.164230,0.301291,0.093237,-0.434785,0.582084,0.345413,-0.001598,-0.130610,-0.015533,-0.055495,-0.180965,0.157521,0.247796,0.159046,0.358230,-0.333668,-0.004880,0.424956', '26678784', '1793491', '30163500', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295324', '真实罗曼史', '爱情', '漫画店打工仔Clarence Worley（克里斯汀·史莱特 Christian Slater 饰）生日的时候，在电影院邂逅了美女Alabama Whitman (帕特丽夏·阿奎特 Patricia Arquette 饰)，两人一夜春宵。第二天，Alabama告诉Cla rence她是个妓女，是Clarence的老板送给他的生日礼物，但她爱上了他。Clarence决定将Alabama从皮条客Drexl Spivey（加里·奥德曼 Gary Oldman 饰）手中拯救出来。夜总会的一阵混战后，Clarence开枪将Drexl杀死，并拿走了一个他以为属于Alabama的手提箱。后来两人发现，手提箱里竟有大量可卡因。两人欣喜若狂，开始流浪，寻找将可卡因换成现金的机会。两人一路来到了洛杉矶，找到了Clarence的老友Dick Ritchie（迈克尔·拉帕波特 Michael Rapaport 饰）。Dick是个在好莱坞混迹的演员，他把一位能转手可卡因的导演Lee介绍给二人。而另一边，被Drexl偷走了大量可卡因的黑帮老大Vincenzo Coccotti（克里斯托弗·沃肯 Christopher Walken 饰）也带着一帮人开始寻找两人的踪迹。一场场大战即将上演，到底这对恋人的罗曼史能否延续下去？', '克里斯蒂安·史莱特', '托尼·斯科特', 8, 12553, 'tt0108399', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2449120503.jpg', 0.5, 1.8, 21.2, 48.3, 28.2, '0.448071,0.006127,-0.442024,0.402132,-0.107989,-0.464553,0.862276,-0.103756,-0.421656,-0.131232,0.007115,0.867974,-0.310274,0.181193,0.373795,0.135869,-0.333165,-0.752602,-0.108152,-0.251399,-0.245991,-0.417644,-0.393794,0.030120,0.057081,-0.190523,0.293950,-0.086183,-0.084926,0.581944,0.558134,0.139078,-0.034277,0.382753,-0.249641,0.150358,0.190529,-0.026909,-0.195208,0.616643,0.062771,-0.317467,-0.006456,0.173594,0.170171,0.223559,0.754270,-0.259112,0.256483,0.060421,0.262717,-0.147413,-0.032141,0.218285,0.112174,0.118047,0.149446,0.047861,-0.372980,0.019206,0.312646,-0.029698,-0.573028,0.145215,-0.125294,0.131620,-0.841235,0.366368,-0.128992,0.046504,0.097093,-0.281497,0.427028,0.292402,0.170346,0.225798,0.120944,-0.171508,-0.762840,0.209133,0.537136,-0.279322,0.263669,0.403204,0.050640,-0.417298,-0.029241,0.082891,-0.481886,-0.103773,0.587077,-0.153238,-0.093734,-0.065821,-0.783122,-0.105642,-0.288866,-0.207893,0.144960,-0.292071,-0.237301,-0.550727,-0.174675,-0.136435,-0.187550,0.130646,-0.029588,-0.256521,0.503815,-0.628194,0.142265,0.6