INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295340', '小鬼当家3', '喜剧', '美国国防部的一块电脑芯片不见了，里面存着高级的机密。国际犯罪分子也将其价格炒到了天文数字。为了能完成交易，犯罪分子将其藏匿在一台玩具遥控车里面，并顺利通过了机场的安检。不过，途中却阴差阳错的被一位老太太调包，最终这台藏着高级机密芯片的遥控车被送到了8岁男孩儿阿历克斯（亚历克斯·D·林兹 Alex D. Linz 饰）的手中。为了取回芯片，受过专业训练的犯罪分子潜入了阿历克斯所住的小区。一天晚上，阿历克斯因为长水痘而被独自留在了家里，这给犯罪分子极大的机会。不过……阿历克斯却不是他们想象中的8岁男孩儿，他有着让人意想不到的“武器”，最终用智慧打败了犯罪分子。由于之前两部的小主角麦考利克金在第三部开拍时已经长大，所以第三部启用了新的小主角亚历克斯·D·林兹。©豆瓣', '亚历克斯·D·林兹', '拉加·高斯内尔', 7.8, 82028, 'tt0119303', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2197177694.jpg', 0.3, 2.3, 28.5, 46.8, 22.1, '0.203184,0.327453,-0.567971,0.372489,-0.187638,-0.255170,0.697648,-0.060887,-0.566580,-0.297190,0.129943,0.655607,-0.129724,0.158140,0.001061,0.014103,-0.416980,-0.319103,-0.114633,-0.509260,-0.430111,-0.428706,-0.513504,0.075824,-0.142971,-0.180299,0.500319,-0.201866,-0.063480,0.058409,0.311951,0.163779,0.062914,0.233871,-0.140138,-0.061760,0.210887,-0.219747,-0.025142,0.464380,0.092651,-0.201635,0.108513,0.058216,0.244635,0.304789,0.779274,-0.383418,-0.012678,-0.048069,0.347524,-0.148146,-0.180856,-0.035600,0.219908,0.132651,0.105863,-0.092398,-0.395349,0.092566,0.335841,-0.271193,-0.774407,-0.110382,0.041194,-0.060875,-0.579369,0.274850,-0.383470,0.086425,-0.010434,-0.311446,0.313734,0.389890,0.183321,0.258689,-0.128524,-0.039420,-0.676695,0.202511,0.226923,-0.261795,-0.291407,0.421058,-0.093899,-0.670247,-0.030933,-0.392056,-0.388090,0.170864,0.682945,0.120390,-0.288578,0.099114,-0.588701,0.017771,-0.454903,-0.047848,-0.082140,-0.155480,-0.185715,-0.528609,0.061633,-0.161185,-0.264258,0.091878,0.123891,-0.217820,0.587732,-0.474439,0.123738,0.689237,0.335287,-0.118907,0.535555,-0.381786,0.191979,-0.074822,-0.163397,-0.129201,0.180186,0.724439,0.457406,0.354777,-0.102160,-0.482473,-0.274012,0.450623', '21619567', '1301345', '1292523', '1300324');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295344', '喋血街头', '剧情', '细荣(李子雄饰）、阿B（梁朝伟饰），辉仔（张学友饰）在石殎尾陡置区一同成长，三人情同手足，虽然各人家境贫困，年轻的心从没有失去对将来的幻想与憧憬。阿B因要与女友小珍（袁洁莹饰）结婚，众人各出奇谋为阿B筹钱。辉仔借来高利贷途中被劫，辉仔负伤往婚礼。及后，阿B与辉仔往复仇而误杀废强，细荣众人遂到越南逃亡。其时西贡市长外弛内张，对众人来说便是炼狱，更遇上越共刺杀越南政要，细荣遂决定要拼死捞一笔钱才离开越南。细荣远亲中、法混血儿阿乐（任达华饰）是职业杀手，阿乐得悉越南恶霸梁源盛在夜总会有黄金交易，遂与一众里应外合，激战后把黄金抢走，阿B为拯救一位香港女歌星陈秀青而险丧命……吴宇森巅峰时期的野心力作，对情与义的探讨有其深邃之处，动作场面火爆亮眼。是港片不可多得的佳作。©豆瓣', '梁朝伟', '吴宇森', 8.2, 48443, 'tt0099426', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1329107141.jpg', 0.4, 1.8, 17.5, 48.8, 31.6, '-0.071678,-0.005882,-0.569697,0.349464,0.354864,-0.394280,0.456962,0.181436,-0.156585,-0.224078,0.252975,0.350583,-0.028454,-0.154897,0.158594,-0.272744,-0.232490,-0.605076,-0.058216,-0.101316,-0.034084,-0.194443,-0.143453,0.045758,-0.457922,-0.127965,0.532807,0.102694,-0.306029,0.394774,0.531048,0.346451,-0.150269,0.199191,-0.214852,-0.062109,-0.082229,0.154286,-0.620713,0.167895,-0.121871,-0.196671,-0.390382,-0.088573,0.219881,0.193783,0.710135,-0.120691,0.125986,-0.234405,0.230848,-0.064502,-0.020878,-0.033487,0.251472,0.108194,0.070839,-0.003347,-0.215787,-0.042810,0.232450,-0.069430,-0.434585,0.010991,0.322638,0.010189,-0.468959,0.019810,-0.138872,-0.045308,0.220973,-0.119033,0.121867,0.326084,0.172850,0.147246,0.280836,0.180886,-0.287482,0.303830,0.731791,0.032013,0.204331,-0.057876,0.047796,-0.711131,0.203882,-0.051173,-0.174589,0.005319,0.410776,-0.225604,0.229959,0.414786,-0.432418,-0.175267,-0.145938,0.224176,0.065150,0.052364,0.082634,-0.474010,-0.166438,-0.331653,-0.052645,0.220533,0.332048,-0.030050,0.579754,-0.477037,0.079951,0.153237,0.357994,-0.483881,0.606752,0.012827,0.104101,-0.385049,-0.020391,0.051009,0.134071,-0.107698,0.012734,-0.011817,-0.171047,-0.057372,-0.135082,0.162320', '1300553', '1308201', '4301278', '2080130');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295363', '红潮风暴', '剧情', '内容描述苏联发生政变时，叛变者控制了一个核子飞弹基地，威胁要攻击美国。美国政府急命阿拉巴马号核子潜艇准备反攻，但就在是否要下达攻击令的关键时刻，潜艇的通讯系统发生故障，无法判断攻击令的真伪。哈克曼饰演的潜艇指挥官决定发射，但新来的副官华盛顿却认为事关重大，应确定讯息再说，不惜为此发动兵变囚禁上司。', '丹泽尔·华盛顿', '托尼·斯科特', 8, 12069, 'tt0112740', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358217779.jpg', 0.4, 1.2, 19.7, 53.3, 25.4, '0.014692,0.108970,-0.390825,0.834178,0.249928,0.474910,0.160221,-0.195301,-0.188324,-0.316610,0.422008,0.312319,0.075370,-0.608935,0.130407,-0.213664,-0.329315,-0.235209,0.267164,-0.015147,-0.321897,-0.720479,-0.002210,-0.557329,0.370769,-0.654723,0.765325,0.184825,-0.694326,-0.121907,0.131200,0.431074,-0.056603,0.634146,0.317846,-0.344784,0.062516,-0.236893,-0.280794,0.406254,-0.088415,-0.225798,0.249511,0.472479,0.177333,0.699682,0.483937,-0.362307,-0.399054,-0.287098,0.251046,-0.294387,0.363533,0.157082,0.484025,0.356466,-0.391589,0.186827,-0.100628,0.104891,-0.034992,0.463958,-0.746773,-0.086453,0.029154,-0.215487,0.010018,-0.395809,-0.804029,0.720691,-0.181878,-0.137398,0.216781,0.759892,0.411404,-0.062211,-0.296249,0.288674,-0.355050,-0.158611,0.524880,-0.630512,-0.697486,0.195008,0.041577,-0.286505,-0.114942,-0.212444,-0.231643,0.078964,-0.022059,0.466498,-0.328058,0.211182,-0.042191,-0.371382,-0.699779,-0.308878,-0.017809,-0.372395,-0.051451,-1.003354,0.068069,0.157868,-0.044863,0.273602,0.109776,0.307436,0.426313,-0.594286,-0.086426,0.667536,0.297002,-0.720301,0.308672,0.583167,-0.229484,-0.466385,0.514713,0.036457,0.298699,0.287361,-0.267983,-0.044392,0.205127,-0.605224,0.051279,-0.157321', '1293830', '2369613', '2973528', '1297753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295374', '金玉满堂', '喜剧', '赵港生（张国荣饰）因厌烦黑社会生活，欲金盆洗手后去加拿大追寻偶像山口百惠，而他选择的移民途径竟是——参加加拿大酒店的厨师考试，丝毫不懂厨艺的他最终因作弊暴露而惨败。某日，赵港生在酒楼遇见了厨艺大师龙昆宝（赵文卓饰），龙昆宝指点他去找自己的旧识满汉楼的欧老板（罗家英饰）学习，不想欧老板竟对他百般刁难，最终将其扫地出门。其间，港生和欧老板的女儿嘉惠（袁咏仪饰）倒是在不经意间擦出了花火。欧老板师承中国著名大宴满汉全席之赵派，某日，牛派的继承人黄荣找上门来挑战，后来又使诡计挖走了他手下的所有师傅。这时，唯有港生挺身而出，和嘉惠一起寻找会做满汉全席的高人，那就是五年前莫名隐退厨艺界的廖杰（钟镇涛饰）。©豆瓣', '张国荣', '徐克', 8.1, 89567, 'tt0113475', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2358564763.jpg', 0.2, 1.2, 20.3, 48.2, 30, '0.022428,0.073222,-0.488343,0.498774,-0.112221,-0.348581,0.364260,0.348576,-0.416453,-0.330911,0.108311,0.717941,-0.114837,0.270067,0.330098,-0.018495,0.031200,-0.616836,-0.015148,-0.226009,-0.142024,-0.195321,-0.003883,-0.264298,-0.196738,0.092052,0.163518,0.088299,-0.392064,0.362974,0.556352,0.257202,-0.008143,0.419101,-0.089886,-0.018902,0.092188,0.206043,-0.346920,0.032226,0.218623,-0.416635,-0.189089,-0.024631,0.016593,0.348442,0.345046,0.257554,0.002907,-0.209474,0.399486,-0.215761,0.043105,-0.178280,0.350084,-0.109046,0.096885,0.095723,0.056711,-0.101613,-0.033235,-0.058004,-0.544782,-0.022898,0.302076,-0.132532,-0.541965,0.324273,0.073719,0.077237,-0.143342,-0.400185,0.223984,0.208687,0.244363,0.005391,0.191481,0.079182,-0.424287,0.540527,0.488143,0.000662,0.397532,0.161559,-0.089967,-0.360340,0.257270,-0.337735,-0.327864,0.038211,0.197887,-0.076850,0.072583,-0.023994,-0.307592,-0.268054,-0.120234,0.030811,0.153588,-0.292490,0.137467,-0.636846,0.042059,-0.309022,-0.084189,-0.053568,0.145573,-0.249093,0.491544,-0.780373,0.081548,0.357885,0.313700,-0.470280,0.817277,0.055405,-0.101405,-0.150720,-0.159234,0.160248,0.106928,0.241937,-0.066277,0.307762,0.350208,-0.106247,-0.164921,0.211818', '4301278', '1302384', '30162520', '1303449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295383', '星际旅行9：起义', '动作', '皮卡特舰长获知百科（Data）中尉在巴库（Baku）星球被掳为人质后立刻率企业号前往营救。当他们来到巴库星球，整个星球上只居住了六百名巴库人，与世隔绝、摒弃科技、崇尚和平，过着纯朴的生活；百科被掳不像是巴库人的作风，想必另有隐情。皮卡特舰长遇到一名叫做安妮的巴库女子，经由她得知巴库人虽然看起来年轻，星球的原居民巴库其实年龄都已经超过三百岁了。面临老化的索纳（Sons）人，发现巴库人长生不老的秘诀再于巴库星球外围的特殊放射线能不断的重组基因结构。如今巴库人要遭受灭种的威胁……来自外层空间的索纳人联结星际联盟，根据原有的巴库人村落拟造了一个一模一样的环境，预谋将巴库人迁徙到这个虚拟村落，企图独享青春泉源。瑟纳人首领鲁阿弗假藉文化访查之名率众进入巴库星球，企图赶走巴库人，占领巴库星球。皮卡特舰长将所获知的情报呈报杜尔迪司令，却发现司令与星际联邦总部早已知情，并暗中参与这项阴谋。杜尔迪不理会皮卡特的抗议，下令企业号立即撤返，不得干预。毕卡舰长面临了关键性的一刻，若他服从命令就违背了当初加入星际舰队时曾立下的誓言，反之，若采取行动，他则必须放弃事业、组员、企业号、一切！来投入这场天堂之战。', '帕特里克·斯图尔特', '乔纳森·弗雷克斯', 7.4, 6183, 'tt0120844', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209408899.jpg', 0.7, 3.3, 38.8, 42, 15.2, '0.040475,0.243532,-0.703598,0.490984,-0.201295,0.134948,0.313646,0.191095,-0.570016,0.105817,0.060246,0.607809,0.214224,-0.218324,0.475182,0.213017,-0.558703,-0.392874,-0.117361,-0.261633,-0.301593,-0.610114,-0.123051,-0.355477,0.124480,-0.654251,0.697371,0.178249,-0.266773,0.058428,-0.193753,0.324675,-0.126608,0.552595,-0.018925,-0.101841,0.251517,-0.419035,-0.362991,0.153811,-0.637647,0.166350,0.101499,0.095122,-0.091942,0.369466,0.433369,-0.366940,0.129440,-0.483218,0.087007,-0.106843,0.094333,-0.115250,0.559299,-0.093228,-0.122630,0.343553,0.007535,0.160757,0.159940,-0.151946,-0.665569,-0.122484,0.079233,0.184217,-0.262567,0.251845,-0.302901,0.083824,-0.377228,-0.091404,0.191039,0.525889,0.235166,0.198412,0.086394,0.145791,-0.593017,-0.061940,0.698932,-0.146097,-0.351514,-0.116982,0.146912,-0.532128,-0.075359,-0.353239,-0.185868,0.072808,0.162311,0.041763,-0.284981,0.373572,-0.674689,0.122306,-0.456332,-0.531008,0.194383,-0.260018,-0.108776,-0.611918,-0.092245,0.068502,-0.122326,0.233537,0.187455,0.009421,0.744023,-0.608563,0.147952,0.568310,0.480461,-0.571983,0.487055,0.052636,0.252860,-0.567618,-0.085915,0.503937,0.283412,0.680521,-0.088686,0.057555,-0.002432,-0.293625,-0.059296,0.186044', '6007281', '26290398', '6532822', '1849026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295384', '星河战队', '动作', '高中生瑞科（卡斯帕•凡•迪恩 Casper Van Dien 饰）毕业后，在女友卡门（丹妮丝•理查兹 Denise Richards 饰）的鼓动下，违背了父亲的意志，加入了机械化步兵学院，卡门亦加入了海军学院。在他们参加训练不久后，地球遭到了来自外星球的昆虫袭击。瑞科的亲人均惨遭杀害，卡门将拍摄到的影像传送给了瑞科。悲愤交加的瑞科率领部下投入到了对抗外星昆虫的战斗中。然而，军队低估了这些昆虫的实力。在一次遭遇战中，10万军队惨遭杀戮，只剩瑞科、卡门等几人侥幸逃生。瑞科亲眼目睹了恐怖的杀戮场面，意外获知了这些昆虫变得如此聪明、强大的秘密。瑞科意识到必须制造更先进的武器才能对付这些昆虫，人类的反击开始了！©豆瓣', '卡斯帕·范·迪恩', '保罗·范霍文', 7.9, 97959, 'tt0120201', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512733819.jpg', 0.5, 2.3, 23.7, 48.7, 24.9, '0.411580,0.127601,-0.695568,0.566692,-0.097872,-0.131286,0.451353,0.027024,-0.541910,-0.012754,0.373954,0.505602,0.033793,-0.015723,0.217717,-0.268834,-0.166826,-0.321286,-0.182817,-0.232390,-0.380339,-0.429751,-0.487813,-0.333526,0.051665,-0.761342,0.601882,0.232339,-0.423032,0.493852,-0.060677,0.192765,-0.025281,0.445768,0.009564,-0.069215,0.228695,-0.082602,-0.142095,0.250810,-0.290806,-0.093342,-0.074302,0.215037,0.039496,0.280974,0.841624,-0.453648,0.141657,-0.329249,0.243493,-0.293031,0.014969,0.125045,0.628446,0.151096,0.005438,0.051329,0.085125,0.443180,-0.240299,0.199704,-0.892471,-0.089440,-0.158980,0.034312,-0.758355,0.292721,-0.171051,0.046542,0.148314,-0.107654,0.202441,0.631141,0.071778,0.221173,-0.037662,-0.091023,-0.492093,0.035542,0.721712,-0.447152,-0.391788,0.116357,-0.024473,-0.646667,-0.303257,-0.450747,-0.136797,0.100481,0.396681,0.178526,-0.164029,0.455018,-0.864861,-0.130703,-0.310322,-0.405865,-0.200371,-0.284558,-0.089083,-0.822637,-0.059711,-0.088006,-0.318908,0.251378,0.181139,-0.082640,0.874273,-0.690964,0.151519,0.612410,0.404325,-0.331506,0.218171,-0.178808,0.147329,0.089341,0.068801,0.398160,0.093534,0.618370,0.270103,0.542408,0.127792,-0.305832,-0.238184,0.414991', '1292680', '25774050', '1292829', '11810348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295387', '史前巨鳄', '喜剧', '一起神秘的死亡时间吸引了古生物学家凯丽（布里吉特·芳达 Bridget Fonda 饰）的注意，为了了解事件的真相，凯丽千里迢迢的赶到了案发地——一个古老的湖泊，而之后发生的事情更让凯丽确信，在这平静的湖面下，隐藏了什么可怕的东西。凯丽的猜测在小镇上引起了轰动，有些人信以为真，另一些人则不以为然。就在舆论的热度到达最顶峰之时，一个游客被不明物体拖入湖中的惨剧让所有人都意识到，事情严重了。凯丽和管理员杰克（比尔·普尔曼 Bill Pullman 饰），警长汉克（布莱丹·格里森 Brendan Gleeson 饰）等人围绕着古湖展开了调查，令人震惊的是，在湖底，他们发现了一只异常凶猛巨大的史前巨鳄。©豆瓣', '比尔·普尔曼', '史蒂夫·迈纳', 5.9, 4794, 'tt0139414', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2387041328.jpg', 4.1, 19.6, 57, 14.6, 4.6, '0.449388,-0.049543,-0.924968,0.467880,0.007346,0.210617,1.135524,0.157066,-0.738615,-0.054877,0.477547,0.649146,-0.568642,-0.151676,0.264313,0.277406,-0.463057,-0.469742,-0.013555,-0.323093,-0.468804,-0.485372,-0.549772,-0.267773,0.085070,-0.329734,0.156185,0.329742,-0.191196,0.534876,0.002290,0.207478,-0.189556,0.702440,0.061730,0.152266,0.192651,-0.107263,0.075915,0.160730,0.050526,-0.276069,-0.119743,0.481735,-0.208616,0.347923,0.661221,-0.286687,-0.352903,0.181652,0.302906,-0.402069,0.131938,0.222167,0.502006,-0.134273,-0.052788,0.091370,-0.473252,0.001875,0.273455,0.317454,-0.802951,0.247076,-0.147074,0.691185,-0.573194,0.447743,-0.102368,-0.303926,0.207499,-0.405959,0.304608,0.368274,0.067131,0.246152,-0.000307,-0.180708,-0.394031,-0.075044,0.651969,-0.027544,-0.253187,0.247111,-0.202405,-0.503129,-0.322588,0.031587,-0.136406,-0.046008,0.538858,0.251180,-0.287779,0.530203,-0.622112,-0.067935,-0.279921,-0.477464,-0.362397,-0.268713,-0.564742,-0.588354,-0.229291,-0.309767,-0.283014,-0.011478,-0.133669,-0.133871,0.665636,-0.615507,0.207812,0.763261,0.207366,-0.090686,0.516550,-0.325504,0.029881,-0.115064,-0.204723,-0.007825,0.101185,0.525345,0.200052,0.505099,-0.094063,-0.440808,-0.374432,0.448990', '20451118', '3011051', '3005387', '1297996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295399', '七武士', '剧情', '日本战国时代，一小山村面临着山贼的威胁，为了保护秋天的收成，村中长老决定让去请武士来保护村子安全，但只能拿出的报酬是一天三顿的白米饭。在城里，他们遭到了武士白眼甚至被打。直到勘兵卫（志村乔饰）的出现，他现今已沦为浪人，几经考虑最后答应了。他对农民说至少需要七名武士，于是久藏（宫口精二饰）、胜四郎（木村功饰）、五郎（稻叶义男饰）、七郎（加东大介饰）、平八（千秋实饰）和菊千代（三船敏郎饰）等六人也加入了队伍，七个人肩负保卫村子的任务。整个防御准备的过程中，武士与农民间发生许多摩擦也闹出不少笑话。而在一次偷袭行动中，有武士为救农民被火枪打死，很快山贼的反扑随之而来，一场恶战即将开始。©豆瓣', '三船敏郎', '黑泽明', 9.3, 182516, 'tt0047478', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2215886505.jpg', 0.2, 0.4, 4.6, 24.1, 70.7, '0.018262,-0.257571,-0.357482,0.105633,-0.153553,-0.251694,0.581604,0.171416,-0.441242,-0.145795,0.454047,0.561297,0.092303,-0.166019,0.323093,-0.507321,-0.005511,-0.439558,-0.062510,-0.213638,-0.407218,-0.161497,0.209470,-0.249418,-0.363666,-0.319999,0.501718,0.360626,-0.046462,0.328897,0.063505,0.201024,-0.025380,0.381964,0.084677,0.017499,0.038985,-0.480619,-0.255066,0.465299,-0.314292,-0.228776,-0.262017,0.122389,0.061078,0.515008,0.668375,-0.239134,-0.051778,-0.282633,-0.085834,-0.302726,-0.312576,0.239683,0.700948,0.035184,0.158231,0.196748,0.063346,-0.107177,-0.084655,-0.075217,-0.575255,0.133243,0.241161,-0.062118,-0.650692,0.408448,0.126770,0.062727,0.131038,-0.190793,0.190356,0.563928,0.301418,0.117914,-0.192124,0.161713,-0.604644,-0.004824,0.826846,-0.409993,0.128759,-0.113446,-0.021033,-0.309322,-0.009447,-0.484377,-0.155816,0.038946,0.135748,-0.066151,-0.205494,-0.100652,-0.559594,0.073452,-0.296633,-0.400623,0.136535,-0.195727,-0.186620,-0.462035,0.312397,-0.092164,-0.222107,0.412026,0.430041,0.169726,0.802416,-0.681307,0.031942,0.540456,0.543712,-0.134752,0.139048,0.010753,0.235837,0.176751,0.132967,-0.374257,0.194047,0.523505,0.505269,0.203169,-0.120677,-0.246079,0.020070,0.063811', '25721544', '1306530', '1304920', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295409', '纵横四海', '剧情', '砵仔糕（周润发饰）、阿占（张国荣饰）和红豆（锺楚红饰）均是孤儿，在养父（曾江饰）栽培下成为国际大盗。长大后成了帮他赚钱的艺术品大盗，而三人同时又认了警察（朱江饰）为干爹。法国巴黎博物馆内，名画《赫林之女仆》被人盗走。与此同时，阿海、阿占和红豆三人以敏捷身手盗得另一幅名画，在与法国大哥交易时得知名画《赫林之女仆》在妖气重重的古堡内，他们在曾江安排下成功地盗取此画之后，反被集团原凶曾江与法国大哥合谋设下陷阱，派人追杀灭口。阿海驾车与杀手快艇相撞……三人失散，数年后，他们在香港重聚，阿海“瘫痪”住在朱江家里，阿占和红豆已经结婚了。曾江又逼他们去偷画……©豆瓣', '周润发', '吴宇森', 8.8, 392317, 'tt0101020', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2597918718.jpg', 0.2, 0.7, 9.2, 38.2, 51.7, '-0.104145,-0.122449,-0.523758,0.359345,0.031140,-0.276719,0.526000,0.260043,-0.307179,-0.113918,0.258961,0.816974,-0.147711,0.122024,0.247665,0.092586,-0.434152,-0.785290,-0.134151,-0.411038,-0.216418,-0.257540,-0.074526,-0.054734,0.007839,0.059362,0.335632,0.017304,0.021511,0.397658,0.192210,0.290037,-0.629708,0.224964,-0.186523,0.358289,0.222508,-0.202757,-0.515049,0.240397,-0.137565,-0.321915,0.079998,-0.258595,0.008914,0.083945,0.616684,-0.054271,0.135872,-0.334019,-0.096613,-0.040277,0.029267,-0.039935,0.347686,-0.033989,0.400083,0.326931,-0.416078,-0.193696,0.232161,-0.039701,-0.453433,0.143972,0.327509,-0.160752,-0.834634,0.342121,-0.219982,0.209850,-0.029204,-0.378038,0.268129,0.338901,0.208686,0.218685,0.134285,0.004584,-0.550196,0.180216,0.507487,0.023807,0.226415,-0.004598,0.330339,-0.308339,0.049962,-0.254261,0.050014,-0.044176,0.578491,-0.102494,0.043925,0.039539,-0.534773,-0.264297,-0.187939,0.222593,-0.050116,-0.309072,-0.075082,-0.777753,0.004079,-0.212721,-0.240796,0.075174,0.137145,-0.186004,0.326072,-0.652502,0.242076,0.358428,0.405168,-0.403386,0.574200,-0.258946,0.059762,-0.168090,-0.120206,-0.219848,0.343453,0.437630,0.395885,0.270206,-0.027598,-0.112268,-0.466538,-0.085998', '11541282', '1306209', '1309069', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295416', '无因的反叛', '剧情', 'Jim（詹姆斯·迪恩 James Dean 饰）因为在学校里无法与其他同学共融，迫使他的父母只能多次搬家，这一次他们来到了洛杉矶。在洛杉矶的一所高中里，他仍旧遭到了同学的排斥，但认识了他心爱的女生Judy（娜塔利·伍德 Natalie Wood 饰）；交到了他真正的朋友 Plato（萨尔·米涅奥 Sal Mineo 饰）。在Jim和当地小混混头目、也是Judy的前男友Buzz一系列的纠纷中，两人最终决定以赛车来定胜负。而在比赛中，Buzz不幸坠入悬崖身亡。Buzz的兄弟们试图找Jim报仇，在两方的对抗中，Plato被警察意外枪杀，使这部影片留下了一个悲剧性的结尾。而Jim和Judy的命运又将何去何从？©豆瓣', '詹姆斯·迪恩', '尼古拉斯·雷', 8, 14473, 'tt0048545', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1332978764.jpg', 0.5, 1.6, 20.4, 51.4, 26.1, '0.587260,-0.091265,-0.687187,0.618354,-0.165840,-0.428921,0.683406,-0.019744,-0.540025,-0.096281,0.221522,1.083345,-0.092873,0.259575,0.319486,-0.226335,-0.224182,-0.952909,0.021454,-0.253128,-0.399421,-0.534981,-0.370330,-0.223382,-0.180908,0.025693,0.672006,0.190057,-0.088938,0.624939,0.372667,0.356244,-0.174643,0.485803,-0.057718,0.156715,0.044957,-0.148463,-0.305711,0.396415,0.200230,-0.414504,-0.206145,0.324023,0.109274,0.649437,0.874046,-0.426635,0.008462,0.126305,0.364625,-0.477126,-0.078892,0.438657,0.355586,0.143589,0.292923,0.243256,-0.285088,0.115755,0.150783,0.039489,-0.699707,-0.022323,0.114161,0.146872,-0.763543,0.932046,-0.024881,-0.085340,0.109403,-0.130778,0.336446,0.358061,0.328906,0.325705,-0.224290,-0.395772,-0.365739,0.075550,0.975487,-0.056832,-0.173533,0.108241,-0.136058,-0.382993,-0.146865,-0.267344,-0.578649,0.034551,0.580320,-0.020032,-0.232432,0.149112,-0.708482,-0.041608,-0.276265,-0.183028,-0.375825,-0.425063,0.093433,-0.602485,-0.049036,-0.428734,-0.267851,0.120756,-0.103511,-0.065035,0.653338,-1.070996,0.052716,0.603131,0.481645,-0.370422,0.757037,0.238471,0.436989,-0.103179,-0.059658,0.018097,0.093179,0.257695,0.251292,0.401231,0.056774,-0.089289,-0.493176,0.436551', '35030151', '1292219', '30345227', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295432', '亲爱的，我把孩子放大了', '喜剧', '三年后，科学家韦恩·斯萨林斯基（里克·莫拉尼斯Rick Moranis饰）一家人搬到内华达州的滨海社区，继续他的电磁分子研究。三年前，他曾经因为操作不当把孩子们的身体“缩小”了，闹出了一连串啼笑皆非的故事。而这次，糊涂韦恩仍旧重蹈覆辙，大摆乌龙。在一次实验过程中，只有两岁的小儿子亚当，居然被“变大”了。小亚当只要一接触电流，身体就会不停的长大。一家人展开了挽救行动，可这根本跟不上小亚当的变大速度。转眼间，小亚当已经长成足有3500公分的巨婴。而更麻烦的是，小亚当居然跑上了街头，朝着赌城拉斯维加斯走去，于是他的奇妙大冒险就这样开始了。小亚当能否缩小回正常婴儿的大小，乌龙科学家韦恩又是否能再次摆脱囧境，一家团聚呢？©豆瓣', '里克·莫拉尼斯', '兰德尔·克莱泽', 7, 5691, 'tt0104437', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508669541.jpg', 0.5, 5.3, 47.8, 35, 11.3, '0.243378,0.066049,-0.688673,0.215558,-0.183228,-0.532475,0.610113,0.210843,-0.456566,-0.015256,0.093018,0.670665,-0.519629,0.346150,-0.086912,0.135029,-0.283408,-0.529636,-0.022133,-0.213666,-0.440128,-0.436521,-0.225967,-0.260690,0.092233,-0.053086,0.155318,0.011840,-0.188742,0.059428,0.191079,-0.362753,0.163773,0.173957,-0.311391,0.190975,-0.026690,0.059778,0.174688,0.110142,0.400920,-0.131765,0.050407,-0.127989,0.230645,0.270916,0.661918,-0.300117,-0.023830,-0.340877,0.256928,-0.059242,-0.234410,0.080450,0.202928,0.082126,0.268090,-0.204205,-0.100402,-0.051206,0.189158,-0.387811,-0.384797,0.485666,-0.382235,0.006682,-0.571379,0.026917,-0.024871,-0.144032,0.137742,-0.501324,-0.139405,0.604016,0.163962,0.316218,-0.451324,0.086811,-0.340721,-0.082151,0.557731,0.012525,-0.552203,0.342986,0.155003,-0.422778,-0.337483,-0.301345,-0.072596,-0.146245,0.412145,0.000917,-0.288186,0.627380,-0.421027,0.055017,-0.583151,-0.224279,-0.160870,-0.084464,-0.205726,-0.385528,0.125629,-0.269296,-0.110542,0.246513,0.112231,-0.226083,0.695443,-0.398874,0.263557,0.493788,0.351658,-0.172258,0.344269,-0.219279,0.125969,-0.085691,0.054183,0.142427,-0.200717,0.527536,0.448827,0.403660,-0.065038,-0.266116,-0.475987,0.473947', '21619567', '30162520', '1458900', '4724586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295437', '春天不是读书天', '喜剧', '芝加哥又迎来了晴朗的一天，逃学高手菲利斯（马修•布罗德里克 Matthew Broderick 饰）自然不会在这天选择枯燥的测验，他伪装病重骗过父母，令同校的姐姐珍妮徒劳嫉妒。菲利斯找来好友凯伦（阿兰•卢克 Alan Ruck 饰），两人联手骗过训导主任罗宁，驾驶凯伦父亲珍藏的法拉利将菲利斯女友思朗接出学校兜风，菲利斯娴熟的电话骗术在凯伦和思朗的配合下将众人戏弄的团团乱转，学生们反而受他的影响颇深，在校内发起给菲利斯谎称的手术捐款。罗宁不堪忍受菲利斯一次次得欺骗，“微服私访”去校外希望能将菲利斯捉个正形，而在城中四处游荡的菲利斯三人则展开了一场隐藏自己身份的冒险……©豆瓣', '马修·布罗德里克', '约翰·休斯', 8, 36704, 'tt0091042', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1382118133.jpg', 0.5, 2.1, 21.1, 47.4, 28.9, '0.378107,-0.129608,-0.416245,0.482655,-0.207780,-0.168559,0.435119,0.136458,-0.393475,-0.073170,0.498221,0.527736,-0.217309,0.289422,0.306924,-0.136685,-0.449536,-0.545490,0.119237,-0.087218,-0.028915,-0.504692,-0.230463,-0.188181,-0.023221,-0.357904,0.272663,-0.202879,-0.013930,0.555624,0.144812,0.149788,-0.029609,0.289668,0.019507,0.020505,0.059047,-0.041757,-0.066104,0.255183,0.160985,-0.270822,-0.269889,0.172658,0.309933,0.185324,0.769712,0.007361,0.168039,-0.064019,0.246177,-0.363713,0.198381,0.220979,0.177178,-0.002540,0.134423,0.001545,-0.212145,0.165537,0.141971,0.245417,-0.539773,0.194154,0.144950,-0.024575,-0.600866,0.425974,-0.216422,-0.084986,0.052172,-0.394532,-0.001848,0.239281,0.010408,0.285161,-0.041071,0.041377,-0.315176,0.077565,0.444037,-0.203788,0.016715,-0.081376,-0.138961,0.050213,0.137972,-0.184583,-0.721331,-0.258625,0.407210,-0.195747,-0.150930,0.371537,-0.437652,-0.299699,-0.561237,-0.197689,-0.067745,-0.344329,-0.124180,-0.764733,0.207705,-0.149656,-0.248077,-0.014650,0.025025,-0.238258,0.468359,-0.781738,0.211488,0.596954,0.204760,-0.343588,0.391661,0.181705,0.145109,0.051514,-0.272000,0.091428,0.224357,0.472579,0.332250,0.392637,0.206699,0.016853,-0.337685,0.354997', '3804656', '3178770', '3811356', '30205667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295451', '第三人', '悬疑', '二战后，美国作家马丁（约瑟夫•科顿 Joseph Cotten 饰）应好友哈里（奥逊•威尔斯 Orson Welles 饰）邀请到维也纳工作，岂料刚到达目的地就传来了哈里车祸身亡的消息。哈里葬礼上，马丁遇到了当地军官卡洛维，卡洛维很不客气的请他马上离开维也纳。马丁没有理会，决心留下调查出好友死亡的真相。马丁找到哈里的女友斯科姆特小姐（阿莉达•瓦莉 Alida Valli 饰）一起调查事件的真相。随着调查的深入，他们发现内幕越加扑朔迷离，首先是他们的房东遇害，接着马丁自己发现被人跟踪，而且他查出哈里死的时候还有个第三人在场。于是，一切关键就在于找出这个神秘的第三人。©豆瓣', '约瑟夫·科顿', '卡罗尔·里德', 8.2, 20877, 'tt0041959', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193745066.jpg', 0.4, 1.4, 16.9, 49.7, 31.6, '0.696766,-0.158491,-0.876133,0.299015,-0.099257,-0.391535,0.508206,-0.103135,-0.468518,-0.518126,0.155561,0.761562,-0.368540,-0.012174,0.447497,0.164589,-0.623933,-0.454660,0.135309,-0.236635,-0.426201,-0.779115,-0.032903,-0.433343,0.114778,-0.057439,0.175207,0.158974,0.028607,0.486463,0.153686,0.624490,-0.033508,0.472734,0.055095,0.334658,0.372718,-0.236108,-0.251831,0.290565,0.081281,-0.080922,0.019717,0.286017,0.063996,0.543896,0.117332,-0.205523,0.015367,0.189479,0.353365,-0.441429,0.111276,0.054990,0.331087,-0.113234,-0.021457,0.517671,-0.372692,-0.118035,-0.258852,0.156526,-0.368413,0.348787,-0.037436,0.571793,-0.304195,-0.147485,-0.454174,0.119339,0.199755,-0.346319,0.427973,0.475940,0.132264,-0.072709,0.254914,-0.007589,-0.617708,-0.064122,0.661790,-0.232992,0.154433,0.064403,0.069095,-0.433102,0.198706,-0.080082,0.066114,0.283741,0.404464,0.248833,-0.095754,0.035519,-0.225965,-0.496236,-0.373142,-0.250495,-0.117732,-0.095584,-0.168788,-0.858803,-0.216777,0.072141,-0.313489,-0.078976,-0.166651,-0.230006,0.380427,-0.667945,0.257629,0.570134,0.259179,-0.338450,0.455888,-0.039800,0.037715,-0.371385,0.127689,0.142098,0.488836,0.093987,-0.045960,0.243095,0.154049,-0.554695,-0.217039,0.097820', '3036464', '2357711', '1293145', '3285622');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295452', '子弹横飞百老汇', '喜剧', '长久以来，剧作家大卫（约翰·库萨克 John Cusack 饰）都过着郁郁不得志的生活，艺术家特有的清高让他对如今腐败混乱的话剧界充满了失望之情。为了讨好情妇奥利芙（詹妮弗·提莉 Jennifer Tilly 饰），黑帮大佬看中了名不见经传的大卫的剧本想要投资，作为前提条件 ，大卫必须让奥利芙饰演主角。虽然奥利芙唠叨的个性和蹩脚的演技让大卫深感抓狂，但在利益面前，他痛苦的屈服了。就这样，一个奇怪的剧组诞生了。剧本的漏洞，女演员们之间的矛盾，男主演日益肥胖的身材都让大卫感到绝望，但令他惊奇的是，一直监视着奥利芙的保镖契奇（查兹·帕尔明特瑞 Chazz Palminteri 饰）在无意中展现了过人的编剧才能。在契奇的帮助下，被改写的剧本居然获得了盛大的成功，与此同时，契奇对由自己操刀的剧本展现出的病态执着和剧组里混乱的男女关系让大卫陷入了另一个困境……', '约翰·库萨克', '伍迪·艾伦', 8.4, 21107, 'tt0109348', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p946721980.jpg', 0.3, 1, 12.8, 50, 36, '0.183252,-0.067737,-0.669959,0.739806,-0.101470,-0.346923,0.881555,0.375306,-0.530157,0.005023,0.365862,0.766654,-0.227389,0.062898,0.321239,0.038770,-0.473967,-0.631445,-0.219270,-0.159847,-0.104412,-0.541331,-0.418069,-0.232637,-0.298900,-0.476258,0.598365,-0.163658,-0.203579,0.648488,0.535544,0.367428,0.081742,0.430022,0.128272,0.132398,0.310434,-0.269897,-0.330495,0.034710,0.278169,0.006543,-0.284356,0.544339,-0.132397,0.415429,0.590661,-0.117772,-0.163064,0.108645,0.400864,-0.223827,-0.049188,0.215390,-0.080599,-0.061128,0.240927,0.148466,-0.375755,0.171668,0.131362,0.021181,-1.189229,0.253752,0.324279,0.205279,-0.740252,0.530529,-0.089617,-0.216712,0.106369,-0.103038,0.083467,0.132960,0.311765,0.535455,-0.109233,0.243588,-0.382311,0.206659,0.342561,0.138037,-0.460246,0.258823,-0.402047,-0.319967,-0.117303,-0.435187,-0.800997,0.019994,0.316578,-0.041230,-0.145481,0.206869,-0.673540,0.042053,-0.316554,-0.103141,-0.159794,-0.517521,-0.133570,-0.541003,-0.441502,-0.288341,-0.397147,-0.309742,0.025383,-0.247209,0.933964,-0.708435,0.092821,0.666474,0.202174,-0.244348,0.591718,0.327157,0.015784,-0.151120,-0.541409,0.228450,-0.046750,0.109866,0.108850,0.541256,-0.016779,-0.384745,-0.361677,0.635250', '1793491', '24284209', 