INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295460', '性爱宝典', '喜剧', '本片由章回形式提出七个敏感又尖锐的性话题：《春药管用么？》导演伍迪·艾伦Woody Allen亲自扮演佞人小丑，迷奸皇后未果而断送性命；《什么是兽交？》中事业有成的医生爱上一只母羊黛茜；《女人为何性冷淡》讲述性冷淡的新婚妻子只有在公众场合才会性欲爆发；《异装癖者是同性恋 么？》里结发夫妻访友，丈夫却偷穿女性服装，上演一场暴露在大庭广众下的尴尬闹剧；第五段《什么是性异常？》设定在公开各自性怪癖的电视脱口秀节目中；其后的《性学博士可信么？》伍迪·艾伦重新登场，阻止了扬言改造人类性器官的性学教授的疯狂实验；最后的故事《射精是怎么回事？》更是把做爱的全过程演绎成如操纵机器般步步可循。本片根据大卫·鲁本医生《你想知道的性问题》一书改编。©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 8, 20653, 'tt0068555', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506003739.jpg', 0.6, 2.1, 20.7, 50.5, 26, '0.209783,-0.248733,-0.144743,0.415254,-0.266519,0.081162,0.341871,-0.049659,-0.142455,-0.177806,0.342918,0.486882,-0.394955,-0.059712,0.154503,0.023346,-0.099799,-0.496222,0.086455,0.184836,-0.088839,-0.387834,-0.068845,-0.107750,0.161193,-0.271712,0.506877,-0.397927,-0.483799,-0.051887,0.674583,0.238643,-0.203627,0.110167,0.130760,-0.030312,0.018028,-0.094634,-0.201593,0.221122,0.176772,-0.136047,-0.007531,0.125232,-0.225817,0.269644,0.479070,-0.450212,-0.086411,-0.059229,0.776037,-0.135360,-0.143274,0.167072,0.222877,0.131381,0.320440,0.212960,0.208379,0.054222,-0.030285,0.102418,-0.566855,-0.213390,0.132998,0.357463,-0.193014,0.089255,0.012589,-0.063626,0.142416,-0.073098,0.001732,-0.050410,0.520995,0.296948,0.087408,-0.131640,-0.087373,0.252773,0.279936,0.173245,-0.440534,0.496621,-0.106383,-0.385966,0.224846,-0.162544,-0.456373,0.099702,-0.071843,-0.203556,-0.202886,0.359231,-0.376440,-0.068826,-0.144783,0.152245,-0.131288,-0.248348,-0.060950,-0.477370,-0.054418,-0.152062,0.112252,-0.335054,0.144764,-0.272487,0.382089,-0.656240,0.067670,0.541418,-0.026677,-0.543916,0.159641,0.188837,-0.031915,-0.324608,-0.140779,-0.033732,0.078003,-0.029893,-0.124634,0.294301,0.252106,-0.045594,-0.333292,0.389316', '26759820', '35151491', '6844861', '4861408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295467', '罗密欧与朱丽叶', '剧情', '莎士比亚的爱情悲剧《罗密欧与朱丽叶》自1595年问世以来已被搬上银幕12次，其中，1968年由弗兰克·杰弗瑞里导演的版本，自问世以来就一直被视为典范之作。在十五世纪意大利的维罗纳城住有二家声望很高而彼此尖锐对立的望族。他们之间不断的发生血腥的争执。蒙达犹家族的罗密欧（莱昂纳德·怀廷 Leonard Whiting 饰）与卡普雷特家族的朱丽叶(奥丽维娅·赫西 Olivia Hussey 饰)。却一见钟情，私自结婚。朱丽叶的表兄挑衅罗密欧而被误杀，罗密欧因此被流放到城外。为了躲避家人逼婚，朱丽叶在神父的帮助下假死，当罗密欧知道后，赶了回来看到墓穴中熟睡的朱丽叶，绝望之余喝下毒药自杀，当醒来的朱丽叶看到爱人死后也绝望的用短剑刺入了自已的胸部殉情而死。©豆瓣', '莱昂纳德·怀廷', '佛朗哥·泽菲雷里', 8.7, 12049, 'tt0063518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2431798722.jpg', 0.2, 0.7, 10.8, 40.8, 47.5, '0.416691,-0.083300,-0.815943,0.391322,0.272076,-0.216249,0.811578,-0.088072,-0.276399,-0.160379,0.320891,0.952084,-0.314260,0.364692,0.347945,-0.050113,-0.111904,-0.991583,-0.021121,-0.215411,-0.387540,-0.289186,-0.109146,0.074061,-0.284289,-0.339617,0.613816,0.050177,-0.086449,0.568923,0.303231,0.387272,-0.095062,0.316300,0.006270,0.151402,0.035613,0.006188,-0.485515,0.187384,0.097196,-0.270014,-0.172694,-0.015660,-0.112231,0.296761,0.508965,-0.379272,0.153266,-0.128142,0.376391,-0.264244,0.009151,0.167554,0.314790,-0.018041,0.086660,0.370185,-0.236692,-0.099744,0.088068,0.118364,-0.619208,0.215752,0.103833,0.098573,-0.552046,0.503405,0.095212,0.202457,0.267494,-0.206645,0.384522,0.369106,0.353639,0.297536,-0.279411,-0.060674,-0.626555,0.245809,0.629170,-0.260963,-0.289841,0.205449,-0.055626,-0.213928,0.176592,-0.398375,-0.578817,0.012849,0.402492,0.088730,-0.136552,0.480748,-0.428968,-0.220966,-0.250093,0.102640,0.137245,-0.293947,-0.218291,-0.509622,-0.383308,-0.512601,-0.163037,-0.024428,0.197188,-0.208891,0.284756,-0.534437,0.317648,0.298729,0.249948,-0.212305,0.697988,0.126470,-0.087716,0.092762,-0.205330,0.624325,0.189736,0.003279,0.053921,0.159375,0.183725,0.007857,-0.558440,0.475013', '30162520', '1292207', '1301582', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295469', '风云雄霸天下', '剧情', '天下会帮主雄霸（千叶真一饰）欲得天下，请神算泥菩萨（黎耀祥饰）批算，泥菩萨预言他的前半生：“金鳞岂是池中物，一遇风云便化龙。”于是雄霸下令找两名孩童收为徒弟，他们生辰八字要与批示相符，以助雄霸大业。他们就是聂风（郑伊健饰）和步惊云（郭富城饰），但实际上二人都与雄霸有不共戴天之仇。风、云与大师兄秦霜及雄霸女儿孔慈（杨恭如饰演）成长成人，习得一身好武艺，天下会几乎称霸武林。惟有死对头剑圣让雄霸不放心，但“成也风云，败也风云”，雄霸开始以女人为工具对付聂风和步惊云，并造成孔慈之死。逃走的步惊云为楚楚（舒淇饰演）所救回。步惊云、聂风携手对付雄霸……©豆瓣', '郑伊健', '刘伟强', 7, 73432, 'tt0165499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1805065018.jpg', 1, 6.3, 45.2, 35.5, 11.9, '-0.290187,-0.019164,-0.350997,0.453127,0.233545,-0.111849,-0.032575,0.075743,-0.362457,-0.299345,0.096855,0.788397,0.169092,0.099415,0.143719,0.064515,0.191239,-0.899355,-0.255903,0.025242,0.198283,-0.181591,-0.265752,-0.167937,-0.228685,-0.121214,0.676276,0.027755,-0.102956,0.508608,0.308189,-0.015861,-0.158660,0.365699,-0.272761,-0.009105,-0.481916,0.179408,-0.677252,0.399617,-0.142241,-0.093775,-0.270070,0.093019,-0.425421,0.306369,-0.061143,-0.229765,-0.114053,-0.555961,0.130583,-0.456180,-0.075994,-0.149627,0.066537,-0.343258,0.492812,0.599300,0.359118,-0.010513,-0.077168,-0.137192,-0.539796,0.205103,0.512661,-0.015220,-0.489215,0.345062,-0.379124,-0.256995,-0.122359,-0.162731,0.050533,0.056437,0.464929,0.053683,-0.041079,-0.154884,-0.593416,0.071415,0.704764,0.066676,0.269186,-0.040898,0.778082,-0.125544,-0.141200,-0.572841,-0.110736,0.026588,0.205718,0.026732,0.405285,0.492527,-0.073864,-0.128485,-0.125283,0.499431,-0.188725,-0.168776,0.249896,-0.270625,-0.075264,-0.202612,-0.258694,-0.183968,0.536313,-0.738885,0.892534,-0.744140,-0.078180,-0.216239,-0.016237,-0.941727,0.274714,0.173059,0.228141,-0.294974,-0.347217,-0.013937,0.094905,0.167211,0.262299,0.148837,0.071134,-0.018431,-0.098369,-0.019408', '1295987', '4301278', '4723944', '1433736');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295484', '双狙人', '动作', '硬汉托马斯·贝克特（汤姆·贝伦杰 Tom Berenger饰）是一位美国海军陆战队的老兵。然而冷酷无情的贝克特却因为曾经不顾他的战友而臭名昭著。这一次，美国情报部门派遣年轻的神枪手理查德·米勒（比利·赞恩 Billy Zane饰）与贝克特搭档，前往巴拿马完成一次刺杀任务。亦敌亦友的一老一少深入丛林，在远离后方支援的情况下，两人却各怀鬼胎，甚至互相攻击。但随着任务的进行，两人开始慢慢地接纳彼此，在紧要关头互相救助。本部由路易斯·罗沙执导的新派战争片《狙击手》，以美国陆军狙击手特种部队为故事题材，另辟蹊径地聚焦资深狙击手和年轻情报员之间的身份与感情矛盾来制造戏剧张力，加上极富震撼力的视觉效果，营造了一部令人叫绝的丛林动作大戏。©豆瓣', '汤姆·贝伦杰', '路易斯·罗沙', 7.2, 5862, 'tt0108171', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2461473599.jpg', 0.7, 5, 42.1, 39.9, 12.3, '0.239444,-0.368385,-0.697719,0.933580,0.014281,-0.248735,0.648479,-0.077157,-0.476304,-0.141729,0.364397,0.732088,-0.120157,-0.240548,0.268195,-0.331037,-0.397582,-0.758595,-0.212265,-0.009837,-0.162146,-0.517809,-0.494071,-0.408369,0.080957,-0.260635,0.954409,0.101341,-0.436594,0.379508,0.301053,0.363145,-0.243005,0.334625,0.090743,-0.388487,0.466841,-0.151791,-0.598634,0.171527,-0.048948,-0.209927,-0.463660,-0.013881,-0.125017,0.470891,0.696952,-0.338096,-0.021599,-0.089222,0.151527,-0.254473,0.149712,-0.148900,0.306116,0.157407,0.222941,0.271211,0.298593,0.103663,-0.243237,0.002072,-0.682381,0.171764,0.158048,0.100393,-0.394577,0.349804,-0.329516,0.052399,0.100672,-0.318858,0.013886,0.239152,0.584398,0.193231,-0.141537,0.082163,-0.228513,0.046148,0.638206,0.203632,-0.421616,0.136364,-0.173509,-0.631969,-0.086677,-0.261359,-0.295214,-0.100128,0.208564,-0.085147,0.094751,0.226222,-0.631134,0.005644,-0.376324,-0.131857,-0.162431,-0.372037,-0.003997,-1.083652,-0.020749,-0.374235,-0.256968,0.071548,0.127233,-0.069126,0.750610,-0.514346,-0.073390,0.574795,0.026523,-0.358692,0.540374,0.214223,0.043153,-0.330094,-0.230266,0.137559,0.067265,0.032938,0.332769,0.353203,-0.317903,-0.092841,-0.281358,0.242767', '20274039', '2369613', '1322847', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295485', '方世玉续集', '喜剧', '方世玉（李连杰 饰）、雷婷婷（李嘉欣 饰）、陈家洛（郑少秋 饰）一行抵达红花会总舵。红花会事业蒸蒸日上之余，帮内争权夺势的斗争亦未停息，堂主于镇海（计春华 饰）因不满父亲传位陈家洛，几次三番找人行刺未果，方世玉出面当众斥责，两人结下仇怨。陈家洛命世玉等人抢夺扶桑武士护送的一锦盒，虽有苗翠花（萧芳芳 饰）出手相助，但任务失败，期间世玉再次相遇对其芳心暗属的两广总督之女安儿（郭蔼明 饰）。为再次抢夺锦盒，方世玉受命接近安儿，却被两广总督算计，危急时刻安儿救得世玉等人性命。世玉辱命，被陈家洛假意废去武功，锦盒之内的秘密被于镇海发现，李国邦（元奎 饰）身死，陈家洛被囚，于镇海坐上总舵主之位。方世玉伤愈归来，准备不惜代价铲除红花会叛徒。©豆瓣', '李连杰', '元奎', 7.8, 74684, 'tt0106937', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2357210098.jpg', 0.2, 1.3, 26.2, 51.6, 20.7, '-0.211312,0.264570,-0.500030,0.147049,0.240599,-0.150445,0.273969,0.377952,-0.665087,-0.259671,0.493781,0.476876,-0.165607,-0.389501,0.063000,-0.286007,0.171735,-0.585342,-0.060702,-0.038306,-0.105370,-0.177394,-0.173342,-0.082213,-0.390982,-0.084638,0.489267,0.183615,-0.086425,0.669966,0.386648,0.266095,-0.399572,0.371810,0.109861,-0.033402,0.010330,-0.207156,-0.462770,0.222753,-0.190290,-0.467064,-0.149949,0.016219,-0.216994,0.293328,0.490320,-0.124388,0.088742,-0.526869,0.008058,-0.198969,0.093025,0.092446,0.211013,0.156961,-0.038972,0.548484,-0.351650,-0.043554,0.275507,-0.063091,-0.341349,0.145140,0.349963,0.111006,-0.317301,0.251758,-0.338005,0.209789,-0.157450,-0.379516,0.026600,0.321009,0.225665,-0.084566,-0.002707,-0.057828,-0.402280,0.144303,0.265371,-0.268922,0.616204,-0.181241,0.500374,-0.138602,0.388878,-0.345486,-0.123341,0.115730,0.600056,0.019861,0.307609,0.010438,-0.153995,-0.345849,-0.569143,0.419964,0.047647,-0.099366,-0.005428,-0.276818,-0.081728,0.006974,-0.355857,0.073299,0.285660,0.040289,0.471996,-0.570984,0.193881,0.092622,0.181705,-0.739164,0.167739,0.306114,0.174670,-0.191037,-0.003358,0.078978,0.134593,0.053775,0.058891,-0.219353,-0.017709,-0.257081,-0.222613,-0.395153', '1300265', '1473074', '1297574', '27621189');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295490', '捕鼠记', '喜剧', '当父亲去世后，欧尼（内森·连恩 Nathan Lane 饰）和拉尔斯（李·伊万斯 Lee Evans 饰）兄弟二人继承了一家线厂和一间旧房子。拉尔斯因不肯卖掉线厂而被势利的妻子赶出家门，而欧尼经营的餐厅突遭横祸，也被迫流落街头。无可耐克的兄弟俩只能搬去了父亲留下的老房子住。偶然间，兄弟两个得知他们住的旧房子是建筑大师的传世之作，非常具有艺术价值，价值数百万。兄弟俩决定将房子装修一番出售，但发现房子了一只常年居住的老鼠。这只聪明的老鼠对房子已经有了感情，不愿兄弟俩将它变卖，于是围绕着这幢古宅，一场人与鼠的大战即将展开......©豆瓣', '内森·连恩', '戈尔·维宾斯基', 7.7, 22737, 'tt0119715', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1198261784.jpg', 0.6, 2.6, 28.1, 47.9, 20.7, '0.402680,-0.182915,-0.600769,0.357882,0.045643,-0.403623,0.832920,0.351105,-0.562018,-0.421614,0.173175,0.747462,0.017036,0.354721,-0.087453,0.113917,-0.053312,-0.173245,-0.065937,-0.390915,-0.115438,-0.371342,-0.056086,-0.283720,-0.049658,-0.066806,0.361020,0.217104,0.018090,0.275833,0.302704,0.249336,-0.135798,0.060272,-0.293977,0.244025,-0.149793,0.148405,-0.366318,0.085422,-0.096348,-0.039226,-0.013794,-0.012760,0.299018,0.233992,0.817863,-0.157349,-0.197857,0.062579,0.175582,0.111303,-0.014599,0.393163,0.479192,-0.079388,0.375502,0.270194,-0.514268,-0.138783,0.208530,-0.244845,-0.434618,-0.064617,0.243029,-0.333399,-0.755870,0.522188,-0.025368,-0.013974,-0.254578,-0.626693,0.225836,0.277526,0.297253,0.563995,0.102805,-0.040305,-0.876653,-0.040419,0.585808,-0.423572,0.290815,0.394406,-0.215326,-0.377301,-0.094459,-0.300616,-0.573204,-0.020439,0.493136,0.008097,-0.150642,-0.183379,-0.941318,-0.210794,-0.391006,-0.318341,0.298407,-0.513368,-0.009335,-0.421175,-0.162757,-0.350900,-0.113553,0.264475,0.032443,-0.043389,0.344262,-0.650036,0.105584,0.196918,0.533479,-0.385367,0.724133,-0.626923,0.382381,0.122966,0.172112,-0.076060,0.289809,0.321515,0.537596,0.355221,0.055029,-0.273619,-0.382107,0.429447', '21619567', '1309101', '3055049', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295507', '第八日', '剧情', '神用七天创造了这个世界，第八天神作了什么？神奉献出了乔治乔治（Pascal Duquenne 饰）是一名唐氏综合征患者，住在康复中心，在这里他有美丽的女友，一群相似的朋友，他可以把自己想象成树，想象成蚂蚁，然而还是缺少了点什么，他想妈妈了，于是他站在路边吹声口哨，给了自己 一个方向，出发了。哈里（Daniel Auteuil 饰）供职于银行，过着不停旋转的职业生活，每天意气风发的装在职业形象的壳子里给员工们培训，然而他快乐么？他回到空无一人的家里，想到前妻将两个孩子带走，他拿起儿子的玩具手枪对镜自杀。又一次错过和孩子们的每周见面，哈里在车上心力憔悴，夜色中险些撞倒乔治，心怀愧疚的哈里试图送乔治回家，但是，乔治无法确切说出地址。这时的哈里并不知道，未来和乔治同行的旅程中将会生出美丽的友谊……©豆瓣', '丹尼尔·奥特伊', '雅克·范·多梅尔', 8.3, 8064, 'tt0116581', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1184771401.jpg', 0.5, 1.9, 16.9, 43.2, 37.5, '0.173140,0.110964,-0.671203,0.435904,-0.450199,-0.396815,0.748673,-0.000387,-0.335250,-0.258908,-0.011333,0.797193,-0.046463,0.603167,0.096214,0.044636,-0.344945,-0.618167,0.045824,-0.002057,-0.221000,-0.369862,-0.078403,-0.361096,-0.094475,-0.257102,0.286532,-0.237705,0.144937,0.357969,0.256571,0.115134,-0.045848,0.356268,-0.457165,0.162830,0.086422,-0.079114,-0.171897,0.346869,0.078763,-0.079805,-0.076926,0.213955,0.118030,0.143734,0.634820,-0.108457,-0.173389,0.062755,0.427370,-0.156366,-0.094238,0.128856,0.128156,0.157484,-0.002046,-0.148938,-0.181682,0.054466,0.179554,-0.100402,-0.649468,-0.025862,-0.241296,0.238397,-0.817791,0.486432,-0.194068,-0.057570,0.232763,-0.387971,0.357396,0.116719,0.080539,0.346330,-0.247026,0.024131,-0.685777,0.121841,0.555613,-0.060263,-0.075388,0.404136,-0.309964,-0.163085,0.096900,-0.022058,-0.520622,-0.052607,0.364023,-0.053965,-0.259057,-0.016078,-0.554386,0.035544,-0.182771,-0.232119,0.002507,-0.433267,-0.194622,-0.346772,0.083015,-0.349099,-0.489871,-0.073494,0.036049,-0.232694,0.756180,-0.724512,0.221374,0.580655,0.250795,-0.363420,0.707224,0.075009,-0.013255,-0.023025,0.148218,0.189655,0.058740,0.366255,0.172157,0.449681,-0.164043,0.007905,-0.503766,0.483225', '1783772', '3055049', '1783461', '3016252