INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295527', '浪人', '动作', '一支由特种部队的退伍军人组成的神秘小组正在郊外的一间仓库接受雇主任务，他们个个身怀绝技，山姆（罗伯特·德尼罗 Robert De Niro 饰）是前中情局官员、文森特（让·雷诺 Jean Reno 饰）为前欧洲情报局官员、格雷戈（斯特兰·斯卡斯加德 Stellan Skarsgård 饰）则是德国电子专家，同时还有英国武器专家史宾斯（肖恩·宾 Sean Bean 饰）和司机拉里。小组受命要袭击一支全副武装的车队并劫下一只神秘的公文包。经过一系列激烈追逐和枪战，小组总算拿到了箱子，却不料格雷戈竟然背叛了组织，携公文包潜逃并试图将其兜售给俄罗斯。然而，在随后的追回箱子过程中，背叛似乎如诅咒般笼罩着小组，在一次次胆战心惊的追逐和辗转之下，成员们再也已无法分辨站在面前的是敌是友……©豆瓣', '罗伯特·德尼罗', '约翰·弗兰克海默', 7.6, 16462, 'tt0122690', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p961406562.jpg', 0.5, 2.4, 30.8, 48.9, 17.4, '0.227016,0.013065,-0.606583,0.368649,0.053121,-0.127452,0.719017,0.005140,-0.632550,-0.060924,0.211149,0.651166,0.135546,-0.061576,0.124142,-0.116372,-0.488430,-0.936104,-0.554633,-0.201557,-0.445572,-0.435897,-0.200685,-0.225344,0.154711,-0.206155,0.635714,0.015337,0.008679,0.476591,0.482441,0.664381,-0.528624,0.382795,-0.113046,-0.187438,0.476770,-0.149091,-0.309905,-0.017081,-0.226879,-0.295038,-0.255186,0.049685,0.160078,0.355608,0.623990,-0.331100,0.189507,-0.217790,0.014049,-0.128878,0.115919,-0.165216,0.372884,0.319640,0.206628,0.332557,0.084088,0.195405,0.145816,-0.102539,-0.863974,0.096777,0.366862,0.148632,-0.632751,0.294646,-0.352582,0.243899,0.202279,-0.150390,0.149577,0.319386,0.304407,0.217466,0.029402,-0.031353,-0.535730,0.109078,0.256076,-0.019611,-0.181254,-0.049409,-0.124169,-0.438305,-0.125675,-0.097528,-0.271146,-0.146825,0.265233,0.079520,0.240741,0.013861,-0.669196,0.035173,-0.424653,-0.290038,-0.005756,-0.343461,-0.124150,-0.836547,0.159239,-0.180833,-0.220292,0.379061,0.036544,0.257480,0.485288,-0.502574,0.165184,0.537829,-0.007969,-0.160212,0.453628,-0.046230,0.086618,-0.115998,-0.125621,0.084683,0.418625,0.378306,0.054351,0.384668,-0.095211,-0.304842,-0.221208,-0.044815', '25723905', '30143331', '26577354', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295547', '一个好人', '喜剧', '澳大利亚墨尔本，华裔厨师积奇（成龙 饰）是当地小有名气的人物，定期在电视上主持烹饪节目。毒枭金·卡洛（Richard Norton 饰）集团颇有势力，金·卡洛本人残暴冷酷，清除了敌对帮派的卧底之后率众和对方在仓库大打出手，而枪战全过程被记者戴安娜（Gabrielle Fitzpatrick 饰）用摄影机记录。在躲避贩毒集团追逐的路上，戴安娜巧遇积奇，后者仗义出手为她引开歹徒，孰料两人分手时戴安娜错将积奇的节目录像带当做证据带走。戴安娜的住处很快被贩毒集团找到，遍搜不获的歹徒们开始将目标转向积奇。积奇女友美琪（李婷宜 饰）远道来访，特意参加了积奇的节目录制，贩毒集团在录制现场围捕积奇，经过一番街头苦战，积奇终于脱险。黄雀在后的金·卡洛敌对帮派带走了美琪，要挟积奇用录像带换人，一时间，围绕着录像带，积奇、警方、以及两个犯罪集团陷入了混乱的争夺战。©豆瓣', '成龙', '洪金宝', 7.2, 33595, 'tt0117786', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2239595849.jpg', 0.5, 3.1, 44.4, 39.1, 12.8, '0.275575,0.152359,-0.376181,0.191816,0.278690,0.005505,0.540982,0.172603,-0.481577,-0.089379,0.293813,0.388574,-0.374831,-0.011338,0.324619,-0.153186,-0.565649,-0.772722,-0.268863,0.035523,-0.076692,-0.537941,-0.210376,-0.135656,0.214397,-0.138336,0.366585,-0.108115,-0.169489,0.476007,0.485546,0.323512,-0.341599,0.284310,0.086779,-0.042169,0.367324,-0.234042,-0.474731,0.383398,-0.255510,-0.374227,-0.309100,-0.030582,0.067935,0.581435,0.843244,0.084994,0.127890,-0.160933,0.327003,-0.376029,-0.028659,-0.129953,0.585734,0.111245,0.233699,0.135550,-0.082379,-0.041031,0.041463,0.066063,-0.583421,0.089753,0.173189,0.138238,-0.495163,0.288461,-0.246152,0.367922,0.066652,-0.185862,0.193493,0.212277,0.203779,-0.165441,0.243881,0.146361,-0.484916,0.291134,0.457747,-0.014612,0.188398,-0.006017,0.249830,-0.450528,-0.017976,-0.163968,-0.160333,-0.091685,0.748012,-0.440774,0.098102,0.069606,-0.539060,-0.476010,-0.231373,-0.318804,0.163503,-0.180417,-0.145812,-1.084783,-0.126120,0.116237,-0.115361,-0.184127,0.002274,0.055720,0.447766,-0.613973,0.020724,0.658048,0.112988,-0.259400,0.290861,-0.077389,0.192625,-0.125354,-0.450890,-0.238610,0.452030,0.404006,0.340717,0.062456,-0.101241,-0.285390,-0.231636,-0.009120', '25723905', '3003137', '6984051', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295560', '007之金刚钻', '动作', '在生产钻石的南非，最近怪事连连，一大批未经切割的钻石失踪了，而且谋杀案频发。这些异常现象引起了英国当局的高度重视，于是007（肖恩•康纳利 Sean Connery 饰）来到了南非。007以钻石批发商的名义展开了一系列的调查，发现一切原来都是他的死对头魔鬼党的首领艾纳斯 （查尔斯•格雷Charles Gray 饰）在背后操纵的，而艾纳斯追求的并不是只是金钱，而是企图利用这些钻石制造最具杀伤力的激光卫星设备，用以达到自己邪恶的目的。于是，007在美丽的邦女郎坎丝（吉尔•圣约翰 Jill St. John 饰）的帮助开始了粉碎这个阴谋的行动！©豆瓣', '肖恩·康纳利', '盖伊·汉弥尔顿', 6.7, 9036, 'tt0066995', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1726437573.jpg', 1.2, 7.6, 54, 27.6, 9.6, '0.417921,0.092125,-0.725663,0.576505,-0.161119,0.050555,0.609001,0.166954,-0.394066,-0.238036,0.315308,0.375301,-0.299940,-0.265569,-0.009577,0.163946,-0.158638,-0.571953,-0.139759,-0.239076,-0.254308,-0.615131,-0.571049,-0.263378,-0.117389,-0.423194,0.550012,0.199479,-0.238597,0.284646,0.412434,0.466058,0.217911,0.373747,-0.187340,-0.238962,0.159531,-0.086405,-0.320381,0.321239,-0.104663,-0.425945,0.123402,0.481344,-0.128625,0.486011,0.545105,-0.587500,0.058253,-0.298063,0.492974,-0.567847,0.085907,0.116455,0.479145,0.183416,-0.117404,0.139761,-0.342921,0.321588,0.581776,0.008063,-0.952237,-0.205331,0.184493,0.212952,-0.521348,0.252258,-0.339372,-0.173924,0.008364,-0.197760,0.422196,0.565191,0.027234,0.141264,-0.108487,0.104933,-0.659622,0.232031,0.429244,-0.072136,-0.346347,0.407184,-0.277926,-0.470952,-0.293301,-0.115322,-0.036340,-0.100208,0.438019,-0.114957,0.060373,0.351236,-0.984046,-0.184831,-0.215514,-0.401437,0.000496,-0.359360,-0.133230,-0.988195,-0.173866,-0.548972,-0.197044,0.044646,0.093810,-0.169114,0.695929,-0.864873,-0.108466,0.710555,0.266539,-0.602435,0.171023,-0.143851,-0.053466,-0.197869,-0.447614,-0.038325,0.345634,0.403896,-0.180612,0.334297,0.447608,-0.545610,-0.330292,0.347225', '11810348', '1498811', '7155241', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295568', '深闺疑云', '剧情', '英俊帅气的约翰尼·依斯咖斯（加里·格兰特 Cary Grant）在火车上邂逅羞涩美丽的女孩丽娜·艾美斯莱德劳（琼·芳登 Joan Fontaine饰）。单纯善良的丽娜很快就被这位外表充满魅力的男人所吸引，却不知道约翰尼实际上是一位嗜赌如命的瘾君子。当得知丽娜是一位拥有大量财富的千金小姐后，约翰尼更是使尽浑身解数去追求她。很快，两人结婚。然而就在两人的蜜月期间，丽娜发现了约翰尼很多可疑之处，她开始害怕丈夫为谋取财产而杀害她。面对居心叵测的约翰尼，终日惴惴不安的丽娜害怕自己就是下一个受害者。由著名悬疑惊悚大师阿尔弗雷德·希区柯克于1941年执导的悬疑影片《深闺疑云》，荣获1942年第14届奥斯卡金像奖最佳女主角奖及最佳影片提名和最佳配乐提名。©豆瓣', '加里·格兰特', '阿尔弗雷德·希区柯克', 7.4, 22282, 'tt0034248', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1071785832.jpg', 0.4, 3.3, 37.7, 43.5, 15.1, '0.119985,-0.061815,-0.568198,0.278942,-0.093853,-0.311478,0.800022,-0.032907,-0.329311,-0.188816,0.351884,0.883136,-0.167569,0.166904,0.402379,0.200703,-0.380454,-0.462138,-0.119179,-0.329522,0.222228,-0.300605,-0.396318,0.200946,-0.062130,-0.646519,0.604362,-0.245935,-0.050405,0.558559,0.725941,0.255818,-0.034390,0.233944,0.048439,0.097768,0.394196,-0.208511,-0.341965,0.308884,-0.143429,-0.150054,-0.352640,0.046209,-0.208903,0.313051,0.561411,-0.063754,-0.164071,-0.045577,0.453926,-0.210702,-0.074958,0.166578,0.017485,-0.311470,0.362614,0.121204,-0.309346,-0.028490,0.242820,-0.035873,-0.747938,0.058763,0.404457,0.407089,-0.329863,0.183869,-0.195420,-0.112897,-0.001177,-0.112440,-0.194665,0.022789,0.047059,0.271147,-0.076601,0.070731,-0.196048,0.397934,0.416653,0.242313,-0.261931,0.474056,-0.254071,-0.303300,0.247984,-0.329850,-0.703502,0.053362,0.347020,0.019956,0.136893,0.311124,-0.524894,-0.032996,-0.362232,0.039102,-0.017104,-0.257992,-0.297739,-0.521861,-0.249725,-0.363635,-0.157307,-0.118758,0.185662,-0.421238,0.731083,-0.666671,0.292007,0.566787,0.098048,-0.357914,0.745543,0.221545,-0.192685,-0.276157,-0.301990,0.356361,-0.047272,-0.023514,-0.114114,0.425573,-0.127475,-0.359373,-0.256131,0.464732', '34890458', '4847665', '30167633', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295576', '恐惧拉斯维加斯', '剧情', '来自南太平洋萨摩亚群岛的体育记者杜克（约翰尼·德普 Johnny Depp 饰）和他的律师朋友刚佐博士（本尼西奥·德·托尔 Benicio Del Tore 饰）一起开车前往拉斯维加斯，寻找他们的“美国梦”。一路上，他们带了大量毒品和酒精，也遇到形形色色的人，药物作用下，许多迷乱和癫狂的画面出现，让他们分不清幻觉和现实，到底哪个更残破，哪个更肮脏扭曲。两个人的混沌，加上拉斯维加斯本身的纸醉金迷，“美国梦”似乎遥不可及，两个人留下垃圾场一样的五星级酒店房间，无法停止迷幻的路途……©豆瓣', '约翰尼·德普', '特瑞·吉列姆', 7.3, 7290, 'tt0120669', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195619869.jpg', 2.3, 6.8, 33.8, 36.8, 20.3, '0.555643,-0.143493,-0.613963,0.565594,0.069197,-0.125471,1.037583,0.254484,-0.624831,-0.593195,-0.073950,0.834650,-0.154348,0.077149,0.085414,0.041876,-0.584892,-0.470139,-0.051874,-0.133952,-0.465504,-0.400494,-0.358023,-0.278328,0.161104,-0.087346,0.356848,0.098232,0.015421,0.419252,0.232011,0.280379,-0.383624,0.322767,-0.320868,-0.058028,0.111000,0.077847,-0.453416,0.113380,0.048482,0.048590,-0.103399,0.050230,-0.035569,0.049613,0.598172,0.122823,0.005344,-0.136050,0.089684,-0.245433,-0.203867,-0.037108,-0.037142,-0.372356,0.382887,0.012675,-0.063834,-0.105503,-0.004870,0.370351,-0.744020,0.207320,0.251314,0.263927,-0.212827,0.199073,0.181327,0.029835,-0.022046,-0.011646,0.362808,0.135017,0.294720,0.248235,0.066044,-0.372594,-0.624552,-0.032528,0.688265,0.057103,-0.244259,0.354123,-0.426981,-0.422484,-0.401966,0.101286,-0.510326,0.277574,0.118327,-0.004058,-0.391054,0.278707,-0.870876,0.126969,-0.105277,-0.376272,-0.357977,-0.175530,-0.201664,-0.889568,-0.124378,-0.379136,-0.216238,-0.010052,0.149924,0.258711,0.402097,-0.444268,0.095533,0.537413,0.331226,-0.393771,0.737708,-0.184760,-0.210880,-0.374211,-0.298538,0.289419,0.237035,0.345872,-0.122920,0.329761,-0.289554,0.236567,-0.414686,0.410741', '10466639', '4944008', '1309101', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295578', '活死人黎明', '动作', '死而复生的嗜血僵尸如瘟疫般迅速占领全城，整个城市在一夜之间成为僵尸之城。为了躲避僵尸的攻击，两个特种部队警察和一个交通记者以及他的女友，逃到了一个荒废的大型购物中心里。这四个人斯蒂芬（大卫·艾梅治 David Emge 饰）、彼得（肯·弗里 Ken Foree 饰）、罗杰（斯科特·H·雷宁格 Scott H. Reiniger 饰）以及法兰妮（盖伦·罗丝 Gaylen Ross 饰）使尽浑身解数武装自己，尽一切可能抵抗凶残僵尸的袭击。然而他们的抵抗却不敌越来越多的僵尸，好景不长，僵尸蜂拥而至。雪上加霜的是，一大群车手也发现了这个避难所。四人不但要躲避疯狂的僵尸，还要同凶残的劫匪对抗。丧失电影教父乔治·A·罗梅罗继1968年成功推出《活死人之夜》后，再次打造本部经典恐怖片《活死人黎明》，成为僵尸三部曲中盈利最多的一部。©豆瓣', 'David Emge', '乔治·A·罗梅罗', 7.3, 8774, 'tt0077402', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2187252960.jpg', 1, 5.2, 36.2, 41.2, 16.4, '0.188702,-0.246106,-0.480470,0.325080,0.208744,-0.068885,0.893753,-0.238683,-0.271491,-0.241172,0.335652,0.522713,-0.130914,-0.127182,-0.028852,-0.274230,-0.045531,-0.525833,-0.220075,-0.013516,-0.150568,0.037467,-0.618225,-0.411247,0.091048,-0.197738,0.641282,0.256809,-0.033771,0.336343,0.248084,0.273330,-0.093656,0.173559,0.122720,0.002757,0.119903,-0.491049,-0.069406,0.531219,-0.361783,-0.054046,-0.103710,0.072043,-0.397748,0.329221,0.625876,-0.460604,0.077147,-0.390096,0.252114,-0.490581,-0.223020,0.181513,0.284881,-0.412705,0.175283,-0.075456,0.022542,0.000421,0.067011,0.071464,-0.841766,0.050319,-0.021164,0.274336,-0.490348,0.194246,0.085841,0.331446,-0.016989,-0.249986,0.053343,0.071144,0.006805,0.321471,-0.013782,0.007406,-0.626140,0.248484,0.701945,-0.104996,-0.593625,0.097314,0.080080,-0.379463,-0.136180,-0.407089,-0.345644,-0.115676,0.494232,-0.114288,-0.042384,0.370106,-0.894776,-0.096745,-0.539288,-0.094766,-0.326840,0.035116,0.002255,-0.876107,0.079195,-0.199812,-0.026964,0.159685,0.104059,-0.088574,0.566845,-0.695911,0.006563,0.486853,0.339492,-0.363996,0.179829,-0.338463,0.137626,0.082258,-0.173046,0.225365,0.457656,0.546906,0.230748,0.324473,-0.025753,-0.263911,-0.237976,0.513668', '25828589', '11810348', '1578502', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295582', '刺客战场', '动作', '身为一名杀手，罗伯特（西尔维斯特·史泰龙 Sylvester Stallone 饰）有着自己不可动摇的原则，那就是除了任务目标外，决不滥杀无辜。尽管与罗伯特是同行，但米高（安东尼奥·班德拉斯 Antonio Banderas 饰）的生死观却和罗伯特大相径庭，他不仅为了达成目的不择手段，更是将业内“德高望重”的罗伯特视作眼中钉肉中刺，欲除之而后快。充满了杀戮的生活令罗伯特感到厌倦，他决心再干最后一票，从此金盆洗手。很快，技术高超的罗伯特便捉住了目标任务——一名叫伊莉（朱丽安·摩尔 Julianne Moore 饰）的女贼，不幸的是，此时的伊莉和她手中价值两百万美元的磁盘亦成为了米高的猎物。随着时间的推移，罗伯特渐渐的爱上了伊莉，与此同时，残暴的米高也离他们越来越近。©豆瓣', '西尔维斯特·史泰龙', '理查德·唐纳', 7.2, 4433, 'tt0112401', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p798520600.jpg', 0.7, 4.2, 42.3, 40.7, 12, '0.090104,0.110395,-0.567100,0.658394,-0.063548,-0.412686,0.673229,0.193664,-0.267850,-0.084398,-0.046829,0.691607,0.060619,-0.072968,0.314564,-0.250456,-0.110640,-0.755624,-0.482600,-0.502915,-0.027760,-0.647432,-0.297590,-0.393132,-0.174723,-0.223443,0.603756,-0.058571,-0.231868,0.591283,0.691885,0.400444,0.272804,0.399065,-0.153323,-0.363941,0.168863,-0.419529,-0.221154,0.043843,0.034987,0.101414,0.034741,0.172274,-0.095249,0.506851,0.471964,-0.313492,-0.167202,-0.141351,0.146210,-0.387185,0.137232,0.012715,0.293262,-0.208283,0.132231,0.265079,-0.212245,-0.028611,0.192821,-0.207440,-0.966599,0.027661,0.144737,-0.134763,-0.324420,0.458342,-0.414825,-0.106395,0.257659,-0.259775,0.100743,0.107408,0.123899,0.180426,-0.164723,-0.004607,-0.474470,0.051688,0.587282,0.232212,-0.086180,0.033463,-0.226136,-0.586125,-0.315277,-0.415630,-0.113154,-0.370336,0.732852,0.235899,0.164021,0.402728,-0.572869,-0.104210,-0.454364,-0.102014,0.059703,-0.452751,0.167602,-0.235622,-0.023261,-0.479868,-0.321076,-0.032057,0.113238,-0.413381,0.787470,-0.657232,0.379708,0.587744,0.218820,-0.387714,0.786638,0.153934,0.285731,-0.077917,-0.309866,0.339491,0.066917,0.323037,0.062632,0.398683,0.089301,-0.405289,-0.314110,0.773559', '3785918', '30163500', '25880986', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295586', '黄昏双镖客', '西部', 'Indio（吉昂·马利亚·沃隆特 Gian Maria Volonté 饰）是一个穷凶极恶的通缉犯，他伙同他的团伙屡次作案，他有一个怀表，每次大开杀戒之前都会看一看表，表上有一个女人的照片。赏金猎人Manco（克林特·伊斯特伍德 Clint Eastwood 饰）正在追捕Indio，而另外一个赏金猎人Colonel Douglas Mortimer（李·范·克里夫 Lee Van Cleef 饰）也在追捕同样的目标。两人一开始都看对方不顺眼，后来才决定一起追捕Indio。两人得知Indio准备去抢劫银行，于是定下计谋，让Monco加入Indio的团队，之后再和Mortimer来个里应外合。后来两人不慎被Indio所抓获。到底Manco和Mortimer能否除掉Indio，而Indio怀表里那个女人又和Mortimer有何联系？本片为意大利导演赛尔乔·莱翁内 Sergio Leone执导的“通心粉”西部片。', '克林特·伊斯特伍德', '赛尔乔·莱昂内', 8.9, 45572, 'tt0059578', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191195219.jpg', 0.1, 0.4, 7, 41, 51.6, '0.165468,-0.267294,-0.603462,0.735917,-0.083406,-0.487881,0.740175,-0.015868,-0.219598,-0.293009,-0.025782,0.933179,-0.079956,0.130479,0.285516,0.190699,-0.470629,-0.811067,-0.072744,-0.425147,-0.548651,-0.436191,-0.488217,-0.393127,0.224284,0.188418,0.420365,-0.021269,-0.205881,0.315270,0.636046,0.187916,-0.117552,0.567349,-0.125295,-0.137788,0.315546,-0.082150,-0.015816,0.334135,0.148896,-0.339406,-0.224980,0.124321,0.118065,0.549527,0.652205,-0.186823,0.097848,-0.227097,0.104595,-0.203310,0.040227,0.077219,0.398814,-0.155137,0.268556,-0.003270,-0.220464,-0.030998,0.036534,-0.026367,-0.885592,0.159010,0.223967,0.006573,-0.617552,0.038886,-0.129044,0.137679,0.032571,-0.204893,0.140288,0.650080,0.534436,0.070103,0.045305,-0.340276,-0.678031,0.058854,0.484496,0.139940,0.123524,-0.033656,0.245707,-0.502690,0.061601,-0.065435,-0.293589,-0.026232,0.746874,-0.188259,0.005449,-0.081719,-0.719824,-0.183111,-0.282288,0.047697,-0.068927,-0.433717,0.107824,-0.752968,-0.132303,-0.148483,-0.210303,0.229591,0.176204,-0.132280,0.517125,-0.650105,0.076373,0.629593,0.322615,-0.732175,0.504660,0.330166,0.195578,-0.223503,0.041872,-0.197500,0.528406,0.319609,0.299993,0.331992,0.145979,-0.404904,-0.137436,0.226465', '4301278', '5973984', '1303139', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295603', '抢钱大作战', '剧情', '19岁的少年赛斯·戴维斯（吉奥瓦尼·瑞比西 Giovanni Ribisi饰）一心希望能尽快淘到自己的第一桶金，好让父亲另眼相看。他本打算靠玩非法纸牌起家，却发现此路根本行不通，直到一家名为J.T.马林经纪公司的股票经纪商找上了赛维斯。在这个号称“锅炉房”的核心办公室里，多少个一夜间成为百万富翁的故事深深诱惑着赛维斯。很快，野心勃勃的赛维斯便以优异的成绩通过了股票经济人认证考试，开始了他的“成功之路”。他把那些永远都没有前途的股票卖给利欲熏心的投资者。赛维斯正以极危险的速度追逐着金钱与利益，靠近着他所谓的功成名就，贪婪而不安。在纽约长岛这个瞬息万变的商业圈里，良心未泯的赛维斯终于开始面对良心的考验。©豆瓣', '吉奥瓦尼·瑞比西', '本·杨格尔', 7.4, 7352, 'tt0181984', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2635175881.jpg', 0.4, 3.3, 36.8, 45.6, 13.8, '0.177569,0.341569,-0.512346,0.605923,0.102311,-0.658655,0.151627,0.149240,-0.299043,-0.209932,-0.096891,0.795632,0.023937,0.240906,0.204127,0.114582,-0.185584,-0.667813,-0.020039,-0.263930,-0.041824,-0.552421,-0.502661,-0.012600,-0.140204,-0.101524,0.515948,0.097766,-0.271723,0.404985,0.169201,0.218035,0.255985,0.227901,-0.221437,-0.240312,0.327720,-0.311779,-0.408325,-0.001764,0.075666,-0.069162,-0.178953,0.078780,0.296347,0.354103,0.457033,-0.318515,-0.119138,0.040438,0.293591,-0.385585,-0.025737,-0.055587,0.063421,-0.051341,0.135410,0.166626,-0.165366,0.017405,0.098353,-0.170796,-0.908135,-0.152046,-0.139635,0.357899,-0.644083,0.367012,-0.213199,-0.065465,0.015591,-0.055794,0.112966,0.340489,-0.051224,0.162407,-0.349228,-0.087292,-0.655625,0.098749,0.402966,0.096635,-0.297106,0.264448,0.065193,-0.398266,0.180034,-0.405301,-0.347034,-0.266026,0.518915,0.149047,-0.009807,0.218312,-0.728101,0.166202,-0.113420,-0.280468,-0.028850,-0.371172,-0.045955,-0.532004,-0.253334,-0.309142,-0.325029,-0.064850,0.019080,-0.364130,0.648299,-0.781471,0.008514,0.720673,0.446776,-0.461346,0.600643,-0.090599,0.279969,-0.164837,-0.664191,0.090437,-0.197554,0.328635,-0.093764,0.337074,0.152544,-0.532251,-0.205669,0.893021', '1793491', '1308585', '1870681', '1308815');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295614', '士兵之歌', '剧情', '二战期间，19岁的通讯兵阿廖沙（弗拉迪米尔·伊瓦绍夫 Vladimir Ivashov饰）在卫国战争中用反坦克枪击毁了德军的两辆坦克而受到嘉奖。但阿廖沙请求将军不必为他授奖，只希望给他几天假回家探望一次母亲（安东尼娜·马克西莫娃 Antonina Maksimova饰）。于是阿廖沙踏上了为期只有六天的归家旅程。途中，阿廖沙邂逅了天真无邪的少女舒拉（让娜·普罗霍莲柯 Zhanna Prokhorenko饰），两人一见钟情。然而他们乘坐的火车被炸，他救死扶伤耽搁了不少时间。当阿廖沙终于回到家乡时，只来得及和母亲在田边说几句话就要返回前线。可这一去，阿廖沙就再没有回来。由著名导演格利高利·丘赫莱依执导的苏联现实主义电影杰作《士兵之歌》，荣获1962年第34届奥斯卡金像奖最佳原创剧本提名，入围1960年第13届戛纳电影节金棕榈奖，并获得1962年第15届英国电影和电视艺术学院奖电影奖-最佳影片等多项大奖。', '弗拉迪米尔·伊瓦绍夫', '格利高利·丘赫莱依', 9.1, 12795, 'tt0052600', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p806332287.jpg', 0.1, 0.5, 5.6, 32, 61.8, '-0.320437,-0.131839,-0.616724,0.509351,0.531671,-0.542719,0.357201,-0.140492,-0.354626,-0.036971,-0.041737,0.655808,-0.258082,0.108921,0.475377,0.115726,-0.777687,-0.553211,0.136280,-0.275804,-0.070031,-0.270065,0.080024,0.119597,0.111684,-0.509869,0.477128,-0.147222,0.033992,0.613638,0.379739,-0.001850,0.245956,0.358758,-0.051229,0.272779,0.276234,-0.033429,-0.382588,0.555469,0.130695,-0.174825,-0.556386,-0.228920,0.291828,0.096366,0.728416,-0.221316,0.097279,-0.037907,0.371390,-0.284628,0.067965,-0.184586,0.141386,-0.010954,0.283021,0.250602,0.023196,0.513420,-0.025281,-0.194878,-0.205094,0.168577,-0.327324,-0.204104,-0.618535,0.501868,-0.418434,0.340088,-0.015963,-0.202996,0.239224,0.394217,0.155375,0.115497,-0.178429,-0.041935,-0.435624,0.602799,0.503548,-0.151953,-0.233600,0.539832,0.214947,-0.564779,0.056370,-0.348080,-0.344540,0.333447,0.367321,-0.156959,0.024250,-0.039345,-0.353297,-0.198750,-0.482388,-0.419759,0.116546,-0.178139,0.070850,-0.649024,0.288693,0.024456,-0.197789,0.060145,0.158207,-0.144889,0.585906,-0.240811,0.487883,0.346890,0.191294,-0.085501,0.885880,0.146812,0.011027,-0.154909,0.263605,0.128509,-0.178777,0.273531,0.160878,0.233086,0.025215,-0.425694,-0.145325,0.320091', '1829654', '1302279', '3011997', '1297368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295622', '捉贼记', '爱情', '最近城里的屡屡发生珠宝劫案，警察们都束手无策。因为贼人的手法和以前闻名的大盗“黑猫”约翰（加里•格兰特 Cary Grant 饰）如出一辙，警察们找上了正在乡间别墅过着悠闲生活的约翰。约翰当然不会轻易就范，他摆脱了警察之后，开始调查到底是谁用他的手法屡屡作案。毫无头绪的约翰找到了以前的战友巴先生，却被巴先生餐馆里的人视作不速之客。幸好在侍者孚的女儿的帮助下，约翰来到了嘎纳海滩。在保险公司经理的帮助下，约翰展开了他的抓贼行动。©豆瓣', '加里·格兰特', '阿尔弗雷德·希区柯克', 7.2, 21799, 'tt0048728', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1543980657.jpg', 0.4, 4.3, 45.4, 36.2, 13.7, '0.641892,-0.288739,-0.593270,0.288034,-0.135122,-0.375764,0.544445,-0.047555,-0.861021,-0.297254,0.326664,0.414392,-0.032605,0.294602,0.245186,-0.046666,-0.544697,-0.783510,-0.043784,-0.105870,-0.368484,-0.381735,-0.296473,-0.351285,0.040287,-0.061663,0.066171,-0.021528,-0.000773,0.228557,0.144826,0.328716,0.023223,0.466489,-0.017707,0.118845,0.335052,-0.286561,-0.203471,0.282017,0.292317,-0.332951,-0.268357,0.111615,0.282793,0.511621,0.518216,-0.495821,-0.229586,0.044865,0.072572,-0.271055,0.192587,0.154316,0.198538,-0.056319,0.243256,0.257041,-0.092284,-0.222377,0.073557,0.079255,-0.511139,0.316579,0.046101,0.335107,-0.787564,0.075392,-0.257610,0.231593,-0.145372,-0.639864,0.244721,0.259004,0.291212,-0.063825,0.047818,-0.069045,-0.700941,0.029681,0.789688,0.171073,-0.040319,-0.038790,-0.206400,-0.315375,-0.070920,-0.224485,-0.335536,-0.057852,0.281880,-0.274232,-0.155539,0.145917,-0.595874,-0.122290,-0.263768,-0.017805,-0.283484,-0.114273,-0.042167,-0.776294,0.145749,-0.304167,-0.174411,0.088959,0.036541,-0.124193,0.473064,-0.800422,0.130676,0.623027,0.357084,-0.132753,0.612586,-0.237833,-0.124067,-0.101672,-0.565989,0.015241,0.471663,0.540267,0.438300,0.419620,0.275604,-0.410477,-0.054564,0.346988', '26341750', '3178770', '1308755', '1877016');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295629', '杀手阿一', '剧情', '新宿歌舞伎町的民宿大厦——“流氓公寓”的山口组蜗居点。黑社会组织安生组的老大安生芳雄与情妇及一亿日圆现金失踪后，流氓公寓每天都有黑道人被杀。外界断定这是传说中的杀手“Ichi”所为。武斗派头目垣原（浅野忠信饰）于是开始疯狂寻找凶手。垣原是个极度被虐狂，视虐待成狂的老大如自己的神明一般，迷恋与崇拜他。垣原误信退役江湖老鬼阿叔，掳劫了敌对帮派头目，酷刑逼供，引起江湖风暴，令安生组进退失据。老大情妇Karen（孙佳君饰）与阿叔相熟，为讨好垣原以身犯险。Karen在阿叔帮助下，渐渐接近神秘杀手阿一……大导演三池崇史的名作，血腥暴力美学推向极致。©豆瓣', '浅野忠信', '三池崇史', 7.5, 32944, 'tt0296042', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2633002964.jpg', 2.1, 5.5, 30.7, 40.9, 20.8, '0.019552,0.009333,-0.237842,0.241817,-0.008712,0.068017,0.218330,0.255580,-0.386438,-0.209229,0.238282,0.576121,-0.089987,0.088442,0.214558,-0.089530,0.113896,-0.559867,-0.590310,-0.198081,0.136278,-0.293675,0.042407,0.044642,0.024221,-0.120099,0.406780,0.119532,-0.172696,0.260719,0.399027,0.615105,-0.372218,-0.085654,-0.163918,-0.086675,0.203464,-0.115207,-0.373992,-0.075705,-0.430384,0.035532,-0.035340,0.091780,0.034735,0.161855,0.564021,-0.319121,-0.287331,-0.473430,0.221242,-0.156790,-0.346466,-0.099481,0.502945,-0.198755,0.238777,0.436855,0.045689,-0.000074,-0.111210,0.213921,-0.711103,0.010574,0.353472,-0.172097,-0.424927,0.062013,-0.021720,-0.041636,0.063079,0.147145,0.275780,0.188644,0.195188,-0.066971,0.067705,0.193825,-0.220816,0.154301,0.603620,-0.055557,-0.050871,-0.157262,-0.022933,-0.134513,0.267908,-0.480072,-0.132071,-0.096100,-0.014885,-0.368200,-0.191292,0.258212,-0.422206,-0.079915,-0.036019,0.197984,0.094228,-0.215057,-0.329142,-0.700829,-0.254596,-0.026279,0.153844,-0.000559,0.134728,0.054657,0.452397,-0.645934,0.200926,0.605944,0.221967,-0.607671,0.509054,-0.118220,-0.347144,-0.193938,-0.361516,0.014414,0.549060,0.535668,0.153446,0.141139,-0.400948,-0.230616,0.003549,-0.014739', '2369613', '26678784', '4301278', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295635', '致命武器', '动作', '圣诞节前夕，一名衣着暴露的独身女子在酒店高层房间中神情恍惚，她来到阳台上，翻身坠落……刚过50岁生日的黑人警员罗杰（Danny Glover 饰）负责此案，他发现坠楼女子是自己越战时的搭档麦克之女。警局派遣瑞格（梅尔·吉布森 Mel Gibson 饰）协助罗杰，瑞格能力卓越，但是最近陷入失去妻子的悲伤心境中无法自拔。这对新搭档很快就为瑞格解决问题的莽撞方式大吵，或许正如瑞格所说，这是一座疯狂的城市，人人都试图自杀。随着调查不断深入，罗杰与瑞格发现坠楼事件背后的真相超出了他们的控制：原来美国中情局在越战时成立特种部队，针对越共的毒品交易进行渗透、破坏，战后，这批特种兵利用当年的交易网大肆贩毒，而麦克由于妨害毒品集团利益遭到杀害。罗杰与瑞格虽然找到了方向，但是将毒品集团捣毁显然困难重重。©豆瓣', '梅尔·吉布森', '理查德·唐纳', 7, 5663, 'tt0093409', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1955833185.jpg', 0.9, 4.3, 46, 39.5, 9.2, '0.333529,0.170194,-0.661399,0.368875,-0.077314,-0.079898,0.657697,0.110513,-0.612233,-0.330884,0.317064,0.486596,0.008789,0.092849,0.461865,-0.043356,-0.468004,-0.702509,-0.086832,-0.189530,-0.250285,-0.580485,-0.201543,-0.275031,0.003488,-0.361193,0.634150,0.266702,-0.357009,0.487670,0.154312,0.588654,-0.239063,0.205095,0.323979,-0.295195,0.491715,-0.163854,-0.400382,0.277417,-0.211154,-0.178302,0.047904,0.127451,-0.105027,0.439890,0.364036,-0.141842,-0.086950,-0.434008,0.405429,-0.182721,0.136683,0.060335,0.557385,0.134912,0.127717,0.189893,-0.325980,-0.111031,0.068682,-0.119624,-0.763309,0.087922,0.300719,-0.056400,-0.539617,0.119861,-0.277212,0.192864,0.150531,-0.173692,0.028121,0.633877,0.509415,0.072949,-0.099596,-0.030608,-0.571319,-0.128343,0.756981,-0.184257,-0.224560,-0.051356,0.045234,-0.245662,-0.026770,-0.122109,-0.085414,-0.055498,0.037800,0.106977,0.065590,0.269526,-0.303259,0.007709,-0.282711,-0.274320,-0.022064,-0.135400,-0.263688,-0.830314,-0.387221,-0.112768,-0.047841,-0.084701,-0.095261,-0.233018,0.197795,-0.712158,0.331950,0.536261,0.346355,-0.412636,0.455630,-0.093846,0.191515,-0.371331,-0.261565,0.351456,0.352890,0.118082,-0.059991,-0.019038,-0.082145,-0.332384,-0.162812,0.234715', '5157137', '1307442', '25723905', '1298104');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295638', '永远的蝙蝠侠', '动作', '高谭市的黑暗势力又开始蠢蠢欲动了，这次是毁了半边脸的“双面人”（汤米•李•琼斯 Tommy Lee Jones 饰）。一次，“双面人”袭击了马戏团，演员迪克（克里斯•奥唐纳 Chris O''Donnell 饰）阻止了“双面人”的阴谋，家人却因此惨遭杀害。布鲁斯（瓦尔•基尔默 Val Kilmer 饰）收留了迪克，并说服了满腔仇恨的迪克留了下来。因研究计划被拒绝而仇视韦布斯的公司职员爱德华（金•凯瑞 Jim Carrey 饰）成功研究出脑波吸收装置，化身成为“谜语侠”。“双面人”和“谜语侠”联手破坏高谭市，并通过脑电波吸收装置大量吸收市民的脑电波。蝙蝠侠这次的对手强大得可怕，蝙蝠侠最终能否战胜罪恶？©豆瓣', '方·基默', '乔·舒马赫', 6.7, 29262, 'tt0112462', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2410156576.jpg', 1.4, 9.3, 53.2, 26.8, 9.4, '-0.120139,0.255305,-0.225684,0.450986,0.013282,-0.238987,0.607468,0.114001,-0.326620,-0.092123,-0.099127,0.240781,-0.226376,-0.293111,0.152487,-0.009498,-0.526647,-0.346770,0.100742,0.068912,-0.436146,-0.622891,-0.458985,-0.434164,0.163599,-0.675269,0.370900,0.298858,-0.277827,0.073017,0.323545,0.439652,0.013508,0.220562,0.452569,-0.032313,0.002354,-0.441524,-0.042941,0.331113,-0.134007,0.072791,-0.036948,0.407518,0.078292,0.443301,0.446272,-0.383011,0.187452,-0.376297,0.107905,-0.402105,-0.007072,-0.119205,0.257684,-0.088238,0.264083,-0.004546,0.078945,-0.159278,0.260389,0.152789,-0.793499,0.199396,0.082569,-0.094681,-0.256880,0.128709,-0.275341,0.208833,-0.204231,-0.161028,-0.086063,-0.005190,0.431429,0.216042,0.061245,0.114655,-0.490519,0.101784,0.376383,-0.074328,-0.502789,-0.015109,-0.169529,-0.315089,-0.424254,-0.279553,0.034576,-0.085710,0.858235,0.232961,0.028695,0.358847,-0.493007,-0.356617,-0.621958,0.158835,0.022269,-0.364800,0.176456,-0.847610,-0.112446,0.156757,0.016410,-0.178533,0.000628,-0.273588,0.464373,-0.648769,0.195442,0.568053,0.283249,-0.415209,0.432682,-0.051714,-0.043722,-0.224690,-0.205950,0.152041,0.325880,0.331221,0.413185,0.117328,0.210317,-0.247511,0.027325,0.388034', '1301345', '4014396', '4014397', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295644', '这个杀手不太冷', '剧情', '里昂（让·雷诺饰）是名孤独的职业杀手，受人雇佣。一天，邻居家小姑娘马蒂尔达（纳塔丽·波特曼饰)敲开他的房门，要求在他那里暂避杀身之祸。原来邻居家的主人是警方缉毒组的眼线，只因贪污了一小包毒品而遭恶警（加里·奥德曼饰）杀害全家的惩罚。马蒂尔达得到里昂的留救，幸免于难，并留在里昂那里。里昂教小女孩使枪，她教里昂法文，两人关系日趋亲密，相处融洽。女孩想着去报仇，反倒被抓，里昂及时赶到，将女孩救回。混杂着哀怨情仇的正邪之战渐次升级，更大的冲突在所难免……©豆瓣', '让·雷诺', '吕克·贝松', 9.4, 2164629, 'tt0110413', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p511118051.jpg', 0.1, 0.2, 3.2, 22.7, 73.9, '0.159328,-0.092600,-0.317354,0.073778,-0.127525,-0.221024,0.476240,0.142551,-0.575220,-0.101426,0.148342,0.547787,-0.007011,-0.007668,0.219677,-0.082641,-0.094055,-0.542589,0.006246,-0.118579,-0.141558,-0.420508,-0.200914,-0.242524,0.017078,-0.139386,0.198024,-0.148814,-0.177890,0.427386,0.224539,0.351918,-0.228966,0.165904,-0.057021,0.022341,0.149968,-0.306995,-0.174470,0.013948,-0.122446,-0.115148,-0.069390,-0.264274,0.134726,0.396295,0.582026,-0.197547,0.010409,-0.183106,0.041274,-0.178093,0.084982,-0.042889,0.296411,-0.058807,0.020503,0.284908,-0.279417,-0.134516,0.102796,-0.042425,-0.366937,0.423322,0.161598,0.184026,-0.491375,0.231758,-0.199720,-0.044564,0.274766,-0.067653,0.098432,0.429592,0.303921,0.038761,0.015432,-0.147943,-0.637793,-0.015637,0.571517,-0.324550,0.188416,-0.122536,-0.290781,-0.189299,0.037849,-0.391648,-0.265389,0.016176,0.506770,-0.176327,0.098603,0.301613,-0.448009,-0.327979,-0.437952,0.093056,-0.033204,-0.351862,0.154449,-0.788117,0.135645,-0.105733,-0.385685,-0.178707,0.004235,-0.276323,0.461115,-0.460286,0.310151,0.677892,0.425519,-0.239750,0.352555,0.093993,0.167323,-0.147092,-0.229279,0.556849,0.414102,0.055908,0.295870,0.122112,-0.012050,-0.034086,0.001576,0.169305', '3147969', '1899892', '3326747', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295646', '大独裁者', '剧情', '影片讲述第一次世界大战，托曼尼亚王国独裁者辛格尔（查理·卓别林饰）上台。他的大肆扩张导致战乱不断民不聊生。并且他大搞阴谋政策，煽动民众对犹太人的敌对与仇恨，让犹太人民陷入水深火热的灾难之中。被征入伍的犹太人理发师查理（查理·卓别林饰）更是在这样的高压政策下难逃一劫。当查理逃出边境时，被驻守在这里的军队误认为是独裁者辛格尔，他趁机做了一场“为自由而战斗”的大演说。该片是查理·卓别林的第一部有声片，摄于希特勒统治最为黑暗的时期，片中对他辛辣讽刺跟丑化比比皆是。本片荣获第13届（1941）奥斯卡最佳电影、最佳男主角、最佳男配角、最佳编剧、最佳音乐5项提名。©豆瓣', '查理·卓别林', '查理·卓别林', 9.2, 71448, 'tt0032553', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1960167314.jpg', 0.1, 0.4, 5.2, 29.1, 65.2, '-0.279041,0.001273,-0.678410,0.727234,0.264217,0.024043,0.546559,0.087600,-0.479696,-0.083087,0.418011,1.082572,-0.296460,-0.195142,0.405267,-0.078577,-0.532802,-0.814230,-0.302396,0.183678,-0.000707,-0.238336,-0.464715,-0.063836,-0.424495,-0.302550,0.841747,0.124463,-0.671353,0.176446,0.506622,0.362951,0.242854,0.017898,0.021637,0.018041,0.245431,-0.434008,-0.648585,0.463760,-0.084228,-0.375542,-0.444301,0.329308,-0.050932,0.193192,0.661342,-0.473102,0.144303,-0.147943,0.678565,-0.683124,-0.326318,0.156252,0.289428,-0.079986,0.291268,0.150233,0.066895,0.235406,-0.079738,-0.177105,-0.901918,0.145904,-0.073487,0.220927,-0.398008,0.406004,0.052524,0.081346,0.199762,0.099195,0.220171,0.677420,0.504416,0.172506,-0.220255,-0.046553,-0.344748,0.463129,0.491957,-0.114301,-0.430284,0.050454,-0.279023,-0.516162,0.036399,-0.367527,-0.474675,-0.288655,0.453311,-0.434870,-0.032068,0.647346,-0.449400,-0.191380,-0.321792,-0.596169,-0.014250,-0.159792,-0.063222,-0.831210,-0.324865,-0.399833,0.101769,-0.102267,0.158464,-0.152931,0.610165,-0.609919,0.322839,0.523571,0.153405,-0.476724,0.466412,0.346270,0.138829,-0.159136,-0.216281,0.462398,0.096843,0.147233,0.124445,0.068419,0.043855,-0.430949,-0.156044,0.413411', '1298911', '26990609', '27073234', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295647', '超时空接触', '剧情', '艾莉·爱罗维（茱迪·福斯特饰）自幼就对无线电通讯情有独钟。长大后，她成为一名天文学家，其项目内容为接收外太空信号。她希望能借此找到宇宙其他文明的存在。天才的理想得到的却是投资者的冷眼相看，幸好有神秘人帮助艾莉继续工作。一次偶然的机会，艾莉收到了来自织女星的频率信号，似乎证明了艾莉一直以来的工作是正确的。但这带来的不是她个人事业的成功，而是政治、社会、宗教、国家各个角度的矛盾与讨论。深陷这一切暴风中心的艾莉，更要面对与神职人士帕尔默·乔丝（马修·麦康纳饰）的感情纠葛。个人与世界，真相与现实，艾莉面临着远远超越学术范围的挑战。©豆瓣', '吉娜·马隆', '罗伯特·泽米吉斯', 8.4, 101955, 'tt0118884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453499268.jpg', 0.4, 1.4, 15, 44.1, 39.1, '0.087733,0.111169,-0.664162,0.905337,-0.287254,0.130711,0.542857,0.092961,-0.695615,-0.152794,-0.073193,0.434804,-0.032882,-0.043739,0.453368,-0.126430,-0.287895,-0.709988,0.096499,-0.257589,-0.335493,-0.785291,-0.674783,-0.442257,-0.297233,-0.359491,0.786860,-0.130907,-0.474313,0.197726,-0.086867,0.374843,-0.188809,0.661490,0.010704,-0.420239,0.158759,0.092742,-0.564991,0.278369,0.082116,0.116209,0.016382,0.305133,-0.217557,0.223062,0.484019,-0.337616,-0.065989,-0.180730,0.397310,-0.103683,-0.040057,0.063032,0.296659,-0.053254,0.121051,0.120192,0.304734,-0.184679,0.049277,-0.067118,-0.896175,-0.328082,0.129173,0.291230,-0.251244,0.278022,-0.335067,-0.200292,-0.177026,-0.310727,0.028853,0.467203,0.740600,0.297745,-0.333816,0.151143,-0.444086,-0.044036,0.358851,0.112167,-0.570664,0.317238,-0.320199,-0.666885,-0.324607,-0.077224,-0.638515,0.140956,0.407446,0.375777,-0.252760,0.417771,-0.526534,0.016663,-0.128809,-0.524638,0.285729,-0.574819,0.194704,-0.949092,-0.222727,-0.447045,-0.445293,-0.138844,0.232074,-0.477888,1.058880,-0.791881,0.155901,0.807535,0.280472,-0.600882,0.886618,0.198064,0.574832,-0.570909,-0.159547,0.164234,-0.065567,0.397173,-0.285994,0.077217,0.231683,-0.182442,-0.306420,0.438254', '25932086', '27602116', '3318306', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295656', '潜行者', '剧情', '清晨，空荡幽暗的卧室。潜行者（亚历山大·凯伊达诺夫斯基 Aleksandr Kajdanovsky饰）悄然无息地起身准备与另外两人会合前往一片恐怖复杂的地带。可妻子（阿丽萨·弗雷因德利赫 Alisa Frejndlikh饰）却极力哀求他不要冒险进入该地。而这位训练有素、 经验丰富的潜行者，即将穿越的是一片有着千变万化陷阱和圈套的地区“The Zone”。这块二十年前因陨星坠落而荒芜的恐怖地区，传说有一个名叫“The Room”的囚室，它能满足人们潜意识里最深层的意愿和欲望。潜行者与为寻求灵感的作家（安纳托里·索洛尼岑 Anatoli Solonitsyn饰）和为探明真相的科学家（尼古莱·格陵柯 Nikolai Grinko饰），踏上了这片变幻莫测的死亡之地。这部极具史诗片气质，探究人类灵魂本质的科幻电影《潜行者》，用诗意而极富隐喻的长镜头，挖掘着人类潜意识与外部世界的重重矛盾与深层意义。1957年，一场发生在苏联车里亚宾斯克附近名叫玛雅卡工厂的核灾难，深深触动了导演安德烈·塔科夫斯基，成为本部电影中的创作素材。影片也改变自小说《The Roadside Picnic》。本片荣获1980年第33届戛纳电影节天主教人道奖。', '亚历山大·凯伊达诺夫斯基', '安德烈·塔可夫斯基', 8.8, 26965, 'tt0079944', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2327634482.jpg', 1.1, 1.9, 9.2, 29.9, 57.9, '0.266308,0.216089,-0.739864,0.752840,0.329919,0.065416,0.847263,-0.015005,-0.413747,-0.293955,0.040223,0.594389,-0.182581,-0.038481,0.265928,0.120015,-0.396511,-0.508126,-0.213646,-0.196726,-0.271392,-0.353483,-0.544463,-0.120299,-0.036705,-0.491698,0.811243,0.459355,-0.389214,0.210038,0.146528,0.666279,-0.178670,0.220755,0.190814,-0.159356,0.142705,-0.079905,-0.444408,0.153381,-0.053320,-0.147554,-0.276918,0.119657,-0.099447,0.148529,0.716864,-0.422451,0.044248,0.011101,0.429419,-0.222289,0.034618,-0.143522,0.105989,-0.087812,0.088009,0.275749,0.110706,0.128464,0.103038,-0.298566,-0.654100,-0.156962,0.110974,0.076246,-0.266419,0.140616,0.027683,-0.042491,0.097878,-0.097021,0.274469,0.103969,0.338681,0.279176,-0.126166,-0.094315,-0.337944,0.108758,0.235683,0.067829,-0.381267,0.178554,-0.439365,-0.622714,-0.076518,-0.169602,-0.450448,-0.064259,0.446530,0.136533,-0.065345,0.406286,-0.734653,0.190254,-0.228530,-0.274926,-0.115241,-0.242854,-0.086538,-0.670045,-0.269214,-0.196292,-0.000551,-0.046435,0.012481,-0.055336,0.493753,-0.439108,0.400658,0.455204,0.171259,-0.116669,0.722226,-0.228041,0.100259,-0.284618,-0.006526,0.493127,-0.082072,0.270035,-0.026653,0.318247,-0.033949,0.041686,-0.445093,0.559760', '1299261', '1293433', '1467779', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295674', '猛鬼佛跳墙', '喜剧', '建筑设计师骠叔（董骠 饰）在行业内辛勤工作二十年，最近因一单设计受到老板赏识，升迁之余，更获赠一幢山中别墅的使用权。骠叔与妻子（狄波拉 饰）兴高采烈的告别了拥挤的旧屋，携大女儿阿珍（李丽珍 饰）、阿珍男友大旧（何启南 饰）探访别墅，虽然家具需要重新添置、阿珍又在别墅中看到可疑的黑影，但难掩一家人的乔迁之喜。然而不久别墅中便发生众多可疑之事，凌乱的阁楼中似乎潜藏着对骠叔一家不怀好意的鬼魂，大旧请来的捉鬼专家被鬼物肆意整治后，骠叔欲为恶鬼拍照却被鬼上身，受恶鬼影响的骠叔愈发暴躁。在这一家人要将恶鬼生前的悲剧重演之时，住在附近的独眼道士（梁小龙 饰）出手相助……©豆瓣', '董骠', '于仁泰', 6.8, 5836, 'tt0095616', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2347433322.jpg', 1.1, 7.9, 51.2, 28.8, 11, '0.270469,-0.142934,-0.577476,0.194591,0.091538,-0.075000,0.983273,0.189358,-0.591651,-0.377968,0.289584,0.379990,-0.287730,0.213546,0.029278,-0.134533,0.024746,-0.299575,0.013412,-0.243455,-0.035719,-0.042315,-0.235956,-0.198037,-0.174902,-0.315423,0.193506,0.276235,0.125685,0.346401,0.328924,0.280662,-0.337901,0.266557,-0.213902,-0.075237,0.110328,0.013594,-0.152306,-0.009930,-0.224469,-0.369514,-0.105286,0.024750,-0.103424,0.316753,0.714442,-0.016356,-0.410609,-0.145343,0.272942,0.211022,0.142606,0.359288,0.377857,-0.056609,0.288222,0.239806,-0.316473,0.049650,0.269635,-0.153966,-0.285629,0.065146,0.344097,0.116860,-0.514739,0.325903,0.014179,0.016759,-0.066443,-0.191710,0.271498,0.126777,0.211894,0.420335,0.077161,0.066906,-0.520268,0.139377,0.260250,-0.053064,0.156134,0.299807,-0.226467,-0.425460,0.189055,-0.069388,-0.448855,-0.226776,0.474877,0.057593,-0.144850,-0.007999,-0.590074,-0.136928,-0.119508,0.091256,-0.373784,-0.150869,-0.200979,-0.698779,-0.076977,-0.260412,0.052800,0.142362,0.055611,-0.088878,0.179715,-0.627392,0.227503,0.173913,0.440229,-0.344392,0.659367,-0.400095,0.269067,0.023529,-0.320374,-0.135194,0.181182,0.456435,0.169499,0.260602,-0.264727,-0.393928,-0.400648,0.207872', '10466639', '20451118', '21619567', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295675', '大丈夫日记', '喜剧', '任职于金融机构的周定发（周润发 饰）。他分别认识了做空姐的Sally（叶倩文 饰）跟开时装店的祖儿（王祖贤 饰）。周定发面对两位天姿国色都无法下决定，难舍其一，于是分别在英国及法国跟两女子结婚。婚后他们回到香港，周定发在好友志雄（李子雄 饰）的帮助下努力周旋与两个老婆之间，笑料百出。可是事情到了后来都是让两个老婆知道了真相，Sally与祖儿气愤不已，打算联合起来报复周定发。©豆瓣', '周润发', '楚原', 7.6, 24546, 'tt0094935', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2258660233.jpg', 0.5, 3.1, 32.5, 46.1, 17.8, '0.315047,-0.310534,-0.595798,0.386443,0.097526,-0.368406,0.233094,0.125504,-0.444588,-0.083134,-0.155705,0.579036,-0.268347,0.517379,0.179038,-0.330235,-0.324312,-0.794274,0.103925,-0.180621,0.104873,-0.585228,0.005696,0.026392,-0.028851,-0.026480,0.239070,-0.041866,0.076207,0.493640,0.790370,0.168041,-0.323654,0.300719,-0.080371,-0.077807,0.071481,0.130090,-0.517275,0.249079,-0.062666,-0.222394,0.023529,0.067677,0.204437,0.346632,0.341691,-0.095865,-0.139388,-0.057943,0.256010,0.053190,-0.143186,0.229829,0.252862,0.159517,0.345091,0.261698,-0.301762,0.032766,0.414713,0.406443,-0.441826,0.342677,0.191363,0.090248,-0.744063,0.306265,-0.122918,-0.150105,0.162860,-0.690943,0.299093,0.502034,0.425038,0.402004,-0.228712,0.072213,-0.438683,0.231483,0.764201,0.189792,0.292515,0.009889,-0.003966,-0.251155,0.002156,-0.084169,-0.392858,-0.116076,0.165661,0.058183,0.065201,0.042286,-0.313040,-0.294766,-0.006584,-0.199554,0.050750,-0.529088,0.259568,-0.372341,-0.207419,-0.580282,-0.339367,0.440365,0.528947,-0.244950,0.624962,-0.650089,0.102753,0.181997,0.456735,-0.845755,0.379402,0.628947,0.201915,-0.302075,0.177215,-0.216472,0.060900,0.066454,0.108537,0.212464,-0.106344,-0.146064,-0.388173,-0.062113', '1297710', '1418613', '1890558', '1316525');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295681', '每天爱你8小时', '剧情', '每天都有24小时，到底该怎么分配才是生活的最合理的方式？张书伟（梁朝伟 饰）是才华横溢的设计师，从事广告工作，屡次被甩的他对爱情已无期待，看着同事兼好友Patrick（方中信 饰）左拥右抱地和固定女友亚芬（童爱玲 饰），暗恋他的同事亚媚（关秀媚 饰）纠缠发展，他更是不敢再爱了。但是凑巧这时候他遇到了清纯与性感兼具的影视新人徐若如（徐若瑄 饰），对方单纯而直接，张书伟一方面在抑制自己对她的感情，一方面又无法抗拒诱惑。与此同时，张书伟又与平时对立的女上司Vivian（蔡少芬 饰）日久生情。面对截然不同的两个人该如何选择，两段感情又该如何收场？关秀媚凭借本片获得台湾金马奖最佳女配角提名。©豆瓣', '梁朝伟', '阮世生', 7.2, 8416, 'tt0178998', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2460357247.jpg', 0.7, 4.3, 43.3, 38.8, 13, '0.051453,-0.206692,-0.455511,0.673098,-0.059989,-0.142937,0.606947,0.232998,-0.316716,-0.019908,0.214971,0.548601,-0.202869,-0.053026,0.096881,-0.104754,-0.178315,-0.754729,0.236747,-0.036774,-0.028056,-0.365384,-0.301524,-0.146258,-0.026654,0.072017,0.866157,-0.148892,-0.174824,0.146735,0.660131,0.285932,-0.098142,0.414087,0.050093,-0.097683,0.016534,0.316709,-0.241385,0.192312,0.293049,-0.311824,-0.139040,0.160168,-0.123605,0.304291,0.610315,-0.045974,-0.130865,0.010303,0.459515,-0.201458,-0.015284,0.016407,0.091243,-0.096547,0.410075,0.140788,-0.242904,0.004072,0.287969,0.062999,-0.701117,0.099998,0.253059,0.136094,-0.448877,0.504272,-0.191152,-0.320347,0.064903,-0.232844,-0.189351,0.432918,0.436592,0.419587,-0.165919,-0.112327,-0.143394,0.532167,0.549911,0.391238,-0.188786,0.574225,-0.290154,-0.589778,-0.126223,-0.508053,-0.475306,-0.157115,0.068420,0.317184,-0.002356,0.072694,-0.468645,0.132484,0.070292,0.150787,-0.028407,-0.726611,0.308381,-0.437066,-0.146208,-0.674534,-0.274504,-0.009088,0.289196,-0.266889,0.771547,-1.027762,-0.159672,0.290624,0.451143,-0.792398,0.669213,0.464106,-0.161673,-0.326024,-0.116347,0.169884,-0.229343,-0.150023,0.042207,0.316171,0.076519,-0.060571,-0.298468,0.250482', '4301278', '6963575', '26354526', '4920528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295684', '一夜风流', '喜剧', '埃伦·安德鲁斯（克劳黛·考尔白 饰）与飞行员金·韦斯特利（詹姆森·托马斯 饰）的婚事遭到了富豪父亲（沃尔特·康诺利 饰）的极力反对。被困在游艇上的埃伦绝食无效，竟跳海逃走去找金。心急如焚的父亲派出侦探对女儿围追堵截，不料聪明的埃伦托人（艾玛·坦西 饰）在侦探眼皮底下买了去纽约的长途车票。旅行计划很完美，可是不谙世事的埃伦不仅行李被偷，还落下车票，错过了班车。而捡到车票的前记者彼得·沃恩（克拉克·盖博 饰）为了把票还给埃伦，选择留在车站等待。失去财富的埃伦与失去工作的彼得之间，会擦出怎样的火花？©豆瓣', '克拉克·盖博', '弗兰克·卡普拉', 8.8, 50131, 'tt0025316', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p692891579.jpg', 0.1, 0.4, 8.7, 41, 49.9, '0.160753,0.032801,-0.682928,0.375338,0.046163,-0.730491,0.431345,0.147673,-0.197597,-0.172480,-0.059637,0.599658,-0.092944,-0.008372,0.544159,0.121207,-0.549030,-0.479963,0.151199,-0.009232,-0.339422,-0.573520,-0.047422,-0.158417,-0.000198,-0.243228,0.239131,0.051081,0.099228,0.499337,0.636962,0.507646,-0.078600,0.378221,-0.120794,0.199419,-0.053959,-0.073487,-0.194302,0.468567,0.246791,0.041005,0.140931,-0.070455,0.359267,0.261085,0.525927,-0.058660,0.307637,0.024822,0.285227,-0.271237,0.190299,0.129638,0.293572,0.035874,-0.111763,-0.184307,-0.453431,0.167894,0.343367,-0.065720,-0.349971,0.095306,0.076688,0.107781,-0.790959,0.336715,-0.397756,0.112513,0.089983,-0.555516,0.079411,0.245905,-0.032450,0.012326,0.071638,0.047904,-0.655668,0.022315,0.267783,0.019961,0.265513,0.098807,-0.145434,-0.194824,0.005697,-0.227262,-0.425945,0.020516,0.392957,-0.056009,0.001124,-0.010397,-0.635633,-0.382684,-0.598377,-0.224967,0.068410,-0.314968,-0.205048,-0.763263,0.194818,-0.153506,-0.184985,0.129669,0.098021,-0.101768,0.304575,-0.549470,0.128634,0.583085,0.319210,-0.230167,0.578810,0.004036,0.126139,-0.067161,-0.119427,0.256054,0.390026,0.414012,0.187698,-0.061208,0.078629,-0.159179,-0.116928,0.400547', '1293511', '1292222', '3326747', '3183490');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295686', '盗火线', '剧情', '文森特•汉纳（阿尔•帕西诺 饰）是洛杉矶警局重案组的探长，工作积极投入，打击犯罪毫不手软，因此，家庭生活危机重重，目前的第三次婚姻也面临解体；尼尔•麦考利（罗伯特•德尼罗 饰）是职业匪徒，混迹江湖多年，做事干净利落，而且心狠手辣，不留后患，组织手下成功抢劫运钞车的案子，使他受到了警方的“特别关注”。一个偶然的机会，尼尔认识了平面设计师伊迪，两人一见钟情，再看到手下都有安定的家庭生活，尼尔也想把握自己的幸福，遂萌生退意。然而，在最后一次抢劫银行的行动中，因为叛徒的出卖，手下一死一伤，本已逃出的尼尔，带着伊迪在去机场的路上，得知了叛徒的消息，他决定替手下报仇，同时也和文森特•汉纳进行最后的较量……©豆瓣', '阿尔·帕西诺', '迈克尔·曼', 8.5, 114506, 'tt0113277', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792508289.jpg', 0.2, 1, 12.9, 44.2, 41.6, '0.049987,-0.143331,-0.621683,0.344215,-0.218755,-0.281963,0.466948,0.046774,-0.607456,-0.093496,0.388352,0.667784,0.255862,-0.095871,0.386031,-0.200131,-0.377593,-0.640588,0.150573,-0.063349,-0.247997,-0.640663,-0.281339,-0.429478,-0.068884,-0.245076,0.383837,0.112549,0.021441,0.467605,0.179980,0.267892,-0.041676,0.472433,0.269603,-0.136145,0.366829,-0.187622,-0.460294,0.164520,-0.070494,-0.063169,-0.115293,0.119607,0.205706,0.525510,0.414210,0.171165,-0.098314,-0.183367,0.127615,-0.236066,-0.041468,0.018359,0.367527,-0.062113,0.098696,0.473531,-0.096863,-0.332977,-0.159641,-0.103694,-0.951975,0.068972,0.067532,0.065076,-0.644201,0.337303,-0.212365,0.148830,-0.020838,-0.184524,0.193034,0.524211,0.638720,-0.079572,-0.112819,0.148043,-0.438045,0.026024,0.606536,-0.152704,-0.046075,-0.005858,-0.197987,-0.352101,-0.014047,-0.336145,-0.247306,-0.093277,0.334252,-0.111666,-0.303678,0.121698,-0.373978,-0.163431,-0.373526,-0.088384,-0.009128,-0.368584,0.108460,-0.698523,-0.162614,-0.124501,-0.468238,0.148199,-0.030324,-0.165158,0.506464,-0.714986,0.208912,0.647584,0.234644,-0.622612,0.587848,0.267263,0.254729,-0.264161,-0.137196,0.336493,0.180471,0.390802,0.179431,0.079471,-0.026041,-0.392228,0.010188,0.176859', '26678784', '1793491', '1307442', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295703', '火山高校', '动作', '历经十七年混战的火山高校内部派系林立，传说中，谁拿到武林秘笈就可以号令天下，创立108年的火山高因此动荡不安……身怀超能力的转校生金英俊（张赫 饰）在火山高的第一天就颇不寻常，举重队黑牛帮的张良（金秀路 饰）、剑道部校花当家柳采怡（申敏儿 饰）以及学校头号战将——同样拥有超能力的茶道部松学林（权相宇 饰）纷纷粉墨登场，金英俊珍惜最后的转校机会，处处隐藏实力求平安。犹如闲云野鹤一般的校长意外中毒，由其保管的武林秘笈顿时成为众矢之的，副校长苦寻未得，而张良趁松学林作为嫌疑犯被关押，在校内大开杀戒，连番混战中，一股更强大的力量进入学校参与秘笈之争……©豆瓣', '张赫', '金泰均', 5.9, 7144, 'tt0301429', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p742533398.jpg', 6.5, 19.7, 51, 17.7, 5.2, '-0.016544,0.090597,-0.445597,0.315241,0.142626,0.005231,0.102318,0.049312,-0.635493,-0.339722,0.331588,0.433789,-0.111863,0.141382,-0.099067,-0.275094,0.218267,-0.625744,-0.192624,-0.218632,-0.186475,-0.034584,-0.435801,0.068545,-0.081913,-0.359262,0.550097,0.063620,-0.321473,0.415085,0.098851,0.209621,0.032122,0.044250,-0.240164,-0.343095,0.013684,0.343281,-0.285768,0.200141,-0.308486,-0.167036,-0.222286,-0.004552,0.156962,0.045187,0.312050,-0.075699,0.169643,-0.221324,0.582215,-0.119710,-0.175452,0.044193,0.588139,0.048800,0.261131,0.268282,0.052940,0.174802,-0.162962,-0.275904,-0.640754,-0.066629,0.412856,0.225248,-0.096889,0.445467,0.125887,-0.291978,0.022016,0.003971,-0.004978,0.145554,0.241441,0.200072,-0.090830,0.125424,-0.445654,0.279791,0.465840,-0.179954,-0.208465,-0.212414,0.140233,-0.470256,-0.101172,-0.468672,-0.248975,0.045378,0.367312,0.109935,0.368113,0.338920,-0.422505,-0.021514,-0.087677,0.304110,-0.050343,-0.045074,-0.164984,-0.429130,-0.094958,-0.014440,-0.087077,-0.020721,0.302397,-0.189408,0.991676,-0.679943,0.162973,0.073067,0.048907,-0.465543,0.367099,-0.017241,0.148864,-0.181067,-0.186587,0.079435,0.268896,0.451525,-0.054964,0.370104,-0.226745,-0.407274,0.037860,0.124017', '27602116', '24284209', '25922902', '1920765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295713', '危险关系', '剧情', '侯爵夫人梅特伊（格伦·克洛斯 Glenn Close 饰）和恶名昭彰的浮华浪子瓦尔蒙（约翰·马尔科维奇 John Malkovich 饰）是两个在情场可互相匹敌的朋友，利用性当作武器，去抵毁对方的名誉与地位。一日，梅特伊提出让瓦尔蒙去勾引16岁的贵族少女塞西尔（乌玛·瑟曼 Uma Thurman 饰），使其失身从而身败名裂。而瓦尔蒙却认为这样太缺乏挑战，他非但引诱了纯洁的塞西尔。还追加赌注勾引虔诚、美貌素以贞节著称的杜维尔夫人（米歇尔·菲佛 Michelle Pfeiffer 饰）。最终杜维尔夫人投入了他的怀抱，而瓦尔蒙也渐渐真心爱上了杜维尔。梅特伊心生妒火，让自己的音乐教师兼新情人唐斯尼（基努·李维斯 Keanu Reeves 饰）替她报复，结果，瓦尔蒙在与唐斯尼决斗时死于剑下，杜维尔伤心致死，而梅特伊也因此名誉扫地。©豆瓣', '格伦·克洛斯', '斯蒂芬·弗雷斯', 7.6, 10700, 'tt0094947', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1427106020.jpg', 0.5, 3, 29.9, 47.1, 19.5, '-0.025302,-0.119405,-0.333692,0.555325,-0.477376,-0.319634,0.666811,0.306880,-0.297401,-0.164287,0.125293,0.772799,-0.076199,0.170232,0.489563,0.269697,-0.133356,-0.618952,0.184697,0.031189,0.055295,-0.586364,-0.199699,-0.231359,0.112463,-0.270314,0.314214,0.081394,-0.364340,0.367711,0.388773,0.344118,0.282298,0.501776,0.223087,0.010980,0.000172,-0.172523,-0.010900,0.183912,-0.101693,-0.227890,-0.144436,0.302741,0.117519,0.420634,0.297537,-0.291568,0.291634,-0.143861,0.365600,-0.223221,0.454037,0.287635,0.008180,-0.593148,-0.039185,0.021351,-0.190039,-0.002965,0.359000,-0.159976,-0.607504,0.267868,-0.016278,-0.205791,-0.634356,0.408491,-0.186260,0.076395,-0.027563,0.058771,-0.144064,0.034463,0.146968,-0.087893,-0.297496,-0.141058,-0.462177,0.219176,0.198294,0.280058,-0.156738,0.088099,-0.208605,-0.414189,-0.153685,-0.539366,-0.561988,-0.366707,0.353112,-0.126380,0.171878,0.245156,-0.402196,-0.483160,-0.317018,0.167655,0.060697,-0.504355,0.282742,-0.511452,-0.206174,-0.393937,-0.164547,-0.296829,0.202598,-0.432423,0.444098,-0.513128,0.138457,0.527351,0.062494,-0.655460,0.480876,0.385318,0.116831,0.209379,-0.227260,0.734585,0.376421,0.014520,0.188825,0.250052,0.194244,0.207528,0.051335,0.503228', '1299799', '3119246', '34890458', 