INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295733', '火线狙击', '剧情', '肯尼迪总统的遇刺让身为他贴身保镖的弗兰克（克林特·伊斯特伍德 Clint Eastwood 饰）陷入了自责的情绪中不能自拔。即使多年过去，但只要一想到此时，弗兰克总觉得是自己的失职和大意造成了这一悲剧。某一日，一个神秘的电话引起了他的警觉。打电话的男人名叫米奇（约翰·马尔科维奇 John Malkovich 饰），他告诉弗兰克，自己准备暗杀现任总统，并邀请弗兰克玩一个所谓的“游戏”，这个游戏的成败将直接影响总统的命运。往事重演，这一次，弗兰克决定无论如何都要保护总统的安全。这个米奇到底是谁？他这么做的目的何在？在一连串的疑问面前，一场激烈而又危险的追杀游戏逐渐展开。©豆瓣', '克林特·伊斯特伍德', '沃尔夫冈·彼德森', 7.3, 6223, 'tt0107206', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2364488947.jpg', 0.3, 2.4, 39.4, 47.1, 10.8, '0.180093,0.116864,-0.737597,0.668902,-0.165177,-0.243267,0.766559,0.047908,-0.456688,-0.412979,0.280157,1.086480,-0.214364,0.023820,0.401839,0.093174,-0.290672,-0.653806,-0.048200,-0.065336,-0.187980,-0.580783,-0.299278,-0.297880,0.253556,-0.111282,0.209960,0.046933,-0.321833,0.509267,0.600837,0.351625,0.182056,0.622308,0.452096,-0.068865,0.264399,-0.131311,-0.107748,0.122426,0.300158,-0.259129,0.025672,0.632338,0.011115,0.426470,0.260513,-0.352488,-0.455247,0.014964,0.407060,-0.537043,-0.076288,0.020286,0.251037,-0.057218,-0.099603,0.271033,-0.274896,-0.080076,0.132410,0.118140,-1.071221,0.094563,-0.263601,0.183299,-0.465980,0.090576,-0.195460,-0.022403,-0.074016,-0.120923,0.299316,0.559629,0.465424,0.120382,-0.368440,0.037642,-0.293449,0.016848,0.838790,-0.060858,-0.063667,0.142369,-0.010480,-0.207975,-0.042443,-0.188552,-0.533109,-0.024448,0.274209,-0.043108,-0.169698,0.165106,-0.318277,-0.134929,-0.339009,-0.315262,-0.269483,-0.548304,-0.007377,-0.099996,-0.206300,-0.216233,-0.424745,-0.063764,0.111955,-0.142200,0.573818,-0.706196,0.343074,0.869975,0.079379,-0.574222,0.477620,0.633281,0.190710,-0.097211,-0.035822,0.193276,0.148611,0.160008,-0.045508,0.310767,0.364190,-0.283440,-0.273504,0.312414', '26678784', '34890458', '30216729', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295742', '洛奇', '剧情', '洛基•巴尔博厄(西尔维斯特•史泰龙 Sylvester Stallone 饰)是费城的过气拳击手。他空有拳击热忱，却只混杂于三流拳击赛中。一天，他对售货员艾黛丽安（塔里亚•希雷Talia Shire 饰）一见倾心，虽然这个姑娘长相一般，性格内向，却毫不阻碍洛奇对她爱得炽热。爱情得意，事业也开始一路畅通。为了庆祝美国建国200周年，当地举办了一个拳击比赛，胜出者将获得15万美元的高额奖金。美国一个拳击巨星在比赛中受了伤，主办方选中了洛奇去上演一场“灰姑娘”式的比赛，大敌当前的同时，也是洛奇事业转机、大显身手的良机。洛奇在赛场上苦撑15回合，在面肿血流之际，会不会有奇迹的发生？©豆瓣', '西尔维斯特·史泰龙', '约翰·G·艾维尔森', 8.7, 58128, 'tt0075148', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453792998.jpg', 0.2, 0.6, 9.5, 41.4, 48.4, '-0.098875,0.217196,-0.524012,0.285029,-0.135419,-0.309818,0.501087,0.004673,-0.191467,0.104268,0.610815,0.822556,-0.525886,-0.071266,0.246644,-0.082584,0.008669,-0.733658,0.096327,0.114413,0.033079,-0.284916,-0.346512,-0.020931,-0.170917,-0.205111,0.511006,-0.025908,-0.187813,0.648968,0.427785,0.185910,0.315286,0.358980,-0.193497,-0.146437,0.047159,0.013085,-0.213420,0.253190,0.090572,-0.225540,-0.300263,0.154902,0.081704,0.376284,0.447421,-0.019594,0.196804,-0.123913,0.304289,-0.276810,-0.027951,0.248465,0.188182,-0.163011,0.343076,0.002173,0.104086,0.096028,0.060623,-0.109197,-0.467597,-0.052437,0.017590,0.468344,-0.374318,0.880274,-0.289871,-0.167975,0.008606,-0.059140,-0.196769,0.352797,0.266780,0.164758,-0.112587,-0.033704,-0.450326,0.275094,0.729915,-0.058563,-0.229523,0.390009,-0.027332,-0.497212,0.054284,-0.279375,-0.268326,0.059259,0.532733,-0.152876,0.188447,0.373257,-0.601807,0.273289,-0.296077,-0.264107,-0.226795,-0.295769,-0.014336,-0.611085,0.093599,-0.270877,-0.232909,0.128725,0.200025,-0.343616,0.528507,-0.805304,0.042749,0.635135,0.223401,-0.021387,0.580761,0.253232,0.058414,0.001932,-0.066487,0.093621,-0.310550,0.062738,-0.096110,0.499601,0.196353,-0.166098,-0.077057,0.795026', '3139191', '4202326', '11541282', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295746', '黑侠', '喜剧', '徐夕（李连杰）本是神秘杀手组织701部队里的一名冷血杀手，因为不想再做杀人工具，他逃离了该组织来到香港化身为一名普通的图书馆理员，因此结识警察石SIR并与之成为好友，不想701部队为追杀黑帮头目突然现身香港，一时石SIR及警方均束手无策，见好友处于危难中，徐夕挺身而出化 为黑侠。黑侠让701部队的首脑熊菊（龙刚）大为震怒，遂派徐夕旧情人若兰规劝黑侠归顺，被徐夕断然拒绝，结果令图书馆除Tracy（莫文蔚）之外的诸同事皆丧命。为保护Tracy，徐夕再做黑侠采用强硬态度要带她走，遭不知黑侠就是其意中人徐夕的Tracy的拒绝。后在与熊菊一干人等对抗的过程中，徐夕渐从Tracy身上寻到自己想要的情感。©豆瓣', '李连杰', '李仁港', 6.9, 36465, 'tt0115693', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2398005166.jpg', 0.9, 7.1, 50.3, 31.8, 9.9, '0.241923,-0.034485,-0.595471,0.491177,0.046292,-0.107624,0.541071,0.043857,-0.626038,-0.533911,0.134812,0.678642,0.063659,0.264647,0.331248,-0.461925,-0.110583,-0.668165,-0.240317,-0.172254,-0.240929,-0.139904,-0.078651,-0.180735,-0.328265,-0.140187,0.735499,0.155280,-0.332049,0.454757,0.413102,0.594343,-0.285963,0.571532,0.165846,-0.322743,-0.004597,-0.019890,-0.438047,0.293163,-0.155973,-0.401753,-0.191642,0.225750,-0.172711,0.366738,0.456321,-0.135165,-0.056053,-0.362186,0.108843,-0.362321,0.077415,-0.072248,0.291978,-0.004478,0.159189,0.211927,-0.086823,0.135897,0.083757,0.104451,-0.940145,0.163339,0.213113,-0.057616,-0.641989,-0.057802,-0.217097,0.020956,-0.017223,-0.102775,0.333046,0.414490,0.238453,0.210320,-0.083223,0.006788,-0.306085,0.090215,0.700014,-0.126648,0.134970,-0.193187,0.292537,-0.475493,0.398384,-0.425289,0.010770,-0.038652,0.014064,0.082937,0.079777,0.086256,-0.544770,-0.191798,-0.330224,0.016180,-0.080127,-0.378789,-0.039820,-0.580538,0.076468,0.071735,-0.014111,0.290103,0.247419,-0.030638,0.494115,-0.842665,0.071701,0.267388,0.374143,-1.014960,0.518544,0.148614,0.163762,-0.180719,-0.116066,0.081419,0.352818,0.358714,0.165290,-0.018203,-0.013237,-0.381873,-0.338812,-0.262785', '26678784', '1293265', '3811342', '10604851');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295749', '王牌特派员', '喜剧', '因和女友洛萍·哈瑞斯（莱丝莉·曼 Leslie Mann 饰）发生不快，房地产经营上史蒂夫·考维克斯（马修·布鲁德里克 Matthew Broderick 饰）被迫搬到一幢新的公寓。不久，有线电视安装人员杜哲（吉姆·凯瑞 Jim Carrey 饰）登门拜访。杜哲举止乖张，为人却颇为幽默开朗。两人由此成为好朋友，更相约外出游玩。在杜哲的指点下，史蒂夫成功赢回女友的芳心。然而杜哲似乎过于热情，他越来越多介入到史蒂夫的生活当中，令后者渐感烦躁和不安。史蒂夫开始有意识地远离这个不太正常的家伙，感觉被好友抛弃的杜哲由此暗升报复之心…… 本片荣获1997年儿童选择奖最受欢迎男主角奖（Jim Carrey）。©豆瓣', '金·凯瑞', '本·斯蒂勒', 6.7, 6454, 'tt0115798', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177762576.jpg', 1.6, 9.2, 51.3, 27.4, 10.5, '0.391267,-0.118343,-0.662243,0.137600,-0.050774,-0.269316,0.555877,0.074054,-0.505223,-0.274591,0.198025,0.659740,-0.487868,0.216799,0.562154,-0.065304,-0.476785,-0.265164,0.172964,-0.006797,0.119254,-0.265488,-0.237781,-0.150622,-0.253814,-0.417079,0.499312,0.022897,-0.148047,0.450569,0.092256,0.426434,0.143891,0.453452,0.097444,0.016334,0.224454,-0.146644,-0.192460,0.121441,-0.063536,-0.211644,-0.123093,0.047530,0.194810,0.353904,0.677992,0.074957,-0.266333,-0.046601,0.442950,-0.095002,-0.105626,-0.035124,0.090733,0.107929,-0.016497,0.031918,-0.319096,0.089024,-0.033966,-0.245413,-0.339169,0.374759,0.119756,0.074710,-0.240260,0.210508,-0.279366,0.166263,-0.057577,-0.367788,-0.089923,0.237185,0.233690,0.089895,-0.121234,0.112193,-0.240665,-0.009539,0.723662,0.155125,-0.133923,0.245813,-0.313523,-0.400933,0.166558,-0.109232,-0.450604,-0.175113,0.193025,0.011069,0.241749,0.367856,-0.543820,-0.112245,-0.160049,0.080854,0.011521,-0.342106,0.017259,-0.713376,-0.035851,-0.334781,-0.077665,-0.277591,0.031433,-0.435669,0.371633,-0.727894,0.036811,0.305164,0.407761,-0.330296,0.290253,-0.135677,0.169192,-0.296262,-0.191408,0.313736,0.001286,-0.145169,0.110687,0.333015,-0.173941,-0.366984,-0.223992,0.350207', '11541282', '1498831', '1291992', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295753', '日出', '剧情', '盛夏的度假时节，一位城市女人来到乡下滞留，这期间，城市女人诱惑了当地的农夫并教唆他杀死自己的妻子（Janet Gaynor 饰）以便贩卖掉农庄后私奔。被迷惑了心窍的男人早已忘记了那些同妻子共处的纯美时光，他将妻子带到河面蓄谋加害，却在要下毒手时幡然悔悟，伤心的妻子踏上了进城的列车，男人穷追不舍一同抵达城市。城市里真正是一片花花世界呵，这对夫妻在街上游走玩乐，在那些小小的玩笑中，甜蜜的冒险中，他们又找回了爱情的美妙共鸣……和好如初的两人返回乡村，不料却在归途遇上了肆虐的风浪……本片是德国导演茂瑙赴美发展后拍摄的第一部作品，曾被多家权威媒体评选为默片最佳杰作之一，获第一届奥斯卡最佳女演员、摄影等多项褒奖。©豆瓣', '乔治·奥布莱恩', 'F·W·茂瑙', 8.8, 14275, 'tt0018455', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1443400002.jpg', 0.3, 0.9, 8.6, 38.9, 51.4, '0.150984,0.056798,-0.744807,0.465606,-0.039141,-0.141903,0.837464,0.192239,-0.502944,0.084043,0.387448,0.681624,-0.367831,0.256593,0.261002,-0.028452,-0.308129,-0.626058,-0.090843,-0.346410,-0.085085,-0.099798,-0.264710,-0.000643,-0.095121,-0.233117,0.736490,0.301713,-0.236037,0.303296,0.320614,-0.105488,-0.325399,0.522975,-0.466742,0.095763,0.207257,0.142317,-0.412047,0.335074,-0.327311,-0.392884,-0.141763,-0.069776,-0.234480,0.275676,0.901573,-0.115860,-0.012689,-0.194881,0.447018,-0.307664,0.053269,0.031812,0.194863,-0.179613,0.226454,0.129746,-0.282158,-0.016301,0.015130,-0.196011,-0.480192,0.174512,0.142795,-0.103511,-0.771783,0.434844,0.188999,-0.095880,0.005407,-0.071126,0.468092,0.238757,0.238010,0.429639,0.111214,0.144129,-0.372115,0.532005,0.717733,-0.205183,-0.197130,0.473258,-0.250834,-0.337454,0.234738,-0.337615,-0.601613,-0.151150,0.269184,-0.171786,-0.197981,0.147749,-0.557469,0.039876,-0.264041,-0.165581,0.035962,-0.350408,-0.229450,-0.731116,-0.050930,-0.269397,-0.070798,0.052573,0.126403,-0.195853,0.557738,-0.736103,0.204057,0.800078,0.374999,-0.536295,0.820159,0.152279,0.090950,-0.191360,-0.140775,0.412573,-0.045987,0.336978,-0.028797,0.235299,-0.159951,-0.147490,-0.473899,0.456023', '3326747', '21619567', '3055049', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295773', '致命快感', '动作', '美艳的神秘女郎爱伦（莎朗·斯通 Sharon Stone 饰）突然闯进美国西部一个充满暴力的小镇，为了一段不堪回首的回忆而开展复仇。在她到达小镇后不久，一位名叫科特的牧师（罗素·克劳 Russell Crowe 饰）也来到小镇。与此同时，蜂拥而至的神枪手们也从四面八方纷纷赶来。而让他们趋之若鹜的原因，是一场以巨额奖金为诱饵的枪击比赛。比赛只有一条规则，就是完全遵守大魔王赫罗德（吉恩·哈克曼 Gene Hackman 饰）的规则。赫罗德借此向镇民们征收大量税金。不仅如此，只手遮天、无恶不作的赫罗德更想通过这次枪击比赛，让高手们彼此厮杀，从而坐享渔翁之利。残酷的枪击比赛没有丝毫人性可言，半决赛中，赫罗德甚至亲手杀死了自己的儿子基德（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）。终于，一场扣人心弦的生死决斗在科特与赫罗德之间展开了。©豆瓣', '莎朗·斯通', '山姆·雷米', 6.8, 5983, 'tt0114214', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358790428.jpg', 1.3, 8.6, 50.7, 28.9, 10.5, '0.079116,-0.058411,-0.492350,0.632441,-0.036200,-0.321631,0.723655,-0.149305,-0.285947,-0.103513,0.324550,0.704316,-0.273383,-0.058118,0.431542,-0.350891,-0.215171,-0.680978,-0.231762,-0.102001,-0.373651,-0.517726,-0.277120,-0.207241,0.015452,-0.397500,0.691271,0.177314,-0.265565,0.519728,0.408792,0.336021,-0.102503,0.355794,-0.062111,-0.198638,0.290012,-0.031190,-0.402998,0.272533,-0.302621,-0.112257,-0.505611,0.190686,-0.054736,0.408544,0.680518,-0.516972,0.125731,-0.145130,0.199184,-0.263588,0.051237,0.281653,0.154871,-0.161257,0.299928,0.241043,-0.070034,0.111854,0.054396,-0.260869,-0.655660,0.157940,-0.095830,0.154350,-0.240955,0.379997,-0.041338,-0.141207,0.191857,-0.067662,0.093636,0.460565,0.268955,0.168591,-0.335338,-0.282866,-0.436956,0.039922,0.707288,-0.044124,-0.175188,0.198621,-0.042360,-0.424688,-0.101029,-0.205823,-0.316087,-0.100657,0.583256,-0.151183,0.112277,0.500932,-0.873121,0.011078,-0.411546,-0.488231,-0.090002,-0.185395,-0.012862,-0.928526,-0.072940,0.000715,-0.156705,0.280524,0.144052,-0.125137,0.684589,-0.684687,0.248469,0.488753,0.143141,-0.403871,0.297422,0.153284,0.231869,-0.111903,-0.252260,0.177345,0.374973,0.333847,0.064608,0.313575,0.001439,-0.318757,-0.151486,0.632562', '20274039', '11541282', '1294917', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295782', '老夫子2001', '喜剧', '老夫子漫画的主编王泽决定封笔，导致本来衣食无忧的漫画人物老夫子和大番薯顿时成了失业青年，两人出尽招数找工作却屡屡碰壁。这日，CID峰（谢霆锋 饰）和女友Miss张（张柏芝 饰）正因张母反对二人在一起而苦恼，老夫子和大番薯因得罪黑社会老大金爷被追杀，引发了一场大车祸。车祸中峰和Miss张失去了记忆，痊愈后两人形同陌路。金爷十分看好峰，认为他是自己最合适的接班人，于是骗峰说自己是他的契爷，峰加入了黑社会。同时，Miss张恢复了一点记忆，回到了学校教书。一次峰在拉学生加入黑社会时，遇到了Miss张。峰对Miss张一见钟情，展开了猛烈追求。Miss张因记起自己已有一位恋人而拒绝了峰，峰陷入了低谷。这时，金爷发现峰加入后自己一直倒霉，于是准备除掉峰。关键时候，老夫子和大番薯赶到了！©豆瓣', '谢霆锋', '邱礼涛', 5.9, 17074, 'tt0199898', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2356564685.jpg', 4, 20, 57.4, 13.7, 4.9, '0.203255,0.025230,-0.430099,0.606523,0.009830,-0.428192,0.461660,0.252705,-0.592882,-0.266823,-0.148751,0.966425,-0.345501,0.906680,0.145942,-0.250646,-0.095715,-0.608919,0.035039,-0.112155,-0.492502,-0.274046,0.296508,0.062444,-0.173293,-0.104665,0.474891,0.208151,-0.557348,0.518194,0.394521,0.157152,-0.017134,0.623544,-0.027474,0.194411,-0.121830,0.118283,-0.312744,-0.038105,0.367684,-0.333534,-0.356946,0.006395,0.220615,0.377368,0.561055,0.049548,-0.517067,-0.164793,0.238435,-0.390756,-0.140545,-0.128105,0.709388,-0.005925,0.163634,-0.013563,-0.297841,-0.014198,-0.242408,-0.312185,-0.299813,0.144102,0.143755,-0.258388,-0.626585,0.443116,0.114651,0.058370,0.023823,-0.294065,0.266768,0.416483,0.038796,0.111519,-0.049488,0.031582,-0.432470,0.414193,0.783728,-0.102023,0.113409,0.335882,0.517762,-0.230553,-0.118056,-0.242719,-0.106364,0.324984,0.490204,-0.102824,-0.174438,0.123508,-0.330323,-0.247878,-0.302965,0.007506,0.004554,-0.283623,-0.172734,-0.508653,-0.317738,0.078696,-0.142753,0.312988,-0.198463,-0.225479,0.592226,-0.835636,0.130940,-0.081546,0.268430,-0.616383,0.520655,-0.199987,-0.048963,-0.513658,-0.029936,-0.021296,0.053227,0.214143,0.484385,0.094837,-0.204424,-0.244110,-0.069957,0.340906', '1292219', '25721544', '1307922', '27135473');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295783', '死亡密码', '剧情', '犹太天才数学家马克西·米利安·科恩（希恩·格莱特 Sean Gullette饰）痴迷沉醉于数字的世界，他认为一切自然界的事物都可以用数字解释。他潜心研究，试图透过数字推演出种种生命迹象背后的奥秘和规律。可越是逼近答案，他越是无法忍受致命的头痛。他发现了过去十年来股票市场的混乱波动，其实是由背后的一套数学模式在操纵。与此同时，他的研究引来了华尔街股票市场的炒家们和犹太神秘教派的注意。在介乎真实与虚拟的世界中，马克西正在走向疯狂。1996年2月，阿伦诺夫斯基开始筹备这部成本只有六万美元的长片处女作。两年后，《死亡密码》以其新颖的创意和崭新的拍摄手法，一鸣惊人。先是斩获圣丹斯电影节的导演奖，翌年又摘得独立精神奖的最佳编剧处女作奖。2000年，他再次自编自导了《梦之安魂曲》，也赢得了不错的反响。2005年，他还入围“最需要关注的好莱坞100人”。©豆瓣', '肖恩·格莱特', '达伦·阿伦诺夫斯基', 7.5, 9610, 'tt0138704', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1349989987.jpg', 1.7, 5.4, 30.1, 43.3, 19.5, '0.022067,0.058143,-0.726256,0.536579,0.107899,0.106036,0.481232,-0.178149,-0.528538,-0.107659,0.007736,0.606777,-0.374192,0.011517,0.300668,0.021619,-0.309536,-0.861178,-0.111498,-0.422985,-0.060726,-0.476528,-0.468804,-0.288546,-0.077744,-0.592544,0.577889,0.256310,-0.244324,0.119536,0.252462,0.116968,0.093319,0.404910,0.006107,-0.010039,0.007155,-0.090632,-0.274827,0.217063,0.101578,-0.384231,-0.280191,0.283718,-0.128171,0.201660,0.676005,-0.436306,0.136817,0.133385,0.689218,-0.244521,-0.182437,-0.190407,0.136897,0.161115,0.258418,0.269160,0.019564,0.066398,-0.185214,-0.241739,-0.991510,-0.052087,0.140498,0.193272,-0.453529,0.175439,-0.115015,-0.002928,-0.179121,-0.311083,-0.018551,0.080664,0.464642,0.365393,-0.231186,-0.141055,-0.188615,0.389766,0.218036,-0.107819,-0.573803,0.571005,-0.169959,-0.589283,-0.382606,-0.276189,-0.249664,0.056994,0.395977,0.267152,0.017488,0.200286,-0.530942,0.236108,0.042518,-0.459005,-0.062468,-0.306716,-0.129936,-0.681166,-0.284715,-0.225575,-0.222440,-0.218812,0.081589,-0.445409,0.795530,-0.548981,0.089670,0.570123,0.243727,-0.173604,0.694368,-0.193907,-0.231796,-0.376588,-0.321408,0.251771,-0.257398,0.089337,-0.058977,0.320838,0.206276,-0.274519,-0.281567,0.609554', '3318306', '27602116', '25928048', '1303263');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295802', '勇者无惧', '剧情', '1839年，运送黑奴的阿米斯塔德号在大洋上遭遇暴风雨，黑奴们趁乱暴动，将船员砍杀，控制了阿米斯塔德号后试图驶回家乡，然而六周后，他们阴差阳错抵达了美国，幸存下来的44名黑奴被美国军方逮捕，并将面临杀人罪的指控。此时，西班牙女王向美国总统要求引渡这些属于西班牙的黑奴；两名海军军官也宣称黑奴是他们的战利品；另有人拿出了在古巴购买这些黑奴的证明。各方争执之际，废奴会的领袖之一、同时也是船公司负责人的乔德森（摩根·弗里曼 Morgan Freeman 饰）与友人塔培安雇佣了律师罗杰，希望证明这些黑奴来自非洲，从而在废奴观念深入人心的大环境下为他们谋取自由……©豆瓣', '摩根·弗里曼', '史蒂文·斯皮尔伯格', 8.2, 7437, 'tt0118607', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187209224.jpg', 0.5, 1.6, 16.9, 50.1, 30.9, '0.446200,0.142468,-0.492368,0.413195,-0.167316,-0.273590,0.474757,0.155213,-0.507501,-0.035602,0.191028,0.833191,0.070200,-0.003144,0.325210,0.036287,-0.468277,-0.653271,-0.371472,-0.293666,-0.169051,-0.442714,-0.270664,-0.362680,-0.239102,-0.281426,0.529798,0.110531,-0.120959,0.500099,0.285694,0.616075,0.065263,0.276307,-0.233556,-0.121819,0.268339,-0.466301,-0.413423,0.441743,-0.285497,-0.188539,0.102800,0.232013,0.168172,0.523157,0.600732,-0.381400,0.171518,-0.232497,0.192346,-0.241506,0.153925,0.313337,0.427626,0.157377,-0.181071,0.344044,-0.193053,-0.020067,0.049282,0.109939,-0.654156,0.065349,-0.187179,0.066087,-0.712204,0.204137,-0.266181,0.265621,-0.146587,-0.117675,0.373535,0.748271,-0.043667,0.259868,0.105525,-0.005621,-0.718679,0.233487,0.822480,-0.186607,-0.167100,-0.288401,-0.242540,-0.487269,0.121393,-0.188877,-0.086229,-0.331237,0.534508,-0.098836,-0.041858,0.369014,-0.850907,0.131228,-0.481260,-0.677502,0.077861,-0.324364,-0.074202,-0.865254,0.048261,-0.159390,0.013473,0.054124,0.382528,0.086153,0.963964,-0.560851,0.216142,0.863996,0.524786,-0.486529,0.437391,-0.221488,0.217047,-0.109848,-0.142470,0.116016,0.442883,0.525948,0.194013,0.123189,-0.055403,-0.234771,-0.020815,0.232234', '3147969', '3811356', '2294565', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295804', '贝隆夫人', '剧情', '艾薇塔（麦当娜 Madonna饰）和当时在阿根廷颇为走红的歌手一夜情后，就以此为跳板踏上了前往布宜诺斯艾利斯之路。这个美丽的少女，就是日后名气大震的贝隆夫人。可是，15岁的艾薇塔一无所有，她被抛弃在陌生的城市里，唯一的资本就是自己的美貌。艾薇塔挤入了上流圈子，成为名流男士中间的交际花。随之而来的，是她进军娱乐圈取得的不俗成绩。她一跃成为名人，并在慈善会上结识了贝隆上校（乔纳森·普雷斯 Jonathan Pryce饰），二人情投意合。艾薇塔从此正式登上了政治舞台。她当上了贝隆政治生涯的贤内助，并一直主张为穷人谋利益。政治的世界风云幻变，而艾薇塔也渐渐找到实现自己政治理想的路径，并为此努力一生，成为阿根廷民众心中的“第一夫人”。©豆瓣', '麦当娜', '艾伦·帕克', 7.7, 16586, 'tt0116250', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1402610916.jpg', 0.6, 3.2, 29.8, 45.5, 20.9, '0.066032,0.382231,-0.546642,0.658500,-0.246855,-0.321616,0.315148,0.141192,-0.559352,-0.068303,0.083070,1.096347,-0.148990,0.248398,0.467082,0.068513,-0.083113,-0.914884,-0.004321,-0.281727,-0.054945,-0.310931,-0.334636,-0.127148,-0.429385,-0.364387,1.012447,0.304923,-0.278297,0.365789,0.470724,0.091985,0.217548,0.379953,-0.264777,-0.018953,0.106467,0.040691,-0.447567,0.213669,-0.266728,-0.358338,0.011842,0.197139,-0.143798,0.212475,0.365031,-0.185366,0.259134,-0.090964,0.473311,-0.342117,-0.041466,-0.018838,0.155233,-0.142266,0.056447,0.232499,-0.098352,0.058568,-0.014104,-0.369406,-0.672855,-0.048833,0.185240,0.083664,-0.621642,0.595622,-0.010849,-0.342080,0.012319,-0.143615,0.102903,0.288313,0.160844,0.163746,-0.224415,0.347879,-0.429231,0.343449,0.665314,0.363564,-0.318055,0.276719,-0.252995,-0.650812,-0.013426,-0.317281,-0.280815,-0.253040,0.290584,-0.046586,0.166818,0.248549,-0.531373,0.152848,-0.352459,-0.251593,0.266955,-0.379383,0.175660,-0.483155,-0.206929,-0.269808,-0.204262,-0.142959,-0.014931,-0.466226,0.751851,-0.957319,0.112894,0.556100,0.234210,-0.642903,0.834336,-0.036503,0.391797,-0.274536,-0.170066,0.565407,-0.125907,0.293715,-0.529061,0.169059,-0.184663,-0.335796,-0.306042,0.742438', '1870681', '1303034', '1780122', '24875409');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295812', '砂之女', '剧情', '一个昆虫学家（冈田英次 饰）在沙漠做野外考察，却不慎错过归程班车，被困在一个沙漠中的小村子里。他落脚在一个寡妇（岸田今日子 饰）家，被招待之后发现通往外界的路已经被封住。他慢慢观察村子的各种古怪，比如全部村民每到夜晚都要出动铲沙，以免居住的房屋被沙子埋掉，所有的水都受到管制，实行配给制使用等。收留他的寡妇开始用身体诱惑他，试图和他重组一个家庭，他几次三番尝试逃走都以失败告终，只好表面上虚与委蛇，进入村子定期劳动、享受配给的生活模式，但他内心始终在做逃走的打算。一日，寡妇突发急病，被医生诊断为意外怀孕，大家手忙脚乱带她去送医，男人终于有了千载难逢的逃走机会……©豆瓣', '冈田英次', '敕使河原宏', 8.6, 10946, 'tt0058625', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2151938579.jpg', 0.4, 1.2, 11.8, 43.5, 43.1, '0.151661,0.111248,-0.589877,0.109866,-0.145555,-0.069806,0.687165,0.077315,-0.455391,-0.240439,0.230599,0.536932,-0.121796,-0.023518,-0.111835,-0.137320,-0.249981,-0.304867,0.141972,0.142580,-0.529845,-0.043290,-0.004132,-0.179502,-0.147846,-0.124439,0.558446,0.261674,-0.181218,0.131662,-0.116063,0.132676,0.012566,0.582208,-0.418380,-0.040715,-0.132061,-0.231827,-0.028028,0.395514,-0.259658,-0.364155,-0.199985,0.029251,0.224125,0.632169,0.842425,0.009735,-0.343117,-0.003772,0.204962,-0.230219,-0.071428,0.287948,0.303310,0.001716,0.045717,0.147390,-0.317658,0.036343,0.123198,-0.106996,-0.576353,0.100402,0.236350,0.025558,-0.705048,0.252119,0.230780,-0.080931,-0.108708,-0.496770,0.204175,0.297585,0.219807,0.152465,-0.252511,0.131446,-0.470807,0.062778,0.660230,-0.310365,-0.186773,0.249870,-0.119832,-0.251900,0.440081,-0.327076,-0.423861,-0.126601,0.091159,0.028713,-0.672856,-0.148527,-0.484017,0.078127,-0.427707,-0.421788,-0.047459,-0.255351,-0.212472,-0.681885,0.123561,0.108786,-0.455481,0.355707,0.183854,-0.095814,0.327413,-0.546022,0.263147,0.579685,0.271055,-0.682170,0.575055,0.023969,0.185057,-0.006762,0.060376,0.245493,0.243295,0.602298,0.056028,0.395332,-0.156397,0.241854,-0.415750,0.327605', '21619567', '1308833', '1298197', '26418093');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295815', '那年夏天，宁静的海', '剧情', '聋哑青年茂（真木藏人饰）是名清洁工，他在一个清理垃圾堆时发现了一个被人扔掉的破旧冲浪板，捡去修好后就带着女朋友贵子（大岛弘子饰）到海边练习，贵子也是个聋哑人。茂对冲浪从喜爱发展到痴迷的程度，他一下班就到海边不停地练习，而贵子总是坐在海滩上微笑地望着他。日复一日，茂的技术越来越好。冲浪用品店老板送给茂一套潜水服，并给了他一份参加冲浪比赛的申请表。在比赛那天，茂和贵子兴致冲冲地到了海边，却因意外没有参加成比赛。但茂对冲浪的热爱不减，贵子也一如既往地支持他，在后来的比赛中，茂取得了优胜。几天以后，茂又到海边练习。贵子因事来迟，却没有看到茂，眼前是一片寂静的海面。©豆瓣', '真木藏人', '北野武', 8.6, 83455, 'tt0103704', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2153209777.jpg', 0.2, 0.9, 12, 44.5, 42.4, '0.153638,0.044957,-0.691971,0.496046,-0.065943,-0.391735,0.684529,0.201617,-0.021004,-0.054572,0.105341,0.783414,-0.548106,0.342358,0.139370,-0.056893,-0.444209,-0.596470,-0.145144,0.004638,-0.496132,-0.401444,0.095534,0.063614,0.069861,-0.219607,0.433312,0.358955,-0.143401,0.790575,-0.021133,-0.134227,0.173340,0.737485,-0.593851,0.090931,0.038015,0.180735,0.354873,0.379771,0.088865,-0.558426,-0.544984,0.246083,0.343927,0.336407,1.019146,-0.108491,-0.222998,0.283252,0.036356,-0.236836,-0.062956,0.060110,0.602083,-0.220845,-0.266492,0.032386,-0.110146,0.128763,-0.038265,-0.168994,-0.465189,0.101939,-0.190152,0.279466,-0.660166,0.757534,-0.014545,-0.104212,-0.026655,-0.465151,0.269177,-0.044065,-0.275808,0.527453,-0.113079,0.087299,-0.520522,0.390772,0.446078,0.007877,0.166195,0.589263,-0.261912,-0.321040,0.205247,-0.269916,-0.492263,-0.424271,0.382293,-0.204794,-0.086411,-0.461564,-0.494846,0.279308,-0.155037,-0.549328,-0.055660,-0.165993,-0.145712,-0.621836,0.340424,-0.537655,-0.320720,0.289724,-0.071354,-0.479274,0.632716,-0.760705,0.032668,0.477447,0.044061,-0.218069,0.642027,-0.144898,-0.141251,-0.092396,-0.232899,-0.334839,0.025776,0.314159,0.250409,0.639640,-0.000266,-0.316278,-0.641609,0.539992', '3155839', '24839498', '3811356', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295820', '狂凶记', '惊悚', '理查德是一名飞行员，退伍后，他在一家酒吧打工，认识了同事芭芭拉（安娜·玛西 Anna Massey 饰）并与之相爱。性格粗暴的理查德同老板发生口角后被开除，身无分文的的只得投奔前妻布伦达（Barbara Leigh-Hunt 饰）。布伦达经营着一家婚姻介绍所，她友善的接待了理查德并偷偷的在他口袋里塞了一些钱。没想到几天后，布伦达在介绍所中被她与理查德共同的朋友鲍伯（巴里·福斯特 Barry Foster 饰）玷污并用领带勒死，原来鲍伯就是伦敦臭名昭著的领带勒杀狂魔。布伦达死了，理查德成了最大的嫌疑人。为了将更大的罪嫌推到理查德身上，鲍伯又趁机杀死芭芭拉，一时间理查德成为了全城通缉的对象，最终落网。负责此案的奥克斯福德（埃里克·麦克文 Alec McCowen 饰）觉得事有蹊跷，经过夫人的提点，他发现真正的罪犯已经露出了马脚。©豆瓣', '乔·芬奇', '阿尔弗雷德·希区柯克', 7.9, 19140, 'tt0068611', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359406828.jpg', 0.3, 1.6, 22.5, 53.7, 21.9, '0.477889,-0.007204,-0.423718,0.300069,-0.170728,-0.394869,0.799644,0.091229,-0.368857,-0.245660,0.081341,0.822912,-0.283556,0.277332,0.471988,0.079477,-0.297812,-0.781318,0.097515,-0.339245,-0.344384,-0.546624,-0.201849,-0.040392,0.017743,-0.260926,0.118857,-0.057809,-0.026161,0.458116,0.487604,0.371346,0.011966,0.345844,0.013232,0.154274,0.248131,-0.346786,-0.181882,0.091319,0.012573,-0.132058,-0.035065,0.247976,0.033596,0.564399,0.437616,-0.116771,-0.010056,-0.120396,0.275758,-0.197747,0.118517,0.051266,0.398794,-0.010747,0.165334,0.310480,-0.250261,-0.022867,0.442169,-0.042363,-0.679701,0.241909,0.008898,0.129994,-0.592931,0.352376,-0.192646,0.159804,-0.074538,-0.332000,0.106369,0.306222,0.157173,0.070596,-0.045643,0.060681,-0.567409,0.085109,0.409780,-0.198861,0.095777,0.130534,-0.144005,-0.307962,0.132823,-0.090130,-0.331214,-0.217291,0.579126,-0.119537,-0.155519,0.154412,-0.482430,-0.418296,-0.351977,-0.021444,0.033719,-0.276806,0.016349,-0.479952,-0.205433,-0.290859,-0.236666,-0.136389,0.070944,-0.223095,0.219952,-0.638754,0.098195,0.556516,0.223113,-0.456954,0.470977,0.057813,0.347333,0.090690,-0.160106,0.062501,0.518022,0.363820,0.480912,0.446708,0.065278,-0.416399,-0.157773,0.329971', '1309069', '1303139', '1301686', '1299799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295824', '洛奇5', '剧情', '洛基电影的第五集。自从上一集洛基（西尔维斯特•史泰龙 Sylvester Stallone 饰）击败了苏联的拳击机械人后，他决意归隐，从此过些安安乐乐的日子。阴险商人杜克（东尼•布顿 Tony Burton 饰）是拳击经理人，利用拳击手赚黑心钱，他高薪引诱洛基投到他门下，洛基不为所动，断然拒绝了他的邀请。退隐后的洛基还是没有离开拳击，他的好友拳击教练米克死后留下了一座拳击训练馆，洛基继承了米克的事业，每天到拳击馆里训练新人。年轻拳手绰号“机枪”的涛米极具天分，洛基倾其所有传授米涛拳术，米涛在洛基的帮助很快就跻身了优秀拳手的行列。成名后的米涛被名声和金钱所蒙蔽，投到了杜克的帐下，成了杜克阴谋的一枚棋子。怒不可遏的洛基决定用自己的手段拯救米涛！©豆瓣', '西尔维斯特·史泰龙', '约翰·G·艾维尔森', 8, 10927, 'tt0100507', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2389681501.jpg', 0.5, 2.6, 25, 42.5, 29.5, '0.293618,-0.030674,-0.395461,0.581796,-0.530328,-0.402320,0.361461,0.267117,-0.127563,-0.119752,0.481892,0.749031,-0.056066,-0.086657,0.100953,0.043427,-0.238235,-0.828184,-0.095407,0.018406,-0.056770,-0.419533,-0.280827,-0.118787,-0.039636,-0.314608,0.526801,-0.222518,-0.255818,0.348768,0.178864,0.285292,0.410238,0.239568,-0.204278,0.291652,0.208598,-0.202805,-0.199200,0.270286,-0.065827,-0.482082,-0.211683,0.156214,-0.077720,0.384186,0.415299,0.001805,0.135485,-0.163915,0.149236,-0.296224,-0.234478,0.137396,0.263765,-0.045713,0.074589,-0.000106,0.044414,0.064236,0.140733,-0.005507,-0.549751,-0.284593,-0.042545,-0.079558,-0.687200,0.619464,-0.294206,0.165116,-0.085651,-0.201581,-0.199698,-0.120026,-0.036959,0.044528,-0.031137,0.128925,-0.335935,0.537698,0.447139,-0.194073,-0.243279,0.151587,0.100470,-0.367693,-0.017402,-0.368755,-0.152065,-0.243755,0.760199,-0.230127,0.041458,0.322148,-0.534333,-0.137637,-0.396041,-0.087910,0.005393,-0.305373,0.028668,-0.686697,-0.029617,-0.208931,-0.093184,-0.148573,0.125897,-0.299681,0.702574,-0.854168,0.078805,0.354513,0.134259,-0.159676,0.619726,-0.229044,0.029703,-0.076866,0.011479,0.048800,0.127567,0.323653,0.245268,0.612612,0.355733,-0.290114,-0.145739,0.711808', '1870681', '4301274', '1308609', '10462973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295831', '女巫布莱尔', '悬疑', '1994年十月，三个电影学院的学生——迈克（Michael C. Williams 饰），希瑟（Heather Donahue 饰）和乔什（Joshua Leonard 饰）前往马里兰州的布莱尔小镇，拍摄一部关于女巫布莱尔的纪录片，然而在拍摄过程中三人全部失踪。人们在一年以后，发现了他们留下的电影胶片，记录了他们失踪前发生的一切……在布莱尔小镇上，长久以来流传着关于杀害孩子的女巫布莱尔的传说，这里集中的儿童墓地，还有小镇上几乎人尽皆知的古老故事，都印证着女巫的存在。迈克等三名同学，在一个平静的周日展开了对布莱尔故事的追索，可是在他们深入密林的同时，诅咒也开始降临在他们头上。©豆瓣', '希瑟·多纳约', '丹尼尔·麦里克', 6.4, 22492, 'tt0185937', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1451524667.jpg', 4.8, 14.2, 45.6, 26.3, 9.1, '0.341976,-0.192498,-0.804690,0.567661,0.153358,0.052632,0.783005,-0.077817,-0.533111,-0.370571,0.264378,0.611871,-0.351053,0.266286,0.424868,-0.033383,-0.625914,-0.593742,-0.090028,-0.389417,-0.379445,-0.581298,-0.219566,-0.274634,0.007003,-0.618413,0.431182,0.169225,-0.136845,0.354515,0.164091,0.113197,-0.435534,0.107090,-0.281971,0.075328,0.245582,-0.036140,-0.236771,0.291636,-0.107911,-0.207036,-0.151822,-0.135083,0.058488,0.272093,0.866275,-0.299736,-0.217714,0.392325,0.355525,-0.267703,-0.239183,0.048696,0.572915,0.019356,0.105541,0.429927,-0.122054,-0.239261,-0.108859,-0.187627,-0.601561,0.032925,0.104902,0.534346,-0.507226,0.832922,-0.045238,0.048051,0.029189,-0.506185,0.447643,0.433396,0.041508,0.317962,0.004334,-0.203569,-0.545232,0.389598,0.536072,-0.201327,-0.130543,0.268349,0.049036,-0.422954,-0.453250,0.143306,-0.494315,0.196151,0.347801,-0.063777,-0.474384,0.455268,-0.635625,-0.083056,-0.039070,-0.645264,0.175496,-0.342473,-0.400398,-0.953164,-0.093067,-0.233209,-0.271475,0.029411,0.011579,-0.152347,0.897805,-0.714653,0.726960,0.538491,0.135462,-0.066188,0.813008,-0.219054,0.316659,-0.091263,-0.136655,0.285526,0.315343,0.465032,0.153340,0.360640,-0.168264,-0.133563,-0.491605,0.551960', '1307897', '1308609', '10466639', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295834', '极度空间', '动作', '在未来的某个年代，人们的思维已经被政府机构控制，政府机构通过电视信号传输一种催眠电波控制人们的行动。但是一些不甘心被强权统治的人们研究出一种眼镜，戴上这种眼镜，电视节目里道貌岸然的官员就会现出骷髅般的原形……', '罗迪·派彭', '约翰·卡朋特', 7.4, 7474, 'tt0096256', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2268360662.jpg', 0.8, 4.5, 34.2, 44.6, 16, '0.529690,0.478396,-0.353518,0.750324,-0.514195,0.501210,0.536061,0.090638,-0.500105,-0.336319,0.358128,0.484492,-0.303471,0.139414,-0.158321,-0.083382,-0.334755,-0.580399,-0.069946,0.095241,-0.251271,-0.187080,-0.584358,-0.391933,-0.465510,-0.366780,0.942723,0.223859,-0.703176,-0.182761,-0.159778,0.334609,0.173711,0.296611,0.080368,-0.572739,-0.141724,-0.876473,0.416368,0.098826,-0.025030,-0.226235,0.315070,0.469449,-0.456361,0.070007,0.843251,-0.525217,-0.325978,-0.271832,0.740086,-0.209082,-0.537012,0.503990,0.232721,0.399490,-0.494849,-0.039112,-0.173588,0.243355,0.065399,0.229959,-0.687752,-0.311722,-0.276593,0.710946,-0.216449,-0.040154,0.109441,0.094527,-0.503156,-0.401316,0.241177,0.153250,0.289030,0.712403,-0.399147,0.196577,-0.657395,0.153096,0.244424,-0.306604,-1.094951,-0.014949,-0.898815,-0.540361,-0.467237,-0.073715,-0.715725,-0.401792,0.322436,-0.148490,-0.459507,0.535564,-0.732654,-0.152743,-0.197127,-0.160782,-0.228023,-0.331342,0.109271,-1.122995,-0.343669,-0.329064,0.151804,0.043141,0.422495,-0.001949,0.745831,-0.988961,0.014292,0.685034,0.080707,-0.448198,0.195809,-0.153726,0.014070,-0.202409,-0.170835,0.026915,0.298244,0.447359,-0.303261,0.521252,0.199988,-0.170480,0.039947,0.271708', '2369613', '20274039', '1322847', '1292347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295858', '现代豪侠传', '动作', '结婚生子后的冬冬（梅艳芳 饰）过着相夫教子的的日子，但世界并不太平。经历过核爆炸后，世界面临水荒，但却有一家神秘的净水公司控制着纯净水并从中谋取暴利，甚至遏制了整个社会的命脉。此时，一位名叫长空（金城武 饰）的人被推到台前，成为其背后势力反政府的领袖。然而，不久长空被杀，杀手将此罪责嫁祸给冬冬的老公（刘松仁 饰），他也是当时的公安局长。局长因此被杀，冬冬也被捕，军长趁机发动了政变。陈三（杨紫琼 饰）救出总统，同时陈七（张曼玉 饰）受冬冬之托带着冬冬的女儿去寻找干净的水源，冬冬也终于重拾信念做回女飞侠。这突如其来的灾难背后有着怎样的阴谋？三位女飞侠能否再次给这黑暗世界到来一丝曙光？©豆瓣', '杨紫琼', '杜琪峰', 7.3, 15649, 'tt0108606', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457355761.jpg', 0.8, 5, 39.1, 39.6, 15.5, '0.098610,0.303353,-0.632036,0.367106,-0.020782,-0.199733,0.506811,0.185381,-0.384167,-0.225848,0.240870,0.540331,0.073612,0.044001,0.210034,0.114477,-0.001780,-0.666119,-0.047641,-0.069576,-0.219952,-0.149248,-0.299637,0.258466,0.010148,-0.216305,0.521429,0.048251,-0.108406,0.453420,0.346471,0.333877,0.054383,0.676729,-0.092248,0.231471,-0.000995,-0.172969,-0.569167,0.288335,0.123273,-0.300580,-0.152482,0.334531,-0.305768,0.152277,0.420207,-0.212532,-0.108989,-0.348956,0.301873,-0.389046,-0.025646,0.122428,0.324571,0.219074,0.200797,0.516917,-0.158202,0.148824,0.283745,-0.029275,-0.778211,0.004624,0.215569,0.107260,-0.469697,0.239374,-0.097153,-0.130428,-0.064741,-0.145631,0.423191,0.357311,0.243178,0.290591,-0.520663,0.177302,-0.753254,0.005215,0.519015,-0.198159,-0.045772,0.026063,-0.082139,-0.340536,0.139737,-0.358455,-0.379638,0.170968,0.333179,0.133971,-0.193388,0.303101,-0.596072,0.061066,-0.361042,-0.047573,0.066598,-0.259600,-0.167243,-0.370554,-0.290467,-0.200246,-0.266180,-0.128040,0.154314,-0.194759,0.626119,-0.600937,0.188631,0.487895,0.405244,-0.405789,0.480991,0.197755,0.400088,-0.090005,-0.136509,-0.118265,0.006137,0.553030,0.048942,0.214910,0.018071,-0.373163,-0.014451,0.208232', '30163500', '1793491', '1835843', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295865', '燃情岁月', '剧情', '辽阔的西部草原住着一位父亲和他的三个儿子——父亲是退了休的骑兵上校，三个儿子个性鲜明：大儿子艾尔弗莱德（艾丹•奎因 Aidan Quinn  饰）忠厚老实，二儿子特里斯坦（布拉德•皮特 Brad Pitt 饰）狂放不羁，最小的儿子塞缪尔（亨瑞•托马斯Henry Thomas饰）温文尔雅。父子在大草原的生活随着塞缪尔未婚妻苏珊娜（朱莉娅•奥蒙德 Julia Ormond  饰）的到来而改变。苏珊娜年轻漂亮，给艾尔弗莱德带来了内心的震动。他暗恋她，然而苏珊娜心里却不由自主的迷恋上豪放粗犷的特里斯坦。出于道德的坚守，他们一直压抑着内心的感情。直到塞缪尔壮烈牺牲在前线，事情有了变化。特里斯坦非常爱戴哥哥，无法面对已经爱上苏珊娜的现实，于是离家出走。而苏珊娜万念俱灰，答应嫁给了艾尔弗莱德，而特里斯坦在草原之外也已结婚生子。事情好像趋于了平静，但特里斯坦妻子的亡故又令事情有了波澜。', '布拉德·皮特', '爱德华·兹威克', 8.8, 270033, 'tt0110322', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2797313535.jpg', 0.4, 1.1, 10.4, 36.4, 51.8, '0.043619,-0.067475,-0.851183,0.790369,-0.096486,-0.479119,0.849766,0.373487,-0.494245,-0.353595,0.007703,0.736002,0.022601,0.272546,0.274469,0.157660,-0.181026,-0.586292,-0.023793,-0.021506,-0.065117,-0.636025,0.005562,-0.433013,-0.042116,-0.309130,0.501221,-0.123971,0.047863,0.477359,0.427082,0.308080,0.257297,0.521690,-0.121975,0.138549,0.108488,-0.053125,-0.243196,-0.012896,0.161454,0.032083,-0.143528,0.452544,-0.047786,0.529283,0.410302,-0.206763,-0.132897,-0.004647,0.242586,-0.169322,0.113759,0.240535,0.195339,-0.274620,-0.118919,0.107487,-0.098300,-0.169160,0.104510,-0.072944,-0.268224,0.153070,-0.043897,0.129192,-0.722705,0.460153,-0.231828,-0.147267,0.101422,-0.265736,0.082067,0.261762,0.081438,0.334911,-0.296879,0.102771,-0.429819,-0.099651,0.651031,0.117794,-0.285687,0.177605,-0.570044,-0.406878,-0.125640,-0.366448,-0.764372,-0.014902,0.219530,0.078967,-0.015518,0.526964,-0.263635,-0.154950,-0.214718,-0.074194,-0.159320,-0.462812,-0.061241,-0.172300,-0.282919,-0.582161,-0.414567,-0.003373,-0.158336,-0.175447,0.640615,-0.649584,0.251733,0.334957,0.167505,-0.519748,0.439731,0.401841,0.136277,-0.358856,0.137213,0.616542,-0.185689,-0.233485,0.185040,0.133156,-0.167943,0.035245,-0.262449,0.783869', '1300754', '1299802', '2075721', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295871', '终极标靶', '动作', '娜塔莎（杨茜•巴特勒 Yancy Butler 饰）年轻富有，这次专门来到新奥尔良市寻找自己失散多年的退伍的父亲。然而她刚踏入这个城市就遭到了抢劫，失业海员赞斯（尚格•云顿 Jean-Claude Van Damme 饰）见义勇为帮她打走了匪徒。娜塔莎见赞斯富有正义感，就聘请他为自己寻找父亲，为存够钱重新出海的赞斯欣然答应。不久，警方找到了被火烧焦了的娜塔莎的父亲。直觉敏锐的赞斯觉得事情不简单，他在现场仔细搜寻，终于发现了被箭射穿的娜塔莎父亲的士兵牌，从而确定了娜塔莎父亲是被人射杀的。赞斯和娜塔莎通过调查，发现了新奥尔良市有一伙暴徒，他们专门找一些无依靠的退伍军人，然后让富人们像猎杀动物一样猎杀他们。赞斯和娜塔莎决心要将这伙冷酷的暴徒乘之于法！©豆瓣', '尚格·云顿', '吴宇森', 6.6, 4481, 'tt0107076', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2159375129.jpg', 1.4, 8.4, 54.4, 28.6, 7.2, '0.354604,-0.254598,-0.555843,0.371536,-0.381219,-0.269861,0.640267,-0.102263,-0.372790,-0.173924,0.122072,0.878965,-0.102254,-0.003028,0.045855,0.254982,-0.294676,-0.637983,0.048155,-0.089670,-0.323798,-0.359320,-0.209655,-0.325555,0.093816,-0.239198,0.369641,0.039261,-0.176066,0.444350,0.191106,0.415274,0.165802,0.471272,-0.413724,0.127457,0.049223,-0.205205,0.024702,0.356570,0.002667,-0.215420,-0.041275,0.102783,-0.046731,0.735207,0.536372,-0.023450,-0.245090,-0.097139,0.166292,-0.434743,0.148379,0.237673,0.280547,0.166060,-0.199850,0.009207,-0.302473,-0.098835,-0.010884,-0.024547,-0.665191,0.010131,0.114760,-0.078905,-0.717464,0.136444,-0.196118,0.092540,0.214730,-0.104267,0.324474,0.342420,0.113895,0.190370,0.213553,0.032011,-0.532133,0.138960,0.805355,-0.329917,0.101650,0.232779,-0.076603,-0.436846,0.332860,-0.232394,-0.128231,-0.003861,0.619131,-0.025862,-0.379784,-0.189001,-0.493295,-0.072670,-0.381013,-0.227598,-0.174795,-0.410897,-0.136332,-0.405263,-0.161840,-0.264679,-0.264662,0.120905,-0.027147,-0.244055,0.571136,-0.757062,0.171119,0.665280,0.380776,-0.680573,0.503379,-0.385292,-0.123749,-0.185383,0.235292,-0.008064,0.525434,0.588810,0.478426,0.285670,0.015780,-0.424276,-0.204348,0.308669', '1309069', '1292584', '25908042', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295872', '西北偏北', '悬疑', '罗杰（加里·格兰特 Cary Grant 饰）是个平凡的广告商人，最近却莫名其妙的惹了一身的麻烦——他被别人错认成一名叫“凯普林”的人，还被人灌醉放进车中，意图造成车毁人亡，命大的罗杰却顺利逃过这一劫。这个离奇的经历让罗杰又后怕又好奇，为了证明自己的清白，他非要找出真正的 “凯普林”不可。噩运在纠缠罗杰。他一路设法摆脱追杀，一边千里追踪凯普林的线索。他跳上了一趟开往芝加哥的列车，车上巧遇娇娃坎多（爱娃·玛丽·森特 Eva Marie Saint 饰），愿意助他一臂之力。眼看就快可以约见凯普林，事情却又起了波澜——他不但没有见到凯普林，还随之陷入了又一场危机当中。真相越来越扑朔迷离，拉什莫山的总统雕像，也成了一场生死搏斗的大舞台。©豆瓣', '加里·格兰特', '阿尔弗雷德·希区柯克', 8.3, 96884, 'tt0053125', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1769720671.jpg', 0.1, 0.8, 15, 52.9, 31.1, '-0.004639,0.314732,-0.756269,0.446717,-0.189414,-0.561098,0.750235,0.061711,-0.488676,0.050931,-0.055090,0.431661,-0.332585,0.138160,0.305413,0.325804,-0.468108,-0.572051,0.227387,-0.092573,-0.357782,-0.208138,-0.485244,-0.498528,0.064842,-0.146605,0.052349,0.418426,-0.307607,0.176229,0.733714,0.111519,0.043995,0.647694,-0.130957,0.300291,-0.172627,0.100728,-0.016236,0.113292,0.187738,-0.507056,-0.120445,0.370165,0.046823,0.336515,0.479915,-0.012690,-0.149650,-0.056615,0.177170,-0.461691,0.240533,-0.033891,0.297900,-0.311046,-0.246480,-0.196939,-0.296322,-0.188647,0.338825,0.172903,-0.773489,0.193066,-0.046710,0.125812,-0.515475,0.204078,-0.225519,0.010978,-0.078531,-0.153859,0.029746,0.371348,0.505850,-0.017678,-0.120119,-0.206959,-0.486693,0.344678,0.733135,0.171188,-0.086398,0.078586,-0.171279,-0.395009,0.026778,-0.174011,-0.248411,-0.060163,0.840731,-0.081117,-0.095983,0.305270,-0.138673,-0.068654,-0.561573,-0.093592,-0.588657,-0.401566,0.185624,-0.228873,-0.078466,-0.285762,-0.069124,0.164360,-0.024110,-0.306061,0.182589,-0.221395,0.229951,0.633802,0.125429,-0.211368,0.243611,0.124472,0.033819,-0.037851,-0.103533,0.149447,0.022663,0.558963,0.448726,0.535903,0.168593,-0.122845,-0.247117,0.421364', '26897427', '1294941', '1301345', '20497559');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295873', '偷自行车的人', '剧情', '二战过后，罗马同许多城市一样，充斥失业和贫困，人们常常为一个工作机会争得头破血流。已失业多时的里奇（Lamberto Maggiorani）费劲千辛万苦获得一份海报张贴的工作后，却为这份工作需要一辆自行车犯愁，为了以后的日子好过，他用妻子的嫁妆--床单从换回已经当掉的自行车，不想，他的自行车在上班第一天就被盗。里奇同儿子布鲁诺（Enzo Staiola）寻遍罗马大街小巷，也没能找到他赖以活命的自行车，眼见无指望的日子又要降临，里奇决定以牙还牙，可是他的运气却没有别的小偷好。©豆瓣', '兰贝托·马乔拉尼', '维托里奥·德西卡', 9.1, 90674, 'tt0040522', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p759707912.jpg', 0.1, 0.3, 5.4, 34.5, 59.7, '-0.036444,0.092290,-0.677826,0.372207,-0.221596,-0.585441,0.507289,0.079669,-0.394569,-0.300531,0.196207,0.684049,0.113593,0.107266,0.209276,-0.039788,-0.300476,-0.654874,0.389828,-0.035331,-0.384911,-0.126489,-0.210670,-0.206641,-0.415939,-0.192676,0.622278,0.248906,0.320277,0.364131,0.142731,-0.206176,0.318611,0.363112,-0.468568,-0.108371,-0.294716,0.265974,-0.328455,0.150774,0.007436,-0.090987,-0.230201,-0.070554,0.218535,0.307325,0.463384,0.278568,0.034551,0.024849,0.257562,-0.129782,0.183185,-0.022052,0.085533,-0.015712,0.107729,0.006316,-0.335852,-0.039244,0.208054,-0.074045,-0.802004,-0.090118,-0.240239,-0.032859,-0.635594,0.537482,-0.267689,-0.000042,-0.031079,-0.397946,0.171785,0.529014,0.056818,0.476526,-0.051006,0.179893,-0.585633,0.418495,0.639238,-0.294943,0.266668,0.673739,-0.030960,-0.023748,0.272721,-0.468765,-0.596900,-0.082290,0.146887,-0.160321,-0.411786,-0.010098,-0.472131,0.116530,-0.260844,-0.529926,0.250757,-0.247920,-0.007205,-0.466610,0.171217,-0.129551,-0.137751,0.254836,0.319103,-0.176918,0.445470,-0.652075,0.333536,0.526298,0.140952,-0.732688,0.560134,0.093480,0.324575,-0.056504,0.131751,-0.078659,0.014018,0.602574,0.291922,-0.069052,0.139258,-0.355015,-0.379076,0.611920', '1835843', '1306916', '26678784', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295877', '二楼传来的歌声', '剧情', '「或许得开始承认那些令我们无能为力的环境，我们自己也得负上责任。我相信西方人的生活方式抑制了人们的潜能发展。你看本片，应该明白人类的行为有多愚蠢。紊乱将人蚕食，情况越来越严重」 ─导演 洛伊 安德森（Roy Andersson）极具野心的挑战性钜作，宗教、经济、世代关系、家庭、情爱，种种议题都经过奇特而荒谬的扭曲，呈现出世人经常视而不见的一面。如弥猴一般在十字架上单手晃荡的耶稣塑像、心智退化的老人在满室各怀鬼胎的贺客面前度过百岁生日、放火诈财的父亲，写诗发疯入院的儿子，独特的视觉语言，在看似连结松散的场景之间，构筑了导演心目中当代世界的深层面貌。在一个不知名所在的奇特夜晚，怪事接连不断地发生：毫无尊严的公司职员遭到屈辱的裁员；外来移民莫名其妙地被不良份子袭击，整个巴士站的人袖手旁观；玩大锯活人的魔术师真的把志愿上台的观众开膛剖腹。一团混乱当中，灰烟满脸的卡尔出现了，他刚刚放火烧了自己的家具店，想骗火灾保险金。一整夜，人人都忙乱的无法阖眼。第二天，局势混乱的程度有增无减，保险公司与卡尔正在角力，整个城市陷入完全动弹不得的大塞车当中，当一切在千禧年一开始就似乎都失去了控制的时候，卡尔慢慢察觉到世界的荒谬，也渐渐了解要作一个「人类」有多困难。这是一部由一系列小品组成的情节松散的电影，充满了黑色幽默。影片中每个人都变得失去理智，一些无条理的怪异行为发生了。一个小职员遭到侮辱性的解雇，一个新移民在大街上遭人袭击，一个魔术师在表演中出现了不该有的失误。在这些怪事中有一件特别引人注目，浑身是灰的Karl为了得到保险金烧毁了自己的家具店。最后他们体会到世界有多荒谬，做人真难。得奖：2000年戛', 'Lars Nordh', '罗伊·安德森', 8.3, 8511, 'tt0120263', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2163286030.jpg', 1, 2.2, 15.9, 45, 35.9, '0.416561,0.100696,-0.807661,0.350202,-0.162887,0.035016,0.893864,0.063641,-0.482438,-0.196352,0.357965,0.657759,-0.307470,0.096578,0.162507,-0.156951,-0.093104,-0.642229,-0.168096,0.005245,-0.262121,-0.487205,-0.270738,-0.366976,-0.206314,-0.349075,0.528268,0.361427,-0.387690,0.049699,0.130141,0.112652,0.101095,0.359239,-0.002817,-0.067137,-0.041308,0.006301,-0.021841,-0.120729,0.006155,-0.173588,-0.048900,0.265763,-0.293250,0.306260,0.623271,-0.383075,-0.492239,-0.022451,0.695914,-0.244356,-0.236044,0.232220,0.239573,0.064360,0.030686,0.013457,-0.150552,0.045959,0.024085,0.114657,-0.863374,-0.008078,0.128381,0.318601,-0.343588,0.450497,0.134126,-0.193152,-0.045175,-0.351413,0.239700,0.225604,0.433613,0.494771,-0.044382,0.006108,-0.425088,0.067573,0.835013,0.036890,-0.654064,0.224289,-0.575179,-0.339215,-0.229557,-0.313826,-0.195805,-0.047635,0.245694,-0.082296,-0.314141,0.493852,-0.457040,0.168222,-0.023185,-0.395151,-0.235597,-0.241883,-0.188810,-0.417821,-0.186058,-0.348778,-0.146544,0.049233,0.081811,-0.202476,0.704524,-0.669301,0.186264,0.587959,0.174924,-0.351522,0.397911,-0.032778,-0.011107,0.047242,-0.301728,0.166164,-0.040790,0.340828,0.169079,0.246823,-0.027998,0.038596,-0.209897,0.492504', '1874704', '3005387', '25828589', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295899', '二见钟情', '喜剧', '露西（桑德拉·布洛克 Sandra Bullock饰）有着平凡的职业，平凡的长相。每天在车站售票处寂寞的工作着，生活唯一亮色就是天天都盼望着准时在车站出现的英俊的彼特（彼得·盖勒 Peter Gallagher饰）。她默默坚持的感情终于在一个圣诞夜有了进展——她救起昏迷在车站的彼特，送往医院，被闻讯赶来的彼特家人误认为她就是彼特的女友。于是，露西既尴尬又不失幸福地接受了这个误会，悉心照料一直昏迷的彼特。彼特的家人这么热心，亲情的包围这么温暖，露西不舍得离开，谎言一个个说下去。但是，这引起了彼特弟弟杰克（比尔·普尔曼 Bill Pullman饰）的怀疑，出人意料的是，杰克的出现并没有带走露西的幸福，反而让露西终于寻获自己的幸福……©豆瓣', '桑德拉·布洛克', '乔·德特杜巴', 7.7, 20100, 'tt0114924', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p863459595.jpg', 0.2, 2.1, 29.5, 48, 20.2, '0.274847,-0.041736,-0.714110,0.466322,-0.353871,-0.561041,1.012689,0.375376,-0.177646,-0.172806,0.375276,0.583676,-0.032776,0.328485,0.296022,0.414410,-0.467378,-0.388724,0.115658,-0.062211,-0.184544,-0.387315,-0.162740,-0.227019,-0.026969,-0.327232,0.381061,-0.079279,0.187718,0.652703,0.317241,0.142636,0.105778,0.702419,-0.249601,0.231960,0.135019,-0.024110,-0.118363,0.062056,0.084434,-0.010102,-0.040911,0.373060,0.024590,0.198139,0.540697,0.039477,-0.275730,0.391786,0.393976,-0.430241,0.036607,0.034686,0.220974,-0.278936,0.022152,-0.237643,-0.325155,0.027748,0.349116,0.244608,-0.779311,0.210394,-0.061546,0.442802,-0.669328,0.591603,-0.132401,-0.197558,0.156415,-0.425847,0.038437,0.395652,0.107300,0.363133,-0.174138,0.294995,-0.548888,0.022842,0.523098,-0.137404,-0.424963,0.393379,-0.580254,-0.252773,0.166245,0.030394,-0.801584,-0.106740,0.334694,-0.061205,-0.231212,0.149261,-0.453577,-0.078148,-0.315779,-0.104440,-0.063869,-0.558185,-0.125214,-0.665016,-0.093122,-0.526109,-0.602649,-0.139357,-0.100283,-0.233729,0.668570,-0.776746,0.428004,0.646995,0.194457,-0.414818,0.623303,0.543320,0.013484,0.053632,-0.224052,0.683164,-0.037482,0.270883,0.150543,0.488815,0.074011,0.153147,-0.429657,0.582904', '1309172', '1292062', '1292211', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295903', '飞天法宝', '喜剧', '菲利普教授（罗宾·威廉姆斯 Robin Williams 饰）对研究工作的痴迷就像瘾君子沉溺毒品般，终日为了研究忙得不可开交，甚至因此已经错过了自己的两次结婚典礼。眼下第三次大婚的钟声已来到门外，菲利普的研究却出现了重大突破，毫无意外，他再一次因此错过了婚礼，留未婚妻莎拉（马西娅·盖伊·哈登 Marcia Gay Harden 饰）在教堂苦苦等候，怨言满腹。菲利普看着被他称为“飞天法宝”的新发明——一种绿色的胶状物质，能够克服地心引力，只需将它涂在任何物体上，那个物体就会腾空而起。不过这种物质也有个难以捉摸的特性，随时会捉弄一下使用它的人。为了追回被他气走的未婚妻，同时挽救即将关闭的学校，菲利普教授将飞天法宝涂在校篮球队员的球鞋上，结果球队大获全胜。然而同时，也招来了别有用心者对飞天法宝的觊觎……©豆瓣', '罗宾·威廉姆斯', '莱斯·梅菲尔德', 7.2, 4913, 'tt0119137', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166103541.jpg', 0.8, 4, 43, 39.1, 13, '0.266929,0.061898,-0.523254,0.499666,-0.130427,-0.157636,0.606760,-0.026893,-0.297789,-0.207784,0.269225,0.722181,-0.408121,0.037554,-0.063240,-0.040152,-0.096097,-0.686792,0.164058,-0.047483,-0.558098,-0.341067,-0.224787,-0.274309,-0.022098,-0.372143,0.608519,-0.032149,-0.054928,0.306902,0.050863,0.088131,0.280777,0.582448,-0.172916,-0.025980,-0.107577,-0.062600,0.075128,0.303069,0.183697,-0.219284,-0.029991,0.262583,0.080527,0.231187,0.613080,-0.282891,-0.033670,-0.193193,0.242434,-0.321868,0.352544,0.250594,0.081461,0.091301,0.005745,0.016291,-0.291256,0.047966,0.274593,0.038094,-0.626115,-0.013104,-0.138188,0.129055,-0.375709,0.417815,-0.163230,0.018812,-0.007216,-0.289563,0.104712,0.321471,0.260883,0.115667,-0.209615,-0.044059,-0.560922,0.068235,0.318112,-0.135683,-0.190617,0.447998,-0.296116,-0.214097,-0.115328,-0.200608,-0.299375,-0.168893,0.512739,0.346268,-0.098109,0.121529,-0.488836,-0.012671,-0.285010,-0.107840,-0.124946,-0.317406,-0.209925,-0.504599,0.106310,-0.106716,-0.585120,0.162090,0.177833,-0.173670,0.490287,-0.743262,0.247040,0.625040,0.143139,-0.347338,0.694031,-0.056785,-0.026060,-0.109433,-0.248655,0.238382,0.021381,0.543574,0.104821,0.492000,0.277229,-0.087914,-0.215929,0.456501', '1509868', '3230462', '30162520', '3027015');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295920', '魂断蓝桥', '剧情', '在伦敦的合唱团工作结束后，美国女孩玛拉·多维尔（梅·克拉克 Mae Clarke饰）因无法找到工作，只能靠出卖肉体来养活自己。伦敦的滑铁卢大桥是休假的士兵进城的主要入口，同时也是玛拉生意较好的地点。一天晚上滑铁卢大桥发生了空袭，而玛拉意外遇到了一位加拿大军队二等兵罗伊·克罗宁（道格拉斯·蒙哥马利 Douglass Montgomery饰）。玛拉因空袭打消了做生意的念头，而年轻的罗伊并没有意识到玛拉的职业，在袭击结束后，护送她到了公寓，并在那里共进晚餐。玛拉将自己描述为一个失业的合唱团女孩，家庭富裕的罗伊对她的慷慨帮助却让玛拉心情复杂。玛拉为自己的隐瞒感到羞愧，而罗伊却疯狂地喜欢上了她……©豆瓣', '梅·克拉克', '詹姆斯·惠尔', 8.7, 6728, 'tt0022550', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2239791077.jpg', 0.1, 0.5, 9.3, 43.1, 47, '0.444633,0.199834,-0.813275,0.445707,-0.198081,-0.358999,0.756788,0.181138,-0.388802,-0.193223,0.233933,0.639791,0.022063,0.228532,0.600198,0.160362,-0.241071,-0.603444,0.270553,-0.115216,-0.318571,-0.583078,-0.125963,-0.411438,-0.097596,-0.481410,0.387049,0.355848,0.048934,0.583371,0.183806,0.269330,0.249029,0.584807,-0.086002,-0.015572,0.094226,-0.121114,-0.058403,0.194258,-0.094635,-0.321064,-0.199346,0.419467,0.382760,0.618135,0.752001,0.118225,-0.119717,0.129719,0.253352,-0.302282,0.201220,-0.111220,0.361435,-0.137837,-0.032574,-0.045858,-0.237242,-0.031255,0.043217,0.006464,-0.738714,0.153496,0.110797,0.150990,-0.696847,0.556054,-0.323223,-0.210342,0.051148,-0.443824,-0.005726,0.544401,0.217496,0.430219,-0.128193,0.097885,-0.522750,0.218498,0.811702,-0.130203,-0.189147,0.325898,-0.331777,-0.525453,0.024193,-0.074460,-0.309478,-0.180451,0.232247,0.073459,-0.238121,0.064545,-0.422756,-0.193626,-0.474115,-0.362492,-0.080335,-0.313243,0.013994,-0.837732,0.165836,-0.306050,-0.360467,-0.012257,0.015280,-0.047984,0.556110,-0.841513,0.263833,0.915898,0.419795,-0.315694,0.499421,0.111625,0.139920,0.003976,0.134998,0.320038,-0.088847,0.227106,0.118041,0.237937,-0.051511,-0.100536,-0.301647,0.679445', '1306723', '11541282', '3326747', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295933', '僵尸先生', '喜剧', '富贵乡绅任发（黄虾 饰）先父当年威逼利诱求得一块风水宝地，经风水先生指点，其父下葬二十年后起坟迁葬，以利子孙。然九叔（林正英 饰）察看墓穴得知，当年风水先生与任家私怨在身，在墓穴中做下手脚，二十年后任老太爷尸体已生恶变。九叔提议就地火化，在任老爷请求下才将尸骨移往义庄。虽经小心看护，但任老太爷仍化作僵尸，将其子任发杀害。九叔断定任老太爷和任发的僵尸将再次出现，于是命令徒弟秋生（钱小豪 饰）和文才（许冠英 饰）小心应付……©豆瓣', '林正英', '刘观伟', 8.4, 80420, 'tt0089371', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561349592.jpg', 0.2, 0.8, 14.2, 47.1, 37.8, '-0.001763,-0.166887,-0.095257,0.061812,-0.115949,-0.151115,0.295330,0.256463,-0.529742,-0.314768,0.558025,0.628367,0.029900,0.088670,-0.264032,-0.009428,0.013673,-0.427574,-0.130553,0.065221,-0.101361,-0.463403,0.038248,-0.072763,-0.144932,-0.296424,0.177807,0.073151,0.358412,0.145042,-0.107411,0.111762,-0.482887,-0.296452,-0.383822,0.377137,-0.261766,0.088034,-0.416485,-0.005924,-0.098811,-0.702641,-0.142008,-0.271149,0.124228,0.261715,0.514363,-0.275283,-0.197340,-0.206579,0.158074,0.061391,0.092995,0.449236,0.527724,0.064237,0.233059,0.937004,-0.233864,-0.050650,0.333444,0.153307,-0.002578,0.033012,0.342761,0.012323,-0.780645,-0.044902,-0.050602,0.071759,-0.498997,-0.507425,0.455963,0.025426,-0.141483,0.188887,-0.198148,-0.102519,-0.292328,0.421033,-0.177668,-0.085069,0.273215,-0.479606,0.411201,-0.190915,0.457016,-0.230543,-0.158165,-0.116509,0.328373,0.160694,-0.172309,0.060601,-0.154407,-0.390788,-0.581589,0.226952,0.066316,0.062597,-0.118366,-0.273779,-0.248128,0.323847,0.101777,0.063964,0.282834,-0.337624,0.199218,-0.218873,0.221825,-0.238220,0.275717,-0.379097,0.279580,-0.063809,0.163518,-0.233610,0.274453,-0.094655,0.302635,0.250654,0.302485,0.083572,-0.154887,-0.054506,-0.397072,-0.117914', '27621189', '1306490', '1296837', '1296196');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295942', '畸形人', '剧情', '本部饱受争议的离奇影片围绕马戏团里一群畸形人展开。矮人汉斯（哈利·厄尔斯 Harry Earles饰）暗自倾心于“正常人”——美貌的秋千表演者克里奥佩特拉（奥尔加·巴古拉诺娃 Olga Baclanova饰），同为侏儒人的弗里达（黛西·厄尔斯 Daisy Earles饰）告诫汉斯，她只是为他的钱财。克里奥佩特拉与“正常人”大力士赫克留斯（道格•霍奇森 Henry Victor饰）两人相好，设计让克里奥佩特拉嫁给汉斯得到钱财。婚礼上，克里奥佩特拉大吼在场的人都是“FREAKS”，激怒了所有畸形人。雨夜，畸形人对这两个“正常人”展开了报复……本片在1932年发行后因题材过于怪诞而被禁止，成为了当时的赔钱电影。可在当下来看，却是一部难得的“正常”影片。导演向我们抛掷了一个赤裸裸的提问：到底谁才是“正常人”？©豆瓣', '华莱士·福特', '托德·布朗宁', 7.9, 7168, 'tt0022913', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2389174006.jpg', 0.5, 2, 23.6, 49.5, 24.3, '0.264228,-0.314520,-0.420208,0.430804,-0.013656,-0.335675,0.758199,0.053669,-0.564848,-0.088637,0.320237,0.825654,-0.382204,-0.159333,0.209266,0.147831,-0.574972,-0.621392,-0.097858,-0.097345,-0.124145,-0.434451,-0.110783,-0.481838,-0.168467,-0.351856,0.230089,-0.291629,0.000704,0.268371,0.428670,0.320712,0.178343,0.055273,0.127606,0.238770,0.048109,-0.284615,-0.172574,0.101715,-0.065787,0.057788,-0.305465,0.104714,-0.156990,0.366418,0.548062,-0.472480,0.192392,-0.250112,0.368201,-0.280043,0.063842,0.251168,-0.019199,-0.242149,0.094651,0.073792,-0.122763,0.016318,0.220362,0.052106,-0.469086,0.206812,0.106965,0.245355,-0.337085,0.426157,-0.228377,-0.071339,0.057086,-0.200154,-0.176518,-0.063490,0.415380,0.296852,0.092143,-0.237917,-0.368653,0.052813,0.341023,0.310570,-0.434052,0.154624,-0.380186,-0.476646,-0.299566,-0.219580,-0.430366,-0.030014,0.288871,-0.115786,-0.098752,0.486613,-0.563487,-0.046413,-0.263640,-0.165720,-0.204392,-0.381240,-0.126488,-0.757329,-0.014605,-0.254664,-0.225132,-0.189369,0.184383,-0.268975,0.540687,-0.391447,0.085769,0.474833,0.288999,-0.249539,0.497689,-0.212861,0.015330,-0.069880,-0.174172,0.192299,0.264606,-0.080234,0.157612,0.298184,0.092686,-0.169993,-0.102955,0.484678', '35161768', '30162520', '1306762', '13