INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295955', '魔鬼末日', '动作', '1979年，罗马梵蒂冈教廷意识到和恶魔撒旦有着莫大关系的一名女婴诞生在纽约，二十年后，距离本世纪还剩最后三天的12月28日，撒旦（加布里埃尔·伯恩 Gabriel Byrne 饰）以一名人类银行家的肉身重现人间，丧失了妻女的前任警察杰瑞克（阿诺·施瓦辛格 Arnold Schwarzenegger 饰）和自己的安保团队受雇于伪装的魔鬼，为其提供保护。不久一名神父冒死狙杀撒旦，不幸失败，他在临死前向布瑞克提出警告。布瑞克与同伴按照神父留下的线索找到了女子克里斯汀（罗宾·汤尼 Robin Tunney 饰），得知她是命中注定要与撒旦结合的女性，如果撒旦能在千禧之夜和克里斯汀发生关系，那就意味着世界的毁灭。布瑞克决定不惜一切代价以人类的身份阻挡撒旦……©豆瓣', '阿诺·施瓦辛格', '彼得·海姆斯', 6.4, 5886, 'tt0146675', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2451449170.jpg', 1.9, 10.9, 57.7, 22.7, 6.7, '-0.041223,0.014634,-0.435686,0.534028,-0.430446,-0.236967,0.649730,0.005405,-0.345048,-0.326374,0.459726,0.979455,-0.024858,-0.151273,0.668738,-0.097960,-0.434071,-0.644206,0.099662,-0.410096,-0.247495,-0.593181,-0.322417,-0.324474,-0.041522,-0.703625,0.774870,-0.039934,0.062669,0.195701,0.214095,0.418773,-0.198022,0.159688,0.066715,-0.032084,0.176387,-0.311087,-0.574623,0.541114,-0.106113,0.123038,0.024879,0.156728,-0.269372,0.235218,0.364286,-0.525398,0.068903,-0.273751,0.362582,-0.334004,0.114177,0.138058,0.361468,-0.257573,-0.007264,0.474803,-0.114874,-0.224138,0.244490,-0.181139,-0.944441,0.024007,-0.010556,0.234566,-0.466082,0.312249,-0.103215,0.233631,0.374251,-0.202005,0.097297,0.247108,0.437560,0.379891,0.007304,-0.161990,-0.496159,-0.024269,0.607886,-0.167137,-0.368142,-0.120685,-0.098287,-0.418571,-0.235868,-0.124000,-0.215161,0.154144,0.235633,0.120890,-0.162656,0.390527,-0.495358,-0.484482,-0.473559,-0.072298,0.141875,-0.204754,-0.055153,-0.762982,-0.226202,-0.260742,-0.094892,-0.000582,0.148299,-0.260337,0.541673,-0.889617,0.332107,0.682319,0.515989,-0.305182,0.530703,-0.020016,0.230252,-0.492800,0.045425,0.589592,0.179595,0.244788,0.304554,-0.063072,0.184698,0.242347,-0.126031,0.262320', '1793491', '3861846', '5910040', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295965', '我最好朋友的婚礼', '喜剧', '朱莉安（朱莉娅•罗伯茨 Julia Roberts 饰）和迈克尔（德蒙特•莫罗尼 Dermot Mulroney饰）是大学时候的情侣。和大多数的恋人一样，他们的热恋慢慢降温，直到沦为好朋友。于是毕业前有了这样一个约定：如果28岁之前，彼此还是单身，那么就明证了他俩是天造地设的一对，到时候两人就结婚。毕业后二人一直通电，朱莉安以为只是友情。然而迈克尔的婚讯却让她如梦初醒——自己一直都还深爱迈克尔，此时强烈的妒嫉和伤心让她寝食难安。朱莉安决定要改变这一切。她一手设计了一个个令人哭笑不得的“阴谋”，让迈克尔未婚妻当众出丑，离间他们的感情。当发现迈克尔对未婚妻的爱竟然占了上风时，朱莉安在婚礼上做出了疯狂举动，这一招果真气走了新娘。然而事情又有了变化。©豆瓣', '朱莉娅·罗伯茨', 'P·J·霍根', 7.3, 86838, 'tt0119738', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p923538632.jpg', 0.4, 3.1, 38.9, 44, 13.6, '0.353591,-0.107088,-0.873644,0.578253,-0.162754,-0.621928,0.726896,0.213179,-0.649321,-0.150147,0.011337,0.697861,-0.757961,0.186442,0.166735,0.158047,-0.402630,-1.020758,0.048226,-0.288635,-0.220858,-0.443717,-0.222489,-0.069944,-0.072946,-0.160520,0.411715,-0.096706,0.054987,0.518744,0.637646,-0.013191,0.289044,0.583948,-0.117007,0.119415,0.076435,0.315083,-0.352474,0.065633,0.108595,-0.063700,-0.046833,0.473595,-0.168568,0.467287,0.369507,0.006631,-0.320008,-0.012804,0.124995,-0.370950,0.024649,0.579916,0.169447,-0.320882,0.422254,0.007801,-0.236659,-0.033985,0.007618,0.152798,-0.472675,0.196011,-0.069948,-0.060057,-0.621696,0.358797,-0.122309,-0.077134,0.286222,-0.192826,0.155236,0.550646,0.467904,0.492279,-0.287293,-0.125613,-0.612233,-0.042908,0.816259,0.025064,-0.358849,0.525799,-0.090183,-0.298389,-0.192990,0.155588,-0.483440,0.095556,0.104547,0.132315,-0.066772,0.257193,-0.530797,-0.182999,-0.195316,0.181363,-0.094520,-0.647234,0.178140,-0.385931,-0.201166,-0.520335,-0.649320,0.085742,-0.059270,-0.235873,0.588860,-0.610845,0.272531,0.502071,0.371534,-0.468728,0.697765,0.452312,-0.050134,-0.264941,-0.035372,0.150277,-0.225666,-0.068128,0.314974,0.473118,0.143749,-0.091495,-0.358172,0.596303', '1292211', '30162520', '25837574', '34973399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295987', '绝代双骄', '喜剧', '社会动荡不安的唐朝未年，每18年举行一次的武林赏善罚恶大会上，武林十大前辈选出移花宫主为担任赶杀十大恶人重任的武侠义士，不料却遭到突至的宫主夫君燕南天的阻止。宫主以一招之差落败燕南天后夫妻反目，立誓18年后将授一门人杀尽十恶。为感谢燕南天的救命之恩，十大恶人担起扶养其儿子小鱼儿（刘德华）的重任，并欲把他培养成天下最恶之人。宫主则收养了花无缺（林青霞），边授其武功边灌输男人都该杀的思想。18年过去，十大恶人与宫主分别命小鱼儿与花无缺在新一届赏善罚恶大会上争夺盟主，两人的生活轨迹开始交叉。©豆瓣', '刘德华', '曾志伟', 6.4, 21942, 'tt0104572', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513199034.jpg', 2.5, 12.8, 55.6, 21.8, 7.3, '-0.137463,0.136441,-0.175083,0.529950,0.108918,-0.256252,0.074499,0.028628,-0.542781,-0.105906,0.271912,0.523864,-0.013296,0.145492,0.480576,-0.084678,0.337386,-0.930750,-0.371221,-0.211716,-0.005982,-0.002356,0.001206,0.005979,-0.214300,-0.157816,0.713514,-0.049664,-0.008253,0.342809,0.260767,-0.013592,-0.138091,0.109328,-0.146276,-0.151428,-0.226708,0.030386,-0.535005,0.167393,-0.427669,-0.576068,-0.229396,0.040574,-0.350487,0.262323,0.209904,-0.489976,0.168066,-0.623696,0.155943,-0.298465,-0.248995,0.023686,0.403932,0.176525,0.260351,0.733787,0.132516,-0.328963,0.004116,-0.439347,-0.563215,-0.120351,0.372185,-0.040532,-0.402383,0.711173,-0.282305,0.104637,-0.394299,-0.374894,-0.095169,0.159294,0.329491,0.053595,-0.241310,-0.128805,-0.309638,0.237644,0.636067,-0.127649,0.151469,-0.263738,0.618867,-0.461638,0.154496,-0.869136,-0.142817,0.079707,0.233642,-0.169803,0.293765,0.573193,-0.257274,-0.325558,-0.246370,-0.024994,0.118083,-0.196427,0.198918,-0.170876,0.054332,0.118929,-0.242023,-0.213066,0.508068,-0.320449,0.949020,-0.758460,0.233859,0.091705,-0.003917,-0.776132,0.643373,0.099772,0.370898,-0.234003,-0.461686,0.009301,0.216405,0.415417,-0.005307,0.116083,-0.121149,0.069403,-0.081246,0.066682', '1295469', '27602116', '1306998', '26266892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1295995', '仁心与冠冕', '喜剧', '路易斯（丹尼斯·普莱斯 Dennis Price 饰）的母亲出身高贵的阿斯特内家族，但因和一个意大利歌唱家私奔，至死都受到家族排斥。已经长大成人的路易斯深深牢记贵族亲戚们拒绝母亲葬在家庭墓地的嘴脸，又经历心爱的少女茜贝拉（简·格林伍德 Joan Greenwood 饰）因他贫穷拒绝他的求婚，于是着手展开他的复仇计划。他把有爵位继承权的男性亲属一个个用计谋杀掉，旨在自己可以得到公爵爵位，在杀人变得越来越得心应手后，连老弱妇孺都不肯放过，反正他总能制造各种巧合，从来没有人怀疑到他身上。但在复仇计划执行的同时，他也陷入感情困扰——嫁人后的茜贝拉和他藕断丝连，又有个家族内美丽的遗孀艾迪丝（Valerie Hobson 饰）爱上了他，愿意和他订婚，在路易斯得意洋洋继承爵位和举办婚礼之际，他的罪行似乎也要败露……©豆瓣', '亚历克·吉尼斯', '罗伯特·哈默', 8.5, 6666, 'tt0041546', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1112153309.jpg', 0.2, 0.7, 11.7, 51.1, 36.3, '0.274991,0.149749,-0.808630,0.581378,-0.231691,-0.216922,0.725041,0.023809,-0.382719,-0.312911,0.157484,0.890484,-0.039130,0.205016,0.207882,-0.060895,-0.242111,-0.729031,0.095176,-0.030264,-0.175348,-0.670125,0.133598,-0.436549,-0.130848,-0.361332,0.629166,0.046383,-0.035337,0.314814,0.418061,0.336635,0.189165,0.433282,-0.192212,0.107443,-0.036713,-0.051712,-0.101057,0.196897,-0.006414,-0.077045,-0.178887,0.431367,0.141808,0.507758,0.520420,-0.292816,0.091786,-0.234677,0.271255,-0.256165,0.068253,0.405179,0.172189,-0.164346,0.036378,0.543796,-0.216195,-0.309338,0.273445,-0.004246,-0.760477,-0.034369,0.169795,0.198304,-0.600137,0.499729,-0.157536,0.098341,-0.044140,-0.336657,0.223061,0.299056,0.144945,0.117120,-0.259239,0.114529,-0.710935,0.173463,0.820341,-0.046739,-0.166747,-0.052547,-0.517408,-0.262210,-0.037391,-0.486265,-0.797602,-0.029723,0.309480,0.091973,-0.195929,0.471460,-0.353738,-0.350486,-0.309701,-0.099173,0.217569,-0.597977,0.108128,-0.378003,-0.212162,-0.350367,-0.508459,-0.025344,-0.011936,-0.434312,0.505598,-0.756932,0.255518,0.391620,0.515653,-0.788060,0.493237,0.270254,0.234309,0.011995,-0.294309,0.435455,0.174196,-0.146933,0.082095,0.116215,0.218009,0.028766,-0.160156,0.489247', '3215099', '1301022', '25721544', '14