INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296008', '鬼作秀', '喜剧', '全片分六段描述、恐怖的事，有鬼屋、杀人断头．．．．等，集恐怖之大成、饮血吸髓、包您大呼过瘾。', '哈尔·霍尔布鲁克', '乔治·A·罗梅罗', 7.3, 6797, 'tt0083767', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494856236.jpg', 1.2, 4.9, 38.1, 39.7, 16.1, '-0.154526,-0.696181,-0.193617,-0.366364,0.235845,0.272939,0.399098,0.062173,0.239303,-0.004725,0.670694,0.022718,-1.005638,-0.441292,-0.256832,-0.431086,0.745888,-0.239717,0.175083,-0.000052,0.021426,0.316547,-0.400814,0.279819,0.027737,0.193462,-0.536294,0.064592,-0.246818,-0.010871,0.100394,0.347216,-0.050469,0.269762,-0.257186,-0.370755,-0.027310,0.043791,-0.003609,-0.332467,0.158242,0.352855,-0.020044,0.233427,0.085611,0.036129,0.223590,0.097071,-0.433238,-0.003965,0.511161,0.375145,-0.497233,0.104877,-0.252281,0.130052,0.141995,-0.042237,0.207407,0.071620,-0.326071,-0.069504,-0.850879,-0.354088,0.155910,-0.570280,0.246498,-0.290297,-0.216626,-0.073145,0.529094,0.156129,-0.107032,-0.569035,0.281090,0.697430,0.675445,-0.373699,-0.225775,0.764384,0.669525,-0.545410,-0.506608,-0.055300,0.770225,-0.484625,-0.067889,-0.728690,0.200817,0.422025,0.287866,0.024681,0.242433,0.027135,-0.313735,-0.456820,-0.035545,0.084251,-0.421886,0.261277,-0.512097,-0.180761,-0.341865,0.016491,-0.161715,-0.137162,0.546190,-0.456998,0.580147,0.273672,0.225977,0.243175,0.009108,-0.143372,0.179222,-0.151116,-0.059754,0.142461,-0.268789,-0.052538,0.142306,0.432151,0.801918,0.454099,0.031364,-0.000736,-0.751609,0.587542', '6844861', '27098364', '3603547', '6874140');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296011', '红番区', '喜剧', '货车司机黄家驹（成龙）赴美向移居美国的骠叔祝贺新婚之喜，知晓其打算婚后与黑人妻子过安静的晚年生活，经营多年的超级市场也已卖给了年轻寡妇Elaine（梅艳芳）经营。由于一见面就对Elaine有好感，黄家驹主动协助Elaine打点起业务来。不久，以Johnny为首的一帮朋克党开始恶意捣乱破坏超市，面对他们，黄家驹面无惧色勇敢地用起了自己的拳头，同时不忘晓他们以人生大义，然而这波未平那波又起，黄家驹又被卷入了钻石赃物被盗的漩涡，受到了黑手党的追杀。©豆瓣', '成龙', '唐季礼', 7.7, 91881, 'tt0113326', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2095090668.jpg', 0.2, 1.7, 30.2, 49.4, 18.5, '0.219413,0.034888,-0.782029,0.352861,-0.160961,-0.452174,0.756681,0.317219,-0.251073,0.044028,0.097915,0.626860,-0.149786,0.269284,0.335964,-0.194923,-0.079514,-0.536187,-0.161480,-0.011306,0.097843,-0.106977,-0.080826,-0.195059,-0.276268,-0.234050,0.336608,0.023156,-0.171948,0.568148,0.545363,0.135953,-0.085522,0.425939,-0.018906,0.222988,-0.151328,0.143674,-0.555764,0.302841,-0.118021,-0.421294,-0.063664,0.211784,-0.197565,0.449182,0.750970,0.185144,-0.110399,-0.302371,0.490869,-0.034246,0.009436,0.028758,0.538413,0.359826,0.014981,0.243296,-0.254319,0.063747,0.157427,-0.170586,-0.573515,0.211922,-0.123898,0.032571,-0.657925,0.413250,-0.197287,-0.156769,-0.245554,-0.431225,0.180855,0.355046,0.066203,0.325838,-0.167631,0.337306,-0.400785,0.261433,0.766323,-0.069579,-0.094190,0.036103,-0.060559,-0.288905,0.394208,-0.379269,-0.244668,-0.263225,0.544717,0.059707,-0.037081,0.083521,-0.611136,-0.017464,-0.293100,-0.262201,0.282123,-0.167128,0.006486,-0.618614,-0.152132,-0.279651,-0.342278,0.086323,0.277613,-0.024171,0.629571,-0.771019,0.155008,0.628435,0.433569,-0.718840,0.420990,-0.032612,0.146123,-0.090386,-0.097624,-0.157979,0.025061,0.311376,0.333950,0.198169,-0.053800,-0.311753,-0.094611,0.081637', '1301022', '1305364', '3326747', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296026', '见鬼', '剧情', '自幼失明的黄嘉汶（李心洁 饰），接受了眼角膜移植手术，能看见周围的事物，但也因此陷入了无尽的烦恼。她发现，自己除了能看见正常的事物以外，还能看见别人看不见的鬼魂，严重干扰她的生活，嘉汶甚至宁愿自己从来没有看见过。同住一个病房的小女孩瑛瑛手术中去世，来向她告别，目送着瑛 瑛的离开，嘉汶因此明白了“阴阳眼”的好处：能够看到自己希望看到的人。当她终于平静下来，准备接受自己的“与众不同”时，却惊恐莫名地发现，她在镜子中看到的竟然不是自己，而是另外一个女人。在心理医生卢医生（周俊伟 饰）的帮助下，嘉汶找到了眼角膜捐赠者的资料，一个泰国华侨女子，二人到泰国寻找所有事情的答案，他们并不知道，更大的秘密和灾难，在前面等着他们……©豆瓣', '李心洁', '彭发', 7.3, 36439, 'tt0325655', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p919646397.jpg', 0.6, 3.9, 40, 42.9, 12.6, '0.359363,0.137646,-0.877458,0.660257,-0.214556,-0.293608,0.886193,-0.048586,-0.564317,-0.428877,0.025068,0.727168,-0.122101,0.255234,0.025949,0.183921,-0.320257,-0.840706,-0.263053,-0.059106,-0.695581,-0.478095,-0.241773,-0.349515,-0.201203,-0.291320,0.472827,0.240460,-0.048821,0.404195,0.175996,0.154810,-0.148608,0.715111,-0.240463,0.142432,-0.092916,0.095901,-0.218600,0.261626,0.230722,-0.323464,-0.360195,0.546900,-0.229222,0.329712,0.525078,-0.291192,-0.432819,0.053723,0.106114,-0.080692,-0.000139,0.123919,0.038819,-0.171826,0.327637,-0.159636,-0.318288,0.194725,0.096204,0.373547,-0.660515,-0.049931,-0.027198,0.573051,-0.731429,0.307787,0.061429,-0.105529,0.105271,-0.413588,0.459197,0.347592,-0.087967,0.507853,-0.545075,0.088029,-0.812521,0.136441,0.527999,-0.063075,-0.297068,0.573732,-0.297395,-0.451146,-0.051309,-0.015261,-0.465998,0.228451,0.297878,0.410665,-0.541829,-0.130460,-0.315206,-0.141320,-0.128861,-0.370008,-0.250994,-0.423691,-0.015975,-0.552693,-0.097841,-0.253628,-0.725771,0.348686,-0.236356,-0.629801,0.643784,-0.938580,0.245669,0.413097,0.631955,-0.481376,0.904891,-0.158467,0.131104,-0.127097,-0.463332,0.355207,-0.069100,0.389739,0.257804,0.270382,-0.080762,-0.104608,-0.568021,0.468157', '1302384', '3055049', '1292211', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296044', '七小福', '动作', '小龙（张文龙 饰）出生于贫困的家庭之中，母亲无力抚养小龙，于是将他送入了戏剧学校拜于占元（洪金宝 饰）为师，学习技艺。在学校中，小龙结识了三毛（钟锦任 饰）、阿彪（黄剑伟 饰）等同门师兄，彼此之间结下了极为深厚的友谊。校规森严，三毛和小龙等人吃尽了苦头，却依旧热爱着这门事业，于占元虽然表面上黑口黑面，却发自内心的呵护和疼爱着他的弟子们。一次偶然中，三毛结识了名为程水仙的粤剧花旦，两人情投意合，走到了一起。随着时间的推移，京剧的热度逐渐退却，观众越来越少，不少同行转战电影行业，混得风生水起。入不敷出的于占元最终决定关闭学校，小龙等人因此失去了唯一庇护他们的家园，师徒依依不舍的别离，迈向各自的人生。©豆瓣', '洪金宝', '罗启锐', 7.7, 4951, 'tt0095937', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2047110347.jpg', 0.4, 2, 29.1, 47.9, 20.5, '0.126989,0.034410,-0.528085,0.607566,-0.007308,-0.525311,0.535936,0.378081,-0.702330,0.064220,0.120119,0.434301,-0.135786,0.417273,0.136799,-0.356959,-0.180316,-0.638069,0.012397,-0.246374,0.038507,-0.262795,-0.182403,0.158555,-0.511224,-0.179023,0.652816,0.154318,-0.079610,0.637609,0.174019,-0.157497,-0.168868,0.245212,-0.213400,0.221374,-0.042042,-0.055448,-0.357678,-0.066235,0.135422,-0.249804,-0.137195,-0.093551,0.193555,0.200483,0.860973,-0.178626,-0.042644,-0.161575,0.322857,-0.097766,-0.095800,0.105097,0.077864,0.278912,0.431625,0.252759,-0.118618,0.235718,-0.018820,-0.094271,-0.441363,0.208269,0.325881,0.017668,-0.677614,0.798566,0.175276,-0.113330,-0.112136,-0.403446,-0.015904,0.270269,0.030146,0.341336,-0.331912,0.091549,-0.353952,0.186043,0.608094,-0.159693,-0.028401,0.244697,-0.267968,-0.333434,-0.056861,-0.278146,-0.277521,-0.304485,0.482455,0.240150,-0.043973,0.315828,-0.538882,0.074843,0.080218,-0.132921,0.161680,-0.393581,0.127078,-0.679627,-0.126837,-0.601037,-0.255626,0.085014,0.010077,-0.143549,1.115816,-0.709419,0.127014,0.277098,0.347789,-0.351856,0.807474,-0.143436,0.347483,-0.069163,-0.036562,0.216728,-0.163892,0.282660,0.367160,0.418567,-0.184479,0.050700,-0.369799,0.383379', '3811356', '25922902', '1826173', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296078', '断头谷', '悬疑', '十八世纪末期的纽约，警察们还延用古老的办案方式，对罪犯刑讯逼供，年青的警察伊卡布·克瑞恩（约翰尼·戴普 饰）笃信科学的办案方式，因此受到市内同行的排挤，被派到一个叫断头谷的小镇办理一起连环凶杀案。断头谷一直流传着关于“无头骑士”的传说，据说，他是因为嗜血而战的黑森林雇佣军，被敌人割去头颅后，他的孤魂一直在断头谷游荡，在月黑风高之夜，他会骑着快马、 拿着大斧将经过此地的行人的头颅割下。两个月内，小镇中已经三个人惨遭毒手。克瑞恩住进了当地富豪范塔索（迈克尔·甘伯恩 饰）家中，他对“无头骑士”的传说不以为然，但是，又有人接二连三的死去，他还亲眼目睹了“无头骑士”砍掉小镇治安官的头颅，他不得不相信传说的存在，也坚定了要查出真相的决心。经过一番调查，克瑞恩将疑点放在了范塔索身上，同时，他和范塔索的女儿卡翠娜（克里斯蒂娜·里奇 饰）刚刚萌芽的爱情也被残酷的现实所摧毁。就在克瑞恩以为一切真相大白，黯然神伤中准备离开断头谷时，事情发生了意想不到的变化……', '约翰尼·德普', '蒂姆·波顿', 7.6, 113308, 'tt0162661', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2429986978.jpg', 0.3, 2.4, 30.2, 48.7, 18.4, '0.261784,-0.027487,-0.510238,0.358060,-0.010027,-0.022057,0.771522,-0.028651,-0.494318,-0.204618,0.484622,0.461675,-0.165579,0.299507,0.340941,-0.004829,-0.340525,-0.668781,-0.104977,-0.237937,-0.523023,-0.378429,-0.207211,-0.347135,-0.175931,-0.197262,0.315237,0.329123,-0.123750,0.251862,0.315443,0.297104,-0.243837,0.415482,-0.334519,0.022845,0.059015,-0.255672,-0.132067,0.209688,0.104639,-0.350540,-0.068495,0.090706,-0.071965,0.248961,0.670679,-0.295341,-0.016996,-0.050162,0.252660,-0.355597,0.111628,0.247043,0.522402,-0.036302,-0.039038,0.209876,-0.090709,-0.111437,0.171675,-0.225386,-0.659274,-0.059829,-0.036134,0.241158,-0.801835,0.351022,-0.023104,0.192506,0.032608,-0.257230,0.320479,0.093529,0.335326,0.311784,0.038067,-0.175492,-0.492172,0.232251,0.445778,-0.143441,-0.370101,-0.020373,-0.128375,-0.566121,-0.286953,-0.156420,-0.291554,-0.009881,0.541931,-0.069956,-0.300799,0.369304,-0.443352,-0.089098,-0.282562,-0.275193,-0.221203,-0.049114,-0.211738,-0.414519,0.023548,-0.266704,-0.252136,0.238929,0.082024,0.121609,0.407219,-0.521429,0.376231,0.584348,0.185151,-0.336057,0.409715,-0.150471,0.123509,0.004839,-0.105226,0.279930,0.418257,0.474256,0.335636,0.370661,-0.107151,-0.269454,-0.322285,0.367503', '21619567', '1578663', '1805685', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296097', '风烛泪', '剧情', '50年代的意大利，战争带来的恶劣余韵还在持续着，面对强大的生存压力和微薄的养老金，曾经为政府辛辛苦苦工作几十年的退休者们终于呐喊着走上了街头，但很快便被警察驱散了。在散开的人群中，温贝尔托（卡罗·巴蒂斯特 Carlo Battisti 饰）显得格外的凄凉，他身无分文又生了病，即将要因为付不起房租而被赶出住了二十年的老宅，而在他身边一直陪伴着他的，却只有他的爱犬。女房东凶神恶煞，但她的女佣玛利亚（玛丽娅-皮埃·卡西里奥 Maria-Pia Casilio 饰）却对温贝尔托格外关照。但是玛利亚的力量微薄，不足以保全温贝尔托的住处，走投无路的温贝尔托只得牵着爱犬流落街头。他想乞讨，但放不下尊严；他想自杀，但舍弃不了人生；他想丢掉他的爱犬让它另寻主人，但爱犬的不离不弃唤醒了他心中的感动的希望。影片的最后，一人一狗渐渐远去的画面在另一个层面控诉了生活的残酷和无奈。', '卡洛·巴蒂斯蒂', '维托里奥·德西卡', 8.6, 6259, 'tt0045274', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204988530.jpg', 0.1, 0.5, 9.5, 49.2, 40.7, '0.030021,0.211393,-0.601983,0.707383,-0.340137,-0.471999,1.022422,0.307476,-0.373625,-0.100704,0.256425,0.855211,0.176137,0.526291,0.174518,0.173415,-0.150010,-0.576349,-0.100064,-0.034112,-0.306170,-0.418045,-0.294610,-0.374124,-0.383422,-0.194897,0.541730,0.376962,-0.028491,0.265217,0.338849,0.255960,0.003435,0.632268,-0.405159,0.050743,-0.152291,-0.087667,0.009103,-0.060734,0.283382,-0.501961,-0.367560,0.407580,0.120644,0.332004,0.542285,-0.167424,-0.037646,0.152411,0.328782,-0.464210,0.029801,0.226638,0.034243,-0.084403,0.138344,-0.050980,-0.299382,-0.104269,0.176178,-0.021038,-0.762712,0.285266,-0.104428,0.003112,-0.867795,0.575691,-0.072058,0.066926,0.066959,-0.241502,0.206692,0.314429,0.057032,0.475313,-0.427486,-0.117843,-0.638180,0.174211,0.519143,-0.190153,-0.284960,0.310906,-0.653516,-0.374877,-0.016018,-0.452215,-0.673911,-0.356650,0.385295,0.278460,-0.392714,0.225557,-0.663054,0.139031,-0.266643,-0.279235,-0.412174,-0.547024,-0.061184,-0.421548,-0.238149,-0.551562,-0.270042,0.250845,0.017126,-0.298241,0.733955,-0.615277,0.276242,0.715762,0.304284,-0.589802,0.685828,0.187925,0.135840,0.255856,0.013787,0.589184,-0.034434,0.322138,0.592857,0.297784,-0.219040,0.098758,-0.397959,0.764165', '26884422', '351