INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296102', '绝地战警', '喜剧', '迈阿密警局的一对“黄金”搭档，顾家爱妻的好男人宾纳（马丁•劳伦斯）和衣着光鲜风流倜傥的富家子弟劳瑞（威尔•史密斯），奉命追查一桩价值上亿美元的毒品证物失窃案，如果不能及时完成任务，他俩就得卷铺盖走人。在两人疲于奔命之际，该案件唯一的性感女证人打电话到警局声称她愿意指认主谋，但条件是劳瑞必须出面保护她，否则一切免谈，此时劳瑞刚好不在警局，宾纳为套取线索，急中生智冒名顶替。其后，为了不失去女证人的信任，两人只得将对调身份一事进行到底，宾纳在枪林弹雨及汽车追逐中贴身保护女证人，劳瑞则来到他家中陪伴其妻。©豆瓣', '马丁·劳伦斯', '迈克尔·贝', 7.5, 43804, 'tt0112442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p686546035.jpg', 0.4, 3, 33.8, 47.9, 14.9, '0.195420,-0.056424,-0.575682,0.302836,-0.457954,-0.281947,0.363996,0.121050,-0.478949,-0.260989,0.393161,0.585364,0.233703,-0.154255,0.231132,0.019486,-0.588980,-0.511318,0.061505,-0.302806,-0.232320,-0.713142,-0.031478,-0.539141,-0.195275,-0.106018,0.339116,-0.077615,0.104666,0.024129,0.477992,0.311239,-0.449960,0.015337,-0.027543,-0.371657,0.366355,-0.040006,-0.578463,0.363843,0.003438,-0.201537,-0.030882,0.207080,0.198941,0.300171,0.428412,-0.070310,-0.107660,0.053462,0.153954,-0.354574,0.341349,0.072357,0.225566,-0.143814,0.339270,0.460384,-0.405553,-0.264970,0.232789,-0.012024,-0.582582,-0.042966,0.294875,0.281626,-0.332870,0.105456,-0.475912,0.115825,0.110124,-0.391175,0.146474,0.241167,0.088842,-0.157735,-0.091812,0.010598,-0.730282,0.328220,0.603289,0.098073,0.137720,0.140910,0.110675,-0.373065,-0.052340,-0.044115,-0.444619,0.047873,0.352386,0.054180,0.001191,-0.114673,-0.004128,-0.332689,-0.488645,0.029504,-0.299177,-0.394361,0.300673,-0.391308,0.007970,0.098274,-0.223490,0.270032,0.352699,-0.179754,0.277763,-0.397978,-0.038285,0.608702,0.162514,-0.632792,0.403782,0.170362,0.455583,-0.512185,-0.084038,-0.168580,0.489003,0.037543,0.070898,-0.026087,-0.129377,-0.222415,-0.309463,0.182294', '1293434', '1292268', '1428602', '3006781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296109', '变形金刚大电影', '动作', '2005年，经过多年的正邪之争，汽车人终于将霸天虎赶出地球。然而威震天却率领部众入侵了汽车人的总部塞伯坦行星，擎天柱留下通天晓等战士驻守地球，自己则带人马于塞伯坦旁边的两颗卫星建立秘密基地，计划对霸天虎施以致命一击。但是计划被霸天虎侦得，威震天率先对行星和地球的汽车人发起攻击。战斗中擎天柱不幸牺牲，威震天也伤势严重。弥留之际，擎天柱将领导模块传给通天晓。而邪恶的宇宙大帝为了摧毁阻碍自己的领导模块，拯救了被红蜘蛛背叛和抛弃的威震天，将其改造为更为强大的惊破天。汽车人和霸天虎新一代领导人相继浮出水面，正邪大战不断升级……©豆瓣', '彼特·库伦', '尼尔森·申', 8.3, 5173, 'tt0092106', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1809882654.jpg', 0.8, 1.7, 17.8, 40.3, 39.4, '-0.186813,0.205093,-0.836289,0.588589,0.226211,0.216852,0.288831,-0.143047,-0.353045,0.112558,0.254176,0.515374,0.010907,-0.368562,0.393455,-0.091555,-0.098148,-0.534929,-0.029155,-0.045550,-0.584578,-0.256055,-0.256854,-0.493676,0.273405,-0.665059,0.963265,0.500094,-0.081278,0.271404,-0.171302,0.163737,-0.319904,0.505822,-0.113385,0.006854,-0.141351,-0.219840,-0.223682,0.223871,-0.585227,-0.141767,0.009961,0.411756,-0.488432,0.207036,0.458741,-0.579381,0.139377,-0.585372,-0.122638,-0.699251,-0.082939,-0.223937,0.724718,0.136149,-0.069257,0.513116,0.201043,-0.167989,0.036991,-0.017162,-0.870510,-0.342178,-0.300820,-0.397821,-0.462924,0.549673,-0.223248,0.380517,0.076876,-0.150017,0.446188,0.330739,0.314760,0.355021,-0.306417,0.081285,-0.428821,-0.067434,0.527078,-0.225222,-0.344886,-0.166901,0.058336,-0.268520,-0.445874,-0.743135,-0.175118,-0.235001,0.331105,0.188346,0.101535,0.479068,-0.464720,0.025083,-0.455981,-0.502974,0.068864,-0.303045,-0.180903,-0.532190,-0.180332,0.061673,-0.073260,0.376957,-0.023657,0.087390,1.013915,-0.903815,0.181138,0.378824,0.523582,-0.720778,0.598479,-0.233459,-0.055525,-0.463876,-0.111451,0.072450,0.054655,0.625027,0.125829,-0.028933,-0.266500,-0.014720,0.021823,0.120661', '27602116', '3861846', '24284209', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296132', '倾城佳话', '剧情', '查理（尼古拉斯•凯奇）是个善良、温和、喜欢孩子的好警察，却有一个虚荣自私的妻子，他们像所有不搭调的夫妻一样吵闹不断，但是查理总是忍让。一天查理的妻子说梦见父亲并认定有特殊含义，叮嘱查理买彩票。善良的查理在早餐中没有钱付给伊娃小费，就约定如果彩票中了奖就一人分一半，如果没中奖则第二天来把小费补上。没有当真的伊娃没料到奇迹的事情发生了，查理的彩票一下子中了四百万美元巨奖！信守承诺的查理把一半的奖金分给了伊娃，让伊娃从此摆脱了破产穷困的生活，尽管惹来妻子的牢骚不满。晋身富豪的妻子在上流社会谈笑风生，而查理与同样善良热情的伊娃越走越近。妻子把二人告上法庭，要回属于自己的财产，查理与伊娃败诉。打算离开这个城市的二人最后一夜在自己的咖啡店相处，给了雨夜中毫无分文的黑人一碗热汤。这个在纽约城打拼了十年的黑人记者把这一夜的经历写在报纸上，全纽约城的人都知道了这对善良人的故事，纷纷给他们寄来自己的小费。信件如雪片，查理和伊娃靠着全纽约城善良人们的小费，赎回了自己的咖啡店，过上了幸福的生活。', '尼古拉斯·凯奇', '安德鲁·伯格曼', 7.5, 11287, 'tt0110167', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2227936335.jpg', 0.8, 3.6, 33.5, 44.3, 17.8, '0.366757,0.046183,-0.588814,0.424080,-0.536893,-0.511217,0.877418,0.074356,-0.309086,0.062932,0.122329,0.950358,-0.034224,0.000719,0.369414,0.135374,-0.331638,-0.591559,-0.110068,-0.256753,-0.115272,-0.648431,0.029572,-0.218577,-0.205568,-0.112539,0.062153,-0.184618,0.102584,0.475585,0.253403,-0.057408,0.207690,0.399837,-0.389349,0.359283,0.119161,0.265494,-0.237105,0.236797,0.034545,-0.122391,0.002718,0.328603,0.192984,0.329907,0.585107,-0.118579,-0.306391,0.183925,0.421555,-0.201562,-0.107879,0.182948,0.163845,0.088831,0.149895,-0.009557,-0.389242,0.003722,0.170917,0.023365,-0.885272,-0.099700,-0.085812,0.136259,-0.715354,0.862632,-0.062844,0.036995,0.186908,-0.256161,0.421921,0.189011,0.098766,0.457244,0.015013,-0.004401,-0.793293,0.378400,0.537944,0.029815,-0.023569,0.426925,-0.418030,-0.299018,0.147603,-0.130362,-0.698018,0.046291,0.385929,0.030853,-0.354991,0.200356,-0.563039,-0.054929,-0.172210,-0.390289,0.070162,-0.566610,-0.297947,-0.328846,-0.160218,-0.493341,-0.301857,0.095959,0.152986,-0.145968,0.870799,-0.598464,0.341520,0.661608,0.475069,-0.542017,0.785332,0.303346,0.016004,-0.006008,0.138843,0.068838,0.132849,0.323185,0.518199,0.317573,-0.074891,-0.142899,-0.184299,0.702037', '30162520', '26884422', '1299932', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296140', '地球停转之日', '剧情', '随着科技的不断发展，人类赖以生存的地球却受到越来越严重的污染和威胁。某天，一架巨大的飞碟出现在地球上空，引起各国民众一片恐慌，谁也不知道这个不速之客将对他们的命运带来怎样的影响。飞碟最终降落在美国华盛顿公园的中央，当地警察和军队倾巢出动。飞碟被全副武装的军人和好奇的民众团团围住，经过两个小时的对峙，悬梯从飞碟中缓缓探出。随着舱门的打开，一个身形与人类别无二致的外星人克拉图（Michael Rennie 饰）和全身金属的机器人出现在众人面前。这两个外星人似乎为了地球的命运而来，他们表示出友好，却未得到应有的回报……本片荣获1952年金球奖最佳促进国际了解电影奖。©豆瓣', '迈克尔·伦尼', '罗伯特·怀斯', 7.3, 5249, 'tt0043456', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1517027661.jpg', 0.8, 4.5, 37.1, 44.1, 13.5, '0.246534,0.318330,-1.063522,0.737886,0.183033,0.170740,1.028172,-0.208521,-0.360765,0.005303,0.277289,0.838913,-0.261043,-0.109687,0.186817,-0.152363,-0.362248,-0.668996,-0.352522,-0.284791,-0.511592,-0.327403,-0.530362,-0.203137,-0.144338,-0.212101,0.702891,0.185633,-0.162117,0.695595,0.194267,0.215748,-0.120149,0.362606,-0.194871,-0.032219,0.048498,0.005895,-0.169170,0.167987,-0.199281,-0.224794,0.008721,0.191092,-0.375266,0.130036,0.744687,-0.531714,-0.258452,-0.171064,0.531864,-0.409944,-0.021303,0.013184,0.508361,0.090981,-0.208923,-0.157639,-0.047616,0.074559,0.076265,0.065947,-0.687108,0.006644,-0.249273,0.343836,-0.529209,0.454164,0.016882,-0.224076,-0.045467,-0.135999,0.363475,0.666012,0.216502,0.529341,-0.525514,0.170322,-0.544315,-0.166613,0.630132,0.136027,-0.597702,0.011027,-0.421185,-0.611567,-0.266449,-0.227431,-0.278366,-0.235812,0.347484,0.169311,-0.126634,0.314424,-0.630365,0.362100,-0.156586,-0.675153,0.053631,-0.457655,-0.247073,-0.976831,-0.127741,-0.559213,-0.057531,0.351402,-0.089784,-0.066203,0.893664,-0.770324,0.104720,0.604326,0.543584,-0.396245,0.690711,-0.203676,-0.073858,-0.263543,-0.385692,-0.070363,0.189371,0.640167,0.013290,0.325167,0.097091,-0.017410,-0.189026,0.150895', '3005387', '2159244', '34461680', '4079119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296141', '控方证人', '剧情', '伦敦著名刑案辩护律师韦菲爵士（查尔斯•劳顿 Charles Laughton 饰）接受了心脏病治疗，但是身体依旧虚弱，第一天回家休养，护士一直严厉监督他服药，并杜绝烟酒。管家为了便于上楼，还专门为他修了电梯。但是，种种关心照顾，对于这位桀骜不驯、牙尖嘴利的大律师根本不起作用，反倒是一纸诉状令他倍感兴奋。律师梅休和当事人沃尔（泰隆•鲍华 Tyrone Power饰）登门拜访，请他出山打官司。原来，沃尔结识了富婆，两人相见甚欢，虽然仆人对他发明的打蛋器充满鄙夷，但是富婆却对他充满爱意，甚至为他修改了遗嘱，把8万英镑留给了他。然而，富婆却惨遭毒手。于是，沃尔成为警方的头号嫌疑犯。他的唯一证人是妻子克里斯汀（玛琳•黛德丽 Marlene Dietrich饰），然而后者登门时的冷漠与淡定，令韦菲爵士怀疑这其中另有隐情。在扑朔迷离的案件背后，隐藏着一个个环环相扣、不可告人的秘密……本片改编自阿加莎•克里斯蒂同名小说。', '泰隆·鲍华', '比利·怀尔德', 9.6, 488085, 'tt0051201', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1505392928.jpg', 0.1, 0.1, 1.6, 16, 82.3, '0.032920,0.010281,-0.371757,0.423055,-0.006066,-0.221115,0.709698,0.212307,-0.642311,-0.481916,0.012872,0.579918,-0.300571,0.002035,0.223707,0.138836,-0.253410,-0.431011,-0.027996,-0.085551,0.031102,-0.656461,-0.118049,-0.463688,-0.056576,-0.208494,0.273579,0.063506,-0.024154,0.463138,0.297031,0.347946,0.044635,0.437851,0.135034,-0.132259,0.055380,-0.136175,-0.333084,0.040963,0.424591,-0.024165,-0.208712,0.300784,0.210049,0.586766,0.146230,0.028743,-0.473324,0.079176,0.212490,-0.254440,0.040905,0.258930,0.049002,0.078086,0.253585,0.258427,-0.098291,0.055766,0.101525,-0.048314,-0.691332,0.211650,-0.058245,0.039769,-0.296780,0.366905,-0.395113,0.123440,-0.097256,-0.144700,0.167432,0.027273,0.030507,0.227954,-0.181003,0.166979,-0.349902,0.137513,0.138540,0.021012,-0.098590,0.219803,-0.358587,-0.390903,0.160822,-0.167489,-0.500475,0.099145,0.141739,0.150423,-0.078736,0.091100,-0.204736,-0.266047,-0.402283,-0.014593,-0.143222,-0.435263,-0.019002,-0.480077,-0.115851,-0.208322,-0.373058,-0.219351,0.273471,-0.276457,0.498271,-0.584230,0.008026,0.413455,0.092702,-0.584929,0.593415,0.135825,-0.033968,-0.328670,-0.429266,0.250134,0.158939,0.091863,0.248281,0.130875,0.044074,-0.033754,-0.136493,0.156292', '1293145', '1296217', '3670447', '10546747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296147', '呼喊与细语', '剧情', '艾格尼丝（哈里特·安德森 Harriet Andersson饰）、玛丽亚（丽芙·乌曼 Liv Ullmann饰）和卡琳（英格里德·图林 Ingrid Thulin饰）虽然是三姊妹，各人内心却有着积重难返的隔膜和疏离。艾格尼丝身患绝症，生命将近，守护在她身边的是女仆安娜。艾格尼丝没有得到过母亲完整的爱，死前妄想让关系紧张的姐妹变得珍爱彼此，却一再事与愿违。玛丽亚是最得母亲宠爱的孩子，因此遭到姐妹的嫉妒。她的感情生活处理的一塌糊涂，在丈夫和情人之间徘徊周旋。她对爱越是拥有，就越是贪婪。卡琳的生活更是充满压抑。和丈夫的关系陷入僵局，令她沉沦于自虐。和好的愿望太过遥远，她们想摆脱生活的阴影，重新拉近彼此的心，却发现隔膜似乎不可打破。©豆瓣', '哈里特·安德森', '英格玛·伯格曼', 8.6, 27100, 'tt0069467', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2183935299.jpg', 0.4, 1.1, 10.6, 41.5, 46.4, '0.209378,-0.209120,-0.826553,0.758164,0.024014,-0.427403,1.205504,0.214466,-0.640263,-0.076908,0.076551,0.546161,-0.383975,0.281733,0.182952,-0.019837,-0.312539,-0.789602,-0.034724,-0.040302,-0.039304,-0.563973,-0.190325,-0.141566,-0.337771,-0.516498,0.887850,0.041866,-0.148460,0.162725,0.217103,0.548059,-0.123602,0.547477,-0.136017,0.019568,-0.136672,0.037698,-0.618087,-0.277503,0.296722,0.159097,-0.205433,0.386652,-0.015006,0.301889,0.561889,-0.315434,-0.095637,-0.036364,0.157249,-0.174149,-0.062369,0.090059,-0.061514,-0.233043,0.132918,0.228432,-0.300339,-0.062343,0.063850,0.159133,-0.720334,0.205487,0.419130,0.310768,-0.458338,0.484296,-0.152579,-0.086166,0.211138,-0.297567,-0.000547,0.202140,-0.006238,0.608895,-0.417865,0.049729,-0.533353,-0.142440,0.817338,0.043101,-0.205813,0.530186,-0.645705,-0.272151,-0.058123,-0.358143,-0.765058,-0.166606,0.137279,0.305725,0.015309,0.674285,-0.682340,-0.255752,-0.355882,-0.001584,0.325398,-0.965885,0.106865,-0.319051,-0.371293,-0.881364,-0.591131,0.138991,-0.057189,-0.440530,0.765267,-1.044356,0.321422,0.361676,0.517752,-0.518721,0.605582,0.643181,0.054555,-0.325978,-0.172744,0.648390,-0.187107,-0.221439,0.233346,0.043718,-0.030342,0.356792,-0.473795,0.678833', '2131640', '4275444', '24756472', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296148', '玛蒂尔达', '喜剧', '哈里（丹尼·德维托 Danny DeVito 饰）和泽尼亚（雷亚·普尔曼 Rhea Perlman 饰）两夫妻，一个是商人，一个是赌棍，两人再也没有想到的是，他们爱情的结晶，小小的玛蒂尔达（玛拉·威尔逊 Mara Wilson 饰）竟然是个世间罕有的天才。应玛蒂尔达的要求，完全忽视她的教育的父母将她送进了康琴小学，一段新的旅程在玛蒂尔达面前就此展开。身为康琴小学的校长，特拉齐布尔小姐（帕姆·费里斯 Pam Ferris 饰）喜欢听话而温顺的孩子，身为铅球高手，她解决问题的唯一方法就是武力。和暴力的特拉齐布尔小姐完全相反的是一年级老师汉尼小姐（艾伯丝·戴维兹 Embeth Davidtz 饰），她的温柔和耐心让玛蒂尔达如沐春风。聪明的玛蒂尔达发现汉尼小姐似乎有着一些无法结局但又说不出口的难处，她决定用自己的力量帮助汉尼小姐。©豆瓣', '玛拉·威尔逊', '丹尼·德维托', 7.9, 10770, 'tt0117008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2638146106.jpg', 0.4, 2, 24.9, 47.6, 25, '0.368141,-0.014972,-0.284394,0.581435,-0.527171,-0.463214,0.658921,0.152375,-0.489461,-0.356149,0.331318,0.822000,-0.094553,0.013158,0.042840,0.167557,-0.198399,-0.474672,0.028814,-0.226419,0.207869,-0.683350,-0.158478,0.012809,0.004914,-0.422286,0.346409,-0.373423,-0.008190,0.357494,0.375752,0.199699,0.134659,0.415148,0.035658,-0.052843,0.147304,-0.104360,-0.062864,0.126230,0.052874,0.391908,-0.017674,0.144759,0.087157,0.309414,0.398845,-0.371673,-0.013459,-0.030810,0.497063,-0.203111,0.109265,0.347047,0.139328,-0.302098,0.170858,0.008890,-0.073196,-0.042558,0.437646,-0.124834,-0.726237,-0.031711,0.054944,0.106753,-0.673179,0.322465,-0.290999,-0.492180,0.076267,-0.428185,-0.071315,0.235692,0.217818,0.316907,-0.183130,-0.051948,-0.665957,-0.267276,0.461821,-0.126622,-0.286209,0.263886,-0.499174,-0.727123,-0.066034,-0.567985,-0.569095,0.122358,-0.013104,0.020986,0.095479,0.174544,-0.617359,-0.081578,-0.492422,0.074813,0.035555,-0.635848,0.072970,-0.264912,0.144186,-0.464218,-0.511049,-0.237556,0.159231,-0.477687,0.950770,-0.796476,0.148655,0.569091,0.366472,-0.024068,0.704566,0.169915,-0.199540,-0.141799,-0.025290,0.298902,-0.215821,0.173602,0.025743,0.714372,0.347595,-0.258371,-0.027176,0.548584', '24284209', '26348103', '27602116', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296153', '八毫米', '悬疑', '一个去世议员的家人无意中发现了议员的一件遗物——一卷8毫米的影片，里面竟然有女孩被虐杀的整个过程，于是交给了一名私家侦探汤姆威勒（Nicolas Cage尼古拉斯•凯奇饰）调查真相。汤姆威勒本来平静的生活开始危机四伏。汤姆威勒一步步破解真相的过程，亦是一步步陷入泥潭的过程。但是影片中陌生女子的受虐惨剧在他脑中挥之不去。良心促使他在凶险的真相面前变得无惧。但当真相揭露之时，世间的丑恶不堪得令汤姆威勒也陷入了惊恐……©豆瓣', '尼古拉斯·凯奇', '乔·舒马赫', 7.3, 28393, 'tt0134273', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1088311945.jpg', 0.4, 3.6, 37.1, 46.2, 12.7, '0.325581,0.152930,-0.637368,0.373236,-0.053811,-0.144074,1.000858,-0.010394,-0.622391,-0.449822,0.348631,0.629534,-0.291958,0.070575,0.366353,0.175129,-0.233723,-0.742786,-0.295184,0.013778,-0.223911,-0.494426,-0.338845,-0.478808,-0.063166,-0.468416,0.697095,0.603739,-0.268231,0.182888,0.011905,0.496048,-0.144740,0.366764,0.198153,0.000373,0.296767,-0.224896,-0.299590,-0.105356,0.103266,-0.454264,-0.208698,0.533480,-0.269125,0.180888,0.824840,-0.326770,-0.441907,0.261307,0.617930,-0.203073,-0.407197,0.167174,0.199649,0.086060,0.207105,0.302898,-0.089781,-0.196042,0.180122,0.111064,-0.789005,0.022065,0.045345,0.422288,-0.102913,0.111744,-0.151860,0.302910,0.006048,-0.331021,0.233482,0.145552,0.466095,0.373139,-0.290932,-0.006590,-0.448146,0.101102,0.514684,0.028719,-0.405316,0.296418,-0.253845,-0.486545,-0.188861,-0.341713,-0.562055,0.135024,0.436883,0.072028,-0.553248,0.816826,-0.314064,-0.186099,-0.431584,-0.083581,-0.294933,-0.328623,-0.465122,-0.118878,-0.455665,-0.050412,-0.346274,-0.392263,0.016885,-0.256018,0.624586,-0.349997,0.492242,0.412844,-0.358033,-0.038015,0.499855,-0.024194,0.193754,0.049503,-0.026302,0.300371,0.233107,0.094361,-0.012268,0.367711,-0.124267,-0.117135,-0.453760,0.390025', '2377539', '1292528', '25909236', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296157', '迷墙', '剧情', '本片用迷幻的影像和摇滚乐讲述了一个非典型乐队主唱的成长史。儿时，平克（鲍勃•吉尔道夫 Bob Geldof  饰）的父亲在二战中身亡，母亲与家庭医生关系暧昧，这让他幼小心灵备受创伤。在学校，他对呆板的填鸭教育深恶痛绝，时刻准备着绝地反击。成年后，他在泡吧时结识了风骚的舞女，并与之发生了关系。然而，性欲的满足感并没有维持太久，他就厌倦了这种不靠谱的感情，特别是他对于女人的怀疑和嫉妒达到了无以复加的地步，因此当对方再度示好投怀送抱的时候，他便歇斯底里地爆发了，仿佛要把全世界都砸碎了才算安心。在此期间，他还表达了强烈的反战情绪和愤世嫉俗的观念，在物质丰富的生活中，他的精神生活极度匮乏，在工业化大行其道的环境里，他还固守着梦想的断壁残垣……©豆瓣', '鲍勃·吉尔道夫', '艾伦·帕克', 8.8, 47580, 'tt0084503', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567407809.jpg', 0.6, 1.5, 11.3, 32.4, 54.2, '0.250853,0.043665,-0.925159,0.708579,-0.267261,-0.128358,0.957752,0.132046,-0.548360,-0.074669,0.077819,0.709483,-0.339045,0.428625,0.168762,-0.121357,-0.100045,-0.907107,-0.158197,-0.051560,-0.138006,-0.357186,-0.350641,-0.140445,-0.245645,-0.597809,0.560679,0.091473,-0.529794,0.309375,-0.001719,0.152664,0.323616,0.855831,-0.253762,-0.005973,-0.070292,0.084708,-0.051712,-0.058898,0.286938,-0.529727,0.048923,0.526754,-0.067874,0.363267,0.803110,-0.397373,-0.302753,0.002764,0.313312,-0.149228,-0.174674,0.403955,-0.015668,-0.067978,0.092085,0.272542,-0.193513,0.108865,0.019577,0.051766,-0.925822,-0.042475,-0.135747,0.048603,-0.680338,0.781866,-0.001491,-0.191464,0.053716,-0.217627,0.304548,0.216981,0.117160,0.619852,-0.394996,-0.135459,-0.428624,0.398794,0.716138,-0.016024,-0.548637,0.519768,-0.591741,-0.563539,-0.154496,-0.233538,-0.513526,-0.389029,0.153584,0.180833,-0.465163,0.271617,-0.551039,0.133505,-0.024243,-0.211206,-0.108669,-0.457043,-0.018279,-0.634782,-0.427977,-0.751539,-0.375355,-0.079871,0.139050,-0.253134,0.811661,-0.969900,0.261476,0.661132,0.346060,-0.523625,0.596740,0.152932,-0.167701,-0.047503,-0.188285,0.298430,-0.373523,0.358396,0.278109,0.499895,-0.021089,0.131606,-0.354796,0.959768', '35158375', '24756472', '4058933', '3742987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296172', '情欲写真', '剧情', '克莱丽（苏菲·玛索 Sophie Marceau 饰）年轻貌美又独具才华，一次偶然中，她和名为克里夫（帕斯卡·格里高利 Pascal Greggory 饰）的男子相遇了，克里夫醉心于克莱丽独特的气质之中，而克莱丽亦爱上了克里夫，两人很快走到了一起，准备踏入婚姻的殿堂。就在这个节骨眼上，一个名叫莫内（吉约姆·卡内 Guillaume Canet 饰）的摄影师闯入了克莱丽的生活之中。和温文尔雅的克里夫不同，莫内粗鲁有不羁，然而，正是这份狂野深深地吸引了克莱丽。一边是许下了神圣誓言后结为连理的丈夫，一边是不断抗拒但又情不自禁想要靠近的情人，夹在两人之间不知该如何选择的克莱丽终于感受到了生命之重与爱情之苦。©豆瓣', '苏菲·玛索', '安德烈·祖拉斯基', 7, 8543, 'tt0204761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1277365907.jpg', 1.7, 8.1, 44.1, 31.5, 14.6, '0.519007,0.372666,-0.714082,0.766933,-0.012834,-0.453744,0.999359,0.189727,-0.364329,0.134160,0.004846,0.673664,-0.348272,0.224102,0.715662,0.410349,-0.455139,-0.683958,0.055495,-0.442734,-0.483383,-0.767453,-0.162234,-0.022273,-0.159847,-0.206589,0.484303,-0.188772,0.002154,0.584543,0.608591,0.625059,-0.250589,0.542503,-0.035696,0.027585,0.432742,-0.022824,-0.068103,0.183002,0.342460,-0.387323,-0.023974,0.238465,-0.136153,0.149189,0.330374,-0.621487,0.281946,-0.115901,0.330310,0.171821,0.206887,0.447655,-0.043926,-0.046742,0.162687,0.060199,-0.525271,-0.226882,0.182908,-0.172186,-0.489919,-0.085297,0.001865,0.257221,-0.592248,0.498471,0.063759,-0.266754,0.091082,-0.214315,-0.120253,0.097567,0.571376,0.138127,-0.131741,-0.287741,-0.344675,-0.368393,0.545780,0.317754,-0.346078,0.508617,-0.088972,-0.287357,-0.142916,0.023664,-0.612152,-0.388754,0.363355,0.356098,0.373561,0.297988,-0.731162,-0.061875,-0.634245,0.017452,-0.022480,-0.326646,-0.221432,-0.439445,-0.403687,-0.661443,-0.578140,0.259053,-0.049583,-0.250777,0.755732,-1.036149,0.277244,0.391121,0.352025,-0.227852,0.694271,0.056696,0.359850,0.014147,0.015751,0.399087,0.186908,-0.009822,0.282100,0.688435,-0.279848,-0.006262,-0.277520,0.827883', '1299556', '3230121', '24756472', '20277433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296196', '乱', '剧情', '一文字秀虎（仲代达矢饰）征战多年，手段残忍。在七十岁时，秀虎准备将家业一分为三，由三个儿子分掌大权。他把太郎孝虎（寺尾聪饰）、次郎正虎（根津甚八饰）、三郎直虎（隆大介饰）叫到跟前，以“支箭会断，砚支箭折不断”喻语告诫三兄弟，嘱咐他们要休戚与共。三郎当场把三支箭横在膝上折断，以抗议父亲枉经乱世，而不知人情。秀虎大怒，将三郎驱逐出境。三郎遂到邻国入赘为婿。而之后一文字家果然被三郎言中，背信弃义的告诫果然成真，父子及兄弟间的纷乱开始，迎接他们的将是什么命运？©豆瓣', '仲代达矢', '黑泽明', 8.9, 80726, 'tt0089881', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2556724149.jpg', 0.3, 0.6, 7.5, 35.8, 55.9, '0.171887,-0.036789,-0.354838,0.355902,0.239129,-0.539364,0.303329,0.184101,-0.383535,0.060561,0.157974,0.611524,-0.117411,0.085372,0.258329,0.042026,0.359284,-0.856489,-0.298559,-0.127750,-0.275605,-0.641164,0.215070,-0.056706,-0.309289,-0.121719,0.126315,-0.078661,0.114759,0.247966,0.067501,0.121957,-0.200515,-0.124740,-0.151201,0.216033,-0.193023,0.009801,-0.370872,-0.065173,-0.078725,-0.405605,-0.247591,0.151058,-0.203097,0.217921,0.689288,-0.402568,0.241580,-0.291814,0.158638,0.000216,-0.218105,0.321310,0.310627,0.082237,-0.092751,0.555947,-0.276608,-0.230297,0.235750,-0.186123,-0.429000,-0.001818,-0.358794,-0.136440,-0.848993,0.134592,-0.306219,-0.073274,0.005239,-0.459258,0.321125,0.339324,0.227025,0.203472,-0.461029,-0.104422,-0.172402,0.185723,0.527113,-0.258208,0.295326,-0.146937,0.330550,0.045818,0.001923,-0.327266,-0.229796,-0.247904,0.447863,0.065807,0.005236,0.008706,-0.286134,-0.300875,-0.323261,0.034284,0.294168,-0.501953,-0.241400,0.205154,0.128324,-0.274131,-0.436734,0.401572,0.587405,-0.085470,0.749081,-0.510771,-0.211167,0.140900,0.226930,-0.262085,0.293653,-0.036226,-0.015787,-0.032464,0.112939,-0.422804,0.388933,0.086240,0.698217,0.309280,-0.267850,-0.006093,-0.128606,0.230815', '1307146', '35048413', '34869495', '1293607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296201', '逃学威龙2', '喜剧', '周星星（周星驰 饰）圆满完成了校园任务后，以为可以升职，偏偏被调为交通警察。跟他一样立功的曹达华（吴孟达 饰）则继续以卧底的身份在学校内调查国际恐怖组织的案件。他的事业跌到了低谷，就连准备婚礼的钱都是女友阿敏（张敏 饰）的私房钱，令阿星十分无奈。为了证明自己的能力，他决 定以个人的身份到学校协助曹达华，恐怖分子如期行动，双方开始奋战。©豆瓣', '周星驰', '陈嘉上', 7.8, 186149, 'tt0105534', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2563028145.jpg', 0.2, 2.1, 28, 45.3, 24.4, '0.163836,0.135017,-0.500986,0.595960,-0.245313,-0.222671,0.081500,0.336153,-0.440756,-0.122746,0.320672,0.464781,0.015500,0.097956,0.200642,-0.434995,-0.376967,-0.878052,-0.095008,-0.185725,-0.283798,-0.451405,-0.155770,-0.193513,-0.321469,0.101204,0.591526,0.020808,-0.036388,0.305368,0.457799,0.170565,-0.009789,0.347456,-0.105598,-0.138465,0.199908,0.074301,-0.278282,0.212208,0.184107,-0.221590,-0.085288,0.218912,0.354991,0.378000,0.648322,0.159146,-0.173101,-0.120771,0.336147,-0.293238,0.180071,0.107679,0.454909,0.129811,0.228544,0.310685,-0.053582,0.154055,0.159484,-0.160638,-0.901601,-0.085013,0.047554,0.144047,-0.523688,0.408673,-0.304003,0.049289,0.154333,-0.371015,0.060755,0.443894,0.221418,0.202064,-0.340433,-0.032945,-0.609606,0.549631,0.317319,-0.026749,0.164996,0.384478,0.135258,-0.475888,-0.154378,-0.015896,-0.296190,0.086548,0.265610,-0.051278,-0.074229,0.006207,-0.424151,-0.355445,-0.155878,-0.255274,-0.249952,-0.514678,0.115704,-0.574949,-0.093316,-0.090383,-0.221875,0.148849,0.227072,-0.167038,0.328662,-0.910086,-0.148941,0.669074,0.178893,-0.797163,0.335613,0.062042,0.180247,-0.386579,-0.072784,-0.248320,0.018539,0.403770,0.072374,0.286481,0.021294,-0.475418,-0.264818,0.454027', '30345227', '1986338', '3811342', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296203', '警察故事3：超级警察', '喜剧', '这集，神勇干探陈家驹（成龙 饰）将远赴大陆，化身囚犯打入国际军火毒品走私集团的内部。在大陆美女公安杨建华（杨紫琼 饰）的帮助下，家驹顺利接近了正在服刑的集团成员豹强（元华 饰）。豹强视家驹为心腹，和他策划越狱行动。为了放长线，家驹爽快应承了。他们越狱后，豹强主张到家驹随口编出来的家乡躲避，幸得杨建华提前安排，才没有漏出马脚，杨建华自称家驹妹妹，与他们同行。他们来到香港见到了集团的老大猜霸，顺利成为集团的一员。猜霸带着手下前往吉隆坡营救被绑架的妻子，遇到了家驹的女友阿美（张曼玉 饰）。阿美不知家驹正在执行任务，以为他和杨建华在偷情。阿美的举动引起了集团成员的怀疑，连场大战一触即发！©豆瓣', '成龙', '唐季礼', 7.8, 60984, 'tt0104558', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233939993.jpg', 0.2, 1.3, 26.5, 50.6, 21.4, '-0.059707,0.045843,-0.825933,0.436185,0.000475,-0.022561,0.149728,0.184060,-0.329120,-0.307197,0.357038,0.512249,-0.029820,-0.096544,0.479040,-0.201060,-0.268827,-0.606683,-0.233499,-0.149879,0.067514,-0.257542,-0.188394,-0.246537,-0.193365,-0.164181,0.501483,0.228629,-0.142199,0.632587,0.416016,0.343992,-0.517317,0.359954,0.026457,0.077202,0.469609,0.120282,-0.622468,0.361967,-0.069016,-0.046743,0.090110,0.094062,0.260075,0.276021,0.475836,-0.038765,-0.197096,-0.175094,0.118819,-0.553421,0.338653,-0.310616,0.802534,0.015632,0.201300,0.427143,-0.227695,-0.191633,-0.041416,-0.266197,-0.895281,0.114734,0.290302,-0.007856,-0.532742,0.350345,-0.317878,-0.044712,0.085135,-0.319421,0.564101,0.886617,0.386147,0.124695,0.164463,0.453216,-0.576609,0.129757,0.820047,-0.174013,0.107860,-0.138059,0.317256,-0.205405,0.135480,-0.304014,-0.007882,0.119238,0.257304,-0.130689,-0.075235,0.190633,-0.423055,-0.371690,-0.282954,0.042844,0.289731,-0.331397,0.052451,-0.578723,0.027513,0.002459,0.051339,0.138707,0.032265,-0.214269,0.452914,-0.957962,0.114670,0.412732,0.617150,-0.785879,0.592721,-0.047241,0.104650,-0.477881,-0.057930,-0.226527,0.229939,0.193316,0.292974,0.203713,-0.074349,-0.476592,-0.171291,-0.353720', '1482541', '1296947', '5157137', '30211551');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296217', '一级恐惧', '剧情', '芝加哥发生了一桩震惊全城的恐怖血案。当地一间教堂的主教罗森惨遭杀害，身上被刻上神秘数字，警方逮捕了当时在场身染血迹的犯罪嫌疑人阿伦（ Edward Norton 饰）。马丁（理查•基尔 Richard Gere 饰）作为阿伦的辩护律师，和他的前女友检控官珍妮特较上了劲。马丁并不在乎事实，他为阿伦辩护的唯一目的就是要赢得官司，让自己一战成名。而珍妮特作为正义的代表当然寸步不让。珍妮特（劳拉•琳妮 Laura Linney 饰）调查得知罗森主教生前曾对阿伦等人进行性侵犯，而阿伦关于自己患有“时间失忆”症的辩解亦显得荒唐，关于他提到的凶案证人一直都未找到。珍妮特认为杀人动机等一切证据俱全。马丁借口阿伦患精神病使其成功脱罪，然而，一切皆出人意料。', '理查·基尔', '格里高利·霍布里特', 8.5, 197554, 'tt0117381', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1150407027.jpg', 0.1, 0.7, 11.7, 48.9, 38.5, '0.215530,0.009562,-0.450455,0.294703,-0.101207,-0.180537,0.748462,-0.035265,-0.634615,-0.582053,0.306345,0.486123,-0.136842,-0.107832,0.328613,-0.017830,-0.373275,-0.636479,0.220773,-0.150697,-0.076122,-1.044059,-0.219152,-0.361834,-0.051868,-0.312089,0.173701,0.055565,0.044847,0.256590,0.449765,0.511869,0.083563,0.227430,0.272235,-0.236966,0.064393,-0.189407,-0.408669,-0.118545,0.150914,-0.409978,-0.058741,0.516472,-0.142060,0.668163,0.147959,-0.100929,-0.138957,-0.090322,0.344942,-0.443162,0.312706,0.250491,0.183930,-0.043906,0.365424,0.532402,-0.047968,-0.436128,0.177350,0.175623,-0.857911,0.008441,0.280169,0.374987,-0.065107,0.258633,-0.503964,0.162183,-0.094611,0.012402,0.183772,0.138562,0.394401,0.184744,-0.093527,-0.107865,-0.323916,0.016094,0.463787,-0.158695,-0.132378,0.060350,-0.115848,-0.371343,-0.044173,-0.125569,-0.154641,0.397961,0.047179,0.074023,0.057589,0.293487,-0.170483,-0.347174,-0.627665,-0.128050,-0.194245,-0.047846,0.086282,-0.490170,-0.084080,0.074216,-0.380142,-0.307534,0.239158,-0.323600,0.212114,-0.508841,0.140729,0.448330,-0.072724,-0.606166,0.281281,0.229493,0.168085,-0.239768,-0.191083,0.355640,0.267880,-0.034778,-0.077762,0.078299,0.214519,-0.275702,-0.115476,0.304199', '25862560', '26331839', '4132395', '2996790');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296218', '过年', '剧情', '一年一度的农历春节来临，生活在东北农村的程家老两口（李保田 & 赵丽蓉 饰）满心欢喜地等待儿女回家过年。去年的团圆饭不欢而散，因此母亲更加盼望这次能过个愉快的团圆年。不久，子女们陆续回来：长子（六小龄童 饰）木讷老实，大媳妇（丁嘉丽 饰）泼辣刁蛮；干部大姐夫（葛优 饰）不走正道，在外拈花惹草，还强逼妻子堕胎；小儿子（梁天 饰）不务正业，贪图享乐，只知道伸手要钱；父亲最疼爱的二女儿当初忤逆父命嫁给架子工（申军谊 饰），如今自食其力干出事业的小两口也再次归来。看似喜庆祥和的兄弟妯娌们却各有各的小九九，不知今年的年夜饭该如何收场……赵丽蓉籍此片获1990年第4届东京国际电影节评委最佳女主角大奖。©豆瓣', '赵丽蓉', '黄健中', 8.9, 48648, 'tt0206313', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206392237.jpg', 0.1, 0.3, 7.4, 39.7, 52.5, '-0.132252,-0.125622,-0.542716,0.114951,0.078524,-0.328571,0.091062,0.384537,-0.494954,-0.327938,0.189346,0.511664,-0.233743,0.393226,0.197164,-0.106722,-0.140930,-0.181391,0.159872,0.035234,0.254802,-0.007229,0.220278,0.170568,-0.169213,0.337884,0.231875,0.035731,0.412061,0.454116,0.586145,-0.081297,0.077293,-0.042536,-0.242894,0.034327,-0.143155,0.437778,-0.482053,-0.191585,-0.109417,-0.096712,-0.449422,-0.358822,0.469703,0.158561,0.534798,0.135356,0.140593,-0.193027,0.515442,0.010816,-0.319657,0.231977,0.270220,0.017067,0.335156,0.175638,0.063317,0.196917,-0.292339,-0.464827,-0.017871,0.100475,0.151491,0.059828,-0.537032,0.334068,0.031362,-0.029656,-0.051000,-0.356084,0.192545,0.580950,-0.165961,0.623329,-0.133577,0.383241,-0.338385,0.560402,0.627905,0.009541,0.083455,0.077538,-0.206962,-0.254525,0.596605,-0.730050,-0.709252,0.102808,0.163578,0.035563,0.067019,0.387030,-0.055725,-0.054924,0.038697,-0.073685,0.418634,-0.311890,-0.005413,-0.460879,0.128499,-0.408295,-0.213847,0.244367,0.208186,-0.136121,0.650315,-0.399429,0.338382,-0.060799,0.205948,-0.708308,0.441188,0.597179,0.466627,-0.373222,-0.174645,-0.040782,-0.166502,-0.173710,-0.159240,0.083614,-0.206925,-0.298164,-0.049742,0.062581', '24879820', '1308035', '1421278', '4066127');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296223', '伊丽莎白', '剧情', '本片荣获最佳影片、最佳导演、最佳女主角、最佳造型化妆奖等各项荣誉。1554年，在玛丽一世血腥的统治下，英国陷入了空前的混乱。直到1558年她驾崩，她同父异母的妹妹伊丽莎白（凯特·布兰切特 Cate Blanche tt 饰）登上女王的宝座，举国上下一片欢腾。令伊丽莎白兴奋不已的不仅仅是登上王位， 还有幼时的心上人罗伯特-达德利（约瑟夫·费因斯 Joseph Fiennes 饰）结束流放，重新走进了她的生活。但突如其来的宫廷政变、暗藏的阴谋、大臣的欺骗、国家糟糕局势，无不给这位新任女王带来危机。但她运用自己的智慧，在一次次宫廷政变中，华丽脱身，一次次扫除异己，巩固了自己的王位，并将16世纪的英格兰从岌岌可危的边缘推向昌盛的顶点。但伊丽莎白拒绝任何政治上的联姻，坚持追求真爱。这位威严、冷峻、刚毅的女王最后终生未嫁，只与国家和权利终身为伴。©豆瓣', '凯特·布兰切特', '谢卡尔·卡普尔', 7.7, 34890, 'tt0127536', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p880919713.jpg', 0.3, 1.9, 29.1, 50.9, 17.8, '-0.152247,0.519400,-0.629253,0.763688,0.017029,-0.195193,0.601466,0.290240,-0.551498,-0.088412,0.430867,0.721684,-0.124158,0.009749,0.579270,0.078889,-0.313677,-0.748020,-0.123873,0.145155,-0.080762,-0.424582,-0.439571,-0.167496,-0.333758,-0.506403,1.028009,0.071580,-0.237956,0.310414,0.348581,0.167735,0.237744,0.452880,-0.073757,-0.051269,-0.032507,-0.201000,-0.407476,0.200052,-0.103174,-0.500834,-0.253611,0.468083,-0.030018,0.254329,0.402179,-0.544707,0.092188,-0.196953,0.736980,-0.367045,-0.158936,0.306737,0.027608,-0.193616,-0.157989,0.444993,-0.090712,-0.246457,0.041254,-0.225836,-0.699303,0.065388,-0.129425,0.078277,-0.443551,0.617911,-0.104003,0.046457,0.159451,0.065217,0.280821,0.468887,0.149868,0.332952,-0.262143,0.202314,-0.312265,0.354431,0.603827,0.003542,-0.408506,0.053608,-0.328314,-0.469581,-0.009015,-0.623268,-0.554793,-0.205822,0.346412,0.182859,0.255015,0.476179,-0.528943,-0.022637,-0.469020,-0.310986,0.171859,-0.429379,-0.016408,-0.552974,-0.398749,-0.337496,-0.236880,-0.110716,0.085765,-0.489362,0.668075,-0.642361,0.256632,0.399240,0.115121,-0.508680,0.546429,0.256350,0.188763,-0.165570,-0.474384,0.546120,-0.029674,0.114988,-0.198824,0.090115,-0.169699,-0.004643,-0.338586,0.633564', '5308201', '25880