INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296230', '呆头鹅', '喜剧', '由伍迪·艾伦编著并主演的本片，描述一名亨佛莱鲍嘉的大影迷，整天梦想自己成为鲍嘉，连妻子也受不了离他而去，于是他找寻新的伴侣，结果找到了朋友的妻子。导演赫伯特·罗斯把此片从亨佛莱鲍嘉在《北菲谍影》里的形象发展出来，压轴戏完全重复了《北菲谍影》的场面，但情节却恰恰相反，因而制造出不可言喻的幽默妙趣。其中更有伍迪·艾伦的精彩表演，对于伍迪·艾伦的影迷而言，此片是非看不可。', '黛安·基顿', '赫伯特·罗斯', 8, 6145, 'tt0069097', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2551797574.jpg', 0.3, 1.2, 20.9, 54, 23.6, '0.096568,-0.209731,-0.528921,0.615649,0.072063,-0.344672,0.710558,0.099889,-0.383528,-0.357837,-0.069744,0.885674,-0.151373,0.078322,0.277527,0.003153,-0.253231,-0.600230,-0.118088,-0.029720,0.151625,-0.382436,-0.208797,-0.183960,-0.312541,-0.291644,0.534355,-0.011201,-0.333392,0.004762,0.501558,0.196797,0.060847,0.434249,0.031783,0.227563,0.032712,-0.139404,-0.265098,0.321495,0.211934,-0.021701,-0.162194,0.333178,-0.163742,0.318833,0.341711,-0.494491,-0.139961,0.107467,0.495871,-0.359123,-0.003408,0.030786,-0.040119,0.014125,0.423720,-0.059715,-0.136721,0.141009,-0.028795,-0.125574,-0.916123,0.164713,0.043517,0.368681,-0.362412,0.389064,0.048292,-0.210954,-0.025345,-0.407507,0.172300,-0.257966,0.310040,0.136174,-0.291413,0.059147,-0.154730,0.185097,0.506905,0.147630,-0.103484,0.364386,-0.371859,-0.444705,-0.175543,-0.362172,-0.450759,0.159801,0.191458,0.152889,0.010601,0.251815,-0.477544,-0.036502,-0.283049,-0.146032,-0.451268,-0.585067,0.102833,-0.650884,0.021361,-0.205656,0.006838,-0.183664,0.070638,-0.583519,0.716496,-0.588950,-0.168551,0.471847,0.104180,-0.379747,0.489148,0.063985,0.176908,-0.202893,-0.288885,0.589863,-0.022602,0.097234,0.098367,0.227322,0.036391,-0.483690,-0.262465,0.423520', '34890458', '4301278', '27602116', '26834930');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296240', '南北少林', '剧情', '北少林棍僧智明（李连杰 饰）为报父母之仇，日日苦练功夫，他天性纯良聪明，深得师父器重。这天，智明收下的一班顽童“徒弟”向他报信，声称退隐多年的赫索王爷再度出山摄政，智明听闻杀父仇人消息怒发冲冠，随即下山为赫索祝寿伺机行刺。与此同时，和智明一样与赫索有血海深仇的莆田南少林俗家弟子司马燕（黄秋燕 饰）亦北上刺杀赫索，南少林派出另一俗家弟子赵威（胡坚强 饰）暗中接应与保护司马燕。在赫索的寿诞庆典上，智明、司马燕与赵威等人联手行刺，却仍然功亏一篑，三人在重重围堵中逃出，而路上，智明发现司马燕居然是他指腹为婚的未婚妻，身为出家人的智明无法迎娶司马燕，三人计划再度行刺赫索……©豆瓣', '李连杰', '刘家良', 7.1, 10316, 'tt0091607', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2286331031.jpg', 0.6, 3.7, 46.8, 36.8, 12.2, '-0.097908,-0.124640,-0.346081,0.705033,0.040695,-0.093446,0.131053,0.006456,-0.635053,-0.764175,0.062048,0.792058,0.019247,0.456371,0.313986,-0.220864,0.362532,-0.518715,-0.415791,-0.000228,-0.085900,-0.503629,0.128685,-0.590938,-0.076434,-0.006485,0.283918,0.376642,-0.118270,0.887214,0.397122,-0.040269,-0.508931,0.364125,-0.125756,0.194431,-0.032235,0.253549,-0.252052,0.220754,-0.284069,-0.493807,-0.280691,0.123760,0.039454,0.590941,0.124737,-0.216642,0.125828,-0.255142,-0.222391,-0.176910,0.453979,0.445763,0.275150,-0.085950,0.247058,0.297631,-0.143950,-0.178911,-0.300623,-0.348752,-0.150909,0.306290,0.515692,-0.443088,-0.518776,0.206395,-0.357154,0.216230,-0.199814,-0.280372,-0.000256,0.407437,0.194634,-0.109933,-0.111134,-0.050070,-0.270380,0.125281,0.581699,-0.004345,0.354217,-0.451192,0.429565,-0.249980,0.190460,-0.398542,0.124846,-0.112196,0.594269,-0.097008,0.167169,0.091483,0.151234,-0.400086,-0.313077,0.680420,-0.070067,-0.069193,0.150384,-0.523875,0.168760,-0.352372,-0.137216,0.270148,0.168432,-0.347494,0.513227,-0.605772,0.130956,-0.176611,-0.177889,-1.045839,0.655861,0.014632,-0.248247,-0.017308,0.041977,0.390378,0.327059,0.037769,0.253691,0.263639,-0.375930,-0.019268,-0.230657,-0.083218', '1300883', '1416728', '1968502', '1297497');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296242', '巴黎圣母院', '剧情', '爱斯米兰达是一个性格活泼热情似火的吉普赛女郎，生性善良的她赢得了许多人的赞美和喜爱。巴黎圣母院的神父克洛德觊觎爱斯米兰达的美貌已久，终于按奈不住派出手下样貌丑陋的撞钟人卡西莫多，将爱斯米兰达强行掠夺至巴黎圣母院，谁知道半途杀出了英俊勇敢的上尉菲比斯，后者令爱斯米兰达一见倾心。菲比斯遭到了蒙面歹徒的袭击，而爱斯米兰达居然成为了罪魁祸首。爱斯米兰达被判处绞刑，在行刑之前，卡西莫多救走了身陷囹圄的爱斯米兰达，将她藏到了巴黎圣母院之内。起初，爱斯米兰达对卡西莫多充满了戒备，但随着时间的推移，她渐渐了解到，在卡西莫多丑陋的外表下，隐藏这一颗金子一样的心。©豆瓣', '吉娜·劳洛勃丽吉达', '让·德拉努瓦', 8.1, 28432, 'tt0050781', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1942074866.jpg', 0.2, 0.9, 19.1, 54.4, 25.3, '0.424949,0.147084,-0.699480,0.503395,-0.411429,-0.320776,0.886299,0.085989,-0.180717,-0.031695,0.312388,0.596786,-0.481332,0.032930,0.274500,0.260787,-0.347869,-0.553428,-0.426355,-0.383264,-0.134887,-0.590818,-0.125269,-0.144178,-0.191700,-0.556174,0.335225,-0.072928,0.132541,0.420537,0.381426,0.418902,0.237637,0.349927,-0.126805,0.234012,0.153238,-0.495134,0.333232,0.261503,0.163522,-0.142675,-0.239564,0.304817,-0.138022,0.520391,0.576301,-0.463009,0.058479,0.081992,0.336623,-0.331161,0.403982,0.399669,0.298415,-0.248099,-0.317147,-0.077828,-0.419370,-0.155998,0.141653,-0.119771,-0.418608,0.220344,0.024220,0.170321,-0.533530,0.415937,-0.211076,0.214700,0.072335,-0.246701,-0.158082,-0.006108,-0.008887,0.194227,0.144341,-0.074499,-0.323864,-0.150292,0.651961,0.105987,-0.394847,0.213664,-0.416299,-0.526944,-0.211511,-0.285571,-0.529415,-0.126193,0.719359,0.014067,0.031383,0.365238,-0.537105,-0.248274,-0.565552,0.160821,-0.267504,-0.466507,-0.372445,-0.397497,-0.423641,-0.527491,-0.207081,-0.069486,-0.193198,-0.060649,0.900264,-0.663623,0.220002,0.810463,0.265242,-0.251669,0.394721,-0.077480,-0.195902,0.223726,-0.270424,0.795993,0.446953,0.104411,0.172440,0.536640,-0.107540,0.024473,-0.382972,0.655939', '3005387', '26348103', '1469111', '1298468');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296246', '天生爱情狂', '剧情', '精神科医生杰克（马龙·白兰度 Marlon Brando 饰）的家庭平静但缺少激情，随着年岁的增长，他感到曾经的梦想离自己越来越远。就在离退休还有10天时，他接手了一个有妄想症，企图自杀的青年。青年自称唐璜（约翰尼·德普 Johnny Depp 饰），带着面具，穿着不符合时代的长靴和披风，佩带长剑，他因被最爱的女人抛弃，而萌生了自杀的念头。唐璜虽然行为举止十分怪异，但却有着无法抵挡的个人魅力，他向杰克倾诉自己的过往，他的传奇经历深深吸引了杰克，同时也引发了他对自己婚姻生活的深刻的思考。就在杰克被唐璜吸引之时，唐璜的祖母和母亲相继出现，两人所言却大相径庭。他到底是谁？只是一个疯疯癫癫的浪荡子，还是真的是一个背负着沉重过去的大情圣？10天很快就要过去了，面对同事和法官，他又会做出怎样的选择呢？©豆瓣', '约翰尼·德普', '杰里米·莱文', 8.1, 17804, 'tt0112883', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1710894798.jpg', 0.2, 1.9, 21.5, 46.7, 29.6, '0.270184,-0.105440,-0.720585,0.535024,-0.315919,-0.313095,1.148862,0.040558,-0.446216,-0.247846,0.441464,0.810839,-0.075933,0.177341,0.205760,0.055584,-0.045945,-0.713931,0.073905,-0.075432,-0.301479,-0.422873,-0.323761,-0.163603,-0.197137,-0.308035,0.620266,-0.039708,-0.261907,0.259448,0.486495,0.393443,0.092098,0.830504,-0.349952,0.026562,-0.007735,-0.024164,-0.011295,0.076961,0.409007,-0.305209,-0.168382,0.468803,-0.530673,0.408726,0.617130,-0.226331,-0.330669,0.102887,0.430368,-0.163241,-0.104755,0.112107,0.073438,-0.060398,-0.053933,0.149025,-0.100819,-0.156715,0.007445,0.131808,-0.655340,0.206770,0.094234,0.302072,-0.721567,0.475264,-0.128391,-0.196046,0.234540,-0.397453,-0.018472,0.047564,0.247425,0.450076,-0.253110,-0.198756,-0.473270,0.175736,0.682026,0.311623,-0.437743,0.473424,-0.609688,-0.391630,-0.270804,-0.247113,-0.666283,-0.036886,0.257755,0.098494,-0.206297,0.198388,-0.357116,0.026060,-0.200173,-0.082967,-0.084781,-0.563956,-0.146989,-0.142970,-0.301794,-0.689580,-0.468498,-0.028644,0.132858,-0.315498,0.793736,-0.936514,0.095904,0.557638,0.248999,-0.557406,0.619990,0.105011,-0.167594,-0.117330,-0.077138,0.282773,-0.086158,0.103276,0.159973,0.458023,0.057258,-0.074056,-0.334456,0.673080', '4275444', '1292062', '1296370', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296252', '将军的女儿', '剧情', '“军队罪行调查部”的高级官员布伦纳（约翰·特拉沃夫塔 John Travolta 饰）和其助手森希尔（马德琳·斯托 Madeleine Stowe 饰）奉命36小时内调查清楚一起神秘的谋杀案，副总统的有力竞争者坎贝尔将军（詹姆斯·克伦威尔 James Cromwell 饰 ）的女儿伊丽莎白（莱斯利·斯蒂芬森 Leslie Stefanson 饰）在军事基地内被残忍杀害。随着调查深入，布伦纳发现曾就读于西点军校的伊丽莎白除了成绩优异、长相出众外在高中时还发生过一起不为人知的事情，与父亲的关系并不融洽，而坎贝尔将军也不像他所塑造的形象一样刚正不阿。在揭开事情真相的同时布伦纳也发现了许多军队中的秘密。最终，杀人凶手被惩治以法，事件得以平息。©豆瓣', '约翰·特拉沃尔塔', '西蒙·韦斯特', 7.3, 11485, 'tt0144214', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2359435252.jpg', 0.4, 2.6, 38.3, 47.5, 11.2, '0.298193,-0.089768,-0.584676,0.574046,0.024389,-0.142718,0.592712,-0.094097,-0.901863,-0.616992,0.056243,0.595188,-0.249578,0.016941,0.200369,0.153877,-0.494601,-0.875795,-0.030039,-0.305253,-0.177915,-0.894130,-0.312143,-0.455557,0.125991,-0.436393,0.452839,0.027347,-0.097540,0.405207,0.224423,0.341230,-0.250943,0.340658,0.113179,-0.127775,0.357624,-0.054843,-0.383219,-0.079375,0.123467,-0.223974,-0.072187,0.058276,0.179822,0.490731,0.290267,-0.386737,-0.184234,-0.075870,0.229658,-0.070745,0.107223,0.390000,0.501815,-0.098205,0.230001,0.662162,-0.228451,0.042065,0.070575,-0.182738,-0.419944,-0.109269,0.150628,0.442703,-0.419395,0.345125,-0.320876,-0.031178,0.201792,-0.092651,0.035737,0.339418,0.187499,0.189283,-0.023278,-0.012691,-0.456013,0.117453,0.567555,-0.006204,-0.163314,-0.052554,-0.251895,-0.463994,-0.148236,-0.477498,-0.166849,0.180933,0.089592,0.046432,0.156369,0.587419,-0.201800,-0.382068,-0.413249,0.012018,-0.234394,-0.210411,-0.006593,-0.599453,-0.203229,-0.293494,-0.282299,0.078706,-0.136841,-0.299269,0.373141,-0.742608,0.147476,0.402155,0.333389,-0.264720,0.431908,0.107584,0.134774,-0.351425,-0.330886,0.272031,0.341379,0.067496,0.104659,0.307501,0.141019,-0.714378,-0.303911,0.274416', '1301164', '24325856', '3263169', '1294756');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296253', '没完没了', '剧情', '韩冬（葛优 饰）是一个出租车司机，他生性老实，把车常年包给旅行社老板阮大伟（傅彪 饰）做生意。然而阮大伟却是个奸商，长期拖欠韩冬包租费。韩冬的姐姐发生了意外，变成了植物人躺在医院，需要大笔医疗费。无计可施的韩冬决定绑架阮大伟的女友小芸（吴倩莲 饰），威胁他还钱。小芸十分厌恶这个粗俗的歹徒，然而当她听阮大伟说，宁可韩冬撕票和不给钱的时候，她心里失望透顶。韩冬为了追回欠款，小芸为了报复阮大伟，两人共同商议上演了一出戏来捉弄阮大伟。阮大伟气急败坏，发誓不会放过韩冬。老实巴交的韩冬被吓怕了。不料小芸得知了韩冬大费周章只为救姐姐，打心里喜欢上了这个其貌不扬的老实人。©豆瓣', '葛优', '冯小刚', 7.7, 94263, 'tt0276329', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2104173609.jpg', 0.3, 1.7, 28.6, 50.5, 18.8, '0.452745,-0.189308,-0.440136,0.237163,-0.466256,-0.334406,0.513855,0.018554,-0.526413,-0.216638,0.099802,0.470937,-0.088778,0.455794,0.230877,0.173650,0.016783,-0.251291,0.057841,0.162315,-0.021934,-0.654324,0.335612,-0.281376,-0.039975,0.515107,-0.048917,-0.257181,-0.076233,0.713229,0.488937,0.212353,0.235939,0.596994,0.065075,0.419090,-0.102843,-0.334589,-0.039416,-0.079514,0.270942,-0.199413,0.061367,0.249129,0.261860,0.386117,0.336535,0.257710,-0.183538,0.059339,0.301858,-0.420358,0.247992,0.044239,-0.013569,-0.172872,0.262673,-0.042289,-0.409078,0.020275,0.344127,0.015829,-0.363851,0.361955,-0.007122,-0.204912,-0.619736,0.288318,-0.017348,0.360740,-0.109941,-0.209113,0.345697,0.118204,0.355871,0.241850,-0.107860,-0.003918,-0.694655,0.314423,0.378983,-0.134029,0.309737,0.489633,0.100242,-0.116008,0.213028,-0.142318,-0.582743,0.084424,0.292056,-0.295107,-0.460946,-0.394074,-0.297601,-0.121592,-0.171480,0.130737,-0.123372,-0.151322,-0.377957,0.094515,-0.262902,-0.464165,-0.311612,0.134182,-0.241045,-0.265190,0.384932,-0.457015,-0.319640,0.255463,0.269650,-0.772033,0.477731,0.152641,-0.165111,0.000927,0.273003,-0.101967,0.211878,0.310707,0.546747,0.051900,0.111549,-0.070472,0.338897,-0.036753', '1297710', '1302110', '10355329', '3998385');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296266', '本命年', '剧情', '经过劳动改造，犯人李慧泉（姜文 饰）刑满释放，他回到了从小生长的胡同。老街坊邻居罗大妈很照顾这个父母亡故、孤苦伶仃的小伙子。当年，哥们叉子因为女友爱上了别人，气愤不过，拉着讲义气的李慧泉，教训了那个男人，结果无意中弄出了人命，二人双双入狱。如今，叉子的家人对他们依旧抱有成见，只有叉子的弟弟觉得李慧泉是条汉子。 李慧泉在民警小刘（刘斌 饰）的帮助下，后来选择了练摊谋生，期间遇到了三教九流令他尝遍人间冷暖。在歌厅里，李慧泉认识了驻唱的歌手赵雅秋（程琳 饰），此后他成为她的护花使者，但是在他决定重新开始新生活的时候，却陷入了始料未及的困境……本片根据刘恒的小说《黑的雪》改编，获得1990年柏林电影节银熊奖。©豆瓣', '姜文', '谢飞', 8.3, 42750, 'tt0123450', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377282602.jpg', 0.2, 0.6, 13.8, 53.4, 32, '0.175112,-0.092763,-0.480842,0.287153,-0.186764,-0.438454,0.556520,0.250498,-0.712223,-0.089484,0.253285,0.442827,-0.162808,0.424427,0.244572,-0.115584,-0.409162,-0.581631,-0.046141,-0.105910,-0.320296,-0.206188,-0.006612,0.018390,-0.260026,-0.044572,0.268801,-0.012517,-0.083045,0.302777,0.297311,0.028829,0.034949,0.288519,-0.286373,0.296952,0.054328,0.046501,-0.192674,-0.030519,0.100068,-0.375283,-0.190211,-0.006318,0.210539,0.449774,0.710381,-0.183723,-0.197373,-0.094147,0.415345,-0.195333,-0.204798,-0.037092,0.187691,0.139319,0.275619,-0.143079,-0.158947,0.002761,0.045353,-0.259774,-0.226981,0.054272,-0.069921,0.060252,-0.699990,0.425630,-0.056602,0.072780,-0.107539,-0.479982,0.268780,0.195305,0.218267,0.388564,-0.087177,0.075858,-0.441097,0.318593,0.753814,-0.079752,-0.031613,0.200798,-0.224571,-0.481867,-0.001885,-0.137146,-0.335277,0.016565,0.477005,-0.114336,-0.416387,0.223084,-0.457654,-0.020652,0.022929,0.034853,0.176658,-0.292164,-0.268460,-0.226413,-0.050753,-0.356139,-0.255818,-0.041979,-0.106387,-0.313558,0.709904,-0.764926,0.147669,0.313524,0.178281,-0.430900,0.630378,0.069144,0.126549,-0.176044,0.000267,0.261340,0.140312,0.329094,0.376879,0.309073,-0.194362,-0.275262,-0.297438,0.296598', '35030151', '1299062', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296272', '跛豪', '剧情', '1962年，内地正值经济困难时期，随难民潮逃到香港的汕头青年吴国豪（吕良伟）因不甘被黑帮欺凌，投靠黑帮大佬肥波（郑则士），几场拼命的血战后，他被肥波重用，在黑帮中确立下地位，势力越来越大。渐感威胁的肥波设局令吴国豪被毒枭追杀，虽没使其毙命，却也让其残了一条腿，但他自己 终被对方设计陷害锒铛入狱。靠雷总华探长夺位，吴国豪接下肥波所有地盘，成为黑帮四大家族之首，又因他愿出钱替为其效劳的警界中人买探长做，警署成为他贩毒的保护伞。然而随着1973年（香港成立廉政公署）的临近，加上他因位高权重狂妄自大导致众叛亲离，其运势开始一路下滑。©豆瓣', '吕良伟', '潘文杰', 8.3, 73687, 'tt0101490', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2054520775.jpg', 0.2, 0.8, 14.8, 51.5, 32.8, '0.142674,0.137346,-0.740760,0.243186,0.200103,0.006586,0.266928,0.253318,-0.585444,-0.044311,0.184124,0.605186,-0.030700,-0.022790,0.011708,-0.366087,0.223875,-0.646351,-0.030959,-0.043292,0.018922,-0.091991,-0.339495,-0.002334,-0.431034,0.054362,0.621277,0.315803,-0.307340,0.333636,0.181847,0.306791,0.016188,0.384639,-0.101933,0.006939,0.151084,-0.272574,-0.216503,0.127493,-0.005827,-0.836286,-0.087907,0.248738,-0.126843,0.459781,0.432626,-0.035766,0.169005,-0.576962,0.291309,-0.468879,-0.323314,-0.151666,0.712375,0.066994,-0.078076,0.536129,-0.114890,-0.161920,0.068562,-0.026401,-0.854085,0.023695,0.167141,0.093793,-0.476743,0.385288,-0.192480,0.132676,-0.428723,-0.111610,0.079157,0.254260,0.104783,-0.063785,-0.040379,0.364726,-0.495736,0.101625,0.931301,-0.021320,-0.244721,-0.276698,0.132450,-0.196506,0.279957,-0.862520,-0.230080,-0.244486,0.441666,-0.256011,-0.049799,0.347060,-0.133925,-0.186108,-0.575706,-0.045691,-0.149546,0.054688,0.107318,-0.265319,-0.215104,-0.297825,0.041550,0.001559,0.275876,-0.290561,0.440829,-0.572561,-0.177793,0.552085,0.580216,-0.870645,0.299648,-0.065738,0.347237,0.061228,-0.309284,0.098590,0.357793,0.073771,0.392788,-0.139667,-0.357845,-0.391683,0.205554,0.050162', '1307106', '1877596', '26678784', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296282', '歌厅', '剧情', '20世纪30年代的德国柏林，纳粹势力正在兴起。美国女艺人Sally（丽莎·明奈利 Liza Minnelli 饰）是一家俱乐部的舞女，非常受欢迎。刚刚来到柏林的英国男教师Brian Roberts（麦克尔·约克 Michael York 饰）碰巧成了Sally的室友，他 以教英语来养活自己。Sally诱惑Brian没有成功，于是怀疑他是个男同性恋者。Sally和她的一个朋友Max（赫尔穆特·格里姆 Helmut Griem饰）发生了关系，后来她发现，Robert也和Max发生过关系。另一边，一个犹太人Fritz爱上了Robert学生Natalia，一个有钱的犹太小姐。为了和Natalia在一起，他从一个基督教徒转变成犹太教徒。Sally怀孕了，但她却不知道孩子是Robert还是Max的。纳粹在德国的势力越来越盛，Robert决定带Sally回英国.....本片被提名1973年奥斯卡十项大奖，最终赢得包括最佳导演、最佳女主角等八项。', '丽莎·明奈利', '鲍勃·福斯', 8.9, 12244, 'tt0068327', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1345340636.jpg', 0.4, 0.9, 8.5, 36.4, 53.9, '0.331846,-0.149957,-0.642414,0.437720,-0.220663,-0.285605,0.858570,-0.095104,-0.566576,-0.227501,0.130466,0.945765,-0.254749,0.078283,0.398826,0.083318,-0.273822,-0.660034,0.192725,-0.246297,0.018405,-0.572346,-0.176088,-0.055373,-0.432431,-0.239879,0.568730,-0.153992,0.034796,0.414479,0.585792,0.183610,0.331860,0.313064,-0.184697,0.128167,0.470537,-0.165576,-0.218883,0.524468,0.248003,-0.248909,-0.153620,0.129446,0.104268,0.306426,0.459374,0.127916,0.179420,0.022176,0.366843,-0.290540,-0.349014,0.221404,0.586874,-0.202412,0.216389,0.078319,0.006623,-0.106321,0.057925,-0.089716,-0.465156,0.239651,0.269336,0.244931,-0.480384,0.518860,-0.205254,-0.054614,-0.042035,-0.382763,0.286988,0.347266,0.195035,0.255367,-0.017245,0.174605,-0.674786,0.339039,0.902600,-0.107489,-0.201507,0.266008,-0.300723,-0.556592,0.020946,-0.304159,-0.482356,0.156375,0.266854,-0.285674,-0.166722,0.027997,-0.604574,-0.095520,-0.148983,-0.314814,0.222805,-0.262949,0.169103,-0.429327,-0.251240,-0.436480,-0.116580,0.099537,-0.062622,-0.240671,0.850502,-0.959264,0.083666,0.598178,0.559407,-0.547245,0.922955,0.131912,0.072939,-0.210667,-0.077472,0.133089,-0.033577,0.037376,-0.043309,0.458002,0.248103,-0.480056,0.0