INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296283', '慕德家一夜', '剧情', '电影为侯麦《六个道德故事》系列之一。故事讲述一个34岁的天主教徒让-路易斯（简-路易斯·特林提格南特 Jean-Louis Trintignant 饰）爱上了一个年轻的女大学生。他偶遇老朋友维塔尔（安东尼·维特兹 Antoine Vitez 饰），被邀请到一个性情豪放的离婚女人慕德（弗兰西丝·法比安 Françoise Fabian 饰）家中共进晚餐。饭桌上，持有不同道德思想的三人大谈宗教、无神论、爱情、道德、以及哲学家帕斯卡尔的生活与哲学著作等话题。聊到深夜，外面下起了大雪，维塔尔离去，慕德劝说让-路易斯留宿一夜。慕德是情场高手，她极尽挑逗之能事去引诱他。保守忠诚的天主教徒让-路易斯面对了两难之境，一方面心中已有所爱，另一方面美艳的慕德实在又难以抗拒。他半推半就，最终还是抵制住了美色的诱惑。后来，他与心爱的女孩结婚，却发现她竟然曾是慕德丈夫的情妇。本片获得第42届奥斯卡最佳外语片提名、最佳原创剧本提名。', '让-路易·特兰蒂尼昂', '埃里克·侯麦', 8.3, 13129, 'tt0064612', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2203325739.jpg', 0.3, 0.9, 13.6, 52.5, 32.6, '0.308860,0.021077,-0.658747,0.697839,-0.154451,-0.355073,0.658462,0.249052,-0.425346,-0.393827,0.097731,0.751355,-0.269872,0.322830,0.468356,-0.011497,-0.150216,-0.590416,0.131159,-0.014136,-0.008093,-0.514698,-0.134508,0.003366,-0.219603,-0.270713,0.462793,0.022540,-0.189585,0.211251,0.584110,0.323325,0.095318,0.233742,0.035987,0.013538,0.393997,-0.087182,-0.313996,0.328926,-0.190266,-0.090674,-0.307212,0.225165,-0.136995,0.344966,0.416538,-0.141417,0.116693,0.063997,0.516619,-0.216663,-0.094916,0.107072,0.228969,-0.207852,0.155761,0.378884,0.056397,0.076704,0.024420,-0.024038,-0.651359,0.083003,-0.045871,0.060467,-0.407017,0.335422,-0.228170,0.038975,-0.121187,-0.132777,-0.004016,0.170512,0.386061,0.320260,0.114227,0.077292,-0.336868,0.264465,0.515033,0.317907,-0.204313,0.186143,-0.423048,-0.337252,0.163404,-0.384154,-0.555475,-0.071135,0.214690,-0.041492,0.074042,0.235533,-0.443314,-0.184610,-0.298987,0.065276,0.212112,-0.380710,0.134283,-0.580699,-0.350683,-0.312873,-0.251134,-0.056593,0.162391,-0.285331,0.774511,-0.443027,0.178045,0.595825,0.362614,-0.485795,0.739876,0.459102,0.014905,-0.151431,0.081313,0.563612,-0.140158,-0.224208,-0.092831,0.287789,-0.002147,0.014194,-0.298776,0.390191', '30162520', '34890458', '4301278', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296284', '情定日落桥', '喜剧', '美国女孩罗伦（戴安•琳恩 饰）随母亲改嫁来到了法国生活。罗伦的性格比较内敛，也没有很多的朋友。于是当她移居法国她认识了当地男孩子丹尼尔，她的生活也产生了改变。因为，这两名年轻人相爱了。一位老绅士朱塞（劳伦斯·奥利弗 饰）给他们讲述了一个深情的传说：如果相爱的人日落时分在叹息桥上亲吻，他们的爱便会天长地久。在朱塞的帮助下两人前往威尼斯的叹息桥，罗伦的母亲以为自己的女儿被绑架了。警察一路追踪，这时才发现朱塞原来是名小偷，但这次他是真心实意想要帮助一对小情人。好事多磨，最后丹尼尔跟罗伦又能否实现期待多时的浪漫之吻呢？©豆瓣', '戴安·琳恩', '乔治·罗伊·希尔', 8.2, 8400, 'tt0079477', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1126290487.jpg', 0.2, 1.1, 17.4, 49.8, 31.4, '0.235866,-0.145607,-0.652606,0.601648,-0.296681,-0.440500,0.791634,0.082776,-0.270363,-0.145054,0.181996,0.910419,-0.021519,0.312282,0.354817,0.231088,-0.283561,-0.585450,0.202651,-0.251832,-0.307390,-0.326401,-0.244692,-0.082109,-0.177010,-0.102220,0.411543,0.168058,-0.157214,0.438366,0.376204,0.192724,-0.021901,0.366574,-0.452005,0.206130,0.263844,0.207310,-0.212248,0.062620,-0.176765,-0.120410,0.035468,0.137763,-0.156763,0.300031,0.591196,-0.147931,-0.097879,-0.003859,0.001708,-0.202443,0.114920,0.138619,0.108531,-0.113448,0.105409,0.155317,-0.240733,-0.327210,-0.083211,0.026406,-0.487323,0.243881,-0.069436,-0.016754,-0.541794,0.354322,-0.019348,-0.142863,-0.047371,-0.384961,0.272933,0.524083,0.123672,0.256735,0.048157,0.013215,-0.372208,0.269978,0.814240,0.122037,-0.092410,0.501495,-0.417222,-0.482941,0.090835,-0.109858,-0.597570,0.162674,0.334748,0.022108,-0.343557,0.000402,-0.423607,0.030563,-0.175762,0.208086,0.069519,-0.550143,-0.015590,-0.583508,-0.143771,-0.476758,-0.356445,-0.041698,-0.102154,-0.247828,0.787597,-0.762010,0.118960,0.665107,0.354624,-0.621551,0.803829,0.283984,-0.246753,-0.263259,0.245200,0.395488,-0.083322,-0.060380,0.188808,0.354688,-0.039858,0.074660,-0.373156,0.357441', '30162520', '1292720', '3055049', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296299', '情挑六月花', '剧情', '二十七岁的马克斯（詹姆斯·斯派德 James Spader 饰）是一位事业有成的广告人，不久前，他的妻子不幸去世，至今，马克斯都未能走出丧妻的悲痛阴影中，个性也因此而变得封闭和阴沉。某日，他来到了一间小酒吧喝酒解闷，在这里，马克斯遇见了名为诺拉（苏珊·萨兰登 Susan Sarandon 饰）的四十三岁女招待。命运让这两个身份地位和年龄都悬殊巨大的人相互吸引，诺拉让马克斯暂时淡忘了痛苦，马克斯亦教会了诺拉什么是尊重，随着时间的推移，他们坠入了爱河。然而，这段世人眼中并不匹配的恋情注定要遭到诸多的考验，最终，他们的真爱能否战胜世俗的非议和彼此之间巨大的鸿沟呢？©豆瓣', '苏珊·萨兰登', '路易斯·曼多基', 7.4, 6562, 'tt0103251', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1739881776.jpg', 0.8, 3.8, 35.6, 42.8, 17, '0.358913,0.228309,-0.717592,0.468272,-0.142579,-0.328908,0.856567,0.263589,-0.471452,-0.308769,0.132401,0.878302,-0.267836,0.371898,0.196579,-0.069757,-0.209841,-0.702364,-0.046661,-0.408459,-0.404851,-0.494225,-0.478612,-0.147198,-0.109682,-0.311597,0.574441,0.204996,-0.202135,0.548937,0.387579,0.202590,-0.096059,0.526817,-0.187215,0.153248,0.249625,0.065420,-0.196348,-0.165976,-0.040082,-0.229220,0.005993,0.202628,-0.057383,0.421204,0.474029,-0.304802,-0.210793,0.066961,0.217731,-0.480152,-0.098257,0.308972,0.187027,-0.258696,0.086625,0.462860,-0.163457,0.005394,-0.260075,0.018947,-0.810941,0.207076,0.044344,0.192428,-0.513397,0.635934,0.141828,-0.413650,-0.039835,-0.062513,0.078494,0.387570,0.110764,0.506393,-0.212974,0.000802,-0.426924,-0.019125,0.764692,0.086628,-0.499725,0.260303,-0.455408,-0.434307,-0.243195,-0.277716,-0.646334,-0.115314,0.350473,0.355349,-0.044760,0.578022,-0.501485,0.141252,-0.288510,0.075295,-0.152179,-0.586259,-0.016141,-0.562413,-0.437308,-0.688763,-0.289277,0.067520,0.096839,-0.298500,0.794132,-0.536115,0.294641,0.293546,0.416358,-0.458772,0.881999,0.337017,0.320942,-0.174667,-0.071977,0.311458,-0.086309,0.041953,-0.017785,0.213912,0.088178,0.037158,-0.476223,0.463277', '30162520', '1456503', '25721544', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296332', '阴风阵阵', '恐怖', '在一场瓢泼大雨之中，孱弱的女子苏西（杰西卡·哈珀 Jessica Harper 饰）孤身一人来到德国，前往那里的芭蕾舞学校学习舞蹈。刚刚抵达的苏西看到一位女子从学校的大门里狂奔而出，口中念念有词，随后消失在了雨幕之中，让苏西没有想到的是，第二天，她便听闻了这位女子的死讯。很快，苏西便发现这所学校里的同学并不如她想象的那样友善，她的室友更是一个唯利是图的女人，而苏西结交到的唯一一个朋友，竟然同先前死去的女生是好友。在她的口中，苏西听说了学校里女巫作祟诅咒横行的传言，而接连出现的诡异现象亦让苏西慢慢察觉到，在这所阴森的学校中，隐藏着不可告人的秘密。©豆瓣', '杰西卡·哈珀', '达里奥·阿基多', 7.5, 19144, 'tt0076786', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2220607722.jpg', 1, 4.8, 29.7, 45.2, 19.2, '0.677300,-0.025646,-0.786173,0.730818,-0.152920,-0.195464,1.084960,-0.024501,-0.664698,-0.376607,0.332807,0.761098,-0.280299,0.451334,0.454880,0.051582,-0.146935,-0.678468,-0.360598,-0.610131,-0.274721,-0.331400,-0.440586,-0.106941,-0.047729,-0.382274,0.459406,0.184156,-0.275338,0.697037,0.155464,0.020142,-0.390311,0.562673,-0.207834,-0.093806,0.152792,0.372620,0.099032,0.330203,0.200771,-0.395446,-0.186264,0.126650,-0.179217,0.386164,0.599465,-0.242740,-0.034024,0.012290,0.323204,-0.153278,-0.168793,0.109617,0.397565,-0.053444,0.350549,0.031060,-0.181579,0.056506,-0.089686,-0.110515,-0.415877,0.118566,0.011369,0.359345,-0.398834,0.479048,0.104316,-0.269450,0.232410,-0.373781,0.248494,0.002603,0.035733,0.485028,-0.303453,0.008951,-0.476350,0.110930,0.467332,-0.046926,-0.343764,0.251575,-0.105150,-0.400599,0.192057,0.287858,-0.470638,-0.049290,0.160834,0.101326,-0.343244,0.246280,-0.504470,-0.000985,-0.235812,-0.018385,-0.100565,-0.183284,-0.474307,-0.694168,-0.074868,-0.118641,-0.143383,0.024143,-0.175982,-0.123952,0.632951,-1.174302,0.297705,0.363845,0.248792,-0.187545,0.570918,-0.247512,0.276806,0.045136,-0.262804,0.307925,0.209457,0.286245,-0.157724,0.572707,-0.220000,-0.231499,-0.465954,0.463993', '1296534', '1308755', '1309080', '30225296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296334', '滚滚红尘', '爱情', '本片根据三毛最后一部同名作品改编。日伪时期，女作家沈韶华（林青霞 饰）在报纸上连载她的自传体小说《白玉兰》，很多情节感同身受。某日，她接到了一位神秘的读者来信。她对这个名叫章能才（秦汉 饰）的男人充满了好奇。终于，两人见面，一见钟情。然而，因为章是汉奸，常有外人滋事，令韶华很是不安。此时，她的闺中密友月 凤（张曼玉 饰）因与男友（严浩 饰）赌气，来找她倾诉。韶华一边规劝，一边把爱人介绍给她。三人一起出游，感情很好。然而，见到日本军人凌辱中国人，月凤顿觉章面目可憎。三人闹得不欢而散。此后，时局动荡，日本投降，国共开战，韶华的情感经历了更加复杂的波澜……©豆瓣', '林青霞', '严浩', 8.1, 47117, 'tt0099719', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1281789791.jpg', 0.3, 1.7, 18.7, 49.4, 29.8, '0.428694,-0.153463,-0.463983,0.531200,0.462751,-0.253212,0.578554,-0.000414,-0.666745,-0.178918,0.081784,0.548854,-0.401883,0.370476,0.149011,0.009494,-0.440326,-0.685745,0.044026,-0.095251,0.207335,-0.200302,0.012367,0.001416,-0.207827,0.118310,0.543982,-0.049414,-0.164187,0.571296,0.373131,0.326723,-0.076502,0.637882,-0.166741,0.121479,-0.208986,-0.075070,-0.359681,0.057789,0.210014,-0.254941,-0.206623,0.188929,-0.214682,0.242714,0.622257,-0.220752,-0.256199,0.121368,0.745325,-0.074656,-0.054009,-0.004492,0.263090,0.174402,0.244644,-0.009207,-0.220775,-0.085953,-0.038182,0.053902,-0.231003,0.277952,0.230519,0.381915,-0.356492,0.399846,-0.128441,0.241467,0.158268,-0.052668,0.218054,0.270479,0.371416,0.102724,-0.123770,-0.027058,-0.206406,0.558130,0.425832,0.217558,0.116698,0.314087,-0.062748,-0.187394,0.125249,-0.104466,-0.523012,0.113020,0.043335,-0.114954,0.040375,0.203419,-0.636734,-0.094284,-0.077123,0.124378,0.086956,-0.421433,-0.046760,-0.585129,-0.434450,-0.392691,-0.266566,-0.073160,0.327277,-0.322840,0.658865,-0.550554,0.009846,0.259175,0.145305,-0.565217,0.576390,0.303274,-0.200211,-0.129675,-0.034793,0.525476,-0.288889,-0.172344,-0.038296,0.298041,0.091954,-0.016559,-0.130508,0.289024', '1418179', '3811356', '1296992', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296339', '爱在黎明破晓前', '剧情', '美国青年杰西（伊桑·霍克 Ethan Hawke 饰）在火车上偶遇了法国女学生塞琳娜（朱莉·德尔佩 Julie Delpy 饰），两人在火车上交谈甚欢。当火车到达维也纳时，杰西盛情邀请塞琳娜一起在维也纳游览一番，即使杰西翌日便要坐飞机离开。与杰西一见钟情的塞琳娜接受了杰西的邀请。他们一边游览城市，一边谈论着彼此的过去 ，彼此对生活的感想，两人了解越加深刻。他们非常珍惜这美妙的晚上，这对恋人一起经历了很多浪漫的经历因为他们约定在半年后再见，而此次约会将会在日出之间结束……©豆瓣', '伊桑·霍克', '理查德·林克莱特', 8.8, 621733, 'tt0112471', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2555762374.jpg', 0.3, 1, 9.7, 34.8, 54.2, '0.681804,0.081081,-0.634230,0.373138,0.438761,-0.439470,0.481793,0.082823,-0.407357,-0.042467,0.322655,0.743437,-0.547523,0.219081,0.749899,-0.012188,-0.969988,-0.662978,0.427466,-0.393772,-0.248060,-0.532204,-0.114088,0.134876,-0.052186,-0.194663,-0.011618,-0.250881,0.147864,1.055426,0.187463,-0.184658,-0.333965,0.435571,-0.198563,0.019186,0.485782,0.413827,-0.970397,0.252653,0.110411,0.193884,-0.188750,-0.296251,0.285057,-0.044354,0.641702,-0.084852,-0.126359,0.010565,0.195108,-0.185430,0.150480,0.206412,0.183517,0.041458,0.465079,0.141426,-0.107268,-0.003331,0.156529,0.161629,-0.042491,0.303005,-0.021911,0.177014,-0.338349,0.670941,0.044965,-0.094903,0.288161,-0.546283,0.058552,0.784292,0.102482,0.120745,0.242830,-0.365625,-0.312962,0.159207,1.105366,0.087170,0.175154,0.154409,-0.164786,-0.251166,0.094941,0.211868,-0.534969,-0.116591,0.240544,0.142441,-0.161056,0.270846,-0.604801,0.024758,-0.304563,-0.239268,0.344416,-0.482452,0.067021,-1.386474,-0.193462,-0.835202,-0.358878,-0.066796,0.039381,-0.093598,0.554484,-0.749613,0.338943,0.494375,0.560165,0.006965,0.757225,0.372264,0.085566,-0.462084,0.037018,0.354259,-0.114213,0.132822,0.109292,0.544902,-0.042291,0.305096,-0.654019,0.422153', '3036464', '2075345', '35287558', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296359', '我恨你的十件事', '喜剧', '比安卡（Larisa Oleynik饰）是全校公认的甜心宝贝，可事实上，她甚至未有过一次约会——比安卡的老爸对女儿的管教极尽苛刻，男生们只能对她望而却步。在女儿的不断抗议下，老爸终于做了“让步”，他声明，比安卡可以约会，只要她的姐姐凯特（Julia Stiles饰）也去。听到这个消息，暗恋比安卡的喀麦隆（Joseph Gordon-Levitt饰）决心无论如何都要找到能和凯特约会的人。千挑万选之下，他找到派特里克（Heath Ledger饰）帮忙。凯特可是人人眼中的怪物啊，仿佛愤世嫉俗般，对任何人和事都有一股不满的情绪。要让约会顺利进行，这是前所未有的挑战，还是一个不可能的任务？©豆瓣', '朱丽娅·斯蒂尔斯', '吉尔·约格尔', 7.9, 48936, 'tt0147800', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2464154962.jpg', 0.3, 2.2, 25.9, 46.3, 25.3, '0.044469,-0.221726,-0.718668,0.819738,-0.205788,-0.235776,0.485750,-0.052311,-0.500479,-0.056520,0.023813,0.586583,-0.240052,0.272761,0.010473,0.164346,-0.215303,-0.764167,0.091537,-0.244978,-0.218756,-0.409456,-0.147763,-0.247600,-0.008251,-0.060997,0.296229,-0.091109,-0.186631,0.272770,0.613127,0.195591,0.473326,0.745069,-0.244258,-0.262780,0.125174,0.113185,-0.091851,0.198932,0.242193,0.049768,-0.259300,0.380000,0.356024,0.431132,0.224575,-0.249778,-0.139125,0.160695,0.155215,-0.094730,0.281853,0.404129,-0.073512,-0.291696,0.441577,0.439059,-0.054600,0.071142,0.233073,0.031218,-0.821433,0.003767,0.255667,0.097965,-0.685606,0.204947,-0.138706,0.007338,0.171035,-0.356586,0.156257,0.043541,0.110190,0.455865,-0.302978,0.028087,-0.510750,0.047295,0.682725,0.038070,-0.069617,0.192742,-0.251203,-0.404576,0.008876,-0.206441,-0.673261,0.244879,-0.059949,0.077280,-0.163117,0.136555,-0.362658,-0.280696,-0.078640,-0.245429,-0.119016,-0.663349,0.176562,-0.415953,-0.050515,-0.359111,-0.501523,0.327765,0.176180,-0.235255,0.740605,-0.776235,0.023191,0.561667,0.320869,-0.711189,0.782011,0.502808,-0.125150,-0.281357,-0.149678,-0.019116,-0.067343,0.124051,0.097275,0.363592,0.554796,-0.312230,-0.208462,0.475975', '1877596', '4301278', '30163500', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296370', '爱情万岁', '剧情', '骨灰盒推销员小康（李康生）结束心力交瘁的一日后，悄悄潜入一幢公寓里的一间房，没想这间房里，还会潜入一个会是其欲望（投射）对象的地摊小贩（陈昭荣）。房子的暂时主人是一个售楼小姐（杨贵媚），她和小康性向虽然有异，却同样是没有爱情（情感）温暖心灵的人。小康和地摊小贩一开始时时提防（售楼小姐和彼此），待他们认识了解到各自的生活后，提防心理消除，却也没有自此成为朋友（懦弱的小康也鼓不起勇气示爱）。售楼小姐和地摊小贩发生过几次性关系，清楚地明白彼此都是为了满足身体的长久饥渴，爱情（感情）并没有什么万岁之处，身体上的快感可以暂时满足，精神上的安慰却无法获得（即使有，也是短暂如烟花）。©豆瓣', '杨贵媚', '蔡明亮', 7.9, 32445, 'tt0109066', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2040684308.jpg', 0.7, 2.4, 22, 48.9, 26, '0.458526,0.068867,-0.780719,0.419153,-0.219014,-0.095779,1.153096,0.052645,-0.570624,-0.061764,0.168913,0.716893,-0.280006,0.270897,-0.137463,0.184692,-0.141975,-0.628033,-0.050238,-0.084116,-0.201850,-0.486286,-0.420663,-0.155236,-0.411049,-0.194768,0.491483,0.252445,-0.149077,0.401585,0.006329,0.008241,0.083968,0.775325,-0.040657,0.017725,-0.117549,0.191598,-0.527827,-0.040701,0.025338,-0.307881,-0.223399,0.318879,0.140882,0.437579,0.571014,-0.135830,-0.332652,0.188184,0.218009,0.158772,0.010816,0.267362,0.184893,-0.048358,0.424890,0.192030,-0.138151,0.000463,0.026149,0.152984,-0.792675,-0.228420,0.219413,0.206952,-0.522025,0.403676,-0.053668,-0.159065,-0.065345,-0.422205,0.221449,0.065034,0.202381,0.449561,-0.315783,0.011626,-0.543922,-0.010068,0.913704,0.154142,-0.146833,0.568954,-0.585616,-0.552999,0.013739,0.022249,-0.617606,-0.193265,0.101322,0.415531,-0.345626,-0.168956,-0.408896,0.207468,-0.140791,-0.191103,0.106058,-0.570303,0.204101,-0.379641,-0.304320,-0.611099,-0.381922,0.035748,0.203191,-0.247444,0.614057,-1.091017,0.201783,0.546552,0.565900,-0.487404,0.875221,0.172934,-0.031850,0.044069,0.130132,0.016727,-0.368660,0.261396,0.045124,0.406795,0.151088,0.065658,-0.337229,0.458809', '1308755', '4275444', '3059036', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296384', '心理游戏', '剧情', '亿万富翁范先生（迈克尔·道格拉斯）在四十八岁生日时收到弟弟（西恩·潘）的一份礼物，CRS俱乐部的游戏卡。游戏的内容为迈克尔量身定做，直指他内心深处的童年阴影和婚姻创伤。迈克尔由于好奇，渐渐投入到游戏中去，并由此结识了女侍应生克莉丝汀（黛博拉·卡拉·安格）。可是在种种恶作剧后，迈 克尔发现这一系列离奇事件并不是简单的游戏，他的生活甚至生命正被拖向深渊。当生命不断受到威胁，迈克尔一次次的告诉自己，这只是个游戏。然而游戏的策划者正把他引向何方？父亲48岁生日时坠楼自杀的场景不断在他头脑里闪现……©豆瓣', '迈克尔·道格拉斯', '大卫·芬奇', 7.7, 100654, 'tt0119174', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2371537316.jpg', 1, 3.9, 27.4, 45.8, 21.9, '0.184648,0.280062,-0.606210,0.483556,-0.096233,-0.177061,0.855442,-0.038754,-0.495240,-0.336975,0.301921,0.869618,-0.325872,0.224937,0.303670,0.014984,-0.313049,-0.611680,-0.080957,0.017403,-0.286842,-0.580361,0.008703,-0.136037,0.094042,-0.346415,0.413238,-0.055992,-0.292052,0.398504,0.285291,0.517307,-0.187424,0.553422,0.124169,0.237843,0.277757,0.017339,-0.214955,0.129597,0.270024,-0.290699,-0.112595,0.296531,0.030692,0.364989,0.679202,-0.360830,-0.203945,0.043726,0.668793,-0.262525,-0.060196,0.120893,0.022725,0.088693,0.110319,0.059077,-0.032656,0.093479,-0.016948,-0.337527,-0.886172,-0.086605,-0.217111,0.205169,-0.339040,0.183161,-0.228354,0.123369,0.268628,-0.132801,0.046864,0.367971,0.384302,0.257054,-0.491625,0.085986,-0.366894,0.156456,0.481270,-0.035025,-0.111175,0.693773,-0.296451,-0.469094,-0.201946,0.137297,-0.528892,0.001492,0.439764,0.110203,-0.360119,0.477212,-0.461510,-0.158060,-0.233735,-0.446157,0.198693,-0.254788,-0.411423,-0.496147,-0.220598,-0.232403,-0.325096,-0.112540,-0.053320,-0.460693,0.330322,-0.754976,0.418639,0.822851,-0.093386,-0.158678,0.694571,-0.042717,-0.075766,-0.184743,-0.155208,0.471477,0.197570,0.182612,0.046479,0.237675,0.113912,-0.094851,-0.468830,0.789086', '1309172', '25763555', '34890458', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296390', '王子复仇记', '剧情', '丹麦王子哈姆雷特（劳伦斯·奥利弗 Laurence Olivier 饰）的父王某日在花园中离奇死亡，国王的弟弟克劳迪亚斯登上了王位，并娶原王妃即哈姆雷特的母亲为妻。父亲的突然离世，加上母亲的改嫁，使哈姆雷特终日郁郁寡欢。一天哈姆雷特的好友霍拉旭告诉他，每到子夜时分，城堡高台上会出现一个悲愤抑郁的鬼魂。哈姆雷特便在半夜里来到高台上，与父亲的幽魂相会，他从鬼魂口中得知父王为现任国王克劳迪亚斯所杀。鬼魂要求哈姆雷特向那个篡夺王位、霸占王妃的凶手复仇。背负了复仇任务的哈姆雷特决定用假装发疯的办法来掩饰自己，以窥探克劳迪亚斯的一举一动。然而优柔寡断的他迟迟没有动手杀死叔父，正当他犹豫不决时，一个戏班来到了宫廷。他就安排了一场戏，将国王被害一幕以戏剧形式表演出来。国王和王后的反应，让他证实了这场宫廷阴谋……©豆瓣', '劳伦斯·奥利弗', '劳伦斯·奥利弗', 8.3, 11260, 'tt0040416', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1217889861.jpg', 0.3, 1.1, 16.5, 47.3, 34.7, '0.070348,0.153520,-0.644067,0.559127,-0.093104,-0.419452,0.848631,0.139194,-0.499751,-0.323844,0.549158,0.850310,-0.173825,0.140459,0.419920,0.164325,-0.311750,-0.450819,-0.144681,-0.089206,-0.017347,-0.522395,-0.081749,-0.476459,-0.011573,-0.438187,0.586279,-0.149410,0.047902,0.367719,0.367817,0.151417,-0.086002,0.492162,0.177603,-0.024577,0.109956,-0.166563,-0.184041,0.403184,0.088875,-0.216274,-0.341364,0.258844,-0.165650,0.352903,0.463034,-0.553120,0.039350,-0.229079,0.535851,-0.397504,0.093294,0.417348,0.151400,-0.170727,-0.056166,0.384390,-0.127343,-0.222732,-0.131869,0.147709,-0.492617,0.143176,-0.066768,0.114931,-0.576305,0.366193,-0.347825,0.035558,0.287136,-0.409287,0.353712,0.316597,0.099566,0.399024,-0.300859,-0.124969,-0.552920,0.175603,0.522170,0.016414,-0.096306,-0.004611,0.246530,-0.343411,0.091673,-0.211617,-0.488546,-0.021597,0.495050,-0.065784,-0.101247,0.362458,-0.150588,-0.511250,-0.598487,-0.057913,0.174188,-0.362760,-0.122383,-0.343101,-0.044084,0.281303,-0.067238,-0.116648,0.143749,-0.357415,0.439338,-0.525567,0.596984,0.561255,0.264830,-0.543708,0.475604,0.237888,0.110751,-0.185432,-0.148698,0.362800,0.073800,0.210273,-0.077388,-0.003588,0.070491,-0.103207,-0.459950,0.404460', '1292217', '1301717', '34890458', '1