INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296436', '有话好好说', '剧情', '失恋的青年赵小帅（姜文饰）是名个体书商，他与女友安红(瞿颖饰)分手后又想和好，死缠烂打不放。不过，安红正与某娱乐公司的老板刘德龙（刘信义饰）恋爱，视对方为情敌的两人终于大打出手。混乱之中，小帅抢过行人张秋生（李保田饰）的背包，当武器抡打，砸电线杆上将包内电脑摔坏。最终小帅仍被打伤，他发誓要报仇，将刘德龙一只手跺掉。张秋生为索赔电脑奔波于小帅与刘德龙之间，协商着息事宁人，索还电脑。而赵小帅依然为报复刘德龙寻找机会，张秋生拼命阻止，最终小帅的复仇计划离奇落空……©豆瓣', '姜文', '张艺谋', 8.4, 208090, 'tt0120543', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553967182.jpg', 0.2, 0.9, 13.5, 48.6, 36.8, '0.212344,0.116501,-0.081041,0.313328,0.059953,-0.474205,0.597739,0.120129,0.091959,-0.135519,0.014426,0.361650,-0.170006,0.261741,0.080062,-0.201219,-0.150573,-0.845054,-0.077113,0.366946,-0.277419,-0.516675,-0.079624,-0.180841,-0.349887,0.425761,0.588145,-0.340064,-0.288233,0.389138,0.510853,0.068631,-0.158435,0.524582,-0.154326,0.027145,-0.306636,0.048784,-0.335231,-0.082392,0.148681,-0.370602,-0.003502,0.167677,-0.015697,0.395668,0.532577,0.116735,0.090320,-0.357145,0.197227,-0.257685,-0.165029,0.092167,0.222719,0.150284,0.124688,-0.035687,-0.050172,-0.014389,0.533711,-0.136246,-0.522538,-0.041876,0.000519,-0.183155,-0.548112,0.265241,-0.351358,0.319604,0.100920,-0.036173,0.091043,0.374090,0.580606,-0.022565,-0.255350,0.122935,-0.322251,0.173927,0.287167,-0.093984,0.279951,0.098125,0.150972,-0.206462,0.125959,-0.054202,-0.484533,-0.297714,0.346099,0.000707,-0.141831,0.002827,-0.602439,-0.255682,-0.340717,0.021780,-0.017768,-0.358551,-0.140183,-0.122485,-0.154642,-0.216370,-0.225630,0.107377,0.126287,-0.181773,0.311213,-0.472344,-0.164064,0.279471,0.310537,-0.400196,0.516417,0.227390,-0.089626,-0.130734,-0.053171,-0.107731,0.212454,0.255243,0.230503,0.093241,0.162996,-0.167815,-0.224877,0.250262', '30345227', '25777330', '25977027', '25911595');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296454', '阿呆与阿瓜', '喜剧', '罗伊·克里斯玛特（金·凯瑞饰）与好友哈里·邓恩（杰夫·丹尼尔斯）是一对蠢哥们。二人不仅智商不高，还找不到工作。一次，罗伊得到一个临时工作，驱车送摩登女郎玛丽·斯旺森（劳恩·霍利饰）去飞机场。罗伊对玛丽一见钟情，怎奈二人身份悬殊。玛丽登上飞机，罗伊发现玛丽遗忘了一个皮箱在飞机场候机厅。于是，为了追求真爱，罗伊决定和哈里一起驾车，向玛丽提到的飞机目的地驶去，他不仅要将皮箱归还，更要追求玛丽。可是皮箱似乎没有这么简单，一伙匪徒盯上了皮箱，试图将罗伊等人置于死地，怎奈罗伊智商不同寻常，阴差阳错地躲过灾难。两个蠢蛋，能否达到他们的目的地。一段傻傻的开心之旅就此展开。©豆瓣', '金·凯瑞', '彼得·法雷里', 7.4, 42638, 'tt0109686', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1690015840.jpg', 0.8, 4.8, 35.6, 41.7, 17, '0.401930,0.072576,-0.541255,0.398343,-0.317581,-0.672038,0.573438,0.179452,-0.102240,-0.247453,0.202676,0.453677,-0.109401,-0.199165,0.412990,0.172372,-0.437572,-0.374138,0.246396,-0.167182,-0.317532,-0.731895,-0.196999,-0.306587,0.013512,-0.084816,0.262381,-0.136948,0.064017,0.542633,0.437696,0.137323,-0.189075,0.413506,-0.194786,0.168752,0.400494,-0.065594,-0.340244,0.371574,0.043624,0.235272,-0.081032,0.188808,0.071945,-0.055404,0.646808,0.058288,-0.141599,-0.122013,-0.001671,-0.184931,-0.045383,0.061770,0.347738,-0.217450,0.025287,0.006373,0.006901,0.072458,0.331923,-0.015504,-0.313297,0.254752,-0.302682,-0.089098,-0.535316,-0.017147,-0.398581,-0.089942,0.250740,-0.457610,-0.382756,0.341064,0.374346,0.222940,0.055541,0.038216,-0.545078,-0.205643,0.623276,0.056687,0.075323,0.430747,0.149366,-0.213843,0.097534,0.216916,-0.485448,0.006842,0.648920,-0.068094,-0.052889,-0.039617,-0.423822,-0.105890,-0.693934,-0.128233,0.229027,-0.482511,0.148441,-0.587863,0.125727,-0.042032,-0.097901,-0.191012,-0.207159,-0.117471,0.366070,-0.387563,0.199161,0.716720,0.193251,-0.398953,0.468421,0.193990,-0.002105,-0.338438,0.004547,0.069675,0.175796,0.210874,0.075124,0.204903,0.188194,-0.097211,-0.375969,0.296351', '1301345', '1295684', '1410557', '1819460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296459', '星际传奇', '动作', '在浩瀚的宇宙间，一艘名为猎人号的商用飞船正进行着漫长的旅程。船上搭载着40位乘客，其中包括重刑罪犯理查·雷迪克（Vin Diesel 饰）。当行驶到丹吉尔星系时，突如其来的事故令飞船遭受重创，空气飞速泄漏，最终迫降到一颗炎热而荒凉的星球上。着陆时的巨大冲击力几乎让飞船支离破碎，死伤者众多。幸存者们来到这片陌生的国土，严酷的自然环境考验着每一个人，不同民族不同职业的他们此时必须捐弃前嫌，联合起来。他们不仅要与天空中三个太阳作抗争，还要时刻提防隐藏在黑暗中的危险……本片荣获2001年澳大利亚摄影师协会年度最佳摄影师和金三角架奖。©豆瓣', '范·迪塞尔', '大卫·杜西', 7.2, 29954, 'tt0134847', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1104457435.jpg', 0.9, 5.3, 39.8, 41, 13.1, '-0.053731,0.249123,-1.004978,0.827732,0.458427,0.220074,0.963249,0.061896,-0.327874,0.070532,0.428152,0.528837,-0.012561,0.189046,0.471634,-0.003251,-0.510924,-0.358496,-0.519162,0.007167,-0.814104,-0.487161,-0.363657,-0.064366,-0.130021,-0.442513,0.718520,0.456090,-0.239264,0.179547,-0.025860,0.152033,-0.376500,0.487945,-0.309229,-0.420061,0.163987,-0.198517,-0.314955,0.100514,-0.579926,-0.218690,-0.192884,0.034733,-0.026898,0.251424,0.852209,-0.360505,0.026838,-0.186753,0.271275,-0.312832,0.033275,-0.208182,0.506561,0.099672,0.020368,-0.110896,0.092015,0.164164,0.208423,-0.151907,-0.726444,0.030497,0.067864,0.080497,-0.432244,0.402916,0.055100,-0.011704,-0.046454,-0.090650,0.206100,0.101960,-0.015470,0.339388,-0.399544,0.176718,-0.398217,0.055196,0.754322,0.055051,-0.770539,-0.077623,-0.252279,-0.516882,-0.322288,-0.282819,-0.524356,-0.284927,0.619300,0.148031,0.039668,0.399793,-0.849490,0.400797,-0.116975,-0.639142,-0.218154,-0.178502,-0.324841,-0.883945,0.297295,-0.281250,-0.231897,0.572572,0.054898,0.051321,0.800740,-0.322389,0.345584,0.700379,0.007914,-0.130080,0.514243,-0.049743,0.232148,-0.203916,-0.253578,0.074053,0.023590,0.513004,0.010040,0.291895,-0.314790,0.301246,-0.275044,0.351098', '1473795', '2159244', '3011051', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296500', '雏菊', '剧情', '影片开始于两个都叫玛丽的少女（Jitka Cerhová 和 Ivana Karbanová 饰）的对话：没有人理解我们，这个世界上的一切正在变得越来越糟糕。于是两人决定：我们也要变得越来越坏！玛丽一号喜欢和老男人约会，在他们吃饭的时候，玛丽二号会突然出现，旁若无人地大吃特吃。玛丽一号把老男人送上火车，老男人以为她会陪着他，火车开动，她却下了火车。玛丽二号在一个收藏蝴蝶标本的男青年家中，用他的标本遮住自己身体的隐秘部位。她们在夜总会里捣乱，最后被赶走。她们无意中闯入一个没有人的宴会，开始肆无忌惮地享受美食.....本片献给精神生活一团糟的人们。©豆瓣', '伊特卡·采尔霍娃', '维拉·希蒂洛娃', 8.4, 8667, 'tt0060959', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2392561926.jpg', 0.8, 2.3, 13.9, 39.9, 43.1, '0.446613,0.022579,-0.928355,0.455418,-0.279036,-0.265673,1.079285,0.232860,-0.262022,0.071176,0.354286,0.753064,-0.446804,0.358253,0.390915,0.242582,-0.555264,-0.654443,0.059154,0.078145,-0.273068,-0.194733,-0.192522,-0.496864,-0.135153,-0.128596,0.258415,-0.076198,-0.175415,0.209446,0.251714,-0.197564,0.144588,0.698208,-0.370668,-0.029514,0.212152,-0.199766,0.102101,0.141804,0.014143,-0.248944,-0.078852,0.240667,0.089316,0.086289,0.722469,-0.405987,-0.272019,-0.085418,0.135829,-0.187877,-0.230457,0.158806,0.268438,-0.152550,0.316849,-0.051418,-0.222107,-0.072893,0.023518,-0.065639,-0.352209,0.274673,-0.205711,0.342133,-0.446076,0.263492,-0.077780,0.175791,0.262204,-0.619439,0.295220,0.015309,0.105429,0.429000,-0.032929,-0.058906,-0.489972,0.117128,0.660748,0.046014,-0.163871,0.387865,-0.166914,-0.155978,-0.009268,-0.082786,-0.574387,-0.201734,0.303709,-0.085843,-0.430207,0.251003,-0.617170,0.058638,0.152311,-0.452443,0.029129,-0.264863,-0.391904,-0.742701,-0.090460,-0.328103,-0.065680,0.112988,-0.081053,-0.083240,0.853808,-0.804710,0.243420,0.550911,0.234046,-0.466722,0.660909,0.142585,-0.042533,-0.151551,-0.270926,-0.204934,-0.078226,0.230665,0.343722,0.714093,-0.158328,0.237760,-0.640616,0.476455', '1296534', '1302133', '2269893', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296519', '喋血双雄', '剧情', '杀手亚庄（周润发）在一次暗杀行动中误伤了歌星Jennie（叶倩文），令其双目接近失明，自此，深感内疚的他开始暗中保护、帮助 Jennie，并想趁她眼睛完全失明前筹一笔款送她去国外医治，为此，亚庄铤而走险再当杀手，不想任务完成后不但没收到钱，反被雇他杀人的汪海派人追杀。奉命侦查相关命案的警探李鹰（李修贤）在查案过程中知晓事情另有隐情，亚庄并非冷血杀手，开始同其惺惺相惜，而在应对汪海势力的追杀中，两人更是结成生死之交。然而亚庄的命运，似乎是被注定了。©豆瓣', '周润发', '吴宇森', 8.5, 78186, 'tt0097202', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554438688.jpg', 0.2, 0.7, 12.9, 47.6, 38.6, '0.180369,0.027856,-0.625929,0.274659,-0.141669,-0.179883,0.345064,-0.052796,-0.545576,-0.292961,0.273293,0.355523,0.144926,0.021617,0.344191,-0.402993,-0.098764,-0.674670,0.063634,-0.191581,-0.348812,-0.490657,-0.124396,-0.447242,-0.013683,-0.347457,0.675914,0.514041,-0.450750,0.504195,0.231681,0.263643,-0.227452,0.653702,0.076323,-0.157528,0.097924,-0.086155,-0.195986,0.301167,-0.041805,-0.636192,-0.162543,0.423634,-0.056548,0.653828,0.497443,-0.223423,-0.221457,-0.280316,0.083084,-0.625967,-0.081220,-0.060450,0.347112,0.195907,0.133589,0.286330,-0.314092,0.057525,-0.017560,0.115068,-0.777179,0.043289,0.281617,0.023593,-0.672430,0.036179,-0.223110,0.186888,-0.176159,-0.148805,0.195860,0.170243,0.306087,0.082301,-0.080206,-0.021315,-0.556026,0.370392,0.820833,-0.268338,0.205655,0.116595,0.305357,-0.401109,0.000771,-0.352172,0.060557,0.149376,0.474627,0.087889,-0.312873,0.377428,-0.215910,-0.052623,-0.368021,0.047053,-0.334785,-0.498979,0.176435,-0.627960,-0.132505,0.088745,-0.267143,0.145304,0.144786,-0.464585,0.197523,-0.696219,0.155308,0.774879,0.226644,-0.744487,0.396007,0.234895,0.191027,-0.195912,-0.135672,-0.079999,0.416879,0.274729,0.271413,-0.152536,-0.001355,0.035061,-0.154557,0.193768', '25908042', '35073886', '5157137', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296520', '武士', '剧情', '1375年，中国正是元明更替之际，高丽国亦经历了内乱，明朝使臣被高丽所杀。这一年，高丽使团在龙虎将军崔祯（朱镇模 饰）和州镇兵系统的长官大政（安圣基 饰）率领下出使明朝，却被边境官员以为明朝使臣报仇为由羁押，发配大漠。使团一行人在大漠遭遇蒙古一部袭击，意外的获得了自由，在返回高丽的途中，使团偶遇被蒙古拉哈木将军（于荣光 饰）一部捉获的明朝公主芙蓉（章子怡 饰），崔祯决定救出芙蓉公主，以便南下南京觐见朝廷，完成使团的任务。使团中获得自由身的奴隶英率（郑宇成 饰）和龙虎军、州镇兵等人大开杀戒，将公主救出。拉哈木不甘示弱，返回大营召集部从，誓要将公主带回大漠……©豆瓣', '安圣基', '金成洙', 6.8, 4990, 'tt0275083', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2364475259.jpg', 1.9, 9.2, 46.4, 31.2, 11.4, '-0.025754,0.269179,-0.371189,0.675750,0.661706,0.051999,0.015654,0.285285,-0.477878,-0.262418,0.270153,0.354466,0.047079,-0.561874,0.627013,-0.003429,-0.474435,-0.726470,-0.287729,-0.241387,0.038750,-0.068723,-0.101641,-0.262145,-0.058639,-0.596382,0.882416,0.403394,0.123004,0.963181,0.144133,0.214600,-0.245640,0.469442,-0.208480,0.213792,0.231518,-0.207222,-0.294343,0.392162,-0.468616,-0.683706,-0.164537,-0.038379,0.207721,0.249446,0.660109,-0.688232,0.435016,-0.322528,0.115443,-0.314856,0.054318,0.019142,0.481899,0.299967,-0.016112,0.480351,-0.242903,-0.019895,0.076795,-0.298775,-0.227741,0.049462,0.286743,-0.042411,-0.645843,0.368861,-0.305505,0.214650,0.124864,-0.417096,0.387617,0.994976,0.053812,0.129789,0.122747,-0.022788,-0.677979,0.456235,0.915958,-0.441728,0.222029,-0.825771,0.386934,-0.593829,0.304541,-0.417309,-0.035270,0.194107,0.186591,-0.567455,0.379841,0.074279,-0.421155,-0.220545,-0.709244,-0.247513,0.473635,0.083719,0.138730,-0.503736,0.108932,0.024340,-0.064709,0.042103,0.778926,0.456760,0.368628,-0.551820,-0.014689,0.362146,0.731089,-0.844343,0.373129,0.114314,0.053311,-0.152864,0.035035,-0.122726,0.397317,0.550793,0.116075,0.113890,-0.428293,-0.311939,-0.460847,-0.152474', '34906611', '1302705', '3074408', '3078390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296528', '星球大战2：帝国反击战', '动作', '维德勋爵（大卫•普劳斯 David Prowse 饰）把抵抗力量赶出基地，并派出数以千计的探针寻找卢克•天行者（马克•哈米尔 Mark Hamill 饰）。抵抗力量埋伏到冰天雪地的哈斯星，卢克在一次巡逻任务中意外被雪人所俘，运用“原力”逃生后晕厥中听到欧比-旺•肯诺比（亚历克•吉尼斯 Alec Guinness 饰）要他前往狄克星寻找绝地武士尤达师傅受训。银河帝国派出大军进攻哈斯星，韩•索罗（哈里森•福特饰）携猿人丘巴卡（彼得•梅林 Peter Mayhew 饰）带莉亚公主（卡里•费什尔 Carrie Fisher 饰）和机器人C-3PO乘千年隼飞船逃生，到达韩•索罗的旧识总督蓝多•卡瑞辛（比利•迪•威廉姆斯 Billy Dee Williams 饰）的贝斯平云城暂时歇脚，却发现蓝多早与维德勋爵达成协议，出卖韩•索罗设计陷阱诱惑卢克前来。学业未成的卢克不顾尤达的劝阻执意孤身付险，一场恶战在所难免。本片获第53界奥斯卡最佳声效奖及视觉效果特殊贡献奖，并获最佳艺术指导-布景及最佳原创电影音乐两项提名。', '马克·哈米尔', '厄文·克什纳', 8.4, 98188, 'tt0080684', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p732937546.jpg', 0.3, 1, 14.8, 46.3, 37.6, '0.134940,0.033931,-0.492404,0.561199,0.301008,-0.115613,0.412900,0.026010,-0.112424,-0.456033,0.058250,0.530544,-0.144685,-0.175479,0.386090,-0.150346,-0.411526,-0.276644,0.045633,-0.156488,-0.100315,-0.496930,-0.247244,-0.167718,0.042916,-0.624578,0.376214,0.142749,-0.099452,0.520385,0.276682,0.383817,-0.191887,0.120976,0.282132,0.034590,0.415652,-0.403155,-0.329925,0.521044,-0.238985,0.158555,-0.106346,0.090361,0.299249,0.263521,0.390838,-0.493040,0.513544,-0.017807,-0.072168,-0.310343,0.455491,-0.066564,0.339041,-0.290345,-0.227995,0.206175,0.086392,0.377592,0.165566,-0.242683,-0.562367,0.126549,-0.017862,-0.007428,-0.520443,0.004741,-0.186663,0.174914,-0.105964,0.011898,0.096604,0.309766,0.273071,-0.248863,0.202577,0.131523,-0.431448,0.025979,0.152467,-0.310474,-0.123118,-0.161407,0.138146,-0.631575,0.133607,-0.223600,-0.238421,-0.046432,0.602629,-0.085847,0.456431,-0.017267,-0.399810,-0.176426,-0.653628,-0.180909,-0.186524,-0.032310,0.170602,-0.997133,0.352041,0.005555,-0.066708,0.159717,-0.005772,-0.058539,0.167180,-0.395978,0.157171,0.511426,0.175480,-0.055954,0.161501,-0.084623,0.101567,-0.272658,-0.143550,0.505839,0.334896,0.396041,0.149935,0.091881,0.141027,-0.166123,-0.276387,0.229927', '6517421', '1297151', '2075345', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296534', '神秘列车', '剧情', '美国田纳西州，猫王的故乡孟菲斯，一家廉价破旧的孟菲斯旅馆，三段彼此交错的平行故事，就发生在这家献给猫王埃尔维斯·普雷斯利的旅馆之中。故事一：一对痴迷于美国五十年代摇滚音乐的日本情侣来到孟菲斯。然而一个是猫王的粉丝，一个则喜欢与猫王同时期崛起的音乐人卡尔·帕金斯。两人以朝圣的心情来到猫王的故乡。那些生活中浪漫的微小细节，却并不能阻止他们沉溺在音乐之中忘乎自我，男孩甚至对任何事情都无动于衷。出门时，他们听到一声枪响，戛然而止。故事二：一个为了躲避陌生男人纠缠的寡妇，投宿在这家孟菲斯旅馆。形单影只的她，遇见了刚与男友分手的独身女孩，两人共处一室。深夜，这位寡妇似梦非醒的看见了猫王的幻影。在神秘的会面之后，收音机里传来《蓝月亮》。出门的一刻，枪声响起。故事三：同样的猫王照片，同样的《蓝月亮》。回溯故事二中的女孩。男友与她分手后在酒吧喝酒，然而一语不合让他错手打伤了老板，他和女友以及女友的弟弟，仓皇中逃亡至此。天亮时，屋内传来一声枪响。', '永濑正敏', '吉姆·贾木许', 8.1, 16107, 'tt0097940', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p459490157.jpg', 0.5, 1.6, 17.9, 51.6, 28.4, '0.565545,0.032534,-0.739559,0.623180,-0.045589,-0.289494,1.189339,0.130373,-0.336892,-0.314644,0.090987,0.981703,-0.366326,0.374519,0.356088,-0.004738,-0.057720,-0.698068,0.011380,-0.148006,0.021807,-0.253395,-0.032330,-0.304459,-0.061482,-0.062978,0.375226,0.130613,-0.203400,0.639846,0.187748,0.048737,-0.556069,0.476262,-0.172216,0.026056,0.187461,0.194091,-0.463160,0.095550,-0.181776,-0.050947,-0.068996,-0.004805,-0.297273,0.189757,0.587140,-0.338629,-0.040274,0.041454,0.327450,0.216070,-0.308137,-0.059312,0.342248,-0.086714,0.503154,0.184136,-0.052384,-0.019202,-0.261943,0.075447,-0.212678,0.352703,-0.134481,0.202464,-0.300084,0.350777,-0.108922,0.108307,0.362913,-0.305797,0.388093,0.088034,0.275615,0.598085,-0.323887,0.138979,-0.453566,0.064269,0.768203,0.035687,-0.222833,0.455005,0.023191,-0.491846,-0.051726,0.115437,-0.623633,-0.079237,0.246405,-0.093822,-0.151575,0.093720,-0.627941,-0.052697,-0.032601,-0.290998,-0.074903,-0.235727,-0.452013,-0.671142,-0.063562,-0.319933,-0.063828,0.192341,0.076882,-0.011751,0.557849,-0.868485,0.262661,0.531122,0.195200,-0.106402,0.561063,0.089231,0.282679,-0.103906,-0.177337,0.282877,0.085135,0.108939,-0.056302,0.267866,-0.211761,0.005844,-