INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296535', '幽灵船', '悬疑', '1962年5月，意大利豪华客轮安东尼亚•格拉撒号在行驶到白令海峡附近时，连同船上数百名乘客突然凭空消失，成为近代航海史著名的悬案之一。2002年，一架加拿大空军的飞机在该海域发现了一艘随波逐流的小船，飞行员杰克•弗里曼（Desmond Harrington 饰）为小船背后的秘密所吸引，他雇佣西恩•墨菲船长（Gabriel Byrne 饰）及其搜救小组前去公海寻找那艘漫无目的漂泊的客轮。按照海洋法规定，任何在公海发现的无主船只都归发现者所有，而一艘豪华客轮无疑是一笔巨大的财富。及至找到目标时莫菲船长才发现，这便是那艘消失了四十年之久的安东尼亚•格拉撒号！为财富所吸引，他们相继登上这艘客轮，而各种怪异诡秘的事件也相继发生……©豆瓣', '加布里埃尔·伯恩', '史蒂芬·贝克', 6.9, 40643, 'tt0288477', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p509817191.jpg', 0.9, 6.3, 48.6, 34.8, 9.5, '0.045118,-0.037309,-0.847010,0.422980,0.541619,-0.145473,0.629841,-0.283155,-0.474535,-0.149888,0.325859,0.876039,0.080007,-0.049533,0.756721,0.400285,-0.539071,-0.364657,-0.134610,-0.569616,-0.431026,-0.724280,-0.127192,-0.387121,0.097559,-0.321090,0.698436,0.481968,0.168715,0.460694,0.318232,0.254136,-0.318035,0.471940,-0.271059,-0.091494,0.318590,-0.312322,0.073631,-0.096527,-0.839205,-0.256739,0.219137,-0.204784,0.062304,0.243603,0.952854,-0.355102,-0.093561,0.183318,0.045217,-0.278827,0.216822,-0.527673,0.676684,-0.069670,-0.490283,0.176635,-0.328875,-0.089302,0.084984,0.234244,-0.251939,-0.122434,-0.291119,-0.021364,-0.316240,-0.008536,-0.226267,-0.025216,-0.185279,-0.102961,0.336813,0.292365,0.012000,0.128702,-0.025868,0.381757,-0.552103,0.044273,0.664411,0.022175,-0.138582,0.161714,-0.065585,-0.432814,-0.282917,-0.557081,0.029161,-0.304804,0.493017,0.135858,0.113282,0.283535,-0.680325,0.181297,-0.543914,-0.662645,-0.073296,-0.030960,-0.351456,-1.067259,0.342490,-0.155598,0.161735,0.502647,-0.062085,0.010885,0.542094,-0.288676,0.356387,0.605388,-0.041130,-0.225692,0.777049,-0.344623,0.165648,-0.249331,-0.072978,0.354222,0.261414,0.408679,-0.313546,0.152612,-0.020377,-0.118928,-0.139665,0.246362', '2159244', '3871833', '10466639', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296538', '小飞侠', '动画', '小飞侠皮特•潘是梦幻岛上永远不会长大的小精灵，这天，忍不住寂寞的他飞到了伦敦，飞入了小女孩温蒂的家。温蒂做梦也没有想到这世界上真的有小精灵存在，而且自己还被邀请前往梦幻作客。兴奋不已的她带上两个弟弟，三人一起跟随小飞侠飞往了那个想象中的世界。梦幻岛上有温蒂他们从来没有见过的各种各样的东西，印第安酋长、美丽的公主、童话中的人鱼等等，让三人玩得十分开心，小飞侠还帮他们在这里安了家。这时，坏蛋海盗船长来到了岛上，小飞侠必须去战斗了！©豆瓣', '鲍比·德里斯科尔', '克莱德·杰洛尼米', 8.4, 28826, 'tt0046183', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1161429881.jpg', 0.2, 0.7, 15.4, 46.1, 37.5, '0.528698,0.041220,-0.916629,0.439750,-0.159973,-0.373746,0.735862,-0.107224,-0.655165,0.041632,-0.152303,0.903560,-0.326438,0.385171,0.204637,0.270627,-0.577608,-0.455462,-0.249751,-0.231701,-0.386302,-0.375510,0.043565,-0.101745,-0.061045,-0.198506,0.244233,-0.015675,0.205985,0.594108,0.150689,-0.067199,-0.283283,0.575159,-0.372026,0.250915,0.097323,0.212654,-0.046835,0.415073,0.033423,0.025859,0.117518,0.177404,0.203277,-0.018137,0.564573,-0.497890,0.041124,-0.171160,-0.092716,-0.123882,-0.044645,-0.003192,0.272069,-0.453947,0.101412,-0.207490,0.013415,-0.101668,0.035116,-0.176431,-0.553959,0.163031,0.191806,0.095865,-0.627667,0.205617,0.071482,0.001857,0.166994,-0.336754,0.611427,0.242000,0.194663,0.215272,0.082062,0.050440,-0.665397,0.120771,0.887859,0.018186,0.068608,0.006177,-0.245574,-0.371795,-0.159789,-0.224074,-0.499880,0.251150,0.304373,0.008038,-0.420246,-0.034940,-0.682448,0.161497,-0.094663,-0.219993,-0.072369,-0.438936,-0.190795,-0.491387,0.259698,-0.413295,-0.312746,0.022857,-0.159547,-0.193609,0.686401,-0.929999,0.399324,0.526023,0.524162,-0.178847,0.947298,-0.167453,-0.144991,-0.113446,0.059815,0.256792,0.155039,0.266667,0.278939,0.374320,-0.052141,-0.065917,-0.381839,0.441840', '3055049', '1302384', '2990737', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296542', '铁达尼号沉没记', '剧情', '据说永不沉没的泰坦尼克号巨型游轮即将从伦敦起航，直奔大西洋的彼岸美国。各种各样的人聚集在船上，其中有商人阿利森一家、漂亮的女游客伊莎贝拉、小偷贾米。阿利森太太因为两个孩子雇佣了一个新保姆，却发现她经常神情紧张、心事重重；伊莎贝拉在一次聚餐上邂逅了初恋情人温，被父亲的独断压抑的恋情热烈地爆发了；贾米被纯洁的女仆吸引，渐渐意识到做人的真正意义……许多故事刚刚揭开序幕，意外发生了——泰坦尼克撞上了冰山，所有人都被推到了生死存亡的紧急关头……', '彼得·盖勒', '罗伯特·里伯曼', 8.7, 5926, 'tt0115392', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1502753803.jpg', 0.7, 1.1, 11.5, 37.2, 49.5, '0.484028,0.127593,-0.862868,0.270821,-0.123068,-0.308547,0.934027,0.139050,-0.355634,-0.103577,0.415007,0.959102,-0.716100,0.214037,0.540804,0.149287,-0.130237,-0.517478,-0.169680,-0.042682,-0.316979,-0.211695,-0.132647,-0.170451,0.005319,-0.268225,0.273522,0.267277,-0.106710,0.367806,0.273639,0.282425,-0.254453,0.691535,-0.210507,0.096892,0.329536,-0.106713,0.304223,-0.030269,-0.328317,-0.284463,0.092675,0.205351,-0.032933,0.471892,0.745341,-0.159155,-0.097318,0.078863,0.348120,-0.159591,0.087603,0.155970,0.542042,-0.033010,-0.269032,0.153898,-0.089195,-0.366784,0.031294,0.027103,-0.435303,0.057120,-0.083224,0.237691,-0.495439,0.673430,-0.057233,-0.005192,0.055348,-0.187453,0.373494,0.289561,0.109437,0.083145,0.058374,0.179971,-0.359231,0.113608,0.791519,-0.075114,-0.207105,0.555076,-0.447644,-0.305610,0.056676,-0.264392,-0.433982,-0.091961,0.684182,-0.101102,-0.296008,0.433273,-0.788612,-0.175058,-0.386674,-0.261576,-0.297137,-0.278510,-0.322888,-0.604379,-0.027802,-0.318051,-0.015521,0.183490,-0.181868,0.077778,0.796650,-0.548315,0.281390,0.768879,0.150978,-0.039161,0.583936,-0.221346,-0.030335,-0.143301,0.049501,0.237872,0.087958,0.338176,0.073226,0.396414,-0.458309,0.107043,-0.218983,0.647119', '30162520', '3011051', '34461680', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296553', '女囚尼基塔', '动作', '妮琪塔（安妮·帕里洛德饰）与一群朋友抢劫一家商店的药品，商店的主人与她的朋友都在这次的事件中身亡，妮琪塔则是因为杀了一位警察而被送入狱。此时来了一个神秘的政府组织，选上了妮琪塔，并训练她成为特务杀手，在经过数年的特务训练之后，妮琪塔以一个平凡的护士身份回到现实的生活中，在此时她爱上了一个男人，他们的关系在妮琪塔接到一个特务命令时，面临了紧张的局面...', '安娜·帕里约', '吕克·贝松', 7.5, 17544, 'tt0100263', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555194472.jpg', 0.6, 3.5, 32.6, 47.3, 15.9, '0.492899,-0.012889,-0.423624,0.589718,-0.414010,-0.399639,1.076484,0.227025,-0.609668,-0.478323,0.434953,0.909084,0.075267,0.222300,0.439440,-0.128799,-0.301022,-0.713693,-0.046996,-0.385428,-0.398925,-0.226301,-0.122901,-0.446535,-0.051918,-0.434261,0.625445,-0.020371,-0.142646,0.514262,0.271828,0.230789,-0.259035,0.469761,-0.034229,-0.152798,0.646366,-0.157668,-0.236003,0.466072,-0.308760,-0.373305,0.075714,0.210088,-0.062766,0.430440,0.630287,-0.279582,-0.207667,-0.050990,0.242119,-0.343255,-0.189394,0.152768,0.658034,-0.080481,0.140817,0.146115,-0.418708,0.160512,-0.035241,-0.062720,-0.944243,-0.186197,-0.005306,0.204148,-0.706415,0.662469,-0.190332,0.060901,-0.110101,-0.399680,0.469192,0.426849,0.136654,0.437613,-0.191462,0.022583,-0.527519,0.139674,0.789206,-0.124587,0.009925,0.213088,-0.161241,-0.553974,-0.079032,-0.065333,-0.444450,-0.007007,0.478081,-0.314390,-0.328273,0.112439,-0.640201,0.019042,-0.228329,-0.073155,-0.154809,-0.374128,-0.190574,-0.726920,0.056290,-0.237367,-0.320570,0.213135,0.036916,0.075324,0.672793,-1.017713,0.245793,0.609749,0.148833,-0.622812,0.407568,0.262077,0.343679,-0.203654,-0.069694,0.051454,0.436457,0.612730,0.068781,0.466088,-0.179313,-0.149626,-0.307385,0.218129', '1793491', '3285642', '1308755', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296557', '投奔怒海', '剧情', '日本摄影记者芥川（林子祥）三年后重返刚刚解放的越南采访，遍地的生机令他心生欢喜，但当他无意间走进城市的另一隅结识当地女孩琴娘（马斯晨）后，方知之前所见不过是越共政府特意为他这样的外国记者安排的粉饰太平的假像。在琴娘并非刻意的“导游”下，越南平民百姓正处于水深火热中的悲惨生活逐渐被芥川尽收眼底。琴娘一家人、战后唯一留下来的某酒吧的老板娘（缪骞人）及她的正想方设法逃离越南的情人祖明（刘德华）等人的被越共任意践踏的自尊强烈地触动着芥川敏感善良的心，尽管他并无彻底改变他们命运的能力，却仍是尽力给予帮助。©豆瓣', '林子祥', '许鞍华', 8.5, 20372, 'tt0084807', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2492745076.jpg', 0.4, 0.8, 11.7, 48.5, 38.6, '0.350718,0.119878,-0.754977,0.444387,-0.280893,-0.174153,0.702681,0.174533,-0.764495,-0.056624,0.188785,0.692593,-0.045641,0.404367,0.193105,0.112173,-0.369304,-0.645073,-0.438799,0.059312,-0.076275,-0.189225,-0.257397,-0.213853,-0.340453,0.017247,0.666244,0.312868,-0.106459,0.222465,0.048601,0.336918,-0.033395,0.588142,-0.283542,0.052449,-0.084820,-0.135149,-0.395003,0.106847,-0.032421,-0.380420,-0.310107,0.406425,-0.301395,0.473760,0.507186,-0.255724,-0.188540,-0.166434,0.454592,-0.260094,0.142195,0.215850,0.089341,0.017522,0.376248,0.024237,-0.209154,0.042599,0.123499,0.189119,-0.607324,0.075952,0.077703,0.133110,-0.391504,0.557628,0.083708,0.102279,0.170715,-0.145127,0.131473,0.230271,0.096493,0.257927,-0.282654,0.043650,-0.300966,0.203788,0.703423,0.149537,-0.292006,0.167784,-0.258218,-0.366658,0.440418,-0.248042,-0.313968,-0.113314,0.221132,0.253655,-0.213573,0.105749,-0.373074,0.018671,-0.231191,-0.142645,-0.078506,-0.440950,-0.127959,-0.647207,-0.105677,-0.489222,-0.219380,-0.005225,0.282830,-0.129647,0.662757,-0.908979,0.112194,0.679477,0.251023,-0.478528,0.555098,0.069849,-0.089377,-0.118702,-0.296308,0.376415,0.022775,0.533097,0.105691,0.209256,-0.170347,-0.211455,-0.218307,0.404411', '35030151', '1301022', '1308755', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296569', '我的老婆是大佬', '喜剧', '恩珍（申恩庆 饰）从小与姐姐相依为命，命运的洪流却冲散的两人。待再相见时，恩珍已经成为了能够独当一方的黑道首领，而姐姐却患上了绝症。即将不久于人世的姐姐有一个愿望，那就是在有生之年能够看着恩珍找一个好男人托付终生，为了实现姐姐的愿望，黑帮大佬开始了漫漫寻爱路。朱兜（朴相勉 饰）是一个三十岁老处男，他生性老实，有稳定的工作和一颗爱家的心，这样的人正是成为恩珍夫婿的最佳人选，恩珍隐瞒了自己的身份，两人约法三章绝不发生肌肤之亲，违者挨揍。没想到这时姐姐的愿望升了级，她不仅希望有一个妹夫，还希望恩珍能品尝到做母亲的喜悦，爱姐心切的恩珍只得为了姐姐的愿望再次风风火火的奔走起来，这时敌对势力的成员开始不断的骚扰恩珍的正常生活，作为一个母亲和妻子，恩珍要为了自己的家庭全力反抗。©豆瓣', '崔民秀', '赵真奎', 6.4, 20877, 'tt0296696', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2262652837.jpg', 1.6, 10.7, 60, 22.7, 5, '-0.068837,0.063788,-0.596648,0.591850,-0.366153,-0.375805,0.663001,0.199746,-0.454193,-0.089293,0.114957,0.867555,0.085840,0.359540,0.349527,-0.096511,-0.023195,-0.762048,0.000490,-0.144384,-0.096818,-0.141345,-0.177293,-0.170473,-0.196697,-0.347006,0.701719,0.043358,0.006899,0.200763,0.461536,0.115170,0.044516,0.406011,-0.332948,-0.129732,-0.234726,0.096336,-0.521469,0.228447,0.021805,-0.068943,0.118597,0.053919,-0.146078,0.162278,0.571086,-0.189985,-0.197514,-0.269859,0.279918,-0.176337,0.094957,0.124170,0.167881,-0.199380,0.326237,0.130061,-0.211649,-0.297639,0.115489,-0.154703,-0.890672,-0.142113,0.272640,0.199696,-0.524247,0.349806,-0.070019,-0.192694,0.254368,-0.322576,0.090892,0.630570,0.143316,0.294037,-0.514459,0.179020,-0.472615,0.235706,0.861758,-0.027000,-0.102800,0.451103,-0.053953,-0.392853,0.164560,-0.260383,-0.575839,-0.068299,0.170090,0.180120,-0.303646,0.079577,-0.383736,-0.087069,-0.246180,0.004964,0.168835,-0.647251,0.138019,0.075609,-0.115850,-0.288070,-0.315307,0.229736,0.027130,-0.346219,0.908655,-0.963058,0.206484,0.462703,0.355191,-0.725679,0.755576,0.415353,0.221293,-0.247666,0.150922,0.094325,-0.206936,0.290860,0.042252,0.283570,0.043448,0.001645,-0.300966,0.279169', '4301278', '30345227', '1877596', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296579', '枕边书', '剧情', '和子（邬君梅 饰）小时候每次生日，父亲就会用毛笔蘸上红颜料在她脸上写字，这给和子留下极深刻的印象，她从此认定写在身体上的书法才是唯一的书法。加上自幼接受文学熏陶，内心有着自己独立的想法，却迫于现实中父权的权威而无法尽情释放自我。亦因为难以明白她对自我的追寻是寓于对 文学 的痴迷中，和子的第一段婚姻以失败收场。其后她去了香港，在那里她认识了出版商和他的同性恋情人谢朗（伊万·麦克格雷格 Ewan McGregor 饰），谢朗鼓励她在自己身上写字，和子就此创作《枕草子》，每写满一遍为一卷，每写完一卷，谢朗就去找出版商，把身上的字给出版商看。而后和子却因受不了谢朗冷落对他避而不见，谢朗为夺回和子，决定以死相逼。©豆瓣', '邬君梅', '彼得·格林纳威', 6.7, 10814, 'tt0114134', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1014297496.jpg', 3.3, 11.6, 44.1, 28.9, 12.1, '0.172651,0.072052,-0.644490,1.001167,-0.063964,-0.415685,0.669152,0.036543,-0.494700,-0.213700,-0.010528,0.956486,-0.058282,0.289969,-0.024703,-0.019878,-0.244227,-0.712759,-0.075194,-0.126082,-0.312864,-0.591789,-0.027229,0.028027,-0.352529,-0.105643,0.477912,0.070871,-0.377502,0.262073,0.366856,0.219793,0.116507,0.286220,-0.063159,0.154363,-0.539121,-0.106809,-0.170028,-0.014126,0.507304,-0.368233,-0.157318,0.296513,-0.191040,0.234503,0.771033,-0.212084,-0.088631,-0.050240,0.559476,-0.338081,-0.149633,0.221314,-0.046785,0.279299,0.332946,0.129379,-0.282332,0.028175,-0.011414,-0.005296,-0.778714,-0.177974,0.248839,0.112860,-0.627484,0.659708,-0.297438,-0.111082,0.000428,-0.385817,0.000698,0.007068,0.273632,0.454356,-0.167513,-0.027204,-0.171038,0.298162,0.253831,0.099991,-0.009603,0.268075,-0.361159,-0.061925,0.140921,-0.437185,-0.267768,-0.127584,0.105786,0.428782,-0.281338,-0.080684,-0.290353,-0.071330,0.014016,-0.185233,0.131674,-0.631428,0.000583,-0.143250,-0.246507,-0.438223,-0.328945,-0.185340,0.202141,-0.433440,0.642307,-0.721973,0.320162,0.256104,0.301227,-0.413224,0.600666,0.416186,-0.197827,-0.056685,0.029272,0.360622,0.032228,0.179551,0.242225,0.163104,0.358858,0.008714,-0.458493,0.821565', '27666513', '1870681', '3119246', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296617', '杀戮战场', '剧情', '1972年，美军在越南溃败撤离柬埔寨之后，纽约时报驻柬埔寨的战地记者辛尼（萨姆·沃特森 Sam Waterston饰）仍留在当地继续采访。柬埔寨人潘迪（吴汉润 Haing S. Ngor饰）是辛尼的当地翻译兼助手。辛尼在潘迪的帮助下，多次化险为夷逃过鬼门关。两人在战火纷飞中结下了深厚的友谊。1975年，红色高棉占领金边。辛尼得以全身而退，然而潘迪却因为没有护照而被捕，开始了生不如死的地狱生活。在柬共的劳动改造中，潘迪目睹了红色高棉政权的残暴血腥，受到了非人的待遇。1978年，越共入侵柬埔寨，潘迪趁机逃亡到泰国边境，与一直在寻找他的老朋友辛尼重逢。本片荣获1985年第57届奥斯卡金像奖最佳男配角、最佳摄影和最佳电影剪辑三项大奖。©豆瓣', '萨姆·沃特森', '罗兰·约菲', 8.3, 6598, 'tt0087553', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1300292638.jpg', 0.4, 1.5, 13.5, 49.9, 34.7, '0.013636,-0.280162,-0.629886,0.458884,0.230225,-0.248710,0.444699,0.039826,-0.602460,0.011531,0.117511,0.589603,-0.276676,-0.087868,0.375268,-0.085982,-0.389432,-0.929764,-0.192570,-0.100511,-0.091362,-0.254924,-0.469486,-0.068075,-0.353827,-0.474429,0.747811,0.092387,-0.065415,0.621721,0.243324,0.132459,-0.162219,0.142515,-0.305802,0.124003,0.146288,-0.034358,-0.765230,0.452425,-0.051479,-0.532987,-0.412070,0.039743,0.365449,0.398547,0.602403,-0.157977,0.265199,0.040934,0.422949,-0.458106,-0.292559,0.103935,0.346113,0.067841,0.230560,0.312845,-0.224823,0.129216,-0.180355,-0.101595,-0.587070,-0.046692,-0.079200,0.127036,-0.379278,0.593065,-0.224235,0.284132,-0.049301,-0.315074,0.216451,0.575742,0.195704,0.303327,-0.111573,0.184591,-0.413664,0.513466,0.895278,-0.115438,-0.315318,-0.034325,-0.034667,-0.614606,0.030503,-0.388926,-0.173110,-0.011818,0.362163,0.053395,-0.203648,0.216192,-0.670696,-0.196023,-0.416116,-0.372162,0.036163,-0.000764,-0.163650,-0.903986,-0.318757,-0.430896,-0.124048,0.168993,0.006564,-0.243371,0.544773,-0.607438,0.430797,0.610583,0.315290,-0.358804,0.605624,0.306182,0.134446,-0.043328,0.031223,0.512754,0.058720,0.373506,0.326330,0.165870,-0.282323,-0.225618,-0.132521,0.257491', '11541282', '1780122', '26365262', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296623', '两个只能活一个', '剧情', '生活潦倒的穷鬼阿武（金城武）某次因为赌博被人殴打至重伤后，开始把生命看得一文不值，拿命赌命以八万元代价接了一宗杀人买卖。行动前因为获得八十万意外之财，阿武又爱惜起生命来，请了刚从监狱出来的女杀手卡雯（李若彤）代他完成任务。卡雯无法对旧情释然，屡次要阿武去见有负于她的旧男友，否则拒绝行动，阿武于无奈之下听命，却在了解事实真相的过程中慢慢爱上了卡雯，然而任务必须进行，阿武开始犹豫是否再把卡雯替下来自己去杀人。©豆瓣', '金城武', '游达志', 7.7, 21755, 'tt0119818', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2460373357.jpg', 0.5, 2.8, 28.1, 47.3, 21.2, '-0.038111,0.426872,-0.424150,0.269683,-0.289135,-0.472686,0.529958,-0.086602,-0.285589,0.092947,0.086693,0.631637,0.257276,-0.124504,0.159482,-0.148161,-0.287409,-0.473658,-0.244702,-0.153633,-0.391686,-0.563304,0.179970,-0.182699,-0.217186,-0.166269,0.449476,0.101872,-0.089697,0.368650,0.439200,0.304961,0.024607,0.494994,-0.110973,-0.092241,-0.160586,0.057243,-0.424126,0.322004,0.321094,-0.395060,-0.221628,0.385248,0.097145,0.350599,0.606091,-0.103466,-0.333762,-0.185975,0.406737,-0.189917,-0.054740,0.141770,0.049611,0.360865,0.126249,0.179571,-0.156221,0.107057,0.039966,-0.077737,-0.792596,0.029233,0.094995,0.022539,-0.685324,0.198558,-0.433504,0.181735,-0.027050,-0.394112,-0.026177,0.367559,0.520268,0.102359,-0.415956,-0.047608,-0.425194,0.162209,0.659131,-0.147845,0.134989,0.423536,0.193422,-0.418562,0.228672,-0.415759,-0.123890,0.109367,0.287369,0.164688,-0.348125,0.053450,-0.392940,-0.336670,-0.208799,-0.105826,-0.177903,-0.403997,-0.165563,-0.062262,-0.052164,0.234541,-0.425352,0.104385,0.173502,-0.415796,0.321909,-0.662267,0.138356,0.683101,0.405108,-0.574140,0.336936,0.036647,0.142856,-0.029185,0.155547,0.066859,0.138683,0.620261,0.492275,0.058745,0.075481,-0.147323,-0.216735,0.363012', '26678784', '1292584', '1304977', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296628', '特警判官', '动作', '这是一部典型的史泰龙式的科幻电影。2139年，科学高度发达。凭借高科技武器和过人身手，爵德（西尔维斯特•史泰龙 Sylvester Stallone 饰）成了梅洛城法官、警察和行刑人于一身的判官战警，他发现罪犯可以马上逮捕、马上判刑，死刑的话还可以马上执行。就是这样一个四出惩治罪恶的判官，这次竟然被诬蔑成杀人犯。幸好有主席法官尽力相助，爵德才幸免一死，不过他被逐出了梅洛城。不甘心含冤受屈的爵德冒险潜回了梅洛城调查整件事的来龙去脉，犯罪分子里戈（阿曼德•阿山特 Armand Assante 饰）逐渐浮出了水面……©豆瓣', '西尔维斯特·史泰龙', '丹尼·加农', 6.6, 9828, 'tt0113492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2193563613.jpg', 1.2, 7.8, 56.6, 26.7, 7.7, '0.260772,-0.033765,-0.320363,0.253552,-0.028808,-0.087194,0.223911,-0.026696,-0.456732,-0.156494,0.044335,0.685451,-0.106957,0.027333,0.387870,0.094182,-0.502961,-0.583245,-0.117894,-0.203361,-0.339968,-0.582943,-0.080153,-0.369253,0.155067,-0.335764,0.399732,0.062143,-0.118338,0.196182,0.343567,0.588944,0.101109,0.220998,-0.017935,0.177856,0.211978,-0.457690,-0.169566,0.292141,-0.033953,-0.142774,-0.099819,0.011893,-0.055455,0.398432,0.287048,-0.271819,-0.286887,-0.186294,0.335624,-0.739792,-0.027321,0.103154,0.098744,-0.295976,-0.023513,0.544293,-0.130676,-0.001029,0.213919,-0.264433,-0.614852,-0.107022,-0.028557,0.198378,-0.438488,0.120513,-0.412775,0.098774,-0.327854,-0.060174,0.161447,0.137707,-0.096683,0.257322,0.100360,-0.202809,-0.774369,0.389013,0.483543,0.095899,-0.431044,-0.170611,0.154667,-0.513978,-0.053723,-0.444122,0.038425,0.070111,0.430549,-0.185934,-0.133092,0.037936,-0.258546,-0.362836,-0.660778,0.159583,-0.406069,-0.229109,0.027182,-0.238796,-0.044873,-0.009609,-0.258990,0.129499,0.000522,-0.030236,0.058642,-0.509148,0.052300,0.324567,0.162955,-0.410046,0.231806,0.076741,-0.100756,-0.201708,-0.100004,-0.015207,0.510478,0.465022,0.390247,0.287273,0.464515,-0.492678,-0.021651,0.192311', '1292659', '1295318', '25862560', '26949264');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296629', '倩女幽魂2：人间道', '爱情', '宁采臣（张国荣 饰）与燕赤霞（午马 饰）安葬好小倩的骨灰后，分道扬镳。宁采臣回到世间，正是奸臣当道，朝政混乱，民生困苦的时代。宁偶入一家黑店，险被残杀之际又被捕快误抓入狱，遇到名士诸葛卧龙（谷峰 饰），得其相救。逃出狱后路经一所荒寺，被年青鬼马道士知秋一叶（张学友 饰）缠上，误会不断。山庄中阴森恐布，隐藏着一只巨尸，然巨尸未现，却出现一伙白衣鬼魂。宁偶摘掉其中一女子面具，发现其竟与昔日恋人小倩（王祖贤 饰）一模一样……©豆瓣', '张国荣', '程小东', 8.1, 168588, 'tt0100625', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2518212196.jpg', 0.2, 1.6, 21.1, 49, 28.1, '0.164685,0.196434,-0.297348,-0.058489,0.185731,-0.187896,0.802306,0.133514,-0.423505,-0.400273,0.300510,0.407385,-0.256932,0.235601,0.167038,0.072356,0.070247,-0.531146,-0.149811,-0.228022,-0.070345,-0.044620,-0.310478,0.127934,-0.153432,-0.195221,0.387868,0.088728,-0.027728,0.749409,0.319303,0.404178,-0.814998,0.242363,-0.230651,-0.004857,-0.038142,0.161969,-0.341065,0.261194,-0.448552,-0.240995,-0.094499,-0.139880,-0.664922,0.197020,0.679049,-0.170974,-0.086903,-0.375217,0.376652,-0.024503,-0.193696,0.060541,0.435964,-0.063098,0.224182,0.117951,-0.380230,-0.041245,0.082021,-0.033549,0.020184,0.282548,0.366271,0.396370,-0.231937,0.044647,0.039407,-0.036056,-0.019590,-0.389100,0.202747,-0.007263,0.673397,0.135030,0.031927,-0.022955,-0.458230,0.361205,0.430797,-0.172880,0.167343,-0.084208,0.426367,-0.064218,0.271681,0.050647,-0.185668,-0.022722,0.409567,-0.083352,-0.106675,0.173642,-0.413716,-0.172875,-0.469506,0.626523,-0.266441,0.145742,-0.449208,-0.346943,-0.169756,-0.107645,-0.248773,0.143122,0.128032,0.019374,0.283707,-0.439984,0.097267,0.121003,0.185752,-0.061555,0.228720,-0.176471,0.200817,0.006104,-0.259759,0.393315,0.346626,0.148109,-0.060365,0.132628,-0.399690,-0.157407,-0.122639,-0.029550', '1302393', '10466639', '1292506', '1773217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296636', '小马王', '爱情', '广袤的美国西部地区，野马史比瑞特和他的族群过着平静的生活。然而，当史比瑞特第一次见到人类时，他就被抓去训练成战马。幸好善良的印第安小男孩小溪将史比瑞特从训练营里救了出来，并带他回到了自己部落。在小溪的部落，史比瑞特遇上了斑纹木马小雨。这一次，史比瑞特对回家乡还是留下来感到难以抉择，因为他深深爱上了小雨。小溪察觉出了两匹马的爱情，他决定让他们一起回史比瑞特的家乡。当史比瑞特刚刚依依不舍的和小溪告别后，小溪的部落就遭到了骑兵的袭击。史比瑞特和小雨马上回去救小溪，慌乱之下，小雨替小溪挡了一枪，而史比瑞特也重新被抓……©豆瓣', '马特·达蒙', '凯利·阿斯博瑞', 8.7, 22858, 'tt0166813', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2284067604.jpg', 0.2, 0.9, 12.7, 38.2, 48, '0.343919,0.019763,-0.721397,0.600943,-0.071232,-0.423837,0.606283,0.066650,-0.551724,0.137676,0.213535,0.658116,0.137336,0.340361,0.133539,-0.035140,-0.314699,-0.492635,0.000921,0.011808,-0.625858,-0.062618,-0.047810,0.088712,0.217610,-0.185679,0.565334,0.009659,-0.096626,1.038337,-0.045200,0.082519,-0.208006,0.590016,-0.399811,0.309175,-0.135925,-0.005515,-0.198316,0.155987,0.112507,-0.029357,-0.184959,0.239236,0.093600,0.246952,0.844311,-0.119808,0.004658,0.069872,0.045755,-0.575940,0.351575,-0.072731,0.506511,-0.236971,0.028155,0.177204,-0.087916,0.009932,-0.070253,-0.021872,-0.373829,0.155293,-0.170002,0.037892,-1.008074,0.371527,0.168315,-0.104485,0.426928,-0.401099,0.128496,0.249627,0.166527,0.465687,-0.326286,0.023927,-0.564343,0.094451,0.725043,-0.314141,0.052668,0.265621,-0.011635,-0.389521,0.346627,-0.153936,-0.136834,0.038937,0.595446,0.053401,-0.863891,0.116014,-0.723308,0.041257,-0.309670,-0.361505,0.143145,-0.330849,-0.364783,-0.137734,0.016125,-0.292138,-0.196687,0.227027,-0.294765,0.145788,0.530513,-0.636983,0.205851,0.635708,0.326559,-0.318012,0.667975,-0.114721,-0.081732,0.131506,0.578237,0.189205,-0.036553,0.725260,0.522117,0.451171,-0.282310,0.136109,-0.507531,0.462301', '35256235', '1451563', '26603666', '1294252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296659', '舞台春秋', '剧情', '1914年夏天，伦敦一所单身公寓。芭蕾舞女演员塞瑞拉·安布罗斯（克莱尔·布鲁姆 Claire Bloom饰）在自己的房间里，打开煤气企图自杀。万幸的是，喝得醉醺醺，刚回家的邻居卡尔费罗（查理·卓别林 Charles Chaplin饰）正好救了她。等赛瑞拉苏醒以后，卡尔费罗才得知她是因为患了风湿不能再跳舞，才产生轻生的念头。而卡尔费罗曾经是一名伟大的喜剧演员。他悉心的照料着赛瑞拉，并用自己的滑稽喜剧打消了她自杀的想法。六个月后，赛瑞拉重新成功的站了起来，并在一出芭蕾剧中担当重要角色。可赛瑞拉却与一名作曲家陷入了热恋，卡尔费罗只能默默的祝福他们，独自上演他的含泪喜剧。本片的主题曲为卓别林亲自操刀制作，以其优美动人的旋律，荣获1973年第45届奥斯卡金像奖，最佳原创配乐（剧情类）。©豆瓣', '查理·卓别林', '查理·卓别林', 8.9, 7296, 'tt0044837', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2299155914.jpg', 0.3, 0.8, 8.3, 34.9, 55.7, '0.071242,0.030884,-0.501370,0.519388,0.127029,-0.751376,0.737078,0.078599,-0.373139,-0.053293,0.220935,0.836128,-0.302139,0.175307,0.559320,0.128394,-0.604191,-0.675700,0.272286,-0.047166,-0.088692,-0.200288,-0.299602,-0.038909,-0.100222,-0.403493,0.545715,-0.403876,-0.136344,0.208157,0.563997,0.524544,0.058334,0.043981,0.221602,-0.015629,0.309942,-0.256229,-0.374436,0.261032,0.171118,-0.323836,-0.280473,0.184762,-0.006194,0.111124,0.521742,-0.282186,0.119227,0.161682,0.469998,-0.447820,-0.151423,-0.114952,0.106078,-0.055940,0.237353,0.040775,-0.106431,0.086256,-0.154141,-0.305392,-0.674788,0.058814,0.198181,0.148231,-0.561813,0.278215,-0.239259,0.194067,0.160698,-0.184267,0.029580,0.156017,0.353777,0.411629,-0.279281,-0.163993,-0.260175,0.384363,0.291918,0.118310,-0.318763,0.432291,-0.076002,-0.637754,0.106905,-0.182969,-0.448530,-0.022983,0.415104,-0.006136,-0.069644,0.062663,-0.353474,-0.374816,-0.462737,-0.232538,0.032231,-0.048069,0.031916,-0.583281,0.106242,-0.150047,-0.220446,-0.399749,-0.037315,-0.247121,0.616484,-0.552078,0.426685,0.616451,-0.100549,-0.059254,0.525706,-0.049876,0.351031,0.077442,-0.228419,0.502031,-0.477369,0.054349,0.183534,0.509662,0.022783,-0.189716,-0.481321,0.658858', '1299663', '30167633', '34890458', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296666', '回到未来3', '喜剧', '马丁（迈克尔·J·福克斯 饰）从他生活的八十年代来到了1955年，根据好朋友埃米• 布朗博士（克里斯托弗·洛伊德 饰）于1885年留下的信件，马丁找到了博士研制的时空穿梭机。本以为可以乘坐着这台机器回到未来，马丁却意外发现了博士的墓碑，原来他在留下那封信后不久便被人杀害。为了拯救埃米博士，马丁乘坐时空穿梭机来到了1885年的美国西部。 马丁能否改变历史，拯救博士的生命？二人能否成功回到未来？“回到未来三部曲”完结篇，一起与马丁乘坐时空穿梭机畅游时间。©豆瓣', '迈克尔·J·福克斯', '罗伯特·泽米吉斯', 8.5, 89859, 'tt0099088', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p475893249.jpg', 0.2, 0.8, 12.9, 44.7, 41.4, '0.088051,0.229803,-0.571026,0.432219,0.053424,-0.687964,0.384436,-0.099298,-0.585460,-0.505624,-0.051285,0.759908,-0.130033,-0.010969,0.666207,0.267385,-0.975285,-0.198524,0.115817,-0.386980,-0.452885,-0.597143,-0.225328,-0.366836,0.276937,-0.691584,0.619927,-0.019294,0.268605,0.578416,-0.362438,0.383247,-0.314555,0.007823,-0.310579,0.243130,0.283263,-0.121939,-0.840262,0.376198,-0.007005,-0.095697,0.178241,-0.204412,-0.157561,-0.066593,0.725353,-0.125394,0.134083,0.048842,0.151865,-0.229684,0.067320,-0.434068,-0.053471,0.106513,-0.210220,0.642513,-0.156919,0.111713,0.118342,-0.291880,-0.537664,0.054605,-0.322775,0.123896,-0.322823,0.263259,-0.477045,0.203881,-0.016537,-0.332080,0.280120,0.427417,0.553698,0.405091,-0.229963,0.305312,-0.512862,0.224898,0.476299,-0.301579,-0.123203,0.393676,0.263495,-0.455265,-0.090446,0.199930,-0.498918,0.180493,0.384661,0.217209,-0.132379,0.225174,-0.620487,-0.188831,-0.611981,-0.208639,0.418577,-0.178027,-0.104765,-0.823351,0.037492,0.123796,-0.052849,-0.174349,-0.135301,-0.308766,0.539602,-0.467087,0.661072,0.530414,0.252446,-0.114331,0.977181,-0.203402,0.066208,-0.539435,0.232332,0.382446,-0.013080,0.533837,0.075782,0.212357,0.229830,-0.389569,-0.200539,0.345676', '1293656', '2075345', '1293572', '1291859');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296669', '罗马，不设防的城市', '剧情', '1944年，罗马，被纳粹侵占下伤痕累累的大街。德军肆无忌惮的搜捕着保卫家园的游击队，意大利地下反抗组织领袖、工程师乔治·曼菲蒂（马塞罗·巴格利埃罗 Marcello Pagliero 饰）遭到德军追缉。危急中，曼菲蒂逃往朋友弗朗西斯科家中暂避，在弗朗西斯科的未婚妻碧娜（安娜·玛妮雅妮 Anna Magnani 饰）的帮助下，曼菲蒂见到了唐·彼得罗神父（阿尔多·伯立兹 Aldo Fabrizi 饰），并请神父将一笔巨款交给游击队。弗兰西斯科为了掩护曼菲蒂而被捕，碧娜也中弹身亡。然而绝处逢生的曼菲蒂被女友告密，曼菲蒂和神父被捕入狱。纳粹故意在神父面前严刑拷打曼菲蒂，两人最终在敌人的酷刑和枪弹下英勇牺牲。本片根据塞吉欧·阿米迪的原著改编。©豆瓣', '阿尔多·法布里齐', '罗伯托·罗西里尼', 8.1, 13680, 'tt0038890', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2316008251.jpg', 0.2, 1, 18.8, 55.6, 24.4, '0.222971,-0.104967,-0.446583,0.476420,0.176145,-0.387159,0.592127,0.148992,-0.141727,-0.183795,0.246736,0.604879,0.021401,0.007510,0.511376,-0.007586,-0.428744,-0.786878,-0.186767,0.097987,-0.245373,-0.667238,-0.257016,-0.439499,-0.206544,-0.345422,0.351809,0.206583,0.104432,0.429072,0.404029,0.700147,-0.006990,0.163939,0.111834,0.071834,0.397508,-0.503415,-0.389158,0.349638,0.133049,-0.310724,-0.098132,0.148345,0.080583,0.277806,0.516197,-0.457204,0.296278,-0.258475,0.163436,-0.296462,0.378219,0.223158,0.505307,-0.169174,-0.124953,0.094426,-0.150767,-0.075844,0.201307,0.007321,-0.499430,-0.238680,0.203482,-0.078297,-0.696583,0.181604,-0.299152,0.512174,0.182973,-0.096225,0.239391,0.526651,0.262472,0.126274,-0.123296,0.021872,-0.548386,0.024901,0.338360,-0.061363,-0.088519,-0.461457,-0.367661,-0.409490,0.225362,-0.148147,-0.373978,-0.012210,0.408312,-0.368801,0.143885,0.305924,-0.452850,-0.326313,-0.561280,-0.063942,-0.407925,-0.210486,0.037289,-0.807238,-0.084566,0.014716,-0.112626,0.272192,0.004396,0.129392,0.301651,-0.352852,0.381640,0.641587,0.343775,0.063290,0.283859,0.138613,0.169778,0.054270,-0.313867,0.668809,0.546935,0.266387,0.387660,0.131166,-0.090019,-0.107967,-0.080350,0.177115', '6517421', '1306915', '7916027', '6435936');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296679', '红胡子', '剧情', '刚毕业的医学院学生保本（加山雄三 Yuzo Kayama 饰），在父亲的介绍下，来到穷乡僻壤的小石川诊所实习。他的老师是一位被称作红胡子（三船敏郎 Toshiro Mifune 饰）的古怪医师。起初，向往长崎的保本对这个贫民窟厌恶之极，并迁怒于红胡子，觉得自己受骗上当，无用武之地。红胡子是这里远近闻名的杏林高手，他没有对保本提什么要求，而是默默地行医，不畏权贵，不计酬劳，手下治愈的病人不计其数，其中包括因受虐精神失常的少妇（香川京子 Kyôko Kagawa 饰），因酗酒导致半身麻木的醉汉，因被贩卖至青楼身患性病的雏妓等等。在协助红胡子救死扶伤的过程中，保本逐渐发现了医德的重要，并修正了自己的人生态度……©豆瓣', '三船敏郎', '黑泽明', 8.8, 13801, 'tt0058888', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2215875666.jpg', 0.4, 0.8, 9, 37.2, 52.6, '0.518865,-0.254470,-0.373838,0.159604,-0.331807,-0.315532,0.828739,0.127842,-0.622608,-0.392880,0.457731,0.598960,0.018609,0.185570,0.248742,-0.155119,0.214487,-0.360580,-0.241076,-0.163314,-0.335964,-0.462365,-0.242401,-0.133243,-0.462448,-0.343206,0.415680,0.103368,-0.220479,0.468645,0.198770,0.367555,0.162824,0.140529,-0.220704,-0.031006,-0.066252,-0.190073,-0.131355,0.099049,0.064686,-0.292134,0.043591,0.066186,0.104329,0.639957,0.473281,-0.021159,-0.222435,-0.169103,0.321133,-0.034936,-0.066007,0.116571,0.317284,-0.013382,0.038528,0.016482,-0.168299,-0.009160,-0.048123,0.088809,-0.789906,-0.195903,0.348584,0.444654,-0.503888,0.496025,-0.040338,-0.274330,0.073068,-0.180655,-0.137445,0.055111,-0.028038,0.330010,-0.018369,0.051245,-0.401122,0.464059,0.317200,-0.088450,-0.134990,0.314106,-0.262830,-0.444265,0.223685,-0.316743,-0.351115,-0.035327,-0.018773,0.017361,-0.143332,-0.048312,-0.246866,0.124093,0.002455,-0.155281,-0.025182,0.054496,-0.310793,-0.517864,0.260228,-0.315837,-0.183200,-0.009162,0.337513,-0.097957,0.687522,-0.910586,0.197049,0.503822,0.185904,-0.525132,0.431611,0.124430,0.046527,-0.032524,-0.395316,0.234580,0.274960,0.406717,0.068378,0.257343,-0.124942,-0.281472,-0.094454,0.310055', '1793491', '3263169', '3005387', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296693', '醉拳', '喜剧', '广东武术界名人黄麒英自儿子黄飞鸿（成龙）小时候起就严格训练其习武，可惜黄飞鸿少年时代年轻气盛，经常用三脚猫功夫在外惹事生非，武学上一直无大的长进。直到某次较量中被人打得落花流水且受到侮辱，黄飞鸿才发誓要拜苏乞儿（袁小田）为师好好习武。由于苏乞儿懒于收徒，加上对黄飞鸿的人品很不信任，他开出了种种苛刻条件。为表决心，黄飞鸿一一应允并努力将它们全都实现，终以真心将苏乞儿打动，令其将醉拳传授给了他，黄飞鸿渐从一名莽撞的少年成长为一个见义勇为的年轻人。©豆瓣', '成龙', '袁和平', 7.7, 70449, 'tt0080179', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1387691770.jpg', 0.3, 1.5, 29, 50.8, 18.3, '-0.141621,-0.053089,-0.439159,0.811481,-0.366625,-0.526753,0.190160,-0.325670,-0.384310,-0.416819,0.028470,0.457009,-0.188391,0.194934,0.239794,-0.354074,0.143675,-0.615691,-0.045127,0.095010,-0.140431,-0.497263,0.249103,-0.236895,-0.705813,0.068536,0.303556,0.213697,-0.354856,0.132553,0.179282,-0.191339,0.290743,0.196625,-0.139189,0.037689,-0.402955,0.007895,-0.070478,0.045272,0.290723,-0.408202,-0.054634,0.033982,-0.048789,0.142497,0.451668,-0.205424,-0.226236,-0.312815,0.313056,-0.050049,0.085652,0.049421,0.131838,0.136146,0.098390,0.040403,0.111761,0.234518,-0.125206,-0.344409,-0.306968,0.050902,0.328268,-0.562544,-0.724104,0.273269,0.017444,0.062266,-0.427622,-0.164822,-0.460692,0.037607,0.457082,0.123730,-0.204379,0.247105,-0.235222,0.193596,0.343241,0.012806,-0.029042,0.144982,-0.050504,-0.429788,0.374180,-0.478204,-0.213652,0.014309,0.187636,-0.193958,-0.181616,0.164629,-0.011140,-0.189684,-0.201045,0.118238,-0.097221,-0.140994,0.192378,-0.160690,-0.121256,-0.284958,-0.190532,-0.224272,0.251021,-0.520136,0.984200,-0.783344,0.097394,0.095628,0.014536,-0.524403,0.336186,-0.054752,0.047147,-0.003415,-0.091267,0.262632,0.312558,0.015152,0.291457,0.374503,-0.180727,-0.058103,0.157767,0.397303', '27602116', '26730542', '26593587', '1303010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296697', '人猿星球', '科幻', '一艘出发自二十世纪的宇宙飞船经过6个月的近光速飞行，相当于经历了七百年时间，船长泰勒（查尔登•海斯顿 Charlton Heston 饰）设定自动飞行状态后，飞船最终坠落在公元3978年的一颗陌生星球上。泰勒和两名幸存队员发现该星球与地球环境相当，而且竟然存在没有语言能力靠采集为生的人类，不待泰勒进行进一步的考察，一群具有智能的人猿突然出现将一众人类捕获。原来这颗星球的主人是人猿，人类只不过是供他们捕猎研究的野兽，人猿博士基拉（金•亨特 Kim Hunter 饰）和男友康奈利分别进行着人类行为学和人猿历史的研究，喉部受伤的泰勒暂时失去语言能力，但他的沟通行为很快引起了基拉的注意，在顽固的人猿学术界引发了争议。一直设法争取自由的泰勒不久终于发现了人猿星球的真相……©豆瓣', '查尔顿·赫斯顿', '富兰克林·沙夫纳', 8.2, 34943, 'tt0063442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p915141074.jpg', 0.4, 1.3, 16, 50.6, 31.7, '0.228561,0.068216,-0.678967,0.617774,-0.112908,-0.066750,0.372008,-0.220253,-0.422070,-0.270220,0.093230,0.605237,-0.241456,-0.038668,0.067314,-0.128212,-0.438714,-0.265965,0.082082,-0.210129,-0.579949,-0.578329,-0.474359,-0.355063,0.095498,-0.505953,0.780699,-0.183450,-0.195168,0.392134,-0.346803,0.220347,0.042951,0.319485,-0.163598,-0.228632,0.279670,-0.217090,-0.087413,0.300840,-0.202496,-0.022716,0.230234,-0.034167,-0.078167,0.301580,0.784767,-0.554739,-0.257761,-0.339303,0.285935,-0.101105,0.087436,-0.148341,0.643847,-0.006981,-0.199225,0.056735,-0.030618,0.086545,0.183117,-0.068142,-0.709318,-0.044880,-0.124694,0.159572,-0.302914,0.202100,-0.090341,-0.108098,-0.103182,-0.311063,0.175664,0.693426,0.451536,0.248210,-0.011031,0.039675,-0.316128,-0.006451,0.455074,-0.135497,-0.721808,0.448268,-0.038174,-0.885493,-0.320717,-0.160018,-0.088693,-0.200854,0.170427,0.362786,-0.469437,0.282035,-0.717988,0.133809,-0.241202,-0.478825,-0.008012,-0.148071,-0.161425,-0.782678,-0.116929,-0.548957,-0.207150,-0.107229,0.083786,-0.176097,0.840225,-0.805276,0.181482,0.566160,0.338154,-0.270579,0.602151,-0.436913,0.100541,-0.303225,0.144254,0.271404,0.122335,0.313729,0.045409,0.256327,0.247013,-0.051375,-0.238992,0.408235', '1420088', '25863940', '2369613', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296698', '幻影特攻', '惊悚', '三个一起在孤儿院长大的好友德高（郑伊健 饰）、松鼠（陈小春 饰）、小蓝（陈慧琳 饰）成为了科学家，在美国中央情报局研究“人类潜意识”。他们得到消息称不法分子狂龙打算趁机在世界杯期间恶意把暴力意识传到东南亚，进一步引发金融风暴。德高与松鼠、小蓝这几名出色的科学家成为了狂龙的目标。在松鼠结婚当天，他们杀死了松鼠的妻子，挟持了小蓝离开。德高与松鼠决心要报复与拯救小蓝，所以自愿接受了科学院里的潜意识训练，想通过训练成为杰出的打手。可是在他们成功救出小蓝的时候，松鼠的意识发生了变异，错手杀死了德高的爱人小蓝。从此松鼠与德高各走各路，但对爱人逝世无法释怀的德高决定为女友报仇，一定要找到松鼠。©豆瓣', '郑伊健', '马楚成', 5.9, 5853, 'tt0181582', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p967686414.jpg', 3.8, 20.2, 59.6, 12.6, 3.9, '0.100604,0.199780,-0.489692,0.536587,0.022306,-0.052488,0.428266,-0.004186,-0.371733,-0.199017,-0.090924,0.704085,-0.029300,0.250925,0.137549,-0.223597,0.041655,-0.734409,0.068155,0.060154,-0.251464,-0.601582,-0.176544,-0.337145,0.056557,-0.420437,0.852685,0.143208,-0.205015,0.558995,0.332809,0.195771,-0.237944,0.161395,-0.214936,0.013494,0.238858,-0.083836,-0.421330,0.339695,0.013954,-0.062853,0.142944,0.181200,0.070439,0.093707,0.509843,-0.364448,-0.226350,-0.283243,0.274129,-0.331136,-0.036844,0.315416,0.485451,-0.074839,0.054957,0.272435,-0.021055,0.252917,-0.028296,-0.101785,-0.727752,-0.131006,-0.001781,0.169032,-0.775683,0.083740,-0.053863,0.255151,0.309965,-0.152202,0.150442,0.417160,-0.044174,0.343234,-0.147839,0.406589,-0.645499,0.007669,0.818463,-0.414637,0.196330,0.110250,0.288748,-0.489944,-0.054910,-0.101802,0.018598,-0.046280,0.363653,0.197228,-0.634495,0.050423,-0.552140,-0.286444,-0.300154,-0.132636,0.254683,-0.383097,0.094560,-0.364023,-0.087174,-0.263644,-0.313421,-0.018811,-0.023062,-0.503872,0.864569,-1.046349,0.270447,0.630013,0.312311,-0.681715,0.766330,0.005642,0.153647,-0.427617,0.220498,0.123885,0.109871,0.125900,0.295745,0.044149,0.088638,-0.232250,-0.379130,0.106067', '35030151', '30345227', '35048413', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296702', '星际旅行10：复仇女神', '动作', '企业号宇宙飞船遨游在太空，在人类和外星人中间传播好意，同时也在防范敌对星球有可能的攻击行为，因为有迹象表明，星际联盟的老对头罗木兰星球有可能发起新一轮的攻击。皮卡特船长和他的船员们也在小心翼翼的观察着事态的进展，时刻准备投入战斗。可就在这时，罗木兰星球发出了和谈的讯息，星际联盟命令企业号前往谈判，当皮卡特船长第一次见到罗木兰星球新的执政官后惊呆了，原来对方就是罗木兰很久以前制造的皮卡特的人类复制品，面对这个难缠的对手，皮卡特船长和他的船员们该如何是好？', '帕特里克·斯图尔特', '斯图尔特·贝尔德', 7, 7723, 'tt0253754', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2209409030.jpg', 1, 5.9, 45.7, 34.6, 12.8, '-0.077336,0.214523,-1.015026,0.647787,-0.064213,-0.148521,0.417477,0.220272,-0.277258,0.088947,0.176872,0.641509,-0.125741,-0.083681,0.293730,-0.110756,-0.451969,-0.415765,-0.243179,-0.161735,-0.737372,-0.471096,-0.256495,-0.708313,0.099525,-0.505055,0.512483,0.108976,-0.511545,0.088060,0.427233,0.279195,-0.072970,0.843331,-0.076824,-0.172112,0.353126,-0.046789,-0.391822,0.141633,-0.255501,0.150504,0.076405,0.214803,0.302443,0.473802,0.490435,-0.543802,0.097502,-0.100117,0.032021,-0.224695,0.468417,-0.118913,0.879007,-0.181783,-0.393707,-0.139614,0.185291,0.031538,-0.022123,0.064699,-0.837897,0.063299,0.080019,0.381681,-0.428074,0.232953,-0.130787,0.289723,-0.204205,-0.213903,0.238240,0.888847,0.328489,0.069872,0.112346,0.335470,-0.584225,-0.114502,0.536636,0.221271,-0.486824,-0.010186,-0.196784,-0.498385,-0.310866,-0.191180,-0.277781,-0.322988,0.588671,-0.061449,-0.067692,0.450347,-0.783633,0.014345,-0.062191,-0.524548,-0.013936,-0.315499,-0.106834,-0.932058,0.145704,-0.468604,-0.236714,0.323079,0.037711,-0.017477,0.952792,-0.935389,0.178949,0.585800,0.522650,-0.450677,0.615524,0.277008,-0.052926,-0.508851,-0.072222,0.260846,0.169542,0.499255,0.283758,0.164043,0.229077,-0.079766,-0.155059,0.348137', '2042279', '1300089', '7054604', '1303447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296703', '楢山节考', '剧情', '信浓有一座楢山，附近山村的人到了七十岁就得进楢山。树桩家六十九岁的阿玲（坂本澄子 饰）还有三件事放不下：一是四十五岁的长子辰平（绪形拳 饰）去年成了鳏夫；二是二十岁的长孙袈裟吉（仓崎青儿 饰）总是在村里人面前嘲笑自己牢固的牙齿；三是三十五岁的次子利助（左顿平 饰）还未与女人性交过。一年一度的祭祀日，等来了新儿媳阿玉（竹城明 饰）的阿玲狠下心在石臼上磕掉了两颗门牙。割稻子的时节，袈裟吉将雨屋家的阿松（高田顺子 饰）领进了树桩家，可是阿松却将树桩家的粮食偷运至雨屋家。辰平抓住了阿松，但并未张扬，只是私下教训了事。可是雨屋家世代偷盗，终于引发众怒。村里人不仅抄了雨屋家，为绝后患，还将雨屋全家活埋，阿松也不例外。阿玲打定主意冬天进楢山，但是利助的事该拜托谁呢……©豆瓣', '绪形拳', '今村昌平', 9, 52290, 'tt0084390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p981755735.jpg', 0.3, 0.6, 6.8, 33, 59.3, '0.035648,0.025536,-0.426094,0.107891,-0.016222,-0.574874,0.155297,0.457649,-0.191658,-0.179033,0.132394,0.195408,-0.147693,0.260903,-0.112822,0.343566,-0.082709,-0.306185,0.071179,-0.141656,-0.583176,-0.150414,0.252239,-0.045944,-0.173922,0.038769,0.307607,0.148564,0.012387,0.071017,0.236871,0.090004,0.187148,0.206826,-0.485017,0.231575,-0.189538,0.119162,0.048443,0.101943,-0.335950,-0.353008,-0.214012,0.112557,0.348520,0.547910,0.617588,-0.295603,-0.161852,-0.070611,0.048290,-0.044106,-0.125378,0.396055,0.626178,-0.191742,0.137713,0.300361,-0.292823,-0.057170,0.261021,-0.151531,-0.016815,-0.006331,0.247556,-0.071961,-0.690199,0.525021,0.051291,-0.082289,-0.199114,-0.397122,0.346188,0.083647,-0.119465,0.338722,-0.436086,-0.097260,-0.529678,0.231992,0.419467,-0.241661,0.304220,0.193111,0.072974,-0.331355,-0.047297,-0.219027,-0.180970,0.046617,0.276279,-0.135230,-0.362324,0.052837,-0.402961,-0.258546,-0.333693,0.094319,0.121886,-0.176048,-0.230382,0.024503,0.083934,-0.352620,-0.345545,0.364022,0.404997,0.027293,0.428292,-0.260774,0.283114,0.315998,0.091960,-0.026218,0.281043,-0.074830,0.063791,-0.031964,-0.107486,-0.280773,0.055468,0.235719,0.305932,0.350005,-0.096393,-0.384738,-0.020324,0.193639', '1294737', '1306505', '1432825', '1308607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296705', '终极密码战', '剧情', '阿特（布鲁斯·威利斯 Bruce Willis 饰）是一名FBI探员，不幸的是，他出色的工作能力和特立独行的个性非但没有赢得上司的认可，反而让他惨遭降职的命运。在一次行动中，阿特的任务是找到一个名为西蒙（米克·休吉斯 Miko Hughes 饰）的九岁男孩，然而，一帮凶残的杀手赶在阿特之前来到了西蒙家，他们残忍杀害了西蒙的父母，男孩则因为躲在衣柜里而逃过了一劫。原来，西蒙年纪虽小，却在数学上颇有建树，偶然之中，他竟然破译了美国军方的情报密码，这也为他引来了杀生之祸。阿特救出了西蒙，但危险却没有因此而放过两人，在接连不断的追杀之中，阿特能够顺利将西蒙带离险境吗？©豆瓣', '布鲁斯·威利斯', '哈罗德·贝克尔', 6.7, 5377, 'tt0120749', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2630846271.jpg', 1.3, 7.4, 54.6, 29.4, 7.3, '0.295414,0.205892,-0.654836,0.798987,-0.430624,-0.321890,0.800666,0.069100,-0.587847,-0.178121,0.365149,0.770606,0.205435,-0.142530,0.111971,0.152342,-0.159219,-0.481316,0.172612,-0.252247,-0.342752,-0.679820,-0.676199,-0.330079,-0.124194,-0.558939,0.532829,0.000027,-0.061643,0.582646,0.228174,0.105037,-0.023053,0.638098,-0.273773,0.062436,0.452757,-0.054142,-0.005267,0.464133,0.020131,-0.461398,-0.113306,0.380908,0.064685,0.697126,0.583999,-0.359437,-0.247699,-0.035722,0.375683,-0.430072,-0.108547,0.290249,0.314251,-0.235943,0.321571,0.323903,-0.195335,0.097701,0.038420,0.178524,-0.938435,-0.039444,0.092682,0.180943,-0.655994,0.521515,-0.219472,-0.205511,0.017238,-0.313773,0.201539,0.361861,0.310413,0.195922,-0.189574,0.072609,-0.628493,-0.214679,0.789444,-0.267195,-0.197667,0.309433,-0.213909,-0.528166,0.032953,-0.454547,-0.476406,0.083042,0.513540,-0.137184,-0.186368,0.329493,-0.305617,-0.109857,-0.523019,0.015506,-0.419235,-0.345062,-0.140052,-0.308384,-0.031235,-0.479848,-0.766513,0.160147,-0.095562,-0.365933,0.686415,-0.924046,0.262113,0.719337,0.221857,-0.360666,0.750323,0.377443,0.320612,0.156211,-0.149224,0.203031,0.121365,0.335865,0.125211,0.463343,0.065853,-0.519281,-0.235006,0.446207', '3785918', '1793491', '25932086', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296717', '夺宝奇兵', '动作', '二战期间，希特勒在世界各地召集考古学家寻找“失落的约柜”——圣经中引导希伯来人与上帝交流的圣物，希特勒欲借其来护佑纳粹的战争。为了使希特勒的计划破灭，印第安纳琼斯博士（Harrison Ford饰）奔赴尼泊尔，一边奋力挖掘蛛丝马迹，一边还要与无孔不入的纳粹分子周旋。凭借着过人的智慧和异于常人的胆量及大无畏的勇气，琼斯终于在罗马找到了指示约柜位置的太阳手杖，继而发现了约柜。就在大功告成之际，纳粹军却侵吞了胜利果实，还将琼斯等人留在了蛇穴里！但是无往不胜的琼斯总是有办法死里逃生，并狠狠地还以颜色！©豆瓣', '哈里森·福特', '史蒂文·斯皮尔伯格', 7.9, 87232, 'tt0082971', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p735571282.jpg', 0.4, 1.8, 23.5, 50.8, 23.5, '-0.099083,0.072016,-0.592747,0.629746,0.044855,-0.370126,0.501162,0.056153,-0.415280,-0.003731,-0.036620,0.443185,-0.045682,-0.042487,0.206853,-0.083483,-0.676863,-0.925658,0.004501,0.072437,-0.305277,-0.459447,-0.486887,-0.245729,-0.024711,-0.437361,0.419444,0.113484,-0.238013,0.280093,0.060416,0.124826,-0.000600,0.565645,-0.275506,-0.269762,-0.019478,-0.170233,-0.375805,0.173427,0.230476,-0.440681,-0.249417,0.306748,-0.054889,0.363226,0.501819,-0.603097,0.309200,-0.133994,-0.050865,-0.135794,-0.026226,0.299181,0.256652,0.189454,-0.031338,0.291459,0.090650,0.226784,0.283793,-0.093144,-0.720669,-0.268523,-0.011296,0.134071,-0.502511,0.287782,0.037632,0.169056,0.204282,-0.339261,0.095332,0.227120,0.092108,0.278982,-0.127663,-0.360131,-0.567870,0.038396,0.132935,-0.279291,0.045836,0.093749,0.030451,-0.537350,0.016049,0.159657,0.042134,-0.413088,0.514172,0.053812,-0.016321,0.239781,-0.898784,0.069895,-0.404995,-0.070824,-0.012834,-0.376413,0.125800,-0.825702,-0.027856,-0.061011,0.073401,0.363668,0.187447,-0.049063,0.664531,-0.466292,0.175491,0.702113,0.215051,-0.325268,0.463500,-0.015350,-0.097166,-0.215089,-0.220171,0.408690,0.064172,0.512015,0.038821,0.254976,0.087173,-0.189578,-0.344073,0.309209', '20274039', '1307442', '6984051', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296718', '浅坟', '惊悚', '亚历克斯（伊万•麦克格雷格 Ewan McGregor 饰）、大卫（克里斯托弗•埃克莱斯顿 Christopher Eccleston 饰）和朱丽叶（凯瑞•福克斯 Kerry Fox 饰）三个好友合住在一户公寓内，三人征集新房客时问出各种怪异问题，玩的不亦乐乎，最后在朱丽叶主张下，吸纳了写作的单身男子雨果，岂料雨果入住不久就身亡在屋内，惊慌的三人发现了雨果装有巨额现金的箱子，金钱诱惑难以抵御，他们悄悄将雨果分尸掩埋。巨款在手的亚历克斯和朱丽叶春风得意，但会计员大卫却终日忧心忡忡，终于大卫在二人挥霍钱财后暴发，将钱箱搬到阁楼收藏看管。与此同时，两名匪徒为了寻找钱箱，一路大开杀戒，并闯入了三人的公寓，大卫突然发力将匪徒杀死，此时的大卫，已经愈发神经质，将事情引向了更加危险的方向……©豆瓣', '凯瑞·福克斯', '丹尼·博伊尔', 7.7, 10444, 'tt0111149', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1259486024.jpg', 0.5, 2.3, 26.2, 53.1, 17.9, '0.372312,-0.074049,-0.482143,0.058471,0.004193,-0.493414,0.994904,0.299252,-0.376450,-0.071506,0.385807,0.626038,-0.288349,0.057798,0.319588,0.012704,-0.457156,-0.554843,-0.112727,-0.265887,-0.279876,-0.517832,-0.095516,-0.347941,-0.020401,-0.321177,0.281757,-0.066361,-0.085652,0.564156,0.305457,0.342755,-0.450195,0.646340,-0.004844,0.189541,0.451000,-0.223806,-0.196020,0.319501,-0.183140,-0.297159,-0.344166,0.146182,0.108757,0.419366,0.683662,-0.232510,-0.068568,0.242171,-0.001181,0.053933,-0.165788,0.162698,0.104513,0.061019,0.060372,0.031279,-0.444470,0.088388,0.210324,-0.042075,-0.458687,0.132920,-0.138782,0.096016,-0.611819,0.283570,-0.076871,0.082277,0.151244,-0.323865,0.029412,0.250483,0.094243,0.183198,-0.078846,-0.158029,-0.509119,0.092360,0.037526,-0.295646,0.057209,0.329674,-0.035468,-0.192868,-0.090793,0.271752,-0.378105,-0.446024,0.867318,0.270685,0.060876,0.070850,-0.599590,-0.096825,-0.296340,-0.185715,-0.125750,-0.280814,-0.239775,-0.860871,-0.103402,0.108401,-0.202851,0.070687,0.156649,0.085547,0.461335,-0.314377,0.135827,0.405387,0.279365,-0.010365,0.335784,-0.374341,0.142056,-0.084582,-0.276232,0.109961,0.362926,0.433778,0.470225,0.432550,-0.364464,-0.230359,-0.446188,0.460133', '1316693', '10466639', '1306670', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296720', '变蝇人2', '科幻', '这部拍摄于1989年版的《变蝇人2》是1986年版《变蝇人》的续集，影片承接第一集母亲维尼卡怀上赛斯孩子的伏笔，当她产下一枚蝇蛹时被当场吓死。当局的科研机关巴托工业园收养了苍蝇之子马丁·布朗多（艾瑞克·斯托罗兹 Eric Stoltz饰），由巴托工业的老总巴托先生（约翰·盖兹 John Getz饰）抚养。巴托先生密切监视着马丁的一举一动，表面上把马丁视如己出，实则却把他当作研究对象，暗地里用摄像机记录下他所有的生活过程，让马丁研究他父亲生前的时空传送装置。马丁看上去英俊帅气，无异于常人，除了的惊人的生长速度和超人的天资才能。不久，马丁就与美丽的贝斯·洛根（达芙妮·祖尼加 Daphne Zuniga饰）坠入爱河。可隐藏在马丁体内的变异染色体突然苏醒，等待马丁的是变成下一个“苍蝇人”的恐怖噩耗。©豆瓣', '艾瑞克·斯托罗兹 Eric Stoltz', 'Chris Walas', 6.3, 5167, 'tt0097368', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1813903680.jpg', 2.5, 15, 55.7, 19.9, 6.9, '0.079970,-0.019570,-0.621066,0.601090,-0.363787,-0.255974,0.713666,0.265360,-0.468729,-0.203409,0.246123,0.835401,-0.334869,-0.055339,0.067805,0.327499,-0.508019,-0.434806,-0.302147,0.196223,-0.112878,-0.409565,-0.501803,-0.279840,0.057584,-0.462305,0.506673,-0.042233,0.037667,0.074202,-0.123863,0.410083,-0.129944,0.036697,-0.248963,0.148334,0.027662,-0.349443,-0.125784,0.172497,0.042014,-0.008325,0.019881,-0.050097,0.039965,0.150408,0.496952,-0.082206,0.023233,-0.161331,0.274204,-0.192053,-0.005466,0.048864,0.098252,-0.039939,0.219331,0.248113,-0.212332,0.013562,0.207999,-0.227415,-0.821426,0.008699,0.025090,0.207736,-0.425776,0.152471,-0.410506,0.225816,0.117964,-0.239225,0.038562,-0.086199,0.133125,0.487481,-0.028884,0.087137,-0.367623,0.083467,0.256531,-0.060680,-0.536191,0.156279,-0.183788,-0.372551,-0.160330,-0.139421,-0.418578,0.082834,0.500101,0.042254,-0.137330,0.334705,-0.519493,-0.100901,-0.478444,-0.164524,-0.179653,-0.262723,-0.146726,-0.762338,-0.070417,-0.295502,-0.335148,-0.147938,0.176604,-0.236849,0.757618,-0.360915,0.426715,0.513667,0.024041,-0.209041,0.485033,-0.098543,0.122406,-0.203468,-0.200715,0.235501,0.168941,0.189054,0.088782,0.472214,0.096749,-0.202410,-0.427076,0.577902', '3318306', '1293433', '259