INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296736', '钢琴家', '剧情', '史标曼（艾德里安•布洛迪 Adrien Brody 饰）是波兰一家电台的钢琴师。二战即将爆发之时，他们全家被迫被赶进华沙的犹太区。在战争的颠沛流离中，家人和亲戚最终被纳粹杀害，而史标曼本人也受尽种种羞辱和折磨，他侥幸得到一位朋友的帮助，暂时有了藏身之处。战争愈加猛烈，朋友不得不抛下他回老家寻得安全的住所养育儿女。此时史标曼恶病缠身，却还要在搜捕中逃亡。在废墟的阁楼上他遇见了一名德国军官，在军官的要求下他弹奏了钢琴曲。美妙的琴声令德国军官萌发了恻隐之心，他暗暗帮助史标曼直到苏军对波兰的解放到来…… 影片根据波兰钢琴家瓦拉迪斯罗•斯皮曼(Wladyslaw Szpilman)的自传体小说《死亡城市》改编。©豆瓣', '艾德里安·布洛迪', '罗曼·波兰斯基', 9.3, 572997, 'tt0253474', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p792376093.jpg', 0.1, 0.2, 4, 28.1, 67.6, '0.112257,-0.136556,-0.708403,0.569014,0.207527,-0.267885,0.690831,0.057737,-0.548464,-0.063795,0.319084,0.851228,-0.085160,0.210468,0.201535,-0.148241,-0.383147,-0.698639,-0.177975,0.019916,-0.236278,-0.384657,-0.213254,-0.359566,-0.168812,-0.461077,0.686725,0.468086,-0.274494,0.285719,0.229866,0.492962,-0.011324,0.396965,-0.192770,0.118848,0.306745,-0.211911,-0.332872,0.265191,-0.031294,-0.491624,-0.175580,0.250346,-0.043620,0.399217,0.830023,-0.096653,0.105447,-0.193945,0.294726,-0.244315,0.202095,0.099692,0.266051,-0.022674,0.119738,0.141768,-0.167855,0.045179,-0.166464,-0.117741,-0.459518,-0.180460,0.209445,-0.041785,-0.638709,0.368586,-0.100328,0.309785,0.133796,-0.011142,0.339664,0.472872,0.118804,0.358899,-0.198355,0.023655,-0.484867,0.407195,0.824551,-0.123732,-0.214860,0.073757,-0.461243,-0.473880,0.131130,-0.334687,-0.622614,-0.120458,0.457713,-0.094455,-0.116144,0.296559,-0.490913,-0.182528,-0.342115,-0.275736,-0.034754,-0.257313,0.043127,-0.715953,-0.177169,-0.186510,-0.166774,0.235625,0.062954,-0.026872,0.823479,-0.687139,0.389148,0.543251,0.348016,-0.299811,0.523970,0.131443,0.200389,0.060351,0.141211,0.603624,0.042778,0.410967,0.187688,0.086664,-0.077168,-0.127516,-0.336578,0.413028', '3811356', '30162520', '25721544', '3158990');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296747', '抢钱夫妻', '喜剧', '资深电视报道员蒋有为（许冠文）被医生诊断患肠癌，并且只能活3个月。电视台老板得知他的病情，本想炒他就鱼，后来又利用他提高节目收视率。蒋有为为了家人今后有生活保障，隐瞒病情拼命赚钱，一番拼搏使他既赚了钱又赢得公众信赖。长女阿诗（陈少霞）得知真相告诉家人，家人忧心忡忡。终于，蒋有为在一次新闻报道时揭露了电视台的骗局，告诫大众不要轻信媒体。他本人的肠癌切除术最终失败。', '许冠文', '张之亮', 8.2, 7686, 'tt0106551', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2027457540.jpg', 0.4, 1.6, 17.7, 46.8, 33.5, '-0.464464,-0.090364,-0.004088,0.430555,-0.017759,-0.291302,0.179518,0.205035,-0.450604,-0.167403,0.325060,0.444650,-0.257262,0.124226,-0.001778,-0.313925,-0.356730,-0.399506,0.552129,0.122545,0.095669,-0.360815,0.006846,-0.429815,-0.086315,-0.107864,0.541279,0.027263,-0.193482,-0.196287,0.111157,0.092807,0.401256,0.267673,0.338253,0.015197,0.060259,-0.080641,-0.604604,0.370351,0.322555,-0.396977,-0.216448,0.297567,0.204823,0.220392,0.483564,0.151615,-0.481093,-0.198839,0.773502,-0.166904,0.117107,-0.173532,0.305436,0.212961,0.449047,0.509414,-0.384219,-0.147764,-0.277649,0.265859,-0.613598,-0.164503,0.381626,-0.005690,-0.308598,0.229982,-0.376851,0.264751,-0.085776,-0.072024,0.039777,0.594927,0.389167,0.126535,-0.185576,0.260681,-0.259347,0.463906,0.599900,-0.052118,0.136384,0.107106,-0.157657,-0.197745,0.583949,-0.412051,-0.457215,0.298387,0.047762,-0.022582,-0.470470,0.400830,0.274687,-0.245875,-0.375314,-0.373688,0.371806,-0.220968,0.019590,-0.436238,-0.188028,0.214130,0.093182,-0.355196,0.167959,-0.621366,0.679057,-0.460190,0.131341,0.549997,0.100507,-1.009755,0.528739,0.273239,0.128134,-0.422177,-0.059384,0.021797,0.033054,0.331258,0.051076,-0.368789,0.267087,-0.292587,0.061535,-0.044724', '1484760', '26678784', '1421278', '3412882');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296753', '卡萨布兰卡', '剧情', '二战期间，卡萨布兰卡是欧洲逃往美国的必经之地，那里鱼龙混杂，局势紧张。里克（亨佛莱•鲍嘉 Humphrey Bogart 饰）是一个神秘的商人，他在卡萨布兰卡开了一家人气很旺的夜总会，并拥有两张宝贵的通行证。一天，反纳粹人士维克多和妻子伊尔莎（英格丽•褒曼 Ingrid Bergman 饰）来到夜总会，原来他们正在逃避纳粹的追捕。碰巧的是，里克发现，伊尔莎竟然是他的旧日情人。那段爱曾经刻骨铭心，却因为一个误会而终止。而当误会消解时，伊尔莎和里克的感情还是不可避免的重燃了。里克手上的两张通行证能帮助维克多度过难关，但这样一来，伊尔莎是决定留下，还是离去，他们的爱情在政治和伦理的推波逐流中走向何方。©豆瓣', '亨弗莱·鲍嘉', '迈克尔·柯蒂兹', 8.7, 209380, 'tt0034583', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247003945.jpg', 0.1, 0.7, 11.4, 41.1, 46.8, '0.574377,0.082837,-0.534401,0.530485,-0.108480,-0.307663,0.706140,0.084884,-0.415731,-0.200901,0.321098,0.979396,-0.010618,0.228338,0.253081,0.405284,-0.532406,-0.676129,0.140816,-0.249369,-0.120561,-0.774599,-0.318506,0.111078,-0.128586,-0.261096,0.628696,0.155610,-0.112987,0.463404,0.515896,0.482887,-0.152377,0.371883,0.041350,-0.174270,0.233359,-0.183887,-0.302870,0.183366,0.136025,-0.206978,-0.229712,0.407545,0.117337,0.423590,0.321242,-0.264307,0.098666,0.163034,0.230825,-0.419286,0.051781,0.140361,-0.061097,-0.228764,0.195444,0.133999,-0.246167,0.045295,0.008412,-0.035761,-0.648207,0.014124,0.010023,0.362667,-0.457590,0.446615,-0.172788,-0.224519,0.166371,-0.363681,0.150310,0.606411,0.388063,0.351614,-0.271380,-0.116456,-0.531865,-0.083779,0.847820,-0.078153,-0.295846,0.327313,-0.342671,-0.203396,-0.095746,0.091325,-0.464298,-0.088148,0.495136,-0.107959,-0.099827,0.382065,-0.747779,0.024601,-0.387334,-0.100046,0.219671,-0.247358,-0.044614,-0.601682,-0.154204,-0.537136,-0.486867,-0.064942,0.036239,-0.351282,0.583451,-0.812121,0.143913,0.664520,0.284546,-0.354716,0.597491,0.171232,-0.072492,0.004434,-0.086197,0.658416,0.257603,0.217229,0.140587,0.081723,0.091722,-0.231670,-0.236802,0.389321', '30162520', '25721544', '1303036', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296757', '随心所欲', '剧情', '影片讲述了女主人公娜娜（安娜·卡里娜 Anna Karina饰）如何从一名普通售货员走上卖淫道路的悲情一生。娜娜厌倦了售货员的生活，想要成为一名演员，可命运却让她陷入了出卖肉体的色情深渊。她越是深入生命的深刻意义，越是怀疑生活的本来面目。命运辗转，就在她终于遇见她的爱人 时，命运又再一次跟她开了场玩笑，死在了皮条客的枪下。看似凌乱毫无关联的章节，充满哲理如呓语般的台词，为了“拯救灵魂而出卖肉体”么？影片抛掷给我们的又岂止是这一个问题。©豆瓣', '安娜·卡里娜', '让-吕克·戈达尔', 8.5, 17628, 'tt0056663', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199277617.jpg', 0.3, 1, 12, 47.4, 39.2, '0.083165,0.230093,-0.191472,0.678617,-0.178500,-0.378124,0.955119,0.120326,-0.144820,0.037688,0.277560,0.779306,-0.025920,0.071547,0.123925,0.127918,-0.313299,-0.736907,0.198500,-0.001850,-0.300656,-0.258876,0.019776,-0.023809,0.153252,-0.407010,0.754233,0.142910,-0.513090,0.057550,0.186738,0.209002,-0.078820,0.414447,-0.173094,0.159309,0.139203,0.111079,-0.223335,0.093547,0.034255,-0.228021,-0.110660,0.318637,-0.479783,0.099864,0.815196,-0.215713,-0.287147,0.023544,0.604546,-0.263411,-0.114771,-0.079575,-0.058344,-0.021286,0.072122,0.209609,-0.090504,0.138408,0.343359,0.073798,-1.083677,-0.109794,-0.160094,0.060995,-0.517015,0.337749,0.094898,0.128234,0.117639,-0.144198,0.067493,0.051130,0.513479,0.325265,-0.477944,-0.197674,-0.485655,0.449832,0.692254,0.173962,-0.270019,0.763173,-0.255119,-0.453081,-0.156293,-0.166431,-0.600906,-0.036118,0.325956,0.196807,-0.657005,0.368753,-0.671932,0.032519,-0.307694,-0.185959,-0.190042,-0.677260,-0.131188,-0.246755,-0.408920,-0.316435,-0.187283,-0.084382,0.122484,-0.298005,0.702769,-0.622196,0.276380,0.749322,0.029085,-0.616446,0.565460,0.439583,-0.178928,-0.138989,0.076653,0.524901,-0.104640,0.310112,0.159068,0.246596,-0.113472,0.223899,-0.367547,0.800763', '35360296', '30368448', '30279170', '4820775');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296769', '巴尔扎克与小裁缝', '剧情', '七十年代的中国，知青罗明（陈坤 饰）和马剑铃（刘烨 饰）上山下乡来到湘西的一个小山村，接受贫下中农再教育，可是乡下贫乏的生活使他们逐渐感到厌倦。他们与村子里的小裁缝（周迅 饰）相遇，活泼开朗的小裁缝给他们死水般的生活带来了光亮。而他们也发现了一箱所谓的“禁书”，此后，他们生活 中惟一的乐趣便是偷看箱子里的一本本书——巴尔扎克的小说。禁书令少年与小裁缝幻想中的世界豁然开朗，慢慢地两人同时爱上了小裁缝，他们的爱情之火越烧越炽热...©豆瓣', '周迅', '戴思杰', 8, 44765, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1119158729.jpg', 0.3, 1.8, 21.8, 51.6, 24.5, '0.495684,-0.155157,-0.465039,0.684640,-0.149665,-0.288750,0.866727,0.068803,-0.555989,-0.231800,0.119529,0.918972,-0.116950,0.438254,0.099328,-0.010869,-0.383267,-0.791539,-0.209244,-0.433121,-0.182353,-0.092939,-0.328791,-0.312891,-0.217170,0.037013,0.720477,0.251149,-0.190058,0.434756,0.001659,-0.091823,-0.100803,0.196122,-0.167854,0.032444,-0.152741,0.101411,-0.230272,-0.103179,0.006656,-0.021603,-0.049604,0.016393,0.203807,0.011599,0.997042,-0.382261,-0.089837,-0.307525,0.255764,0.055406,-0.377996,0.034904,-0.110788,0.337585,0.367903,-0.073295,-0.079134,-0.055616,-0.085174,-0.225155,-0.279010,0.245507,0.116795,0.192086,-0.495481,0.305736,0.276049,-0.400015,0.127126,-0.403614,0.274491,-0.186012,0.524906,0.590306,-0.309828,-0.175879,-0.173068,0.571009,0.232967,-0.152370,-0.223848,0.384695,-0.351471,-0.327852,0.238125,0.128506,-0.485586,-0.063134,0.191372,0.007396,-0.330213,0.451667,-1.053627,0.204547,-0.167883,-0.306700,0.038383,-0.319483,-0.285868,-0.650917,-0.262964,-0.337304,-0.111323,0.164366,0.282972,-0.246632,0.913199,-0.546758,0.258363,0.197144,0.292499,-0.193186,0.673425,-0.227097,0.168732,-0.046869,-0.062372,0.253102,-0.245739,0.422615,0.112324,0.451352,-0.447009,0.022429,-0.358805,0.594198', '1467779', '26290398', '1307146', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296770', '修女也疯狂2', '喜剧', '本片为1992年《修女也疯狂》的续集。狄乐丝（乌比·戈德堡 Whoopi Goldberg 饰）已经正成为了拉斯韦加斯的知名歌手，而在上集中与她同患难共欢乐的修女们也被调至一个社区学校服务。但是，这个社区学校的孩子们是个大麻烦。顽皮的他们与遵守规范的传统修女们简直是水火不容。不是无视修女们打瞌睡，就是醒来捣乱破坏了，令修女们颇为头疼。无可奈何的修女们只好请狄乐丝再度出山来管教这帮孩子。孩子们见到狄乐丝自然不服气，他们无视她，更想出各种鬼点子捉弄她。但是，很快学生们就领教了狄乐丝厉害。无论他们对她做了什么，最后凡狄乐丝总能“以其人之道还治其人之身”。这样一来，大家都对狄乐丝的管教服帖起来，就连最顽皮的孩子认识到她的厉害。孩子们第一次有目标地参加一次大赛时，但是这下，狄乐丝身份又成了问题……©豆瓣', '乌比·戈德堡', '比尔·杜克', 7.4, 20312, 'tt0108147', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1505799489.jpg', 0.5, 3.6, 37.2, 43.4, 15.2, '0.548938,-0.138475,-0.452388,0.237709,-0.290634,-0.190196,0.522908,-0.237920,-0.474959,-0.136814,0.009664,0.745450,-0.303188,0.470922,0.156397,-0.039409,-0.221540,-0.643814,-0.130773,-0.058449,-0.252586,-0.298496,0.033347,-0.277559,-0.228825,-0.191066,0.233220,-0.047689,-0.099497,0.348548,0.550515,0.241957,0.199401,0.262950,-0.335462,-0.147079,0.031279,-0.000331,0.174666,-0.125675,-0.065665,-0.075510,-0.563302,0.193493,0.316734,0.246939,0.520413,-0.288988,-0.255486,-0.155876,0.316234,-0.343410,-0.093096,0.377231,0.215556,-0.101989,0.302267,-0.008821,0.084939,0.281174,-0.075694,-0.103048,-0.767130,0.292236,0.212223,-0.228344,-0.667722,0.273783,0.281014,-0.294001,-0.059249,-0.335382,0.170844,0.193561,-0.041575,0.417696,-0.273532,-0.052875,-0.416374,0.023339,0.727879,0.111754,-0.327098,0.134613,-0.250624,-0.349371,0.107657,-0.498038,-0.347073,-0.017552,0.121101,-0.105408,-0.153757,0.053590,-0.533680,-0.116349,-0.153023,-0.453059,-0.077221,-0.392496,0.056680,-0.561152,0.124322,-0.344272,-0.459425,0.083661,0.076046,-0.168095,1.202450,-0.871710,0.134745,0.498120,0.078229,-0.863442,0.816842,0.338832,0.169791,0.036646,-0.243458,-0.182488,0.141103,0.095784,0.219259,0.578588,0.014393,-0.316744,-0.138000,0.355409', '24284209', '27602116', '1877596', '1304034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296778', '一树梨花压海棠', '剧情', '大学教授韩拔（杰里米•艾恩斯 饰）年幼时经历了失去初恋女友之痛后，自此他对未成年少女有特殊的感情。一次他到了美国去，成为了寡妇夏洛特（梅勒尼•格利菲恩 饰）的房客，当他看到夏洛特年仅14岁的女儿洛丽塔（多米尼克•斯温 饰）时，他疯狂爱上了这个美丽的少女。事实上，夏洛特希望可以跟韩拔结婚，让自己与女儿都能有个依靠。同时为了能让自己能够留在洛丽塔身边，韩拔还是跟夏洛特结婚了。不久，夏洛特知道了丈夫对自己女儿的迷恋，愤怒出走时遇车祸身亡了。韩拔把在身在夏令营的洛丽塔接到身边，瞒着母亲去世的消息与她游历美国，而他们也展开了一段不伦恋。面对小妖女洛丽塔，韩拔百般顺从，但洛丽塔还是厌倦了他，密谋逃走……©豆瓣', '杰瑞米·艾恩斯', '阿德里安·莱恩', 8.2, 215230, 'tt0119558', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p571119308.jpg', 0.5, 1.5, 17.3, 47.5, 33.3, '0.195148,0.070443,-0.807735,0.386596,-0.312517,-0.453066,0.785259,-0.122319,-0.649404,-0.178027,0.020436,0.941656,-0.164376,0.451961,0.177840,0.238769,-0.230089,-0.762245,0.178082,-0.299807,-0.324791,-0.454972,-0.035672,-0.119758,-0.223927,-0.508309,0.457486,-0.057962,0.049695,0.618805,0.427915,0.238583,0.227795,0.589852,-0.385170,0.263219,-0.031226,0.040303,-0.226020,0.420009,0.376205,-0.219613,-0.128135,0.264584,-0.005155,0.280498,0.666035,-0.211508,-0.007006,-0.167540,0.239171,-0.132652,0.006225,0.347184,0.242069,-0.043623,0.094268,0.178111,-0.285407,-0.146212,0.149736,-0.028573,-0.398865,0.072342,-0.107167,0.048518,-0.820515,0.331276,-0.299850,-0.111061,0.414865,-0.434117,0.196900,0.462770,0.132805,0.450960,-0.278324,0.089298,-0.614779,0.267670,0.751714,0.108076,-0.190050,0.373079,-0.203960,-0.359844,-0.119651,-0.323892,-0.595545,0.174121,0.296252,0.068711,-0.402442,0.187808,-0.180398,-0.222365,-0.384529,0.036819,0.041909,-0.522172,-0.122152,-0.029312,-0.271999,-0.521600,-0.451532,0.064521,-0.082185,-0.415550,0.599787,-0.990128,0.445648,0.621233,0.638387,-0.600576,0.694597,0.317884,0.156247,-0.186662,0.172362,0.428727,-0.194107,0.114282,0.241447,0.226590,0.173453,-0.005380,-0.405381,0.432066', '1302384', '35030151', '1301022', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296791', '诺斯费拉图', '恐怖', '布特（古斯塔夫·冯·沃根海姆 Gustav von Wangenheim 饰）是一家不来梅地产公司的职员，受公司委派去一座古堡与诺斯费拉图伯爵（马科斯·夏瑞克 Max Schreck 饰）做房屋买卖交易，但是在古堡附近的旅店投宿时，人们得知他目的地的反应都很奇怪。到了古堡，见到面目枯槁、行为古怪的诺斯费拉图伯爵，也得知他昼伏夜出的生活习惯，布特对他的身份心生窦疑，终于探知他就是传说中的吸血鬼。布特逃出古堡，伯爵也一路奔向他买好的、位于不来梅的房子。布特回家后，得知吸血鬼伯爵已经到来，而且正是他令小城瘟疫肆虐，他和妻子艾伦（Greta Schröder 饰）一起，开始设法消灭吸血鬼伯爵……©豆瓣', '马科斯·夏瑞克', 'F·W·茂瑙', 8.2, 14547, 'tt0013442', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2673132785.jpg', 0.4, 1.5, 16.6, 50.9, 30.6, '0.310705,0.060455,-0.534227,0.456979,0.059221,-0.213853,0.826244,0.312977,-0.399496,-0.417592,0.262578,0.737000,-0.067782,0.347523,0.539961,0.422077,-0.482757,-0.262427,0.063568,-0.425199,-0.029265,-0.445693,-0.237237,-0.474249,0.324280,-0.630646,0.286818,0.330478,-0.004510,0.116289,0.244893,0.330589,-0.278347,0.465143,0.006970,0.049117,0.332884,-0.314612,-0.309963,0.133914,-0.036204,0.049200,-0.205336,0.066376,0.445198,0.423214,0.362324,-0.211892,-0.007234,0.029099,-0.023629,-0.098348,0.332903,0.325550,0.357213,-0.509317,0.172812,0.222615,-0.195531,-0.128380,-0.146700,-0.054962,-0.383425,0.305909,0.229507,0.135031,-0.588727,0.218649,-0.390126,-0.072552,0.013049,-0.541779,0.109446,0.282119,0.079288,0.359508,0.303178,-0.076226,-0.829631,-0.319834,0.552252,-0.069762,-0.261238,-0.144858,-0.098481,-0.491660,-0.090113,0.004782,-0.194121,-0.110584,0.295177,-0.088510,-0.072508,0.090977,-0.539279,-0.388792,-0.559184,-0.437761,0.150466,-0.236979,-0.123429,-1.016428,-0.098647,-0.276703,0.041113,-0.243131,0.077132,-0.084661,-0.077495,-0.587423,0.283359,0.548232,0.376551,-0.264532,0.627526,-0.479511,0.001891,-0.186799,-0.075244,0.450427,0.420266,0.373218,0.103026,0.159580,0.185971,-0.314218,-0.026759,0.630157', '3183490', '34961898', '3178770', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296792', '冬日之光', '剧情', '埃里克森牧师在瑞典一小镇宣扬基督的爱，认为爱是上帝存在的证明，但围绕在他身边发生的事却弥漫着世界末日的气息，因为他与人全无沟通。上承《犹在镜中》，下启《沉默》的《信仰三部曲》中间作品，场景集中（室内剧形式），时间短促（发生在一天内），虽然简洁但传递出深刻的涵义。', '古纳尔·布约恩施特兰德', '英格玛·伯格曼', 8.3, 5963, 'tt0057358', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1886926656.jpg', 0.5, 1.2, 15.5, 49.3, 33.5, '0.233455,0.301595,-1.005983,0.726404,0.161548,0.319026,0.971289,-0.191856,-0.516020,-0.364844,0.279873,0.557987,-0.198298,-0.063942,0.411241,-0.130641,-0.245335,-0.794843,0.070831,-0.220759,-0.164155,-0.563906,-0.074017,-0.174742,-0.387338,-0.464563,0.438720,0.357548,-0.275977,0.193143,0.126361,0.059333,-0.354784,0.506618,0.172571,-0.326657,-0.014710,0.201879,-0.346674,0.042413,0.122768,-0.167363,-0.136454,0.223420,-0.294001,0.233752,0.582674,-0.719952,-0.279740,0.252202,0.436638,-0.031695,-0.170564,0.021909,-0.014352,0.308513,0.087772,0.446363,-0.170521,0.011021,-0.127149,0.153164,-0.657800,-0.184558,-0.050973,0.597334,-0.089521,0.826413,0.121721,-0.212971,-0.139161,-0.320928,0.343956,-0.142261,0.396000,0.459783,-0.004269,-0.081440,-0.380033,-0.128400,0.801317,-0.203218,-0.638611,0.378569,-0.838423,-0.302402,-0.274147,-0.160946,-0.260008,0.041815,-0.133888,0.313098,-0.132155,0.321794,-0.401842,0.190097,0.262755,-0.455558,-0.122393,-0.492003,-0.155143,-0.582704,-0.278440,-0.379534,-0.089505,0.079558,0.093622,-0.515168,0.582989,-0.765192,0.441252,0.491630,0.253128,-0.092290,1.047420,0.155834,-0.027574,-0.096421,0.104595,0.405277,0.102289,-0.058132,0.215595,0.120216,-0.124072,0.086079,-0.285705,0.554426', '1292211', '1917323', '1304862', '1292338');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296794', '怪形', '科幻', '1982年冬天，挪威科考队的一架直升机突然打破了南极大陆的平静，直升机疯狂的追逐一只雪橇犬，最后坠毁在美国科考营地的附近。美国科考队员对挪威考察队近期人员骤减的情况有所耳闻，于是飞行员麦克（Kurt Russell 饰）与众人赶赴挪威营地，结果看到的是一地破败中四处散落着奇怪的尸体，并有证据表明挪威人得到了某种冰封状态中的生物。医生布莱尔（Wilford Brimley 饰）研究了尸体的变异却无法破解成因。当晚，犬笼中的狗遭到袭击并发生了变异，一种不可知的生物正在这孤寂的南极大陆威胁着科考队员们的生命……本片翻拍自1951年由霍华德•霍克斯指导的《The Thing From Another World》。©豆瓣', '库尔特·拉塞尔', '约翰·卡朋特', 8.1, 47831, 'tt0084787', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p449608716.jpg', 0.4, 1.6, 20.1, 50.3, 27.5, '0.316949,-0.092602,-0.780282,0.614255,0.224310,0.171213,0.685312,-0.326431,-0.685216,-0.143482,0.346226,0.596251,-0.021775,0.171667,0.207002,-0.042167,-0.370434,-0.471636,-0.369193,-0.192579,-0.608248,-0.327181,-0.651365,-0.406374,0.103894,-0.435058,0.670676,0.359948,-0.138673,0.657260,-0.170525,0.325039,-0.150821,0.528469,-0.120435,-0.149742,0.116418,-0.100788,-0.056211,0.115453,-0.053735,-0.202404,-0.194262,0.120247,0.081561,0.446103,0.820250,-0.534643,-0.062816,-0.363318,0.082977,-0.266844,0.298004,-0.003036,0.886040,0.044039,-0.080778,0.220299,0.066234,0.120113,-0.113641,0.219935,-0.428954,-0.173755,-0.054036,0.421593,-0.204555,0.421945,-0.049938,0.153634,-0.098783,-0.193216,0.333885,0.275378,0.141016,0.418027,-0.110601,-0.233100,-0.508670,0.133027,0.465989,-0.139063,-0.354167,0.092931,-0.398381,-0.647440,-0.133480,-0.135030,-0.200603,-0.087834,0.342555,0.297742,-0.321511,0.406330,-0.779213,0.202679,-0.208770,-0.618903,-0.408443,-0.170369,-0.116578,-0.764359,0.169881,-0.201985,-0.124456,0.252005,0.064288,0.064418,0.471550,-0.609538,0.273699,0.525056,0.218067,-0.077162,0.352829,-0.371815,-0.019257,-0.117359,-0.027866,0.260390,-0.006636,0.437829,0.062906,0.335268,0.119823,-0.363826,-0.251215,0.230794', '2159244', '3097525', '2059276', '26309788');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296805', '无语问苍天', '剧情', '本片根据纽约市的英籍神经医师奥利佛·萨克斯（Oliver Sacks）的同名回忆录改编。1969年，羞怯内向但对实验充满热忱的脑科医生马尔科姆·塞尔（罗宾·威廉姆斯 Robin Williams 饰）来到纽约市布朗克斯区一家医院，对院内的强直性昏厥证患者进行治疗。在护士埃莉诺（朱莉·卡夫娜 Julie Kavner 饰）的帮助和鼓励下，塞尔医生对病人大胆用药，使一群昏厥几十年的患者重获新生，尤其对患者伦纳德·洛（罗伯特·德尼罗 Robert De Niro）效果尤为明显。但令人意外的是，患者们在苏醒后不久，又纷纷出现了病情恶化的趋势……本片获奥斯卡最佳影片、最佳男主角（罗伯特·德尼罗）和最佳改编剧本奖提名，并获金球奖剧情类影片最佳男主角提名（罗宾·威廉姆斯）。©豆瓣', '罗伯特·德尼罗', '潘妮·马歇尔', 8.4, 10484, 'tt0099077', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200706542.jpg', 0.2, 0.8, 12.7, 49.6, 36.7, '-0.010084,-0.380269,-0.088064,0.280316,0.220782,-0.246159,0.655450,0.165910,-0.545963,-0.285785,0.308330,0.800234,-0.386418,0.114971,0.400161,-0.117045,-0.593511,-0.460523,-0.009337,0.048470,-0.277434,-0.480233,-0.275757,-0.431318,-0.054105,-0.852428,0.409964,-0.286930,-0.113103,0.600369,0.204780,0.261036,0.222894,0.231688,0.400097,0.265344,0.517764,-0.455307,-0.353433,0.682374,0.575616,-0.165822,-0.439311,0.179687,0.253247,0.370083,0.652301,-0.128693,-0.059497,0.103278,0.706078,-0.271342,0.029375,0.065437,0.158908,-0.107199,0.311126,0.102348,-0.032206,0.140254,0.006105,-0.085330,-0.531906,0.156582,0.093508,0.387583,-0.329430,0.244417,-0.277852,0.104738,-0.102540,-0.063436,0.033339,0.068727,0.288267,0.248306,-0.136698,-0.093153,-0.162349,0.213905,0.018316,0.122130,-0.523837,0.377019,-0.508764,-0.947998,-0.035774,0.084880,-0.420997,0.036728,0.463142,-0.042449,0.115229,0.050455,-0.244775,-0.176052,-0.545463,-0.410967,-0.493076,0.073001,0.219438,-1.022316,0.049847,0.050424,-0.068030,-0.358881,0.127246,-0.224107,0.706414,-0.551436,0.293576,0.255131,-0.128571,-0.318152,0.503852,-0.018865,0.077608,-0.425897,-0.430904,0.700700,-0.036424,0.158063,0.025990,0.448942,-0.084962,-0.112046,-0.330272,0.380317', '2075345', '1484091', '34961898', '2255841');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296814', '魔法圣婴', '剧情', '一位面目丑陋不堪的老妇生下了一个相貌标致、拥有天使面孔的男婴。然而男婴的姐姐（朱丽娅·奥蒙德Julia Ormond饰）却声称孩子是自己的。处女生子的荒唐前提一旦成立，一连串不可思议的玄虚之事便相继发生，整个世界的秩序将不复存在。她先是宣称男婴为神之附体的圣婴，后是以圣母玛利亚自称，靠圣婴赚取钱财。当姐姐与主教的儿子（拉尔夫·费因斯Ralph Fiennes饰）相恋时，却遭到了圣婴的阻碍，主教的儿子惨死在牛角之下。姐姐为了报复，杀死了圣婴，闻讯赶来的人们要求严惩这个触犯天条的女人，于是她被判处了死刑，由于当时法律规定，处女是不能处死的，所以教皇命令208名士兵强奸她。姐姐在强暴中死去，人们欢快地将圣婴肢解后分掉，希望可以得到圣婴的庇佑。©豆瓣', '朱莉娅·奥蒙德', '彼得·格林纳威', 6.9, 6388, 'tt0106335', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1782637657.jpg', 3.5, 10.4, 37.8, 31.7, 16.6, '-0.070827,0.276168,-0.530489,0.521952,-0.598325,-0.058099,0.767305,0.217991,-0.391321,-0.056254,0.526354,0.749162,-0.121804,0.221074,0.365925,0.220709,0.013050,-0.630727,-0.157111,-0.266522,-0.168950,-0.325751,0.025355,-0.186665,-0.274947,-0.789744,0.690072,-0.016775,0.023159,0.061148,0.276530,0.135092,-0.030194,0.140346,-0.282642,-0.035798,-0.089271,-0.175959,0.036545,0.263868,-0.202884,-0.306131,0.180502,0.226142,-0.374512,0.500594,0.616307,-0.768724,-0.108868,-0.649215,0.584763,-0.285813,-0.105821,0.547528,0.259295,-0.171411,0.194699,0.316148,-0.152582,-0.191696,0.389977,-0.046824,-0.795142,-0.156003,0.241029,0.153898,-0.529175,0.329429,-0.162023,0.236507,0.098883,-0.197374,0.240042,0.152900,0.133807,0.596056,-0.125976,0.002554,-0.505722,0.138245,0.558015,-0.118467,-0.258436,0.119364,-0.308056,-0.502117,0.194188,-0.336852,-0.292384,0.203350,0.335112,0.035570,-0.163149,0.443620,-0.333399,-0.448448,-0.624800,0.013657,-0.124976,-0.334364,-0.130919,-0.068673,-0.024970,-0.092296,-0.086717,0.013395,0.184600,-0.138989,0.855341,-0.701798,0.298907,0.442407,0.467790,-0.643057,0.504633,0.316673,0.325481,-0.124238,-0.067921,0.135825,0.260502,0.375561,0.026794,0.079054,0.035205,-0.016424,-0.079936,0.239019', '24284209', '25767747', '30195228', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296821', '苹果酒屋法则', '剧情', 'Homer Wells（托比·马奎尔 Tobey Maguire 饰）从小在St. Clouds的一所孤儿院长大，孤儿院的院长Dr. Wilbur Larch（迈克尔·凯恩 Michael Caine 饰）对他关怀备至。Homer和其他孤儿一起健康快乐地成长，他还在Dr. Larch身边学习，掌握了精湛的医术，尤其是妇科手术。有一天，中尉Wally Worthington（保罗·路德 Paul Rudd 饰）带着他的未婚妻Candy Kendall（查理兹·塞隆 Charlize Theron 饰）来到孤儿院进行堕胎手术。术后，Homer询问Wally能否带他到外面的世界去看一看，Wally欣然答应。于是Homer跟着Wally离开了孤儿院，生命中第一次见到了大海，还在Wally家的苹果庄园找了份工作。不久后Wally又去缅甸参加战争。Homer和Candy在日复一日地相处中滋生了爱情。而另一方面，Homer收到孤儿院寄来的信，Dr. Larch希望他回去当他的助手，但Homer拒绝了，他更想留在外面的世界。此时Wally前线传来噩耗，Wally受伤下半身瘫痪即将回家。Homer该如何处理这些问题呢？本片根据John Irving的同名小说改编，获得七项奥斯卡提名，赢得最佳男配角和最佳改编剧本奖。', '托比·马奎尔', '拉斯·霍尔斯道姆', 8.2, 25872, 'tt0124315', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p483594726.jpg', 0.2, 1.2, 17.6, 51.9, 29.1, '-0.088138,0.092737,-0.671892,0.459026,-0.115538,-0.356839,0.436117,0.145147,-0.323130,-0.216317,-0.037960,0.820480,0.125781,0.343655,0.280643,0.000528,-0.601138,-0.518353,0.065146,-0.175424,-0.451997,-0.463423,-0.002229,-0.232674,0.028819,-0.342117,0.558179,-0.029339,0.041208,0.572569,0.136845,0.138476,0.010379,0.319871,-0.288034,0.097299,0.150877,0.101213,-0.409872,0.448387,0.549035,0.019500,-0.347961,-0.021285,0.413475,0.047175,0.678079,0.078072,-0.028014,-0.036155,0.423872,-0.129108,0.008746,-0.122354,0.248180,0.167584,0.193566,0.264576,-0.179432,0.189061,-0.136053,-0.185998,-0.442945,-0.131764,0.142347,0.148808,-0.709829,0.173125,-0.027255,0.023144,0.117907,-0.365029,0.226561,0.501108,-0.019261,0.532702,-0.159587,0.128952,-0.511895,0.387375,0.395218,-0.316357,-0.095570,0.311609,-0.021752,-0.460986,0.123494,-0.061574,-0.488910,0.177319,0.310819,0.097949,-0.320104,-0.107053,-0.274848,-0.053608,-0.208742,-0.361993,0.164978,-0.486961,0.019931,-0.766537,0.052768,-0.094071,-0.280519,-0.170840,0.117792,-0.267130,0.738032,-0.656244,0.286517,0.