INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296824', '简爱', '剧情', '孤儿简·爱从小寄居在舅母家，受尽舅妈极其表弟的折磨，后被送往由布洛克赫斯特先生所开的教会学校。在学校里，简·爱仍遭歧视，但她认识了同学海伦，第一次感受到友情的温暖。海伦却因违抗布洛克赫斯特先生遭受惩罚染病去世。孤独的简·爱（琼·芳登 Joan Fontaine饰）成年后离开学校来到桑菲尔德，给爱德华先生的私生女阿黛勒当家庭教师。一个夜晚，她在郊外巧遇了远行归家的爱德华先生（奥逊·威尔斯 Orson Welles饰）。经过一系列交流后两人的感情迅速升温，陷入了恋爱中。就在他们两人准备成婚之际，一个真相却打断了他们的幸福。远离了爱德华的简·爱回家探望了濒死的舅妈，同时收到了爱德华遭受噩耗的消息，最后这两个彼此深爱的不幸之人能否终成眷属呢？本片根据十九世纪英国女作家夏洛蒂·勃兰特的著名作品《简·爱》改编，由四十年代的好莱坞影星琼·芳登与奥逊·威尔斯主演。', '奥逊·威尔斯', '罗伯特·斯蒂文森', 7.8, 21726, 'tt0036969', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1398210826.jpg', 0.2, 1.8, 26.7, 49.3, 22, '0.155155,-0.072257,-0.745412,0.551452,0.105007,-0.619630,0.788257,0.221658,-0.416404,-0.401767,-0.162041,0.970551,-0.350739,0.492752,0.505850,0.170026,-0.042496,-0.476132,-0.098718,-0.116032,-0.186995,-0.465935,0.032844,-0.264657,-0.076826,-0.244370,0.263435,0.112216,-0.212610,0.534830,0.208498,0.408466,-0.251829,0.342309,-0.114623,0.288497,0.292011,0.037223,-0.591823,0.236566,0.256054,-0.053164,0.197466,0.066970,0.084500,0.209724,0.725679,-0.218697,-0.058334,-0.141250,0.353540,-0.059850,0.018744,0.125507,0.232885,0.033621,0.199733,0.318131,-0.207573,-0.049044,-0.127296,-0.189679,-0.356996,0.010736,0.070925,0.052005,-0.515668,0.609528,-0.229053,0.116417,-0.106117,-0.218391,0.333772,0.353040,-0.017732,0.340869,-0.009508,0.162124,-0.115560,0.107772,0.788538,-0.104677,-0.169071,0.239916,-0.369469,-0.295069,0.263952,-0.131067,-0.654283,0.174177,0.305118,-0.003248,-0.224746,0.192424,-0.362731,-0.348383,-0.446219,0.154791,0.085563,-0.510068,-0.167055,-0.707056,-0.125498,-0.480601,-0.279030,0.029199,-0.044829,-0.168953,0.637601,-0.702480,0.544038,0.271092,0.403152,-0.400853,0.666900,0.264111,0.146071,-0.211722,0.166198,0.606453,0.122544,0.075262,0.262265,0.006275,-0.086396,0.082437,-0.536213,0.305335', '26687241', '1303333', 