INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296826', '赌霸', '喜剧', '阿星（周星驰 饰)利用特异功能在赌王大赛出尽风头，而后云游世界，不知所踪。洪光（秦沛 饰）不甘心失败，再度组织“超级赌王大赛”。松爷（刘镇伟 饰）勒令三叔（吴孟达 饰）寻觅特异功能人士参赛。另一方面，大陆对阿星在港所作所为十分不满，派出同样有特异功能的阿星之姐阿梅（梅艳芳 饰）赴港捉回阿星。三叔巧遇鱼市赌霸（郑裕玲 饰），为其赌技折服邀她出赛，却不知对方只是为弟弟筹措手术费的一名老千而已。阿梅暂住三叔家里，与大陆抵港的义匪大B（钟镇涛 饰）结识并心生爱意，并且最终答应传授赌霸特异功能以帮助她渡过难关。赌王大赛如期举行，阿梅却遭袭以致功力大减，而洪光却请来了大陆异人为自己撑腰……©豆瓣', '郑裕玲', '元奎', 6.5, 14686, 'tt0101780', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2218987484.jpg', 1.8, 12.1, 54.6, 21.2, 10.2, '-0.576332,0.146938,-0.498725,0.357000,0.112620,0.093071,0.046450,0.039989,-0.471897,-0.333646,0.226305,0.677664,0.055069,0.191035,0.181381,-0.155009,0.107480,-0.316066,0.348211,-0.225166,-0.124180,-0.053799,-0.443224,-0.014226,-0.196744,-0.152760,0.427506,0.031896,-0.582287,0.646350,0.437068,0.251811,-0.082457,0.268082,-0.090039,-0.016501,0.054874,0.301810,-0.388179,0.005034,-0.244694,-0.088599,-0.358604,-0.113880,0.190445,0.245077,0.458509,0.118656,0.032076,-0.414438,0.153780,-0.253879,0.012437,-0.339795,0.156180,0.031658,0.124060,0.149284,0.057717,0.176934,0.102416,-0.096182,-0.529980,0.215801,0.590266,-0.020114,-0.401358,0.331317,-0.379832,-0.204987,-0.457099,-0.071594,-0.055599,0.426230,0.086938,-0.083944,0.110742,0.091471,-0.269386,0.370588,0.494749,-0.087337,0.298771,0.022393,0.130322,-0.383526,0.362227,-0.376127,-0.063156,0.151451,-0.002803,-0.079039,0.164871,0.111801,-0.197669,-0.207437,-0.253852,0.019631,0.094904,-0.267474,0.358728,-0.595456,-0.074043,-0.049005,-0.046465,-0.155085,0.306043,-0.105035,0.577049,-0.791710,0.059345,0.214631,0.380990,-0.663202,0.481368,0.173598,-0.036527,-0.596051,-0.392676,0.117030,0.022707,0.016596,-0.200902,-0.002251,0.227387,-0.315465,-0.230681,-0.073998', '6013880', '1897368', '35030151', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296834', '彼岸花', '剧情', '某个婚礼上，与新娘父亲同期的三上周吉（笠智众 饰）独独缺席，原来他的女儿文子（久我美子 饰）坚持离家出走，和所爱的男人住到一起，令周吉颇为烦恼。周吉拜托公司常务，同时也是他的好友平山涉（佐分利信 饰）去文子工作地点探望。有道是别人家的事总归无关痛痒，平山虽然看似开明表示理解文子的做法，可是放到自身态度就立马180度大转弯。他的大女儿节子与公司员工谷口正彦（佐田啓二 饰）自由恋爱，打乱了平山对女儿婚事的安排。父亲和女儿不仅仅是两代人的关系，更好像天生依存而又互相折磨的冤家，一代又一代，宿命地轮回下去……本片根据里見弴的原作改编。©豆瓣', '佐分利信', '小津安二郎', 8.3, 6649, 'tt0051720', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2187076419.jpg', 1.2, 0.9, 12.7, 53.2, 32.1, '0.133582,-0.163686,-0.479341,0.614135,-0.058258,-0.431335,0.265385,0.323103,-0.514305,-0.324676,0.066983,0.693911,-0.006327,0.129422,0.246132,0.075919,-0.127800,-0.566269,-0.126646,-0.020575,-0.113604,-0.514338,0.023443,-0.118062,-0.005029,-0.005325,0.364453,-0.045857,-0.119763,0.323021,0.267436,0.297070,-0.093397,0.275888,0.124867,0.059178,-0.336242,0.359460,-0.241036,-0.049944,-0.175256,-0.044198,-0.212619,0.084557,0.205188,0.393083,0.423049,-0.249448,-0.289427,-0.218490,0.289368,-0.221195,-0.209286,0.035478,0.337990,0.045752,0.546128,0.566852,-0.251894,-0.183903,0.069258,-0.109075,-0.402857,0.037167,0.138619,-0.037775,-0.471501,0.548232,-0.057625,-0.201543,0.048916,-0.523260,0.009375,0.164412,0.243481,0.403709,-0.390055,-0.061300,-0.106438,0.099131,0.637505,0.171676,0.020449,0.086117,-0.156298,-0.221738,-0.251832,-0.203845,-0.393585,-0.041236,0.003112,0.018446,0.011327,0.212373,-0.153124,-0.171263,-0.137951,0.212916,0.161383,-0.582473,0.265390,-0.402461,-0.037302,-0.541021,-0.349924,-0.145135,0.504317,-0.336704,0.716855,-0.508199,0.115498,0.382161,0.180404,-0.615071,0.465046,0.520191,0.091507,-0.514195,-0.177165,-0.088107,-0.176209,0.054208,0.104394,0.120321,-0.039551,-0.118969,-0.260393,0.413099', '35048413', '1456503', '1418613', '1309177');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296835', '青春年少', '剧情', '才华横溢，有一腔理想抱负的热血少年马克斯·费舍尔（詹森·舒瓦兹曼 Jason Schwartzman饰），在休斯敦一间贵族预备学校就读。初入名校的马克斯，却把全部的心思都投注于社团上。凭借着过人的聪明才智，他很快在各种社团里游刃有余。然而过分忽视功课的他，不久就面临着被退学的威胁。因缘际会，他与事业成功的商业大亨赫尔曼·布卢姆（比尔·默瑞 Bill Murray饰）成为了忘年之交，学会了很多人生真理。然而这一切都终结在了才貌双全的女老师露丝玛丽·克罗丝（奥莉维亚·威廉姆斯 Olivia Williams饰）手里。马克斯深陷爱情的世界里，不能自拔。本片凭借着处处充满针锋相对的机智对白与幽默感，以及新老演员对角色的成功塑造和诠释，荣获1999年第56届金球奖电影类-最佳男配角提名及1999年独立精神奖最佳导演、最佳男配角等多项大奖。©豆瓣', '詹森·舒瓦兹曼', '韦斯·安德森', 8.1, 22380, 'tt0128445', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1593683857.jpg', 0.3, 1.6, 19.7, 49.4, 29, '0.113870,0.078098,-0.427200,0.574034,-0.163372,-0.245647,0.477482,-0.004491,-0.474260,-0.131961,0.000047,0.811323,-0.320412,0.145915,0.498893,-0.242173,-0.324867,-0.804697,-0.073677,-0.187697,0.162629,-0.584623,-0.520790,0.133353,-0.287349,-0.544869,0.801776,-0.163335,-0.159881,0.371798,0.497406,0.179508,0.221281,0.208537,0.070631,0.152140,0.412030,-0.019762,-0.374857,0.389308,0.009977,-0.166207,-0.298397,0.071355,0.008590,0.015758,0.575164,-0.148388,0.247658,0.077416,0.562787,-0.232105,-0.196738,0.209962,0.166583,-0.087332,0.156122,0.386171,-0.062913,0.150297,0.166512,-0.330561,-0.855344,-0.227073,0.196571,0.120864,-0.519739,0.500713,-0.069224,-0.014802,-0.066283,-0.060459,-0.082348,-0.124844,0.261253,0.267503,-0.068928,0.105818,-0.267912,0.436373,0.269625,-0.000895,-0.496574,0.134261,-0.165330,-0.571740,-0.062011,-0.363493,-0.471506,-0.097716,0.355636,0.105405,0.147623,0.271091,-0.513312,0.072914,-0.157226,-0.246515,0.016461,-0.521722,0.078982,-0.728832,-0.236164,-0.322798,-0.245653,-0.102851,0.196452,-0.367121,0.903341,-0.800918,0.145351,0.260723,-0.043017,-0.133174,0.725823,0.053454,0.302880,-0.299720,-0.407892,0.388862,-0.139877,0.047740,-0.112254,0.610813,-0.128310,-0.333199,-0.232422,0.720565', '27602116', '25880986',