INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296837', '新少林五祖', '剧情', '清朝康熙年间，少林俗家弟子洪熙官（李连杰饰）是红花会成员，力图反清复明。洪熙官因被同门师兄马宁儿（计春华饰）出卖，家人被叛徒杀害，幸得幼子文定（谢苗饰）避过大难，洪熙官将马宁儿刺死后与文定浪迹天涯。洪熙官父子和行骗的朱小倩和红豆母女碰到一起，闹出许多事情。少林遭劫难，至菩禅师将藏宝图纹在五个年幼的的俗家弟子背上，为防被朝廷夺走，并密函告知洪熙官，务必护送他们前往红花会。但马宁儿被洪熙官打成重伤后，并没有死，而是变成全身是毒、刀枪不入的怪物，他杀害了红花会总舵主，并追杀五个孩子……©豆瓣', '李连杰', '王晶', 7.9, 88052, 'tt0110054', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2677766485.jpg', 0.2, 1.2, 23.3, 52.7, 22.6, '0.120509,-0.255015,-0.332484,0.285304,0.015757,-0.170887,0.468923,0.237183,-0.711890,-0.169883,0.376073,0.715087,-0.081016,0.055256,-0.158907,0.056846,0.390623,-0.747734,-0.091124,-0.138859,-0.177304,-0.363518,0.180154,-0.014760,-0.209875,-0.395452,0.514971,0.172463,-0.139150,0.640499,0.429514,0.221352,-0.375893,0.412569,-0.195164,0.393831,-0.105999,-0.309941,-0.251831,0.182245,-0.206639,-0.462864,0.143951,-0.008073,-0.368287,0.399113,0.471002,-0.269748,-0.040476,-0.532867,-0.064895,-0.411296,-0.128417,0.409344,0.620664,0.071253,0.577759,0.712252,-0.042745,0.074700,0.115541,0.041614,-0.400644,0.215495,0.657541,0.018715,-0.727346,0.507489,-0.104437,0.112375,-0.160856,-0.382346,0.372332,0.245618,0.148477,0.005617,-0.150621,-0.386784,-0.706098,0.353705,0.564752,-0.507020,0.520382,-0.164454,0.246478,-0.101528,0.191151,-0.522168,0.125098,0.526196,0.763083,-0.088538,-0.262873,0.313557,-0.111213,-0.337450,-0.601894,0.234100,-0.158230,-0.217497,0.133027,-0.278099,0.043447,-0.221726,-0.540678,-0.125343,0.271390,-0.108473,0.572801,-0.496391,0.196417,0.091566,0.167253,-0.543248,0.317084,0.148151,0.070643,0.183955,-0.093386,0.036583,0.442311,0.399816,0.378134,0.121435,-0.070110,-0.009456,-0.112568,-0.164122', '27621189', '1306313', '1304401', '1300857');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296845', '煤气灯下', '剧情', '姑母意外死亡，给美丽、善良的少女宝拉（英格丽·褒曼 Ingrid Bergman 饰）留下大笔遗产，引来心术不正的青年安东（查尔斯·博耶 Charles Boyer 饰）觊觎。追求宝拉成功后，二人回到宝拉姑母曾经遇害的伦敦旧宅居住。本以为就此拥有完美丈夫和幸福生活的宝拉，逐渐受到古怪现象困扰，她总会听到奇怪的响声，东西经常莫名其妙消失又出现，新来的女仆也对她态度轻蔑，煤气灯也开始忽明忽暗，安东暗示一切都是宝拉自己的幻觉，是宝拉的精神出现了问题。就在宝拉慢慢心理崩溃，濒临发疯的边缘，一个年轻的侦探伯林（约瑟夫·科顿 Joseph Cotten 饰）出现了，他发现宝拉正在被孤立，背后的主谋正是她的完美丈夫……©豆瓣', '查尔斯·博耶', '乔治·库克', 8.4, 14903, 'tt0036855', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p858808545.jpg', 0.1, 0.7, 11.2, 54.2, 33.9, '0.125546,0.105442,-0.730963,0.243964,-0.257739,-0.045233,0.838130,0.200254,-0.470635,-0.361530,0.445661,0.761334,-0.271184,0.187393,0.303224,0.270203,-0.163526,-0.664013,0.115956,-0.017521,-0.094052,-0.413561,-0.244668,-0.371005,-0.001952,-0.640156,0.119902,-0.075113,-0.300083,0.527978,0.330875,0.466003,-0.134914,0.498856,-0.011293,0.251993,0.118680,-0.159029,-0.078871,-0.067332,-0.051017,-0.225604,0.155913,0.206510,-0.300047,0.303129,0.686025,-0.162545,-0.374136,-0.053297,0.345873,-0.170850,-0.074355,0.267535,0.304795,0.035295,0.080698,0.000225,-0.481696,-0.074512,-0.024827,-0.003589,-0.469982,0.165239,0.067865,0.364973,-0.299805,0.286398,0.139686,-0.291188,0.404664,-0.301847,0.208917,-0.003981,0.406299,0.408204,-0.229266,0.206958,-0.205277,-0.114560,0.279067,-0.162171,-0.256962,0.437378,-0.222645,-0.285017,0.145753,-0.077724,-0.484900,0.190235,0.244534,0.018601,-0.088958,0.326431,-0.423344,-0.013718,-0.303890,-0.085045,-0.009626,-0.288917,-0.287355,-0.227408,-0.325894,-0.081092,-0.370693,0.142616,-0.318717,-0.257248,0.480976,-0.746217,0.647398,0.484358,0.295704,-0.433620,0.219553,0.012645,-0.093486,-0.261869,-0.247600,0.329913,0.037162,0.143162,-0.078137,-0.013221,-0.146644,-0.046284,-0.157346,0.497280', '1302488', '3111650', '6827727', '4896894');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296867', '大买卖', '动作', '偷窃老手尼克（罗伯特·德尼罗 Robert De Niro 饰）顺利完成了委托人的任务返回住所，但是在交接时委托人麦斯（马龙·白兰度  Marlon Brando饰）给他带来了一好一坏两个消息：坏消息是买主死掉了，尼克无法出货；好消息则是有一单四百万的大生意在等着他——需要尼可从海关大楼的地下室偷出国王的加冕权杖。预备和女友结婚的尼可不想再涉足偷窃，但是麦斯的合作者——乔装弱智打入海关内部的青年杰克（爱德华·诺顿 Edward Norton 饰）对这单生意锲而不舍，杰克终于打动尼可，与之结成了偷窃权杖的二人组合。杰克凭借出色的急智完成了准备工作，尼可对这位锋芒毕露的年青人要求严格，但又不乏暗暗的赞许。行动当夜，两人潜入海关，但事情的发展却出人意表……©豆瓣', '罗伯特·德尼罗', '弗兰克·奥兹', 7.1, 12899, 'tt0227445', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2494354430.jpg', 0.6, 4.7, 44, 40.7, 10.1, '0.079168,-0.015557,-0.536518,0.428369,-0.210880,-0.430332,0.462162,0.194690,-0.384059,-0.257065,0.246848,0.575460,-0.158431,-0.183940,0.379242,0.183757,-0.219653,-0.486924,0.210364,-0.346103,-0.208239,-0.785287,-0.148327,-0.404514,-0.183990,-0.151913,0.415909,0.024537,-0.186531,0.212057,0.444601,0.251349,0.045002,0.380979,-0.226719,-0.185581,0.275719,-0.143621,-0.324436,0.315226,0.201541,-0.062410,-0.199391,0.144157,0.389142,0.622549,0.394473,-0.201221,-0.295260,0.175213,0.183939,-0.200969,0.008684,-0.015886,0.202855,0.102033,-0.007549,0.287750,-0.368984,-0.159503,0.227568,-0.234611,-0.720250,0.101403,-0.031405,0.099255,-0.683242,0.244603,-0.333819,0.136744,-0.092788,-0.418777,0.191050,0.447364,0.204105,0.281559,0.081070,0.185627,-0.597608,0.060597,0.353318,-0.015539,-0.104049,0.267969,-0.094596,-0.602116,-0.125974,-0.170790,-0.247569,0.010316,0.528075,-0.013742,0.056910,0.114169,-0.527253,-0.218462,-0.436011,-0.194905,-0.027264,-0.375792,0.002093,-0.792579,-0.117034,-0.090519,-0.497700,0.273445,0.186091,-0.114315,0.507019,-0.812096,0.018108,0.535801,0.241191,-0.553240,0.522914,0.111391,0.393170,-0.298301,-0.150804,-0.072275,0.249886,0.271620,0.377928,0.356219,0.165701,-0.615161,-0.362479,0.309304', '1307442', '1986338', '1793491', '1498811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296869', '艾曼纽', '剧情', '主人翁艾曼妞原是忠于丈夫的纯情妻子，跟外交官丈夫前往泰国，遇上一群法国老乡。鸳鸯恋她赫然发现那些贵妇人在异国环境下因感生活沉闷而到处留情，她在别人怂恿下也迈出了偷腥的第一步。不料在她丈夫知悉后，不但未予责怪，竟然鼓励她深入探索自己的内心情欲需求，于是她更加肆无忌惮地在曼 谷的大街小巷展开“性之旅”。后来艾曼妞认识了一名当地的性爱大师，在他的引导下终于达到情欲解放的最高境界。©豆瓣', '阿兰·居尼', '贾斯特·杰克金', 6.6, 5605, 'tt0071464', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1581760724.jpg', 2.3, 13.3, 47.7, 27.4, 9.3, '0.259351,0.197580,-0.888428,0.637210,-0.245525,-0.069161,0.585978,0.301847,-0.275670,-0.066364,0.336314,0.589151,-0.138515,0.235758,0.098065,-0.059669,-0.053161,-0.467761,0.018469,-0.004986,-0.029857,-0.062644,-0.355264,-0.036686,-0.215002,-0.365075,0.509911,0.281829,-0.469513,0.161040,0.372481,0.159290,-0.060872,0.493160,-0.279164,0.185445,0.314783,0.067788,-0.215842,0.212828,-0.133421,-0.260806,-0.196645,0.074256,-0.176613,0.323858,0.646257,-0.171309,-0.270718,-0.058969,0.406261,-0.134684,0.061200,0.270328,0.127068,-0.148825,0.093854,0.220711,-0.026804,0.117620,-0.142202,0.069419,-0.490409,0.031910,-0.048407,-0.009542,-0.559474,0.220290,0.031893,-0.005425,-0.044598,-0.332328,0.045317,0.408011,-0.157491,0.246047,-0.243903,0.050495,-0.464577,0.289872,0.819894,0.207098,-0.130410,0.445984,-0.240615,-0.362878,0.106126,-0.214084,-0.531434,-0.465904,0.170303,0.070424,-0.382499,0.141044,-0.413176,-0.057879,-0.179717,-0.066236,0.044688,-0.390251,0.041221,-0.537465,-0.242206,-0.340488,-0.325816,-0.101900,-0.061590,-0.327790,0.577157,-0.722803,0.349513,0.739578,0.230696,-0.757234,0.603678,0.131630,-0.076868,-0.126109,-0.310203,0.725533,0.225317,0.398332,0.047659,0.292806,-0.292903,0.102194,-0.472509,0.355439', '1309177', '25858759', '4861627', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296874', '紧急迫降', '剧情', '一架从上海飞往北京的民航客机即将起飞，在这次航班上，机长李嘉棠（邵兵 饰）和乘务长妻子丘叶华（徐帆 饰）的婚姻正陷入问题，即将辞职结婚的空姐舒骏（池华琼 饰）静静等来了自己的最后一次飞行，而形形色色的乘客们：害怕耽误工作任务的魏朝成（魏宗万 饰）、自视甚高的孟凡（林栋甫 饰）等等，也都各怀心事踏上了旅途。然而起飞不久，李嘉棠发现起落架故障无法放下，这意味着飞机无法正常降落，他迅速向地面指挥报告了这一情况。工程师刘元（尤勇 饰）担任地面总指挥，与李嘉棠在市长等领导亲临现场的关注下，尝试了多种应急方案，但最终无法排除故障，国外公司传来的资料也无法应对这种特殊情况。在飞机燃料只能支持两个小时的前提下，李嘉棠等人只能选择紧急迫降，市长与各部门竭尽全力降低事故可能，然而这次迫降的难度毕竟太大……©豆瓣', '邵兵', '张建亚', 7.4, 19208, 'tt0262529', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2218414892.jpg', 1.4, 5.6, 34.9, 39.3, 18.8, '0.258623,0.070362,-0.800119,0.365593,0.126717,-0.172198,0.280895,0.239606,-0.408121,-0.233051,0.441821,0.569937,0.046906,-0.145498,0.261719,-0.313266,-0.742154,-0.454192,0.240535,-0.139443,-0.629420,-0.613248,0.152624,-0.217364,0.111077,0.029542,0.644944,0.291826,0.081535,0.528936,0.319398,0.051344,-0.067678,0.592763,-0.167922,-0.362936,0.054332,-0.091412,-0.302553,0.289685,0.159667,-0.222290,0.036189,0.037130,0.333334,0.437783,0.539370,-0.039368,-0.362529,0.069204,-0.019147,-0.242640,0.308155,-0.103043,0.550192,0.300871,0.027283,0.124031,-0.289675,0.176468,0.057535,0.304466,-0.504886,0.011036,-0.265590,0.061089,-0.454524,0.172521,-0.288830,0.016656,-0.075775,-0.356898,0.184687,0.736193,0.166266,0.187534,-0.410795,0.151034,-0.249734,0.130805,0.492463,0.229214,-0.323964,0.540680,0.085438,-0.548726,-0.325481,-0.303026,-0.239108,-0.138034,0.252835,0.396976,-0.176310,-0.055823,-0.260333,0.136793,-0.228436,-0.462761,-0.281075,-0.299735,0.028095,-0.702681,0.326000,-0.205184,-0.207713,0.333051,0.238035,0.139176,0.496051,-0.597590,0.031520,0.297839,0.126536,-0.521000,0.495943,0.266263,0.159123,-0.340104,0.121864,-0.158487,-0.381099,0.722831,-0.110834,0.152423,0.072268,-0.314403,-0.388791,-0.142702', '10519331', '6007281', '3871833', '1431694');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296895', '新英雄本色', '剧情', '大虾（刘青云 饰）替名震江湖的老大唐俊（郑伊健 饰）办事，帮他杀死了叛徒黑牛，很受俊的赏识。大虾一怒之下杀了奸夫，俊为他多方奔走才使他脱罪，自此两人成了莫逆。岂料俊遭到他的亲大哥威陷害运毒，被警方通缉，无奈只好潜回大陆避难。俊的女友辣椒（邱淑贞 饰）前往找威报仇，失手被擒后惨遭摧残。两年后，俊重回香港，俊发现大虾已经成为威身边的大红人，只是大虾还不知道当日陷害俊的就是威。俊万念俱灰，想就此退隐江湖。大虾在得悉威就是当日的幕后黑手时，发誓要帮俊报仇雪恨！©豆瓣', '郑伊健', '王晶', 6.6, 5077, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2246985661.jpg', 1.7, 9.8, 52.9, 26.3, 9.3, '-0.130309,0.057523,-0.266124,0.526930,0.305447,-0.152683,0.088378,0.443583,-0.046435,-0.111977,0.277030,0.612036,-0.122936,0.598674,-0.015045,0.097992,0.133274,-0.813191,-0.184138,-0.254809,-0.105335,-0.207438,-0.497137,0.202036,0.162597,-0.392308,0.407715,0.165403,-0.137660,0.336675,0.438735,0.111682,-0.083669,0.395012,-0.376398,0.185405,-0.025757,-0.058497,-0.399833,-0.159698,0.109519,-0.744729,-0.027595,0.262688,-0.220299,0.336042,0.526759,-0.064721,-0.235024,-0.415816,0.184449,-0.749161,-0.094705,0.199313,0.459099,-0.500176,-0.060446,0.435669,-0.353669,0.182317,0.352711,-0.037298,-0.515688,0.310436,0.091522,-0.205574,-0.370631,0.021999,-0.341568,0.266240,-0.196116,0.101108,0.329048,0.388677,0.074480,0.001118,0.267370,0.565219,-0.481544,0.292667,0.658291,-0.161696,0.196148,0.015299,0.365801,0.017905,0.333727,-0.502047,0.030892,-0.056377,0.318516,-0.233486,-0.112520,0.153282,-0.051878,-0.503743,-0.750315,0.495010,0.131143,-0.028465,-0.309212,-0.489988,-0.609302,0.087316,0.206690,0.430594,0.086378,-0.347782,0.254661,-0.314906,-0.157220,0.308346,0.328660,-0.825514,0.421034,0.050382,-0.427578,0.005358,-0.076734,-0.218191,0.588840,0.036370,0.449775,-0.034060,-0.007901,-0.229024,-0.097883,0.027270', '1302110', '1296272', '1297574', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296897', '大富之家', '喜剧', '任大宽（关德兴 饰）家道兴旺，四世同堂，但家家有本难念的经，这一家也不例外。大儿子求富（黄百鸣 饰）与老婆月容（冯宝宝 饰）争吵不断，处在离婚的边缘。二儿子求贵（梁家辉 饰）天生口吃，与老爸不和，年纪不小却还没有女朋友。小儿子求其年少无知，却调皮捣蛋，在学校里惹事不断。三女儿求安（毛舜筠 饰）天性叛逆，在法国留学后更是一发不可收拾。这一天，求安从法国带来一个长发不羁的罗伯特（张国荣 饰），让表哥孝忠（刘青云 饰）醋意大起。与此同时，训导主任何守贞（郑裕玲 饰）发现求其的漫画，要求见家长。而求贵爱上了守洁（袁咏仪 饰），两人日渐亲密，却被守洁姐姐守贞百般阻拦……©豆瓣', '黄百鸣', '高志森', 7.8, 30181, 'tt0109524', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p940232872.jpg', 0.3, 1.9, 27.7, 46.6, 23.5, '0.005755,-0.117460,-0.653905,0.452355,0.031806,-0.218784,0.656848,0.447668,-0.438019,-0.257291,-0.131875,0.610335,-0.270029,0.191753,-0.094889,-0.221445,0.099148,-0.440899,0.062083,0.093728,0.104597,-0.291755,0.025435,0.123949,-0.210777,-0.043882,0.315064,-0.058861,-0.081785,0.600327,0.486348,0.111764,-0.076974,0.181071,-0.145499,0.195191,0.028001,0.348793,0.065528,-0.144223,-0.035062,-0.123892,-0.108013,0.066944,0.142634,0.451691,0.442667,-0.123132,-0.062912,-0.289554,0.550726,0.160061,-0.156427,0.322273,0.142818,-0.309291,0.450932,0.185063,-0.099744,0.097115,0.155485,-0.155018,-0.157926,0.156317,0.267220,0.086753,-0.508791,0.359064,-0.261629,-0.450912,-0.057703,-0.313574,0.024591,0.342704,-0.170112,0.235263,-0.284665,0.110669,-0.509425,0.228892,0.274181,0.159640,0.241095,0.282277,-0.051782,-0.062970,0.206652,-0.197510,-0.882065,-0.250134,0.027941,-0.045319,0.066612,0.061905,-0.352665,0.045065,-0.118940,0.287405,0.105614,-0.136304,-0.039316,-0.160165,-0.174350,-0.734079,-0.402321,0.142402,0.137704,-0.157133,0.713182,-0.578422,0.188406,0.179481,0.275915,-0.563403,0.563902,0.440907,0.056822,-0.324032,0.046002,-0.043593,-0.128879,-0.141630,0.152385,0.361509,-0.088847,-0.307951,-0.004511,0.193560', '26348103', '1415573', '3445516', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296908', '窃听大阴谋', '剧情', '哈里·考尔（吉恩·哈克曼 Gene Hackman 饰）在旧金山开了一家侦探公司，他最近的一单生意是去窃听一对男女的对话。他精心地在一个广场附近布下层层的窃听装置，来捕捉这对男女所说的每一句话。窃听进行得很顺利，声音很清晰，但他不理解他们所说的话到底什么意思。 他带着录音文件去雇佣他的公司准备拿他的报酬，却被告知老板不在，便决定暂时不交出录音文件，并退回报酬。他只能小心翼翼地保管着他的录音文件，即使在聚会的时候仍旧提心吊胆，生怕录音文件被人偷走。千防万防，录音文件还是丢失了。心急如焚的哈里只能按照他窃听到的录音内容，于某日来到那对男女口中提到的酒店，却不想他正陷入一场巨大的阴谋中……©豆瓣', '吉恩·哈克曼', '弗朗西斯·福特·科波拉', 8.1, 12105, 'tt0071360', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2678676749.jpg', 0.7, 1.9, 18.2, 49.5, 29.6, '0.341131,0.221812,-0.657670,0.598803,-0.167966,-0.043773,0.857201,0.180341,-0.364507,-0.247470,0.197042,0.474772,-0.144705,0.057033,-0.027257,0.302463,-0.587709,-0.445325,-0.013744,-0.259752,-0.205017,-0.676459,0.016070,-0.267406,-0.012040,0.037451,0.275291,0.036406,-0.404988,-0.062710,0.078994,-0.012661,-0.187959,0.709463,-0.277490,-0.004005,-0.007748,0.009777,-0.035284,0.017408,0.343710,-0.455600,-0.378384,0.246814,0.287125,0.411368,0.511167,-0.131268,-0.196424,0.693988,0.135792,-0.376917,0.047226,0.008254,0.247243,0.337603,0.169416,0.327084,-0.631464,0.177245,0.081621,0.026437,-0.847873,-0.131763,-0.214506,0.583964,-0.354102,0.411130,-0.661354,0.419357,-0.035823,-0.595748,0.116741,0.124064,0.195713,0.367412,-0.113828,-0.043339,-0.723699,-0.034080,0.409438,-0.011008,0.159878,0.445460,-0.032875,-0.573055,-0.179476,0.251050,-0.409730,-0.054192,0.452095,0.092207,-0.176426,-0.150885,-0.424162,-0.164191,0.021401,-0.460589,-0.152508,-0.738810,-0.175727,-0.696361,-0.072906,-0.187614,-0.386860,0.091866,0.219424,0.014430,0.636388,-0.618565,0.023134,0.698805,0.121139,-0.232731,0.523817,0.301776,0.041897,-0.201997,-0.159651,-0.219334,0.365048,0.629246,0.449490,0.402440,0.373441,-0.378782,-0.410778,0.324012', '1308842', '1301345', '1947080', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296909', '虎口脱险', '喜剧', '二战期间，英国一架飞机在执行轰炸任务中，被德军击中，几名英国士兵被迫跳伞逃生。他们约好在土耳其浴室见面，并用这次行动的代号“鸳鸯茶”作为接头暗号。他们分别降落在法国巴黎德军占领区的不同地点。大胡子中队长雷金纳德被动物园管理员所救。而另外两名士兵，也分别在油漆匠奥古斯德 （布尔维尔 饰）和乐队指挥斯塔尼斯拉斯（路易·德·费内斯 饰）的帮助下掩藏好了。即便德军展开了全城的搜索，油漆匠、指挥和中队长还是在浴室顺利地会面，几经辗转，英国士兵终于接上了头。几个原本并不认识的人，就这样结成了生死同盟，与敌人展开了斗智斗勇的生死游戏。同时，也闹出了不少温情的笑话。他们用微薄的力量对抗严酷德军，险相迭生，滑稽搞笑，为了逃出虎口，共同战斗。©豆瓣', '路易·德·菲奈斯', '热拉尔·乌里', 8.9, 236280, 'tt0060474', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2399597512.jpg', 0.3, 0.8, 8.6, 32.9, 57.4, '0.496875,-0.065531,-0.703462,0.511158,0.093493,-0.388228,0.456863,-0.021773,-0.236577,0.108751,0.496898,0.576662,-0.064113,-0.314361,0.165499,-0.290221,-0.664802,-0.819745,-0.097651,-0.107942,-0.418756,-0.498339,-0.159903,-0.245214,0.160061,-0.252643,0.398159,-0.053778,-0.034562,0.391099,0.283771,0.207019,-0.185738,0.430549,-0.047546,-0.003194,0.333210,-0.311952,-0.181855,0.191438,-0.349355,-0.163292,-0.196064,-0.104608,0.269557,0.557511,0.780894,-0.266897,0.145982,-0.103533,-0.136288,-0.285090,0.226716,0.114432,0.438868,0.011323,0.231658,0.078835,0.032506,0.056127,-0.204508,0.038196,-0.544847,0.217878,-0.011122,-0.020669,-0.453095,0.498902,-0.217974,0.090636,0.087389,-0.164228,-0.024301,0.780417,0.306019,0.233776,-0.213064,0.082027,-0.432490,0.004549,0.566669,-0.070557,-0.252222,-0.016093,0.001930,-0.372988,-0.009287,-0.215977,-0.014330,-0.342543,0.567323,-0.209618,0.084749,0.088816,-0.865588,0.042243,-0.433713,-0.250914,-0.051393,-0.318709,0.104555,-1.097051,0.022467,-0.244377,-0.515670,0.293333,0.124478,0.315783,0.572879,-0.617201,-0.084693,0.613144,0.296999,-0.064541,0.397152,0.229871,0.185441,-0.176261,0.191959,0.138852,0.073831,0.542216,0.519985,0.613204,-0.125107,0.102592,-0.269774,0.207603', '21349734', '20274039', '3178770', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296925', '非强力春药', '喜剧', 'Lenny（伍迪·艾伦 Woody Allen 饰）是一个体育新闻记者，他的第二个妻子Amanda（海伦娜·邦汉·卡特 Helena Bonham Carter 饰）则是一个画家。Amanda想要个孩子，于是她不顾Lenny的反对领养了一个小孩，Lenny给他取名为Max。Max非常可爱，也很聪明，在Lenny和Amanda的关爱下茁壮成长，转眼间已经5岁了。然而Lenny却发现他和Amanda之间的激情已经越来越少。强烈的好奇心驱使着Lenny去寻找Max的真正母亲。经过多方打听，他找到了Max的母亲Linda（米拉·索维诺 Mira Sorvino 饰）。此时的Linda是一个演色情片的演员，也是一个妓女。Lenny试图改变Linda的生活，两人经常聚在一起聊天。而另一方面，Amanda也被画廊的合作者Jerry猛烈追求。Linda终于在Lenny的帮助下摆脱了妓女的生活，并和Lenny介绍的男子开始约会。然而有一天，Lenny还是发现了Amanda和Jerry的奸情......饰演Linda的米拉·索维诺凭借此片获得奥斯卡最佳女配角奖。', '伍迪·艾伦', '伍迪·艾伦', 7.7, 14838, 'tt0113819', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1196765064.jpg', 0.3, 2, 28.3, 51.5, 17.8, '0.491917,-0.226423,-0.698902,0.812719,-0.348608,-0.301289,0.961623,0.044710,-0.327477,-0.276566,0.096953,1.011507,-0.252802,0.446968,0.294706,0.053434,-0.154673,-0.724612,-0.046135,0.105515,-0.206261,-0.520297,-0.382777,0.014363,-0.194041,-0.341063,0.660288,-0.144003,-0.112052,0.567687,0.582558,0.086619,0.128009,0.615865,-0.276221,0.103663,0.054197,-0.016256,0.055794,0.421389,0.144321,-0.383270,-0.128434,0.217049,-0.165158,0.622939,0.640740,-0.253314,-0.087854,0.050339,0.468419,-0.293102,-0.066654,0.149187,0.257851,-0.159814,0.214095,0.032388,-0.302944,0.114030,-0.015278,-0.103230,-0.927953,0.082122,0.315079,0.122942,-0.890956,0.407552,0.170381,-0.264921,0.145702,-0.367384,0.242767,0.541695,-0.046529,0.486312,-0.367226,0.028667,-0.620186,0.218939,0.691822,0.101083,-0.190709,0.580591,-0.268489,-0.497957,0.045877,-0.150447,-0.629405,-0.198929,0.289744,0.177588,-0.342059,-0.132366,-0.685065,0.095266,-0.235992,-0.152878,0.029727,-0.680414,0.157191,-0.652208,-0.285125,-0.432515,-0.369468,0.032644,-0.034709,-0.507708,0.960250,-0.990967,0.070612,0.738578,0.326501,-0.579836,0.854230,0.200093,0.017315,-0.188065,-0.056225,0.231816,0.101561,0.105823,-0.013505,0.525221,-0.000169,-0.303914,-0.438094,0.509457', '30162520', '3230462', '3119246', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296929', '科学怪人', '科幻', '弗兰肯斯坦（科林·克利夫 Colin Clive 饰）是一个天才科学家，他想像上帝一样创造生命，于是不顾学校教授的反对，离开了大学，和助手到山上的一座古堡里做人体实验。他从墓地等地方找来了各种人体残肢，还从学校实验室偷了一颗大脑，利用这些制造出一具人体。他的未婚妻伊丽莎 白（梅·克拉克 Mae Clarke 饰）出于担心，就与好友（约翰·博尔斯 John Boles 饰）和学校教授一同去古堡实验室找弗兰肯斯坦。正是在这个暴风雨之夜，弗兰肯斯坦的人体实验完成了——他利用雷电让手术台上的躯体有了生命。然而几天后，这个由科学家创造出来的怪物开始不受控制，他先是把科学家的助手杀死，又开始攻击教授和科学家。于是，身心俱疲的科学家被接了回家，并且开始筹备婚礼，而怪物则留给教授处理。但是怪物却把教授杀死了，从实验台上逃了出来，一步一步走近村庄，还把一个小女孩淹死。正在举行婚礼的弗兰肯斯坦对此浑然不知……', '科林·克利夫', '詹姆斯·惠尔', 7.5, 7253, 'tt0021884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1405163297.jpg', 0.5, 2.5, 32.9, 49, 15.1, '0.502067,-0.154624,-0.360572,0.293584,-0.284813,-0.509430,0.656348,-0.107106,-0.235667,-0.422015,0.168854,0.614395,-0.231486,0.220631,0.214359,0.102273,-0.432830,-0.443932,-0.207568,0.031534,-0.465769,-0.499991,0.014913,-0.318619,0.261922,-0.525587,0.625957,0.060104,-0.045071,0.414002,-0.089844,0.370958,0.074106,0.357729,-0.082226,0.049749,0.192782,-0.153958,-0.007978,0.418845,0.284904,-0.123388,-0.026292,0.229279,0.012686,0.233230,0.588246,-0.046086,0.064728,-0.236013,0.431686,-0.442683,0.132077,0.043456,0.353483,-0.112710,-0.065273,0.107770,-0.066649,-0.001955,0.183828,-0.144848,-0.581298,-0.102492,-0.047754,0.082085,-0.816527,0.118393,-0.030216,0.146719,0.108338,-0.453531,0.319448,0.216843,0.079458,0.526395,-0.178546,-0.196393,-0.710176,0.291569,0.313507,-0.385164,-0.048623,0.138045,0.020804,-0.379156,0.148730,-0.055416,-0.295494,-0.121325,0.211672,-0.028260,-0.339192,0.020301,-0.675021,-0.188172,-0.538695,-0.331648,0.184511,-0.487673,-0.118960,-0.778591,0.009414,0.424200,-0.046628,-0.163005,-0.059905,-0.300780,0.543378,-0.611138,0.331689,0.685058,0.416605,-0.206514,0.557932,-0.392514,0.061474,-0.277336,0.275448,0.016081,0.352033,0.674587,0.189871,0.508870,0.286171,-0.258870,-0.457507,0.312121', 