INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296942', '魔鬼司令', '喜剧', '平静的城市中突然发生了一系列暗杀事件，受害者皆为退役特种部队上校约翰（Arnold Schwarzenegger 饰）的昔日部下，老上司克比为此拜访了约翰的山间小屋向其提出警告，退隐多时的约翰只想同尚年幼的女儿詹妮享受生活，不愿再次卷入仇杀，岂料这次的敌人尾随克比寻至约翰住处，他们掳走了詹妮，强迫约翰刺杀奥维地共和国总统，以便为幕后策划者阿里乌斯登上该国总统之位铺平道路。约翰当然不会就范，他摆脱了随行的监视人员，从飞机一跃而下，暂时脱离了阿里乌斯的控制之后，他只有十一小时救出詹妮。约翰在机场请求素不相识的黑人姑娘西迪（Rae Dawn Chong 饰）相助，两人一同经历了连串的火爆战斗，西迪对这位陌生魁梧男子的态度由戒备转向全力协助，并最终登上了阿里乌斯藏匿的岛屿……©豆瓣', '阿诺·施瓦辛格', '马克·L·莱斯特', 7.3, 10892, 'tt0088944', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2479172530.jpg', 0.6, 3.9, 41.1, 40.3, 14.1, '0.258636,-0.007909,-0.523584,0.436484,-0.188357,-0.446704,0.449799,0.237740,-0.593338,-0.240049,0.565506,0.572095,0.031191,-0.125225,0.587609,0.118308,-0.537984,-0.570666,-0.190833,0.009926,-0.252042,-0.585878,-0.100578,-0.487809,0.040684,-0.462515,0.502449,-0.009788,0.026714,0.504946,0.360460,0.527751,-0.145339,0.381810,0.239336,-0.068289,0.236976,-0.379554,-0.512325,0.320988,-0.293760,-0.350261,-0.171844,0.047787,-0.016020,0.510029,0.490186,-0.265568,-0.046559,-0.204895,-0.051229,-0.378612,0.256365,-0.028022,0.274410,-0.035221,0.012253,0.407431,-0.227843,-0.223732,-0.140576,0.022045,-0.338124,0.351334,0.087645,0.095843,-0.516695,0.178452,-0.298181,0.188910,0.248128,-0.153664,-0.155858,0.614383,0.094593,0.079101,-0.061355,0.120624,-0.265472,0.035476,0.481706,-0.043226,-0.272796,-0.145308,0.033708,-0.312188,0.152596,-0.353400,-0.309444,-0.196494,0.346555,0.118083,-0.045430,0.339093,-0.299290,-0.371866,-0.607335,-0.161156,0.058362,-0.309326,0.115750,-0.785458,-0.054630,0.031563,-0.046852,-0.158515,-0.034286,0.055804,0.398609,-0.584491,0.356523,0.353342,0.309365,-0.417926,0.475143,-0.013834,0.182402,-0.185196,0.045493,0.275025,0.238611,0.312881,0.053498,0.108347,0.047111,-0.282756,-0.372471,0.116316', '1293537', '3036464', '1297715', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296947', '警察故事4：简单任务', '喜剧', '这次，国际警察陈家驹（成龙 饰）受到美国中央情报局的委托，调查一个国际核子武器的贩卖集团。上司与家驹开始都以为是天荒夜谈，他们根本不相信有什么组织能从黑市里搞来核子武器，认为调查的只是一群乌合之众。然而，当家驹跟踪疑犯徐杰进行交易，进而意外发现了乌克兰的核弹基地，他才意 识到事态严重。交易的双方发现了家驹，他逃走时失足掉入了冰湖，幸得俄军相救才侥幸活命。家驹恢复后俄军上校格里格派往澳洲追查徐杰的妹妹安妮（吴辰君 饰）。但家驹刚抵达澳洲，就遭到了当地黑帮的追杀，家驹隐隐感到事件背后不简单。©豆瓣', '成龙', '唐季礼', 7.6, 38698, 'tt0116704', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1754446563.jpg', 0.3, 2.2, 33.1, 46.9, 17.4, '0.197598,-0.078287,-0.786163,0.326958,0.064887,-0.128850,0.161604,-0.164207,-0.487139,-0.225302,0.302275,0.564611,-0.045138,-0.133063,0.075366,0.155012,-0.366451,-0.447293,-0.072458,-0.246594,-0.135089,-0.348023,-0.337979,-0.157012,-0.071891,0.141116,0.428232,0.380616,-0.488485,0.427793,0.102889,0.352745,-0.095110,0.600033,0.064913,-0.006182,0.428816,-0.017028,-0.194820,0.229136,-0.039127,-0.154592,0.050566,0.232885,0.155153,0.622270,0.318272,-0.051294,-0.205506,-0.191933,0.128436,-0.485682,0.192938,-0.084484,0.595624,0.019800,0.064317,0.162712,-0.277995,-0.031484,-0.071261,0.005997,-0.598080,0.080301,0.061819,0.136837,-0.303732,-0.081519,-0.314547,0.031988,-0.092672,0.005990,0.411370,0.757090,0.283211,-0.108471,0.023313,0.052867,-0.645896,0.011141,0.771111,-0.306946,-0.153221,0.067863,0.331914,-0.446381,0.251593,-0.018389,0.142190,0.115588,0.290522,-0.135037,-0.239178,0.069923,-0.398841,-0.096702,-0.504080,-0.003011,-0.162197,-0.190557,-0.073599,-0.672310,-0.151975,-0.097028,-0.254286,0.048090,0.115955,-0.002317,0.282631,-0.775200,0.035280,0.599875,0.301177,-0.527350,0.237865,-0.108862,-0.197854,-0.296175,0.001881,-0.215460,0.153602,0.248977,0.160094,0.133260,0.135724,-0.536889,0.182646,-0.194144', '5157137', '4193254', '1299782', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296963', '日落黄沙', '动作', '派克（威廉·霍尔登 William Holden 饰）是个失败的强盗，他和他的同伙们不仅在抢劫银行上栽了跟头，自己还遭到了赏金猎手桑顿（罗伯特·瑞安 Robert Ryan 饰）的追杀，好在有印第安青年安琪（杰米·桑切兹 Jaime Sánchez 饰）出手相助，才得以脱险。跟随着安琪，派克一行人来到了墨西哥边界，在那里，驻扎着个性凶残暴躁的军阀玛帕奇（费南德斯·埃米里奥 Emilio Fernández 饰）及其同党，而玛帕奇和安琪之间，有着一段充满了仇恨和鲜血的不堪往事。为了能够通过玛帕奇的地盘，交出安琪成为了唯一也是无奈的选择。派克打算带领弟兄们救回安琪，不幸的是为时已晚，安琪已经被杀害。在悲愤交加的派克和玛帕奇之间，一场恶战即将拉开帷幕。©豆瓣', '威廉·霍尔登', '萨姆·佩金帕', 8.3, 10100, 'tt0065214', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p966598612.jpg', 0.5, 1.6, 15.8, 46.9, 35.2, '0.307662,-0.054819,-0.744468,0.255673,-0.034420,-0.491570,0.698985,-0.003386,-0.455802,0.057912,0.275545,0.800579,0.000694,0.058315,0.368969,-0.015941,-0.341069,-0.767896,-0.134786,-0.128902,-0.262062,-0.638044,-0.407487,-0.120985,0.011197,-0.571931,0.388083,0.069354,-0.083685,0.642266,0.424599,0.504888,-0.219509,0.357448,-0.268335,0.080312,0.169290,-0.326677,-0.351061,0.112061,-0.034581,-0.230064,-0.095991,0.122478,0.056526,0.450537,0.528964,-0.335643,0.141665,0.017427,-0.059856,-0.520281,-0.076557,0.179475,0.357526,-0.226308,0.075344,0.348687,-0.225422,-0.035126,0.259564,0.012919,-0.732468,0.017700,0.014784,0.262693,-0.702808,0.581314,-0.143693,-0.184897,0.269459,-0.381911,0.084774,0.570227,0.141162,0.062390,-0.071292,-0.157504,-0.708404,-0.097098,0.673413,-0.023362,0.150205,-0.020031,0.051943,-0.405510,-0.069197,-0.327991,-0.311101,-0.090520,0.717989,-0.116824,-0.143152,0.272203,-0.644434,-0.121404,-0.446240,-0.219146,-0.220538,-0.322936,-0.104509,-0.547991,-0.168272,-0.414143,-0.416604,0.195506,0.009198,-0.072606,0.564398,-0.894812,0.210851,0.386703,0.402206,-0.245991,0.288342,0.209377,0.048893,0.063057,-0.060820,0.162944,0.201088,0.134349,0.368307,0.248321,0.006095,-0.164568,-0.268518,0.404446', '1301022', '1309069', '20277433', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296973', '最后的莫希干人', '爱情', '本片改编自美国作家库柏“皮袜子”系列小说中的第二部。1757年七年战争期间，英法两军在北美殖民地激战正酣。军官邓肯带队护送长官之女可娜（Madeleine Stowe 饰）前往威廉亨利堡，半路遭法属印第安人埋伏，莫希干族最后的战士——金卡加（Russell Means 饰）、安卡斯父子与白人霍克依（Daniel Day-Lewis 饰）出手相救。但抵达要塞时他们发现这里已陷入战火，要塞长官门罗与邓肯做事强硬，不肯放走民兵自降战力，并将霍克依监禁，可娜这时已同霍克依相恋，但却无力援救。英军战事不利弃堡投降，印第安人马瓜带领族人向英军寻仇，可娜与霍克依失散后被马瓜带走，霍克依、金卡加、安卡斯一行进入马瓜族人的营地，以期带回可娜。©豆瓣', '丹尼尔·戴-刘易斯', '迈克尔·曼', 7.6, 12750, 'tt0104691', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2152405391.jpg', 0.7, 3.3, 30.3, 46.4, 19.2, '0.164681,-0.189202,-0.526669,0.199393,0.593872,-0.289006,0.449971,0.152072,-0.414123,-0.146537,0.032821,0.571234,0.176702,-0.208391,0.533610,-0.090561,-0.798901,-0.494356,-0.152200,-0.058742,-0.125443,-0.589313,0.157907,-0.229405,-0.025957,-0.388526,0.571620,0.296178,-0.242435,0.696409,0.157943,0.639543,-0.273699,0.298269,0.417053,0.035627,0.119381,-0.702017,-0.386815,0.254668,-0.415073,0.222024,-0.382787,-0.048876,0.444624,0.577530,0.502782,-0.533916,0.316371,-0.273188,-0.131234,-0.158670,0.389720,0.113293,0.538966,-0.279418,0.035474,0.163924,0.061060,0.039125,-0.179847,-0.152954,-0.156697,0.115912,0.061340,-0.197494,-0.775817,0.110060,-0.274278,0.298235,0.088544,-0.092691,0.001270,0.833936,0.040831,-0.185186,0.213223,-0.144852,-0.717982,-0.334328,0.490766,0.183508,-0.073097,-0.540538,0.452681,-0.660090,0.006475,-0.164734,-0.317839,0.040840,0.399106,-0.064384,0.313955,0.206113,-0.469602,-0.264956,-0.576360,-0.160128,0.178592,-0.119041,-0.114453,-0.477521,-0.012573,-0.176055,-0.383210,0.120065,-0.035630,0.320434,0.183397,-0.444706,0.134881,0.152303,0.388004,-0.099161,0.385576,-0.115095,0.230304,0.043796,0.185559,0.606758,0.518825,0.183408,0.643950,-0.037039,-0.078614,-0.012941,-0.022090,-0.029375', '1302987', '3836070', '2062677', '1297785');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296976', '飞行员的妻子', '剧情', '弗朗索瓦（Philippe Marlaud 饰）深深爱着名为安娜（玛丽·瑞莱 Marie Rivière 饰）的女子，然而，由于工作的缘故，两人几乎无法见面。一次偶然中，弗朗索瓦看到安娜和她的前男友克里斯汀（马修·加里瑞 Mathieu Carrière 饰）在一起，之后，他又发现克里斯汀和另一名陌生女子有所来往。于是，弗朗索瓦起了跟踪克里斯汀的念头。 在跟踪的途中，弗朗索瓦结识了名为露西（Anne-Laure Meury 饰）的女子，在得知了事情的来龙去脉之后，露西对于弗朗索瓦的行为表示了理解，同时加入了他的跟踪队伍中。终于，弗朗索瓦从安娜的口中得知了陌生女子的真实身份，她和克里斯汀是兄妹。同时，露西亦投向了另一个男人的怀抱。©豆瓣', '菲利普·玛劳德', '埃里克·侯麦', 8.2, 10527, 'tt0080728', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2201353791.jpg', 0.3, 0.9, 15.4, 55.7, 27.6, '0.584011,-0.015462,-0.736745,0.673698,-0.099339,-0.311787,0.861412,0.013340,-0.879858,-0.222934,0.336813,1.000543,-0.200703,0.261328,0.705155,0.417288,-0.777101,-0.829423,0.103799,-0.591084,-0.538584,-0.733197,-0.018944,-0.055153,0.012174,-0.514838,0.348250,-0.191502,-0.135666,0.495051,0.341954,0.536892,-0.287707,0.606546,0.334508,0.230699,0.519147,-0.201134,-0.198442,0.311719,0.077727,-0.307560,-0.315309,0.459753,-0.018096,0.473509,0.586158,-0.494644,-0.032811,-0.051587,0.069516,0.139375,0.168223,-0.091345,0.171835,-0.024725,0.423499,0.119628,-0.393605,-0.169917,0.086016,0.179881,-0.398665,0.457589,0.168060,0.407118,-0.637950,0.357620,-0.222642,-0.122388,0.251704,-0.246259,-0.006876,0.309307,0.271521,0.189641,0.002547,-0.044435,-0.264854,-0.257667,0.414873,0.320033,-0.149191,0.501559,-0.355404,-0.149827,-0.179240,0.277864,-0.501585,-0.130265,0.484843,0.339297,-0.196541,0.392405,-0.284244,-0.245809,-0.412927,0.120586,0.058341,-0.276818,-0.257509,-0.721849,-0.219685,-0.518670,-0.422062,-0.093140,-0.143142,-0.250412,0.529866,-1.101847,0.093405,0.523141,0.259666,-0.086758,0.487438,-0.089690,0.071123,-0.470949,-0.060517,0.438884,0.094526,-0.053548,0.237201,0.403633,-0.045104,-0.125599,-0.447929,0.541382', '1309172', '3213250', '1296332', '24325856');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296978', '双龙会', '喜剧', '由于匪徒劫持，一对双胞兄弟刚出生即遭分离。弟弟玩命（成龙）被舞女捡到抚养长大，终日浪迹于社会底层，为帮朋友泡妞，他结识了歌女芭芭拉（张曼玉），因此得罪黑社会；哥哥马友（成龙）被一对有钱夫妇带去美国，接受了良好教育长为著名音乐家，回港开音乐会时，结识世伯家的女儿唐心（利智）。阴差阳错中，两人互换角色进入对方生活，由于大家分不清谁是马友谁又是玩命，笑话迭出，芭芭拉与唐心的心思也渐起变化。音乐会上，玩命胡指乱挥不想大获成功，而马友在黑帮威逼下，开车去救被黑帮抓做人质的玩命的好友泰山，随后，两兄弟开始连手共斗强敌。©豆瓣', '成龙', '徐克', 7.7, 86400, 'tt0105399', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1914274264.jpg', 0.2, 1.8, 30.5, 49.5, 18, '0.259902,-0.293076,-0.360836,0.091346,-0.133200,-0.329261,0.291021,0.085272,-0.527413,0.032651,0.211145,0.640928,-0.174329,0.118802,0.091083,-0.122920,-0.120804,-0.588824,0.116991,0.183512,0.114257,-0.206444,-0.066643,0.117988,-0.200110,0.094537,0.298640,-0.201622,-0.017298,0.547506,0.553691,0.137632,-0.438543,-0.036819,-0.236547,0.183264,-0.105615,0.030222,-0.601997,0.301753,-0.016375,-0.243827,-0.100973,-0.192545,0.141362,0.113356,0.634178,0.023535,0.307064,-0.451925,0.166736,-0.199588,-0.171191,0.050777,0.322263,0.048819,0.400151,-0.033569,0.053912,-0.044857,-0.073608,-0.058621,-0.257911,0.263306,0.320216,-0.094204,-0.682038,0.117691,-0.069567,-0.151368,0.013642,-0.220454,0.277409,0.296510,0.200318,0.331859,-0.145390,0.148395,-0.347611,0.048974,0.948579,-0.040300,0.321082,-0.014706,0.128242,-0.132118,0.279803,-0.582282,-0.298863,0.010928,0.237812,-0.280734,-0.194085,0.176513,-0.322912,-0.122638,-0.151849,0.224201,0.037057,-0.405295,-0.006304,-0.359256,0.077202,-0.088394,0.013383,0.063230,0.119823,-0.409628,0.470037,-0.737124,0.036186,0.385007,0.313581,-0.595179,0.547789,0.116447,0.130185,-0.281910,-0.080233,-0.119955,0.324711,0.116806,0.348735,0.040125,-0.254661,-0.010228,0.058402,-0.060007', '1308035', '1419416', '1299062', '2084048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296987', '安妮·霍尔', '剧情', '喜剧演员艾维·辛格（伍迪·艾伦 Woody Allen 饰）是这样一个人：非常介意自己的犹太人的出身；自认为有童年阴影，看了十六年心理医生没见好转却一直付钱看；有点阿Q精神，但对人生却充满消极；喜欢一直讲无聊的笑话。正因为自身的神经质特质，艾维经历了两次失败的婚姻。艾维 遇到了安妮（黛安·基顿 Diane Keaton 饰）――一直梦想成为歌星的女孩，两人渐渐堕入爱河。安妮在艾维的帮助下歌唱技巧迅速提高，但她的父母却反对她与艾维来往。安妮得到了唱片商托尼的注意，获邀前往好莱坞灌录唱片，艾维跟着前往了好莱坞向安妮求婚。©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 8.6, 98699, 'tt0075686', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p619900470.jpg', 0.3, 1, 10.9, 41.9, 45.9, '0.287651,-0.140215,-0.583781,0.446537,-0.169697,-0.463157,0.870995,0.021078,-0.569654,-0.222904,0.061942,1.003130,-0.366195,-0.008504,0.251575,0.081471,-0.388995,-0.617663,0.323067,0.118581,-0.000716,-0.450141,-0.226252,0.041543,-0.373183,-0.416690,0.568166,-0.201751,-0.240618,0.581347,0.187759,0.112481,0.205577,0.624338,-0.015632,0.155236,0.083938,-0.024672,-0.150639,0.198360,0.260533,-0.066933,-0.393490,0.071237,0.028212,0.208103,0.240419,-0.088011,-0.097559,-0.015139,0.426162,-0.218955,-0.085756,-0.014186,0.102825,0.005666,0.247140,-0.153478,-0.186698,-0.077047,-0.066600,0.177320,-0.635905,0.187857,0.012651,0.471958,-0.650202,0.380202,-0.182127,-0.154977,0.125321,-0.254478,-0.073132,0.308905,0.374087,0.264239,-0.237706,0.129203,-0.420914,-0.060299,0.480996,0.260408,-0.445417,0.540474,-0.322300,-0.369703,0.045462,0.047066,-0.721389,0.040520,0.220300,0.087901,-0.184621,0.217476,-0.637187,-0.009073,-0.093766,-0.364431,-0.015002,-0.582294,-0.033925,-0.780334,-0.246839,-0.519562,-0.388255,-0.363565,-0.108122,-0.490556,0.540895,-0.978904,0.190073,0.500607,0.515966,-0.386648,0.757531,0.186269,0.037209,-0.004797,-0.165526,0.522272,-0.330953,0.046986,0.122895,0.275850,0.324156,-0.246436,-0.219446,0.484232', '1297239', '1309172', '1308755', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296992', '洛丽塔', '剧情', '在大学教授法文的亨博特（James Mason 詹姆斯•梅森 饰）少年时期曾有一段刻骨铭心的经历，当年的初恋情人不幸夭亡，令他此去经年依旧对那些充满青春气息的少女有着别样情感。因工作之需，亨博特寻找住房，因此结识了寡妇夏洛特（Shelley Winters谢利•温特斯 饰）及其妖精一般的女儿洛丽塔（Sue Lyon 休•莱昂 饰）。夏洛特迷上了这位儒雅庄重的大学教师，一心与之交往；而亨博特却迷恋上了青春逼人的洛丽塔，为了和这个精灵长相厮守，甚至违心与夏洛特结婚。他将对洛丽塔的情感全部写进日记，锁入抽屉。直到某天夏洛特打开了潘多拉宝盒，他们的命运从此改变……本片根据作家纳博科夫同名小说改编。©豆瓣', '詹姆斯·梅森', '斯坦利·库布里克', 7.8, 95494, 'tt0056193', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2216931670.jpg', 0.5, 2, 26.1, 48.3, 23.1, '0.250502,-0.025400,-0.474721,0.697109,-0.090989,-0.486922,1.047229,-0.003102,-0.402028,-0.432295,-0.056484,0.706024,-0.270943,0.311717,0.377831,0.023401,-0.133503,-0.687351,-0.075589,-0.279661,0.051228,-0.314670,-0.084661,0.176692,-0.126302,-0.263405,0.878212,-0.066934,-0.026708,0.576209,0.121962,0.379583,-0.093767,0.128219,-0.085665,0.140362,-0.221663,0.055991,-0.303561,-0.074698,0.257654,-0.000628,0.030974,-0.002563,-0.226318,0.191480,0.751821,-0.253730,-0.041201,-0.095705,0.669773,0.263940,0.008773,0.227393,-0.028406,0.140180,-0.004483,0.300182,-0.115811,-0.181481,0.156591,-0.166710,-0.527436,-0.174100,0.018829,0.292972,-0.220478,0.396886,-0.128257,0.036834,0.159839,-0.193210,-0.084043,0.011328,0.218177,0.364159,0.109982,0.118442,-0.211011,0.386356,0.269671,0.140073,-0.168151,0.514057,-0.451975,-0.292838,0.085452,-0.165939,-0.720254,0.151926,0.282409,0.153579,0.017699,0.357952,-0.687687,-0.199933,-0.080672,0.152846,0.372614,-0.414619,-0.152979,-0.636559,-0.447399,-0.481507,-0.321096,-0.184065,0.289657,-0.282047,0.864355,-0.819609,0.236037,0.529677,0.093367,-0.485486,0.616214,0.209754,0.069257,-0.040630,-0.004594,0.804771,0.034313,0.330201,-0.060729,0.276817,-0.056433,0.003082,-0.529395,0.592187', '3097044', '3811356', '4233625', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296993', '真爱同心', '剧情', '贾姬（苏珊·萨兰登 Susan Sarandon饰）是路克（艾德·哈里斯 Ed Harris饰）的前任妻子。她为他生下一对儿女，精心操持家务，却终因性格不合而宣告婚姻失败。离婚三年来，儿女一直由贾姬和路克轮番照料，生活倒也波澜不惊，直到女摄影师伊莎贝尔（朱莉娅·罗伯茨 Julia Roberts饰）和路克堕入情网，矛盾开始繁衍激化。伊莎贝尔搬到路克家来，一心一意要做一个合格的继母。即使她没有多少持家经验，但还是设法和孩子们快乐相处，让他们接受自己。事与愿违，在孩子的心中，谁也无法替代生母贾姬的地位。而贾姬的心情更是复杂。她已经身患癌症，当然盼望有个好继母照顾孩子。可是，妒嫉心却让她不愿看到伊莎贝尔和孩子们情如骨肉。病症一天天恶化，心理挣扎的贾姬，终于有了令人释怀的决定。©豆瓣', '朱莉娅·罗伯茨', '克里斯·哥伦布', 7.8, 4877, 'tt0120686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193932086.jpg', 0.3, 1.6, 25, 51.8, 21.3, '-0.317555,-0.108861,-0.627609,0.368747,-0.339723,-0.366984,0.785271,0.102119,-0.632686,-0.326428,0.063626,0.666789,-0.073217,0.433071,-0.063075,-0.006167,-0.261051,-0.618259,0.262105,0.212294,-0.202778,-0.396867,-0.009252,-0.484201,-0.251400,-0.193423,0.700498,-0.058190,0.314239,0.155575,0.361519,0.154392,0.118655,0.326301,-0.163027,-0.034423,-0.189983,0.059848,-0.259892,-0.142630,0.339337,-0.045157,-0.414178,0.172003,0.250716,0.421273,0.530456,-0.117971,-0.108950,-0.141435,0.205113,-0.235306,0.004480,0.306038,0.007249,-0.124563,0.132074,0.204724,-0.265005,-0.168098,0.023730,-0.018605,-0.582920,0.238174,0.254204,-0.041182,-0.654334,0.307451,-0.203141,-0.173382,0.025080,-0.233241,-0.074685,0.461113,0.170217,0.627278,-0.529708,0.192640,-0.282522,0.136686,0.811710,0.041019,-0.239424,0.393985,-0.472169,-0.279631,0.201526,-0.372325,-0.804076,-0.104141,0.051476,0.314889,-0.297640,0.496901,-0.118686,-0.050080,-0.450572,-0.054641,0.075622,-0.632008,0.321647,-0.184115,-0.239789,-0.493933,-0.549309,-0.018263,0.143417,-0.443522,0.844112,-0.701789,0.241590,0.126270,0.183053,-0.970804,0.532280,0.455364,0.295040,-0.293262,0.045329,0.585191,-0.264749,-0.367575,0.151673,0.047312,0.042566,0.251120,-0.223079,0.350103', '1309033', '1877596', '1421278', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1296996', '哈利·波特与密室', '奇幻', '哈利波特（丹尼尔•雷德克里夫 Daniel Radcliffe 饰）结束了假期，即将回到霍格沃兹继续学习魔法。一个叫多比的家养小精灵警告哈利不要回到霍格沃兹，否则会陷入极大的危险。哈利没有听从多比的劝告，回到了霍格沃兹。很快，霍格沃兹发生了一连窜怪事:接二连三出现学生被石化，一直找不出原因。而哈利总能听到一种奇怪的声音，从墙壁里传出来。传说，霍格沃兹有一个密室，里面记录着伏地魔年轻时的秘密，只有斯莱特林的人才能打开密室。哈利偶然发现自己能听懂蛇说话，一时传闻是哈利打开了密室。难道多比所指的危险就隐藏在密室？©豆瓣', '丹尼尔·雷德克里夫', '克里斯·哥伦布', 8.8, 681272, 'tt0295297', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2440298618.jpg', 0.1, 0.5, 9.2, 38.6, 51.6, '0.431539,-0.080387,-0.523007,0.253918,0.230877,-0.212346,0.950329,-0.032324,-0.825443,-0.419225,-0.060724,0.571654,-0.457009,0.477743,-0.010851,0.098360,-0.337885,-0.216266,-0.079094,-0.402080,-0.538638,-0.459633,0.131705,-0.664846,0.029320,-0.613623,0.073607,0.042060,-0.477880,-0.003616,0.099570,0.344280,0.096331,0.400080,-0.232300,-0.056684,0.296405,0.319583,0.002558,0.309656,0.220276,0.004186,-0.369928,-0.001142,0.058650,-0.009078,0.409021,-0.432784,-0.137945,0.411835,0.533213,-0.098068,-0.160276,-0.058912,0.538830,-0.075926,0.069976,0.126276,-0.079117,0.244414,-0.002209,-0.108110,-0.292617,-0.054711,-0.085666,0.525589,-0.397387,-0.024314,0.018413,0.136969,0.326742,-0.507601,0.264355,0.184429,0.328184,0.115676,0.080641,0.244671,-0.652023,-0.273462,0.298227,-0.603807,-0.495533,0.198399,-0.055496,-0.555820,0.041876,0.227398,-0.199765,-0.086942,0.674734,0.076491,-0.162654,0.112280,-0.066126,-0.223270,-0.223663,-0.456690,-0.036630,-0.270494,-0.652574,-0.442548,0.065155,0.138615,-0.034992,0.225650,-0.263723,-0.069643,0.459025,-0.951173,0.463117,0.351625,0.080615,0.210709,0.526981,-0.439060,0.143090,-0.105450,0.182773,0.236124,0.374661,0.526022,0.236288,0.505103,0.225159,-0.265405,-0.369576,0.358076', '1296332', '1302384', '35073565', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297000', '大鼻子情圣', '剧情', '西哈诺（杰拉尔•德帕迪约 Gérard Depardieu 饰）生性狂野不羁，心地善良，他默默地爱慕着表妹罗克珊（安妮•波诺什 Anne Brochet 饰），但是他生来长着一个丑陋的大鼻子，纵使自己才华横溢，也不敢对表妹表明心迹。一天晚上他狠狠地嘲讽并且击败一个富家子之后，罗克珊约他次日见面。西哈诺写好情书后准备表明情愫之时，罗克珊却告诉他自己爱上了英俊的新兵克里斯蒂（文森特•佩雷斯 Vincent Perez 饰），并嘱咐在同一兵队的西哈诺保护他。克里斯蒂也喜欢着罗克珊，西哈诺便将自己对罗克珊的爱慕付诸笔端以克里斯蒂之名送达罗克珊之手，并且巧妙地安排了两人的婚姻。谁知早就对罗克珊心怀不轨的军官见此情景愤恨难忍，将克里斯蒂调去了阿拉斯作战……©豆瓣', '热拉尔·德帕迪约', '让-保罗·拉佩诺', 7.8, 10260, 'tt0099334', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1016937325.jpg', 0.3, 1.5, 26.4, 49.3, 22.5, '0.229555,-0.004271,-0.617351,0.812176,-0.338160,-0.373138,0.824300,0.108820,-0.202284,0.055650,-0.046099,0.593184,-0.236225,0.172272,0.199688,0.206498,-0.174012,-0.782875,-0.067239,-0.350838,-0.000892,-0.447152,-0.339070,-0.187842,0.112120,-0.288040,0.201386,-0.246744,0.123425,0.662735,0.249227,0.212109,0.208761,0.606342,0.036874,-0.121349,-0.153115,-0.082411,0.040875,0.099526,0.154748,-0.102662,-0.039542,0.227359,-0.162510,0.484803,0.529947,-0.216084,-0.072453,-0.137153,0.264090,-0.029054,0.290036,0.471470,0.018129,-0.133640,0.243193,0.167145,-0.121094,-0.080296,0.037508,0.016336,-0.567025,0.128037,-0.138776,-0.087297,-0.654261,0.698849,-0.342416,0.096392,0.013142,-0.342675,-0.113749,0.063919,0.202172,0.067907,-0.077296,-0.039231,-0.181170,0.139302,0.241724,0.025681,0.131494,0.318540,-0.133508,-0.156604,0.321322,0.269483,-0.553899,-0.154142,0.463464,0.186915,-0.132767,0.031411,-0.541300,-0.444084,-0.440618,0.366890,0.130594,-0.596166,0.003945,-0.324283,-0.308616,-0.416102,-0.541256,-0.043220,0.168442,0.015757,0.649314,-0.644894,0.136684,0.615811,0.093528,-0.465478,0.638707,0.484116,-0.042667,-0.084197,0.031553,0.421460,0.173659,0.029378,0.111534,0.597486,-0.104327,-0.026842,-0.296609,0.537339', '1308974', '26677495', '3111650', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297003', '霹雳娇娃2', '动作', '娜塔莉（卡梅伦•迪亚兹 饰）、戴兰（德鲁•巴里摩尔 饰）与艾利克斯（刘玉玲 饰）三位“天使”依然效忠于查理先生，依然到处锄强扶弱。艰巨的任务再次降临她们的身上，她们需要通过一些不同的密码，才能找到失踪的法官。虽然她们极力遵循规定保护所有的证人，可是证人还是不可避免都遇 害了。任务实行困难重重，一名神秘人物——堕落天使（黛米•摩尔 饰）更出手与她们较量。她们远赴了蒙古边境，极力成功完成任务，可是事情并不是那么简单，一个天大的秘密正等待她们面对。©豆瓣', '卡梅隆·迪亚兹', '约瑟夫·麦克金提·尼彻', 6.6, 45179, 'tt0305357', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209217518.jpg', 1.2, 8.8, 56.1, 25.6, 8.4, '0.103752,-0.031300,-0.307165,0.365663,-0.113082,-0.071131,0.500891,-0.276453,-0.254637,-0.601888,0.172645,0.641859,0.044660,-0.321409,0.207932,-0.335118,-0.639467,-0.439330,0.350169,-0.269949,-0.142131,-0.649695,-0.176400,-0.138852,-0.288296,-0.030095,0.754660,0.032480,0.228520,0.340630,0.431223,0.462929,-0.363234,0.235605,-0.097025,-0.437131,0.323905,-0.157983,-0.421777,0.185099,-0.064510,0.265460,-0.196877,0.266071,0.133342,0.216313,-0.006074,-0.531285,-0.148475,-0.140906,0.000395,-0.332540,0.249001,0.285335,0.137410,-0.058358,0.321633,0.405033,-0.007747,0.001161,0.096406,-0.316652,-0.912073,-0.035900,0.435254,0.411080,-0.026789,-0.028514,-0.275183,0.126708,-0.055044,-0.354458,-0.041773,0.404793,0.514649,0.194655,-0.387372,-0.001030,-0.530481,-0.284309,0.455489,0.110995,-0.051522,-0.017049,0.025761,-0.497370,0.036150,-0.251664,-0.332848,0.483982,-0.053521,0.247749,0.270750,0.310668,-0.534395,-0.203238,-0.514692,-0.168198,-0.181611,-0.430180,0.210846,-0.735251,0.121904,-0.002821,-0.425434,0.294244,0.228190,-0.247276,0.563905,-0.772601,0.252185,0.368165,0.489262,-0.691433,0.132927,0.511624,0.569428,-0.513022,-0.213109,0.286398,0.190489,0.190979,0.063378,0.196027,0.049604,-0.073177,-0.152649,0.248087', '27073234', '2369613', '5910040', '3006783');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297007', '闪亮的风采', '剧情', '本片根据澳大利亚钢琴家戴维•赫尔夫戈特（David Helfgott）的真人真事改编。生于犹太人家庭的戴维（Alex Rafalowicz 饰）自幼便展现过人的天赋，他的父亲望子成龙，逼迫戴维苦练钢琴，甚至不切实际地让儿子挑战号称“世界上最难演奏的作品” 《D小调第三钢琴协奏曲》。戴维在父亲的阴影下苦不堪言，而父亲为防止家庭破裂又千方百计阻止儿子外出求学，最终父子走向决裂。长为青年的戴维（Noah Taylor 饰）远赴英国皇家音乐学院求学，在此期间，“拉三”仍然是他心中未了的情结，经过紧张筹备，他终于走向舞台挑战父亲为他设下的攀登极限……影片荣获1997年奥斯卡最佳男主角奖（Geoffrey Rush）。©豆瓣', '杰弗里·拉什', '斯科特·希克斯', 8.4, 11882, 'tt0117631', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2406769198.jpg', 0.3, 1, 14, 47, 37.7, '-0.192911,-0.108839,-0.491342,0.702320,0.143103,-0.401838,0.361797,0.213020,-0.269362,-0.156473,0.426796,0.755571,-0.013235,0.321884,0.498963,-0.063460,-0.305636,-0.736350,-0.042712,0.005064,-0.105420,-0.420058,-0.226820,-0.147562,-0.243151,-0.359537,0.941925,-0.046396,-0.336866,0.371157,0.199074,0.220507,-0.073297,-0.096155,-0.067511,-0.069347,0.135453,0.002022,-0.331004,0.069816,0.063474,-0.471197,-0.221778,-0.062802,-0.057940,0.265467,0.641757,-0.102969,0.377183,-0.189349,0.503958,-0.226121,-0.039912,0.013654,0.082966,0.011149,0.104001,0.407189,0.059230,-0.145934,-0.186423,-0.220262,-0.621548,0.017232,0.262658,-0.226453,-0.620984,0.267738,-0.242826,-0.045484,0.171509,-0.154100,-0.135981,0.136756,0.248967,0.496500,-0.277825,0.241999,0.020726,0.316785,0.495978,-0.045093,-0.121502,0.041793,-0.236136,-0.314210,0.032731,-0.498163,-0.601449,-0.110474,0.132806,0.079712,0.249265,0.175171,-0.160937,-0.227114,-0.393908,-0.013684,0.169465,-0.204694,-0.013972,-0.591899,0.062579,0.074338,-0.051850,-0.282193,0.142193,-0.549793,0.652458,-0.394035,0.331874,0.451457,0.080996,-0.424999,0.636198,0.078747,0.168135,-0.303034,-0.237734,0.571302,-0.298409,0.015636,-0.260381,0.111145,0.037110,-0.271005,-0.334361,0.581462', '30349667', '25880986', '6101834', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297009', '因父之名', '剧情', '这是一个真实的故事。盖瑞（丹尼尔•戴-刘易斯 Daniel Day Lewis 饰）生活于当年战火纷飞的北爱尔兰，那时北爱共和军正致力于反对英国的殖民统治。年轻的盖瑞整日无所事事，偷鸡摸狗，无意间得罪了北爱共和军。无奈之下，其父（皮特•波斯尔思韦特 Pete Postlethwaite 饰）只能送他到英国闯天下。孰料，刚到英国的盖瑞就被当地心急立功的警察诬蔑为北爱共和军的恐怖分子，还连累了在英国的姑妈一家一同被当作恐怖分子关进了监狱。其父四处陈情，最后也被关进了监禁。父子俩在监狱受尽苦头。直到多年之后，一位英国的女律师才开始从头调查这件极其荒谬的冤案。这件冤案最后能否得以平反，父子能否重见生天？©豆瓣', '丹尼尔·戴-刘易斯', '吉姆·谢里丹', 8.8, 36773, 'tt0107207', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p758788727.jpg', 0.2, 0.7, 8.8, 42, 48.4, '0.109037,0.019163,-0.561645,0.369904,-0.136527,-0.585428,0.334798,0.238193,-0.766561,-0.118036,0.140644,0.783965,-0.093792,0.233061,0.332622,0.138421,-0.382111,-0.606136,-0.051322,-0.197728,-0.188544,-0.455345,-0.210434,-0.234303,-0.270024,0.042213,0.281170,0.158371,-0.150877,0.042633,0.365591,0.532807,-0.247277,0.189572,-0.271564,0.138577,0.366004,-0.201084,-0.382390,-0.073971,-0.050086,-0.494474,-0.011069,0.089679,0.101971,0.046894,0.500932,-0.080135,-0.077684,-0.242033,0.375850,-0.335349,-0.164475,0.227646,0.469007,0.004151,0.131413,0.340026,-0.060622,-0.208967,-0.031428,0.029307,-0.521872,0.040384,-0.031692,-0.118997,-0.425748,0.505218,-0.177876,0.250557,0.077193,-0.131636,0.183738,0.538383,0.033244,0.367221,-0.127585,0.145511,-0.462108,0.388053,0.514715,-0.137103,-0.209480,-0.000028,0.026262,-0.153845,0.525474,-0.385766,-0.335903,-0.061865,0.604520,-0.320928,-0.144188,0.365974,-0.322231,-0.221556,-0.563895,-0.119057,0.245037,-0.055815,-0.071182,-0.330355,-0.185022,-0.366249,-0.158140,0.174987,0.164204,0.271530,0.249217,-0.317294,0.385921,0.511380,-0.001974,-0.455641,0.402586,0.247254,0.286273,0.378008,0.060228,0.185117,0.387246,0.454653,0.088102,0.140681,0.150167,-0.365373,-0.213014,-0.035441', '1309069', '1291866', '1307922', '4892342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297012', '老大靠边闪', '喜剧', '纽约黑社会老大保罗（罗伯特•德尼罗 Robert De Niro  饰）深感自己患上了心脏病，虽然体检报告并没有任何征兆，但他还是在老朋友的介绍下，找了离婚的心理医生本（比利•克里斯托 Billy Crystal 饰）治疗。在治疗中，保罗的黑帮作风令本胆战心惊，但是这次交流却让他的焦虑症得以缓解。此后，即使遇到房事的困扰，他都会对本一吐衷肠。不过，正与未婚妻劳拉（莉莎•库卓 Lisa Kudrow 饰）度蜜月的本显然对此准备不足。警方发现了医生与黑帮的关系，派他做卧底。与此同时，保罗也钦点他作为私人医生，形影不离。在闹出很多啼笑皆非的笑话后，保罗和本都从中得到了某种心理补偿……©豆瓣', '罗伯特·德尼罗', '哈罗德·雷米斯', 7.4, 8162, 'tt0122933', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1484311735.jpg', 0.5, 3, 36.7, 46.1, 13.7, '0.219185,-0.192820,-0.645432,0.336146,-0.147376,-0.189171,0.519201,0.119845,-0.592822,-0.483230,-0.048546,0.568576,-0.262218,0.173930,0.334110,-0.172980,-0.308305,-0.620161,0.129860,-0.253131,-0.369751,-0.687457,-0.388963,-0.408740,-0.042683,-0.369229,0.177039,-0.259700,-0.342934,0.451434,0.193785,0.310260,0.273257,0.593881,0.026787,-0.077396,0.071278,0.093208,-0.156818,0.150545,0.550938,-0.274048,-0.086190,0.448119,0.309695,0.803376,0.211475,-0.182522,-0.342429,-0.023383,0.104776,-0.120190,0.176372,-0.022367,0.049592,-0.088026,0.241221,0.382924,-0.160129,-0.067255,0.021425,0.226995,-0.825691,0.271109,-0.065862,0.260849,-0.437253,0.368567,-0.054891,0.038117,-0.266873,-0.200527,0.309707,0.636816,0.183742,0.171012,-0.263242,0.218110,-0.482496,0.083612,0.582168,0.233913,-0.056598,0.258761,-0.397906,-0.370098,0.207216,-0.031786,-0.194250,-0.009344,0.124227,-0.062057,-0.174860,0.082596,-0.323559,-0.217870,-0.344583,-0.102819,-0.273239,-0.403534,0.411436,-0.721442,-0.130762,-0.359237,-0.407369,-0.087895,0.246654,-0.213836,0.478111,-0.810112,0.174648,0.495718,0.315635,-0.699927,0.577404,0.420195,0.005181,-0.174123,-0.251438,0.163615,0.166810,0.389539,0.190778,0.203647,0.478165,-0.409969,-0.270050,0.221044', '35073886', '1307442', '1299035', '1293434');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297018', '冒牌天神', '喜剧', '布鲁斯（金•凯瑞 Jim Carrey 饰）是美国水牛城的一名记者。三十而立的他，不仅没有变得成熟和独立，反而还整天毛手毛脚，弄得自己诸事不顺。布鲁斯还不知自我检讨，总是把一切过错的责任推到别人或上帝身上。还好他的幽默颇受当地观众喜爱，才不致于他被电视台扫地出门。这天，布鲁斯一醒来就霉运就来了：先是在床上烦躁得睡不着，接着女友做的早餐难吃得要命，跟着家里的狗竟然在沙发上撒尿了……布鲁斯忍无可忍，指着天空没完没了地大骂起上帝对他的不公。上帝真的被他从天上骂下来了！上帝允许布鲁斯做一天上帝，管理这个世界。兴奋的布鲁斯发现自己真的无所不能了，他开始了自己疯狂的游戏……©豆瓣', '金·凯瑞', '汤姆·沙迪亚克', 7.7, 205037, 'tt0315327', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165714151.jpg', 0.2, 1.9, 30.2, 50.5, 17.2, '0.276532,0.337582,-0.942113,0.311165,-0.391240,-0.467043,0.532342,0.113949,-0.195923,0.154824,0.277877,0.683526,-0.454721,0.507494,0.234749,0.394772,-0.393173,-0.735177,-0.158286,0.218193,-0.381105,-0.311555,-0.240184,-0.343118,-0.302310,-0.170950,-0.076687,-0.127208,-0.066602,-0.041629,0.374905,-0.126312,0.621399,0.624100,-0.418476,0.237842,-0.080909,0.002748,0.378652,-0.114490,0.200695,-0.360603,-0.073650,0.485499,-0.025754,-0.032497,0.310801,-0.181006,-0.282752,-0.161400,0.614262,-0.371617,-0.099315,0.264370,0.420153,-0.145120,-0.004266,-0.046943,-0.054285,-0.120025,0.247290,0.231341,-0.632127,-0.020975,-0.460504,0.120077,-0.371111,0.327537,-0.293534,0.092910,-0.002218,-0.435961,0.060189,-0.039731,0.065147,0.677163,-0.201087,-0.028887,-0.518202,0.278533,0.396976,0.118425,-0.127631,0.331998,-0.082380,-0.100037,0.027274,-0.148839,-0.405843,-0.316089,0.554411,-0.341277,-0.118131,0.281266,-0.289298,0.075085,-0.102706,-0.453761,-0.317707,-0.164483,-0.301874,-0.095246,0.086690,-0.148636,-0.229540,0.084161,0.127655,-0.101853,0.553372,-0.679180,0.306605,0.832005,0.097175,-0.396136,0.337211,0.242056,-0.139974,0.048102,-0.035664,0.017228,0.015410,0.463955,0.596916,0.511134,-0.056132,-0.015883,-0.274731,0.587986', '1947080', '1309069', '1299292', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297032', '新难兄难弟', '剧情', '时值九十年代的香港，父亲楚帆（梁家辉 饰）讲义气爱吹牛，儿子楚原（梁朝伟 饰）却冷漠实际，二人无法沟通，矛盾不断，母亲（刘嘉玲 饰）夹在二人中间左右为难。中秋节楚帆心软放走匪导致自己受伤昏迷，楚原却借探望父亲的机会又和医院女医生鬼混，女友阿夷（袁咏仪 饰）好心劝慰却无法令浪子回头。 当夜正值木星和月亮交叠，楚原误打误撞掉入一口施工用井中，却重返几十年前和风华正茂的父亲及春风街邻居重新相识。楚原这才知道，原来母亲罗拉当年亦是富家小姐，年轻漂亮却倾心热心英俊的电车厂工人楚帆，两人的爱情被外公百般阻拦……©豆瓣', '梁家辉', '陈可辛', 8, 26951, 'tt0108611', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2454426258.jpg', 0.3, 1.1, 20.7, 52.5, 25.4, '-0.075615,0.014188,-0.517718,0.285616,0.000814,-0.480523,0.736409,0.206352,-0.638511,-0.184014,0.129812,0.464383,-0.048465,0.447040,0.028092,-0.037472,-0.158545,-0.435333,0.164068,0.155842,0.026759,-0.274296,-0.260069,0.190741,-0.136873,0.069727,0.240846,-0.196082,0.112332,0.575466,0.330822,0.156388,-0.465720,0.457158,-0.322020,0.103859,-0.022178,0.382176,-0.527171,-0.174708,-0.080264,-0.267593,-0.046641,0.033123,0.078937,0.473040,0.405721,0.248699,-0.147824,-0.047934,0.386957,-0.069001,0.141994,0.235713,0.388242,-0.102430,0.449731,0.125726,-0.056562,-0.249058,-0.115400,0.042593,-0.230549,0.269701,0.257397,-0.103529,-0.520062,0.438106,-0.103245,0.052649,-0.095213,-0.200913,0.101743,0.266485,0.188244,0.388900,-0.213946,-0.023858,-0.183947,0.227808,0.386330,0.101092,0.008945,0.386732,-0.192087,-0.053304,0.339203,-0.119765,-0.436002,0.022845,0.232986,-0.024615,-0.119990,0.149953,-0.187728,-0.188072,-0.191090,0.415103,0.084132,-0.230876,-0.038980,-0.175469,-0.097291,-0.505778,-0.297514,0.132268,0.144300,-0.064158,0.326859,-0.433533,0.122942,0.349066,0.436612,-0.414494,0.513272,0.384682,-0.135599,-0.434235,-0.004015,0.432594,-0.256473,-0.088077,0.089040,0.185924,-0.142194,0.066153,-0.424869,-0.099107', '3111650', '4728342', '26296258', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297038', '合家欢', '喜剧', '雁南归（许冠文 饰）与远嫁香港的妹妹阿萍（郑雅文 饰）分离多年，虽然阿萍常寄钱物，但雁南归大都用来为村民谋福，自己整日在树林中腾跃劳作，落得快活。这一日，雁南归终于决定奔赴香港，探望妹妹和传闻中富足的妹夫黄嘉范（黄百鸣 饰）。然而雁南归甫一抵达，便发现实情颇有出入，妹妹一家四口与嘉范未嫁的空姐小妹黄嘉玲（王祖贤 饰）挤在一间不大的两居室里，黄嘉范只凭鞋店店员的工作养家。同时，黄家人对雁南归大大咧咧的乡下作风颇感不适，双方硬凑一个屋檐下，惹起诸多矛盾。雁南归经黄嘉范介绍入鞋店工作，但只一天便被老板娘逐出；嘉玲与富商公子的关系不久也被雁南归搞砸。失落之下雁南归参加有奖节目意外获得出国机会，却不幸在旅途中遭遇不测……©豆瓣', '许冠文', '高志森', 7.6, 6137, 'tt0097922', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1958005271.jpg', 0.9, 2.8, 32.1, 45.9, 18.3, '-0.043597,-0.074622,-0.366898,0.250825,0.184199,-0.289562,0.381389,0.140591,-0.471133,-0.234864,-0.072643,0.694097,-0.088148,0.283756,0.362413,0.032897,0.029758,-0.360086,0.210276,-0.208792,0.059570,-0.306241,0.064262,-0.247330,-0.059756,0.030274,0.380551,0.247263,-0.185890,0.629426,0.085916,0.016607,-0.600470,0.458964,-0.401486,0.155644,-0.172651,0.388932,-0.277106,-0.012934,-0.176464,-0.250425,-0.275559,-0.167295,0.457511,0.318721,0.887761,-0.309502,-0.294680,-0.056114,-0.022396,0.088508,-0.165515,-0.088376,0.372050,0.037578,0.456825,0.105900,-0.489883,-0.014204,-0.074330,-0.170439,0.078620,0.240655,0.342850,-0.187991,-0.348824,0.555860,0.087162,0.135865,-0.241783,-0.270047,0.091596,0.298729,-0.092819,0.155340,-0.130672,0.265029,-0.208110,0.364295,0.895057,0.154775,0.341186,0.051723,-0.101681,-0.278058,0.494061,0.015938,-0.455714,-0.073598,0.206242,-0.122014,-0.083959,-0.007385,-0.358553,0.112741,-0.531693,0.297338,-0.050698,-0.366622,0.026721,-0.482887,0.198934,-0.272160,-0.268030,0.295163,0.392813,-0.170380,0.315219,-0.704094,-0.001951,-0.085482,0.319872,-0.533512,0.721260,-0.036849,0.516517,-0.025159,0.060769,-0.030049,-0.041462,-0.136637,0.068635,-0.037921,-0.281407,-0.272599,-0.250869,-0.006186', '26687241', '1291992', '2080130', '20388223');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297050', '007之雷霆谷', '动作', '一天，美国太空船遭到了不明飞行物的攻击，美方怀疑是苏联的阴谋，目的是想独霸太空。美方测出了不明飞行物的降落地点是在日本，于是英国军方派出007（肖恩•康纳利 Sean Connery 饰）前往日本替美方调查此事。由于007的身份特殊，直接进入日本容易被敌人察觉。为了掩人耳目，007先是在香港假死，然后用新的身份进入了日本。另一方面，苏联的太空船也受到攻击，苏联同样认为是美国的阴谋。007在经过一番调查之后，发现整个阴谋的幕后主脑竟然是日本一家化学公司！007能否及时粉碎它的阴谋，化解误会？©豆瓣', '肖恩·康纳利', '刘易斯·吉尔伯特', 6.9, 8409, 'tt0062512', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p737016531.jpg', 1, 6.5, 51.2, 30.5, 10.8, '0.305694,0.290789,-0.755237,0.486254,-0.108802,0.107164,0.080823,-0.205497,-0.654731,-0.397225,0.168932,0.647255,-0.032821,-0.212279,-0.165293,0.002942,-0.255824,-0.516997,-0.227529,-0.220193,-0.395718,-0.711707,-0.424750,-0.399833,0.110075,-0.232738,0.488314,0.513173,-0.575837,0.015687,0.405230,0.806541,-0.265436,0.522137,0.049026,-0.403706,0.165965,-0.556873,-0.563440,0.639697,-0.170224,-0.592696,0.167292,0.391243,-0.226839,0.532899,0.506120,0.120877,-0.271047,-0.419141,0.332068,-0.554140,0.044538,0.068707,0.764007,0.121264,0.064010,0.361084,-0.178372,0.217608,0.207688,0.165561,-0.706644,-0.086260,0.017200,0.071081,-0.311260,-0.104463,-0.329236,-0.099050,-0.196116,-0.137315,0.527930,0.907135,0.494752,0.068043,0.060855,0.509795,-0.563535,-0.281523,0.808316,-0.200726,-0.179893,0.088947,0.148666,-0.305586,0.138641,-0.250702,0.429867,0.076054,0.520255,-0.104601,-0.078031,0.126649,-0.598257,-0.074077,-0.718357,-0.479365,-0.019733,-0.290847,0.349313,-0.867427,-0.193357,-0.197924,-0.375387,-0.044198,0.058338,0.008478,0.363470,-0.759235,0.164401,0.837346,0.372341,-0.696119,0.263514,0.137334,-0.248910,-0.214188,0.074954,-0.096238,0.138845,0.230829,-0.286650,0.080443,0.500601,-0.593971,-0.143522,-0.229449', '1296947', '4193254', '5157137', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297052', '侧耳倾听', '剧情', '正在读初三的月岛雯是一个喜欢看书的女孩，她每次都能在借书卡上看到一个叫天泽圣司名字，因此她对这个人充满了好奇。 雯一直喜欢写诗，有一天她跟好友夕子在讨论写诗的事，夕子告诉雯自己收到了情书，但事实上夕子已有了喜欢的人。更没有想到的是，夕子喜欢的杉村喜欢的是雯，雯一时间感到十分困惑。 雯无意中来到了一个小店，原来店主是圣司的爷爷。认识了圣司之后，听到了圣司对自己理想的追求之后，也激发了雯对自己理想的追求之念。当圣司离开了到意大利学习做小提琴时，雯决定要专心写作。当雯完成了作品之后，她发现原来自己高估了自己，就这样她选择继续考高中，这时她非常想念圣司。 一天凌晨，她站到窗边，突然看到了一个熟悉的身影……©豆瓣', '本名阳子', '近藤喜文', 8.9, 430964, 'tt0113824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456692072.jpg', 0.1, 0.5, 8.3, 35.3, 55.8, '0.564237,-0.037372,-0.915220,0.603641,-0.192521,-0.390011,0.627253,-0.158218,-0.538513,-0.408050,0.012353,0.931158,-0.328930,0.475354,0.346430,0.240563,-0.228202,-0.920123,0.187767,-0.545368,-0.488681,-0.617302,0.372509,-0.058266,-0.261373,-0.288630,0.315483,0.212508,0.007939,0.527027,0.189565,0.162548,0.267828,0.727733,-0.206275,0.148100,0.051176,0.151630,0.273120,0.279614,0.379555,-0.095890,-0.484933,0.421061,0.075381,0.299189,0.571802,-0.138770,-0.554604,0.215443,0.421287,-0.200134,-0.231246,0.026427,0.298129,-0.043547,0.027465,-0.079909,-0.274158,0.005067,-0.316937,-0.049021,-0.643360,-0.009184,-0.034228,0.183639,-0.596377,0.441292,-0.094805,-0.183249,0.347180,-0.378380,0.241734,0.255730,0.143355,0.472101,-0.182194,0.039847,-0.361358,0.109315,0.651818,0.026338,-0.002514,0.920654,-0.122784,-0.146798,-0.012881,0.041054,-0.471145,0.179254,-0.099083,0.212748,-0.216028,-0.428963,-0.405734,0.070247,0.154652,-0.160434,0.147578,-0.539969,-0.413914,-0.112879,-0.154175,-0.440997,-0.299937,0.169583,-0.316213,-0.632447,1.008621,-1.311834,0.100738,0.476096,0.641344,-0.555450,0.802168,0.130385,-0.354346,-0.231824,0.037205,-0.052241,-0.078242,0.037472,0.064381,0.295028,0.239646,-0.247550,-0.623193,0.449718', '1937946', '1292219', '1395231', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297068', '中南海保镖', '剧情', '香港地区一起杀人案的唯一目击证人Michelle（钟丽缇 饰）正被杀手追杀，因为其未婚夫是与大陆高层关系密切的富商，身手不凡的中国特警许正阳（李连杰 饰）便被中央委派去香港保护Michelle。两人初接触时互看两生厌，但慢慢都发现了对方的优点并产生了感情，然而因为身 份和工作性质，许正阳尽量将感情压抑，却免不了在刻意回避时患得患失，就在两人感觉无从择决时，一个异常危险的杀手悄悄靠近了他们。©豆瓣', '李连杰', '元奎', 7.8, 99324, 'tt0111835', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1397968890.jpg', 0.3, 2.1, 28.5, 46.5, 22.7, '0.537407,-0.255149,-0.726776,0.609796,0.010717,-0.153225,0.796173,0.268937,-0.721529,-0.335855,0.235536,0.786000,-0.171902,0.081949,0.162153,-0.222546,-0.146734,-0.862184,0.093037,-0.359197,-0.291675,-0.351154,-0.195522,-0.244940,-0.129121,-0.007767,0.560284,0.151821,-0.330550,0.508463,0.234264,0.073482,-0.341965,0.877316,-0.022977,-0.314814,0.171151,-0.053178,-0.236301,0.000125,0.101694,-0.374098,-0.161602,0.448634,-0.011396,0.611262,0.665869,-0.176316,-0.298367,-0.127388,0.150832,-0.049055,0.184466,0.240127,0.489954,0.145343,0.135676,0.258822,-0.253728,0.124743,0.240097,0.384113,-0.606687,0.342663,0.170531,0.134454,-0.458900,0.448868,0.003976,-0.322187,-0.239031,-0.003712,0.384883,0.391830,0.325727,-0.031926,-0.334524,-0.084980,-0.280799,0.091552,0.634396,0.100276,-0.071896,0.296055,-0.088804,-0.515995,-0.195828,-0.161180,-0.081785,-0.151477,0.266900,0.347376,-0.278940,0.186495,-0.541594,-0.003228,-0.174967,0.049257,-0.478595,-0.589574,0.183356,-0.747816,-0.304642,-0.358154,-0.211168,0.170915,0.131507,-0.086999,0.496443,-0.650085,0.033047,0.717451,0.530814,-0.709783,0.664614,0.258526,-0.050789,-0.363405,-0.209170,0.145972,0.071745,0.257984,0.372493,0.276376,-0.308924,-0.033579,0.139570,0.211415', '1301022', '1293142', '1309297', '1917313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297102', '天生一对', '喜剧', '安妮（琳赛·洛翰 Lindsay Lohan 饰）和荷莉（琳赛·露安 Lindsay Lohan 饰）两个小女孩在夏令营中相识。她们相貌惊人地相似，却非常合不来。十分偶然的，她们知道了对方原来是自己的孪生姐妹。她们开始互相打听对方的生活，讨论自己的父母：他们在一个豪华的航海轮船上相遇，在旅途中就结了婚，然而最后却以感情破裂收场。因为这场离异，双胞胎姐妹一个被爸爸（丹尼斯·奎德 Dennis Quaid 饰）带到加州，生活在一个美丽的葡萄园；一个则被当婚纱设计师的妈妈（娜塔莎·理查德森 Natasha Richardson 饰）带到伦敦。两人因此从未谋面，甚至不知道彼此的存在。得知了这个真相，两个调皮的小鬼开始谋划她们的计策：她们决定调换身份，到对方的家庭去生活。一切都进展顺利，直到父亲要再婚，姐妹俩对后母（伊莲·亨德里克斯 Elaine Hendrix 饰）的一场疯狂狙击大战开始了……本片翻拍自1961年版美国电影《爸爸爱妈妈》。年仅11岁的琳赛·洛翰凭借在片中一人分饰两角的表演，荣获1999年美国“艺术新秀奖”最佳年轻女演员奖。', '琳赛·洛翰', '南希·迈耶斯', 8.4, 173097, 'tt0120783', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2867860412.jpg', 0.1, 0.6, 14.8, 49.2, 35.4, '0.284867,-0.137518,-0.778004,0.496972,-0.196757,-0.318044,0.720968,-0.056976,-0.444609,-0.325763,0.365242,0.838064,-0.273553,0.361155,0.122972,0.056712,-0.280584,-0.713473,0.091650,-0.040512,-0.147675,-0.332075,-0.126494,-0.024751,-0.224574,0.069619,0.538356,-0.307341,-0.028166,0.499116,0.297877,0.049311,-0.169085,0.170153,-0.184688,0.121743,0.216411,0.081460,-0.469974,0.225348,-0.051877,-0.037269,-0.158673,0.049221,0.020774,0.278871,0.814464,-0.137513,-0.024246,0.086009,0.432812,-0.064922,-0.195126,0.316448,0.396294,-0.095370,0.386485,0.007860,-0.091946,0.013720,-0.084255,-0.037656,-0.491101,0.296122,0.173464,0.150534,-0.380328,0.392982,-0.044138,-0.043830,0.100135,-0.358967,0.048969,0.403411,0.172753,0.392927,-0.231090,0.055492,-0.469986,0.271797,0.775255,0.010324,-0.084044,0.432067,-0.180197,-0.435775,-0.072290,-0.202851,-0.679104,0.253532,0.377952,-0.187140,-0.010118,0.281370,-0.580791,0.023986,-0.198872,-0.030925,0.053672,-0.481976,0.011129,-0.620620,-0.327542,-0.590980,-0.447359,0.060757,-0.123651,-0.326222,0.737750,-0.866435,0.107318,0.394435,0.181976,-0.477697,0.518665,0.319456,0.269718,-0.343211,-0.001859,0.368031,-0.155326,-0.211835,-0.082235,0.400747,0.186722,0.103357,-0.429973,0.286373', '1292219', '3811356', '1301022', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297105', '陆上行舟', '剧情', '20世纪初南美秘鲁。痴迷歌剧的白人菲茨杰拉德（克劳斯·金斯基 Klaus Kinski饰）被当地人称为空想家“菲茨卡拉多”。菲茨卡拉多经常做出一些令人无法理解的举动，尤其当他在巴西的亚马逊大剧院欣赏到世界著名男高音卡鲁索的演出之后，居然萌生出要在秘鲁小镇上也修建出一座宏大剧院的疯狂念头。为了获得足够的资金，菲茨卡拉多接受了当地橡胶大亨向他提出到神秘恐怖的乌圭里亚林区进行收割的任务，一段惊险刺激的旅程随之开始。由德国著名导演沃纳·赫尔佐格执导的影片《陆上行舟》，荣获1982年第35届戛纳电影节主竞赛单元-最佳导演奖并入围该届金棕榈奖提名，以及入围1983年第40届金球奖最佳外语片提名。©豆瓣', '克劳斯·金斯基', '沃纳·赫尔佐格', 8.8, 10666, 'tt0083946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2544269037.jpg', 0.5, 1, 9.5, 37.3, 51.7, '-0.011874,0.036657,-0.976318,0.579576,0.212826,-0.218076,0.416734,-0.142854,-0.432762,0.124493,0.195278,1.036895,-0.441123,-0.001845,0.664105,-0.110093,-0.440978,-0.346412,-0.043188,-0.334843,0.063353,-0.407998,-0.436347,0.037312,-0.089734,-0.486967,0.632260,0.070956,-0.120882,0.440138,0.454615,0.171688,0.182010,-0.014293,0.115000,-0.076481,0.639887,0.037987,-0.646711,0.509335,-0.188368,-0.063078,-0.529998,-0.111590,0.147977,0.207378,0.457726,-0.277187,0.147220,0.162848,0.782585,-0.357727,-0.061337,-0.158287,0.095260,0.096074,0.153071,0.248075,-0.035810,0.292250,-0.236182,-0.392064,-0.570474,0.219620,0.170649,0.240678,-0.290594,0.237109,-0.108278,0.054919,-0.205370,-0.304008,-0.044002,-0.012099,0.308505,0.280066,-0.041105,0.155697,-0.172334,0.393749,0.570262,-0.019115,-0.587394,0.151037,0.005748,-0.615618,0.081789,-0.640036,-0.082421,0.106411,0.491669,-0.199897,0.179055,0.218214,-0.497864,-0.036754,-0.064336,-0.735726,0.348944,0.207411,-0.067435,-1.005237,0.287348,0.027678,0.215962,-0.140380,0.300079,-0.478716,0.717994,-0.418688,0.298136,0.692202,0.186156,0.036486,0.564765,-0.001381,0.033058,-0.092976,-0.303111,0.288897,-0.237026,0.207335,-0.183726,0.352291,-0.144045,-0.648966,-0.144687,0.550552', '34961898', '1298911', '3077791', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297110', '睡美人', '爱情', '奥罗拉公主的出生让国王和皇后乐坏了。宴会上他们邀请来十二位仙女，为公主献上祝词。一个没有机会前来宴会的坏心肠仙女，一气之下落下诅咒：她今天受的屈辱都会报应在公主身上，公主会在18岁那年死于纺锤之下。在这个魔咒的笼罩下，国王和仙女都小心翼翼的保护着奥罗拉公主。国王甚至把全国的纺织器具统统没收，以防止公主遇上不测。然而，悲剧还是发生了。奥罗拉在一个古堡里看到了正在纺布的老奶奶，一伸手就被纺锤的魔法击中，美丽的公主顿时沉睡，整个王国都随之陷入沉睡，国王，侍从，甚至猫狗，都落入了巫婆的咀咒。邻国的王子闻说睡美人的故事，决定披荆斩棘前来古堡搭救公主，他的武器除了勇气和毅力之外，还有对奥罗拉公主的真爱。©豆瓣', '玛丽·科斯塔', '克莱德·杰洛尼米', 8.2, 43246, 'tt0053285', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1833029768.jpg', 0.1, 0.8, 18.2, 49.3, 31.6, '0.074933,0.264413,-0.565662,0.898432,0.177621,-0.254898,0.977003,0.028586,-0.155822,-0.286313,0.689337,0.583300,-0.459744,0.185836,0.492542,-0.053055,-0.381375,-0.584541,-0.383976,-0.163287,-0.534878,-0.194192,0.086823,-0.362453,-0.099332,-0.727469,0.370583,-0.109404,-0.061982,0.290187,0.297626,0.103651,-0.060945,0.556832,-0.254933,0.080908,0.036873,-0.065741,0.036266,0.462416,0.138317,-0.225695,0.234406,0.426880,0.075188,0.119170,0.542362,-1.092457,0.421833,-0.351976,0.234314,-0.048241,0.212737,0.554028,0.430741,-0.346464,0.282244,-0.082282,-0.110836,-0.281155,0.575327,-0.176507,-0.336924,0.100889,0.093231,0.276842,-0.668678,0.253599,-0.040176,0.264670,0.174024,-0.348959,0.664218,0.281659,0.131134,0.507990,-0.137257,0.174235,-0.793822,0.145598,0.691626,-0.023277,0.019509,-0.127895,-0.295380,-0.682551,-0.004414,-0.270223,-0.366994,0.003046,0.250945,-0.369875,0.108187,0.621081,-0.474429,-0.347688,-0.388790,-0.172098,0.182435,-0.693427,0.024111,-0.142851,0.201251,0.077756,0.075434,0.671718,0.540810,-0.086420,0.665763,-0.732322,0.542569,0.601788,0.372722,-0.336975,0.722959,-0.059447,-0.117331,0.041496,-0.225349,0.244778,0.114069,0.367026,0.072825,0.505174,0.048104,-0.085352,-0.368993,0.333064', '25767747', '1308366', '5938000', '3012819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297126', '恋恋三季', '剧情', '本片描写了越南风景的三段恋曲：春季，乡下姑娘欣被大户人家雇为采摘白莲花的女工。每天望着荷花荡的风景，她都会跟其他女工哼唱民歌。她的歌声吸引了患麻风病的杜先生。她在为他抄送诗词的时候，两人产生了忘年之交；旱季，三轮车夫海偶然结识了妓女莲。她总在跟他描述星级酒店里的奢华生活，但是他却只是痴望着她。慢慢地，两个人的关系也发生了微妙的变化；雨季，越战老兵詹姆斯（哈威•凯特尔 Harvey Keitel 饰）在酒吧里邂逅了推销小贩伍迪，并从他贩卖的货物里发现了一枚越战时的打火机。詹姆斯对伍迪诉说着他跟妻女失散的离别之苦。此后，两人各自的情感均有所收获……1999年圣丹斯电影节评审团大奖、最佳摄影奖，2000年美国独立精神奖、最佳摄影奖。©豆瓣', 'Ngoc Hiep Nguyen', '托尼·裴', 8.3, 10675, 'tt0138874', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p505934165.jpg', 0.2, 1, 16.2, 50.8, 31.7, '0.308286,-0.252853,-0.614557,0.557390,0.149765,-0.132366,0.790754,0.171812,-0.409085,0.045935,0.152729,0.909136,-0.360668,0.244591,0.132698,0.145944,-0.255721,-0.838892,-0.006366,-0.230924,-0.090840,-0.136867,-0.280940,-0.152252,-0.127527,-0.124085,0.219535,0.193112,-0.185013,0.513675,0.084955,-0.157325,-0.063256,0.559706,-0.324557,0.153085,0.204254,0.206268,-0.025970,0.138059,0.097434,-0.541262,-0.475384,-0.152379,0.277858,0.453399,0.916952,-0.262938,0.084271,0.190758,0.215430,-0.111670,0.210852,-0.094349,0.211756,-0.095048,0.118860,0.059688,-0.150715,-0.002666,-0.069557,-0.117634,-0.331198,0.106433,0.006907,0.205284,-0.584755,0.691158,0.199783,0.167807,-0.145505,-0.113824,0.370166,0.015813,0.066125,0.205000,-0.101446,-0.221098,-0.490802,0.616598,0.485596,0.060481,-0.254416,0.593535,-0.653957,-0.603804,-0.261819,-0.124701,-0.598956,-0.117876,0.464746,-0.012825,-0.102013,0.144730,-0.689433,0.045661,0.044548,-0.124527,-0.265383,-0.186017,-0.109168,-0.761852,-0.006746,-0.549933,-0.406758,-0.088307,0.127877,-0.137584,0.657773,-0.556904,0.164026,0.598926,0.136091,-0.345542,0.804602,-0.108277,-0.010223,-0.017913,-0.373464,0.276272,-0.315085,0.210570,0.301811,0.568496,-0.113180,-0.036160,-0.192085,0.504517', '30162520', '3154392', '3811356', '1294565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297127', '史密斯先生到华盛顿', '剧情', '美国的一个小镇，Jefferson Smith（詹姆斯·斯图尔特 James Stewart饰）是当地的童子军的首领，深受青少年们的喜爱，被选为新的参议员，来到了华盛顿。遇到了他父亲的老朋友，同为参议员的Joseph Paine（克劳德·雷恩斯 Claude Rains饰），并且迷上了Joseph的漂亮女儿。单纯的Jefferson从来没来过华盛顿，在华盛顿闹了不少笑话，被媒体纷纷取笑。Joseph让Jefferson起草一个提案，并让他的女秘书Clarissa Saunders（琪恩·亚瑟 Jean Arthur 饰）协助Jefferson。然而Jefferson却发现，他的这个所谓参议员不过是其他老谋深算的参议员手中的木偶，他发现了他们一个巨大的阴谋。Jefferson决定以自己单薄的力量来对抗那群人，来改变这个腐败的政治环境。到底他能否成功？史密斯先生的华盛顿之旅会如何结束？本片获第11届奥斯卡10项提名，赢得最佳原创剧本一奖。', '詹姆斯·斯图尔特', '弗兰克·卡普拉', 8.6, 10469, 'tt0031679', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2100240855.jpg', 0.4, 0.9, 11.7, 42.5, 44.5, '0.328136,0.062444,-0.775022,0.790014,-0.245162,-0.269927,0.535946,0.053580,-0.531816,-0.338377,0.140853,1.005732,-0.296146,0.282649,0.145414,-0.000809,-0.084693,-0.674012,-0.134256,-0.063796,-0.200499,-0.398828,-0.378707,-0.090004,-0.105359,-0.061518,0.602840,0.033001,-0.027404,0.363871,0.629439,0.247503,0.231486,0.475919,-0.172632,0.116300,0.261143,-0.164586,-0.242228,0.287257,0.053807,-0.162353,-0.219559,0.436306,0.074846,0.440336,0.563438,-0.260562,-0.168665,-0.116125,0.631384,-0.353899,0.111526,0.254377,0.249938,0.081125,-0.088229,0.135371,-0.067631,0.103312,-0.061969,-0.098334,-0.779300,0.103545,-0.028196,0.189107,-0.565304,0.439066,-0.128110,-0.151174,-0.264720,-0.141686,0.196237,0.481808,0.022838,0.174611,0.064587,0.102246,-0.476184,0.273637,0.629564,0.074461,-0.436534,0.253842,-0.253967,-0.544809,0.079206,-0.379513,-0.348060,0.079176,0.400369,-0.250897,-0.018075,-0.046721,-0.552839,-0.170555,-0.367242,-0.165919,-0.010327,-0.484257,0.042243,-0.650297,-0.079968,-0.309096,-0.234342,-0.086882,0.037298,-0.392368,0.782335,-0.780437,-0.010692,0.707068,0.179635,-0.609441,0.558042,0.227561,0.053268,-0.095069,-0.327392,0.089568,0.181552,0.248387,0.095558,0.330206,0.21