INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297128', '人人都说我爱你', '喜剧', '影片从朱娜（娜塔莎·雷昂 Natasha Lyonne 饰）的视角出发，展现了一个大家庭中的成员追求真爱的幸福光景。准姐夫霍尔顿（爱德华·诺顿 Edward Norton 饰）一直想找机会向生性浪漫的表姐斯凯勒（德鲁·巴里摩尔 Drew Barrymore 饰）求婚，而后者似乎迷 上了一个有前科的犯罪分子菲利（蒂姆·罗斯 Tim Roth 饰）。生父乔·柏林（伍迪·艾伦 Woody Allen 饰）走出上一段婚姻后一直都保持着单身的状态，直到有夫之妇赛迪尔（朱莉娅·罗伯茨 Julia Roberts 饰）出现，尽管朱娜极力撮合生父与赛迪尔的这段姻缘，但真正的结果只有乔自己能够掌控。妹妹劳拉（娜塔丽·波特曼 Natalie Portman 饰）暗恋着一个几乎不曾有过交流的男生。至于朱娜自己呢，曾经夸下海口绝不谈恋爱的她，居然闪电般地坠入了与一名威尼斯小伙的爱河之中。爱情就是这样可遇不可求，圣诞节就要来了，这群快乐又善良的人们能否在这个合家团圆的节日之中找到自己的真爱呢？', '伍迪·艾伦', '伍迪·艾伦', 7.4, 27498, 'tt0116242', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2228938927.jpg', 0.4, 3.1, 36.6, 45, 14.9, '0.369515,0.011309,-0.555431,0.627259,-0.214927,-0.594421,0.745154,-0.028630,-0.288294,-0.311189,0.076587,0.589986,-0.272935,0.514323,0.385283,0.299744,-0.470006,-0.716106,0.095494,-0.230270,-0.196475,-0.409531,-0.409584,-0.014874,-0.101385,0.093952,0.416192,-0.059632,0.036602,0.235402,0.310056,0.292957,0.213290,0.228743,-0.126345,0.027630,0.156618,0.047232,-0.394899,0.143008,0.114640,-0.048700,-0.102469,0.255099,0.066594,0.232765,0.487969,-0.490681,0.315950,-0.147607,0.315322,-0.063379,0.208079,0.199463,-0.128237,-0.300521,0.353841,0.022559,-0.101791,-0.066760,0.212600,-0.289435,-0.512630,0.156447,0.043090,0.112169,-0.359030,0.272247,-0.079992,-0.060468,0.221399,-0.303038,-0.055819,0.417839,0.376684,0.277458,-0.284915,0.008027,-0.418109,0.111813,0.431120,0.043075,-0.305465,0.178871,-0.317719,-0.568630,-0.115007,-0.030352,-0.743740,-0.124204,0.398230,-0.015348,0.059489,0.413287,-0.516259,-0.050301,-0.243180,0.095015,-0.038604,-0.390598,-0.186869,-0.598641,-0.040349,-0.518838,-0.225066,0.124509,0.000359,-0.392535,0.429005,-0.704939,0.256950,0.375571,0.202329,-0.474251,0.807560,0.390871,0.014648,-0.201630,-0.022691,0.672092,-0.027825,-0.124910,0.062352,0.245809,0.053467,0.076425,-0.344501,0.605641', '3055049', '26809592', '3033092', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297131', '圣诞夜惊魂', '动画', '万圣镇的各位鬼怪，已经习惯于在每年万圣节那天出没搞作一下，他们是彻头彻尾的少根筋的生物，只晓得如何吓人。而南瓜王子杰克，是非常与众不同的一个。他已经厌倦了带给人们惊恐的玩意，一心想做出某些改变。偶然一次打开了圣诞镇的大门，让他眼前豁然一亮，杰克心中燃起了要带领兄弟制造圣诞欢乐的决心。但是，这帮万圣镇的鬼怪们似乎并不明白其中深意。杰克绑架了胖乎乎的圣诞老人，吩咐伙计们开始埋头制作圣诞礼物。满脑只有恐怖点子的万圣镇兄弟，又怎能逃过思维惯性，做出令人欢乐的礼物呢。于是，恐怖的、吓人的礼物将在圣诞那夜抛给孩子们，当杰克坐着人造鹿车派出礼物时，一枚高射炮正对准了这个好心办坏事的可怜虫。©豆瓣', '丹尼·艾夫曼', '亨利·塞利克', 8.2, 103368, 'tt0107688', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p470366787.jpg', 0.2, 1.6, 19.1, 43.8, 35.2, '0.532149,0.054958,-0.439561,0.298268,-0.123038,-0.015306,0.696696,0.049497,-0.389105,-0.076331,0.128957,0.563761,-0.390718,0.354518,0.140821,0.189556,-0.292627,-0.234145,-0.209025,-0.056629,-0.149770,-0.303923,-0.288664,-0.394543,0.089963,-0.114274,0.120026,0.156627,0.046626,0.397578,0.507627,0.164579,0.093118,0.404996,-0.301911,-0.038532,0.016831,-0.055542,0.192354,0.030707,-0.079901,-0.201133,-0.201924,0.424185,-0.005171,0.269592,0.543797,-0.524195,-0.438084,-0.200189,0.254664,-0.296896,-0.065130,0.241763,0.079784,0.143755,0.020022,-0.168034,-0.096716,0.173931,0.010783,-0.040165,-0.625921,0.097262,0.013487,-0.075665,-0.672971,0.215640,0.074482,-0.010797,0.203045,-0.283651,0.343928,0.259108,0.156702,0.335098,0.023249,-0.038153,-0.382333,0.074315,0.719777,-0.149638,-0.067699,0.387431,-0.238276,-0.210648,0.037757,0.089112,-0.159316,0.104950,0.500539,0.018854,-0.056073,0.208055,-0.647352,-0.077385,-0.205259,-0.367228,-0.012556,-0.392673,-0.318265,-0.319050,-0.016505,-0.073409,-0.248651,0.109177,0.301619,0.018343,0.822550,-0.588617,0.190342,0.493592,0.001733,-0.335851,0.465014,-0.004724,-0.147902,-0.037091,-0.223745,-0.393605,0.073142,0.355957,0.091758,0.433590,0.069644,-0.236298,-0.124174,0.479795', '4181031', '2053515', '1302661', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297141', '义盖云天', '喜剧', '港生（王祖贤 饰）从大陆偷渡至香港，一路颠簸还被蛇头欺辱，搏斗过程中将蛇头打伤才逃脱出来，但外面的世界同样令她感到陌生惶恐。她起初预备投靠自己的姨妈，却遭到姨妈拒绝且冷言讽刺港生，而姨父则垂涎其美色，港生只得离开姨妈家再次流落街头。督查何定邦（周润发 饰）和祥仁（吕方 饰）追捕白粉雄，白粉雄驾车冲出街道撞倒了路边的港生。港生在医院苏醒以后害怕身份败露被送回大陆，灵机一动谎称自己脑部受伤得了失忆症，还“认准”何定邦就是其丈夫伟雄。心性善良的定邦只得将港生接回家中暂住，二人关系日渐改变，但港生“偷渡客”的身份却像两人关系中的定时炸弹时时刻刻存在着……©豆瓣', '周润发', '罗文', 6.9, 6302, 'tt0092260', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2346935659.jpg', 1.6, 6.7, 50.9, 29, 11.8, '-0.001885,0.221179,-0.703588,0.374009,0.101483,-0.003263,0.517928,0.314815,-0.346187,-0.218590,0.270248,0.439703,0.036234,0.365225,0.034980,0.234247,-0.043518,-0.488635,0.078291,-0.174792,-0.192281,-0.070541,-0.149695,0.008880,-0.230806,-0.339876,0.386164,0.157325,-0.358436,0.443041,0.301558,0.189689,-0.467036,0.586558,-0.205214,0.153837,-0.280306,-0.017068,-0.235631,-0.236957,0.064678,-0.241296,-0.026830,0.165646,0.056821,0.404228,0.673253,0.069524,-0.084035,-0.336831,0.222103,-0.197671,0.009857,-0.021146,0.561942,-0.091838,0.105752,0.129765,-0.096806,0.322713,0.210268,0.352707,-0.317469,0.265444,0.118237,0.098278,-0.590808,0.083488,-0.219401,0.043409,-0.341417,-0.208802,0.287275,0.101576,-0.103478,0.363978,-0.146150,0.264077,-0.381087,-0.161290,0.520478,-0.030827,-0.196625,-0.017437,-0.225471,-0.102509,0.378384,-0.290151,-0.300202,-0.109178,0.334437,0.018713,-0.377708,0.123190,-0.144803,-0.045764,-0.502426,0.214064,-0.095134,-0.147748,0.035806,-0.359299,0.032015,-0.263038,-0.183891,0.046842,0.044546,-0.027380,0.335166,-0.200540,-0.016876,0.290081,0.676007,-0.534016,0.254566,0.052703,0.119876,-0.042170,-0.078607,0.393887,0.120141,0.122217,-0.057932,-0.008786,-0.191063,-0.034921,-0.172879,0.133261', '25837175', '3011051', '4832825', '1300958');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297145', '无懈可击', '悬疑', '迈克尔·法拉第（杰夫·布里吉斯 Jeff Bridges 饰）是一名乔治华盛顿大学的历史系教授，单独抚养着9岁的儿子，他的妻子原是FBI探员，前不久死于一次执勤。最近，迈克尔家街对面搬来了一户新人家，奥利弗（蒂姆·罗宾斯 Tim Robbins 饰）和雪柔（琼·库萨克 Joan Cusack 饰）以及他们的儿子布雷迪。然而不知是由于正在讲授恐怖组织一课的职业惯性还是第六感作祟，迈克尔总是对这户新邻居心存怀疑，当然，周围没有一个人相信他的荒谬推理。迈克尔开始对奥利弗一家明察暗访，渐渐发现了原来奥利弗一直在用假身份生活，家族史也颇有疑点，但是奥利弗和雪柔的警惕始终让迈克尔的调查寸步难行。直到一天，迈克尔的女友无意在奥利弗的车后发现了一只可疑的包裹，然而就在他们还来不及弄清楚事情原委的时候，谋杀已经笼罩了这座城市……©豆瓣', '杰夫·布里吉斯', '马克·佩灵顿', 7.6, 17315, 'tt0137363', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p811670078.jpg', 0.7, 3.2, 29, 50.2, 16.9, '0.266589,-0.274502,-0.679972,0.538301,-0.148442,-0.368970,0.733697,0.048471,-0.687495,-0.578155,0.180206,0.708012,-0.171447,0.372834,0.231955,0.129109,-0.398514,-0.563946,0.107987,-0.338869,-0.322601,-0.815139,-0.369030,-0.436220,0.063565,-0.341747,0.287132,-0.071741,-0.132552,0.332101,0.337570,0.248337,0.030363,0.438522,-0.183843,0.110442,0.448991,-0.093930,-0.058757,0.008234,0.113799,-0.185692,-0.229480,0.123752,0.136496,0.603632,0.462230,-0.199433,-0.300780,0.197522,0.120798,-0.200893,0.068666,0.135947,0.522756,-0.209309,0.124600,0.280010,-0.138109,-0.120146,0.068693,0.002735,-0.566493,0.112051,0.040470,0.228892,-0.562488,0.328708,-0.180775,-0.123690,-0.042164,-0.402216,0.178159,0.303367,0.081019,0.339639,-0.014262,0.019665,-0.469880,-0.113387,0.450736,0.061644,-0.080502,0.368601,-0.251082,-0.269644,-0.196861,0.133078,-0.615897,-0.024836,0.279696,0.065865,-0.166876,0.135370,-0.295194,-0.116341,-0.311682,-0.235151,-0.059550,-0.358395,-0.009487,-0.416842,-0.191037,-0.308440,-0.275802,0.005944,-0.107347,-0.183491,0.453303,-0.822512,0.367589,0.481418,0.095373,-0.324625,0.646577,0.179214,0.030785,-0.293170,-0.322034,0.108551,0.252815,0.134087,0.074726,0.462237,0.236586,-0.420627,-0.274758,0.385860', '1302384', '1293145', '10546747', '17