INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297147', '同窗之爱', '剧情', '故事发生在1930年的英国，于伊顿贵族学校就读的盖伊·班尼特（鲁伯特·艾弗雷特 Rupert Everett 饰）是个同性恋者，他的好友贾德（柯林·菲尔斯 Colin Firth 饰）是名共产主义者，对资本主义深恶痛绝，对学校规章制度更是不屑一顾。学校里的同性恋风气蔓延，一名叫马提诺的学生与另一名男同学发生关系时被发现，随后马提诺上吊自杀。此事给盖伊以及整个学院都造成了不小的影响。不久后，盖伊爱上了同校的詹姆斯（加利·艾尔维斯 Cary Elwes 饰），两人常常在夜里约会。然而有一天事情败露，盖伊为了保护詹姆斯，而独自接受了鞭责，同时他的最高年级长的位置也被取代。严格的校规和保守的道德观使他对自己在英国的事业前途感到失望。二十年后，盖伊从英国外交部投奔共产主义国家苏联，成为“叛国"者，轰动英国朝野。本片原为轰动英伦的舞台剧，取材自三十年代的真人真事。主角盖伊·班尼特的原型为“剑桥五杰”之一盖伊·伯吉斯。', '鲁伯特·艾弗雷特', '马雷克·卡尼耶夫斯卡', 7.8, 12246, 'tt0086904', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2608457478.jpg', 0.2, 1.5, 25.9, 50.7, 21.7, '0.435660,-0.150267,-0.663173,0.661433,0.074946,-0.260304,0.433109,0.132128,-0.585448,-0.438282,0.021342,0.885236,-0.387614,0.240373,0.415768,-0.155527,-0.169237,-0.792816,-0.123351,-0.449805,-0.351911,-0.603651,-0.044269,-0.355504,-0.375355,-0.477949,0.430835,0.006778,-0.284889,0.437628,0.473850,0.514974,0.368493,0.172916,0.057158,0.010978,0.300983,-0.059570,-0.208035,0.177028,0.035458,-0.067117,-0.115769,0.112022,0.047768,0.231228,0.556227,-0.108697,-0.055093,-0.274464,0.572796,-0.295869,-0.100629,0.104733,0.733132,-0.162842,-0.008459,0.437165,-0.039798,-0.026496,0.282403,-0.252505,-0.355311,-0.034501,0.091024,0.150254,-0.472831,0.553512,-0.267085,-0.236389,0.094321,0.056087,0.033098,0.395651,0.210335,0.446784,0.163178,0.130873,-0.279929,0.005489,0.592490,-0.132297,-0.482415,-0.049849,-0.391952,-0.453614,0.033400,-0.243751,-0.396843,-0.039800,0.186716,-0.178446,0.071250,0.459261,-0.441492,-0.196059,-0.210678,-0.341661,-0.125547,-0.286489,-0.043024,-0.466637,-0.075283,-0.462350,-0.187469,0.017309,0.133914,-0.115031,0.602472,-0.795593,0.320859,0.392575,0.226053,-0.543029,0.674167,-0.070904,0.278820,-0.130210,-0.135684,0.207638,0.197458,0.157963,0.076872,0.311461,0.068735,-0.346258,-0.107314,0.509526', '30162520', '1303449', '1292720', '2245683');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297148', '超时空要爱', '喜剧', '警察刘一路（梁朝伟饰）某天在路上突然接到一个电话，告诉他千万要劝阻“那个”女孩自杀，因为女孩的生死会成为他人生的转折点。刘一路对这通电话感到莫名无比，而就在这时，两个流氓Gigi（李绮虹饰）大飞（刘以达饰）在街上枪战，刘一路喉部误中大飞子弹。被送到医院抢救后，刘一路灵魂出窍，遇上了一个身无寸缕的少女，一番言语后，刘一路却突然重返人间，但刚才的少女已经躺在他身边死了。刘回想起之前的奇怪电话，突然觉得这也许就是上帝的启示，于是，他决定仔细调查少女的死因。原来，少女是被富豪曹强奸后割腕自杀，而重要的证人Gigi和大飞也欲为富豪所灭口，开始了逃亡生涯。刘一路为了追随两人，居然回到了三国时代？©豆瓣', '梁朝伟', '黎大炜', 7, 18597, 'tt0163581', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p986340147.jpg', 1.6, 8, 40.9, 36, 13.5, '-0.012320,0.149173,-0.752719,0.557723,-0.133092,-0.576457,0.916407,-0.071871,-0.619043,-0.433285,-0.106684,0.547514,-0.469882,0.489319,0.518558,-0.275099,-0.196492,-0.664967,-0.202814,-0.109068,-0.573717,-0.174459,0.157460,-0.359142,-0.074667,0.104046,0.269353,0.368493,-0.274427,0.456615,0.474130,0.362150,-0.134884,0.723531,-0.161772,0.287408,0.096608,0.142643,-0.078473,0.040554,0.513641,-0.682453,0.041434,0.167519,-0.262699,0.206594,0.567097,-0.114761,-0.291382,-0.034679,0.391591,-0.219398,-0.071295,-0.068469,0.508180,-0.028511,0.217287,-0.392866,-0.052407,-0.262997,0.266682,-0.011655,-0.358688,0.067737,-0.305260,0.098478,-0.567624,-0.173928,-0.109719,0.350039,0.208899,-0.470934,0.572266,0.365101,0.409982,0.473122,-0.067993,-0.084862,-0.466385,0.280546,0.750029,0.089426,0.085426,0.377789,0.006437,-0.674969,0.011420,0.342917,-0.275498,0.198243,0.636926,-0.067339,-0.130878,-0.181009,-0.183095,-0.292437,-0.137763,-0.046517,-0.237192,-0.404886,-0.153425,-0.226414,0.038676,-0.268302,-0.139969,0.438802,-0.057520,0.007864,0.350800,-0.722766,0.315562,0.515117,-0.023465,-0.719699,0.490781,-0.046660,0.137168,-0.114455,0.426618,0.279247,0.323651,0.454486,0.322449,0.431304,-0.363161,0.026534,-0.343086,0.282212', '25870679', '1293142', '1309125', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297151', '星球大战3：绝地归来', '动作', '银河帝国再建威力更大的新“死星”，试图彻底消灭抵抗力量。卢克•天行者（马克•哈米尔 Mark Hamill 饰）派机器人R2-D2和C-3PO前往塔图因星贾霸处协商交换被冷冻的韩•索罗（哈里森•福特饰）未果；后在莉亚公主（卡里•费什尔 Carrie Fisher 饰），猿人丘巴卡（彼得•梅林 Peter Mayhew 饰）和蓝多•卡瑞辛（比利•迪•威廉姆斯 Billy Dee Williams 饰）的帮助下终于营救成功。在尤达师傅处，卢克发现了更多关于自己身世的秘密，也终于决定迎接成为一个绝地武士的终极挑战。卢克回到抵抗组织参与攻打“死星”行动，与韩•索罗，莉亚公主，丘巴卡，机器人R2-D2和C-3PO共同前往森林密布的恩多星破坏“死星”防护罩的能源站，与此同时蓝多•卡瑞辛驾驶千年隼飞船带领各部施展航空打击。没曾想卢克一行人刚踏上恩多星，就遭遇当地部落伊沃克人，莉亚公主也不知所踪……本片获第56界奥斯卡视觉效果特殊贡献奖，并获最佳艺术指导-布景，最佳声音剪辑，最佳原创电影音乐及最佳音效四项提名。', '马克·哈米尔', '理查德·马昆德', 8.4, 89547, 'tt0086190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p847596881.jpg', 0.3, 1, 14.8, 45.6, 38.2, '0.004438,0.136191,-0.501351,0.648951,0.360023,-0.172664,0.249286,-0.005807,-0.046842,-0.444418,0.007043,0.493136,-0.037702,-0.144639,0.289632,-0.204631,-0.487457,-0.290783,0.023080,-0.061884,-0.391764,-0.477066,-0.131121,-0.201744,0.060687,-0.553414,0.696202,0.106485,-0.307462,0.270398,0.301768,0.350111,-0.247731,0.211928,0.177740,0.107453,0.453966,-0.220778,-0.355322,0.465548,-0.375751,-0.034408,0.020844,0.106196,0.175736,0.250603,0.486188,-0.536477,0.320844,-0.052876,-0.114671,-0.311825,0.284095,-0.105321,0.373834,-0.246518,-0.047778,0.114228,-0.095027,0.165433,0.014249,-0.295969,-0.673942,0.019603,0.112957,-0.169362,-0.535372,-0.192491,-0.216095,0.147089,0.032930,-0.046784,0.196089,0.562395,0.340879,-0.025346,0.091360,0.130883,-0.130990,0.059611,0.290605,-0.222964,-0.246408,-0.055642,0.141928,-0.724558,-0.088291,-0.191210,-0.037672,-0.072829,0.476375,0.089997,0.466732,0.093801,-0.629346,-0.058389,-0.592930,-0.263259,0.058446,-0.220829,0.293818,-1.028762,0.056082,0.114582,0.058932,0.146014,0.036656,-0.067700,0.352086,-0.479311,0.372764,0.096213,0.274910,-0.253917,0.221796,-0.134743,0.089024,-0.368424,-0.037686,0.348579,0.152585,0.295251,