INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297187', '刮痧', '剧情', '电脑游戏设计师许大同（梁家辉 饰）与妻子简宁（蒋雯丽 饰）在美国奋斗了8年，事业有成。一次意外却令美好的家庭变得愁云惨雾：5岁的儿子生病了，老父亲（朱旭 饰）用传统的中国民间刮痧帮孙子治病。大同夫妻继而被控告虐待儿童，一个又一个物证人证令夫妻俩百口莫辩，西医根本无法了解这种传统中国疗法。因为这件事，父子与夫妻都不得已的分开了。大同伤心欲绝，面对儿子与妻子，他能做什么为自己伸冤呢？事情又能否得到圆满的解决呢？©豆瓣', '梁家辉', '郑晓龙', 7.5, 33417, 'tt0297928', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2160415384.jpg', 0.4, 2.3, 31.9, 51.7, 13.7, '0.120850,-0.337323,-0.301860,0.461806,-0.121775,-0.364679,0.394996,0.138679,-0.651919,-0.400236,-0.070109,0.624001,-0.000661,0.327153,0.054003,-0.069361,-0.035997,-0.623434,0.295165,0.020206,-0.248367,-0.405901,-0.224889,-0.389558,-0.138418,0.058211,0.352408,0.042776,0.089346,0.271580,0.271915,0.207443,0.111380,0.117494,-0.040392,0.005048,-0.049769,0.322233,-0.531847,0.028569,0.264160,-0.170354,0.070490,0.319273,-0.103815,0.403511,0.495402,0.004345,-0.210994,-0.302089,0.478206,-0.110139,-0.008473,0.341773,0.009497,-0.008929,0.412491,0.342331,-0.088739,-0.139481,0.096845,0.116127,-0.725744,-0.003622,0.203697,-0.271505,-0.520335,0.205826,-0.197527,-0.089252,0.011291,-0.339790,0.426519,0.849485,0.347714,0.801557,-0.491960,0.055381,-0.498654,0.664009,0.616642,0.034061,-0.036247,0.280662,-0.263747,-0.422747,0.221572,-0.484617,-0.545325,0.212112,-0.011296,-0.103807,-0.131752,0.297950,-0.204741,-0.076625,-0.272244,0.117617,0.091028,-0.357898,0.187026,0.037886,-0.040425,-0.278810,-0.359545,0.006432,0.381876,-0.277761,0.636903,-0.480483,-0.119927,0.272783,0.364561,-0.831300,0.535997,0.415129,0.332094,-0.388062,-0.099761,-0.023181,-0.101597,0.056705,0.035511,0.110360,0.205843,0.045682,-0.183759,0.086379', '26678784', '1877596', '1309033', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297188', '自由的幻影', '剧情', '本片由几个超现实的小故事串联而成。公园里，一个神秘男子塞给一个中产阶级家庭的女孩几张图片，女孩父母对这些帕特农神庙、凯旋门等古建筑的图片大惊失色。丈夫晚上被幻觉困扰求助医生，恰巧女护士请假离去，在回家的路上，女护士偶遇受虐狂帽商、赌博的神父等人。一位教授搭护士的车来到警局授课，却总被打断，他最后讲了一段赴宴的经历，几个朋友在马桶上闲聊，而吃饭却在厕所一样的单间里。一名罹患癌症的男人被告知女儿失踪，虽然女儿就在身边，但一群人仍然四处寻找。一名枪手在高层建筑里随意射杀路人，被判处死刑，但看起来却像是当庭释放。警察局长接到了死去的妹妹电话，他前往墓地查看，却发现自己的位置已经被别人代替……本片获1975年意大利电影新闻记者协会银兔奖。©豆瓣', '阿德里娅娜·阿斯蒂', '路易斯·布努埃尔', 8.6, 12345, 'tt0071487', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1563624888.jpg', 0.3, 1.2, 10.5, 43.7, 44.2, '0.393868,-0.050176,-0.347595,0.352477,-0.186223,-0.283758,1.032692,0.138498,-0.422524,-0.365603,0.311210,0.781876,-0.319263,0.447071,0.346688,-0.048650,-0.255008,-0.449016,0.077663,-0.088203,-0.457168,-0.143324,-0.057019,-0.215066,0.014346,-0.237590,0.292759,-0.185438,-0.054806,0.408873,0.112641,0.013836,-0.362903,0.403728,-0.265223,0.132990,0.203274,-0.098794,0.076680,0.238590,-0.078051,-0.311530,-0.111141,-0.077848,-0.039381,0.256311,0.650350,0.079396,-0.129576,0.055977,0.245443,-0.167488,-0.074136,0.107870,0.492283,0.239123,0.359414,0.077763,-0.181129,-0.003770,0.008304,-0.102955,-0.319398,0.139575,-0.106000,0.283868,-0.587452,0.503999,-0.018881,0.195224,-0.097316,-0.268642,0.443117,-0.113839,-0.041104,0.604862,0.042592,-0.059951,-0.479833,0.237252,0.340672,-0.125727,-0.023398,0.281875,-0.116960,-0.255049,0.203849,0.138196,-0.543254,0.150427,0.244659,-0.420293,-0.405457,-0.347505,-0.397048,0.036245,-0.409692,-0.083123,-0.161234,-0.377659,-0.235365,-0.748709,0.180313,0.245437,-0.202446,0.207553,0.087954,0.061920,0.671825,-0.356838,0.256002,0.533726,0.252040,-0.377474,0.811651,-0.097642,0.099545,-0.170249,-0.026627,0.188002,0.409407,0.429350,0.017689,0.369115,-0.464975,-0.125448,-0.506723,0.183379', '10466639', '1296534', '21619567', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297192', '致命ID', '剧情', '一个典型而又引人入胜的悬疑故事：一个汽车旅馆里，住进了10个人，他们中间有司机、妓女、过气女星、夫妇、警探和他的犯人，还有神秘的旅馆经理。这天风雨大作，通讯中断，10人被困在了旅馆里，惊悚的故事开始了。他们一个接一个的死去，并且按照顺序留下牌号。10个人存活下来的渐渐变少，他们开始恐慌，互相猜忌，却无意间发现了彼此间的联系。但是，大家怀疑的嫌疑人却纷纷死去，谜团笼罩在旅馆狭小的空间里，这样的凶杀案件却有着人们猜不到的真相……©豆瓣', '约翰·库萨克', '詹姆斯·曼高德', 8.8, 760739, 'tt0309698', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2558364386.jpg', 0.2, 0.5, 8.1, 39.3, 51.9, '0.580324,-0.002658,-0.702188,0.482310,0.008029,-0.055186,1.266758,0.097585,-0.629295,-0.163125,0.267684,0.762637,-0.373757,0.348050,0.085398,-0.101439,-0.505109,-0.508483,-0.079683,-0.394222,-0.273580,-0.411832,-0.334905,-0.539777,0.001842,0.056761,0.345898,0.291330,-0.074554,0.309438,0.170646,0.028292,-0.423778,0.664320,-0.101510,0.227331,0.068224,-0.081242,0.007758,0.123611,-0.200959,-0.062021,-0.059902,0.144937,-0.140621,0.691244,0.601077,-0.180989,-0.410538,0.209161,0.388708,-0.021578,-0.518420,0.056361,0.475891,0.065235,0.401058,0.015919,-0.221646,-0.108437,-0.178662,0.336704,-0.664881,0.136124,0.111664,0.507481,-0.400541,0.424410,-0.039378,-0.141691,-0.209985,-0.321548,0.410406,-0.055189,0.209378,0.307696,-0.110207,-0.211127,-0.515823,0.017883,0.733735,-0.185496,-0.444793,0.274047,-0.338654,-0.451003,-0.153799,0.159683,-0.389166,-0.089843,0.442610,0.058517,-0.187247,0.001218,-0.774511,-0.024905,-0.050965,-0.107924,-0.329083,-0.512028,-0.289734,-0.489421,-0.286173,0.050036,-0.214638,0.226688,0.028516,-0.081372,0.650816,-0.629588,0.239185,0.515167,0.161153,-0.399073,0.595905,-0.098095,0.331154,-0.075687,-0.165754,-0.049339,-0.017314,0.575244,0.185822,0.496515,-0.349380,-0.035685,-0.515654,0.141480', '20451118', '21619567', '1296534', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297194', '杀手之王', '喜剧', '一名老人在中日战争时期被日本财阀杀害了全家，故此他请了世界第一杀手刺杀财阀。财阀被杀后，他生前设立的复仇基金启动了，查出并杀死幕后指使者的人能得到一亿基金。全世界的杀手都对这笔基金虎视眈眈，就连财阀的孙子都找来世界第二号杀手灰狼寻找真凶。鳄佬（曾志伟 饰）与小富（李连杰 饰）是杀手群中的一对拍档。身手不凡的小富希望能赚钱回老家，刚好被骗子鳄佬利用了他的身手，两人合作致力得到高额基金……©豆瓣', '李连杰', '董玮', 6.8, 26309, 'tt0163818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2354816016.jpg', 0.7, 6, 53, 31.3, 9, '-0.159736,-0.083670,-0.425533,0.361179,-0.201130,-0.085301,0.119622,0.003327,-0.348932,-0.032983,0.327792,0.706896,0.220777,-0.067876,0.375635,-0.033095,0.286579,-0.542879,-0.101141,-0.276443,0.003400,-0.322267,-0.411338,-0.417796,-0.100435,-0.183127,0.765220,0.185629,-0.142025,0.191817,0.348049,0.270024,-0.089972,0.172023,-0.342666,-0.121286,0.386801,-0.243128,-0.420579,0.528277,-0.396712,-0.204475,0.187594,0.250989,-0.109231,0.335304,0.386655,-0.339414,0.242693,-0.622570,0.136551,-0.320873,-0.190067,0.028252,0.733783,-0.069486,0.420762,0.578002,0.000174,-0.260346,0.178765,-0.141587,-1.096941,-0.185157,0.446714,-0.037600,-0.855627,0.152063,-0.268678,0.106512,-0.150291,0.021316,0.433477,0.251860,0.263163,0.251649,0.197607,0.332791,-0.800368,0.421004,0.452190,-0.254418,0.019828,-0.074980,0.331226,-0.562111,-0.102273,-0.465973,0.067239,0.007287,0.726890,-0.394633,-0.310608,0.007381,-0.507616,-0.164148,-0.282160,-0.197885,0.280757,-0.518950,-0.058145,-0.477037,-0.005043,0.025483,0.189742,0.168333,0.391737,-0.277620,0.768304,-0.730537,-0.168982,0.838549,0.633083,-0.649217,0.705608,-0.325314,-0.039658,-0.293042,-0.284291,-0.276012,0.628763,0.236809,0.140455,-0.103523,0.032907,-0.361753,0.444099,-0.033988', '1793491', '27009869', '30396443', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297203', '着魔', '剧情', '马克（Sam Neill 饰）的妻子安娜（Isabelle Adjani 伊莎贝尔•阿佳妮 饰）未留下任何原因离家出走，他一度认为安娜与一个名叫海恩里克（Heinz Bennent 饰）的男人有染，却发现海恩里克也在寻找许久未见的安娜。马克于是雇佣私家侦探调查。但随着线索的逐一呈现，事实的真相反倒令马克等人难以置信。安娜所耽恋的对象竟然是……本片分别荣获1982年戛纳国际电影节和法国凯撒电影节最佳女演员奖、1983年葡萄牙奇幻电影节观众大奖和最佳女主角奖、1981年西班牙圣保罗国际电影节评论奖。©豆瓣', '伊莎贝尔·阿佳妮', '安德烈·祖拉斯基', 7.9, 34450, 'tt0082933', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2633303314.jpg', 1.4, 3.7, 21.9, 42.7, 30.3, '-0.438062,-0.063280,-0.639253,0.685006,0.404318,-0.283064,0.241544,-0.195488,-0.637715,-0.258086,0.211511,1.023546,-0.546583,-0.021189,0.621873,0.083962,-0.667061,-0.900459,0.086406,-0.346669,-0.042475,-0.443699,-0.196658,-0.076960,-0.039742,-0.338673,0.757551,-0.206633,0.009170,0.580821,0.819550,0.172158,-0.031220,0.257136,0.208717,0.198566,0.715255,0.036822,-0.482687,0.332576,-0.027996,-0.401470,-0.478504,0.188467,0.266721,0.357141,0.580622,-0.298835,0.008784,-0.053516,0.438369,-0.382205,0.017696,-0.120624,0.240770,-0.251670,0.471880,0.260520,-0.069180,-0.008972,0.190898,-0.071477,-0.471784,0.356580,0.300326,0.285609,-0.178080,0.233016,-0.277618,0.258385,-0.296722,-0.029146,0.193758,0.158047,0.206671,0.008074,0.079650,0.173803,-0.329165,0.512022,0.240037,0.240806,-0.390983,0.209579,-0.150059,-0.619497,-0.347875,-0.147733,-0.400604,0.405724,0.425626,0.120682,-0.036079,0.302525,-0.506896,-0.199125,-0.185193,-0.339797,0.174275,-0.129795,-0.121177,-0.831469,0.004830,-0.073956,-0.123153,-0.307691,-0.023974,-0.031924,0.516236,-0.436335,0.177254,0.508091,0.269697,-0.381197,0.892973,0.031728,-0.212632,-0.423645,-0.589664,0.402262,-0.086485,-0.208264,-0.266803,0.104947,0.089802,-0.544462,-0.222319,0.234635', '1780122', '1298616', '1292759', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297213', '龙少爷', '喜剧', '清朝末年，洋人入侵，大厦将倾。大内太监总管程公公（陈惠敏 饰）趁宫中混乱之际，将一件件国宝偷卖给洋人。这天，龙山镇的富家公子、武艺高强的龙少爷（成龙 饰）与朋友外出游玩之际，无意中来到了一处堆满宝藏的地方。看守的人发现了惊奇不已的龙少爷，一路追杀过来。幸好当地王员外暗中相 救，龙少爷才躲过一劫。原来此处是程公公的私藏国宝之地，机关重重。同时，一直反对程公公所作所为的副总管于海趁乱偷出了一些国宝，程公公得知后大怒，派人追杀于海。龙少爷拔刀相助，反而给王员外也惹来了杀身之祸。怒不可遏的龙少爷决定挑战程公公这个老奸巨猾的卖国贼。©豆瓣', '成龙', '成龙', 6.9, 12338, 'tt0084266', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204681689.jpg', 0.8, 5.1, 54.4, 29.4, 10.3, '0.124658,0.102075,-0.307437,0.281663,0.003426,-0.560859,0.434136,0.168778,-1.079473,-0.561306,0.189998,0.314198,-0.236013,-0.187410,0.520278,-0.015391,-0.173765,-0.122807,-0.373809,-0.049571,-0.293680,-0.020549,-0.272706,-0.453013,-0.298369,-0.109040,-0.194211,0.376570,-0.145714,0.475450,0.259382,0.233890,-0.388220,0.606526,-0.145152,0.431778,0.272001,-0.203880,-0.287951,0.264316,-0.044409,-0.416615,-0.268567,0.031881,0.107244,0.137908,0.222363,-0.430867,-0.162073,-0.153769,0.246803,-0.331564,0.216249,0.074925,0.448544,-0.051174,0.169144,0.020802,-0.232329,0.129862,0.178167,-0.102953,0.020808,0.229778,0.374194,-0.173885,-0.431602,-0.178735,-0.112704,0.014215,-0.177737,-0.451762,0.829016,0.301363,-0.086547,-0.118100,0.031214,-0.080853,-0.688230,0.378200,0.180911,-0.135241,0.351387,-0.542174,0.347065,-0.263971,0.462253,-0.170882,-0.188102,0.082578,0.502932,-0.203427,0.028019,-0.066399,-0.330426,-0.062150,-0.549064,0.391469,-0.097594,-0.175647,-0.135349,-0.389806,0.016213,-0.097967,0.252717,0.074567,0.408866,0.152253,0.253007,-0.279356,0.100328,0.179153,0.061466,-0.505367,0.442557,-0.309442,-0.038791,-0.203064,-0.108018,-0.525695,0.588277,0.563292,-0.037551,0.240510,-0.113160,-0.650306,0.042967,-0.091140', '5422105', '3412830', '1303176', '1306490');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297223', '鹿鼎记', '喜剧', '清朝初期，康熙皇帝尚且年少，奸臣从中控制政权，民不聊生。“天地会”是一个推翻清朝的民间组织。“天地会”首领陈近南（刘松仁 饰）在一次行动中幸得韦小宝（周星驰 饰）相救，小宝就此加入天地会，被派到王宫当卧底，偷取藏有清朝秘密的四十二章经。聪明机灵的小宝很快便成为了皇上的心腹，做了大官。小宝陷入了两难的状态，他既要执行任务却又跟皇帝成为了好朋友。就在小宝想要逃走之际，师父陈近南也找到了他，并派人监视他回到王宫。不久，小宝便受到了鳌拜同盟以及假太后的追杀，与天地会的人大战起来。©豆瓣', '周星驰', '王晶', 8.3, 311286, 'tt0104770', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2166580970.jpg', 0.2, 1, 17.2, 47.7, 34, '0.114665,0.265880,-0.540479,0.410707,-0.122550,-0.272334,0.311120,0.277080,-0.704034,-0.053483,0.478903,0.658421,0.037018,-0.047602,0.067751,0.107857,-0.258244,-0.602467,0.011376,-0.174794,-0.085804,-0.160662,-0.214395,-0.184689,-0.206524,-0.438929,0.644622,0.092968,-0.148493,0.250521,0.214974,0.028039,-0.111346,0.659293,-0.235739,0.342848,0.217036,-0.355957,-0.179499,0.215436,-0.081242,-0.503940,-0.277335,0.211075,-0.016299,0.254953,0.377171,-0.479580,-0.048356,-0.167478,0.039435,-0.455537,-0.323640,0.092219,0.490613,0.040881,0.139451,0.523386,-0.101070,0.219646,-0.087503,-0.051908,-0.549194,0.110025,0.357126,0.080654,-0.476319,0.161001,-0.136293,-0.009403,-0.031915,-0.399997,0.223669,0.648090,-0.064470,0.242797,-0.128680,-0.007543,-0.712419,0.281890,0.681197,-0.348142,-0.047139,-0.109481,0.466561,-0.390465,0.379583,-0.478888,0.138048,0.005005,0.687340,-0.303540,-0.188064,0.183865,-0.302507,-0.078797,-0.479932,-0.005010,0.041820,-0.293085,0.260971,-0.228867,-0.227690,0.047859,-0.354329,-0.069626,0.165685,-0.038216,0.643267,-0.816437,0.281747,0.531119,0.181526,-0.860755,0.342721,0.061582,0.105218,-0.231191,0.098047,-0.203027,0.081659,0.403413,0.112767,0.118895,-0.109645,-0.399950,-0.338042,0.010373', '1297710', '1301022', '1877596', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297228', '一封陌生女子的来信', '剧情', '影片改编自著名作家兹威格的同名小说，由美国环球影片公司出品。1885年，14的丽莎（琼·芳登 Joan Fontaine 饰）暗恋着住在隔壁的钢琴家斯蒂芬（路易斯·乔丹 Louis Jourdan 饰）。风流的斯蒂芬常把女人带进他的寓所，而年少的丽莎则对那个神秘世界羡慕不已。即便搬走后她仍对钢琴家难以忘怀。当她出落成了一个美丽的女郎，回来寻找钢琴家，并同他发生了关系。钢琴家很快将丽莎如其他女子般遗忘。丽莎生下了他的儿子后来嫁给了一个奥地利贵族。15年后，两人再次相逢，她离开丈夫最后一次献身于这个她惟一所爱的男人，钢琴家如往常一样逢场作戏，并将她很快忘记。最后儿子得伤寒而死，心力交瘁丽莎写了封长信给钢琴家，述说了15年来她从未停止的爱。丽莎死后，悲痛的丈夫要求同钢琴家决斗，在读到丽莎这封感人至深的信后，原本准备逃走的他登上了驶往决斗地的马车……©豆瓣', '琼·芳登', '马克斯·奥菲尔斯', 8, 8807, 'tt0040536', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2164352043.jpg', 0.4, 1.8, 21, 51.6, 25.2, '0.360764,0.085933,-0.679745,0.473243,-0.095072,-0.601187,0.922804,0.143624,-0.493347,-0.248455,0.168976,0.877175,-0.291955,0.360394,0.324520,0.266104,-0.214621,-0.758105,0.101781,-0.336170,-0.023775,-0.270261,0.041727,0.043433,0.066362,-0.326536,0.511527,-0.326395,0.182055,0.528804,0.296443,0.119663,0.202502,0.250367,-0.235910,0.222205,-0.073518,-0.016386,-0.289928,0.366691,0.085597,-0.100564,-0.119261,-0.074350,-0.191973,0.126674,0.668421,-0.375290,0.148688,-0.231571,0.479713,-0.165301,0.000050,0.195584,-0.102373,-0.015741,0.022390,0.202054,-0.394390,-0.058861,0.177194,-0.053428,-0.544159,0.216193,0.060199,0.251682,-0.547543,0.506938,-0.255122,0.136891,0.061011,-0.394343,0.193059,0.074664,0.049756,0.426437,-0.176882,0.134440,-0.398431,0.461131,0.629609,0.136979,-0.117438,0.398489,-0.155357,-0.241518,0.130848,-0.282782,-0.745982,0.263893,0.396014,0.077759,-0.271310,0.135910,-0.395632,-0.295451,-0.432256,0.050802,0.104188,-0.482561,-0.210827,-0.379948,-0.126764,-0.188728,-0.147138,-0.275117,-0.064954,-0.244340,0.762290,-0.733092,0.278458,0.540273,0.308442,-0.432462,0.602975,0.196511,-0.007248,-0.070556,0.099081,0.624650,-0.001890,0.370548,0.025939,0.294862,-0.092413,-0.071759,-0.382043,0.466711', '1296534', '4233625', '1291877', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297229', '亡命天涯', '剧情', '金波医生（Harrison Ford 饰）的妻子在家中被人谋杀，虽然金波当晚撞见独臂凶手并与之搏斗，但是凶手终于逃走，金波本人却因种种不利证据被判定为谋杀罪。在押解前往监狱的途中，一名犯人试图逃脱造成狱车事故，金波在混乱中搭救了一名警员并趁夜色逃逸。赶到事故现场的联邦司法官山姆（Tommy Lee Jones 饰）接手此案追捕金波，山姆为人精明强干，作风强硬，更重要的是，他怀有一颗探求真相的正义之心。山姆带队与金波展开了节奏紧凑的追捕与反追捕，金波在四面无援的困境中，依靠为爱妻报仇的意念坚持了下来，并将山姆引向此案的真相。原来某大制药厂为使一种失败的新药通过审查，动用了篡改医疗报告等不法手段，不肯合作的金波于是成为了他们暗杀的对象……本片获1994年奥斯卡最佳男配角奖等多项褒奖。©豆瓣', '哈里森·福特', '安德鲁·戴维斯', 8.1, 36052, 'tt0106977', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p805294540.jpg', 0.1, 0.7, 17.7, 55.7, 25.8, '0.108437,0.055348,-0.617042,0.389994,-0.116802,-0.054781,0.551257,0.132705,-0.533789,-0.290123,0.401730,0.546215,0.194747,-0.203821,0.357514,-0.253700,-0.305651,-0.711898,-0.073244,-0.082333,-0.180600,-0.651753,-0.295376,-0.042196,-0.155668,-0.265443,0.597149,0.264666,-0.266983,0.478278,0.233869,0.497615,-0.206073,0.389784,0.190930,-0.224758,0.252365,-0.395344,-0.487848,0.369945,-0.019599,-0.718687,-0.146056,0.319850,-0.277651,0.566403,0.681919,-0.275603,-0.229858,-0.292725,0.269995,-0.620451,0.037277,0.177001,0.328999,0.080855,0.003039,0.496724,-0.341488,0.134035,-0.000663,0.119137,-0.993588,0.030336,0.172983,0.130499,-0.503139,0.009944,-0.143693,0.130409,-0.010756,-0.208921,0.090474,0.352485,0.149668,0.145952,-0.264545,0.024476,-0.599981,0.024299,0.625672,-0.235272,0.069313,-0.029170,0.089778,-0.407179,0.145464,-0.099888,-0.230527,-0.123474,0.512973,0.201061,-0.168513,0.173751,-0.291518,-0.103082,-0.622142,0.081493,-0.266349,-0.226112,0.084387,-0.613602,0.029094,0.171246,-0.184217,-0.091719,0.238868,-0.218019,0.320725,-0.601402,0.183625,0.490608,0.274461,-0.844220,0.256140,0.316680,0.293098,-0.183978,-0.315983,0.117086,0.421610,0.597224,0.005382,0.071299,0.188036,-0.382843,-0.376958,-0.042975', '26747274', '26678784', '1297862', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297233', '心之全蚀', '剧情', '本片是关于两位法国象征派大诗人魏尔伦和兰波的传记片，内容大多都建立在真实的历史记录基础上。1871年，17岁的诗人兰波（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）接受当时已是著名诗人魏尔兰（大卫·休里斯 David Thewlis 饰）的邀请，去往 巴黎。当时魏尔兰已经结婚，妻子家境富有。但他偏偏对这个恃才傲物，举止怪异，放浪不羁的兰波，着迷不已。他因此而抛下妻子，与兰波流浪到伦敦，同居在了一起，过着放纵不羁又贫困潦倒的生活。在疯狂的两年同居生活中，两人相互追逐，彼此伤害，纷争不断。1873年，在最后一次争执中，魏尔兰开枪打伤了兰波逮捕并被判入狱两年。之后兰波一人孤身返乡，四处漂泊，经历繁杂，甚至贩卖军火，最终37岁时病逝于马赛。©豆瓣', '莱昂纳多·迪卡普里奥', '阿格涅丝卡·霍兰', 8.2, 78334, 'tt0114702', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2283025640.jpg', 0.5, 1.6, 18.6, 47.2, 32.1, '0.214541,-0.176272,-0.624767,0.422578,0.040179,-0.500414,0.665965,-0.057581,-0.507334,-0.324969,-0.062455,0.625647,-0.339496,0.450832,0.452698,-0.220726,-0.248407,-0.609938,0.189965,-0.223731,-0.156933,-0.747147,-0.210057,-0.144914,-0.262958,-0.286726,0.379223,0.079843,-0.059934,0.753172,0.145877,0.264137,-0.197811,0.262537,-0.233590,0.087307,0.249649,0.161396,-0.376454,0.075523,-0.117457,-0.396887,-0.297392,-0.152592,0.066065,0.398164,0.490289,-0.245520,-0.092933,-0.058834,0.605955,0.073151,-0.264331,0.187860,0.402865,0.063659,0.258427,0.415691,-0.151862,-0.024292,-0.115890,-0.105428,-0.291676,0.063340,0.105413,0.020813,-0.560106,0.597909,-0.050204,0.084434,-0.122035,-0.212601,0.102961,0.336183,0.095273,0.479397,-0.013615,-0.065854,-0.331775,0.334578,0.858639,0.156439,-0.389362,0.064202,-0.240193,-0.086238,-0.065127,-0.431153,-0.517849,-0.009743,-0.024313,0.006942,-0.243311,0.589621,-0.433181,0.163341,-0.182200,0.068123,0.010662,-0.201753,-0.163227,-0.546180,-0.333782,-0.576957,-0.304590,0.094332,0.037298,-0.304478,0.518106,-0.585704,0.479650,0.490905,0.304607,-0.342004,0.532436,0.292857,0.152832,0.078836,-0.002180,0.652613,0.147054,-0.154302,-0.043023,0.152922,0.012153,0.054798,-0.344180,0.412916', '26687241', '25721544', '1292720', '26296258');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297239', '了不起的盖茨比', '剧情', '汤姆（布鲁斯•邓恩 Bruce Dern 饰）和黛西（米亚•法罗 Mia Farrow 饰）的婚姻并不幸福，因为汤姆是一个花花公子，经常出去鬼混。汤姆还经常和与他们相邻的黛西的舅舅尼克一起出席舞会，寻欢作乐。尼克的邻居盖茨比是个神秘的有钱人，他经常邀请尼克参加宴会，两人很快相熟。相熟后，盖茨比（罗伯特•雷德福 Robert Redford 饰）邀请尼克带着他的侄女黛西来他家作客。此时，黛西认出了盖茨比。原来盖茨比是黛西5年前的恋人，只因当年盖茨比只是一个穷小子，为了改变命运而出国拼搏，黛西正是在这个时候与汤姆结了婚。两人很快旧情复燃。一次宴会，黛西又和汤姆吵翻了，借酒消愁的她酒后和盖茨比一起开车回家时不幸撞死了汤姆的情妇。为了昔日的情人，盖茨比决定挺身而出。©豆瓣', '罗伯特·雷德福', '杰克·克莱顿', 8.1, 22942, 'tt0071577', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2081917343.jpg', 0.2, 1.2, 20.3, 51.1, 27.2, '0.415011,-0.311762,-0.608689,0.400259,-0.362086,-0.896733,0.873116,0.294540,-0.419514,-0.508157,-0.038377,1.291988,-0.409850,0.515346,0.247620,0.021641,-0.657631,-0.564424,0.203803,-0.000363,-0.065006,-0.670614,-0.117726,-0.187780,-0.172650,-0.074608,0.150334,-0.369967,0.161594,0.987571,0.436210,0.155410,0.045348,0.501980,-0.247266,-0.034007,0.264000,0.190936,-0.549045,0.185969,0.202759,0.223496,-0.074959,-0.207810,0.120931,0.276188,0.098411,-0.141329,0.185513,-0.229960,0.074472,-0.028392,-0.004708,0.169389,0.264728,-0.324529,0.404318,0.221302,-0.143020,-0.108690,0.184281,-0.025200,-0.283233,0.469204,0.145045,0.162403,-0.450680,0.461176,-0.215811,0.083200,0.333834,-0.169087,0.182275,0.512957,0.021501,0.239619,-0.064341,-0.014600,-0.673294,0.014086,0.759658,0.337260,0.247912,0.435554,-0.140441,-0.046792,0.271471,-0.090305,-0.458160,0.343943,0.278641,-0.448031,-0.100514,0.426852,-0.634170,-0.232302,-0.183767,0.140975,-0.029124,-0.444529,-0.034813,-1.016818,-0.106377,-0.540801,-0.201725,-0.285709,0.184973,-0.276354,0.509010,-1.043182,0.236830,0.598756,0.434377,-0.361985,0.803944,0.080113,0.126738,-0.338338,-0.069761,-0.019033,0.003648,-0.020385,-0.089286,0.300169,0.207200,-0.259412,-0.220777,0.637446', '1303333', '11541282', '1829654', '4319218');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297242', '大白鲨2', '惊悚', '影片故事背景一如上集，主要人物布迪警长亦由上集的罗伊·谢德扮演，但是今次出现肆虐艾密迪海滩的大白鲨，却是一条满含恨意，一心前来报“杀夫之仇”的母鲨。', '罗伊·谢德', '吉诺特·兹瓦克', 6.4, 5121, 'tt0077766', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198882795.jpg', 1.6, 11.4, 58.8, 21.6, 6.5, '-0.305037,-0.194114,-0.048776,0.961634,0.546280,-0.101867,0.518766,0.167711,-0.234087,-0.253085,0.533807,0.389409,-0.070512,-0.174307,0.451084,-0.260553,0.148098,-0.054755,0.326010,-0.035718,0.820352,-0.458082,-0.763649,-0.006176,0.142326,0.135500,0.847214,-0.343258,0.260816,0.720889,0.493450,0.643828,-0.523954,0.144115,0.199512,-0.159351,-0.369598,-0.000239,-0.355334,-0.071460,-0.065361,-0.099123,-0.080934,-0.351490,-0.341433,0.534695,0.727193,-0.129899,-0.287243,-0.234096,0.521347,-0.188150,0.440665,0.197289,0.365747,-0.021958,0.118399,0.630113,0.351798,-0.054712,-0.105593,-0.204542,-0.310988,-0.442658,0.033150,0.150029,0.126686,0.014552,-0.390951,0.039252,-0.047999,0.176896,-0.107925,-0.115108,0.086853,0.569042,-0.066068,0.099118,-0.183608,0.046656,0.050520,0.109903,0.193701,0.166933,0.146789,-0.318492,0.027635,-0.005642,-0.454982,0.174333,0.154484,-0.167434,-0.749803,0.675509,-0.665037,-0.360632,-0.214730,-0.079491,0.016237,0.160478,-0.064202,-0.719144,-0.287398,0.168859,0.070439,-0.072824,0.106413,-0.205039,0.397079,-0.509079,0.192101,0.246898,-0.092503,-0.399137,0.598053,0.139476,-0.204976,0.044105,-0.209571,0.593686,0.079136,-0.235339,-0.005936,-0.111030,-0.302511,-0.266172,-0.340458,0.298188', '26349397', '24879819', '1303390', '1295656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297248', '五亿探长雷洛传1：雷老虎', '剧情', '本片用一个香港警察从理想青年变成一代枭雄的过程，反应了香港五六十年代的社会问题。1949年，热血青年雷洛（刘德华 饰）成为警察。当时，香港警察待遇不高，警察向商户们收取保护费的潜规则蔚然成风，雷洛不愿意和他们同流合污，受到同事们的排挤，也得罪了权倾一时的探长颜同（秦沛 饰），面临停职的危险，然而，探长陈统(关海山 饰)暗暗欣赏他，对他维护有加。雷洛和杂货店老板的女儿阿霞（邱淑贞 饰）两情相悦，但是阿霞的父母不愿意女儿跟着他受苦，百般阻挠。雷洛借酒浇愁，到黑社会的赌场闹事，被人殴打，多亏探长陈统搭救，并帮他筹到了五万元的聘礼。但是，1951年九龙东头村的大火，烧毁了雷洛的美梦。雷洛一家侥幸逃脱，阿霞家人却葬身火海，阿霞本人也音信全无。转眼到了50年代末，雷洛经历了警队派系倾轧，几经浮沉，渐渐适应了香港警界，收保护费的事情也做得得心应手。他有幸娶到了“大捞家”白饭鱼的女儿，美丽泼辣白月娥（张敏 饰），靠着岳父的大力支持和自己在镇压1957年九龙暴动中的出色表现，荣升探长。成为探长的雷诺规范了管区内收取保护费的制度，减少了各界冲突，深得上级的器重。恰逢油尖区探长退休，雷洛和颜同都成为了这个职位的有力竞争者，二人各自展开了行动，一时风起云涌，此时，雷洛意外遇见了一个人，让他震惊不已……', '刘德华', '刘国昌', 7.9, 56267, 'tt0103292', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1273873245.jpg', 0.2, 1.4, 24.9, 51.8, 21.7, '0.163745,-0.020109,-0.623539,0.147935,-0.180824,-0.279707,0.438130,0.213599,-0.609818,-0.101808,0.280919,0.598221,-0.120739,0.105253,0.267663,-0.082332,-0.143823,-0.498824,0.154238,0.053113,-0.053046,-0.305796,-0.179913,-0.438456,-0.197846,-0.198416,0.364288,0.108827,-0.081680,0.489462,0.250837,0.097917,0.048055,0.377060,-0.112090,0.162649,0.266808,0.087622,-0.272256,0.153234,-0.153197,-0.325656,-0.293606,0.152490,0.197770,0.500087,0.350238,0.040075,-0.199157,-0.034735,0.303553,-0.418638,-0.208570,0.020957,0.348959,-0.004063,-0.092756,0.229720,-0.196177,-0.147241,-0.027695,-0.023513,-0.433234,0.026273,0.186677,0.102454,-0.700700,0.416864,-0.118544,-0.019412,-0.213713,-0.261096,0.128337,0.144313,-0.126534,0.319832,-0.129010,0.108590,-0.607151,0.391024,0.700841,-0.072989,-0.268578,0.032865,-0.234407,-0.469880,-0.106727,-0.441746,-0.417327,-0.046813,0.293029,-0.121577,-0.057702,0.212399,-0.317803,-0.220870,-0.190578,-0.079969,-0.174138,-0.250817,-0.006896,-0.297764,-0.301923,-0.398067,-0.314015,-0.046741,0.118467,-0.234064,0.624466,-0.567158,0.044234,0.487216,0.333838,-0.791808,0.659945,0.160909,0.058275,-0.226371,-0.264832,-0.231741,0.173869,0.274455,0.287834,0.097980,-0.154751,-0.448104,0.079854,0.082657', '1308035', '25721544', '25908042', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297258', '火烧红莲寺', '动作', '清朝时，少林寺图谋反清复明，为清兵所剿灭，少林子弟星散，清廷鹰犬紧追不舍……少林俗家弟子方世玉（季天笙 饰）与师叔至能大师与荒漠之中躲避清兵，偶遇从良妓女豆豆（李若彤 饰），三人于乱世相识，方世玉对豆豆一见钟情。清兵围堵三人，至能惨死，世玉和豆豆被带回红莲寺。红莲寺在神公（黄锦江 饰）掌控下逼迫众多少林弟子为奴，昔日的少林俗家弟子洪熙官屈服神公担任工头，与方世玉大打出手，方世玉被神公暗算，奄奄一息。红莲寺内机关重重，少林弟子动辄命丧劳作之中。被神公纳为宠姬的豆豆为方世玉求得性命。一众少林子弟决意冲出红莲寺，重返自由……©豆瓣', '李若彤', '林岭东', 6.8, 8400, 'tt0110080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2869825717.jpg', 0.9, 6.5, 52.5, 31, 9.1, '0.076099,-0.083090,-0.310064,0.315645,0.257311,-0.162547,0.129659,0.178772,-0.810485,-0.332162,0.398849,0.578166,0.056022,-0.005481,-0.140667,-0.247242,0.266284,-0.678396,-0.442319,-0.180009,0.195295,-0.102098,0.121232,-0.005393,-0.561927,-0.193152,0.669455,0.374287,-0.381426,0.561441,0.122920,0.248188,-0.493432,-0.075710,-0.160958,0.262446,0.041162,-0.173024,-0.637028,0.165756,-0.633947,-0.466344,-0.091513,-0.432460,-0.522202,0.249205,0.465995,-0.294908,0.035804,-0.553751,-0.362045,-0.115252,-0.285648,0.441978,0.343397,0.137534,0.459747,0.341527,0.165103,0.157123,-0.125584,-0.025916,-0.163039,0.054959,0.681879,-0.144664,-0.536964,0.323553,-0.202062,0.101335,-0.051581,-0.388440,-0.110124,0.082724,0.247501,0.056392,-0.203693,-0.137608,-0.564323,0.349190,0.604852,-0.394717,0.674746,-0.500574,0.376970,-0.121834,0.519070,-0.394599,-0.163204,0.116292,0.462625,-0.389523,0.175222,0.509681,-0.211686,-0.107915,-0.402627,0.357000,-0.325902,0.078963,-0.002031,-0.584019,0.046947,0.121854,-0.037908,-0.169857,0.404143,0.049511,0.798426,-0.502037,0.249878,-0.204889,0.432636,-0.359244,0.654458,-0.165033,0.355819,0.054897,-0.434238,0.201908,0.324135,0.496259,0.147394,0.009842,-0.379053,-0.052352,-0.041272,-0.357507', '1298443', '1306998', '1433736', '3230460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297260', '笨贼妙探', '喜剧', '盗贼麦尔斯（马丁·劳伦斯 Martin Lawrence 饰）与三名同伙合作盗窃钻石，岂料其中一人德克背叛了他们，警方被惊动，麦尔斯走投无路，只得逃跑中将钻石藏在一栋未完工的大楼通风管道里，之后束手就擒。两年后，麦尔斯刑满释放，但外面的一切似乎都已改变，女友不再需要他，而当年他藏钻石的那栋楼居然变成了——警察局！为了取回钻石，麦尔斯偷到ID卡，又凭借伪造的档案乔装成警察混入警局，由于警方缺人手，假警察麦尔斯很快得到任命，和菜鸟探员卡森（卢克·威尔逊 Luke Wilson 饰）结成搭档。麦尔斯凭借自己的盗窃经验很快表现出位，在警局得到重用，而管道中的钻石经过冲洗后下落不明，麦尔斯只得坚持假装下去。不久，德克为了得到麦尔斯的钻石再次出现……©豆瓣', '马丁·劳伦斯', '莱斯·梅菲尔德', 7.7, 23130, 'tt0181316', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1898841633.jpg', 0.2, 1.7, 28.6, 50.9, 18.5, '0.251836,0.230496,-0.651717,0.241136,-0.266587,-0.351409,0.618170,0.053562,-0.317938,-0.309102,0.370395,0.504475,-0.149479,0.066510,0.215287,-0.145281,-0.637460,-0.481198,0.077137,-0.541785,-0.313499,-0.624454,-0.356560,-0.141155,-0.123562,-0.183835,0.727846,0.259836,0.069098,0.188883,0.278093,0.338603,-0.120248,0.211758,0.065671,0.009820,0.347042,-0.062557,-0.331647,0.435674,0.012720,-0.083707,0.096107,-0.069858,0.265931,0.396082,0.327174,-0.171888,0.093299,0.037160,0.132853,-0.124892,0.016607,-0.081992,0.512533,0.198862,0.094178,0.184385,-0.541454,0.049787,0.200157,0.063081,-0.571720,-0.067629,0.066594,0.088017,-0.283696,-0.029143,-0.317876,0.294224,0.119566,-0.303505,0.014803,0.300245,0.154653,0.067902,-0.088636,-0.000291,-0.788790,-0.033757,0.324006,-0.303455,-0.106718,0.010652,0.245640,-0.361517,0.219007,-0.171858,0.065139,0.045831,0.475968,0.125264,0.002838,-0.263817,-0.391083,-0.310457,-0.544059,-0.053180,-0.088977,-0.229697,-0.132669,-0.767685,-0.037660,0.086606,-0.190018,-0.067592,-0.016870,-0.172981,0.183547,-0.568843,0.123287,0.201286,0.237836,-0.424906,0.278075,-0.251761,0.245726,-0.078774,-0.149773,0.169306,0.650344,0.458671,0.277696,0.078913,-0.025183,-0.399401,-0.228119,0.041356', '1292214', '1301345', '3183490', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297268', '秋日奏鸣曲', '剧情', '夏洛特（英格丽·褒曼）是某乐团杰出的钢琴演奏员，她的女儿伊娃（丽芙·乌尔曼）是一名在农村社区工作的牧师的妻子，两人之间有一道深深的感情鸿沟，七年来不曾有过任何交流。在得知夏洛特的第二任丈夫去世后，伊娃写信邀请夏洛特来同住，两人都试着友好相处，却不免又将往事重提。伊娃怨恨夏洛特没在她童年时给予她足够的爱护，只把重心放在自己的事业上，疏远了自己和另一个有高度残疾、只能发不清晰的音来与人交流的女儿海琳（莱娜·尼曼）。而夏洛特因为海琳与伊娃住在一起，加上丈夫的去世给自己造成很大打击，也是心情闷闷紧锁眉头。©豆瓣', '英格丽·褒曼', '英格玛·伯格曼', 9, 30403, 'tt0077711', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2034707962.jpg', 0.2, 0.6, 6.1, 33, 60.2, '0.368880,-0.068479,-0.784805,0.724569,-0.122757,-0.501425,0.980378,0.174978,-0.541114,-0.242546,0.227250,0.891438,-0.176136,0.489664,-0.063964,0.097597,-0.261646,-0.797372,0.074413,-0.137883,-0.324677,-0.787336,0.027579,-0.237214,-0.246984,-0.314775,0.574811,-0.472668,-0.290521,0.260976,0.286605,0.412241,0.070122,0.669928,-0.297784,0.299110,0.055633,0.003502,-0.078462,-0.103909,0.189486,-0.084241,-0.202421,0.351724,0.098347,0.554595,0.650152,-0.158680,-0.033975,0.006462,0.307415,-0.124114,0.103672,0.151855,0.286186,0.055071,0.162881,0.273386,-0.437732,-0.031116,0.063358,-0.106818,-0.489075,0.167756,0.018161,0.218550,-0.690765,0.691792,-0.200685,-0.346022,0.285267,-0.275558,0.101075,0.475111,-0.081350,0.464467,-0.325821,0.161702,-0.241163,0.143666,0.767480,0.175246,-0.249783,0.458636,-0.529634,-0.339062,-0.074878,-0.160610,-0.520989,-0.080711,0.248626,0.173798,-0.107886,0.359763,-0.397338,-0.133118,-0.302730,-0.105809,0.175524,-0.656738,-0.006452,-0.660049,-0.345691,-0.537980,-0.555646,0.033148,0.193410,-0.396105,0.835670,-1.026832,0.170830,0.410068,0.374246,-0.345301,0.756877,0.290307,0.259529,-0.204152,0.050002,0.396433,-0.119844,-0.061382,0.352298,0.159903,-0.001820,0.324417,-0.298671,0.536253', '3230121', '1292219', '1308755', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297271', '圣女贞德', '剧情', '14世纪爆发的英法持续超过百年，法国节节败退，大部分国土都被英国占领了。就在这个时候，珍妮（米拉•乔沃维奇 Milla Jovovich 饰）出生在法国的穷乡僻壤中。年少起，珍妮就经常看到各种幻想。一次，她看到幻想并根据指示找到了一把剑，当她带着剑回到家时发现家里已遭英军蹂躏。珍妮知道是上天安排她来捍卫法国。于是她向当时的皇太子查理（约翰•马尔科维奇 John Malkovich 饰）请求率领一支军队去抗击英军。走投无路的查理答应了珍妮的请求。随后珍妮率领法军节节胜利，查理亦顺利登基。登基后的查理不再需要珍妮帮助，珍妮在以后的一次战斗中陷入困境但无人来救，她被英军捉住并带到了英国审批……©豆瓣', '米拉·乔沃维奇', '吕克·贝松', 7.4, 28780, 'tt0151137', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p475086031.jpg', 0.8, 4, 35.9, 44.7, 14.6, '0.066339,0.289554,-0.916762,0.463040,-0.156992,-0.373281,0.432805,-0.254506,-0.277668,-0.150213,0.239232,0.784036,-0.000551,0.117328,0.429984,0.000156,-0.484688,-0.718433,0.104621,-0.107899,-0.212740,-0.400459,-0.116493,-0.116929,-0.156948,-0.324701,0.437994,-0.138374,-0.177530,0.685402,-0.006920,0.293586,0.291697,0.479866,-0.114312,0.120517,0.119779,-0.294098,-0.335796,0.556993,0.083704,-0.280818,-0.258921,0.302748,0.053008,0.288103,0.617772,-0.263357,0.233525,-0.210434,0.233168,-0.206759,0.089189,0.216879,0.323899,0.273099,-0.074658,-0.021859,-0.390077,0.284633,-0.124276,0.009145,-0.438524,0.130798,-0.208902,0.011051,-0.668744,0.330430,-0.325856,0.105389,0.207057,-0.570856,0.155549,0.619291,0.072112,0.365118,-0.301790,0.084490,-0.754833,0.066946,0.550704,-0.372510,-0.097787,0.046349,0.256007,-0.252202,0.355344,-0.038776,-0.352323,-0.031070,0.390327,-0.029054,-0.143852,0.212169,-0.505234,-0.155061,-0.672309,-0.528004,0.093223,-0.204489,-0.047722,-0.673731,-0.139673,-0.110408,-0.242921,0.205191,-0.000597,0.058323,0.391449,-0.656714,0.430526,0.463543,0.546010,-0.330123,0.409168,0.323522,0.069236,0.007887,0.139636,0.528293,0.074676,0.354153,0.250241,0.173004,0.169489,-0.308013,-0.298371,0.393314', '1302987', '3285622', '3430271', '26678509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297280', '公主新娘', '爱情', '故事从慈祥的爷爷给生病的孙子讲故事说起，爷爷带来一本厚厚的童话故事书《公主新娘》。这个世代相传的童话故事讲述了一段爱与冒险的真爱故事。善良美丽的少女布卡特（罗宾·怀特 Robin Wright 饰）住在宁静的小村庄弗洛林，她与少年维斯特雷（加利·艾尔维斯 Cary Elwes 饰）青梅竹马两小无猜，两人很快陷入热恋。然而贫穷的维斯特雷希望给布卡特更好的生活，于是扬帆远航离开了村庄。但是维斯特雷的船并没有到达目的地，传言说他死在了海盗的手里。五年后，伤心欲绝的布卡特成为了王子胡姆普丁克（克里斯·萨兰登 Chris Sarandon饰）的未婚妻，可她并不爱他，她的心里仍苦苦思念着真爱维斯特雷。一次意外让布卡特再次遇见了维斯特雷，然而邪恶的王子却绑架了布卡特，并逼迫她嫁给自己。此时的维斯特雷已是一位勇敢强壮的海盗，为救真爱，他与武艺超群的剑客埃尼戈·蒙托亚（曼迪·帕廷金 Mandy Patinkin饰）、力大无比的巨人菲兹克（安德烈·捷安特 André the Giant饰）一起踏上了拯救公主之路。本部童话式爱情冒险电影《公主新娘》，荣获1988年第60届奥斯卡金像奖最佳原创歌曲提名，1987年第12届多伦多国际电影节人民选择奖-最佳故事片奖以及1988年第15届美国电影电视土星奖最佳奇幻电影。', '加利·艾尔维斯', '罗伯·莱纳', 7, 10539, 'tt0093779', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1047219022.jpg', 1.6, 8.2, 42.7, 33.4, 14.1, '-0.192913,-0.031653,-0.452766,0.819553,0.285707,-0.419340,0.697807,0.055055,-0.290347,-0.271456,-0.081659,0.743140,-0.126149,0.217706,0.490078,0.286503,-0.442491,-0.565477,0.001570,-0.009086,-0.135380,-0.327386,-0.114656,-0.128191,0.080885,-0.473473,0.575473,0.181834,-0.080875,0.456609,0.501168,0.130380,-0.011560,0.189618,-0.106299,0.166427,0.139151,0.084369,-0.336489,0.247246,-0.162310,-0.097889,-0.118309,0.167441,0.222908,0.101565,0.614658,-0.460744,0.189576,0.025916,0.403096,-0.241580,-0.041306,-0.160472,0.073118,-0.281342,0.105362,0.051496,0.263239,-0.060006,0.112003,-0.411733,-0.465728,0.080782,-0.075350,0.045742,-0.604666,0.428433,-0.268558,0.364507,0.014075,-0.138692,0.160278,0.068611,0.303095,0.178634,-0.149060,0.141721,-0.424796,0.478189,0.451580,0.246510,-0.220528,0.209453,-0.254095,-0.482778,-0.062765,-0.259571,-0.643264,0.325394,0.585642,-0.127891,0.002073,0.353055,-0.456184,-0.310494,-0.286831,-0.080530,0.197682,-0.457537,-0.096743,-0.482678,0.107828,-0.183501,-0.173918,-0.164332,-0.068697,-0.394418,0.691100,-0.495632,0.545620,0.563786,0.033030,-0.334610,0.671244,0.209553,0.047050,-0.155746,0.023615,0.587959,-0.062145,0.066006,0.243251,0.256595,-0.128776,-0.054143,-0.251147,0.481431', '1299663', '1460341', '1870681', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297291', '夏日么么茶', '喜剧', 'Summer（郑秀文 饰）是一个事业型女性，可是她事业跟爱情都失意。她只好来到马来西亚的丹丹岛，那里有一个沙滩是她与表格合资买下来的，刚好传出有财团想收购这个岛，与财团商量卖岛的事之余她还可以度假散心。来到岛上才知道，表哥也因为欠债的问题把半个沙滩的卖给了一个叫么么茶（任贤齐 饰）的当地人。可是么么茶为了可以让喜欢这个沙滩的人继续享受欢乐，不同意把沙滩卖出。Summer只好软硬兼施，在不知不觉之间两人发生了微妙的关系，继而展开了一场浪漫爱情。©豆瓣', '郑秀文', '马楚成', 6.7, 78074, 'tt0259741', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p482172556.jpg', 0.9, 7.4, 55.4, 28.1, 8.2, '0.338039,0.150981,-0.631630,0.637986,-0.119109,-0.232752,0.489852,0.184953,-0.050790,0.082547,-0.077593,0.977762,-0.023390,0.342757,0.316329,0.472126,-0.088691,-0.876587,0.167846,-0.110337,-0.232323,-0.418781,-0.140190,-0.234488,-0.212208,-0.002996,0.338335,0.172389,-0.038546,0.395494,0.425801,-0.137542,0.034417,0.559071,-0.449322,-0.037778,0.088067,0.333862,-0.331373,0.313728,0.012740,-0.148571,0.066437,-0.092987,0.486874,0.258202,0.573827,0.075173,-0.299176,0.210008,0.038073,-0.249436,0.083997,-0.007042,0.301063,-0.257311,0.157739,0.348193,-0.579555,-0.018947,0.265962,-0.041119,-0.797189,0.080806,-0.113232,-0.134845,-0.583629,0.631437,0.085676,-0.596664,0.001853,-0.124578,0.551742,0.692694,0.285949,0.339054,-0.119059,-0.023440,-0.799963,0.232547,0.747065,0.169813,0.234623,0.560308,0.031469,-0.244556,0.035913,-0.077442,-0.047505,-0.065793,0.168870,-0.263634,-0.390142,-0.264923,-0.988320,0.162588,-0.036029,-0.444039,0.209035,-0.807319,-0.090288,-0.325513,-0.045156,-0.318304,-0.079179,0.064096,0.167601,-0.062835,0.672355,-0.630142,0.029160,0.558130,0.405622,-0.710969,0.711585,0.337744,-0.045912,-0.189942,0.044499,-0.304753,-0.101783,0.240266,0.277076,0.471296,0.330110,-0.188102,-0.550729,0.164772', '30162520', '26678784', '4301278', '3215099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297294', '迷魂记', '爱情', '退役警探约翰·弗格森（詹姆斯·斯图尔特 James Stewart 饰）的同学加文·埃尔斯特（汤姆·赫尔莫 Tom Helmore 饰）是造船商。他请求约翰跟踪自己的妻子，并称妻子经常被鬼魂附身。随后，约翰按照加文的指示，在厄尼餐厅见到了一位美丽的女人（金姆·诺瓦克 Kim Novak 饰）。经过跟踪，约翰发现女人确有不同寻常的行为：开车出门，去花店买花，去墓园在卡洛塔·巴尔德斯的碑前驻足，去荣勋宫博物馆凝视卡洛塔画像，最后进入麦基屈克旅馆并出现在二楼的一扇窗前。约翰随即进入旅馆调查，发现女人登记名为卡洛塔·巴尔德斯，但其房中无人。卡洛塔·巴尔德斯究竟是何方神圣，鬼魂真的能附身活人吗？©豆瓣', '詹姆斯·斯图尔特', '阿尔弗雷德·希区柯克', 8.7, 115528, 'tt0052357', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1275162115.jpg', 0.2, 0.7, 9.6, 43.5, 46.1, '0.248344,0.092568,-0.370093,0.269901,-0.161393,-0.550330,0.823473,0.335444,-0.241492,-0.516311,0.330371,0.555197,-0.147332,0.178063,0.558527,0.380989,-0.477638,-0.380288,0.053471,-0.342476,-0.436445,-0.474990,-0.138869,-0.441366,0.194810,-0.251447,0.207794,-0.237649,-0.048298,0.073414,0.374604,0.539489,-0.443249,0.222679,0.031819,0.141361,0.455938,-0.106833,-0.205281,0.199538,-0.051400,-0.056690,-0.274940,-0.151659,0.301996,0.017892,0.240637,-0.083495,-0.046653,0.306908,0.088255,0.246139,0.219857,0.050462,0.351440,-0.217686,0.162071,-0.053654,-0.084631,0.008080,-0.005493,0.051504,-0.041753,0.084946,-0.130301,0.208055,-0.462058,0.199231,-0.340160,0.239621,-0.068350,-0.466556,0.146241,-0.038546,0.085698,0.127962,0.241691,-0.106576,-0.540083,-0.347597,-0.127693,0.086901,-0.009080,0.105273,-0.145566,-0.434527,-0.028827,0.319292,-0.222834,0.181169,0.400076,-0.045216,-0.099040,-0.267589,-0.414122,-0.477959,-0.570412,-0.047061,-0.042183,-0.039132,-0.271900,-0.897358,0.115692,0.105704,-0.101377,-0.126641,-0.314406,-0.107938,0.139974,-0.656875,0.329848,0.762487,0.231617,0.034558,0.789185,-0.279587,0.011708,-0.209224,-0.315194,0.490882,0.592646,0.461377,-0.039078,0.258064,0.061290,-0.072978,-0.187340,0.524360', '3183490', '1301686', '1297659', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297304', '笑傲江湖', '动作', '大内库藏武功秘笈《葵花宝典》失窃。东厂主管太监古今福（刘洵 饰）率千户欧阳全（张学友 饰）等，南下调查辞官锦衣卫林镇南，同时收用“五岳盟主”左冷禅（元华 饰）外围策应。华山派大弟子令狐冲（许冠杰 饰）与师妹岳灵珊（叶童 饰）奉师命增援林镇南，无奈两人实力不济，领得林镇南遗嘱后遁走，二人于路先后巧遇顺风堂堂主刘正风（午马 饰）、日月神教长老曲洋（林正英 饰）、华山派风清扬，获传《笑傲江湖》曲谱和独孤九剑。各路人马为《葵花宝典》纷纷聚于苗人地界，欧阳全与左冷禅争功不下，遂假扮林平之混入华山派一行。令狐冲结识日月神教任盈盈（张敏 饰）与蓝凤凰（袁洁莹 饰），因曲洋之关系得其协助。古今福与岳不群为《葵花宝典》大打出手，令狐冲不忍一班师兄弟受牵连愤而使出独孤九剑，始明了“笑傲江湖”真意。本片根据金庸同名小说改编。©豆瓣', '许冠杰', '胡金铨', 8, 99413, 'tt0100973', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2543084320.jpg', 0.3, 1.6, 21.8, 50.4, 25.9, '-0.187199,-0.140952,-0.240796,0.632561,0.223314,-0.361528,-0.026785,0.357782,-0.819301,-0.463707,0.295009,0.404581,-0.045307,-0.240898,-0.080339,-0.349886,0.069611,-0.663177,-0.206149,-0.355342,0.217208,-0.125480,0.275485,0.027959,-0.506624,-0.123278,0.246834,0.040223,-0.175962,0.534900,0.544763,-0.131528,-0.593952,-0.033372,0.197364,0.314106,0.076486,-0.086988,-0.557471,0.139622,-0.143044,-0.249924,-0.349452,-0.294151,-0.176233,0.168980,0.403643,0.141773,0.141726,-0.262187,-0.062128,0.159615,0.023411,-0.010639,0.329665,0.303528,0.243649,0.175425,0.024338,-0.036585,-0.100507,0.183017,-0.295291,-0.017786,0.685087,-0.060257,-0.241331,0.246841,-0.776410,-0.185149,-0.459453,-0.611908,-0.108917,0.170425,0.448671,-0.309563,0.241898,-0.342928,-0.201258,0.511153,0.155336,0.028421,0.581886,-0.347093,0.405055,-0.120901,0.075070,-0.194522,0.006631,0.167314,0.607219,-0.402196,0.747194,0.207812,0.094628,-0.320187,-0.186527,0.468664,-0.229239,0.151947,0.376350,-0.791479,0.101313,-0.093528,0.080303,-0.526480,0.685134,0.059896,0.674812,-0.288296,-0.098882,-0.459326,-0.202566,-0.654146,0.199232,-0.044262,0.296883,-0.062185,-0.200934,-0.105276,0.202775,0.421036,0.389284,0.313953,-0.114542,-0.226427,-0.119649,-0.371092', '1298761', '1299059', '1297517', '1294417'