INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297311', '水牛城66', '剧情', '倒霉的比利（文森特•加洛 Vincent Gallo 饰）替人顶罪蹲了5年牢，今天，他出狱了。可是他的霉运似乎还没有结束，刚出狱的比利内急想上厕所小便时，不是厕所维修就是被拒绝；即使鬼鬼祟祟的躲到汽车后面想就地解决时汽车也马上开走了。比利和双亲的关系并不好，但他一直想修复与父母的关系。即使坐牢，比利也想方设法瞒着家里，他告诉他们这5年自己在外打拼，已功成名就，并承诺将带着女友回家。为了实现承诺，他“绑架”了一名女孩蕾拉作为自己的女友。可是，当比利带着蕾拉回到家里时，事情并没有预想中顺利。©豆瓣', '文森特·加洛', '文森特·加洛', 8.5, 48163, 'tt0118789', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453576673.jpg', 0.6, 1.7, 13.3, 41.8, 42.7, '0.335759,0.024955,-0.725729,0.268426,-0.322747,-0.610559,0.801269,-0.014640,-0.320600,-0.384431,-0.172687,0.439509,0.041610,0.324474,0.128893,0.248256,-0.738686,-0.697120,0.371926,-0.083924,-0.348962,-0.455834,-0.024561,-0.052946,-0.378501,0.021363,0.279504,-0.186379,0.012342,0.507932,0.229298,-0.018623,0.093895,0.720988,-0.205085,-0.027010,-0.006761,0.166535,-0.099147,0.135416,0.264614,-0.381275,-0.266644,0.122192,0.374349,0.531185,0.217970,-0.014427,-0.009980,0.070894,-0.198317,-0.391397,0.111426,0.029803,0.243519,-0.148955,0.249144,0.348953,-0.143768,-0.066174,0.177649,-0.145425,-0.556274,0.120049,-0.204097,-0.198714,-0.673555,0.306883,-0.247278,0.148742,0.221517,-0.356855,0.305947,0.372802,0.067071,0.355137,-0.427936,0.178146,-0.799948,0.125888,0.636455,-0.210934,0.131419,0.466060,0.034283,-0.196512,0.114615,-0.095960,-0.541529,0.071749,0.195394,0.175930,-0.517313,-0.159439,-0.134229,-0.040492,-0.430653,-0.154261,-0.123956,-0.305221,-0.000943,-0.219098,-0.015061,-0.333247,-0.390966,0.044866,-0.240879,-0.179268,0.121720,-0.522370,0.298495,0.576973,0.604321,-0.711171,0.798561,0.176944,0.203881,0.021845,0.003403,0.004650,-0.129798,0.432599,0.315733,0.288116,0.272842,-0.189910,-0.228696,0.559583', '10355329', '1292584', '1306916', '3239892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297317', '谁陷害了兔子罗杰', '喜剧', '在美国洛杉矶有一个专供卡通人物居住的“图恩城”，卡通明星兔子罗杰（Charles Fleischer 配音）怀疑妻子杰西卡（凯瑟琳·特纳 Kathleen Turner 配音）有外遇，拍戏时常常走神，遭到他的搭档娃娃哈曼的奚落。卡通电影公司老板马隆便雇佣私人侦探埃迪（鲍勃·霍斯金斯 Bob Hoskins 配音）去查明情况，并拍下杰西卡偷情的照片，好让罗杰下定决心，斩断情缘，专心投入卡通系列片的拍摄。埃迪因自己的弟弟特迪不久前被“图恩城”的卡通角色暗害，也急于早日追出凶手，便慨然将此事承诺下来。而随着调查的深入，事情并不像埃迪想的那么简单，其中还另有奸情，慨然将此事承诺下来，就不能轻易放弃，埃迪能否找到案件背后的真相呢……本片根据加里·沃尔夫的同名畅销小说改编，同时是一部真人和动画相结合的影片。©豆瓣', '鲍勃·霍斯金斯', '罗伯特·泽米吉斯', 7.8, 21671, 'tt0096438', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199309048.jpg', 0.3, 2.1, 27, 50.3, 20.3, '0.330946,0.018784,-0.461433,0.519094,0.129904,-0.148852,0.459901,0.078618,-0.190803,-0.247438,0.145828,0.716818,-0.151612,0.132559,0.055567,0.216409,-0.599646,-0.640628,-0.000109,-0.054101,-0.080856,-0.515792,-0.157802,-0.344859,0.008959,-0.179560,0.542450,-0.103437,-0.300922,0.117860,0.467820,0.221059,-0.329636,0.426363,0.025742,0.303699,0.060141,-0.030342,-0.223780,0.299620,0.140555,-0.006865,-0.032596,0.169179,0.120572,0.450320,0.413968,-0.122811,-0.213843,-0.089807,0.359294,-0.122465,0.345842,0.077380,0.298181,0.063277,0.377900,0.283932,-0.309494,0.129597,-0.035619,-0.147920,-0.583835,0.113069,0.153898,0.114085,-0.450623,0.008909,-0.363895,0.072744,0.191635,-0.224277,-0.035878,0.390114,0.566860,-0.035779,0.119666,0.127439,-0.442781,0.316733,0.420468,0.112737,-0.009515,0.277565,0.036591,-0.378892,-0.189901,-0.140292,-0.225932,0.108430,0.481389,-0.096780,-0.046958,0.111612,-0.253211,-0.181699,-0.345419,-0.086290,-0.051846,-0.441115,0.112148,-0.654801,0.018081,0.166862,-0.202435,-0.316744,0.242623,-0.387010,0.463859,-0.522554,0.167083,0.606576,0.278251,-0.308671,0.417299,0.041701,0.010922,-0.268208,-0.086113,0.180112,0.218689,0.154969,0.196170,0.150160,0.243522,-0.464229,-0.325060,0.383954', '1307442', '4301278', '34890458', '1484091'