INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297320', '艳舞女郎', '剧情', '诺密（伊丽莎白·伯克利 Elizabeth Berkley 饰）是一名性感漂亮的女郎，年轻的她来到拉斯维加斯淘金，希望在这里能找到令她立足的工作。没想到，刚到此地，便被小混混骗走了行李，身无分文的她遇见了化妆师克里斯特（吉娜·格申 Gina Gershon 饰），两人一见如故结下了深厚的友谊。诺密发现，想在拉斯维加斯得到一个饭碗实在是太难了，热爱舞蹈的她最后决定加入当地最有名的艳舞团队。经过层层选拔，诺密得到了她的角色，而一旦开始涉入这个复杂的声色世界中，她沦陷的速度就再也不会停止。本来自尊自重的诺密，居然也开始为了向上发展而出卖自己的肉体。诺密越来越有名，但她和克里斯特的距离也越来越远。为了弥补这段友情，诺密安排了克里斯特和她的偶像歌手见面，没想到看似偶像实则禽兽，克里斯特惨遭凌辱住进医院，也击碎了诺密关于名声和金钱的最后的幻觉。©豆瓣', '伊丽莎白·伯克利', '保罗·范霍文', 7, 11381, 'tt0114436', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2126139368.jpg', 1.6, 7.8, 42.3, 35, 13.3, '0.588428,0.107052,-0.681937,0.675096,-0.126681,-0.401366,0.524245,0.016082,-0.356821,-0.263281,0.162407,0.739079,-0.287007,0.145465,0.357141,0.000011,-0.055267,-0.580329,0.070292,-0.290609,-0.251772,-0.343810,-0.382477,-0.211431,-0.235266,-0.218533,0.688156,0.192377,-0.158808,0.434956,0.329872,0.125548,0.222112,0.365763,-0.252132,0.099837,0.086783,0.088133,-0.121686,0.360772,0.077234,-0.274913,0.031922,0.230225,0.072110,0.299176,0.477761,0.002452,-0.170831,-0.027121,0.453843,-0.314950,-0.002837,0.081755,0.272412,-0.250869,0.224306,0.102511,-0.297894,0.045225,0.078648,-0.261242,-0.753648,0.120634,0.073136,-0.038479,-0.653624,0.386567,-0.084702,-0.149971,0.113202,-0.305699,0.077965,0.318975,0.175686,0.366071,-0.164288,-0.023659,-0.519169,0.126382,0.710251,-0.040358,-0.200588,0.453801,-0.196822,-0.383876,-0.057282,-0.358604,-0.160404,-0.096073,0.236967,0.000830,-0.045030,0.155717,-0.627281,-0.028658,-0.349697,-0.064993,-0.032931,-0.456049,-0.036110,-0.456016,-0.261496,-0.328146,-0.259384,0.152483,-0.077055,-0.343221,0.712003,-0.935604,0.071515,0.725725,0.221749,-0.676397,0.465350,0.238449,-0.015218,-0.149024,-0.358264,0.332641,0.078780,0.200368,0.159656,0.389950,-0.070925,-0.270340,-0.266784,0.463606', '1793491', '35030151', '35144311', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297347', '斗鱼', '剧情', '美国的塔尔萨，17岁的詹姆斯有一个绰号叫“摩托车手”的哥哥。“摩托车手”是一个传说中的神奇人物，擅于打架斗殴，并是一个天生的青年帮会的领袖。一天晚上，詹姆斯和女朋友帕蒂约会时碰到了号称“打架大王”的威尔科斯，“打架大王”向詹姆斯挑衅，两人打成一团。詹姆斯不是对手，多处受 伤，在这关键时刻，消失了两个星期的“摩托车手”突然出现了，赶走了“打架大王”，并照料詹姆斯。厌倦了过去生活的“摩托车手”同黑社会脱离了关系，行踪不定，但仍享有很大的名气。由于经常逃学，詹姆斯被学校开除了，帕蒂也同他分了手。一天，詹姆斯在一家动物商店发现了“摩托车手”，哥哥将一些红、蓝两色的暹罗斗鱼指给弟弟看，并告诉他：这些鱼如果被关在密闭的容器里就会相互厮杀，直至死亡。“摩托车手”要将暹罗斗鱼带到河边去放生，这样它们就不会自相残杀。但就在他走到河边的时候，却被警察开枪打死。詹姆斯遵循着哥哥最后的指示，带着暹罗斗鱼，骑上摩托车，直向大海而去。', '马特·狄龙', '弗朗西斯·福特·科波拉', 8.1, 5674, 'tt0086216', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p472330250.jpg', 0.6, 2, 19, 48.7, 29.7, '0.476000,-0.066210,-0.614154,0.492017,-0.170080,-0.266867,0.821106,0.240690,-0.152846,-0.158965,0.214783,0.759965,-0.076065,0.111465,0.216804,0.053630,-0.062791,-0.819792,-0.092287,-0.009786,-0.610887,-0.211217,0.126187,-0.125500,0.030683,-0.112970,0.265119,0.010155,-0.103223,0.624021,0.267710,-0.157180,-0.034299,0.477814,-0.511785,0.052812,-0.067887,-0.194909,0.049794,0.426733,0.094795,-0.086940,0.105888,0.006116,0.077384,0.214329,0.464894,-0.101023,0.072762,-0.077231,-0.017418,-0.237920,0.001983,0.098866,0.499702,-0.095086,0.186459,-0.159421,0.022450,0.092028,0.251666,-0.055479,-0.343941,0.253454,-0.487309,0.185109,-0.826024,0.318272,-0.074064,-0.106942,-0.086885,-0.210844,0.315048,0.108317,0.047481,0.264155,0.007447,-0.015466,-0.714095,-0.259673,0.479605,-0.164174,0.097974,0.183969,-0.072815,-0.257227,0.040733,-0.166462,-0.283819,-0.218219,0.561026,-0.338958,-0.540453,0.211220,-0.570435,0.179576,-0.260490,-0.162950,-0.157774,-0.416877,0.055904,-0.348084,0.143079,-0.333129,-0.120521,0.367950,0.149645,-0.220843,0.346145,-0.802214,0.274973,0.714312,0.396861,-0.212272,0.588243,0.104640,0.035544,-0.099975,0.052574,0.018471,0.373376,0.488194,0.357692,0.468630,0.100814,-0.221175,-0.428189,0.442571', '1303462', '1947080', '1805685', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297359', '幽灵公主', '动画', '为了拯救危难中的村民，阿斯达卡的右手中了凶煞神的诅咒。达卡只好离开亲人往西方流浪以寻找解除诅咒的方法。旅途中他遇到了由幻姬大人带领的穷苦村民在麒麟兽的森林里开采铁矿，提炼矿石。 白狼神莫娜和她养大的人类女孩“幽灵公主”桑对幻姬恨之入骨，因为她们觉得幻姬带领众人破坏了森林。想帮助人类的阿斯达卡被桑深深吸引，他理解她，但为了帮助穷人又不得不和她作战。一次战斗中，阿斯达卡被麒麟兽所救，他的立场更加摇摆不定。 这时，以疙瘩和尚为首的一群人来杀麒麟兽，幻姬以火枪击毙了麒麟，麒麟的头被疙瘩和尚抢走。愤怒的麒麟的灵魂为夺回自己的头，大肆破坏着森林。阿斯达卡和桑联手决定帮麒麟夺回头颅。©豆瓣', '松田洋治', '宫崎骏', 8.9, 491139, 'tt0119698', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1613191025.jpg', 0.1, 0.5, 8.3, 35.5, 55.6, '0.244648,0.058495,-0.464468,0.581362,-0.079834,-0.367172,0.720747,0.014955,-0.388542,-0.079684,0.475174,0.451699,0.332758,-0.009437,0.295097,0.058347,-0.202441,-0.347070,-0.000900,0.033874,-0.251501,-0.042218,-0.372253,-0.374437,-0.298997,-0.448009,0.663039,0.355189,-0.049765,0.305608,-0.129539,0.506816,-0.160936,0.312976,0.040123,-0.037177,-0.132921,-0.205269,0.078602,0.582463,-0.299531,0.124263,-0.077923,0.586934,-0.144055,0.311829,0.666542,-0.976410,0.220822,-0.674334,0.033216,-0.626528,0.164468,0.302396,0.243367,-0.256081,0.369273,-0.087522,-0.114748,-0.172804,0.120028,-0.033798,-0.665735,-0.201591,-0.106402,-0.092495,-0.742385,0.012053,0.116617,0.222804,0.506455,-0.251589,0.042659,0.263648,0.423669,0.411426,-0.265778,-0.345352,-0.361191,-0.146104,0.493450,-0.499926,-0.028222,-0.371351,-0.339114,-0.567697,0.119560,-0.298349,-0.034707,-0.332414,0.530382,0.271649,-0.171443,0.434621,-0.684762,-0.166238,-0.289091,-0.248296,-0.103280,-0.392719,-0.053930,-0.202198,0.019631,-0.108277,0.111088,-0.240856,0.308102,-0.124745,0.463916,-0.796212,0.360107,0.472858,0.582264,-0.390048,0.272319,-0.224544,0.023164,-0.246933,-0.174382,0.309317,0.231803,0.452484,0.220554,0.006314,0.225135,0.135141,-0.378102,0.408077', '3213270', '1305071', '25774050', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297368', '卓别林', '剧情', '传记作家乔治赴瑞士采访卓别林（Robert Downey Jr 饰），后者将自己的故事娓娓道来……1894年的英国，小小年纪的卓别林已经开始为临时演员母亲救场，但失祜的困苦生活导致卓别林兄弟分离，母亲也因发疯入院。1903年，卓别林经哥哥介绍进入一家英国剧团开始自己的 演艺生涯，不久他打出名号，获得美国制片厂的邀请，在美国，卓别林接触到梦幻般的电影艺术，并用自己的灵气在电影这种媒介的帮助下名利双收。卓别林无法忘记自己的出身，掌握制片权后坚持在自己的影片中加入批判精神，也因此被扣上红色份子的帽子，惹上诸多麻烦。这位卓越的电影人经历了政治打压、情人们的离去、成功与失落后垂垂老矣，他在影院看着自己当年的电影，潸然泪下。本片获1993年英国电影学院奖最佳男演员，伦敦影评人协会年度演员奖，芝加哥影评人协会奖最有前途女演员奖。©豆瓣', '小罗伯特·唐尼', '理查德·阿滕伯勒', 8.6, 16467, 'tt0103939', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2236690438.jpg', 0.2, 0.7, 10.7, 44, 44.5, '0.069644,0.105311,-0.560805,0.594696,0.297445,-0.274810,0.376219,0.170607,-0.482469,-0.162250,0.239265,0.991284,-0.361566,0.254928,0.279372,-0.063427,-0.404609,-0.766488,-0.059870,-0.023804,0.064436,-0.155467,-0.264545,-0.117585,-0.342209,-0.501892,0.787326,0.118902,-0.340101,0.342388,0.387066,0.168657,0.219221,0.048888,0.015034,0.222427,0.174593,0.051190,-0.374077,0.371047,0.242013,-0.440017,-0.219765,0.018863,0.057026,0.146779,0.662860,0.131087,-0.020639,-0.232883,0.817923,-0.374362,-0.153374,0.034280,0.203435,0.227481,0.257936,0.246726,-0.070940,0.191769,-0.225431,-0.197651,-0.688513,0.039355,0.225038,0.179480,-0.600291,0.306287,-0.081371,0.231656,-0.274992,-0.248679,0.134452,0.251072,0.252503,0.171427,-0.153462,0.183250,-0.354358,0.817626,0.674998,-0.148420,-0.218422,0.280554,-0.205553,-0.507637,-0.162899,-0.505000,-0.476860,0.127402,0.315703,-0.189164,-0.040057,0.199044,-0.486319,-0.057170,0.091626,-0.307470,0.099848,-0.284003,0.207906,-0.946464,-0.245497,-0.231491,-0.269724,-0.391849,0.205949,-0.423809,0.921397,-0.533720,0.250604,0.532233,0.279452,-0.432322,1.019300,-0.114157,-0.010738,-0.114629,-0.181022,0.418481,-0.084834,0.095680,-0.160565,0.116650,-0.040588,-0.379197,-0.045145,0.413745', '2027945', '22265121', '1322847', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297389', '生死时速2：海上惊情', '动作', '安妮（桑德拉·布洛克 Sandra Bullock 饰）和杰克的恋情并未走到最后，失落的安妮决意不再与特警恋爱，现任男友亚历克斯（杰森·帕特里克 Jason Patric 饰）为爱情隐藏特警身份，但无奈还是暴露，于是携安妮前往加勒比海度假作为弥补。在他们的游轮上，潜藏着一名危险人物——设计轮船操作系统的工程师基格（威廉·达福 Willem Dafoe 饰），基格身患绝症却遭到解雇，他为了报复公司掌控了轮船的自动航行系统，在船内装满炸弹，船长只得与乘客弃船，危机关头，亚历克斯挺身而出，与安妮返回船上救助被困的乘客。在游轮冲向毁灭终点的同时，安妮又落入了基格之手……©豆瓣', '桑德拉·布洛克', '扬·德·邦特', 5.9, 7898, 'tt0120179', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2182082745.jpg', 4.6, 20.9, 54.4, 15.7, 4.4, '0.130006,-0.060657,-0.627342,0.284561,0.031874,-0.373718,0.840177,0.223081,-0.255111,-0.013548,0.666695,0.730937,0.025283,-0.056741,0.507177,0.052209,-0.835898,-0.386134,0.211335,-0.112150,-0.192405,-0.592982,-0.181344,-0.133400,0.051606,-0.320001,0.938420,0.084095,-0.262675,0.477297,0.229793,0.530161,-0.503238,0.655397,0.027567,0.044716,0.244307,-0.346150,-0.337842,0.237388,-0.215302,-0.137177,0.145652,0.027844,0.092005,0.456204,0.657174,-0.283987,0.120737,0.043377,-0.034828,-0.518756,0.204085,-0.101675,0.312498,0.048737,-0.275454,-0.037782,-0.213693,0.012551,0.361863,0.081349,-0.604387,0.029665,-0.206493,0.146496,-0.427243,0.006290,-0.482237,0.051704,0.118231,-0.402828,-0.038699,0.184732,0.215997,0.138347,-0.296850,0.379296,-0.544952,-0.136204,0.485474,-0.036512,-0.021313,0.184685,0.068559,-0.301631,-0.107623,-0.184793,-0.628406,-0.282805,0.497934,0.280681,0.065862,0.347971,-0.541538,-0.171325,-0.498985,-0.184940,-0.030845,-0.300586,-0.202000,-0.885393,0.139860,0.023031,-0.116909,0.020799,0.177486,-0.003929,0.449487,-0.707594,0.247495,0.478817,0.351103,-0.368765,0.557658,0.098987,0.287571,-0.354611,-0.013578,0.379863,-0.139538,0.448598,-0.007943,0.051523,0.034612,-0.105530,-0.318482,0.178658', '2369613', '20274039', '1316693', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297395', '群龙夺宝', '剧情', '富商宋金荣与保险巨头吴家结怨，为了报复吴家，他特意将自己收藏的旷世奇珍——可兰经公开展览，并向吴家买了巨额保险。宋金荣找到了神偷卓非凡（泰迪罗宾 饰），要求他盗取可兰经，以此迫使吴家破产。卓非凡觉得偷取可兰经十分好玩，就答应了宋金荣；另一方面，吴老板的义子陈查理（刘德华 饰）身手不凡，为了万无一失，他亲自负责可兰经的保安工作。同时，神枪手马如龙亦想将可兰经弄来送给女友，以讨女友欢心。一场争夺可兰经的游戏开始了。©豆瓣', '刘德华', '袁振洋', 7.3, 6488, 'tt0095946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2348542999.jpg', 0.7, 3.8, 39.9, 40.7, 14.9, '0.081768,0.006737,-0.342066,0.463712,-0.241148,-0.272502,0.119031,-0.001804,-0.485655,-0.347625,-0.018364,0.590232,-0.139951,0.021219,0.102257,0.104662,0.015296,-0.460564,-0.174107,-0.156259,-0.075058,-0.369457,0.069394,-0.408612,-0.194117,0.176691,0.237953,-0.144103,-0.216806,0.253977,0.433512,0.347595,0.057714,0.200119,-0.283607,-0.006226,-0.377431,0.058022,-0.492771,0.212618,0.388357,-0.297033,-0.121790,0.513308,0.407224,0.359485,0.431139,-0.114850,0.078170,-0.136053,0.260975,-0.103788,0.148705,-0.073815,0.131816,0.283265,0.082257,0.310499,-0.206391,-0.160184,0.209733,-0.314287,-0.516518,0.076301,0.326880,-0.408384,-0.371030,0.127083,-0.515754,0.302478,0.060918,-0.136340,0.365364,0.281110,0.288826,-0.153865,-0.038483,0.048371,-0.585346,0.705737,0.311031,-0.098454,0.710100,0.004814,-0.113379,-0.332116,0.436242,-0.251405,-0.057911,0.007166,0.828913,-0.332707,0.558067,-0.240110,-0.553363,-0.554669,-0.445310,-0.079023,0.274759,-0.434918,0.257708,-0.316518,-0.108792,-0.013613,0.054814,-0.239959,0.147453,-0.420362,0.706095,-0.560382,-0.160494,0.594592,0.288965,-0.868490,0.353376,-0.165323,0.192309,-0.265724,-0.251479,-0.269225,0.419993,0.337525,0.224841,-0.070882,0.357262,-0.346532,-0.045731,0.077611', '1302110', '1300857', '5973984', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297399', '怪房客', '剧情', '内向的波兰裔青年塔尔科夫斯基（罗曼·波兰斯基 Roman Polanski 饰）独自来到巴黎，希望在此租住一间公寓。这间房之前的房客西蒙·肖（Romain Bouteille 饰）不知出于何种原因跳楼自杀。在西蒙于医院中气绝身亡后，塔尔科夫斯基顺利地成为了新的房客。乔迁之喜并未给他带来太多欢乐，周遭的压抑气氛无时无刻不在侵扰他的神经。这桩古老的公寓中住着许多古板沉闷的人，他们抱怨塔尔科夫斯基制造过多的噪音、联名排挤其他房客……这个可怜的青年虽然小心应对，却渐渐被他们逼向绝境。塔尔科夫斯基开始意识到西蒙·肖自杀的原因，他同时发现，自己也正被这群怪房客引向毁灭的终点……©豆瓣', '罗曼·波兰斯基', '罗曼·波兰斯基', 7.9, 18684, 'tt0074811', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318513541.jpg', 0.5, 2.1, 22.5, 51.9, 23, '0.476977,0.140415,-0.854457,0.245328,-0.296918,-0.197446,1.048972,0.265183,-0.519473,-0.296971,0.145120,0.579277,-0.166813,0.222493,0.330730,0.126729,-0.366376,-0.247124,-0.108458,-0.138350,-0.356255,-0.512475,-0.199155,-0.244470,-0.092155,-0.226980,0.322662,0.388753,-0.250893,0.138601,0.193063,0.534463,0.015149,0.590725,0.027046,0.183462,0.331147,-0.196053,0.071236,-0.032945,0.015782,-0.213040,-0.355247,0.381372,-0.030385,0.499609,0.662369,-0.074675,0.029061,0.144241,0.263341,-0.099216,0.086056,0.188399,0.211140,-0.156738,0.163818,0.032897,-0.274470,0.136133,-0.065855,0.108659,-0.403624,0.199771,0.127823,0.169618,-0.356416,0.505488,-0.205144,-0.133261,-0.003696,-0.265101,0.046947,0.551016,0.183914,0.366998,-0.221067,0.087122,-0.344272,-0.039661,0.662054,-0.169226,-0.343343,0.120252,-0.534416,-0.411382,0.064343,-0.019863,-0.514531,-0.565886,0.515114,0.161300,-0.018585,0.154779,-0.570670,-0.052821,-0.293394,-0.315942,-0.180723,-0.206164,-0.151158,-0.701846,-0.273867,-0.326185,0.023244,-0.212093,-0.084677,0.071525,0.363423,-0.528847,0.332925,0.517339,0.463777,-0.183266,0.218758,-0.000351,0.320069,0.110219,-0.219100,0.264312,0.201057,0.379217,0.157820,0.409314,0.101094,-0.085427,-0.331307,0.485509', '3011051', '20451118', '2269893', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297418', '麻将', '剧情', '富商儿子红鱼（唐从圣饰）从父亲那里学到很多骗人之术，他和纶纶（柯宇纶饰）、牙膏（王启赞饰）、香港（张震饰）组成一个四人小集团，到处敛财骗色。有一次，他们在咖啡店里遇见从法国来台北寻找男友的女孩马特拉（维吉妮亚•雷多尔恩饰），红鱼就此盯上了她，意图欺骗对方。但伦伦良心发现，并带马特拉躲到了自己家。之后，红鱼要报复曾与父亲（张国柱饰）有奸情的老女人Angel（吴家丽饰），要香港去勾引她……。另一边，一生骗人无数的红鱼父亲却深觉人生空虚，等待他们每个人的将是什么命运？©豆瓣', '柯宇纶', '杨德昌', 8.7, 42251, 'tt0116962', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2327303475.jpg', 0.1, 0.7, 9.8, 44.4, 44.9, '0.073838,-0.099335,-0.462995,0.439500,-0.144623,-0.272419,0.672904,-0.046810,-0.583511,-0.087074,-0.061923,0.832413,-0.057422,0.079549,-0.012243,0.384895,-0.215793,-0.532697,0.210262,-0.092863,-0.195524,-0.318930,-0.225447,-0.217363,-0.098739,0.065282,0.273594,-0.045254,-0.074112,0.275755,0.518832,0.293746,-0.357122,0.231723,-0.056106,0.275150,0.078128,0.040192,-0.121157,0.217971,-0.082527,-0.218682,-0.279386,0.094241,0.074331,0.373764,0.477688,0.046922,0.163709,-0.205956,0.034948,-0.214311,-0.125783,0.026676,0.122867,-0.442779,0.282837,0.311399,-0.189051,-0.110289,0.094186,0.204297,-0.607814,-0.209465,0.168505,0.051016,-0.541988,0.104066,0.033694,0.011598,0.078066,-0.316773,0.175338,0.185310,0.007757,0.010747,-0.019812,-0.131093,-0.567880,0.120772,0.637963,-0.130412,0.350837,0.279383,-0.089209,-0.070764,0.002355,-0.079080,-0.515327,-0.007350,0.350810,-0.085237,-0.305991,0.095230,-0.639490,-0.057362,-0.261497,0.144120,0.197999,-0.276669,-0.060544,-0.392672,0.119414,-0.456133,-0.300606,-0.104787,0.007168,-0.090550,0.403817,-0.728661,0.212586,0.586161,0.263437,-0.433646,0.632264,-0.040997,-0.161362,-0.223680,0.044527,0.107242,0.240844,0.129922,-0.042760,0.191331,0.155482,0.065819,-0.163012,0.305367', '1783461', '3055049', '30162520', '1299799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297445', '洛奇4', '剧情', '1985年，那时正是美苏两极争霸越演越烈的年代，史泰龙自导自演的洛基系列也出到了第四集，这一系列影片旨在振奋人心、宣扬美国精神。这一集讲述的是洛基（西尔维斯特•史泰龙 Sylvester Stallone 饰）的好友前美国拳王到苏联出战他们研制的拳击机械人，不敌对手最终身遭不测。为了帮好友复仇和维护国家荣誉，洛基决定再次出马。出战前，洛基进行了一系列精心的准备工作，他深入到大自然，利用自然的艰苦条件刻苦训练。当一切准备妥当，洛基和苏联拳王――拳击机械人的决斗展开了！©豆瓣', '西尔维斯特·史泰龙', '西尔维斯特·史泰龙', 7.7, 12699, 'tt0089927', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199972853.jpg', 0.9, 4.3, 29.9, 39.5, 25.5, '0.053446,-0.011494,-0.811286,0.551418,0.111643,-0.084950,0.114718,-0.141896,-0.326713,-0.294546,0.306450,0.587520,-0.064198,-0.244446,0.238441,-0.202102,-0.515368,-0.691023,-0.131261,0.145392,-0.218813,-0.369267,-0.210682,-0.323628,-0.104684,-0.210874,0.504155,0.005736,-0.176717,0.365787,0.102575,0.301555,0.143541,0.210172,0.126594,-0.081701,0.011581,-0.171060,-0.626204,0.108364,0.089023,-0.221588,-0.298979,0.290841,0.102707,0.475058,0.497029,-0.275667,-0.012153,-0.202443,0.584574,-0.422784,-0.066481,0.073594,0.208851,0.072256,0.033487,0.222096,0.177854,0.033758,-0.094120,-0.368705,-0.727109,-0.105241,-0.041028,-0.090277,-0.380451,0.596111,-0.272179,0.296694,0.150666,-0.272487,0.001035,0.576732,0.611866,0.170772,-0.046400,-0.130117,-0.265233,0.485482,0.692473,-0.162317,-0.188145,0.255584,0.048094,-0.394349,-0.055427,-0.406541,-0.067580,-0.078150,0.454717,0.063931,0.051295,0.318138,-0.598070,-0.118727,-0.213900,-0.351942,0.049314,-0.282598,0.196352,-0.924486,-0.269576,-0.176127,-0.114410,0.168256,0.085154,-0.338943,0.621744,-0.679528,-0.024690,0.719901,0.178271,-0.472157,0.256505,0.014557,0.200732,-0.265279,-0.099613,0.036480,-0.141849,0.277727,0.143052,0.450641,0.446642,-0.038065,-0.207065,0.416616', '11541282', '24751811', '30229667', '1307762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297447', '倩女幽魂', '爱情', '书生宁采臣（张国荣饰）收账不成，无处可归，遂夜宿鬼寺兰若寺，遇上侠士燕赤霞（午马饰），二人成为邻居。一日偶遇艳女小倩（王祖贤饰），二人两情相悦，但小倩乃是被树妖姥姥控制的鬼魂，专门迷惑精壮男子代姥姥吸取阳气。小倩见宁采臣心地善良不忍加害，并与他感情逐渐加深。宁采臣欲救小倩脱离姥姥魔掌，但苦于姥姥功力深厚，小倩无法脱离其魔掌。二人遂向燕赤霞求救......©豆瓣', '张国荣', '程小东', 8.8, 685314, 'tt0093978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2414157745.jpg', 0.1, 0.4, 9.3, 41.6, 48.5, '0.184420,-0.142410,-0.224896,0.084105,-0.079030,-0.375310,0.438685,0.107717,-0.540469,-0.260149,-0.011136,0.074536,0.165652,0.233307,-0.224032,0.069800,0.377258,-0.356157,0.062728,0.075615,0.389611,-0.082229,-0.001680,0.449181,-0.307537,-0.348974,0.540092,-0.128414,-0.228218,0.620466,0.086219,0.358851,-0.701912,0.265727,-0.083686,0.275643,-0.219464,-0.226677,-0.490554,0.296961,0.083326,-0.209683,-0.064915,-0.013890,-0.494169,0.214509,0.697442,-0.068363,-0.190079,-0.369239,0.140436,0.130255,0.112300,0.284283,-0.046723,-0.005870,0.357681,0.050262,-0.213374,-0.161862,0.070472,0.063669,0.105961,0.513120,0.619140,-0.170995,-0.382299,0.193177,-0.022891,-0.131646,-0.214628,-0.406242,-0.322011,0.002917,0.113413,0.073356,-0.474670,-0.232517,-0.340613,0.176981,0.481036,0.151097,0.136988,0.162660,0.218228,-0.062639,0.250292,-0.117304,-0.266937,-0.001490,0.372283,0.323921,-0.274009,0.367742,-0.288723,-0.095288,-0.517987,0.745774,-0.133965,-0.095248,0.251761,-0.418372,-0.271116,0.058266,0.039758,-0.169192,0.359470,-0.209207,0.396231,-0.557250,0.162917,0.262270,0.357321,-0.418689,0.317534,-0.151218,0.102493,-0.215347,-0.200094,0.343992,-0.103780,0.227267,0.461633,0.048308,-0.126617,0.282057,-0.206617,-0.265566', '1296629', '1302393', '4328444', '1292506');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297478', '上帝也疯狂', '喜剧', '广袤无垠的非洲大陆，现代文明与原始社会和谐共存。在离现代大都市六千公里的卡拉哈里沙漠腹地，生活着仍未受到外来文明影响的布须曼人。他们刀耕火种，狩猎农作，过着与世无争、敬畏自然的平静生活。某天，一支来自现代文明的可乐瓶打乱了他们一成不变的日子。最先发现瓶子的基（N!xau 饰）将其带回部落，族人惊叹可乐瓶子的完美构造和繁多的用途，认为这是上帝赐予他们的礼物。可是兴奋的心情很快为别样的情绪所取代，习惯了平等共有的族人开始想要将瓶子据为己有，矛盾悄然而生。基不愿看到族人发生争吵与殴斗，于是决定将可乐瓶还给上帝，只为恢复曾经平静快乐的生活……©豆瓣', '马瑞斯·威尔斯', '加美·尤伊斯', 8.7, 134101, 'tt0080801', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2173719538.jpg', 0.3, 1, 11.7, 38.9, 48.1, '0.318366,0.351257,-0.472950,0.591636,0.149424,0.083132,0.789534,0.030283,-0.479975,-0.204714,-0.143108,0.518748,0.181390,-0.049946,0.371780,-0.085535,-0.246108,-0.513997,-0.419552,-0.069305,-0.159064,-0.255678,-0.200946,-0.180345,-0.088696,-0.629496,0.482425,0.170551,-0.216944,0.521435,-0.243366,0.298303,-0.414495,0.402315,-0.294768,-0.240639,-0.402325,-0.002384,-0.645885,-0.120986,-0.281144,0.000039,-0.046532,0.325360,0.087843,0.039931,0.760850,-0.471457,-0.519843,-0.060151,0.345386,-0.066803,-0.214546,-0.088485,0.182325,0.267970,-0.052078,0.059285,-0.113344,0.156637,0.180594,-0.247034,-0.650571,0.037397,-0.129475,0.163901,-0.371690,0.740369,0.229839,-0.133363,0.132552,-0.134332,0.345352,0.493805,0.461682,0.623958,-0.155632,-0.047665,-0.639217,0.080137,0.750732,-0.234593,-0.272642,0.200224,-0.510759,-0.608052,-0.051452,-0.329862,-0.422068,0.034617,0.176138,0.441045,-0.059714,0.701958,-0.988532,0.254930,-0.064078,-0.526406,0.581555,-0.424601,-0.328676,-0.280209,-0.204897,-0.188353,-0.298335,0.043484,0.103625,-0.210266,0.801587,-0.729020,0.396755,0.336273,0.123267,-0.429778,0.618899,-0.097317,-0.184704,-0.342232,-0.161778,0.439221,0.083845,0.246449,-0.009920,0.268306,-0.094164,0.154914,-0.258066,0.428860', '26290398', '6982558', '1849026', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297497', '江湖情', '剧情', '香港早期，大量难民涌入，龙蛇混集。潮州人杨群带年幼的小凤和阿华（刘德华 饰）来港，不料投靠的朋友刚好去世，于是他独自抚养小凤、阿华和良仔。数年后，良仔（万梓良 饰）不学无术，沉迷赌博，结果欠下一笔巨款。阿华为救他被殴打致伤，并引来黑势力大佬的追杀，走投无路的他向周（周润发 饰）求救。周因阿华的英勇和义气将他留在身边并委以重任，使阿华继而平步青云；良仔轻佻浮躁，不得周的垂青，却因此对阿华怀恨在心。良仔勾结黑帮大佬杀死了得到周庇护的泰国毒枭（李修贤 饰），周要杀良仔报仇，后经阿华求情才获生路。但良仔不思悔改反要杀阿华，并策划在周结婚之日大开杀戒……©豆瓣', '周润发', '黄泰来', 7.2, 12159, 'tt0093306', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p987807504.jpg', 0.6, 4.1, 43.4, 37.3, 14.6, '-0.289229,-0.095456,-0.471507,0.364445,-0.179803,-0.453204,0.584624,0.096231,-0.281933,-0.133740,-0.161956,0.398262,-0.002499,0.449110,0.198020,-0.287686,0.066655,-0.552876,-0.025459,0.113571,-0.021006,-0.373388,-0.049267,-0.306888,-0.268892,0.056092,0.320985,0.221162,-0.297119,0.704553,0.493129,0.211379,-0.273550,0.550943,-0.126692,0.139255,-0.143071,0.131906,-0.288151,-0.032321,0.124582,-0.577003,0.082110,0.148013,0.164009,0.359518,0.371696,-0.103516,0.079368,-0.356231,0.385322,-0.520981,0.111961,0.026529,0.252770,0.062711,0.148696,0.211222,-0.154136,-0.079328,0.004995,-0.172899,-0.454416,-0.070430,0.210444,-0.215485,-0.530297,0.172692,0.078070,0.293669,-0.175156,-0.007742,0.102352,0.298368,0.023052,0.151432,-0.037387,0.245876,-0.464435,0.262948,0.388638,-0.305867,0.196612,-0.172666,0.274952,-0.429399,0.334886,-0.093581,-0.179992,-0.031204,0.599204,-0.243213,0.070574,-0.006777,-0.289538,-0.380354,-0.261674,0.198715,0.039427,-0.189164,0.245024,-0.409794,-0.048190,-0.192928,-0.177197,0.251428,0.227174,-0.318808,0.503383,-0.400444,0.137299,0.452508,0.497406,-1.023785,0.413064,0.091109,0.105220,-0.176291,0.040115,0.270618,0.583932,0.120146,0.456888,-0.283008,-0.188510,-0.152262,0.050381,-0.025794', '1302110', '3998385', '1304021', '1300857');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297503', '月球漫步', '音乐', '迈克尔·杰克逊自资拍摄电影''Moonwalker''(外星战将),但是并没有得到预期的佳评。在这部电影中，迈克尔·杰克逊将自己塑造成一个漫画主角般，一身短小的西装，一顶压得很低的礼服帽，片中表演了惊人的顷斜45度的舞蹈。这些都成为了迈克尔·杰克逊个人神话中不可替代的标志。此片全场劲歌热舞，令人热血沸腾！ 洛杉矶市长Tom Bradley宣布11月为''Michael Jackson Month''(麦可杰克森月)。杰克逊推出了自己创作故事脚本，自己投资拍摄的音乐电影《Moonwalker》。在这部电影中，杰克逊俨然将自己塑造为一个如漫画名角迪克。崔西般的传奇人物。一身短小的西装，一顶压的很低的礼帽，袖子上扎着一个袖标，所有这些都成为了杰克逊个人神话中不可替代的标志性符号。值得一提的是，正是在这部电影中，杰克逊表现出了对于儿童的特有的偏爱。就像当年曾红遍中国大街小巷的游戏厅中那个根据《Moonwalker》改编而成的游戏里反映的那样，杰克逊不仅要拯救世界，杰克逊更重要的是拯救儿童。也正是从这张专辑开始，杰克逊和他的唱片公司一起走上了一条造神的不归之路.', '迈克尔·杰克逊', '科林·奇尔弗斯', 8.9, 6209, 'tt0095655', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1129454817.jpg', 0.6, 1.5, 11.2, 26.7, 60, '0.209550,0.017898,-0.412929,0.901005,-0.066802,-0.182836,0.653383,0.021747,-0.245851,-0.152110,0.133829,1.098874,-0.484969,0.216115,0.135608,0.008303,-0.417469,-0.907701,-0.486630,-0.114421,-0.064326,-0.189066,-0.507575,0.130781,-0.198904,-0.270943,0.902068,-0.001078,-0.450049,0.369478,0.489914,0.067199,0.288993,0.077011,-0.100871,-0.037208,-0.042146,-0.019340,0.025399,0.416320,0.089922,-0.158945,-0.024223,0.424541,-0.331457,0.307616,0.443157,-0.479537,0.085850,0.101089,0.906957,-0.166835,-0.143664,-0.101451,0.131330,0.285217,0.208877,0.168431,-0.142932,0.304417,-0.025680,-0.373684,-1.120356,0.032636,0.224510,0.303026,-0.505159,0.382792,-0.284100,0.117098,0.224605,-0.257988,0.103549,-0.188379,0.455211,0.513486,-0.045173,0.071013,-0.581537,0.763090,0.377581,0.168479,-0.376704,0.319919,-0.340630,-0.304343,-0.302599,-0.175210,-0.487728,0.082419,0.319511,-0.210790,0.149323,0.037077,-0.449349,0.137511,-0.080501,-0.478204,-0.253645,-0.273703,-0.033161,-0.929266,-0.155403,-0.443959,0.341684,-0.260707,0.215467,-0.427381,0.691109,-0.555392,0.060034,0.304494,-0.035599,0.001455,0.730298,-0.067878,0.202428,0.002756,-0.276885,0.162471,0.030766,0.077960,-0.030091,0.601789,0.234811,-0.483691,-0.594235,0.735605', '22265121', '2027945', '27602116', '26577354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297509', '超完美谋杀案', '惊悚', '史蒂文·泰勒（迈克尔·道格拉斯 Michael Douglas 饰）身为一位叱咤华尔街的百万富豪，金钱和地位却始终无法令他满足，他渴望的是妻子艾米丽（格温妮斯·帕特洛 Gwyneth Paltrow 饰）的忠贞爱情，但却从来吝于表达自己对她的爱。美貌与才情兼备的艾米丽并不想成为丈夫身边的一只花瓶，工作之余她偶然结识了才华横溢的穷画家戴维·肖（维果·莫腾森 Viggo Mortensen 饰），从他那里尝到了丈夫不曾给过的爱恋激情。然而，频繁的幽会最终还是被泰勒察觉，妒火中烧加之妻子身后巨额保险金的诱惑，使泰勒渐渐萌生了杀妻之念，他精心策划了一起超完美谋杀案，然而再完美的计划也赶不上变化，一场猫鼠游戏才刚刚开始……本片是翻拍自悬疑片大师希区柯克1954年的经典作品《完美的谋杀案》。©豆瓣', '迈克尔·道格拉斯', '安德鲁·戴维斯', 7.1, 22648, 'tt0120787', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2578851631.jpg', 0.5, 3.9, 44.7, 40.7, 10.2, '0.081547,0.045014,-0.737156,0.635136,-0.079847,-0.463249,0.637758,0.033995,-0.542081,-0.260888,0.160205,0.745838,-0.227976,0.207233,0.022400,-0.007319,-0.000249,-0.720760,-0.020379,0.018415,0.081011,-0.246564,-0.454092,-0.155501,-0.291597,-0.221979,0.681328,0.014930,-0.154935,0.453658,0.541523,0.181416,0.110348,0.484930,-0.014936,-0.077359,0.229538,0.206919,-0.460650,0.126770,0.076624,-0.355052,-0.192234,0.327665,-0.125360,0.340465,0.343359,-0.200841,-0.108419,0.005922,0.458785,-0.055632,0.094379,0.090116,0.009026,-0.094739,0.132021,0.131549,-0.059617,-0.178574,0.191611,-0.057323,-0.888207,-0.181272,0.030133,0.022393,-0.500048,0.382641,-0.170361,-0.044960,-0.013153,-0.054232,-0.027598,-0.089937,0.327799,0.213784,-0.219934,0.135615,-0.319614,0.599985,0.535837,0.297271,-0.287232,0.604952,-0.513477,-0.609450,-0.079584,-0.495671,-0.658762,0.146674,0.186573,0.216165,0.033027,0.378041,-0.382472,-0.122579,-0.392838,0.171694,-0.005093,-0.472141,0.108520,-0.433891,-0.383648,-0.651121,-0.442679,-0.047069,0.061802,-0.427912,0.616787,-0.713386,0.234296,0.570101,0.105552,-0.381712,0.677824,0.245456,-0.067824,-0.076416,-0.141473,0.536160,-0.094069,-0.238605,0.098727,0.149775,0.101584,-0.110470,-0.211857,0.742184', '1306795', '34890458', '30279170', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297514', '画魂', '剧情', '民初女画家潘玉良的传奇一生。潘玉良原是江南的妓女出身,对绘画独有天分，却无人赏识。一次机缘让她认识了芜湖海关盐业总监潘赞化（尔东升饰），随即被纳为妾。她随潘赞化到了上海,因为见她喜欢绘画，潘赞化介绍了专业老师让她学习，从此开始了学画的学生生活。其后由于潘赞化的正室的介入让原本感情很好的二人渐渐产生了矛盾。她于是留学巴黎,渐渐成为国际著名的画家。上海美术学院校长刘海粟观念开明,请她回国任教,不料学风开放的欧洲与国内艺术界的情形大相径庭。一心为艺术的潘玉良被保守的知识分子们指责为“妓女艺术家”，抨击与阻碍她教授的人体画艺术......©豆瓣', '巩俐', '黄蜀芹', 7.3, 10123, 'tt0107158', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165947843.jpg', 0.5, 4, 41, 41.4, 13.2, '0.533173,-0.005384,-0.624541,0.720317,-0.087243,-0.394966,0.254683,0.277038,-0.709966,-0.341939,0.023979,0.952689,-0.089255,0.232201,0.196703,0.031306,-0.133341,-0.722216,0.144084,-0.194976,-0.006667,-0.383707,-0.073789,-0.098185,-0.392518,-0.349693,0.446108,0.072224,-0.220182,0.618745,-0.062741,0.193189,0.286095,0.301733,-0.243378,-0.125607,0.286975,0.079306,-0.390776,-0.045149,0.127310,-0.422860,-0.119549,-0.063592,-0.132920,0.159839,0.545341,0.016768,0.022363,-0.262783,0.655208,-0.208435,0.006077,0.204805,0.217340,0.285574,0.094403,0.328139,-0.254222,0.067364,-0.179753,-0.246111,-0.306468,0.010136,0.343622,0.028880,-0.631306,0.658464,0.024755,-0.307731,-0.197493,-0.227378,0.056743,0.114532,0.004255,0.408638,0.095415,0.367204,-0.206422,0.549327,0.567663,0.160657,-0.333293,0.174126,-0.310915,-0.387469,0.331930,-0.520868,-0.293642,-0.029391,0.084344,-0.090243,-0.100309,0.116286,-0.645316,-0.077021,-0.155019,0.103154,0.077170,-0.446781,0.131347,-0.628997,-0.184313,-0.486438,-0.208016,-0.469031,0.223883,-0.270706,1.029618,-1.027889,0.007640,0.422534,0.371521,-0.806084,0.845480,0.162321,-0.029669,-0.181681,-0.172537,0.000381,-0.183707,0.434903,-0.133085,0.570638,0.193350,-0.388328,-0.134921,0.484380', '3445516', '1292720', '25922902', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297517', '新天龙八部之天山童姥', '动作', '天山派李秋水（林青霞 饰）爱上掌门师兄逍遥子，却不知逍遥子所爱的其实是李秋水的孪生妹妹李沧海（林青霞 饰）。而天山童姥巫行云（巩俐 饰）对李沧海亦有超越性别之爱。逍遥子被同门叛徒丁春秋（徐少强 饰）下毒中伤，被迫归隐到飘渺峰，设下“玲珑棋局”等来本性善良、佛性极深的有缘人虚竹 （林文龙 饰），将百年功力悉数相传，以期代他清理门户。 为夺少林宝物，丁春秋率阿紫（张敏 饰）、诱动连手的李秋水等人欲血洗少林，得到了逍遥子毕生功力的虚竹在巫行云的帮助下临危受命，与丁春秋展开了回合大战。©豆瓣', '林青霞', '钱永强', 7.5, 74555, 'tt0111776', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2168076509.jpg', 0.6, 3.5, 33.4, 43.5, 19, '-0.033093,0.270968,-0.481900,0.825782,-0.087388,-0.581774,0.148707,-0.061469,-0.432573,-0.295351,0.285572,0.262650,-0.003869,0.019630,-0.157348,-0.147430,0.327027,-0.694263,-0.191227,-0.287109,-0.173868,-0.187393,0.017310,0.115636,-0.349617,-0.155862,0.441959,0.050027,-0.138889,0.308033,0.448139,0.293031,-0.156928,0.274034,-0.165730,0.221607,-0.254762,0.035279,-0.430422,0.395632,-0.114094,-0.518672,-0.098059,0.141761,-0.613617,0.378084,0.488405,-0.295321,-0.032442,-0.335470,-0.066111,-0.077268,0.028157,0.230116,0.431878,-0.033104,-0.006110,0.402477,-0.224556,-0.046798,0.193006,0.079891,-0.300340,-0.011471,0.536274,-0.060868,-0.407767,0.265791,-0.553981,0.059750,-0.257082,-0.514316,-0.209888,0.020442,0.413327,0.051240,0.008645,-0.270388,-0.351018,0.334150,0.442890,-0.125155,0.619828,0.043766,0.274873,-0.332124,0.082865,-0.329395,0.043162,0.049578,0.605513,-0.184665,0.353995,0.330884,-0.175794,-0.330165,-0.270040,0.491845,-0.245641,-0.165480,0.207944,-0.469770,-0.275483,-0.233357,-0.143823,-0.288813,0.443262,-0.177200,0.930854,-0.650913,0.201047,-0.084377,-0.074003,-0.457634,0.400402,0.055231,-0.099973,-0.215773,-0.348532,0.359746,-0.089379,0.398674,0.385098,0.270032,0.042198,0.227551,-0.212238,-0.062195', '25922902', '27602116', '25863940', '1303010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297518', '九品芝麻官', '剧情', '包龙星（周星驰 饰）用钱买来了一个候补知县的职位，可是为人贪婪，县上的人都对他痛恨之极。在他代替正式知县的时候，戚家媳妇戚秦氏（张敏 饰）遭到了常威( 邹兆龙 饰 )的强暴，后来常威动了杀机把戚家上下都杀害了，更嫁祸于戚秦氏。常威是水师提督大人的儿子，请来大状方唐镜（吴启华 饰），收买了所有证人以便洗脱罪名。包龙星虽然极力寻找证据，也被迫害至落难他乡。他决定要上京告御状，后来他因没钱不得不在妓院打工，向老板娘学习了一身斗嘴的好功夫。他在妓院里误打误撞认识了皇上，帮助皇上有功他被封了大官，重审戚家被害的案件。他凭着聪慧与口才，全力为戚秦氏讨回公道。©豆瓣', '周星驰', '王晶', 8.7, 612524, 'tt0110201', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p648370300.jpg', 0.1, 0.4, 10.3, 43.6, 45.5, '0.002071,-0.046435,-0.537227,0.542117,-0.555560,-0.207951,0.420747,0.419911,-0.780304,-0.222380,0.316395,0.587831,0.025913,0.036344,-0.056440,0.041806,-0.091157,-0.594954,0.130151,-0.308545,-0.111258,-0.446755,-0.081868,-0.282277,-0.208440,-0.126569,0.078946,0.052740,-0.077730,0.072515,0.440862,0.105914,0.164634,0.511990,-0.357371,0.202416,0.041573,-0.209688,0.070065,0.099469,0.017248,-0.680563,-0.133607,0.242275,0.116960,0.516783,0.507915,0.062891,0.022782,-0.242736,0.124149,-0.272727,0.153387,0.397490,0.270549,-0.038322,0.092111,0.436691,-0.400953,-0.246339,0.191204,-0.058684,-0.805630,-0.037782,0.265680,-0.113779,-0.699404,0.434180,-0.297247,0.081722,-0.108998,-0.376921,0.138764,0.081875,-0.166579,0.229347,-0.156502,-0.039379,-0.639837,0.730334,0.566897,-0.080878,0.326103,0.148480,0.052589,-0.263750,0.291792,-0.415526,-0.346414,0.005844,0.493229,-0.143772,-0.146141,0.146540,-0.283954,-0.395760,-0.306062,0.075021,-0.003226,-0.347881,0.118255,-0.087603,-0.286578,-0.239078,-0.188864,-0.021344,0.281944,-0.130120,0.562872,-0.620657,-0.129993,0.647265,0.394809,-0.919683,0.565825,0.175084,0.067772,0.037015,-0.170443,-0.435232,0.455164,0.490717,0.370000,0.206096,-0.063454,-0.347362,-0.203875,0.364231', '1302110', '3811342', '1877596', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297531', '电视台风云', '剧情', '妻子的死给电视台王牌主播霍华德（彼得·芬奇 Peter Finch 饰）带来了沉重的打击，使他陷入痛苦和悲伤中无法自拔。电视台决定解雇已经无心工作的霍华德，霍华德的老朋友麦克斯（威廉·霍尔登 William Holden 饰）成为了传达这一噩耗的不二人选。得知自己即将被 解雇，为电视台做牛做马多年的霍华德十分愤怒，在第二天的节目上，他竟然向观众们预告，自己即将进行自杀直播。霍华德的这一出格举动惹恼了电视台的高层，更让一直对麦克斯心存不满的总裁弗兰克（罗伯特·杜瓦尔 Robert Duvall 饰）发现了找茬的机会。在隔天的新闻直播中，霍华德理应按计划对自己的不慎言行做出道歉，可是恼羞成怒的他却大放厥词，将矛头直指当代美国的种种弊端。女制片人戴安娜（费·唐纳薇 Faye Dunaway 饰）从霍华德的一系列行为中看出了商机，她买通了弗兰克，成为了霍华德背后的推手。', '费·唐纳薇', '西德尼·吕美特', 8.4, 11185, 'tt0074958', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1199384619.jpg', 0.4, 1.4, 14.7, 45, 38.4, '0.177723,0.159386,-0.752582,0.603292,-0.126475,-0.244251,0.622539,0.121801,-0.533760,-0.108200,0.289018,0.847443,-0.601716,0.226185,0.464167,0.005244,-0.352129,-0.882997,-0.212718,-0.096848,-0.150425,-0.543284,-0.120828,-0.330443,0.029083,-0.130936,0.461423,-0.045601,-0.409990,0.285812,0.441597,0.355272,0.465667,0.616872,0.378281,0.279324,0.326099,-0.329023,-0.186117,0.191287,0.237416,-0.475089,-0.122879,0.673725,-0.109558,0.614044,0.414960,-0.280653,-0.209583,-0.147955,0.603937,-0.472040,0.216593,0.307528,0.285769,0.013138,0.057247,0.194239,-0.474390,0.006280,0.132529,0.038769,-0.973711,0.203150,-0.114678,0.167919,-0.560895,0.387736,-0.260436,0.352317,0.022010,-0.350219,0.164992,0.183126,0.289335,0.125048,-0.150842,0.050504,-0.187217,0.104278,0.470431,-0.020172,-0.186204,0.085033,-0.151795,-0.167758,0.102668,-0.190008,-0.435459,-0.190660,0.669269,-0.121222,0.053423,0.245403,-0.189802,-0.326214,-0.268048,-0.447477,-0.144952,-0.406330,-0.107745,-0.739897,-0.128069,-0.141851,-0.198160,-0.182200,0.096740,-0.201828,0.567692,-0.669826,0.156183,0.622995,0.097639,-0.422162,0.593843,0.073880,0.066015,-0.182809,-0.170347,0.053498,0.035772,0.164576,0.292472,0.186218,0.141887,-0.512311,-0.104017,0.440710', '1307442', '34890458', '25928048', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297538', '阴阳路5：一见发财', '恐怖', '香港出租车夜晚拉客常常遇鬼，比如夜车司机林中发（古天乐饰）就差点载一女鬼（罗兰饰）前往荃湾，而同事“快车长”（雷宇杨饰）却遇见某女扮鬼诈骗，随后又载真女鬼前往和合石火葬场。嗜赌成性的林中发收工后被追债上门，为躲赌债不得已携妻子（李蕙敏饰）和儿子安仔搬入阴阳路上某廉价大屋，却发现房中闹鬼，吓得安仔夜夜哭泣不停。林中发向屋中鬼魂（吴毅将饰）赌咒发誓，若帮他畅通财路，便愿将自己所有一切分半同享。第二日，林中发发现屋中出现一组神秘数字，从此他所向披靡，逢赌必胜；但林中发没想到的是，屋中鬼魂要分的不仅是他的财富，还有他的妻子和儿子……本片是《阴阳路》系列的第五部作品。©豆瓣', '古天乐', '邱礼涛', 6.5, 7862, 'tt0193578', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2251191603.jpg', 1.4, 10.1, 57.3, 23.3, 8, '0.071023,0.001259,-0.531009,0.151256,0.128957,-0.122445,0.499144,-0.039430,-0.334001,0.031476,0.130638,0.445470,-0.237683,0.219168,0.211743,0.047678,-0.169118,-0.338623,-0.029093,-0.001174,-0.212626,-0.020511,-0.035539,0.118494,-0.219290,0.003349,0.079249,0.156378,0.134915,0.489571,0.278504,0.133196,-0.436074,0.363605,-0.297470,0.307695,-0.098004,0.021221,0.101160,0.145003,-0.217974,-0.244799,-0.137322,-0.068478,0.019344,0.356555,0.484935,0.024726,-0.008450,-0.305183,0.246604,-0.055475,-0.221356,-0.065173,0.218659,0.107581,0.635222,0.043976,-0.116187,-0.229087,0.071299,0.112554,-0.124536,0.153289,0.067762,-0.046744,-0.401183,-0.207974,-0.174030,-0.032790,0.291890,-0.210423,0.271774,-0.285206,0.394977,0.172919,0.046258,-0.298859,-0.621594,0.121394,0.309607,-0.331126,0.226841,0.372356,0.116400,-0.132324,0.284116,0.183245,-0.245278,-0.207820,0.286613,-0.016565,-0.144859,-0.319136,-0.306990,0.121526,-0.243807,0.013818,-0.159688,-0.188073,-0.390016,-0.510679,0.165057,-0.238018,-0.024271,0.306033,0.087327,-0.063597,0.156464,-0.231985,0.242896,0.354014,0.330201,-0.392403,0.652312,-0.130740,0.115166,0.091813,0.188519,-0.052399,0.219396,0.409117,0.093541,-0.040989,-0.290347,0.033276,-0.222584,0.270620', '10466639', '1930829', '26882457', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297540', '艾玛', '剧情', '母亲的早逝、姐姐的出嫁令少女艾玛（格温妮斯•帕特洛 Gwyneth Paltrow 饰）很快就成了哈菲尔德大宅的女主人，在成功撮合了她的家庭教师泰勒小姐（格列塔•斯卡奇 Greta Scacchi 饰）与韦斯顿先生（詹姆斯•卡沙莫 James Cosmo 饰）的美好姻缘后，艾玛更加意气风发。这次艾玛又将目标对准了她的好友——出身平凡的哈丽叶特小姐（托妮•科莱特 Toni Collette 饰），她准备将哈丽叶特小姐介绍给当地的牧师——绅士埃尔顿先生（艾伦•卡明 Alan Cumming 饰）。为此，艾玛不仅处处为哈丽叶特小姐和埃尔顿先生制造相处的机会，甚至怂恿毫无主见的哈丽叶特小姐拒绝了和她身份般配而且善良富足的农夫马丁先生的求爱。这一切，艾玛的好友——聪明的奈特利先生（杰瑞米•诺森 Jeremy Northam 饰）都看在眼里，虽然他极力反对艾玛的做法，并且认为艾玛这样做会害了哈丽叶特小姐，但信心满满的艾玛又怎会将他的意见放在眼里。艾玛一方面继续着她的“红娘事业”，另一方面期待着从小寄养在舅母家的韦斯顿先生的绅士儿子——弗兰克的拜访。艾玛的“事业”最后能否成功，她又能否找到自己的意中人？', '格温妮斯·帕特洛', '道格拉斯·麦克格兰斯', 7.5, 10741, 'tt0116191', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2527171213.jpg', 0.5, 2.5, 34, 46.8, 16.3, '0.223368,0.041165,-0.344837,0.635554,-0.257227,-0.707416,0.342845,0.255587,-0.299046,-0.249214,0.186090,0.642596,-0.094230,0.278520,0.401567,0.396864,-0.392833,-0.363755,0.006951,0.016197,0.037583,-0.605116,-0.166176,-0.248229,0.075843,-0.445939,0.243645,-0.211527,0.134117,0.332746,0.211252,0.179216,0.175469,0.436700,-0.035582,0.384632,0.295015,-0.017850,-0.476716,0.221940,0.220392,0.177506,0.118553,0.379636,0.279457,0.328383,0.450209,-0.460330,0.056764,0.142525,0.501066,-0.167097,0.552400,0.420436,0.211021,-0.100789,0.144405,0.156465,-0.203212,-0.241182,0.233540,-0.161326,-0.534421,0.155363,0.294708,-0.104743,-0.697739,0.467808,-0.218379,-0.100527,0.007845,-0.235173,0.045186,0.275063,0.112915,0.017283,-0.125962,0.282399,-0.313163,0.040997,0.372326,0.075400,0.037522,0.293117,-0.278105,-0.409296,0.269282,-0.155165,-0.844404,-0.032399,0.269831,-0.154454,0.101230,0.382068,-0.392088,-0.301834,-0.588125,0.297096,0.104359,-0.679523,0.086479,-0.230762,-0.039403,-0.362739,-0.143083,-0.254149,0.222739,-0.236758,0.702037,-0.802116,-0.063000,0.434605,0.263571,-0.277019,0.575960,0.231976,0.068679,-0.237735,-0.384571,-0.010706,0.132946,-0.009091,0.222625,0.462143,0.298809,-0.175052,-0.102117,0.382442', '1292720', '26348103', '1309178', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297544', '国家公敌', '剧情', '迪恩（威尔 史密斯 Will Smith 饰）是一个家庭生活和美、前途一片光明的黑人执业律师。圣诞节前夕，迪恩遇到了一位久未谋面的朋友。从此，迪恩的生活发生了天翻地覆的变化。原来这位友人将一张记录了某个位高权重的人谋杀国会议员整个过程的光盘放进了迪恩的袋子！可怜的迪恩在毫不知情的情况下，被NSA中的害群之马严密监视，并被施加了各种各样的压力，甚至无端遭到了谋杀前女友雷切尔的起诉。迪恩迫于无奈之下，只得只身展开了逃亡、追查幕后真凶之路。©豆瓣', '威尔·史密斯', '托尼·斯科特', 8.2, 109285, 'tt0120660', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1209268712.jpg', 0.1, 0.6, 15.7, 55.7, 27.9, '0.364728,-0.013915,-0.536360,0.568576,-0.196836,-0.023324,0.879495,0.329567,-0.531200,-0.362224,0.371174,0.821582,-0.274523,0.186781,0.374454,-0.107907,-0.234904,-0.807855,-0.172095,-0.052369,-0.420597,-0.518579,-0.439919,-0.171093,-0.089862,-0.280181,0.457425,0.277407,-0.137421,0.218579,0.068379,0.421141,-0.144945,0.473875,-0.016934,0.053723,0.436514,-0.199567,-0.304789,0.175154,-0.141681,-0.518498,0.021755,0.383878,-0.067659,0.512066,0.776304,-0.294800,-0.317510,-0.115984,0.585111,-0.288944,-0.164210,0.306828,0.399358,0.127119,-0.130008,0.368787,-0.167906,-0.147604,0.298141,0.054988,-0.772054,0.012152,0.047086,0.214218,-0.513402,0.392460,-0.178423,-0.005760,-0.098044,-0.256822,0.292837,0.323967,0.212529,0.072808,0.032232,0.280645,-0.398077,0.096351,0.503978,0.017897,-0.365878,0.147558,-0.251664,-0.316797,-0.110190,-0.002873,-0.502285,-0.099119,0.686551,-0.076401,-0.306722,0.338354,-0.606308,-0.105490,-0.435345,-0.312449,-0.145770,-0.339547,-0.376023,-0.582180,-0.128163,-0.246448,-0.385816,-0.012310,-0.019642,-0.214254,0.515934,-0.397430,0.231191,0.581080,-0.006736,-0.537398,0.416769,0.167272,0.254260,0.194708,-0.151366,0.196208,0.301113,0.519514,0.279948,0.230087,-0.143646,-0.100481,-0.221359,0.213700', '2988294', '3119246', '25828589', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297547', '神鬼奇谋', '喜剧', '吉姆（蒂姆·艾伦 Tim Allen 饰）是一名个性冷酷武艺高强的杀手，他只有一个弱点，那就是喜欢听故事。这一回，他的目标是一个名叫芬奇（克里斯汀·史莱特 Christian Slater 饰）的摄影师，没想到，这项本以为能够轻松完成的任务却被芬奇的一个故事给搅黄了。故事中，一名江洋大盗和女儿将价值连城的宝物埋藏在了底下，然后被捕。在小贼“范”的帮助下，大盗越狱成功，范和大盗的女儿之间亦产生了真挚的感情。企图洗刷过去污点重新享受社会生活的大盗和范决定盗用死人的身份。没想到，范所盗用的身份是一个遭受黑帮追杀的摄影师，故事至此真相大白，原来芬奇就是故事中的范，吉姆的内心里开始了天人交战，究竟是完成任务还是帮助范完成这个传奇一般的故事？吉姆最终做出了自己的选择。©豆瓣', '克里斯蒂安·史莱特', 'Chris Ver Wiel', 8.1, 7410, 'tt0246500', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515682832.jpg', 0.4, 2.2, 19.2, 49.8, 28.3, '0.253789,0.222833,-0.460332,0.839565,-0.377160,-0.165382,0.666323,-0.318024,-0.517859,-0.405140,0.140391,0.695676,-0.118510,0.310534,0.395760,-0.044271,-0.328501,-0.734328,-0.066012,-0.294496,-0.318893,-0.615421,-0.481628,-0.306499,-0.072991,-0.062314,0.529454,0.370460,-0.390438,0.127579,0.735698,0.509370,0.043378,0.196666,-0.071514,0.005919,0.284774,-0.153736,-0.128623,0.256359,0.079523,-0.217248,0.171522,0.288944,-0.177142,0.354216,0.519779,-0.321208,-0.242759,-0.146099,0.399270,-0.349449,0.133766,0.015944,0.181775,0.061252,0.110986,0.154183,-0.097448,-0.001598,0.184753,-0.289885,-1.158168,-0.190949,0.287835,0.094348,-0.528488,0.077514,-0.138140,0.075846,-0.078076,-0.157012,0.019253,0.093699,0.869356,0.389066,-0.062107,0.180800,-0.532119,0.167589,0.540171,-0.013983,-0.284308,0.353396,0.027544,-0.474985,-0.124907,-0.236482,-0.132456,0.049100,0.341727,-0.027362,0.004847,0.162173,-0.426497,-0.118091,-0.322421,0.180171,-0.055350,-0.373711,-0.159076,-0.351473,-0.183735,-0.234023,-0.302132,0.063726,0.004245,-0.557442,0.730747,-0.593349,0.113474,0.411769,0.020679,-0.429860,0.522658,0.339655,0.071544,-0.359830,0.149602,0.204323,0.211329,-0.030212,0.156061,0.213770,0.048181,-0.387579,-0.364147,0.643317', '6844861', '27098364', '26678784', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297570', '变相怪杰', '喜剧', '银行小职员斯坦利（金•凯瑞 Jim Carrey 饰）老实本分，过着和所有老实人一样的平凡生活。一次，斯坦利在接待金发美女蒂娜（卡梅隆•迪亚茨 Cameron Diaz 饰）时深深恋上了对方，不料蒂娜却是黑帮头目多利安（彼得•格林纳 Peter Greene 饰）抢劫银行前派来打探地形的。多利安随后成功抢劫了斯坦利所在的银行。一晚，斯坦利意外获得了一个奇怪的面具。戴上面具后的斯坦利变得力大无比、身手敏捷。斯坦利开始四出捉弄平日欺负他的人，并抢走了多利安劫得的巨款，与蒂娜在夜总会尽情飞舞。多利安知道了面具的威力后，用计夺走了面具，斯坦利则被关进了监狱。斯坦利最后能否凭自己的智慧夺回面具，与蒂娜有情人终成眷属?©豆瓣', '金·凯瑞', '查克·拉塞尔', 8, 253438, 'tt0110475', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2043441362.jpg', 0.2, 1.4, 22.1, 50.5, 25.7, '0.129966,0.251737,-0.496572,0.397037,-0.347379,-0.456807,0.738567,0.429962,-0.231330,-0.152876,0.047544,0.692504,-0.364259,0.193146,0.236780,0.442678,-0.573908,-0.501610,-0.225131,-0.437146,-0.173786,-0.417398,-0.236876,-0.173816,0.164515,-0.332999,-0.007530,-0.001467,-0.073328,0.366018,0.787516,0.308348,-0.136366,0.336843,-0.069121,-0.164457,0.161731,-0.425524,-0.007058,0.063691,-0.191336,-0.095024,-0.077506,0.049536,0.282554,0.285244,0.608297,-0.154502,0.014950,-0.214038,0.256629,0.068085,0.227247,0.021308,0.096751,-0.240138,-0.239072,-0.015894,-0.126351,0.177359,0.508887,-0.297473,-0.870877,0.108300,-0.054058,0.109928,-0.657228,0.153304,-0.123864,0.327378,-0.151556,-0.197189,-0.025689,0.151730,0.107717,-0.027250,0.322148,0.223311,-0.586421,0.179817,0.208066,-0.000717,-0.128474,0.183510,-0.174911,-0.431372,-0.106147,0.061206,-0.321728,-0.143991,0.680729,-0.204477,-0.147281,-0.098722,-0.556889,-0.340434,-0.472620,0.074561,-0.155045,-0.266811,-0.179896,-0.647228,-0.111535,-0.547970,-0.412163,-0.009620,-0.085149,0.076216,0.476405,-0.651627,0.068733,0.606230,0.118929,-0.171413,0.371601,0.057119,-0.021163,0.165206,-0.125078,0.284345,0.669249,0.423810,0.427881,0.382199,-0.056990,-0.062956,0.002663,0.341989', '1301345', '1307442', '1300324', '6753166');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297574', '英雄本色', '剧情', '香港某个国际伪钞集团重要分子宋子豪（狄龙 饰）和Mark（周润发 饰）情同手足，某次宋子豪带手下谭成（李子雄 饰）去台北交易时被其出卖受枪伤被捕入狱，为替好兄弟报仇，Mark孤身赴台，结果被人打成瘸子，江湖地位自此一落千丈，而宋子豪的父亲也在不久丧命。 一向视宋子豪为偶像的宋子杰（张国荣 饰）得知哥哥的真实身份后，对黑社会及他恨之入骨，立誓利用警察身份将黑帮势力斩草除根，宋子豪出狱后不顾苦等他想重创辉煌的Mark的劝阻，决心弃暗投明，无奈得不到宋子杰的谅解。而此时已成帮会老大的谭成欲找宋子豪再合作，遭拒绝后放言会害宋子杰，被逼走投无路，宋子豪决定再与Mark连手共抗强敌。©豆瓣', '周润发', '吴宇森', 8.6, 497099, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2504997087.jpg', 0.1, 0.5, 11.2, 43.5, 44.7, '-0.079746,0.033336,-0.592458,0.237931,0.044809,-0.176466,0.079934,0.542183,-0.574706,-0.097345,0.262566,0.838457,0.181475,0.154876,0.234820,-0.328372,-0.109312,-0.777155,0.018957,-0.153399,0.080023,-0.455831,0.064719,-0.028589,-0.381238,-0.073035,0.551505,0.051314,-0.192313,0.652833,0.488769,0.458339,-0.059733,0.423798,0.166772,0.082201,0.018735,-0.057872,-0.759541,0.239055,-0.015399,-0.155151,0.091111,0.201296,-0.071547,0.259545,0.331184,0.075600,-0.141303,-0.404841,0.308283,-0.612487,-0.071780,0.308582,0.410199,-0.023772,0.176214,0.419682,-0.246497,-0.209101,0.232184,0.195569,-0.696943,-0.028624,0.319871,-0.302180,-0.767840,0.474183,-0.397666,-0.007376,-0.103122,-0.088839,0.306118,0.539069,0.335453,-0.013737,-0.070705,0.176694,-0.388454,0.127373,0.759724,-0.012134,0.331083,-0.335565,0.441854,-0.013261,0.162405,-0.667632,-0.139473,0.035397,0.376863,-0.102151,-0.277002,0.057155,0.003546,-0.381597,-0.387148,0.257494,0.118404,-0.357694,-0.026925,-0.403441,-0.330556,-0.033733,0.012253,0.115326,0.054014,-0.182020,0.404987,-0.555412,0.117010,0.173809,0.606579,-1.028921,0.307472,0.200087,-0.015699,-0.149948,-0.147212,0.076181,0.485130,0.104202,0.272126,-0.182760,0.009598,-0.203228,0.094121,-0.353477', '1302110', '1484760', '26678784', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297585', '两个人的车站', '剧情', '钢琴家普拉东（Oleg Basilashvili 奥列格•巴西拉什维利 饰）的妻子开车撞死了人，为了妻子，普拉东甘愿顶罪。在审判前的一个星期，普拉东赶回家见父亲的一面。途中，他经过了一个普通的、喧哗的车站。车站餐厅里，普拉东和美丽女服务薇拉（Lyudmila Gurchenko  留德米拉•古尔琴科 饰）相遇了。两人一开始因为普拉东抱怨餐厅的服务而互相结怨，尔后，普拉东和薇拉越聊越投契，普拉东还到了薇拉家作客。两人的爱情之火就在点点滴滴中点燃了，最终步入爱河。普拉东入狱了。在难得的家属探视日，薇拉千里迢迢来看普拉东了。两人在监狱外的木屋内度过了难忘的一晚。©豆瓣', '柳德米拉·古尔琴柯', '埃利达尔·梁赞诺夫', 8.6, 8767, 'tt0084873', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p856874299.jpg', 0.3, 0.6, 11.2, 44.8, 43.1, '0.572329,-0.126162,-0.676991,0.378226,-0.100361,-0.374432,0.923037,0.465825,-0.167040,0.216870,0.293532,0.905063,-0.401879,0.531941,0.611003,0.064186,-0.532918,-0.888505,-0.006153,-0.435381,-0.453700,-0.477041,0.130878,0.029977,-0.081664,-0.233295,0.163026,-0.196599,0.308825,0.737916,0.111142,0.097786,-0.332685,0.454992,-0.345691,0.060447,0.264781,0.173090,-0.065221,0.145851,0.062854,-0.201927,-0.224196,-0.010531,0.102629,0.363123,0.708187,-0.387436,0.283649,-0.101604,0.191899,-0.225896,0.156847,-0.099132,0.417340,-0.214861,0.159298,0.278380,-0.544156,-0.075600,0.047718,-0.168810,-0.478674,0.323611,-0.179442,-0.318132,-0.728506,0.533895,0.186171,0.191685,0.217929,-0.263398,0.182540,0.255320,-0.218308,0.589706,-0.085925,-0.149022,-0.224148,0.188413,0.556452,-0.229412,-0.087890,0.611468,-0.081750,-0.241244,-0.014196,-0.012741,-0.727312,-0.473257,0.565370,-0.000177,-0.008033,-0.246562,-0.681531,-0.149691,-0.460259,-0.044890,0.090829,-0.082542,-0.145903,-0.531722,-0.178238,-0.165274,-0.186409,0.119833,-0.158588,-0.084322,0.302533,-0.480019,0.180341,0.491623,0.306835,-0.545974,0.937317,0.022808,0.295715,0.096834,0.058367,0.327655,-0.009586,0.539359,0.321479,0.512382,-0.338298,0.069883,-0.579480,0.327436', '1361252', '26687241', '1303531', '1422912');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297589', '恶汉甜梦', '剧情', '这部惊险报仇片剧情复杂，线索纵横交错，黑泽明通过一宗贿赂事件，无情地揭露了日本官商界的黑暗，对人性的丑恶一面刻划得入木三分。在构图方面，黑泽明控制得更完美无瑕，通道、楼梯、房间的排列、镜的摆设，以至瓦砾堆的空间布置，都拍得均整有致，计算得惊人地准确。', '三船敏郎', '黑泽明', 8.4, 7620, 'tt0054460', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2205014870.jpg', 0.4, 0.8, 12.3, 50.8, 35.7, '0.232682,0.101688,-0.400279,0.694485,0.229743,0.174757,0.519890,0.102890,0.103846,0.280990,0.665723,-0.050400,-0.574901,-0.403158,-0.049105,-0.230881,-0.479368,-0.357632,-0.387330,-0.215526,-0.491727,-0.405726,-0.674705,-0.615323,-0.200949,-0.400682,0.727222,0.479535,-0.366675,-0.274822,-0.238685,-0.130327,-0.206282,-0.303947,-0.253259,-0.064741,-0.348593,0.152593,-0.278446,-0.433411,-0.279556,-0.331865,-0.227851,0.362967,-0.263140,0.337234,0.768721,-0.021924,-0.255432,0.613109,0.677996,-0.106967,-0.081685,0.142623,0.466303,0.105468,0.137913,0.185170,-0.225721,-0.117393,0.151936,0.091011,-1.101309,-0.368160,0.550563,0.143938,0.069363,0.342307,-0.059381,0.192356,-0.178668,-0.387933,-0.104133,-0.310195,0.327664,0.629723,-0.091474,0.051023,-0.250906,0.442814,-0.251363,-0.230990,-0.419913,0.324629,-0.187221,-0.430993,-0.555769,-0.304218,0.041981,-0.013212,0.724211,-0.370283,0.026800,0.317943,-0.608681,-0.204371,-0.137469,-0.267785,-0.281132,-0.301569,-0.258380,-0.707812,-0.305831,-0.083884,-0.105505,0.075654,0.029681,0.014548,0.550456,0.256172,0.019827,0.321250,-0.335082,-0.322920,0.719132,0.000584,0.024907,0.050076,-0.169229,0.064974,0.270500,0.316156,0.007910,0.802067,0.053325,-0.408882,-0.795614,0.419239', '3318306', '6844861', '6874140', '26577354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297598', '露西亚的情人', '剧情', '风流倜傥的小说家洛伦佐（Tristán Ulloa 饰）在遭遇创作瓶颈之际邂逅了自己的崇拜者露西亚（Paz Vega 帕兹•维嘉 饰）——一名在咖啡馆工作的女招待。她点燃了洛伦佐沉寂已久的激情，两人开始一段愉快刺激的同居生活。偶然机会，洛伦佐得知自己拥有一个女儿，那是他一年前在海边夜晚的所留下的艳遇结晶。自此他的心情重归浮躁，他私下寻找女儿，却将小说中的情节和现实混为一谈。露西亚和洛伦佐的爱情开始出现龃龉，某晚在接到警察一通电话之后，她逃离这座压抑沉闷的城市，来到爱人曾经徜徉的海边……©豆瓣', '帕斯·贝加', '胡里奥·密谭', 7.6, 29375, 'tt0254455', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2163031990.jpg', 0.8, 3.7, 31.1, 45.5, 18.9, '0.414773,0.294796,-0.809878,0.637467,-0.081642,-0.252256,1.071864,0.102353,-0.527468,-0.254504,0.235095,0.896783,-0.455133,0.452157,0.494803,0.004253,-0.273580,-0.766761,0.238096,-0.087231,0.045988,-0.288857,-0.357289,-0.226691,0.009764,-0.406762,0.670457,0.296920,-0.176427,0.506900,0.028960,0.151412,-0.227136,0.535295,-0.279337,0.207355,0.167994,0.194065,-0.322289,0.072053,-0.004334,-0.287273,-0.032712,0.056967,-0.035280,0.181391,0.759160,-0.073753,-0.267565,0.196873,0.447172,-0.000035,-0.140713,-0.019319,0.230129,-0.034522,0.171842,0.081024,-0.281499,-0.059098,-0.093737,-0.153814,-0.436837,0.001327,-0.092768,0.237537,-0.396723,0.588519,0.115515,0.069901,0.231654,-0.218073,0.128811,0.418305,0.213204,0.420893,-0.179906,-0.053067,-0.322881,0.470404,0.873410,-0.224280,-0.137204,0.621370,-0.302303,-0.299188,-0.133491,0.101802,-0.649314,-0.201272,0.404158,-0.027940,-0.312717,0.232198,-0.737044,-0.010288,-0.100725,-0.073265,0.126941,-0.332404,-0.281370,-0.643801,-0.232159,-0.165834,-0.302944,0.071671,-0.034113,-0.356799,0.635869,-0.822821,0.415257,0.720827,0.077632,-0.303990,0.658668,0.065154,0.139634,-0.174499,0.115989,0.620298,-0.204678,0.354178,0.052928,0.254098,-0.280274,0.219068,-0.649696,0.666633', '1296534', '1309172', '1291835', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297606', '一个男人和一个女人', '剧情', '她，Anne Gauthier（阿努克·艾梅 Anouk Aimée 饰）是一个寡妇，独自抚养着她的女儿。她是一名电影场记，丈夫是一个特技演员，在拍摄一场戏的时候不幸丧生。她每周都要从Paris去Deauville接送她在Deauville一所学校寄读的女儿。他，Jean-Louis（让-路易斯·特林提格南特 Jean-Louis Trintignant 饰）是一个鳏夫，独自抚养着他的儿子。他是一名赛车手，一场车祸后他的妻子以为他已经丧生而自杀身亡。他每周也要到Deauville去接送他的儿子。有一天，Anne送女儿上学后错过了回巴黎的最后一班火车，因此邂逅了Jean-Louis，Jean-Louis开车送Anne回家，两人约定下周一起去接孩子。下个周日，两人和两个孩子在一起度过了愉快的时光。两个寂寞的男女被彼此所吸引，爱情正在生根发芽。然而，Jean-Louis觉得这段爱情中有些奇怪，而对前夫的思念又让Anne纠结不已......本片获1967年戛纳电影节金棕榈奖和1968年奥斯卡最佳外语片奖。', '阿努克·艾梅', '克洛德·勒卢什', 8.4, 9938, 'tt0061138', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1944186307.jpg', 0.3, 1.1, 14.4, 47.1, 37.2, '-0.103053,-0.216367,-0.781482,0.565894,-0.162677,-0.525768,0.871688,0.140188,-0.285804,-0.073113,0.180034,1.003828,-0.130581,0.664372,0.391474,0.093913,-0.296158,-0.657502,0.021008,-0.194829,-0.329559,-0.285117,0.093254,-0.049443,0.102327,-0.170730,0.495398,-0.092978,0.241086,0.591482,0.431838,-0.164429,-0.053481,0.539497,-0.365590,0.201123,0.020766,0.168275,-0.101136,0.481791,0.364490,-0.255015,-0.432674,-0.073508,0.119158,0.211711,0.865246,0.132966,0.035814,0.001947,0.397615,-0.420145,-0.273347,0.105586,0.300272,-0.176208,0.171674,0.014855,-0.323870,0.078247,0.163648,-0.046772,-0.523960,0.063707,-0.086890,-0.089595,-1.104903,0.734040,-0.002671,-0.024166,0.149455,-0.532106,0.367695,0.410080,0.048614,0.540009,-0.200684,-0.196817,-0.429804,0.616412,1.019567,-0.121287,-0.029486,0.447168,-0.179735,-0.353374,0.076174,-0.107218,-0.956524,0.161648,0.435541,-0.226907,-0.244054,0.012478,-0.342260,-0.014049,-0.236518,-0.252390,-0.073892,-0.576276,0.166193,-0.389165,0.176973,-0.379348,-0.436083,-0.027890,0.183933,-0.337360,0.729443,-0.569392,0.469638,0.967521,0.213112,-0.490455,1.001114,0.353100,0.364797,-0.214919,0.197380,-0.073131,-0.226733,0.14