INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297607', '南京1937', '剧情', '1937年深秋，为躲避战乱，中国医生成贤（秦汉 饰）携带怀有身孕的日本妻子理惠子（早乙女爱 饰）和孩子从上海逃到南京老家，他没想到南京也差不多快被侵华日军夷为废墟。被告知可以进入欧美列强势力保护的安全区避难时，成贤认为自己与难民身份不同没做理会，投靠了老朋友继续行医。以小学教师刘天琴（刘若英 饰）为代表的同胞的悲剧令他震惊愤怒，但他认为自己首要任务不是反抗暴敌而是尽职做好一名医生。同年冬天12月13日，南京全面沦陷，日军开始在南京疯狂烧杀淫掠，成贤终于意识到日军的残酷麻木，让妻子先行一步去安全区躲避，自己则留下来继续救死扶伤，他不知道的是，安全区早已名存实亡，而要反抗时，他发现已无可能。©豆瓣', '秦汉', '吴子牛', 7.5, 4005, 'tt0113930', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2576993146.jpg', 0.9, 3.2, 33.6, 43.2, 19.1, '0.198460,0.037225,-0.735024,-0.012624,0.082078,-0.106097,0.406579,-0.016233,-0.567260,-0.213958,0.032949,0.388086,0.265215,-0.024906,-0.057350,-0.000745,-0.180264,-0.562955,-0.072510,-0.190474,-0.278933,-0.414158,0.052763,-0.332171,-0.240595,-0.209521,0.569435,0.343518,-0.105828,0.467079,-0.066778,0.178453,0.054801,0.699160,0.011465,-0.077655,-0.061832,-0.232736,-0.427927,0.284302,0.018885,-0.304028,-0.338567,0.304727,-0.015748,0.528253,0.540092,0.011301,-0.040297,-0.183230,0.314064,-0.372197,-0.189601,0.396195,0.499337,-0.065934,-0.037877,0.146395,-0.035862,-0.083371,-0.009271,-0.068937,-0.544243,0.192631,0.110698,0.051822,-0.515202,0.505911,-0.275822,-0.038947,0.087849,-0.591053,0.404873,0.503919,0.077957,0.259055,-0.240588,0.097853,-0.520968,0.361575,0.842473,-0.218002,-0.138658,0.119734,0.110862,-0.153260,0.147892,-0.508157,-0.259382,-0.117396,-0.332120,0.084264,-0.358037,0.057866,-0.122730,-0.155305,-0.454288,-0.294808,-0.055052,-0.213886,-0.130310,-0.126815,-0.074691,-0.201549,-0.108281,0.124675,0.185081,-0.008403,0.535157,-0.758187,0.206789,0.602158,0.609840,-0.814086,0.650075,0.043986,-0.069908,-0.117578,0.062408,0.312152,0.157710,0.283512,0.275571,0.026078,-0.107271,-0.155856,-0.068240,-0.008151', '25908042', '1494897', '35073886', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297611', '进化危机', '喜剧', '一颗陨石坠落到亚利桑那州的荒漠中，在它撞击形成的溶洞内，一个与世隔绝的奇异世界正飞速形成。从单细胞到多细胞，从类鸟类到灵长类，外星生物已难以想象的速度高速进化，并开始影响人类的生存。在大学任教的伊尔（David Duchovny 大卫•杜楚尼 饰）和同事兼好友哈里（Orlando Jones 奥兰多•琼斯 饰）最早发现了陨石所带来的外星生物痕迹，并意识到其高速进化背后的危险性。在隶属军方疾病控制中心的女官员艾丽森（Julianne Moore 朱丽安•摩尔 饰）的帮助下，他们偷偷搜集数据，寻找遏制外星生物入侵的办法……©豆瓣', '大卫·杜楚尼', '伊万·雷特曼', 6.8, 17734, 'tt0251075', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453531507.jpg', 1.5, 8.5, 46.2, 34.2, 9.6, '0.235611,0.140327,-0.962881,0.628371,-0.074608,0.230869,0.887034,0.033421,-0.271004,-0.021147,0.301927,0.471800,-0.221201,0.036990,0.217214,-0.093834,-0.218372,-0.173373,0.171242,-0.217387,-0.684096,-0.415420,-0.759232,-0.382213,0.108282,-0.685556,0.797846,0.125239,-0.302043,0.234732,-0.277975,0.360093,-0.537726,0.558097,-0.250069,-0.065852,0.055209,0.063594,-0.211108,0.071944,-0.220597,-0.105453,0.227275,-0.087779,-0.154410,0.038994,0.956363,-0.567835,0.177508,-0.346743,0.387871,-0.080799,0.117889,-0.144612,0.673463,0.056129,-0.208870,-0.143061,0.184027,0.446739,0.273735,-0.034576,-0.618779,-0.275614,-0.167128,0.614970,-0.273152,0.116181,0.110472,-0.269710,-0.109736,-0.493867,-0.005192,0.030976,-0.115316,0.407376,-0.413191,0.122531,-0.300697,-0.063629,0.462141,-0.227530,-0.755896,0.261433,-0.350190,-0.797048,-0.378534,0.091103,-0.102414,-0.384322,0.333852,0.507329,-0.420112,0.518772,-1.031513,0.276729,-0.121105,-0.475091,-0.135177,-0.050559,-0.113749,-0.926782,-0.046907,-0.151170,-0.065326,0.258017,0.074765,-0.280153,0.547474,-0.448037,0.228021,0.863722,0.273990,-0.227179,0.352886,-0.498848,-0.035012,-0.321113,-0.293028,0.429046,0.289824,0.665491,-0.299599,0.410240,0.059449,0.022354,-0.360749,0.531841', '3006772', '26309788', '30336307', '1578502');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297628', '午夜牛郎', '剧情', '生活清贫的牛仔乔恩（乔恩·沃伊特 Jon Voight 饰）从老家来到纽约讨生活，他自认为风流倜傥，因此想在纽约当个男妓混口饭吃。当他第一天来到纽约时，就在大街上勾搭女人。不料，人地生疏的他生意不成反而亏了20块钱。沮丧不已的乔恩遇到了专靠骗点小钱为生的里佐（达斯汀·霍夫曼 Dustin Hoffman 饰），里佐骗乔恩说他认识一个男妓集团的首脑，但要收20元作为中介费。最后里佐只是把乔恩介绍给了一个同性恋的皮条客，愤怒不已的乔恩随后找到了里佐。里佐收留了无家可归的乔恩，两人渐渐成了无所不谈的好朋友。 寒冷的纽约冬天，两人过的十分辛酸，以至于衣食无着，里佐也没有钱买药治病里佐向往着迈阿密的生活，他邀请乔恩和他一起到迈阿密去闯世界。生活无着的两人这晚来到一家地下酒吧去碰运气，当乔恩终于搞到一单生意后，体力不支的里佐摔下了楼梯。奄奄一息的里佐此时最记挂的仍是迈阿密家乡的阳光，乔为了完成朋友的愿望，开始铤而走险。', '强·沃特', '约翰·施莱辛格', 8.3, 20974, 'tt0064665', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2261560304.jpg', 0.2, 1, 14.5, 50.6, 33.7, '0.315019,-0.005183,-0.654614,0.372894,-0.207410,-0.622466,0.474368,0.221266,-0.354080,-0.235417,-0.017961,0.871090,0.047360,0.668383,0.477319,0.243213,-0.279080,-0.556526,-0.046639,-0.413151,-0.063529,-0.418206,-0.270152,-0.184793,-0.452585,0.025641,0.201342,0.211530,0.115670,0.501554,0.201101,0.269583,0.142096,0.504583,-0.271670,0.091091,0.007151,0.029578,-0.118882,0.178969,0.122937,-0.304445,-0.155873,-0.115915,0.579023,0.495944,0.585969,0.063179,0.084911,0.075577,0.222740,-0.134876,-0.168780,0.024026,0.075265,-0.108058,0.214892,-0.051235,-0.484069,-0.040493,0.182606,-0.126610,-0.538768,0.065104,0.005834,-0.036492,-0.722556,0.468406,0.089106,0.042131,0.107293,-0.426502,0.504293,0.201411,0.002402,0.372053,-0.114857,0.106179,-0.408548,0.289831,0.962547,-0.001334,0.030705,0.196568,-0.209997,-0.237128,0.318052,-0.043508,-0.397644,-0.249174,0.289067,-0.157938,-0.225119,0.004779,-0.614578,-0.035115,-0.117891,-0.091575,-0.039763,-0.130578,-0.059703,-0.509538,-0.078189,-0.318898,-0.123644,0.312045,-0.080961,-0.215103,0.282137,-0.639518,0.008029,0.561113,0.184499,-0.159317,0.744073,-0.131943,0.308685,0.144003,-0.020818,0.090524,0.057458,0.514246,0.172182,0.373281,-0.181721,0.009060,-0.296856,0.405360', '26687241', '1926007', '2080130', '3718782');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297630', '第六感', '剧情', '麦克（布鲁斯·威利斯 饰）是著名儿童心理学家，却也有始终未能治愈的患者，甚至因此遭到枪击，这名少年随后也饮枪自毙。这给麦克带来很大心理阴影，一年后他找到另一个症状很像这名患者的男孩柯尔（海利·乔·奥斯蒙 饰），并耐心的做起了他的医生。柯尔并不容易接近，但麦克还是慢慢赢得 了他的信任，得知了柯尔的秘密。原来柯尔有着灵异的第六感，可以看到鬼魂。虽然这令人感到难以置信，但麦克在证实了事情的真相后还是帮助柯尔接受了这个事实。可是就在问题即将得到解决的时候，麦克却在柯尔的引导下，发现了一个更令人震惊的秘密……©豆瓣', '布鲁斯·威利斯', 'M·奈特·沙马兰', 8.9, 518961, 'tt0167404', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220184425.jpg', 0.1, 0.4, 7.6, 37.6, 54.2, '0.197532,0.198681,-0.671476,0.490109,-0.269531,-0.033911,0.905101,-0.020242,-0.574292,-0.505268,0.110923,0.669490,-0.039171,0.227909,0.279810,0.131519,-0.467571,-0.458152,0.248794,-0.190956,-0.499959,-0.612830,-0.440280,-0.394654,-0.165197,-0.394778,0.341147,0.294040,-0.299100,0.357788,0.201699,0.389901,0.378752,0.829568,-0.009098,0.116972,0.352172,-0.118451,0.119826,0.212631,0.543644,-0.317501,-0.065830,0.515684,-0.150485,0.690685,0.212285,-0.450567,-0.557677,0.295849,0.245009,-0.360586,0.000796,-0.075725,0.152809,-0.196245,-0.016098,0.039403,-0.225499,0.087932,0.024615,0.263351,-0.942111,0.125329,0.143230,0.437795,-0.509012,0.318403,-0.162493,-0.014633,-0.130649,-0.209379,-0.035361,0.265935,0.319351,0.192229,-0.340560,-0.051549,-0.683852,-0.172187,0.443378,0.195963,-0.560113,0.462100,-0.519877,-0.809574,-0.085843,-0.035922,-0.180371,0.220385,0.405087,0.371828,-0.364802,0.210821,-0.255514,-0.019175,-0.425697,-0.126604,-0.295774,-0.373535,-0.033280,-0.483019,-0.168072,-0.364089,-0.641664,-0.078707,0.005618,-0.481712,0.873545,-0.793510,0.187856,0.600808,0.059545,-0.382373,0.472952,0.150618,0.039829,-0.223994,-0.243994,0.440006,0.048731,0.375585,0.147180,0.434077,0.181453,-0.675147,-0.382030,0.618300', '26341137', '25932086', '1793491', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297634', '失去的周末', '剧情', '唐（雷·米兰德 Ray Milland 饰）都不知道自己能否称自己为一个失意的作家，因为一个作品从来没有被公众所接受过的作家怎么能是作家呢？为了排遣心中的愤懑，唐选择了向酒精寻求安慰，殊不知，酒精只会让他的情况变得更糟。海伦（简·怀曼 Jane Wyman 饰）的出现将唐从酗酒的泥潭中拉了出来，她的温柔和善解人意温暖了唐孤寂的生活，也令他找到了心灵的归属，他决定重新振作起来。好景不长，海伦的父亲对唐和女儿的关系十分不满，在他的眼中，唐只是一个一事无成的浪荡儿而已。感情遭到否定的汤再次陷入了酗酒的危机中，甚至动起了自杀的念头。面对心灰意冷的爱人，海伦能否再一次将唐从死亡边缘中解救回来呢？©豆瓣', '雷·米兰德', '比利·怀尔德', 7.8, 7266, 'tt0037884', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1637462016.jpg', 0.4, 1.7, 25.1, 53.5, 19.3, '0.084153,0.318220,-0.823510,0.983365,-0.270395,-0.684883,0.819535,-0.006385,-0.808715,-0.317285,-0.511625,0.667297,-0.319442,0.651180,0.170122,-0.161195,0.138370,-0.762697,-0.340142,0.100076,-0.627681,-0.378881,-0.237491,-0.675513,-0.187241,-0.099461,0.494175,0.496443,-0.501933,0.030509,0.540266,0.530007,0.231258,0.916703,0.013222,0.027321,-0.377674,0.205449,-0.358985,0.476935,0.513952,-0.441225,0.040201,0.482425,0.007568,0.361312,0.729659,-0.366192,-0.225635,0.047594,0.535526,-0.331578,0.000391,0.196063,0.019159,-0.091271,-0.172678,-0.207022,-0.311075,0.114402,0.062932,0.068587,-0.873856,-0.235551,-0.015097,0.090300,-0.909784,0.380081,-0.071732,0.037682,0.030442,-0.328489,0.364064,0.339934,0.461566,0.283601,-0.397982,-0.016891,-0.513220,0.218327,0.750042,0.283889,-0.206832,0.348090,-0.507142,-0.562310,-0.092591,-0.138543,-0.632203,-0.011047,0.409216,0.157467,-0.115765,0.236725,-0.447042,-0.440551,-0.085930,-0.147341,-0.135130,-0.690556,0.177967,-0.087372,-0.170626,-0.493129,-0.358340,-0.038148,0.001367,-0.462304,0.720123,-0.991377,0.265043,0.373311,0.228524,-0.619854,0.495227,0.257050,0.062911,-0.077256,0.225908,0.513431,0.125727,0.190196,0.407365,0.316950,-0.123950,0.045520,-0.284841,0.569282', '1301022', '1299802', '26253737', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297643', '心火', '剧情', '伊丽莎白（苏菲·玛索 Sophie Marceau 饰）和英国贵族查理（斯蒂芬·迪兰 Stephen Dillane 饰）之间有一个不可告人的交易——她给他三个晚上，为他生下孩子，然后安静地离开。查理给了伊丽莎白一笔钱用以还清她父亲的债务。伊丽莎白按照约定，诞下女儿露易莎。但7年来她心火不灭——她记挂着女儿，每个女儿的生日，她都在画簿上写画心事。同时令她念念不忘的，还有当时与查理之间若有若无的感情。她来到查理家，要当露易莎的家庭老师，查理惊恐要她赶出家门，最终只答应给她一个月教导调皮的女儿。露易莎慢慢被调教得有了修养，而伊丽莎白也与查理旧情复燃。在已经变成植物人的妻子和伊丽莎白之间，查理将如何选择？©豆瓣', '苏菲·玛索', '威廉姆·尼克尔森', 8, 29506, 'tt0119125', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2562936999.jpg', 0.2, 1.4, 21.6, 49.5, 27.2, '-0.007831,0.188932,-0.537755,0.522655,-0.313998,-0.461078,0.689923,0.010243,-0.422329,-0.142385,0.144503,0.883504,-0.052921,0.361977,0.267148,0.388245,-0.564840,-0.726556,0.288414,-0.241464,-0.276550,-0.666766,0.193120,-0.396585,-0.006815,-0.123084,0.351114,-0.448845,0.184720,0.165053,0.088225,0.114139,0.073937,0.083467,-0.304704,0.307571,-0.041486,-0.175714,-0.166432,0.179312,0.210724,0.044565,-0.307409,0.162545,0.244260,0.399181,0.623769,-0.013726,0.012116,-0.078098,0.111400,-0.040919,0.112851,0.231894,-0.036762,0.068284,0.306096,0.317141,-0.481129,-0.113478,0.108778,-0.163043,-0.575299,0.219988,0.040276,0.175189,-0.663198,0.764817,-0.301354,0.049576,0.224017,-0.368974,0.009107,0.611722,0.172568,0.530191,-0.258439,0.112811,-0.681080,-0.069387,0.509276,-0.047262,0.124331,0.447792,-0.364211,-0.165555,0.075538,0.018436,-0.593829,-0.074621,0.340706,0.138210,-0.119325,0.414378,-0.618876,-0.421980,-0.394896,-0.036334,0.190825,-0.593072,0.003540,-0.197894,-0.302685,-0.429527,-0.607640,-0.162019,0.203932,-0.377810,0.711732,-0.660105,0.447444,0.443930,0.594532,-0.504685,0.727459,0.302666,0.133159,-0.130795,0.070285,0.319315,0.147767,-0.034972,0.374408,0.204764,0.181126,0.029966,-0.262788,0.512328', '5327188', '1296132', '35048413', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297644', '茜茜公主3', '剧情', '奥地利年轻的皇后茜茜（罗密·施奈德 Romy Schneider 饰）遍访匈牙利，感受到这里的人民对她毫无政治性的热情，她深深地喜欢上了这个国家和人民，这也是唯一一种能让她逃离维也纳皇室生活压力的办法。然而，当她和安德森伯爵在匈牙利安抚不愿屈服的贵族时，皇太后苏菲（Vilma Degischer 饰）却在散布茜茜与伯爵之间的谣言。弗兰兹（卡尔亨兹·伯恩 Karlheinz Böhm 饰）一直埋头国事，任凭母亲苏菲去干预朝政，甚至包括女儿的抚养问题。当茜茜被诊断患有严重的肺结核病时，弗兰兹竟然依从母亲的意思让医生将女儿从茜茜身边带走。茜茜被送往遥远的岛上养病，孤独无助的她在母亲的精心呵护下，身体逐渐康复。茜茜病愈之后陪同弗兰兹前往意大利北部进行访问。那里的民族主义者们强烈地反对奥地利的统治，对整个王室表现出很大的敌意。但是，当茜茜和她的女儿在圣马可广场重聚时，意大利人民被善良的茜茜感化了，他们热情地欢迎她和女儿的团聚。', '罗密·施耐德', '恩斯特·马里施卡', 8.4, 31688, 'tt0050974', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2539792218.jpg', 0.1, 0.9, 15.5, 44, 39.5, '0.249260,0.256858,-1.014450,0.684066,-0.143430,-0.151100,0.684638,0.258380,-0.678467,-0.096436,0.130383,0.828073,-0.105755,0.236309,0.255951,0.369118,-0.439306,-0.772530,-0.191696,0.154442,-0.363465,-0.364790,-0.033436,-0.318568,-0.299158,-0.402673,0.426772,0.094930,-0.160758,0.532405,0.069926,0.425174,0.127747,0.525119,-0.146750,-0.059156,0.085117,-0.144329,-0.198612,0.243929,0.287597,-0.134659,-0.265717,0.523717,0.172826,0.343141,0.587303,-0.348554,0.124436,-0.177803,0.334064,-0.240480,0.258529,0.435503,0.051412,-0.085286,0.226559,0.167252,-0.330571,-0.113663,0.063087,-0.101310,-0.601869,-0.036110,0.026793,0.194560,-0.718153,0.645517,-0.180880,-0.238036,0.068825,-0.279134,0.391419,0.548889,-0.333736,0.552529,-0.309152,0.171542,-0.381196,-0.027675,0.721321,-0.041449,-0.415187,-0.051848,-0.540026,-0.306974,0.078488,-0.320369,-0.583358,-0.207889,0.101035,0.048319,-0.156522,0.267657,-0.396061,-0.095194,-0.446212,-0.327499,0.123507,-0.501217,0.105696,-0.457909,-0.048126,-0.543938,-0.330645,-0.138123,0.099884,-0.146010,0.819128,-0.643238,0.307178,0.531077,0.607026,-0.619883,0.638102,0.268989,0.097738,-0.030075,-0.366809,0.554157,0.015325,0.188359,0.175383,0.267748,0.151750,0.132928,-0.381431,0.401927', '3111650', '25723780', '21354767', '26425072');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297646', '逍遥骑士', '剧情', '比利（丹尼斯·霍珀 Dennis Hopper 饰）和怀特（彼得·方达 Peter Fonda 饰）用一次毒品交易的钱骑着他们的机车上路了，他们的目的地，是新奥尔良的狂欢节。在路上，他们经过了离群索居的波西米亚人群落，短暂逗留的数天里目睹了他们自由放浪但也贫穷困苦的生活。在德克萨斯州，他们仅因为行为举止诡异就被警察关进了监狱，在那里，他们遇见了律师汉森（杰克·尼科尔森 Jack Nicholson 饰），汉森帮助他们逃离了牢狱之灾，他们怂恿汉森同他们一起上路。抵挡不住内心的骚动，汉森同意了。三人来到一个保守的小镇，在那里受尽了居民的白眼。不受欢迎的三人只得露宿荒野，夜里，当地的居民乔装袭击了他们，汉森被打死。比利和怀特虽然震惊，但这一切都没能阻止他们前进的脚步。到达目的地的两人并没有感到喜悦，有的只是无尽的空虚，沮丧的两人打道回府，但令人意外的是，一个卡车司机和他的双杆猎枪使得他们的行程截然而止。这是影史上最伟大的公路电影，也是为数众多的公路电影的鼻祖。', '彼得·方达', '丹尼斯·霍珀', 8.3, 22342, 'tt0064276', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1379548347.jpg', 0.4, 1.8, 16.1, 46.8, 34.9, '0.488464,-0.330686,-0.879762,0.454865,0.011293,-0.281832,0.992479,0.112434,-0.555616,-0.050858,0.326634,0.877056,-0.148714,-0.011000,0.210846,-0.016549,-0.432074,-0.466542,0.016622,-0.202018,-0.223637,-0.412536,-0.171948,-0.542148,-0.029682,-0.100723,0.459327,0.348028,-0.147082,0.820972,0.247549,0.067636,-0.094491,0.644909,-0.375960,0.276897,0.165505,-0.210215,-0.176093,0.085168,-0.083368,-0.272232,-0.254937,0.322120,0.273936,0.546930,0.683425,-0.077907,-0.239618,0.304423,-0.004712,-0.566213,-0.037545,0.123731,0.294076,-0.271033,0.221736,0.188944,-0.149644,0.115455,-0.036321,0.258521,-0.649462,0.343717,-0.165413,0.111781,-0.739822,0.738899,-0.023186,-0.219117,-0.131110,-0.338440,0.467536,0.241646,0.177343,0.244074,0.029936,-0.234512,-0.736866,0.003254,0.924716,-0.001360,-0.265939,0.219993,-0.449349,-0.507245,-0.264315,-0.173017,-0.548243,-0.146163,0.522672,0.043652,-0.390229,0.095162,-0.620226,0.188388,-0.322352,-0.318937,-0.342540,-0.434857,-0.144850,-0.909353,0.122897,-0.661628,-0.454328,0.126705,-0.050531,-0.025342,0.507315,-0.678587,0.086351,0.601881,0.529471,-0.287382,0.837327,0.039003,0.240036,0.050900,0.075066,0.185257,-0.012375,0.496940,0.473975,0.491293,-0.010962,0.012497,-0.378928,0.497526', '3055049', '26687241', '1301686', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297650', '越空狂龙', '动作', '洛杉矶的“罪恶终结者”约翰（西尔维斯特•史泰龙 Sylvester Stallone 饰）因逮捕恶贯满盈的“铁凤凰”（韦斯利•斯奈普斯 Wesley Snipes 饰）时连带了30多人丧命，被判处了几十年的冰冻刑罚，而“铁凤凰”则被判无期冰冻。几十年过去了，约翰刑满获得解冻重回人间。此时人类的生活方式已和当年大不一样，为了令他尽快适应新社会，当局安排了一位女警的帮助了约翰。约翰的脑子里被植入了含有裁缝技能的记忆芯片，很明显当局想他当一名裁缝。然而，“铁凤凰”阴差阳错地也从冰冻中苏醒并逃出了监狱。更为可怕的是，他的脑里植入了毁灭者的记忆芯片。未来，人类已经不再使用枪、火箭炮等野蛮的武器了。“铁凤凰”在武器博物馆里搞到了一切装备后，开始大肆破坏……©豆瓣', '西尔维斯特·史泰龙', '马可·布拉姆贝拉', 6.8, 5920, 'tt0106697', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p726735301.jpg', 1.2, 6.7, 52.9, 30.8, 8.4, '0.013261,0.261706,-0.506879,0.399324,-0.129822,-0.292137,0.720933,-0.017718,-0.471999,-0.343887,0.196946,0.576548,-0.078367,-0.056450,0.118611,0.000028,-0.374785,-0.523389,-0.118840,-0.124215,-0.600459,-0.211027,-0.274826,-0.277521,-0.056770,-0.533231,0.626742,0.115743,-0.138619,0.058798,0.013926,0.441240,0.033557,0.218035,-0.075444,-0.043546,0.134952,-0.124940,-0.239437,0.328113,-0.004968,-0.335328,0.234938,0.298962,-0.152626,0.349880,0.678600,-0.410457,-0.035853,-0.242964,0.245459,-0.196964,-0.242565,0.112514,0.191818,0.148491,-0.142151,0.092602,-0.369846,0.134918,0.126828,-0.049549,-0.754797,-0.144521,-0.137358,-0.074419,-0.449086,0.472722,-0.117430,0.386009,-0.132893,-0.333235,0.178070,-0.019534,0.200067,0.439335,-0.169875,-0.108145,-0.487666,0.402814,0.395578,-0.272588,-0.447339,0.317573,-0.147217,-0.636945,-0.353722,-0.124381,-0.030506,-0.224020,0.589869,0.240107,-0.367360,0.521560,-0.820931,0.007810,-0.508681,-0.104461,-0.144926,-0.148451,-0.093939,-0.535750,-0.126709,-0.259558,-0.141872,-0.107974,0.089784,-0.099601,0.508088,-0.605407,0.249320,0.433348,0.015879,-0.404967,0.129675,-0.104567,0.018999,-0.176428,0.030675,0.255953,0.347103,0.705316,0.599317,0.299005,0.040020,-0.129495,-0.308329,0.713898', '25774050', '1578502', '1292680', '1293531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297659', '卢浮魅影', '悬疑', '美丽的姑娘丽莎（苏菲·玛索 Sophie Marceau 饰）和祖母一同居住在卢浮宫对面的大楼。卢浮宫的修葺工程使老旧的大楼常出问题，丽莎因此结识了善良的电工小伙马丁（弗雷德里克·迪方多 Frédéric Diefenthal 饰）。某次的施工无意中打通了卢浮宫地道与大厦的电梯间，丽莎与马丁因此夜入卢浮宫，走进了科学家们研究古埃及木乃伊的实验室。丽莎与一具木乃伊干尸对望，没想到却使木乃伊中的鬼魂进入了她的身体，从此每到深夜，丽莎便被鬼魂驱使在卢浮宫里游荡，搜寻古埃及的护身符。馆长请来经验丰富的退休警察弗拉克（米歇尔·塞侯 Michel Serrault 饰）负责调查卢浮宫幽灵事件，从英国来的埃及学专家格兰达（朱莉·克里斯蒂 Julie Christie 饰）也帮了大忙。但众人的努力是否真能制服丽莎体内的强大幽灵呢？©豆瓣', '苏菲·玛索', '让-保尔·萨罗米', 6.6, 43877, 'tt0214529', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2354703197.jpg', 1.2, 9.2, 53.9, 28.4, 7.2, '0.415739,-0.219052,-0.565775,0.098059,-0.081593,-0.382665,0.841247,0.059745,-0.613776,-0.322571,0.532753,0.667825,-0.298874,-0.050068,0.129858,0.317049,-0.619900,-0.464923,-0.073818,-0.236407,-0.369251,-0.409907,-0.350399,-0.184039,0.115116,-0.298070,0.278028,-0.051447,0.118098,0.503351,-0.189298,0.475500,-0.182833,0.072811,-0.170110,-0.121075,0.417922,-0.023682,0.026881,0.244861,0.019678,-0.124769,-0.161537,-0.138673,0.120228,0.193722,0.585103,-0.292456,0.192223,-0.102656,0.188557,-0.091803,0.217955,0.167060,0.209336,0.011132,0.252450,0.185852,-0.327730,-0.071818,0.081363,-0.154493,-0.401925,0.096677,0.173730,0.249814,-0.610151,0.257029,0.062078,0.069275,0.156607,-0.196294,0.312247,0.144450,0.061002,0.531286,0.130797,0.025758,-0.511477,0.040918,-0.032788,-0.080911,-0.247440,0.144857,-0.173527,-0.307254,0.011857,0.229507,-0.184945,-0.213673,0.341003,-0.093352,-0.166426,0.069943,-0.883928,-0.206365,-0.640272,0.004731,-0.101617,-0.052356,-0.202518,-1.134604,-0.150839,-0.143795,0.122509,-0.220962,0.062272,0.026389,0.561550,-0.622010,0.199449,0.545570,0.352088,-0.234161,0.738976,-0.255345,0.100197,-0.199712,-0.269897,0.155757,0.111671,0.652167,0.061867,0.540166,-0.091117,-0.385291,-0.585673,0.092723', '10466639', '1307897', '6517421', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297666', '星银岛', '爱情', '这天，15岁的少年占美阴差阳错的得到了一张球状星空藏宝图。这张地图记录了宇宙海盗搜刮来的巨额财宝的埋藏地点，于是少年占美踏上了一艘巨大的太空帆船，他的太空历险由此开始。占美遇到了船上的厨师约翰，在约翰的帮助下，占美学习到了很多太空人的知识。在一系列的太空历险与战斗中，占美逐渐掌握在太空生存的技巧与法则。当他们越来越接近宝藏时，占美慢慢发现原来自己一路上的好朋友约翰原来是一个阴险狡诈的海盗。面对朋友的背叛，占美将如何是好？©豆瓣', '约瑟夫·高登-莱维特', '罗恩·克莱蒙兹', 7.9, 12086, 'tt0133240', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2210982462.jpg', 0.3, 1.9, 25.2, 47, 25.7, '0.297440,-0.028237,-0.749673,0.665716,-0.097860,-0.393710,0.614346,-0.105790,-0.529018,-0.003345,0.394929,0.785217,-0.090542,0.118782,0.333288,0.038568,-0.512466,-0.366653,-0.214383,-0.287672,-0.477307,-0.642735,-0.519448,-0.098430,0.092285,-0.542533,0.781910,0.448349,-0.063981,0.198700,-0.239188,0.052750,-0.098732,0.426913,-0.411203,-0.018414,0.147176,0.015941,-0.116079,-0.025280,-0.494624,-0.326247,-0.047648,-0.006982,-0.067307,0.213473,1.016771,-0.240117,-0.071488,0.052299,0.325362,-0.423455,-0.124913,-0.236017,0.264838,-0.015198,-0.285517,-0.185181,-0.192451,-0.110860,-0.067142,-0.129277,-0.689458,-0.380961,-0.146029,0.046458,-0.365937,0.224886,-0.186767,0.038018,0.039881,-0.482244,0.182804,0.294489,0.131385,0.142757,-0.114821,0.091011,-0.578166,0.171493,0.495146,-0.030369,0.025201,0.468969,-0.040159,-0.651711,-0.301816,-0.226842,-0.447579,-0.178049,0.569515,0.029340,-0.315415,0.346164,-0.994284,0.189280,-0.196689,-0.325883,0.084081,-0.395436,-0.386237,-0.740743,-0.264649,-0.269890,-0.121714,0.274982,-0.021479,-0.257714,0.992741,-0.556047,0.188257,0.733035,-0.022884,-0.113163,0.650592,-0.335505,0.000097,-0.302203,-0.046227,-0.010898,0.299511,0.532833,0.038153,0.427783,0.039920,0.093239,-0.313836,0.468903', '26290398', '4181031', '1302661', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297670', '致命罗密欧', '剧情', '韩星（李连杰 饰）本来是香港的一名警察，但他的家族却掌管着美国一个华人犯罪集团，势力庞大。一次韩星为了替父亲顶罪，丢掉了工作，进入了香港的监狱服刑。服刑期间，韩星突然得知自己的亲生弟弟的死讯，悲痛不已的他成功越狱前往了美国寻找弟弟的死亡真相。所有的人都告诉韩星，弟弟的死是和他们家族对立的黑人帮派造成的，但韩星却隐隐觉得别有内情，于是他展开了调查。期间，韩星认识了美丽的女孩特蕾西（阿丽雅 Aaliyah 饰），原来特蕾西正是对立帮派的老大的女儿。不久，特蕾西的哥哥也被人谋杀了，同样不相信周围的人都一面之词的特蕾西和韩星一起展开了调查。最终，他们发现，真相原来很残忍。©豆瓣', '李连杰', '安德泽·巴特科维卡', 6.1, 12412, 'tt0165929', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1669831164.jpg', 2.4, 16.8, 59.9, 16, 4.8, '0.247885,-0.190053,-0.673339,0.590683,-0.241110,-0.243893,0.678316,0.025145,-0.754846,-0.346313,0.305166,0.704390,0.055655,0.351148,0.119016,0.184922,-0.304259,-0.621515,-0.082100,-0.255821,-0.209637,-0.556226,-0.223229,-0.260520,0.039520,0.037157,0.584126,0.092431,-0.053100,0.356255,0.372508,0.197327,-0.134954,0.593370,0.072392,0.142686,0.295950,-0.069533,-0.134613,0.076399,0.106625,-0.275075,-0.072508,0.431765,-0.028032,0.541895,0.446347,-0.053007,-0.112414,-0.339583,0.345532,-0.581799,-0.082564,0.003324,0.351635,-0.035136,0.300414,0.444949,-0.270057,-0.321821,-0.026459,0.034714,-0.774354,0.255674,0.419891,0.150216,-0.501833,0.374371,-0.214558,0.083099,0.079867,-0.235913,0.418292,0.678865,0.223925,0.235390,-0.317446,-0.029207,-0.757775,0.182842,0.808854,-0.178982,-0.017919,-0.028130,-0.143355,-0.434693,-0.108268,-0.309831,-0.372812,0.141257,0.224730,0.039440,-0.334884,0.197642,-0.333892,-0.195658,-0.226154,-0.196861,-0.114420,-0.601241,-0.017653,-0.343305,-0.338404,-0.355778,-0.397915,-0.091144,-0.107602,-0.275604,0.708161,-0.848161,0.043952,0.599050,0.458930,-0.765398,0.591692,0.105742,0.057052,-0.325891,-0.137891,0.149200,0.317962,0.088637,0.133432,0.253245,0.042709,-0.391869,-0.268219,0.098617', '25721544', '1949320', '1301022', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297683', '野兽刑警', '剧情', '飞虎队督察Mike（王敏德）被下放到环境复杂的红番区后，成为一群散漫的生番警察的领导，这群人中尤其烂鬼东（黄秋生）最让他头痛，此人曾殉私让其杀了人的黑帮好友Roy（张耀扬）潜逃，初来乍到时，Mike吃尽他带头搞的苦头。Roy的心腹图钉华（谭耀文）借大佬潜逃坐上第一把交椅 ，成为Mike等人眼中的头号敌手。Mike为找图钉华犯罪证据监视YoYo时，与之生出真情。偷渡回港的Roy得知被Mike戴了绿帽子后，气急败坏欲找Mike报仇，不想被图钉华一刀劈死。烂鬼东得知好友死讯后立时大怒，独自一人闯入图钉华老巢，刑警即可变作野兽。©豆瓣', '黄秋生', '陈嘉上', 7.6, 16172, 'tt0157366', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2028302298.jpg', 0.4, 2.8, 31.3, 49.3, 16.1, '0.199094,-0.175728,-0.437082,0.397183,0.073691,-0.161400,0.355713,0.209240,-0.668151,-0.127896,-0.047723,0.506892,-0.235961,0.212208,0.305751,-0.188692,-0.245528,-0.741260,-0.288430,-0.230816,-0.319690,-0.248593,-0.159585,-0.125108,-0.107232,0.052967,0.282055,0.082766,-0.137462,0.451729,0.510370,0.655917,-0.100759,0.466142,-0.099092,-0.161263,0.005888,-0.052156,-0.157525,0.048740,0.121681,-0.756838,0.113183,0.206351,-0.068027,0.255957,0.519098,0.001249,-0.049600,-0.522936,0.053826,-0.384954,-0.273115,-0.024632,0.241783,-0.121502,-0.019061,0.059392,-0.125398,-0.084653,0.012065,0.073812,-0.767926,-0.097826,-0.067825,-0.056363,-0.632753,0.062525,-0.084530,0.437698,-0.203704,0.063172,0.748052,0.104004,0.122676,-0.043936,0.012433,0.021791,-0.335434,0.045338,0.624291,-0.083232,0.296690,-0.342443,0.165089,-0.220533,0.485310,-0.214429,-0.024604,-0.030909,0.419150,-0.110245,-0.026499,-0.108794,-0.270157,-0.454045,-0.370244,0.177046,-0.020125,-0.107010,-0.408905,-0.267087,0.008925,-0.082019,0.006230,0.225756,0.211451,-0.014900,0.361711,-0.465957,0.076663,-0.071928,0.286339,-0.565373,0.553983,-0.250900,0.170851,-0.305655,-0.315326,-0.163056,0.778913,0.308390,0.331914,0.015959,-0.559359,-0.403611,-0.212397,-0.238092', '3811342', '1305201', '25870679', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297689', '少数派报告', '科幻', '随着科技的发展，人类发明了能侦察人的脑电波的“聪明”的机器人――“先知”。“先知”能侦察出人的犯罪企图，所以在罪犯犯罪之前，就已经被犯罪预防组织的警察逮捕并获刑。乔恩（汤姆•克鲁斯 Tom Cruise 饰）就是犯罪预防组织的一个主管。在一次通过“先知”成功阻止了一起因外遇引起的双人命案之后，乔恩隐约感到了这一套完美的预防犯罪系统中隐含的秘密，那就是少数派报告。原来，共有三个“先知”一起判定一个人是否有杀人企图。当出现分歧时，按少数服从多数原则定案，但最后若证明少数那一方是正确的话，则会秘密保存一份少数派报告。乔恩一觉醒来，突然发现自己已是昔日同事的抓捕对象。乔恩唯一的出路就是找到能证明自己清白的那份少数派报告……©豆瓣', '汤姆·克鲁斯', '史蒂文·斯皮尔伯格', 7.9, 158906, 'tt0181689', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2266526895.jpg', 0.2, 1.6, 23.9, 54, 20.4, '0.329796,0.115355,-0.417273,0.681570,-0.414541,-0.038716,0.419319,-0.112742,-0.546880,-0.285368,0.246558,0.547674,0.298290,-0.038899,0.167972,-0.140168,-0.306580,-0.498780,-0.060330,-0.315001,-0.532791,-0.765946,-0.359944,-0.417446,0.073450,-0.269418,0.688797,0.012271,-0.372458,0.056878,0.148276,0.242422,-0.195797,0.213782,-0.060675,-0.242114,0.403418,-0.157487,-0.363294,0.352848,0.097707,-0.103095,0.080447,0.366128,-0.372091,0.614511,0.328341,-0.576005,-0.317394,0.005651,0.455811,-0.268356,-0.044065,0.067540,0.457004,-0.035896,0.135580,0.332929,-0.117283,-0.135995,-0.109353,0.271057,-1.256435,-0.367849,-0.025129,0.202292,-0.162992,-0.027731,-0.036423,0.050871,0.187581,-0.074449,0.266933,0.464465,0.296602,0.281855,-0.096677,-0.081871,-0.569999,0.068427,0.410022,-0.113207,-0.281709,0.224583,-0.206969,-0.618361,-0.028793,-0.088164,-0.051190,0.089654,0.345379,0.111192,-0.119492,-0.112248,-0.415513,-0.076265,-0.271461,0.017163,-0.028542,-0.483944,0.132070,-0.466416,-0.113640,0.149588,-0.266375,0.309021,0.210393,-0.357546,0.602139,-0.844800,0.137173,0.771665,0.031434,-0.663371,0.450944,0.318182,0.072710,-0.456735,-0.031099,-0.149900,0.348604,0.458843,0.092135,0.236817,0.337122,-0.447403,-0.335870,0.333013', '1793491', '27009869', '3785918', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297710', '天若有情', '剧情', '华弟（刘德华 饰）是一个黑道的小混混，喜欢从飚车中得到快感，整天骑着电单车。他在极不愿意的情况下做了一宗抢劫案，警方怀疑他实施追捕，他挟持了富家女Jojo（吴倩莲 饰）出走，没想到他们不管悬殊的身份地位，很快爱上了对方。Jojo不管家里人的反对跟着华弟出走。华弟后来更遭到了黑道老大的追杀，两人亡命天涯。©豆瓣', '刘德华', '陈木胜', 8.4, 97868, 'tt0100777', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2564014416.jpg', 0.2, 1, 15.3, 46.1, 37.4, '0.454078,-0.113458,-0.749947,0.405321,-0.092686,0.129009,0.377750,0.203040,-0.456843,-0.160615,0.410795,0.726422,0.135895,-0.114455,0.040294,-0.168035,-0.235778,-0.534454,0.268091,-0.249344,-0.098261,-0.318521,-0.212587,-0.317427,-0.281668,0.147338,0.417909,0.082671,-0.540101,0.554712,0.912251,0.249306,-0.090135,0.524801,-0.238605,0.011558,0.120505,0.109851,-0.018303,0.296651,0.022805,-0.397878,0.103383,0.047849,0.078455,0.197393,0.420624,-0.002888,-0.092573,-0.198869,0.105848,-0.257688,-0.194457,0.020533,0.645943,-0.167286,0.014944,0.373166,-0.062595,-0.137665,0.049856,0.354664,-0.614714,0.005608,0.149251,0.341562,-0.809147,0.064482,-0.436413,-0.082862,0.012467,-0.356302,0.094814,0.340307,0.175100,0.077425,0.027645,-0.081405,-0.871151,0.066582,0.973575,0.044800,0.112515,0.206246,-0.137771,-0.108687,-0.150056,-0.420308,-0.344744,-0.008320,0.495564,-0.073913,-0.594330,0.274726,-0.011058,-0.102620,0.091010,-0.006121,-0.344974,-0.455664,0.051944,-0.198536,-0.401247,-0.483725,-0.155997,-0.010909,-0.344354,-0.060726,0.468252,-0.891719,-0.027117,0.360182,0.495690,-1.051521,0.515968,0.349872,-0.242730,-0.123473,0.001522,-0.041578,0.224494,0.136054,0.137941,0.187403,0.039533,-0.447559,0.132352,-0.051245', '1305915', '1308206', '25908042', '3998385');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297715', '火星人玩转地球', '喜剧', '5月9日的傍晚，肯塔基州某地燃烧的牛群狂奔过农场，一架飞碟腾空而起……美国政府很快探知火星人的飞碟已集结在地球周围，经过一番思量，美国总统戴尔（杰克•尼科尔森 Jack Nicholson 饰）决定向世界发布火星人到来的消息。在白宫中，总统夫人玛莎（格伦•克洛斯 Glenn Close 饰）和女儿戴菲（娜塔丽•波曼 Natalie Portman 饰）面对火星人到来像谈论一场寻常的访问活动；在纽约，从事新闻业的史东与娜塔莉正在筹备采访唐纳博士（皮尔斯•布鲁斯南 Pierce Brosnan 饰）；在堪萨斯，瑞奇的哥哥即将担任接见火星人的守卫军人；在拉斯维加斯，昔日拳王拜伦如今为家庭生计苦苦工作。终于到了火星人降临的时刻，他们发出了和平的信号，但之后却是大开杀戒，火星人一再的戏弄政府高层，人们束手无策，然而，真正能战胜火星人的武器出乎了所有人的预料……', '杰克·尼科尔森', '蒂姆·波顿', 7.3, 43980, 'tt0116996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1079311904.jpg', 1, 4.8, 37.3, 43.2, 13.7, '0.054737,-0.072410,-0.802604,0.254866,0.101281,-0.184248,0.431594,0.153456,-0.605526,-0.214994,0.429992,0.674645,-0.463279,0.026991,0.560722,-0.104626,-0.638919,-0.581365,-0.032183,-0.078260,0.005241,-0.489036,-0.254765,-0.358477,0.062412,-0.414617,0.461370,0.085274,0.058906,0.426192,0.210966,0.282417,-0.094587,0.567357,0.006765,-0.120100,0.398884,-0.060968,-0.607274,0.302251,-0.054383,-0.020216,-0.188495,0.094781,0.147829,0.295209,0.404886,-0.522034,0.008362,-0.237808,0.216632,-0.301144,0.203473,0.191907,0.482386,0.029070,-0.136609,0.189593,-0.019244,0.039220,-0.111952,-0.111473,-0.273398,0.130961,-0.014643,0.260655,-0.385308,0.246551,-0.327949,0.227775,-0.049517,-0.386849,0.194352,0.514064,0.004482,0.444506,-0.074067,0.054632,-0.489506,0.157237,0.583102,0.136455,-0.388513,0.161804,0.042348,-0.419920,-0.207328,-0.083639,-0.454835,-0.120097,0.293629,-0.009574,-0.203967,0.433482,-0.492697,-0.201018,-0.401390,-0.593097,0.096390,-0.345586,-0.144240,-1.130372,0.057877,-0.189469,0.016117,0.201800,0.213667,0.006161,0.501740,-0.887893,0.156569,0.452882,0.233158,-0.107004,0.439871,-0.093801,0.194769,-0.213020,-0.013129,0.297867,0.151879,0.490008,-0.161086,0.189497,0.030697,-0.174911,-0.379382,0.241124', '3178770', '3003137', '2075345', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297723', '整九码', '喜剧', '迈阿密牙医奥斯（马修•派瑞 Matthew Perry  饰）的生活并不愉快，这一切都是因为他的妻子苏菲（罗姗娜•阿奎特 Rosanna Arquette 饰）。菲比为人泼辣，十分霸道，令到奥斯整天只能忍气吞声。这天，奥斯家来了新的邻居——吉米（布鲁斯•威利斯 Bruce Willis 饰）。这个吉米不简单，他曾是芝加哥的一个黑帮杀手，因为背叛了黑帮老大查理才来此暂避风头。查理已经发出悬赏令通缉吉米。苏菲为了赏金逼奥斯到芝加哥去告密，本来不愿去的奥斯不得已只能只身前往芝加哥。奥斯也打好了自己的如意算盘，拿到了赏金后就将苏菲甩掉。另一方面，苏菲也有自己的小九九，等奥斯拿到赏金后就雇人将他干掉。岂料意外接踵而至，吉米的老婆辛西娅（娜塔莎•亨斯屈奇 Natasha Henstridge 饰）被查理绑架了，场面变得混乱起来……©豆瓣', '布鲁斯·威利斯', '乔纳森·林恩', 7, 5386, 'tt0190138', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2169724794.jpg', 0.9, 5, 46.3, 38.2, 9.6, '0.186366,0.101499,-0.580520,0.371190,-0.293641,-0.546002,0.536392,0.244467,-0.413776,-0.107051,0.255741,0.633702,0.013105,-0.145733,0.310672,0.446240,-0.624692,-0.338349,0.122896,-0.473425,-0.067273,-0.507026,-0.213609,-0.366314,0.017678,0.161040,0.126902,-0.408532,-0.079341,0.395853,0.530498,0.343640,0.292571,0.563665,0.025095,0.259208,0.222449,-0.183651,-0.103441,0.150001,0.166557,-0.249615,-0.129417,0.450160,0.169762,0.498852,0.279449,-0.215848,0.121847,-0.226197,0.066962,-0.377062,-0.089929,0.087148,0.204097,-0.274427,0.161565,0.026093,-0.341684,-0.023102,0.197237,0.115588,-0.739321,0.298344,-0.034460,0.141034,-0.413657,0.286979,-0.609633,-0.019853,0.084822,-0.402676,-0.056801,0.389157,0.353444,0.116893,0.075747,0.106471,-0.435625,0.229513,0.687902,-0.020485,0.073817,0.061802,-0.135974,-0.203357,0.068181,-0.106953,-0.500088,-0.203649,0.658610,-0.156154,-0.239596,0.287660,-0.462924,-0.325682,-0.583811,-0.267223,-0.294695,-0.257400,0.020981,-0.461359,-0.041603,-0.035577,-0.328285,-0.228721,0.048239,-0.086383,0.371120,-0.695557,0.312900,0.822274,0.544764,-0.172967,0.136475,0.217864,0.268531,0.079683,-0.176848,0.004306,0.270234,0.406827,0.441315,0.341426,0.336684,-0.489642,0.004292,0.571802', '1306723', '1292646', '1907467', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297726', '少林小子', '喜剧', '在风景如画的桂林，两户人家隔河相望，一家是武当嫡传的鲍笙凤（于承惠 饰），鲍家一连八个，皆为女儿，致武当剑法有失传之虞，鲍笙凤整日愁眉不展，更对对岸的少林一家怒目相视。十年前，少林弟子天龙（于海 饰）、二龙从强盗秃鹰（计春华 饰）一伙手中救下八名孤儿，师兄弟将八个干儿子辛苦养大，自己的终身大事却一拖再拖，两人属意鲍家大凤、二凤（丁岚 饰）多时，无奈鲍笙凤视少林为敌，定下十头牛换一门亲的苛刻条件。三龙（李连杰 饰）与七个兄弟为成全干爹和二叔，不舍不弃使出连番妙计，同时与三凤（黄秋燕 饰）在长期的对峙中互生了情意……另一方面，不甘十年前受创的秃鹰一伙派出奸细，试图进一步挑拨龙、凤两家关系，三龙为父为己的求婚之路，顿时荆棘密布……©豆瓣', '李连杰', '张鑫炎', 7.3, 9972, 'tt0086301', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2242874295.jpg', 0.6, 3.4, 39.8, 41.1, 15.1, '-0.016622,-0.327350,-0.439999,0.666509,0.291195,-0.325722,0.264361,0.065159,-0.604479,-0.227618,0.224768,0.620671,0.014348,0.267969,-0.179007,-0.310300,0.352813,-0.672017,-0.190076,-0.180379,0.009406,-0.248175,0.053510,-0.056374,-0.124640,-0.067928,0.248223,0.147930,0.214877,0.679210,0.521706,0.117460,-0.530147,-0.289375,-0.230750,0.113206,-0.078310,0.126549,-0.425451,0.019960,-0.349374,-0.160763,-0.129918,-0.044351,-0.100724,0.624792,0.522195,-0.080248,-0.126206,-0.331572,-0.068690,0.121914,-0.144874,0.141905,0.491528,-0.051341,0.404308,0.322827,-0.209540,-0.004713,-0.071563,0.003095,-0.592581,0.185409,0.368865,-0.206226,-0.714598,0.607659,-0.117351,-0.251959,-0.124576,-0.243033,-0.159858,0.384271,0.101694,0.138546,-0.255666,-0.074830,-0.263480,0.121860,0.554395,-0.252085,0.492856,-0.052724,0.267739,-0.093335,0.124485,-0.304916,-0.051698,-0.172989,0.471308,-0.097808,0.303656,0.226613,-0.481718,-0.085968,-0.158324,0.378173,-0.057883,-0.240267,0.312176,-0.353688,0.089016,-0.329963,-0.183753,0.279358,0.394183,-0.172232,0.652389,-0.419503,0.056166,-0.347845,0.308588,-0.716302,0.575733,0.132573,0.297516,-0.308671,-0.178357,-0.072514,0.085163,-0.098961,0.508078,0.223742,-0.100573,0.074000,-0.229042,0.042883', '1293607', '26678784', '27621189', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297735', '没有面孔的眼睛', '剧情', '生物学教授詹尼西尔（Pierre Brasseur 饰）因一次车祸使心爱的女儿克莉丝汀（Edith Scob 饰）面容尽毁，女儿伤愈后只能终日戴着瘆人的白色面具，痛苦非常。爱女心切且心怀内疚的詹尼西尔与助手路易丝（Alida Valli 阿莉达•瓦莉 饰）伪装克莉丝汀失踪、死亡的假象，暗中诱拐与女儿年龄相仿的女性，将其麻醉后剥掉面皮，移植到克莉丝汀脸上。但手术接连失败，牺牲者也不断增加。亲眼所见诸多同龄女孩惨遭杀害，克莉丝汀心中痛苦不已。另一方面，众多女孩失踪的案件也引起了警方的注意，他们逐渐将目标锁在疯狂的詹尼西尔身上……©豆瓣', '皮埃尔·布拉瑟', '乔治·弗朗叙', 7.5, 6503, 'tt0053459', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1917242779.jpg', 0.4, 2.1, 32.3, 51.9, 13.3, '-0.235406,-0.208755,-0.288047,0.449360,-0.307553,-0.085744,0.941608,0.129238,-0.824735,-0.224071,0.321047,0.772848,-0.374062,0.435155,0.175468,-0.012338,-0.521838,-0.554120,0.073021,-0.287455,-0.493291,-0.365462,-0.015233,-0.265949,-0.162311,-0.623577,0.546818,-0.081659,0.097203,0.493182,0.128921,0.327463,-0.226403,0.204077,0.452857,0.089502,-0.137542,-0.480361,0.206700,0.128219,0.065704,-0.184893,0.017552,0.391146,-0.010062,0.468086,1.161693,-0.190566,-0.017676,-0.444728,0.486571,-0.232788,0.139545,0.346019,0.004868,0.090074,0.230725,0.187689,-0.382649,-0.316972,0.384411,0.157001,-0.505210,0.242097,0.238021,0.139059,-0.550864,0.264447,-0.391066,0.031934,0.121470,-0.274800,0.056807,0.351593,0.106636,0.233073,-0.291978,0.030811,-0.287005,-0.017372,0.196935,0.195070,-0.058057,0.043262,-0.559723,-0.298592,0.134151,-0.121841,-0.477574,-0.048466,0.426691,0.211712,-0.095056,0.482345,-0.100748,-0.320341,-0.534374,-0.048104,-0.070597,-0.234878,-0.077529,-0.566475,-0.314361,-0.536960,-0.428207,-0.176669,0.036645,-0.219823,0.577008,-0.658600,0.278908,0.474440,0.084894,-0.009013,0.125165,-0.041616,0.397460,-0.126018,-0.317143,0.658397,0.057566,-0.039791,-0.001546,0.187716,-0.054939,0.244930,-0.192451,0.297458', '21619567', '1467779', '27066196', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297737', '窈窕淑男', '喜剧', 'Michael Dorsey（达斯汀·霍夫曼 Dustin Hoffman 饰）是一个没什么名气的演员，混迹在一些小话剧和肥皂剧中，最近和经纪人George Fields（西德尼·波拉克 Sydney Pollack 饰）闹翻了，因为经纪人不愿意帮他的下一部话剧找投资，更认为他不可能再找到工作了。为了筹到钱来演他的室友Jeff（比尔·默瑞 Bill Murray 饰）所写的剧本，Michael于是化妆成一个女人的模样，并化名Dorothy Michaels。他从他的女性朋友Sandy（特瑞·加尔 Teri Garr 饰）那听说了一部电视剧的试镜，他成功成为剧中一个叫Kimberly的角色。他和戏中的女主角Julie Nichols（杰西卡·兰格 Jessica Lange 饰）两人相谈甚欢，甚至让Julie的父亲都爱上了他。然而Julie却不知道Dorothy的真正性别。Michael日渐发现Julie的男朋友，电视剧导演Ron，并不是真心爱她，而他自己，也越来越喜欢Julie。Michael所塑造的角色引起了轰动，更让他烦恼的是，有越来越多的男人向他求爱.....', '达斯汀·霍夫曼', '西德尼·波拉克', 8.1, 12260, 'tt0084805', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p817072758.jpg', 0.2, 0.8, 17.4, 56, 25.5, '0.316681,-0.162062,-0.672929,0.729746,-0.271262,-0.266159,0.939750,0.020236,-0.306229,-0.260431,0.002690,1.047282,-0.144613,0.113168,0.018414,0.042485,-0.351916,-0.705488,0.066872,-0.199309,-0.048961,-0.386957,-0.389858,-0.073692,-0.228866,-0.291336,0.812126,-0.054125,-0.344088,0.136890,0.648619,0.003088,0.458423,0.628349,0.060232,0.135817,-0.162811,0.105069,0.052837,0.356337,0.222390,-0.213732,-0.212432,0.351998,-0.088698,0.476671,0.400795,-0.073400,-0.180187,-0.003129,0.564760,-0.321213,0.036133,-0.098433,0.000674,-0.209934,0.440756,0.065945,-0.264917,0.089585,-0.025581,-0.088529,-0.883799,0.247392,0.185899,0.455909,-0.651762,0.396973,-0.251855,-0.222545,0.009644,-0.368667,0.233601,0.228159,0.326173,0.198278,-0.262043,-0.074255,-0.635368,0.597617,0.619192,0.367883,0.047963,0.865378,-0.229873,-0.506193,-0.294336,-0.251411,-0.658349,0.162305,0.192760,-0.300327,-0.108574,-0.056198,-0.494533,0.105965,0.099982,-0.157533,-0.207901,-0.697455,0.238467,-0.557618,-0.308650,-0.476813,-0.154260,-0.300849,0.135220,-0.697996,0.860973,-0.897346,-0.105683,0.684295,0.427837,-0.637469,0.865594,0.359559,-0.145188,-0.217568,-0