INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297743', '幸福时光', '剧情', '退休工人老赵（赵本山饰）相中了一个胖女人，令他尴尬的是，胖女人与他初次见面就提出要5万块钱作为婚礼的费用，老赵只能咬着牙答应了。徒弟小傅给他出了个主意，让他利用厂区后面的一个旧公共汽车车厢，使它成为那些恋爱男女约会的场所，并起名为“幸福时光小屋”。一天老赵到胖女人家见到胖女人前夫留下的盲女孩（董洁饰），胖女人嫌弃她，要老赵将盲女孩安排在“幸福时光小屋”工作。事有不巧，当老赵带盲女“上班”时，旧车厢已被吊在空中。胖女人家已没盲女的容身之地，老赵只好带盲女回家。为帮盲女恢复生活的信心，老赵和众工友将这个啼笑皆非却又感人的骗局小心翼翼地继续下去，一班退休同事假扮成前来按摩的顾客……©豆瓣', '董洁', '张艺谋', 7.2, 23029, 'tt0303243', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2183481605.jpg', 0.8, 4.8, 42.5, 38.3, 13.7, '0.046951,0.135332,-0.176145,0.052604,-0.535238,-0.585972,0.705148,0.037851,-0.271889,-0.222473,-0.075811,0.478332,-0.013710,0.497770,0.164087,0.140976,-0.064399,-0.472233,-0.179299,0.076994,-0.313937,-0.263027,0.193778,-0.286048,-0.215958,0.052084,0.256647,0.010235,0.171649,0.333622,0.431478,-0.040820,0.003545,0.313268,-0.427926,0.103268,0.020403,-0.024541,-0.197397,0.003967,-0.066556,-0.045482,-0.115972,-0.075804,0.066936,0.182780,0.659554,0.352718,-0.273925,-0.024377,0.226957,-0.051005,-0.010900,-0.115943,0.285063,0.144061,0.194137,-0.063123,-0.243126,-0.100631,0.290887,-0.107081,-0.363892,0.329005,0.094940,-0.149087,-0.517420,0.316222,0.064192,0.009945,-0.011358,-0.407891,0.129503,0.082177,0.338445,0.384446,-0.188275,0.252072,-0.432507,0.375252,0.328231,0.062246,0.008540,0.433388,-0.163527,-0.132240,0.314411,0.002918,-0.434766,0.028880,0.329998,-0.157159,-0.259894,-0.169264,-0.440521,-0.267573,-0.309625,0.086481,0.082270,-0.447675,-0.139475,-0.307031,0.057407,0.075126,-0.193318,0.170586,0.213490,-0.078752,0.447020,-0.510809,0.111241,0.491744,0.292676,-0.352906,0.790919,0.162166,0.181128,-0.257747,0.075373,-0.157455,-0.050111,0.305568,0.235300,0.376652,-0.270441,-0.059261,-0.329067,0.364965', '2375763', '3055049', '1302384', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297747', '少林足球', '喜剧', '二十年前有“黄金右脚”之称，但因一场被师兄强雄设计陷害的比赛而断了右脚自此名誉扫地的明锋（吴孟达）偶然认识了有惊人脚力的星（周星驰），说服了对方练习足球参加不久会举行的全国超级杯足球大赛，星找来曾一同在少林寺习武的一帮师兄弟，并唤醒了他们快被平庸生活消磨光了的潜在斗志，众人经过历练终结成名副其实的“少林队”。阿梅（赵薇）以太极功夫制造馒头，令星十分敬佩与之成了好友，但阿梅不只当星为好友，只因样貌奇丑而自卑一直不敢表露心意。“少林队”在全国超级杯足球大赛上屡战屡捷杀进决赛，不想卫冕之战对手竟是强雄（谢贤）所带领的“魔鬼队”，同二十年前一样，强雄再耍阴招令“少林队”节节败退，关键时刻，阿梅现身。©豆瓣', '周星驰', '周星驰', 8.1, 387433, 'tt0286112', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2507107765.jpg', 0.4, 2.4, 22.3, 43.5, 31.5, '-0.133515,-0.074032,-0.457139,0.367179,0.086085,-0.231696,0.071315,0.083466,-0.554948,-0.183453,0.024921,0.723498,-0.265605,0.049196,0.050171,-0.525618,0.151246,-0.586645,-0.224695,-0.206531,-0.041226,-0.124573,0.026122,0.141267,-0.030092,-0.157764,0.760714,-0.107841,-0.418582,0.573894,0.412255,0.034789,0.138731,0.219381,-0.187025,0.023567,0.018351,0.103341,-0.114352,0.255302,-0.265437,-0.372339,-0.189269,0.050918,0.114948,0.189827,0.482138,-0.019944,-0.000718,-0.439192,0.227481,-0.234512,-0.070825,-0.056290,0.368393,0.036689,0.359428,0.143792,0.201310,-0.054249,-0.079457,-0.405039,-0.570104,0.307692,0.326015,-0.244913,-0.643990,0.643578,-0.045232,-0.035202,-0.219134,0.108427,0.202571,0.350301,0.251850,-0.027747,-0.007701,-0.281888,-0.361654,0.274721,0.723318,-0.174157,-0.055403,0.148379,0.319053,-0.316937,0.121298,-0.714968,-0.136531,0.180110,0.178237,-0.027195,0.096412,0.240078,-0.385709,0.040849,-0.306159,0.132534,0.027927,-0.232131,0.229890,-0.432461,-0.092054,-0.312085,-0.346517,0.084451,0.006464,-0.105305,0.658584,-0.892420,0.179711,0.317058,-0.046322,-0.351535,0.613313,0.223177,0.022249,-0.155293,0.032919,0.251339,0.006139,0.154305,0.128754,0.488648,-0.004957,-0.150600,-0.430448,0.050489', '35030151', '1826173', '22964524', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297753', '最高危机', '动作', '1995年，反恐特别行动组特维斯中校（史蒂文·席格 Steven Seagal 饰）带队执行一次解救行动，不料却以失败告终……三个月后，军情局顾问戴维（库尔特·拉塞尔 Kurt Russell 饰）接到消息：恐怖组织头目阿布亚法被捕并将被引渡到美国。10天后，一架由雅典飞往华盛顿的747客机被阿布亚法的副手安塔尔劫持，后者要求美国政府释放阿布亚法。戴维受命解决危机，他指出恐怖分子的本意是利用毒气炸弹攻击美国本土，所以坚决不能使飞机入境。同时参会的特维斯提出了大胆的计划：他要率领反恐特别行动组通过空中对接的方式登上被劫持的747客机……©豆瓣', '库尔特·拉塞尔', '斯图尔特·贝尔德', 7.5, 6930, 'tt0116253', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1150346103.jpg', 0.6, 2.3, 33.1, 47.4, 16.7, '0.212394,0.095640,-0.550649,0.613436,-0.072321,0.045645,0.057089,0.111720,-0.530851,-0.197559,0.180043,0.446419,-0.101440,-0.374702,0.437923,-0.015218,-0.285454,-0.539203,-0.071706,-0.080231,-0.308690,-0.763715,0.031899,-0.428664,0.099871,-0.319405,0.625566,0.089048,-0.096922,0.488570,0.350725,0.565200,-0.050907,0.505335,0.227570,-0.459982,0.402331,-0.502944,-0.362591,0.700274,-0.084842,-0.344592,0.039899,0.245491,0.177911,0.546648,0.558844,-0.116017,0.097357,-0.473098,0.055085,-0.646820,0.132225,-0.070839,0.489112,0.370119,-0.228659,0.470243,-0.087087,0.147273,0.089698,-0.163820,-0.623870,0.143543,-0.128734,-0.098447,-0.357167,-0.241043,-0.594959,0.619941,-0.057326,-0.352813,-0.012108,0.522859,0.352868,-0.010595,-0.070943,0.237272,-0.345394,-0.073564,0.804019,-0.284364,-0.289354,-0.330291,0.031864,-0.341095,0.275560,-0.217328,0.243887,0.193301,0.341087,-0.050682,0.078035,-0.117777,-0.407784,-0.229123,-0.601470,-0.297364,-0.197709,-0.290311,0.270785,-1.094635,0.287700,0.295930,-0.238680,0.186228,0.115463,0.219566,0.367897,-0.615818,0.013629,0.682851,0.264932,-0.574793,0.116128,0.234795,0.033195,-0.636615,0.200361,0.044310,0.357258,0.293289,-0.076089,0.063395,0.077515,-0.338995,-0.060837,-0.254162', '2369613', '2028645', '1293572', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297756', '白雪公主和七个小矮人', '爱情', '白雪公主原本是世界上最幸福的人，可惜当她母后逝去，父王娶了她继母后，这一切都改变了。恶毒的继母处处为难白雪公主，当她父王也死后，白雪公主过得更艰难了。这天，皇后从魔镜中得知世上最美的人不是自己而是白雪公主后，气急败坏的她下令武士将她带到森林处决了，好心的武士放走了白雪公主。夜晚，森林里的七个小矮人收留了无家可归的白雪公主。当皇后得知白雪公主还没死时，气急败坏的她决定亲自出马将白雪公主害死。第二天，她化妆成了一个老婆婆，带着毒苹果往森林深处走去。©豆瓣', '阿德里亚娜·卡塞洛蒂', '戴维·汉德', 8.4, 112798, 'tt0029583', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1833054584.jpg', 0.1, 0.6, 14.9, 48.7, 35.6, '-0.008319,0.330517,-0.603363,0.484706,-0.337870,-0.203423,0.954088,-0.098805,-0.347340,0.115126,0.203544,0.631564,0.025992,0.404605,0.130169,0.449777,-0.581792,-0.339053,-0.245498,-0.381153,-0.473905,-0.181534,-0.046274,-0.281803,0.089092,-0.353872,0.473778,-0.008454,0.017336,0.162331,0.316011,-0.225554,0.008011,0.565037,-0.325466,0.535275,0.022639,-0.108153,0.099427,0.291977,-0.022288,-0.274035,-0.089345,0.345741,-0.162468,0.258843,0.575989,-0.541132,0.141627,-0.447148,0.358416,-0.407327,-0.196191,0.292383,0.140576,-0.425672,0.032447,0.152543,-0.105074,-0.166406,-0.004588,-0.147415,-0.606027,0.137425,-0.035463,-0.017613,-0.569288,0.229514,-0.050985,0.098811,0.434100,-0.404830,0.430125,-0.198047,0.035328,0.332880,-0.166648,-0.009023,-0.673904,0.547067,0.626753,-0.166294,-0.015154,0.335163,0.107475,-0.263841,0.384894,-0.165190,-0.454154,0.160779,0.553101,-0.101291,-0.485431,0.186533,-0.265066,-0.304873,-0.239357,-0.033928,0.063753,-0.624325,-0.313801,0.194260,-0.030010,-0.069192,-0.289159,-0.052169,-0.126436,-0.106836,0.526002,-0.295037,0.518839,0.586915,0.347330,-0.533823,0.678711,-0.156616,0.166486,0.001741,0.243440,0.328653,0.091469,0.369462,0.276066,0.248589,-0.011654,0.039049,-0.610374,0.399661', '21619567', '26884422', '1292217', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297759', '战争与和平', '剧情', '1812年，拿破仑的军队控制大部分的欧洲国家。在为数不多未被征服的国家中，俄国打算联合奥地利一起进行殊死抵抗。贵族安德烈公爵（梅尔·弗尔 Mel Ferrer 饰）就是这样怀揣一腔抱负的俄国军官。然而安德烈的挚友皮埃尔公爵（亨利·方达 Henry Fonda 饰）却毫不关心战事。他在父亲临终前成为遗产继承人，与贵族之女海伦（安妮塔·艾克伯格 Anita Ekberg 饰）结婚，却在婚后不久发现性格不合而分居。安德烈战役失败被释放归家看望难产而死的妻子。几个月后，彼埃尔与罗斯托夫伯爵一家在去打猎，叫上了安德烈。安德烈对伯爵的女儿娜塔莎（奥黛丽·赫本 Audrey Hepburn 饰）一见钟情。不久，娜塔莎接受了安德烈的求婚，然而安德烈很快重返军队。海伦的弟弟阿纳托里趁虚而入，骗得娜塔莎的爱，唆使娜塔莎与他私奔。俄法战争开始，娜塔莎遇到了深受重伤的安德烈，安德烈在临死前原谅了娜塔莎的背叛。战争结束后，皮埃尔回到了莫斯科，与娜塔莎结合在了一起。', '奥黛丽·赫本', '金·维多', 7.6, 9874, 'tt0049934', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2125200529.jpg', 0.7, 3.5, 29.7, 45.5, 20.7, '0.286606,0.132476,-0.804372,0.437600,-0.027122,-0.634795,0.631296,0.099388,-0.491019,-0.242860,0.244986,0.988789,-0.154782,0.167478,0.432874,0.013965,-0.523601,-0.733641,0.100046,0.001479,-0.147642,-0.645306,0.077891,-0.304245,-0.157086,-0.589548,0.777125,0.040732,0.087841,0.448472,0.286346,0.439467,0.194879,0.375565,-0.012601,0.140707,0.239955,-0.234809,-0.585928,0.491162,0.057694,-0.026473,-0.073710,0.158287,0.049385,0.236962,0.453358,-0.497230,0.530909,-0.333356,0.191018,-0.212546,0.047334,0.367622,0.419879,-0.034902,-0.003746,0.322165,-0.189153,-0.381401,0.078275,-0.043650,-0.229102,0.135759,-0.078572,0.164930,-0.686952,0.629272,-0.272825,0.182208,0.236762,-0.170547,0.079595,0.801412,0.008061,0.345416,-0.172955,0.203947,-0.624197,-0.004808,0.805854,-0.262804,-0.133515,-0.095607,-0.041506,-0.360722,0.125736,-0.435278,-0.555756,-0.037563,0.305606,-0.069538,0.030878,0.527609,-0.504839,-0.259867,-0.671916,-0.153703,0.337013,-0.390104,0.112354,-0.797073,-0.189145,-0.387226,-0.248361,0.037996,0.157217,-0.119067,0.555954,-0.918943,0.310464,0.390482,0.605171,-0.559030,0.490898,0.336282,0.358679,-0.148334,0.085083,0.711205,0.129663,-0.106017,0.292200,0.149176,0.255367,0.045013,-0.108445,0.420013', '25721544', '1302987', '26971054', '26393561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297763', '方世玉', '喜剧', '方世玉（李连杰 饰）原是城中纨绔子弟，好打抱不平。一日，他闻说外省富豪雷老虎在次设下擂台，比武招亲，又听讲雷小姐貌美如花，遂前往比武招亲。当方世玉过赢准备打赢未来岳母李小环时，一阵风吹过，将台上坐着的小姐的盖头吹了起来，他发现竟是一名丑女时，马上故意认输，溜之大吉。方世玉的母亲苗翠花（萧芳芳 饰）听说儿子擂台上败下阵，自觉颜面无光，于是化身方世玉的哥哥方大玉前往打擂，一举打败了李小环。岂料雷老虎当晚即派人来接方大玉成亲。世玉为救母亲，只有代替母亲前往雷家成亲。母子两计划新婚之后趁回门的时候一起出逃，岂料方世玉的父亲方德回来了！©豆瓣', '李连杰', '元奎', 8, 152978, 'tt0106936', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2608498684.jpg', 0.1, 0.9, 21.4, 54.3, 23.3, '-0.082221,0.122050,-0.524808,0.190314,-0.134532,-0.297918,0.006128,0.263279,-0.204735,-0.228638,0.222937,0.595001,-0.179394,0.416227,0.572548,-0.050017,0.047114,-0.422311,-0.108093,-0.090310,-0.161146,-0.185142,0.128291,0.071451,0.159485,-0.239042,0.124751,0.009454,0.013482,0.688198,0.467220,-0.265813,-0.210427,0.392444,-0.242207,0.287612,-0.187672,0.266511,-0.427111,0.296568,-0.076606,-0.054441,-0.331705,-0.283873,0.265629,0.272980,0.254283,-0.141393,0.081083,-0.467057,0.192138,-0.024167,0.179774,0.154400,0.394753,-0.030402,0.107971,-0.062224,0.030993,-0.039513,-0.001235,-0.248440,0.123124,0.419250,0.121537,-0.387173,-0.524056,0.213044,-0.121196,0.278081,-0.069931,-0.205698,0.282874,0.307735,0.032441,0.118531,-0.170793,0.254309,-0.474126,0.231665,0.768453,-0.039541,0.557033,-0.092267,0.609579,-0.126061,0.266014,-0.119080,-0.187487,0.141418,0.478716,-0.037673,-0.082714,-0.333500,-0.127811,-0.550730,-0.335558,0.338086,0.140875,-0.324095,0.092761,-0.284352,0.060627,0.254014,0.051841,0.163143,0.022218,-0.193580,0.317673,-0.400327,0.234865,0.191005,0.325262,-0.442241,0.268275,0.080486,0.242626,-0.194514,0.177467,-0.245204,0.181710,0.139439,0.352748,0.231691,-0.221303,0.000796,-0.077547,0.058986', '2084048', '1451563', '1296978', '25856453');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297769', '马语者', '剧情', '安妮（克里斯汀•斯科特•托马斯 Kristin Scott Thomas 饰）的女儿格雷斯（斯嘉丽•约翰逊 Scarlett Johansson 饰） 喜欢骑马，却在一次事故中和好友一同从马背摔下，好友遇难，而格雷斯也摔断了一条腿，她心爱的马匹“朝圣者”受伤得面目全非。格雷斯的心里蒙上了挥之不去的阴霾。母亲心里十分着急。听说蒙大拿有精通马语之人汤姆（罗伯特•雷德福 Robert Redford 饰），安妮决定携女儿和“朝圣者”同往疗伤。汤姆起初不答应，终被感动，格雷斯和“朝圣者”在马语者精心的训练调养下慢慢复原，而离开了大都市的安妮也沉浸在那一片安静广袤的天地中。但是，安妮为此付出了代价——她长期离职，被解雇了，同时和丈夫的感情越来越疏远淡漠。另一方面，汤姆的与众不同让安妮心里泛起了阵阵涟漪。©豆瓣', '罗伯特·雷德福', '罗伯特·雷德福', 8.1, 19552, 'tt0119314', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p949388374.jpg', 0.2, 1.2, 18.6, 51.3, 28.7, '0.113388,-0.113613,-0.920335,0.645433,-0.057396,-0.508316,0.987081,0.156696,-0.460173,-0.105483,0.323871,0.868858,-0.214548,0.181904,0.261641,0.203148,-0.357890,-0.556307,0.002673,-0.064446,-0.217627,-0.523796,-0.184963,-0.193400,-0.240633,-0.488786,0.490611,0.011473,0.205588,0.783738,0.096507,0.298122,0.120283,0.522367,0.040890,0.235213,-0.081026,-0.179137,-0.020992,0.079259,0.397122,-0.224526,-0.158975,0.117192,-0.015630,0.526668,0.606836,-0.061062,0.003405,-0.082447,0.289637,-0.346960,0.240323,0.127564,-0.071985,0.054732,0.225754,0.050998,-0.302643,-0.028632,0.236140,0.090374,-0.311256,0.226681,0.067226,0.195726,-0.838857,0.534569,-0.420463,-0.006344,0.020844,-0.354242,0.272977,0.164974,0.122584,0.410251,-0.305034,0.218815,-0.372927,-0.120010,0.499080,-0.004608,-0.007210,0.348459,-0.540680,-0.251481,0.188599,0.058430,-0.447964,-0.241282,0.417820,0.114295,-0.079378,0.326477,-0.402788,-0.013184,-0.373932,-0.273209,-0.442150,-0.364304,-0.142350,-0.271169,-0.227334,-0.432758,-0.390473,-0.157054,0.020931,-0.198677,0.408946,-0.800383,0.244348,0.220664,0.153386,-0.156311,0.495578,0.079326,0.205344,0.061208,-0.017074,0.394802,-0.023733,0.259313,0.489151,0.427183,-0.027227,0.146094,-0.503687,0.458806', '3111650', '6827727', '25723780', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297785', '星球大战前传2：克隆人的进攻', '动作', '绝地武士战胜西斯学徒后十年，银河共和国再次面临威胁，前绝地武士杜库伯爵（克里斯托弗•李 Christopher Lee 饰）鼓动数千星系与共和国决裂，并筹建大批机器人军队为政变做准备。纳布星的阿米达拉（娜塔丽·波特曼 Natalie Portman 饰）结束女王任期后以议员身份抵达考路斯坎星，决意为组建共和军队投出关键一票。欧比-旺•肯诺比（伊万•麦克格雷格 Ewan McGregor 饰）携长大了的阿纳金（海登·克里斯滕森 Hayden Christensen 饰）奉命保护阿米达拉的安全。在阿纳金护送阿米达拉返回纳布星避难的途中，二人情愫暗生，决定共同前往塔图因星寻找阿纳金之母。与此同时，欧比-旺追查刺客行迹一路深入吉诺西斯星，发现了杜库伯爵的阴谋，自己却深陷囹圄，危在旦夕……本片获2003年第75界奥斯卡最佳视觉效果奖提名。©豆瓣', '伊万·麦克格雷格', '乔治·卢卡斯', 8, 95182, 'tt0121765', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2308393297.jpg', 0.3, 1.9, 21.8, 47.5, 28.5, '-0.111084,0.219736,-0.549097,0.246725,0.288768,-0.136146,0.194153,0.296551,-0.229154,-0.228887,0.298919,0.483861,-0.014199,-0.284479,0.549307,0.110725,-0.750600,-0.323834,0.116111,-0.440299,0.049592,-0.359254,-0.276091,-0.116917,-0.153148,-0.671708,0.628241,0.174493,0.180796,0.305625,0.245727,0.674090,-0.108050,0.017870,0.444083,0.054331,0.560982,-0.399412,-0.608642,0.578565,-0.312532,0.297851,-0.269921,-0.115760,0.198519,0.472020,0.302192,-0.335006,0.496386,-0.428680,0.040962,-0.222609,0.086176,0.021649,0.416339,-0.123323,-0.262857,0.226339,0.010429,-0.064443,-0.170545,-0.241346,-0.485604,0.237114,0.337038,-0.010543,-0.547662,-0.246747,-0.515410,0.083164,0.162030,-0.057640,-0.087145,0.855252,0.188939,0.011297,0.208630,0.059671,-0.299052,-0.044318,0.416005,-0.232136,-0.179751,-0.426527,0.193591,-0.497574,0.152975,-0.033893,-0.140034,-0.248018,0.392233,-0.055966,0.491899,0.553298,-0.514379,-0.122630,-0.734336,-0.261143,0.313043,-0.017334,0.110560,-0.804690,0.219767,0.144625,-0.038246,0.030284,0.089734,0.038715,0.279292,-0.339350,0.478864,0.553362,0.449128,-0.265297,0.333878,-0.141862,0.178548,-0.367161,0.057231,0.742306,0.268230,0.300588,0.191740,-0.011986,0.033324,-0.326423,-0.097266,0.041516', '1293572', '1297151', '2973528', '26627736');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297787', '同居蜜友', '喜剧', '家中三代经营牛杂店的少东蒋通菜（梁朝伟饰）于一次交通意外与泼辣的少棠（郑秀文饰）相识。原是冤家的两人酒后发生了关系。少棠与父亲闹翻又遭到公司上司夺权解雇，竟在医院与蒋通菜相遇，少棠欺骗通菜自己到医院堕胎，通菜大为紧张，见通菜为人不错，于是告之真相后握手言和，通菜也把她带了回家暂住。两人共渡了一个少棠误造的一个难关，感情倍增。可是通菜即将回来的正式女友（周丽淇饰）是两人的障碍，少棠不得不离开。可缘分让相爱的两人重逢了，又能否眷属呢？©豆瓣', '郑秀文', '马伟豪', 6.6, 9979, 'tt0286623', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p549923725.jpg', 1.2, 9.4, 56.6, 25.1, 7.8, '0.244918,-0.162677,-0.598926,0.369602,0.181190,-0.554317,0.559645,0.361823,-0.611298,-0.002492,-0.016591,0.759670,-0.382842,0.228084,0.204991,-0.093017,0.082231,-0.664208,0.286041,-0.161703,-0.172999,-0.439784,-0.006837,0.029956,-0.105775,0.062280,0.342385,0.147769,-0.036128,0.540261,0.443832,0.043716,-0.390874,0.599039,-0.271849,0.096681,0.006237,0.425195,-0.649878,0.007648,0.176037,-0.260527,-0.157751,-0.016760,0.155447,0.370007,0.516057,0.213069,-0.500609,-0.110495,0.202679,-0.030228,-0.075124,0.175014,0.317919,-0.001412,0.323473,0.464334,-0.267775,-0.050646,0.137539,0.102784,-0.416262,0.291721,0.097850,-0.169802,-0.570402,0.488803,-0.142266,-0.160979,0.082363,-0.342790,0.333488,0.626389,0.459317,0.439599,-0.139315,0.007378,-0.571326,-0.012040,0.906208,-0.014405,0.017064,0.462062,0.077422,-0.302933,0.102463,0.010074,-0.357758,0.305794,0.176193,0.035565,-0.220724,0.225785,-0.577929,-0.259763,-0.345460,0.068657,0.170287,-0.462331,0.214066,-0.475205,-0.148639,-0.501846,-0.541027,0.086190,0.281239,-0.174668,0.312617,-0.659077,-0.018911,0.149114,0.327505,-0.871827,0.667029,0.261039,0.233795,-0.245510,0.094237,0.003904,0.070460,0.130610,0.371878,0.275123,0.047293,0.106182,-0.338300,0.009479', '4145476', '25721544', '1308035', '6890343');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297819', '白气球', '剧情', '伊朗新年之前，小女孩纳西亚（艾达•莫哈默德哈尼 Aida Mohammadkhani 饰）随妈妈到集市购买过年用品，路过驯蛇人的摊位，发现众人围观，挤进去才发现他正在吆喝，要观众掏钱看蛇类表演，并贩卖肥大的金鱼。纳西亚很想买一只金鱼，但是因为家境贫寒，妈妈手里只有500图曼的过年钱，而一条鱼要100图曼，所以妈妈只得带着纳西亚回家。她本想用新年礼物跟妈妈讨价还价，但却被严词拒绝。失望的她只得拜托哥哥帮忙，结果哥哥说服了妈妈，把500图曼给了她。纳西亚把钱放进小鱼罐，兴冲冲地跑到养蛇人的摊位，准备满足心愿。然而事情在此突然发生了转机……本片获得第48届戛纳电影节金摄影机奖。©豆瓣', 'Aida Mohammadkhani', '贾法·帕纳西', 8.1, 7733, 'tt0112445', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p642741690.jpg', 0.5, 1.6, 19.2, 49.8, 29, '0.217904,-0.144790,-0.220441,0.122717,-0.005506,-0.558961,0.334954,0.193855,-0.167039,0.107817,-0.166262,0.564928,-0.188319,0.062690,0.299378,0.274815,-0.574731,-0.315461,0.496578,-0.081077,-0.058226,-0.201008,0.141022,-0.245937,0.023749,-0.226554,0.103920,-0.102911,0.230239,0.446999,0.259466,-0.061665,0.029732,0.592955,-0.039789,0.410683,0.065541,-0.158190,-0.151279,0.292343,-0.015577,-0.140887,-0.517649,0.163088,0.661035,0.195001,0.560144,-0.165711,0.196156,-0.012760,0.053168,-0.191171,0.118070,-0.096461,-0.133238,0.321123,0.274651,-0.074285,-0.222893,0.394842,0.256013,-0.219610,0.033826,0.335095,-0.083664,0.054754,-0.739792,0.196025,-0.093033,0.244540,0.205112,-0.589420,0.329703,0.273149,0.013031,0.279423,-0.148870,0.142131,-0.893359,0.073164,0.263494,-0.249388,0.383013,0.195666,-0.054538,-0.298546,0.541881,-0.115241,-0.213019,0.213786,0.382609,0.089871,-0.324138,-0.178421,-0.651570,-0.249918,-0.211231,-0.614740,0.089811,-0.528098,-0.301920,-0.362010,0.262228,0.068033,-0.001764,0.067028,0.185354,-0.242598,0.496618,-0.169109,0.131111,0.361297,0.661432,-0.216084,0.629040,-0.248525,-0.097758,-0.133555,-0.276991,-0.020785,-0.037349,0.239621,0.204119,0.143872,0.245732,-0.266262,-0.287036,0.331934', '1306505', '1293908', '1293511', '1432825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297841', '浮草', '剧情', '歌舞伎艺人岚驹十郎（中村雁治郎 饰）率领他的剧团来到志摩半岛的小镇，早年间他曾来此演出，并和当地的女子阿芳（杉村春子 饰）结合生下一子。多年来，他无论身在何处都不忘接济阿芳母子，虽然欣喜儿子阿清（川口浩 饰）的成长，却不愿让他知道这层父子关系，只以叔叔的身份陪伴在他的左右。剧团长时间驻留小镇，生意也从最初的火爆变得萧条。纵然人心惶惶，驹十郎却仍不愿带团离开。驹十郎在剧团的情人寿美子（京町子 饰）某天终于得知隐情，且恨且妒的她怂恿年轻女演员加代（若尾文子 饰）去勾引阿清，谁知两人却一见钟情……©豆瓣', '中村雁治郎', '小津安二郎', 8.6, 8714, 'tt0053390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173414954.jpg', 1, 0.5, 10, 45.3, 43.2, '-0.006559,-0.036338,-0.862867,0.469458,0.025775,-0.337256,0.441094,0.260813,-0.447707,-0.312709,0.281936,0.578498,-0.035911,0.239024,0.033885,0.202444,-0.061139,-0.479972,0.134962,-0.145462,0.078961,-0.131714,-0.135461,-0.078344,-0.154076,-0.056521,0.496027,0.089355,-0.057004,0.494612,0.405272,0.071493,-0.473572,0.397302,-0.081455,0.101537,0.028847,0.275752,-0.139268,-0.117139,-0.208213,-0.352138,-0.404959,-0.055548,0.300554,0.486939,0.656148,0.106053,-0.189472,0.161264,0.193337,0.027247,-0.004249,0.061050,0.345737,-0.204899,0.067836,0.325867,-0.383345,0.075157,-0.235781,0.099190,-0.338438,0.226615,0.249085,0.184618,-0.559859,0.536584,-0.146461,-0.331531,-0.163060,-0.414374,-0.072174,0.195309,-0.166553,0.248265,-0.029875,0.197753,-0.351509,0.308446,0.787697,0.098650,0.010557,0.194527,-0.101915,-0.420762,-0.161301,-0.146505,-0.577254,-0.106457,0.050475,-0.126709,-0.149304,0.067578,-0.216859,-0.022053,-0.306863,0.158566,0.277824,-0.241629,0.021758,-0.259381,-0.126161,-0.539212,-0.326124,0.227024,0.240596,-0.057726,0.672511,-0.752152,0.086790,0.478434,0.258012,-0.612994,0.505263,0.418369,-0.164600,-0.225533,-0.206177,0.421226,-0.031064,0.087096,0.120585,-0.032431,0.007959,-0.055845,-0.394107,0.005024', '35030151', '1301022', '3445516', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297862', '英雄本色2', '剧情', '第一部中，小马哥（周润发 饰）死在乱枪之下，宋子豪（狄龙 饰）和弟弟宋子杰（张国荣 饰）冰释前嫌，英雄的故事还在继续。警方怀疑宋子豪的恩师龙四（石天 饰）利用船厂做掩护，暗中操纵伪钞集团，派宋子杰去接近龙四的女儿小辉，做卧底，宋子豪为了弟弟的安全，不得不假释出狱，协助警方调查。其实，龙四对手下的犯罪行为并不知情，他被亲信高英培陷害，不得不逃亡纽约，女儿的被害，使他精神失常，在小马哥弟弟阿健（周润发 饰）的帮助和保护下，才渐渐恢复神智。出于道义，阿健放弃了经营多年的餐厅，同龙四共同返港。香港这边，宋氏兄弟几近艰险终于获得了高英培的信任，掌握了伪钞集团的犯罪证据，和阿健、龙四会和后，四人策划了火爆的复仇行动，也付出了鲜血甚至性命的代价。©豆瓣', '狄龙', '吴宇森', 8.4, 163482, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2597917153.jpg', 0.2, 1.2, 14, 46.5, 38.1, '-0.011271,-0.035565,-0.528692,0.488710,-0.064755,-0.287068,0.223320,0.236711,-0.360610,-0.250060,0.409348,0.506353,0.311983,0.154024,0.103272,-0.199491,-0.385383,-0.746771,-0.211646,0.153929,-0.111143,-0.695500,-0.217223,-0.120678,-0.223420,-0.164464,0.411883,0.215515,-0.107903,0.390591,0.386275,0.089732,-0.365678,0.315664,0.265715,0.038804,0.130661,-0.053549,-0.551649,0.118387,0.136398,-0.405497,0.093092,0.294458,0.148045,0.486761,0.509994,-0.105655,-0.040522,-0.362488,0.147700,-0.368990,0.071111,-0.018939,0.271368,0.088757,0.299468,0.584889,-0.366396,-0.050536,-0.064604,0.107098,-1.076628,-0.138736,0.396282,-0.256882,-0.719646,0.314490,-0.380166,0.097318,0.072486,-0.360858,0.393990,0.570256,0.285790,0.145364,-0.318019,0.040483,-0.448704,0.209748,0.657652,-0.104422,0.149380,-0.044241,0.089519,-0.174057,-0.109256,-0.257322,-0.041016,-0.035156,0.465258,-0.047779,-0.108444,0.093763,-0.270902,-0.301128,-0.310386,-0.028729,0.022045,-0.383836,0.234816,-0.425333,-0.156036,-0.201349,-0.078003,0.100624,0.035332,-0.463769,0.474964,-0.561930,-0.024722,0.439112,0.353956,-0.833488,0.221839,0.070151,0.062407,-0.240049,-0.173563,0.070454,0.161231,0.100708,0.317128,-0.111806,-0.022586,-0.180931,-0.228114,-0.062279', '26678784', '1304382', '1302110', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297863', '武状元苏乞儿', '喜剧', '广州提督之子苏灿（周星驰 饰）在考取武状元时，被人设计陷害沦为乞丐。因为丐帮四大长老杀了自己的教主，入主朝廷的天理教太乙真人四处迫害丐帮，加上丐帮帮主阵亡令打狗棒法失传，丐帮一时四分五裂群龙无首。在心仪苏灿的如霜（张敏 饰）的暗中帮助下，传功长老选中苏灿为丐帮接班人，传以打狗律 法要诀。苏灿学艺成功后，成为新任帮主，开始团结各地丐帮会员自强，共同奋力对抗天理教。太乙真人（徐少强  饰）欲拥兵自立，预谋在皇帝狩猎之时下手行刺，不料消息走露传到苏灿耳中。©豆瓣', '周星驰', '陈嘉上', 8.1, 352205, 'tt0100963', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1148052547.jpg', 0.2, 1.1, 22.2, 48.1, 28.5, '-0.155576,0.173194,-0.508815,0.388080,0.020182,-0.087135,-0.083617,0.388693,-0.739122,-0.379156,0.232005,0.436763,0.063377,0.033869,0.335393,-0.012941,0.287868,-0.703594,-0.040675,-0.378075,0.208948,-0.072137,0.037681,-0.169479,-0.242444,-0.335414,0.765957,0.258971,-0.428811,0.276175,0.247007,0.138401,-0.235646,0.177542,-0.017049,0.059445,0.394598,-0.201973,-0.311921,0.282723,-0.358227,-0.303144,-0.141660,-0.158249,-0.449041,0.463236,0.072297,-0.301024,0.008044,-0.389298,0.050037,-0.251557,-0.071999,0.145705,0.881623,0.397394,0.189231,0.448052,-0.018182,0.055756,-0.190468,0.124197,-0.381945,0.023088,0.458382,-0.133552,-0.334704,0.497147,-0.284103,0.159291,-0.196270,-0.349081,0.181846,0.503756,0.117124,-0.276522,-0.057465,0.026969,-0.497948,0.508002,0.598682,-0.239150,0.330089,-0.499892,0.790502,-0.057266,0.384679,-0.694132,0.160158,-0.123267,0.613808,-0.362020,0.411986,0.451384,-0.007946,-0.276060,-0.387710,0.363299,-0.074345,0.048070,0.032439,-0.563681,-0.106839,0.415048,0.068843,-0.342639,0.378240,-0.243634,0.656526,-0.867821,0.064275,-0.002716,-0.096207,-0.768592,0.315697,0.044019,0.123219,-0.178237,-0.519378,-0.031798,0.657138,0.541034,0.147943,0.003546,-0.158663,-0.306004,-0.064344,-0.386517', '1295987', '6425116', '1295469', '1307914');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297866', '上海正午', '喜剧', '故事发生在清朝，蓓蓓公主（刘玉玲 饰）由皇帝主婚，必须嫁给皇族亲王，公主心里十万分的不愿意。这时，不怀好意的英文教师安德鲁看出了公主心意，怂恿她出逃美国。公主出逃后，安德鲁留下了一封勒索信给皇帝，所要赎金十万金条。这下皇帝慌了神，马上派出三名大内高手带上赎金前往美国营救公主。大内侍卫黄强（成龙 饰）在公主出逃时曾见过她，不过并没能拦下她，对公主一直不能忘怀。于是，他请求当翻译的叔叔为他说请，让他参与营救行动。侍卫队长批准了他的请求，一行人正式踏上了美国。©豆瓣', '成龙', '汤姆·戴伊', 6.5, 28979, 'tt0184894', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p900363862.jpg', 1.3, 9.7, 59.4, 23.3, 6.2, '-0.199527,0.321628,-0.417641,0.754811,0.069259,-0.263516,0.479347,0.084384,-0.650926,-0.299412,0.463849,0.427686,0.017701,-0.245018,0.513760,-0.023698,-0.558243,-0.239741,-0.141630,-0.283269,-0.098941,-0.343203,0.453637,-0.455112,-0.279758,-0.555446,0.375223,-0.118698,0.248442,0.457091,0.427584,-0.075606,-0.113026,0.570897,-0.038011,0.192667,0.381253,-0.108376,-0.232558,0.403726,0.026484,-0.368732,-0.208334,0.296032,0.217300,0.346668,0.039169,-0.588756,0.276745,-0.184376,0.053816,-0.196527,0.181730,0.264455,0.173727,0.009169,0.355663,0.149392,-0.054216,-0.240162,-0.062155,0.037473,-0.187654,0.215270,-0.083533,0.145901,-0.831251,-0.095119,-0.561982,0.330840,0.112141,-0.304287,0.356224,0.444817,-0.050617,-0.188540,0.046522,0.055679,-0.620607,0.447858,0.786803,-0.077732,0.322743,-0.342663,0.085036,-0.573392,0.357990,-0.243985,-0.237149,0.424919,0.246677,-0.202208,0.067550,-0.142328,0.032441,-0.606654,-0.647500,-0.065242,0.302306,-0.798122,0.374632,-0.097404,0.215511,0.010070,-0.088196,-0.053462,0.505080,0.012118,0.440657,-0.670703,0.047744,0.257111,0.554254,-0.973365,0.598804,0.139456,-0.327545,-0.307277,0.096545,-0.229414,0.140012,0.473569,0.120797,0.358140,0.248295,-0.528437,-0.214716,-0.150563', '1297710', '1421278', '1395445', '1306249');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297880', '芙蓉镇', '剧情', '本片分上下两集，讲述了位于湘、粤、桂三省交界处的芙蓉镇上，人称“芙蓉姐”的漂亮女人胡玉音（刘晓庆）在“四清运动”及“文化大革命”中的遭遇。1963年，凭着热情周到的服务，胡玉音与丈夫桂桂（刘利年）经营的米豆腐摊子前渐渐成为早市上最热闹的一道风景，加上夫妻俩省吃俭用，手中积攒了一 笔数目可观的财富。镇党支书也是胡玉音干哥的黎满庚（张光北）、粮站主任谷燕山（郑在石）及乡邻们都为他们高兴。当他们盖好新房准备日子更上一层楼时，迎上“四清运动”，一直嫉妒胡玉音的原国营饮食店经理、今县商业局科长李国香（徐松子）与二流子王秋赦（祝士彬）联手，趁机将她定性为“反革命五类分子”中的“富农婆”，将之派去与原县文化馆馆长、今被人称作“秦癫子”的“右派”秦书田（姜文）一起清扫大街，桂桂身亡。运动中黎满庚昧着良心将胡玉音背叛，谷燕山则一直以老革命军人的标准诚实做人。1966年，“文化大革命”开始，世道的荒谬从不停调换角色的李国香与王秋赦两人身上便可窥见。一起扫街时，胡玉音将自己的悲惨遭遇归罪于秦书田，后者曾在她与桂桂成亲之时唱了后被认为反革命的贺喜歌、在她新房子建成之时写了后被认为反革命的贺喜联。对于胡玉音的怨恨，秦书田并不多做辩解，相反时常暗中将她帮助。慢慢地，两人生出感情，计划着成为一家人好好生活，但前路充满血风腥雨。而在他们最艰难时，谷燕山从没忘伸手一帮。', '刘晓庆', '谢晋', 9.2, 112478, 'tt0087301', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2174804034.jpg', 0.1, 0.2, 4.3, 28.7, 66.6, '0.286507,0.158908,-0.623037,0.585314,0.009789,-0.392875,0.438696,0.175893,-0.421179,-0.111244,-0.117146,0.275969,-0.131250,0.279426,0.289985,-0.333448,-0.090544,-0.696672,-0.291684,-0.034841,-0.191897,-0.405566,0.079135,-0.033380,-0.473971,0.123457,0.040845,0.026582,0.004459,0.443127,0.337884,0.156575,0.058876,0.296849,-0.162647,0.088473,-0.089100,-0.110620,-0.254943,0.045088,0.188055,-0.470038,-0.156666,-0.137638,0.121977,0.216883,0.606614,-0.183024,-0.073047,-0.237371,0.235442,0.016851,0.067895,0.279763,0.351711,0.154792,0.115304,0.181020,-0.430591,-0.099239,0.087940,-0.236757,-0.416695,0.043249,0.093586,-0.093472,-0.693386,0.180331,0.079394,0.139169,0.048661,-0.342336,0.365645,0.259097,0.250450,0.268288,-0.225415,-0.005003,-0.443789,0.373979,0.581389,0.053348,0.135661,0.065764,-0.164819,-0.276886,0.116980,-0.054306,-0.210772,-0.127727,0.227286,-0.162685,0.111983,0.130355,-0.492354,-0.207658,-0.068219,-0.110940,0.183082,-0.126167,-0.166603,-0.389701,-0.218093,-0.429975,-0.241849,0.059959,0.018199,-0.298840,0.679963,-0.631259,0.185504,0.150926,0.216614,-0.437528,0.610524,0.035665,0.335745,-0.006106,-0.109181,-0.126801,0.097799,0.430525,0.555141,0.506207,-0.397722,-0.049213,0.005176,0.521657', '21360412', '5977789', '26730542', '1293607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297889', '龙兄鼠弟', '喜剧', '多年前科学家进行了一项创造完美人类的饰演，没想到实验过程中的细胞分裂不均匀导致了这个实验只成功了一半，另一半则完全失败。科学家创造出来的这对双胞胎兄弟一个是完美人类的典型――德智体美全面发展的高大的朱利斯（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）；另一个则是人类所有缺点的集合体――小矮个文森（丹尼•德维托 Danny DeVito 饰）。兄弟两一出世就被分离，朱利斯被科学家送到南海的一个小岛上抚养长大，而弟弟则在孤儿院度过了他的童年。直到兄弟两已过不惑之年，他们才知道了对方的存在。朱利斯与未曾谋面的兄弟文森重逢后，两兄弟决定踏上寻找亲生母亲之路。但是这时，一场意外给他们惹来了杀身之祸。©豆瓣', '阿诺·施瓦辛格', '伊万·雷特曼', 6.8, 4667, 'tt0096320', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2200099609.jpg', 0.6, 5.2, 57.4, 29.6, 7.1, '0.199635,-0.137496,-0.680528,0.664785,-0.235391,-0.596596,0.830146,-0.149987,-0.543495,-0.160091,0.171866,0.862413,-0.069553,0.189668,0.182296,0.035411,-0.213999,-0.587325,-0.257026,-0.067591,-0.454423,-0.325845,-0.391207,-0.111526,-0.192114,-0.196336,0.696181,-0.034583,-0.071755,0.378157,0.089316,0.115777,-0.214281,0.195817,-0.150389,0.405183,0.350923,0.038669,-0.353522,0.291985,0.033597,-0.021750,0.146508,0.244970,-0.298815,0.347547,0.869614,-0.369524,-0.164444,-0.444337,0.403452,-0.380420,-0.172051,0.107828,0.309487,0.063666,0.281358,0.235941,0.071324,-0.094582,-0.015416,-0.238500,-0.996586,-0.156577,0.099244,-0.047285,-0.586449,0.543143,0.074212,-0.203828,-0.072985,-0.412986,0.194686,0.519943,0.446519,0.340959,-0.407805,0.063796,-0.357952,0.231027,0.689283,-0.265376,-0.377111,0.454480,-0.154122,-0.596534,0.010126,-0.445457,-0.348123,0.102042,0.431271,0.201603,-0.081359,0.327717,-0.701311,0.103188,-0.494848,-0.110167,0.147097,-0.389070,-0.155164,-0.218214,-0.074589,-0.285210,-0.493655,0.282090,0.009909,-0.433840,0.869977,-0.687543,0.201369,0.527579,0.194310,-0.528659,0.632109,0.119873,0.404747,-0.535667,0.134751,0.152178,-0.030199,0.204173,0.151386,0.329818,-0.041551,0.026343,-0.646988,0.327093', '26678784', '25928048', '1308585', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297894', '处女之死', '剧情', '一把冷冷的男声带来了故事的开始。青春期对里斯本一家的5个豆蔻女儿们来说，是一道迈不过的槛。首先自杀的是最小的女儿赛西利娅（汉娜霍尔 Hanna R. Hall 饰）。她变得脆弱低落，想结束生命，这一切都没有道得明的原因。父母以为，让她去和男孩交往，会改善情况。然而，赛西利娅还是选择了告别人生。和男孩交往频繁，性情放纵的，是另一个女儿勒克斯(克尔斯滕·邓斯特 Kirsten Dunst 饰)。勒克斯认识花花公子特里普，被和他发生了关系，却最终被特里普抛弃。里斯本父母害怕再次失去女儿，于是失去了理性。他们把四个女儿困在家中，给她们最严密的保护。然而自杀的惨剧就像疫情一样，迅速的扩散。©豆瓣', '克斯汀·邓斯特', '索菲亚·科波拉', 7.5, 19544, 'tt0159097', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p701336955.jpg', 0.7, 4.1, 32.6, 45.8, 16.8, '0.283379,-0.110317,-0.550442,0.543779,-0.216686,-0.382639,0.939992,0.081256,-0.398884,-0.307115,-0.009752,0.952123,-0.205616,0.212999,0.150337,0.065105,-0.180394,-0.691111,-0.009385,0.054832,-0.292820,-0.632449,0.136389,-0.199697,-0.088550,-0.281273,0.563983,-0.094426,-0.197319,0.440882,0.502990,0.354063,0.136187,0.538673,-0.145626,0.142891,-0.070726,-0.188547,-0.160703,0.082660,0.129913,0.159681,-0.100297,0.414447,0.261365,0.438747,0.596601,-0.152500,-0.146520,-0.073642,0.290422,-0.258140,0.014995,0.319535,0.280380,-0.059014,0.208222,0.024369,-0.306040,-0.302189,0.152352,-0.091002,-0.569186,0.233524,0.369919,-0.044124,-0.699755,0.226671,-0.069788,-0.184680,0.262130,-0.235106,0.215281,0.485541,0.313707,0.474364,-0.242450,-0.156860,-0.424826,-0.062362,0.846099,-0.083615,-0.472592,0.448140,-0.437086,-0.397158,-0.061949,-0.279576,-0.442945,0.037436,0.380543,0.076569,-0.272233,0.414088,-0.399649,-0.202851,-0.255517,-0.118052,-0.046015,-0.644946,-0.047708,-0.130476,-0.253485,-0.323950,-0.475665,0.041663,-0.233276,-0.275168,0.749231,-0.807492,0.333484,0.512207,0.462382,-0.583963,0.542506,0.274253,0.304253,-0.145247,0.217748,0.463413,-0.020144,-0.058237,0.084827,0.188397,-0.103590,-0.099715,-0.252677,0.624802', '30162520', '25721544', '4275444', '1303036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297907', '西部世界', '科幻', '在遥远的未来，一座巨型高科技成人乐园Delos建成，其中有西部世界，罗马世界，中世纪世界三大主题版块的机器人世界，它提供给游客杀戮与性欲的满足，而这座巨大机械乐园的后台监控渐渐失去了对机器人的控制，游客被机器人杀死，所有想逃离者都被锁定……', '尤·伯连纳', '迈克尔·克莱顿', 7.2, 10110, 'tt0070909', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2359950530.jpg', 0.9, 4.6, 42, 40.7, 11.9, '0.091180,0.570027,-0.961913,0.464154,-0.251539,0.647896,0.872676,-0.246624,-0.310335,0.221244,0.153046,0.873022,-0.068639,-0.053992,0.166307,-0.072213,-0.120840,-0.447321,-0.319811,-0.303526,-0.463251,-0.409599,-0.510203,-0.723949,0.106124,-0.763627,1.156524,0.264729,-0.161116,-0.201999,-0.419551,0.199916,-0.399714,0.391583,-0.356809,-0.254216,0.194323,-0.319552,-0.164545,0.456376,-0.844656,0.409529,0.362080,0.388885,-0.652254,-0.229737,0.952116,-0.592473,-0.179209,-0.566276,0.256616,-0.251536,-0.085272,-0.309833,0.472999,0.052464,-0.148514,0.023202,-0.119642,0.170865,0.308060,-0.411845,-0.783081,-0.321684,0.290578,-0.054597,-0.105274,0.383836,0.188040,-0.177860,-0.091932,-0.140537,0.338662,-0.087773,0.716047,0.672148,0.054746,0.353325,-0.401092,0.146758,0.515386,-0.292690,-0.811555,0.197951,-0.398338,-0.370793,-0.375857,-0.365635,-0.417556,-0.157570,0.437623,0.248340,-0.360605,0.423982,-1.181110,0.206477,-0.183813,-0.576883,0.123718,-0.588401,-0.244310,-0.858785,-0.080537,0.193271,0.496779,0.079147,0.183054,-0.131156,1.074939,-0.831879,0.434083,0.804937,0.669826,-0.517359,0.918303,-0.584482,0.218373,-0.413371,0.089390,0.443994,0.107231,0.805310,-0.219130,0.115600,-0.323916,-0.024542,-0.592325,0.845527', '26290398', '1458894', '2977870', '10439358');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297909', 'A计划', '喜剧', '上世纪初，猖獗的香港海盗屡屡劫持商船，考虑到各国商家的投资信心会因此减少，继尔香港国际贸易中心的地位可能会不保，当局改编水师，成立了一支特警小队负责海上治安。队长马如龙（成龙）执行公务时遭人陷害，愤而辞职。海盗头目罗三炮（狄威）抓走官兵家眷做人质，当局决定利用内线周永龄从中调停。因为早知周永龄与海盗勾结，马如龙自告奋勇拯救人质，他重组水师，制定了A计划，期望通过与上司洪天赐（元彪）及好兄弟卓一飞（洪金宝）作里应外合，将海盗一网打尽。©豆瓣', '成龙', '成龙', 8.1, 133284, 'tt0085127', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2345955373.jpg', 0.2, 1, 19.6, 51.5, 27.7, '-0.075741,-0.129984,-0.459818,0.357783,0.132911,0.015880,-0.162367,0.125025,-0.674508,0.024394,0.237729,0.427968,0.448712,-0.298915,0.497896,-0.241393,-0.519568,-0.650322,-0.146837,-0.122380,0.120340,-0.612748,-0.252028,-0.678751,0.064304,-0.302465,0.553196,0.182042,-0.328931,0.364012,0.000712,0.022083,-0.263591,0.206937,0.428346,-0.018798,0.397677,-0.359641,-0.707699,0.105898,-0.436468,-0.313706,0.105676,-0.295651,0.170998,0.598709,0.444509,-0.105454,-0.070857,-0.503258,0.000482,-0.541935,0.154031,-0.210693,0.662969,0.261989,-0.080029,0.353119,-0.065789,-0.223661,-0.212688,-0.107209,-0.564929,-0.095830,0.182237,-0.230963,-0.370484,0.066760,-0.219168,0.587715,-0.071970,-0.125180,0.194396,0.653308,0.269081,-0.173180,0.067350,0.253343,-0.532051,0.393333,0.871496,-0.228698,0.276394,-0.777648,0.193052,-0.205839,0.165983,-0.447537,-0.022226,-0.100692,0.427365,-0.436754,0.042672,0.151227,-0.266119,-0.168812,-0.585307,0.222223,0.019145,-0.080415,0.407406,-0.664988,0.132175,0.182105,0.260286,0.297448,0.353293,0.112878,0.594352,-0.547181,-0.309538,0.664517,0.719031,-0.887548,-0.043211,0.079387,0.247956,-0.497839,-0.101197,-0.402491,0.278024,0.126909,0.321335,-0.158372,-0.089442,-0.467754,0.385951,-0.605066', '1484760', '1307106', '26616145', '1307914');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297920', '小孩与鹰', '剧情', '英国男孩比利•卡士柏（David Bradley 饰）生活在一个破碎的工人阶级家庭里，父亲离家出走，除母亲和哥哥外，比利也要打工贴补家用。在学校里比利捣蛋或者逃课看漫画书，从中找寻这个年龄应有的快乐。某天他在农场高墙上发现一个鹰巢，于是从书店偷回训练猎鹰的教材，按照书本所写养了一只名为凯斯的小鹰……本片荣获1971年BAFTA电影奖最佳导演、最佳电影提名、最佳男配角、最佳新人、最佳编剧以及1970年卡洛维法利国际电影节水晶球奖。©豆瓣', '大卫·布拉德利', '肯·洛奇', 8.6, 8986, 'tt0064541', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1665724556.jpg', 0.2, 0.5, 8.4, 48.7, 42.1, '-0.201686,-0.202827,-0.305012,0.685843,0.072100,-0.351161,0.436005,0.178605,-0.177685,-0.257241,0.079233,0.979213,-0.000243,0.368627,0.240418,0.007079,-0.435934,-0.710112,-0.262593,-0.307893,-0.024006,-0.340617,-0.486887,-0.104073,-0.176313,-0.146959,0.791578,-0.404801,0.024730,0.476577,0.408573,-0.306406,-0.012695,-0.261077,-0.124125,-0.086000,0.382586,0.129759,-0.222409,0.580798,0.126563,-0.266899,-0.278753,-0.180966,0.342993,0.089210,0.803553,-0.096714,0.022032,-0.068855,0.737886,-0.091282,-0.352803,-0.101303,0.333497,-0.187996,0.284373,-0.098183,-0.056128,0.291803,-0.037778,-0.427053,-0.600196,-0.225716,0.041971,0.124939,-0.594800,0.482012,-0.008158,0.205810,0.228022,-0.223718,0.249075,0.194757,0.052632,0.367504,-0.346085,0.086503,-0.200411,0.802527,-0.019157,-0.192773,-0.192206,0.236561,-0.197430,-0.490731,0.042011,-0.074495,-0.545640,0.042224,0.421306,-0.168659,-0.120074,-0.198900,-0.480906,0.073744,0.077661,-0.377262,0.046079,-0.161628,-0.204150,-0.974538,0.008426,-0.081636,-0.084664,-0.321695,-0.001248,-0.449938,0.809708,-0.642336,0.298497,0.601364,0.062260,-0.135592,0.905018,-0.241181,0.217411,-0.264367,-0.119028,0.063166,-0.025982,0.287406,-0.268335,0.247198,0.117324,-0.574824,-0.420172,0.487392', '30397916', '1297368', '22265121', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297923', '十字街头', '剧情', '在动乱的年代下，数万年轻人被抛在了人生的十字路口，事业、爱情、理想，如此等等，都成为他们不得不去面对与抉择的关键。而他们的每一次选择，也将影响各自的命运。黄浦江畔，滚滚江水是彷徨着不断的愁绪。毕业于华东大学的小徐找不到工作，一度起了轻生的念头，关键时刻被老赵（赵丹 饰）救下。老赵和小徐、阿唐、刘大哥都毕业于名门学府，可是空有一身才学却无法在乱世找到自己的位置。绝望的小徐踏上归乡之途，刘大哥奔赴战场。老赵和阿唐则分别在报馆和商店找到一份工作。在一次冲突中，老赵结识了在纱厂当教练员的姑娘杨芝瑛（白杨 饰），爱情之花艰难地绽放。十字街头，年轻人们摸索寻找着未来的路……©豆瓣', '赵丹', '沈西苓', 7.8, 5407, 'tt0195260', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1995834956.jpg', 0.3, 1.4, 24.4, 54, 19.8, '-0.032456,0.159063,-0.722400,0.624014,-0.190752,-0.530145,0.534374,0.088786,-0.436027,-0.165353,0.099703,0.588879,-0.058335,0.535027,0.128651,-0.424552,-0.049232,-0.718328,-0.125720,-0.163619,-0.379215,-0.483494,-0.262803,-0.108747,-0.304200,0.056490,0.845486,0.458618,-0.341394,0.312230,0.385815,0.101494,-0.111121,0.529553,-0.469756,-0.077136,-0.066588,0.254578,-0.502718,-0.040905,0.216824,-0.477632,-0.331531,-0.085033,0.201289,0.112454,0.931674,-0.159722,0.074283,0.006786,0.439618,-0.173462,0.083242,-0.046620,0.287256,0.112020,0.011710,0.063338,-0.092176,0.004691,0.281614,-0.271278,-0.536274,-0.131993,0.251690,0.174652,-0.956219,0.451722,0.043854,-0.230145,0.230467,-0.564948,0.185565,0.253905,0.308056,0.483575,-0.367290,0.040561,-0.497006,0.285679,0.744936,0.218140,-0.198032,0.114236,-0.073257,-0.483825,-0.117678,-0.068776,-0.516154,-0.178361,0.522523,0.036407,-0.147799,0.254885,-0.456849,0.048651,0.000201,-0.284203,0.073390,-0.426458,-0.144782,-0.351028,0.089296,-0.273629,-0.323325,0.381766,0.184138,-0.147319,0.800190,-0.787433,0.162397,0.474875,0.169615,-0.472989,0.864946,0.230645,0.298017,-0.244462,0.013937,0.319272,-0.207413,0.637872,0.209342,0.302914,-0.461227,0.102396,-0.477884,0.584150', '2080130', '1308609', '26021055', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297924', '水浒传之英雄本色', '剧情', '八十万禁军教头林冲（梁家辉饰），为人极为正直，深得朝庭器重。且古道热肠，甚爱结交江湖豪侠，常常以武会友，是名副其实的一个"武痴”，唯一的缺点就是为人处事过于率直，不懂官场丑恶，常得罪人而不自知。冲爱妻（王祖贤饰）常常相劝，想丈夫脱离险恶官场，但冲决心为朝庭效力，无奈，冲妻只好望冲带眼识人。一日，冲在五台山巧遇花和尚鲁智深（徐锦江饰），两人不打不相识，越谈越投机。这时，林夫人被奸臣高逑的儿子高衙内（单立文饰）调戏，冲本欲教训高衙内，被高逑手下陆谦暗中提醒，才未惹出祸事。怎奈，好色的高衙内和奸险的陆谦为得到林夫人，暗中布下陷阱，把冲逼上梁山……...©豆瓣', '王祖贤', '陈会毅', 7.3, 31923, 'tt0105400', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167120607.jpg', 0.5, 3.1, 39.7, 43.7, 13.1, '0.393382,-0.219983,-0.153028,0.439912,-0.259886,0.022932,0.153792,0.311712,-0.629203,-0.156106,0.297597,0.412451,-0.265357,-0.277183,-0.038429,-0.321392,0.263485,-0.374845,-0.248382,0.026046,0.266042,-0.405994,-0.111356,-0.146679,-0.626433,-0.147333,0.213602,0.105782,-0.146891,0.224522,0.325291,0.416956,-0.004083,0.523659,-0.319125,-0.053089,-0.095926,0.072987,-0.082832,-0.166374,0.077053,-0.386056,-0.326693,-0.124748,-0.152835,0.201671,0.202977,-0.298538,-0.069242,-0.282563,0.350047,-0.402579,-0.052386,0.047370,0.176076,-0.147065,0.045189,0.247729,0.024331,0.066455,0.041827,0.019307,-0.351533,-0.000851,0.330629,-0.429504,-0.575332,0.249784,-0.139637,-0.327304,-0.067655,-0.021777,-0.055737,0.005833,0.221594,-0.026331,0.138908,0.079004,-0.404527,0.111557,0.391258,0.209310,0.186577,0.143443,0.015492,-0.256630,0.659072,-0.465510,-0.257435,-0.253175,0.329919,-0.304600,0.031753,-0.009334,0.065539,0.047508,-0.188215,0.482201,-0.085319,-0.406351,-0.346033,-0.095868,-0.324674,-0.490004,-0.026120,-0.049495,0.097929,-0.083209,0.605861,-0.586054,-0.248350,0.221301,0.065152,-0.841989,0.880923,0.248005,-0.148677,-0.364668,-0.113521,-0.046588,-0.025441,-0.227109,0.107062,0.142674,-0.328164,-0.681927,-0.028741,0.105834', '1421278', '1303674', '5294324', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297929', '异形3', '动作', '经过长时间的飞行，蕾普莉（西格妮•韦弗 Sigourney Weaver　饰）搭乘的飞船并没有飞回地球！飞船返航途中发生意外，低温休眠舱在母船爆炸前脱离主船，掉进了一个黑暗、寒冷的星球。除了残存的主教外，只有蕾普莉一人生还。这里是地球的一个外星废弃矿井，现在成了一个管制危险犯人的监狱。蕾普莉在医生的救助下恢复了健康。随着蕾普莉的到来，这里的犯人开始一个一个被神秘杀害。当局以为是犯人内部的犯罪，然而蕾普莉隐隐知道没这么简单。当她找出主教的残体连接上电脑查看飞行记录后，证实了她的想法：异形来了。©豆瓣', '西格妮·韦弗', '大卫·芬奇', 7.3, 93104, 'tt0103644', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1593615176.jpg', 0.7, 5.1, 39.8, 39.6, 14.8, '0.625633,0.276398,-0.843993,0.443993,-0.057511,-0.161187,1.291892,-0.013909,-0.024700,-0.047010,0.244618,0.501507,-0.200655,-0.079837,0.109942,0.224872,-0.587545,-0.334769,-0.143532,-0.519319,-0.661803,-0.701125,-0.411280,-0.077400,0.061934,-0.584562,0.347712,0.118155,-0.035208,0.337394,-0.076734,0.151193,-0.149125,0.451648,-0.252413,-0.076537,0.240433,-0.259186,0.176981,0.432749,0.027671,0.007876,0.219010,0.350590,0.044044,0.553705,0.864718,-0.439044,0.055121,-0.054415,0.014687,-0.239617,0.012811,-0.226562,0.659753,-0.276048,-0.164798,-0.075762,-0.126632,0.016744,0.187300,0.036308,-0.625146,-0.076242,-0.552142,0.166281,-0.361749,0.000500,-0.300232,0.041944,-0.026114,-0.480265,0.315217,0.683119,-0.003887,0.456311,-0.295712,0.217968,-0.641708,0.070285,0.638755,-0.159890,-0.567683,0.542193,-0.275737,-0.576846,-0.001704,-0.172771,-0.388985,-0.360801,0.513656,-0.211992,-0.315740,-0.042781,-0.403723,0.128388,-0.706066,-0.408262,-0.430507,-0.126655,-0.396404,-0.526121,0.015467,-0.023444,-0.234768,0.121455,-0.347699,-0.324809,0.427702,-0.629978,0.563338,0.698001,0.264219,-0.462307,0.605826,-0.134007,0.196557,0.293698,0.092549,0.359021,0.214059,0.804487,0.007977,0.591418,0.198369,-0.124722,-0.574276,0.211415', '20451118', '1578663', '21619567', '2977957');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297946', '捉鬼敢死队2', '喜剧', '捉鬼敢死队员们又一次拿起武器在曼哈顿与恶魔决斗，在纽约城一场小战争后，敢死队发现一个千年恶魔准备重返地球并对曼哈顿不怀好意，而且通过他的王国---曼哈顿艺术博物馆进行破坏行动，现在只有捉鬼敢死队为了拯救纽约城与恶魔决斗一场……', '比尔·默瑞', '伊万·雷特曼', 6.6, 4436, 'tt0097428', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p785323639.jpg', 1.6, 7.9, 56.9, 24.4, 9.2, '-0.284287,0.020053,-0.461224,0.370499,-0.085105,-0.033431,0.836154,-0.527928,-0.041644,-0.063212,0.357008,0.665636,-0.299348,-0.044986,0.032206,-0.277591,-0.544483,-0.677435,-0.205203,-0.050419,-0.388593,-0.008179,-0.492348,-0.283593,0.250907,-0.352493,0.631225,0.084206,-0.444851,0.320447,0.330243,0.188884,-0.393587,0.190250,-0.187093,-0.744126,-0.066609,0.032153,-0.668062,0.491944,-0.181535,0.248662,-0.659964,0.197263,-0.049777,0.063963,0.935264,-0.957758,0.107937,-0.731556,0.027530,-0.543693,-0.156102,0.033756,0.461939,-0.222210,-0.222922,0.055117,0.296606,-0.064459,0.088113,-0.385062,-0.678786,0.230627,-0.241861,0.186051,-0.275161,0.408218,0.079912,0.586154,0.169908,-0.111000,0.174480,0.646506,0.703630,0.386462,-0.199564,-0.172562,-0.616005,-0.064447,0.979609,-0.219068,0.112123,0.174935,0.389848,-0.711143,0.053108,-0.213305,-0.114149,-0.048794,0.200232,-0.370524,-0.149287,0.360785,-1.025951,-0.169933,-0.105985,-0.349525,0.209114,-0.607311,0.187439,-1.111750,0.053350,0.189030,0.116267,0.412008,0.292865,0.047430,0.290018,-0.763392,0.446939,0.916083,0.271522,-0.476705,0.298576,-0.050838,-0.087016,-0.496043,-0.192029,0.109285,0.491557,0.834998,0.433866,0.021709,0.011704,-0.227906,-0.150966,0.700631', '1306809', '11541282', '2159244', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297965', '窈窕淑女', '剧情', '第三十七届(64年)奥斯卡最佳影片《窈窕淑女》获十三项提名夺得最佳影片、最佳导演、最佳男主角、最佳彩色片摄影、最佳彩色片美工、最佳彩色片服装设计、最佳音响、最佳改编音乐八项大奖。卖花女伊莉莎.杜利特尔，长得眉清目秀，聪明乖巧，但出身寒微，家境贫寒。她每天到街头叫卖鲜花，赚点钱补贴家用。一天，伊莉莎低俗的嗓音引起了语言学家希金斯教授的注意，教授夸口只要经过他的训练，卖花女也可以成为贵夫人。伊莉莎觉得教授说的话对她是一个机会，就主动上门请求教授训练她。教授的朋友皮克林和他打赌，如果让伊莉莎以贵夫人的身份出席6个月后将举办的大使游园会而不被人识破真相，那么皮克林愿意承担一切试验费用和伊莉莎的学费，这激起了教授的斗志，希金斯欣然接受了挑战。他是不甘示弱的，他从最基本的字母发音开始教起。希金斯是个精力旺盛和讲究科学的学者，对每一感兴趣件事都能废寝忘食。他胸怀坦荡、丝毫不怀任何恶意，但他又象孩子一样，毫不顾及他人的感情，对伊莉莎严加训练。有一次，希金斯带伊莉莎去参加母亲的家宴时,年轻的绅士弗雷迪被伊莉莎的美貌和谈吐自若的神情深深打动,一见倾心,竟然丝毫也认不出她就是曾经在雨中向他叫卖的肮脏的卖花姑娘不。希金斯已经40多岁，还未结婚，他从来看不上年轻姑娘，可现在在生活上竟然离不开伊莉莎了。他的衣服饮食和约会安排，全凭伊莉莎照料。然而使伊莉莎气恼的是希金斯简单粗暴的脾气。他教她温文尔雅的用语，却从不用温文尔雅的态度对待她。6个月后，希金斯满怀信心地带伊莉莎和皮克林一起出席希腊大使举办的招待会。伊莉莎是以皮克林上校的养女的身份参加这次大使的招待会的，她全力以赴，谈笑自若，风度翩翩，光彩照人。当她', '奥黛丽·赫本', '乔治·库克', 8.2, 98042, 'tt0058385', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p842376184.jpg', 0.3, 1.4, 17.8, 48.4, 32.2, '0.160601,-0.090381,-0.502072,0.520086,-0.569389,-0.270156,0.456975,-0.084179,-0.369353,-0.264262,0.199292,0.868363,-0.230654,0.079469,0.187692,0.040485,-0.232390,-0.556842,-0.132060,-0.052222,-0.020235,-0.597235,0.073567,-0.134925,-0.101962,-0.307491,0.299284,-0.261498,-0.198186,0.636079,0.382921,-0.026737,0.395267,0.362115,-0.178017,-0.152094,0.054115,0.071023,-0.107098,0.334119,0.210591,-0.101306,-0.326748,0.218458,0.217075,0.466712,0.415663,-0.140852,-0.109529,0.239242,0.501524,-0.253965,0.145486,0.287937,0.118622,-0.109042,0.226048,0.226815,-0.126550,0.036606,0.010208,-0.284633,-0.608132,0.116720,0.026174,0.217773,-0.513742,0.439802,-0.200714,-0.042822,-0.067451,-0.238329,0.176512,0.137045,0.110038,0.246800,-0.043908,0.047932,-0.397503,0.375259,0.440656,0.174474,-0.300735,0.397779,-0.318579,-0.511633,0.246891,-0.485066,-0.489212,0.171395,-0.042817,-0.074564,0.003907,-0.044313,-0.228499,-0.109890,-0.137999,-0.111405,0.040977,-0.438078,-0.047305,-0.561062,-0.050444,-0.530960,-0.298277,-0.093555,0.229425,-0.364237,0.846220,-0.877482,0.063118,0.424580,0.266014,-0.436516,0.729547,0.189556,-0.037994,-0.144762,-0.275942,-0.037570,0.012671,0.094048,0.059424,0.615582,0.300611,-0.317964,-0.112791,0.360260', '1292720', '35144311', '1292219', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297970', '蝙蝠侠', '动作', '在罪恶横行的高汉市，有一个令罪犯们心惊胆颤的名字：蝙蝠侠。蝙蝠侠（迈克尔•基顿 Michael Keaton 饰）穿梭于最黑暗的角落，四处打击罪恶。在一次打击罪恶的行动中，蝙蝠侠令匪徒尼巴（杰克•尼科尔森 Jack Nicholson  饰）落入了化学池。尼巴因此面部神经受损，成了永远咧嘴笑的笑面人，人称“小丑”。“小丑”杀死了团伙的首领，控制了整个高汉市的黑道。“小丑”利用化学药品让人发笑而死，他用这种方法袭击了博物馆，幸得蝙蝠侠及时赶到，挫败了“小丑”的阴谋。在女友碧姬（金•贝辛格 Kim Basinger 饰）家里时，“小丑”突然袭击，蝙蝠侠巧妙躲过了袭击，意外发现“小丑”就是杀死自己的父母的仇人。“小丑”这次虏走了蝙蝠侠的女友碧姬，约定蝙蝠在教堂楼顶决一死战！©豆瓣', '迈克尔·基顿', '蒂姆·波顿', 7.5, 55453, 'tt0096895', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1502638000.jpg', 0.4, 2.7, 35, 46.1, 15.8, '0.087134,-0.150922,-0.260497,0.207133,-0.073254,-0.099167,0.774423,0.256830,-0.335268,-0.116614,0.516026,0.622377,-0.372266,-0.023644,0.109964,-0.090820,-0.246452,-0.584504,-0.256745,-0.179737,-0.280673,-0.195485,-0.341924,-0.396266,0.179081,-0.397392,0.400575,0.109898,-0.449256,0.301927,0.405147,0.314033,-0.234072,0.375070,-0.270301,0.037909,0.069363,-0.307208,-0.072273,0.225482,-0.320239,-0.310536,0.015315,0.332656,-0.431429,0.259511,0.867687,-0.532788,-0.098343,-0.448254,0.223832,-0.532124,-0.083895,0.058057,0.289246,-0.380982,0.125699,-0.349112,0.047734,0.076259,0.474725,0.051381,-0.856150,-0.068476,-0.036720,0.175493,-0.572206,0.305149,0.032808,0.420012,0.246988,-0.031199,0.372876,-0.074306,0.360757,0.300556,-0.119713,0.128236,-0.538146,0.115915,0.406321,-0.001555,-0.287006,0.082482,-0.150335,-0.290017,-0.231636,-0.181702,-0.083620,-0.078319,0.683145,-0.289862,-0.274501,0.364297,-0.594941,-0.316410,-0.172203,0.283354,-0.302634,-0.433589,-0.249027,-0.790875,0.002129,0.019103,0.142445,0.001657,-0.238032,-0.128491,0.278822,-0.502558,0.308497,0.735433,0.099079,-0.216914,0.448986,0.102660,-0.055601,-0.095126,0.006335,0.351771,0.425575,0.361857,0.238472,0.209394,-0.130627,-0.232413,-0.157811,0.341571', '2988294', '1300324', '25774050', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297979', '独臂刀', '剧情', '大侠齐如丰将为救他而身亡的仆人方诚的儿子方刚（王羽）抚养成人后，欲立其为掌门人，此举引来方刚师兄的嫉妒。追求方刚不成的齐如丰的女儿齐佩联合师兄与方刚比武，却失手砍断方刚右臂，方刚负伤逃离齐家。只剩左臂的方刚被少女小蛮（焦姣）救下后一度意志消沉，但终在小蛮的鼓励下重获信心，凭借小蛮父亲留下的秘籍《左手图谱》练成“左手神刀”绝技。齐如丰的仇家笑面二郎和长臂神魔将齐的弟子系数杀尽，并囚禁了齐佩和齐如丰。顾及师恩，方刚决意不计前嫌助齐家一力。©豆瓣', '王羽', '张彻', 7.4, 8001, 'tt0061597', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2285562180.jpg', 0.5, 3.1, 36.3, 46.3, 13.8, '-0.127105,-0.011213,-0.352226,0.421858,-0.133299,-0.581392,0.347188,0.252058,-0.273853,-0.115844,0.307386,0.513879,0.117056,0.228829,0.123776,-0.367146,0.418387,-0.802438,-0.240686,0.124418,-0.176946,-0.210275,0.216715,0.120738,-0.169894,-0.410897,0.718595,0.010889,-0.138330,0.499577,0.344541,0.131225,-0.016013,0.321048,-0.201450,0.275515,-0.356899,-0.134307,-0.330190,0.180504,-0.002373,-0.291078,0.028765,0.221333,-0.464388,0.247878,0.553447,0.101394,0.171154,-0.535739,0.090591,-0.140194,0.049623,0.263450,0.100924,0.183688,0.132175,0.143810,0.021636,-0.200582,0.209889,-0.162380,-0.760856,-0.136926,0.245405,-0.384213,-0.751774,0.350060,-0.262475,0.239034,-0.211176,-0.018454,0.052423,0.191769,0.041994,0.015506,-0.190455,-0.004120,-0.305590,0.043610,0.443577,-0.490890,0.270285,-0.183990,0.024861,-0.188311,0.171661,-0.389706,-0.022070,-0.102894,0.360827,0.240963,-0.040812,0.346818,-0.120862,-0.224457,-0.439094,0.460961,0.060068,-0.260398,-0.026630,0.039005,-0.112912,0.015933,-0.051560,-0.257548,0.404262,-0.439473,0.785822,-0.558691,0.145205,-0.005560,0.455432,-0.281120,0.501106,0.045190,0.319624,-0.014431,-0.372150,0.096964,0.199011,0.307829,0.536189,0.156202,-0.171200,-0.132946,-0.354210,0.116396', '6101834', '27602116', '25880986', '25903033');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297981', '最佳福星', '剧情', '一宗跨国要案难住香港警方，在一次高层秘密会议上，曹探长（曹德发 饰）接受下属建议，决定派非警方人员盗走日本黑帮犯罪分子的名贵钻石。他照例找到五福星老搭档，但最终只有鹧鸪菜（洪金宝 饰）同意接手。经过一番筛选，他们从警局内部又找到4个不着调的警员，分别是：狗王伦（谭咏麟 饰）、肥豹（郑则士 饰）、Rambo（刘德华 饰）、Band友（陈友 饰）和力保健（楼南光 饰）。这几个人的搞笑和脱线本领比起五福星来有强不差，闹出更多的笑话。为了在短期内将他们训练有素，曹探长还专门派出性感迷人且身怀绝技的女警察一品香担任教练，只是这群色迷迷、只想着占便宜的家伙最终能否成功完成任务呢？©豆瓣', '洪金宝', '曾志伟', 6.9, 9369, 'tt0091447', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266775041.jpg', 1, 6.5, 51.8, 28.7, 11.9, '-0.036735,0.081875,-0.351823,0.446296,-0.175432,-0.052006,0.157281,-0.083264,-0.397683,-0.311389,0.020002,0.345373,-0.131464,0.018420,0.014087,-0.089619,-0.268455,-0.390414,0.121098,-0.074467,-0.101739,-0.636574,-0.278732,-0.256188,0.221309,0.033778,0.274579,0.180276,-0.078452,0.141894,0.585843,0.144068,-0.208203,0.061687,-0.089745,-0.126542,0.335453,0.053123,-0.120760,0.176931,-0.056727,-0.185888,-0.155313,-0.038052,0.277953,0.304269,0.334790,-0.072686,-0.140523,-0.144878,0.144715,-0.293959,-0.106904,-0.156246,0.379805,0.094607,0.240239,0.314465,-0.174038,0.107314,0.147009,-0.124122,-0.761937,0.126782,0.420582,0.011154,-0.478390,0.203084,-0.228031,0.228717,-0.109261,-0.243496,-0.011021,0.418988,0.227367,0.070383,0.122970,0.186440,-0.584995,0.276235,0.541868,0.126445,0.161493,-0.095476,0.130762,-0.624895,0.164707,-0.420444,-0.006915,0.214924,0.263657,-0.257720,0.291996,-0.517741,-0.492964,-0.174795,-0.089208,-0.007948,-0.066446,-0.155693,0.334465,-0.643953,0.111227,-0.268240,-0.375117,0.117145,0.247175,-0.230098,0.557948,-0.428405,-0.158714,0.448229,0.055931,-0.753461,0.557566,0.151802,0.017468,-0.350174,-0.463035,-0.514793,0.397411,0.065716,0.333254,0.337166,-0.195742,-0.736239,-0.093138,-0.410921', '1302110', '3670447', '25918677', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297991', '杀死一只知更鸟', '剧情', '美国南部的梅岗镇上住着父亲芬奇(格利高里·派克 Gregory Peck 饰)和他的一对儿女。尽管妻子已经亡故，一家人仍过得乐也融融，芬奇对儿女亦既严格又疼爱有加。父亲平时还对他们说过，不要杀死为人类唱歌的知更鸟，因为她们善良而从不伤害人。芬奇除了是一个慈父，还是当地一名勇于伸张正义的律师。这天他接到一宗强奸案，被告是黑人罗宾逊（布洛克·皮特Brock Peters 饰），而受害者是一名白人女子。这样一个案件，在那个种族歧视相当严重的年代，罗宾逊的境况堪忧。即使芬奇找到了他没有犯罪的证据，也不足以让人们抛开种族成见。芬奇在法庭上奋力维护事实和法律的公正，然而却没能阻止人们根深蒂固的偏见。更糟糕的是，怀有种族偏见的白人已经把芬奇当作公敌，而罗宾逊也无法洗清罪名，更可悲的命运在等待着他。©豆瓣', '格利高里·派克', '罗伯特·马利根', 8.6, 53487, 'tt0056592', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164106144.jpg', 0.2, 0.7, 11.3, 44.6, 43.2, '0.261314,-0.149706,-0.604115,0.726144,-0.574309,-0.267830,0.975615,0.162766,-0.609099,-0.250466,0.250582,0.870864,0.269056,0.291117,0.049647,0.004551,-0.315723,-0.470668,0.062974,-0.105515,-0.171297,-0.768047,-0.288613,-0.441454,-0.277069,-0.333358,0.537888,-0.099561,-0.229389,0.191849,0.421243,0.312769,0.084127,0.430146,-0.271876,-0.170193,0.033380,0.081157,-0.363304,-0.020599,0.117761,-0.225217,-0.217713,0.602194,-0.268920,0.442525,0.330242,-0.465981,-0.314324,-0.213269,0.457291,-0.578191,0.102363,0.373453,0.479881,-0.422020,0.221757,0.425105,-0.014528,-0.017686,0.153932,0.082221,-0.771315,-0.117837,0.165191,0.174176,-0.647056,0.650560,-0.329385,-0.098864,-0.097568,-0.225421,0.045418,0.118385,0.094625,0.419030,-0.266587,-0.215732,-0.687399,0.117237,0.628691,0.045392,-0.316105,0.157682,-0.421382,-0.489577,-0.074880,-0.392904,-0.833835,-0.041480,0.198674,-0.175369,-0.243179,0.342703,-0.305460,0.089499,-0.361316,-0.121702,-0.108774,-0.469600,0.112585,-0.207628,-0.058879,-0.546080,-0.521215,0.036901,0.159051,-0.248158,0.925634,-0.715972,0.196202,0.559563,0.349716,-0.727180,0.771650,0.455415,0.118371,-0.334305,-0.392954,0.288683,0.162827,0.110379,0.037132,0.074646,0.157809,-0.221573,0.093765,0.525982', '4847665', '26348103', '1456503', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297995', '美女与野兽', '喜剧', '贝儿美丽善良，与老父亲一起住在一个宁静的小村庄里。一次，父亲不小心闯进了野兽的领地，被囚禁在野兽的城堡里。为了救出亲爱的父亲，贝儿只身犯险，答应与野兽同居于古堡而换回了父亲。野兽的城堡华丽而充满奇幻色彩，有充满绅士风度的烛台先生，和蔼亲切的茶壶妈妈，还有可爱的小茶壶宝宝。然而，贝儿生活的并不愉快，一心想念着她的父亲。终于，贝儿找到了逃走的机会。可是却遇到了凶狠的狼群。危难关头，野兽及时出现，解救了贝儿，自己却受了伤。贝儿心存感动，细心照顾野兽。相处的过程中，二人互相了解，野兽也被感化，慢慢变得温和，学会去爱。朝夕相处，日生情愫。也许，野兽也可以是英勇的守护骑士，温雅的白马王子。©豆瓣', '佩吉·奥哈拉', '加里·特洛斯达勒', 8.5, 168297, 'tt0101414', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2238467474.jpg', 0.1, 0.5, 12.8, 47.4, 39.2, '0.047744,0.060673,-0.577391,0.613391,-0.230599,-0.243839,1.039541,-0.079005,-0.304823,-0.063147,0.369991,0.567459,0.201710,0.332775,-0.067463,-0.030525,-0.042873,-0.439081,-0.091554,0.139849,-0.109435,-0.204360,-0.260445,-0.223262,0.120420,-0.389972,0.386213,0.041878,0.007759,0.620429,-0.122948,0.082711,-0.399240,0.589685,-0.258291,-0.219525,-0.097726,0.089626,-0.277182,0.080845,0.058609,0.075073,-0.090479,0.142750,0.155602,0.187351,0.712359,-0.421642,-0.290761,-0.104993,0.197279,-0.221786,0.185742,0.280705,0.057627,-0.153043,0.205301,-0.072550,-0.111911,0.101563,0.079524,-0.386560,-0.514627,0.084160,0.017876,0.184165,-0.516579,0.594119,0.176160,0.063742,0.505247,-0.290868,0.151715,-0.000736,0.227540,0.498458,-0.179001,0.312033,-0.424906,-0.148496,0.656592,-0.219085,-0.161138,0.304142,-0.578304,-0.438299,0.472966,-0.234129,-0.640606,-0.016135,0.339439,-0.039403,-0.668994,0.409935,-0.630153,-0.022829,-0.305996,0.198904,-0.050179,-0.564745,-0.210137,-0.233103,-0.100030,-0.422558,-0.303639,0.139001,-0.032255,-0.170274,0.849002,-0.942453,0.373419,0.650532,0.475969,-0.272406,0.658105,0.026767,-0.133117,0.127805,0.149233,0.495321,-0.008731,0.048934,0.247706,0.228231,-0.263969,0.236720,-0.543037,0.280558', '3005387', '1292062', '2081098', '2377539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1297996', '活死人之夜', '悬疑', '在一场意外中，芭芭拉（朱迪思·欧迪 Judith O''Dea 饰）和哥哥遭到了丧尸的袭击，这些活死人个性凶残样貌可怖，在它们的脑袋里，只装了一件事情，那就是“吃”。受伤的哥哥不幸感染了病毒成为了丧尸中的一员，悲痛和恐惧之中，芭芭拉逃进了一间民宅内，在那里，她遇见了同样在此躲避丧尸的本（杜安·琼斯 Duane Jones 饰）。藏在这间屋子里的并不止芭芭拉和本两人，汤姆（Keith Wayne 饰）、朱迪（Judith Ridley 饰）、哈里（Karl Hardman 饰）和海伦（Kyra Schon 饰）等人纷纷加入了避难的队伍，面对屋外越来越多的丧尸，众人知道，如果不能主动出击，那么只有死路一条。搜集仅有的武器，封锁门窗，在这一危急时刻，每一个人都在为了生存而战斗着。©豆瓣', '杜安·琼斯', '乔治·A·罗梅罗', 7.4, 8642, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2182915725.jpg', 1.1, 3.8, 34.4, 45.1, 15.7, '0.358816,-0.135492,-0.901005,0.243885,-0.107756,0.064904,1.218533,0.031833,-0.460054,-0.202389,0.371907,0.720803,-0.083115,-0.062347,0.106562,-0.292622,-0.309788,-0.360158,-0.142292,-0.329986,-0.529139,-0.252184,-0.539110,-0.560436,0.160684,-0.370287,0.452030,0.429728,-0.130624,0.545080,0.231415,0.189825,-0.277186,0.612897,-0.130256,-0.013594,-0.012974,-0.117609,-0.003829,0.285252,-0.204286,-0.305039,-0.083211,0.139481,0.052264,0.311590,0.629646,-0.674568,0.000949,0.022922,-0.100121,-0.219766,-0.071929,0.300755,0.384499,-0.390523,0.415790,-0.028607,-0.240842,0.204516,0.129547,0.205590,-1.054787,-0.089981,0.075032,0.412368,-0.597348,0.568296,0.101267,0.016022,0.205054,-0.146448,0.297685,0.171304,0.020196,0.252517,-0.279355,-0.214238,-0.720499,-0.145357,0.601296,-0.256925,-0.005230,0.171233,-0.124578,-0.500107,-0.214853,-0.130946,-0.424779,-0.164970,0.391702,0.116543,-0.335622,0.091433,-0.663138,0.175285,0.030246,-0.252005,-0.405925,-0.277062,-0.163472,-0.406882,0.084897,-0.431313,-0.365469,0.346668,-0.083281,-0.040317,0.678398,-0.799300,0.181290,0.365388,0.487533,-0.318124,0.541856,0.044298,0.377553,0.275848,-0.152216,0.063683,0.102994,0.427613,0.403854,0.582059,0.140980,-0.192986,-0.493108,0.412648', '21619567', '3005387', '1428054', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298003', '天才与白痴', '喜剧', '李护士（许冠杰 饰）是精神病院的护士，一次偶然间，他发现了病院的打杂阿添（许冠文 饰）经常在停尸间偷取死去的病患身上的贵重物品。于是，李护士提出四六分账，阿添无奈接受，两人就这样合作干起了这个偷鸡摸狗的行当。一日，病院新来了一名病人大只佬乔明，他入院不久就精神病发去世了。阿添在停尸间里发现了乔明身上带有一些名贵古董的碎片。兴奋不已的两人调查后得知乔明有一个女儿，人称公主。他们找到了公主，哄骗公主后得知乔明生前经常在香港一个海滩潜水。两人来到海滩后轻易找到了价值连城的古董，但这时，意外发生了！©豆瓣', '乔宏', '许冠文', 7.5, 6089, 'tt0100776', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505096229.jpg', 0.5, 3.2, 35.1, 43.8, 17.4, '0.291175,0.087203,-0.600680,0.325685,-0.147959,-0.341870,0.818401,0.005146,-0.720405,-0.417913,0.313607,0.583569,-0.378101,0.420501,0.228527,0.090351,-0.224835,-0.443012,-0.087634,-0.378709,-0.630336,-0.243571,-0.221920,-0.301762,-0.333940,-0.063892,0.125284,0.137377,0.004445,0.466256,0.324679,0.062082,-0.036740,0.473806,-0.267491,0.206958,0.296974,0.298600,0.083465,0.315361,0.342330,-0.304202,0.029024,-0.101336,0.315909,0.319392,0.619948,-0.023199,-0.263674,-0.059662,0.511566,0.095325,-0.092882,0.003283,0.562210,0.068218,0.178663,-0.275068,-0.446472,-0.323247,0.139196,0.285563,-0.079926,-0.018362,-0.118326,0.305738,-0.736170,0.009250,-0.168511,0.039883,-0.105925,-0.605262,0.489031,0.216494,0.130558,0.313628,0.043298,-0.111509,-0.732360,0.395303,0.577106,-0.074912,-0.101816,0.135769,-0.075849,-0.593975,0.301604,-0.033628,-0.183328,0.201530,0.539940,-0.247590,-0.271800,-0.291705,-0.279684,-0.437954,-0.218556,-0.092830,0.030044,-0.134213,-0.025400,-0.608608,-0.021776,-0.092904,-0.292031,0.177472,0.016405,-0.159006,0.637706,-0.678632,0.314040,0.360379,0.177249,-0.492175,0.523965,-0.444282,0.282653,-0.114090,0.197910,-0.122901,0.317722,0.391530,0.342361,0.699089,-0.167510,-0.131509,-0.237354,-0.122610', '1302384', '26591649', '21619567', '30210700');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298038', '诺丁山', '喜剧', '著名影星安娜斯各特（茱莉亚罗伯茨 饰）的演艺事业如日中天。一天她来到了诺丁山的一间书店，邂逅了事业爱情两失意的老板威廉萨克（休格朗特 饰）。威廉认出了安娜是红极一时的明星，十分惊讶，也没想到自己会爱上这位明星，假扮记者借故约会安娜。很快两人坠入爱河，本来甜蜜的生活却一下子被发现了的记者破坏了。安娜承受着媒体的压力，需要做出决定，两人也吵了起来……©豆瓣', '朱莉娅·罗伯茨', '罗杰·米歇尔', 8, 339043, 'tt0125439', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p480943589.jpg', 0.2, 1.7, 22.3, 47.9, 27.9, '0.465033,0.000634,-0.773838,0.150562,0.168398,-0.375905,0.903326,0.449232,-0.313417,-0.064019,0.462333,0.961536,-0.695236,0.320216,0.665794,0.066890,-0.505369,-0.703776,0.268349,-0.118266,0.228378,-0.277653,-0.104532,-0.154989,0.015907,-0.343253,0.378957,-0.055359,0.022101,0.492440,0.361690,-0.003608,0.271934,0.627327,0.189002,0.272299,0.554562,-0.046528,-0.209095,0.275063,-0.087919,-0.184951,0.046835,0.231428,-0.124550,0.084385,0.357746,-0.162295,-0.167457,0.119786,0.521741,-0.179590,-0.040233,0.121078,0.312960,-0.177346,0.235015,-0.146260,-0.277117,0.048847,0.230373,0.154140,-0.371669,0.462605,-0.020805,0.255284,-0.724464,0.404279,-0.023930,-0.106122,-0.015391,-0.364538,-0.009541,0.189082,0.241462,0.358799,0.021351,0.273081,-0.512381,0.149456,0.626586,0.037570,-0.135920,0.466924,-0.269510,-0.177287,-0.150906,-0.062754,-0.654808,-0.018633,0.658272,-0.186940,-0.088539,0.200204,-0.546477,-0.181463,-0.297286,-0.097670,-0.171067,-0.483985,-0.190108,-0.771353,-0.371682,-0.113314,-0.186913,-0.331388,0.027801,-0.259749,0.729729,-0.915689,-0.096521,0.614660,0.406330,-0.423703,0.631861,0.157771,-0.168986,-0.223082,-0.126017,0.359216,-0.392945,0.294879,0.195297,0.527221,0.019040,-0.216742,-0.111944,0.249394', '1301686', '3326747', '1296534', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298040', '倩女幽魂3：道道道', '动作', '小和尚十方（梁朝伟 饰）随师父白云（刘洵 饰）护送金佛去五台山。路上偶遇痞子道士燕赤霞（张学友 饰）杀死强盗无数，三人结下梁子。十方与师父夜宿鬼寺兰若寺。师父外出打探时，十方遭遇女鬼小卓（王祖贤 饰）。十方不受其诱惑，二人争斗，十方念咒将其制服，但仍好心将其放走。十方将金佛不慎丢失，找到后已破成两段，树妖姥姥趁机发难，白云被活捉。十方在小卓帮助下逃出，外出求人修补金佛却不幸被骗。幸得再遇小道士燕亦霞，得其相助。小卓死敌小蝶（利智 饰）出击勾引二人不成，恼怒之际识破小卓与十方的计划，引姥姥到三人藏匿之处。十方在小卓再次帮助下逃出，并救得师父，小卓却被姥姥抓回折磨。十方与燕赤霞掘出小卓骨灰逃出兰若寺，但姥姥已布下天罗地网，众人危在旦夕，最后关头，十方化成佛祖金身，对付树妖……©豆瓣', '梁朝伟', '程小东', 7.6, 101792, 'tt0102932', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515752551.jpg', 0.4, 2.8, 32.8, 43.8, 20.2, '-0.086907,0.139770,-0.551041,0.146625,-0.063839,-0.106851,0.287801,-0.072857,-0.227007,-0.269032,0.202998,0.267126,-0.156060,-0.027661,0.168634,0.070620,0.384769,-0.435467,-0.069365,0.050696,0.058073,-0.002426,-0.394471,0.207073,-0.243909,-0.312376,0.283199,0.217190,-0.081482,0.260444,-0.026735,0.110843,-0.791357,0.216240,-0.184896,0.251124,-0.543765,-0.005895,-0.148790,0.496850,-0.425557,-0.467924,-0.123751,0.057417,-0.298960,0.256717,0.309102,-0.410598,0.071114,-0.310639,-0.045577,-0.241764,-0.146829,0.415733,-0.023910,-0.098831,0.402558,0.136919,-0.407891,0.155287,0.165219,-0.087527,-0.059534,0.323555,0.307409,-0.313695,-0.503169,-0.114528,0.020622,0.338756,-0.168888,-0.561584,0.129374,0.141865,0.218795,-0.008662,-0.192998,-0.233212,-0.471559,-0.234890,0.407857,-0.449682,0.567837,-0.328584,0.415555,0.165612,0.160623,-0.001470,0.118710,0.272034,0.425945,0.046921,0.121252,0.093498,-0.397646,-0.606658,-0.509229,0.601711,-0.345887,-0.046859,-0.025021,-0.575866,0.005702,0.314820,-0.278719,-0.069179,0.198268,-0.140662,0.313949,-0.383634,0.497132,0.169091,0.318884,-0.251531,0.319162,0.106626,0.363535,-0.005694,-0.040310,0.065488,0.212502,0.753578,0.491026,0.073445,-0.109998,-0.069382,-0.228240,-0.343980', '33392524', '3066798', '25827963', '1303676');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298043', '巴顿·芬克', '剧情', '巴顿（约翰•特托罗 John Turturro 饰）是纽约的一名优秀的编剧，他的剧本刚刚在百老汇得到认可，好事便接踵而来。好莱坞的一间电影公司邀请他到当地创作一部关于摔角的B级片剧本，于是，巴顿便来到了好莱坞。巴顿租住在一间破败的旅馆中开始了他的创作，无奈灵感却迟迟未光临，他陷入了巨大的苦闷当中。更不幸的是，此刻，巴顿隔壁的房间里发生了种种怪事，使他犹如置身于人间炼狱，脑海中不时浮现出种种荒诞可笑的幻象……©豆瓣', '约翰·特托罗', '乔尔·科恩', 8.1, 33567, 'tt0101410', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1058380546.jpg', 0.6, 2, 18.8, 49.2, 29.3, '0.561518,0.332558,-0.880389,0.443613,0.238260,-0.204028,1.045267,0.107733,-0.661077,-0.253847,0.386306,0.886676,-0.350775,0.450343,0.249093,0.045943,-0.468161,-0.616074,-0.090461,-0.393290,-0.034219,-0.310916,-0.594057,-0.260683,-0.027753,-0.176221,0.368188,0.424963,-0.339514,0.227396,0.192803,0.425259,-0.185996,0.423776,-0.021795,0.418127,0.233066,0.210249,-0.020676,0.161479,0.139114,-0.350856,-0.436955,0.259753,-0.077350,0.423248,0.477693,-0.246287,-0.317787,0.275706,0.640871,-0.053853,-0.134381,0.053997,-0.001782,0.135029,0.238288,0.049440,-0.370115,0.222569,-0.150109,-0.166019,-0.835818,-0.142829,-0.045605,0.379670,-0.461746,0.264460,-0.133508,-0.081915,0.256149,-0.270195,0.036036,-0.026611,0.420041,0.620453,-0.109174,0.081176,-0.318669,0.481039,0.570585,0.052265,-0.485393,0.531048,-0.261806,-0.307851,-0.125610,0.046428,-0.346181,-0.112366,0.524590,0.030087,0.073341,0.107811,-0.472893,-0.061176,-0.246440,-0.262443,-0.363822,-0.061331,-0.217154,-0.923335,-0.208568,0.082315,-0.036471,-0.199338,-0.049719,-0.008418,0.618564,-0.710506,0.228374,0.490994,0.053655,0.057916,0.649741,-0.233749,0.211840,0.062634,0.122378,0.137761,-0.077321,0.373492,-0.045403,0.521417,0.066340,-0.364390,-0.705476,0.604980', '1316693', '10466639', '1296534', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298047', '造雨人', '剧情', '初出茅庐的鲁迪·贝勒（马特·达蒙 Matt Damon饰）是刚踏进律师界的新手。一腔热血的鲁迪接手的第一个案子是一宗涉及医疗保险赔偿的诉讼。无助的母亲，生命垂危的儿子，拒绝支付医疗费的保险公司，不择手段的辩护律师，一切都跟当初设想的大相径庭。面对种种举步维艰的行业阴暗面和陷于困境的弱势群体，鲁迪至始至终都没有放弃他的正义之心。影片的另一条主线还有一位遭受家庭暴力的受虐少妇。影片用写实的手法，向我们描绘了一场捍卫正义的道德之战。本片根据约翰·格里沙姆的同名小说改编。©豆瓣', '马特·达蒙', '弗朗西斯·福特·科波拉', 8.2, 15253, 'tt0119978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2162186286.jpg', 0.2, 1, 17, 54.7, 27.1, '0.292762,-0.150281,-0.471055,0.533472,-0.151598,-0.350351,0.550650,0.113092,-0.203845,-0.310570,0.447735,0.740649,0.024555,0.049191,0.311312,-0.050437,-0.081609,-0.739927,-0.337969,0.209203,-0.148971,-0.622536,-0.224104,-0.275041,-0.306306,-0.172068,0.823377,-0.055155,-0.665895,0.164710,0.500760,0.320555,-0.018112,0.115471,0.034697,-0.064520,-0.164814,0.042129,-0.508629,0.023806,0.141744,-0.137983,-0.126129,0.280294,-0.163742,0.750405,0.522144,-0.354284,0.068287,0.064783,0.783852,-0.428593,-0.049631,0.139672,0.195758,0.000326,-0.062679,0.447146,-0.119403,-0.101776,0.136268,-0.247227,-1.170215,-0.513783,0.120757,0.385513,-0.410988,0.433013,-0.145461,0.075963,0.226933,-0.343277,0.033665,0.246067,0.476842,0.535672,-0.184138,-0.059007,-0.386353,0.333552,0.531876,0.062231,-0.283679,0.273857,-0.424831,-0.542002,-0.104418,-0.482614,-0.634197,0.200619,0.227297,-0.185841,-0.075152,0.400621,-0.663620,-0.226357,-0.074851,-0.381855,-0.024849,-0.324152,-0.082102,-0.522109,-0.212462,-0.229492,-0.242964,-0.033263,0.306529,-0.236526,0.705089,-0.616956,-0.058656,0.482292,0.195214,-0.716769,0.767911,0.146157,0.071853,-0.134520,-0.176797,0.355921,0.117932,0.251305,-0.082348,0.102590,0.221936,-0.107535,-0.187825,0.541907', '26678784', '1293989', '27602116', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298063', '早安', '喜剧', '在东京近郊公路桥下，矗立着几间普普通通的民房，那里住着这个国家最富活力的平凡百姓，琐碎而有趣的故事也在他们中间发生。妇女协会的会费发生亏空，女人们叽叽喳喳打算查明原因。担任会计的小幸妈刚好给家里添置了洗衣机，因此成为重点怀疑对象。无聊的时候女人们婆婆妈妈，张家长李家短，好像永远看不得别人家的半点好。工作了一天的林先生（笠智众 饰）厌烦了女人的聒噪和孩子们的吵闹，偏偏两个儿子小实（设乐幸嗣 饰）和小勇（岛津雅彦 饰）他赌气决定不再说话。而这一次父子的无心之举又在邻居间激起了波澜。大人的世界总是麻烦多多，谦恭礼貌的外表下又有多少捉摸不透的小心思……©豆瓣', '杉村春子', '小津安二郎', 8.7, 9791, 'tt0053134', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200572533.jpg', 1, 0.5, 7.9, 45.6, 45, '0.439754,0.014111,-0.716606,0.177350,-0.371475,-0.107471,0.666395,0.364467,-0.515058,-0.233155,0.070498,0.366039,0.008481,0.410397,-0.062407,-0.111211,-0.314959,-0.435211,0.033125,-0.135082,-0.056311,-0.469627,0.008100,-0.295699,-0.095613,-0.279151,0.057016,0.116813,0.140499,0.110057,0.425726,-0.072155,-0.075371,0.471992,-0.092405,0.068838,0.043694,0.145707,0.060605,-0.207264,-0.135307,-0.114354,-0.390898,0.005529,0.223897,0.364742,0.574683,-0.080690,-0.377881,-0.037969,0.391258,-0.028508,0.086549,0.071646,0.295172,-0.062904,0.307140,0.281533,-0.153216,-0.123517,0.150875,-0.068642,-0.323673,0.209738,-0.010022,0.274686,-0.538226,0.578098,0.166010,-0.241788,-0.136372,-0.387817,0.312538,0.260228,0.279850,0.301621,-0.280415,0.276900,-0.342769,0.184705,0.644942,0.348095,-0.323791,0.198772,-0.121907,-0.132862,0.075840,-0.328493,-0.684469,-0.152711,0.239531,-0.207119,-0.224869,0.095192,-0.529817,0.163624,-0.016843,-0.114296,0.041438,-0.381691,-0.110639,-0.293918,0.163994,-0.502198,-0.274700,0.114967,0.286530,-0.050507,0.833539,-0.627196,0.102548,0.598177,0.353146,-0.433614,0.547411,0.078972,0.167895,-0.070559,-0.293217,-0.276322,-0.074617,0.338423,0.225542,0.361987,-0.256939,-0.240407,-0.262499,0.180181', '26348103', '5262027', '1293175', '1308831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298065', '异灵灵异2002', '喜剧', '警方设立一个名为“2002”的部门，专门对付祸害人间的游魂野鬼。部门内潮（谢霆锋 饰）是拥有阴阳眼的人类，Sam（李灿森 饰）则是个鬼魂，整个部门便由这一人一鬼组成。期间他们遇到了形形式式的加害人类的鬼魂，并一一收复了。后来潮受死去的四婆所托，帮忙照顾住院中的孙女Rain（李彩桦 饰）。潮爱上了医院中的一名护士。但他要专心于Sam一起对付水鬼，这场争斗将决定他们的生死。©豆瓣', '谢霆锋', '叶伟信', 6.7, 9319, 'tt0294251', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2236027016.jpg', 1.7, 10.2, 51.5, 26.9, 9.7, '0.473920,-0.281883,-0.282820,0.443782,-0.298614,0.145600,0.573071,0.025657,-0.473052,-0.441438,0.004768,0.602629,0.244345,0.283331,-0.057945,-0.285995,-0.051879,-0.620443,-0.313998,0.042276,-0.381454,-0.135376,-0.395057,-0.256283,-0.075673,-0.015470,0.516508,-0.006084,0.122051,0.317871,0.282877,0.271874,-0.496890,0.049520,-0.008972,-0.181919,0.053875,-0.031859,-0.154217,0.351428,-0.207113,-0.190759,0.032443,0.198784,-0.163992,0.472583,0.541237,-0.300352,-0.094428,-0.595400,0.184059,-0.393050,-0.104562,0.097549,0.429437,0.132040,0.450044,0.310522,-0.328150,0.127276,0.186362,-0.042092,-0.975604,-0.128860,0.408383,0.161480,-0.459247,0.131370,0.141844,0.058604,-0.257219,-0.147349,0.392463,0.410738,0.208454,0.427335,-0.104654,-0.338419,-0.395695,0.244856,0.651759,-0.063868,-0.164123,0.013037,-0.094215,-0.542346,0.105243,-0.351913,-0.106492,0.036186,0.021265,0.029525,-0.123864,0.001965,-0.768740,-0.062206,-0.152437,0.038094,-0.324381,-0.195385,0.279834,-0.620507,0.143803,-0.275062,-0.233570,0.243479,0.206765,-0.039136,0.674654,-0.511436,0.014698,0.588326,0.430460,-0.766504,0.748041,0.031257,0.526615,-0.204096,0.150783,-0.254419,0.130385,0.395234,0.064800,0.254036,0.126639,-0.122796,-0.298265,-0.014361', '26678784', '4301278', '1793491', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298070', '加勒比海盗', '动作', '故事发生在17世纪，传说中海盗最为活跃的加勒比海。风趣迷人的杰克·斯伯洛（约翰尼·德普 Johnny Depp 饰），是活跃在加勒比海上的海盗，拥有属于自己的“黑珍珠”号海盗船。对他来说，最惬意的生活就是驾驶着“黑珍珠”号在加勒比海上游荡，自由自在的打劫过往船只。但不幸的是，他的仇敌，老谋深算的巴尔巴罗萨船长(杰弗里·拉什 Geoffrey Rush 饰)偷走了他的“黑珍珠”号。巴伯萨是一个无恶不作的坏蛋，他抢劫了杰克的"黑珍珠号"后，更加猖狂，在加勒比海上横行霸道，一时成为整个加勒比海的霸主。一次，巴伯萨一伙袭击了罗亚尔港小镇，还绑架了总督的女儿伊莉莎白·斯万(凯拉·奈特莉 Keira Knightley 饰)和伊莉莎白青梅竹马的铁匠学徒威尔·特纳（奥兰多·布鲁姆 Orlando Bloom 饰），想方设法救出了狱中的船长杰克，偷来英国皇家舰队最快的"拦截号"军舰迅速向"黑珍珠"追去。在打斗中，威尔和杰克发现，巴尔巴罗萨和他的海盗们身背着咒语，在每一个月光之夜，他们就变成了不死骷髅，而伊莉莎白正是解开咒语的关键。', '约翰尼·德普', '戈尔·维宾斯基', 8.8, 804970, 'tt0325980', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1596085504.jpg', 0.1, 0.5, 9, 39.5, 50.9, '0.255982,-0.160881,-0.720474,0.633404,-0.212491,-0.256517,1.084990,0.060513,-0.300231,0.115169,0.372983,0.781693,0.016102,-0.006062,0.524962,0.523605,-0.515844,-0.449372,-0.003656,-0.122635,-0.133938,-0.556570,-0.483833,-0.185099,0.117229,-0.401715,0.349441,-0.070172,-0.103401,0.400892,0.325049,0.393814,-0.011908,0.361674,-0.451596,0.055539,0.227697,-0.368361,0.120525,0.263076,-0.334469,-0.218101,0.074680,0.058103,0.024027,0.316006,0.742854,-0.543382,0.311277,0.004052,0.026366,-0.528165,-0.053659,-0.082091,0.435188,-0.252043,-0.150914,-0.058590,-0.047949,-0.236023,-0.006622,-0.028157,-0.609643,0.156595,-0.119778,0.291502,-0.646565,0.419311,-0.337939,0.154400,0.198737,-0.309659,0.362129,0.119443,-0.047167,0.128206,0.023149,-0.075011,-0.767995,0.233999,0.374998,0.143677,-0.095917,0.228787,-0.042494,-0.527880,-0.110483,-0.413840,-0.418309,-0.322362,0.742912,-0.413399,-0.129926,0.413478,-0.803893,0.093051,-0.333704,-0.488767,-0.132060,-0.214980,-0.153404,-0.771345,0.038136,-0.512270,-0.214753,0.164037,-0.070728,-0.166317,0.604737,-0.788890,0.312623,0.918287,-0.037366,-0.083931,0.639201,0.069330,0.105984,-0.002609,-0.090696,0.310010,0.406282,0.409675,0.082515,0.547314,0.088253,-0.176189,-0.273429,0.641263', '1301686', '21619567', '1293515', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298084', '硅谷传奇', '剧情', '本剧是部描述苹果公司与微软的，非官方授权的传记式电影。电影改编自保罗·弗列柏格与米迦勒·史文所撰写的《硅谷之火》。电影由马汀·伯克编导，于1999年在透纳电视网（简称T.N.T.）播出。本片讲述了美国柏克莱大学，言论自由运动时期的故事。通过苹果公司的创办人，年轻的史蒂夫·乔布斯（诺亚·怀尔 Noah Wyle 饰）与史蒂夫·沃兹尼克（乔伊·斯洛尼克 Joey Slotnick 饰）；微软公司的创办人，学生时代的比尔·盖兹（安东尼·迈克尔·豪尔 Anthony Michael Hall 饰）、他的高中朋友史蒂夫·包尔摩（约翰·迪·玛吉欧 John Di Maggio 饰）、保罗·艾伦（乔什·霍普金斯 Josh Hopkins 饰）等几个人的事迹诉说了”苹果”和“微软”当初的发展史崛史。©豆瓣', '诺亚·怀尔', '马丁·伯克', 7.6, 11197, 'tt0168122', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1949178259.jpg', 0.5, 3.1, 31.8, 46, 18.5, '0.251180,-0.313488,-0.449962,0.702381,0.416007,-0.573277,0.396465,0.233114,-0.452930,-0.430889,-0.062173,0.947984,-0.427586,0.335997,0.293620,0.081488,-0.529008,-0.610708,0.039258,-0.159498,0.339513,-0.565624,-0.182596,-0.492303,-0.047331,-0.398163,0.627789,-0.391510,-0.243070,0.290185,0.238898,0.402253,0.174340,-0.130491,0.165883,0.171897,0.502407,-0.226573,-0.626789,0.130707,0.103784,-0.033463,-0.134530,0.051964,0.225101,0.240190,0.310264,-0.239151,0.352419,-0.003736,0.439598,-0.164815,0.123333,-0.022234,0.213107,0.069880,0.229991,0.441479,0.058012,-0.110623,-0.119368,-0.341204,-0.587602,-0.145605,-0.182161,0.448571,-0.244630,0.409410,-0.576397,0.342125,-0.049596,-0.205691,-0.103574,-0.041610,0.415618,0.384190,0.248210,-0.033648,-0.207844,0.607434,-0.030824,0.125543,-0.455683,0.324864,-0.250394,-0.409984,-0.506982,0.023381,-0.631470,0.149296,0.584124,-0.358418,0.105870,0.506547,-0.686531,-0.401089,-0.030943,-0.319452,0.061762,-0.208325,-0.013669,-1.156140,-0.110137,-0.301136,-0.142177,-0.546181,0.226089,-0.257694,0.743675,-0.556389,0.076581,0.390049,-0.008865,0.011578,0.636594,-0.217794,0.020996,-0.185729,0.029297,0.367650,0.079877,-0.098620,0.036617,0.541462,0.265597,-0.394820,-0.206770,0.545805', '34961898', '10508921', '30397916', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298093', '警察学校', '喜剧', '某市女市长突发奇想，下令不计教育背景、工作经历等，适龄的年轻人都可以报考警校。一时间，西班牙口音的花花公子乔治、擅长口技的乔维、懦弱的胖子巴巴拉、不爱红装爱武装的汤普森（金•凯特罗尔 Kim Cattrall 饰），以及被父亲好友里德上尉强制塞进警校的惹事泊车仔马哈尼（斯蒂夫•古根伯格 Steve Guttenberg 饰）等人涌向警察学院。与此同时，警校方面痛感严格传统的丧失，拉萨德校长令哈里和卡拉汉两教官在接下来的14周时间内对学员严加训练。这班背景各异的学员绝不是省油的灯，从武器痴迷者到夜夜化妆进入女寝寻欢的大情人无所不有，哈里少尉从学员中选出两人担任班长以配合自己的铁血教育，然而这一切都无法阻止一心求被开除的马哈尼的恶作剧……©豆瓣', '斯蒂夫·古根伯格', '休·威尔逊', 7.8, 9010, 'tt0087928', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1607708527.jpg', 0.5, 2.4, 26.1, 47.7, 23.4, '0.289002,-0.361076,-0.431663,0.409881,-0.267642,-0.341451,0.299135,0.051247,-0.587581,-0.366190,0.014091,0.404212,-0.032961,0.119963,0.484928,-0.308153,-0.282856,-0.679565,-0.256290,-0.106019,-0.220072,-0.560947,0.255355,-0.301012,-0.071351,-0.505026,0.368282,-0.266332,-0.206438,0.444376,0.380505,0.387543,0.085438,0.062041,0.092920,-0.160478,0.451574,-0.219895,-0.240721,-0.025669,0.071389,0.118394,0.056237,-0.077919,0.287197,0.302527,0.481573,-0.131899,0.279031,0.007596,0.155195,-0.178447,-0.125592,0.124101,0.341228,0.052611,0.045413,0.185484,0.179831,0.259556,-0.180285,-0.157953,-0.440989,-0.154746,0.176820,0.164400,-0.496735,0.489406,-0.233143,0.092631,0.085939,-0.038614,-0.181847,0.111086,-0.015369,0.360157,0.073567,0.175537,-0.280677,0.201338,0.457838,-0.027868,-0.295385,-0.096925,-0.315896,-0.400749,0.206761,-0.288078,-0.479346,-0.055691,0.022141,-0.033149,0.147030,0.062066,-0.425687,-0.127534,-0.162231,-0.129463,0.032147,-0.233207,-0.245684,-0.663167,0.179224,-0.266031,-0.078509,0.065382,0.129916,0.012396,0.795819,-0.920097,0.015196,0.151341,0.190817,-0.396682,0.567809,0.048985,0.211626,-0.259061,-0.320171,0.106886,0.502061,0.501537,0.046814,0.594882,-0.069945,-0.535748,-0.004287,0.118802', '4127270', '25922902', '1826173', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298095', '射杀钢琴师', '剧情', '巴黎一间默默无闻的小酒馆里，一位忧郁而孤独的钢琴伴奏师查理·科勒（夏尔·阿兹纳夫 Charles Aznavour饰）。他的生活简单而又单调。热情的酒馆女侍莉娜（玛丽·杜布瓦 Marie Dubois饰）为查理的才华所倾倒，爱上了他。原来，查理曾经是显赫一时的著名钢琴师，在妻子自杀身亡后隐姓埋名于此。莉娜鼓励他重新找回自己走上舞台。然而一日，多年未见的弟弟奇科·萨洛扬（阿尔伯特·雷米 Albert Rémy饰）因躲避黑道仇家的追杀而闯进了他的生活中。查理帮助弟弟逃脱了仇家的追杀，却意外卷入这场残酷的生死逃亡之中。幸运之神并没有眷顾与查理生死与共的莉娜，在激战中，莲娜不幸中弹身亡。查理再度回到了往昔的小酒馆中，一切又回归起始，却物是人非。由法国电影大师弗朗索瓦·特吕弗执导的黑白影片《射杀钢琴师》，根据美国作家大卫·古迪斯的小说改编而成。©豆瓣', '查尔·阿兹纳弗', '弗朗索瓦·特吕弗', 7.8, 6572, 'tt0054389', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2178294262.jpg', 0.3, 2, 24.5, 52.2, 21, '0.132978,0.102595,-0.442313,0.429558,-0.200671,-0.498054,1.076035,0.042514,-0.572499,-0.212416,0.447051,1.032024,0.191674,0.174580,0.569531,0.292326,-0.434912,-0.672604,0.065913,-0.146705,0.024637,-0.515236,-0.576249,-0.200622,-0.117359,-0.448569,0.659554,0.025715,-0.165984,0.636101,0.110738,0.274973,-0.263182,0.316113,0.062129,0.218962,0.331471,0.142183,-0.398250,0.126135,-0.205504,-0.451241,-0.238806,0.164307,-0.128233,0.401811,0.556210,-0.347757,0.008713,-0.193261,0.397756,-0.297712,-0.083825,0.090630,0.129338,0.103106,0.292878,0.135010,-0.150968,-0.040233,-0.102612,0.039714,-0.721140,0.029357,0.203620,0.200862,-0.539476,0.613163,-0.082354,-0.083021,0.019362,-0.187502,0.145505,0.164587,0.349519,0.298819,-0.131625,-0.115350,-0.098188,0.391281,0.657965,-0.175620,-0.315114,0.232372,-0.086106,-0.199412,0.271107,-0.136693,-0.711839,-0.089792,0.380584,0.078089,0.002647,0.495666,-0.463861,0.016620,-0.565533,0.037735,-0.272566,-0.180161,-0.183501,-0.837625,-0.152485,-0.263369,-0.013004,-0.393192,-0.036079,-0.275416,0.427475,-0.727328,0.515365,0.442435,0.108935,-0.091674,0.586354,0.138745,0.239700,-0.044813,0.027990,0.688261,-0.070613,0.079283,0.014571,0.199553,-0.022154,-0.042795,-0.392417,0.454925', '1316693', '1296534', '34890458', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298104', '雷霆战警', '动作', '正在休假的警察Darren（郭富城）与好友兼搭档Alex（王力宏）一起出席后者女友的时装发布会时，目睹一桩谋杀案，两人立刻停止休假投入到了破案中。调查时，两人发现案件异常复杂，牵涉到大陆南方某城的一个庞大的犯罪组织，赶赴到该城后，两人结识为调查一宗涉及国际犯罪组织的案件而深入虎穴当卧底的国际刑警Norika（藤原纪香）。为引出大鱼，Norika铤而走险假扮模特儿走秀，Darren与Alex则在暗中观察，当等来目标人物与之发生枪战时，Alex不幸中弹身亡。伤心至极的Darren发誓要将黑帮铲除，他和Norika也渐渐生出感情。©豆瓣', '郭富城', '唐季礼', 5.9, 9938, 'tt0266408', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203717463.jpg', 3.3, 19.1, 59.6, 13.8, 4.2, '0.287779,-0.305185,-0.780314,0.430858,0.252593,0.061832,0.691035,0.008111,-0.605202,-0.235928,0.261409,0.818694,-0.509316,0.129928,0.699646,-0.376864,-0.294812,-1.194715,-0.085710,-0.056981,-0.233221,-0.428077,-0.241808,-0.222139,-0.154760,-0.150189,0.729658,0.371202,-0.228889,0.630540,0.374816,0.517887,-0.712145,0.606536,0.171642,-0.433664,0.289958,0.273726,-0.434713,0.333640,0.099415,-0.330311,-0.102201,0.004018,-0.014020,0.387941,0.662722,-0.002433,-0.319420,-0.352068,0.430808,-0.515175,0.026837,-0.096190,0.686698,0.267122,0.139398,0.527576,-0.393934,-0.130491,0.018523,-0.069304,-0.861451,-0.016882,0.257685,0.243142,-0.340279,0.137633,-0.211286,0.005862,0.214645,-0.191455,0.484834,0.838913,0.377586,0.035453,0.014655,0.128092,-0.268703,0.168113,0.715209,0.064803,0.091764,-0.006463,0.341024,-0.394077,0.096869,-0.152521,0.145459,0.102941,0.173247,-0.044272,-0.096442,0.501186,-0.535077,-0.505543,-0.220353,-0.205177,-0.004318,-0.350523,-0.096226,-1.008867,-0.247891,0.032452,-0.158725,0.106048,0.232947,-0.304629,0.247417,-0.890305,-0.010577,0.562191,0.086378,-0.720965,0.557354,-0.082428,0.308750,-0.429967,-0.276360,-0.190264,0.349456,0.196840,-0.099939,0.100160,-0.253316,-0.263102,-0.394793,-0.142155', '25723905', '1305249', '6041191', '3621404');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298107', '大都会', '剧情', 'Freder（Gustav Fröhlich 饰）是大都会主宰 Joh Fredersen（Alfred Abel 饰）的儿子。经一位圣洁姑娘（Brigitte Helm 饰）启示，Freder 来到地下目睹了在此劳作的劳工们悲惨的境遇。Freder 向父亲进言，想改变劳工们的处境。但 Joh 不为所动，却对从劳工们身上发现的地图感到忧虑。为弄清地图所示，Joh 不得不向老对头 Rotwang（Rudolf Klein-Rogge 饰）求教。地图所示究竟为何地？劳工们为何要去那里？©豆瓣', '阿弗莱德·阿贝尔', '弗里茨·朗', 9.1, 42091, 'tt0017136', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p906689323.jpg', 0.3, 0.7, 6.4, 30.3, 62.4, '-0.095656,0.019087,-0.458628,0.531718,0.070574,-0.253571,0.563770,-0.069062,-0.423855,-0.265002,0.575297,0.464210,-0.053509,0.229158,0.200059,0.195642,-0.323475,-0.662376,-0.264477,-0.240135,-0.448165,-0.245416,-0.332238,-0.284011,-0.166810,-0.262133,0.531054,0.348579,-0.182571,0.250422,0.429144,0.410368,-0.349657,0.074992,-0.273614,-0.293892,-0.220754,0.090927,-0.268859,-0.205139,-0.088131,-0.277525,-0.749796,0.140649,0.172645,0.275694,0.806332,-0.291711,-0.333306,0.068624,0.449279,0.086312,0.447389,0.519512,0.161243,0.457123,-0.324544,-0.061657,-0.116568,0.237310,0.011995,0.016831,-0.787479,-0.037974,0.095681,0.553786,-0.707335,-0.071317,-0.108810,-0.396386,-0.170315,-0.604449,0.164092,0.199231,0.080422,0.716011,-0.082743,0.009805,-0.327708,-0.136327,0.433866,0.418913,0.220101,0.042036,-0.097427,-0.252237,-0.012339,0.059220,-0.315346,0.045508,0.008905,0.122049,0.141802,0.173604,-0.771498,-0.179398,-0.323614,-0.514419,0.128022,-0.287577,-0.267944,-0.449869,0.123777,-0.158743,-0.229680,0.185782,0.199427,-0.224533,1.002078,-0.572333,0.104581,0.338533,0.176892,-0.954152,0.632165,0.342481,-0.188432,-0.150150,-0.082148,0.170905,0.334034,0.387846,-0.168178,-0.203744,0.054382,-0.576768,-0.368322,0.088481', '1296770', '4181031', '1302661', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298112', '堕落天使', '剧情', '天使1号（黎明）很懒惰，所以选择做了时间、地点、谁该死都不用操心的杀手。天使2号（李嘉欣）很冷艳，是1号的上线，喜欢华服夜出为1号清理房间。天使3号（金城武）很怪异，从不讲话的他爱做的事是半夜撬开别人的店面做生意和拿着摄像机将老爸拍个遍。天使4号（杨采妮）很“现实”，虽无法忘记旧 男友，却也能转身用另外的方式将自己安慰。天使5号（莫文蔚）很神经，喜欢在大雨夜冒出。五位天使在自己的生活轨道上固执寂寞地前行着，为了避免换回更多伤心，他们在轨迹交叉时会提醒自己“忘记他是他”，可是，他们的真情还是会不由自主地流露出来。©豆瓣', '黎明', '王家卫', 8.3, 171824, 'tt0112913', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p449524516.jpg', 0.3, 1.3, 16, 45.5, 36.9, '0.149931,0.052805,-0.468090,0.519519,-0.329784,0.017499,0.887511,0.065759,-0.191490,0.051969,0.214761,0.656442,0.136618,0.318888,0.157668,0.216854,-0.410536,-0.500576,0.082677,-0.174612,-0.244877,-0.301223,0.111267,-0.288791,-0.201546,-0.288480,0.370076,-0.076855,0.032939,-0.111279,0.543225,0.097904,0.204560,0.715201,-0.381029,-0.285432,-0.359760,-0.028141,0.186426,0.154758,0.006495,-0.228451,-0.161984,0.382924,-0.079821,0.202253,0.719894,-0.325524,-0.193466,-0.117981,0.263112,-0.311726,0.136952,-0.147519,0.147278,-0.127476,0.168402,0.213475,-0.017942,0.134225,0.035054,0.056531,-0.773211,0.030373,0.031474,0.137377,-0.740251,0.265777,-0.395941,0.203900,0.275818,-0.546475,0.121462,0.013751,0.390848,0.180741,-0.246091,-0.036074,-0.461105,0.214736,0.601148,0.309567,0.031368,0.557813,-0.359751,-0.379788,-0.248178,-0.288026,-0.609766,-0.196292,0.023496,0.031807,-0.144081,0.185521,-0.497075,0.175125,0.016495,-0.394435,-0.121859,-0.681817,-0.052605,-0.352954,0.094106,-0.515157,-0.321278,0.087666,0.000174,-0.269215,0.716942,-0.900039,0.052880,0.690602,0.337538,-0.472734,0.922194,0.502891,-0.411630,-0.234219,0.106286,0.204313,-0.092807,0.294772,0.184741,0.444030,0.041475,-0.016355,-0.363809,0.582711', '3230462', '3055049', '1296370', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298114', '小亲亲', '喜剧', '专栏作家吴秋月（陈慧琳 饰）笔锋一向泼辣，并以专栏《月经》闻名。因为一张怀旧的黑胶唱片与电台DJ章戎结怨。章戎专门在电台聆听听众的感情烦恼事。接着二人有了更多的见面机会，可是每次都是斗气收场，水火不容。但不过多久的相处，两人却互有了好感，很快陷入了热恋。秋月的前男友此时想要回到秋月的身边，并向求婚及提出移民的要求。秋月收拾好了行李做好了准备，可是心里却始终不知如何是好，心里还是放不下章戎。©豆瓣', '郭富城', '奚仲文', 6.9, 10989, 'tt0253955', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2875006734.jpg', 1.1, 7.3, 47.7, 31.2, 12.7, '0.284294,-0.067403,-0.434501,0.335072,0.203899,-0.500712,0.540997,0.162360,-0.704535,-0.334197,-0.212288,0.281674,-0.324193,0.191821,-0.038349,-0.262981,-0.440600,-0.646060,0.047446,-0.052446,-0.114875,-0.393610,0.125057,0.175991,-0.011889,0.134447,0.550106,-0.018708,-0.083060,0.512941,0.324646,-0.087364,0.091958,0.849194,0.169905,-0.108257,-0.112619,0.020471,-0.458132,-0.060040,0.220684,-0.175750,-0.356008,0.175660,0.098661,0.474062,0.294554,0.079828,-0.400078,0.210900,0.477614,-0.057324,0.128464,0.162681,0.200391,0.080866,0.317360,-0.111875,-0.220898,0.143328,-0.000488,0.086287,-0.309735,0.531095,-0.081497,0.193198,-0.454743,0.352689,-0.197774,0.079471,-0.324525,-0.413084,0.140601,0.262721,0.323609,0.511957,-0.399272,0.094439,-0.380678,-0.106657,0.772447,0.342779,0.106006,0.537853,0.094763,-0.555087,-0.092796,0.181935,-0.299803,-0.040595,0.015736,0.341140,0.103563,0.004008,-0.631871,0.162204,0.019823,0.026800,0.214194,-0.598623,-0.011043,-0.615950,-0.370986,-0.421441,-0.731632,-0.013247,0.351906,0.028483,0.734033,-0.952591,-0.120148,0.091952,0.432811,-0.530033,0.525017,0.410536,-0.026670,-0.020300,0.126203,0.168058,-0.420617,0.138117,0.320398,0.232390,0.122728,-0.229063,-0.252703,0.286857', '1301022', '35030151', '2052978', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298120', '刀锋战士', '动作', '刀锋战士布莱德的母亲怀孕时被吸血鬼咬伤了，生下他后就去世了，由此布莱德（韦斯利•斯奈普斯 Wesley Snipes 饰）带上了一半吸血鬼的血。布莱德自幼在武器专家阿伯拉罕家长大，阿伯拉罕（克里斯•克里斯托佛森 Kris Kristofferson 饰）为他打造威力最强大的对付吸血鬼的武器和为他注射药物以免他变为吸血鬼。布莱德一直是人类保护神，吸血鬼的克星。当他一次次破坏吸血鬼的好事，猎杀无数吸血鬼后，吸血鬼王佛斯特（斯蒂芬•多尔夫 Stephen Dorff 饰）发誓要除掉这个心头大患。他先是劝说布莱德加入他们的行列，这样的话他们就天下无敌。然后设计弄到布莱德的血，因为这样他就能用他的血实施血祭，唤出血潮，这样所有的人就都会变为吸血鬼。布莱德最终能战胜这个强敌吗？©豆瓣', '韦斯利·斯奈普斯', '斯蒂芬·诺林顿', 7.1, 61902, 'tt0120611', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1625335671.jpg', 0.8, 4.7, 44.7, 39.1, 10.8, '0.004147,-0.061436,-0.395514,0.378997,-0.295951,-0.338140,0.759357,0.028879,-0.178856,-0.093434,0.295182,0.955857,-0.042588,-0.061011,0.108264,0.358692,-0.212858,-0.437248,0.176940,0.001359,-0.497154,-0.069820,-0.531023,-0.467632,0.193166,-0.492071,0.414740,-0.106149,-0.237155,0.007532,0.213483,0.425247,0.390022,0.108259,-0.184254,0.233283,0.025574,-0.325941,0.245191,0.394019,-0.070540,-0.002748,-0.090640,0.318212,-0.198923,0.414892,0.362084,-0.336726,0.108814,-0.566965,0.022258,-0.632753,0.054305,0.230012,0.136895,-0.386083,0.313492,0.139461,-0.057807,-0.089669,-0.019665,0.187792,-0.974109,-0.000548,-0.197826,0.103559,-0.648070,0.195098,-0.218249,0.075105,0.140832,-0.234693,-0.060693,0.259373,0.005490,0.173181,-0.211848,-0.361805,-0.683046,0.193109,0.559713,-0.458015,-0.401887,0.141264,-0.208782,-0.468988,-0.059348,-0.460353,-0.207162,-0.141109,0.484719,0.180487,-0.257627,0.587060,-0.524710,-0.415354,-0.584781,-0.011287,-0.086344,-0.008404,0.056672,-0.346550,-0.214545,-0.208631,-0.353068,0.065892,0.040088,-0.224841,0.590389,-0.581266,0.231242,0.474768,0.293982,-0.426668,0.166825,0.088191,-0.003009,0.042314,-0.040030,0.276881,0.313755,0.331272,0.345832,0.443413,0.437545,-0.038498,-0.182491,0.699590', '1793491', '1308585', '27098364', '30216729');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298128', '西雅图未眠夜', '剧情', '自从妻子去世后，萨姆（汤姆·汉克斯 Tom Hanks饰）就相信自己此生的爱已经走到了尽头，不会再有新的恋情走进心中，他在西雅图和儿子乔纳一起平静的生活。而乔纳，却一直希望爸爸能够开始新的婚姻，重获生活的阳光。抱着这样的想法，乔纳在圣诞夜打电话到电台的情感热线。就这样，萨姆的经历在此夜传遍了各个角落，很多人在倾听他的故事，其中包括安妮（梅格·瑞安 Meg Ryan饰）——一个住在东部的女记者。她善良，温柔，有一个知心的好友，和一个即将结婚的男友。然而，幸福的生活就被这个电话彻底打破了。她的内心有一种冲动，让她一步步地接近这个远在西部的男人。然而，一次次辗转的错过让萨姆和安妮迟迟不能会面。屡次在缘份的天空下失诸交臂的二人，一直为爱而奔波，等待一个遇见的机缘。©豆瓣', '汤姆·汉克斯', '诺拉·艾芙隆', 7.9, 223324, 'tt0108160', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p480953026.jpg', 0.3, 1.6, 23.4, 49.9, 24.8, '0.299221,0.133042,-1.037898,0.729264,-0.153767,-0.321984,0.965180,0.173995,-0.432166,-0.059562,0.096609,0.946615,-0.211505,0.555312,0.438944,0.013832,-0.166747,-0.833999,0.005098,-0.006173,-0.289807,-0.388618,-0.131532,-0.218357,-0.069878,-0.199651,0.762674,0.152885,0.134144,0.583335,0.211574,0.151869,0.076873,0.603263,-0.437528,0.067094,0.180919,0.071310,-0.322075,0.385968,0.124341,-0.134062,-0.083691,0.304358,-0.206611,0.205455,0.612936,-0.283698,-0.237607,0.372639,0.447007,-0.298554,0.037628,0.136809,0.122655,-0.141765,0.147401,0.170718,-0.488150,0.076580,-0.032042,-0.008865,-0.788143,0.007427,-0.150327,0.357718,-0.622433,0.596909,-0.005683,-0.120689,0.216677,-0.401722,0.270476,0.425673,0.041082,0.499860,-0.459038,0.211152,-0.363425,-0.033334,0.890611,-0.024509,-0.208634,0.507348,-0.212246,-0.223718,-0.063384,0.022913,-0.915927,-0.161344,0.276293,0.024395,-0.393855,0.274927,-0.660297,0.159586,-0.236006,-0.122415,0.207286,-0.604829,-0.179291,-0.387207,-0.285737,-0.407552,-0.488699,0.311014,-0.130368,-0.331687,0.813286,-1.018261,0.452204,0.626059,0.252871,-0.507671,0.919810,0.462595,0.176550,-0.131533,0.278779,0.572737,-0.182003,0.370692,-0.004193,0.387761,-0.011949,0.091044,-0.648269,0.594377', '4275444', '1292211', '1291877', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298134', '关山飞渡', '剧情', '十九世纪的美国西部，一辆马车在荒漠中行驶着。车上有九个素不相识的乘客。其中有被镇上驱赶的妓女Dallas（克莱尔·特雷弗 Claire Trevor 饰），一个酒鬼医生Doc Boone （托马斯·米切尔 Thomas Mitchell饰），寻找丈夫的孕妇Lucy Mallory，威士忌商人Samuel Peacock，逃狱为父报仇的Ringo Kid（约翰·韦恩 John Wayne 饰）。一路上危险重重，马车要躲避印第安人的追杀，Dallas要忍受他人的轻视和冷落，除了对她有好感的Ringo。而Ringo则要处理他和警察的关系。孕妇Lucy在半途就要分娩了，醉醺醺的医生能否化险为夷？一段充满了艰险的旅程过后，最后Ringo和Dallas这两个社会边缘人能否走到一起？本片获1940年奥斯卡五项提名，赢得了最佳男配角和最佳配乐两个大奖。©豆瓣', '约翰·韦恩', '约翰·福特', 8.4, 14290, 'tt0031971', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p875109798.jpg', 0.2, 0.7, 12.4, 53.9, 32.8, '0.197091,-0.279855,-0.360915,0.600059,0.074651,-0.423008,0.945631,0.134950,-0.346473,0.043165,0.376926,0.754307,-0.114126,0.065199,0.469740,0.049151,-0.291352,-0.542688,-0.182271,-0.072412,-0.577496,-0.345759,-0.292475,-0.306811,-0.183820,-0.117205,0.527552,0.052872,0.008185,0.644468,0.356164,0.071072,-0.183372,0.411287,-0.306595,0.132144,0.256383,-0.108660,-0.234125,0.389806,0.242956,-0.367231,-0.206570,0.001687,0.156069,0.438196,0.630796,0.100578,0.123361,0.083941,0.149632,-0.354652,0.022463,-0.109443,0.309491,-0.312185,0.116218,0.340797,0.005819,-0.092074,0.070418,0.032523,-0.528841,0.021030,-0.053475,0.144596,-0.808401,0.558263,-0.035308,-0.007105,0.017559,-0.111995,0.259897,0.256967,-0.041772,0.280218,-0.014720,-0.254134,-0.673051,0.284412,0.604999,-0.184113,-0.141748,0.212126,-0.332583,-0.497518,0.090847,-0.280325,-0.622860,-0.197905,0.664427,-0.080452,-0.180649,-0.078769,-0.414735,0.145986,-0.300893,-0.224330,-0.177943,-0.231684,0.037962,-0.609899,0.095286,-0.484579,-0.202514,0.162837,0.146101,-0.062122,0.687558,-0.462241,0.207944,0.739785,0.234756,-0.475572,0.883404,0.142484,0.357610,-0.230164,-0.104613,0.047546,-0.281489,0.269593,0.025772,0.499680,-0.144498,-0.097875,-0.478867,0.230953', '1297606', '1361252', '1783772', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298139', '关于施密特', '剧情', '66岁的施密特先生（杰克•尼科尔森 Jack Nicholson 饰）退休赋闲在家，无所事事的生活让他颇感无聊。每天依旧7点起床，可是陪伴他的只是无聊的字谜游戏和令人生厌的妻子，施密特需要找点事来改变自己的生活，于是他打算资助一位坦桑尼亚的孤儿恩度古，并提笔给他写了第一封信。妻子的忽然离世让他的生活显得更加冷清，他曾至开始想念那个乏味的女人，可是就在这时，他在妻子的换衣间里找到妻子和另一个男人的情书。施密特决定独自驾车去旅行，他去了很多曾经生活过的地方，回忆当年感慨良多。在一时冲动亲吻一位有夫之妇之后，他慢慢的原谅了自己的妻子。女儿的婚姻比自己想像的更糟，平庸的丈夫和不可思议的家庭让他对女儿的未来愈加担忧，然而这一切都非他所能改变。旅途中他从未停止给恩度古写信，在信里，施密特详尽的描述着自己的生活和困惑。当施密特参加完女儿的婚礼，回到家时意外的收到恩度古的回信，看着那些简单的文字和恩度古充满童真的图画，施密特忽然泪如泉涌……', '杰克·尼科尔森', '亚历山大·佩恩', 7.9, 6007, 'tt0257360', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1394116565.jpg', 0.3, 1.1, 22.5, 55.8, 20.3, '0.273199,-0.076190,-0.767600,0.813533,-0.387020,-0.394201,0.891942,0.056895,-0.743932,-0.579717,-0.077087,1.056362,-0.043781,0.688954,0.303980,0.107636,-0.285847,-0.681009,-0.018069,-0.035138,-0.298326,-0.549508,-0.060923,-0.518616,-0.081216,-0.181856,0.455670,0.152945,-0.126031,0.463728,0.076419,0.167864,0.030699,0.660332,-0.527807,0.102048,-0.262909,0.284941,-0.166046,-0.117967,0.305746,-0.140501,-0.224816,0.381755,0.136021,0.293421,0.526507,-0.189654,-0.496498,0.130977,0.389935,-0.196784,-0.025531,0.130636,-0.073884,0.087271,0.119691,0.037235,-0.354144,-0.037098,-0.186600,-0.236332,-0.737276,-0.014917,-0.039234,0.057066,-0.762951,0.476867,-0.156091,0.058975,0.233104,-0.435751,0.204643,0.563856,0.034913,0.550038,-0.252523,0.029770,-0.373239,0.598115,0.616806,0.274626,-0.050054,0.544209,-0.246013,-0.247965,-0.083930,-0.246957,-0.728966,0.134068,0.188607,0.039684,-0.295427,0.147202,-0.436231,-0.115498,-0.069751,-0.278989,0.037023,-0.543415,-0.137777,-0.361726,-0.077306,-0.367692,-0.415521,0.043828,-0.044869,-0.470769,0.658934,-0.792900,0.444413,0.419707,0.251012,-0.650965,0.614771,0.279276,-0.002314,-0.245610,0.022091,0.493226,0.002356,0.273825,0.061596,0.281931,0.065968,0.056