INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298152', '阴阳路2：我在你左右', '喜剧', '琛仔（古天乐饰）、紫少（雷宇扬饰）和长发（丁子峻饰）是广播台灵异节目的当红主持人。老板（谷德昭饰）为达收听率不择手段，没有告知三人当年有人因为作该节目暴毙的事。一日三人夜晚作节目时接到一个名叫Anita（李蕙敏饰）的少女打来的电话，诉说痛失男友的痛苦。不耐烦的长发让Anita想不开就去跳楼，结果Anita就范。此后，三人身边开始不断出现怪事，情况也越来越凶险......©豆瓣', '古天乐', '邱礼涛', 6.6, 11976, 'tt0269987', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558716557.jpg', 1.7, 9.4, 54.8, 25.4, 8.7, '-0.179913,-0.180182,-0.504874,0.442135,0.258511,0.213226,0.577680,0.398103,-0.546378,-0.445161,-0.076604,0.386965,-0.586302,0.169819,0.430083,-0.185550,-0.254607,-0.815465,0.027821,0.108790,-0.042110,-0.162073,0.247511,-0.186658,-0.001973,-0.123662,0.293923,-0.012522,-0.217730,0.674149,0.625739,0.395376,-0.301292,0.461631,0.038157,-0.190720,0.160615,0.173469,-0.102843,0.285386,0.162842,-0.331978,-0.059636,0.000095,-0.004548,0.237631,0.519739,0.027578,-0.461286,-0.073682,0.513601,-0.221904,-0.095658,-0.050525,0.683010,0.056923,0.617431,0.107344,-0.225146,0.204231,0.140312,-0.029658,-0.444615,0.233150,-0.047954,0.285452,-0.230208,0.019087,-0.286156,-0.136476,0.326327,-0.368149,0.375407,0.164160,0.318867,0.147354,-0.066808,0.062327,-0.284877,0.390961,0.715310,0.319018,0.420134,0.259471,0.329180,-0.286631,-0.088123,0.069025,-0.454712,0.466485,-0.008051,0.017914,-0.091917,0.025163,-0.068257,-0.246024,-0.178320,-0.170825,-0.099261,-0.305196,-0.536361,-0.526841,-0.028765,0.291445,-0.294623,0.163570,-0.009170,-0.201724,0.430507,-0.617076,0.350664,0.368327,0.093246,-0.294398,0.437328,0.131639,0.038511,-0.182319,-0.069871,-0.194591,-0.156797,-0.075055,-0.102494,-0.126045,-0.152367,-0.368703,-0.095336,-0.184423', '25723081', '1307186', '25856453', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298155', '富贵兵团', '喜剧', '抗日战争期间，海外爱国侨胞筹集了一笔善款存于瑞士银行，作为抗日经费，提款的密码只有一个代号叫“财神”的人知道，但是“财神”从海外返回祖国时不幸被日军捉住，关在了732号集中营内。为了营救“财神”，中方派出了最优秀的特务天字一号（洪金宝 饰）、天字二号罗森（谭咏麟 饰）、天子三号花木兰（梅艳芳 饰）在集中营外与日军头领周旋收集情报，天字四号华英雄（刘德华 饰）在集中营内接应。华英雄与狱友花生米（陈百祥 饰）、臭鸭蛋（楼南光 饰）、大香蕉（成奎安 饰）、棉花糖（郑则仕 饰）一起合作，与日军大佐（龙方 饰）斗智斗勇。最后在飞虎队成员，以及众多抗日勇士的帮助下天字特务组终于拿到了密码获得了经费。本片的明星阵容非常强大，融合了香港影坛近30位优秀演员参演，曾志伟、莫少聪、苗侨伟、陈勋奇等人也只是有几个镜头。©豆瓣', '洪金宝', '郑则仕', 6.9, 10321, 'tt0097394', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2349321361.jpg', 1.1, 6.2, 52.1, 30.1, 10.5, '-0.212039,-0.168124,-0.487231,0.340544,0.217733,-0.057488,0.281949,0.258724,-0.275752,0.021256,0.399467,0.520862,0.136626,-0.070651,0.035335,-0.094448,-0.322531,-0.589262,-0.369928,-0.442815,-0.205203,-0.341890,-0.309451,-0.055527,-0.135997,-0.095955,0.601993,0.019293,-0.116104,0.285340,0.615485,0.183504,-0.210029,0.021788,-0.023830,0.094097,0.710810,-0.089605,-0.261340,0.290530,-0.454073,-0.240678,0.086056,-0.279191,0.252150,0.325465,0.463391,-0.297464,0.206316,-0.077706,0.062496,0.009500,-0.390194,-0.109459,0.309109,0.281929,0.393350,0.157089,-0.259609,0.346440,0.004088,-0.096833,-0.630595,-0.148828,0.184485,0.114522,-0.443412,0.481831,-0.249975,0.278351,0.279989,-0.189554,0.296548,0.206540,0.154939,0.130974,-0.092492,0.069033,-0.278016,0.444508,0.290633,-0.196674,0.120991,-0.060440,0.150475,-0.640728,0.034276,-0.168793,0.083782,0.028355,0.403838,-0.164561,0.413952,-0.141018,-0.722446,0.117431,-0.072859,-0.124229,0.112381,-0.052715,0.081057,-0.995595,-0.088361,-0.133122,-0.085262,0.260922,0.328869,0.002761,1.059815,-0.459083,-0.063105,0.459849,0.174881,-0.411956,0.574159,0.095415,0.054749,-0.282510,0.082884,-0.174426,0.326726,0.446777,0.194746,0.291857,-0.496366,-0.484439,-0.229924,-0.262934', '3318306', '25863940', '27602116', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298183', '像鸡毛一样飞', '剧情', '首都机场附近的某个小镇上，曾经的诗人陈小阳（廖凡）化身黑鸡养殖场场长，一心做着自己场出产的营养黑鸡蛋全部占领北京市场的梦。某日，小镇迎来陈小阳的昔日好友、失败诗人欧阳云飞（陈建斌）。在欧阳云飞眼里，宁静的小镇神秘怪诞，正与他的心境相契合。孤独、有许多怪癖、患有色盲症的小镇姑娘方芳（秦海潞）爱上了欧阳云飞，并期望对方能带她离开对她来说只有黑白二色的小镇，但欧阳云飞想的只是如何成名。在一张偶然买到具有神奇魔力的盗版光盘的帮助下，欧阳云飞梦想成真，可是怪事也接踵而来。©豆瓣', '陈建斌', '孟京辉', 7.6, 10760, 'tt0329775', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2186476991.jpg', 1.3, 4.8, 27.7, 43.6, 22.6, '0.144988,0.277087,-0.551351,0.420686,-0.218303,-0.109369,0.606415,0.145581,-0.793225,-0.199314,0.121414,0.502674,0.066995,0.347665,0.093941,0.272478,0.154189,-0.194758,0.101100,-0.088911,-0.216440,-0.421565,-0.388660,-0.272503,-0.109776,-0.286183,0.380543,0.362867,-0.104196,0.308360,-0.002554,0.042482,-0.275763,0.601465,-0.138282,0.111749,-0.226305,0.306742,-0.553747,0.369287,-0.160623,0.090733,-0.169799,-0.013970,0.209101,0.159851,0.579580,0.003086,-0.265209,-0.139400,0.288794,-0.361101,-0.134571,0.124913,0.047453,-0.000480,0.372835,-0.181850,0.004362,-0.423582,-0.067447,-0.152524,-0.289839,-0.196410,0.248486,0.241246,-0.312668,0.488209,-0.288229,-0.342493,0.165377,-0.542949,0.234364,0.165833,0.430384,0.362465,-0.026050,-0.050375,-0.560923,0.207126,0.550935,0.288790,-0.220758,0.232995,-0.198973,-0.514285,-0.234175,-0.055813,-0.308996,0.220095,0.366998,-0.084175,-0.287221,0.017739,-0.497906,0.063790,0.222185,0.059080,0.186963,-0.437790,-0.187328,-0.503992,0.078202,-0.548115,-0.115598,-0.070952,0.209443,-0.465343,0.633684,-0.676532,0.329310,0.349283,0.279112,-0.261119,0.283936,-0.135010,-0.120905,0.001759,-0.093901,0.351963,-0.102868,0.346475,-0.098103,0.408821,-0.198539,0.083038,-0.406876,0.561730', '25721544', '26704621', '25810920', '1307561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298189', '极速60秒', '动作', '孟菲斯（尼古拉斯•凯奇 Nicolas Cage 饰）是这个世界上最高明的窃车贼，人们形容他为“gone in 60 seconds”，即只要他盯上的车停在这里，他60秒内便能连人带车一起消失得无影无踪。孟菲斯终究厌倦了窃车贼的虽然惊险刺激但重压在身的生活，宣布金盘洗手 了。但他的弟弟却想步其后尘，不料很快就卷入了一次黑帮危险的交易中。孟菲斯为了救出兄弟，只好重操旧业，答应黑帮一晚内偷来50辆车。不料，警察正在密切监视着孟菲斯。当他偷得最后一辆野马跑车时，警车、警察直升机尾随而至，展开了一场马路追逐……©豆瓣', '尼古拉斯·凯奇', '多米尼克·塞纳', 7.4, 48882, 'tt0187078', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p952878894.jpg', 0.4, 3.5, 37.1, 44.7, 14.4, '0.400065,0.245251,-0.673808,0.505013,-0.176669,-0.400147,0.615855,0.165428,-0.495989,0.146921,0.354403,0.524050,-0.144254,-0.072996,0.426267,0.236070,-0.455093,-0.724147,0.012171,-0.244291,-0.375486,-0.110952,-0.191690,-0.315334,-0.076809,0.170587,0.392990,0.334269,0.245091,0.454244,0.258025,-0.123209,-0.304677,0.525072,-0.196462,-0.008584,-0.019975,-0.092987,0.072299,0.262139,-0.093117,-0.438705,-0.058560,-0.066057,-0.033471,0.128747,0.455348,-0.139134,-0.117425,-0.019617,-0.105221,-0.433831,-0.074593,-0.193655,0.416834,-0.173028,0.147927,-0.192483,-0.216767,-0.161075,-0.038957,0.343208,-0.302596,0.142622,-0.366103,-0.083379,-0.588097,0.318604,-0.198357,0.159328,-0.151155,-0.172775,0.125883,0.059252,0.036149,0.292776,-0.227055,-0.118951,-0.652313,0.178667,0.766572,-0.110338,-0.118607,0.236229,0.145435,-0.111931,0.012693,-0.198415,-0.312098,-0.337539,0.628910,0.048744,-0.397117,0.186335,-0.444637,-0.054780,-0.461414,0.008215,-0.275108,-0.319022,0.004201,-0.532044,0.182072,-0.254842,0.150514,0.366422,-0.066249,0.021771,0.294940,-0.684026,0.284314,0.684650,0.156830,-0.271499,0.575005,-0.179889,0.291929,0.073168,0.081814,-0.067915,0.107100,0.498202,0.306904,0.321118,-0.116999,-0.274471,-0.298900,0.478841', '1297347', '1303462', '1292533', '2078159');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298197', '偷吻', '剧情', '本片是特吕弗著名的“安托万系列”的第三部，但影迷通常忽视短片《Antoine et Colette》误将其认作第二部。23岁的Antoine Doinel（Jean-Pierre Léaud 让-皮埃尔•李奥）从军队逃出后，虽侥幸逃脱惩罚，却因殴打警察入狱，不良记录对 他找工作造成妨碍，他先后做过旅店守门人、私家侦探等职业。过程中，安托万联系上了昔日女友克里斯汀。两人的感情暧昧而不确定。而按客户要求混进一家鞋店盯梢风情万种的老板娘时，他又将其迷上，感情的天平开始在两个女人之间摇摆。©豆瓣', '让-皮埃尔·利奥德', '弗朗索瓦·特吕弗', 7.9, 6234, 'tt0062695', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190633596.jpg', 0.3, 1.6, 23.7, 53.7, 20.8, '0.469301,0.126719,-0.511892,0.404475,-0.021835,-0.020444,0.806663,0.064192,-0.479589,-0.051644,0.159494,0.555508,-0.232182,0.127809,0.228412,-0.011316,-0.221251,-0.767726,0.157237,-0.134915,-0.204340,-0.485080,-0.061953,-0.211069,-0.243660,-0.360789,0.467787,-0.031142,-0.380204,0.349100,0.303780,0.089269,-0.165446,0.349274,0.191269,-0.000510,0.316796,-0.167562,-0.199118,0.384506,0.042629,-0.442330,0.008607,0.012212,-0.110461,0.617053,0.885066,-0.098955,-0.283600,-0.043404,0.439275,-0.163622,-0.179670,0.039723,0.271315,0.124754,-0.016200,0.274920,-0.204708,-0.070637,-0.050495,-0.012317,-0.654703,0.144851,0.095917,0.218265,-0.566583,0.397461,-0.232317,0.128798,-0.117215,-0.143740,0.054910,0.124847,0.323382,0.202981,-0.050013,0.072741,-0.330303,0.139781,0.491288,-0.091879,-0.132417,0.344832,-0.283803,-0.274790,0.001799,-0.067922,-0.396941,-0.051012,0.247944,0.009297,-0.156205,0.100352,-0.352977,-0.145537,-0.350408,0.049933,-0.068222,-0.535534,0.037582,-0.832342,-0.219219,-0.245205,-0.252158,-0.160772,0.305183,-0.352416,0.487219,-0.678055,0.171206,0.586155,0.232820,-0.501697,0.706028,0.197327,0.178971,-0.242053,-0.063288,0.218174,0.237895,0.015212,0.143778,0.233128,-0.009560,-0.154927,0.019483,0.270518', '3326747', '10466639', '3811356', '3804656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298199', '倾城之恋', '剧情', '上海富户白家的养女白流苏（缪骞人 饰）嫁给了一个纨绔败家仔。婚后不久，夫妻便闹翻，白流苏离了婚之后搬回娘家住。她随身携带的钱财被逐渐败落的白家在数年间耗尽，又处处受兄长奚落。为了挣脱日渐困窘的处境，流苏只得考虑再嫁。此时，白家好友徐太太正在为白家七妹宝络牵红线，对方是从英国留学归来的范柳原（周润发 饰）。柳原学成经商，个性风流倜傥、浪漫不羁。在与宝络相亲之日，范柳原却更钟情于白流苏，与她共舞整夜，完全忽略了宝络。白家认为流苏从中作梗，让宝络婚事无望，更加责怪于她。流苏与柳原二人互生倾慕，在香港再次重逢之后，迅速坠入爱河。然而一贯风流的柳原却无结婚的打算，流苏不甘心返回上海。后来柳原不断来电要她去港相会，经不住对柳原的思念，流苏又赴港，两人同居。太平洋战争爆发了，香港沦陷，动乱局势困住了原打算去英国的柳原，两人遂在香港成婚，过着暂且平淡的生活。本片获第25届台湾电影金马奖最佳服装设计奖。', '周润发', '许鞍华', 6.8, 16421, 'tt0087959', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2164764721.jpg', 1.2, 9, 49.3, 31.3, 9.2, '0.038789,0.126201,-0.671550,0.324250,0.033918,-0.619302,0.446940,0.297461,-0.513999,-0.206297,-0.006424,0.638119,-0.085517,0.231011,0.123604,-0.046819,-0.194630,-0.540599,0.121002,-0.083550,0.215937,-0.187403,0.179165,0.099845,-0.151818,0.039834,0.567269,0.198424,-0.124347,0.598967,0.333970,0.190790,-0.364563,0.445429,-0.282397,0.035922,-0.168763,0.287116,-0.502944,0.260009,0.026052,-0.296133,-0.144864,-0.071480,0.201490,0.135748,0.763539,0.056683,0.055656,-0.222494,0.474476,-0.074341,-0.231733,0.303505,0.326231,0.023937,0.053712,0.257200,-0.388660,-0.065685,0.024312,-0.039280,-0.102979,0.310055,0.132148,0.007078,-0.541176,0.380116,-0.179786,-0.046099,-0.211431,-0.385193,0.146415,0.522276,0.139528,0.067326,-0.215453,0.182863,-0.341832,0.469976,0.773473,0.149254,0.105336,0.297997,0.075966,-0.207666,0.223905,-0.279722,-0.505290,-0.182516,0.361057,0.029457,0.011942,0.393520,-0.246335,-0.165620,-0.337122,0.053744,0.187965,-0.380857,0.153147,-0.441202,-0.347190,-0.494760,-0.243444,0.074333,0.300279,0.020913,0.333305,-0.737216,0.199543,0.339171,0.533740,-0.771278,0.364534,0.303045,0.233527,-0.225380,0.077937,0.319399,-0.161028,0.092504,0.056497,0.099796,-0.162956,0.079466,-0.253577,0.061306', '1308035', '6890343', '1300553', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298204', '101忠狗', '喜剧', '罗格于（Ben Wright 配音）和阿尼塔（Lisa Davis 配音）夫妇饲养的大麦町狗庞哥（Rod Taylor 配音）与帕蒂塔（Cate Bauer 配音）喜结良缘，共组成欢乐家庭。没过多久，帕蒂塔生育了十五只小狗。正在一家人享受小狗带来的欢乐之际，阿尼塔的女上司克鲁拉·德维尔（Betty Lou Gerson 配音）打起了坏主意。她正在为制作一件黑白斑点的大衣而发愁，于是她派人绑走了小狗，和其他八十四只大麦町幼犬一同关在乡间的空屋里。发现孩子失踪的庞哥与帕蒂塔，通过狗吠召集全市的狗类，一同找寻自己的孩子，一场小狗救援记就此展开，庞哥与帕蒂塔能否在小狗被宰杀之前营救他们逃出呢……《101斑点狗》是迪士尼1961年推出的第17部经典动画，取材自Dodie Smith 的作品。©豆瓣', '罗德·泰勒', '克莱德·杰洛尼米', 8.5, 58745, 'tt0055254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1686398356.jpg', 0.1, 0.5, 14.2, 45.9, 39.3, '0.344865,-0.592756,-0.343538,0.297079,0.139137,-0.307124,0.451827,0.242664,-0.240143,0.022208,-0.015322,0.555200,-0.178739,0.339530,0.088026,-0.068118,-0.187928,-0.553101,-0.002016,0.144842,0.066555,-0.105023,-0.102712,-0.203684,0.148514,-0.330354,0.408229,-0.238855,-0.043089,0.560842,0.314057,0.036609,-0.638271,0.025265,0.013394,0.215757,0.198106,0.088355,-0.040173,0.099762,-0.312626,-0.069946,0.070675,-0.296462,0.070262,0.302103,0.867656,-0.644973,0.164002,-0.251628,0.160178,-0.239361,-0.150120,-0.017970,0.170305,0.085770,0.243899,0.116497,-0.179230,0.122101,-0.008841,-0.380931,-0.429441,0.015179,-0.091042,0.147522,-0.369295,0.421641,0.014577,0.245382,0.505123,-0.363413,0.163415,0.294057,0.072622,0.544993,-0.034292,0.140623,-0.481570,0.349332,0.493471,-0.154401,0.142782,0.304253,-0.047719,-0.254272,0.166096,-0.094593,-0.208237,-0.262065,0.415690,0.093157,-0.190426,-0.098711,-0.831809,0.031347,-0.125125,-0.289144,0.220161,-0.388053,0.005603,-0.778784,0.254076,-0.251296,-0.076923,0.110047,0.447137,-0.321473,0.516540,-0.542582,0.190591,0.315462,-0.015559,-0.246847,0.672313,-0.255604,0.286582,-0.000590,0.218928,-0.250846,0.176784,0.262555,0.444617,0.216149,-0.065716,-0.133758,-0.679686,0.178528', '5403927', '1309194', '1294917', '5322572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298207', '红色恋人', '剧情', '佩恩（泰德·巴勃考克 Todd Babcock 饰）是生活在上海租界里的一名美国医生，一次偶尔的机会，他认识了国民党特务皓明（陶泽如 饰）。皓明年轻时受十月革命的感召也曾有过伟大的红色理想，但白色恐怖的残酷却让他改变初衷，拿起了屠杀共产党的屠刀。皓明的妻子自杀前把女儿秋秋送进了教会学校，秋秋（梅婷 饰）长大后在共产党人靳（张国荣 饰）的影响下加入共产党并且与靳假扮夫妻隐匿在上海为身患重病的靳治病。秋秋出现在佩恩面前时，佩恩对这个美丽的中国女人一见钟情。然而当他得知秋秋和靳的故事之后，在决定不顾一切的帮助他们的同时，还见证了那段浪漫又凄美的红色之恋。©豆瓣', '张国荣', '叶大鹰', 7.2, 14301, 'tt0192679', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p939585430.jpg', 0.9, 5.4, 43.1, 33.9, 16.7, '0.135191,0.201775,-0.811385,0.675051,-0.136226,-0.566845,0.701654,-0.001176,-0.385802,-0.169221,0.104519,0.547017,-0.041224,0.337105,0.198309,-0.028786,-0.181163,-0.850250,-0.048600,-0.065061,-0.505482,-0.415689,-0.529173,-0.131856,-0.203304,-0.121673,0.450322,0.268542,-0.312440,0.405154,0.564885,0.414770,-0.047632,0.573924,-0.371763,0.125293,0.087035,0.218001,-0.538582,0.148093,0.342092,-0.490885,-0.077352,0.262248,-0.112415,0.220396,0.724676,-0.413361,-0.266716,-0.179559,0.407198,-0.156286,-0.314009,0.156197,0.348688,0.082242,0.014407,0.149862,-0.162464,-0.147407,-0.196745,0.013923,-0.516517,-0.063469,0.065662,0.132632,-0.837299,0.529855,-0.184352,0.097648,0.051122,-0.231919,0.484703,0.509960,0.133048,0.310979,-0.331323,0.090354,-0.477108,0.578528,0.745036,0.053013,-0.195542,0.183507,-0.510242,-0.255626,0.036576,0.042060,-0.457594,-0.008112,0.028097,-0.389839,-0.239292,0.251127,-0.589200,-0.224192,-0.437309,0.199683,0.119108,-0.257088,-0.084630,-0.474472,-0.185373,-0.463300,-0.347944,0.202657,-0.182241,-0.286348,0.909377,-0.838362,0.387488,0.315581,0.520167,-0.373782,0.794809,0.226585,0.278853,-0.126086,-0.044943,0.307673,-0.068255,0.088849,0.166451,0.418715,0.147142,-0.065798,-0.410656,0.496040', '21360412', '1308609', '26021055', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298214', '猛鬼街3', '惊悚', '在梦境中杀害孩子们的弗莱迪回来了。少女克里斯汀最近会陷入一个持续的噩梦中，她在那所自己制作的梦中房屋里险些死于弗莱迪之手——尽管在外人看来，克里斯汀更像是梦游或者自杀。于是，克里斯汀被送到了医院进行治疗，这里有多位和她一样受噩梦困扰的少年。曾经从弗莱迪手中逃脱的南茜（希瑟·兰根坎普 Heather Langenkamp 饰）如今已是一位医生，她来到医院帮助克里斯汀和众少年，并且发现后者拥有将别人带入她梦中的能力，在医生科尔曼的协助下，南茜等人进入了克里斯汀的梦境，孩子们发现在梦中自己可以拥有不同寻常的能力，南茜随即准备带领他们与弗莱迪在梦中一战，熟料，古板的医院方面仍然认为孩子们不过是梦游和受臆想困扰……©豆瓣', '希瑟·兰根坎普', '查克·拉塞尔', 7, 6136, 'tt0093629', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2177124459.jpg', 0.9, 5.1, 48.4, 33.5, 12.1, '0.205809,0.064280,-0.478342,0.305423,-0.350182,-0.073382,0.970390,-0.060928,-0.839447,-0.525997,0.330685,0.864528,-0.031331,0.505075,0.331676,0.044936,-0.568299,-0.775648,-0.253811,-0.195903,-0.613799,-0.374191,-0.153432,-0.114579,-0.040525,-0.474379,0.507650,-0.068204,-0.233725,0.213523,0.015467,0.511033,-0.152623,0.429580,-0.008447,0.189149,0.056540,-0.196504,-0.186048,0.604105,0.069161,-0.141662,-0.182041,0.351788,0.160965,0.075220,0.733389,-0.383830,-0.098378,-0.243594,0.073817,-0.203904,-0.027990,0.248202,0.028390,-0.064079,0.402554,-0.026904,-0.299704,0.065332,0.049895,-0.086645,-0.810498,0.145197,0.190265,0.303110,-0.658476,0.068783,0.117555,0.125960,0.173076,-0.004060,0.124186,0.198337,0.314468,0.520191,-0.171157,-0.258023,-0.488353,-0.027952,0.551266,-0.247739,-0.256219,0.401178,-0.227852,-0.282623,-0.226491,0.000695,-0.444275,0.077486,0.281134,0.122426,-0.437697,0.487228,-0.226633,-0.152322,-0.333234,-0.103477,-0.365211,-0.265153,-0.229452,-0.581591,0.147812,-0.223342,-0.374164,-0.068332,0.023527,-0.391499,0.434783,-0.921110,0.518777,0.569470,0.215328,-0.048391,0.474571,-0.055912,0.219790,-0.130633,0.018527,0.451574,0.104201,0.156846,0.182416,0.148381,-0.150075,0.159724,-0.576745,0.343842', '2988294', '27006896', '1309172', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298241', '玉女风流', '喜剧', '麦克纳马拉（詹姆斯·贾克内 James Cagney 饰）是可口可乐公司西德分部的总经理，长久以来，他默默地为公司辛勤工作，业绩屡创新高，是上司眼中的红人，亦是最有希望获得晋升的职员。某日，上司致电麦克纳马拉，告知他自己的女儿斯嘉丽（帕梅拉·蒂芬 Pamela Tiffin 饰）即将前往西德游玩，希望麦克纳马拉能够成为她的监护人。然而，让麦克纳马拉没有想到的是，斯嘉丽尽管年纪轻轻，个性却极其热情奔放，来西德没多久，便同一位名叫奥托（豪斯特·巴奇霍兹 Horst Buchholz 饰）的男子坠入了爱河，他们不仅结了婚，斯嘉丽的腹中甚至还有了奥托的骨肉，更糟糕的是，奥托来自于东德，是一位根正苗红的社会主义者，鄙视资本主义的一切。就在这个节骨眼上，麦克纳马拉得知上司很快就要前往西德接他的女儿。©豆瓣', '詹姆斯·卡格尼', '比利·怀尔德', 8.9, 16294, 'tt0055256', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1082838488.jpg', 0.2, 0.7, 7.5, 37.5, 54.1, '0.168661,-0.038014,-0.610333,0.696432,-0.295349,-0.478540,0.499878,0.300840,-0.653538,-0.288250,0.193277,0.867490,-0.094547,0.238055,0.492451,0.078737,-0.102600,-0.536532,-0.097817,-0.142484,-0.197518,-0.721420,-0.406565,-0.170053,-0.148740,-0.464803,0.690586,0.013398,-0.191180,0.204936,0.454862,0.482915,0.276548,0.559876,-0.358567,-0.033771,0.303975,-0.149083,-0.191699,0.279980,0.079072,0.020775,-0.038906,0.108478,0.066997,0.341366,0.129203,-0.018463,-0.034955,-0.159093,0.449829,-0.087059,0.136112,0.103759,0.287545,-0.290618,0.085970,0.294524,-0.285888,-0.019329,0.085592,-0.121476,-0.749145,0.053900,-0.057726,0.301180,-0.763963,0.258748,-0.325440,-0.188128,0.075200,-0.246535,0.085575,0.319834,-0.024006,0.506393,0.215634,0.125365,-0.499698,0.013616,0.645077,0.164291,-0.291835,0.283312,-0.250684,-0.185271,0.178369,-0.216781,-0.435416,0.017806,0.132674,0.121615,0.113347,0.276076,-0.275168,-0.130528,-0.477374,-0.191562,0.151005,-0.358093,-0.007556,-0.484576,-0.031155,-0.372821,-0.182929,-0.052613,0.227648,-0.285947,0.668167,-0.879442,0.151687,0.372198,0.231797,-0.581583,0.744602,0.218984,0.143302,-0.365824,-0.064034,0.265544,0.286188,-0.026143,-0.135219,0.311201,0.094205,-0.471886,-0.019995,0.352841', '34968329', '1783461', '27056396', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298244', '天罗地网', '爱情', '烈日当头，纽约大都会艺术博物馆，一幅正在展出的印象派大师莫内的无价名画失窃。高明的盗窃手段，加上因高温完全失效的红外线监控系统，都让这起神秘的失窃案更加扑朔迷离。亿万富翁托马斯·克劳恩（皮尔斯·布鲁斯南 Pierce Brosnan饰），一位富可敌国的上流富商兼收藏家。当金钱再也不能带给他任何满足感时，唯有那些金钱买不到的东西才能引起他的兴趣，比如这件无价之宝。美貌聪慧的女调查员凯瑟琳·班宁（蕾妮·罗素 Rene Russo饰）负责全权处理此失窃事件。与此同时，警方也派出了精明的迈克尔·麦克甘（丹尼斯·利瑞 Denis Leary饰）警官调查此案。班宁与麦克甘不约而同地将克劳恩列为头号嫌疑人，而克劳恩更被这位与众不同的女子所深深吸引。本片改编自1968年诺曼·杰威森执导的电影《托马斯·克朗事件》，此次由曾执导过《虎胆龙威》等知名动作片的导演约翰·麦克蒂尔南重新演绎这段经典好莱坞浪漫爱情片。', '皮尔斯·布鲁斯南', '约翰·麦克蒂尔南', 7.1, 7967, 'tt0155267', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2354690405.jpg', 0.7, 4.6, 44.2, 38.8, 11.6, '0.297913,-0.177796,-0.501900,0.454023,0.108613,-0.168840,0.653323,0.067148,-0.433566,-0.477916,0.125820,0.564032,-0.364938,-0.064610,0.482487,0.115858,-0.444847,-0.480740,-0.125680,-0.326862,-0.004692,-0.516028,-0.447236,-0.154385,0.025913,-0.241897,0.290330,0.084470,-0.328578,0.285768,0.319185,0.575743,0.023088,0.046123,0.214447,-0.197280,0.351366,-0.106644,-0.436565,0.252463,0.104701,-0.185516,-0.008549,0.065985,0.010087,0.151214,0.341612,-0.247322,-0.051490,-0.022852,0.465848,-0.150827,0.278002,-0.051311,0.056608,-0.015022,0.099669,0.209551,-0.268865,-0.077961,0.234741,-0.072073,-0.710460,-0.058276,0.244075,0.146451,-0.215890,-0.022128,-0.279348,0.070271,-0.163526,-0.088847,0.135663,-0.032386,0.307654,0.024489,0.181323,0.026959,-0.225728,0.506244,0.121557,0.239723,-0.219945,0.130393,-0.186468,-0.538129,-0.080996,-0.194819,-0.343481,0.210818,0.637995,-0.136055,0.363727,0.374145,-0.387847,-0.247290,-0.340183,-0.161190,-0.083435,-0.040948,0.160257,-1.066504,-0.238914,-0.327863,-0.050206,-0.297205,0.440427,-0.175016,0.633645,-0.236000,0.237264,0.440701,-0.125356,-0.186268,0.314005,0.014293,0.027187,-0.146916,-0.567587,0.218055,0.488828,0.197472,-0.141518,0.353180,0.334995,-0.522023,-0.020647,0.