INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298245', 'K-19：寡妇制造者', '剧情', '影片是根据真人真事改编的，K19是苏联第一艘战略核潜艇。影片导演凯瑟琳·毕格罗是首位奥斯卡最佳女导演奖获得者。亚里克西（哈里森·福特 Harrison Ford 饰）船长，在冷战最为紧张的时刻接到命令接替原船长米克黑尔（ 连姆·尼森 Liam Neeson 饰）出任核动力导弹潜艇K-19的指挥官。亚里克西的任务是不惜一切代价，尽快将这艘维护不当的潜艇投入作战戒备，执行其处女航行。但是两人和全艇忠诚的官兵们压根也没想到他们会去执行什么任务。他们也无法料想到失败的代价对于他们以及全世界会意味着什么。那时，一个核反应堆发生故障，一个危险的燃料棒即将溶融、发生核爆炸，这将肯定使艇上所有人员葬身海底。当时他们在北冰洋底游弋，是全体船员们的勇敢，以及船长对国家和对船员们的职责感最终挽救了K-19，避免了一场即将发生的核灾难。©豆瓣', '萨姆·斯普卢尔', '凯瑟琳·毕格罗', 7.8, 12859, 'tt0267626', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1973385941.jpg', 0.3, 1.7, 26.6, 51.3, 20.1, '-0.042960,-0.013947,-0.831534,0.470220,-0.113079,0.113168,0.604596,-0.133825,-0.386315,-0.012641,0.478175,0.985687,-0.013151,-0.449170,0.369482,0.063101,-0.482920,-0.528173,-0.335308,0.085209,-0.315583,-0.733770,-0.156475,-0.267185,-0.028412,-0.399084,0.720584,0.049218,-0.017664,0.269708,0.623060,0.394846,-0.014060,0.546565,0.176377,-0.203209,0.248330,-0.521595,-0.159253,0.119192,-0.087141,-0.000921,-0.076162,0.164900,0.135529,0.413326,0.507508,-0.325423,-0.369556,-0.109422,0.120651,-0.553803,0.328370,-0.025210,0.343833,-0.091232,-0.254565,0.287520,-0.024062,0.004204,0.080071,0.126709,-0.977151,-0.310300,0.090345,0.233488,-0.449677,0.051988,-0.482582,0.181393,0.126387,-0.101800,0.420748,0.687162,0.270055,0.011515,-0.400883,0.078363,-0.501486,0.167579,0.871657,-0.121004,-0.323909,0.164919,-0.111271,-0.487637,-0.348401,-0.412786,-0.440012,0.212445,0.170668,0.164470,0.074016,0.140933,-0.555959,-0.042923,-0.391280,-0.724512,-0.210895,-0.220126,0.075227,-0.813638,0.245648,-0.421019,-0.253185,0.144342,0.081789,-0.162579,0.895476,-0.588754,0.059362,0.603897,-0.005018,-0.443910,0.395355,0.289347,0.281123,-0.327276,0.165179,0.084182,-0.028356,0.383456,-0.168974,0.349449,0.439394,-0.304614,-0.052316,0.292404', '30163500', '25928048', '1294941', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298248', '安德烈·卢布廖夫', '剧情', '15世纪初，俄罗斯动荡时期。著名圣像画家安德烈·卢布廖夫（安纳托里·索洛尼岑 Anatoli Solonitsyn饰）在大公的邀请下前往莫斯科为教堂作画，受到了贵族式的服务与对待。然而，卢布廖夫却身处在一个饱受鞑靼人铁蹄践踏和充满灾难残杀的悲惨时代。目睹了黎民百姓在大公暴政下的水深火热，卢布廖夫毅然离开教堂返回修道院。不久，卢布廖夫被迫再度回到莫斯科进行圣像创作。然而面对居民被无辜的残杀，教堂在战火中被无情的摧毁，卢布廖夫再次陷入艺术与现实巨大反差的质疑之中，拒绝继续作画。1423年，鞑靼人的军队终于被赶出俄罗斯的大地。在经历了炮火、鲜血的锤炼洗礼后的卢布廖夫，终于完成了传世名作《三位一体》的创作。由苏联电影大师安德烈·塔科夫斯基执导的旷世史诗巨作《安德烈·卢布廖夫》，用塔式特有的诗化电影语言和如历史壁画一般的浓重画笔，呈现了15世纪俄罗斯著名圣像画家安德烈·卢布廖夫漂泊与抉择的一生。本片荣获1969年第22届戛纳电影节费比西奖。', '安纳托利·索洛尼岑', '安德烈·塔可夫斯基', 9.1, 13548, 'tt0060107', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1209470213.jpg', 0.6, 0.9, 7, 28.4, 63.1, '0.005733,0.146260,-0.690145,0.520882,0.420999,-0.326740,0.722150,0.092711,-0.207158,-0.258697,0.267114,0.823539,-0.396846,0.055032,0.619355,-0.057875,-0.403664,-0.831043,-0.225451,-0.041429,-0.130982,-0.321736,-0.039402,0.065452,-0.196730,-0.506911,0.768363,0.273554,-0.261955,0.292864,0.134216,0.655507,0.109568,0.242335,-0.011468,-0.114199,0.262865,-0.129684,-0.564248,0.204878,-0.160599,-0.188640,-0.210807,0.061576,-0.175861,-0.002990,0.552100,-0.594279,0.346394,-0.014829,0.447521,-0.238023,-0.157037,0.243881,0.069181,0.158324,-0.019135,0.146209,-0.210646,0.050380,0.037841,-0.508528,-0.393121,-0.364110,0.025707,-0.050254,-0.620284,0.529154,0.031083,0.267337,-0.129168,-0.022053,0.273838,0.188814,0.402921,0.685389,-0.068702,-0.159286,-0.539016,0.277925,0.345056,0.060541,-0.718859,-0.051100,-0.194920,-0.350236,0.124623,-0.706351,-0.424224,0.002278,0.403640,-0.231111,0.063109,0.616036,-0.857168,-0.132582,-0.504566,-0.549895,0.264696,-0.146006,-0.270569,-0.932712,-0.263189,-0.270305,0.065466,0.180221,0.140243,-0.153552,0.735290,-0.494501,0.469595,0.263863,0.307174,0.000148,0.647812,-0.139936,-0.103486,0.112362,0.190110,0.780014,0.018818,0.348968,-0.009919,0.197514,-0.101395,-0.024005,-0.090965,0.638081', '1308069', '1780122', '10439358', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298252', '胜者为王', '惊悚', '在三联帮有杰出表现的山鸡（陈小春 饰）即将迎娶日本帮派山田组的头目草刈一雄（千叶真一 饰）的女儿菜菜子（安雅 饰）。身为好友的陈浩南（郑伊健 饰）及一众香港的黑帮头目也到日本出席了山鸡的婚礼。三联帮帮主的儿子雷复轰是个有能之士，对父亲的帮派事业毫无兴趣。山鸡成了他心中继承位置的最佳人选，却遭到了同是帮内头目的忠勇伯的反对，他决意要与山鸡争取帮主的地位。两人明争暗斗，忠勇伯这时被袭击了，他认定山鸡指使了人攻击他。俩人再次因为有关政府的方案而互相对立，帮派内讧。山鸡除了事业上的不如意，妻子菜菜子更被父亲手下强奸了。山鸡正处在水深火热之中，陈浩南前往台湾助山鸡一臂之力，雷复轰却为了帮内团结要把让忠勇伯当帮主。忠勇伯竟在这个时候被杀了，山鸡再次被嫌疑……©豆瓣', '郑伊健', '刘伟强', 7.4, 50268, 'tt0265739', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2614053953.jpg', 0.8, 3.9, 36.3, 41.2, 17.8, '0.235900,0.089941,-0.563295,0.366157,-0.030810,-0.108518,0.317938,0.630385,-0.591002,-0.020869,0.142658,0.585493,0.202190,0.060641,0.085638,-0.184787,0.060384,-0.812989,-0.111479,0.067756,0.014468,-0.299660,-0.078146,-0.358099,-0.256538,0.076723,0.520584,-0.012920,-0.098758,0.468153,0.463626,0.390344,-0.010134,0.455299,-0.120018,0.031274,0.221463,-0.225702,-0.346505,0.191224,-0.174392,-0.457297,-0.038329,0.402928,0.010194,0.434332,0.565031,-0.060234,-0.002959,-0.616139,-0.123419,-0.187331,0.095304,0.200639,0.752407,-0.122565,0.127744,0.468946,0.021243,-0.125190,0.114624,-0.102980,-0.881409,-0.068926,0.175604,0.076143,-0.745970,0.582031,-0.227620,-0.185688,0.238168,-0.026044,0.353271,0.380922,0.263692,0.112335,-0.080773,0.300500,-0.547400,0.068641,0.748770,-0.048556,0.454880,-0.160840,0.114565,-0.372023,0.024777,-0.539061,0.003790,-0.128217,0.508480,-0.141095,-0.075167,0.174171,-0.554470,-0.152554,-0.141139,-0.051366,0.157516,-0.322486,0.019328,-0.340975,-0.124163,-0.350508,-0.323451,-0.019334,0.374074,-0.020278,0.823009,-0.974900,-0.100798,0.475148,0.319860,-0.522354,0.418819,0.215758,0.051988,-0.304683,-0.162943,-0.545684,0.336066,0.131579,0.336621,0.223840,-0.020907,-0.286223,-0.206307,0.056550', '1877596', '35030151', '1793491', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298272', '地下情', '剧情', '香港少女阮贝儿（温碧霞）和来自台湾的廖玉屏（金燕玲）、赵淑珍（蔡琴）皆以成名为人生目的，但现实证明她们离当明星的生活仍有一段不短的距离。三人在酒廊偶识米铺少爷张树东（梁朝伟），不久阮贝儿与其发展成同居关系。赵淑珍不明原因的死亡引来警探蓝振强（周润发），但他的所谓调查徒 具形式。廖玉屏无法安然面对赵淑珍的离去，悲痛引来张树东对其肉体的安抚，不料不小心致其怀孕。其后廖玉屏的震惊没能让张树东在取舍问题上有眉目，彼此发现所谓爱人只是爱己。而蓝振强临死前的一段话更让他们将自己看清（同他人发生关系是觉得多个人的无聊总好过一个人），可是他们依旧没有独自面对没有希望的日子的勇气。©豆瓣', '周润发', '关锦鹏', 7.4, 6958, 'tt0090922', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2336728731.jpg', 0.6, 3.4, 35.2, 44.5, 16.3, '0.392843,0.012861,-0.660046,0.509603,-0.024436,-0.104040,0.922127,0.022749,-0.555772,-0.572460,-0.051354,0.434241,-0.203077,0.112473,0.023867,-0.335686,0.079608,-0.526857,0.132786,-0.140129,-0.237853,-0.684594,-0.113929,-0.394038,-0.456396,0.100560,0.565493,0.232734,-0.174621,0.435401,0.272896,0.092475,-0.190579,0.648560,0.046833,0.105487,-0.063946,0.341432,-0.470759,0.011862,0.426468,-0.488159,-0.387273,0.303871,-0.158009,0.309005,0.441864,0.075746,-0.303933,0.104271,0.209304,-0.251358,0.053705,0.022224,0.271951,-0.237572,0.170411,0.162884,-0.106690,-0.123250,0.204840,0.150262,-0.769166,0.170905,0.243041,0.262109,-0.331088,0.241629,-0.123993,-0.041948,-0.078689,-0.298183,0.374049,0.478398,0.546834,0.257961,-0.162394,0.098215,-0.618830,0.299815,0.945371,0.178756,-0.230255,0.303330,-0.206527,-0.513101,-0.198500,-0.244372,-0.572172,0.184049,0.055489,0.268989,-0.196675,-0.033188,-0.307881,-0.040401,-0.128377,0.002422,-0.047093,-0.292850,0.248218,-0.311284,-0.368836,-0.652491,-0.365892,0.045780,0.089671,-0.620186,0.769640,-0.782240,0.121245,0.109766,0.439007,-0.795616,0.806474,0.274558,0.238033,-0.322662,0.122407,0.291301,0.015391,0.013647,0.356154,0.066407,-0.147688,0.019653,-0.141641,0.270313', '25721544', '1293265', '1296370', '1303036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298291', '怪医杜立德', '喜剧', '杜立德医生（艾迪·墨菲 Eddie Murphy饰）拥有一个幸福的家庭，一个小有名气的诊所，没有人知道他曾经有着异常的经历，那就是能够听懂动物的说话。小时候，他就和猫狗马驴之类的动物交谈过，了解动物的需要，知道它们的心事。随着岁数增长，杜立德医生早已失去了这个“特异功能”。然而，他却因为一次开车差点撞上路边的小狗，似乎又能听到了小狗骂他笨蛋。这下子杜立德的生活可热闹起来了，因为他沉睡已久的动物语言天赋又被重新唤醒，阿猫阿狗不但成为了他的朋友，还主动找上门来找杜立德医生看病。诊所变成了熙熙攘攘的动物世界，而生意也因此陷入低迷。人人都以为杜立德疯了，家人对他的行为也非常的不理解，杜立德医生和他的诊所面临着不小的挑战。©豆瓣', '艾迪·墨菲', '贝蒂·托马斯', 6.9, 13945, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2329693960.jpg', 0.6, 4.7, 52.1, 33.3, 9.4, '0.496102,-0.058235,-0.484426,0.597666,-0.312372,-0.265168,0.991123,-0.015775,-0.492054,-0.215119,-0.010010,0.671444,-0.150273,0.240290,0.149019,0.003801,-0.027251,-0.372924,0.249143,0.257896,-0.181876,-0.364943,-0.331646,-0.259008,-0.055955,-0.312946,0.351940,-0.107636,-0.184284,0.469428,0.002034,0.096781,0.361104,0.533162,-0.336854,0.315496,0.046378,0.184528,0.131960,-0.068593,0.195037,0.015519,0.123391,0.227771,-0.188137,0.143550,0.399820,-0.266700,-0.448476,-0.196883,0.243312,-0.196424,0.104925,0.149795,0.449248,-0.155878,0.335687,-0.125308,0.048452,0.114607,-0.011889,0.373393,-0.730418,0.051690,-0.090810,0.276430,-0.603794,0.335090,0.128283,0.112660,-0.185057,-0.349373,0.382456,0.080494,0.093925,0.559304,-0.079587,-0.132796,-0.953967,-0.030387,0.677436,-0.192708,-0.273125,0.647097,-0.513643,-0.680514,0.043547,-0.364654,-0.443455,0.029434,0.076359,-0.066656,-0.946234,0.026456,-0.237256,0.219256,-0.034614,-0.370275,-0.280577,-0.506536,-0.005240,-0.318784,-0.044500,-0.476458,-0.285994,-0.050086,0.023099,-0.339060,0.695325,-0.998335,0.120826,0.641307,0.242629,-0.453546,0.743710,-0.058596,-0.191431,-0.249478,-0.114125,0.113765,0.013751,0.423263,0.367753,0.338121,0.123606,-0.236508,-0.309141,0.655151', '1296370', '1308755', '3055049', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298297', '莉琪的异想世界', '喜剧', '莉琪（希拉里·达芙 Hilary Duff饰）的欧洲之行真是充满“离奇”！本来她是一名在学校屡屡出丑的女生，和同伴来到意大利旅行之后，神奇的经历就纷至沓来。都怪莉琪长得太像意大利的歌星伊丽莎白，伊丽莎白的情歌对唱搭档保罗，把这个小女生当成了乐坛红人。在保罗的安排下，莉琪作为“伊丽莎白”的星途迅速铺开，她亦以自己的魅力征服万千歌迷，然而，上帝真的如此眷恋莉琪吗？少不更事的莉琪，没想到自己已经陷进了一场阴谋当中。幸好，莉琪还有一帮守望相助的朋友，他们在合力保护着莉琪不受伤害，莉琪在美妙的梦境中醒来时，会发现最真实最宝贵的，是身边可爱的友人。©豆瓣', '希拉里·达芙', '吉姆·弗尔', 6.8, 19622, 'tt0306841', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204980160.jpg', 0.9, 7.2, 52, 30.1, 9.8, '0.440970,-0.054776,-0.580056,0.630697,-0.233233,-0.225212,0.844535,-0.117772,-0.352526,-0.134445,0.566262,0.824857,-0.325062,0.326282,0.447893,0.092357,-0.358636,-0.796949,-0.295402,-0.178249,-0.196320,-0.475962,-0.399236,0.025213,-0.134739,-0.409168,0.641814,-0.226068,-0.115417,0.266443,0.405725,0.148844,0.000238,0.380510,-0.129892,0.223463,0.234333,0.055630,-0.284215,0.062404,0.080647,-0.208510,-0.077929,0.301880,-0.331339,-0.020942,0.586688,-0.348396,0.041157,-0.137367,0.547654,-0.371712,-0.021508,0.073085,-0.014244,-0.179705,0.338661,-0.085197,-0.231261,0.140985,0.120655,-0.031891,-0.699702,0.275887,0.159142,0.043394,-0.373664,0.411118,0.160210,-0.163622,0.361126,-0.324304,0.110133,0.198082,0.170990,0.401832,-0.095684,0.142881,-0.364348,0.129150,0.790700,0.069593,-0.262708,0.425621,-0.234458,-0.378099,0.011572,-0.215946,-0.699908,0.167385,0.205264,-0.123258,-0.040432,0.278959,-0.620344,-0.044107,-0.137988,-0.118845,0.080070,-0.479629,-0.140733,-0.468880,-0.249037,-0.554427,-0.344959,0.003927,0.055047,-0.397861,0.796898,-0.876772,0.098275,0.676851,0.019094,-0.246886,0.636808,0.194048,-0.205089,-0.025265,-0.391635,0.370231,-0.072034,0.124713,0.010561,0.411257,-0.012499,-0.173022,-0.521685,0.466671', '30162520', '4275444', '4817024', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298299', '危险性游戏', '剧情', '萨巴斯丁（莱恩•菲利普 Ryan Phillippe 饰）和凯瑟琳（莎拉•米歇尔•盖拉 Sarah Michelle Gellar饰）本来是两个家庭的孩子，因为父母的结合成为了两姊弟。二人为了私心开始了一场游戏，如果萨巴斯丁输了，他的豪华跑车将归凯瑟琳所有；如果他赢了，凯瑟琳将要为他提供一夜服务。这个游戏就是，萨巴斯丁必须把校长的女儿安妮（瑞茜•威瑟斯彭 Reese Witherspoon 饰）搞到手。尽管他上过曼哈顿地区的无数女孩，但是对于安妮，却有着一定的难度——她曾经在《十七岁》杂志上发表文章声称，要把童贞留到新婚夜。对于这次有难度的猎艳行动，萨巴斯丁当然全力以赴，然而让他意外的是，游戏变得越来越复杂，超出了他的预计。©豆瓣', '莎拉·米歇尔·盖拉', '罗杰·昆宝', 6.5, 16657, 'tt0139134', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1844649230.jpg', 2.3, 12.6, 50.9, 26.1, 8.1, '0.359258,0.311754,-0.651011,0.475691,-0.294092,-0.233649,0.659554,0.003759,-0.469101,-0.132561,-0.073492,0.647772,-0.295788,0.310282,0.156558,0.133668,-0.232588,-0.524624,0.047087,-0.043379,-0.213255,-0.780200,-0.228669,-0.185163,-0.167241,-0.239634,0.514478,-0.036825,-0.095845,0.179480,0.433185,0.318855,0.247085,0.627680,-0.009822,-0.037734,0.007395,-0.043855,-0.115586,0.212857,0.330804,-0.172725,0.054017,0.257027,0.301546,0.300270,0.464028,-0.180357,-0.237629,0.025659,0.318570,-0.194575,-0.047004,0.259200,0.044824,-0.107470,0.107690,0.198110,-0.255979,-0.071037,0.231488,-0.187724,-0.877835,0.186185,0.246635,-0.102315,-0.665255,0.326704,-0.360398,-0.035635,0.012833,-0.237816,0.036167,0.435238,0.419766,0.152252,-0.163940,-0.090661,-0.674581,0.026427,0.736329,0.129577,0.015666,0.383458,-0.154148,-0.473642,-0.224574,-0.107744,-0.444564,0.307123,0.428951,-0.085921,0.051314,0.127198,-0.619433,-0.248780,-0.380571,-0.412249,-0.077729,-0.444945,-0.005664,-0.361809,0.076121,-0.524359,-0.438331,-0.051200,0.198063,-0.677342,0.842817,-0.941666,0.110301,0.559636,0.259886,-0.565998,0.470282,0.019148,0.328735,-0.165249,0.001992,0.069983,0.065682,0.108304,0.341209,0.405865,0.162598,-0.322014,-0.147237,0.993698', '1783461', '1793491', '6874741', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298308', '巴顿将军', '剧情', '1943年3月，巴顿（乔治·C·斯科特 George C. Scott 饰）率美军在法属摩洛哥登陆后临危受命，担任美军在北非的第二军团长，性格强势、钟情古典文化又熟稔战史相信灵魂转世的巴顿很快用铁血律令扭转了北非部队的散漫风格，连番激战后与蒙哥马利统率的英军合力将“沙漠之狐”隆美尔赶出了北非。随后升任第7集团军司令的巴顿筹划占领西西里，战斗中巴顿抢在蒙哥马利之前连下军事重镇，立下赫赫战功的同时饱受非议，部下指责他用士兵的生命换取荣耀，在成功占领西西里后，巴顿因严厉训斥一位士兵遭到媒体的谴责，铁血将军只得公开道歉……然而长于战争的巴顿又迎来了新的重任……©豆瓣', '乔治·C·斯科特', '富兰克林·沙夫纳', 8.2, 33505, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1029244884.jpg', 0.3, 1.2, 17.2, 52.5, 28.8, '-0.006159,0.180432,-0.861009,0.654511,0.215745,-0.276368,0.209413,0.082811,-0.600451,0.153672,0.224997,0.533641,0.188221,-0.361194,0.489781,-0.317077,-0.532294,-0.783365,-0.332406,-0.087932,-0.121866,-0.556930,-0.143123,-0.328789,0.069489,-0.688826,0.566140,-0.054828,-0.246898,0.422772,0.146453,0.461900,0.307265,0.427330,0.168427,0.127609,0.281823,-0.473800,-0.432058,0.336645,-0.276208,-0.154466,-0.119414,-0.098610,-0.005587,0.392746,0.441431,-0.573707,0.358689,-0.275008,0.215769,-0.157907,0.025117,0.143311,0.429876,0.222362,-0.250249,0.237923,-0.048099,0.085565,-0.190196,-0.110580,-0.421739,-0.188967,-0.258154,0.002620,-0.452329,0.716285,-0.300001,0.524151,0.092503,-0.211179,-0.059012,0.674919,0.328541,0.210276,-0.012988,0.306536,-0.092963,0.037966,0.525299,-0.151587,-0.481926,-0.353058,-0.074384,-0.105659,0.427586,-0.710363,-0.190206,-0.156969,0.226074,-0.103737,0.532156,0.486963,-0.561743,-0.139377,-0.548307,-0.374482,0.102898,-0.129705,-0.068187,-0.809802,-0.142283,-0.353897,-0.137753,0.166681,0.189655,0.257913,0.773696,-0.736679,0.109264,0.263013,0.455777,-0.367864,0.202298,0.358245,0.312938,0.002125,0.137772,0.660167,0.241166,0.555770,0.210196,0.225403,-0.244845,-0.296430,0.059442,0.117481', '1826173', '1316511', '1297715', '26356488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298320', '疯狂店员', '喜剧', '美国的小众独立电影，讲述了便士多店小店员但丁（布莱恩·奥哈罗兰 Brian O''Halloran 饰）郁闷抓狂的一天。过了睡眠质量极差的一晚后，但丁大清早被老板叫去加班。这只是倒霉的一天的起始，接下来，还有更多麻烦事情接踵而至，开店门、喷标语、遇见唠叨的反吸烟人士阻挠店面生意。一个头两个大的但丁，还要和前来店铺的女朋友维罗尼卡（玛丽莲·吉格洛尔蒂 Marilyn Ghigliotti饰）交流性生活经验。结果落得个不欢而散，因为女朋友拥有过的性伴侣数目实在令但丁叹为观止。麻烦事还是一桩接一桩，这时前女友的到来令但丁的心狠狠振作了一下。他的艳遇到了，似乎终于可以扫走霉运。可是，卫生间内的“奇遇”，又摧毁了这件美好的事情。©豆瓣', '布莱恩·奥哈罗兰', '凯文·史密斯', 8.1, 21379, 'tt0109445', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1203262182.jpg', 0.8, 2.8, 19.1, 45.5, 31.8, '0.330926,-0.160526,-0.426493,0.139302,0.064943,-0.494248,0.694342,0.182008,-0.380488,-0.257292,-0.062682,0.455337,-0.577847,0.278574,0.490570,-0.084402,-0.216784,-0.469327,0.382577,-0.245400,-0.233872,-0.308259,-0.085391,-0.244334,-0.070732,-0.134726,-0.106499,0.092985,-0.153621,0.199418,0.326344,0.072139,0.094267,0.541351,-0.099278,0.065262,0.189351,0.229901,-0.002189,0.014052,0.289595,0.007906,-0.162862,0.113205,0.271828,0.349778,0.091723,0.015853,-0.385620,-0.010149,0.364115,-0.053258,-0.051249,0.005441,0.390056,0.132573,0.332422,0.007902,-0.220458,0.054178,0.145385,-0.064022,-0.536071,0.134469,-0.006106,-0.230117,-0.581615,0.380019,-0.089076,-0.009704,-0.113889,-0.320618,0.101360,0.491685,0.311315,0.430000,-0.088413,0.148406,-0.359653,0.093952,0.487008,0.100427,-0.120743,0.524061,0.007899,-0.304151,-0.094492,-0.109878,-0.226522,0.123007,0.467582,-0.141223,0.013081,0.177668,-0.673112,-0.070618,-0.321543,-0.335726,-0.138983,-0.229540,-0.264237,-0.425666,-0.054926,-0.047466,-0.231066,0.284859,0.320080,-0.140433,0.469077,-0.357992,-0.142813,0.512074,0.200546,-0.343481,0.330871,0.060137,0.087275,0.073954,-0.087778,0.012865,-0.058601,0.358530,0.162175,0.351204,0.168543,-0.418486,-0.343935,0.361689', '1296542', '1299767', '1301686', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298328', '天兆', '剧情', '格雷汉姆·海斯（梅尔·吉布森 Mel Gibson 饰）是美国费城某小镇上一个普通的农场主，一天早上醒来，他和家人意外的发现自己的玉米田里出现了几个一串串紧紧连结在一起的庞大环状神秘图案。这可让格雷汉姆一家吃惊不小，因为玉米田里根本没有任何足迹，看上去像是外星球人的飞船降落的痕迹。很快全世界各地都传出了一夜之间出现神秘图案的消息，人们惊恐万分，惶惶不可终日。全国的媒体、记者和观众也都把焦点以风一般的速度转移到了这个美国南部的小镇，集中到了巴克斯郡的海斯一家。这足有500英尺宽的神秘麦田圈，到底是有人恶意制造的恶作剧，还是乘坐UFO的外星人降临的痕迹，或者是某种灵异事件的结果？只有格雷汉姆发现了一些端倪，决定追查到底......©豆瓣', '梅尔·吉布森', 'M·奈特·沙马兰', 6.5, 18196, 'tt0286106', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453508337.jpg', 2.1, 11, 52, 27.3, 7.5, '0.526899,-0.116010,-0.922184,0.435046,-0.029110,0.157377,0.700361,0.184226,-0.670778,-0.156871,0.033791,0.670307,-0.411084,0.140084,-0.087884,0.118382,-0.349442,-0.596566,-0.041942,-0.481067,-0.398724,-0.425818,-0.499980,-0.389330,0.046117,-0.289754,0.067295,0.240482,-0.099376,0.572197,0.277805,0.096133,-0.142800,0.611602,-0.260275,0.050619,0.165318,-0.221738,0.228966,0.157548,-0.213528,-0.144062,0.048209,0.263574,-0.002198,0.715843,0.572828,-0.162428,-0.198297,0.166640,0.370652,-0.251606,0.090276,0.010756,0.541389,-0.235582,-0.004834,-0.063608,-0.144698,0.002078,0.189422,0.169349,-0.447486,-0.066225,0.037043,0.512764,-0.616334,0.325000,0.058076,-0.322054,-0.156322,-0.514580,0.476971,0.246753,0.091425,0.203810,0.047749,-0.021542,-0.539990,-0.041431,0.618224,0.039587,-0.593459,0.155264,-0.205129,-0.427649,-0.241242,-0.054044,-0.209474,0.164971,0.381443,0.127144,-0.128603,0.390331,-0.776463,0.151540,-0.302599,-0.475753,-0.280356,-0.254185,-0.303230,-0.761349,-0.071095,-0.315424,-0.206472,0.260463,-0.039849,-0.033570,0.657774,-0.497513,0.333222,0.671914,0.283850,-0.154466,0.554380,-0.357664,-0.004629,-0.068275,-0.287076,0.085881,0.249650,0.460020,-0.159128,0.426524,0.032471,-0.317959,-0.344085,0.395591', '34461680', '1298405', '1293019', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298334', '杀之恋', '爱情', '月黑风高的夜晚，戚志广（张国荣饰）独自行驶在路上，电台里播放着鬼故事，这时车子突然驶离轨道，戚停下车检查，等他再次上车后蓦地发现后座竟多了个清纯的白衣女子（钟楚红饰）！下车后，白衣女子突然主动向惊魂未定的戚志广献上热吻，待戚带其去舞厅后伊人却随即失去了踪影。经此一见，戚像失了魂般心中全是佳人的影子，并在第二天回到旧地寻找。不料找到的却是一座坟冢。尽管朋友们都说戚是大白天撞鬼，戚还是对白衣女子念念不忘，他在街上苦候数日，终于发现了她的踪影，而此时她的身份是亿万富翁曹三（黄锦燊饰）的情人？戚决定不论人鬼，都要对女郎展开不舍不弃的追求……©豆瓣', '张国荣', '梁普智', 7.3, 6985, 'tt0096078', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2347619649.jpg', 0.8, 5.5, 40.4, 33.2, 20, '0.287381,0.225304,-0.735629,0.290092,0.214754,-0.493854,1.033210,0.268742,-0.574737,-0.247149,0.052512,0.476906,-0.437389,0.444392,0.475196,0.025221,-0.377899,-0.845678,-0.270128,-0.254223,-0.459195,-0.029784,0.023970,-0.068311,-0.002081,0.031899,0.327031,0.271270,0.003452,0.710772,0.533603,-0.104545,-0.377016,0.791890,-0.393389,0.067280,-0.015127,0.089410,0.024406,0.372888,0.040434,-0.736558,-0.265522,0.069503,-0.334916,0.338682,0.768538,-0.094929,-0.301018,0.238121,0.001610,-0.036487,0.044364,-0.210227,0.261038,-0.150998,-0.010245,-0.199790,-0.241675,0.110624,-0.074475,0.055000,0.135399,0.232121,-0.161063,0.193776,-0.670635,0.159913,-0.089628,0.040395,0.117995,-0.572435,0.339698,-0.074785,0.100631,0.347009,-0.086848,0.136562,-0.528990,0.182318,0.233744,0.426596,0.151570,0.681065,-0.006768,-0.410391,0.077411,0.273919,-0.190994,-0.377680,0.395117,0.302539,0.064813,-0.249001,-0.391705,-0.063909,-0.156502,-0.045087,-0.155261,-0.341055,-0.263433,-0.483313,-0.023794,-0.240896,0.067597,0.613396,-0.410557,0.193734,0.507584,-0.741897,0.292625,0.245634,0.225962,-0.505067,0.644666,-0.178804,0.080364,-0.048659,0.178688,0.521441,0.006819,0.448386,-0.057638,0.147034,-0.365389,-0.087201,-0.667606,0.289968', '21348112', '35073565', '4312232', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298346', '芭啦芭啦樱之花', '剧情', '上海的舞蹈老师王锦胜（郭富城饰）天生有严重色盲，活在灰色世界中。一天，王锦胜到街上进行宣传活动，当他正在表演时，遇上了混进队伍中的乐儿（张柏芝饰），他们在街头贴身热舞，两个素未谋面的人竟是异常合拍。后来两人再次街头相遇，王锦胜英雄救美，赶走骚扰乐儿的人。数天后，乐儿来到舞蹈中心邀请王锦胜陪她到苏州游玩。乐儿向他透露，她是中日混血儿，为了逃婚才离开日本到上海。二人有了一个欢乐假期，王锦胜世界仿佛有了色彩，可感情并不容易衡量，王锦胜并不是乐儿理想中的男人。假期结束后，她决定返回日本完婚，王锦胜痛苦无比，决定到日本追求一次真正的爱情……©豆瓣', '郭富城', '马楚成', 6.2, 51852, 'tt0293895', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2553650344.jpg', 2.5, 14.7, 60.4, 17.7, 4.7, '0.151368,0.004883,-0.781850,0.269679,-0.111033,-0.137525,0.667188,0.065063,-0.509201,-0.013344,0.334740,0.590248,-0.178815,0.358004,0.482096,0.023039,-0.352217,-0.714734,0.231077,-0.190713,-0.136671,-0.254841,0.050858,-0.117410,-0.077676,-0.300542,0.410297,0.194494,-0.122658,0.667288,0.138963,-0.178687,-0.357436,0.607516,-0.077964,-0.077417,0.284868,0.198135,-0.463135,0.344818,0.045205,-0.079610,-0.358101,0.096527,-0.162047,0.156611,0.854842,-0.246360,-0.083032,-0.176727,0.316316,-0.110849,-0.205973,-0.030453,0.090635,-0.089083,0.428860,0.310030,-0.092126,0.234683,-0.284685,-0.176683,-0.079418,0.312477,0.065467,0.130751,-0.215542,0.360919,0.201106,-0.235493,0.183597,-0.312621,0.056178,0.199045,0.313477,0.140466,-0.095476,0.147152,-0.312509,0.343133,0.833062,-0.007528,-0.189875,0.437522,0.017262,-0.158638,0.261724,-0.120530,-0.112130,0.052395,0.233437,-0.087560,-0.299401,-0.086175,-0.664263,0.238650,-0.247735,-0.164778,0.133981,-0.443955,0.025430,-0.661265,-0.093208,-0.424448,-0.264853,0.011137,0.098480,-0.169158,0.538799,-0.856824,0.135218,0.620158,0.269724,-0.566363,0.568739,0.138911,-0.037195,-0.286677,0.117080,0.176425,-0.324381,0.281892,-0.205176,0.130484,-0.088089,0.086448,-0.566988,0.421493', '26687241', '3401409', '26930504', '1299433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298351', '奏鸣曲', '剧情', '北岛组干部村川（北野武 饰）因与大老板（逗子とんぼ 饰）关系不佳，而被派去冲绳协助兄弟帮派对抗阿南组。村川等人的到来似乎激化了原有的矛盾，双方对抗不断升级。在一次酒吧枪战中，村川的手下中弹身亡，随后他与手下片桐（大杉涟 饰）、肯（寺道进 饰）等人躲到海边小屋中暂避风头。在金黄的沙滩上，这群经历了血雨腥风的大男人们玩起了充满童真的游戏。然而他们的逍遥快活无法持续太久，北岛组和阿南组秘密联合，意欲将村川等人彻底铲除……本片荣获1994年日本电影学院奖最佳电影原声、1995年法国干邑影展影评人奖。©豆瓣', '北野武', '北野武', 8.4, 20745, 'tt0108188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1899389314.jpg', 0.2, 0.9, 13, 49.2, 36.7, '-0.042099,0.047223,-0.663725,0.363102,0.219299,-0.122178,0.405080,0.166531,-0.577540,0.080975,0.055586,0.613301,-0.267489,0.108907,0.129798,-0.253203,-0.171453,-0.815636,-0.198560,-0.200172,-0.246490,-0.070945,0.078896,-0.184335,-0.187849,0.047586,0.621978,0.094083,-0.205613,0.598155,0.366857,0.391093,-0.287785,0.264302,0.135058,-0.039741,0.320125,-0.124363,-0.358557,0.415000,-0.307274,-0.376363,-0.416780,-0.073280,0.385910,0.053378,0.819612,-0.229066,-0.044831,-0.208694,-0.086088,-0.212030,-0.294580,-0.047886,0.424461,-0.077997,0.247202,0.377047,-0.161945,-0.072234,0.007164,-0.150949,-0.436243,0.412286,0.079738,0.046232,-0.441933,0.491124,-0.213472,0.054743,0.183883,0.001286,0.167385,0.436051,0.397054,0.004679,-0.099606,-0.017150,-0.383661,0.408284,0.817487,-0.176096,-0.056009,-0.096377,0.375811,-0.272148,-0.401052,-0.391785,-0.175418,-0.157087,0.392024,-0.124922,-0.036273,0.042795,-0.493482,0.093316,0.012701,-0.345381,0.123384,-0.113171,0.192022,-0.853179,-0.121320,-0.163600,-0.294268,0.253041,0.154121,0.189615,0.748212,-0.500519,0.121584,0.552176,0.231229,-0.351426,0.399039,0.007455,-0.070396,-0.151596,-0.166702,-0.080780,-0.065041,0.328915,0.467669,0.313589,-0.366116,-0.125124,-0.403419,-0.169825', '3811356', '5403927', '26365262', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298354', '蛇眼', '悬疑', '暴风雨侵袭中的大西洋城，一场拳赛正在体育馆中预备上演，当地警探瑞克（尼古拉斯·凯奇 Nicolas Cage 饰）在敲诈赌客之余亦不忘为老拳王泰勒打气。这场比赛同时吸引到了国防部长莅临现场，担任部长护卫的海军长官凯文得以同老友瑞克见面，两人相谈甚欢。拳赛开始后，一名红发女子吸引了凯文的注意，另一名银发女子则与部长交头接耳，泰勒中拳倒地的刹那，部长中枪，凶手被凯文当场击毙。瑞克为自责中的凯文出谋划策，滞留全场一万多名观众。从比赛录像中，瑞克发现拳赛有假，以泰勒为突破口，瑞克锁定幕后的几名可疑人员，逼迫真凶出面将同伙灭口。同时银发女子茱莉亚向瑞克透露了事情真相，军火商为盈利在飞弹试验结果中作假，为防止事情败露暗杀了部长。瑞克决定拾起警察的责任，将罪犯绳之以法。©豆瓣', '尼古拉斯·凯奇', '布莱恩·德·帕尔玛', 6.9, 9822, 'tt0120832', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358141248.jpg', 0.7, 5.1, 48.8, 38, 7.5, '0.062981,-0.120101,-0.357418,0.154043,-0.263223,-0.251131,0.674834,-0.168716,-0.339916,-0.088154,0.765307,0.685040,-0.393338,-0.106704,0.663759,-0.260475,-0.664904,-0.980842,-0.354007,-0.083328,-0.112029,-0.505748,-0.255585,-0.183386,-0.045769,-0.192581,0.393957,-0.113566,-0.113557,0.575105,0.361078,0.367750,-0.210789,0.259632,0.546092,-0.195053,0.615431,-0.614148,-0.394626,0.323502,-0.085428,-0.290195,-0.314738,0.149952,0.048480,0.537816,0.562078,-0.158001,0.284833,-0.292215,0.102353,-0.346802,0.345195,0.377107,0.330843,0.319013,0.132279,0.272322,-0.231253,0.152359,0.026679,0.211610,-0.396360,0.149526,0.099781,0.475569,-0.209927,0.195587,-0.233977,-0.079617,0.260168,0.125388,0.210572,0.103874,0.358255,0.080618,0.076145,-0.161885,-0.201219,0.121944,0.527118,-0.232925,0.092980,-0.236066,0.194568,-0.258072,0.164405,0.148747,-0.096178,-0.118975,0.501058,-0.066889,0.256302,0.577348,-0.322064,-0.326444,-0.444706,-0.168362,-0.489029,-0.200112,-0.478555,-0.811866,-0.011627,0.168310,0.052322,-0.084575,0.218398,-0.036235,0.309088,-0.570954,-0.172845,0.386267,0.153057,0.033540,0.199313,0.133810,0.390167,-0.155448,-0.402169,-0.291448,0.368863,0.488211,0.190839,0.162814,-0.180961,-0.493271,-0.237728,-0.025678', '6517421', '25723905', '1298616', '1306449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298366', '斯巴达克斯', '剧情', '公元前73年，来自古罗马利比亚省的奴隶斯巴达克斯（柯克•道格拉斯 Kirk Douglas 饰）在加普亚格斗学校中爱上了女奴瓦瑞妮娅（琼•西蒙斯 Jean Simmons 饰）。同年，格斗学校的奴隶在斯巴达克斯带领下发动起义，获得自由，随后斯巴达克斯与瓦瑞妮娅团聚，结为夫妇。起义震惊了罗马的统治集团，激化了元老院中贵族派和平民派的矛盾。贵族将领克拉苏（劳伦斯•奥利维尔 Laurence Olivier 饰）乘机击败平民派首领格拉古（查尔斯•劳顿 Charles Laughton 饰），篡夺了首席执政官的权力，实行独裁。格拉古为了打击克拉苏，打算私下放走奴隶大军；克拉苏却重金收买了海盗，并召回在国外作战的两支大军。斯巴达克斯起义军三面受敌，寡不抵众，数万奴隶战死，他与妻子和六千幸存战友均被克拉苏所俘。在最后的关头，由于格拉古的帮助，情况又发生了变化。©豆瓣', '柯克·道格拉斯', '斯坦利·库布里克', 8.1, 25456, 'tt0054331', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2573968464.jpg', 0.4, 1.4, 19.8, 51.5, 26.9, '0.338321,-0.017808,-0.506734,0.503336,0.132327,-0.157417,0.359969,0.260850,-0.407101,-0.294708,0.266510,0.558038,0.130745,-0.151383,0.355197,-0.374892,-0.432224,-0.744315,-0.141230,-0.118076,-0.054099,-0.471170,-0.168388,-0.514922,0.024968,-0.553669,0.800411,0.205591,-0.151911,0.481605,0.319383,0.408245,-0.094736,0.227500,0.089972,0.000694,0.401551,-0.477883,-0.446434,0.270076,-0.651568,-0.342037,-0.140420,0.036390,0.132356,0.411161,0.580564,-0.538700,0.398055,-0.265755,-0.208571,-0.106105,-0.099316,0.192365,0.626369,-0.016188,-0.057933,0.317447,0.178573,0.006365,-0.090073,0.013761,-0.526498,-0.025418,0.061276,-0.068863,-0.753382,0.793297,-0.142997,0.276030,0.030908,-0.073831,0.127509,0.898786,0.141386,0.219199,0.088548,-0.202158,-0.659530,0.195294,0.673149,-0.392155,-0.219284,-0.445101,-0.313164,-0.515884,0.227462,-0.491078,-0.090383,-0.126413,0.406574,-0.271561,0.181385,0.638337,-0.751988,-0.207225,-0.512474,-0.209542,0.044224,-0.209975,0.303191,-0.495880,0.024617,-0.186150,-0.189304,0.155249,0.351774,0.252767,0.594927,-0.603978,0.066623,0.378347,0.674317,-0.606447,0.319113,0.082566,0.157227,0.029196,-0.139209,0.260012,0.387041,0.222665,0.367308,-0.098521,-0.152877,-0.325749,-0.006134,0.139501', '26852888', 