INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298382', '黄飞鸿笑传', '动作', '这是一部颠覆黄飞鸿传统形象的喜剧电影。话说黄飞鸿（谭咏麟 饰）从父亲那里继承了宝芝林的当家，成了一众徒弟的师傅。少年黄飞鸿其实不学无术，只会装装样子，混混日子。徒弟梁宽、牙擦苏等都十分着急，逼着他学武功。飞鸿对此却不以为然，总是得过且过。直到有一天，恶人石坚（梁家辉 饰）出现了。石坚不仅自己偷运鸦片，还利用十三姨（毛舜筠 饰）作人质逼飞鸿同流合污……©豆瓣', '谭咏麟', '李力持', 6.3, 5720, 'tt0104459', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350609942.jpg', 2.3, 13, 57.9, 20.2, 6.6, '-0.023043,-0.246762,-0.285758,0.287401,-0.213933,-0.347684,0.055409,0.181265,-0.445614,-0.308230,0.354952,0.481260,0.013518,-0.003694,-0.063024,-0.038388,-0.307911,-0.342511,-0.045013,-0.072904,0.410577,-0.480140,-0.014165,0.061689,-0.292606,-0.154573,0.306626,-0.280166,-0.329694,0.285623,0.466503,-0.183369,0.149099,0.228671,-0.157899,0.328406,0.188604,0.014557,-0.099729,-0.201553,-0.047112,-0.312298,-0.037865,-0.091389,-0.133107,0.293849,0.302436,-0.027798,-0.067834,-0.022664,0.022564,-0.182126,-0.501906,-0.172862,0.073283,-0.123073,0.313550,0.222456,-0.006883,0.038883,0.035276,0.239177,-0.483353,0.194857,0.219088,0.154554,-0.498548,0.400150,0.061472,-0.001817,-0.112471,-0.244723,0.098863,-0.282683,0.277435,0.254106,-0.214208,0.175949,-0.556810,0.509601,0.192632,-0.165312,0.094137,0.336932,0.126264,0.050911,0.251411,-0.424731,-0.291761,-0.178088,-0.062446,-0.347108,-0.244947,0.055278,-0.097278,-0.149775,-0.006907,0.347566,0.009351,-0.286522,0.138764,-0.334326,0.082827,-0.392449,-0.030022,-0.263020,0.141316,-0.281831,0.627409,-0.284440,0.110551,-0.029601,0.035146,-0.554859,0.214128,0.261586,-0.029594,-0.143790,-0.298430,-0.005956,-0.153243,0.053649,0.328084,0.316787,0.285672,-0.551169,0.149645,0.137018', '6557030', '27602116', '1877596', '3179758');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298385', '解构爱情狂', '剧情', '哈里（伍迪·艾伦 Woody Allen 饰）是一个才华横溢的著名作家，由于他神经兮兮、过于疯狂，他一直过着支离破碎、混乱无序的生活。他把身边的人和周围发生的事都写进自己的小说里，把自己和多名女性的感情生活也写成小说出版，由此哈里伤害和得罪了身边很多人。哈里的真实生活与小说中的虚构情节不断交织，同时哈里发现自己的灵感开始枯竭。在哈里的生活过得一团糟的时候，他被母校邀请回校接受名誉学位，但他找不到一个可以陪他一起去的伴儿。他只好找了个妓女陪同，第二天朋友理查德也来陪他，路上他还从前妻手中拐来自己的儿子一同前去。四人在途中又遇到了什么，到达目的地之后又有什么状况？哈里试图解构自己的现实生活、解构自己小说中的虚构人物的生活、解构小说人物在自己生活中起到的影响，这个不能正常运作自己的生活，却只能在艺术中发挥才能的天才作家，究竟能不能解构出自己人生中的“真相”。', '伍迪·艾伦', '伍迪·艾伦', 8.6, 32192, 'tt0118954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2099964935.jpg', 0.2, 1, 11.6, 44.9, 42.3, '0.419182,-0.035265,-0.711809,0.771257,-0.300084,-0.162302,0.909674,-0.108073,-0.516149,-0.290984,0.000892,0.917956,-0.142650,0.387980,0.119592,0.104670,-0.525172,-0.873065,0.150181,-0.073580,-0.360264,-0.397742,-0.405264,-0.191734,-0.281381,-0.044570,0.462198,-0.006400,-0.322607,0.234166,0.003879,0.178368,-0.116314,0.643117,-0.264069,0.315369,-0.066376,0.071151,0.085414,0.229388,0.374186,-0.347999,-0.108578,0.348400,0.157662,0.141010,0.709984,-0.173751,-0.026766,0.099165,0.359127,-0.113898,-0.138332,0.190051,0.075437,-0.051155,0.347175,0.011098,-0.110735,0.223867,-0.268899,0.020243,-0.994583,-0.145763,0.048399,0.226054,-0.693394,0.339192,-0.002050,-0.329884,0.032850,-0.428732,0.293580,0.312379,0.240801,0.299156,-0.339486,-0.135021,-0.537479,0.428013,0.738503,0.108448,-0.280692,0.401655,-0.432630,-0.247079,-0.256037,-0.235416,-0.641590,-0.137522,0.190486,0.049940,-0.391139,0.302749,-0.467965,0.192291,-0.063232,-0.262829,-0.215419,-0.425438,0.014472,-0.437351,-0.108893,-0.494454,-0.258884,-0.087155,-0.031052,-0.421779,0.774392,-0.622454,0.152995,0.768635,0.267225,-0.452236,0.778893,0.209774,0.134588,0.064781,-0.009871,0.082812,-0.015125,0.605568,0.121206,0.381539,0.297121,-0.000171,-0.491572,0.765664', '30162520', '34890458', '25928048', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298389', '猛鬼街', '惊悚', '这几天，艾姆街上的小孩都在作着同一个噩梦。梦中，一个脸上有道吓人的刀疤，戴着钢爪手套的怪人正在折磨他们。艾姆街的小孩随之一个接一个死去。南茜（希瑟•兰登坎普 Heather Langenkamp 饰）的好朋友都离奇死去，她觉得这一定跟那个噩梦有关。于是，南茜展开了调查。经过调查发现，梦中的怪人就是当年因骚扰儿童而被愤怒的父母活活烧死的变态佛瑞迪（罗伯特•英格兰德 Robert Englund 饰）！事隔多年，佛瑞迪的鬼魂回来找小孩子们报仇了！为了不被杀死，南茜必须保持清醒，在支撑不住前将佛瑞迪解决掉……©豆瓣', '希瑟·兰根坎普', '韦斯·克雷文', 7.4, 32808, 'tt0087800', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p471154636.jpg', 0.8, 3.5, 35.5, 44.7, 15.5, '0.309152,-0.324529,-0.548941,0.211611,-0.316884,-0.385408,0.954533,-0.106277,-0.203606,-0.504805,0.166240,0.446743,-0.263787,0.498840,0.123668,-0.086120,-0.170245,-0.498442,-0.172436,0.058740,-0.437659,-0.303655,-0.379785,-0.223865,0.067559,-0.215324,0.253083,-0.070355,0.190067,0.423479,0.321498,0.336411,0.012868,0.218814,-0.259384,-0.018419,-0.123163,-0.259692,0.108623,0.193277,0.192111,0.041692,0.178503,0.237920,-0.307759,0.408992,0.578967,-0.285474,-0.136888,-0.288321,0.258469,-0.490280,-0.139687,0.234456,0.139295,-0.025116,0.054636,0.041211,-0.276077,-0.010208,0.258694,0.063985,-0.626456,0.391369,0.249338,0.340088,-0.500457,0.366942,-0.010666,0.231272,0.144212,-0.147058,0.321245,0.463620,0.379907,0.456678,-0.208752,0.138666,-0.645104,0.162789,0.674215,-0.284666,-0.117375,0.143521,0.003591,-0.091558,0.305329,-0.181220,-0.271313,0.080502,0.221860,-0.204411,-0.515328,0.150696,-0.471396,-0.302635,-0.327508,0.045799,-0.302025,-0.296453,-0.392951,-0.365592,-0.090598,-0.162627,-0.242201,0.232828,-0.115726,-0.185554,0.414214,-0.425295,0.344343,0.807009,0.199396,-0.220327,0.328672,0.047318,0.191798,-0.049005,-0.038935,0.260507,0.409300,0.291967,0.240259,0.226731,0.022737,0.074163,-0.530301,0.378676', '1428054', '21619567', '1947080', '25909236');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298405', '第三类接触', '剧情', '1978年意大利大卫奖最佳外语片。1945年的一天夜里，当诺伊·尼尔瑞（理查德·德莱福斯 Richard Dreyfuss 饰）在装载卡车时，忽然被神秘的光线所笼罩，之后奇怪的幻象和五个音符一直在他脑海中回旋。他能否发现幻象的意义，又是谁将其置于他的脑海中呢？与此同时，美国政府同星际来客有了一定的接触并确定其降落的地点。为了掩饰真相，政府要求人们远离此地。然而，包括诺伊在内的一群人，却被其共同的幻象所吸引，来到此地。在沙漠中的魔鬼山上，空军临时修建的基地上空，外星人如约来到，他们的飞船流光异彩，将半个天空都照亮了。人类播放了以前从太空接受到的外星人信息中破译出的音乐作为联络的手段，飞船的大门打开了，从前失踪的地球人都回到了自己的家乡，而一批外形矮小的外星人则来到地球人中间和他们做心灵的沟通……©豆瓣', '理查德·德莱福斯', '史蒂文·斯皮尔伯格', 7.2, 19815, 'tt0075860', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2214707465.jpg', 1, 5.6, 38, 41.4, 14, '0.378939,0.192846,-1.018944,0.641505,-0.089812,0.013875,0.680484,-0.059108,-0.532483,-0.181050,0.218220,0.787726,-0.090969,0.227808,0.231704,0.198022,-0.482104,-0.761505,-0.069139,-0.607851,-0.364478,-0.369234,-0.346029,-0.344648,0.144835,-0.517663,0.589290,0.266648,-0.047998,0.278335,0.011066,0.045646,-0.333016,0.484320,-0.105364,-0.058321,-0.004850,0.018569,-0.149682,0.142165,-0.410528,-0.354389,-0.055413,0.147480,-0.148848,0.375722,0.871416,-0.391307,-0.053339,0.015031,0.101552,-0.360648,0.073555,-0.018234,0.266532,0.034530,-0.065720,0.195056,-0.331459,0.268444,-0.208945,0.061571,-0.699086,-0.014251,-0.081276,0.103742,-0.437537,0.339134,-0.054719,-0.035520,-0.075545,-0.347148,0.377396,0.159446,0.100740,0.485674,-0.331868,0.087074,-0.386534,0.003438,0.591414,-0.079633,-0.514852,0.240010,-0.176686,-0.521065,-0.346010,0.114337,-0.126527,-0.083227,0.485287,0.295687,-0.237246,0.284803,-0.898523,0.105294,-0.243066,-0.349443,-0.065842,-0.365302,-0.322557,-0.904868,-0.009242,-0.242659,-0.146120,0.116523,-0.077782,0.054562,0.668770,-0.629771,0.337128,0.652701,0.251475,-0.222124,0.734149,-0.245687,0.117371,-0.180805,-0.029501,0.139291,0.268695,0.680029,-0.116902,0.305114,-0.073536,-0.027412,-0.491291,0.349501', '2159244', '34461680', '1293019', '19965431');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298412', '三十九级台阶', '悬疑', '音乐厅中传来枪声，观众们一片惊慌。一位外国女子（露西•曼娜海姆饰）询问理查德•汉内（罗伯特•多纳特饰）是否可以在他家中过夜。次日该女子在被杀之前告诉理查德必须阻止间谍组织“三十九级台阶”将国家机密偷偷送出英国。汉内为了证明自己并不是杀人凶手无奈前往苏格兰高地寻找线索，在火车上他寻求一位叫做帕梅拉（玛德琳•卡罗尔饰）的金发年轻女子帮助，但她却马上向警察告发了他。他找到了“三十九级台阶”的领导人乔丹教授，但随即被陷害入狱。侥幸逃脱后又由于帕梅拉的告发被两位伪装成便衣警察的人带走，并且他们还把帕梅拉和他铐在了一起。于是两人携手逃脱了出来并取得了互相的信任，然后他们再次回到音乐厅，汉内看到了上次就见过的表演。他向号称可以回答任何问题的“记忆先生”（怀特•沃森饰）提问：“什么是三十九级台阶“，于是……希区柯克曾说“记忆先生“是他最喜欢的角色之一，这个角色建立在一个名叫达塔斯的真人基础上，他自己小时候在伦敦看过他的表演。', '罗伯特·多纳特', '阿尔弗雷德·希区柯克', 7.8, 32317, 'tt0026029', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2250578848.jpg', 0.2, 1.6, 27, 51.1, 20, '0.345841,0.145006,-0.594418,0.554928,-0.395696,-0.374782,0.717049,0.006262,-0.428969,-0.126217,0.165907,0.823877,-0.014640,0.203715,0.310757,0.131525,-0.456270,-0.590230,0.237993,-0.297095,-0.384569,-0.599643,-0.158501,-0.266636,0.037357,-0.406414,0.416506,-0.070910,-0.264481,0.342758,0.359779,0.114493,-0.006679,0.543855,-0.312441,0.084265,0.136993,-0.251748,-0.237470,0.358372,0.035357,-0.378755,-0.217983,0.156272,-0.027839,0.479368,0.351429,-0.155628,-0.014184,0.189015,0.148224,-0.240864,0.204799,0.209870,0.224122,-0.097182,-0.005106,0.306531,-0.089681,-0.086240,-0.052767,-0.025138,-0.528832,0.197627,-0.045578,0.379259,-0.583171,0.252143,-0.250198,-0.056257,0.034385,-0.230570,0.260064,0.146793,0.004949,0.158991,-0.179602,-0.112171,-0.590818,0.186078,0.479991,0.065288,0.100131,0.221718,0.126780,-0.491397,0.054532,0.008608,-0.154014,0.124063,0.481950,-0.056029,-0.262028,-0.206640,-0.390596,-0.251539,-0.348361,-0.149181,-0.130047,-0.520665,0.032359,-0.593440,0.013144,0.027347,-0.305004,-0.118876,-0.060456,-0.318396,0.523278,-0.740177,0.113845,0.669975,0.497438,-0.309062,0.632733,0.010487,0.050576,-0.105672,-0.025213,0.196780,0.341679,0.392315,0.057530,0.401369,0.129258,-0.269663,-0.343