INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298437', '致命玩笑', '惊悚', '暑假来临，大学新生刘易斯·托马斯（保罗·沃克尔 Paul Walker 饰）决定穿州过省，前往新泽西去看望他自高中时代便喜欢的女孩维娜·威尔柯斯（Leelee Sobieski 饰）。为了打发旅途上的无聊时光，他将正因酒后驾车蹲局子的老哥富勒（史蒂夫·赞恩 Steve Zahn 饰）保释出来，兄弟俩一路通行。旅途中，富勒买了一部车载对讲机，与其他的司机扯皮聊天。期间他们搭上一个绰号“锈钉”的卡车司机，富勒突发奇想，怂恿弟弟假扮女人用对讲机勾引锈钉。对他们来说，这似乎是旅途中一个无伤大雅、转眼就忘的玩笑。没想到他们却惹上了这个难缠和恐怖的家伙。在接下来的时间里，锈钉成为刘易斯、富勒和维娜难以摆脱的噩梦……©豆瓣', '保罗·沃克', '约翰·达尔', 6.8, 8780, 'tt0206314', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2362605313.jpg', 1.1, 6.9, 49.6, 33.5, 8.9, '0.515899,-0.089464,-0.500569,0.380868,-0.370719,-0.149711,0.724480,-0.014744,-0.372753,-0.095492,0.170161,0.562143,-0.340862,0.241103,0.341742,0.131979,-0.584751,-0.611065,0.223791,-0.175354,-0.330941,-0.382332,-0.170151,-0.100354,0.006235,-0.038901,0.116048,-0.135021,-0.137544,0.620581,0.278036,0.282162,-0.063362,0.347542,-0.147157,0.054504,0.019139,-0.013141,0.115865,0.022818,0.070233,-0.113635,0.057510,-0.099062,0.195848,0.339579,0.487512,-0.109032,0.221259,-0.080189,-0.077399,-0.384207,-0.030329,-0.006241,0.123232,0.107555,0.199370,0.055478,-0.277835,-0.112276,-0.022867,-0.063193,-0.436267,0.211704,-0.329827,-0.096738,-0.612662,0.478980,-0.227098,0.021161,0.001071,-0.385281,0.191773,0.098984,0.201484,0.188549,0.063071,-0.117143,-0.374404,0.155403,0.466336,-0.119834,-0.141294,0.331772,0.081030,-0.006449,0.120855,-0.128170,-0.399350,-0.310539,0.287730,-0.258401,-0.167878,0.024977,-0.321662,0.156388,-0.236319,-0.101926,0.046723,-0.276438,-0.188670,-0.547757,0.158421,-0.404312,-0.274520,0.029404,0.095734,-0.007429,0.264184,-0.430007,0.215922,0.507449,0.192975,0.017636,0.841014,0.164987,0.163606,-0.198820,-0.035126,0.074661,0.133902,0.263877,0.183917,0.506054,0.007943,-0.132813,-0.536029,0.534388', '1309172', '3055049', '26809592', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298442', '艳贼', '剧情', '聪明漂亮的公司女秘书玛尔妮·埃德加（蒂比·海德莉 Tippi Hedren饰）实际上是一名品行不端的女窃贼，嗜偷如命。几个月后，她偷走了公司保险柜里的将近一万美元的现金，恰好公司的大主顾马克·鲁德兰（肖恩·康纳利 Sean Connery饰）也在场。他对这位冷艳神秘的女人有着浓厚的兴趣。更有缘分的是，马克就是玛尔妮的新任老板。玛尔妮对红色的东西始终有着一种神经性的恐惧，这更让马克觉得这个怪异的女孩背后一定有着什么故事，企图接近她。鲁德兰猛烈的爱情攻势，让玛尔妮倍感恐慌和不安。虽然她也对这个风度翩翩的英俊男人动了心，却仍习惯性地从公司的保险柜里偷出现金，打算远走高飞。马克及时阻止了她，并引导玛尔妮说出真话。面对自己难以逾越的心理障碍，玛尔妮内心中那段不愿告人的身世之谜即将揭开面纱。©豆瓣', '蒂比·海德莉', '阿尔弗雷德·希区柯克', 7.3, 19194, 'tt0058329', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1974065801.jpg', 0.6, 3.9, 39.8, 39.4, 16.3, '0.230331,0.151169,-0.729302,0.578840,-0.194866,-0.260087,1.021607,-0.092716,-0.478157,-0.310771,0.008427,0.614073,-0.303440,0.278748,0.145678,0.259140,-0.087608,-0.387786,-0.206359,-0.382312,-0.243742,-0.369612,-0.523656,-0.311739,-0.011281,-0.090499,0.227673,0.265791,-0.198788,0.357617,0.568339,0.277370,0.104575,0.688864,0.010728,-0.154194,-0.042436,-0.070319,0.059431,-0.059282,0.193903,-0.061385,-0.026922,0.346323,-0.101931,0.587106,0.283941,-0.186068,-0.185114,0.063290,0.378179,-0.141255,-0.056851,0.054006,0.210800,-0.108431,0.002065,0.049846,-0.281251,-0.143933,0.201759,-0.158554,-0.904262,0.066490,0.091201,0.186769,-0.475016,0.108565,-0.252443,0.123847,0.148154,-0.164143,0.012969,0.009880,0.256822,0.217513,-0.044676,0.138622,-0.474576,-0.093885,0.292543,0.129033,-0.253647,0.245424,-0.486811,-0.430687,-0.132569,0.016452,-0.542396,0.011676,0.347142,0.150240,0.109632,0.038651,-0.587586,0.073501,-0.206293,0.090645,-0.042710,-0.412876,-0.082816,-0.328833,-0.283468,-0.589641,-0.289530,0.030063,0.283314,-0.186571,0.677903,-0.576109,0.088403,0.619285,0.447381,-0.356272,0.509053,0.193510,-0.143058,-0.211602,-0.640416,0.367028,0.095951,0.020300,-0.127884,0.583833,0.093258,-0.261870,-0.144614,0.636945', '1417428', '35158375', '1297996', '26648284');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298443', '黄飞鸿', '剧情', '清朝末年，曾任黑旗水军教头兼民团总教练的广东佛山武师黄飞鸿（李连杰）常在宝芝林教人练武，期望借此自强救国，可是眼见政府苟且偷生洋人横行霸道，他渐渐领悟到单凭武术不足以使民众从苦海中脱离，开始努力找寻其它救国出路。梅县梁宽（元彪）在戏院结识黄飞鸿的恋人十三姨（关之琳）后与黄飞鸿出生种种误会，终投武夫严振东门下与黄飞鸿成为敌手。严振东与洋人连手鼓吹美国是金山世界，将包括十三姨在内的大批中国妇女骗掳上洋船，梁宽此时幡然醒悟，明白黄飞鸿是友非敌，在他的帮助下，黄飞鸿开始与洋人及其爪牙展开浴血奋战。©豆瓣', '李连杰', '徐克', 8.3, 165895, 'tt0103285', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204476216.jpg', 0.1, 0.6, 14.7, 53, 31.6, '0.284589,-0.077525,-0.425117,0.262031,0.092922,-0.002715,0.177724,-0.072315,-0.725819,-0.224027,0.168313,0.664144,0.242754,0.181796,-0.121978,-0.366353,-0.173750,-0.799227,-0.138903,-0.072962,0.233500,-0.335972,-0.330511,0.121759,-0.509849,-0.253592,0.572240,0.295452,-0.330958,0.504357,0.189501,0.123238,-0.116389,0.216526,-0.055638,0.163936,-0.073558,-0.277041,-0.674102,-0.008498,-0.177371,-0.322944,-0.319591,-0.053152,-0.277981,0.204190,0.452325,-0.066115,0.264534,-0.371432,0.170315,-0.097881,-0.220117,0.123422,0.184051,0.146321,0.061307,0.313646,0.207446,0.065100,-0.119345,0.089808,-0.405553,-0.083160,0.269327,-0.007285,-0.701465,-0.051780,-0.000767,-0.204311,0.080754,-0.286773,-0.005700,0.332381,0.166249,0.126920,-0.170162,0.048703,-0.621345,0.413008,0.728272,-0.168905,-0.023655,-0.159930,0.245116,-0.262378,0.175608,-0.378355,-0.001711,-0.305380,0.061394,-0.311422,-0.021303,0.031307,-0.220290,0.008223,-0.195054,0.083254,-0.011742,-0.078467,0.105139,-0.492493,-0.296168,-0.377223,0.123350,-0.204415,0.264085,-0.310919,0.707447,-0.718644,-0.092622,0.279595,0.394274,-0.322141,0.616847,0.076678,0.061735,-0.161364,-0.149109,0.067544,0.160687,0.362474,0.028195,0.201725,-0.350288,0.016963,-0.010728,0.154795', '3230460', '35030151', '25721544', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298455', '孟菲斯美女号', '剧情', '影片描写了二次大战中的1943年，10名飞行员驾驶B—17轰炸机飞越德军上空轰炸既定目标的壮烈场面。这群朝气勃勃的小伙子，刚刚完成了他们的第24次飞行任务，再飞一次可以返家了，久违的家在等他的，战争结束之后该做什么，在每个人的心中都有一番憧憬。然而，残酷的事实摆在他们面 前，无法向人表露的紧张和恐惧，只有默默地祈求冥冥中的神灵保佑。为此，他们视好运胜过一切，一块护身挂牌，甚至是一条幸运皮筋，都可以使他们的心灵得以寄托。在紧张、无奈的等待之后，终于等来了出发的命令，满载弹药的飞行方阵穿过云层，向目标靠近。主机孟菲斯美女号是戴尼斯为了纪念他在孟菲斯相识的女友而命名。在天气恶劣、云层密布，目标无法确认的情况下，戴尼斯为了保护无辜的生命和医院、学校等公共设施，冒死重新飞回，确认了目标。重创之下的飞机终于载着这群伤痕累累却胜利完成使命的英雄的归来。', '马修·莫迪恩', '迈克尔·卡顿-琼斯', 8.3, 6176, 'tt0100133', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2356056022.jpg', 0.2, 1.3, 15.9, 49.3, 33.3, '-0.066083,0.012420,-0.723943,0.492271,0.024646,-0.177758,0.502035,-0.073110,-0.275040,0.134913,0.514703,0.574649,-0.035504,0.110709,0.197237,-0.149926,-0.520986,-0.585021,-0.068510,-0.219212,-0.538418,-0.358026,-0.193402,-0.218521,0.030382,-0.352255,0.587163,0.293996,0.114320,0.496430,0.295112,0.014695,-0.053614,0.528318,-0.419294,-0.259418,-0.092473,-0.027454,-0.317812,0.319360,-0.156015,-0.192306,-0.181418,0.300899,-0.024830,0.328819,0.963584,-0.220189,-0.209338,0.009155,0.074890,-0.335098,0.216370,0.236787,0.071492,0.091156,-0.038413,0.004211,0.011117,0.175850,-0.215735,-0.007192,-0.854931,-0.135018,-0.104251,-0.010997,-0.463041,0.630965,-0.135436,0.083369,0.182026,-0.412416,0.300594,0.338581,0.120313,0.498869,-0.375803,0.174414,-0.377803,0.079649,0.605092,-0.148307,-0.362934,0.391074,-0.082200,-0.288736,-0.073105,-0.085062,-0.568580,-0.116815,0.436036,0.451879,-0.148451,0.066416,-0.585435,-0.013464,-0.461313,-0.520665,-0.043159,-0.575925,-0.144055,-0.399504,0.084998,-0.319949,-0.258983,0.384126,0.067634,-0.143427,0.683529,-0.599361,0.287693,0.472107,0.196540,-0.264250,0.610336,0.135894,0.083547,-0.123305,0.133227,0.260299,-0.125665,0.723429,0.112061,0.208968,-0.099741,0.124595,-0.501447,0.385744', '25928048', '2032339', '26418093', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298467', '红灯停，绿灯行', '喜剧', '记者苟宇佳（牛振华 饰）、下岗女工程芬（丁嘉丽 饰）、个体户绿豆（王劲松 饰）、大款老差（句号 饰）是驾校1025班的成员，在退伍军人侯教练手下练习。随着时间的推移，大家渐渐摸清彼此的习性。记者小苟八面玲珑，处事圆滑，一心想把学车费报销，结果天不遂人愿；待业女工阿芬被下海的丈夫发来离婚的传票，一人带着女儿，老实度日；早年丧父，母亲瘫痪在床的绿豆沾染上了毒品，白天学车，半夜偷井盖，却是个孝顺儿子；大款老差则是个打着盹儿都能赚上十万、八万的有钱人，不把驾校规定放在眼里；侯教练的教练身份为他带来了免费的香烟和赚回扣的机会，也因此引火烧身，弄得家里鸡犬不宁。这段驾校生活，波折连连，却都一一化险为夷，5人间的暗战明战也都随着考试的顺利通关而结束。这段驾校的经历牵扯出了5个人的悲喜，除了学到了驾驶规则，似乎更学到了生存法则。©豆瓣', '牛振华', '黄建新', 8.3, 8825, 'tt0182030', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2327919681.jpg', 0.2, 0.8, 14.9, 51.9, 32.3, '0.014294,-0.056651,-0.300147,0.223419,-0.172108,-0.338305,0.139702,0.030664,-0.197915,-0.284280,0.032538,0.286084,-0.118756,0.158009,0.401361,-0.333605,-0.067245,-0.375542,0.007955,-0.093834,-0.177373,-0.410544,-0.111890,-0.218548,-0.136043,-0.086107,0.256272,0.040018,0.095999,0.350371,0.200296,-0.285025,0.234960,0.172808,-0.209669,0.179858,-0.156839,0.017229,0.088881,-0.236667,-0.031044,-0.120819,-0.071012,-0.380350,0.661120,0.341522,0.654699,0.036783,-0.028398,-0.100178,0.316217,-0.169964,-0.204867,-0.084675,0.359413,0.108755,0.356146,0.273174,-0.022287,-0.028093,0.123202,-0.019167,-0.622395,-0.034536,0.118776,-0.018468,-0.432567,0.475901,-0.136229,-0.005063,-0.414263,-0.235714,0.303393,0.364151,-0.018619,0.400710,-0.095786,-0.018102,-0.453709,0.652375,0.432295,0.015162,-0.159547,0.192936,-0.310745,-0.368893,0.078525,-0.431252,-0.321946,-0.077852,0.354649,-0.071957,-0.150097,0.052442,-0.309284,0.164175,0.055340,-0.167372,0.031105,-0.566200,-0.094937,-0.388834,-0.030642,-0.264884,-0.351563,0.318997,0.339523,-0.192452,0.634114,-0.428480,-0.077002,0.466829,0.213909,-0.457953,0.729787,0.029058,0.201333,-0.166400,-0.119501,-0.162117,0.146453,0.530127,0.224537,0.411255,-0.246357,-0.326558,0.075750,0.207873', '1877596', '2027945', '1908036', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298468', '邮差', '剧情', '马里奥（马西莫•特罗西 Massimo Troisi 饰）是一个渔民的儿子，他并不喜欢大海，却当上了邮递员，专门负责小岛上信件的发送。小岛上住着智利诗人聂鲁达（菲利浦•诺瓦雷 Philippe Noiret 饰）和他的妻子。聂鲁达被流放至此地，他擅长写诗，才华横溢。马里奥每天都收发很多聂鲁达的信件。在频繁的接触中，马里奥越发崇拜这个诗人，他热衷于跟聂鲁达讨论诗，学习诗。当爱上岛上的美丽姑娘后，马里奥经常跟聂鲁达倾诉心事，并最终用诗打动了姑娘的芳心，二人结成伉俪。直到聂鲁达离开小岛，马里奥仍然坚持着对诗的热爱。他继续写诗，正打算在工人集会上读诗，却遭致了意想不到的灾难。©豆瓣', '菲利普·努瓦雷', '迈克尔·莱德福', 8.8, 20248, 'tt0110877', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537507687.jpg', 0.1, 0.5, 8, 40.8, 50.5, '0.443600,-0.162630,-0.702483,0.765261,0.094020,-0.277094,0.635589,0.096454,-0.473951,-0.101556,0.011278,0.763469,-0.337913,0.502984,0.160185,0.180660,-0.412559,-0.595309,-0.050755,-0.014886,-0.123561,-0.684918,-0.074576,-0.042458,-0.111228,-0.171107,0.182870,-0.025368,-0.173022,0.517953,0.010175,0.346808,0.150313,0.572646,-0.201749,0.115413,0.019568,-0.056767,-0.099762,0.095186,-0.000519,-0.040471,-0.241324,0.067689,0.025225,0.186404,0.669892,-0.435179,0.044503,0.032023,0.177280,-0.039362,0.340129,0.029381,0.085055,-0.056746,0.330560,0.111173,-0.119941,-0.091651,-0.239192,-0.073865,-0.258728,-0.089305,0.167231,0.249689,-0.605315,0.700434,-0.262336,0.051529,-0.174807,-0.337652,0.175571,0.099904,-0.003349,0.377307,0.058274,-0.072277,-0.319015,0.245437,0.318451,0.309686,-0.052797,0.334305,-0.289863,-0.385350,0.156768,-0.203053,-0.315382,-0.051063,0.162856,-0.130852,0.024676,-0.067960,-0.572694,0.226274,-0.264157,-0.095057,0.014702,-0.511095,-0.189811,-0.448063,0.314119,-0.221140,-0.221187,-0.034904,0.073842,-0.228188,0.989200,-0.530332,0.256212,0.829547,0.058778,-0.259255,0.520077,0.236476,-0.228323,-0.158110,-0.219034,0.359528,-0.005500,0.284507,0.069766,0.259789,0.213860,-0.192404,-0.290637,0.621777', '1307146', '30162520', '1308609', '10773239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298492', '高度戒备', '剧情', '重案组高级警察包伟雄（刘青云饰）因开枪打死人陷入深深的负罪感之中。前土木工程师麦坤（吴镇宇饰）因赌马失败失去一切，放手一搏准备其惊天大案。但不想一开始就因为杀人嫌疑被包伟雄关进大牢。本以为案件就此结束，麦坤的同伙竟公然在运送麦坤的途中截车救人！案情突然变得复杂，麦坤家中藏有大量炸药原料，包伟雄推断麦坤要抢劫金库。但香港金库之多，麦坤的目标到底是哪里？时间一分一秒的过去，陷入窘境的包伟雄，走投无路的麦坤，谁将在今夜成功达成自己的目标？©豆瓣', '刘青云', '林岭东', 7.1, 10943, 'tt0134664', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1630105655.jpg', 0.7, 4, 44.4, 42.1, 8.8, '0.153169,0.103505,-0.677194,-0.107098,0.125660,0.031642,0.613285,-0.295317,-0.411790,-0.237635,0.375085,0.477947,-0.167293,-0.105505,0.144023,-0.221277,-0.347985,-0.587012,-0.072717,-0.373373,-0.363003,-0.459136,-0.142659,-0.364798,0.299838,0.059499,0.580859,0.432482,-0.152001,0.237849,0.302062,0.573781,-0.358965,0.427744,0.125678,0.018576,0.180592,-0.133507,-0.231888,-0.003515,-0.031187,-0.350236,-0.122708,0.164958,-0.011256,0.242257,0.566374,-0.118017,-0.355033,-0.032533,0.214935,-0.372744,-0.216553,-0.003475,0.373088,-0.032154,-0.110676,0.281040,-0.232474,0.101292,0.170785,-0.001388,-0.843120,-0.036777,-0.007725,0.009943,-0.064292,-0.103767,-0.249225,0.183173,-0.186739,-0.236935,0.098814,0.306066,0.549248,-0.112317,-0.298383,-0.273199,-0.579681,-0.017333,0.642632,-0.377129,0.156227,0.130635,0.227216,-0.327978,-0.036698,-0.097784,-0.057333,0.032851,0.368324,0.000157,-0.174210,0.041060,-0.207228,-0.053347,-0.338008,-0.055845,-0.220736,0.052678,-0.198110,-0.340718,0.063672,0.080192,-0.336461,0.128773,0.117088,-0.008128,0.134675,-0.383073,0.040775,0.544992,0.163449,-0.399179,0.157052,-0.236453,0.001271,-0.184562,-0.196795,-0.205031,0.314474,0.348205,0.382849,-0.066349,-0.106321,-0.310696,-0.131838,0.088870', '26747274', '2988294', '26678784', '1857099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298493', '塘鹅暗杀令', '剧情', '两名高等法院的法官遭杀手谋杀，法学院高材生达比（朱莉娅•罗伯茨 Julia Roberts 饰）随后开始调查此案，起草一份该案的报告，名为《塘鹅报告》。达比找到了记者格兰（丹泽尔•华盛顿 Denzel Washington 饰），因为他是最后一名见到其中一名法官的人，希望能得到他的帮助调查此案。一天格兰接到了一个神秘人来电，此人自称知道谁是该案凶手，格兰跟踪到了此人，可惜未能拦下他。此时，总统暗中命令相关人士不要插手此案。格兰由此起疑，随后调查到了总统和马氏集团关系密切，而且一切证据都表明，马氏与两位法官的死有着千丝万缕的关系！©豆瓣', '朱莉娅·罗伯茨', '艾伦·J·帕库拉', 7.2, 6977, 'tt0107798', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1961859459.jpg', 0.4, 3.4, 41.7, 43.6, 10.9, '0.231661,-0.229503,-0.625575,0.641768,-0.159629,0.000866,0.330467,0.273588,-0.910876,-0.516493,0.186664,0.511908,-0.068401,0.129782,0.478673,-0.271621,-0.497156,-0.595314,0.168343,-0.445098,-0.241238,-0.855513,-0.116433,-0.164676,-0.047588,-0.261550,0.291192,0.081454,-0.071963,0.344963,0.310088,0.533364,-0.107843,0.286177,0.011358,-0.163391,0.476660,-0.317040,-0.450289,0.399746,0.168720,-0.064559,0.007240,0.191448,-0.033499,0.531314,-0.051915,-0.042404,-0.190788,-0.237891,0.360759,-0.140999,0.271319,0.340749,0.637545,0.225063,-0.087271,0.620652,-0.552009,-0.315291,-0.052270,0.134011,-0.802687,-0.056144,0.107731,0.550520,-0.410416,-0.157122,-0.574108,0.130463,-0.111244,-0.199900,0.076815,0.380400,0.052087,0.072467,0.430705,0.004163,-0.816383,-0.124611,0.742288,0.074485,0.140784,-0.211817,0.225687,-0.507535,-0.101220,0.056559,-0.075452,0.436909,0.322651,0.079297,0.170204,0.094762,-0.116536,-0.517979,-0.420669,-0.050706,-0.136707,-0.429029,-0.021003,-0.588880,-0.139213,0.193879,-0.394785,0.016878,0.169812,-0.326945,0.561164,-0.593701,-0.000412,0.433121,0.306844,-0.645896,0.563652,0.197307,0.165139,-0.400295,-0.079810,-0.075370,0.869060,0.231390,0.182859,0.054952,0.094794,-0.679439,-0.052477,-0.291600', '26352445', '1296252', '1292633', '30318116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298505', '火车怪客', '惊悚', '盖伊（法利·格兰杰 Farley Granger 饰）拥有一段并不幸福的婚姻，他的妻子乔伊斯（凯茜·罗杰斯 Kasey Rogers 饰）是一个水性杨花的浪女，盖伊对妻子的不忠恨之入骨。布鲁诺（罗伯特·沃克 Robert Walker 饰）常年受到专横的父亲安东尼先生（乔纳森·哈勒 Jonathan Hale 饰）的压制，忍无可忍的他逐渐起了杀心。就是这样的两个倒霉男人，他们在一列火车上相遇了。互诉衷肠之后，布鲁诺提出了交换杀人的建议，企图给警方造成无动机的假象。盖伊以为布鲁诺只是开玩笑呢，不置可否，哪知道没过几天，乔伊斯竟然真的死于非命。布鲁诺完成了他的承诺，下面轮到盖伊了。©豆瓣', '法利·格兰杰', '阿尔弗雷德·希区柯克', 8.1, 35637, 'tt0044079', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2155823844.jpg', 0.1, 1, 18.6, 55.6, 24.6, '0.496748,0.005710,-0.633815,0.648730,-0.388744,-0.407094,0.673881,0.103776,-0.319887,-0.140462,0.257591,0.627913,-0.147429,0.274808,0.069992,0.186137,-0.213796,-0.580383,0.086310,-0.248064,-0.344647,-0.749167,-0.090575,-0.275629,-0.134556,-0.263406,0.228807,-0.092657,-0.121599,0.107847,0.554311,0.398587,0.424563,0.399453,-0.108579,0.307825,0.052658,-0.074778,-0.328416,0.300069,0.043876,-0.053808,0.036736,0.432095,-0.258377,0.446404,0.446011,-0.363614,-0.143837,-0.239134,0.386938,-0.339911,0.223898,0.314107,0.222916,-0.103034,-0.052876,0.215827,-0.321756,-0.049895,0.270196,0.157583,-0.645970,0.004755,-0.326739,0.148020,-0.429012,0.604166,-0.346898,-0.145848,-0.052386,-0.166110,0.024521,0.275300,0.338065,0.100891,-0.150298,-0.196621,-0.544070,-0.062643,0.550554,0.018164,-0.190719,0.323087,-0.187188,-0.218954,0.082002,-0.110648,-0.443928,-0.133004,0.333273,-0.066732,-0.103849,0.130601,-0.296880,-0.147242,-0.401835,0.043645,-0.133762,-0.535928,-0.011656,-0.334959,-0.049506,-0.386577,-0.386850,0.030792,-0.015093,-0.348766,0.430593,-0.765304,0.253976,0.678265,0.372777,-0.366753,0.392239,0.342504,-0.101655,-0.323688,-0.020322,0.197564,0.246022,-0.102697,0.456782,0.316864,0.404442,0.106356,0.001293,0.605383', '10774184', '1307442', '1922691', '1306512');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298506', '史崔特先生的故事', '剧情', '阿尔文史崔特先生（理查德·法恩斯沃斯 Richard Farnsworth 饰）已经七十多岁了，他不仅个性孤僻古怪，视力状况也每况愈下。史崔特先生和女儿罗斯（茜茜·斯派塞克 Sissy Spacek 饰）相依为命，父女两人的日子虽然过得清贫，但也不失宁静和乐趣。哥哥莱尔（哈利·戴恩·斯坦通 Harry Dean Stanton 饰）病重的消息打破了史崔特先生家中的平静气氛。虽然由于曾经的矛盾，兄弟两人已经将近十年没有见过面了，但如今史崔特先生已然步入了老年，经历过生命力的种种变幻和无常，史崔特先生决定，是时修补一下兄弟之间的裂痕了。就这样，史崔特先生驾驶着自己的割草机上路了，目的地是300英里之外的威斯康辛州。©豆瓣', '茜茜·斯派塞克', '大卫·林奇', 8.6, 28671, 'tt0166896', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1634826666.jpg', 0.2, 0.9, 11.5, 45.6, 41.8, '0.038647,-0.216175,-0.323944,0.415478,-0.055613,-0.777852,0.677014,0.240093,-0.818930,-0.748673,-0.134966,0.597877,-0.201834,0.384680,0.405885,0.189252,-0.401928,-0.381533,0.146309,-0.276645,0.039854,-0.716613,-0.460597,-0.183332,-0.056035,-0.701083,0.196613,0.085463,-0.012570,0.636919,-0.117424,0.039331,0.054345,0.525781,-0.002170,0.342920,0.138739,-0.023369,-0.575448,-0.291239,0.262088,0.011898,0.000028,0.137947,0.399796,0.444859,0.455594,-0.207522,-0.221141,0.271074,0.117534,0.178061,0.066027,0.244990,0.507231,-0.239156,0.351533,0.528872,-0.152205,-0.118101,-0.226391,-0.066859,-0.463438,0.390491,-0.023713,0.024750,-0.669893,0.618212,-0.594094,-0.414326,-0.231546,-0.292461,0.182698,0.678549,0.327708,0.278886,-0.125412,-0.214623,-0.186417,0.002949,0.568529,0.081440,-0.502831,0.423386,-0.351022,-0.591045,-0.349672,-0.270757,-0.428667,-0.017109,0.056426,-0.063977,-0.034392,0.772874,-0.375825,0.036983,-0.501195,0.086536,-0.117714,-0.080502,-0.100403,-0.439148,-0.197487,-0.742250,-0.300705,-0.014582,-0.143432,-0.118520,0.469301,-0.704185,0.312537,-0.061247,0.120696,-0.038702,0.720846,0.099338,0.077979,-0.166829,0.155129,0.238418,-0.107632,0.163717,0.475784,0.471366,0.161402,-0.305173,-0.147382,0.525278', '1947144', '1308806', '1300685', '24325918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298521', '正午', '剧情', '小镇执法官威尔·凯恩（加里·库柏 Gary Cooper 饰）在卸任的当天，同未婚妻艾米（Grace Kelly 饰）举行了婚礼，两人预备开始蜜月旅行的当口，小镇迎来了三位不速之客，他们是皮尔斯、科比和本，三人在火车站等候五年前被威尔抓获的恶棍弗兰克·米勒。预感小镇将被卷入一场血腥仇杀的人们纷纷躲避，或者力劝威尔离开，但前任执法官执意留下，并开始在镇上寻找帮手，岂料不得升迁的员警哈维、当年审判弗兰克的法官等人全部与此事撇清了关系，新婚妻子亦不支持威尔的坚守，孤立无援的威尔只得拿起自己的枪战斗……这部影片中的时间与真实世界中的时间步调一致。本片获1953年奥斯卡最佳男主角奖等十余项专业褒奖。©豆瓣', '加里·库珀', '弗雷德·金尼曼', 8.4, 22424, 'tt0044706', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164578536.jpg', 0.2, 1.1, 13.2, 50.3, 35.2, '0.186753,-0.163906,-0.560573,0.168390,-0.121709,-0.158677,0.625398,0.279963,-0.423208,-0.109751,0.278218,0.767289,-0.376331,-0.106622,0.671919,-0.225891,-0.441486,-0.773689,-0.066750,-0.022261,0.014820,-0.551782,-0.150916,-0.329379,-0.192798,-0.225522,0.518217,0.039964,0.068011,0.520676,0.264185,0.177464,-0.147479,0.368208,0.104044,-0.057967,0.419145,-0.369772,-0.449849,0.436711,0.080617,-0.313870,-0.295170,0.129103,0.238054,0.422417,0.461125,-0.100229,0.167323,-0.056015,0.012132,-0.303986,0.030565,0.218814,0.214786,-0.121850,0.256726,0.476831,0.130361,-0.159918,-0.009995,-0.281869,-0.311063,0.368994,-0.156743,0.124405,-0.456904,0.504226,-0.301743,0.038692,0.072340,-0.270729,0.230849,0.333693,0.058631,-0.046265,-0.102932,-0.232832,-0.439624,0.288700,0.416874,-0.011207,0.005439,0.072685,0.161473,-0.500228,-0.050796,0.061982,-0.440061,-0.111441,0.535276,0.116223,-0.055564,0.298509,-0.488353,-0.121444,-0.358544,-0.346322,0.129343,-0.278594,0.027874,-0.865155,0.046994,0.005851,-0.362177,-0.125956,0.164278,0.064524,0.297271,-0.590015,0.397049,0.430707,0.171790,-0.420283,0.693076,0.177004,0.635171,0.022580,0.058217,0.111884,0.001876,0.523190,0.232514,0.214890,-0.076798,-0.176971,-0.496507,0.472589', '25833539', '2075345', '11541282', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298522', '小妇人', '剧情', '南北战争时期，马萨诸塞州的康科德城。马其家是镇上一个普通家庭，父亲在外打仗，留下坚强的妻子和四个女儿。Meg十六岁，俨然一个窈窕淑女。Jo（薇瑞娜•赖德）十五岁，喜爱写作，发表的文章为家里付清了各种费用。Beth温柔乖巧，羞怯地爱好着钢琴。Amy最小也最漂亮，也有点 爱出风头。马其太太的坚强给了四个女儿力量，她们时常接济贫穷的居民，圣诞节也不例外。当她们的邻居劳伦斯先生听说此事后便准备了丰富的晚餐给这群可爱的小妇人们。而劳伦斯的孙子劳里也跟Jo成为了好朋友，成为了马其家的一员。他的家庭教师约翰爱上了Meg，Beth在照顾生病的邻居孩子时感染上了猩红热，在最危险的时候，去华盛顿照顾受伤父亲的妈妈回来了，把父亲也带回来，他们一家团聚。四年后，Meg和约翰终于喜结连理，大学毕业的劳里也向Jo求婚，却惨遭拒绝，打击太大的他愤而离家，辗转欧洲，偶遇在欧洲旅游的Amy，此时的Amy早已改掉了虚荣的毛病，她对劳里的关切打动了劳里的心，他们决定结婚。然而此时却传来了Beth病危的消息，还没赶到家Beth已经离开了大家。心灰意冷的Jo去了纽约，认识了她生命中的真命天子。', '薇诺娜·瑞德', '吉莉安·阿姆斯特朗', 8.5, 69803, 'tt0110367', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2445191695.jpg', 0.1, 0.6, 12.1, 49.3, 37.9, '0.285330,-0.084591,-0.747887,0.472657,-0.410857,-0.689324,0.679309,0.136617,-0.378498,-0.287848,-0.027355,0.983037,0.027193,0.598271,0.286084,0.183275,-0.168276,-0.547303,-0.030794,-0.181714,-0.254993,-0.299161,0.038906,-0.120460,-0.033547,-0.265149,0.288593,0.042198,0.046959,0.655514,0.205864,0.039297,0.241394,0.525849,-0.461377,0.168081,-0.075735,-0.015149,-0.166394,0.155342,0.101290,-0.081743,-0.220845,0.205757,0.281054,0.455255,0.598141,0.097514,-0.189388,-0.104431,0.362577,-0.198734,-0.006359,0.315366,0.347784,-0.103997,0.307120,0.028685,-0.341674,-0.032510,-0.239133,-0.104517,-0.567363,0.069736,0.012831,-0.107106,-0.869545,0.592307,-0.086813,-0.168737,0.007437,-0.454235,0.440852,0.524777,-0.342729,0.509637,-0.277191,0.302852,-0.434646,0.211152,0.703787,-0.164689,-0.053581,0.308296,-0.241493,-0.418577,0.272574,-0.387169,-0.656605,0.089951,0.171874,-0.020462,-0.388962,0.129816,-0.485580,-0.167851,-0.272068,-0.275746,0.069852,-0.496980,-0.097091,-0.451570,-0.087279,-0.422051,-0.453301,0.084268,0.103366,-0.060578,0.988952,-0.695549,0.327329,0.510301,0.450888,-0.639471,0.748999,0.190260,0.183063,-0.149067,0.067933,0.208054,-0.035352,0.205877,0.207140,0.348020,0.019013,-0.267822,-0.400744,0.577446', '1292720', '30162520', '1292219', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298525', '碟中谍2', '动作', '超级病毒“金美拉”和抗生素在运送途中，被恐怖组织头目Sean Ambrose（ Dougray Scott  饰）盗走，Ethan Hunt（Tom Cruise 饰）率领他的IMF小组接受中情局的任务，找回病毒。这次，Ethan Hunt找到了女飞贼Nyah Nordoff-Hall（Thandie Newton  饰）搭档，后者是Sean Ambrose的前女友。Ethan Hunt在获取Nyah信任的同时，二人也暗生情愫。但是，为了完成任务，Ethan Hunt不得不安排Nyah回到Sean Ambrose身边卧底。Nyah终于打探出病毒所在的药厂，接获情报的Ethan Hunt前往药厂准备销毁病毒；另一边，Sean Ambrose已经察觉出了Nyah回到自己身边的真正目的，组织人马在药厂等待Ethan Hunt自投罗网。激烈的搏斗中，Nyah为了帮助Ethan Hunt完成任务，将病毒注入了自己体内，只有在20个小时之内将抗生素注入Nyah体内，才能挽救她的性命，Ethan Hunt又将面临不可能的任务。', '汤姆·克鲁斯', '吴宇森', 7.3, 170501, 'tt0120755', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2197697182.jpg', 0.7, 5.4, 38.3, 40.8, 14.8, '0.029160,0.351689,-0.463504,0.367409,-0.307086,-0.022149,0.323627,-0.283708,-0.391754,-0.387939,0.217957,0.488685,0.283081,-0.185075,0.153052,-0.126228,-0.368492,-0.711999,-0.240801,-0.381141,-0.667437,-0.565865,-0.402531,-0.248933,0.203664,-0.502471,0.861755,0.275796,-0.209911,0.320786,0.341723,0.733639,-0.370514,0.477847,-0.063432,-0.278669,0.176635,-0.323746,-0.321905,0.691644,0.351896,-0.374203,0.320455,0.153535,0.246423,0.297277,1.045514,-0.338688,-0.139018,-0.383186,0.177739,-0.588128,0.197173,-0.073059,0.331089,0.485889,0.092193,0.274770,-0.554268,0.133242,0.085868,-0.216983,-1.203125,-0.360847,0.227318,0.068518,-0.443438,0.130773,-0.186005,0.183608,0.168461,-0.387110,0.420351,0.709691,0.286578,0.339911,-0.393785,0.022235,-0.636524,-0.057936,0.687058,-0.573374,0.226563,0.237380,0.122542,-0.528752,-0.039102,-0.330189,0.250567,0.058338,0.311269,0.717145,-0.140047,-0.000459,-0.504519,0.003322,-0.329922,-0.321153,0.261315,-0.338669,0.079942,-0.832997,-0.191946,0.419432,-0.163442,0.273950,0.192540,-0.314136,0.567599,-0.868925,0.099105,0.830380,0.415445,-0.882824,0.332762,-0.069956,0.334871,-0.617203,0.208611,0.060695,0.179203,0.725372,0.295049,0.214466,-0.265003,-0.243016,-0.536161,0.244858', '2369613', '26759820', '26678784', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298528', '花月佳期', '喜剧', '江继威（吴奇隆饰）和洪欣欣（杨采妮饰）同在七夕节去月老庙求姻缘，江继威对外表清纯的张小盈（张庭饰）一见钟情，却因失神撞了想要偷拿红绳的欣欣，恼火的欣欣旋即对其展开“报复”行为，两人变成见面就吵的冤家。两星期后，欣欣在戏台上吊嗓时，却看见了江继威的鬼魂，原来江继威上了张小盈的当，被卷入抢劫案中继而被灭口。不甘心的江继威借助电线回到阳间，且歪打正着跑到欣欣所在的剧院。他希望欣欣可以帮他回到过去，挽回自己被杀的命运。欣欣最终经不住江继威的恳求，和他一起回到了两星期前。©豆瓣', '吴奇隆', '徐克', 7.9, 12198, 'tt0113351', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2528117083.jpg', 0.4, 1.9, 24, 48.7, 25, '0.547833,0.210512,-0.633734,-0.037989,-0.036913,-0.526300,0.737567,0.221971,-0.344013,0.249365,0.215711,0.499484,-0.385753,0.090437,0.176811,0.293451,-0.235610,-0.718844,0.057912,-0.205331,-0.309089,-0.174502,0.051124,0.415069,0.015261,-0.005944,0.325768,-0.155225,-0.038193,0.766140,0.207246,0.185343,-0.119273,0.528952,-0.184249,0.418948,-0.166307,0.011115,-0.327444,0.276910,0.183303,-0.222436,-0.120670,-0.035177,-0.173498,0.218741,0.769034,-0.264090,-0.042132,-0.038855,0.269670,-0.212954,-0.331183,0.298629,0.102188,0.222654,0.235990,0.251497,-0.492775,0.138181,0.300093,0.069554,-0.360655,0.419258,0.045870,0.092608,-0.732301,0.613137,0.053276,-0.109524,0.235148,-0.392585,0.064056,0.320572,-0.046356,0.534094,-0.265181,0.115786,-0.463460,-0.142484,0.692868,-0.002567,0.104542,0.288122,0.305936,0.079478,0.130936,-0.183161,-0.162483,-0.074813,0.459234,0.053608,-0.261142,-0.137306,-0.766371,-0.193963,-0.377600,0.164523,0.051697,-0.441474,-0.352462,-0.350659,-0.118856,-0.381999,-0.275518,-0.013983,0.066161,-0.309238,0.340894,-0.761810,0.150077,0.429577,0.550339,-0.355622,0.718799,0.339677,-0.001157,-0.226284,0.014989,-0.130565,-0.153541,0.800055,0.363396,0.241110,-0.012735,0.083450,-0.508652,0.283887', '1451563', '1294252', '1926007', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298574', '机器战警2', '动作', '在这部续集中，生产机械战警的泛消费公司掌控着底特律城的治安，警察们因薪水迟迟不能到位而举行罢工。凯恩（Tom Noonan 饰）旗下的犯罪集团依靠制造风靡各地的毒品“纽克”大发横财，社会治安极度败坏，到处是暴力事件。机械警察墨菲（Peter Weller 饰）追查毒品，将凯恩的制毒工厂捣毁，由此被凯恩团伙埋伏，惨遭肢解。与此同时，泛消费公司趁市政府财务困难，凭合同欲将城市行政纳入公司范畴，泛消费的新机械战警开发计划屡屡失败，于是请到心理学家菲克斯参与设计，菲克斯改动墨菲的命令程序使其无法如常工作，从错误程序摆脱出来的墨菲带领一干热血干警横扫凯恩总部，但是菲克斯却将凯恩改造成为巨大的机械战警，墨菲与凯恩的再次战斗不可避免……©豆瓣', '彼得·威勒', '厄文·克什纳', 7, 12379, 'tt0100502', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529230959.jpg', 0.7, 5, 49.1, 34, 11.2, '0.324657,0.192831,-0.552252,0.053214,0.115708,-0.099407,0.349983,0.381417,-0.377144,-0.062578,0.143499,0.365255,0.015798,-0.161632,0.249689,-0.167635,-0.490234,-0.562063,-0.152300,-0.045914,-0.043050,-0.368985,-0.047554,-0.384059,-0.194256,-0.525350,0.514777,0.093918,-0.333550,0.197873,0.031641,0.479577,-0.247897,0.299185,0.295901,-0.360742,0.436308,-0.690627,-0.363395,0.358847,-0.170196,-0.175442,-0.044870,-0.062830,0.335828,0.551528,0.682756,-0.200262,0.037087,-0.257464,0.440461,-0.463195,-0.094895,-0.181866,0.229861,0.281902,-0.252283,0.269844,-0.489361,0.099607,0.294976,-0.434180,-0.997749,-0.191387,0.077145,0.181402,-0.408862,-0.023959,-0.253747,0.139610,-0.065405,-0.192228,0.042764,0.278736,0.311313,0.079189,-0.013632,0.263608,-0.785628,0.298965,0.448565,-0.178056,-0.256984,-0.114335,-0.240010,-0.392679,-0.153372,-0.447573,-0.076483,-0.232438,0.296532,-0.042612,0.111572,0.176991,-0.551565,-0.257358,-0.491910,-0.715695,-0.093669,-0.185299,-0.123534,-0.976838,-0.107305,0.234645,-0.023575,0.031760,0.076906,0.046731,0.253635,-0.756461,-0.050381,0.558300,0.316787,-0.502116,0.212913,-0.156689,0.208036,-0.097242,-0.436947,-0.013597,0.417099,0.570504,0.304276,0.228460,0.224764,-0.375889,0.119059,0.366210', '27073234', '2369613', '1308752', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298581', '星尘往事', '剧情', '桑迪（伍迪·艾伦 Woody Allen 饰）是一个颇有名气的导演，他所拍摄的喜剧作品深得观众的喜爱。无论走到哪里，桑迪都被他的诸多粉丝拥簇着，甚至有女粉丝买通门卫，躲在他的被窝里想要和他共度春宵，这让桑迪深感困扰。逐渐的，桑迪发现自己不再有创作喜剧的欲望，可他最近正 在拍摄的正剧却没有得到制片人的肯定。令桑迪郁闷的还远不止这些，女友多丽娅（夏洛特·兰普林 Charlotte Rampling 饰）的躁郁症眼见着有加重的趋势；情人伊莎贝尔（玛丽-克里斯汀·巴洛特 Marie-Christine Barrault 饰）和丈夫决裂，带着孩子投奔桑迪，却不愿和他共居一室，除此之外，作风极具个性的小提琴家戴茜（杰西卡·哈勃 Jessica Harper 饰）迷得桑迪神魂颠倒。站在人生交叉点的桑迪该何去何从？©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 8.1, 7828, 'tt0081554', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2180919216.jpg', 0.3, 1.6, 19.6, 49.3, 29.3, '0.359550,-0.262601,-0.858192,0.733417,-0.028088,-0.148508,0.932869,0.272350,-0.409978,-0.174760,0.256406,0.670698,-0.474588,0.362964,0.240138,0.111725,-0.300195,-0.642104,-0.308197,0.046369,-0.137642,-0.393773,-0.384010,-0.054305,-0.184394,-0.375421,0.699100,-0.038621,-0.183803,0.256399,0.509252,0.255530,0.081625,0.611927,-0.153351,0.379177,0.210812,-0.082827,0.036522,0.023099,0.381030,-0.371975,-0.322476,0.208961,-0.016157,0.451733,0.502357,-0.202494,0.039936,0.297825,0.420320,-0.292895,0.010461,0.111096,0.117010,-0.270053,0.186585,-0.097616,-0.224219,-0.047965,0.149822,0.141367,-0.862736,0.197001,0.216213,0.413956,-0.577708,0.431544,-0.273890,-0.169201,0.145718,-0.189231,-0.010636,0.192221,0.050642,0.298357,0.029813,0.077149,-0.578614,0.187820,0.531145,0.349529,-0.181250,0.402057,-0.497198,-0.222818,-0.048047,-0.099267,-0.837184,-0.282587,0.352373,-0.081180,0.003551,0.165126,-0.271495,0.131500,0.005740,-0.239954,-0.026369,-0.560907,-0.103483,-0.671901,-0.182358,-0.617543,-0.060112,-0.086944,0.216238,-0.274766,0.814086,-0.716555,0.191694,0.581245,0.278162,-0.425026,0.791803,0.123602,-0.082954,-0.025161,-0.492682,0.199439,-0.076738,-0.004433,0.344644,0.490585,0.100084,-0.332617,-0.318862,0.525291', '4847665', '1303077', '1304641', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298586', '木乃伊归来', '动作', '公元前3067年，魔蝎大帝（“岩石”洛克Dwayne Johnson 饰）率领大军企图征服世界，但他的野心在长达七年的战役中遭到挫败，他的残兵败部进入神圣的阿姆谢沙漠，严酷的环境使得曾经骁勇的战士们接连倒毙，濒临死亡的魔蝎大帝向死神阿努比斯献出灵魂，以求打败他的敌人。在此之后，魔蝎大帝及来自地狱的死神军团所向披靡，大获全胜的死神军团也重新沉睡地下。1933年埃及，瑞克·奥克康纳（布兰登•弗雷泽 Brendan Fraser 饰）和艾弗琳（瑞切尔•薇茨Rachel Weisz 饰）带着他们的儿子艾里克斯（弗莱迪•布斯Freddie Boath 饰）重返此地，并发现了魔蝎大帝的手镯。与此同时，另一伙神秘组织找到邪恶法老伊莫特的尸体，他们需要那只手镯复活伊莫特。针对手镯的正邪争夺战旋即展开，瑞克夫妇不得不面对新一轮的奇幻大冒险……©豆瓣', '布兰登·费舍', '斯蒂芬·索莫斯', 7.6, 131604, 'tt0209163', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p847064824.jpg', 0.3, 2.6, 32.4, 48.2, 16.5, '-0.084129,0.207566,-0.574660,0.625394,0.123961,0.010293,0.599462,-0.154196,-0.273049,-0.274392,0.484554,0.434831,0.119372,-0.095049,0.253720,0.015668,-0.226960,-0.495767,-0.086975,-0.071227,-0.372678,-0.000703,-0.422535,-0.308524,0.066913,-0.748021,0.733062,0.096659,0.157887,0.254410,0.074248,0.796718,-0.198439,0.395447,0.153731,0.076034,0.119693,-0.356743,-0.340676,0.451814,-0.452594,0.364293,-0.219557,0.484799,-0.201943,0.128522,0.727915,-0.936316,0.424888,-0.444100,0.263754,-0.283730,0.030477,-0.010991,0.590792,-0.203322,0.019888,0.170284,0.153556,-0.170489,-0.141377,-0.215446,-0.761180,-0.192231,-0.111594,0.141281,-0.275296,0.413764,0.002442,0.537691,0.221649,0.131393,0.067043,0.474736,0.347731,0.201866,0.174874,-0.244517,-0.327685,-0.049581,0.409790,-0.131866,-0.352146,-0.314275,-0.068588,-0.745082,-0.293785,-0.234063,-0.206379,-0.027413,0.481906,0.015459,0.090893,0.783088,-1.049338,-0.262363,-0.467631,0.005227,0.143251,-0.172810,-0.122290,-0.478554,-0.008435,-0.140905,-0.041222,0.087505,0.014834,0.084299,0.179630,-0.631235,0.571222,0.464969,0.440863,-0.004168,0.505754,-0.428422,0.042397,-0.390763,-0.120749,0.818322,0.464654,0.230667,0.403989,0.036228,0.146565,0.117754,-0.239774,0.483955', '20326665', '7056398', '2158490', '3321892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298589', '新流星蝴蝶剑', '爱情', '明中叶，东西两厂明争暗斗不断。东厂曹公公手下养了三大高手，分别是孟星魂（梁朝伟饰）、高老大（杨紫琼饰）、叶翔（甄子丹饰）三大高手，亦有小王爷（林志颖饰）帮忙。高老大经营快活林，孟星魂与叶翔皆是其从小养大的结拜弟弟，三人亲如手足。叶翔暗恋大姐，大姐却对孟星魂情有独钟。孟星魂与八卦门掌门之女小蝶（王祖贤饰）是爱侣，小蝶亦已怀有孟之骨肉。四人面对纠缠的感情痛苦不已，而此时孟星魂亦与高大姐接下刺杀孙玉函（徐锦江饰），将西厂李公公控制下的聚贤山庄一网打尽的任务。到底任务能否完成？而四人的感情又将何去何从？©豆瓣', '梁朝伟', '麦当杰', 6.9, 17131, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1693315871.jpg', 0.7, 5.9, 51.2, 32.5, 9.6, '-0.162826,-0.272074,-0.241945,0.538851,0.130701,-0.226191,0.349170,0.161990,-0.400222,-0.213802,0.442103,0.383129,0.224939,0.021848,0.024295,-0.272164,0.229524,-0.663136,-0.265294,-0.200392,-0.008052,-0.352841,-0.291932,0.053561,-0.064473,-0.027088,0.451158,-0.158154,-0.032631,0.290867,0.644194,0.161816,-0.682168,0.152091,0.039987,-0.099704,0.205463,0.148523,-0.566999,-0.154172,-0.179124,-0.112254,-0.075842,-0.215994,0.202254,0.175616,0.339110,-0.207321,-0.070940,-0.262290,-0.028772,-0.051492,0.116990,-0.034546,0.190729,0.155379,0.339457,0.449938,-0.010022,0.017561,0.047719,-0.083945,-0.581929,0.118333,0.617316,-0.182464,-0.456466,0.451018,-0.175403,-0.077356,-0.175553,-0.289469,0.109244,0.287334,0.128855,0.389214,-0.109143,-0.057215,-0.304582,0.079599,0.412787,0.020124,0.200514,-0.207247,0.251687,-0.304992,0.126789,-0.319531,-0.149454,-0.004365,0.332452,0.217622,0.295809,0.429862,-0.127673,-0.039027,-0.132234,0.277472,0.117203,-0.399007,0.290060,-0.256868,-0.239452,-0.424983,-0.432362,-0.153608,0.521325,-0.178305,0.773043,-0.654823,0.009119,-0.124933,0.249638,-0.729121,0.326540,0.094900,0.241658,-0.299452,-0.464735,-0.092608,-0.050334,-0.019043,0.186317,0.224332,-0.117034,-0.219524,-0.345524,-0.127114', '4301278', '26730542', '3670447', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298593', '金刚', '动作', '导演卡尔·丹汉姆（罗伯特·阿姆斯特朗 Robert Armstrong饰）为了完成他的电影而来到了荒无人烟的骷髅岛。一只巨大的非洲大猩猩金刚居住在这个与世隔绝的岛上。然而它却被卡尔逮住并带到了纽约，在那里它成了供人观赏的怪物。卡尔一直为没有找到适合的女主角而烦恼，直到他遇见了貌如天仙的美丽女孩安·达罗（菲伊·雷 Fay Wray饰）。而此刻，金刚也深深地爱上了安。1933版本的黑白影片《金刚》，融合动画、真人和模型为一体，开创了特技片的先河，在当年取得了巨大成功，轰动一时。“金刚”也成为日后影坛翻拍无数的英雄角色。本片荣获2006年第32届美国电影电视土星奖-最佳经典影片DVD提名。©豆瓣', '菲伊·雷', '梅里安·C·库珀', 7.7, 7357, 'tt0024216', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1518925250.jpg', 0.5, 2.3, 28, 49.8, 19.3, '-0.045008,0.014920,-0.682398,0.661998,0.203718,-0.246593,0.557717,0.170129,-0.359999,-0.131217,0.087780,0.918274,-0.446187,0.057681,0.189501,0.152861,-0.119478,-0.568124,-0.072618,-0.136734,0.029064,-0.036663,-0.359087,-0.149600,0.069299,-0.511365,0.807840,0.121320,-0.099664,0.125468,0.375161,0.126230,-0.048364,0.192859,-0.206743,0.216351,-0.046427,-0.010233,-0.098395,0.615215,-0.335500,-0.151947,-0.039523,0.106513,-0.138260,0.194710,0.623076,-0.370302,-0.068020,-0.198978,0.445105,-0.345914,-0.070306,-0.231672,0.313475,-0.242048,0.224885,-0.025205,0.062718,0.261428,0.134313,-0.508448,-0.770707,-0.064999,0.236820,0.102840,-0.508099,0.694365,-0.095428,0.174699,-0.206660,-0.098224,0.341458,0.050203,0.379366,0.272680,-0.094427,0.136018,-0.523616,0.681557,0.378136,0.152455,-0.321633,0.504179,-0.063644,-0.592895,-0.419320,-0.463175,-0.242301,0.014871,0.433924,0.003972,-0.161129,0.032104,-0.635199,-0.191271,-0.241634,-0.101893,-0.146320,-0.351206,-0.061852,-0.711924,0.092287,-0.243830,0.012658,-0.142199,-0.123594,-0.355474,0.690249,-0.735917,0.435447,0.372618,0.057374,-0.146291,0.906657,-0.255721,-0.130417,-0.278203,-0.051549,0.383746,0.114510,0.462926,0.144535,0.226451,-0.054102,-0.328144,-0.538534,0.551594', '1870681', '25880986', '2027945', '4144683');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298596', '裸体午餐', '剧情', '1953年的纽约，杀虫人比尔（Peter Weller 饰）进行着孤独的个人写作，只有两个好友知晓他的文学尝试。比尔的妻子琼（Judy Davis 饰）沉迷于注射杀虫粉，比尔为她拜访了戒毒医生班威，不久被麻醉品管理处传讯，在那里他遇到了能说话的虫子，它指出比尔的真实身份是一名间谍，比尔惊慌失措的逃回家，开枪误杀妻子，只得按照怪异生物的指点远赴中东的“区间”避难。当地的黑肉场场主、美国作家和他酷似琼的妻子、同性恋商人、以及集市上的女人看起来无不是一桩阴谋的一部分，比尔在自己那台会说话的打字机“克拉克诺瓦”的帮助下进行创作，并不断接近阴谋的真相，在又一次失去了琼以后，比尔发现了区间同班威医生的联系。本片获1993年伦敦电影节年度女演员奖，1992年加拿大吉尼奖最佳导演、最佳摄影等多项褒奖。根据威廉·罗伯斯同名小说改编。©豆瓣', '彼得·威勒', '大卫·柯南伯格', 7.6, 8809, 'tt0102511', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2186935450.jpg', 1.6, 4.7, 29.8, 42.4, 21.6, '0.253073,-0.166721,-0.438687,0.565463,0.049603,-0.212598,0.411475,-0.012089,-0.344452,-0.244565,0.118621,0.695665,-0.149264,0.200634,0.209618,-0.033482,-0.297716,-0.557946,0.008693,-0.207721,-0.155055,-0.491427,-0.313563,-0.239563,-0.042085,-0.450865,0.537681,-0.124024,-0.180731,0.439221,0.180741,0.048314,0.010269,0.156095,-0.072152,-0.060068,0.166591,-0.221393,-0.327235,0.416355,0.080273,-0.308691,-0.124759,0.016312,0.054507,0.385208,0.553739,-0.214886,-0.059133,0.023006,0.464319,-0.133769,0.080431,-0.005491,0.357333,-0.089001,0.159398,0.215554,-0.242051,0.043975,-0.054780,-0.065475,-0.683335,0.053984,0.043027,0.345389,-0.530999,0.336791,-0.219932,0.177338,-0.061243,-0.202554,0.170790,0.315074,0.100879,0.242000,0.023264,0.077194,-0.355405,0.297878,0.367260,0.053467,-0.313118,0.064439,-0.209688,-0.399929,0.034876,-0.181772,-0.327911,0.070615,0.384476,-0.082026,-0.242847,-0.078443,-0.431822,-0.015755,-0.284267,-0.184679,-0.080718,-0.061884,-0.005148,-0.877003,-0.023592,-0.216899,-0.159941,-0.271431,0.094368,-0.408392,0.639809,-0.708381,0.160058,0.685243,0.327054,-0.438105,0.689995,0.001454,-0.073283,-0.361404,-0.206489,0.310065,0.198450,0.128645,0.030969,0.314395,0.147240,-0.272610,-0.280382,0.291944', '2369613', '3811356', '1293656', '10763928');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298603', '望夫成龙', '喜剧', '石金水（周星驰 饰）与吴带娣（吴君如 饰）同在乡下长大，二人青梅竹马，也私定终生了。由于阿娣的父亲反对，两人不得不私奔到市区生活。刚开始金水的求职路十分不顺，处处碰壁，夫妻俩过着拮据的生活。得到工作后的金水勤奋工作得到了上司Nancy赏识提携。二人更渐生情愫，导致了金水与妻子阿娣感情破裂，阿娣伤心离去。两年后，金水浪子回头，决定找回昔日的爱妻。©豆瓣', '周星驰', '梁家树', 7.5, 40664, 'tt0100902', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2349243229.jpg', 0.5, 3.7, 38, 38.3, 19.5, '0.033793,-0.170975,-0.675651,0.409119,0.189586,-0.792259,0.494594,0.366970,-0.825050,-0.123611,0.073989,0.640414,-0.193468,0.467560,0.327569,-0.337268,-0.275395,-0.391465,0.088379,-0.114725,0.027907,-0.461597,0.097860,0.094540,-0.521382,-0.224024,0.667803,0.090124,0.126884,0.633865,0.125659,0.099390,-0.198182,0.182925,-0.146613,0.342040,-0.163504,0.637815,-0.735094,-0.245082,0.377688,0.046730,-0.236415,-0.211971,0.287314,0.240145,0.527306,-0.012577,-0.290092,-0.080378,0.392560,-0.107532,-0.007357,0.142092,0.271532,0.088893,0.260571,0.479231,-0.400594,0.198094,-0.068582,-0.011315,-0.059814,0.082723,0.005866,-0.043900,-0.704532,0.386318,0.141858,-0.332441,0.102807,-0.605512,-0.046557,0.536876,-0.081671,0.361227,-0.473161,-0.010502,-0.419889,0.452822,0.925416,0.066070,0.144049,0.419821,0.026397,-0.352646,0.126951,0.005392,-0.530072,-0.023507,0.331040,0.330171,-0.127614,0.299540,-0.704668,-0.154329,-0.101991,0.314171,0.487188,-0.330496,0.135424,-0.596990,-0.266707,-0.480035,-0.447955,0.097454,-0.067052,-0.293977,0.544794,-0.886194,0.233397,0.095279,0.378237,-0.975477,0.296547,0.250676,0.377104,-0.436137,0.204724,0.232577,-0.146838,0.263987,0.274336,-0.027437,-0.337728,0.071465,-0.379252,0.145413', '1308035', '1293265', '6890343', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298616', '最后一班地铁', '剧情', '二战中德国占领下的巴黎，剧作家、导演兼剧院管理人的犹太人卢卡斯•斯坦纳（海因茨•本南特 Heinz Bennent 饰）被妻子玛丽安•斯坦纳（凯撒琳•丹尼芙 Catherine Deneuve 饰）藏入蒙马特剧院地下室，伺机逃往非占领区。身为演员的玛丽安不得不肩负起剧院管理人的事宜，雇佣了男演员伯纳德•格兰戈（杰拉尔•德帕迪约 Gérard Depardieu 饰）排练卢卡斯的新话剧。随着德军战线的扩大，卢卡斯的出逃一步步成为幻影，只好靠地下室的采暖管道来听每日的彩排，暗中进行指导……本片获法国恺撒奖最佳影片、最佳导演（弗朗科依斯•特吕弗）、最佳剧本、最佳剪辑、最佳摄影、最佳男主角（杰拉尔•德帕迪约）、最佳女主角（凯撒琳•丹尼芙）、最佳音乐、最佳舞台设计和最佳声音十项大奖，并获最佳男配角（海因茨•本南特）和最佳女配角（安德烈亚•费雷奥尔Andréa Ferréol）提名。本片同时获金球奖和奥斯卡奖最佳外语片提名。', '凯瑟琳·德纳芙', '弗朗索瓦·特吕弗', 7.7, 9719, 'tt0080610', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2198125083.jpg', 0.4, 2.3, 27.7, 50, 19.6, '-0.161638,-0.140994,-0.534062,0.552745,0.299162,-0.275649,0.412642,0.238544,-0.089215,-0.038950,0.337858,1.057989,-0.341495,-0.292394,0.646501,0.091762,-1.100663,-0.806268,-0.146119,-0.226745,0.079779,-0.622842,-0.219154,0.046021,-0.198199,-0.251973,0.944072,-0.474695,0.081222,0.374657,0.652741,0.131630,0.023816,-0.184411,0.163609,0.194905,0.836306,-0.578009,-0.525186,0.702457,0.010399,-0.141189,-0.516700,0.100886,0.328614,0.280823,0.472926,-0.210534,0.578727,0.131143,0.527782,-0.286611,0.157734,-0.212455,0.075697,-0.368668,0.446263,0.218575,-0.154813,0.229678,-0.053832,-0.415561,-0.660790,0.232381,0.357028,-0.031297,-0.209701,0.029214,-0.065924,0.274309,0.126976,0.093525,-0.049149,0.234367,0.271622,0.032039,-0.112368,0.064336,-0.127456,0.479491,-0.079404,-0.099484,-0.382372,0.126446,0.085618,-0.576271,0.061074,-0.074478,-0.288209,-0.152494,0.652612,-0.123343,0.597371,-0.205055,-0.300935,-0.134640,-0.320382,-0.324121,-0.075925,0.015846,0.143937,-1.387634,0.016763,0.057372,0.105406,-0.359305,-0.003303,-0.104420,0.340908,-0.442273,0.040498,0.513427,0.060169,-0.014002,0.469263,0.063435,0.561687,-0.423858,-0.378436,0.220259,-0.342827,0.190959,0.073181,0.316217,0.076633,-0.463945,-0.4518