INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298624', '闻香识女人', '剧情', '查理（克里斯•奥唐纳 Chris O''Donnell  饰）是一个普通的中学生，他因为见证着一件恶作剧但又不想出卖朋友，于是面临着一道艰难的选择题——要么坦白，要么被学校勒退。而史法兰（阿尔•帕西诺 Al Pacino  饰）是一个退伍军官，因为意外失明，人生从顶点的辉煌滑落谷底。自从两人的人生有了交集，命运的转折慢慢清晰。史法兰打算结束失去了意义的生活，于是在查理的陪伴下，尽情享受着人生最后一趟出行。他吃最美味的佳肴，买光鲜的汽车，在狭窄的街道上飚车，住在豪华的套房里，跟随陌生女子的袅袅香水味，跳一段优雅性感的探戈……极乐的疯狂后，他拿枪对准了自己的头颅。然而，查理声嘶力竭的劝阻改变了一切，曙光亦渐渐在这个老人心中重新升起，二人情深如父子。史法兰在学校礼堂激昂演说，挽救了查理的前途，讽刺了学校的伪善。二人在互相鼓舞中得到重生。©豆瓣', '阿尔·帕西诺', '马丁·布莱斯特', 9.1, 817082, 'tt0105323', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2550757929.jpg', 0.1, 0.4, 6, 30.8, 62.6, '0.411389,0.167503,-0.577503,0.607558,-0.103971,-0.334804,0.905577,0.330034,-0.299312,0.095982,0.397851,0.620974,-0.130231,0.217833,0.484734,-0.045290,-0.358151,-0.691584,0.142500,-0.133814,-0.090142,-0.400851,-0.110799,-0.330329,-0.058180,-0.220474,0.507838,0.106521,-0.118808,0.710692,0.244822,0.147614,-0.059709,0.347425,-0.266164,-0.062366,0.139159,0.002063,-0.288231,0.067007,-0.029876,-0.354292,-0.124800,0.294567,-0.039615,0.207668,0.664246,-0.265308,-0.167962,0.204061,0.430220,-0.065103,-0.030570,0.111887,0.151249,0.160600,-0.096475,0.063704,-0.110490,-0.040765,0.192367,-0.043649,-0.657791,-0.058009,-0.236959,0.194270,-0.569238,0.799262,-0.083141,-0.179718,0.299243,-0.228052,0.333007,0.240093,0.287370,0.411565,-0.195894,0.144823,-0.433318,0.302256,0.694449,0.009778,-0.296644,0.439520,-0.471260,-0.348823,-0.034686,0.000746,-0.574074,-0.342047,0.557101,0.117405,-0.155754,0.244140,-0.497474,0.041319,-0.104430,-0.274820,-0.037299,-0.253940,-0.292875,-0.364607,-0.286068,-0.237438,-0.240386,0.128368,-0.249355,-0.103934,0.576250,-0.610968,0.368328,0.498326,0.041815,-0.089976,0.743634,-0.062436,0.207085,-0.037112,0.073228,0.439122,-0.084786,0.324238,0.225486,0.508430,-0.332457,0.273034,-0.402251,0.747256', '26687241', '1309172'