INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298635', '蒸发密令', '剧情', '艾伦（范妮莎•L•威廉姆斯 Vanessa Williams 饰）是美国最大武器武器制造公司西历公司的高级职员，她慢慢发现了这加公司的一些黑幕――该公司生产了一种明令禁止的武器并在黑市交易。FBI利用艾伦获得了一些证据，艾伦成了本案的关键证人。鉴于这间公司的势力，证人保护中心派出了法警约翰（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）前往保护艾伦。当约翰赶到艾伦家时，杀手正在谋杀艾伦。约翰救出了惊魂未定的艾伦，并告诉了她现在情况。安顿好艾伦后，约翰前往酒吧和同伴罗伯特（詹姆斯•凯恩 James Caan 饰）见面，罗伯特告诉约翰因为保护证人的计划泄漏，要重新安排，并要求约翰一起行动。向来都是独立完成任务的约翰起了疑心，他慢慢开始觉得这件事背后的势力并不简单。©豆瓣', '阿诺·施瓦辛格', '查克·拉塞尔', 7.4, 27956, 'tt0116213', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2398105543.jpg', 0.3, 2.3, 37.6, 47, 12.8, '0.294993,0.052502,-0.387125,0.221020,-0.110166,-0.248026,0.379192,0.188632,-0.354755,-0.594383,0.159373,0.566645,0.166767,0.108856,0.279420,-0.023193,-0.726252,-0.532253,0.122959,-0.279451,-0.360690,-0.747233,0.099061,-0.684344,0.111424,-0.173001,0.498924,-0.017988,-0.059874,0.168818,0.146917,0.237954,-0.089029,0.305605,0.318240,-0.273225,0.377346,-0.332551,-0.602312,0.330922,-0.028582,0.092836,0.033580,0.437600,0.426223,0.482122,0.225366,0.046748,-0.150325,-0.132018,0.162612,-0.103622,0.272283,-0.193064,0.366229,0.031710,0.011781,0.243494,-0.144682,0.074345,-0.036573,-0.149590,-0.860276,0.059087,0.080610,0.118327,-0.486618,0.029173,-0.405786,0.362206,0.059772,-0.383082,0.182688,0.619381,0.165431,-0.028135,-0.043118,0.142451,-0.566027,0.045155,0.337740,-0.258393,0.257348,0.157520,-0.156561,-0.435526,-0.217326,0.208301,-0.017161,-0.026003,0.266692,0.235705,0.056213,0.129366,-0.556122,-0.315570,-0.288025,-0.223283,0.020289,-0.417433,0.372403,-0.684504,0.038771,0.117465,-0.255164,-0.128888,0.005468,-0.120578,0.328245,-0.649797,-0.039541,0.836179,0.452698,-0.512920,0.144302,-0.017690,0.300685,-0.477430,-0.189759,0.078467,0.274823,0.303788,0.151989,0.222382,0.489730,-0.570688,-0.205458,0.110466', '1401535', '1292573', '1307442', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298638', '鸟人', '剧情', '伯迪（马修·莫迪恩 Matthew Modine 饰）是个从小活在幻想中的孩子，他一直向往鸟的生活，羡慕他们有翅膀可以飞翔，自己也兴致勃勃地动手制作翅膀，幻想有朝一日飞上天空。越战爆发打断少年美梦。战场上残忍的一幕幕让内心脆弱的伯迪受到极大刺激，终于失去理智，成为现实意义中的“精神病人”，被送进医院。在医院里，他从不说话，每天以鸟的姿态蹲着，以鸟的方式吃东西，在牢笼里望着一方小小的蓝天向往飞翔。为了治疗伯迪，医院找来他的儿时好友艾尔（尼古拉斯·凯奇 Nicolas Cage 饰），希望他能引导伯迪重新和人交流。艾尔用大量共同回忆开启伯迪的心智，也认识到对伯迪来说只有飞翔的梦想是永恒的……本片根据威廉  ·霍顿发表于1978年的小说改编而成，曾获戛纳电影节评委会大奖。©豆瓣', '马修·莫迪恩', '艾伦·帕克', 8.3, 23262, 'tt0086969', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p852618632.jpg', 0.2, 1.2, 15.3, 49.7, 33.5, '0.102119,0.163379,-0.690880,0.661668,0.035297,-0.042426,0.672568,0.036128,-0.337651,-0.085257,0.137565,0.649441,-0.054678,0.389109,0.111231,-0.073329,-0.338682,-0.606047,-0.106923,0.042328,-0.006500,-0.313125,-0.345764,-0.204246,-0.194569,-0.383951,0.620924,0.018706,-0.249944,0.498689,0.177730,0.181250,-0.012614,0.253398,-0.342338,-0.099938,-0.082502,0.262651,-0.219335,0.223552,-0.050455,-0.157243,-0.063925,0.153763,-0.019131,-0.136250,0.819031,-0.437877,-0.048969,-0.193631,0.303385,-0.240819,0.080267,0.101487,-0.022982,0.223576,0.175600,-0.209198,-0.118236,0.197699,0.038815,-0.200836,-0.798919,-0.297390,-0.010528,0.149206,-0.603285,0.400078,0.062706,0.021295,0.265474,-0.172671,0.102196,-0.150569,0.208477,0.528441,-0.086357,0.104864,-0.329744,0.183739,0.513827,-0.308644,-0.383850,0.306987,-0.477225,-0.242805,-0.073778,-0.147373,-0.564167,-0.235096,0.154885,0.137837,-0.332946,0.252203,-0.383128,0.289258,-0.145849,-0.253571,0.028022,-0.447485,-0.021690,-0.507638,-0.101395,-0.259978,-0.130020,-0.111459,0.048783,-0.471435,0.683326,-0.749191,0.545030,0.416950,0.212408,-0.140831,0.735396,0.005962,-0.180671,-0.203658,0.042827,0.482718,-0.086041,0.131142,-0.049523,0.066034,0.101824,0.253133,-0.399293,0.674003', '26021055', '30401849', '1303077', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298644', '赌圣', '喜剧', '大陆青年左颂星（周星驰）到港投靠三叔（吴孟达），嗜赌的三叔发现他有特异功能后，以为找到发家致富的康庄大道，开始带他出入各大赌场，并要他以赌神为偶像，将赌技再发扬光大成为新一代赌圣。风头正劲的左颂星引起台湾赌王陈松与香港赌王洪光（秦沛）的注意，双方均欲夺左颂星为其手下代表其出席世界赌王大赛。陈松成功将左颂星罗至门下后，洪光派来美女绮梦（张敏）将左颂星迷得晕头转向，又在大赛决赛时刻令绮梦消失，以期左颂星无心应战将赌王宝座拱手相让。©豆瓣', '周星驰', '元奎', 7.9, 193217, 'tt0104147', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1148006580.jpg', 0.2, 1.7, 26.9, 46.3, 24.8, '-0.305806,0.487453,-0.661878,0.362551,0.010586,-0.074001,-0.000319,-0.102267,-0.570929,0.206268,0.242489,0.926936,-0.374771,0.052212,0.520012,-0.050809,0.113454,-0.843940,-0.261965,-0.110811,-0.085937,0.040018,-0.089366,0.294977,-0.393569,-0.141072,0.720397,-0.100758,-0.327016,0.692835,0.374689,0.035974,0.104625,0.477451,-0.062031,0.055405,-0.086385,-0.133648,-0.636464,0.576856,-0.009704,-0.105173,-0.370708,0.107632,0.003107,-0.095645,0.483392,0.091869,0.243879,-0.288497,0.249150,-0.372822,-0.166303,-0.189725,0.306221,0.147401,-0.061251,0.416278,-0.098039,0.112818,0.209811,-0.052729,-0.553096,0.255909,0.211208,0.068264,-0.497188,0.140429,-0.247047,-0.196801,-0.070835,-0.036681,0.286276,0.322618,0.255038,-0.229320,0.072763,0.055421,-0.492312,0.322223,0.441554,-0.283424,0.116945,-0.162857,0.557260,-0.409217,0.392062,-0.546403,-0.043952,0.030791,0.390819,0.034209,0.165434,0.024235,-0.220038,-0.200249,-0.117867,-0.261557,0.268172,-0.291101,-0.038590,-0.617805,-0.209813,0.199215,0.162729,-0.252876,0.222120,-0.337593,0.623227,-0.792487,0.100629,0.365037,0.359665,-0.607948,0.686180,-0.051747,0.180445,-0.376079,-0.543996,-0.124745,0.296010,0.453669,-0.130747,0.146981,-0.173355,-0.432024,-0.045734,0.228584', '1780122', '1897368', '4301278', '1996313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298653', '荒岛余生', '剧情', '查克（汤姆•汉克斯 Tom Hanks饰）任职于美国联邦快递，他系统工程师的职业决定了他的生活忙碌、自律、充满时间紧迫感。而查克总能把一切工作都井井有序的安排在每天的日程里，时间就在他的控制之下。他无暇顾及的只是女朋友凯莉（海伦•亨特 Helen Hunt 饰）。一场飞机失事改变了这一切。所有人都以为查克丧生于这场灾难中，然而事实上他活了下来，被困在一个荒无人烟的小岛上。荒岛上的生活就连吃喝都成问题，查克成为了现代鲁滨逊。但另一方面，他在这里却因为与大自然依存，与险境搏斗，与孤独作伴，与饥饿抗争，得到了以前从来没有领悟到的感受。当他回到现代社会时，人生有了新的开始。©豆瓣', '汤姆·汉克斯', '罗伯特·泽米吉斯', 8.6, 263465, 'tt0162222', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2207673534.jpg', 0.1, 0.5, 10.4, 45.9, 43, '0.154986,0.075376,-0.915722,0.525399,-0.242387,-0.333472,0.757672,-0.059336,-0.523719,-0.282213,0.064284,0.700697,-0.070753,0.287177,0.284474,-0.181376,-0.618978,-0.881931,-0.072221,0.033045,-0.295409,-0.375150,-0.386664,-0.303801,-0.292339,-0.189773,0.694643,0.200584,-0.010608,0.320069,-0.026718,0.133506,0.087050,0.729421,-0.267100,-0.014190,-0.001870,0.031096,-0.352283,0.040413,0.159535,-0.137546,-0.108997,0.266405,0.308884,0.224063,0.607079,-0.284597,-0.302309,-0.010280,0.230740,-0.202843,-0.061152,0.154810,0.177716,-0.017699,0.011587,0.166173,-0.279747,0.008467,0.032336,0.134786,-0.713246,-0.125372,-0.182927,0.114223,-0.516930,0.541061,-0.002547,-0.116838,-0.287338,-0.457560,0.318309,0.284286,0.315551,0.386558,-0.174960,-0.231912,-0.476956,0.275295,0.932724,-0.142867,-0.576138,0.408220,-0.257296,-0.434817,-0.232582,-0.250700,-0.461451,-0.182113,-0.079101,0.121936,-0.377207,0.411235,-0.568083,0.347524,-0.120423,-0.587115,-0.142393,-0.482471,-0.204296,-0.612444,-0.065845,-0.514776,-0.482514,0.045116,0.187035,-0.349852,0.565811,-1.001522,0.428144,0.602505,0.162032,-0.305812,0.821910,0.088583,0.426273,0.045508,0.217297,0.288844,-0.276213,0.482008,0.225159,0.318342,-0.018709,0.152498,-0.405602,0.843990', '1870682', '1308755', '3055049', '1652618');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298655', '玛丽娅·布劳恩的婚姻', '剧情', '德国人玛丽娅（汉娜·许古拉 Hanna Schygulla饰）和赫尔曼（克劳斯·洛维斯奇Klaus Löwitsch饰）的婚姻在乱世中注定了动荡飘摇。在赫尔曼上战场之后，玛丽娅等候丈夫回来的心从焦急变为绝望，德国战败，赫尔曼大概也在前线牺牲了，玛丽娅只好嫁给了一个黑人军官比尔（格雷戈·伊格斯Greg Eagles饰）。然而，在玛丽娅的心中，赫尔曼永远是无法抹去的至爱。奇迹发生了，赫尔曼竟是没死，他的回来引发了和比尔之间的决斗。慌乱中玛丽娅举起凶器，杀死了比尔。这项谋杀罪赫尔曼自愿顶了下来，赫尔曼的入狱，令玛丽娅再一次陷入了无尽的等待。富商奥斯瓦尔德（伊凡·德斯尼 Ivan Desny饰）对玛丽娅照顾有加。她不仅拥有了自己的事业，还因为和奥斯瓦尔德一起而得到了安定的生活。尽管如此，狱中的赫尔曼始终让她牵挂，玛丽娅和奥斯瓦尔德之间达成了一项协议……©豆瓣', '汉娜·许古拉', '赖纳·维尔纳·法斯宾德', 8.3, 7346, 'tt0079095', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1524929404.jpg', 0.4, 1, 15.5, 51.2, 32, '0.145519,0.099317,-0.887354,0.545392,0.027455,-0.630217,0.843483,0.145995,-0.271737,-0.033591,0.129348,0.877920,-0.168576,0.235088,0.319720,0.066078,-0.672419,-0.706247,-0.000616,-0.134571,-0.257752,-0.790676,-0.169625,-0.278529,-0.077123,-0.376197,0.606434,0.029633,0.086854,0.543359,0.369219,0.394362,0.298175,0.591452,0.054851,0.165589,0.299919,-0.330794,-0.293342,0.075340,0.292993,-0.036983,-0.050862,0.444169,0.141856,0.287839,0.407299,-0.620811,0.337416,-0.047771,0.109395,-0.286900,0.277656,0.159020,0.106679,-0.154903,-0.205916,0.334435,-0.458610,-0.064424,0.279828,0.074544,-0.501110,0.072810,0.046950,0.219494,-0.660228,0.479101,-0.267409,-0.071499,0.055458,-0.106370,0.227626,0.538247,0.211585,0.426951,-0.209057,-0.141798,-0.577218,-0.041649,0.468077,-0.116852,-0.366598,0.187376,-0.261140,-0.432175,-0.163069,-0.060406,-0.359641,-0.326154,0.573802,-0.077127,-0.120588,0.626974,-0.461581,-0.314583,-0.637091,-0.227952,-0.117215,-0.330010,-0.122191,-0.406990,-0.167960,-0.291053,-0.434357,0.091094,-0.072928,-0.172994,0.504637,-0.640577,0.324617,0.422097,0.223964,-0.136254,0.600150,0.217275,0.362855,-0.012849,0.078092,0.633111,0.116421,0.189984,0.570903,0.052836,0.133072,0.230966,-0.114296,0.548106', '1300960', '1297769', '25723780', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298667', '危险人物', '剧情', '黑道分子波特（Mel Gibson 梅尔•吉布森 饰）和沃尔（Gregg Henry 饰）搭档，洗劫了某华人帮的14万现金，然而在事成之际，他却被沃尔和自己的妻子林恩（Deborah Kara Unger 饰）暗算。不仅钱被悉数卷走，还中弹险些丢掉性命。伤愈归来的波特只有一个念头，要回应该属于自己的7万美元。为此他上天入地，大开杀戒，凡是阻挠他的人全被干掉。这笔在很多大人物眼里微不足道的小钱，却因此掀起了一场震动黑道的血雨腥风……本片荣获1999年法国干邑影展观众奖。©豆瓣', '梅尔·吉布森', '布莱恩·海尔格兰德', 7.2, 5880, 'tt0120784', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1931501559.jpg', 1, 4.4, 40.4, 42.3, 11.9, '-0.015339,0.123567,-0.568976,0.267160,-0.063914,-0.344946,0.552274,0.052917,-0.401053,-0.147289,0.157277,0.892573,-0.233985,-0.166011,0.291602,0.004196,-0.010118,-0.707141,0.071740,-0.207229,-0.141316,-0.048559,-0.426163,-0.180599,-0.273506,-0.156592,0.418060,0.220895,-0.141999,0.510871,0.461734,0.431014,0.143881,0.319621,-0.089684,0.244498,-0.061302,-0.111281,-0.211264,0.173722,-0.146645,-0.417202,-0.156473,0.175513,0.098232,0.461602,0.432720,-0.056690,0.191900,0.011372,0.158210,-0.548127,-0.105850,0.118987,0.034212,-0.152621,0.184842,0.172849,-0.306147,0.310131,0.393011,-0.118412,-0.673771,-0.103007,0.007423,0.083826,-0.770639,0.668402,-0.190426,0.518352,-0.216346,0.184281,0.143411,0.140396,-0.123428,0.175846,-0.186660,0.059125,-0.869352,0.250210,0.583553,-0.314136,-0.032084,-0.097380,0.021481,-0.301836,-0.101067,-0.285936,-0.202919,0.111899,0.749164,-0.302855,0.135686,0.399531,-0.644045,-0.007970,-0.359223,-0.427100,-0.098855,-0.367869,-0.143176,-0.362365,-0.033246,-0.002687,-0.230696,0.174769,0.197479,-0.117094,0.567743,-0.331233,0.108242,0.496569,0.205996,-0.463594,0.472906,-0.021340,0.201912,-0.057302,-0.177895,0.079069,0.451246,0.186596,0.265848,-0.109918,0.014792,-0.291949,0.182786,0.427115', '1309069', '1300857', '6753166', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298672', '阿玛柯德', '剧情', '◎1975奧斯卡最佳外語片◎1974紐約影評人協會最佳導演及最佳影片三月，空氣中紛飛飄揚著輕軟絮草，教堂的鐘響迴盪在石板路上，小鎮的春天就此揭開序幕。時序回到三零年代亞德里亞海邊的小城，墨索里尼的極右理想仍是信奉的教條，建築工人老爸、家庭主婦老媽、遊手好閒的舅舅、頑皮的小弟，男孩在天主教、法西斯和義大利傳統家庭價值中，迎接他的青春與成長。教室裡捉弄老師的惡作劇、教堂裡擔心手淫的懺悔、鄉村海邊的熱鬧婚宴，費里尼從容隨意地摘選擷取小鎮生活的切片與軼事，密密織就一片記憶之網，在時代洪流與個人思憶之間相互輝映。費里尼曾說：「一個人所能做的紀錄，永遠是，也只能是對他自己的紀錄」。《阿瑪珂德》不但被推崇為其個人寫實語法的代表作，也被視為他最重要的自傳作品之一。影片一方面帶領觀眾走進費里尼的童年生活，看見他純真誠摯、幽默風趣的情感源頭。在時代景況的描繪上，也跳脫了純粹客觀、歷史觀察式的審視與檢驗，從最根本的生活細節著手，真實地重現了二次大戰前後義大利境內法西斯的樣貌。有趣的是，在《阿瑪珂德》中，我們也可清楚地看到費里尼對女性形象的思索與著迷，聖母、烈女、蕩婦的三位一體，母親與妓女形成了互為表裡的對比，而費里尼作品中一再出現的、體態豐腴、巨大的女體，不但是哺育孩童的母性泉源，也是青年性啟蒙的開端。', '普佩拉·玛奇奥', '费德里科·费里尼', 8.8, 14678, 'tt0071129', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p771183436.jpg', 0.3, 1, 10, 37.6, 51, '0.667988,-0.164489,-0.736480,0.780464,-0.267869,-0.359171,0.753185,0.259655,-0.510296,0.197562,0.466213,0.875711,-0.088522,0.241930,0.212107,0.122735,-0.305349,-0.827169,-0.206222,-0.006638,-0.277832,-0.428987,-0.152758,-0.110195,-0.204005,-0.397444,0.696735,0.312808,-0.036193,0.148423,0.212029,0.012473,0.337541,0.477190,-0.264056,0.102982,-0.059603,0.092716,-0.193807,-0.043399,-0.148596,-0.526910,-0.287118,0.210547,-0.191078,0.537497,0.526125,-0.371474,0.053144,0.052774,0.438612,-0.296444,0.023027,0.275002,0.117751,-0.192674,0.308894,0.198346,-0.040803,0.056183,0.092585,-0.223304,-0.798815,-0.146861,0.335502,0.093186,-0.739442,0.928926,-0.047170,-0.274613,0.147295,-0.300157,0.211767,0.074237,-0.044807,0.598950,-0.133702,-0.173052,-0.567157,0.329221,0.483531,-0.052153,-0.396416,0.445787,-0.653852,-0.541650,-0.176811,-0.327531,-0.545451,-0.113873,0.304477,-0.115284,-0.254112,0.295140,-0.807312,0.237290,-0.146043,-0.369707,-0.162578,-0.359611,-0.216888,-0.449698,-0.128587,-0.614548,-0.266086,0.009452,0.202461,-0.252262,0.881400,-0.819587,0.224937,0.514357,0.140792,-0.314171,0.840362,0.088515,0.078823,-0.104438,-0.316943,0.210094,-0.205205,0.287249,0.051205,0.655085,0.073432,-0.230474,-0.349431,0.853691', '30162520', '35158375', '4301274', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298692', '铁钩船长', '家庭', '时光飞逝，当年的小飞侠彼得·潘（Robin Williams 罗宾·威廉姆斯 饰）已长大成人，成为一名出色能干的律师。他与儿时的女伴温蒂（玛吉·史密斯 Maggie Smith 饰）的孙女结婚，并育有两个可爱的孩子。一家人在现实世界中幸福温馨，其乐融融。此时的彼得已忘记了自己小飞侠的身份，以及曾在梦幻岛上那惊险和快乐的时光。在带着妻儿探望祖母的路上，邪恶的铁钩船长（Dustin Hoffman 达斯汀•霍夫曼 饰）竟然再次出现，并虏去了他们的孩子。焦急的彼得手足无措，为了拯救孩子，他必须尽快找回小飞侠的身份，回到梦幻岛与宿敌决一雌雄……©豆瓣', '达斯汀·霍夫曼', '史蒂文·斯皮尔伯格', 6.8, 5042, 'tt0102057', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p732906821.jpg', 1.2, 7.9, 49.8, 29.8, 11.3, '0.023237,0.156670,-0.625681,0.421299,-0.320455,-0.562975,0.922969,0.042605,-0.478026,-0.278354,0.162626,0.806123,0.098656,0.684571,0.457077,0.163145,-0.325508,-0.655614,0.065937,-0.111082,-0.137486,-0.477158,-0.258131,-0.241797,0.045930,-0.364230,0.467734,-0.084212,0.275707,0.635657,0.327594,0.091423,-0.451264,0.260574,-0.433062,0.282343,0.136560,0.200617,-0.652141,-0.108940,0.070952,-0.054484,-0.145591,-0.021064,-0.052450,0.144335,0.684797,-0.281315,-0.103445,0.053438,0.252309,-0.161207,0.073197,0.193667,0.018430,-0.210695,0.049686,0.008634,-0.155895,-0.102865,0.003309,-0.278043,-0.821189,0.264863,0.087048,0.083623,-0.683769,0.538631,-0.089689,0.027829,0.463833,-0.338810,0.232075,0.387033,-0.088742,0.546173,-0.279550,0.308798,-0.389614,0.310045,0.660524,-0.000848,-0.012929,0.199282,-0.271527,-0.229301,0.011206,-0.263235,-0.800875,0.147037,0.597331,-0.029977,-0.090536,0.426349,-0.403049,-0.043090,-0.293344,0.060121,-0.025547,-0.411699,-0.035222,-0.424648,0.000102,-0.511106,-0.299435,0.000602,-0.052073,-0.258001,0.742734,-0.697909,0.372628,0.374179,0.122257,-0.315424,0.722766,0.212708,0.325716,-0.542077,-0.101897,0.440950,0.010319,0.040758,0.195655,0.375337,-0.116330,0.247320,-0.564328,0.639174', '4847665', '26884422', '26021055', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298694', '恐龙', '动画', '小禽龙阿拉达生活在白垩纪晚期，他自小就生活在一个桃花园般的小岛上。由一群狐猴抚养长大大的阿拉达从来就没有见过自己的同类，与他的狐猴朋友一直无忧无虑的生活在一起。一场不期而至的流星雨将阿拉达所在的小岛击毁了，阿拉达和他的狐猴朋友一起逃难来到了大陆。这时，因为大气变热，水源供给越来越紧张，阿拉达他们遇上了一群正在迁徙寻找新的栖身之地的恐龙并加入了他们。于是，阿拉达和同伴们一起开始了这次异常艰难的迁徙之旅。©豆瓣', '阿尔法·伍达德', '埃里克·莱顿', 7.6, 19686, 'tt0130623', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1006533162.jpg', 0.4, 2.6, 32.4, 44.3, 20.3, '0.337098,-0.377613,-0.681520,0.560738,-0.188076,-0.223595,0.834443,0.068077,-0.421974,0.054710,-0.084536,1.074210,-0.181048,0.392420,0.169221,-0.024837,-0.327524,-0.626062,-0.244566,0.002250,-0.238339,-0.188488,-0.194362,-0.167659,-0.107071,-0.278578,0.627967,-0.119227,0.079142,0.882563,0.066254,-0.010140,-0.413465,0.622343,-0.632934,-0.010142,0.031761,0.350202,-0.083388,0.177804,-0.354025,0.016377,-0.061033,0.083321,0.214509,0.079553,0.728186,-0.375302,-0.051123,-0.341104,0.042492,-0.138980,0.149179,-0.027957,0.679368,-0.240099,0.217113,0.114016,-0.090460,0.030870,-0.075112,-0.242800,-0.543345,0.138492,-0.017664,0.148641,-0.815181,0.589898,0.487823,-0.381776,0.096501,-0.409518,0.364395,0.894752,0.075604,0.356538,-0.221112,-0.023765,-0.310592,0.187014,1.053256,-0.065045,-0.180827,0.308370,-0.114230,-0.440797,-0.120238,0.090078,-0.503690,-0.312493,0.209974,0.060684,-0.535620,0.274270,-1.051386,0.410786,-0.100408,-0.534620,0.156943,-0.308420,-0.114329,-0.720151,0.065185,-0.473254,-0.160496,0.268795,-0.087710,-0.182407,0.684023,-0.783019,0.333866,0.575567,0.377411,-0.346226,0.521546,0.019608,0.124483,-0.103401,0.123906,0.332767,0.018706,0.612095,0.344650,0.431589,-0.115534,0.124707,-0.497370,0.600429', '11541282', '27042738', '1303333', '35256235');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298695', '夺命感应', '剧情', '警官约翰·荷伯斯（丹泽尔·华盛顿 Denzel Washington 饰）新近逮捕了一名杀人犯里斯，此人除了在电刑前说了几句奇怪的语言跟留下了一则暗语，并无特别之处。然而荷伯斯很快发现里斯的暗语指向一名三十年前自杀的警察罗伯·米拉诺。与此同时，几起连锁杀人案接连发生，凶手的手段如出一辙，更令人惊异的是每次的受害者即是上一桩凶案的嫌凶。荷伯斯拜访了罗伯之女格瑞坦，对方劝诫荷伯斯放弃调查。里斯的留言终被破译，原来他用叙利亚的古语言向荷伯斯发出威胁，而荷伯斯的坚持有了进一步的收获，他发现罗伯与近期几宗凶案的死者可能皆出自名为“阿萨索”的恶灵之手，阿萨索可以随意依附人体作恶，荷伯斯的缉凶之路因此而困难重重。这场人与恶灵之战，究竟如何收场？©豆瓣', '丹泽尔·华盛顿', '格里高利·霍布里特', 7.2, 9552, 'tt0119099', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1646633267.jpg', 0.8, 4.6, 40.5, 42, 12, '0.312032,-0.340255,-0.583703,0.537330,0.149316,-0.125591,0.735396,-0.055606,-0.581072,-0.267043,0.168688,0.507032,-0.250861,-0.305654,0.302154,-0.237073,-0.136591,-0.676922,0.145064,-0.355013,-0.285963,-0.599589,-0.317074,-0.276035,-0.050550,-0.344632,0.079148,0.198728,-0.244572,0.283646,0.319303,0.565223,-0.194538,0.279327,0.177885,-0.091201,0.135421,-0.075358,-0.112574,0.233355,0.223977,-0.305626,-0.223065,0.103502,-0.269266,0.756792,0.372718,-0.416994,-0.329142,0.009346,0.352458,-0.326276,0.054330,0.190212,0.275283,-0.072341,-0.008021,0.419277,-0.151326,-0.165241,0.300588,0.189409,-0.771503,-0.047350,-0.005965,0.396650,-0.288077,0.276115,-0.353034,-0.022471,-0.270387,-0.293320,0.356462,0.502836,0.343163,-0.003479,0.028000,-0.329778,-0.553278,-0.036235,0.546307,0.107096,-0.369427,0.087997,0.000895,-0.556903,-0.139543,-0.179447,-0.134943,0.226817,0.354390,0.138325,-0.120958,0.257922,-0.503037,-0.318721,-0.434513,-0.009612,-0.320587,-0.190036,0.014792,-0.687296,0.044885,-0.185342,-0.148614,-0.166226,0.230194,-0.243131,0.348526,-0.716314,0.161153,0.376229,0.273427,-0.186817,0.319610,0.031409,0.017870,-0.094838,-0.263818,0.079410,0.568883,0.366544,0.211485,0.266667,0.380666,-0.326469,-0.202173,0.180304', '1307442', '4132395', '1947080', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298717', '再造战士', '剧情', '越战后，美国政府进行了一项绝密的科学计划。科学家们将越战中牺牲的士兵的尸体冰冻起来，植入电脑芯片，输入战争程序，讲他们改造成为新一代的战争机器人――“宇宙战士”，这些机器人没有情感和以前的记忆，只有冰冷的杀戮武器。士兵卢克（尚格•云顿 Jean-Claude Van Damme 饰）和班长安德鲁（杜夫•朗格 Dolph Lundgren 饰）就是其中两员，他们被派往参加一场新的战争。战争中，两人的芯片突然出错，令两人都恢复了以前的记忆。卢克记起越战当年正是安德鲁突然性情大变将属下和俘虏都杀光，误闯美军基地的女记者罗伯斯（艾丽•沃克 Ally Walker 饰）意外获悉了美军这一秘密。本来罗伯斯难逃一死，关键时刻卢克救走了她。于是，美军派出所有的宇宙战士开始追杀二人。©豆瓣', '杜夫·龙格尔', '罗兰·艾默里奇', 6.7, 4438, 'tt0105698', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1530925992.jpg', 1.2, 7.3, 56.2, 27.6, 7.8, '0.312532,-0.067622,-0.556810,0.438557,0.087126,-0.244832,0.691100,-0.275081,-0.409458,-0.234136,0.395790,0.572690,-0.014070,-0.155271,0.210029,-0.224788,-0.501898,-0.741889,-0.395861,-0.078050,-0.442852,-0.423542,-0.180000,-0.319860,0.103090,-0.626935,0.760077,0.118143,-0.390941,0.275742,0.055915,0.202213,-0.074565,0.415641,0.089390,-0.007181,0.249092,-0.300175,-0.223390,-0.086265,-0.225323,-0.101310,-0.085733,0.057908,-0.045438,0.310449,0.579822,-0.587191,0.169011,-0.421342,0.262645,-0.237851,0.024083,-0.166076,0.500704,0.226627,0.079537,0.059598,0.267182,-0.022638,0.088415,-0.018888,-0.692627,-0.087121,-0.154904,0.164837,-0.476357,0.268429,-0.203727,0.414324,0.146174,-0.082442,0.168399,0.359179,0.334812,0.185543,-0.228200,-0.225543,-0.461412,0.251892,0.554458,-0.361579,-0.336987,0.122291,-0.128503,-0.699545,-0.288154,-0.282025,-0.276814,0.027965,0.611862,0.088777,-0.005743,0.615005,-0.707153,0.114277,-0.199658,-0.456218,-0.131358,-0.204175,0.031101,-0.721590,-0.240731,-0.022025,-0.289511,0.007841,0.056631,-0.029475,0.831838,-0.569107,0.167230,0.431877,0.242514,-0.559509,0.232242,-0.019653,0.249777,-0.194865,0.093552,0.134291,0.117333,0.525093,0.304803,0.474507,-0.025041,-0.180194,-0.193952,0.397396', '25863940', '25774050', '10467125', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298718', '不知不觉爱上你', '喜剧', '山姆（马修•布罗德里克 饰）深爱的未婚妻琳达（凯莉•普雷斯顿 饰），琳达却移情别恋毅然与他分手了。山姆没想到自己的无限量牺牲换不来女友的珍惜。山姆不愿就此放手，于是他在琳达与新男友安东尼的新居附近租下了房子，企图日夜监视琳达的生活，继续了解琳达是生活并希望琳达会有回心转意的一天。山姆认识了邻居玛姬（梅格•瑞安 饰），原来玛姬也是在监视自己的前男友，她的前男友竟然是琳达的新欢安东尼。两人竟然会一起通过望远镜看到了自己的前女友与前男友的缠绵生活，愤怒不已的玛姬竟然想到要联合山姆一起报复安东尼……©豆瓣', '梅格·瑞恩', '格里芬·邓恩', 7.1, 6455, 'tt0118556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p931876666.jpg', 0.7, 5.7, 43.5, 38.2, 12, '0.176087,-0.192188,-0.794679,0.441942,-0.202688,-0.526865,0.527852,0.058597,-0.364833,-0.387420,0.206009,0.776533,-0.243826,0.421955,0.039339,0.241902,-0.435983,-0.769851,0.027827,-0.134196,-0.317499,-0.493476,-0.083950,-0.384861,0.074328,-0.116613,0.403443,-0.180696,0.055459,0.346834,0.448742,0.234798,-0.019831,0.574268,-0.136657,0.100074,0.294147,-0.060105,-0.466038,0.136100,0.196812,0.071820,0.063718,0.287047,0.075372,0.246090,0.622632,-0.028301,-0.086263,0.106049,0.078640,-0.057560,0.144623,0.094647,0.189133,-0.392723,0.228183,0.195618,-0.407685,-0.330778,0.277097,0.084577,-0.510995,0.220361,-0.124779,0.075224,-0.498847,0.315844,-0.272942,0.018232,0.260934,-0.296621,0.124585,0.492893,0.189527,0.233575,-0.178745,-0.073567,-0.422967,-0.034773,0.632450,0.125641,0.195551,0.349914,-0.282597,-0.080959,-0.117949,0.160652,-0.796358,-0.096387,0.183101,-0.035407,-0.106378,0.181947,-0.633511,-0.246181,-0.633232,0.217684,0.328765,-0.509906,0.021039,-0.520767,-0.057166,-0.400581,-0.342723,0.060989,-0.154897,-0.484359,0.436324,-0.925974,0.173878,0.622009,0.702215,-0.613047,0.562999,0.248350,-0.178439,-0.220693,0.025866,0.486009,-0.082517,-0.118864,0.209465,0.165962,0.388589,-0.004360,-0.294126,0.539772', '1301022', '1299556', '30345227', '1857175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298728', '贴身情人', '喜剧', '百万富翁乔治·维德(休·格兰特 Hugh Grant 饰)的衣食住行都倚赖公司的律师露西·凯尔森(桑德拉·布洛克 Sandra Bullock 饰)。露西条理分明，但也有点神经质。而露西喜欢上了聪明，迷人的乔治。她一直在帮助乔治打点从服装到离婚案的所有大小事件，但乔治并没有什么表示。五年过去了，露西终要停止这一切。 乔治一开始不想让露西走，但最终还是答应了她，但他有个要求，让露西找个人来代替她。经过寻找，露西雇佣了一个年轻漂亮又野心勃勃的律师琼（艾丽西亚·维特 Alicia Witt 饰）。琼对她富有的新老板很感兴趣，而乔治也仿佛受到她的吸引。露西终于摆脱了乔治，准备和自己忠心耿耿的男朋友一起去海上旅行。失去露丝后，乔治也像失去了一个近身知己，接替的人如何主动献身也填补不了他精神上的失落。原来，一切彼此最需要的就在身边，只是一直未曾为意，漏了眼的缘份，知道会否太迟？', '桑德拉·布洛克', '马克·劳伦斯', 6.9, 20351, 'tt0313737', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2169345942.jpg', 0.7, 6, 51.4, 32.6, 9.3, '0.425412,0.008080,-0.699813,0.478535,-0.379130,-0.724400,0.864084,-0.026415,-0.313396,-0.255823,-0.169274,0.815840,-0.116734,0.150216,0.233806,0.546976,-0.497168,-0.631428,0.169377,-0.205768,-0.263197,-0.647031,-0.084070,-0.239757,-0.195477,-0.105644,0.404831,-0.203378,0.133857,0.378765,0.382482,0.090517,0.396682,0.621439,0.122708,0.083810,0.064295,-0.132307,-0.042855,0.217258,0.347320,-0.191139,-0.269065,0.565287,0.029600,0.454798,0.190085,-0.285258,-0.100875,0.159197,0.272401,-0.354371,0.233669,0.234493,0.137451,-0.087186,0.041248,-0.002849,-0.341277,-0.078236,0.166018,0.119906,-0.829233,0.086439,-0.081330,0.103878,-0.703376,0.311648,-0.159272,-0.065777,0.000648,-0.499267,0.103145,0.466377,0.168443,0.029611,-0.264924,-0.014472,-0.510679,-0.102702,0.688597,0.214955,-0.338313,0.387345,-0.298420,-0.415065,-0.044407,-0.158715,-0.569029,-0.067315,0.198952,0.058117,-0.008746,-0.060103,-0.483888,0.013102,-0.412475,-0.294529,-0.230865,-0.475998,0.238136,-0.421068,-0.312848,-0.637797,-0.522370,-0.095531,0.049200,-0.294655,0.658062,-0.913306,0.193599,0.760470,0.260972,-0.488457,0.545938,0.080766,-0.033721,-0.140005,-0.085910,0.183889,-0.017343,0.228595,0.350179,0.423601,0.393582,-0.157162,-0.256623,0.463902', '1783461', '1299362', '1308755', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298733', '日落大道', '剧情', '过气演员诺玛（葛洛丽亚·斯旺森 Gloria Swanson 饰）已经将近50岁，曾经的风华绝代正在她居住的荒废豪宅里慢慢凋谢，身边只有好友马克思（埃里克·施特罗海姆Erich von Stroheim）伺奉。她没放弃重燃光辉的梦想，《莎乐美》的剧本正待编写，而逃避债务逃至此地的没落编剧乔（威廉·霍尔登 William Holden饰），正是这项事业的最佳候选。诺玛收留他住下，给他提供舒适的环境写作，并慢慢的倾心于他。但是，乔并不能接受这个青春已逝的妇人。他拒绝了她，并转过身和另一个美丽的女子谋划新的剧本，他们相爱，打得火热。诺玛得知了乔的“背叛”，她卑微地哀求他，却动摇不了他渐行渐远的心，诺玛终于举起枪对准正要离开的乔。©豆瓣', '威廉·霍尔登', '比利·怀尔德', 8.8, 55603, 'tt0043014', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1119483806.jpg', 0.2, 0.6, 8.3, 42, 48.9, '0.039966,0.125456,-0.659089,0.643541,-0.282244,-0.611450,0.862516,0.053690,-0.098157,-0.403671,-0.055364,0.586514,0.172257,0.611561,0.316666,0.204640,-0.389650,-0.793217,-0.039572,-0.039448,-0.196381,-0.503159,-0.206555,-0.239439,-0.217493,0.078981,0.680347,0.147243,-0.163444,0.290769,0.298131,0.065552,0.154874,0.462199,-0.161542,0.156609,-0.069892,-0.097049,-0.244281,0.115222,0.178923,-0.333857,-0.236527,0.228173,0.181556,0.448164,0.360911,-0.295539,0.129164,0.064267,0.357348,-0.280175,0.135332,0.056692,-0.088428,-0.108741,-0.019857,-0.245518,-0.284943,-0.066113,-0.024914,-0.233430,-0.645636,0.158122,-0.077580,0.089936,-0.611608,0.414713,-0.282375,0.107249,-0.010672,-0.369738,-0.165661,0.212273,0.174778,0.283721,-0.258871,0.074305,-0.345842,0.286450,0.371539,0.214434,-0.372488,0.379561,-0.436822,-0.524312,-0.004177,-0.101801,-0.547527,-0.346407,0.358508,0.305843,0.111835,0.109545,-0.317545,-0.123696,-0.363476,-0.061528,0.117914,-0.336719,-0.250655,-0.407167,-0.254122,-0.314473,-0.302668,0.093776,-0.140851,-0.428772,0.563860,-0.534455,0.344845,0.336087,0.318277,-0.518937,0.624343,0.070938,0.192163,0.165614,-0.000528,0.980621,-0.168944,0.369923,0.204593,0.053322,-0.077228,0.070291,-0.465124,0.492853', '1296992', '1292277', '1436768', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298744', '十二猴子', '科幻', '公元2035年，人类被12只猴子军研制的一种病毒侵袭，大部分人类都在这场病毒灾难中死亡，只有少数人侥幸逃生，但也只能在阴暗的地下，苟且偷生。科学家们决定派人穿越时光回到1996年追查12只猴子军的来历。囚徒詹姆斯·科尔(布鲁斯·威利斯 Bruce Willis 饰)被 挑选为志愿者。阴差阳错，科尔回到了1990年，当他向当时的人们描述未来的那场大灾难时，被当作精神病捉了起来并被医生凯瑟琳·雪莉（玛德琳·斯通 Madeleine Stowe 饰）诊断为精神分裂症。科尔在病友杰弗里·戈因斯帮助下逃脱，回到了未来。因为没查清12只猴子军的来历，科尔再次被派回了1996年。科尔这次发现了12只猴子军的起源地在费城，他找到了医生凯瑟琳，二人一起展开了追查12只猴子军的冒险之旅!©豆瓣', '布鲁斯·威利斯', '特瑞·吉列姆', 8.2, 214722, 'tt0114746', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p627041570.jpg', 0.4, 1.6, 17.1, 49.8, 31, '0.245275,-0.114731,-0.405176,0.069221,-0.055675,-0.317647,0.533656,-0.246649,-0.772794,-0.431025,0.242666,0.449889,0.018648,0.098051,0.158378,0.029873,-0.506943,-0.485926,0.021696,-0.312629,-0.305101,-0.178003,-0.361695,-0.318966,0.102384,-0.478795,0.530166,0.068108,-0.281198,0.209305,-0.044684,0.514022,0.042742,0.508296,-0.012496,0.288439,0.199531,-0.293342,-0.118681,0.330235,0.041114,-0.466171,-0.326677,0.058077,0.053492,0.370142,0.832268,-0.758416,0.097935,-0.292739,-0.146934,-0.471420,-0.074683,0.258763,0.330208,0.060115,0.031483,0.287365,-0.033778,0.088102,-0.026946,-0.045349,-0.523787,0.177086,-0.160584,0.278594,-0.586040,0.348871,-0.350280,0.258594,-0.066391,-0.568384,0.216294,0.478104,0.184185,0.474978,-0.238628,-0.042444,-0.678626,0.339652,1.025623,0.009191,-0.336811,-0.050734,-0.053241,-0.617017,-0.078150,-0.125121,-0.266697,0.265073,0.816590,0.107694,-0.241829,0.490456,-0.803805,0.031262,-0.537236,-0.362854,-0.180956,-0.257126,-0.117793,-0.523948,-0.059141,0.223265,-0.124823,-0.022723,0.143036,-0.171871,0.540643,-0.623703,0.399769,0.539557,0.177027,-0.481076,0.463336,-0.101621,0.221957,-0.167661,0.128633,0.394402,0.221632,0.706427,0.477787,0.428186,-0.048672,-0.312599,-0.309635,0.188079', '26280899', '2032339', '24397586', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298753', '邮差', '剧情', '2013年的地球一片荒芜，经历过一次毁灭性的战争后，世界原以建立的文明荡然无存，人类颠沛流离的生活在这片焦土之上，在饥荒与暴力下生不如死。一个名叫霍尔内斯特的恐怖组织，以其对居民们的暴力镇压而迅速扩张，规模庞大。组织的统治者伯利恒上将（威尔·帕顿 Will Patton 饰）甚至妄想统治世界。一个无名无姓的流浪汉（凯文·科斯特纳 Kevin Costner 饰）被捕后，被强行加入了这个组织。终于，他抓住仅有的一次机会成功逃走。在一辆废弃的吉普车上，他发现了一具骷髅骨架。为了取暖，他穿上了骨架上的邮差服，并且他意外的发现了一包过期邮件。从此，他开始往返于各个城镇之间，为之送信，并谎称自己是邮递员。很快，他赢得了小镇人们的信任，并带领大家与极权统治者展开了顽强斗争。©豆瓣', '凯文·科斯特纳', '凯文·科斯特纳', 7.5, 6932, 'tt0119925', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p925479194.jpg', 1.3, 5.6, 30.4, 43.1, 19.6, '0.212288,0.344406,-0.713633,0.528316,-0.131105,-0.095771,0.760091,0.040770,-0.559831,-0.059022,0.212914,0.807429,0.005209,-0.088835,0.196042,-0.180275,-0.209194,-0.633555,-0.051817,-0.185087,-0.495505,-0.259009,-0.589253,-0.367100,-0.185249,-0.295667,0.716608,0.239619,-0.197214,0.403063,0.090619,0.137932,-0.007685,0.500234,-0.239391,-0.107266,0.087060,-0.240040,-0.229336,0.192460,-0.486416,-0.295690,0.094599,0.227472,-0.265181,0.287602,0.823304,-0.505846,-0.109805,-0.554280,0.334721,-0.200686,-0.067788,0.146897,0.301977,0.088876,0.096709,0.230369,-0.038859,-0.133962,0.103353,-0.206079,-0.723489,-0.216754,-0.227713,0.138240,-0.533572,0.666144,0.038573,-0.063358,-0.260424,-0.436946,0.139466,0.462158,0.296452,0.191451,-0.138025,-0.056453,-0.373925,0.043534,0.639184,-0.179605,-0.420173,0.276237,-0.130893,-0.472853,-0.115762,-0.236060,-0.411881,-0.199492,0.375025,-0.093000,-0.167794,0.292664,-1.131903,0.111690,-0.533087,-0.501375,0.029689,-0.074980,-0.101323,-0.368002,-0.210293,-0.132501,-0.291662,0.089711,-0.084521,-0.110919,0.574773,-0.719897,0.399542,0.493949,0.365810,-0.503965,0.427230,-0.098320,0.205138,-0.016666,0.018689,0.452960,0.216462,0.695905,0.159968,0.261413,-0.119055,-0.028253,-0.252036,0.522199', '26290398', '25774050', '7056398', '1309031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298754', '袅袅夕阳情', '剧情', '该片讲述了一个充满生命情趣的教师内田毅然辞去大学教书职务，一心在家从事写作之后发生的一连串生活趣事。内田深受学生们的爱戴，学生们每年都会为老师举办生日会。每年的生日会上，学生们都会问老师“准备好了吗？”，而内田的回答则永远是“还没”。内田对生死的豁达也深深地影响着自己的学生们，时刻提醒着学生们要有一个健康积极的心态。教授的猫丢了一直哭，学生们赶紧去看望他，为他到处找猫，还到学校等地方发传单，在报纸上登启事，希望能够帮助老师找回猫咪，重拾笑颜。浓厚的师生情贯穿全片。影片结尾，内田在生日宴后入睡，外面学生在畅饮交谈，他已近暮年的梦里是孩童时在稻草堆里捉迷藏的场景，一大堆孩子连连喊着藏好没，他连连回答“还没还没”。', '松村达雄', '黑泽明', 8.3, 7916, 'tt0107474', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2031639015.jpg', 0.6, 2, 15.7, 45.6, 36, '0.095515,-0.352010,-0.576526,0.368998,-0.147076,-0.211601,0.485735,0.041153,-0.454866,-0.371860,0.038977,0.552928,-0.317299,0.715395,0.106860,-0.156181,-0.399531,-0.721291,-0.259515,0.125398,-0.224836,-0.325588,0.191142,-0.057401,-0.553802,-0.263338,0.045159,-0.081146,-0.012470,0.461802,0.101019,0.050593,0.188151,0.400250,-0.277863,-0.031217,0.070678,0.252141,0.071481,0.103173,0.171090,-0.273403,-0.562991,-0.145255,0.421773,0.168805,0.698758,0.049083,-0.107852,0.139283,0.342581,-0.233275,0.081886,0.408395,0.311928,0.011498,0.301885,-0.024461,-0.040200,0.246307,-0.043072,-0.280041,-0.386129,-0.238724,-0.052046,0.277483,-0.573406,0.541440,0.251467,0.076621,0.456623,-0.398992,0.190683,0.091936,-0.156227,0.498797,0.051073,0.051728,-0.276506,0.563842,0.649979,-0.158854,-0.081031,0.178195,-0.387326,-0.220526,0.173285,-0.028223,-0.763268,0.035131,-0.082138,0.030577,-0.350545,-0.067128,-0.260613,0.008961,0.130168,-0.455869,0.163234,-0.320705,-0.135151,-0.800288,0.236539,-0.152860,-0.295961,0.150114,0.035107,-0.280048,1.133040,-0.898078,0.347239,0.658189,0.188439,-0.419990,0.844119,0.296261,0.010100,0.092785,0.037031,-0.209330,-0.019854,0.434444,0.157856,0.364028,-0.046057,-0.193946,-0.281822,0.267369', '25922902', '3811356', '1308609', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298755', '刘三姐', '剧情', '根据广西壮族民间传说改编而成的戏曲电影。砍柴女刘三姐（黄婉秋）以唱帮穷苦人解气的山歌名闻四乡，却也因此被视她为肉中刺的财主陷害，幸运捡得一条命后，她一路歌声沿江而下。老渔夫（张巨克）和儿子阿牛（刘世龙）通过歌声将她辨出，将她接入家中。远近乡民听闻，都赶来与刘三姐赛歌，以为她已人头落地的哥哥刘二（梁音）也因此机与她重逢。因为歌词中多处直揭财主对穷苦人的盘剥，乡民叫好同时亦令当地财主莫怀仁（夏宗学）极为恐慌。为防乡民暴动，莫怀仁想以淫威令刘三姐噤声，只换回自己的难堪，刘三姐言称若赛歌胜过她，她自不会开口再唱。刘二怕妹妹重蹈覆辙，想带她远走他处，但刘三姐誓要好好惩治莫怀仁。莫怀仁找来一帮酸臭文人信心满满与刘三姐赛歌，不想个个被她骂得狗血喷头。为让刘三姐屈服，莫怀仁暗中将她绑至府中，施以锦衣美食，只换来刘三姐的几声冷笑。早已与刘三姐暗中生情的阿牛、刘二及众乡民，则颇为担忧她的安危，正想办法将她营救。', '黄婉秋', '苏里', 8.4, 15452, 'tt0054034', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2502176435.jpg', 0.5, 1.2, 14.7, 43.5, 40.2, '0.130513,-0.134670,-0.417447,0.502130,-0.013473,-0.357141,0.563982,-0.038383,-0.561783,0.074876,0.116818,0.534630,-0.116465,0.137307,-0.022831,-0.042908,-0.240669,-0.462604,-0.072459,0.084812,0.282119,-0.176833,0.096298,-0.091121,-0.372892,-0.057073,0.208353,0.122887,-0.266943,0.463667,0.124164,0.278009,-0.132978,0.495223,-0.084768,0.238327,-0.268377,-0.185176,-0.012158,-0.193222,0.135115,-0.394565,-0.373943,0.272234,-0.123637,0.427818,0.699142,-0.363688,0.084244,-0.057104,0.197949,-0.250012,0.460944,0.227506,-0.088857,-0.019005,0.298141,0.236200,-0.344346,0.105352,-0.094319,0.291731,-0.273930,0.217722,0.340658,-0.380144,-0.530012,0.317232,-0.038260,0.025892,-0.028673,-0.226146,0.356684,-0.156433,0.294451,0.198593,-0.246450,-0.079683,-0.489140,0.339055,0.682220,0.209904,0.354098,-0.084459,-0.067795,-0.344656,0.263804,-0.191530,-0.270091,-0.130965,0.293483,-0.064445,0.016254,0.032406,-0.265883,-0.141554,-0.348741,0.093321,-0.160295,-0.287252,-0.186958,-0.162423,0.070614,-0.026825,0.016060,-0.092866,0.444042,-0.226343,0.598972,-0.373258,-0.118576,0.384487,0.124061,-0.381563,0.309262,0.053598,0.080184,0.041212,-0.327433,-0.004501,0.145071,0.265613,0.484245,0.061708,-0.256709,-0.200808,0.065874,0.344402', '