INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298759', '狗镇', '剧情', '封闭守旧的美国小镇闯进了一个神秘女子格蕾斯（妮可•基德曼 Nicole Kidman  饰）。她美丽善良，正在逃避歹徒追杀。镇中的作家汤姆力劝村民留下这个女子，让她暂时在镇里避过难关。然而条件就是格蕾丝要干各种农活来偿还。人们同意了，不久后却发现格蕾丝是一个通缉中的逃犯。大家要把格蕾丝赶走，最后答应，如果她更卖力的干活，才可以在这里逗留。格蕾丝日以继夜的劳作，终难逃过不幸的事情发生。一个镇民在警察搜捕后，强暴了格蕾丝。龌龊的事情拉开了序幕：人们开始随意的污辱她，甚至连汤姆，也揭开了善良的面具，格蕾斯沦为镇上的一条狗，干活，受罪，善良的心也有了渐渐的改变。镇上的人怎么也想不到，这个女子的神秘身世，让此刻的污辱成为了他日的灭顶之灾。©豆瓣', '妮可·基德曼', '拉斯·冯·提尔', 8.4, 142183, 'tt0276919', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457169802.jpg', 1, 2.3, 13.6, 39.7, 43.4, '0.233758,-0.029279,-0.590058,0.315482,-0.406332,-0.242437,0.873183,0.011886,-0.384089,-0.015256,0.239147,0.628286,0.000358,0.264484,0.261173,0.198015,-0.310737,-0.555569,0.070837,-0.186950,-0.328843,-0.121350,-0.138311,-0.517693,-0.009803,-0.170767,0.341226,0.351189,-0.161201,0.254879,0.342916,-0.036963,0.014148,0.534645,-0.173365,0.067808,0.055006,-0.050489,0.086313,0.133895,-0.134831,-0.404745,-0.121369,0.226797,-0.099742,0.519778,0.520813,-0.239699,-0.382594,-0.031367,0.303915,-0.447684,-0.106535,0.273075,0.251749,-0.323342,0.063840,0.110338,-0.343074,-0.110753,0.088414,0.070642,-0.632543,0.024157,0.108066,0.160110,-0.753494,0.363432,0.080054,0.007520,-0.034327,-0.331063,0.166564,0.199785,0.102411,0.158661,0.078191,0.006624,-0.453700,0.353279,0.763908,-0.146315,-0.237843,0.223019,-0.203365,-0.252897,0.214946,-0.314383,-0.538092,0.010025,0.260147,-0.188758,-0.413950,0.304945,-0.516655,-0.168287,-0.478715,-0.099953,-0.145695,-0.348401,-0.196140,-0.296048,0.000579,-0.165382,-0.376787,0.208466,-0.048018,-0.187253,0.741734,-0.668725,0.184215,0.809834,0.355818,-0.622508,0.578201,0.061148,0.240357,0.070718,-0.096723,0.122004,0.165687,0.482042,0.199780,0.377908,0.075276,-0.218584,-0.142464,0.342093', '1309116', '1292217', '26718282', '10486471');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298761', '新仙鹤神针', '动作', '六扇门主事曹雄（张铁林饰）召开武林大会欲统领江湖。各大门派赶赴大会，点苍派师徒一阳子（刘松仁饰）和徒弟马君武（梁朝伟饰）亦于其中。师徒两人遇上天龙帮突袭，幸得白云飞（梅艳芳饰）相救。其后白更答应往桃花潭捕捉千年灵龟，以解众掌门之毒。几经辛苦，3人终捕得灵龟，岂料又被蓝小蝶（关之琳饰）利用琴音夺走，扬言要白亲自去取回。此时，由于曹雄误传归元秘籍为白云飞所有，于是追杀白云飞的武林行动也展开了。而曹雄学得绝世武功，无人能敌......©豆瓣', '梁朝伟', '陈木胜', 7.1, 30858, 'tt0108607', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2289717171.jpg', 0.7, 4.4, 44.2, 38.5, 12.3, '-0.198180,0.091102,-0.294824,0.466264,0.349679,-0.351156,0.020860,0.046673,-0.351801,-0.225885,0.046789,0.391608,-0.073894,-0.222610,0.230732,-0.234253,0.334813,-0.413639,-0.123178,-0.189087,0.090169,0.073549,-0.150432,0.165282,-0.097700,-0.142661,0.456748,0.142826,-0.157287,0.749743,0.440749,0.229982,-0.420834,0.080923,-0.031531,-0.100021,-0.282395,0.168057,-0.463407,0.286242,-0.111049,-0.258449,-0.189957,-0.079550,-0.226979,0.206472,0.234471,-0.254907,-0.004925,-0.322971,0.034851,-0.277729,0.026818,-0.078831,0.495635,0.256265,0.281328,0.372257,-0.303469,0.266532,0.132297,-0.097434,-0.173218,0.237139,0.484781,-0.011297,-0.235468,0.170232,-0.316123,0.184588,-0.282925,-0.391429,-0.195373,0.338026,0.205913,-0.183098,0.029222,-0.248366,-0.349321,0.177967,0.303945,-0.194269,0.725526,-0.164848,0.669551,-0.276164,0.271486,-0.178719,0.386278,0.121725,0.678399,-0.034861,0.324141,0.103412,-0.363767,-0.247876,-0.273582,0.211614,-0.086779,-0.086857,0.162663,-0.806582,0.199814,0.134572,-0.163813,-0.183680,0.494531,0.008641,0.480370,-0.595475,0.160451,-0.046797,-0.089498,-0.573211,0.284575,-0.047873,0.156853,-0.040078,-0.209889,-0.007043,0.143288,0.687287,0.225612,0.289863,-0.017382,-0.219879,-0.207069,-0.385979', '26365262', '2075345', '1473074', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298817', '淘金记', '喜剧', '流浪汉查理（查理·卓别林 Charlie Chaplin 饰）随队伍来到阿拉斯加淘金。他在一间小木屋里碰见了通缉犯拉逊，接着淘金人吉姆也闯进来，并抢走了拉逊的枪。拉逊出去找食物时发现了吉姆正在开发的金矿，于是他没回木屋。小木屋里，饥肠辘辘的查理煮了皮鞋充饥，饿的神智恍惚的吉姆却把查理想象成火鸡追杀。突然，一头熊撞进来，两人一起把熊打死，饱餐之后分道扬镳。吉姆发现了拉逊占了自己的金矿坑，拉逊将他打昏，不料却在逃跑时掉下深谷。查理在小镇邂逅舞女乔治亚（乔治亚·黑尔 Georgia Hale 饰），帮她摆脱暴发户的骚扰。第二次又巧遇她时，查理邀她除夕共餐，但是乔治亚爽约了，失落的查理只能在幻梦中为她表演舞蹈。被打成失忆的吉姆在镇上重遇查理，他请查理帮他一起找金矿。两人回到小木屋，却被大风雪吹落下了万丈深渊。醒来时他们惊喜地发现金矿正在身边。查理与吉姆淘金成功，在回乡的船上遇见困顿的乔治亚。在新闻记者的镜头前，查理与乔治亚亲密拥抱。', '查理·卓别林', '查理·卓别林', 9.2, 52444, 'tt0015864', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1581774481.jpg', 0.1, 0.2, 4.2, 30.1, 65.4, '0.276262,0.056282,-0.678529,-0.003769,-0.245372,-0.663802,0.954343,0.310786,-0.356274,0.076358,0.179064,0.730920,-0.222141,0.277920,0.374035,0.211109,-0.615839,-0.464009,0.229941,-0.088571,-0.348680,-0.235722,-0.173330,-0.250074,0.103292,-0.095155,0.175580,-0.139171,-0.217059,0.568843,0.059318,0.019776,-0.123002,0.499217,-0.357161,0.314090,0.233823,-0.096099,-0.225367,0.272602,-0.213235,-0.198469,-0.333427,0.082911,0.155366,0.304203,0.643526,-0.016607,-0.012161,0.068390,0.082221,-0.103142,0.063740,0.012315,0.304455,0.001719,0.047763,-0.279773,-0.161253,0.103575,0.161842,0.135606,-0.157816,0.554009,-0.225746,0.193276,-0.609590,0.449845,0.056915,0.153754,0.134309,-0.356411,0.187480,0.144450,0.083980,0.359919,-0.026708,0.113384,-0.776353,-0.077460,0.423431,-0.127463,0.100028,0.186757,0.172249,-0.214252,0.366339,0.231566,-0.103681,-0.321213,0.624837,-0.098572,-0.499633,0.013169,-0.618899,-0.178823,-0.401813,-0.188171,-0.212542,-0.134957,-0.273798,-0.761797,0.035392,-0.105887,-0.322375,-0.012007,0.016450,0.039801,0.012728,-0.452591,0.365993,0.766950,0.313033,0.136494,0.643800,-0.181659,0.087874,0.038685,0.175113,0.244349,0.281278,0.407128,0.599902,0.468538,-0.123402,-0.068386,-0.682550,0.427139', '1301686', '1301345', '1394176', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298869', '神偷次世代', '动作', 'Mac（黎明）、Bird（陈小春）、Sam（李灿森）和Michelle（雪儿）是国际神偷组织界的精英，四人一向合作无间配合默契，完成过许多艰巨任务。此次四人要到马来西亚侦察一名科学家，希望偷取其刚研制成功的治癌药。可是在悄悄潜入药厂行动的过程中四人却遭遇埋伏，方知此次任务是骗局一场。在四人试图逃脱的过程中，Mac失手，但因神秘性感的女子June（舒淇）得以解困。从June身上，Mac忆起前女友被旧拍档出卖而死去的往事，并拥有了一个破解迷局的重要线索。©豆瓣', '黎明', '叶伟信', 5.8, 8131, 'tt0272822', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868791572.jpg', 3.8, 20.8, 59.2, 12.6, 3.6, '0.111627,0.196946,-0.428369,0.371615,-0.245077,0.049798,0.526327,-0.306178,-0.660766,-0.357783,0.417192,0.530413,0.111450,-0.157849,0.285011,-0.146641,0.015051,-0.615892,0.086221,-0.202849,-0.362698,-0.179692,-0.391233,-0.127701,-0.012087,-0.550113,0.910634,0.473461,-0.383231,0.362790,0.169553,0.344966,-0.703832,0.398024,0.012777,-0.250726,0.319650,0.034154,-0.511851,0.435739,-0.178047,-0.394806,-0.356783,0.175364,-0.107745,0.367397,0.638720,-0.047868,-0.364191,0.060820,0.083709,-0.500718,-0.171683,-0.139688,0.438261,0.106026,0.054043,0.372937,0.007062,-0.054000,-0.103416,-0.110608,-1.044569,-0.154050,0.535687,0.106296,-0.346986,0.177239,-0.393258,0.285404,-0.188097,-0.458164,0.123623,0.363217,0.442386,0.230383,-0.094750,0.168001,-0.569054,0.281629,0.680466,-0.296624,-0.061053,0.326161,0.226658,-0.602730,-0.005846,-0.250075,-0.016922,0.394932,0.354018,0.029452,-0.168731,0.264457,-0.588035,0.072174,-0.430983,-0.131307,-0.046751,-0.122754,-0.092851,-0.667311,-0.124139,-0.037813,-0.386604,0.184028,0.040955,-0.455293,0.589720,-0.842447,0.261105,0.642800,-0.209853,-0.427740,0.327927,0.171587,0.475334,-0.484164,-0.088992,0.069638,0.108558,0.185603,-0.005527,0.245891,-0.284656,-0.274246,-0.629496,-0.098443', '1793491', '2369613', '27073234', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298870', '浮云', '剧情', '二战期间，被派往日本侵占下越南的幸田幸子（高峰秀子饰），在那里认识了有妇之夫富冈兼吾（森雅之饰），继而相恋。战败回国后，幸子在衰败的街道里找到了富冈的家，发现他依然和妻子（中北千枝子饰）生活在一起，并没有离婚。出来后的他们偷偷相会并继续暗中往来，但富冈的态度依然暧昧不清，借口多多。离开富冈后，走投无路的幸子跟了个洋人生活，之后兼吾找回幸子，幸子再次与他一起，但在伊香保温泉，富冈又看上旅店老板的妻子（冈田茉莉子饰），而幸子发现自己怀孕了。之后，富冈发生意外，他又回来找到幸子，两个人打算开始新的生活……©豆瓣', '高峰秀子', '成濑巳喜男', 8.6, 10024, 'tt0048757', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2319858048.jpg', 0.2, 0.8, 11, 44.8, 43.2, '0.490829,0.251155,-0.544403,0.465750,0.146138,-0.563333,0.725225,0.051464,-0.489112,-0.321512,-0.263803,0.878619,-0.048282,0.598379,0.095043,0.316053,-0.585295,-0.820844,-0.003406,-0.310875,-0.398188,-0.392777,0.283365,0.153835,-0.364169,0.149761,0.633464,0.075684,0.307058,0.748753,0.044266,0.059220,-0.126261,0.508296,-0.186067,0.465728,0.016882,0.135812,-0.293386,0.481085,0.165847,-0.263009,-0.317482,0.184252,0.254597,0.394391,0.655084,0.052631,-0.173519,-0.260076,0.046348,0.149361,-0.119781,0.402440,0.488289,0.057267,0.199307,0.177253,-0.532359,-0.032884,-0.015265,0.335158,-0.067087,0.174808,-0.100067,0.100671,-0.481480,0.258994,0.125094,-0.175537,0.123352,-0.525110,0.174980,0.580593,0.249006,0.246448,-0.473125,0.210550,-0.359976,-0.046306,0.809162,-0.001683,0.215249,0.426649,0.097802,-0.314732,0.091672,-0.069072,-0.264783,-0.277144,0.044891,0.118193,-0.317294,-0.050277,-0.605351,-0.048853,-0.259406,-0.041217,0.083412,-0.198412,-0.081183,-0.745995,-0.070652,-0.607032,-0.400784,0.380896,0.060741,-0.365769,0.402230,-0.918925,0.103713,0.631543,0.641226,-0.414405,0.443824,0.124100,0.043509,-0.075920,-0.011097,0.224204,0.130322,0.646091,0.350820,0.307110,-0.279678,-0.064653,-0.544469,0.127763', '30345227', '1292219', '1297239', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298874', '黄河绝恋', '剧情', '二战后期，盟军飞行员欧文（Paul Kersey）因飞机被日军军舰击中被迫降落在长城脚下，生命危急之际，他被八路军和当地老百姓救下，不久，战士黑子（王新军）和懂英文的女军医安洁（宁静）奉命护送他前往根据地。为渡过黄河，黑子先带欧文和安洁潜回他的家乡，徒生波折险些丧命。通过与安洁的交流，欧文对中国有了更深的了解，他渐渐爱上美丽、聪慧、坚强的安洁。黄河近在眼前，就在他们以为可以顺利渡过时，日军突至对他们进行了疯狂的阻击。©豆瓣', '宁静', '冯小宁', 7.6, 41515, 'tt0229539', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2364345603.jpg', 0.7, 2.5, 29.5, 48.7, 18.5, '0.328933,0.073705,-0.873431,0.522782,0.194099,-0.112675,0.586554,-0.156493,-0.282017,0.014180,0.190443,0.529071,-0.001934,-0.071180,0.056451,-0.402937,-0.221534,-0.564681,0.027403,0.060763,-0.298223,-0.336244,-0.246341,-0.104810,-0.155329,-0.457942,0.653434,0.600353,-0.115288,0.561027,-0.124447,0.373505,-0.075895,0.513347,-0.054121,0.258945,-0.110488,-0.415243,-0.361668,0.262495,-0.020846,-0.353990,0.059648,-0.074565,0.079560,0.369162,0.807361,-0.074675,-0.051307,0.004497,-0.120428,-0.515064,0.310152,0.455978,0.382189,-0.021985,-0.194061,-0.046681,-0.095254,-0.159287,-0.143709,-0.154713,-0.619859,0.031766,-0.240453,-0.186447,-0.452197,0.162338,-0.375504,0.255129,0.459866,-0.309235,0.144799,0.829846,0.180303,0.246828,-0.282884,0.163416,-0.278534,0.173665,0.947913,0.069939,-0.217079,0.098656,-0.109593,-0.358261,0.074005,-0.432296,-0.251697,0.106385,0.485507,-0.112620,-0.119016,0.124169,-0.289907,-0.018867,-0.412151,-0.317121,0.047008,-0.137487,-0.139785,-0.501737,0.079088,-0.516282,-0.315643,0.368850,-0.124909,0.014764,0.820317,-0.808031,0.083890,0.703947,0.575121,-0.388974,0.495998,0.162709,-0.004025,0.030098,0.279691,0.413390,-0.054827,0.512573,0.483244,0.380755,-0.460041,0.246207,-0.380896,0.203158', '26418093', '1294941', '1870682', '34822138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298880', '生命因你动听', '剧情', '1964年的秋天，美国俄勒冈州。心怀远大理想的作曲家格兰·霍兰为了挣钱完成他的事业，在一所中学谋到了一份音乐教师的工作。他这么做完全是退而求其次的无奈之举，家庭生活的重担使得他不得不面对现实。他到学校上课的第一天，音乐基础级差的学生们便给了他一个难堪的下马威。他们在弹奏乐器时不但走调，甚至连大名鼎鼎的古典作曲家巴赫都没有听说过。霍兰的信心遭到了打击，女校长杰克布也多次向他提出善意的批评。在丈夫的工作遇到挫折时，从事摄影工作的妻子在一旁耐心地劝解和宽慰他；好友体育教师比尔·梅斯特也用自己从教以来的亲身经历，向霍兰证明教导学生需要无私的爱心和充分的时间。在霍兰的悉心培育下，原本对音乐一窍不通的白人学生格楚特·兰和黑人学生路易斯·鲁斯，分别学会了单簧管和大鼓这两样乐器。就在霍兰醉心于教学生活的时候，他的儿子降生了，谁知却是个先天性的失聪患儿。这一重创使霍兰对家庭的重心有所转移，消极彷徨中和漂亮的女学生露韦娜·摩根有了一段朦胧的恋情。妻子察觉到了丈夫的细微变化，但并没有点破。摩根去纽约深造后，霍兰便将全部的身心转移到了儿子和教学上，和妻子的关系也冰释前嫌。之后的30年间，霍兰不但提高了学生们的音乐素养，而且还用爱心、信任和理解赢得了大伙的尊敬和爱戴。在他退休前，深怀感激之情的历届学生们欢聚一堂，为老师开了一场盛大的欢送会，管弦乐队奏响了一支激昂雄壮的“美国交响曲”向霍兰表示了最崇高的敬意。', '理查德·德莱福斯', '斯蒂芬·赫瑞克', 8.5, 6121, 'tt0113862', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1216701008.jpg', 0.4, 1, 12.6, 44.4, 41.6, '0.256279,-0.145850,-0.687365,0.789638,-0.323073,-0.376855,0.659759,0.132920,-0.458753,-0.142867,0.122198,0.750142,-0.022420,0.433810,0.352215,-0.199363,-0.332676,-0.912385,-0.083557,-0.044340,-0.232899,-0.558189,-0.144280,-0.325368,-0.307816,-0.467130,0.386978,-0.076705,-0.210345,0.534385,0.059325,0.072997,0.431755,0.455934,-0.091808,0.043071,0.089639,0.116720,-0.212446,0.017043,0.266566,-0.301125,-0.313904,0.163280,0.144857,0.501705,0.628568,-0.070935,-0.108249,0.016552,0.439998,-0.234321,0.122138,0.175393,0.234468,0.128278,-0.020041,0.223876,-0.120702,0.078054,-0.165368,-0.164072,-0.790376,-0.087146,-0.024463,-0.073265,-0.784336,0.918210,-0.044274,-0.103998,-0.068368,-0.319318,0.120819,0.242008,-0.018002,0.548354,-0.347714,0.207678,-0.244593,0.357179,0.631371,-0.018407,-0.363545,0.285442,-0.462793,-0.514159,-0.054593,-0.241169,-0.473290,-0.244370,0.237093,0.082641,-0.035649,0.069255,-0.554695,-0.184618,-0.093664,-0.265436,0.041979,-0.565138,0.030801,-0.677367,0.088543,-0.436298,-0.431055,-0.108266,0.214275,-0.346184,1.129905,-0.964844,0.147244,0.501958,0.269008,-0.458764,0.767379,0.045526,0.220308,-0.004536,-0.242964,0.124610,-0.105774,0.366099,0.254191,0.570957,0.059653,-0.241506,-0.222877,0.539473', '27602116', '4127270', '26809007', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298898', '暗战', '剧情', '大盗张彼德（刘德华）得知生命只剩四周时，决定为死于黑道老大（李子雄）之手的父亲报仇，为此他精心设计打劫了黑道老大的运输公司隔壁的财务公司，并挟持人质引来因得罪上级被转调文职的高级谈判专家何尚生（刘青云）。何尚生在同张彼德展开追逐时，虽屡战屡败，却渐了解到黑帮老大实则借 助运输公司做非法走私珠宝的生意，于是同张彼德化敌为友，携手同黑帮势力展开了斗智斗勇的游戏。而张彼德在逃避何尚生追逐的过程中无意结识女孩梁婉婷（蒙嘉慧）后，在生命的尽头获得一份浪漫奇缘。©豆瓣', '刘德华', '杜琪峰', 8.6, 231840, 'tt0216165', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2001994907.jpg', 0.1, 0.6, 11.5, 46.6, 41.2, '0.111247,0.042549,-0.410768,0.261636,0.058132,-0.171233,0.273400,0.293988,-0.517678,-0.159566,0.171874,0.551412,0.243657,-0.073225,0.282361,-0.273437,-0.147313,-0.490950,-0.205528,-0.049200,0.068058,-0.502910,-0.187784,-0.215451,-0.133633,-0.045144,0.753312,0.215003,-0.339686,0.383925,0.331898,0.197107,-0.465652,0.307941,0.011474,-0.158296,0.300116,0.266122,-0.742813,0.175806,-0.179140,-0.199201,0.039060,-0.262213,0.075935,0.395137,0.511503,0.026336,0.096765,-0.281649,0.243179,-0.273480,0.039551,-0.337154,0.456244,0.260017,0.146301,0.398618,-0.213640,-0.188599,0.034345,0.042802,-0.867232,-0.069283,0.290484,-0.059882,-0.467563,0.247411,-0.022389,0.262174,0.080650,-0.157986,0.198549,0.436664,0.353265,0.056717,0.091300,0.201775,-0.545525,0.382969,0.618682,-0.103981,0.215872,0.170218,0.200194,-0.352498,0.072531,-0.504181,-0.087497,-0.188005,0.226547,-0.140509,-0.203837,0.305674,-0.630673,-0.213680,0.019419,0.057581,0.339312,-0.326821,-0.058060,-0.761346,-0.042057,-0.055649,0.039755,0.166612,0.324235,-0.288965,0.346092,-0.739940,-0.000464,0.761473,0.236590,-0.623589,0.689045,0.052732,0.316847,-0.375571,-0.286874,-0.003923,0.490622,0.322913,0.135187,-0.268829,-0.115601,-0.309607,-0.152451,-0.123959', '1793491', '1294893', '27073234', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298909', '魔鬼代言人', '剧情', '凯文（Keanu Reeves饰）是个保持不败记录的年轻律师，娇妻相伴，事业有为的他宛如生活在天堂一般。受到纽约著名事务所的邀请，他携妻子来到纽约。奢华的生活近在眼前，一切似乎都昭示着明天的坦途与光明。老板米尔顿（Al Pacino饰）对凯文非常赏识，不断地委以重任，同时也带他见识了五光十色的世界。面临着工作的压力和色情，名利各个方面的诱惑，凯文渐渐的迷失在生活中，甚至忽视了妻子精神上的反常。直到失常的妻子自刎在他的臂弯中，凯文才猛然意识到身边的危机。凯文愤怒的指责米尔顿给他设下陷阱。然而，究竟是魔鬼的诱惑还是内心的虚荣将凯文引向今日的迷雾与深渊？自由意志下凯文又会做出怎样的抉择？©豆瓣', '基努·里维斯', '泰勒·海克福德', 8.4, 149356, 'tt0118971', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1695005982.jpg', 0.2, 1, 14.1, 47.9, 36.8, '0.100697,0.270448,-0.763868,0.663927,-0.133060,-0.189051,0.849817,0.507368,-0.405497,-0.039799,0.603309,0.626731,-0.156578,0.305909,0.550538,0.167386,-0.287206,-0.896196,-0.177644,-0.020355,-0.251591,-0.481853,-0.591197,0.127609,-0.054937,-0.297354,0.603380,0.175521,-0.195250,0.290405,0.099335,0.328108,0.185804,0.759911,-0.200477,-0.093567,0.010518,-0.026616,-0.443701,0.060640,0.125863,-0.432588,-0.155888,0.414484,-0.206971,0.147498,0.714823,-0.386670,-0.328310,-0.027179,0.575845,-0.282251,0.123316,0.271552,0.036933,0.012693,-0.085991,0.288244,-0.193947,0.125878,0.109915,-0.057409,-0.962713,-0.033673,0.153532,0.259301,-0.527144,0.226884,0.039623,-0.092166,0.113250,-0.306251,-0.037132,0.103317,0.183451,0.684393,-0.246050,0.322680,-0.352364,-0.072945,0.564386,-0.041355,-0.337033,0.209218,-0.413139,-0.215848,-0.037023,-0.198016,-0.696994,-0.308596,0.091152,0.328489,-0.158869,0.427548,-0.565304,0.164980,-0.194892,-0.216177,-0.131163,-0.669797,-0.207603,-0.585384,-0.378353,-0.500926,-0.207628,-0.090009,0.115753,-0.161741,0.745766,-0.760298,0.287541,0.706945,0.241764,-0.399722,0.686105,0.194196,-0.066670,-0.119309,-0.049480,0.438959,-0.095289,0.341935,-0.092276,0.212659,0.023651,0.155537,-0.314905,0.696924', '25928048', '35158375', '1509868', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298911', '遥远的桥', '剧情', '欧战尾声，盟军上下逐渐弥漫着乐观的情绪。为了提前结束战争，各地盟军将领认为只要一番猛攻，便可提早直捣柏林结束战争。于是轻率地将大批伞兵空投在德军营地背后，去攻占阿纳姆的那座横跨莱茵河的大桥。不料遭遇德军的顽强抵抗，盟军付出了伤亡惨重的代价。这场堪称二战中最具戏剧性的战役，终以盟军的惨痛失败而告终。由奥斯卡金像奖得奖导演理查德·阿滕伯勒执导的战争巨片《遥远的桥》，根据科尼利厄斯·瑞恩的同名小说改编而成。影片表现和讴歌了盟军在二战中浴血奋战的斗争精神，被誉为电影史上的超级战争巨片。本片的明星阵容空前强大，聚集了诸如詹姆斯·卡恩、迈克尔·凯恩、肖恩·康纳利、罗伯特·雷德福、安东尼·霍普金斯等数国的数十位明星。本片荣获1978年第31届英国电影和电视艺术学院奖最佳摄影、最佳男配角、最佳原声等多项大奖与提名。©豆瓣', '德克·博加德', '理查德·阿滕伯勒', 8.2, 8486, 'tt0075784', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2394480788.jpg', 0.3, 1.6, 15.7, 51.9, 30.5, '-0.165590,-0.046057,-0.924733,0.708269,0.671626,-0.198768,0.394520,-0.116099,-0.224058,0.038559,0.376077,1.051922,-0.296494,-0.377882,0.391746,-0.377935,-0.569083,-0.807346,-0.540263,0.111252,0.005711,-0.258878,-0.491841,-0.009475,-0.032034,-0.386861,1.024477,0.293457,-0.287499,0.521623,0.463250,0.173769,0.178015,0.154800,0.243779,0.159048,0.269403,-0.365914,-0.582764,0.485897,-0.168839,-0.337384,-0.386851,0.110052,0.014607,0.212572,0.736061,-0.337654,0.253496,0.144003,0.542628,-0.466428,-0.002017,0.152033,0.405291,0.076249,0.080826,0.196174,0.029699,0.200700,-0.269432,-0.302427,-0.750824,-0.075495,-0.065122,0.004897,-0.257288,0.493750,-0.048841,0.223307,0.110647,0.090819,-0.002350,0.547204,0.422550,0.021010,-0.076702,-0.019667,-0.221249,0.427034,0.514367,-0.183564,-0.375234,0.119582,0.003624,-0.544937,-0.098266,-0.698807,-0.404529,0.131059,0.517686,-0.386676,0.290615,0.432924,-0.631886,0.118505,-0.365345,-0.635591,-0.118081,0.115702,0.118789,-1.213198,-0.195650,-0.207796,0.092611,0.027979,-0.035116,0.076128,0.722836,-0.327448,0.131897,0.464975,-0.056004,-0.020052,0.408547,0.115916,0.129304,-0.015654,0.037458,0.417726,-0.298072,0.283284,0.143161,0.259314,-0.002502,-0.342353,-0.220068,0.435686', '1780122', '26990609', '24751811', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298917', '卡桑德拉大桥', '剧情', '《卡桑德拉大桥》是一部英国，意大利和西德联合拍摄的影片，该片的拍摄手法与内容成为此后灾难片的经典模式。恐怖分子闯进了日内瓦的国际卫生组织总部，欲实施恐怖袭击，受到了保安人员的阻击。追捕过程中，警员不小心将实验品鼠疫细菌打碎溅到罪犯身上。一名歹徒当场感染腐烂而死，另一名 窜到一列开往斯特哥尔摩的火车上。病毒感染非常快，整个火车上许多人都给传染上了这种细菌，国际警局为这种鼠疫细菌不传染给其他人，对火车进行控制，不许在任何车站停留，并要将其开到卡桑德拉大桥给毁掉。女作家珍妮弗（索菲娅·罗兰 Sophia Loren 饰）和丈夫张伯伦医生（理查德·哈里斯 Richard Harris 饰）也被卷入。医生通过实验方法使许多人解除细菌，却不被上级相信，只有用自己的方法进行解决，列车上的人们与防化部队发生冲突，人们纷纷拿起武器。众人的命运跟随火车一起驶向未知....', '索菲娅·罗兰', '乔治·P·科斯马图斯', 8.3, 28021, 'tt0074292', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1971441788.jpg', 0.1, 0.9, 14.7, 53.4, 31, '0.496193,-0.108010,-0.601503,0.430028,-0.020880,-0.013310,0.791543,-0.100674,-0.372551,0.058328,0.334316,0.626576,-0.210146,-0.180974,0.304852,-0.020220,-0.650985,-0.619244,0.053716,0.142136,-0.776815,-0.271927,-0.048924,-0.277363,-0.067455,-0.414714,0.636642,0.189180,-0.410984,0.242880,-0.055618,0.434833,-0.193506,0.494387,-0.060316,0.009198,-0.139139,-0.610836,-0.113050,0.473856,0.106327,-0.244683,0.079904,-0.011581,-0.125276,0.320953,0.674886,-0.152623,-0.066602,-0.391743,0.113756,-0.620153,0.096982,0.153180,0.351532,0.107391,0.001926,0.190947,-0.136437,0.208400,0.062251,0.221521,-0.576679,-0.132859,-0.131157,0.353252,-0.529839,0.293829,-0.394081,0.164093,-0.116493,-0.246114,0.274317,0.140863,0.147104,0.178760,-0.250189,-0.221022,-0.675716,0.015456,0.734244,-0.156903,-0.221789,0.138992,-0.230719,-0.379971,-0.031656,-0.255155,-0.279513,0.035248,0.259495,0.045714,-0.205693,0.210196,-0.584917,-0.116354,-0.257443,-0.499100,-0.174297,-0.090461,0.066449,-1.041049,0.175007,-0.191993,-0.149175,-0.035804,0.259045,0.007329,0.510906,-0.413977,0.154271,0.390969,0.352962,-0.332530,0.268633,-0.136714,0.232008,-0.047584,-0.180008,-0.059184,0.343357,0.782636,0.169371,0.469962,-0.009907,-0.167803,-0.175175,0.330569', '1307897', '10466639', '1294917', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298930', '天雷勾动地火', '喜剧', '一个还未曾恋爱过的同性恋剧作家盖百列（Christian Campbell 克里辛•坎贝尔 饰），自从和室友瑞奇一起住以后，就烦恼不断。瑞奇和女友朱迪有着频繁的性生活，搞得盖百列几乎夜夜都要躲到外面有家不能回。这晚，又被赶出家门的盖百列跑到了同性恋酒吧去喝闷酒，就在这一晚，他遇到了go-go boy——马克(John Paul Pitoc 约翰•保罗•皮托克饰)。两人一见钟情，决定来一晚一夜情，可惜，他们没有地方。于是，他们沿着街头行走，一次又一次，他们的计划总是被各种各样的事情打扰，笑话连连。但是，两人也随着接触的时间增长，慢慢熟悉了对方，一段爱情就这样慢慢滋长。©豆瓣', '托蕊·斯培林', '吉姆·弗尔', 7.7, 7329, 'tt0162710', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503262842.jpg', 0.6, 3, 29.1, 43.2, 24.1, '0.450706,-0.336999,-0.711571,0.577021,-0.089524,-0.545902,0.742533,0.086777,-0.438639,-0.195824,0.016403,0.569251,-0.560043,0.187710,0.205539,0.066530,-0.424787,-0.758992,0.536131,-0.308977,-0.499455,-0.163070,-0.214498,-0.246735,-0.227995,0.023050,0.096072,-0.124360,-0.008854,0.430759,0.191075,-0.067429,-0.190982,0.761599,-0.263313,0.329264,0.069786,0.198164,-0.201938,0.250255,0.390496,-0.184752,-0.102572,-0.104310,0.248169,0.181306,0.448074,-0.086254,-0.100424,0.232189,-0.029104,-0.098778,-0.143373,0.099892,0.560963,-0.298879,0.424706,0.258751,-0.265272,0.024524,-0.008234,0.151826,-0.148303,0.311341,-0.270895,0.068599,-0.582118,0.569079,0.043730,-0.091320,-0.093152,-0.439780,-0.040668,0.310592,0.298733,0.222360,-0.243741,-0.105370,-0.419128,0.034856,0.700330,0.051562,-0.148338,0.569051,-0.033339,-0.125990,-0.064184,-0.016772,-0.611969,-0.139814,0.332472,-0.056546,-0.384252,0.193849,-0.549528,-0.023078,-0.299072,-0.340357,0.021677,-0.165735,0.255611,-0.529575,-0.108017,-0.213377,-0.264844,0.362601,-0.033626,-0.028024,0.133043,-0.513125,0.384031,0.631054,0.343494,-0.386588,0.519369,0.176174,0.265334,0.155243,0.031118,0.014842,0.039651,0.523818,0.552984,0.706420,0.090027,0.074425,-0.432168,0.543758', '1309172', '1292533', '21447058', '25837574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298944', '无言的山丘', '剧情', '1927年，大量贫苦农民涌向台湾九份山区金瓜石，圆他们的淘金梦。憨厚的佃农阿助、阿尾兄弟随着淘金人潮来到九份，投租在寡妇阿柔的陋屋里。阿柔是位人称克夫运的可怜女人，她与阿助日久生情。淘金热的兴起，使九份充斥着走私与色情。日本方面派才俊柴田负责治理金矿的秩序。然而，矿工与妓院勾结，黄金交易日益猖獗，抗争事件纷乱迭起，才俊被杀。阿助与阿柔婚后不久病故，阿柔欲哭无泪，带着四个孩子及亡夫的牌位，落寞地离开九份……', '杨贵媚', '王童', 9.2, 19500, 'tt0108602', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522310203.jpg', 0.2, 0.5, 4.9, 29.1, 65.3, '0.160823,-0.245881,-0.412485,0.079473,0.111295,-0.233667,0.709712,0.150491,-0.613294,-0.158344,0.041646,0.439829,-0.000614,0.221894,0.294575,0.067920,-0.001917,-0.432952,-0.434991,-0.041654,0.179553,-0.374045,0.044125,-0.147810,-0.353730,-0.406600,0.577451,0.279703,-0.003135,0.563149,0.108905,0.330246,-0.658349,0.088083,-0.300847,0.118798,0.061807,-0.092152,-0.349609,0.077377,-0.318644,-0.200192,-0.292011,-0.397597,-0.009328,0.167745,0.829864,-0.217151,0.165122,-0.083407,0.171702,-0.175105,-0.389854,0.082980,0.380293,0.021757,0.159200,0.268419,-0.293206,-0.295023,0.143127,-0.139968,-0.098054,0.074530,0.189338,0.043547,-0.717092,0.337033,0.152151,-0.188919,0.012585,-0.163672,0.252479,0.395544,-0.043222,0.650362,-0.016173,0.069722,-0.410009,0.292272,0.577323,0.012550,0.157263,-0.171091,-0.070967,-0.472972,0.146832,-0.396991,-0.457969,-0.157591,0.312372,-0.272275,0.039752,0.480950,-0.763527,0.148902,-0.171133,-0.282605,0.265813,0.030881,-0.187491,-0.426980,-0.035256,-0.214843,-0.160668,0.266448,0.429934,0.121487,0.658872,-0.576271,0.052166,0.426284,0.365024,-0.552095,0.414445,-0.130393,0.073258,-0.314678,-0.292150,-0.004149,0.229160,0.240452,0.276691,-0.021169,-0.495711,-0.009625,-0.229564,0.130445', '21619567', '27594653', '1467779', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298947', '催眠', '惊悚', '为迎接即将到来的田径大赛而集中特训的18岁少女、和相伴一生的妻子共庆生日的73岁老人、与所爱的女友举行隆重婚礼的新郎。三个在各自圈子里过着平凡生活的陌生人，却在同一晚同一时刻死亡。他们的死状恐怖，死因蹊跷，并且都在临终前留下“绿猴子”的神秘语句。起初这三起案件被认定为普通的自杀事件，但资深刑警樱井孝典（宇津井健 饰）则认定其中必有玄机，他找到对催眠颇有研究的心理学教授嵯峨敏也（稲垣吾郎 饰）协助调查。经过一段时间的调查，樱井他们偶然将疑点锁定在某电视催眠节目上，与此同时，各种蹊跷死亡案件仍在不断发生，案情紧迫。患有人格分裂的少女入绘由香（菅野美穂 饰），成为了走有案件走向的重要人物……©豆瓣', '稻垣吾郎', '落合正幸', 7.2, 6828, 'tt0228807', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1378831467.jpg', 2, 6.9, 37, 38.5, 15.6, '0.158884,-0.197185,-0.538557,0.269962,-0.045385,0.183631,0.678732,0.044512,-0.435800,-0.605163,0.565036,0.615897,-0.357358,0.230765,0.317769,-0.193629,-0.004665,-0.790201,-0.060126,-0.129127,-0.414702,-0.622997,-0.079003,-0.211222,0.027738,-0.366286,0.620159,0.153243,0.009312,0.401326,0.295002,0.496145,-0.411457,0.251824,-0.245533,-0.223779,0.181688,0.174658,-0.310862,0.057695,-0.032695,-0.332310,-0.112135,-0.011594,-0.053327,0.453158,0.732145,-0.338701,-0.540131,0.161153,0.635051,-0.410427,-0.126271,0.178308,0.605828,0.256654,0.061920,0.490184,-0.158009,-0.035258,-0.131745,0.028858,-0.819209,-0.070944,0.399577,0.377994,-0.382611,0.494389,-0.035480,-0.039858,0.168331,-0.032208,0.242990,0.545255,0.175249,0.191123,0.142225,0.224689,-0.213620,0.265990,0.707559,0.077214,-0.132005,0.216659,-0.234577,-0.456972,-0.101743,-0.197719,-0.173772,0.260364,0.135523,0.104561,-0.101968,0.155086,-0.311974,-0.043695,0.067066,0.016483,0.075212,-0.225397,-0.280789,-0.658220,-0.015572,-0.261676,-0.482151,0.082487,0.143492,-0.349602,0.723533,-0.652181,0.394506,0.526359,0.068342,-0.435790,0.762133,0.203582,0.168529,-0.451534,-0.230971,0.234145,0.110446,0.240232,-0.104978,0.343925,-0.058033,-0.082037,-0.777966,0.194694', '25880986', '3811356', '25928048', '30352946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298973', '永远的莉莉亚', '剧情', '莫斯科街头，花季少女莉莉亚（奥莎娜·阿金什那 Oksana Akinshina饰）正向朋友吹嘘即将随母亲移居美国。可到家之后，母亲告诉她要留下来跟姑妈生活。而姑妈则趁机霸占她的房子，把她赶到一幢肮脏破旧的公寓去住。莉莉亚那童话般的幻想瞬间崩塌，此时她终于相信被母亲遗弃了。孤独无助的莉莉亚只能从她唯一的朋友男孩沃洛佳（波古查史基 Artyom Bogucharsky饰）那里得到一丝安慰。为了活下去，莉莉亚也被迫走上了靠出卖肉体为生的道路。当善良天真的莉莉亚以为遇到真爱的时候，便不顾一切的去了瑞典。可她又怎会知道，这地狱般的生活其实才刚刚开始……童星奥莎娜·阿金什那凭借这个角色获得2002年欧洲电影奖最佳女演员的提名。©豆瓣', '奥莎娜·阿金什那', '鲁卡斯·穆迪森', 8.2, 9590, 'tt0300140', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p668928865.jpg', 0.4, 1.3, 15.9, 51.3, 31.1, '0.071925,0.080823,-0.409751,0.389875,0.115702,-0.584557,0.511314,0.040875,-0.090121,-0.310871,0.112069,0.868348,0.171552,0.334489,0.294556,0.344542,-0.402913,-0.401396,0.023959,-0.158615,-0.284719,-0.336329,-0.101727,0.037550,0.003742,-0.185786,0.612867,0.010077,-0.089878,0.394209,0.260383,0.350333,0.090040,0.144255,-0.144453,-0.020385,-0.039177,0.080073,-0.467110,0.231486,0.162867,0.057829,-0.055875,0.201080,0.104740,0.021801,0.608485,-0.303908,0.154732,0.020693,0.219789,-0.197062,-0.003306,0.088453,-0.017855,-0.370332,0.286775,0.084793,-0.251900,-0.054779,0.164041,-0.180869,-0.467045,0.196240,-0.004342,-0.325550,-0.406628,0.112338,0.243910,0.154131,0.428290,-0.377959,0.366961,0.270669,0.095919,0.571810,-0.422685,0.124137,-0.482595,0.116753,0.630677,-0.113963,0.181164,0.383168,-0.254112,-0.201079,0.209868,-0.412268,-0.690636,0.079618,0.052987,0.094935,-0.404917,0.153542,-0.498682,-0.195803,-0.503476,-0.101081,0.204382,-0.469402,-0.148848,-0.117346,-0.216305,0.078337,0.018961,-0.109822,-0.286536,-0.387586,0.537551,-0.632328,0.472208,0.672524,0.479229,-0.532715,0.782735,0.014666,0.024743,-0.191970,0.027681,0.745835,-0.027323,0.304718,0.009228,-0.042469,-0.041774,-0.089261,-0.264688,0.688301', '1460341', '1292720', '30167633', '3036465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298974', '我心狂野', '爱情', '因杀人而入狱的塞勒（尼古拉斯•凯奇 Nicolas Cage 饰）终于熬过几年铁窗生涯获释了，心上人罗拉（劳拉•邓恩 Laura Dern 饰）迎接了他的出狱。有情人又得以团聚，但罗拉的母亲玛丽一直都不喜欢塞勒，一直在阻挠女儿和塞勒来往。两人只好相约私奔，来到了南方。玛丽找来了侦探男友约翰尼追踪他们，企图将罗拉带回去。两人在私奔过程中，都向对方袒露了自己生活中曾经有过的阴暗岁月，那些岁月里都混杂着血腥、暴力和性，但他们都充分体谅了对方。塞勒此时正为一个毒品贩子桑托干活，桑托怕约翰尼因跟踪塞勒而发现他们的交易场所，因此将约翰尼干掉了。另一个毒贩鲍比为了除掉塞勒，设了一个圈套正等待着塞勒上钩。©豆瓣', '尼古拉斯·凯奇', '大卫·林奇', 7.4, 26258, 'tt0100935', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1218720978.jpg', 1.3, 5.6, 32.1, 42.4, 18.6, '0.274027,-0.086933,-0.519302,0.402684,-0.269831,-0.478342,0.801565,0.016510,-0.416703,-0.223079,0.072782,0.612335,0.004766,0.166331,0.273494,0.091946,-0.608226,-0.641518,0.022036,-0.240340,-0.225405,-0.489431,-0.289564,-0.374062,-0.284559,-0.198451,0.380317,-0.070188,0.111821,0.382352,0.417936,0.243054,-0.233900,0.519448,-0.129721,0.220180,0.350685,-0.229296,-0.350951,0.277880,-0.004650,-0.340201,-0.217831,0.143315,0.082688,0.531470,0.782413,-0.244854,0.160914,-0.036233,0.038521,-0.352069,0.014283,0.246617,0.179568,-0.191571,0.202213,0.322665,-0.169959,-0.052504,0.087190,0.045529,-0.480530,0.084861,-0.059627,0.032905,-0.437925,0.238850,0.134795,-0.076221,-0.004246,-0.379143,0.125982,0.259392,0.296574,0.217177,-0.173531,-0.077100,-0.476331,0.149087,0.623299,-0.193602,0.195254,0.317146,-0.223133,-0.363068,0.204409,-0.036615,-0.475298,-0.226013,0.495391,0.051056,-0.241916,0.432620,-0.615399,-0.064489,-0.473410,0.007525,-0.035662,-0.553650,-0.113994,-0.728419,-0.316067,-0.297629,-0.360890,0.144065,-0.097483,-0.244231,0.345936,-0.607527,0.383820,0.744144,0.323942,-0.416945,0.608014,0.114037,0.257927,-0.066098,0.028595,0.383478,0.164149,0.171686,0.378332,0.390627,0.182767,-0.032718,-0.322086,0.361047', '3326747', '1298197', '10466639', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298976', '铁血战士', '动作', '美军一名飞行员在南美洲的原始森林失踪了，那里盘踞着不怎么友好的当地游击队。美军特种兵少校达奇（阿诺•施瓦辛格 Arnold Schwarzenegger）率领部下亲自前往搜救。他们在森林里很快就发现了失踪的飞行员的尸体，死状恐怖。大家都认为那是当地的游击队干的，愤怒的队 员开始寻找当地游击队的基地，要为同伴报仇。然而当他们发现当地游击队的营地时，发现当地人也被一种恐怖气氛所笼罩着。随后，队员们相继被袭击身亡，但每次都没发现敌人的半个影子。对方就像凭空隐形了一样。孤身一人的达奇决心凭自己的力量面对这股神秘恐怖的力量……©豆瓣', '阿诺·施瓦辛格', '约翰·麦克蒂尔南', 7.7, 36358, 'tt0093773', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2101543383.jpg', 0.4, 2.3, 28, 48.9, 20.4, '0.415364,-0.301593,-0.985790,0.544172,0.006518,-0.046049,0.748463,-0.093585,-0.675577,-0.197771,0.270990,0.796537,0.206846,0.111120,-0.092718,-0.215170,-0.346647,-0.633797,-0.637587,-0.159407,-0.368146,-0.152791,-0.411553,-0.310027,0.117599,-0.416751,0.543791,0.193929,-0.038480,0.603279,0.108611,0.359770,0.030939,0.652566,-0.136078,0.050027,0.401239,-0.425955,0.087270,0.086896,-0.236412,-0.133730,-0.064729,0.168711,-0.039125,0.449020,0.797373,-0.097393,-0.206761,-0.177345,-0.001138,-0.293926,0.254580,0.241685,0.742683,-0.058097,0.153029,-0.167821,0.064082,0.056388,-0.114479,0.174840,-0.643381,0.096653,-0.003819,0.160896,-0.485661,0.221486,0.017005,0.060371,0.243479,-0.274776,0.398498,0.376135,-0.058079,0.242941,-0.177543,-0.123061,-0.707369,0.049070,0.910513,-0.396946,-0.395415,0.014561,-0.225072,-0.456416,-0.040286,-0.220524,-0.110474,-0.085292,0.369916,0.059909,-0.291400,-0.036681,-0.765195,0.111362,-0.281335,-0.333697,-0.456074,-0.215902,-0.244947,-0.741870,-0.111139,-0.245598,-0.221280,0.498998,-0.095596,0.272153,0.624611,-0.671194,0.275981,0.797000,0.116503,-0.443393,0.405586,-0.135551,-0.008837,0.170122,0.055465,-0.011517,0.408261,0.580375,0.449968,0.471241,-0.250892,-0.312893,-0.133157,0.180256', '34461680', '3011051', '1292849', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298981', '致命武器2', '喜剧', '一次偶然中，瑞格（梅尔·吉布森 Mel Gibson 饰）与莫道（丹尼·格洛弗 Danny Glover 饰）这对好搭档撞破了一起走私南非金币的违法勾当，正义感爆棚的两人决心绝不对此坐视不管，于是展开了一系列充满了进场刺激的火爆追击。随着调查的深入，一个名叫艾金（乔斯·雅克兰德 Joss Ackland 饰）的男人浮出了水面，他的真实身份竟然是享有外交豁免权的南非外交官，瑞格和莫道陷入了举步维艰的境地。两人被上司派去保护一名叫盖茨（乔·佩西 Joe Pesci 饰）的男人，他曾经是帮助艾金洗钱的同谋，如今成为了警方的污点证人。很快，发生的一系列事件就让瑞格和莫道明白了，保护盖茨甚至比追击艾金还要危险和困难。©豆瓣', '梅尔·吉布森', '理查德·唐纳', 7, 3784, 'tt0097733', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1955834005.jpg', 0.8, 3.7, 47.2, 39.2, 9.1, '0.423057,-0.221032,-0.551586,0.597201,-0.160296,-0.238593,0.738940,0.415981,-0.740942,0.008380,0.146074,0.735035,-0.303154,-0.221850,0.413784,0.028598,-0.328561,-0.803199,-0.072706,-0.131954,-0.160033,-0.852885,-0.542404,-0.232069,-0.103173,-0.243231,0.263917,0.086974,-0.320002,0.624204,0.539714,0.436163,-0.087828,0.537639,0.246866,-0.028476,0.415644,-0.257359,-0.425351,0.212209,0.118215,-0.078933,0.033118,0.232529,-0.003238,0.473694,0.293320,-0.231736,-0.157902,-0.163983,0.316518,-0.428233,0.109504,0.198315,0.202775,-0.080543,0.009869,0.384561,-0.384914,-0.141806,0.225082,0.184324,-0.831363,0.069421,0.216639,0.127846,-0.718393,0.129974,-0.276007,-0.099684,0.083680,-0.207959,0.128342,0.511516,0.260184,0.164040,0.122749,-0.176614,-0.545360,0.020872,0.593910,0.030518,-0.199270,0.125934,0.004760,-0.318602,-0.231494,-0.152216,-0.112605,-0.064511,0.484815,-0.068933,-0.103918,0.378464,-0.459936,-0.098292,-0.409744,-0.234195,-0.218858,-0.301436,-0.091948,-0.671481,-0.317187,-0.390890,-0.279031,0.074213,-0.002846,-0.148965,0.448504,-0.728311,0.280866,0.627309,0.277314,-0.411086,0.505501,0.189918,0.203450,-0.096009,-0.019350,0.032315,0.035829,0.121735,0.157143,0.256029,0.175294,-0.315707,0.043024,0.267800', '1307442', '1299799', '1294616', '6790253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298997', '黄昏之恋', '剧情', '尽管父亲是著名的婚外情调查专家，尽管见识过了无数的忠贞感情最终化为泡影，艾莲（奥黛丽·赫本 Audrey Hepburn 饰）却依旧对爱情有着无限的期望和憧憬，她甚至觉得，只有那些明知不道德却还要迎难而上的恋情才能算的上是真爱。一次偶然中，艾莲结识了父亲的调查对象法兰肯（加里·库柏 Gary Cooper 饰）——一个在情场上如鱼得水的风流浪子。艾莲捏造了虚假的身份，开始在法兰肯面前扮演起了神秘女郎的角色，没想到，自己的纯情和真挚竟然猎得了这位浪子的真心。法兰肯拜托私家侦探调查艾莲的踪迹，没想到这位侦探正是艾莲的父亲。迫于父亲的压力，本来心心相印的两人只得分手，一对天设地造的情侣眼看这就要擦身而过。©豆瓣', '加里·库珀', '比利·怀尔德', 7.5, 6767, 'tt0050658', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2172379612.jpg', 0.8, 4.8, 31.9, 41.4, 21.1, '0.346417,-0.016050,-0.548756,0.670671,-0.183876,-0.356081,0.659876,-0.095864,-0.616685,-0.260337,0.314604,0.632886,-0.190825,0.295158,0.261296,0.048889,-0.242387,-0.765240,-0.196388,-0.313297,-0.037532,-0.566249,-0.694963,0.153085,-0.175372,-0.057475,0.543379,-0.002706,-0.203048,0.526069,0.523639,0.404331,0.067202,0.303608,-0.265288,-0.164779,0.254924,0.324708,-0.468939,0.121369,0.082652,-0.227939,-0.015537,0.273030,-0.138187,0.387997,0.387252,-0.383691,-0.157260,0.020930,0.454518,-0.026876,0.154456,0.196702,0.192923,-0.130548,0.289047,0.209651,-0.081128,-0.259106,0.094315,-0.054825,-0.908611,-0.032388,0.145833,0.137704,-0.607994,0.251462,-0.092154,-0.148988,0.037971,-0.208146,0.078579,0.213616,0.232780,0.258506,-0.118714,0.215585,-0.286167,0.223130,0.624230,0.323625,-0.067486,0.520572,-0.197431,-0.442354,0.021824,-0.312146,-0.556908,0.031792,0.211170,0.018666,-0.096621,0.276684,-0.591844,-0.104770,-0.324659,0.213675,0.044071,-0.462211,-0.007327,-0.378341,-0.414190,-0.650864,-0.270416,0.195647,0.046488,-0.429654,0.763852,-0.990834,0.062455,0.570427,0.024241,-0.540628,0.687512,0.523186,-0.210114,-0.259804,-0.236909,0.306936,-0.026288,0.025796,0.024344,0.246474,0.224220,-0.338588,-0.350028,0.475538', '4301278', '1793491', '1783461', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1298999', '心动的感觉', '喜剧', '女大学生凡伦黛（苏菲·玛索 Sophie Marceau 饰）正为了她的教师资格证而努力读书，某天，在滑雪场上，凡伦黛结识了充满了魅力的音乐家奈德（文森特·林顿 Vincent Lindon 饰），为了缓解考试带来的紧张和压力，凡伦黛和奈德之间发展出了一段露水情缘，两人非常有默契的达成了共识——只动性，不动情。没想到，一夜过后，凡伦黛竟然深深的迷恋上了奈德，奈德也暗暗被凡伦黛的魅力所折服。分开后的两人无法常常见面，只能通过电话互诉衷肠，误会也油然而生。心高气傲的凡伦黛一气之下选择了离开奈德，奈德却无法放下对凡伦黛的爱意，阴差阳错之间，一对两情相悦的恋人眼看着就要擦肩而过。©豆瓣', '苏菲·玛索', '克洛德·皮诺托', 7.6, 15189, 'tt0096523', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2377321054.jpg', 0.5, 3.1, 31.9, 43.8, 20.7, '0.499513,-0.033112,-0.612905,0.540172,0.064348,-0.636878,0.828954,-0.012325,-0.583487,-0.114843,0.074616,0.786284,-0.470295,0.409800,0.494181,-0.231410,-0.499187,-0.986213,0.074171,-0.321630,0.031362,-0.690154,-0.247701,0.066155,-0.141629,-0.222597,0.358143,-0.131291,-0.051054,0.740968,0.295030,0.122322,-0.127084,0.519102,-0.079980,-0.083761,0.174982,0.154613,-0.411293,0.116578,0.216939,0.004872,-0.078421,0.068855,-0.216564,0.249946,0.537367,-0.238701,-0.090907,0.044794,0.443729,-0.305019,0.200574,0.232167,0.156414,0.282396,0.484339,0.090971,-0.221150,-0.127708,0.212471,0.121616,-0.632474,0.405649,0.021440,0.107700,-0.504203,0.640194,0.097313,-0.390556,0.236843,-0.525993,-0.058405,0.360216,0.666160,0.396000,-0.512092,0.042708,-0.352877,-0.103654,0.774745,0.165749,0.021038,0.341725,-0.317671,-0.480194,0.083149,-0.147066,-0.259452,-0.417133,0.585983,0.464128,-0.021305,0.105295,-0.555413,-0.093246,-0.291941,-0.005579,-0.145663,-0.708871,0.277028,-0.562254,-0.439014,-0.561284,-0.526016,0.335601,0.383486,-0.386637,0.529749,-0.958324,0.214772,0.419822,0.290773,-0.213310,0.653674,0.447014,-0.252303,-0.104031,-0.144878,0.470543,-0.410536,0.326558,0.225395,0.470334,-0.117215,0.198263,-0.308208,0.453914', '1308755', '34429100', '25853727', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299035', '绝世宝贝', '喜剧', '自从成功研发“绝世好Bra”后，Lena（梁咏琪 饰）、Johnny（刘青云 饰）跟Wayne（古天乐 饰）再次受命研发以“绝世好B”为卖点的一系列婴儿产品。Johnny升职为部门主管，聘请了十分神经质的秘书Sabrina（关之琳 饰）。Wayne与Lena也早已确定了恋爱关系，更有了结婚的打算。Wayne对婴儿有恐惧症，对三人的研究任务带来的诸多不便。总公司派来了儿童行为专家Boey来协助他们的研究，Boey的特殊能力使Wayne对她刮目相看，两人对彼此有了特别的感觉。研究的过程中错漏百出，产品还没有研究成功，众人之间的关系已经十分复杂。时限将到，他们还是顺利研究出一个可以解读婴儿语言的“绝世好B”，Johnny与Wayne也知道了自己的最爱。©豆瓣', '刘青云', '梁柏坚', 5.8, 29450, 'tt0340047', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p482187455.jpg', 3.7, 21, 61.4, 11.2, 2.8, '0.172232,-0.154092,-0.531993,0.671465,-0.056252,-0.089234,0.391467,-0.055416,-0.687468,-0.334055,-0.043204,0.673958,-0.273333,-0.168658,0.095863,-0.208327,-0.167296,-0.794233,-0.073671,-0.293147,-0.446913,-0.703036,-0.412634,-0.175306,-0.211590,-0.435152,0.463670,-0.085074,-0.310561,0.318803,0.176037,0.119704,0.197344,0.583983,-0.280892,-0.251621,0.080838,0.167313,-0.388136,0.176894,0.309536,-0.162104,0.059626,0.113865,0.035589,0.540605,0.553411,-0.206024,-0.518947,-0.064437,0.329577,0.027650,0.067828,0.066467,0.294409,0.286311,0.157910,0.294215,-0.422593,0.074565,0.039995,-0.175580,-1.258381,-0.115243,0.320059,0.044522,-0.509466,0.294504,-0.133486,-0.206595,0.214615,-0.257875,0.346595,0.653797,0.534027,0.426500,-0.047790,0.039121,-0.333885,0.290782,0.257626,-0.002283,-0.173593,0.738869,-0.262266,-0.766329,-0.151182,-0.214055,-0.089611,0.041486,0.012575,0.345454,-0.237080,-0.139637,-0.682815,-0.056466,-0.072642,-0.168444,-0.048205,-0.558377,0.368837,-0.702200,-0.271818,-0.498515,-0.605495,0.001792,0.276148,-0.314610,0.876525,-1.123010,0.002951,0.312842,0.332104,-0.790794,0.602812,0.068790,0.004592,-0.553583,-0.305753,-0.170109,-0.244864,0.333032,0.074177,0.670531,0.296940,-0.527038,-0.412536,0.213817', '1793491', '26678784', '4301278', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299042', '人生', '剧情', '大西北粗粝广袤的土地上，仪表堂堂的高加林（周里京 饰）是这片黄土地上极其惹眼而又独树一帜的存在。他是镇上的老师，虽然兢兢业业教了三年书，但大队书记的儿子高中刚毕业就顶了他的位置，让加林愤愤不平。自古民不与官斗，在爹娘苦苦哀求之下，加林打消了告状的念头，心怀抑郁和愤懑的青年无奈回到田里耕作。在此期间，多亏了纯朴而美丽的姑娘刘巧珍（吴玉芳 饰）给了他安慰。爱情的滋润让加林重新找到前进的方向，他打理田间地头，业余时间从事写作。而就在此时，加林却意外得到了一个可以去县里工作的机会。人生和爱情面前，青年不得不做出抉择……本片根据路遥的同名小说改编。©豆瓣', '周里京', '吴天明', 8.4, 8483, 'tt0087992', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2637656503.jpg', 0.3, 0.7, 12.6, 49.4, 37, '0.117511,0.064420,-0.513557,0.628036,-0.191782,-0.405428,0.519655,0.265908,-0.535535,0.108845,0.122790,0.563671,0.116122,0.332334,0.173740,0.210531,-0.377971,-0.513938,0.082412,-0.135013,-0.226154,-0.455993,-0.351554,-0.127222,-0.109093,-0.159188,0.548336,0.107132,-0.180929,0.579654,0.022591,0.076442,0.154599,0.356223,-0.366024,0.153094,-0.050157,0.070054,-0.135481,0.111400,0.169574,-0.236600,-0.319830,0.167214,0.132685,0.462284,0.606145,0.168138,-0.286191,-0.026880,0.372613,-0.177336,0.001705,0.120973,0.155875,0.013198,0.271389,0.143653,-0.189575,-0.136214,-0.001220,-0.179305,-0.543925,0.005957,0.037787,0.145849,-0.906595,0.521134,0.010579,-0.340186,0.027082,-0.678004,0.195417,0.023169,0.198763,0.486717,-0.187655,-0.145647,-0.293547,0.461423,0.397834,0.135189,-0.121502,0.214933,-0.268524,-0.267531,0.233502,-0.268028,-0.490082,-0.226549,0.132257,0.030011,-0.192803,0.018979,-0.436961,0.198090,-0.269432,-0.131041,-0.026441,-0.444405,-0.156059,-0.132228,-0.074872,-0.284583,-0.331523,0.011621,0.178792,-0.311598,0.760093,-0.635432,0.133758,0.506373,0.237049,-0.372728,0.645487,0.163404,0.111431,-0.162126,0.119711,0.010678,-0.197225,0.506955,0.012902,0.379665,-0.205255,-0.374938,-0.492836,0.567822', '26958479', '21360412', '25731805', '4301274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299048', '特警新人类', '喜剧', '日本恐怖分子赤虎把香港作为亚太区的走私军火的重要基地，他们还使用了高端科技，蓄意挑战特区政府，政府束手无策，继而严重威胁到全港市民的安全。警官陈聪（曾志伟 饰）为了证明自己的能力，到警校挑选了Jack（谢霆锋 饰）、Match（冯德伦 饰）、异型（李灿森 饰）与千年虫（叶佩雯 饰）四名叛逆少年组成一支特警新人类，务求抓拿赤虎。特警在首次行动渗入了黑帮杰少的组织，杰少正是赤虎的接头人。特警渐渐得到杰少的信任，却又被警方视为杰少的同谋，腹背受敌。在众人奋力逃生之时，也发现了赤虎的重大阴谋……©豆瓣', '谢霆锋', '陈木胜', 6.4, 30956, 'tt0206334', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2028321791.jpg', 1.6, 11.6, 59.3, 21, 6.5, '0.237050,0.022669,-0.689317,0.442267,-0.099641,0.004290,0.472591,0.059410,-0.573457,0.044449,0.647867,0.523743,0.210834,-0.151888,0.178186,-0.141455,-0.102663,-0.726903,-0.114654,-0.224228,-0.351050,-0.305307,-0.529681,-0.417855,0.031008,-0.314505,0.613461,0.093170,-0.314234,0.267607,0.239726,0.382441,-0.263531,0.347832,-0.104452,-0.132093,0.420024,-0.405746,-0.345750,0.070784,-0.188623,-0.455949,-0.123420,0.413209,-0.147022,0.579158,0.665329,-0.339363,-0.088495,-0.189070,0.297117,-0.460855,-0.063497,-0.189960,0.553215,0.148562,-0.077629,0.169779,-0.023496,0.138713,-0.032685,0.150091,-0.802595,-0.007302,0.090729,0.143264,-0.397067,0.440513,-0.260930,0.110830,0.219799,-0.401157,0.090190,0.293956,0.139602,0.036615,-0.032451,0.165972,-0.588101,0.295605,0.421471,-0.221880,-0.125265,-0.073264,-0.018060,-0.666836,-0.149142,-0.324005,-0.131869,-0.234438,0.627475,-0.156619,-0.014991,-0.007113,-0.674514,0.001653,-0.123455,-0.119449,-0.191565,-0.168082,0.217739,-0.782968,-0.076831,-0.263146,-0.168927,0.319014,0.266917,-0.038840,0.788497,-0.736594,-0.199513,0.773929,0.290353,-0.703746,0.140409,-0.260471,0.021556,-0.219682,-0.412597,-0.222976,0.396206,0.541849,0.307491,0.353883,-0.074022,-0.342062,-0.027557,-0.161352', '1292829', '26921827', '1309112', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299054', '香草的天空', '爱情', '大卫·阿姆斯（汤姆·克鲁斯 Tom Cruise 饰）可以称为上帝的完美杰作：他家境优渥、事业有成、仪表堂堂、风度翩翩，无数性感迷人的女性都为其柔情蜜语所倾倒。而大卫自是不愿浪费这天赐的条件，他四处出击，以猎艳为乐，甚至连好友的女朋友索菲娅（佩内洛普·克鲁兹 Penélope Cruz 饰）都不放过。不过，大卫终要为自己的花心付出代价，在和前女友茱丽（卡梅伦·迪雅兹 Cameron Diaz 饰）乘车出行之时，茱丽开车撞向大树，企图与之同归于尽。这场车祸使大卫的人生跌入谷底，而更为诡异的却仍在前面等待着他……本片荣获2002年美国科幻恐怖电影学院最佳男主角奖（汤姆·克鲁斯）、2001年波士顿影评人协会最佳女配角奖（Cameron Diaz）、2002年芝加哥影评人协会最佳女配角奖。©豆瓣', '汤姆·克鲁斯', '卡梅伦·克罗', 7.5, 64095, 'tt0259711', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p541484436.jpg', 0.6, 3.9, 33.9, 44.3, 17.3, '-0.158769,-0.236629,-0.547250,0.609409,-0.171504,-0.447870,0.639829,0.083139,-0.242329,-0.070740,0.295399,0.894986,-0.329080,0.066842,0.495386,0.132875,-0.260523,-0.677537,-0.271246,-0.194275,0.126191,-0.287816,-0.427149,0.071638,-0.202099,-0.417808,0.555792,-0.436077,-0.097689,0.500300,0.658155,0.418438,0.000349,0.101655,0.036529,-0.068697,0.177959,-0.219480,-0.515833,0.342116,-0.032639,-0.380002,-0.238052,0.034337,-0.229247,0.127585,0.789136,-0.036016,-0.049877,-0.352380,0.623897,-0.224998,0.192701,0.339405,0.191450,-0.307461,0.383285,0.168323,0.128550,-0.037769,0.372579,-0.051957,-0.614474,0.194799,0.089426,0.077012,-0.366243,0.351725,-0.132535,0.125874,0.047645,-0.070233,-0.026025,0.011324,0.210699,-0.103033,-0.105666,0.050493,-0.169691,0.470213,0.444093,0.463138,-0.346902,0.372117,-0.235857,-0.464951,0.054872,-0.208480,-0.909631,-0.005041,0.436242,0.047923,0.339239,0.266112,-0.419807,-0.087298,-0.101106,0.045671,-0.121139,-0.096869,-0.075793,-0.830350,-0.072617,-0.344613,-0.241901,-0.068477,0.298811,-0.116798,0.549273,-0.405881,0.203982,0.695542,0.055375,-0.409326,0.819239,-0.117984,0.056706,-0.045325,-0.481737,0.334619,-0.044992,0.079591,-0.166517,0.307623,-0.067577,-0.353780,-0.466855,0.491021', '34795703', '1484091', '1829654', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299057', '义胆群英', '动作', '某社团老大乘车夜归途中遭人枪杀，凶手不知去向。该社团围绕继承人问题展开争论，为避免出现分裂与争执，社团元老马公（午马 饰）与王律师（黄霑 饰）商议，委托老大之名指定正直勤奋的阿修（李修贤 饰）为帮会继承人。另一方面，与阿修同期的阿泰（陈观泰 饰）某日接到老大司机的电话，称阿修为刺杀老大的幕后指示。阿泰的小弟小奇（周星驰 饰）听到录音后恼羞成怒，发誓要阿修付出代价。一场裹挟了黑帮阴谋仇杀和兄弟情谊的战争随即展开……©豆瓣', '姜大卫', '吴宇森', 7, 5572, 'tt0094351', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2348750430.jpg', 0.8, 5.8, 48.3, 32, 13.1, '-0.065430,-0.117989,-0.132463,0.280948,0.310536,-0.144141,0.253437,0.431299,-0.432754,-0.351671,0.270161,0.435786,-0.066307,-0.139414,0.605442,-0.437553,-0.259286,-0.684829,-0.148022,-0.052466,0.014888,-0.425260,0.235669,-0.295179,0.020773,-0.054204,0.273070,-0.187355,-0.136999,0.550394,0.551632,0.371579,-0.461535,-0.048694,0.315136,-0.077009,0.218026,0.165580,-0.726569,-0.035733,-0.127145,-0.082982,-0.081431,-0.243113,0.072008,0.426109,0.345923,0.015471,-0.075507,-0.689062,0.169115,-0.392870,0.057314,-0.072559,0.628706,0.342552,0.379505,0.663389,0.093528,-0.271750,-0.104351,-0.189222,-0.624531,-0.010592,0.342480,0.044795,-0.357142,0.143012,-0.380570,0.012149,0.270672,0.015499,0.208793,0.385118,0.487474,-0.007166,0.125597,0.142451,-0.140604,0.228662,0.552934,-0.193456,0.466548,-0.336219,0.553757,-0.266489,0.086812,0.060650,-0.250767,-0.059500,0.255884,-0.272976,0.223215,0.257542,-0.449868,-0.489666,-0.174432,0.039600,0.130363,-0.456873,0.075450,-0.493527,-0.048336,0.142799,0.255691,0.281088,0.197474,0.124063,0.528266,-0.898691,-0.048633,0.210938,0.289903,-0.804164,0.287766,0.344253,0.186197,-0.714669,-0.004626,-0.356403,0.351244,0.158305,-0.008907,-0.156763,0.125125,-0.371276,-0.082595,-0.374060', '1293265', '26827040', '1307914', '1482541');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299059', '倚天屠龙记之魔教教主', '动作', '张翠山（吴镇宇 饰）携妻及子张无忌（李连杰 饰）从孤岛出发赶去给其师父贺百岁大寿的途中，被人暗算，张无忌中寒冰掌。在武当山，张翠山和妻子被各大门派逼迫致死，张无忌也不再能练习武功，只能靠张三丰每日所输真气得以残活。张三丰的举动引来宋青书（邹兆龙 饰）的妒忌，他联合了峨眉女弟子周芷若（黎姿 饰）共同对付张无 忌。明教圣女小昭（邱淑贞 饰）令张无忌改变命运，使其先在断崖上遇到高人治好体内寒冰毒、学会九成“九阳神功”，又在明教禁地练得“乾坤大挪移心法”。得知蒙古郡主赵敏（张敏 饰）设计令江湖六大派围攻光明顶想歼灭明教时，张无忌决意为拯救明教赴汤蹈火。©豆瓣', '李连杰', '王晶', 7.9, 174783, 'tt0108624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2042952696.jpg', 0.3, 2.1, 25.7, 47.3, 24.5, '-0.173950,-0.105115,-0.504239,0.568741,0.056753,-0.149857,-0.138352,0.164400,-0.494492,-0.360236,0.263354,0.582356,-0.018873,0.142237,-0.123437,-0.073504,0.345387,-0.566640,-0.139854,-0.253507,-0.221252,0.002404,0.327263,-0.134238,-0.119582,-0.441171,0.300608,0.267427,-0.346929,0.180039,0.212137,0.069462,-0.329487,0.195725,-0.236739,0.060710,-0.267282,-0.083711,-0.115227,0.422984,-0.182758,-0.423432,-0.209228,0.082610,-0.438043,0.478611,0.479329,0.108322,0.131001,-0.242041,-0.102360,0.043655,-0.107280,-0.006554,0.415059,-0.009544,0.185056,0.234701,-0.143022,0.005660,0.025633,0.014747,-0.305417,0.091492,0.645085,-0.396067,-0.382177,0.203629,-0.432719,0.088613,-0.339021,-0.417925,-0.269722,0.260854,0.246328,-0.148721,-0.018362,-0.413717,-0.480336,0.309925,0.499419,-0.306751,0.612998,-0.027048,0.385721,-0.108976,0.085303,-0.594802,0.122454,0.044977,0.688759,-0.145986,0.141528,0.243754,-0.137016,-0.192980,-0.313273,0.374724,-0.219139,0.031296,0.318335,-0.741928,-0.029675,0.082397,-0.028686,-0.206286,0.382580,-0.072963,0.861759,-0.407976,0.206441,-0.048647,-0.006908,-0.735385,0.413109,-0.004356,0.192792,-0.144287,-0.198587,0.281449,0.103807,0.515542,0.312858,0.288419,-0.094521,0.015335,-0.517879,-0.130784', '27602116', '1297517', '25863940', '1401205');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299062', '坏孩子的天空', '剧情', '小马（金子贤饰）和新志（安藤政信饰）是一对好朋友，他们喜欢在操场上一起踩辆单车。作为“坏学生”的他们，总是跷课闲逛、捉弄老师、欺负同学等等。有一次小马被人揍打，对方是一个经常被他欺负的学生找来的拳击手。受到打击的小马开始学习拳击，想要争口气。新志也跟着学，没想到他却更有练拳的天分。后来小马放弃学拳，加入了黑帮当小弟。而新志却发奋练习，并有所收获。等待他们的又将是什么样的未来呢？几年后，小马和新志在街头巧遇。几年间发生的事情让他们改变了不少，又似乎什么都没变，两个坏孩子再度回到昔日的校园。©豆瓣', '金子贤', '北野武', 8.5, 96428, 'tt0116767', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2197513152.jpg', 0.1, 0.7, 11, 47.8, 40.3, '0.307095,-0.479069,-0.443095,0.415648,-0.311628,-0.399537,0.449853,-0.097179,-0.558894,-0.303554,0.030504,0.625951,-0.324584,0.293212,0.047389,-0.150166,-0.105905,-0.735667,0.391140,0.042812,-0.215010,-0.245479,-0.187028,0.020454,-0.072121,-0.085777,0.292982,-0.040362,-0.254914,0.652524,0.326463,-0.172540,0.180857,0.358355,-0.411769,0.067047,-0.055024,0.180450,0.163606,-0.109231,0.128582,-0.298134,-0.258804,-0.190916,0.249549,0.118646,0.550739,0.171311,-0.312381,-0.042466,0.227797,-0.130232,-0.114882,-0.037331,0.408370,-0.088833,0.191156,0.108820,0.117094,0.118918,-0.058121,0.067351,-0.391083,0.125678,0.144309,-0.120730,-0.871964,0.476389,0.353099,-0.066932,0.106456,-0.169353,0.114892,0.530604,0.246384,0.260897,-0.080028,0.052692,-0.491447,0.037827,0.939134,-0.194435,0.023403,0.153000,-0.027691,-0.118292,0.135717,-0.182777,-0.408809,0.185089,0.129001,-0.264774,-0.323600,-0.049844,-0.430260,0.216661,-0.036822,-0.102842,-0.009893,-0.586461,-0.078416,-0.508624,0.323091,-0.426721,-0.264226,0.192273,0.038682,-0.454102,0.716269,-1.036291,0.189416,0.418460,0.292337,-0.696402,0.679086,0.031129,-0.142365,-0.040266,-0.066505,-0.306752,0.175420,0.261218,0.042046,0.430637,0.224978,-0.264967,-0.131306,0.481045', '35030151', '1419416', '1877596', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299067', '一诺千金', '剧情', '十五岁的伊戈成长的世界，奸恶无大碍、台底交易是正常秩序。一天，父亲雇用的西非籍非法劳工堕楼垂危；父亲为免官非让他流血致死，且设法隐瞒真相。雇工临死前，伊戈许下承诺要照顾他的孤儿寡妇。自此，他无忧的世界崩溃，对父纯粹的效忠不再，罪疚感正义感又阳光又阴霾。达登内兄弟以欧洲当前时弊为剧情框架：移民潮、多种族杂居、非法劳工等。一段简单的道德醒觉，透过强烈的质感、细节及流畅的手摇摄影，把观众领进比利时边境的边缘人世界，重新焕发出写实主义的光辉。', '杰瑞米·雷乃', '让-皮埃尔·达内', 8.4, 6947, 'tt0117398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1651159323.jpg', 0.1, 0.6, 11.4, 55.9, 32, '-0.008689,0.351418,-0.491366,0.324793,-0.205115,-0.052027,0.546162,0.176517,-0.422513,0.026038,0.171256,0.479491,0.067218,0.021597,0.111271,0.084853,-0.225494,-0.640418,-0.058598,-0.146893,-0.201812,-0.475950,-0.104935,-0.428227,-0.292045,-0.637307,0.613538,0.329223,-0.109114,-0.029012,-0.167050,0.020274,0.008989,0.295427,0.001996,-0.291901,-0.265696,-0.114943,-0.489379,-0.162877,-0.152796,-0.051924,-0.064031,0.103483,-0.399570,0.348544,0.740630,-0.125426,-0.167506,-0.459104,0.644822,-0.137066,0.033878,-0.028022,0.060519,0.218998,-0.133967,0.510011,-0.094034,-0.112180,0.005733,-0.107989,-0.713904,-0.237653,0.127776,0.160334,-0.173694,0.411835,-0.334731,-0.195005,-0.038842,-0.074855,-0.014925,0.183439,0.361900,0.395471,-0.000508,0.141810,-0.143963,0.323091,0.625676,-0.058291,-0.395020,0.187591,-0.593787,-0.402067,0.187290,-0.310735,-0.195833,-0.056694,0.143012,-0.012630,-0.238851,0.344363,-0.494529,0.041427,-0.353577,-0.232294,-0.156389,-0.145845,0.080159,-0.186565,-0.209304,-0.012042,-0.001358,-0.009636,0.385342,-0.135124,0.659528,-0.386150,0.349003,0.620017,0.552312,-0.563803,0.395057,0.032754,0.099240,-0.267287,0.016582,0.409568,-0.030686,0.305365,-0.092459,-0.028981,-0.021153,0.127120,-0.068588,0.358239', '26678784', '26315728', '26759820', '25947154');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299080', '后窗', '悬疑', '摄影师杰弗里斯（詹姆斯·斯图尔特 饰）因站在赛车道中间拍摄，断了左腿，只得在家静养七周。除了保险公司的护士斯特拉（西尔玛·里特 饰）和女友丽莎·卡罗尔·弗里蒙特（格雷斯·凯利 饰）每日前来照料，百无聊赖的杰弗里斯只能在窗前闲看邻居们的日常生活以打发时间。对面公寓的二楼住着人造珠宝推销员拉尔斯·托瓦尔德（雷蒙德·伯尔 饰）及妻子安娜（艾琳·温斯顿 饰），夫妻之间争吵不断。一个雨夜，杰弗里斯看到拉尔斯提着箱子外出数次。次日，杰弗里斯又看到拉尔斯用报纸包裹一把锯和一把刀。杰弗里斯起了疑心，他怀疑拉尔斯杀害了安娜并分尸抛弃。然而，杰弗里斯并未目击案发过程，也未见到尸体。那么真相究竟如何呢？杰弗里斯的推测只是他的臆想吗？为了证实他的推测，杰弗里斯要如何寻找证据呢？©豆瓣', '詹姆斯·斯图尔特', '阿尔弗雷德·希区柯克', 8.7, 176313, 'tt0047396', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p998913501.jpg', 0.2, 0.6, 9.6, 44.7, 45, '0.105509,-0.124743,-0.356111,0.273025,0.017359,-0.509036,0.757684,0.325274,-0.203756,-0.450790,0.233423,0.444577,-0.054215,0.197834,0.281091,0.131633,-0.698595,-0.587151,0.220186,-0.092496,-0.402164,-0.715943,-0.103064,-0.233975,0.124779,-0.278512,-0.036464,-0.483756,0.175572,0.341800,0.317620,0.182038,-0.157995,0.193283,-0.066322,0.010325,0.126094,-0.091604,-0.352011,0.190413,0.139875,-0.089449,-0.329894,-0.006895,0.108487,0.373208,0.499341,-0.251804,0.289875,0.004977,0.180616,0.098663,0.376837,0.036029,0.227815,-0.032243,0.174909,0.009421,-0.283051,0.070864,0.363417,0.094525,-0.361393,0.161861,-0.166200,0.312030,-0.514806,0.216800,-0.370401,0.093744,0.075028,-0.453457,-0.043847,0.326645,0.067610,0.091565,-0.164051,-0.305018,-0.691100,0.003024,-0.105667,-0.018808,0.221826,0.293088,-0.054074,-0.051537,0.011832,0.220228,-0.429599,-0.204129,0.405056,0.090504,-0.209656,0.259769,-0.214303,-0.026773,-0.429129,-0.183953,-0.053280,-0.274138,-0.053690,-0.742539,0.003560,0.071499,-0.250222,-0.203125,0.069228,-0.064574,0.089491,-0.338950,0.210044,0.461232,0.158025,0.117284,0.331557,0.139213,0.294780,-0.011454,-0.234926,0.221808,0.443961,0.232087,0.266479,0.425442,0.196328,-0.186034,-0.317939,0.300593', '26915921', '1301345', '3183490', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299085', '一刀倾城', '武侠', '故事发生在清朝末年，西方列强的洋枪洋炮轰开了东方睡狮闭锁许久的大门，慈禧太后只手遮天，无心国运。华夏大地生灵涂炭，民不聊生，革命的火种酝酿蓬勃，即将成为一场足以颠覆王朝的燎原大火。出身于刘永福黑旗军的大刀队长王五（杨凡 饰）怀有一身高超武艺，然而在刺杀日军司令的行动中他遭遇惨痛的败绩，手下们相继阵亡，愧对部下的他跳崖自杀，侥幸生还后则隐居在东北乡野。在命运的安排下，王五结识了谭嗣同（狄龙 饰）和袁世凯（赵长军 饰），三人情投意合，携手上京闯荡。创立了强武学会的王五邂逅了美人颜夕（关之琳 饰），而对方却是奕亲王（黄锦江 饰）的爱妃。国家局势动荡不安，王五和谭嗣同、袁世凯也各自走上了不同的人生之路……©豆瓣', '狄龙', '洪金宝', 8, 7363, 'tt0108622', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2350760600.jpg', 0.4, 2.6, 22.5, 44.5, 30, '-0.043906,0.030667,-0.697324,0.450201,0.129163,-0.103564,0.414579,0.217321,-0.614343,-0.071457,0.558584,0.614255,0.008790,-0.001400,0.285240,-0.283546,-0.164374,-0.870457,-0.105506,-0.026478,-0.136798,-0.212529,-0.301208,-0.157055,-0.251259,-0.118469,0.613687,0.284167,-0.284638,0.565819,0.239660,0.181783,-0.175843,0.437071,-0.206253,0.166524,-0.092599,-0.064748,-0.532675,-0.035726,-0.208505,-0.560215,-0.380377,0.084853,-0.173426,0.144331,0.423014,-0.325441,0.232167,-0.340136,0.267694,-0.200669,-0.240343,0.136609,0.398107,0.122641,-0.031330,0.311287,0.185416,-0.204709,0.012872,0.046265,-0.388319,-0.012976,0.188642,0.173366,-0.492102,0.655818,-0.031159,-0.065366,-0.077394,-0.303859,0.146450,0.475600,0.130450,0.217335,-0.134730,-0.125194,-0.517793,0.422083,0.746609,-0.026602,-0.208242,-0.217097,0.107595,-0.313388,-0.118945,-0.247669,-0.287218,-0.158781,0.536681,-0.141130,0.062876,0.466539,-0.401520,0.032513,-0.248178,0.028801,0.017224,-0.011485,-0.037977,-0.441299,-0.360322,-0.544301,-0.308933,0.153147,0.220845,-0.038672,0.659297,-0.593665,-0.051103,-0.011186,0.133819,-0.542191,0.474894,0.023286,0.116645,0.043856,0.018474,0.322426,-0.245323,0.361948,0.028931,0.306675,-0.230778,-0.083151,-0.303448,0.165514', '3230460', '4202326', '25721544', '1480318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299092', '回到未来2', '喜剧', '马丁（Michael J. Fox 饰）才回到现实世界与女友团聚，布朗博士（Christopher Lloyd 饰）就心急火燎地把他们带到了30年后的未来世界，原来这一次是马丁未来的两个孩子因参与抢劫锒铛入狱，博士要携马丁一起阻止悲剧发生。周旋一番后，两个孩子被成功挽救，但三人回到现实世界后，却发现周遭发生了天翻地覆的变化，世界被贝夫（Thomas F. Wilson饰）所控制，马丁的父亲乔治惨死，母亲洛莲（Lea Thompson 饰）竟然成了贝夫的妻子！这一切都是因为时光机器的秘密不慎被未来的老贝夫识破，他偷偷回去捣鬼，竟因此使得整个世界都在他的掌握下！马丁与博士再次踏上时光穿梭的征途，希望将世界扳回正轨。©豆瓣', '迈克尔·J·福克斯', '罗伯特·泽米吉斯', 8.5, 103342, 'tt0096874', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p475857703.jpg', 0.1, 0.7, 12.7, 46.5, 39.9, '-0.088760,0.557060,-0.807108,0.223271,-0.248522,-0.377692,0.707082,-0.040332,-0.568406,-0.231036,0.074879,0.654815,-0.444930,0.251886,0.521981,0.053517,-0.377916,-0.989523,0.091161,-0.180172,-0.342998,-0.387106,-0.271989,-0.157152,0.005652,-0.504881,0.667948,0.264313,0.049156,0.108721,-0.033774,0.243088,-0.265446,0.429001,-0.160993,0.434844,0.114429,0.190069,-0.642661,0.190769,0.067117,0.031178,-0.024738,0.094161,-0.203630,-0.228510,0.976494,-0.387570,-0.150111,-0.197653,0.396658,-0.343195,-0.238773,-0.089675,0.253056,-0.005984,-0.058654,0.523920,-0.163408,-0.062062,0.238258,0.070660,-0.696999,0.270521,0.142027,-0.038559,-0.639542,0.146102,-0.055439,-0.011739,-0.234171,-0.250373,0.446998,0.670347,0.872867,0.483467,-0.198874,0.144532,-0.438351,-0.087255,0.788174,-0.410387,-0.213497,0.385619,-0.035671,0.055388,-0.029127,-0.132359,-0.341061,0.144970,0.380373,0.190499,-0.242717,0.455533,-0.466942,-0.255090,-0.650894,-0.310878,0.258054,-0.597191,-0.120650,-0.359103,-0.027618,-0.033707,-0.310643,-0.056605,-0.008295,-0.316481,0.501105,-0.468121,0.508432,0.604529,0.168592,-0.517846,0.661478,-0.100894,0.429121,-0.469009,0.215935,0.380545,0.176070,0.388263,0.007539,0.246339,-0.093647,-0.053208,-0.322390,0.494634', '10581450', '30345227', '25978126', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299107', '恐怖角', '惊悚', '迈克斯（罗伯特•德尼罗 Robert De Niro 饰）因为强奸而遭到起诉，他找来了律师萨姆（尼克·诺尔蒂 Nick Nolte 饰）为自己辩护；他有所不知的是，萨姆是一个女权主义者。出于义愤，萨姆在辩护是故意隐瞒了一项对迈克斯有利的证据，最终导致了迈克斯被多判了6年。本来不懂法律的迈克斯在狱中通过自学法律发现了萨姆对他的背叛，发誓一定要找萨姆报仇。一晃14年过去了，迈克斯刑满获释了，他开始展开他的复仇计划。他首先在萨姆家附近出现，引起他们的恐慌；随后，萨姆派来对付他的人被他打得落花流水；他之后潜入萨姆家杀死了保镖和厨娘。惊惶不安的萨姆一家逃到了一个叫“恐怖角”的地方，迈克斯也尾随而至……©豆瓣', '罗伯特·德尼罗', '马丁·斯科塞斯', 7.4, 12820, 'tt0101540', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1280557643.jpg', 0.7, 3.4, 34.5, 47.8, 13.7, '0.567710,-0.152617,-0.848661,0.578717,-0.218226,-0.437203,0.476832,-0.051508,-0.294242,-0.280281,0.283067,0.847730,-0.273653,-0.093465,0.126373,0.119928,-0.169632,-0.665731,0.015324,-0.525318,-0.432320,-0.692290,0.027059,-0.564822,-0.165547,-0.314212,0.174243,-0.148382,0.017404,0.357675,0.123329,0.402686,0.698559,0.358712,0.206083,0.265768,0.119442,-0.517891,-0.095936,0.441862,0.341995,-0.257129,-0.189315,0.343384,-0.103407,0.663958,0.421183,-0.320123,0.046507,-0.130017,0.308232,-0.773813,0.207817,0.222242,0.434233,-0.427093,-0.321518,0.389719,-0.578956,-0.197247,0.107062,-0.167774,-0.684202,-0.032582,-0.204054,0.155422,-0.487131,0.209544,-0.363169,0.193912,0.096352,-0.332596,0.109704,0.271253,0.273956,0.251809,0.186327,-0.093348,-0.444822,-0.041720,0.781311,-0.020393,0.008444,0.064531,-0.283706,-0.246311,-0.083776,-0.214975,-0.462646,-0.204295,0.608587,-0.212474,-0.252970,0.165516,-0.473583,-0.436862,-0.549597,-0.075258,-0.210486,-0.482021,-0.048267,-0.289448,-0.147494,-0.163816,-0.285877,0.063182,-0.198788,-0.305936,0.446502,-0.845201,0.104103,0.887203,0.459692,-0.528797,0.680365,-0.079338,-0.075683,-0.021426,0.083006,0.262395,0.546446,0.349173,0.408345,0.280698,0.385349,-0.099789,-0.141270,0.239838', '1309069', '25908042', '1295733', '1308762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299111', '鬼玩人3：魔界英豪', '喜剧', '美国青年艾许（布鲁斯•坎贝尔 Bruce Campbell 饰）在和女友琳达（布丽切特•方达 Bridget Fonda 饰）度假时，偶然发现一本《死亡之书》。书中记载各种神秘的丧葬风俗以及招魂仪式，更为诡异恐怖的是，这本不应该存在于人间的书具有十分强大和邪恶的魔力。为与之斗争，艾许失去了女友和自己的右手，但最后还是体力不支，被《死亡之书》带到600年前的中世纪。他奇怪的穿着一度被骑士们当作间谍抓起来，经过一番波折，艾许决定帮国王打败《死亡之书》幻化出来的怪兽，这也是他回到现代社会的唯一办法……本片荣获1993年布鲁塞尔奇幻电影节金鸦奖、1993年葡萄牙奇幻电影节影评人奖、1994年美国科幻恐怖电影学院土星奖最佳恐怖片。©豆瓣', '布鲁斯·坎贝尔', '山姆·雷米', 7, 6806, 'tt0106308', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2177138783.jpg', 2.1, 8.2, 43, 32.7, 13.9, '-0.046506,-0.112439,-0.527689,0.658867,0.309718,0.036864,0.782798,-0.230569,-0.458381,-0.673317,0.087651,0.941634,-0.347183,0.119374,0.562774,0.102616,-0.260886,-0.687211,-0.092012,-0.082539,-0.167013,-0.136770,-0.531882,0.053377,-0.238620,-0.532941,0.700041,0.163305,-0.298446,0.392065,0.208914,0.551084,-0.190177,0.136501,-0.199381,-0.116634,0.011749,0.031013,-0.268330,0.161745,0.169449,-0.242938,-0.386527,0.357940,0.076001,0.008012,0.678409,-0.266237,-0.131169,-0.230724,0.646826,-0.143808,-0.396545,-0.004352,0.134534,0.124643,0.265720,0.068942,0.307029,0.155797,0.192634,-0.310411,-0.631200,0.044468,0.035406,0.216318,-0.282131,0.314816,-0.170585,0.224163,-0.233497,-0.386443,0.252037,0.107685,0.295004,0.427568,0.126554,-0.114127,-0.496778,0.406473,0.280857,0.064388,-0.449734,0.276486,-0.218916,-0.775855,-0.039174,-0.413672,-0.299847,0.331324,0.483211,0.136506,-0.008836,0.361424,-1.056298,-0.054391,0.036467,-0.234438,0.011543,-0.210417,-0.068971,-0.654442,-0.198823,-0.208408,-0.336951,-0.158706,0.124563,-0.359990,0.742463,-0.583561,0.523082,0.460967,0.135614,-0.334726,0.456702,-0.112393,0.032846,-0.032414,-0.159782,0.202497,0.007365,0.390011,-0.095111,0.188444,0.238977,-0.499528,-0.456432,0.491032', '26290398', '1294434', '25837262', '1296769');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299112', '梦', '剧情', '本片是日本电影天皇黑泽明对梦的勾画，全片共有八个梦境，分别是：太阳雨、桃园、风雪、隧道、乌鸦、红色富士山、垂泪的魔鬼和水车之村。这八个梦几乎贯穿了人类生活的所有主题，战争与和平、社会与人生。在不同的梦境里有着不同的场景，配合不同的色彩，把人类所面对的所有主题一一呈现。', '寺尾聪', '黑泽明', 8.7, 51590, 'tt0100998', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2215880880.jpg', 0.3, 1.1, 10.9, 38.6, 49, '0.076603,-0.059447,-0.446112,0.887675,0.269484,-0.072715,1.162156,0.099877,-0.372864,-0.265995,0.337648,0.658374,-0.299933,0.167475,0.130579,-0.227362,-0.345652,-0.784901,-0.759843,0.005084,-0.230188,-0.450241,-0.097179,-0.029720,-0.012078,-0.161730,1.028887,0.088424,-0.300034,0.207695,0.241017,0.314059,-0.658015,-0.083285,-0.417606,-0.283918,-0.262366,0.212355,-0.783693,-0.012735,-0.575707,0.238186,-0.091041,0.343471,-0.430323,0.041882,1.045961,-0.632310,-0.066709,-0.104259,0.477859,-0.267576,-0.516410,0.124523,0.188273,0.055212,0.250284,-0.037565,0.217986,0.008248,-0.148706,-0.306320,-1.029954,-0.327440,0.254012,0.371722,-0.221120,0.535547,0.461939,-0.265273,0.331049,0.110669,0.353177,-0.015243,0.858517,0.661317,-0.021991,-0.288588,-0.503505,0.265296,0.630598,-0.024114,-0.643785,0.832914,-0.513842,-0.422894,-0.517738,0.085577,-0.136376,0.363263,-0.107184,-0.057872,-0.363394,0.623936,-1.149989,0.136002,-0.022579,-0.677439,0.056719,-0.468073,-0.215363,-0.639372,-0.449981,-0.661516,-0.424092,-0.055203,0.218956,0.248052,0.675182,-0.896632,0.220764,0.255283,-0.135168,-0.161550,0.854233,0.186922,-0.037635,-0.377182,0.212421,0.292665,0.096456,0.370673,-0.496915,0.437820,-0.259541,0.478638,-0.912285,0.582860', '1457127', '26290398', '1467779', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299120', 'A计划续集', '喜剧', '清朝末年的香港，在上、中、西环有“镇三环”之称的帮办暗中勾结西环恶霸勾心虎，西环治安一时乌烟瘴气。警官马如龙（成龙）奉命接管西环后，迅速将勾心虎拘捕人狱，招来“镇三环”的怨恨。彼时内地革命风云翻涌，革命党人来港宣传，并计划营救被捕同志。为将革命党人一网打尽，清廷派遣密使联络镇三环，马如龙结识白影红、莹莹、珊珊等革命党人（张曼玉、关之琳、刘嘉玲等）后也被卷入斗争漩涡，而同时，一群四肢发达头脑简单的海盗正在伺机向马如龙报仇。©豆瓣', '成龙', '成龙', 7.8, 68309, 'tt0092501', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204526758.jpg', 0.2, 1.3, 26.5, 50.7, 21.3, '0.288351,0.046320,-0.374651,0.315317,0.593698,0.018255,0.170493,0.434919,-0.558445,-0.016576,0.103398,0.338635,-0.075593,-0.130606,0.170198,-0.159072,-0.229580,-0.725955,-0.320157,-0.093931,0.164184,-0.343189,-0.089387,0.055120,-0.045453,-0.047766,0.516229,0.358452,-0.000368,0.625159,0.312068,0.290866,-0.559303,0.302505,0.069476,-0.009712,0.266117,-0.426463,-0.342288,0.110503,-0.162122,-0.381698,0.204944,-0.080604,0.067068,0.430792,0.635944,0.026706,-0.006891,-0.358546,-0.050347,-0.464850,-0.241243,0.077140,0.447221,0.044591,0.019258,0.362238,-0.283000,-0.137354,-0.346445,-0.129848,-0.515479,0.148462,0.325082,0.131604,-0.336270,-0.034374,0.108932,0.052496,0.073958,-0.007107,0.078294,0.445514,-0.161791,0.115433,0.184868,0.294762,-0.232111,0.347012,0.657465,-0.187816,0.318081,-0.392193,0.382877,-0.057280,0.123403,0.095130,0.133514,-0.382078,0.300603,-0.375597,0.086079,0.259714,-0.511056,-0.050609,-0.646591,0.176326,0.121391,0.112297,0.001290,-0.603026,-0.133253,0.009239,0.105089,-0.002377,0.179884,0.348182,0.142520,-0.653474,-0.118325,0.521113,0.417229,-0.550814,0.243831,0.063966,0.023839,-0.373964,-0.209922,-0.260505,0.448415,0.551158,0.102106,0.209380,-0.343498,-0.531142,-0.144809,-0.071545', '1292846', '25723905', '3621404', '3387546');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299122', '猫儿历险记', '喜剧', '故事发生在繁华的大都市巴黎，一位善良的贵妇决定将自己的巨额财产留给一直陪伴她的宠物猫“女公爵”（伊娃·嘉宝 Eva Gabor 配音）以及它尚未长大的孩子们，贪婪的管家得知了这一消息，开始打起了这笔遗产的主意。一天深夜，管家趁着夜幕偷偷将女公爵和它的孩子们丢在了杂草丛生荒无人烟的乡下，在他心中的算盘上，只要没了这些碍事的猫咪们，自己继承遗产简直如同囊中探物。寒冷和饥饿时时威胁着女公爵一家人的性命，幸运的是，一只名叫托马斯（菲尔·哈里斯 Phil Harris 配音）的野猫在紧要关头出现在了女公爵的面前。在托马斯的帮助下，小猫们不仅健康成长，女公爵也学到了许多为猫处世的宝贵道理，最终，它们不仅顺利回到了巴黎，揭穿了管家的虚伪假面，女公爵和托马斯之间还上演了一段浪漫的情缘。©豆瓣', '菲尔·哈里斯', '沃夫冈·雷瑟曼', 8.5, 5500, 'tt0065421', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1605686921.jpg', 0.4, 0.7, 13.4, 43.6, 41.9, '0.284114,0.218932,-0.687688,0.434174,-0.280770,-0.331087,0.693152,0.104177,-0.320609,-0.130123,0.414354,0.865476,-0.113578,0.336913,0.389948,-0.024859,-0.366838,-0.544186,-0.236050,-0.107952,-0.078711,-0.462847,-0.372329,-0.128288,-0.255783,-0.499755,0.301237,0.096897,0.156002,0.169912,0.369267,0.055038,-0.083891,0.312289,-0.472215,0.205607,0.264241,-0.053416,0.037841,0.119455,0.009457,-0.116484,-0.125393,0.173714,0.256497,0.203420,0.826348,-0.732106,-0.083414,-0.139593,0.359269,-0.252421,0.089090,0.287362,0.274950,-0.183783,0.245280,0.172317,-0.165928,-0.132203,0.194458,-0.156498,-0.650722,-0.015752,-0.017148,0.155071,-0.683326,0.345872,-0.086975,-0.003343,0.140989,-0.435006,0.443001,0.198474,-0.078769,0.331698,-0.202772,0.290238,-0.572113,0.211962,0.630878,0.076790,-0.263714,0.174806,-0.205696,-0.306094,0.043350,-0.194415,-0.591191,-0.252572,0.668741,0.017085,-0.401869,0.323625,-0.642094,-0.059573,-0.269994,-0.270508,0.117370,-0.483321,-0.304720,-0.395962,0.012428,-0.395486,-0.191236,0.032688,0.325639,-0.093915,0.923608,-0.732716,0.288536,0.487511,0.051311,-0.363884,0.588725,-0.057705,0.315603,0.159141,-0.229717,-0.027001,0.282334,0.336314,0.268562,0.508966,-0.225115,-0.119044,-0.382224,0.575066', '30162520', '1302661', '1481233', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299131', '教父2', '剧情', '迈克尔（阿尔·帕西诺 饰）是美利坚黑手党科利昂家族的头目。 迈克尔的父亲维托·安多里尼（罗伯特·德尼罗 饰）出生于意大利科利昂镇。1901年，维托的父亲安东尼奥、兄长保罗、母亲（玛丽亚·卡塔 饰）都死于黑手党西乔家族之手。9岁的维托只得漂洋过海逃亡美利坚谋生。入境时，海关官员（理查德·沃森 饰）将其名姓登记为维托·科利昂。 1958年，迈克尔为儿子安东尼（詹姆斯·古纳瑞斯 饰）举办了初领圣体的聚会，不想当晚便遭遇暗杀。迈克尔侥幸躲过一劫，两名杀手却被人灭口。 维托在异国他乡如何生存？他身负的血海深仇能否得报？想要迈克尔性命的是谁？将杀手灭口的又是谁？©豆瓣', '阿尔·帕西诺', '弗朗西斯·福特·科波拉', 9.3, 508689, 'tt0071562', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2194138787.jpg', 0.1, 0.3, 4.5, 26.8, 68.2, '0.033492,-0.179665,-0.309255,0.354236,-0.264861,-0.686165,0.199275,0.209801,-0.640708,-0.224849,0.324945,0.837078,0.151071,0.098248,0.279001,0.271642,-0.449666,-0.632579,0.103172,-0.261044,-0.099311,-0.506214,-0.306885,-0.180252,0.022582,-0.313848,0.294808,-0.119465,0.165238,0.150138,0.394871,0.710861,-0.004507,0.039931,0.012953,0.196226,0.384596,-0.470266,-0.475413,0.001845,-0.184017,-0.221897,-0.378616,-0.070938,0.105059,0.498393,0.200366,-0.077171,0.610921,-0.450339,0.051885,-0.342171,0.189958,0.233480,0.232925,-0.355816,-0.007908,0.542483,0.096052,-0.239720,0.124748,-0.012497,-0.682865,0.211212,0.038657,0.196862,-0.503104,0.399561,-0.731743,0.083598,-0.159933,-0.237066,-0.018423,0.294064,0.117875,0.065426,0.170589,0.002678,-0.502396,-0.044587,0.652836,-0.169096,0.086961,-0.349399,-0.200058,-0.554381,-0.068174,-0.396576,-0.581440,0.115554,0.490387,-0.296495,0.113457,0.476122,-0.234783,-0.313917,-0.832647,0.020117,-0.136390,-0.056332,-0.064298,-0.480317,0.060113,-0.122915,-0.293602,-0.204224,0.328755,-0.057228,0.411780,-0.403524,0.172923,0.620777,0.247712,-0.174218,0.402523,0.003820,0.295876,-0.134289,-0.184608,0.386256,0.468407,-0.118026,-0.024379,0.105066,0.281778,-0.236242,0.201656,0.282751', '2132930', '22266126', '1292269', '26389148');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299135', '92黑玫瑰对黑玫瑰', '喜剧', '黄蝴蝶（邵美琪 饰）是一个失意的编剧，几经波折，已经堕落到向闺蜜阿娟（毛舜筠 饰）探讨三级片的程度。胡蝶的邻居警官吕奇（梁家辉 饰）对她颇有好感，后者在英雄救美后意外得到了她家的钥匙，然而他的不请自来，却落得狼狈而逃。因为事业接连遭受重创，胡蝶决定在江边横刀自尽，然而怯懦 的她终于没有自裁，反而盲打误撞惊扰了一对偷情的鸳鸯。后者仓皇逃窜，却遗留了一些私人财物。为了物归原主，胡蝶和阿娟一同登门，却无意中卷入了一场黑吃黑的血案。侥幸逃生的胡蝶临走前，还多事地留下了黑玫瑰的字条，而阿娟却因为留下了手印而被警方对号入座。结果，黑玫瑰成为了全城热议的话题，而这也引起了黑玫瑰掌门人（冯宝宝 饰）与师姐（黄韵诗 饰）的注意，于是一场剪不断理还乱的情场争夺战开始上演了……©豆瓣', '梁家辉', '刘镇伟', 7.4, 22017, 'tt0103602', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2349914061.jpg', 0.9, 4.8, 35.9, 41.6, 16.8, '0.214316,0.067099,-0.659126,0.419017,-0.039008,-0.393988,0.788887,0.184633,-0.325958,-0.027091,0.417878,0.687730,-0.411495,-0.040263,0.195605,-0.018252,-0.095157,-0.731713,0.221951,-0.036587,-0.176117,-0.271468,-0.281981,-0.068078,-0.162876,-0.046142,0.455327,0.241324,-0.428165,0.592484,0.454239,0.104985,-0.246399,0.721801,-0.157405,0.300640,-0.080015,0.181318,-0.087764,0.069574,0.152618,-0.611406,-0.282969,0.291586,-0.043811,0.685387,0.805972,-0.211877,-0.152465,0.076879,0.395170,-0.359361,0.008108,0.233769,0.331691,0.010109,0.177772,-0.043095,-0.185364,-0.122372,0.342287,0.152887,-0.571117,0.188926,0.064886,0.317821,-0.473742,0.658870,-0.126218,-0.065623,0.022204,-0.078880,0.307362,0.302690,0.315963,0.048061,-0.391827,-0.143735,-0.439127,0.252424,0.405702,-0.004171,0.072013,0.587216,-0.009851,-0.418279,0.032673,-0.159250,-0.306882,-0.131733,0.599542,0.099572,-0.279661,0.105733,-0.604126,-0.177269,-0.422794,0.001547,-0.326117,-0.394393,-0.067943,-0.471433,-0.207261,-0.292946,-0.483736,-0.010612,0.036733,-0.140181,0.568887,-0.497605,0.040817,0.576568,0.107170,-0.626563,0.402630,0.207836,0.063362,0.159558,-0.121305,0.032539,-0.084157,0.412287,0.381281,0.243218,-0.013454,-0.365893,-0.193213,0.176249', '3111650', '21619567', '21348112', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299153', '异形4', '动作', '静静的宇宙，一艘名叫“贝蒂”的太空船正在飞向“御夫座”星球。船上躺着数十个被麻醉冻僵了的地球人，他们全然不知即将到来的灾难。原来，丧尽天良的军方和商人将这些人诱拐过来，要送到“御夫座”上孵化异形女皇两百年前生下的蛋。雷普莉（西格妮•韦弗 Sigourney Weaver  饰）已成为了异形女皇生下的转世为人的异形人。她的基因里带上了异形的基因，变得特别强壮、忽明忽暗，成了“双面人”。“贝蒂”上有个叫考尔（维诺娜•赖德 Winona Ryder 饰）的年轻女人，正在设法破坏孵化异形蛋计划。当“贝蒂”来到“御夫座”，意想不到的情形发生了！©豆瓣', '西格妮·韦弗', '让-皮埃尔·热内', 7.7, 89628, 'tt0118583', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2243611578.jpg', 0.4, 2.4, 29.1, 48.5, 19.6, '0.211436,0.093374,-0.715830,0.326955,-0.261342,-0.064646,0.989256,0.084848,-0.348728,0.083836,0.224138,0.548844,-0.340709,0.091140,0.475326,0.346494,-0.587457,-0.290712,-0.162776,-0.081439,-0.603902,-0.130226,-0.543626,-0.459406,0.248786,-0.601229,0.604992,-0.218380,0.070626,0.001489,0.229242,0.502064,-0.271855,0.253069,-0.256663,0.101703,-0.205111,-0.287658,-0.005536,0.258637,-0.323524,-0.268716,0.005013,0.009694,-0.207889,0.112600,0.748653,-0.708035,-0.008761,-0.682267,0.291456,-0.372594,0.090843,0.052048,0.427036,0.058076,-0.043691,-0.076873,-0.010156,-0.025869,0.423008,-0.168883,-0.707733,0.061669,-0.096002,0.387673,-0.536043,0.299335,-0.015354,0.300466,0.247785,-0.394068,0.341862,0.312507,-0.006429,0.543162,-0.109548,0.157468,-0.676615,-0.114307,0.505171,0.047233,-0.533500,0.250037,0.243478,-0.662092,-0.140186,-0.175783,-0.295533,-0.080834,0.538483,0.184982,-0.313996,0.394367,-0.604102,0.034926,-0.261290,-0.376639,-0.129906,-0.142656,-0.294942,-0.500507,-0.087364,-0.292666,-0.312627,0.304942,0.115349,-0.153265,0.649355,-0.432580,0.263988,0.384710,0.218188,-0.244243,0.455312,-0.537073,0.073028,-0.206928,-0.086993,0.050123,0.178213,0.258442,0.063157,0.350964,-0.055494,0.032337,-0.460809,0.443577', '21619567', '1467779', '3005387', '1578502');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299158', '美丽新世界', '剧情', '青年张宝根（姜武 饰）为了领取一套中奖得来的房子，离开家乡小镇来到上海，上海虽大，但宝根能投奔的只有自己的小阿姨金芳（陶虹 饰）。金芳为人斤斤计较，在收取了宝根租房款后勉强收留了他，但仍不时讥讽宝根的憨厚土气。在上海找工作时屡次碰壁，逐渐心灰意懒的宝根决意离开，在地下通道偶遇流浪歌手阿亮（伍佰 饰），最终因为阿亮的劝告而留下。不久，宝根在人头攒动的交易所发现了商机，开始每日向股民们提供快餐，生意竟然出乎意料的红火，宝根在街上又偶遇阿亮，热情地邀请他回到家里 ，但很快因为金芳的一张快嘴，阿亮又一次踏上了旅途。有了收入的宝根找到了留下的理由，而他和金芳之间，也渐渐加深了互相的了解……在快速旋转的大城市中，也许宝根真能实现自己的希望。©豆瓣', '陶虹', '施润玖', 7.7, 8165, 'tt0191002', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2567000925.jpg', 0.3, 2.3, 27.8, 50.2, 19.3, '0.250011,0.150939,-0.668001,0.357628,-0.121820,-0.490067,0.451613,0.315050,-0.436835,-0.015238,0.138600,0.663528,0.049134,0.338617,0.132215,-0.082893,-0.086489,-0.255925,0.207689,-0.268197,-0.201538,-0.406594,-0.093365,-0.274480,-0.211213,-0.153862,0.255259,0.290851,-0.086036,0.561406,0.177245,-0.008928,-0.096636,0.510558,-0.439313,0.109716,-0.118262,0.178165,-0.183637,0.267375,0.007831,-0.308555,-0.299069,-0.142033,0.236744,0.559227,0.766459,0.002900,-0.310456,0.273124,0.316059,-0.044531,-0.030973,-0.068672,0.087002,0.226728,0.186039,0.039653,-0.517068,0.024938,0.099525,-0.077177,-0.356436,0.243975,0.050104,0.090183,-0.705562,0.494705,0.117255,-0.126729,0.061847,-0.623715,0.067775,0.485242,0.062682,0.408436,-0.163631,0.223909,-0.562733,0.151049,0.427285,0.033920,0.032660,0.480569,-0.061056,-0.239230,0.217995,0.022758,-0.216735,-0.136348,0.435342,0.147656,-0.209898,-0.064626,-0.801604,0.024495,-0.133587,-0.249491,0.151199,-0.313035,-0.214989,-0.679751,-0.088352,-0.186676,-0.175796,0.211109,0.049027,-0.161812,0.551723,-0.790484,0.169277,0.573481,0.482493,-0.486065,0.739656,-0.118418,0.027747,-0.177774,-0.139202,0.020006,0.132674,0.472622,0.404097,0.207401,-0.332739,-0.219439,-0.299987,0.308086', '1307811', '4830911', '3055049', '26951746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299166', '街角的商店', '剧情', '匈牙利布达佩斯，街角一间普通的小杂货铺。老板雨果·马图舍克（弗兰克·摩根 Frank Morgan饰）一直经营着这家小店，他的店员阿尔弗雷德·克莱里克（詹姆斯·斯图尔特 James Stewart饰）是店里经验最丰富的优秀店员。来到小店应聘的克拉尔·诺瓦克（玛格里特·苏利文 Margaret Sullavan饰）很快就被老板雇佣，却与阿尔弗雷德互相仇视，不能容忍对方。孤独又痴情的阿尔弗雷德有一个从未谋面的笔友。当他背着老板前去酒吧与笔友见面时，居然发现互相倾慕已久的亲密笔友居然就是自己讨厌的克拉尔。天意弄人，被老板解雇的阿尔弗雷德因为失业而不敢上前与她相认。由著名电影喜剧大师恩斯特·刘别谦执导的经典喜剧电影《街角的商店》，被列入美国电影学会评选的百年百大爱情类电影。本片具有四十年代喜剧的乐观积极气氛，被改编拍摄成1998年的新版本《电子情书》。©豆瓣', '玛格里特·苏利文', '恩斯特·刘别谦', 8.6, 11228, 'tt0033045', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1362848748.jpg', 0.1, 0.5, 10.1, 46.5, 42.8, '0.429372,-0.097501,-0.582188,0.342929,-0.032402,-0.498356,0.701122,0.190137,-0.407984,-0.306587,0.104984,0.950585,-0.394353,0.137091,0.338739,0.282061,-0.288949,-0.475170,-0.029019,-0.058577,0.219042,-0.274765,-0.406231,-0.309572,-0.115528,-0.234837,0.338839,-0.005061,-0.221000,0.288338,0.429193,0.281104,0.047854,0.088885,0.027683,0.131664,0.605418,-0.193585,-0.423030,0.108917,-0.224241,0.034890,-0.265918,-0.152314,0.136076,0.261619,0.368544,-0.088863,-0.099061,0.124864,0.709036,-0.011102,0.038016,-0.045332,0.120331,0.093036,0.469796,-0.001798,-0.021532,-0.050290,-0.079366,-0.174680,-0.744856,0.265159,0.107604,0.031436,-0.451322,0.340155,-0.206054,-0.092208,0.039867,-0.443221,-0.078335,-0.103488,0.526918,0.301093,0.035405,-0.006892,-0.312409,0.196021,0.401862,0.147524,-0.274312,0.300063,-0.243337,-0.443023,0.165746,-0.318166,-0.538212,0.138024,0.537778,-0.339221,0.204621,0.226011,-0.794274,-0.058464,-0.282163,0.016532,0.284147,-0.130538,-0.136239,-1.063318,-0.086426,-0.344872,-0.306218,-0.187396,0.087601,-0.140193,0.701637,-0.536028,0.218546,0.494325,0.363127,-0.215034,0.833573,-0.019831,-0.079360,-0.059679,-0.310069,0.187783,0.115325,0.192713,0.195307,0.357524,0.130232,-0.235789,-0.156824,0.406888', '3318306', 