INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299182', '富贵开心鬼', '剧情', '凌浩西（董彪 饰）和老婆（沈殿霞 饰）育有两个漂亮的女儿，生活美满幸福。不过凌母一心移民加拿大，为此不惜逼小女儿玲玲（陈淑兰 饰）甩掉一片痴心的男朋友包有路（吴大维 饰）。得知真相的包有路气愤离开，而当晚凌家四口人也因煤气中毒死亡。他们的灵魂来到阴间，移民之心不死，却被告知须在加拿大修好坟墓方好动身。然前期筹备移民，钱财散尽。凌家人获得特许，暂时还魂赚钱。蒙在鼓里的包有路帮助他们出主意，让凌父充当警方线人，凌母当按摩师、大女儿嘉嘉（吕秀菱 饰）。一家人全部动员起来，眼看最后期限临近……©豆瓣', '董骠', '黎大炜', 6.8, 6956, 'tt0097395', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2348735508.jpg', 0.9, 6.5, 54.9, 26.5, 11.2, '-0.417823,0.116067,-0.676729,0.053334,-0.071022,-0.279769,0.258683,0.151769,-0.240368,-0.266332,0.001269,0.392688,0.136244,0.150119,0.308397,0.009685,-0.230869,-0.281197,0.256948,-0.029320,-0.375249,-0.129655,0.100488,-0.226150,-0.290968,-0.073759,0.411125,0.388539,0.239989,0.465924,0.159985,0.033335,-0.335869,0.066769,-0.040110,0.198836,-0.082788,0.004935,-0.532023,-0.043211,-0.279764,-0.047465,-0.137331,-0.088673,0.181752,0.464837,0.653767,0.281362,-0.053899,-0.337645,0.140206,-0.449554,-0.192310,0.049341,0.112494,0.100155,0.278699,0.139660,-0.483768,-0.033397,0.256066,-0.076115,-0.403243,0.281840,0.087014,-0.152993,-0.329106,0.114665,-0.194280,0.107584,0.095212,-0.528377,0.230100,0.341860,-0.178563,0.308885,-0.222505,0.265738,-0.690826,0.305155,0.630079,-0.331398,0.286688,0.060957,0.027773,-0.113902,0.290708,-0.162781,-0.238548,-0.124001,0.225771,0.069236,-0.086467,0.027340,-0.141106,-0.226411,-0.342072,0.049807,0.320915,-0.495153,-0.010793,-0.469806,0.085817,-0.051650,-0.098774,0.402264,0.130657,-0.362741,0.507001,-0.200256,0.003415,0.149537,0.495504,-1.034040,0.455168,0.020469,0.580419,-0.324833,0.067051,0.245238,0.168593,0.175965,0.154713,-0.210678,-0.092905,-0.014560,-0.278223,0.049170', '1421278', '1484760', '1302110', '1428876');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299193', '理智与情感', '剧情', '老庄园主去世后，可怜的母女四人被长子逐出了庄园。靠着亲戚的帮助，她们在一处小小的农舍安顿下来。势力眼的长嫂未曾想到的是，她的弟弟爱德华（休·格兰特 饰）爱上了三姐妹中的大姐埃莉诺（艾玛·汤普森 饰）。理智的埃莉诺尽管也倾心于爱德华，却顾及两人地位的悬殊而努力克制着自己的感情。与此同时，妹妹玛丽安娜（凯特·温丝莱特 饰）和英俊的军官威罗比（格雷·怀斯 饰）陷入热恋。情感外露的玛丽安娜热情奔放的释放着自己对威罗比的爱慕，甚至不顾及伤害追求者布兰登（艾伦·瑞克曼 饰）上校的感情。未曾想，威罗比为人不正，根本没有把玛丽安娜的感情真正放在心上。两个姐妹的感情相继陷入了危机。性格迥异的两姐妹谁能得到真正的爱情，如愿以偿呢？母女四人又该如何走出生活的困境呢？©豆瓣', '艾玛·汤普森', '李安', 8.4, 124949, 'tt0114388', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1107322461.jpg', 0.1, 0.6, 13.1, 52.1, 34.2, '0.382009,0.012529,-0.769626,0.546523,-0.161974,-0.541529,0.825346,0.334875,-0.423917,-0.305512,0.338916,0.529879,-0.044146,0.258945,0.146032,0.129613,-0.385740,-0.682057,0.067078,0.023186,-0.022750,-0.655422,-0.243913,-0.121196,-0.017375,-0.494110,0.428381,-0.132573,-0.138566,0.290793,0.170958,0.268616,-0.015220,0.363780,0.128549,0.324698,0.195133,0.000481,-0.541043,-0.030622,0.028813,0.038928,-0.122182,0.293110,0.071010,0.228729,0.790557,-0.450277,0.021357,0.043900,0.181521,0.001437,0.165783,0.397780,0.136997,-0.486881,0.129413,0.095094,-0.075296,-0.136197,0.199141,0.110777,-0.643938,0.219631,0.085506,0.235026,-0.681676,0.631318,-0.303891,-0.245348,-0.010508,-0.143518,0.015836,0.367157,-0.064031,0.368711,-0.421411,-0.017828,-0.503649,-0.157647,0.637850,-0.009068,-0.265808,0.258538,-0.473336,-0.361119,-0.191766,-0.332224,-0.768456,-0.146776,0.307736,0.217679,-0.011237,0.495756,-0.275648,-0.210244,-0.311288,0.122585,0.152680,-0.681901,0.045860,-0.490863,-0.334065,-0.557452,-0.408156,-0.158316,0.052845,-0.162762,0.735395,-0.738133,0.174193,0.288963,0.413241,-0.474810,0.709894,0.125780,0.176155,-0.228824,-0.365268,0.392238,-0.086074,-0.313925,0.383472,0.235201,0.003244,0.069069,-0.087890,0.374836', '1309161', '1308047', '26348103', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299195', '砂之器', '悬疑', '和贺英良（加藤刚 饰）是业内闻名的钢琴家，年纪轻轻就取得了崇高的成就，事业前途一片大好。某日，英良遇见了名为三木谦一（绪形拳 饰）的老人，让英良感到震惊的是，这位老人竟然知道自己隐藏了多年的秘密和一直想要舍弃和埋葬的过去。 惊慌而又愤怒的英良选择杀死了三木，之后，三木的尸体被发现了，警部今西荣太郎（丹波哲郎 饰）和吉村弘（森田健作 饰）是负责调查此案的警官。敏感而又聪慧的今西通过缜密的调查和取证，渐渐将目标锁定在了英良的身上，挖掘出了这位天才音乐人不为人知的黑暗一面，最终，今西和吉村逮捕了英良，为这悲剧性的案件画上了终点。©豆瓣', '丹波哲郎', '野村芳太郎', 8.1, 7291, 'tt0202604', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561626578.jpg', 0.5, 1.8, 18, 49.3, 30.3, '0.221422,-0.088123,-0.577042,0.538468,-0.105237,-0.389542,0.658784,0.162659,-0.474983,-0.372244,0.206468,0.790346,-0.266916,0.113153,0.343166,0.133893,-0.234704,-0.959792,-0.275091,-0.280945,-0.339928,-0.583283,-0.436866,-0.178426,0.051431,-0.396691,0.666123,0.344298,-0.154669,0.581332,0.330847,0.454586,-0.017157,0.445811,-0.088341,0.192964,0.154422,-0.031180,-0.115628,0.119759,-0.021858,-0.450436,-0.121481,0.378176,-0.170762,0.582909,0.495828,-0.156872,-0.416948,-0.010353,0.240924,-0.516201,-0.100501,0.171231,0.477986,0.032670,0.054167,0.441554,-0.411722,-0.201435,0.172799,0.067772,-1.128608,-0.032128,0.230200,0.213866,-0.592064,0.344262,-0.034791,-0.325831,0.210858,-0.312671,0.281084,0.202320,0.199400,0.277907,-0.091997,0.056426,-0.151740,0.197364,0.438105,-0.079614,0.017689,0.212814,-0.003659,-0.488646,0.003621,-0.325735,-0.113425,-0.114683,0.296922,0.337421,-0.227199,0.072371,-0.494770,-0.191298,-0.331816,0.002280,0.031893,-0.457327,-0.194399,-0.236021,-0.314882,-0.511149,-0.402515,0.156253,-0.054948,-0.357601,1.035304,-0.934090,-0.034167,0.513978,0.091607,-0.409691,0.698604,-0.015776,-0.232757,-0.207963,-0.082550,-0.191501,0.054560,0.490540,0.138628,0.521463,-0.082486,-0.313076,-0.606026,0.213043', '27602116', '24284209', '1793491', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299204', '红菱艳', '剧情', '佩吉（莫伊拉·希勒 Moira Shearer 饰）是一名很有天赋的芭蕾舞演员，她对芭蕾舞的热爱让她觉得她生来便是为了舞蹈。她参加了芭蕾舞剧《红菱艳》的演出，在剧中，她扮演那个穿上红鞋一直舞蹈到死的舞女，她的演出获得了业界的一致好评，她的演艺事业就此扶摇直上。之后，她结识了作曲家朱利安（马留斯·戈尔林 Marius Goring 饰）并且迅速坠入了爱河。为了所爱的人，佩吉放弃了自己的事业，但婚后平静的生活令她无法忍受，似乎总有一种魔力在召唤她穿上舞鞋翩然起舞。佩吉听从了内心的召唤，她离开了朱利安重新回到了舞台，但渐渐的，她想起了自己曾经扮演过的那个穿着红鞋的舞女，她觉得她们的身影正在慢慢重叠，不安的佩吉猛然醒悟，自己生命中最重要的并非舞蹈而是家庭，她冲出剧院想要重拾朱利安的爱情，但一辆火车从天而降，终结了她年轻的生命。影片荣获1949年奥斯卡最佳配乐及最佳艺术指导奖。', '莫伊拉·希勒', '迈克尔·鲍威尔', 8.2, 9158, 'tt0040725', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2160799647.jpg', 0.3, 1.2, 16.8, 50.8, 30.9, '0.178056,0.162656,-0.713517,0.760866,-0.250577,-0.364812,0.878771,0.160591,-0.321779,-0.156294,0.479404,0.910417,-0.083056,0.268274,0.432799,0.146310,-0.302306,-0.862998,0.106703,0.006517,-0.191027,-0.037703,-0.114888,-0.060412,-0.149915,-0.444739,0.842244,-0.096138,-0.123989,0.523490,0.454941,0.074307,0.317759,0.344005,-0.242157,0.139964,0.092828,0.116236,0.012797,0.238632,0.077252,-0.464058,-0.147908,0.276589,-0.263327,0.235124,0.770634,-0.360920,-0.006892,0.032557,0.663425,-0.387180,0.121385,0.071313,-0.106900,0.164533,-0.055700,-0.128634,-0.118364,0.037591,0.040057,-0.195362,-0.756476,0.013977,0.033381,0.227320,-0.649939,0.383682,-0.064774,-0.073671,0.163670,-0.182841,0.051991,-0.059483,0.298404,0.143613,-0.314410,0.062625,-0.433723,0.589135,0.669240,0.102864,-0.367673,0.723630,-0.589648,-0.614849,-0.166700,-0.116489,-0.472526,-0.260379,0.443087,0.122231,-0.017559,-0.109801,-0.457749,-0.027454,-0.000011,-0.269309,-0.225079,-0.534188,0.060805,-0.349589,-0.329860,-0.451368,-0.223155,-0.252371,-0.181573,-0.509037,0.786193,-0.919746,0.259635,0.717997,0.076369,-0.417852,0.633916,0.009951,0.175587,-0.020638,-0.007154,0.520547,-0.356783,0.224375,-0.037885,0.529149,-0.112226,0.140856,-0.576711,0.749853', '323046