INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299213', '感官游戏', '科幻', '幻想与现实界限模糊的未来世界，科技已经发展到远远超越时代的地步。电玩界女王爱丽拉·盖勒（詹妮弗·杰森·李 Jennifer Jason Leigh饰）不仅美丽性感，更是一位设计尖端游戏的设计师。她所设计的虚拟实境系统“X接触”可以直接干扰玩家的神经系统。在试玩大会上，各方玩家齐聚一堂，体验爱丽拉的最新杰作。然而一群狂热者企图刺杀爱丽拉，危急时刻，爱丽拉被守卫泰德·皮库（裘德·洛 Jude Law饰）救走。为了躲避追杀，两人双双进入“X接触”的异次元世界，然而一切正在变得越来越虚幻。这部隐含大量社会议题的科幻惊悚影片《感官游戏》，由国际影坛最富争议性、最成功的导演之一大卫·柯南伯格执导。本片入围1999年第49届柏林国际电影节金熊奖，导演大卫·柯南伯格荣获该年度柏林国际电影节银熊奖-杰出艺术成就，并荣获2000年第26届美国电影电视土星奖-最佳科幻电影提名等多项大奖。', '詹妮弗·杰森·李', '大卫·柯南伯格', 7.2, 15570, 'tt0120907', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1713355242.jpg', 1.8, 6.9, 36.9, 40.4, 14, '-0.197369,0.370540,-0.548635,0.550342,0.459982,-0.030146,0.082046,0.048995,-0.291965,-0.314992,0.229271,0.665811,-0.619721,-0.112441,0.527012,-0.162298,-0.238174,-0.477583,-0.138638,-0.217611,0.021354,-0.138641,-0.540037,-0.015246,-0.143403,-0.390238,1.005197,0.023366,-0.599760,0.289137,0.486918,0.126249,-0.179246,0.275608,0.115680,-0.324954,0.706001,-0.060190,-0.763929,0.278964,-0.258936,-0.072547,-0.107617,-0.001989,-0.169799,-0.306990,0.557581,-0.180849,0.127294,-0.052692,0.815753,-0.216139,-0.285368,-0.331328,0.370320,0.032887,0.075356,0.144852,0.411618,0.182600,-0.110439,-0.381702,-0.759697,0.122744,0.192196,0.051062,0.000660,-0.073112,-0.313188,0.182188,-0.172859,-0.027346,0.136180,0.080767,0.613240,0.097143,0.118948,0.210021,-0.184842,0.570392,0.188877,-0.099052,-0.632315,0.346339,-0.006035,-0.659035,-0.437243,-0.433884,-0.426000,0.340426,0.368879,-0.139615,-0.062555,0.474745,-0.498423,0.113881,-0.122101,-0.562132,0.101905,-0.024410,0.184599,-1.172976,-0.201424,0.094481,0.102533,-0.283910,0.062525,-0.382058,0.709504,-0.338904,0.287399,0.367983,0.082665,-0.311085,0.749172,-0.010354,-0.011104,-0.425606,-0.425166,0.429519,-0.182665,0.153389,-0.426486,0.298327,-0.083284,-0.327959,-0.228148,0.482920', '26