INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299227', '魔法阿妈', '喜剧', '台北小孩豆豆（庄博文 配音）因为爸爸出车祸，妈妈要处理后世因此不得不先搬去台南和外表可怕的阿妈（文英 配音）同住。但是不久豆豆就惊奇地发现阿妈其实是拥有制服妖怪法力的驱魔师，鬼怪都很怕她。有一天，由于豆豆的贪玩，一个鬼怪（许杰辉 配音）被放了出来，鬼怪为了对付阿妈，利用豆豆做出了一些伤害阿妈的事情以增强自身的魔力。而在朝夕相处下，豆豆对阿妈的感情也起了变化，阿妈会不会被击败，就在最后关头了，豆豆能否成功帮助阿妈战胜魔鬼就看最后时刻了。©豆瓣', '文英', '王小棣', 8.9, 7379, 'tt0223391', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2726583460.jpg', 0.1, 0.6, 8.6, 34.3, 56.5, '0.158345,-0.260011,-0.365857,0.301051,-0.371888,-0.379398,0.365856,0.072157,-0.370378,-0.249085,0.081618,0.580139,0.009087,0.120320,-0.283860,0.081086,-0.248670,-0.348818,0.109903,-0.007290,-0.353078,-0.197721,-0.089906,0.011559,0.133108,-0.456747,0.266409,-0.248875,-0.307946,0.233006,0.067228,-0.010434,0.045196,0.520377,0.008632,0.165448,-0.278707,-0.009565,0.044039,0.432705,0.488317,-0.132939,0.114088,0.354046,0.141845,0.015784,0.616985,-0.312567,-0.318054,-0.037553,0.150592,-0.291339,0.067696,0.107427,0.372727,-0.093241,0.336281,0.184425,-0.226979,-0.011048,0.041514,0.190061,-0.597514,0.094296,0.231699,0.055785,-0.607273,0.165163,0.098269,-0.018464,0.262038,-0.579724,0.207675,0.360322,0.151478,0.492129,-0.413077,-0.064973,-0.600313,0.002303,0.627221,-0.285405,0.177552,0.237812,-0.150314,-0.270369,0.228632,-0.376278,-0.377512,0.289857,0.126042,0.076273,-0.515659,0.216975,-0.558729,-0.072666,-0.175559,-0.040312,-0.153184,-0.406452,0.098104,0.001716,-0.069729,-0.339015,-0.260234,-0.068308,-0.001820,-0.392755,0.941347,-0.893732,0.237580,0.690613,0.607495,-0.349912,0.438222,-0.106454,0.013135,-0.065200,0.357444,-0.160906,-0.296728,0.358805,0.370582,0.226485,0.307469,-0.316107,-0.294031,0.483062', '24284209', '1877596', '1292219', '3755531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299235', '毒品网络', '剧情', '在崇尚享乐的现代社会，毒品已成为了美国政府甚为头痛的难题。为了应对日益严重的毒品犯罪和买卖，美国总统发起反毒品战争计划，正直的俄亥俄州最高法院大法官罗伯特·刘易斯（迈克·道格拉斯 饰）由此调任成为国家药品政策管理局的官员，他不仅要面对各个利益团体的攻伐和拉拢，还要应对来自家庭内部的毒品侵蚀；墨西哥南部，恪尽职守的警官哈维德·罗德里格兹在军方某将军的授意下，即将对盘桓这里的贩毒组织展开行动，而他也陷入了毒品泥潭中难以抽身；联邦干探蒙特尔和雷从事毒品卧底工作多年，虽然老牌毒枭卡尔落网，但他们又将和卡尔的妻子海伦娜（凯瑟琳·泽塔·琼斯 饰），这个继承了丈夫产业的新毒品贩子展开抗争……©豆瓣', '迈克尔·道格拉斯', '史蒂文·索德伯格', 7.6, 13952, 'tt0181865', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p817029842.jpg', 0.6, 2.6, 28.6, 51.1, 17.1, '0.323205,-0.049558,-0.501972,0.442603,0.051192,-0.183782,0.410047,0.353474,-0.566034,-0.153182,0.256158,0.791955,0.256614,-0.174489,0.217367,0.097043,-0.588939,-0.751653,-0.134695,-0.021455,-0.024573,-0.523990,-0.489071,-0.538888,-0.197753,-0.188428,0.664457,0.133955,-0.335552,0.131603,0.203196,0.571557,0.041526,0.383229,0.183427,-0.302139,0.502067,-0.378292,-0.725178,0.215734,0.070870,-0.269926,0.000651,0.300182,0.256929,0.454608,0.286215,-0.302389,0.253138,-0.508771,0.324294,-0.564315,0.022009,0.090839,0.468828,0.025270,-0.069507,0.531685,-0.193355,-0.135193,0.156951,-0.130498,-0.862050,-0.246376,0.076830,0.192961,-0.516031,0.165238,-0.161310,0.161032,-0.289873,-0.233040,0.042313,0.682757,0.270001,0.220555,0.002971,0.120300,-0.503649,0.125867,0.462103,-0.065521,-0.300051,-0.233863,-0.386788,-0.668671,0.033458,-0.548879,-0.223159,-0.459614,0.290683,-0.270228,0.079399,0.669011,-0.766635,0.135169,-0.297061,-0.280699,0.075230,-0.107266,-0.074764,-0.829888,-0.297847,-0.248224,-0.093041,0.136622,0.404851,0.025467,0.511483,-0.702411,-0.132244,0.733070,0.409628,-0.790504,0.291160,0.211702,0.204165,-0.404930,-0.268260,0.248716,0.104359,0.403457,-0.029470,-0.030545,0.172271,-0.319158,0.138456,0.217381', '1305096', '1309112', '27073234', '1292573');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299237', '郁金香芳芳', '喜剧', '故事发生在社会动荡、战争不断的法国路易十五时期。方方（文森特·佩雷 Vincent Perez 饰）是个身手不凡的农村青年，为了逃婚离家出走，又轻信了路遇的波希米亚女郎预言，认为自己会娶国王的女儿，为了这个预言他加入了军队。进入军队他才发现，给他预言的女郎是军团中士的侄女阿德丽娜（佩内洛普·克鲁兹 Penélope Cruz 饰），并且先一步对他倾心。机缘巧合，方方救了一位被匪徒围困的女孩，恰好是国王女儿昂丽叶特公主，为了“预言成真”，方方爬城堡想再见公主，结果被当成匪徒抓起来，还被判处死刑。为救方方，阿德丽娜也来到王宫，怎料美貌的她马上引发国王垂涎，眼看方方行刑就要开始，阿德丽娜却被囚禁……“郁金香方方”是法国家喻户晓的民间传奇人物。©豆瓣', '文森特·佩雷斯', '热拉尔·克瓦兹克', 6.6, 10194, 'tt0305568', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p813148464.jpg', 1, 8.4, 55.9, 28.1, 6.5, '0.061379,0.035102,-0.443715,0.255770,-0.277753,-0.236814,0.678080,0.038614,-0.436082,-0.156417,0.634502,0.750614,-0.208048,-0.034954,0.372661,0.414425,-0.290278,-0.520029,0.230406,-0.118562,-0.094519,-0.163242,-0.105357,-0.178393,-0.023052,-0.548808,0.541527,-0.194584,-0.267317,0.073414,0.262041,0.342193,0.082888,0.178047,-0.247546,0.291535,0.166284,-0.313166,-0.291510,0.272238,-0.352031,-0.217409,-0.149692,0.147382,-0.267083,0.086411,0.368066,-0.338965,0.206809,-0.412027,0.388286,-0.368555,-0.102382,0.134065,0.529656,-0.223057,0.099017,0.111261,-0.023074,-0.394471,0.287424,-0.165073,-0.478680,0.409351,0.154212,0.195647,-0.608051,0.100570,-0.251171,-0.047399,0.226773,-0.256310,0.112696,0.479303,0.099388,0.201302,-0.071035,0.063950,-0.764502,0.053927,0.397914,-0.168546,-0.032418,0.094767,0.054130,-0.418366,0.391910,-0.248175,-0.508474,0.213723,0.300848,-0.340203,-0.151090,0.284362,-0.306817,-0.161652,-0.724110,-0.163691,0.246250,-0.470358,-0.241251,-0.014509,-0.166746,-0.044423,-0.045503,-0.060885,0.132245,-0.057150,0.601428,-0.527270,0.312057,0.632954,0.279800,-0.636755,0.406590,0.274295,-0.203411,-0.151810,-0.013563,0.228561,0.033105,0.331430,0.068890,0.198125,0.205175,-0.401117,-0.143461,0.240204', '1292217', '1293976', '1309069', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299247', '007之明日帝国', '动作', '英国海军的德文郡号军舰在中国领海内被遭到不明鱼雷攻击沉没。为了查明情况，英国海军决定动用武力，派出军舰前往出事海域进行反击。然而却被秘密情报负责人M（朱迪·丹奇 Judi Dench 饰）阻止，并派出代号007的情报员詹姆斯·邦德（皮尔斯·布鲁斯南 Pierce Brosnan 饰）去查清真正的原因，避免两国之间一触即发的战争。在不断深入的调查中，媒体大亨卡佛（乔纳森·普雷斯 Jonathan Pryce 饰）进入了邦德的视线。而且在卡佛举办的晚宴上，邦德遇上了前女友帕丽丝（泰瑞·海切尔 Teri Hatcher 饰），现在的卡佛夫人。在帕丽丝的帮助下，邦德利用GPS让已出动的英国军舰偏离了航道为自己的调查争取到了宝贵的时间。从卡佛处偷来的设备上，邦德发现了沉没军舰的准确位置，不过在沉船处却与中国女特工林惠（杨紫琼 饰）一起被卡佛擒获。原来，卡佛是想通过引发战争来获得全球媒体的垄断地位。这一次，邦德能否逃出魔掌捣毁卡佛的阴谋？', '皮尔斯·布鲁斯南', '罗杰·斯波蒂斯伍德', 7.4, 40092, 'tt0120347', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1721307776.jpg', 0.3, 2.2, 38.6, 46.7, 12.1, '0.249379,0.232858,-0.724065,0.556905,0.326064,-0.161623,0.546350,-0.112456,-0.390223,-0.102238,0.186596,0.526562,-0.061019,-0.357653,0.256492,0.132263,-0.520926,-0.566170,0.088477,-0.172018,-0.389245,-0.666241,-0.425310,-0.260166,0.165161,-0.394359,0.613176,0.382551,-0.444817,0.241979,0.262330,0.340650,-0.011332,0.456781,-0.019768,-0.127907,0.209611,-0.379681,-0.370547,0.661939,-0.087283,-0.269200,0.069659,0.232237,0.141379,0.518770,0.510700,-0.289697,0.102182,0.077356,0.069445,-0.419092,0.209684,0.110029,0.464010,0.047486,-0.163215,0.194042,-0.354195,0.123104,0.161662,0.144197,-0.677013,0.016644,0.021676,0.208762,-0.385060,0.179871,-0.517825,0.067123,-0.205960,-0.302374,0.320250,0.572346,0.164855,-0.190112,-0.142402,0.221730,-0.624984,-0.107099,0.586113,-0.094886,-0.056629,-0.005331,0.107981,-0.415954,-0.084810,-0.476115,0.009645,-0.024409,0.421135,-0.098116,0.034174,0.346490,-0.577580,-0.199278,-0.565763,-0.520336,-0.137361,-0.249886,0.012652,-0.905641,-0.149185,-0.111290,-0.145799,0.113536,0.108900,-0.178033,0.501811,-0.660554,0.084227,0.829300,0.402990,-0.314170,0.584214,0.097735,0.207032,-0.302782,-0.156886,0.159064,0.283254,0.386886,-0.049907,0.115101,0.104572,-0.503654,-0.247880,0.093314', '2973528', '3178770', '1307897', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299248', '镜子', '剧情', '本片是导演安德烈·塔科夫斯基（Andrei Tarkovsky）的一部自传体电影。幼年的塔科夫斯基随着母亲（玛格瑞塔·泰瑞柯娃 Margarita Terekhova 饰）去亲戚家借钱，他独自在一个陌生的房间里发现了一面镜子，并通过镜子审视自己，在巴赫的音乐中，塔可夫斯基的回忆慢慢带出了一系列的事件：电视上在播报一个口吃的年轻人通过催眠治痊了自己；一个被家庭忽视的妻子遇上一位迷路的乡村医生，两人之间产生若即若离的关系；一个未曾露面的叙述者与前妻在争吵；一个早熟的年轻人备受军事指导员的呵责。这些毫无关联的片段式回忆通过镜子串联起来，展现了导演对时间、历史、生活、土地、梦境等意象的哲学思考。导演的母亲在影片中扮演艺术家的母亲；他的父亲，一位著名的俄罗斯诗人，在画外音中朗读自己的诗作。©豆瓣', '玛格丽特·捷列霍娃', '安德烈·塔可夫斯基', 9, 31654, 'tt0072443', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2327630533.jpg', 0.6, 1.1, 7.1, 28.4, 62.9, '0.530502,-0.009079,-0.606301,0.935830,-0.110564,-0.219445,1.095412,0.186255,-0.438533,-0.380822,0.273925,0.877704,-0.345608,0.362930,0.077148,-0.190720,-0.440960,-0.771810,0.050260,-0.061547,-0.205514,-0.439077,-0.229618,-0.080971,-0.197755,-0.404282,0.676565,-0.157218,-0.387548,0.142587,0.108081,0.055526,-0.031704,0.300407,-0.191794,0.123945,0.206160,0.047592,-0.133797,0.169707,0.077528,-0.195488,-0.147206,0.188319,-0.243703,0.263468,0.871043,-0.301143,-0.081029,0.213564,0.651215,0.085478,-0.075582,-0.012062,0.326343,0.197995,0.026609,0.160205,-0.330216,0.034410,-0.223614,-0.059605,-0.684177,-0.271864,0.027688,0.405716,-0.590930,0.505115,0.117826,-0.073192,0.026572,-0.249748,0.314857,0.183917,0.304454,0.633991,-0.244429,-0.035092,-0.367043,0.425559,0.213388,-0.058415,-0.371765,0.586329,-0.472076,-0.352687,-0.212223,0.000383,-0.780548,-0.103588,0.293824,-0.447238,-0.360415,0.162049,-0.541685,-0.003858,-0.262730,-0.299246,-0.076362,-0.470614,-0.204768,-0.768782,-0.397765,-0.330268,-0.058944,-0.105164,0.041226,-0.305521,0.782628,-0.662671,0.142429,0.634955,-0.053653,-0.246721,0.757208,0.198044,0.110213,-0.287250,0.009577,0.415421,0.147922,0.155241,-0.110615,0.641055,0.115458,0.125553,-0.534070,0.583332', '26677495', '30401849', '1467779', '26884422'