INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299250', '给爸爸的信', '剧情', '大陆卧底公安巩伟（李连杰 饰）因工作关系，不能给与重病的妻子更多照顾，也不能为懂事又武艺高强的儿子巩固（谢苗 饰）提供更多关怀，在妻儿急需要他的时候，巩伟因上司的命令，假扮罪犯，和大陆抓获的香港黑道分子小黑（柯受良 饰）一同逃跑，踏上了远赴香港甫光（于荣光 饰）团伙卧底的旅途。巩伟与甫光团伙在炸弹交易中黑吃黑，混战中搭救了香港督查方逸华（梅艳芳 饰），并凭借出色身手得到了甫光的信任。方逸华来到北京调查巩伟身份，获知真相，并在巩妻去世后带领巩固至香港寻父，方逸华上司将巩伟巩固父子身份暴露，使巩伟处境危险，而此刻甫光策划的拍卖抢劫行动亦迫在眉睫……©豆瓣', '李连杰', '元奎', 8, 71985, 'tt0113153', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2352180519.jpg', 0.2, 1, 21.8, 53, 24, '-0.060659,0.066725,-0.592179,0.380603,-0.024947,-0.012209,0.054358,0.414249,-0.443761,-0.228333,0.204134,0.516441,0.161915,-0.059992,0.149410,-0.334293,-0.394063,-0.613436,0.142807,-0.213867,0.029652,-0.317053,-0.296878,-0.345167,-0.261021,-0.340960,0.596443,0.343809,-0.262683,0.431799,0.206602,0.107258,-0.325071,0.290732,-0.050707,-0.368959,0.025193,0.290518,-0.656329,0.175976,-0.089525,-0.278478,0.011923,0.090668,0.305364,0.420580,0.408854,-0.039172,-0.138746,-0.315239,0.167402,-0.356417,0.285854,-0.190458,0.536257,0.134486,0.226485,0.490287,-0.277376,0.290003,-0.184758,-0.134908,-0.756524,0.130644,0.428260,0.036400,-0.508828,0.152913,-0.339340,-0.200511,-0.019944,-0.155437,0.121924,0.496324,-0.043968,0.142223,-0.076621,0.201070,-0.208000,0.244444,0.474471,-0.213806,0.198457,0.053707,0.069046,-0.291881,0.098930,-0.320469,0.181108,-0.032108,0.202310,-0.027847,0.079654,0.275857,-0.143221,-0.099318,-0.337942,0.201513,-0.077926,-0.271591,0.165237,-0.660621,-0.119025,-0.109345,-0.090378,0.167107,0.334188,-0.125182,0.439948,-0.539242,-0.004945,0.516403,0.579689,-0.970131,0.284892,0.168441,0.228498,-0.670947,-0.032572,0.210677,0.287316,0.038194,-0.184146,-0.182881,-0.226367,-0.313749,-0.060757,-0.039354', '1484760', '1302110', '3412882', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299256', '辛巴达七海传奇', '动画', '故事从希腊神话的纷争女神艾莉丝（米歇尔·菲佛 Michelle Pfeiffer 配音）开始，她是一个喜欢混乱的女神，她盗走了“和平宝典”，又将这个罪名嫁祸给了辛巴达（布拉德·皮特 Brad Pitt 配音），护送“和平宝典”的王子普罗士（约瑟夫·费因斯 Joseph Fiennes 配音）是辛巴达的从小玩得好的朋友，“和平宝典”被窃也使得他的任务失败，无法向自己的王国交代，而王国里的大臣都一致认为是辛巴达盗走了。但普罗士相信辛巴达的清白，他主动提出以自己生命做抵押，让辛巴达追回宝物“和平之书”。普罗士的未婚妻玛琳娜（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 配音），为监视辛巴达也偷偷登上了船。辛巴达能否经受考验，为夺回“和平之书”救出朋友的性命？他和玛琳娜又在患难中发生了怎样的爱情？ 影片改编自阿拉伯民间故事《一千零一夜》中的《辛巴达航海记》。', '布拉德·皮特', 'Patrick Gilmore', 7.4, 6027, 'tt0165982', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1953047717.jpg', 0.6, 3.8, 36.5, 43.1, 16.1, '0.255394,0.168757,-0.332685,0.725694,-0.003190,-0.352939,0.459644,-0.012826,-0.253470,-0.197335,0.211501,0.938853,0.183973,-0.147294,0.492273,0.469430,-0.466136,-0.752024,0.050916,-0.112013,-0.077517,-0.526594,-0.209718,-0.306003,-0.331408,-0.597828,0.461548,0.036587,-0.261724,0.118439,0.470538,0.110941,-0.015054,0.240802,-0.041614,0.196754,-0.038134,-0.138626,-0.369142,0.196972,-0.052418,-0.249341,-0.140261,0.331671,0.129953,0.329992,0.501588,-0.295461,0.117141,-0.001960,0.308618,-0.472329,0.028571,-0.042852,0.044767,0.128028,-0.010775,0.259563,-0.028004,-0.257325,0.046144,-0.150045,-0.963821,-0.090650,0.008414,0.201840,-0.408805,0.324523,-0.220912,0.077055,0.178727,-0.141392,0.351537,0.340423,0.407219,0.296150,-0.102716,0.022805,-0.461823,0.467125,0.513970,-0.171230,-0.025197,0.212493,-0.196856,-0.662923,0.118078,-0.381268,-0.627707,-0.032679,0.494847,-0.173165,0.081094,0.594686,-0.699373,-0.193729,-0.361105,-0.359874,0.129497,-0.605558,0.187314,-0.240502,-0.183687,-0.150622,-0.029916,-0.124718,0.214779,-0.498066,0.891337,-0.712721,0.241811,0.652581,0.143571,-0.576837,0.620279,0.255113,0.232498,-0.102002,-0.029882,0.250950,0.378696,0.403218,0.036239,0.071996,0.543139,-0.136649,-0.473514,0.473014', '27602116', '4301278', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299261', '红色沙漠', '剧情', '意大利北部工业城市拉文纳，无处不在的工厂噪音、被污染的河流、荒凉的郊外、冷清的街道，一片人间炼狱的模样。远处，一个身着绿衣的年轻女子，在巨型高耸的烟囱和吞吐着迷雾的管道中驻足。在这污浊荒废之地，她显得烦躁不安又神思恍惚。原来这个略显神经质的女人朱莉安娜（莫尼卡·维蒂 Monica Vitti饰）的丈夫正是这家冶炼厂的经理乌戈（卡洛·吉奥内蒂 Carlo Chionetti饰）。乌戈把她介绍给自己的同事科拉德·泽勒（理查德·哈里斯 Richard Harris饰）。两人相互吸引，朱莉安娜难以控制自己的感情，与泽勒发生了肉体关系。渐渐地，她发觉自己已经难以同丈夫和儿子恢复以往的亲密感情。泽勒对她的感情，也依旧无法抚慰她寂寞的心灵。这条淌满血的红色沙漠，是机器工业时代将人性摧残得无以复加的血淋淋的荒漠。这部由意大利新现实主义导演安东尼奥尼执导的他第一部彩色片《红色沙漠》，荣获1964年第29届威尼斯国际电影节金狮奖。影片用极为大胆的色彩，描绘出一副野蛮的工业社会对人类精神的压抑和异化之景。作品简化甚至舍弃叙事和戏剧冲突，使得影片得到两极化的评价。', '莫尼卡·维蒂', '米开朗基罗·安东尼奥尼', 8, 18711, 'tt0058003', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2248487533.jpg', 0.6, 2.6, 19.8, 48.4, 28.7, '0.218306,0.160713,-0.760784,0.838139,0.069854,-0.130498,0.947785,0.325967,-0.379609,-0.016393,0.257582,0.584258,-0.274837,0.112322,0.173305,0.094676,-0.303244,-0.588754,-0.249227,-0.000650,-0.071254,-0.321939,-0.533121,-0.188935,-0.091076,-0.499655,0.775051,0.134197,-0.230456,0.274387,0.091635,0.140285,0.046584,0.244547,-0.204740,-0.039961,0.053912,-0.004315,-0.149157,-0.113754,-0.056822,-0.049379,-0.029597,0.255889,-0.274913,0.384766,0.853191,-0.146405,-0.060731,-0.031911,0.509490,-0.142408,0.213859,0.070936,0.118742,-0.235457,0.109982,0.080696,-0.227774,-0.022413,0.053088,-0.067193,-0.556011,0.145477,0.048200,0.257099,-0.395235,0.556081,-0.082256,-0.267393,-0.025711,-0.264287,0.057976,0.002598,0.282957,0.590888,0.048923,-0.004147,-0.351906,0.238228,0.361198,0.050444,-0.604709,0.520573,-0.696007,-0.365935,-0.301950,-0.280891,-0.653157,-0.220981,0.277650,-0.043235,-0.180512,0.444876,-0.935670,0.084991,-0.115292,-0.318124,-0.144079,-0.119524,-0.134010,-0.659314,-0.330610,-0.691900,-0.122579,-0.224883,-0.062851,0.035906,0.522242,-0.430196,0.074704,0.472760,0.276095,-0.183623,0.619038,-0.074499,-0.042771,-0.122257,-0.255902,0.555494,-0.210191,0.288995,0.118813,0.514255,-0.089322,0.102932,-0.423270,0.709982', '1467779', '3055450', '2334814', '1294434');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299282', '精装追女仔', '喜剧', '同在一个修车店工作的烂口发（周润发 饰）、交通灯（陈百祥 饰）还有吴准少（曾志伟 饰）是同事也是好友，他们都不屑老板刘定坚（冯淬帆 饰）的吝啬刻薄。烂口发因不堪女友（张敏 饰）的势利眼母亲而忍痛与女友分开了。刘定坚建议伙计们一起跟廉价旅行团到槟城游玩，但到达才知道这个旅行团是货不对版的。但在槟城，烂口发等人认识了在当地拍广告的董董（张曼玉 饰）与其好友蚊滋。烂口发想进一步接近董董，便假装自己是富家公子，董董也同样以富家女的身份欺骗对方。两人出席一个舞会的时候得罪了真正的富家子赵完先，赵完先还看上了董董。赵为了要报复烂口发，他向董董揭发了烂口发的真实身份，董董面对欺骗非常伤心。董董准备参加赵完先的舞会，但她与好友都不知道卑鄙的赵完先另有企图，烂口发等人前往营救。©豆瓣', '周润发', '王晶', 6.8, 17698, 'tt0093056', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1276197847.jpg', 1, 6.9, 52.6, 29.3, 10.1, '0.284345,-0.278800,-0.280798,0.361781,-0.247692,-0.204108,0.538786,0.297894,-0.284288,-0.123737,0.150977,0.635975,-0.191072,0.162214,0.160317,0.023172,-0.189787,-0.512577,0.101311,-0.105534,-0.201826,-0.522027,0.044570,-0.315775,-0.132993,0.124762,0.284826,0.005522,-0.277250,0.458279,0.599771,0.086513,-0.095652,0.546260,-0.104570,-0.017281,-0.026819,0.114810,-0.201933,0.026499,0.057390,-0.435002,-0.171714,0.128957,0.188894,0.522213,0.400268,0.022355,-0.150870,0.098994,0.123526,-0.346587,-0.053856,0.167563,0.180760,-0.192548,0.407025,0.049001,-0.069122,0.061633,0.224321,0.015270,-0.498082,0.180342,0.349639,-0.029098,-0.679908,0.469682,-0.197922,-0.247043,0.022188,-0.409849,0.328037,0.108360,0.077139,0.180526,0.003247,-0.122337,-0.484727,0.430685,0.561148,0.391424,0.077045,0.185083,-0.009805,-0.447490,-0.022191,-0.245124,-0.466658,-0.076282,0.101132,-0.057619,-0.051229,-0.246164,-0.511277,-0.219549,0.098292,0.023454,-0.021099,-0.351942,0.203157,-0.457967,-0.255101,-0.588933,-0.121920,0.197298,0.224679,-0.234241,0.560450,-0.789608,0.075063,0.397528,0.516628,-0.798761,0.711699,0.198547,-0.151479,-0.123106,-0.137746,-0.309514,0.221572,0.022436,0.091867,0.397036,0.218521,-0.292845,-0.177510,0.119344', '1308206', '3033092', '25908042', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299287', '城市英雄', '剧情', '迈克尔·道格拉斯扮演的威廉·福斯特是一家军工场的工程师，被解雇后心情很压抑。因离婚，小女儿的生日没被邀请，恰好路上堵车，他弃车走进一家杂货铺，想找点零钱打电话，却遭到刁难，他操起垒球棒砸了铺子。在公园休息时，又和流氓打了一架；在快餐店里因和服务生发生争执，他拔出从流氓那里缴获的手枪一阵乱射，此时他已完全失控。最后，他面对退休警官的枪口，不禁自问：“我是坏人吗？”', '迈克尔·道格拉斯', '乔·舒马赫', 8.1, 9997, 'tt0106856', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2530507350.jpg', 0.5, 1.7, 18.4, 51.5, 27.9, '0.512892,-0.155954,-0.518144,0.003327,-0.247043,-0.521171,0.911591,0.357121,-0.171857,-0.300774,0.271914,0.591814,-0.309706,0.284625,0.340530,-0.213884,-0.200268,-0.479541,0.109891,0.083080,-0.120011,-0.241718,0.054372,-0.125231,0.140464,0.123881,0.161372,-0.214556,-0.281217,0.463146,-0.016727,0.252849,0.172028,0.490000,-0.236542,0.054685,0.082124,-0.062622,0.021448,0.102153,0.254997,-0.437022,0.044357,0.079133,0.211085,0.655434,0.450261,0.286545,-0.092317,0.005656,0.036216,-0.041482,0.018146,0.095728,0.277666,-0.036126,-0.036506,-0.162481,-0.367778,-0.137928,0.225256,0.142968,-0.268647,0.291886,-0.363609,-0.354025,-0.674627,0.430839,-0.312871,0.200831,0.032470,-0.264231,0.611891,0.249429,-0.077360,0.366934,-0.051852,-0.019221,-0.680528,0.126544,0.567713,-0.234813,0.293617,0.192237,-0.027675,-0.018376,0.383620,0.048595,-0.464615,-0.262414,0.552773,-0.280464,-0.290690,-0.298365,-0.265266,-0.125468,-0.187556,-0.234796,0.001864,-0.246733,-0.443306,-0.517693,0.160324,0.007967,-0.053924,0.081553,-0.013579,0.394953,0.076346,-0.747718,0.085430,0.384030,0.355341,-0.143690,0.550295,-0.036395,-0.223468,0.051104,0.119385,-0.202592,0.205371,0.494722,0.423138,0.283640,0.013442,-0.336954,-0.166383,0.380382', '1301686', '1308755', '1302384', '1303462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299288', '胭脂扣', '剧情', '报社记者袁永定（万梓良 饰）遇到了一位前来登寻人广告的女子如花（梅艳芳 饰），无意中才发现了该名冷艳的女子原是鬼魂，早在50年前，她是一名红牌妓女，结识了一名纨绔子弟十二少陈振邦（张国荣 饰）。如花深深爱上了这名多情的公子，两人已到了谈婚论嫁的地步，由于身份悬殊，遭到了十二少家人的极力反对。无奈之下，他们以胭脂扣定情，一起吞鸦片殉情。如花未能在地府看到自己的爱人，便到阳间寻找。如花在两名记者的帮助下，得知原来当年十二少被人救活了，如今生活潦倒。面对十二少的懦弱，如花伤心欲绝，把胭脂扣返还，回到阴间投胎转世。©豆瓣', '梅艳芳', '关锦鹏', 8.5, 265553, 'tt0093258', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205476838.jpg', 0.1, 0.6, 12.6, 49.5, 37.2, '0.261293,0.252359,-0.521675,0.371295,-0.401927,-0.268421,0.684298,-0.048734,-0.379137,-0.185562,0.460029,0.788720,-0.186440,0.404603,0.298762,-0.201795,0.236974,-0.455627,-0.088256,-0.354907,-0.147175,-0.210456,-0.206531,0.281771,-0.252601,-0.260641,0.418528,-0.024264,-0.023110,0.465117,0.517530,0.418848,-0.442402,0.214399,-0.355106,0.273451,0.103978,0.077534,-0.035306,0.363439,-0.254996,-0.487450,-0.058432,-0.100969,-0.125489,0.181386,0.550921,-0.164961,-0.332522,-0.157008,0.297610,0.044660,-0.207633,0.373601,0.327199,-0.088485,0.201770,0.135297,-0.324161,0.087156,-0.024318,0.041278,-0.535053,0.263052,0.145779,0.178439,-0.708085,0.231013,-0.211010,-0.056016,0.050013,-0.409431,0.293554,0.221848,0.150016,0.183469,-0.038439,-0.057015,-0.665314,0.514951,0.699112,0.394302,-0.109405,0.343979,0.214913,-0.255819,0.064574,-0.521049,-0.369753,0.338998,0.250782,0.065678,-0.080235,0.208109,-0.412805,-0.382582,-0.242301,0.029666,-0.028353,-0.075428,-0.280925,-0.334238,-0.423769,-0.462474,-0.396379,0.153747,0.243446,-0.234866,0.903815,-0.737463,0.224216,0.325880,0.338491,-0.779541,0.642381,0.040031,0.095837,-0.056110,-0.081386,0.327205,0.204569,0.233493,0.210615,0.156155,-0.647771,-0.101924,-0.422821,0.163459', '1296770', '1877596', '25721544', '1306530');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299292', '八美图', '喜剧', '圣诞节前夕，一个富裕人家正在忙着筹备圣诞。窗外白雪皑皑，屋里迎来了女儿大学归来。一家人沉浸在圣诞前团聚的气氛。此时，大家以为作为一家之主的父亲还没有睡醒，谁知打开房门一开，他竟死在了睡床上，背后插着一把刀。众人惊慌失措，想报警之时却发现电话线早以被剪断；车已被蓄意破坏，无法开到警局。明显地，凶手就在这8人中间。彼此的猜忌和指控开始了，各人不为人知的秘密一一曝光，伦理道德的颠覆，贪婪自私的本性，令这个圣诞前夕特别混乱。讽刺的是，最后谁是凶手已经不重要了……©豆瓣', '达尼埃尔·达里约', '弗朗索瓦·欧容', 7.7, 51716, 'tt0283832', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p619021003.jpg', 0.5, 2.8, 26.9, 48.9, 20.9, '0.529810,0.327016,-1.045784,0.190018,-0.007787,-0.145807,0.827778,0.085998,-0.350828,-0.154174,0.013057,0.248959,-0.365708,0.525258,0.227429,0.167880,-0.414843,-0.791269,-0.252508,-0.062504,-0.300231,-0.058648,-0.143914,-0.094336,-0.171421,0.055465,0.305481,0.343473,-0.091480,0.337897,0.333657,0.046532,-0.110304,0.649397,-0.332272,0.047378,0.029398,0.026789,-0.163381,-0.046845,-0.013508,-0.523120,-0.257801,0.272795,-0.083115,0.380671,0.384530,-0.082488,-0.163999,0.104658,0.379025,-0.340652,-0.218376,0.486174,0.547848,-0.035062,0.291628,0.016555,-0.106400,-0.081131,-0.000421,-0.034976,-0.700956,0.131083,-0.213452,0.039427,-0.398285,0.678596,-0.307813,0.126107,0.082270,-0.348351,0.566054,0.316634,0.006271,0.464674,0.007968,-0.073573,-0.731798,-0.075754,0.632703,-0.249340,-0.123895,0.332072,-0.090089,-0.036841,0.164998,-0.088180,-0.385531,-0.144479,0.658091,0.206610,-0.296403,0.157169,-0.197813,0.050130,-0.094219,-0.187035,0.075761,-0.467472,-0.398062,-0.280067,-0.192834,-0.255688,-0.403270,0.228083,-0.037235,-0.152336,0.308284,-0.700605,0.246493,0.357882,0.204624,-0.109636,0.575535,0.187848,0.152595,-0.029606,-0.122628,-0.216564,0.022458,0.560606,0.466082,0.429241,-0.068296,-0.052441,-0.591576,0.280694', '25870679', '1947080', '1292211', '1309125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299327', '夜访吸血鬼', '剧情', '18世纪的路易斯安娜州，丧失妻女痛不欲生的庄园主路易（布拉德·皮特 饰）遇上了吸血鬼莱斯塔特（汤姆·克鲁斯 饰），被其施法变成吸血鬼。路易心存人性，不愿意吸血杀人，靠吸食动物的血为生，而莱斯塔特则一心要把路易斯教导成一个真正的吸血同类。在新奥尔良，路易禁不起诱惑吸了小女孩克萝迪娅（克尔斯滕·邓斯特 饰）的血，而莱斯塔特则不顾路易斯的反对把克萝迪娅也变成了吸血鬼。三个人组成了一个奇特的家庭。几十年过去了，克萝迪娅开始怨恨莱斯塔特剥夺了他真正的人生，她设计杀死了莱斯塔特，和路易周游世界，过着既像父女、又像情人的生活，寻找同类，也寻找着自身存在的意义。在巴黎，他们遇上了以阿蒙（安东尼奥·班德拉斯 饰）为首的一群吸血鬼，聚居在剧院地下，过着和他们迥然不同的生活，阿蒙给了路易许多教导，想成为路易的新伙伴，为此，路易和克萝迪娅之间出现了裂痕，最终，酿成了无可挽回的悲剧。1988年，路易斯返回了新奥尔良，向一个年轻记者马洛伊（克里斯琴·斯莱特 饰）讲述了自己的经历，讲述了吸血鬼长生不死背后的哀伤，不料，马洛伊在听完之后却被深深地吸引，一个新的吸血鬼的故事，将由此开始。', '布拉德·皮特', '尼尔·乔丹', 8.3, 272086, 'tt0110148', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1353910572.jpg', 0.2, 1.4, 16.6, 44.4, 37.4, '0.456229,-0.065470,-0.437203,0.521660,-0.232890,-0.527363,1.060865,0.101964,-0.372937,-0.090877,-0.051798,0.813758,-0.181189,0.213793,0.344256,-0.003477,-0.397117,-0.641781,-0.040057,-0.083458,-0.309815,-0.464453,-0.270376,-0.394768,-0.065999,-0.451405,0.277952,0.080143,0.046578,0.448911,0.364785,0.503850,0.090541,0.278616,-0.189042,0.288692,0.229861,-0.182979,-0.004601,0.218925,0.092411,-0.050303,0.005047,0.208500,-0.148276,0.372691,0.571110,-0.496441,0.177787,-0.435303,0.289268,-0.214917,0.139377,0.214716,0.396787,-0.021071,-0.072085,0.160836,-0.105921,0.067889,0.182139,0.074298,-0.788565,-0.100247,-0.029455,0.243868,-0.847140,0.511298,0.112921,-0.112559,-0.020271,-0.311094,0.072879,0.218471,0.205540,0.357890,0.019185,-0.079555,-0.735801,0.234563,0.750081,0.005796,-0.377433,0.122964,-0.178386,-0.429903,-0.077775,-0.329640,-0.371101,-0.182038,0.628652,0.097458,-0.168081,0.432650,-0.813677,-0.180573,-0.406861,-0.247291,0.031371,-0.432403,-0.175984,-0.514230,-0.189711,-0.363585,-0.320231,0.085837,-0.127457,-0.261404,0.675407,-0.731065,0.180543,0.621883,0.377306,-0.317791,0.513248,-0.097249,0.054762,-0.126049,0.113610,0.623887,0.254113,0.232101,0.422028,0.400856,0.112032,0.092160,-0.336980,0.771932', '4944008', '21619567', '1428054', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299330', '爵士春秋', '剧情', '本片是一部音乐歌舞片，集七十年代爵士乐之大成。在1980年第33届戛纳国际电影节上获得金棕榈奖，获52届奥斯卡（1979）最佳服装设计、最佳剪辑，最佳音乐三项金像奖。◇剧情介绍◇作为一个音乐剧迷，即使你不太熟悉金像奖导演Bob Fosse这个名字，我打赌你也一定听说过托尼奖和奥斯卡的大赢家《芝加哥》和《歌厅》，Fosse分别是这两部音乐剧电影版的编剧和导演，他的另一部著名作品就是这部《爵士春秋》。（其实只要稍微留意就可以从《芝加哥》的编舞上发现许多《爵士春秋》的影子，而且《芝加哥》开门见山的第一只曲子就是‘All That Jazz’。）《爵士春秋》可称是Bob Fosse本人的半自传影片，片中的主人公是一位叫Joe Gideon的百老汇资深导演，他天马行空，我行我素，才华横溢，但是由于没有树立起远大的理想和正确的人生观和世界观，工作的压力和情感的放纵使他灰心厌世，健康每况愈下，最后在其作品的歌声舞影中，Gideon哼着《再见我爱》在手术台上踏上了不归之路。人生就是这般无常，Gideon先生可以创造票房奇迹，可以吸引各式各样的女子投怀送抱，但他和我们一样，常常对心灵的空虚和肉体的软弱束然无策。有志趣相投的朋友聊天，有喜欢的文章可读可写，有好听的音乐剧可以欣赏，有幽默的心情可以时常微笑，有不含SARS病毒的空气可以呼吸――不知道这样简单的幸福上天还可以赐我们多久？金曲提示：《在百老汇》(On Broadway)、《自君别后》(After You''ve Gone)、《重焕生机》(Everything Old Is New Again) 、《再见我爱》(Bye Bye Love) 。', '罗伊·谢德', '鲍勃·福斯', 8.6, 9434, 'tt0078754', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2192967650.jpg', 0.6, 1.2, 12.1, 41.9, 44.2, '0.095508,-0.061123,-0.517464,0.703122,0.046697,-0.091188,0.570412,0.113898,-0.297300,-0.023388,0.002623,0.910742,-0.090048,0.080790,0.193857,0.020984,-0.277300,-0.720263,-0.121990,-0.161695,0.113945,-0.490514,-0.378129,0.109805,-0.200632,-0.431611,0.682096,0.018718,-0.522639,0.419170,0.488062,0.013332,0.266642,0.219347,-0.442246,0.078820,0.027702,0.158052,-0.464781,0.395820,0.273215,-0.230759,-0.139483,0.117675,-0.054982,0.193137,0.417918,-0.095304,-0.212322,0.379403,0.716958,-0.216677,-0.059852,-0.080556,-0.062630,0.067921,0.436817,0.275206,-0.028604,0.146381,-0.317155,-0.262098,-1.059809,-0.066074,0.129885,0.320951,-0.410811,0.502300,-0.099965,-0.224252,0.065945,-0.061127,0.313120,0.086901,0.311388,0.315800,-0.042352,0.072297,-0.347313,0.535630,0.616666,0.127970,-0.455888,0.716919,-0.108098,-0.574536,-0.205455,-0.342394,-0.589389,0.189745,0.074720,0.032034,0.067341,-0.223907,-0.429276,0.156869,0.231235,-0.192959,-0.049407,-0.473136,0.094086,-0.487479,-0.194804,-0.456457,-0.036984,-0.245007,0.280741,-0.519070,1.008116,-0.949436,0.310145,0.446092,0.215891,-0.358453,0.989594,0.481016,-0.216276,-0.181400,0.044884,0.035044,-0.277499,0.064211,-0.026078,0.499058,0.353241,-0.298852,-0.671313,0.510273', '27602116', '24284209', '25880986', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299335', '龙之吻', '剧情', '中国特工刘剑（李连杰）受命前往巴黎帮助警察局侦破当地毒品走私集团。由于任务极度敏感，上级并没有告知刘剑具体的任务细节。他到达巴黎后，去见了合作的警察局高级侦探理查德（切基·卡尤 Tchéky Karyo 饰）。刘坚头一次与理查德面对面，就亲眼目睹他将一名嫌犯殴打致死。他实际上是贩毒集团成员，预谋杀害并诬陷刘剑。身手矫健、机智过人的刘坚只身击退了几十名理查德的打手的追击，成功脱身，并结识了美国人洁西卡（布里吉特·芳达 Bridget Fonda 饰）。洁西卡的女儿被理查德挟持，自己也因为吸毒受到理查德的胁迫，成为妓女。因理查德的诬陷，刘剑被指控犯有谋杀罪。他与洁西卡为情势所迫，不得不联手共同对付阴险狡诈的对手......©豆瓣', '李连杰', '克里斯·纳汉', 6.8, 17917, 'tt0271027', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2391098388.jpg', 1.1, 8.1, 51.3, 28.4, 11.1, '0.324995,-0.002707,-0.479203,0.635775,-0.158575,-0.112578,0.505543,0.144077,-0.391155,-0.446574,0.318468,0.567397,0.001691,-0.113217,0.257141,-0.167127,-0.228019,-0.667134,0.021354,-0.032901,-0.183494,-0.737426,-0.186515,-0.217896,-0.028622,-0.283294,0.515176,-0.005402,-0.398173,0.624740,0.541814,0.476070,-0.263874,0.487245,0.166066,-0.055730,0.426867,-0.215197,-0.356457,0.278838,-0.012038,-0.233254,0.106211,0.210826,0.002839,0.612595,0.356551,0.032969,-0.007341,-0.433701,0.158547,-0.519852,0.267680,0.153826,0.503216,-0.160346,0.085364,0.445972,-0.145827,0.021418,0.110590,0.044676,-1.082891,0.156934,0.302633,-0.177844,-0.363731,0.131640,-0.412821,0.207933,-0.060707,-0.031434,-0.102728,0.412139,0.216216,0.026427,0.227212,0.075244,-0.460398,0.113350,0.615140,-0.041027,0.090423,-0.152400,0.020189,-0.554845,0.183176,-0.386244,0.018992,0.078340,0.342166,-0.170364,-0.258873,0.047206,-0.225326,-0.301569,-0.681899,0.127713,-0.155145,-0.299871,0.369335,-0.828444,0.047615,-0.061370,-0.281545,0.004804,0.061023,-0.217203,0.337667,-0.769225,0.078706,0.740591,0.540546,-0.569890,0.237055,0.298139,0.021262,-0.160483,-0.331621,0.363852,0.723020,0.216638,0.122175,0.206476,0.115975,-0.413977,-0.154226,0.133643', '1307442', '27073234', '26352445', '3428500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299361', '爱·回家', '剧情', '为了方便找工作，妈领着7岁的相宇（俞承浩饰）去乡下的外婆家，想把他暂时留在那里。外婆（金亦芬饰）年事已高，不能说话也不识字。而一直生活在城市里的孙子相宇，刚开始无法适应连游戏机、电池都没得卖的乡下生活。他开始蛮横地流露出不满，抱怨这个抱怨那。为了买电池，偷走外婆的银头簪拿去卖；外婆得知孙子想吃炸鸡，却只理解到鸡肉，炖了只鸡给孙子吃，却被生气的相宇踢翻了。老人家默默包容着孙子的一切，渐渐的，相宇也体会到外婆的良苦用心，适应并喜欢上了乡下生活。©豆瓣', '金艺芬', '李廷香', 9.1, 83438, 'tt0312841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2107418134.jpg', 0.3, 0.7, 7.1, 28.4, 63.4, '0.325258,0.116521,-0.698235,0.322629,-0.622584,-0.632038,0.252655,0.396049,-0.306676,-0.186634,-0.317705,0.425351,0.454341,0.448014,-0.332641,0.251220,-0.432339,-0.172628,0.311340,0.042735,-0.010397,-0.208696,-0.096256,-0.171432,-0.116004,0.070062,-0.054819,-0.224779,-0.089901,0.273559,-0.000862,-0.372682,0.291322,0.453605,-0.570435,0.155501,-0.475082,-0.037819,-0.225823,-0.020837,0.408981,-0.114050,-0.120005,0.145228,0.539080,0.276426,0.492825,0.129309,-0.260267,0.006853,0.075860,0.022732,-0.127195,0.175168,-0.066371,0.070472,0.205879,-0.184149,-0.289116,0.325532,0.066467,-0.025154,-0.445442,0.081686,-0.182083,0.135292,-0.755377,0.557484,-0.079574,-0.201845,0.035831,-0.661682,0.383081,0.077558,-0.158493,0.721534,-0.294244,0.182439,-0.576425,0.330048,0.492236,-0.440959,0.209070,0.298963,-0.116153,0.074351,0.330112,-0.599447,-0.696377,-0.037917,-0.184234,0.226649,-0.538539,-0.030800,-0.565517,0.129181,0.287432,-0.563983,0.379110,-0.511779,-0.279090,0.017326,0.068746,-0.461632,-0.372499,-0.137381,0.171771,-0.393057,0.507707,-0.464654,0.343328,0.536785,0.459788,-0.498755,0.552540,0.078709,-0.073741,-0.130142,-0.122123,-0.042748,-0.036293,0.352938,0.422628,0.279508,0.098288,-0.212759,-0.532160,0.381471', '1306019', '1291565', '1305175', '2139766');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299362', '保镖', '剧情', '弗兰克（凯文•科斯特纳 Kevin Costner 饰）是前总统的保镖，他责任心强，公私分明，从不和雇主发生感情。但是歌手雷切尔（惠特尼•休斯顿 Whitney Houston饰）却打破了他的信条。雷切尔是一个魅力非凡的女歌星，无数人甘愿做她的裙下之臣。这天她收到匿名信，恐吓说要杀掉她。雷切尔惟有请来弗兰克做保镖。尽管二人之前并不认识，但在相处中，弗兰克还是被雷切尔的魅力征服，二人堕入爱河。然而职业的操守和理智，让弗兰克变得自制。他认为雷切尔是雇主，他的首要任务是保护她的安全，他刻意和雷切尔保持一定的距离，这一切伤透了雷切尔的心。她怀疑弗兰克的真情时，弗兰克却给了她一个坚定的答案。©豆瓣', '凯文·科斯特纳', '米克·杰克逊', 7.9, 77160, 'tt0103855', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1679820460.jpg', 0.2, 1.6, 24.3, 50.9, 23, '0.233465,0.149252,-0.717409,0.706427,-0.516725,-0.312670,0.868504,0.080172,-0.431201,-0.296912,0.180911,0.826025,-0.027829,-0.033979,0.210403,0.232000,-0.211335,-0.749793,-0.069509,-0.073570,-0.012925,-0.585598,-0.333568,-0.233735,-0.195774,-0.207793,0.448870,-0.007591,-0.147135,0.292471,0.394393,0.203025,0.388656,0.716680,0.082229,-0.064937,0.236549,-0.373315,-0.169116,0.087835,0.179216,-0.147439,-0.194136,0.466070,0.033155,0.616347,0.182654,-0.068469,-0.338083,0.114966,0.262856,-0.433451,0.189976,0.185839,0.008119,-0.013662,0.021210,0.441574,-0.217011,-0.050397,-0.007187,-0.002900,-0.957581,0.073187,0.103873,0.250949,-0.601861,0.511096,-0.432382,0.070898,-0.032949,-0.187690,0.141024,-0.146694,0.255963,0.223673,-0.050512,-0.070289,-0.425916,-0.060623,0.843390,0.065590,-0.408664,0.323845,-0.571392,-0.459711,-0.110617,-0.129292,-0.639251,-0.035277,0.154292,0.008592,-0.098538,0.035875,-0.306754,-0.194736,-0.350185,0.072468,-0.444808,-0.744621,0.120883,-0.123552,-0.264287,-0.698633,-0.629196,-0.153734,-0.034959,-0.380746,0.778480,-0.906273,0.115799,0.648915,0.307724,-0.587741,0.708370,0.344564,0.005331,-0.083143,0.004891,0.312166,0.035136,-0.023862,0.037277,0.396402,0.244064,-0.072922,-0.209336,0.506424', '6874741', '30163500', '1303112', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299365', '菊豆', '剧情', '杨天青（李保田饰）的叔叔杨金山（李纬饰），是个有生理缺陷的染坊主，在折磨死两房太太后，为续香火，他又花大价钱买了个年轻漂亮的女人菊豆（巩俐饰），对其百般虐待。年近四十而尚未娶亲的天青，对因叔叔每夜滥施淫威而痛苦哀叫的菊豆由怜生爱，两人私通，生得一子。金山喜出望外，以为己出，取名天白。但不久金山中风，半身不遂，菊豆与天青更加肆无忌惮，得知真相的金山想要报复，后却误坠染池丧命。按家族的规矩，天青要搬出染房，被迫分离的菊豆与天青只能暗地来往。10多年后，天白长大，外人的闲言琐语使他分外仇恨生父……©豆瓣', '巩俐', '张艺谋', 8.2, 100471, 'tt0099902', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2331293839.jpg', 0.2, 0.8, 16.2, 55, 27.7, '0.031720,0.019548,-0.536468,0.338031,-0.008080,-0.395044,0.507497,0.315275,-0.567953,-0.111461,0.355522,0.591462,-0.058216,0.103862,-0.109355,0.143808,0.136238,-0.251550,0.097007,-0.114129,0.084460,-0.300926,0.060426,-0.022473,-0.276558,-0.121115,0.316687,-0.253511,0.073026,0.529774,0.431576,0.252405,0.247627,-0.033756,-0.252021,0.116569,-0.274393,0.181106,-0.305997,0.138665,0.028952,-0.098725,-0.056815,-0.087315,-0.311146,0.339370,0.496896,-0.157085,-0.341310,-0.192498,0.283544,-0.244435,-0.150122,0.304499,0.268881,-0.300299,0.328456,0.354815,-0.516265,-0.215240,0.048632,0.321473,-0.194187,-0.004708,0.409401,-0.100838,-0.620013,0.306968,-0.069456,-0.085404,-0.226361,-0.622196,0.136013,0.324051,0.099795,0.433936,-0.552813,-0.190608,-0.687063,0.173806,0.416373,-0.215290,0.134995,0.321230,-0.127991,-0.027011,0.454298,-0.616991,-0.534480,-0.094406,0.358671,-0.229848,-0.223930,0.302249,-0.394675,-0.073752,-0.408986,0.076102,-0.094321,-0.221826,-0.121828,0.142183,-0.401164,-0.588807,-0.039462,-0.022789,0.228424,-0.042032,0.672698,-0.504713,0.577662,0.166686,0.325473,-0.769471,0.496232,0.258046,-0.028307,-0.140963,0.098464,0.000505,0.025202,0.020389,-0.067191,0.096567,0.160966,-0.117018,-0.068613,0.088751', '1291565', '1421278', '1394163', '1301221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299367', '三狼奇案', '犯罪', '本片根据香港60年代轰动一时的“三狼案”改编。混迹于各种下层场所的无照化妆师马二灿（郑则仕 饰）、驾驶教练邓子敬（徐锦江 饰）和商社服务生李怀（梁家辉 饰）三人年少时结为兄弟，如今靠马二灿工作之便，他们时常坑蒙拐骗，然而三个底层市民的小把戏被李怀之老板发现后每每被当场拆穿并遭辱骂。李怀又因舞女情妇与老板的公子发生冲撞，三人心怀愤懑，遂计划绑架老板家公子勒索，不料计划被赌徒蛇仔明偷听，于是当夜只得带上蛇仔明匆忙行动，他们得手后不慎将老板公子打死，勒索不成四人再度绑架老板本人，终于得逞，然而一张悲剧的网也逐渐向他们收拢……©豆瓣', '梁家辉', '黄泰来', 7.4, 7291, 'tt0098250', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2168061359.jpg', 0.6, 3.2, 37.6, 43.7, 14.8, '0.383993,-0.219604,-0.247314,0.084578,0.106179,-0.389240,0.403916,0.190539,-0.414108,-0.198690,0.452030,0.599372,-0.427797,0.059585,0.502963,-0.322909,-0.231991,-0.573678,-0.022563,0.080466,0.293408,-0.234327,0.025286,-0.159502,-0.223931,-0.063913,0.371813,0.011018,-0.110004,0.505364,0.295539,0.312972,-0.569710,0.402987,0.210358,0.304654,0.184209,-0.222752,-0.346026,0.059051,-0.135920,-0.442323,0.037927,-0.118152,-0.012002,0.391866,0.656856,-0.311714,-0.324743,-0.324012,0.310880,-0.261449,0.013237,0.173825,0.301473,0.075576,0.483244,0.307026,-0.145713,-0.025261,0.228012,0.230024,-0.156649,0.221565,0.274076,-0.213641,-0.312632,-0.019615,-0.025785,0.218894,-0.140465,-0.287737,0.304334,0.171955,0.457752,-0.058808,0.072206,-0.015313,-0.383061,0.053747,0.442075,-0.101392,0.230012,0.098169,0.266566,-0.251423,0.437620,-0.257938,-0.100518,0.051730,0.366117,-0.004394,-0.128885,0.017822,-0.461067,-0.217349,-0.358720,0.170510,0.088741,-0.324363,0.015298,-0.590541,-0.071299,-0.020214,-0.017647,0.145321,0.379230,0.070841,0.145216,-0.638874,-0.027496,0.255581,0.182920,-0.514815,0.208060,-0.199202,0.043610,0.096867,-0.195861,-0.385726,0.501681,0.374392,0.054408,0.225239,-0.027459,-0.380257,0.116412,-0.159425', '1309194', '25723905', '1292506', '3387546');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299374', '我左眼见到鬼', '喜剧', '何丽珠（郑秀文饰）去加勒比海度假，遇上了一名相貌堂堂知书识礼的男子，虽然才相识7天，二人还是闪电结婚。然而好景不长，男子在潜水中不幸丧生，令何丽珠悲伤万分。这段闪电的姻缘却没有让丽珠很快地忘掉丈夫。她沉浸在生活的阴影当中，久久不能自拔。一天她竟偶然发现，自己左眼可以见到鬼。在此之后，丽珠遇见王劲威（刘青云饰）。他自称是丽珠的小学同学，曾经对她非常的倾心。丽珠开始时嫌他麻烦，然而和他相处过程中，却屡屡得到他的帮助劝慰，让她快点医好丈夫逝去的心病。在王劲威要去投胎之前，丽珠想让他找来丈夫，见上一面，然而王劲威没能找回来。然而，丽珠却慢慢发现，自己的心愿其实并没落空，而且生活的希望也在一点点的回到她的心中。©豆瓣', '郑秀文', '杜琪峰', 7.6, 75085, 'tt0319901', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2003160703.jpg', 0.6, 4.1, 33.6, 39.2, 22.5, '0.003677,0.053649,-0.946590,0.475215,-0.172626,-0.671765,0.937649,-0.135965,-0.618416,-0.438468,0.034039,0.582440,-0.168160,0.321224,0.081649,0.017062,-0.184112,-0.616823,0.228882,-0.183437,-0.299240,-0.117972,-0.283757,0.065920,-0.213981,-0.230568,0.663107,0.247513,-0.003390,0.513156,0.060480,0.107666,0.041490,0.820823,-0.490732,0.050177,-0.324519,0.339854,-0.147947,0.242359,0.279221,-0.398979,-0.477733,0.299981,-0.113482,0.335470,0.603546,-0.166419,-0.214950,0.207261,0.225173,-0.272015,0.037095,0.033146,0.010752,-0.092410,0.169007,0.037341,-0.398459,-0.219832,-0.099040,-0.008969,-0.563075,0.261028,-0.079639,0.138575,-0.618386,0.414001,-0.037885,0.056131,0.039869,-0.493136,0.204643,0.224887,0.277886,0.312393,-0.488842,0.138055,-0.564645,0.238447,0.784840,0.080337,0.007332,0.615271,-0.015604,-0.380185,0.080922,-0.010300,-0.444326,0.131877,0.132974,0.353807,-0.506636,0.059858,-0.264352,0.135325,-0.430417,-0.027695,-0.081912,-0.473503,-0.103810,-0.224206,-0.204979,-0.318115,-0.505989,0.053411,-0.065935,-0.433123,0.465967,-0.921329,0.363215,0.496031,0.150878,-0.528826,0.873030,0.417548,-0.062250,-0.187364,-0.071623,0.341847,-0.015843,0.163579,0.214858,0.176390,-0.087051,0.022570,-0.548699,0.428637', '1292211', '1308755', '1302384', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299378', '单身汉', '喜剧', '身为一个单身汉，杰米（克里斯·奥唐纳 Chris O''Donnell 饰）感到十分自豪，对于婚姻所带来的束缚和牵制，他避之不及。一个人的不婚主义并不代表他不能追逐爱情，安娜（芮妮·齐薇格 Renée Zellweger 饰）的出现让杰米迅速坠入了爱河。一转眼3年过去，迫于各方面的强大压力，杰米终于决定走进婚姻的围城。没想到，自己不诚恳的求婚誓言惹恼了安娜，安娜选择了离去。杰米的祖父去世了，留下了一亿美元的遗产，根据遗嘱，杰米必须再30岁之前结婚成家才能够得到继承的权利，而此时距离杰米30岁的生日只有24个小时了。如何在一天之内找到一个情投意合的新娘？又如何辨别这位新娘到底是爱杰米本人还是爱他的钱？杰米在安娜和诸多前女友之间迷失了方向。此时的他才意识到，结婚是一件非常神圣而严肃的事情。©豆瓣', '克里斯·奥唐纳', '加里·辛纳尔', 6.5, 5686, 'tt0120596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1251494174.jpg', 1.4, 9.4, 59.9, 23.8, 5.5, '0.259039,0.079933,-0.695860,0.458618,-0.375573,-0.541962,0.755358,-0.012792,-0.338346,-0.435786,0.150434,0.906021,-0.030742,0.212039,0.338963,0.216927,-0.278835,-0.604862,0.112607,-0.282085,-0.276967,-0.561937,-0.095745,-0.038339,-0.183857,-0.183953,0.612957,-0.059892,0.060140,0.381381,0.393566,0.325180,0.165560,0.539287,0.018687,0.028974,0.176179,0.087104,-0.253269,0.266048,0.046103,-0.035858,-0.006441,0.375709,-0.124949,0.295305,0.400999,-0.326887,-0.240446,-0.112645,0.537114,-0.239793,-0.224287,0.261130,0.133722,-0.140350,0.191109,0.209582,-0.311363,-0.038818,-0.020109,-0.081058,-0.771969,0.047657,0.004728,0.196476,-0.638887,0.403298,-0.267670,-0.246397,0.178280,-0.570712,-0.167218,0.518009,0.259962,0.606760,-0.573574,0.034787,-0.609224,-0.161564,0.863522,0.061853,-0.146546,0.328859,-0.266097,-0.517327,-0.008082,-0.115713,-0.433312,0.055042,0.348246,0.492021,0.016695,0.249559,-0.301771,-0.203325,-0.405579,-0.241738,0.077202,-0.808870,-0.008690,-0.132513,-0.274306,-0.420318,-0.300339,0.152509,0.112964,-0.421719,0.588090,-0.798726,0.282340,0.412819,0.613906,-0.537077,0.740495,0.464954,0.107139,-0.447618,0.209197,0.462905,-0.169114,0.013732,0.022091,0.143415,0.294919,-0.126695,-0.290195,0.634394', '25721544', '1296569', '1456503', '1304977');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299383', '最后的武士', '剧情', '美国内战结束的十年后，当年的南北战争英雄纳森（汤姆•克鲁斯 Tom Cruise）因无所事事而终日酗酒。一次偶然的机会，他结识了来美做生意的日本商人。纳森的彪炳战绩令对方刮目相看。此时正值明治维新时期，日本天皇意欲训练一支现代化的作战部队，于是纳森被请到了日本。日本很 多武士都不欢迎纳森的到来，他们坚决不肯抛弃传统的武士道精神，对将武士西化十分反感。他们在首领乌吉奥（渡边谦 饰）的带领下举刀起义，躲到了一条偏僻的小山村自立为政。天皇大怒，派纳森率领他训练出来的现代化军队去围剿叛变武士。岂料皇军全军覆没，纳森亦成为了阶下囚……©豆瓣', '汤姆·克鲁斯', '爱德华·兹威克', 7.9, 73159, 'tt0325710', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p860163476.jpg', 0.5, 2.6, 23.9, 46.3, 26.6, '0.155210,-0.063055,-0.689396,0.501029,-0.013240,-0.273296,0.327582,0.034400,-0.464238,-0.337137,0.355541,0.638443,0.237198,-0.143342,0.307627,-0.229645,-0.068138,-0.469537,-0.195965,-0.044464,-0.128706,-0.245351,-0.126188,-0.504192,-0.364485,-0.306177,0.576200,0.201107,-0.160870,0.637884,0.213285,0.303373,0.313194,0.478178,-0.116889,-0.169924,0.180782,-0.418296,-0.204260,0.195021,-0.264032,-0.284807,-0.215313,0.492858,-0.037803,0.191047,0.590983,-0.350725,0.038815,-0.267759,0.262022,-0.397040,-0.233735,0.194900,0.676863,0.019677,-0.078645,0.116416,0.227324,0.099866,-0.447216,-0.158402,-0.553540,0.071710,-0.151363,0.004490,-0.630279,0.714143,-0.171586,0.053896,0.008896,-0.258337,-0.006108,0.500997,0.163057,0.032465,0.134781,0.271359,-0.597742,0.291112,0.833106,-0.215469,-0.161751,-0.204139,-0.135656,-0.476180,0.051225,-0.589739,-0.417807,-0.119806,0.264910,-0.499470,-0.046661,0.177610,-0.626377,0.016344,-0.498314,0.005705,0.125505,0.018926,0.063139,-0.530694,0.120492,-0.314661,-0.140994,0.305366,0.112136,0.131021,0.776767,-0.663125,-0.092096,0.507654,0.231846,-0.554978,0.401252,0.064728,-0.074032,0.001431,-0.095004,0.442391,0.305554,0.324611,0.266188,0.380370,0.017477,-0.317933,-0.137175,0.218709', '25721544', '35030151', '1826173', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299398', '大话西游之月光宝盒', '喜剧', '孙悟空（周星驰）护送唐三藏（罗家英）去西天取经路上，与牛魔王合谋欲杀害唐三藏，并偷走了月光宝盒，此举使观音萌生将其铲除心思，经唐三藏请求，孙悟空被判五百年后重新投胎做人赎其罪孽。五百年后孙悟空化身强盗头头至尊宝。当遇见预谋吃唐僧肉的妖怪姐妹蜘蛛精春三十娘（蓝洁瑛）和白骨精白晶晶（莫文蔚）时，因为五百年前孙悟空曾与白晶晶有过一段恋情，至尊宝与她一见钟情，但因菩提老祖将二人妖怪身份相告，至尊宝仍带领众强盗开始与二妖展开周旋，过程中，白晶晶为救至尊宝打伤春三十娘，自己也中毒受伤，为了救白晶晶，至尊宝去找春三十娘，遭白晶晶误会，绝望自杀，至尊宝开始用月光宝盒以期使时光倒流。©豆瓣', '周星驰', '刘镇伟', 9, 1145094, 'tt0112778', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561721372.jpg', 0.2, 0.5, 7.4, 31.8, 60.1, '-0.188262,-0.082543,-0.373788,0.276575,0.031891,-0.554580,0.376537,-0.291852,-0.389446,-0.144297,-0.145787,0.306932,-0.326065,0.322627,-0.051292,-0.178820,-0.038792,-0.363493,-0.073647,-0.117873,0.182806,0.143722,0.033092,0.139556,-0.270838,-0.142363,0.439241,-0.249995,0.093812,0.374905,0.413591,0.200621,-0.508628,0.019773,-0.038768,0.500090,-0.357635,0.175822,-0.379914,0.235366,0.035172,-0.328971,0.004534,-0.113670,-0.333888,0.403274,0.440816,-0.396000,-0.231527,-0.690071,0.077791,-0.070876,-0.120162,0.285017,0.309604,-0.026484,0.317808,0.375684,0.110156,-0.047148,-0.071586,-0.120752,-0.176304,0.086704,0.051111,-0.291293,-0.321254,-0.123955,0.034962,0.457598,0.105087,-0.035693,0.099035,0.251523,0.406041,0.050997,-0.243788,-0.394317,-0.355839,0.280881,0.644284,-0.298650,0.621796,0.225912,0.560369,-0.179692,0.276275,0.166382,0.230371,0.335063,0.285619,0.052837,-0.255858,0.293825,-0.365151,-0.521617,-0.523671,0.583523,-0.175000,-0.081839,0.217258,-0.283513,0.040347,0.073261,-0.189970,-0.378706,0.472820,-0.140304,0.340719,-0.218637,0.325037,0.187000,0.245679,-0.604951,0.428690,-0.093687,0.177760,-0.446025,0.017919,0.213975,-0.035718,0.342192,0.382001,-0.128276,-0.043351,0.267447,-0.231076,-0.037957', '25827963', '1297763', '1304021', '1301946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299408', '醉画仙', '剧情', '19世纪50年代，朝鲜面临内忧外患，人民生活艰苦。被人殴打的乞丐少年张承业被书生金柄文（安圣基饰）所救，二人结下终生不解的友谊。在金柄文的朋友李凝轩（韩明求饰）的帮助下，他在大画院正式拜师学画。五年后，张承业（崔岷植饰）凭着自己过人的天分，开始学有所成，离开了老师闯荡 天下。一次偶然的机会，张承业结识了青楼女子梅香，为她在群摆上画了梅花，并题写了“梅花一生不卖香”的字句。不久，他来到初恋情人李凝轩的妹妹素云（孙艺珍饰）家中，为久病的恩人作了一副《仙鹤图》。李凝轩离去后，张承业告别素云。当时的社会非常鄙视作画的文人，失意的张承业只得继续云游四方，陶冶性情。©豆瓣', '崔岷植', '林权泽', 7.5, 7635, 'tt0317234', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459548165.jpg', 0.5, 3.1, 33.6, 44.8, 17.9, '0.135419,0.013233,-0.375345,0.476593,-0.237245,-0.398567,0.326442,0.256645,-0.581411,-0.145416,0.378308,0.827705,-0.189347,0.355612,0.289740,-0.049759,-0.113902,-0.603402,0.131248,-0.330757,-0.204174,-0.221478,0.135283,-0.236579,-0.345400,-0.209736,0.516862,0.079467,0.032393,0.507054,-0.075639,-0.029428,0.100765,0.207062,-0.436482,0.270415,-0.137877,0.008351,-0.381194,0.074727,0.023081,-0.462998,-0.355930,0.066596,-0.049878,0.061500,0.733328,-0.177616,-0.039791,-0.269418,0.372281,-0.020713,0.042474,0.100245,0.089461,0.081145,0.176805,0.278121,-0.232512,0.001521,-0.140914,-0.403725,-0.209628,0.135583,0.200209,0.018445,-0.716339,0.885126,-0.020049,-0.067216,-0.101514,-0.279625,-0.104952,0.425312,0.370005,0.402639,-0.030204,0.207915,-0.415848,0.526626,0.427427,0.076347,-0.058867,0.431658,-0.124080,-0.196348,0.197419,-0.190982,-0.278008,-0.125695,0.390316,-0.095744,-0.243741,0.032411,-0.648356,0.098535,-0.276484,0.328169,0.131773,-0.205635,-0.300095,-0.456280,-0.102513,-0.254307,-0.287922,-0.076108,0.203727,-0.355852,0.887037,-0.719094,0.209596,0.124081,0.258326,-0.475298,0.690208,0.107479,-0.071455,-0.125401,-0.090313,0.409869,-0.043776,0.437067,0.141200,0.220567,-0.157884,-0.029198,-0.091708,0.294464', '1308609', '1296044', '3811356', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299433', '亚特兰大号', '剧情', '故事从一场婚礼开始，驳船亚特兰大号的船长迎娶了漂亮的乡下姑娘朱丽叶。婚后，朱丽叶开始了全新的船上生活。一开始她对船上生活感到新鲜有趣，和丈夫的相处也甜甜蜜蜜，然而很快她便厌倦了这种单调枯燥的生活，渐渐地向往起大城市巴黎的热闹繁华。船长为了满足朱丽叶，将亚特兰大号开往巴黎。然而期间发生种种波折，导致船长迟迟没有带朱丽叶去巴黎，二人的矛盾日渐加深。不久，朱丽叶悄悄离开了亚特兰大号，独自去了巴黎，船长得知后生气地驾船而去。分开后船长对朱丽叶无限思念，终日神不守舍。孤零零一人流落在巴黎的朱丽叶，最终会选择留在灯红酒绿的巴黎，还是回到亚特兰大号上，回到深爱自己的丈夫身边？©豆瓣', '米歇尔·西蒙', '让·维果', 8.1, 5718, 'tt0024844', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1821233512.jpg', 0.4, 1.7, 19.1, 50.2, 28.6, '0.194814,0.196817,-0.807972,0.277299,0.208464,-0.449440,0.802272,0.165828,-0.633059,0.189127,0.190398,1.014378,-0.071833,0.560908,0.532729,0.257503,-0.805294,-0.569260,0.028043,-0.250787,-0.318363,-0.460257,0.176401,-0.077327,0.066948,-0.136178,0.424544,0.231167,0.226358,0.912630,0.214220,0.100763,-0.132338,0.783788,-0.320195,0.144028,0.052693,0.052789,-0.467276,0.183448,0.190233,-0.106489,-0.250233,-0.048136,0.114354,0.111022,1.023079,-0.095530,-0.162440,-0.095538,0.388049,0.086598,-0.051451,0.048807,0.097150,0.258113,-0.222720,0.003951,-0.407758,-0.084761,-0.212995,-0.025461,-0.046832,0.331839,-0.025672,-0.036506,-0.484825,0.441511,0.012242,-0.018219,0.375349,-0.402694,0.323764,0.551345,0.307732,0.311588,0.049026,0.309381,-0.301161,0.229680,1.058593,0.028379,-0.079732,0.458615,0.056410,-0.140359,-0.016739,-0.270507,-0.529730,-0.168914,0.263716,0.037742,-0.193211,0.313041,-0.851971,0.266177,-0.258032,-0.278960,0.298897,-0.327642,-0.082331,-0.634382,0.053068,-0.371927,-0.111246,-0.012885,-0.171665,-0.095125,0.554449,-0.832637,0.481876,0.604072,0.277099,-0.486279,0.652384,0.182660,0.237025,-0.157272,0.261276,0.709477,-0.277862,0.469214,-0.133695,0.301531,-0.091660,0.189828,-0.583755,0.547676', '26687241', '2365260', '1298346', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299436', '风柜来的人', '剧情', '阿清（钮承泽）、阿荣（张世）等男孩生于风柜长于风柜，他们在高中毕业后等待征兵的日子里百无聊赖，每日通过赌博、打架、看白戏等形式来挥霍过量的精力。因为一次较严重的打架事件，也因对周遭环境的厌倦，他们怀揣几颗忐忑的心，离开风柜来到高雄。起始，自然只能如迷途羔羊般，在大都市的五光十色中乱撞。在阿荣姐姐的帮助下，他们有了暂时的栖身处。而安稳下之后，阿清和阿荣因渐形成不同的世界观产生分歧。一封家书勾起阿清有关父亲的复杂回忆，加上眼见爱慕对象小杏（林秀玲）与男友（庹宗华）情感变故，阿清沉默了下来。©豆瓣', '钮承泽', '侯孝贤', 8.4, 42332, 'tt0085533', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2197299205.jpg', 0.1, 0.6, 12.3, 53.7, 33.3, '0.308003,0.002394,-0.750551,0.314873,0.161962,-0.177408,0.818619,0.183214,-0.595036,-0.147347,0.050347,0.411397,-0.165430,0.267222,0.073458,-0.340389,-0.445746,-0.568591,-0.096984,-0.248387,-0.224700,-0.385273,-0.007625,-0.045926,-0.168731,-0.293209,0.407685,0.120077,-0.038281,0.621405,0.026416,0.196301,-0.320484,0.487418,-0.085289,-0.051251,-0.280047,0.214829,-0.455432,0.091542,0.256331,-0.285703,-0.140990,-0.111740,0.225504,0.292058,0.732077,-0.292766,-0.291479,-0.057998,0.046982,-0.085726,-0.131805,0.207908,0.172479,0.276594,0.178997,-0.026617,-0.494384,0.130446,-0.157795,-0.064454,-0.389821,-0.140150,0.125905,0.289097,-0.439818,0.528741,0.277017,-0.301924,0.051644,-0.340046,0.186702,0.365721,0.379022,0.389947,-0.321780,-0.001125,0.012934,-0.051298,0.608995,0.054901,-0.060121,0.425378,-0.250627,-0.188459,0.030697,-0.045656,-0.462972,-0.179761,0.153939,0.147083,-0.324578,0.228770,-0.387263,0.086008,0.029059,-0.237621,-0.141585,-0.424122,-0.115476,-0.517875,0.022455,-0.446179,-0.275032,0.172271,0.290252,-0.245811,0.495305,-0.752024,0.394874,0.272048,0.162447,-0.437499,0.296771,-0.058111,0.184584,-0.158978,0.075024,0.276771,-0.051148,0.327082,0.076684,0.177244,-0.273679,0.159998,-0.373398,0.327596', '2365260', '3111650', '1302488', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299441', '股疯', '剧情', '1992年，炒股热悄悄在上海兴起。许多老百姓厌倦了平凡无味的生活，开始纷纷投入这个让人疯狂失常的怪圈中。香港男人阿伦（刘青云 饰）热衷赚钱，因此忽略了女友安娜的感受。随着时间的推移，两人的关系逐渐出现裂痕。安娜不辞而别来到上海，阿伦于是追来这里。失望的阿伦在上海小青年三宝的介绍下，权且借炒股打发时间，也因此结识了公交车售票员阿莉（潘虹 饰）。阿莉和丈夫、女儿住在底层的弄堂里，邻里间吵架拌嘴不断，生活条件迟迟得不到改善。凭借阿伦的指点，阿莉终于尝到日进斗金的快感，她的生活逐渐改善，周围人也对她尊敬有加，只是在这一过程中她渐渐成为股票和金钱的奴隶，沉湎其中，无法自拔……©豆瓣', '潘虹', '李国立', 7.8, 12067, 'tt0109946', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230452235.jpg', 0.3, 1.9, 27.2, 48.6, 21.9, '0.231545,0.118949,-0.651443,0.329537,-0.101388,-0.283293,0.733454,0.173628,-0.679212,-0.055590,0.015376,0.548459,-0.221348,0.329791,0.298894,-0.091486,-0.447800,-0.683987,0.163127,-0.215382,-0.142318,-0.313910,-0.225711,-0.312413,-0.420243,-0.199846,0.371145,0.059097,-0.033404,0.681104,0.000748,-0.056430,0.020556,0.649761,-0.097573,0.171758,0.198464,-0.084800,-0.314391,-0.095498,0.043314,-0.287538,-0.018434,-0.096001,0.230628,0.266814,0.716110,0.029825,-0.036767,-0.008644,0.320328,0.051688,-0.182754,-0.199654,0.174321,0.147291,0.293591,-0.051682,-0.348479,0.052579,-0.252830,0.082229,-0.443612,0.228126,-0.021098,0.074118,-0.624297,0.386249,0.184256,-0.162300,-0.071115,-0.318959,0.054848,0.381037,0.123810,0.294325,-0.411211,0.034710,-0.222138,0.230944,0.740512,-0.036755,-0.273663,0.514123,-0.387200,-0.164258,0.088526,-0.029764,-0.294473,-0.505838,0.164154,0.244828,-0.218264,0.405010,-0.585137,0.209158,0.026815,-0.204066,0.115470,-0.353047,-0.138757,-0.653379,-0.394510,-0.466248,-0.200153,-0.039570,-0.069069,-0.222379,0.638905,-0.682216,0.287732,0.670629,0.465478,-0.489166,0.774543,-0.086894,0.174535,-0.173216,-0.157780,0.289936,-0.232072,0.221671,0.157092,0.233916,-0.192637,0.121522,-0.085854,0.525148', '26687241', '3111650', '1309172', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299481', '查令十字街84号', '剧情', '女作家海伦（安妮·班克罗夫特 Anne Bancroft 饰）住在纽约，她常常为自己不能买到所需的珍稀图书而沮丧。偶然，她在一本杂志上发现一则来自一家英国旧书店刊登的广告，便抱着试探的心态给这家位于伦敦查令十字街84号的马克书店老板写了求书单。很快，马克书店给了她一个超乎想象的惊喜：她买到了自己一直苦苦寻找的珍品书籍，并且还获得了弗兰克（安东尼·霍普金斯 Anthony Hopkins 饰）对书籍珍本的诚意推荐。自此，两个热爱书籍的人开始了长达20年的书信来往。海伦不仅向弗兰克求购难寻书籍，还与他分享自己的读书心得。两人互相交流文学观点，评述名家作品。弗兰克奔波四处为海伦购买书籍珍本，海伦则从美国寄来丰盛食物，为书店员工们缓解因英国实物配给制而造成的食物匮乏难题。两人通过持续书信来往成为精神至交。海伦一直想前往伦敦拜访弗兰克，却因为各种突发情况而未能如愿。直到她收到弗兰克去世消息的书信，她才终于坐上了飞往英国的飞机，而此时，查林十字街84号的马克书店却面临着被拆迁……', '安妮·班克罗夫特', '大卫·休·琼斯', 8.6, 20757, 'tt0090570', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1188142682.jpg', 0.1, 0.6, 10.8, 43.7, 44.8, '0.363794,0.040434,-0.613125,0.677864,0.372356,-0.457402,0.493701,0.193559,-0.513933,-0.337191,0.130429,0.661980,-0.148717,0.341702,0.181376,0.082866,-0.525733,-0.547582,0.399260,-0.256413,-0.261352,-0.314282,-0.292623,-0.480656,-0.198325,-0.295124,0.280385,0.095087,-0.208683,0.486783,-0.032281,0.215540,0.038178,0.534297,-0.331335,-0.080402,0.208318,-0.064861,-0.231012,0.303075,0.155582,-0.422425,-0.262835,0.139801,0.336135,0.236135,0.790103,0.030796,-0.150198,0.214700,0.382267,0.047839,0.166417,0.133219,0.180593,0.331092,0.186572,-0.009814,-0.497518,0.204129,0.029145,-0.120106,-0.617650,-0.058850,-0.093339,0.193053,-0.436976,0.523438,-0.479596,0.128263,-0.143976,-0.526148,0.003747,0.318295,0.006343,0.291784,-0.028166,-0.039485,-0.337586,0.222565,0.189815,-0.048302,0.045608,0.276396,-0.311540,-0.332324,0.207999,-0.048294,-0.382869,0.010427,0.383408,0.080509,0.104082,0.059660,-0.929801,0.009111,-0.231577,-0.523691,0.343345,-0.236624,-0.210209,-1.088796,-0.022297,-0.070287,-0.210104,-0.181194,0.401658,-0.277751,0.979115,-0.332854,0.168624,0.591297,0.153578,-0.584236,0.790856,-0.233779,-0.104277,-0.039233,-0.190187,0.146419,0.074167,0.481611,0.183841,0.1