INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299495', '惊声尖叫2', '惊悚', '血雨腥风再度向温莎学院袭来！一对儿学生情侣在观看恐怖电影时被头套面具的凶徒当众杀死，而台下观众在案发时以为是电影造成的一场玩笑而无人制止。另一方面，希德妮（内芙•坎贝尔 Neve Campbell 饰）现在已经是克兹镇上的知名人物，在卡顿维瑞因魏盖尔的新书无罪释放后，媒体和警方再次将注意力集中在希德妮身上。同时，面具杀人狂再次大开杀戒，而神秘的电话也继续纠缠希德妮和她身边的人。一时间，打大家再次陷入了对未知凶手的恐慌中，而希德妮的男友德瑞克，看上去颇为符合凶手暴露的蛛丝马迹。究竟，面具杀人狂的真身是谁？魏盖尔、兰迪等希德妮的好友或者相关人士，卷入了这场追凶冒险。©豆瓣', '内芙·坎贝尔', '韦斯·克雷文', 6.4, 19520, 'tt0120082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2177125493.jpg', 2, 11.6, 56.9, 22.7, 6.8, '0.400534,0.124909,-0.485278,0.493589,0.193357,-0.154928,0.784096,0.158408,-0.486765,-0.138488,0.057887,0.386771,-0.436934,-0.013298,0.371185,0.083181,-0.740105,-0.903339,-0.186156,-0.220734,-0.438983,-0.313733,-0.168756,-0.276296,0.009688,-0.429887,0.311344,0.073233,-0.307830,0.430047,0.708978,0.559361,-0.281136,0.620828,0.359063,-0.196893,0.164204,-0.314952,-0.239188,0.305272,-0.042180,-0.216254,-0.220034,0.268329,-0.019776,0.192209,0.768378,-0.410325,0.033190,-0.097813,0.336383,-0.512676,0.072552,0.154513,0.304605,-0.349959,0.354395,-0.100449,-0.019340,-0.084881,0.402392,0.102065,-0.419366,0.117125,-0.138437,0.532962,-0.365203,0.270480,-0.101279,-0.132507,0.142057,0.054020,0.281024,0.197176,0.086174,-0.051582,0.010785,-0.408339,-0.371391,0.066768,0.452704,0.235143,-0.018199,-0.063880,-0.064177,-0.445163,-0.183102,0.112374,-0.458490,0.076301,0.622837,-0.082702,-0.114446,0.475201,-0.283011,-0.347820,-0.538362,-0.037513,-0.261793,-0.728041,-0.239474,-0.951679,-0.250562,-0.229602,-0.187026,-0.224414,0.118802,-0.194181,0.332085,-0.899659,-0.017316,0.453013,0.100539,0.048840,0.312388,-0.145255,0.188699,-0.227604,-0.392115,-0.117929,0.408792,0.383805,0.241507,0.336911,0.044599,-0.049683,-0.075847,0.394359', '25723905', '1316693', '1295547', '1306449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299502', '霹雳火', '动作', '车房修理工阿火(成龙 饰)脾气火爆，他不仅身手敏捷，而且开车技术一流，只因家中贫穷才一直没有实现当赛车手梦想。这天，警方找到他希望他能帮忙逮捕偷车集团的首脑库克。因为库克开车技术一流，警方多次设路障追截都一无所获。阿火欣然答应。在阿火的帮助下，警方费了九牛二虎之力终于捉到了库克。但是库克在拘留期间，被集团同伙救走了。偷车集团还袭击了阿火的车房，阿火侥幸逃过一劫，两个妹妹却深受重伤。随后库克加入了日本某车队，并约阿火在日本赛道上一决高下。为了报仇，阿火毅然参赛!©豆瓣', '成龙', '陈嘉上', 7, 31512, 'tt0114126', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1974113927.jpg', 0.4, 4.3, 50, 34.1, 11.2, '-0.074791,0.178409,-0.556526,0.204611,-0.107071,-0.631356,0.062290,0.004038,-0.402113,-0.477472,0.229564,0.538669,0.262819,0.022253,0.089038,-0.140089,-0.296403,-0.394221,0.085660,0.052064,-0.242397,-0.434800,-0.231400,0.012894,-0.064146,0.030919,0.402948,-0.011798,-0.069485,0.652742,0.187450,-0.041505,-0.118648,0.451541,-0.238038,0.004499,0.550353,-0.278309,-0.255439,0.279790,-0.163492,-0.261004,0.054648,-0.141738,0.376711,0.399917,0.243151,0.225179,-0.240830,-0.113100,-0.104875,-0.383881,0.202446,-0.156283,0.614115,-0.335814,0.141020,0.199690,-0.225628,-0.294429,-0.030690,0.103757,-0.751828,0.160428,0.069991,-0.266337,-0.782407,0.299816,-0.483047,-0.027520,-0.096592,-0.279129,0.150771,0.599845,0.064574,-0.034653,0.002476,0.307863,-0.608752,-0.054045,0.752240,-0.193589,0.114021,-0.079409,0.062751,-0.327892,0.171004,-0.224172,0.006932,-0.134075,0.642365,-0.018479,-0.398072,-0.282438,-0.238639,-0.044489,-0.545642,-0.064783,-0.184566,-0.153679,0.249588,-0.601166,0.142119,-0.031068,-0.182116,0.065674,-0.005890,-0.101936,0.601986,-0.570764,0.180068,0.702375,0.419217,-0.609267,0.339628,0.040323,0.045068,-0.108420,-0.137949,0.102967,0.228598,0.286591,0.330910,0.282227,0.095292,-0.480144,-0.244372,0.065639', '25908042', '1292849', '1877596', '1296947');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299510', '死亡实验', '剧情', '本片以1971年美国的“斯坦福监狱实验”为基础，根据马里奥•乔丹努的小说《黑盒子》改编。出租司机塔瑞克•法德（莫里兹•布雷多Moritz Bleibtreu 饰）看到报纸上一个征招心理实验对象的广告前去应聘，与其他19名各行各业各年龄段的男性应聘者被分为两组，本别扮演十二名囚犯和八名狱警，实施为时2周的模拟监狱实验，并各获4000德国马克报酬。实验前夕，塔瑞克回到自己两年前曾供职的报社，决定将实验过程中发生的情形写成报道出售。塔瑞克在实验中是囚犯77号，他依仗着实验中不准使用暴力的规定，故意挑起事端制造新闻。狱警博鲁斯（贾斯特斯•冯•多纳伊Justus von Dohnanyi 饰）不满塔瑞克的嚣张，在对囚犯的制裁中一步步确立自己的权威。二人的针锋相对为实验带来了不可预计的后果……本片获德国电影奖年度电影及三项年度突出表现金奖——最佳男主角（莫里兹•布雷多）、场景设计及最佳男配角（贾斯特斯•冯•多纳伊）。', '莫里兹·布雷多', '奥利弗·希施比格尔', 7.9, 29159, 'tt0250258', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497503957.jpg', 0.6, 2.3, 21.7, 50.3, 25.1, '-0.019101,-0.102465,-0.535757,0.763921,-0.036677,-0.161029,0.545146,0.034181,-0.263631,-0.245236,0.007111,0.550287,-0.351222,0.240135,0.292151,-0.380647,-0.459922,-0.652009,-0.380238,-0.315595,-0.339972,-0.476321,-0.041921,-0.484301,-0.064086,-0.383546,0.610425,-0.052629,-0.415908,-0.072183,0.572681,0.264283,-0.186434,0.107909,0.329779,-0.113699,0.487706,-0.299353,-0.321148,0.369503,-0.008320,-0.162218,-0.166325,0.089161,0.496051,0.345481,0.716143,-0.268129,0.038276,-0.059091,0.669699,0.068874,0.168326,0.022800,0.282101,0.267837,-0.113040,0.133800,-0.132251,0.282499,-0.027346,-0.390688,-0.783304,-0.394771,0.216659,-0.016788,-0.547691,0.281502,-0.292371,0.301897,-0.062789,0.067093,-0.007777,0.303599,0.545193,0.276661,0.080612,-0.217231,-0.441960,0.474470,0.048360,0.028409,-0.240766,0.003532,-0.185508,-0.744835,-0.238498,-0.143967,-0.134393,0.060793,0.551902,-0.325272,0.216550,0.292134,-0.313649,-0.242537,-0.229363,-0.456471,-0.070750,-0.016990,0.104745,-1.107109,0.350928,0.058441,-0.144634,0.006087,0.215037,-0.322522,0.460191,-0.469964,0.231460,0.531525,0.270074,-0.364252,0.528893,-0.014061,0.283739,-0.358517,-0.133000,0.143125,0.328936,0.352425,0.179844,0.280556,0.105065,-0.488974,-0.305689,0.565375', '2028645', '34961898', '26275494', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299513', '阿拉丁', '喜剧', '阿拉伯少年阿拉丁不仅拥有忠实的朋友猴子阿布的友谊，还拥有一条神奇的魔法飞毡，他们在闹市中过着无忧无虑的快乐生活。一天，城堡里的公主厌倦了无聊透顶的皇宫生活，决定独自一人偷跑出来见识外面的花花世界。偷跑出来的公主在闹市里遇到了阿拉丁，阿拉丁对她一见钟情。同一时候，邪恶国师企图利用阿拉丁帮助自己找到能实现愿望的神灯，阿拉丁当然不肯束手就擒，于是，他的冒险之旅开始了。©豆瓣', '斯科特·维内尔', '罗恩·克莱蒙兹', 8.3, 71916, 'tt0103639', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1833285442.jpg', 0.1, 0.5, 16.7, 52, 30.7, '0.235531,0.317859,-0.610212,0.647825,-0.268897,-0.082328,0.611012,-0.313703,-0.463091,-0.080530,0.291742,0.663234,0.071609,0.353350,0.342860,0.369486,-0.433640,-0.237506,0.208409,-0.305369,-0.057469,-0.299998,-0.395455,-0.326332,-0.249933,-0.470928,0.511392,0.115568,0.045348,0.187267,0.109535,-0.109049,-0.190712,0.327743,-0.439916,-0.080369,-0.007771,0.380659,-0.287952,0.351723,-0.021560,-0.149686,-0.044225,0.205659,0.078088,-0.251072,0.582426,-0.732615,0.051536,-0.159109,0.337028,-0.141320,-0.124518,0.229982,0.124339,-0.111217,0.197660,-0.124755,0.018239,-0.150353,-0.160891,-0.261532,-0.564158,-0.170316,-0.091901,-0.090962,-0.466500,0.127484,0.237982,-0.056940,0.436251,-0.447377,0.235096,0.182216,0.420936,0.282010,-0.163028,-0.015617,-0.770500,0.216122,0.807727,-0.534360,-0.286484,0.338186,-0.185557,-0.358307,-0.069005,-0.226419,-0.798617,-0.115765,0.251771,-0.170219,-0.438962,0.215799,-0.663789,0.231262,-0.146936,0.215926,0.162625,-0.366662,-0.032876,-0.414202,0.050554,-0.132258,-0.056455,0.006629,-0.057547,-0.485703,0.604469,-0.789395,0.371533,0.783965,0.427056,-0.462257,0.851916,0.017575,0.153110,-0.178978,-0.109533,0.509041,-0.140441,0.414522,0.114482,0.383370,0.038836,0.035048,-0.527067,0.622287', '3055049', '1460341', '1949005', '2129039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299536', '不良少女莫妮卡', '剧情', '因无法忍受家人所带来的压力，少女莫妮卡（哈里特·安德森 Harriet Andersson 饰）决定离家出走，她找到了与自己情投意合的男孩哈里（Lars Ekborg 饰），希望能够与他一同生活。莫妮卡的到来让哈里欣喜若狂，在丢掉了工作后，两人驾着小艇，度过了一段悠游自 在的快乐时光。可是，逐渐拮据的经济让两个年轻人意识到这种生活并非长久之计，与此同时，莫妮卡的怀孕也给两人之间的关系带来了质的改变。莫妮卡和哈里结婚了，哈里外出工作，莫妮卡生下了一个可爱的女儿。然而，孩子的到来并没有让莫妮卡感到快乐，反而让她感到了束缚和不自由，而在日复一日的枯燥工作中，莫妮卡和曾经的情人旧情复燃，一个本来美满和睦的家庭开始分崩离析。©豆瓣', '哈里特·安德森', '英格玛·伯格曼', 7.9, 9477, 'tt0046345', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1104856635.jpg', 0.3, 1.4, 22.3, 54.9, 21, '0.403081,-0.011916,-0.777490,0.638971,-0.220503,-0.450124,1.024725,0.259353,-0.617944,-0.257235,-0.165502,0.792996,-0.077927,0.447030,0.436872,0.018864,-0.187288,-0.715341,0.081009,0.103655,-0.256656,-0.512772,-0.064280,-0.415834,-0.301463,-0.469101,0.793367,-0.046891,0.176004,0.772643,0.062337,0.131120,-0.047617,0.690590,-0.265552,0.212497,-0.010206,0.213645,-0.456254,0.126225,0.260158,-0.104188,0.048565,0.520959,0.054341,0.142954,0.838879,-0.260396,-0.241881,-0.018833,0.314153,-0.209912,-0.036932,0.140599,0.005826,-0.035347,0.119110,0.257706,-0.439286,0.103537,0.181070,-0.094849,-0.738807,0.166853,0.018750,0.172572,-0.632174,0.626826,-0.025608,-0.273507,0.267500,-0.378268,0.223676,0.852047,0.282803,0.660682,-0.374056,0.148589,-0.568334,0.126446,1.096519,-0.104604,-0.299281,0.671369,-0.589517,-0.202914,-0.099438,-0.075606,-0.665927,-0.165790,0.312725,0.311868,-0.351418,0.377993,-0.620188,0.121075,-0.262115,-0.123886,0.015439,-0.739222,0.141564,-0.484311,-0.172935,-0.583678,-0.494936,-0.025458,-0.013211,-0.533431,0.622309,-0.981165,0.256441,0.630388,0.342080,-0.521939,0.673872,0.387792,0.441475,-0.248330,0.182362,0.288338,-0.180256,0.179720,0.256563,0.260612,-0.160121,0.255277,-0.376794,0.623817', '25721544', '1308755', '35030151', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299539', '悬崖上的野餐', '剧情', '1900年的情人节，沿用英式教育的澳洲亚普利亚德女子学院组织了一次目的地为海茵悬岩的郊游。孤儿萨拉却因拖延学费而无法同行，只能目送好友米兰达和同学们在迈克劳小姐的带领下出发。抵达目的地后，米兰达等四人离队攀岩，被同在悬岩下郊游的迈克尔和仆役埃尔伯特发现，迈克尔对米兰达一见钟情，尾随了上去。当天晚上，校长收到迈克劳与米兰达等四人失踪的报告。警方马上介入调查，校长为学院名声紧张不已，而萨拉因为失去了米兰达茶饭不思。迈克尔与埃尔伯特攀岩搜索找回了一名女学生，但米兰达仍然下落不明，萨拉在绝望中被校长赶回孤儿院，她选择了自杀……本片根据琼•莱斯利的同名小说改编，获1977年英国电影学院奖最佳摄影奖。©豆瓣', '瑞秋·罗伯茨', '彼得·威尔', 7.5, 7916, 'tt0073540', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p752812460.jpg', 1.1, 4.4, 30.8, 45, 18.8, '0.348779,-0.296746,-0.488206,0.432198,0.281765,-0.508685,0.334167,0.108935,-0.544959,-0.353750,0.046812,0.742738,-0.382935,0.366435,0.682821,-0.201313,-0.685010,-0.547448,-0.138072,-0.420667,-0.168039,-0.582382,0.169508,-0.100828,-0.115625,-0.365235,0.597743,-0.224221,0.078771,0.899631,0.223720,0.408664,-0.156877,0.168787,0.020372,0.100732,0.480557,-0.132796,-0.243445,0.590578,0.181641,-0.124590,-0.230095,-0.080039,0.371469,0.354357,0.590003,-0.102662,0.007841,-0.130641,0.192423,-0.361443,0.143532,0.123709,0.550954,-0.068014,0.098899,0.318147,-0.191347,0.070887,-0.267650,-0.123209,-0.271989,0.186700,0.093948,0.059136,-0.735481,0.276952,-0.294121,-0.032996,0.115947,-0.347644,0.179027,0.493521,0.148606,0.155552,0.163669,-0.007968,-0.259836,0.086657,0.503828,-0.165512,0.026807,-0.040656,0.006840,-0.439712,0.204856,0.037303,-0.495851,0.134793,0.268259,0.210076,0.010655,0.067704,-0.379077,-0.214674,-0.593046,-0.429985,-0.143225,-0.387875,-0.134154,-0.901586,0.108410,0.007038,-0.159302,0.022831,-0.017655,-0.036084,0.454203,-0.781554,0.349754,0.470863,0.309799,-0.369452,0.639949,0.068581,0.118282,-0.302195,0.015914,0.300082,0.294197,0.459835,0.108345,0.223465,-0.089169,-0.207456,-0.460919,0.302888', '2075345', '25833539', '3036464', '1819460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299550', '行运一条龙', '剧情', '行运茶餐厅餐厅老板（吴孟达 饰）每天都乐于在茶餐厅中忙前忙后，他的儿子阿男（陈晓东 饰）却非常嫌弃，一次他在遇到了离家出走的富家女芳芳（舒淇 饰），芳芳还跟了他回家，父亲以为他们是男女朋友的关系。此时，阿福（葛文辉 饰）送外卖时遇到了Fanny（杨恭如 饰），便向何金水（周星驰 饰）这位情圣请教，可是何金水也遇上了当年的初恋情人Cindy（郑秀文 饰），Cindy借故报复当年的恩怨，令何金水患得患失。茶餐厅被勒令收回，全茶餐厅的人都决定要抵抗到底……©豆瓣', '周星驰', '李力持', 6.9, 58456, 'tt0138587', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2633509143.jpg', 0.9, 7.5, 49.8, 29.5, 12.3, '0.237638,-0.081260,-0.455851,0.166231,-0.113059,-0.394363,0.463531,0.404589,-0.526111,-0.228052,0.062525,0.586427,-0.268047,0.335543,0.276522,-0.037045,-0.048080,-0.439003,0.212433,-0.066971,-0.129192,-0.251881,-0.147979,-0.045241,0.140410,0.150302,0.091212,-0.065770,-0.019362,0.356164,0.527504,-0.045602,-0.152492,0.490776,-0.118359,0.200185,-0.057192,0.519620,-0.197392,-0.134733,0.125480,-0.293397,-0.057829,0.189537,0.363763,0.422264,0.313929,0.122187,-0.186126,0.053988,0.145754,0.003926,0.095933,0.186021,0.241305,-0.193911,0.328711,0.149320,-0.182906,0.039422,0.116990,0.176298,-0.339786,0.248690,0.275191,-0.157886,-0.709305,0.364108,-0.045912,0.028877,0.112147,-0.415959,0.237561,0.279087,0.185210,0.157398,-0.023611,-0.148106,-0.715822,0.399421,0.471314,0.070260,0.374022,0.391179,-0.007253,-0.239861,0.040545,0.016076,-0.484934,0.138106,0.087352,-0.034628,-0.182147,-0.173588,-0.545818,-0.314468,0.011195,0.213178,0.014770,-0.192470,-0.010351,-0.446068,0.156866,-0.447376,-0.190483,0.053762,0.054978,-0.040466,0.375671,-0.768778,0.082008,0.313448,0.324282,-0.665214,0.734833,0.153967,-0.245959,-0.221754,-0.146035,-0.140661,0.078032,0.048131,0.131965,0.440981,0.137797,-0.282163,-0.154740,0.297624', '1302384', '3033092', '2124718', '1293030');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299556', '飞越长生', '喜剧', '海伦（歌蒂·韩 Goldie Hawn 饰）和恩尼斯（布鲁斯·威利斯 Bruce Willis 饰）是一对感情十分要好的情侣，海伦的好友梅德林（梅丽尔·斯特里普 Meryl Streep 饰）要在百老汇进行一场演出，两人遂携手一同前往观看。没想到梅德林居然对英俊帅气的恩尼斯搔首弄姿，之后更是插足于两人之间横刀夺爱。同时失去了好友和爱人，海伦悲伤又愤怒，对人生失去希望的她暴饮暴食，很快就变成了一个人人见而避之的肥婆。不要用别人的错误惩罚自己，明白了这个道理，海伦开始发愤图强，她不仅恢复了曾经的姣好身材，更出版了描写期间心路历程的新书。海伦的改变让生活并不如意的恩尼斯重燃了旧情，梅德林坐不住了，为了和昔日好友一决高下，她开始向邪恶的女巫寻求帮助。©豆瓣', '梅丽尔·斯特里普', '罗伯特·泽米吉斯', 7.6, 8268, 'tt0104070', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1050069252.jpg', 0.5, 3, 30.5, 46.9, 19.1, '0.407815,-0.149087,-0.554960,0.632244,0.155352,-0.583252,0.810564,0.124388,-0.304376,-0.034700,-0.066140,0.950428,-0.373765,0.355569,0.440489,0.137070,-0.409885,-0.853466,0.067776,-0.123083,-0.087721,-0.539303,-0.177264,-0.049256,-0.210454,-0.380057,0.420066,-0.032274,-0.042683,0.661251,0.340751,0.080141,0.124738,0.316219,0.157551,-0.001419,0.012960,-0.105951,-0.510355,-0.010036,0.398261,-0.125508,-0.186710,0.429462,-0.035558,0.296833,0.494834,-0.347276,-0.113557,-0.081109,0.199702,-0.065815,0.198547,0.285378,-0.067230,-0.213190,0.101210,0.188465,-0.253123,-0.014055,0.121200,-0.173936,-0.680141,0.240549,0.107953,0.167110,-0.491713,0.356169,-0.037353,-0.029473,0.176844,0.027981,-0.066550,0.433716,0.311329,0.160237,-0.197455,-0.080747,-0.343533,0.015477,0.597616,0.241624,-0.195402,0.372272,-0.140798,-0.300919,-0.147990,0.004269,-0.546349,-0.024626,0.355768,0.087146,-0.004453,0.308194,-0.775326,-0.109101,-0.408798,0.039648,-0.061569,-0.477397,0.035299,-0.527975,-0.317256,-0.525877,-0.370087,-0.073740,0.096099,-0.394041,0.767292,-1.094251,0.132878,0.207234,0.331135,-0.650945,0.430036,0.247542,-0.001853,-0.185928,0.090903,0.372782,-0.159703,0.042435,0.292241,0.277542,0.172458,0.039063,-0.237569,0.645118', '1292219', '30345227', '1301022', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299560', '深渊', '剧情', '美国核潜艇蒙坦娜号在深海追踪一个不明物体的时候不幸失踪，高压潜水钻台深海之心号工头巴德（艾德·哈里斯 Ed Harris 饰）接到命令负责配合科菲上尉（迈克尔·比恩 Michael Biehn 饰）前去营救。令人意想不想不到的是一同前往的还有跟巴德一直在闹别扭的妻子—— 石油公司工程师琳西（玛丽·伊丽莎白·马斯特兰托尼奥 Mary Elizabeth Mastrantonio）。三人为主的救援队潜到潜艇失踪的海底深渊边缘，却发现潜艇上无人幸存，令人恐慌的是深渊里还存在着一种未知的怪物。经过一系列的危机之后，科菲上尉不听劝阻认定这是苏联的阴谋，决定把从潜艇上拆下来的核弹发射给不明的敌人，于是巴德和琳西联手开始了殊死搏斗。千钧一发之际巴德不顾危险救下了琳西，并且潜下深渊去拆掉核弹头上的引信，完成任务之后巴德的氧气已经消耗殆尽，而就在此刻深海的怪物再次出现。', '艾德·哈里斯', '詹姆斯·卡梅隆', 8, 39068, 'tt0096754', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209378207.jpg', 0.5, 2.2, 21.7, 49.4, 26.1, '0.289243,0.045150,-0.906015,0.562659,0.054690,-0.128026,0.758167,-0.004064,-0.294152,-0.037995,0.349364,0.511916,-0.017567,-0.130003,0.126725,0.170692,-0.658767,-0.455660,-0.426198,-0.004096,-0.766102,-0.679406,-0.230640,-0.055870,0.247788,-0.342317,0.549257,0.282855,-0.087310,0.326660,0.069999,0.551137,-0.243518,0.726657,-0.003048,-0.124301,0.212818,-0.273864,-0.147659,0.264293,-0.002050,-0.017322,0.078988,0.174778,0.085830,0.435894,0.524578,-0.332580,0.177892,-0.022972,-0.077949,-0.315487,0.220521,0.005232,0.471099,-0.226632,-0.255773,-0.100487,-0.219258,0.052310,0.161541,0.248731,-0.545428,0.046949,-0.199577,0.179818,-0.319707,0.019364,-0.396812,0.244911,0.148393,-0.415929,0.101099,0.285480,0.115109,0.240022,-0.297775,0.108619,-0.597323,-0.166412,0.617889,-0.223068,-0.175590,-0.036984,0.241626,-0.410723,0.013034,-0.034578,-0.201570,-0.252387,0.536189,0.298519,-0.245444,0.259922,-0.767869,0.115891,-0.607187,-0.326300,-0.236074,-0.252747,-0.338911,-0.720344,0.037725,-0.037582,-0.205187,0.303899,0.141479,-0.009247,0.416528,-0.446886,0.373801,0.680566,0.073589,-0.088997,0.593612,-0.101479,0.021904,-0.327551,0.143938,0.202202,0.162577,0.441129,0.107960,0.363893,0.126817,-0.237849,-0.307055,0.165477', '3011051', '34461680', '7065211', '1410557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299576', '我盛大的希腊婚礼', '喜剧', 'Toula（妮娅·瓦达拉斯 Nia Vardalos 饰）虽然在美国出生长大，却是生活在一个巨型的希腊世界中，整个庞大的家族以父亲权威般的意志为代表坚持着希腊是世界之源的精神动力，从小就眼观着家人古怪行为的Toula听得最多的就是母亲与神经质祖母的言论：嫁给一个希腊人，生一大堆希腊小孩，喂饱自己的肚子直到世界的最后一天。长到30岁的Toula邋遢肥胖，在一次夜雨中继续听着父亲的唠叨，然而当她走进日复一日工作的家庭餐馆时，她决定要改变自己的命运！她去学习，去美容院整理自己的仪容，当她浑身散发出自信时，命定的白马王子Ian（约翰·考伯特 John Corbett 饰）出现了，二人一见钟情，迫不及待要组织自己的新家庭。对这个庞大的希腊家族来说，Ian不折不扣是一个外人，婚礼的繁琐和斗争才刚刚开始，不同的价值观引发了一连串笑料。©豆瓣', '妮娅·瓦达拉斯', '乔尔·兹维克', 6.9, 18713, 'tt0259446', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1461669339.jpg', 0.9, 6, 50.7, 34.5, 7.9, '0.125050,0.352177,-0.809596,0.664056,-0.416502,-0.222632,0.763906,0.223274,-0.560202,-0.315847,0.173326,0.894122,-0.042558,0.556287,0.179020,0.216147,-0.169796,-0.626933,-0.135347,0.017764,-0.264496,-0.379982,-0.085824,-0.286021,-0.099899,-0.362165,0.496039,-0.058359,-0.249064,0.166461,0.322910,0.261804,0.113811,0.304592,-0.403659,-0.172125,-0.005784,0.065531,-0.172065,0.025948,0.114149,0.179830,-0.177631,0.367523,-0.242212,0.158200,0.676409,-0.387779,-0.249139,-0.323101,0.666266,-0.122186,-0.202622,0.138715,0.255590,0.018617,0.164777,0.262305,-0.046978,0.164267,-0.001377,-0.229133,-0.710964,-0.239247,0.092625,0.150782,-0.833223,0.548665,0.054944,-0.278697,0.130407,-0.295046,0.136915,0.399125,0.166794,0.825748,-0.301109,0.118232,-0.384856,0.190664,0.644406,0.030244,-0.410623,0.439024,-0.334789,-0.195564,0.025696,-0.225391,-0.603089,-0.229053,0.044021,0.014566,-0.252800,0.341184,-0.694468,0.143073,-0.152284,-0.372438,0.197953,-0.429788,-0.138086,-0.323884,-0.285243,-0.410346,-0.268171,0.240019,0.027565,-0.157104,0.911099,-0.696037,0.232148,0.599875,0.229633,-0.490589,0.605411,0.053164,0.187947,-0.391539,0.039926,0.355620,-0.179346,0.063490,-0.163630,0.387510,0.102128,0.013956,-0.407549,0.757388', '30162520', '25731805', '26348103', '4058933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299578', '火烧圆明园', '剧情', '咸丰二年（1852年），颇有姿色的叶赫那拉氏玉兰（刘晓庆）被选进宫册封为贵人，由于历史上叶赫那拉与爱新觉罗两家族有宿仇，玉兰起初不得咸丰（梁家辉）的宠幸，但善于心计的她终以一曲哀怨缠绵小调和倾城美貌将咸丰紧紧捆绑，被册封为懿嫔，又因生下儿子载淳，被进封为懿贵妃，地位一时除皇后（陈烨）外，无人可及。清宫各嫔妃争宠、咸丰耽于享乐之时，觊觎大清财富良久的英法等帝国对中国屡次发兵侵犯，胆小怕事的咸丰在肃清等八位大臣的规劝下，丢下举世闻名的有“万园之园”之称的圆明园，以“秋猎”之名携带众嫔妃逃到了热河行宫，继续“两耳不闻窗外事，一心只行及时乐”的奢淫生活。©豆瓣', '刘晓庆', '李翰祥', 7.5, 17846, 'tt0085703', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2538063804.jpg', 0.6, 2.5, 34.8, 47.5, 14.6, '0.236988,0.376213,-0.599855,0.744132,0.251640,-0.071762,0.341602,0.365743,-0.781489,-0.194321,0.319035,0.446215,-0.487372,-0.022736,0.001875,-0.078318,-0.009300,-0.580229,-0.271126,-0.280050,0.197019,-0.085189,0.057839,0.021971,-0.489400,-0.384710,0.651751,-0.362118,0.170282,0.466516,0.205364,0.153862,-0.009431,0.296600,-0.362271,0.286901,-0.198465,-0.303125,-0.194250,0.074924,-0.160142,-0.778728,-0.398566,-0.154645,-0.047771,0.098403,0.285963,-0.486875,0.377401,-0.591800,0.416765,0.113034,-0.049659,0.668486,0.362715,-0.077628,0.003049,0.567898,-0.290657,-0.009295,-0.031034,0.020724,-0.443596,-0.032940,0.280812,0.000572,-0.306792,0.640076,-0.185437,-0.337803,-0.087434,-0.150372,0.422356,0.571395,-0.064801,0.424259,-0.089108,0.315451,-0.419873,0.271047,0.395645,-0.012101,-0.025795,-0.056918,0.198991,-0.297210,0.484740,-0.622343,-0.298854,-0.319333,0.113483,-0.184284,0.444304,0.430880,-0.353815,0.039821,-0.440754,-0.112439,0.353256,-0.304415,-0.017778,-0.134115,-0.165999,-0.554549,-0.482198,0.037408,0.626871,-0.104143,0.602860,-0.557263,0.082233,0.380072,0.617843,-0.832002,0.739055,0.167598,0.205936,0.436710,-0.374134,0.182379,-0.015537,-0.019614,-0.209175,0.210992,-0.418358,-0.315701,-0.464084,0.044146', '3606975', '1301081', '1295987', '6557030');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299582', '绿洲', '剧情', '刑满释放的洪忠都（薛景求饰）出狱后，家人对他横加排斥，而他之所以被判入狱，只是为了顶替哥哥的罪名。之后心冷意凉的他，来到车祸死者的住所拜访家属，遇到死者的女儿韩恭洙（文素利饰）——一名重度脑麻痹患者，面容扭曲、手脚抽搐。但忠都却被她吸引，并在冲动下做出大胆之举。但在意外事件后，两人彼此都萌生了情感思念，孤独的心灵就此渐渐靠拢。他们看似身心不甚健全的非正常人，却遭遇着赤裸裸的现实不公。不过，命运并没有就此放过戏弄他们的机会。©豆瓣', '薛景求', '李沧东', 8.7, 61306, 'tt0320193', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2371311227.jpg', 0.3, 0.9, 9.6, 42.4, 46.7, '0.073685,-0.029103,-0.702536,0.361690,-0.205188,-0.180206,0.971989,0.395200,-0.517772,-0.153909,0.473446,0.620260,-0.074983,0.293191,-0.066723,-0.076586,-0.219166,-0.695243,0.030429,-0.024331,-0.284435,-0.282359,0.095666,-0.382515,-0.150741,-0.311334,0.524873,0.118931,-0.263626,0.367709,0.193545,0.194175,-0.017063,0.841968,-0.081976,0.064023,-0.077204,0.069338,-0.206284,-0.134352,0.197999,-0.494634,-0.060732,0.573171,-0.415317,0.605544,0.712288,-0.224235,-0.482865,-0.270438,0.225666,-0.455350,0.052924,0.376538,0.080691,0.038024,0.196175,0.405898,-0.169900,0.074004,0.246415,0.369843,-0.705609,0.180448,0.067515,0.142711,-0.313387,0.591763,-0.083653,0.077034,-0.300588,-0.216231,0.094310,0.137559,0.368603,0.106750,-0.430703,-0.026667,-0.203395,-0.059518,0.784252,-0.122882,-0.495560,0.338342,-0.657906,-0.473725,0.111449,-0.182046,-0.314316,-0.111979,0.240177,0.296696,-0.483832,0.352188,-0.216928,-0.113902,-0.296607,0.071526,-0.309573,-0.366974,0.095566,-0.136131,-0.339467,-0.164453,-0.550368,0.161002,0.199782,-0.298114,0.183437,-0.630876,0.341038,0.660698,0.177568,-0.834830,0.351368,0.230916,-0.295667,-0.083324,-0.163631,0.513966,-0.001212,0.335886,0.189107,0.116040,-0.221610,0.324027,-0.171346,0.434787', '26718282', '35073886', '1309116', '1292064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299584', '大冒险家', '剧情', '立仁（刘德华 饰）自小便父母双亡，在泰国的孤儿院长大。长大后，立仁进入了泰国空军。此时，他仍耿耿于怀当年父母的死亡。原来，在立仁9岁的时候，他的父母带着他携带一批重要资料和物品来到泰国，岂料父亲的结拜兄弟见利忘义，将他的父母杀害了。一天，立仁糊里糊涂的和仇人的情妇Mona（关之琳 饰）发生了关系，由此受到了杀手的追杀。无奈之下立仁逃到了美国寻求CIA的帮助。在美国，立仁无意中又救了仇人的女儿Chrystal（吴倩莲 饰），两人堕入了爱河。爱情、亲仇交织在一起，立仁该何去何从？©豆瓣', '刘德华', '林岭东', 6.6, 7528, 'tt0112772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457030223.jpg', 1.4, 9.2, 58.5, 22, 8.9, '0.188007,-0.036737,-0.918426,0.493739,-0.112000,-0.320658,0.632168,0.269917,-0.432877,-0.176591,0.377341,0.933480,0.093567,0.484814,0.173955,0.026282,-0.146812,-0.886368,0.089449,-0.362165,-0.345522,-0.430796,-0.161005,-0.037723,-0.106819,-0.231670,0.542861,0.136073,0.023231,0.520996,0.267713,0.360252,-0.452443,0.412524,-0.410238,0.267126,0.321215,0.346922,-0.429657,0.197351,0.131968,-0.447767,0.061197,0.093757,-0.024805,0.402173,0.833145,-0.146882,-0.066556,-0.161210,0.182919,-0.306065,-0.190051,0.338378,0.429185,-0.019019,0.145026,0.362347,-0.294154,-0.148118,0.016441,0.075114,-0.516218,-0.126800,0.190640,-0.057432,-0.818817,0.517345,-0.106894,0.006765,0.048063,-0.368803,0.389441,0.574979,-0.179422,0.522309,-0.243548,0.026352,-0.473574,0.309753,0.909427,-0.195877,0.040946,0.237238,0.002091,-0.252815,0.049777,-0.267960,-0.501057,0.036814,0.609097,-0.068600,-0.500243,0.333105,-0.414353,-0.138974,-0.076286,0.132180,0.005790,-0.411420,-0.076740,-0.306861,-0.293904,-0.631805,-0.294450,0.112621,-0.070904,-0.197841,0.722399,-0.715421,0.277585,0.423969,0.470306,-0.700985,0.671740,0.016826,0.143553,-0.215966,0.084884,0.323966,0.106155,0.180328,0.310716,0.015119,-0.060884,0.143290,-0.321389,0.046772', '1301022', '1306209', '4861627', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299586', '月光光心慌慌', '惊悚', '十五年前的万圣节，哈登菲尔德镇的六岁男孩迈克尔（威尔•桑丁 Will•Sandin 饰）用一把菜刀杀死了他的姐姐，当人们发现他时，他正双手血淋淋的呆望着天空，无论怎样问话，他保持着那个姿势一动也不动。于是，迈克尔被送进了精神病院。在那里，医生费尽了心思，用尽了各种方法，迈克尔还是呆望天空一动也不动。直到1978年的12月30日，迈克尔（东尼•莫兰 Tony•Moran 饰）似乎听到了某种召唤，偷了精神病院的钥匙，独自偷走回到了家乡哈登菲尔德。一场新的杀戮即将开始……©豆瓣', '唐纳德·普利森斯', '约翰·卡朋特', 6.7, 14745, 'tt0077651', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177127286.jpg', 2.3, 10.9, 46.3, 29.8, 10.7, '0.131510,0.153475,-0.634133,0.091570,-0.141929,-0.571038,0.717036,0.104824,-0.272118,-0.130357,0.269165,0.645254,-0.217078,0.471287,0.305882,0.195078,-0.464707,-0.757126,-0.370360,-0.142411,-0.351470,-0.242040,-0.139711,0.115749,0.113202,-0.159540,0.234042,-0.044498,0.140367,0.247851,0.241544,0.028993,0.248456,0.340477,-0.189066,0.110838,0.006603,-0.287465,0.034374,0.286597,0.327267,-0.468803,-0.359590,0.164213,-0.041617,0.198854,0.502458,-0.381114,0.209160,-0.143274,0.031631,-0.126660,-0.148310,0.113068,0.101582,0.007648,0.068021,-0.180246,-0.263096,-0.049375,0.220056,-0.107372,-0.160736,0.073554,-0.326505,0.202570,-0.696683,0.203146,-0.223028,0.340763,0.000875,-0.543321,0.077471,0.057060,-0.135187,0.344170,-0.382367,-0.144629,-0.442944,0.085943,0.069588,-0.215876,-0.093812,0.269337,0.128960,-0.335847,-0.200088,0.109403,-0.345349,-0.382296,0.703935,0.127765,-0.286038,0.107838,-0.358019,-0.115707,-0.166214,-0.282913,0.157813,-0.244575,-0.368903,-0.481297,0.155271,-0.065642,-0.006325,0.043832,-0.009555,-0.006546,0.252060,-0.573169,0.562708,0.473818,-0.028025,0.252466,0.405479,-0.351068,0.080770,-0.057419,0.051710,0.308822,0.022093,0.737883,0.431810,0.535155,0.159783,-0.004732,-0.599637,0.736429', '1303462', '1302133', '1298817', '1297347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299591', '鬼娃回魂3', '惊悚', '楚其被熔毁之后八年，玩具公司为打开销路考虑再度推出“好家伙”公仔，他们将当年楚其的残骸回收，再度制作使其复活，获得重生的楚其为了完成灵魂转移，将玩具公司总裁杀死后消失于夜色。安迪（Justin Whalin 饰）经历了八年收养生活，此时来到一所军校就读，当年楚其留给他的恐怖回忆仍然挥之不去，而在学校中应付严苛的助理上校谢尔顿（Travis Fine 饰）亦并不轻松。楚其将自己邮寄到军校以寻找安迪，不料却被小学员二等兵泰勒占为已有，楚其认为自己的身体获得新生，可以摆脱必须占有安迪身体的宿命，随即把自己的秘密告知泰勒，并计划夺走泰勒的肉身。安迪不能坐视同侪受害，再度与楚其展开抗争……©豆瓣', '贾斯廷·威林', '杰克·本德', 6.2, 5093, 'tt0103956', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1302824546.jpg', 3.6, 18.7, 51.7, 16.5, 9.4, '0.247476,0.334362,-0.333386,0.422380,-0.250097,-0.450716,0.613693,-0.096619,-0.428300,-0.423672,-0.043523,0.621708,-0.106449,0.279181,0.207328,-0.091345,-0.049105,-0.688189,-0.084442,-0.060310,-0.233646,-0.496576,-0.267287,-0.271502,-0.187401,-0.381117,0.988240,0.043614,-0.183870,0.152072,0.041840,0.231927,-0.079261,0.432755,0.007156,-0.016001,-0.175302,0.030453,-0.372432,0.425035,0.150521,-0.358199,0.152466,-0.009746,0.090545,0.096539,0.869458,-0.131967,0.056320,-0.260754,0.494920,-0.305957,-0.151666,-0.044101,-0.031183,0.413183,-0.186654,0.240323,-0.339518,0.148598,0.298755,-0.342089,-0.725441,-0.222214,0.153069,-0.172193,-0.435270,0.128636,-0.175396,0.355324,0.179439,-0.314241,-0.016629,0.357034,0.264567,0.280773,-0.283233,0.164956,-0.387132,0.167044,0.461446,-0.437719,-0.228288,0.086497,-0.203929,-0.272617,0.255750,-0.229774,-0.084401,0.091940,0.260106,0.674682,0.071326,0.341218,-0.319147,-0.514236,-0.390924,-0.226614,0.218843,-0.557248,-0.126903,-0.488887,-0.234982,0.210420,-0.076954,-0.053848,0.131487,-0.444391,0.466970,-0.779913,0.182977,0.288454,0.404899,-0.261647,0.294075,-0.279919,0.447764,-0.213630,0.160719,0.510408,0.266291,0.465295,0.101116,0.121042,-0.025961,-0.074432,-0.446421,0.420391', '26759820', '26759819', '30345227', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299603', '落水狗', '惊悚', '黑帮老大乔·卡伯特（劳伦斯·蒂尔尼 饰）和他的儿子“好家伙”艾迪（克里斯·佩恩 饰）召集了六名强盗，准备到珠宝店抢劫一批天然钻石。这六个人彼此各不相识，甚至连对方的姓名都无从得知。乔为了保持机密，以颜色作为代号分别给六人起名为白先生(哈维·凯特尔 饰)、橙先生（蒂姆·罗思 饰）、金先生（迈克尔·马德森 饰）、粉先生（史蒂夫·布斯塞米 饰）、棕先生和蓝先生，并规定他们之间不能透露任何私事。抢劫时，六人中了警察的埋伏，蓝先生和棕先生当场死亡。白先生带着身受重伤的橙先生回到预定的聚集地——一个仓库。一会儿，粉先生、“好家伙”艾迪和金先生也来到这里，并活捉了一名警察。几人回忆案发时的情景，得出结论，六人中必定有人向警察告密。为了揪出告密者，大家审问拷打那个警察，仍然无法得知事实真相。本就互不了解的几个人，开始互相猜忌，事情的发展完全偏离了预设的轨道。©豆瓣', '哈威·凯特尔', '昆汀·塔伦蒂诺', 8.4, 192865, 'tt0105236', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1851340431.jpg', 0.2, 0.9, 13.3, 49.3, 36.2, '0.354288,-0.116143,-0.065574,0.413261,0.063485,-0.485085,0.415493,0.089908,-0.351510,-0.497668,-0.054135,0.462993,-0.229373,0.113501,0.394022,0.109506,-0.687664,-0.530386,-0.183252,-0.364973,-0.268462,-0.754222,0.076397,-0.321338,0.033501,-0.003215,0.222528,-0.054108,-0.012521,0.440531,0.303814,0.354548,-0.383445,0.230381,0.268483,-0.006624,0.368021,-0.268399,-0.586283,0.220800,0.022716,0.182384,0.069712,-0.023767,0.295261,0.533656,0.334369,-0.439979,-0.066184,0.081295,-0.081333,-0.131280,0.357425,0.225210,0.445080,-0.103779,0.372063,0.290518,-0.192593,0.200650,0.043866,0.083594,-0.523997,0.225659,0.139418,0.301015,-0.223090,0.061469,-0.158858,0.064144,-0.030879,-0.073388,0.077225,0.300629,0.116562,-0.234863,0.069360,-0.099627,-0.557680,-0.148055,0.442328,0.011952,-0.014333,-0.183547,0.131861,-0.358763,-0.149752,0.295304,-0.237740,0.057340,0.378070,-0.071973,0.195133,-0.067518,-0.658738,-0.237518,-0.334505,-0.134974,-0.056850,-0.203915,0.026571,-0.504124,-0.007050,-0.229788,-0.246942,0.087854,0.254333,0.058181,0.319861,-0.646726,-0.014043,0.145612,0.210658,-0.363003,0.343954,-0.004327,-0.082173,-0.477761,-0.469634,-0.125993,0.545343,0.353430,0.377124,0.329658,0.165459,-0.244057,-0.048988,-0.142951', '3006781', '1307442', '1308237', '4043647');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299607', '东京日和', '剧情', '摄影家岛津已喜男（竹中直人饰）想要出版一本摄影集，这是一本献给亡妻阳子（中山美穗饰）的摄影集，标题为《东京日和》，岛津希望藉着这本摄影集，重新去感觉他和阳子之间的情愫与回忆。在旅行社工作的阳子患有内分泌失调症，因而常常出现有别于常人的情绪和行为，甚至会无缘无故地走失。同事和上司也发现她的异常，但岛津对她依旧钟爱，并尽力保护她，使她免受现实残酷的压力。在柳川之旅，夫妇俩人故地重游，然而，阳子的病症越来越严重，岛津最终未能留住心爱的阳子。©豆瓣', '竹中直人', '竹中直人', 8.3, 14701, 'tt0123302', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2552418230.jpg', 0.5, 1.6, 16.6, 45.8, 35.5, '-0.036434,-0.116430,-0.328655,0.678768,0.122267,-0.245053,0.645857,0.319156,-0.757990,-0.467629,0.153117,0.812769,0.094985,0.325955,0.146056,-0.081583,-0.147939,-0.527233,0.065126,0.146189,0.099132,-0.189407,-0.210691,-0.280545,-0.444746,-0.543827,0.735346,0.187639,-0.317603,0.352018,0.055744,0.396124,-0.128330,0.683414,0.258387,0.093539,-0.365665,-0.000413,-0.296476,0.127247,0.184802,-0.278656,-0.076141,0.463771,-0.129652,0.331097,0.623583,-0.223439,-0.400314,-0.009642,0.506538,-0.139931,-0.070563,0.519495,0.187314,0.360278,0.298865,0.140323,-0.333312,0.045697,0.184057,0.198626,-0.440559,-0.123438,0.339760,0.282404,-0.170138,0.498858,-0.382018,-0.177018,0.252176,-0.459715,-0.052595,0.371793,0.255527,0.268217,-0.375405,0.045446,-0.175599,-0.053510,0.341478,-0.178589,0.026358,0.259815,-0.326605,-0.453442,-0.255341,-0.288383,-0.339951,0.069120,0.093933,0.290168,-0.334645,0.203355,-0.551938,0.056391,0.209184,-0.043164,0.044239,-0.362234,0.191637,-0.565189,-0.004313,-0.562263,-0.319013,-0.092553,0.440138,-0.479331,0.736983,-0.678148,0.125641,0.690670,0.132766,-0.428570,0.469171,0.367610,-0.288488,0.093626,-0.092003,0.280542,0.042153,0.569864,-0.017072,0.246629,0.068294,0.092096,-0.258369,0.399924', '3811356', '25880986', '10174444', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299624', '半生缘', '剧情', '1930年代的上海，在同一间工厂做工的世钧（黎明）和曼桢（吴倩莲）成为恋人。曼桢早年丧父，姐姐曼璐（梅艳芳）为了养活一家老小，心痛离别恋人去当舞女赚钱，最终嫁给了有妇之夫祝鸿才（葛优）。世钧收到告急家书回到南京，方知家人召回只为让其成亲。因为性格上的软弱，也因久等不来曼桢的书信，世钧最终迎娶了他并不喜欢的门当户对的翠芝（吴辰君）。上海这边，不能生育的曼璐为保全自已的地位，设计令曼桢怀上了祝鸿才的孩子，葬送了曼桢与世钧的爱情。曼璐死后，曼桢为了孩子委身祝鸿才。两个有缘无分的人就这样错过情缘。©豆瓣', '黎明', '许鞍华', 7.9, 83368, 'tt0127468', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1526661173.jpg', 0.2, 1.4, 23.9, 52.3, 22.2, '0.127080,0.014161,-0.584248,0.257219,-0.258396,-0.687602,0.549444,0.289859,-0.456030,-0.208131,0.081363,0.934796,0.242864,0.408263,0.057253,0.066924,-0.092241,-0.457080,0.187394,-0.157187,-0.006510,-0.291704,0.159754,-0.029441,-0.173316,0.055244,0.667261,-0.003683,0.061397,0.433439,0.330103,-0.091789,-0.145691,0.302457,-0.279734,0.186362,-0.423877,0.299694,-0.683022,0.202622,-0.156027,0.142031,0.129626,0.005942,-0.073315,0.158514,0.563268,0.043659,0.153938,-0.335965,0.518127,-0.053986,-0.090735,0.061919,-0.061176,-0.068826,0.266220,0.224876,-0.490681,-0.174141,0.001826,-0.053334,-0.601160,0.224258,0.311683,-0.078684,-0.570617,0.422974,-0.311777,-0.081992,0.046608,-0.524338,0.221154,0.470907,0.178350,0.423657,-0.447305,0.233968,-0.421697,0.355038,0.802058,-0.005239,0.096355,0.239482,-0.016997,-0.309417,0.431745,-0.318989,-0.728780,0.220758,0.058153,0.175748,-0.158064,0.224398,-0.305110,-0.202075,-0.104209,0.344695,0.375576,-0.543549,0.027697,-0.040415,-0.084565,-0.267850,-0.402930,-0.066446,0.247365,-0.318211,0.554328,-0.500037,0.235223,0.405558,0.560390,-0.866126,0.734534,0.356665,0.408296,-0.251515,0.056636,0.304104,-0.164098,0.092911,0.072032,-0.250423,-0.016172,0.035269,-0.180296,0.252106', '1308035', '1296569', '26678784', '6890343');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299628', '马戏团', '喜剧', '马戏团的表演因为呆板无趣而失去了观众，他们面临着破产和倒闭的危险，谁都不知道会不会有“救星”从天而降。流浪汉查理（查理·卓别林 Charles Chaplin 饰）在游园会中被卷入了一个小偷的圈套中，招来警察的追捕。他像无头的苍蝇一样钻进了正在演出的马戏团。舞台上，查理 躲避警察的各种肢体动作，被观众当成马戏团的表演，他们非常喜欢查理的“表演”，热烈地鼓掌来。马戏团老板想让查理留下来，帮助马戏团起死回生。虽然查理并不想以马戏团为生，但是走投无路的他为了维持生计也只好接受了老板的提议。很快，查理的喜剧表演天赋让他成为了马戏团的招牌演员。他爱上了善良柔弱的马戏团老板女儿，想尽办法取悦她，但是，老板的女儿真正爱上了的人却是走钢丝的男演员，为了成全所爱的人，伤心的查理默默地离开了喜欢他的观众。查理·卓别林凭此片获得第1届奥斯卡金像奖荣誉奖。©豆瓣', '查理·卓别林', '查理·卓别林', 9.2, 20773, 'tt0018773', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1959764913.jpg', 0.1, 0.2, 4.1, 29.3, 66.4, '0.356474,-0.149845,-0.557505,0.323708,-0.529031,-0.250306,0.849500,0.179795,-0.414845,0.181260,0.421538,1.086120,-0.220794,0.104445,0.218540,0.117185,-0.419844,-0.632797,-0.213245,-0.008729,0.085108,-0.258929,-0.055413,-0.467065,-0.026260,-0.158217,0.498169,-0.081974,-0.271314,0.408779,0.497030,0.111826,0.318092,0.436371,-0.066892,0.122706,0.086410,-0.100607,-0.163605,0.250494,-0.005613,-0.177633,-0.176733,0.342778,-0.114552,0.166388,0.628103,-0.324347,-0.065585,-0.124946,0.342154,-0.604395,0.133503,0.165218,0.122689,0.004992,0.296260,-0.228932,-0.023930,0.186060,0.083482,0.009187,-1.012947,0.158786,0.226402,0.284998,-0.525073,0.380878,0.098489,0.021472,0.111019,-0.252389,0.374242,-0.072739,0.494571,0.321705,-0.074062,0.026056,-0.717396,0.305144,0.772155,0.136316,-0.279416,0.288589,-0.404455,-0.398373,0.105236,-0.461200,-0.518283,-0.063542,0.495200,-0.136983,-0.340712,-0.003662,-0.408038,-0.157922,-0.091073,-0.256285,-0.286996,-0.660173,-0.062667,-0.566726,0.057836,-0.320737,-0.010908,-0.308883,-0.026186,-0.412775,0.766349,-0.843993,0.274086,0.969486,0.298949,-0.298770,0.853539,0.217804,-0.199627,-0.079832,-0.284980,0.065008,0.044008,0.300709,0.195265,0.231964,0.132410,-0.374428,-0.192004,0.539664', '34890458', '30162520', 