INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299643', '宝莲灯', '动画', '天神爱上凡人，这原本就是不被允许的事情。但是，天宫中的三圣母（徐帆 配音）却执意爱上了人间的书生刘彦昌。不顾二郎神（姜文 配音）的反对，三圣母带着神器宝莲灯私下凡间与刘彦昌私定终身并生下一子取名叫沉香。平静、幸福的七年很快就过去了，有一天二郎神突然下凡，并用小沉香威胁三圣母交出宝莲灯并被其压在华山下。一个美好的家庭也由此破碎。沉香从土地神口中知道了自己的身世，为了夺回宝莲灯，救出母亲，由此踏上了艰辛的寻母之路。多年的磨练，让沉香成长为一个英勇的少年，并在孙悟空（陈佩斯 配音）的点拨下，获得一把神斧，最终宝莲灯与沉香合二为一，战胜了二郎神，劈开华山，救出了母亲。©豆瓣', '姜文', '常光希', 8.4, 181878, 'tt0262264', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195312435.jpg', 0.3, 1.6, 17, 38.8, 42.2, '0.093632,0.529968,-0.637116,0.670920,-0.205715,-0.512532,0.538180,-0.096629,-0.239908,0.028746,0.275138,0.917498,-0.122671,0.083199,-0.039347,0.304488,-0.009302,-0.568082,-0.017613,-0.038460,-0.049676,-0.223911,-0.070394,0.150085,-0.183537,-0.316124,0.656339,-0.072334,0.097587,0.521729,0.249117,-0.143670,-0.155111,0.175804,-0.293113,0.412840,-0.414886,0.482782,-0.184033,0.369904,-0.048350,-0.382617,-0.066500,0.328617,-0.353239,0.322666,0.238015,-0.545644,-0.090082,-0.288687,0.287492,-0.078651,-0.251901,0.219525,0.176881,-0.055537,0.029103,0.497190,-0.337714,0.112240,0.134990,-0.152257,-0.661526,-0.104181,0.012945,-0.136304,-0.601939,0.304723,0.098619,0.000789,0.087367,-0.462952,0.176628,0.243141,0.212182,0.459944,-0.631671,-0.134630,-0.503056,0.419093,0.532862,-0.214664,0.062702,0.329330,0.015930,-0.294050,-0.094719,-0.359437,-0.198370,-0.024713,0.659476,0.266780,-0.095693,0.217859,-0.367038,-0.145928,-0.386700,0.127203,-0.119849,-0.370729,0.156192,0.039571,-0.126495,-0.123424,-0.354044,-0.208590,0.349268,-0.370903,0.848121,-0.690628,0.416366,0.379138,0.253411,-0.513393,0.545226,0.456250,0.026052,-0.271235,-0.008502,0.278728,-0.098937,0.530225,0.205456,0.160885,-0.142144,0.028212,-0.517514,0.273443', '1870681', '27602116', '1309069', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299644', '来的都是客', '剧情', '竹林乡自从办起了竹编工艺社，面貌发生了很大的变化。从此参观取经的、检查工作的、采访的、旅游订货的来客络绎不绝，他们成天成月地吃，为了吃，吵嘴、打架、酒精中毒的事屡屡发生，把精明能干的食堂管理员肖望发折腾得啼笑皆非、苦不堪言。一次，省委郭副书记要到乡里检查工作，为他准备的午饭被县里的领导吃了。肖望发只好把绿豆稀饭、馒头、花生米等家常便饭拿出来，心惊肉跳地准备受罚。不料郭副书记却吃得很高兴，竹林乡的乡亲们从中看到了希望。', '赵本山', '马绍惠', 8.3, 9477, 'tt0333762', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868317761.jpg', 0.1, 1, 15.1, 50, 33.7, '0.581129,-0.371942,-0.378390,0.107751,-0.303158,-0.635137,0.118572,0.736146,-0.595878,-0.181716,-0.121844,0.225518,-0.504624,0.258327,0.316861,-0.435737,-0.260669,-0.311331,0.213527,0.027953,-0.076652,0.158450,0.174690,-0.210981,-0.095694,0.357792,-0.143628,-0.055840,0.259832,0.139130,0.196420,-0.340402,0.414138,0.426001,-0.428901,-0.092898,-0.156065,0.063213,-0.101958,0.091821,0.324129,-0.371182,-0.351390,0.179818,0.640448,0.376257,0.473812,0.288048,-0.526741,-0.009883,0.282933,-0.235328,0.349726,0.141391,0.522754,0.551327,0.025855,0.041006,-0.524304,-0.053304,0.183581,-0.173280,-0.495566,0.087375,-0.102255,0.237368,-0.468285,0.200441,0.054984,0.101475,0.075383,-0.281364,0.551202,0.609788,0.190783,0.649891,0.292327,0.104716,-0.413794,0.430216,0.724460,-0.338536,0.199306,0.094309,-0.109164,-0.154567,0.658110,-0.267208,-0.176991,0.175076,-0.053128,0.020894,-0.285062,-0.147169,-0.419418,-0.011948,-0.179146,-0.656214,-0.059210,-0.184266,-0.374742,-0.665126,0.206655,-0.086841,-0.020057,0.218896,0.274217,0.283964,0.317856,-0.346135,-0.029989,0.437921,-0.026209,-0.584207,0.583667,-0.009723,-0.153076,-0.316469,0.106052,-0.436022,0.160728,0.795336,0.332019,0.718283,0.146854,-0.409467,-0.354886,0.011324', '1293847', '1439400', '1309184', '30214261');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299649', '下一站…天后', '剧情', '家中以卖鱼为生的金大喜（蔡卓妍饰），热爱唱歌的她从小便发明星梦。一个机会让她进入了Harry(陈小春饰)的唱片公司担任歌手Shadow的助手。加入了他们之后才发现，Harry与弟弟阿荣（余文乐饰）不和，Shadow的兴趣更不是在唱歌方面。金大喜极力为他们解围，令原本冷冷清清的一家人多了许多温暖。本来就互有好感的阿荣跟Shadow的撮合下成为恋人。Shadow被唱片公司任命灌录唱片，使五音不全的她十分为难，便开玩笑的要让金大喜帮她开腔，怎料Harry误让老板听到了那首歌，并扬言要大力宣传。Harry只好求金大喜扮演幕后代唱的位置。Hary知道金大喜的心意，并为她争取了一个出演的机会，不料被对头人陷害，最后还是要帮Shadow代唱，令大喜黯然，可是阴差阳错的事情又发生了……©豆瓣', '蔡卓妍', '马伟豪', 6.5, 32575, 'tt0366371', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2255616708.jpg', 1.6, 9.7, 57.3, 23.7, 7.7, '-0.031102,0.131082,-0.669511,0.643310,-0.033990,-0.384523,0.518376,0.226318,-0.398092,-0.110002,-0.209565,0.819700,-0.246894,0.266837,0.188651,0.049349,-0.073886,-0.567389,0.035620,0.010307,0.026250,-0.307850,-0.129340,-0.145144,-0.297099,-0.154021,0.365211,-0.023565,-0.305897,0.445438,0.780487,0.104596,0.067063,0.584716,0.169842,0.043411,0.022014,0.258223,-0.161714,0.066997,0.020416,-0.425553,-0.069593,0.352156,0.184172,0.357578,0.342657,0.054621,-0.154936,-0.117904,0.201493,-0.213961,0.202113,-0.163367,0.178983,0.094315,0.292560,0.219410,-0.486732,0.152345,-0.035558,-0.126715,-1.087021,0.354676,0.303535,-0.197014,-0.888076,0.171655,-0.079022,-0.085179,-0.086220,-0.270400,0.408981,0.591944,0.409506,0.176691,-0.230456,0.088237,-0.458438,0.276906,0.699734,0.147159,0.217105,0.505204,-0.029523,-0.267848,0.080944,0.039366,-0.178025,-0.036879,0.300850,0.161851,-0.039874,-0.306015,-0.537712,-0.224108,-0.196298,-0.090083,0.028760,-0.588649,0.285800,-0.352798,0.058097,0.053642,-0.156300,0.058833,0.301041,-0.384106,0.744458,-0.850571,0.047927,0.467161,0.362342,-0.839962,0.567579,0.355125,0.093320,-0.237931,-0.036338,-0.294516,0.088715,0.108625,0.348556,0.240420,-0.012259,-0.611856,-0.315286,0.234665', '26678784', '30163500', '1304382', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299658', '龙虎风云', '剧情', '本片是周润发早期英雄片的代表作之一。一夜，一名警官在搜查红灯区时，却意外遭枪击身亡，警局高层意识到了这里潜藏着一班不寻常的匪徒。刘帮办联系上了警局一直部署在江湖的卧底，也是他的外甥――高秋(周润发 饰)，要他尽快打入这帮匪徒的内部，获知他们的犯罪计划。高秋化身作枪械贩子，和匪首南哥与他的手下阿虎（李修贤 饰）取得了联系。刘帮办恐自己的外甥出意外，派人暗中跟踪。不料歪打正着反而因为警方的派人跟踪令高秋顺利取得了匪帮的信任，南哥正式拉高秋一起加入他们的抢劫金铺的计划。在与阿虎的点滴接触中，高秋发现自己与他逐渐建立了兄弟情谊。一边是兄弟情谊，一边是社会公义，高秋将如何取舍?©豆瓣', '周润发', '林岭东', 7.7, 17276, 'tt0093435', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166041332.jpg', 0.2, 1.7, 29.6, 50.2, 18.2, '0.351340,-0.023195,-0.577210,0.500698,-0.119260,-0.224782,0.425361,0.107464,-0.728009,-0.143201,0.228110,0.412538,-0.057995,0.016950,0.021919,-0.107721,-0.310381,-0.869915,-0.146795,-0.172637,-0.262056,-0.490455,-0.340308,-0.347673,-0.117848,-0.115497,0.435095,0.231343,-0.377907,0.471462,0.311019,0.145161,-0.347141,0.624451,-0.099294,0.197080,0.299324,-0.181833,-0.338929,0.049716,0.057298,-0.505612,-0.035608,0.070088,0.155832,0.544533,0.595530,0.024866,-0.187174,-0.062825,0.216212,-0.319195,-0.027391,-0.036885,0.671635,0.056365,-0.011834,0.377353,-0.140352,-0.118703,-0.057437,0.039598,-0.854783,-0.094457,0.224334,0.226716,-0.631307,0.276582,-0.213855,0.169118,-0.040677,-0.128649,0.431202,0.501633,0.213196,0.032442,0.094835,-0.247346,-0.532870,0.344583,0.896614,-0.255848,0.170661,-0.033317,-0.044053,-0.475479,-0.104750,-0.101039,-0.118893,-0.060804,0.507343,-0.183788,-0.120023,0.003494,-0.380533,-0.123790,-0.166248,0.093484,-0.177514,-0.409576,0.333549,-0.570986,-0.255552,-0.455533,-0.341166,0.100253,0.079050,-0.127276,0.575100,-0.806131,-0.057956,0.683431,0.285473,-0.582215,0.627331,0.031831,0.095413,-0.262564,-0.095331,-0.260065,0.337810,0.334917,0.368904,0.361060,-0.175517,-0.292551,-0.173639,-0.140790', '3811342', '25908042', '1301022', '1917313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299661', '苏州河', '剧情', '上海苏州河上，用摩托车替人送货的马达（贾宏声）接下送接纯真少女牡丹（周迅）的活，两人相处时，牡丹爱上马达，但就在她决定把终身托付给对方时，马达财迷心窍联合黑道朋友绑架了她，令牡丹心灰意冷跳进苏州河里。临跳前，牡丹丢下会变成美人鱼再寻马达的话。五年后，为自己行为懊悔不迭的马达疑惑牡丹又回来了，开始四处找寻。当在某酒吧里看到扮美人鱼表演的美美（周迅）时，马达认定她就是牡丹，然而美美不过是另一个痴情女子而已。©豆瓣', '周迅', '娄烨', 8.2, 205498, 'tt0234837', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2615399343.jpg', 0.3, 1.6, 17.9, 48.3, 31.9, '0.166526,0.169105,-0.480460,0.304908,-0.079942,-0.455614,0.500038,0.001812,-0.507130,0.064760,0.183875,0.663581,-0.230769,0.129757,0.150527,0.469671,-0.398566,-0.583928,0.050678,-0.267038,-0.023277,-0.123797,0.100784,-0.242741,0.081110,0.079046,0.381740,-0.053845,0.071703,0.565918,0.406696,0.093910,-0.092030,0.313290,-0.133969,0.182926,-0.082548,-0.078245,-0.111546,0.280258,-0.106742,-0.211496,0.148047,-0.075150,-0.150804,0.302140,0.594425,-0.164428,-0.058828,-0.242642,0.267503,-0.102612,0.014799,0.070981,0.033622,0.055198,0.236623,-0.179223,-0.397861,-0.148126,0.272329,0.020440,-0.172319,0.252697,-0.205045,0.037580,-0.747744,0.000601,-0.085791,0.010445,0.442404,-0.124036,0.243458,-0.125565,0.352750,0.319082,-0.239766,0.023846,-0.563840,0.396075,0.615563,0.271932,0.177183,0.690580,0.095964,-0.171607,0.434054,-0.211590,-0.142015,-0.131209,0.013746,0.102485,-0.077661,-0.070077,-0.516168,0.097325,-0.203934,0.253955,-0.026676,-0.248703,-0.392060,-0.430288,0.095766,-0.142707,-0.258512,-0.031906,-0.091624,-0.102045,0.553902,-0.767942,0.132491,0.369557,0.351134,-0.328762,0.686454,-0.017662,0.020154,-0.013647,0.249035,0.114926,-0.202056,0.231642,0.052823,0.147605,-0.225142,-0.041121,-0.271984,0.280730', '1299965', '2124718', '2052978', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299662', '六天七夜', '动作', '奎因（哈里森·福特 Harrison Ford饰）是一个粗鲁乏味的货机驾驶员，洛宾（安·海切 Anne Heche饰）是一个唠叨的职场女强人，二人有着自己各自的生活。但是，所谓千里姻缘一线牵，自从洛宾和未婚夫一起前来夏威夷度假，她和奎因之间的故事便开始了。洛宾在度假第二天便接到工作任务，需要尽快赶往大溪地拍摄明星广告。洛宾央求奎因用货机载她一程，不料飞行路上货机不幸遇上暴风雨，奎因只好紧急迫降在一个荒凉的小岛上。在这里，奎因和洛宾将面临着严峻的生存问题：如何寻找食物，如何寻找活路，以及如何逃过岛上凶险的海盗。奎因虽是个粗人，此时却强有力地保护着洛宾，二人情不自禁地互生情愫，然而身为他人未婚妻的洛宾，心中却有万分挣扎。这段感情，是否只能存活在这个现实世界之外的小岛…©豆瓣', '哈里森·福特', '伊万·雷特曼', 6.8, 12502, 'tt0120828', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209388938.jpg', 0.9, 6, 52.7, 32.8, 7.6, '0.310251,0.016221,-0.741988,0.701026,-0.002949,-0.256917,0.575023,-0.002595,-0.474442,-0.337985,0.132457,0.651856,-0.039271,0.245712,0.157323,0.133828,-0.511876,-0.314229,-0.016530,0.016436,-0.348098,-0.606333,-0.312648,-0.214125,0.022187,0.126143,0.739369,0.245318,-0.016772,0.481759,0.078223,0.376236,-0.450528,0.658093,-0.347128,-0.233860,0.084583,0.038468,-0.279775,0.234067,0.116395,-0.105495,-0.234205,0.113194,0.158190,0.467605,0.484142,-0.181437,-0.103586,0.193234,0.071370,-0.318888,0.219593,-0.100310,0.189674,-0.352818,0.007108,0.115292,-0.257663,0.072789,0.063872,-0.069617,-0.533303,-0.056674,-0.028666,0.070720,-0.576701,0.307616,-0.286738,-0.087654,-0.095788,-0.376974,0.319357,0.517278,0.297428,0.387693,-0.180942,0.089708,-0.394005,-0.070002,0.736820,0.163066,-0.114185,0.236404,-0.126411,-0.376258,0.013134,-0.141544,-0.489037,-0.288938,0.279296,0.206580,-0.274636,0.022823,-0.593822,0.337554,-0.392857,-0.105556,-0.065654,-0.520643,-0.164360,-0.567700,0.277551,-0.381938,-0.353150,0.048351,0.206538,-0.096770,0.634105,-0.541545,0.195164,0.589736,0.177344,-0.375223,0.514651,0.279255,0.314020,-0.215518,0.190293,0.279014,-0.124239,0.228143,0.028315,0.176651,-0.052320,0.149122,-0.432018,0.362566', '34461680', '3606973', '1293952', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299663', '日出时让悲伤终结', '剧情', '17世纪的法国，音乐大师桑德·哥伦布（Jean-Pierre Marielle 饰）沉浸在丧妻之痛中无法自拔，他带着两个女儿远离喧嚣，过着隐居的生活，每当他演奏手中的维奥尔琴时，妻子的倩影便会出现在他的面前。英俊潇洒、才华横溢的年轻人马莱斯（Guillaume Depardieu与Gérard Depardieu 饰）拜入哥伦布的门下，向其学习音乐。心高气傲的他无心师傅的教诲，一心凭着技艺跻身凡尔赛著名琴师行列。师徒俩由此决裂，而哥伦布的大女儿玛德琳（Anne Brochet 饰）则紧随爱人马莱斯的身后。纸醉金迷，物欲横流，被奢华表象所迷惑的马勒斯渐渐丧失原有的真性情，他与玛德琳的爱情破碎，那曾经为爱人创作的《梦中的女孩》也变成不堪的回忆……本片荣获1992年法国凯撒奖最佳摄影、最佳服装设计、最佳电影原声、最佳音效、最佳导演、最佳女配角（Anne Brochet）和最佳影片等七项大奖。', '热拉尔·德帕迪约', '阿兰·科诺', 8.1, 6896, 'tt0103110', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p613051123.jpg', 0.3, 1.6, 19.8, 48.9, 29.3, '0.069382,0.002508,-0.701240,0.926454,-0.090891,-0.408300,0.801171,0.153458,-0.559665,-0.317007,0.227482,1.034018,-0.061569,0.348951,0.522873,0.128878,-0.366445,-0.999591,-0.349545,-0.040674,0.100147,-0.252700,-0.270076,0.065406,-0.396382,-0.270727,0.851591,0.018466,-0.232410,0.567383,0.425133,0.092421,0.005998,-0.003873,-0.333674,0.056523,0.180836,-0.115510,-0.429976,0.264956,0.015491,-0.418395,-0.237410,-0.033908,-0.229617,-0.058679,0.766112,-0.292128,0.199925,0.009706,0.544711,-0.210508,0.082571,0.059580,-0.151549,0.002127,0.315762,0.044925,-0.186147,0.086680,-0.077807,-0.213461,-0.770955,0.052832,0.141843,-0.000438,-0.546759,0.405788,-0.069755,-0.098384,0.149950,-0.003587,0.112021,0.018121,0.231223,0.318106,-0.242392,0.016614,-0.266685,0.596686,0.340035,0.095549,-0.402435,0.357153,-0.072330,-0.529415,-0.084499,-0.452952,-0.573322,-0.167514,0.390614,0.124361,0.194475,0.301485,-0.339876,0.080860,-0.078941,-0.218132,-0.120545,-0.130715,-0.279126,-0.713757,-0.187689,-0.425498,-0.099841,-0.156187,-0.008751,-0.219606,0.820748,-0.742104,0.430240,0.362310,0.046223,-0.141720,0.702083,0.004727,0.124043,-0.308543,-0.449596,0.528020,-0.071528,0.132898,-0.111265,0.228411,-0.106276,0.078427,-0.581767,0.709055', '1870681', '25880986', '1303034', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299665', '偷窥狂', '剧情', '马克（卡尔亨兹·伯恩 Karlheinz Böhm 饰）是一名摄影师，热爱摄影的他随身都携带着他父亲留给他的一台手持摄影机。一起连环杀人案件在城中引起了恐慌，被害者均为女性，死去时，她们的脸上布满了极为恐惧的表情，而仪表堂堂的马克，就是犯下这些可怕罪行的真凶。原来，马克的父亲是一位研究儿童恐惧的心理学家，作为他的实验对象，从小马克就被各种各样突如其来的惊吓所包围，这样长久的恐惧和压抑导致了他扭曲的性格，也成为了一切惨剧的导火索。一次偶然，马克被邻居海伦（安娜·玛西 Anna Massey 饰）的美貌所吸引，正当他准备对海伦下手时却犹豫了。海伦的天真美好暂时治愈了马克的童年创伤，但时常肆虐的疯狂却又让他陷入了与天性的自我纠葛中。接连犯案的马克引起了警方的注意，而在被捕之际，绝望的马克选择了自我毁灭。©豆瓣', '卡尔海因茨·伯姆', '迈克尔·鲍威尔', 7.9, 7942, 'tt0054167', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p741954829.jpg', 0.5, 2.4, 23.1, 49.7, 24.4, '0.350959,-0.018331,-0.668269,0.532456,-0.198425,-0.354722,1.128458,0.104892,-0.474004,-0.285601,0.453554,0.805283,-0.327150,0.348605,0.060658,0.038744,-0.200694,-0.696132,-0.307310,-0.108699,-0.255797,-0.360710,-0.410827,-0.172755,0.024230,-0.494159,0.602627,0.127122,-0.334312,0.523068,0.166289,0.418387,0.119843,0.794883,0.066888,0.082995,0.050585,-0.346411,-0.108353,-0.131967,0.149139,-0.502771,0.025856,0.653283,-0.325740,0.574179,0.914756,-0.358947,-0.186170,-0.098836,0.430588,-0.404933,0.149372,0.421715,0.138845,-0.045460,0.102499,0.029420,-0.336504,-0.017751,0.203692,0.283403,-0.973949,-0.044209,0.061550,0.242642,-0.619207,0.479955,-0.134788,-0.070743,0.173869,-0.108318,0.234970,0.204175,0.234407,0.421275,-0.340894,-0.157152,-0.264394,0.197862,0.739760,-0.169452,-0.381057,0.238520,-0.657096,-0.398082,-0.081268,-0.222213,-0.579426,-0.153501,0.555339,0.101061,-0.176002,0.537272,-0.563954,-0.104084,-0.349957,-0.130911,-0.361819,-0.449795,-0.242890,-0.663279,-0.204656,-0.398493,-0.398329,-0.142792,0.065112,-0.157450,0.734727,-0.651807,0.355865,0.742789,0.027629,-0.414987,0.340666,0.077068,0.046817,0.028613,-0.214946,0.349223,0.034107,0.297464,0.115852,0.419599,0.079796,0.044372,-0.281102,0.765696', '25828589', '10486471', '21619567', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299667', '驱魔警察', '喜剧', '重案组警察在追踪一起贩毒案时遭遇奇怪事件，运毒女子表情呆板、蛮力过人，七八个警察也不能阻止她的前进，最终一辆失控的卡车将该女子撞倒。经调查，警方发现该女子是东平洲三婆的女儿，因此要求三婆前来录口供。为了照顾三婆年迈的身体，在东平洲当警察的丰叔（林正英 饰）前来配合警方调查。丰叔是一名法术高强的警察，他在看过尸体后发现其中有所古怪，进而怀疑有人利用行尸运毒。丰叔的老搭档（午马 饰）情知案件严重，因此拜托丰叔调查。与丰叔配合的是两个不着调的小警察（林俊贤、苗侨伟 饰），他们看中丰叔的侄女（王美华 饰），因此与古板的丰叔闹出不少笑话。随着调查的深入，隐藏在幕后的邪教贩毒组织渐渐浮出水面……©豆瓣', '林正英', '董玮', 7.8, 27164, 'tt0098150', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162764447.jpg', 0.3, 1.7, 28, 46.8, 23.1, '0.213829,-0.323513,-0.461253,0.293136,-0.162938,0.087559,0.630330,-0.002179,-0.788413,-0.267634,0.406210,0.220477,0.043679,-0.155396,0.097782,-0.168413,-0.274183,-0.521434,0.055269,-0.102921,-0.390304,-0.413046,-0.150610,-0.360709,0.053574,-0.236508,0.192859,0.053163,-0.371370,0.412552,0.202432,0.226328,-0.574403,0.162486,-0.011338,-0.011791,0.150732,-0.264641,-0.117236,0.020771,0.006734,-0.255973,-0.197476,-0.120032,-0.001814,0.544373,0.656463,0.111171,-0.387275,0.068912,0.190556,-0.244890,0.044428,-0.200687,0.701819,0.202642,0.042722,0.375502,-0.293551,-0.091427,-0.086648,0.216329,-0.542839,0.350323,0.172066,0.374807,-0.470047,-0.012913,-0.190772,0.011012,-0.079944,-0.224745,0.252876,0.459876,0.063042,0.044386,0.132289,0.064079,-0.406925,0.203053,0.448438,0.086581,0.082963,0.061166,0.016681,-0.399338,-0.112242,-0.215120,-0.080461,0.138212,0.326367,-0.159330,-0.276702,-0.001034,-0.186330,-0.394653,-0.309204,0.162017,-0.260350,-0.116921,-0.128961,-0.535812,-0.155184,-0.127005,-0.132092,0.098762,-0.040361,-0.087903,0.470976,-0.652880,0.043572,0.558677,0.158665,-0.661860,0.357862,-0.009748,-0.048327,-0.349944,-0.310434,-0.259926,0.371522,0.367022,0.186328,0.273099,-0.013808,-0.504776,-0.185326,-0.483956', '3263169', '35073886', '1292829', '3136507');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299680', '整蛊专家', '喜剧', '大好青年车文杰（刘德华 饰）邂逅了公司老板千金程乐儿（关之琳 饰），在乐儿好友Banana（邱淑贞 饰）的撮合下两人迅速陷入热恋。乐儿前男友金默基（李子雄 饰）得知情况后，马上对车文杰产生敌意，聘请整蛊专家古晶（周星驰 饰）作弄车文杰，让他一无所有。于是古晶假扮车文杰父亲车亲仁（吴孟达 饰）从大陆来的私生子，从中捣乱。古晶的到来令车文杰的生活打乱，一切事仿佛都在古晶的操控之中。但Banana发现了古晶的真实身份，劝古晶顾念车家父子对他的照顾，转过头帮忙车文杰对付金默基。©豆瓣', '刘德华', '王晶', 7.9, 260489, 'tt0103328', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2222649480.jpg', 0.2, 1.9, 26.3, 45.7, 25.9, '0.109353,0.068426,-0.462749,0.241091,0.013458,-0.194924,0.403501,0.308679,-0.529332,-0.275862,0.390036,0.323749,-0.132164,0.149121,0.293932,0.153299,-0.292058,-0.482637,0.167523,0.023714,-0.042052,-0.286190,-0.295570,-0.129658,0.110848,-0.275948,0.235245,-0.198711,-0.431493,0.595812,0.229071,0.300472,-0.291186,0.420543,0.123786,0.162527,0.160627,0.178772,-0.646795,0.142519,-0.085698,-0.084031,-0.186447,0.055092,-0.230162,0.276636,0.692410,-0.146080,-0.280839,0.041790,0.277185,-0.256557,-0.084865,-0.153491,0.273353,0.098899,0.218760,0.144318,-0.380307,0.146828,0.056405,0.241947,-0.178540,0.166800,0.183066,0.134474,-0.440894,0.210344,-0.047036,-0.146407,0.119470,-0.262382,0.338380,0.286874,0.177273,0.219005,-0.153496,0.106518,-0.390149,0.226236,0.260954,-0.056586,0.213086,0.362326,0.035629,-0.133303,-0.005563,0.074664,-0.352384,-0.135601,0.205919,-0.081198,-0.120304,0.186826,-0.305562,-0.307172,-0.173653,0.079288,0.116728,-0.552763,-0.071976,-0.444836,-0.407123,-0.175229,-0.160719,-0.148498,0.130614,-0.182178,0.511604,-0.613518,0.045693,0.125813,0.111596,-0.588285,0.436867,-0.105587,-0.061701,-0.537225,-0.227146,-0.058514,0.027518,0.082988,0.007478,0.081848,0.012775,-0.048317,-0.215254,-0.061546', '1480318', '3445516', '2052978', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299687', '错位', '科幻', '赵书信（刘子枫 饰）做了那么多年的工程师，总算被升职成为了局长，然而，令他没有想到的是，等待着他的却是排山倒海般的各类文件和开不完的无聊会议，令他感到窒息。灵机一动之下，赵书信做了一个和他样貌一模一样的智能机器人，将自己不愿意参与的工作打发给这个机器人做，每一次，机器人都能出色的完成这些任务，没有被任何人察觉出破绽。然而，随着时间的推移，机器人的个性开始变得愈发张狂，它渐渐的渗入到了赵书信生活的角角落落中去，甚至开始企图插手主人的感情生活！察觉出异像的赵书信找到机器人和它谈判，要么唯命是从，要么就要被毁灭，面对这样的选择，机器人竟然发动了叛乱！©豆瓣', '刘子枫', '黄建新', 8.1, 16494, 'tt0346810', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247620315.jpg', 0.2, 1.4, 16.6, 54.9, 26.9, '0.414403,0.253770,-0.929740,0.928198,-0.465597,-0.149390,0.761051,-0.115755,-0.566560,-0.414190,-0.221922,0.520462,-0.293408,0.081767,-0.104458,-0.362625,-0.024825,-0.789017,-0.410663,0.004577,-0.366042,-0.452618,-0.005737,-0.445424,-0.095543,-0.083368,0.567881,0.014816,-0.173832,0.227496,0.274355,0.201633,0.280172,0.902915,0.048472,-0.026066,-0.095493,-0.084389,0.098696,0.154911,0.401632,-0.415986,0.174465,0.411367,-0.016213,0.362923,0.670259,-0.237628,-0.232359,-0.104187,0.483637,-0.247135,-0.008515,0.180135,0.127995,0.298052,-0.311140,0.001847,-0.282499,0.099372,0.246508,-0.168832,-0.978663,-0.023926,-0.099463,0.221010,-0.623892,-0.079017,-0.277443,0.075749,-0.135162,-0.642232,0.446389,0.280448,0.436936,0.347284,-0.152502,0.017436,-0.727385,0.391919,0.776667,0.149725,-0.449471,0.270518,-0.052458,-0.628528,-0.008468,-0.303042,-0.080412,0.129855,0.316896,0.293876,-0.106568,0.083654,-0.540927,-0.075830,-0.077567,-0.439919,-0.048929,-0.733628,0.073402,-0.612156,-0.125833,-0.381905,-0.328492,0.323784,0.045386,-0.416607,0.619401,-0.770413,0.106136,0.317109,0.266485,-0.679421,0.537321,0.001555,0.067163,-0.020154,0.326234,-0.037911,0.275860,0.655258,0.621807,0.386450,0.101031,-0.185757,-0.234965,0.589336', '1301022', '1851857', '26981174', '1947270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299711', '大逃杀2：镇魂歌', '剧情', '自从七原秋也与中川典子从新世纪教育法（简称BR）中逃出，两年转眼就过去了。人类社会进入了恐怖主义时代！首都在反BR国家的恐怖分子的袭击下，化为一片废墟。政府当局认定凶犯为七原秋也，开始了对其国际通缉。 七原作为反BR组织“wild seven”的精神领袖，对所有成人发出 了宣战通告。成人为了剿灭七原，发起了一个新游戏——BR2。又一个高中班被军队绑架到荒岛，他们无一例外地被勒令换上军队制服，稍有不从下场就只有死亡！又一场血腥、残忍、惨无人道的大逃杀开始了！本片为《大逃杀》的续集，导演深作欣二在开机伊始便病倒，不久病故，其后的拍摄工作由他的儿子深作健太担任。©豆瓣', '藤原龙也', '深作健太', 5.3, 31208, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p698791440.jpg', 12.5, 29.9, 40.9, 11.7, 4.9, '0.044931,0.252025,-0.555756,0.463330,-0.100096,-0.076937,0.486588,-0.041944,-0.201490,-0.078763,0.328861,0.868390,-0.292796,0.012196,0.421865,-0.003374,-0.275123,-0.802611,-0.385939,-0.292762,-0.394727,-0.151208,-0.092831,-0.287010,0.006933,-0.266364,0.893074,0.285815,-0.288035,0.225988,0.411737,0.289767,-0.076846,0.422318,0.012031,0.197669,0.060352,-0.023941,-0.247401,0.430428,-0.239074,-0.500749,-0.149707,0.152781,-0.282370,0.395477,0.689164,-0.203771,-0.006224,-0.551510,0.544700,-0.476231,-0.410369,0.044994,0.933152,0.055672,0.033265,0.416153,-0.098129,0.177528,-0.179203,-0.077720,-0.519966,0.050544,-0.065809,0.072114,-0.490285,0.408883,-0.209391,0.031650,-0.017340,-0.288957,-0.045555,0.544288,0.197511,0.551177,-0.117815,0.223723,-0.373064,0.255965,0.719648,-0.216158,-0.266442,-0.039633,0.163551,-0.425285,0.092329,-0.290833,0.024034,-0.264005,0.407352,-0.204504,-0.240185,0.324972,-0.705230,-0.056512,-0.375676,-0.491124,0.135716,-0.283369,-0.058533,-0.746734,-0.052818,-0.009904,-0.120693,0.242631,0.201077,-0.099467,0.622774,-0.773005,0.206417,0.416677,0.310692,-0.667030,0.087251,0.247544,0.150648,-0.210082,0.218812,0.066071,0.220229,0.849567,0.412414,0.169740,0.011653,-0.333026,-0.178162,0.287524', '1449328', '1408130', '25723905', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299745', '破坏之王', '喜剧', '快餐店打工仔阿银（周星驰）某日送快餐时邂逅正在武术训练馆学习日本空手道的阿丽（钟丽缇），对其一见钟情。遭遇同样喜欢阿缇的武馆教练林国斌的羞辱后，自觉太弱小的阿银决定拜自称为“魔鬼筋肉人”的达叔（吴孟达）为师，达叔一开始只想骗取阿银的钱财，终被其善良和执着打动，开始教授其中国古拳法。阿丽遇坏人拦截，阿银头戴加菲猫面具出手相救，情急之下从高台上抱着歹徒滚下，却由此创出了“无敌风火轮”，不料事后被林国斌领功。为了证实自己的实力，阿银报名参加了搏击比赛与林国斌决斗，想借此再赢阿丽芳心。©豆瓣', '周星驰', '李力持', 7.8, 164166, 'tt0110852', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165828468.jpg', 0.3, 2.2, 28.3, 44, 25.2, '0.214838,-0.010113,-0.383079,0.355778,-0.112539,-0.373918,0.108421,0.019457,-0.172170,-0.372665,0.240393,0.578672,-0.179139,0.226533,0.128284,-0.217345,-0.001395,-0.517113,-0.129719,0.108569,-0.354060,-0.141352,0.064548,-0.179419,-0.156210,-0.069563,0.185440,-0.082966,-0.455400,0.572178,0.460773,0.180961,0.220894,0.167808,-0.114455,-0.164821,-0.068968,0.095527,-0.267179,0.216758,0.071424,-0.126098,-0.239527,0.112223,-0.240111,0.029607,0.458668,-0.048909,0.048192,-0.328048,0.246987,-0.227138,-0.033211,0.164369,0.035460,0.017384,0.055978,-0.142459,0.226235,0.117999,0.252580,-0.277132,-0.404962,0.024624,-0.069587,-0.277355,-0.454508,0.145107,-0.193691,0.413964,0.125417,-0.115161,-0.189435,0.126806,0.195026,-0.093021,0.072150,-0.078280,-0.251561,0.321361,0.489837,-0.110344,0.169641,0.056755,-0.107786,-0.438484,0.400574,-0.229310,-0.029096,-0.025955,0.364536,-0.044238,-0.097499,-0.074524,-0.500710,-0.233830,-0.154411,0.165758,-0.144319,-0.256205,0.044712,-0.266939,-0.151873,-0.170359,-0.153604,-0.178231,-0.001595,-0.207371,0.835985,-0.813555,0.239540,0.465980,0.296996,-0.213624,0.450397,-0.010986,-0.199165,-0.150006,-0.312376,0.163311,0.100707,0.333832,0.087924,0.362061,0.090915,-0.185947,-0.313446,0.438657', '4127270', '25922902', '1292219', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299765', '回魂夜', '喜剧', '一场阴差阳错的谋杀案，牵连了一栋大厦里多个无辜的人。失恋女（莫文蔚饰）在七月半被男友抛弃，于是把自己关在房里，不断往楼下扔东西发泄。两个心怀鬼胎的保安也在此时酝酿打劫大厦的计划。一对夫妇突然间不见了儿子，遂请求保安队长（李力持饰）帮忙。队长进入二人家中却发现了另一桩与死去老妇有关的凶案。而此时失恋女发现了站在楼道口对着一盆花说话的神秘黑衣人（周星驰饰）。队长发现了夫妇谋杀老母亲的事实，遂被追杀。而此时老母亲的鬼魂前来索命终被黑衣人制服。而夫妇也最终被黑衣人制服后坠楼身亡。含恨的厉鬼就要来索命，牵连该事件的若干人无奈之下只有与神秘的黑衣人合作......©豆瓣', '周星驰', '刘镇伟', 8.1, 213301, 'tt0113356', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2673787975.jpg', 0.5, 2.2, 20.6, 45, 31.8, '0.225301,-0.220563,-0.600992,0.147900,-0.081877,-0.381764,1.050122,0.184245,-0.505108,-0.293979,0.543683,0.625480,-0.336250,0.337682,0.282168,-0.202488,-0.116538,-0.710677,-0.356053,-0.350179,-0.519394,-0.299929,0.038479,-0.206824,0.003190,-0.074877,0.309675,0.061750,0.008899,0.490494,0.561309,0.365677,-0.554288,0.551938,-0.060007,0.182745,0.300592,-0.116207,0.063600,0.165061,0.035254,-0.423599,-0.184395,-0.002276,-0.272992,0.487107,0.719704,-0.390680,-0.099932,-0.094646,0.211926,-0.211585,-0.113039,0.281300,0.679435,-0.032437,0.285502,0.175724,-0.361092,-0.283943,0.284748,0.121869,-0.316564,0.318863,0.019768,0.154123,-0.713650,0.501793,0.064464,0.081683,0.122721,-0.258137,0.383289,0.291202,0.284471,0.406458,-0.173552,-0.135397,-0.561295,0.120229,0.571500,0.002236,0.150139,0.210196,0.187883,-0.175791,-0.129154,0.052839,-0.269981,-0.158552,0.668734,0.013772,-0.219871,0.073194,-0.544544,-0.249778,-0.384475,0.357302,-0.216294,-0.406258,-0.347495,-0.404841,0.003185,0.159316,-0.144249,0.452146,0.092941,0.141753,0.479508,-0.520322,0.176207,0.304958,0.251063,-0.487978,0.661168,-0.135654,0.162090,-0.053778,-0.096226,-0.041070,0.314254,0.404257,0.423580,0.364566,-0.385016,-0.237776,-0.336125,-0.103273', '21619567', '1578663', '20451118', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299767', '鬼作秀2', '恐怖', '本片以分段式描述三个令人毛骨悚然的恐怖故事。故事一：Old Chief Wood''nhead一个印第安人还魂后为被谋杀的小士多店主复仇；故事二：The Raft池塘的食肉浮渣袭击小艇上的四个年轻人；故事三：Dawn Of The Dead富婆在和男妓风流后的返家途中意外撞死一名搭便车的男子……', '汤姆·萨维尼', '迈克尔·高尼克', 7.4, 5508, 'tt0092796', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2542551546.jpg', 0.9, 4.2, 37.2, 40.6, 17.2, '0.158020,-0.290241,-0.345530,0.712147,0.213420,-0.304390,1.408978,0.057745,-0.310484,0.014859,0.111306,0.718829,-0.287547,0.197206,0.560299,0.031150,0.080245,-0.209046,-0.589973,0.040574,-0.517794,-0.293163,-0.164457,-0.384681,0.151314,-0.206105,0.133043,0.028196,-0.412786,0.492288,0.384219,0.295916,-0.524606,-0.042309,-0.441971,0.043321,0.188244,0.155329,0.135725,0.029954,-0.459933,-0.135265,-0.239498,0.018328,-0.768329,0.363578,0.677002,-0.324566,-0.302932,-0.244589,0.258716,0.102528,-0.329426,-0.216848,0.258714,-0.216379,0.604035,0.174566,0.126076,-0.097382,0.091673,0.114905,-0.940621,-0.009405,-0.320648,0.050908,-0.672112,-0.117409,0.031257,-0.009902,0.287129,-0.154414,-0.031940,-0.105788,0.421255,0.415861,-0.236185,0.213577,-0.372455,0.430626,0.636056,0.333448,-0.420995,0.366264,0.347940,-0.209145,0.028187,0.042676,-0.110414,0.002665,0.553088,-0.393584,-0.167892,-0.026412,-0.962252,-0.302895,-0.395782,-0.146854,-0.319145,0.038453,-0.602568,-0.311052,0.139138,0.021772,-0.387887,0.039100,0.564020,-0.020134,0.992628,-0.150955,0.463045,0.746448,-0.432074,-0.513466,0.385136,0.201811,0.070523,-0.159090,-0.302228,-0.249935,0.052476,0.023603,0.099088,0.741937,-0.576510,-0.281688,-0.700061,0.551824', '1578663', '21619567', '1467779', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299769', '第六感生死缘', '剧情', '也许在爱情的天平上，神与人是平等的。死神为了体验人世的悲欢，化身翩翩少年Joe Black(布拉德•皮特 Brad Pitt 饰) 降落到新闻媒体大亨William Parrish（安东尼•霍普金斯 Anthony Hopkins 饰）的家中。机缘巧合，Joe爱上了William的小女儿Susan （克莱尔•馥兰妮 Claire Forlani饰），品尝到人世间爱情的甘醇。这孩子般纯真的，迷恋花生酱的翩翩死神与他美丽端庄的，拥有夜色深邃眼睛的女孩会有着什么样不同寻常的奇遇？他们把爱情谱成乐章，邀你我一同聆听。©豆瓣', '布拉德·皮特', '马丁·布莱斯特', 8, 92598, 'tt0119643', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p511183278.jpg', 0.5, 2.5, 22.9, 45.4, 28.8, '0.363541,0.262657,-0.689075,0.510485,-0.379695,-0.173219,0.932381,0.433004,-0.426471,0.342769,0.480275,0.773877,-0.158653,0.256066,0.556508,0.179614,-0.272862,-0.829070,-0.086285,-0.151924,0.045334,-0.145698,-0.377765,0.079634,0.159527,-0.340744,0.735477,0.123029,0.059584,0.477086,0.217225,0.184106,-0.177256,0.080320,-0.427887,0.023265,-0.126959,0.342445,-0.385647,0.071426,-0.056102,-0.275853,-0.093344,0.203598,-0.402807,-0.133150,0.770945,-0.524663,-0.098619,-0.170071,0.378631,-0.175475,0.170181,0.235558,-0.113268,-0.099651,-0.120804,0.254792,-0.033519,-0.268508,0.087991,-0.029137,-0.797286,-0.264624,0.072231,0.393845,-0.318778,0.443164,0.161604,-0.303940,0.314491,-0.111758,0.103835,-0.093887,0.252004,0.343972,-0.019410,-0.323162,-0.429110,0.620274,0.559485,0.179818,-0.504341,0.423180,-0.637525,-0.534690,-0.237165,-0.258708,-0.655205,0.050696,0.391245,0.172149,0.022070,0.381805,-0.757830,-0.027004,-0.140204,0.178698,-0.094650,-0.605105,-0.208772,-0.450731,-0.399876,-0.854263,-0.269088,-0.097912,0.277147,-0.198522,0.803968,-0.830815,0.347958,0.681006,0.040213,-0.130465,0.924090,-0.072326,-0.388745,-0.511848,-0.091090,0.678617,-0.103751,-0.018591,-0.165439,0.255173,-0.156032,0.798268,-0.496251,0.410674', '5029050', '4058963', '1309161', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299777', '细雪', '剧情', '随着新时代的来临，曾一度显赫的京都蒔冈家慢慢开始衰败，而家中的四个女儿却仍是城中一道美丽的风景。大姐鹤子（岸恵子 饰）固守祖屋，时刻维护着家族的声誉；二姐幸子（佐久间良子 饰）性格刚烈强势，使得上门女婿贞之助（石坂浩二 饰）相形见绌；老三雪子（吉永小百合 饰）温柔贤淑，然对于自己的婚事却总迟迟未决；老四妙子（古手川祐子 饰）个性张扬开放，是一个比较西化的女孩。妙子的绯闻闹得满城风雨，烦恼的鹤子和家人商量，决定尽早为雪子找到如意郎君，以维护门风。不过说起来容易，一向沉默不语的雪子却接连回绝了数门婚事，这倒让欣赏雪子的贞之助暗暗欢喜……改编自谷崎润一郎同名小说，东宝映画50周年纪念作品。©豆瓣', '岸惠子', '市川昆', 8.1, 7457, 'tt0086242', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2258271151.jpg', 0.4, 1.7, 19.2, 50.1, 28.5, '0.127215,0.222996,-0.429628,0.447291,0.147579,-0.273778,0.149771,0.480200,-0.478041,-0.497342,0.213095,0.462007,-0.062932,0.053765,0.200984,0.274529,-0.002937,-0.371834,0.069159,0.128533,0.279703,-0.233230,0.161244,0.059407,-0.340091,-0.133503,0.475628,0.086104,-0.057954,0.432032,0.249628,0.219144,-0.116669,0.073069,0.134651,0.002349,-0.071926,0.094514,-0.188714,-0.080819,-0.092092,-0.122823,-0.369480,0.024538,0.328984,0.462101,0.415503,-0.116410,-0.372467,-0.069314,0.377212,-0.151930,-0.162780,0.235919,0.354914,-0.144875,0.285279,0.320139,-0.365960,-0.367275,0.087910,-0.037248,-0.185957,0.226146,0.434117,0.104569,-0.246995,0.304843,-0.142862,-0.223575,0.156408,-0.377166,-0.003932,0.080278,0.115705,0.146176,-0.184321,0.416886,-0.052923,0.232224,0.405542,0.307026,0.011276,0.180787,-0.190994,0.082547,0.026050,-0.436853,-0.749370,-0.131046,0.133503,0.015864,0.170320,0.255741,-0.220449,-0.099841,-0.310482,0.248605,0.357170,-0.486465,0.001665,-0.390868,-0.069875,-0.356591,-0.406589,0.144518,0.171861,-0.156848,0.932441,-0.580541,-0.311634,0.345072,-0.011413,-0.435670,0.102346,0.225425,-0.144372,-0.099209,-0.139632,0.040078,-0.179732,-0.160121,-0.057224,0.328654,-0.166872,-0.271399,-0.206761,0.213963', '26348103', '25922902', '3445516', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299782', '非常突然', '剧情', '三名大陆赴港的毛贼在白天抢劫金铺后，遇上巡警慌张逃亡，其中一人逃入另一帮被警方通缉多时并配备有强大火力的大陆悍匪躲藏的大厦，紧接着，警方重案组的命运被这两帮歹徒意外牵连，当他们以为成功打死悍匪可以放松庆祝时，又碰上那两个漏网的毛贼，一轮混战后，事情顿时变得非常突然。而与警匪交战主干线并行发展的爱情线来得也非常突然。重案组干将钟健（任达华）和李森（刘青云）在办金铺劫案时巧遇以前认识的茶餐厅老板，就她的芳心到底属谁，众人猜测一番后得到吃惊答案。©豆瓣', '任达华', '游达志', 8, 34310, 'tt0159432', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1275273375.jpg', 0.5, 1.9, 19.6, 52.2, 25.8, '0.233643,-0.247826,-0.836720,0.178892,0.263346,-0.085949,0.580843,0.107650,-0.444315,-0.112705,0.342054,0.615501,-0.403041,0.048135,0.369965,-0.462786,-0.281795,-0.538782,-0.079474,-0.321532,-0.266362,-0.083130,-0.076202,-0.318990,0.291112,-0.053391,0.453352,0.363544,-0.255767,0.560448,0.401363,0.291847,-0.427433,0.684753,-0.179963,-0.046655,0.395248,0.013776,-0.192194,0.040904,-0.444799,-0.093367,-0.103023,-0.041682,0.068154,0.334551,0.598369,0.022227,-0.323775,-0.176993,0.108680,-0.298650,-0.020014,-0.139822,0.751036,-0.012714,0.193843,0.131897,-0.048201,-0.023991,-0.049683,0.077822,-0.804188,0.285946,0.038919,0.110184,-0.394662,-0.028352,0.015190,-0.037811,-0.018368,0.005390,0.514193,0.815328,0.384318,-0.080630,0.082484,-0.159560,-0.630710,-0.062409,0.816844,-0.211055,-0.076789,0.115100,0.199473,-0.591646,0.014818,-0.030135,0.113865,0.107375,0.438665,-0.111678,-0.079053,0.113385,-0.385583,0.109391,-0.129937,-0.038809,-0.288160,-0.454039,-0.201823,-0.640723,-0.014572,-0.007782,-0.368125,0.399819,0.098358,0.137344,0.361081,-0.600703,-0.246020,0.516787,0.236443,-0.555431,0.287401,0.116205,-0.010373,-0.307938,-0.218550,-0.169943,0.345606,0.513095,0.175966,0.357918,-0.244093,-0.269744,-0.123888,-0.058967', '1294941', '1296947', '5157137', '30211551');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299786', '失恋排行榜', '剧情', '罗伯（约翰·库萨克 John Cusack 饰）是个音乐狂热爱好者，他经营着一家唱片店，店里的两名店员迪克和伯利都是音乐爱好者。一天，罗伯的女友罗拉（艾本·叶尤 Iben Hjejle 饰）跟他提出分手，他甚至搞不清楚原因。为此他做起自己的“失恋排行榜”，回顾一路以来失败的恋爱。他发现自己总是充当被甩的一方，于是他决定重新联系这些前女友，询问她们当初选择分手的原因。与此同时，罗拉因为要搬出罗伯的住处而与他一直保持着联系。一次，罗伯从罗拉的朋友口中得知，罗拉居然开始和住在自家楼上的伊安（蒂姆·罗宾斯 Tim Robbins 饰）约会。这让罗伯大受打击，他开始不停地打电话骚扰罗拉和伊安，在他们楼下徘徊。终于有一天，转机到了，罗拉告诉罗伯，她父亲去世了……©豆瓣', '约翰·库萨克', '斯蒂芬·弗雷斯', 7.3, 7302, 'tt0146882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p823489173.jpg', 0.9, 5.5, 37.7, 40.3, 15.7, '0.361947,-0.039839,-0.863601,0.528149,-0.233540,-0.315318,0.625813,0.035299,-0.507307,-0.481140,-0.099529,0.883394,-0.300897,0.710843,0.527723,0.079920,-0.330350,-0.758310,0.334942,0.018832,-0.191861,-0.638945,-0.238439,-0.470611,-0.223383,-0.115488,0.253166,-0.128946,-0.173806,0.435119,0.493676,0.334354,0.117216,0.417132,-0.015059,0.248726,0.265886,-0.079340,-0.106799,0.263554,0.262160,-0.133242,-0.105701,0.227235,0.388367,0.547856,0.510047,0.037653,0.103586,0.336384,0.307204,-0.362537,0.111304,0.018359,0.336622,-0.051905,0.229187,0.196598,-0.284583,-0.145577,-0.025045,0.073773,-0.503453,0.193811,-0.113295,0.130547,-0.815202,0.150827,-0.195037,0.213145,0.079328,-0.521508,0.178788,0.505305,0.335340,0.242849,-0.232520,-0.224715,-0.519276,0.126547,0.747569,-0.041789,0.217309,0.319585,0.051544,-0.199705,-0.117222,0.153876,-0.566927,-0.231555,0.226437,0.013570,-0.041459,-0.013799,-0.437849,-0.292450,-0.178204,-0.239600,0.144012,-0.392628,0.028426,-0.704289,-0.045515,-0.361310,-0.218672,0.005484,-0.147096,-0.292519,0.393740,-0.864950,0.227360,0.408652,0.355870,-0.546694,0.657239,0.139795,0.152252,-0.322860,0.192840,0.406284,0.147049,-0.094709,0.154463,0.302089,0.272337,0.116795,-0.315191,0.358670', '21354767', '1301022', '1302384', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299790', '新最佳拍档', '喜剧', '金刚（许冠杰 饰）与光头佬（麦嘉 饰）在一次泰国的任务中不欢而散，自此分道扬镳各奔前程……时间一晃三年，国宝兵马俑与秦皇宝剑在赴港展出的路上被白手套一伙施调包计窃走，自称“新最佳拍档”的飞贼姐弟（利智&张国荣 饰）再由白手套手中夺走宝剑，并高调登报嫁祸于最佳拍档。一时间，大陆方面派出的中国蓝波（李元霸 饰）与白手套等人均认为退出江湖的最佳拍档是夺剑人，对金刚和光头佬展开连番追捕。最终两个老搭档终于澄清误会，联合飞贼姐弟接受大陆方面的艰苦训练，以期能够为保护国宝而战……本片是《最佳拍档》系列电影的第五集。©豆瓣', '许冠杰', '刘家良', 6.9, 7710, 'tt0098681', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2642861597.jpg', 1, 7.1, 50.3, 28.4, 13.2, '-0.204990,0.015856,-0.351059,0.507584,0.287652,-0.172815,0.123591,-0.098351,-0.304577,-0.192945,0.214896,0.820679,-0.248893,-0.213584,0.261834,-0.207863,-0.196166,-0.918430,-0.201936,-0.092470,-0.186433,-0.064676,-0.230910,-0.009164,-0.312884,-0.343869,0.701968,-0.037291,-0.125519,0.671104,0.687508,-0.037321,-0.374327,-0.042384,-0.077523,-0.223820,0.104064,0.149666,-0.823011,0.539084,-0.018066,-0.014306,0.056918,0.165837,0.063610,0.124188,0.736963,-0.315621,0.050589,-0.353347,0.206338,-0.349341,-0.326953,-0.133519,0.653029,-0.092370,0.358861,0.214299,-0.139007,0.264736,0.144269,-0.212444,-0.555257,0.114894,0.578518,-0.206308,-0.587367,0.379193,-0.198570,0.059042,-0.051168,-0.048808,0.376433,0.539873,0.623647,-0.037483,0.073578,-0.033571,-0.192171,0.587368,0.240463,-0.041487,0.070356,-0.106983,0.307159,-0.278877,-0.084074,-0.189242,0.077411,-0.137538,0.409968,-0.128076,0.207796,-0.024171,-0.716654,-0.137992,-0.362962,-0.028678,0.266535,-0.484663,0.207984,-0.773874,0.124646,-0.453860,0.196679,0.279342,0.334878,-0.166035,0.288233,-0.600699,-0.049885,-0.033318,0.108651,-0.402082,0.618569,0.183299,0.305370,-0.576581,-0.230338,0.052771,0.252961,0.087387,0.070964,0.183828,0.076302,-0.134425,-0.224582,-0.032419', '1780122', '26365262', '25723905', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299795', '非常公寓', '剧情', '麦克斯（文森特•卡塞尔 Vincent Cassel 饰）和女友就要步入结婚的殿堂，他却意外地看到失踪了的前女友丽萨（莫妮卡•贝鲁齐 Monica Bellucci 饰）。往事一幕幕闪回：他们曾经是甜蜜的一对，却因为没有转交到丽萨手中的一封信而错过了这段感情——这个遗憾恰恰是由于丽萨的邻居爱丽丝（罗曼娜•波琳热 Romane Bohringer饰）一手造成，她暗恋麦克斯已久，麦克斯叮嘱她交给丽萨的信，其实一直搁置在她手中。如今，爱丽丝住进了丽萨的旧公寓里。当麦克斯走进公寓想找寻丽萨时，眼前看到的却是爱丽丝。二人发生了关系，爱丽丝终于得到了这个梦寐以求的男人，并且一再设下圈套，让麦克斯和丽萨擦肩而过，终见不得一面。而丽萨的悲剧，还远远不止如此。得到了麦克斯的爱丽丝，还是选择抽身而去，看见麦克斯和他的未婚妻在机场相拥，她脸上露出复杂的笑意。©豆瓣', '罗曼娜·波琳热', '吉勒斯·米莫尼', 8.1, 23014, 'tt0115561', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p581851559.jpg', 0.4, 1.8, 19, 48.7, 30, '0.706849,0.188238,-0.977242,0.486036,-0.137451,-0.721647,1.125458,0.020052,-0.391241,-0.348320,0.336799,0.715489,-0.420980,0.354690,0.229978,0.359292,-0.453997,-0.760937,0.062664,-0.366151,-0.249752,-0.504559,-0.335484,-0.014521,-0.079456,-0.302889,0.459340,0.029294,0.026569,0.614733,0.440871,0.234113,-0.146019,0.568359,-0.167683,0.211209,0.011552,0.137633,-0.294675,0.255172,0.290194,-0.323852,-0.315549,0.322396,0.108649,0.377854,0.558456,0.045220,-0.204416,0.314210,0.184237,-0.280946,-0.026166,0.140574,0.114695,-0.089037,0.159907,-0.011635,-0.411564,-0.178181,0.244564,0.045659,-0.629115,0.148680,-0.063747,0.322070,-0.557731,0.375943,-0.433851,0.021943,0.418172,-0.644758,0.174772,0.318269,0.254396,0.527505,-0.231610,0.082749,-0.511186,0.057501,0.557213,0.031723,-0.059040,0.412959,-0.177523,-0.180797,-0.015272,0.239231,-0.486688,0.135854,0.506085,0.193062,-0.087692,0.234188,-0.440016,-0.253683,-0.440061,-0.036685,0.140687,-0.536121,-0.079754,-0.627051,-0.301782,-0.455805,-0.572232,0.080989,-0.258390,-0.259516,0.306760,-0.704424,0.422948,0.420672,0.383517,-0.178812,0.626220,0.209113,0.131307,-0.064153,-0.116908,0.514182,-0.101795,0.199505,0.241245,0.345791,0.149302,-0.142008,-0.675800,0.468216', '1292211', '1296534', '1300958', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299799', '赌城风云', '剧情', '电影《赌城风云》是由大导演马丁·斯科塞斯与老拍档罗伯特·德尼罗的第八度合作。萨姆·“埃斯”·罗思坦（罗伯特·德尼罗 Robert De Niro 饰）抱着“赌博是一桩需要认真对待的事业”这个信念经营这一家拉斯维加斯的赌场。这个信念使他的赌场生意兴隆，而也让他成为富四一方的大亨。但是自从他娶了妓女出身的金姬（莎朗·斯通 Sharon Stone 饰）后，一切都发生了改变。金姬是个贪得无厌，嗜好酒和毒品的美丽女人，对前男友旧情不忘甚至给他送钱；黑社会老大派来保护萨姆的尼基（乔·佩西 Joe Pesci 饰）总是触犯法律，被警方禁止踏足赌场，还不量力要当老板；萨姆开除了不负责任的雇员却得罪了当地的官员；更糟糕的是，萨姆和昔日的合作伙伴间的摩擦加剧。所有的一切，都使萨姆心神不宁……©豆瓣', '罗伯特·德尼罗', '马丁·斯科塞斯', 8.3, 41449, 'tt0112641', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1236519296.jpg', 0.4, 1.1, 14, 50.6, 33.9, '0.209040,-0.110532,-0.645887,0.458561,-0.264516,-0.424679,0.732909,0.274835,-0.367435,-0.158219,0.024145,0.921203,-0.102095,0.151181,0.280035,0.287469,-0.140262,-0.770177,-0.057841,-0.020611,0.019324,-0.533342,-0.267800,-0.210210,-0.219152,-0.047334,0.176524,0.101070,-0.264927,0.245051,0.476336,0.131224,0.256944,0.274963,-0.120768,0.041715,0.274622,-0.078031,-0.331003,0.087421,0.064897,-0.027421,-0.054829,0.148243,0.162830,0.476048,0.144658,-0.020571,-0.139902,-0.178844,0.274449,-0.423943,-0.039230,0.083180,0.149044,-0.231829,-0.027820,0.421517,-0.332505,-0.104726,0.199144,-0.035866,-0.988562,0.050825,0.107712,0.222773,-0.752108,0.358448,-0.260774,0.038880,-0.179993,-0.100282,0.257900,0.269155,0.254047,0.219111,-0.027640,0.026771,-0.653535,0.104388,0.684667,0.025699,-0.191003,0.224203,-0.315243,-0.303113,-0.017700,-0.254791,-0.578905,-0.073168,0.185406,-0.260021,0.025016,0.321675,-0.579973,-0.145455,-0.144254,-0.220424,0.053730,-0.365144,0.060807,-0.603017,-0.293662,-0.615420,-0.157612,-0.019281,0.369981,-0.166037,0.486650,-0.575926,0.071523,0.574254,0.217674,-0.707733,0.724998,0.304126,0.064941,-0.010155,-0.251430,-0.131966,0.271803,0.278015,-0.018551,0.292220,0.347349,-0.418485,0.076859,0.354178', '26678784', '1783461', '34890458', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299800', '大力士', '喜剧', '海格力斯（泰特·多诺万 Tate Donovan 配音）是宙斯（雷普·汤恩 Rip Torn 配音）的儿子，天生拥有神力，力大无穷。冥王哈迪斯（詹姆斯·伍兹 James Woods 配音）企图叛变，他将海格力斯视作最危险的敌人，于是借机将他贬为凡人，想就此将他消灭。然而，哈迪斯的阴谋并没有伤害到海格力斯，尽管变成了凡人，但在他的身上依旧保留着神力，当他发现自己的真实身份和过往后，善良而富有正义感的海格力斯决定重返奥林帕斯山，然而这谈何容易。一次偶然中，大力神结识了名为梅佳拉（Susan Egan 配音）的美丽女子，可是梅佳拉的真实身份竟然是哈迪斯的手下，通往奥林帕斯山的道路充满了荆棘，海格力斯最终能够抵达目的地吗？©豆瓣', '泰特·多诺万', '约翰·马斯克', 7.9, 10143, 'tt0119282', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1833038181.jpg', 0.4, 1.5, 25.3, 46.7, 26.2, '0.487441,0.366697,-0.812050,0.961813,0.035794,-0.427144,0.493821,0.021394,-0.332965,-0.557922,0.282855,0.884916,0.236787,-0.001669,-0.082129,0.152315,-0.224200,-0.430999,-0.009097,-0.288582,-0.452740,-0.460309,-0.136961,-0.207038,-0.121814,-0.319503,0.715567,0.222616,-0.118615,0.098288,0.275787,0.418327,0.238022,0.415637,-0.183864,0.123090,0.039777,-0.169783,-0.099107,0.547195,0.139644,0.047890,-0.166006,0.676365,-0.010633,0.421114,0.511138,-0.751957,0.124650,0.066244,0.263827,-0.516432,0.328532,0.038195,0.336419,-0.328672,-0.244646,0.273438,-0.168067,-0.295541,0.200643,-0.273916,-0.687039,-0.326419,-0.088426,0.026101,-0.144368,-0.065684,0.176500,0.049014,0.112600,-0.045675,-0.038264,-0.028503,0.364743,0.118926,0.145343,0.015720,-0.363411,-0.097716,0.687838,0.019394,-0.508629,0.364134,-0.337814,-0.530787,-0.317801,-0.828811,-0.431512,-0.033858,0.445916,0.394572,-0.117776,0.598189,-0.506740,-0.246159,-0.588941,0.297598,-0.201582,-0.322471,-0.063799,-0.219664,-0.254153,-0.236063,-0.000274,0.095057,-0.106965,-0.301329,0.536632,-0.876404,0.231065,0.781487,0.314625,-0.270132,0.633283,-0.187261,-0.287448,-0.089044,-0.008158,0.740463,0.412471,0.195612,0.156327,0.114070,-0.063380,-0.104668,-0.414897,0.617591', '3824339', '1303034', '3213270', '6972849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299802', '宝贝小情人', '剧情', '因为有着一个开殡仪馆的父亲加上母亲的早逝，女孩维达（安娜·克鲁姆斯基 Anna Chlumsky 饰）对生离死别有着自己深刻而另类的见解，同时，对于死亡的恐惧也无时不刻的纠缠着维达。在维达的身边， 男孩托马斯（麦考利·卡尔金 Macaulay Culkin 饰）将她的喜怒哀乐全部看在眼里，个性内向的托马斯唯一能够做的事情，就是温柔的陪伴在女孩身边。雪莉（杰米·李·柯蒂斯 Jamie Lee Curtis 饰）的出现让维达有了强烈的危机感，她感到这个女人很可能将要分享父亲对她的独一无二的关注和爱。一次维达造成的意外中，托马斯死去了，看着心爱的人又一次永远的离开了自己，维达痛不欲生，而来自父亲和继母的安慰与教导终于让她明白了要如何珍惜生命里真正重要的东西。©豆瓣', '安娜·克拉姆斯基', '霍华德·齐耶夫', 8.3, 7094, 'tt0102492', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1194943338.jpg', 0.2, 1.1, 17.3, 44.6, 36.9, '0.164920,-0.021270,-1.002890,0.915301,-0.418224,-0.399964,1.173187,0.052054,-0.706985,-0.200071,0.214711,0.953711,0.085461,0.390219,0.193375,0.316080,-0.092655,-0.840652,-0.122683,-0.187193,-0.443934,-0.576636,-0.379081,-0.358051,-0.121474,-0.392873,0.324806,0.009507,-0.038490,0.404456,0.582896,0.458534,0.199402,0.697807,0.006403,-0.083706,0.001020,0.023156,-0.326504,-0.025920,0.471443,-0.023837,-0.055258,0.463423,-0.124366,0.213067,0.688306,-0.536363,-0.234340,-0.094237,0.468130,-0.259499,0.137136,0.128368,-0.162618,-0.042677,0.132808,0.067989,-0.368511,-0.032788,0.200332,0.153901,-0.975494,-0.062821,0.090796,0.243622,-0.828632,0.530066,-0.054684,-0.190702,0.400981,-0.435379,0.269216,0.218138,0.355762,0.519478,-0.425870,-0.021898,-0.248343,-0.064453,0.655819,-0.062742,-0.222788,0.347884,-0.576188,-0.273136,-0.056938,-0.258496,-0.819184,0.118024,0.229565,0.329930,-0.174067,0.325190,-0.356302,0.016224,-0.279237,-0.222587,-0.114634,-0.706634,-0.132127,-0.170793,-0.311464,-0.680723,-0.510231,-0.060916,0.080199,-0.460465,0.981579,-0.931567,0.427870,0.686810,0.460212,-0.529301,0.652953,0.358603,0.054563,-0.397190,-0.137532,0.568905,-0.019923,-0.087291,0.020478,0.352869,-0.003304,0.018150,-0.404937,0.775660', '24756472', '6745433', '4058933', '1300754');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299811', '太阳帝国', '剧情', '1941年上海，中国抗日战争已经历时四年，随着太平洋战争的爆发，英美加入战局，上海外租界的西方人的生活也经历了巨大的动荡，11岁的Jamie就是其中之一。在逃难的途中，Jamie和父母走失，他遇到美国人贝希和弗兰克，差点被他们卖掉，三人辗转到了闸北集中营。在集中营，J amie明白了战争的残酷，学会了“为了吃饭什么事都能干”的生存哲学，还认识了和他一样喜欢飞机的日本小孩。但是，在他内心深处，一直渴望着和父母团聚的一天。©豆瓣', '克里斯蒂安·贝尔', '史蒂文·斯皮尔伯格', 7.7, 22918, 'tt0092965', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p506639780.jpg', 2, 4, 24, 46.2, 23.8, '0.389010,-0.197754,-1.044886,0.393330,-0.009329,-0.443710,0.463547,-0.234866,-0.591880,-0.081454,-0.061950,1.053691,-0.175900,0.440337,0.153841,-0.001255,-0.161056,-0.846848,-0.175199,-0.126898,-0.290454,-0.442681,-0.206174,-0.224771,-0.052627,-0.295446,0.415376,0.380737,-0.134400,0.654497,0.249211,0.119667,-0.068274,0.592584,-0.409223,-0.001340,-0.040245,0.203023,-0.373317,-0.101771,-0.023718,-0.466112,-0.159058,0.015873,0.160271,0.296579,0.532374,0.028359,-0.081483,-0.017740,0.232269,-0.398206,-0.417699,0.137720,0.545987,-0.040611,0.227903,0.329890,-0.080324,0.039203,-0.200959,-0.049777,-0.551895,-0.146578,-0.144547,0.033102,-0.897815,0.783436,0.211297,-0.081884,0.069320,-0.386452,0.397810,0.809656,-0.072450,0.622555,-0.327054,-0.082043,-0.787241,0.426978,1.150996,-0.383524,-0.427954,0.341141,-0.066520,-0.515292,-0.259720,-0.491804,-0.306648,-0.022767,0.140709,-0.251919,-0.601926,0.415409,-0.793763,0.288965,0.045220,-0.538133,0.098396,-0.269888,-0.048424,-0.505118,-0.441913,-0.809678,-0.487261,0.264266,0.053408,-0.165098,0.905867,-0.899421,0.399369,0.821521,0.511676,-0.524743,0.772315,0.239972,0.031460,-0.161593,0.050178,0.267402,-0.165714,0.221813,0.034778,0.381404,0.019529,-0.009356,-0.374145,0.600574', '25721544', '30162520', '1926007', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299830', '山丘之王', '剧情', '以处女作《性、谎言、录影带》一举成名的新进导演史蒂文．索达伯格，在接下来的作品中出人意料地选择了一个十分冷门的题材，从小孩子的角度来反映三十年美国经济崩溃时期的贫民生活是如何刻苦艰辛熬过来的。剧本根据美国作家A．E．贺契纳的童年回忆改编，主人翁是小学生，其父是推销员，其母生病住院休养，弱弟弟被逼送到亲戚家寄养。他一个人住在小旅馆中，依靠朋友的帮忙和自已的随机应变来应付三餐不继的生活。全片并无完整故事，但导演透过一些生动的细节描写和演员的生动演出重塑出一个特殊的时代，童星杰西．布拉德福德长得十分英俊可爱，表现也出奇的精彩。', '杰西·布拉德福特', '史蒂文·索德伯格', 8.1, 6755, 'tt0107322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2174134502.jpg', 0.5, 0.9, 17.9, 56.7, 24, '0.116264,-0.286706,-0.272028,0.639802,-0.221615,0.012151,0.655670,-0.065880,-0.398831,-0.372457,0.090730,0.769093,-0.172446,0.297335,0.261118,-0.206065,-0.326335,-0.316110,-0.017908,0.095791,-0.023880,-0.439596,-0.351804,-0.109169,-0.311469,-0.415240,0.680094,-0.047169,-0.320744,0.142030,-0.074680,0.034510,-0.066826,0.021012,-0.144770,-0.056144,-0.303553,0.065338,-0.168293,0.214374,0.221760,-0.027446,-0.358496,0.077868,0.010618,0.433488,0.674532,-0.078628,-0.240157,0.211549,0.757553,-0.106415,-0.351837,-0.081937,0.114155,0.061983,0.312533,0.003232,-0.143217,0.160931,-0.194053,-0.424220,-0.901301,-0.161332,0.471346,0.235802,-0.568695,0.489557,-0.031522,-0.164506,0.020979,-0.438284,0.080374,0.168659,0.335456,0.580944,0.021567,0.367169,-0.224004,0.399790,0.282630,0.153930,-0.703119,0.526574,-0.468977,-0.493625,0.195449,-0.632428,-0.629199,0.265595,0.022102,-0.277861,-0.166010,0.099083,-0.404369,0.093040,-0.160300,-0.156320,-0.101985,-0.402054,-0.229503,-0.698217,-0.051119,-0.348487,-0.116294,-0.348160,0.135573,-0.466024,0.997892,-0.609773,-0.166856,0.361463,-0.027837,-0.132644,0.576999,0.100253,0.134520,-0.206981,-0.135380,0.188332,0.040958,0.071217,-0.125466,0.332346,-0.037798,-0.239959,-0.544293,0.581617', '27602116', '24284209', '22265121', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299837', '虎胆龙威3', '动作', '西蒙（杰里米•艾恩斯 饰）是个头脑慎密，心狠手毒的恐怖分子。为了实现一场惊天大阴谋，他先是制造了一起爆炸案。在警方紧张破案之际，他又给警长约翰•麦卡伦（布鲁斯•威利斯 饰）打电话，声称警方必须听从他的一系列指令，否则他将继续在全市搞爆炸活动。在杂货店老板宙斯（塞缪尔•杰克逊 饰）的帮助下，麦卡伦完成了西蒙的一系列指令，多次死里逃生。然而意犹未尽的西蒙，命令麦克莱恩去拆除街心花园的炸弹，又宣称在纽约市一所小学校内安放了炸弹。警方和市政官员几乎全部出动，去各小学疏散学生，搜寻炸弹。麦卡伦逐渐对西蒙一个又一个的指令产生疑虑，他终于发现西蒙调动全市警力背后的真相……©豆瓣', '布鲁斯·威利斯', '约翰·麦克蒂尔南', 7.9, 53872, 'tt0112864', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1617435860.jpg', 0.1, 1.1, 23.5, 54.3, 21, '0.137241,0.006553,-0.647067,0.438433,0.054725,-0.031233,0.423426,-0.014894,-0.214342,-0.216774,0.399727,0.435127,-0.243235,-0.123703,0.111622,-0.147845,-0.700105,-0.598787,-0.013621,-0.075069,-0.233103,-0.707865,-0.101047,-0.446897,0.261016,-0.086169,0.222453,0.064540,-0.050324,0.176648,0.245931,0.207097,-0.032493,0.572013,0.145299,-0.059069,0.437699,-0.456843,-0.068069,0.280286,0.056681,-0.448616,-0.044444,0.215334,0.089441,0.498945,0.466721,-0.116998,-0.171401,-0.013028,0.292259,-0.306092,0.051310,0.266236,0.390829,0.313027,-0.317231,0.150899,-0.534742,0.167589,0.330769,0.069659,-0.576825,-0.249823,-0.155585,0.192960,-0.312605,0.139181,-0.213695,0.403228,-0.040046,-0.308990,0.138691,0.352719,0.148893,0.158897,-0.354887,0.208974,-0.395561,-0.005190,0.455532,-0.164109,-0.105491,-0.156114,-0.072447,-0.456421,0.021181,0.336163,-0.155957,-0.163943,0.551191,-0.170496,-0.006686,0.206153,-0.388927,-0.361781,-0.595439,-0.415160,-0.293291,-0.348521,0.009222,-0.969817,0.093518,0.462257,-0.051226,0.097293,-0.064935,-0.071561,0.477443,-0.495854,-0.046385,0.767227,0.063923,-0.379667,0.037788,0.036409,0.251286,-0.235530,-0.062468,-0.119696,0.448116,0.763397,0.274119,0.558253,0.103758,-0.312650,-0.145941,0.101015', '6517421', '2973528', '21349734', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299840', '傻冒经理', '喜剧', '“比家美”旅店的经理二子（陈佩斯 饰）经历一番风雨，终于将旅店搞得有声有色。不料二虎的一根筋却令他处处不讨好，一次听音乐会时遇到工商局的老齐没有票却不懂得让票，张大菊趁机让票讨好。没几天，张大菊的“菊香”旅店在“比家美”对面开张了，“菊香”旅店利用一批美貌妖艳的女子吸引顾客，“比家美”生意大幅下跌。二子为了对抗“菊香”，借钱重新装修旅店，岂料麻烦一个接一个……©豆瓣', '陈佩斯', '段吉顺', 7.5, 4934, 'tt0351712', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2205941536.jpg', 0.3, 2.7, 36.2, 42.8, 17.9, '0.246399,0.414809,-0.287232,0.378950,-0.191086,-0.536811,0.628392,0.170982,-0.138148,-0.128962,0.059553,0.345156,-0.560522,0.154779,-0.118714,-0.060768,0.385728,-0.099650,0.093696,0.289659,-0.250761,0.005381,0.097000,-0.216136,-0.269782,0.198492,-0.083639,0.137918,-0.027110,0.176039,0.066321,0.108683,-0.053811,0.046503,-0.062624,-0.047342,0.336347,0.192314,0.003260,0.322229,-0.424759,-0.534218,-0.540847,0.283342,0.269231,0.359440,0.464836,0.092327,-0.327545,-0.055426,0.246316,0.177343,-0.066924,-0.103402,0.237894,-0.128411,0.456750,-0.165573,-0.610928,-0.226907,0.261795,-0.254288,-0.398036,0.341303,0.059725,0.049543,-0.815641,0.381180,-0.233380,0.153538,-0.030309,-0.387542,0.183123,0.383194,0.310253,0.326649,0.125063,0.329591,-0.549782,0.263289,0.609752,-0.016026,0.240443,0.492042,-0.069736,0.046478,0.355585,0.007906,-0.334916,-0.130481,0.366009,-0.021694,-0.052163,-0.415159,-0.665612,-0.082617,-0.294582,-0.282670,0.120230,-0.308102,-0.166531,-0.788183,-0.072012,-0.194811,0.150561,0.156962,0.570483,0.005680,0.497563,-0.399015,-0.042541,0.404796,0.080563,-0.551050,0.610290,0.062984,-0.168811,0.205703,-0.051641,-0.694091,0.266142,0.098517,0.560422,0.589415,-0.391217,-0.494024,0.009078,0.421055', '1294917', '3183490', '1309101', '1300080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299851', '笑破铁幕', '喜剧', '此片由曾以《空前绝后满天飞》和《家有恶夫》扬名电影界的三位导演吉姆．亚伯拉罕斯、戴维．朱克、和杰里．朱克共同执导，三人共有的特点就是惯以戏谑性的电影手法来泡制笑料。剧情描述一名扬名美国的摇滚乐歌手尼克瑞应邀前往东德表演，邂逅科学家佛莱曼的女儿希拉莉，在得知佛莱曼被囚在监狱制造一种致命武器后，决意帮助她劫狱救父，因此无意中被卷入了一宗间谍案。该片以极端夸张的手法模仿希契科克式的间谍动作，对××主义有较深的讽刺意味，其中也有不少令人忍俊不禁的发笑片断和场面，值得一看。', '方·基默', '大卫·扎克', 7.8, 6488, 'tt0088286', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2252927586.jpg', 0.9, 3.6, 26.5, 43.9, 25.1, '0.281080,-0.166043,-0.473048,0.679014,0.257023,0.009514,0.739396,0.087976,-0.483661,-0.378769,0.162216,0.787184,-0.421521,-0.252537,0.292357,-0.190080,-0.200456,-0.450141,-0.200564,-0.260503,0.055645,-0.602270,-0.211056,-0.295225,-0.059814,-0.540037,0.351330,-0.059200,-0.520974,0.390596,0.337906,0.580164,-0.112255,0.137934,-0.181201,0.010055,0.174545,-0.129281,-0.467822,0.103625,0.098072,-0.167620,-0.295783,0.225290,-0.233840,0.274553,0.468857,-0.218117,0.048735,0.079170,0.359898,-0.321271,-0.024223,0.101763,0.204950,-0.040697,0.203429,0.157919,0.004469,0.039707,-0.045339,-0.137816,-1.026123,-0.064590,0.249507,-0.038052,-0.257600,0.266291,-0.096764,-0.076844,0.024073,-0.008586,0.206965,0.013658,0.494720,0.316133,0.186773,0.058321,-0.325591,0.134785,0.370363,0.064211,-0.246763,0.114851,-0.358893,-0.537062,-0.049397,-0.531738,-0.267133,0.128012,0.328241,-0.318131,0.180641,0.374096,-0.527054,-0.230440,-0.294693,-0.029798,-0.003105,-0.249940,0.027987,-0.909316,-0.182321,-0.254461,-0.068372,-0.334978,0.175790,-0.336586,0.710202,-0.698023,0.095930,0.473381,-0.018162,-0.155126,0.623510,0.060438,-0.000195,-0.256227,-0.324867,0.195484,0.123919,-0.169234,0.037228,0.636979,0.232772,-0.264155,-0.122401,0.176123', '3318306', '1793491', '26577354', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299858', '龙兄虎弟', '喜剧', '伯爵矢志要将失散八百年的圣经所记载的用来对抗魔鬼的五件“上帝的武装”一一寻回，经过一番努力，他寻得包括亚洲飞鹰Jackie（成龙）在非洲土人手中夺得的“圣灵宝剑”等三件，而另外两件在一伙恐怖分子手中。Jackie的朋友Alan（谭咏麟）的女友Laura（关之琳）在时装表演中遭僧侣打扮的恐怖分子绑架，对方期望用她换得所缺的“上帝的武装”。 Alan求助Jackie，Jackie以会从恐怖分子手中抢过来伯爵所缺的那两件“上帝的武装”作担保，从伯爵手中借出他所拥有的三件。Jackie、Alan以及伯爵的女儿西行欧洲，展开救人夺宝的行动。©豆瓣', '成龙', '成龙', 7.4, 29059, 'tt0091431', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2346966817.jpg', 0.4, 2.8, 38, 41.8, 17, '0.271936,-0.106348,-0.516886,0.633926,-0.285690,-0.242422,0.623395,-0.315702,-0.169939,-0.289481,0.645827,0.723142,0.181993,-0.061145,0.422468,0.083379,-0.122918,-0.714198,-0.280961,-0.101278,-0.109321,-0.408627,-0.591632,-0.079610,-0.093061,-0.489357,0.754537,-0.057022,-0.111624,0.011325,0.455558,0.284681,-0.079862,-0.208571,-0.675445,-0.255344,-0.311083,-0.182699,-0.492829,0.563437,-0.040611,0.003016,0.182133,0.424569,-0.062623,0.243974,0.749881,-0.636735,0.363961,0.006280,0.450887,-0.187428,0.145971,0.180051,0.069938,0.477975,-0.063737,0.125517,-0.129810,-0.157641,0.387764,0.043730,-0.807581,-0.300496,0.221853,0.118297,-0.520768,0.357397,-0.332329,0.392523,0.219820,-0.144575,0.179596,0.491292,-0.059045,0.260927,0.015082,-0.215549,-0.673613,0.579863,0.416610,-0.361928,0.179527,-0.068349,0.126517,-0.404574,0.001151,-0.326984,-0.258082,-0.131187,0.586330,-0.103318,0.350963,0.163590,-0.748449,-0.130841,-0.280854,-0.088141,0.397689,-0.257102,-0.072833,-0.679857,0.096578,-0.026567,-0.010689,-0.116153,0.650181,-0.284971,0.674603,-0.481202,0.097724,0.479915,-0.003777,-0.349550,0.227803,-0.247847,0.167062,-0.063277,-0.380322,0.017682,0.791417,0.549454,-0.010374,0.247344,0.422053,-0.132123,-0.169954,0.163866', '25774050', '10467125', '25928048', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299865', '天地玄门', '奇幻', '明代孝宗年间，施家镇出现扶桑鬼王（左颂升 饰）危害人间，并霸占美女施施（王祖贤 饰）为爱姬。鬼王伤害性命无数，惹得天怒人怨，皇上任命正直武官马尚峰（成奎安 饰）捉拿鬼王。正当愁眉不展之际，师爷向马举荐身怀绝技的草芦居士（林正英 饰）帮忙，却得知为除鬼王需牺牲自己的性命。马愤愤返回，草芦居士设计令马尚峰假死，使其化为金甲武士与徒弟（黄一山 饰）担任自己的左右护卫。师徒三人与鬼王展开艰苦鏖战，却由此导致天地玄门大开，正邪双方穿越时空，来至现代。在这里，师徒三人各自遭遇不同的蹊跷趣事。偶然机会，草芦居士发现酷似施施的女医生Gigi。绵延数百年的正邪大战将再次展开……©豆瓣', '林正英', '叶成康', 6.5, 6842, 'tt0088267', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2608041944.jpg', 1.7, 12.5, 54.8, 20.8, 10.2, '0.034748,-0.031850,-0.310829,0.325851,0.289321,-0.197594,0.399210,0.105548,-0.600996,-0.491018,0.444250,0.277672,-0.157716,-0.148673,0.301603,-0.264593,0.163492,-0.471611,-0.110939,0.012626,0.002001,0.039946,-0.200968,-0.070915,-0.388783,-0.323242,0.429106,-0.025358,-0.128113,0.473657,0.274478,0.220560,-0.574842,0.292862,0.063878,0.136006,-0.287062,-0.145695,-0.395025,0.081826,-0.333713,-0.274105,-0.118969,0.032550,-0.309457,0.256219,0.572894,-0.417197,-0.288302,-0.315883,0.324172,-0.088415,0.038784,0.233315,0.307841,0.165625,0.299234,0.096848,0.001867,0.020857,-0.041614,0.084121,-0.227174,0.083650,0.297500,0.064137,-0.231836,0.217993,-0.108761,-0.024365,-0.024491,-0.205037,0.076185,0.472921,0.308085,0.040403,0.049121,-0.201507,-0.394993,0.339425,0.401472,-0.153049,0.136315,-0.220922,0.184731,-0.387057,0.176204,-0.292084,0.128704,0.055591,0.239058,0.002752,0.456637,0.375152,-0.343723,-0.082494,-0.456881,0.443436,0.094567,-0.051434,-0.067898,-0.397587,0.167587,0.038446,-0.092331,0.079407,0.229509,-0.114497,0.352470,-0.402042,0.001335,0.134693,0.372970,-0.225529,0.644943,-0.274551,0.299660,-0.226395,-0.212270,0.182094,0.121882,0.449321,-0.017092,-0.018288,-0.004275,0.094048,-0.135429,-0.211298', '26575103', '6068516', '1306021', '5247058');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299877', '波希米亚生活', '剧情', '在艺术之都的巴黎，几个穷困潦倒的艺术家住在低档住宅区，他们分別是來自阿爾巴尼亞的油畫家、愛爾蘭的作曲家及一個法國劇作家，他们因缘聚合，虽然生活窘迫、境况艰难却一直坚持创作，渴望有朝一日被社会认同，虽然如此，他们依旧乐观生活，渴望爱情，他们互相帮助，顽强努力。机会终于向他们招手，而外省女孩咪咪的出现让他们三人的发生了微妙的变化，画家爱上了她，不久，画家因为非法入境而被驱逐，好事多磨，在好朋友们帮助下他又回到了巴黎当自由艺术家，他不仅事业有了转机也赢得了咪咪的爱情，好景不长，他们的杂志社倒闭了，三人回到了原地，更悲惨的命运等待着他们….。－－－－kavkalu', '马蒂·佩龙帕', '阿基·考里斯马基', 8.4, 5893, 'tt0105750', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2566565531.jpg', 0.2, 0.7, 12.6, 54.1, 32.4, '0.136217,0.117680,-0.776081,0.330086,-0.140672,-0.260831,0.842192,0.156002,-0.466790,0.019678,0.302685,0.776974,-0.122062,0.354629,0.248550,-0.209984,-0.391266,-0.798385,0.259515,-0.019191,-0.118299,-0.133024,-0.364874,-0.266742,-0.366281,-0.071979,0.685329,0.404418,0.105053,0.421361,0.121940,0.020834,-0.051486,0.580018,-0.427754,0.139108,0.221711,0.125046,-0.408276,0.016839,0.176541,-0.447381,-0.235951,0.260561,-0.148296,0.088459,0.731841,-0.121342,-0.501060,0.035274,0.259257,-0.427743,-0.093344,0.261877,0.225509,-0.074186,0.175346,0.065284,-0.086263,-0.037595,-0.206422,0.126320,-0.831840,0.083633,0.116071,0.266060,-0.741754,0.771267,0.179263,-0.196408,-0.040838,-0.402741,0.111933,0.539166,0.302697,0.320330,-0.385675,0.081597,-0.546702,0.238798,0.929810,-0.020725,-0.583323,0.411148,-0.417013,-0.420984,0.008099,-0.242169,-0.635270,-0.103789,0.584935,0.186077,-0.211625,0.224677,-0.639272,0.131651,-0.099897,-0.136013,0.031758,-0.703568,0.132225,-0.635284,-0.072621,-0.470146,-0.447319,0.112005,-0.030964,-0.451348,1.016524,-0.875385,0.056562,0.668444,0.583616,-0.737769,0.718485,-0.014922,0.158589,-0.126244,-0.081963,0.484081,-0.323949,0.463326,0.243279,0.427620,-0.081554,0.178031,-0.364345,0.707360', '30162520', '25721544', '3230462', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299878', '白兰', '剧情', '母亲逝世后，白兰（张柏芝饰）飘洋过海，前往韩国仁川市投靠素未谋面的叔叔，但到了那里才知道叔叔已移民加拿大。她钱财用尽，无奈下只好同人假结婚以获取居留权。白兰从没有见过 “丈夫”李江齐（崔岷植饰），身边只有他的一张照片和一个名字。白兰辛苦打工、身体过劳，生活孤单外还要忍受四周的眼光。唯一带给她安慰的是房里那张“丈夫”的照片，她很感激这名素未谋面的陌生男子，但事实上，对方是个无所事事的中年混混，由于缺钱才会同意假结婚。命运让他们屡次错失见上一面的机会，一直到有件事情发生……©豆瓣', '张柏芝', '宋海星', 7.5, 7505, 'tt0289181', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p637805639.jpg', 0.7, 4, 33.7, 44.1, 17.5, '0.116189,-0.138216,-0.531953,0.479940,-0.239036,-0.300543,0.709618,-0.073848,-0.517727,-0.466478,0.154909,0.857606,0.276766,0.622032,0.153894,0.291767,-0.212732,-0.489194,-0.162549,-0.200801,-0.383721,-0.396642,-0.238687,-0.075268,-0.302078,-0.081792,0.457852,-0.006999,-0.041884,0.545940,0.338151,0.149241,0.017136,0.588007,-0.246170,0.058780,-0.110279,0.232838,-0.246542,0.171243,0.197701,-0.256028,-0.152094,0.276648,0.151917,0.367976,0.424007,0.080400,-0.331296,-0.080230,0.232713,-0.193325,-0.028422,0.108123,0.209798,-0.013168,0.346259,0.052639,-0.312094,-0.216225,0.070182,0.078288,-0.498430,0.221596,0.097438,0.086303,-0.503893,0.275831,-0.232033,-0.094884,0.064256,-0.648088,0.400003,0.345554,0.047040,0.196535,-0.320373,0.201411,-0.377132,0.215392,0.741181,0.188603,-0.061517,0.176671,-0.377070,-0.181437,0.207281,-0.374598,-0.617472,0.187496,-0.123154,0.072172,-0.264625,-0.167145,-0.284654,0.011271,-0.118664,-0.089229,0.093926,-0.301131,0.011510,-0.267847,-0.431443,-0.397535,-0.403496,0.016151,-0.020334,-0.363605,0.591336,-0.557137,0.215544,0.528057,0.622524,-0.586347,0.777340,0.330924,0.037827,-0.182837,0.089434,0.205634,0.136166,0.040383,-0.158148,-0.103058,0.042113,-0.114609,-0.305895,0.296704', '26420626', '1302384', '2990737', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299884', '人到中年', '剧情', '北京某医院眼科大夫陆文婷（潘虹 饰）因长期繁重的工作压力，突发心肌梗塞，生命垂危。把一最宝贵年华奉献给眼疾病人的陆文婷如今人到中年。虽已是眼科资深医师，但仍是工资只有几十块钱的住院医生，一家四口挤在12平米的房子里，生活拮据。家庭生活的担子落在丈夫傅家杰（达式常 饰）身上，自己则没时间照顾儿子园园（郑毅 饰）和女儿佳佳（曹雪 饰），以致佳佳发烧都不能及时抽身送她上医院。工作的压力和生活的重担压垮了她。就在她病倒的当天上午，她还连续给三个病人做了手术。闻讯赶到医院的傅家杰看着从昏迷中醒来的妻子，百感交集。四目相对，耳边盈盈响起匈牙利著名诗人裴多菲那不朽的名句......©豆瓣', '潘虹', '王启民', 8.1, 5033, 'tt0227366', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2370856662.jpg', 0.3, 1.6, 18.5, 52.3, 27.3, '-0.112777,-0.166711,-0.450450,-0.002918,-0.068962,-0.495274,0.771486,0.457094,-0.325823,-0.335636,0.408981,0.539075,0.254327,0.354765,0.267975,-0.165107,-0.220612,-0.675869,0.016912,0.238445,-0.431413,-0.189742,0.003989,-0.153567,-0.004390,-0.326910,0.192816,-0.065320,0.159171,0.406880,-0.063473,0.208767,-0.019096,0.470795,-0.251506,0.025024,0.008233,0.003709,-0.241699,0.339992,0.333945,-0.349741,-0.076836,0.053138,0.225457,0.287733,0.607130,0.335713,-0.238057,-0.076701,0.318791,0.027498,-0.300408,0.005451,0.208578,0.010067,0.440910,-0.002842,-0.516796,0.048334,0.080978,0.018998,-0.567872,-0.048233,0.171263,0.189042,-0.712547,0.699476,-0.190021,0.071940,-0.146729,-0.432695,0.376176,0.235138,-0.390161,0.823490,-0.405225,0.160842,-0.498279,0.443019,0.242877,-0.224725,-0.059995,0.536258,-0.375725,-0.399164,0.259086,-0.196275,-0.502231,0.004889,-0.057457,0.043805,-0.287660,-0.080843,-0.213152,0.174545,-0.113515,-0.410551,-0.149205,-0.140221,-0.092815,-0.245894,0.051591,-0.292467,-0.542294,0.234789,0.374635,-0.028771,0.616414,-0.314769,0.142741,0.282160,0.397555,-0.098690,0.907235,-0.007522,0.378625,-0.015047,0.069726,0.189059,-0.346257,0.497625,0.239400,0.182183,-0.199927,0.005570,-0.416885,0.409273', '1293270', '4066127', '5364952', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299888', '星际旅行8：第一类接触', '动作', '本片是以地球人与瓦肯人的“第一类接触”事件为背景，将重心放在《星际迷航之下一代》电视系列剧中的大敌『博格人』。企业号正在宇宙空间做例行巡航时，舰长皮卡特接到密电，称博格人已联合其他星系的力量，准备向地球发起攻击。由于舰长皮卡特曾受敌方俘虏并同化，星际舰队对其不很信任，故没有派其出战。皮卡特不顾命令，仍然参与战斗，之后企业号跟随博格人的时间漩涡回到21世纪，以阻挡博格人试图改变人类的外星发展史达到征服地球的企图。', '帕特里克·斯图尔特', '乔纳森·弗雷克斯', 7.9, 7715, 'tt0117731', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209408788.jpg', 0.5, 1.9, 24.9, 49.7, 23, '-0.151675,-0.062118,-0.720202,0.745485,-0.072901,0.034781,0.571776,0.316344,-0.449372,-0.065596,0.022905,0.496193,0.234619,-0.338259,0.600214,-0.062519,-0.538714,-0.607437,-0.015317,-0.021547,-0.404300,-0.350327,-0.090634,-0.677375,-0.004742,-0.567595,0.915506,-0.077323,-0.473496,0.054568,-0.076458,0.393091,-0.132442,0.715107,-0.077330,-0.171704,0.008128,-0.657013,-0.515724,0.265205,-0.502548,0.236565,0.017831,0.186137,-0.222654,0.250244,0.576783,-0.464285,0.171866,-0.678556,-0.005720,-0.159664,0.292117,-0.239873,0.688793,0.071185,-0.179363,0.333428,0.272160,0.184925,0.105956,-0.099016,-0.831711,0.070720,0.009982,0.163071,-0.379675,0.191077,-0.547289,0.240572,-0.420223,-0.027110,0.017637,0.605352,0.258966,0.121074,0.018956,0.207015,-0.285696,-0.144362,0.557613,0.056253,-0.669052,-0.057737,0.173982,-0.397436,-0.140202,-0.612250,-0.096723,0.031983,0.202277,0.320432,0.082613,0.595720,-0.695889,-0.108744,-0.351803,-0.752270,0.216127,-0.440566,-0.021951,-1.048611,0.050313,-0.050449,-0.336945,-0.029749,0.230739,0.077934,0.718372,-0.747205,0.055066,0.627399,0.558638,-0.525700,0.847180,-0.183177,0.024145,-0.500039,-0.054593,0.417196,0.316850,0.508511,-0.061572,0.116390,0.076806,0.059813,0.023123,0.242258', '2369613', '1293656', '1307897', '30229667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299889', '暗恋桃花源', '剧情', '某剧场这晚迎来现代爱情悲剧《暗恋》和古装爱情喜剧《桃花源》两个不相干的剧组，因为都与之签定了当晚的彩排合约、又都是演出在即，双方发生争执只为独占唯一的舞台，结果谁都不愿相让只能间隔着排戏。现代悲剧里，江滨柳（金士杰）和云之凡（林青霞）在上海战乱时生出爱情，无奈一别竟是杳无音信大半生，江滨柳几十年来不间断的寻找云之凡从来无果，耄耋之年身患重病的他拿看似美满的家庭事业比对永藏在心间的对云之凡的单纯爱恋，只觉空落。古装喜剧中，武陵渔夫老陶（李立群）被妻子春花（丁乃筝）戴绿帽，每日受尽她及其情人袁老板（顾宝明）的欺辱，某日借口外出打鱼实为想自杀之时，误入桃花仙境，而春花与袁老板结为夫妻后，过的却是比原来更不堪的日子。一悲一喜两戏同台排练，摩擦和尴尬自是难免，却也意外成就了舞台奇观，这戏里出错或可有可无的幕布、道具，一场戏排练完毕留在台上的残迹，竟成那戏天然的一部分。而将两出戏连在一起的，尚有一个找寻某个男人的神情恍惚女子。', '林青霞', '赖声川', 8.5, 54448, 'tt0103699', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194108903.jpg', 0.3, 1.2, 12.5, 43.2, 42.8, '0.166957,-0.135998,-0.641720,0.490841,0.104687,-0.275348,0.942688,0.103256,-0.346703,-0.156236,0.182044,0.707719,-0.552138,0.528075,0.215361,-0.242670,-0.084197,-0.780466,-0.201384,-0.080318,-0.053576,-0.212864,-0.127831,-0.032409,-0.191618,-0.036530,0.586162,0.283656,-0.154851,0.432276,0.430120,0.071949,-0.350336,0.472436,-0.274617,0.028067,-0.280003,0.402362,-0.370153,-0.131469,0.134229,-0.469296,-0.207372,0.244913,-0.057516,0.353355,0.668608,-0.203374,-0.053517,-0.128334,0.394137,-0.061066,0.012185,0.116462,0.219773,-0.068384,0.401310,0.172539,-0.119445,0.172064,0.070813,-0.035006,-0.582271,0.228039,0.246640,0.112490,-0.423134,0.504249,0.261937,-0.034232,-0.132268,-0.072911,0.175546,0.190156,0.463615,0.493758,-0.309514,-0.085316,-0.413240,0.478165,0.663934,0.247358,-0.004475,0.654137,0.033265,-0.467120,0.107349,-0.254634,-0.423813,-0.002701,0.213459,-0.248693,0.164866,0.061355,-0.730657,0.083027,0.023991,0.057068,-0.000461,-0.357398,-0.027526,-0.575069,0.069697,-0.487835,-0.426364,0.155782,0.267460,-0.417909,0.510579,-0.640774,0.082772,0.358813,0.044702,-0.683201,0.617424,0.301496,0.280171,-0.025953,0.107939,0.347129,-0.099401,0.357037,0.131065,0.194225,-0.217419,0.071212,-0.461027,0.4