INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299900', '亚当斯一家的价值观', '喜剧', '亚当斯庄园多了一个刚出生的婴儿，Morticia（Anjelica Huston 饰）被他搞得焦头烂额。Gomez（劳尔·朱力亚 Raul Julia 饰）雇了个保姆Debiie，她很讨亚当斯一家人的欢心。但Pugsley和Wednesday看穿她的用心，用来她是有名的“黑寡妇”，小时候便杀死了她的父母，后来又连续为钱杀死了她的两个丈夫。但当孩子们还来不及告发Debbie时，Debbie已经将他们都送去了夏令营，和Fester叔叔结婚了。婚后，Debbie想尽办法想要把Fester叔叔杀死，还要伪装成一场意外，但每一次都没能得逞。而尽管夏令营很好玩，但孩子们不断的惹老师生气，不停地破坏小朋友们的游戏气氛，为的就是老师能早点把他们送回家，好让他们能警告他们的家人：小心Debbie……©豆瓣', '克里斯蒂娜·里奇', '巴里·索南菲尔德', 8.7, 47374, 'tt0106220', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p652970475.jpg', 0.1, 0.7, 10.5, 39.3, 49.4, '0.150373,-0.204035,-0.476164,0.442598,-0.605177,-0.376852,0.541241,0.027097,-0.399360,-0.061308,-0.237203,0.777942,-0.036268,0.422843,-0.073941,0.230098,-0.119304,-0.556828,0.107237,-0.046072,-0.249441,-0.276463,-0.052228,-0.262385,-0.130605,-0.103351,0.100476,-0.237319,0.181712,0.373975,0.197790,-0.019365,0.236398,0.547150,-0.521806,0.211224,-0.096217,-0.137832,0.059965,0.190406,0.196329,-0.033778,-0.275037,0.361629,0.284776,0.377435,0.651440,0.008220,-0.232661,-0.144166,0.292871,-0.415782,0.070815,0.443853,0.067933,-0.012929,0.476142,0.106803,-0.220210,0.077964,0.322889,-0.011214,-0.884247,0.377379,0.150982,-0.372841,-0.946255,0.410426,0.016627,0.154514,0.159823,-0.300130,0.483576,0.488453,-0.033962,0.385829,-0.342116,-0.096249,-0.732812,0.304093,0.894986,-0.252671,0.093857,0.393777,-0.136176,-0.124662,0.391738,-0.452247,-0.488407,0.244420,0.417030,-0.074676,-0.438385,-0.004023,-0.399356,-0.212113,-0.411550,-0.250983,-0.259710,-0.822339,0.057664,-0.268368,0.072214,-0.359110,-0.444915,0.005752,0.041434,-0.135386,0.867752,-0.631607,0.234826,0.765076,0.338444,-0.691189,0.679606,0.401053,0.038807,0.169900,-0.070376,-0.541275,0.199716,0.295414,0.461329,0.580351,0.186641,-0.338940,-0.330673,0.404722', '1877596', '30163500', '1306530', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299903', '老枪', '剧情', '二战中德军节节败退，但战事的失利没能阻止德军在他们的法国殖民地的大屠杀，相反德军开始了更加疯狂的屠杀。巴黎的医生于连（菲利浦•诺瓦雷 Philippe Noiret 饰）由于感到城里日渐紧张的气氛，他怕家人遭遇不测，于是安排了他的妻子和孩子回乡下暂避风头。于连送了妻子回乡不觉已过一段时间，他决定回乡探望家人。孰料他回到乡下，看到的只剩斑斑血迹，残忍的德军对这条小村庄进行了屠杀。愤怒的于连在村里的老屋内找到了一杆老枪。于连决定向德军举起复仇之剑！©豆瓣', '菲利普·努瓦雷', '罗贝尔·恩里科', 8.2, 8238, 'tt0073864', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2219594603.jpg', 0.2, 1.3, 17.9, 50.3, 30.3, '0.101632,-0.176487,-0.874502,0.242303,0.045438,-0.363302,0.468937,0.154849,-0.569479,-0.105990,0.089699,0.725452,0.011145,0.160383,0.205701,-0.504777,-0.167218,-0.507934,-0.179982,0.166812,-0.222458,-0.424535,-0.167216,-0.517765,-0.122406,-0.343658,0.496581,0.296725,-0.137295,0.450778,0.189647,0.340151,0.072689,0.508194,-0.328480,0.060031,-0.310187,-0.307207,-0.459082,0.099388,0.119019,-0.222851,-0.328091,0.043497,0.146535,0.577908,0.856629,-0.220569,-0.176051,-0.292408,0.339757,-0.290216,-0.060246,0.327933,0.226315,0.072301,0.129004,0.011658,-0.293940,-0.101313,0.194693,-0.132689,-0.294205,0.270135,-0.020901,0.156300,-0.659980,0.533966,-0.271314,0.127516,0.108409,-0.627428,0.438818,0.479486,-0.300218,0.375102,-0.199521,-0.358731,-0.481918,0.292761,0.721626,-0.297511,-0.246018,0.144167,0.073439,0.006838,0.119718,-0.324530,-0.402304,0.082241,0.387880,0.007935,-0.296354,0.328333,-0.576946,-0.167269,-0.343702,-0.585111,-0.008820,-0.251032,-0.226352,-0.616014,-0.012879,-0.393105,-0.302000,0.218333,-0.017358,0.316552,0.343587,-0.860710,0.163742,0.141569,0.343381,-0.520764,0.410536,0.267370,0.175111,0.337562,0.205765,0.319656,-0.125421,0.429177,0.578367,0.166948,-0.194855,-0.044912,-0.183082,0.285840', '1301022', '26418093', '2027925', '1419918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299904', '天劫余生', '剧情', '1972年10月13日，赴智利比赛的一支乌拉圭橄榄球队所搭乘的飞机在安第斯山脉失事。生还的二十多位幸存者面对冰天雪地的生存环境，竭尽全力地以求能活着走出这座荒无人烟的死亡之地。在经历了满心希望的等待着救援队伍无果之后，绝望地他们只能面对着残酷的事实，赖以维生的食物日渐减少，海拔气候寒冷严苛，遭遇好几次雪崩以及内心对死亡充满的巨大恐惧。在激烈的讨论和内心挣扎后，他们开始尝试一些不可能做到的事情，分食死尸。终于，在飞机坠毁五十多天以后，天气渐渐转暖，救援队终于找到了他们。活下来的十六个人终于走出了这块死亡之地，再一次与家人团聚在了一起。由美国导演弗兰克·马歇尔执导的灾难求生影片《天劫余生》，根据英国作家皮尔斯·保罗·里德的报告文学《活着：安第斯幸存者的故事》的真实事件改编而成。影片对于人性生存渴望的写实描绘，曾一度激发美国社会对于生命与道德的激烈探讨与辩论。', '伊桑·霍克', '弗兰克·马歇尔', 8.1, 12949, 'tt0106246', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1466805847.jpg', 0.3, 1.5, 18.8, 51.9, 27.5, '-0.103756,0.039021,-0.837405,0.495361,0.290562,-0.198430,0.636977,-0.072977,-0.529942,-0.187313,0.248986,0.593419,-0.181344,0.120750,0.194448,-0.495987,-0.533401,-0.585252,-0.237672,0.044747,-0.428770,-0.351369,-0.258824,-0.220902,-0.026922,-0.226212,1.003257,0.628470,-0.085105,0.401545,-0.169739,0.230348,0.004402,0.367885,-0.263759,-0.269659,0.049060,0.085920,-0.715063,0.325991,0.117975,-0.199358,-0.308599,0.055522,0.006811,0.153180,0.843441,-0.425985,-0.244722,0.124781,0.176450,-0.473088,0.001239,0.120661,0.152546,-0.083520,0.139065,0.328168,-0.121051,0.039106,-0.203469,0.017042,-0.651315,0.034839,-0.132457,0.199055,-0.350199,0.464121,0.005676,0.017546,0.112501,-0.367911,0.137012,0.501452,0.259480,0.601626,-0.364721,-0.096649,-0.309215,0.053851,0.931109,-0.256469,-0.315874,0.162729,-0.298161,-0.552840,-0.078732,-0.472825,-0.467970,-0.080165,0.321844,0.292400,-0.392887,0.511423,-0.747910,0.238158,-0.265150,-0.593342,0.080599,-0.185180,-0.027533,-0.696958,-0.158749,-0.240430,-0.181190,0.004175,0.113333,-0.238693,0.781123,-0.575611,0.417527,0.521368,0.243091,-0.365408,0.340018,0.137386,0.002140,-0.219233,0.155931,0.596642,-0.331752,0.419154,0.084179,0.211537,0.004396,0.183103,-0.378398,0.476273', '1302050', '129244