INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299922', '落跑新娘', '喜剧', '艾克(理查•基尔 Richard Gere 饰)是一名专栏记者，他的妻子就是顶头上司。然而，这并没有给他带来多少好运气，相反，和妻子性格不合离婚后，因这层关系艾克过得更加抑郁。一次偶然，艾克在酒吧里听闻了马里兰州一名女子玛琪(朱莉娅•罗伯茨 Julia Roberts 饰)三次踏上红地毯时临阵脱逃的故事。他对这件事深感兴趣，并将其写成了专栏。当艾克去到实地采访当地人时，没想到人们普遍对他的做法感到很愤怒。而即将第四次踏上红地毯的事件主人公玛琪因为看了艾克的专栏后大感尴尬，第四次临阵逃脱。玛琪认为是艾克害惨了自己，决定以牙还牙。©豆瓣', '朱莉娅·罗伯茨', '盖瑞·马歇尔', 6.8, 24085, 'tt0163187', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1080986510.jpg', 0.7, 6.6, 51.7, 32.8, 8.2, '0.387697,-0.108689,-0.694896,0.658598,-0.050080,-0.231239,0.759038,0.093500,-0.703940,-0.170764,0.074318,0.795874,-0.539210,0.094049,0.426748,-0.036073,-0.244232,-0.507043,0.112403,-0.220543,-0.513952,-0.369231,0.042551,-0.224526,-0.341787,-0.257711,0.542104,0.211469,-0.211688,0.496102,0.492877,0.415557,0.288639,0.727475,0.189929,0.198765,0.222408,0.133674,-0.118656,0.249280,0.118945,-0.188786,-0.146273,0.624426,-0.032177,0.417353,0.429235,-0.240413,-0.393967,0.054650,0.431937,-0.226440,0.226964,0.283868,0.299657,0.049381,0.331059,0.239429,-0.094590,-0.196045,0.103531,-0.002850,-0.514878,0.211185,-0.141693,0.170070,-0.486757,0.464850,-0.313852,0.045369,0.097479,-0.327141,0.003184,0.116955,0.481552,0.088199,-0.158693,-0.174471,-0.225564,0.174032,0.601580,0.248579,-0.045763,0.597170,-0.185115,-0.395204,-0.003775,0.167121,-0.438754,0.269700,0.345452,0.117202,-0.198743,0.203465,-0.369122,-0.332206,-0.317706,-0.246079,-0.162316,-0.299829,-0.037535,-0.393443,-0.038975,-0.266397,-0.425357,-0.078108,0.089100,-0.317723,0.419001,-0.817245,0.273118,0.496777,0.171871,-0.457298,0.588238,0.310137,-0.043544,-0.218587,-0.087176,0.163937,0.122681,0.085884,0.183847,0.284646,0.168904,-0.437050,-0.227082,0.687614', '1309172', '3213250', '1308755', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299923', '喜福会', '剧情', '晶妹（温明娜 饰）的母亲宿愿（翘征 饰）生前讲过一个有关鹅毛的故事。宿愿过世后，好友林冬（周采芹 饰）、安梅（卢燕 饰）、映映（阮兰丝 饰）联系上了宿愿早年失散的双胞胎女儿。晶妹决定远渡重洋与两位姐姐相认，众人齐聚宿愿家为晶妹践行。聚会上，林冬、映映、安梅各自忆起了被母（奚美娟 饰）抛弃、杀死亲子、等候母亲（邬君梅 饰）的往事，而三人女儿钟韦弗利（富田谭玲 饰）、琳娜（劳伦·汤姆 饰）、罗丝（赵家玲 饰）的婚姻也深受各自母亲的影响。聚会后，晶妹的父亲（冀朝理 饰）讲述了宿愿遗弃双胞胎的真相……©豆瓣', '周采芹', '王颖', 8.4, 46472, 'tt0107282', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1269318004.jpg', 0.6, 1.8, 13.6, 43.6, 40.3, '0.064573,-0.092522,-0.348483,0.364906,0.276667,-0.464109,0.432505,0.234104,-0.492531,-0.376203,0.323160,0.737136,-0.079974,0.436523,0.138865,0.117231,-0.274602,-0.698123,0.320940,-0.235758,-0.111218,-0.442568,0.053885,0.135228,-0.051071,-0.097788,0.170252,-0.294254,0.183676,0.666644,0.356552,0.305269,-0.415680,-0.139987,-0.005168,0.277196,-0.092960,0.361399,-0.547422,-0.160717,-0.452190,0.135910,0.238738,0.190944,-0.002036,0.257159,0.648219,-0.313180,0.249262,-0.491898,0.260643,0.121068,0.141279,0.431177,0.274648,0.301761,0.269459,0.472916,-0.427010,-0.149830,0.083146,-0.029416,-0.158044,0.013147,0.556601,0.205583,-0.565629,0.330535,-0.090077,0.038231,0.042219,-0.168236,0.185407,0.405942,0.103778,0.329781,-0.175602,0.107606,-0.061143,0.508233,0.516785,-0.388761,0.419034,0.176132,-0.128982,0.002287,0.074313,0.001087,-0.521902,0.026248,0.201191,-0.006471,0.204689,0.392680,-0.509893,-0.641804,-0.313001,0.247549,0.255623,-0.218767,0.233657,-0.554133,-0.213048,-0.473582,-0.523273,0.009823,0.090936,-0.178586,0.751750,-0.428848,0.268344,-0.090517,0.146501,-0.422157,0.429135,0.172664,0.391385,-0.425357,0.250561,0.580817,-0.012243,-0.380532,-0.231379,-0.115982,0.046984,0.062572,-0.439754,-0.021577', '3811356', '6814906', '1307146', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299932', '恐惧的代价', '剧情', '马里奥（伊夫·蒙当 Yves Montand 饰）是一个游手好闲的混混，在那个小镇里，所有的人都在找工作，可是没有一个人有正式的工作。就是这样一个贫穷的地方，每天还有无数人前来淘金，落魄的商人吉奥（查尔斯·文恩 Charles Vanel 饰）就是其中的一员。同时，命不 久矣的鲁奇（Folco Lulli 饰）和嚣张跋扈的班巴（彼得·范·埃克 Peter van Eyck 饰）也出现在了当地鱼龙混杂的酒吧里，他们的目标只有一个，那就是赚钱。此时，500公里外的S•O•C石油公司的油井燃起了熊熊大火，为了灭火，必须有人驾驶着装有十吨硝化甘油的卡车开往此地，而对于公司的雇工来说，这无疑是自杀的举动，因为只要有任何一点点的颠簸和受热，十吨硝化甘油就将化为十吨威力无比的炸弹。无良的老板打起了混混们的主意，因为即使他们死了，也不会有工会来追究责任。马里奥、吉奥、班巴和鲁奇获得了这个危险的任务，并被允诺每人将有2000美金的酬劳。就这样，为了金钱，一行人将性命捏在手里，驶上了危险与恐惧并存的不归路。', '伊夫·蒙当', '亨利-乔治·克鲁佐', 8.7, 11796, 'tt0046268', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204999616.jpg', 0.4, 1.3, 10.3, 41.2, 46.9, '0.443326,-0.053308,-0.777881,0.520770,-0.430515,-0.195417,1.006692,0.103780,-0.472732,-0.080555,0.189232,0.918419,0.052898,0.071682,0.048184,0.017052,-0.064083,-0.481286,-0.345519,-0.384495,-0.270888,-0.528621,-0.172490,-0.357398,-0.188163,-0.136303,0.500303,0.207412,-0.020260,0.390153,0.459075,0.238920,0.259677,0.593832,-0.438325,-0.032365,-0.015223,-0.137418,0.087290,0.251179,-0.004735,-0.209293,0.146633,0.233675,0.179729,0.509593,0.519811,-0.211560,-0.156664,-0.024952,0.185065,-0.404548,0.086636,-0.071661,0.350895,-0.178876,0.187572,0.065666,-0.442728,0.170998,0.330822,-0.034071,-1.113992,-0.072688,0.074399,0.128534,-0.757092,0.524127,-0.119155,-0.456283,-0.003156,-0.153416,0.440858,0.276386,0.159807,0.090717,-0.228195,-0.122068,-0.908003,0.047725,0.634108,-0.079864,-0.160674,0.251428,-0.296123,-0.373853,-0.059019,-0.392589,-0.299811,-0.203469,0.444835,-0.030394,-0.145697,-0.101101,-0.721209,0.316556,-0.126384,-0.383329,-0.062144,-0.258351,-0.251396,-0.484541,0.192493,-0.338639,-0.426587,0.348224,0.241720,-0.083723,0.762162,-0.697462,0.035529,0.662235,0.491556,-0.530431,0.756459,-0.105492,0.028604,-0.086227,-0.089691,-0.091951,0.183074,0.547701,0.124997,0.453531,0.012576,-0.273812,-0.136541,0.660365', '1793491', '4944008', '1783461', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299952', '小鬼当街', '喜剧', '百万富翁卡尔维夫妇9个月大的儿子比克（亚当•罗伯特•沃顿 Adam Robert Worton 、雅各布•约瑟夫•沃顿 Jacob Joseph Worton 分饰）长得十分聪明可爱。卡维尔夫人想让她的宝贝比克成为明星宝贝，于是约了一位在当地颇有名气的摄影师为比克拍摄一辑婴儿照片，准备登上杂志封面。这时，艾迪（乔•曼特纳 Joe Mantegna 饰）、诺比和威高三名歹徒假扮摄影师，掳走了比克。艾迪三人原想利用比克勒索卡尔维夫妇五百万美元。谁料，比克聪明过人，不但将三个贼人玩得团团转，还顺利从贼窝里逃了出来。艾迪等慌忙出外寻找比克，最后比克能否顺利回到父母身边？©豆瓣', '亚当·罗伯特·沃顿', '帕特里克·里德·约翰逊', 8.2, 49309, 'tt0109190', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2539524010.jpg', 0.3, 1.3, 18.4, 48.2, 31.8, '0.072206,-0.212878,-0.498643,0.432528,0.041902,-0.710906,0.340178,0.216979,-0.067879,-0.251769,-0.025227,0.683852,-0.504177,0.257767,0.335970,0.371827,-0.759240,-0.533703,-0.225725,-0.207797,0.016791,-0.419221,-0.339426,-0.321598,0.010881,-0.298668,0.013319,-0.219409,0.618917,0.391248,0.282573,0.216327,-0.099945,0.028889,-0.150103,0.547302,0.564086,-0.581021,-0.078790,0.391603,-0.072657,0.363712,0.056895,0.005281,0.328837,0.242458,0.521238,-0.248727,0.325494,0.060764,0.148880,0.153388,0.054735,0.078819,0.329654,-0.410666,0.055270,-0.312309,-0.282402,0.024961,-0.067549,-0.199581,-0.563040,0.420934,-0.250509,-0.061431,-0.688458,-0.047865,-0.291930,0.324731,0.287507,-0.182086,-0.094578,0.285260,-0.004739,0.197803,0.284849,0.434974,-0.254571,-0.065701,0.299482,0.101431,0.150445,0.105492,-0.055584,-0.299930,0.051891,-0.218682,-0.395395,0.050257,0.831375,-0.337058,0.267706,-0.065326,-0.172985,-0.380546,-0.785906,0.052162,0.044392,-0.101380,-0.222035,-0.640260,0.221269,0.162157,-0.165521,-0.261604,-0.165706,-0.258943,0.947568,-0.129195,0.145388,0.603847,0.174603,-0.195340,0.464886,-0.199192,0.346303,-0.135173,-0.090488,-0.032474,0.332681,0.161498,0.570484,0.344407,-0.163440,-0.460124,-0.047114,0.105523', '1829654', '27602116', '26665875', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299957', '猛鬼街2', '惊悚', '上一集南茜将恶魔佛瑞迪（罗伯特•英格兰德 Robert Englund 饰）的鬼魂封在了钢爪手套后，她举家搬出了艾姆街。男孩杰西（马克•佩顿 Mark•Patton 饰）一家搬了进来，自从杰西住进这座房子，他就不断的作恶梦，搅得他不得安生。一次偶然，杰西在地下室发现了南茜留下的钢爪手套，因此佛瑞迪的鬼魂得以逃脱封印。重获自由的佛瑞迪利用杰西的身体开始四出作案，尽管杰西努力控制自己想以此对抗佛瑞迪的控制，可是佛瑞迪的邪恶意识太强大了，杰西根本控制不了自己。当佛瑞迪将魔爪伸向杰西的女友莉莎时，这时候只有杰西才能挽救她，杰西最终能否战胜恶魔？©豆瓣', '马克·帕顿', '杰克·舒德', 6.3, 6120, 'tt0089686', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177124235.jpg', 2.9, 17.9, 51.9, 18.1, 9.2, '0.251655,0.269960,-0.341113,0.131272,-0.256783,-0.438066,0.604125,0.180355,-0.315626,-0.158294,0.538119,0.343982,-0.143612,0.050384,0.035050,0.248320,-0.224132,-0.534255,0.443942,-0.013483,-0.389222,-0.178640,-0.660043,-0.280591,0.142127,-0.518271,0.459228,-0.051746,-0.055950,0.004902,0.144431,0.301951,0.079615,0.250019,-0.062472,0.197352,0.019790,-0.444585,-0.202217,0.421105,0.117916,-0.209783,-0.130687,0.512061,-0.161354,0.348591,0.730334,-0.491662,0.034278,-0.026361,0.317375,-0.160925,-0.231937,0.191000,-0.028527,-0.219637,-0.017832,-0.009995,-0.272791,0.072378,0.428884,0.110560,-0.508946,-0.032414,-0.076950,0.110268,-0.427914,0.264119,-0.114889,0.228204,0.085878,-0.440915,-0.189644,0.375712,-0.026912,0.213923,-0.144086,-0.024873,-0.481398,0.066506,0.366187,-0.520136,-0.291913,0.218142,-0.149087,-0.250922,-0.125658,-0.218895,-0.296219,-0.214602,0.664591,0.269237,-0.379966,0.167580,-0.450955,-0.424258,-0.663697,0.030664,-0.005048,-0.189374,0.050753,-0.423448,-0.281939,0.162029,0.088690,-0.308726,-0.188637,-0.281596,0.184643,-0.718532,0.390865,0.774034,0.431180,0.028558,0.298880,-0.249846,0.253969,-0.098421,0.074410,0.249598,0.273304,0.599135,0.633132,0.303285,0.170268,0.021716,-0.251749,0.744500', '3077408', '1793912', '1300324', '1301232');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299965', '长短脚之恋', '喜剧', '阿美（王祖贤 饰）是个美丽的女孩子，可是天生脚就有残疾。她的父亲（黄霑 饰）因被堂叔欺骗买下了一间破旧不堪的超级市场，花掉了毕生积蓄的父亲变得疯疯癫癫的。阿美既要照顾父亲，又要帮忙打理超级市场，生活的重担落在了她的身上。在一次交通意外中，司机梁少祖（周润发 饰）以为自己 把阿美撞至残疾，十分内疚，便决定要帮助阿美经营超级市场。阿美一开始并不信任梁少祖，到后来他联合朋友来帮助自己的超级市场度过难关，心里满是感动，两人更坠入了爱河。©豆瓣', '周润发', '王钟', 6.9, 10970, 'tt0094852', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2347551721.jpg', 0.9, 5.6, 52.5, 30.6, 10.4, '0.044672,-0.113607,-0.668481,0.279991,-0.345829,-0.590091,0.743906,0.234213,-0.464108,-0.067692,0.363193,0.743795,0.009705,0.176782,0.114108,0.301898,-0.077779,-0.492313,0.089569,-0.036810,-0.260489,-0.335841,-0.142825,-0.319623,-0.357019,-0.114529,0.323822,0.060948,-0.152714,0.294573,0.185787,0.199798,0.084948,0.545990,-0.270051,0.080241,-0.275557,0.016132,0.054501,0.138355,0.097345,-0.153326,0.120686,0.294120,0.128725,0.410214,0.624331,0.153765,-0.109411,-0.165591,0.202668,-0.088683,0.060771,0.227166,0.195711,0.086552,0.132644,0.150879,-0.655559,0.036545,0.345715,-0.226802,-0.647806,-0.026414,0.155985,-0.044224,-1.037754,0.452553,-0.072147,-0.096387,-0.034272,-0.468255,0.207003,0.223118,0.139908,0.555100,-0.128993,0.110446,-0.427662,0.184872,0.760520,-0.072220,0.263680,0.601137,-0.336871,-0.131902,0.122937,-0.016693,-0.496464,-0.047290,0.360477,-0.028621,-0.072178,0.085927,-0.508152,-0.136458,-0.282782,-0.092285,-0.296934,-0.495166,0.082717,0.034677,-0.163899,-0.213983,-0.195509,-0.007086,0.285305,-0.198114,0.565336,-0.958056,0.013475,0.408367,0.435767,-0.517343,0.515560,0.080694,0.051293,-0.131586,0.021890,0.228571,-0.107264,0.140487,0.104351,0.246580,-0.066500,0.028109,-0.277923,0.405305', '1783461', '2124718', '24698878', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299966', '重案组', '剧情', '这是根据香港当年轰动一时的王德辉绑架案改编。香港富翁王一飞（罗家英 饰）自上次被绑架安全回来后，现在再度遭到绑架了！警局高层高度关注此案，此案的资料甚至视为高度机密。年轻有为的陈帮办（成龙 饰）负责侦察此案，由于多日来毫无头绪，他只能去请教之前将王一飞从劫匪手中救回了的老警察洪爷（郑则士 饰）。洪爷为陈帮办提供了不少办案思路，陈帮办根据洪爷的指示一步步追踪案件的真相。但是，随着案件逐渐进入高潮，陈帮办忽然发现自己似乎被歹徒玩弄于股掌，他的一举一动歹徒竟然了如指掌！歹徒究竟有何本领令到陈帮办一再受挫？©豆瓣', '成龙', '黄志强', 7.3, 15497, 'tt0108656', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2207572277.jpg', 0.4, 2.7, 40.6, 43, 13.2, '0.017162,0.096982,-0.537331,0.347983,-0.084764,-0.155563,0.360810,-0.219426,-0.753202,-0.636677,-0.017079,-0.019505,-0.155012,0.053688,0.147717,-0.362706,-0.383059,-0.835054,-0.253857,0.010532,-0.522502,-0.593240,-0.313217,-0.320215,-0.107598,0.266233,0.217925,0.326860,-0.473817,0.238186,0.358512,0.486633,-0.232040,0.487690,-0.055779,0.125553,0.393942,0.023911,-0.243203,-0.069131,0.290003,-0.816119,0.059128,-0.037195,0.272748,0.538846,0.651764,-0.120844,-0.381275,0.017061,0.506881,-0.223405,0.094433,-0.141732,0.528994,0.368910,-0.043442,0.050425,-0.307595,-0.231447,0.016173,-0.167860,-0.527264,-0.087891,0.197465,0.040913,-0.186479,-0.600939,-0.325218,0.441010,0.059113,-0.396793,0.230144,0.389101,0.282473,0.052440,0.185183,0.125905,-0.374359,0.385291,0.597634,0.190391,0.065578,-0.374827,-0.078500,-0.578415,0.068510,-0.045269,0.253636,0.203093,0.524343,-0.079440,0.146177,0.188344,0.156557,-0.599007,-0.202060,-0.007175,0.037422,-0.263117,0.102882,-0.537726,-0.125611,-0.238578,0.066021,-0.029658,0.114705,-0.222594,0.218157,-0.581573,0.148676,0.453862,-0.183691,-0.709339,0.284902,-0.076034,0.126022,-0.247678,-0.084184,-0.112817,0.628018,0.576952,0.207145,0.186885,0.113344,-0.451745,-0.031273,-0.028430', '25870679', '1300299', '26835911', '5422105');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299967', '剃刀边缘', '悬疑', '家庭主妇凯特（安吉·迪金森 Angie Dickinson 饰）和丈夫的婚姻生活乏善可陈，儿子皮特又（凯西·戈登 Keith Gordon 饰）终日沉迷于自己的发明之中。对此她经常向艾略特（迈克尔·凯恩 Michael Caine 饰）求助，甚至想引诱这位高大英俊的心理医生。一日，凯特在美术馆里偶遇了一名男子，两人经过短暂的相互试探之后很快就干柴烈火起来。激情退却后的凯特想起了丈夫和儿子，觉得心有愧疚，正当她乘坐电梯准备离开时，被一名戴着墨镜的奇怪女子残忍的用剃刀杀死。妓女布雷克（南茜·艾伦 Nancy Allen 饰）目睹了这恐怖的一幕，作为目击证人的她反而被警方怀疑是杀人凶手。为了洗清嫌疑，她决定深入案件查询真相，在皮特的帮助下，她很快将嫌疑锁定在了一个叫做“巴克”的人身上，而这个“巴克”竟然也是艾略特的病人。这一切是阴谋还是巧合？在布雷克接近真相的同时，巨大的危险也渐渐的离她越来越近。', '迈克尔·凯恩', '布莱恩·德·帕尔玛', 7.6, 9377, 'tt0080661', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1224079971.jpg', 0.5, 2.5, 27.8, 52.6, 16.5, '0.357357,-0.031335,-0.773040,0.348413,-0.230333,-0.264975,1.027314,-0.072700,-0.594257,-0.326708,0.411665,0.774880,-0.377168,0.193096,0.298714,0.108775,-0.403772,-0.686764,-0.055225,-0.296011,-0.291849,-0.572245,-0.427432,-0.441450,0.126670,-0.286396,0.331687,0.098568,-0.188553,0.397421,0.465033,0.380774,-0.093475,0.639732,-0.112299,0.075566,0.171827,-0.313574,-0.067589,0.206199,0.244539,-0.419234,-0.092048,0.420553,-0.241815,0.514849,0.663830,-0.155817,-0.268533,0.038216,0.212008,-0.293016,0.130431,0.414493,0.188435,-0.039339,0.086590,0.137691,-0.239595,-0.065685,0.051626,0.141652,-0.779753,0.162524,0.003858,0.171735,-0.582150,0.291342,-0.272333,-0.118026,0.284256,-0.327867,0.140052,0.237008,0.304952,0.315033,-0.181785,-0.000054,-0.343905,0.056017,0.601912,0.101088,-0.157838,0.287898,-0.162168,-0.314745,-0.105417,0.106360,-0.376066,-0.130768,0.558078,0.164147,-0.054499,0.150690,-0.375765,-0.234021,-0.451331,0.008415,-0.253036,-0.279212,-0.148401,-0.313542,-0.046157,-0.324810,-0.431375,-0.027420,-0.100235,-0.294821,0.353602,-0.695083,0.308803,0.746113,0.303320,-0.310388,0.492375,0.019694,0.116151,-0.219772,-0.184481,0.279948,0.142316,0.223796,0.184222,0.456113,0.098242,-0.082141,-0.343644,0.47