INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299981', '惊声尖笑', '喜剧', '6 个朋友：辛迪（安娜•法瑞丝 Anna•Faris  饰），鲍比（琼•阿伯拉罕Jon•Abrahams 饰），布佛（莎诺•伊丽莎白 Shannon Elizabeth 饰），格雷戈（拉科恩•玛诺 Lochlyn Munro 饰），雷（肖恩•韦恩斯 Shawn Wayans 饰） ，和布兰达（雷吉娜•赫尔 Regina Hall 饰）现在正深陷困境，被一位连环杀手跟踪。事情起源于他们在去年万圣节的晚上开车回家时发生了车祸，为了逃避责任，他们没有报警，而是选择逃离了现场。现今，一位自称知道他们的事的连环杀手，似乎已经从恐怖电影里走出来，进入了他们的生活。六位好友将不得不想方设法逃离这个杀手的魔掌和那些恼人的记者，如果他们想活下去的话……©豆瓣', '安娜·法瑞丝', '基伦·埃弗瑞·韦恩斯', 7, 66377, 'tt0175142', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1231134565.jpg', 1.8, 7.6, 42.1, 34.8, 13.8, '0.399462,-0.232051,-0.422212,0.323968,-0.080100,-0.172722,0.820397,0.035789,-0.406016,-0.718314,-0.014110,0.854951,-0.188508,0.142329,0.374284,0.170202,-0.624371,-0.652559,0.310839,-0.069222,-0.352133,-0.417356,-0.074866,-0.286299,0.123518,0.068185,0.382762,0.233241,-0.243307,0.626321,0.282979,0.410735,-0.152300,0.345268,-0.082167,0.010376,0.293478,-0.044680,-0.213529,0.308909,-0.025199,-0.294321,-0.201798,0.317461,0.287018,0.376835,0.327945,-0.396175,0.179712,0.106552,-0.156219,-0.419652,0.058324,0.424507,0.233790,-0.286245,0.228840,0.156040,-0.203419,0.036142,0.136018,-0.084947,-0.860534,0.208279,-0.098415,0.134603,-0.578685,0.042694,-0.276532,0.019286,0.075895,-0.214674,0.293831,0.364464,0.171601,0.033563,-0.155003,-0.172878,-0.755097,0.023351,0.724594,-0.147850,0.248407,0.220423,0.171180,-0.432103,-0.419174,0.149054,-0.353980,0.074166,0.608823,-0.139679,-0.210256,0.085047,-0.287565,-0.367445,-0.410481,-0.161113,-0.401366,-0.181207,-0.171311,-0.414141,0.212632,-0.082588,-0.273956,0.083039,-0.165257,0.019425,0.429435,-0.697002,0.228003,0.432760,0.338602,-0.678329,0.471651,0.157139,0.164871,-0.397856,-0.169350,0.236034,0.265788,0.280296,0.360948,0.398527,0.146144,-0.266687,-0.225641,0.176153', '2988294', '1294941', '1292584', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299986', '夏天的滋味', '剧情', '河内一个由兄妹四人组成的普通中产阶级家庭，大姐香与摄影师丈夫昆有一个儿子，但两人性生活不和谐，二姐卿（黎卿）同作家金结婚没多久，小妹琳（陈女燕溪）患有幽闭恐惧症，她与弟弟海保持着一种暧昧关系。在母亲的斋祀日，三姐妹追忆起被戏称为“母亲的谭”的神秘男人。为获得写作灵感，金前往西贡寻找有关谭的资料，此时他发现梅已怀有身孕，不明白梅为什么要对自己保密，香在昆出差期间有了外遇，琳则在与海保持暧昧关系的同时，与另一个男孩有交往。透过平静生活的表面，三姐妹都有不愿人知的秘密和心事。©豆瓣', '陈女燕溪', '陈英雄', 7.7, 7552, 'tt0224578', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2390018064.jpg', 0.3, 2.7, 28.3, 49.4, 19.2, '0.000504,-0.153119,-0.862402,0.759162,0.191993,-0.196922,0.752325,0.105466,-0.251264,-0.607409,-0.240026,0.696267,-0.222169,0.561215,0.173492,-0.056187,-0.109706,-0.640952,-0.138911,-0.233950,-0.537329,-0.661405,0.278949,-0.247961,-0.379827,-0.198779,0.478687,-0.044658,-0.184337,0.306315,0.393616,0.442157,-0.460830,0.503983,-0.147414,-0.052893,-0.109217,0.327650,-0.520113,0.095079,0.270112,0.121913,-0.158150,0.041747,0.353201,0.460802,0.713716,-0.328173,-0.194259,0.006918,0.185567,0.161314,0.095560,-0.268422,0.545991,-0.183635,0.096350,0.284057,-0.391983,-0.163244,-0.076473,-0.172498,-0.397640,-0.015798,0.461647,0.168692,-0.500731,0.466229,0.012148,0.008953,-0.027330,-0.044726,0.260383,0.698847,-0.153243,0.507942,-0.070188,0.344868,-0.547385,-0.017706,0.855439,0.479209,-0.038379,0.372398,-0.483230,-0.302238,-0.156535,0.036369,-0.489572,-0.056708,0.305329,-0.031977,0.058968,0.165570,-0.528652,-0.227502,0.062242,0.487033,0.336656,-0.467900,0.034408,-0.302292,0.019506,-0.577723,-0.307559,0.111634,0.124334,-0.483541,0.873371,-1.034619,0.218518,0.096296,0.372053,-0.908949,0.889265,0.282383,0.104738,-0.755988,-0.109098,0.201918,0.099778,-0.272013,0.318155,0.224601,-0.190444,0.187767,-0.431598,0.154227', '3445516', '1303036', '1292219', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1299990', '十日谈', '剧情', '获柏林电影节评审团大奖。影片取材于意大利文艺复兴时期薄伽丘的著名小说集《十日谈》，帕索里尼从中挑选了8个（亦有说10个）发生在那不勒斯等意大利南部地区的故事进行拍摄（原著中以佛罗伦萨地区故事为主），这些故事大多以揭露教会虚伪丑恶本质为宗旨，并鲜明地表现了作者对人性解放的肯定态度。原著《十日谈》是意大利文艺复兴时期最重要的文学作品之一，它以十四世纪黑死病横行的时期为背景，通过十位青年所讲述的一百个故事，大胆鞭挞了当时天主教会的种种丑行，表现出平民阶层追求自由、摆脱宗教束缚的渴望。这部现实主义风格明显的作品堪称欧洲古典文学的杰作，被后人誉为和但丁《神曲》齐名的" 人曲"。意大利新现实主义影片后期崛起的导演帕索里尼，延续了自己六十年代以古代神话题材警醒当今世人的创作路线，以相对通俗化的手法连续改编拍摄了《十日谈》、《坎特伯雷故事》和《一千零一夜》三部古典名著影片，合称"生命三部曲"。因为这三部影片中裸露镜头较多，又采用了较为通俗的娱乐片路线，有的电影学者也称之为帕索里尼的"色情三部曲"。对此帕索里尼本人阐述了自己的创作观点："我向观众表现的是整个世界，封建的世界，在这个世界里，情欲极其深刻而狂热地起着支配一切的作用。……我要推出这个世界并且说：你们可以比较一下，我要向你们表明，我要向你们诉说，我要向你们提醒。"', '弗兰科·奇蒂', '皮埃尔·保罗·帕索里尼', 7.5, 9225, 'tt0065622', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2408023926.jpg', 0.8, 3.5, 32.5, 45.1, 18.2, '0.161654,-0.027148,-0.409746,1.017556,0.246453,0.036305,0.454400,-0.111170,-0.313574,-0.197022,0.031797,0.762353,-0.153995,-0.045522,0.404604,-0.149536,-0.415869,-0.449378,-0.115186,-0.094079,-0.048610,-0.370069,-0.248388,-0.173210,-0.294377,-0.416090,0.809183,0.113776,-0.760208,-0.058179,0.224685,0.331465,0.050735,-0.156311,0.012036,-0.131126,-0.037607,-0.126064,-0.523123,0.284625,-0.082067,-0.087989,-0.238297,0.252108,-0.451924,0.170599,0.542504,-0.440537,-0.058258,0.031808,0.851746,-0.166743,-0.149634,-0.089647,0.045958,0.055087,0.387694,0.491168,0.277537,0.157122,-0.261952,-0.286805,-1.052111,-0.213959,0.265251,0.127455,-0.391790,0.414424,-0.060276,-0.067630,-0.010085,-0.300586,0.153832,0.084834,0.552844,0.461738,0.139574,-0.149112,-0.238419,0.413084,0.246393,0.055928,-0.557427,0.393105,-0.426013,-0.348812,-0.157306,-0.356187,-0.274433,0.154717,0.107567,-0.235126,-0.029811,0.464347,-0.647859,0.032978,0.251917,-0.535851,0.165353,-0.317946,0.185934,-0.687139,-0.335339,-0.406338,0.009259,-0.577274,0.245267,-0.243980,1.157941,-0.417187,0.052968,0.440945,0.156020,-0.622788,0.635533,0.121051,-0.091767,-0.273623,-0.086100,0.444351,-0.059582,-0.011674,-0.231439,0.485537,0.222332,-0.485505,-0.419800,0.792511', '27602116', '22265121', '1303542', '4267948');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300019', '埋伏', '剧情', '在一个漆黑的夜晚，某海滨城市船厂仓库管理员李玉洪一家四口被人残忍杀害。这起恶性案件引起当地公安机关的高度重视，重案组杨高（张嘉译 饰）专门负责此案。经过缜密分析，警方已经锁定几个重要嫌疑人，杨高委托供职于船厂保卫科的叶民主（冯巩 饰）和老田（滕汝骏 饰）蹲守第七个埋伏点——市郊废弃火车站，负责监视犯罪团伙中的头目“智者”（牛振华 饰）。由于工作性质的关系，民主和老田对家里人也严格保密，夜以继日在火车站内的水塔里监视。在此期间，民主的女友百林（江珊 饰）心生误会，老田的身体也垮了下去。肝癌晚期的老田最终无奈退出，叶民主则在水塔内孤军奋战，似在进行一场遥遥无期的战争……©豆瓣', '冯巩', '黄建新', 7.9, 10590, 'tt0151464', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870046328.jpg', 0.3, 1.4, 23, 54.5, 20.8, '0.115840,-0.072365,-0.621683,0.395729,0.021407,0.243736,0.714910,0.139912,-0.416551,-0.246840,0.287307,0.398748,0.086405,0.278085,0.267959,-0.216069,-0.444361,-0.533075,-0.272955,-0.103974,-0.385136,-0.677354,-0.202980,-0.395106,0.023136,0.224904,0.231047,0.420169,-0.099242,0.178568,0.214434,0.341373,-0.415411,0.167217,0.159085,-0.243750,0.313040,-0.203232,-0.253705,0.063861,-0.131468,-0.116100,0.030594,-0.128613,0.416467,0.545257,0.550522,-0.133362,-0.418525,-0.132222,0.334645,-0.323548,-0.051163,0.121438,0.688813,0.195711,0.189123,0.412195,-0.562584,0.210902,0.017696,-0.316506,-0.623146,-0.055449,0.231553,0.037709,-0.351613,0.599605,0.051248,0.040117,-0.147625,-0.218974,0.379327,0.327640,0.223224,0.396805,-0.076629,0.282609,-0.128127,0.114273,0.338961,-0.091477,-0.130733,-0.211418,-0.139549,-0.343570,0.021719,0.074391,-0.088989,-0.298171,0.300396,-0.291051,-0.040618,-0.063123,-0.381902,-0.109375,-0.034208,-0.252926,-0.220712,-0.143381,-0.029597,-0.739848,0.119483,-0.215593,-0.055773,0.423662,-0.080410,-0.059733,0.246617,-0.581166,-0.094894,0.375166,0.049236,-0.756708,0.321281,0.119364,0.403154,-0.333215,-0.260462,0.129203,0.214049,0.624747,0.115645,0.324129,-0.210898,-0.324910,-0.250898,-0.071894', '27110363', '1306809', '27126336', '22266320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300029', '王尔德', '剧情', '根据十九世纪唯美主义先锋作家王尔德的真实经历改编。王尔德（Stephen Fry 史蒂芬•弗莱饰）一生在诗歌、戏剧、童话、小说创作、文学批评上广泛涉猎，他谈吐幽默，作品充满机锋，英国首相丘吉尔曾说来生最愿倾心长谈的人便是王尔德。在当时的伦敦，王尔德几乎每部戏剧都在舞台上取得轰动效果，风头可谓一时无两。可是，王尔德的文学生涯却在后来完全被毁掉，这一切都源于他和道格拉斯•波西伯爵（Jude Law 裘德洛饰）的一场相遇，王尔德不仅背负“鸡奸罪”入狱，蒙受名誉上的污点，家中所有也全部被拍卖，妻子只得带着两个儿子远走他乡，并给他们改姓。©豆瓣', '斯蒂芬·弗雷', '布莱恩·吉尔伯特', 7.8, 35088, 'tt0120514', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1527574884.jpg', 0.3, 1.6, 26.8, 51.1, 20.2, '0.141758,-0.107465,-0.535341,0.640291,0.209914,-0.403530,0.513393,0.020771,-0.493968,-0.294612,0.290547,0.826069,-0.391493,0.008475,0.215117,-0.141465,-0.465380,-0.728259,-0.141003,-0.065741,0.174550,-0.518374,-0.182350,0.092212,-0.066447,-0.365514,0.453943,0.018155,-0.474816,0.386627,0.434174,0.172937,-0.015375,0.083636,0.012593,0.303606,0.012486,0.074650,-0.465485,-0.005091,-0.147977,-0.317506,-0.193514,0.071531,-0.211770,-0.059992,0.542190,-0.381748,-0.094195,0.134364,0.836661,-0.302151,0.093597,0.230658,0.002312,0.199766,0.376558,0.509944,-0.041645,0.081265,0.073479,-0.149130,-0.786188,-0.027651,0.194558,0.058373,-0.405687,0.765870,-0.033233,0.064622,-0.302906,-0.010572,0.040101,-0.234773,0.294124,0.401509,0.041191,0.143635,-0.307896,0.485710,0.483693,-0.178935,-0.306824,0.113626,-0.244466,-0.252004,-0.128539,-0.500873,-0.511112,0.429549,0.234164,-0.209671,0.032676,0.385082,-0.368821,0.051002,-0.226889,-0.305174,0.088251,-0.254673,0.072343,-0.685449,-0.437530,-0.325157,-0.358747,-0.371690,0.399027,-0.363574,0.732175,-0.311333,0.392599,0.305048,-0.123963,-0.343693,0.545010,0.261082,0.074165,0.106066,-0.360901,0.530264,0.149048,0.129449,-0.061724,0.250704,0.191150,-0.059853,-0.205865,0.784063', '27602116', '22265121', '26647163', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300034', '德尔苏·乌扎拉', '剧情', '这是一部极为出色的关于人与自然的电影。1902年和1907年，沙俄军官阿尔谢尼耶夫两次率领勘探队到乌苏里地区探险，都巧遇赫哲族老猎手德尔苏·乌扎拉。德尔苏.乌扎拉为勘探队充当向导，并挽救了阿尔谢尼耶夫的生命，与之建立了深厚的情谊。德苏对大自然相当了解与尊重，藉由他的示范 与见解，让人们了解大自然的伟大与残酷，人是可以与大自然和平相处，但当大自然被破坏时，人们将是第一个遭殃。德苏是一个神枪手，但后来在一次打猎时，德苏发现自己的眼睛因为身体衰老而退化，看不清猎物了，十分沮丧。他随阿尔谢尼耶夫到大城市伯力居住。但是，城市文明德苏却无法习惯，城市和他过去赖以生存的地方，那片纯朴的自然大地是完全不同的。猎人离开枪，离开了他所熟悉的环境，仿佛鱼儿离开了水。“城里没法狩猎，不狩猎就没有貂”“我突然想念空气。”他象是被囚禁了一般，闷闷不乐。德苏执意回到山里，回到那片密林。但是，猎人没有好的视力，便是最大的悲剧。猎人不能猎杀，自己便被会猎杀。勇敢的德苏虽然带着阿尔谢尼耶夫送给他的新猎枪，但是他却死了……', '马克西姆·蒙祖克', '黑泽明', 8.4, 7787, 'tt0071411', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206328338.jpg', 0.6, 1.5, 13.7, 46.5, 37.7, '0.412234,-0.111410,-0.808758,0.645540,-0.114425,-0.228563,0.868856,-0.053263,-0.609088,-0.167144,-0.108960,0.676239,0.099660,0.053799,0.141499,0.215777,-0.304013,-0.558303,-0.095484,-0.122140,-0.462522,-0.495688,-0.407764,-0.196217,-0.173119,-0.298345,0.547687,0.329923,-0.372736,0.424070,-0.147579,0.232765,0.147130,0.588300,-0.367712,-0.157298,0.014373,-0.142715,-0.156856,0.111286,0.100427,-0.040783,-0.430242,0.186212,0.061206,0.354108,0.586206,-0.454147,-0.265267,-0.151692,0.156125,-0.418674,0.176919,0.192071,0.200410,-0.131961,0.151520,-0.022347,0.063047,-0.033474,-0.055504,-0.233253,-0.587548,0.282786,0.032641,-0.021933,-0.752472,0.495868,0.053003,-0.176150,0.027104,-0.382960,0.264571,0.286918,0.305992,0.408076,-0.127296,-0.090873,-0.614817,0.000546,0.888961,0.035330,-0.497760,0.292009,-0.344129,-0.754926,-0.035967,-0.396515,-0.372856,0.095395,0.320698,0.160411,-0.268875,0.413854,-0.733620,0.162390,-0.393789,-0.435740,-0.064737,-0.386395,-0.053176,-0.388741,-0.314401,-0.612606,-0.259371,0.246361,0.143753,-0.169557,0.712861,-0.972474,0.278411,0.518428,0.239625,-0.487038,0.612673,-0.046874,0.031929,-0.202747,0.247766,0.326043,0.236015,0.379806,0.387751,0.370497,0.094848,0.008703,-0.364817,0.545373', '25721544', '1308755', '3055049', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300038', '中国最后一个太监', '剧情', '宣统三年，偏僻小山村的穷孩子来喜见到本村大太监小德张“衣锦还乡”，心生羡慕。尽管母亲（归亚蕾 饰）不忍，却还是在父亲（林正英 饰）的劝说下对儿子进行净身送入宫中，以求全家得以温饱。成年后的来喜（莫少聪 饰）并没有如预期一样丰衣足食，不久民国推翻了满清，宫内的太监都不能留下。来喜来到戏班拜班主（洪金宝 饰）为师学艺，并且重逢了幼时的好友招弟（温碧霞 饰），招弟误认他是革命党人想以身相许，在知道来喜太监的身份后招弟落寞离去。来喜为逃避军阀追踪重新混入紫禁城，得到丁公公（午马 饰）照顾，经过一系列政治斗争后来喜与丁公公又被驱逐到了宫外，此时怀着身孕的招弟又出现在来喜面前。好多年过去了，当来喜以为能够拥有幸福的时候，招弟的革命党丈夫（刘德华 饰）却又出现了，而此时丁公公带着对皇帝最后的愚忠，妄图让来喜和自己前往日本领事馆照顾溥仪，来喜该何去何从？本片改编自太监孙耀庭的一部半自传体小说，是张之亮从制片转为导演的处女作，也是莫少聪提名金马奖最佳男主角奖的代表作。', '莫少聪', '张之亮', 7.4, 15837, 'tt0096505', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204679692.jpg', 0.6, 3.4, 36.5, 44.1, 15.3, '-0.276256,0.037211,-0.651215,0.543086,-0.168390,-0.567103,0.647346,0.183750,-0.627041,-0.108101,0.216989,0.770796,-0.232973,0.050285,0.034101,0.001438,-0.250725,-0.420820,-0.166925,-0.293031,-0.124051,-0.126218,0.129583,-0.026568,-0.271203,-0.130092,0.317032,0.088317,0.116687,0.449461,0.790117,0.122293,-0.066560,0.412137,0.060291,0.505066,-0.146038,-0.111320,-0.305128,0.098451,0.135842,-0.397478,-0.436782,0.050528,0.149415,0.155016,0.591075,-0.124385,-0.051124,-0.146366,0.500985,-0.053282,-0.055500,0.255408,0.302336,0.138438,0.121503,-0.070137,-0.159836,0.193685,-0.234058,-0.104808,-0.548559,0.149277,0.349345,0.076520,-0.709831,0.273346,-0.146598,-0.209564,0.033959,-0.458448,0.242434,0.394869,0.037692,0.572682,-0.114784,0.242770,-0.473959,0.480258,0.542111,-0.038901,0.096972,0.217742,-0.141713,-0.367837,0.343721,-0.130666,-0.428530,-0.119458,0.260522,-0.000757,-0.223689,-0.020647,-0.149841,-0.095004,-0.351582,0.221652,0.240671,-0.296574,-0.131380,-0.239976,-0.026263,-0.410389,-0.152905,0.132867,0.256826,-0.266272,0.691701,-0.691015,0.430047,0.248571,0.217116,-0.618527,0.529606,0.102188,0.144386,-0.147210,-0.072657,0.106722,-0.074909,0.403027,0.119150,0.002289,-0.23435