INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300043', '白色夹竹桃', '剧情', '在阿斯特丽德（爱莉森•洛曼 饰）15岁那年，母亲（米歇尔•菲佛 饰）杀死了抛弃她的情人。阿斯特丽德亲眼看着母亲被捕。自从母亲被捕，她便过着孤苦伶仃的生活，与此同时她被收养了。阿斯特丽德从女主人的男友身上感觉到了父爱，却被女主人认为她勾引自己的男友，向她开枪。康复后的阿斯特丽德居住进抚养院，她常被欺负，但自从被枪伤之后她便知道她需要依靠自己力量来保护自己。在抚养院中，男孩保尔主动接近阿斯特丽德，他们都喜欢画画。他们的来往却得不到母亲的赞同，母亲告诉她无论如何都要靠自己走下去，不能靠男人。在后来阿斯特丽德被一名女明星克莱尔（芮妮•齐薇格 饰）收养。克莱尔很珍爱经历坎坷的阿斯特丽德，可是阿斯特丽德的母亲却嫉妒她们，那次见面之后，克莱尔竟然自杀了。克莱尔的死对阿斯特丽德的打击很大，她要求被一名俄罗斯女商人收养，她变得自甘堕落。这时母亲要求阿斯特丽德为她出庭作证，并从母亲嘴里知道了有关自己的身世，可是她要求母亲放她走。母亲果真放她走了，母亲没有要她出庭，阿斯特丽德看着母亲走上囚车……', '米歇尔·菲佛', 'Peter Kosminsky', 8, 6024, 'tt0283139', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p811156990.jpg', 0.2, 1.3, 21.9, 51.1, 25.6, '0.278280,0.072343,-0.684825,0.603708,-0.168438,-0.956733,1.042024,0.248858,-0.332009,-0.453857,0.165739,0.516327,0.096315,0.402830,0.066667,0.083179,-0.579127,-0.321488,0.196558,-0.042611,-0.306146,-0.250512,0.107874,-0.250715,-0.241887,-0.165410,0.372800,-0.374404,-0.264969,0.085256,0.506825,0.323694,0.229889,0.633649,0.041263,0.380501,0.133451,-0.036585,0.030084,0.195350,0.242367,-0.184304,-0.140935,0.117711,0.168002,0.189561,0.509176,-0.337204,0.231793,-0.233084,0.234196,-0.166977,0.331714,0.396287,0.040298,-0.301560,0.025912,0.061610,-0.232358,-0.175872,0.056649,-0.099598,-0.351170,-0.128450,0.227489,0.180198,-0.904975,0.258927,-0.347169,0.113832,0.121656,-0.442708,-0.145568,0.429903,-0.006870,0.501887,-0.298871,0.022950,-0.605043,0.016033,0.780397,-0.226522,0.273386,0.206653,-0.432050,-0.807224,0.078765,-0.017559,-0.697930,0.098537,0.424227,-0.281134,-0.040826,0.551553,-0.037830,-0.471077,-0.423953,0.122278,0.039097,-0.384323,0.238884,-0.067248,-0.085296,-0.387035,-0.564610,0.040532,-0.301837,-0.252241,0.377055,-0.526618,0.456962,0.575017,0.550709,-0.220894,0.581302,0.166295,0.075404,-0.453364,0.036677,0.772612,0.257281,0.162250,0.489238,0.140045,0.279466,0.129712,-0.159685,0.481190', '2075721', '26245360', '1844413', '26580232');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300044', '谋杀绿脚趾', '喜剧', '勒保斯基（杰夫·布里吉斯 Jeff Bridges 饰）绰号“督爷”，是个无所事事的中年混混，终日最大的消遣就是和两个同样无能的朋友沃特（约翰·古德曼 John Goodman 饰）和多尼（斯蒂夫·巴斯米 Steve Buscemi 饰）打保龄球。一日，一群打手把他错认成城里和他同名同姓的那个百万富翁加以威胁，临走还尿在他的地毯上。平白无故吃亏的督爷只好跑去找那个富翁（戴维·哈德莱斯顿 David Huddleston 饰）赔偿，未果后自作主张偷了富翁一块地毯。几日后富翁又把督爷找去帮忙，因其年轻妻子邦妮（塔拉·雷德 Tara Reid 饰）遭到绑架，督爷被要求帮忙送赎金给绑匪，就此和两个朋友一起卷入一场哭笑不得的犯罪事件……©豆瓣', '杰夫·布里吉斯', '乔尔·科恩', 7.7, 54583, 'tt0118715', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2225804430.jpg', 0.8, 3.8, 28.1, 45.2, 22.1, '0.385510,-0.251447,-0.217199,0.325384,-0.415366,-0.488586,0.653890,0.242910,-0.264057,-0.335674,-0.059351,0.826683,-0.166762,0.067468,0.361813,0.249870,-0.384056,-0.627833,0.091427,-0.016314,-0.176887,-0.487787,-0.156322,-0.163982,-0.098390,-0.039069,-0.042789,-0.374650,-0.109248,0.603262,0.669625,0.404699,-0.021385,0.126097,-0.251312,0.144982,0.146000,-0.275437,-0.007929,0.224622,-0.134135,-0.055878,0.200836,-0.253240,0.104019,0.306457,0.370517,-0.028849,0.098868,-0.251916,0.179150,-0.344174,0.081210,0.265552,0.227178,-0.266996,0.206363,0.035564,-0.355922,-0.013968,0.631956,0.012751,-0.588326,0.122403,-0.027392,0.118027,-0.852802,0.408126,-0.241320,-0.215138,0.074315,-0.114141,0.169495,0.327642,-0.015661,0.351074,-0.061620,-0.064598,-0.591056,0.116239,0.414845,0.076102,0.308203,-0.128607,0.265350,-0.101338,0.445875,-0.182481,-0.434439,-0.034941,0.570933,-0.570184,-0.150284,-0.097575,-0.746097,-0.183591,-0.482734,-0.196128,-0.047282,-0.362458,0.051579,-0.522587,0.076951,-0.124344,-0.306509,-0.013703,0.273536,0.098272,0.204767,-0.092062,0.274238,0.586752,0.338301,-0.251084,0.495573,0.120859,0.278476,-0.070752,-0.048837,-0.257438,0.681652,0.359376,0.281784,0.394195,0.271978,-0.237146,-0.085756,0.089807', '1295324', '6753166', '1298667', '1418194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300055', '全金属外壳', '剧情', '越战期间，美军大量征兵。大批年轻人应征入伍，在新兵营接受“残忍”的训练。“傻瓜”比尔运动神经不发达，常常犯错而连累所有人一起受罚。“小丑”（马修•莫迪恩 Matthew Modine 饰）奉命帮助比尔，但比尔还是老犯错误，连累其他人。大家忍无可忍下打了他一顿，比尔从此变得精神恍惚，在新兵营毕业前夕枪杀教官后吞枪自杀。“小丑”随后分到了军队新闻组。他在采访中看到了当时的同伴们都已经变得麻木、残忍。一次，“小丑”随“牛仔”执行任务时，遭到越共狙击手伏击，“牛仔”亦不幸中弹身亡。众人经过一番搜索，击伤了狙击手。“小丑”发现狙击手竟是一个年轻少女。有人提议留下她挣扎而死，“小丑”在少女“杀了我”的哀求声中，扣下了扳机。©豆瓣', '马修·莫迪恩', '斯坦利·库布里克', 8.6, 123699, 'tt0093058', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553116438.jpg', 0.2, 0.8, 10.8, 45.6, 42.6, '0.042539,-0.362083,-0.392453,0.025886,-0.372803,-0.341393,0.448376,-0.097706,-0.188238,0.077258,0.710598,0.700711,-0.227652,0.074702,0.213968,-0.403172,-0.372202,-0.565544,-0.027573,0.080290,-0.233926,-0.332065,0.216809,-0.505992,0.226855,-0.428330,0.568064,0.110981,-0.171613,0.499154,0.096316,0.066251,0.031021,0.401661,0.096873,0.007066,0.330453,-0.524462,0.065816,0.138935,-0.232961,-0.223966,-0.279218,-0.076983,-0.154309,0.405037,0.493471,-0.185720,-0.145438,-0.333796,0.230765,-0.479057,0.019507,0.177366,0.314162,-0.091857,0.144280,-0.219671,0.128806,0.144519,-0.122137,0.109600,-0.108556,0.095829,0.030652,0.157380,-0.576423,0.458938,-0.196643,0.666453,-0.018603,-0.125339,0.006635,0.227093,0.179348,0.150490,-0.138749,0.005999,-0.136598,0.244035,0.692726,-0.177067,-0.424059,-0.198667,0.030457,-0.160369,0.298583,-0.142165,-0.317635,0.076888,0.441966,-0.210374,-0.358615,0.284968,-0.110972,-0.179651,-0.255283,-0.121677,-0.442150,-0.123584,-0.290607,-0.730541,0.158572,0.141176,-0.320768,0.117578,-0.177314,0.030624,0.388210,-0.643674,0.242239,0.433329,0.312070,-0.224584,0.183815,0.072304,-0.119129,0.072765,0.004092,0.198836,0.494151,0.142763,0.363154,0.138893,-0.287474,-0.262088,-0.153086,0.082681', '1899892', '11541282', '26365262', '3804656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300056', '四百击', '剧情', '作文课上，安托万（Jean-Pierre Léaud 饰）在同学传来的女人图像上涂鸦，被罚站墙角。下课后，独守教室的安托万在墙上作诗宣泄自己的不满，引得老师（Guy Decomble 饰）更加愤怒。晚上，母亲（Claire Maurier 饰）因安托万没买面粉大发雷霆， 而继父（Albert Rémy 饰）则在安托万的请求下拿出一笔钱让他吃午饭。 第二天，安托万在同桌勒内（Patrick Auffay 饰）的怂恿下逃了学，跑去看电影打游戏，还在街上看到母亲跟一个安托万不认识的男人亲吻。 第三天，安托万回到学校，慌乱中谎称母亲去世，获得了老师的原谅和疼惜。不想继父获知了他逃学的事，与母亲一起赶到学校，戳穿了他的谎言，还当着全班同学打了他两耳光。 安托万决定留下一封信离家出走。可是小小年纪的他能去哪呢？巴黎那么大，法国那么大，哪里才是他的安身之处呢？©豆瓣', '让-皮埃尔·利奥德', '弗朗索瓦·特吕弗', 8.8, 102794, 'tt0053198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191743027.jpg', 0.2, 0.6, 8, 39.5, 51.7, '0.388104,-0.013060,-0.585179,0.464759,-0.204075,-0.419947,0.527943,0.314724,-0.193449,-0.087017,-0.041789,0.684386,-0.271136,0.594177,0.085000,0.104423,-0.476102,-0.627167,0.202308,-0.184412,-0.324460,-0.570039,0.111353,-0.208549,0.098737,-0.123693,-0.038451,-0.184577,-0.063629,0.406018,0.364550,0.034798,0.033048,0.430993,-0.314025,0.214683,-0.139100,0.306322,0.110917,0.146349,0.365542,-0.478295,-0.214752,-0.030830,0.148408,0.308981,0.436472,0.188163,0.089513,-0.198779,0.337362,-0.044817,-0.044603,0.234080,0.161403,-0.097004,0.322834,-0.014116,-0.262998,0.176703,0.128997,0.033708,-0.164036,0.076078,-0.046022,0.070355,-0.749958,0.570370,-0.241539,0.029761,0.287739,-0.511918,0.148471,0.222302,-0.195609,0.513446,-0.188881,-0.072200,-0.604329,0.173004,0.419736,-0.228503,0.532523,0.177665,0.107684,-0.057092,0.227146,-0.137627,-0.448335,0.070822,0.106970,-0.199945,-0.196972,-0.191385,-0.337910,-0.196001,-0.192951,-0.171814,0.010027,-0.586639,-0.258147,-0.481660,0.122287,0.000777,-0.415056,0.192436,0.117046,-0.192206,0.538478,-0.527997,0.195738,0.390548,0.532354,-0.304654,0.765676,0.176444,-0.244983,0.004715,0.111492,0.036987,0.217040,0.291708,0.286347,0.342523,-0.072217,-0.082700,-0.426480,0.500902', '5327188', '1302384', '1783772', '1292207');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300060', '战神传说', '动作', '故事发生在江湖时代。孤儿阿飞（刘德华 饰）传说自小由鱼群抚养长大，因此身手不凡。不过阿飞却对功名不感兴趣，在渔村过着逍遥自在的生活。一次偶然机会，阿飞结识了前朝遗民燕十三（钟镇涛 饰），两日成立莫逆之交。为了帮助燕十三与兰陵国君一起从十四太子手中夺回王位，阿飞前往兰陵国救出了兰陵国君及其女月牙儿（梅艳芳 饰）。阿飞与月牙儿在逃亡过程中互生情愫，但月牙儿早已与燕十三订下婚约，阿飞只能黯然离开了他们。趁阿飞离开，十四太子调遣部队包围了燕十三他们，情况危在旦夕。©豆瓣', '刘德华', '洪金宝', 6.3, 5884, 'tt0108650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350666192.jpg', 2.4, 14.9, 57.2, 18.6, 6.9, '-0.229646,0.119581,-0.575068,0.573871,0.329401,-0.250395,0.385338,0.029465,-0.709760,-0.621768,0.000651,0.398320,-0.006434,0.160689,0.334641,-0.040545,-0.016611,-0.580275,0.033914,-0.278905,-0.122234,-0.493443,0.042576,-0.172410,-0.067439,-0.180135,0.803705,0.169616,-0.118621,0.741650,0.033513,0.062166,-0.697954,0.205020,-0.447240,0.073207,-0.157121,0.237506,-0.708397,0.180459,-0.347182,-0.367160,-0.528464,0.067286,0.441171,0.041679,0.714100,-0.530294,0.258806,-0.251130,-0.466155,0.049502,-0.179166,-0.031263,0.292743,-0.165020,0.225580,0.580737,0.309746,-0.152398,-0.305739,-0.216908,0.020018,0.324323,-0.114175,0.084605,-0.680263,0.373608,-0.301597,0.041545,-0.139831,-0.331545,0.345794,0.569684,0.169358,-0.065199,-0.168725,0.276443,-0.571560,0.086064,0.675419,0.077634,-0.038838,0.241158,0.381247,-0.194076,-0.118533,-0.043500,-0.067494,0.066485,0.530457,0.033089,-0.331909,0.641265,-0.364993,-0.123095,-0.324651,0.207390,0.322000,-0.043255,0.362926,-0.370852,-0.141187,-0.333117,-0.449179,-0.099559,0.224710,-0.181918,0.613161,-0.782084,0.274029,-0.139732,0.220964,-1.086325,0.341700,0.374682,0.349639,-0.301302,-0.005597,0.145717,0.012319,-0.082642,0.185635,-0.059228,-0.516149,-0.122229,-0.414653,-0.038270', '1293265', '1484760', '1474336', '3598221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300064', '家有喜事', '剧情', '常家大哥常满（黄百鸣 饰）事业有成，可是却嫌弃家中老婆程大嫂（吴君如 饰）是个黄脸婆，不懂打扮。程大嫂每天在家服侍老人痴呆的公婆，深得常骚（张国荣 饰）与常欢（周星驰 饰）的喜爱。娘娘腔常骚与“男人婆”表姑妈梁无双（毛舜筠 饰）是一对死对头，可在两人同时受到感情伤害的时候，萌生爱意。常欢是出名的花花公子，却意外撞坏了脑子，女朋友何里玉（张曼玉 饰）还是愿意留在他的身边。当个人都心有所属时，却要帮大哥想办法挽回与程大嫂的感情。©豆瓣', '张国荣', '高志森', 8.5, 250631, 'tt0104553', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p940263436.jpg', 0.2, 0.9, 14.5, 44.5, 39.8, '-0.267256,-0.182489,-0.446085,0.385329,-0.183184,-0.424537,0.664578,0.183650,-0.690763,-0.425071,-0.266021,0.268550,0.022200,0.450222,0.029680,0.080326,0.034339,-0.388164,0.083178,0.157396,-0.054794,-0.320623,-0.023703,-0.128555,-0.233060,0.023833,0.158144,0.020796,-0.247935,0.307331,0.690073,0.051530,-0.142098,0.342937,-0.139370,0.020033,-0.157117,0.214901,-0.261215,-0.139339,0.186946,0.094451,-0.119137,0.087834,0.316746,0.304503,0.284695,0.201570,-0.277271,-0.058026,0.191087,0.159123,0.196903,0.149737,0.061782,-0.329639,0.494062,-0.176675,0.124953,0.061014,0.319215,-0.097743,-0.158878,0.114907,0.466248,-0.109801,-0.826885,0.414534,-0.200304,-0.271015,-0.163199,-0.185226,0.339508,-0.028588,0.156265,0.406260,-0.115013,0.201738,-0.468227,0.301206,0.374894,0.355549,0.116295,0.373516,-0.185216,-0.289619,-0.109249,-0.217898,-0.644794,0.229507,-0.034026,-0.036757,0.020192,-0.039202,-0.112357,-0.181416,0.138686,0.548076,-0.099742,-0.584456,0.315086,0.018655,-0.041039,-0.744349,-0.198902,0.224362,0.165352,-0.187240,0.539975,-0.641696,0.188379,-0.093608,0.217313,-0.893543,0.734120,0.495381,-0.240989,-0.509892,0.043302,-0.136389,-0.031594,-0.610946,0.048664,0.118008,0.120200,-0.254518,-0.137146,0.141361', '1421278', '35376457', '1301221', '1872133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300069', '偷天陷阱', '动作', '一个著名画家在纽约举办了一次画展，不料展出的名画却被盗走，众人怀疑的矛头指向了大盗麦克（肖恩•康纳利 Sean Connery 饰）。因为麦克是一个名贵艺术品的惯偷分子，而这次名画失窃的所有证据，也表明麦克嫌疑最大。为了使其入罪，承包此画的保险公司决定使用美人计——职员维吉尼亚（凯瑟琳•泽塔-琼斯 Catherine Zeta-Jones 饰）假扮麦克的同道中人，诱使麦克出手犯罪，而保险公司则随后追踪取证。然而，每一次麦克都没有落入圈套，还与维吉尼亚渐生情愫。得知千年虫入侵电脑，维吉尼亚唆使麦克利用这个机会入侵马来西亚的国际银行，这里管理森严，号称全球之最。一场斗智斗勇的计划开始了，而维吉尼亚也陷入了效忠公司和帮助爱人的选择当中。©豆瓣', '肖恩·康纳利', '乔恩·阿米尔', 7.8, 101215, 'tt0137494', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1670850240.jpg', 0.1, 1.4, 25.5, 53.3, 19.6, '0.111224,-0.110251,-0.538540,0.733261,-0.117519,-0.086766,0.718310,0.173877,-0.392223,-0.333475,0.207555,0.717108,-0.046499,-0.099869,0.361773,0.011084,-0.375713,-0.681381,0.050957,-0.271127,0.018667,-0.570340,-0.321304,-0.363295,0.056882,0.030509,0.413401,0.213144,-0.323571,0.513026,0.407777,0.341325,-0.110917,0.265280,0.265585,-0.448691,0.386696,-0.196969,-0.502773,0.451183,-0.072300,-0.276646,0.033497,0.369639,-0.039415,0.462928,0.364697,-0.225666,0.107575,-0.161596,0.371390,-0.422623,-0.002188,-0.016572,0.261473,-0.002104,0.112866,0.209875,-0.362602,0.015572,0.407580,-0.052809,-0.957917,-0.044561,-0.006281,0.051326,-0.369966,0.148563,-0.244187,0.267167,-0.402604,-0.134820,0.277019,0.240444,0.518447,-0.068538,0.002623,-0.122065,-0.569391,-0.133584,0.378438,-0.258465,0.045440,0.049778,0.201861,-0.373432,0.232819,-0.126881,-0.114983,0.054177,0.339211,-0.116956,0.100855,0.209649,-0.648220,-0.108335,-0.397036,-0.223707,0.104546,-0.354393,0.106013,-0.932216,-0.101681,0.127215,-0.230648,-0.067624,0.188292,-0.133747,0.287945,-0.663358,0.177948,0.522113,0.199088,-0.601943,0.497496,0.131360,0.090187,-0.396986,-0.278699,0.184574,0.340920,0.456179,-0.070328,-0.008621,0.306666,-0.527220,-0.120079,0.206618', '1307442', '30143331', '4014397', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300070', '赌侠1999', '喜剧', '阿king（刘德华 饰）当年因出千被捕，事实上他是被人陷害的。出狱时他为他接风的是崇拜他已久的化骨龙（张家辉 饰），化骨龙是个终日无所事事的人，希望能跟着king有所作为。出狱后的king到处寻找已怀孕的妻子（张慧仪 饰），与当日的得力助手（张锦程 饰），后来King与化骨龙妹妹晴（朱茵 饰）产生了好感。King得到Rocky（吴志雄 饰）的帮助上了赌船，碰见了多年前便想交手的马交文（高捷 饰），king想与之一决高低，却遭到马交文的手下省镜（李子雄 饰）陷害，揭开了king的底细更想进一步迫害king，king又能否躲过劫数呢？©豆瓣', '刘德华', '王晶', 6.8, 37141, 'tt0184354', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2358906814.jpg', 0.9, 6.6, 53.6, 29.2, 9.7, '0.100379,0.157035,-0.692371,0.700277,-0.025970,-0.327873,0.545267,-0.010233,-0.562772,-0.256031,0.049956,0.595340,-0.266978,0.222821,0.089117,0.113141,-0.174744,-0.739601,0.029128,-0.146092,-0.334799,-0.292600,-0.489639,-0.001562,-0.100352,-0.290846,0.346638,0.199928,-0.114327,0.422906,0.602106,0.526237,-0.066530,0.390371,-0.058389,0.132413,-0.211521,0.207969,-0.296563,0.089284,0.010280,-0.662501,-0.044014,0.211677,-0.022615,0.448333,0.629964,-0.185202,-0.162206,-0.289188,0.260816,-0.253267,0.115008,0.104833,0.222099,0.074679,0.383602,0.329025,-0.292487,-0.080803,0.015712,-0.024658,-0.878126,-0.064144,0.447012,-0.152766,-0.634486,0.290343,-0.248537,-0.012018,-0.135819,-0.225196,0.250296,0.509185,0.047015,0.278287,-0.129224,-0.175892,-0.515800,0.330897,0.759234,0.002139,0.209795,0.190867,0.071626,-0.219255,0.109058,-0.329903,-0.145683,0.074327,0.334374,0.089886,-0.111533,-0.020081,-0.302133,-0.136687,-0.386886,0.278679,0.097946,-0.310584,0.143666,-0.189750,-0.201660,-0.563154,-0.408356,0.146638,0.112277,-0.509033,0.438147,-0.840296,0.215840,0.350596,0.411940,-0.688992,0.761815,0.125006,-0.072307,-0.055563,-0.071745,-0.062364,-0.015850,-0.110271,0.094499,0.232342,0.110283,-0.364543,-0.366276,0.135373', '1301022', '3811342', '1308805', '1299649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300075', '小姐与流浪汉', '喜剧', '圣诞节到了，吉姆送了一条宠物狗“淑女”给太太。聪明乖巧的“淑女”备受女主人宠爱，一直过着无忧无虑的幸福生活。然而，随着一个小生命降生到这个家庭，“淑女”的地位就开始节节下降。受到冷落的“淑女”离家出走了，然而从来就不愁吃不愁穿的“淑女”顿时陷入了困境，幸亏她遇到了一只好心的流浪狗查普。查普与“淑女”很快成了好朋友，并在经历了种种冒险之后，他们擦出了爱的火花，“淑女”也平安回了家，从此无忧无虑的生活在一起。©豆瓣', '芭芭拉·卢迪', '克莱德·杰洛尼米', 8.6, 25145, 'tt0048280', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1833124344.jpg', 0.1, 0.4, 12, 45.5, 42, '0.316430,0.311624,-0.578546,0.328655,-0.257234,-0.638217,0.574186,0.361007,-0.422000,0.089856,0.095984,0.780390,-0.158158,0.425586,0.575478,0.024266,-0.182488,-0.738900,-0.002772,0.148591,-0.010482,-0.126686,-0.019997,-0.020431,-0.137727,-0.407117,0.101545,-0.079119,0.311653,0.527415,0.219031,-0.183899,0.031185,0.482892,-0.638446,0.438293,-0.220026,0.270508,-0.348297,0.099467,0.166424,-0.139269,0.090532,0.072657,0.319196,0.138832,0.644751,-0.573514,-0.497126,-0.000028,0.665070,-0.060198,-0.035381,0.215193,0.439272,-0.089623,0.203543,-0.265222,-0.035827,0.403423,0.159399,-0.317472,-0.479521,-0.119499,-0.166741,0.040976,-0.794892,0.832135,0.199803,-0.333820,0.112882,-0.347448,0.195107,0.151663,-0.175716,0.432536,-0.422927,0.519277,-0.434573,0.333194,0.789636,0.136083,-0.540680,0.457836,-0.266106,-0.256999,0.152600,-0.745494,-0.601570,-0.128232,0.265048,0.179513,-0.528631,0.355981,-0.736402,0.107084,-0.233203,-0.135267,0.222996,-0.492422,-0.267534,-0.177642,-0.190803,-0.508172,-0.364992,0.163814,-0.163463,-0.084767,0.695914,-1.003825,0.513663,0.327496,0.159668,-0.611986,0.493607,0.024766,0.240278,0.216131,0.243486,0.318336,-0.115847,0.451952,0.248596,0.376691,-0.332219,-0.016913,-0.196535,0.474758', '1292219', '1292720', '1299062', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300080', '鸡同鸭讲', '喜剧', '许记烧鸭是香港街头尽人皆知的风味美食，虽然店铺寒酸，装潢陈旧，但是凭借老板老许（许冠文 饰）那一手出色的烧鸭技巧，依然引得众多食客前来大快朵颐。店内生意兴隆，但老许对待下面的员工却甚为苛刻。无休止的加班、可怜的薪水，员工们怨声载道，反被老许巧言令色蒙骗过去。不过就在某一天，许记烧鸭的灾难来了。对门的店铺开了一家西式炸鸡店，老板丹尼（吴启华 饰）以先进的理念推广他的西式快餐，很快便将老许的客人抢了去。危机当头，老许想出各种办法应对，而丹尼也意欲将烧鸭店置于死地……本片荣获1989年美国拉斯维加斯国际喜剧最佳男主角奖大奖。©豆瓣', '许冠文', '高志森', 7.9, 16063, 'tt0095396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2505096296.jpg', 0.4, 1.5, 25.1, 50.5, 22.4, '0.315584,0.211747,-0.318974,0.178898,0.072593,-0.224437,0.483828,0.500603,-0.388525,0.001410,0.265794,0.506703,-0.067322,0.077900,0.407772,0.065278,-0.014191,-0.256758,0.026052,-0.104573,0.001404,-0.073495,-0.165946,-0.361877,-0.207061,0.262079,0.013304,0.002497,-0.089372,0.223389,0.399498,-0.174948,0.005336,0.274860,-0.257186,-0.055008,0.233901,-0.153967,-0.502385,0.168936,-0.103155,-0.429814,-0.218721,0.166096,0.343635,0.243848,0.406565,0.189135,-0.340572,0.181455,0.453468,0.053471,-0.087461,0.302986,0.269335,0.049104,0.252679,-0.191004,-0.203518,0.095656,0.024840,-0.165129,-0.654440,0.138054,0.045721,-0.286570,-0.545359,0.412236,-0.005428,-0.034976,-0.364219,-0.358022,0.073733,-0.180271,0.346660,0.355493,0.271990,0.235200,-0.674436,0.309357,0.450588,0.105925,-0.003191,0.124457,-0.356757,-0.295182,0.174805,-0.420812,-0.297091,-0.150450,0.344163,-0.059632,-0.006106,-0.184422,-0.891328,0.158067,-0.077252,-0.324639,0.062489,0.002004,-0.197523,-0.890557,0.192155,-0.198383,-0.138145,-0.146042,0.520158,0.054257,0.721426,-0.410787,-0.189532,0.676553,0.339985,-0.372102,0.745332,-0.288903,0.080077,0.217720,-0.611918,-0.332083,0.075246,0.256208,0.251183,0.627686,0.119247,-0.532779,0.001914,0.258114', '1309101', '19965431', '20283482', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300082', '古今大战秦俑情', '爱情', '李碧华的妙笔在时空的流转下谱写出一段可歌可泣、跨越古今三代的传奇爱情。公元前二百多年，秦始皇暴虐无道，民不聊生。方士徐福骗得始皇信任，征召众多童男童女东渡蓬莱寻取长生仙药。曾因搭救秦始皇而被封官赐剑的郎中令蒙天放（张艺谋饰）与应征少女韩冬儿（巩俐饰）一见钟情，偷尝禁果，以欺君之罪被赐死。行刑前，冬儿暗将徐福炼就的长生不老金丹送入蒙天放口中，自己投身窑炉，殉情而死。蒙天放则被泥封为俑，置于皇陵。20世纪30年代，冬儿转世成为三流影星朱莉莉。剧组前往秦始皇陵附近拍摄电影。莉莉发现自己暗恋的大明星白云飞（于荣光饰）盗掘皇陵的勾当。白云飞为杀人灭口，驾机携莉莉飞入空中。莉莉误将仪表盘打破，随机栽入秦始皇陵，使沉睡地下两千年的蒙天放得以复苏，并与闯入墓中的白云飞等盗墓贼展开搏斗......©豆瓣', '张艺谋', '程小东', 7, 47771, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2456463996.jpg', 1.1, 6.3, 44.1, 36, 12.4, '0.028993,0.243306,-0.407692,0.393750,0.017359,-0.091516,0.587412,-0.174528,-0.305422,-0.155317,0.382880,0.630503,-0.456721,-0.083608,0.126341,0.149788,0.002374,-0.584133,-0.166745,-0.110288,-0.113840,-0.151919,-0.402694,0.322115,-0.314883,-0.273626,0.816300,0.041936,-0.101312,0.202414,0.056631,0.255488,-0.267990,-0.042310,-0.295400,0.248152,-0.267966,-0.111227,-0.274269,0.330715,-0.366711,-0.459097,0.003013,-0.165949,-0.483044,0.031205,0.371741,-0.308507,0.216858,-0.402705,0.478050,-0.177458,-0.412875,0.021710,0.204733,0.400817,-0.040808,0.346744,-0.157995,0.093538,0.144056,-0.050973,-0.359241,0.036927,0.090208,0.059428,-0.351399,0.012348,0.115919,0.054131,0.097852,-0.192492,0.231233,0.160919,0.382430,0.324807,-0.142802,-0.106233,-0.462229,0.535290,0.279092,-0.350987,0.013650,-0.011565,0.279557,-0.473044,0.220263,0.017072,-0.074503,-0.062261,0.333631,-0.050943,0.026712,0.387163,-0.369423,-0.203163,-0.406955,0.099220,0.033876,0.211088,-0.368218,-0.544984,-0.119295,0.090172,-0.174477,-0.321674,0.251403,-0.300754,0.390348,-0.268651,0.386258,0.254672,0.196333,-0.197144,0.679597,-0.177607,0.089717,-0.039741,-0.072630,0.520521,0.012922,0.363728,-0.052155,-0.010100,-0.194444,0.106632,-0.467521,0.192509', '1780122', '1322847', '1297368', '26990609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300085', '尸家重地', '喜剧', '三百年前，一个岛上渔村的村民将一队路过的护送贡品官兵尽数杀死，并不慎惊醒了一具秦尸，借宝物力量将其封印。自此，此地村民不事生产却凭借祖传财宝衣食无忧。驻岛警察石春（元奎 饰）怀疑村民制毒谋利，令两名助手陈龙士（杜德伟 饰）、小钢炮调查多时但一无所获。是日，一戏班来岛上演出，疑心戏班与村民里应外合贩毒的石春出面调查，不期然使戏班的九姐（吴君如 饰）对自己一见钟情。当夜，九姐和戏班中的阿秋（陈淑兰 饰）、林老师（卢冠廷 饰）偶然得到从村民中泄露出来的藏宝图，三人试图将村中宝藏据为己有，却惊动秦尸令其再出人间，复仇的冤魂在村中大开杀戒，石春为斩妖除魔，犯险寻找古时宝物——钟馗宝剑。©豆瓣', '吴君如', '刘镇伟', 7.2, 12742, 'tt0100598', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2332476790.jpg', 1.2, 5.6, 42.3, 35.3, 15.6, '0.023408,0.023933,-0.239048,0.267489,0.003458,-0.002942,0.569611,-0.367417,-0.744563,-0.184395,0.148992,0.520134,0.080620,0.169280,0.059419,0.035167,-0.143075,-0.435292,-0.160509,-0.248161,-0.261852,0.067661,-0.168456,-0.285865,-0.339786,-0.351574,0.303439,0.371225,-0.176788,0.449008,0.205391,0.134795,-0.606427,0.312605,-0.057449,0.041913,-0.107841,-0.025487,-0.206520,0.189639,-0.388269,-0.550653,-0.187216,0.045225,-0.030898,0.396563,0.623725,-0.302350,0.068381,-0.198076,0.068756,-0.005923,0.103225,-0.051009,0.425973,0.230162,0.087308,0.210624,-0.471127,0.019978,0.050072,-0.049893,-0.455209,-0.102969,0.395038,0.025422,-0.516318,-0.026155,0.107503,0.316452,-0.159783,-0.164224,0.460614,0.069106,0.196018,-0.105879,-0.098169,-0.364019,-0.601691,0.530109,0.369297,-0.584440,0.331987,-0.219226,-0.050806,-0.465001,0.293220,-0.017957,-0.035466,0.090794,0.462254,0.067776,0.058857,-0.048984,-0.504048,-0.194082,-0.404388,0.166000,-0.165055,-0.057509,-0.054414,-0.667227,0.097428,0.294208,-0.040963,0.143914,0.455732,0.009349,0.503196,-0.330956,0.014249,0.546905,0.320596,-0.257982,0.408128,-0.431782,0.324926,-0.116562,-0.215846,-0.036103,0.455649,0.533015,0.110682,0.173205,-0.119950,-0.275160,-0.150513,-0.058357', '1307897', '10466639', '1306490', '1301257');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300089', '星际旅行1：无限太空', '科幻', '寇克将军，欢迎您重返企业号！一团硕大无朋的高能离子云，在遥远而神秘的太空中迅疾地飘移。这团能量云具有无坚不摧的威力，足以毁灭宇宙间任何物质结构。在它所划过的轨迹上，早已有好几艘分属银河三大势力的星舰遇难了……地球-银河系星球联邦的重镇，星际舰队总部的所在地。在位于北美洲旧金山的星际联邦舰队总部，寇克将军正像往常一样百无聊赖无所事事，突然间却接到了一个再好不过的命令检视企业号准备执行紧急任务。原来地球的防卫体系己经发现了那团高能离子云，而且侦测出它正对准地球飞来。寇克将军的任务，就是要赶在它到达地球之前，率领企业号先迎上去一探究竟。阔别了将近十年，当寇克重新登上企业号时，内心的兴奋与激动真是难以形容。可是当他 随着现任的舰长迪卡检阅过了人员与装备之后，却又不禁兴起不少陌生的感觉。因为经过 这些年来的不断改良，企业号的功能与威力都增强了许多，但也因而使得前任的舰长寇克 将军有点摸不着头绪了。不过还好的是，接下来马上就有很大的惊喜冲淡了这份陌生感神通广大的寇克竟然在短时间之内几乎把老战友都找齐了！例外的只有史波克先生，他因为正在瓦肯星进行高深的修炼，所以没有办法赶来，成了这次任务的唯一遗憾。由于寇克是星际舰队的高级长官，所以在出发之后，迪卡舰长只好很不情愿地暂时交出指挥权。一开始的时候，两位新旧舰长之间难免有些成见与摩擦，但渐渐地就因为相互了解而变得惺惺相惜。寇克发现迪卡的确是个优秀称职的好舰长，而迪卡也开始真正地把寇克 敬作父执。原来迪卡的父亲也曾做过寇克部下，后来却不幸在末日武器那个事件中英勇牺牲了。企业号上的新面孔，除了迪卡舰长之外，还有一位美丽的女领航员伊莉雅。虽然她是德罗坦', '威廉·夏特纳', '罗伯特·怀斯', 7.7, 15539, 'tt0079945', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209380289.jpg', 0.7, 3.1, 28.5, 44.6, 23.1, '0.169854,0.256252,-0.871575,0.681070,0.203470,-0.179162,0.667120,0.017608,-0.508390,-0.144614,0.035883,0.616319,0.133362,0.257983,0.326669,0.072291,-0.311068,-0.419909,-0.162347,-0.314240,-0.416058,-0.655935,-0.364223,-0.187184,0.074491,-0.511146,0.713407,0.159012,-0.125092,0.225494,0.160060,0.168449,0.043710,0.682150,-0.176924,-0.185174,0.229801,-0.029927,-0.104966,0.069801,-0.043921,-0.016418,0.081913,0.183851,0.130953,0.460615,0.465261,-0.422007,-0.159651,-0.040533,0.171672,-0.049497,0.117137,-0.194907,0.436663,0.211216,-0.146350,0.076622,-0.060004,0.014471,0.011134,-0.036899,-0.720233,-0.037625,0.148226,0.046333,-0.419999,0.206293,-0.196694,-0.095311,-0.175541,-0.289026,0.190345,0.502733,0.082718,0.242503,-0.192904,0.247871,-0.352260,-0.043022,0.502548,0.078473,-0.585543,0.294111,0.042465,-0.536493,-0.274810,-0.299602,-0.195691,-0.086024,0.169179,0.181156,0.117889,0.395871,-0.678268,0.210728,-0.373735,-0.330042,-0.003259,-0.180992,0.038145,-0.593810,0.181437,-0.346001,-0.286404,0.251281,0.144672,-0.016411,0.686743,-0.788000,0.071150,0.453160,0.134333,-0.295360,0.506995,0.015370,-0.010752,-0.287719,0.090376,0.077075,0.134298,0.587767,0.206598,0.420837,0.136355,-0.353155,-0.260400,0.449612', '34461680', '25932086', '4079119', '1304496');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300092', '地心抢险记', '动作', '某天，世界各地接连出现奇怪现象：安装心脏起搏器的病人突然暴亡、鸽子迷失方向四处乱撞、金门大桥断裂、罗马竞技场遭到密集雷电袭击……一时间，人类陷入前所未有的恐慌，似乎恐怖的世界末日就在眼前。各国政府及军队紧急动员，急切找到这一连串灾难发生的原因。在这关键时刻，地质物理学家乔许·凯斯（艾伦·艾克哈特 Aaron Eckhart 饰）探明真相，原来地核因某种未知的原因停止转动，导致磁场消失。为了拯救人类和地球，乔许以及蕾贝卡·柴德（希拉里·斯万克 Hilary Swank 饰）、罗伯特·艾维森（布鲁斯·格林伍德 Bruce Greenwood 饰）等专家组成一支救援小组，共同前往地球中心实行艰巨而充满危险的拯救任务。人类的命运命悬一线……©豆瓣', '艾伦·艾克哈特', '乔恩·阿米尔', 6.8, 26277, 'tt0298814', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1715872334.jpg', 1.1, 7.6, 51.7, 31.1, 8.6, '0.119964,0.057271,-0.818143,0.114233,0.418954,0.337526,0.667190,-0.111082,-0.182465,-0.384486,0.336060,0.400631,-0.363375,-0.241417,0.242166,-0.090104,-0.421445,-0.410248,-0.056031,-0.017397,-0.387526,-0.476026,-0.498427,-0.582281,0.366867,-0.348969,0.566267,0.363719,-0.218908,0.351255,-0.108505,0.792839,-0.333043,0.396522,0.309665,-0.097319,0.271574,-0.222200,-0.285146,-0.007588,-0.124800,0.115512,0.094197,0.293030,-0.299169,0.289124,0.444744,-0.560504,-0.007413,-0.240512,0.254747,-0.442656,0.025556,-0.193991,0.379889,0.046548,-0.240543,-0.136982,0.001767,0.062284,0.061198,0.051440,-0.608938,0.054085,0.030064,0.422404,0.051072,-0.070284,-0.093650,-0.026202,0.097553,-0.306279,0.163342,0.775644,0.548551,0.353905,-0.338750,0.086199,-0.128320,-0.241707,0.617042,-0.223099,-0.706772,-0.164551,-0.406239,-0.357356,0.041708,-0.065024,-0.330230,-0.139580,0.318174,0.170865,0.020410,0.598811,-0.584219,0.026515,-0.350329,-0.475328,-0.221919,0.062640,-0.367900,-0.862362,0.083007,0.068111,-0.145085,0.115078,-0.162278,0.082276,0.367334,-0.352328,0.379856,0.671816,0.051605,-0.281088,0.126317,-0.205330,0.017050,-0.361898,-0.311852,0.590039,0.111994,0.397991,-0.192563,-0.223553,0.110039,0.213005,-0.261816,0.201771', '3871833', '3231742', '1306809', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300093', '胜利大逃亡', '剧情', '二战末期，德国纳粹的攻势渐显疲态。位于法国的某纳粹集中营内，德国军官为鼓舞士气，同时打击盟军的气焰，竟别出心裁地想出了一场国际足球赛。由兵强马壮的德国队，对抗羸弱不堪的国际战俘队。前英国国脚科尔比（迈克尔·凯恩 Michael Caine 饰）认为这是绝佳的越狱良机，于是欣然接受德军 的提议。科比一方面网罗足球方面的人才，抓紧训练，一面委派美国人哈奇（Sylvester Stallone 史泰龙 饰）逃出集中营，联络巴黎的地下组织，准备在比赛那天里应外合，集体越狱。比赛的日子逐渐临近，他们最终能否成功？©豆瓣', '西尔维斯特·史泰龙', '约翰·休斯顿', 7.8, 6059, 'tt0083284', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2410171376.jpg', 0.3, 1.6, 26.8, 52, 19.3, '-0.137050,-0.001317,-0.563575,0.501847,0.336602,-0.385708,0.005111,0.061538,-0.454647,-0.048233,0.368678,0.306891,-0.087213,-0.151915,0.402400,-0.453873,-0.411379,-0.748987,-0.337850,-0.013321,-0.152808,-0.310671,-0.609389,-0.280964,0.150564,-0.265381,0.840599,0.313626,-0.298056,0.286755,0.260328,0.408850,0.384201,0.138222,0.124159,-0.379299,0.337319,-0.220398,-0.585088,0.322545,-0.067096,-0.275653,-0.221706,-0.029172,0.186285,0.274201,0.541353,-0.201507,0.372139,-0.317994,0.313731,-0.216669,-0.043623,0.294597,0.426309,0.144506,0.073090,0.060510,0.028971,0.071430,-0.181711,-0.301987,-0.519600,0.224936,0.036815,-0.172635,-0.207669,0.464805,-0.270332,0.473667,0.148699,-0.233218,-0.066474,0.775407,0.230844,0.143142,0.106303,0.157467,-0.327328,0.173226,0.562953,-0.175536,-0.282773,-0.325240,-0.126962,-0.295767,0.313578,-0.589545,0.127716,-0.004581,0.376387,-0.392632,0.134900,0.288768,-0.678983,0.030820,-0.430911,-0.264094,0.123896,0.045765,0.168869,-1.089792,0.063110,-0.019521,0.010518,0.058598,-0.026973,0.339028,0.609563,-0.712773,-0.105544,0.719513,0.130912,-0.273450,0.240319,0.164548,0.214354,-0.069149,-0.150259,0.289234,-0.247080,0.269812,-0.163575,0.291110,-0.064113,-0.481800,-0.036597,0.105485', '2369613', '4014397', '20274039', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300108', '秋菊打官司', '剧情', '中国西北某个小山村里，村妇秋菊（巩俐 饰）的丈夫万庆来（刘佩琦 饰）在与村长争执时被对方踢伤下体无法再干农活，只能整日躺在床上，对此村长没表一态。秋菊气不过，找村长理论不得对方理会，为讨一口气，她一纸诉状将村长告到了乡政府。乡政府李公安耐心调解一番后，村长答应赔偿秋菊家的经济损 失，却是把钞票直接扔在地上拒不道歉。村长的举动虽蛮横无理，众人还是觉得事情可以就此划上句号，唯独秋菊被激怒，立誓要讨个说法，于是她挺着个大肚子和妹妹来到县城，开始了漫漫告状路。©豆瓣', '巩俐', '张艺谋', 8.2, 95056, 'tt0105197', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554073275.jpg', 0.2, 0.8, 17.1, 54.8, 27.1, '0.431424,0.164325,-0.372416,0.351483,-0.286608,-0.394365,0.321092,0.303824,-0.592342,0.115940,0.061072,0.378826,-0.177185,0.165387,-0.057188,-0.164827,-0.284131,-0.425553,-0.103872,0.058242,-0.185600,-0.528223,0.430710,-0.206844,-0.635169,0.335033,0.050453,-0.341842,-0.181393,0.185941,0.303363,0.048086,0.175007,0.358985,-0.309208,0.285742,-0.251865,-0.164878,-0.087397,0.082499,0.329099,-0.258337,-0.243883,0.100780,0.209876,0.302198,0.453865,0.034242,-0.127998,-0.205796,0.201477,-0.120141,0.267028,0.491099,0.236061,-0.188185,0.253807,0.035263,-0.370417,-0.171653,0.558935,-0.034435,-0.053141,0.237493,-0.158055,0.224323,-0.898123,0.135346,-0.094936,0.017367,-0.088154,-0.436362,0.158155,0.114672,0.030018,0.308074,-0.013512,-0.002564,-0.455243,0.282871,0.349005,0.143981,0.304879,0.019463,-0.018458,-0.150824,0.369374,0.043770,-0.224204,-0.304289,0.214728,-0.211043,-0.125410,-0.184190,-0.335180,-0.151444,-0.213370,-0.224908,0.010677,-0.247415,-0.157756,0.131110,0.000766,-0.072750,-0.270417,0.121745,0.225790,0.091118,0.206740,-0.269684,-0.134958,0.214270,0.288677,-0.326765,0.634192,0.403917,0.164529,-0.201486,0.257590,-0.331922,0.017489,0.646473,0.553123,0.144356,0.031914,-0.256088,-0.083165,0.249061', '1754628', '1306505', '1432825', '1461964');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300117', '千钧一发', '剧情', '未来的世界，科技的力量胜过一切，基因决定命运，几乎成为金科玉律。不幸文森特（伊桑•霍克 Ethan Hawke  饰）是一个基因不良的人，出生以来就决定了他近视和心脏病的缺陷，他只能活到30岁。于是父母为文森特增添了一个有着优良基因的弟弟。文森特的梦想是漫游太空，然而恶劣的基因令他无法圆梦，直到他遇到了太空中心的杰罗姆（裘德•洛 Jude Law  饰）。杰罗姆有优秀的基因，却在一次意外中半身瘫痪。二人决定调换身份，文森特千方百计隐藏自己的基因信息，每天都认真清洗掉自己的皮屑毛发，不暴露任何蛛丝马迹。另一方面，杰罗姆帮他筹备进入太空前需要检查的基因物品。事情进展得非常顺利，然而一桩谋杀案和一根睫毛，让事情节外生枝。©豆瓣', '伊桑·霍克', '安德鲁·尼科尔', 8.8, 268784, 'tt0119177', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195672555.jpg', 0.1, 0.5, 8.6, 40, 50.7, '-0.133368,0.115077,-0.649808,0.679267,-0.425657,-0.163318,0.450022,-0.001917,-0.578234,-0.483807,0.125307,0.658704,0.130510,0.208635,-0.068056,0.008733,-0.378598,-0.680152,0.373973,0.032043,-0.612067,-0.535131,-0.367080,-0.474433,-0.016104,-0.539348,0.764400,0.113288,-0.308058,0.097451,-0.024074,0.353980,-0.037627,0.324223,-0.302151,-0.206759,0.220613,-0.045850,-0.225801,0.227553,0.191928,0.025322,0.140551,0.421246,-0.114639,0.362114,0.623170,-0.255594,-0.450379,-0.072102,0.481326,-0.359393,0.045739,0.194777,0.390139,0.131484,-0.045203,0.300510,-0.087385,0.057338,0.244662,0.056574,-1.183188,-0.394416,0.111051,0.184172,-0.538733,0.336111,-0.227796,-0.004220,0.031860,-0.430805,0.034353,0.317608,0.442905,0.309240,-0.328208,0.178725,-0.537085,0.036972,0.436130,-0.096698,-0.472949,0.699295,-0.365308,-0.614564,-0.257361,-0.341926,-0.338091,0.299054,0.279879,0.382240,-0.195278,0.592231,-0.455008,-0.103352,-0.461450,-0.311842,-0.075638,-0.225760,0.035594,-0.228248,-0.315550,-0.342942,-0.645275,0.162317,0.043629,-0.589070,0.552490,-0.518343,0.053153,0.449982,-0.113039,-0.799442,0.578831,-0.061539,0.272357,-0.310590,0.138263,0.264075,-0.081658,0.125452,-0.050134,0.244385,0.194977,-0.021557,-0.488700,0.480868', '26678784', '6844861', '3670447', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300122', '玉蝎子的魔咒', '喜剧', 'CW•布里格斯（伍迪•艾伦饰）是20世纪40年代美国纽约著名的北海岸保险公司的最出色的保险调查员，他的拿手绝活是能窥探犯人心中所想，从而轻而易举地破案。自从老板请来了“效率专家”贝蒂，这一切就改变了。贝蒂新官上任，带来新的策划新的管理方式，布里格斯成为被开刀的第一人。二人之间火药味甚浓。在同事乔治的生日会上，他俩被魔术师叫上台，在玉蝎子的魔力下，二人被催眠，醒来后对刚才发生的事一无所知。之后城内接二连三发生珠宝盗窃事件，而被窃珠宝的报警装置是布里格斯亲手设置的，没有他是不可能破开的。在调查案件中，肯辛顿家的尤物女儿（查理•塞隆饰）主动约他约会，他怀疑她的动机。而贝蒂请来侦探协助他调查让他更为不快。贝蒂是上司的情人，因为老板迟迟不肯跟妻子离婚而倍感伤心。神使鬼差走到了布里格斯家跟他倾诉，布里格斯怀疑是贝蒂泄漏了公司机密，随后贝蒂对他的示爱更令他加深怀疑。要在一系列欢笑嬉闹中，最后才想起一切缘自当初的那个玉蝎子的魔法，这些盗窃案最后还撮合了一对天作之合。', 'John Tormey', '伍迪·艾伦', 7.7, 7687, 'tt0256524', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1287746872.jpg', 0.4, 2.1, 29.1, 49, 19.3, '0.329948,-0.090419,-0.756062,0.485095,-0.250866,-0.102651,0.648662,-0.094225,-0.614726,-0.345720,0.137982,0.751670,-0.359182,0.134532,0.182473,0.164413,-0.217492,-0.803628,-0.038184,-0.229633,-0.213873,-0.525679,-0.119088,-0.317287,-0.116552,-0.129550,0.254454,0.014628,-0.275084,0.198512,0.291429,0.335810,-0.120426,0.406363,-0.106949,0.006761,0.294347,0.114164,-0.376703,0.219939,0.212154,-0.331842,-0.026335,0.439239,-0.008290,0.363189,0.406195,-0.196985,-0.158415,-0.052436,0.342437,-0.326175,0.070089,0.093871,0.408491,0.088655,0.095884,0.303237,-0.377579,-0.223808,0.139383,0.044391,-0.774483,0.118624,0.134462,0.104441,-0.577531,0.153859,-0.266037,0.082680,0.149982,-0.275274,0.468156,0.363924,0.285987,0.193469,0.102400,-0.076243,-0.453346,0.179407,0.676388,-0.113549,0.062637,0.384872,-0.240469,-0.274011,0.010575,-0.083074,-0.322370,0.210997,0.335809,0.135890,-0.114210,0.188791,-0.393270,-0.319532,-0.302542,-0.113960,-0.077495,-0.459526,0.005593,-0.510430,-0.222490,-0.444952,-0.247372,-0.059393,0.111899,-0.292518,0.324245,-0.934950,0.012046,0.708211,0.195942,-0.618585,0.509577,0.113498,-0.064313,-0.337742,-0.067620,-0.238182,0.074400,0.295041,0.150214,0.448506,0.435154,-0.294592,-0.229698,0.220642', '35073886', '1301022', '30345227', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300130', '森林泰山', '喜剧', '从小被猩猩养大的乔治（布兰登·费舍 Brendan Fraser饰）一直生活在茂密的丛林中，逐渐成了森林之王。白人少女乌苏拉（莱斯利·曼恩 Leslie Mann饰）与未婚夫莱尔（托马斯·哈登·丘奇 Thomas Haden Church饰）来到非洲丛林中探险。然而两人突然遭遇狮子的袭击，危急时刻，自私的男友居然扔下乌苏拉独自逃生。幸好乔治及时将她救下，将她带到丛林的树屋中。在这里，两人度过了一段美好奇妙的丛林时光，单纯善良的乔治也赢得了乌苏拉的芳心。然而死心不改的莱尔竟开枪射伤了乔治，甚至偕同几个盗猎者要抓乔治的猩猩朋友去卖钱。由迪斯尼公司于1997年推出的卖座喜剧电影《森林泰山》，根据美国六、七十年代同名电视卡通系列片改编而成。真人版的《森林泰山》，风格节奏及人物塑造依旧保持着原卡通片的幽默夸张，巧妙地保留了动画风格。本片在当年的全球票房收入高达一亿七千万美元，同时也捧红了“森林之王”布兰登·费舍，使他一跃跻身为好莱坞当红小生的行列。', '约翰·克里斯', '萨姆·韦斯曼', 7, 7109, 'tt0119190', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2254790965.jpg', 0.6, 4.3, 48.8, 35.2, 11.1, '0.092400,0.166965,-0.618677,0.553450,0.050148,-0.226364,0.653977,0.101291,-0.083227,0.017007,0.317622,0.562059,-0.221544,-0.022648,0.329586,0.112286,-0.213159,-0.369001,-0.391293,0.169774,-0.092487,-0.064638,-0.774731,-0.268076,-0.098948,-0.300552,0.642877,-0.109640,-0.281865,0.434943,0.172877,0.216886,-0.172857,0.016542,-0.268909,0.115527,0.135961,-0.031004,-0.297246,0.300886,-0.250885,-0.121256,-0.144636,-0.171226,-0.014290,0.217260,0.768661,-0.292895,0.138859,0.063809,0.432909,-0.159038,-0.003213,-0.241288,0.299430,-0.361541,0.160081,-0.013914,-0.040840,0.121239,0.035438,-0.333524,-0.531565,0.149296,-0.015625,0.058251,-0.502130,0.205207,-0.129917,0.122661,0.234127,-0.353200,-0.219603,0.052004,0.334677,0.191262,0.102797,0.155869,-0.288990,0.226119,0.357535,-0.282078,-0.342282,0.314467,-0.075005,-0.422276,-0.084335,-0.194160,-0.464682,-0.233824,0.520721,-0.188646,-0.103357,0.120745,-0.589631,-0.164532,-0.235876,-0.175491,0.061229,-0.309677,-0.231461,-0.530845,-0.007042,-0.337878,-0.139399,-0.229203,-0.044960,-0.054906,0.471036,-0.223208,0.429608,0.459971,-0.026363,-0.047968,0.613543,-0.250286,0.035884,0.097948,-0.028645,0.586969,0.174052,0.239181,0.326352,0.364799,-0.266002,-0.181874,-0.365365,0.460519', '24879819', '1467779', '21619567', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300139', '终极斗士', '剧情', '加州沙漠的甜水监狱，在一群疯狂的犯人观众之中，监狱拳王蒙罗•哈金（韦斯利•斯奈普斯 Wesley Snipes 饰）再一次击败了他的对手。哈金曾是一名拳手，因杀人被判终身监禁，他凭借出色的拳击技术，在监狱之间的拳击联赛中蝉联十年冠军。此时，重量级拳击冠军“冰人”乔治•钱伯斯（文•瑞姆斯 Ving Rhames 饰）因强奸罪被起诉，被收押在甜水监狱。监狱众人认为蒙罗和冰人之间必有一战，阅拳手无数的狱中拳赛安排者——雷顿开始筹划两人的比赛。冰人坚称自己并未犯罪，利用自己拳王的影响力在狱中向监狱长施压，同时不忘挑衅蒙罗这种他根本看不上眼的狱中拳手。蒙罗在和冰人的对峙中尽落下风，早早就被监狱方面关入了单人牢房，二人的决战，似乎已不可避免……©豆瓣', '韦斯利·斯奈普斯', '沃尔特·希尔', 6.7, 6273, 'tt0281322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2163981993.jpg', 1.6, 9.6, 50.7, 27.2, 10.9, '0.183606,-0.157016,-0.578197,0.523471,-0.098640,-0.018759,0.778563,0.168339,-0.557844,-0.075473,0.535913,0.665574,-0.301403,-0.109079,-0.050560,-0.537429,-0.113499,-0.889370,-0.476581,-0.233662,-0.393100,-0.425128,-0.128916,-0.058807,-0.002617,-0.198406,0.655382,0.114440,-0.267917,0.385423,0.161280,0.471213,-0.018275,0.239913,-0.103799,-0.148359,0.365894,-0.118614,-0.362471,0.363591,-0.117183,-0.194229,-0.274507,0.088122,0.124404,0.277605,0.542486,-0.037000,0.046151,-0.291674,0.285087,-0.408915,-0.185701,0.355190,0.542472,-0.201185,0.167559,0.266380,0.092624,-0.013128,-0.012468,-0.100778,-0.647011,0.148794,0.013125,0.023376,-0.357239,0.828252,-0.058729,0.403576,-0.160536,0.257812,-0.077182,0.044560,0.136282,0.114302,-0.002363,-0.231715,-0.627246,0.379205,0.645856,-0.224466,-0.184168,-0.133181,0.178981,-0.539287,-0.128010,-0.249811,-0.267216,-0.154729,0.594751,-0.135955,-0.149152,0.219654,-0.208402,-0.048332,-0.279161,-0.137064,-0.182903,-0.282378,-0.087875,-0.648402,-0.136143,-0.124527,-0.216195,0.120485,0.066094,-0.144881,0.162449,-0.725016,0.225223,0.573004,0.252490,-0.226747,0.677077,0.026782,0.120538,0.029041,-0.168959,0.122411,0.476753,0.198317,0.387102,0.556992,0.006584,-0.072131,-0.189517,0.622669', '4202326', '1293155', '1652618', '1295742');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300161', '情迷六月花', '剧情', '阿娜伊丝•宁（Maria de Medeiros玛丽亚•德•梅黛洛 饰），银行家雨果（Richard E. Grant 饰）的妻子，一个外表雍容却沉迷于D. H. 劳伦斯文字的野性女子。在丈夫的介绍下，阿娜伊丝结识了外表颓废粗糙的小说家亨利•米勒（Fred Ward弗雷德•沃德 饰），她迷上了眼前这个睿智的男子，继而又为亨利的妻子琼（Uma Thurman 乌玛•瑟曼 饰）所吸引。在琼的嘱托下，阿娜伊丝开始照料亨利的生活，为他的小说《北回归线》四处奔走，并由此衍生出一段段狂野激情的欢愉……本片获1991年奥斯卡最佳剧本提名。©豆瓣', '弗莱德·沃德', '菲利普·考夫曼', 7.6, 22974, 'tt0099762', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2531737113.jpg', 0.8, 3.5, 31.7, 44.3, 19.7, '0.103210,0.194422,-0.523826,0.694795,-0.088800,-0.586555,0.920056,0.141072,-0.124151,-0.192051,0.232323,0.702606,-0.473815,0.198072,0.509697,0.542639,-0.299039,-0.617138,-0.089398,-0.209876,0.126707,-0.299999,-0.292274,-0.126252,0.099281,-0.509037,0.641695,-0.186808,-0.089527,0.491863,0.123882,0.207650,0.229455,-0.055531,0.083028,0.285197,0.004532,-0.319470,-0.106879,0.043869,0.038416,-0.312305,-0.278414,0.346377,-0.092080,0.404211,0.840642,-0.337606,0.119464,-0.067024,0.503589,0.367049,0.356034,-0.072321,-0.168906,-0.246595,0.086137,0.130280,-0.061100,-0.114874,0.016155,-0.118342,-0.616654,0.210196,-0.012869,0.471878,-0.376652,0.478198,-0.348780,0.017275,-0.287636,-0.243983,-0.274382,0.048127,0.085304,0.342891,-0.019637,0.240117,0.002246,0.352361,-0.138343,0.321201,-0.387680,0.600335,-0.804697,-0.478220,0.053866,-0.059342,-0.710066,-0.141461,0.528246,-0.043536,0.216293,0.237727,-0.559600,-0.139922,-0.393642,0.258521,-0.134117,-0.094997,-0.218035,-0.686883,-0.338716,-0.431325,-0.310274,-0.452188,0.041297,-0.150008,0.854455,-0.411214,0.186189,0.579912,-0.086231,-0.195252,0.286262,0.094074,0.039271,-0.159033,-0.145726,0.772781,0.063684,-0.154603,-0.060443,0.555170,-0.054249,-0.080982,-0.507114,0.607973', '1296992', '3811356', '3097044', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300183', '古惑仔激情篇之洪兴大飞哥', '剧情', '洪兴大飞（黄秋生 饰）手下没牙佬的女儿阿May和东星大咪的手下皇帝（黎骏 饰）相恋，两个大佬为此坐下谈判。大飞嚣张气焰令皇帝的小弟善仔等人颇为不满，他们次日大闹大飞的桑拿馆，结果反被对方修理一通。某日，大飞看望罹患癌症不久于人世的前女友阿玲，继而得之自己有一个17岁的儿子，而儿子正是善仔。虽然亲子鉴定显示了他们的父子关系，但大飞和善仔均无法接受这个事实。东星社计划和云南毒贩做毒品生意，皇帝亲自操办此事。他委派善仔等人亲自前行，却暗中吞掉毒品，嫁祸大飞。在兄弟情义和父子亲情面前，善仔面临着充满艰险的抉择……©豆瓣', '黄秋生', '梁宏发', 6.4, 14763, 'tt0240559', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515570681.jpg', 4.2, 15, 49.4, 21.2, 10.2, '-0.017515,-0.170679,-0.514121,0.530335,-0.196575,-0.262519,0.348340,0.438871,-0.595809,-0.175239,0.273010,0.666198,-0.174915,0.341856,0.229768,-0.195538,-0.282126,-0.602656,-0.099815,0.213020,-0.037183,-0.328768,0.086465,-0.518890,-0.206153,0.204607,0.286091,-0.017199,0.007961,0.457415,0.255165,0.152663,-0.205266,0.498447,-0.067865,0.180840,0.113884,-0.094526,-0.368059,0.006065,0.232194,-0.348800,0.002930,0.155125,-0.083237,0.406891,0.467821,-0.099675,-0.130208,-0.534778,0.090674,-0.462564,-0.040247,0.140937,0.365877,0.002669,0.113932,0.269942,-0.139625,-0.455910,0.144063,-0.074799,-0.545389,-0.024834,0.121610,0.020037,-0.535902,0.347164,-0.277844,0.282777,-0.108631,-0.175236,0.260046,0.443936,0.112871,0.362571,-0.035466,0.047293,-0.507791,0.249675,0.728362,-0.101385,0.132302,-0.172547,-0.034498,-0.320280,0.190975,-0.294679,-0.297553,-0.008239,0.487142,-0.207715,0.008762,0.107424,-0.200769,-0.238780,-0.279009,0.079342,0.131506,-0.317468,0.156056,-0.401211,-0.194198,-0.384537,-0.275495,0.096821,0.294654,0.016256,0.328400,-0.463507,-0.015052,0.273335,0.359774,-0.647108,0.401333,0.145820,0.019437,-0.610910,-0.253990,-0.191626,0.144192,0.078857,0.342167,0.124038,-0.003838,-0.098720,-0.255828,-0.133251', '25721544', '25908042', '1301022', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300185', '月亮上的男人', '剧情', '这部传记电影的一开场，主人公安迪·考夫曼（金·凯瑞 Jim Carrey 饰）却向观众开了一个谢幕的玩笑。安迪自幼喜爱表演，成年后顺理成章成为饭店驻场演员，但事业并不顺利，一次他模仿猫王的表演引起好莱坞经纪人乔治注意，后者将他引荐到电视界。上镜前安迪从东方修行课上得到幽默的秘诀：沉默。安迪凭独特的表演风格得到观众青睐，进入了他颇为鄙视的情景喜剧领域。他创造出了一个不存在的人物托尼·克里夫，然后借克里夫的身份实现他和搭档的疯狂点子，和女人们进行的摔跤比赛更把他的疯狂推向了巅峰，安迪不断的戏弄、激怒观众，直至他患上癌症却没人相信，但安迪不在乎，因为生活本身就是一场无止尽的玩笑……本片获2000年柏林国际电影节最佳导演银熊奖，金球奖最佳男演员奖。©豆瓣', '金·凯瑞', '米洛斯·福尔曼', 7.8, 15428, 'tt0125664', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1950529895.jpg', 0.9, 3.9, 23.5, 45.6, 26.1, '-0.011474,0.092929,-0.529586,0.794281,-0.067520,-0.087975,0.625563,0.007115,-0.168674,-0.023836,0.261132,0.847251,-0.549884,0.014330,0.382101,-0.129448,-0.256898,-0.632520,0.123429,0.085650,0.114785,-0.261391,-0.275858,-0.149742,-0.286296,-0.455511,0.629629,-0.118191,-0.584593,0.310399,0.471091,0.010464,0.340686,0.462982,0.077470,0.072987,0.230866,-0.080994,-0.148043,0.476687,0.088207,-0.260606,-0.250899,0.232678,0.042971,0.148048,0.506594,-0.251151,-0.081655,-0.040277,0.610196,-0.428984,-0.066390,0.079470,0.078239,-0.026690,0.218800,0.010064,0.040409,0.174971,-0.213384,-0.243385,-0.871096,0.059877,-0.021098,0.100116,-0.349787,0.392557,-0.023384,-0.065659,-0.119552,-0.161655,0.051182,0.024386,0.446190,0.127346,-0.168036,0.131339,-0.435838,0.455748,0.625940,0.046799,-0.406530,0.600131,-0.177217,-0.629378,-0.068660,-0.432428,-0.454593,0.065487,0.480186,-0.044848,0.164763,0.003199,-0.188063,-0.274089,0.061031,-0.354866,-0.047237,-0.587894,0.137602,-0.770837,-0.138832,-0.155542,-0.083695,-0.497408,-0.019575,-0.734395,0.927271,-0.797051,-0.046715,0.542123,0.260828,-0.306372,0.776990,-0.095715,0.025509,-0.257967,-0.322705,0.139278,0.018078,0.094155,0.065589,0.522406,0.058566,-0.346033,-0.154305,0.643258', '27602116', '2027945', '1870681', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300186', '春逝', '剧情', '录音师李尚优（刘智泰饰）的妈妈早年去世，跟他相依为命的只有爸爸和患上了老人疑呆的奶奶。一个冬天，尚优认识了刚刚离婚的电台DJ韩恩素（李英爱饰）。恩素到来的目的是为自己的节目收录一些效果声音，他们到了一个竹林，用录音工具录下了风吹起竹叶的声音，到一间寺庙录取风铃的声音。他们走遍郊区，四处记录大自然的声音。两人感情发展迅速，春去夏至，李尚优和韩恩素跑到海边捕捉浪潮声。年轻的尚优仍然爱得炽热，但恩素的激情却开始冷淡下来。曾经历婚姻失败的她，始终不相信爱情会永恒不变，未能忘记离婚所带来的伤痛。而他一直想不通，爱情怎么会无声无息地溜走？©豆瓣', '李英爱', '许秦豪', 7.9, 22135, 'tt0295192', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1369457641.jpg', 0.3, 2.3, 25.4, 47.4, 24.6, '0.094777,0.107765,-0.678826,0.717458,-0.129896,-0.129296,0.928242,0.155434,-0.399632,-0.290118,0.010880,0.643215,-0.107021,0.316931,-0.138205,0.140396,-0.132992,-0.672158,0.041514,-0.098539,-0.306210,-0.388097,-0.017317,-0.092426,-0.044433,-0.098551,0.508717,0.283571,-0.258683,0.483014,0.138549,-0.218089,0.055882,0.541787,-0.297738,0.082882,-0.076232,0.188481,-0.166446,-0.044506,0.065325,-0.312880,-0.329021,0.096229,-0.160885,0.238892,0.602544,0.148074,-0.077947,0.283064,0.500246,-0.240506,0.045730,-0.019557,0.372904,0.061539,0.474512,0.359657,-0.187418,-0.077449,-0.126904,-0.016824,-0.497532,0.318107,-0.061045,0.438742,-0.340813,0.203167,-0.278891,0.078553,0.134841,-0.522344,0.065785,0.075551,0.096690,0.822512,-0.744491,-0.013836,-0.497207,0.255707,0.909082,-0.324770,-0.199700,0.591162,-0.176665,-0.406113,-0.181544,0.128004,-0.711013,-0.087295,0.270339,0.117796,-0.219377,0.068066,-0.530580,-0.035106,0.019344,-0.209228,0.073188,-0.456189,-0.203998,-0.364009,-0.423216,-0.467641,-0.423551,0.098023,-0.029164,-0.181239,0.578931,-0.629044,0.242548,0.484333,0.125417,-0.198720,0.518185,0.160354,-0.116029,-0.073878,0.274987,0.375400,-0.214132,0.283742,0.198512,0.228872,0.152025,0.044116,-0.521947,0.283819', '1296534', '4275444', '1291877', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300193', '性爱狂想曲', '喜剧', '其貌不扬的朝男（邓肯饰），毫无女人缘，他从早到晚想的就是和女人做爱。他认为只要有车就会有女人投怀送抱，艳遇不断，但是根本没人搭理他。他卖掉爷爷的肝和肾脏，换买了一辆敞篷车，之后又是想着飞机头等舱，意图打劫银行，或者是去当演员，但都没有能过成功，他的尝试一次又一次的以闹剧和失败收场。最后他想着变成别人看不见的隐形人，这样就可以肆无忌惮堤接近女人。在科学家（北野武饰）发明的机器帮助之下，他真的变成了隐形人，这次朝男能成功了吗？©豆瓣', '北野武', '北野武', 7, 17090, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2378326787.jpg', 1.9, 7.9, 41.2, 35.2, 13.9, '0.036714,-0.269923,-0.646160,0.404626,-0.515460,-0.249785,0.727036,-0.024390,-0.410047,0.241659,0.169962,0.634050,-0.161246,-0.110845,0.101264,0.163249,-0.337351,-0.608087,0.267514,-0.089776,-0.437051,-0.294409,-0.188664,-0.515314,0.084497,-0.190465,0.615527,-0.039785,-0.331202,-0.153396,0.613671,0.119676,0.306939,0.720271,-0.390923,0.050869,-0.286019,0.141044,0.021036,0.563847,0.152015,-0.108365,-0.139365,0.154781,-0.109895,0.338348,0.552321,-0.188421,-0.204036,0.002777,0.090784,-0.242155,-0.068677,0.064476,0.004032,-0.275726,0.338293,-0.072669,0.021246,-0.213576,0.361140,0.229894,-0.514208,0.156357,-0.203924,-0.112168,-0.546720,0.351347,-0.103680,-0.083553,0.102648,-0.485834,0.277137,0.113216,0.444242,0.281888,-0.206981,-0.250561,-0.880336,0.435461,0.592366,0.322589,-0.293384,0.769740,0.002147,-0.254294,0.006965,-0.573035,-0.463437,0.108495,0.228250,0.070542,-0.507030,-0.163700,-0.264375,0.162457,-0.159444,-0.192114,0.051726,-0.510952,-0.022503,-0.254329,0.145350,-0.126548,-0.225153,0.279501,-0.073027,-0.413996,0.520299,-1.028685,0.049596,0.645483,0.583382,-0.859772,0.931005,-0.029675,-0.389293,-0.182111,-0.017952,-0.296683,0.030484,0.316516,0.259322,0.432783,0.289821,-0.151927,-0.046740,0.448466', '2052978', '1853752', '1302384', '1293030');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300201', '金玉良缘红楼梦', '爱情', '千里迢迢投奔外祖母的林黛玉（张艾嘉 饰）与表兄宝玉（林青霞 饰）相会，两小无猜，童言无忌，虽惹出摔玉的闹剧，却让他们彼此走得更紧。岁月流逝，兄妹俩两情相悦，心意相托。但他们的爱情为族人所不容，王熙凤献出偷梁换柱之计，令宝玉娶得薛宝钗（米雪 饰）。黛玉悲痛难忍，含恨而逝。得知真相的宝玉弃家出走，遁入空门。本片荣获1978年亚太电影节和金马奖最佳美术执导奖项。[背景] 台湾独闯江湖失败后的大导演李翰祥，重新回到香港邵氏电影公司。适值红楼之风盛行，然而市面上多为粗俗拙劣之作。如邵氏早先一无名导演拍摄的《红楼梦》，另一家公司的《红楼梦醒》，以及更加粗俗的《红楼春梦》和《红楼春上春》，其业余和粗糙实在是对曹公名著的侮辱。也因此饱受中国古典文学熏陶的李翰祥才决定拍出一部艺术水平可与之相匹配的作品出来。演员方面他大胆启用曾参加台湾影视培训班的无名小辈林青霞和张艾嘉。电影开拍之初，李翰祥临时将林青霞和张艾嘉的角色兑换，这个无心之举却使他成为林青霞反串角色的发掘者。', '林青霞', '李翰祥', 7.4, 6731, 'tt0075959', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2666248375.jpg', 0.9, 4.1, 35.9, 41.5, 17.6, '0.093822,0.133801,-0.618980,0.624225,0.257303,-0.191352,0.422385,0.152250,-0.518217,-0.225058,0.208009,0.855234,-0.353157,0.220090,0.242226,0.036005,-0.190189,-0.486450,-0.167865,-0.103342,0.331207,-0.179924,-0.138069,0.087360,-0.422410,-0.091970,0.775160,0.064659,-0.486472,0.311584,0.427953,0.052355,-0.151075,0.080552,0.042406,0.153481,-0.223185,0.244803,-0.524244,0.100964,0.264513,-0.286010,-0.529201,-0.165146,-0.102742,0.182298,0.461688,-0.061528,0.002539,-0.211179,0.799004,-0.273218,-0.102248,-0.033977,0.044229,0.014533,0.420511,0.225953,-0.078782,0.168653,-0.095489,-0.182003,-0.679653,0.309431,0.410704,-0.076478,-0.369581,0.164967,-0.300679,0.053013,-0.261839,-0.248027,0.000110,0.003076,0.357210,0.286860,-0.164381,0.043757,-0.365993,0.711100,0.395940,0.066807,-0.133444,0.381579,0.076293,-0.590945,0.099907,-0.544056,-0.344403,0.165967,0.238938,-0.133947,0.070607,0.107972,-0.487173,-0.181341,-0.117887,0.061568,0.150608,-0.283596,0.194389,-0.702448,-0.198211,-0.299885,-0.239533,-0.300308,0.559767,-0.308938,0.776111,-0.431661,-0.048624,0.237818,0.121258,-0.612546,0.645170,-0.012143,0.120951,-0.027334,-0.098275,0.130992,-0.292301,-0.033032,0.107257,0.196479,0.042612,-0.418388,-0.252916,0.184565', '22265121', '27602116', '1297368', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300202', '八两金', '剧情', '张婉婷“移民三部曲”之一，时间背景为中国大陆改革开放初期。猴子（洪金宝）文革期间一声不吭离别家乡汕头台山偷渡赴美，立誓再也不回中国。16年来，他凭着中国人特有的小聪明和吃苦耐劳兢兢业业地做着的士司机，可是攒下的积蓄却是有限，不过身体倒是发福不少。熬不住思乡之苦下决心回乡时，他向伙伴借下八两金（金手表、金项链），又买大大小小物件若干好“衣锦还乡”。归家途中遭遇小波折，他借录“遗声”表达对父母、小妹的愧疚。到家猴子发现父母陪小妹去了乡下偷生政策不许的第二胎，在今成妹夫的儿时玩伴的陪同下，他见到童年时的拌嘴表妹乌嘴婆（张艾嘉），后者像其时的许多广东人一样想去香港或美国，不过比他们幸运的是，她已拿到赴美的“签证”——未来的husband在纽约唐人街开有一家餐馆，来年春天会接她赴美，不久猴子与携弟弟的乌嘴婆一起回到乡下。与父母、小妹话过相思之苦，猴子像许多多年不曾归乡的归乡客一样，被中国特有的世故人情害得哑巴吃黄连。猴子与乌嘴婆相处初期，讲话不忘夹带半生不熟的英文单词的乌嘴婆沉浸在对美国生活的浪漫幻想中，猴子不时泼去冷水，随着接触的深入，两人慢慢生出爱情，乌嘴婆渐渐不再提她的美国梦，但她的未来之路早已铺好，而猴子也在父母的安排下开始了相亲之旅。', '洪金宝', '张婉婷', 8.3, 14916, 'tt0099079', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553170357.jpg', 0.2, 0.8, 14.9, 50.6, 33.4, '0.158807,-0.111411,-0.665923,0.413372,-0.063165,-0.375553,0.527841,0.056343,-0.507977,-0.117076,-0.029498,0.692696,0.035182,0.374687,0.002941,-0.142026,-0.180224,-0.392804,0.185229,-0.130027,-0.057968,-0.168846,-0.109092,0.134055,-0.271045,-0.151500,0.339255,0.073889,0.052599,0.502740,0.030863,0.021076,-0.044114,0.341688,-0.421303,0.065394,-0.263735,0.413243,-0.376636,-0.046322,0.144583,-0.097755,-0.175550,-0.198497,0.220392,0.281210,0.635793,0.133903,-0.074311,-0.280139,0.249470,0.057783,-0.106022,0.037634,0.217269,0.194305,0.339635,0.094046,-0.131473,-0.072949,-0.065823,-0.072026,-0.203816,0.152364,0.079928,-0.069260,-0.680543,0.388266,-0.006130,0.031883,-0.109211,-0.516893,0.185872,0.282173,0.136591,0.498262,-0.046145,0.141958,-0.434075,0.410070,0.883639,0.010810,-0.037973,0.400141,-0.157865,-0.283021,0.228916,-0.242187,-0.445577,-0.033030,0.043239,-0.196103,-0.441421,0.194923,-0.520960,0.095389,-0.100457,-0.118002,0.219526,-0.351514,-0.080087,-0.384855,-0.049556,-0.654496,-0.255954,0.123031,0.318299,-0.165629,0.675954,-0.604829,0.308001,0.485851,0.408438,-0.515265,0.761080,0.0