INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300208', '姿三四郎', '剧情', '明治十五年，柔道爱好者姿三四郎（藤田进 饰），无意中目睹了门马党与修道馆之战。修道馆馆主矢野本五郎凭借一己之力，以柔道击败门马党众，令姿三四郎心悦诚服，拜其为师。然而，矢野觉得他生性好斗，出尔反尔，有意考验他的耐性。姿三四郎幸得老僧的 指点，抱树入水沉溺多日，终于领悟师傅教诲。在老师的调教下，姿三四郎的柔道突飞猛进，对门马党一战成名。此时，一位不速之客前来挑衅，姿三四郎正欲挺身而出，却被对方拒绝，相约后会有期。此后，姿三四郎遇到了美女小夜（轰夕起子 饰）并坠入爱河，却没想到比武对手竟是她的父亲——柔术大师村井（志村乔 饰）……©豆瓣', '大河内传次郎', '黑泽明', 7.5, 10448, 'tt0036400', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166773243.jpg', 0.6, 2.3, 36.5, 44.2, 16.3, '-0.171429,-0.017856,-0.103238,0.487896,0.035913,-0.402649,0.062392,0.062561,-0.326451,-0.758747,0.214908,0.290510,-0.084738,0.247857,0.249822,-0.432116,0.465447,-0.567939,-0.234245,0.127365,-0.056995,0.011277,0.215483,0.388756,-0.367145,-0.243811,0.280981,0.073964,-0.356347,0.465522,0.329669,0.392470,0.033547,0.231669,-0.017484,0.110844,-0.130404,0.106896,-0.247153,0.051156,-0.364578,-0.150854,-0.329251,-0.188707,0.158124,0.275698,0.591112,-0.031369,-0.113967,-0.144366,0.130232,0.172879,-0.007732,0.333128,0.543701,0.112411,0.204110,0.110184,0.066233,-0.087378,-0.039311,0.073569,-0.419446,0.038969,0.262483,-0.471495,-0.326786,0.219170,-0.141922,0.102969,-0.513697,0.073477,-0.405110,0.068994,0.333449,-0.223851,-0.062650,-0.263590,-0.265063,0.103090,0.417271,0.312393,-0.096618,0.237864,0.270598,-0.483083,0.110469,-0.400669,-0.015662,0.014542,0.188754,-0.064469,0.361804,0.108775,-0.248284,-0.274068,-0.450369,0.699674,-0.101271,-0.168612,0.041137,-0.280088,0.162146,0.013087,-0.407031,0.202697,0.511056,-0.478422,0.516447,-0.748079,0.063250,0.199422,0.227566,-0.059428,0.831981,-0.063471,-0.171984,-0.231580,-0.229791,0.288835,-0.034537,-0.119947,-0.023009,0.868206,-0.293130,-0.115501,-0.341593,-0.021394', '22964524', '1291564', '2046839', '1871817');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300211', '私恋失调', '剧情', '单身汉Barry Egan（亚当·桑德勒 Adam Sandler 饰）经营着一家小工厂，生活在七个姐姐压力下的他会不时地哭泣、用暴力来发泄情绪，乱砸东西。这天他在路上捡回了一个被人丢弃的小钢琴，还认识了一个女子。原来这个女子正是他的一个姐姐想要介绍给他认识的Lena Leonard（艾米丽·沃森 Emily Watson 饰），两人相约改天一起吃晚餐。夜里寂寞无聊的Barry拨打了一个色情电话，和电话里的女郎聊的不亦乐乎，却也惹上了麻烦：女郎付不起房租跟他借钱被拒绝后，便不断打电话骚扰他。Barry和Lena第一次约会后，两人情投意合。然而当Barry回到家的时候，却遭到了一伙人的打劫，原来是经营色情电话公司的Dean（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）派来的。当Lena在夏威夷出差的时候，Barry更破天荒地去夏威夷寻找她，两人确立了恋爱关系。当那伙人再次开车撞了Barry的车时，Lena受伤了，Barry终于爆发了......', '亚当·桑德勒', '保罗·托马斯·安德森', 7.9, 12979, 'tt0272338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189231848.jpg', 0.6, 2.9, 23.3, 47, 26.1, '0.360289,-0.024247,-0.665221,0.442242,-0.247911,-0.507355,0.695882,0.255882,-0.207959,-0.141312,-0.092862,0.860043,-0.270210,0.452860,0.397177,0.132744,-0.315670,-0.691891,0.165945,-0.043364,-0.245128,-0.262149,-0.068906,-0.144299,0.017488,-0.019218,-0.150389,-0.164487,-0.312465,0.592313,0.270220,-0.111425,-0.031643,0.762530,-0.421838,0.008802,0.234768,0.200255,0.151712,0.336266,0.102794,-0.491627,0.129396,0.068085,0.297271,0.531891,0.552920,0.024936,-0.038812,-0.084182,-0.047520,-0.092824,-0.001179,0.135189,0.199356,-0.002691,0.444296,-0.030273,-0.418235,-0.055435,0.206052,-0.010710,-0.512474,0.250218,-0.230747,-0.114761,-0.668271,0.546116,-0.033521,0.030601,0.065061,-0.430972,0.502366,0.364110,0.077568,0.345531,-0.081631,-0.005190,-0.497376,0.206465,0.694907,-0.110220,0.251323,0.428279,0.006085,-0.184484,0.201838,0.065506,-0.512220,-0.245222,0.534719,-0.227137,-0.321219,-0.148652,-0.729420,-0.058132,-0.296690,-0.112068,-0.105886,-0.494531,-0.206315,-0.565190,-0.061900,-0.297609,-0.395384,0.342624,0.058092,0.136549,0.522605,-0.628756,0.089879,0.722090,0.434853,-0.475808,0.674863,0.159131,-0.110834,-0.042170,0.170037,-0.147966,-0.004974,0.413038,0.289956,0.494205,-0.128861,0.001625,-0.512687,0.271323', '1361252', '30162520', '3326747', '1316560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300220', '莎翁情史', '剧情', '伊丽莎白一世时期的英国，处处有风花雪月的娱乐活动，然而莎士比亚（约瑟夫•费因斯 Joseph Fiennes 饰）此时却陷入了创作的枯竭期。他笔下的《罗密欧与海盗之女阿丝》因此搁浅。薇拉夫人（格温妮斯•帕特洛 Gwyneth Paltrow 饰）的出现可谓一石激起千 层浪。她酷爱话剧，不顾女人不能登台的世俗观念，不惜女扮男装前来参演莎士比亚的戏剧。莎士比亚洞悉了薇拉夫人的秘密。他从她身上强烈感受到创作的灵感，闻出爱情来到的味道。二人共坠爱海。他笔下开始有了罗密欧与茱丽叶熠熠生辉的故事。好景不长，薇拉要嫁入一个贵族人家。莎士比亚的创作如有神助，感情却陷入无望。但他还在努力用笔，用真情，去改写这一切。©豆瓣', '约瑟夫·费因斯', '约翰·马登', 7.3, 79167, 'tt0138097', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1201856136.jpg', 0.6, 4, 38.3, 43.2, 13.9, '0.441633,0.075058,-0.761851,0.746642,0.071233,-0.069272,0.970449,0.049846,-0.320010,-0.127221,0.394459,0.813123,-0.566529,0.095511,0.266297,0.095629,-0.375808,-0.924704,0.155860,-0.105162,0.224698,-0.349479,-0.089445,0.125937,-0.371195,-0.276798,0.716628,0.050948,-0.322061,0.414616,0.055731,0.251485,0.013951,0.385772,-0.057373,0.341763,-0.274350,-0.069203,-0.179604,0.097775,0.367866,-0.093667,-0.447385,0.169742,-0.091389,0.204540,0.612661,-0.530971,0.260928,0.312639,0.758854,-0.250627,0.079733,0.025400,0.132285,-0.060801,-0.161648,0.218051,-0.149970,-0.065614,0.070589,-0.198751,-0.719227,-0.028880,0.108277,0.259094,-0.488267,0.221700,-0.117828,0.053152,-0.065674,-0.044473,-0.060345,0.069641,0.319829,0.303951,0.002416,0.054256,-0.432026,0.272291,0.668590,-0.072646,-0.400790,0.719422,-0.335990,-0.400668,-0.196869,-0.420527,-0.590667,-0.087277,0.200999,0.082897,-0.098985,0.329057,-0.467512,-0.242554,-0.111673,-0.108786,0.110535,-0.241849,-0.240337,-0.440800,-0.530831,-0.299174,-0.172772,-0.091104,0.190418,-0.533586,0.728396,-0.616433,0.177640,0.349438,0.014846,-0.335147,0.800944,-0.069473,-0.187060,0.133476,-0.295624,0.619906,-0.202366,0.098179,0.158564,0.224346,-0.090453,0.102459,-0.357959,0.531419', '30162520', '1299663', '1291877', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300242', '安娜与国王', '剧情', '本片根据史事改编，与1956年的黛博拉•蔻尔与尤•伯连纳（女男主角）版本相比，重新诠释了寡居的英籍女教师安娜•里欧诺文与暹罗（泰国旧称）国王之间著名的爱情故事。19世纪60年代，安娜（朱迪•福斯特）携子来到暹罗，成为该国多妻多子的国王（周润发）家的家庭教师。起初，由于迥异的风俗文化，安娜遭遇了许多看似难以克服的困难，国王对她也近似“野蛮人”。随着两人的深入交往，尽管仍有许多不和谐存在，但他们逐渐赢得了互相的尊重，并碰撞出爱情的火花。©豆瓣', '朱迪·福斯特', '安迪·坦纳特', 6.8, 17971, 'tt0166485', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2191675270.jpg', 0.7, 7.1, 53.2, 30.7, 8.3, '0.637214,0.163013,-0.576839,0.490226,0.321145,-0.124007,0.752667,-0.051794,-0.429971,-0.379930,0.167328,0.714697,-0.299618,-0.295615,0.432942,-0.115464,-0.445764,-0.599596,0.095841,-0.241962,-0.035746,-0.566875,-0.249859,-0.073336,-0.449149,-0.393341,0.591870,-0.136133,-0.249518,0.607860,0.051713,0.305305,-0.146234,0.305624,-0.014851,0.098401,0.184058,0.046020,-0.475068,-0.085292,0.003333,-0.089932,-0.134697,-0.119689,-0.006096,0.407052,0.458747,-0.672964,0.218859,-0.157875,0.460704,0.135360,-0.253045,0.085938,0.230967,0.051970,0.307348,0.511969,-0.014371,0.004242,-0.125515,-0.213625,-0.458184,0.359319,0.455961,0.353203,-0.250968,0.557130,-0.011931,-0.330867,-0.011384,-0.128642,0.092922,0.355504,0.453122,0.473290,0.048100,0.080144,-0.346462,0.119504,0.830679,0.392095,-0.612294,0.070928,-0.592944,-0.762074,-0.189811,-0.169800,-0.415732,0.008885,0.148977,-0.027346,-0.034561,0.641050,-0.869342,-0.029836,-0.268508,0.049633,0.299759,-0.303295,0.139646,-0.825882,-0.300986,-0.847731,-0.064187,-0.172531,0.127846,-0.259998,0.977964,-0.927862,0.056486,0.220448,0.609716,-0.289391,0.638125,0.234671,0.004576,-0.356954,-0.338603,0.556896,0.003196,-0.154326,0.013780,0.378655,-0.040994,-0.097545,-0.109715,0.432362', '3811356', '25721544', '1303036', '1303010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300246', '我老婆未满十八岁', '喜剧', '刚刚成年的Yoyo（蔡卓妍饰）有众多的追求者，所以总是充满自信，觉得自己魅力非凡。她应父母的要求到英国跟指腹为婚的张十三（郑伊健饰）完婚。两人对这种荒谬的事情深感厌烦，却又无法违背长辈的意思，于是两人假扮结婚，一年后自动离婚。张十三把外婆的家传宝带到香港给Yoyo，Yoyo为了留下十三收取房租，便告诉十三到自己就读的女校任教，可以有助他为自己的硕士命题收集材料。十三帮Yoyo结识男孩子，Yoyo失恋，十三帮她治疗情伤，最终两人也发生了关系。相处多时后，两人恋上了彼此，但Yoyo的体育老师（廖碧仪饰）也爱上了十三，到底十三要如何选择呢？©豆瓣', '郑伊健', '阮世生', 6.5, 34957, 'tt0345685', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p954766619.jpg', 1.6, 10.8, 56, 23.9, 7.7, '0.223607,-0.068555,-0.598051,0.667912,-0.190243,-0.589214,0.375783,-0.071242,-0.464108,-0.294119,0.041099,0.551034,-0.057990,0.437862,0.122577,-0.019954,-0.041577,-0.672777,0.151334,-0.322775,-0.371741,-0.722863,0.013054,0.339642,-0.177443,-0.106315,0.348005,-0.064543,-0.163097,0.224903,0.282732,0.318279,0.001230,0.223664,-0.140144,-0.044048,-0.253002,0.478749,-0.270980,0.033594,0.120006,-0.123280,-0.234384,0.060622,0.239804,0.333796,0.529761,0.089638,-0.165276,-0.033607,0.212165,0.057062,-0.198815,0.216669,0.111236,0.067776,0.338034,0.390521,-0.237868,0.058571,-0.209431,0.105790,-0.578841,0.043243,-0.046868,-0.142817,-0.781736,0.245650,-0.151172,-0.131143,0.218305,-0.474167,-0.018456,0.397221,0.147924,0.341976,-0.173956,0.188155,-0.368829,0.101846,0.705904,-0.002452,-0.133956,0.216602,0.093618,-0.306536,0.002668,-0.285825,-0.311865,0.262213,-0.028049,0.312162,-0.134336,0.050276,-0.571828,-0.276542,-0.166390,-0.168831,0.154568,-0.342785,0.396806,-0.234127,-0.123232,-0.524221,-0.549862,-0.156506,0.474183,-0.397274,0.742407,-0.649497,0.367032,0.011000,0.320296,-0.918058,0.395587,0.493617,0.063850,-0.431243,-0.181449,-0.244639,0.010216,0.129936,0.298997,0.252134,0.148152,-0.234453,-0.508160,0.308300', '26730542', '1877596', '1301376', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300250', '太空异种', '剧情', '居住在休士顿的阿玛考斯特夫妇生活安逸幸福，妻子吉莉安（查理兹·塞隆 Charlize Theron 饰）是一名小学教员，丈夫史宾塞（约翰尼·德普 Jonny Depp 饰）则是供职于太空总署的宇航员。为了维修故障卫星，史宾塞和老搭档艾力克斯·史瑞克（Nick Cassavetes 饰）进入地球轨道。然而原本简单的任务却突发事故，故障卫星爆炸，导致两人与地球失去联系长达两分钟之久。所幸他们并无大碍，最终还是安全回到地球。在此之后，史宾塞和艾力克斯对那神秘的两分钟绝口不提，吉莉安也从他们的沉默中预感到什么。就在史宾塞决定辞职和妻子搬到纽约前不久，艾力克斯与妻子娜塔莉（Donna Murphy 饰）相继暴亡。吉莉安对此深感不安，她隐隐感到某些不祥的事件将发生在她和丈夫的身上……©豆瓣', '约翰尼·德普', '兰德·拉维奇', 6.3, 7033, 'tt0138304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1550495769.jpg', 2.4, 13.7, 56.2, 22.1, 5.6, '0.162861,-0.041986,-0.989377,0.291043,-0.014132,-0.343466,0.856744,0.046626,-0.501842,-0.593067,0.082513,0.772154,-0.356907,0.231642,0.336523,-0.030697,-0.460482,-0.536166,0.301786,-0.244894,-0.309628,-0.593846,-0.184268,-0.420170,-0.102821,-0.561303,0.554435,0.060888,-0.112633,0.522404,0.085263,0.574245,-0.401439,0.544938,-0.141113,0.044151,0.014748,-0.018705,-0.409774,0.138349,0.185350,0.075882,0.010825,0.003927,0.281970,0.431614,0.658843,-0.150882,-0.393212,0.106496,0.163280,-0.245935,0.136138,-0.033892,0.515381,0.047685,-0.248779,0.189737,-0.299645,0.234561,0.166257,0.069598,-0.406153,-0.122074,-0.182028,0.308367,-0.282765,0.468830,-0.474120,-0.431365,-0.005151,-0.244724,0.380371,0.592235,0.144668,0.395679,-0.123823,0.334102,-0.247647,-0.066917,0.699119,0.074243,-0.395571,0.400182,0.024049,-0.536359,-0.283990,0.055247,-0.383834,-0.021444,0.232768,0.096442,0.010677,0.397433,-0.397549,0.050316,-0.387789,-0.195774,-0.092268,-0.287905,0.224267,-0.657015,0.038326,-0.323747,-0.377343,0.122697,0.112557,-0.036254,0.246528,-0.831919,0.636940,0.322611,0.454268,-0.290870,0.372181,0.134141,0.308467,-0.399917,0.134386,0.371641,0.101136,0.493274,-0.033033,0.178922,0.090805,-0.082841,-0.454459,0.275713', '1302488', '1300958', '30137576', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300264', '至尊无上II之永霸天下', '剧情', '江湖中传说，有两块赌神玉牌，拥有者可以凭借玉牌召唤赌神帮助，逢赌必胜。八年前，范叔与徒弟詹永飞（王霄 饰）、鸡翼（刘德华 饰）、“亚洲第一快手”仇杰（王杰 饰）与人对赌，不料詹永飞背叛，导致范叔输掉了安身立命的豪华赌轮，并因高空坠落而下身瘫痪，仇杰也遭陷害入狱。八年后，范叔与鸡翼、小倩（吴倩莲 饰）在一艘小木船中开设赌局度日，每日为参加亚洲赌赛勤勉筹备，詹永飞获悉范叔拥有赌神玉牌，带人逼索使范叔身亡。出狱归来的仇杰面对范叔之死，只想过平常人生活意欲退出江湖，岂料詹永飞反复纠缠，设计先后令仇杰断臂、鸡翼目盲，忍无可忍的情况下，仇杰与鸡翼决定用赌来讨回公道……©豆瓣', '刘德华', '杜琪峰', 7.3, 11492, 'tt0108654', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2349425063.jpg', 0.8, 4.4, 39.2, 37.6, 18, '-0.445785,0.054544,-0.407381,0.093487,0.027610,-0.055919,0.373476,0.180364,-0.363315,-0.052970,0.331495,0.543356,-0.086488,-0.019877,0.359124,-0.202806,0.117175,-0.581568,0.011854,-0.084911,-0.214560,-0.282571,-0.139298,-0.062242,-0.252079,-0.061695,0.624882,0.036776,-0.142770,0.685317,0.354048,0.251601,-0.196714,-0.036522,-0.018579,-0.236056,-0.216491,0.381500,-0.663992,0.253706,-0.161261,-0.151694,0.001857,-0.021118,0.068126,0.116142,0.561840,-0.128048,0.086086,-0.471119,0.142082,-0.110192,-0.202978,0.003813,0.205352,0.279817,0.189440,0.338928,-0.159708,0.109341,0.257387,-0.115268,-0.446555,-0.029687,0.079838,-0.233143,-0.431492,0.243254,-0.182303,-0.087195,-0.220296,-0.132675,0.171592,0.207974,0.396983,0.017557,-0.099872,-0.284872,-0.360668,0.254702,0.295763,-0.089970,0.124350,0.021792,0.607402,-0.282687,0.253405,-0.371977,0.047125,0.082369,0.149103,0.119533,-0.054881,-0.050765,-0.296104,0.104517,-0.267388,-0.041146,0.270680,-0.158373,-0.000257,-0.438556,-0.216808,0.030374,-0.173710,0.073979,0.268125,-0.362654,0.285277,-0.539768,0.169579,0.040714,0.329538,-0.369755,0.419895,0.141828,0.277726,-0.158938,0.054962,0.106825,0.205312,0.229908,-0.118179,-0.207185,-0.002785,0.011556,-0.395317,0.016434', '1780122', '26365262', '1299790', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300265', '六指琴魔', '动作', '黄雪梅（林青霞 饰）的父母因保护“天魔琴”为六大门派追杀致死，小弟黄麟也失踪。她抱琴跳崖，重伤未死，并练得绝世之功“天龙八音”后出山报仇。她设计让欲夺“天魔琴”的武林人士自相残杀。在与飞虎镖局吕腾空义子吕麟（元彪 饰）交手中，雪梅发现他就是自己失踪的弟弟……©豆瓣', '林青霞', '吴勉勤', 7.2, 55357, 'tt0107428', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352113496.jpg', 0.5, 3.7, 43.4, 40.2, 12.3, '-0.087626,-0.211662,-0.654321,0.465491,-0.009184,-0.156656,0.309579,0.029213,-0.626349,-0.296682,0.458532,0.435456,0.161817,0.249638,0.257408,0.062358,0.429452,-0.821211,-0.029946,0.015898,-0.181438,0.235434,-0.082037,-0.141415,-0.141826,-0.203473,0.568724,-0.150234,-0.243044,0.653409,0.173035,0.290636,-0.525063,0.072852,-0.105274,0.243798,-0.328710,-0.091248,-0.139728,0.147701,-0.427243,-0.583639,-0.146709,0.298679,-0.329581,0.405883,0.405892,-0.071444,0.172383,-0.580089,-0.147849,-0.246750,-0.045532,-0.332506,0.513675,-0.049343,0.326466,0.363014,-0.227669,-0.078922,-0.212537,0.088508,-0.638627,0.317980,0.446431,-0.009582,-0.566764,0.513867,-0.351028,0.235919,-0.228386,-0.120118,0.030853,0.244590,-0.051712,0.055146,-0.139756,-0.196513,-0.607951,0.467818,0.506265,-0.586194,0.689643,-0.176415,0.679742,-0.170218,-0.010119,-0.592675,-0.021895,-0.097031,0.527101,-0.173418,0.142430,0.267992,-0.252094,-0.322111,-0.521948,0.476826,-0.389474,0.049760,0.048950,-0.228493,-0.040118,0.202770,-0.257286,-0.429299,0.107870,-0.378408,0.744927,-0.791032,0.258450,0.108830,0.075246,-0.806380,0.386231,0.086131,0.288122,0.085525,-0.112263,0.161311,0.273685,0.163208,0.212608,-0.024832,0.177536,0.077825,-0.185126,-0.080593', '35030151', '1295469', '1410695', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300266', '阳光下的罪恶', '悬疑', '阿伦娜·马歇尔（黛安娜·里格 Diana Rigg 饰）是一个美艳不可方物的女明星，天性放浪的她从不掩饰对其他男性的喜爱，也十分享受被男性追求的感觉，从而彻底忽略了丈夫和养女的感受。帕特里克（尼古拉斯·克莱 Nicholas Clay 饰）是个血气方刚的英俊小伙，虽然已经有了体弱多病的妻子克里斯汀（简·伯金 Jane Birkin 饰），但他依然难以抵挡向他暗送秋波的阿伦娜的诱惑。今年，位于莱瑟库姆湾旁小岛上的度假旅馆“快乐罗杰”成为了展示罪恶的舞台，来这里渡假的所有游客，似乎都和阿伦娜有个多多少少的利益纠葛。哪里有罪恶，哪里就有波罗（彼得·乌斯蒂诺夫 Peter Ustinov 饰），这次也不例外，聪明的他将一切矛盾都看在眼底。阿伦娜死了，这令众人毫不意外。尽管每个人都有作案的动机，但每个人又都有完美的不在场证明。究竟是谁杀了阿伦娜？其实凶手早早的，便露出了他狐狸尾巴。', '彼得·乌斯蒂诺夫', '盖伊·汉弥尔顿', 8.3, 44025, 'tt0083908', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173899536.jpg', 0.1, 0.6, 14, 54.4, 30.9, '0.449015,-0.351430,-0.596665,0.593478,-0.283457,-0.064877,0.812021,0.025263,-0.175559,-0.076284,0.106180,0.854510,-0.113052,0.257201,0.126898,0.612819,-0.517434,-0.552279,0.059160,-0.225697,-0.086797,-0.580071,-0.332293,-0.245446,-0.023189,-0.191997,0.288339,-0.036324,-0.050759,0.446170,0.442741,0.201167,0.284108,0.711476,-0.045622,0.030153,0.229833,-0.322366,0.357253,-0.122485,0.002697,-0.304282,-0.236081,0.563190,0.022245,0.633633,0.482826,-0.342310,0.010850,0.075836,0.300861,-0.328903,0.433060,0.305872,-0.000005,-0.547038,-0.076072,0.185628,-0.118225,-0.134460,0.385018,0.135222,-1.059943,0.180959,0.335824,0.080112,-0.399405,0.654368,-0.099608,-0.250782,-0.099155,0.013022,0.252242,0.092117,0.045235,-0.022195,-0.066581,-0.101300,-0.582817,-0.169823,0.583439,0.268361,-0.340188,0.304294,-0.614252,-0.614088,-0.257954,-0.248734,-0.517134,-0.000465,0.200369,0.219205,0.011818,0.228683,-0.409700,-0.040632,-0.294040,-0.162020,-0.111194,-0.575979,-0.135573,-0.495427,-0.271001,-0.781535,-0.622258,-0.165667,0.184121,-0.189236,0.766483,-0.780548,-0.090127,0.682267,0.172479,-0.514738,0.939194,0.016286,-0.150166,-0.120164,-0.199003,0.350339,0.026888,-0.000835,0.288445,0.586694,-0.011654,0.038657,-0.029722,0.759990', '35158375', '3785918', '1299362', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300267', '乱世佳人', '剧情', '美国南北战争前夕，南方农场塔拉庄园的千金斯嘉丽（费雯·丽 Vivien Leigh 饰）爱上了另一个农场主的儿子艾希礼（莱斯利·霍华德 Leslie Howard 饰），遭到了拒绝，为了报复，她嫁给了自己不爱的男人，艾希礼妻子梅兰妮（奥利维娅·德哈维兰 Olivia de Havilland 饰）的弟弟查尔斯。战争期间，斯嘉丽成为寡妇，失去母亲，挑起生活的重担， 不再是当初的千金小姐；战争结束后，她又两度为人妻，嫁给了爱她多年的投机商人瑞德（克拉克·盖博 Clark Gable 饰）。然而，纵使经历了生活的艰苦，斯嘉丽对艾希礼的感情仍然没有改变。艾希礼妻子梅兰妮的去世，给了斯嘉丽一个机会，一边是深爱自己的丈夫瑞德，一边是心心念念多年的艾希礼？斯嘉丽会给自己怎样一个不一样的明天？©豆瓣', '费雯·丽', '维克多·弗莱明', 9.3, 645054, 'tt0031381', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1963126880.jpg', 0.1, 0.3, 4.3, 25.2, 70.1, '0.189919,0.172898,-0.653426,0.697910,-0.367715,-0.710926,0.743797,0.078206,-0.332045,-0.311723,0.089251,0.906064,0.126405,0.184863,0.137563,0.518011,-0.461157,-0.673726,0.171476,0.169041,-0.237809,-0.419190,-0.000928,-0.332121,-0.009721,-0.316818,0.600081,-0.042917,0.122118,0.185488,0.508719,0.480035,0.429502,0.330144,-0.013354,0.275653,0.157295,0.052653,-0.473943,0.375159,0.099467,0.008862,-0.000336,0.366044,-0.055078,0.303373,0.517825,-0.217503,0.203384,-0.565550,0.458040,-0.241748,-0.061057,0.166400,0.130613,-0.341738,0.131982,0.271902,-0.315293,-0.349835,0.313902,-0.181409,-0.482205,-0.164502,0.068890,0.102717,-0.718349,0.651710,-0.377366,0.034275,0.052847,-0.275140,-0.025952,0.507110,0.152486,0.185729,-0.331346,0.141503,-0.558207,0.375768,0.886688,0.181901,0.010424,0.396025,-0.424099,-0.196028,0.170862,-0.497176,-0.893503,0.057625,0.119873,-0.176802,-0.259065,0.504529,-0.332289,-0.159917,-0.608840,-0.047809,0.437262,-0.585774,-0.253027,-0.203322,-0.143140,-0.544790,-0.483642,0.003158,-0.163552,-0.390223,0.598793,-0.879861,0.353734,0.432098,0.397049,-0.643246,0.623387,0.291976,0.206451,-0.422327,0.353953,0.596269,-0.224322,-0.200547,0.100795,-0.044084,0.088872,0.076778,-0.073255,0.672735', '1292720', '30345227', '2075721', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300275', '大开眼戒', '剧情', '医生威廉姆(汤姆•克鲁斯 Tom Cruise 饰)携太太(妮可•基德曼 Nicole Kidman 饰)参加他的一位主顾――当地一个名流――家里举行的晚会时，巧遇了他的一位大学同学－－在晚会上担任钢琴师的尼克。当晚，威廉姆因公外出。料理完公事后，他在一家酒吧再次遇到了尼克，尼克告诉了他有这样一个秘密舞会：在舞会上，所有的人都穿着晚礼服，戴着面具，到处都是裸体的美女。威廉姆禁不住好奇，再三乞求尼克，尼克告诉了他举行那个舞会的地址和入门的暗语。威廉姆匆匆准备后，展开了一次如幻如梦的冒险之旅。过程充满了诡异和神秘，背后的玄机更是令人无法参透。©豆瓣', '汤姆·克鲁斯', '斯坦利·库布里克', 8, 138754, 'tt0120663', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1708137969.jpg', 0.4, 2.2, 22.5, 45.7, 29.2, '0.374182,0.059053,-0.674878,0.344677,-0.048398,-0.341949,0.469389,0.083371,-0.506244,-0.381035,0.402311,0.887619,-0.348836,0.443504,0.566318,0.072702,-0.643671,-0.607523,0.168209,-0.135612,-0.490376,-0.336543,0.186365,-0.260953,0.083797,-0.332153,-0.131974,0.043938,0.106289,0.886481,0.466037,0.321672,0.177479,0.476785,-0.084751,-0.217119,0.541302,-0.065680,-0.047987,0.503006,0.152224,-0.054920,-0.379689,0.183591,0.196569,0.356954,0.590096,-0.203081,0.093284,0.154519,0.353919,-0.123817,0.028026,0.186215,0.192485,0.051156,0.087549,0.231230,-0.297386,-0.051107,0.181853,-0.100271,-0.479689,0.004072,-0.063399,0.523204,-0.409354,0.389494,-0.127593,0.043891,0.117902,-0.500252,0.195273,0.105921,0.153307,-0.072877,0.263978,0.144651,-0.452572,0.370321,0.624853,0.284019,0.096427,0.038670,-0.361681,-0.403944,0.019297,0.139511,-0.534186,0.157816,0.344791,-0.395921,-0.007867,0.084939,-0.641176,-0.458476,-0.152992,-0.263966,-0.087931,-0.095861,-0.170524,-0.910721,0.024475,-0.129741,-0.233947,0.015181,0.120447,0.077001,0.462228,-0.804486,0.407074,0.501486,0.114655,0.088235,0.822001,0.017137,0.350640,-0.056048,-0.319467,-0.029632,0.096955,0.361968,-0.053913,0.736195,0.222402,-0.105922,-0.445601,0.332637', '25833539', '3178770', '4319218', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300282', '异次元骇客', '科幻', '十三，一个听起来就有些阴冷的数字。在一座大厦的第十三层，科学家道格拉斯•霍尔（克雷戈•比克饰）和汉农•富勒（阿明•缪勒－斯塔尔饰）用电脑模拟出一个逼真的1937年的洛杉矶，他们可以通过电脑进入这个虚拟世界，真实地体验1937年的生活与自己。然而一个夜里，富勒被人杀死，种种线索都表明似乎是霍尔所为。可霍尔却对当天夜里的事情全无记忆。这时一个自称是富勒女儿的女人又神秘出现，可霍尔从未听富勒说过自己有女儿……为了找到凶手明晓真相，霍尔循着富勒留下的线索来到虚拟世界中，他离真相越来越近了……近到窒息……©豆瓣', '克雷格·比尔克', '约瑟夫·鲁斯纳克', 8.4, 100850, 'tt0139809', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1932438619.jpg', 0.2, 1, 13.6, 48.9, 36.4, '0.332502,0.047550,-0.828051,0.708290,-0.404092,-0.319632,1.119247,-0.267764,-0.722262,-0.486821,0.105921,0.803941,-0.420322,0.125946,0.368925,0.414341,-0.303935,-0.597048,0.213589,-0.401495,-0.122963,-0.691759,-0.367968,-0.337815,0.004891,-0.222162,0.362151,0.210282,-0.098275,0.180510,0.107649,0.201140,-0.047854,0.599560,-0.069324,0.052232,0.255043,0.070635,-0.022666,0.070655,-0.014681,-0.140838,-0.217427,0.284567,-0.388020,0.378509,0.278159,-0.205813,-0.147769,0.223642,0.223083,-0.144356,-0.220130,0.170874,0.188662,-0.028593,0.054443,0.249127,-0.386852,0.051524,-0.123324,0.134494,-0.934335,-0.058925,-0.101087,0.287622,-0.325554,0.069018,-0.551584,-0.158612,0.147188,-0.472704,0.274394,0.137979,0.372105,0.523193,-0.335820,-0.121753,-0.684919,-0.107631,0.521996,-0.089217,-0.261844,0.226493,-0.023117,-0.491567,-0.176823,0.062816,-0.247672,0.067588,0.105846,0.075018,-0.337839,0.324102,-0.537833,-0.014524,-0.453753,-0.572714,-0.015752,-0.337233,-0.313832,-0.392966,-0.316490,-0.217521,-0.424621,0.071330,-0.050971,-0.519324,0.565240,-0.658934,0.328727,0.494580,0.218134,-0.159210,0.587221,0.108341,0.066045,-0.329912,-0.032360,0.354667,0.182083,0.410356,0.145172,0.380453,0.017727,-0.249072,-0.511492,0.629642', '25909236', '1417428', '3569911', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300288', '惊魂记', '惊悚', '女律师林楚翘（林青霞 饰）即将移民加拿大，却在临行前收到一封恐吓信。信中威胁林支付100万，否则将其伪造假遗书的丑行公之于众。林经过一番试探，怀疑为其亲信阿May（王小凤 饰）所为。阿May早年随林打拼，如今却因学历问题而无法移民，怀恨在心的她发出恐吓信。在被林怀疑后，她悬崖勒马，决定收手。另一方面，阿May的室友阿群（王祖贤 饰）有一个蹲狱三年的双胞胎妹妹阿Cat（王祖贤 饰）。阿Cat欠下他人钱财，性命不保。为了筹得钱款，阿群在阿May的帮助下潜入林楚翘的别墅偷盗现金100万。阴差阳错，当晚适逢林在家中，撕扯中阿群被误杀，而这一切都被尾随前来的阿Cat看在眼里。事情开始朝着不可预测的方向发展……©豆瓣', '林青霞', '钟志文', 7.4, 5684, 'tt0097623', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2529748224.jpg', 0.5, 3.5, 35.9, 45, 15.1, '-0.126877,0.312780,-0.616504,0.726824,0.070019,-0.495717,0.455765,0.194947,-0.206424,-0.517000,-0.024776,-0.060143,0.033717,0.128106,0.200831,-0.420104,-0.161959,-0.378038,-0.112326,-0.452830,-0.269213,-0.333639,0.112412,-0.378447,-0.535962,-0.231547,0.213650,0.230791,-0.407840,0.214696,0.688358,0.405512,-0.142839,0.353058,-0.034458,0.145893,-0.219647,0.157778,-0.374657,0.285145,0.398884,-0.425950,0.050262,0.057136,0.144532,0.371201,0.993561,-0.259563,-0.225887,-0.295072,0.604658,-0.065624,0.312758,0.132182,0.547765,0.187521,-0.161891,0.008837,-0.475493,-0.098225,0.643963,-0.143323,-0.394636,-0.423315,0.312654,-0.027763,-0.503712,-0.213113,-0.453331,0.386957,-0.199375,-0.323299,0.060615,0.725201,0.343053,-0.039763,0.095843,0.258500,-0.375960,0.340281,0.604020,-0.064370,0.468255,-0.095091,-0.405565,-0.743584,0.171717,0.258374,-0.259059,0.282469,0.568884,-0.146586,0.265642,0.285911,0.017922,-0.418269,-0.307184,0.070847,-0.234498,-0.545892,0.153750,-0.348450,-0.066857,0.087985,0.082029,0.317320,0.296409,-0.157389,0.201948,-0.271434,0.256665,0.333236,0.500252,-0.482862,0.313368,-0.101139,-0.031678,-0.521443,-0.126342,0.300346,0.520168,0.203330,0.280944,-0.083232,0.074674,-0.074733,-0.159320,0.255997', '1303148', '1295344', '35327724', '1944900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300292', '谍海计中计', '动作', '詹姆斯（柯林·法瑞尔 Colin Farrell 饰）以优等生的身份顺利通过中情局的初期审查，和其它精英学子一起进入训练基地接受特种训练。中情局派出了最有经验的王牌特工沃特（阿尔·帕西诺 Al Pacino 饰）来训练这群年轻人。在近乎冷血的各式各样的残酷训练当中，表现最佳的詹姆斯却莫名被淘汰出局。在新人中，女学员莱拉（布丽姬·穆娜 Bridget Moynahan 饰）引起了上层的怀疑。被怀疑是个敌对情报组织派来的卧底。于是，在训练中和莱拉关系甚好的詹姆斯被悄悄安排了反卧底工作。詹姆斯开始刻意接近莱拉，打探情况。但随着两个人的相处，他竟对不知道敌友的莱拉情愫。在国家的荣誉与个人的情感面前，詹姆斯那苦恼的心，又要如何去抉择呢？©豆瓣', '阿尔·帕西诺', '罗杰·唐纳森', 7, 19828, 'tt0292506', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p854752982.jpg', 0.5, 4, 47.1, 39.9, 8.5, '0.479396,-0.119685,-0.612118,0.750899,-0.172097,-0.112598,0.418728,-0.048084,-0.704556,-0.412252,0.266789,0.572072,-0.131551,-0.106004,0.340934,-0.359027,-0.378809,-0.802609,-0.298548,-0.271537,-0.459678,-0.590559,-0.343219,-0.230582,-0.077691,-0.291755,0.667130,-0.115072,-0.337263,0.459428,0.381074,0.380804,0.052580,0.352277,0.074809,-0.270373,0.610948,-0.234026,-0.081141,0.254605,-0.014759,-0.079106,-0.155227,-0.023614,0.332940,0.531222,0.619501,-0.196933,0.068082,0.017753,0.237450,-0.335127,-0.022205,0.364400,0.528726,0.050961,-0.101959,0.156018,-0.047149,0.295732,-0.166387,-0.095849,-1.039729,0.004763,0.183676,0.237615,-0.781691,0.351184,-0.131201,-0.110243,0.090590,-0.084463,0.166134,0.460748,0.275636,0.354703,0.002240,-0.215013,-0.335037,0.004760,0.733846,-0.019776,-0.184661,-0.044876,-0.385376,-0.587648,-0.004205,-0.375500,-0.315336,-0.164274,0.242720,-0.017799,-0.007366,0.371234,-0.566930,-0.037966,-0.089399,-0.171586,-0.342231,-0.617869,0.198675,-0.884931,-0.225368,-0.451006,-0.463676,0.063562,0.060528,-0.259424,0.780884,-1.089260,0.034019,0.618318,0.301098,-0.650851,0.465857,0.249929,0.192687,-0.396888,-0.246730,0.163759,0.306002,0.123535,0.078727,0.599418,-0.061149,-0.473336,-0.217801,0.206669', '1793491', '1420088', '20388224', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300295', '天若有情2之天长地久', '动作', '大陆女子小倩（吴倩莲 饰）为了把弟弟从监狱中搭救出来，远赴香港准备卖身筹钱，不料却卷入黑社会大哥被杀一案，小倩从事发现场卷款逃走，黑社会内的真正凶手对小倩下达了追杀令。慌不择路的小倩将老警员彪叔（关海山 饰）打伤，逃到了赛车场，摩托车手阿富（郭富城 饰）助小倩脱离险境，又将其收留在家中。阿富本是富家公子，因酷爱赛车造成母亲车祸身亡，导致他和父亲（秦沛 饰）的关系疏远，独自在破败楼层中居住，每晚在赛场上挥洒孤独的青春。在警局遭受嘲笑的彪叔为了挽回同侪尊重，出力寻找小倩的下落，同时黑社会方面也渐渐逼近了阿富和小倩的所在。这天，在赛场上遭受搭档背叛的阿富回家时发现，他的家已经被黑社会付之一炬……©豆瓣', '郭富城', '陈木胜', 6.8, 6966, 'tt0105589', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2351325884.jpg', 1.4, 8.7, 51.1, 27.6, 11.3, '0.151625,0.141446,-0.542646,0.127600,-0.122690,-0.169720,0.450197,0.170756,-0.394687,-0.140264,0.427559,0.751309,0.053850,0.182905,0.126707,0.032566,-0.089051,-0.651912,-0.093043,-0.209260,-0.293792,-0.461973,0.059538,0.256010,-0.055622,-0.237446,0.360827,-0.023924,-0.347334,0.863915,0.216914,0.278033,-0.316697,0.472199,-0.138198,0.312135,0.028744,-0.002148,-0.220584,0.111102,0.099660,-0.404553,0.078836,-0.077351,0.094722,0.314904,0.723588,0.043800,-0.088946,-0.272435,0.334636,-0.188786,0.035368,0.057411,0.583998,-0.009072,0.073188,0.367147,-0.292943,-0.144590,0.139604,0.045272,-0.507477,0.082431,0.348373,-0.059458,-0.756819,0.448264,-0.059829,-0.085606,0.165068,-0.222621,0.429063,0.352220,0.053915,0.291984,-0.287122,0.008522,-0.549016,0.209664,0.783877,-0.323762,0.285804,-0.040097,0.194663,0.001814,0.245532,-0.346904,-0.356821,-0.027933,0.312497,-0.152830,-0.433398,0.072930,-0.327154,-0.108968,-0.247337,0.028498,-0.099944,-0.276201,-0.297407,-0.480930,-0.238953,-0.136670,-0.007644,-0.014658,-0.205176,-0.150228,0.405103,-0.627375,0.269437,0.528312,0.656825,-0.442306,0.685309,-0.123357,0.132723,-0.010197,-0.274292,0.071299,0.370401,0.476469,0.182303,-0.039733,-0.336069,-0.092411,-0.252635,0.046579', '1451563', '25908042', '1897368', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300299', '杀人回忆', '剧情', '1986年，韩国京畿道华城郡，热得发昏的夏天，在田野边发现一具女尸，早已发臭。小镇警察朴探员（宋康昊饰）和汉城来的苏探员（金相庆饰）接手案件，唯一可证实的是这具女尸生前被强奸过。线索的严重缺乏让毫无经验的朴探员和搭档曹探员（金罗河饰）只凭粗暴逼供和第六感推断，几次将犯罪 嫌疑人屈打成招。而苏探员客观冷静，据理分析，几次排除嫌疑，警察内部为了证明与推翻矛盾不断，然而无辜女子还是接二连三被残忍杀害，他们只好达成共识一起合作。此时，一个极其符合作案特征的小青年（朴海日饰）成为最大嫌疑人，警方神经绷紧地锁定住他，同时DNA检测报告也被送往美国，然而案件并未在此处停止。©豆瓣', '宋康昊', '奉俊昊', 8.9, 653810, 'tt0353969', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1633113220.jpg', 0.2, 0.6, 7.6, 37.7, 53.9, '0.302526,-0.143801,-0.367729,0.437774,-0.156404,0.125271,0.639953,-0.243284,-0.825938,-0.441027,0.030161,0.302751,-0.236916,0.095326,0.254459,-0.233007,-0.133772,-0.784205,-0.177060,0.044984,-0.483465,-1.042419,-0.142237,-0.520879,-0.091892,-0.176655,0.552557,0.284902,-0.454421,0.305474,0.299693,0.316270,-0.395511,0.489228,0.033248,-0.222538,0.215748,-0.457872,-0.199745,0.192658,0.389800,-0.421674,0.156211,0.158147,-0.078559,0.693766,0.509453,-0.156575,-0.400093,0.057324,0.388357,-0.460766,0.007910,0.154112,0.725007,-0.007722,0.165541,0.215165,-0.250965,-0.339257,0.215788,0.058943,-0.626123,-0.187311,0.269738,0.080306,-0.261083,0.183515,-0.122230,0.323937,-0.027827,-0.232636,0.235450,0.356915,0.447776,0.130892,-0.054233,0.069174,-0.325533,0.049491,0.550914,0.237615,-0.147178,-0.104641,-0.319003,-0.733940,-0.192890,-0.289021,0.117500,0.107946,0.163367,0.051342,-0.270334,0.032439,-0.265404,-0.262883,-0.366961,-0.106679,-0.094125,-0.180274,0.212588,-0.478073,-0.257451,-0.017436,-0.122304,0.293077,-0.093456,-0.279143,0.311309,-0.585788,-0.069462,0.434572,0.265093,-0.541936,0.375699,0.024050,0.013239,-0.397002,-0.089815,0.229941,0.762763,0.266062,0.542115,0.197047,-0.355017,-0.113039,-0.240897,0.036969', '1296217', '3263169', '1305053', '4132395');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300300', '死神来了', '惊悚', '剧情惊险恐怖，环环相扣。高中生艾利克斯-伯朗宁（德文•萨瓦 Devon Sawa  饰）与7名同班同学登机前往巴黎。起飞前，他突然预感到恐怖的一幕：飞机将会在空中爆炸。艾利克斯非常惊恐，大喊飞机即将出事，大家要立刻下机，结果混乱中他和其余6名乘客被机组人员赶了出来。但是，被艾利克斯不幸言中，飞机在半空中爆炸，全部人员罹难。所有下了机的人都在庆幸大难不死，却不知死神还是不愿放过他们。接下来，等待他们的将会是更恐怖的死亡方式和更难逃脱的死亡命运。而艾利克斯又能从各人的死亡顺序里面发现什么秘密，在死神的魔爪中逃出生天？©豆瓣', '戴文·萨瓦', '黄毅瑜', 7.9, 309981, 'tt0195714', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2867790676.jpg', 0.3, 1.8, 24.6, 50, 23.3, '0.469783,0.149742,-0.965419,0.256512,0.313306,0.044869,0.608388,-0.343345,-0.514106,-0.207300,0.619063,0.835991,-0.558154,0.053635,0.097136,-0.002311,-0.270636,-0.627407,-0.179420,-0.451880,-0.736320,-0.262898,-0.218888,-0.271290,-0.060306,-0.156881,0.450475,0.336730,0.221371,0.435628,0.143680,0.392841,-0.145181,0.575063,-0.231306,0.165342,-0.023699,-0.342406,-0.075009,0.171073,0.168165,-0.271074,-0.273332,0.461840,0.068119,0.331859,0.717073,-0.401076,-0.123213,0.237667,0.221964,-0.508843,-0.021351,0.345872,0.465185,-0.204361,0.014952,0.025977,-0.067451,0.183461,-0.008244,0.224857,-0.549151,-0.001642,-0.379162,0.286186,-0.374110,-0.022191,-0.270540,0.103000,0.373419,-0.332314,0.289688,0.149224,0.239760,0.453340,-0.171394,-0.383272,-0.323895,-0.135412,0.805710,-0.113831,-0.389720,0.380980,-0.232291,-0.497434,-0.459960,-0.262538,-0.444497,0.170523,0.710532,0.498771,-0.115860,0.596809,-0.482014,-0.053161,-0.349456,-0.030683,-0.672721,-0.416083,-0.245398,-0.552924,0.147682,0.022277,-0.142944,0.620928,0.051136,-0.101871,0.663510,-0.542206,0.161235,0.581757,0.270226,-0.186480,0.315064,-0.019274,0.041042,0.093043,0.177433,0.105710,0.121066,0.468336,0.215780,0.485765,-0.193260,-0.089218,-0.400122,0.199125', '3011051', '4919019', '4832825', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300303', '我是谁', '喜剧', '三名科学家在非洲大陆发现了一种神秘的矿石，这种矿石具有极强的杀伤力。就在这三名科学家携带矿石返回的途中，美国中央情报局派出了由11名来自不同国家的特种兵组成的特别行动小队将科学家和他们成果劫持了。情报局内部出现了内鬼，想把这一成果据为己有。于是，他命令负责接应的飞行员制造了一次空难，以此来杀人灭口和掩饰其已夺取了成果。特别行动小队几乎全军覆灭，只有队员杰克（成龙 饰）侥幸逃生。当杰克被当地的土著救活时，他因剧烈的碰撞而丧失了所有记忆，自己的名字、来历通通都一无所知。他逢人只会问“我是谁”。为了查明自己的身世，杰克回到了纽约……©豆瓣', '成龙', '陈木胜', 7.7, 141482, 'tt0127357', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2002166139.jpg', 0.3, 1.9, 29, 48.5, 20.3, '0.183956,-0.152328,-0.796167,0.596772,-0.389269,-0.072016,0.578641,-0.270348,-0.652257,-0.264149,0.216604,0.736369,0.138479,-0.142043,0.054808,-0.128851,-0.311774,-0.540851,-0.147802,-0.387260,-0.489205,-0.416893,-0.296710,-0.331554,0.107843,-0.438114,0.523554,0.087156,-0.445645,0.231222,0.093468,0.448049,-0.063468,0.534597,-0.066442,-0.023853,0.181094,-0.351635,-0.065766,0.205038,-0.156277,-0.287543,0.044044,0.274003,-0.165755,0.473960,0.784538,-0.408179,-0.039564,-0.222516,0.105431,-0.478430,0.067297,0.000051,0.320780,0.250519,-0.020637,0.110694,-0.166271,0.051477,0.090688,0.166224,-0.990550,-0.100210,0.163011,0.071688,-0.673055,0.244709,-0.188150,0.192250,0.065769,-0.247861,0.403022,0.436618,0.057335,0.168973,-0.026197,-0.156729,-0.617173,0.234163,0.820646,-0.425690,-0.215262,-0.022327,-0.165752,-0.624046,-0.161387,-0.231792,0.054579,0.000800,0.453907,0.194332,0.007492,0.037833,-0.747077,0.030849,-0.193959,-0.292662,-0.234413,-0.405844,-0.044372,-0.604160,-0.001591,0.041665,-0.284449,0.049309,0.143401,0.015749,0.904087,-0.702091,-0.026699,0.651577,0.292335,-0.656901,0.261210,-0.152352,0.051968,-0.281277,-0.130089,-0.016263,0.372945,0.574034,0.141877,0.400347,0.205817,-0.259836,-0.359783,0.115871', '30163500', '25928048', '1793491', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300306', '一个国家的诞生', '剧情', '美国南北战争时期，南方庄园主卡梅伦一家原本过着安逸的生活。卡梅隆和斯通曼家的孩子同在一所寄宿学校念书，接触中，年轻的本杰明·卡梅隆（亨利·B·沃斯奥 Henry B. Walthall饰）和埃尔西·斯通曼（丽莲·吉许 Lillian Gish饰）互生情愫。然而不久南北战争爆发。本杰明参加了南方军队，奔赴前线，与北方的昔日好友斯通曼（拉尔夫·李维斯 Ralph Lewis饰）成了敌手。战后，黑人烧杀抢掠。本杰明组织三K党，对黑人进行报复，粉碎了建立所谓的“黑人王国”的阴谋。本杰明与埃尔西这对患难情侣也终于走到了一起。他们的结合，预示着一个新的国家的诞生和统一。这部由美国电影巨匠D·W·格里菲斯编导的长达三个多小时的鸿篇巨制《一个国家的诞生》，是世界电影史上最重要的里程碑式电影，也是默片时代的经典之作。本片因为对白人优越主义的提倡，以及对三K党的美化而颇具争议性。', '丽莲·吉许', '大卫·格里菲斯', 7.9, 9795, 'tt0004972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1827536032.jpg', 2.1, 2.9, 21.1, 46.4, 27.6, '0.438901,-0.162170,-0.684902,0.698449,0.221462,-0.243030,0.759647,-0.000378,-0.254179,-0.218147,0.097263,1.060699,-0.221300,0.222110,0.438415,-0.130619,-0.284765,-0.769475,-0.258980,-0.131754,-0.118300,-0.501289,-0.454753,-0.250790,-0.104483,-0.380968,0.831396,0.169352,-0.258255,0.429816,0.254512,0.331114,-0.045296,0.108298,-0.165308,-0.089560,0.094315,-0.002984,-0.576782,0.269508,-0.081511,-0.040741,-0.195143,0.043065,-0.134863,0.280394,0.450917,-0.277648,0.092776,-0.423449,0.473414,-0.143807,-0.406172,-0.034374,0.443779,0.062297,0.317778,0.446632,0.149364,-0.084173,-0.070739,-0.332937,-0.691223,0.090827,0.117748,0.085826,-0.642383,0.702592,0.072235,-0.328806,-0.049169,-0.087361,0.275823,0.604132,0.288699,0.483981,0.032533,0.098129,-0.456759,0.324205,0.484388,-0.061895,-0.499783,0.176835,-0.164193,-0.523096,-0.197150,-0.452579,-0.508729,-0.125802,0.178877,-0.373367,-0.025931,0.128097,-0.862915,0.172224,-0.122699,-0.348992,0.280574,-0.286596,0.049070,-0.845281,-0.235435,-0.634821,-0.280176,0.014258,0.217370,-0.132520,1.006484,-0.763017,0.136386,0.342245,0.459077,-0.527038,0.762633,0.149352,0.207588,-0.484526,-0.143497,0.314149,-0.113031,-0.002761,0.022256,0.322748,-0.008392,-0.137894,-0.302418,0.528843', '187