INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300317', '烈火战车2：极速传说', '动作', '生性高傲的Sky（郑伊健 饰）仗着母亲与继父的不俗地位到处闯祸。一直以来他都热爱赛车。在他眼里就只有自己的女友阿希（林熙蕾 饰）和两位好友趴地熊（谭耀文 饰）、谢贤（林晓峰 饰）。Sky与丧偈（陈豪 饰）结怨，丧偈的哥哥（任达华 饰）是一代车神，来挑战Sky，比赛中不堪落后的Sky失手翻车，女友当场死去。Sky强忍失去爱人的痛楚，逃到外地躲过仇人的追杀，到泰国寻找自己的亲生父亲（柯受良 饰），当年父亲车神的风采不再，令他相当失望。幸得一直暗恋他的凉子（张栢芝 饰）在旁鼓励照顾，但趴地熊的死去，彻底让他改变了。©豆瓣', '郑伊健', '刘伟强', 6.6, 8042, 'tt0234105', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2354868018.jpg', 1.6, 9.3, 56.3, 23.3, 9.5, '-0.035092,-0.116492,-0.684889,0.562337,0.054295,-0.232204,0.669769,0.033288,-0.461461,-0.228208,0.323795,0.704913,0.001748,0.484110,0.059841,-0.131585,0.184271,-0.585754,-0.094038,0.219255,-0.159472,-0.227873,-0.401338,0.014292,-0.359168,-0.233046,0.597457,-0.036217,-0.223874,0.691765,0.496983,0.343447,0.022014,0.382770,-0.237183,0.238599,-0.333101,0.264471,0.012996,-0.023557,0.114557,-0.356693,-0.084010,0.344858,0.074686,0.401784,0.585431,-0.252499,-0.038422,-0.301619,0.182475,-0.300117,0.034787,0.240090,0.217245,-0.188318,0.331773,0.278892,-0.195948,0.048813,0.167846,0.109485,-0.552188,-0.007920,0.304738,0.067769,-0.826657,0.515981,-0.252667,0.062826,0.190576,-0.214626,0.163787,-0.059125,-0.145166,0.342487,-0.370983,0.050413,-0.397959,0.346862,0.592702,-0.109373,0.106095,0.017633,0.079854,-0.311393,-0.087829,-0.543444,-0.689885,-0.027401,0.131858,-0.134462,-0.130194,0.092118,-0.411072,-0.218623,-0.119737,0.184076,-0.174643,-0.357412,0.084770,-0.261773,0.022937,-0.735208,-0.294913,0.102166,-0.038383,-0.547860,0.662282,-0.699085,0.197411,0.167558,0.108293,-0.711126,0.620219,0.241162,0.029655,-0.196097,-0.115209,0.611085,0.149022,-0.219045,-0.012071,-0.001803,-0.093759,0.148816,-0.338786,0.450182', '3111650', '3445516', '35030151', '26921076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300324', '007之八爪女', '动作', '这次007（罗杰•摩尔 Roger Moore 饰）的任务是追寻真正的法布尔金蛋，在追踪过程结识了美丽的马戏团女郎“八爪女”（莫德•亚当斯 Maud Adams 饰）。007在“八爪女”的房间找到了重要的证据，从而揭露了苏联的一个大阴谋。原来苏联以走私珠宝的名义和“八爪女”合作，其实暗中企图利用“八爪女”的马戏团巡回表演时当场引爆核弹。007深知事态严重，他必须在苏联引爆核弹前阻止他们的阴谋，他费尽千辛万苦在人群拥挤的马戏团里终于找到核弹并将它拆除。随后，“八爪女”不小心被抓走了，为了朋友，007将只身闯虎穴！©豆瓣', '罗杰·摩尔', '约翰·格兰', 6.8, 7787, 'tt0086034', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1725339245.jpg', 1, 6, 53.8, 29.1, 10.1, '0.022801,0.182925,-0.460568,0.289988,-0.177719,0.164584,0.544785,-0.023694,-0.141136,0.100353,0.381482,0.717663,0.005874,-0.109593,0.002400,0.081603,-0.332267,-0.311523,-0.278994,-0.228697,-0.342466,-0.321165,-0.303796,-0.109047,0.157302,-0.348708,0.480838,0.049150,-0.321140,0.150512,0.584427,0.344230,-0.285240,0.233228,-0.227741,-0.152378,0.432581,-0.054910,-0.093375,0.228534,-0.233365,-0.270696,-0.058334,0.160736,-0.034095,0.312737,0.683683,-0.469631,0.064076,-0.299149,0.177085,-0.411141,0.295050,0.067320,0.171156,-0.043778,0.039972,0.226675,-0.159167,-0.083953,0.550294,-0.169697,-0.909305,0.044999,0.103102,-0.016721,-0.304664,0.251283,0.028640,0.305494,0.142905,-0.036647,0.374509,0.412195,0.321335,-0.206966,-0.161859,0.252395,-0.724314,0.161071,0.511843,-0.080702,-0.080716,0.299472,0.055985,-0.432228,0.067735,-0.111697,-0.003291,-0.257956,0.900432,0.019772,-0.543165,0.037266,-0.654963,-0.362648,-0.512465,-0.022148,0.101706,-0.412977,-0.120142,-0.752639,-0.117565,0.013607,0.088584,0.085613,0.071362,-0.042915,0.674811,-0.645298,0.088366,1.002658,0.276057,-0.311924,0.542950,-0.019953,-0.057694,-0.253036,-0.112645,-0.063088,0.459246,0.565965,0.188201,0.465115,-0.012293,-0.445293,-0.553837,0.317896', '25928048', '1301345', '5973984', '27069070');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300330', '赌城大亨之新哥传奇', '剧情', '贺新（刘德华 饰）本生于买办之家，从小生活优裕，然而父亲一次投资失败导致家道中落，贺新与母亲从此受尽白眼，而他也只有靠努力学习来改变境遇，贺新在校期间与同学程乐儿（王祖贤 饰）交好，可面对富家子情敌的挑衅他只有隐忍。1941年，日本入侵香港，贺新与好友阿南（万梓良 饰） 奔赴澳门，二人在码头做苦力被经理王昌（秦沛 饰）算计，但因成功击退地痞保卫码头，他们进入外籍主管阿方索入住，此间贺新对阿方索的私生女儿阿妹（邱淑贞 饰）一见钟情。贺新出计策打败了赌场的“听骰客”，又做成了私货生意，得以在澳门赌场大哥傅老喳门下出头，踏上赌城大亨之路……©豆瓣', '刘德华', '王晶', 6.7, 9672, 'tt0104145', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2355313874.jpg', 1.4, 9.3, 51.6, 26.9, 10.7, '-0.222584,-0.099062,-0.378587,0.166795,-0.000319,-0.340637,0.356208,0.259332,-0.654333,-0.153953,0.122863,0.670285,-0.012133,0.189159,0.427967,-0.114863,0.030709,-0.430808,0.234482,-0.146241,0.308814,-0.363287,0.074037,-0.208012,-0.270088,-0.150960,0.428200,0.185032,-0.135556,0.519044,0.325099,0.206730,-0.329399,0.249738,-0.030780,0.072129,0.030660,0.113903,-0.616093,0.076355,-0.200825,-0.187628,-0.164698,-0.267088,0.280381,0.283549,0.502725,0.052671,-0.010922,-0.358597,0.140416,-0.171924,-0.126810,-0.017303,0.176934,0.063438,0.333058,0.434078,-0.068456,-0.129756,0.090039,-0.150513,-0.068031,0.061182,0.138626,-0.317763,-0.616058,0.279363,-0.010108,-0.038353,-0.180376,-0.335758,0.164934,0.344858,0.282093,0.248292,-0.089546,0.279435,-0.462077,0.184532,0.703211,0.013159,0.257666,0.147276,0.303160,-0.229289,0.273615,-0.484698,-0.285997,0.119143,0.103524,-0.276534,-0.022070,0.050658,-0.396652,-0.094717,-0.290517,0.139465,0.332820,-0.394270,0.086231,-0.610636,-0.134866,-0.311656,-0.251995,0.143277,0.298741,-0.246854,0.252584,-0.768117,-0.080515,0.191500,0.499369,-0.673950,0.670887,0.059092,0.137494,-0.283243,0.021742,0.246893,0.086259,0.222089,-0.099731,-0.167083,-0.151260,-0.226828,0.097667,0.005129', '1296978', '1308035', '25721544', '1291992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300334', '熊的故事', '剧情', '宁静的原始森林，熊妈妈正带着自己的孩子约克寻找蜂蜜。正当母子享受这顿美餐时，灾难不期而至。熊妈妈被一块巨石砸死，约克伤心备至，不得已踏上了独自生存的艰险之路。它路遇被猎人伤害的成年灰熊，灰熊一心报复伤害它的人类，对待约克分外冷淡。但随着一段时间的相处，它和约克慢慢成为了好朋友。它们一路遭到猎人的追踪，也遇到了各种各样的险情，在这个危机重重的原始丛林中寻找属于自己的一片天地……本片根据1885年发生在美国洛基山脉中人与熊之间的真实故事改编，并荣获1989年法国凯撒奖最佳导演奖、1990年Genesis奖最佳外语片奖、1990年年德国艺术院电影公会公会电影奖银奖最佳外语片、1988年法国电影学院奖。©豆瓣', '巴特熊', '让-雅克·阿诺', 9.1, 26411, 'tt0095800', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2454268056.jpg', 0.2, 0.5, 6.5, 30.9, 61.8, '0.008200,-0.193494,-0.459357,0.486561,0.381346,-0.091493,0.307966,-0.209704,-0.508142,-0.203115,0.042916,0.777896,-0.125760,0.081245,0.110878,-0.174979,-0.194545,-0.409047,-0.115978,0.016592,-0.042225,0.029394,-0.506091,-0.114782,-0.119055,-0.325002,0.647060,0.114337,0.051268,0.531511,0.188595,0.190059,-0.095028,0.153525,-0.178702,0.091752,0.251939,0.090632,-0.466696,0.318700,-0.242699,-0.299094,-0.229129,0.003850,0.068109,0.094541,0.790693,-0.408729,-0.244027,-0.154493,0.494801,-0.620495,-0.032817,-0.080470,0.555466,-0.282171,0.117881,0.236604,-0.059353,0.185307,-0.030831,-0.452486,-0.517244,-0.004803,-0.014503,0.115086,-0.447066,0.298920,0.220250,0.353127,0.069095,-0.032212,0.280298,0.243254,0.394750,0.261550,-0.327389,0.102411,-0.394589,0.377858,0.729250,-0.314822,-0.283465,-0.022651,-0.277410,-0.655580,0.127539,-0.488059,-0.487544,-0.026685,0.493091,0.289384,-0.276789,0.219914,-0.758445,0.164805,-0.146219,-0.510931,0.067663,-0.346617,-0.148629,-0.560147,0.130462,-0.387123,-0.332605,-0.067552,-0.137367,-0.306380,0.638359,-0.420296,0.650249,0.734729,0.247774,-0.316302,0.792859,-0.211163,-0.014475,-0.245108,0.068147,0.509671,-0.085954,-0.081664,0.193495,0.143623,0.032528,-0.054286,-0.106001,0.559667', '24879819', '26290398', '1780122', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300343', '幻影英雄', '喜剧', '杰克系列电影是由施瓦辛格主演的系列电影。在这电影中，施瓦辛格扮演的杰克（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）总是世界的救世主，每当他的老对头班尼迪（查里斯•丹斯 Charles Dance 饰）出来作恶时，杰克总是能及时赶到，讲班尼迪打得落花流水。小男孩丹尼是杰克系列电影的忠实影迷，杰克系列电影的前三集他都能倒背如流。这天他的好朋友，电影放映员尼克给了丹尼一张神奇的电影，丹尼凭着这张电影票进入到了还未上演的杰克系列第四集中。不料班尼迪抢走了丹尼的电影票，从电影中来到了现实中。他的目标就是除掉杰克的扮演者施瓦辛格，这样在电影世界里就不再有人能够阻止他的邪恶计划。©豆瓣', '阿诺·施瓦辛格', '约翰·麦克蒂尔南', 7.6, 8155, 'tt0107362', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2196874153.jpg', 0.5, 2.8, 30.9, 46.3, 19.5, '0.057227,0.146191,-0.759247,0.534008,0.159287,-0.370484,0.790980,0.084505,-0.140254,0.032179,0.310241,0.722139,-0.301956,0.064129,0.312243,0.312186,-0.632458,-0.632995,-0.290124,-0.081077,0.048119,-0.218561,-0.720089,-0.198892,0.023677,-0.471679,0.654212,-0.160125,-0.453655,0.047634,0.487181,0.027180,-0.043084,0.311652,-0.054231,0.437107,0.102246,-0.333445,-0.430098,0.651554,0.250871,0.056420,-0.205974,0.156112,-0.122491,0.389832,0.808116,-0.342625,0.007726,0.238107,0.614345,-0.186709,-0.293841,-0.102416,0.005236,-0.069372,0.423093,-0.093735,0.182786,0.302841,-0.169252,-0.162379,-0.942912,0.186105,-0.045626,0.263833,-0.443581,0.227725,-0.474894,0.243722,0.322692,-0.344451,0.313140,-0.144844,0.428376,0.331574,0.081650,0.074723,-0.602645,0.662353,0.362803,0.155548,-0.220130,0.744421,-0.082659,-0.314654,-0.512722,-0.270286,-0.641978,0.258453,0.730326,-0.267965,-0.294325,0.194568,-0.572142,0.007547,-0.131471,-0.230334,0.031884,-0.215376,-0.019080,-0.952555,-0.199654,-0.121477,-0.044403,-0.286767,0.014052,-0.526454,0.878669,-0.608145,0.122297,0.624087,0.088190,0.093580,0.884226,0.117973,-0.090015,0.023801,-0.026268,0.020411,0.132869,0.455184,0.257839,0.573119,0.282614,-0.415802,-0.523232,0.921120', '3318306', '26275494', '2027945', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300352', '七次机会', '喜剧', '讲述商人吉姆面临经济危机，幸好去世的祖父留下巨额财产给他，但条件是他必须在27岁生日晚上七点前结婚，结果引来全城妇女的求婚，当然，最后还是有情人终成眷属。', '巴斯特·基顿', '巴斯特·基顿', 8.9, 11728, 'tt0016332', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2321431402.jpg', 0.2, 0.5, 6.2, 39.4, 53.8, '-0.429295,-0.049407,-0.564460,-0.143705,-0.146494,-0.409621,0.258212,-0.213506,-0.279114,-0.629755,0.260652,0.618290,0.019584,0.532487,0.547733,-0.262795,-0.318556,-0.143798,0.622182,0.111938,-0.310267,-0.607752,0.531281,0.145373,0.094737,0.008847,0.320059,0.240378,0.204085,0.454429,0.323847,0.037654,0.332272,0.539158,-0.222573,-0.257113,0.251800,-0.048607,-0.746203,0.360362,0.042094,-0.420061,0.191512,0.116421,0.162695,0.613979,0.078239,0.085284,-0.252684,-0.094020,0.955136,-0.217961,-0.418009,0.193258,0.688668,0.391032,0.767140,0.390506,-0.064056,-0.271901,-0.203908,-0.336009,-0.119316,0.305036,0.395889,-0.240159,-0.496061,0.331021,-0.103700,0.353016,0.257519,-0.261236,0.390711,0.534135,0.036656,0.287856,-0.088832,0.111972,-0.749682,-0.164837,0.705746,-0.398297,0.315782,0.154167,-0.199598,-0.542203,0.522754,-0.344894,-0.158676,0.981094,-0.301091,-0.075867,-0.466396,0.253248,-0.005623,-0.574014,-0.182191,-0.273921,0.571033,-0.190874,-0.440129,-0.349275,-0.087230,-0.044359,-0.686992,0.192092,0.271519,-0.441018,0.550258,-0.365261,0.241402,0.325816,0.682812,-0.515028,0.706431,0.391085,0.387064,-0.276804,0.284719,0.139644,-0.309876,-0.094128,-0.220082,-0.606467,0.316349,-0.387960,-0.108838,0.502888', '1292869', '4022090', '30159567', '27170563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300353', '巴黎最后的探戈', '剧情', '让娜（玛利亚•施奈德 Maria Schneider 饰）穿行大街而过，来到一个旅馆，怪诞的服务员给了她一串空房间的钥匙。她开门而入发现已经有个中年男人在那里。简单交流后两人目光如炽，在空荡的房间里激烈地亲热。结束后安娜来到火车站接男友汤姆，汤姆正在拍摄电影，准备记下与女友恋爱的发展过程。此后让娜经常到那间公寓与中年男人约会。中年男人保罗（马龙•白兰度 Marlon Brando 饰）来自巴黎，出轨的妻子在不久前自杀，他十分痛苦。让娜试图了解保罗，向他敞开心扉，而保罗却一再拒绝她的窥探亦不希望了解她。汤姆向让娜求婚，让娜答应了。两人在选择婚纱时，让娜因汤姆重视拍摄效果冷落自己，冲进大雨找到保罗……©豆瓣', '马龙·白兰度', '贝纳尔多·贝托鲁奇', 7.1, 35585, 'tt0070849', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1593669998.jpg', 2.9, 6.1, 36.7, 39.1, 15.2, '0.231963,-0.057786,-0.604871,0.461410,0.226415,-0.157981,0.980787,0.247168,-0.113217,-0.267333,0.195093,0.752229,-0.237800,0.484693,0.594256,0.403686,-0.704212,-0.632694,0.250956,-0.057347,-0.332121,-0.455502,0.229434,-0.428439,0.112959,-0.300344,0.386439,0.018753,-0.312526,0.629538,0.128979,-0.066922,-0.149003,0.755854,0.020800,0.045488,0.235725,-0.152722,-0.278583,0.311438,0.303123,-0.177226,-0.369098,0.266074,0.285731,0.223572,0.794930,-0.335128,-0.031767,0.402403,0.448180,-0.163322,0.148656,0.143508,-0.072009,-0.211240,0.170634,0.115162,-0.234441,0.220078,0.063100,-0.161851,-0.455136,0.552772,-0.289556,-0.154392,-0.533787,0.530424,-0.268435,0.186837,0.279327,-0.374370,0.169306,0.116479,0.018034,0.280088,-0.253149,0.138540,-0.246336,-0.109405,0.405076,0.052400,0.252024,0.590238,-0.162560,-0.312025,-0.058816,0.214949,-0.554312,-0.140627,0.471809,0.121430,-0.171820,-0.270440,-0.398489,-0.405877,-0.526342,-0.216818,0.265715,-0.504233,-0.379900,-0.897652,-0.212226,-0.118923,-0.336200,-0.013046,-0.370933,-0.222473,0.303407,-0.755533,0.013142,0.644515,0.382416,-0.432643,0.918084,-0.159329,0.098155,-0.247826,0.017067,0.475476,0.134774,0.279911,0.307600,0.501751,-0.028329,0.215864,-0.482881,0.247136', '10466639', '1309172', '1301686', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300359', '大块头有大智慧', '剧情', '大隻佬（刘德华 饰）在跳艳舞时与前来扫黄的警花李凤仪（张柏芝 饰）相遇，同时，重案组亦在附近调查一起印度人杀人案。大隻佬逃跑时与逃走的印度逃犯不期而遇，最后逃犯逃走了，大隻佬被当成了嫌犯抓回了警局。其实大隻佬以前是大陆一名武僧，因好友小翠惨死，悲伤过度在树下不慎打死小鸟，对着小鸟坐禅7天7夜因而获得能看到因果的能力——看到结果时，便能看到因由。他看到了小翠的死是因果，他打死小鸟是因果，因无法平静接受这一切，他还俗了。这次，他看到了李凤仪，看到了日军在杀人，便知她罪业太重，会遭遇横祸。为了帮助这位心地善良的警花，他开始暗中帮助她，帮她屡破奇案，救她于危难，希望能帮她洗刷罪业……©豆瓣', '刘德华', '杜琪峰', 6.8, 79203, 'tt0374184', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1179163130.jpg', 1.9, 10.6, 47.1, 28.4, 12, '0.011878,0.046450,-0.733209,0.150376,-0.186443,-0.073234,0.583210,-0.201396,-0.607664,-0.021274,0.176064,0.818079,-0.198595,0.111090,0.109120,0.015464,-0.170603,-0.677500,-0.011986,0.043350,-0.455011,-0.198830,-0.114472,-0.202754,-0.106598,-0.167300,0.394451,0.399500,-0.183665,0.359484,0.328782,0.261601,-0.191943,0.368578,-0.400860,0.075474,-0.204061,-0.067926,-0.129757,0.281058,0.111332,-0.424786,-0.195740,0.043683,-0.204922,0.165562,0.525617,-0.233186,-0.260846,-0.287627,0.206218,-0.298587,0.110320,0.181644,0.126619,-0.237133,0.225447,-0.024620,-0.148285,-0.160631,0.296549,0.005644,-0.516262,0.217252,-0.088825,0.163921,-0.528080,0.245640,-0.275233,0.124819,0.176961,0.037260,0.220895,0.289615,0.239094,0.189523,-0.073743,-0.127100,-0.755741,0.109808,0.699919,-0.062931,0.193812,0.264884,-0.000662,-0.248503,-0.009438,-0.253924,-0.021190,0.232581,0.540864,-0.036051,-0.580607,0.274853,-0.158332,-0.276324,-0.429040,0.181793,-0.293849,-0.218216,-0.297128,-0.131090,-0.109189,-0.144159,-0.379697,0.311744,0.153026,-0.357731,0.519414,-0.921665,0.137299,0.545419,0.395018,-0.406511,0.715221,0.155325,-0.088657,-0.087993,-0.132218,-0.002126,0.090334,0.463501,0.636538,0.133436,-0.034581,-0.253942,-0.161562,0.075277', '1302384', '1308755', '1309069', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300361', '第一滴血2', '动作', '神勇的蓝波（西尔维斯特•史泰龙 Sylvester Stallone 饰）又回来了！这次，蓝波奉命返回越南调查失踪的美军是否已成为战俘。然而，蓝波甫一登陆越南，所有装备和武器都丢失了！随身剩下的，只有一把军刀和一套军用弓箭。身处逆境的蓝波，偶然发现了出卖他的正是自己的部队！蓝波在九死一生之际，得到了当地一名越南少女的帮助。在少女的帮助下，蓝波凭借其高超的求生技能和坚强的意志，克服了一切困难，终于逃出生天。蓝波决定向出卖他的人重拳出击！©豆瓣', '西尔维斯特·史泰龙', '乔治·P·科斯马图斯', 7.8, 47483, 'tt0089880', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2485316784.jpg', 0.3, 1.8, 25.8, 50.1, 22, '-0.026294,0.022769,-0.777746,0.463979,-0.254846,-0.412221,0.500575,-0.199285,-0.096048,-0.314626,0.367779,0.716226,0.426760,-0.024876,0.355616,-0.143414,-0.307238,-0.866149,-0.178368,0.036545,-0.545089,-0.299575,-0.526308,-0.114230,-0.079464,-0.491354,0.843394,0.332052,-0.245653,0.277942,0.213408,0.337164,-0.041514,0.478950,-0.216199,-0.106133,0.071481,-0.337468,-0.194219,0.432195,-0.137253,-0.351256,-0.155891,0.354442,0.075396,0.373562,0.752700,-0.443293,-0.085763,0.146192,0.074045,-0.157969,-0.014828,0.051242,0.155721,0.075972,-0.018287,-0.169845,-0.241432,0.134652,0.116630,-0.051810,-0.776464,-0.207716,-0.021681,-0.058999,-0.676548,0.271252,-0.331307,0.237258,0.313341,-0.542751,0.066023,0.552839,-0.063986,0.282933,-0.573002,-0.094857,-0.583463,0.095026,0.520562,-0.415651,-0.147544,0.066251,0.136779,-0.527474,-0.027387,-0.356057,-0.134395,-0.015646,0.703700,0.282645,-0.234480,0.204412,-0.701517,-0.045220,-0.371724,-0.269310,-0.046991,-0.190590,-0.120930,-0.570464,0.005569,-0.230533,-0.310815,0.161019,0.205934,-0.252327,0.938083,-0.850571,-0.005709,0.513220,0.102145,-0.340573,0.283323,-0.145136,0.200083,0.119507,0.016147,0.217077,0.401654,0.563346,0.268251,0.373379,-0.002462,-0.192439,-0.407070,0.336639', '25774050', '25928048', '1826173', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300371', '机器战警3', '剧情', '泛消费公司已完全掌控了底特律市之后，与日本金光财团合作组建OCP，在底特律开发三角洲城，并招揽雇佣兵组成暴力改建队，驱逐居民，相当数量的拆迁地居民为捍卫家园组成武装力量反抗财阀的不义计划，女童妮科（Remy Ryan Hernandez 饰）凭借高超的电脑技术在反抗军中表现抢眼。机器战警墨菲（Robert John Burke 饰）与老搭档路易斯执行任务期间偶然发现了居民们的藏身地点，出于正义感，墨菲同随后赶到的改建队交火，机体损坏严重，路易斯不幸身亡，墨菲决定加入反抗军。同时日本方面为执行拆迁计划派出特工忍者雄志，改建队头目亦利用反抗军中的叛徒查到了反抗总部。在妮科的帮助下，墨菲被拉瑟斯博士整修完备，汇同不齿改建队暴力行径而选择站到居民一边的底特律警察们，同雄志、改建队展开最后决战。©豆瓣', '罗伯特·约翰·伯克', '弗莱德·戴克尔', 6.7, 9556, 'tt0107978', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2112032963.jpg', 1.3, 7.9, 53.3, 27.3, 10.2, '0.137363,-0.032168,-0.621643,0.176184,0.211202,-0.095483,0.202446,0.132002,-0.341106,-0.261303,0.407928,0.167118,0.319327,-0.241760,0.233033,-0.532860,-0.466396,-0.561496,-0.206612,-0.016356,-0.087809,-0.514499,-0.010177,-0.543071,0.116399,-0.366755,1.066382,0.324731,-0.522574,0.243322,-0.027159,0.443552,-0.241365,0.062117,0.204373,-0.385900,0.559018,-0.485149,-0.422220,0.244121,-0.746820,0.056408,-0.067747,-0.193198,0.464915,0.574067,0.772046,-0.209867,-0.084902,-0.411978,0.089015,-0.376003,0.169883,-0.001194,0.628845,0.200747,-0.059730,0.220338,-0.034497,-0.076841,-0.080231,-0.294863,-0.850054,-0.235292,0.300053,-0.147259,-0.657014,0.321035,-0.329162,0.197097,-0.144876,-0.264652,0.086435,0.513997,0.129276,0.136427,0.208069,0.337005,-0.338265,-0.042780,0.561566,-0.369385,-0.232480,-0.452328,-0.119785,-0.483182,-0.091490,-0.411298,0.106589,-0.295891,-0.006480,-0.160651,0.519933,0.198717,-0.742017,-0.051166,-0.295600,-0.309485,0.126837,-0.263673,0.146270,-1.266385,0.113638,0.361614,-0.104506,0.182655,0.085290,0.218606,0.351663,-0.914517,-0.130876,0.505458,0.482612,-0.722639,-0.009186,-0.033427,0.235144,-0.233538,-0.275716,0.255996,0.248546,0.508431,0.125555,0.029896,-0.036689,-0.546741,-0.059009,-0.075824', '2369613', '1306809', '3266509', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300374', '绿里奇迹', '剧情', '狱监保罗（汤姆•汉克斯 Tom Hanks 饰）这天迎来了一位不平凡的杀人犯――约翰•考夫利（迈克•克拉克•邓肯 Michael Clarke Duncan 饰）。约翰因杀了两名幼女被判死刑来到了这座著名的冷山监狱，监狱里有一片称为“绿里”的绿地，绿地那头就是刑场。约翰不仅不像想象中的凶残，相反，他出奇的温厚、机智。约翰的到来给狱中的各人带来了天翻地覆的变化：为老囚犯特里沃的小老鼠注入了生命的强度，给特里沃最后的人生带来最后的慰籍；神奇的拯救了被病痛折磨的保罗和马琳达；将金保斯从死神手中拉了回来……保罗这些天也从约翰身上看到了人生的真谛。约翰行刑的那天终于到了。©豆瓣', '汤姆·汉克斯', '弗兰克·德拉邦特', 8.9, 299570, 'tt0120689', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p767586451.jpg', 0.2, 0.7, 8.4, 34.8, 55.9, '0.202963,0.052672,-0.460740,0.510320,-0.227245,-0.568795,1.036994,0.287251,-0.246791,-0.161508,0.203228,0.629390,-0.285483,0.203437,0.463493,0.005292,-0.458753,-0.610796,-0.391726,-0.097127,-0.468141,-0.420607,-0.366881,-0.012326,0.014234,-0.326651,0.337539,0.055252,-0.097561,0.446277,0.159033,0.576136,0.353991,0.403940,-0.322327,0.359164,0.273875,-0.186482,0.052208,0.331177,0.128464,-0.161907,0.056941,0.393971,-0.137789,0.349956,0.665026,-0.472559,0.006231,-0.159237,0.489491,-0.232535,-0.085356,0.221502,0.131283,-0.082381,-0.149298,0.129880,-0.279891,0.007293,0.048854,-0.275262,-0.939326,-0.047791,-0.274256,0.179536,-0.559243,0.364714,-0.052201,-0.016572,0.091787,-0.229161,0.331121,0.021585,-0.022690,0.614460,-0.064512,-0.111336,-0.514200,-0.011249,0.560272,-0.277746,-0.246380,0.222178,-0.403818,-0.502238,-0.028467,-0.218677,-0.322716,-0.068891,0.637197,0.126635,-0.145314,0.232444,-0.537949,-0.171734,-0.346827,-0.236813,-0.113444,-0.146123,-0.325092,-0.521834,-0.146870,-0.307254,-0.243199,-0.036897,-0.015247,-0.150985,0.547868,-0.306935,0.472202,0.549041,-0.066744,0.101740,0.629197,-0.093689,0.229576,-0.003474,-0.043927,0.287418,0.308354,0.667210,0.468895,0.626105,-0.130251,-0.219327,-0.385105,0.798528', '1578663', '21619567', '4944008', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300377', '群尸玩过界', '喜剧', '故事开始于一支在苏门答腊岛活动的探险队，他们发现了当地一种长相怪异的鼠猴，便带回去卖给动物园，不料却因此酿出一个恶果。莱尼（蒂莫西 巴姆Timothy Balme 饰）有着对他十分依赖的母亲，这天母亲被困在笼里的鼠猴咬了一口。不久后，她开始变得诡异万分，莱尼甚至看见她吃蜘蛛、咬狗，行为癫狂。莱尼请来医生护士，却被母亲撕咬后继而变成僵尸。明知母亲成为高度危险的人物，莱尼却不舍得伤害她，只把她和僵尸困在房间里。不料星星之火可以燎原，在莱尼家的一场舞会中，一大群人遭殃，他们变成乱七八糟的僵尸怪物横冲直撞，莱尼挥出电锯，杀得气喘呼呼，血肉四溅，情急下，莱尼心爱的却已变了质的母亲，也不能幸免。©豆瓣', '蒂莫西·贝尔米', '彼得·杰克逊', 7.8, 34534, 'tt0103873', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2139042743.jpg', 1.3, 4, 26.3, 41.8, 26.6, '0.322419,-0.033279,-0.589491,0.239861,-0.175646,-0.125297,0.969493,0.165492,-0.358677,0.206011,0.362868,0.721829,-0.300088,0.197148,-0.060469,0.171438,0.053479,-0.439299,0.135565,0.104846,-0.108111,-0.008567,-0.469193,-0.334884,0.129889,-0.324533,0.397525,-0.174791,-0.124203,0.331037,0.098697,0.290106,-0.035757,0.490306,-0.107757,0.170438,0.013090,-0.269015,0.205343,-0.017277,-0.056957,0.052570,-0.204252,0.229860,-0.206729,0.301212,0.690281,-0.412336,-0.005413,-0.370384,0.041976,-0.341873,-0.013376,0.283166,0.322081,-0.095316,0.314427,-0.110839,-0.194792,0.174528,0.106745,0.186704,-0.411226,0.079003,0.016862,0.446366,-0.425332,0.218134,-0.091824,0.194716,0.081607,-0.390598,0.095585,0.020066,0.163659,0.417543,-0.155100,-0.076922,-0.709175,-0.153981,0.616383,-0.346631,-0.255590,0.254134,-0.163991,-0.310625,0.113744,-0.265516,-0.337820,-0.318951,0.295051,0.166010,-0.519767,0.194273,-0.593034,-0.181680,-0.292577,-0.300125,-0.295247,-0.143471,-0.454267,-0.093696,-0.011402,-0.289147,-0.338913,-0.032686,-0.008357,-0.007830,0.441962,-0.407841,0.296991,0.456131,0.044532,0.074976,0.257941,-0.167150,-0.021513,0.247629,-0.195257,0.165662,0.349666,0.166880,0.454767,0.347833,0.017762,0.078473,-0.262244,0.575297', '21619567', '1467779', '1578663', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300381', '中华赌侠', '喜剧', '香港新崛起的小赌侠泽西（张家辉 饰）为人无厘头兼手段高强，与拜金又风骚的女友芭娜娜（钟丽缇 饰）纵横赌界，泽西自认风头无两，却被人点破他一直心仪并想超越三年前为情而消失于江湖的一代赌侠阿酷（古天乐 饰）。阿酷拥有一手飞牌绝技，与女友可人（朱茵 饰）、搭档杨光一起几乎登顶亚洲赌坛之巅，然而因为杨光的背叛，阿酷失去了一切……泽西与芭娜娜赴日本旅游，竟意外与栖身小饭店的阿酷相结识，泽西力劝阿酷回港，但后者只想守候可人无心复出。此时杨光再出毒计，逼迫阿酷出面与日本赌王铁男争夺亚洲赌王的位置，而暗地里布置了更大的陷阱……©豆瓣', '古天乐', '程小东', 6.3, 10116, 'tt0325181', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2525648625.jpg', 2.2, 14, 56.9, 19.5, 7.4, '0.079006,0.004056,-0.455068,0.354184,0.086505,-0.249158,0.385300,0.136069,-0.430689,-0.249243,0.013778,0.667591,-0.175271,0.006504,0.189460,0.046073,0.000112,-0.803047,0.085661,-0.030084,0.292628,-0.243667,-0.430115,0.126034,-0.292133,-0.106360,0.638343,-0.139878,-0.205537,0.577340,0.462464,0.131853,-0.248079,0.198543,-0.010428,-0.086805,-0.061714,0.030122,-0.584074,0.191370,-0.218572,-0.223277,-0.340706,0.138642,-0.067331,0.292625,0.444803,-0.036006,-0.040346,-0.380999,0.173460,-0.264401,-0.214863,-0.120609,0.112317,-0.120990,0.417031,0.291623,-0.094452,-0.004516,0.431483,-0.080347,-0.588437,0.427377,0.128150,-0.192740,-0.392232,0.340271,-0.297835,-0.200859,-0.019102,-0.415376,0.099346,-0.009688,0.341149,-0.023520,-0.071941,0.087249,-0.278491,0.197064,0.472774,0.302246,-0.094928,0.133154,0.409849,-0.320433,-0.088072,-0.559924,-0.331687,0.088223,0.096323,-0.101946,0.064216,0.323077,-0.466154,-0.018838,-0.529352,0.180396,-0.039148,-0.264756,0.015947,-0.616288,-0.228680,-0.264066,-0.123676,-0.117310,0.393473,-0.208881,0.595464,-0.878651,0.179032,0.182284,0.403379,-0.522589,0.606549,0.232170,0.164544,-0.094751,-0.420322,0.197600,-0.097209,0.041000,-0.032866,0.203532,-0.303378,-0.191248,-0.282016,0.106137', '4301278', '30345227', '35030151', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300399', '第一滴血3', '动作', '历经无数战火与生死考验，孔武有力的豪情勇士约翰·兰博（西尔维斯特·史泰龙 Sylvester Stallone 饰）放下手中的杀人武器，在泰国过起了平静的修行生活。这一日，特劳特曼上校（理查德·克里纳 Richard Crenna	饰）突然出现在他面前。此前不久，上校受命率部队前往阿富汗，协助当地的圣战勇士反抗苏联人的入侵。虽然照片中阿富汗平民饱受外敌侵略和蹂躏的情景触目惊心，但兰博还是拒绝了上校的邀请。某晚，特劳特曼的部队在执行任务途中遭到苏联军队的伏击，其本人也不幸沦为阶下囚。得知这一消息，兰博再也无法静观其变。浴血战士重披战甲，只身闯入充满凶险的阿富汗腹地，展开一场紧张纷呈的绝命营救……本片获1989年金酸梅最差男主角奖。©豆瓣', '西尔维斯特·史泰龙', '彼得·麦克唐纳德', 7.6, 39272, 'tt0095956', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2243764496.jpg', 0.5, 2.9, 32.4, 45.1, 19, '0.004679,-0.069823,-0.699382,0.365446,0.274873,-0.104596,0.532369,-0.081039,-0.358345,-0.035339,0.509555,0.752799,0.072021,-0.233722,0.531440,-0.165229,-0.365924,-0.614944,-0.159956,-0.003274,-0.068264,-0.215634,-0.431392,-0.197376,0.027258,-0.616414,0.765831,0.116423,-0.199280,0.704722,0.351769,0.508267,-0.266414,0.515358,0.041279,-0.192733,0.148731,-0.300241,-0.502333,0.230111,-0.244947,-0.256227,-0.193002,0.245637,0.077248,0.262334,0.646775,-0.346558,0.042692,-0.168982,0.160613,-0.421073,-0.029345,0.104882,0.408896,-0.073813,0.048146,-0.068160,0.169528,0.040207,-0.154952,0.039939,-0.489156,-0.248714,0.084160,0.217113,-0.443615,0.306413,-0.253337,0.400845,-0.076241,-0.068426,0.039808,0.604191,0.123273,0.142444,-0.070510,-0.053171,-0.437762,0.280503,0.686707,-0.180423,-0.232320,-0.459304,-0.128496,-0.557245,0.182821,-0.470238,-0.492975,-0.047228,0.220285,-0.129633,0.023935,0.445957,-0.664781,0.084085,-0.493196,-0.095158,-0.170336,0.053506,-0.229954,-0.715285,-0.041106,-0.006358,-0.427914,0.348450,0.135057,0.244245,0.337935,-0.540977,0.296083,0.387567,0.305751,-0.089401,0.216951,0.300887,0.200359,0.047929,-0.124705,0.495609,0.247423,0.402726,0.121064,0.146273,-0.126248,-0.272773,-0.210886,0.202948', '1780122', '11541282', '3871833', '1308069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300426', '美好事物', '剧情', '单亲家庭长大的Jamie（Glen Berry）因为不爱运动，在学校显得很不合群，上学成为他最头疼的事，而随着年龄的增长，他同母亲的交流也有了障碍，尤其在母亲交了个莽撞憨直的男友后，他更不知如何与母亲相处。他的邻居，英俊的小伙子Ste（Scott Neal）与他相比，也好不到哪儿去，Ste时常遭嗜酒如命的父亲和哥哥拳打脚踢。某天，Ste遭家人殴打后又被扫地出门，Jamie的母亲可怜他把他叫到家里同Jamie一起睡，两个少男第一夜虽没共枕，却对彼此生出异样感觉，而随着同床日子的增多，他们渐渐爱上了对方，但是，麻烦也紧接而来。©豆瓣', '林达·亨利', '希提·麦克唐纳', 8.4, 11163, 'tt0115640', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2456957300.jpg', 0.2, 1.3, 17.8, 42.1, 38.6, '0.429135,-0.402047,-0.780737,0.462785,-0.168303,-0.557877,0.890523,0.335048,-0.528507,-0.277533,-0.114974,0.734443,-0.099712,0.376540,0.053044,-0.165867,-0.030311,-0.534647,0.261276,-0.210276,-0.277896,-0.368732,0.096286,-0.149631,-0.151699,-0.195504,0.449958,-0.333589,-0.053108,0.532496,0.292779,0.130462,0.099819,0.837495,-0.527146,0.066847,-0.250000,0.494139,0.156108,-0.027743,0.500648,-0.155424,-0.035903,-0.113732,-0.050926,0.365238,0.604761,0.067690,-0.289979,-0.175669,0.248461,-0.088424,-0.135005,0.264863,0.416359,-0.075554,0.228112,0.189196,-0.299539,-0.052738,-0.201378,0.102092,-0.463255,0.348942,0.187872,-0.149750,-0.708607,0.373934,0.074553,-0.319589,0.056531,-0.405573,0.172402,0.609053,-0.008304,0.555701,-0.381569,-0.075317,-0.450685,-0.116714,1.054587,0.223015,-0.112098,0.485998,-0.261754,-0.248173,0.186828,-0.506950,-0.605853,0.033006,-0.127374,-0.012360,-0.356257,0.234563,-0.561745,0.074717,0.074628,-0.062315,-0.182916,-0.685484,-0.055746,-0.093256,-0.356201,-0.772228,-0.498447,0.048389,0.199559,-0.251350,0.875731,-1.117587,0.212102,0.577731,0.465112,-0.811836,0.766606,0.443988,-0.032163,-0.282045,-0.081000,0.122824,0.073472,0.060668,0.315535,0.190170,-0.188780,0.020021,-0.375347,0.425260', '1308755', '1292219', '25721544', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300487', '烈火战车', '剧情', '本片讲述了1924年英国两名奥运健将的故事。1919年，剑桥大学凯斯学院的开学礼上迎来一名叫亚伯拉罕（本·克劳斯 Ben Cross 饰）的犹太学生。他擅长跑步，参加剑桥的环校挑战赛后一战成名。然而犹太人的身份让他饱受种族偏见之苦，因此他一心想赢得奥运会百米赛跑的金牌， 以此来对抗种族偏见。另外一位短跑健将是来自苏格拉高地的艾利克里德（伊安·查里森 Ian Charleson 饰），他极具跑步天赋，而他本人是个虔诚的基督教徒，认为自己的天赋来自上帝，他是为上帝而跑。在1923年的全国性运动会上，两名青年狭路相逢，艾利克里德最终赢得冠军。亚伯拉罕则请来了职业教练指导自己，备战奥运。1924年的巴黎奥运会来临，艾利克里德却得知百米资格赛在星期天举行，作为一名基督徒，他严格遵守着“安息日不得工作”的教义，最后他决定退出百米赛。另一方面，亚伯拉罕不仅要面对强大的美国名将，更要面对自己的内心。这枚奥运金牌，将花落谁家……', '本·克劳斯', '休·赫德森', 7.8, 10925, 'tt0082158', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1588317576.jpg', 0.5, 2.5, 27.2, 46.8, 22.9, '-0.024346,-0.058467,-0.543573,0.679501,-0.101129,-0.217628,0.271742,-0.089237,-0.420011,-0.427153,0.313219,0.930537,-0.198634,0.212070,0.458961,-0.151881,0.009651,-0.576424,-0.204301,-0.160186,-0.246571,-0.409542,-0.222940,-0.164972,-0.115991,-0.329076,0.571427,-0.079763,-0.210818,0.652112,0.423904,0.325857,0.496749,0.078349,-0.130311,-0.488668,0.319065,-0.029264,-0.213087,0.391782,0.008753,-0.151023,-0.512692,0.208424,0.008881,0.230840,0.392010,-0.093593,0.307406,-0.269867,0.474638,-0.532156,-0.093757,0.133548,0.371767,0.082205,-0.006523,0.486636,0.309920,0.141407,0.023750,-0.402782,-0.554669,0.090197,0.016003,0.025197,-0.549660,0.663814,-0.310553,-0.001667,0.004676,-0.179636,-0.060387,0.234870,0.083988,0.267615,-0.043602,-0.165063,-0.398597,0.282811,0.765784,-0.146822,-0.152060,-0.194658,-0.216175,-0.673728,0.180409,-0.402441,-0.420770,0.043782,0.221025,-0.026457,0.148696,0.161094,-0.455158,-0.005631,-0.328567,-0.398276,-0.038948,-0.229909,0.034158,-0.582247,0.026167,-0.243074,-0.334464,-0.131700,0.150165,-0.294500,0.959032,-0.794146,0.216639,0.523920,0.276314,-0.386429,0.852843,0.187351,0.209508,-0.194602,-0.172745,0.392034,-0.122061,0.125976,-0.394710,0.329848,0.181446,-0.278498,-0.143236,0.668249', '1870681', '1292720', '26711487', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300498', '百变星君', '喜剧', '夏威夷念大学的香港富豪子弟李泽星（周星驰 饰）学业无成挥金如土，是校园一霸，终因搭上黑帮老大情妇遭黑帮追杀，身体被炸成碎片。 在李泽星父亲（吴孟达 饰）的请求下，教授（徐锦江 饰）将李泽星全身人造复原，并把最新研制成功的无敌芯片置入其身，令其摇身一变成为无敌“百变金刚”。黑帮老大得知李泽星复活后，将写有战争程序的芯片植入手下身体，令其变身“铁甲威龙”前来追杀李泽星。为赢得暗恋的女同学虫虫（梁咏琪 饰）的芳心，李泽星决意重塑形象，奋力与“铁甲威龙”展开大战。©豆瓣', '周星驰', '叶伟民', 7.8, 284538, 'tt0112446', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2563027293.jpg', 0.3, 2.4, 28, 44.7, 24.6, '-0.041052,0.057001,-0.248645,0.190946,0.171758,-0.015982,0.336939,0.212819,-0.287654,-0.134517,0.274157,0.363017,-0.356437,0.065207,0.015776,-0.045543,0.144500,-0.820739,-0.213435,0.170562,-0.001429,-0.075778,-0.298926,0.302790,-0.115682,-0.661913,0.934382,-0.233977,-0.198856,0.436630,0.167545,0.483398,-0.128251,-0.115468,-0.315865,0.288927,-0.199190,-0.099542,-0.302940,0.265240,-0.236888,-0.226594,0.525557,-0.150544,-0.095682,-0.045635,0.796384,-0.155112,0.220036,-0.451190,0.534404,-0.255036,-0.218628,-0.047134,0.339229,0.330703,0.106186,0.254978,-0.091735,0.093008,0.496169,-0.004604,-0.616641,-0.254251,0.186153,0.017917,-0.505614,0.165581,-0.351438,0.019025,-0.107558,-0.160581,0.160063,0.186448,0.297412,0.117386,0.084395,0.472068,-0.421514,0.359007,0.342790,-0.214154,-0.150811,-0.022635,0.256746,-0.124612,0.024668,-0.476879,0.016262,-0.132106,0.058105,0.056531,-0.061978,0.273095,-0.509647,-0.384272,-0.412732,-0.079684,0.212548,-0.044712,-0.188138,-0.603528,-0.357500,0.201300,0.044159,-0.140369,0.182419,-0.092430,0.673509,-0.817160,0.201665,0.117981,0.324808,-0.425796,0.292192,-0.021517,0.065228,-0.232088,-0.020901,0.140872,0.493337,0.419564,0.068060,0.033588,-0.336490,-0.228248,-0.412115,0.145042', '26759820', '2369613', '3266509', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300508', '富贵列车', '喜剧', '民国初年，上海至成都的铁路通行了。首班列车的启程引起了黑帮注意，因为上面全是富贵人家，于是他们勾结山贼准备中途劫车。专门偷鸡摸狗的程启天（洪金宝 饰）也打上了这趟列车的主意，为了能摸上列车，他决定炸毁家乡汉水镇前的一段铁路，然后乘机上车。不料程启天被当地保安队长曹卓坚（元彪 饰）认出他是通缉犯，于是想捉拿他归案。程启天侥幸躲过追捕，顺利炸毁了铁路。这正好帮了山贼一个大忙，他们开始团团围攻汉水镇。眼看家乡即将毁于山贼之手，程、曹两人决定联合起来共抗强敌。©豆瓣', '洪金宝', '洪金宝', 7.5, 11083, 'tt0091091', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1610195777.jpg', 0.6, 3.2, 35.9, 43.6, 16.7, '0.541948,0.111812,-0.503608,0.262323,0.206340,-0.153563,0.083265,0.085013,-0.368843,0.242385,0.028378,0.477728,0.031444,-0.060373,0.229280,-0.023910,-0.537226,-0.522673,0.160645,-0.183473,-0.478820,-0.115090,-0.262344,-0.171127,0.089569,0.180470,0.230475,0.637512,-0.031499,0.595670,0.366087,0.016319,-0.204019,0.349941,-0.307970,0.111532,-0.107512,-0.393852,-0.129630,0.193184,-0.402662,-0.483569,0.183462,0.069488,-0.003416,0.672149,0.561754,0.200364,-0.042502,-0.322418,-0.125613,-0.404746,0.309734,-0.036497,0.533447,0.249918,0.010033,-0.014044,-0.295078,-0.309900,0.266301,-0.088222,-0.250141,0.180016,-0.081289,-0.278944,-0.428583,0.113520,0.051301,0.175565,-0.110637,-0.273379,0.224810,0.548470,0.066859,-0.176830,0.073569,-0.035157,-0.613578,0.349869,0.833226,-0.350336,0.482718,-0.116118,0.473670,-0.070168,0.252872,-0.333705,0.212670,-0.164911,0.621352,-0.275176,-0.193610,-0.229890,-0.320238,-0.158276,-0.533834,0.156152,-0.116968,-0.032795,0.089944,-0.414854,0.291395,0.083216,0.079940,0.408929,0.134171,0.194475,0.142985,-0.459462,-0.201816,0.597562,0.511412,-0.478486,0.331696,0.078937,0.152035,-0.076215,0.144902,-0.310371,0.167417,0.776904,0.379830,0.207684,-0.219769,-0.411450,-0.180342,0.218963', '1292846', '30299515', '2079017', '1296947');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300528', '男孩别哭', '剧情', '布兰顿（希拉里•斯万克 Hilary Swank 饰）来到法奥斯城，成为了当地的大众情人，很受女性欢迎。然而他却有着不为人知的隐秘——俊男本是女儿身。“他”的真名叫蒂娜，一直对自己是个女性缺失认同。他喜欢成为男性，并决定来到这个陌生的城市开始新角色和新生活。布兰顿和当地女孩拉娜（科洛•塞维尼 Chloë Sevigny 饰）恋爱了，还和拉娜的前男友成为好友——尽管他们粗野、酗酒，行为暴戾，但被接纳的布兰顿却得到了认同感。生活朝着布兰顿想要的方向发展，一次交通违章却暴露了所有的秘密。布兰顿被识破女儿身，尽管拉娜原谅了她，悲剧却发生了。拉娜的前男友对布兰顿怒不可遏，将她摧毁在一场残忍的暴力事件中。©豆瓣', '希拉里·斯万克', '金伯莉·皮尔斯', 8.2, 43236, 'tt0171804', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167014595.jpg', 0.3, 1.4, 18.1, 50.8, 29.4, '0.434338,0.154205,-0.603307,0.442608,-0.243760,-0.057816,0.737514,0.022958,-0.358705,-0.265940,0.219608,0.844716,-0.373598,0.014683,0.306469,0.295004,-0.279055,-0.752251,0.183742,-0.385291,-0.142610,-0.337043,-0.430664,-0.130179,-0.215506,-0.455470,0.525186,0.075029,-0.346639,0.326732,0.385142,0.670491,-0.020360,0.555684,-0.033910,0.112076,0.125232,-0.259379,-0.285209,0.168083,-0.083093,0.043869,-0.077699,0.456390,0.047636,0.607739,0.432268,-0.320775,-0.229791,-0.082578,0.426113,-0.368545,0.013518,0.253111,0.055605,-0.192392,0.142715,0.108418,-0.200641,-0.028567,0.182740,-0.209087,-0.621173,0.005561,0.197554,0.316762,-0.633847,0.384993,-0.191365,-0.194422,-0.041515,-0.330904,-0.004538,0.099271,0.344098,0.402658,0.045696,0.317530,-0.567833,-0.080531,0.655895,0.256456,-0.508767,0.219986,-0.403440,-0.341899,0.168654,-0.222532,-0.446919,0.017402,0.375234,0.063280,0.049434,0.313719,-0.699617,-0.209501,-0.422346,-0.110218,0.267868,-0.472225,-0.313172,-0.506010,-0.357092,-0.498474,-0.268802,0.009100,-0.139688,-0.485595,0.508639,-1.077992,0.252037,0.476272,0.536036,-0.692228,0.260127,0.181496,0.137785,-0.150168,-0.170409,0.571495,0.083664,0.123146,0.115331,0.318910,0.018413,-0.238169,-0.352055,0.592429', '1301022', '1299556', '1308755', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300537', '虎胆龙威2', '动作', '圣诞前夕，麦卡伦（布鲁斯•威利斯 饰）正在华盛顿的机场等待妻子霍莉（邦尼•彼地丽娅 饰）乘飞机归来过节。然而无意中他却发现了一个重大的阴谋：被议会解职的特种部队施上校正率领部下准备解救被引渡的中美洲毒枭艾将军。麦卡伦将此事告知了机场警卫队的罗队长，但后者的官僚作风和愚蠢却使这一切未能得到阻止。施上校带领部下占领了机场附近的一座小教堂，设置了一个飞行控制中心，并切断了机场控制塔与空中的一切联系，使众多的客机无法降落。而麦卡伦的妻子霍莉此时却正在其中的一架飞机上。为了解救妻子和在空中的众多客机，麦卡伦不得不再次进行艰苦的努力。©豆瓣', '布鲁斯·威利斯', '雷尼·哈林', 7.8, 48602, 'tt0099423', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1617433132.jpg', 0.2, 1.4, 24.8, 54.2, 19.5, '0.414663,0.152398,-0.796868,0.885010,0.084999,-0.213504,0.631543,0.232728,-0.370395,-0.372948,0.186156,0.729470,-0.099274,0.132139,0.311735,0.031644,-0.518421,-0.675667,-0.358625,-0.026461,-0.513216,-0.608710,-0.205680,-0.252269,-0.037557,-0.068859,0.676376,0.280222,0.068313,0.623805,0.266296,0.236670,-0.203468,0.730813,-0.182810,-0.100599,0.283025,-0.179073,-0.122338,0.280358,-0.054271,-0.418810,0.153921,0.292828,0.047667,0.609596,0.766071,-0.276945,-0.008709,-0.262522,-0.012284,-0.490090,0.454772,0.188710,0.437457,0.136131,-0.047193,0.005619,-0.261501,-0.074629,0.053912,-0.012924,-0.658645,-0.175845,-0.056216,-0.155661,-0.445508,0.197149,-0.235744,0.253778,0.073603,-0.290680,0.363742,0.548867,0.079580,0.268680,-0.084853,0.052048,-0.536627,-0.013424,0.625578,-0.242777,-0.141577,0.137877,-0.127006,-0.435209,0.067781,-0.041108,-0.323017,-0.194825,0.326381,0.175572,0.049755,0.061935,-0.426441,-0.137225,-0.755831,-0.311802,-0.187748,-0.512430,0.049021,-0.899567,0.188646,-0.175675,-0.030168,0.359981,0.032680,0.289010,0.465083,-0.722084,0.285923,0.541256,0.340178,-0.281664,0.594810,0.156043,0.390129,-0.192002,0.117964,0.175650,0.116956,0.671714,0.127044,0.300690,-0.154410,-0.220768,-0.505237,0.167526', '1550450', '20274039', '2159244', '3735015');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300553', '等待黎明', '动作', '叶剑飞（周润发 饰）从小在戏班长大，对生活现状很是不满意的他一直想要到美国，希望能够在那里出人头地，但他的偷渡计划却屡屡失败。一次偶然中，叶剑飞结识了名叫黄克强（万梓良 饰）的男子，两人一见如故，结为了好友。黄克强和青梅竹马阿男（叶童 饰）两情相悦，无奈阿男的父亲却要 将阿男嫁给她并不喜欢的富家子弟，黄克强和阿男决定私奔。然而，就当三人跃跃欲试之际，战争爆发了，出国的计划再次流产。之后，阿男惨遭巡警强暴，黄克强终于得到了阿男父亲的认可，而叶剑飞则成为了“日军太保”，至此，三人依然没有忘记当初的约定，他们登上了难民船，开始了他们最后的旅行。©豆瓣', '周润发', '梁普智', 7.8, 5849, 'tt0087137', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2454904654.jpg', 0.5, 1.8, 26.5, 50, 21.2, '0.154231,-0.018921,-0.702176,0.473164,0.002611,-0.634638,0.642451,0.031834,-0.474048,-0.169273,0.086614,0.740339,-0.132144,0.197037,0.174305,0.063142,-0.357108,-0.622262,-0.001655,-0.240188,-0.144702,-0.502205,0.077883,-0.109387,-0.369791,-0.132675,0.878605,0.137196,-0.146758,0.596932,0.429763,0.153570,0.038312,0.679153,-0.405659,0.173469,0.110289,0.075881,-0.522853,0.298092,0.198564,-0.261429,-0.104453,0.356812,0.115804,0.256843,0.783490,-0.265178,-0.055620,-0.165099,0.080189,-0.198526,-0.044583,0.203528,0.317148,0.004148,0.260092,0.098507,0.090117,-0.263236,0.097418,-0.026056,-0.232177,0.064630,0.246640,0.015617,-0.545724,0.484593,-0.066828,0.048057,0.102162,-0.374008,0.130915,0.562089,0.412090,0.138514,-0.296883,0.170546,-0.541003,0.288097,1.030162,0.058470,0.066937,0.426540,-0.107976,-0.680491,0.021914,-0.079921,-0.443779,0.208521,0.424767,0.204330,-0.253036,0.246069,-0.279762,-0.099885,-0.103750,0.244749,-0.004262,-0.469251,0.177931,-0.394243,-0.298005,-0.414757,-0.291006,0.179952,-0.139088,-0.323288,0.584360,-0.965993,0.098883,0.262703,0.493184,-0.638779,0.604769,0.335610,0.011936,-0.373876,0.285761,-0.025271,-0.106176,0.079797,0.313129,0.372336,0.053255,-0.146201,-0.245592,0.331320', '25721544', '35030151', '1301022', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300555', '回到未来', '喜剧', '布朗博士（克里斯托弗•洛伊德 Christopher Lloyd 饰）总是有些稀奇古怪的发明。在一次试验他发明的时光机器时，他找来了忘年交高中生马丁（迈克尔•J•福克斯 Michael J. Fox 饰）。岂料实验过程中博士被歹徒杀害了，马丁慌乱中架着时光机逃跑，回到了30年前。马丁遇到了30年前的父亲乔治（克利斯丁•格拉夫 Crispin Glover 饰）和母亲洛莲（莉•汤普森 Lea Thompson 饰）。马丁一边找寻30年前的布朗博士，好让自己回到未来；一边尽力撮合乔治和洛莲，以免自己在以后消失了。但乔治为人懦弱，马丁在撮合过程中弄巧成拙让洛莲爱上了自己。还有令人讨厌的贝夫从中作梗，令马丁恼怒不已。马丁周旋在他的双亲之间，还要尽快找到博士，想办法回到未来……©豆瓣', '迈克尔·J·福克斯', '罗伯特·泽米吉斯', 8.7, 192969, 'tt0088763', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p475872903.jpg', 0.1, 0.5, 9.5, 42.5, 47.4, '0.150327,-0.039702,-0.651419,0.467149,-0.158710,-0.727462,0.687195,0.078638,-0.684551,-0.465037,-0.088952,0.645113,-0.284967,0.264593,0.251965,0.272212,-0.780374,-0.550207,0.229496,-0.044588,-0.361522,-0.717766,-0.174539,-0.553076,-0.093586,-0.402616,0.214079,-0.019646,0.085134,0.216024,-0.049115,0.505926,0.216229,0.323017,-0.147236,0.242640,0.144600,-0.228089,-0.376832,0.207961,0.550620,-0.146445,-0.125692,0.101638,0.023402,0.261351,0.547857,-0.073827,0.369199,0.166664,0.064320,-0.345462,0.126428,-0.000802,-0.047040,-0.117529,-0.065657,0.170251,-0.291551,0.028324,0.208574,0.069395,-0.662487,0.300450,-0.113814,0.074886,-0.648639,0.277710,-0.328513,0.455197,0.294783,-0.332234,0.161482,0.397820,0.484279,0.151172,-0.225611,0.049772,-0.526986,0.256724,0.560876,-0.007986,0.252866,0.227180,-0.080085,-0.200878,0.045480,-0.078922,-0.508882,-0.097361,0.445629,-0.092563,-0.073489,0.283283,-0.586119,-0.305552,-0.607608,0.071034,-0.080569,-0.262107,-0.097369,-0.538035,0.097926,-0.146095,-0.306517,-0.202788,-0.177660,-0.487496,0.479489,-0.559586,0.294837,0.768686,0.154411,-0.058822,0.634776,-0.010278,0.137829,-0.197834,-0.180144,0.172173,0.092633,0.235037,0.195579,0.426283,0.347744,-0.267941,-0.184191,0.378940', '1907467', '1307442', '1410557', '27093707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300566', '赌侠', '剧情', '得赌神毕生绝技的刀仔（刘德华 饰）在龙五（向华强 饰）的陪同下重出江湖，代表师父以赌技致力慈善事业，人称赌侠。遇到欲拜赌神为师号称赌圣的阿星（周星驰 饰）后，两人互展计谋绝技，打成平手。 侯赛因（单立文 饰）为替被赌神击败的义父陈金城报仇，在赌船上打着赌神旗号骗尽东南亚阔佬钱财，欲使赌神身败名裂，并设计挟持了龙五和阿叔（吴孟达 饰）等人，以期封住刀仔的口，不把他的真实身份揭穿。为了赌神的声誉，刀仔和阿星一用赌技绝学一用特异功能，并肩合作与侯赛因在赌桌上展开了智斗。©豆瓣', '刘德华', '王晶', 7.9, 190297, 'tt0101763', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1987598517.jpg', 0.2, 1.8, 26.9, 47.1, 24, '-0.231432,-0.002597,-0.247524,0.530935,-0.096587,-0.146072,0.074640,0.107853,-0.077297,-0.273365,0.325892,0.631653,0.093687,-0.082681,0.180806,-0.235919,0.011591,-0.680938,-0.138351,0.161877,0.015122,-0.224082,-0.269351,0.065530,-0.434300,-0.070133,0.232554,-0.101495,-0.405960,0.505829,0.635396,0.096176,-0.095425,-0.032428,-0.088970,0.030522,-0.277312,-0.009138,-0.651785,0.302864,-0.066052,-0.433448,0.034814,0.047811,-0.043075,0.113612,0.389964,-0.159385,0.287114,-0.239432,-0.053258,-0.266473,-0.143773,-0.098232,0.011823,0.024884,0.195036,0.125242,-0.094634,0.063050,0.376244,-0.137618,-0.911080,-0.089695,0.286388,-0.249521,-0.751928,0.274131,-0.431110,-0.012505,-0.188268,-0.103287,0.242704,-0.113727,0.326416,-0.031508,-0.007406,0.050087,-0.597300,0.459508,0.407054,-0.059850,0.540649,0.096724,0.491444,-0.194255,-0.086445,-0.224700,0.030291,-0.138307,0.517015,-0.349668,0.117695,-0.038272,-0.310452,-0.436028,-0.059825,0.319816,0.051236,-0.402655,0.377003,-0.408915,-0.128546,-0.242465,0.205021,-0.220700,0.320200,-0.368780,0.464109,-0.692815,-0.123071,0.109875,0.103056,-0.299653,0.681040,0.214341,-0.024749,-0.174506,-0.616189,-0.184124,0.527040,0.239948,0.244514,0.374511,0.237271,-0.146436,-0.046681,0.330198', '1793491', '4301278', '1299649', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300572', '童年往事', '剧情', '从大陆迁往台湾的一家人，在表面平静的日子下，各怀心事。祖母（唐如韫）对大陆念念不忘，一心想回去；父（田丰）母（梅芳）虽也有“外省人” 身份的尴尬，却也清楚知道回大陆只是梦一场；姐姐（萧艾）差不多已当自己是台湾本地人，偶尔伤心落泪是因想起为替父母分重担放弃了念大学；小孩子阿孝咕（游安顺），则只想着自己如何玩得痛快，完全没有大陆的概念，而对父亲的死，他只觉突然并无太多伤心。可是因为家庭的特殊，懵懂中阿孝咕也知自己并不完全相同于同龄人。尽管表面上他做着多数成长中男孩都会做的事（四处打架、开始中意某个女孩子），内里却已埋下会突然裂变的种子，只等某个契机的来临。©豆瓣', '游安顺', '侯孝贤', 8.9, 52221, 'tt0090185', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2259777287.jpg', 0.2, 0.7, 7.6, 38.2, 53.3, '0.146812,0.183134,-0.793820,0.331208,-0.103308,-0.187401,0.589662,-0.155853,-0.537464,-0.282983,0.014782,0.822519,-0.049514,0.449671,-0.188470,0.242695,-0.183395,-0.463827,0.239643,-0.289808,-0.056267,-0.426175,-0.252373,-0.123308,-0.161162,-0.061710,0.427679,0.162688,-0.054915,0.108702,0.229416,0.120097,-0.036283,0.901782,-0.221243,-0.100420,-0.519665,0.436477,-0.170912,-0.443639,0.148399,-0.158165,-0.274778,0.036066,0.260447,0.481484,0.469179,-0.265917,-0.268619,-0.088944,0.248707,-0.111325,-0.017900,-0.030028,0.406012,-0.076080,0.165775,0.163001,0.018969,0.187799,-0.023815,-0.048581,-0.492799,0.029132,0.339590,0.190237,-0.517910,0.564435,0.024315,-0.209857,-0.037951,-0.176002,0.257118,0.521750,0.257603,0.611240,-0.209354,0.015047,-0.274523,0.215075,0.701391,0.367766,-0.222994,0.478437,-0.250802,-0.410074,0.159445,-0.208180,-0.226682,-0.030232,-0.169156,0.161496,-0.305104,0.318508,0.023359,0.234249,0.094129,-0.182925,0.016154,-0.657482,-0.065094,0.091166,-0.021105,-0.424004,-0.377843,-0.007885,0.258805,-0.202657,0.652921,-0.834320,0.196033,0.371754,0.259075,-0.701977,0.456094,0.410501,0.047642,-0.399739,-0.036663,0.373911,-0.349921,0.017849,0.008951,0.122511,0.092884,-0.128897,-0.311276,0.462120', '26718282', '26420626', '1292064', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300575', '岁月风云之上海皇帝', '剧情', '小贩陆云生（吕良伟 饰）常为邻里抱不平，被租界总探氏黄金荣（郑则仕 饰）妻阿桂姐（斯琴高娃 饰）所赏识。未几，陆破获宋教仁被刺案真相，令黄名声大噪。黄对陆赏识，却招侯飞妒忌。陆、黄出面调息了军阀袁啸军劫取法国鸦片事件，发了财，变为大亨。由于黄误打了督军卢永祥之子，陆又去东北军军长毕树政处求情，还搭进了名妓老六（刘嘉玲饰），无奈卢、毕进一步勒索，被陆寻机反击。1927年，陆目睹国共反目，他反对镇压工人武装与屠杀共产党人；为了不被国民党利用，他打入商界，以经济力量与国民党抗衡......©豆瓣', '吕良伟', '潘文杰', 8, 17391, 'tt0105381', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2043222004.jpg', 0.3, 1.5, 21.2, 52.3, 24.8, '-0.426938,0.208118,-0.400282,0.424854,0.147233,-0.147607,0.361079,0.170494,-0.498059,-0.241309,-0.348314,-0.045678,-0.193217,0.260527,0.192446,-0.562148,0.012035,-0.488934,0.032762,0.354845,-0.150516,-0.585392,-0.320769,-0.584413,-0.335953,0.195075,0.294762,0.682579,-0.681016,-0.015301,0.841622,0.344260,-0.018911,0.524769,0.113164,0.249037,0.043038,0.043785,-0.160032,-0.277297,0.019955,-0.982481,0.084889,0.028783,0.391855,0.399090,0.219092,0.016774,0.236174,-0.454027,0.176763,-0.224928,0.243875,0.319015,0.421723,0.086928,0.076694,-0.138092,-0.193752,-0.105011,0.202114,0.037802,-0.102476,0.004282,0.393188,-0.291444,-0.433637,0.087560,-0.229185,0.432282,-0.413213,0.037655,0.054794,0.765996,0.236900,0.019799,0.124055,0.129915,-0.541145,0.747762,0.548097,0.173587,-0.152919,-0.556770,0.017972,-0.395021,-0.027478,-0.182662,0.177480,-0.262847,0.750802,-0.378264,0.624894,0.330161,-0.365896,-0.723022,-0.016519,0.449579,0.118343,0.013257,0.510974,-0.592522,-0.298685,-0.358011,0.171895,0.265295,0.313618,-0.339771,0.311488,-0.290398,-0.244683,-0.019728,0.521662,-0.849322,0.382190,0.117025,0.064839,-0.265949,0.278965,0.318313,0.651036,0.100083,0.665262,0.052747,-0.204008,-0.167811,0.370937,-0.110862', '1297497', '3626416', '1302110', '4822848');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300581', '至尊无上', '剧情', '有“亚洲第一快手”之称的陈亚蟹（刘德华 饰）因出老千入狱，刑满出狱后，他的搭档Sam（谭咏麟 饰）第一时间令助手波波（关之琳 饰）迎接。亚蟹刚获得自由，便同Sam合演了一出里应外合扮猪吃老虎的好戏。不久，两人受朋友所托，远赴美国调查日本出千团伙，结果顺利为赌场挽回损失，令日本人颜面扫地，日本方面自此寻机报复。Sam在美国结识了富家大小姐童可人（陈玉莲 饰），Sam使出众多浪漫桥段抱得美人归，也令岳父接纳了自己，但代价却是要疏远亚蟹等不体面的朋友。同时，日本出千集团首脑宫本父子加紧了报仇的步骤，亚蟹为搭救Sam，被对方废了自己引以为傲的快手。面对宫本的咄咄逼人，亚蟹与Sam兄弟俩终于再次联手对敌。©豆瓣', '谭咏麟', '向华胜', 7.4, 12642, 'tt0098708', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2610191804.jpg', 0.6, 3.8, 36.7, 42, 16.9, '-0.157445,0.096952,-0.462126,0.217691,0.053740,-0.293768,0.180176,0.149041,-0.389746,-0.127469,0.174721,0.556725,-0.306090,-0.122035,0.124726,-0.195483,-0.092494,-0.698750,0.036701,-0.057668,-0.021091,-0.149055,-0.178136,-0.337593,-0.131808,-0.052929,0.421214,0.145305,-0.089325,0.486732,0.357820,0.201697,-0.003030,0.167153,-0.027858,-0.090669,0.168880,0.063626,-0.569162,0.371121,-0.104018,-0.334461,-0.094478,0.174939,-0.092354,0.424603,0.359664,-0.024264,-0.160291,-0.365825,0.184731,-0.231762,-0.041644,0.086397,0.308366,-0.096467,0.357515,0.207625,-0.286803,-0.081368,-0.032513,-0.000505,-0.699316,0.146882,0.407355,-0.351341,-0.413908,0.211456,-0.173098,-0.047706,0.186830,-0.066308,0.074333,0.662954,0.434176,0.062431,0.048434,0.328364,-0.247877,0.246202,0.671875,-0.093317,0.179189,-0.019377,0.263997,-0.247446,0.275057,-0.554015,0.127047,0.023696,0.439183,-0.042256,0.101181,0.010245,-0.269606,-0.264243,-0.432356,0.221058,0.158210,-0.487044,0.281650,-0.727774,-0.081071,-0.053367,0.025537,0.158963,0.379924,-0.236310,0.709766,-0.423126,-0.019196,0.528783,0.374053,-0.645531,0.430977,0.078512,-0.104865,-0.166735,-0.125192,-0.093996,0.140901,0.067030,0.258921,0.219149,-0.018185,-0.330528,-0.087481,0.138475', '4301278', '26678784', '26365022', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300605', '烈火情人', '剧情', '即将入职的内阁部长史蒂夫（杰瑞米•艾恩斯 Jeremy Irons 饰）同妻子英格丽、儿子马丁（拉珀特•格雷夫斯 Rupert Graves 饰）平静安逸地生活着。安娜（朱丽叶•比诺什 Juliette Binoche 饰）的出现像是一股汹涌的暗流冲撞着这个看似完满的家庭。安娜是儿子的女朋友，却背地里与史蒂夫展开了一段热烈浪漫的关系。安娜曾经在青春期里与哥哥的畸恋记忆一直影响着她，这使她一面寻找各种机会和史蒂夫约会，一面又能泰若自然的面对马丁，而当史蒂夫提出要抛弃家庭与她厮守时安娜却冷静地拒绝。某日马丁开门见到二人相会的情景，震惊和痛苦使他不慎跌下楼梯，史蒂夫匆忙下楼抱着死去的儿子，安娜此时却无声地离开，只留下身后中年男人无法重建的坍塌生活。©豆瓣', '杰瑞米·艾恩斯', '路易·马勒', 7.3, 30884, 'tt0104237', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1260972092.jpg', 0.9, 4.4, 37.9, 41.7, 15.1, '0.258491,0.166337,-0.783354,0.553805,-0.115202,-0.556058,1.079632,0.275963,-0.450352,-0.185958,0.304592,0.771030,-0.298232,0.475675,0.413115,0.249496,-0.628260,-0.805090,-0.151549,0.332782,0.022877,-0.435100,-0.182500,-0.082844,-0.091504,-0.213695,0.532166,-0.147690,-0.122686,0.673545,0.138503,0.275862,-0.253444,0.689450,-0.016871,0.095448,-0.016230,0.124439,-0.495403,-0.079228,0.303982,-0.132736,-0.329109,0.081099,0.062809,0.229227,0.475564,-0.343552,0.039368,0.040839,0.323652,-0.064980,0.165359,0.239771,-0.091422,0.147056,0.329757,0.170509,-0.011416,-0.094407,0.262831,-0.031791,-0.323075,0.211914,-0.088352,0.417810,-0.529201,0.363028,-0.195034,0.077915,0.319455,-0.406895,-0.014786,0.346895,0.151633,0.643159,-0.449938,0.215798,-0.369842,0.019912,0.612514,0.042541,-0.260711,0.235918,-0.413102,-0.211223,-0.016821,0.032022,-0.746819,-0.229038,0.388527,0.253748,-0.139420,0.458673,-0.448859,-0.023903,-0.381279,0.128422,-0.132858,-0.325119,-0.118134,-0.597207,0.022827,-0.339308,-0.476656,0.013428,-0.257425,-0.191289,0.410769,-0.578780,0.292269,0.426193,0.586963,-0.018242,0.538686,0.353998,0.104582,-0.245674,-0.030008,0.539221,-0.403769,0.122865,0.100081,0.316614,0.052731,0.173977,-0.418589,0.621275', '1296534', '1309172', '21348112', '1301582');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300608', '夕阳天使', '动作', '亚洲电脑业巨头周氏兄弟发现其公司内部的电脑系统于一夜之间感染病毒全部瘫痪，四处求救之时，一个自称“天使”的神秘高手出手相助，麻烦成功解除，令周氏兄弟十分钦佩。出于好奇，他们提出与“天使”见面道谢，不想应约而至的“天使”是一对拥有天使面容的姊妹花——陈爱琳（舒淇）和陈爱群（赵薇），而之前的电脑中毒事件，也是由这对姊妹花一手策划：她们是想借此突破周氏公司森严的保安系统，实施更大的阴谋。女警江日红（莫文蔚）闻得风声，在爱琳和爱群实施阴谋时展开调查，不想仍让她们得手。随后，在周氏兄弟的策划下，爱琳死于乱枪之下，可是现场留下的指纹却是江日红的。无奈之下，江日红与爱群联起手来，两人逐渐由敌手变作朋友。©豆瓣', '舒淇', '元奎', 6.7, 58789, 'tt0300620', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2050555311.jpg', 1.6, 9.7, 51.2, 28.6, 9, '0.160809,0.111502,-0.625052,0.506202,0.146787,0.061980,0.623981,0.031872,-0.417588,-0.165920,0.299928,0.586890,-0.249976,0.150740,0.165607,-0.285076,-0.118287,-0.666651,-0.176050,-0.025647,-0.003779,-0.466142,-0.232103,-0.104186,-0.272073,-0.417331,0.516106,0.245639,-0.157635,0.385233,0.383026,0.329315,-0.436136,0.438109,0.219770,-0.187339,-0.183696,-0.194688,-0.544303,0.343758,0.079773,-0.052589,-0.242085,0.306321,-0.245496,0.380070,0.292842,-0.184536,-0.266750,-0.425724,0.258745,-0.231510,-0.136399,0.104492,0.480078,-0.083859,0.286739,-0.017519,-0.038378,-0.076601,0.236247,0.131360,-0.779693,0.228522,0.196545,0.113921,-0.384157,-0.022413,-0.370913,0.114044,0.026669,-0.268655,0.289094,0.424599,0.429765,0.157420,0.013607,0.324522,-0.338815,-0.107119,0.489031,0.163111,0.006098,0.062317,-0.098535,-0.364235,-0.070921,-0.205552,-0.034241,0.204016,0.289980,0.211107,0.018653,0.147216,-0.556446,-0.088272,-0.314987,0.021669,-0.116844,-0.466837,-0.051202,-0.526620,-0.172850,-0.119785,-0.272208,0.111848,0.210965,-0.283127,0.428328,-0.990232,-0.000811,0.086041,0.395084,-0.456740,0.364410,0.103114,-0.027149,-0.190927,-0.262540,-0.200490,0.122768,0.370565,0.226224,0.174299,-0.029059,-0.055782,-0.173487,-0.145767', '30345227', '1301022', '1793491', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300613', '土拨鼠之日', '剧情', '菲尔（Bill Murray饰）是个气象播报员，每天除了在摄像机前给观众做风趣幽默的天气预报外，每年的2月2日他还要前往一个名为普苏塔尼的边境小镇，报导当地的土拨鼠日庆典。事实上，菲尔对这一节日相当嗤之以鼻并开始对工作感到厌倦，当他例行公事完成今年的报导后，便急不可待地想重返家园，却因为一场突如其来的暴风雪耽搁了。第2天醒来后，菲尔意外地发现时间仍然停留在前一天土拨鼠日，昨日的一切重新上演。惊讶、不信、刺激、狂喜、烦闷、焦虑、不安、绝望、倦怠等各种情绪轮流侵占菲尔的感官领域，可无论他如何选择度过这一天，他都始终无法再前进一步，开始了他重复的人生。©豆瓣', '比尔·默瑞', '哈罗德·雷米斯', 8.6, 182718, 'tt0107048', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493191199.jpg', 0.1, 0.6, 10.9, 46.1, 42.3, '-0.131391,0.097299,-0.979671,0.483876,0.439435,-0.123476,0.712605,-0.028985,-0.615503,-0.261556,-0.002246,0.116419,-0.499573,0.349826,0.458503,-0.104592,-0.575043,-0.531145,-0.017885,-0.126693,-0.241599,-0.289143,0.026843,-0.302883,-0.079533,-0.332529,0.152112,0.365363,0.171662,0.569616,0.220088,0.059397,0.275429,0.791742,0.206167,-0.238972,0.087281,0.019637,-0.204569,0.075567,0.179593,-0.071396,-0.418447,0.355624,-0.018420,0.361619,0.687732,-0.024154,-0.474018,-0.052826,0.375869,-0.155774,-0.162342,0.179879,0.183949,0.194748,-0.137268,0.100801,-0.229915,0.288067,-0.190786,0.069204,-0.663514,0.153852,-0.253246,0.154163,-0.343773,0.440394,-0.187202,0.151090,-0.219486,-0.383411,-0.133103,0.483038,0.374249,0.431291,-0.065291,0.159078,-0.167027,-0.027213,0.569014,-0.009021,-0.444741,0.686203,0.027685,-0.320855,0.123461,0.098288,-0.396097,0.085443,-0.124556,0.333772,-0.224043,0.345281,-0.488627,0.045766,-0.293037,-0.677158,-0.096062,-0.320093,-0.253547,-0.546873,0.173042,-0.166570,-0.357548,-0.080646,0.322440,-0.117525,0.397700,-0.690335,0.403831,0.550365,0.061365,-0.355628,0.286575,0.372721,0.024475,-0.043834,-0.122370,0.213113,-0.171891,0.523848,0.019021,0.290349,0.053066,-0.060809,-0.303033,0.600105', '2002683', '3011051', '25839662', '4724373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300616', '买凶拍人', '喜剧', '职业杀手Bart（葛民辉饰）技艺高超，雇主很多，收入不俗。他与妻子阿玲（方子璇饰）居于高级住宅区，小日子过的非常滋润。可惜好景不长，金融风暴后夫妻二人陷入经济危机。Bart迫于无奈，便为有钱太太杀人服务，不想有钱太太要求苛刻，要Bart在杀人之余还得拍下杀人过程，方泄心头之恨。Bart深明顾客至上的道理，决定找一个拍档合作。凑巧Bart在酒吧见到导演阿全（张达明饰），二人一拍即合，成为了杀手导演二人组，一时间生意大增，一连串的“买凶拍人”行动随即展开。后来江湖大佬标哥听闻，决定聘Bart及阿全代劳，杀死社团叛徒大雄，并要拍下影带，好让他有真凭实据能向社团交代，稳坐执事人一职。这次买凶拍人行动能否成功呢？©豆瓣', '葛民辉', '彭浩翔', 8.2, 138948, 'tt0312932', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1361412292.jpg', 0.7, 2.1, 16.6, 47, 33.7, '-0.158506,0.000451,-0.180417,0.164292,0.070487,-0.205240,0.146564,0.324646,-0.493366,-0.077601,0.323375,0.418743,-0.182672,-0.218994,0.352881,-0.165962,-0.158538,-0.252942,0.140758,0.027168,0.024310,-0.258037,-0.020691,-0.361572,-0.254534,-0.049871,0.124737,-0.039011,-0.204309,0.182475,0.376903,0.125562,-0.076003,0.055510,-0.138188,-0.134930,0.008612,-0.051274,-0.734752,0.228710,-0.030579,0.030686,-0.159714,-0.200997,0.163280,0.238317,0.155004,0.106179,-0.430229,0.012762,0.239075,-0.195996,-0.199031,-0.111663,0.184121,0.044533,0.387499,0.202143,-0.067443,-0.037475,-0.035560,0.005831,-0.635816,0.148194,0.451119,-0.224644,-0.566940,0.227420,-0.247226,0.103665,-0.243187,-0.181233,-0.302584,0.177651,0.211630,0.133646,0.366554,0.333790,-0.169479,0.341199,0.757333,-0.056761,0.218542,0.104209,0.100583,-0.228694,0.234139,-0.344626,-0.004648,0.107183,0.298078,-0.124091,0.076848,-0.039074,-0.132296,-0.119453,-0.155166,0.034138,0.268683,-0.323595,0.045762,-0.395712,-0.082991,0.168035,-0.317289,-0.015606,0.334800,-0.126473,0.508396,-0.655797,-0.137465,0.100799,0.446775,-0.425817,0.421534,0.068990,-0.059209,-0.270764,-0.312988,-0.515842,0.137805,0.134541,0.258337,-0.063345,0.031776,-0.516424,0.031762,-0.267319', '1296978', '1877596', '1308424', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300618', '空中监狱', '剧情', '空中监狱是美国运送全美最危险的罪犯而专设的飞机。卡麦伦（尼古拉斯•凯奇 Nicolas Cage  饰）坐上这趟飞机，不是因为他罪恶滔天，而是他为了赶在女儿生日那天，亲手给女儿一份礼物而申请的一次飞行。他在狱中表现良好，典狱官答应了他这个请求。然而，却有一个难题——在这趟飞机上，还押送着一帮杀人狂魔。警探非常留神随时可能出现的危险，但防不胜防的是，飞行过程中那帮暴徒还是挟持了飞机上全部的警察，卡麦伦也被迫帮他们完成逃脱任务。地面的联邦部队决定把飞机打下，把狂徒一网打尽，身陷险境的卡麦伦该逃出这个空中监狱？©豆瓣', '尼古拉斯·凯奇', '西蒙·韦斯特', 8.2, 174975, 'tt0118880', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p946632521.jpg', 0.2, 1, 17.4, 52.2, 29.2, '0.207507,0.084027,-0.653461,0.677995,-0.250409,-0.017474,0.442161,0.018987,-0.368898,-0.036499,0.390853,0.793593,0.268505,0.036098,0.281129,0.179187,-0.355694,-0.424854,0.045395,-0.079033,-0.624253,-0.474547,-0.179314,-0.258312,0.070263,-0.128701,0.648528,0.312879,0.102428,0.449197,0.235103,0.098192,-0.042192,0.782230,-0.486886,-0.234946,0.009672,-0.152708,0.087414,0.451025,-0.135732,-0.476817,0.184696,0.303999,0.161938,0.257964,0.663394,0.075195,-0.148824,-0.186949,0.091813,-0.906192,0.032188,-0.052941,0.315198,-0.149467,-0.037172,0.033898,-0.190371,0.001026,0.080675,-0.090145,-0.777443,-0.102486,-0.233659,-0.172809,-0.837028,0.113526,-0.377551,0.420097,0.006278,-0.233815,0.263642,0.268642,0.020944,0.086953,-0.338609,-0.056026,-0.746170,0.048742,0.667618,-0.423581,-0.077349,0.005459,0.149845,-0.434798,0.174126,-0.259836,-0.239439,0.104665,0.283140,-0.086850,-0.350961,-0.106507,-0.333129,-0.040696,-0.601823,-0.219620,-0.266473,-0.560260,-0.148349,-0.492037,0.227997,-0.015219,-0.436534,0.030148,0.064759,-0.104230,0.347155,-0.439552,0.295601,0.920285,0.262723,-0.468888,0.634779,0.244707,0.247949,-0.268328,-0.018415,-0.223928,0.244576,0.509717,0.013596,0.247648,0.091251,-0.251453,-0.258799,0.312767', '1292584', '1292849', '27018354', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300656', '终结者', '动作', '这是一个未来的世界，天下已经由机器人来操控。机器人想完全占有这个世界，把人类赶尽杀绝，然而却遇到了顽强抵抗的人类精英康纳。于是，终结者机器人T-800（阿诺•施瓦辛格 Arnold Schwarzenegger饰）受命回到1984年，杀害康纳母亲莎拉（琳达•汉密尔顿 Linda Hamilton 饰），目的是灭掉康纳的出生。 康纳得知后，火速派战士雷斯（迈克尔•比恩 Michael Biehn 饰）前往救援。雷斯来到1984年的洛杉矶，及时搭救了被机器人追杀的莎拉——她当时还是一个大学生。然而，人们把雷斯当成疯子，不相信未来机器人统治世界。 直到莎拉又一次遭到机器人追击，她才相信了这一切。奔走中她和雷斯相爱，怀上了未来的康纳，而雷斯也陷入和机器人的苦斗当中。人类世界能否从因为这场斗争改变原来的噩运？©豆瓣', '阿诺·施瓦辛格', '詹姆斯·卡梅隆', 8.2, 192903, 'tt0088247', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p511430453.jpg', 0.1, 0.9, 17.4, 52, 29.6, '-0.031242,0.119663,-0.675240,0.285251,-0.343316,-0.204972,0.660988,-0.275945,-0.433293,-0.290017,0.265912,0.834249,0.164384,0.064423,0.422551,-0.002548,-0.519413,-0.502939,0.092234,-0.172443,-0.320729,-0.421804,-0.344051,-0.390792,0.302461,-0.519349,0.677835,-0.109485,-0.174015,0.326841,-0.038931,0.360504,-0.185048,0.418024,0.269460,0.172839,0.459960,-0.158213,-0.373778,0.415165,-0.248802,0.155117,0.008003,0.218955,-0.333251,0.266309,0.578421,-0.792021,0.202427,-0.451241,0.127452,-0.530681,-0.039581,-0.011131,0.267770,-0.260601,-0.214222,0.316857,0.045790,0.156445,0.066691,-0.111267,-0.914324,0.094631,-0.055055,-0.061427,-0.688360,0.341900,-0.179803,0.110092,0.018250,-0.271661,0.177990,0.655154,0.687214,0.441068,-0.181230,-0.056887,-0.579786,-0.110234,0.697062,-0.165721,-0.511532,0.194415,-0.022484,-0.495695,-0.100608,-0.260825,-0.539496,0.023067,0.227621,0.054719,-0.291519,0.564004,-0.504027,-0.168421,-0.672643,-0.247192,0.250425,-0.509722,-0.205877,-0.374736,-0.021862,-0.097600,-0.298609,-0.211258,-0.066441,-0.209358,0.619171,-0.665409,0.266366,0.527303,0.356184,-0.630131,0.569056,-0.045885,0.199464,-0.337391,0.167094,0.512152,0.210353,0.356387,0.109556,-0.030940,0.036288,-0.199445,-0.349364,0.223824', '26678784', '1793491', '30163500', 