INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300659', '空中大灌篮', '喜剧', '美国NBA传奇人物迈克•乔丹（Michael Jordan）在事业最顶峰之际引退篮坛，决定转入职棒。与此同时，怪物行星的太空游乐场经营遭遇窘境，游乐场老板派出手下的小怪物们前往地球，目的是绑架华纳公司包括兔八哥、太妃鸭、三只小猪等在内的动画片明星们为游乐场招揽顾客。为了维护自由，动画明星们紧急磋商对策，他们自作聪明认为外星怪物身材短小，于是决定采取篮球比赛的方式决定胜负。不过动画明星的如意算盘落空，小怪物们暗中盗取了皮蓬、巴克利等NBA明星们的球技，变成了身形健壮修长、球技高超的怪物篮球手。眼看败局已定，兔八哥紧急找来迈克•乔丹助阵，决定动画明星去留的时刻越来越近……©豆瓣', '迈克尔·乔丹', '乔·皮特卡', 7.1, 39786, 'tt0117705', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p843918684.jpg', 1.1, 5.8, 44.3, 35, 13.9, '0.009134,-0.149644,-0.327849,0.106965,0.063368,0.012672,0.084886,0.386505,-0.075932,-0.400971,0.395486,0.418177,-0.354113,-0.096041,0.131764,-0.584742,-0.252307,-0.570363,-0.205756,0.053942,0.181414,-0.127044,-0.223986,-0.367944,0.075250,-0.046070,0.889060,-0.117446,-0.047391,0.238115,0.374814,0.131026,-0.040874,-0.195111,0.066406,-0.277740,0.402303,-0.271433,-0.445527,0.377330,-0.365642,0.137938,-0.156604,-0.069063,-0.018504,0.098295,0.709623,-0.139598,0.077644,-0.518918,0.153282,-0.245176,0.098669,0.175624,0.457098,0.034516,0.317131,-0.199772,0.265973,0.147454,-0.006179,-0.277955,-0.493320,0.204177,-0.026875,0.052772,-0.357780,-0.299674,-0.153820,0.228905,0.162591,-0.546095,0.022873,-0.060486,0.302691,-0.075552,0.124120,0.538684,-0.196312,0.021433,0.468867,0.247309,0.062522,-0.040064,0.085662,-0.430481,-0.109608,-0.463341,-0.162393,-0.047682,0.288397,-0.212449,-0.211335,0.271610,-0.457227,-0.026006,-0.155423,-0.435630,0.035680,-0.337237,0.063620,-0.919556,0.167954,0.031717,0.098780,0.018757,0.214781,0.149038,0.914395,-0.535159,-0.159200,0.653244,-0.060519,-0.476175,0.649696,-0.126977,0.109607,-0.209759,0.014056,-0.360511,-0.175128,0.153253,-0.189173,-0.006139,-0.030728,-0.395940,-0.319352,0.236435', '2369613', '5403927', '1322847', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300678', '没事偷着乐', '喜剧', '张大民（冯巩 饰）对工作敬业，对家庭负责。就算一家六口都要挤在小小的平房里，但一家人相处还算融洽。大民到了适婚年龄都没有结婚，是因为他一直喜欢邻居云芳。这时候云芳失恋了，大民默默陪伴安慰终于得到了云芳的芳心。两人婚后不久，大民的三弟也要结婚了。为了腾出更多的地方，大民推倒围墙建起了一间房间，以解决房间不够的问题。不久两人的孩子出生了，大民也更加忙起来了。身为长子的他又要帮忙兄弟姐妹解决生活上的不如意，大民依然以积极的态度面对生活。大民的厂里终于分配给他一套楼房，但一直期待拥有自己房间的小妹在这时候因患有绝症离世了，大民痛心不已……©豆瓣', '冯巩', '杨亚洲', 7.8, 41224, 'tt0269537', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2540317418.jpg', 0.3, 1.5, 27.4, 49.7, 21.1, '0.118631,-0.225079,-0.665177,0.127401,-0.168002,-0.306795,0.569443,0.223290,-0.470144,-0.267857,0.012196,0.714938,-0.138748,0.406876,-0.083511,-0.068311,-0.332172,-0.323456,0.048846,-0.015714,-0.443094,-0.498628,-0.023366,-0.312547,-0.292134,-0.020681,0.253188,-0.023665,0.137083,0.211194,0.283297,-0.048619,0.186420,0.384718,-0.248075,0.061522,-0.247108,0.232579,-0.234157,-0.080740,0.034240,-0.108393,-0.270690,0.163804,0.467967,0.399714,0.439902,0.171002,-0.425177,0.074405,0.133065,0.044533,-0.190595,-0.125084,0.372825,-0.114701,0.400711,0.294747,-0.337816,-0.058379,0.006143,-0.271076,-0.571854,0.254467,0.168637,-0.255282,-0.509884,0.483187,0.135243,-0.165737,0.077500,-0.489742,0.179934,0.687541,0.061633,0.747434,-0.397273,0.067918,-0.488820,0.112151,0.611935,-0.048248,0.009972,0.615577,-0.434776,-0.250412,0.167588,-0.302295,-0.494414,-0.157857,0.074381,0.177711,-0.347899,-0.051367,-0.181396,0.169201,-0.226963,-0.180278,0.173600,-0.470702,0.067979,-0.218762,-0.194810,-0.318782,-0.349971,0.206860,0.017677,-0.246133,0.837848,-0.801031,0.046982,0.021707,0.670326,-0.763749,0.613354,0.171223,0.307143,-0.041283,0.112721,-0.059290,-0.239659,0.191893,0.353625,0.164351,-0.299567,-0.318789,-0.439198,0.263919', '1877596', '1308367', '1308805', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300685', '克莱默夫妇', '剧情', '克莱默夫妇像普通的美国夫妇一样，克莱默先生（达斯汀•霍夫曼 Dustin Hoffman 饰）在外工作挣钱，克莱默夫人（梅丽尔•斯特里普 Meryl Streep 饰）则在家照料照料6岁的儿子比利（贾斯汀•亨利 Justin Henry 饰）。由于克莱默先生忙于工作忽略了家庭，克莱默夫人某天愤然出走，留下了父子两。克莱默先生现在一方面要忙于工作，一方面又要照顾比利，生活一时陷入麻烦中。克莱默先生不善家务，在照料比利时洋相百出：第一次为比利煎西多士、过程十分恐怖；比利不吃饭要吃雪糕，克莱默先生想阻止却不懂沟通……幸好在女邻居的帮助下，克莱默先生逐渐适应了单身父亲的生活。父子两越来越亲密，互相依赖。这时，克莱默夫人回来了，她已经是纽约一名出色的设计师了。她回来要拿回比利的抚养权……©豆瓣', '达斯汀·霍夫曼', '罗伯特·本顿', 8.5, 65679, 'tt0079417', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1646672189.jpg', 0.1, 0.5, 11.2, 49.8, 38.4, '0.075258,-0.313670,-0.252848,0.152705,0.046543,-0.897401,0.532738,0.569523,-0.426100,-0.655228,0.048553,0.507977,0.227710,0.150599,0.286730,0.022672,-0.515361,-0.038752,0.076637,0.156680,-0.028270,-0.630783,-0.197669,-0.283562,-0.253419,-0.395921,-0.043809,-0.461475,0.206446,0.452780,0.062685,0.231643,0.129592,0.359803,0.083378,0.093724,0.202455,-0.099185,-0.739239,0.230444,0.264014,0.397913,-0.132534,-0.227416,0.568420,0.336160,0.243999,0.164429,-0.077453,-0.158264,0.136128,-0.032092,0.257693,0.081760,0.407396,-0.115257,0.334332,0.204348,-0.339060,-0.074893,-0.081389,-0.143722,-0.388726,0.273998,0.157115,0.242951,-0.713527,0.166151,-0.271324,-0.183315,0.001191,-0.397287,0.071111,0.539140,0.159432,0.380654,0.122565,0.191047,-0.219522,0.180107,0.750044,0.034728,0.023621,0.263405,-0.151612,0.024745,0.305504,-0.306994,-0.794298,-0.084822,0.030579,-0.056305,-0.034903,0.355421,-0.200965,-0.159568,-0.275791,-0.088466,-0.005222,-0.442983,0.049519,-0.567491,0.000399,-0.371399,-0.031700,-0.145932,0.245924,-0.137354,0.489322,-0.675788,0.286959,0.364587,0.329981,-0.251635,0.538552,0.336555,0.259320,-0.252366,-0.046284,0.023885,0.177199,-0.137795,0.113149,0.315210,0.204707,-0.084892,-0.186521,0.050192', '1297239', '1308035', '1295316', '3447595');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300714', '飞龙猛将', '喜剧', '华氏企业下属的化工厂所产废料污染了附近的渔场，渔场负责人阿娴（叶德娴）向法庭申请禁止该厂继续生产的禁令。为将麻烦解除，华氏企业请来律师阿龙（成龙）负责处理此案，并授权他收购渔场。阿龙找来好友黄飞鸿（洪金宝）和阿彪（元彪）帮忙，此二君一个武艺高强，一个虽身手敏捷但头脑不大灵光。阿彪在渔场安下窃听装置，黄飞鸿则想方设法接近阿娴，力劝她卖掉渔场，而阿娴也找来表妹水质专家美玲（杨宝玲）帮忙。阿龙初见美玲，便被对方深深吸引，不久两人陷入热恋中，黄飞鸿与阿娴的感情也日渐浓烈。阿彪不小心泄露了三人的本来意图，令阿娴与美玲失望过后分别与阿龙和黄飞鸿绝交。此事促使阿龙一伙发现工厂相瞒的秘密。©豆瓣', '成龙', '洪金宝', 7.6, 16799, 'tt0093015', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1994755138.jpg', 0.4, 1.9, 34.3, 45.5, 17.9, '0.189767,-0.128257,-0.553368,0.244652,-0.038438,-0.346906,0.453153,0.082453,-0.423513,-0.289678,0.022789,0.688027,0.113732,-0.078612,0.028275,0.054445,-0.308447,-0.348745,-0.028190,-0.001213,0.049399,-0.459257,-0.053173,-0.226136,0.003794,-0.010076,0.373827,-0.265967,-0.358032,0.576706,0.033032,0.028741,-0.391898,0.470046,0.245909,-0.001556,0.181403,-0.209592,-0.594258,0.183335,0.118309,-0.104481,0.006277,-0.139589,0.204006,0.474234,0.474054,0.284853,-0.373271,-0.123065,0.187689,-0.306639,0.184828,-0.143776,0.321361,-0.032669,0.079856,0.391100,-0.447482,0.052180,0.069271,0.011832,-0.522742,0.081506,0.198014,0.021443,-0.379931,0.184108,-0.095846,-0.062111,-0.172079,-0.388636,0.212180,0.260551,0.035048,0.156338,-0.321514,0.147389,-0.318248,0.123473,0.405558,-0.033707,0.234960,-0.017530,0.102873,-0.352065,0.201275,0.041015,-0.142571,-0.096416,0.361358,0.103418,-0.264996,-0.001703,-0.568379,-0.241184,-0.113979,-0.045231,-0.134725,-0.270205,0.229283,-0.635314,-0.179253,-0.207022,-0.191340,-0.137972,0.306611,-0.008518,0.355919,-0.443580,-0.154218,0.337390,0.467876,-0.563342,0.384746,0.023821,0.201378,-0.476494,-0.229781,-0.507864,0.237386,0.323233,0.295606,0.276982,0.150037,-0.273525,-0.253516,-0.308077', '1303333', '11541282', '1293019', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300738', '夺命剑', '剧情', '德川幕府时代，会津藩马回队武士笹原伊三郎（三船敏郎 饰）剑术高超，为人则恪守职责，忍辱负重。某日，藩主松平政容（松村达雄 饰）将爱妾阿市（司叶子 饰）以大不敬的罪名赶出藩邸，并命其下嫁伊三郎的长子与五郎（加藤刚 饰）。迫于对藩主的忠诚，笹原家最终接受了这门婚事。婚后与五郎和阿市相亲相爱，婚姻美满。然事情突然发生变化，阿市于城中生养的儿子成为藩主继承人，为免有失体统，藩主欲将阿市召回。不满藩主的出尔反尔，伊三郎强硬拒绝了来使的无理要求。双方剑拔弩张，伊三郎和与五郎不惜以鲜血维护武士不可侵犯的荣誉……本片荣获1967年英国电影学会奖萨瑟兰郡奖，1968年电影旬报之最佳导演、最佳影片和最佳剧本，1968年每日电影奖最佳影片，1967年威尼斯电影节费比西奖国际影评人奖。©豆瓣', '三船敏郎', '小林正树', 9, 8926, 'tt0061847', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2314224800.jpg', 0.2, 0.3, 6.7, 35.1, 57.7, '-0.561463,-0.035101,-0.177865,0.596236,0.470440,-0.149305,0.205378,0.253513,-0.408817,-0.486043,0.235021,0.803715,-0.092329,-0.083463,0.544657,-0.137162,-0.138347,-0.826986,-0.023150,-0.014269,0.226302,-0.415310,0.046359,-0.257061,-0.582381,-0.290639,0.797144,-0.016421,-0.074663,0.504367,0.488291,0.213323,0.063315,-0.091162,0.298057,0.192202,0.005327,-0.010457,-0.479638,0.124912,-0.086379,-0.397372,-0.388529,-0.116792,0.377525,0.177595,0.517948,-0.312900,-0.042444,-0.410071,0.370488,-0.302279,-0.227934,0.241211,0.286035,-0.046826,0.202618,0.489165,-0.141280,-0.011427,0.205541,-0.279342,-0.479106,-0.107472,0.294427,-0.221960,-0.517899,0.526518,-0.292593,-0.022972,0.067993,-0.300445,-0.005825,0.175445,0.346403,0.163030,-0.400878,0.229212,-0.178626,0.407131,0.300520,0.005785,-0.054714,-0.212356,-0.123391,-0.581264,-0.010209,-0.841990,-0.340757,0.102770,0.134916,0.044595,0.398099,0.241591,-0.142596,-0.608957,-0.105062,-0.042234,0.519459,-0.376573,0.171317,-0.347447,0.105632,-0.356304,-0.239587,0.091138,0.323457,-0.099648,0.735654,-0.508115,-0.035952,0.197862,0.454940,-0.481583,0.501654,0.198034,0.175518,-0.164424,-0.198623,-0.132743,0.044081,0.075517,0.249546,-0.058911,-0.095250,-0.089925,-0.126697,0.068207', '1780122', '25880986', '1440164', '1306998');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300741', '枪火', '剧情', '黑社会老大文哥（高雄 饰）被人追杀，其弟阿南（任达华 饰）安排五个人来做其兄的保镖，并命令他们查出暗杀文哥的幕后人物。这五人分别是阿鬼（黄秋生 饰）、阿来（吴镇宇 饰）、阿Mike（张耀扬 饰）、阿信（吕颂贤 饰）和阿肥（林雪 饰）。阿来和阿信是知名的高手，阿鬼、阿Mike、阿肥则是金盆洗手的昔日英雄：阿鬼是文哥以前的手下，阿Mike是神枪手，阿肥是枪械专家。五人同心协力，将杀手擒获，并查清了幕后主使人。五个不认识的江湖人成为肝胆相照的好友，这时，阿南告诉阿鬼，阿信与文哥之妻通奸，要求阿鬼去杀死阿信，阿来坚决不允许这么做。阿Mike和阿肥又分别支持阿来和阿鬼，最后他们约定在一家小餐厅解决这个问题，互相对准的枪口真是一触即发……©豆瓣', '吴镇宇', '杜琪峰', 8.8, 204670, 'tt0220644', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1538646661.jpg', 0.2, 0.7, 9.4, 38.6, 51, '0.160751,-0.292706,-0.264846,0.377106,-0.068229,-0.210563,0.499743,0.053164,-0.231336,-0.444002,0.239193,0.189058,0.243145,-0.115016,0.058773,-0.289265,-0.266526,-0.598244,-0.141006,-0.247713,-0.221679,-0.595088,0.057587,-0.107762,-0.008498,0.100402,0.185272,-0.322250,-0.190122,0.558635,0.728875,0.208960,-0.185817,0.313252,-0.077412,0.156885,0.172021,-0.176942,-0.462239,0.114714,-0.097707,-0.002758,0.002902,0.018867,0.214970,0.346061,0.457590,-0.179859,0.033113,-0.311142,-0.094419,-0.231728,0.033804,-0.187471,0.395649,-0.213583,0.148535,0.233879,0.141059,-0.013724,0.113270,0.096614,-0.626701,0.044339,0.398049,0.114513,-0.560886,0.138374,-0.277528,-0.033101,0.110827,-0.338772,0.366355,0.137357,0.330703,0.181402,0.200197,0.031865,-0.670082,0.122050,0.741411,0.052575,0.486386,-0.199077,0.113246,-0.816380,-0.128804,0.121089,-0.188385,0.121017,0.351894,-0.297845,0.022307,0.069799,-0.196032,-0.265584,0.058681,0.350884,-0.019161,-0.537604,0.410017,-0.512134,-0.070319,-0.208774,-0.103798,0.359271,-0.091006,-0.098811,0.637553,-0.619478,-0.045302,0.277033,0.594611,-0.279108,0.662470,0.252612,0.022139,-0.462646,-0.134300,-0.410608,0.559392,-0.091417,0.311408,0.313331,0.206229,-0.073666,-0.070872,-0.279888', '2084048', '4301278', '1917577', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300752', '座头市', '剧情', '盲剑客座头市（北野武饰）来到一个小镇上，他染着金发，身怀绝技，出手致命。服部源之助（浅野忠信饰）是名武艺高强的剑客，他为了筹钱给妻子（夏川结衣饰）治病也来到小镇，想要寻找一份工作。与此同时，一对为了复仇，化装成艺妓流浪卖艺的野子姐弟（大家由佑子、橘大五郎饰）也来到此地，他们的目标是镇上恶霸银藏和扇屋等。好打抱不平的座头市得知其中隐情后，决定帮助姐弟俩报双亲被杀之仇，而服部却成了敌人所雇佣的保镖，一场生死大战在所难免。©豆瓣', '北野武', '北野武', 8.1, 45184, 'tt0363226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p764956497.jpg', 0.3, 1.5, 19.1, 51.6, 27.4, '0.149390,-0.228999,-0.018161,0.231475,-0.243490,-0.182597,0.261790,0.115906,-0.274171,-0.475647,0.439386,0.800049,0.201257,0.214651,0.355669,-0.030159,0.123320,-0.553181,-0.056083,-0.227323,-0.070993,-0.287544,-0.111669,-0.170861,-0.268277,-0.051860,0.485786,0.112624,-0.040336,0.509323,0.554010,0.540276,-0.348535,-0.079903,-0.318367,0.023704,-0.083324,-0.221187,-0.429556,0.354136,-0.340762,-0.288768,-0.132484,0.066881,-0.209303,0.301696,0.786220,0.109901,0.017443,-0.262799,0.041268,-0.432980,0.105156,0.324868,0.267284,-0.239946,0.374535,0.149054,-0.181677,-0.088800,0.069058,-0.192501,-0.438175,0.064232,0.479780,0.121667,-0.603453,0.404306,-0.182492,-0.340175,0.110130,-0.091451,0.131511,0.401751,0.399534,-0.016984,-0.080649,0.001289,-0.369729,0.146937,0.736336,-0.278669,0.478284,0.102245,0.215194,-0.187378,0.214564,-0.178918,-0.192737,-0.087289,0.246740,-0.024728,-0.136341,-0.267750,-0.606944,-0.180816,-0.439809,0.138664,0.104919,-0.294507,-0.038552,-0.604941,-0.047757,-0.088342,-0.390507,0.382177,0.314969,0.001643,0.559203,-0.715032,0.024401,0.480612,0.186178,-0.422643,0.515609,-0.041897,0.146249,-0.323646,-0.044141,-0.023712,0.301602,0.271326,0.024887,0.070372,-0.305923,-0.128018,-0.332391,0.055835', '3811356', '11541282', '30345227', '1296978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300754', '人性污点', '剧情', '希尔克（安东尼·霍普金斯 Anthony Hopkins 饰）是一名大学教授，深受同事和学生们的信赖和喜爱。希尔克有一个美丽贤惠的妻子和三个伶俐可爱的孩子，他的生活堪称人生赢家的典范。然而，在希尔克的内心里隐藏着一个惊人的秘密，虽然他对外谎称自己是犹太人，但实际上，他却是一名非裔，只不过肤色极淡几乎无法察觉。这个秘密让希尔克内心里充满了自卑。某日，希尔克在课堂上的一个无心的用词让他的生活产生了翻天覆地的变化。他丢掉了工作、朋友，妻子和孩子也离开了他。在绝望之中，希尔克结识了名为福尼亚（妮可·基德曼 Nicole Kidman 饰），悲惨的童年经历让福尼亚心中充满了伤痛和自卑，但正是这样的相似令希尔克和福尼亚坠入了爱河，两人成为了彼此唯一的依靠。©豆瓣', '安东尼·霍普金斯', '罗伯特·本顿', 7.2, 9518, 'tt0308383', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1357941900.jpg', 0.6, 4.8, 42.1, 40.9, 11.5, '0.424623,-0.055015,-0.874754,0.950468,-0.194446,-0.392596,1.244995,-0.015979,-0.532783,-0.353807,0.045627,1.021759,-0.191883,0.321400,0.314067,0.159873,-0.169164,-0.747667,-0.082897,-0.260744,-0.178833,-0.466687,-0.422781,-0.465862,-0.333678,-0.345744,0.568726,0.117009,-0.098390,0.625727,0.133532,0.522650,0.255498,0.415769,-0.133200,0.078655,0.203301,-0.071573,-0.062700,0.102222,0.353878,0.003550,-0.060997,0.506325,-0.016574,0.580343,0.795410,-0.466744,-0.239888,0.086751,0.330693,-0.242239,-0.143968,0.303578,0.048028,-0.267188,0.119538,-0.020704,-0.295279,-0.198913,0.220121,0.128984,-0.934906,-0.132003,0.170972,0.062947,-0.638422,0.480557,-0.120478,-0.210512,0.061665,-0.128304,0.236066,0.074519,0.213524,0.633653,-0.147921,0.134847,-0.538367,0.019722,0.740871,0.204487,-0.439269,0.222714,-0.791162,-0.514003,-0.190768,-0.361316,-0.807429,-0.111475,0.242159,0.038183,0.060021,0.571090,-0.535728,0.003494,-0.203415,-0.035926,-0.058110,-0.632306,-0.120091,-0.264348,-0.378743,-0.646577,-0.632895,0.015206,0.085477,-0.379273,0.911492,-0.856094,0.363684,0.386695,0.087720,-0.474058,0.887796,0.286699,0.294938,-0.392211,-0.083477,0.521382,0.037434,-0.177770,0.195045,0.578547,-0.169787,0.071744,-0.436040,0.815238', '24756472', '1292062', '26884422', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300766', '美人计', '剧情', '二战刚刚结束，莉亚（英格丽·褒曼 Ingrid Bergman饰）作为战犯的女儿被美国联邦调查局相中，利用她对父亲罪恶的负疚和其父在纳粹阵营内的关系网络，深入调查纳粹首脑契巴斯（克劳德·雷恩斯Claude Rains饰），获得情报将其定罪。联邦调查员迪奥（加里·格兰特Cary Grant饰）在与莉亚合作的过程中，深深爱上这个迷人的姑娘。然而二人感情还是要服从国家利益，因此他将私情搁置一边，忍痛让莉亚成为契巴斯身边的女人。莉亚深深失望的同时，也在契巴斯的生活中充当了间谍的角色，处于危机四伏的环境当中。等到莉亚终于发现了契巴斯的关键情报，不料却被契巴斯发现了自己的真实身份。然而，契巴斯也有自己投鼠忌器的顾虑，为了置莉亚于死地，契巴斯设计了一个不动声色的计谋。莉亚境况堪忧，间谍计划悬念重重。©豆瓣', '加里·格兰特', '阿尔弗雷德·希区柯克', 7.7, 35568, 'tt0038787', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p828519563.jpg', 0.3, 2.3, 29.1, 49.1, 19.3, '0.411023,0.365303,-0.679822,0.695788,0.014305,-0.067881,0.478811,0.094636,-0.501886,-0.326916,0.166947,0.774282,0.020169,-0.043565,0.112695,0.139445,-0.572603,-1.091122,-0.029947,-0.236656,-0.208407,-0.818237,-0.354464,-0.366565,-0.353438,-0.288257,0.655119,0.124585,0.019633,0.221065,0.338287,0.501177,-0.093907,0.322034,0.342410,-0.064280,0.531970,-0.503138,-0.579938,0.438155,-0.015298,0.004285,-0.134058,0.402127,-0.028886,0.560118,0.622286,-0.420913,0.002374,-0.229483,0.294463,-0.247684,0.141040,0.126532,0.066045,-0.186835,-0.080732,0.276958,-0.528938,0.202316,0.191284,0.027067,-0.777113,0.042834,-0.060710,0.292254,-0.480527,0.631705,-0.331838,-0.050569,0.172886,-0.011977,0.197581,0.243883,0.493390,0.146604,-0.189453,0.108755,-0.361014,-0.362725,0.263471,0.060993,-0.237122,0.136661,-0.305889,-0.567792,-0.094753,-0.272193,-0.131030,-0.177947,0.431338,0.150352,-0.056023,0.756453,-0.574229,-0.133394,-0.422114,0.028997,-0.113613,-0.382808,0.127503,-0.436907,-0.397997,-0.207427,-0.461403,0.158447,0.094982,-0.229536,0.486559,-0.621916,-0.017196,0.421074,0.300776,-0.325768,0.302383,0.227288,0.380239,-0.430723,-0.155055,0.397534,0.267725,-0.076481,0.337490,0.037872,0.240212,-0.184262,-0.202513,0.507548', '1307442', '20440456', '30205168', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300774', '五亿探长雷洛传2：父子情仇', '剧情', '上集的末尾，雷洛（刘德华 饰）遇上了阿霞（邱淑贞 饰），并见到自己的儿子雷用贤，原来当年阿霞被亲戚带到了东莞，逃过了那场大火，当时已有身孕。雷诺自觉愧对他们母子，和妻子白月嫦（张敏 饰）商量后，准备纳阿霞为妾，谁知此时，港英政府宣布废除大清律例，执行一夫一妻制，阿霞无奈 之下，带着儿子远走他乡。十多年之后，一家人再次重逢。此时的雷洛荣升总华探长，经历了偏门百花齐放的六十年代，累积了巨额财富，成为当时社会最叱诧风云的人物，不过潜在的危险也渐渐袭来；阿霞一人在海外辛苦，供儿子念书，身染重病；儿子雷用贤（郭富城 饰）大学毕业，是港英政府筹建廉政公署而招揽的人才，对父亲的所作所为深恶痛绝。阿霞病危，雷洛带伤到医院探望，雷洛的仇家也追杀到了医院，儿子雷用贤看见父亲陷入险境，心中也展开了激烈的天人交战……©豆瓣', '刘德华', '刘国昌', 7.5, 37227, 'tt0105846', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1273856967.jpg', 0.4, 2.7, 35.8, 44.6, 16.5, '-0.032886,-0.074973,-0.669759,0.271643,0.115214,-0.354915,0.385708,0.279482,-0.738880,-0.241743,0.294727,0.635964,-0.111862,0.330621,0.423934,-0.214841,-0.157006,-0.518064,-0.062600,-0.112633,-0.296564,-0.352199,0.007308,-0.134025,-0.155834,-0.202181,0.338896,0.174950,0.126320,0.529462,0.271382,0.342342,-0.218608,0.295181,-0.195950,0.272866,-0.019807,0.159622,-0.428135,0.099193,0.151956,-0.365541,-0.178553,0.156865,0.073616,0.376859,0.491051,0.045079,-0.032953,-0.282706,0.367361,-0.250931,-0.225572,0.035826,0.420884,0.035768,0.088064,0.233716,-0.064871,-0.127000,-0.171336,-0.073633,-0.430696,0.210591,0.052714,-0.147392,-0.581821,0.374923,-0.095244,0.088336,-0.033185,-0.171081,0.292006,0.482061,-0.150237,0.410955,-0.353364,0.153961,-0.328415,0.363478,0.623266,-0.217741,0.177766,0.241082,0.013922,-0.221059,0.320962,-0.389877,-0.299099,0.062457,0.162140,0.136058,-0.075824,0.293364,-0.135592,-0.288801,-0.349077,0.071351,0.122690,-0.187029,0.023097,-0.322125,-0.278107,-0.257273,-0.348492,0.231814,0.026804,-0.199796,0.373713,-0.524568,0.176025,0.094879,0.401079,-0.690028,0.487075,-0.124142,0.243057,-0.239383,0.027107,0.153712,-0.014117,0.038484,0.217664,-0.097610,-0.189563,-0.218931,-0.188698,0.102272', '27621189', '35461732', '25721544', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300779', '浪荡儿', '剧情', '影片的主人公是年近30岁的5位年轻人，他们终日游手好闲，热衷于恶作剧并沉溺于梦幻般不切实际的计划里。其中最年长的浮士德让最年少的摩拉德的妹妹桑德拉怀了孕，基于责任心及周围人的力劝而结了婚。浮士德在一家古董店工作，但因为恶习不改企图勾引店主的老婆而被解雇。一天，桑德拉得知浮士德带着一名舞娘到一家廉价的旅馆过夜，于是第二天她带着孩子离家出走；狼狈的浮士德第一次感到桑德拉的重要性。于是和她的兄弟四人拼命寻找桑德拉的下落，终于找到桑德拉的浮士德一边遭到父亲的痛斥；一边恳求桑德拉的原谅。见到二人重修旧好的摩拉德在次日清晨不辞而别，踏上了自己的旅程。', '弗朗科·英特朗吉', '费德里科·费里尼', 8.4, 8832, 'tt0046521', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2363177837.jpg', 0.3, 0.8, 12, 51.6, 35.3, '0.502396,-0.066045,-0.774629,0.559052,-0.031833,-0.525268,0.676392,0.135388,-0.663737,-0.484897,0.254049,0.802945,-0.198489,0.536769,0.596065,0.054784,-0.377760,-0.459592,-0.108191,0.079260,-0.305905,-0.556284,0.062188,-0.330721,-0.269529,-0.287951,0.385565,0.143189,0.057124,0.588884,0.399325,0.273571,-0.096367,0.345123,-0.222300,0.010854,0.171084,-0.012006,-0.334659,0.251980,0.357199,-0.214457,-0.243151,-0.000959,-0.154772,0.391972,0.706305,-0.284068,0.014193,-0.044308,0.382896,-0.417404,-0.059997,0.094032,0.220292,-0.152245,0.181420,0.226316,-0.207757,0.032897,-0.089584,-0.157427,-0.448124,0.128312,0.222874,0.076541,-0.537944,0.458061,-0.022176,0.202305,0.400590,-0.378296,-0.080599,0.237202,-0.149341,0.516259,-0.216066,0.140685,-0.633902,-0.081266,0.535901,0.037057,0.116893,0.445982,-0.086357,-0.167921,0.145850,-0.297630,-0.710537,-0.028234,0.184572,0.204368,-0.212170,0.155925,-0.729457,-0.237991,-0.185872,-0.163377,0.264255,-0.276667,-0.217974,-0.558248,-0.015704,-0.251876,-0.209314,0.282735,0.070002,-0.263941,0.607060,-0.625584,0.263733,0.558986,0.198920,-0.539980,0.725904,-0.012101,0.323358,-0.216722,-0.222142,0.453492,0.096079,-0.039321,0.042354,0.290001,-0.253553,-0.213115,-0.409344,0.389458', '3055049', '1414808', '4319218', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300802', '玛戈王后', '剧情', '十六世纪后半叶，法国处于“胡格诺战争”时期，天主教和新教残酷战争不断。而宫廷内部也奢华淫靡，腐败不堪。为了平息连年内战，信仰天主教的法国宫廷决定将玛格丽特公主（Isabelle Adjani 伊莎贝尔·阿佳妮 饰）嫁给新教徒的首领纳瓦尔国王亨利（Daniel Auteu il 丹尼尔·奥德耶 饰）。1572年8月24日，婚礼在巴黎隆重举行。正当人们沉浸在欢乐的气氛中时。凯瑟琳皇后（Virna Lisi 饰）却下达命令，发动了一场针对新教徒的血腥大屠杀，即西方历史上著名的惨案——“圣巴托罗缪之夜”……影片改编自大仲马的名著，荣获1994年戛纳电影节最佳女主角（维尔娜·丽丝）和评审团大奖，1995年凯撒电影节最佳女主角、最佳女配角、最佳男配角最佳剧本和最佳服装设计等多项大奖。©豆瓣', '伊莎贝尔·阿佳妮', '帕特里斯·夏侯', 7.8, 36255, 'tt0110963', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196127498.jpg', 0.3, 2, 27.3, 47.6, 22.7, '-0.227470,0.223076,-0.494032,0.596868,0.762806,0.034028,0.475057,0.040051,-0.492118,-0.298861,0.326574,0.823442,-0.519776,-0.196937,0.884408,0.072337,-0.918566,-0.706314,-0.154853,-0.008606,0.052476,-0.244654,-0.097381,-0.045829,-0.300356,-0.581501,0.786419,0.144270,0.075388,0.657917,0.452249,0.219315,0.135873,-0.125236,0.265166,-0.028092,0.510729,-0.291911,-0.673524,0.523879,0.021808,-0.397346,-0.469293,0.205309,0.264370,0.055928,0.485240,-0.776559,0.551505,-0.168491,0.790447,-0.494943,-0.277652,0.379652,0.211284,-0.234092,0.277104,0.454654,0.005420,-0.089021,0.009078,-0.516594,-0.470481,0.352915,-0.141494,-0.055350,-0.200944,0.731839,-0.144844,0.349602,0.070144,0.041300,0.314251,0.551806,0.398117,0.197908,-0.125538,-0.044807,-0.263007,0.609962,0.403348,-0.004896,-0.375012,0.110893,-0.131446,-0.704927,-0.247701,-0.583898,-0.328435,-0.079184,0.424946,-0.161842,0.234507,0.466048,-0.482962,-0.246584,-0.330830,-0.615740,0.409837,0.129535,-0.231033,-0.978784,-0.193346,-0.137035,-0.018051,-0.346085,0.024444,0.027921,0.573709,-0.584052,0.464613,0.517276,0.075963,-0.274071,0.567939,0.027020,0.140400,-0.289721,-0.421982,0.574502,-0.295034,-0.035060,-0.125195,0.174647,-0.086847,-0.259651,-0.023644,0.472820', '3275168', '1298616', '1291859', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300820', '罗塞塔', '剧情', '对于在贫穷中挣扎的人们，活下去就是人生最大的意义。18岁的萝赛塔（艾米莉·德奎恩 Émilie Dequenne饰）就是这么一个命运多舛的女子。她的母亲是个自暴自弃的酒鬼，没有谋生能力，沉湎于和底层男人们的性事当中，生活的担子，完全落在了萝赛塔的肩上。母女俩住在流动车上，萝赛塔还没能找到固定的工作，但她的心底却有着倔强的求生意念。在这样恶劣的人生境遇中，为了求得一份工作，她甚至不惜与唯一的朋友交恶。只因友情在生存面前显得太过脆弱。命运没有眷恋这个顽强的少女，她终于在人生的半路陷入崩溃，选择自杀。然而，命运又一次给了她无情的嘲笑。©豆瓣', '艾米莉·德奎恩', '让-皮埃尔·达内', 8.2, 14212, 'tt0200071', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187719666.jpg', 0.4, 1.4, 15.8, 51.1, 31.2, '0.195898,0.144449,-0.797500,0.845678,-0.601085,-0.440334,1.075077,0.171305,-0.462758,-0.169829,0.362506,0.783312,0.119663,0.352631,0.079831,-0.186980,-0.077200,-0.696880,-0.117092,0.087172,-0.293808,-0.309534,-0.262920,-0.160003,-0.410677,-0.293360,1.174537,0.324397,-0.327650,0.040176,0.296845,0.378475,0.108524,0.569737,-0.514128,-0.144689,-0.270968,0.070658,-0.184966,0.035031,0.116782,-0.294460,-0.187894,0.493707,-0.127675,0.278128,0.806576,-0.436793,-0.255030,0.096694,0.360298,-0.307566,-0.222318,0.110370,0.042586,-0.276114,0.160523,0.071075,-0.329757,-0.067154,0.370738,-0.112733,-1.034398,-0.325792,0.098877,0.126950,-0.730004,0.626336,0.042407,-0.087795,-0.060467,-0.375374,0.100816,0.299521,0.276752,0.560757,-0.567776,-0.147203,-0.405519,0.136809,0.753418,-0.038953,-0.451615,0.681579,-0.494200,-0.471269,-0.134059,-0.464007,-0.728981,-0.187397,0.148889,0.169558,-0.451323,0.458353,-0.660741,0.241889,-0.242974,-0.151543,-0.059708,-0.842485,-0.190735,-0.154346,-0.203266,-0.401200,-0.345736,0.252455,0.121285,-0.364545,0.779582,-0.936311,0.329628,0.645924,0.237752,-0.352880,0.809144,0.344102,0.167653,-0.064003,-0.034678,0.615740,-0.233780,0.223525,0.043712,0.237956,-0.135911,0.261089,-0.495305,0.816201', '35287908', '4840388', '1304641', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300830', '狂蟒之灾', '动作', '在蜿蜒流长的亚马逊河流域的雨林深处，生活着古老而神秘的舒尔族。他们与世隔绝，以食人蛇为叩拜图腾。围绕着舒尔族人的传说和秘密让雨林之外的人们振奋不已。人类学家史蒂文•凯（埃瑞克•斯图尔茨 Eric Stoltz 饰）对舒尔人颇感兴趣，他和纪录片导演泰莉•劳瑞（杰妮佛•洛佩 兹 Jennifer Lopez 饰）组成一个七人摄制组，前往雨林为这神秘的部族拍摄纪录片。路上，他们搭救了一个名叫保罗•沙龙（琼•沃纳 Jon Voight 饰）的男子，保罗自告奋勇带摄制组寻找舒尔人，却不曾想这个男人的真正目的竟是寻找一条恐怖的食人巨蟒。蒙在鼓里的史蒂文等人就次踏上一条充满血腥的不归路……本片荣获1998年ALMA拉丁媒体艺术奖最佳女主角奖（Jennifer Lopez）、1998年BMI百代最佳电影音乐奖、1998年世界动画庆典最佳3D制作。©豆瓣', '詹妮弗·洛佩兹', '路易斯·罗沙', 6.7, 47918, 'tt0118615', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1261715918.jpg', 1.2, 7.9, 53.5, 29.7, 7.8, '-0.135027,-0.374020,-0.562408,0.851770,0.391726,-0.065161,0.791376,-0.101258,-0.417111,-0.141041,0.190159,0.752957,-0.307065,0.032413,0.493529,0.125002,-0.550613,-0.426843,-0.176886,-0.229280,-0.180284,-0.011446,-0.386855,-0.322731,-0.049026,-0.409622,0.681294,0.044818,0.008635,0.500235,0.291327,0.366863,-0.361240,0.039453,-0.136015,0.041192,0.383774,-0.223341,-0.182210,0.174577,-0.310017,-0.163642,-0.407091,0.235364,-0.157503,0.358196,0.680682,-0.569463,0.180380,-0.079348,0.196832,-0.483262,0.101116,-0.155301,0.182852,-0.441861,0.223454,0.193170,-0.059105,-0.113910,-0.062317,-0.395033,-0.726423,0.056639,0.095735,0.288282,-0.325204,0.303641,0.110573,0.009340,0.050161,-0.191771,0.074296,0.033679,0.315086,0.135611,0.227256,-0.013908,-0.266659,0.449262,0.421233,-0.058963,-0.123103,0.123335,-0.379906,-0.545635,-0.213900,-0.057095,-0.607245,-0.158068,0.485203,-0.071483,-0.013427,0.063648,-0.723361,0.034618,-0.118647,-0.388804,0.057135,-0.059210,-0.423216,-0.688412,0.004739,-0.088182,0.069336,-0.038027,-0.050231,-0.114087,0.589230,-0.317763,0.370776,0.615912,0.077723,-0.311480,1.066278,-0.386031,-0.106537,-0.402417,-0.260354,0.267156,0.031470,0.076037,0.059915,0.444357,0.037350,-0.118698,-0.370926,0.484545', '1292925', '1293433', '2334814', '25837262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300857', '侠盗高飞', '剧情', '这是周润发早期比较出名的英雄片之一。故事讲述的是担任保安的神枪手高飞（周润发 饰）为人侠义、一身正气，他的好友沈四（黄秋生 饰）欠下一身高利贷，被放高利贷的人抓走了，幸好高飞深入虎穴将沈四救出。沈四为了还债，央求高飞跟他一起合作协助贼人抢劫一批私运的军火，无奈下高飞答应了。整个计划进行得十分顺利，但就在得手后，高飞被贼人出卖，车子冲进了民居造成了一家人除了一名幼女全部罹难。为了弥补自己的错失，高飞决定向贼人抢回赃款补偿幼女。©豆瓣', '周润发', '林岭东', 7, 11715, 'tt0105851', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2557751651.jpg', 0.6, 5, 48.2, 34.7, 11.5, '0.058775,-0.339931,-0.303952,0.330219,-0.272632,-0.212028,0.395392,-0.009648,-0.229088,-0.051315,0.427449,0.766675,0.058733,-0.106798,0.224694,-0.045732,0.035254,-0.612142,-0.156845,-0.152770,-0.326640,-0.503569,0.086347,-0.247874,-0.393646,-0.072384,0.462776,0.133595,-0.349084,0.388760,0.208782,0.164478,-0.149128,0.090235,-0.291752,0.011961,-0.124831,-0.168748,-0.081196,0.338650,-0.205749,-0.369984,0.048384,-0.000164,0.123034,0.409450,0.522119,-0.030432,-0.108330,-0.094392,0.153106,-0.415765,0.089409,-0.045803,0.206101,0.184613,0.087561,0.194638,-0.397100,-0.179370,0.271759,-0.296022,-0.670049,0.102528,0.134614,-0.414371,-0.856210,0.270520,-0.138580,0.173723,0.193691,-0.192534,0.028865,0.242661,0.199264,0.222250,0.001366,0.234691,-0.673764,0.334502,0.647792,-0.193275,0.198333,0.032775,0.066225,-0.269083,0.168242,-0.261959,-0.027977,0.057494,0.804821,-0.172531,0.115933,0.007053,-0.397345,-0.254783,-0.362765,-0.101347,-0.105882,-0.223330,-0.191663,-0.242462,-0.115616,0.057600,-0.174009,0.019885,0.106726,-0.418494,0.642354,-0.544169,-0.005855,0.508439,0.222094,-0.882272,0.366643,-0.083172,0.171120,0.034360,-0.004129,-0.153935,0.452728,0.288908,0.536924,-0.068471,-0.314696,-0.472288,-0.120561,-0.045999', '1302110', '1309069', '26678784', '5973984');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300860', '海蒂', '剧情', '孤儿海蒂（Shirley Temple 秀兰•邓波 饰）和黛特阿姨（Mady Christians 饰）生活在一起，然而黛特不愿继续在照顾外甥女，于是千里迢迢将海蒂送到偏远的善终——海蒂爷爷（Jean Hersholt 饰）的隐居之处。因失去儿子而沉浸悲伤之中爷爷阿道夫 起初无视这个从未见过面的孙女，但随着时间推移，祖孙俩的感情日益加深。但是贪婪的黛特再次返回，骗走海蒂欲将其卖给他人作女佣。天使般的海蒂和主人家的病弱女儿安娜（Helen Westley 饰）培养出亲密的友情；另一方面，阿道夫也踏上寻找孙女的旅程……©豆瓣', '秀兰·邓波儿', '艾伦·德万', 8.5, 7228, 'tt0028988', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2243627008.jpg', 0.1, 0.6, 12.6, 46, 40.7, '0.351252,-0.041036,-0.620618,0.708501,-0.177777,-0.646342,0.680926,0.231302,-0.572362,-0.210417,0.041046,0.636475,0.115695,0.390242,0.239328,-0.002111,-0.308693,-0.491667,0.054039,0.074746,-0.067994,-0.679655,0.021122,-0.126609,-0.250234,-0.265519,0.647374,-0.158920,0.016575,0.615698,0.145820,0.165181,-0.487001,0.259069,-0.104175,0.177810,-0.030289,0.057824,-0.497576,0.231604,0.207688,0.130515,0.067040,-0.028724,0.056827,0.284169,0.853354,-0.388910,-0.030943,-0.219771,0.430120,-0.143741,-0.062862,0.013226,-0.245577,0.227353,0.194233,0.054723,-0.402388,0.044288,0.190515,-0.292142,-0.255683,0.273057,0.218771,-0.097375,-0.654278,0.357161,0.130772,-0.147578,0.214336,-0.432842,0.419230,0.489628,-0.053136,0.650974,-0.392020,0.191365,-0.180869,0.025506,0.469712,-0.124299,0.097754,0.189992,-0.328038,-0.112429,0.453850,-0.334068,-0.645700,-0.034121,-0.032295,0.349262,0.063543,0.444117,-0.643587,-0.084829,-0.353457,0.026989,0.395014,-0.586202,-0.064024,-0.445028,-0.132215,-0.413458,-0.205740,-0.115961,0.103729,-0.398831,0.703930,-0.711339,0.400640,0.252182,0.346741,-0.449262,0.556840,-0.030954,0.330669,-0.167612,-0.175003,0.467397,0.109839,-0.151469,0.102655,0.032527,-0.169131,0.126650,-0.236234,0.249109', '3445516', '1414808', '1292219', '1292642');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300868', '异形', '科幻', '未来的世界，人类已能轻松穿梭于星际之间，在太空中展开商业活动。“诺史莫”是在太空活动的众多星际商业运输船之一。一次，它完成任务满载太空矿石返航地球时，突然收到了一组奇怪的信号，由于这可能是求救信号，飞船接到指令前往信号源地进行搜救。经过一段飞行后，飞船终于抵达信号源发出的地方。船员们发现此处果然有一艘坠毁的飞船，只是，经过一番搜索，他们发现该船的船员们都早已死亡，化为化石。此时，留在“诺史莫”号的第三指挥官里普利已经破译出该信号并不是求救信号，而是警告信号！队员的生死搏斗开始了！©豆瓣', '西格妮·韦弗', '雷德利·斯科特', 8.2, 225125, 'tt0078748', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1756402567.jpg', 0.3, 1.3, 17.2, 48.3, 32.8, '0.098525,0.084548,-0.917464,0.617762,0.259769,0.013575,0.572825,-0.591414,-0.493920,-0.025424,0.004256,0.510136,-0.026352,0.219207,0.211858,-0.034180,-0.723580,-0.294199,-0.154890,-0.533266,-0.530004,-0.709353,-0.148796,-0.267331,0.342370,-0.468516,0.772732,0.355362,-0.267487,0.422040,-0.109743,0.057732,-0.458987,0.848205,-0.279204,-0.240624,0.288862,-0.097242,-0.217823,0.078568,-0.533037,0.106234,0.168022,-0.244853,0.178095,0.457338,0.831250,-0.592133,-0.059669,-0.045109,0.066624,-0.178571,0.312620,-0.408506,0.636222,0.392525,-0.234599,-0.133504,-0.172754,0.461139,-0.174235,0.150532,-0.393143,-0.227669,-0.213657,0.130454,0.115619,-0.099086,-0.466241,0.124070,-0.180621,-0.244382,0.432866,0.428855,0.340690,0.096171,-0.345859,0.447476,-0.337549,-0.304387,0.453908,0.025739,-0.588870,0.342969,0.231773,-0.882162,-0.219076,0.042168,0.092284,-0.249611,0.384616,0.399932,-0.048880,0.235711,-0.779743,0.314144,-0.384589,-0.954347,-0.165797,-0.138134,-0.373136,-1.405393,0.484138,-0.079666,-0.158337,0.538744,-0.069993,0.042268,0.570548,-0.721413,0.350470,0.494131,-0.009808,-0.315060,0.437188,0.055429,0.236440,-0.372101,0.263532,0.077237,0.158595,0.893777,0.001785,0.161921,-0.085021,-0.155010,-0.445084,0.108293', '2159244', '1306809', '27073291', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300870', '瓶中信', '剧情', '特丽莎（罗宾•莱特•潘 饰）离婚后，儿子是她的珍宝。她是一名专栏作家，为了给儿子好的生活，她工作勤劳。一天她在海边跑步的时候，捡到了一个玻璃瓶，里面竟有一封信。特丽莎深切的感受到了写信人心痛的感觉，阴差阳错之间这封信被刊登在了报纸上。读者反应热烈，为了乘胜追击，报社派出特丽莎寻找这封信的主人。写信的人名叫盖瑞（凯文•科斯特纳 饰），自从妻子凯瑟琳离世之后，他每天都活在悲伤的阴影中，用信表达自己对妻子的爱意。特丽莎还是见到了这名伤心的男子，也没有告诉盖瑞她看过他写的那些瓶中信。两人相处的过程中，特丽莎知道自己已经爱上她痴情的盖瑞，盖瑞也因为特丽莎的出现，生活多了许多生气。面对已经逝世的爱妻，与就在面前的特丽莎，盖瑞会如何选择……©豆瓣', '凯文·科斯特纳', '路易斯·曼多基', 7.5, 11996, 'tt0139462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p926595392.jpg', 0.5, 3.2, 35.1, 44.3, 16.8, '0.415222,-0.139836,-0.728473,0.587293,-0.118656,-0.380596,0.738532,0.019537,-0.547174,-0.129221,0.336233,0.911388,-0.271124,0.508650,0.240480,0.383677,-0.344294,-0.788948,0.156633,-0.241253,-0.320327,-0.458852,-0.245764,-0.171648,0.016947,-0.317501,0.327645,-0.212155,0.067180,0.471353,0.241726,0.355860,0.150909,0.746741,-0.074097,0.286372,0.179622,-0.148009,-0.024563,0.148399,0.281767,-0.153384,-0.084484,0.385530,0.138273,0.263889,0.686735,-0.089258,-0.117583,0.017467,0.454682,-0.138110,0.153253,0.156455,0.064662,-0.202643,0.130360,0.176834,-0.471179,-0.094489,-0.094710,0.006885,-0.727106,-0.055509,-0.132356,0.478250,-0.740673,0.354804,-0.295592,-0.046352,0.291687,-0.345231,0.326992,0.387282,-0.145198,0.533464,-0.144576,-0.207951,-0.462838,0.242437,0.356062,-0.112120,-0.060737,0.523292,-0.322005,-0.297236,0.169096,0.014654,-0.485639,0.071079,0.289487,0.115688,-0.122444,0.057143,-0.543603,-0.048338,-0.376639,-0.207018,-0.064649,-0.522224,-0.264375,-0.281593,-0.155899,-0.358009,-0.581729,-0.149109,-0.099706,-0.287102,0.720766,-0.690860,0.233412,0.590383,0.349983,-0.225078,0.707955,0.345045,-0.290703,-0.245985,-0.032010,0.378629,0.170407,0.067922,0.349149,0.307605,0.218364,-0.041159,-0.376299,0.753124', '30162520', '1783461', '1309172', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300874', '死不张扬离奇失魂事件', '剧情', '姜家父亲（朴仁焕饰）将积蓄在汉城郊外的荒山上开了一个家庭旅馆，期想有游客来住宿，儿子（宋康昊饰）是个不中用的家伙，两个女儿心思各异，而同住在家的小叔（崔岷植饰）年纪一把却没成家。旅馆开业后没人光顾，全家人失望至极。终于等来了第一位客人，可他却在次日清晨离奇的自杀身亡，身上也没有钱物和任何身份证明。为了保住旅馆的名声，全家人决定将尸体偷偷埋在山里。第二次来的客人是一对情侣，想不到也在这里殉情自杀了，家里人有了第一次的经验，毫不犹豫的将尸体掩埋了。从此之后，这家旅馆接二连三的发生离奇事件，姜家人都惯性的将尸体埋在山里。最糟糕的是，政府决定在旅馆附近修建公路，家人开始想办法应付更多的难题……©豆瓣', '罗文姬', '金知云', 7.2, 7905, 'tt0188503', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p825517140.jpg', 1, 4.4, 39.6, 41.6, 13.4, '0.360332,-0.143388,-0.825121,0.306606,-0.218363,-0.332684,0.818526,0.162810,-0.637203,-0.168778,0.282526,0.824607,-0.062232,0.383147,-0.110652,-0.133987,-0.254297,-0.374555,0.019890,-0.311496,-0.570721,-0.409062,-0.002685,-0.240031,-0.122468,0.020039,0.193574,0.137495,0.130685,0.207717,0.328902,-0.036691,-0.109753,0.722152,-0.583874,0.123323,-0.031315,0.057734,-0.107191,0.234679,-0.008895,-0.385297,-0.118356,0.214732,0.309510,0.391062,0.749085,0.156353,-0.386210,0.075017,0.152745,-0.114425,-0.016492,0.400635,0.638816,-0.425269,0.322641,0.143374,-0.403736,-0.227171,0.071663,0.051439,-0.571674,0.094988,0.182073,-0.108056,-0.955342,0.565844,0.105122,-0.039671,-0.076010,-0.660787,0.574989,0.302714,-0.083864,0.252701,-0.112820,0.001724,-0.605334,0.233463,0.738689,-0.330227,0.314512,0.481353,-0.064246,-0.338394,0.041601,-0.150913,-0.312935,-0.021954,0.377818,-0.080754,-0.510049,-0.061136,-0.560502,-0.094562,-0.244654,-0.427549,0.098468,-0.281713,-0.142466,-0.246557,0.002595,0.008277,-0.280039,0.316111,0.202932,0.012997,0.534200,-0.564176,0.048637,0.601056,0.251900,-0.514472,0.706861,-0.133105,0.327498,0.186474,0.053474,-0.205306,0.143251,0.530030,0.236520,0.409459,-0.051664,-0.211342,-0.355422,0.384132', '1299965', '26769480', '25837175', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300880', '单挑', '剧情', '杰西·沙特尔斯沃思（雷·阿伦 Ray Allen饰），全国有名的高中篮球明星。杰西一心希望在职业篮球生涯中闯出一片天下，然而却因为有一个身为囚犯的父亲杰克·沙特尔斯沃思（丹泽尔·华盛顿 Denzel Washington饰）而蒙上了一层阴影。当年父亲在一次家庭暴力中错手杀死了母亲，锒铛入狱的杰克因为拥有一个明星儿子而面对了一次交易，只要说服杰西加入州政府指定的大学，事成之后便可得到减刑的机会。美国知名导演斯派克·李执导的影片《单挑》，由好莱坞最具号召力的黑人影星丹泽尔·华盛顿饰演父亲一角，本片也是他与导演斯派克·李的第三次合作。德艺双馨的NBA名将雷·阿伦饰演儿子杰西，雷·阿伦则凭借本片荣获1999年第8届MTV电影奖MTV电影奖-最具突破男演员提名。©豆瓣', '丹泽尔·华盛顿', '斯派克·李', 7.6, 6217, 'tt0124718', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1058801954.jpg', 0.5, 3.4, 30.7, 45.8, 19.5, '-0.360698,-0.076595,-0.501542,0.944906,0.210289,-0.460154,0.491591,0.246751,-0.091504,-0.370553,0.074208,0.938308,-0.176829,0.086353,0.420333,-0.317069,-0.094615,-0.624131,0.030294,-0.039695,-0.106237,-0.314891,-0.502173,-0.064904,-0.099058,-0.330992,0.851987,0.082012,-0.290446,0.246525,0.687505,0.176720,0.245909,0.119504,0.278674,0.014154,0.453111,0.085849,-0.613179,0.473947,0.115539,-0.113338,-0.235261,-0.125482,0.266562,0.262316,0.209913,0.042241,0.262571,-0.058729,0.510017,-0.394465,-0.030193,-0.214167,0.178805,-0.152700,0.317683,-0.043520,0.329428,0.082272,0.141801,-0.342958,-0.709051,0.009420,0.147097,0.006128,-0.498287,0.298560,-0.200725,0.202717,-0.258070,-0.054562,-0.005070,-0.155752,0.232385,0.164509,-0.099405,0.235697,-0.353246,0.410296,0.430022,0.099384,-0.292195,-0.013360,-0.216260,-0.560872,-0.082548,-0.372052,-0.427848,0.387554,0.619149,-0.481610,0.174364,0.233583,-0.141258,-0.376914,-0.207951,-0.153686,0.048256,-0.245877,0.262133,-0.619634,0.029998,0.060519,-0.132764,-0.296776,0.129515,-0.537681,0.694675,-0.581717,0.333864,0.329774,0.121653,-0.257840,0.789437,0.212222,0.180107,-0.416255,-0.058151,0.310010,0.320168,-0.095931,0.143953,0.220141,-0.034204,-0.385973,0.045816,0.482300', '1870681', '24875409', '25880986', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300883', '赌神', '剧情', '高进（周润发 饰）前来香港与赌魔决斗，怎料刚抵港，便被南哥（杨泽霖 饰）追杀，结果堕入陷阱而失忆。幸得刀仔（刘德华 饰）和其女友珍（王祖贤 饰）相救，他们把高进带回家中疗养，发现高进精通赌术后，兴奋不已，想利用他来挣大钱，却反而因为高进发挥不稳亏了钱。高进妻子遭其堂弟 高义醉酒后污辱杀害。高义进而联手南哥，设计谋害高进，四处搜罗进的藏身地点，前往追杀。逃亡之时，高进翻车受伤，竟恢复了记忆——但是却怎样也记不起失忆期间的事情。刀仔提醒进，高义并非好人，但进却已然蒙在鼓里，不知危难当头。©豆瓣', '周润发', '王晶', 8.4, 235837, 'tt0097244', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1986001156.jpg', 0.1, 0.6, 13.2, 48.9, 37.2, '-0.125911,0.123790,-0.553741,0.162828,0.164587,-0.324648,0.363504,-0.083249,-0.107370,-0.710881,0.113405,0.354292,0.094783,-0.007881,0.011559,-0.016075,-0.081887,-0.516514,0.199941,-0.164582,-0.325793,-0.324264,-0.283046,0.145006,-0.168341,0.070770,0.291012,0.193918,-0.502128,0.548227,0.177903,0.355355,-0.273729,0.486369,0.040011,0.200092,-0.271587,0.323911,-0.254749,0.014093,-0.002167,-0.307481,-0.264109,-0.048576,0.205635,0.448833,0.373780,-0.107382,-0.222833,-0.198978,0.197094,-0.217398,-0.044346,-0.021888,0.303162,0.085329,0.261860,-0.007530,-0.124519,0.205621,0.034175,0.041416,-0.558006,0.181040,0.195491,-0.425743,-0.418764,0.099468,-0.088671,0.291763,-0.291720,-0.022155,0.077041,0.208223,0.166933,0.191319,-0.044892,-0.084912,-0.416735,-0.106726,0.672193,-0.188872,0.242286,0.201890,0.342101,-0.219030,0.234982,-0.257785,-0.012710,0.197453,0.379406,0.237258,-0.003032,-0.075353,0.116444,-0.309897,-0.589389,0.634738,-0.268220,-0.098694,-0.051193,-0.306047,-0.116566,0.083263,-0.182730,-0.099426,0.021858,-0.366040,0.222028,-0.555769,0.069440,0.268983,0.261324,-0.919715,0.261148,0.029186,0.015216,-0.201001,-0.253621,0.208127,0.358467,0.032526,0.064823,-0.242547,-0.166560,-0.318037,-0.236582,-0.023767', '1302110', '1295746', '1484760', '3998385');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300894', '城南旧事', '剧情', '本片根据林海音的同名短篇小说改编。小女孩林英子（沈洁 饰）住在五十年前的北京南城，在他们家院子附近住着一个疯女人秀珍（张闽 饰），秀珍的丈夫因参与学生运动被杀，孩子也不知所踪，因此落下了疯病，时常把英子当做自己的孩子“小桂子”看待，英子也喜欢秀珍，答应帮她找回小桂子。英子有个苦命的小伙伴妞儿，学戏时常遭干爹打骂，英子偶然发现妞儿有小桂子的胎记，帮助她们母女相认。英子上小学后，一家人搬到了厂甸。在家门口荒废的院落里，英子发现了一个小偷（张丰毅 饰）藏赃的草堆，小偷为了供弟弟读书只得干不光彩的勾当，英子却不把他看作是坏人。不久，女佣苏妈返乡，父亲去世，英子的童年，彷佛一下结束了……©豆瓣', '沈洁', '吴贻弓', 9.1, 108256, 'tt0085326', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178268394.jpg', 0.1, 0.3, 5.4, 34, 60.3, '0.309567,-0.216330,-0.551583,0.225678,-0.402143,-0.511246,0.517191,0.020711,-0.538204,-0.267070,0.176037,0.508114,0.009841,0.594095,-0.156350,0.173292,-0.155481,-0.335661,0.021231,-0.136088,-0.171704,-0.252292,0.210388,-0.010889,-0.227941,-0.080354,0.144884,-0.212248,0.027328,0.230699,0.214221,-0.157178,-0.256986,0.170713,-0.073517,0.510263,-0.124873,0.012058,-0.088537,0.057466,0.048970,-0.110608,-0.054448,-0.272240,0.242883,0.160882,0.772958,0.042417,-0.043036,-0.307192,0.301083,0.021724,-0.120646,-0.053047,0.452828,-0.103606,0.181382,0.002942,-0.240758,-0.099722,0.151337,-0.235248,0.071085,0.150306,0.367460,-0.045213,-0.683944,0.371593,-0.020922,-0.039688,0.066512,-0.516380,0.410764,0.289776,0.002602,0.460673,-0.330685,0.174449,-0.589450,0.397905,0.547157,-0.260089,0.338736,0.171417,-0.162918,-0.115686,0.383583,-0.071809,-0.574979,0.270557,0.264691,-0.329215,-0.572269,-0.053869,-0.200439,-0.202381,-0.090497,0.167794,0.111221,-0.454266,-0.104577,-0.274851,0.062356,-0.170278,-0.261499,0.066957,-0.056018,-0.157083,0.568853,-0.646161,0.353575,0.426480,0.335983,-0.200195,0.559838,-0.124761,0.314079,-0.190244,0.114564,-0.088603,0.193391,0.184950,0.419776,0.188725,-0.248228,-0.060199,-0.183664,0.125341', '1306505', '1302384', '30205667', '1297606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300912', '魂断威尼斯', '剧情', '1911年，德国作曲家阿森巴赫（德克•博加德）怀带丧女之痛来到威尼斯，想藉水城美景舒缓心情，可是一切景致所勾起的不过是更加伤心的回忆，直到在旅馆里邂逅美少年塔奇奥（伯恩•安德森），对方宛如希腊雕像般的容颜才令他浑身颤栗，浑然忘我地沉醉在激动的热情中。其后，威尼斯城被瘟疫所笼罩，但官方刻意封锁了消息。阿森巴赫逐渐发现这一惊人的危机时，没像其他人一样慌不择路想尽快逃离，相反为了多看塔奇奥一眼，甘愿染上瘟疫命丧威尼斯。©豆瓣', '德克·博加德', '卢基诺·维斯康蒂', 8.2, 25829, 'tt0067445', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2003694039.jpg', 0.5, 1.9, 17.9, 45.1, 34.5, '0.034111,0.071637,-0.911463,0.222715,0.309661,-0.239700,0.607571,0.126023,-0.693543,-0.057854,-0.178553,0.609283,-0.504963,0.315828,0.208397,0.223536,-0.494766,-0.565742,-0.160133,-0.367710,0.025181,-0.123385,-0.018977,-0.122855,-0.121618,-0.503890,0.359387,0.362617,-0.124061,0.476355,0.018470,0.574481,-0.239071,0.564118,-0.029963,-0.099960,-0.025448,-0.363335,-0.380535,0.109740,0.020237,-0.075397,-0.548690,0.483373,-0.078520,0.062723,0.452464,-0.217073,-0.172392,0.029165,0.132227,-0.099092,0.239116,0.224459,-0.184874,-0.081565,0.172040,-0.199483,-0.417046,-0.068478,0.157121,-0.311748,-0.320826,0.267753,0.150870,0.094153,-0.117100,0.069206,0.070679,-0.080313,0.166684,-0.233541,0.251463,0.153675,0.183048,0.407252,-0.155217,-0.020157,-0.353227,0.114197,0.655608,0.170429,-0.651257,0.422042,-0.215124,-0.162558,-0.141010,-0.139906,-0.259372,0.276097,0.369303,0.296008,0.046207,0.545333,-0.296510,-0.079062,-0.667598,-0.272235,-0.626486,-0.129023,-0.364897,-0.567095,-0.350125,-0.019559,0.041675,0.009409,-0.024113,0.067485,0.223992,-0.591722,0.469704,0.586469,0.060751,0.026450,0.191667,-0.280590,-0.218225,0.247061,-0.144930,0.604722,0.082524,0.148240,0.135280,0.152739,-0.166298,-0.123884,-0.244844,0.480911', '3011051', '4832825', '1300958', '4724373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300916', '超人', '动作', '1978年版的电影由克里斯托弗·里夫饰演，他一共饰演了四个版本《超人》系列电影。 氪星即将毁灭之际，为保持种族的延续，科学家乔·艾尔通过飞船将他尚在襁褓中的儿子卡尔（克里斯托弗·里夫 Christopher Reeve 饰）送往地球。卡尔被地球上的肯特夫妇抚养成人，改名为克拉克，他具有超人的能力，将成为地球上正义和真理的守护者。长大了的卡尔来到大都市，成为《行星日报》的记者。平时，他是温文尔雅的普通记者，危急时刻就变成穿着紧身衣、披着斗篷在空中自由飞翔的守护神超人。当邪恶的鲁索妄图统治全世界时，超人是唯一能够制止他的人。©豆瓣', '克里斯托弗·里夫', '理查德·唐纳', 7.7, 25641, 'tt0078346', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p726824081.jpg', 0.4, 2.1, 29.6, 48.4, 19.5, '0.117268,0.467986,-0.605923,0.653434,-0.222683,0.020289,0.520404,0.145147,-0.330434,-0.205187,0.312624,1.001005,-0.105445,0.163056,0.335172,0.237753,-0.530039,-0.681149,-0.163366,0.137580,-0.321363,-0.259640,-0.474714,-0.137928,-0.069881,-0.621420,0.795780,0.026266,-0.070704,0.139388,0.300155,0.395467,-0.103126,0.208173,-0.308950,-0.096800,0.085490,-0.394387,-0.249137,0.430233,-0.340983,0.134369,0.263875,0.280818,-0.332151,0.081509,0.739061,-0.628481,0.322211,-0.452005,0.582304,-0.425886,-0.018994,0.044170,0.209562,-0.018905,-0.064103,0.035811,0.142880,0.243581,0.195618,-0.304243,-0.880002,-0.167781,0.089236,0.169284,-0.602794,0.506553,-0.235848,-0.080227,0.281447,-0.279457,0.122910,0.045987,0.078382,0.505072,0.043919,0.110239,-0.650299,0.354382,0.350344,0.172309,-0.657640,0.151358,-0.310403,-0.463951,-0.367496,-0.450149,-0.464056,-0.288358,0.267958,-0.137965,-0.037908,0.316017,-0.588634,0.073375,-0.220789,-0.204350,0.250231,-0.348531,-0.257351,-0.635925,0.064007,-0.347425,0.008931,-0.010161,-0.029570,-0.473484,1.046970,-0.804491,0.132433,0.493615,0.397856,-0.188438,0.907269,-0.176345,0.296034,-0.408080,0.082997,0.386200,0.140519,0.358641,0.052898,0.196778,-0.101865,0.069715,-0.233951,0.725970', '27602116', '1870681', '24284209', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300919', '天使爱过界', '爱情', '艺术系女生安琪（Audrey Tautou饰）爱上了心脏科医生路易（Samuel Le Bihan饰），可对方已是有妇之夫，也对安琪表现得若即若离，但安琪始终默默守护在路易身旁，坚信两人的真爱会克服一切险阻，最终在一起。路易的爱并不忠贞，在让安琪一次次失望后，他最终还是回到妻子身旁，受不了打击的安琪一时冲动下，打开煤气自杀……安琪被及时赶到的路易救了下来，醒来后，他们彼此才发现原来这段爱情并非表面所见的那样，一切事情的背后都另有隐情……©豆瓣', '奥黛丽·塔图', '拉埃蒂茜亚·科隆巴尼', 7.7, 8607, 'tt0291579', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p691407931.jpg', 0.4, 2.6, 28.2, 50.3, 18.6, '0.096534,0.053028,-0.641567,0.253924,-0.090334,-0.515201,0.746760,-0.182110,-0.553314,-0.369324,0.308147,0.593133,-0.221162,0.268801,0.174628,0.262641,-0.326401,-0.723403,-0.044989,-0.066825,-0.343433,-0.350294,-0.070695,-0.101065,-0.230373,0.015791,0.790292,0.250646,0.075088,0.443378,0.382848,-0.040015,-0.000484,0.739877,-0.004920,0.129548,0.029233,-0.048957,-0.344781,0.107071,0.285373,-0.357600,-0.101013,0.584959,-0.097128,0.029224,0.405818,-0.490153,-0.283320,0.201938,0.159751,-0.533183,0.072366,0.147587,0.354803,-0.072823,0.157306,0.335093,-0.270579,0.089263,0.069701,0.346632,-0.440635,-0.155352,0.079851,0.123006,-0.736002,0.492571,-0.144488,0.052360,0.176022,-0.265813,0.060558,0.201122,0.313951,0.350677,-0.510362,-0.145556,-0.381705,-0.353405,0.663382,0.157804,-0.238923,0.446687,-0.280284,-0.201210,-0.114863,-0.061284,-0.514841,0.291974,0.219878,0.365880,-0.175526,0.196415,-0.156069,-0.255220,-0.046453,0.121282,-0.130628,-0.576855,0.055445,-0.263635,-0.150725,-0.340459,-0.520804,0.028096,-0.243922,-0.348775,0.322146,-0.808981,0.224820,0.390205,0.276391,-0.436749,0.424775,0.456313,-0.088433,-0.079385,0.000378,0.626542,-0.103482,0.229283,0.125737,0.286025,0.042414,0.037946,-0.474817,0.394501', '1301022', '26245360', '35030151', '1417304');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300930', '冰风暴', '剧情', '1973年美国康涅狄格州，感恩节快要到来，一场冰风暴也即将到来。平凡乏味的家庭生活使中年夫妻厌倦，丈夫本•胡德（凯文•克莱恩饰）一直在引诱邻居珍妮特•哈珀，而妻子（琼•艾伦饰）对丈夫的谎言也早已不耐烦了。儿子保罗（托比•马奎尔饰）迷恋着学校里最有人缘的那位女生。女儿温迪（克里斯蒂娜•里奇）兴趣于电视里的水门事件听证会。冰风暴的夜晚，夫妻两个去朋友家参加一个鸡尾酒会，鸡尾酒会的一个重要内容是进行换房间钥匙的游戏。在酒会结束后，每个妻子都可以和别家男人结成新欢。而他们儿子则赶去面对一场诱惑与考验，女儿正陶醉在同邻家男孩子的性游戏中……©豆瓣', '凯文·克莱恩', '李安', 7.9, 28739, 'tt0119349', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p791145802.jpg', 0.3, 1.5, 22.1, 53.7, 22.5, '0.082227,-0.148306,-0.395013,0.328481,-0.276267,-0.130931,0.766493,0.196429,-0.326754,-0.460126,0.110045,0.814490,-0.239830,0.553315,0.553457,0.029618,-0.308529,-0.681741,-0.122165,-0.126664,-0.127299,-0.327516,-0.055950,-0.387472,0.083486,-0.219459,0.432628,-0.255393,0.074098,0.443954,0.490148,0.118001,-0.205817,0.399392,-0.029437,-0.156248,0.237018,0.187742,-0.474474,0.133063,-0.110246,0.095754,-0.127523,0.059191,0.101405,0.109117,0.657577,-0.150700,-0.016500,-0.336248,0.201260,0.038449,-0.203607,0.281641,0.447630,-0.118363,0.444900,0.135086,0.136800,0.010563,0.045275,-0.343700,-0.402684,0.169146,-0.009955,-0.044278,-0.246177,0.557530,-0.078213,-0.064372,-0.002740,-0.272202,0.213248,0.230088,0.256312,0.541744,-0.162833,0.055564,-0.260389,0.173896,0.549756,0.160832,-0.054905,0.449706,-0.266272,-0.266592,0.118293,-0.129078,-0.771406,0.078872,0.189243,-0.139672,-0.159984,0.186939,-0.614863,0.119953,-0.109873,-0.009956,0.075913,-0.386343,-0.043445,-0.859850,0.025692,-0.377418,-0.249613,-0.059654,0.129443,-0.040929,0.664053,-0.597965,0.325620,0.370230,0.207508,-0.407503,0.640785,0.306963,0.511294,-0.412761,-0.029615,0.207784,-0.158390,-0.029924,-0.123665,0.219829,-0.221555,0.078371,-0.299376,0.516251', '10466639', '3811356', '26687241', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300945', '云中漫步', '剧情', '二战结束后，思乡心切的大批美军士兵踏上旧金山港即投进久候的亲人的怀抱，但保罗•萨顿（基努•里维斯）久等仍不见其妻子的踪影，夕阳西沉时，他拖着孤单落寞的身躯走回家中，发现妻子早已改变，她的眼里只剩金钱不再有他。眼看家中已毫无温情，保罗也无心留恋，只是他再次外出离家是为工作。在火车上，保罗结识美丽的姑娘维多利亚•阿拉贡（Aitana Sánchez-Gijón），因为投缘，保罗将她一路细心照顾，而维多利亚在感激之余，向保罗倾诉了自己的不幸，听过她的遭遇后，保罗决定陪她返回家乡，尽其所能帮助她。©豆瓣', '基努·里维斯', '阿方索·阿雷奥', 7.8, 71160, 'tt0114887', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p575591684.jpg', 0.4, 2.5, 27, 48.4, 21.8, '0.254390,0.124700,-1.009097,0.266290,-0.012174,-0.612097,0.806984,0.081354,-0.485259,-0.232871,0.124595,0.548940,0.201204,0.372510,0.241759,0.129111,-0.465579,-0.621205,0.014957,-0.110072,-0.131857,-0.348326,-0.084345,-0.179544,-0.204798,-0.131008,0.537916,0.228391,0.208251,0.803531,0.050168,0.024979,0.072436,0.834567,-0.226152,0.234165,-0.071737,0.001878,-0.170462,0.137362,0.154505,-0.362281,-0.245831,0.105672,-0.054913,0.444748,0.706603,0.059763,-0.030074,-0.115413,0.190398,-0.282914,0.474080,0.070358,-0.053844,0.154932,-0.120616,-0.058728,-0.252020,-0.136660,-0.033573,-0.123539,-0.330780,0.171777,-0.212136,0.040612,-0.595399,0.539311,-0.222365,0.031424,0.121578,-0.525662,0.095687,0.080164,-0.117973,0.090870,-0.117772,0.357659,-0.175032,0.181048,0.580035,-0.104904,-0.129354,0.350089,-0.089321,-0.139944,0.411241,-0.063167,-0.518445,-0.232081,0.207883,0.356233,-0.088470,0.117689,-0.280363,0.164011,-0.543818,-0.175824,-0.182504,-0.384145,0.061734,-0.438762,-0.144145,-0.372444,-0.441913,0.056706,0.027998,-0.182782,0.453112,-0.462836,0.601935,0.523031,0.341464,-0.320559,0.866285,0.004070,0.231817,-0.039145,0.221250,0.897050,-0.225980,0.091999,0.163721,-0.037679,-0.125239,0.294535,-0.498496,0.293463', '1844413', '1292211', '26296258', '4896894');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300946', '业余小偷', '喜剧', '本过着平凡生活的夫妻雷·温克勒（伍迪·艾伦 Woody Allen饰）和弗伦奇（崔茜·尤玛 Tracey Ullman饰），一个是有犯罪前科的洗碗工，一个是专给人修指甲的美容师。然而这平静而安稳的生活，却被雷密谋抢劫银行的计划所打破。即使妻子极力反对，可雷心意已决。他不仅找上三个愚蠢的同伴入伙实施抢劫计划，居然还千方百计地拖弗伦奇下水。可这场希望一夜暴富的美梦并非如想象中顺利，一场状况百出的银行抢劫行动爆笑上演。由美国著名导演伍迪·艾伦自编自演自导的喜剧电影《业余小偷》，沿袭了他一贯善于揶揄讽刺的喜剧风格形式。本剧一连串笑料百出的状况连连，加之带有浓厚地方色彩的机智对白，让这出幽默诙谐的“内行人笑话”，令人忍俊不禁、捧腹不止。女主角崔茜·尤玛凭借此片荣获2001年第58届金球奖电影类-音乐喜剧类最佳女主角提名。©豆瓣', '伍迪·艾伦', '伍迪·艾伦', 7.5, 13054, 'tt0196216', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1757315926.jpg', 0.4, 3, 34, 48.2, 14.4, '0.048689,-0.089675,-0.486080,0.608497,0.021831,0.040051,0.514709,0.058575,-0.415011,-0.193121,0.026805,0.491304,-0.304126,-0.082617,0.333204,-0.256012,-0.186256,-0.412159,-0.306108,0.352359,0.254872,-0.289207,-0.324664,-0.243394,-0.106251,-0.246493,0.413380,0.199653,-0.442322,0.355560,0.697467,0.282361,-0.175842,0.126736,0.078480,-0.122619,0.167555,0.213263,-0.297745,0.165172,0.006248,-0.297252,-0.218004,0.198191,-0.046046,0.394413,0.445754,-0.295631,-0.123897,0.144832,0.598894,-0.474094,-0.181848,0.093260,0.088304,-0.013316,0.259784,0.081591,0.011800,0.054519,0.120144,-0.062956,-0.971699,0.030137,0.287819,-0.101302,-0.296906,0.243918,-0.063167,0.053991,-0.194409,0.063672,0.121030,0.067333,0.641975,0.281833,0.080194,0.087829,-0.368965,0.350047,0.462868,0.140648,-0.438980,0.427384,-0.288779,-0.290082,0.128903,-0.557447,-0.405473,0.105313,0.163983,-0.277296,-0.035272,0.017622,-0.408247,-0.042448,-0.256608,-0.014008,-0.154543,-0.375209,0.012643,-0.749584,0.033477,-0.258475,-0.158160,-0.134214,0.109000,-0.431673,0.420940,-0.443891,0.021838,0.477298,-0.162241,-0.385787,0.433538,0.210962,-0.000486,-0.174784,-0.120377,0.059559,0.082235,-0.182380,0.079746,0.396222,0.049730,-0.369280,-0.104456,0.378147', '6844861', '3318306', '27073234', '25921830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300951', '欲望法则', '剧情', '帕布罗·金特罗（欧塞维奥·庞塞拉 Eusebio Poncela饰）是西班牙一位赫赫有名的导演兼编剧，然而在如此光鲜亮丽的外表背后，他却有着不为人知的一面。他深深地爱着同性恋男友胡安·贝穆德斯（米格尔·莫利纳 Miguel Molina饰），然而胡安对他却颇为冷淡。帕布罗的姐姐蒂娜·金特罗（卡门·毛拉 Carmen Maura饰）是一个变性人，她在性方面遭遇过一次打击之后，便对男人充满了仇恨。蒂娜与女模特艾达（曼奴拉·沃拉斯科 Manuela Velasco饰）共同生活，然而艾达的女儿却爱上了帕布罗。当帕布罗结识了占有欲极强的安东尼奥·贝尼特斯（安东尼奥·班德拉斯 Antonio Banderas饰）后，所有的关系将变得更加混乱不堪。由西班牙著名导演佩德罗·阿莫多瓦执导的影片《欲望法则》，荣获1987年第37届柏林国际电影节泰迪奖最佳长片大奖。本片内容涉及变性、乱伦、同性恋、男性裸体自渎等场面，透过这些对性与暴力犯罪夸张戏谑的描写，赤裸裸地向传统道德观念发起挑战。', '欧塞维奥·庞塞拉', '佩德罗·阿莫多瓦', 8.2, 9454, 'tt0093412', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1958673368.jpg', 0.4, 1.1, 17.7, 49.3, 31.5, '0.196723,0.042649,-0.536267,0.769353,0.178949,-0.251536,0.790407,0.245398,-0.328842,-0.317582,-0.021081,0.732633,-0.514793,-0.013556,0.356998,0.066710,-0.358207,-0.539607,-0.017488,-0.086573,0.015520,-0.462964,-0.268931,-0.065193,-0.292895,-0.534484,0.381519,-0.206104,-0.307637,0.335807,0.640389,0.615863,0.275805,0.344214,0.241317,-0.044557,0.292965,-0.138983,-0.216283,0.175296,0.105602,0.174808,-0.202675,0.155090,0.090098,0.142896,0.453287,-0.395454,0.402579,-0.098416,0.413648,-0.044451,0.103501,0.231925,0.164375,-0.262838,0.111580,0.115558,-0.026865,-0.199930,0.208977,-0.166320,-0.434623,0.020261,0.098799,0.189309,-0.408584,0.287052,-0.368786,0.050458,-0.035879,-0.158377,-0.165649,0.132901,0.419909,0.213302,0.298041,-0.098609,-0.202426,0.050861,0.200547,0.290517,-0.414716,0.127361,-0.657651,-0.616759,-0.315083,-0.195972,-0.544130,-0.042566,0.378813,-0.295136,0.168896,0.604369,-0.605411,-0.165365,-0.363599,-0.036228,0.041780,-0.193502,-0.033287,-0.684751,-0.259901,-0.467588,-0.184346,-0.111654,0.058664,-0.146313,0.508801,-0.431213,0.290123,0.338389,0.169535,-0.024128,0.534806,0.301608,-0.043948,-0.099609,-0.369835,0.685849,0.094397,-0.108770,0.065437,0.531313,-0.013888,-0.125542,0.045400,0.672042', '35161768', '3055450', '1299261', '1291556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300952', '崩溃边缘的女人', '剧情', '女演员佩帕（卡门·莫拉 Carmen Maura 饰）得知自己怀有身孕，但是她的喜悦并未持续多久，因为她的情人伊万（Fernando Guillén 饰）突然失踪。佩帕想尽办法联系伊万，但最终一无所获，这令她歇斯底里，痛苦难耐。而就在这时，伊万的老婆露西娅（Juliet a Serrano 饰）又找上门来大找麻烦。不久，佩帕的好友坎德拉（María Barranco 饰）也因惧怕警察拘捕而寻求避难。一群精神濒临崩溃的女人凑在一起，上演令人唏嘘的悲喜剧……本片入围1988年威尼斯电影节主竞赛单元，最终获得最佳剧本奖；1988年欧洲电影节最佳青年作品和最佳女演员奖；1988年纽约影评人协会最佳外语片奖；1989年歌雅奖最佳女主角（Carmen Maura）、最佳剪辑、最佳剧本和最佳女配角奖（María Barranco）。©豆瓣', '卡门·毛拉', '佩德罗·阿莫多瓦', 7.8, 7669, 'tt0095675', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1264704890.jpg', 0.3, 2.1, 25.4, 51.1, 21.2, '-0.436363,-0.084063,-0.409619,0.392767,0.479739,-0.202902,0.547027,-0.113301,-0.621320,-0.209977,0.292712,0.832248,-0.620390,0.154710,0.541471,-0.082904,-0.481909,-0.746315,0.240212,-0.179254,0.018768,-0.152454,-0.393298,-0.200477,-0.126548,-0.436163,0.820306,-0.045217,0.129592,0.572490,0.752950,0.115402,-0.029254,0.079347,0.321492,0.081598,0.514388,-0.081716,-0.285175,0.513619,0.211014,-0.462481,-0.431749,0.149604,0.186858,0.469830,0.564995,-0.063276,0.054909,0.207143,0.655758,-0.546363,-0.245295,0.007106,0.294197,-0.377743,0.283135,-0.058570,-0.120057,-0.037753,0.009122,-0.155784,-0.518065,0.587992,0.260677,0.125641,-0.164120,0.369165,-0.182440,0.414417,-0.156115,0.087257,0.052800,0.312854,0.403895,0.094583,-0.367585,-0.042587,-0.208668,0.693344,0.206782,0.019225,-0.262420,0.257562,-0.083000,-0.645922,-0.144699,-0.498019,-0.623272,0.065690,0.391965,0.254058,0.009449,0.094556,-0.294888,-0.043881,-0.187087,-0.103916,-0.059131,-0.137224,-0.009407,-0.933950,-0.017211,0.100073,-0.004787,-0.259321,-0.018353,-0.227139,0.637015,-0.459052,0.438447,0.557560,0.071407,-0.547824,0.709520,0.045986,-0.042502,-0.485724,-0.313401,0.380667,-0.305531,-0.234871,0.005843,-0.068840,-0.258819,-0.447076,-0.191271,0.349431', '1292759', '34795703', 