INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300953', '情迷高跟鞋', '剧情', '在蕾贝嘉（维多利亚·阿布里尔 Victoria Abril饰）的童年时期，作为当红歌手的母亲（玛丽莎·佩雷德斯 Marisa Paredes饰）就为了事业而远走他乡，抛下女儿独自长大。蕾贝嘉一直想挽留母亲在身边，不惜间接害死继父，这一切都是枉然。母亲的光彩太耀眼，蕾贝嘉尽其一生去模仿追赶，想要成为母亲那样的人；同时，母亲的无情和永远无法超越的高度，却令蕾贝嘉对她充满妒和恨。她当上了新闻主播，嫁给了母亲的旧情人，力图让自己变得强大。但是母亲回来后，和蕾贝嘉的丈夫爱火重生，这让蕾贝嘉非常生气。她一怒之下把丈夫杀死，并坦诚了自己的罪行。蕾贝嘉入狱后，母亲反省自己和女儿的关系为何变成这样。她要赎罪，要把正当盛年的女儿从监狱里救出来，让蕾贝嘉继续寻找幸福的归宿。©豆瓣', '维多利亚·阿夫里尔', '佩德罗·阿莫多瓦', 7.8, 10588, 'tt0103030', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1958674983.jpg', 0.2, 1.2, 25.5, 53, 20.1, '-0.171515,0.193389,-0.673768,0.776283,-0.347749,-0.459608,0.731315,0.088307,-0.406264,-0.155063,0.087179,0.934814,0.008714,0.315654,0.078672,0.382869,-0.390946,-0.757571,0.127769,-0.316469,-0.033430,-0.529767,0.108181,-0.041678,-0.134582,-0.140090,0.640768,-0.092684,-0.012112,0.113837,0.394096,0.337505,0.219896,0.349417,-0.067147,0.234822,-0.295966,-0.134772,-0.253852,0.082226,0.443450,-0.097403,-0.031340,0.673195,0.017316,0.027021,0.619449,-0.209850,0.108366,-0.391138,0.268087,-0.405959,0.171909,0.206587,-0.126480,-0.207292,0.376343,0.264758,-0.369882,-0.295878,0.147753,-0.134426,-0.862603,0.141501,0.074150,-0.155216,-0.697245,-0.001157,-0.201885,0.156411,0.409130,-0.192321,0.130425,0.300817,0.066294,0.440288,-0.496181,-0.028675,-0.467054,0.172134,0.908413,-0.223897,0.048198,0.422131,-0.297860,0.004175,0.139125,-0.496319,-0.778066,0.026709,0.264230,0.181589,-0.197780,0.390842,-0.179080,-0.472968,-0.412486,0.188204,0.169815,-0.659862,0.015659,0.193243,-0.034843,-0.310305,-0.314656,-0.114499,-0.256524,-0.567977,0.568640,-0.735978,0.353676,0.417413,0.639735,-0.833926,0.688253,0.131002,0.187007,-0.030384,0.013290,0.672823,0.035435,-0.025695,0.017345,-0.188154,0.186428,0.113782,-0.442167,0.437305', '1304977', '26678784', '1296569', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300955', '同流者', '剧情', '马塞洛（让-路易斯·特林提格南特 Jean-Louis Trintignant 饰）是意大利法西斯组织的一员，他的新任务是到巴黎除掉他以前大学时候的教授 卢克·夸德里（Enzo Tarascio 饰），一个反法西斯组织的成员。于是马塞洛以和未婚妻朱利亚（斯蒂芬尼娅·桑德雷莉 Stefania Sandrelli 饰）到巴黎度蜜月为借口，到教授家拜访。和马塞洛一起执行任务的还有伪装成他的司机的曼加涅略（Gastone Moschin 饰)。在教授家，马塞洛被教授的年轻妻子安娜（多米尼克·桑达 Dominique Sanda 饰）深深吸引。马塞洛的同伴曼加涅略不断催促他除掉教授，然而他迟迟不愿下手。曼加涅略得知了教授和他的妻子将到野外去，于是准备独自进行刺杀任务......本片根据意大利小说家阿尔贝托·莫拉维亚的同名作品改编。©豆瓣', '让-路易·特兰蒂尼昂', '贝纳尔多·贝托鲁奇', 8.6, 9029, 'tt0065571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p578516223.jpg', 0.3, 1, 10.5, 44.1, 44.2, '0.556011,-0.137043,-0.511463,0.558242,-0.196342,-0.500226,0.224526,0.257026,-0.369447,-0.272848,0.261837,0.860578,0.131288,0.099443,0.674707,0.303810,-0.483301,-0.568736,0.148713,-0.239264,-0.440944,-0.736211,-0.091756,-0.202056,-0.020744,-0.563143,0.371849,-0.374324,0.089071,0.618502,0.159537,0.735308,-0.030964,0.260210,0.057763,0.214842,0.638650,-0.266097,-0.289635,0.486047,0.215263,0.035745,-0.462989,0.113718,0.188728,0.483021,0.565308,-0.023097,0.395346,-0.037434,0.169591,-0.397937,0.127467,-0.001616,0.342523,-0.078767,0.194226,0.401885,-0.208362,0.037358,0.018396,-0.132462,-0.525455,-0.009166,0.321649,0.083546,-0.710150,0.371118,-0.474983,-0.007749,0.228315,-0.687055,0.194750,0.288857,-0.022579,0.198257,0.083993,0.005207,-0.588323,0.283299,0.405122,-0.082870,0.083556,-0.166306,-0.029159,-0.130965,0.130169,-0.342448,-0.538380,0.052555,0.145551,-0.099021,-0.005326,0.096228,-0.747071,-0.336356,-0.630953,-0.211203,0.117515,-0.442026,0.059484,-0.893827,-0.081442,0.102750,-0.036268,0.024187,0.134516,-0.091196,0.658901,-0.797668,0.226698,0.827479,0.270974,-0.253597,0.597832,0.039319,0.272134,-0.310222,-0.219197,0.036426,0.357036,0.213370,-0.107732,0.556499,0.201905,-0.353767,-0.380105,0.397187', '3285622', '3178770', '25833539', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300956', '一九零零', '剧情', '1901年1月27日，著名作曲家歌剧大师威尔弟去世，这也正是意大利北部两户家庭产子的同一天。阿弗雷德（罗伯特·德尼罗 Robert De Niro饰），富有的农场主的孙子；奥尔茂（杰拉尔·德帕迪约 Gérard Depardieu饰），贫穷的农户的孙子。两人从小就结下了友谊，然而因为地位阶级与出身经历的不同，注定了两人天壤之别的迥然人生。由意大利著名导演贝纳多·贝托鲁奇执导的史诗巨作《一九零零》，以20世纪初期意大利社会动荡时期为故事背景，时间跨越40年，讲述了阶级矛盾和家族纷争下仇恨和抗争的故事。本片被西方国家视为阶级斗争电影读本，加上电影情节的大胆尺度，影片被长期禁映。本片演员阵容豪华，巨星云集，包括罗伯特·德尼罗、杰拉德·德帕迪约、唐纳德·萨瑟兰、多米尼克·桑达、伯特·兰开斯特、斯特林·海登、斯坦芬尼·桑德莱里、劳拉·贝蒂等众多大牌明星。©豆瓣', '罗伯特·德尼罗', '贝纳尔多·贝托鲁奇', 8.7, 9337, 'tt0074084', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1071334596.jpg', 0.5, 1.2, 9.5, 39, 49.8, '0.213030,-0.169127,-0.508902,0.490366,0.450069,-0.346434,0.501369,0.360417,-0.532466,-0.346579,0.079207,0.795945,-0.391469,-0.008525,0.478307,-0.341890,-0.439377,-0.590066,-0.036919,-0.075281,0.113026,-0.373736,-0.205271,-0.173070,-0.170541,-0.549092,0.568427,-0.117283,-0.151017,0.266701,0.228911,0.297559,-0.103292,-0.211605,0.125149,0.099760,0.427269,-0.042116,-0.695698,0.223540,-0.258931,0.150245,-0.065841,-0.193715,0.025730,0.195170,0.310482,-0.136660,0.329696,-0.158227,0.529841,0.140678,-0.331618,-0.014388,0.470036,-0.110121,0.448301,0.473024,0.250132,-0.254899,-0.092420,-0.393582,-0.578481,0.205975,0.209512,0.036615,-0.462734,0.510765,-0.073331,-0.270364,-0.140456,-0.183557,0.013648,0.253977,0.632651,0.388058,0.145144,0.057569,-0.300372,0.306722,0.523426,0.146933,-0.352902,0.110408,-0.264131,-0.560615,-0.290193,-0.548425,-0.595850,0.189816,0.362333,-0.469756,0.018163,0.729864,-0.528850,-0.021448,-0.215771,-0.284908,0.244871,-0.094616,0.182712,-0.695037,-0.293278,-0.524837,-0.216906,-0.292779,0.318684,-0.088183,0.881587,-0.329538,0.283347,0.396090,0.308064,-0.152654,0.918852,-0.082640,0.152997,-0.188287,-0.066567,0.475617,-0.182621,-0.300739,-0.055860,0.229253,-0.092681,-0.308871,0.122230,0.434284', '26647163', '22265121', '27602116', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300958', '沉默', '剧情', '战争阴影还没消散的欧洲，翻译家、知识分子Ester（英格里德•图林）与妹妹Anna（冈内尔•林德布洛姆）以及Anna的儿子Johan一起坐火车回瑞典。途中，患有晚期肺病的Ester发病，三人于一个言语不通的小城下车，住进一家老宾馆。Ester有意无意间总想偷窥Anna的生活，想对她表示好感却无从下手，而Anna一心认为Ester是她的束缚。某晚，Anna外出结识一名酒保，返回宾馆后将幻想中的性爱的过程和刺激描述给Ester听，引起对方的激烈反应，随后，她与酒保在Ester眼皮底下做爱，终引起Ester爆发，多年来深藏在两人心中的、夹杂着嫉恨与冲突的往事被重提。©豆瓣', '英格丽·图林', '英格玛·伯格曼', 8.3, 5953, 'tt0057611', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1886928672.jpg', 0.5, 1.2, 14, 49.6, 34.7, '0.518057,0.092745,-0.964584,0.591870,0.171091,-0.383274,1.018112,0.000438,-0.538691,-0.375855,0.011465,0.758193,-0.457587,0.278015,0.309299,-0.271047,-0.256581,-0.715018,0.101414,0.041527,-0.281907,-0.343066,-0.101588,-0.148638,-0.251883,-0.397404,0.236048,0.205578,-0.423414,0.617067,0.164811,0.619331,-0.227173,0.569111,-0.022888,-0.014670,-0.032026,0.203570,-0.362499,0.124811,0.336295,-0.232122,-0.273423,-0.018181,0.090016,0.320963,0.693764,0.063276,-0.141177,-0.042744,0.086559,-0.210660,-0.043463,0.232895,0.257805,0.055266,0.165690,0.109964,-0.268491,-0.079729,-0.084114,0.183344,-0.395704,0.112421,0.016927,0.155758,-0.587593,0.296093,0.092097,-0.113058,-0.037045,-0.158732,0.158881,0.296532,0.120288,0.499137,-0.114613,0.146947,-0.479678,-0.056667,0.773666,-0.267070,-0.297992,0.144035,-0.095017,-0.261830,0.144327,0.075699,-0.394887,-0.217217,0.137647,-0.011309,-0.237567,0.347325,-0.564095,-0.086359,-0.432593,-0.138926,0.186962,-0.185043,-0.254120,-0.623806,-0.285690,-0.330546,-0.216704,0.086465,0.168421,-0.034206,0.475465,-0.732799,0.321555,0.439564,0.404731,-0.535626,0.610185,0.231268,0.109693,-0.217513,-0.082155,0.178766,-0.036164,0.040379,0.088700,0.293044,-0.149805,-0.006837,-0.393125,0.332004', '1296534', '3011051', '3111650', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300960', '碧海蓝天', '剧情', '杰克（让-马克•巴尔 Jean-Marc Barr）在希腊海边长大，虽然小时候眼看着爸爸死于一次潜水事故，却没有削减杰克对大海的热爱。当杰克的朋友恩佐（让·雷诺 Jean Reno饰）找到他，劝说他参加潜水冠军大赛时，杰克答应了，在比赛中成绩突出勇夺冠军，并且得到了乔安娜（罗姗娜•阿奎特 Rosanna Arquette饰）的爱。两人打得火热，杰克却意识到他放不下、离不开大海。意外发生了。好友恩佐在潜水中不幸丧生，杰克把恩佐的尸首放入大海当中，杰克的心中非常迷乱，他觉得自己不再属于人类社会，只想潜进深海，像海豚一样陪伴大海一生。尽管传来了乔安娜怀孕的消息，杰克深情的看了看爱人，转身投入了大海的怀抱。©豆瓣', '让-马克·巴尔', '吕克·贝松', 8.7, 139237, 'tt0095250', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p455724599.jpg', 0.4, 1.2, 11.9, 37.1, 49.4, '-0.011087,-0.010603,-0.826055,0.520812,-0.059865,-0.578600,1.017076,0.020836,-0.434296,0.168706,0.006189,0.815406,-0.078864,0.096021,0.139614,0.103133,-0.524037,-0.702105,-0.035218,0.068404,-0.248349,-0.562729,-0.152798,0.037621,0.093856,-0.289384,0.542946,-0.093539,-0.160977,0.586467,0.008412,0.184808,0.226168,0.660677,-0.253088,0.115055,0.179769,0.235060,-0.361071,0.355516,0.220828,0.120416,-0.180552,0.310047,0.404317,-0.019891,0.722758,-0.441084,0.027756,0.025080,0.137653,-0.275301,0.164692,-0.029419,0.050591,0.117357,-0.129204,-0.137150,-0.035438,-0.012801,0.265206,0.151770,-0.296810,0.158058,-0.030498,0.316581,-0.509942,0.449009,-0.117140,-0.030982,0.261757,-0.260166,0.204769,0.042614,0.202158,0.390472,-0.220574,0.182989,-0.534330,0.285250,0.716491,-0.069037,-0.159362,0.232482,-0.063358,-0.505358,0.141599,0.122346,-0.494724,0.011420,0.615116,0.094034,-0.456435,0.393304,-0.228728,0.058043,-0.071713,-0.435108,-0.230851,-0.520180,-0.244129,-0.411839,-0.190713,-0.347675,-0.162941,-0.155635,-0.314829,-0.368587,0.597129,-0.754551,0.334000,0.528054,0.229798,-0.157284,0.789998,0.150479,-0.054070,-0.346276,0.315649,0.576666,-0.012826,0.184878,0.437276,0.228617,0.053640,0.011571,-0.409134,0.602954', '1296534', '1292211', '4275444', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300966', '独行杀手', '剧情', '杰夫（阿兰·德龙 Alain Delon 饰）是一名沉默寡言的杀手，他住在一间旅馆里，仅与一只鸟为伴。独来独往的他接到委托暗杀俱乐部的老板，尽管行动天衣无缝，但警察还是扣押了他。钢琴女马蕾莉（凯茜·罗齐尔 Cathy Rosier 饰）认出了杰夫就是当天的可疑男子，但她却选择了包庇杰夫，这使杰夫心生疑虑。杰夫找到中间人结算工钱，没想到中间人开枪打伤了他。逃过一劫的杰夫暗中查明了雇主的身份，找到并且杀死了他，但同时，他发现，当初袒护他的马蕾莉，居然是雇主的情人。心情复杂的杰夫举着手枪来到俱乐部质问马蕾莉，却被早已埋伏在此的警察乱枪打死，事后，警察们发现，杰夫的手枪中并没有子弹，他这一行为的意义也成为了一个永远的秘密。©豆瓣', '阿兰·德龙', '让-皮埃尔·梅尔维尔', 8.3, 21289, 'tt0062229', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2276173501.jpg', 0.4, 1.4, 14.2, 48.1, 35.8, '0.323038,-0.011905,-0.590809,0.375355,-0.499293,-0.212671,0.768604,-0.047774,-0.360047,-0.325284,0.466670,0.675311,0.012000,0.123856,0.180368,0.048152,-0.181058,-0.538016,0.104066,-0.102995,-0.113352,-0.564513,-0.312773,-0.490103,0.116823,-0.116200,0.489565,-0.031849,-0.160367,0.326019,0.239857,0.262294,0.074493,0.534990,-0.151394,0.056875,0.328235,-0.341080,-0.072228,0.260969,-0.148869,-0.278563,-0.153596,0.381842,-0.072401,0.913174,0.331804,-0.124360,-0.357059,0.126587,0.149471,-0.392652,-0.021371,0.128505,0.376653,-0.125110,0.081080,0.221000,-0.286040,0.100273,0.098885,0.225051,-0.670892,0.224477,-0.020196,0.227727,-0.580158,0.352857,-0.430029,0.130230,-0.310940,-0.326124,0.329460,-0.043129,0.095899,-0.002173,-0.178580,0.024957,-0.645982,-0.082591,0.622357,-0.273377,-0.010599,0.090567,-0.111753,-0.444741,0.155635,0.022534,-0.242568,-0.137175,0.497093,-0.055887,-0.200852,-0.197402,-0.428554,-0.165381,-0.465858,0.088562,-0.278775,-0.519200,-0.170746,-0.334986,-0.037545,-0.204432,-0.653773,0.091712,0.089409,-0.095669,0.416626,-0.841391,0.082193,0.597232,0.194105,-0.384985,0.547461,0.186412,0.047926,-0.093114,-0.287959,-0.038724,0.408091,0.303477,0.234875,0.327129,0.156018,-0.543149,-0.076830,0.176743', '1947080', '1920730', '3263169', '1308762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300977', '飞向太空', '剧情', '心理学家克里斯•凯尔文（Donatas Banionis 饰）在飞往索拉瑞斯星之前来到儿时的父母家与当年的索拉瑞斯飞行员亨利•伯顿（Vladislav Dvorzhetsky 饰）见面。伯顿警告凯尔文索拉瑞斯星上会有不可思议的奇事发生，但后者并不以为意。凯尔文离开前，当 着父亲（尼古莱•格陵柯Nikolai Grinko 饰）的面焚毁了自己的个人物品。凯尔文到达索拉瑞斯星附近的太空站后，对科学家奇巴瑞安博士（Sos Sargsyan 饰）之死进行调查，却发现自己多年前已经去世的妻子哈莉（Natalya Bondarchuk 饰）竟突然出现。惊慌失措的凯尔文与太空站上的科学家们讨论该如何面对怪事，却发现原来每人都深受其扰，不明就里……本片被提名1972年戛纳电影节金棕榈奖，并获同年戛纳电影节评委会大奖和国际影评人协会大奖。©豆瓣', '纳塔莉亚·邦达尔丘克', '安德烈·塔可夫斯基', 8.7, 27911, 'tt0069293', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p573091524.jpg', 0.6, 1.5, 11.1, 36.8, 50, '0.250376,-0.049798,-0.724504,0.228408,0.549070,-0.437233,0.589036,0.044369,-0.510824,-0.294030,0.224397,0.809597,-0.511481,0.258309,0.425771,0.266966,-0.929536,-0.671793,0.036182,-0.428653,-0.209316,-0.438203,-0.244366,0.120828,-0.164796,-0.322482,0.358739,-0.155696,0.023577,0.728220,0.471213,0.489676,-0.064500,0.423571,0.195199,0.326408,0.503016,0.188979,-0.254593,0.222832,0.087552,0.181392,-0.419011,-0.095437,0.394251,0.307266,0.362415,-0.251356,0.137987,-0.229596,0.270299,-0.209360,0.255032,0.025581,0.218893,0.009575,0.190591,0.236847,-0.015232,0.196420,0.057198,-0.259172,-0.346282,0.347754,-0.010120,0.234796,-0.442144,0.251843,-0.299902,0.003931,-0.256634,-0.195266,0.236784,0.465277,0.134016,0.165136,-0.036695,0.077924,-0.251799,0.090645,0.177369,-0.024849,-0.469661,0.056421,-0.088533,-0.548221,-0.165031,-0.099607,-0.478519,0.248855,0.349215,0.135399,0.059975,0.416121,-0.424013,-0.165618,-0.600280,-0.134819,0.093117,-0.020149,-0.134716,-0.765414,0.179172,-0.216713,-0.373429,-0.066867,0.093661,-0.224011,0.310059,-0.533094,0.294538,0.036274,0.470710,-0.056781,0.371371,-0.107963,-0.071716,-0.109434,-0.368643,0.498568,0.119037,0.219713,-0.154663,0.084798,0.335562,-0.294677,0.001494,0.347180', '3036464', '2075345', '1298616'