INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300992', '完美的世界', '剧情', '单亲孩子菲利普·佩里（T·J·劳瑟 T.J. Lowther 饰）的母亲对他管教甚严，8岁的小菲利普甚至从未参加过一次鬼节讨糖果的游戏。附近州监狱的两名罪犯越狱成功，劫持了菲利普作为人质，向德州边界逃窜。途中，罪犯之一的布奇（凯文·科斯特纳 Kevin Costner 饰）干掉了鲁莽愚蠢的同伙，却对小菲利普照顾有加。与此同时，德州警探瑞德（克林特·伊斯特伍德 Clint Eastwood 饰）带着手下和州长特派的犯罪专家萨利（劳拉·邓恩 Laura Dern 饰）一同火速追捕布奇。双方在德克萨斯州境内展开了一场公路赛大竞技；而小菲利普也经历了很多从未想过过的刺激与快乐，并与布奇产生了一种近似父子的不寻常感情……©豆瓣', '凯文·科斯特纳', '克林特·伊斯特伍德', 9.1, 289540, 'tt0107808', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2190556408.jpg', 0.1, 0.4, 5.4, 30.3, 63.8, '0.148652,-0.403153,-0.672215,0.666641,-0.207713,-0.226887,0.730430,0.105920,-0.628163,-0.156657,0.263464,0.893059,-0.304540,0.082689,0.236938,-0.031180,-0.369808,-0.563299,-0.133524,-0.256294,-0.344081,-0.461546,-0.348024,-0.194806,-0.062028,-0.319080,0.175704,-0.228663,-0.125196,0.727942,0.291706,0.189058,-0.041115,0.295504,0.049178,-0.006381,0.520810,0.039236,-0.400845,-0.002156,-0.022343,0.039747,-0.207017,-0.033892,0.191346,0.496715,0.573850,-0.484699,0.044295,-0.383991,0.022849,-0.272169,0.147793,0.129222,0.229544,0.018926,0.094234,0.247011,0.006049,-0.090468,0.149626,-0.192275,-0.583376,0.165413,0.072074,0.105921,-0.452188,0.325250,-0.319669,0.032485,0.094741,-0.258766,-0.127746,0.337355,-0.011722,0.229509,-0.088122,-0.124077,-0.439974,0.221615,0.635367,-0.150744,-0.300920,-0.044678,-0.194990,-0.497947,0.166080,-0.248480,-0.561651,0.061073,0.431370,-0.271323,-0.153559,0.453649,-0.381624,-0.020515,-0.572119,-0.172720,0.090408,-0.145419,0.142998,-0.796066,0.207855,-0.479679,-0.335304,0.002634,0.175957,0.080712,0.511985,-0.739794,0.399092,0.744544,0.511175,-0.402145,0.384360,0.270454,0.187403,-0.148507,-0.140744,0.285011,0.275785,0.183009,0.246443,0.327721,0.058908,-0.375328,-0.076199,0.378647', '3285622', '3178770', '11541282', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1300993', '油脂', '爱情', '活泼纯真的澳大利亚姑娘珊迪·奥森（奥莉维亚·纽顿-约翰 Olivia Newton-John饰）在暑假去美国游玩时，邂逅了学校“硬汉帮”的老大丹尼·祖克（约翰·特拉沃塔 John Travolta饰）。对丹尼一见钟情的珊迪，极不情愿地与丹尼吻别后踏上了回家的归途。一段青 涩甜蜜的初恋，就这样随着炎热的夏天结束了。然而峰回路转，桑迪的父母决定移居美国，更令桑迪激动的是，她发现自己居然和丹尼在同一所学校读书。为了追求丹尼，原本端庄稳重的珊迪变得赶时髦潮流，也故意和全校有名的帅气运动员约会。然而事情却不像珊迪期望的那样进行着。本片荣获1979年第51届奥斯卡金像奖最佳原创歌曲提名，1979年第36届金球奖电影类-音乐喜剧类最佳影片提名、最佳女主角提名等多项大奖。©豆瓣', '约翰·特拉沃尔塔', '兰德尔·克莱泽', 7.4, 6471, 'tt0077631', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p928948018.jpg', 0.9, 4, 37.3, 40.9, 16.9, '0.232971,-0.207755,-0.660431,0.611032,0.330203,-0.520505,0.346705,0.159330,-0.274201,-0.101874,-0.137297,0.706370,-0.386103,0.375338,0.371470,0.140319,-0.503114,-0.449995,-0.147617,-0.229147,0.075003,-0.355022,-0.126236,0.267851,0.074218,-0.415895,0.562803,-0.212169,0.024389,0.826009,0.697394,0.154123,0.129789,0.262375,-0.036315,0.005674,0.442905,0.242313,-0.363518,0.348119,0.115910,-0.050843,-0.366673,-0.128088,0.223603,0.192889,0.508543,-0.028566,0.088841,0.134728,0.698893,-0.250065,-0.202141,-0.026550,0.189423,-0.295389,0.295480,0.152798,0.021859,0.302897,-0.030284,-0.379121,-0.350877,0.211685,0.152255,0.167564,-0.423092,0.452365,-0.218215,0.086407,0.158340,-0.200148,0.041833,0.306007,0.223663,0.232191,0.030323,0.132402,-0.244741,0.459065,0.566756,0.083111,-0.478305,0.387372,-0.168113,-0.449765,0.134382,-0.250464,-0.579158,0.193617,0.185826,-0.061408,0.149020,0.213501,-0.588346,-0.146432,-0.119184,-0.080892,-0.043429,-0.326807,-0.090068,-0.659439,0.037802,-0.330629,-0.189155,-0.230528,-0.002927,-0.309274,0.614968,-0.720920,0.400896,0.557500,0.079015,-0.170290,0.656821,0.209784,0.100221,-0.471214,-0.211158,0.302528,-0.222560,0.030077,0.002205,0.583662,-0.015873,-0.395792,-0.423758,0.575318', '26365262', '3811356', '1293726', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301022', '哗！英雄', '喜剧', '阿华（刘德华 饰）一直想当一名好警察，正当他得到了好机会正想大展拳脚的时候，他被调至的小组意志十分消沉，完全没有工作的干劲。他们的队伍常常受到另一队由张扬（张耀扬 饰）的出色人马藐视。阿华十分不满扬的作风，更在一次行动中与之发生冲突。阿华的母亲（林建明 饰）召回了家中，因为阿华的女友阿兰（张曼玉 饰）受父亲（秦沛 饰）所逼要嫁给一个与她完全没有感情的有钱人，阿兰的父亲更是阿华的师傅，情与义之间不知如何抉择。令阿华更加烦恼的是，自己的母亲竟然与自己的同事秋（黄秋生 饰）发生了感情。回到警察局后，一群匪徒企图闯进入拯救自己的同党，但阿华成功擒拿匪徒的功劳竟然被张扬设计夺走。忍无可忍的阿华决定与张扬在跆拳道赛中一决胜负。©豆瓣', '刘德华', '陈木胜', 6, 4670, 'tt0104458', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350645101.jpg', 3.1, 18.5, 58.5, 13.7, 6.2, '0.222776,-0.049746,-0.745086,0.586134,-0.367466,-0.359639,0.652314,0.050542,-0.602059,-0.411174,0.250665,0.645656,-0.047244,0.216748,0.189824,-0.248307,-0.044615,-0.820934,-0.000609,0.045227,-0.118001,-0.356643,-0.166599,-0.002715,-0.099462,-0.146025,0.579788,-0.136935,-0.184001,0.451510,0.410146,0.208432,0.027052,0.623129,-0.124932,0.076320,0.094969,-0.016002,-0.248431,0.020519,0.163716,-0.267846,-0.134882,0.306264,-0.099416,0.340728,0.663332,-0.193187,-0.220595,-0.040070,0.321895,-0.219840,0.054061,0.168504,0.139486,0.013481,0.114590,0.191537,-0.124479,0.065949,0.057387,-0.128311,-0.672978,0.075772,0.116261,0.060026,-0.597850,0.399103,-0.182672,0.077186,0.106598,-0.301454,0.034143,0.369732,0.316006,0.162717,-0.312632,-0.119839,-0.469700,0.043552,0.776209,-0.108228,0.060599,0.200113,-0.112412,-0.343251,0.080109,-0.201318,-0.443635,-0.006074,0.427836,-0.060672,-0.054301,0.014319,-0.473584,-0.131872,-0.191671,0.074824,-0.151372,-0.420334,0.151160,-0.414771,-0.119441,-0.457668,-0.412642,0.069655,0.023571,-0.119111,0.616964,-1.003957,0.050103,0.234197,0.306249,-0.658564,0.361083,0.161559,0.133731,-0.193349,-0.171548,0.052902,0.082937,0.154954,0.234108,0.275759,-0.063274,-0.253878,-0.174258,0.231535', '35030151', '30345227', '1293265', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301026', '革命往事', '战争', '故事发生在二十世纪初的墨西哥革命中。一辆长途马车里，高贵的先生女士们对一位沉默寡言的农民大放厥词，然而突然农民摇身一变，显出家庭式匪帮头目胡安（Rod Steiger 饰）的真面目。胡安打劫后路遇爱尔兰革命军爆破专家约翰（James Coburn 饰），后者的爆破能力令抢劫梅萨维德银行如探囊取物，于是胡安苦苦尾随，不经意间却卷入了配合维拉革命军的梅萨维德暴动。胡安如愿与约翰搭档洗劫银行，但他所有的收获却是解放150名政治犯人。政府军上校刚特率军镇压革命，胡安与革命队伍付出了惨痛的代价。在逆境中，约翰与胡安产生了真正的革命情谊，二人在前往美国的路上折返阻击刚特上校，当约翰中弹之时，这位老战士看到了昔日在爱尔兰的温馨场景……本片获1972年意大利大卫奖最佳导演奖。©豆瓣', '罗德·斯泰格尔', '赛尔乔·莱昂内', 9.2, 18282, 'tt0067140', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206010357.jpg', 0.1, 0.6, 5.4, 29, 64.8, '0.073971,0.077969,-0.648695,0.264651,0.111971,-0.539949,0.682631,0.036631,-0.435077,-0.146795,0.288150,0.828823,-0.144660,-0.205362,0.533898,-0.208509,-0.421087,-0.691153,-0.160919,-0.087953,0.089393,-0.227136,-0.483171,-0.258168,-0.059515,-0.436154,0.517581,0.254550,-0.194081,0.704500,0.195942,0.498114,-0.113030,0.345150,0.089468,0.107455,0.428781,-0.077531,-0.536365,0.000678,-0.222061,-0.313947,-0.478843,-0.076701,0.033770,0.307174,0.604669,-0.411502,0.059750,-0.160779,0.091936,-0.167682,0.022002,0.058871,0.167641,0.006413,0.099718,0.241540,0.132592,0.078261,-0.116009,-0.131946,-0.387684,-0.126055,-0.132924,0.183754,-0.528158,0.377625,-0.182610,0.325537,0.157824,-0.154298,0.141719,0.445134,0.127778,0.326255,-0.091690,-0.013468,-0.444917,0.128703,0.557717,-0.199361,-0.375545,0.149611,-0.357322,-0.483974,0.205452,-0.176405,-0.224861,-0.095515,0.412883,-0.331730,0.244071,0.365587,-0.782478,-0.170007,-0.438402,0.060143,-0.218445,-0.011102,-0.144699,-0.812465,-0.107409,-0.308478,-0.056140,0.185924,-0.036186,0.072134,0.598496,-0.551271,0.134898,0.383276,0.044531,-0.119296,0.382389,0.004044,0.052642,-0.122448,-0.245803,0.225914,0.123604,0.307865,-0.020307,0.283909,-0.249156,-0.278488,0.000939,0.235079', '11541282', '1292050', '1303333', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301061', '纽约黑帮', '剧情', '一个多世纪前的纽约，腐败政客用见不得人的龌龊手段争夺着这个城市的官方领导权；而在曼哈顿岛五分区、包里区、天堂广场一带，爱尔兰移民的黑帮组织“死兔党”和“本地党”则明目张胆地以武力争夺着地盘和一切可以占有的东西…… 《纽约黑帮》海报 “死兔党”的老帮主普瑞斯特·维伦（连恩·尼森）被“本地人党”的头儿、“屠夫”比尔·普尔（丹尼尔·戴-刘易斯）干掉，死者年轻的儿子阿姆斯特丹·维伦（莱昂纳多·迪卡普里奥）继承了首领的位置。当然，他上任后的第一桩“买卖”就是杀死比尔替父亲报仇。然而，帮派之间历时数年的争斗使得其间的孰是孰非已经纠缠不清，“屠夫”比尔又真的是个冷血凶残、杀人不眨眼的屠夫，这些都让阿姆斯特丹的复仇计划困难重重。 　　结识女贼珍妮·埃佛迪安（卡梅伦·迪雅兹）似乎让事情出现了转机，她的帮助给了阿姆斯特丹新的希望，而且两人在互相的合作、利用中渐渐坠入了爱河——谁知道这对于复仇之路究竟是福还是祸呢……', '莱昂纳多·迪卡普里奥', '马丁·斯科塞斯', 7.6, 59089, 'tt0217505', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1744930742.jpg', 0.4, 2.8, 32.2, 47.8, 16.7, '0.232029,-0.018680,-0.507031,0.493197,-0.167343,-0.380681,0.434010,-0.003871,-0.332249,-0.032804,0.058346,0.761056,0.096815,0.113456,0.258775,0.056838,-0.287222,-0.648895,-0.132011,-0.276176,-0.139211,-0.578009,-0.397855,-0.295127,-0.052985,-0.159724,0.489405,0.221460,-0.041494,0.211172,0.525190,0.255414,0.072274,0.254052,-0.178697,-0.088573,0.331970,-0.098499,-0.377088,0.153948,-0.042862,-0.009067,-0.112609,0.233510,0.139291,0.424422,0.387348,-0.258381,0.107004,-0.297140,0.258397,-0.283327,0.096497,0.086521,0.515081,-0.269611,0.183270,0.470341,-0.042473,-0.291944,0.033994,0.031349,-0.870241,0.007120,0.115500,0.066781,-0.623698,0.311611,-0.039421,-0.026702,-0.026004,-0.134792,0.397021,0.489876,0.349543,0.301823,0.075007,-0.114067,-0.504144,-0.048836,0.620144,0.047753,-0.174861,0.032270,0.040955,-0.381137,-0.020156,-0.379197,-0.208826,-0.168320,0.309582,-0.492089,-0.035792,0.549681,-0.729945,-0.002078,-0.219455,-0.050855,0.100001,-0.297570,-0.046200,-0.480114,-0.226212,-0.237060,-0.083464,0.096436,0.185445,-0.081083,0.485987,-0.743144,0.103376,0.862854,0.355640,-0.564802,0.540052,0.225744,0.190253,-0.284672,-0.183433,0.108275,0.262363,0.251274,0.110090,0.260842,0.060728,-0.321258,-0.048268,0.574604', '1793491', '26678784', '27009869', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301081', '垂帘听政', '剧情', '英法联军烧毁圆明园后，又迫使懦弱昏庸的清政府签定了一系列不平等的条约，在中国的嚣张气焰可谓不可一世，胆小怕事的清帝咸丰（梁家辉）躲在了热河行宫内。除去皇后（陈烨），常在咸丰身边出没的妃子有丽妃（周洁）和懿贵妃（刘晓庆），懿贵妃极力讨好咸丰，但丽妃明显更受咸丰宠爱。三十 寿诞时，咸丰突然重病不起，弥留之际，有心篡位夺权的大臣肃清（项堃）因看出懿贵妃为人十分有心计，私下建议赐死懿贵妃再立幼主，咸丰初听觉得有理，察觉肃清心怀不轨后，口谕他与其他七位大臣为辅佐幼主的摄政大臣，并赐“同道堂”印与懿贵妃，叮咛她与皇后齐心协力抚育幼主。咸丰大丧之时，肃清赠皇后与懿贵妃徽号慈安与慈禧，妄图哄骗她们掌握政权，但他终没斗过慈禧。收拾完肃清，慈禧亦没放过慈安。©豆瓣', '刘晓庆', '李翰祥', 7.6, 14177, 'tt0085336', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528965516.jpg', 0.3, 1.5, 30.8, 52.3, 15.2, '0.206350,0.244661,-0.413648,0.729988,0.247354,-0.235557,0.506144,0.508791,-0.762457,-0.086073,0.516852,0.252215,-0.518397,-0.378942,0.070219,-0.202347,-0.452915,-0.380499,-0.270927,-0.238452,0.189010,-0.404483,0.345982,-0.191300,-0.613373,-0.430439,0.689874,-0.363510,0.416391,0.212143,0.157771,-0.065571,0.069936,0.417046,-0.128691,0.175734,-0.359304,-0.436878,-0.257297,-0.099015,0.029401,-0.818333,-0.681928,0.287107,0.075452,0.144334,0.119086,-0.796713,0.225846,-0.505368,0.411231,0.066540,-0.024541,0.590663,0.299415,0.147675,0.073120,0.758143,-0.156949,-0.088491,-0.169102,0.137019,-0.358688,-0.056288,0.088570,-0.067704,0.082654,0.570426,-0.002977,0.204505,-0.127034,-0.166866,0.622712,0.665162,-0.371560,0.315801,-0.248913,0.071150,-0.432095,0.324831,0.182744,-0.034255,-0.124428,-0.121838,0.157210,-0.170922,0.581009,-0.361575,-0.009565,-0.080913,0.005702,-0.245887,0.220672,0.584443,0.086450,-0.236552,-0.656928,0.325892,0.193929,-0.236756,0.103317,-0.099322,-0.286051,-0.408588,-0.282027,-0.114026,0.487295,-0.078432,0.075547,-0.492359,0.166945,0.023745,0.587792,-0.737186,0.536650,0.105968,0.077566,0.089737,-0.510478,-0.320362,-0.118737,-0.210030,-0.135942,0.117663,-0.224621,-0.350792,-0.319688,-0.230314', '1305720', '1437318', '1299578', '3606975');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301105', '代号美洲豹', '剧情', '1988年9月，一伙名为“亚洲黑色特别行动小组”的恐怖分子劫持了环洋公司董事长屈孝真乘坐的专机，飞机迫降大陆。以郑贤平（葛优 饰）为首的恐怖分子以炸机要挟台湾当局释放其小组组长刘庭君。大陆方面召开紧急会议，决定立即通知台湾当局，双方建立合作，共同解救人质，打击恐怖分子，行动代号“美洲豹”。 以梁壮（刘小宁 饰）率领的中国人民解放军反劫机突击队与台湾反恐怖突击队先后来到机场，但反劫机行动接连遭到挫败，双方经过研究，决定进行最后的冲击……©豆瓣', '刘小宁', '张艺谋', 5.4, 5028, 'tt0097144', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2321293139.jpg', 9.8, 30, 45, 11.1, 4.1, '-0.024278,-0.243671,-0.569355,0.524868,0.383182,0.367348,-0.367293,0.117750,-0.444974,-0.132599,0.594460,0.431948,0.117195,-0.284536,0.677929,-0.497223,-0.459689,-0.702629,-0.124389,-0.200680,-0.291794,-0.543908,0.075779,-0.377007,0.362541,-0.119736,0.890465,0.172836,-0.130760,0.711395,0.251660,0.418255,-0.416211,0.301243,0.288188,-0.493025,0.422707,-0.354126,-0.731168,0.132333,-0.277666,0.032276,0.182979,0.098561,0.306708,0.485518,0.598217,-0.125392,0.034099,-0.744803,-0.103930,-0.561112,0.100236,-0.417404,0.889201,0.608172,0.190384,0.592115,0.161241,-0.152153,-0.222826,-0.296205,-0.286839,0.198003,0.132519,-0.480083,-0.307976,0.081694,-0.484982,0.714228,0.070193,0.199656,0.072468,1.009541,0.444649,0.084926,0.223564,0.302641,-0.181184,0.085419,0.518646,-0.359882,-0.184542,-0.459710,0.346781,-0.278440,0.086473,-0.430689,0.508273,-0.042002,-0.066922,-0.029133,0.131526,-0.077065,-0.710200,-0.132983,-0.437040,-0.306348,0.190299,-0.422322,0.292896,-1.281337,0.117515,0.315821,0.048370,0.375054,0.063921,0.464042,0.495328,-0.582038,-0.097370,0.154230,0.427885,-0.711457,0.177280,-0.000863,-0.051833,-0.608638,0.213840,0.107883,-0.050258,0.374745,-0.219131,-0.017534,-0.146145,-0.062978,0.029995,-0.638865', '1293572', '2369613', '1306809', '3562446');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301106', '布达佩斯之恋', '剧情', '人们总是难以抗拒《忧郁星期天》的悲伤情调，原来这首歌与一段复杂凄美的爱情故事有关。上世纪30年代的匈牙利首都布达佩斯的一个餐馆里，美丽的伊洛娜（艾丽卡·莫露珊 Erika Marozsán 饰）同时被两个男人深爱着。一个是餐厅老板，另一个是钢琴师。三个人都并不愿意改变现况，打破平衡，伊洛娜同时拥有两个男人的爱而深感平静幸福。钢琴师为她创作出《忧郁星期天》，他和餐厅也因此一举成名。然而，汉斯的出现彻底毁灭了这一切。他曾经是一个无名小子，深深迷上《忧郁星期天》 的同时，更是成为伊洛娜的裙下之臣。汉斯向伊洛娜求婚，却被拒绝，满腔恨意的他如今成了军官，风光无限，正带着他蓄谋已久的复仇计划来到伊洛娜身边，给他们的生活以致命一击。爱、复仇与战争的故事，在布达佩斯纠结上演。©豆瓣', '艾丽卡·莫露珊', '诺夫·舒贝尔', 8.6, 77449, 'tt0155722', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p467734271.jpg', 0.2, 0.9, 11.7, 42.8, 44.3, '0.305145,0.270036,-0.733623,0.657198,-0.159073,-0.273837,0.992291,-0.045490,-0.465452,-0.184309,0.123982,0.693129,-0.102220,0.478993,0.211334,0.084047,-0.155464,-0.717878,-0.177633,-0.047851,-0.069615,-0.357650,-0.261176,-0.106273,-0.045097,-0.233264,0.574761,0.311393,-0.062595,0.472537,0.540907,0.434739,-0.147643,0.624623,-0.141915,-0.140649,-0.023371,-0.306396,-0.289213,0.108361,-0.091667,-0.226552,-0.147345,0.393469,-0.514891,0.194448,0.642570,-0.110935,-0.267442,-0.178682,0.553947,-0.329460,-0.348628,0.104799,-0.086305,-0.031317,0.138909,0.037314,-0.247360,-0.280496,0.030491,-0.126537,-0.897475,0.099875,-0.024710,0.257147,-0.537790,0.666524,0.048539,-0.168157,0.147576,-0.249651,0.165414,-0.070467,0.490041,0.588128,-0.214208,0.157130,-0.443283,0.092122,0.941950,0.080995,-0.259768,0.370953,-0.381692,-0.162135,-0.041370,-0.269061,-0.658003,0.179899,0.133076,0.031545,0.016674,0.233864,-0.649339,0.102476,-0.298511,-0.086209,0.052195,-0.704350,-0.214024,-0.482856,-0.157843,-0.269682,-0.537177,0.117777,0.130031,-0.331039,0.744341,-0.847288,0.295428,0.506953,0.222009,-0.416677,0.847726,0.250879,-0.042714,-0.117586,-0.080239,0.397464,-0.243475,-0.162471,-0.040535,0.515640,-0.209845,0.200156,-0.581721,0.746152', '2081098', '24756472', '2053515', '1304641');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301119', '狼族盟约', '动作', '影片根据发生在法国国王路易十五统治时期的真实事件改编。18世纪60年代中期，法国路易十五在位时，一只凶残异常的巨狼一直威胁着吉瓦冈地区，而受害者多是妇女和儿童。一时间，全法国都被触目惊心的血腥杀戮震惊了，无人知道凶兽真正面貌，有人盛传是魔鬼化身。为安定民心，路易十五指派皇家骑士弗朗萨克（塞缪尔·勒·比汉 Samuel Le Bihan 饰）捕杀怪兽。在吉瓦冈逗留期间，弗朗萨克爱上了当地伯爵的女儿玛丽安（艾米莉•德奎恩饰），还与美艳动人的官妓西尔维亚（莫妮卡·贝鲁奇 Monica Bellucci 饰）有染，并结识了玛丽安的哥哥让－弗朗索瓦（文森特·卡索 Vincent Cassel 饰）。随着调查的逐渐深入，弗朗萨克从被害者遗体上发现了一颗钢牙，而一位目击者发誓宣称有人控制着巨狼。随着调查，掀起更恐怖阴谋，一场场血腥杀戮战连串发生……©豆瓣', '塞缪尔·勒·比汉', '克里斯多夫·甘斯', 6.6, 8649, 'tt0237534', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1623008321.jpg', 2, 10.5, 49.6, 29.7, 8.2, '0.025309,-0.158296,-0.630871,0.440934,0.233113,-0.005867,0.861434,0.069756,-0.516694,-0.219622,0.346837,0.416272,-0.348477,-0.117667,0.397800,-0.115050,-0.226128,-0.511708,0.068691,-0.137039,0.012852,-0.361037,-0.455126,-0.177097,-0.017841,-0.770960,0.490566,0.162850,-0.195120,0.178241,0.259175,0.388923,-0.268350,0.191241,-0.048764,-0.314297,0.256465,-0.191401,-0.108923,0.116938,-0.090451,-0.240039,-0.110121,0.065449,-0.234825,0.294808,0.433497,-0.467990,0.057548,-0.414513,0.478581,-0.041673,0.103565,0.241619,0.471187,-0.117518,-0.043637,0.231128,0.063845,-0.172267,0.114639,-0.028623,-0.512230,0.105880,-0.122912,0.435554,-0.445463,0.386419,-0.258616,0.142391,0.215292,-0.057341,0.347341,0.381440,0.086952,0.201161,0.144930,-0.011611,-0.402109,0.293187,0.599128,-0.017190,-0.352294,-0.027228,-0.275565,-0.577647,-0.046635,-0.343422,-0.408726,-0.013489,0.185158,0.101676,-0.092372,0.617348,-0.427515,-0.223164,-0.506776,-0.303930,-0.002289,0.053556,-0.185048,-0.616167,-0.372987,-0.319408,-0.037512,-0.166589,-0.002276,-0.235244,0.480714,-0.606590,0.366811,0.692267,0.375040,-0.199434,0.329340,-0.176095,0.043586,0.043459,-0.333997,0.413411,0.369789,-0.032680,0.129724,0.235786,0.008614,-0.243109,0.059720,0.410764', '1307311', '3005387', '3231742', '2377539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301136', '空山灵雨', '剧情', '故事发生在名为“三宝寺”的古刹之中，住持即将圆寂的消息惹得江湖之中一片风雨，原因在于寺庙之中藏有的珍贵手写经书《大乘起信论》，谁若能接替住持的衣钵，便能获得这无价的珍宝。住持有三个徒弟，传衣钵是大事，于是，住持请来了王将军（田丰 饰）、施主文安（孙越 饰）和悟外法师 （ 吴家骧 饰），除了悟外法师之外的两人均觊觎经书的价值连城，文安甚至带来了女飞贼白狐（徐枫 饰）以备不时之需。住持有三个徒弟，大师兄（石隽 饰）和二师弟早已经被王将军和文安收买，只有三师弟慧思（秦沛 饰）是一心一意的为寺庙着想。就在这个节骨眼上，一位名叫邱明（佟林 饰）的男子来到寺里剃度为僧，邱明身为流犯却实为含冤受屈，而令他受冤且害他家破人亡的罪魁祸首不在别处，正在这寺庙之中。©豆瓣', '田丰', '胡金铨', 8.4, 15018, 'tt0192213', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2160006456.jpg', 0.3, 1.2, 13.3, 48.8, 36.5, '0.057344,0.043077,-0.485382,0.498460,-0.102556,-0.158693,0.526547,0.138985,-0.527630,-0.535429,0.272028,0.628693,-0.002267,0.087737,0.013653,0.200201,0.211642,-0.276359,-0.220878,-0.363703,-0.160202,-0.390931,-0.212357,-0.022917,-0.360708,-0.339877,0.285432,0.160860,-0.096809,0.030219,0.382774,0.141912,-0.206514,0.020696,-0.328844,0.197249,0.093312,0.140423,-0.089132,0.113742,-0.213668,-0.244541,-0.176674,-0.039521,-0.256181,0.104792,0.305515,-0.325993,-0.251730,-0.149461,0.004168,0.081005,0.037638,0.252937,0.068907,-0.163673,0.562993,0.516959,-0.209086,0.136908,0.162597,-0.096434,-0.497614,0.186891,0.570373,0.140624,-0.412417,0.400311,-0.154453,-0.284591,-0.126698,-0.316644,0.343535,0.204815,0.108277,0.301866,-0.101052,-0.359135,-0.552199,0.297768,0.137739,-0.201561,0.379839,0.033212,0.183303,-0.336879,0.251482,-0.224174,-0.249991,0.253624,0.381728,-0.115412,0.113533,0.095035,-0.172339,0.014317,-0.182832,-0.020913,0.001252,-0.014614,-0.132780,-0.318947,0.126565,-0.267708,-0.321556,-0.066668,0.542638,-0.221669,0.866384,-0.543015,0.284652,0.147336,-0.054540,-0.384940,0.872172,0.050090,0.282642,-0.065995,-0.342191,-0.288517,-0.179502,0.693944,0.170827,0.215855,-0.055370,-0.422742,-0.305086,0.009369', '26965165', '1302661', '26283288', '25882279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301156', '怪谈协会', '喜剧', '女记者受托进入香港近期兴起的一个神秘协会“怪谈协会”采访，正逢协会选举新会长，所有会员一边吃起了美味的“羊肉”，一边开始听竞选会员们讲自己的参赛故事。第一个故事：小职员（张达明 饰）一直受上司欺压，内心压抑。一日终于忍不住，遂拿刀要挟上司。二人在追逐途中上司不幸心脏病爆发而亡。小职员虽无罪，内心却耿耿于怀。新上司（黎姿 饰）不久到来，是一位美丽却有双重人格的怪人。她时而挑逗骚扰小职员，时而又恢复一本正经。然而可怕的是，小职员开始发现女上司的种种行为和死去的上司一模一样……第二个故事：大学校园医学系的新生阿良与阿辉一进校就被学长们欺负，内心愤愤不平。恰逢校园内有一尊传说很邪的雕像“四不像”，谁摸了之后就会有灭顶之灾，二人赌气与学长们打赌，摸了“四不像”。之后生活看似风平浪静，阿辉不断倒霉，而阿良却安然无恙。一日夜间，阿良一人在寝室读书，却有一神秘的美丽女子来借洗头液。阿良被其吸引，却不知危险已步步逼近……第三个故事：模特阿美（袁咏仪 饰）与丈夫过着幸福的生活，但丈夫一直出差，阿美一人在家害怕，遂张贴了招租的广告。众多申请者其皆不满意，唯一日有一神秘女子（舒淇 饰）前来招租，阿美遂将她留下。不料神秘女子有种奇怪的同化力，阿美开始渐渐抵抗不住……故事会结束后，女记者前去厨房采访，终于发现了惊人的秘密！', '袁咏仪', '马伟豪', 7.2, 10361, 'tt0168224', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1519798098.jpg', 1, 5, 40.9, 41.2, 11.9, '0.153256,0.012231,-0.410794,0.309688,0.062190,-0.084514,0.738110,0.122338,-0.516644,-0.213264,0.183126,0.615828,-0.464614,0.559245,0.194187,0.042167,-0.058481,-0.376086,-0.185604,-0.060551,-0.123366,-0.022345,-0.086221,-0.094579,-0.177399,-0.110783,0.355185,-0.127966,-0.222229,0.462897,0.384643,0.174872,-0.248882,0.426007,-0.256693,-0.066203,0.244251,0.119530,0.054326,-0.072632,0.133938,-0.255463,-0.388012,0.094177,0.003429,0.279468,0.543110,-0.128949,-0.298861,-0.202281,0.511507,-0.136711,-0.019521,0.142976,0.392410,0.279174,0.314415,-0.079250,-0.072118,-0.024593,0.031023,-0.087636,-0.404339,0.152700,0.014045,0.198118,-0.273541,0.195513,-0.031378,0.077874,0.256127,-0.265831,-0.000848,0.184150,0.159342,0.207967,0.015330,0.118064,-0.292112,0.255219,0.627530,0.047080,-0.221418,0.265298,-0.038627,-0.243801,0.197091,-0.024466,-0.503054,0.013607,0.240697,0.092110,-0.031021,0.040866,-0.442873,-0.048355,-0.164430,-0.048510,0.018933,-0.204718,-0.312518,-0.391067,-0.079886,0.075704,-0.303253,0.151196,0.164977,0.066824,0.796852,-0.791261,0.355521,0.529102,0.105698,-0.501003,0.377054,0.212352,-0.049072,-0.177914,-0.118778,0.106924,0.079814,0.299587,0.188342,0.425929,-0.275455,-0.269384,-0.206597,0.183950', '25922902', '1292219', '6963575', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301161', '惊爆点', '动作', '约翰尼（基努·李维斯 Keanu Reeves 饰）是一名FBI探员，正在与老搭档帕帕斯（加里·布塞 Gary Busey 饰）着手调查一系列银行抢劫案。然而这个狡猾的犯罪团伙行事严谨精明，每次犯案均用多位前任总统的面具伪装自己。约翰尼手上唯一的线索只是帕帕斯的推理：罪犯很可能是冲浪爱好者。为了尽快侦破此案，约翰尼决定到海滩学习冲浪以寻找线索，在此过程中，约翰尼结识了冲浪高手普提（帕特里克·斯威兹 Patrick Swayze 饰）和泰勒（罗莉·佩蒂 Lori Petty 饰），他被普提的思想魅力和领袖气息所吸引，爱上了冲浪这项刺激的运动，并与一帮冲浪爱好者结下深厚友谊。然而，在种种相处的细节之中，约翰尼渐渐开始怀疑这帮优秀的朋友就是他要找的神秘团伙……©豆瓣', '帕特里克·斯威兹', '凯瑟琳·毕格罗', 7.4, 8006, 'tt0102685', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2290240310.jpg', 0.5, 4.2, 35.1, 43.1, 17, '0.348733,-0.330230,-0.514070,0.569803,-0.171600,-0.065557,0.497116,-0.025397,-0.608129,-0.619957,0.047448,0.695170,-0.124209,-0.038622,0.393071,0.009009,-0.503858,-0.915520,-0.050485,-0.113807,-0.098119,-0.566183,-0.389994,-0.264696,-0.055395,-0.414522,0.490770,0.127610,-0.331756,0.477215,0.467420,0.410021,-0.334939,0.368938,-0.212680,-0.386464,0.430263,-0.200635,-0.236775,0.150865,0.015149,-0.032850,0.043424,0.141458,0.106052,0.486226,0.525582,-0.075524,-0.213811,0.161259,0.119850,-0.349952,0.167763,0.059687,0.423013,0.021360,0.218309,0.400808,-0.001382,-0.061968,0.138486,-0.269243,-0.926504,-0.117518,0.266885,0.226104,-0.451995,-0.107308,-0.201216,-0.134249,-0.135081,-0.138646,0.021591,0.184156,0.350126,0.041763,0.040032,-0.214532,-0.304436,0.315080,0.282716,0.081249,-0.116566,0.191645,-0.268470,-0.432955,0.015707,-0.122569,-0.137157,-0.147696,0.276131,-0.099560,0.004833,0.413637,-0.657374,0.001460,-0.259772,-0.054912,0.019256,-0.276540,0.050005,-0.867843,-0.339899,-0.361567,-0.223163,-0.043912,-0.045930,-0.448338,0.591691,-0.801966,-0.072313,0.657550,-0.117871,-0.420585,0.465884,0.130513,-0.086493,-0.379554,-0.222951,0.243871,0.295742,0.011187,-0.065224,0.500964,0.178395,-0.422683,-0.319481,0.312727', '25723905', '1307442', '4301278', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301164', '基地疑云', '剧情', '南森·韦斯特（塞缪尔·杰克逊 Samuel L. Jackson饰），一位素以严厉著称美军训练基地魔鬼教官，他的冷酷无情令其和学员之间的关系一向十分紧张。汤姆·哈代（约翰·特拉沃塔 John Travolta饰），一位同样对韦斯特心存怨恨的昔日门下弟子，现任美国药品管理局官员。两人因一起神秘失踪案件而联系在了一起。这宗在巴拿马丛林发生的离奇失踪事件，致使六名受训学员连同韦斯特在飓风后消失得无影无踪。哈代受命与军方调查官员朱丽娅少尉（康妮·尼尔森 Connie Nielsen饰）携手调查此事。然而随着调查的展开，仅存的两名幸存者学员丹巴（布莱恩·范·霍尔特 Brian Van Holt饰）与肯达尔（吉奥瓦尼·瑞比西 Giovanni Ribisi饰）的供词却大相径庭。越来越多的谎言与欺骗渐渐浮出水面，到底谁在说谎，真相背后又是怎么样的可怕事实？©豆瓣', '约翰·特拉沃尔塔', '约翰·麦克蒂尔南', 6.9, 5622, 'tt0264395', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204969185.jpg', 0.8, 6.7, 47.6, 36, 8.9, '0.137898,-0.297653,-0.541721,0.590744,0.090933,-0.203969,0.655153,0.138751,-0.779033,-0.356427,0.135328,0.607446,-0.206977,-0.027248,0.198763,-0.299751,-0.459088,-0.692783,-0.119813,-0.356943,-0.156623,-0.736361,-0.039187,-0.296037,0.017674,-0.443413,0.611529,0.011530,-0.055848,0.406470,0.418595,0.604731,-0.414184,0.243484,0.201297,-0.167949,0.605019,-0.081729,-0.299905,-0.105911,-0.044406,-0.063004,-0.190922,-0.031456,0.191769,0.306942,0.447658,-0.135048,-0.101563,-0.081581,0.074198,-0.173336,0.242535,0.103060,0.667447,-0.050990,-0.068421,0.516898,-0.033463,-0.112119,-0.145675,0.062298,-0.393446,0.147096,0.194033,0.403088,-0.517741,0.120211,-0.216100,0.122728,0.003374,-0.186396,0.017412,0.370989,0.015605,0.083985,0.108902,-0.162302,-0.395257,0.025346,0.431634,0.002198,-0.195221,-0.064905,-0.160387,-0.332476,-0.291913,-0.082009,-0.256878,-0.026911,0.230109,-0.224441,0.209235,0.673602,-0.356272,-0.305766,-0.346929,-0.054710,-0.268875,-0.171422,0.017360,-0.739438,-0.102036,-0.369699,-0.265918,-0.031458,0.032118,0.060184,0.453354,-0.732447,0.175662,0.227556,0.117530,-0.352010,0.192271,0.113675,0.217441,-0.320459,-0.187081,0.325619,0.563780,-0.070862,0.073751,0.323702,0.031265,-0.270376,-0.065870,0.041340', '1296252', '2