INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301166', '垂直极限', '动作', '在一次登山运动中，彼得的父亲为了让他成功获救，毅然选择割断绳索，坠崖身亡。由于内心的痛苦阴影，彼得（克里斯·奥唐纳饰）放弃了登山事业，并由此与同是登山运动员的妹妹不欢而散。妹妹在有一次挑战喜马拉雅山脉西麓高耸入云的K2峰时遇险，全队困在高峰上的岩洞里。由于食物与药物的紧缺，他们的生命岌岌可危。为了营救妹妹，彼得不惜生命危险，再次登上喜马拉雅山，展开与时间的竞赛和对自然极限的挑战。©豆瓣', '克里斯·奥唐纳', '马丁·坎贝尔', 7.7, 29759, 'tt0190865', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p601924899.jpg', 0.5, 2.7, 28.6, 49.8, 18.5, '-0.017871,-0.004768,-0.740753,0.643714,0.251599,-0.534412,0.716599,-0.035383,-0.545934,-0.043884,0.416027,0.795589,-0.003999,0.156032,0.155721,-0.339662,-0.257892,-0.675740,-0.056689,-0.065731,-0.622492,-0.578524,-0.155610,-0.028679,-0.039640,-0.475193,0.813770,0.192408,-0.448346,0.733605,0.300095,0.308920,-0.006539,0.501832,0.043447,-0.272476,-0.131813,-0.052958,-0.672876,0.340394,0.112458,-0.193534,0.056131,0.284124,0.180236,0.463289,0.732957,-0.554169,-0.180725,-0.156012,0.148970,-0.377195,0.273495,0.152868,0.191339,-0.100922,0.204815,0.389266,-0.205207,0.102490,0.033228,-0.353178,-0.719587,-0.046751,0.165786,-0.032317,-0.526556,0.459805,-0.053594,0.042755,0.216014,-0.512954,-0.096270,0.490780,0.307744,0.200608,-0.761637,-0.086407,-0.373813,-0.140019,0.878620,-0.066783,0.143878,0.159469,-0.049143,-0.337005,0.065775,-0.359083,-0.280473,0.067927,0.427075,0.285180,-0.072877,0.449476,-0.509763,0.157660,-0.540357,-0.193503,0.059133,-0.257255,0.065726,-0.449120,0.188657,0.060743,-0.056330,0.053113,0.002670,-0.412701,0.352134,-0.773878,0.424122,0.422183,0.376187,-0.273910,0.588008,0.070492,0.153737,-0.368198,-0.062568,0.515502,-0.092414,0.398447,-0.083514,0.033432,0.028536,0.011496,-0.545691,0.439463', '30345227', '3217169', '25721544', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301167', '102真狗', '喜剧', '在上一集101真狗中，古拉（格伦•克洛斯 饰）被关进了牢狱中。三年牢狱中古拉提前出狱了，本来以为她会改过自身不在打那些可爱斑点狗的主意，就连她自己也说不会再做杀害斑点狗的残忍事。但她的虚荣心还是敌不过自己的意志，看到那些美丽的斑点狗，她再次动心想要取得那些斑点狗的皮毛。法国设计师勾画出的美丽服装设计图，再次让她决定故伎重演的决心。102只斑点狗的生命危在旦夕，但这些懂人性小狗们为了自己家族的生命，也要抵抗到底。在斗争的过程中，一只刚出生的小狗，成为了大英雄。©豆瓣', '格伦·克洛斯', '凯文·利玛', 7.1, 14069, 'tt0211181', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1686549296.jpg', 0.6, 3.9, 47.7, 35.5, 12.4, '0.112036,0.248148,-0.646821,0.586241,-0.562434,-0.268075,0.804515,-0.176268,-0.317521,-0.014819,0.274564,0.907234,0.046378,0.307897,-0.310675,0.193217,-0.293991,-0.716976,-0.054045,-0.153310,-0.167110,-0.251678,-0.343982,-0.186801,0.053291,-0.187860,0.606086,0.128952,-0.119699,0.026635,0.487556,0.038477,0.156651,0.261986,-0.171722,0.103157,-0.027674,0.045966,0.141946,0.017554,-0.014285,-0.155187,-0.136139,0.394612,-0.087138,0.301140,0.569374,-0.536596,-0.147768,-0.404979,0.433052,-0.285595,0.142539,0.480470,0.076187,-0.106668,0.370158,-0.075486,-0.132879,0.137925,0.141011,0.009902,-1.110944,-0.308802,-0.029078,0.127878,-0.780113,0.190297,-0.028338,-0.013301,0.217814,-0.437781,0.010281,0.136244,0.286043,0.316544,-0.298399,-0.135130,-0.712141,0.254959,0.543583,-0.215654,-0.308345,0.494797,-0.276357,-0.486299,-0.044014,-0.371346,-0.298586,-0.159659,0.376411,0.009454,-0.509674,0.383957,-0.600346,0.057165,-0.343566,-0.245844,-0.333647,-0.379628,0.088302,0.066883,-0.249972,-0.491348,-0.366556,0.136663,0.281324,-0.289043,0.715761,-0.783406,0.244530,0.711082,0.341782,-0.434061,0.452472,0.292125,0.042113,0.222528,0.007675,0.223204,-0.038531,0.200692,0.301648,0.422414,0.344401,-0.296681,-0.447832,0.650042', '1793491', '30163500', '1308585', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301168', '卧虎藏龙', '剧情', '一代大侠李慕白（周润发饰）有退出江湖之意，托付红颜知己俞秀莲（杨紫琼饰）将青冥剑转交给贝勒爷（郎雄饰）收藏，不料当夜遭玉娇龙（章子怡）窃取。俞秀莲暗中查访也大约知道是玉府小姐玉蛟龙所为，她想办法迫使玉蛟龙归还宝剑，免伤和气。但李慕白发现了害死师傅的碧眼狐狸（郑佩佩饰）的踪迹，她隐匿于玉府并收玉蛟龙为弟子。而玉蛟龙欲以青冥剑来斩断阻碍罗小虎（张震饰）的枷锁，他们私定终身。关系变得错综复杂，俞秀莲和李慕白爱惜玉蛟龙人才难得，苦心引导，但玉蛟龙却使性任气不听劝阻……©豆瓣', '周润发', '李安', 8.4, 426427, 'tt0190332', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1507810991.jpg', 0.3, 1.2, 15.7, 46, 36.9, '-0.270816,0.090921,-0.345927,0.603484,0.268814,-0.141476,0.537908,-0.009037,-0.516489,-0.082157,0.045096,0.311828,-0.277713,-0.235088,-0.220676,0.215010,0.255473,-0.613242,0.139527,0.014982,0.252143,-0.240411,-0.219336,0.163853,-0.187904,-0.425309,0.557167,0.297833,-0.020570,0.375219,0.346719,0.226058,-0.411334,0.309402,0.023157,0.040243,-0.563909,0.102986,-0.281986,0.042493,0.038839,-0.271598,-0.037885,0.331873,-0.038944,0.447220,0.378980,-0.340974,0.054614,-0.194678,0.101315,-0.101962,0.089583,-0.127104,0.131398,-0.127792,0.102590,0.327425,-0.334389,0.032727,0.215081,-0.118558,-0.227817,0.176458,0.400530,0.114367,-0.578994,0.222521,-0.166885,0.216152,-0.321672,-0.078363,0.103702,-0.169487,0.033504,-0.285856,-0.077469,0.019355,-0.492985,0.300113,0.207542,-0.299285,0.299575,0.222642,0.091802,-0.320853,-0.030600,0.121512,0.280784,-0.449146,0.373229,0.409768,-0.190204,0.018396,-0.291197,-0.348771,-0.379853,0.637464,-0.210262,-0.597359,0.137934,0.054094,-0.068810,-0.274618,0.084624,-0.148518,0.266053,-0.283317,0.507222,-0.552845,-0.106561,0.055165,0.178534,-0.660677,0.596694,-0.215727,-0.009472,-0.325762,-0.314096,0.082530,0.246219,-0.021135,0.444944,-0.046660,0.311121,-0.215373,-0.333207,-0.078326', '1304091', '26730542', '6101834', '3319776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301169', '跳出我天地', '剧情', '比利（杰米•贝尔 Jamie Bell 饰）的家人是英国的一个底层矿工。他们参加罢工，挣扎在贫困的生活中，并认为比利应该学些男人的拳术。比利本来每周都去一回拳击班，偶然的机会却让他走上了不一样的路途。因为一个小意外，比利发现了潜意识中对芭蕾的热爱，而挑剔世故的芭蕾老师威尔金森（朱丽•沃特斯 Julie Walters 饰）无意中发现了比利极具芭蕾天赋。二人一拍即合，威尔金森甚至放弃她的一班女学生，把全部心思放在培养小比利上。可是比利的家庭全然不理解儿子为何爱上女生的玩意。比利在家庭的反对下，痛苦的抉择。然而大好机会就在当前。万一考上伦敦的皇家芭蕾学校，比利的芭蕾梦想将得到一个广阔舞台。比利站在一个十字路口，选择着他的人生。©豆瓣', '杰米·贝尔', '史蒂芬·戴德利', 8.8, 98582, 'tt0249462', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p531278288.jpg', 0.1, 0.4, 8.3, 40.5, 50.6, '0.553917,-0.111289,-0.613640,0.593108,-0.390791,-0.436988,0.634354,0.015771,-0.289202,-0.237308,0.374194,0.807013,0.104794,0.248403,0.163847,-0.030866,-0.291146,-0.598183,0.053292,-0.046819,-0.234247,-0.637013,-0.196364,-0.215654,-0.211201,-0.244796,0.612916,-0.131611,-0.187283,0.517339,0.221249,0.024612,0.225907,0.284638,-0.040568,-0.066234,0.339563,0.078655,-0.061225,0.182950,-0.032559,-0.154537,-0.272707,0.137557,0.086439,0.171051,0.632977,-0.222834,0.063156,-0.049816,0.309255,-0.192670,-0.030449,0.188561,0.186155,-0.140911,0.093122,0.115051,0.057991,0.074249,0.239335,-0.073811,-0.505554,0.102691,0.132237,0.260116,-0.741316,0.666294,-0.042556,-0.323137,-0.003560,-0.395958,-0.080298,0.053512,0.382422,0.326100,-0.292947,0.129647,-0.381461,0.088821,0.678692,-0.065043,-0.351130,0.276315,-0.346119,-0.472666,0.036168,-0.038333,-0.661883,-0.186350,0.250247,-0.073668,-0.307070,0.156852,-0.403292,0.213302,-0.221056,-0.125974,-0.128281,-0.494278,-0.065244,-0.541699,0.127105,-0.176356,-0.414758,-0.103102,0.146021,-0.370956,0.815796,-0.925347,0.150174,0.646455,0.216276,-0.180029,0.873909,0.030951,0.190572,-0.091625,-0.213585,0.280408,0.117595,0.011379,-0.195880,0.601213,-0.043348,-0.156471,-0.264517,0.806180', '1292720', '3230462', '1870681', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301171', '偷拐抢骗', '喜剧', '土耳其（杰森•斯坦森饰）是一位黑市拳击的经理人，不过他遇到了麻烦，本该参加比赛的选手被吉普赛人米奇（布拉德•皮特饰）一拳击倒。土耳其不得不选择在黑帮老大布里克（阿兰•福特饰）与吉塞人之间周旋，来获得生机。与此同时，四指弗兰克（本尼西奥•德尔•托罗饰）携带一颗86克拉的钻石来到伦敦，这件赃物引起了各路匪徒的兴趣，其中包括军火商老布（拉德•舍博德兹加饰）、杀手“子弹牙齿”托尼（维尼•琼斯饰）与黑人小混混维尼（罗比•吉饰）。这些心怀不轨的罪犯各自盘算着自己的完美计划，不想造化弄人，惊人的巧合引出一连串幽默的冷笑话。所有的一切都在伦敦的夜晚交织，究竟谁能够从中解脱？就在盖•瑞奇导演的《偷拐抢骗》中揭晓。©豆瓣', '本尼西奥·德尔·托罗', '盖·里奇', 8.5, 182860, 'tt0208092', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p616753227.jpg', 0.2, 0.9, 11.9, 46.6, 40.5, '0.478009,-0.120657,-0.435955,0.159302,-0.093831,-0.240237,0.581337,0.077030,-0.340562,0.057378,0.427910,0.412938,-0.231522,-0.298533,0.306323,0.082209,-0.351422,-0.602626,0.168824,-0.170953,0.109393,-0.666919,-0.458241,-0.151358,0.022506,-0.201019,0.248827,-0.033372,-0.053333,0.511593,0.455277,0.554263,0.029552,0.013638,0.117963,0.027401,0.385803,-0.211057,-0.363072,0.143350,-0.042784,0.005792,-0.001355,0.042352,0.045928,0.267608,0.337547,-0.021127,0.547022,0.037920,0.197969,-0.267609,0.222527,0.185142,0.113851,-0.118913,0.157911,0.101460,0.042482,-0.046625,0.393175,0.024580,-0.621803,0.142759,-0.030435,0.335047,-0.357001,0.374932,-0.349084,0.031817,-0.002122,-0.185939,0.024123,0.116166,0.192937,-0.076513,0.138863,-0.113563,-0.425912,0.035602,0.504232,-0.217315,-0.205538,-0.119095,-0.125024,-0.316620,-0.113224,0.004614,-0.163235,0.035082,0.740106,-0.100231,0.076606,0.380308,-0.565099,-0.097352,-0.408827,-0.151781,0.035750,-0.197073,-0.078825,-0.640910,-0.172074,-0.074752,-0.131345,-0.004993,0.280940,0.196195,0.385078,-0.669505,0.019243,0.401590,0.102422,0.105710,0.189639,0.021740,0.173150,-0.176844,-0.201248,0.014048,0.389079,-0.036993,-0.022746,0.410430,0.348900,-0.284300,-0.229742,0.111739', '1307442', '1301686', '6517421', '1418190');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301172', '心灵访客', '剧情', '十六岁的黑人男孩詹姆·华莱士（罗伯·布朗 Rob Brown 饰）在篮球方面极富天赋，非常有潜力成为篮球界的明日之星。他常常与小伙伴们一起打篮球，他们注意到住在对面公寓顶层的沉默男人总是看着他们。这位神秘的隐士原来就是知名作家威廉·佛瑞斯特（肖恩·康纳利 Sean Connery 饰）。一次偶然的恶作剧让两人相互结识，威廉发现他在写作方面也很有天份。很快，詹姆凭借自己出色的篮球技术和优秀成绩，获得了一所著名私立学校的邀请。然而对于一所白人学校而言，詹姆却面临着艰难选择和种种质疑。威廉同意帮助詹姆提高他的写作水平。渐渐地，两人在交流中建立了深厚的友谊，循循善诱的威廉激发出詹姆潜藏的写作才能，而威廉自己也开始改变，终于走出避世多年的隐居公寓。©豆瓣', '肖恩·康纳利', '格斯·范·桑特', 8, 6485, 'tt0181536', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2386622308.jpg', 0.5, 1.8, 22.6, 48.8, 26.3, '0.491008,-0.041808,-0.757005,0.717868,-0.222119,-0.375157,0.491592,0.102284,-0.472708,-0.387739,0.205378,0.922156,-0.169192,0.302986,0.346087,-0.211322,-0.323909,-0.786297,0.048287,-0.136857,-0.254793,-0.652515,-0.459931,-0.181858,-0.245247,-0.422951,0.623327,-0.047694,-0.438618,0.555536,0.060289,0.389330,0.083957,0.320123,-0.195793,-0.208400,0.452741,0.032085,-0.220947,0.264966,0.116755,-0.051800,-0.287828,-0.145421,0.140410,0.171368,0.440093,-0.092623,-0.257710,0.176312,0.307379,-0.133800,-0.263700,0.055099,0.502640,0.057230,0.131583,0.201922,-0.025456,0.069563,-0.136736,-0.166172,-0.614854,-0.024161,0.195588,0.049804,-0.567041,0.571537,0.203613,-0.439187,0.190791,-0.369592,-0.227607,0.259575,0.201570,0.287387,-0.166867,0.120080,-0.316183,-0.135637,0.459756,0.114118,-0.511752,0.127146,-0.374810,-0.477808,0.042151,-0.293009,-0.452338,-0.162167,0.397901,0.102783,0.017571,0.197606,-0.503753,0.144987,-0.175154,-0.107523,0.060255,-0.449369,0.101533,-0.982758,-0.200230,-0.465293,-0.256446,-0.115992,-0.104699,-0.582273,1.127428,-1.110307,0.135112,0.420049,0.313228,-0.255269,0.761905,-0.082687,0.128737,-0.302777,-0.349968,0.332027,-0.099435,0.004235,-0.243723,0.484982,0.059637,-0.128156,-0.272118,0.667750', '1870681', '25922902', '3811356', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301185', '我在黑社会的日子', '剧情', '黑帮洪兴社与敌对帮派谈判破裂，双方大打出手。洪兴老大李坤混乱中被刺，重伤身亡，社团顿时一团混乱。留学并定居美国的李万豪（周润发 饰）携妻儿回港为父奔丧，在众老叔苦苦哀求下无奈出任龙头一职。虽生在黑社会家庭，但万豪自幼不参与社团事务，更对江湖上的规矩与利害一无所知，因此一系列改革举措招来了其他帮派的攻击与不满。决意返美的万豪推举老成持重的谢胜（陈惠敏 饰）担当老大，此举却引来少壮派头目杨港（张耀扬 饰）的不满。内忧外患，处在过渡期的洪兴社风雨飘摇……©豆瓣', '周润发', '黄泰来', 6.5, 7696, 'tt0098667', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2348663424.jpg', 1.5, 10.4, 56.3, 23.6, 8.1, '0.188392,0.030515,-0.519910,0.115019,0.367136,0.096683,0.395994,0.545300,-0.691458,-0.221163,0.317415,0.462767,-0.048304,0.088140,0.036660,-0.505760,-0.111072,-0.740757,-0.280802,0.192069,0.100563,-0.558530,-0.095503,-0.162554,-0.411493,0.140038,0.680671,0.191188,-0.496024,0.661869,0.397527,0.475353,-0.252847,0.363508,-0.014307,-0.140072,0.162865,0.054157,-0.408237,-0.313416,-0.283910,-0.392383,-0.259755,0.017974,0.226956,0.576622,0.344893,-0.048166,-0.186606,-0.531308,0.238385,-0.367981,-0.291818,0.234450,0.673066,0.022843,0.159641,0.227990,0.005077,0.042099,-0.147113,0.033344,-0.566114,0.056718,0.326758,0.254435,-0.674614,0.544851,-0.067871,-0.183854,-0.240839,-0.136389,0.193872,0.654972,0.006760,-0.007191,-0.079490,0.460948,-0.306499,0.185642,0.787662,0.057498,-0.342876,-0.475241,-0.013425,-0.409254,-0.130651,-0.281002,-0.092898,-0.309557,0.342684,-0.200844,0.239055,0.456849,-0.288068,-0.019743,-0.052613,-0.128234,-0.201966,-0.128027,0.166590,-0.640738,-0.314101,-0.164705,-0.244964,-0.085141,0.411624,0.318335,0.523979,-0.713161,-0.064016,-0.058745,0.265432,-0.806628,0.373079,0.382961,0.403389,-0.326395,-0.383845,-0.085363,0.321334,0.044928,0.080866,0.102493,-0.282375,-0.399143,0.119146,-0.310294', '1293265', '3230460', '1307106', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301198', '少林寺', '动作', '隋朝末年，隋将王世充的侄子王仁则（于承惠 饰）在督建河防工事时，杀死了起来反抗暴虐的神腿张，但令其儿子小虎子跳河逃离虎口。小虎子被少林僧人救起收入寺中后，为报父仇毅然削发为僧，法名“觉远”（李连杰 饰）。王仁则的侍卫长遇见牧羊女白无瑕（丁岚 饰）后垂涎其美色，强行将其 抢回府并欲酒 后施暴，恰巧被只身前来报仇的觉远发现。在救白无瑕逃生的过程中，觉远因武功欠佳被王仁则刺伤，促使其回到少林寺后更加刻苦练功。后因觉远救援被王仁则追赶的李世民，少林寺遭遇劫难，觉远身上的责任更重一层。©豆瓣', '李连杰', '张鑫炎', 8.3, 99343, 'tt0079891', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457784081.jpg', 0.2, 0.8, 15.9, 49.9, 33.2, '0.032290,0.314206,-0.653119,0.374248,0.059402,-0.511089,0.567601,0.331654,-0.526546,-0.319409,0.288246,0.632589,0.031894,-0.005050,-0.117959,-0.178913,0.417229,-0.613644,-0.331201,-0.133277,-0.302368,-0.096617,0.106362,0.257214,-0.352951,-0.480916,0.403536,0.088612,-0.335463,0.548088,0.364459,0.040110,0.056836,0.751005,0.081090,0.256583,-0.228963,-0.301235,-0.094149,0.313358,0.168519,-0.654434,-0.182515,0.064101,-0.661466,0.204855,0.821890,-0.080276,-0.140975,-0.590112,0.303481,-0.186868,0.036676,0.259201,0.251197,0.238864,-0.069441,0.217509,-0.355814,0.254795,0.277897,-0.084737,-0.406694,0.116926,0.480844,-0.024734,-0.673644,0.135481,-0.026452,0.251347,-0.099422,-0.536134,-0.106519,0.285608,0.050334,0.004361,-0.347941,-0.075865,-0.342608,0.305572,0.238801,-0.612067,0.500766,-0.006411,0.259265,-0.061115,0.723660,-0.207083,-0.059464,0.040092,0.680292,0.098090,-0.237370,-0.076980,-0.321831,-0.404741,-0.743074,0.184742,-0.402266,0.049934,-0.131698,-0.398409,-0.033618,-0.023759,-0.153570,-0.321160,0.154028,-0.159256,0.431838,-0.463114,0.158500,0.356504,0.120191,-0.246494,0.273141,-0.264149,0.187360,0.191131,-0.178131,0.439402,0.143829,0.678860,0.100957,0.344915,-0.176927,-0.000794,-0.397564,0.254204', '1303462', '3082452', '1304129', '4892342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301221', '新龙凤配', '剧情', 'Sabrina（Julia Ormond 朱莉娅·奥蒙德饰）是赖瑞毕家司机的女儿，从小她就暗恋二少爷David（Greg Kinnear 格雷格·金内尔饰）。外界对二少爷的评价可远远不及他的大哥Linus（Harrison Ford 哈里森·福特饰），人们赞许大少爷睿智冷静，富有商业头脑。二少爷不过是个游手好闲，只知道泡妞的花花公子罢了。可Sabrina才不理那些，她一心一意爱着David，但父亲却为此忧心忡忡，他托人将Sabrina送去巴黎深造，期待她能走出狭隘的小圈子，看到世界的辽阔。果然，从巴黎回来后，Sabrina一洗土气，举止大方，谈吐自如，女人味十足。David迅速拜倒在她的石榴裙下，甚至欲至未婚妻于不顾，这引起了家族的恐慌。Linus为此刻意接近Sabrina，希望能把她打发走，可情节的走向却开始逐渐脱离Linus的掌握……©豆瓣', '哈里森·福特', '西德尼·波拉克', 7.4, 7594, 'tt0114319', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2170591332.jpg', 0.7, 4.1, 37.1, 41, 17.1, '0.161080,0.391266,-0.770482,0.566248,-0.380206,-0.383578,0.606958,0.199150,-0.664344,-0.138187,-0.031990,0.539838,0.016362,0.163383,0.123402,0.100903,-0.244735,-0.517938,-0.018523,-0.114885,0.088160,-0.415438,-0.248103,-0.178913,-0.234552,-0.316428,0.331855,0.142233,-0.169772,0.315349,0.283396,0.163856,0.131535,0.536402,-0.247337,-0.004509,-0.034307,0.032566,-0.116197,0.127823,0.184512,-0.153980,-0.198582,0.161055,0.111716,0.184733,0.559249,-0.180187,-0.198470,-0.067700,0.421092,-0.045291,0.067502,0.408250,-0.052057,-0.066169,0.030873,0.076095,-0.116849,-0.036826,0.012617,-0.055334,-0.442207,0.201528,0.008694,0.052559,-0.805894,0.263189,-0.296289,-0.272572,-0.051760,-0.481780,0.071638,-0.007551,0.128461,0.273250,-0.113479,0.216859,-0.498591,0.000170,0.388029,0.247381,-0.244576,0.307425,-0.132777,-0.230273,0.139490,-0.303469,-0.678261,-0.185588,0.274759,0.042389,0.026152,0.300706,-0.165788,-0.085570,-0.176168,-0.102423,0.005328,-0.576280,-0.234418,-0.079291,-0.188077,-0.491793,-0.171104,-0.115594,0.075774,-0.299704,0.735052,-0.796610,0.199460,0.352377,0.166514,-0.786368,0.663507,-0.067655,-0.051053,-0.069857,-0.222376,0.301087,0.221397,0.078502,0.046329,0.549203,-0.179679,-0.233172,-0.171841,0.481733', '26253737', '1877596', '1301022', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301230', '夺魂索', '悬疑', '博兰顿（约翰•达尔John Dall 饰）和菲利普（法利•格兰杰 Farley Granger 饰）都是哈佛的高才生，一天，都是同性恋的两人合谋杀害了同学戴维，并藏尸于一个大箱子中。或许是出于炫耀，他们做出了一个惊人的举动。那就是用装着戴维尸体的箱子当餐桌，邀请了戴维的父母、未婚妻、同学和茹伯特教授（詹姆斯•斯图尔特 James Stewart 饰）来赴宴。他们谎称戴维外出了，和客人们在戴维的“棺材”上进行着宴会。胆小的菲利普从宴会开始就开始坐立不安，但是博兰顿却不慌不忙，在客人中滔滔不绝。然而，聪明的茹伯特教授从博兰顿的谈话中渐渐察觉出事有蹊跷……©豆瓣', '约翰·道尔', '阿尔弗雷德·希区柯克', 8.1, 52627, 'tt0040746', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2154845412.jpg', 0.2, 1.3, 18.9, 52.7, 26.9, '0.691108,-0.156815,-0.634302,0.365617,-0.185455,-0.381886,0.651179,0.101943,-0.484127,-0.392473,0.336071,0.759882,-0.440731,0.368491,0.244601,0.096933,-0.446464,-0.718391,-0.059543,-0.232085,-0.292457,-0.649975,-0.084052,-0.411251,0.021991,-0.276103,-0.017898,-0.192706,0.035076,0.679123,0.263514,0.375620,0.020859,0.486462,-0.101836,0.151002,0.361834,-0.054404,-0.023764,-0.047549,0.040489,-0.295502,-0.386336,0.356572,0.391396,0.605968,0.568267,-0.203236,-0.007483,0.045765,0.196089,-0.287190,0.172875,0.257341,0.541038,-0.001076,0.193152,0.286445,-0.080904,0.104769,0.134656,-0.011857,-0.435219,0.165695,-0.044390,0.354458,-0.638509,0.521899,-0.205606,-0.177150,0.125172,-0.150742,0.291073,0.145972,-0.114663,0.257861,0.131207,-0.234462,-0.721585,0.014988,0.408311,0.177827,-0.079915,0.101793,-0.178042,-0.282179,0.331909,-0.026321,-0.389101,-0.154077,0.321011,-0.140830,0.008594,0.112685,-0.584481,-0.069188,-0.329613,-0.009003,0.015123,-0.236156,-0.147543,-0.850170,-0.033693,-0.307419,-0.218675,-0.021212,-0.012274,-0.264367,0.728589,-0.788401,0.021183,0.494178,0.257607,-0.126980,0.672740,-0.127190,-0.073454,-0.104241,-0.109828,-0.345805,0.057882,-0.107887,0.161186,0.622712,0.209098,-0.161140,-0.215018,0.396034', '1394176', '1292050', '1297239', '1301172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301231', '电话谋杀案', '悬疑', '汤尼（雷·米兰德 Ray Milland饰）和玛戈（格蕾丝·凯利 Grace Kelly 饰）是貌合神离的一对夫妻。汤尼常常为了他的事业和爱好，把娇妻忘在一边，二人感情亮出红灯。而生活寂寥的玛戈和作家马克不可避免的擦出爱之火花，他们约会、通信，不料竟被汤尼发现。汤尼没有 声张，只是写了一封匿名信给妻子以示警告。然而现在马克竟然造访家中，为了一雪耻辱，加之图谋得到妻子玛戈的丰厚财产，汤尼暗生毒计。 汤尼向旧时同学列斯开出了一千英镑的价钱，让其参与他布下的一整套严密杀人计划。这套计划有设计精妙的凶手不在场证据，电话、钥匙，窗帘，统统成为这个阴谋的道具设置。然而计划终究赶不上变化，列斯不但得不到赏金，还要赔上自己的性命。而汤尼却也急中生了智……©豆瓣', '雷·米兰德', '阿尔弗雷德·希区柯克', 8.9, 99190, 'tt0046912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1205111193.jpg', 0.1, 0.3, 6.5, 41.3, 51.7, '0.136241,0.028585,-0.548279,0.607424,-0.239393,-0.221322,0.505140,0.064443,-0.341660,-0.381260,0.030072,0.587594,0.042702,-0.192471,0.145163,-0.151909,-0.351776,-0.724615,0.337804,-0.209689,0.131557,-0.627210,-0.259464,-0.224329,-0.182728,-0.172374,0.310004,0.106461,-0.052268,0.232051,0.227915,0.238159,-0.190333,0.309345,-0.053071,0.041364,0.004411,0.009483,-0.208044,0.143066,-0.038407,-0.203529,0.005283,0.396173,0.048892,0.662082,0.370767,-0.030537,-0.014720,0.069863,0.393088,-0.330960,0.066789,0.193467,0.027721,0.111828,0.129692,0.166220,-0.187517,-0.189748,0.398372,-0.263263,-1.032196,0.045221,0.027795,0.099159,-0.499167,0.468674,-0.715766,-0.030053,-0.008013,-0.179860,0.204532,0.227462,0.506754,0.209925,-0.255060,0.013153,-0.611109,-0.102174,0.266126,-0.227551,0.354323,0.307234,-0.271433,-0.269630,0.114579,-0.220591,-0.276463,0.046922,0.497045,0.076824,0.072303,0.103179,-0.563229,-0.309503,-0.368078,-0.078353,-0.055392,-0.520676,-0.066914,-0.415425,-0.038999,-0.340621,-0.649342,0.129021,0.253651,-0.319974,0.389802,-0.567012,0.037242,0.276809,0.279104,-0.715957,0.504973,0.267229,0.083740,-0.091230,-0.159665,-0.113370,0.226589,0.154176,0.263921,-0.004383,0.166336,-0.295452,-0.145814,0.395589', '26678784', '3670447', '1307442', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301232', '怪尸案', '喜剧', '小男孩哈尼在森林中漫步时，发现了他的父亲——哈利的尸体。不同于一般谋杀案，这次因为多人都自认为凶手而令案情更加扑朔迷离。亚伯特船长（埃德蒙•格温 Edmund Gwenn 饰）认为是他在打猎射击时误杀了哈利；村落里的老处女葛雷布礼小姐（麦尔翠德•耐维克 Mildred Natwick 饰）认为是因为她为了保住自己的名声而用一只鞋子打了哈利的头部而造成他的死亡；与哈利感情不睦的妻子珍妮佛（雪莉•麦克雷恩 Shirley MacLaine 饰）则认为是她因为反抗哈利的性爱用装牛奶的罐子敲向他的脑袋而造成了他的死亡。真相最后能否水落石出？©豆瓣', '埃德蒙·戈温', '阿尔弗雷德·希区柯克', 7.5, 17920, 'tt0048750', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1775148612.jpg', 0.4, 3.3, 34.5, 43.3, 18.5, '0.273980,-0.069895,-0.505406,0.348706,-0.213876,-0.201281,0.902175,0.186891,-0.323291,-0.144446,0.494146,0.694474,-0.010641,0.064432,0.104362,0.166841,-0.268968,-0.576467,-0.019579,-0.157504,-0.408109,-0.378136,-0.266370,-0.320562,-0.104485,-0.298691,0.430209,-0.096019,-0.286075,0.176383,0.150184,0.287679,0.089770,0.437181,0.206945,0.021503,-0.089905,-0.138237,-0.082757,0.125368,0.207290,-0.255707,-0.037290,0.436646,-0.081058,0.519582,0.784263,-0.527739,-0.136066,-0.260072,0.247968,-0.401132,0.154990,0.286254,0.344598,-0.139965,0.067672,0.273552,-0.024313,-0.030144,0.418602,0.175631,-0.538551,0.027680,-0.076542,0.194297,-0.456563,0.369811,-0.232534,-0.035470,0.243729,-0.321477,0.045676,0.251053,0.231305,0.083381,-0.297715,-0.169601,-0.542578,-0.097530,0.317181,-0.100514,-0.099861,0.278992,-0.450719,-0.419773,0.059247,-0.043615,-0.411607,-0.020050,0.511456,-0.021494,-0.235971,0.463606,-0.296337,-0.153867,-0.430485,-0.205004,-0.152420,-0.271831,-0.215919,-0.248954,-0.044933,-0.371162,-0.297740,-0.448669,-0.094631,-0.335513,0.362309,-0.625495,0.246145,0.793978,0.108505,-0.144008,0.409190,0.116409,-0.012592,-0.081627,-0.105012,0.316098,0.113036,0.015474,0.293470,0.276737,0.255568,-0.085978,-0.121025,0.524388', '21619567', '1428054', '1307800', '3001149');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301233', '擒凶记', '剧情', '本（詹姆斯·斯图尔特 James Stewart 饰）和乔（桃丽丝·戴 Doris Day 饰）是一对感情十分要好的夫妻，带着儿子汉克（Christopher Olsen 饰），一家三口来到了风景如画的摩洛哥度假。一次偶然中，本和乔结识了名叫路易斯（丹尼尔·盖林 Daniel Gélin 饰）的男人，他们在一起相处十分融洽。不幸的事情发生了，路易斯被凶手刺杀身亡，临死前，他透露了一个神秘的名字——“安伯斯·查培”，并且告诉本和乔，有人正在伦敦执行一项秘密的暗杀行动，在得知了这个惊天秘密后，本和乔来到了伦敦。暗杀者自知行动泄露，为了取得最后的成功，他们不择手段绑架了汉克，可即便如此，也没能动摇本和乔声张正义的决心。©豆瓣', '詹姆斯·斯图尔特', '阿尔弗雷德·希区柯克', 7.6, 20618, 'tt0049470', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1974127691.jpg', 0.3, 2.1, 32.8, 47.8, 17, '0.172200,-0.040039,-0.670362,0.589077,-0.167473,-0.094430,0.462685,0.040177,-0.680159,-0.338822,0.267309,0.828949,-0.246414,0.063799,0.373678,-0.040400,-0.253433,-0.577803,0.267069,-0.294065,-0.265028,-0.640922,-0.155848,-0.287116,-0.112597,-0.022230,0.299515,0.242035,-0.240161,0.573441,0.362235,0.361249,-0.222859,0.444123,-0.320763,-0.116254,0.318501,-0.004689,-0.260461,0.330205,0.154668,-0.295599,0.006798,0.314229,0.034614,0.567406,0.527796,-0.269520,-0.227646,0.006444,0.170746,-0.397857,-0.007343,0.196953,0.255637,-0.093538,0.100326,0.465244,-0.342270,-0.178960,0.196891,-0.072105,-0.798265,0.105353,0.258410,0.106761,-0.599701,0.445205,-0.177447,0.151387,0.174690,-0.142764,0.306123,0.633157,0.385922,-0.068200,0.086585,0.054051,-0.746080,-0.080037,0.746355,-0.418336,0.083275,0.246217,-0.172302,-0.351494,0.134505,-0.108018,-0.245755,0.150549,0.528834,-0.024393,-0.189493,0.131277,-0.440344,-0.406372,-0.219809,0.158110,0.024772,-0.512324,-0.028373,-0.683048,-0.217796,-0.336078,-0.372778,0.197134,-0.267355,-0.203741,0.389153,-0.876659,0.248567,0.463330,0.032293,-0.626288,0.532088,0.287364,0.319086,-0.322322,0.018515,0.139523,0.232150,0.089801,0.188285,0.213761,0.209262,-0.238823,-0.377791,0.083509', '1301022', '25908042', '3215099', '27060077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301257', '哗鬼旅行团', '喜剧', '潮州姑娘李嘉玲（吴君如 饰）拥有特异功能，她经常帮助邻里乡亲解决各种疑难问题，在乡村野里颇有名气。某天她被高官以游客的身份派往九龙执行一项秘密任务，她所乘坐的巴士因司机招惹了孤魂野鬼而遭到报复，车毁人亡。鬼魂纷纷钻入死者体内，唯嘉玲一息尚存幸免遇难。众鬼连同嘉玲乘车继续向九龙前进。计划与嘉玲接头的一眉道长（林正英 饰）路遇众鬼所乘之车，情知不好，尾随跟踪，终与嘉玲接头。道长告诫她和其他旅客下榻的宾馆有鬼，嘉玲始终不信，直到……©豆瓣', '林正英', '刘仕裕', 6.6, 5508, 'tt0104456', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2227964096.jpg', 1.8, 11.8, 52.4, 22.2, 11.8, '0.235719,-0.261567,-0.268064,0.180626,0.235339,0.148444,0.309959,0.114108,-0.653109,-0.353617,0.435816,0.537324,0.046140,-0.068918,0.140048,-0.205825,-0.241763,-0.135771,0.253352,0.019233,-0.081109,-0.266623,0.070157,-0.326544,-0.116065,-0.333365,0.315923,0.268326,-0.198639,0.264832,0.194655,0.309588,-0.784015,0.189893,-0.241336,-0.082547,-0.038489,-0.025336,-0.091575,0.227667,-0.125805,-0.410701,-0.011848,-0.160220,-0.101706,0.447497,0.570626,-0.132086,-0.384070,-0.058663,0.056030,-0.397599,0.221895,0.166672,0.213078,0.044178,0.248723,0.235195,-0.155542,0.064037,-0.128918,0.269858,-0.131434,-0.166417,0.427033,0.247275,-0.354104,-0.103655,-0.223313,-0.042309,-0.122272,-0.295515,0.192945,0.259849,-0.019532,-0.115228,-0.004268,-0.070596,-0.501186,0.146711,0.656956,-0.024599,0.324882,-0.050562,-0.009164,-0.199449,-0.012398,0.035400,-0.319268,0.102750,0.258947,0.122942,-0.027099,0.035139,-0.297538,-0.271077,-0.101993,0.068546,-0.184509,-0.034393,0.138032,-0.877635,0.341054,0.114381,0.146710,-0.116394,0.295744,0.040095,0.450705,-0.523416,0.127857,0.536440,0.502127,-0.728891,0.433489,-0.218559,0.246678,-0.414795,-0.209133,0.015854,0.448333,0.447026,-0.027469,0.156808,-0.148488,-0.199792,-0.153010,-0.221035', '2369613', '1794401', '3147969', '26826398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301272', '小城之春', '剧情', '本片为田壮壮向1948年费穆执导的同名电影的致敬之作，与费版相比，画面颜色变成彩色，空间延展许多，女主人公的独白被隐去，故事内容和讲述的手法也有一些不同，变得更为今天的观众所能接受。影片伊始，便点题交代了年轻少妇周玉纹（胡靖帆）和丈夫戴礼言（吴军）之间貌不合神也离的关系，玉纹对礼言只是在尽传统道德伦理要求她尽的义务，同时，礼言的昔日好友、玉纹的旧时情人章志忱（辛柏青）正从上海赶往小城，虽然他的到访令玉纹在情与礼之间摇摆不定，有了走出小城的心思，但因独白不再，那更多是突兀而非满足心中长久以来的期待。而小妹戴秀（卢思思）因为身边原有一大帮和她一样充满朝气活力的朋友，志忱对她的触动以及她对志忱的爱，也打了些折扣。©豆瓣', '胡靖钒', '田壮壮', 7.3, 7934, 'tt0332831', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1180841007.jpg', 1.4, 5.8, 35.5, 43.4, 14, '0.410065,0.033153,-0.569209,0.730173,0.030222,-0.181369,0.933748,0.229018,-0.370184,-0.144236,-0.037965,0.840968,-0.335931,0.093717,0.085302,-0.324078,-0.193175,-0.626261,-0.229665,-0.223578,0.039598,-0.620974,0.057301,0.009559,-0.276538,-0.428176,0.695953,-0.009353,-0.341093,0.438774,0.355442,-0.005733,-0.081589,0.476040,-0.091711,0.023658,-0.310900,0.202141,-0.346537,-0.080525,0.119780,-0.072539,-0.260965,0.238579,-0.192211,0.416963,0.743028,-0.140129,-0.376975,0.065813,0.364624,0.093127,0.191562,0.047095,0.041845,0.213040,0.318546,0.279522,-0.122073,0.008656,-0.018686,-0.122591,-0.639184,0.148717,0.333594,0.254963,-0.349718,0.443491,0.046632,-0.249191,0.035256,-0.289018,0.195723,0.099572,0.355537,0.524214,-0.104179,-0.030410,-0.354626,0.131506,0.661157,0.339873,-0.110900,0.620895,-0.673044,-0.405554,-0.179400,0.042299,-0.331917,-0.051776,0.137576,0.019128,0.053586,0.313033,-0.681745,0.058322,0.068795,0.060449,-0.064317,-0.636224,0.081027,-0.453512,-0.336627,-0.726710,-0.251150,0.053345,0.406384,-0.201828,0.921279,-0.944023,0.173049,0.198164,0.290935,-0.586772,0.699665,0.308691,-0.100378,-0.245629,-0.115657,0.303971,-0.116287,0.015028,0.018501,0.233604,-0.198603,-0.156038,-0.373339,0.553115', '1309161', '2053515', '26283288', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301278', '九一神雕侠侣', '剧情', '美君（梅艳芳 饰）、秦哥（刘德华 饰）、小村（钟镇涛 饰）是城市雇佣兵。美君和秦哥青梅竹马，两人情投意合。而后来加入的小村也深爱着美君，美君对两人摇摆不定。美君执行任务，将老鹰双眼弄瞎。老鹰临死前让他的徒弟银狐（郭富城 饰）替其报仇。银狐追杀美君，小村为救美君而死，临死前将他的妹妹惠香（叶蕴仪 饰）托付给秦哥照顾，而银狐的一只眼睛也被美君弄瞎。美君为了不连累秦哥，独自远走高飞。而秦哥则带着惠香，到处寻找美君的踪迹。直到有一天，美君的姐姐美慧（梅艳芳 饰）欺骗秦哥说，现在美君改名换姓为宠物夫人，正在比武招亲。秦哥赢了众人，才得知宠物夫人（刘嘉玲 饰）并非美君，只能拒绝和宠物夫人成婚，独自离去。后来他终于发现了美君的踪迹，然而此时银狐再次追杀上门。美君更中了银狐的“恐怖天使”毒药，24小时内即将毒发，而天下能解此毒的只有宠物夫人。秦哥只能抱着美君回去找宠物夫人.......', '刘德华', '元奎', 6.4, 9228, 'tt0104322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2610998192.jpg', 2.4, 12, 56.8, 21, 7.9, '-0.011933,-0.130822,-0.212595,0.259618,-0.044081,-0.419239,0.583420,0.005883,-0.331885,-0.168627,0.198636,0.458525,0.054206,0.230889,0.019732,0.255288,-0.034988,-0.375256,-0.016901,-0.018429,-0.148169,-0.387859,0.049282,-0.008118,0.081685,-0.091529,0.418709,-0.099606,0.160068,0.513152,0.381809,0.062251,-0.287577,0.311520,-0.102718,-0.021165,-0.122357,0.041513,-0.192034,0.378314,0.128893,-0.067433,-0.042026,0.154127,-0.059555,0.056834,0.661771,-0.393960,0.131498,-0.598940,0.045500,-0.399211,0.109811,-0.115101,0.217872,-0.295117,0.584574,0.087317,-0.184230,-0.150448,0.037066,0.043539,-0.294653,0.412446,0.345726,-0.003033,-0.372325,0.109476,-0.191511,-0.026389,0.306426,-0.285932,0.396679,0.184174,0.060859,0.154570,-0.384275,0.207988,-0.378256,0.063653,0.310167,-0.161241,0.460402,0.129118,0.255550,-0.368358,0.335990,-0.158938,-0.363148,0.164594,-0.032518,0.192644,-0.311925,0.059564,-0.442972,-0.187819,-0.351931,0.096550,0.032863,-0.628093,0.098902,-0.133293,-0.029084,-0.115519,-0.171067,0.168465,0.309722,-0.121098,0.412717,-0.560281,0.231789,0.316714,0.345343,-0.380599,0.504935,-0.010073,0.081564,-0.151822,-0.070857,-0.150627,0.027928,0.226246,0.469926,0.063461,0.143714,-0.103755,-0.297685,0.047665', '1417036', '3445516', '6974439', '2301363');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301283', '古惑仔3之只手遮天', '剧情', '东升社在老大骆驼的重整下声势日盛，而洪兴社在蒋天生（任达华　饰）的管理下亦蒸蒸日上。两个帮派暗中有不少争斗，但表面上两个帮派仍和和气气。东升社的乌鸦（张耀杨　饰）野心极大。他在东升社的最大势力所在地荷兰阿姆斯特丹市枪杀蒋天生，再嫁祸于陈浩南（郑伊健　饰）。洪兴社的众人都以为陈浩南勾结外人杀死了蒋天生，派出大飞追杀陈浩南，陈浩南侥幸逃脱。乌鸦见骆驼病重，乘机将其杀害，顺利坐上了东升社老大的位置。乌鸦准备为骆驼举办一场风光大葬。葬礼当日，各路江湖人马齐聚灵场，浩南、山鸡（陈小春　饰）亦出现了…©豆瓣', '郑伊健', '刘伟强', 7.7, 92985, 'tt0116455', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2607351160.jpg', 0.5, 2.1, 28.9, 47, 21.5, '-0.102248,0.254008,-0.652579,0.508603,0.244287,0.078404,0.229011,0.261657,-0.316385,-0.260654,0.136613,0.448720,0.069305,0.247458,-0.010139,-0.610024,0.087909,-0.363990,-0.137012,0.052000,0.096726,-0.126786,-0.366957,-0.138877,-0.116350,0.302071,0.531017,0.323215,-0.165374,0.853645,0.529410,0.099918,-0.085093,0.209847,-0.260996,0.068422,0.233285,0.069238,-0.047494,0.126478,-0.264225,-0.273981,-0.059119,0.149407,0.133943,0.137858,0.636448,-0.195974,-0.011343,-0.571987,0.123689,-0.307287,0.236975,0.045271,0.958586,-0.034448,-0.022267,0.278452,-0.172939,-0.138326,0.061063,0.082206,-0.434813,0.063507,0.407863,0.053533,-0.539658,0.409568,0.087453,0.025145,-0.260600,-0.016697,0.285321,0.560528,0.228695,-0.091468,0.412387,0.123713,-0.679768,-0.021121,0.828282,0.036363,0.085449,-0.422699,0.337224,-0.144702,0.163892,-0.318988,0.078521,-0.242292,0.539872,-0.490347,0.243099,-0.027526,-0.486746,0.107465,-0.074270,0.190615,-0.067536,-0.335304,0.382300,-0.752584,-0.144036,-0.237050,-0.182147,0.142650,0.278359,-0.009537,0.596752,-0.710204,-0.007875,0.074731,0.100242,-0.623384,0.154944,-0.073492,0.182857,-0.143172,-0.172185,-0.222807,0.470798,0.395748,0.161122,0.227036,-0.294325,-0.420322,0.046705,-0.090571', '26365262', '1294227', '1307186', '2065021');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301328', '暗流', '悬疑', '《暗流》2000年9月27日在法国上映时好评如潮，首周观众人数就突破百万，并成为2000年法国卖座冠军大片。丰富经验的巴黎警探皮耶（让·雷诺 Jean Reno 饰）来到大学城侦查被绞杀的尸体高悬在山崖上的离奇命案。经过一番调查后尼芒斯发现：这所著名学府历史悠久，人才 辈出，但校方为了推行精英观念，竟让教职员间世代通婚。与此同时，充满冲劲的当地年轻警察麦斯（文森特·卡索 Vincent Cassel 饰）则在小教堂追查20年前神秘失踪的少女，有人入侵了十八年前死于车祸的十岁女孩朱迪丝的墓室，并在那里涂画纳粹标志。看似孤立的两起案件却有着内在联系，于是两个办案风格大异其趣的人不得不变成搭档，联手侦破其中的秘密。经过层层抽丝剥茧，终于使隐藏在案件背后的真相浮出了水面。©豆瓣', '让·雷诺', '马修·卡索维茨', 7.3, 17489, 'tt0228786', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193639604.jpg', 0.5, 3, 37.5, 47, 12, '-0.003200,-0.115174,-0.570440,0.315135,0.176723,-0.020795,0.592466,-0.104786,-0.692253,-0.267080,0.330337,0.353092,-0.413329,0.089030,0.254270,-0.330408,-0.349229,-0.728583,-0.107579,-0.497277,-0.278458,-0.229320,-0.430244,-0.177386,0.020848,-0.310396,0.742500,0.523934,-0.195538,0.335804,0.108082,0.250002,-0.453998,0.186444,-0.108098,-0.266511,0.325941,0.043024,-0.183448,0.213357,-0.409571,-0.452154,-0.253048,-0.270783,-0.027631,0.315057,0.644354,-0.084782,-0.136954,0.102470,0.431238,-0.249215,-0.222021,-0.020209,0.758549,0.228463,0.137143,0.495285,-0.130755,-0.089740,-0.058786,-0.344470,-0.322580,0.092571,0.220359,0.238383,-0.347091,0.350311,0.059615,-0.057288,-0.094808,-0.153544,-0.155197,0.308904,0.110582,0.448024,-0.009476,0.203479,-0.489539,0.090558,0.409952,-0.074219,-0.248173,-0.113715,-0.147070,-0.585088,-0.124743,-0.184729,0.081403,0.076865,0.363869,-0.137628,-0.017380,0.410167,-0.576976,0.016510,-0.417871,-0.216183,-0.038359,-0.079167,-0.229506,-0.845782,-0.245723,-0.030072,-0.195432,0.201172,0.031478,-0.184257,0.623603,-0.645160,0.174480,0.439441,0.179708,-0.275200,0.442726,-0.105495,-0.020137,-0.167592,-0.345686,0.394266,0.137226,0.191755,-0.217793,0.237510,-0.212541,-0.447675,-0.228760,0.215416', '25723905', '3266509', '20274039', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301342', '风中奇缘', '剧情', '故事发生在新大陆被发现不久后，英国一批勇敢的开拓者在雷利夫总督和上尉庄麦斯的带领下来到了美洲新大陆，遇上了当地美丽的土著公主宝嘉康蒂。庄麦斯被美丽的宝嘉康蒂深深吸引，庄麦斯向她解释了总督是为了黄金才来到这里，但他很乐意帮助当地的土著建设家园；宝嘉康蒂表示这里的人从来没有见过黄金。这时庄麦斯得知雷利夫总督挖不到黄金，已经开始攻打当地的部落意图从他们手中夺取黄金。他决定阻止这一切，化解白人和当地人之间的仇恨。©豆瓣', '乔·贝克', '迈克·加布里尔', 7.7, 33008, 'tt0114148', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1363167489.jpg', 0.6, 2.6, 29.1, 46.5, 21.3, '0.284995,0.020880,-0.945446,0.509100,0.012471,-0.165491,0.677729,-0.112493,-0.525642,-0.206963,-0.101231,0.834839,-0.145353,-0.018176,0.506607,0.168978,-0.508104,-0.629538,-0.311884,-0.226548,-0.312999,-0.352304,-0.418410,-0.299113,-0.254505,-0.341554,0.338324,0.254878,-0.075643,0.591428,0.267787,0.451197,-0.011854,0.606838,-0.181989,0.221546,0.380911,-0.029767,-0.098404,0.517857,-0.222621,-0.135493,-0.169160,0.443713,0.117397,0.439040,0.317999,-0.444715,-0.044933,-0.019282,-0.031718,-0.535165,0.344608,0.219250,0.673320,-0.070455,-0.010678,0.130329,-0.441997,-0.231417,-0.049462,-0.233297,-0.484862,-0.014305,0.145099,0.159537,-0.675742,0.283013,0.071509,0.022583,-0.028835,-0.552624,0.390549,0.581990,0.060128,0.168756,0.031885,-0.002894,-0.691040,0.094363,1.054525,0.014863,-0.139225,-0.197854,-0.106490,-0.452022,-0.063801,-0.315640,-0.171822,0.098127,0.472537,0.501747,-0.190067,0.119369,-0.824210,-0.312494,-0.384626,-0.390084,0.227396,-0.421399,-0.209967,-0.411062,-0.060142,-0.259474,-0.050816,0.036708,0.118134,-0.033388,0.744314,-1.047968,0.062286,0.460276,0.684593,-0.408279,0.403678,-0.120528,-0.180584,-0.159064,0.150934,-0.017818,0.492332,0.513982,0.159562,0.190244,-0.099171,-0.302788,-0.353712,0.456909', '25721544', '30210700', '1458900', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301345', '偷天换日', '动作', '查理(马克·沃尔伯格 Mark Wahlberg 饰)本来可以拿着抢劫回来的那箱黄金安度余生，同伙史蒂夫（爱德华·诺顿 Edward Norton饰）的出卖却让他的阵脚大乱。史蒂夫不但独吞了巨款逃亡洛杉矶，还害得查理尝尽牢狱之苦。现在从监狱出来的查理，正踌躇满志要找史蒂夫算上一帐。他网罗了盗窃高手——美女斯黛拉（查理兹·塞隆 Charlize Theron 饰）专门负责开保险柜，而他和其他搭档，则全力设计出一条通畅的大道，供迅速逃跑之用。斯黛拉前往引史蒂夫上勾，却被老奸巨猾的史蒂夫识破。查理则飞速的破坏了洛杉矶的红绿灯系统，洛杉矶发生了蔚为壮观的大塞车，然而，令他们意外的是，逃脱没有如此简单——史蒂夫没有驱车追赶，他用了一辆直升飞机，在他们上空穷追不舍。洛杉矶的地下隧道和街头小巷，陷入了一片混战。©豆瓣', '马克·沃尔伯格', 'F·加里·格雷', 7.6, 124995, 'tt0317740', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1693861981.jpg', 0.3, 2.2, 30.9, 49.7, 16.9, '0.285459,0.091690,-0.644639,0.410885,-0.059130,-0.489731,0.864085,0.062794,-0.218717,0.050607,0.247560,0.607467,-0.066058,-0.013749,0.288702,0.031342,-0.536465,-0.326297,-0.040084,-0.250583,-0.235160,-0.477045,-0.391556,-0.195271,0.099622,-0.114835,0.305833,0.029000,-0.112136,0.399458,0.236554,0.309397,-0.062326,0.324445,-0.215174,0.224150,0.057505,-0.301888,-0.122474,0.148020,-0.149099,-0.355926,-0.181475,0.268830,0.062076,0.492762,0.622785,-0.114621,0.052613,0.092791,0.206979,-0.379687,0.131030,-0.183475,0.140994,-0.132007,-0.005928,-0.084130,-0.182419,-0.015135,0.275210,0.128609,-0.797827,0.160005,-0.296591,0.112934,-0.416067,0.257897,-0.324982,0.062435,0.080252,-0.425674,0.116247,0.333627,0.158879,0.120517,-0.006859,-0.054836,-0.865716,0.185769,0.577057,-0.172668,-0.025029,0.247547,-0.188573,-0.222230,0.076188,-0.218658,-0.432956,-0.379339,0.852184,-0.155139,-0.038222,0.013783,-0.315646,-0.071819,-0.477163,-0.283446,-0.203493,-0.097148,-0.201770,-0.864086,0.205534,-0.130417,-0.156325,0.095817,-0.127248,0.049244,0.136927,-0.462269,0.156160,0.707944,0.185153,-0.303131,0.630489,-0.180826,0.140700,0.202151,-0.108350,0.079870,0.378086,0.621452,0.480120,0.413655,0.040626,-0.204631,-0.395168,0.333393', '1301686', '1316693', '3183490', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301359', '五个扑水的少年', '喜剧', '唯野学院的游泳部式微，只得铃木（妻夫木聡饰）一个学员，还是个菜鸟。一日，新来了一位漂亮教练佐久間，男生全被吸引过来，可是，佐久間教的竟然是花样游泳！男生花样游泳！大家纷纷打退堂鼓，只有五个人留下来。谁知，人算不如天算，佐久間才接手游泳队，她就被查出怀孕回家待产，而花样游泳的节目已经被报到文化节上了。群龙无首，游泳部像是一团散沙，所有人都毫不掩饰轻视之情，队员们也毫无自信。在对抗篮球部的一次“反击”行动中，队员们闯下大祸，只能通过卖演出门票来赔偿损失，相应的，表演也成势在必行，这下子，男生们可被逼上梁山啦。©豆瓣', '妻夫木聪', '矢口史靖', 8.3, 56865, 'tt0299213', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p958191439.jpg', 0.2, 1.1, 15.2, 48.4, 35, '0.105372,-0.326052,-0.315441,0.230666,-0.393547,-0.227337,0.149554,-0.169909,-0.308407,-0.144679,0.117494,0.478738,-0.346549,0.303503,0.179997,-0.370300,-0.135305,-0.784433,-0.379314,-0.076960,-0.288431,-0.145964,0.142218,0.008272,-0.107823,-0.008034,0.614924,0.031222,-0.234573,0.461076,0.652265,-0.206834,0.045711,0.195041,0.073978,-0.055615,0.281808,-0.107186,0.420787,0.186313,-0.384790,-0.098036,-0.406047,0.066760,0.221157,0.315753,0.653305,-0.058270,0.010344,-0.129227,0.335207,-0.338465,-0.048491,0.283266,0.464650,0.021337,0.171518,-0.065788,-0.043934,0.445722,-0.107176,-0.092655,-0.536231,0.355065,0.177664,-0.092681,-0.473142,0.545981,0.232023,-0.190513,-0.096761,-0.260496,0.090540,0.091326,-0.002122,0.220869,-0.115004,-0.071263,-0.301593,0.200822,0.798615,-0.002501,-0.196288,-0.234412,0.120605,-0.335390,0.104029,-0.520317,-0.160869,0.192431,0.234817,-0.086511,0.133552,-0.151419,-0.513494,0.027991,-0.155371,-0.486398,-0.231593,-0.375736,0.332249,-0.708190,0.508608,0.228284,-0.547454,0.191835,0.281048,-0.011909,1.081183,-0.786411,-0.022592,0.401968,0.076219,-0.494676,0.479856,-0.073268,-0.121304,-0.001995,-0.210891,-0.252838,0.362449,0.249123,0.267748,0.697580,-0.255162,-0.369613,-0.071025,0.087275', '1316589', '25922902', '1826173', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301367', '潘金莲之前世今生', '剧情', '千古第一淫妇潘金莲（王祖贤饰）身首异处，魂赴阴曹，却念念不忘报仇雪恨。过奈何桥之际推翻孟婆汤，纵身跳入轮回的未知。今世正值文革动乱，芭蕾舞团的翘楚单玉莲（王祖贤饰）惨遭团长强暴，下放农村造鞋厂。一心只求宁静生活，却一再被宿命折磨的可怜女子注定了一生的颠沛流离。由内陆辗转香江，生命中先后出现的3个男人武龙（林俊贤饰）、武汝大（曾志伟饰）、Simon（单立文饰）似乎都只是前世的梦影。凄苦命运是否仍要重演，身处现代的飘零女子是否仍将走上千年前的老路？所谓的报仇雪恨是否真能如愿？爱恨交织的不了情又将何去何从？1989年上映，改编自香江名笔李碧华的同名小说的《潘金莲之前世今》在小心延续了该作妖艳诡异又不乏深邃犀利风格的同时，不可避免加入了港片诸多商业元素。但在注重娱乐性的同时，也将焦点放在了对人性以及女性细腻心理的探索上。镜头语言丰富，画面亦幻亦真，两个不同时空的影像交织，使信息的传达更富感性色彩。值得一看。', '王祖贤', '罗卓瑶', 6.7, 14052, 'tt0098056', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2348768953.jpg', 1.6, 10, 49.1, 29.1, 10.1, '-0.023565,0.193096,-0.429751,0.526009,0.067851,-0.153173,0.587479,0.001088,-0.454422,0.038573,0.276915,0.604495,-0.054758,0.071806,0.214448,-0.130911,-0.044619,-0.627143,-0.133785,-0.006653,-0.153267,-0.274826,-0.375097,0.250662,0.011834,-0.312552,0.797887,0.190592,-0.204067,0.288804,0.150896,0.185785,-0.533134,0.148758,-0.291195,0.005787,-0.099916,0.226724,-0.408685,-0.061567,-0.064011,-0.600297,-0.128138,-0.033971,-0.427006,0.160691,0.674959,-0.417151,-0.188977,-0.022114,0.668662,-0.103504,-0.323873,0.204596,-0.016759,0.216770,0.010628,0.392661,-0.115978,-0.063504,0.040836,0.015272,-0.775881,-0.062280,0.304428,0.163106,-0.350054,0.451149,0.148647,-0.053985,-0.101117,-0.002091,0.173226,0.011878,0.616744,0.355903,-0.119934,0.012961,-0.057246,0.400305,0.598048,0.198882,-0.399231,0.311886,-0.189246,-0.287321,-0.031295,-0.244687,-0.476296,0.022461,0.292652,0.172263,-0.180507,0.540307,-0.594519,0.216948,-0.094466,-0.001754,0.052122,-0.206603,-0.268504,-0.313930,-0.353150,-0.360511,-0.221797,-0.023818,0.302434,-0.144271,0.797577,-0.515595,0.274421,0.522211,0.075736,-0.415851,0.611652,0.090895,0.070618,-0.079068,-0.112854,0.646839,0.012803,0.245421,-0.190705,0.226167,-0.316882,0.069203,-0.411057,0.51