INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301374', '少女情怀总是诗', '剧情', '「少女情懷總是詩」，是1977年坎城影展最受爭議的影片，以大膽而唯美的映像，描述一名情竇初開的女學生與她的初戀，而她的戀愛過程中，又牽扯到女同性戀的情節。標題的「碧麗提絲」，是古希臘一位生活在賽浦路斯的交際花，據說她曾經以跟她同一個時代的古希臘女詩人賽佛（Sappho）類似的風格，寫下不少描述女同志愛情生活的詩篇，因此後來成了西方女同志的象徵人物，而她和賽佛所居住的小島「蕾絲柏斯」（Lesbos），更是女同志「蕾絲邊」（Lesbian）這個名詞的來源。1955年，最早成立的女同志組織之一，就用「碧麗提絲的女兒」（Daughters of Bilitis）當作名稱。', '帕蒂·达班维尔', '大卫·汉密尔顿', 7.4, 8589, 'tt0075753', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2773233414.jpg', 0.6, 4.6, 36.4, 39.9, 18.5, '0.646601,-0.397746,-0.449487,0.883774,-0.212792,-0.342245,0.877886,0.113858,-0.282503,-0.257135,0.702845,0.979837,-0.238617,0.357494,0.691283,0.019415,0.042294,-0.799572,-0.183117,-0.464182,-0.193574,-0.290426,-0.155386,0.121871,-0.280169,-0.652773,0.726551,-0.352809,-0.109712,0.101595,0.402831,0.441625,0.101131,0.208960,-0.476120,0.007968,0.003255,0.088900,0.034568,-0.062776,0.017468,-0.301902,-0.365964,-0.059615,-0.023363,0.418424,0.802146,-0.610065,-0.170343,0.047554,0.543310,-0.574636,-0.023658,-0.029151,0.548552,-0.281938,0.362891,0.087505,-0.006535,-0.171725,0.054748,-0.329576,-0.747149,0.131929,0.137160,0.264501,-0.570976,0.274817,0.281071,-0.018798,0.020786,-0.295320,0.308047,0.283794,0.071497,0.630810,-0.114073,-0.081019,-0.367188,0.669753,0.842581,0.374850,-0.548115,0.522856,-0.506722,-0.712304,-0.334147,-0.306554,-1.017415,-0.023824,0.275600,-0.306232,-0.250127,0.263357,-0.833276,-0.258538,-0.163990,-0.261300,0.243841,-0.340829,0.049148,-0.659434,-0.378396,-0.730921,0.047761,0.076895,0.479955,-0.380434,1.128970,-1.292254,0.136156,0.403929,0.077686,-0.812722,1.023270,0.166358,0.012790,0.108749,-0.355312,0.290509,0.282052,0.220541,-0.257712,0.993286,-0.318982,-0.263078,-0.421732,0.344201', '6963575', '3445516', '4817024', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301376', '龍咁威2003', '喜剧', '龙威（郑中基 饰）是亿万富翁龙大双（罗家英 饰）的独生子，由于家庭十分富有，龙威与其他两名好友黄金舟（张达明 饰）、吴树喜（李灿森 饰）过着挥霍无度的生活。父亲们见他们的儿子都是不务正业的，所以便通过层层关系把龙威几个送到警校接受训练。艰苦的生活对他们来说是莫大的折磨，他们大肆破坏想离开。此时龙威遇到了梦中情人悯情（邓丽欣 饰），但悯情的父亲阻止了他们交往，悯情也不喜龙威的不求上进。龙威自此自暴自弃，在父亲的鼓励下，龙威决定成为一个顶天立地的英雄。父亲极力锻炼龙威，与此同时悯情在一次行动中被挟持，生死未卜。龙威决心要救出心爱的女孩。©豆瓣', '郑中基', '谷德昭', 6.6, 5835, 'tt0379878', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359316179.jpg', 2.6, 11.3, 49.9, 26.2, 10.1, '-0.014950,-0.067890,-0.597543,0.728591,-0.258510,-0.071621,0.688670,0.182469,-0.534425,-0.446226,0.210630,0.565423,0.082521,0.519297,-0.082949,-0.138240,0.010386,-0.754279,-0.175832,0.100901,-0.121489,-0.409407,-0.120172,0.064144,-0.335025,-0.415881,0.600014,-0.035392,-0.267597,0.423708,0.518541,0.371696,-0.016062,0.395276,-0.456923,-0.117807,0.047768,0.203563,-0.452910,0.222620,-0.200711,-0.147740,-0.100744,0.425822,0.158970,0.204341,0.645237,-0.364582,-0.097049,-0.266286,0.268035,-0.251016,-0.076273,0.176617,0.213349,0.169356,0.289943,0.449426,-0.259873,0.267936,-0.067859,0.057168,-0.736192,-0.025669,0.107789,0.078663,-0.885713,0.416924,-0.010595,-0.285633,0.024002,-0.193440,0.221698,0.100322,0.095402,0.418195,-0.331868,0.379117,-0.521942,0.059837,1.094052,-0.116313,0.053345,0.321673,-0.290461,-0.176364,0.074616,-0.116059,-0.409850,-0.195281,0.168742,0.127911,-0.150842,0.172000,-0.618358,-0.060509,-0.261368,0.145954,-0.214342,-0.542283,0.053551,-0.513311,-0.223203,-0.579839,-0.399140,0.198939,0.155795,-0.359325,0.773561,-0.810204,0.141896,0.309915,0.465661,-0.923014,0.503664,0.471612,0.096053,-0.063373,0.154986,0.218150,0.154286,-0.041418,0.034281,0.173963,-0.041676,0.003317,-0.199702,0.488383', '25721544', '4861627', '1301022', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301381', '赌神3之少年赌神', '剧情', '高进（黎明）在同师父千王靳能（钟景辉）学过将近10年技艺后，熟练掌控一切千门技巧，加上与靳能的女儿靳轻（梁咏琪）情投意合，17岁的他可谓春风得意，为了与靳轻风风光光的成婚，他答应靳轻将事业推向高峰，决定参加在澳门举行的新一届“赌神大赛”。令他没想到的是自己会马失前蹄。高进大赛中被靳能出卖，虽因爱慕他的细七（袁咏仪）与好友龙五（陈小春）伸手相助得以侥幸保命，却也几乎成为废人。在细七的精心照料下，高进奇迹般痊愈，晓得了事情的真相，同时发现多年前父亲死的真正原因，新仇加旧恨促使他振作，决意与师兄高傲（吴镇宇）及靳能在赌桌上再战生死，取回属于自己的东西。©豆瓣', '黎明', '王晶', 7, 31682, 'tt0119513', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2462221496.jpg', 0.8, 5.9, 46.8, 33.3, 13.2, '-0.194948,0.257432,-0.612025,0.280959,-0.019809,-0.227022,0.246993,-0.169272,-0.613123,-0.237712,0.314514,0.797327,-0.040270,0.282180,0.101607,-0.365839,0.110076,-0.943280,-0.041739,-0.071523,-0.228245,-0.290287,-0.316706,0.166386,-0.193145,-0.434458,0.645252,0.022320,-0.156310,0.610430,0.390369,0.076521,0.011361,0.297890,-0.109016,-0.104376,-0.162622,0.279245,-0.725919,0.218519,0.056709,-0.359365,-0.287375,0.113206,0.038239,0.246815,0.428295,-0.132636,-0.049902,-0.115087,0.230064,-0.394080,-0.215898,0.175109,0.052960,0.086486,0.095853,0.477344,-0.164589,-0.139768,0.085147,-0.121304,-0.717032,-0.088471,0.231613,-0.119614,-0.671069,0.494828,-0.260238,0.020090,-0.149764,-0.439627,0.138977,0.374530,0.237549,0.090928,-0.271993,-0.028931,-0.340915,0.275517,0.658433,-0.045334,-0.052567,0.262348,0.271688,-0.451957,0.040656,-0.655924,-0.221649,0.139626,0.250626,0.086806,0.008319,0.328478,-0.055545,-0.231691,-0.240074,0.119924,0.050639,-0.323738,0.120786,-0.104112,-0.278399,-0.257232,-0.382834,-0.117403,0.202833,-0.660730,0.666017,-0.794354,0.298475,0.150932,0.230791,-0.387916,0.461008,0.126093,0.247341,-0.354025,-0.178233,0.181711,-0.132894,0.128032,0.085190,0.085239,-0.091331,-0.023225,-0.528310,0.422741', '30345227', '35030151', '1897368', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301392', '让爱传出去', '剧情', '单亲妈妈阿琳·麦肯尼（海伦·亨特 Helen Hunt饰）生活拮据，为了抚养儿子特雷弗·麦肯尼（海利·乔·奥斯蒙特Haley Joel Osment饰）而拼命工作，唯有借酒消愁才能打发深深的失落与无助。相依为命的两母子，一直过着毫无希望的生活。然而这一切在有一天发生了改变。特雷弗的社会学老师尤金·赛门特（凯文·斯帕西Kevin Spacey饰）布置了一道特殊家庭作业：让世界变得更美好。深信善有善报的特雷弗，决心从自己做起，于是他把无家可归的流浪汉请到了自己家中。以彰显人性本善，宣传世界美好为题的社会伦理片《让爱传出去》，由美国女导演咪咪·莱德执导。咪咪为本片推出全奥斯卡阵容：曾获奥斯卡最佳男主角的凯文·斯帕西担当男主角，女主角则由荣获过奥斯卡最佳女主角的海伦·亨特出演，童星海利·乔·奥斯蒙特饰演让世界变得更加美好的小主人公特雷弗。©豆瓣', '凯文·史派西', '米密·莱德', 8.2, 7837, 'tt0223897', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p840638424.jpg', 0.4, 2.2, 18.6, 46.5, 32.3, '-0.032864,-0.123937,-0.432711,0.542781,-0.030758,-0.534758,0.564899,0.333186,-0.231698,-0.215019,0.087318,0.793919,-0.291194,0.189800,0.487823,-0.072290,-0.458740,-0.560161,0.055708,-0.204121,0.000322,-0.529437,-0.192063,-0.461885,-0.225064,-0.266859,0.508088,-0.331807,0.091894,0.193979,0.331749,0.379639,0.325055,0.198938,0.186821,0.218518,0.200510,0.066832,-0.460958,0.112166,0.503581,0.130792,-0.373030,0.258028,0.214927,0.031834,0.637169,-0.430680,0.095589,-0.067007,0.554149,-0.143358,0.080694,-0.142964,0.092366,-0.290169,-0.165518,0.215674,-0.115847,0.056293,0.170715,-0.325535,-0.579413,-0.073530,0.074513,0.053497,-0.328386,-0.132569,-0.174167,0.019665,0.232795,-0.277499,-0.051604,0.203029,0.520587,0.362812,-0.020957,0.073676,-0.159513,0.630351,0.371738,-0.025433,-0.530247,0.373566,-0.608889,-0.237426,0.117613,-0.132433,-0.908209,0.001666,0.376555,-0.291749,0.178803,0.523987,-0.322001,-0.304487,-0.427918,-0.261415,-0.052124,-0.319140,0.086833,-0.628852,-0.313404,-0.019366,0.115372,-0.075334,-0.064480,-0.355337,0.717752,-0.595909,0.356144,0.369205,0.160188,-0.098847,0.589654,0.124727,0.547559,-0.161868,-0.149206,0.741805,-0.164963,-0.093731,0.179258,0.298130,0.117076,-0.005437,-0.323195,0.485536', '26647163', '3009079', '26