INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301403', '偷窥', '爱情', '刚刚经历了一段失败感情的卡莉（莎朗·斯通 Sharon Stone 饰）决定换一个生活环境开始新的生活，于是，她入住了“碎片”大厦。果不其然，没过多久，卡莉就在此处结识了两个风流倜傥的男人杰克（汤姆·贝伦杰 Tom Berenger 饰）和泽克（威廉·鲍德温 William Baldwin 饰），通过这两个男人之口，卡莉发现了一个惊人的秘密，自己租住的房子的原房客系自杀身亡，而熟知此事的邻居也在不久之后于建筑内被害。在和泽克深入交往之后，卡莉发现他竟然就是这幢公寓的主人，而在公寓的角角落落里，布满了泽克设置的，用于满足他偷窥癖好的摄像头。一时间，杀害两名死者的凶手的嫌疑落在了泽克的身上，然而，这一切到底是假象还是事实？卡莉也无法判断。©豆瓣', '莎朗·斯通', '菲利普·诺伊斯', 6.4, 13206, 'tt0108162', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2478768284.jpg', 1.8, 13.2, 53.6, 24.3, 7.2, '0.442323,0.058967,-0.663984,0.559887,-0.340994,-0.168825,0.895854,0.085370,-0.528136,-0.548413,0.379543,0.797588,-0.236044,0.254474,0.198854,0.137309,-0.291140,-0.533615,-0.053851,-0.523231,-0.466196,-0.512041,-0.356145,-0.518856,0.179133,-0.410506,0.483005,0.240728,-0.235846,-0.024748,0.498325,0.347105,-0.318820,0.379770,-0.252052,0.004786,0.266108,0.047553,-0.148839,0.351419,-0.294729,-0.239559,0.061249,0.284182,-0.184754,0.479367,0.831499,-0.215629,-0.419091,0.175949,0.289006,0.017840,-0.056232,0.138918,0.491674,-0.119491,0.311304,0.306080,-0.444242,-0.074755,0.128368,0.074522,-0.604583,-0.201095,0.061399,0.079684,-0.483812,0.435197,-0.130000,-0.173530,-0.187708,-0.361232,0.227213,0.290636,0.212047,0.383581,-0.121268,-0.034251,-0.480308,-0.097338,0.552525,-0.111129,-0.162946,0.579923,-0.178753,-0.398461,-0.172195,0.103672,-0.315284,-0.146140,0.266517,0.156304,-0.228969,0.000912,-0.660968,-0.132802,-0.459445,-0.188759,-0.108197,-0.421978,-0.141528,-0.558071,-0.375446,-0.315171,-0.284880,0.063908,-0.102249,-0.237877,0.390475,-0.849454,0.137866,0.344196,0.099685,-0.544381,0.601912,0.027374,0.178301,-0.172847,-0.074684,0.317497,0.224172,0.315589,0.032763,0.561381,-0.022895,-0.330394,-0.720135,0.578069', '21619567', '1908318', '1296534', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301409', '杀出个黎明', '动作', '这部电影可以说娱乐价值十足。塞斯•杰科（乔治•克鲁尼 George Clooney 饰）恶贯满盈，被判刑多年；弟弟理查德（昆汀•塔伦蒂诺 Quentin Tarantino 饰）打通关节帮他成功越狱。为了能顺利逃往墨西哥，兄弟俩挟持了牧师一家人，一路上以他们作掩护。最终经过重重关卡，他们顺利逃到了墨西哥。到达墨西哥后，杰科兄弟联系上了当地的匪徒卡洛斯为他们打点一切，并约好在一家酒吧碰面。按计划杰科兄弟和卡洛斯接上头后就将释放牧师一家，似乎结局皆大欢喜。然而，他们在酒吧里等到入夜还没见到卡洛斯，等来的却是一大群僵尸！为了保命，他们只能和僵尸浴血奋战！©豆瓣', '乔治·克鲁尼', '罗伯特·罗德里格兹', 7.5, 59674, 'tt0116367', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1776544990.jpg', 1, 4.2, 30.8, 45.1, 19.1, '0.171163,-0.120183,-0.543783,0.244153,0.039958,-0.423552,0.405964,0.002339,-0.564640,-0.060155,0.061909,0.587645,-0.265098,-0.176151,0.205911,-0.120709,-0.669627,-0.541320,0.264269,-0.279868,-0.045206,-0.446149,-0.284547,-0.176357,-0.236772,-0.177988,0.296271,0.022327,0.370407,0.446529,0.178398,-0.073357,-0.178790,0.244050,-0.109014,0.103654,0.201894,-0.403101,-0.612982,0.490472,0.010041,-0.026496,-0.213119,-0.213268,0.366748,0.344101,0.529849,0.062901,0.138450,0.103745,-0.246735,-0.251043,0.187640,0.374807,0.304349,-0.182354,0.552264,0.234267,-0.260884,-0.148449,-0.204949,-0.150080,-0.634813,0.120878,-0.131327,-0.170932,-0.411040,0.393429,0.029646,0.046209,0.286608,-0.492000,0.272912,0.481397,0.426557,0.112105,0.187905,-0.132305,-0.489916,0.086760,0.801310,-0.349788,-0.013071,0.154472,0.284830,-0.366904,-0.001672,-0.093755,-0.149635,0.053619,0.653817,0.073670,-0.113551,-0.180382,-0.436441,-0.009191,-0.510848,-0.272515,-0.046813,-0.374024,0.384483,-0.867773,-0.057752,0.026129,-0.102591,0.379527,-0.042559,-0.089665,0.339417,-0.578779,0.109815,0.487341,0.512969,-0.308067,0.467228,-0.063266,0.293092,-0.031395,0.000536,-0.108534,0.234653,0.493243,0.534162,0.332207,0.052668,-0.156463,-0.132470,0.111319', '11541282', '3178770', '3147969', '1296339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301419', '极度恐慌', '剧情', '1967年，在非洲的扎伊尔莫他巴河谷，美国的雇佣军兵营中被一种突如其来的疾病肆虐，死亡人数不断攀升。军医抽取感染血样离开后，整个军营被炸弹摧毁，附近树林中的白脸猴发出阵阵惊叫声……直到90年代，一个美国年轻人在非洲扎伊尔捕捉到一只小白脸猴，并带回国出售。由于不合买主要求，年轻人将猴子放生，之后一种新型疾病在旧金山的香柏溪镇上蔓延。美国传染病研究所上校军医山姆（达斯汀·霍夫曼 Dustin Hoffman饰）接到消息，与妻子（蕾妮·罗素 Rene Russo 饰）及同事立刻展开研究和救治工作。由于疾病传染性极高，政府紧急出动军队封锁镇子，想要逃离者格杀勿论。此时，有一批保密的染毒血清被送来，但山姆等一群人研究发现，这批血清能救治1967年的疾病，却对如今变异后的病毒毫无作用。不久，山姆的妻子不幸被感染，生命垂危中时，政府也作出决定，准备投放炸弹摧毁整个镇子，以此消灭病毒。时间迫在眉睫，山姆查出了病毒的来源，他必须抢在投弹前找到原始病毒携带者。', '达斯汀·霍夫曼', '沃尔夫冈·彼德森', 7.7, 37995, 'tt0114069', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2517621832.jpg', 0.2, 1.5, 28.8, 52.5, 17, '0.041469,0.155975,-0.539346,0.245766,0.055701,0.232016,0.699399,-0.205632,-0.390517,-0.196169,-0.057457,0.329875,-0.072128,-0.039765,0.108536,-0.121145,-0.259164,-0.324378,-0.062049,-0.139883,-0.682464,-0.203568,-0.297319,-0.416291,0.017415,-0.647167,0.503303,0.114942,-0.317914,0.444662,-0.137877,0.634485,-0.153439,0.668015,-0.075974,-0.231876,0.256421,-0.524793,-0.214541,0.571110,0.240298,-0.168307,0.177046,-0.086829,-0.008615,0.445455,0.742684,-0.256541,-0.091424,-0.459330,0.237560,-0.272107,0.120980,0.055289,0.519839,0.096914,-0.055458,0.135909,-0.287748,0.010968,-0.025442,0.161372,-0.339976,-0.206544,0.060651,0.151997,-0.323759,-0.013431,0.000619,0.360851,-0.040411,-0.257673,0.340621,0.393683,0.020454,0.251946,-0.119150,0.104853,-0.660926,-0.026187,0.585910,-0.561377,-0.263706,-0.000242,-0.264760,-0.568163,0.209843,0.009574,-0.108032,0.036278,0.364763,0.059743,-0.365990,0.101166,-0.459020,-0.087984,-0.421688,-0.531320,-0.139047,0.089884,-0.259725,-0.898665,0.038959,0.098919,-0.180304,0.275121,0.260006,0.136960,0.538016,-0.350478,0.223070,0.504636,0.298651,-0.418530,0.077360,-0.409167,0.133286,-0.331853,-0.055101,0.249484,0.376416,0.529114,0.224090,0.258254,-0.100752,-0.276497,-0.277994,0.261947', '1298917', '1307897', '1306809', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301431', '与魔鬼同行', '剧情', '年幼的弗兰基与家人生活在北爱尔兰恬静的小岛上，慈善的爸爸教导他捕鱼，然而一天晚饭时分，一名蒙面歹徒竟然闯进来枪杀了他父亲，仅仅因为他父亲透露了同情爱尔兰共和军的倾向。长大后的弗兰基（布拉德·皮特 Brad Pitt 饰）成为了一名爱尔兰共和军神枪手，然而英军始终武力强大，因此弗兰基等人决定购买毒刺式导弹。五个月后，弗兰基隐藏了身份，同时被内线安排到了警察汤姆（哈里森·福特 Harrison Ford 饰）的家中暂时住下。一方面，富有魅力的他与汤姆一家人很快建立了友谊，并将大笔买金先藏于汤姆家中，一方面，弗兰基找到当地黑市军火商波克（特里特·威廉斯 Treat Williams 饰）购置导弹。然而军火商急于要钱，竟派蒙面人闯入汤姆家中，整个棋局全盘打乱，火力混乱之际，面对一边是身为警察的朋友，一边是爱尔兰的使命，弗兰基将如何选择……©豆瓣', '哈里森·福特', '艾伦·J·帕库拉', 6.7, 5656, 'tt0118972', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1144036657.jpg', 0.9, 8.8, 52.2, 30.5, 7.7, '0.237348,0.121456,-0.512298,0.382541,-0.292685,-0.191877,0.399641,0.152145,-0.562234,-0.300713,0.220459,0.630718,0.084295,0.223884,0.313792,0.014314,-0.400736,-0.565837,0.025714,-0.008317,-0.298389,-0.581581,-0.148757,-0.350233,-0.002665,-0.194153,0.406803,0.053191,0.100365,0.400659,0.131071,0.427849,-0.087512,0.398916,0.012930,-0.081501,0.324191,-0.459885,-0.361518,0.393212,-0.189814,-0.272891,-0.002977,0.204886,0.057594,0.419327,0.546226,-0.142256,0.000050,-0.244880,0.061431,-0.081948,0.064925,0.218763,0.220458,-0.053288,0.116518,0.200751,-0.163030,-0.028920,0.048127,-0.075717,-0.461959,0.152869,-0.079633,-0.150364,-0.533971,0.320880,-0.302825,0.011207,-0.071163,-0.244750,0.076909,0.247377,0.131709,0.139496,-0.139506,0.071062,-0.484174,-0.073929,0.511483,-0.202449,-0.051357,0.198753,-0.066428,-0.214999,0.085204,-0.277486,-0.261126,-0.142751,0.331951,0.122251,0.012321,0.045620,-0.466645,-0.022641,-0.464353,-0.123917,-0.063948,-0.374047,-0.051985,-0.660697,0.090471,-0.253826,-0.217139,-0.009848,0.185304,0.109105,0.669546,-0.539020,0.059077,0.570060,0.317530,-0.239073,0.255408,-0.095799,0.292837,-0.039257,-0.066602,0.202762,0.314450,0.180016,0.120769,0.033526,-0.155944,-0.179749,-0.053866,0.324772', '3811356', '3285622', '