INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301434', '夺宝奇兵2', '动作', '中国，印第安纳琼斯博士（Harrison Ford饰）与上海黑帮老大交易，对方在换得努尔哈赤的骨灰后便背信弃义，欲灭琼斯之口。关键时刻，机灵小鬼豆丁（Jonathan Ke Quan饰）救下琼斯博士和无故卷进的一位歌女威莉（Kate Capshaw饰）。由于三人乘坐的飞机失事，跳机后，乘着橡皮艇，他们竟漂流到了印度的一个村子。这里河水干涸，庄稼尽毁，饥荒横行，民不聊生。当地人将之归咎为彭高皇宫的妖孽作怪，并将“从天而降”的琼斯一行视为神灵的化身，他们请求琼斯帮他们拿回被掳走的圣石和所有的小孩子。魔宫果然充满古怪，统治者是个小屁孩，贵族们吃水蛭、巨蟒、甲虫、猴脑，皇宫内部更是机关重重，误打误撞间，他们目睹到血腥的邪教献祭仪式……这一仗注定艰苦异常！©豆瓣', '哈里森·福特', '史蒂文·斯皮尔伯格', 7.8, 52823, 'tt0087469', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1709116195.jpg', 0.5, 2.7, 25.8, 49.9, 21.2, '0.301241,0.036121,-0.452739,0.326930,-0.039372,-0.123948,0.675184,0.071857,-0.338095,-0.005633,0.277004,0.689440,-0.157993,-0.075580,0.237340,-0.028328,-0.239926,-0.478401,-0.353364,-0.160424,-0.333270,-0.137333,-0.214979,-0.051093,-0.181411,-0.153436,0.393352,0.182862,0.049721,0.357572,0.180643,0.384328,-0.322694,0.204637,-0.317642,0.014398,-0.052784,-0.063868,-0.087202,0.081667,-0.273133,-0.067841,0.028582,0.098573,-0.126312,0.168688,0.532090,-0.384291,0.068408,-0.600484,0.074910,-0.448244,-0.083771,0.134932,0.458734,-0.148862,0.042713,0.174582,0.040987,-0.160496,0.250359,0.042480,-0.429640,-0.001538,-0.029785,0.005961,-0.360115,0.123918,0.283321,0.094890,-0.023121,-0.270286,0.172746,0.172705,0.153889,0.300157,0.082600,-0.064209,-0.594017,0.069733,0.487882,-0.310444,-0.103387,-0.089890,0.050815,-0.462529,0.354189,-0.175201,-0.111857,-0.015673,0.463696,-0.136857,-0.133097,0.388652,-0.753427,-0.186597,-0.408698,-0.222417,0.044900,-0.161524,-0.221569,-0.640968,0.113489,-0.077601,-0.107211,0.160561,0.252760,0.234371,0.381433,-0.282451,0.301671,0.420476,-0.049834,-0.329676,0.244269,-0.227727,0.172978,-0.068490,-0.200090,0.059543,0.491571,0.502994,0.197629,0.258564,-0.118706,-0.074581,-0.335006,0.188192', '26290398', '1294917', '1856675', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301444', '太空牛仔', '惊悚', '21世纪初，一颗隶属于前苏联的卫星突然出现故障，随时可能坠毁于美国本土，这令美国太空总署（NASA）的大小官员分外紧张。NASA打算派出太空人前往外太空修复卫星，但是却没有找到任何通晓当年技术的技术人员。所谓病急乱投医，几个业已退休的老家伙就这样浮出水面。他们分别是弗兰克·柯文（克林特·伊斯特伍德 Clint Eastwood 饰）、霍克·霍金斯（汤米·李·琼斯 Tommy Lee Jones 饰）、杰瑞·奥尼尔（唐纳德·萨瑟兰 Donald Sutherland 饰）以及坦克·苏利文（詹姆斯·加纳 James Garner 饰）。在上世纪50年代，他们原本会是首批飞向太空的队员，却因为计划的调整而抱憾终生。如今，那颗捣乱的卫星终于能令他们一圆飞上太空的梦想……本片荣获2001年日本《电影旬报》最佳外语片奖、2001年日本每日电影最佳外语片奖。©豆瓣', '克林特·伊斯特伍德', '克林特·伊斯特伍德', 7.5, 6205, 'tt0186566', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p843916460.jpg', 0.5, 2.6, 33.9, 47.6, 15.4, '-0.058233,-0.132640,-0.700651,0.471853,0.203479,-0.371292,0.332232,-0.144243,-0.579068,-0.081858,0.031290,0.697074,-0.128503,-0.090333,0.022592,0.171866,-0.776080,-0.484160,-0.141286,-0.204733,-0.265806,-0.389383,-0.486770,-0.309758,-0.097763,-0.181810,0.861107,0.062553,0.025461,0.383974,0.055532,0.239099,0.095300,0.181845,0.035490,-0.142694,0.245650,-0.219502,-0.339983,0.265665,-0.257016,-0.175990,-0.050198,-0.022046,0.118651,0.459352,0.380498,0.021762,0.163085,-0.161346,0.246065,-0.276030,-0.065745,-0.239317,0.362512,-0.130996,-0.074891,-0.165001,0.090575,-0.125345,0.080776,-0.103784,-0.389190,0.135040,-0.060826,0.220144,-0.251342,0.030437,-0.512743,0.400844,-0.188385,-0.252252,0.291120,0.413103,0.249236,-0.000293,-0.151187,0.040411,-0.400123,0.487009,0.359961,-0.067761,-0.503605,0.118664,0.001719,-0.560898,-0.351530,-0.222979,-0.234679,-0.003506,0.413993,-0.101198,0.170491,0.179619,-0.283452,0.340873,-0.343620,-0.462904,-0.116229,-0.005128,0.144885,-1.057740,0.335014,-0.255959,-0.400129,0.074451,0.077964,-0.012116,0.589314,-0.401979,0.542179,0.600424,-0.024780,-0.173788,0.543786,-0.125163,-0.127467,-0.428660,-0.016715,0.276338,-0.139585,0.184561,-0.206609,0.168224,0.042211,-0.354113,0.053864,0.242072', '2075345', '1293572', '34961898', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301445', '黑衣人', '喜剧', '地球并不只是人类的天下，其实有1500名外星人生活中我们当中，而星际移民局则处理和外星人相关的事情。纽约普通警察爱德华兹（威尔·史密斯 饰）因缘际会之下加入了这一组织，成为MIB的一员，代号J，从此没有名字、没有身份，成为特警K（汤姆·李·琼斯 饰）的搭档。J应对的 第一起事件就是虫族的入侵。亚基伦王子罗斯伯在地球被虫族杀害，而他随身携带的“银河系”——宇宙次原子能源的最好来源也失踪了，若虫族找到，将给亚基伦人带来毁灭性的打击；亚基伦人发出最后通牒，如果地球人不能在一个小时之内交出“银河系”，他们就摧毁地球。为了地球的安全，K和J不得不挺身而出。©豆瓣', '威尔·史密斯', '巴里·索南菲尔德', 8.2, 316483, 'tt0119654', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453512941.jpg', 0.1, 0.9, 16.9, 51.7, 30.4, '0.122341,0.227122,-0.675779,0.808717,-0.256745,0.015949,0.556508,-0.377459,-0.254673,-0.480588,-0.136642,0.872468,0.214427,-0.129370,0.284217,0.264769,-0.342386,-0.527711,-0.143234,-0.444773,-0.651248,-0.650684,-0.416683,-0.751170,-0.018750,-0.272944,0.700374,0.120498,-0.462975,0.213082,0.035432,0.472493,0.052380,0.459609,-0.198507,-0.050212,0.012670,-0.101504,-0.528354,0.285523,-0.264597,0.059671,0.184838,0.525540,0.162499,0.138354,0.495417,-0.741280,0.303254,-0.449350,0.121241,-0.507581,-0.109815,-0.415654,0.627654,-0.340682,0.198328,0.275709,0.015062,-0.134759,0.307682,0.028502,-0.984726,0.013770,0.074409,0.028367,-0.198107,0.206660,-0.164715,0.155831,-0.002636,-0.029118,0.427416,0.538831,0.517402,0.179020,-0.091582,0.032676,-0.499054,-0.002804,0.657313,-0.024138,-0.407231,-0.100412,-0.358347,-0.744566,-0.233009,-0.535710,-0.220440,0.031319,0.245038,0.048024,-0.041434,0.466435,-0.574013,0.017630,-0.195482,-0.571116,0.164582,-0.385744,0.040172,-0.705505,0.010490,-0.068615,-0.328134,0.255097,0.191060,-0.073227,0.807602,-0.747522,0.239494,0.614315,0.564538,-0.677224,0.751949,0.154355,0.196690,-0.453231,0.030132,0.243327,0.319942,0.467026,-0.043210,0.056154,0.131043,-0.144232,-0.177356,0.399867', '25932086', '27009869', '3769423', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301447', '潜龙轰天', '动作', '美国历史上著名的密苏里号战列舰即将退役，盛大的庆典连总统也莅临。而老舰长的生日亦在这一天，舰上的厨师——雷白下士（史蒂文·席格 Steven Seagal 饰）正在全力筹备宴席，讨人嫌的副舰长奎尔与雷白发生冲突并将其关入冷藏室。一支劳军演艺队伍来到舰上，正当表演掀起高潮之际，劳军艺人们突然与奎尔同时行动，袭击船员并控制了密苏里号。“艺人”中的史崔尼（汤米·李·琼斯 Tommy Lee Jones 饰）原是中情局特工，精通舰只，他与奎尔合作，获得了舰上多枚携带核弹头的战斧导弹发射密码。军方被这一恐怖袭击彻底震惊，却又应对无法，此时从冷藏室逃出的雷白成为了他们唯一的希望……©豆瓣', '史蒂文·西格尔', '安德鲁·戴维斯', 7, 7514, 'tt0105690', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164764248.jpg', 0.8, 4.7, 46.8, 36.8, 10.9, '-0.035223,0.065091,-0.752370,0.501880,0.260779,-0.193521,0.777613,-0.012084,-0.284389,-0.184506,0.259631,0.731409,-0.143904,0.073496,0.554696,-0.125141,-0.360046,-0.641998,-0.290005,-0.113174,-0.289591,-0.439394,-0.202828,-0.299694,0.193809,-0.226177,0.603751,0.091200,-0.130015,0.540704,0.359312,0.172772,0.151234,0.642421,-0.007452,-0.167627,0.224557,-0.212470,-0.201936,-0.059358,-0.122924,-0.334787,0.028424,0.105261,0.284009,0.442855,0.618812,-0.457698,0.225352,-0.120458,-0.018628,-0.256933,0.123819,0.068819,0.264343,0.124318,-0.230070,-0.007256,-0.016941,0.147987,0.030448,-0.059206,-0.554369,0.042323,-0.162022,-0.061757,-0.173411,0.237302,-0.560831,0.341380,-0.220309,-0.050567,0.418077,0.489603,0.121836,0.173313,-0.187982,0.272786,-0.418999,0.275109,0.532957,0.030147,-0.312928,-0.069967,-0.004445,-0.575642,-0.133693,-0.309076,-0.100761,-0.217158,0.518086,0.079025,0.395643,0.231865,-0.576361,0.023922,-0.373786,-0.454912,0.001546,-0.044321,-0.008967,-1.027758,0.297174,-0.095179,-0.134919,0.186667,0.253118,-0.009673,0.609206,-0.608033,0.122617,0.184792,0.201809,-0.103560,0.600821,0.081702,0.256338,-0.211895,-0.086050,0.077425,0.099309,0.592093,0.002435,0.503789,0.072682,-0.386223,-0.070451,0.235389', '2159244', '10466639', '20274039', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301459', '小岛惊魂', '剧情', '二战结束，格蕾丝(尼科尔•基德曼)在英伦的小岛上独自抚养着一对儿女，耐心等待着丈夫从战场归来。儿女怕光，受到光照会发病，因此家里的窗帘常年拉得严严实实。就在这样一间阴暗的古宅里，格蕾丝迎来了三个新仆人。这三个人到来之后，却让格蕾丝寒了心——窗帘经常被拉开，门无故打开，钢琴自动发声，而她的女儿说，在房间里经常可以见到陌生男人。格蕾丝陷入了精神紧张的状态，她不明白怪事为何屡屡发生，不明白丈夫为何迟迟未归。而她最后才醒悟，所有的惊恐，其实都来源自身，但是事情已经不可逆转……©豆瓣', '妮可·基德曼', '亚历杭德罗·阿梅纳瓦尔', 8.2, 267333, 'tt0230600', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p492298664.jpg', 0.2, 1.2, 17.5, 50.9, 30.1, '0.034286,0.264781,-0.903858,0.325013,0.007313,-0.087232,0.669209,0.180202,-0.607949,-0.580780,0.080845,0.683914,-0.124155,0.515332,0.097547,0.252934,-0.365585,-0.581986,-0.293918,-0.184896,-0.554115,-0.072316,0.079608,-0.192634,0.007630,-0.358601,0.356286,0.067224,-0.102747,0.253180,0.266778,-0.102815,-0.154447,0.642988,0.080291,0.041266,0.116022,0.127930,-0.013423,0.116484,-0.089897,-0.364106,-0.343291,0.257830,-0.152640,0.225971,0.566702,-0.254465,-0.314700,0.099207,0.226860,-0.272624,-0.233916,0.252270,0.513451,0.070517,0.084334,0.086721,-0.354013,0.118033,0.123740,0.041422,-0.226557,0.232091,-0.206752,0.321764,-0.577748,0.448878,-0.163132,-0.247014,-0.001302,-0.287439,0.297602,0.276894,0.153931,0.420445,-0.347349,-0.053845,-0.548843,-0.271261,0.695687,-0.240372,-0.200332,0.614886,-0.200503,-0.369407,0.244774,-0.071104,-0.666050,-0.048589,0.386660,0.216076,-0.343146,0.220675,-0.183392,0.132242,-0.319968,-0.140990,-0.167294,-0.308525,-0.261868,-0.354975,-0.135227,-0.337455,-0.375328,0.369020,-0.343192,-0.133705,0.465762,-0.610231,0.499130,0.353759,0.144865,-0.280968,0.596586,-0.081905,0.382233,-0.139837,-0.063180,0.194445,0.059696,0.380648,0.292540,0.119297,-0.286426,0.118346,-0.314700,0.308387', '25870679', '1309125', '1292064', '2002683');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301464', '现代爱情故事', '剧情', '因为诈骗罪，约翰尼（阿尔·帕西诺 Al Pacino 饰）面临着为期一年半的牢狱之灾，出狱之后，无处可去的约翰尼被餐馆老板尼克（赫克托·埃里仲杜 Hector Elizondo 饰）收留，成为了一名厨师。餐馆的女侍应生弗兰基（米歇尔·菲佛 Michelle Pfeiffer 饰）吸引了约翰尼的目光，很快，约翰尼就对弗兰基展开了热烈的攻势。一次美妙的约会之后，约翰尼和弗兰基共度了充满了激情的一夜，可是，第二天，弗兰基冷淡的态度无疑是一盆冷水浇在了还处于甜蜜和幸福之中的约翰尼的头上。原来，弗兰基在上一段感情之中饱受伤害，痛苦的她为了自保封闭了内心。但约翰尼并没有就此而放弃，他的温柔和耐心终于打动了弗兰基，两人终成眷属。©豆瓣', '阿尔·帕西诺', '盖瑞·马歇尔', 7.9, 7200, 'tt0101912', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2160263007.jpg', 0.5, 2, 25.9, 46.1, 25.6, '0.172298,0.170483,-0.729507,0.466948,-0.154098,-0.352282,1.204780,0.198387,-0.382856,0.081328,0.119484,0.637311,-0.342463,0.393272,0.550359,0.119042,-0.390312,-0.893825,-0.228758,-0.161184,-0.318884,-0.569905,-0.052054,0.055078,-0.138550,-0.249137,0.384653,0.247176,-0.011916,0.680190,0.351752,0.156920,0.175333,0.786040,0.044693,0.052340,0.340288,-0.096816,-0.276492,0.476062,0.241429,-0.303532,-0.100816,0.202761,-0.099270,0.444348,0.568875,-0.287314,-0.293646,0.104240,0.180885,-0.361908,0.071622,0.363222,0.122165,-0.128976,0.245012,0.086055,-0.457427,0.000292,0.178196,-0.069673,-0.626651,0.098026,-0.032232,-0.004410,-0.568045,0.900835,0.039847,-0.120830,0.015795,-0.114342,-0.138326,0.121947,0.357952,0.576372,-0.228439,-0.064307,-0.343350,0.019813,0.629847,-0.053356,-0.216256,0.551966,-0.322926,-0.307614,0.092956,-0.204100,-0.597882,-0.146758,0.437071,0.280629,-0.064554,0.401277,-0.616423,-0.031664,-0.416666,-0.239978,-0.098330,-0.436508,-0.052247,-0.686640,-0.391793,-0.480083,-0.425148,0.065968,0.104820,-0.229376,0.625939,-0.691659,0.370172,0.421388,0.074670,0.068559,0.536534,0.169937,0.056397,0.063564,0.160075,0.548896,0.068852,0.269160,0.433738,0.553895,-0.019579,0.083099,-0.235260,0.705560', '21348112', '1309172', '2131640', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301465', '纯真年代', '剧情', '19世纪的纽约，上流阶层的人士有着一套自己的判断标准和生活规则，要求体面、得体。年轻律师纽伦（Daniel Day-Lewis 饰）也不例外，他将与门当户对的千金小姐梅（Winona Ryder 饰）订婚。然而在订婚前夕，他与梅的表姐、刚刚离婚自欧洲回到纽约的艾伦（米歇 尔·菲佛 Michelle Pfeiffer 饰）重逢，二人 一见如故，情愫顿生。然而艾伦的大胆行为和追求自我的作风是不被那个上流社会所接纳和允许的，在大家的眼中她是一个讨人厌的怪物。纽伦却意识到这种性格的可贵，并且被这种性格所折服，如果不能和所爱的人在一起，如果一生不是为自己而是为礼数为体面而活，人生将是多么的空虚和苍白。纽伦想和艾伦私奔，然而梅却怀孕了。虽然想追求属于自己的幸福，但是却同样不想伤害他人的这对爱人，最终选择了放手。纽伦和梅结婚了，脾气和顺的梅一直处于无辜的中心。然而直到梅的死去，他们才看见了事物的另一面……', '丹尼尔·戴-刘易斯', '马丁·斯科塞斯', 8.2, 54389, 'tt0106226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217023868.jpg', 0.3, 1.4, 18.5, 49.4, 30.4, '0.531586,0.153507,-0.796939,0.764308,-0.359767,-0.337556,0.777613,0.082154,-0.521947,-0.519074,-0.144431,1.003307,-0.135292,0.434684,0.266892,0.093764,0.020736,-0.702182,-0.084422,-0.018267,-0.197131,-0.604535,-0.000162,-0.287001,-0.177926,-0.134736,0.776766,0.383422,-0.306489,0.478677,0.409473,0.474950,0.078746,0.602978,-0.226496,-0.337063,-0.219451,0.168393,-0.408509,-0.077287,0.174169,-0.263170,0.063812,0.491141,0.042526,0.359192,0.579186,-0.435244,-0.242098,0.051224,0.478258,-0.399567,0.112908,0.407079,-0.051730,-0.364062,0.181017,0.256946,-0.093429,0.070021,0.019326,-0.274624,-0.959062,-0.058488,0.203846,0.047482,-0.716460,0.639073,-0.169548,-0.263910,-0.020476,-0.110540,0.320726,0.353489,0.199858,0.420420,-0.322306,0.008577,-0.659644,-0.078198,0.979961,0.223742,-0.281245,0.553304,-0.461953,-0.629162,-0.163804,-0.475598,-0.582954,-0.013668,-0.061491,0.335269,-0.181272,0.124881,-0.541180,-0.095685,-0.104682,0.120380,0.073945,-0.743791,0.007643,-0.182975,-0.275755,-0.932224,-0.585792,0.125013,-0.038813,-0.414721,0.701686,-1.104249,0.087177,0.354353,0.451885,-0.895024,1.021286,0.333886,0.056084,-0.222956,0.089811,0.416861,0.020572,-0.104133,0.075385,0.299473,0.108422,-0.023389,-0.206674,0.714167', '25721544', '1308805', '1303112', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301480', '金色豪门', '剧情', '根据伊莎贝尔·阿连德的小说《幽灵之家》改编而成。为了心爱的姑娘罗莎，青年埃斯特万（Jeremy Irons饰）离开首都，只身前往荒蛮之地开采金矿。两年后他成功地掘到“第一桶金”，此时却传来爱人罗莎误饮毒酒身亡的噩耗。埃斯特万悲痛万分，心灰意冷之下回老家接手父亲留下的农庄，在埃斯特万井井有条的管理下，农庄日益兴旺发达，他也成为闻名遐迩的农庄主。几年后，埃斯特万邂逅了克拉腊（Meryl Streep饰），克拉腊正是罗莎的小妹妹，她从小便暗恋埃斯特万，此时的克拉腊已出落得亭亭玉立，两人迅速坠入爱河，很快就喜结连理。克拉腊为埃斯特万诞下女儿布兰卡，一家人的生活其乐融融。可是，随着埃斯特万掌握的权力越来越大，他也变得越来越专制和乖戾，他无端怀疑自己的姐姐菲鲁拉（Glenn Close饰）对克拉腊有不轨之意，将其赶出家门；又不满布兰卡（Winona Ryder饰）和农工佩德罗（Antonio Banderas饰）交往，活生生将他俩拆散。夫与妻，父与女的感情开始产生裂痕，整个家庭摇摇欲坠。很快，时局动荡，埃斯特万一家的命运被卷入时代的漩涡中……', '梅丽尔·斯特里普', '比利·奥古斯特', 8, 6696, 'tt0107151', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2454690357.jpg', 0.5, 2.1, 20, 49.6, 27.8, '-0.133665,0.215069,-0.706230,0.302811,-0.094297,-0.277616,0.768603,0.299732,-0.486381,-0.026255,0.011894,0.729573,-0.259395,0.012622,0.502306,0.167173,-0.182863,-0.627195,-0.058935,-0.368151,0.203692,-0.370958,-0.201058,0.108571,-0.238950,-0.359806,0.372520,0.173330,0.069947,0.332897,0.082844,0.514535,-0.122803,0.287492,-0.162600,0.175638,-0.010469,-0.051649,-0.211351,0.012505,-0.205778,0.096579,-0.015701,-0.056809,0.072946,0.300499,0.487740,-0.264211,0.008969,-0.377885,0.374519,0.188685,-0.088915,0.132431,0.160061,-0.182482,0.254179,0.152212,-0.592875,-0.162724,0.218520,-0.182051,-0.327809,0.148784,0.195363,0.017396,-0.644006,-0.003098,-0.013155,-0.092996,0.074442,-0.308684,-0.077435,0.434426,0.244005,0.426799,-0.385735,-0.132170,-0.417494,0.049167,0.543582,-0.046277,-0.198434,0.002147,0.012638,-0.235036,0.100856,-0.123275,-0.405488,-0.229820,0.500127,0.072158,0.209261,0.720000,-0.640478,-0.126202,-0.499304,-0.237483,0.165142,-0.291277,0.025441,-0.408909,-0.196406,-0.141132,-0.223357,0.023668,0.174755,-0.213162,0.400991,-0.336710,0.425400,0.084962,0.358556,-0.506517,0.241244,-0.011955,0.354001,-0.200709,-0.076788,0.553152,0.198026,0.189903,0.003995,0.263503,-0.113211,-0.069174,-0.270002,0.511059', '1292528', '1300958', '25723780', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301498', '地球之夜', '剧情', '本片由五个发生在同一时间，不同国家地区的小故事组成，每个故事都描述了的士司机与乘客的一次短暂遭遇。洛杉矶晚上7:07，假小子司机柯基（薇诺娜·瑞德 Winona Ryder 饰）载着她的客人维多利亚（吉娜·罗兰兹 Gena Rowlands 饰）回酒店，恰巧负责电影选角的维多利亚看中了柯基，然而柯基却告诉她自己想成为一名机械师……纽约晚上10:07，黑人青年尤尤终于拦到了一辆的士，却发现司机是一名根本不会开车且语言不通的外国老人赫尔穆特（阿明·缪勒-斯塔尔 Armin Mueller-Stahl 饰），尤尤只好主动提出由他来开车……巴黎凌晨4:07，年轻的黑人司机把两名出言侮辱他的非洲乘客撵下车后，上来了一位美貌的盲女（碧翠斯·黛尔 Béatrice Dalle 饰），他立即对她产生了好奇与怜悯，却发现她比自己更能在这世界上辨明方向。……本片由贾木许自编、自导、自制而成，他在大约八天内完成了剧本创作，各个故事发生的地点则根据他想合作的演员而定。电影原声带则来自于他的老拍档民谣大师Tom Waits。', '吉娜·罗兰兹', '吉姆·贾木许', 8.2, 47187, 'tt0102536', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p957052935.jpg', 0.2, 1.3, 15.6, 51.6, 31.3, '0.269656,0.120702,-0.668180,0.462355,0.002505,-0.262119,0.740982,-0.081534,-0.285610,-0.326685,0.319439,0.779839,-0.074955,0.258393,0.547638,-0.009353,-0.471424,-0.341232,-0.026763,-0.156524,-0.268478,-0.359555,-0.131702,-0.068082,0.029571,-0.146747,0.245952,-0.256518,-0.172707,0.318403,0.450682,0.161702,-0.080540,0.314381,-0.054644,0.161653,0.173837,-0.261218,-0.092393,0.155062,0.037158,-0.284151,-0.183428,-0.097273,-0.059834,0.361749,0.534736,-0.033126,-0.195581,0.002980,0.329405,-0.016570,0.120605,-0.227122,0.210423,0.125062,0.205785,0.053109,-0.040878,0.104914,0.038307,0.165622,-0.364035,0.364527,-0.089928,0.212058,-0.548155,0.335485,-0.261526,-0.140921,0.002038,-0.559611,0.128849,0.039638,0.152592,0.195608,0.142359,-0.081408,-0.425992,0.166974,0.624296,0.329118,-0.146526,0.358773,-0.093969,-0.439811,-0.108734,-0.009468,-0.450453,0.120947,0.322769,-0.157940,-0.148002,-0.128500,-0.370123,-0.201028,-0.181928,-0.308499,-0.071896,-0.160802,0.097089,-0.840236,0.235674,-0.280610,-0.080997,-0.017447,0.148042,0.085142,0.686973,-0.543971,0.124676,0.534720,0.366724,-0.461830,0.711094,-0.144451,0.150540,-0.310012,0.005408,0.190040,0.088343,0.351086,0.074202,0.426235,-0.134742,-0.183439,-0.421205,0.249397', '1306860', '1829654', '10466639', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301509', '修女也疯狂', '喜剧', '夜总会女二流歌手迪劳丽丝（胡比•戈德堡）因意外目睹一桩谋杀被黑帮头目追杀，为逃脱杀手追击，她求助于警方，警方为保护她这个现场证人，安排她躲进世界上最安全的地方——一所修女院。修女院沉寂冷清的生活令一向好动的迪劳丽丝难以忍受，遂晚上趁人不备跑出去唱歌跳舞，院长（玛吉·史密斯）担心她出事，将她安排到唱诗班里，她又嫌唱诗班异常糟糕，决定动手改造，于是在做弥撒时，唱诗班高唱起流行歌曲，不过歌词改成了赞美天主，谁想，此举竟受到教友的热烈欢迎，并引来教宗的专程前来欣赏。如此好玩的新闻，电视台岂肯放过？可是电视上一曝光，迪劳丽丝也被宣告要再次逃命。©豆瓣', '乌比·戈德堡', '埃米利·阿朵里诺', 8.2, 106012, 'tt0105417', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461439892.jpg', 0.1, 0.8, 17.8, 53.7, 27.5, '0.396552,0.037035,-0.569494,0.182161,0.042318,0.094719,0.620051,0.120338,-0.503099,-0.348409,0.265423,0.583319,-0.225634,0.063976,0.367931,-0.079820,-0.341133,-0.413484,0.053768,-0.057068,-0.006954,-0.138274,0.187998,-0.321750,-0.129640,-0.146119,0.193804,0.205234,-0.357150,0.308926,0.340386,0.160445,-0.028989,0.394523,0.181282,-0.120609,0.123492,-0.049500,0.226424,0.251331,-0.054719,-0.314637,-0.116914,0.195006,0.148432,0.242976,0.401760,-0.080038,-0.179852,-0.234635,0.279374,-0.491716,0.119688,0.203970,0.353621,-0.078474,0.075108,0.060598,-0.230317,0.064171,-0.165478,-0.110750,-0.540717,0.374466,0.198670,-0.090674,-0.412970,0.101826,-0.172582,0.087929,-0.108278,-0.160784,0.381020,0.084348,0.239180,0.121048,0.139588,0.136874,-0.316725,0.109924,0.703329,-0.093877,0.090768,-0.100672,-0.053974,-0.336630,0.241739,-0.338609,-0.386573,0.071089,0.113306,-0.267273,0.043646,-0.079090,-0.122720,-0.300645,-0.370245,-0.189152,-0.132335,-0.400809,-0.115792,-0.656369,0.182603,0.533505,-0.069317,-0.091862,-0.035087,-0.188784,0.482940,-0.562825,0.263598,0.612713,0.250628,-0.528333,0.519013,0.050799,0.238287,0.036255,-0.238253,0.273289,0.370153,0.294976,-0.041611,-0.027416,-0.105860,-0.512681,-0.260049,-0.054502', '25721544', '1309116', '3326747', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301516', '艳娃传', '剧情', '故事发生在新奥尔良的一家妓院里，一战将近，时局动荡不安，惟独在这所妓院里，一切都如往常一样井然有序的行进着。12岁的紫罗兰（波姬·小丝 Brooke Shields 饰）与母亲海蒂（苏珊·萨兰登 Susan Sarandon 饰）和弟弟相依为命，对她来说，最近唯一的大事就是自己即将要进行拍卖的童贞。作为妓院御用的摄影师，贝洛克（基思·卡拉丹 Keith Carradine 饰）显得和开放的大环境有些格格不入，他的目光，一直都落在年幼而美艳的紫罗兰身上。不久之后，海蒂勾搭上了一个有钱人，随即带着儿子离开了妓院，紫罗兰成为了被抛弃的那一个。在紫罗兰走投无路的时候，贝洛克收留了她，两人开始了同居的生活，可是紫罗兰乖僻的性格让贝洛克无法忍受，这段感情最终以分手告终。然而，此时的两人并不知道的是，这只是他们漫长情感纠葛的开始。©豆瓣', '基思·卡拉丹', '路易·马勒', 7.4, 6127, 'tt0078111', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1487763551.jpg', 1.1, 4, 36.7, 42.9, 15.4, '0.479025,0.124594,-0.892535,0.703137,-0.214966,-0.249994,0.949141,0.222436,-0.673652,-0.355674,0.160839,1.009643,-0.330910,0.499284,0.234467,0.276116,-0.240732,-0.722025,-0.288326,-0.382429,-0.236309,-0.498361,-0.117162,-0.050818,-0.147806,-0.196390,0.549281,0.174404,-0.080782,0.613446,0.481401,0.093710,0.013206,0.405296,-0.334991,-0.008895,0.065296,0.175918,-0.202432,0.137604,0.000715,-0.217750,-0.089651,0.164803,0.090049,0.411083,0.606769,-0.348357,-0.047425,0.002947,0.334958,-0.198883,-0.183698,0.276666,0.309016,-0.127307,0.131144,0.131979,-0.437055,0.055414,0.145091,-0.181895,-0.682949,0.123600,-0.024441,0.258058,-0.882150,0.768550,0.059933,-0.161325,0.207214,-0.300312,0.263333,0.376959,0.162944,0.460223,-0.229567,-0.091333,-0.708787,0.085851,0.925962,0.179365,-0.360359,0.623040,-0.374361,-0.342704,-0.208099,-0.251117,-0.467597,-0.116689,0.149366,0.134135,-0.240258,0.424884,-0.615165,0.159031,0.004534,-0.208322,-0.032039,-0.456751,-0.191458,-0.589715,-0.292237,-1.042701,-0.501442,0.152934,-0.019868,-0.151211,0.640478,-0.920813,0.133240,0.401823,0.292974,-0.557220,0.683172,0.316233,0.240318,-0.048315,-0.153819,0.266569,-0.062235,0.242563,0.238045,0.423483,-0.048436,0.012150,-0.498774,0.698001', '3111650', '25721544', '30162520', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301535', '桃色交易', '剧情', '戴维（伍迪·哈里森 Woody Harrelso 饰）和黛安娜（黛米·摩尔 Demi Moor 饰）是一对感情很好的夫妻，两人事业成功，生活幸福，但经济萧条的到来使两人工作每况愈下，甚至连住房都无法操持。他们不甘以失败，下决心去赌城一搏。开始时，他们运气极好，但很快，两人就输光了所有的钱。这时，一位年老英俊的百万富翁盖奇（罗伯特·雷德福 Robert Redfor 饰）提出帮他们，但条件是用100万换取与黛安娜共度一夜，终于，金钱的诱惑力战胜了一切，夫妇两人立下了字据，做了桃色交易。两人回到家中约定永不提此事，但事与愿违，两人感情出现裂痕。这时，盖奇又进入了他们的生活，热烈地追求，戴维一气之下离家出走。最终这一对曾经的爱人是否能够既往不咎？而百万富翁究竟是真心爱着戴安娜，还是另有其他目的？©豆瓣', '罗伯特·雷德福', '阿德里安·莱恩', 7.4, 17894, 'tt0107211', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p949548990.jpg', 0.6, 3.8, 35.7, 43.8, 16.1, '-0.045463,-0.083227,-0.568994,0.334216,-0.169614,-0.579711,0.633325,0.133627,-0.475377,-0.314594,0.057023,0.892922,-0.068923,0.164411,0.129510,-0.017823,-0.352038,-0.706746,0.277194,-0.181224,0.037818,-0.568104,-0.078540,-0.284979,-0.357705,-0.044635,0.622993,0.174705,0.075986,0.479915,0.366911,0.096523,-0.067513,0.375296,-0.198053,-0.161185,-0.046628,0.115526,-0.683834,0.135125,0.010338,0.020532,-0.231227,0.227129,0.143990,0.373298,0.394025,-0.111788,-0.322025,0.052690,0.193955,-0.197133,-0.067728,0.353209,0.044471,0.045603,0.363671,0.319022,-0.312578,-0.290545,0.021290,-0.085336,-0.630405,0.030247,0.011702,0.020174,-0.611680,0.401415,0.008660,-0.062099,-0.043118,-0.212350,0.142574,0.487762,0.418534,0.145029,-0.204967,-0.104614,-0.648043,-0.000805,0.879018,0.099143,-0.153865,0.459852,-0.199301,-0.434387,-0.127226,-0.076631,-0.378574,0.104047,0.240210,0.357624,0.136866,0.158297,-0.632870,-0.039565,-0.260242,0.020517,0.083070,-0.588346,0.219851,-0.575495,-0.302061,-0.502520,-0.629411,0.089413,0.041723,-0.321918,0.643030,-0.738712,-0.055044,0.013957,0.343121,-0.728073,0.669336,0.233114,0.297578,-0.145342,0.138052,0.255073,-0.220131,-0.101420,0.174478,-0.033172,0.086750,0.170393,-0.178303,0.436213', '25721544', '4301278', '1949320', '3215099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301536', '红字', '剧情', '故事发生在17世纪。赫丝特（黛米·摩尔 Demi Moore 饰）离开丈夫，孤身一人来到马萨诸塞湾的英属殖民地定居。在这里开拓的英国人信仰坚定，恪守清规，赫丝特的一些举动在这压抑的殖民地环境下颇为引人注目。当地的牧师阿瑟（加里·奥德曼 Gary Oldman 饰）英俊而富有激情，赫丝特为他的神采深深吸引，两个性情相投的人很快陷入了危险的热恋。不久殖民地方面接到了赫丝特的医生丈夫被印第安人杀害的消息，本以为可以公开关系的一对恋人等到的却是东窗事发，赫丝特为保护阿瑟，拒绝供认通奸者，自此被投入监狱直至产下一名女婴，而阿瑟则在监狱外日日承受心灵的拷问……出狱后的赫丝特戴上了通奸者的耻辱标志，同时她大难不死的丈夫突然现身，誓要将通奸者揪出以发泄心中怒火……©豆瓣', '黛米·摩尔', '罗兰·约菲', 7.4, 6516, 'tt0114345', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2492755250.jpg', 0.8, 3.8, 36.3, 44.2, 14.9, '0.204435,0.138283,-0.600453,0.507171,-0.050950,-0.164233,0.820598,0.230392,-0.567985,-0.073660,0.229645,0.737176,-0.231026,0.247441,0.364468,0.023759,-0.358506,-0.546385,-0.122151,-0.250404,-0.120914,-0.343682,-0.060171,-0.262415,-0.071943,-0.544089,0.668799,0.086623,-0.153955,0.372828,0.144072,0.448449,-0.045210,0.260179,-0.223828,-0.089560,0.128569,-0.185858,-0.356625,0.154616,-0.060163,-0.185467,0.132036,0.151765,-0.213479,0.307550,0.697367,-0.233418,-0.066905,-0.183525,0.363444,-0.073767,0.017827,0.277170,0.314004,-0.134958,0.063240,0.278230,-0.305637,-0.045737,0.147384,-0.052901,-0.542826,0.010558,0.129589,0.159774,-0.218480,0.379806,-0.037553,0.057442,0.019801,-0.107490,0.109683,0.281666,0.049055,0.509680,-0.082799,0.245593,-0.411766,-0.056891,0.585305,-0.323173,-0.167618,0.011997,-0.247355,-0.435046,0.185904,-0.239156,-0.353770,-0.216343,0.486539,-0.009603,-0.144095,0.273986,-0.490968,-0.132739,-0.287219,-0.040823,0.094200,-0.332164,-0.262937,-0.560781,-0.202513,-0.220819,-0.187325,0.135021,0.291768,0.022051,0.491811,-0.632386,0.371113,0.473734,0.239582,-0.626035,0.438770,0.066375,0.232785,-0.280217,0.000770,0.662460,0.224442,0.230706,0.033104,0.147710,-0.329114,0.162150,-0.350752,0.379227', '25721544', '1296992', '1292528', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301538', '钟楼怪人', '剧情', '在巴黎傲然耸立的钟楼内，住着一位钟楼怪人——加西莫多。加西莫多自从出生起，就被邪恶的主人浮罗洛一直囚禁在钟楼内。钟楼里的生活暗无天日，幸好加西莫多结识了不少好朋友，才为他单调乏味的生活增添了一丝亮色。加西莫多总是热切的渴望着到外面的世界去一探究竟，终于，一个改变加西莫多命运的愚人节到来了。这日，他邂逅了美丽了吉普赛姑娘爱丝美拉达，他深深爱上了她。于是，加西莫多决定运用他的智慧与正义，战胜浮罗洛，为自己迎来新生。©豆瓣', '汤姆·休斯克', '加里·特洛斯达勒', 7.7, 9024, 'tt0116583', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2553730090.jpg', 0.4, 2.3, 27.8, 48.7, 20.9, '-0.056854,0.254221,-0.743424,0.595349,-0.342862,-0.353994,1.007798,-0.072402,-0.132734,-0.172375,0.210681,0.664192,-0.159248,0.705913,0.433842,0.405918,-0.343300,-0.472456,-0.054920,-0.333725,-0.173935,-0.283395,-0.598732,-0.008445,0.104018,-0.323685,0.552588,0.300061,0.017860,0.323155,0.233038,0.043960,-0.132402,0.584784,-0.457134,0.075303,0.059693,0.079393,-0.155002,0.248351,0.010615,-0.351040,-0.166107,0.257481,-0.337015,-0.062882,0.679353,-0.529262,-0.186802,-0.187851,0.333751,0.027161,0.025101,0.259488,0.281150,0.127027,-0.151630,0.392000,-0.390468,0.282341,-0.132278,-0.255436,-0.627642,0.044411,-0.078547,-0.013173,-0.661200,0.626108,0.098850,-0.380034,0.068483,-0.366292,0.221336,0.052709,0.062400,0.499274,-0.293846,0.030030,-0.433604,0.000895,0.693334,0.026986,-0.154912,0.324355,-0.181551,-0.312239,0.088305,-0.064096,-0.675790,-0.142848,0.332846,0.033677,-0.215663,0.348489,-0.675400,0.045927,-0.333970,-0.006783,0.048657,-0.489659,-0.096357,-0.371027,-0.296631,-0.042341,-0.190545,0.029707,-0.078920,-0.376169,0.721503,-0.990165,0.481192,0.638349,0.370393,-0.278721,0.655281,0.056993,0.190358,-0.007508,-0.081568,0.532821,-0.257374,0.526091,0.052899,0.508620,-0.213456,0.022454,-0.479857,0.801272', '21619567', '1428054', '1302133', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301547', '生死豪情', '动作', '海湾战争中，坦克部队军官沙林（丹泽尔•华盛顿 Denzel Washington 饰）一次判断失误下令击毁了己军的坦克，令到好友鲍德温意外死亡了。虽然军事法庭判他不需承担责任，然而他还是日夜受着良心的煎熬，一直想找鲍德温的父母说明此事，却也一直没有勇气。上司为了给沙林授勋，派他调查战争中一起机械师勇救士兵牺牲的事件。沙林调查中发现勇救士兵而英勇牺牲的竟然是卡伦（梅格•瑞安 Meg Ryan 饰）竟然是个女人！但现场的几名士兵的供词自相矛盾、漏洞百出。在沙林对其中一名士兵墨菲逼问后，墨菲竟然自杀了。随着墨菲的自杀，事件的真相慢慢浮出水面……©豆瓣', '丹泽尔·华盛顿', '爱德华·兹威克', 7.6, 7777, 'tt0115956', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2498225355.jpg', 0.4, 2, 30.1, 50.6, 17, '0.032769,-0.224993,-0.620928,0.592923,-0.194755,-0.208780,0.864133,-0.271348,-0.651760,-0.191122,0.507175,0.475830,0.072446,-0.087124,0.308405,-0.076878,-0.555020,-0.675927,-0.074491,-0.151590,-0.307459,-0.570249,-0.301496,-0.565215,0.065931,-0.266578,0.672735,0.283425,-0.104238,0.376862,0.409544,0.327943,0.035366,0.555259,0.277070,0.015657,0.311119,-0.310393,-0.091208,0.000592,0.039386,-0.438279,-0.228569,0.271210,-0.057814,0.540251,0.467686,-0.468460,-0.090173,-0.266261,0.037382,-0.464118,0.332657,0.088989,0.353203,0.100362,0.290847,0.193653,0.067414,-0.147700,0.067271,0.344803,-0.632185,-0.032246,-0.005226,0.239118,-0.450783,0.307852,-0.372435,0.175644,0.065675,0.049285,0.055802,0.243749,0.417857,0.187249,-0.512062,-0.184534,-0.409001,0.118061,0.528165,-0.145539,-0.243367,-0.098560,-0.194163,-0.419252,0.173718,-0.168241,-0.327239,0.153775,0.099505,-0.090681,-0.156997,0.270966,-0.146099,-0.160758,-0.744112,-0.248493,-0.465140,-0.150214,-0.075427,-0.490891,0.085345,-0.051950,-0.374146,0.087084,0.021154,0.176944,0.467028,-0.420277,0.128795,0.604826,0.175430,-0.541994,0.303315,0.393292,-0.066563,-0.010948,0.082532,0.170596,0.000007,0.217185,0.283342,0.191845,0.161475,-0.457752,-0.094318,0.252678', '4132395', '1920730', '4724373', '4023433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301562', '少年阿虎', '剧情', '温柔美丽的韩藉华侨金美娇（金贤珠饰）为逃避感情创伤，只身来到香港。希望过一段安静生活的美娇，碰巧受到前大学同学的邀请，当上大学暑假班韩文教师。第一堂课上，她便遇上了反叛不羁的学生于建邦（吴建豪饰）。这个沉默寡言、在课堂上一直打瞌睡的学生，并没有给美娇留下好印象，两人互相敌对对方。慢慢地，美娇开始对这个执着并倔强的男孩有了好感，建邦对于拳击的热爱也深深感染了美娇，两人竟渐渐产生了微妙的爱的感觉。建邦一直梦想能与顶级拳手阿TANK（安志杰饰）在擂台上一决高下，便开始努力争取出赛资格。然而一波三折，建邦圆梦无望。与此同时，美娇的旧情人来到香港，她竟要重回旧情人的怀抱。©豆瓣', '吴建豪', '李仁港', 6, 6534, 'tt0378773', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2359392505.jpg', 3.3, 17.8, 57.8, 15.6, 5.5, '0.442061,0.101017,-0.715166,0.564716,0.063984,-0.488989,0.639502,0.260104,-0.715447,0.043075,0.354055,0.678529,-0.124212,0.339614,0.234402,-0.083417,-0.243898,-0.806804,0.088373,-0.049961,-0.072306,-0.424108,-0.170886,0.239841,-0.206116,-0.246137,0.553414,-0.166846,-0.093550,1.023813,0.034721,0.152363,0.213867,0.529954,-0.063052,0.014678,0.036211,0.187992,-0.579219,-0.078122,-0.044611,-0.239676,-0.193421,-0.061914,-0.001057,0.180582,0.815127,0.101363,-0.238657,0.016800,0.267839,-0.093356,-0.228344,0.220484,0.162822,0.213254,0.374618,0.282537,0.090758,-0.021639,-0.109354,-0.027019,-0.299439,0.139937,0.120197,0.355610,-0.367095,0.974607,-0.125474,-0.155965,0.047450,-0.253835,-0.051743,0.105928,0.134433,0.373254,-0.400491,0.144304,-0.031256,0.128240,0.615241,0.059346,-0.359867,0.365850,-0.079417,-0.382003,0.119792,-0.163265,-0.447234,0.022913,0.033605,0.180810,-0.180567,0.180153,-0.616891,0.314427,-0.019121,0.124848,0.185007,-0.389381,-0.059693,-0.462976,-0.258247,-0.269557,-0.407405,0.113253,-0.012190,-0.231224,0.775586,-1.083890,0.430502,0.542520,0.553057,-0.316000,0.646271,0.376121,-0.105311,-0.153765,-0.305033,0.233358,-0.579709,0.418901,-0.070341,0.428554,-0.180249,-0.056053,-0.196281,0.397192', '35030151', '1292219', '3139191', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301566', '蠢蛋搞怪秀', '喜剧', '约翰尼·诺克斯维尔和一班朋友们是疯狂的恶作剧爱好者。他们是无畏的先锋，用身体躯冲撞吊顶电风扇、冲撞铁护栏、冲撞仙人掌；他们是天生的美食家，用鼻子吸成团的芥末、吃自己尿做成的冰激凌；他们是正宗的混球，用鳄鱼和鞭炮和突如其来的抢衣服对待家人、把租来的汽车撞成一堆废铁后还回去、在五金店的待售坐便中拉屎；他们是勇敢的斗士，和女格斗选手对阵结果被击溃、和“四回合拳王”奶油豆在商场里对战结果被殴打的头破血流；他们是旅行家，在日本的街头大跳风骚之舞、身穿熊猫衣和路人打成一片；他们是易容高手，化装成老人或者胖子继续恶作剧……©豆瓣', '约翰尼·诺克斯维尔', '杰夫·特里梅因', 7.7, 10231, 'tt0322802', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1337958344.jpg', 3.3, 6.1, 24.1, 33.4, 33.1, '0.362670,-0.323687,-0.345199,0.148946,-0.418940,0.077752,0.684609,0.246109,-0.172113,0.264723,0.429656,0.759763,-0.487114,0.019965,0.053805,-0.084892,0.003027,-0.815499,-0.170014,0.100642,-0.444110,-0.152298,-0.173986,-0.233978,0.142123,-0.121728,0.422252,-0.318517,-0.339289,0.383777,0.593689,0.057080,-0.117304,0.198251,-0.502072,0.094789,-0.057660,-0.259242,0.131766,0.028514,-0.408743,-0.216058,0.070522,-0.176623,0.152642,0.198724,0.532095,-0.309682,0.143175,-0.262071,-0.248335,-0.285602,-0.158878,0.327815,0.369187,-0.090319,0.425768,-0.264022,0.297237,0.081006,0.371179,0.129801,-0.436286,-0.008851,-0.109972,0.003108,-0.903685,0.654331,0.015834,-0.062962,0.172085,-0.091308,0.400633,-0.223619,0.062181,0.511009,0.158870,-0.175870,-0.780130,0.150215,0.503729,0.154524,-0.113706,-0.026851,-0.123292,-0.030510,0.030920,-0.592641,-0.213820,-0.251710,0.461661,-0.163980,-0.282250,-0.102094,-0.823351,0.040858,-0.129466,-0.281951,0.015561,-0.188104,-0.298558,-0.701644,0.160042,-0.599148,-0.116223,0.079314,0.236848,-0.163763,0.772567,-0.576189,-0.114357,0.363661,0.195274,-0.043292,0.517347,-0.202402,-0.206045,0.214452,-0.103878,-0.350615,0.273974,0.253748,0.513095,0.892147,-0.088650,0.162124,-0.352294,0.431145', '30162520', '1394176', '1401905', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301576', '留住有情人', '剧情', '一次偶然中，希拉里（朱莉娅·罗伯茨 Julia Roberts 饰）得到了一份看护的工作，她所要看护的对象是一位名叫维克托（坎贝尔·斯科特 Campbell Scott 饰）的百万富翁。维克托患上了白血病，需要接受化疗，在希拉里的精心看护下，他的病情渐渐好转，两人之间亦产生了深厚的感情。一日，维克托突然将希拉里带到了位于海边的小镇上，两人在那里度过一段幸福而温馨的时光。好景不长，卷土重来的病痛让维克托陷入了痛苦中，而他为了隐瞒病情竟然开始偷偷注射吗啡止痛。希拉里发现了维克托的秘密，伤心的她恳求他继续接受治疗，没想到后者断然拒绝。难道病魔真的要将这对心心相印的情人残忍的分开吗？©豆瓣', '朱莉娅·罗伯茨', '乔·舒马赫', 7.8, 6450, 'tt0101787', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177813445.jpg', 0.3, 2.7, 28.2, 44.7, 24.1, '0.127072,0.129229,-0.556674,0.570709,-0.252183,-0.279696,0.885389,0.039720,-0.467147,-0.224897,0.142786,0.619399,-0.222174,0.326540,0.218526,0.154748,-0.323332,-0.625489,0.038424,0.010569,-0.469671,-0.564388,-0.436997,-0.322682,-0.038931,-0.408775,0.412528,0.146356,0.111964,0.370620,0.191478,0.390613,0.133384,0.512526,-0.000285,0.089171,0.130643,-0.029813,-0.247598,0.391738,0.539808,-0.441899,0.090020,0.331506,-0.038839,0.403935,0.604915,-0.084997,-0.308218,-0.023060,0.250189,-0.205485,0.142658,0.166417,0.050649,0.065064,0.152902,0.108241,-0.633831,-0.089574,0.034894,0.112318,-0.651207,0.066110,-0.017099,0.153826,-0.559763,0.554646,-0.131466,0.011112,0.056813,-0.384164,0.061689,0.626736,0.339950,0.429514,-0.326220,-0.102181,-0.250238,0.087631,0.676907,-0.101638,-0.239961,0.540260,-0.327018,-0.346817,0.280357,-0.147026,-0.434914,-0.060500,0.461784,0.133680,-0.236459,0.230757,-0.338508,-0.121753,-0.438231,-0.135830,-0.187915,-0.240604,0.089727,-0.548202,-0.093279,-0.202699,-0.386944,-0.102743,-0.009752,-0.526983,0.475129,-0.687168,0.545401,0.522161,0.131039,-0.459789,0.435467,0.212769,0.316111,-0.112737,-0.056795,0.537817,-0.057290,0.174669,0.413251,0.326236,-0.084752,0.286332,-0.507366,0.400609', '1428054', '1309172', '1292217', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301578', '十一罗汉', '惊悚', '丹尼奥逊（乔治-克鲁尼饰,George Clooney饰）是刚从监狱假释出来的大盗，马上又操起了老本行，这次他的目标是为了盗取赌城富豪泰瑞（安迪•加西亚 Andy Garcia 饰）的一亿五千万金钱。泰瑞来头不小，于是丹尼精挑细选了11个高手前来助阵——有扑克天才拉提斯 （布拉德•皮特 Brad Pitt 饰）、爆破专家、扒手大王、杂技演员。精密的盗窃计划开始了。拉提斯却发现了一个秘密，丹尼的前妻竟然和泰瑞有着不寻常的关系。泰瑞举行一个拳击比赛，那一亿五千万就是比赛的奖金。行动就安排在那一晚，拉斯维加斯的夜晚因为这次周密的盗窃计划波澜起伏。©豆瓣', '乔治·克鲁尼', '史蒂文·索德伯格', 7.9, 176732, 'tt0240772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1973370351.jpg', 0.2, 1.3, 22.8, 54.2, 21.6, '0.147155,0.021855,-0.406257,0.495779,-0.206666,-0.343595,0.652906,0.181262,-0.197621,-0.249763,0.462087,0.685374,-0.362542,-0.354761,0.334045,0.237810,-0.517413,-0.590199,0.003706,-0.211804,-0.288346,-0.413062,-0.256588,-0.279559,0.262797,-0.272831,0.289014,-0.185084,-0.082873,0.413311,0.500089,0.251281,0.150168,0.196252,-0.025493,-0.039588,0.559643,-0.046980,-0.208251,0.488952,-0.045325,-0.012809,-0.192405,0.060005,0.291017,0.664185,0.232611,-0.055571,0.212657,0.094215,0.095360,-0.162979,-0.119487,-0.116023,0.371437,-0.188079,0.051127,0.156317,-0.178669,0.050766,0.238480,-0.294387,-0.846089,0.026945,0.285662,0.187040,-0.388124,0.296058,-0.422451,0.184216,-0.146299,-0.153970,-0.010966,0.442521,0.151163,0.079008,0.390232,-0.041826,-0.674524,0.281613,0.264860,-0.216729,0.067494,0.401107,-0.087592,-0.618440,-0.018583,-0.137912,-0.209014,-0.073986,0.686543,-0.326593,0.008926,0.094815,-0.553637,-0.162539,-0.304767,-0.073807,-0.093921,-0.293275,-0.021642,-0.579691,0.005430,-0.181795,-0.424574,0.015443,0.198134,-0.082904,0.424034,-0.591918,-0.009681,0.836635,-0.092071,-0.117674,0.427600,-0.133284,-0.105698,-0.258575,-0.214268,-0.164355,0.155360,0.404391,0.056713,0.521796,0.402437,-0.679304,-0.267879,0.532501', '1307442', '1300324', '3785918', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301582', '苦月亮', '剧情', '奈杰尔（休•格兰特 Hugh Grant 饰）陷入了七年之痒的婚姻中。他和妻子菲奥纳（克里斯汀•斯科特•托马斯 Kristin Scott Thomas饰）决定乘坐游轮前往印度旅游，尝试改变糟糕的关系。船上，他遇见了瘫痪作家奥斯卡（彼德•考约特 Peter Coyote 饰）和他的美艳妻子咪咪（埃玛纽埃尔•塞纳 Emmanuelle Seigner饰）。奥斯卡似乎要把他和咪咪之间的异常关系告诉陌生人奈杰尔。奥斯卡认识咪咪之初，两人爱得死去活来，情欲之火熊熊燃烧。然而咪咪摄人的魅力只让奥斯卡着迷了一段不长的时间。他开始厌倦，尽管咪咪为了他堕胎、割除子宫、对他一往情深，奥斯卡还是残忍的把她支走。一场车祸后，躺在医院的奥斯卡却赫然发现，咪咪就站在他的病床前，怒不可遏的把他拖下病床，奥斯卡终身残废。他们继续生活在一处。咪咪从来没停止过对奥斯卡的虐待，二人却还相爱。当咪咪遇上菲奥纳，心中燃起了奇妙的爱火，二人相拥而舞。最后，奥斯卡却对着咪咪扣下了扳机。', '彼德·考约特', '罗曼·波兰斯基', 8.4, 112169, 'tt0104779', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p700187064.jpg', 0.3, 1.2, 14, 45.3, 39.2, '0.232747,0.089357,-0.789410,0.366765,-0.151083,-0.230713,1.072996,0.011611,-0.426693,0.297743,0.155965,0.728577,-0.559255,0.290073,0.092239,0.360366,-0.317345,-0.990268,0.062620,0.226289,-0.182542,-0.485700,-0.301344,0.175086,-0.118257,-0.151904,0.499569,-0.146275,0.085437,0.713004,0.231405,-0.041167,0.091819,0.518549,-0.119507,0.303351,0.255667,-0.003220,-0.207512,0.200221,0.446865,-0.263997,-0.085882,0.237185,-0.083426,0.232537,0.510576,-0.295689,-0.119842,-0.140504,0.102014,-0.250990,-0.075390,0.396665,0.132709,-0.045515,0.150903,0.298451,-0.136731,-0.056681,0.277890,0.252033,-0.412875,0.362526,-0.236317,0.239971,-0.608153,0.557475,-0.296300,0.078902,0.193447,-0.037394,0.253131,0.236535,0.093723,0.211122,-0.315624,0.015730,-0.419394,0.070445,0.455359,-0.105179,-0.157159,0.604966,-0.095521,-0.353963,-0.070661,0.079311,-0.400191,-0.132631,0.457421,-0.029036,-0.191915,0.064030,-0.345177,0.089986,-0.224787,-0.082414,-0.212793,-0.291187,-0.053597,-0.348276,-0.169079,-0.444868,-0.462479,0.196823,-0.125369,-0.301029,0.325814,-0.528476,0.174870,0.398364,0.468805,-0.219546,0.793067,0.270801,0.044251,-0.101157,0.001487,0.578874,-0.328456,0.209004,0.365745,0.389815,0.146933,0.251805,-0.459245,0.727666', '1292211', '21348112', '3111650', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301601', '不道德的审判', '剧情', '波利娜（西格妮·韦弗 Sigourney Weaver饰）曾经被一个男子施暴，被蒙着眼的她一直不知道罪人是谁，她的性格也变得神经兮兮。她的丈夫杰拉多（斯图尔特·威尔逊 Stuart Wilson饰）当选委员会主席后回到家中，就发现波利娜有着一些比平时更怪异的举动。她甚至把前来拜访的邻居米兰达（本·金斯利 Ben Kingsley饰）的车子推落山崖，凭着米兰达车里的磁带“死亡和处女”，以及米兰达的气味和呼吸，波利娜坚信，米兰达就是当时对她施暴的元凶。她发了疯似的把米兰达绑在房间，要和丈夫一起审判这个罪犯。然而，米兰达分明有着确凿的不在场证据，这令丈夫也难以相信波利娜的认定。这一切是波利娜的幻觉，还是确有其事，这场审判会令真相一一浮出水面。©豆瓣', '西格妮·韦弗', '罗曼·波兰斯基', 8.2, 13627, 'tt0109579', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2583381880.jpg', 0.5, 1.4, 16.4, 51.4, 30.4, '0.409908,-0.225338,-0.704222,0.599333,-0.117971,-0.055401,0.801053,0.086747,-0.440790,-0.360226,0.066972,0.893193,-0.367742,0.324145,0.169634,0.495186,-0.601460,-0.705328,-0.006951,-0.226427,-0.152145,-0.741023,-0.108235,-0.306681,0.086254,-0.285264,0.366865,-0.171578,-0.081007,0.373025,0.498651,0.210271,0.271065,0.575253,-0.058196,0.031532,0.021507,-0.409925,0.137038,-0.187192,0.186336,-0.119361,-0.059506,0.319450,0.076333,0.301246,0.456909,-0.439029,-0.054725,-0.206113,0.344224,-0.571599,0.298112,0.237537,0.328498,-0.317425,0.102392,0.315280,-0.150585,-0.109637,0.510604,0.015989,-0.731527,0.279212,0.078846,0.205807,-0.546345,0.217447,-0.226161,0.124189,0.132694,-0.027961,0.320710,0.218215,0.150589,0.161084,-0.165282,-0.245488,-0.709340,-0.289049,0.481190,0.090719,-0.019258,0.394423,-0.317833,-0.541473,-0.224116,-0.019926,-0.482690,0.166202,0.298837,0.098366,-0.208160,0.154880,-0.240663,-0.359178,-0.427670,-0.207035,-0.198068,-0.540387,-0.291861,-0.372469,-0.382724,-0.465275,-0.371928,-0.099912,-0.012413,-0.249066,0.417364,-0.702982,0.057792,0.466032,0.240278,-0.346210,0.431616,0.268478,-0.010880,-0.026185,-0.179265,0.357431,0.326583,0.132600,0.198545,0.357718,0.138166,0.120558,-0.067834,0.588875', '1293145', '1783461', '3119246', '30344474');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301616', '丈夫、太太与情人', '剧情', '作为两对相处了十余年的朋友，莎利（朱迪·戴维斯 Judy Davis 饰）和杰克（西德尼·波拉克 Sydney Pollack 饰）之间的和平分手让加贝（伍迪·艾伦 Woody Allen 饰）和朱迪（米亚·法罗 Mia Farrow 饰）夫妇感到不可思议。当看见杰克迅速的另结新欢之后，原本心平气和的萨利感到怒不可遏，为了安抚朋友受伤的感情，朱迪将自己的同事麦克尔（连姆·尼森 Liam Neeson 饰）介绍给了她，后者对萨利的狂热却让朱迪的内心里很不是滋味。另一边，才华横溢的学生雷恩（朱丽叶特·刘易斯 Juliette Lewis 饰）吸引了作为老师的加贝的注意，尽管想在婚姻中保持忠诚，但他向往雷恩的心却像一列火车般无法回头。同时，和新欢相处并不愉快的杰克发现自己对旧爱念念不舍，而此时的萨利正和麦克尔打得火热。就是这样四个在职场上春风得意的成年人，他们的感情生活却是一团糟。导演伍迪·艾伦运用大量的对话探讨了夫妻和男女之间感情的始末，将现代人的情感和生活状态描绘的淋漓尽致。', '伍迪·艾伦', '伍迪·艾伦', 8.3, 8956, 'tt0104466', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2182919863.jpg', 0.2, 1.2, 14.1, 51.5, 32.9, '0.523277,-0.201689,-0.640838,0.539458,-0.055523,-0.468240,0.970827,0.143716,-0.542266,-0.209431,-0.058466,0.729471,-0.395269,0.256806,0.263123,0.087702,-0.418127,-0.887540,-0.143769,0.024720,-0.038982,-0.670356,-0.287004,-0.122533,-0.369664,-0.301622,0.444895,-0.301662,-0.019757,0.814585,0.166713,0.376159,0.136773,0.393472,0.017150,0.027258,0.157032,-0.027276,-0.503094,-0.184178,0.143731,0.143314,0.025848,0.409707,0.021523,0.429876,0.540343,-0.277400,-0.099150,0.113500,0.162168,-0.134088,0.159479,0.155551,0.031148,0.051105,0.244451,0.063452,-0.241466,-0.066867,0.038980,0.104000,-0.789403,0.228677,0.074914,0.319224,-0.588899,0.682965,-0.108637,-0.244369,0.356177,-0.188194,0.216093,0.290026,0.379908,0.525165,-0.248357,0.003552,-0.196435,-0.013102,0.631011,0.146072,-0.185843,0.588075,-0.564844,-0.278085,-0.055683,-0.010519,-0.451884,-0.247800,0.126854,0.235958,0.091810,0.375841,-0.496522,0.002655,-0.152810,0.073857,-0.184585,-0.827095,0.162363,-0.614822,-0.325365,-0.899900,-0.401264,-0.083855,0.007849,-0.252199,0.687807,-0.889979,-0.079503,0.289953,0.281199,-0.248267,0.653941,0.384232,0.004261,-0.294753,-0.002221,0.408398,0.008353,-0.074113,0.183397,0.549538,0.080278,-0.024579,-0.346132,0.620829', '24756472', '25837574', '3111650', '2161696');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301617', '不一样的天空', '剧情', '因为不能面对丈夫自杀的事实，吉伯特(约翰尼·德普 饰)的母亲不停进食，致使体重剧增至六百磅，难以行动。吉伯特的智障弟弟阿尼(莱昂纳多·迪卡普里奥 饰)一出生就被医生诊断活不过十岁，却即将过十八岁生日，最小的妹妹爱伦却正值叛逆的青春期。整个家庭的生计及阿尼的日常起居成了吉伯特的生活全部，姐姐是他唯一的帮手。四处旅游、活泼开朗的贝琪(朱丽叶特·刘易斯 饰)路过小镇，与吉伯特一见钟情，两人很快沉浸在甜蜜的爱情中。贝琪对生活的热情也让吉伯特渐渐认识到，除了家人，生命中他也该有属于自己的追求。阿尼就要过十八岁生日了，这是母亲最后的心愿，待这一切结束，吉伯特能有一个不一样的天空吧。©豆瓣', '约翰尼·德普', '拉斯·霍尔斯道姆', 8.6, 136313, 'tt0108550', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2175712032.jpg', 0.1, 0.6, 10.3, 45, 44.1, '0.240979,-0.349544,-0.615980,0.396387,-0.220325,-0.512321,0.844398,0.146745,-0.582251,-0.394729,-0.080323,0.750493,-0.137691,0.516711,0.349632,0.146649,-0.229612,-0.406804,-0.065077,-0.110511,-0.261891,-0.393917,0.017719,-0.057676,-0.101714,-0.343368,0.417009,-0.400240,0.242050,0.403030,0.283378,0.383165,0.180989,0.414421,-0.232675,0.123193,0.028381,-0.229372,-0.252724,0.181213,-0.050066,0.070387,0.046717,0.213822,0.112944,0.357667,0.711571,-0.287211,-0.049394,-0.086294,0.282643,-0.133202,-0.113745,0.251258,0.141420,-0.286278,0.381684,0.067887,-0.016548,0.081347,-0.044870,-0.375803,-0.647385,-0.105333,0.095980,0.136050,-0.558500,0.276063,-0.146284,-0.375279,0.272808,-0.273905,0.071294,0.559057,-0.028605,0.592660,-0.354430,-0.286344,-0.553448,0.254208,0.576217,0.052275,-0.389305,0.665739,-0.515062,-0.345790,0.214950,-0.209597,-0.532590,0.044817,0.051336,0.130147,-0.068695,0.449370,-0.391116,-0.065864,-0.334620,-0.300999,0.012178,-0.315696,-0.114558,-0.215496,-0.148180,-0.514474,-0.373300,0.144768,0.038452,-0.223130,0.527561,-0.876357,0.420751,0.535869,0.240655,-0.179922,0.501580,0.315157,0.194630,-0.257667,0.047231,0.442035,-0.163796,0.122163,0.065253,0.356510,0.249098,-0.124860,-0.379671,0.683331', '1292062', '1309172', '4275444', '4301215');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301630', '惊声尖叫', '惊悚', '锡德尼•普雷斯科特（内芙•坎贝尔饰）的母亲去世一周年，这个本该平静的加州小镇变成了一片血海！两名学生被残忍地杀害，凶手是一位带着面具的恐怖片爱好者。警方将锡德尼的男友比尔•卢米斯（斯基特•乌尔里奇饰）定为嫌疑犯，并予以逮捕。但这时又有命案发生！神出鬼没的面具凶手仿佛死神般带走一个又一个生命，但凶手的真面目却无人知晓。夜幕降临，凶手将锡德尼身边的人一个个杀害，而被害人只能在被害前惊声尖叫。谁能够从凶手的刀下躲过，谁能揭开凶手的面具呢？©豆瓣', '内芙·坎贝尔', '韦斯·克雷文', 7.1, 48742, 'tt0117571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166895812.jpg', 1, 5, 41.8, 40.8, 11.5, '0.321161,0.016301,-0.416185,0.681406,-0.369870,-0.168737,1.101734,-0.065802,-0.216444,-0.433008,0.439682,0.871878,-0.145892,0.300252,-0.028915,0.324155,-0.196420,-0.732127,-0.137269,-0.461988,-0.461707,-0.320623,-0.313204,-0.202170,0.111850,0.089959,0.366854,0.211119,0.106476,0.321224,0.772139,0.452909,-0.297263,0.339653,-0.235711,-0.152588,0.130677,-0.381678,0.000924,0.461414,-0.095530,-0.281481,-0.227990,0.330724,-0.521503,0.258567,0.758753,-0.139438,0.014715,-0.128033,0.476484,-0.549997,0.205885,0.409310,0.532781,-0.228374,-0.062061,0.394316,-0.235900,-0.136103,0.240427,-0.078134,-0.731752,0.131388,-0.034182,0.329598,-0.326441,-0.070287,-0.331324,0.146918,0.004286,-0.121827,0.351067,0.102068,0.158391,0.414895,-0.130307,-0.155248,-0.844129,0.046862,0.311503,-0.318338,-0.390311,-0.026268,-0.100398,-0.459849,-0.144904,-0.181191,-0.371294,0.218126,0.628290,-0.009234,-0.429702,0.401810,-0.391976,-0.171494,-0.729753,0.134559,-0.517622,-0.306057,-0.482804,-0.402494,-0.160603,-0.089045,-0.288504,0.076905,-0.034766,-0.219985,0.353642,-0.402346,0.278347,0.433121,-0.094402,-0.158480,0.217730,0.297933,0.073677,0.027603,-0.308653,0.385244,0.827871,0.404468,0.131344,0.256991,-0.070567,-0.090589,-0.282169,0.137451', '1578663', '1293976', '2988294', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301646', '瑟堡的雨伞', '剧情', '17岁的少女Geneviève（凯瑟琳·德纳芙 Catherine Deneuve 饰）是法国瑟堡一家雨伞店老板娘的女儿；20岁的少年Guy（尼诺·卡斯泰尔诺沃 Nino Castelnuovo 饰）是一家汽车修理店的员工，和他的伯母和伯母的养女Madeleine (Ellen Farner 饰演)生活在一起。 Geneviève和Guy是一对情侣，然而他们的恋情一直受到Geneviève母亲的阻挠。阿尔及利亚战争爆发了，Guy被迫要去前线服两年兵役。离别前一夜，两人发生了关系。分开的日子里，Geneviève很少收到Guy寄来的信，她开始怀疑他的真心。在母亲的撮合下，怀有身孕的她嫁给了一个一直对她穷追不舍的巴黎珠宝商 Roland Cassard (Marc Michel 饰演)。两年后，服完兵役的Guy回到瑟堡，想要寻回他和Geneviève的爱情，却发现一切早已物是人非......本片被提名37届奥斯卡最佳外语片、获1964年戛纳电影节“金棕榈”奖殊荣。本片所有的对白都是“唱”出来的，配乐也十分出色。', '凯瑟琳·德纳芙', '雅克·德米', 7.8, 11580, 'tt0058450', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377633842.jpg', 0.4, 2.2, 25.5, 50.2, 21.7, '0.065947,-0.123780,-0.627030,0.546773,-0.110265,-0.254376,0.836877,-0.051690,-0.577215,-0.178799,0.156520,1.058109,-0.361036,0.303189,0.376714,0.150129,-0.183772,-0.803072,0.080038,-0.264552,0.019231,-0.301869,-0.119653,0.052872,-0.228682,-0.356932,0.674355,-0.001307,0.231779,0.733486,0.600156,-0.034434,-0.020876,0.362073,-0.251827,0.188705,0.069825,0.090650,-0.410044,0.380872,0.133695,-0.282323,-0.331097,0.112021,0.213707,0.236481,0.567950,0.124734,-0.079074,0.147214,0.541794,-0.238327,-0.005359,0.144172,0.539450,0.002027,0.362527,0.357830,-0.377170,-0.050655,-0.047373,-0.110057,-0.422951,0.046055,0.220704,0.075675,-0.814212,0.646431,-0.139976,0.109814,-0.046764,-0.287636,0.208706,0.399311,-0.118688,0.384848,-0.237015,-0.038937,-0.714496,0.290594,0.828125,-0.229932,-0.319054,0.397217,-0.107124,-0.406054,-0.173799,-0.254578,-0.740163,0.225096,0.179404,-0.096641,-0.135315,0.001445,-0.508870,-0.047754,-0.211905,-0.333944,0.172963,-0.307242,0.071105,-0.590594,-0.208392,-0.700576,-0.390920,0.018877,0.069839,-0.302664,0.563428,-0.816107,0.256948,0.310374,0.323920,-0.460939,0.845101,0.257825,0.182813,-0.139636,-0.067056,0.260182,-0.270757,-0.