INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301647', '冷血惊魂', '剧情', '从布鲁塞尔来到伦敦的卡萝尔（凯瑟琳·德纳芙 Catherine Deneuve 饰）是当地一家美容沙龙的员工。在这个光怪陆离的大都会，青春美丽的卡萝尔竭力压抑自己心中躁动的欲望，由此她表现出些许的焦虑和神经质。虽然有年轻帅气的小伙子柯林（John Fraser 饰）锲而不舍地追求，但卡萝尔更愿意和姐姐海伦（Yvonne Furneaux 饰）厮守在一起。相较于容易紧张的妹妹，海伦似乎颇为适应这个社会，她与一名有妇之夫相恋，两人相约利用假期去意大利旅行。然而，海伦的离开却让卡萝尔的精神接近崩溃边缘，无可挽回的悲剧由此上演……本片荣获1965年柏林国际电影节银熊奖评委会特别奖和国际影评人费比西奖。©豆瓣', '凯瑟琳·德纳芙', '罗曼·波兰斯基', 7.7, 6992, 'tt0059646', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1093961660.jpg', 1, 3.1, 25.5, 50.5, 20, '0.145630,0.114906,-0.890793,0.467147,0.114390,-0.355574,0.865159,0.175569,-0.310311,-0.093117,0.111010,0.851205,-0.437082,0.326466,0.452544,0.038991,-0.367549,-0.656328,0.118664,-0.097145,0.228054,-0.357763,-0.411726,-0.083441,-0.375759,-0.309617,0.664866,0.244944,-0.158586,0.932467,0.430770,0.156912,0.011798,0.524572,-0.095514,-0.221592,0.188920,-0.040604,-0.352805,0.055157,0.319401,-0.185858,-0.278007,0.042647,0.184451,0.281210,0.552643,-0.057710,-0.177934,0.295865,0.635335,-0.226689,-0.010069,0.207122,-0.119283,-0.085208,0.015246,-0.086820,-0.350312,0.160893,0.112324,-0.092146,-0.543633,0.438253,0.283868,0.104030,-0.608232,0.497741,0.046206,-0.101811,0.038865,-0.255227,0.072197,0.363636,0.109576,0.453482,0.020411,0.351139,-0.414476,0.045705,0.637914,0.141401,-0.427572,0.275344,-0.388531,-0.480311,-0.130014,-0.276568,-0.589177,-0.078210,0.194076,-0.120666,0.064321,0.278595,-0.755571,0.113614,-0.198827,-0.104832,-0.059943,-0.228498,-0.104555,-0.709077,-0.195523,-0.520329,-0.249541,-0.189423,0.096292,-0.228792,0.812694,-0.903025,0.159014,0.619101,0.501981,-0.429153,0.630201,0.232590,-0.023896,-0.130060,-0.423884,0.389479,-0.441815,0.161993,-0.140052,0.514042,-0.041350,0.048274,-0.524179,0.410287', '3811356', '3111650', '5977789', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301676', '呼啸山庄', '剧情', '阴云密布的旷野荒原，一位身披斗篷的孤独女人行走其间。她缓缓地讲述着一个关于爱与复仇的故事。19世纪，英国约克郡。呼啸山庄的主人恩萧先生带回了一个男孩，并取名为希斯克利夫。几年后，希斯克利夫（拉尔夫·费因斯 Ralph Fiennes饰）便长成了一位英俊少年。恩萧的女儿凯瑟琳（朱丽叶·比诺什 Juliette Binoche饰）一下子就迷上了这个沉默寡言、我行我素的男孩。然而恩萧先生对希斯克利夫的宠爱，却让恩萧的儿子亨德雷（杰瑞米·诺森 Jeremy Northam饰）异常嫉妒。一次意外，让凯瑟琳邂逅了贵族埃德加·林顿（西蒙·谢普德 Simon Shepherd饰）。面对粗俗的希斯克利夫和优雅的林顿家人，凯瑟琳还是嫁给了埃德加。希斯克利夫一怒之下愤然离去。几年后，衣锦还乡的希斯克利夫展开了疯狂地复仇。本片改编自英国女作家勃朗特姐妹之一艾米莉·勃朗特的同名作品，著名影星朱丽叶·比诺什和拉尔夫·费因斯首度合作演绎这段经典旷世爱情故事。', '朱丽叶·比诺什', '彼得·考斯明斯金', 7.4, 15643, 'tt0104181', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2440663005.jpg', 0.8, 4.4, 37, 41.7, 16.1, '-0.003313,-0.015242,-0.447355,0.839987,0.065583,-0.597293,0.774539,0.042184,-0.202951,-0.262042,0.020546,0.860196,-0.259987,0.256183,0.483595,0.532721,-0.315774,-0.516471,-0.202538,-0.085469,-0.268560,-0.612211,-0.126585,-0.327309,-0.019665,-0.360230,0.405736,0.069996,-0.053327,0.526646,0.450740,0.309004,-0.081339,0.280251,-0.157080,0.067268,0.279318,0.095667,-0.248049,0.060312,0.080583,-0.047456,-0.225275,0.228567,-0.053835,0.172016,0.632759,-0.281255,0.184091,-0.104955,0.313376,-0.057810,0.040287,-0.135671,0.254448,-0.270664,0.096903,0.330272,-0.041208,-0.296072,-0.017559,-0.315007,-0.277991,0.056307,0.094934,0.062184,-0.548141,0.588779,-0.079878,0.001527,0.030396,-0.064035,-0.007677,0.039550,0.368456,0.358316,0.128737,0.240827,-0.246932,0.374111,0.306269,0.259273,-0.471456,0.486962,-0.353517,-0.376771,-0.099732,0.107396,-0.781393,0.096332,0.439919,-0.340911,-0.036265,0.522853,-0.432207,-0.437013,-0.547213,0.197285,0.074551,-0.383802,-0.125179,-0.512157,-0.112055,-0.448037,-0.086645,-0.038159,0.030324,-0.013706,0.798274,-0.551592,0.297549,0.295906,0.093757,-0.165911,0.417140,0.140201,0.189688,-0.131597,-0.068872,0.732459,-0.052967,-0.377470,0.352805,0.459855,-0.004619,-0.009671,-0.329458,0.613679', '26348103', '35161768', '1460341', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301678', '坏血', '剧情', '这部电影将写实与科幻合而为一。一种传染性性疾病STBO正在国内蔓延，它通过没有感情的性活动传播。小偷马克和汉斯欠一个美国女人一笔钱，她限他们两个星期还。他们打算去偷一种专治类似艾滋病的药剂，然后高价转卖。于是他们雇来了亚力克斯，一个正在跟16岁女友丽莎分手的青年。但在计划实施之前，他迷恋上了马克的情妇安娜。丽莎却并没有死心，在他们动手那天她来到了巴黎，使得事情更加复杂化……当然，这是个悲剧。Love that burns fast but lasts forever.这是导演Leos Carax继《男孩遇见女孩》后的第二部作品，继续他对青春和孤独等题材的关注，也就是在此片的五年之后诞生了影史经典之作——《新桥恋人》。', '米歇尔·皮科利', '莱奥·卡拉克斯', 8.2, 12112, 'tt0091497', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2161797753.jpg', 0.4, 2.2, 17.9, 46.2, 33.3, '0.243536,-0.076417,-0.541935,0.581424,-0.145686,-0.270971,0.823448,-0.024653,-0.300239,-0.186827,0.055606,0.901374,-0.234739,0.136179,0.131192,0.120697,-0.525798,-0.598637,0.187923,-0.207452,-0.127644,-0.362083,-0.080500,-0.144747,-0.094878,-0.172355,0.672589,-0.090567,-0.293379,0.491564,0.207221,0.018353,0.051945,0.558909,-0.146848,0.158921,0.101259,-0.129982,-0.338606,0.487735,0.418231,-0.174390,-0.109181,0.197446,-0.026041,0.267191,0.673127,-0.161457,-0.147911,-0.025224,0.357034,-0.242562,-0.242752,0.107977,0.063676,-0.101811,0.452054,0.229087,-0.221366,-0.028414,-0.012798,-0.143235,-0.677147,0.055551,-0.147816,0.136141,-0.516873,0.427587,-0.172435,0.010070,0.068055,-0.311612,0.108212,0.389652,0.327764,0.304547,-0.163174,-0.020421,-0.564898,0.390952,0.615099,0.033976,-0.302873,0.702753,-0.146817,-0.508467,-0.329606,-0.054298,-0.524147,0.140198,0.426184,-0.103938,-0.289928,-0.024056,-0.767680,0.041541,-0.193312,-0.220831,0.005646,-0.260128,-0.007788,-0.596215,-0.262595,-0.247620,-0.293743,-0.074773,0.175862,-0.375768,0.550377,-0.590288,0.270588,0.691993,0.490625,-0.644452,0.625741,0.147376,-0.087849,-0.374846,-0.271524,0.154440,-0.152520,0.337325,0.084638,0.379732,0.339716,-0.044719,-0.249840,0.660578', '30162520', '34890458', '24733428', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301679', '屋顶上的轻骑兵', '剧情', '十九世纪中期，意大利正处在奥匈帝国水深火热的统治中。为了解放祖国，轻骑兵上教安吉罗（奥利维•马丁内兹 Olivier Martinez 饰）密谋发动暴动推翻殖民统治，然而却因计划外漏而不得不流亡法国。因为儿时好友的出卖，安吉罗在法国受到了奥地利间谍的追杀。逃亡中的安吉罗无意闯进了法国的一个瘟疫区，那里哀鸿遍野，人们近乎疯狂。当地人认为是安吉罗投的毒药，安吉罗无端又成了追捕的对象。一天，安吉罗无意中从屋顶掉到了一间阁楼里，偶遇了与丈夫失散了的女子宝林娜（朱丽叶•比诺什 Juliette Binoche 饰）。得知宝林娜现在处境艰难时，安吉罗决心帮助她找回她的丈夫。当他们在疫区穿行时，宝林娜不幸身染疫症……©豆瓣', '朱丽叶·比诺什', '让-保罗·拉佩诺', 7.9, 15743, 'tt0113362', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2238214320.jpg', 0.2, 1.6, 24.2, 50.3, 23.6, '0.201503,0.044830,-0.676736,0.691884,0.109803,-0.467848,0.703994,0.331267,-0.558437,-0.298238,0.262278,0.442082,-0.201781,0.215518,0.586086,0.104606,-0.468280,-0.602270,0.188650,-0.364581,-0.373283,-0.457252,-0.311411,-0.449548,-0.318500,-0.349390,0.454951,0.326773,-0.367974,0.312909,0.253836,0.714423,-0.175405,0.610509,0.114319,0.221026,0.323857,-0.348873,-0.343607,0.297134,0.002261,-0.374566,-0.099296,0.310922,0.106295,0.450936,0.791354,-0.599094,0.487008,-0.424663,0.394213,-0.154473,0.117927,0.208104,0.449180,-0.225780,0.070198,-0.238036,-0.081906,0.044595,0.217919,-0.238668,-0.543851,-0.061030,0.137102,-0.107006,-0.478062,0.176438,0.079648,0.482894,0.340349,-0.042662,0.220920,0.721126,0.332978,0.360803,-0.101656,0.001625,-0.696949,0.011380,0.707348,-0.119344,-0.097182,0.184470,-0.259295,-0.427755,0.244545,-0.187713,-0.595696,-0.133064,0.534328,-0.161420,-0.070073,0.567422,-0.331904,-0.270992,-0.521026,-0.094603,0.016419,0.004957,0.031579,-0.459706,-0.212273,-0.369427,0.058707,-0.043642,-0.506407,0.012480,0.484902,-0.707385,0.362676,0.521383,0.356582,-0.177105,0.435302,0.004929,0.400725,-0.054451,-0.069506,0.601627,0.221129,0.183355,0.292905,0.118852,-0.166062,0.099877,-0.210039,0.341932', '1301022', '1307311', '27042738', '1300958');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301686', '天使在人间', '喜剧', '某个庄园内，正在举行一场豪华派对，以庆祝吉姆·桑德斯（麦克·E·奈特 Michael E. Knight 饰）和佩蒂·温斯顿（菲比·凯茨 Phoebe Cates 饰）的订婚仪式。派对最高潮时，吉姆的好友化装成劫匪将其绑架，一同去参加他们的单身汉聚会。狐朋狗友聚在一起，自然是酒色财气、昏天黑地。正在吉姆醉酒酣睡之时，屋外的泳池传来巨大响动，继而发现一个长着翅膀的美丽女孩（艾曼纽·贝阿 Emmanuelle Béart 饰）昏倒在泳池中。显而易见，这便是传说中的天使。当然更令吉姆焦虑的是，佩蒂误认为他和别的女孩另有奸情，佩蒂那专横的父亲则扬言要杀了这个薄情郎。吉姆的朋友们也不是省油的灯，处心积虑想靠天使赚上一笔。从天而降的天使，给吉姆带来不小的麻烦……©豆瓣', '艾曼纽·贝阿', '汤姆·麦克洛克林', 7.5, 8021, 'tt0092834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2518390209.jpg', 0.9, 4.4, 31.9, 41.7, 21, '0.248287,-0.105209,-0.644156,0.282593,-0.184503,-0.145344,1.107743,0.235491,-0.156384,-0.177376,0.239619,0.734547,-0.345574,0.291732,0.522492,0.068574,-0.354776,-0.508204,-0.129568,-0.123272,-0.133452,-0.438068,-0.178013,-0.266581,0.093180,-0.103224,0.230082,-0.201136,0.042316,0.681186,0.606286,0.347027,-0.124176,0.301515,-0.121520,-0.130352,0.239080,0.025454,-0.212052,0.067523,-0.141828,0.006928,0.016602,-0.010547,-0.033134,0.215004,0.355651,-0.350003,0.331145,-0.210456,0.311400,-0.059600,0.029427,0.145443,0.243234,-0.144116,0.384156,-0.046915,-0.062946,-0.156606,0.215516,-0.182580,-0.442115,0.267577,0.119059,0.071003,-0.320685,0.404702,0.128813,0.049955,0.303109,0.050700,0.247228,0.302211,0.110132,0.303025,0.076761,0.097761,-0.644845,-0.033458,0.532609,0.187003,0.216128,0.192152,-0.115214,-0.345874,0.406146,-0.135980,-0.255927,0.005343,0.555263,-0.252812,0.063512,0.090515,-0.572995,-0.164103,-0.335032,-0.178574,-0.086088,-0.250109,-0.353299,-0.835273,-0.024867,-0.199782,-0.089353,0.058044,0.149969,-0.095028,0.471070,-0.753192,0.250888,0.649703,0.076894,-0.083953,0.644410,0.002593,0.216985,-0.061114,-0.407316,-0.141773,0.184106,0.150150,-0.099444,0.369007,0.086044,-0.221561,-0.364015,0.349239', '10466639', '1296534', '1316693', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301689', '今生情未了', '剧情', '史蒂芬（丹尼尔·奥图 Daniel Auteuil 饰）与马克西姆（安德烈·杜索里埃 André Dussollier 饰）是相处多年的好友，性格迥异的两人之间产生的奇妙化学反应让他们成为了工作上的完美搭档。两人共同创建了一个小提琴工作室，提供出售和修理小提琴的服务，日 子过得平静而快乐。作为工作室的客户，卡米尔（艾曼纽·贝阿 Emmanuelle Béart 饰）的第一次光顾就吸引了两位好友的目光，马克西姆更是立刻就对卡米尔展开了热烈的追求，可是卡米尔的目光却落在了表面冷漠的史蒂芬身上。在拒绝和吸引中，三个人的恋情无法得以善终，多年后，当他们重新聚在一起，是否会因为曾经的退缩和恐惧感到淡淡的伤感？©豆瓣', '丹尼尔·奥特伊', '克洛德·索泰', 8.3, 6434, 'tt0105682', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2177943758.jpg', 0.3, 1.5, 17.7, 45.5, 35.1, '0.450444,-0.104350,-0.673572,0.885707,-0.133473,-0.491908,0.863027,0.111971,-0.404573,-0.080335,-0.016430,0.985690,-0.446172,0.509233,0.424254,0.034605,-0.190697,-1.015009,-0.308249,-0.130514,-0.258746,-0.451747,-0.368400,-0.366040,-0.145074,-0.487095,0.554940,0.031431,-0.161660,0.780577,0.422437,0.306853,-0.212075,0.553054,0.045249,-0.234416,0.127456,0.177012,-0.401388,0.139104,-0.078853,-0.184269,-0.134053,0.308010,0.106558,0.389322,0.623691,-0.170568,-0.233849,0.193868,0.264765,-0.109347,0.151164,0.021796,0.123017,0.195533,0.215816,0.239044,-0.385580,-0.037564,-0.065812,-0.009269,-0.960277,0.161489,-0.021758,0.134265,-0.573287,0.664838,0.128180,-0.201113,0.074386,-0.260946,0.165699,0.204239,0.403254,0.580033,-0.172542,0.133763,-0.016397,0.065925,0.741084,0.045587,-0.463766,0.423826,-0.443097,-0.292216,-0.050488,-0.176886,-0.397138,-0.199419,0.454853,0.387756,0.356745,0.377009,-0.800839,-0.045216,-0.166558,-0.135946,0.236274,-0.589565,0.215246,-0.891018,-0.313225,-0.823116,-0.456039,0.264727,0.024844,-0.363242,0.786435,-0.898562,0.252771,0.377568,0.086454,-0.440666,0.749918,0.260660,-0.024301,-0.054404,-0.075566,0.024618,-0.035289,-0.033347,0.299957,0.443628,-0.077881,0.142038,-0.290076,0.523318', '30162520', '3006892', '4301278', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301711', '不死劫', '悬疑', '一场火车对撞的惨剧夺去131名乘客的性命，大卫•杜恩（Bruce Willis 布鲁斯•威利斯 饰）奇迹般地成为这场灾难过后的唯一幸存者，且浑身上下毫发无伤。在他参加遇难者追悼会之后，他在车窗上发现一张神秘便条，写道：“你这一生生过几次病？”不久，一个名叫伊利亚•普莱斯（Samuel L. Jackson 塞缪尔•杰克逊 饰）的黑人出现在大卫面前。和大卫不同的是，伊利亚天生手脚残废，脆弱不堪。喜爱漫画的伊利亚认定大卫就是书中那种具有超自然能力的超人。懵懂的大卫开始在伊利亚的引导下认识自身的能力……©豆瓣', '布鲁斯·威利斯', 'M·奈特·沙马兰', 6.8, 22163, 'tt0217869', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199134149.jpg', 1.4, 8.6, 48.2, 32.9, 8.9, '0.228081,0.020262,-0.605647,0.392689,-0.313596,-0.190304,0.834597,0.092656,-0.517025,-0.326020,0.444495,1.063131,-0.321629,0.141835,0.075033,-0.044636,-0.241487,-0.534899,-0.169904,0.013272,-0.614711,-0.459000,-0.322332,-0.014067,0.128513,-0.622040,0.503201,-0.183988,-0.217011,0.619467,0.401681,0.369867,0.134246,0.145689,-0.132522,0.197853,-0.136210,-0.135479,-0.357745,0.198172,-0.059016,-0.157418,-0.001386,0.315559,-0.273021,0.232877,0.651865,-0.232892,-0.193910,-0.178969,0.609992,-0.103783,-0.132354,0.233632,0.278870,-0.015087,0.074025,-0.003680,0.055368,-0.054561,0.242320,0.287497,-0.676832,-0.206430,-0.040865,0.353880,-0.492398,0.497608,-0.254968,-0.190865,-0.218849,-0.308116,0.163384,0.210841,-0.004079,0.242995,0.004219,-0.000290,-0.537808,-0.058420,0.569427,0.099034,-0.451615,0.392799,-0.149404,-0.335263,-0.127234,-0.273419,-0.452761,0.234823,0.526350,-0.042836,-0.120166,0.117922,-0.457812,0.060875,-0.254312,-0.040571,-0.338527,-0.179238,-0.216168,-0.663076,-0.203018,-0.303252,-0.337033,-0.031165,-0.088942,-0.464579,0.603669,-0.676000,0.349348,0.450358,-0.021446,0.143968,0.355769,0.189470,0.126391,-0.039400,-0.139103,0.455110,0.283368,0.267659,0.011915,0.314037,-0.005275,0.118260,-0.399212,0.581700', '1309069', '34890458', '30162520', '1298095');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301715', '美国精神病人', '剧情', '本片改编自布莱特·伊斯顿·艾利斯极具争议的同名小说，是一部描述20世纪80年代末期美国都市生活的黑色社会讽刺片。帕特里克·贝特曼（克里斯蒂安·贝尔 Christian Bale 饰）是华尔街的骄子，炙手可热的股票经纪人，英俊迷人，谈吐风趣幽默，年轻有为的他每天给自己的 客户们赚进无数的美元。可当夜幕降临时，黑暗的无边恐怖唤醒了贝特曼双重性格中的另一面。他将一个个猎物绑架到他的豪华公寓，一点一点折磨，看着鲜血慢慢涌出，猎物痛苦地死去，一种莫名的快感袭击着他。他身份使得调查这一系列罪案的警官从未把他列为嫌疑对象，而另外一名同样嗜血的杀人狂却想作下一件更为血腥的案子，成为真正的杀手之王。贝特曼的双重性格让他终日忙碌。然而罪恶终是无法掩盖，一个冷血的连环杀人案凶手的结局会是怎样呢？贝特曼会被抓住吗？©豆瓣', '克里斯蒂安·贝尔', '玛丽·哈伦', 7.8, 77674, 'tt0144084', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p887623643.jpg', 0.5, 2.3, 24.9, 50.5, 21.9, '0.143217,0.175891,-0.514465,0.627626,-0.116918,-0.050582,0.935318,0.039679,-0.356278,-0.273027,0.372723,0.736770,-0.180601,0.146017,0.257444,0.281755,0.073404,-0.651879,-0.203255,-0.157235,-0.104012,-0.334187,-0.651072,-0.194748,0.208416,-0.205226,0.498453,0.258339,-0.218530,0.118000,0.357103,0.680623,0.075466,0.448048,-0.255626,-0.184346,0.316050,-0.220492,-0.058568,0.127504,0.103485,-0.308076,-0.183979,0.385087,-0.283851,0.287694,0.738328,-0.301276,-0.062010,-0.055959,0.706473,-0.374946,-0.047433,0.075932,0.201076,-0.082272,0.222710,0.188052,-0.058719,-0.250201,0.156001,-0.051299,-0.983699,-0.124266,-0.099198,0.242313,-0.378466,0.204051,-0.155450,0.153910,0.157201,-0.049564,0.240909,-0.062104,0.256169,0.438524,0.062762,0.016005,-0.455712,0.294993,0.634675,0.086226,-0.356952,0.279604,-0.492759,-0.322468,-0.015029,-0.459890,-0.551702,-0.187386,0.517765,-0.012185,-0.239125,0.554816,-0.590720,-0.098020,-0.373803,0.016247,-0.287549,-0.334496,-0.358020,-0.421696,-0.310230,-0.369952,-0.078527,-0.057491,0.037442,-0.225543,0.577256,-0.507767,0.048095,0.667582,-0.037875,-0.276816,0.530030,-0.064178,-0.114928,0.004620,-0.234164,0.265825,0.196083,0.087901,0.132798,0.490006,0.014409,-0.209324,-0.248747,0.767249', '25828589', '26667010', '2988294', '13