INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301717', '哈姆雷特', '剧情', '丹麦王子哈姆雷特（肯尼思·布拉纳 Kenneth Branagh 饰）被传召回家参加父亲的葬礼以及自己母亲和叔父克劳迪斯的婚礼。父亲的突然离世，加上母亲的改嫁，使哈姆雷特终日郁郁寡欢。一次哈姆雷特在半夜里来到城堡高台上，与父亲的鬼魂相会，得知父王被叔父克劳迪斯毒死。鬼魂要求哈姆雷特向那个篡夺王位、霸占王妃的凶手复仇。背负了复仇任务的哈姆雷特决定用假装发疯的办法来掩饰自己，以窥探克劳迪斯的一举一动。随后他安排了一场宫廷戏，将国王被害一幕以戏剧形式表演出来。叔父看后原形毕露，而哈姆雷特却误杀了恋人（凯特·温丝莱特 Kate Winslet 饰）的父亲，导致恋人发疯死去。随后哈姆雷特的母亲也饮毒酒死亡，最终哈姆雷特愤怒杀死叔父。©豆瓣', '理查德·阿滕伯勒', '肯尼思·布拉纳', 8.3, 5486, 'tt0116477', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195389799.jpg', 0.8, 1.6, 15.6, 46.3, 35.7, '-0.069713,-0.057034,-0.480831,0.577089,-0.107343,-0.431584,0.881852,0.167323,-0.366275,-0.298476,0.535945,0.918540,-0.157169,0.354926,0.364237,-0.073149,-0.183481,-0.560498,-0.074454,-0.022346,-0.029333,-0.543739,0.035946,-0.482149,0.201361,-0.471292,0.501434,-0.264833,-0.048615,0.356860,0.476399,0.312557,-0.153645,0.372725,0.111688,0.083664,-0.079833,-0.267727,-0.313989,0.306880,0.227241,-0.125855,-0.231196,0.197736,-0.140137,0.330902,0.605958,-0.569913,0.054630,-0.424293,0.612662,-0.499678,0.165044,0.373970,0.088986,0.032387,0.027045,0.477022,-0.111758,-0.175050,-0.053364,0.117804,-0.455645,0.047129,0.114122,-0.055104,-0.639356,0.385637,-0.204306,0.107237,0.222632,-0.184864,0.260755,0.321599,0.099536,0.508372,-0.429841,-0.111360,-0.521378,0.281905,0.589113,-0.237240,0.073039,0.012778,0.233814,-0.182859,0.205483,-0.391541,-0.426915,0.232777,0.535391,-0.086207,-0.107952,0.421346,-0.132540,-0.900062,-0.565588,0.003598,0.201188,-0.499157,-0.035065,-0.430602,-0.061027,0.303352,-0.075832,-0.325151,0.164258,-0.287168,0.368474,-0.302921,0.398012,0.317801,0.259273,-0.626469,0.341461,0.148828,0.097013,-0.234984,-0.013266,0.346642,0.219682,-0.013983,-0.006076,-0.122748,0.209880,0.106268,-0.535000,0.340157', '26588017', '1296390', '1292217', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301718', '绝恋', '剧情', '裘德（克里斯托弗·埃克莱斯顿 Christopher Eccleston饰）在农村长大，一心要用知识改变命运，考取大学成为了他的奋斗目标。但是，年少的欲望却让他与当地一个姑娘发生了关系，大学梦也随之破碎。不久姑娘远走澳洲，寻觅更美好的生活。剩下裘德和他的梦想，继续在这里萌芽成长。裘德为了能考上大学，专门搬到大学城附近苦苦寻求机会。同时在这里，表妹苏（凯特·温丝莱特 Kate Winslet饰）让他暗暗倾心。迫于亲缘的关系，二人都不敢打破禁忌。当苏嫁给了他人，裘德终于冲破了心中压抑已久的感情。他们不理世俗，不想后果，只要一起。即使流浪到天涯都无所畏惧。然而，不幸终究来临。他们的孩子为这一切付上了沉重的代价，裘德和苏的感情，亦迎来了寒冷的严冬。©豆瓣', '克里斯托弗·埃克莱斯顿', '迈克尔·温特伯顿', 7.9, 6341, 'tt0116722', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2338916098.jpg', 0.5, 1.9, 23.5, 50.8, 23.3, '0.179173,0.099386,-0.798794,0.698360,-0.094149,-0.615529,0.598315,0.081994,-0.403549,-0.389051,-0.088973,0.612569,0.066766,0.468280,0.160736,-0.086388,-0.223263,-0.574163,0.281733,-0.340751,-0.205765,-0.412122,-0.189758,-0.216340,-0.264031,-0.072482,0.719534,0.281178,0.088674,0.382964,0.228974,0.172010,0.051913,0.563575,-0.307508,0.113517,0.076527,0.169934,-0.602179,0.137586,0.197437,-0.181039,-0.190777,0.143612,0.124241,0.062380,0.467493,0.070742,0.001469,-0.056383,0.205022,-0.217307,0.174848,0.233297,0.095431,-0.239725,0.169278,0.274652,-0.214686,0.011816,0.125760,-0.049454,-0.464428,-0.023937,0.297394,-0.052502,-0.567568,0.419235,0.164326,-0.150834,-0.017438,-0.193986,0.045562,0.478344,0.440863,0.339282,-0.320879,0.139676,-0.493807,0.072311,0.958236,-0.150818,-0.254501,0.408101,-0.202557,-0.307553,-0.014658,-0.300388,-0.545760,-0.033315,0.142009,0.339658,-0.323243,0.621528,-0.454227,-0.101409,0.050559,-0.010225,0.080021,-0.435089,0.104501,-0.212320,-0.296522,-0.280410,-0.305473,0.235307,0.107302,-0.367942,0.706007,-0.683881,0.240671,0.442394,0.443425,-0.471053,0.591658,0.240571,0.334368,-0.094815,0.131265,0.500181,-0.316251,0.480412,0.194142,0.186974,0.024408,0.129890,-0.328246,0.670515', '25721544', '1870682', '4861627', '4728584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301720', '鹅毛笔', '剧情', '萨德（乔弗瑞•拉什Geoffrey Rush饰）是19世纪的法国作家。他才高八斗，崇尚言论自由，小说中有不少情色描写。这些作品激怒了法国当局，政府把他关入疯人院，然而，专制的枷锁只令到萨德更坚定地奋笔疾书，作品在疯人院里一部一部的诞生。疯人院的主管是一个开明的年轻神父。他也读萨德的小说，对萨德的才华和精神充满欣赏。他对萨德提供优厚的生活条件，让他专心写作，同时让洗衣女梅德林（凯特•温斯莱特Kate Winslet饰）帮助萨德，把他的作品带到外面出版。梅德林与萨德之间也暗生情愫。然而，强大的国家机器还是将萨德送上了绞刑架。政府容忍不了他“伤风败俗”，但他的作品却流传了下来，开启了民众的思想。©豆瓣', '杰弗里·拉什', '菲利普·考夫曼', 7.6, 20971, 'tt0180073', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p701827908.jpg', 0.6, 3.1, 33.2, 44.2, 18.9, '0.484456,0.088780,-0.589920,0.926450,-0.165914,-0.133053,0.624445,0.160692,-0.342253,-0.104043,0.114613,0.895397,-0.008681,0.188905,0.163937,0.316268,-0.415128,-0.599986,0.000513,-0.093708,-0.037093,-0.468138,-0.441016,-0.417892,-0.334626,-0.310412,0.657060,0.253326,-0.428135,0.201030,0.101600,0.394965,0.236769,0.350992,-0.105558,0.020499,0.105257,-0.387553,-0.025077,0.203975,0.146925,-0.272230,-0.298174,0.296523,0.053429,0.231166,0.372518,-0.051847,-0.213466,0.172583,0.695412,-0.219080,-0.009846,0.140308,-0.103407,0.064812,-0.020139,0.350995,-0.198360,0.301018,-0.050117,-0.173407,-0.845898,-0.151077,-0.041634,0.157093,-0.672860,0.621495,-0.239432,0.025010,-0.180612,-0.214617,0.019301,-0.050084,0.166272,0.514126,-0.030917,0.084284,-0.438779,0.392090,0.239232,0.024372,-0.525452,0.229507,-0.574781,-0.374078,-0.042939,-0.317808,-0.615135,-0.293741,0.394571,-0.033137,-0.131353,0.303157,-0.670024,0.089488,-0.190129,-0.247782,-0.082654,-0.343016,-0.011361,-0.621423,-0.400346,-0.445212,-0.245453,-0.143967,0.333774,-0.505057,1.160898,-0.600365,0.089158,0.562516,0.262942,-0.527762,0.865442,0.186766,-0.103511,0.331519,-0.021907,0.258912,0.067988,0.331000,0.116377,0.505315,0.286367,-0.291000,-0.249671,0.771883', '27602116', '1870681', '22265121', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301723', '生命中不能承受之情', '剧情', 'Max（Clive Owen）是贪恋肉欲之欢的男同性恋，德国纳粹对同性恋展开大规模的迫害之前，他一直过着随心所欲的生活，之后，他在同恋人Rudy逃亡时落入纳粹之手，为求自保，他隐瞒了自己的同性恋身份，并当着纳粹的面打死了Rudy。前往集中营的途中，Max 结识同道中人Horst（Lothaire Bluteau），对方力劝沉浸在悲痛中想报复的他凡事冷静，不久，两人被命令一起不停地搬运石头，慢慢地，他俩生出“柏拉图”恋情，因为身体微小的碰触也是禁忌。Horst染上流感，Max不忍看到他在这种情况下继续忍受非人折磨，与纳粹军官进行性交易换来感冒药，Horst得知后，情愿一死也不愿看到爱人的尊严被继续无情践踏。©豆瓣', '克里夫·欧文', '西恩·马提亚斯', 8.1, 7834, 'tt0118698', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1385858466.jpg', 0.4, 1.6, 20.9, 47.2, 29.9, '0.399490,0.070169,-0.793570,0.463254,-0.102443,-0.033237,0.774998,0.071350,-0.528285,0.090983,0.324901,0.791332,-0.259483,0.193188,-0.035667,-0.123515,-0.359535,-0.845034,-0.157140,0.055055,-0.306385,-0.367086,-0.038696,-0.218253,-0.252027,-0.315964,0.642047,0.231038,-0.501496,0.444235,0.363247,0.365248,-0.137177,0.675443,-0.132407,-0.052196,-0.148398,0.032123,-0.514855,0.098225,0.248426,-0.360801,-0.085778,0.207460,-0.212253,0.383280,0.589891,-0.324870,-0.207627,-0.183741,0.129806,-0.417999,-0.190182,0.497793,0.056040,0.065478,0.091128,0.277146,-0.087050,0.069869,0.114896,0.382666,-0.548439,-0.278399,-0.229076,0.151576,-0.613215,0.395846,-0.046908,0.154673,0.066289,-0.090652,0.149317,0.339476,0.178631,0.231456,-0.335256,-0.106235,-0.505352,0.284813,0.819676,0.068077,-0.279733,0.268793,-0.407932,-0.248582,0.263331,-0.474316,-0.320395,-0.336029,0.128329,0.223679,-0.530919,0.532117,-0.440565,-0.189172,-0.221027,-0.073661,-0.011197,-0.408528,-0.036216,-0.344634,-0.184505,-0.409613,-0.531660,0.211032,-0.052040,-0.366353,0.389335,-0.784245,0.437949,0.663427,0.527003,-0.580422,0.567635,0.478154,-0.082565,0.118327,-0.164747,0.589695,0.155120,0.304198,0.351605,0.103541,0.004199,0.296395,-0.268912,0.374469', '1301022', '1308755', '25721544', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301726', '兵临城下', '剧情', '斯大林格勒战役中，瓦西里（裘德•洛 Jude Law 饰）是一个威震部队的神枪手。他的好枪法百发百中，令敌人闻风丧胆。为了激励士气，树立榜样，瓦西里的战友——苏军文宣部军官丹尼洛夫（约瑟夫•费因斯 Joseph Fiennes 饰）在报纸上大量刊登瓦西里的英雄事迹，令瓦西里的形象更为高大。然而，坦妮娅（雷切尔•薇姿 Rachel Weisz 饰）的出现，让瓦西里和丹尼洛夫都同时迷恋上了这个飒爽女兵。但塔妮娅喜欢的是瓦西里，这让丹尼洛夫大为妒忌。另一方面，德军派出了他们的狙击手康尼（艾德•哈里斯 Ed Harris 饰），让同是神枪手的他抗衡瓦西里。在硝烟弥漫的战场上，瓦西里和康尼开始了斗智斗勇的决斗。©豆瓣', '裘德·洛', '让-雅克·阿诺', 8.4, 183937, 'tt0215750', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1591033712.jpg', 0.6, 1.1, 12.2, 47.4, 38.7, '0.407507,-0.342995,-0.776054,0.853412,-0.085867,-0.173706,0.770241,-0.005976,-0.494505,0.127140,0.276439,0.784059,-0.059096,0.105785,0.204591,-0.141838,-0.362525,-0.978298,-0.289021,-0.075902,-0.239002,-0.611788,-0.446194,-0.418649,0.011078,-0.342668,0.462797,-0.072951,-0.151009,0.618266,0.373111,0.281211,0.471035,0.447408,-0.081614,0.067063,0.079732,-0.509413,-0.085371,0.126838,0.012845,-0.216692,-0.251492,0.554788,-0.084688,0.328419,0.604480,-0.275552,0.181654,-0.069657,0.173322,-0.262058,0.403909,0.040873,0.146574,-0.141374,-0.105976,-0.128713,0.073912,-0.009572,0.089230,0.177697,-0.812636,0.133597,0.020175,-0.059523,-0.726246,0.684115,-0.394252,0.144570,0.248563,0.095632,0.253716,0.355081,0.180696,0.117498,-0.095027,-0.063060,-0.445266,0.073443,0.383649,0.057369,-0.257965,0.051625,-0.387131,-0.315480,-0.073352,-0.301544,-0.399288,-0.288565,0.310865,-0.384186,0.458658,0.150541,-0.634729,0.028078,-0.279504,-0.166602,-0.409976,-0.192072,-0.198293,-0.676438,-0.342343,-0.747836,-0.431585,0.196974,-0.127113,-0.092170,1.002819,-0.763550,-0.222433,0.559665,0.043836,-0.199732,0.679710,0.135326,-0.034268,0.128443,-0.185081,0.360759,0.165593,0.108633,0.204623,0.493343,-0.142141,-0.239026,-0.274987,0.710955', '1307146', '30162520', '1298880', '3006892');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301746', '汉尼拔', '惊悚', '本片是《沉默的羔羊》十周年纪念日推出的续集，这一集故事仍然改编自作家托马斯哈里斯的小说。从高度戒备的医院逃脱的汉尼拔（安东尼·霍普金斯 Anthony Hopkins 饰）恶习难改，继续寻找他的“猎物”，不料成了曾在自己刀下侥幸活命的梅森（加里·奥德曼 Gary Ol dman 饰）的猎杀对象。梅森是一个罪大恶极的恋童癖，曾经强暴过自己的亲妹妹，年轻的时候逃狱，并且接受过人魔汉尼拔·莱克特的心理治疗，但汉尼拔·莱克特却害他半身瘫痪并且严重毁容，现在必须靠人工呼吸器维生。但是他拥有庞大的财产，并且不断收集各种不同的儿童，希望能把汉尼拔引出来，进行恐怖的报复行动。无奈之下汉尼拔求助于克莱丽斯探员（朱丽安·摩尔 Julianne Moore 饰）。两大恶魔对决，到底谁胜谁败？©豆瓣', '安东尼·霍普金斯', '雷德利·斯科特', 8.3, 181543, 'tt0212985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p613321434.jpg', 0.3, 1.3, 16.2, 48.4, 33.9, '0.131803,-0.059807,-0.332511,0.418775,-0.153765,-0.075025,0.585008,-0.034506,-0.227209,-0.135440,0.444532,0.592420,0.072306,0.041251,-0.081248,0.116110,-0.226578,-0.470259,0.092262,0.156816,-0.222834,-0.510990,-0.659925,-0.169965,0.083209,-0.311342,0.526450,-0.057725,-0.142345,0.055633,0.370444,0.451072,0.062848,0.173038,-0.113539,0.047452,0.187188,-0.281540,-0.149439,0.409738,0.062049,-0.025958,-0.124556,0.129033,-0.045997,0.421918,0.337749,-0.273686,-0.031755,-0.071209,0.305425,-0.232980,-0.128899,0.380614,-0.013114,-0.204207,0.196776,0.165479,0.014314,-0.210968,0.114611,0.146474,-0.860124,-0.148746,-0.044364,0.144207,-0.432462,0.169241,-0.303460,0.336247,0.100085,-0.076082,-0.163297,0.314444,0.214788,0.169996,-0.096509,0.033213,-0.519503,0.108605,0.298342,-0.040302,-0.347138,0.094138,-0.127848,-0.387300,-0.000263,-0.447032,-0.466177,-0.001790,0.268068,0.027258,-0.195104,0.359278,-0.515573,-0.298986,-0.379358,0.064524,-0.182394,-0.193740,-0.261803,-0.553215,-0.057371,-0.160048,-0.112376,-0.178631,0.181647,-0.487281,0.592463,-0.569310,0.283216,0.601303,0.005810,-0.448177,0.349777,0.066458,-0.031024,-0.101263,-0.152552,0.373362,0.324026,0.048505,0.267242,0.305557,0.273963,-0.219921,-0.289453,0.581125', '1308585', '1793491', '3769423', '4816602');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301753', '狮子王', '动画', '辛巴是狮子王国的小王子，他的父亲穆法沙是一个威严的国王。然而叔叔刀疤却对穆法沙的王位觊觎已久。要想坐上王位宝座，刀疤必须除去小王子。于是，刀疤利用种种借口让辛巴外出，然后伺机大开杀戒，无奈被穆法沙即时来救。在反复的算计下，穆法沙惨死在刀疤手下，刀疤别有用心的劝辛巴离开，一方面派人将他赶尽杀绝。辛巴逃亡中遇到了机智的丁满和善良的彭彭，他们抚养辛巴长成雄壮的大狮子，鼓励他回去森林复国。在接下来一场复国救民的斗争中，辛巴真正长成一个坚强的男子汉，领会了责任的真谛。©豆瓣', '乔纳森·泰勒·托马斯', '罗杰·阿勒斯', 9.1, 779429, 'tt0110357', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2277799019.jpg', 0.1, 0.3, 6.4, 32.4, 60.9, '0.119063,0.256930,-0.523443,0.658600,-0.228264,-0.369726,0.613895,-0.039220,-0.215955,-0.166259,0.219289,0.574287,0.249598,0.385724,-0.016001,0.027140,-0.174067,-0.442393,-0.206584,0.248244,-0.184150,-0.350434,-0.290236,-0.196073,-0.012466,-0.192273,0.489579,-0.028053,-0.047091,0.488582,0.468692,0.120894,-0.003940,0.517431,-0.086766,0.151973,-0.030968,-0.225630,-0.111033,-0.003523,0.064799,-0.311667,-0.235394,0.231211,-0.029212,0.424815,0.344338,-0.358992,0.002505,-0.389331,0.235785,-0.399265,0.146230,0.249707,0.397911,-0.187925,-0.139832,0.321143,-0.172325,-0.097978,0.022877,-0.135159,-0.712365,-0.015028,-0.114098,-0.006563,-0.841685,0.430572,0.051400,0.139451,0.423937,-0.249565,0.081524,0.409881,0.226059,0.053170,0.049558,0.611063,-0.356877,-0.082995,0.742409,-0.056621,0.018628,-0.339460,0.109157,-0.371894,0.197285,-0.361665,-0.353984,-0.388667,0.714438,-0.177824,-0.519138,-0.122921,-0.457795,-0.286354,-0.470435,0.008657,-0.153815,-0.367728,-0.146571,-0.110551,-0.044235,-0.307462,-0.203468,0.216246,0.123394,-0.256945,0.666675,-0.461255,0.108170,0.504169,0.249278,-0.557079,0.440337,0.175723,-0.003914,-0.116207,-0.031884,0.422686,0.285680,0.089492,0.331662,0.119778,-0.128326,-0.011499,-0.596934,0.549068', '6874741', '1309069', '30396443', '1299649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301757', '狮子王2：辛巴的荣耀', '喜剧', '辛巴（马修·布罗德里克 Matthew Broderick 配音）的女儿琪拉雅（内芙·坎贝尔 Neve Campbell 配音）调皮好动，喜欢到处奔跑，受辛巴所托看护她的彭彭和丁满实在无计可施。在另一处，刀疤的余党吉娜意图把儿子高孚训练成刀疤的接班人，并蓄谋一场复仇之战， 篡夺荣耀国的统治权。好奇的琪拉雅偷偷去森林外冒险遇到高孚，他们在玩耍时掉进鳄鱼湖。勇敢的琪拉雅救了高孚，两人成为莫逆之交。几年后，阴险的吉娜设计让高孚混入辛巴的阵营，获取辛巴的信任，再伺机发动复仇之战。高孚与琪拉雅在相处中爱上彼此，于是高孚决定放弃复仇说出真相。辛巴虽然相信了高孚，但还是有所保留。一天，高孚和辛巴散步时误入了蛮荒之地，吉娜突然出现了，经过一阵激烈的厮打，辛巴在高孚的帮助下逃脱了。但受伤的辛巴对高孚产生误会，将他赶回了蛮荒之地，琪拉雅伤心地离家出走。荣耀之战即将在辛巴与吉娜之间展开，但这是否能将父辈的恩怨、儿女的情仇彻底化解呢？', '马修·布罗德里克', '达雷尔·鲁尼', 7.8, 59245, 'tt0120131', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1838192559.jpg', 0.3, 2.1, 26.1, 48.3, 23.1, '0.253683,0.226765,-0.707841,0.492747,0.254766,-0.273459,0.497734,-0.087298,-0.308392,-0.024047,0.167731,0.635564,-0.145714,0.236008,0.163769,-0.052607,-0.294511,-0.456774,0.028315,-0.133541,-0.206836,-0.506340,-0.181880,-0.177019,0.039419,-0.173809,0.515861,0.209984,-0.266312,0.462993,0.373714,0.095854,-0.303892,0.436334,0.065537,0.259046,0.025341,0.036400,-0.307639,0.069155,0.007421,-0.085645,-0.165542,0.003532,0.186733,0.332443,0.669860,-0.570377,-0.081249,-0.038025,0.168002,-0.375867,0.092623,0.298183,0.332615,-0.043295,-0.190210,0.238152,-0.203204,-0.019080,0.063522,-0.240462,-0.702795,0.223294,0.011106,0.040530,-0.752314,0.399985,0.156301,-0.092373,0.387155,-0.148610,0.230894,0.811532,0.218095,0.153914,-0.222446,0.249376,-0.411047,-0.123704,0.882025,-0.169732,0.098206,0.052902,0.116556,-0.379947,0.171819,-0.202341,-0.273044,-0.213336,0.556583,0.033773,-0.282888,0.350751,-0.578971,-0.186510,-0.432164,0.044733,0.128464,-0.518660,-0.006512,-0.497359,-0.026253,-0.328260,-0.346293,0.064304,-0.154278,-0.432651,0.469340,-0.985904,0.071157,0.432972,0.324351,-0.475589,0.397072,0.031178,0.210566,-0.067320,-0.096505,0.565361,0.280774,0.119635,0.416169,0.281609,-0.051859,0.128997,-0.4