INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301777', '幻想曲2000', '动画', '2000年，早已荣登动画殿堂的迪斯尼经典作品《幻想曲》以全新的面貌重现世人面前，主要曲目为：1）贝多芬：第五号交响曲（Symphony No.5）（命运）、2）雷斯庇基：罗马之松（Pines of Rome）、3）格什温：蓝色狂想曲（Rhapsody in Blue）、4）肖斯塔科维奇：第二号钢琴协奏曲——快版（Piano Concerto No. 2，Allegro，Opus 102）、5）圣桑：动物狂欢节（Carnival of the Animals）、6）杜卡：《魔法师的学徒》（The Sorcerer''s Apprentice）、7）艾尔加：威风凛凛进行曲（Pomp & Circumstance）、8）斯特拉文斯基：火鸟组曲（Firebird Suite）。除《魔法师的学徒》直接取自旧版外，其他曲目均为全新收录。本片首次采用IMAX技术制作，荣获2000年动画大奖安妮奖动画角色杰出个人成就奖（Eric Goldberg）、特效杰出个人成就奖（Ted Kierscey）和最佳剧情设计奖（Susan Golderg）。', '史蒂夫·马丁', '詹姆斯·阿尔格', 8.9, 12745, 'tt0120910', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p643090411.jpg', 0.2, 0.8, 8.8, 32.3, 57.9, '-0.237155,0.039455,-0.126981,0.755743,0.714717,-0.102945,0.359062,0.064370,-0.208156,-0.550664,0.142972,0.932369,-0.155371,-0.139851,0.448075,-0.108880,-0.534543,-0.543008,-0.002588,0.021884,0.160772,0.090050,0.037559,-0.156974,-0.196591,-0.574918,1.015887,-0.504216,-0.304472,0.343731,0.623964,0.141412,-0.151995,-0.813747,0.038587,-0.320600,0.630430,-0.227192,-0.452401,0.356810,-0.515133,-0.048396,-0.211532,-0.361509,-0.457587,-0.325088,0.776525,-0.300354,0.513859,-0.027189,0.879515,0.044682,0.031831,-0.596745,0.108504,0.091789,0.467925,0.110056,0.263497,0.132826,-0.411871,-0.433339,-0.836676,0.009928,0.316935,-0.055165,0.000454,0.549250,-0.217869,0.306983,0.110206,0.036068,0.164918,-0.480550,0.605236,0.458600,0.006673,0.118341,-0.215075,0.701203,0.000835,0.103797,-0.520154,0.254023,-0.120297,-0.676607,-0.392347,-0.953506,-0.287389,0.496792,0.166936,0.248879,0.712419,0.117124,-0.525936,-0.204877,0.101014,-0.375829,0.182579,-0.001996,-0.011412,-0.915675,0.206401,0.347102,0.095742,-0.418934,0.344599,-0.420746,0.826173,-0.280121,0.534371,0.134829,-0.373120,0.159402,0.662538,-0.306595,0.315194,-0.167599,-0.380805,0.181990,-0.369956,0.101661,-0.366456,0.340754,0.231340,-0.452328,0.004377,0.506254', '22265121', '30397916', '1322847', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301788', '怪医杜立德2', '喜剧', '杜立德（艾迪·墨菲 Eddie Murphy 饰）因为拥有能够和动物交流的特殊能力而在当地名声大噪，拜访他的除了人类以外，前来寻求帮助的动物亦是络绎不绝，一时间，杜立德忙的焦头烂额，在无形之中忽略了家人们的感受。一天，一群动物找到了杜立德，它们赖以生存的森林即将被砍伐，它们希望杜立德能够帮助它们保护唯一的家园。杜立德在森林里找到了珍稀物种太平洋熊艾娃（莉莎·库卓 Lisa Kudrow 配音），只要能给艾娃觅得一配偶，那么就可以要求政府保护这片森林。在马戏团里，杜立德找来了早已经被人类驯化的大熊阿奇（史蒂夫·茨恩 Steve Zahn 配音），但很显然，阿奇并没能够吸引到艾娃的注意。©豆瓣', '艾迪·墨菲', 'Steve Carr', 6.7, 4882, 'tt0240462', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2329693788.jpg', 0.9, 7.3, 57, 26.2, 8.6, '0.317778,0.097694,-0.613332,0.494970,-0.056433,-0.083777,0.459581,-0.063176,-0.385780,-0.311125,-0.215486,0.527448,0.122879,0.056317,0.152463,0.097802,-0.271709,-0.142476,0.057334,-0.178876,-0.572479,-0.378605,-0.553191,-0.594610,-0.199471,-0.540116,0.601779,0.020845,-0.299150,0.347577,-0.057861,0.235085,-0.054473,0.459549,-0.405563,-0.149146,0.241377,-0.233691,-0.276504,0.415624,-0.228155,0.187328,-0.026599,0.324196,0.141211,0.207418,0.726253,-0.441480,-0.229225,-0.079670,0.033153,-0.168019,0.528277,0.059822,0.541391,-0.461215,0.258448,0.082537,-0.093144,0.216514,0.137532,-0.103345,-1.142092,-0.075345,-0.013777,0.254080,-0.353063,0.031658,0.424501,-0.143700,0.005184,-0.249004,0.457500,0.415877,0.041332,0.332407,-0.111763,-0.005864,-0.550648,0.030294,0.565751,-0.406848,-0.226071,0.556350,-0.519292,-0.609960,-0.073553,-0.171315,-0.388729,-0.131131,0.299728,0.400054,-0.561350,0.047433,-0.721297,-0.012527,-0.242480,-0.417236,-0.118062,-0.578745,0.032570,-0.700326,0.043171,-0.170801,-0.142051,0.112294,0.240091,-0.375519,0.761754,-0.907108,0.264252,0.695861,0.300567,-0.344424,0.677106,-0.190002,0.155939,-0.031888,-0.087893,0.329958,0.320341,0.353067,0.202762,0.270909,0.123986,-0.362691,-0.444871,0.394148', '1793491', '3769423', '27009869', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301798', '不法之徒', '剧情', '奥尔良监狱里新来了两个“无辜”的罪犯：Zack（汤姆·威兹 Tom Waits 饰）和Jack（约翰·劳瑞 John Lurie 饰）。Zack是一个DJ，被女友抛弃后在街上浪荡的他接受了一个朋友的工作：把一辆车开到一个地方，路上他却被警察拦了下来随后在车后座发现了一具尸体；而Jack则被一个老朋友所说服，去见一个年轻貌美的妓女，就在他准备享受一番之时，警察破门而入将他带走。不久，监狱里又来了一个意大利杀人犯Bob（罗伯托·贝尼尼 Roberto Benigni 饰）。三人在一间牢房里闹了不少笑话。百无聊赖的他们计划逃狱，竟然成功了。三人艰辛走过沼泽地，穿过树林，来到了一个意大利女人Nicoletta（尼可莱塔·布拉斯基 Nicoletta Braschi 饰演）住的小屋。Bob和Nicoletta两个意大利人沉浸在爱河中，最后只剩下Jack和Zack继续上路，而他们两人又将在面对岔路口时走向何方......本片由美国独立电影导演吉姆·贾木许Jim Jarmusch执导，为一部黑白电影，参加了1986年的戛纳电影节。', '汤姆·威兹', '吉姆·贾木许', 8.2, 12050, 'tt0090967', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1616290291.jpg', 0.5, 1.5, 17.7, 49.9, 30.4, '0.481882,0.010293,-0.613572,0.539099,-0.245600,-0.561487,1.166805,0.225368,-0.316728,-0.089229,0.091611,0.998145,-0.257699,0.225557,0.316386,-0.068484,-0.434905,-0.698049,-0.232869,-0.267899,-0.501265,-0.204426,-0.233493,-0.130882,-0.096569,-0.004439,0.513043,0.122821,0.229829,0.529997,0.456836,0.098302,-0.390998,0.420218,-0.281183,0.285712,0.447059,-0.159095,-0.041119,0.562338,-0.190460,-0.421140,-0.203143,0.029361,-0.121917,0.238482,0.965995,-0.068435,0.038269,-0.015371,0.086366,-0.314708,-0.149346,0.271052,0.338845,-0.098858,0.260961,0.100027,-0.394187,0.153542,0.093942,-0.159139,-0.551784,0.057713,-0.354528,0.102170,-0.860222,0.467308,0.003537,-0.101306,-0.037744,-0.467105,0.371669,0.001410,0.244095,0.516594,-0.188545,-0.079239,-0.659561,0.021750,0.623755,-0.018928,0.072575,0.459754,0.134181,-0.300615,0.028464,-0.072910,-0.558672,-0.179986,0.694163,-0.426128,-0.293961,-0.372464,-0.699344,-0.051726,-0.411110,-0.225863,-0.254008,-0.500705,-0.156452,-0.637407,0.124965,0.054633,-0.235525,0.169168,-0.102177,0.000754,0.504548,-0.447527,0.184709,0.554561,0.295146,-0.359272,0.907892,-0.139262,0.477871,0.046069,0.294506,-0.066420,0.347443,0.503421,0.387863,0.758550,-0.465269,-0.050698,-0.685508,0.292984', '21619567', '1578663', '1467779', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301811', '鳄鱼波鞋走天涯', '剧情', '故事发生在一个宁静的小镇里，德斯特（约瑟夫·梅泽罗 Joseph Mazzello 饰）和艾瑞克（布拉德·兰弗洛 Brad Renfro 饰）是一对毗邻而居的同龄人。一场医疗事故打破了德斯特的平静生活，由于医疗设备的污染，德斯特在输血的过程中感染了可怕的艾滋病。尽管不幸从天而降，并非谁的过错，但德斯特一家还是遭到了居民们的孤立和排挤。在大家眼里，艾瑞克是一个让人头疼的孩子，性格孤僻的他似乎和谁都处不好关系。某一日，隔着一道竹篱笆，艾瑞克和德斯特相遇了。性情相似的两人很快就结为了好友，艾瑞克想方设法的想要治好德斯特的病，在诸多治疗都以失败告终之后，艾瑞克毅然决然的带着德斯特踏上了求医之旅。©豆瓣', '布拉德·兰弗洛', '彼得·霍顿', 9.1, 19981, 'tt0112757', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2188484411.jpg', 0.2, 0.4, 5.9, 31.1, 62.5, '0.365539,-0.008923,-0.618201,0.625212,-0.172437,-0.138777,0.984226,0.306046,-0.577138,-0.119985,0.145700,0.786470,-0.103320,0.235061,0.361307,0.082102,-0.270855,-0.569492,-0.045467,-0.153943,-0.473914,-0.605820,-0.298439,-0.287766,-0.056573,-0.508531,0.325570,0.094069,-0.273334,0.511368,0.220579,0.262888,-0.188250,0.500235,-0.231903,-0.038632,0.098762,0.083679,-0.134492,0.037977,-0.013585,-0.294712,-0.276437,0.032742,0.115844,0.656577,0.624446,-0.245813,-0.182331,0.044265,0.111788,-0.304737,0.075669,0.261608,0.318964,-0.038641,0.274547,0.292815,-0.372565,-0.036322,0.106732,0.095425,-0.729829,-0.010772,0.217086,0.289255,-0.561780,0.937560,0.068555,-0.373244,-0.078977,-0.134014,0.164912,0.448741,0.224626,0.525044,-0.185346,0.066344,-0.445982,-0.118636,1.027018,0.019767,-0.517784,0.329478,-0.276073,-0.335051,-0.055590,-0.099032,-0.625577,-0.109731,0.395243,-0.171815,-0.250413,0.419559,-0.718473,-0.002337,-0.232728,-0.320344,-0.293675,-0.281098,0.040390,-0.608015,-0.003142,-0.629343,-0.550246,0.131329,0.003636,-0.086824,0.701562,-0.876998,0.252841,0.320585,0.142575,-0.432320,0.606751,0.252056,0.287391,0.034742,-0.141530,0.127410,0.219709,0.190314,0.309949,0.585634,0.086642,0.028993,-0.453031,0.754178', '25721544', '26687241', '1308755', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301849', '一九八四', '剧情', '这是一部虚构的政治恐怖电影。一九八四年，在经历一系列战争和合并后，世界只存在三个超级大国了——大洋国、东亚国和欧亚国。温斯顿（约翰•赫特 John Hurt  饰）生活在老大哥统治下的大洋国，这里，和其他两国一样，到处都安装着电幕（一种类似电视机的监视器），每个人都生活都在党的思想警察的监视下，历史完全按照党的需要每天都被改写。虽然无法说出为什么，作为外围党员的温斯顿从心里厌恶老大哥。一日，他偷偷从一家陈年杂货铺处买了一本日记本——原则上党不允许写日记，表达个人思想——开始写日记。当他和在小说司工作的裘莉亚（苏珊娜•汉密尔顿 Suzanna Hamilton 饰）违反党的政策开始秘密偷情时，思想警察悄悄盯上了他。©豆瓣', '约翰·赫特', '迈克尔·莱德福', 7.8, 14926, 'tt0087803', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1073879508.jpg', 0.5, 3.2, 26.7, 46.2, 23.4, '0.340136,0.115196,-0.655382,0.778774,0.149361,0.127631,0.477293,0.000913,-0.520525,-0.364643,-0.068638,0.749926,-0.055315,0.245869,0.144406,-0.151102,-0.569425,-0.804130,-0.288202,-0.246627,-0.308462,-0.434830,-0.205702,-0.483138,-0.335800,-0.133382,0.580610,0.185534,-0.444427,0.120339,0.073186,0.169678,-0.147848,0.246223,-0.167897,-0.126576,0.251197,-0.058712,-0.240309,-0.133028,-0.008626,-0.017999,-0.178254,0.244266,0.319654,0.240588,0.452642,-0.444623,-0.204124,-0.012940,0.380247,-0.085565,-0.306550,0.029564,0.550824,0.066356,0.099625,0.568379,0.133712,0.254998,0.116477,-0.033385,-0.778291,-0.294348,-0.021463,0.258927,-0.616837,0.581577,-0.253781,0.005760,-0.055968,-0.195713,0.421341,0.535041,0.353639,0.470984,-0.101737,-0.092743,-0.675399,0.436416,0.619165,0.119007,-0.392395,0.082598,-0.105054,-0.255270,-0.354688,0.066689,-0.348349,-0.187941,0.138663,-0.204670,-0.240378,0.349588,-0.770314,0.183888,0.059703,-0.526508,0.315480,-0.643942,0.044322,-0.726417,-0.202273,-0.401137,-0.012547,0.292846,0.352698,-0.065350,0.763679,-0.697787,0.169412,0.405771,0.275127,-0.611941,0.731829,0.266481,-0.139635,-0.407755,-0.123890,0.148904,0.356499,0.452668,0.030066,0.341369,0.119136,-0.041990,-0.125186,0.491214', '4301278', '30162520', '25928048', '1303449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301853', '高潮艺术', '剧情', '阳光女孩席德（拉达•米契尔 Radha Mitchell 饰）是一间摄影杂志的编辑，她活泼大方，和男友一起同居与纽约的一栋公寓。一次偶然的机会，因为家中浴室天花板的裂缝，席德认识了楼上的邻居露西（艾尔利•沙迪 Ally Sheedy 饰）。露西原来是一名有着大好前途的摄影师，因沉迷于毒品，事业彻底毁掉了。席德一心想帮助露西，于是两个女孩成了好友。两人交往的过程中，彼此吸引，渐渐走近对方的世界。席德开始吸一点毒，而露西则开始重新拿起相机，企图走进席德的阳光生活。然而，意外发生了。©豆瓣', '拉达·米切尔', '丽莎·查罗登科', 7.4, 7579, 'tt0139362', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1501310015.jpg', 1, 5, 34.8, 40.4, 18.8, '0.512056,0.121950,-0.519971,0.274111,-0.122912,-0.435243,0.834508,0.341126,-0.347072,-0.210075,-0.000308,0.560590,-0.305735,0.499310,0.559675,0.207213,-0.450389,-0.666563,0.132196,-0.159637,-0.460569,-0.237385,-0.369517,-0.351941,-0.095972,-0.314867,0.510415,-0.019006,0.067536,0.503968,0.233496,0.098819,-0.112581,0.321611,0.134576,-0.024212,0.295478,-0.018352,-0.484904,0.247665,-0.216285,-0.176237,-0.133672,0.161229,-0.033940,0.104590,0.763201,0.064699,-0.029137,-0.267905,0.275664,0.162891,-0.107607,-0.146755,0.385086,0.114570,0.276231,-0.079792,-0.099752,-0.385009,0.156424,-0.151818,-0.280281,0.021721,-0.002517,0.130979,-0.203016,0.262074,-0.004634,-0.150751,0.101270,-0.440799,0.043761,0.119443,0.597356,0.304180,-0.233318,-0.053920,-0.472506,-0.053387,0.199888,0.007595,-0.098988,0.754822,-0.374954,-0.125815,-0.016542,0.422421,-0.542009,0.023064,0.629157,-0.003631,-0.169853,0.185936,-0.678853,-0.059626,-0.402241,-0.120002,0.113430,-0.342746,-0.180241,-0.728523,-0.397048,-0.167678,-0.169464,-0.085185,-0.218504,-0.054161,0.606062,-0.723338,0.188454,0.348840,0.061182,-0.139706,0.524509,-0.055227,0.221662,-0.072680,0.163786,0.302830,-0.133845,0.115346,0.070957,0.517099,-0.197681,-0.057093,-0.343017,0.320684', '1394176', '10466639', '3811356', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301859', '意大利人在俄罗斯的奇遇', '喜剧', '呼啸而来的救护车拉来了病危的老太太，她漂亮的孙女奥利卡（安东尼娅 桑提利 Antonia Santilli 饰）匆忙赶来医院，老太太去世前告诉孙女一个天大的秘密，多年前一箱珠宝埋在俄罗斯。却被在病房里等妻子生孩子的玛比奥索（塔诺·希玛罗萨 Tano Cimarosa 饰），开救护车的司机安东尼奥（阿利耶罗·隆歇热 Alighiero Noschese 饰）和比杰瑞（尼纳托·达沃力 Ninetto Davoli 饰），断了腿的瘸子和医生都听到了。于是，都坐上了去俄罗斯旅游的飞机展开了寻宝之旅。在飞机上他们不期而遇，玛比奥索把医生的护照偷拿了出来塞进马桶里，不料护照却飘出了窗外贴在窗户上，情急之下他用双脚踹烂玻璃，失去密封的飞机失控了他卡在了窗户中。帅气的导游瓦西列夫（安德雷·米罗诺夫 Andrei Mironov 饰）来接他们，大伙分头行动，上演了滑稽好笑的故事。医生没护照只好在飞机上飞来飞去，导游和两个救护车司机一路飙车紧追奥利卡。瓦西列夫和奥利卡在寻宝过程中互生好感，奥利卡却意外得知他是文物局派来的警察......', '安德烈·米罗诺夫', '埃利达尔·梁赞诺夫', 8.4, 13386, 'tt0070439', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2517687714.jpg', 0.2, 1.2, 15.6, 42.4, 40.6, '0.358157,0.102516,-0.713613,0.348454,0.086315,-0.540313,0.829356,0.211024,-0.252255,0.028565,0.089298,0.475814,-0.143482,0.122270,0.392329,0.342508,-0.736208,-0.513493,0.164148,0.004543,-0.745521,-0.311424,-0.050236,-0.264992,-0.044903,-0.219642,-0.194378,-0.333617,0.004897,0.481043,0.356894,-0.012368,-0.231416,0.227565,-0.145710,0.380222,0.125461,-0.163304,0.074385,0.153182,0.175914,-0.082013,0.005099,-0.100369,0.485228,0.446684,0.476924,0.001031,0.351218,0.336192,-0.069778,-0.173050,0.037139,0.110808,0.172888,0.193988,-0.075616,-0.224377,-0.355745,-0.132510,0.256830,0.106408,-0.268506,0.159910,-0.322407,-0.021071,-0.754050,0.596472,-0.490427,0.275862,0.005070,-0.530887,0.306657,-0.063224,-0.316567,0.352168,0.067330,-0.034509,-0.676804,-0.073055,0.156262,0.022589,0.051924,0.234467,-0.222520,-0.314949,-0.008187,0.078965,-0.424717,-0.202672,0.766975,-0.367270,-0.126613,-0.051234,-0.406858,-0.156300,-0.618670,-0.174299,-0.208072,-0.045852,-0.232371,-0.491815,0.175242,-0.196438,-0.267384,0.178319,-0.130655,0.257252,0.472594,-0.300107,0.204279,0.529475,0.160446,0.291522,0.698752,-0.170318,0.205805,-0.081543,-0.095599,0.052994,0.346325,0.670346,0.447519,0.499058,-0.167673,-0.134517,-0.383163,0.437069', '1303462', '1301345', '1293511', '1298817');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301861', '惊声尖笑3', '喜剧', '在华盛顿特区以西20哩的小镇上，农夫汤姆（查理•辛 Charlie Sheen 饰）的田中出现了怪圈，当地记者辛迪（安娜•法瑞丝 Anna Faris 饰）对这条新闻颇为留意，不顾上层反对着力调查，汤姆的弟弟乔治（西蒙•雷克斯 Simon Rex 饰）痴迷嘻哈音乐无心农业令汤姆颇为头疼。在怪圈出现后，小镇上的孩子们出现了诸多怪异表现。辛迪的朋友布兰达在看了一部录像带后离奇死亡，而辛迪本人也接到了宣布七天后她将死亡的神秘电话，无助的辛迪向乔治求助，得以拜见了黑人先知，才发现一系列怪事的根源与一座灯塔有关。同时，辛迪通过电视向身处危机之中的人们发出外星人可能来袭的警告，连美国总统（莱斯利•尼尔森 Leslie Nielsen 饰）也开始正视此事……©豆瓣', '安娜·法瑞丝', '大卫·扎克', 6.8, 33808, 'tt0306047', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1231145600.jpg', 1.4, 8.1, 49.4, 29.2, 11.9, '0.409634,-0.132431,-0.688450,0.379710,0.171738,-0.170522,0.615792,0.130902,-0.865216,-0.089463,0.234790,0.740367,-0.440060,0.187161,0.425286,-0.085102,-0.607117,-0.747924,-0.110807,-0.213353,-0.228050,-0.543948,-0.172167,-0.440387,-0.201120,-0.332962,0.275245,0.088236,-0.114480,0.510193,0.182129,0.396288,-0.113277,0.519344,0.166017,0.060678,0.263422,-0.222904,-0.207781,0.203700,0.152555,-0.198962,-0.153129,0.391131,-0.069400,0.456403,0.611551,-0.404043,-0.157354,-0.187717,0.538625,-0.073290,0.087033,0.290290,0.364411,0.061193,-0.127368,0.102933,-0.324011,-0.063527,0.008575,0.295448,-0.306096,0.144791,-0.271285,0.540330,-0.426146,0.225073,-0.072337,-0.133570,0.079111,-0.408385,0.190166,0.307000,0.227431,0.168656,0.007400,0.045035,-0.101788,0.057720,0.200993,0.046814,-0.362111,0.148911,-0.058209,-0.410260,-0.061048,0.094354,-0.675834,-0.040746,0.480728,0.090377,-0.094176,0.185190,-0.497051,-0.245156,-0.286779,-0.545104,-0.119818,-0.129630,-0.380560,-0.965996,-0.070460,-0.250026,-0.227834,-0.231916,0.014550,-0.064237,0.483524,-0.736986,0.181225,0.469369,0.255118,-0.018089,0.584469,-0.207928,0.061409,-0.249860,-0.138227,0.376441,0.177413,0.303549,0.045655,0.131824,0.123046,-0.303754,-0.259611,0.314481', '1297715', '1465415', '3003137', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301865', '咖喱辣椒', '喜剧', '咖喱（张学友 饰）与辣椒（周星驰 饰）从小就是一对好友，后来又一起加入了警队。两人看起来吊儿郎当的，可是他们的工作表现突出，生活上工作上都是彼此的好搭档。但主播祖儿（柏安妮 饰）的出现让两人的友情遇到了考验。祖儿到警局为咖喱与辣椒做专访，而他们同时爱上了这名美丽的女孩。即使两人心中都有了芥蒂，工作时候也是心绪不宁。他们无意间破坏了警方正在侦查的毒品案，他们的线人更因为身份暴露而被杀害了。他们都感到十分沮丧，于是两人放下心中芥蒂，再次合力侦破案件……©豆瓣', '周星驰', '柯受良', 7.4, 58809, 'tt0099629', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2585539234.jpg', 0.4, 3.3, 39.3, 40.2, 16.8, '0.526105,-0.377323,-0.552353,0.596265,0.021819,-0.330459,0.669562,0.294372,-0.614828,0.028844,0.181645,0.731763,-0.279101,0.287045,0.140168,-0.187584,-0.517882,-1.003208,0.086245,-0.281730,-0.275492,-0.369674,-0.139915,-0.232338,-0.141259,-0.024326,0.641248,-0.050174,-0.127976,0.533271,0.374337,0.038355,-0.149923,0.697536,0.031222,-0.094038,0.130444,0.052681,-0.165876,-0.146894,0.064972,-0.502497,-0.122129,0.417427,0.169071,0.489952,0.650573,-0.035316,-0.504775,-0.158345,0.045463,-0.364014,-0.015614,-0.002461,0.317388,0.083780,0.444445,0.173642,-0.166523,-0.023388,0.054207,0.000577,-0.678748,0.259175,0.135750,0.127995,-0.503090,0.452232,-0.042094,-0.119530,0.176258,-0.417428,0.397323,0.344279,0.509410,0.257393,-0.305464,-0.175110,-0.527143,0.058010,0.815003,0.130115,-0.075993,0.253225,-0.314142,-0.522294,-0.156047,-0.113757,-0.195384,0.027612,0.164062,0.325856,0.041956,0.202602,-0.770751,0.043707,-0.023136,-0.068334,-0.174376,-0.636425,0.154311,-0.677491,-0.341353,-0.660888,-0.703368,0.220164,0.093203,-0.344922,0.695364,-0.811608,0.122246,0.302143,0.235497,-0.602345,0.643015,0.129861,0.003023,-0.237179,-0.216454,0.017366,-0.147660,-0.000172,0.359553,0.398604,-0.181085,-0.075552,-0.334595,0.279015', '1301022', '4301278', '34429100', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301867', '烈日灼人', '剧情', '影片的时代背景落在30年代斯大林统治下的前苏联。科托夫（尼基塔·米哈尔科夫 Nikita Mikhalkov 饰）是红军的光辉领袖，拥有殷实家底和幸福家庭，正在与妻子玛露莎（英格波佳·达库内提 Ingeborga Dapkunaite 饰）、女儿一起在别墅中度过幸福时光。不料，一名不速之客闯进了这里。当他揭开层层乔装的外物时，人们认出了他——一个失踪了十年的没落贵族米迪亚（欧列格·米契柯夫 Oleg Menshikov 饰）。米迪亚的到来犹如地狱派来的使者，随着他娓娓道来的故事，米迪亚和科托夫之间的恩怨纠结、和玛露莎之间的陈年旧情以及随着时代而扭曲的人生，都在故事中一一展开。而更为残酷的是，他带来了一个令科托夫一家陷入绝境的消息……©豆瓣', '欧列格·缅希科夫', '尼基塔·米哈尔科夫', 8.6, 18877, 'tt0111579', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p799102683.jpg', 0.5, 1.2, 10.7, 42.8, 44.9, '0.411235,0.077230,-0.592010,0.612909,-0.053632,-0.183825,0.869219,0.126215,-0.609711,-0.130189,0.077625,0.614604,-0.216159,0.283158,0.584320,0.026794,-0.453009,-0.888860,-0.125882,-0.433885,-0.179792,-0.566475,-0.270321,-0.107136,-0.144166,-0.446514,0.382213,-0.130507,0.084038,0.560892,0.411826,0.392190,-0.231806,0.295243,-0.144310,0.084079,0.131906,0.115768,-0.334552,0.024181,-0.089882,-0.115428,-0.157563,-0.170193,-0.079519,0.346604,0.539435,-0.289756,0.211566,-0.190741,0.109001,-0.098559,-0.008175,0.248167,0.283643,-0.103844,0.110342,0.337177,-0.209049,-0.114533,0.152097,-0.199070,-0.564013,0.059151,0.181667,0.205538,-0.366324,0.336622,-0.070637,0.124594,0.165159,-0.340271,0.299051,0.484989,0.467768,0.446348,-0.337823,-0.140536,-0.560267,0.272920,0.751830,-0.081015,-0.349038,0.210188,-0.227457,-0.082560,-0.197478,-0.013740,-0.571209,-0.188525,0.343742,-0.014874,0.152340,0.717296,-0.896506,-0.260433,-0.391211,-0.253411,0.096611,-0.314686,-0.244882,-0.451029,-0.409234,-0.548109,-0.169462,0.257921,-0.010936,-0.247780,0.811085,-0.515721,0.247277,0.140556,0.352708,-0.037347,0.820490,0.034554,0.413889,-0.022757,0.006905,0.503212,0.218726,-0.003598,-0.080468,0.349999,-0.325500,-0.101158,-0.366294,0.386563', '30162520', '1303449', '1307146', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301876', '阿虎', '剧情', '阿虎是一个自由搏击拳手（刘德华 饰）。他抱着“打假拳”的心态代表香港到泰国参加了比赛，完全没想着要胜出比赛。阿虎在泰国与女摄影师阿萍相遇，两人相处后产生了感情。阿虎在比赛时无心恋战中途弃权，对手察差却故意挑衅。阿虎被激怒后错手将对手打死了，结果阿虎被判入狱13年。出狱后，阿虎急着寻找阿萍，但原来阿萍已经去世了剩下了为阿虎生下的女儿Poly。阿虎便极力寻找下落不明的女儿。过程中他认识了孤儿院院长霗（常盘贵子 饰），这位年轻的院长帮他找到了女儿。性格同样倔强的Poly十分不满父亲抛弃她们母女，阿霗从中调解。女儿要求阿虎能胜出拳赛，才会遇阿虎和好。后来又有人认出了阿虎是当年的杀人犯……©豆瓣', '刘德华', '李仁港', 6.9, 19128, 'tt0277558', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2356225852.jpg', 0.8, 6.3, 50.4, 31, 11.4, '-0.169620,-0.132659,-0.535808,0.309566,-0.193422,-0.596719,0.391204,0.027452,-0.476492,-0.271037,0.258150,0.582119,-0.229737,0.169293,0.120589,-0.229347,-0.198710,-0.632019,-0.163097,0.046791,-0.343210,-0.366120,0.047020,0.069461,-0.058839,-0.060726,0.330151,-0.128850,-0.143066,0.661923,0.269615,0.185723,0.074329,0.381873,-0.129702,0.177591,0.181409,0.115625,-0.352847,0.405439,0.223330,-0.109027,-0.152168,0.133672,0.061787,0.381610,0.657673,-0.035488,0.024575,-0.239847,0.054380,-0.289749,-0.068772,0.234566,0.419179,0.072317,0.319365,0.195884,-0.116883,-0.221529,-0.014645,-0.038438,-0.329974,0.388360,-0.008306,0.003466,-0.598635,0.437198,-0.249757,0.125442,-0.004645,-0.231295,0.216737,0.355514,0.256975,0.081654,-0.141274,-0.092763,-0.510132,0.050800,0.710389,-0.241916,0.130288,0.166588,-0.032778,-0.437206,0.245938,-0.392608,-0.230436,0.168146,0.479056,0.036838,-0.383677,-0.120497,-0.079355,-0.257392,-0.091521,0.161498,-0.076116,-0.539850,0.124461,-0.181077,-0.258358,-0.262208,-0.400191,-0.119093,-0.140958,-0.217172,0.569724,-0.872100,0.196310,0.381325,0.409680,-0.492645,0.544640,0.220971,0.007138,-0.314652,0.118490,-0.126838,0.043985,0.118978,0.399239,0.311585,0.049888,-0.237358,-0.217828,0.269610', '35030151', '1292219', '1299062', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301886', '居家男人', '剧情', '1987年，踌躇满志的杰克·坎贝尔（尼古拉斯·凯奇 Nicolas Cage 饰）告别女友凯特（蒂娅·利奥尼 Téa Leoni 饰），只身前往纽约打拼。13年后，杰克已然成为华尔街炙手可热的投资经纪人，他的事业一帆风顺，生活奢侈优渥，身边美女如云，俨然一个完美无瑕的成功人士。然而，就在圣诞夜节的前两天，杰克的人生发生翻天覆地的变化。当他一觉醒来时，发现自己身在新泽西老家，凯特成为他的妻子，两人更育有两个可爱的孩子。全新而对立的人生让杰克无所适从，而他终将在金钱和亲情间做出抉择……本片荣获2001年美国科幻与恐怖电影学院最佳女主角奖（Téa Leoni）、2001年青年艺术家最佳表演奖（Makenzie Vega）。©豆瓣', '尼古拉斯·凯奇', '布莱特·拉特纳', 8.1, 49734, 'tt0218967', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p622619176.jpg', 0.3, 1.5, 19.6, 48.1, 30.6, '0.055533,-0.037108,-0.563354,0.358950,0.196228,-0.547610,0.651618,0.083352,-0.405599,-0.299137,0.294065,0.991015,-0.268084,0.307419,0.820448,-0.004360,-0.252764,-0.839856,-0.065954,-0.041030,0.013422,-0.294147,-0.445177,-0.230487,-0.242351,-0.469023,0.738787,-0.149937,0.109663,0.655724,0.470600,0.100791,-0.024949,0.196078,-0.169643,0.112370,0.466525,0.295518,-0.557226,0.262447,-0.041938,-0.245702,-0.268586,0.130053,0.044802,0.028886,0.669880,-0.138873,-0.040327,-0.075821,0.695286,-0.180444,-0.325120,0.006832,0.256247,-0.288228,-0.092768,0.136377,-0.010587,-0.168595,0.008052,-0.422695,-0.513125,0.022933,-0.029978,0.085996,-0.452857,0.314210,0.004074,-0.058184,0.128139,-0.303681,0.064628,0.431302,0.421362,0.378677,-0.099232,0.243116,-0.274926,0.581502,0.802539,0.170778,-0.615799,0.339252,-0.384163,-0.464809,-0.231845,-0.319251,-0.729044,-0.050394,0.194035,0.033455,-0.006250,0.396547,-0.469749,-0.027468,-0.249389,-0.107513,0.220864,-0.257878,-0.192555,-0.588841,-0.261841,-0.436763,-0.346062,0.097272,0.097322,-0.335646,0.642703,-0.680909,0.368932,0.420775,0.050471,-0.412214,0.956012,-0.380448,0.203875,-0.431612,-0.044927,0.546898,-0.226149,-0.023536,-0.207524,0.231964,-0.306010,0.025372,-0.121722,0.609214', '30162520', '1780122', '34795703', '1307200');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301887', '变身国王', '喜剧', '故事发生在古代的南美洲一个帝国。这个帝国年轻的国王Kuzco虚荣心极重，为了大肆庆祝自己十八岁的生日，他决定在帝国首都附近的一座山上建立一座宫殿。山上世代在此生活的居民一时陷入了困境，村民Pacha来到皇宫请求Kuzco考虑下当地居民的处境，收回成命，但遭到Kuzco一口回绝。于此同时，邪恶女祭司Yzma准备投毒杀害Kuzco夺取王位，但她的跟班Kronk搞错了毒药，误将变身药给了Kuzco吃。于是，Kuzco变成了一头骡马，并阴差阳的错上了Pacha的车去了山上的村庄。Yzma得知后，对Kuzco展开了一系列追杀，而Kuzco也在Pacha等人的帮助下展开了反击！©豆瓣', '大卫·斯佩德', '马克·汀戴尔', 8.1, 12706, 'tt0120917', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1839969451.jpg', 0.3, 1.6, 21.3, 46, 30.9, '0.441290,0.275578,-0.631208,0.742596,0.167445,-0.015646,0.588826,0.263608,-0.345352,-0.135956,0.279175,0.830612,0.018867,0.150447,0.503458,-0.162720,-0.328309,-0.382339,-0.015218,-0.178652,-0.482117,-0.271355,0.014724,-0.437898,-0.112211,-0.316127,0.589474,0.373894,-0.122205,0.271417,0.222131,0.181602,0.045925,0.491418,-0.261559,0.119650,-0.011006,-0.264112,-0.102850,0.560349,-0.229633,-0.495527,0.098126,0.398309,0.123557,0.197007,0.684970,-0.341128,-0.453527,-0.457485,0.268715,-0.464568,0.157705,0.291253,0.609751,-0.166471,-0.024391,0.176555,-0.242842,-0.084494,-0.072072,-0.246162,-0.525158,-0.152406,0.056275,-0.132138,-0.799708,0.434312,0.128881,-0.027937,-0.291893,-0.406824,0.459254,0.685232,0.180895,0.282014,-0.159579,-0.109234,-0.768125,0.038096,0.808428,-0.260370,0.008614,-0.004027,0.033759,-0.570842,0.017047,-0.111448,-0.297602,-0.127755,0.199861,0.024361,-0.404617,0.108053,-0.671469,-0.167474,-0.565315,-0.541677,0.293244,-0.384381,-0.175512,-0.362503,0.026498,0.080933,-0.192249,0.084764,0.148006,0.060682,0.564617,-0.734217,0.207427,0.660464,0.583366,-0.647899,0.558125,-0.133770,0.240373,0.200863,-0.110978,0.246700,0.222080,0.468376,0.035149,0.188175,-0.075208,-0.204965,-0.333677,0.124895', '3430271', '1292584', '26678509', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301888', '墨西哥人', '喜剧', '“墨西哥人”不是人，而是一把古董手枪。附带在它身上有一个传说，故事的悲剧收场，让这把枪沾上了凶险的不祥之兆。每个持有它的人，都会遭来不测。如今，小混混杰瑞（布拉德·皮特 Brad Pitt饰）面临着抉择：要么接过黑帮大佬的任务，远赴墨西哥把这支枪找回来；要么乖乖地听漂亮女友萨蔓莎（朱莉娅·罗伯茨 Julia Roberts饰）的话，和黑道断绝来往，做回一个光明正大的人。当然，得罪黑帮无异于惹火烧身，杰瑞再三考虑，还是决定把“墨西哥人”寻回，干完这桩事情就金盘洗手。风尘仆仆的赶到墨西哥后，杰瑞在异乡经历着曲折的寻枪过程。“墨西哥人”的神秘魔咒也渐渐浮现——萨蔓莎遭到了黑帮老大的绑架，以此来威胁杰瑞务必把枪完好带回。杰瑞的前路，面临着凶险的黑帮势力、手枪的古老魔咒，更有爱情的真谛等待他发现。©豆瓣', '布拉德·皮特', '戈尔·维宾斯基', 7.1, 9386, 'tt0236493', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p818779880.jpg', 0.6, 5.9, 44.1, 37.3, 12.1, '0.206821,0.025535,-0.455492,0.313637,-0.179852,0.081251,0.706213,0.004394,-0.336246,-0.093150,0.336912,0.678855,0.054468,-0.134849,0.197326,0.043025,-0.386946,-0.715174,0.072635,0.022046,-0.269022,-0.395122,-0.061760,-0.185860,0.068296,0.013375,0.137955,0.171013,-0.199021,0.300041,0.167113,0.286457,-0.036701,0.360540,-0.257046,0.016678,-0.041300,-0.014214,-0.235237,0.312604,0.358444,-0.285390,-0.006417,0.269454,0.036485,0.208085,0.511697,-0.199013,0.002974,0.105473,0.231312,-0.537161,-0.182475,0.024514,0.254221,0.022946,-0.059262,0.168866,-0.181966,-0.007223,0.435274,-0.085341,-0.720940,0.072001,0.016703,0.326413,-0.589393,0.323231,-0.248968,0.102875,0.059241,-0.245547,0.432899,0.235828,0.344832,0.088019,-0.014509,0.086446,-0.711025,0.168886,0.513061,-0.238209,0.110287,-0.228793,0.077157,-0.409043,-0.043935,-0.334663,-0.291433,0.001167,0.697600,-0.215800,-0.290903,0.162662,-0.525078,-0.125954,-0.010061,-0.247475,0.050965,-0.398482,-0.175605,-0.277121,0.004613,-0.176306,-0.445768,0.187603,0.131048,-0.052769,0.653116,-0.334033,0.101376,0.633348,0.252681,-0.371172,0.434002,0.055054,0.230098,-0.256473,-0.176853,0.266583,0.217194,0.464452,0.355570,0.308475,0.043058,-0.128475,-0.138274,0.231696', '1299932', '1309069', '10486471', '6753166');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301890', '浓情巧克力', '剧情', '平静的小镇在寒冬里迎来了火热的一天。年轻的薇安萝雪（朱丽叶特-比诺什 Juliette Binoche 饰)）带着女儿来到这里，在当地教堂的对面开了一间名为“天上人间 核桃糖”的巧克力店。巧克力香浓的气味在小镇上空飘荡，吸引众多小镇居民，而神奇的是，薇安萝雪每次做出来的巧克力，都能满足顾客的心理需求，发掘他们心中隐蔽的渴望。很多人原本封闭灰暗的生活有了新的色彩。但是，这却激怒了镇里的神父和贵族，他们视薇安萝雪为异类，镇里出现了对立的两派。而这时，吉普赛人洛克斯（强尼戴普 Johnny Depp 饰）远道而来，加入了薇安萝雪的阵营，他令薇安萝雪勇敢地打开了自己内心的欲望，二人共浸爱河，却想不到神父盘算着如何把这个“不祥”女子赶出小镇，于是，新旧观念的大碰撞开始了。©豆瓣', '朱丽叶·比诺什', '拉斯·霍尔斯道姆', 8, 111669, 'tt0241303', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p703826185.jpg', 0.1, 1.2, 22.2, 51.4, 25, '0.654019,0.157961,-0.860677,0.596438,-0.142966,0.025280,0.948043,0.425818,-0.356891,0.200779,0.232272,0.832120,-0.281967,0.451402,0.299531,0.292496,-0.242990,-0.585235,-0.256215,-0.599487,-0.270839,-0.202677,-0.283079,-0.356058,-0.006736,-0.172923,0.411256,0.431745,0.097157,0.427251,0.193696,0.124256,-0.045554,0.506153,-0.302626,0.005922,0.117952,-0.195118,-0.097212,0.161249,-0.019294,-0.079424,-0.273206,0.305103,0.130036,0.441050,0.662814,-0.320311,-0.164213,0.150888,0.388249,-0.077622,0.048530,0.093551,0.228995,-0.052178,-0.000663,-0.112019,-0.199700,-0.086450,-0.126950,-0.032720,-0.519372,0.208235,-0.046637,0.122445,-0.712583,0.523589,0.261541,-0.024918,0.104972,-0.176721,0.351492,0.092834,0.169207,0.568013,0.075142,-0.027031,-0.589758,-0.097105,0.616484,-0.067114,-0.355983,0.287954,-0.753787,-0.307817,0.058733,-0.140004,-0.530063,-0.345201,0.511346,0.190229,-0.084022,0.086315,-0.841532,0.203622,-0.138263,-0.231982,0.227763,-0.134923,-0.594143,-0.703875,-0.141686,-0.274159,-0.235077,0.136558,-0.041620,0.058947,0.889682,-0.808552,0.091675,0.640247,0.362705,-0.303385,0.707356,-0.246650,-0.109158,0.105025,-0.267326,0.182348,-0.116470,0.445169,0.254362,0.608697,-0.291338,0.077895,-0.523169,0.460749', '3005387', '1309101', '21619567', '25728612');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301897', '何处是我朋友的家', '剧情', '伊朗的偏僻山村小学里，一群孩子在课堂里聆听老师讲课。在检查作业的时候，老师发现穆罕德屡次没有完成家庭作业，于是严厉地批评了他，说如若再犯立马开除。老师对学生强调这是帮助他们树立良好的规矩。当天放学后，小男孩阿穆德却赫然发现自己把同桌穆罕德的作业本带回了家。听懂了老师的谆谆善诱，所以阿穆德明白这作业本就是穆罕德继续听讲的凭证。为了把作业本还给同桌，阿穆德曾希望母亲和祖父可以施以援手，但是均告失败。所以，他只能孤身前行，到对面大山里的村落去寻找同桌，归还作业本。然而，由于不认识同桌的家，所以他处处碰壁，遭遇到了无法想象的艰难险阻……本片获得第42届戛纳电影节艺术电影奖。©豆瓣', '巴比·艾哈迈德·波', '阿巴斯·基亚罗斯塔米', 8.9, 23968, 'tt0093342', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p740033093.jpg', 0.2, 0.5, 7.1, 40.5, 51.8, '0.423439,-0.028484,-0.577566,0.747553,0.098347,-0.552377,0.164946,0.052981,-0.324219,-0.448509,-0.056251,0.372567,0.071413,0.315182,0.217344,-0.150806,-0.437686,-0.519319,-0.002897,-0.152930,-0.395947,-0.667285,0.141638,-0.047759,-0.232573,-0.372952,0.183319,-0.143905,-0.356519,0.472685,-0.007346,0.064661,0.276863,0.231122,-0.155817,0.081317,0.011368,0.187947,-0.349609,0.235544,0.384441,-0.056596,-0.544126,0.063290,0.588294,0.295674,0.713298,-0.104156,-0.169790,0.040783,0.418602,-0.200614,0.002467,0.006328,0.413918,0.145942,0.309566,0.186853,0.154788,0.256223,-0.118107,-0.344989,-0.163068,-0.220167,0.101091,0.255099,-0.576031,0.458240,-0.084644,0.156663,0.090878,-0.251746,0.196187,0.308389,0.197500,0.465849,0.008522,0.130725,-0.401472,-0.083912,0.413687,-0.172175,0.055247,0.069451,-0.092421,-0.411434,0.510379,-0.165773,-0.550981,0.410565,-0.066097,0.044731,-0.312069,0.130639,-0.322862,-0.365335,-0.235364,0.009469,0.201665,-0.503039,-0.119049,-0.504955,0.221072,0.097039,-0.138121,0.177666,-0.159174,-0.386148,0.740835,-0.599420,0.373242,0.358270,0.519391,-0.079911,0.717720,0.244213,0.072021,-0.285152,-0.078821,-0.092849,0.307194,0.605720,0.190606,0.231090,0.089271,-0.519088,-0.269131,0.350586', '30283308', '1308609', '25922902', '1309178');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301899', '睁开你的双眼', '剧情', '25岁青年塞萨尔（Eduardo Noriega 饰）从早亡父母那里继承的遗产使他衣食无忧，频繁的更换女友让他在朋友圈里有不羁的名声，但是最近塞萨尔被一名女子诺丽亚纠缠，为摆脱诺丽亚，塞萨尔求助于好友的女友索菲亚（Penélope Cruz 饰）。故事切换到监狱内，面容可怖的塞萨尔因涉嫌杀人被拘，医生安东尼奥正诱使他说出事情的经过，原来诺丽亚在索菲亚家门外载到塞萨尔，路上发生了车祸导致后者毁容……塞萨尔从梦中醒来与索菲亚在公园约会，但他很快又发现公园约会才是美梦一场，医生们对塞萨尔的面容无能为力，不久他在朦胧中签订了一份协议，院方的新设备奇迹般恢复了塞萨尔的容貌，但他却发现索菲亚居然是自己虚构的人物，塞萨尔无法区分梦境与现实，决定和安东尼奥一起找到事情的真相……本片获1998年东京电影节东京知事奖等多项专业褒奖。©豆瓣', '爱德华多·诺列加', '亚历杭德罗·阿梅纳瓦尔', 8, 17841, 'tt0125659', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p828428718.jpg', 0.5, 1.9, 20.5, 50.9, 26.3, '0.079620,0.189569,-0.461016,0.266418,-0.103240,-0.263520,0.577116,0.109740,-0.424192,-0.372663,0.143345,0.895434,-0.358022,0.296874,0.283553,0.039707,-0.376175,-0.856260,0.168483,-0.170623,-0.360204,-0.433676,0.018277,-0.035407,-0.045730,-0.391087,0.614120,-0.173853,0.009005,0.340113,0.136754,0.333837,-0.066867,0.382880,-0.064133,0.150636,0.248257,0.165402,-0.269148,0.301471,0.039219,-0.466651,-0.340935,0.297436,0.076665,0.221696,0.598532,-0.138472,-0.177705,0.085101,0.316013,-0.172680,0.033446,0.173348,0.251392,-0.128955,0.076640,0.201554,-0.312090,-0.132116,-0.135297,0.039821,-0.384951,0.078504,0.120515,0.046852,-0.538655,0.186858,-0.220036,0.072197,0.099625,-0.270909,0.075693,0.194625,0.198961,0.485644,-0.065764,0.111480,-0.555786,0.025909,0.372287,-0.045200,-0.361954,0.417799,-0.311106,-0.385816,-0.018303,-0.148405,-0.390608,0.167886,0.198818,-0.171563,-0.143252,0.274786,-0.405880,-0.259302,-0.476514,-0.111186,-0.237546,-0.130413,-0.286238,-0.572874,-0.208486,-0.153865,-0.272273,0.028852,-0.046292,-0.196721,0.429416,-0.595737,0.125665,0.641778,0.086247,-0.312203,0.617535,-0.077413,0.219842,-0.338484,0.052114,0.215718,0.033602,0.009842,0.054642,0.084025,-0.087781,-0.047695,-0.567931,0.456832', '30162520', '25785124', '30167633', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301912', '秋天的童话', '剧情', '留学生李琪（钟楚红 饰）独自一人从香港到纽约读书，满心以为接机的会是自己的男友（陈百强 饰），来到却是一位远方亲戚和一位在唐人街打工的船头尺（周润发 饰）。原来自己的男友已经移情别恋了，令李琪伤心不已，把自己关在房内。船头尺不放心前往询问，闻到煤气味便以为李琪自杀，原来只是煤气泄漏。船头尺鼓励李琪就算一个人也要好好生活读书，李琪得到了他的鼓励及帮助，便开始专心读书和工作。当中船头尺也屡遭不顺，两人互相帮助之余，船头尺也爱上了李琪……©豆瓣', '周润发', '张婉婷', 8.5, 88345, 'tt0093426', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1164872896.jpg', 0.1, 0.5, 12.9, 47.4, 39.1, '0.105519,-0.239763,-0.920112,0.586416,-0.032742,-0.322050,0.495016,0.215807,-0.231534,-0.176356,0.019799,0.812384,0.187098,0.641465,0.428508,0.110690,-0.270577,-0.761983,0.075240,-0.148712,-0.424646,-0.121809,-0.023080,-0.169736,-0.386211,-0.053789,0.333514,0.107679,0.032239,0.528094,0.249246,-0.053463,-0.034057,0.559030,-0.364125,-0.076292,-0.117392,0.249848,0.079484,0.005371,0.093978,-0.587215,-0.068936,0.119214,0.321967,0.195955,0.685869,0.224371,-0.184507,0.073233,0.018058,-0.067430,0.254891,-0.007596,0.145533,-0.072628,0.354968,-0.109511,-0.393865,0.222608,0.068500,-0.119173,-0.175431,-0.029606,0.007253,-0.101135,-0.536903,0.312411,-0.169346,-0.301012,0.097710,-0.218600,0.180129,0.287346,-0.193692,0.423510,-0.366966,-0.237648,-0.635379,0.318318,0.370857,0.113273,0.275510,0.144101,0.125746,-0.122188,0.044070,0.135453,-0.384037,-0.319616,0.270385,0.077888,-0.042908,-0.119371,-0.372625,0.076520,-0.106928,0.104211,0.097724,-0.368273,0.007892,-0.508553,0.091012,-0.224713,-0.076386,0.078087,0.146437,-0.513864,0.612853,-0.651275,0.185676,0.345638,0.233075,-0.503373,0.739021,0.057172,0.119025,-0.309652,0.095305,0.026946,-0.131331,0.148904,0.117537,0.436692,0.152468,-0.279168,-0.338195,0.276915', '1460888', '3055049', '1292207', '25785124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301922', '背起爸爸上学', '剧情', '本片根据真实故事改编。农村孩子石娃（赵强）自幼丧母，与父亲（江化霖）和姐姐（颜丹晨）相依为命的他长到七岁时，为生活所困的父亲再也拿不出足够的钱供他和姐姐同时读书，一把铜勺令成绩优异的姐姐辍学，父亲叮咛石娃好好读书。石娃上初中时，姐姐为给家中节省开支早早出嫁，并从男方出的彩礼钱中挤出一部分供他念书。懂事的石娃刻苦读书，在全国化学奥林匹克竞赛中夺得一等奖第三名的好成绩，并考取了省城师范学校，但此时父亲却在干活时不幸摔伤终瘫痪在床，为了照顾好父亲又不耽误学业，石娃决定背起父亲上学。©豆瓣', '赵强', '周友朝', 7.4, 7128, 'tt0168499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870180268.jpg', 0.8, 3.6, 35.8, 44.4, 15.5, '-0.351412,-0.040146,-0.556061,0.400543,-0.264991,-0.702045,0.325789,-0.008387,-0.318519,-0.265712,-0.094479,0.710650,0.451083,0.732958,0.054581,-0.191166,-0.202033,-0.597047,0.199399,-0.122113,-0.225810,-0.380458,0.185955,0.133250,-0.369701,-0.359472,0.286568,-0.177062,0.092577,0.622566,-0.185263,-0.309783,0.094446,0.128006,-0.191257,0.022633,-0.545648,0.487972,-0.244852,0.035272,0.321969,-0.107890,-0.294512,-0.445834,0.700381,0.299200,0.656383,0.118047,0.026891,-0.335604,0.447901,0.080340,-0.186837,0.048267,0.142594,0.058900,0.329545,0.056016,-0.317447,0.278751,-0.148594,-0.639149,-0.242824,-0.301699,0.281544,-0.324368,-0.862767,0.594697,-0.068179,0.021483,0.111615,-0.335348,-0.075791,0.505709,-0.407186,0.544731,-0.628333,0.339747,-0.172177,0.660460,0.387723,-0.383639,0.224110,0.126765,-0.125916,-0.338724,0.638451,-0.554403,-0.354091,0.236126,-0.039997,0.100667,-0.298344,0.169445,-0.131758,-0.126169,0.064484,-0.126715,0.059361,-0.529579,0.016363,-0.021100,0.173289,-0.064231,-0.302142,-0.089952,0.080716,-0.516284,0.865697,-0.737119,0.341298,0.167918,0.414703,-0.373644,0.501430,0.069680,0.621955,-0.188979,-0.108370,0.027153,-0.133275,0.243691,-0.093659,0.068719,0.103196,-0.282593,-0.411364,0.702543', '26593587', '1306031', '35048413', '1308609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301926', '摇滚芭比', '剧情', '汉塞尔（约翰·卡梅隆·米切尔 John Cameron Mitchell 饰）从小就被摇滚乐吸引，希望以后能够成为一名摇滚乐歌手，某日，他遇见了美国大兵卢瑟（毛里斯·迪恩·温特 Maurice Dean Wint 饰），卢瑟答应带他去美国，但前提是汉塞尔必须和他结婚。为了追寻自己的梦想，汉塞尔毅然进行了变性手术，虽然手术给他带来了永久的创伤，但汉塞尔总算踏上了美国的土地。两年之后，卢瑟抛弃了汉塞尔，在这片举目无亲的土地上，汉塞尔顽强的生存着。他为自己找了一份看护的工作，还成立了名为“The Angry Inch”的摇滚乐队，在此期间，汉塞尔遇见了名为汤米（迈克尔·皮特 Michael Pitt 饰）的年轻男孩，殊不知这个男孩将会成为他日后的噩梦。©豆瓣', '约翰·卡梅隆·米切尔', '约翰·卡梅隆·米切尔', 8.7, 9483, 'tt0248845', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p696969988.jpg', 0.3, 1.1, 11.1, 36, 51.5, '0.070701,0.138334,-0.401710,0.486909,-0.358162,-0.699141,0.435852,0.336939,-0.359109,-0.019934,0.224299,0.854144,0.363472,0.154675,0.283087,0.301567,-0.632723,-0.605275,0.222787,0.021333,-0.109033,-0.370331,-0.449662,-0.207428,-0.134680,-0.416744,0.582993,-0.034325,0.021354,0.343109,0.137496,0.288171,0.514115,0.482047,-0.192374,0.280072,0.341613,-0.308635,-0.322547,0.353547,0.072522,-0.104950,-0.089254,0.094598,-0.170781,0.502358,0.485642,-0.039244,0.042165,-0.308662,0.357067,-0.412781,0.062437,0.162050,-0.037958,-0.053011,0.042890,0.225311,-0.313142,-0.000660,0.145048,-0.107523,-0.578822,-0.109261,0.119495,0.188546,-0.971702,0.473462,-0.306550,-0.199148,0.174529,-0.228214,0.121043,0.437199,0.275792,0.200856,-0.058021,0.203714,-0.633554,0.407988,0.677107,-0.149746,-0.295573,-0.001689,-0.055367,-0.493785,0.079196,-0.042958,-0.587388,-0.001155,0.289815,-0.165924,-0.126394,0.240427,-0.705906,-0.200535,-0.515344,-0.445836,-0.038736,-0.249529,0.084771,-0.554750,-0.005820,-0.270377,-0.241712,-0.092378,0.050095,-0.164436,0.660509,-0.614951,0.517946,0.819724,0.461644,-0.207302,0.421971,0.268888,0.262906,-0.126839,0.156088,0.411508,-0.050789,0.408923,0.039263,0.443759,0.391618,-0.113567,-0.225182,0.838538', '10774184', '30162520', '1309069', '1469353');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301928', '山村老尸2：色之恶鬼', '恐怖', '警方追查色魔案件，派出了女警花生（陈炜 饰）引诱色魔。警员追捕色魔到某地盘，可是最后色魔被砍断了四肢而死，警员也离奇死亡了。花生与其警察男友一哥（王合喜 饰）咖啡（张慧仪 饰）所在的杂志社对此事件着手报道，他们买通警员阿图索取资料，可是不久负责此案件的记者也死去了。通灵小说家蓝精灵（万绮雯 饰）也加入到案件调查当中，这时花生的表姐也离奇死亡了，使案件更加耐人寻味。蓝精灵查出案件与一个叫华月媚的女子有关，没想到这个姓华的女子是花生的曾祖母。刚开始一哥不认同案件与恶鬼有关，直到警员阿图也变得怪异起来。咖啡也常常看到很多奇怪的画面，似乎她与一切都有所联系。蓝精灵建议他们用催眠的方法勾起潜意识弄清事实，弄清一段隔世的恩怨情仇，当时冤死的恶鬼，要来讨回公道……©豆瓣', '王合喜', '蓝志伟', 5.7, 9962, 'tt0345885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2377307235.jpg', 7.2, 25.5, 47.2, 13.3, 6.7, '0.312298,-0.329539,-0.313026,0.221008,-0.134834,0.051558,0.668705,-0.011155,-0.647378,-0.162968,0.221461,0.287671,-0.321263,0.070091,0.319017,-0.030852,-0.221568,-0.679062,0.106497,-0.133609,-0.248140,-0.532624,-0.141372,-0.460513,0.131501,-0.207525,0.412779,0.122508,0.002012,0.417685,0.231163,0.188345,-0.578750,0.486028,0.086826,0.069156,0.290270,-0.107298,-0.157994,-0.011610,0.117638,-0.455484,0.005715,0.255837,-0.156232,0.474558,0.473930,-0.138998,-0.415812,-0.072933,0.307710,-0.341782,-0.155448,0.034325,0.682845,0.061296,0.140146,0.344542,-0.176386,-0.015691,0.089864,0.144153,-0.506196,0.005152,0.122610,0.490237,-0.209785,-0.102571,-0.137926,0.333536,0.160322,-0.098246,0.268875,0.087275,0.450399,0.091037,-0.017701,-0.139296,-0.563704,0.283410,0.498378,0.046721,0.052953,0.072437,-0.083682,-0.475672,-0.296490,0.090879,-0.017736,0.335196,0.277880,-0.004632,-0.312403,0.407115,-0.482147,-0.385966,-0.102863,0.049323,-0.015582,-0.193754,-0.100801,-0.448991,-0.306199,0.061185,-0.233596,-0.088485,0.216546,-0.211428,0.543071,-0.537201,0.039195,0.704525,0.097567,-0.517388,0.247026,-0.036972,-0.000936,-0.403309,-0.268408,-0.093121,0.319651,0.312157,0.179376,0.261160,0.013768,-0.416584,-0.221284,-0.214448', '3263169', '1299667', '3136507', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301946', '大醉侠', '动作', '江湖败类“索命五虎”作恶多端，杀人如麻。其老大被两江总督张大人俘获，不日问斩。其余四虎铤而走险，劫走张大人之子张步青以作要挟。张步青之妹张熙燕（郑佩佩 饰）武艺高强，人送绰号“金燕子”。为救兄长，张熙燕独闯虎穴，然恶徒狡猾非常，金燕子救兄不成，还险些丢掉性命。关键时刻，幸得隐于江湖的侠客范大悲（岳华 饰）出手搭救。范大悲曾为某寺院修行者，其师兄了空大师为夺掌门人之位杀害师傅，师傅临死前将丐帮掌门人信物交给范大悲。念及师兄弟之情，范从此隐姓埋名，以醉猫的诨号浪荡江湖。此次索命五虎与了空大师联手，势要将金燕子和范大悲斩草除根……©豆瓣', '郑佩佩', '胡金铨', 7.5, 9950, 'tt0059079', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2203949798.jpg', 0.4, 2.2, 34.8, 48.7, 13.9, '-0.436896,-0.006112,0.050975,0.275787,-0.207884,-0.343679,-0.162451,0.058152,-0.663538,-0.242483,0.141969,0.498245,0.112937,0.091995,0.287717,-0.302261,0.434734,-0.519240,-0.265546,-0.027790,0.154803,-0.152122,0.066014,-0.208824,-0.274251,-0.022165,0.298793,0.181378,-0.275543,0.219064,0.382025,0.346623,-0.474724,0.034482,-0.312173,0.222066,-0.279557,-0.132126,-0.546212,0.016660,-0.385636,-0.583071,0.038478,-0.006923,-0.294530,0.423315,0.163155,-0.064810,-0.155295,-0.678814,-0.055624,-0.313816,0.059934,-0.053818,0.230172,-0.074649,-0.017539,0.262529,0.026821,-0.202098,0.276330,-0.119362,-0.398995,0.009491,0.631834,-0.338346,-0.478352,-0.042515,-0.332025,0.334413,-0.349364,0.015254,0.000840,-0.177167,0.308489,-0.314180,0.364228,-0.107402,-0.370063,0.392948,0.395635,-0.530093,0.685420,-0.356728,0.819645,-0.299389,0.570658,-0.339803,0.164094,0.193341,0.557686,-0.324897,0.185973,0.432756,0.038597,-0.455905,-0.365453,0.912294,-0.064053,0.050190,0.078989,-0.304226,0.148339,0.245490,0.087995,-0.205951,0.657212,0.052106,0.507154,-0.255878,-0.039301,-0.382105,-0.062724,-0.379004,0.572132,0.090583,-0.075170,-0.156764,-0.132863,0.188037,0.723419,0.270676,0.303386,-0.308312,-0.266332,-0.101640,0.107124,-0.226341', '1422908', '1294488', '1300265', '1294564');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301948', '梦旅人', '剧情', '可可（卓娜）掐死孪生妹妹后被父母送进了精神病院，在这个“特殊”的地方，用一身黑乌鸦毛扮天使的她结识了卷毛（浅野忠信）和小悟（桥爪浩一），三人成为好友。卷毛因失手杀死了屡次侵犯他的变态老师被送到这里，噩梦自此伴随，小悟则是脱离现实的妄想狂。某天可可和卷毛沿着医院的围墙走到了外面的世界，教堂里的圣歌声令他们停下脚步，得到一本由一位好心牧师所送的《圣经》后，卷毛认定世界末日即将来临，而可可觉得自己死亡的时刻才代表真正的世界末日。其后，三人再次爬上医院的围墙，结伴去等世界末日的降临。©豆瓣', '恰拉', '岩井俊二', 8.3, 78701, 'tt0117338', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p481965652.jpg', 0.6, 2.1, 17.2, 40.6, 39.4, '0.415821,0.086705,-0.517283,0.320128,0.064628,-0.131609,0.767388,0.219911,-0.364212,0.034552,0.483532,0.879648,-0.262010,0.297335,0.438273,0.104536,-0.193868,-0.693444,-0.111538,-0.162492,-0.538402,-0.113609,-0.078470,0.084740,0.005514,-0.187806,0.560252,-0.009344,0.005072,0.741755,0.140666,0.293541,-0.104664,0.189742,-0.268417,0.155002,0.175210,-0.051307,-0.034755,0.388419,0.014839,-0.037565,0.089174,0.267090,-0.271505,0.050733,0.564972,-0.361302,-0.076158,-0.219998,0.300920,-0.433506,-0.128713,0.167418,0.420114,-0.161667,0.096393,0.152870,-0.038821,-0.060589,-0.026971,0.073414,-0.547711,0.046841,-0.092379,0.050513,-0.462933,0.255868,-0.010245,0.017172,0.423192,-0.350009,0.348555,0.060134,0.010121,0.669530,-0.261975,-0.060882,-0.348125,-0.059964,0.443870,-0.257369,0.010310,0.212775,0.030708,-0.121649,0.079967,0.057963,-0.389940,-0.139976,0.341965,0.160711,-0.379127,-0.051569,-0.685525,-0.078281,-0.357158,-0.094041,-0.018477,-0.286973,-0.613663,-0.239805,0.077660,-0.152718,-0.002952,0.000806,-0.129236,-0.093283,0.469862,-0.629782,0.534290,0.451634,0.271148,-0.213253,0.722151,-0.089821,0.049273,-0.053760,0.135601,0.098020,0.137091,0.747966,0.123880,0.233677,-0.088317,0.003932,-0.546787,0.363072', '1309194', '1296534', '1361252', '1908318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301974', '安娜玛德莲娜', '喜剧', '陈家富（金城武饰）是个调琴师，有点木讷的他每日过着重复的生活。某日，他和游牧人（郭富城饰）相遇，游牧人的生活居无定所，不是泡妞就是赌马，好心的陈家富收留了他。某日，他俩的楼上搬来了一个喜欢弹巴赫爱的协奏曲的女生莫敏儿（陈慧琳饰），陈家富对其一见钟情，但是却始终无法对其表达自己的好感，很快，莫敏儿被游牧人捷足先登，两人成了一对。最后，陈家富讲了个“XO侠侣”的故事，原来世界上的每个人都在寻找他的莫敏儿，运气好的找到了，运气不好的穷尽一生都找不到。爱情就是如此。©豆瓣', '金城武', '奚仲文', 7.5, 11391, 'tt0159251', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p940229727.jpg', 0.5, 3.9, 35.6, 42.1, 17.9, '0.437152,-0.205735,-0.557552,0.719968,-0.332451,-0.290916,0.832184,0.026791,-0.495170,-0.079239,-0.010311,0.744864,-0.043918,0.482207,-0.112721,0.153639,-0.064807,-0.491767,0.115403,-0.082348,-0.182997,-0.303804,-0.242676,-0.194556,-0.361435,0.008664,0.241633,0.019790,-0.230226,0.359294,0.383967,0.173912,0.253495,0.396344,-0.547927,0.215789,-0.234287,0.231869,0.096184,0.164022,-0.067584,-0.188814,-0.044676,0.261428,-0.272139,0.546376,0.451291,-0.088910,-0.152965,-0.055673,0.313169,-0.225876,-0.103921,-0.127772,0.311133,-0.057677,0.161908,0.092884,-0.142642,-0.034566,-0.032328,0.208349,-0.828261,-0.016521,0.332538,0.068153,-0.710118,0.670666,0.023256,-0.353850,-0.324558,-0.365293,0.418691,0.011767,0.285483,0.273109,-0.126580,0.122246,-0.628801,0.458484,0.819219,0.044883,-0.158371,0.630746,-0.129882,-0.389665,0.035576,-0.174557,-0.633780,-0.037704,0.173797,-0.048890,-0.068376,-0.086260,-0.554527,0.235872,-0.027657,-0.040151,0.029545,-0.584325,0.006003,-0.226962,-0.286537,-0.764008,-0.426604,0.127969,0.066993,-0.384992,0.863766,-0.755437,-0.052881,0.679565,0.057701,-0.646677,0.744026,0.333400,-0.156316,-0.089549,-0.002676,0.217990,0.010656,0.120204,0.073914,0.440284,0.133599,-0.013483,-0.417793,0.728859', '26283288', '1432669', '30162520', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301982', '刀剑笑', '喜剧', '横刀（徐锦江）、名剑（林青霞）和笑三少（刘德华）是三个齐名江湖的武林高手，但因志向有别，三人走上不同的路，横刀投身朝廷，名剑与笑三少则为争天下第一相约决斗。笑三少被帮内叛徒诬陷曾深夜入宫奸杀皇妃偷盗宝剑，被不明真相的横刀和四大护卫追捕，为洗清冤屈，笑三少开始同情人蝶舞一起走上躲避追捕、查证实情的征途。历经千难万险，笑三少终于查出名剑之嫂彩衣为保名剑天下第一，倚仗其独特的武技，借诈死七年的“名流花”教主燕敦煌之手和朝廷、横刀及他抗争。计谋失败后，暗恋名剑的彩衣自刎身亡，但在临死前，却依旧惦念著名剑与笑三少决斗的事。©豆瓣', '刘德华', '黄泰来', 6.4, 24700, 'tt0109540', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352148015.jpg', 2.2, 11, 58.5, 22, 6.2, '-0.162187,-0.046849,-0.122311,0.415962,0.167892,-0.211894,0.448544,-0.092205,-0.162940,-0.548811,0.634016,0.680079,-0.060877,0.145205,0.109194,-0.073573,0.204422,-1.080703,-0.059764,-0.135838,-0.120034,-0.132173,0.144549,0.217137,-0.424791,0.094047,0.552456,0.204163,-0.230349,0.772755,0.435651,0.279320,-0.320626,0.183082,-0.511803,-0.215505,-0.061070,0.073441,-0.578391,0.103713,-0.302174,-0.645518,-0.567771,0.199642,-0.149494,0.235635,0.340729,-0.044657,0.267256,-0.155357,0.038354,-0.197239,-0.063260,0.073767,0.426384,0.038555,0.093710,0.221736,-0.115511,-0.239694,-0.094098,-0.073162,-0.646382,0.015480,0.194119,-0.254350,-0.702299,0.480461,-0.401829,-0.016730,-0.104988,-0.060138,0.346386,-0.019086,0.115353,-0.056831,-0.105143,-0.170181,-0.541241,0.268397,0.576272,-0.184358,0.310592,-0.312614,0.388419,-0.329725,-0.164783,-0.452085,0.145437,-0.056264,0.319546,-0.149026,0.251218,0.657926,-0.424197,-0.043660,-0.288093,0.594443,-0.026720,-0.268043,-0.192526,-0.390334,-0.068327,-0.224428,-0.047481,-0.017731,0.501500,-0.292675,0.554591,-0.637667,0.043433,-0.145480,-0.038266,-0.945100,0.635641,0.565629,0.071082,-0.245830,-0.484941,0.314254,0.429029,0.099213,0.107318,0.061087,0.081766,-0.076845,-0.503812,-0.030766', '4301278', '1295469', '4202326', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301996', '贪吃树', '剧情', '一对老夫妇始终没有小孩，并为此伤心，一日，丈夫挖出了一具人形树根，送给妻子当做小孩取乐，但令人意想不到的是，这具人形树根竟然真的活了起来，夫妇俩欣喜若狂，把它叫做欧提科。欧提科显然是个胃口很好的小孩，一直哭闹着要吃的，老夫妇两人为了喂饱它，花光了所有的钱，但它仍是饥饿地捉了家里的猫吃掉了。尝到肉味道欧提科从此拒绝其他食物，又把偶然进入家中的邮差、路人，还有楼里的邻居都吃掉了。老夫妇又惊又怕，但面对越长越大的欧提科显然没有任何办法，只要任由它吃掉了自己。没了管束的欧提科走到大街上，遇到的活人活物都进了它无底洞一样的胃。在菜地大啖卷心菜后，欧提科睡在了树下，直到愤怒的田地主人老太婆向它举起斧头……©豆瓣', 'Veronika Zilková', '杨·史云梅耶', 7.9, 7448, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2492875852.jpg', 1, 2.5, 22.6, 46.6, 27.2, '-0.004096,-0.160569,-0.677853,0.092471,-0.334470,-0.523356,0.869612,0.336440,-0.414317,0.099353,-0.113198,0.438402,-0.008707,0.247749,-0.196582,0.098737,-0.018557,-0.274090,-0.121543,-0.049441,-0.371117,0.053832,-0.177520,-0.266343,-0.085638,-0.012873,0.210055,-0.166330,0.070074,0.018221,0.267307,-0.312537,0.313299,0.498487,-0.506294,0.331248,-0.249110,0.123184,0.174994,0.068632,0.031429,-0.076328,-0.164977,0.288008,0.201962,0.377465,0.678801,-0.373199,-0.407932,-0.182956,0.109044,-0.213911,0.010022,0.078269,0.350620,-0.221459,0.290235,-0.276940,-0.137183,0.090536,0.486208,0.152322,-0.486308,0.060419,-0.167763,0.041115,-0.621406,0.512619,0.339412,0.199682,-0.159953,-0.484442,0.506796,0.001236,-0.136340,0.458910,-0.247888,0.016505,-0.950431,0.098862,0.551980,-0.122766,-0.181997,0.228071,-0.270941,-0.403079,0.104811,-0.369162,-0.145135,-0.074541,0.479124,0.440423,-0.781628,0.158892,-0.584669,0.123591,-0.182921,-0.095999,0.036803,-0.355397,-0.121886,-0.237003,0.291982,-0.186324,-0.181063,0.096584,0.057758,-0.164837,0.560685,-0.171073,0.295077,0.510720,0.188014,-0.222818,0.587192,-0.065970,-0.054467,0.053034,-0.031782,0.117565,0.380485,0.313768,0.721400,0.378076,0.074495,-0.017832,-0.345133,0.476049', '21619567', '10527288', '1394470', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1301997', '鬼马双星', '喜剧', '这是香港70年代的典型武打搞笑片。老千邓国文（许冠文 饰）经常出入于监狱，狱中无聊时，他经常会表演一些自己的千术以资同仓的犯人解闷。犯人刘俊杰（许冠杰 饰）对国文的千术十分佩服，希望出狱后能和他一起合作挣大钱。国文并没有答应，因为老千一般都独来独往。两人出狱后，俊杰组织了一帮老千和国文对赌，国文通过一早买通在场的舞女佩佩将他们击败。俊杰更加佩服国文，再次提出两人合作。国文抵不住他的死缠烂打，终于应承了。两人计划向城中恶霸大哥全下手，为了筹集赌资，他们还参加了电视台的有奖游戏，国文凭借聪明的头脑顺利的赢下了奖金。和大哥全对赌的日子到了。©豆瓣', '许冠文', '许冠文', 7.4, 8278, 'tt0071588', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1388155720.jpg', 0.5, 3.2, 38.2, 41.8, 16.2, '0.210003,-0.167387,-0.360459,0.392829,-0.065863,-0.359480,0.183796,-0.032879,-0.455919,-0.105927,0.142391,0.558773,-0.132581,0.061114,0.251327,-0.452237,-0.280533,-0.730035,-0.200069,-0.103824,0.013901,-0.513132,0.094282,-0.063102,-0.299733,-0.034093,0.206170,-0.133269,-0.217476,0.715159,0.197787,0.177263,0.290924,0.217853,-0.016640,-0.078369,0.064020,0.164775,-0.424264,0.153256,0.276158,0.036683,-0.252397,-0.063386,0.439377,0.069335,0.434502,0.050710,-0.152066,-0.013284,0.112870,-0.361989,-0.305800,0.204628,0.243921,0.002198,0.483195,0.309512,-0.073125,0.042041,-0.129761,-0.062788,-0.649362,0.045867,0.159229,-0.155702,-0.298272,0.086917,-0.047085,-0.075983,-0.116424,-0.254862,0.099276,0.393297,0.386667,0.045878,-0.202297,-0.103664,-0.380392,0.396386,0.628092,-0.068204,-0.057020,-0.052288,0.146323,-0.389060,0.159142,-0.198021,-0.152918,0.141297,0.296580,-0.213626,-0.141888,-0.190727,-0.419958,0.030435,0.014010,-0.005747,0.085605,-0.550032,0.093571,-0.634075,-0.163373,-0.277036,-0.274963,-0.155013,0.305882,-0.382541,0.744515,-0.898677,-0.132401,0.446725,0.369081,-0.500498,0.596142,0.160848,-0.159305,-0.176011,-0.170401,-0.526184,0.158893,0.442272,0.088898,0.648557,0.081469,-0.545912,0.008812,0.205283', '4127270', '34429100', '3091208', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302013', '查泰莱夫人的情人', '剧情', '故事发生在等级制度森严的英国，年轻的康妮（西尔维娅·克里斯蒂 Sylvia Kristel 饰）终于等来了与自己分别多时的丈夫克利福特（Shane Briant 饰），但同时也等来了丈夫下半身永久瘫痪的噩耗。面对残酷的现实，善良的康妮只得默默接受。一次偶然中，康妮邂逅了庄园的看林人米尔斯（尼古拉斯·克莱 Nicholas Clay 饰），后者健壮结实的躯体让康妮的内心激动难耐。一来二往之下，康妮和米尔斯发生了关系，尽管粗鲁的情人大字不识一个，但康妮依旧在他的身上找到了久违的满足与热情。纸终究包不住火，康妮和米尔斯之间的奸情败露，令克利福特大为火光，同时，在英国已经无法生存的米尔斯决定前往加拿大开辟新的天地，究竟该留下还是离开，康妮面临着严峻的选择。©豆瓣', '西尔维娅·克里斯蒂', '贾斯特·杰克金', 6.6, 5604, 'tt0082640', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2156566635.jpg', 1.7, 9.7, 53.3, 27.1, 8.3, '0.342808,0.162340,-0.912903,0.459763,0.018684,-0.339453,0.878104,0.162566,-0.533767,-0.101021,0.091268,0.698479,-0.243035,0.178826,0.252748,0.050743,-0.370337,-0.651317,-0.096761,-0.088543,-0.423808,-0.622688,-0.289777,-0.173032,-0.014223,-0.127268,0.438746,0.054356,0.269839,0.363202,0.389167,0.378911,-0.106755,0.501205,-0.096265,0.046698,0.271637,-0.124599,-0.297944,0.125942,0.220554,-0.061346,-0.028547,0.363311,0.081182,0.335758,0.511593,-0.371957,-0.157134,0.132859,0.248242,0.039087,0.070281,0.263649,-0.022246,-0.148658,0.065055,0.158668,-0.241210,-0.035565,0.239311,0.000349,-0.758304,0.232466,0.186076,0.255992,-0.599645,0.439127,-0.270214,-0.218392,0.093637,-0.515953,-0.010373,0.422064,0.436144,0.518005,-0.252169,0.123771,-0.321679,-0.187193,0.540434,0.270252,-0.421589,0.110575,-0.497759,-0.138819,0.042729,-0.108299,-0.471043,-0.268400,0.460488,0.332930,-0.252533,0.382541,-0.535416,-0.213490,-0.455064,-0.116653,-0.039843,-0.369568,-0.075733,-0.459288,-0.329607,-0.461667,-0.296353,-0.041398,0.031253,-0.004335,0.594563,-0.723556,0.321671,0.395278,0.242092,-0.121171,0.332302,0.348875,0.382938,-0.041499,-0.010945,0.587615,0.065453,0.168282,0.194935,0.449120,-0.001439,0.104798,-0.387623,0.415702', '1292211', '25723780', '6827727', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302022', '美女与野兽之贝儿的心愿', '动画', '本片剧情内容则采用回忆倒叙的方式，叙述美女贝儿回忆当初到城堡当囚犯时的第一个圣诞节，贝儿唤醒了城堡失去已久的欢悦感觉，使得城堡重新享受圣诞节庆的温馨，终于也让野兽重新体会人生的光明面，抛弃自私自立的心理，贝儿与野兽才彼此相知的情形。本片除电影原班人马演出之外，还多了三个新角色，包括名叫安吉利的圣诞树饰品娃娃、阴险的管风琴以及他的小跟班短笛等贝儿必须克服管风琴从中作恶，才能完成心愿使野兽重享圣诞节的欢欣。', '佩吉·奥哈拉', '安德鲁·耐特', 8.1, 5659, 'tt0118692', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1838187132.jpg', 0.4, 1.3, 19.4, 50.6, 28.3, '-0.095722,-0.050592,-0.238324,0.558553,0.195113,-0.408610,0.685816,0.015271,-0.108910,-0.163482,0.178283,0.407514,-0.333436,0.341167,0.336030,-0.150707,-0.482161,-0.642132,-0.216594,0.105785,-0.156620,-0.086695,-0.029146,-0.237901,0.216722,-0.352187,0.716668,0.222477,-0.099739,0.190220,0.233848,0.013172,-0.368009,0.073257,-0.030804,-0.261252,0.223436,0.174159,-0.467049,-0.296816,-0.157400,-0.133368,-0.120910,0.206181,-0.067238,-0.037526,1.056449,-0.467778,-0.208339,-0.066020,0.331615,0.192541,-0.072175,-0.119033,-0.134449,-0.029092,0.156143,0.215960,-0.063605,0.292468,-0.054041,-0.321100,-0.881535,-0.099298,0.094143,-0.270727,0.020654,0.201458,0.143432,0.273449,0.408182,-0.079024,0.255290,0.194794,0.339214,0.615427,-0.342288,0.095476,-0.165361,0.312313,0.360464,-0.272756,-0.394709,0.487571,-0.424707,-0.434594,0.091548,-0.105844,-0.193005,0.184786,0.319334,0.211152,-0.426637,0.168306,-0.703610,-0.221967,-0.214856,-0.269922,0.378290,-0.484737,-0.075285,-0.885382,-0.154411,0.019584,0.010658,-0.114604,0.245149,-0.212311,0.782166,-0.434621,0.336705,0.493093,-0.124354,-0.392618,0.436129,-0.133119,0.112017,-0.295930,0.312745,0.336816,-0.207884,0.167964,0.140647,0.206083,-0.376389,0.161916,-0.450644,0.688011', '5403927', '4181031', '26759820', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302033', '妖怪都市', '喜剧', '香港道士林正（林正英 饰）远赴泰国，施法帮助泰国警方制服了雌雄降头大盗金莎与乃密（周比利 饰），岂料两人的尸体被其师父盗走并炼成强大的阴阳同体尸，且阴阳尸只要获得出生于十灵时的女性便可以成为无敌的至强魔尸。林正返回香港后开始为担任实习医生的女儿林小婷（陈雅伦 饰）的交友问题头疼，施法令觊觎小婷的色狼男医生原形毕露。与此同时，阴阳尸来到香港向林正寻仇，林正师兄被害，不敌阴阳尸的林氏父女选择报警，警探大B（张国强 饰）与林小婷有嫌隙，于是趁机数落父女二人，随林小婷至现场勘查的大B在阴阳尸攻击下一败涂地。林氏一家和大B苦思降服阴阳尸之法，而出生于十灵时的小婷与大B其实就是战胜阴阳尸最强大的武器……©豆瓣', '林正英', '袁祥仁', 6.4, 5280, 'tt0105868', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2774992233.jpg', 2.4, 13.6, 54.9, 18.8, 10.2, '-0.210209,-0.356842,-0.618627,0.175815,-0.091166,-0.032937,0.182323,0.111454,-0.263569,-0.296705,0.066355,0.436624,0.011642,-0.142589,0.141265,-0.075555,0.344006,-0.626897,-0.102024,0.081487,-0.287266,-0.152321,-0.401258,-0.108769,-0.208742,-0.316199,0.282153,0.209947,-0.292017,0.164839,0.136897,0.332075,-0.610365,-0.023064,-0.227908,0.056119,-0.386214,0.023277,-0.261036,0.339651,-0.117048,-0.032078,-0.265696,-0.158073,-0.096690,0.267815,0.410763,-0.280849,-0.111031,-0.468369,0.190270,-0.261272,-0.385655,-0.085139,0.332483,0.029509,0.619695,0.061973,-0.182004,-0.080210,-0.039116,0.092297,-0.756982,0.277141,-0.074372,-0.192288,-0.074919,0.278707,-0.054164,-0.070730,-0.202152,-0.469003,0.167645,0.204525,-0.002274,0.104081,-0.149595,-0.192461,-0.516993,-0.160166,0.492522,0.114326,0.012995,-0.017244,0.313783,-0.283772,-0.442499,-0.446233,0.198107,-0.145618,0.685387,0.284617,0.110993,0.138883,-0.482917,-0.401874,-0.490272,0.499519,0.004362,0.143207,0.184106,-0.462252,0.047493,-0.102289,-0.119876,-0.127518,0.449467,-0.303667,0.649725,-0.747666,0.260241,0.111154,0.499824,-0.683335,0.284647,-0.104232,0.466331,-0.351603,-0.315168,-0.062265,0.446587,0.455341,0.313050,0.247877,-0.048955,0.043001,-0.347707,-0.067026', '4301278', '1877596', '26678784', '24756658');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302050', '广岛之恋', '剧情', '1957年，法国女演员（埃曼纽尔•莉娃）来到日本广岛拍摄一部宣传和平的电影时，邂逅当地的建筑工程师（冈田英次），两人在短暂时间内忘记各自的有夫之妇、有妇之夫身份，产生忘我恋情。然而因为广岛这块土地的特殊性，两人在激情相拥时，女演员脑海中总会闪现若干有关战争的残酷画面，建筑工程师也常令她回忆起她在战时于法国小城内韦尔与一名德国占领军的爱情。电影拍摄结束后，被纠缠的女演员感觉自己唯一能做的，是在有限的时间里，更加投入地把身体交于建筑工程师。©豆瓣', '埃玛妞·丽娃', '阿伦·雷乃', 7.8, 38159, 'tt0052893', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2356864113.jpg', 0.6, 2.6, 25.2, 46.9, 24.6, '0.194247,0.083019,-0.794256,0.503906,0.358362,-0.237901,0.683682,-0.022651,-0.649762,-0.390134,0.179981,0.767127,-0.452166,0.189628,0.281703,-0.276192,-0.643385,-0.896477,-0.189650,-0.184883,-0.060020,-0.325472,-0.164756,-0.326114,-0.299026,-0.234787,1.022984,0.197091,-0.332155,0.164254,0.062119,-0.086542,-0.162131,0.260576,0.114321,-0.155765,0.291563,-0.135808,-0.583952,0.269475,0.010757,-0.264940,-0.126866,-0.201503,0.102666,0.035170,1.004650,-0.142174,-0.055037,-0.067439,0.434375,0.004650,-0.109702,0.106036,-0.085058,0.232281,0.348507,0.116057,-0.482366,0.118428,0.197959,-0.278220,-0.518671,0.148728,-0.143711,0.261617,-0.245352,0.572598,-0.276138,0.079414,0.214220,-0.345761,0.218558,0.447040,0.479441,0.355517,-0.260947,-0.058810,-0.205870,0.434743,0.731528,0.009559,-0.332778,0.405601,-0.321749,-0.583053,-0.306464,-0.101161,-0.249532,-0.037791,0.145952,-0.081018,-0.168484,0.556211,-0.797136,0.051659,-0.095477,-0.370683,0.066659,-0.123443,-0.276683,-1.086722,-0.358924,-0.495679,-0.257215,-0.007945,0.131219,-0.114007,0.885961,-0.799632,0.052490,0.569974,0.454270,-0.087439,0.891163,-0.000867,0.101270,-0.133244,0.014178,0.456915,-0.280413,0.200779,0.049421,0.276189,-0.268337,0.061054,-0.433104,0.393288', '1322847', '5403927', '3811356', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302054', '金枝玉叶2', '喜剧', '接着上集，林子颖（袁咏仪饰）搬入Sam（张国荣饰）公寓与其同居。可是不过10日，Sam就对这种平淡琐碎的生活产生了厌烦，他希望两人能保持一定的距离。在好友肥婆（曾志伟饰）的建议下，Sam要阿颖以男装重回娱乐圈，本意是要分散她的注意力，不料却获得空前成功，Sam被指为同性恋加吃软饭，感到脸上无光的他开始对阿颖恶声恶气起来。楼下搬来一个谜样的女人方艳梅（梅艳芳饰），气质高雅，女人味十足。在她的开导下，阿颖渐渐走出忧郁，却发现自己对方姐生出异样情愫，而对方似乎也大胆地回应她的感情。Sam和方姐之前曾有过一夜情，他自以为是地保持和方姐的暧昧。有一天，Sam终于发现了阿颖和方姐之间的不对劲……©豆瓣', '张国荣', '陈可辛', 8, 44340, 'tt0116462', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p939948826.jpg', 0.3, 2.1, 24, 45.2, 28.3, '0.421018,0.129242,-0.711776,0.464797,-0.146075,-0.149084,0.944185,0.073738,-0.544125,-0.065952,0.061362,0.504195,-0.480797,0.290368,0.107669,0.188045,-0.230369,-0.684428,-0.008810,-0.033112,-0.135662,-0.330508,-0.264721,-0.097793,-0.288315,-0.160937,0.356841,0.138527,-0.333228,0.552112,0.351885,0.132444,0.139823,0.856817,-0.204510,0.142631,-0.149214,0.289624,-0.100065,0.145310,0.270818,-0.270017,-0.292748,0.304803,0.003489,0.477744,0.580181,0.050931,-0.383522,0.378938,0.287199,-0.075940,-0.089301,0.069480,0.040151,0.050592,0.168190,0.120112,-0.261576,0.044773,-0.050596,0.102433,-0.362790,0.296780,-0.013453,0.047526,-0.393196,0.417769,-0.018132,-0.038820,0.227088,-0.255976,-0.006890,0.198438,0.396182,0.320608,-0.264011,0.140572,-0.378847,-0.097588,0.621869,0.203553,-0.192397,0.555130,-0.313166,-0.340023,-0.103992,0.024066,-0.298106,-0.256013,0.064611,0.102877,-0.190014,0.046929,-0.591018,-0.082601,-0.052289,0.139183,0.031239,-0.581553,0.041479,-0.236847,-0.294800,-0.647215,-0.419125,0.160030,0.015153,-0.426802,0.514640,-0.944274,0.230799,0.448293,0.479959,-0.546171,0.532758,0.193915,-0.263299,-0.244296,-0.127234,0.138730,-0.273517,0.044688,0.240387,0.506527,-0.147924,-0.042728,-0.420915,0.388819', '1308755', '3059036', '1296370', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302061', '德州巴黎', '剧情', '查韦斯（哈利·戴恩·斯坦通 Harry Dean Stanton 饰）迷失在德州荒无人烟的沙漠中，因为身体虚弱而昏迷。医院联系了他的弟弟沃特（迪恩·斯托克维尔 Dean Stockwell 饰）来接他。出院的查韦斯一直沉默，直到看见“巴黎，德州”的牌子，才终于开口。回 到洛杉矶弟弟家，查韦斯见到了儿子——亨特（亨特·卡森 Hunter Carson 饰演），弟弟弟妹其实是养父养母。但是亨特对突如其来的父亲并不接受。后来，查韦斯用很特别的方式收复了孩子的心。通过交流，查韦斯了解到孩子的生母——简（娜塔莎·金斯基 Nastassja Kinski 饰）的下落。于是，父子踏上了一条寻母之路……本片获第37届戛纳电影节最佳影片金棕榈大奖。©豆瓣', '哈利·戴恩·斯坦通', '维姆·文德斯', 8.6, 55204, 'tt0087884', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2237305324.jpg', 0.2, 1.2, 12.3, 41.4, 44.9, '0.021357,-0.185067,-0.642899,0.658399,0.068532,-0.551193,0.435460,0.212099,-0.592778,-0.169333,-0.007976,0.889602,-0.201407,0.245966,0.503695,0.336662,-0.653646,-0.391716,0.051749,-0.049970,-0.289504,-0.547200,-0.143081,-0.040598,0.002510,-0.274337,0.489402,0.012809,0.140153,0.426636,0.271083,0.181533,0.022919,0.580431,0.004296,0.254772,0.131702,0.043005,-0.392615,0.362000,0.315858,-0.029947,-0.215064,0.164707,0.354728,0.328259,0.521763,-0.179911,0.072163,-0.080022,0.176478,-0.241686,-0.098826,-0.102571,0.163276,-0.086279,0.324897,0.168752,-0.139202,-0.005107,-0.135434,-0.212504,-0.036739,0.352062,0.043617,0.163491,-0.452040,0.341715,-0.371388,-0.026096,-0.046342,-0.648381,0.276427,0.340102,0.012240,0.414912,-0.298039,-0.046400,-0.448556,-0.109699,0.436166,-0.305761,-0.255863,0.356926,0.025573,-0.421691,0.228897,-0.217420,-0.428269,0.243801,0.321499,0.136757,-0.261843,0.102811,-0.234469,-0.511200,-0.354293,-0.269042,0.103188,-0.389011,0.113452,-0.535781,0.054159,-0.224145,-0.098594,-0.208536,-0.019836,-0.317559,0.289929,-0.629312,0.372593,0.288011,0.227417,-0.332768,0.525208,0.081976,0.128384,-0.546756,0.012435,0.635545,0.015808,-0.036913,-0.015473,0.036480,-0.025097,-0.190822,-0.239395,0.525704', '4319218', '3645150', '1297239', '3285622');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302063', '小上校', '剧情', '年仅6岁的劳德•舍曼（Shirley Temple 秀兰•邓波 饰）是一个天真可爱的小女孩，她憨态可掬，招人疼爱，父亲的士兵都戏谑地称之为小上校。劳德的母亲伊丽莎白（Evelyn Venable 饰）是一位南联盟军上校的女儿，她与来自北方的杰克坠入爱河，却遭致古板父亲（Lionel Barrymore 饰）的反对。最终伊丽莎白选择了爱情，而父亲也与之决裂。六年后，小上校和母亲返回外公家。时间并未冲淡父女间的隔阂，老上校对女儿依然冷颜以对。小上校的出现打破了尴尬的局面，她凭着机智和可爱渐渐弥合了外公和母亲心中的裂痕……©豆瓣', '秀兰·邓波儿', '大卫·巴特勒', 8.3, 5165, 'tt0016029', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2170114382.jpg', 0.1, 0.5, 14.6, 52.9, 32, '-0.074316,0.058405,-0.678383,0.679174,-0.413088,-0.472301,1.037909,0.237448,-0.514641,-0.144829,0.277375,0.912562,0.004191,0.548183,0.278468,0.177539,-0.304158,-0.712082,-0.122951,-0.301331,-0.016778,-0.624610,-0.311483,-0.181746,0.066453,-0.375123,0.524132,-0.037893,-0.133963,0.657085,0.155165,0.080592,0.055179,0.524864,-0.088787,0.258220,0.054466,-0.034570,-0.131387,-0.354822,0.272771,0.115136,-0.112609,0.077694,0.023297,0.615438,0.780501,-0.538493,-0.099616,-0.199520,0.053851,-0.267036,-0.028943,0.261890,0.191725,-0.110077,0.309935,0.123856,-0.098408,-0.248944,0.042971,-0.071266,-0.303811,0.333953,0.045180,-0.004102,-0.443620,0.534465,-0.159702,-0.152504,0.240011,-0.559864,0.041018,0.312187,0.069089,0.671663,-0.410458,0.113164,-0.207667,0.040672,0.463253,0.142742,-0.436355,0.235230,-0.436791,-0.287538,0.031951,-0.452938,-0.677580,0.097923,0.193582,-0.094160,0.109884,0.618233,-0.506679,-0.170489,-0.560041,0.288385,0.121760,-0.564969,-0.186206,-0.110458,-0.188177,-0.569784,-0.383508,0.104153,0.008278,0.019914,0.909555,-0.697478,0.239513,-0.039548,0.496052,-0.460035,0.688716,0.273938,-0.026104,-0.454539,0.119723,0.354358,-0.254786,0.040844,0.192250,0.200525,-0.069729,-0.143456,-0.281281,0.154923', '3111650', '26348103', '4724586', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302077', '雁南飞', '剧情', '本部电影讲述身处硝烟弥漫的战争年代，一对热恋中男女青年的悲情爱情故事。薇罗尼卡（塔吉娅娜·萨莫依洛娃 Tatyana Samojlova饰）和鲍里斯（阿勒克塞·巴塔洛夫 Aleksey Batalov饰）本是沉浸在甜蜜热恋中的幸福情侣，可随着战争的爆发，这一切的美好即将 破灭。鲍里斯参军，薇罗尼卡的父母在敌机的轰炸中双亡，悲痛欲绝的她只能寄宿在鲍里斯父亲的家中。鲍里斯的表弟趁机占有了她，薇罗尼卡受到众人指责。双重打击下的薇罗尼卡本想一死了之，可心中仍苦苦等待着鲍里斯的归来。当得知鲍里斯牺牲的消息后，薇罗尼卡彻底绝望了。战争结束，当所有人都在庆祝胜利的时候，薇罗尼卡也双手捧着鲜花来到广场上。这时，一行大雁在空中飞过，就像当初的美好时光一样。本片一经问世，就轰动了整个世界影坛，以其绝美的光影对比，绝佳的镜头运用，一举荣获1958年戛纳国际电影节金棕榈奖和摄影大奖。', '塔吉娅娜·萨莫依洛娃', '米哈伊尔·卡拉托佐夫', 8.8, 15124, 'tt0050634', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2058841317.jpg', 0.1, 0.5, 8, 43.6, 47.7, '0.321409,-0.049102,-0.820706,0.478738,0.248449,0.022925,0.764346,0.101591,-0.261245,0.151206,0.507879,0.765473,-0.467203,0.482562,0.561804,0.262295,-0.611541,-1.067626,-0.093189,-0.136717,0.119620,-0.463839,-0.186673,0.486236,-0.083189,-0.410428,0.629296,-0.012848,0.093757,0.767132,0.292039,0.046172,-0.170071,0.473301,-0.118822,0.222417,0.161338,-0.029227,-0.446791,0.099118,0.069569,-0.103767,-0.272747,0.347231,-0.064326,0.043645,0.744900,-0.623726,0.419236,0.103471,0.480712,-0.302762,0.305392,0.216189,0.121021,-0.191038,0.372813,-0.028535,-0.346139,0.173494,0.154551,-0.142943,-0.483935,0.376546,-0.048973,-0.055240,-0.554366,0.452798,0.081925,0.205371,0.249211,0.196713,0.247568,0.353789,0.222529,0.491254,-0.425797,0.121497,-0.169255,0.217029,0.422645,-0.139156,-0.558140,0.492304,-0.079965,-0.185469,-0.358483,-0.155508,-0.759994,-0.273338,0.649514,0.030382,-0.125911,0.403071,-0.491673,0.021934,-0.270609,-0.494397,0.142559,0.186130,-0.366873,-0.689654,-0.260187,-0.156703,-0.419590,-0.038752,-0.038633,-0.164449,0.662777,-0.572534,0.252304,0.438513,0.005013,-0.279145,0.541687,0.049719,0.241051,-0.003346,-0.193499,0.495715,-0.219854,0.069399,0.045645,0.308179,-0.077180,0.204276,-0.272243,0.841579', '1307146', '1