INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302090', '逃学威龙', '喜剧', '周星星（周星驰 饰）是飞虎队队长，奉命以卧底的身份到圣育强中学寻找警司于参观时被窃的配枪。周星星就算百般无奈还是接受了任务。他很快适应了学校的生活，功夫高强的他也受到了学校众多学生的拥戴，周星星也顺势调查失枪案件。警队的另一位卧底曹达华（吴孟达 饰）也参与了这个案件，最后也与同学一起合力，帮助周星星破获一踪大型军火贩卖案件。©豆瓣', '周星驰', '陈嘉上', 8.1, 312454, 'tt0103045', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2573231828.jpg', 0.2, 1.2, 21.7, 48.1, 28.9, '0.351764,-0.291598,-0.297763,0.352681,-0.143168,-0.101420,0.150537,0.234467,-0.634406,-0.354089,0.379898,0.659993,0.083890,0.186757,0.189491,-0.364183,-0.480930,-0.659873,-0.001157,-0.224002,-0.415462,-0.358087,-0.168588,-0.287721,0.000665,0.065800,0.549557,0.005927,-0.331001,0.593737,0.431138,0.326519,-0.334619,0.360019,-0.072051,-0.231137,0.547140,0.211030,-0.216232,0.116107,-0.049313,-0.499107,-0.178221,-0.144650,0.375262,0.427777,0.535175,0.329130,-0.363389,-0.046659,0.064221,-0.412578,-0.045683,-0.235428,0.595814,0.231719,0.109321,0.366443,-0.136204,0.127569,0.033127,-0.084540,-0.896872,-0.082882,0.337738,-0.003699,-0.334996,0.199319,-0.106522,-0.180236,-0.037551,-0.066095,0.051170,0.412289,0.015075,0.062948,-0.164181,-0.052524,-0.229678,0.625590,0.415614,-0.167206,-0.155911,-0.053531,-0.008456,-0.669217,-0.062816,-0.193320,-0.014083,0.222165,0.135075,-0.046652,-0.160229,0.041862,-0.519409,-0.259012,-0.286481,-0.097995,-0.134530,-0.253692,0.208918,-0.903521,-0.072172,-0.152930,-0.323694,-0.122431,0.176280,-0.051515,0.636536,-0.736454,-0.172510,0.615605,0.117671,-0.743515,0.589496,-0.033745,0.228637,-0.408296,-0.132508,-0.140258,0.222099,0.694717,0.054425,0.424400,0.174207,-0.627932,-0.198682,-0.026488', '25723905', '2369613', '27073234', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302100', '尼罗河上的惨案', '剧情', '痴情的神枪手 Jackie（Mia Farrow 饰）将贫穷的未婚夫 Simon Doyle（Simon MacCorkindale 饰）介绍到朋友 Linnet Ridgeway（Lois Chiles 饰）的庄园工作。谁知不久后 Simon 与 Linnet 结了婚，两人还如胶似漆地去埃及度蜜月。愤怒的 Jackie 跟到埃及，时时骚扰纠缠。在尼罗河游船上，Linnet 发现除了 Jackie 之外，船上很多游客都不怀好意。上岸参观卡纳克神庙时，一块巨石从高高的柱子上掉落，下面的 Simon 与 Linnet 差点丧命。可是，针对 Linnet 的谋杀并未停止。Linnet 躲过了一劫，却没躲过第二劫。除了 Linnet 惨死床上，Linnet 的女仆 Louise（Jane Birkin 饰）、声称目击到凶手的 Salome Otterbourne 夫人（Angela Lansbury 饰）都被灭口。经过调查，侦探 Hercule Poirot（Peter Ustinov 饰）发现，除了 Jackie 和 Simon，几乎每个游客都有充分的作案动机和时间。 那么，凶手究竟是谁？他是如何实施犯罪的？而之前推下巨石的又是谁？', '彼得·乌斯蒂诺夫', '约翰·吉勒明', 8.5, 133747, 'tt0077413', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2366278130.jpg', 0.1, 0.4, 10.6, 50.7, 38.3, '0.374983,-0.282499,-0.885419,0.426303,0.005391,-0.328157,0.834058,-0.130681,-0.365523,-0.065961,0.372966,0.393371,-0.376581,0.186429,0.244237,-0.039759,-0.366065,-0.802202,-0.151447,-0.112337,-0.836340,-0.461014,-0.323045,-0.000455,-0.006458,-0.318782,0.370411,0.174914,-0.098012,0.430842,0.326386,0.166693,-0.441146,0.475089,-0.349457,-0.132169,-0.060553,0.215547,-0.182171,0.244993,-0.123372,-0.590475,-0.153850,-0.010118,-0.035192,0.619940,0.569829,-0.214636,-0.083414,0.114406,0.201263,-0.312652,0.161965,0.353670,0.589893,-0.157959,0.151743,0.482704,-0.149626,-0.068146,0.302490,0.175978,-0.487729,0.062589,0.299571,0.180247,-0.727219,0.229488,-0.071184,-0.096819,-0.132909,-0.358319,0.445100,0.421966,0.028526,0.284531,-0.355794,-0.000213,-0.800605,0.013149,0.719667,0.033452,0.137523,0.056129,0.416063,-0.387473,0.101212,-0.197255,0.034383,0.039140,0.134457,0.067913,-0.143100,-0.089246,-0.712605,0.099338,-0.441606,-0.401539,-0.103011,-0.458938,-0.209641,-0.668855,0.107176,-0.288169,-0.386030,0.381528,0.345596,-0.242995,0.492436,-0.610990,0.194746,0.503611,0.313645,-0.367575,0.662239,0.010358,-0.196483,0.027558,-0.227758,-0.154983,0.589854,0.298527,-0.064238,0.291289,-0.099144,-0.384325,-0.510194,0.179505', '1947080', '25870679', '3055049', '1297347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302109', '12夜', '剧情', 'Jeannie（张柏芝饰）是一个空姐，与工程师Alan（陈奕迅饰）相遇在同一辆车上，之后便开始了他们的爱恋。刚开始的时候，两人都打得火热，深深投入到彼此的生活，如胶似漆。跟很多恋情一样，Alan厌倦Jeannie对他管太紧的方式，开始挣扎，Jeannie认为自己已把一切给了男友，便全身心投入感情，但渐渐的两人之间当初热恋的感觉不再，感情转淡。Jeannie努力挽回感情，两人也复合了，Jeannie在这时才发现自己已不再爱Alan了，导致最后分手收场。Jeannie消失于Alan的生活中，独自一人继续游走在繁华的都会里，寻找另一个“十二夜”，她也遇到了另一个令她心动的人。©豆瓣', '张柏芝', '林爱华', 8.3, 106649, 'tt0282159', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2176182513.jpg', 0.2, 1.2, 16.7, 49.2, 32.6, '0.561582,0.079392,-0.925846,0.513931,-0.083154,-0.543849,0.914782,0.076058,-0.495824,-0.081824,0.006011,0.826056,-0.297814,0.398374,0.187544,-0.168419,-0.329509,-1.190371,-0.090119,-0.050430,-0.277666,-0.502195,-0.070425,-0.031412,-0.405793,-0.007991,0.773711,0.245550,-0.137188,0.510058,0.232699,0.047590,-0.183925,0.814998,-0.039333,-0.006617,0.114060,0.265827,-0.338580,0.018456,0.087048,-0.296160,0.018205,0.157996,-0.140437,0.323437,0.903014,-0.194210,-0.235238,0.107393,0.206624,-0.165979,-0.212363,0.210105,0.200594,0.242110,0.203527,0.085351,-0.435421,0.055613,-0.096443,0.142000,-0.504000,0.149124,-0.256374,0.136064,-0.568857,0.492602,0.125226,-0.235994,0.135311,-0.371442,0.299167,0.496252,0.387726,0.317756,-0.464079,-0.267364,-0.289936,0.116319,1.049889,0.115493,-0.189115,0.836297,-0.027744,-0.365805,-0.246034,-0.014865,-0.242686,-0.364317,0.065299,0.477477,-0.355644,0.461490,-0.751006,0.336103,-0.003010,-0.010702,0.044882,-0.665101,0.097258,-0.542204,-0.418258,-0.575506,-0.324025,0.386771,-0.085152,-0.285031,0.610277,-0.882674,0.302243,0.372752,0.360811,-0.720636,0.644060,0.167422,0.199670,-0.174353,0.320539,0.348923,-0.374354,0.223594,0.402320,0.426018,-0.111829,0.422166,-0.507436,0.619758', '1301022', '35446144', '2027925', '34973399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302110', '福星闯江湖', '喜剧', '曹警司（曹达华 饰）为了使过气黑帮头子戴哥大（卢海鹏 饰）做警方污点证人，指证黑帮头子巫二器（王青 饰）的罪行，设计逼犀牛皮（冯淬帆 饰）、大生地（吴耀汉 饰）、花塔饼（苗乔伟饰）、罗汉果（曾志伟 饰）等四位有福星之称的私家侦探做卧底，曹又派他的女儿高级帮办Banan a（刘嘉玲 饰），应徵做女佣人暗中保护他们。 四福星入狱救出戴哥大，同往找他的女儿Mina，适值巫二器正欲迷奸她，他们把她救出，戴哥大感激四福星，答应做污点证人指证巫二器的罪恶，但给巫二器想尽一切办法开脱了罪名。 曹警司又安排Banana诈被巫杀死，激发起四福星替她报仇的斗志。片末，四福星和警方一起逮捕了巫二器，把他领导的匪帮全部消灭。©豆瓣', '吴耀汉', '冯淬帆', 6.5, 4579, 'tt0121302', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2043751408.jpg', 2.4, 12.7, 52.9, 21.5, 10.6, '-0.458720,-0.186235,-0.423424,0.476422,-0.446003,-0.081184,0.473382,0.230626,-0.271815,-0.229811,-0.028625,0.537907,0.025112,0.020025,0.063807,-0.060658,-0.070438,-0.732643,0.038673,0.020091,-0.143539,-0.560414,-0.195080,-0.461073,0.167161,0.155849,0.017691,0.139984,-0.081893,0.140650,0.757323,0.330010,-0.138250,-0.108987,0.022374,0.048725,-0.005707,-0.117189,-0.177547,0.022586,-0.242639,-0.286145,0.036144,0.113495,0.058454,0.415098,0.224652,0.010402,0.073661,-0.461779,-0.044504,-0.566204,0.230032,0.083126,0.065841,-0.012422,0.042785,0.298879,-0.219835,-0.362915,0.434107,-0.127691,-1.081688,0.174447,0.296058,-0.280522,-0.742987,0.029457,-0.252161,0.244876,0.128270,0.059066,0.177115,0.165622,0.234107,0.131773,-0.058701,0.319379,-0.529358,0.338140,0.317160,-0.167676,0.467263,-0.422409,0.268327,-0.024559,0.304881,-0.160570,-0.068998,0.004265,0.346941,-0.291041,0.190859,-0.237371,-0.208417,-0.507345,-0.464990,0.244393,-0.018856,-0.240553,0.444780,-0.356279,0.042826,-0.031236,-0.172258,0.076332,0.518192,-0.317796,0.593452,-0.071837,0.088055,0.403260,0.243934,-1.343924,0.457310,0.450074,0.133845,-0.324269,-0.123313,-0.429619,0.411543,0.308654,0.644224,0.080130,-0.286163,-0.457552,-0.165028,-0.362798', '3670447', '26678784', '1304382', '35096844');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302128', '新独臂刀', '动作', '因身怀“鸳鸯双刀”绝技而驰名江湖的白衣少侠雷力（姜大卫）被龙异之（谷峰）设计陷害，自废右臂退出江湖后，他隐姓埋名于某个小饭馆里当伙计，过着任人侮辱欺负的日子。邻居铁匠的女儿巴蕉（李菁）因对他心生爱慕，时常鼓励其重塑形象，无奈雷力战胜不了心魔。有缘结识翩翩少侠封俊杰（狄龙）后，雷力重拾生活的信心，并说好在封俊杰赴过龙异之的约后两人一起去过归隐的生活。不幸的是封俊杰像多年前的雷力一样也中了龙异之的诡计，奋力抵抗一番终因不敌敌手身亡，得知消息的雷力大悲，矢志用左臂练就一身好功夫为好兄弟报仇。©豆瓣', '姜大卫', '张彻', 8.1, 12908, 'tt0069518', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526673269.jpg', 0.3, 1.4, 20, 51.9, 26.3, '-0.115585,-0.086271,-0.465456,0.412000,-0.265703,-0.325172,0.501649,0.165303,-0.524980,-0.337528,0.212189,0.544323,0.204998,0.390488,0.187735,-0.093497,0.363696,-0.723501,-0.003002,-0.113391,0.159179,-0.063404,-0.257983,0.187073,-0.250150,-0.447512,0.373581,-0.064499,-0.032870,0.623918,0.013312,0.116249,-0.127477,0.324332,-0.134008,0.053512,-0.155781,0.092418,-0.596333,0.102387,-0.004160,-0.359344,0.111349,-0.032434,-0.239060,0.152800,0.540670,-0.053338,-0.056080,-0.440802,0.214074,0.018149,0.007848,0.183249,0.028106,0.057212,0.543755,0.208391,-0.042166,-0.003496,-0.055246,0.048217,-0.454648,-0.087122,0.258203,-0.210693,-0.488246,0.635152,-0.041690,-0.082143,-0.602172,-0.372029,-0.041699,0.018851,0.220983,0.038722,-0.110050,0.054889,-0.270014,0.186694,0.761145,-0.152967,0.035794,0.144811,0.320117,-0.026200,0.409926,-0.312216,-0.396503,-0.163479,0.247290,0.048537,0.013521,0.296159,-0.316196,-0.043514,-0.492837,0.607582,0.115242,-0.026873,0.028460,-0.279699,-0.330196,-0.176151,-0.348440,-0.144890,0.252846,-0.201017,0.675890,-0.871129,-0.028796,0.235652,0.285693,-0.527620,0.484462,0.106502,0.280694,0.135785,-0.086300,0.176923,0.002038,0.514033,0.177421,0.295685,-0.023349,-0.082991,-0.474254,0.124078', '35030151', '1292219', '30345227', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302133', '秘密花园', '剧情', '孩子眼中的世界在这部电影里美妙的展开，父母双亡的小玛丽（凯特·马伯里 Kate Maberly饰）来到苏格兰的亲戚家住了下来。这是个美丽而又有点神秘的庄园，尤其是秘密花园更是玛丽心中的一个大谜团。原来，玛丽的姨母曾经在自己这个花园的千秋上丧命，姨父便从此紧锁了花园大门。无意中发现了钥匙的玛丽打开了花园的大门。从此，花园成为了玛丽与大自然水乳交融的圣地。玛丽还带上了长期坐在轮椅上的表弟科林（海登·普劳斯 Heydon Prowse饰），他本来封闭的视野在神奇的大自然面前变得豁然开朗，而朋友迪康（安德鲁诺特 Andrew Knott饰）更是在这里和他的鸟儿朋友们聊天，秘密花园的大门就这样通向了孩子们心中的天堂……©豆瓣', '凯特·马伯里', '阿格涅丝卡·霍兰', 8.5, 19312, 'tt0108071', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1193040563.jpg', 0.1, 0.9, 13.2, 45.6, 40.1, '0.450347,0.200039,-0.811008,0.681961,0.006863,-0.470172,1.276531,0.333481,-0.476632,-0.025707,0.352385,0.922833,-0.304645,0.642612,0.448135,0.446737,-0.588939,-0.550308,-0.340007,-0.413114,-0.279769,-0.244913,-0.426014,-0.271568,-0.013199,-0.155187,0.529953,0.151268,-0.130616,0.307674,0.076465,0.153508,-0.325377,0.204510,-0.373247,0.191460,0.145115,-0.003578,-0.089196,-0.070556,-0.137185,-0.177845,-0.189876,0.215943,0.062190,-0.017429,0.653820,-0.447168,-0.102915,-0.029103,0.138258,0.034244,-0.055338,0.017350,0.242239,-0.130529,0.278128,0.038945,-0.271399,-0.037570,0.079705,-0.247500,-0.456363,0.229697,-0.087790,0.177423,-0.587373,0.337726,0.089574,-0.365898,0.157201,-0.514505,0.252565,-0.092862,0.062504,0.468027,-0.390841,0.102455,-0.586191,-0.137946,0.337797,-0.003592,-0.105743,0.358772,-0.214899,-0.396906,0.036667,0.180987,-0.607259,-0.185538,0.630078,-0.072725,-0.123046,0.178391,-0.802553,0.102201,-0.312096,-0.264547,-0.042382,-0.250643,-0.297569,-0.658058,-0.177789,-0.274986,-0.293786,0.060147,0.047271,0.078765,0.677786,-0.846309,0.415239,0.366743,0.083491,-0.107075,0.822597,-0.078650,0.260256,0.120803,-0.302483,0.206469,-0.150861,0.638556,0.045464,0.635576,-0.238826,-0.094108,-0.758136,0.633774', '1296534', '21619567', '1467779', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302164', '特警新人类2：机动任务', '动作', '一款可以用来代替士兵作战的全自动化机器人RS1被成功研制，送往香港参加展览。RS1的破坏力极为巨大，亦十分危险，它的存在令许多犯罪分子们垂涎欲滴。香港特警马奇（冯德伦 饰）、艾伦（李灿森 饰）和艾迪森（陈冠希 饰）奉命保护RS1的安全，而马奇和艾迪森之间曾经有过一段极不愉快的过往，使得两人在合作之中屡屡发生冲突。科特（孙国豪 饰）是艾迪森的好友，他的真实身份是一名天才黑客。科特趁同艾迪森叙旧之际催眠了后者，操纵其打开了RS1的开关，输入了逃走程式。RS1大闹场馆，死伤无数，而艾迪森亦被列为了头号通缉犯，遭到了FBI的穷追猛打。艾迪森知道，想要自证清白，唯有捉住目前下落不明的科特。©豆瓣', '陈冠希', '陈木胜', 6, 5800, 'tt0251094', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2356149392.jpg', 3.7, 20.8, 55.4, 14, 6.1, '0.380754,-0.101022,-0.556956,0.502735,0.146346,0.079441,0.679101,-0.031671,-0.703422,-0.301824,0.076678,0.613371,-0.068184,-0.048302,0.321016,-0.195975,-0.056827,-0.563328,-0.223621,-0.319231,-0.259819,-0.498452,-0.573752,-0.244512,-0.206416,-0.624691,0.685995,-0.140980,-0.381678,0.379791,0.244229,0.551002,-0.330944,0.337228,0.004356,-0.203657,0.130594,-0.283989,-0.481197,0.311235,-0.100883,-0.234582,0.145575,0.189094,-0.127255,0.445111,0.541114,-0.342854,-0.015768,-0.100875,0.216915,-0.504890,0.020380,0.000883,0.217328,0.222443,-0.012993,0.106726,-0.257051,0.222890,0.244619,-0.031891,-0.759224,-0.005761,0.281070,0.126297,-0.454388,0.416625,-0.306785,-0.024514,0.046219,-0.077672,0.216673,0.335386,0.343359,-0.017326,0.024010,-0.094650,-0.523411,0.119868,0.592549,-0.066393,-0.219187,0.211544,-0.206095,-0.321785,-0.084310,-0.343815,-0.353252,-0.083164,0.407613,0.229405,0.222271,0.173924,-0.575893,-0.097348,-0.369382,-0.038909,-0.268549,-0.150652,0.252663,-0.784043,-0.105001,-0.408584,-0.262125,-0.061972,0.065519,-0.141229,0.479085,-0.824420,-0.040030,0.280875,0.215292,-0.372407,0.261130,0.199288,0.214681,-0.327190,-0.242673,0.111956,0.346385,0.282464,0.135836,0.238121,0.056941,-0.385166,-0.237939,0.120005', '1793491', '24753477', '2369613', '5308201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302165', '加油站袭击事件', '喜剧', '夜色中，前棒球手（李成宰 饰）、纯情流氓（刘五性 饰）、前主唱（姜成珍 饰）、绘画爱好者（刘智泰 饰）四名好友出于好玩冲入一家加油站行劫，岂料老板颇有被劫经验，一早令家人将钱款取走，四人收获甚微，遂决定取代老板经营权，乔装加油站服务生坐地收钱。一撮流氓前来勒索加油站，反被四人暴打后塞入休息室，沦入和加油站职员们一样被看管的境地。老板则在办公室里被强迫打电话给家人，四人控制着加油站成功，叫来外卖填肚，满腹抱怨的外卖小子被四人赶跑后流氓头目带人前来报仇，结果又被暴打，一起做了俘虏。四人招待各式客人，引发连串冲突。外卖小子挨打后喊到大批帮手复仇，流氓大头目亦率人同一时间赶到，三方陷入混战，防暴警察到场镇压……看来这个夜晚，注定不会平静。©豆瓣', '李成宰', '金相辰', 7.6, 11734, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1837011657.jpg', 1.4, 4, 28.5, 46.4, 19.7, '0.216962,-0.012337,-0.305688,-0.095207,-0.027939,-0.126808,0.452489,0.472164,-0.313827,-0.030805,0.217537,0.402499,-0.120996,-0.085565,0.633095,-0.447846,-0.290183,-0.493387,-0.317479,-0.140382,-0.165732,-0.118140,0.143038,-0.084705,0.034140,0.124489,-0.080605,-0.159410,-0.104099,0.562080,0.445591,0.262122,-0.349143,0.336576,0.094736,0.154737,0.404757,-0.326671,-0.161031,0.270180,-0.452245,-0.286391,0.072338,-0.229238,0.206111,0.125095,0.651942,0.151036,-0.136083,-0.212046,-0.136779,-0.085166,-0.050751,0.280119,0.275221,0.302758,0.398263,-0.122699,-0.297324,0.077354,0.162501,-0.089693,-0.257873,0.389028,-0.087203,-0.322900,-0.457905,0.073145,0.109751,0.195474,-0.026993,-0.097808,0.315951,-0.007622,0.265374,0.110712,0.351908,-0.104414,-0.515906,-0.097500,0.555015,-0.455319,0.555833,-0.261377,0.228718,0.015789,0.312334,-0.120935,-0.154617,-0.105450,0.443099,-0.035660,-0.137042,-0.339034,-0.519811,-0.078979,-0.301228,-0.000167,-0.069778,-0.137656,-0.306319,-0.729493,0.260727,0.451629,-0.119808,0.241891,0.272336,0.387338,0.457516,-0.459251,0.099551,0.377669,0.423472,-0.385168,0.317899,-0.240303,0.056658,-0.156083,-0.054942,-0.300248,0.525468,0.415672,0.259197,0.169965,-0.470671,-0.230255,-0.052558,-0.205663', '3147969', '10466639', '25833539', '1914923');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302181', '热带鱼', '剧情', '在台北市即将进入联考的紧张又炎热的夏天里，刘志强整天幻想着带暗恋的女孩去绿岛上坐潜水艇游海底，做着“热带鱼”的美梦。在又一次令父母失望的模考成绩下，他偶然在电视上看见一起绑架案，试图只身解救小孩没想到自己反被抓了去。绑匪阿庆（林正盛 饰）是自乡下来台北混世的打工仔，勒索失败后他把两个小孩带回了家。阿庆全家人生活困顿却其乐融融，一面悉心安顿两个小孩的生活另一面想办法如何获得高额的绑票。阿庆甚至找来辍学妹妹阿娟闲置的书本让刘志强继续复习。最终，警察还是找到了被阿庆带到海上逃避追捕的刘志强，可刘志强却否认阿庆是绑匪……©豆瓣', '林嘉宏', '陈玉勋', 8.7, 14657, 'tt0117970', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1148607609.jpg', 0.2, 0.7, 9.4, 44.6, 45.1, '0.188734,0.005106,-0.526917,0.372393,-0.323335,-0.402251,0.631657,0.125048,-0.497525,-0.008919,0.119836,0.449806,-0.032617,0.606967,-0.015198,0.219747,-0.481976,-0.578293,-0.089382,0.070301,-0.408134,-0.215324,-0.091364,0.032763,0.030532,0.206073,0.369090,-0.022445,-0.055579,0.375116,0.166877,-0.070558,-0.270106,0.593336,-0.403670,0.040495,-0.133387,0.047066,-0.024170,0.229171,0.054980,-0.477551,-0.356800,-0.087179,0.294941,0.307323,0.704840,0.072383,0.022605,0.086086,0.063060,-0.325343,-0.323441,0.017185,0.266003,0.023308,0.071202,-0.242830,-0.193413,-0.042032,0.171465,-0.012732,-0.413938,0.168576,-0.098531,0.045283,-0.792095,0.369026,0.095533,0.205308,0.176762,-0.398339,0.066973,0.176217,0.036967,0.558013,-0.203658,0.236960,-0.397630,0.227854,0.634467,-0.165534,0.173921,0.116906,-0.010870,-0.195556,0.358591,-0.214926,-0.484028,-0.073962,0.299527,-0.145702,-0.503237,-0.046201,-0.560525,0.014087,-0.367325,-0.100046,-0.114779,-0.429779,-0.119260,-0.360748,0.257196,0.056747,-0.351395,0.087912,-0.027852,-0.437001,0.399314,-0.486110,0.230345,0.737210,0.273865,-0.371817,0.540590,0.139989,0.113303,-0.032819,-0.039666,0.009039,0.096160,0.540589,0.205492,0.246411,-0.045088,-0.045662,-0.335084,0.318389', '1297606', '25837175', '2063528', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302193', '改编剧本', '剧情', '女记者苏珊（梅丽尔•斯特里普 Meryl Streep  饰）采访了一个因酷爱兰花，经常偷采兰花而满身官司的“采花贼”，并将此人的故事加工成了传记小说《兰花窃贼》。不久，好莱坞某电影公司将这本书的改编权买了下来，并请来了颇负盛名的改编人查理（尼古拉斯•凯奇 Nicolas Cage 饰）来将它改编成电影剧本。无奈查理已江郎才尽，他绞尽脑汁都无法完成《兰花窃贼》的改编。查理无奈之下只好向原作者苏珊求助，但性格内向的查理见到了美艳华贵的苏珊竟紧张得说不出话来。他只好叫来了对编剧极感兴趣并想涉足其中的弟弟唐纳德来帮忙。兄弟两在改写剧本时历经了一系列曲折。查理突发奇想，将自己改写剧本的创作过程也写进了剧本。这部剧本最后会变成什么样呢？©豆瓣', '尼古拉斯·凯奇', '斯派克·琼斯', 7.6, 24165, 'tt0268126', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p761691475.jpg', 0.7, 4, 29.5, 46.5, 19.4, '0.142494,0.045379,-0.304838,0.463593,0.054731,-0.443558,0.476593,-0.082261,-0.500185,-0.112000,0.197025,0.664311,-0.375892,-0.009149,0.260796,0.114386,-0.561102,-0.476069,-0.004931,-0.325941,0.021014,-0.396651,-0.166883,-0.133142,-0.065376,0.154554,0.354870,-0.198128,-0.245257,0.195814,0.209521,0.165588,-0.005024,0.144649,0.170361,0.434910,-0.097195,-0.281511,-0.109132,0.161924,0.344348,-0.300327,-0.378243,0.255519,-0.044278,0.306885,0.570295,-0.147356,-0.091101,0.095760,0.679265,-0.187841,0.081620,-0.050556,0.123957,0.288628,0.286187,0.006704,-0.251483,0.153056,0.106791,-0.154111,-0.775274,0.383278,-0.078527,0.344135,-0.509751,0.254953,-0.268896,0.069990,-0.132204,-0.529716,0.136893,-0.024595,0.672976,0.296812,0.094700,0.032426,-0.370982,0.698498,0.111072,0.168536,-0.027442,0.460354,-0.033083,-0.340589,0.059022,-0.165338,-0.311554,0.193573,0.541284,0.125794,-0.096935,-0.064061,-0.648830,-0.312680,-0.318088,-0.203499,-0.057767,-0.400025,-0.073306,-0.516669,-0.204483,0.098088,-0.089006,-0.399349,0.213670,-0.184192,0.728914,-0.330143,-0.039681,0.499877,0.063041,-0.269520,0.352099,0.042431,-0.095154,0.097623,-0.098746,0.179922,0.015481,0.349467,0.467694,0.371671,0.330906,-0.483367,-0.386739,0.319839', '27602116', '27199913', '22265121', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302205', '办公室的故事', '剧情', '前苏联时期，莫斯科某统计局女局长洛德尼拉·伯洛哥菲耶夫娜·卡卢金娜（Alisa Freyndlikh 饰）业务能力极强，事业为上，而形成鲜明对比的则是她的私人生活，爱情之花迟迟没有绽放。对于这个表情肃穆古板的上司，职员们背地里叫他“冷血动物”。相貌老成的统计员安里多勒· 耶里姆多维奇·诺瓦谢利采夫（Andrey Myagkov 饰）于青年时代便才华横溢，虽然独自辛勤抚养两个孩子，却为人乐观，颇受同事喜爱。对于“冷血动物”，诺瓦谢利采夫自命清高，不愿自贬身价求助卡卢金娜。而在卡卢金娜眼里，诺瓦谢利采夫唯唯诺诺，能力平庸，毫无闪光之处。适逢轻工业处处长职务从缺，诺瓦谢利采夫有心补位，却不得不面对这个难缠的“顶头天敌”。正所谓不是冤家不聚头，这样性格有着天壤之别的两人，奇妙的爱情竟在彼此心间萌生……©豆瓣', '阿丽萨·弗雷因德利赫', '埃利达尔·梁赞诺夫', 8.8, 19474, 'tt0076727', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2216166945.jpg', 0.2, 0.6, 9.8, 39.4, 50.1, '0.171278,0.005317,-0.763999,0.608741,-0.361729,-0.204281,0.722951,0.309023,-0.678326,-0.305513,-0.034635,0.589673,-0.008359,0.117211,0.138274,-0.084693,-0.209422,-0.524204,-0.168390,0.068281,0.064540,-0.459342,-0.405566,-0.195397,-0.490897,-0.285043,0.457868,-0.066983,-0.033335,0.318397,0.472289,0.648143,0.043142,0.220789,0.044718,-0.272140,0.304512,-0.057698,-0.254710,-0.248165,-0.051976,0.223253,-0.339444,0.131352,0.054981,0.244927,0.316914,-0.217803,-0.091112,-0.355026,0.259986,-0.052137,0.064972,0.202215,0.125782,-0.154348,0.340660,-0.025579,-0.074421,-0.001166,0.086525,-0.078146,-0.687252,0.035968,0.044495,0.225113,-0.276375,0.289415,-0.261913,-0.198346,0.080112,-0.328829,-0.294816,-0.042538,0.164230,0.315832,-0.018660,-0.055584,-0.101370,-0.339261,0.332472,0.441783,-0.754990,0.301196,-0.644775,-0.363968,0.416366,-0.458983,-0.387530,-0.094422,-0.156728,0.024948,0.206054,0.308299,-0.415714,0.218598,-0.300085,0.297625,-0.046774,-0.345656,-0.160149,-0.271958,-0.236846,-0.714969,-0.424759,0.165172,0.191928,-0.032594,0.624905,-0.653077,0.147106,0.202924,-0.015940,-0.163867,0.543623,0.278814,-0.104021,-0.346528,-0.281171,0.318010,0.028507,0.079544,-0.301712,0.196121,-0.071804,-0.288563,-0.015151,0.448694', '1417428', '1308745', '1422954', '1769507');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302209', '星际之门', '动作', '美国军方在地球的某处发现了一个奇怪的圆环，圆环的制造技术完全不同于地球，而且通过测定圆环的历史非常久远甚至可以追溯到人类出现之前，圆环上还刻有很多奇怪的符号。这个圆环到底有什么作用？考古学家丹尼尔·杰克逊（詹姆斯·斯派德 James Spader 饰）博士对古埃及的象形文字及其历史有很深的研究，而且对金字塔的建造也有一套自己的理论，可是他的观点却无法被人所接受。为了能寻找有力的证据，他开始对军方发现的这个圆环进行研究，却发现这个圆环却是一个高科技产物，通过特定编码的推动能与另外一个圆环联通，形成一个虫洞，可以进行超长距离且耗时极短的空间旅行。为了探知圆环联通的另一端到底有什么，丹尼尔与杰克·欧尼尔（库尔特·拉塞尔 Kurt Russell 饰）上校为首的军方小队一起穿越这星际之门，进入另外一个世界探险。在另一边，他们发现了很多令人无法相信的事情，金字塔的建造之谜、外星人是否到访过地球这些不解之谜都有了一个新的解读……', '詹姆斯·斯派德', '罗兰·艾默里奇', 7.2, 16028, 'tt0111282', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p460477140.jpg', 0.9, 5.2, 39.5, 39.9, 14.5, '0.432635,-0.007097,-0.749653,0.911507,-0.140329,0.184870,0.789463,-0.306886,-0.516971,-0.570066,0.058059,0.802151,-0.289100,0.012289,-0.218915,0.120876,-0.189586,-0.295490,0.191051,-0.331644,-0.813124,-0.671579,-0.618237,-0.215898,-0.075223,-0.194225,0.886655,0.166754,-0.205909,0.056441,-0.156703,0.282289,-0.108352,0.353264,-0.420218,-0.166666,0.164774,0.026359,-0.126667,0.015753,-0.132267,0.112133,0.220196,0.380518,-0.402674,0.333711,0.507614,-0.475257,-0.052740,0.068660,0.519446,-0.099494,-0.219519,-0.043111,0.277387,0.324474,-0.293102,0.089589,-0.092765,0.051604,0.115794,-0.104798,-1.087681,-0.220781,0.110417,0.402516,-0.388714,0.102333,-0.172757,-0.414151,-0.289410,-0.224374,0.238580,0.652265,0.423522,0.344459,-0.215025,-0.014920,-0.699348,-0.145542,0.277253,0.048089,-0.783794,0.459338,-0.338504,-0.633518,-0.191960,0.027942,0.007456,-0.053205,0.187507,0.038286,-0.112949,-0.016875,-0.848332,0.415662,-0.221115,-0.137237,0.097146,-0.453082,-0.201867,-0.830212,-0.226439,-0.429346,-0.368922,0.116740,-0.042153,-0.225049,0.698747,-0.837280,0.016432,0.541540,0.376849,-0.378651,0.759434,0.159860,-0.034350,-0.584115,-0.283116,0.115401,0.006012,0.448807,-0.244576,0.510144,0.519101,-0.347607,-0.638075,0.366141', '1793491', '1293433', '1308585', '1416898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302233', '情人眼里出西施', '剧情', '哈尔（杰克•布莱克 饰）的父亲竟然在临终前跟儿子说以后一定要找最美丽的女孩做终身伴侣。于是他开始上演追逐不同美女的戏码，可是他的相貌平平，遇到了不少挫折。早已过了而立之年的他仍不愿违背父亲的遗愿，直到他受到了某位专家的催眠，逐步改变他以貌取人的的毛病，他观赏美女的的眼光竟然开始了很大程度上的的下降，后来他甚至爱上了体重达到150公斤的露丝玛丽（格温妮丝•帕特洛 饰），哈尔全然不介意露丝玛丽笨重的身材，他感觉自己的女友是最善良的人，无可救药的彻底爱上了对方。好友马里西奥不忍哈尔有个相貌如此不堪的女友，经想方设法要破除掉施用在哈尔身上的催眠术……©豆瓣', '格温妮斯·帕特洛', '博比·法雷里', 7.1, 7512, 'tt0256380', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1371979021.jpg', 0.9, 4.9, 46.4, 36.2, 11.5, '0.311534,-0.198087,-0.687320,0.597607,-0.603851,-0.362076,0.904235,0.222726,-0.583712,-0.173369,0.432898,0.810711,-0.264766,0.184843,0.297575,0.229353,-0.211378,-0.579512,0.168221,-0.082623,-0.237958,-0.474451,-0.380297,0.079208,-0.192173,-0.394405,0.499555,-0.182903,-0.302762,0.125803,0.276701,0.140056,0.565434,0.572680,-0.248359,0.123613,-0.085330,-0.160461,0.166639,0.117077,0.297584,-0.231267,0.083666,0.390600,-0.364242,0.464274,0.571827,-0.168200,-0.040592,-0.163436,0.478345,-0.072302,0.199423,0.245490,0.038157,-0.240088,0.177413,0.046626,-0.105579,-0.284596,0.147407,0.015316,-0.565189,0.080252,0.102962,0.116827,-0.665542,0.270539,-0.290293,0.085969,-0.005613,-0.337589,-0.134407,0.102469,0.080165,0.135503,-0.302562,-0.130611,-0.578793,0.122092,0.546586,0.304372,-0.285799,0.392248,-0.331875,-0.408963,-0.086540,-0.451575,-0.628185,0.115908,0.225718,0.030597,-0.333650,0.388132,-0.468893,-0.236478,-0.421204,-0.078554,-0.045941,-0.266098,-0.103404,-0.320424,-0.259356,-0.728678,-0.375868,-0.171393,-0.017680,-0.427619,0.765268,-0.879602,0.097667,0.488677,0.260688,-0.449027,0.520664,0.176139,-0.127190,-0.067993,-0.267819,0.445199,-0.102171,0.191127,0.151577,0.433437,0.208437,-0.202338,-0.362806,0.840007', '1292062', '24756472', '4275444', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302235', '茜茜公主2', '剧情', '维也纳盛大的皇家婚礼之后，茜茜（罗密·施奈德 Romy Schneider 饰）开始皇后的生活。她慢慢地调整自己以适应奥地利宫廷生活，但她发现与皇太后苏菲（玛达·施耐德 Magda Schneider 饰）相处非常艰难。专横的皇太后恪守着皇室的陈规陋习，并不断地向弗兰兹（卡尔亨兹·伯恩 Karlheinz Böhm 饰）灌输应该怎样遵守皇室法规去经营帝国和家庭。茜茜的女儿出生之后，她和苏菲之间的矛盾进一步激化。苏菲依据皇室的规矩不让茜茜自己抚养女儿，而弗兰兹竟然顺从母意，让茜茜与女儿无法在一起。伤心失望的茜茜只身一人回到巴伐利亚。愧疚弗兰兹立刻追随而至，劝服茜茜和他一起返回奥地利。这时，苏菲也不得不改变主意同意茜茜抚养女儿。之后，茜茜伴随弗兰兹出访多国，在匈牙利她受到了热烈的欢迎，他们在匈牙利人民的欢呼声中加冕为奥匈帝国的国王和皇后。影片获得第10届戛纳电影节金棕榈奖提名。', '罗密·施耐德', '恩斯特·马里施卡', 8.4, 38785, 'tt0049762', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2160427412.jpg', 0.1, 0.7, 14.9, 45.5, 38.8, '0.039368,0.394231,-0.878679,0.850244,0.263308,-0.253813,0.415387,0.271050,-0.503301,-0.108254,0.152433,0.768535,-0.084508,0.025220,0.498866,0.126051,-0.744946,-0.716657,0.060522,-0.024413,-0.175468,-0.411232,0.182479,-0.414843,-0.322107,-0.407027,0.647766,-0.189952,-0.048367,0.543961,0.388259,0.296561,0.033652,0.223878,0.006877,-0.001049,0.151713,-0.026737,-0.478954,0.104975,0.231359,0.052863,-0.485767,0.279146,0.384896,0.223492,0.464061,-0.408959,0.326779,-0.339331,0.441252,-0.189304,0.121314,0.170148,-0.008142,0.082532,0.250653,0.430186,-0.146091,-0.063721,-0.166708,-0.270548,-0.296652,0.202481,0.127344,0.142653,-0.622899,0.455875,-0.192312,-0.243679,0.108057,-0.325665,0.105871,0.875928,0.085692,0.364219,-0.343244,0.162051,-0.349629,-0.091776,0.773113,-0.100598,-0.420285,0.058551,-0.288603,-0.399549,0.101824,-0.305789,-0.768855,-0.256015,0.151548,-0.013306,0.201453,0.548270,-0.388873,-0.310324,-0.466153,-0.412817,0.411892,-0.466158,0.385813,-0.500464,-0.172196,-0.436356,-0.277202,-0.103981,-0.028894,-0.209286,0.618172,-0.699281,0.317424,0.294978,0.635889,-0.660087,0.379691,0.206456,0.261837,-0.280477,-0.335698,0.510591,-0.115723,-0.085257,-0.068986,0.161490,0.254071,0.137064,-0.319401,0.374895', '13