INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302242', '特务迷城', '喜剧', '从小习武的健身器材店营业员小北（成龙）有奇异的预感能力，梦想有天成为特务。凭借预感及身手，小北将打劫银行的劫匪当场逮捕，成为新闻人物，引来私家侦探的注意，怀疑他可能是其韩国客户朴元正失散多年的儿子，决定带他去见朴元正的律师。好奇心驱使，小北决定跟随律师到韩国寻找身世之谜，不想刚与朴元正见面对方就过世。从美国某周刊女记者福喜（金玫）口中，小北知晓朴氏夫妇本为著名的双重特务，遵循着朴元正的遗言，小北在福喜的帮助下又来到土耳其找到了一笔鉅款，并邂逅了神秘女子咏（徐若瑄）。得意忘形之际，小北开始遭遇一连串莫名其妙的袭击，令他意识到身边早已危机四伏。©豆瓣', '成龙', '陈德森', 6.6, 27377, 'tt0271946', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2634397015.jpg', 1, 7.4, 57.3, 26.7, 7.5, '0.103126,-0.006080,-0.623895,0.163365,0.208365,-0.218950,0.334061,0.134997,-0.568099,-0.329007,0.337764,0.634981,-0.199603,0.369171,0.557304,0.133271,0.030749,-0.543493,0.057892,0.021547,-0.018746,-0.410190,-0.195158,-0.065138,0.006308,-0.248053,0.369402,-0.043252,-0.451924,0.524531,0.140047,0.404622,-0.364501,0.614326,-0.069596,0.159612,0.152499,-0.182658,-0.463896,0.060807,0.158197,-0.202069,0.031719,0.006947,-0.094809,0.131309,0.374704,-0.049656,-0.166654,-0.070138,0.425590,-0.095141,-0.091989,0.013187,0.421748,0.360837,0.111961,0.107069,-0.195647,0.031050,0.005719,0.009681,-0.416012,0.124192,0.066333,0.313221,-0.398349,-0.131735,-0.135881,0.045580,0.206867,-0.303267,0.185524,0.072985,0.178000,0.321317,-0.060329,0.256384,-0.303936,-0.134380,0.573067,-0.188851,0.246638,0.245136,0.107848,-0.213015,0.292191,0.096410,-0.029904,0.029449,0.132938,0.245154,-0.266010,-0.047278,-0.295395,-0.067883,-0.211133,0.166930,0.244499,-0.237409,-0.093455,-0.529347,-0.154809,0.115135,-0.233107,0.101731,0.167295,-0.212868,0.659677,-0.673228,0.190707,0.695456,0.326606,-0.546826,0.464342,-0.051370,-0.078376,-0.118674,-0.188724,0.138995,0.084494,0.363036,-0.127204,-0.007305,-0.161163,-0.324418,0.091567,0.068823', '3285622', '1480318', '35030151', '1294497');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302244', '咒乐园', '剧情', '14年前，某梦幻乐园突发事故，一小女孩从摩天轮上坠落丧生。自此，乐园仿佛被施以毒咒，伤亡事件不断，最终导致乐园被迫关闭。天伦（萧正楠 饰）当年曾目睹惨剧的发生，某天他在图书馆翻阅到该事件的报道，遂萌生调查的念头，然而却从此消失人间。天伦的妹妹昕（陈文媛 饰）不相信母亲关于哥哥已死的定论，约上Ken、Pinky、山、Dan、YY、家豪等六名好友，一同前往废弃的乐园寻找天伦。青年男女们并未理会神秘老头的警告，反而带着些许玩乐的心态走入乐园。他们从此走上了一条血腥的不归路……©豆瓣', '陈文媛', '刘伟强', 6, 10940, 'tt0385598', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2327995315.jpg', 6.4, 19.8, 48.7, 17.8, 7.3, '0.488967,0.068095,-0.602320,0.086196,0.363748,-0.202742,0.699212,0.268404,-0.507376,-0.076994,0.455091,0.645645,-0.350150,0.207644,0.296866,-0.317358,-0.409374,-0.392788,-0.091790,-0.247288,-0.158971,-0.250587,-0.019514,0.047164,0.035799,-0.150762,0.572616,0.220578,-0.171223,0.706785,0.118643,0.376567,-0.784382,0.381078,-0.203795,0.006792,0.087348,0.354565,-0.353083,0.208232,-0.286934,-0.448271,-0.073937,-0.059348,-0.155191,0.157095,0.895285,-0.468742,-0.339619,-0.200005,0.280512,-0.264214,-0.072053,0.101741,0.208865,0.327308,0.058859,0.614025,-0.142894,-0.214249,-0.010468,-0.170598,-0.136277,0.016023,0.046633,0.494618,-0.344361,0.116399,0.146399,0.020815,0.137316,-0.157700,0.183437,0.245825,0.233618,0.277363,-0.003690,0.030821,-0.310033,0.254749,0.778694,-0.330837,-0.036625,0.294871,0.159374,-0.165676,-0.079243,0.035543,-0.465344,0.067837,0.291701,0.144393,-0.393954,0.458862,-0.569905,-0.084139,-0.448977,-0.209371,-0.035703,0.085162,-0.245382,-0.584364,-0.044163,0.165267,-0.253677,0.184898,0.028487,-0.009491,0.362678,-0.631566,0.632350,0.347920,0.194708,-0.654493,0.484654,-0.054724,0.009144,-0.176191,0.114955,0.594442,-0.022811,0.407089,-0.405379,-0.013428,-0.048929,-0.117560,-0.457510,0.147888', '1914923', '1309194', '1299433', '1773217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302271', '的士速递2', '喜剧', '魔鬼出租车司机达尼埃尔（萨米·纳塞利 Samy Naceri 饰）依旧每天在公路上风驰电掣，这天他因为开车运送临产孕妇而一举夺得赛车冠军，同时也耽搁了和女友莉莉（玛丽昂·歌迪亚 Marion Cotillard 饰）父母见面的约会，但达尼埃尔很快用速度帮助了接见日本防卫部长的未来将军岳父。与此同时，考驾照再次失败的埃米利安（佛瑞德瑞克·迪分索 Frédéric Diefenthal 饰）奉命一同迎接日本部长，与达尼埃尔在机场重逢。警察局长在车队行进途中安排了反恐演习向日本客人展示法国的先进技术和干练部队，而暗处的一股日本黑帮正计划劫持部长。达尼埃尔和埃米利安联手为国家尊严而战……©豆瓣', '萨米·纳塞利', '热拉尔·克瓦兹克', 7.9, 51060, 'tt0183869', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1339506474.jpg', 0.2, 1.4, 23.6, 53.5, 21.4, '0.152553,-0.137753,-0.569142,0.460509,0.122758,-0.687741,0.254201,0.488292,-0.400703,-0.098475,0.134226,0.719969,0.058939,-0.453824,0.821052,0.009402,-0.656990,-0.450810,0.123221,0.118941,-0.155372,-0.599178,-0.054849,-0.346810,0.191579,-0.391016,0.143807,-0.244507,0.153600,0.827447,0.091037,0.218899,-0.199480,0.267277,-0.026338,-0.311784,0.582755,-0.496555,-0.465963,0.427157,-0.021294,0.171958,-0.129400,-0.090792,0.045900,0.296771,0.463962,0.210452,0.299948,-0.360969,0.022702,-0.247900,0.344848,-0.197301,0.304666,0.063791,0.119231,0.148714,0.041209,-0.198506,-0.061557,-0.072715,-0.213600,0.216882,-0.205953,-0.038188,-0.566310,0.366100,-0.389341,0.187270,0.496606,-0.383115,0.225583,0.511141,-0.059375,0.076096,-0.088418,-0.073455,-0.526797,-0.184080,0.532485,-0.052246,0.236782,-0.075138,-0.010751,-0.238897,0.330899,-0.085846,-0.466137,-0.127702,0.140410,-0.288431,0.319456,0.188067,-0.534102,-0.164189,-0.707305,-0.198115,0.039257,-0.190075,0.296734,-1.154894,0.115029,-0.329975,-0.026571,-0.056207,0.197439,0.272983,0.364413,-0.666836,0.340571,0.652403,0.375485,-0.273687,0.653442,0.125789,0.249018,-0.311975,0.026398,0.095989,-0.106535,0.563504,-0.122175,0.295002,0.246109,-0.316409,-0.011385,0.306387', '2075345', '25833539', '3036464', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302279', '俄罗斯方舟', '剧情', '一名当代电影人与另一个来自19世纪的法国外交官（Sergei Dontsov 饰）发现自己置身于圣彼得堡的一座古老的宫殿中，周围的人完全看不到他们。两人结伴在宫殿中徘徊，见证了暴怒的彼得大帝用鞭子抽打他的将军；凯瑟琳女皇的私人生活；革命前夕末代沙皇一家最后的晚餐以及1913年最后一场辉煌盛大的宫廷舞会。短短100分钟内，亲身经历了俄国200多年的历史……本片荣获2004年阿根廷影展最佳外语片奖、2003年德国相机奖剧情片荣誉奖、2003年西班牙奇幻电影奖最佳男主角（Sergei Dontsov），最佳剧本和最佳导演、2004年尼卡奖最佳美术指导、2003年旧金山影评人协会荣誉奖、2002年多伦多国际电影节视觉奖。©豆瓣', '谢尔盖·德雷登', '亚历山大·索科洛夫', 7.6, 12332, 'tt0318034', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2183461246.jpg', 1.3, 5.2, 29.4, 42.1, 22, '-0.288772,0.056245,-0.466269,0.863768,0.568725,0.010658,0.336787,-0.214343,-0.624796,-0.297748,0.415595,1.102486,-0.563206,0.085694,0.625254,-0.061356,-0.496827,-1.043275,-0.307890,-0.312771,-0.123426,0.053817,-0.549304,-0.219749,-0.311105,-0.218238,0.746493,0.018482,0.126692,0.623601,0.473484,-0.053880,0.173617,-0.265700,-0.004749,-0.068128,0.634560,-0.058984,-0.505715,0.512378,-0.072145,-0.573286,-0.441516,0.048325,0.049984,0.063177,0.615269,-0.185480,0.250454,-0.132795,0.668863,-0.244254,-0.410619,0.000036,0.430436,-0.131730,0.265849,0.367798,-0.082215,0.022724,-0.108069,-0.556487,-0.531423,0.111243,-0.110560,-0.015963,-0.336423,0.816138,0.109004,0.339823,-0.251902,0.033202,0.373762,0.089992,0.420578,0.361007,-0.029055,-0.090657,-0.150292,1.072660,0.536257,0.014586,-0.603157,0.069230,-0.162991,-0.693452,-0.186741,-0.546854,-0.406660,0.240319,0.372807,0.078910,0.076145,0.115359,-0.656553,0.273946,-0.191918,-0.532564,0.161461,-0.162260,-0.268369,-1.002872,-0.091817,-0.287341,0.017155,-0.000287,-0.144370,-0.008545,0.780560,-0.343866,0.416528,0.515515,0.149483,0.071239,1.244876,-0.091824,-0.165461,-0.134313,-0.266856,0.237815,-0.501147,0.091153,-0.194236,0.220405,-0.155247,-0.356508,-0.230621,0.408841', '1780122', '1297368', '30397916', '1297920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302292', '狱中龙', '动作', '富家子弟张荣日（何家劲 饰）因冲动犯事儿进入劳役中心服刑，他老实内向，对道上规矩更是一窍不通，因此饱受虾毛等人欺负，在此期间他结识了颇讲义气的阿豪（刘德华 饰），二人成为莫逆之交。此后他们洗心革面，齐心向学，更通过了中学会考。出狱后，身份不同的两个人也自然走上不同的人生路。荣日飞赴英国，研读法律；阿豪则因家境贫苦，终日为生计奔波，却当年的仇家马超追杀，最终被迫随虾毛遁入黑道。日光荏苒，转眼6年过去。荣日学业有成，顺利归国。阿豪也在腥风血雨中拚杀出自己的一片天空。适值此时，马超设计陷害阿豪，这也促使分处黑白两个世界荣日和阿豪站在同一法庭上。只是时过境迁，个中滋味谁人知……©豆瓣', '刘德华', '郑则仕', 7, 6296, 'tt0100995', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2222648692.jpg', 0.8, 6.3, 48.4, 30.8, 13.8, '0.065681,0.046217,-0.551451,0.262847,0.007163,-0.318926,0.309614,0.219789,-0.523613,-0.156076,0.097729,0.310980,0.000876,0.348655,0.160123,-0.251617,-0.278438,-0.604466,0.069038,-0.250908,-0.116559,-0.212249,-0.067812,0.019862,-0.322140,0.085079,0.384747,0.085970,-0.006447,0.520378,0.163230,-0.093552,-0.233229,0.144886,-0.096314,-0.048659,-0.222796,0.243858,-0.262574,-0.309015,-0.296203,-0.374364,-0.267711,-0.234104,0.066579,0.397312,0.528816,-0.088982,-0.093069,-0.221170,0.444469,-0.328272,-0.189259,0.137638,0.324244,-0.013177,0.243751,0.220242,-0.068366,0.127456,-0.359155,-0.002175,-0.395643,-0.004306,0.012982,0.035088,-0.326838,0.468799,0.066625,-0.301459,-0.309720,-0.326009,-0.050110,0.296620,0.104655,0.340164,-0.075937,0.063452,-0.240376,0.180062,0.793293,0.069788,-0.119140,-0.110426,-0.023955,-0.208097,0.102929,-0.180894,-0.210081,-0.270508,0.238908,-0.158829,0.003089,0.316995,-0.394395,0.208586,-0.111990,0.209154,-0.090154,-0.126895,0.063046,-0.328364,-0.061113,-0.369761,-0.514202,0.087923,0.028127,-0.191285,0.453412,-0.445348,0.059427,0.167832,0.190699,-0.631042,0.523088,0.207973,0.313714,-0.073497,-0.034703,0.347829,0.213291,0.191700,-0.039436,0.176365,-0.042388,-0.006062,-0.171128,0.152822', '1294713', '25721544', '4145476', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302303', '原罪', '剧情', '在十九世纪的古巴，当地咖啡业富商路易斯（安东尼奥•班德拉斯 饰）要迎娶一个邮购新娘。路易斯从未见过这名美国女子茱莉亚（安吉丽娜•朱丽 饰），当他在码头首次见到这位妻子的时候，茱莉亚的美貌令他倾心。但他不知道这位美丽新娘满脑诡计。新婚生活让路易斯幸福无比，他以为幸福日子可以一直这样持续下去。路易斯发现他的妻子并不是他想象中那样单纯。茱莉亚隐藏着一连串的谎言，最终目的都是路易斯的巨大财富。看似幸福的生活，就此暗藏了许多暗涌与变数。©豆瓣', '安东尼奥·班德拉斯', '迈克尔·克里斯托弗', 7.4, 70755, 'tt0218922', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2563026581.jpg', 0.4, 3.1, 36.1, 44.7, 15.8, '0.014890,0.256804,-0.675233,0.655706,-0.201259,-0.047706,1.045240,-0.007788,-0.430104,-0.441794,0.133468,0.814582,-0.118518,0.263736,0.214510,0.233819,-0.267798,-0.385079,0.018134,-0.135561,0.076196,-0.272670,-0.185465,-0.323447,-0.108716,-0.269780,0.579829,0.134951,0.123269,0.471416,0.307288,0.332466,0.222234,0.452148,-0.254200,-0.285008,0.231413,0.188897,-0.277099,0.211170,-0.176313,-0.270166,-0.139547,0.503120,-0.193942,0.009673,0.441981,-0.118986,-0.046078,-0.005029,0.107218,-0.195230,0.094521,0.170538,0.146230,-0.382492,0.077735,0.057158,-0.218186,-0.184225,0.260380,-0.106739,-0.651726,0.082273,-0.011479,0.303680,-0.402589,0.342831,-0.284691,-0.047819,0.103246,-0.255023,0.056046,0.164834,0.342420,0.225318,-0.203344,0.300656,-0.670805,0.406474,0.785241,0.063717,-0.267975,0.558076,-0.605014,-0.280082,-0.041403,-0.186965,-0.829574,0.032824,0.049106,0.007329,-0.209988,0.484853,-0.388380,0.013232,-0.388889,0.007914,0.025998,-0.532225,-0.199836,-0.393450,-0.313426,-0.566088,-0.450642,-0.148981,-0.066781,-0.320237,0.753807,-0.734645,0.229609,0.640956,0.163156,-0.509409,0.749586,0.594512,-0.048599,-0.164557,-0.222630,0.516051,-0.035467,-0.243645,-0.182488,0.443362,0.139022,0.057466,-0.117574,0.774020', '1304641', '4275444', '1292062', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302325', '毁灭之路', '剧情', '迈克尔(汤姆•汉克斯 Tom Hanks 饰)是美国芝加哥一个黑帮老大鲁尼的养子，他一直是鲁尼得力的左右手――帮派中令人恐惧的杀手“死亡天使”。迈克尔虽然杀人不眨眼，但现实中却是一个温文尔雅，烟酒不沾的好丈夫、好父亲。他的两个儿子一直都不知道父亲的职业，直到大儿子小迈克尔12岁了。一天他偷溜进父亲的汽车决定探知父亲的职业。小迈克尔目睹了一起杀人案，他的行为也被帮会知悉了。帮会怕他走漏风声，然而迈克尔却以“他是我的儿子”为由保证他一定不会走漏消息。然而，迈克尔的妻子和他的小儿子却遭帮会误杀了，他们本来的目标是他和小迈克尔。父子两开始了亡命天涯和复仇之路!©豆瓣', '汤姆·汉克斯', '萨姆·门德斯', 7.7, 41563, 'tt0257044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2644634834.jpg', 0.3, 1.8, 27.3, 52.2, 18.5, '0.190866,0.036089,-0.690163,0.710432,-0.473017,-0.447610,0.752635,0.127760,-0.557782,-0.129749,0.338046,1.018613,0.118714,0.460500,-0.071553,0.148728,-0.084547,-0.751798,-0.200812,-0.252014,-0.140375,-0.455436,-0.277247,-0.238267,-0.098319,0.093454,0.497992,-0.108421,0.047495,0.198169,0.482494,0.067446,0.208956,0.521673,-0.048166,0.154017,0.168596,-0.222842,-0.145907,-0.075608,0.246010,-0.222437,-0.175382,0.245811,0.006066,0.665041,0.382471,-0.283587,-0.039253,-0.388385,0.194559,-0.395695,-0.095123,0.136931,0.331198,-0.354322,0.357235,0.432850,0.118704,-0.201126,-0.071304,0.103794,-0.799571,0.138458,0.114559,0.016532,-0.636082,0.380204,-0.378985,-0.007081,0.219295,-0.259073,0.118285,0.102076,0.256326,0.237986,-0.259544,0.065551,-0.541355,0.070165,0.753381,-0.110221,-0.226944,0.058499,-0.132128,-0.430096,-0.153886,-0.466121,-0.598692,0.054395,0.454801,-0.224708,-0.288085,0.285416,-0.356646,-0.005962,-0.328743,-0.091346,-0.331041,-0.447835,0.081308,-0.267961,-0.009055,-0.594223,-0.433932,0.010334,0.025508,-0.332192,0.672497,-0.815117,0.086662,0.771588,0.179131,-0.719226,0.755528,0.355792,0.270897,-0.335466,-0.037939,0.139103,0.017811,0.165013,0.352556,0.355004,0.024938,-0.169547,-0.241329,0.572135', '30162520', '34890458', '1309069', '1299799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302344', '非常小特务', '喜剧', '特工格雷格里奥（安东尼奥•班德拉斯 Antonio Banderas 饰）和英格丽德（卡拉•古奇诺 Carla Gugino 饰）是世界上最顶尖的特工，两人在一次任务中相遇，然后就一发不可收拾的堕入了爱河，从此世界上就少了两名出色的特工，多了一个幸福的家庭。一晃眼九年过去了，平静的世界再起波澜，格雷格里奥以前的战友们一个接一个神秘失踪，这一定是阴谋分子又在兴风作浪。无奈之下，格雷格里奥和英格丽德只好再度出马，不料两人亦同样遭到绑架！这下，重担只能落在两个从小生长在特工之家的小鬼卡门（亚历克斯•维加 Alexa Vega 饰）和朱尼（达里尔•沙巴拉 Daryl Sabara 饰）身上，我们的特工神童出征了。©豆瓣', '达里尔·沙巴拉', '罗伯特·罗德里格兹', 6.5, 15195, 'tt0227538', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1282019678.jpg', 1.9, 10.3, 55.5, 23.7, 8.6, '0.359889,-0.079277,-0.621829,0.474333,-0.294456,-0.433518,0.818270,0.100626,-0.348463,0.099554,0.138439,0.922125,-0.218329,0.119951,0.515818,-0.015480,-0.617952,-0.935163,-0.029719,-0.382560,-0.301465,-0.484593,-0.313592,-0.106916,-0.012598,-0.497536,0.464465,-0.121084,0.110073,0.382293,0.417535,0.562354,-0.376207,0.277645,-0.178299,0.046174,0.484597,-0.127585,-0.103874,0.198055,-0.121865,0.036150,-0.170762,-0.071338,0.097699,0.055660,0.374743,-0.281034,0.168032,-0.218383,0.100359,-0.192902,-0.222711,0.030889,0.561827,-0.351950,0.104034,0.292325,0.019402,0.026241,0.141892,0.067562,-0.595059,0.031579,0.150105,0.049786,-0.648846,0.582407,-0.102377,-0.429309,-0.157229,-0.241461,0.075778,0.391579,0.177538,0.318750,-0.155518,0.002307,-0.286431,-0.137426,0.380748,0.099849,-0.269346,0.086401,0.174363,-0.399004,-0.241065,-0.212937,-0.435678,0.014341,0.585870,-0.228143,-0.053842,0.495509,-0.712246,0.051189,-0.588943,-0.178083,-0.143638,-0.307545,-0.099466,-0.533161,0.083171,-0.299147,-0.519574,0.241101,0.183329,0.092384,0.772476,-0.534367,0.299832,0.370737,0.085755,-0.017499,0.418226,0.240922,0.365205,-0.181031,0.169992,0.239949,0.209480,0.330207,0.182060,0.556706,-0.187984,-0.169336,-0.156859,0.412584', '1307146', '30162520', '25777634', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302377', '甜蜜十一月', '剧情', '漂亮开朗的莎拉（查理兹·塞隆 Charlize Theron 饰）非常热衷于投资“短线”爱情，期限为一个月。总有不少的男人在她身边来来往往，但满月后就会被莎拉果断中止关系。广告商尼尔森（基努·李维斯 Keanu Reeves 饰）成为了这群人当中的一员。他平日有着繁忙的工作，生活了无乐趣。莎拉主动建议尼尔森搬来和自己同住，做个“一个月情人”，让他的生活透进阳光。起初，尼尔森对这个女人的行为非常诧异。但他终于接受了这个建议，住进了莎拉的家。二人就像情侣一样生活，莎拉热情四射的性格让尼尔森的内心重新获得了生活的激情，亦令他真心地爱上了莎拉。然而，合约只有一个月，期满以后，二人的生活将各不相干。分离的日子渐近，尼尔森的心中有着强烈的不舍，更意外的是，他得知了关于莎拉的一个重大秘密，她一个月交往期的背后，藏着残酷的真相。©豆瓣', '基努·里维斯', '帕特·奥康纳', 7.1, 15049, 'tt0230838', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1188968652.jpg', 1.3, 7.2, 40, 37.4, 14.2, '0.301136,0.155834,-0.576711,0.622323,-0.293727,-0.182179,0.711023,0.119652,-0.570607,-0.294169,0.098350,0.673296,-0.371323,0.232108,0.224425,0.087219,-0.278744,-0.700701,-0.036760,-0.210671,-0.051531,-0.552398,-0.042417,-0.304057,-0.261285,-0.306639,0.595542,-0.037708,0.126346,0.517274,0.284901,0.346403,0.259357,0.522071,-0.151518,-0.045784,0.165901,0.045775,-0.276377,0.100282,0.086811,-0.084905,-0.015597,0.232519,0.215807,0.392942,0.648640,-0.040537,-0.469786,0.219874,0.316326,-0.101796,-0.027531,0.155026,0.241435,0.010863,0.126298,0.333616,-0.383011,0.110514,0.006213,-0.114003,-0.634520,0.215400,-0.014221,0.051517,-0.509674,0.381181,-0.033813,-0.093517,0.134963,-0.234285,0.105303,0.504446,0.303698,0.369904,-0.072021,0.120330,-0.460803,0.151998,0.775371,0.067084,-0.303749,0.516139,-0.696591,-0.343447,-0.054720,-0.146527,-0.596173,-0.114729,0.277498,0.086350,-0.345267,0.478799,-0.640465,0.145771,-0.144118,-0.184422,0.188399,-0.534884,0.063409,-0.554495,-0.407503,-0.615615,-0.634773,-0.157272,0.042013,-0.452564,0.788381,-0.843194,0.243246,0.451406,0.249022,-0.517177,0.743765,0.274666,0.185303,-0.040452,0.233256,0.432807,-0.096893,-0.007365,0.084704,0.349997,-0.141321,-0.047166,-0.355539,0.605394', '1309161', '35030151', '3230462', '1303112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302379', '坏小子特攻', '剧情', 'King（郑伊健 饰）跟Queen（杨恭如 饰）是兄妹，他们跟Jack（古天乐 饰）组成的“BadBoy特工”专门为人寻找失去的爱情。台湾首富容永兴想找他们寻回初恋情人——亚洲女飞人管正（舒淇 饰），同时青年天涯（陈晓东 饰）也来寻找失踪的情人Shadow（舒淇 饰），没想到管正和Shadow有着同样的面孔。更没想到的是King在酒吧里认识了失忆的Eleven（舒淇 饰）跟管正、Shadow十分相似。多情的King爱上了Eleven，后来Eleven被抓走。天涯找到了Shadow，原来日本野心家企图把从管正身上取得的DNA注入Shadow体内，失败后Shadow毁容。得知情况后，King跟Jack立即营救Eleven。©豆瓣', '郑伊健', '叶伟民', 6, 7223, 'tt0284878', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2375723263.jpg', 3.2, 16.8, 61, 14.8, 4.2, '0.202240,-0.337776,-0.480306,0.494515,-0.009913,-0.374649,0.539775,-0.001259,-0.592353,-0.245328,-0.156258,0.746784,-0.277896,0.059887,0.268286,0.095888,-0.261657,-0.873754,-0.106733,-0.161481,-0.310446,-0.519498,-0.390827,0.051498,-0.005332,-0.344991,0.629532,0.014512,-0.331656,0.801859,0.533502,0.549609,-0.368181,0.311465,-0.200415,0.136894,-0.033074,0.225152,-0.299810,0.400231,0.203034,-0.222551,0.148053,0.086134,-0.175610,0.399861,0.576254,-0.036037,0.087510,-0.308502,0.163598,-0.210825,-0.230989,-0.073060,0.216001,0.054668,0.347926,0.318703,-0.431735,-0.030346,0.404470,-0.025430,-0.650765,0.302179,0.455046,0.128585,-0.549716,0.088855,-0.253641,-0.288946,0.306959,-0.255523,0.529876,0.381442,0.320387,0.114469,-0.019880,-0.106771,-0.721587,0.211074,0.599774,-0.075424,0.257027,0.352270,0.262716,-0.214402,0.034478,-0.202513,-0.115545,0.325406,-0.122097,0.280492,-0.185533,-0.140308,-0.640951,-0.139783,-0.237379,0.069918,0.252290,-0.407268,-0.212783,-0.390956,-0.484838,-0.471008,-0.146785,0.058294,-0.045190,-0.104690,0.567329,-0.970142,0.098677,0.129908,0.495038,-0.713027,0.694262,0.034001,-0.175170,-0.356549,0.108748,-0.181180,0.221860,0.232598,0.040690,0.046633,-0.106327,-0.364334,-0.495583,-0.075238', '30345227', '35030151', '1410695', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302384', '赵先生', '剧情', '上海市下岗女工周若敏（张芝华）无意中发现在某所大学任教师的丈夫赵先生（施京明）与从前的女学生田静（陈怡南）在搞婚外情时，于深夜对丈夫实施了凌厉攻势，要他在她与情人之间做出选择，赵先生不置可否。第二日，田静告诉赵先生说她已怀上他的孩子，也要赵先生给个交代，赵先生依旧含糊其辞。赵先生的不表态令田静非常伤心，赶去医院做了人工流产，闻讯赶来的赵先生在手术室外与田静的一位朋友交谈时渐处下风落荒而逃，在街上被卡车撞倒成为植物人。此时，他脑子里不再有妻子和情人，代替她们出现的是赵先生出车祸前一晚在办公室无意间邂逅的异地美丽女子（蒋雯丽）。©豆瓣', '施京明', '吕乐', 7.8, 9994, 'tt0166890', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2006857702.jpg', 0.6, 2.4, 26, 50.7, 20.4, '0.302153,-0.107309,-0.606875,0.342933,-0.154230,-0.216906,0.929948,0.078859,-0.546179,-0.380557,0.103975,0.852484,-0.225830,0.365119,0.348196,0.017143,-0.249576,-0.550883,-0.041388,-0.040313,-0.213076,-0.575377,0.186363,-0.104306,-0.135634,-0.112290,0.439454,-0.112401,-0.153734,0.342682,0.226210,0.221774,-0.223578,0.491233,-0.267422,0.061062,0.044365,0.332062,-0.299739,0.267939,0.149506,-0.340275,-0.226632,-0.096704,0.006609,0.297148,0.490756,0.228081,-0.303184,-0.021089,0.319911,-0.158754,0.203479,0.161885,0.491455,-0.239585,0.274010,0.087313,-0.240727,-0.132372,0.030356,0.028693,-0.230944,0.082183,0.082393,0.123644,-0.714307,0.487469,-0.058405,0.150473,0.303055,-0.487962,0.427585,0.310485,-0.016074,0.274896,-0.129326,-0.067789,-0.569555,0.162380,0.633769,0.338270,-0.020589,0.349985,-0.138764,-0.385014,0.194518,0.039017,-0.568321,0.070937,-0.003462,0.073380,-0.496868,0.006774,-0.071903,-0.228219,0.003443,0.092926,-0.066695,-0.537420,-0.193633,-0.384487,-0.019575,-0.289911,-0.267689,0.135479,0.012001,-0.198650,0.529494,-1.028670,0.173374,0.263490,0.427244,-0.460757,1.031018,0.285143,0.101596,-0.274743,0.084694,-0.085183,0.125277,0.225292,0.129184,0.368668,-0.132138,-0.006943,-0.414045,0.066974', '2052978', '3055049', '1308755', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302393', '僵尸叔叔', '喜剧', '偏僻山间，一僧一道比邻而居。和尚（午马 饰）随和开朗，更有一女徒菁菁（李丽珍 饰）玲珑可爱；道士（陈友 饰）古板严厉，而徒弟嘉乐（钱嘉乐 饰）却鬼马顽皮。性格不同的两个师傅口角不断，大斗其法，两个冤家徒弟也搞笑连连，笑料频出。某天，一支奇异的丧葬队伍路过此地，某边疆皇族中尸毒死去，幻化成僵尸，千鹤道长及王子护送棺木上京。途中遭遇暴雨，棺木被雷劈开，僵尸破棺而出，大开杀戒。乌侍郎（元华 饰）携王子侥幸逃命，但王子已中尸毒。和尚与道士命徒儿照看王子，两人则冲入树林寻找千鹤道长……©豆瓣', '午马', '刘观伟', 8.1, 35167, 'tt0099881', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2217843198.jpg', 0.3, 1.7, 20.5, 46.1, 31.5, '-0.041768,-0.237648,0.071262,0.130544,0.197636,-0.163247,0.765115,0.373476,-0.219352,-0.281420,0.668094,0.153347,-0.121358,-0.253467,0.110123,0.076788,0.231870,0.110905,-0.045140,0.010311,0.118093,-0.048488,0.057783,-0.076023,-0.138892,-0.398711,0.255540,-0.025037,0.246458,0.728377,0.136196,0.033630,-0.742843,0.044801,-0.153099,0.214597,-0.090090,0.014397,0.104682,-0.073970,-0.331242,0.026523,-0.074071,-0.363786,-0.227113,0.323352,0.547602,-0.226385,-0.030290,-0.320739,0.166191,-0.039926,-0.164046,0.223959,0.399131,-0.066988,0.482481,-0.139160,0.266951,-0.286292,0.002512,0.009580,0.204334,0.499547,0.231176,0.011921,-0.192341,0.135071,0.064395,-0.143501,0.029575,-0.429748,0.145567,-0.146492,0.263846,0.004401,-0.189614,-0.010553,-0.410252,0.144626,0.189606,-0.102036,0.191734,-0.101802,0.001801,-0.204289,0.478292,-0.100027,-0.054205,0.142637,0.489980,-0.551492,0.098496,0.238577,-0.345045,0.030593,-0.406595,0.735879,-0.157629,0.027307,-0.253436,-0.427204,0.276628,0.113656,0.022441,-0.078161,0.219654,0.338779,0.597263,-0.349345,0.161103,0.269770,0.121837,-0.067237,0.408560,-0.229978,0.076916,-0.144300,-0.182993,-0.009939,-0.019217,0.309103,0.126846,0.522049,-0.181627,-0.026234,-0.131729,-0.451029', '1296629', '10466639', '1578663', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302413', '穆谢特', '剧情', '14岁的少女穆谢特（Nadine Nortier 饰）生活在法国的乡间，她的童年暗淡无味，充满艰辛。父亲（Paul Hebert 饰）是一个贩卖私酒的贪杯酒鬼，对家务不管不顾；母亲（Marie Cardinal 饰）病入膏肓，终日躺在床上等待死神的莅临；尚在襁褓中的弟弟整天哭闹不止，令人心烦气躁。家庭的磨难让这个小女孩过早成熟，她打工赚来的钱被父亲抢走，还经常遭到殴打。她在学校受到同学的嘲笑和欺负，倔强的穆谢特只能通过在放学时向同学丢土块宣泄心中的不满。原本应该充满快乐的花季童年，就这样过早地凋谢了……本片荣获1967年戛纳电影节OCIC奖、1968年法国电影评论协会奖最佳影片奖、1969年意大利电影新闻记者协会银兔奖最佳外语片导演奖、1967年威尼斯电影节Pasinetti最佳影片奖。©豆瓣', '娜丁·诺蒂尔', '罗伯特·布列松', 8.5, 6972, 'tt0061996', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1710495655.jpg', 0.3, 0.8, 13.2, 46.6, 39.1, '-0.098216,-0.145253,-0.466495,0.289376,-0.121802,-0.101679,0.498582,0.079031,-0.480070,-0.052670,0.092677,0.784978,-0.278925,0.570575,0.200899,-0.200229,-0.287252,-0.578207,-0.211744,-0.015974,-0.017912,-0.061885,0.003111,-0.130138,-0.314806,-0.417420,0.731702,-0.017989,0.006724,0.656141,0.391135,0.158181,0.080067,0.006902,-0.323304,0.036870,0.115594,0.294170,-0.075343,0.259039,0.075142,-0.550274,-0.254108,-0.099666,0.277309,0.068918,0.751682,0.072001,-0.122082,-0.118535,0.657997,-0.439237,-0.288180,0.050959,0.260434,-0.239187,0.167436,-0.012588,-0.213965,0.242208,0.211899,-0.230184,-0.404834,-0.049937,0.251361,0.003898,-0.619310,0.554248,0.048849,0.306876,0.136508,-0.124692,0.191585,0.180645,-0.138249,0.540758,-0.160717,0.171617,-0.552022,0.810202,0.372644,-0.229753,-0.294541,0.272268,-0.510106,-0.247588,0.113872,-0.490844,-0.768579,-0.037280,0.207887,-0.225513,-0.214958,0.218981,-0.430607,0.140946,0.192187,-0.331351,0.168241,-0.178003,-0.345364,-0.467562,0.026016,-0.308179,-0.307080,0.056981,0.180819,-0.247831,0.710278,-0.498131,0.699371,0.573397,0.245366,-0.126759,0.757781,0.213493,-0.066178,-0.056960,-0.292207,0.434616,-0.191520,-0.088051,-0.162341,0.004330,-0.191015,-0.030396,-0.269204,0.337314', '1908036', '1291976', '1297368', '3732800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302415', '武侠七公主', '喜剧', '明朝中叶，倭寇不断骚扰东南沿海，东瀛柳生一族辅佐德川家康之余亦要席卷中原武林。于是“东瀛霸刀”柳生（任达华饰）杀入武林、所向披靡，亦要向中原武林第一高手“天剑”独孤无极（刘松仁饰）挑战。独孤无极正要与新婚妻子梦青丝（杨紫琼饰）成亲，却不得不为此事拖延。他向“鬼医”（吴孟达饰）求助，遂用剧毒将自己功力提高数倍。比武之日，独孤无极力战柳生，将其赶走，自己却被体内毒气错乱神经，以致糊涂杀死山庄里无数友人，并气走青丝。青丝自此男装打扮，化名独孤贞，杀尽天下负心人。鬼医弟子吴通（张卫健饰）为了逃避年纪比他大许多的未婚妻牛娃（郑裕玲饰），成婚当日逃走，巧遇微服出游的天香公主（张曼玉饰）和贴身侍卫（吴君如饰），三人发生争执，此时独孤贞出现解围。而此时镇上却在传言梦青丝在妓院摆出迷魂阵召贤比武的香艳传闻，惊讶的独孤贞于是与吴通一起前去探个究竟......©豆瓣', '杨紫琼', '王晶', 6.4, 6343, 'tt0108601', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2228299130.jpg', 2.1, 11.4, 56.2, 22.7, 7.6, '-0.331949,-0.101005,-0.162051,0.562811,0.093730,0.010495,0.377032,0.101070,-0.500599,-0.561147,0.292339,0.448285,-0.093120,0.141959,0.305611,0.143762,0.204003,-0.847720,-0.051061,0.064617,0.017948,-0.090124,-0.120903,-0.129353,-0.211564,-0.088189,0.539432,0.158062,-0.115599,0.774947,0.164839,0.062763,-0.515878,0.373349,-0.134714,0.101526,-0.339416,-0.013822,-0.215063,0.285565,-0.438377,-0.323822,-0.318529,0.327577,0.000168,0.223436,0.249561,-0.208773,0.540122,-0.319742,0.193845,-0.017756,0.059574,0.348836,0.157265,-0.091622,0.480887,0.216961,-0.165479,0.006083,-0.081820,-0.049630,-0.224175,0.349574,0.222085,-0.170454,-0.439881,0.375822,-0.505875,-0.063522,-0.042852,-0.048478,0.042856,0.332128,0.414635,-0.042277,-0.228854,-0.158503,-0.340296,0.129355,0.416336,0.106420,0.398036,-0.023156,0.502023,-0.097786,-0.214559,-0.282604,0.291493,-0.137739,0.406192,0.020293,0.196206,0.476877,-0.086693,-0.364162,-0.094141,0.322047,0.002981,0.150745,-0.181590,-0.335318,-0.089026,-0.356020,-0.303086,-0.109536,0.509524,-0.008154,0.316165,-0.541636,-0.171167,0.161778,0.156474,-0.663041,0.242873,-0.199590,0.035964,0.128210,-0.299238,0.387335,0.161526,0.379505,0.006002,0.301553,-0.317109,-0.073270,-0.306499,-0.172021', '1301982', '1968502', '1294417', '1307186');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302425', '喜剧之王', '剧情', '尹天仇（周星驰 饰）一直醉心戏剧，想成为一名演员，平时除了做跑龙套以外，还会在街坊福利会里开设演员训练班。此时舞小姐柳飘飘在妈妈桑的带领下来到这里要求学做戏，原来柳飘飘有一段非常不愉快的经历，在尹天仇对她指导的过程中，柳飘飘对尹天仇渐生情愫，同时她也成为了夜总会里当红的小姐。尹天仇受到了极多白眼之后，终于得到了大明星鹃姐（莫文蔚 饰）的赏识，提携他担演新戏中的男主角，但没想到突然把他的角色换掉了，令他失望不已。在片场当场务的卧底警员（吴孟达 饰）身份被识穿，尹天仇阴差阳错的帮忙破了案。之后尹天仇继续活跃在街坊福利会的演员训练班里。©豆瓣', '周星驰', '周星驰', 8.8, 901710, 'tt0188766', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2579932167.jpg', 0.1, 0.6, 9.3, 38.7, 51.3, '0.193681,0.047782,-0.445651,0.530654,0.077396,-0.128766,0.621900,-0.050019,-0.584985,-0.221374,0.106670,0.649441,-0.486012,0.463712,0.354939,-0.196877,-0.307294,-0.653216,-0.187858,-0.141035,-0.305032,-0.312279,-0.191266,-0.205335,-0.430933,-0.172286,0.405886,0.185449,-0.114242,0.405939,0.529172,0.037118,0.037158,0.484091,-0.069914,0.299292,0.233988,0.054207,-0.013011,0.350032,0.361639,-0.420992,-0.152860,0.020600,0.353550,0.278911,0.528479,-0.098137,-0.179628,0.094789,0.374828,-0.131008,0.226576,0.028593,0.229800,0.067458,0.429193,0.075534,-0.283478,0.101318,0.002648,-0.312323,-0.454221,0.152022,0.441211,0.128696,-0.615923,0.292899,0.009666,0.004888,0.057967,-0.145660,0.186948,-0.028839,0.443688,0.191204,-0.117865,0.103075,-0.469807,0.546322,0.488942,0.182834,0.026253,0.355136,-0.096969,-0.475880,-0.233136,-0.155940,-0.207390,-0.078213,0.282729,-0.203348,0.138580,0.005431,-0.225770,-0.180959,0.140995,0.086989,-0.372320,-0.403622,-0.116609,-0.368131,0.020057,-0.347299,-0.018742,-0.006689,0.129109,-0.378013,0.809617,-1.091425,0.028104,0.282609,0.204981,-0.505758,0.621217,-0.037310,0.127576,0.053980,-0.057138,-0.184471,-0.057069,0.170660,0.386274,0.539378,-0.231043,-0.384426,-0.037086,0.114162', '35030151', '1292219', '2052978', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302429', '佛莱迪大战杰森', '惊悚', '佛莱迪（罗伯特·英格兰德 Robert Englund饰）和杰森（肯·克辛格Ken Kirzinger饰）都是两个大魔头：佛莱迪是一个“恶夜鬼王”，有潜入梦境控制他人意志的本领；而杰森则是“嗜血狂魔”，最爱肢解小孩。死于两人手下的冤魂不计其数。如今，不甘寂寞的佛莱迪又起 了杀人心瘾，他决定和杰森两人联袂，给春木镇一个血流成河的杀戮。镇上居民在两个恶魔的屠杀下遭受血光之灾，佛莱迪和杰森两人也在疯狂的杀人中相互结仇。谁是杀戮王者谁拥有最多的地盘，两人心中早有芥蒂。几个年轻人在他们的魔爪面前，巧妙的利用了他们的弱点进行离间调拨，这招不仅救了自己，还挑起了佛莱迪和杰森之间的一场大战！©豆瓣', '罗伯特·英格兰德', '于仁泰', 6.4, 10031, 'tt0329101', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1904247948.jpg', 2.8, 14.1, 51.9, 21.9, 9.3, '0.201070,-0.126673,-0.651251,0.520581,-0.154480,-0.164584,0.853225,-0.173245,-0.224317,-0.034324,0.334254,0.735342,-0.141004,0.101662,0.042292,-0.258646,-0.044254,-0.696083,-0.184793,0.016346,-0.181576,-0.264152,-0.584541,-0.205189,-0.008554,-0.242446,0.407354,0.077328,-0.223092,0.296960,0.568923,0.401093,-0.253098,0.309486,-0.308040,0.026234,-0.103334,-0.266591,-0.268092,0.287673,-0.011027,-0.065614,-0.259312,0.397111,-0.217454,0.378991,0.706596,-0.448461,0.033811,-0.339800,-0.018630,-0.397698,-0.149438,0.251091,0.355528,-0.521270,0.232744,0.254756,0.011813,-0.075511,0.030297,0.184938,-1.033928,-0.114563,-0.040145,0.047464,-0.522579,0.412537,0.103992,0.020973,-0.092583,-0.070567,0.192195,0.403309,0.197335,0.202634,-0.198950,-0.481756,-0.719614,-0.136323,0.876907,-0.093431,-0.060572,0.085288,-0.182592,-0.379893,-0.278872,-0.380634,-0.326119,-0.196338,0.531032,-0.222654,-0.060635,0.443763,-0.824803,-0.023050,-0.320815,0.172049,-0.075411,-0.430069,0.002281,-0.531507,-0.267416,-0.358800,-0.386113,0.236012,0.138571,-0.096483,0.644593,-0.734588,0.090148,0.549717,0.364793,-0.379738,0.486301,0.097661,0.071966,-0.162585,-0.093769,-0.131105,0.409369,0.152160,0.525679,0.450087,0.032290,0.071160,-0.155922,0.449687', '25828589', '2032339', '1874704', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302434', '机动部队', '剧情', '反黑组警长肥沙（林雪 饰），不慎丢失手枪。这件事非同小可，如果手枪被匪徒用去行凶，肥沙将大祸临头。PTU（警察机动部队）警官何文展（任达华 饰）出于义气，答应一定会在天亮之前寻回手枪，带几名手下开展了寻枪行动。另一方面，却在横生枝节：警员Kat（邵美琪 饰）死守纪律，坚持要将此事汇报上级处理；而在同一晚，CID的Madam张（黄卓玲 饰）在接手一单黑社会谋杀案时，怀疑肥沙与黑社会有染，由此与PTU发生意见分歧。人与人，部门与部门之间的矛盾、争斗和角力，在夜幕中徐徐拉开。而第二天清早，揭晓的真相，原来都在他们的意料之外……©豆瓣', '任达华', '杜琪峰', 8.2, 92579, 'tt0250638', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173360401.jpg', 0.3, 1.4, 17.7, 51.7, 28.9, '0.284967,-0.168218,-0.594340,-0.052961,-0.018535,0.142334,0.785315,0.139856,-0.424144,-0.280479,0.281310,0.476135,-0.037179,-0.237001,0.396305,-0.440858,-0.514179,-1.100895,0.163371,-0.082575,-0.342449,-0.735049,0.026608,-0.421253,0.115320,0.004266,0.529974,0.190946,-0.300546,0.588731,0.285364,0.148772,-0.416755,0.530676,0.063128,-0.319141,0.063511,0.046425,-0.359897,-0.057412,0.204292,-0.521920,-0.163203,0.069094,0.336647,0.536742,0.469602,-0.176363,-0.285299,0.157343,0.048671,-0.502734,0.101784,0.072668,0.591094,0.180962,-0.210431,0.678664,-0.386253,0.108463,-0.002534,-0.061687,-0.480772,0.222015,0.087581,0.197113,-0.564047,0.277236,-0.353092,0.193383,0.270325,-0.152188,0.329713,0.712411,0.092235,-0.012635,0.119613,-0.058434,-0.605438,0.003710,0.540587,-0.183148,0.248533,-0.171145,0.368634,-0.413713,-0.393403,0.055069,-0.112746,-0.082670,0.335470,0.001948,-0.120555,0.082607,-0.389861,-0.211314,-0.068785,0.179045,-0.117786,-0.287724,-0.041233,-0.446941,0.022098,-0.298850,-0.355333,0.238566,0.263277,0.113551,0.374526,-0.684022,-0.104532,0.383567,0.218774,-0.635111,0.448560,0.203520,0.308667,-0.442591,-0.043810,-0.245820,0.340862,0.454160,0.251428,0.219537,0.121524,-0.213309,-0.076206,-0.355245', '1298104', '3263169', '1306449', '1306454');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302441', '表姐，你好嘢！', '剧情', '四川女公安郑大姐（郑裕玲饰）负责赴港捉拿逃跑的疑犯，不得不与香港警方合作。警长伍卫国（梁家辉饰）负责接待与合作调查，被初次到港、天真纯朴的郑大姐与助手阿胜（张坚庭饰）弄得晕头转相。由于地区文化差异，郑大姐与伍卫国不断产生摩擦、矛盾，多次让疑犯有机可乘、逃之夭夭。由于在旅馆被疑犯袭击，督察安排郑大姐去伍卫国家住。而伍卫国之父正是当年国民党军72师的排长。由于信仰不同，郑大姐一到家就与伍父闹了个水火不容。一连串爆笑的争锋相对就这样展开了，而奇妙的事，郑大姐与伍卫国之间的感情也在慢慢产生变化......©豆瓣', '郑裕玲', '张坚庭', 7.7, 9311, 'tt0101442', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204679567.jpg', 0.5, 2.9, 29.2, 48.2, 19.2, '0.375825,-0.248991,-0.641682,0.519658,0.218840,-0.227768,0.591453,0.334815,-0.370978,-0.526907,-0.252730,0.313734,-0.247799,0.197522,0.301120,-0.478433,0.032743,-0.495898,-0.161464,0.077251,-0.120458,-0.659701,0.125383,-0.209837,-0.118670,0.023471,0.190072,0.066390,-0.551712,0.549800,0.384532,0.352127,-0.501590,0.598959,0.101017,0.097533,0.150879,0.149608,-0.427967,-0.338227,0.405953,-0.476189,0.218515,-0.079324,0.332193,0.489376,0.645344,-0.114610,-0.248774,-0.141788,0.184201,-0.243637,0.287350,0.111247,0.631295,-0.070525,0.118932,0.075023,-0.300013,-0.100644,0.037908,-0.199671,-0.331601,0.365818,0.415709,-0.260253,-0.523792,0.023230,-0.057983,-0.030134,0.115334,-0.274389,0.506883,0.789730,0.242209,0.345923,-0.051408,0.024315,-0.245107,0.299392,1.013357,0.117897,0.031042,-0.131144,0.077574,-0.589606,-0.152284,-0.144062,-0.248338,0.018040,0.281830,-0.413076,0.371434,0.091320,-0.662825,-0.488601,-0.080518,0.207938,0.127063,-0.222152,0.447941,-0.503606,-0.236425,-0.604091,-0.216457,0.332590,0.166041,-0.018349,0.319983,-0.811121,-0.013503,0.310323,0.233264,-0.972217,0.502592,0.249321,0.292301,-0.512247,0.189176,-0.084174,0.398951,0.247584,0.488618,0.448308,-0.117182,0.004109,0.030152,-0.145019', '1293265', '4145476', '1297710', '6890343');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302443', '吉星拱照', '喜剧', '林宝生（周润发 饰）是香港富豪，与表妹玉仙（利智 饰）早已订婚。但宝生并不喜欢未婚妻的庸俗，决定逃婚，并要证明自己能独立生活。出走的第一天，他阴差阳错来到了一个慈善晚会，认识了晚会赞助商东东快餐店的老板（夏雨 饰）与其妹妹（张艾嘉 饰），还成为了快餐店的员工之一。宝生与一群善良的同事度过了一段难忘的时光，他也看到了自己价值的存在，与老板的妹妹也产生了感情，但他与表妹的婚期将至，他的真实身份也将浮出水面，而他与老板妹妹的感情又会如何呢？©豆瓣', '周润发', '杜琪峰', 7.5, 12466, 'tt0097619', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2349194057.jpg', 0.6, 3.2, 35.8, 42.9, 17.5, '0.225896,0.031393,-0.498402,0.662337,-0.307470,-0.298645,0.772554,0.255520,-0.595098,-0.080941,0.165710,0.985787,-0.216788,0.416014,0.254112,0.288825,0.048342,-0.709740,0.204590,-0.250695,0.074862,-0.456662,-0.197699,-0.259946,0.013128,-0.096113,0.526186,0.094481,0.043277,0.422902,0.486452,-0.112425,-0.187108,0.654062,-0.215426,-0.001995,0.005885,0.395262,-0.515682,0.135431,0.114552,-0.266326,0.171071,0.175869,-0.061893,0.306629,0.721861,-0.086418,-0.262470,-0.065839,0.389166,-0.338050,0.142615,0.292284,0.146190,-0.126919,0.346849,0.442129,-0.114745,0.093104,0.071715,-0.176518,-0.587028,0.099622,0.131683,-0.040412,-0.745694,0.716548,-0.183916,-0.324448,0.003798,-0.479426,0.288307,0.334570,0.182739,0.285541,-0.265451,-0.146216,-0.616154,0.429081,0.799812,0.098809,0.123252,0.766090,-0.225391,-0.646993,-0.211864,-0.174083,-0.509296,0.221911,0.162596,0.021894,-0.126827,0.162606,-0.628019,-0.028762,-0.146878,-0.047850,0.161137,-0.693546,0.208028,-0.178523,-0.291417,-0.477134,-0.437226,-0.101420,0.280534,-0.357859,0.740232,-1.100522,-0.029252,0.592944,0.509952,-0.730620,0.817262,0.310313,-0.038855,-0.264659,-0.057482,-0.120739,-0.334651,0.207575,-0.156140,0.416213,0.156296,-0.164703,-0.215103,0.313167', '1292219', '1302384', '1395231', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302451', '风雨同路', '剧情', '大胆（成奎安 饰）率一伙悍匪打劫南非钻皇得手，他们找到中间人李云飞（陈惠敏 饰）销赃，却在交易时黑吃黑射杀收购人，李云飞趁乱逃脱。卧底张郎（周星驰 饰）因工作的特殊情况，导致和女友周文丽（周慧敏 饰）之间的误会越来越深，张郎欲甩手不干，但迫于老上司李警官（李修贤 饰）压 力，只得为了查清钻石劫案，奉命接近李云飞。其时李云飞正受到大胆一伙的追杀，张郎助其脱险得到了李云飞的信任。在接触中，张郎逐渐发现李云飞作为老派江湖人物行事有情有义，两人遂结为异姓兄弟。另一方面，张郎几经努力却无法向丽文表白自己的卧底身份，后者眼看要假结婚前往加拿大，而张郎在警局中的上司，又只将李云飞看做引诱大胆现身的诱饵，张郎现身职责和情义之中左右为难……©豆瓣', '周星驰', '黄柏文', 7.7, 19067, 'tt0097348', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2638807235.jpg', 0.5, 2.6, 31.2, 41.2, 24.5, '0.224710,0.072582,-0.523545,0.373778,-0.070537,-0.053999,0.364356,0.043813,-0.496287,-0.374461,0.388599,0.352540,-0.078254,-0.033581,0.142915,-0.094157,-0.166353,-0.617908,0.019388,-0.033088,0.017676,-0.429175,-0.307404,-0.215799,-0.365858,0.188472,0.637680,0.013117,-0.476918,0.276614,0.533737,0.262659,-0.259518,0.406050,0.032616,-0.064152,0.205236,-0.048977,-0.510201,0.195352,-0.013717,-0.243106,-0.208106,0.201151,-0.036118,0.576247,0.444098,-0.095347,-0.160794,-0.176398,0.215532,-0.384319,-0.063247,-0.004885,0.309741,0.160399,0.218585,0.170414,-0.191086,0.090347,0.147150,0.184302,-0.501122,0.105705,0.195872,-0.069252,-0.332550,-0.171326,-0.132283,-0.007463,0.115173,-0.355531,-0.129746,0.234603,0.169079,-0.068658,-0.120649,0.070089,-0.281529,0.075160,0.658774,0.010803,0.108313,-0.091505,-0.006234,-0.319330,0.245087,-0.176083,0.006571,-0.289969,0.429498,0.030449,0.021115,0.113943,-0.301674,-0.242951,-0.437616,0.454482,-0.133043,-0.290704,0.071878,-0.481936,-0.356127,-0.272666,-0.061734,0.162102,0.125613,-0.228346,0.222913,-0.506437,-0.191648,0.463810,0.251753,-0.650671,0.322917,0.477120,-0.042331,-0.473010,-0.316194,0.002600,0.215938,-0.042055,0.042597,-0.138356,-0.124923,-0.201427,-0.134798,-0.256736', '1293265', '1484760', '25908042', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302455', '宋家皇朝', '剧情', '政局腐败民不聊生的晚清末年，宋查理（姜文）凭借其在美国所获先进知识与孙中山（赵文瑄）合力，企图推翻满清。其后，宋查理留学美国的各具风情的三个女儿学成归国，老大宋霭龄（杨紫琼）下嫁商人孔祥熙（牛振华），老二宋庆龄（张曼玉）不顾父亲反对追随了革命者孙中山，老三宋美龄（邬君梅）则在先是革命者后是叛国者的蒋介石（吴兴国）的狂烈追求下成为其妇，三人的命运开始在动荡不安的政局中随着对其时的中国最重要的三个男人的命运沉浮。©豆瓣', '张曼玉', '张婉婷', 7.7, 45883, 'tt0120164', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561537651.jpg', 0.5, 2.7, 27.4, 49.1, 20.4, '0.129170,0.105582,-0.779018,0.676446,0.020388,-0.265946,0.603015,0.265556,-0.524412,-0.161457,0.203376,0.638528,0.288549,0.245008,0.287874,-0.214447,-0.241214,-0.763958,-0.334377,0.131670,0.044092,-0.609431,-0.120742,-0.288218,-0.496753,0.078754,0.687485,0.021035,-0.216701,0.401549,0.505574,0.218256,-0.038142,0.253250,-0.058091,0.240712,0.231846,-0.218769,-0.839202,0.039216,0.184361,-0.577706,-0.115446,0.162908,-0.273307,0.065441,0.408003,-0.205006,0.344053,-0.415308,0.549376,-0.083830,-0.389415,0.194915,0.476488,0.040225,0.231104,0.365629,0.071349,0.048814,0.090366,0.140433,-0.442284,-0.172015,0.296739,0.187218,-0.453261,0.457530,0.026144,-0.018215,-0.108961,-0.480666,0.174639,0.657599,-0.022701,0.438955,-0.140566,0.265429,-0.271927,0.380399,0.466370,-0.051202,-0.287591,-0.149071,-0.056796,-0.350716,0.109904,-0.234584,-0.430844,-0.398801,0.555511,-0.169557,0.103226,0.551757,-0.448462,-0.140897,0.007174,0.040526,0.076477,-0.110235,0.122150,-0.440570,-0.300456,-0.776869,-0.069620,0.057651,0.240097,-0.317442,0.847991,-0.487491,0.012951,0.112408,0.247075,-0.656727,0.432803,0.104328,0.209532,-0.367277,-0.039262,0.387695,0.130630,0.033730,-0.010613,0.188488,-0.069866,-0.180585,0.026919,0.256700', '1305441', '10573695', '1480318', '1299085');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302457', '阿育王', '剧情', '公元前的印度孔雀王朝，宾头沙罗国王之子阿育王子（沙鲁克·汗 Shah Rukh Khan 饰）勇猛善战，虽遭兄弟忌恨陷害，却接连立下汗马功劳，声望扶摇直上。面对荆棘环绕的王位，阿育起先沉着应对，不以为意，最终还是应母亲（Shilpa Mehta 饰）的苦苦哀求隐姓埋名，离开王宫。修行途中，阿育邂逅美丽动人的卡列加公主卡瓦奇（卡琳娜·卡普 Kareena Kapoor 饰）。失意时节相知相守，一对不平凡的青年男女爱情花朵恣意绽放。不过正如僧侣所说，太阳即使躲在云层后面仍是太阳，阿育注定重返王宫，继承王位。为此他与卡瓦奇生离死别，在金碧辉煌的宫殿内与政敌和外敌攻防周旋。在血雨腥风的斗争中，阿育的那颗心逐渐冰冷，攻城略地，征战杀伐，血流遍野，为了最顶点的荣耀，黑色阿育王逐渐膨胀。史上最伟大的护法转轮王阿育，亘古流传的王者传奇……©豆瓣', '沙鲁克·汗', '桑托什·斯万', 7.7, 14396, 'tt0249371', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196649757.jpg', 0.5, 3.4, 29, 44.4, 22.6, '-0.231604,0.240566,-0.522751,0.699102,0.424301,-0.296291,0.578174,0.364305,-0.340888,-0.216483,0.533942,0.538007,-0.169327,-0.237603,0.271059,-0.019645,-0.248620,-0.444201,-0.005904,0.039204,0.148309,-0.008686,-0.410170,0.070960,-0.243385,-0.472362,0.927100,0.325420,0.050650,0.290557,0.133057,0.135270,-0.208932,0.082385,-0.301724,-0.272954,-0.167472,0.363987,-0.288327,-0.108367,-0.514374,-0.306304,-0.128422,-0.117265,0.005939,0.064763,0.360858,-0.626112,0.410303,-0.350476,0.374236,-0.160200,-0.191810,0.302843,0.192123,-0.073486,0.169999,0.437493,0.145338,-0.323179,-0.119856,-0.197044,-0.462262,-0.107349,0.252297,0.049399,-0.329161,0.732152,-0.006564,-0.190409,0.278714,-0.029579,0.277122,0.243819,0.041847,0.225239,-0.008325,0.035949,-0.457410,0.199629,0.327453,-0.031575,-0.322728,0.067684,-0.218083,-0.305107,0.057244,-0.307704,-0.327536,-0.294435,0.285832,0.000006,0.275971,0.726865,-0.372351,0.017891,-0.440303,0.054185,0.078707,-0.269088,-0.285136,-0.248053,-0.319802,-0.463486,0.014607,0.101870,0.119636,0.009048,0.461199,-0.501351,0.182545,0.119430,0.129474,-0.000128,0.534056,0.096835,0.048325,-0.292420,-0.216820,0.845216,-0.067433,0.128764,-0.300044,0.033172,-0.341376,0.180917,-0.208854,0.291268', '1763916', '20284873', '1303390', '4202204');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302467', '黑客帝国3：矩阵革命', '动作', '第二集中，尼奥（基努·里维斯 Keanu Reeves 饰）没有能从内部摧毁“母体”，他的身体在真实世界的飞船上陷于昏迷，思想却被困在介于“母体”和真实世界的中间地带，这个地方由“火车人”控制。墨菲斯（劳伦斯·菲什伯恩 Laurence Fishburne 饰）和崔妮蒂（凯瑞-安·莫斯 Carrie-Anne Moss 饰）等人知道了尼奥的情况，在守护天使的带领下， 找到了“火车人”的控制者梅罗纹奇，经过一番激斗，将尼奥救了出来。此时，电子乌贼部队对锡安发起了猛烈的攻击，人类组织所有机甲战士展开顽强的抵抗，形势危在旦夕；尼奥和崔妮蒂驾驶了一艘飞船克服重重困难，到达机器城市，尼奥终于见到了机器世界的统治者“机器大帝”，双方谈判并达成了协议：尼奥除掉不受“母体”控制的史密斯，以换取锡安的和平。在“母体”中，尼奥和史密斯展开了关系人类生死存亡的最后决斗。', '基努·里维斯', '拉娜·沃卓斯基', 8.8, 419727, 'tt0242653', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p443461818.jpg', 0.2, 0.8, 9.9, 35.6, 53.5, '0.233571,0.303937,-0.657141,0.377897,0.072699,-0.144202,0.739957,0.240758,-0.126254,0.139659,0.558445,0.685959,-0.074493,-0.374010,0.262991,-0.104929,-0.655408,-0.581790,-0.039728,0.147922,-0.583760,-0.583800,-0.371475,-0.346000,0.192327,-0.678630,0.824444,0.094209,-0.110550,0.238440,-0.217483,0.401326,-0.065981,0.590689,0.082165,0.067755,0.073399,-0.381913,-0.445377,0.346178,-0.199144,-0.028847,-0.126511,0.380397,0.078787,0.304493,0.694603,-0.625496,0.287589,-0.284409,-0.059644,-0.298243,-0.028655,-0.101648,0.466532,-0.403763,-0.121099,-0.057727,-0.113327,0.077385,-0.008342,-0.022098,-0.880100,-0.107709,-0.002776,0.196831,-0.605714,0.265738,-0.321525,0.275100,0.029038,-0.413343,0.228825,0.633462,0.127156,0.320590,-0.104221,-0.215787,-0.733218,-0.347437,0.346068,-0.194047,-0.721227,0.071210,-0.282989,-0.547467,-0.634872,-0.344942,-0.222258,-0.444297,0.523445,0.116388,-0.282503,0.210606,-0.639821,-0.092480,-0.375492,-0.513215,-0.076148,-0.469513,-0.112627,-0.910457,-0.063627,-0.332878,-0.117109,0.239231,-0.104949,-0.057498,0.592098,-0.920803,0.149212,0.844335,0.388093,-0.235594,0.513966,-0.005246,0.205735,-0.359611,0.034048,0.210709,-0.098520,0.594670,0.445014,0.381600,-0.040544,0.383824,-0.471822,0.492218', '11