INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302476', '麦兜故事', '剧情', '麦兜，一个长得不帅，头脑平平的小朋友。和妈妈麦太太，在香港一个叫大角咀的地方过着并不富裕却很快乐的生活。从麦兜带着妈妈的期望来到世界那一刻开始，他的脑海中一直飘满七彩幻想的泡泡。那个蓝天白云，椰林树影，水清沙白的童年的马尔代夫，那充满诱惑的圣诞火鸡的浓香，还有那个关于“抢包山”的奥运金牌的梦想，让麦兜平凡着他的平凡，却幸福着他的幸福。麦兜，和春田花花幼儿园的小朋友们一起，陪着我们，简单的在爱的呵护下慢慢长大。©豆瓣', '李晋纬', '袁建滔', 8.6, 175849, 'tt0312941', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p804938713.jpg', 0.3, 1.1, 13.3, 40.6, 44.7, '0.468152,0.113622,-0.722913,0.753293,-0.278188,-0.288473,1.092202,0.330807,-0.062502,0.138949,-0.266139,0.630483,-0.008399,0.994775,0.002187,0.394227,-0.074072,-0.549567,-0.201812,0.186607,-0.204958,-0.170904,-0.125491,0.045548,-0.114594,-0.006499,0.466560,0.134888,0.360323,0.729884,0.408372,-0.211695,-0.097547,0.540681,-0.728947,0.031885,-0.015964,0.392127,-0.183175,0.080969,0.150460,-0.008876,0.006964,0.094402,-0.022475,-0.129038,0.902559,-0.294267,-0.034861,0.137720,0.226210,-0.168794,-0.092229,-0.041680,0.085213,-0.064039,0.008629,-0.135136,-0.031575,0.079793,0.017238,-0.266515,-0.750266,-0.279701,0.252715,0.409821,-0.715969,0.556034,0.162437,-0.034426,0.426409,-0.166835,0.116484,0.031580,-0.305700,0.674144,-0.358381,0.633308,-0.633994,0.487037,0.478939,-0.072866,-0.012455,0.329371,-0.718889,-0.186951,0.180252,0.107012,-0.902826,-0.224520,0.294667,-0.197066,-0.531129,0.006177,-0.727717,0.410775,0.308291,-0.248984,0.172912,-0.595954,-0.244403,-0.261588,-0.057216,-0.894117,-0.374257,0.167639,-0.130829,-0.183762,0.933580,-0.846599,0.419353,0.734496,0.258653,-0.037400,0.797928,0.494859,-0.018482,-0.263429,-0.296962,0.549560,-0.183928,0.277706,0.156324,0.750904,0.042077,0.136923,-0.722266,0.845633', '3796613', '26677495', '26348103', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302488', '犹在镜中', '剧情', '遗传了母亲精神病的凯伦（Harriet Andersson 饰）经过入院治疗，被作家父亲大卫（Gunnar Björnstrand 饰）安排到一小岛上调养。凯伦男友马丁（Max von Sydow 饰）是一名医生，两人的感情此时处于低谷，马丁相信凯伦有痊愈的可能。青春期中的弟弟米纳斯颇有才华，但看上去有些焦躁。四人在封闭的岛上休整，但各自心中的不安似乎正慢慢滋长。凯伦发现父亲在冷漠的观察自己病情变化后情绪短暂失控。次日上午马丁与大卫乘小舟离去，被留下的凯伦开始沉溺于冥想，并对米纳斯显示出侵略性，在两人回岛之前凯伦昏倒在破旧的木船内，她向弟弟宣称，自己听到了上帝的声音……本片是伯格曼“神之沉默”三部曲的第一部，于1962年获奥斯卡最佳外语片奖。©豆瓣', '哈里特·安德森', '英格玛·伯格曼', 8.4, 10719, 'tt0055499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2182280169.jpg', 0.4, 1.2, 12.9, 49.3, 36.3, '0.054178,0.001242,-0.952149,0.297556,0.199005,-0.371941,1.021504,0.129398,-0.772964,-0.364610,0.258207,0.777779,-0.457789,0.247968,0.396403,-0.118670,-0.530356,-0.694487,-0.100516,-0.127410,-0.078717,-0.487837,-0.265853,-0.052491,-0.240373,-0.664645,0.568509,-0.013501,0.040001,0.691604,-0.104851,0.280964,0.120647,0.394813,0.046070,0.102533,-0.034030,-0.270196,-0.259303,0.288195,0.400730,-0.147725,-0.184333,0.231438,0.120749,0.485445,0.756793,-0.203258,-0.434194,0.233904,0.397154,-0.076564,-0.094118,0.146611,0.255749,0.180659,0.063468,0.150294,-0.307993,0.150908,-0.193180,0.111554,-0.370771,0.188284,-0.131234,0.461965,-0.455007,0.417769,-0.115972,-0.185405,-0.098992,-0.463510,0.086422,0.197098,0.203295,0.576941,-0.252514,0.112278,-0.266547,-0.172446,0.234657,-0.043099,-0.251414,0.569000,-0.171025,-0.480940,0.030458,0.016809,-0.456287,-0.147841,0.339284,0.300194,0.007116,0.029715,-0.239786,-0.065853,-0.328869,-0.341020,-0.354967,-0.180567,-0.172758,-0.539190,-0.134173,-0.379700,-0.286730,-0.167031,0.100078,-0.163429,0.434673,-0.965826,0.478102,0.326946,0.176747,-0.264784,0.386145,-0.048233,0.055566,-0.213457,-0.043956,0.469438,-0.240791,0.073942,0.172659,0.315368,-0.180561,0.015249,-0.490960,0.201304', '6827727', '21348112', '3111650', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302495', '阴阳路3：升棺发财', '喜剧', '阿力（古天乐饰）为人精明干练，以开殡仪馆作死人生意为生。同事化妆师阿红（袁洁莹饰）是其工作拍档也是他的心头爱，却因为忙于工作无时间陪她，而被好友Daviv（谢天华饰）撬了墙脚。Daviv生性花心，终对阿红始乱终弃，阿红遂踏上不归路......另一个年轻化妆师（丁子峻饰）痴迷歌星陈美丽，一日半夜酒醉后遇到偶像，激动之余拍下了宝贵照片。结果第二天早上便听到偶像的死讯......殡仪馆另三个工作人员（雷宇扬、吴志雄等饰）嗜财如命，骗了一位过世老婆婆（罗兰饰）之女（伍咏薇饰）的钱胡乱做法，结果被老婆婆缠住无法脱身......©豆瓣', '古天乐', '邱礼涛', 6.6, 9806, 'tt0207839', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2660416179.jpg', 1.1, 8.8, 58, 24, 8.2, '-0.200113,0.056470,-0.380868,0.194413,-0.176052,-0.243239,0.619536,0.217227,-0.478217,-0.324099,0.062740,0.262524,-0.178252,0.349278,0.108176,0.072546,-0.240557,-0.508567,0.080872,0.156118,-0.197574,0.177363,0.046016,-0.320893,-0.242216,0.017883,0.154711,-0.037426,0.108598,0.502208,0.530697,0.268106,-0.107656,0.268393,0.004431,0.051071,0.201989,-0.092341,0.045902,-0.062438,-0.025965,-0.312927,0.011107,0.155395,-0.013821,0.446372,0.447311,0.300217,-0.105157,-0.359278,0.303553,-0.139648,-0.103735,-0.023567,0.187824,0.019961,0.438988,-0.017074,-0.171401,-0.032309,0.186548,-0.004582,-0.372275,0.250816,0.042134,-0.042346,-0.403481,0.254096,-0.459728,-0.024626,-0.011628,-0.290718,0.043927,-0.265679,0.351856,0.191061,0.278193,0.143888,-0.110403,0.567866,0.337443,0.049638,0.352947,0.536852,0.053099,-0.315963,0.344128,-0.207085,-0.225481,0.070785,0.320621,-0.099189,0.021362,-0.199009,-0.248851,-0.147963,-0.175874,0.307558,0.031620,-0.196823,-0.371067,-0.416607,0.048195,-0.269107,-0.313114,0.145529,0.087348,-0.024615,0.573184,-0.389162,-0.006183,0.267760,0.101565,-0.654761,0.750955,0.003026,-0.069127,-0.173096,0.270868,0.113546,0.034616,-0.029064,0.042558,0.019121,-0.287064,-0.197365,-0.297900,0.169248', '7161707', '1438093', '1418179', '2046839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302512', '摩登保镖', '喜剧', '邓小龙（许冠英 饰）从小就为人正直、乐于助人，他的志愿就是长大了能当一名除暴安良的好警察。无奈天意弄人，他因身材矮小，而且天生色盲，于是被警局拒之了门外，他只好去保安公司当了一名护卫员。保安主管周世昌（许冠文 饰）是一名老油条，为人尖酸刻薄、贪生怕死。下属阿Sam（许冠杰 饰）一早就看他不顺眼，只是有冤无处申。这次，公司的太子王平凡从国外留学回来，假扮保安混进了公司考察情况。不久阿Sam和小龙就因工作出色而获得提拔，而周世昌却被剥夺了主管之位降职任用，还有几个月就可以退休享受的他会为了退休金忍下这口恶气还是会另有所谋？©豆瓣', '许冠文', '许冠文', 8.2, 14965, 'tt0082761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505126469.jpg', 0.3, 1.3, 17.1, 49.7, 31.7, '-0.092075,-0.056089,-0.350716,0.312030,-0.484247,-0.585375,0.413514,0.434072,-0.598852,-0.307576,0.016163,0.582638,0.083921,0.262688,0.127980,0.072326,-0.222307,-0.442206,-0.199139,-0.288928,-0.298852,-0.178274,-0.017798,-0.464028,-0.240493,-0.027095,0.475444,-0.020180,-0.204775,0.088110,0.620031,0.270802,0.176193,0.621535,-0.322865,-0.018312,0.246523,-0.191356,0.097099,-0.027344,0.143970,-0.357968,-0.199695,-0.015266,0.293948,0.362106,0.378171,0.253549,-0.193168,-0.479092,0.208482,-0.158872,0.064954,-0.085885,0.383885,-0.051241,0.287414,0.010758,-0.151613,-0.070732,-0.028671,-0.241439,-0.610323,0.022114,-0.050191,-0.130015,-0.572446,0.281054,-0.068566,-0.085697,0.050338,-0.205935,-0.030864,0.193044,-0.027329,0.422185,0.176622,0.100802,-0.561922,0.546341,0.641303,0.151144,-0.295564,0.131778,-0.115577,-0.621779,0.191664,-0.326134,-0.330401,-0.032497,0.706300,-0.113474,0.010139,-0.359318,0.075284,-0.116971,-0.307336,0.248705,-0.012665,-0.460664,0.139575,-0.265230,0.164254,-0.158108,-0.329785,0.136859,0.136160,-0.011327,0.671967,-0.746150,-0.128261,0.481930,0.254327,-0.986029,0.729519,0.059640,0.125301,-0.129407,0.136123,-0.309701,0.107269,0.553739,0.509026,0.322418,-0.028026,-0.440587,0.010104,0.008003', '1421278', '1302110', '1305915', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302522', '荒野大镖客', '动作', '墨西哥边境小镇来了一位大镖客（克林特·伊斯特伍德 Clint Eastwood 饰），他得知镇上势不两立的两大帮派罗霍兄弟和镇长巴克斯特相厮杀已久，便决定与两派斡旋，除去镇上恶势力，恢复小镇的平静。他目击罗霍兄弟劫杀了一队士兵并私占黄金，于是利用两具士兵尸体吸引巴克斯特来寻找罗霍兄弟的罪证。同时，他又将消息透露给罗霍兄弟，导致双方展开了一场激烈枪战。乔在两派激战时找到了黄金，并发现被罗霍兄弟囚禁的女人玛利索，他将玛利索交给巴克斯特，换回了在激战中被捕获的儿子安东尼奥。但后来他得知玛利索是被罗霍家的雷蒙抢占，于是设法救出了她，帮助她与丈夫孩子一起逃出镇子。深爱着玛利索的雷蒙发现心爱的女人被放走，便认定是巴克斯特一家所为，于是展开了疯狂的报复。究竟两大帮派谁胜谁负，作为中间人的大镖客能否实现恢复小镇和平的计划？©豆瓣', '克林特·伊斯特伍德', '赛尔乔·莱昂内', 8.4, 64399, 'tt0058461', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2178157710.jpg', 0.2, 0.8, 13.1, 48.9, 36.9, '0.309216,-0.104885,-0.468583,0.258916,0.133711,-0.362309,0.326218,0.021947,-0.469816,-0.003041,0.076869,0.696646,-0.038207,-0.132312,0.211942,0.092779,-0.244148,-0.827542,-0.107613,-0.090039,-0.200902,-0.535693,-0.198707,-0.375042,0.065657,-0.371132,0.300911,0.115573,-0.113919,0.264567,0.365274,0.127760,-0.395303,0.414568,-0.041443,0.203319,0.142416,-0.315157,-0.338745,0.298807,-0.202560,-0.114991,-0.151269,0.176648,0.272934,0.467375,0.630710,-0.327461,0.014272,0.018545,0.063721,-0.320689,0.099070,0.175199,0.260181,-0.096082,0.028346,0.324342,-0.248534,-0.351170,-0.102829,-0.073835,-0.447080,0.114337,0.072708,-0.237007,-0.756170,0.387229,0.044193,0.036747,0.104148,-0.174784,0.253587,0.533534,0.135824,0.062327,0.120156,-0.287213,-0.493013,-0.043272,0.701738,-0.188307,0.221176,-0.058340,0.059013,-0.476168,-0.032683,-0.467376,-0.139312,-0.107104,0.622735,-0.034942,-0.055790,0.395318,-0.596885,-0.265625,-0.734514,-0.086003,0.093915,-0.358450,0.048844,-0.430623,-0.197348,0.095881,-0.106138,0.309450,-0.057639,-0.048867,0.560299,-0.724113,0.134933,0.698043,0.351772,-0.445597,0.328938,-0.051702,0.342893,-0.258766,-0.020722,0.020987,0.652745,0.188029,0.556390,0.111298,-0.407995,-0.045929,-0.394043,0.163657', '1309069', '30345227', '1293829', '1291838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302531', '少林搭棚大师', '剧情', '一介贫民仁杰（刘家辉）为惩罚平时靠鱼肉百姓过日子的恶霸高峰（王龙威），假扮三德和尚对其展开攻势，不想被对方识破反遭一顿痛殴。其后，仁杰来到少林寺请求三德和尚传授功夫，但不被对方作正眼旁观。有感于仁杰的诚心，三德和尚最终允许他留在少林寺，但不教授功夫，只让他负责搭棚修葺的工作。仁杰在工作之余，不忘初来志愿，见缝插针恳求三德和尚收他为徒，终惹怒对方，在对方的示意下，仁杰明白搭棚亦是少林功夫的一种，从此刻苦学习。©豆瓣', '刘家辉', '刘家良', 7.6, 5632, 'tt0081494', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2174882971.jpg', 0.4, 1.8, 32.5, 50.5, 14.8, '0.100388,-0.072671,-0.476173,0.632637,0.085813,-0.417124,0.336661,0.219019,-0.127641,-0.556399,0.027193,0.363803,-0.032857,0.071355,0.008778,-0.244057,0.062365,-0.311148,-0.136473,0.068862,-0.093326,-0.598359,0.228470,-0.480272,-0.569684,-0.071948,0.303938,0.092119,-0.165573,-0.030729,0.158156,0.272686,0.259366,0.179673,-0.183146,0.070350,-0.196155,-0.289392,-0.200997,0.022594,0.010553,-0.414629,-0.503864,0.111301,-0.087346,0.369996,0.524934,0.057302,-0.232107,-0.220575,-0.046730,-0.204338,-0.036469,0.104745,-0.037461,-0.423528,0.132942,0.426446,0.037982,0.408655,-0.093686,-0.100851,-0.381443,-0.031561,0.229036,-0.074423,-0.667622,0.433008,-0.221464,0.153310,-0.651116,-0.339187,-0.441888,0.419689,0.010702,0.141132,0.028561,0.315297,-0.409927,-0.029561,0.573906,0.135854,0.121969,0.314825,0.296356,-0.176592,0.357051,-0.248726,-0.414803,-0.170654,0.096787,0.006066,0.025918,-0.122046,-0.267748,-0.637208,-0.434118,0.227722,-0.041220,-0.322776,-0.020564,-0.340200,0.259160,-0.169855,-0.431503,-0.017387,0.405263,-0.413564,0.528098,-0.816548,0.113845,0.118131,0.025971,-0.766292,0.712821,0.260143,0.149021,-0.224243,-0.314926,-0.086326,0.445570,0.377218,0.476626,0.249681,0.096840,-0.290895,0.037183,0.011606', '1877596', '1419416', '1308805', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302537', '火烧岛', '剧情', '警官黄伟（梁家辉 饰）被借调调查一件涉及警员犯罪的案子，为搜集证据，黄伟犯险入狱。火烧岛典狱长（柯俊雄 饰）治下的监狱充斥着暴力、不公，以及制度化的犯人殴斗。黄伟很快在狱中结识了室友小朱（庹宗华 饰）和因思念儿子多次越狱的刘世杰（洪金宝 饰），并经历了帮派人物大林（高捷 饰）的入狱洗礼。台球选手大锤（成龙 饰）因误杀帮派大哥钢珠（刘德华 饰）之弟入狱，大林受命向大锤复仇，此事被狱中大哥桂老大（王羽 饰）调解。黄伟、大锤等四人被典狱长吸收进入“清风队”，在执行暗杀任务的过程中，黄伟意外的发现了自己追查多时的幕后真凶。©豆瓣', '成龙', '朱延平', 6.7, 15371, 'tt0099812', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2255620642.jpg', 1.8, 8.3, 51, 28.5, 10.5, '0.097850,-0.171996,-0.177981,0.066906,-0.090517,-0.057052,0.454900,0.319159,-0.639454,-0.327042,0.675979,0.327733,-0.319524,-0.154414,0.242317,-0.163028,-0.229932,-0.784053,-0.020242,0.060545,-0.147631,-0.480488,-0.041803,-0.001485,0.080109,-0.115285,0.411352,0.076864,-0.075325,0.540216,0.223536,0.518595,-0.441187,0.180251,0.283295,0.073418,0.467040,-0.095249,-0.473394,-0.078802,-0.104276,-0.445069,0.142397,0.084331,-0.047633,0.435065,0.598943,-0.004479,-0.116866,-0.384374,0.261850,-0.368280,-0.042867,-0.053657,0.486371,0.433593,0.084284,0.584153,-0.133364,-0.068870,0.042481,-0.079158,-0.576572,-0.040961,0.252631,0.237945,-0.254943,0.311211,-0.241386,0.328671,-0.083834,0.047968,0.114444,0.236014,0.067521,0.276375,-0.145415,-0.012717,-0.322230,0.599531,0.317611,-0.504620,0.261983,-0.233351,0.169293,-0.414631,-0.003082,-0.034591,-0.182265,0.045715,0.467568,-0.130734,-0.271169,0.146649,-0.388351,-0.066410,-0.382219,0.221841,-0.135210,-0.026047,-0.115037,-0.535545,-0.123259,0.003300,-0.356322,-0.148239,0.091697,-0.080423,0.165766,-0.538186,0.049511,0.489979,0.164876,-0.488604,0.243926,0.194044,0.063717,-0.381276,-0.073977,-0.134807,0.360633,0.378879,0.289321,0.122512,-0.015467,-0.499352,-0.235317,-0.229793', '25723905', '1307914', '26835911', '3136507');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302542', '血迷宫', '剧情', '雨夜，雷伊（约翰•盖兹 John Getz 饰）跟艾比（弗兰西斯•麦克多蒙德 Frances McDormand 饰）在酒店偷情。雷伊是酒吧伙计，而艾比则是酒吧老板玛迪（丹•哈达娅 Dan Hedaya 饰）的妻子。玛迪怀疑妻子出轨，因此雇佣侦探维斯调查。知悉真相的玛迪怒不可遏，潜入雷伊家，企图绑走妻子，却在厮打中受伤。玛迪密会维斯，决定花钱做掉二人。维斯潜入雷伊家翻到了艾比的手枪。回来后，维斯给玛迪看了两人被杀的照片，趁玛迪不备，将其击毙。雷伊发现玛迪尸体，误以为艾比所为，因此毁尸灭迹。晚上，雷伊再次回到酒吧，赫然发现了威斯假造的照片。这时，雷伊和艾比都不知道，死亡的威胁正在步步紧逼……本片为科恩兄弟的处女作，创作于1984年，只用了80万美元，2个月即拍摄完成。2009年，制片人张伟平斥资200万美元购得本片版权，邀请张艺谋据此拍摄了《三枪拍案惊奇》。', '约翰·盖兹', '乔尔·科恩', 7.8, 36152, 'tt0086979', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2170091763.jpg', 0.5, 1.9, 23.3, 54.5, 19.9, '0.257196,-0.154942,-0.250946,0.138528,0.069518,-0.476890,0.542140,0.107029,-0.088511,-0.554587,0.246177,0.703489,-0.256695,-0.259859,0.476115,0.185061,-0.572625,-0.673725,-0.012688,-0.208251,0.030735,-0.563509,-0.094959,-0.060354,0.082675,-0.317181,0.151464,-0.253535,0.013203,0.425729,0.273450,0.382095,-0.134444,0.190101,0.214411,0.149450,0.306912,-0.345111,-0.401899,0.395949,-0.181878,-0.211699,-0.121197,-0.023470,0.054732,0.268713,0.634046,0.026018,0.005199,-0.074646,0.465619,-0.192559,0.107865,-0.009595,0.172813,0.057830,0.224171,0.211048,-0.424012,-0.017766,0.316496,-0.030935,-0.523131,0.305809,0.001409,-0.097108,-0.521867,0.363748,-0.714625,0.178716,0.180328,-0.237646,0.195791,0.321980,0.237550,0.163259,-0.068960,-0.096087,-0.592616,0.095215,0.226752,-0.050259,0.344432,0.226767,0.293192,-0.346788,0.111791,0.146057,-0.064537,0.004085,0.468170,0.210488,-0.124922,0.177957,-0.525651,-0.506262,-0.683643,-0.291944,-0.134877,-0.532866,-0.352565,-0.773821,-0.363162,0.311407,0.034040,-0.194178,0.064658,-0.203910,0.231332,-0.489470,0.240012,0.349679,0.312762,-0.051419,0.624499,-0.130032,-0.174227,-0.198237,-0.052799,0.217058,0.458874,0.271170,0.276471,0.195787,0.186602,-0.356112,-0.356400,0.148594', '6517421', '1297659', '1295187', '3183490');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302570', '星际旅行5：终极先锋', '动作', '本片是《星舰迷航记》系列电影的第五集，由原班人马主演，但改由饰演寇克船长的威廉·赛特纳执导，也是他的导演处女作。故事描述一名神秘的疯狂幻想家赛布克占领了一个遥远的星球，劫持星际大使作人质，强迫企业号宇宙飞船紧急出发，进入没有人做访过的未知宇宙去寻找传说中的上帝，但上帝到底是谁呢？本片的开场颇具震撼力，可惜发展下去难以为继，使大部分的篇幅在过分玄奥的故事框架中兴圈子，只能靠壮观的视觉特效维持其吸引力，幸好结局是略有起色，不致令观众太过失望。正在基地修整的企业号接受了一项紧急任务，科克船长一行奉命到属于中立区的宁布星球，解救遭到叛徒控制的乐园市民。叛军挟持了企业号到银河系中心去寻找根源。', '威廉·夏特纳', '威廉·夏特纳', 6.9, 6923, 'tt0098382', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2243474607.jpg', 1.4, 9.1, 44.9, 30.9, 13.8, '-0.044512,0.280362,-0.661046,0.499110,0.119786,0.243764,0.558183,0.075330,-0.300905,-0.115710,0.318728,0.497501,0.119667,-0.213951,0.379178,0.139369,-0.230187,-0.131013,0.026358,-0.115807,-0.146947,-0.506652,-0.283744,-0.320237,0.012221,-0.555109,0.837419,0.280524,-0.405823,0.016443,0.107058,0.189224,-0.102620,0.297731,-0.042035,-0.069066,0.221915,-0.225766,-0.342375,0.239108,-0.271571,-0.099749,-0.117534,0.157620,-0.120489,0.332482,0.670069,-0.176089,-0.171595,0.064786,0.415618,-0.383916,-0.159267,-0.373097,0.345276,0.022297,-0.259425,0.073762,0.072581,-0.011639,-0.120038,-0.122536,-0.970040,-0.048381,0.373250,0.159119,-0.402339,0.174391,-0.222602,-0.021339,-0.113514,-0.293343,0.229485,0.105918,0.399993,0.338356,0.171422,0.220639,-0.423873,0.284486,0.609853,-0.115803,-0.534418,0.284436,-0.062947,-0.465510,-0.301258,-0.456824,-0.499764,0.160314,0.121233,-0.154161,-0.029713,0.122999,-0.557829,-0.016426,-0.285910,-0.548726,0.024920,-0.449739,0.135035,-0.749087,0.010295,0.126499,0.228382,-0.023176,0.190311,-0.185116,0.804072,-0.459502,0.054451,0.951488,0.073649,-0.630868,0.733284,0.198300,0.079942,-0.312338,-0.022675,0.221606,-0.000186,0.293039,-0.157928,0.202883,0.080094,-0.329950,-0.385187,0.166590', '25928048', '3769423', '1473562', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302589', '中国姑娘', '剧情', '60年代下半期的某一天。巴黎某区。银行家的女儿维络尼卡在一位已同双亲外出度假的女友处借来的住宅里，召开“马列主义共产党”支部会议。房里堆放着一大批小红皮书，墙壁上醒目地挂着一些手写的毛泽东语录。在从北京传来的无线电广播声中，维洛尼卡宣布支部正式成立，并以“阿登-阿拉维亚”的命名，以纪念被法国共产党开除出党的这一同名小说的作者波尔·尼赞。支部成员包括青年演员吉罗姆、女佣人伊沃娜、画家基里洛夫和大学生亨利。维洛尼卡给支部规定的任务是“进行两条战线的斗争”。正值此时，原先缺席的亨利走了进来。他血流满面，是在巴黎大学同法共党员们进行关于中国“文化大革命”的辩论时被打伤的。这使维洛尼卡更有理由宣布她的“路线”的正确性，即不仅不与法国共产党为伍，而且视其为主要敌人……导演戈达尔醉心于宣扬毛泽东主义，他的这部机敏的讽刺作品激怒了循规蹈矩的批评家。戈达尔当时的妻子Anne Wiazemsky在片中饰演一个哲学系学生，她对校园里的四个毛主义小组成员很同情。他们的目标老是为外界因素所干扰，如招贴海报，红宝书，教条化的颂歌等，似乎总也弄不清自己政治信念的真正含义。他们也不能对实践活动给予任何一点思想上的支持。戈达尔显然处处站在学生的立场上，尽管在描述他们的狂热时尽量向革命者的传统风格靠拢。', '安妮·维亚泽姆斯基', '让-吕克·戈达尔', 7.5, 5661, 'tt0061473', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247580225.jpg', 1.3, 4.7, 31.6, 43.2, 19.2, '0.447261,-0.096668,-0.597825,0.794651,0.093381,-0.146492,0.577617,0.147675,-0.317618,-0.196438,0.242180,0.722809,0.003580,0.139171,0.311000,-0.121592,-0.498242,-0.641602,-0.252831,-0.095141,-0.274271,-0.637364,0.012957,-0.126593,-0.242493,-0.261062,0.586051,0.039115,-0.362932,0.217850,0.348330,0.216585,0.061658,0.176805,0.058130,-0.209070,0.162759,-0.248506,-0.103653,0.073114,0.128990,-0.051260,-0.257211,0.110492,0.109827,0.419480,0.524719,-0.409998,0.075924,0.031005,0.538951,-0.261742,0.046488,0.174577,0.370957,0.002383,0.309322,0.344392,0.100573,0.121853,-0.115009,-0.205517,-0.743988,-0.161448,0.018418,0.335640,-0.541815,0.706556,-0.142865,0.114679,0.022879,-0.173949,0.107672,0.285718,-0.070662,0.202707,-0.067397,-0.011041,-0.350825,0.128931,0.342891,0.127858,-0.354422,0.055306,-0.426712,-0.311804,-0.134571,-0.014552,-0.415670,-0.270441,0.182687,-0.227916,-0.003269,0.034972,-0.607066,-0.040985,-0.049213,-0.286291,0.078812,-0.307823,-0.042211,-0.743347,-0.000633,-0.310051,-0.129315,-0.057325,0.179104,-0.122344,0.806870,-0.791334,0.040802,0.385048,0.222725,-0.209920,0.696469,0.177412,0.135101,-0.213144,-0.353328,0.226331,0.244542,0.363287,0.000722,0.487711,0.113225,-0.318057,-0.215415,0.522054', '27602116', '1870681', '10763928', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302605', '远山的呼唤', '剧情', '寒冷偏远的北国，人们祖祖辈辈生活于此。在这片纯然且严苛的土地上，盛开着一朵来自他乡、柔弱而又坚强的鲜花。她叫风见民子（倍賞千恵子 饰），早年不顾家人的反对，决然跟随爱人来到北国经营农场。数年前丈夫撒手人寰，民子既要继续支撑农场，又要抚养儿子武志（吉岡秀隆 饰），个中艰辛谁人知。某天，一名沉默寡言有着坚毅面庞的男人路过农场，他去而复返，恳请民子留他在这里帮工。虽则顾虑重重，但是民子还是收留了这个名叫田岛耕作（高倉健 饰）的男人。耕作背负着不堪回首的过去，在这个远离城市喧嚣的偏远所在，他全身心地投入劳作，既与武志结下深厚的友情，也赢得了周围人的信任。他的坚毅也慢慢开启了民子的心门……本片为“民子三部曲”的最后一部，前两部为《家族》和《故乡》。©豆瓣', '高仓健', '山田洋次', 8.7, 13968, 'tt0080843', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2213081303.jpg', 0.1, 0.3, 9.2, 44.4, 46, '-0.037535,0.194393,-0.639137,0.625017,-0.155756,-0.389742,0.661800,0.284234,-0.274708,-0.098002,0.225612,0.752885,0.373192,0.280817,0.112819,0.025197,-0.183505,-0.335643,-0.230608,-0.126430,-0.155533,-0.118381,-0.176183,-0.244920,-0.354263,0.008568,0.771308,0.270251,-0.015408,0.553522,0.075634,0.193541,-0.173434,0.312909,-0.277367,-0.007770,-0.220827,0.164880,-0.249485,0.052534,-0.220315,-0.309317,-0.322943,-0.046481,0.018104,0.406611,0.675834,0.038377,-0.236603,-0.252990,0.363563,-0.064043,-0.038104,0.191403,0.125030,-0.096593,0.057967,0.340629,-0.400631,-0.110532,-0.028517,-0.300644,-0.610419,-0.120950,0.198893,-0.010938,-0.772472,0.680189,0.143941,-0.387450,-0.037753,-0.520756,0.116595,0.245309,-0.044924,0.417788,-0.324510,-0.028380,-0.149879,0.264082,0.521590,-0.029143,-0.253068,0.234299,-0.366206,-0.328817,0.248187,-0.432559,-0.824341,-0.287088,-0.027756,0.007618,-0.095424,0.183579,-0.661050,0.159756,-0.148453,-0.117154,0.161794,-0.364142,-0.254013,-0.296170,-0.053749,-0.451057,-0.272164,0.285780,0.191713,-0.269963,0.824245,-0.667674,0.233612,0.524298,0.374193,-0.442536,0.685584,0.049807,0.099359,-0.068042,-0.212036,0.578739,0.026300,0.432210,-0.035885,0.102831,-0.347772,0.104677,-0.474329,0.400186', '26348103', '3445516', '1292720', '3732800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302619', '八月狂想曲', '剧情', '本片以长崎作为本片的拍摄背景。透过四个孩子的眼睛，记录了麻麻获旅居美国七十年的兄长邀请前往夏威夷，以圆兄妹团聚的美梦。然而麻麻的亡夫多年前被原子弹炸死，这事令麻麻梗梗于怀，迟迟未答应前往相聚，藉著美日混血的侄儿到访，一场缠绕四十多年的 仇恨，终于得到解结。全片清新怡人， 笑中有泪。', '村濑幸子', '黑泽明', 7.5, 6801, 'tt0101991', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1590633839.jpg', 1.6, 3.8, 32.2, 42, 20.4, '-0.095693,0.034172,-0.789911,0.480248,0.334170,-0.412425,0.466578,-0.113613,-0.250881,-0.145151,0.084769,0.597979,-0.496286,0.552426,0.050509,0.137552,-0.070147,-0.538458,-0.254693,-0.140595,-0.158562,-0.105501,-0.172434,0.403858,-0.122202,-0.064087,0.727597,0.195530,0.156279,0.684248,0.214713,0.095116,-0.228890,0.119517,-0.203802,-0.073127,-0.016432,0.283720,-0.438226,0.375245,0.038078,0.002652,0.086986,-0.238417,-0.032184,0.298302,0.517126,-0.199648,0.198251,-0.232688,0.094039,-0.035538,-0.153794,0.305491,0.141318,0.344137,0.232657,0.013320,-0.375177,-0.162664,-0.066416,-0.243909,-0.470932,-0.005513,0.374380,-0.098036,-0.441137,0.398571,-0.142688,-0.235008,0.068289,-0.245198,0.352184,0.347721,0.114919,0.672220,-0.187129,0.599925,-0.205038,0.074692,0.734845,-0.321109,-0.119380,0.074909,-0.131224,-0.285436,0.552816,-0.220502,-0.165969,0.441931,0.048190,0.001663,0.079561,0.330028,-0.474318,-0.038076,-0.511628,-0.023252,0.329191,-0.276385,-0.113388,-0.668733,-0.229898,-0.085356,0.026229,0.263220,0.336490,-0.276227,0.548141,-0.411978,0.332776,0.196978,0.036096,-0.138821,0.643163,0.340161,0.121033,-0.198961,0.046285,0.405725,0.099982,0.000037,0.192123,-0.003625,-0.245312,0.251767,-0.394423,-0.167919', '26687241', '1303333', '3606973', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302628', '多情剑客无情剑', '动作', '当年以“小李飞刀”的绰号名震江湖的李寻欢（狄龙 饰），迄今沉寂已长达十个年头。谁知近来二十年前横霸江湖的梅华盗的再度出现，而且传言这一切皆为李寻欢所为。为了给自己正名，同时也为了见一见一直挂念的表妹林诗音（余安安 饰），李寻欢辗转回到关中，并与途中结识了高傲的独行剑客阿飞（尔冬升 饰）。十年前李寻欢和龙啸云（岳华 饰）结为兄弟，为报恩更将所爱的表妹让给对方做妻子。当他回到龙啸云的兴云庄时，发现早已物是人非。贪婪无耻肆意践踏着江湖道义，血雨腥风再度掀起……本片根据武侠小说名家古龙的经典名作改编。©豆瓣', '狄龙', '楚原', 7.4, 5388, 'tt0076827', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2266400516.jpg', 0.5, 3.1, 35.5, 45, 15.8, '-0.096362,0.074593,-0.417857,0.540738,0.177577,-0.529995,0.394783,-0.166071,-0.765689,-0.533736,0.102955,0.848980,-0.138276,0.073800,0.241212,-0.082355,0.115194,-0.791105,-0.192930,-0.447771,0.150633,-0.142467,-0.312802,0.136500,-0.293166,-0.133033,0.547715,0.073948,-0.093788,0.549693,0.410579,0.249473,-0.210586,0.293811,-0.338324,-0.009614,-0.425369,0.284790,-0.769500,-0.117420,-0.201458,-0.342674,-0.018179,-0.196650,-0.447772,0.241014,0.566592,-0.281484,-0.325320,-0.256346,0.547427,-0.000915,-0.047952,-0.094815,0.111255,0.076388,0.284603,0.294626,-0.098392,0.004565,-0.170438,-0.165712,-0.780053,0.002554,0.266518,-0.118559,-0.489161,0.448596,-0.296652,-0.129825,-0.036234,-0.026245,0.193825,0.271282,0.465346,0.146263,-0.308501,-0.046424,-0.137801,0.422757,0.509524,0.126778,0.140417,0.400433,0.328013,-0.150950,0.292205,-0.369449,-0.224186,0.076229,0.003340,0.133505,0.152565,0.424863,-0.488360,-0.156568,0.032213,0.142722,0.314554,-0.393283,-0.331645,-0.323179,-0.292313,-0.232285,-0.017669,-0.143994,0.236324,-0.284412,0.609003,-0.729806,0.243615,-0.023898,-0.089847,-0.483360,0.613607,-0.040535,0.028561,-0.175012,-0.366385,0.467286,0.261476,0.266681,-0.020803,0.018884,-0.074766,-0.251779,-0.398188,0.229989', '4301278', '30345227', '27056396', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302638', '幽灵人间', '悬疑', '15年前的一桩交通事故，令一个男人（黄秋生 饰）死于车底。他的头被卡在车身地下，身体却走了一段路后才倒下。这个恐怖的场面，被一个小女孩看到了，吓得目瞪口呆。15年后，发型师Peter（陈奕迅 饰）和June（舒淇 饰）一夜情，却令Peter真的爱上了June。June是一个神秘的女孩，自称阴阳眼可以见到鬼。自从二人交往以来，怪事连连发生，Peter目睹了件件怪事，灵异的现象让他非常苦恼。最后他怀疑眼前的June，并发现她与身着道袍的人碰头。当June提醒他，有无头鬼要索他的命，Peter也只当她胡言乱语，一气之下与她分手。然而June说得没错，一切的灵异诡秘，都来源于15年前的那场车祸。©豆瓣', '陈奕迅', '许鞍华', 6.2, 8103, 'tt0287811', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1423783228.jpg', 2.8, 15.4, 56.9, 19.1, 5.8, '0.367164,-0.201623,-0.788222,0.259330,-0.027995,-0.205273,1.101171,-0.254425,-0.585057,-0.445512,0.286025,0.742735,-0.765591,-0.012983,0.423202,0.118234,0.141932,-0.724601,0.009384,-0.150957,-0.538956,0.065416,-0.077338,-0.067512,-0.304275,-0.271450,0.302158,0.306460,-0.089522,0.485408,0.494415,0.260375,0.007892,0.493596,-0.174648,0.000977,-0.078986,0.295609,0.316017,-0.017296,-0.070445,-0.521245,0.093024,0.438569,-0.259545,0.202338,0.478788,-0.352964,-0.530668,0.098989,0.387327,-0.260734,-0.185014,0.089353,0.420746,0.011406,0.274480,0.151755,-0.218063,-0.316316,0.297899,0.345955,-0.597601,0.205061,-0.072743,0.082282,-0.582252,0.373716,0.059463,-0.045223,0.055442,-0.296880,0.447427,0.215389,0.383431,0.418504,-0.105533,-0.042477,-0.658274,0.219147,0.649284,0.165748,-0.247743,0.516444,-0.094025,-0.473995,-0.278973,0.108365,-0.278298,0.595940,0.241986,-0.032273,-0.457182,0.147512,-0.362207,-0.082502,-0.225878,0.086168,-0.384222,-0.358391,-0.363231,-0.031408,-0.263467,-0.426481,-0.418108,0.201693,-0.181088,-0.259242,0.212006,-0.453119,0.049618,0.517250,0.089325,-0.386182,0.592416,0.186529,0.033665,-0.098620,0.013674,0.126720,0.114426,0.219716,0.171156,0.515834,0.140875,-0.146775,-0.239019,0.422281', '25909236', '21348112', '1309125', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302642', '花火', '剧情', '西佳敬（北野武饰）是一名警察，几年前女儿不幸死去，现在妻子（岸本加世子饰）患白血病已到晚期。好意让他去探望妻子的搭档堀部（大杉涟饰），则在任务中严重受伤，导致下半身瘫痪，与轮椅为伴。后来西在一次逮捕行动中处理失当，又导致后辈田中（芦川诚饰）丧生。引咎辞职的他，想着供养田中的寡妻（大家由佑子饰），接近并安慰老友堀部，黑社会紧追着他索讨利息，这一切都令西感到不堪重负。他决定铤而走险，做件冒险的事情，将一切做个了结。最后，西陪妻子做一次没有归途的旅行。©豆瓣', '北野武', '北野武', 8.7, 107623, 'tt0119250', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p513347103.jpg', 0.2, 0.8, 10.5, 42.8, 45.7, '-0.229211,-0.228578,-0.312414,0.027066,-0.249054,-0.220577,0.614342,0.158924,-0.368939,-0.556555,0.439259,0.622569,0.055840,0.240984,0.198104,-0.068299,-0.107936,-0.548879,0.087474,0.103865,-0.308170,-0.400778,-0.099466,-0.290361,-0.361324,-0.146746,0.547874,0.168594,-0.032086,0.414006,0.200719,0.208810,-0.020775,0.358102,0.130904,0.060457,-0.017046,0.044553,-0.242714,0.172162,0.158625,-0.360250,0.099408,0.262737,0.232812,0.534387,0.672188,-0.151581,-0.262212,-0.415642,0.380730,-0.346997,0.166880,0.357056,0.143864,0.197086,0.021774,0.456835,-0.498827,-0.307385,0.125827,0.098916,-0.622810,-0.004992,-0.030586,0.115177,-0.641716,0.233344,-0.165403,0.088529,-0.012224,-0.389773,0.191064,0.460298,0.330906,0.146568,-0.296363,0.154358,-0.071559,0.290712,0.949038,-0.053340,0.117505,0.096162,-0.053709,-0.117746,0.270844,-0.427726,-0.332680,0.071096,-0.111884,0.075453,-0.190202,0.312493,0.163087,-0.149587,-0.406519,-0.151871,-0.198892,-0.082495,0.213338,-0.130966,0.213321,0.107064,-0.492495,0.025442,0.175048,-0.359431,0.303902,-0.292044,0.119593,0.660807,0.394050,-0.645812,0.390716,0.301506,0.260365,-0.279188,0.186872,0.236223,-0.045456,0.260636,0.245173,-0.103338,0.083200,0.073436,-0.454892,0.091722', '1309116', '26678784', '4728584', '26996783');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302654', '奇门遁甲', '喜剧', '清康熙二年，八旗总教头高雄（高雄 饰）因触犯满汉通婚之法，被肃亲王指使蝙蝠法师（袁信义 饰）截杀，危急关头高雄绑架肃亲王的小贝勒出逃，岂料他意外将小贝勒勒死……十四年后，江湖上有“奇门”（梁家仁 饰）和“遁甲”（袁祥仁 饰）的师兄妹法力高强，虽然他们为人古怪但却不时造福一方，在奇门遁甲生活的镇上，就潜藏着隐姓埋名多年的高雄，高雄当年拾到一个孤儿“树根”（袁日初 饰），尽心尽力将其抚养成人。不久高雄身份暴露，蝙蝠法师再度追杀，并计划将树根伪装成昔日失踪的小贝勒，以便令自己控制朝廷。高雄力战蝙蝠法师身死，树根只得向奇门遁甲二人求助，随引发连场不可思议的法术对决……©豆瓣', '袁日初', '袁和平', 8.1, 23477, 'tt0084557', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2344677928.jpg', 0.3, 1.6, 18.9, 49.6, 29.5, '0.146122,-0.114174,-0.279185,0.606339,0.027108,0.071237,0.331896,0.084835,-0.433940,-0.481661,0.428456,0.484846,0.017023,-0.086556,-0.103773,-0.218297,0.094288,-0.596751,0.061530,-0.053830,-0.172905,-0.308822,-0.207618,-0.385474,-0.212362,-0.485560,0.435213,0.198493,-0.113186,0.423153,0.128771,0.237098,-0.519305,0.070376,-0.111662,0.194434,-0.104359,-0.120682,-0.076458,-0.087568,-0.359129,-0.678668,-0.031386,0.000151,-0.025517,0.350393,0.701990,-0.279099,0.163093,-0.332745,0.161000,-0.170748,-0.112551,0.196771,0.529765,0.026849,0.024651,0.248697,0.027679,-0.082571,-0.042741,0.094467,-0.431984,0.079022,0.325128,-0.123379,-0.413428,0.333603,-0.059403,0.003868,-0.163019,-0.237919,-0.003960,0.269091,0.170046,0.096368,-0.160435,-0.042216,-0.303893,0.259231,0.263611,-0.182558,-0.017900,-0.275396,0.043978,-0.412244,0.163524,-0.510684,-0.034640,-0.121719,0.407257,0.006725,0.108737,0.426323,-0.306310,-0.167158,-0.372639,0.415868,0.142696,-0.107044,0.128868,-0.385717,0.071657,-0.202648,-0.194512,0.067182,0.423676,-0.059979,0.441403,-0.365731,0.138326,0.285959,0.257708,-0.538570,0.384181,-0.191461,0.239195,-0.073701,-0.114350,-0.057618,0.288658,0.326967,0.170630,0.268043,-0.199297,0.037808,-0.215027,0.017644', '4881604', '1306490', '1440164', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302661', '飞天小女警 剧场版', '动画', '《飞天小女警》（英文：The Powerpuff Girls），是美国时代华纳公司旗下的Cartoon Network推出的动画片。小镇村本来只是一个平凡的小镇，自从科学家尤教授来到镇上以后，这个平凡的小镇就摇身一变成为一个举世瞩目的地方。尤教授希望可以运用科学方法，创造出世界上最“完美”的小女孩。他将蔗糖和香料还有各种美好的材料混在一起，不过，他不小心将神秘的黑色化学物质「X」也给加了进去，结果就创造了三位模样可爱，嫉恶如仇，誓与罪犯周旋到底的飞天小女警：花花（Blossom）、泡泡（Bubbles）、 毛（Buttercup）。三人组成了一个世界之最的队伍，她们靠天赋拯救了世界。尤教授一心想将三位飞天小女警教育成普通的女孩子，可是他却没有办法阻止她们与魔猴啾啾、毛茸怪兽、阿米巴帮，以及蟑螂教练等一班坏蛋们斗智斗力。©豆瓣', '凯茜·卡瓦蒂妮', '克雷格·迈克科雷肯', 8.1, 19799, 'tt0289408', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2257978711.jpg', 0.4, 2.1, 23.6, 41.6, 32.4, '0.284275,0.078525,-0.344425,0.616972,-0.297314,-0.162155,0.493211,0.001635,-0.117601,-0.033151,-0.219187,0.518456,0.048849,0.190453,0.084778,0.045298,-0.021711,-0.437326,-0.092919,-0.122003,-0.313256,-0.357607,-0.325585,-0.378168,-0.025492,-0.376732,0.450991,-0.063348,-0.164594,0.244995,0.164835,0.147364,-0.250170,0.163109,-0.452456,-0.082286,0.200532,-0.080475,-0.003606,0.195731,-0.174774,0.039088,0.098343,0.059400,-0.052037,-0.003640,0.743625,-0.448078,-0.042597,-0.341585,0.136010,-0.113080,-0.128530,-0.140079,0.184434,-0.329485,0.401147,0.055558,0.185274,0.142019,0.183120,-0.236966,-0.770690,0.101173,0.136395,-0.009238,-0.532777,0.157407,0.071820,-0.103448,0.184801,-0.311858,0.172050,0.012152,0.460291,0.364081,0.097320,0.293042,-0.559517,0.253983,0.487143,0.074620,-0.197625,0.332547,-0.287412,-0.421031,-0.157613,-0.305517,-0.055409,0.028263,0.284004,-0.177164,-0.251443,-0.125867,-0.803443,0.083845,-0.178459,-0.117214,0.116377,-0.164957,-0.039221,-0.476935,0.182416,-0.123232,-0.322963,-0.142923,0.181854,-0.125580,1.095196,-0.503775,0.110189,0.346834,0.226199,-0.418464,0.804155,-0.059129,0.024004,-0.303966,0.012240,-0.186805,0.279055,0.319606,0.110293,0.505143,-0.011716,-0.088306,-0.234420,0.432393', '4181031', '27602116', '24284209', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302662', '双城故事', '剧情', '阿伦（谭咏麟）与志伟（曾志伟）打小便是一对好友，分离20年重相见时，志伟办了一家养鸡场，阿伦在一家PUB苦练歌艺，梦想成为一名歌星。志伟邂逅Olive（张曼玉）后介绍她与阿伦认识，令他们生出感情，志伟虽也心仪Olive，但鉴于兄弟情深只把情感藏在心底。后来阿伦如愿以偿成为当红歌星，同志伟与Olive相处时间日益减少，令他们于“被冷落”中生出共患难的心情。一场台风摧毁养鸡场，志伟黯然离去，Olive也在了解到志伟出走真相后，悄然与阿伦分手。但三人的缘分并没到此终止。©豆瓣', '谭咏麟', '陈可辛', 7.8, 11495, 'tt0102886', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2228233904.jpg', 0.4, 2, 28.3, 48.2, 21.1, '0.039802,-0.183946,-0.617329,0.106102,0.358071,-0.486015,0.680258,0.020946,-0.458321,-0.129978,-0.116980,0.832072,-0.583179,0.403771,0.279681,-0.399863,-0.174694,-0.628289,0.155868,-0.208171,0.382780,-0.449109,-0.086303,0.104645,-0.155212,-0.160804,0.734635,0.138782,-0.116759,0.866923,0.246291,0.032474,-0.391433,0.455570,0.062648,0.220805,0.244883,0.379689,-0.838551,-0.052559,0.141248,0.000323,0.002115,-0.076802,0.016666,0.274397,0.516554,0.028105,-0.250668,-0.038936,0.032102,-0.091585,0.085073,0.096814,0.130182,0.130441,0.134890,0.292908,-0.284455,0.214758,-0.227286,0.158526,-0.328585,0.374230,0.061730,-0.243550,-0.365231,0.380334,0.044854,-0.154345,-0.160425,-0.208843,0.290055,0.312889,0.468134,0.277494,-0.360259,0.213631,-0.131295,-0.122686,0.999377,-0.148888,-0.092476,0.560366,0.064851,-0.422540,0.170872,0.125691,-0.211295,-0.032769,0.073660,0.341556,0.135145,0.395748,-0.524734,-0.125306,-0.223431,0.315829,0.292423,-0.647523,0.095944,-0.284210,-0.509760,-0.276158,-0.577853,-0.094821,0.273276,-0.488110,0.558889,-0.753209,0.206089,0.142993,0.283514,-0.465891,0.745892,0.303999,0.260705,-0.158287,0.182682,0.460546,-0.193992,-0.178502,0.048902,0.168878,-0.231284,0.154369,-0.254345,0.180903', '25721544', '4728584', '1294713', '1422067');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302673', '人鱼传说', '喜剧', '教师阿志（郑伊健 饰）自小怕水，一次溺水被人鱼小美（钟丽缇 饰）所救，小美体内的珍珠却被阿志误吞下肚。失去了珍珠的小美无法回到大海，只好假扮学生进入了阿志所在的学校，希望拿回珍珠。没想到阿志得知秘密后就算被吓坏了，还是依然与小美展开了一段唯美的人鱼恋。纸包不住火，小美的秘密最后让校长（郑则士 饰）知道了，校长决定抓住小美。虽然阿志极力救出阿美，他们的恋情却又遭到了挑战。©豆瓣', '郑伊健', '罗文', 7.3, 32320, 'tt0110969', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2459834795.jpg', 0.4, 3.4, 42.3, 39.8, 14.1, '0.233198,0.170871,-0.540491,0.340219,-0.123154,-0.428818,0.665178,0.065273,-0.641533,-0.128642,-0.017878,0.475521,-0.377806,0.253899,0.070046,0.011581,-0.267230,-0.573704,0.082967,-0.283710,-0.229326,-0.226566,-0.103205,0.399316,0.104015,-0.301280,0.502938,-0.035339,-0.266198,0.451698,0.383344,0.242300,-0.145345,0.369441,0.020914,0.346965,0.056538,0.091843,-0.209965,0.177046,0.233726,-0.347127,0.124711,0.236362,0.196155,0.232127,0.656123,-0.433713,-0.044691,-0.084870,0.059982,-0.600147,-0.182896,0.292413,0.183032,0.147435,0.353638,0.029764,-0.529423,0.058395,0.329415,-0.072393,-0.366791,0.311774,0.406374,0.128873,-0.514272,0.285866,-0.126491,0.140963,0.057989,-0.404911,0.122522,-0.009920,0.447076,0.365778,-0.093795,0.200307,-0.428348,-0.062438,0.818625,-0.141236,0.098670,0.167878,0.090308,-0.359795,0.218866,-0.008218,-0.184082,0.411785,0.539077,0.493281,-0.495493,0.021175,-0.529003,-0.314477,-0.667047,-0.087058,0.034081,-0.421434,-0.193632,-0.079221,-0.007156,-0.079428,-0.128734,0.199671,-0.008230,0.007497,0.735536,-0.625609,0.116013,0.307740,0.373653,-0.452196,0.430057,0.173037,0.024332,-0.255847,0.179346,0.139572,0.044626,0.663829,0.487066,0.374750,-0.327425,-0.433303,-0.510627,0.030895', '25721544', '21619567', '35030151', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302675', '夏天的故事', '剧情', '贾斯伯（梅尔维尔·珀波 Melvil Poupaud 饰）来到布列塔尼亚的海边小镇度假，在这里，总是独来独往的他结识了餐馆招待玛戈（阿曼达·朗格勒 Amanda Langlet 饰），两人一见如故相谈甚欢。贾斯伯告诉玛戈，他和一个名叫琳娜（奥蕾莉亚·诺林 Aurelia Nolin 饰）的女孩相约于此，玛戈对此一笑了之不置可否。在一场舞会上，贾斯伯遇见了野性美女苏兰（Gwenaëlle Simon 饰），对她一见钟情，苏兰也对这个能歌善舞的小伙子心存好感。虽然玛戈心里不是滋味，但表面上她大度的祝福了这段感情。贾斯伯邀请苏兰共赴他心目中的梦幻之岛，没想到姗姗来迟的琳娜出现在了他的眼前。梦中情人的出现让贾斯伯无比欢欣，很快就忘记了和苏兰的约定，可是琳娜的性格如这个夏天一般多变，此刻还风和日丽，下一刻便已下起瓢泼大雨。苦恼的贾斯伯只得去向玛戈倾诉，但心怀爱意的玛戈也无法给予他更多的帮助。在这个充满了激情和艳遇的夏天，徘徊在三个女孩之间的男孩究竟会怎样面对自己的感情呢？', '梅尔维尔·珀波', '埃里克·侯麦', 8.3, 44441, 'tt0115940', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1404178381.jpg', 0.1, 0.8, 14.3, 52.3, 32.5, '0.460508,0.081569,-0.838289,0.603843,-0.096816,-0.251524,0.929989,0.077093,-0.316470,-0.161006,0.269795,0.871831,-0.461003,0.448896,0.322635,0.165544,-0.391229,-0.563999,-0.053444,-0.188270,0.012404,-0.594590,-0.367348,0.114142,-0.174257,-0.119683,0.226176,-0.019166,0.000957,0.669618,0.361857,0.224990,0.166453,0.747239,-0.183414,-0.031461,0.120402,0.306136,-0.154480,0.170905,0.081678,-0.049510,-0.128231,0.286745,-0.075535,0.336777,0.569852,-0.218341,-0.152154,0.083823,0.279706,-0.245753,0.283410,0.088928,0.115899,-0.372614,0.104929,0.003729,-0.260257,-0.035151,0.120769,0.053427,-0.370518,0.241691,0.090792,0.072417,-0.662758,0.477511,-0.039770,-0.270270,0.062460,-0.345635,0.115486,0.284155,0.296000,0.404237,-0.077213,-0.104522,-0.565492,-0.127744,0.776434,0.274460,-0.148487,0.454738,-0.471116,-0.508449,-0.075664,0.131996,-0.496937,-0.135704,0.097810,0.128402,-0.208372,0.291620,-0.605863,0.075330,-0.219942,0.124225,0.036029,-0.736899,-0.055267,-0.604836,-0.248724,-0.688953,-0.545716,-0.083027,0.184055,-0.179369,0.575211,-0.899630,0.308907,0.438853,0.289782,-0.232396,0.706482,0.524025,-0.162686,-0.089910,-0.223085,0.540789,-0.071222,-0.137936,-0.073146,0.524155,0.045122,-0.010661,-0.527678,0.540539', '1292211', '1309172', '1296534', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302678', '逃学威龙3之龙过鸡年', '喜剧', '百万富翁王百万（周星驰 饰）被人用冰锥插死，由于他与妻子汤茱蒂（梅艳芳 饰）的感情破裂，汤茱蒂便有最大的嫌疑。刚好周星星（周星驰 饰）的相貌与王百万几乎一模一样，警方便让周星星假扮王百万让汤茱蒂带回家，好让周星星能够从中寻找证据。当周星星进入王家后，发觉王百万的好友林大岳（黄秋生 饰）也有重大嫌疑。怎料林大岳也同样被杀害。案情疑点重重，周星星后来发现汤茱蒂跟王百万的女秘书有暧昧的关系。©豆瓣', '周星驰', '王晶', 7.6, 122568, 'tt0108293', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1277819805.jpg', 0.4, 3.4, 33.5, 41, 21.7, '0.012981,0.376012,-0.598100,0.594020,0.261306,-0.292218,0.835806,-0.057701,-0.659513,-0.594160,-0.293144,0.265402,-0.489001,0.023368,-0.064370,-0.449365,0.374278,-0.504238,-0.423046,-0.056121,-0.439785,-0.237398,-0.401609,-0.296993,-0.343988,0.112809,0.146084,0.045135,-0.584846,0.092022,0.728816,0.318906,-0.231919,0.439601,-0.321596,0.217530,-0.092746,0.459733,-0.371790,0.147517,-0.106221,-0.229022,-0.092927,-0.159572,0.034548,0.411075,0.666353,-0.100499,-0.415753,0.052583,0.286239,-0.197537,-0.019383,0.099716,0.444027,-0.104036,0.355095,0.059310,-0.354035,-0.234092,0.520156,-0.133649,-0.855752,-0.144589,0.232786,-0.112927,-0.376921,-0.162621,-0.253481,-0.244357,0.367536,-0.033243,0.563210,0.662125,0.370470,-0.041467,-0.072169,-0.019148,-0.571502,0.642284,0.429438,0.412047,-0.107705,-0.282096,-0.059433,-0.700100,-0.265704,0.031370,-0.040078,0.194092,0.561215,-0.089872,0.090608,-0.028955,-0.440665,-0.650158,-0.430990,0.190798,-0.092270,-0.619141,0.318493,-0.321134,-0.171124,-0.547075,-0.290137,0.285475,0.345211,-0.202519,0.508171,-0.457831,0.216342,-0.166077,0.348281,-0.504742,0.469664,-0.145426,-0.152503,-0.345674,0.011494,0.098201,0.487188,0.398797,0.541287,0.363224,-0.081190,-0.441738,-0.305894,0.434178', '3670447', '1944900', '1304318', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302705', '天地英雄', '剧情', '公元700年盛唐时期，中国同阿拉伯及中东在经济、文化上有许多交流，西域的丝绸之路是相互来往的要道，为捍卫其完整，唐朝军队不断与突厥对垒。戍边校尉李（姜文）因不愿屠杀突厥的老人、妇女和孩子俘虏触犯军令成为通缉犯，为缉捕他，皇帝封屡请回国的日本遣唐使来栖（中井贵一）为捕快，并许诺只要能将校尉李捉拿归案，便可满足其回国心愿。其时战事正值严峻，来到西域的来栖又受托护送将军之女文珠（赵薇）回长安，中途他遇见校尉李，一场大战后，两人不分轩轾，相约长安城下再决生死。不久，他们碰上护送经书的朝廷商队及觊觎驼队的响马子安（王学圻），生死大战蓄势待发。©豆瓣', '姜文', '何平', 6.6, 30696, 'tt0374330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2181236622.jpg', 2, 11.4, 49.4, 28.2, 9, '-0.115761,0.274677,-0.551769,0.470276,0.279326,-0.274808,0.377402,-0.008476,-0.484038,-0.261751,0.109862,0.401461,0.082275,-0.046340,0.171985,-0.310182,-0.105109,-0.780275,-0.302787,-0.131532,-0.164493,-0.185542,-0.022081,-0.070677,-0.476908,0.033595,0.521259,0.126520,-0.088648,0.515695,0.064241,0.155289,-0.134953,0.456539,-0.383638,-0.064800,-0.277036,-0.057382,-0.601932,-0.022239,-0.277724,-0.378490,-0.505411,-0.281731,0.054165,0.288896,0.522700,-0.240363,0.153236,-0.302412,0.158893,-0.160214,0.103442,-0.054173,0.515707,0.258201,-0.010779,0.127658,0.070258,-0.195223,-0.300934,-0.176746,-0.131596,0.082598,0.011371,0.122576,-0.535843,0.245466,-0.039348,0.024994,0.033488,-0.473674,0.231065,0.954549,0.185156,0.161418,0.216347,0.135747,-0.505117,0.368869,0.867214,-0.002332,0.024636,-0.478665,0.099804,-0.726871,0.446293,-0.203114,-0.250433,0.056538,0.184628,-0.511619,0.246388,0.333348,-0.457422,-0.108859,-0.370322,0.138595,0.226641,0.015767,0.366910,-0.544626,0.024085,-0.396297,-0.146613,0.255735,0.679252,0.025249,0.487821,-0.504353,-0.099261,0.348861,0.538881,-0.745100,0.368341,0.189812,0.302153,-0.070008,-0.064032,0.086737,0.230527,0.367443,0.077659,0.042820,-0.162321,0.036863,-0.226271,0.102789', '3078390', '25978126', '26852888', '1291822');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302718', '铁血战士2', '动作', '洛杉矶最近黑帮的团伙成员一个个被人残忍杀害，警局认为黑帮火拼又开始了。于是派出探员麦克（丹尼•格洛弗 Danny Glover 饰）去调查这次事件，并将凶徒乘之于法。不料麦克出师不利，反遭这些凶徒袭击，差点丧命。凶徒能杀人于无形，具有隐身的能力。原来这是一群来自外星的专门狩猎人类的怪物，能隐身、身上具有多种武器并能利用红外线监测到人类准确位置。联邦调查局也注意到了这一情况，他们派出了特别行动小组想活抓这些怪物作研究。然而麦克心里只有消灭怪物未受害者报仇这一念头……©豆瓣', '丹尼·格洛弗', '斯蒂芬·霍普金斯', 6.6, 15395, 'tt0100403', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1417780248.jpg', 1.7, 11.1, 53.9, 24.1, 9.1, '0.401460,-0.333106,-0.547615,0.145718,-0.126806,0.104442,0.575885,-0.234286,-0.614044,-0.227336,0.198686,0.262215,-0.026942,-0.264924,0.142145,-0.321566,-0.290107,-0.350814,-0.091935,-0.157536,-0.554752,-0.441163,-0.541387,-0.657691,0.179540,-0.093173,0.350357,0.102932,-0.366412,0.407672,0.110928,0.607580,-0.344568,0.415382,-0.031287,-0.317874,0.235648,-0.604374,-0.215129,0.457754,-0.201839,-0.122176,-0.052618,0.279981,-0.208493,0.479994,0.661000,-0.394790,-0.105929,-0.484360,0.056965,-0.366786,-0.051998,-0.031247,0.714803,-0.100147,0.143140,0.128644,0.334296,0.114627,0.141908,-0.054839,-1.023055,0.045343,-0.008946,0.017258,-0.139871,-0.306796,-0.148988,0.411340,-0.034514,-0.068180,0.270593,0.213839,0.410060,0.098043,0.078083,-0.110271,-0.610061,-0.068176,0.566496,-0.430438,-0.225560,-0.028314,0.116158,-0.619079,-0.111846,-0.459802,0.271523,0.149470,0.509715,0.175490,-0.374356,0.105730,-0.437422,0.027900,-0.241667,0.093109,-0.245376,-0.361552,-0.076490,-0.487593,-0.020239,0.254055,-0.409422,0.225947,0.035385,0.030556,0.466468,-0.718463,-0.014456,0.991769,0.137530,-0.597222,0.121037,-0.035867,-0.061232,-0.004423,-0.317932,-0.111215,0.618028,0.700300,0.295363,0.167933,0.170578,-0.499083,0.044371,-0.094356', '1293605', '26747274', '1297689', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302737', '鬼马智多星', '剧情', '30年代的香港，社局动荡，黑帮林立。香港大亨胡老头这日找到私家侦探哎吆（林子祥 饰），要求其调查胡太太，因为他觉得胡太太这些天表现奇怪。哎吆调查后发现，原来是坏蛋神父卡邦派（麦嘉 饰）人勾搭上了胡太，意欲偷取胡老头价值连城的股票。他们这一计划遭哎吆撞破后，四处追杀哎吆。哎吆亡命之际，又发现了胡老头其实并非什么香港大亨，只是一名老千，他来香港的目的就是要骗卡邦等流氓的钱。胡老头邀请哎吆入伙，一起设局骗卡邦。和好友探长罗宾（泰迪•罗宾 饰）商量后，哎吆决定来个将计就计。©豆瓣', '林子祥', '徐克', 6.7, 4171, 'tt0082485', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p885431412.jpg', 1.4, 7.6, 55, 26.7, 9.3, '0.229294,-0.413046,-0.264561,-0.038830,-0.082720,-0.599591,0.089727,-0.035053,-0.527554,-0.477581,-0.430804,-0.263638,-0.229301,0.368044,0.291773,0.103512,-0.141712,-0.281063,-0.116343,-0.081814,-0.079975,-0.312773,-0.000694,-0.160237,-0.109946,0.192662,-0.371801,0.280029,-0.125183,0.272638,0.618871,0.235515,-0.101924,0.077207,0.051706,0.357940,0.579302,0.050113,-0.140696,0.055541,0.268215,-0.220984,0.305158,-0.117640,0.340893,0.210374,0.043808,-0.138517,0.289406,-0.223342,0.086085,-0.089048,-0.081391,-0.199452,0.460613,-0.230996,0.224081,-0.038419,-0.036009,-0.467288,0.215292,-0.111619,-0.164308,0.563457,-0.007660,-0.332450,-0.442681,-0.348846,-0.123274,0.359528,-0.369120,-0.347851,0.545144,0.212149,0.625834,-0.089137,0.474785,0.204035,-0.416688,0.074215,0.462942,0.049864,0.346533,0.207699,0.332897,-0.291027,0.075820,0.025169,-0.023520,0.332594,0.045318,-0.378053,0.060707,-0.282606,-0.329840,-0.324885,-0.072743,0.240495,-0.072149,-0.225563,-0.111686,-0.202786,-0.271827,0.030990,0.111011,0.173421,0.226665,-0.132996,0.259941,-0.345739,-0.234358,0.415118,-0.042035,-0.635122,0.508759,0.094328,-0.504042,-0.160410,-0.043107,-0.624756,0.602466,0.166814,0.330404,0.133444,0.120641,-0.621218,0.267548,-0.236436', '1304021', '1297213', '3074415', '1920620');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302753', '飞鹰计划', '喜剧', '历经艰辛刚摆脱非洲土人的追杀，飞鹰Jackie（成龙）就接到伯爵的急电，要其迅速赶到西班牙。二战末期，知道自己来日不多的德国纳粹把在欧洲抢掠所得的数万吨黄金隐藏在了非洲撒哈拉大沙漠一个秘密基地，伯爵急电Jackie，正是要其配合冷艳的考古专家Ada（郑裕玲）再赴非洲寻找这批黄金，途中，藏金副官的外孙女Elsa加入寻宝队伍。费尽艰辛终抵大沙漠后，Jackie一行人于一次意外无意发现了藏金基地，而就在他们欣喜若狂之际，一个神秘大汉突然出现，一场生死博斗遂即展开。©豆瓣', '成龙', '成龙', 7.8, 73267, 'tt0099558', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1975184595.jpg', 0.2, 1.6, 26.3, 50.1, 21.8, '-0.113579,-0.014510,-0.896311,0.438988,0.328141,-0.303437,0.430287,-0.234673,-0.362102,-0.056251,0.339255,0.718416,0.062580,-0.219513,0.138835,0.046973,-0.258618,-0.407404,-0.246989,-0.179898,-0.266673,-0.183447,-0.577689,-0.241838,0.114558,-0.283017,0.422550,0.309470,-0.273277,0.519948,0.230542,0.328523,-0.445246,0.404443,-0.412131,-0.063114,0.454795,0.059742,-0.280396,0.356665,-0.149550,-0.183465,-0.296495,0.037771,0.103507,0.232734,0.611042,-0.151188,-0.078386,-0.082712,0.284261,-0.355345,-0.136821,-0.180363,0.579953,-0.060099,-0.128162,-0.016859,-0.178403,0.009630,-0.091910,-0.267845,-0.454083,-0.002306,-0.049803,0.210882,-0.608069,0.204698,-0.034213,0.133809,0.177583,-0.395038,0.048737,0.846251,0.187555,-0.027427,0.219572,-0.017901,-0.440485,0.321554,0.783723,-0.355381,-0.037566,0.037210,0.179424,-0.492017,0.266662,-0.206359,-0.179444,-0.041583,0.676898,-0.192535,-0.329628,0.151964,-0.686676,0.117673,-0.632073,-0.318920,0.109913,0.072924,-0.328326,-0.586609,-0.017847,-0.083110,-0.131721,0.363371,0.169553,0.186151,0.708632,-0.474733,0.419039,0.830324,0.094443,-0.373813,0.333484,-0.238258,0.014455,-0.152541,0.297961,0.028170,0.386241,0.511983,-0.027538,0.280045,-0.131925,-0.247808,-0.276279,0.067118', '1294941', '34461680', '1306723', '1292849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302762', '鬼影人', '悬疑', '年轻干练的米兰达（海莉·贝瑞 Halle Berry 饰）是一名卓有成就的犯罪心理学家，她和丈夫共同经营一家精神治疗机构，两人无论生活还是事业都春风得意，顺风顺水。不过一向理性的米兰达也遇到了难缠的对手，她的病人之一克罗伊（佩内洛普·克鲁兹 Penélope Cruz 饰）因谋害继父背叛入狱，克罗伊经常沉浸在不切实际的幻想中，这令米兰达困扰不已。在某个雨夜，米兰达驱车回家途中险些撞上一名小女孩，继而发生了令人难以置信的事情。当她从昏迷中苏醒后，发现自己被关在了精神病院，接下来则要面对谋杀丈夫的指控。米兰达想方设法要证明自己的清白，在这一过程中也发现了恐怖、黑暗的真相……本片荣获2004年青年选择奖最佳女主角奖（Halle Berry）。©豆瓣', '哈莉·贝瑞', '马修·卡索维茨', 6.5, 8669, 'tt0348836', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1785569096.jpg', 1.7, 10.1, 56, 26.5, 5.7, '-0.017004,-0.065623,-0.701079,0.390892,-0.084068,-0.326398,0.828096,0.002810,-0.580222,-0.389839,0.484983,0.774373,-0.101315,0.320554,0.558011,-0.017920,-0.249784,-0.725646,-0.057754,-0.034729,-0.361020,-0.368297,-0.355963,-0.212036,-0.148413,-0.353221,0.528870,-0.129609,-0.264393,0.289605,0.353940,0.460125,-0.048479,0.273432,-0.089873,0.003619,0.345828,0.109374,-0.166151,0.169047,0.069399,-0.519164,-0.104028,0.195517,-0.115291,0.408330,0.617214,-0.099084,-0.295734,-0.088462,0.405879,-0.318421,-0.189931,0.242055,0.274384,-0.181620,0.123230,0.200847,-0.112079,-0.191062,0.057557,0.055674,-0.892286,0.031729,0.153263,0.105886,-0.517432,0.239774,-0.007798,0.129780,0.009556,-0.166381,0.151091,0.295422,0.309153,0.432234,-0.232831,0.097281,-0.339410,0.316768,0.552004,0.046593,-0.291563,0.370456,-0.315353,-0.334696,0.011153,-0.216987,-0.562470,-0.062701,0.422924,0.163478,-0.239814,0.401048,-0.174582,-0.054017,-0.132996,-0.080005,-0.270655,-0.188959,-0.212194,-0.301775,-0.197459,-0.403330,-0.365137,-0.077769,-0.047094,-0.238198,0.492465,-0.674932,0.265712,0.697565,0.040492,-0.496284,0.545793,0.225581,0.197050,-0.133537,-0.209043,0.385484,-0.086338,0.032525,-0.176310,0.312607,-0.031329,-0.112404,-0.420341,0.461462', '34890458', '1793491', '25828589', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302769', '我的失忆男友', '喜剧', '丁叮（应采儿 饰）从美国回来后到了北京戏剧学院读书，一次偶然的机会她认识了阿当（古天乐 饰），这名大帅哥是出了名的“花心大萝卜”，他却对性格爽朗，外表清秀的丁叮。他遇见丁叮的时候正在甩掉一堆追求他的女生。两人在匆忙间一见钟情，彼此倾心。不久，阿当便向丁叮表达了爱意，两人顺利坠入爱河，共享了许多甜蜜的热恋时光。可是好景不长，阿当患上了失忆症，把丁叮当作了陌路人。丁叮顿时晴天霹雳，但面对深爱的阿当，她不懈努力，要与阿当重新开始。丁叮以为两人能够从此幸福的走下去，但阿当的失忆症状总是不时发作，一次次忘掉丁叮……©豆瓣', '古天乐', '马楚成', 6.3, 29091, 'tt0379975', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486551329.jpg', 3, 15, 54.9, 20.4, 6.7, '0.135252,0.255077,-0.497769,0.354637,-0.315989,-0.429032,0.759896,0.082866,-0.152191,-0.060962,-0.553006,0.432768,-0.418316,0.600096,0.200893,-0.063172,0.080968,-0.787683,0.069124,-0.165044,-0.242207,-0.106440,0.130024,-0.300998,-0.205874,0.088037,0.143487,0.236468,-0.386320,0.342650,0.555861,0.308561,-0.386736,0.770555,-0.348242,0.306981,0.242563,0.443983,-0.147848,-0.046902,0.295361,-0.277341,0.020698,-0.157458,-0.122814,0.275326,0.531183,-0.069629,-0.141127,0.130413,0.401526,0.077738,0.097321,0.253977,0.087441,0.120215,-0.057498,-0.340424,-0.063584,0.017949,0.026997,-0.221648,0.005497,-0.096622,-0.063046,-0.159622,-0.524495,0.390329,0.019008,0.354566,0.000884,-0.105451,0.101184,0.009620,0.460084,0.325482,-0.146158,0.140959,-0.268727,0.337065,0.573198,0.320127,-0.621099,0.638928,-0.044358,-0.719529,-0.167552,0.189357,-0.446660,-0.198092,0.816860,0.230630,-0.181587,0.202127,-0.472299,-0.099458,-0.154648,0.200526,-0.079362,-0.259546,-0.134329,-0.571926,-0.172364,-0.603559,-0.321861,0.440485,-0.173027,-0.469384,0.789699,-0.862379,-0.029779,0.148602,-0.022102,-0.313294,0.491107,0.299416,0.079633,-0.259493,0.675792,0.305224,0.348039,0.010837,0.522365,0.421532,-0.458168,0.357886,-0.606713,0.403872', '26354526', '1307146', '24839498', '6557144');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302770', '阿基拉', '动作', '1988年7月，关东地区使用新型炸弹进行爆破，第三次世界大战即刻爆发。31年后，人类从一片废墟中重建都市，东京湾上建立了巨大城市——新东京。世界仿佛要恢复到以前的繁荣。2019年的一个夜晚，新东京郊外的封闭高速公路上，暴走族团体正在公路上飙车。带头的少年，是一名叫做金 田的职业高中学生。突然，街上出现了一位奇怪的矮个子男子，暴走族少年铁雄为躲避车祸连人带车飞出公路。正当金田要拿那位男子问罪之时，军队驾驶直升飞机赶到。将那位矮个男子与铁雄一起收押。铁雄进入了一个陌生的地方，这里似乎在从事超能力的研究。而金田则在盘算如何营救铁雄。二人都不知道，他们的未来，因为神秘力量——阿基拉而已经开始了巨大的变化。©豆瓣', '岩田光央', '大友克洋', 8.5, 79501, 'tt0094625', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p711283071.jpg', 0.3, 1.3, 13.1, 41.9, 43.4, '0.189323,0.052392,-0.695279,0.377058,0.033342,-0.167821,0.720419,-0.115246,-0.447083,-0.195033,0.389598,0.610542,-0.197833,0.316333,0.547413,0.062106,-0.236636,-0.606899,-0.187314,-0.293669,-0.776204,-0.295834,-0.345634,-0.232997,0.022804,-0.342709,0.628104,0.344171,-0.131427,0.448931,0.056515,0.215243,-0.274254,0.607370,-0.168599,-0.311885,0.111376,0.012291,0.017827,0.227509,-0.456786,-0.524145,-0.055756,-0.077818,-0.129049,0.387132,0.778361,-0.087241,-0.050676,-0.417293,0.209484,0.026317,-0.166363,-0.115215,0.456149,0.092297,-0.109794,-0.127551,-0.049295,-0.347598,-0.186843,-0.397451,-0.049575,0.121184,-0.203092,0.050650,-0.482876,0.227349,0.038938,-0.099980,0.078616,-0.261445,0.270051,0.322157,0.349685,0.378354,-0.189826,0.106789,-0.424538,0.103359,0.690491,0.007930,-0.478932,0.161879,0.018001,-0.446992,-0.346351,0.054963,-0.238473,-0.187380,0.130721,0.037003,-0.149082,0.072031,-0.652370,0.175950,-0.253269,-0.167051,-0.076165,0.092628,-0.611213,-0.651541,0.072455,-0.160557,0.036785,0.233491,-0.025030,0.036108,0.677051,-0.694707,0.228110,0.401084,0.298881,-0.359139,0.436334,-0.406418,0.218836,-0.385427,-0.117111,-0.023643,0.034473,0.630537,-0.040447,0.357015,-0.469483,-0.096319,-0.447082,0.479339', '21619567', '2159244', '1467779', '1458894');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302776', '我爱贝克汉姆', '剧情', '因为热爱足球，而喜欢贝克汉姆。因为贝克汉姆而更加喜爱足球。与许多球迷一样，杰西（帕敏德·纳格拉 饰）就是这样一个女孩。作为一个居住英国的印度裔少女，杰西有过人的足球天赋，她热爱足球，狂热迷恋贝克汉姆，房间里面贴满了小贝的照片。她的梦想就是能像小贝一样成为出色的球员。然而，这一切在印度家庭都是不被允许的。一次偶然的机会，杰西结识了霍斯特女队的队员朱莉(凯拉·奈特莉 饰)，并在她的邀请下加入了球队。杰西便瞒着家人，偷偷地开始编织她绿荫场上的梦想。造物弄人，杰西和朱莉竟然同时爱上了她们的教练乔（乔纳森·莱斯·梅耶斯 饰）。面对家庭的反对，朋友的冲突，杰西内心充满矛盾，完成足球之梦，原来如此艰难。也许，心中的偶像，会给杰西带来力量吧…©豆瓣', '帕敏德·纳格拉', '顾伦德·查达哈', 6.5, 7851, 'tt0286499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p785902518.jpg', 1, 9.3, 58.9, 25.3, 5.5, '0.350753,-0.118129,-0.558795,0.647179,-0.260847,-0.344165,0.594269,0.132950,-0.553487,-0.071608,0.203841,0.825191,-0.217737,0.144421,0.377486,0.172787,-0.211994,-0.839545,0.106315,-0.080356,-0.210281,-0.408583,-0.194492,-0.463378,-0.032464,-0.402618,0.646573,-0.106133,-0.134375,0.528434,0.252145,0.332189,0.376428,0.342223,-0.039543,0.227016,0.285115,-0.043445,-0.465209,0.253775,0.037196,0.180941,-0.142532,0.381600,-0.046386,0.021297,0.468514,-0.197087,0.128832,-0.094481,0.302842,-0.120356,0.252363,0.293628,0.113932,-0.119291,0.405587,0.000648,0.192915,0.112865,0.320289,-0.091586,-0.656210,0.184430,0.110637,0.165975,-0.483992,0.633518,-0.128076,-0.065538,0.182249,-0.199337,-0.066758,-0.019797,0.329306,0.243222,-0.168560,-0.053261,-0.296481,0.093320,0.565328,-0.019468,-0.230616,0.230606,-0.745623,-0.322632,-0.034286,-0.211636,-0.728161,0.099737,0.496065,-0.032910,-0.000518,0.358763,-0.441018,0.202443,-0.175415,-0.186502,0.046940,-0.571736,0.090917,-0.478744,-0.146854,-0.399754,-0.336275,-0.194912,-0.140398,-0.229924,0.886820,-0.919244,0.219942,0.813672,0.266959,-0.255038,0.658955,0.094282,-0.021007,-0.271419,-0.212300,0.418158,-0.107481,-0.030321,-0.175806,0.420593,0.190251,0.039464,-0.155285,0.628656', '35030151', '1292720', '3445516', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302786', '天脉传奇', '动作', '早在十三世纪，西藏的能工巧匠制作了“敦煌之心”，它是能够打开保存玄奘舍利子之处的宝物。数百年来，当初在敦煌守卫舍利子的僧人们渐渐变成了一个杂技世家，延续着自己保护圣物的神圣使命。这个杂技世家的最新一代传人——白嫣飞（杨紫琼 饰）、白跃童姐弟正在青岛进行表演，而此时，白嫣飞的前任男友、父亲（赵文瑄 饰）的徒弟艾里克（本•卓别林 Ben Chaplin 饰）应大亨卡尔的要求，成功盗得了敦煌之心。艾里克获悉敦煌之心的秘密后，又再次从卡尔手中偷走了宝物。带着敦煌之心的艾里克找到白氏一家，白嫣飞怨恨艾里克三年来音信全无，但是家族的使命令她不能退缩，愤怒的卡尔派遣手下对白家袭击，双方在敦煌展开了一场宝物争夺之战……©豆瓣', '杨紫琼', '鲍德熹', 5.5, 19413, 'tt0293660', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1988307040.jpg', 6.8, 28.1, 52.9, 9.9, 2.3, '0.001867,0.245472,-0.595502,0.734750,-0.011956,-0.148759,0.205780,-0.021683,-0.361354,-0.253419,0.361043,0.823214,-0.017158,0.050156,0.037589,0.324588,-0.350575,-0.590466,-0.023826,-0.414077,-0.015372,-0.232708,-0.147554,-0.178627,-0.142252,-0.298211,0.524813,0.027527,-0.061465,0.412458,0.245339,0.305177,-0.270503,0.137814,-0.261144,-0.029282,0.137906,-0.006354,-0.156506,0.347942,-0.008989,-0.400659,-0.153389,0.325517,-0.153037,0.262234,0.415080,-0.412557,0.191859,-0.355299,0.024417,-0.169980,-0.115071,0.053658,0.333748,0.163010,-0.075704,0.318350,-0.153584,-0.160763,0.277615,-0.170069,-0.493800,-0.240582,0.097480,0.185588,-0.617666,0.424581,-0.330862,0.201239,-0.178544,-0.356994,0.232970,0.367842,0.051214,0.128674,-0.139096,-0.060232,-0.570424,0.275831,0.437519,-0.565866,0.068676,0.169846,0.151996,-0.456418,-0.009054,-0.157628,-0.443186,-0.212472,0.871261,0.162761,0.274340,0.275721,-0.726450,-0.076401,-0.518435,-0.020236,0.171602,-0.039559,0.034772,-0.436117,-0.162946,-0.154086,-0.122291,-0.182729,0.168378,-0.208863,0.845123,-0.501365,0.247337,0.426358,0.029420,-0.588612,0.337185,-0.053247,0.083683,-0.183375,-0.255676,0.203128,-0.048534,0.589367,0.082142,0.139784,0.143049,-0.148256,-0.231945,0.333052', '1309069', '26665875', '27602116', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302789', '鹳鸟踟蹰', '剧情', '故事发生在希腊边境，有人说它是一部关于世纪末的绝望的电影。它关注的是在东欧共产主义没落和苏联解体后，当代的边境、难民和变迁的问题。一位政治家离开议会从家里出走，消失得无影无踪。新闻工作者Gregory Karr正在报导停留在边境的移民和难民的情况，他在人群中碰到一个人非常像那个失踪的政治家。他还找到了一个被作为国境线的河流一分为二的小镇，看到一场超现实的婚礼，新娘和家人在河的这边，新郎和亲友在河的那边。那个人的身份一直没有确定，而那些不幸的难民以及被分割的村庄使Karr理解了他对人情世故的绝望。', '马塞洛·马斯楚安尼', '西奥·安哲罗普洛斯', 8.8, 6902, 'tt0102439', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2480385103.jpg', 0.2, 0.7, 8, 39.6, 51.4, '0.430536,-0.096266,-1.006482,0.702777,0.024348,0.091323,1.050289,-0.045321,-0.508511,-0.085606,0.062626,1.064670,-0.226482,0.062845,0.321240,-0.054127,-0.346901,-0.878343,-0.108704,-0.185507,-0.366244,-0.415087,-0.162997,-0.323128,-0.170372,-0.391536,0.889099,0.490819,-0.371915,0.544404,0.131852,0.158555,-0.263955,0.695603,-0.517826,0.171021,-0.013205,0.048354,-0.188380,0.164115,-0.027072,-0.267162,-0.168722,0.071919,-0.109861,0.445294,0.645260,-0.231988,-0.050685,0.290816,0.331086,-0.584810,-0.010480,0.214280,0.745673,-0.220046,-0.033953,0.140853,-0.188421,-0.194313,-0.084024,0.021487,-0.733650,-0.111621,-0.023327,0.674451,-0.756493,0.718703,0.018997,-0.181125,0.054745,-0.385432,0.671239,0.582774,-0.133271,0.622765,-0.212585,-0.024607,-0.881846,0.310419,0.821290,0.041595,-0.509213,0.379185,-0.093996,-0.543007,-0.223271,-0.174802,-0.397836,-0.062406,0.441879,-0.385477,-0.575293,0.295353,-0.727963,0.053007,-0.008407,-0.740443,0.051799,-0.447236,-0.411410,-0.684618,-0.191340,-0.575518,-0.174469,0.133662,-0.071904,-0.023552,0.950346,-0.896336,0.211750,0.585939,0.432833,-0.683977,0.986300,0.104987,0.145874,-0.039388,-0.086391,0.244923,0.248100,0.544070,0.079022,0.382455,-0.101893,-0.241184,-0.510800,0.349147', '3055049', '30162520', '1478066', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302795', '茉莉花开', '剧情', '影片根据苏童小说《妇女生活》改编。20世纪30年代，18岁的茉（章子怡饰）不听母亲（陈冲饰）劝阻，执意当了电影演员，并被导演孟先生（姜文饰）包养。日本占领上海，孟先生逃往香港，留下茉一人生下女儿莉。到了60年代，莉（章子怡饰）嫁给工人邹杰（陆毅饰），与母亲茉（陈冲饰）住在一起。因为莉不能生育，夫妻二人领养了女儿花，莉却陷入担心丈夫不忠的偏执狂躁中。80年代，花（章子怡饰）与外婆茉（陈冲饰）相依为命。花与大学生小杜（刘烨饰）相爱并怀孕，却不得不面临小杜变心的事实……本片获第7界上海国际电影节评委会大奖，并获第13界中国电影金鸡奖最佳女主角（章子怡）奖及最佳音乐（苏聪）和最佳录音（吴凌）提名。©豆瓣', '章子怡', '侯咏', 7.3, 55748, 'tt0370969', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1008950338.jpg', 0.7, 4.5, 37.1, 42.7, 15, '-0.243819,0.039601,-0.424561,0.355420,0.476209,-0.381512,0.577782,0.098668,0.013470,-0.322822,-0.329666,0.603316,-0.215292,0.236802,0.260634,0.068262,-0.367792,-0.444911,0.223509,-0.104498,0.039335,-0.163045,0.224246,-0.093371,-0.281550,-0.123757,0.899973,-0.005326,-0.104866,0.334466,0.389101,0.197867,-0.190797,0.202001,0.103880,0.497751,0.258648,0.127047,-0.798760,0.340565,-0.013642,0.004164,0.027050,0.162348,-0.031964,0.198097,0.591979,-0.133424,0.208687,0.001327,0.639893,-0.216900,-0.335924,-0.469010,0.377282,-0.339299,0.470772,0.279157,0.124035,0.183968,-0.039052,-0.367232,-0.328048,0.011024,0.557794,-0.024615,-0.360108,0.135723,-0.269672,0.305049,-0.219067,0.096294,0.252578,0.212495,0.345615,0.355820,-0.106473,0.146855,-0.182096,0.663666,0.165212,0.175325,-0.025971,0.479758,-0.319550,-0.629617,0.245860,-0.462630,-0.525647,0.410823,0.021630,-0.048168,-0.104873,-0.026737,-0.057181,-0.261102,-0.092600,0.012282,0.402520,-0.444798,0.179612,-0.506394,-0.106774,-0.526222,-0.386464,-0.151803,0.115772,-0.376927,0.541192,-0.446599,0.057297,0.341713,0.374344,-0.471775,0.596942,0.146391,0.050640,-0.439043,-0.094614,0.436164,-0.503441,0.035753,-0.034136,-0.078810,0.033993,-0.141226,-0.027886,0.173054', '1388176', '1780122', '26980827', '26410593');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302799', '卫斯理传奇', '动作', '著名作家、冒险家卫斯理（许冠杰 饰）在埃及游历时，受到了大富翁霍普的请托，后者请卫斯理寻找他的师兄高大威（泰迪罗宾 饰）。卫斯理在收到高大威主动寄来的信件后，赶赴尼泊尔与其汇合。高大威其时正为青帮龙头白奇伟（狄龙 饰）寻找传说中的喜马拉雅龙珠，眼看成功在即却身陷“邪教”的追杀中，卫斯理帮助高大威潜入宗教内部夺得龙珠，在撤出时飞机失事高大威不知所踪，逃跑失败的卫斯理被带到只有五岁的小佛爷面前，卫斯理受小佛爷感化，承诺追回龙珠，以延续此一教派。返回香港的卫斯理再遇霍普助手，并拒绝向对方交出龙珠，第一时间赶到白公馆，白奇伟之妹白素（王祖贤 饰）是卫斯理的书迷，在白素帮助下，卫斯理取得龙珠，但是一场三方围绕龙珠的争夺战才刚刚开始……©豆瓣', '许冠杰', '泰迪·罗宾', 6.6, 5157, 'tt0090302', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1387182825.jpg', 1.1, 8.8, 55.6, 26, 8.5, '-0.109817,0.407765,-0.741609,0.341006,0.159779,-0.100760,0.268790,0.113464,-0.158652,-0.335692,0.276339,0.538036,-0.160977,0.145643,0.125909,-0.003459,-0.252652,-0.373192,-0.002937,0.071559,-0.025166,-0.347360,-0.391221,0.113409,-0.125450,-0.434708,0.686511,0.291247,-0.158035,0.600310,0.162196,0.157947,-0.361445,0.218607,-0.273565,0.026610,0.049210,0.223375,-0.395591,0.671379,0.103105,-0.341193,0.035803,0.063882,0.076822,0.192777,0.479505,-0.409877,0.141385,-0.035063,0.270526,-0.302546,-0.231849,0.033103,0.274128,0.097945,-0.078924,-0.034650,-0.416196,0.207206,-0.015684,-0.103341,-0.498884,0.081052,0.095952,0.297869,-0.366755,0.213970,-0.106891,0.146480,0.099732,-0.409341,0.017438,0.367559,-0.047200,0.055201,-0.088558,0.355184,-0.409972,-0.206003,0.501138,-0.228199,0.009179,-0.231624,0.262694,-0.266019,0.174636,-0.084510,0.052774,-0.018991,0.492598,-0.058722,0.343278,-0.025672,-0.532682,-0.254254,-0.589688,0.077211,0.204870,-0.125190,-0.294875,-0.792954,-0.003887,-0.021660,0.098012,-0.009991,0.147735,-0.383262,0.615658,-0.526844,0.245791,0.156385,0.372545,-0.406406,0.552050,-0.093897,0.088413,-0.367323,-0.158256,0.344677,0.390391,0.301696,0.006790,-0.143448,-0.090877,-0.273543,-0.278686,0.013712', '2369613', '1293656', '20274039', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302812', '知法犯法', '动作', '阿Mike（吴彦祖 饰）出身警察之家，可惜父母早死，与舅舅住在一起，一直被当作多余的人。在警局做警察太过拼命，又成为同行的眼中钉。内心郁闷只有在警局locker一个人冲凉时才能缓解。一次任务中的意外让Mike受到处分，组长刘Sir让他放假。Mike在打游戏机的时候偶遇洪兴大哥任擎天（曾志伟 饰），二人结缘。随后在酒楼又偶遇任的妻子Pauline（关秀媚 饰），Mike被美丽的阿嫂吸引。刘Sir最终决定让Mike去做卧底，埋伏在任的身边，而一直郁郁不得志的Mike却自打着出人头地的如意算盘……©豆瓣', '吴彦祖', '麦子善', 6.8, 7407, 'tt0284985', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2033979577.jpg', 1, 6, 52.9, 31.3, 8.7, '0.111488,0.030185,-0.651301,0.541007,-0.222354,-0.467371,0.638653,0.355804,-0.587240,-0.283682,0.032511,0.572445,-0.156236,0.386119,0.193273,-0.340019,-0.002365,-0.650130,-0.091027,-0.162659,-0.233569,-0.368790,0.204683,-0.339165,-0.049196,0.030508,0.351002,0.037628,0.063859,0.412945,0.671023,0.167912,-0.189544,0.661101,-0.109780,-0.050699,0.036009,0.178939,-0.181072,0.105004,0.141318,-0.564703,-0.130030,-0.002838,0.170894,0.319028,0.636576,0.001363,-0.252166,-0.178627,0.046637,-0.094622,0.037849,-0.006896,0.485389,-0.227170,0.020577,-0.008493,-0.226909,0.104230,0.428852,0.071596,-0.633001,0.039503,0.272157,-0.132171,-0.665092,0.271589,0.113426,0.125973,0.023066,-0.350676,0.544135,0.337275,0.305657,0.396407,-0.221324,0.308768,-0.457282,0.406783,0.741591,0.086035,0.266770,-0.076681,-0.133086,-0.191814,0.226366,-0.328185,-0.629874,-0.020376,0.318730,-0.076013,-0.086929,-0.056423,-0.305316,-0.210995,-0.018783,0.075518,-0.211893,-0.703866,0.215598,-0.445291,0.089860,-0.071436,-0.208858,0.448340,0.061333,-0.244906,0.462707,-0.837412,0.122637,0.507326,0.246872,-0.578914,0.748196,0.311605,0.130655,-0.278686,-0.151209,-0.020607,0.324728,0.302112,0.407802,0.355796,-0.249827,-0.182282,-0.393356,0.030774', '25870679', '1301022', '2990737', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302815', '罗马风情画', '剧情', '这不是一部普通的纪录片，而是透过意大利电影大师费德里克．费里尼独特的艺术家眼光为罗马古都写出来的一篇个人回忆录。全片打破传统叙事手法，以现实与超现实场面交叉穿梭进行，渗入了大量的幻觉和回忆，充分表现出费德里克．费里尼个人对罗马的爱恋，也让观众看到了这个城市隐蔽着的另一面。男星彼得．龚扎莱斯在片中饰演年轻时代的费德里克．费里尼，而费德里克．费里尼则演出他自己，在片中可以看到马戏团对费氏作品根深蒂固的影响。也可以从中揣摩出费尼电影风格的一些基本特质，喜爱他的影迷不容错过。', '彼得·冈萨雷斯·法尔孔', '费德里科·费里尼', 8.4, 7133, 'tt0069191', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1221824736.jpg', 0.6, 1.1, 14.4, 47.2, 36.7, '0.371118,0.006209,-0.632686,0.869334,0.130482,-0.251375,1.057966,-0.056938,-0.245389,-0.246397,0.150512,0.820184,-0.193111,-0.178267,0.336091,-0.138620,-0.616431,-0.597072,-0.235994,-0.161379,0.139433,-0.533316,-0.677028,-0.118550,-0.177499,-0.447688,0.623326,0.173498,-0.565766,0.277937,0.288029,0.257719,0.304731,0.096150,0.336984,-0.090878,0.067078,-0.090993,-0.195084,0.123423,0.148880,-0.140361,-0.337816,0.199366,-0.184308,0.228445,0.691699,-0.279765,-0.127257,0.467363,0.754364,0.012543,0.168430,0.007623,-0.193399,-0.046976,0.352738,-0.060158,-0.058759,0.313774,-0.433498,-0.304896,-0.868121,-0.250110,0.237390,0.077823,-0.575457,0.558609,-0.088058,-0.301230,-0.016713,-0.271931,0.010765,-0.031437,0.613997,0.545445,0.065877,-0.153838,-0.378420,0.411401,0.154928,0.286980,-0.513622,0.399483,-0.796714,-0.532156,-0.507981,-0.483438,-0.435907,0.092731,0.616830,-0.299745,-0.231479,0.220060,-0.449989,0.071945,0.037463,-0.246879,-0.128022,-0.357030,0.111115,-1.104787,-0.268572,-0.338061,0.048593,-0.470707,0.156376,-0.395114,0.958697,-0.541920,0.121588,0.672953,0.084627,-0.061622,0.927457,-0.086965,-0.188334,-0.072305,-0.311955,0.235401,0.091267,0.157506,0.110045,0.744216,0.319260,-0.306720,-0.509609,0.760092', '2027945', '1293433', '3318306', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302827', '人工智能', '剧情', '21世纪中期，由于温室效应，南北极冰川融化，地球上很多城市被淹没。此时，人类科技已经高度发达，人工智能机器人就是人类发明出来用以应对恶劣自然环境的科技手段之一，而且，机器人制造技术已经高度发达，先进的机器人不但拥有可以乱真的人类外表，还能感知自身的存在。莫妮卡的儿子马丁重病住院，生命危在旦夕，为了缓解伤痛的心情，她领养了机器人小孩大卫（海利•乔•奥斯蒙特 饰），大卫的生存使命就是爱她。马丁苏醒，恢复健康，回到了家里，一系列的事情使大卫“失宠”，最后被莫妮卡抛弃。在躲过机器屠宰场的残酷追杀后，大卫在机器情人乔（裘德•洛 饰）的帮助下，开始寻找自己的生存价值：渴望变成真正的小孩，重新回到莫妮卡妈妈的身边。谁也不知道他能否完成自己的心愿，脱胎换骨成为真正的人，等待他们的只是凶吉难料的旅程……©豆瓣', '海利·乔·奥斯蒙', '史蒂文·斯皮尔伯格', 8.7, 414803, 'tt0212720', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792257137.jpg', 0.3, 1.1, 11.5, 38.7, 48.4, '-0.021254,0.333308,-0.502881,0.401357,-0.520289,-0.128455,0.502719,-0.055687,-0.366228,-0.375660,0.190349,0.583648,0.130065,0.143482,0.013453,0.057728,-0.476147,-0.327508,0.054189,0.043317,-0.523493,-0.444182,-0.507659,-0.431784,0.011010,-0.430044,0.757209,0.257298,-0.327177,-0.071139,-0.144352,0.262320,0.007359,0.395771,-0.204488,-0.020318,-0.058033,-0.279224,-0.406434,0.163676,0.022747,0.101835,0.256195,0.389229,-0.199962,0.092510,0.505248,-0.311600,0.033595,-0.383466,0.388805,-0.346697,0.090885,-0.041663,0.054317,-0.110181,-0.135023,-0.067271,0.050790,0.124309,0.253531,-0.152297,-0.973877,-0.095634,-0.009877,-0.028096,-0.318764,0.128653,-0.153103,0.139326,-0.121609,-0.273871,0.167393,0.459132,0.318533,0.700200,-0.342038,0.088851,-0.636887,0.172268,0.681208,-0.241144,-0.503763,0.603318,-0.307289,-0.654175,-0.308870,-0.636931,-0.335116,-0.125329,0.212706,0.194245,-0.305286,0.413451,-0.420772,0.159046,-0.321640,-0.236581,-0.006341,-0.261472,0.129275,-0.564761,-0.077046,-0.300994,-0.259628,-0.062888,-0.036458,-0.718459,0.755860,-0.639918,0.266466,0.533333,0.335817,-0.467567,0.354638,-0.316016,0.106103,-0.362941,0.020440,0.704610,-0.075477,0.350261,0.032105,0.086731,0.061789,0.138599,-0.277916,0.728277', '1811755', '27098364', '1793491', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302868', '傲慢与偏见', '剧情', '班纳一家五个女儿待嫁闺中，应上流贵族彬格莱之邀参加盛大舞会。班府大小姐简妮（莫琳·奥沙利文 Maureen O''Sullivan 饰）深受彬格莱青睐，相互倾慕。彬格莱的好友达西（劳伦斯·奥利弗 Laurence Olivier 饰）虽迷恋二小姐伊丽莎（葛丽亚·嘉逊 Greer Garson 饰），但因性情傲慢和原家中总管的儿子韦翰的污蔑招致伊丽莎白的误会与偏见。表哥柯林斯向伊丽莎白求婚遭拒后与夏绿蒂结合，并法定继承班家财产。达西再次在自己的庄园与伊丽莎白相遇时，态度诚恳、礼仪周全，伊丽莎白弄清事情真相，两人终于从傲慢与偏见的迷失中走了出来，缔结幸福之果。©豆瓣', '葛丽亚·嘉逊', '罗伯特·Z·伦纳德', 8.2, 14123, 'tt0032943', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1353558009.jpg', 0.3, 1.8, 17.9, 46, 34, '0.078442,0.075860,-0.427384,0.491195,0.051365,-0.549419,0.769807,0.010240,-0.303228,-0.391627,0.092288,0.907435,-0.407849,0.542538,0.580732,0.286620,-0.334639,-0.459273,0.012433,-0.013206,0.078705,-0.731273,0.339038,-0.386336,-0.042059,-0.203227,0.063284,-0.070384,-0.251593,0.689235,0.477180,0.409722,-0.399532,0.221702,0.159608,-0.064713,0.192825,0.279455,-0.634890,-0.250522,-0.089976,0.042800,-0.135086,0.127592,0.461930,0.294140,0.413139,-0.354435,0.096974,-0.268677,0.240646,0.326917,0.289551,0.516878,0.142022,-0.152229,0.108110,0.342872,0.099322,-0.151390,-0.048789,-0.166223,-0.247605,0.072789,0.004062,-0.022083,-0.355820,0.489574,-0.120116,-0.249430,-0.128115,-0.170127,-0.176008,0.175274,0.255192,-0.024865,-0.179956,0.167448,-0.288866,-0.238838,0.337023,0.337319,-0.075275,0.193170,-0.342553,-0.640177,0.163646,0.115747,-0.655874,-0.065916,0.276852,0.141679,0.374459,0.669327,-0.424706,-0.501615,-0.467337,0.193747,0.359593,-0.440960,0.060648,-0.592837,-0.149697,-0.667075,-0.403881,-0.328523,0.277629,-0.277391,0.563885,-0.517015,0.260820,-0.027140,0.358139,-0.726546,0.367783,0.370943,0.306755,-0.250314,-0.349693,0.326123,0.027881,-0.277586,0.174429,0.120425,-0.089502,-0.048544,-0.199905,0.255954', '1297239', '1293145', '1299556', '1296824');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302874', '风月', '剧情', '父母双亡的忠良（张国荣）投靠嫁入庞家的姐姐秀仪（何赛飞）时，处处受到姐夫的挤兑和侮辱，一怒之下用鸦片毒废了姐夫，逃到上海后，阴差阳错投入黑帮头目大大门下，成为利用色相勾引富家太太上钩再勒索其钱财的“拆白党”。庞府老爷死后，大小姐如意（巩俐）被立为主事，为骗庞家财产，大大命忠良回到庞府引诱如意，岂料两人日久生出真情，不忍再欺骗如意的忠良独身返回上海，而如意也被大大接到上海，眼见了忠良所从事的“拆白党”勾当，心生死灰。©豆瓣', '张国荣', '陈凯歌', 7.7, 37503, 'tt0116295', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2346776403.jpg', 0.7, 3.2, 28.5, 45.5, 22, '-0.048030,0.060909,-0.208161,0.184541,-0.069492,-0.535220,0.050517,0.452187,-0.688212,-0.040851,0.196676,0.629419,-0.094815,-0.054127,-0.011440,0.228962,-0.064675,-0.371494,0.239693,-0.096043,0.426194,-0.137480,0.227478,0.031099,-0.189829,-0.136768,0.195111,0.074645,-0.198404,0.312426,0.232922,0.264579,-0.146996,-0.036920,0.055004,0.530479,-0.220249,-0.104280,-0.499746,0.268279,-0.202409,-0.367305,-0.080863,-0.220401,-0.140751,0.197484,0.355712,-0.101027,-0.086118,-0.575304,0.470549,-0.324539,-0.139506,0.397649,0.248750,0.008409,0.256602,0.324575,-0.540649,0.107775,0.280641,-0.035293,-0.414524,0.031956,0.036863,-0.222621,-0.702409,0.011632,-0.231382,0.039749,-0.074713,-0.230457,0.170629,0.118724,-0.061523,0.037220,-0.615321,0.168303,-0.420928,0.161145,0.636845,-0.263735,0.257387,-0.169844,0.469285,0.195279,0.747167,-0.781970,-0.084118,-0.054215,0.184566,-0.024903,0.049250,0.444207,-0.445272,-0.265308,-0.523842,0.292279,0.307576,-0.360204,-0.116295,-0.232230,-0.294286,-0.049861,-0.062790,-0.014465,0.478637,-0.134326,0.461198,-0.555384,0.095575,0.234329,0.511761,-1.150371,0.352369,0.079008,0.138451,0.092682,-0.363023,-0.222557,0.394583,0.481969,0.135555,-0.223974,-0.118263,-0.166709,0.243617,-0.162977', '1440958', '1302110', '1421278', '1297574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302912', '儿子的大玩偶', '剧情', '《儿子的大玩偶》：乡镇失业青年坤树（陈博正饰）为了养家糊口，替电影院做“三明治广告人”。他化装成小丑身前身后挂着厚厚的广告牌，但却得不到家人及亲友的认同，总为此事争吵不休。当坤树去掉化装的油彩时，小儿子竟不认识父亲了，被吓得哭闹起来……《小琪的帽子》：王武雄（金鼎饰）退伍后找到一份推销员的工作，公司派他到沿海城镇推销日本生产的压力锅，在小镇内遇到小女孩小琪。然而，王武雄最感到不解的是小琪头上总是紧扣著那顶帽子，让他觉得非常奇怪。同时王武雄的搭档林再发（方定台饰）接到怀孕妻子写信要求他快点回家。但是，压力锅却发生问题……《苹果的滋味》：居住在贫民区的小工阿发（卓胜利饰），被美军汽车撞成残废后住进豪华医院。美军给了他一笔可观的赔偿费，还答应将其哑女送美国学习。阿发一家人悲喜交集，连连向美军道谢……©豆瓣', '陈博正', '侯孝贤', 8.1, 6642, 'tt0085503', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2360897688.jpg', 0.3, 1, 17.4, 56.5, 24.9, '0.109556,-0.009499,-0.595757,0.320227,-0.115098,-0.269432,0.466657,0.260823,-0.202348,-0.138016,0.122443,0.592883,-0.068473,0.258873,0.078039,0.143171,-0.120062,-0.453201,-0.010573,-0.074693,-0.355771,-0.262995,0.095427,-0.141065,-0.263782,0.007918,0.267246,-0.036771,0.068110,0.245442,0.304112,0.054578,0.073215,0.417356,-0.368097,0.086420,-0.071577,-0.233554,-0.140826,0.188586,0.044231,-0.039103,0.038390,0.080151,0.102471,0.269208,0.593622,0.215377,-0.246271,-0.114506,0.296188,-0.114133,0.123471,-0.064505,0.237222,0.228276,0.032251,-0.230064,-0.264000,0.035270,0.480519,-0.096801,-0.290424,0.217547,0.046750,0.066633,-0.740447,0.331098,-0.238958,0.256462,0.158658,-0.387218,0.312918,0.272144,0.074379,0.472666,-0.163216,0.410053,-0.705913,0.194587,0.354476,-0.077833,0.097892,0.159070,-0.406788,-0.140052,0.420844,-0.161268,-0.368022,0.036725,0.152714,-0.138893,-0.220729,-0.199336,-0.222679,-0.130262,-0.104770,-0.183635,0.087727,-0.284586,-0.290193,-0.444820,0.118604,-0.163223,-0.368183,0.013535,0.102459,-0.079357,0.413833,-0.296796,0.036521,0.397641,0.353415,-0.186970,0.522304,-0.077197,0.196844,-0.115519,-0.074827,-0.057815,0.202255,0.301188,0.380778,0.129711,-0.191066,-0.211419,-0.255850,0.176223', '1306505', '25837175', '25731805', '3430271');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302926', '基佬四十', '喜剧', '家声（林子祥 饰）已经四十六岁了，至今仍未成家。他青梅竹马女友丽泉（伍咏薇 饰），要求与他之间做个了断。两人多年来没有结果是因为家声是一名同性恋者。而家声是有一名男朋友Sonny（陈小春 饰）的，但Sonny十分享受花花世界给他带来的虚荣，这样便使得家声觉得十分没有安全感，却又对Sonny的感情越来越深。家声一名同性恋好友永烈因艾滋病死去了，家声劝止永烈的男友（吴镇宇 饰）不要出现在丧礼上，却被Sonny从中捣乱，家声也因此与Sonny分手了。但家声复杂的感情世界并没有因为这样得到解决……©豆瓣', '林子祥', '舒琪', 7.7, 6687, 'tt0117417', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2240454172.jpg', 0.5, 2.3, 28.9, 50.5, 17.8, '0.346992,0.027691,-0.529108,0.626082,-0.161632,-0.374868,1.057993,0.036754,-0.598738,-0.416111,-0.277312,0.950419,-0.278672,0.263932,-0.248371,-0.248402,-0.073473,-0.726090,0.080266,-0.113726,-0.257558,-0.513859,0.136543,0.215870,-0.510500,-0.028813,0.733975,0.090461,-0.345669,0.509366,0.301722,0.213726,0.102815,0.721459,-0.502987,0.058860,0.129558,0.352974,0.002146,0.198629,0.130163,-0.242868,-0.299335,0.533481,0.023499,0.498194,0.480820,-0.141602,-0.408578,-0.094111,0.247311,0.078322,0.132072,-0.022504,0.234351,-0.079990,0.453131,0.532781,-0.203358,-0.216226,0.151774,0.098048,-0.755465,0.307304,0.327606,0.149221,-0.549838,0.489697,-0.304661,-0.515386,0.025777,-0.244038,0.288924,0.467650,0.193715,0.346565,-0.640139,0.242920,-0.563362,0.259948,0.916581,0.173078,-0.222269,0.560847,-0.345765,-0.557422,0.036769,-0.090723,-0.632966,-0.268588,-0.026223,0.172978,-0.030283,-0.006235,-0.388075,-0.021190,-0.131403,0.009247,-0.011464,-0.384817,0.066072,-0.107917,-0.468616,-0.467433,-0.673823,0.206875,0.097949,-0.117403,0.508981,-0.894191,0.190204,0.200917,0.395868,-0.520034,0.625669,0.463457,-0.107077,-0.045205,-0.111263,-0.046229,0.001283,-0.264106,0.303455,0.081909,-0.003818,-0.379513,-0.277829,0.302593', '25721544', '1308755', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302927', '富贵逼人', '喜剧', '骠叔（董骠 饰）在电视台当新闻主播，一家五口都靠他糊口，生活拮据。妻子骠婶（沈殿霞 饰）十分热衷买六合彩，总期待着有中奖的一天。他们每天都梦想自己能变成富人，搬到宽大的屋子居住。他们终于中了六合彩头奖，本来一家人想好好利用这一笔横财，没想到他们存放巨款的银行突然倒闭了。更祸不单行的是，他们变富人的消息招来了恶手——他们的小女儿被绑架了，全家人着急得不得了。他们又变回了穷人，该如何拯救至亲呢？©豆瓣', '沈殿霞', '高志森', 7.6, 24031, 'tt0091090', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2346972513.jpg', 0.2, 1.9, 32.3, 48.7, 17, '0.032806,-0.237973,-0.652168,-0.016978,-0.162518,-0.337064,0.444533,0.259133,-0.281448,0.076737,0.191028,0.731192,-0.174527,0.404820,0.103648,0.203858,-0.304633,-0.242086,0.188119,-0.301164,-0.004699,-0.132365,-0.269041,-0.377425,-0.090112,0.242834,0.092863,0.174325,0.196407,0.051983,0.383585,0.044074,0.150063,0.334713,-0.559940,0.347352,0.033141,0.325591,-0.049166,-0.024462,-0.149779,-0.193935,-0.192065,0.123045,0.299987,0.143474,0.439378,0.094217,-0.285910,0.115711,0.243345,-0.300183,-0.417800,0.077103,0.085818,-0.193522,0.420190,-0.147890,-0.462754,-0.132547,0.269787,-0.033801,-0.646620,0.104544,0.099606,0.014749,-0.675556,0.370125,0.004991,0.083059,-0.033551,-0.411358,0.322962,0.586584,-0.006534,0.457374,0.035988,-0.056687,-0.904264,0.525926,0.671629,-0.306416,-0.055152,0.447651,-0.159003,-0.381338,0.215275,-0.397619,-0.427819,-0.082523,0.505927,-0.129479,-0.116793,0.067319,-0.537560,0.180174,0.082902,-0.275619,-0.011486,-0.448144,-0.109253,-0.352095,-0.066173,-0.174184,-0.293108,0.242754,0.252742,-0.340833,0.573147,-0.425069,0.015999,0.431972,0.348336,-0.688679,0.566023,-0.134118,0.060276,-0.016517,-0.155273,-0.359379,0.020447,0.553935,0.359296,-0.018753,0.058549,-0.089251,-0.081485,0.609366', '3215099', '1835843', '2133293', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302941', '戏梦人生', '剧情', '布袋戏大师李天禄（李天禄饰）出生于台湾的日本殖民统治时期，他用口述回忆自己的戏梦人生，故事终结于日本战败投降。小时候的李天禄家里充满矛盾，母亲去世，来了一位冷酷的继母（杨丽音饰），他跟父亲（蔡振南饰）学得掌上手艺后独自离家，随木偶剧团登台演出、四处游走。年轻时的李天禄（林强饰）入赘女方家里。后来战争爆发，布袋戏被禁。唱歌仔戏到邂逅丽珠（魏筱惠饰），太平洋战争爆发后，他加入“英美击减催进队”，为日本演宣传剧，和日本人有了不错的交情。后来李天禄一家人躲避空袭疏散到南部，这过程中，他失去了亲人，而第二天战争就告结束。©豆瓣', '蔡振南', '侯孝贤', 8.4, 8163, 'tt0107157', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524811511.jpg', 0.3, 1, 12.7, 49.2, 36.8, '0.044271,0.148253,-0.695167,0.475793,0.117426,-0.523740,0.575909,0.016194,-0.298099,-0.379572,0.037260,0.481829,-0.249464,0.132014,0.210199,-0.398148,-0.109066,-0.574390,-0.037129,0.194535,-0.088469,0.018309,0.097985,-0.140957,-0.518706,0.041180,0.400428,0.190608,-0.425820,0.489663,0.198425,0.423030,0.077466,0.244001,-0.067262,0.302135,-0.133972,0.511387,-0.335828,0.151468,0.317323,-0.385380,-0.299279,-0.079469,0.112979,0.240576,0.747693,0.042816,0.197861,-0.545717,0.303985,-0.094503,-0.373143,0.073180,0.463893,0.254401,0.163884,-0.106018,0.025211,-0.352421,-0.393930,-0.107764,-0.128465,0.026291,0.207202,-0.084835,-0.421277,-0.089720,-0.180996,0.246588,0.081300,-0.457440,0.315235,0.491157,0.363228,0.261955,-0.088974,0.342994,-0.452794,0.710917,0.833810,-0.286532,-0.247528,-0.212520,-0.061780,-0.449201,0.050340,-0.237552,-0.281311,0.096673,0.368742,-0.568003,0.188739,0.203192,-0.421739,-0.345183,0.020717,-0.085516,0.127948,-0.115547,0.029081,-0.641559,-0.130274,-0.426855,0.030459,-0.156560,0.132906,-0.131718,0.595739,-0.511353,0.336528,0.073556,0.210796,-0.479357,0.551036,0.237427,0.155869,-0.442185,0.404695,0.195215,-0.075485,0.111072,0.268032,0.164777,-0.012792,0.080922,-0.299863,0.327222', '1295344', '26687241', '1300202', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302977', '赌侠2：上海滩赌圣', '喜剧', '阿星（周星驰 饰）由赌神处学成归来，恰逢不甘心失败的大军集合中南海五大高手复仇，虽有龙五（向华强 饰）相助，但阿星与三叔（吴孟达 饰）仍被大军等人发功送至1937年的上海……阿星与三叔失散后意外击杀谋害许文强之凶手，得以结识丁力（吕良伟 饰），自此与祖父周大福（吴孟达 饰）留在丁力身边，丁力女友如仙（巩俐 饰）令阿星魂牵梦绕，却不知她是自己所中意女孩如梦（巩俐 饰）的孪生姐姐。川岛芳子意欲控制上海，于是网罗大军等人频频向丁力发难，并约定最后以赌局决定胜负，阿星由日本人手中涉险逃脱，终于赶上赌局，而决定这场赌局的关键，却是一个名叫“今晚打老虎”的神秘人物……©豆瓣', '周星驰', '王晶', 7.7, 123338, 'tt0101783', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2349573639.jpg', 0.3, 2.7, 31.4, 43.9, 21.6, '-0.242433,-0.042463,-0.450062,0.297467,0.173380,-0.248930,0.340811,0.145300,-0.469720,-0.353698,0.389042,0.528863,-0.014359,0.126571,0.361151,-0.118142,-0.048440,-0.639858,0.068548,-0.112625,-0.030276,-0.145430,-0.304283,0.002584,0.027463,0.088446,0.558259,0.188498,-0.057661,0.677619,0.495926,0.246507,-0.481052,0.407621,0.043853,-0.119800,-0.075102,-0.023586,-0.608464,0.190949,-0.198515,-0.319390,-0.233371,0.075662,-0.021941,0.329061,0.485878,-0.225044,0.061096,-0.333595,-0.065307,-0.257600,-0.077521,-0.016812,0.105617,-0.094725,0.407506,0.229140,-0.017415,-0.031885,0.026047,-0.166175,-0.425588,0.280349,0.274447,-0.030322,-0.402218,0.101858,-0.199247,0.076085,-0.098823,-0.302030,-0.013714,0.331889,0.367251,0.016661,-0.110183,-0.042958,-0.291574,0.187882,0.527394,-0.128501,0.234756,-0.006285,0.451485,-0.405540,0.161259,-0.303175,-0.255767,0.394547,0.278698,0.238220,0.118694,-0.224900,-0.206772,-0.276563,-0.318061,0.265913,0.083570,-0.328206,0.169192,-0.433393,-0.105361,-0.013527,-0.268062,0.189564,0.164290,0.089035,0.469410,-0.576146,0.061465,0.305685,0.321754,-0.599449,0.401110,0.174492,0.060631,-0.475831,-0.036918,-0.053725,-0.034713,-0.006866,0.057586,-0.053302,-0.067759,-0.288445,-0.153867,-0.178734', '3230460', '35030151', '4301278', '1294713');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1302987', '珍珠港', '剧情', '雷夫（本•阿弗莱特）和丹尼（乔什•哈奈特）是一对自小玩在一起的好兄弟，两人对飞行都有很大兴趣，曾一起学习过驾驶飞机，二战初期，两人又一起加入了美国空军部队。受训期间，雷夫与军中医院里的女护士伊弗琳（凯特•贝金赛尔）坠入爱河。为协助欧洲各国抵抗纳粹德国的侵略，美军决定派出精英部队前往欧洲大陆，雷夫自告奋勇前往参战，并将伊弗琳托付给丹尼照顾，不久，噩耗传来，雷夫的飞机在空战中不幸被德军击落，生还可能几乎为零。伊弗琳与丹尼在相互勉励的伤痛中，萌生爱情。令他们没想到的是，雷夫并没死去，当三人重聚首时，尴尬顿生。日军偷袭珍珠港一事帮他们解了围，雷夫与丹尼决定不做情敌做战友。©豆瓣', '本·阿弗莱克', '迈克尔·贝', 8, 248781, 'tt0213149', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1340424701.jpg', 0.3, 1.9, 21.8, 48.1, 27.9, '0.348377,-0.351107,-0.877425,0.458760,0.193510,-0.283238,0.398408,-0.191512,-0.479369,-0.088716,0.008383,0.793603,0.082710,0.117115,0.347883,-0.273241,-0.586434,-0.797783,0.014489,-0.041549,-0.311051,-0.652427,-0.251243,-0.150041,-0.084282,-0.496970,0.502450,-0.130796,-0.032561,0.922468,0.259923,0.283501,-0.193370,0.656419,0.046997,0.020027,0.201637,-0.066843,-0.534445,0.307037,-0.179577,0.076020,-0.072408,-0.230136,0.373427,0.179198,0.611581,-0.198737,0.206458,-0.310366,-0.416329,-0.315998,0.216074,0.044907,0.392991,-0.010414,0.227233,0.183361,0.013962,0.158727,-0.031132,0.035189,-0.452260,0.067372,-0.016152,-0.304331,-0.640746,0.232010,-0.137305,0.057359,0.192621,-0.029855,0.102358,0.762173,0.229355,0.173188,-0.144510,-0.010907,-0.398593,-0.000118,0.885452,-0.182449,0.047403,-0.055361,0.060687,-0.335870,0.205877,-0.217672,-0.075700,0.024725,0.093400,-0.036156,0.068440,0.356848,-0.470542,0.093689,-0.557452,-0.190670,-0.155010,-0.392049,0.269162,-0.782083,-0.003175,-0.212098,-0.247294,0.139836,0.165289,-0.009918,0.541493,-0.862565,0.273668,0.210450,0.643886,-0.356677,0.622505,0.408236,0.310890,-0.231848,0.025866,0.218730,-0.080168,0.112866,0.200365,0.185600,0.070529,0.138353,-0.285898,-0.064798', '1451563', '1307186', '1897368', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303001', '西伯利亚的理发师', '剧情', '在一辆开往莫斯科的火车上，军事学院的学生安德烈.托尔斯泰（欧列格·缅希科夫 Oleg Menshikov饰）偶遇了风情万种的美国女人珍（朱莉娅·奥蒙德 Julia Ormond 饰），两人暗生情愫。珍谎称自己是个寡妇，来俄罗斯看 望疯狂的机械师父亲（理查德·哈里斯 Richard Harris 饰），但实际上是被请来骗取军事学院院长拉德洛夫将军（阿列克谢·彼得连科 Aleksey Petrenko 饰）信任的交际花，好让机械师的“西伯利亚理发师”伐木机能够顺利驶进西柏林亚。但是没想到将军对珍动了真感情，并想向她求婚，而安德烈对珍的感情愈演愈烈，珍一方面想接受安德烈的感情，另一方面又想完成任务，于是事件发展到了不可收拾的地步。在一次演出中安德烈因为嫉妒和误会，抽伤了院长，被流放到了西伯利亚。在火车站上尽管珍赶上了最后的送别，但是安德烈始终没能和珍见最后一面。十年后，珍终于在西伯利亚找到了安德烈的住所，但终究逃不过命运的改变……若干年后珍回到了美国，把这段往事在信中讲述给了军事学院的儿子。', '朱莉娅·奥蒙德', '尼基塔·米哈尔科夫', 8.6, 38347, 'tt0120125', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1949265483.jpg', 0.3, 1.1, 11.3, 40.7, 46.6, '0.292973,0.212583,-0.609731,0.707651,0.187697,-0.502519,0.480959,-0.048719,-0.507793,-0.102783,-0.085292,0.741404,-0.388505,0.193779,0.277977,0.287829,-0.455507,-0.602615,0.008326,-0.207311,-0.429771,-0.769201,0.076109,-0.189279,0.004246,-0.280079,0.484146,0.095390,0.038166,0.409492,0.243971,0.471647,0.314111,0.407374,-0.142406,0.165422,0.196923,0.043803,-0.210576,0.195277,0.421280,-0.334531,-0.075805,0.298877,0.245397,0.385073,0.687217,-0.128769,0.124552,0.072399,0.155166,-0.365576,0.074626,0.191355,0.309316,-0.057173,-0.126065,0.298653,-0.244296,-0.135795,0.038020,-0.120158,-0.414036,0.231523,-0.078412,-0.085141,-0.684966,0.567324,-0.173522,0.181934,-0.115258,-0.283171,0.354068,0.342021,0.034158,0.384428,-0.210676,-0.010086,-0.514431,0.098370,0.717258,-0.032886,0.026663,0.447101,-0.168213,-0.268530,0.091575,-0.241197,-0.417237,0.056549,0.287272,0.008680,-0.145464,0.123038,-0.478421,-0.276297,-0.676819,-0.043271,0.034394,-0.548312,-0.055882,-0.390073,-0.070860,-0.506014,-0.334648,0.092711,0.027476,-0.244841,0.481664,-0.765560,-0.100165,0.489335,0.224050,-0.489118,0.735813,0.155639,0.007739,-0.258621,-0.020256,0.353992,-0.082703,0.317987,0.390226,0.433060,-0.039750,-0.491107,-0.255750,0.437263', '1895119', '21766698', '25908042', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303010', '蒙娜丽莎的微笑', '剧情', '1950年代，美国女性的社会地位表面看来有了明显提高，然而在如威斯理般著名的女子大学里，教师们教授学生，仍是一切围绕将来的好姻缘打转，并不鼓励她们主动获取自己感兴趣的知识，也不注重培养她们的心里素质。美丽成熟的凯瑟琳（朱莉娅·罗伯茨 Julia Roberts 饰）大学毕业，怀揣理想和热情来到该学校担 任艺术史教师时，便因想散播自由的种子碰壁连连。然而因为风趣、率直、热情、渊博，凯瑟琳很快赢得了学生们的喜爱，她的几个学生，想同男孩一样干出一番事业的琼（朱丽娅·斯蒂尔斯 Julia Stiles 饰）、活泼好动的丽薇（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）等，也慢慢地展露出真性情。然而，另一名学生贝蒂（克斯汀·邓斯特 Kirsten Dunst 饰）要结婚的消息，又将自由浪漫的氛围打破。©豆瓣', '朱莉娅·罗伯茨', '迈克·内威尔', 7.8, 51371, 'tt0304415', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p701334998.jpg', 0.3, 1.8, 26, 49.2, 22.7, '0.445905,0.097773,-0.658288,0.566566,-0.279071,-0.218034,0.386789,0.015606,-0.371941,-0.186469,0.020074,0.507561,-0.243754,0.349770,0.315402,-0.016639,-0.446278,-0.620041,0.134737,-0.119446,0.112234,-0.484134,-0.073219,-0.298583,-0.424719,-0.394337,0.315907,-0.093524,0.093438,0.506025,0.191317,0.271417,0.277293,0.211735,0.033260,-0.118851,0.253912,0.059771,-0.008069,-0.054060,0.158630,0.069480,-0.302967,-0.048528,0.403259,0.181041,0.567316,-0.055699,-0.013652,0.001614,0.510877,-0.026424,0.214695,0.227844,0.222895,-0.001409,0.038347,0.061456,-0.047014,0.183745,0.078019,-0.421262,-0.194251,-0.007744,0.396057,-0.024449,-0.517889,0.423446,0.057930,-0.285810,0.021588,-0.263775,-0.282792,0.155730,0.278936,0.432515,0.270961,0.142442,-0.207141,0.201590,0.418635,0.140184,-0.491878,0.190679,-0.731467,-0.498161,0.004935,-0.267180,-0.652238,-0.112737,0.225510,0.067132,0.045483,0.366543,-0.465906,-0.012237,-0.186972,-0.023669,0.084527,-0.390201,-0.089890,-0.643514,-0.108767,-0.568796,-0.366488,-0.114419,-0.027302,-0.222885,1.255099,-0.844098,-0.039473,0.345493,0.073297,-0.635034,0.558479,0.003353,0.144785,-0.213005,-0.225650,0.440485,0.025886,-0.061801,-0.027518,0.513657,-0.191844,-0.376931,-0.139051,0.370040', '26348103', '25922902', '6963575', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303017', '喜马拉雅', '剧情', '在与天相连的莽莽群山之中有一座藏族村寨，由于生产的粮食不够自给，世世代代靠运盐为生。老首领天尼的儿子本应是下一任村里的头人，却在运盐的路上意外身亡，而众望所归的继任者卡玛在天尼的眼中则是为夺头人之位而蓄意害死自己儿子的罪犯。在一次新的运盐旅程开始前夕，村子里以老天尼和卡玛分别为首的两派各持一辞，互不相让。最终卡玛带领年轻人在提前于老人们占卜的日子出发，而天尼而带领自己当喇嘛的儿子和孙子以前一群老随从按占卜的日子上路。运盐队伍不仅一路风餐露宿还要应对群山之中意想不到的危险，两支运盐的队伍谁能克服艰难险阻先到达旅途的终点？本片影像风格粗狂绮丽、荡气回肠，宛如仙乐般的藏密梵音贯穿始终，令人心旷神怡。该片是由法国、尼泊尼、瑞士和英国四国合作，历时9个月拍摄的剧情与纪录大片，曾入围第72届奥斯卡最佳外语片奖提名以及2000年欧洲电影最佳摄影奖提名，并于当年获得了恺撒最佳摄影奖和音乐奖。', '蒂伦·洛迪普', '埃里克·瓦力', 8.6, 14271, 'tt0210727', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2238295864.jpg', 0.2, 0.9, 11.5, 41.8, 45.6, '-0.207285,-0.337594,-0.650038,0.632075,0.281170,-0.255906,0.463047,0.084737,-0.624517,-0.101946,0.146195,0.751893,0.093759,0.094014,0.559776,-0.268499,-0.346985,-0.581553,-0.312307,-0.306898,-0.227701,-0.276946,-0.203360,0.000772,-0.099566,-0.320913,0.715706,0.220846,0.050487,0.562200,0.466881,0.118821,-0.328132,-0.050032,-0.472713,-0.200958,0.048557,0.020857,-0.364342,0.257725,-0.203582,-0.235717,-0.450468,-0.144505,0.047240,0.264272,0.585584,-0.395805,0.048581,-0.029417,0.185418,-0.259488,-0.097323,-0.044549,0.368719,-0.067938,0.361030,0.430717,-0.053235,0.027292,-0.136968,-0.296746,-0.656714,0.172554,0.113668,0.001432,-0.551659,0.184336,0.194055,-0.032106,0.105083,-0.277123,0.173628,0.300902,0.300523,0.404684,-0.201089,-0.165147,-0.415374,0.184562,0.610497,-0.062668,-0.293408,0.030181,0.075498,-0.450272,0.030329,-0.278103,-0.398843,0.157475,0.325632,0.107757,0.183062,0.252983,-0.443835,0.295678,-0.148605,-0.404567,0.065155,-0.159485,-0.091273,-0.751069,0.169566,-0.308715,0.130390,0.130559,0.285263,0.017140,0.496206,-0.476841,0.331832,0.302445,0.037170,-0.288846,0.707018,0.134737,0.235188,-0.270125,-0.252587,-0.000692,0.009879,0.250519,0.008371,0.159481,-0.211242,-0.092866,-0.255524,0.228124', '1780122', '1294917', '1293656', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303021', '小鞋子', '剧情', '家境贫寒的男孩Ali（Amir Farrokh Hashemian）帮妹妹Zahra（Bahare Seddiqi）取修补好的鞋子时，不慎将鞋子弄丢，为了不被父（Mohammad Amir Naji）、母（Fereshte Sarabandi ）责罚，他央求Zahra暂时保密，说两人可以替换着穿他的鞋子上学，并答应一定会帮她买双新鞋子。Ali原本指望用他和父亲进城打工挣的钱帮Zahra买双新鞋，父亲的意外受伤打消了他的美梦。看到全市长跑比赛季军的奖品是一双运动鞋时，Ali决定参加比赛，但是他错过了报名日期。几经哀求，老师（Dariush Mokhtari ）破例让实力出众的Ali参加了比赛。比赛场上，Ali不断提醒自己，一定要得第三名！©豆瓣', '默罕默德·阿米尔·纳吉', '马基德·马基迪', 9.2, 381256, 'tt0118849', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2165511465.jpg', 0.1, 0.2, 4.2, 28.6, 66.9, '-0.269526,0.152966,-0.087217,0.239508,-0.430428,-0.541195,-0.296579,0.032049,-0.057152,-0.206920,0.110282,0.704881,-0.078055,-0.070984,0.068612,-0.037208,-0.213603,-0.613571,0.426961,0.246551,-0.631733,-0.259813,0.246939,0.001894,0.053062,-0.236595,0.376766,-0.028399,-0.301619,0.634305,0.374023,-0.114565,0.561724,0.396717,-0.289353,-0.426441,-0.481351,0.138939,0.104241,0.444195,0.016654,-0.220717,-0.117778,0.224270,0.633137,0.471995,0.490151,0.233284,-0.056998,0.088625,0.410720,-0.136706,0.224692,0.244963,-0.310146,0.253476,0.151674,0.207640,-0.235945,0.080347,0.273059,-0.373370,-0.353836,0.076713,0.088034,-0.147407,-0.813490,0.542391,-0.366993,0.236412,0.274218,-0.092254,0.204513,0.389120,0.092358,0.115327,-0.094419,-0.047551,-0.682020,0.561986,0.325585,-0.450483,0.704893,0.100968,0.064879,-0.186346,0.516207,-0.402103,-0.288803,0.530468,0.337120,0.083815,-0.302086,-0.369049,-0.343284,-0.404047,-0.159484,-0.603425,-0.140966,-0.538525,0.132563,0.021071,0.226615,-0.026017,-0.524729,-0.061671,0.080471,-0.380514,0.413894,-0.570950,-0.011273,0.599961,0.547823,-0.542944,0.669421,-0.105658,0.394100,-0.125448,-0.140825,-0.380548,-0.050025,0.145827,0.351033,0.469233,0.244740,-0.158999,-0.452659,0.394224', '1293908', '1306505', '1305594', '1293607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303026', '给我一个爸', '剧情', '1988年的布拉格，大提琴手路卡（Zdenek Sverák 饰）丢掉了乐团的工作多时，只能靠为殡仪馆伴奏和修补墓碑为生。这位大龄单身汉在女人面前颇有魅力，他也乐此不疲，但困窘的生活让他不得不违背初衷，与一位苏联女子假结婚以获得报偿。婚后几日，苏联女子转道投奔西德，将五岁幼子科里亚（Andrei Chalimon 饰）丢给路卡抚养，路卡有一搭没一搭的用对方听不懂的捷克话向科里亚抱怨苏联人的霸道，同时还要应付警察对假结婚的追查以及敌视苏联人的母亲。路卡拜托多位女友照顾科里亚，这对父子也慢慢产生了对彼此的依赖，不久苏联政府要接回孩子，路卡趁着八十年代末混乱的形势，带着科里亚离家出走……本片获1997年奥斯卡最佳外语片奖，1996年威尼斯电影节荣誉奖等十几项褒奖。©豆瓣', '兹旦内克·斯维拉克', '扬·斯维拉克', 8.3, 6058, 'tt0116790', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2399528486.jpg', 0.3, 0.8, 13.3, 52.8, 32.8, '0.047411,-0.148919,-0.469132,0.469109,-0.147295,-0.295486,0.533367,0.035406,-0.566472,0.030285,0.177330,0.745929,-0.253088,0.016330,0.408796,0.112451,-0.435108,-0.660702,0.014107,-0.038090,-0.209816,-0.524352,-0.220304,-0.360049,-0.392992,-0.477810,0.465168,-0.151497,-0.141819,0.484931,0.306456,0.131864,0.151172,0.223979,-0.285685,-0.010116,-0.114527,-0.065644,-0.401022,0.284557,0.108023,-0.336400,-0.399415,-0.014549,-0.011666,0.392240,0.585052,0.052643,0.069767,-0.085466,0.193458,-0.290318,-0.150675,-0.033683,0.308427,-0.064060,0.069695,0.317828,-0.274175,-0.108975,0.087486,-0.269533,-0.313427,0.114818,-0.059404,-0.033612,-0.660119,0.350769,-0.141949,0.189858,0.114688,-0.190671,0.039625,0.502591,0.073283,0.451233,-0.129863,0.036966,-0.317797,0.316076,0.417552,-0.204401,-0.162977,0.100279,-0.206647,-0.425420,0.147007,-0.393844,-0.519438,-0.052253,0.074813,-0.075997,0.023736,0.156591,-0.461101,-0.079385,-0.106925,-0.332073,0.272499,-0.488570,0.096834,-0.469344,-0.104553,-0.467706,-0.218593,0.099892,0.363237,0.006432,0.841050,-0.538768,0.318762,0.393515,0.503027,-0.603871,0.708116,0.168673,0.121737,-0.247250,-0.181683,0.141834,-0.206468,-0.113296,0.238669,0.185128,0.062186,-0.106405,-0.130401,0.270477', '1308609', '3445516', '35048413', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303031', '教室别恋', '剧情', '37岁的女教师维奥娜（马莉卡•劳伦丝 Marika Lagercrantz 饰）美艳动人，当丝袜推销员的丈夫却整天出差，就算回到家也只是听音乐、喝闷酒，让她心里非常寂寞难耐。班上15岁的青春少年史迪（约翰•威德伯格 Johan Widerberg 饰）懵懂无知，有着青春期特有的冲动。师生间两眼对视的瞬间，自然而然产生了相互依赖的畸形恋情。当他们完全沉醉在肉欲之欢里时，史迪对同龄的女生已经毫不感兴趣，拒绝了同班同学的暗恋。维奥娜的丈夫其实早已知道了妻子秘密，但他并没有揭穿妻子的秘密，而是继续饮酒、听音乐。此情此景，让史迪开始对自己的肉欲和这段畸形恋进行反思。©豆瓣', '约翰·维德伯格', '波·维德伯格', 7.2, 31173, 'tt0113720', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2569615088.jpg', 0.8, 4.5, 40.9, 40.7, 13.1, '0.384724,-0.113526,-0.561286,0.390477,-0.125170,-0.185788,0.903044,0.064506,-0.399177,-0.394723,-0.315993,0.683164,-0.363880,0.758184,0.264936,0.149290,-0.366770,-0.816368,-0.007915,-0.084192,0.094836,-0.433959,0.230170,-0.032152,-0.130942,-0.339429,0.582299,-0.133155,-0.224847,0.612793,0.330173,0.150845,0.118993,0.562732,-0.067186,-0.092721,0.114378,0.082270,-0.004734,-0.230490,0.233301,-0.068734,-0.018874,0.178939,-0.065303,0.320573,0.656004,-0.451504,-0.151877,-0.068034,0.462555,-0.077148,-0.056191,0.220545,0.077866,-0.161666,0.376836,-0.072611,-0.090624,0.033639,0.127050,-0.033228,-0.456398,0.254239,-0.093171,-0.036486,-0.130262,0.413777,0.095100,-0.031190,0.363608,0.093564,-0.023050,-0.005262,0.251072,0.539939,-0.252178,0.105550,-0.196427,0.109758,0.432134,0.309357,-0.207506,0.635941,-0.545916,-0.443605,0.007906,-0.150993,-0.613042,-0.133514,-0.161914,0.374636,-0.153051,0.274420,-0.388998,-0.038367,-0.088238,0.137157,0.128761,-0.655783,-0.265469,-0.402000,-0.427789,-0.477033,-0.315506,-0.013559,0.254058,-0.207393,0.694171,-0.969904,0.031290,0.425751,0.264261,-0.594450,0.700774,0.270469,-0.050200,-0.215492,-0.275121,0.651655,-0.189840,-0.024924,0.114811,0.586126,-0.079866,-0.031947,-0.244484,0.470647', '4817024', '3059036', '1389971', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303034', '绝代妖姬', '剧情', '这部电影是由意大利、比利时、法国合拍的，曾获得金球奖最佳外语片，凯撒奖最佳服装设计、最佳音响以及奥斯卡最佳外语片提名。古典音乐作曲家卡多（恩里克·洛维索 Enrico Lo Verso 饰）为了保全弟弟法瑞内利（斯特法诺·迪奥尼斯 Stefano Dionisi 饰）的声音不会因为成长而消失，不惜在他孩童时实施宫刑，从而让法瑞内利成为了伟大的歌唱家。兄弟两个人的命运就此相连，约定从此共有一切——音乐，荣誉，女人。法瑞内利的醉人的歌声及纯真的魅力迷倒了不少美女，卡多与弟弟分享一具肉体，并在感情和事业上处处控制着单纯的法瑞内利。终于有一天，了解真相的法瑞内利悲痛不已，无法原谅他的兄长对他的所作所为，从此两人决裂。在日食来临的时候，卡多割腕未遂，苏醒的他终于得到法瑞内利的原谅，于是，他在弟弟的女人爱丽丝肚子里留了个孩子作为对以前行为的补偿后悄然离去。©豆瓣', '斯特法诺·迪奥尼斯', '热拉尔·科尔比奥', 8, 9693, 'tt0109771', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p976252959.jpg', 0.4, 1.6, 22.7, 49.5, 25.8, '-0.081267,0.076314,-0.698361,0.719580,-0.295960,-0.366950,0.679837,0.152498,-0.476867,0.000742,0.173568,1.076192,-0.124958,0.172309,0.189083,-0.008343,-0.312338,-0.884131,-0.104483,-0.239595,-0.136100,-0.536269,-0.167662,-0.073557,-0.255136,-0.529872,0.855866,0.055197,-0.126118,0.211224,0.465391,-0.117430,0.013583,0.228676,-0.076333,0.083292,0.156014,-0.058629,-0.467859,0.360497,0.158202,-0.154653,-0.127395,0.185810,-0.143458,0.121344,0.626061,-0.487251,0.003816,-0.065561,0.488417,-0.355837,0.143982,0.121662,-0.231519,-0.116136,0.500500,0.321424,-0.284903,-0.096354,0.007462,-0.139193,-0.883554,0.012967,0.108968,0.032539,-0.507860,0.488059,-0.192168,0.119545,0.229686,-0.117056,0.233803,0.269640,0.221155,0.393405,-0.322955,0.076554,-0.246353,0.148081,0.648419,-0.096327,-0.359521,0.379690,-0.234530,-0.489089,-0.115308,-0.325804,-0.539862,0.095270,0.407962,0.199374,0.067497,0.340260,-0.372694,-0.112363,-0.247816,-0.092625,0.169000,-0.415014,0.108742,-0.413791,-0.246695,-0.252282,-0.102770,-0.070192,0.206363,-0.432813,0.901582,-0.847752,0.324396,0.524795,0.293365,-0.383746,0.600269,0.187663,0.143961,-0.235273,-0.120453,0.526756,-0.137042,-0.056453,0.100828,0.064509,0.084681,-0.087779,-0.425836,0.592274', '1870681', '27602116', '4301278', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303036', '暴雨将至', '剧情', '在马其顿，战争中的波斯尼亚，东正教的一位年轻修士以沉默保护一位年轻女孩，这位阿尔巴尼亚女孩涉嫌杀害一位东正教徒。但其实只是误会。修士以自己的善良决定与女孩私奔。在伦敦，一位摄影记者（凯特琳·卡特利吉 Katrin Cartlidge 饰）在餐馆与她的丈夫谈论感情变淡的问题，二人争吵激烈之时，一名种族主义者冲入餐馆开枪扫射。爱，在生死之间突然变得清晰。一位离开好友的摄影记者（拉德·舍博德兹加 Rade Serbedzija 饰）从伦敦出发，回到16年没来的老家马其顿。这里有他的老朋友，他的东正教朋友们，还有与阿尔巴尼亚人的种族矛盾。摄影记者尝试通过和解的方式化解纷争，但是，这一切远没有他想象的那么简单。“圆圈不是一个圆。”三段相互交错的故事，不同文化、宗教、民族的误会造成的悲剧。©豆瓣', '格莱戈尔·科林', '米尔科·曼彻夫斯基', 8.6, 27033, 'tt0110882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p470344042.jpg', 0.3, 1.1, 10.5, 42.2, 45.9, '0.510321,-0.258515,-0.590270,0.548369,-0.127267,-0.188050,1.051505,0.050615,-0.257905,-0.430267,0.198974,0.875527,-0.152971,0.014988,0.289277,-0.168075,-0.153319,-0.695490,0.204087,0.002169,-0.151701,-0.708959,-0.134233,-0.321456,-0.192565,-0.368461,0.651514,0.156872,-0.339799,0.423463,0.130426,0.264279,-0.360327,0.398553,-0.193601,-0.240162,0.250968,0.204881,-0.505452,0.060749,-0.266170,0.015578,-0.183909,0.136357,-0.247319,0.479313,0.462158,-0.293654,-0.072760,0.156898,0.186035,-0.077507,-0.062351,0.192511,0.393554,-0.039317,0.271364,0.010577,0.065960,-0.242449,-0.243816,-0.155481,-0.368233,0.126732,0.146949,0.186180,-0.371104,0.624496,0.012752,-0.233714,0.038498,-0.228703,0.106041,0.610621,0.265288,0.394026,-0.127136,0.056294,-0.454339,-0.140570,0.964428,0.131199,-0.529077,0.319500,-0.286292,-0.425168,-0.233604,-0.176288,-0.577692,-0.020679,0.213900,-0.259989,-0.042038,0.384483,-0.678598,-0.152670,-0.158897,0.039137,0.187098,-0.270962,-0.099546,-0.425032,-0.275137,-0.395898,-0.432934,-0.033531,-0.029123,-0.107064,0.982398,-0.934314,0.209113,0.456094,0.444256,-0.689850,0.813291,0.228073,0.149821,-0.317559,-0.282620,0.454846,0.114827,-0.136119,0.000294,0.308184,-0.179555,0.139356,-0.243169,0.082280', '25721544', '2002744', '1292219', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303037', '喜宴', '剧情', '伟同（赵文瑄）是事业有成的男同志，与男友赛门（Mitchell Lichtenstein）在美国过着幸福的同居日子，烦恼来自要用各种招数应对远在台北的父（郎雄）母（归亚蕾）的一次次逼婚。伟同被逼以“乖乖仔”形象修书一封声称会在美国结婚，没料父母想亲眼见证。无奈，他只得拉上来自上海的不得志的女艺术家葳葳（金素梅）“假婚”，想逃过一劫。父母对葳葳相当满意，却对伟同的草率态度不满，为让父母满意尽快返回台北，伟同犹如“拼命三郎”使出了浑身解数。但人算不如天算，不断的波折使得父母的返台日期一次次推迟，令他和赛门的感情亮起“红灯”，而葳葳又意外怀上了他的孩子。似乎，伟同在强大的父母（传统）面前，只能选择去做一个 “表面正常”的男人。©豆瓣', '赵文瑄', '李安', 9, 329100, 'tt0107156', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2249048907.jpg', 0.1, 0.3, 5.9, 38.9, 54.8, '-0.115514,0.063936,-0.559993,0.551055,-0.090344,-0.190305,0.390166,0.060096,-0.543514,-0.216880,0.202897,0.687262,-0.032238,0.230550,0.076939,0.038760,-0.157342,-0.516692,0.165687,-0.028691,0.024075,-0.506382,-0.157497,-0.261546,-0.148263,-0.249975,0.385440,-0.007831,0.013816,0.449484,0.489683,0.144142,-0.140791,0.473398,-0.329343,0.038353,-0.327284,0.160580,-0.480059,0.042914,0.333255,-0.330524,-0.266739,0.321505,0.137824,0.488953,0.639199,0.033729,-0.463252,0.070116,0.611416,-0.264627,-0.264622,0.385153,0.204618,0.096441,0.103186,0.073128,-0.095245,-0.110855,0.081437,-0.016562,-0.636889,0.016594,0.198815,-0.204862,-0.703923,0.515854,-0.228707,-0.036720,0.136571,-0.653962,0.157974,0.327364,0.067116,0.633118,-0.343707,0.320591,-0.135161,0.270711,0.797912,0.137586,-0.209883,0.266220,-0.359994,-0.275744,0.059898,-0.468057,-0.593665,0.089585,0.234253,-0.003916,-0.314185,0.243051,-0.322640,-0.204390,-0.228307,0.147613,-0.099586,-0.566429,0.075692,-0.249020,0.015556,-0.348787,-0.375764,0.080111,-0.094954,-0.340592,0.682753,-0.649636,0.111892,0.637973,0.484435,-0.588946,0.645596,0.420695,-0.023566,-0.096728,-0.039162,0.158237,-0.151496,0.111081,0.186508,0.176405,0.096649,-0.097881,-0.252551,0.224083', '1877596', '2080130', '35048413', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303066', '莫斯科不相信眼泪', '剧情', '十七岁的美丽少女卡捷琳娜（薇拉·阿莲托娃 Vera Alentova 饰）假扮成教授的女儿，在一场宴会上邂逅了名为拉齐克夫（尤里·瓦西里耶夫 Yuri Vasilyev 饰）的摄影师，两人很快就双双坠入了情网之中。然而，当卡捷琳娜的真实身份曝光之后，拉齐克夫残忍的抛弃了她，完全不顾她此时腹中已经怀上的骨肉。 坚强的卡捷琳娜并没有因此而一蹶不振，她决定将孩子生下来，独自抚养长大。一晃眼十六年过去，卡捷琳娜凭借着智慧和努力成为了工厂厂长。某日，一位名叫果沙（阿勒克塞·巴塔洛夫 Aleksey Batalov 饰）让卡捷琳娜再度体会到了心动的感觉，谁知道，她的身份再一次成为了这段感情中的绊脚石。©豆瓣', '薇拉·阿莲托娃', '弗拉基米尔·缅绍夫', 8.6, 19792, 'tt0079579', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2542279117.jpg', 0.3, 0.8, 11.6, 45.5, 41.8, '0.250104,0.305226,-0.679978,0.315413,-0.453744,-0.444656,0.605017,0.048451,-0.445259,-0.117229,0.127167,0.800543,-0.293717,0.353453,0.425737,0.346230,-0.237887,-0.906254,0.045301,-0.301389,-0.260291,-0.557004,-0.192441,0.198671,-0.042968,-0.383103,0.604799,-0.127452,-0.018373,0.527988,0.387562,0.253251,0.157270,0.318903,-0.056646,0.292203,-0.070708,0.005374,-0.244646,0.312004,-0.007313,-0.071127,-0.116031,0.127646,-0.121585,0.236914,0.646888,-0.304954,0.050766,-0.336343,0.546902,-0.098860,0.024493,0.282705,0.258646,-0.193138,0.129234,0.180644,-0.502075,-0.071278,0.271402,-0.040010,-0.632920,0.153619,0.138028,-0.077206,-0.736953,0.222430,-0.059402,-0.263003,0.178790,-0.305906,0.164236,0.229251,0.243635,0.529646,-0.371145,-0.085961,-0.372282,0.059912,0.734988,-0.029310,-0.372047,0.528241,0.104138,-0.290372,0.079303,-0.458626,-0.505878,0.090397,0.286090,0.438502,-0.353720,0.340077,-0.159072,-0.293248,-0.573621,0.012456,0.038863,-0.497737,0.001186,0.003956,-0.531638,-0.235801,-0.244066,-0.141807,-0.154149,-0.320281,0.649546,-0.624524,0.442955,0.327225,0.230107,-0.386635,0.527838,0.180315,0.352029,-0.126996,0.127555,0.540092,-0.123954,0.141066,0.166638,0.327320,-0.294574,0.002398,-0.388732,0.504188', '1303034', '25747028', '30345227', '1850797');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303067', '影武者', '剧情', '日本战国时代三雄之首的武田信玄（仲代达矢饰），号称“甲斐之虎”。他的信条是“疾如风，徐如林，侵略如火，不动如山”。当武田信玄包围德川军的野田城，即将直取京都完成霸业时，他被敌人的狙击冷枪打中，重伤濒死。临死前，他留下遗言要部下隐瞒自己死讯三年。先前弟弟武田信廉（山崎努饰）找到的替身（仲代达矢饰），原为窃贼的他面貌和信玄酷似，即日本人所说的“影子武士”，担当起了重任。就这样，在武田信廉一旁的支持辅助下，影子武士从贼性未改到被武田家的大义之举所感动，尽心尽力履行职责，他令武田家人及敌人坚信他就是信玄本人。然而，三年将至，意外之事发生，影子武士被揭露，他被赶走，而武田家的气数也将尽……©豆瓣', '仲代达矢', '黑泽明', 9.1, 65161, 'tt0080979', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p997945263.jpg', 0.2, 0.5, 5.9, 33.2, 60.2, '-0.114618,0.082874,-0.586106,0.512435,-0.179623,0.087340,0.375753,0.063401,-0.344213,-0.503310,0.452638,0.560444,0.112890,0.013885,0.275330,-0.049998,0.332693,-0.871923,-0.311594,-0.026108,0.066897,-0.322275,-0.111531,-0.210023,-0.357550,-0.376068,0.854681,0.387113,-0.154897,0.155979,0.205656,0.511548,-0.120695,0.340469,0.111663,0.214703,-0.317189,-0.321075,-0.034791,0.185994,-0.275071,-0.586137,-0.060365,0.622985,-0.311363,0.378334,0.586221,-0.336340,-0.170898,-0.426409,-0.057102,-0.435645,0.031169,0.445791,0.545607,-0.162547,-0.020714,0.362409,0.089103,-0.312308,0.089485,0.039288,-0.578348,-0.250697,-0.036032,0.153719,-0.690108,0.461378,-0.470315,0.202703,0.211729,-0.340094,0.118358,0.227243,0.187068,0.013096,-0.322551,0.097681,-0.514475,0.351638,0.669355,-0.176720,-0.153956,-0.110763,0.109134,-0.261464,-0.116258,-0.460822,-0.092756,-0.092303,0.371817,0.091092,0.058467,0.009785,-0.143098,-0.299199,-0.285140,0.209159,-0.040130,-0.221989,0.051705,-0.205775,0.193024,-0.344622,-0.340753,0.465768,0.189753,-0.201110,0.633602,-0.701848,0.006070,0.429310,0.361059,-0.266159,0.245370,-0.030863,-0.104676,-0.064541,0.110309,0.182729,0.587676,0.179929,0.365305,0.066655,-0.259107,-0.088563,-0.402164,0.311644', '4202326', '30345227', '1826173', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303071', '朦胧的欲望', '剧情', '法国绅士马德奥（费尔南多•雷依 Fernando Rey 饰）在西班牙乘车回国，在车厢里他遇到了一对母女、一个侏儒以及一个弟弟的朋友。火车发动前，一个女人（莫利纳•安赫拉 Molina Angela 饰）拎着行李匆匆赶来，马德奥向她泼了一桶冷水，这让众人颇为不解。回到车厢后，马德奥跟其他人讲述自己的遭遇：原来这女人是马德奥哥哥家的西班牙女仆孔奇塔（卡洛尔•布盖 Carole Bouquet 饰）。她的美貌深深吸引了马德奥。为了示爱，他资助孔齐塔母女摆脱经济困难，然后提出让她做自己的爱人。虽然，孔奇塔对他半推半就，但是始终没有答应他的性要求。这令他非常恼火，特别是当他发现这个自称处女的女人居然另有情人时，更是怒不可遏……本片中，西班牙导演布努埃尔用两名女演员扮演同一角色，颇具象征意义。©豆瓣', '费尔南多·雷伊', '路易斯·布努埃尔', 8.2, 9644, 'tt0075824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1561050122.jpg', 0.5, 1.5, 16.7, 50, 31.3, '0.326010,-0.025343,-0.672311,0.800912,-0.204350,-0.253952,0.801138,0.092320,-0.332092,-0.226505,0.291796,0.887637,-0.156733,-0.051216,0.395085,0.020424,-0.440371,-0.620750,-0.035655,-0.088520,-0.385820,-0.125702,-0.114945,-0.327607,-0.304334,-0.007910,0.218563,-0.209272,0.006902,0.489881,0.607010,0.315947,0.043005,0.453327,-0.197858,0.363577,0.140549,-0.038924,0.004838,0.250685,0.128018,-0.087358,-0.119311,0.245728,0.012428,0.339099,0.497756,-0.222355,0.009831,-0.276951,0.134044,-0.275852,0.134844,0.119963,0.140926,-0.022215,0.017922,-0.143328,-0.171258,-0.054552,0.254905,0.048399,-0.253328,0.302927,-0.039525,-0.084407,-0.675475,0.295863,-0.164348,0.210178,0.114963,-0.260025,0.079283,0.127261,0.249705,0.237146,0.017726,0.104677,-0.636021,0.011277,0.446795,0.065966,0.003912,0.200512,-0.423079,-0.397932,0.277097,-0.096584,-0.521166,-0.019386,0.426884,-0.106711,0.016987,-0.112430,-0.482232,-0.214114,-0.137205,0.017425,-0.017753,-0.429979,-0.039093,-0.445766,0.052037,-0.626139,-0.136176,0.031598,-0.077561,-0.027832,0.669763,-0.453078,-0.112326,0.286478,0.360401,-0.390203,0.582350,0.025523,0.220817,-0.229082,-0.065692,0.274163,0.121537,-0.011574,0.145983,0.576625,-0.164499,0.132712,-0.192509,0.441217', '30162520', '26809592', '3111650', '1769507');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303073', '望乡', '剧情', '基于各种原因，自幕府末期至昭和初期，日本大批穷苦人家的女孩被贩卖到南洋当妓女，世称“南洋姐”。她们的命运坎坷，受尽人世间的屈辱。有些人客死他乡，有些即使回到故乡，却仍要承受世俗鄙夷的目光。女性史学家三谷圭子（栗原小卷 饰）为了调查和解开这段历史，走访了九州天草的崎津町 ，不过她的采访并不顺利，曾经历那个年代的老人们对此皆闭口不谈，讳莫如深。偶然间，她在路边冷饮店邂逅曾当过南洋姐的阿崎婆（田中绢代 饰），经过一段时间的试探和交往，原本紧锁心门的老婆婆终于向圭子敞开心扉，一同回首那段不堪回首的悲伤往事……改编自山崎朋子的小说《山打根8号娼馆 底层女性史序章（サンダカン八番娼館- 底辺女性史序章）》，影片荣获1973年亚太电影节最佳影片奖、1975年柏林国际电影节最佳女演员奖等多个奖项。©豆瓣', '栗原小卷', '熊井启', 8.7, 10428, 'tt0073654', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151476445.jpg', 0.2, 0.4, 8.6, 43.5, 47.3, '-0.006799,-0.084380,-0.464356,0.450128,0.354886,-0.278816,0.410057,-0.125144,-0.519301,-0.370149,0.056052,0.636183,-0.216210,0.462605,0.387196,-0.144186,-0.307119,-0.509762,-0.081156,-0.498275,-0.098561,-0.116084,-0.297351,-0.087399,-0.464525,-0.196276,0.745678,0.299883,-0.165557,0.430872,0.359540,0.218595,-0.206667,0.200654,-0.132360,0.123809,0.276349,0.169910,-0.410036,-0.132087,-0.133054,-0.487716,-0.363206,0.036317,0.140940,0.051715,0.706524,-0.167081,0.034195,-0.013073,0.474015,-0.104642,-0.188711,0.061610,0.458381,-0.061732,0.032459,0.416246,-0.120430,-0.021575,-0.053312,0.028109,-0.360607,-0.067465,0.224895,0.076533,-0.389178,0.355868,-0.030991,0.188316,-0.082823,-0.109514,0.032525,0.217403,0.321398,0.249169,-0.080885,0.131400,-0.122085,0.658868,0.544718,0.169539,-0.256104,0.234544,-0.141065,-0.561831,-0.162313,-0.219399,-0.455643,0.195246,0.209879,-0.088734,-0.160178,0.418018,-0.333638,-0.035887,0.030284,-0.342612,0.282954,0.047410,-0.041948,-0.784886,-0.227240,-0.547802,-0.102392,-0.050188,0.342023,-0.085264,0.618904,-0.561367,0.157353,0.435852,0.147747,-0.322217,0.750356,0.276268,-0.064546,-0.224807,-0.162528,0.492574,-0.123294,0.334597,-0.131866,0.209474,-0.079177,-0.106974,-0.181615,0.206807', '1322847', '3811356', '1297368', '1302050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303074', '土耳其狂欢', '剧情', '本片围绕一位年轻的雕刻家艾里克（鲁特格尔·哈尔 Rutger Hauer饰）与美艳女郎奥尔加（莫妮卡·梵·德·冯 Monique van de Ven饰）展开，讲述两人之间一段刻骨铭心的孽缘情债。一起车祸让天性崇尚自由欲望的艾里克，邂逅美艳女郎奥尔加。从此他终日沉迷于暴力虐待式的床第之欢。当奥尔加远嫁美国后，艾里克重陷孤独，他只能以更加疯狂的性欲来发泄心中的痛苦。然而当两人再次重遇时，那段刻骨铭心的爱欲却再也无法重现，唯化作一段孽缘成追忆。这部由荷兰著名电影导演、剧作家、制片人保罗·范霍文执导，改编自畅销作家Jan Wolkers同名小说《土耳其狂欢》的情色电影，不但荣获1974年第46届奥斯卡金像奖最佳外语片提名，更获得“本世纪最佳荷兰电影”称号。本片营造出一种颓废唯美的绝望氛围，创下当年荷兰票房纪录。《土耳其狂欢》以热情大胆的爱情故事和赤裸野性的性暴力场面，成为荷兰电影史上是一部举足轻重的影片。', '莫妮卡·梵·德·冯', '保罗·范霍文', 7.4, 6340, 'tt0070842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1598876949.jpg', 1.5, 5.8, 32.6, 41.8, 18.2, '-0.106353,0.097562,-0.625356,0.689693,0.601771,-0.412885,0.724067,-0.096114,-0.314395,-0.051427,0.072682,0.714075,-0.371892,0.182803,0.463742,-0.071418,-0.347930,-0.722311,-0.234037,0.055132,0.298985,-0.098393,-0.381049,0.061522,-0.178038,-0.371549,0.847013,0.013801,-0.411251,0.577649,0.691734,0.488282,-0.042496,0.013073,0.008179,-0.023719,0.163025,-0.008371,-0.733520,0.262463,-0.031235,-0.363503,-0.198595,0.034525,-0.331384,-0.159958,0.655352,-0.244125,0.071599,-0.146400,0.830971,0.053551,-0.241802,0.102406,-0.164400,0.052790,0.452449,0.188011,-0.097847,0.083505,-0.038630,-0.226325,-0.697105,0.179111,0.150768,0.096197,-0.074616,0.292202,-0.099699,0.114839,0.228425,0.024812,-0.163000,-0.140729,0.490881,0.382272,0.022843,0.238323,-0.058661,0.588983,0.628456,0.102455,-0.565586,0.392011,-0.210077,-0.306755,0.009800,-0.443504,-0.490874,0.118886,0.321820,-0.045690,0.244016,0.363034,-0.686726,0.000379,-0.279303,-0.108143,0.103296,-0.003578,-0.001437,-0.779707,-0.384072,-0.234345,0.002196,-0.244077,0.197928,-0.244726,0.741929,-0.268402,0.439443,0.512518,-0.084871,-0.263222,0.566097,0.313722,-0.044638,-0.076616,-0.108279,0.826373,-0.357616,-0.200061,-0.143871,0.175704,-0.200507,0.131262,-0.286788,0.586922', '22265121', '26647163', '1780122', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303075', '这里的黎明静悄悄', '剧情', '本片根据鲍瓦西里耶夫于小说《这里的黎明静悄悄》改编。影片获1973年威尼斯国际电影节纪念奖、全苏电影节大奖，1975年又获列宁奖金。1942年之夏，瓦斯柯夫准尉带领一个排的四联装高射炮的炮手驻扎在一个靠近小车站的村子里。一天，班长丽达在不远的树林里发现了空降的德军。 瓦斯柯夫带 领一支小分队去搜查敌军，成员包括丽萨、迦尔卡、丽达、索妮娅、冉妮娅五个姑娘。队员们英勇牺牲了，受重伤的丽达不愿连累准尉把儿子托付给他后饮弹自尽。悲愤的瓦斯柯夫一举歼灭敌军营，光荣完成了任务获得援救。多年后，瓦斯柯夫带着丽达那个现在是军官的儿子来到当年他母亲牺牲的小树林，对所有的女兵们表示了深深的敬意。©豆瓣', '安德烈·马尔蒂诺夫', '斯坦尼斯拉夫·罗斯托茨基', 8.7, 11860, 'tt0068161', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2549456054.jpg', 0.2, 0.5, 9.9, 42.1, 47.4, '0.031319,-0.200587,-0.587944,0.426154,-0.099431,-0.322556,0.580490,-0.067229,-0.328772,0.043642,0.299963,0.649249,0.032179,0.107168,0.307437,-0.153623,-0.489374,-0.648573,-0.464786,-0.279543,-0.354616,-0.410425,-0.150124,-0.377328,-0.090425,-0.449520,0.514917,0.063489,0.172117,0.579717,0.248249,0.216729,-0.035026,0.112932,0.117562,0.373454,0.397744,-0.363315,-0.111546,0.360352,-0.251705,-0.020123,-0.354620,-0.393598,0.325371,0.310401,0.876605,-0.096809,0.052799,-0.164334,0.073248,-0.303032,0.184455,-0.032926,0.236491,0.028920,-0.007874,-0.026937,-0.038467,0.102442,-0.161366,-0.198394,-0.386871,-0.191275,-0.047168,-0.022585,-0.727774,0.525962,-0.306812,0.283727,0.293683,-0.161058,0.122527,0.301738,-0.088832,0.263465,-0.174715,0.042519,-0.547777,0.204796,0.380441,-0.437917,-0.056219,-0.104564,-0.171324,-0.372647,0.188370,-0.133119,-0.479663,0.132185,0.439614,-0.269941,0.311392,0.039290,-0.502949,-0.154027,-0.444696,-0.401121,-0.044059,-0.120285,-0.087257,-0.563538,0.103007,-0.013448,-0.205030,0.323621,0.053759,0.112178,0.808564,-0.369058,0.347167,0.457150,0.136534,-0.356353,0.506254,-0.007348,0.221187,0.086033,0.219250,0.250231,0.150964,0.538173,0.400007,0.531765,-0.367445,-0.483061,-0.308169,0.084844', '3811356', '21619567', '1307146', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303077', '电车狂', '剧情', '这是一个市井的故事，发生在任何发展中国家高楼大厦的背面；这是普罗大众真实的社会，在主流媒体有意无意的忽略中。影片片名出自电影主人公的口头禅（Dodes&#39;ka-den），一种模仿电车行走的声音。在人的世界里总要发出一点声音指证你的存在。在隆隆的电车声中，我们看见你的笑容，智障的小六，安详而自得。来来往往的电车一天又一天，时序的轮回中，普罗大众的每一天都是相同的，无奈而无助，在个体无法抗衡运命的那刻。小六的智障何尝不是一种幸福。对于市井中的芸芸众生，活着，有时只是一口气，他们的每一天都为着生计和饭钵忙碌，沉重而又无望。在这点上而言，智障的小六何尝不是一种幸福。存在的世界，思考的人因为思考招致的烦忧还少吗？小六的家母吟诵着经文，一旁的小六合十拜佛，祈祷佛佑其母，此一细节说明了小六的善良和乐观，活在无奈中的底层人民，学习些阿Q精神或者更能面对凄苦的生存状态吧！智障的人和清醒的人，到底哪一种人更幸福？！两个人的祈佛声越来越响，在无法改观境遇的存在中，留下一个希望总比没有希望好。智障的小六以为自己是个电车司机，每一天准时在贫民窟的垃圾场边风雨无阻开着子虚乌有的电车，这就是母子每天的生活，噙泪的母亲总是呆呆望着沉浸在另一个世界中的孩子，母亲的辛酸只有母亲一人独存。这样一个题材，黑泽明却用小六家那堵色彩艳丽画满电车的墙，表述着心念中对美好世界的希望，那些天真的蜡笔画是生命在灰暗中对亮色的一种期待，一种积极的人生态度。整个画满淫浸着导演的热忱和理想…车，是向前的载体；车，是动力的投射；一个未来的念想。', '头师佳孝', '黑泽明', 8, 6820, 'tt0065649', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528848849.jpg', 0.8, 2.6, 22.2, 45.4, 29, '0.223845,0.095980,-0.627627,0.849138,-0.169065,-0.082984,1.046017,0.116514,-0.412374,-0.078841,0.261625,0.671055,-0.004669,0.442049,0.103901,-0.166395,-0.215689,-0.546220,-0.299851,-0.168729,-0.345591,-0.471789,-0.408662,-0.283183,-0.214757,-0.185098,0.430347,0.389447,-0.096940,0.227557,0.219948,0.004292,-0.132942,0.249604,-0.429877,-0.169149,-0.236730,0.153348,-0.014404,-0.088275,0.056404,-0.038906,-0.215037,0.143031,-0.284124,0.188571,0.630260,-0.512286,-0.190114,0.093969,0.318048,-0.179646,-0.213856,0.033048,-0.066819,-0.037798,0.238857,0.076550,-0.130791,0.093749,0.066255,0.127165,-1.118642,-0.145974,-0.077826,0.460434,-0.506331,0.641986,0.169269,-0.310242,0.191943,-0.225622,0.260464,0.123048,0.235657,0.793976,-0.356920,0.033878,-0.497612,0.129162,0.530356,0.126005,-0.550341,0.587437,-0.485443,-0.124188,-0.095454,-0.155085,-0.786480,-0.257319,0.095023,0.011435,-0.233250,0.244067,-0.502057,0.381999,0.113207,-0.262356,-0.086144,-0.486097,-0.203842,-0.399504,0.085922,-0.549736,-0.164096,0.170245,0.354624,-0.308439,0.973181,-0.790774,0.303705,0.369622,0.114200,-0.250225,0.871817,0.242372,-0.098976,-0.206759,-0.220540,0.258145,-0.206923,0.195309,-0.079029,0.369170,-0.237038,0.185955,-0.563327,0.681451', '1303542', '26884422', '35360296', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303083', '怪谈', '剧情', '本片分为四个故事：《黑发》居住在京都的武士（三國連太郎 饰）厌倦了贫苦的生活，他抛弃妻子（新珠三千代 饰），与一个贵族小姐（渡辺美佐子 饰）结婚。然而现任妻子的冷酷让武士怀念起前妻的温柔贤淑，他再次与前妻相遇，结果却出人意料；《雪女》狂风暴雪的一日，青年（仲代達矢 饰）在山上邂逅美丽的雪女（岸恵子 饰）。雪女爱慕青年，饶他不死，但青年不得将这次相遇告知外人；《无耳芳一的故事》盲僧芳一（中村賀津雄 饰）的琵琶弹唱连鬼魂也分外欣赏，但经常与鬼接触势必折损阳寿，寺中的长老决定拯救芳一；《茶杯中》武士关内（中村翫右衛門 饰）喝茶时发现茶碗有一个陌生人的面孔，他打破茶碗，却引来了一个不速之客。本片根据小泉八云同名短篇小说改编，并荣获1965年戛纳电影节评委会特别奖、1966年每日电影最佳艺术指导和最佳摄影两项大奖。©豆瓣', '新珠三千代', '小林正树', 8.6, 20998, 'tt0058279', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p716970089.jpg', 0.4, 1.1, 12, 42.7, 43.8, '-0.049021,-0.028953,-0.197857,0.583246,0.074905,-0.201066,0.754069,0.128196,-0.348826,-0.363222,0.327617,0.759893,-0.074025,0.258971,0.576215,0.060951,-0.104934,-0.543897,-0.161348,-0.057832,-0.131462,-0.146549,0.001284,0.006794,-0.244870,-0.383163,0.680717,0.020719,-0.042771,0.747703,0.290119,-0.029882,-0.369974,0.171967,-0.048351,-0.034971,0.058701,0.085944,-0.120519,0.283886,-0.435361,-0.369988,-0.383329,-0.089781,-0.064635,0.357278,0.678343,-0.374313,-0.107075,-0.158591,0.334133,-0.031782,-0.202477,0.151769,0.281072,-0.097734,0.237005,0.215484,-0.192555,-0.166825,0.109652,-0.207244,-0.236691,0.237732,0.199891,0.215118,-0.353983,0.444722,-0.066801,0.071863,-0.096639,0.096356,0.085414,-0.012421,0.335530,0.154154,-0.216130,-0.010002,-0.222226,0.519983,0.496899,0.147688,-0.155589,0.131037,-0.094936,-0.486527,-0.190805,-0.271800,-0.365088,0.141131,0.109928,-0.107113,0.020311,0.143298,-0.546601,-0.124354,-0.129209,0.208192,0.147632,-0.243778,-0.220236,-0.497127,0.071292,-0.212571,-0.440621,0.141618,0.312060,-0.119172,0.889555,-0.617148,0.081663,0.384702,0.154861,-0.085191,0.769846,0.096920,-0.125483,-0.170424,-0.163539,0.279980,0.106692,-0.019321,0.028867,0.423793,-0.362613,-0.162730,-0.319759,0.073687', '3811356', '25922902', '10174444', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303086', '水中刀', '剧情', '一对中产夫妻驾车出游，丈夫（里昂•尼梅兹科 Leon Niemczyk 饰）总是夸夸其谈，但妻子（乔兰塔•乌梅卡 Jolanta Umecka 饰）只是随声附和。途中，他们遇到了一个临时搭便车的年轻人（兹古蒙特•马拉诺维兹奇 Zygmunt Malanowicz 饰）。夫妻经过商量，决定载他一程。三人来到了海边，丈夫准备用私家的帆船出海，为了向年轻人炫耀，所以邀他一同游玩。年轻人欣然应允，于是他们共同踏上了航程。航行中，年轻人渐渐对他们敞开了心扉，三个人还玩起了桌面上的竹签游戏。年轻人对夫妻坦言，自己不会游泳，因此他只是孤零零地在甲板上把玩手中的匕首。丈夫跟他开玩笑，无意中却把匕首丢入了大海。年轻人很生气，结果两人厮打在一起，双双落入水中，妻子大惊失措，三人关系也因此发生了逆转……©豆瓣', '莱昂·涅姆奇克', '罗曼·波兰斯基', 8.1, 11403, 'tt0056291', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p743347278.jpg', 0.3, 1.2, 17.1, 54.7, 26.7, '0.379089,-0.210668,-0.610604,0.316033,0.075048,-0.391943,0.636608,0.294777,-0.504470,0.104860,0.379434,0.649385,-0.113665,0.084020,0.450228,-0.044167,-0.534902,-0.816840,0.103352,-0.063898,-0.283293,-0.333398,0.128008,-0.155799,-0.269737,0.129823,0.172211,-0.175377,0.136108,0.621829,0.243860,-0.088853,-0.458922,0.493610,-0.285694,-0.022141,-0.058683,0.147906,-0.354139,0.114867,-0.040609,-0.098335,-0.105063,-0.020122,0.259491,0.236934,0.820917,-0.112488,0.039977,-0.109716,-0.308508,-0.018734,0.174306,0.063359,0.156781,0.211853,0.135377,-0.055324,-0.176199,-0.109641,0.103592,-0.089454,0.055434,0.364290,-0.248086,-0.074687,-0.608226,0.415474,0.062787,-0.074658,-0.047705,-0.258668,0.285312,0.289687,0.324536,-0.005803,-0.112630,-0.286821,-0.542856,0.090360,0.520351,0.088318,0.271240,0.324830,-0.116350,-0.155891,-0.170821,0.095422,-0.396240,-0.323972,0.357126,0.051900,-0.245712,0.129707,-0.618368,0.129444,-0.348252,0.165444,0.029224,-0.415903,0.172404,-0.361940,0.282748,-0.289259,-0.381025,0.163733,-0.054562,-0.077057,0.453712,-0.472369,0.053919,0.347924,0.408900,-0.193865,0.697004,-0.041305,0.189908,-0.454534,0.159121,0.164390,0.077767,-0.031262,0.239385,0.323226,-0.003961,0.174815,-0.256723,0.192050', '2976123', '3111650', '3155839', '1294252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303110', '战国英豪', '剧情', '元龟二年夏，早川的又七（藤原釜足 饰）、太平（千秋实 饰）被困秋月无法返家，只因秋月战败于山名，故山名重兵把守秋月早川的边境以防秋月的雪姬（上原美佐 饰）逃亡。二人在山中遇见了秋月武士真壁六郎太（三船敏郎 饰）和雪姬，并在不知对方真实身份的情况下与其共同运送木柴取道山名向早川进发，只因觊觎藏在木柴里的金条。真壁的计谋帮助四人顺利通过了秋月山名的边关，而雪姬不忍看秋月女子（樋口年子 饰）在山名受辱，命真壁赎之。五人运木柴赶路，忽被四名山名兵盘查。真壁当机立断杀死两人，又飞身上马追杀逃掉的两人。一路追至敌营，遇见了山名武士田所兵卫（藤田进 饰）。二人相见恨晚，较量许久，难分高下……©豆瓣', '三船敏郎', '黑泽明', 8.4, 13537, 'tt0051808', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2102884387.jpg', 0.4, 0.9, 11.9, 50.4, 36.4, '0.174590,-0.381796,-0.373593,0.105638,0.285537,-0.264675,0.432453,0.226356,-0.502728,-0.176169,0.590695,0.244878,0.103531,-0.327999,0.217680,-0.089752,-0.037548,-0.564854,0.142023,-0.322330,0.011359,-0.232851,-0.101164,0.096724,-0.076227,-0.176118,0.599095,-0.067823,-0.049821,0.632448,-0.072222,0.170214,-0.681410,0.397481,0.055294,0.311730,-0.004920,-0.058156,-0.054690,0.407169,-0.633167,-0.463446,-0.515150,-0.104651,0.081596,0.281684,0.535009,-0.441308,0.073404,-0.068821,-0.114513,-0.045646,-0.010866,0.385220,0.458195,-0.167873,-0.001698,0.041340,-0.306101,0.039960,-0.017499,0.205898,-0.064620,0.169454,0.081861,0.279186,-0.571787,0.504765,-0.023862,-0.210915,0.202041,-0.426056,-0.167951,0.289876,0.188136,0.104498,-0.271710,-0.163602,-0.368179,0.071585,0.336873,0.089940,0.417224,-0.052801,0.246650,-0.319104,-0.296404,0.127907,-0.357676,-0.225232,0.558056,0.200154,0.115463,-0.103719,-0.403910,0.058304,-0.311950,0.116518,0.048494,0.012186,-0.035552,-0.542975,0.160921,-0.514612,-0.538589,0.213967,0.421791,0.152113,0.332885,-0.440137,-0.067053,0.429971,0.162749,-0.068248,-0.016965,0.234826,-0.008757,0.277768,0.068978,0.080809,0.003347,0.645048,0.334243,0.395598,-0.304647,-0.065305,-0.456875,-0.214974', '1466273', '6402464', '26365262', '3082452');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303112', '麻辣宝贝', '剧情', '美丽的莫莉•甘（布兰妮•墨菲 饰）从摇滚明星父亲那里得到了巨额遗产，她总是能吸引人所有人的目光，她有专人设计的衣服，每天都有出席不完的派对，更有众多的追求者。在她22岁生日的那天晚上，朋友为她在最热闹的酒吧举行晚会。但这晚过后，她的遗产管理人骗走了她所有的财产，而曾经的公主必须要面对迫切的生活问题。在好友的帮助下，莫莉找到了一份保姆的工作，需要她看护的是音乐制作人罗玛•斯克琳（海瑟•洛克莱 饰）的女儿雷（达柯塔•芬尼 饰）。8岁的雷是个过分早熟的人，她不像平常的小孩子那样喜欢玩耍，而且有严重的洁僻，她早已学会了如何控制她要掌握的一切。莫莉从来不是一个尽责任的成年人，她对雷的行为也深感讨厌，但为了生活，她不得不学着照顾雷。她们一开始是那样水火不容，但随着彼此的了解，她们都发现了彼此身上散发的魅力……©豆瓣', '布莱特妮·墨菲', 'Boaz Yakin', 7.1, 8095, 'tt0263757', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p520766246.jpg', 0.9, 5.9, 44.4, 35.5, 13.2, '0.265545,-0.104886,-0.716875,0.542359,-0.449586,-0.073953,0.703465,0.148718,-0.502171,-0.355457,0.191399,0.786581,-0.057187,0.304510,0.251705,0.209388,-0.267127,-0.606520,-0.047120,0.091803,-0.309375,-0.466036,-0.034452,-0.473606,-0.138664,-0.266567,0.358009,0.166370,0.006911,0.125347,0.286484,0.126749,0.302023,0.673743,-0.285528,-0.211349,-0.115497,0.135723,0.117709,0.098928,0.087275,-0.178988,-0.197209,0.314846,0.251779,0.470129,0.457930,-0.128939,-0.207685,0.000368,0.510000,-0.242875,0.101333,0.045837,0.103348,-0.092555,0.282933,-0.016686,-0.228822,0.018132,0.011681,-0.183282,-0.808758,-0.204535,0.378106,0.078455,-0.713709,0.497455,-0.056513,0.116872,-0.044740,-0.298740,0.149185,0.318189,-0.083683,0.364177,-0.027171,-0.068323,-0.714880,0.270540,0.915065,0.148536,-0.204469,0.467815,-0.698947,-0.437877,-0.223726,-0.456120,-0.585523,0.127364,0.193942,0.070429,-0.092840,0.154413,-0.466800,-0.218323,0.235127,-0.303175,0.106934,-0.697026,-0.088352,-0.468929,-0.140114,-0.793551,-0.403999,-0.033968,0.062465,-0.454928,1.016387,-1.141865,0.113873,0.571520,0.296051,-0.626713,0.794713,0.117095,-0.006989,-0.163650,-0.144979,0.074774,0.029198,-0.010756,0.185969,0.396672,0.190301,-0.056015,-0.395253,0.551356', '1877596', '1309161', '7065238', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303137', '杀手壕', '喜剧', '美国的“杀手壕”格斗比赛即将拉开帷幕，两支芝加哥地区的黑帮都意欲在比赛中胜出，而其中一方的王牌选手——杀人王李呼声颇高。青年阿龙（成龙 饰）一家在芝加哥经营饭店，龙父遭黑帮勒索，阿龙出手赶跑恶人反被父亲抱怨，原来龙父一直不满阿龙跟自己弟弟学习武术，斥之不务正业，要求他向做了医生的长子学习。阿龙教训恶徒的经过被黑帮二代当家彭看见，彭有意令阿龙为他们出战杀手壕比赛，彭所在黑帮随即殴打阿龙好友，并绑架了阿龙没过门的嫂子要挟他与杀人王战斗。阿龙和叔叔救人失败，无奈只得刻苦训练，代表彭一伙参加比赛。阿龙在比赛中连战连捷，在他和杀人王的终极决赛之时，彭却出卖了他……©豆瓣', '成龙', '罗伯特·高洛斯', 6, 4086, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2344145356.jpg', 3.8, 20.9, 53.7, 14.8, 6.9, '-0.130241,-0.298931,-0.479302,0.407300,-0.087858,-0.362411,0.345266,-0.075596,-0.377328,-0.430216,0.197275,0.499221,-0.046276,0.164382,0.265824,-0.584643,0.224157,-0.738754,-0.267370,0.254912,-0.145568,-0.394481,0.002001,-0.290050,0.047662,0.130081,0.360966,0.145703,-0.606133,0.549284,0.435929,0.226919,-0.041514,0.400963,0.020890,-0.113128,0.279139,0.008403,-0.338672,0.063719,-0.019527,-0.341231,-0.238656,-0.025039,0.473670,0.441286,0.399669,-0.108217,0.181039,-0.358887,0.002659,-0.398166,-0.095826,0.192492,0.464991,-0.188325,0.309865,0.159145,0.364944,-0.191440,-0.229374,-0.277744,-0.597100,0.131172,-0.027487,-0.239751,-0.577070,0.558460,-0.188123,0.338893,0.061322,0.108990,0.318328,0.281212,0.211375,0.051153,0.004908,-0.068160,-0.447430,0.346584,0.655491,-0.038277,0.171130,-0.382319,0.321555,-0.556516,0.036474,-0.488664,-0.186803,0.141160,0.678811,-0.387202,-0.005127,-0.074343,-0.236243,-0.306219,0.188687,-0.049464,-0.134760,-0.351168,0.166717,-0.714144,0.204021,-0.197410,-0.209523,0.021921,-0.039010,-0.263515,0.509735,-1.162589,-0.069933,0.207512,0.426912,-0.748930,0.418345,0.210177,0.137159,-0.334065,-0.185475,0.019005,0.499513,0.136117,0.347786,0.294877,0.050538,-0.210020,0.005249,0.211442', '1301022', '2079632', '1316589', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303139', '玩命快递', '动作', '身手不凡的退役特种兵弗兰克·马丁（杰森·斯坦森 Jason Statham 饰）如今从事着用宝马车货运的营生，弗兰克不管自己服务的是否是银行抢劫犯，他更关注协议与原则。一单任务结束后，他免不了又要迎接警察的盘问与新工作。一个美国犯罪团伙托付弗兰克运送一件物品，弗兰克不经意中发现货物居然是一位名叫莱（舒淇 饰）的东方女子。弗兰克完成任务后对方却要灭口，只得带着莱回到住处。弗兰克这次惹上的麻烦显然不小，因为雇主随后带人将他的住所夷为平地，莱神秘的身份也浮出水面：原来她是某国际蛇头的独女。弗兰克被卷入了偷渡犯罪中的父女情仇，他需要作出决定来面对他和莱的关系与正义。©豆瓣', '杰森·斯坦森', '路易斯·莱特里尔', 7.4, 117331, 'tt0293662', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1439374533.jpg', 0.5, 3.7, 37.1, 44.5, 14.1, '0.262322,0.235343,-0.406650,0.616449,-0.197755,-0.364810,0.756720,0.020188,-0.340627,-0.360321,0.142841,0.927646,0.068285,0.068516,0.530803,0.250642,-0.420147,-0.838611,-0.155891,-0.347903,-0.387880,-0.619274,-0.166356,-0.333784,-0.049634,0.146283,0.235886,0.063791,-0.078908,0.450094,0.531831,0.357463,-0.175834,0.571592,0.069329,-0.205626,0.222835,0.001965,-0.103913,0.155728,0.207264,-0.254954,-0.005226,0.149960,0.237115,0.735450,0.459070,-0.108515,0.037835,-0.270468,0.070655,-0.315955,0.390082,0.068159,0.285850,0.046712,0.001423,0.353676,-0.313899,-0.034874,0.259994,-0.123155,-0.716598,-0.144423,-0.013157,0.130973,-0.585166,0.097395,-0.180635,0.258434,-0.125071,-0.225826,0.181109,0.360378,0.361497,0.054913,0.076087,0.093763,-0.562601,0.126531,0.577309,0.107562,0.077279,-0.052301,-0.178239,-0.408698,0.130304,-0.187228,-0.231248,-0.155003,0.558200,0.123858,0.142801,0.028939,-0.481227,-0.202988,-0.383243,-0.161639,-0.234504,-0.366410,0.000787,-0.669431,0.043003,-0.344929,-0.352334,0.201478,0.117938,-0.158738,0.413674,-0.688994,-0.230382,0.572471,0.294632,-0.582435,0.488580,0.130503,0.190342,-0.517801,-0.165303,-0.075521,0.153642,0.357395,0.138394,0.129646,0.039114,-0.345843,-0.135621,0.333326', '3119246', '1307442', '1299799', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303145', '薄荷糖', '剧情', '1999年春天，对生活绝望的中年男子金永浩（薛景求饰），落魄地参与了同学会，他神经质般哭叫，并在高架桥上面对迎面而来的火车嘶喊：我要回去！火车带着记忆倒走，三天前的金永浩已然崩溃，欲寻了断，但是被神秘人物叫去见一个人；再之后是1994年，他生活放荡，对妻子（金丽珍饰）冷若冰霜又出手大打；1987年身为警察的他，手段凶悍；1984年、1980年一直到1978年，直到第7个片段通过初恋情人（文素利饰）以及“薄荷糖”这一点题信物，影片才给出是什么碾压过主人公的生命，粉碎其美好的答案。©豆瓣', '薛景求', '李沧东', 8.6, 67378, 'tt0247613', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519637549.jpg', 0.4, 1.2, 11.5, 44.3, 42.6, '-0.077909,-0.072689,-0.310881,0.387881,0.055332,-0.327981,0.696539,-0.280058,-0.578752,-0.258111,-0.146274,0.285641,-0.378840,0.296073,0.390354,0.048262,-0.069237,-0.690983,0.051429,-0.143704,-0.407092,-0.055428,0.057251,-0.132272,0.074707,-0.115713,0.407904,0.066987,0.056848,0.604076,0.216842,0.061834,0.063626,0.545423,-0.198924,0.012332,-0.229976,0.217460,-0.257305,-0.009159,-0.021092,-0.670705,-0.239659,-0.150368,-0.258574,0.244225,0.371196,-0.014594,-0.094610,0.079967,0.170275,-0.171303,-0.345576,0.250691,0.216481,0.075047,-0.125500,0.411548,-0.120534,-0.060914,-0.186982,-0.222894,-0.538444,0.016658,-0.231391,0.037061,-0.417487,0.666763,-0.096430,0.271403,-0.154677,-0.403875,0.145371,-0.070939,0.147534,0.592363,-0.409734,0.074308,-0.452857,0.345571,0.484327,0.176372,-0.185496,0.413427,-0.071639,-0.477535,-0.134518,-0.424680,-0.359114,0.261799,0.050663,0.308701,-0.467504,0.163741,-0.639550,-0.038948,-0.280243,-0.263845,0.021585,-0.309420,-0.351951,-0.236524,-0.142859,-0.318637,-0.389327,0.220838,-0.072496,-0.113183,0.716767,-0.371082,0.367698,0.550049,0.364636,-0.335735,0.672540,0.117680,-0.284422,-0.233809,0.158057,0.453801,-0.094589,0.365881,0.132151,0.183736,-0.216898,-0.050902,-0.200132,0.456587', '3448362', '20388242', '1307146', '3212120');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303148', '永失我爱', '剧情', '苏凯（郭涛 饰）是一个专门替人从外地运送汽车的个体司机，偶然机会，他邂逅了空姐林格格（徐帆 饰），并对其一见钟情。然而苏凯表面贫嘴油滑的样子未给林留下好的印象，经过一番周折，林渐渐对苏产生好感，两人陷入热恋之中。苏凯用卖旧房得来的钱在公路旁买地建房，准备营建温馨的二人世界。但一场灾难不期而至，苏凯被诊断患有一种名为“肌无力性疾病”的绝症，命不久矣。为了不拖累爱人，他隐瞒了自己的病情，并将林赶了出去。林的好友杨艳（剧雪 饰）得知真相后，选择照顾苏凯的起居。经过一段时间的相处，杨艳也开始喜欢上这个生命将逝的男人……本片根据王朔的小说《永失我爱》和《空中小姐》改编，是著名导演冯小刚执导的首部电影作品。©豆瓣', '徐帆', '冯小刚', 6.9, 7218, 'tt0185028', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230370394.jpg', 1.9, 9, 44.9, 31.8, 12.4, '-0.008618,0.208741,-0.547226,0.693649,-0.079819,-0.379453,0.766605,0.013207,-0.499461,-0.436309,-0.134940,0.433189,-0.178145,0.294261,0.259485,-0.182757,-0.223358,-0.366645,-0.084574,0.004000,-0.274108,-0.253280,-0.025762,-0.401719,-0.239048,-0.223582,0.433122,0.236423,-0.367635,0.174747,0.378661,0.142672,0.082271,0.520811,-0.050828,0.240296,-0.250183,0.030245,-0.431655,0.303291,0.337487,-0.271713,-0.019204,0.049257,0.075492,0.343122,0.960806,0.067638,-0.444812,-0.083473,0.680287,-0.051691,0.285803,-0.260567,0.295185,0.290109,0.207762,-0.045452,-0.266401,0.065898,0.141051,-0.194753,-0.445672,-0.168294,0.065549,-0.060794,-0.506657,0.327551,-0.101382,-0.061007,-0.238716,-0.270791,0.442664,0.369559,0.519875,0.131346,-0.038721,0.047288,-0.388089,0.451173,0.631820,0.127068,0.121269,0.715752,-0.498367,-0.672484,-0.043506,0.068986,-0.449306,0.164244,0.514163,-0.009568,-0.141661,0.002313,-0.228162,-0.132452,-0.006246,-0.058253,-0.083998,-0.368993,0.243033,-0.520738,-0.134546,-0.296095,-0.265187,-0.067151,-0.021156,-0.294077,0.527607,-0.503794,0.119505,0.188948,0.164148,-0.496854,0.582814,0.018731,-0.020113,-0.362461,0.179592,0.421463,0.152233,0.132424,0.242285,0.302798,-0.031522,0.040020,-0.296258,0.483696', '35131347', '21619567', '3815920', '25717233');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303156', '悭钱家族', '喜剧', '典型都市女性Diana（郑裕玲 饰）有着骄人的事业成绩，也积极经营着自己的爱情。可是香港经济不景气，她与同公司的小职员韦大汉（曾志伟 饰）都在了裁员的名单上。韦大汉早年妻子因为好赌离家出走，丢下了女儿千华（杨千嬅 饰）及小儿子万华需要供养。他向儿女隐瞒自己已经被解雇的事实，可是Diana的出现让千华及弟弟都知道了爸爸的真实情况。原来Diana的出现是想跟他们参加一个家庭制的游戏，只有胜出游戏，电视台便会原价收购他们的负资产业。Diana是一个自私冷酷的人，在游戏的过程中，被大汉付出在儿女身上的感情而改变了她。千华也在游戏中与导演（陈奕迅 饰）产生了感情。游戏最终由他们胜出，可是千华亲生母亲的出现使局面彻底改变了……©豆瓣', '杨千嬅', '赵崇基', 6.3, 12594, 'tt0368770', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358205188.jpg', 2.1, 13.5, 56.2, 21.7, 6.5, '-0.100574,0.095937,-0.596682,0.520131,-0.205815,-0.240580,0.597133,0.339774,-0.503171,-0.070388,0.211398,0.787260,-0.045296,0.206117,0.166849,-0.083968,0.002734,-0.811228,-0.216252,-0.068919,-0.181850,-0.496034,-0.044813,-0.328297,-0.120447,-0.198057,0.742784,0.076569,-0.357780,0.177765,0.455747,0.091743,-0.015905,0.404074,0.021170,0.112101,0.007056,0.254412,-0.373335,0.081232,0.010818,-0.344355,-0.049446,0.213815,0.047153,0.493546,0.672111,-0.207389,-0.246955,-0.090886,0.411752,-0.338231,-0.257550,-0.124325,0.245955,0.036914,0.203244,0.323706,-0.097107,-0.185026,0.143902,-0.273894,-0.823417,-0.077606,0.176729,0.120949,-0.735567,0.681902,-0.201548,-0.169095,-0.136474,-0.249304,0.186958,0.266483,0.335279,0.242843,-0.248284,0.087937,-0.748671,0.540438,0.577895,0.019589,-0.178540,0.362408,-0.445855,-0.525120,-0.382881,-0.573845,-0.558296,-0.015465,0.234742,-0.050311,-0.264780,0.185947,-0.376296,0.003907,0.069629,-0.199477,0.099345,-0.593070,0.007256,-0.289991,-0.246888,-0.574814,-0.550066,0.118667,0.119952,-0.468678,0.865696,-0.957268,0.006049,0.546779,0.602467,-0.788454,0.891599,0.056009,0.266132,-0.172942,-0.209114,-0.020682,-0.070277,-0.035630,0.174706,0.028319,-0.019706,-0.142220,-0.283080,0.493519', '1877596', '4301278', '5985887', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303164', '第十三层', '恐怖', '小女孩无意中目击了她的父亲电死一个小男孩。当她长大后，被谋杀的男孩的鬼魂出现在她面前，他们决定一起出发去揭发她父亲的罪行。本片非经典电影《异次元骇客》（《十三度凶间》http://movie.douban.com/subject/1300282/），请移步收藏或评论。', 'Kylie Clare', '克里斯·罗哈', 8.3, 5990, 'tt0094591', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2209647250.jpg', 0.6, 1.2, 14.3, 48.2, 35.7, '0.380950,-0.082141,-0.580685,0.456387,-0.357055,-0.183159,1.061779,0.143636,-0.161244,0.078084,0.414300,0.890557,-0.219676,0.355795,-0.019178,0.181176,-0.508459,-0.503257,-0.238554,-0.400162,-0.472602,-0.331805,-0.019318,-0.071519,0.052285,0.154372,0.413691,-0.250748,-0.183655,0.188905,0.174461,0.031981,-0.295991,0.499491,-0.329103,0.218550,0.017507,-0.348227,-0.095018,0.493248,-0.172038,-0.491047,0.006314,0.241920,-0.140228,0.073392,0.909356,-0.413964,0.164742,-0.166198,0.458929,-0.174570,-0.009011,0.184110,0.162699,0.071190,0.491603,0.273406,0.194244,-0.091086,-0.104055,-0.152036,-0.338975,-0.061637,-0.062339,0.258996,-0.638547,0.070234,0.038846,0.387587,0.271146,-0.343485,0.078065,-0.099564,0.093048,0.153410,-0.366507,-0.129456,-0.472522,0.311183,0.214244,-0.008804,0.033825,-0.046073,0.005036,-0.461757,0.276823,-0.024276,-0.384851,0.105630,0.547379,-0.186819,-0.642042,0.407261,-0.190398,-0.581065,-0.316901,0.048466,-0.461543,-0.360967,-0.242161,-0.483504,0.024499,-0.074067,-0.236786,-0.166875,-0.032832,-0.287012,0.736539,-0.371718,0.623140,0.914770,0.510709,-0.613363,0.852826,0.245007,-0.035059,0.044425,0.083366,0.088936,0.302562,0.417268,0.206009,0.222149,0.039572,0.127019,-0.574730,0.346996', '21619567', '1467779', '1292217', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303170', '上海皇帝之雄霸天下', '剧情', '这部《雄霸天下》的故事紧接《岁月风云》展开。陆云生（吕良伟 饰）场面做大，他为人重情义不计开销导致入不敷出，遂计划涉足银行业，岂料上海各银行家集体抗拒。陆请动古羽（苗侨伟 饰）协助，终令银行家们低头服输……1937年，政府推行“新生活”运动，陆云生放弃鸦片生意带头戒毒，结果险些丧命，不久卢沟桥事变爆发，陆云生为支持抗战捐赠战机，却仍没有挽回上海沦陷的结局，是役更导致他众多门生身亡。陆云生为躲避日本人暂居香港，期间黄金荣（郑则仕 饰）留沪装傻；袁肃军（徐锦江 饰）投靠日军成为汉奸，陆云生只得派出阿山（汤镇业 饰）刺袁。抗战终于胜利，陆云生有望成为上海市长，让他颇感欣慰，但冷酷的现实是他已失去利用价值，一代枭雄在不属于他的时代渐入穷途……©豆瓣', '吕良伟', '潘文杰', 7.9, 14282, 'tt0108105', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528374815.jpg', 0.3, 1.7, 24.4, 50.1, 23.5, '-0.339511,0.163231,-0.454885,0.020209,0.120914,-0.064505,0.021143,0.149653,-0.343510,-0.174933,0.279662,0.409839,0.147279,-0.262540,0.019749,-0.284820,-0.087119,-0.475416,0.137350,0.180505,0.248832,-0.062242,-0.285210,-0.382957,-0.293897,-0.078344,0.910290,0.507321,-0.393878,0.293614,0.316314,0.346006,0.139329,0.455500,0.081707,0.036693,0.032950,-0.169666,-0.476999,0.062516,-0.248076,-0.499938,-0.272669,0.097388,-0.042759,0.316194,0.368285,0.022103,-0.047806,-0.393348,0.394551,-0.460314,-0.356298,-0.077917,0.264433,0.199701,0.059569,0.348446,-0.260537,-0.059373,0.070479,0.160615,-0.498269,-0.053813,0.362081,0.050047,-0.451517,0.320957,-0.265742,0.148386,-0.206248,-0.194543,0.011068,0.398464,0.460206,-0.010162,-0.083400,0.241467,-0.297574,0.506015,0.778923,-0.242867,-0.221886,-0.020584,-0.064655,-0.315849,0.194384,-0.595722,-0.116925,-0.106542,-0.052298,-0.112388,0.183344,0.317073,-0.273102,-0.188125,-0.184789,-0.234403,0.055898,-0.062468,0.036332,-0.458334,-0.165156,-0.084092,-0.128618,-0.081182,0.189891,-0.249198,0.653322,-0.419512,0.022510,0.115507,0.299982,-0.787659,0.574859,0.264912,0.114075,-0.252668,0.216446,0.413367,-0.104203,-0.062813,-0.041268,-0.356067,-0.169673,-0.315483,0.168744,0.241275', '1484760', '30391300', '26365022', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303173', '甲方乙方', '喜剧', '四个年轻人姚远(葛优饰)，周北雁(刘蓓饰)，钱康(冯小刚饰)，梁子(何冰饰)是一群自由职业者。他们突发奇想，开办了一个“好梦一日游”业务，承诺帮人们过上梦想成真的一天。人们离奇古怪的愿望接踵而至，似乎人人都想给自己现有的生活来一个180度大转弯。于是，富贵的想尝试贫穷，明星想体验平凡，小平民想做巴顿将军，守不住秘密的厨子想成为守口如瓶的铮铮铁汉……在搞笑荒诞的愿望中，四个年轻人忙碌着扮演各种场景角色，他们把真情融入到了这些故事当中。生活过得充满乐趣，有滋有味。©豆瓣', '葛优', '冯小刚', 8.4, 288049, 'tt0260987', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2436823425.jpg', 0.2, 0.8, 13.2, 49.7, 36.2, '0.193119,-0.171421,-0.389884,0.370934,-0.371271,-0.167015,0.766738,-0.042767,-0.619597,-0.172029,0.078117,0.449686,-0.167389,0.420616,0.211500,-0.052965,-0.376251,-0.475112,0.148808,-0.163286,0.146642,-0.276480,-0.202114,-0.516466,-0.319044,-0.026427,0.280561,0.037120,0.127435,-0.082865,0.368726,-0.040892,-0.055783,0.100689,-0.464994,-0.067186,0.011437,0.017284,-0.565979,0.131595,-0.414418,-0.062700,-0.437329,0.050275,0.029702,-0.065635,0.681805,-0.105067,-0.328506,0.075022,0.194031,-0.208705,-0.348205,0.209795,-0.102675,0.258276,0.287415,-0.162062,0.080728,-0.124231,-0.044181,-0.300019,-0.909479,-0.144860,0.211663,0.029047,-0.557331,0.233512,0.072539,-0.127958,-0.023725,-0.417588,0.126554,0.024381,0.555570,0.403422,0.042493,0.288862,-0.446257,0.645307,1.016999,0.066618,-0.288065,0.401055,-0.303193,-0.226909,-0.059822,-0.031406,-0.556628,0.012377,-0.039218,-0.320573,-0.299083,0.195468,-0.645362,0.376174,-0.124422,-0.199311,0.015052,-0.328768,-0.151503,-0.263850,-0.067054,-0.053456,-0.207024,-0.024039,0.113370,-0.367195,0.951463,-0.570407,0.043530,0.524633,0.030828,-0.541735,0.639500,0.228699,0.103963,-0.207194,0.007823,-0.012700,-0.206966,0.094060,0.021062,0.386622,-0.097995,-0.028724,-0.350914,0.439592', '26678784', '1308424', '24284209', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303176', '九星报喜', '喜剧', '彩虹村本是民风淳朴的和谐之村，谁知新上任的知县却见不得村民们互助友爱，认为人性本恶，于是搞得村子上下鸡犬不宁，人人自私自利。原来这新知县马麟大（黄百鸣 饰）本是朝廷四品高官，可是却生性贪婪，心术不正。其二弟马麟举（周文健 饰）更是一个好色之徒，唯有三弟马麟祥（张国荣 饰）为人善良，英俊潇洒。可就在马麟大来彩虹村上任的路上，三弟却不知所踪。原来此时的马麟祥偶遇了彩虹村相国夫人的侄女紫云（吴倩莲 饰），两人一见钟情。最终，彩虹村能否重拾往日的美好？马麟祥与紫云又能否有情人终成眷属呢？©豆瓣', '张国荣', '高志森', 6.9, 12086, 'tt0237501', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p940031193.jpg', 1.6, 8.4, 48, 28.4, 13.6, '-0.049194,0.078688,-0.319523,0.271046,-0.131799,-0.331525,0.148002,0.339885,-0.987602,-0.155998,0.191057,0.334597,-0.323423,0.071062,0.054230,0.277647,-0.050235,-0.106514,-0.111835,-0.230046,0.187456,-0.017951,-0.260634,0.129143,0.026962,0.061049,0.256305,0.336661,0.104164,0.168549,0.425795,0.256930,-0.338499,0.119039,-0.278095,-0.078829,-0.049295,0.437268,-0.294845,-0.283497,-0.474911,-0.138607,-0.455927,-0.209649,0.106335,0.303517,0.321922,-0.187680,-0.408282,-0.279074,0.240254,0.135836,0.009945,0.170852,0.374459,-0.302502,0.410779,0.114305,0.130556,-0.318239,0.003976,-0.217975,-0.333817,0.421330,0.294803,0.026781,-0.255433,0.187424,0.136695,-0.316183,-0.085339,-0.356395,0.058517,0.160522,0.151591,0.272524,-0.024666,0.015213,-0.382999,0.426819,0.718236,0.227380,-0.210555,0.178425,-0.225549,-0.247806,0.139466,-0.253717,-0.442121,0.117286,0.270076,-0.062698,0.095987,0.227290,-0.384586,0.109891,-0.314480,0.381526,0.224045,-0.195251,-0.245509,-0.307131,0.158853,-0.447790,-0.294920,-0.011990,0.251451,0.044028,0.792268,-0.583690,0.102764,0.024445,0.077592,-0.640700,0.376295,0.372548,-0.132157,-0.070044,-0.357481,-0.025131,0.213286,0.300533,-0.023884,-0.023476,-0.471033,-0.416341,-0.116195,0.159538', '10561880', '22555690', '25721544', '1424743');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303184', '异度空间', '剧情', '章昕（林嘉欣 饰）得知房东的妻儿死于泥石流后，总会看见她们的鬼魂，令男友无法忍受折磨离她而去，无奈之下，她求助于心理医师阿占（张国荣 饰）。阿占清楚知道章昕所见不过是因长久孤闭所生幻觉，开始竭尽全能帮助她，终使其慢慢脱离了种种恐怖的意想。两人在这一过程中渐渐生出感情。当置身阿占的生活空间时，章昕发现阿占有诸多怪异举动，调查过后，发现他患有严重的精神分裂，一到晚上某时即被幻象所困痛不欲生。为了让爱人回归正常，章昕决定帮助他赶走心里的魔障。©豆瓣', '张国荣', '罗志良', 7.5, 90027, 'tt0316023', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p582577555.jpg', 0.4, 2.9, 34.8, 44.4, 17.4, '0.030763,0.177846,-0.749276,0.128451,0.101370,0.003968,0.680590,-0.042178,-0.686831,-0.503769,0.030185,0.513134,-0.191107,0.354494,0.238948,-0.224848,-0.049407,-0.453177,-0.079119,-0.073086,-0.278244,-0.330900,-0.190500,-0.295171,-0.053966,-0.546013,0.311253,0.260545,-0.292269,0.406243,0.104117,0.507833,-0.153460,0.403783,0.099038,0.014235,-0.266762,-0.045612,-0.430093,0.023242,0.250531,-0.185165,0.025053,0.260130,-0.331543,0.292347,0.639734,-0.222600,-0.585917,-0.093145,0.615052,-0.239030,-0.193560,0.253721,0.030141,0.172882,0.120927,-0.132882,-0.444882,0.012634,0.193174,0.291681,-0.627314,-0.027610,0.157672,0.016650,-0.193311,-0.009309,0.067530,-0.026422,0.166870,-0.289203,0.204731,0.261696,0.406204,0.443724,-0.330925,-0.014303,-0.177591,0.008470,0.952323,-0.083547,-0.174575,0.340628,-0.164829,-0.180631,0.208128,-0.160662,-0.153855,0.074041,0.140148,0.530933,-0.358195,0.311813,-0.020862,-0.223938,-0.274197,-0.009754,-0.313824,-0.320551,-0.074430,0.016575,-0.371647,-0.038091,-0.179154,0.062619,-0.110196,-0.449417,0.271606,-0.793327,0.560996,0.580494,0.230134,-0.514897,0.401842,0.085513,0.003468,-0.209090,-0.032708,0.423437,-0.071792,0.131790,0.057347,0.040309,-0.114499,0.083402,-0.410995,0.133265', '1292064', '1305084', '4861627', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303203', '瘦身男女', '喜剧', 'Mini Mo（郑秀文饰）遭受失恋的打击后，饮食失去控制后体重升至260磅，窈窕身材不再。她与初恋情人黑川约定在十年后的日本相见，但旧貌不再的她深感自卑。偶然相识了跟她同样体型极胖的肥佬（刘德华饰），肥佬非常同情她，决定要帮她重塑魔鬼身材。肥佬以地狱式减肥方法锻炼Mini，为了让她减肥成功，得到更多的金钱让她上专业美容院减肥，肥佬不惜在街头被拳击换取酬劳。令Mini感动不已。Mini恢复原貌前去赴约，黑川向她提出求婚，可是她心中仍念念不忘为她默默付出的肥佬，盼望跟他重逢的一天。©豆瓣', '刘德华', '杜琪峰', 6.9, 155690, 'tt0286797', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2627630318.jpg', 0.6, 5.8, 50.9, 32.6, 10.1, '-0.288235,-0.021268,-0.641961,0.441022,-0.379207,-0.509474,0.705392,0.099302,-0.219254,-0.061695,0.147017,0.628778,-0.127774,0.216988,0.015994,-0.005840,-0.152983,-0.478507,0.202796,0.043153,0.017562,-0.165103,-0.037765,-0.101061,-0.429461,-0.332031,0.805448,-0.021411,-0.184959,0.471300,0.316119,-0.009397,0.554183,0.342474,-0.297675,-0.049066,-0.197129,0.127846,-0.155488,0.348207,0.485383,-0.391761,-0.064728,0.382228,-0.112643,0.226669,0.715197,0.075934,-0.463707,-0.272974,0.484917,-0.176885,0.080752,0.307003,-0.097736,0.142273,0.173940,-0.072113,-0.372357,0.043643,0.278678,-0.055623,-0.446078,0.010076,0.210448,-0.268302,-0.634177,0.418244,-0.349412,0.157422,0.228643,-0.394087,-0.192779,0.490020,0.378331,0.126306,-0.280761,0.002825,-0.434427,0.305108,0.814599,0.170594,-0.067191,0.344703,-0.240472,-0.518665,0.023589,-0.368529,-0.103249,0.028856,-0.062883,0.100641,-0.220098,0.135219,-0.515341,0.060775,-0.368890,-0.187232,-0.123931,-0.252613,0.092445,-0.462642,-0.209325,-0.390806,-0.264125,0.044762,0.331583,-0.648406,0.662543,-0.704668,0.204534,0.541312,0.713692,-0.651505,0.633867,0.000850,-0.120126,-0.268955,0.074566,0.414157,-0.195217,0.054792,0.100475,0.117404,-0.004369,0.089337,-0.561466,0.601666', '25721544', '35287908', '4728584', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303237', '驱魔人前传', '惊悚', '1949年的开罗。考古学家、战争时曾担任牧师的梅林（斯特兰•斯卡斯加德 Stellan Skarsgård 饰）接到一份工作，将前往肯尼亚参与发掘一座五世纪的教堂，委托人了解梅林在圣神像领域的专长，要求他取得一个苏美尔风格的恶魔像。梅林来到肯尼亚，与教廷派来的神父汇合，才得知教廷对这座五世纪的教堂一无所知，而这座教堂本身充满了疑点。在发掘队医生莎拉（伊沙贝拉•斯科鲁普科 Izabella Scorupco 饰）等人的介绍下，梅林发现整个发掘过程也充满诡异现象，考古学家贝松在发掘中发疯，而贝松画出的图画，分明与梅林看到的恶魔像如出一辙。同时，发掘营地的孩子出现了被“恶魔触碰”的状况，浑身抽搐却能操纵土狼。梅林等人似乎在恶魔的诅咒中越陷越深……©豆瓣', '斯特兰·斯卡斯加德', '雷尼·哈林', 6.5, 4552, 'tt0204313', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2214183115.jpg', 2.2, 11.3, 51.6, 27.1, 7.8, '0.275472,-0.043110,-0.740445,0.585264,-0.063231,-0.064057,0.919713,0.014883,-0.435432,-0.265638,0.444987,0.823990,-0.373612,0.015796,0.434593,-0.001846,-0.511862,-0.534993,-0.119848,-0.306225,-0.329510,-0.521077,-0.259711,-0.285093,0.130934,-0.795613,0.548736,0.266676,-0.268678,0.297582,-0.172500,0.383334,-0.338364,0.084653,-0.265510,-0.251068,0.312836,-0.033829,-0.210092,0.211960,-0.122352,0.002288,-0.247833,0.010384,-0.252209,0.198982,0.501679,-0.545695,0.132435,-0.151614,0.286728,-0.111881,-0.044371,0.024923,0.426492,-0.039595,-0.183815,0.237160,0.003960,-0.035326,-0.043071,-0.324538,-0.638513,0.052373,0.183719,0.361626,-0.623240,0.308611,0.308700,0.069261,0.177760,-0.250566,0.233862,0.164970,0.250043,0.596568,0.105943,0.095501,-0.631247,-0.080474,0.262209,-0.260389,-0.368397,0.039389,-0.141091,-0.733216,-0.234217,0.046790,-0.307237,0.121578,0.127399,-0.066223,-0.131224,0.262837,-0.779997,-0.076121,-0.387117,-0.489263,0.050413,-0.256587,-0.292710,-1.030340,-0.363904,-0.081156,-0.107704,0.153971,0.079745,-0.151089,0.433162,-0.807594,0.570553,0.427169,0.300235,-0.280252,0.789331,-0.052268,-0.143825,-0.400888,-0.251989,0.563576,0.258579,0.388158,0.090292,0.223084,-0.080810,-0.214088,-0.475409,0.504428', '1297659', '1309056', '1294917', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303246', '狙击电话亭', '惊悚', '公关人员斯图（柯林•法瑞尔 Colin Farrell 饰）在外面瞒着妻子有一个秘密情人，为了躲避妻子的电话单检查，这天他又偷偷溜到街上公用电话亭准备打电话约会情人。不料，在他进入电话亭的一刹那，电话铃响了。虽然不知是谁打的电话，出于习惯，斯图拿起了听筒。阴沉单调的男 声随即响起，警告斯图不要挂掉，否则将血溅街头！斯图当然没有理会这恶作剧般的警告，正要走出电话亭。这时，一声枪响，一名路人已经倒在地上。斯图吓得魂飞魄散，动也不敢动。警察闻讯而来，然而他们对斯图的解释怎么也不相信，斯图还成了枪击案的主要嫌疑人。一时间，全城轰动，斯图的妻子和情人都闻讯赶来了……©豆瓣', '科林·法瑞尔', '乔·舒马赫', 7.9, 187436, 'tt0183649', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1593362214.jpg', 0.5, 2, 22.3, 52.5, 22.6, '0.363704,-0.057985,-0.638494,0.328389,-0.006735,-0.416074,0.687290,0.047066,-0.031332,-0.092952,-0.107360,0.445973,-0.307994,-0.230388,0.249316,-0.067764,-0.365654,-0.507585,0.038117,-0.236947,-0.203316,-0.322655,-0.073532,-0.353367,-0.026455,-0.062887,-0.158677,-0.128461,-0.296987,0.408064,0.603725,0.069561,-0.189169,0.666212,-0.005643,0.187805,0.050168,-0.047897,0.025863,0.089521,0.210624,-0.424533,-0.235837,0.149732,0.230261,0.557203,-0.168454,-0.139311,-0.000265,0.147316,0.172777,-0.169982,0.025439,0.072404,0.493606,-0.129638,0.106935,0.057694,-0.280795,-0.057611,0.267796,0.350512,-0.310258,0.210021,-0.112357,0.276820,-0.394077,0.204052,-0.363773,0.098904,0.087751,-0.259973,0.512635,0.064778,-0.121706,0.287071,-0.158913,0.092290,-0.629358,-0.062467,0.407783,0.018983,0.097737,0.174490,0.151189,-0.367895,0.005475,0.057737,-0.511836,-0.240880,0.385953,-0.111236,-0.312226,-0.342218,0.143131,-0.087189,0.024337,-0.407328,-0.434944,-0.391630,-0.426948,-0.303117,0.076347,0.164012,-0.195621,0.447187,-0.127833,0.313633,0.316973,-0.629767,-0.013592,0.317569,0.209714,-0.029075,0.497321,0.032893,-0.057187,-0.064435,0.056502,0.036544,0.536547,0.647658,0.389951,0.251212,-0.187060,-0.375523,-0.276432,-0.125537', '25870679', '35073565', '1299292', '1416301');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303263', '诗人之血', '剧情', '《诗人之血》，是法国人考克多纵横于诗、小说、戏曲、绘画等创作世界后，作为走向电影世界的第一作，也是当时盛行的先锋派电影（avant-grade film）代表之作。披着假面具的考克多和写着 “诗全部都是纹章，所以，有必要读解诗人的血和眼泪。” 的字幕出现在观众面前，全篇洋溢 着主人公那异想天开、荒谬无规的世界，考克多的要素（个人的体验、私人的神话世界），通过把电影技巧融合在自己的 “死与再生” 的独特观念来展现出一个形象化的故事，影像的时间在影片的开始和结尾的瞬间得到了意义上的统一。电影对于考克多来说，就像是能够实现 “不死鸟术” 的魔法媒介，他的第一部作品已经形成了有别于其它表现方式的，衍生于边缘生命的理念，同时也体现出他对 “艺术家死而复生” 的命题作终生的反复追求。', '恩里克·里韦罗斯', '让·科克托', 8.3, 6222, 'tt0021331', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2205371266.jpg', 0.5, 1.7, 16.4, 47.4, 34, '0.190080,0.211128,-0.685940,0.967182,0.030614,0.018767,0.765055,-0.065971,-0.290887,-0.059521,0.022526,0.936047,-0.294056,0.224367,0.161480,-0.268887,-0.317125,-0.824888,-0.031694,-0.065295,-0.139491,-0.567867,-0.156010,-0.094063,-0.210222,-0.808419,0.824326,0.194629,-0.680284,-0.056363,0.236690,0.168215,-0.067577,0.192605,-0.074392,-0.172352,-0.184885,0.048223,-0.291804,0.176482,0.295757,0.087351,-0.178657,0.061882,-0.504904,-0.043180,0.914444,-0.507622,-0.188234,0.120052,0.926449,-0.157159,-0.045323,-0.281352,-0.232708,0.175045,0.303624,0.248531,0.252053,0.287686,-0.011922,-0.201051,-1.329284,-0.326920,0.220414,0.214850,-0.597453,0.709666,-0.148630,-0.462156,0.049896,-0.363418,0.286770,-0.059354,0.617844,0.603415,-0.192158,-0.053245,-0.494416,0.442056,0.263058,0.224472,-0.642215,0.786519,-0.464944,-0.578864,-0.647584,-0.395653,-0.100560,0.034658,0.198977,0.030853,-0.184417,0.094656,-0.853979,0.126125,0.064927,-0.407855,0.313947,-0.445586,-0.104733,-0.588316,-0.242998,-0.307569,-0.245171,-0.155801,0.331070,-0.516536,1.217866,-0.701130,0.167459,0.500892,0.067888,-0.383423,0.954458,0.146242,-0.172982,-0.165687,-0.094410,0.211512,-0.117574,0.449895,0.026237,0.444456,0.230033,-0.068550,-0.585983,1.018354', '27602116', '6844861', '22265121', '1303542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303269', '冲锋陷阵', '喜剧', '王启聪（陈奕迅 饰）和李耀庭（郭富城 饰）是互不认识的重案组探员。聪大大咧咧不修边幅，庭辣手灵敏自命不凡。两个性格各异的警界精英因为一宗案件聚到一起，女警冯宝宝（郑希怡 饰）暂时成为他们的上司。这宗案件由KEN（黄品源 饰）引发，他和女友打算盗窃一件价值连城的珠宝，还商量到手后就隐退江湖。结果却是螳螂捕蝉黄雀在后，他们盗来的宝物被另一伙人看上，他们追杀并捉走了KEN，女友则带着珠宝幸得逃走。她向警方提出要求：她愿意用这条项链，换回KEN的安全回来。警方开始追查绑架KEN的黑帮。其间聪、庭和冯宝宝却意见各异冲突不断。案件的侦破困难重重。©豆瓣', '陈奕迅', '林超贤', 6.3, 7210, 'tt0373906', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2359415310.jpg', 2, 11.8, 61.4, 19.9, 4.9, '0.340245,-0.082429,-0.411102,0.311195,-0.039900,-0.006894,0.420643,0.028288,-0.365733,-0.206402,0.047088,0.555992,-0.193432,0.061478,0.066531,-0.087798,-0.486235,-0.768372,0.023762,-0.012977,-0.290553,-0.406136,-0.014786,-0.151259,0.038065,0.108677,0.439493,0.015259,-0.196362,0.672374,0.759606,0.415748,-0.578348,0.442050,-0.153740,-0.182709,0.094760,0.132000,-0.363426,0.013445,-0.068937,-0.320572,-0.109291,0.165409,0.277295,0.473484,0.560300,-0.181409,-0.105170,-0.044236,0.123678,-0.332729,-0.086735,-0.065568,0.529337,0.114514,0.097319,0.470641,-0.149265,-0.121688,0.006214,0.079400,-0.659562,0.123559,0.250782,0.353254,-0.233626,0.135484,-0.121562,0.234595,-0.077935,-0.258491,0.166523,0.263506,0.135245,-0.037588,0.151102,-0.054123,-0.665237,0.282494,0.501139,-0.026714,0.246609,-0.050742,0.046889,-0.322183,-0.047646,-0.233271,-0.012248,0.002347,0.510752,-0.192471,0.111632,-0.148524,-0.449474,-0.145999,-0.204587,0.018046,-0.001012,-0.366317,0.195527,-0.650021,0.085559,-0.287575,-0.471901,0.258362,0.088691,-0.271547,0.290422,-0.339988,-0.254154,0.327463,0.355445,-0.819045,0.412228,-0.080569,0.067458,-0.447516,-0.438193,-0.220962,0.348939,0.131732,0.227772,0.271609,0.178089,-0.309319,-0.116159,-0.194689', '1302110', '4301278', '1297710', '1428602');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303278', '大亨游戏', '剧情', '某房地产公司的销售业务每况愈下，除了员工里基（阿尔•帕西诺 Al Pacino 饰）业绩尚可，其他员工只剩下在酒吧里买醉。公司主管约翰（凯文•史派西 Kevin Spacey 饰）看到士气低落，于是请来了推销大师布莱克（亚历克•鲍德温 Alec Baldwin 饰）前来布道。这家伙盛气凌人，出言尖酸刻薄，把各位批得一无是处。为了生存，老推销员莱文（杰克•莱蒙 Jack Lemmon 饰）因为女儿生病住院，所以希望可以得到照顾，保住饭碗；乔治（艾伦•阿金 Alan Arkin 饰）则因为年事已高，听天由命；戴夫（艾德•哈里斯 Ed Harris 饰）偷窃里基买卖的主意，一切通过金钱交易，神不知鬼不觉。然而，这个如意算盘并不是一帆风顺……©豆瓣', '阿尔·帕西诺', '詹姆斯·弗雷', 7.8, 8637, 'tt0104348', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1561443754.jpg', 0.6, 2.8, 24.9, 48.1, 23.6, '-0.045971,-0.008093,-0.240319,-0.065321,-0.326089,-0.558782,0.272735,0.353482,-0.427835,-0.589078,0.007529,0.499710,0.038578,0.038193,0.254078,-0.074855,-0.419402,-0.172444,0.119745,-0.058416,0.330449,-0.641440,-0.193562,-0.576015,-0.371473,-0.164255,0.089981,-0.048347,-0.025792,0.245511,0.306069,0.288162,0.138517,0.012203,0.400262,-0.055533,0.208982,-0.332292,-0.555161,0.143088,0.089622,0.457737,-0.020702,0.049459,0.706761,0.314263,0.034244,-0.172061,0.034316,-0.130606,0.195119,0.018216,0.377050,0.098034,-0.042234,0.009161,0.381800,0.004119,-0.289061,-0.124508,0.233556,-0.173667,-0.663953,0.150114,-0.128251,0.163686,-0.285639,0.186185,-0.325126,-0.003139,0.010133,-0.276029,-0.074638,0.190317,0.374303,0.084952,-0.036486,0.173190,-0.468754,0.197709,0.272219,-0.022839,0.186568,0.306704,0.019357,-0.153744,0.297482,-0.213562,-0.213828,0.029242,0.173603,-0.103504,0.333869,0.164251,-0.301469,-0.109957,-0.220292,-0.298413,-0.040684,-0.135108,0.110915,-0.568764,0.191133,0.157570,-0.226842,-0.184887,0.139651,-0.025842,0.297343,-0.642054,-0.024467,0.498066,0.421366,-0.337863,0.420478,-0.014952,0.411055,-0.132731,-0.570724,0.227787,0.277700,0.246729,0.137224,-0.122371,0.164679,-0.530362,-0.013186,0.164194', '1298635', '1401535', '3006781', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303333', '你妈妈也一样', '剧情', '出身标准富有阶级家庭的墨西哥青年胡里奥（Gael García Bernal 饰）与德诺（Diego Luna 饰）是一对儿死党，他们各自精力旺盛的女友结伴出国旅行，丢下两人为消磨漫长的无聊暑假犯愁。在德诺家举办的一次总统也亲临现场的宴会上，两人结识了德诺表哥的西班牙妻子露莎，并向她兜售通往传说中号称“天堂之门”的海滩之旅。一别多日，露莎惊闻丈夫出轨伤心欲绝，遂致电德诺要求参加海滩之旅。三人马上出发，于路露莎同两位大男孩无话不谈，并先后与德诺、胡里奥发生了关系，这让德诺与胡里奥的友情产生了裂痕，他们发现女友曾经同对方偷情后愤怒不已，但还是一同到达了天堂之门。这个夏天过后，一些关于青春的记忆永远留在了那片海滩上……本片获2002年洛杉矶电影节最佳外语片等几十项褒奖。©豆瓣', '盖尔·加西亚·贝纳尔', '阿方索·卡隆', 7.6, 18656, 'tt0245574', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199715297.jpg', 0.7, 3.8, 30.6, 46.7, 18.3, '0.038118,-0.029513,-0.783460,0.451853,0.180861,-0.328564,0.699291,0.081681,-0.476517,-0.069986,0.024967,0.973761,-0.417685,0.456165,0.549132,-0.072747,-0.345461,-0.620625,0.069985,-0.426609,-0.158409,-0.262831,-0.080383,0.160369,-0.107509,-0.242157,0.545837,-0.032941,0.020605,0.787451,0.288805,-0.088878,-0.274503,0.306416,-0.126630,-0.025249,0.156517,0.329050,-0.506036,0.016403,-0.260116,0.033536,-0.129420,-0.220185,0.215569,0.203178,0.581356,-0.110078,0.015923,-0.163135,0.182526,-0.108096,-0.098840,0.099566,0.232779,-0.065552,0.292874,0.283450,0.063726,-0.134100,0.029504,-0.238667,-0.403379,0.240939,-0.069414,0.022544,-0.430793,0.543069,0.037128,-0.240631,0.020506,-0.354843,0.172703,0.441703,0.149335,0.277483,-0.160282,-0.073296,-0.217763,0.201706,0.789693,0.120122,-0.219520,0.142051,0.083696,-0.288412,0.141364,-0.089000,-0.399787,0.070847,0.382825,-0.076407,-0.036010,0.188245,-0.703843,0.044626,-0.151751,-0.226235,0.172766,-0.218947,0.080857,-0.934786,0.024969,-0.446584,-0.399623,-0.005731,0.202879,-0.183331,0.521679,-0.711196,0.242470,0.436323,0.363491,-0.555798,0.688415,0.200225,0.319099,-0.150652,0.068854,0.328277,-0.120949,0.268357,-0.131158,0.339434,-0.179317,-0.079499,-0.487886,0.191827', '11541282', '26687241', '3147969', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303340', '木头美人', '喜剧', '在很久很久以前，英国王子威廉（威廉•罗格斯戴尔饰）与农家女杰西（克里斯蒂•斯旺森饰）坠入情网。但女王对这桩婚事极度反对，并命令巫师（特瑞•克斯饰）将一个魔法项链戴在杰西的脖子上。杰西被项链的魔法变成了一尊塑料模特。一段爱就这样被了结。一千年后的美国费城，杰西作为文物被放在了博物馆中，供人了解历史。但是商店工人杰森（威廉•罗格斯戴尔饰）阴差阳错的取下了魔法项链，杰西活了过来，并把杰森当作王子，再次陷入了热恋。不知所措的杰森与突然面对高科技的姑娘，开始了一段美妙的生活。但此时一个人暗中想毁掉这一切，他就是千年前的巫师。穿越千年，王子与灰姑娘的故事，能否画上圆满的句号？©豆瓣', '克里斯蒂·斯旺森', '斯图尔特·拉菲尔', 8.1, 8397, 'tt0102395', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2434685021.jpg', 0.5, 1.8, 22.7, 44.5, 30.5, '0.396721,0.192081,-0.219479,0.490588,-0.099674,-0.538439,0.772434,-0.157629,-0.745273,-0.311244,0.292203,0.843414,-0.469754,0.100641,0.391263,0.385352,-0.628489,-0.576521,0.271543,-0.313741,-0.241440,-0.395146,-0.327992,-0.161807,-0.166477,-0.498848,0.582878,-0.180268,0.142238,0.396796,0.226663,0.335279,0.140420,0.256861,-0.102195,0.152035,0.152624,-0.186295,-0.428302,0.208854,0.047338,-0.022056,0.227489,0.266702,-0.133295,0.004486,0.504566,-0.598214,0.204096,-0.046755,0.350846,-0.328625,-0.099924,0.337680,0.295500,0.105904,0.047518,0.142377,-0.143448,-0.164003,0.478710,-0.182704,-0.461079,0.108919,-0.226208,0.315187,-0.528200,0.359739,-0.353939,0.092724,0.034360,-0.382719,0.176412,0.106858,0.557660,0.278696,-0.228946,-0.104690,-0.536648,0.324016,0.255901,0.019783,-0.287050,0.369474,-0.243695,-0.631539,-0.275617,-0.054908,-0.264643,0.040543,0.651046,-0.094801,-0.104064,0.505258,-0.826403,-0.088257,-0.364773,-0.074008,0.153506,-0.501814,-0.236387,-0.523824,-0.170377,-0.255913,-0.268302,-0.147937,0.223762,-0.117976,0.451695,-0.662191,0.464510,0.317668,0.265764,0.112095,0.557142,0.040765,0.178036,-0.252978,-0.083793,0.255536,0.145811,0.441066,0.182740,0.433212,0.235588,0.086764,-0.311362,0.661894', '26586766', '1302133', '35161768', '1309210');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303357', '纸月亮', '剧情', '莫塞斯（瑞安·奥尼尔 Ryan O''Neal 饰）并不是一个本分的商人，即使干的是推销圣经的行当，也并不能阻止他使用一些上不了台面的手段。一场车祸夺取了莫塞斯的情人的性命，情人留下的一个小女儿埃迪（塔图姆·奥尼尔 Tatum O''Neal 饰）成了莫塞斯的负担。在向肇事者要得200美元后，莫塞斯决定将埃迪送往她的姨妈家去。在路上，埃迪展现了她天才般的口才和推销才能，让莫塞斯大赚了一笔，这对假父女之间也产生了真感情。然而，得意忘形的两人不慎掉入了一个圈套之中。一番波折之后，有惊无险的二人终于抵达了终点，但看着即将离自己而去的埃迪，一种名叫“不舍”的情感充满了莫塞斯的内心。©豆瓣', '瑞安·奥尼尔', '彼得·博格丹诺维奇', 8.6, 11417, 'tt0070510', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2559717631.jpg', 0.1, 0.3, 8.9, 50.3, 40.4, '0.323233,0.202213,-0.551841,0.894719,-0.383604,-0.685558,1.011064,0.126327,-0.248709,-0.029925,-0.069194,0.821870,-0.206619,0.236864,0.312541,-0.054140,-0.252858,-0.617898,-0.002560,-0.385413,-0.319909,-0.731657,-0.090853,-0.315304,-0.227512,-0.117186,0.540716,0.254445,-0.160491,0.304486,0.309516,0.250307,0.269332,0.634167,-0.095859,0.151511,0.037382,0.036443,-0.182131,0.254376,0.464723,-0.289378,-0.115829,0.404788,0.204339,0.508147,0.671246,-0.447782,0.055198,0.081854,0.288894,-0.302028,0.445018,0.209255,-0.015739,-0.136287,-0.076991,-0.023394,-0.566282,0.142506,0.360053,-0.102532,-0.802444,-0.221326,0.064196,-0.153348,-0.913744,0.506513,-0.031850,-0.129792,-0.261356,-0.230963,0.219230,0.241344,0.552940,0.283243,-0.305658,0.013508,-0.831044,-0.229132,0.672657,0.138399,-0.009596,0.434858,-0.032131,-0.713358,-0.338633,-0.182250,-0.468774,-0.202210,0.773492,-0.218432,-0.135886,0.302135,-0.547992,-0.303296,-0.495549,-0.315485,-0.204266,-0.576182,-0.027800,-0.203123,0.074051,-0.566379,-0.292227,0.143509,0.204930,-0.336441,0.589087,-0.640518,0.073635,0.819827,-0.080948,-0.461943,0.547306,0.148296,0.300474,-0.009043,0.056494,0.144893,0.050598,0.339599,0.576163,0.581901,0.041483,-0.028047,-0.018279,0.915852', '1299932', '1299327', '1292584', '1867335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303368', '千年之恋之源氏物语', '剧情', '故事发生在千年之前的越前国，紫氏部（吉永小百合 饰）嫁给比自己大很多的丈夫，生下女儿贤子。丈夫婚后不久就去世，紫氏一直过着孀居的生活并开始创作小说《源氏物语》。不久，藤原道长唤她来京都担任女儿彰子的老师，希望把彰子调教成皇后最合适的人选。紫氏入宫，一边继续创作《源氏物语》，一边给彰子讲其中的故事……这是关于光源氏一生的爱情故事。源氏（天海佑希 饰）俊美无比，从小失去母亲。他岁与左大臣的女儿葵上成婚，但并不爱她。源氏从小对父亲的宠妃藤壶心生爱慕，并发生了乱伦关系。藤壶怀孕生子，使两人都充满负罪感。源氏意外发现一个叫紫上（常盘贵子 饰）的女孩，长得很像藤壶。便把她养在家里，并娶为正式。源氏又相继与明石姬、栊月夜、六条等十数位贵族女性发生了暧昧关系。贵族的糜烂生活，人世的宿命，女人的悲剧，一并听紫氏娓娓道来。©豆瓣', '天海祐希', '堀川とんこう', 7.2, 17001, 'tt0316566', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p510023693.jpg', 0.8, 5.4, 40.7, 37.6, 15.6, '0.043902,-0.168666,-0.255595,0.533829,0.070127,-0.252682,0.573362,0.111739,-0.519480,-0.623222,-0.016844,0.827029,-0.360386,0.544085,0.116676,0.090398,-0.191371,-0.614187,0.081298,-0.027522,-0.004973,-0.346468,0.426626,-0.001334,-0.196010,-0.342606,0.698113,-0.207309,0.136173,0.211434,0.227845,0.233566,-0.113741,0.283877,-0.229899,0.361085,-0.316886,0.231464,-0.246479,0.096600,-0.146261,-0.124814,-0.055823,-0.020438,0.117558,0.110624,0.429472,-0.351738,-0.136287,-0.493081,0.459137,0.238849,-0.031614,0.239927,0.487053,0.034454,0.196630,0.554195,-0.147729,-0.190339,-0.034148,-0.167735,-0.329505,0.079758,0.237818,0.085680,-0.423478,0.367293,0.058912,-0.127877,0.345333,-0.244954,0.262185,0.245094,0.207558,0.416628,-0.453763,0.330130,-0.359581,0.287730,0.541639,0.082575,0.001734,0.517937,-0.118754,-0.505073,-0.073393,-0.110314,-0.440864,0.171439,-0.071438,0.222153,-0.166107,0.420273,-0.050692,-0.019971,-0.066681,0.057768,0.472524,-0.512051,0.027575,-0.123835,-0.175426,-0.502872,-0.407089,0.031416,0.197840,-0.357610,0.675627,-0.500396,0.308014,0.170925,0.251192,-0.742134,0.411095,0.324198,0.098998,-0.243736,-0.097140,0.528657,-0.107236,-0.124195,-0.015347,0.078549,-0.186821,-0.077532,-0.289427,0.205422', '3319776', '25721544', '1304091', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303376', '金枝玉叶', '喜剧', '著名音乐人顾家明（张国荣 饰）精心栽培了最受欢迎女歌星玫瑰（刘嘉玲 饰）。两人男才女貌，是十分相配的一对。他们的忠实fans林子颖（袁咏仪 饰）误打误撞成为了唱片公司的男新人，众人都没有发现其实林子颖是女扮男装的。子颖生活在偶像的圈子中才发现这对金童玉女正面临感情的考验。子颖的纯真同时吸引住了家明与玫瑰的眼球，分别对子颖产生了爱意。一段复杂的三角关系，引出不少笑料。©豆瓣', '袁咏仪', '陈可辛', 8.4, 91316, 'tt0109958', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167118411.jpg', 0.2, 0.7, 14.6, 47.7, 36.8, '0.379220,-0.227952,-0.550964,0.706777,0.095493,0.171791,0.880248,0.085192,-0.506019,-0.025033,0.480251,0.453109,-0.511579,0.122579,0.191507,-0.004123,-0.234680,-0.665776,-0.044856,-0.434713,-0.184064,-0.447806,-0.342400,0.150575,-0.163331,-0.178354,0.760989,0.176715,-0.127723,0.489917,0.477010,0.185677,-0.240043,0.152848,-0.183067,0.146694,0.375229,0.222595,-0.432250,-0.083241,-0.402912,-0.145799,-0.352218,0.449060,-0.195753,0.144456,0.785214,-0.278718,-0.115567,0.029353,0.555606,-0.263680,-0.015516,-0.182394,0.442865,-0.003342,0.460226,-0.132057,-0.244759,-0.085559,-0.057781,0.058974,-0.676749,0.310775,0.395792,0.259331,-0.400298,0.641048,0.125765,-0.423651,0.126918,-0.033223,0.276104,0.157187,0.407352,0.327305,-0.059927,0.364099,-0.361316,0.119390,0.624079,0.184665,-0.090987,0.714649,-0.469586,-0.387973,-0.198635,0.014307,-0.410146,-0.117952,0.499002,0.042129,0.072413,0.029307,-0.579197,0.019090,0.098730,0.018604,0.457710,-0.378107,-0.095754,-0.876028,-0.396992,-0.886687,-0.386732,0.006835,-0.083255,-0.318386,1.143829,-0.768063,-0.258132,0.209646,0.079429,-0.660860,0.798578,-0.060918,-0.261654,-0.328211,-0.476600,-0.018654,-0.101902,-0.430711,0.178114,0.657206,-0.055640,-0.175281,-0.284233,0.249321', '3811356', '25863940', '25922902', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303388', '安全至下', '喜剧', '在本片中，罗依德扮演一名百货公司的店员。该公司为了商业宣传，请了一位特技演员前来表演从楼下爬到大楼屋顶的绝技，不料那位特技演员途中与交通警员发生了纠纷而无法赶到。百货公司为了向围观的群众有所交代，只好由罗依德权充演员，在众目睽睽之下表演特技。', '哈罗德·劳埃德', '弗雷德·C·纽迈尔', 8.9, 10605, 'tt0014429', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1920360311.jpg', 0.2, 0.6, 7, 39.3, 52.9, '0.308200,-0.279699,-0.465037,0.433362,0.112911,-0.062138,0.367540,0.394087,-0.280047,-0.496788,0.806574,0.807815,-0.411220,0.082629,0.672366,-0.681473,-0.359042,-0.596401,-0.129168,-0.181582,-0.429640,-0.068157,0.059494,-0.419801,-0.422876,-0.193615,0.533175,0.079744,-0.462041,-0.000572,0.703803,0.298509,-0.679702,0.092458,0.038941,-0.237068,0.453383,-0.119803,-0.514973,0.490943,-0.040298,-0.734036,-0.528507,-0.228549,0.103110,-0.101123,0.672511,0.170674,-0.054608,0.166922,0.384864,-0.268548,0.579605,0.071831,0.647611,0.124972,0.167268,0.010859,-0.050988,0.333807,0.015982,-0.289112,-0.835696,0.219656,-0.084130,0.134189,-0.737003,0.248468,-0.131175,-0.212540,0.107519,-0.382531,0.162922,0.175172,0.108079,0.130294,-0.040002,0.135666,-0.391712,0.415882,0.450307,0.491401,0.099220,0.632085,-0.017291,-0.465904,-0.151423,-0.116269,-0.283850,-0.024704,0.518031,-0.081194,-0.129558,-0.112080,-0.313583,-0.389047,-0.116338,-0.585728,-0.176193,-0.261327,-0.135895,-1.355011,0.214992,-0.017878,0.539920,0.019256,0.177788,0.184363,0.692086,-0.989162,-0.491701,0.582543,0.101607,-0.472805,0.860474,-0.224281,0.298242,0.256457,-0.454166,-0.598997,0.165836,0.807048,0.056328,0.299396,-0.170901,-0.493799,-0.405256,-0.244097', '2369613', '24751811', '25723905', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303390', '敦煌', '剧情', '北宋年间，举人赵行德（佐藤浩市 饰）面对西夏的考题哑口无言，抱憾殿试。此后心灰意冷的行德决定远走塞外，前往令人充满遐想的西夏游历。旅行途中，行德所在商队遭到汉人组成的佣兵部队的袭击，他被迫编入部队，并渐渐得到队长朱王礼的赏识和器重。在与回鹘人的作战中，他救下并藏匿了回鹘 公主斯鲁比娅（中川安奈 饰）。二人由恨转爱，并相约逃跑前往西夏，无奈阴差阳错，行德只得留下爱人独自前行。谁知他一去两年，期间斯鲁比娅竟被西夏王子李元昊（渡濑恒彦 饰）霸占。饱受命运的左右与玩弄，行德注定在历史尘沙中留下一段千古传奇……本片日本历史小说名家井上靖的名著改编，并荣获1988年第12届日本电影金像奖最佳影片、最佳导演和最佳男主角奖（西田敏行）。©豆瓣', '西田敏行', '佐藤纯弥', 8.4, 8014, 'tt0095071', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2613586886.jpg', 0.4, 1.4, 15, 45.1, 38, '-0.047730,-0.062216,-0.435405,0.700662,0.584243,-0.182049,0.317858,-0.071041,-0.345176,-0.398899,0.295519,0.757253,-0.150433,-0.042920,0.366098,-0.214302,-0.343021,-0.708766,0.055076,-0.248783,0.098274,-0.313148,-0.002102,0.002739,-0.184111,-0.174135,1.046301,0.170102,-0.102292,0.779884,0.268630,0.135135,-0.348738,0.231904,-0.021977,0.339694,0.074672,-0.108055,-0.425014,0.243428,-0.131341,-0.252392,-0.271292,-0.124180,-0.020177,0.214401,0.607492,-0.481847,0.218468,-0.149995,0.282413,-0.372369,-0.230606,0.047210,0.319650,0.016578,0.132070,0.334807,0.028097,0.089735,-0.179128,0.069496,-0.232697,-0.001760,0.257867,-0.018706,-0.309593,0.387505,0.146763,0.035564,0.191310,-0.083074,0.017523,0.405216,0.414242,0.084989,-0.000939,-0.005588,-0.215023,0.475170,0.460215,-0.157817,-0.051837,-0.140363,0.062875,-0.498090,0.202859,-0.354972,-0.366961,0.171896,0.213773,-0.015659,0.234991,0.370623,-0.436139,0.066527,-0.332407,0.101676,0.269397,-0.268372,0.082899,-0.623831,0.154069,-0.116677,-0.130407,0.210153,0.312348,-0.124476,0.342558,-0.282853,0.136089,0.474183,0.317116,-0.464502,0.369120,0.165821,-0.004643,-0.087307,-0.060411,0.675259,0.083128,0.289345,-0.103351,0.034528,-0.301863,-0.200335,-0.460082,0.196444', '1780122', '3266509', '26365262', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303394', '青蛇', '剧情', '南宋是一个人妖难分的时期，法海和尚（赵文卓 饰）到处收服妖精，也扰乱了在西湖底修炼的白青二蛇。青（张曼玉 饰）曾获白（王祖贤 饰）相救，二者便以姐妹相称。姐妹俩受惑佯装成人生活在民间，白更嫁于老实书生许仙，青也同时看上了许仙，便常常以媚态勾引许仙，无奈许仙只深爱白一个。白开设了药店，以为可以自此过上安定的生活，可许仙却受不了青的百般挑逗，更发现了青白二蛇的真实身份，可他却不舍得离开家中的天姿国色。法海得知了青白二蛇的下落，更抓走了许仙。原来白为了爱情放弃修成正果，更怀有了身孕。为了救回丈夫，二蛇与法海展开了搏斗……©豆瓣', '张曼玉', '徐克', 8.6, 488286, 'tt0106559', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2570901292.jpg', 0.1, 0.8, 12, 42.7, 44.4, '0.149356,0.100131,-0.275065,0.477158,0.068269,-0.596974,0.528349,0.014848,-0.465966,-0.012829,-0.203439,0.550943,-0.255090,0.256933,-0.046169,0.133552,0.076133,-0.458172,-0.024014,-0.070113,-0.085814,-0.167755,-0.214752,-0.096744,-0.157266,-0.190741,0.570670,0.071505,-0.092471,0.290081,0.725766,0.014296,-0.367453,0.383138,-0.469721,0.173055,-0.558193,0.458042,-0.290019,-0.009101,-0.020872,-0.334403,0.012775,-0.094291,-0.109920,0.312596,0.350536,-0.194829,-0.328917,-0.392034,0.239695,-0.103821,-0.263592,0.210953,0.294473,-0.398872,0.542059,-0.030299,-0.332066,0.084400,0.025725,0.262042,-0.418369,0.315467,0.511643,0.115621,-0.409057,0.216642,0.109457,-0.010131,-0.270386,-0.252480,0.037318,0.399638,0.012034,-0.029084,-0.157542,-0.185104,-0.499129,0.413793,0.397778,0.211133,0.296037,0.553358,0.027970,-0.225966,0.181596,-0.162459,-0.241764,-0.239987,0.280048,0.149678,-0.121583,0.044865,-0.676450,-0.473589,-0.332485,0.345235,-0.129089,-0.370854,0.271537,-0.029772,-0.224172,-0.647752,-0.442981,0.139929,0.295541,-0.550229,0.440053,-0.915150,0.079796,-0.051043,0.278963,-0.728119,0.293045,0.337339,0.221142,-0.281217,-0.177590,0.536750,-0.171068,0.077349,0.114249,0.182876,-0.114161,-0.040516,-0.400223,0.461388', '26730542', '3033092', '1299556', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303407', '非洲和尚', '喜剧', '华侨阿森（陈山河 饰）请来林道士（林正英 饰）参加远在英国的拍卖会，二人将阿森家族祖先的僵尸买下，准备运回国内安葬，岂料飞机半路遭遇浓雾天气，他们失去了方向飞到了非洲，并在跳伞时和僵尸分散。僵尸被当地土著人历苏和族人们带回，而林道士和阿森却陷入了野兽的围困之中。历苏好心帮助了一位抓捕非洲少女的白人女性，她却不思报答，反而脱身而去，计划将土著人用作工具的钻石据为己有。林道士和阿森脱身后再度遇险，又是历苏出手相救，二人入住历苏族人的营地养伤，同时也找到了丢失的僵尸。此时，白人带领众多帮手返回抢夺钻石，林道士派出僵尸大战白人请来的黑巫师……本片旁白由周星驰和吴孟达担任，主角历苏凭借《上帝也疯狂》一举成名。©豆瓣', '历苏', '陈会毅', 7.1, 11889, 'tt0101864', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233067101.jpg', 1.4, 7.5, 43.1, 31.8, 16.4, '-0.047857,-0.084450,-0.457766,0.285677,0.039100,-0.305470,0.640088,-0.034583,-0.319936,-0.305944,0.085579,0.481752,0.039532,0.009481,0.251565,-0.252563,-0.378900,-0.382220,-0.191242,0.062091,-0.414270,-0.072867,-0.242461,-0.561940,-0.085833,-0.405312,0.589166,0.275630,-0.378779,0.451615,0.193148,0.251020,-0.440983,0.399060,-0.239054,0.076148,-0.048107,-0.081939,-0.358444,0.529705,-0.133721,-0.343775,-0.116852,-0.138241,0.163212,0.440980,0.729387,-0.173024,0.082227,-0.275213,-0.062722,-0.531851,0.055297,0.004974,0.546136,-0.145225,0.073801,-0.213612,-0.011648,0.001128,0.172807,-0.201599,-0.216277,0.329215,0.183480,-0.074127,-0.611660,0.192339,0.072060,0.325044,0.041579,-0.427820,0.430216,0.255215,0.101026,-0.077761,0.299016,-0.099538,-0.589735,0.425784,0.707751,-0.066286,0.257577,-0.287163,-0.022839,-0.795247,0.085185,-0.075811,-0.090845,-0.128990,0.635337,-0.004166,-0.061995,-0.033130,-0.560195,-0.359887,-0.354066,-0.022777,-0.101336,-0.301919,0.135579,-0.738742,0.100931,0.127851,0.161144,0.058684,0.186591,0.086521,0.705098,-0.495972,0.138589,0.287503,0.552068,-0.425381,0.418858,-0.524926,0.223498,-0.140958,-0.095675,0.055964,0.600438,0.496054,0.307383,-0.005944,-0.276767,-0.105925,-0.235347,0.021448', '2159244', '30299515', '1307897', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303408', '福尔摩斯二世', '喜剧', '影片的男主角基顿（巴斯特·基顿 Buster Keaton 饰）是一名乡村影院电影放映师，他喜欢阅读侦探类的书籍，经常幻想自己就是一名像福尔摩斯一样的大侦探。一天，他把价值一元的巧克力糖谎称四元送给女友凯莎琳（Kathryn McGuire 饰），不料被情敌趁机陷害，说基 顿偷了别人的手表拿去当才有钱买巧克力。凯莎琳相信了谗言，遂将基顿赶出门外，并取消了二人之间的婚约。基顿查访之后，发现情敌才是偷表典当的家伙，但却苦无证据洗清冤情。某日，基顿在放映电影时，发现银幕上的故事竟和他的遭遇同出一辙，而且人物也雷同，唯一不同的是电影中的故事发生在一个上流家庭而已。基顿边放映电影边沉溺在电影之中，于是走出放映室，从观众席走入银幕之中逮捕情敌罪犯。可是进入银幕后的基顿却四处碰壁，一筹莫展．随着场景的变化，银幕上的映象不断从幻想变成事实……©豆瓣', '巴斯特·基顿', '巴斯特·基顿', 9.5, 23173, 'tt0015324', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206737207.jpg', 0.2, 0.2, 2.8, 18.7, 78.1, '0.407440,0.116780,-0.511787,0.412149,0.306517,-0.256775,0.846206,0.158405,-0.352281,-0.175199,0.238157,0.775570,-0.534955,0.248290,0.078335,0.075673,-0.454974,-0.791277,0.056508,-0.382703,-0.035759,-0.396170,-0.485323,-0.043206,0.014850,-0.227833,0.558285,0.050300,-0.456675,0.169764,0.526743,-0.053251,-0.232561,0.374283,-0.015121,0.258919,0.091065,0.230330,-0.259496,0.268693,0.020268,-0.369496,-0.112602,-0.156404,-0.047395,0.283486,0.799533,-0.335902,-0.231251,0.116093,0.560464,-0.103988,-0.336187,0.144454,0.151158,0.245543,0.261816,-0.015370,-0.066471,0.076465,-0.016333,-0.129094,-0.592817,-0.078367,-0.001738,0.356554,-0.427718,0.175244,-0.118291,-0.102357,0.078609,-0.211079,0.360450,-0.202589,0.492507,0.415715,-0.136289,-0.053456,-0.621343,0.153482,0.247652,0.113750,0.015154,0.649145,-0.079455,-0.313593,-0.101306,-0.142114,-0.475097,0.167424,0.292297,-0.107650,-0.242581,0.071594,-0.530209,0.021859,-0.244601,-0.245451,0.050720,-0.187943,-0.190987,-0.677584,-0.074294,-0.132144,-0.091570,-0.082203,0.040682,-0.346873,0.625113,-0.423534,0.285704,0.597557,0.114158,-0.357205,0.797160,-0.004103,-0.090670,-0.021953,-0.020854,0.080905,0.325229,0.255172,0.069839,0.243627,-0.033815,-0.330841,-0.329497,0.590308', '30162520', '1292925'