INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303418', '你逃我也逃', '喜剧', '波兰华沙有一个剧团，其中有一名演员Bronski（Tom Dugan 饰）极其擅长模仿德国纳粹领袖希特勒。Maria Tura（卡洛·朗白 Carole Lombard 饰）和Joseph Tura（杰克·本尼 Jack Benny 饰）是剧团里的一对夫妻，剧团最近正在上演《哈姆雷特》。演出间隙，Maria收到了一束鲜花，来自一个年轻的飞行员Stanislav Sobinski（罗伯特·斯塔克 Robert Stack 饰），趁着Joseph在舞台上念著名台词“to be or not to be”的时候，她安排Sobinski进了后台，两人情愫暗生。然而不久后，纳粹侵略波兰，Sobinski只能前往作战。Sobinski所在队伍的领导是Siletsky教授，Sobinski想让Siletsky帮忙带封信给Maria，然而Siletsky却连著名女演员Maria都不认识，于是Sobinski开始对Siletsky产生了怀疑。Sobinski为了追踪Siletsky又回到华沙。而另一方面，Maria却被两个纳粹士兵带去见Siletsky，Siletsky对Maria也是心生爱慕，更希望Maria成为纳粹在波兰的间谍。Maria借故逃回家，却在家中意外的碰到了Sobinski和她的丈夫Josef，这段三角关系该如何收场，他们又要如何联手对抗纳粹？', '卡洛·朗白', '恩斯特·刘别谦', 9.2, 40927, 'tt0035446', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1339915772.jpg', 0.1, 0.3, 4.2, 27.9, 67.4, '0.313533,-0.160791,-0.779583,0.588291,-0.011823,-0.204670,0.661160,-0.049358,-0.621488,-0.255592,0.120698,0.794874,-0.198395,-0.102399,0.133276,-0.074617,-0.363344,-0.643406,0.062378,-0.263019,-0.183759,-0.503651,-0.279646,-0.152733,0.020212,-0.184954,0.593353,0.087261,-0.284943,0.533054,0.558077,0.384865,-0.076441,0.541912,-0.047880,-0.140693,0.232241,-0.127255,-0.261530,0.348307,0.212501,-0.172054,-0.329545,0.053300,-0.136426,0.352003,0.562936,-0.117387,0.138763,-0.066559,0.212553,-0.284142,-0.010460,0.218721,0.417990,0.059247,0.153970,0.044339,-0.085887,0.256759,-0.119315,-0.026160,-0.493504,0.249539,0.133458,0.186590,-0.776415,0.426149,-0.164792,-0.131579,0.371717,-0.241233,0.297781,0.454454,0.205640,0.507128,0.127264,-0.017154,-0.551116,-0.063139,0.739116,-0.061927,0.052757,0.220758,-0.129874,-0.322110,0.102891,-0.126341,-0.248508,0.020155,0.227260,-0.074786,0.062909,-0.117740,-0.626528,-0.009236,-0.270354,-0.162402,0.170818,-0.653605,0.181788,-0.757089,-0.064308,-0.360496,-0.258191,0.114543,0.156968,-0.047586,0.842425,-0.852347,0.186676,0.435797,0.342722,-0.612848,0.674767,0.436215,0.084180,-0.193811,-0.054594,0.061250,0.097473,0.170741,0.043401,0.253068,0.061818,-0.374834,-0.111487,0.000356', '25721544', '1301022', '35030151', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303436', '醉拳3', '喜剧', '袁世凯（何家驹 饰）为登基称帝笃信邪教，教主赠送玉扳指佑其成功，岂料袁世凯将扳指送给四王爷之三公主沈玉（李嘉欣 饰），并计划立她为皇后。教主令袁世凯收回扳指，与此同时，潜伏袁世凯身边的孙文革命军干部杨君（刘德华 饰）掳走沈玉以阻止袁登基。李督军（刘家辉 饰）自此奉袁世凯之名沿途追索杨、沈二人，杨君在路经过宝芝林时邂逅黄麒英（郑少秋 饰），遂将护送沈玉之重任托付于黄麒英和痴迷醉拳的黄飞鸿（季天笙 饰）父子二人。飞鸿护送沈玉的路上遭密探（任达华 饰）截杀，致使代步汽车撞入仁伯（刘家良 饰）的酒庄，醉拳高手仁伯帮二人解围，但又留下他们做工来弥补酒庄损失，由此卷入玉扳指争端战，李督军不久率军赶到，各路高手掀起连番激战……©豆瓣', '刘德华', '刘家良', 6.5, 17009, 'tt0109678', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2352139950.jpg', 1.8, 11.2, 54.5, 23.8, 8.7, '-0.338751,0.259116,-0.509977,0.644366,0.190075,-0.204599,0.363643,0.248711,-0.598246,-0.363313,0.488459,0.327288,-0.224045,-0.328705,0.349033,-0.289477,0.001318,-0.473795,0.067785,0.099252,0.103710,-0.211780,-0.106766,-0.282286,-0.447048,-0.115307,0.564475,0.211712,-0.112260,0.590867,0.388532,0.152882,-0.378546,0.425489,0.119093,0.171617,-0.213025,0.050695,-0.490787,0.029654,-0.236126,-0.546811,-0.099945,-0.043258,0.084116,0.186508,0.561640,-0.311421,0.303653,-0.372083,0.115448,-0.266637,0.074710,-0.131547,0.183616,0.406167,0.040411,0.202551,-0.213158,-0.075462,0.043897,-0.040679,-0.006584,0.182655,0.343179,-0.154776,-0.393371,0.035064,-0.437847,0.273512,-0.201265,-0.403653,0.224099,0.571762,0.141556,-0.158698,-0.026994,0.098098,-0.314815,0.392216,0.251875,-0.100947,0.429207,-0.397615,0.277175,-0.436790,0.266828,-0.016588,0.122663,-0.022006,0.636077,-0.247930,0.656077,0.090058,-0.261790,-0.605400,-0.388271,0.159173,0.403480,-0.002408,0.398249,-0.584180,0.240728,-0.229738,-0.254918,-0.017048,0.400936,-0.096821,0.201897,-0.245800,0.044319,-0.139912,-0.014490,-0.746880,0.240251,-0.165213,0.226547,-0.138828,-0.065026,0.135524,0.170631,0.203019,0.178912,0.104592,-0.209000,-0.216097,-0.202357,-0.203395', '3626416', '3291930', '1294693', '1307704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303444', '随风而逝', '剧情', '伊朗库尔德斯坦省的一个小村子里来了一群工程师。村民们对这群突然来到的外来人议论纷纷，好奇他们来此地的目的。虽然感到陌生，但是村民对客人还是表现出友好的欢迎。其中一个工程师，对村里的一切都饶有兴趣。他每天跟随着村里的小孩到处查看，注意到有个生病的老太太，于是不停地打听老太太的病情。因为需要用无线电话和总部联络，而村里的信号不好，所以工程师每次都要跑到山上的墓地去接听。在山上，他发现有个村民总是在独自挖着坑，觉得好奇的他经常上前与这个村民聊天。突然有一天，如风般顺畅的日子发生了变化。山上村民挖的坑塌陷了，活埋了村民，医生前去奋力抢救村民，顺道发现那个老太太也在病危中。面对生命的逝去，工程师惆怅万分。本片荣获第56届威尼斯电影节评审团特别大奖。©豆瓣', '纳格·阿萨迪', '阿巴斯·基亚罗斯塔米', 8.1, 14114, 'tt0209463', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2534949005.jpg', 0.4, 1.9, 17.9, 53.2, 26.6, '0.399422,-0.442820,-0.768256,0.284696,-0.113259,-0.127803,0.733583,-0.236840,-0.729417,-0.152730,0.206507,0.577352,-0.263236,0.480226,0.153303,-0.107444,-0.370682,-0.132666,-0.191855,-0.178831,-0.296185,-0.177898,-0.083403,-0.419419,-0.158937,-0.135415,0.047631,0.081798,0.035253,0.727799,0.087041,0.097450,-0.137796,0.638838,-0.230518,0.165202,0.058823,-0.113188,0.023185,0.028926,0.044447,-0.135797,-0.395398,-0.106541,0.314563,0.582068,0.475414,-0.055942,-0.406350,0.384727,0.335212,-0.230496,0.072224,0.196695,0.717660,0.050712,0.182583,-0.093397,-0.003897,0.078709,-0.263056,-0.000812,-0.337778,0.200990,0.165345,0.387118,-0.733428,0.362301,0.279845,-0.091204,-0.158131,-0.536831,0.521266,0.249256,-0.082193,0.547297,-0.196803,-0.144237,-0.365098,0.050559,0.650372,-0.184290,-0.033300,0.204139,-0.286764,-0.376221,0.298602,0.046809,-0.471635,-0.043784,0.175836,-0.169953,-0.378642,0.023207,-0.565651,0.280918,0.021029,-0.505258,-0.060878,-0.320539,-0.290558,-0.581223,0.206928,-0.157438,-0.098259,0.283531,-0.015289,0.069000,0.763875,-0.595692,0.186457,0.781531,0.425115,-0.489415,0.627647,-0.192252,-0.038083,-0.188057,-0.346798,-0.117022,0.194955,0.757368,0.116704,0.353301,-0.217519,-0.439572,-0.393271,-0.136300', '1394424', '2990737', '26469862', '1293019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303447', '火星任务', '剧情', '公元2020年，云集了无数顶尖科学家的世界空间站（World Space Station）正在进行一项载人飞船火星登陆计划。由卢克·格莱姆（Don Cheadle 饰）率领的4人小组成功抵达这颗无人星球，他们在此发现一些奇怪景象，随后小组成员也接连毙命。为了调查这起悲剧 的原因并寻找可能的生还者，空间站派出伍迪·布雷克（蒂姆·罗宾斯 Tim Robbins 饰）率领的救援小组前往火星。然而救援小组也遭遇诸多磨难，船体损坏、机器失灵、燃料泄漏、成员死亡等等，无一不在消磨着救援人员的斗志。抵达火星后，布雷克他们找到了卢克船长，继而发现亿外年前外星人留在火星上的遗迹和信息，这一切都与人类有着千丝万缕的关系……©豆瓣', '加里·西尼斯', '布莱恩·德·帕尔玛', 7.6, 29436, 'tt0183523', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p686618740.jpg', 0.5, 3, 29.8, 48.3, 18.4, '-0.052211,-0.019141,-0.974736,0.144916,0.316625,0.141488,0.421659,-0.199774,-0.561697,-0.260894,0.176308,0.499049,-0.109303,-0.094356,0.315171,-0.307056,-0.664193,-0.420116,-0.080881,-0.532965,-0.548492,-0.565228,-0.187134,-0.439123,0.415002,-0.616682,0.878388,0.383039,0.003708,0.417876,-0.208782,0.334671,-0.400886,0.536674,0.186250,-0.069196,0.270745,-0.177631,-0.294461,0.189273,-0.504413,-0.023466,0.000099,-0.215756,-0.070205,0.375461,0.786787,-0.284544,0.019495,-0.186237,-0.093311,-0.456308,0.289876,-0.264962,0.629962,-0.035878,-0.058384,0.296660,0.237607,0.037898,0.077990,0.036551,-0.815814,-0.215857,0.150488,0.368487,-0.297194,0.241577,-0.323009,0.190927,-0.214159,-0.319734,0.365623,0.691399,0.395163,0.016062,-0.218356,0.083012,-0.438813,-0.007946,0.617782,-0.311249,-0.240400,-0.009669,-0.010162,-0.457223,-0.349769,-0.138011,0.016401,0.073789,0.357641,0.346531,0.195831,0.336462,-0.771294,0.191025,-0.242574,-0.555450,-0.084641,-0.153856,-0.011080,-1.223066,0.138811,0.081151,-0.326875,0.279300,0.121106,0.078973,0.670106,-0.466698,0.214420,0.565063,0.270267,-0.505848,0.538068,-0.225666,0.088461,-0.584963,0.034778,0.245291,0.324826,0.464170,-0.222916,0.095309,-0.022578,-0.272616,-0.340947,-0.211880', '2369613', '1306809', '3871833', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303449', '鬼狗杀手', '剧情', '居住在新泽西的黑帮杀手“鬼狗”（Forest Whitaker弗雷斯特•惠特克 饰）身为非裔，却浸淫在日本武士道的精神世界里，“忠义”为其平生最高信条。他深居简出，不苟言笑，日常与老大靠飞鸽传书联系。鬼狗视老大路易（John Tormey 饰）如亲生父亲，接到命令后决不手软，手起刀落，血浆四溅。孤独的他也有可以交心的朋友，闲暇时与公园买冰淇淋说法语的非裔聊聊天，各说各话，却也有趣；或与爱看书的小女孩交流品读《罗生门》的心得。鬼狗活在自己的世界里，但周遭已发生巨大变化。终于有一天，他被路易抛弃，成为帮派倾轧的牺牲品……©豆瓣', '福里斯特·惠特克', '吉姆·贾木许', 7.6, 6379, 'tt0165798', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2206916681.jpg', 1.3, 4.3, 29, 45.4, 20, '0.163215,-0.054149,-0.667489,0.526145,-0.136579,-0.258912,0.710149,0.224571,-0.543564,-0.135883,0.053242,0.846429,0.007619,0.175252,0.368977,-0.140594,-0.138195,-0.909829,0.128382,-0.285016,-0.019947,-0.452668,-0.284724,-0.276030,-0.176840,-0.281363,0.329536,-0.087589,-0.224715,0.309226,0.214379,0.311595,-0.089244,0.500269,-0.341394,-0.334519,-0.055698,0.113634,-0.369452,-0.064789,-0.135140,0.114830,-0.061007,-0.035539,0.054839,0.234035,0.479871,-0.328603,-0.179148,-0.216538,0.156632,-0.004072,-0.055149,-0.028974,0.384735,0.083530,0.291939,0.405016,0.060349,0.083778,-0.034134,0.012060,-0.641120,-0.173265,0.034868,0.248518,-0.552574,0.580082,-0.066760,-0.322407,0.025047,-0.017738,0.366883,0.235086,0.211665,0.396997,0.091745,0.049758,-0.330972,0.208867,0.497638,-0.069044,-0.309230,0.317832,-0.170462,-0.173332,0.312044,-0.348676,-0.224575,-0.258133,-0.007314,-0.092369,-0.189923,0.322085,-0.569082,0.113804,0.084176,-0.017811,0.136804,-0.470632,-0.143835,-0.589446,-0.125414,-0.444469,-0.202970,0.063664,0.281299,-0.041425,0.816116,-0.873492,0.295509,0.191983,0.180970,-0.359854,0.825317,0.235808,-0.002933,-0.199687,0.015621,0.443325,0.270562,0.287966,-0.052375,0.139178,0.065615,0.016668,-0.375423,0.343514', '30162520', '4301278', '35048413', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303451', '海上花', '剧情', '该片改编自张爱玲曾将其“翻译”成国语的吴语小说《海上花列传》。上海英租界一所名叫“长三公寓”的高级妓院里，红倌人沈小红（羽田美智子）、黄翠凤（李嘉欣）与周双珠（刘嘉玲）心事迥异，一个想同某个男人建立长久关系，一个一边与多个男人斡旋，一边秘密锁定其中最有闲有钱的一位，想其 将来帮她赎身，另一个心地仁厚，却又看破红尘，觉得人生不过如此。几个女人用生存、竞争与心计作武器参与两性（同性）斗争，来到妓院狎妓的男人则抛出金钱、权力与性，见招拆招。©豆瓣', '梁朝伟', '侯孝贤', 8.2, 68971, 'tt0156587', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2588046848.jpg', 0.3, 1.4, 16.8, 48.6, 32.9, '0.416373,0.020141,-0.239261,0.710079,-0.125177,0.028690,0.689318,0.213168,-0.150192,-0.465563,0.221872,0.824337,0.029540,0.184163,0.220130,-0.127606,-0.199371,-0.647333,0.038929,-0.116938,0.011256,-0.438845,-0.198086,-0.215960,-0.333454,0.125161,0.431269,-0.129449,-0.443580,-0.039671,0.306366,0.383800,-0.527381,-0.006323,-0.206146,-0.222766,-0.000520,0.053344,-0.290413,0.165932,-0.370320,-0.047854,-0.185449,-0.258288,-0.001204,0.093026,0.410137,0.026874,0.015645,-0.137511,0.330760,0.249774,-0.552987,-0.066819,-0.020017,-0.163991,0.446089,0.186205,-0.278466,-0.053686,0.187366,-0.098524,-0.705129,-0.179628,0.115044,0.028759,-0.217624,0.207396,-0.000148,-0.408789,-0.232790,-0.214266,0.016129,0.029849,0.249662,0.174695,-0.022297,0.189165,-0.378947,0.273080,0.479894,0.103174,0.102783,0.078368,0.119355,-0.475139,0.110605,-0.186519,-0.276503,-0.371856,0.106257,-0.238761,0.043259,0.062116,-0.741135,0.219466,-0.115697,0.322914,0.302182,-0.274411,-0.000079,-0.327608,-0.175663,-0.196401,-0.112510,0.035167,0.440181,-0.157508,0.988164,-0.510799,-0.105027,0.521989,0.311906,-0.785614,0.661312,0.283953,0.399833,-0.408183,-0.195991,0.211791,-0.026496,-0.135631,-0.257323,0.252653,-0.297096,-0.200540,-0.259084,0.231665', '27602116', '4301278', '24284209', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303453', '鳗鱼', '剧情', '中年男子山下拓郎（役所广司）在亲眼目睹了妻子与人偷情的场面后，于愤怒中刺死了妻子，锒铛入狱，八年后，获假释出狱的他在千叶县利根河边开了家小理发店，因为当年的遭遇，他对人很难再信任，平时唯有的交流对象是所养的鳗鱼。山下无意间救下自杀的桂子（清水美砂）后，后者为了报答他留在理发店里工作，并因性格开朗为他招来很多客人，而他的性格亦渐渐阳光起来。山下的前狱友高崎出狱后，来到利根河附近从事垃圾回收的工作，为将山下的平静生活打乱，他开始不断地揭露山下的“丑行”，而桂子的原情人堂岛也于此时寻来，要带桂子和她的钱走，虽然深知一旦与人发生冲突就必须回到狱中继续服刑，山下还是为了保护桂子勇敢地采取了行动。©豆瓣', '役所广司', '今村昌平', 7.9, 13543, 'tt0120408', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204850715.jpg', 0.3, 1.7, 22.4, 53.7, 21.9, '0.046953,-0.027211,-0.551442,0.423912,-0.227078,-0.320190,0.663554,0.218121,-0.464779,-0.043912,0.056745,0.772654,0.161053,0.307501,0.307700,-0.000034,-0.495119,-0.616248,-0.245997,-0.256308,-0.251707,-0.288808,-0.000264,-0.274489,-0.319390,-0.120987,0.545560,0.275540,-0.027342,0.494182,0.164530,0.147744,0.021635,0.494967,-0.111984,-0.018035,-0.267432,0.144619,-0.272906,0.275504,0.072305,-0.471702,-0.232043,0.074510,0.306745,0.462534,0.641036,-0.132583,-0.243179,-0.317166,0.102003,-0.178759,0.119809,0.259969,0.407767,-0.048830,0.335756,0.417266,-0.484105,0.007584,-0.088692,-0.013666,-0.659036,0.012984,0.132037,-0.063869,-0.614660,0.406818,0.029867,0.017649,0.179323,-0.363189,0.054653,0.234383,0.195426,0.272580,-0.367497,-0.084269,-0.242394,-0.022717,0.796925,-0.051559,0.200152,0.270559,-0.088775,-0.369459,0.165956,-0.166337,-0.177941,-0.174182,0.192043,0.239956,-0.322400,0.171074,-0.412953,-0.021793,-0.196275,-0.022248,-0.067722,-0.283320,-0.213894,-0.483124,0.188584,-0.437865,-0.208822,0.068512,0.047594,-0.255852,0.387998,-0.717866,0.264459,0.609185,0.449691,-0.618282,0.472192,0.059716,0.223657,-0.208652,-0.039351,0.220595,0.186079,0.747487,0.223798,0.215119,-0.141272,-0.131406,-0.405919,0.438634', '30345227', '25721544', '1292584', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303456', '河流', '剧情', '作过一次临时演员后，小康（李康生）罹患歪脖子的怪病，父亲（苗天）带其四处求医。父亲虽已有妻、子，却是贪恋年轻男孩身体的同性恋者，家庭对他早已名存实亡，已丧失承担责任的能力（或认为并没什么责任要承担），可是对于小康，他又不自觉扮演起传统意义上的“父亲”角色，却也只能是失职的。小康是年轻的同性恋者，可是却并不清楚自己期望从同性处获得怎样一种安慰，父母的貌合神离不但令他对男女关系失掉信心，对同性关系的理解也盲从地认为只是两具肉体的短暂吸引、结合。而作为被丈夫（同时代男人）与儿子（更年轻的男人）同时冷落的母亲（陆筱琳），则只能默默忍受肉体与精神的双重饥渴与孤独。©豆瓣', '李康生', '蔡明亮', 7.7, 8724, 'tt0119263', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2524039419.jpg', 1, 2.9, 26.5, 48.4, 21.1, '-0.001085,-0.047013,-0.543578,0.421018,-0.393232,-0.289945,0.866749,0.016640,-0.572802,-0.147112,0.170660,0.732131,0.205172,0.346518,0.026046,-0.059525,0.110409,-0.573084,-0.119991,0.156148,-0.327355,-0.494063,-0.172398,-0.116673,-0.505427,-0.342570,0.864707,-0.152837,-0.400565,0.243391,0.455100,0.297712,0.046270,0.679328,-0.119517,-0.148523,-0.410064,0.219824,-0.375584,-0.192867,0.333808,-0.186426,-0.114703,0.185795,-0.254965,0.433186,0.525018,-0.303959,-0.418098,-0.290841,0.355796,-0.121728,0.011158,0.257836,0.097153,0.067377,0.329414,0.189824,0.096769,-0.068092,0.091899,0.153587,-0.822020,-0.099170,0.307523,0.061144,-0.451050,0.581016,-0.116797,-0.274165,0.042570,-0.168088,-0.120435,0.048739,-0.028979,0.607561,-0.561089,0.113386,-0.141294,0.045038,0.511273,0.320528,-0.495163,0.522022,-0.687558,-0.517498,0.027868,-0.386197,-0.597724,-0.089031,-0.141338,0.377401,-0.163587,0.301471,-0.053437,0.117998,-0.257549,0.073257,0.108230,-0.446615,0.264059,-0.104100,-0.222350,-0.479202,-0.317773,-0.026551,0.451218,-0.441612,0.680022,-0.862671,0.128534,0.511026,0.276554,-0.789321,0.439776,0.447253,0.151739,-0.267800,-0.215172,0.535052,-0.136741,-0.136766,0.021669,0.016452,-0.064147,0.026298,-0.203130,0.573653', '3318473', '4840388', '1308076', '6745433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303458', '南国再见，南国', '剧情', '高哥（高捷）接到小麻花（伊能静）的电话，赶到夜市见到被揍得鼻青脸肿的扁头（林强），没动手而是找到刑警欲讨公道，却被反抓，明白自己的尴尬处境——原来“弃武从文”只会使自己更难堪。可是以前混黑社会的日子，想想得来的也只有失落。因为不懂与时俱进，高哥显得很“可悲”，天早换成了另外的天，他却仍固守着原来的那朵云。30岁的他顾家、重情义、有思想，不想在打打杀杀中混日子，可是却无力改变环境，只能想办法适应环境，然而适应的结果，是事业与爱情的双失败。当他和小麻花、扁头在一起，能短暂放松身心，但是他们在食物链中处于相同的一环，能做的，也只是尽量要笑声持久一些。©豆瓣', '高捷', '侯孝贤', 8.1, 17055, 'tt0117151', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2412811816.jpg', 0.4, 1.5, 18.5, 52, 27.6, '0.414080,0.065698,-0.703867,0.407311,-0.288056,-0.307884,0.610492,0.142360,-0.537204,-0.270022,-0.145550,0.327608,0.078841,0.334894,-0.090425,-0.024398,-0.131573,-0.481970,0.144575,0.155841,-0.143112,-0.513759,-0.279407,-0.142796,-0.234021,-0.009386,0.598907,0.250078,-0.290840,0.237963,0.288863,-0.048913,0.228010,0.544573,-0.340491,-0.129963,-0.265433,-0.076863,-0.103476,-0.151129,0.376346,-0.218534,-0.309275,0.390262,0.182932,0.414331,0.400177,-0.154239,-0.334519,0.215311,0.209998,-0.439380,-0.282040,0.036063,0.115884,-0.073370,0.307770,-0.093469,-0.078151,0.165837,0.210248,-0.016485,-0.715787,0.418542,0.034300,0.206978,-0.656442,0.397001,0.044022,-0.173156,-0.031848,-0.453630,0.269196,0.397076,0.252058,0.500576,-0.366439,0.052083,-0.648931,0.080772,0.899433,0.123134,-0.427640,0.476282,-0.177503,-0.282224,-0.088482,-0.544868,-0.279778,-0.201666,0.189495,0.110347,-0.507333,0.015477,-0.170783,0.122915,-0.068570,-0.047729,-0.282877,-0.471563,-0.095714,-0.045922,-0.253504,-0.564683,-0.489664,0.284502,0.107908,-0.420031,0.451395,-1.053169,-0.022386,0.399387,0.301636,-0.572856,0.545232,0.467127,-0.104354,-0.043030,-0.179844,0.084604,-0.250435,0.098938,0.321432,0.146477,-0.154538,-0.357991,-0.470637,0.342028', '1877596', '35030151', '1301022', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303459', '妖夜慌踪', '悬疑', '这被认为是大卫•林奇拍得最混乱的一部电影。爵士乐手（比尔•普尔曼 Bill Pullman 饰）和他的妻子（帕特丽夏•阿奎特 Patricia Arquette 饰）一天早上收到了一盒录影带，他们发现里面的内容竟然是他们日常生活的点点滴滴。从此，他们每天早上都会收到这样的录影带。这天，乐手发现录影带里的内容竟然是他杀死了妻子！当他冲进卧室时，发现妻子果然死在了床上。警察将他带走了。一晚过后，原本在监房里坐着的乐手变成一个年轻的维修工，莫明其妙的警察只好将他放了。维修工因一手出色的修车技术深得黑社会老大器重，这时，他发现老大的女人竟然和他的妻子长得一摸一样，只是头发颜色不一样。老大的女人主动勾引了维修工，两人携款潜逃。当他们来到荒漠公路时，维修工与女子疯狂做爱，之后他又变回了乐手……©豆瓣', '比尔·普尔曼', '大卫·林奇', 8.1, 28224, 'tt0116922', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2040157660.jpg', 1.1, 2.7, 18.7, 45.9, 31.6, '0.491223,-0.093242,-0.698524,0.342587,-0.297979,-0.363417,0.791893,0.139843,-0.604693,-0.234420,0.239377,0.795514,-0.370237,0.337173,0.197185,0.168364,-0.466774,-0.874695,-0.277825,-0.174388,-0.353567,-0.174568,-0.195534,-0.132919,0.177178,-0.297023,0.331500,-0.152634,0.028272,0.476145,0.270469,-0.157737,0.008064,0.450487,-0.292878,0.344895,0.120508,-0.124103,0.155605,0.214141,0.151838,-0.205409,0.047434,0.035324,-0.138086,0.395748,0.631406,-0.195476,-0.124680,-0.063791,0.357142,-0.195283,-0.212354,0.177581,0.437847,0.055406,0.305412,0.004675,-0.186264,-0.123587,0.182182,0.035587,-0.477676,0.069499,-0.146281,0.152229,-0.688635,0.212142,-0.359545,0.066837,0.035981,-0.483925,0.457524,0.089669,0.032021,0.473315,0.094912,-0.097685,-0.644997,0.215507,0.469872,-0.061478,0.078395,0.504663,0.014516,-0.405643,-0.017884,-0.172986,-0.368712,0.019800,0.531483,-0.232573,-0.159281,-0.162272,-0.426488,-0.005842,-0.044445,-0.092388,-0.107145,-0.286000,-0.357793,-0.208343,-0.047675,-0.349624,-0.246710,0.161740,-0.143960,-0.143237,0.580987,-0.684729,0.237350,0.473753,0.207605,-0.154206,0.708618,-0.161606,-0.088407,-0.106260,0.025338,-0.175000,0.304741,0.401572,0.510736,0.468162,-0.134880,-0.298772,-0.420408,0.359989', '1805685', '3111650', '1307146', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303462', '离魂异客', '剧情', '来自克里夫兰的美国小伙子威廉•布莱克（约翰尼•德普 Johnny Depp 饰）往西部去讨生活，他准备前往当地的一间工厂应聘会计。不料，他错过了应聘时间，被赶了出来。还遭到了当地迪金森金属厂的老板的百般凌辱，甚至被枪指着脑袋。当他沮丧地来到当地的小酒馆，一夜情发生了。岂料，和他发生一夜情的女子的男友突然闯了进来，子弹穿过女子的胸膛嵌在了威廉的胸膛上，威廉本能之下杀死了女子的男友，夺了他的马匆匆逃走了。一段充满了惊险、追杀的逃亡之旅开始了……©豆瓣', '约翰尼·德普', '吉姆·贾木许', 8, 20917, 'tt0112817', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155134187.jpg', 0.7, 2.4, 20.8, 45.7, 30.3, '0.509571,-0.013448,-0.869221,0.248108,-0.214553,-0.370494,0.903994,0.231509,-0.222499,0.042667,0.400763,0.639454,-0.331593,0.125858,0.569321,0.285619,-0.059358,-0.783286,-0.164022,-0.142271,-0.419064,-0.026426,-0.093281,-0.217499,0.043964,-0.160901,0.375706,0.079315,-0.137505,0.478487,0.220148,0.258059,0.013344,0.642922,-0.424389,0.458870,0.255911,-0.131721,-0.004631,0.288707,0.158429,-0.703339,-0.062448,-0.066908,-0.162998,0.504587,0.626810,0.066626,0.139302,0.079589,0.265755,-0.135312,-0.010782,0.189543,0.452792,0.199923,-0.174199,-0.003356,-0.253723,-0.019545,0.454069,-0.067990,-0.290373,0.266968,-0.296589,0.043264,-0.966512,0.318273,-0.166446,0.140795,0.042285,-0.553953,0.311821,0.079824,-0.065178,0.193101,-0.003392,0.093549,-0.713354,0.323004,0.624010,-0.051650,-0.015510,0.103519,-0.056526,-0.345250,0.025981,-0.093251,-0.413367,-0.213915,0.931817,-0.298025,-0.445760,0.013393,-0.572272,-0.066863,-0.466119,-0.290673,-0.142874,-0.102956,-0.305608,-0.668463,-0.034576,-0.211915,-0.234040,0.052299,0.027421,0.116728,0.244500,-0.694695,0.009196,0.705270,0.383169,-0.232227,0.651912,-0.225122,0.010957,0.257542,0.037045,0.185248,0.242756,0.790196,0.360910,0.671157,-0.019282,-0.144543,-0.238283,0.469602', '1297347', '25837175', '1292533', '2078159');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303463', '冷酷祭典', '剧情', '苏菲（桑德里娜·伯奈尔 Sandrine Bonnaire饰）在中产阶级乐里芙家做女佣，她千方百计隐藏着自己不识字的秘密。性格内向的苏菲内心非常敏感，事事留神不犯差错，并得到了主人家的认同。乐里芙一家对苏菲彬彬有礼，同时也昭示出主仆间的不同等级。在镇上的邮局，苏菲认识了同属穷人阶级的珍（伊莎贝尔·于佩尔 Isabelle Huppert饰）。珍对有钱人充满了扭曲的愤恨心理，成为苏菲的好友后，她从没有停止过煽动苏菲，让她与富人阶级决裂。矛盾一步步走向无可调和的地步，苏菲的秘密在乐里芙家曝了光，和谐的外壳瞬间倒坍，珍和苏菲的反抗如同狂风骤雨……©豆瓣', '伊莎贝尔·于佩尔', '克洛德·夏布洛尔', 8.1, 11231, 'tt0112769', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2304513161.jpg', 0.5, 2.3, 16.8, 53.8, 26.6, '0.580475,0.103089,-0.842997,0.464613,0.044829,0.174766,0.936223,0.325883,-0.439009,0.075000,0.070017,0.509485,-0.344913,0.018163,0.159709,0.046776,-0.355478,-0.542011,0.234722,-0.461067,-0.012685,-0.552888,-0.044602,-0.145687,-0.219745,-0.336821,0.389336,-0.224005,-0.287401,0.410993,0.420535,0.485623,-0.086373,0.520520,-0.062192,0.142488,-0.012870,-0.106537,-0.165123,-0.107527,0.162632,0.162468,-0.472362,0.263758,0.040818,0.598139,0.498970,-0.358264,0.089774,0.011844,0.245136,0.105688,0.132701,0.226074,0.126944,-0.284429,0.017786,0.343158,-0.140037,0.234752,0.321420,0.133534,-0.666641,0.150119,0.361666,0.286356,-0.692451,0.507699,-0.046093,-0.238212,-0.012450,-0.160932,0.086424,0.322492,0.005533,0.236915,-0.209570,0.156410,-0.580816,-0.100517,0.291363,0.235906,-0.578348,0.491094,-0.540041,-0.269082,-0.269331,-0.053204,-0.550979,-0.503186,0.358985,0.250818,-0.271114,0.198818,-0.511445,-0.204179,-0.295246,-0.021639,0.070385,-0.480150,-0.202708,-0.580461,-0.274658,-0.739350,-0.321217,-0.166663,-0.215006,-0.360231,0.613027,-0.904466,-0.117795,0.330604,0.476546,-0.421605,0.397052,-0.052149,-0.097195,-0.279011,-0.396357,0.302193,-0.051553,0.253898,0.373151,0.550130,0.066022,0.230812,0.198190,0.806194', '26704621', '20277433', '3111650', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303471', '生生长流', '剧情', '1990年伊朗西北部发生大地震，影片《哪里是我朋友家》的拍摄地点柯盖尔就在这个地区，导演带着儿子驱车前往那里寻找影片中的演员。父子俩沿路接触到的一个个劫后余生的村民没有人们想象中的悲哀神态，而是积极投身到震后的重建工作，更加珍视生命。尤其是那对在地震后第二天就举行婚礼的年轻夫妇，更能让人感受到经历过劫难的村民们的强大生命力。最后他们没有见到扮演两位小主人公的演员，但有人说刚刚看见他们。观众应该还记得《何处是我朋友的家》中那个可爱的演员小男孩，1990年，灾难降临在他居住的地方，大地震几乎毁灭了当地一切。小演员生死未卜下落不明，阿巴斯在地震后，坐着汽车重返故地，寻找孩子。在路上，导演见到了许多触目惊心的景象，废墟、悲痛的人们、死亡……然而，令导演觉得惊奇的是，人们并没有沉溺于悲痛无法自拔，而是在灾难之后重整心情重建家园。死亡使生者更加珍惜生命，以更加充足的勇气活下去，希望并没有失去，片中比较高潮处，是一对男女在地震后举行婚礼。小演员最终没有找到，给片子积极向上的基调抹上了淡淡的感伤色彩。幕后制作：该片记录了前往灾区一路上的见闻，获得1992年戛纳国际电影节罗西里尼人道主义精神奖、金摄影机奖。看这部片子，有一种做梦的感觉，对人生的感悟从寻找的足迹一层层剥离出来，彷佛跟阿巴斯一起进行了一次远行，时间随着形形色色的风景在平静中不易觉察地缓慢流逝，蛮有意思。日本导演黑泽明曾经称阿巴斯的作品“无与伦比”，这句评论是否太过此处不予界定，但从这部片子里，阿巴斯的从容以及悲天悯人的胸怀，确实够得上大师的封号，对生命的思考是阿巴斯永不休止的询问以及创作灵感的来源。此片中有一些场面，会在《橄榄树下的', '法德哈·基德曼', '阿巴斯·基亚罗斯塔米', 8.8, 11276, 'tt0105888', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1944277781.jpg', 0.2, 0.4, 7.8, 40.3, 51.2, '-0.083672,-0.093339,-0.762674,0.587609,0.115009,-0.153480,0.872090,-0.069954,-0.460585,-0.162323,0.214561,0.704313,-0.375803,0.249239,0.261314,-0.112146,-0.462234,-0.599708,-0.253618,0.061522,-0.280002,-0.260047,-0.305985,-0.083791,-0.211814,-0.415377,0.687773,0.503002,-0.229171,0.429407,0.038413,-0.056928,-0.096082,0.591160,-0.211481,-0.065181,-0.100797,0.268071,-0.358310,0.211473,0.180751,-0.307761,-0.400510,0.283785,0.011353,0.299133,0.582540,-0.280555,-0.204313,0.155810,0.480293,-0.232454,0.030371,0.055014,0.103061,0.075635,0.217277,0.088918,-0.109570,-0.015442,-0.108789,-0.158028,-0.733508,-0.034836,0.044469,0.384339,-0.459559,0.341800,0.146323,-0.036411,0.147110,-0.273275,0.476407,0.227638,0.225426,0.415825,-0.128112,-0.077137,-0.334457,0.275223,0.707732,-0.071183,-0.294956,0.540951,-0.376336,-0.557793,-0.100865,-0.166182,-0.528628,0.263413,0.119354,0.184051,-0.171216,0.215451,-0.488245,0.101611,-0.027667,-0.476457,-0.037028,-0.199626,-0.118944,-0.900423,-0.169547,-0.342984,-0.097551,-0.131356,0.146707,-0.338255,0.835070,-0.646600,0.213680,0.462855,0.231706,-0.365155,0.708370,-0.082849,-0.103055,-0.093626,-0.001920,0.229572,-0.151725,0.313628,-0.008273,0.208866,-0.151491,-0.142040,-0.308245,0.580900', '26259202', '3318306', '30162520', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303485', '洗澡', '剧情', '早年丧偶育有两子的老刘（朱旭）苦心经营了一辈子澡堂子，是京城搓澡行业的一把手。长子大明（濮存昕）离家南下多年没归，身边只有傻二儿子二明（姜武），加上澡堂子生意日益冷清，老刘生出无限凄凉，好在，他还有一帮离不开澡堂子的老伙计相陪。某日，大明突然归来，令老刘错愕不已，原来他是收到二明寄发的明信片误以为父亲病逝才匆忙赶回。而面对安然无恙但已到迟暮之年的父亲、什么也不懂的傻弟弟和破败的澡堂子，大明毫无久留之心，只想速速返程。就在大明动身时刻，老刘突然犯病，不得已，大明放下行李开始照顾父亲、弟弟和澡堂子，自此，他开始试着去了解父亲，并渐渐生出感动。©豆瓣', '姜武', '张杨', 8.4, 63355, 'tt0215369', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2619211905.jpg', 0.1, 0.7, 13.2, 49.7, 36.3, '-0.113564,-0.077602,-0.980469,0.206642,-0.080851,-0.636444,0.452769,0.282706,-0.660333,-0.586283,-0.109018,0.530293,0.065434,0.677689,-0.109883,-0.068458,-0.086230,-0.249051,-0.155593,-0.046606,-0.162701,-0.306842,0.085317,-0.254612,-0.232521,-0.008983,0.242466,0.132959,0.057014,0.453020,0.455595,0.005926,-0.102001,0.695687,-0.325406,0.277855,-0.155137,0.206772,-0.345228,-0.303236,0.405057,-0.288847,-0.147585,-0.181949,0.281954,0.112810,0.282900,0.168166,-0.336599,0.001518,0.408238,-0.104750,-0.199215,-0.093356,0.425054,0.002656,-0.118164,-0.120810,-0.179150,-0.021905,-0.174088,-0.152460,-0.026818,0.218797,0.082165,-0.103732,-0.786255,0.011080,0.039422,-0.204985,0.069284,-0.722071,0.374443,0.395499,0.029563,0.549326,-0.100709,0.136002,-0.398721,0.286762,0.607875,-0.081278,-0.050151,0.086408,0.208613,-0.215443,0.522956,-0.128074,-0.421994,0.000884,0.165242,-0.026202,0.019251,0.095281,-0.045158,-0.146335,-0.152106,-0.119800,0.368832,-0.225723,0.126575,-0.125505,-0.282700,-0.400799,-0.136772,0.243601,0.217525,-0.247117,0.442904,-0.715815,0.324203,0.164751,0.264019,-0.854975,0.436393,0.033529,0.106149,-0.109220,0.201626,0.300725,0.184140,0.193306,0.352450,-0.116102,-0.401575,-0.028161,-0.143921,0.130393', '1421278', '1301221', '35461732', '30241301');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303497', '神经刀与飞天猫', '喜剧', '携带侄儿小飞刀（林志颖）以缉盗领赏为生的大飞刀（梁家辉）被大风骚（张敏）爱慕，但因不解风情，令大风骚因爱生怨，时常带着妹妹小风骚（叶蕴仪）与大小飞刀作对。大风骚得知富商曹员外（陈鸿烈）出高价诱捕天下第一大盗九尾狐（张学友）时，施计绊住大小飞刀，想捷足先登，没料九尾狐的老婆飞天猫（张曼玉）很不好惹，大小风骚在偷袭时不敌被擒。大小飞刀及时赶来将大小风骚救出，四人合力拿住了九尾狐，但终被其逃脱。在追赶九尾狐时，四人再次与飞天猫狭路相逢。见其欲色诱大飞刀，大风骚醋劲大发与其展开恶战，而此时曹员外缉捕九尾狐的真正原因被揭露，众人遂连手一致对抗曹员外。©豆瓣', '林志颖', '朱延平', 6.7, 12712, 'tt0108112', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2569937448.jpg', 1.3, 8.2, 52.9, 28.5, 9, '-0.095193,-0.056130,-0.612780,0.072531,-0.127653,0.034573,0.588419,-0.005695,-0.210228,-0.064524,0.322679,0.441870,-0.551669,-0.020541,-0.211312,-0.130265,0.463682,-0.497835,-0.191755,0.220650,0.034825,-0.164335,-0.290516,0.059464,-0.010981,0.259776,0.043087,-0.299138,-0.115689,0.473320,0.581954,0.039555,-0.462898,-0.113411,-0.149022,-0.063276,-0.316924,-0.150365,0.028905,0.266681,-0.110086,-0.311425,-0.196024,-0.250646,-0.205434,0.487631,0.536918,-0.369126,0.010684,-0.331701,0.208443,-0.142292,-0.164884,0.164238,0.038633,-0.004697,0.097223,-0.527066,-0.262142,-0.153844,0.420623,-0.373117,-0.415982,0.594081,-0.056457,-0.257222,-0.305930,0.234535,-0.165215,0.032388,0.320418,-0.324346,-0.117429,-0.030219,0.133252,-0.216180,-0.033529,0.068676,-0.455732,0.174006,0.365697,0.005636,0.175921,-0.270504,0.358668,-0.176383,0.104829,-0.542396,0.002918,-0.095716,0.808915,0.137303,-0.099082,0.375021,-0.289680,-0.004179,-0.525272,0.785403,-0.146225,-0.007048,-0.261271,-0.250932,-0.003779,-0.347481,-0.174717,0.130614,0.445624,0.023814,0.681401,-0.638949,-0.064060,0.006267,0.307298,-0.462576,0.302394,-0.083431,-0.017873,0.138267,-0.303197,-0.224388,0.565377,0.143707,0.788516,0.197630,-0.320989,-0.323433,-0.270411,-0.086562', '1292440', '1300359', '1302033', '1294488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303521', '特写', '剧情', '德黑兰，记者法拉兹曼德前去报道年轻人霍塞·萨布齐恩因诈骗被捕的事件。原来，失业的油漆工萨布齐恩是一个影迷，他自称是著名导演穆赫辛·马克马尔巴夫，取得阔绰的阿汉卡赫一家信任，向他们借钱拍片。事发后，萨布齐恩被抓。导演阿巴斯·基亚罗斯塔米就此案展开了纪录片似的跟踪调查，他采访了警察，阿汉卡赫全家，以及萨布齐恩本人。审讯过程中，萨布齐恩为骗取了阿汉卡赫一家的感情而后悔，但他说之所以这样做是因为对艺术的热爱，如果有钱，他真地会拍摄自己的电影。而且，假扮导演马克马尔巴夫赋予了他自信。最后，原告阿汉卡赫家撤销了起诉，而萨布齐恩也见到了真正的马克马尔巴夫，后者骑小摩托带这个年轻人重访阿汉卡赫。', 'Hossain Sabzian', '阿巴斯·基亚罗斯塔米', 8.8, 12532, 'tt0100234', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2350715785.jpg', 0.3, 1, 9.1, 39.1, 50.5, '0.217082,0.010771,-0.541602,0.631714,0.138758,-0.751482,0.412372,0.238191,0.156200,-0.574166,0.183151,0.246375,-0.346371,0.320922,0.230537,0.193032,-0.417162,-0.455387,-0.047991,-0.108156,-0.247204,-0.534349,0.105262,-0.588657,-0.134221,-0.135550,0.036344,-0.174800,-0.110585,0.194789,0.444272,0.317320,0.500157,0.287606,0.304763,0.240196,0.435329,-0.135654,-0.255034,0.201088,0.222035,-0.021417,0.097620,0.281517,0.306089,0.464193,0.505783,-0.264074,0.217765,0.013099,0.333819,-0.498082,0.269024,0.028670,0.151369,-0.280083,-0.124706,-0.148141,0.049635,-0.214732,0.006402,-0.061033,-0.417457,-0.189116,-0.272387,0.018923,-0.239288,0.017885,-0.207132,0.282876,-0.133416,-0.108193,0.089000,0.118778,0.404512,0.169864,0.367032,0.067524,-0.504065,0.173049,0.561346,-0.125187,-0.175414,0.181265,-0.503318,-0.757013,0.196624,0.009297,-0.355890,0.132438,0.457023,-0.528477,0.311024,0.307429,-0.158031,-0.375462,-0.387355,0.468254,-0.172534,-0.199313,0.273046,-0.640673,-0.111306,-0.120179,-0.157609,0.008130,-0.156612,-0.304027,0.467238,-0.251998,0.132517,0.520632,0.453779,-0.333765,0.671105,-0.161275,-0.356740,-0.199355,-0.051005,0.292465,0.300270,0.021443,0.375079,0.147408,0.266804,-0.365242,0.246813,0.381328', '26636537', '1293460', '20365404', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303525', '流浪者之歌', '剧情', '巴尔干某城市边缘的茨冈村落里，小伙子贝汉（Davor Dujmovic 饰）与外婆一家四口生活在一起，嗜赌的舅舅梅尔桑每次输光后就开始怀念在德国的生活，妹妹的腿疾因无钱而得不到救治。贝汉与同村的阿兹娜相恋，但对方母亲嫌弃贝汉一家贫穷坚决回绝。长年在意大利赚钱的族长阿梅德回到村子，在赌桌上让梅尔桑输到丧失理智，毁掉了自家人的木屋。但外婆却用巫术救回了阿梅德的孩子，为表谢意，阿梅德答应带妹妹出国治病，并让身怀隔空移动小铁器特异功能的贝汉随行。贝汉很快发现阿梅德不过是利用儿童乞讨盗窃的团伙头子，但已无力摆脱只得随顺，不久阿梅德患病，将小团伙交予贝汉管理，贝汉摇身一变成为有钱人，遂回乡将阿兹娜接到米兰，但阿兹娜腹中的骨肉让贝汉大为光火，坚持要将孩子卖掉……本片获1989年戛纳电影节最佳导演奖。©豆瓣', '达沃尔·杜伊莫维奇', '埃米尔·库斯图里卡', 9.1, 13298, 'tt0097223', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2384320756.jpg', 0.2, 0.6, 5.6, 29.3, 64.3, '0.000172,-0.107158,-0.481982,0.321470,-0.308212,-0.315015,0.564855,0.148060,-0.323846,-0.060287,0.102235,0.823455,0.158971,0.328834,0.059275,0.136695,0.030866,-0.340498,0.083616,-0.021111,-0.216359,-0.516950,-0.055786,-0.338532,-0.280866,-0.361707,0.661102,0.008966,0.019930,0.544775,0.293043,0.112617,-0.158810,0.269795,-0.501159,0.057191,-0.310673,-0.008019,-0.365984,0.358413,0.174855,-0.096675,-0.174593,-0.052139,0.403147,0.258395,0.681553,-0.025851,0.054828,-0.154956,0.227374,-0.323282,-0.252120,0.136646,0.188257,0.137533,0.275557,0.071637,-0.421962,0.051973,0.233377,-0.095310,-0.288361,0.198219,0.130050,-0.173143,-0.966444,0.179285,0.044410,-0.192236,-0.088790,-0.411120,0.284466,0.342518,-0.013617,0.416619,-0.044894,0.157631,-0.537718,0.076823,0.584518,-0.438534,-0.109663,0.096439,-0.053996,-0.176108,0.469880,-0.413161,-0.300662,-0.065414,0.109917,0.005756,-0.332300,0.000651,-0.531586,-0.128518,-0.277477,0.005776,0.272350,-0.571524,-0.071325,-0.464133,-0.037742,-0.097317,-0.140075,-0.069688,0.343681,-0.234695,0.608143,-0.629645,0.235812,0.333319,0.404043,-0.475464,0.644042,0.026671,0.374470,-0.153403,0.023475,0.242488,0.386764,0.124580,0.183426,0.051774,-0.230796,-0.144383,-0.272606,0.164240', '1306505', '1299965', '25731805', '1876765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303526', '女人韵事', '剧情', '尽管玛丽（伊莎贝尔·于佩尔 Isabelle Huppert 饰）如今已是两个孩子的母亲了，可是从小没有接受过什么正规教育的她在心智上依旧犹如一个懵懂的孩童。玛丽的丈夫保罗（弗朗索瓦·克鲁塞 François Cluzet 饰）是一名士兵，在动荡的局势下，他被派往前线参加战争，至今未归，留下妻儿过着贫穷又困苦的生活。玛丽帮助一个女人进行了堕胎手术并从中发现了商机，在那个年代，堕胎是违法行为，协助堕胎更是死罪一条，可迫于生活的压力，面对金钱的诱惑，玛丽还是干起了这违法又危险的工作。一次偶然中，玛丽结识了名叫卢锡安（尼尔斯·塔维涅 Nils Tavernier 饰）的男子，两人一见钟情，遂即展开了一段背德的爱情。没想到归来后的保罗识破了二人的奸情，愤怒的他向警方告发了玛丽的全部行径，玛丽将要面对的，是死亡的判决。©豆瓣', '伊莎贝尔·于佩尔', '克洛德·夏布洛尔', 8.2, 9644, 'tt0096336', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554650899.jpg', 0.2, 0.8, 13.7, 57.2, 28.1, '0.318946,0.037121,-0.673930,0.559443,-0.303289,-0.419079,0.962543,0.129401,-0.496401,-0.147344,0.403260,0.583308,-0.101951,0.268354,0.209775,0.047234,-0.193814,-0.597644,-0.035769,-0.041982,-0.397976,-0.373204,-0.328740,-0.201807,-0.129650,-0.336886,0.547470,0.129538,-0.179725,0.404581,0.419285,0.323506,-0.016472,0.655148,-0.118089,0.022596,0.267103,0.019923,-0.284309,0.214046,0.095675,-0.627797,-0.146679,0.349555,-0.123209,0.500159,0.626403,-0.501591,-0.201168,-0.217077,0.451402,-0.263509,-0.084337,0.289321,0.282395,-0.158386,-0.028179,0.249963,-0.136707,-0.051013,0.023570,-0.039751,-0.683210,-0.167103,-0.048101,0.356001,-0.839001,0.420537,-0.222791,-0.090564,-0.207818,-0.385170,0.085464,0.341600,-0.005891,0.474700,-0.332102,0.031465,-0.514312,0.212221,0.728783,-0.054460,-0.376365,0.280897,-0.459175,-0.467579,0.161019,-0.226824,-0.652765,0.050982,0.448710,-0.113301,-0.362527,0.262606,-0.551297,0.014821,-0.452461,-0.164218,-0.136003,-0.301195,-0.109403,-0.524386,-0.027188,-0.555886,-0.584312,0.073274,0.130555,-0.201613,0.632065,-0.735950,0.224527,0.670552,0.251730,-0.607258,0.380167,0.354714,0.231065,0.039600,-0.130071,0.384500,-0.054390,0.264080,0.142377,0.407881,0.186302,-0.151375,-0.210960,0.495267', '21619567', '1301022', '129