INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303531', '下班后', '剧情', '电脑文书保罗（Griffin Dunne 饰）下班后去餐厅宵夜，他手上的《北回归线》让邻座的神秘女子玛西（Rosanna Arquette 饰）上前搭讪，玛西留下电话号码，并向他介绍与自己合租的女雕塑家琦琦。保罗为追求一段艳遇，在午夜时分拨通了玛西的电话，玛西家中因纸糊雕塑显得凌乱不堪，她本人则急于喋喋不休的倾诉，让保罗无法得逞，保罗不能忍受那个没有露脸的男人“富兰克林”与玛西的神经质表现，在急欲返家之时，却又卷入了连串麻烦，与酒吧老板、酒吧女招待、朋克青年们、两名窃贼、开冰激凌车的女青年等等纠缠不清，似乎在这个夜里，所有人都在妨碍保罗回家。本片获1986年戛纳电影节最佳导演奖，1986年独立精神将最佳导演奖。©豆瓣', '格里芬·邓恩', '马丁·斯科塞斯', 8.2, 8963, 'tt0088680', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2100221825.jpg', 0.4, 1.7, 15.6, 52.5, 29.8, '0.223436,0.071922,-0.555785,0.427899,-0.242157,-0.257739,0.870708,0.294591,-0.040412,-0.217683,0.033150,0.843826,-0.233362,0.288509,0.517766,-0.144345,-0.415954,-0.666179,0.089445,-0.121437,-0.096948,-0.234200,-0.083893,0.032252,-0.084882,-0.238478,0.237293,-0.199070,-0.203082,0.627612,0.423851,0.028226,-0.115803,0.504207,-0.260965,-0.010858,0.236979,-0.162744,-0.244729,0.232191,0.123970,-0.396437,-0.365291,0.310550,0.212701,0.318644,0.596276,-0.090843,-0.178039,0.172904,0.334882,-0.117376,0.118411,0.103721,0.147720,-0.241124,0.163486,-0.042626,-0.147335,0.089309,0.157224,-0.007245,-0.443577,0.466508,-0.117952,0.223441,-0.574931,0.446045,-0.374582,0.092939,-0.000751,-0.308369,0.228833,0.102811,0.009394,0.254734,0.230615,0.116030,-0.410158,0.314372,0.381901,0.334747,-0.023555,0.271339,-0.103430,-0.358218,0.061179,0.055640,-0.714077,-0.129781,0.519408,0.044278,-0.106368,-0.179183,-0.351707,-0.229924,-0.248494,-0.192172,0.009052,-0.262026,-0.364099,-0.742658,0.068071,-0.000874,-0.228182,0.121815,0.154181,0.094517,0.521385,-0.478308,0.286565,0.606076,0.321642,-0.387500,0.816646,0.039816,0.133819,-0.186024,-0.166406,0.044502,0.132960,0.325194,0.147382,0.486254,-0.222990,-0.072690,-0.510760,0.260224', '3326747', '1301686', '1361252', '4319218');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303534', '沙滩上的宝莲', '剧情', '年轻美丽的波琳正在和她性感的堂姐玛利恩在法国风景秀丽的大西洋海岸度假，这一切的发生是因为不久前三个男子诱惑她们陷入爱河。当谎言和欺骗妨碍他们多愁善感的情绪的时候，田园诗般的乐园不再甜蜜……波琳天真无邪的爱情观不再纯洁……', '阿曼达·朗格勒', '埃里克·侯麦', 8.1, 13593, 'tt0086087', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164464526.jpg', 0.3, 1.1, 16.7, 55, 27, '0.486950,0.016624,-0.924643,0.455988,-0.486615,-0.080797,1.391759,0.160936,-0.319626,-0.029896,-0.067283,0.695132,-0.214949,0.650574,0.423236,0.378629,-0.440435,-0.667320,-0.292640,-0.106997,0.370423,-0.376007,-0.082247,0.143552,0.222526,-0.638714,0.562396,0.162244,-0.333683,0.336393,0.271572,0.424826,-0.401137,0.291318,-0.187689,-0.123344,0.098742,0.293273,-0.400135,0.141892,-0.103777,-0.024022,-0.103997,0.140697,-0.224530,0.080185,0.682013,-0.202641,-0.408122,0.054014,0.312696,-0.184099,0.104742,0.368354,0.097620,-0.610889,0.365213,0.169677,-0.258884,-0.183272,0.305364,-0.253739,-0.594562,0.126990,0.114696,0.396361,-0.093672,0.398509,0.076405,-0.426751,0.556251,-0.239005,0.043621,0.186150,0.280279,0.641581,-0.071580,0.232018,-0.416188,0.219909,0.949410,0.657385,-0.471526,0.576427,-0.432163,-0.104794,-0.081042,-0.163421,-0.605210,0.255035,0.160237,-0.059429,-0.354581,0.508301,-0.694603,-0.012595,-0.034287,-0.143127,-0.015059,-0.578897,-0.436776,-0.632808,-0.309428,-0.952132,-0.272441,-0.064529,-0.006052,0.235713,0.651282,-1.031597,0.468119,0.769214,0.179254,-0.486385,0.533731,0.569002,-0.246080,-0.244604,0.064098,0.555131,-0.334843,0.088400,0.039865,0.441547,-0.311662,0.373999,-0.550904,0.442268', '1296534', '4275444', '1291835', '2131640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303535', '战场上的快乐圣诞', '剧情', '1942年，第二次世界大战如火如荼，此时的日本在亚洲各战场所向披靡，无往不利。在南洋爪哇岛的热带丛林中，一所日军战俘看守所伫立于此，陆军大尉世野井（坂本龙一 饰）和大原上士（北野武 饰）共同管理看守所。大原作风粗鲁，冷酷无情，他对待欧美战俘从来不留情面，而对于那些有同性恋倾向的人更残酷至极。相比之下，相貌俊美的世野则显得绅士许多。英国陆军少佐杰克（David Bowie 饰）潇洒俊朗。他的第一次出现便让世野心有所动。同性之风盛行的战俘营中，几多情感不能自已。在接下来的日子里，两个人徘徊在家国恩怨和个人情感之间，彼此心中进行着辛苦而残酷的角力……本片根据英国人劳伦斯·包斯特的小说改编，并荣获1984年电影旬报观众选择奖最佳影片，1984年每日电影最佳导演、最佳影片、最佳配乐、最佳剧本以及最佳男配角（北野武）等5个奖项。©豆瓣', '大卫·鲍伊', '大岛渚', 8.8, 107655, 'tt0085933', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2630100110.jpg', 0.4, 0.9, 8.6, 36.9, 53.2, '0.007313,-0.049727,-0.682678,0.693717,0.315538,0.038124,0.617044,-0.003226,-0.663057,-0.190713,0.070052,0.851641,-0.169777,-0.086804,0.324304,-0.292734,-0.465907,-0.809811,-0.483350,0.025927,0.117581,-0.255276,-0.338727,-0.193558,-0.331688,-0.253050,0.773781,-0.076902,-0.030403,0.599309,0.320421,0.130864,-0.101056,0.074256,0.090037,-0.245144,0.294875,-0.085383,-0.479783,0.226760,-0.026955,-0.168783,-0.417668,0.054304,-0.010329,0.197118,0.689579,-0.178458,-0.266193,0.126327,0.500452,-0.190796,-0.363677,0.093669,0.273141,-0.263185,0.258668,0.297605,0.010923,0.319090,-0.097568,-0.218572,-0.581901,-0.046765,-0.010833,0.206776,-0.192068,0.555662,-0.106513,0.238535,-0.125211,-0.068960,0.085500,0.133275,0.498697,0.110009,-0.247548,-0.027197,-0.098880,0.674987,0.429995,0.215553,-0.490863,0.066492,-0.282326,-0.502787,-0.171145,-0.450210,-0.440274,-0.094350,0.090716,-0.258324,0.169246,0.273914,-0.554408,0.246333,0.045499,-0.229525,0.065667,-0.163707,-0.158963,-0.785729,-0.215582,-0.595579,-0.280060,0.123331,0.207075,0.075033,0.916045,-0.616358,0.033019,0.367670,0.125447,-0.259279,0.647208,0.216567,-0.024978,-0.102689,-0.314278,0.371471,-0.114810,-0.086955,-0.066157,0.346091,-0.343747,-0.286706,-0.148571,0.301072', '3811356', '27602116', '1780122', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303536', '钱', '剧情', '一个男孩因为向父母讨要零花钱失败，去当了自己的手表，却换回一张500元法郎的假钞。之后，这张假钞在很多人之间转手，最后落到了一个叫伊文（克里斯琴·佩蒂 Christian Patey 饰）的年轻人手中。伊文试着去餐馆花掉这张假钞，但被服务员发现了。警察认为他参与了假钞贩卖案而逮捕了他，但法官念他初犯，没有给他判刑。伊文释放之后，丢了工作。没有了钱，他只好和朋友去银行抢劫，却又一次栽在警察手里，被抓进监狱，被判刑三年…… 本片是布列松的最后一部作品，改编自托尔斯泰的短篇小说《伪息券》，曾获第36届戛纳电影节主竞赛单元最佳导演奖。©豆瓣', 'Christian Patey', '罗伯特·布列松', 8.3, 11714, 'tt0085180', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1722573465.jpg', 0.5, 1.6, 13.6, 49, 35.3, '0.165316,-0.028291,-0.388508,0.391565,-0.371386,-0.654631,0.886648,0.217026,-0.309296,0.100914,0.185491,0.818864,-0.103634,-0.049621,0.277477,0.207577,-0.356547,-0.557107,0.101152,-0.604368,-0.160052,-0.341154,-0.190995,0.108809,-0.203735,-0.105862,0.425558,-0.318715,-0.226853,0.288705,0.442426,0.055697,0.084627,0.368066,-0.154208,0.341554,0.150403,-0.139094,-0.064191,0.524253,0.188530,-0.512164,-0.247127,0.152682,0.348140,0.508966,0.753726,0.211886,-0.083976,0.152324,0.535867,-0.228144,-0.431651,0.058456,0.079749,0.256464,0.134686,-0.052557,-0.355507,-0.030606,0.283908,0.056821,-0.576807,-0.178631,-0.053379,0.100946,-0.773321,0.823735,-0.497991,0.382903,-0.217921,-0.433678,0.257715,0.195845,0.102143,-0.001097,-0.007865,-0.230986,-0.778741,0.506027,0.286542,-0.273074,0.020293,0.332958,-0.116321,-0.463059,-0.076123,-0.154880,-0.271210,0.292337,0.731224,-0.045798,-0.408941,-0.117061,-0.554156,-0.433605,-0.347954,-0.333888,0.034922,-0.322124,-0.264999,-0.362776,0.015175,0.044309,-0.311959,0.050004,0.087399,-0.290104,0.523073,-0.242134,0.263648,0.771156,0.381371,-0.240853,0.673126,0.208459,-0.130612,0.142741,0.140909,-0.325532,0.511695,0.887660,0.488694,0.196758,0.127267,-0.501409,-0.095788,0.469613', '21619567', '6753166', '1295324', '1316560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303542', '石榴的颜色', '剧情', '影片部分根据18世纪亚美尼亚诗人Savat Nova的生平拍摄，但更多地是以诗句代替了诗人的形象。全片几乎没有对白，主要是旁白和剧中人自言自语。无法用文字概括该片的内容，而且每个人都有权利按自己的方式诠释它。影片几乎从头到尾都是精彩瞬间，电影语言的诗化、色彩的明艳、构图的奇特均衡、内容上的仪式感、宗教感和展现的民族传统文化，都使影片具有超凡脱俗、特立独行的品质。影评：试图用文字概括这部影片的内容，基本上是一种荒谬的想法，而且对于亚美尼亚传统文化和宗教无法了解太多的我们，甚至无法完整说出哪怕一个细节所提供的含义。但对于这样一部风格鲜明突出的杰出影片，如果是因为无法描述而使一些朋友失之交臂的话，那对于我们这个每日碟评栏目来说，是个不可推卸的责任。所以，尽管以下文字仅仅是提供一个视觉概况和大意揣测，也显露出编辑作者的浅薄无知，我们还是做出一篇碟评，供大家参考批评。我是一位生活和内心充满痛苦的人。石榴的颜色，就是血的颜色，它带着利刃的创痛。我生活在一个富足的家庭，从小受到父母的无上宠爱。我从小就生活在严谨而温和的宗教氛围之内，在寺院中博览群书。我们民族的生活是多姿多彩的，女人们赤足清洗着地毯、男人们把线染成各种鲜艳的颜色，我们向骑白马的圣乔治顶礼致敬，通过浴室的窗户我见到了世界上最完美的乳房。我成长为一个苍白清俊的青年，学习音律的同时，我也在生命中第一次爱上了一个女孩，她是我一生的女神，我们在对方心里寻找着自我。在富饶美丽的生活中，我得到的只是痛苦。我们享受着宫廷一般的社交、游玩、骑猎，但内心是无限的空虚。我们为自己的爱寻找一个庇护所，但正相反，这是一条通向死亡谷之路。我怎么用蜡做成爱', '索菲柯·齐阿乌列里', '谢尔盖·帕拉杰诺夫', 8.7, 17133, 'tt0063555', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2239895233.jpg', 0.7, 1.3, 11.2, 37.7, 49.1, '0.200839,0.069192,-0.442433,1.144697,-0.258965,0.105618,0.764221,-0.003146,-0.410101,-0.138988,0.130922,0.709810,0.085636,0.187252,0.017121,-0.013517,-0.201037,-0.586640,-0.060390,-0.013481,-0.229895,-0.480152,-0.135124,-0.327285,-0.214481,-0.424839,0.771840,0.185602,-0.497824,0.084424,0.012498,0.127641,0.038072,0.158195,-0.262918,-0.391922,-0.183699,0.008544,-0.164818,-0.000102,0.093862,-0.112531,-0.111782,0.408640,-0.356017,0.251153,0.617052,-0.452630,-0.349595,0.152016,0.616908,-0.150067,-0.072352,0.207481,-0.134261,-0.011138,0.357689,0.236540,-0.002291,0.146917,0.022035,-0.164769,-1.183491,-0.273849,0.209161,0.266549,-0.387961,0.696653,-0.025665,-0.363236,0.046774,-0.370178,0.184751,-0.099058,0.436773,0.468475,-0.146281,-0.033727,-0.381421,0.359238,0.594106,0.176290,-0.585957,0.445510,-0.820113,-0.449578,-0.135022,-0.301863,-0.411939,0.112864,-0.052726,0.051887,-0.207754,0.063270,-0.787408,0.221711,0.186200,-0.473495,0.053487,-0.523558,0.045115,-0.501818,-0.294673,-0.761752,-0.345785,-0.139722,0.346863,-0.368780,1.140859,-0.744903,0.033982,0.381113,0.030598,-0.563450,0.920514,0.153019,-0.187418,-0.076635,-0.139511,0.320970,-0.095923,0.082466,-0.065959,0.479338,0.149991,0.088944,-0.460582,0.781542', '27602116', '4267948', '27666513', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303543', '玩乐时间', '喜剧', '来到巴黎办事的于勒先生（雅克·塔蒂 Jacques Tati饰）初入巴黎就被超级现代化的世界博览会大楼所震惊。于勒先生很快就迷失在这座叹为观止的高科技大楼中，精妙绝伦的最新先进设备、流光溢彩的博览会景观以及来自世界各地的游客和顾客，都让于勒先生大开眼界。当于勒先生终于想起要去找办事的人时，天已渐黑。谈完公事，于勒先生来到了刚刚装修好的夜总会。午夜魅影，恍如白昼，里面的男男女女兴致正高。自然，于勒先生也加入了他们的狂欢队伍。于勒先生更一时兴起，把刚刚装修好的屋顶装饰弄了下来，屋内一片狼藉。怎知客人们非但没有觉得扫兴，反而玩得更加疯狂。旦夕之间已是清晨，狂欢一夜后的巴黎别有一番韵味。由法国著名喜剧导演雅克·塔蒂自编自导自演的喜剧影片《玩乐时间》，用一种接近单色的色调和70毫米的巨大画卷，将钢筋玻璃世界的冷酷转化成格格不入的超现实影像。本片几乎没有对白，但巧妙的运用了音效，加上演员肢体动作的表现，有着较为浓厚的早期默片风格。', '雅克·塔蒂', '雅克·塔蒂', 8.8, 23417, 'tt0062136', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192795338.jpg', 0.5, 1.6, 9.8, 34.3, 53.7, '0.197608,-0.070148,-0.587722,0.463854,0.185317,-0.230011,0.782993,0.183481,-0.486683,-0.342076,0.148049,0.537617,-0.501702,0.089732,0.610466,-0.022212,-0.467004,-0.440298,-0.220507,-0.170099,-0.036882,-0.474331,-0.236506,-0.136625,0.054051,-0.329441,0.334312,0.185162,-0.228931,0.388384,0.002380,-0.134988,-0.019401,0.370998,-0.239503,-0.306824,0.101874,0.038104,-0.284526,0.021010,0.019495,-0.044159,-0.111799,0.125489,0.000847,0.075287,0.698100,-0.247962,-0.187409,0.227516,0.573835,0.089989,0.127927,0.058247,0.024991,0.150327,0.292145,0.021238,-0.320314,0.089181,0.078642,-0.283140,-0.593607,0.440084,0.255298,-0.069865,-0.074743,0.426506,-0.078919,-0.241265,-0.086153,-0.265781,0.364977,-0.070039,0.376440,0.587371,0.266697,0.038725,-0.375187,0.125693,0.438343,0.122708,-0.300789,0.447816,-0.286394,-0.289100,0.060217,-0.175433,-0.100383,-0.093730,0.258216,-0.034287,0.089542,0.038440,-0.778816,-0.043974,-0.114670,-0.351556,-0.164894,-0.281847,-0.155353,-0.887240,-0.111471,-0.283238,0.220689,-0.074481,0.285397,0.105211,0.555864,-0.646608,0.138867,0.176873,0.123047,0.035520,0.656828,-0.441141,-0.191899,0.105836,-0.277267,-0.065198,-0.004741,0.458756,0.175828,0.768127,0.023772,-0.439955,-0.435800,0.255935', '1394176', '10466639', '1297659', '19965431');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303555', '蔑视', '剧情', '保罗（米歇尔·皮寇利 Michel Piccoli 饰）与卡米尔（碧姬·芭铎 Brigitte Bardot 饰）是一对幸福的夫妻，保罗剧作家的工作也足以保证他们的衣食无忧。一次，制片人普罗可修（杰克·帕兰斯 Jack Palance 饰）邀请这对夫妻参加一个会谈，在会谈之中，面对着滔滔不绝的丈夫，卡米尔的心中第一次浮现出了一种名为“轻蔑”的可怕情感。随着时间的推移，这种情感非但没有减弱，反而越来越强烈，强烈到她已经无法再像以前那样的对丈夫施以深刻的爱意。同时，英俊帅气的普罗可修吸引了卡米尔的注意，两人越走越近。当奸情败露后，保罗大发雷霆，可卡米尔和普罗可修却毫不在意的驾驶着豪车扬长而去，哪知道，悲剧性的命运正在前方等待着他们。©豆瓣', '碧姬·芭铎', '让-吕克·戈达尔', 7.8, 8348, 'tt0057345', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2201081188.jpg', 0.7, 3.2, 27.2, 45.3, 23.7, '0.257681,0.008197,-0.885031,0.884098,0.068062,-0.269782,1.057792,0.208739,-0.376686,-0.019078,0.115196,0.668427,-0.454178,0.226045,0.338705,-0.122542,-0.161416,-0.572578,-0.192993,-0.201267,-0.036557,-0.501920,-0.460687,-0.075609,-0.202535,-0.225759,0.246846,0.120592,0.019574,0.717642,0.516991,0.196974,-0.037879,0.656401,0.001660,-0.075880,0.130702,0.050435,-0.209897,0.002992,0.427992,0.049529,-0.053528,0.224679,-0.174598,0.289259,0.496841,-0.418203,-0.287672,0.009091,0.426076,-0.151346,0.190577,0.317830,0.055520,0.036608,-0.029445,0.101970,-0.072371,-0.065183,0.008945,0.101992,-0.770173,0.276137,-0.304658,0.318097,-0.474683,0.356735,-0.118966,-0.326157,0.238391,-0.152904,0.129770,0.231494,0.100504,0.383069,-0.369175,0.048077,-0.419031,0.081204,0.571300,0.218567,-0.417941,0.437591,-0.536527,-0.220073,-0.254559,-0.255582,-0.699386,-0.254942,0.387953,0.388546,0.096790,0.243196,-0.197637,-0.079988,-0.281449,-0.117027,-0.022017,-0.463695,0.117608,-0.696386,-0.295528,-0.824902,-0.399208,0.229619,-0.010121,-0.205129,0.553460,-0.710344,0.316059,0.487533,0.425004,-0.245857,0.478965,0.380451,-0.056190,-0.177442,-0.465907,0.456783,-0.169799,0.166710,0.103198,0.541082,0.207865,0.005953,-0.171849,0.786596', '24756472', '1298442', '1417428', '24639908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303557', '维莉蒂安娜', '剧情', '长年在修女会中修行的维莉蒂安娜（Silvia Pinal 饰）即将立誓归宗，嬷嬷建议她在仪式前探望资助人叔叔海麦，维莉蒂安娜前往叔叔在乡间的大宅，岂料海麦因她酷似自己妻子而动情，维莉蒂安娜短暂停留后即将返回修女会，在动身的前夜，海麦央求她穿上了妻子的婚纱并向维莉蒂安娜求婚，被拒后指使女仆用药麻醉了她。第二天海麦自杀身亡，维莉蒂安娜返回大宅决定留下，海麦的私生子何塞（Francisco Rabal 饰）携女友也来到大宅，马上雇人重整荒芜田地，同时维莉蒂安娜邀请一些流浪汉与病乞共享大宅，维莉蒂安娜照顾他们的生活，带领他们虔诚祷告，试图为他们提供神的帮助。何塞的女友大感失落宣布分手，趁维莉蒂安娜与何塞进城的功夫，病乞和流浪汉们登堂入室，将大宅搞得一团混乱。本片是布努埃尔宗教三部曲的第二部，获1961年戛纳电影节金棕榈奖。©豆瓣', '西尔维娅·皮纳尔', '路易斯·布努埃尔', 8.6, 6247, 'tt0055601', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1531025433.jpg', 0.9, 0.7, 9.3, 44.4, 44.7, '0.085777,-0.041798,-0.444790,0.115517,0.067822,-0.306256,0.419538,0.464583,-0.384470,-0.274239,0.561634,0.844493,-0.117455,0.143811,0.499369,0.186301,-0.654867,-0.494769,0.119856,-0.135287,-0.128418,-0.190809,0.262953,-0.192112,0.027685,-0.565331,0.326727,-0.197721,0.173069,0.641784,0.113310,0.203943,-0.198077,0.248072,0.084234,0.332814,0.216749,-0.046959,-0.447236,0.160201,-0.171049,-0.152314,-0.108439,-0.067710,0.294356,0.354998,0.646292,-0.230909,0.033698,-0.233713,0.194772,-0.111620,0.122603,0.319486,-0.003155,-0.011728,0.361629,0.380828,-0.349890,0.109345,-0.121116,-0.218865,-0.238358,0.240249,0.217474,0.040562,-0.722737,0.408839,-0.130314,-0.077050,0.052746,-0.445730,0.061813,0.512687,-0.189225,0.421294,0.152162,0.044347,-0.424843,0.278293,0.495354,-0.150830,0.223254,0.202888,-0.131730,-0.111885,0.199675,0.031308,-0.556722,0.057969,0.368928,-0.006513,-0.154832,0.197313,-0.397533,-0.282707,-0.490239,-0.155138,0.245530,-0.348668,-0.196815,-0.761155,0.114163,0.128184,-0.034515,-0.248999,0.088085,0.019942,0.393856,-0.789908,0.380784,0.280229,0.627534,-0.439233,0.498334,-0.084366,0.192809,-0.222900,0.030476,0.412625,-0.049151,0.434535,0.126284,0.141028,0.004948,0.084354,-0.334685,0.226797', '1291992', '3036464', '11541282', '1292403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303559', '扒手', '剧情', '影片以日记的形式呈现。无所事事的年轻人米歇尔（马丁·拉萨尔 Martin LaSalle 饰）在赛马场目睹了一个小偷偷窃的全过程，他被小偷那自信优雅的手法所吸引遂即加入了偷窃的勾当。爱读书，坚持虚无主义哲学思想的米歇尔坚信偷窃是一种手指的芭蕾，一场完美的行窃就像一场精彩的行为艺术。米歇尔有一个久违的病重的母亲，在去探望的时候结识了一直照顾他母亲的邻居珍妮（玛莉卡·格林 Marika Green 饰），漂亮的珍妮唤醒了米歇尔心中沉睡已久的感情。米歇尔被警察盯住了，警长虽然三番五次的给了他改过自新的机会，但米歇尔依旧沉迷于他的“艺术”中无法自拔，很快，米歇尔被捕了。珍妮来狱中探望米歇尔，她向他袒露了自己的真情，米歇尔在泪水中猛然醒悟，当生命中还有所爱的人存在，生活就不会是一片虚无。©豆瓣', '马丁·拉萨尔', '罗伯特·布列松', 8.3, 18032, 'tt0053168', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1716876999.jpg', 0.3, 1.5, 14.7, 48.2, 35.2, '0.284185,0.025177,-0.675379,0.693068,-0.531593,-0.303971,0.995986,0.040047,-0.518104,-0.007275,0.390977,0.877906,-0.228946,0.313642,0.285870,0.304114,-0.254185,-0.798978,-0.213854,-0.042865,-0.198997,-0.306992,-0.444385,-0.274460,-0.009220,-0.313962,0.319484,0.078300,-0.280163,0.484102,0.155453,0.221829,0.065087,0.457864,-0.107344,0.017701,0.177972,-0.097870,-0.067034,0.100929,0.196696,-0.486202,-0.075776,0.374163,-0.343481,0.441934,0.673562,-0.228605,-0.020937,0.021799,0.325232,-0.352847,0.002661,0.308786,0.033349,-0.071003,-0.024376,0.021001,-0.253540,-0.016703,0.057949,0.006212,-0.878298,-0.134215,-0.076217,0.339470,-0.619222,0.611922,-0.083716,-0.108194,0.087936,-0.190712,0.160987,-0.070365,0.090274,0.383112,-0.064597,-0.069375,-0.397317,0.384294,0.569165,-0.056770,-0.203699,0.504741,-0.455082,-0.347381,0.194496,-0.196316,-0.505884,-0.114521,0.591240,-0.121627,-0.377037,0.198959,-0.540630,-0.208093,-0.387627,-0.122746,-0.254475,-0.381794,-0.176024,-0.409545,-0.289388,-0.430546,-0.314562,0.046413,-0.096666,-0.306567,0.750669,-0.810210,0.390730,0.820146,0.049519,-0.336229,0.744663,0.188797,-0.134371,-0.083640,-0.041005,0.276832,0.047015,0.300430,0.162782,0.503961,0.221552,0.002721,-0.450647,0.835386', '35158375', '30162520', '1309172', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303562', '死囚越狱', '剧情', '本片取材于真人真事。故事讲述被判死刑的男主人公弗朗西斯(弗朗索瓦·莱特瑞尔 François Leterrier饰)在临刑前的几个小时内，如何成功越狱地扣人心弦的故事。为逃脱纳粹监狱，弗朗西斯策划了一场天衣无缝的逃亡计划。为确保计划万无一失，他不仅做足越狱准备，还在仅有的洗漱空挡，多次跟隔壁囚室的狱友联络，试图找到共同实施计划的同盟。可还没来得及他准备好一切时，就被判立刻执行死刑。最终他毅然带着年轻的囚犯男孩一起踏上了逃亡之路。极简的叙事结构，单一密闭的监狱空间，分秒必争的紧迫时间，罗伯特·布列松因本片荣获第10届戛纳电影节(1957)最佳导演奖。©豆瓣', '弗朗索瓦·莱特瑞尔', '罗伯特·布列松', 8.5, 17179, 'tt0049902', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1714790575.jpg', 0.5, 1.2, 12.6, 44.3, 41.5, '-0.176247,0.003227,-0.616440,0.504283,0.091244,-0.387460,0.357952,0.050857,-0.232640,-0.256800,0.168473,0.425447,-0.303778,-0.184644,0.390128,-0.214254,-0.916755,-0.787841,-0.301735,-0.094372,-0.344364,-0.504512,-0.087372,-0.158067,-0.084058,-0.276003,0.680247,0.223683,0.126000,0.065272,0.332031,-0.046752,-0.336195,0.222025,-0.135649,0.055836,0.377172,-0.224237,-0.615728,0.290490,0.149367,-0.189410,-0.289387,-0.011405,0.007590,0.531429,0.736131,-0.223013,-0.067915,0.139680,0.550082,-0.302514,-0.127362,0.102976,0.314452,0.061967,0.143692,0.429758,-0.048312,0.038769,0.007384,-0.402855,-0.745833,-0.079895,0.092035,-0.111073,-0.251902,0.122311,-0.092469,0.440636,0.249715,-0.216213,-0.194167,0.454671,0.602447,0.260749,-0.070156,0.103987,-0.374316,0.277490,0.461714,-0.110299,-0.241701,0.307877,0.199973,-0.570915,-0.016121,-0.046558,-0.179733,-0.090017,0.435047,0.018989,-0.208227,-0.124957,-0.310087,-0.136945,-0.482519,-0.139377,0.000601,-0.247555,-0.048352,-0.938937,0.067069,0.209588,-0.245342,0.204293,0.012298,-0.156733,0.240243,-0.363921,0.310495,0.539750,0.040247,-0.364230,0.423898,0.221896,0.382124,-0.153837,0.062769,-0.023045,-0.121963,0.457296,0.308950,0.456430,-0.104957,-0.190366,-0.669799,0.273732', '1298616', '2028645', '1293572', '2075345');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303571', '骗子', '剧情', '奥古斯特带领的三个骗子化装成传教士到处行骗，屡屡得手。一次他在街头偶遇自己天真烂漫的女儿，心里不禁有所顿悟，但却被人当场认出是骗子，并在女儿面前给人逮送到警局。出狱后的奥古斯特重操旧业，但在为筹集女儿学费的一次行骗中，他想独吞财物而被同伙痛殴，最终死在山崖边。', '布罗德里克·克劳福德', '费德里科·费里尼', 8.1, 6977, 'tt0047876', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528209564.jpg', 0.3, 0.8, 16.9, 59.3, 22.7, '0.045564,-0.064887,-0.934634,0.519139,-0.496717,-0.552735,0.689152,-0.157388,-0.742469,-0.031750,0.202244,0.901359,-0.284130,0.416930,0.257211,0.082149,-0.084294,-0.655879,0.209513,-0.202447,-0.362412,-0.357258,-0.118206,-0.375810,-0.240170,-0.117575,0.430978,0.311950,0.095824,0.370603,0.450025,0.183723,-0.065852,0.425672,-0.563885,0.217855,-0.056880,-0.358031,0.004744,0.296632,-0.065886,-0.519951,-0.451597,-0.018938,-0.132689,0.412346,0.750335,0.014381,-0.124624,-0.082143,0.143157,-0.641853,-0.172571,0.102964,0.283940,-0.210148,0.378322,-0.060763,-0.285193,-0.020357,0.412544,0.060140,-0.440571,0.050167,-0.056121,-0.155240,-0.808464,0.344859,-0.008894,0.192208,-0.071930,-0.176515,0.220352,0.067132,0.250669,0.336469,-0.231788,-0.209287,-0.945787,0.035422,0.552799,-0.056191,0.306585,0.177518,0.115475,-0.108881,0.441551,-0.421329,-0.113405,0.195032,0.288112,-0.147540,-0.600981,-0.060531,-0.296545,-0.149820,-0.532064,0.121498,-0.137338,-0.731804,-0.398667,-0.226614,-0.072122,0.111587,-0.360435,0.206170,0.126966,-0.263476,0.159352,-0.685207,0.113584,0.659308,0.139339,-0.699507,0.489650,0.181126,-0.038670,0.098321,-0.299251,-0.141513,0.717276,0.388489,0.328581,0.040243,-0.182667,-0.174603,-0.218623,0.228589', '1292584', '1300359', '1293908', '1309125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303577', '雨月物语', '剧情', '战国时代，琵琶湖附近的一个小山村里住着源十郎（森雅之饰）和妻子宫木（田中绢代饰），还有妹夫藤兵卫（小泽荣饰）、妹妹阿滨（水户光子）。他们以开小瓷窑、烧制瓷器为生，战乱中，源十郎想趁着战乱发一笔横财，而藤兵卫则想着成为一名武士，出人头地。二人带着烧制好的上好瓷器离开家乡去市镇变卖，果然赚到一大笔钱，源十郎甚至碰上了一位美若天仙的贵族小姐若狭（京町子饰），雨云之欢，乐不思蜀。一天晚归的源十郎被一僧人告知是否遇见什么不干净的东西……。而藤兵卫也如愿以偿地成为了武士，撞大运碰上美事，好不威风，但他居然在寻欢之时遇见了妻子……，骇人的事实摆在了他们的面前。©豆瓣', '田中绢代', '沟口健二', 8.6, 23187, 'tt0046478', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2439235403.jpg', 0.2, 0.5, 9.3, 47.3, 42.7, '0.260320,-0.011894,-0.596505,0.365899,-0.188656,-0.413007,0.665191,0.036250,-0.154302,-0.359421,0.256373,0.835681,-0.085893,0.269127,0.285560,0.276461,-0.051754,-0.301382,0.110815,-0.249819,-0.198182,-0.225814,-0.319175,0.098833,-0.270624,-0.042857,0.349828,0.212565,0.170829,0.291074,-0.010655,-0.171728,-0.140994,0.375526,-0.494271,0.029329,0.038775,0.187307,-0.131842,0.335811,-0.131494,-0.306344,-0.212928,-0.236331,0.096994,0.044547,0.444813,-0.231866,-0.010057,-0.075112,0.098412,-0.082066,-0.040872,0.291174,0.114211,-0.122066,0.345300,-0.137824,-0.382312,-0.063187,0.234282,-0.169400,-0.261953,-0.019203,0.090311,0.049366,-0.689392,0.399402,-0.026595,-0.220360,-0.093459,-0.493209,0.334998,0.339397,0.173661,0.364293,-0.251943,0.243237,-0.932508,0.164938,0.718122,0.120497,0.038471,0.136749,0.328858,-0.320418,0.325319,-0.354931,-0.458302,0.039414,0.284138,-0.222226,-0.223229,-0.054790,-0.705437,0.034352,-0.293998,-0.039573,0.123139,-0.010464,-0.332368,-0.178733,0.078091,-0.276428,-0.543633,0.312475,0.462647,-0.300326,0.680329,-0.480629,0.056407,0.483604,0.392570,-0.317540,0.564773,-0.154182,0.089576,0.175892,-0.354995,-0.377595,0.070928,0.347133,0.410747,0.294112,-0.333007,-0.314939,-0.039376,0.232730', '1309101', '1306505', '26678509', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303588', '爷儿俩开歌厅', '喜剧', '老奎（陈强 饰）和儿子二子（陈佩斯 饰）在深圳闯荡一番后，回到了北京。见多识广的父子俩决定在北京创业，老奎倾尽积蓄开办了一家卡拉OK厅，并请来他们在车站结识的来京闯荡的小歌手小依（傅艺伟 饰）。卡拉OK厅生意火爆，父子俩渐渐有了钱。二子爱上了小依，小依一方面和二子约会，一方面又傍着老奎给她买这买那，另一方面又和另外一个台湾大款纠葛不清，周旋在三个男人中间……©豆瓣', '陈佩斯', '陈佩斯', 7.1, 5787, 'tt0352000', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230016766.jpg', 0.5, 3.7, 47.1, 36.8, 11.8, '0.149781,-0.034892,-0.740112,0.492967,0.056660,-0.558806,0.441965,0.586755,-0.333931,-0.115484,0.006445,0.768370,0.017296,0.509786,0.339935,-0.066563,-0.477143,-0.223916,0.063504,-0.238665,-0.038504,-0.406891,-0.181814,-0.048822,-0.031500,0.143080,0.158742,-0.131047,-0.134204,0.528649,0.662764,-0.063627,-0.301458,0.082940,-0.377230,0.218098,-0.111515,0.310960,-0.351648,-0.012060,-0.091421,-0.215245,-0.269342,-0.412319,0.576846,0.369810,0.586901,0.203482,0.153115,0.024703,0.109152,0.032658,-0.128809,-0.090905,0.045929,0.153343,0.442581,0.174894,-0.441131,-0.197792,0.041071,-0.162211,-0.341715,0.234425,0.014189,-0.134807,-0.908600,0.528671,0.097615,-0.293855,-0.034311,-0.332240,-0.046849,0.606988,-0.209986,0.406159,0.053641,0.061579,-0.611036,0.387747,0.699303,0.085698,0.381120,0.226956,0.367660,-0.265438,0.092652,-0.185411,-0.355448,-0.312281,0.483072,-0.368560,-0.151273,-0.117821,-0.581968,0.145859,0.029008,-0.175837,0.421635,-0.218407,0.034099,-0.711929,-0.284442,-0.456885,-0.278924,0.072210,0.308346,-0.041505,0.661482,-0.750599,-0.086606,0.464641,0.466514,-0.692458,0.794906,-0.045775,0.297863,-0.342327,-0.169186,-0.326713,0.017271,0.330407,0.392405,0.463056,-0.266381,-0.204108,-0.604907,0.155596', '1308035', '1926007', '1306209', '6858739');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303590', '玻璃之城', '剧情', '在1997年的除夕夜，英国伦敦的人们都在准备迎接新年的到来，为新年的到来欢呼庆祝。此时一辆汽车失事撞毁了，港生（黎明 饰）和韵文（舒淇 饰）是车上的一对中年男女，他们在人们的欢呼声中逝去。经调查发现，原来他们是一对偷情的爱侣，由于各自都有家室，家中亲人大怒，只派了他们各 人的儿子及女儿处理后事。刚开始这两个年轻人都认为对方的父母破坏了自己的家庭幸福，各有怨恨。当他们翻查警方交给他们有关父母的资料的时候，才从照片、书信、日记等东西中，看到了他们父母当年美好的爱情故事……©豆瓣', '黎明', '张婉婷', 7.9, 66227, 'tt0179110', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p791235992.jpg', 0.3, 2, 25.9, 46.2, 25.6, '0.385338,-0.304798,-0.765808,0.271353,-0.108055,-0.235676,0.670576,0.085823,-0.612884,-0.323467,0.446737,0.745084,-0.222487,0.502048,0.331373,-0.094566,-0.634645,-0.870049,-0.021654,-0.284580,-0.423841,-0.188449,-0.043775,-0.261897,0.060044,-0.220363,0.227817,0.045280,0.230752,0.599580,0.267281,-0.113916,-0.321946,0.440132,-0.234102,0.157310,0.116038,0.190146,-0.328513,-0.169875,-0.339744,-0.376210,-0.176466,0.137961,-0.101681,0.546143,0.836842,-0.115465,-0.124969,-0.040088,0.203866,-0.123546,0.017497,0.306845,0.459064,0.149523,0.158566,0.308671,-0.304037,-0.168126,-0.265485,0.166638,-0.656944,0.044810,0.018123,0.194656,-0.451553,0.593185,-0.083241,0.112728,0.223885,-0.338971,0.660893,0.491142,-0.090261,0.693989,-0.085839,-0.165727,-0.511924,0.435782,0.771673,-0.157961,0.233080,0.311384,-0.319917,-0.380359,0.040872,0.163313,-0.561207,0.015324,0.530378,0.249115,-0.158408,0.219709,-0.486669,0.046546,-0.003301,-0.402214,0.114118,-0.492333,-0.181244,-0.785837,-0.184890,-0.466056,-0.352821,0.261620,0.175266,-0.046136,1.068276,-0.494684,0.172949,0.190281,0.083639,-0.760230,0.816965,0.063468,0.143796,-0.196642,0.004790,-0.157920,0.176110,0.209300,-0.054494,0.175332,-0.031071,-0.033399,-0.423710,0.413709', '3811356', '30162520', '1306860', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303603', '西鹤一代女', '剧情', '夜幕下，年过五旬的妓女阿春（田中绢代 饰）在街头游荡，走进一个寺庙后，她回想起自己坎坷悲惨的前半生。年轻时的阿春是一个贵族家里的女佣。她与下等武士胜之介相恋，二人偷情时被发现。阿春连同她父母被驱逐出城，胜之介则被处死。松平大领主为了继承香火，派人四处选妾。貌美的阿春被选中，做了松平领主的妾侍。很快，她产下一子。松平家族欢天喜地，阿春以为自己就此安定下来。可是原配十分嫉妒阿春，于是松平家族以阿春迷惑领主为由，将她遣返回家。为了偿还债务，阿春的父亲把她卖去妓院。一个出手阔绰的客人看中了阿春，要为她赎身。然而此人是个专门造假币的骗子，随即就被抓走，阿春也被妓院赶走。其后阿春经历了种种波折，她最终走投无路，只好沦落街头。贫病交加之际，她得知自己的儿子当上了领主……©豆瓣', '田中绢代', '沟口健二', 8.3, 6429, 'tt0045112', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2154438018.jpg', 0.3, 1.1, 13.5, 52.9, 32.2, '0.226651,0.333896,-0.478423,0.296926,-0.343991,-0.393928,0.700160,0.044749,-0.472204,-0.448538,0.326852,1.089137,-0.094289,0.452740,0.356727,0.175371,-0.044295,-0.500695,-0.142947,-0.323685,-0.098995,-0.106133,0.217105,-0.126991,-0.263445,-0.168268,0.297647,0.132043,0.111092,0.287869,0.258868,0.400436,-0.001586,0.359607,-0.261550,0.529590,-0.013337,-0.221376,0.078903,0.284570,-0.201905,-0.398961,-0.079178,-0.116400,-0.075118,0.320029,0.682520,-0.265720,-0.028466,-0.437422,0.187445,-0.193769,-0.067654,0.359486,0.294182,-0.090459,-0.012343,0.235190,-0.476903,-0.185201,0.211679,-0.051431,-0.566715,0.216703,0.195113,-0.171443,-0.821179,0.248112,-0.113669,0.135078,-0.043737,-0.250342,0.292569,0.288282,0.120984,0.244441,-0.325189,0.100758,-0.540149,0.481989,0.864390,-0.089032,0.161936,0.033061,-0.106402,-0.263249,0.514406,-0.558434,-0.458024,0.016282,0.498967,-0.006027,-0.240988,0.140194,-0.402036,-0.501817,-0.553649,-0.047228,0.139577,-0.459836,-0.267453,-0.086169,-0.052709,-0.043249,-0.364983,0.083757,0.182046,-0.155902,0.539303,-0.604964,0.160230,0.531238,0.480948,-0.752137,0.554109,-0.335747,0.211047,0.143696,-0.046806,-0.017216,0.346810,0.444150,0.304542,0.157294,-0.318267,-0.208204,-0.252377,0.127822', '1309069', '1308035', '1292584', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303624', '蓝色青春', '剧情', '男子高中——朝日高校，是一所不良少年云集的学校。这些正处在躁动青春期的男孩们仿佛看不到未来的方向，他们通过拳头征服对手，向顶点进发，以此证明着自己存在的意义。不过，这里的学生却发明了新的决定老大的方式：自认有实力的挑战者一字排开，站在顶楼露台的栏杆外，随着号令松开握着栏杆的手同时双手击掌，击掌次数最多且没有摔下楼的便可称为朝日高校的老大。经过一番惊险角逐，三年级新生九条（松田龙平 饰）以8连击的佳绩成功问鼎。新学期伊始，九条以及青木（新井浩文 饰）、雪男（高岡蒼佑 饰）、木村（大柴裕介 饰）、吉村（忍成修吾 饰）等一众三年级学生开始经历理想向现实的残酷转变，他们自愿或被迫选择前进的方向，并为着残酷的青春付出血淋淋的代价……本片根据漫画家松本大洋同名短篇原著改编。©豆瓣', '松田龙平', '丰田利晃', 7.9, 8019, 'tt0309291', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p981530157.jpg', 0.8, 3.1, 25.1, 43.1, 27.9, '0.113780,0.004478,-0.454606,0.553564,0.052324,-0.042612,0.645981,0.221706,-0.199079,0.016689,0.448533,0.313887,-0.094063,0.294498,0.380616,-0.174251,-0.091668,-0.836372,-0.251756,-0.095350,-0.304341,-0.268850,-0.074588,-0.022724,-0.254470,-0.148454,0.974025,-0.007012,-0.158596,0.611496,0.423532,0.078327,-0.014152,-0.023778,-0.191102,-0.218011,0.051192,0.078003,-0.354786,0.213696,-0.136939,-0.249410,-0.392443,0.040380,-0.075803,0.299988,0.688097,-0.319002,0.090328,-0.071201,0.391426,-0.181630,-0.085495,0.220260,0.447634,0.206519,0.102810,-0.003973,0.200573,0.152441,0.049558,-0.253335,-0.490367,-0.156793,0.073757,0.228207,-0.446232,0.643323,-0.087279,-0.179547,0.296386,-0.243437,-0.314813,0.147627,0.274365,0.145082,-0.349299,0.018311,-0.105292,0.044901,0.598548,0.005024,-0.291973,0.122588,-0.167051,-0.404292,-0.356316,-0.176739,-0.302991,-0.180025,0.330229,0.305077,0.074813,0.063413,-0.316907,0.178339,0.021317,-0.324302,0.206247,-0.153566,-0.168561,-0.694567,0.130310,-0.250467,-0.073759,0.123134,-0.033702,-0.376019,0.856195,-0.681899,-0.126049,0.416931,0.360539,-0.125228,0.620691,0.035864,0.095102,-0.130287,-0.226962,0.200123,-0.191036,0.504763,-0.003642,0.443873,-0.164044,-0.231037,-0.326900,0.530041', '1826173', '4202326', '3811356', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303630', '金鸡', '剧情', '老妓女金如（吴君如 饰）在自助银行里遇到了小偷（曾志伟 饰）打劫，怎料突然停电，两人都被锁在里面，阿金开始向小偷说起了她与香港一起成长的故事。她16岁开始当“鱼蛋妹”，当时已经月入数千，后来成年后就正式成为了舞小姐，可是她没有出色的容貌，也只能在夜总会里担演丑角。可是仍为她带来了十分丰厚的收入，却不一小心怀上了不知是那位客人的孩子，为了生活，阿金只好把帐认到了另一位客人头上，客人也把儿子带到了美国。经济不景，接着她只好做按摩女郎，继续做着老本行，她看到了很多，也感受到了很多。©豆瓣', '吴君如', '赵良骏', 8.1, 62886, 'tt0354593', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2874356325.jpg', 0.4, 2, 18.9, 49.5, 29.2, '0.313462,0.081009,-0.593838,0.310761,-0.454575,-0.412712,0.682103,0.179244,-0.471735,-0.087545,0.158673,0.763716,-0.123092,0.587179,0.153421,0.157354,-0.261746,-0.575406,-0.091414,-0.191710,-0.364064,-0.163154,-0.136429,0.009449,-0.357461,-0.007414,0.115773,-0.161483,-0.096558,0.165353,0.406416,-0.059706,0.026618,0.536662,-0.464879,0.253425,0.196842,0.033473,0.163402,0.263931,0.068726,-0.651165,-0.146548,0.069146,0.287854,0.394379,0.623933,-0.202844,-0.104195,-0.047123,0.276039,0.038725,-0.116480,0.069051,0.269697,0.135742,0.399501,-0.007541,-0.328030,-0.104751,0.072788,-0.154874,-0.406154,0.279831,-0.002541,0.121429,-0.759959,0.277075,-0.238489,-0.111513,0.051751,-0.438824,0.267033,0.099265,0.107684,0.297841,-0.163767,-0.058506,-0.719116,0.377044,0.733227,0.090110,-0.005715,0.400086,0.071129,-0.416013,0.178064,-0.188529,-0.196964,0.035393,0.233413,0.025613,-0.222665,0.050611,-0.489757,0.158712,-0.164178,-0.361462,0.017925,-0.303202,-0.053571,-0.275005,-0.070912,-0.416367,-0.312741,0.100957,0.213698,-0.059476,0.790321,-0.743754,0.036165,0.538290,0.448601,-0.389477,0.751198,-0.187551,0.190111,0.152575,0.131539,-0.341075,-0.055752,0.359723,0.472654,0.587252,-0.087335,-0.303416,-0.183626,0.456922', '1783772', '3055049', '30162520', '5262027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303637', '红柿子', '剧情', '从大陆撤到台湾的一批将士及其亲属中，有一个来自河南的大家庭。除了将军的跟班福顺和姥姥（陶述 饰）中意的那副齐白石的柿子图意外走散，家里人口总算齐全的到达了台湾。换了一个新地方，姥姥各种不适应，被将军女婿（石隽 饰）许诺不久就能重返老家。但随着时间的推移，这个问题很少再被提及。横在一家人面前的是生活的难题。家里小孩众多，物资匮乏，但点子颇多的姥姥常常化腐朽为神奇。像是把女婿照的X光片裁成多份做写字板；跟教堂的修女弄好关系得到面粉牛奶；把女婿的锦旗做成孩子们校运会的旗帜等，过程中惹出不少笑话。而没了官职的将军则和妻子倒弄起养殖业，鸡鸭青蛙鱼轮番上阵，还卖过铅笔，但都没能赚到钱。日子就这么平平淡淡过去，孙辈渐渐长大，而福顺（赵正平 饰）意外地和这家人再次相遇，带来了姥姥的那副柿子图及那份不曾离去的乡愁。©豆瓣', '陶述', '王童', 8.9, 7141, 'tt0116558', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2587213240.jpg', 0.2, 0.5, 6, 39.4, 53.8, '0.271622,-0.109257,-0.409167,0.422915,-0.228265,-0.314446,0.518202,0.314361,-0.467196,-0.102325,-0.140301,0.551878,-0.054693,0.121838,0.136509,-0.085060,-0.235286,-0.472709,0.082232,-0.283155,-0.264507,-0.280159,-0.180459,-0.115775,-0.250913,-0.182656,0.334520,-0.007772,0.156491,0.319958,0.051973,-0.191440,0.023165,0.403277,-0.508496,0.382195,-0.052532,0.266488,-0.054208,0.112830,0.084607,-0.144704,-0.070459,0.130312,0.415840,0.211311,0.715827,-0.109193,-0.182388,-0.032783,0.158045,0.126955,-0.005923,0.060719,0.355204,0.136037,0.311950,-0.027245,-0.265487,0.025741,0.107691,-0.079982,-0.381262,0.071777,0.171538,0.018831,-0.810971,0.378661,0.046389,-0.166305,-0.178732,-0.378321,0.604347,0.435351,0.159259,0.530294,-0.162410,0.089767,-0.787195,0.443901,0.408613,-0.066605,-0.070779,0.184084,-0.173832,-0.271796,0.194922,-0.424047,-0.231736,0.191073,0.198685,-0.085529,-0.131580,0.088835,-0.662395,0.165479,-0.146604,-0.358136,0.209141,-0.294676,-0.215137,-0.290390,0.066095,-0.313233,-0.222635,0.223605,0.322654,-0.027616,0.872345,-0.338449,0.070626,0.139472,0.281322,-0.389732,0.550949,0.042124,0.182208,-0.169336,-0.072039,-0.392987,0.182055,0.297184,0.516899,0.369276,-0.131211,-0.456330,-0.121467,0.373447', '1306505', '1302661', '25731805', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303638', '都市情缘', '剧情', '梁智武（黎明饰）早年丧母，由父亲（吴孟达饰）一手带大。父亲一次带他回家时，买了块糕点被别人抢去，为了息事宁人，胆小的父亲竟默认是小武抢了别人的马拉糕。这成为少年心上永远无法愈合的伤口，和父亲的关系从此裂痕难补。学校里，小武常常受人嘲笑，没有人去真正关心他。小武最终早早成了少年犯。出狱后，成天沉溺赌博，父亲对他灰了心。有人介绍小武跟威哥（陈浩民饰）混，小武对威哥女友Jojo（吴倩莲饰）一见钟情，当晚便拉着Jojo出去，不料却被追来的威哥一群人打了一顿。不死心的小武继续约会Jojo，当晚在楼梯上等人的他竟莫名其妙地卷入谋杀案中，又以“袭警”罪名遭到非人虐待，奋力逃出后，他所想的只是在码头上再见Jojo一面，岂料迎来的却是警察……©豆瓣', '黎明', '刘镇伟', 8.2, 6852, 'tt0109692', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2352136430.jpg', 0.4, 1.7, 19.2, 42.8, 35.8, '0.241671,0.094986,-0.569758,0.286242,-0.304272,-0.337891,0.679715,0.241320,-0.578519,0.086621,0.083787,0.747271,-0.273685,0.288151,-0.020627,0.130666,-0.303099,-0.600563,0.223023,-0.071229,-0.413177,-0.129296,-0.018157,-0.131791,-0.244834,0.093447,0.156763,-0.005299,-0.117872,0.559537,0.396926,0.086386,-0.102079,0.663223,-0.326541,0.368443,-0.154223,0.033292,-0.120188,0.104028,0.244636,-0.377656,-0.109814,0.102385,-0.029821,0.340357,0.479063,-0.028382,0.131653,-0.299837,0.039273,-0.269285,-0.066124,0.263342,0.190062,0.112978,0.325757,0.069810,-0.244057,-0.056247,0.218369,-0.072860,-0.296686,0.024140,-0.090746,-0.056793,-0.598315,0.438450,-0.111044,0.160724,0.113947,-0.277594,0.177192,0.049869,0.156075,0.267735,-0.130773,-0.030605,-0.402941,0.189839,0.660479,-0.084863,0.330404,0.227831,0.056630,0.028640,0.201503,-0.288635,-0.242729,0.033158,0.450421,-0.048431,-0.437210,-0.099183,-0.391993,-0.105528,-0.297926,0.041235,-0.048077,-0.421151,-0.244144,-0.085663,0.069272,-0.377756,-0.324919,0.240961,-0.113720,-0.065833,0.250967,-0.596610,0.379830,0.386297,0.379920,-0.565828,0.473053,0.176875,0.024670,-0.047461,0.041091,0.052449,0.248507,0.337439,0.392797,0.209817,0.047124,-0.037404,-0.147234,0.196877', '1308755', '3111650', '1293142', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303654', '杀人短片', '剧情', 'Jacek Lazar（米罗斯洛·巴卡 Miroslaw Baka 饰）是一个二十一岁的男子，他在街上游荡，吓走广场上的鸽子，在天桥上朝底下的汽车扔石头，在照相店让人将他口袋里那张已经出现了折痕的照片放大，是一个小女孩的照片。Waldemar Rekowski（Jan Tesarz 饰）是一个普通的的士司机，调戏年轻女子，捉弄乘客，故意按喇叭惊吓动物，他的下一个乘客是Jacek。Piotr Balicki（Krzysztof Globisz 饰）是一个年轻的律师，认为刑罚并不能防止犯罪，而防止犯罪正是法律的目的，他刚刚通过律师考试，他为杀人犯Jacek辩护。Jacek坐上了Waldemar的的士，他们开车到野外，Jacek用一条绳子勒死了司机。Balicki极力为Jacek辩护，希望避免死刑，但Jacek最后还是被判处了死刑。临终前，Jacek和Balicki长谈，说起因为他和一个卡车司机喝酒，致使卡车司机开车碾死他妹妹的事情......', '米罗斯洛·巴卡', '克日什托夫·基耶斯洛夫斯基', 8.3, 13518, 'tt0095468', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497615647.jpg', 0.6, 1.8, 15.6, 44.5, 37.5, '0.480432,-0.017968,-0.201073,0.722984,-0.558649,-0.167254,1.023874,0.311075,-0.163053,-0.035907,0.581542,0.742446,-0.138234,0.435604,0.297079,0.272888,-0.157959,-0.632439,-0.042522,0.041392,-0.593346,-0.573059,-0.047957,-0.249497,-0.001671,-0.148550,0.322009,-0.024570,-0.267473,0.416149,0.403734,-0.161338,-0.106133,0.470537,-0.426582,-0.229232,-0.098851,-0.131338,0.221660,-0.037738,-0.150253,-0.732190,0.223003,0.124408,-0.146669,0.575460,0.570498,-0.093765,-0.145237,0.094983,0.298497,-0.512936,0.106599,0.074425,0.317564,-0.111835,0.240125,-0.131237,-0.165540,0.029116,0.248597,0.212528,-0.529737,-0.042263,-0.382943,0.046742,-0.701357,0.493044,-0.315363,0.238590,0.036743,-0.198921,0.447133,-0.112459,0.075029,0.231231,-0.148649,-0.136540,-0.698547,0.082069,0.328976,-0.016264,0.061533,0.329648,-0.401535,-0.285177,0.086944,-0.005582,-0.442878,-0.234024,0.459433,-0.533559,-0.488956,-0.335064,-0.377418,-0.146067,-0.428447,-0.232545,-0.207188,-0.261322,-0.258483,-0.228268,0.191738,-0.214769,-0.271084,0.217343,0.103273,-0.280071,0.545425,-0.417665,0.011700,0.763777,0.257605,-0.447975,0.910030,0.025820,0.028523,-0.063672,-0.016883,-0.086748,0.343864,0.544816,0.020117,0.455698,-0.176361,-0.129507,-0.531561,0.420665', '1783772', '1298134', '1578663', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303674', '干柴烈火', '剧情', 'Alice（杨千嬅 饰）虽然其貌不扬，但是心地善良，家中四代都是开设跌打馆，身为记者的她也精通中医术。因为她效力的杂志《淑女》，被《绅士》杂志收购了，继而她认识了该杂志的副主编Ryan（古天乐 饰）。Ryan看上去英俊潇洒，但实际上身体虚弱。两人刚开始有些误会，当误会冰释后两人成为了朋友。Alice也暗暗喜欢上了Ryan，毫不知情的Ryan告诉Alice自己对名作家Michelle（陈慧珊 饰）一见钟情。身为Michelle忠实读者的Alice开始帮助Ryan追求梦中情人，而Alice只好默默守在Rayn的身边……©豆瓣', '古天乐', '叶伟信', 6.5, 24596, 'tt0346909', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2358120196.jpg', 1.2, 9.2, 58.1, 24.3, 7.2, '0.484031,0.078435,-0.385302,0.468772,-0.033189,-0.041443,0.451044,0.060560,-0.497082,-0.338818,0.072649,0.891891,-0.068133,0.441577,0.122702,0.103310,-0.060565,-0.626462,-0.046869,-0.120941,-0.146340,-0.417513,-0.200645,-0.207486,-0.441746,-0.217087,0.407568,0.146161,-0.070149,0.571492,0.658297,0.284512,0.263387,0.430916,-0.138715,-0.024895,0.106812,-0.019719,0.005871,0.077934,0.045197,-0.367777,0.124533,0.325916,0.107260,0.386212,0.412073,0.023589,-0.378641,-0.114156,0.516469,-0.166192,0.183790,0.145684,0.385987,0.354656,0.454859,0.039009,-0.077246,0.027647,-0.116347,-0.009062,-0.532521,-0.112862,0.512668,0.127692,-0.752111,0.485465,-0.122270,-0.265828,-0.092826,-0.222795,0.323155,-0.002232,0.400266,0.127294,0.167523,0.117616,-0.376459,0.218042,0.358444,0.453328,-0.161114,0.565359,-0.248067,-0.362913,0.109350,-0.283270,-0.405370,0.013926,-0.355896,0.238853,0.048070,-0.038112,-0.275934,0.139079,0.004366,0.065515,-0.019688,-0.660409,0.041231,-0.263005,-0.161060,-0.584304,-0.226998,-0.285537,-0.058318,-0.460666,1.026078,-0.926386,0.075112,0.339776,0.369088,-0.678307,0.899270,0.432555,-0.112876,0.048448,-0.198956,0.184856,0.044184,0.005700,-0.113228,0.250302,0.167280,-0.552137,-0.249239,0.212948', '35048413', '6963575', '1292720', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303676', '猛鬼大厦', '喜剧', '易办事（楼南光 饰）与新婚妻子（吴君如 饰）自泰国蜜月返回，适逢阿信警司（胡枫 饰）为侦破一起伪钞案，令易妻与两名女警（柏安妮&关秀媚 饰）连同外甥女小敏（张敏 饰）组成卧底队伍，与香港嫌犯大傻（成奎安 饰）在枫林大厦接洽。当夜枫林大厦颇为热闹，一位僧人做法收鬼，将肆虐大厦的群鬼一一收复封印，却不料一只女鬼半路逃逸。而误会妻子与阿信偷情的易办事亦气势汹汹的赶到枫林“捉奸”。女鬼在大厦内四处游弋，寻找机会释放群鬼，令易办事等人魂飞魄散，连累前来谈判的大傻一同被猛鬼缠身。高僧返回枫林收拾残局，于是一场人鬼之间的无厘头对决在深夜中的大厦上演……©豆瓣', '吴君如', '刘镇伟', 6.9, 8565, 'tt0093523', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2255620099.jpg', 1, 7.4, 50.7, 28.9, 11.9, '0.133910,-0.294584,-0.521990,0.170023,0.240416,0.082417,0.583010,0.436537,-0.375731,-0.277672,0.465318,0.449167,-0.453755,0.159840,0.529019,-0.188524,0.004334,-0.428185,-0.229774,-0.050753,-0.046740,-0.196106,-0.102916,0.021379,0.082827,-0.019140,0.329525,0.193408,-0.100862,0.545588,0.457245,0.233252,-0.916135,0.178623,-0.048989,-0.128991,0.222299,0.154783,-0.160424,0.250583,-0.371196,-0.215911,-0.190923,-0.340025,-0.036885,0.044492,0.702262,-0.173293,-0.020067,-0.300626,0.216900,-0.290358,0.225256,0.124589,0.338741,-0.014430,0.262776,0.127841,-0.402416,-0.074187,0.107336,-0.292024,-0.214872,0.509653,0.166825,-0.024746,-0.399796,0.115996,0.056384,0.106743,0.138478,-0.110024,0.262222,0.445100,0.279010,0.249711,0.100956,-0.028523,-0.447281,0.091597,0.486557,0.022287,0.287718,-0.012760,0.358122,-0.085381,0.001063,0.160295,-0.228987,-0.288209,0.486585,-0.357018,0.028230,-0.070708,-0.383728,-0.259313,-0.348089,0.120814,-0.174183,0.100366,-0.035167,-0.816831,0.055836,0.051775,0.132596,0.342258,0.033465,0.226534,0.171144,-0.443666,0.197388,0.351431,0.343311,-0.645840,0.517685,-0.086853,0.146274,-0.297011,-0.059242,-0.034169,0.495278,0.371922,0.290804,0.159822,-0.381238,-0.098511,-0.325979,-0.215308', '10466639', '1930829', '1301257', '1914923');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303691', '青春残酷物语', '剧情', '真琴（桑野美雪 饰）是个叛逆的女高中生，一次搭便车时她险被车主非礼，幸好被路过的藤井清（川津祐介 饰）救下。次日二人再次相遇，相约到水边游玩，然而阿清却粗暴对待真琴并企图强暴她。事后真琴并没有迁怒于阿清，还给他留下了联系方式。阿清却迟迟没有联系真琴，因为他与一个有夫之妇有染。伤心的真琴在酒吧里借酒消愁，遭到几个小混混骚扰。阿清赶来救下真琴，于是二人再度和好，并决定同居。因为把钱都给了小混混，阿清交不起学费，他便决定和真琴联手，敲诈那些愿意搭载真琴的中年男人，二人屡屡得手。不久后真琴怀孕，阿清执意要她去堕胎。为了筹钱，阿清只好又和有夫之妇上床，另一方面，郁郁寡欢的真琴和另一个男人发生关系。这对恋人都不知道，会有怎么样的命运等着他们……©豆瓣', '桑野美雪', '大岛渚', 7.4, 8439, 'tt0054286', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2248320095.jpg', 0.7, 3.8, 34.3, 46.5, 14.7, '0.568945,-0.121273,-0.659384,0.233521,-0.241821,-0.579552,0.752590,-0.093442,-0.338718,-0.399721,-0.015595,0.718530,0.020172,0.269690,0.050368,-0.011495,-0.253641,-0.756239,0.266970,-0.058045,-0.382396,-0.371635,0.252232,0.033130,-0.125854,-0.003321,0.401522,-0.190472,-0.185538,0.646820,0.485270,0.126747,-0.214544,0.741525,-0.191520,0.349913,-0.105041,0.224942,-0.091654,0.439012,0.144915,-0.329566,-0.193550,0.315647,0.094266,0.606606,0.580896,-0.069525,-0.219839,-0.061559,0.139527,-0.202660,0.015591,0.287885,0.298255,-0.138430,0.198517,0.279289,-0.349104,-0.012648,0.168198,0.168715,-0.393641,0.324671,0.021812,0.028524,-0.603669,0.388445,-0.126820,-0.025677,0.294699,-0.264009,0.009686,0.499690,0.333167,0.110070,-0.369058,-0.069407,-0.340267,0.065759,0.807623,0.137334,0.334705,0.360336,-0.121557,-0.174194,0.284198,-0.169127,-0.493955,0.114935,0.250790,0.152534,-0.464795,-0.135156,-0.427205,-0.268103,-0.354100,0.127595,-0.018063,-0.378452,0.050720,-0.353787,0.109511,-0.381108,-0.652250,0.337973,0.086738,-0.158932,0.398021,-0.911145,0.104218,0.819249,0.702796,-0.586755,0.425917,0.379362,-0.114760,-0.051406,0.078851,-0.039999,0.212476,0.354320,0.196345,0.162539,0.283761,0.032318,-0.351075,0.069025', '1308755', '1301022', '26718282', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303693', '防弹武僧', '喜剧', '一卷神秘的中国古代卷轴，由于蕴藏着巨大的力量，邪恶的坏蛋们个个都想得到它来统治世界；一个来自中国西藏的无名武僧（周润发 饰），为了保护着卷卷轴，一直过着颠沛流离的生活，他几乎躲遍了世界的每一个角落。直到有一天，武僧觉得累了，于是，他开始物色合适的人成为自己的弟子，将这个艰巨的任务继承下去。街头混混卡尔（西恩•威廉•斯科特 Seann William Scott 饰）偶然中帮武僧解了围，或许是心灵感应，武僧感应到这个混小子就是自己的传人了，于是决定将一身武功传给卡尔。卡尔开始了他对抗邪恶的艰难宿命。©豆瓣', '周润发', '保罗·亨特', 5.3, 21488, 'tt0245803', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2243984850.jpg', 7.9, 32.7, 48.5, 8.4, 2.5, '0.192647,0.119608,-0.612694,0.748585,-0.445012,-0.011425,0.451265,-0.067163,-0.514467,-0.144136,0.438516,0.816698,0.143535,0.186774,0.182266,0.356536,-0.118209,-0.749290,-0.146196,-0.266009,-0.483128,-0.261613,-0.412953,-0.348139,-0.130369,-0.457507,0.454966,0.233719,-0.110774,0.045113,0.314081,0.179440,-0.081149,0.380321,-0.430218,-0.037888,0.083919,-0.328998,0.036027,0.181347,-0.004967,-0.109361,-0.061048,0.246749,-0.193453,0.090844,0.523295,-0.343039,0.036274,-0.124267,0.356407,-0.186196,-0.409397,-0.035111,0.247839,0.237192,0.078215,0.082300,0.064933,0.068687,0.132801,-0.106008,-0.862940,-0.009795,0.180111,0.155166,-0.679541,0.463907,0.028872,-0.237539,-0.154644,-0.342825,0.133978,0.061262,0.199813,0.236571,0.034972,-0.018224,-0.413793,0.207064,0.481124,-0.222190,-0.309145,0.102512,-0.047181,-0.251888,-0.159894,-0.257252,-0.403700,-0.131147,0.496683,-0.000229,-0.235033,0.150247,-0.720071,0.215356,-0.078072,-0.143177,0.077013,-0.340952,-0.144290,-0.303165,-0.086082,-0.079010,-0.246940,0.050878,-0.028271,-0.294119,0.983049,-0.577949,0.271572,0.905131,0.158544,-0.212308,0.554752,-0.167735,0.216981,-0.210260,-0.142146,0.294449,-0.057062,0.551259,0.311076,0.453604,-0.025051,0.106152,-0.286249,0.734587', '27602116', '25928048', '24284209', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303695', '洛奇3', '剧情', '在第二次击败宿敌——黑人拳王阿波罗·克里德（Carl Weathers 饰）后，当初贫民窟出身的穷小子洛奇（西尔维斯特·史泰龙 Sylvester Stallone 饰）逐渐走上事业的顶峰。他先后十次卫冕，创造了重量级拳王的不败神话，受到来此各界的疯狂追捧。原本打算引退的洛奇受到了黑人拳击手克鲁伯（Mr. T 饰）的挑战，他不顾经纪人米基（Burgess Meredith 饰）的阻拦，决然走入擂台，却遭遇了生涯中久违的惨败。在此之后，米基因心脏病去世，洛奇也陷入消沉。就在这关键时刻，阿波罗出现在洛奇面前，他要帮助这个昔日的劲敌重新振作起来，寻找属于自己的荣光……本片荣获1983年青年艺术家奖最佳动作片奖。©豆瓣', '西尔维斯特·史泰龙', '西尔维斯特·史泰龙', 8.2, 14675, 'tt0084602', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199773386.jpg', 0.2, 1, 19.8, 45.4, 33.7, '-0.104301,0.222230,-0.594294,0.463873,0.098427,-0.445477,0.455022,0.182638,-0.342956,-0.196512,0.500528,0.904176,-0.236835,0.022405,0.579153,-0.290016,-0.144708,-0.759251,-0.039256,-0.024044,-0.098953,-0.105327,-0.605479,-0.007509,-0.138419,-0.513549,0.799218,-0.091031,-0.408724,0.625629,0.480107,0.473135,0.262622,0.201180,-0.112205,0.251309,0.340551,-0.110106,-0.423134,0.421790,-0.162295,-0.283431,-0.092144,0.197770,-0.028661,0.151473,0.505219,-0.175515,0.116278,-0.170795,0.433293,-0.303797,-0.199435,0.113358,0.250521,-0.182088,0.020954,0.228050,0.183913,0.126846,0.168123,-0.214484,-0.814619,-0.055753,-0.010503,0.309756,-0.573908,0.441845,-0.156155,-0.044807,-0.031306,0.129263,-0.023335,0.262204,0.257420,0.171053,-0.194993,0.032657,-0.384816,0.381556,0.561348,-0.045205,-0.272793,0.159358,-0.048885,-0.431397,-0.089360,-0.544761,-0.565009,-0.052581,0.357838,0.038945,0.035747,0.411258,-0.467646,-0.129247,-0.385029,-0.021738,-0.116392,-0.078475,-0.151763,-0.608072,-0.225637,-0.049044,-0.283752,0.079738,-0.242701,-0.266511,0.530509,-0.607996,0.452440,0.350427,0.331700,-0.099724,0.526355,-0.045076,0.050111,-0.284248,-0.211589,0.484289,-0.062458,0.193583,-0.113437,0.132748,-0.068121,-0.124048,-0.190468,0.619349', '1482099', '1780122', '24875409', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303698', '405谋杀案', '悬疑', '某晚，丁娟赴约去见男友李良，发现他倒死在自己屋内。东海市公安局干警钱凯（徐敏）、陈明辉（仲星火）接到报案后，火速赶到案发现场。法医鉴定李良之死属他杀后，两人注意到一些诸如李良伤口上有根细小的鸟类羽毛、茶杯上有一个明显的指纹之类的蛛丝马迹，其中在李良的笔记本上，有一句“阿三，我决不放过你！”的话。调查后，小钱老陈两人得知与李良相熟的名叫阿三的共有两人，一为在黄山青溪农场工作的绰号为“橡皮鱼阿三”的人，他和李良曾在钱财上有过纠纷，一为曾与李良共过事的东海电视台摄影师方明山（严翔），他与李良曾有很深的矛盾。一番取证鉴定，方明山成为重大嫌疑人，但案件并非如此简单。©豆瓣', '仲星火', '沈耀庭', 8.4, 14575, 'tt0339981', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2231138515.jpg', 0.3, 1, 12.5, 50.3, 36, '0.487265,-0.096328,-0.764583,0.382306,-0.003457,-0.163266,0.646284,0.049247,-0.667800,-0.176204,0.273543,0.692097,-0.146930,0.234399,-0.051401,-0.068680,-0.389056,-0.501961,0.137945,-0.274827,-0.529122,-0.648898,-0.037525,-0.052670,0.062233,0.156346,0.075750,-0.107806,-0.171156,0.484905,0.097378,0.065965,-0.237895,0.571232,-0.275002,0.280890,-0.062631,0.057939,-0.239724,0.066195,0.120006,-0.136998,-0.303899,0.051574,0.094764,0.571159,0.372899,0.125917,-0.470013,0.136344,0.186788,-0.209364,0.175625,-0.121733,0.596776,0.203101,0.267513,0.328499,-0.394556,-0.189233,0.125683,0.070881,-0.398823,-0.146987,-0.036679,0.509419,-0.416498,0.203198,-0.165991,-0.075391,0.012482,-0.570169,0.308372,0.364681,-0.026494,-0.009294,0.033367,-0.173450,-0.495819,0.315136,0.673585,0.136341,0.036227,-0.157271,0.143829,-0.663426,-0.037988,0.000120,0.099772,0.147818,0.523230,-0.185829,-0.309175,-0.227498,-0.502429,-0.028878,-0.058517,-0.092955,-0.150790,0.053262,-0.042111,-0.466088,-0.143242,-0.388207,-0.652817,-0.037771,0.192513,-0.295854,0.406492,-0.751005,0.258791,0.340841,0.099381,-0.436331,0.581650,0.041921,-0.029430,-0.201255,-0.184757,-0.070467,0.346431,0.391527,0.197862,0.273143,-0.091120,-0.436890,-0.346708,-0.141002', '3263169', '25870679', '30210700', '1293145');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303717', '夏日福星', '喜剧', '鹧鸪菜（洪金宝 饰）、犀牛皮（冯淬帆 饰）、大山地（吴耀汉 饰）、罗汉果（曾志伟）、花旗参（秦祥林 饰）、大力丸（成龙 饰）、巴巴拉（胡慧中 饰）和维奇（元彪 饰）等警察兄弟一起放大假出外旅游，岂料他们刚刚到达目的地就被上司通知马上回港执行任务。原来，香港富商冯先生遭杀手杀害，他的女儿冯小姐（关之琳 饰）和冯先生的好友刘先生现在随时都有生命危险。于是，为了保护两人，大力丸和助手贴身保护刘先生；而年轻漂亮的冯小姐则住到巴巴拉的家由犀牛皮等人保护，众人都想和这位漂亮开放到冯小姐搭上关系；维奇和巴巴拉住入冯家引诱杀手上钩。夏日里，一连串爆笑惊险的场面上演了！©豆瓣', '洪金宝', '洪金宝', 7.4, 24486, 'tt0090342', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521395606.jpg', 0.5, 3, 37.9, 42.2, 16.3, '0.068805,-0.348650,-0.485768,0.310068,0.006176,-0.083756,0.397244,0.259128,-0.228401,-0.313862,0.187773,0.395163,-0.310336,0.166281,0.332183,0.101144,-0.347365,-0.492497,-0.045994,0.112016,-0.337597,-0.216526,0.008053,-0.263764,0.093568,-0.113209,0.080553,-0.046483,0.050871,0.573749,0.458224,0.052848,-0.279252,0.146261,0.071258,0.199247,0.276672,0.109298,-0.349240,0.280035,0.070778,-0.068008,0.117014,-0.136547,0.429878,0.430046,0.286914,-0.082982,0.176975,-0.005982,-0.203209,-0.190252,0.395026,0.190038,0.282844,-0.190036,0.379774,-0.035271,-0.373827,0.021661,0.165391,-0.328973,-0.404991,0.300492,0.380967,-0.195611,-0.353610,0.141012,-0.241475,0.045308,-0.063292,-0.309880,0.342199,0.281374,0.128585,0.041852,-0.048824,0.087734,-0.365429,0.256772,0.480485,0.015586,0.371394,-0.073317,0.064085,-0.228669,0.052194,-0.112311,-0.268947,0.016687,0.346632,-0.156004,0.145831,-0.237902,-0.448737,-0.257659,-0.204203,0.150509,-0.163455,-0.197087,0.099062,-0.637808,0.154275,-0.246781,0.082621,0.375594,0.304846,-0.121741,0.626301,-0.366869,0.091462,-0.020198,0.413237,-0.583274,0.467348,-0.135805,0.163032,-0.337128,-0.091236,-0.151357,0.400176,0.125948,0.375674,0.339567,-0.250506,0.000486,-0.098649,-0.104709', '3147969', '1930829', '4301278', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303723', '天堂陌影', '剧情', '居住在纽约的匈牙利移民威利（约翰·劳瑞 John Lurie 饰）是一个自认为时髦的年轻人，受姨妈之托，很不情愿地接待素未谋面的表妹艾娃（伊斯特·伯林特 eszter balint 饰）来住所借宿10天。然而在短暂又无聊的十天中，个性的艾娃却渐渐赢得了威利的好感，也与他 的好哥们艾迪（Richard Edson 饰）成为了朋友。时间来到一年后，威利和艾迪打扑克赢下了许多钱，他们决定离开这座城市，去克利夫兰找艾娃。亦是因为无聊，三个朋友在回合后又决定离开克利夫兰，一起去佛罗里达度假。然而在佛罗里达，无聊的时光终于出现了戏剧性的变化，威利和艾迪去赛狗输光了所有钱，而艾娃却在海边散步时，被一个毒贩误认而获得一笔意外之财。艾娃给两个伙伴留下了一些钱后，便准备买机票飞回欧洲，而与此同时，威利和艾迪去赛马又把钱赢了回来，他们能否在机场顺利追回艾娃……本片曾获1984年洛迦诺国际电影节金豹奖以及1985年圣丹斯电影节评委会特别奖。', '约翰·劳瑞', '吉姆·贾木许', 8.6, 14944, 'tt0088184', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1730030247.jpg', 0.2, 0.9, 11.2, 46, 41.7, '0.034832,-0.106979,-0.517247,0.329345,-0.082714,-0.664147,0.544746,0.147151,-0.349036,-0.092617,-0.042288,0.860966,-0.093238,0.158660,0.565014,0.028280,-0.501006,-0.425015,0.152888,-0.406462,-0.171711,-0.524263,-0.031667,-0.241659,-0.023075,-0.288291,0.161162,0.102366,0.295122,0.837698,0.342483,0.053706,-0.123326,0.502026,-0.313418,0.124146,0.223228,0.103544,-0.195352,0.494120,0.128465,-0.134785,-0.384250,-0.056532,0.465380,0.223080,0.701079,0.084540,-0.111061,0.115505,0.204574,-0.156766,-0.069425,-0.003486,0.164245,-0.056643,0.221630,0.134371,-0.426299,0.153598,0.137240,-0.211089,-0.312030,0.300527,-0.193318,-0.027055,-0.791917,0.724678,-0.072554,-0.120665,-0.156454,-0.477684,0.214376,0.374542,0.119068,0.231822,0.015899,0.020156,-0.388247,0.155369,0.859756,-0.152545,0.066084,0.266897,0.081160,-0.443705,-0.029155,-0.006628,-0.344149,0.018809,0.519960,-0.108179,-0.066820,-0.042254,-0.675906,-0.110760,-0.403771,-0.418385,-0.050663,-0.410200,0.134305,-0.585672,0.029509,-0.064045,-0.225381,0.169341,0.115584,-0.059030,0.563058,-0.621915,0.337799,0.685882,0.527438,-0.331923,0.695706,-0.060158,0.230038,-0.028744,0.030512,0.005179,0.141465,0.309106,0.229061,0.300986,-0.003833,-0.276997,-0.1844