INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303724', '最佳损友闯情关', '喜剧', '咸湿超（陈百祥 饰）即将与女友Dorlina（吴君如 饰）结婚，损友牛精帆（冯淬帆 饰）、口臭奇（曹查理 饰）极力阻止。这时候他们的好友之一徐定贵（刘德华 饰）的哥哥徐定富因为经营不善而导致自己的公司负债累累，欠下了霍氏公司一大笔债务，定富的公司被迫宣告破产。为了帮助哥哥，徐定贵与咸湿超等几位好友潜进了霍氏公司，希望能对复兴公司有所帮助。定贵的办事能力得到老板的赏识，霍氏便把女儿Nicole（关之琳 饰）介绍给定富认识，怎料在Nicole的生日舞会上，定贵的女友豆豆（邱淑贞 饰）出现了……©豆瓣', '刘德华', '王晶', 6.7, 7354, 'tt0098718', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2415586874.jpg', 1.3, 8.2, 56.2, 24.4, 9.9, '0.069873,0.151685,-0.460950,0.261046,-0.004334,-0.305823,-0.005569,0.613418,-0.460305,-0.223943,0.085508,0.753386,-0.068180,0.271840,0.155654,-0.005099,0.017667,-0.327177,0.142071,-0.036121,0.059252,-0.505788,-0.078530,-0.213686,-0.296668,-0.149263,0.408578,0.061348,0.078089,0.549322,0.650648,0.235299,-0.086691,0.153355,-0.003729,0.077336,0.181254,0.271337,-0.543204,0.306343,-0.161122,-0.160261,0.272742,0.072228,0.274067,0.289726,0.217442,0.059326,-0.234582,-0.177565,0.414365,-0.039941,0.216587,-0.034825,0.316929,0.098596,0.468405,0.402246,-0.572184,-0.176106,0.126028,-0.112716,-0.780042,0.042591,0.365415,-0.054999,-0.666289,0.294654,-0.342494,-0.091957,0.053064,-0.396013,0.236967,0.573590,0.242722,0.149009,-0.125041,0.437147,-0.431990,0.331415,0.332437,-0.267874,0.317006,0.338227,0.024252,-0.182978,-0.062358,-0.028526,-0.433212,0.056019,0.243673,0.159156,0.214222,-0.062688,-0.353752,-0.271141,-0.212319,-0.015819,0.330504,-0.355431,0.088396,-0.348862,-0.240162,-0.242611,0.022664,0.078043,0.214479,-0.323778,0.527856,-0.782784,-0.097046,0.439620,0.790085,-0.835918,0.595235,-0.225437,0.213922,-0.378831,-0.240472,-0.242145,0.194446,-0.148378,0.070135,-0.086877,0.094178,-0.276726,0.134282,-0.101671', '1304382', '1417543', '1299649', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303769', '龙在江湖', '剧情', '黑社会组织成员韦吉祥（刘德华）因突发纷争砍伤仇家丧波惹上麻烦，在曾心仪许久的大律师Sandy（梁咏琪）的帮助下，他的麻烦得以摆脱，丧波被判入狱五年，但他的妻子亦被人撞死。独自抚养爱子大洪（余文浚）的韦吉祥拙手笨脚，与大洪摩擦不断，幸得红颜知己Ruby（关秀媚）从中调解，两人关系渐变和谐。为了大洪，韦吉祥有心退出江湖，令组织老大对他越来越不爽。丧波刑满出狱，与组织老大联合起来展开复仇行动，身不由己的韦吉祥只能勇敢地站起来应战，然而一切还是无法控制越变越糟糕。©豆瓣', '刘德华', '王晶', 7.2, 21326, 'tt0165998', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2038162492.jpg', 0.7, 4.7, 44, 36.4, 14.2, '0.044061,0.033712,-0.414966,0.178860,0.177787,-0.329654,0.363318,0.236174,-0.722143,-0.161514,0.027604,0.260972,-0.283835,0.181805,0.163085,-0.321731,0.107705,-0.499028,0.169790,0.251214,0.034335,-0.530773,-0.236647,-0.583530,-0.262640,-0.125999,0.342621,0.314040,-0.317509,0.338589,0.442039,0.301100,-0.325202,0.407747,-0.058406,0.016723,-0.273347,0.128670,-0.448458,-0.149497,-0.018513,-0.508534,-0.168864,0.156260,0.059752,0.141576,0.295307,-0.296555,-0.047309,-0.432654,0.332231,-0.313034,-0.052008,-0.023987,0.541212,0.001311,0.030639,0.480185,-0.115873,-0.143418,-0.154432,0.027764,-0.518354,0.210188,0.260930,-0.042263,-0.598669,0.060003,-0.072858,0.306489,0.023345,-0.224175,0.097816,0.631351,0.217044,0.023896,-0.192424,0.358702,-0.315900,0.196135,0.841484,0.205111,0.252603,-0.234778,-0.065964,-0.331457,-0.072696,-0.228876,-0.215862,-0.272952,0.470348,-0.002628,-0.023918,0.323949,-0.294190,-0.135011,-0.262240,0.248299,-0.158311,-0.211160,0.330210,-0.211559,-0.179059,-0.049207,-0.154780,0.203415,-0.149425,-0.367704,0.492334,-0.458800,0.259714,0.368226,0.303154,-0.594330,0.175897,0.440377,0.238592,-0.278144,-0.388735,0.233944,0.009275,0.112747,0.356770,-0.141914,-0.322482,-0.045428,-0.129190,-0.049100', '1484760', '1293265', '1296978', '1299658');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303773', '007之择日而亡', '动作', '特工英雄007詹姆斯•邦德（皮尔斯•布鲁斯南 Pierce Brosnan 饰）这次在北朝鲜发现了一位世界级的媒体大亨——盖斯特维的阴谋诡计。盖斯特维妄图研制一枚类似于第二颗太阳那样的卫星来挑起全球战争，进而达到他控制地球的企图。007当然不会允许盖斯特维的阴谋得逞，于是在北朝鲜展开了调查。经过调查，007发现盖斯特维的真实身份，那是经过整容后改头换面的原北朝鲜领导人Zao。现在，007必须抓紧时间找到Zao，制止他的阴谋以阻止战争的全面爆发。007真的能成功吗？©豆瓣', '皮尔斯·布鲁斯南', '李·塔玛霍瑞', 7.3, 44232, 'tt0246460', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p940106094.jpg', 0.4, 3.3, 41.3, 42.9, 12.1, '0.139086,0.220270,-0.561420,0.460193,0.014181,-0.097436,0.141331,0.072170,-0.070760,-0.130441,0.500083,0.608721,-0.310454,-0.654642,0.142810,-0.217796,-0.486909,-0.962847,0.137461,-0.157007,-0.358004,-0.404413,-0.550428,-0.160638,0.212594,-0.613860,0.554233,0.215155,-0.482869,-0.126201,0.038729,0.449124,0.129143,0.200706,0.013643,-0.207367,0.155944,-0.330645,-0.456779,0.634130,0.184380,-0.005395,-0.043904,0.427633,0.002793,0.406580,0.445716,-0.691079,-0.046697,-0.172859,0.333786,-0.431311,0.088222,-0.112516,0.352723,-0.085923,-0.344530,0.432165,-0.164061,0.133365,0.191559,0.178648,-0.963584,-0.117473,-0.123624,0.200023,-0.350378,0.209888,-0.190393,-0.093025,-0.174964,-0.110958,0.278088,0.933282,0.206939,-0.163486,-0.007973,0.353701,-0.639585,0.122535,0.413275,0.010602,-0.191498,0.346465,-0.113791,-0.093254,-0.023884,-0.426744,-0.398890,0.056387,0.323790,-0.160943,-0.059867,0.211825,-0.455372,-0.662938,-0.696665,-0.180937,0.153426,-0.273377,0.013048,-0.711148,-0.370995,0.100412,-0.080427,-0.119438,-0.066270,-0.217422,0.177748,-0.882189,0.111920,0.401272,0.286732,-0.192573,0.174705,0.017671,-0.244624,-0.353751,-0.456740,0.185698,0.347217,0.464763,-0.003041,0.351797,0.515024,-0.513231,-0.269503,0.239944', '1291860', '6041191', '1307442', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303781', '精装追女仔之2', '喜剧', '坚叔（冯淬帆饰）与两个伙计（曾志伟与陈百祥饰）惨淡经营一间汽车行，坚叔的侄子阿备（刘德华饰）是一个头脑灵活的年轻人，同时也常无赖地找坚叔骗吃骗喝。一次偶然的机会，坚叔与两学徒误打误撞被发达台监制（王晶饰）看中，纳入旗下，而鬼马的他们到处闯祸，终被赶出。而此时阿备迷恋上了邻居十三妹（黄韵诗饰）的一个学生宝珠（李美凤饰）。为了达到目的与报仇，他带领坚叔和两个伙计与十三妹的学生们参加了老周电视台，共同筹拍了一部短剧，不料演出后却大受人们的喜爱。然而，此时阿备却暗藏了另一个秘密，阿备的爱情又会何去何从呢......©豆瓣', '刘德华', '王晶', 6.6, 8865, 'tt0095404', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2161916167.jpg', 1.3, 9.3, 56.2, 23.3, 9.9, '0.150953,-0.213559,-0.519005,0.621554,-0.080652,-0.350940,0.659773,0.244422,-0.536452,-0.180041,0.016193,0.784096,-0.182416,0.281805,0.273554,-0.068820,-0.040987,-0.548061,-0.114563,-0.201969,-0.118913,-0.167072,-0.302573,-0.151568,-0.169074,-0.011408,0.367964,0.153064,-0.143066,0.610470,0.612823,0.190291,-0.218424,0.152396,-0.036188,0.093060,0.292244,-0.035264,-0.109386,0.208115,-0.183494,-0.296308,-0.327349,-0.073094,-0.158292,0.430312,0.699726,-0.162008,-0.039506,-0.275540,0.148773,-0.183605,-0.258010,0.170428,0.087313,-0.037486,0.480480,0.128292,-0.104054,0.057209,0.146802,-0.210455,-0.771303,0.076237,0.209587,-0.063947,-0.618561,0.534368,0.030226,-0.216668,-0.198664,-0.314672,0.176059,0.210645,0.204950,0.260530,-0.223607,-0.105005,-0.415033,0.229744,0.539325,0.131827,0.161083,0.371306,0.218837,-0.397690,0.071979,-0.139178,-0.514241,0.097716,0.527814,-0.075287,0.029031,-0.251857,-0.767865,0.030746,-0.350495,-0.003563,-0.031354,-0.468580,0.103356,-0.582159,0.095775,-0.540866,-0.288271,0.066970,0.219974,-0.043093,0.870609,-0.780884,-0.018979,0.275299,0.017879,-0.648285,0.734575,0.058583,0.223986,-0.328349,-0.124903,-0.589962,0.084056,0.173695,0.269271,0.430565,-0.197354,-0.388811,-0.333249,-0.060717', '4301278', '3811356', '35144311', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303783', '赌城大亨II之至尊无敌', '剧情', '贺新（刘德华 饰）人到中年，他的赌场生意也越做越大，却突然间因为国际级老千经常光顾而使得赌场损失连连。经过一番调查，贺新认为公司有内鬼，且因为长期经营理念的不和，贺新和公司总经理聂傲天（刘兆铭 饰）越来越貌合神离。此时，贺新的一双儿女贺天宝和贺天儿（陈德容 饰）都回到了他身边，尤其是贺天儿更是带着男友程震一同回来想要协助父亲的生意。一次，贺天宝与程震两人飙车，不幸的是天宝车毁人亡，贺新经过一番调查确认一切是程震蓄意而为，为了给儿子报仇，贺新派了杀手找程震。另一边，贺太太阿妹（邱淑贞 饰）竟发现另一个更大的秘密：程震竟然是贺新旧情人程乐儿的儿子。程震和贺新又有怎样的恩怨呢？©豆瓣', '刘德华', '王晶', 6.6, 8034, 'tt0104146', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2043221653.jpg', 1.7, 10.8, 53.3, 24.1, 10.1, '-0.221466,-0.332484,-0.531228,0.530265,-0.000263,-0.391920,0.532180,0.174761,-0.863606,-0.617754,-0.292531,0.436231,-0.241547,0.537293,0.410356,-0.125058,0.056923,-0.477860,-0.186819,0.113512,-0.282336,-0.572081,-0.226367,-0.427298,0.017786,0.241345,0.000381,0.351320,-0.274393,0.413064,0.503502,0.159846,-0.255740,0.657123,0.040158,-0.013539,0.060208,0.210779,-0.207454,0.081166,0.339695,-0.329729,-0.038282,0.124086,0.075186,0.499281,0.299904,-0.048314,-0.066880,-0.134261,0.269739,-0.184035,0.091409,-0.125218,0.431376,-0.049739,0.367495,0.251279,-0.337346,-0.261550,0.173212,-0.244171,-0.348840,0.265475,0.235295,-0.184106,-0.565248,0.280024,-0.025369,0.196357,-0.105199,-0.232606,0.447829,0.446207,0.402922,0.139356,-0.262862,-0.000440,-0.589399,0.207908,0.646414,0.294747,0.603402,0.190031,-0.080849,-0.616067,-0.078894,-0.271927,-0.138567,-0.090771,0.419692,-0.130060,0.281863,-0.011180,-0.270986,-0.197844,-0.119385,-0.047182,0.162691,-0.200829,0.236534,-0.445977,-0.154058,-0.703683,-0.138658,0.232912,0.020898,-0.362494,0.419530,-0.896815,0.097773,0.163844,0.051520,-0.887301,0.632044,-0.015539,0.093969,-0.251323,-0.023293,-0.326869,0.274452,0.117007,0.295233,0.037244,0.007555,-0.208961,0.144589,0.162525', '1306249', '1293265', '22555690', '1872133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303801', '瞧这一家子', '剧情', '曙光毛纺厂精织车间主任老胡（陈强饰），一向埋头苦干但思想僵化，觉得工作就得埋头苦干而搞技术革新是投机取巧。女儿嘉英（张金玲饰）是精织车间的挡车工，她正与车间的修理工郁林（汪用桓 饰）相恋。在车间党委书记老齐的启发下，郁林和嘉英等几个青年工人想把光电管装到织机上，利用“光电探纬设计方案”以提高产品质量，减轻劳动强度，所以和老胡发生了矛盾，连郁林为老胡理发都搞得不欢而散。而老胡的儿子嘉奇（陈佩斯饰）因为在文革中没有受到良好教育而有些好逸恶劳，但本性不乏闪光点，一次与朋友大阮、张岚（刘晓庆饰）在逛公园的过程中奋不顾身跳入水中救根本没落水的孩子，这些却给孩子的姑姑一一新华书店的营业员林小红（方舒饰）留下了好印象。另一方面老胡也在工作中有所触动希望去书店找一些技术资料进行学习，却被工作态度蛮横的张岚搞得争吵起来，林小红出面解决了问题。而胡嘉奇应张岚的邀请教大家舞蹈，不仅满口白字，譬如“如火如茶”“披荆斩辣”，而且动作夸张僵硬，只有小红作为手风琴手默默鼓励和支持他，这使得嘉奇对她产生了好感，并决心用学习使得自己进步。经过周折，光电探纬仪试验成功。“十一”前夕，郁林和嘉英喜结良缘。老胡请来张岚，嘉奇请来女友小红，张岚、小红一齐来到老胡家中，老胡、胡婶错把张岚当作未来的儿媳。大阮赶来接走张岚，这时，大家才知闹了个笑话。小红和嘉奇幸福地依偎在一起。值得一提的是电影中客串扮演摄影师的正是已故著名相声表演艺术家马季。本片于1980年 获第三届电影百花奖最佳配角奖（刘晓庆），文化部1979年优秀影片奖、青年优秀创作奖（王好为、张金玲、刘晓庆）。', '陈强', '王好为', 8.1, 10422, 'tt0334195', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205940427.jpg', 0.2, 0.7, 19.5, 51.5, 28, '0.085276,-0.076610,-0.550833,0.478923,-0.052677,-0.420926,0.510189,0.010899,-0.455613,-0.294710,0.085104,0.356483,-0.118425,0.276169,0.144023,-0.327937,-0.256796,-0.558380,-0.061403,0.168505,-0.152689,-0.427729,0.063864,-0.113277,-0.325758,-0.278304,0.215404,-0.054180,-0.259748,0.391584,0.414149,0.006534,0.106214,0.226679,-0.065733,0.108435,0.017323,0.024639,-0.234237,0.116996,0.216062,-0.160892,-0.305818,-0.011912,0.341304,0.234616,0.477296,-0.026073,-0.192259,0.001071,0.260186,-0.249481,0.057071,-0.051910,0.272409,0.274679,0.276634,0.053042,-0.233832,0.126362,0.078098,-0.151072,-0.546514,0.202817,0.201904,-0.010483,-0.662884,0.158022,0.077466,0.025940,0.021809,-0.370799,0.246718,0.104819,0.343826,0.435367,-0.322673,0.197106,-0.303721,0.326857,0.482260,-0.028994,-0.092540,0.329602,-0.144111,-0.326708,0.047389,-0.155024,-0.113310,0.022404,0.160276,-0.073407,-0.019868,0.037690,-0.309530,-0.126440,0.089136,-0.071503,0.064768,-0.392270,0.068546,-0.482084,-0.125885,-0.388768,-0.157138,-0.054430,0.052019,-0.426234,0.660638,-0.603840,0.078056,0.186172,0.103049,-0.488689,0.590627,0.168139,0.067807,-0.213593,-0.064577,-0.279423,-0.117440,0.037085,0.148287,0.330242,-0.151121,-0.359189,-0.236045,0.105430', '26283288', '1293607', '35144311', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303815', '你丫闭嘴！', '喜剧', '铁蛋（杰拉尔·德帕缔约）是个大话痨，与人聊天不分时间、场合和对象，也因此他没有朋友，在监狱里一个接一个的换着室友，直到他遇到总也不说话的杀手卢比。铁蛋可以一直对卢比说下去，卢比（让·雷诺）不说话，不生气，脑子里总在策划越狱。尽管卢比的越狱计划天衣无缝，却不想被铁蛋死死的黏住，可也正由于铁蛋的帮忙，两人在混乱中逃了出去。卢比心中还有为女友复仇的计划，然而铁蛋只是想永远和卢比做朋友，开一个餐馆。一个喋喋不休，一个喊着要对方闭嘴。两个人在逃亡的途中，冲突不断，笑料迭出。©豆瓣', '热拉尔·德帕迪约', '弗朗西斯·韦贝尔', 8.1, 197064, 'tt0310203', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2173579470.jpg', 0.2, 1.6, 19.5, 48.3, 30.4, '0.568960,-0.255494,-0.620598,0.545155,-0.246880,-0.490899,1.059540,-0.042776,-0.346185,-0.200888,-0.133797,0.527255,-0.121925,-0.061618,-0.023819,0.076714,-0.322021,-0.488054,0.160819,0.015725,0.028382,-0.645311,-0.076975,-0.224503,-0.342310,0.156401,0.168116,-0.197598,-0.122551,0.268809,0.321026,-0.041261,-0.185696,0.685854,-0.140954,-0.036886,0.161215,-0.118592,0.011235,0.339183,0.185281,-0.163052,-0.338995,0.307428,0.184481,0.491301,0.189857,-0.125128,-0.029327,0.216647,-0.215033,-0.401813,-0.112888,0.059914,0.183472,-0.358081,0.613377,-0.001390,-0.000470,0.285532,0.150589,-0.083941,-0.753308,0.261240,-0.132782,0.371124,-0.663618,0.389438,-0.251763,-0.097715,0.118330,-0.336052,0.318013,0.353846,0.458452,0.222348,-0.381788,-0.097735,-0.809828,0.055828,0.763492,0.088571,0.016521,0.332594,-0.004418,-0.111818,0.042683,0.126898,-0.737347,-0.174493,0.116390,-0.062882,-0.546776,-0.106494,-0.400135,0.255168,-0.129435,-0.119613,-0.290857,-0.636703,0.104541,-0.187023,-0.072296,-0.200049,-0.359841,0.274568,-0.057777,-0.045571,0.555868,-0.715930,0.068570,0.543650,0.549137,-0.387703,0.530126,0.578499,0.075035,-0.150554,0.196671,-0.288844,0.144742,0.205846,0.555673,0.569530,0.300836,-0.142835,-0.212675,0.241281', '1308755', '1296370', '4275444', '35441371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303823', '癫佬正传', '剧情', '女记者（叶德娴 饰）受托跟踪采访一个忠实于精神病患者救助事业的社会工作者（冯淬帆 饰），二十多年来他一直与街头流浪汉打交道，旨在引导他们走向康复，但他的行为得不到人们的响应。女记者亲眼目睹了他对垃圾佬（周润发 饰）、终日游荡在菜市场的癫仔（梁朝伟 饰）与康复的患者（秦沛 饰）的关怀 与他们辛酸的故事。康复患者其实有间歇性发作精神病，受到生活中重重压迫后，想念儿子的他持刀闯入幼儿园酿成血案......©豆瓣', '冯淬帆', '尔冬升', 8.6, 19148, 'tt0090940', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2329847890.jpg', 0.3, 0.8, 10, 45.5, 43.4, '-0.048223,-0.482069,-0.391431,0.148599,-0.077159,0.117515,0.882866,0.232095,-0.600485,-0.176782,0.535323,0.600951,-0.212361,0.276825,0.225094,-0.276069,-0.239916,-0.703091,0.054755,0.283881,-0.114162,-0.208155,-0.187287,-0.487504,-0.485222,-0.478950,0.458646,0.040636,-0.268512,0.503944,0.393303,0.402477,-0.057261,0.441091,-0.196233,0.028531,-0.006437,0.077041,-0.361355,0.137260,0.315063,-0.390335,-0.023943,0.031696,-0.031091,0.260175,0.739700,-0.286572,-0.143869,-0.278853,0.453458,-0.339357,-0.050110,0.400799,0.281354,0.237985,0.343958,0.104461,-0.209130,0.090134,-0.111899,0.123218,-0.255679,-0.251688,0.175643,0.367044,-0.499826,0.362103,0.076159,-0.027211,-0.174684,-0.083058,0.180089,-0.003633,0.098546,0.460293,-0.077587,-0.117110,-0.356646,0.344755,0.649823,-0.064747,-0.210612,0.250067,-0.479094,-0.442272,-0.014445,-0.070801,-0.626214,-0.080239,0.094926,-0.198391,-0.518034,0.259739,-0.372060,-0.027295,-0.175577,-0.079758,-0.178986,-0.134117,-0.136645,-0.826565,0.154134,-0.243279,-0.244060,0.048984,0.191587,-0.249439,0.820845,-0.852457,0.181445,0.451276,0.412402,-0.876950,0.773724,0.006854,-0.042544,-0.244499,-0.319430,0.554911,0.151543,0.306699,0.073216,0.116738,-0.290238,0.047081,-0.334849,0.103301', '1418179', '3445516', '1316589', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303847', '致命弯道', '恐怖', '克里斯（Desmond Harrington 戴斯蒙•哈林顿 饰）接到一份紧急的采访任务，他必须在3个小时之内赶到美国北卡罗来纳州的罗利市。原本应该顺利的形成却被一起交通事故打乱，一辆运载化学品的车辆翻倒，导致高速公路大塞车。万般无奈之下，克里斯选择一条人烟稀少的小路行进。另一方面，杰西（Eliza Dushku 艾丽莎•杜舒 饰）、卡莉（Emmanuelle Chriqui 曼纽尔•克莉琪 饰）、斯科特（Jeremy Sisto杰瑞米•西斯托 饰）、埃文（Kevin Zegers 凯文•席格斯 饰）和弗朗丝（Lindy Booth 林蒂•布丝 饰）等5位好友驱车前往山中露营游玩。谁知汽车半路离奇爆胎，等待救援时汽车又被突遇险情的克里斯撞上。众人结伴去附近求助，却未料到走入了变态食人魔所设下的重重陷阱……©豆瓣', '戴斯蒙德·哈灵顿', '罗布·施密特', 6.7, 39976, 'tt0295700', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1751977517.jpg', 1.6, 10.2, 50.9, 27.1, 10.2, '0.549445,0.096769,-0.654335,0.487045,0.487354,-0.197165,0.357116,0.282402,-0.123821,-0.272961,0.419762,0.461927,-0.380450,-0.237412,0.490437,-0.140513,-0.603845,-0.144341,0.223607,-0.134160,-0.572878,-0.521284,-0.285057,-0.018505,0.150122,0.059255,0.208966,0.204174,0.252066,0.793207,0.191704,0.335944,-0.392317,0.367263,0.071791,0.185930,0.398352,-0.135088,0.087822,0.358681,-0.231475,-0.147940,-0.036814,-0.327887,0.263574,0.404646,0.617287,-0.044793,0.018704,-0.105879,-0.054745,-0.035689,0.442372,0.048118,0.404277,-0.116371,0.155527,-0.004179,-0.467577,0.219465,0.350745,0.166300,-0.072610,0.213643,-0.371171,-0.075939,-0.495878,0.058237,-0.161385,-0.112589,0.079893,-0.583900,0.047331,0.352493,0.322406,-0.010101,0.128215,-0.022272,-0.278501,-0.313163,0.541448,-0.112272,-0.064242,0.117612,-0.087316,-0.050692,0.141620,0.050636,-0.252356,-0.226972,0.624693,0.045694,0.008118,-0.063550,-0.216360,0.016303,-0.801133,-0.237824,-0.358253,0.081189,-0.283148,-1.116642,0.624164,0.146070,0.056596,0.410557,-0.208897,0.269573,0.022966,-0.234428,0.296370,0.479304,0.213928,-0.122077,0.358790,-0.109259,0.169775,-0.196098,-0.124760,0.278281,0.163279,0.603694,0.041833,0.232092,-0.165881,-0.230698,-0.385298,0.241730', '2075345', '1293572', '34961898', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303862', '锦绣前程', '剧情', '林超荣（张国荣 饰）是一名刚被辞退的保险经纪。事业低谷加上感情失意令他重新投入到老友阮世生（梁家辉 饰）妹妹的怀抱，并同老友借了钱，想去澳门赌一把来翻身。虽然失败而归，但却遇上了一个赏识自己的大老板（曾江 饰），并喜欢上了老板的情人（关之琳 饰）。为了帮老板挣钱，林超荣决定不顾阮世生的反对，卖掉他所坚守的老人院。然而朋友的痛苦与冷漠终于令林超荣重新明白了一些人生的道理……©豆瓣', '张国荣', '陈嘉上', 7.6, 13440, 'tt0110198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p940058299.jpg', 0.5, 3.2, 34.6, 40.7, 21, '0.010968,0.205521,-0.501938,0.382016,-0.152777,-0.649093,0.686067,0.335191,-0.337178,-0.143441,0.013640,0.716093,0.293284,0.258177,0.218574,0.089179,0.007462,-0.457152,-0.019369,0.049756,-0.164069,-0.366716,-0.070696,0.056794,-0.334519,0.007205,0.550056,0.180189,-0.115900,0.433987,0.560739,0.100848,0.199887,0.610701,0.004984,0.055264,-0.239119,0.414853,-0.585324,0.072486,0.086298,-0.151362,-0.139163,0.214632,0.209508,0.484719,0.289127,0.007642,-0.200272,0.139840,0.241704,-0.066594,-0.044876,-0.041832,0.017842,0.304535,0.283872,-0.011526,-0.350947,0.106563,0.155113,-0.196238,-0.796931,-0.117811,0.142007,-0.121986,-0.739116,0.443224,-0.061015,-0.110446,-0.101579,-0.289720,0.051330,0.100605,0.323845,0.151277,-0.423269,0.195635,-0.378550,0.400673,0.641344,-0.002910,0.294539,0.595714,-0.032721,-0.412044,0.075166,-0.269027,-0.303913,0.090496,0.243882,0.119476,-0.186948,-0.083013,-0.499971,-0.159012,-0.286984,0.094551,0.020109,-0.612499,0.192024,-0.007307,-0.104885,-0.082657,-0.047268,0.035757,0.400013,-0.390543,0.572781,-0.721995,0.181399,0.536118,0.365021,-0.497196,0.454017,0.248551,0.056308,-0.335970,-0.145277,0.144624,0.140626,0.182243,0.113462,0.111459,0.001016,-0.418022,-0.199051,0.271864', '1299649', '1304977', '1299965', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303871', '我和爸爸', '剧情', '小鱼（徐静蕾 饰）一直跟妈妈生活在一起，直到高中时母亲意外去世，她才第一次见到自己的父亲老于（叶大鹰 饰）并和他生活在一起。老于是个典型的北京油子，经常夜不归宿，小鱼十分没有安全感，但倔强的她照顾自己的生活，也不张嘴跟父亲抱怨。小鱼长大了，谈恋爱了，和男朋友结婚了，带回家吃饭。饭桌上老于毫不留情面地看不上小鱼丈夫，小鱼爆发了，把多年来对父亲不关心自己的积怨和伤痛骂了出来。老于让小鱼离婚后直接回家，不要留恋。小鱼忍无可忍，拉起丈夫就走了。一年后，抱着小小鱼的小鱼回来了。为了不让女儿这么辛苦，老于去打麻将想给女儿挣点钱，但世道和以前不一样了，已经不是当年老于叱咤风云的时代了，这天老于打麻将时被喊抓赌的人吓着，成痴呆了。小鱼把父亲接回家，像小时候那样照顾他。女儿和爸爸的爱，是血浓于水，恩恩怨怨也不能磨灭的。©豆瓣', '叶大鹰', '徐静蕾', 7.4, 17549, 'tt0379587', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1226988141.jpg', 0.9, 3.8, 36.6, 44.4, 14.4, '0.279239,-0.292641,-0.723088,0.287737,-0.391283,-0.832750,0.675727,0.149768,-0.550236,0.032824,-0.249379,0.747486,-0.004316,0.578024,-0.107024,0.308969,-0.398500,-0.605933,0.128524,0.127771,-0.200504,-0.384069,0.049970,0.078766,-0.234754,0.011741,0.051822,-0.437097,0.156451,0.649209,0.094674,-0.068508,0.238323,0.681765,-0.440800,0.342902,-0.083822,0.363187,-0.206172,-0.007304,0.443195,-0.064592,-0.109557,0.214989,0.303623,0.033129,0.372215,-0.060287,-0.119695,-0.186036,0.021902,-0.347761,-0.236502,0.122935,0.151401,-0.127889,0.552031,0.184652,-0.226733,0.043288,-0.020112,-0.139866,-0.235646,0.085655,-0.107297,0.053268,-0.971640,0.606854,-0.183123,-0.149265,0.236003,-0.583540,0.391730,0.256307,-0.094985,0.608973,-0.522564,0.151126,-0.719435,0.394576,0.849686,-0.151093,0.415801,0.468269,-0.017064,0.098988,0.278245,-0.274581,-0.626988,0.113588,0.021226,-0.147466,-0.861695,0.162309,-0.405275,-0.074992,-0.016925,0.049772,0.026970,-0.630290,-0.280908,0.201948,-0.169523,-0.597000,-0.306306,0.071065,-0.073086,-0.153474,0.780307,-0.749714,0.232180,0.310159,0.567496,-0.662422,0.877936,0.357845,-0.034536,-0.197577,0.557120,-0.149429,-0.122071,0.282546,0.633351,0.326845,0.183162,-0.031610,-0.205086,0.514847', '1291565', '1291586', '1300202', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303897', '宠物坟场', '惊悚', '医生路易斯（Dale Midkiff 饰）因工作关系，携妻子瑞秋（Denise Crosby 饰）、女儿艾莉和儿子普吉离开芝加哥搬到了某小镇中，新家近傍公路，屋后有一条蜿蜒小路。邻居杰德（Fred Gwynne 饰）老人介绍小路通往宠物坟场，那里埋着多年来死在公路上的动物们。第一天上班，路易斯就遭遇了一位重伤死亡的患者，他仿佛看到死者对他说话，对方声称为了感谢他的救助，将阻止他接近鬼魂。不久，儿女的猫被车撞死，杰德带领路易斯将猫埋葬在山上的印第安坟场，而猫竟然复活了，担心女儿伤心的路易斯松了一口气，但复活的猫咪变得异常暴力与恶臭。数天后，小儿子不幸被车撞死，伤心欲绝的路易斯想把儿子的尸体埋入印第安坟场……©豆瓣', '戴尔·米德基夫', '玛丽·兰伯特', 7.1, 8985, 'tt0098084', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2523736932.jpg', 1.1, 5.7, 42.4, 38.6, 12.2, '0.113621,-0.309666,-0.566121,0.290924,-0.081747,-0.374186,0.812151,-0.043591,-0.391923,0.047596,0.404641,0.779341,-0.162183,0.335727,0.123187,0.013989,-0.169079,-0.180935,0.068699,-0.033064,-0.420357,-0.212467,-0.261503,-0.247598,0.048147,-0.402790,0.418966,-0.013294,0.195823,0.671013,0.025267,0.242757,-0.211367,0.203241,-0.184385,0.181825,-0.004720,-0.018056,0.113453,0.095256,-0.264907,-0.095937,0.122870,-0.013629,0.120495,0.346507,0.772475,-0.130679,-0.047081,-0.342141,0.092306,-0.307515,0.171589,0.366529,0.459754,-0.215259,0.199933,0.152235,-0.210371,-0.299390,0.054131,-0.036743,-0.202244,0.006092,-0.203374,0.179968,-0.586288,0.302955,-0.080414,0.011444,0.193451,-0.510014,0.369755,-0.011398,0.026274,0.471307,0.071177,0.118615,-0.498528,-0.019051,0.565576,-0.490929,0.102831,0.169085,-0.039605,-0.352421,0.298931,0.057516,-0.244796,-0.124948,0.436295,-0.092727,-0.698858,-0.029636,-0.404642,-0.187355,-0.365578,-0.120547,-0.175420,-0.047017,-0.307041,-0.271828,0.186090,0.003763,0.089847,0.021994,-0.136468,-0.207204,0.282095,-0.296653,0.525980,0.481340,0.397202,-0.385470,0.697032,-0.150211,0.264884,-0.121169,0.208441,0.640598,0.252909,0.352105,0.472671,-0.061087,-0.359721,0.044397,-0.428340,0.421793', '21619567', '1844413', '1401900', '1296636');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303907', '百变狸猫', '剧情', '随着人类文明的发展，城市的规模越来越大，与之相对，青山绿水则迅速减少。东京都提出“多摩新市”的概念，大肆向周边的原始森林扩张。祖辈生长在多摩丘陵的狸猫家族受到巨大冲击，随着树木花草的急剧减少，可供它们生存的食物也开始短缺。最终，鹰之森和玲之森的狸猫发生内战，战况激烈。在火玉婆婆的点拨下，两派狸猫握手言和，转而将主要目标对准破坏森林的人类。为了更好地了解对手，火玉婆婆和龟鹤和尚教授族人已被遗忘很久的变化之术。经过一段时间的艰苦修行，狸猫们终于学会了自由变化。在激进派代表权太的领导下，一部分狸猫向建筑工人发起恐怖袭击，造成多人伤亡。它们的行动虽然取得成效，然而却无法阻挡利益熏心的人类的脚步。森林被一点点蚕食，狸猫家族的命运危在旦夕……©豆瓣', '古今亭朝太時代', '高畑勋', 8.6, 88812, 'tt0110008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2156875496.jpg', 0.1, 0.8, 13, 42.8, 43.3, '0.311152,0.068752,-0.688048,0.615940,0.200383,0.081901,0.722874,0.097411,-0.177873,-0.156929,0.351666,0.350068,-0.054741,-0.376178,-0.079259,-0.533860,0.085443,-0.387519,-0.184315,0.204456,-0.097428,-0.256798,-0.387370,-0.283483,-0.224639,-0.400075,0.891946,0.362573,-0.331213,0.155481,-0.268081,0.077162,-0.187952,0.212756,0.002895,-0.085509,-0.013747,-0.075699,-0.263575,0.265879,-0.148007,-0.296899,-0.248601,0.247191,-0.088284,0.247291,0.851960,-0.368889,-0.398850,-0.524424,0.291756,-0.224199,0.179782,0.070378,0.721872,-0.087062,0.164468,0.234928,-0.044363,0.012235,-0.197427,-0.188369,-0.543814,0.067358,0.283332,0.287701,-0.485763,0.405755,0.360064,-0.112665,-0.130460,-0.580569,-0.106761,0.752210,0.354523,0.192979,-0.422825,0.132639,-0.374030,-0.354971,0.758371,-0.064084,-0.615381,-0.065183,-0.379643,-0.485025,-0.182252,-0.229461,-0.255896,-0.446613,0.473103,0.251068,-0.354318,0.700853,-0.843425,0.257723,-0.300585,-0.879643,0.114025,-0.319367,0.033183,-0.696684,-0.064860,-0.396556,-0.150361,0.151447,0.188826,-0.211133,0.721791,-0.612524,0.226495,0.672769,0.367625,-0.490251,0.046016,-0.482535,0.134236,-0.136099,-0.281437,0.341027,0.014760,0.647573,0.203993,0.017516,0.037326,-0.044291,-0.338170,0.346120', '35155748', '3006772', '35058077', '24879819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303910', '天降奇兵', '动作', '1899年的新旧世纪之交，欧洲各国处于难得的和平时期，然而一股新近崛起的邪恶势力在首脑“幽灵”的策划下，凭借当时人们闻所未闻的先进武器，在各国间制造误会与摩擦，妄想点燃世界大战的火焰。英国政府邀请隐居非洲的传奇冒险家艾伦·考特曼（Sean Connery  饰）出山解决此次危机，艾伦虽对冒险心生厌倦，但不忍非洲大陆陷入战火，遂与女吸血鬼米娜、化身博士海德、透明人斯基纳、不老不死的英俊青年格雷、尼摩船长、美国特工汤姆·索亚组成绅士联盟，乘坐尼摩船长的鹦鹉号潜艇前往威尼斯阻止幽灵的阴谋。经威尼斯一役，联盟发现此次行动居然是幽灵安排好的棋局，一切只为取得联盟成员各自的超能本领以便实现他更大的野心，被激怒的绅士联盟前往冰雪覆盖下的北国，对幽灵的组织发起了最后的决战……©豆瓣', '肖恩·康纳利', '斯蒂芬·诺林顿', 7.1, 25107, 'tt0311429', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2177655215.jpg', 1, 6.4, 43, 38.1, 11.5, '0.269922,0.124538,-0.626983,0.468891,0.168708,-0.037773,0.344139,-0.028827,-0.424370,-0.260391,0.373312,0.623560,-0.099933,-0.147313,0.421706,-0.046804,-0.454251,-0.616928,-0.207949,-0.031261,-0.036969,-0.399964,-0.539346,-0.238252,-0.037217,-0.502718,0.877257,0.308245,-0.383835,0.299883,0.034812,0.429122,-0.037531,0.238232,0.015228,-0.359601,0.159326,-0.167116,-0.390272,0.301037,-0.394235,0.088992,-0.126186,0.089895,-0.138744,0.238257,0.457944,-0.607508,0.184383,-0.535576,0.254032,-0.605381,0.029574,0.095824,0.433854,0.074085,-0.236817,0.280947,0.209411,-0.059027,-0.177358,-0.235319,-0.551432,0.133238,0.097890,0.257057,-0.400156,0.293796,-0.165208,0.166792,0.051532,-0.102529,-0.020001,0.552431,0.488646,0.111155,0.124385,0.384372,-0.466565,-0.114493,0.818210,0.062998,-0.374347,-0.252018,-0.099139,-0.482103,-0.075068,-0.347439,-0.244153,-0.111978,0.170889,-0.093027,0.078806,0.673626,-0.951663,-0.116514,-0.481642,-0.064094,0.094387,-0.213720,-0.121197,-0.919715,-0.153786,0.003150,-0.050176,0.157607,0.275858,0.016391,0.637482,-0.791828,0.196147,0.427412,0.270876,-0.239960,0.553792,0.030165,-0.037561,-0.330132,-0.081148,0.219459,0.214174,0.303930,0.017647,0.115354,-0.083807,-0.215229,-0.037413,-0.125638', '2369613', '20274039', '26290398', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303913', '南海十三郎', '剧情', '开片是说书人因聚众滋事，被警察（黄霑 饰）带到了警局问话，借说书人之口讲述了粤剧金牌编剧——南海十三郎艺海浮沉的一生。作为江太史公的十三子，江誉镠（谢君豪 饰）自由顽皮，出入名流场所。一次偶然的舞会，他遇到了上海的千金小姐莉莉（吴绮莉 饰），然而双方有缘相逢，无 份结亲。后来，他跟随她来到上海，竟落得穷困潦倒。2年后，回到了广东的家中，他已被学校除名。当时太史公已经年事已高，他便天天去看戏，从不受戏班老板薛老五赏识，到后来成为御用编剧一鸣惊人，人送绰号——南海十三郎。然而，时局动荡，他到了江西写剧本慰劳前线战士，因看不过同行媚俗之作，愤然出手，不欢而散。这时一次车祸，让他与昔日恋人重逢，可惜她已嫁给老外。十三郎郁郁寡欢，后来入寺修行，却在一次代人祈福的对话中，得知了自己家道中落的败局，他疯了……©豆瓣', '谢君豪', '高志森', 9.3, 61739, 'tt0134836', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578760496.jpg', 0.2, 0.4, 4.4, 23.8, 71.2, '0.037380,-0.070754,-0.556105,0.322671,-0.060545,-0.474690,0.382469,0.147062,-0.755314,-0.232621,0.235732,0.720059,-0.214465,0.385392,0.289158,0.024606,0.070762,-0.523642,0.178871,-0.159469,0.050537,-0.209546,0.138292,-0.025584,-0.247789,-0.034398,0.363647,0.256520,-0.104245,0.510234,0.176628,0.204291,-0.212159,0.451911,-0.345094,0.316407,0.084523,0.182809,-0.119057,0.078503,-0.130458,-0.436110,-0.363226,-0.033611,0.190354,0.300536,0.602600,0.028530,0.021750,-0.036520,0.358559,-0.098124,-0.135983,0.035554,0.401237,0.164345,0.333177,0.300889,-0.131729,-0.034134,-0.302713,-0.004412,-0.097182,0.167731,0.068629,-0.024792,-0.609841,0.594688,-0.239833,0.020783,-0.257261,-0.191828,0.183299,0.078292,0.302327,0.082116,0.056107,0.100075,-0.391851,0.555557,0.723341,0.070058,-0.073092,0.222216,0.348611,-0.281115,0.321395,-0.445821,-0.276954,0.299091,0.356945,-0.115909,-0.124774,0.177070,-0.248707,-0.381377,-0.415706,0.135728,0.244357,-0.107016,-0.142572,-0.469597,-0.086829,-0.197322,-0.249798,-0.173041,0.264430,-0.147135,0.508149,-0.565939,0.188574,0.338559,0.060821,-0.541802,0.775521,0.217396,0.153268,-0.085048,0.198767,0.007948,0.153974,0.320056,0.153463,0.072011,-0.169047,-0.202015,-0.343087,0.140295', '1308035', '2080130', '25721544', '1307922');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303917', '阴阳师', '剧情', '公元794年，日本桓武天皇时期，京都长冈被其胞弟早良亲王怨灵诅咒，天灾人祸不断。桓武天皇被迫迁都平安京，由此开启四百年平安时代序幕。彼时权贵内部斗争激烈，人民生活疾苦，世间因此怨灵丛生，人、鬼与怪物屏息同栖。隶属于宫廷阴阳寮的阴阳师们，作为平衡天、地、人、鬼间矛盾的存在，自此活跃在历史舞台上，其中最为耀眼的便是身世成谜的安倍晴明（野村万斋 饰）。右近卫中将源博雅（伊藤英明 饰）受托拜访安倍晴明，被所目睹的奇异景象及晴明的个人魅力深深折服；晴明亦被博雅正直的品德吸引。故事便从两人宿命相识，结下珍贵情谊开始。宫廷内近来异事频发。左大臣藤原师辅之女诞下敦平亲王，婴儿降世却身负诅咒。晴明招来蜜虫（今井绘理子 饰）和神秘女子青音（小泉今日子 饰），与博雅一同化解恶咒，却反遭诬陷。原来一切皆是阴阳头道尊（真田广之 饰）所为。他利用左右大臣间矛盾与后妃间争宠频生事端，更欲召唤出150年前的最强怨灵早良亲王，将平安京彻底颠覆……影片根据梦枕貘《阴阳师》系列小说改编。', '野村万斋', '泷田洋二郎', 7.8, 35311, 'tt0355857', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1001267362.jpg', 0.5, 2.8, 26.2, 45.9, 24.6, '-0.043301,0.232776,-0.214820,0.138396,0.291322,0.175500,0.382230,0.133383,-0.655847,-0.581758,0.322184,0.337772,-0.255817,-0.032147,0.292874,-0.078036,-0.096784,-0.654911,-0.120532,-0.075206,0.134182,-0.074198,-0.198780,-0.151761,-0.339444,-0.601215,0.615444,0.274768,0.066651,0.176798,-0.079598,0.637405,-0.625005,-0.021816,0.055942,0.028112,-0.144642,0.019506,-0.340528,-0.106393,-0.470752,-0.321518,-0.319929,0.101791,-0.287525,0.040632,0.441324,-0.776788,0.173927,-0.485573,0.343451,-0.047053,-0.337120,0.357351,0.267293,0.154250,0.250606,0.398170,-0.024244,-0.283404,0.014649,0.143106,-0.308471,-0.056816,0.139207,0.108456,0.127458,0.341738,0.053072,-0.219626,0.146565,-0.174893,0.168182,0.153195,0.451814,0.189184,-0.202685,0.096317,0.018032,0.077606,0.534468,0.048698,-0.300002,-0.163820,-0.117027,-0.510509,-0.158460,-0.343043,-0.090193,0.004188,0.274459,0.180711,0.308887,0.880353,-0.359297,-0.336739,-0.328733,0.357601,0.382559,-0.083905,0.005734,-0.378344,-0.205584,-0.189583,-0.159264,-0.139369,0.558380,-0.177373,0.634275,-0.530281,0.172178,0.366615,0.148792,-0.254114,0.338708,-0.161115,0.100686,-0.210711,-0.244433,0.127154,0.067015,0.234481,-0.082579,0.087126,-0.315402,0.159414,-0.257434,0.075885', '27667334', '30284141', '1763916', '26850330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303944', '鬼咬鬼', '喜剧', '茅山道士九叔（林正英 饰）的大徒弟肥宝（洪金宝 饰）与茶肆老板的女儿珠女（龚慈恩 饰）系指腹为婚，但其岳丈嫌弃肥宝贫穷，欲将女儿许配富家子弟史公子。为了筹备高额聘礼，肥宝盘下粥摊赚钱。谁知第一个顾客竟然是个女鬼，肥宝尾随其后，进而得知这个名为小红（王文君 饰）的女鬼为了照顾失明的母亲而盘桓人间，于是冒充小红的表哥将母女二人接至家中。肥宝师弟小海（孟海 饰）得知，请求小红色诱史公子，以帮助师兄赚得钱财。不想却被史家的巫师识破……©豆瓣', '洪金宝', '刘观伟', 7.5, 12122, 'tt0080828', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2047112707.jpg', 0.4, 2.7, 37.5, 40.9, 18.5, '0.190469,0.004422,-0.096190,0.453271,-0.279951,-0.418291,0.207046,0.255444,-0.455318,-0.337078,0.359354,0.577463,0.111053,0.262219,0.129177,0.178099,0.240932,-0.186102,-0.017448,-0.050482,0.095060,-0.270557,-0.105000,-0.153260,-0.408245,-0.031920,0.229564,-0.104980,0.100397,0.418580,0.428133,-0.007624,-0.268954,-0.065678,-0.113818,0.272388,-0.157964,-0.063423,-0.392733,0.096091,0.037250,-0.119067,0.266780,-0.150831,0.160553,0.226045,0.598111,-0.338132,0.067300,-0.385709,0.334426,-0.062876,0.196968,0.125101,0.157598,0.030650,0.515239,-0.085937,-0.241656,-0.352056,0.384964,-0.073604,-0.189386,0.345728,0.471808,-0.192786,-0.535701,0.181035,-0.340602,-0.044712,-0.050665,-0.497165,0.128297,0.228322,0.173809,0.089676,-0.126459,-0.023362,-0.387855,0.368858,0.232645,-0.237506,0.564037,0.198175,-0.037842,-0.280748,0.538166,-0.326306,-0.462641,0.220919,0.213832,0.011576,-0.105103,0.165735,-0.256647,-0.302718,-0.424389,0.413823,0.204796,-0.271861,-0.170862,-0.095143,-0.069252,-0.021896,0.053677,-0.023428,0.513706,-0.047607,0.661339,-0.640357,0.037265,0.269817,0.326912,-0.517210,0.534260,-0.230973,0.320000,-0.201258,-0.348896,-0.367540,0.182146,0.054914,0.180378,0.099140,-0.062861,-0.297063,0.051772,-0.161245', '1416722', '3445516', '1292720', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303948', '包法利夫人', '剧情', '一次出诊中，包法利医生（让-弗朗索瓦·巴尔梅 Jean-François Balmer）和年轻的女孩艾玛（伊莎贝尔·于佩尔 Isabelle Huppert 饰）相遇了，艾玛的纯情和美丽让医生迅速坠入了情网，两人随即结婚。婚后的生活并不如艾玛所幻想的那样充满了乐趣和激情，是帅气的雷翁（卢卡斯·贝尔沃克斯 Lucas Belvaux 饰）的出现让艾玛重新快乐了起来，但他的离开带来的则是更深的痛苦和绝望。富豪鲁道夫（克里斯托弗·马拉沃伊 Christophe Malavoy 饰）贪恋艾玛的美色，给予了她诸多的空洞承诺，而为了配得上鲁道夫，艾玛不惜赊账购入首饰与华服。在约定好私奔的那一天，鲁道夫失约了，大受打击的艾玛一病不起。在丈夫的照料下，艾玛渐渐康复，在一场音乐会上，她与雷翁重逢了，与后者打的火热的日子里，艾玛丝毫没有察觉自己早已债台高筑。而当催债的传票出现在眼前时，被所有男人抛弃的艾玛选择了死亡。', '伊莎贝尔·于佩尔', '克洛德·夏布洛尔', 7.5, 8409, 'tt0102368', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1739873051.jpg', 0.4, 2.5, 34.1, 47.7, 15.4, '0.243857,0.008526,-0.759433,0.513894,-0.281279,-0.651274,1.038912,0.060765,-0.420087,-0.105574,-0.010519,0.875459,-0.498844,0.486490,0.446333,0.197091,-0.229200,-0.789084,-0.073867,0.007721,-0.310779,-0.538280,-0.126148,-0.129154,0.008711,-0.438557,0.525502,0.094855,-0.019737,0.669742,0.370441,0.200923,0.103360,0.608083,-0.203262,0.126380,-0.039063,-0.028050,-0.274631,0.321504,0.175062,-0.136229,-0.011508,0.297697,-0.096489,0.223730,0.685242,-0.405636,-0.091644,-0.104023,0.362143,-0.164697,0.087386,0.288187,-0.101140,-0.201547,0.062089,0.031628,-0.457188,-0.121072,0.286397,-0.080213,-0.605685,0.135879,-0.101167,0.282150,-0.769341,0.649648,-0.087119,-0.041301,0.230997,-0.200335,0.214501,0.201113,0.211002,0.412423,-0.252363,-0.037545,-0.508891,0.192220,0.529810,0.192437,-0.170085,0.482722,-0.404718,-0.326456,0.096138,-0.088366,-0.651019,-0.059548,0.384244,0.111738,-0.134230,0.368805,-0.655343,-0.165085,-0.374757,-0.243367,-0.162222,-0.489933,-0.142366,-0.569638,-0.283685,-0.543679,-0.449234,0.071968,0.070063,-0.381896,0.585256,-0.944804,0.295358,0.517196,0.368275,-0.339808,0.627628,0.224014,0.160084,0.064020,-0.108831,0.500447,0.016744,0.175527,0.378031,0.372716,-0.165376,0.273573,-0.417024,0.900449', '1309172', '3111650', '3230121', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303976', '白头神探3', '喜剧', '正在监狱中服刑的爆炸专家洛高接受了恐怖集团一项五百万美元酬劳的任务：用薄如纸片的新式炸弹在美国制造恐慌。另一边，白头神探弗兰克（莱斯利•尼尔森 Leslie Nielsen 饰）光荣退休，那些惊心动魄的战斗似乎瞬间就成为了往事，警方获悉恐怖爆炸计划后邀请弗兰克再次出山，令其进入医院卧底，以接近洛高的情人谭雅。妻子珍（普瑞希拉•普雷斯利 Priscilla Presley 饰）对于孩子的渴望愈发强烈，但再次为公众安全疲于奔命的弗兰克毫无亲昵的多余体力，伤心的珍离家出走。弗兰克二次卧底进入监狱，打入洛高一伙并与他成功越狱，自此留在洛高身边监视，此时珍找到弗兰克，卷入了卧底行动。洛高计划在奥斯卡颁奖典礼上安放炸弹，而能挽救奥斯卡的，只有弗兰克……©豆瓣', '莱斯利·尼尔森', '彼得·西格尔', 7.8, 16871, 'tt0110622', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1036759304.jpg', 0.4, 2.5, 28.5, 45.5, 23.1, '-0.118757,0.108618,-0.554623,0.243459,0.179201,-0.201289,0.566434,0.096946,-0.243073,-0.255575,0.066984,0.508311,-0.337165,0.067283,0.081822,-0.125596,-0.357025,-0.636435,-0.255170,-0.184243,-0.367499,-0.562745,-0.068681,-0.265178,0.253658,-0.311726,0.648817,0.219751,-0.316062,0.445641,0.232495,0.572615,-0.165986,0.326438,-0.004038,-0.121027,0.249283,-0.090213,-0.494952,0.192982,0.102170,-0.009069,0.141892,0.110321,0.269311,0.340140,0.615645,-0.295573,-0.220362,-0.057316,0.262199,-0.215751,-0.142177,0.005804,0.094666,0.110908,-0.042028,0.078126,-0.255745,0.204635,-0.014824,-0.299604,-0.721169,0.010499,0.010010,-0.025038,-0.160812,0.074465,-0.159185,0.490365,0.140487,-0.014714,0.191755,0.301481,0.003390,0.204277,-0.331497,0.354298,-0.302501,0.221333,0.494410,-0.238263,-0.230868,0.213655,0.033188,-0.218879,0.122653,-0.323764,-0.103028,0.050731,0.272497,0.058928,0.179642,0.193991,-0.311178,-0.213614,-0.690436,-0.088276,-0.083961,-0.208748,-0.019893,-0.708182,-0.097209,0.190935,-0.243989,0.206906,-0.112569,-0.419602,0.427853,-0.355553,0.413558,0.590879,0.166502,-0.335138,0.207045,-0.229862,0.158393,-0.444249,-0.108526,0.454267,0.219954,0.297216,0.125818,0.082870,-0.114456,-0.300820,-0.281632,0.218391', '2369613', '2028645', '27073234', '7916027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303983', '龙在边缘', '惊悚', '志成（古天乐 饰）还在警校的时候便被派往潜入黑社会的洪兴社做卧底，智勇的志成后来成为了帮中老大飞龙（刘德华 饰）的赏识。多年来上司都要求志成交出飞龙的犯罪证据，但志成发现飞龙不过是一名商人而已，更发现飞龙有改邪归正的意图。飞龙有一名好兄弟阿豹（黄秋生 饰）因为被出卖， 被警方打至重伤瘫痪了，儿子文俊（谭耀文 饰）决心要为父亲报仇，更要夺得江湖上老大的位置，于是他有了陷害飞龙的阴谋。果然，飞龙这时不但被警方通缉，儿子的生命更受到了文俊的威胁。志成及时赶到，救走了飞龙，但飞龙的妻子还是死去了。悲伤之极的飞龙要找文俊报仇，志成不想看到飞龙因杀人被捕，于是表明了自己的身份……©豆瓣', '刘德华', '霍耀良', 7.3, 20018, 'tt0219887', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1630232391.jpg', 0.5, 3.7, 42, 39.4, 14.4, '0.313062,-0.220827,-0.468007,0.266815,-0.130479,-0.447511,0.322880,0.177715,-0.680893,-0.152579,0.796579,0.650230,0.286541,-0.082798,0.033863,0.061925,-0.065483,-0.595816,0.262166,-0.180953,0.088885,-0.431216,-0.211347,0.195287,0.057661,-0.236055,0.457725,-0.320797,0.031632,0.720456,0.229483,0.365416,0.183375,0.365557,-0.044645,0.232450,0.260678,-0.291846,-0.271201,0.410753,0.199843,-0.347075,-0.055612,0.350902,-0.356767,0.455025,0.515624,-0.141594,-0.264389,-0.284659,0.271123,-0.626067,0.087508,0.093520,0.525942,0.005216,0.153262,0.697935,-0.198631,0.214302,-0.042117,0.360427,-0.967994,0.189131,0.081062,0.248545,-0.665593,0.425297,-0.290003,-0.104417,0.143078,-0.415449,0.344623,0.149180,0.010474,0.101460,-0.422568,0.265414,-0.866782,-0.086940,0.585579,-0.341900,0.395435,-0.082845,0.376273,-0.131518,0.425530,-0.374007,-0.032671,-0.037107,0.472374,-0.015321,-0.433563,-0.020552,-0.553930,-0.058777,-0.668516,0.090659,-0.261312,-0.206197,-0.279277,-0.042291,-0.207702,-0.110862,-0.189392,-0.197223,0.013502,-0.231496,0.640807,-0.853744,-0.032648,0.382408,0.408600,-0.725219,0.455202,0.179642,-0.093252,-0.071382,-0.157641,-0.438923,0.117201,0.555105,0.340811,-0.097492,0.140607,-0.764140,-0.036059,-0.021165', '1410695', '1793491', '1877596', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1303989', '喷火女郎', '喜剧', '叉烧（郑丹瑞 饰）是一个不务正业的小青年，整体装神弄鬼骗钱。一天，叉烧的一个租客——在夜总会当妈妈桑的大B（叶德娴 饰）的家里来了一个客人，她美丽的外甥女云云（邱淑贞 饰）。大B用尽千方百计将美丽的云云哄到夜总会当舞女，想着从她身上大赚一笔。一个晚上，黑社会老大炮哥到夜 总会消遣时遇到了云云，炮哥垂涎她的美色，找人把云云捉走了。怎知谁也料不到云云这个弱女子竟然拥有超能力——会喷火，关键时候她用自己的超能力脱身了。不久叉烧就得知了云云的这个本领，于是，一个坏主意计上心头……©豆瓣', '邱淑贞', '郑丹瑞', 6.2, 5355, 'tt0105119', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2631611618.jpg', 2.6, 15.2, 58.9, 16.9, 6.5, '0.379012,0.198257,-0.433609,0.352851,-0.461924,-0.318195,0.478792,0.144052,-0.194229,-0.276670,0.240834,0.799267,-0.360291,0.354758,-0.118426,0.326644,0.080171,-0.496796,0.081533,-0.062850,-0.175111,-0.007353,-0.383509,-0.179731,0.015286,0.276035,-0.111620,-0.009793,-0.012975,0.219468,0.437666,-0.092379,0.244626,0.282015,-0.313410,0.103286,0.157438,0.040274,0.358620,0.340178,0.149429,-0.369068,-0.010992,0.063015,-0.063600,0.240844,0.605511,-0.023283,-0.137244,-0.105349,0.324426,-0.161560,-0.024250,0.068139,0.048267,-0.290411,0.143013,-0.249192,-0.367550,0.169160,0.295573,-0.109104,-0.703167,-0.027191,-0.017304,-0.197678,-0.593555,0.054375,-0.047593,-0.192827,0.073947,-0.242327,0.341908,0.096471,-0.033108,0.331361,-0.192730,0.152037,-0.791712,0.371111,0.393495,-0.060271,0.156714,0.291904,0.108207,-0.150894,0.206012,-0.341571,-0.316588,-0.075518,0.428217,-0.306863,-0.419652,-0.164759,-0.668337,0.068050,-0.290456,0.200248,-0.026531,-0.264038,-0.358919,-0.092662,0.008519,-0.195174,-0.186464,0.433325,0.344400,0.019566,0.997475,-0.606048,-0.029675,0.808417,0.203141,-0.566828,0.569145,-0.022522,-0.223578,0.024698,-0.102642,-0.348035,-0.048210,0.401885,0.250277,0.480943,-0.043069,-0.222002,-0.278477,0.462138', '24284209', '1302661', '27602116', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304002', '打工皇帝', '喜剧', '面包厂的阿忍（许冠杰 饰）和拖车厂的阿神（徐克 饰）、阿庆（泰迪罗宾 饰）因一场小车祸双双丢掉工作。阿忍面对抚养自己长大母亲只得谎言应付，阿庆则跟随好友阿神回家，暂时住在同一屋檐下。所谓不打不相识，三人因此事件却成为了好朋友，最终进入皇帝面厂工作，但上班第一天便遇到了麻烦。车间主任（吴孟达 饰）和厂长任人唯亲，颠倒黑白，为包庇一个犯错的女人企图开除三人顶包。多亏董事长女儿阿美（王祖贤 饰）帮助才保住工作。自此，三个好朋友连同阿美与腐败的厂长一伙展开了笑料百出的斗智赛……©豆瓣', '许冠杰', '徐克', 6.9, 8621, 'tt0088981', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2509420935.jpg', 0.9, 6.8, 50.7, 30, 11.6, '-0.035473,-0.243575,-0.190117,0.106760,-0.038824,-0.482509,0.279843,0.500981,-0.305209,-0.452256,0.245475,0.561285,0.040219,0.157263,0.258752,-0.461787,-0.256289,-0.524818,0.232017,0.193272,-0.106842,-0.376616,-0.027120,-0.086747,-0.186587,0.052048,0.546363,-0.128136,-0.035348,0.451927,0.335150,0.034289,-0.278434,0.169572,0.053553,0.049631,-0.008000,0.131637,-0.672119,0.191961,-0.066835,0.001212,0.017323,-0.218331,0.571868,0.308223,0.553409,0.001951,-0.164459,-0.261133,0.035209,-0.387084,-0.064098,-0.123114,0.308699,0.158507,0.429545,0.373361,-0.402008,0.025479,0.088398,-0.148935,-0.369795,0.121570,0.281675,-0.257573,-0.619545,0.318267,0.003428,-0.047704,0.111399,-0.271437,0.246100,0.380938,0.309769,0.432987,-0.154315,0.278879,-0.305716,0.136267,0.510722,-0.174478,0.215421,0.207074,0.341402,-0.034330,0.162979,-0.251525,-0.347113,0.084061,-0.012284,-0.147324,-0.027319,0.006256,-0.625945,-0.385055,-0.229844,0.188621,0.303821,-0.476351,0.262851,-0.387451,0.162066,0.056960,-0.368790,0.082351,0.081608,-0.157440,0.431337,-0.547434,0.109923,0.189588,0.249954,-0.734085,0.448476,0.299017,0.558587,-0.430813,-0.080455,-0.088776,0.117744,0.102151,0.109231,0.120322,-0.137347,-0.275017,-0.197170,-0.247177', '30345227', '3598221', '4723944', '1295316');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304021', '人吓人', '喜剧', '纸扎店小工朱宏利（洪金宝 饰）自小由道士二叔公（林正英 饰）带大，朱宏利道术未习多少，行事偶而颠倒，却有一副正气心肠，因不肯拖累指腹为婚的未婚妻阿云（钟楚红 饰），时常给人家冷脸。朱宏利好友马麟祥（午马 饰）外出闯荡，返乡时却变成了一具尸体，一同回来的还有马麟祥怀孕的妻子跟几个男伴，朱宏利感事有蹊跷，出力调查却一无所获。几日后，马麟祥冤魂找到朱宏利求助，原来马麟祥返乡时并未身亡，只为伙同他人盗取自家祖上的陪葬品而出此下策，却不料假戏成真，被同伙取了性命。心灰意懒的朱宏利拗不过冤魂骚扰，请来二叔公做法帮好友报仇，结果自己丢掉了肉身以至丧命。悲痛欲绝的阿云经二叔公指点，欲与鬼差斗计抢回朱宏利的魂魄……©豆瓣', '洪金宝', '午马', 7.4, 17275, 'tt0084587', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2004837783.jpg', 0.5, 3, 38.8, 40.7, 17.1, '-0.308048,-0.145023,-0.399681,0.211754,-0.224161,-0.700041,0.646151,0.175698,-0.653092,-0.616436,-0.223310,0.355084,-0.010702,0.500060,-0.041324,-0.205831,0.186385,-0.156325,-0.028460,0.156260,-0.218006,-0.151810,0.087198,-0.293395,-0.284755,0.045030,0.067460,0.380136,-0.087666,0.412630,0.497079,0.149887,-0.318425,0.439943,-0.195839,0.278286,-0.375585,0.179248,0.057694,-0.085464,0.287537,-0.479184,-0.135762,-0.119373,0.147445,0.730502,0.537843,-0.035456,0.203722,-0.301706,0.343626,-0.253982,0.119007,-0.067611,0.267783,-0.064272,0.082092,-0.152739,-0.223529,-0.153040,0.157424,0.014482,-0.515450,0.181965,0.215454,-0.365111,-0.822847,-0.032729,-0.131927,0.498892,-0.189249,-0.283459,0.285695,0.167294,0.225921,-0.105253,0.055804,0.153183,-0.505601,0.311761,0.455152,-0.187755,0.301796,-0.041021,0.392985,-0.441140,0.243493,-0.392691,-0.108629,0.031986,0.688879,-0.131953,0.189986,-0.222779,-0.269993,-0.660448,-0.270432,0.581031,0.053177,-0.172059,0.003466,-0.096482,0.350415,-0.183033,-0.049269,0.019493,0.169579,-0.202431,0.316683,-0.348258,0.263093,-0.084110,0.054211,-1.073613,0.575111,0.179420,0.197286,-0.103144,0.266002,0.035973,0.613920,0.253523,0.666156,-0.165383,-0.181436,0.042391,-0.104751,-0.038185', '1302110', '1297497', '3998385', '1305201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304022', '大腕', '喜剧', '尤优（葛优饰）接到个美差，拍一部宣传记录片记录好莱坞大腕导演泰勒（唐纳德•萨瑟兰饰）在中国拍摄影片的工作过程。一开始工作顺利，但随着制片人托尼（保罗•莫索尔斯基饰）的到来，事情起了变化。闲下来的尤优和泰勒、泰勒的助手露茜（关之琳饰）到寺庙游览，三人相处得非常愉快。不料几天后泰勒因心脏病发作，生命垂危，他希望尤优能为自己操办个喜丧葬礼，尤优揽下活儿。尤优找到老同学王小柱（英达饰），泰勒将死对王来说是一个难得商机，对托尼来说也是如此，惟有尤优和露茜是怀着朴实感情面对此事。王小柱开始出谋献策，拉了好多赞助，众多商家不惜花大钱在葬礼上做广告。局面变得无法收拾，却不料，在葬礼的背后另有玄机。©豆瓣', '葛优', '冯小刚', 7.9, 199560, 'tt0287934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1276429294.jpg', 0.4, 2, 23.4, 49.9, 24.4, '0.213058,0.014968,-0.643207,0.303208,0.195218,-0.406416,0.585771,0.207243,-0.517922,-0.551918,0.084019,0.496956,-0.470599,0.277168,0.239280,-0.311106,-0.413244,-0.368742,0.014721,0.269759,-0.133361,-0.166511,-0.122822,-0.300110,-0.346837,-0.180663,0.373780,-0.029996,-0.077586,0.511448,0.412786,0.322168,0.205252,0.424582,-0.020648,0.047706,0.010924,0.056215,-0.420586,0.330362,0.148520,-0.103754,-0.389042,0.268369,0.285109,0.352069,0.324804,0.004042,-0.149770,0.096176,0.474721,-0.357709,0.115022,0.092158,0.330287,0.174411,0.227657,0.064001,-0.473829,0.114903,0.114636,-0.346003,-0.566811,0.100166,-0.029907,0.355451,-0.701533,0.150933,-0.226523,0.005815,-0.174564,-0.612152,0.204653,0.469072,0.199339,0.236987,0.085697,0.323480,-0.471932,0.298478,0.670296,0.075489,0.145622,0.420076,-0.056080,-0.477242,-0.077558,-0.029089,-0.418280,0.109015,0.289271,-0.333443,0.210789,0.020028,-0.201457,-0.233961,-0.119577,-0.248496,-0.036887,-0.386346,-0.098848,-0.771426,-0.063409,-0.116182,-0.461581,-0.122363,0.225685,-0.222448,0.655880,-0.589214,-0.009531,0.174387,-0.204831,-0.251497,0.540827,0.194028,0.212520,-0.283490,-0.028747,-0.100622,-0.018074,-0.022990,0.348059,0.247647,-0.143998,-0.374298,-0.210951,0.418049', '26259202', '27060077', '24751811', '5992865');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304026', '我要复仇', '剧情', 'Ryu（申河均饰）是名聋哑青年，自父母去世一直和姐姐相依为命。在特殊学校里，他遇上了装作失聪的女友（裴斗娜饰），二人感情发展不错。可是姐姐却患上了绝症，需要移植肾脏以维持生命。他本想通过黑市以自己肾脏换取适合姐姐移植用的肾脏，却遭诈骗，损失自己肾脏外，还被骗去所有的钱。当有合适姐姐的肾脏时，他却没有医药费。女友提议他去绑架有钱人的小孩再索取赎金，并说这种绑架不算是罪过。他们看上了工厂老板东劲（宋康昊饰）的女儿，对离了婚的东劲而言，生命中最重要的就是女儿。遭绑架后，他并没有报警而是准备赎金以求换回女儿，但故事并没有朝好的方向走去……©豆瓣', '宋康昊', '朴赞郁', 7.9, 69858, 'tt0310775', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p671348030.jpg', 0.5, 2.1, 22, 51.2, 24.3, '0.011676,-0.065536,-0.410086,0.346969,-0.569701,-0.286427,0.872115,0.007468,-0.315543,-0.178743,-0.057163,0.576735,0.539842,0.128530,-0.181609,0.415144,-0.168264,-0.408831,0.221540,-0.197730,-0.356480,-0.666473,0.004894,-0.043686,-0.261463,-0.220323,0.443614,-0.128277,-0.351357,0.104983,0.106648,0.119220,0.151931,0.652765,-0.276641,0.172253,-0.230660,0.264955,-0.232015,0.318600,0.291731,-0.202836,0.134925,0.255197,0.252036,0.709931,0.314062,-0.150713,-0.074005,-0.218344,0.320240,0.040290,-0.094288,0.162984,0.095308,-0.174441,0.565416,0.038955,-0.300453,-0.108800,0.129465,0.001499,-0.751488,-0.121050,0.206953,-0.084107,-0.669935,0.338471,-0.077602,-0.099182,0.225556,-0.311720,0.350132,0.298176,0.033967,0.251664,-0.384322,-0.108026,-0.563130,0.361554,0.664034,-0.108460,-0.051650,0.586222,-0.413153,-0.515848,0.200990,-0.254862,-0.284837,0.232593,0.092366,0.106109,-0.297222,-0.152025,-0.186043,0.093643,-0.080919,-0.094253,0.090937,-0.399309,0.122794,-0.295965,0.077014,-0.396462,-0.387528,0.013900,0.173176,-0.420397,0.480638,-0.627745,0.007541,0.683674,0.630254,-0.971179,0.718449,0.105879,0.098432,-0.269700,-0.256054,0.199126,-0.079019,0.456476,0.124837,-0.070689,0.375518,-0.110855,-0.192305,0.236769', '1307873', '1306916', '26718282', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304034', '小孩不笨', '剧情', 'EM1、EM2、EM3，这几个让人摸不清头脑的数字，实则是新加坡小学的分班制。EM1代表学习最优，EM2代表中等，而EM3则是垫底。小孩们被分到不同的班级，打上了聪明、中庸和笨蛋的标记。这让许多小孩都表示不满。其中，国斌、Terry、文福，这3位来自EM3的小孩则是反抗的最激烈的几个。三个小孩不但志同道合，而他们的家长也有有着这样那样的联系，但是都不怎么友好。在三位笨小孩无助彷徨时，班上来了位新老师，她的鼓励让小孩们意识到自己并不比别人差。文福等人成绩均有提高。而另一边，三位小孩的家庭也因为患难看到了真情。一切，都朝着好的方向发展着……©豆瓣', '向云', '梁智强', 8, 8210, 'tt0307681', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497092424.jpg', 0.4, 1.7, 22, 49.9, 26.1, '0.551642,-0.365320,-0.664011,0.665544,-0.445853,-0.076922,0.670457,0.215627,-0.525847,-0.147580,0.191083,0.662253,-0.004402,0.313532,0.060342,-0.401739,-0.033468,-0.608798,-0.288032,-0.373361,-0.599632,-0.478865,-0.133514,-0.162632,-0.303760,-0.174609,0.423505,-0.158444,-0.163385,0.546205,0.273124,0.059705,0.162343,0.412282,-0.356104,0.076725,-0.014835,0.112111,0.273360,-0.049710,-0.067902,0.162685,-0.315379,0.225821,0.055898,0.633560,0.727206,-0.097931,-0.254954,-0.012197,0.226669,-0.149529,-0.227268,0.177897,0.484105,-0.063487,0.143916,0.041921,0.117655,0.247543,-0.097236,0.189835,-0.972087,0.262266,0.309337,0.190923,-0.706985,0.694049,0.374628,-0.484034,0.094095,-0.183466,0.139618,0.452944,-0.079756,0.501984,-0.271255,-0.082611,-0.521697,0.026700,0.692257,0.215490,-0.411113,0.262846,-0.427506,-0.532286,-0.039281,-0.374012,-0.436886,0.061421,0.101390,0.219437,-0.136879,-0.005939,-0.537364,0.196867,0.182557,-0.159224,-0.179736,-0.876210,0.073760,-0.668329,0.043584,-0.586278,-0.412364,0.067992,0.136837,-0.307196,1.446425,-0.900318,-0.139890,0.484871,0.341325,-0.710125,0.890921,0.219609,0.013950,-0.321627,-0.347214,-0.121921,0.198476,0.128308,-0.018838,0.598497,-0.264267,-0.253036,-0.292918,0.550457', '27602116', '24284209', '26348103', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304038', '魔法灰姑娘', '喜剧', '艾拉（安妮•海瑟薇 饰）出生与一个色彩斑斓的奇幻世界中，每个在这里出生的孩子都会得到仙女的“礼物”。而可爱的艾拉得到的“礼物”是服从。自此，无论是多苛刻的要求，只要一声命令，艾拉便会一一照办。艾拉母亲去世前便叮嘱她以后要用自己内心的真实信念去抗行咒语，而且必须找到下咒语的魔女才能完全解除咒语。此时的艾拉已经饱受继母及继母女儿的折磨，而她告诉自己必须要找到当年的魔女。但一切进行得并不顺利，而在一个偶然的机会中，她认识了英俊的王子查尔。自小父母便离世的查尔十分听从叔叔的话。艾拉跟王子很快便坠入了爱河，当回到城堡的时候，艾拉发现了查尔叔叔的秘密，而且她身上的咒语更受到了查尔叔叔的利用……©豆瓣', '安妮·海瑟薇', '汤米·奥·哈沃', 6.6, 56533, 'tt0327679', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2222938875.jpg', 1.2, 9.1, 54.2, 27.3, 8.2, '0.183609,0.223028,-0.551249,0.817118,-0.253425,-0.371228,0.812496,-0.102362,-0.618372,-0.191355,0.081879,0.983350,0.113826,0.397888,0.367660,0.432258,-0.436059,-0.605394,0.113415,-0.253337,-0.326080,-0.691528,0.006404,-0.079043,-0.085204,-0.540963,0.413823,-0.151452,0.187452,0.336573,0.041854,0.145831,0.020027,0.494845,-0.160559,0.042693,-0.002935,-0.154648,-0.245555,0.496441,0.439173,0.295398,-0.022875,0.318181,0.019016,0.259429,0.450331,-0.593122,-0.246503,-0.192345,0.475378,-0.145221,0.129007,0.313991,0.069598,-0.091089,0.517346,0.343289,-0.285481,0.160982,-0.082662,0.016248,-0.644718,0.099100,0.237365,0.078737,-0.822712,0.144657,-0.196274,0.127735,0.220378,-0.486715,0.159082,0.232592,0.296234,0.512975,-0.600286,-0.156253,-0.526724,-0.214891,0.458146,-0.215132,-0.246355,0.238906,-0.217819,-0.409854,0.091517,-0.061183,-0.461601,0.220098,0.254699,0.429578,-0.304819,0.358395,-0.398219,-0.312936,-0.433557,-0.151597,0.015930,-0.532955,-0.212758,-0.332637,-0.124856,-0.051077,-0.239664,-0.015948,0.143039,-0.215595,0.880466,-0.907864,0.455461,0.341279,0.476194,-0.476733,0.322677,0.304854,0.340260,-0.134625,0.185730,0.325341,0.129858,0.257113,0.010238,0.323646,0.281592,-0.123989,-0.320344,0.604644', '26593587', '35048413', '1303034', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304044', '鬼童院', '悬疑', '1939年，持续三年的西班牙内战接近尾声，右翼法西斯分子风头正劲。左派战争孤儿卡洛斯（费尔南多·缇艾弗 Fernando Tielve 饰），被父亲的战友们送到一个位于荒郊野外的孤儿院。这个孤儿院由严厉的卡门女士（玛丽莎·佩雷德斯 Marisa Paredes 饰）和和蔼的卡萨瑞斯教授（Federico Luppi 饰）共同经营。卡洛斯离开亲人和叔叔们的失落情绪并未持续太久，他很快就融入了这个满是同龄人的大家庭。不过，这个院子中央插着炮弹的地方，也许原本就存在着些许异常。卡洛斯所睡的12号床之前属于一个名叫山迪的孩子，山迪在不久前离奇死去。自从卡洛斯来之后，那个小男孩的鬼魂便不断出现……本片荣获2002年阿姆斯特丹奇幻电影节评委会银奖；2002年法国Gérardmer电影节国际影评人奖、评委会特别奖和青年评委会奖；2002年青年艺术家奖最佳演员奖（Fernando Tielve）。', '费尔南多·提尔弗', '吉尔莫·德尔·托罗', 7.2, 7560, 'tt0256009', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515760145.jpg', 0.8, 4.4, 39.5, 43.3, 11.9, '0.090147,-0.016879,-0.438798,0.435254,0.091208,-0.251816,0.594595,-0.040991,-0.591313,-0.398888,0.188570,0.809648,-0.249966,0.265276,0.425155,0.034775,-0.530454,-0.620695,-0.233407,-0.211539,-0.199972,-0.315062,-0.180049,-0.009442,-0.217028,-0.319043,0.616472,-0.191964,0.214704,0.717194,0.177030,0.287596,0.149039,0.111334,0.020626,0.117065,0.587881,-0.108354,-0.253701,0.339912,0.157623,-0.124916,-0.426949,-0.090058,0.163848,0.055489,0.662693,-0.213682,0.135892,-0.140994,0.266880,-0.171195,-0.214592,0.034763,0.362278,-0.217117,0.229480,0.200294,-0.096046,0.100466,-0.010092,-0.306576,-0.208541,0.300468,-0.065156,0.123618,-0.383497,0.535160,0.027231,0.211630,0.009649,-0.215972,0.239834,0.263681,0.003147,0.248288,-0.255185,0.071649,-0.306575,0.465910,0.380117,-0.098815,-0.524821,0.053432,-0.310494,-0.462458,-0.191421,-0.146850,-0.581097,0.135307,0.471888,-0.105854,-0.035048,0.481854,-0.615433,0.008591,-0.241707,-0.270680,0.155339,-0.048184,-0.232243,-0.722398,-0.117525,-0.061906,-0.194057,-0.060881,-0.231675,0.155717,0.767876,-0.540497,0.447032,0.469593,0.298889,0.004484,0.650023,-0.067279,0.095538,-0.310570,-0.363666,0.429856,-0.184296,0.018620,-0.067958,0.278279,-0.135584,-0.241466,-0.133497,0.300425', '3811356', '1780122', '26365262', '1303083');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304045', '十万火急', '剧情', '消防队长云（刘青云饰）是个刻己尽责的救火队员，每当意外发生，他都要和队员赶到火场。新调来的上司（方中信饰）决心以严谨纪律重整阵容，他的苛刻要求招致一众消防员的不满。但在生活上，他们各自并不如意。上司重遇前妻，形同陌路。一心为事业的女见习队长（黄卓菱饰）也与丈夫貌合神离。云在一次现场抢救过程中，搭救了Carmen（李若彤饰）。面对那场突然爆发的灾难性的五级大火，对消防员自身构成危险，所有人必须离开火场，火场內藏有大量危险品及引致大爆炸，並且释放出大量有毒气体，而火场內仍有生还者待救。身处生死边缘的消防队员们，仍决定奋不顾身继续救人，最后他们能否成功？©豆瓣', '刘青云', '杜琪峰', 7.4, 11219, 'tt0120115', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2354355617.jpg', 0.5, 2.4, 36.4, 46.8, 13.9, '-0.135115,0.104005,-0.661492,0.173324,0.067096,0.028821,0.689541,-0.181460,-0.436380,-0.305376,0.544995,0.678566,0.025455,0.050932,0.065381,-0.474690,-0.209279,-0.613298,-0.293310,0.119192,-0.458758,-0.363238,-0.134433,-0.144029,-0.139162,-0.189562,0.534883,0.232966,-0.125035,0.296832,0.340052,0.294916,-0.271652,0.653801,0.030343,-0.122825,-0.081770,-0.011899,-0.405162,-0.101073,0.020890,-0.118536,-0.401147,-0.048982,0.271408,0.492376,0.582025,-0.092492,-0.313957,-0.071840,0.396867,-0.408120,0.297280,0.286946,0.398114,0.160026,0.024686,0.125861,0.137798,0.013727,-0.223192,-0.082341,-0.698024,-0.114914,0.180625,-0.001343,-0.465850,0.161837,0.132405,0.065605,0.253980,0.039668,-0.216272,0.285770,0.102636,0.161001,-0.566882,-0.083264,-0.311522,0.029532,0.714627,-0.172220,-0.412656,0.066580,-0.106036,-0.389450,0.065746,-0.195039,-0.399262,-0.015493,0.299853,0.243389,-0.050468,0.072512,-0.309523,-0.028232,-0.343800,-0.177517,-0.262898,-0.010208,-0.038752,-0.640462,0.136163,-0.063403,-0.315123,0.189273,-0.019767,0.022633,0.597912,-0.489341,0.071158,0.301034,0.200655,-0.758236,0.141879,0.200387,0.333723,-0.205472,-0.079193,0.139714,0.012860,0.457966,0.082051,0.132273,-0.083509,-0.014815,-0.235990,-0.035153', '1294941', '1301022', '26678784', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304056', '茜茜公主', '剧情', '《茜茜公主》系列影片包括《茜茜公主》、《年轻的皇后》和《皇后的命运》三部曲。作为系列影片的首部，该片讲述了茜茜公主（罗密·施奈德 Romy Schneider 饰）与奥地利国王弗兰兹·约瑟夫（卡尔亨兹·伯恩 Karlheinz Böhm 饰）邂逅相恋的故事。茜茜出生在 巴伐利亚的贵族之家，她美艳动人，性格活泼。姨妈苏菲打算安排自己的儿子，即奥地利王位继承人弗兰兹，在他的生日庆典上与茜茜的姐姐海伦订婚。母亲和姐姐带着茜茜赴奥地利参加庆典，调皮的她偷偷溜出去钓鱼，不料却与英俊的国王弗兰兹相遇。茜茜动人的微笑深深击中弗兰兹，让他彻底爱上了天真纯情的茜茜，并不顾一切违背母亲苏菲的旨意，在生日庆典上宣布茜茜才是自己的皇后。虽然有情人终成眷属，但这段浪漫纯真的爱情却是刚刚面临考验。©豆瓣', '罗密·施耐德', '恩斯特·马里施卡', 8.5, 103917, 'tt0048624', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2160427238.jpg', 0.1, 0.7, 15.1, 43.4, 40.7, '0.205138,0.312465,-0.673734,0.740814,-0.014771,-0.347071,0.666337,-0.010857,-0.113273,-0.095801,0.322640,0.723371,-0.540312,0.198490,0.599724,0.452109,-0.461772,-0.660288,0.074939,-0.039911,-0.063808,-0.401409,0.205355,0.211402,0.137284,-0.360559,0.608016,-0.316067,-0.030119,0.633795,0.437101,0.236201,-0.252044,0.105488,-0.047234,0.081559,0.009696,-0.104105,-0.296118,-0.033981,0.050741,-0.151093,-0.288329,0.377998,0.056120,0.358312,0.681259,-0.466096,0.265335,-0.200372,0.417749,-0.176662,0.154629,0.202585,-0.154962,-0.147223,0.347742,0.232326,-0.079393,-0.378627,-0.087922,-0.493079,-0.361849,0.328318,0.059323,0.182647,-0.300860,0.521303,-0.277175,0.139253,0.345603,-0.253514,0.142132,0.412787,-0.107823,0.542340,-0.096643,0.092991,-0.297232,0.184617,0.552152,0.098300,-0.171553,0.396168,-0.291007,-0.243885,0.115698,-0.256568,-0.834623,0.384746,0.143811,-0.291702,0.122214,0.393524,-0.520750,-0.208368,-0.338814,-0.017139,0.480686,-0.441605,0.061528,-0.745820,-0.227428,-0.559328,-0.477634,-0.078460,0.142715,-0.324566,0.751108,-0.752143,0.275514,0.312009,0.387340,-0.509605,0.513820,0.270840,0.023066,-0.200609,-0.151414,0.590893,-0.249554,-0.421430,-0.114646,0.392495,0.083110,0.047549,-0.591470,0.548117', '3811356', '1296992', '26926321', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304073', '假如爱有天意', '剧情', '2003年的大学生梓希（孙艺珍饰）一天收拾房间，无意中发现一个神秘的箱子，里面满载着母亲珠喜（孙艺珍饰）留下的情书，在阅读中她重温着母亲的初恋回忆。1968年的珠喜，是一个清纯可爱的少女，与穷学生俊河（曹承佑饰）一见钟情，由于珠喜显赫的家世，令两人的恋爱陷入俗套的门不当户不对的痛苦纠结中。2003年的梓希爱情同样坎坷，她暗恋着戏剧学会的尚民（赵寅成饰），却一直难以表白自己的爱意。而巧妙的是，梓希发觉母亲的初恋故事跟她自己遭遇十分相似。自己能得到幸福吗？还是如母亲一般曲折难求？©豆瓣', '孙艺珍', '郭在容', 8.4, 391759, 'tt0348568', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p479746811.jpg', 0.4, 1.5, 15.8, 41, 41.3, '0.514671,0.073985,-0.476778,0.670159,-0.122538,-0.298883,1.019659,-0.249214,-0.576030,-0.412650,0.183967,0.505952,-0.129477,0.634977,0.069568,0.335018,-0.080050,-0.805455,-0.154894,-0.073251,-0.235326,-0.294942,-0.343322,0.008779,-0.151680,-0.201844,0.467953,0.157894,-0.116257,0.474824,0.147658,0.143868,-0.195719,0.334755,-0.258345,0.150590,-0.080571,0.460349,-0.211967,-0.097305,0.024115,-0.267104,-0.285518,0.192736,-0.164216,0.192431,0.710958,-0.260919,-0.165374,0.212970,0.608340,-0.028627,-0.267882,0.097277,0.071303,0.247879,0.295556,0.114724,-0.195617,-0.085572,0.054961,-0.161943,-0.628370,-0.324148,0.168283,0.297394,-0.392844,0.715288,-0.028382,0.008050,0.237248,-0.274187,-0.081671,-0.081521,0.409749,0.701244,-0.463293,0.057835,-0.360244,0.598130,0.585911,0.171092,-0.243156,0.589877,-0.487155,-0.350045,0.104384,-0.177494,-0.961708,0.239788,0.212798,0.234723,-0.192376,0.246216,-0.466239,0.061871,-0.190352,0.107323,-0.017550,-0.530480,-0.339009,-0.110781,-0.380513,-0.754571,-0.645022,0.064344,0.005548,-0.447998,0.854368,-0.767532,0.293450,0.461444,0.145798,-0.298933,0.836137,0.184517,-0.324137,-0.161488,-0.155257,0.591195,-0.336483,-0.236403,-0.037258,0.387607,-0.256298,-0.100789,-0.513593,0.461162', '3796613', '1303077', '26348103', '4817024');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304091', '东方三侠', '动作', '东东（梅艳芳 饰）与心靖（杨紫琼 饰）年幼时得到武林高手的收养，传授她们武功望她们能长大后行侠仗义。同是孤儿的两人情同姐妹。不料心靖在12岁时被抓走，从此失去音信。东东长大后下嫁了警官刘启文（刘松仁 饰），生下女儿后当上了贤妻良母。多年来她一直向家人隐瞒自己的身份，但 夫妻俩之间却因为这样变得疏远。当年心靖被清朝宦官陈公公抓走，用毒液洗去了她记忆后利用她的好身手干着坏事。陈七（张曼玉 饰）也是公公的手下，生性不羁，她中毒并不深，记忆不久便恢复了。她跟东东一般富有正义感但视钱如命。三人在一次偷取婴儿的争斗中相遇了，但心中的正义感令她们本来对立的角色演变成一直的方向，对付危害大众生命的女勇士。©豆瓣', '梅艳芳', '杜琪峰', 7.5, 49253, 'tt0105619', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2355311538.jpg', 0.6, 3.4, 35.1, 43.8, 17.1, '0.126533,-0.035342,-0.335586,0.400545,-0.277672,-0.381119,0.730212,0.060169,-0.712303,-0.314174,-0.007633,0.621930,-0.144246,0.082815,-0.033072,-0.028643,-0.218828,-0.744816,0.004346,-0.082825,-0.108000,-0.322704,-0.049180,-0.107137,-0.272515,-0.393093,0.545406,-0.100096,0.004969,0.485275,0.209477,-0.004684,-0.089869,0.364212,-0.104627,0.305850,-0.149094,0.189170,-0.173979,0.165112,0.163964,-0.201721,-0.079625,-0.034199,0.008368,0.353333,0.542471,-0.154884,-0.069684,-0.457227,0.152926,-0.049133,-0.168504,0.106634,0.235690,0.029339,0.408949,0.316033,-0.027721,-0.003141,-0.123664,0.021768,-0.246610,0.048355,0.275879,-0.085136,-0.637739,0.254331,-0.001417,-0.063191,-0.168391,-0.384481,0.192999,0.188537,0.241231,0.240288,-0.177948,0.090748,-0.540730,0.170235,0.762285,0.043254,-0.204801,0.343772,-0.123219,-0.464211,0.100927,-0.402849,-0.232419,0.144063,0.219948,0.261333,-0.138147,0.286785,-0.430848,-0.080961,-0.217002,0.476714,0.079790,-0.474538,-0.001438,-0.100840,-0.392705,-0.633967,-0.432783,-0.077642,0.052065,-0.370969,0.680439,-0.761777,0.237038,0.177718,0.305891,-0.695250,0.586536,0.041154,0.077970,-0.119787,-0.006523,0.252869,-0.080946,0.073870,0.142292,0.027790,-0.235659,-0.053113,-0.053840,0.163436', '25721544', '35030151', '1301022', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304100', '最爱', '剧情', '人入中年的吴明宝（缪骞人 饰）和白芸（张艾嘉 饰）有一份几十年的友情，如今他们的丈夫都已故去，各自的女儿青春可人，正像她们当年的年纪，她们的回忆，一起回到了当年吴明宝和俊彦（林子祥 饰）订婚的时候……吴明宝在律师楼做秘书的时候与律师老板俊彦日久生情，双方家长撮合下，他们即将成婚。吴明宝将俊彦介绍给一起长大的闺蜜白芸，俊彦与白芸两人相谈甚欢，感到彼此所呼应的默契，一段隐秘的情愫在两人之间滋长。终于，俊彦在婚礼前产生了动摇，然而白芸拒绝了俊彦，与一位相识不久的医生匆匆成婚。多年以后，两个好友再度聊起当年的往事，吴明宝发现好友和丈夫瞒了她多年的一段情……©豆瓣', '张艾嘉', '张艾嘉', 7.5, 5616, 'tt0092301', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2719552156.jpg', 0.6, 2.6, 34.5, 45.9, 16.3, '0.467763,-0.178467,-0.569573,0.495482,-0.041359,-0.560197,0.625928,0.176651,-0.618732,-0.290113,0.163818,0.840517,-0.473256,0.521307,0.305443,-0.189182,-0.247447,-0.989164,0.099576,-0.273593,0.021924,-0.437935,0.042474,0.122332,-0.019008,-0.198930,0.501302,-0.230124,0.321496,0.831998,0.168553,-0.021366,-0.557570,0.268479,-0.015296,0.243288,0.274784,0.405148,-0.864840,-0.100245,0.066594,-0.022972,-0.153304,-0.220018,-0.017710,0.218743,0.570410,0.055127,-0.308152,0.070027,0.243923,0.137214,0.032264,0.186381,0.348462,0.143483,0.406799,0.461839,-0.351137,-0.185377,-0.245642,0.098117,-0.180146,0.228903,0.101857,0.008504,-0.590204,0.724390,0.119349,-0.051310,0.102668,-0.410482,0.376741,0.632884,0.119491,0.310754,-0.172635,0.032549,-0.285075,0.285959,0.998699,0.208231,0.223668,0.324570,-0.087276,-0.130412,-0.109719,0.074524,-0.651006,0.148492,0.144522,0.082652,-0.151739,0.291800,-0.521335,-0.120953,-0.215754,0.477950,0.387994,-0.623369,0.025781,-0.619353,-0.590569,-0.675794,-0.291304,0.182106,0.161688,-0.206326,0.828491,-0.756244,0.131197,0.075028,0.385427,-0.551765,0.835892,0.238568,0.223951,-0.388212,0.087783,-0.063633,-0.252552,0.002467,0.276594,0.330403,-0.207087,0.440665,-0.347250,-0.094205', '3078390', '3212120', '25721544', '1294713');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304102', '谍影重重', '动作', '杰森·伯恩（马特·达蒙 饰）在意大利被人从海上救起，他失去了记忆，除了臀部的瑞士银行帐号之外，他完全没有办法证明自己的身份。杰森从瑞士银行找到了大量的现金，六本护照，一把枪，同时他发现自己格斗、枪械、和语言等方面的能力，他开始追查自己的身份，并且把陌生女子玛丽（弗兰卡·泼坦特 饰）也卷了进来。两人从瑞士到巴黎，一路上受到神秘杀手组织的追杀，危机重重。杰森能否化险为夷，找到自己的真实身份？他是否有勇气面对真相？©豆瓣', '马特·达蒙', '道格·里曼', 8.6, 397071, 'tt0258463', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1597183981.jpg', 0.1, 0.7, 12.3, 43, 43.8, '0.158618,0.362947,-0.895921,0.461031,-0.507194,-0.001096,0.454035,-0.120554,-0.552683,-0.314377,0.289907,0.707485,0.211838,0.038018,0.138235,0.177310,-0.372064,-0.838396,0.242011,-0.184422,-0.704572,-0.446178,-0.299578,-0.288402,0.014189,-0.397270,0.474402,0.021037,-0.490168,0.097528,-0.037202,0.323283,-0.279320,0.519648,-0.240222,-0.023766,0.264326,-0.150314,-0.153643,0.406764,0.101004,-0.371570,-0.321984,0.549900,0.009421,0.489164,0.652783,-0.040933,0.000722,0.240926,0.122069,-0.066404,-0.044662,0.097834,0.061661,-0.081226,-0.094094,0.134827,-0.086007,-0.058293,0.202410,0.123238,-0.737709,0.002765,-0.178846,0.275609,-0.595596,0.127526,-0.751061,-0.045545,0.087582,-0.485484,0.049638,0.123503,-0.010767,-0.070950,-0.249647,-0.021995,-0.783112,0.089233,0.513739,-0.088775,-0.208716,0.190057,-0.026255,-0.513623,-0.367525,-0.068166,-0.144320,0.022403,0.697264,0.232172,-0.340166,0.014332,-0.573006,0.035131,-0.284479,-0.294668,-0.150158,-0.249962,-0.011490,-0.528289,-0.468911,-0.340886,-0.291488,-0.231992,0.201514,-0.224282,0.710251,-0.515343,0.045846,0.661504,0.241478,-0.519600,0.315587,-0.120229,-0.043603,-0.217686,-0.253767,0.232950,0.448319,0.354719,0.229707,0.223946,0.075617,-0.077896,-0.246177,0.433889', '1309069', '1947080', '1300303', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304114', '美国甜心', '喜剧', '葛雯（凯瑟琳•泽塔琼斯 饰）与埃迪（约翰•库萨克 饰）是一对银幕夫妻，他们一起拍的电影每部都十分卖座。但实际上他们的婚姻远远超出了观众的想象及宣传的效果。葛雯是个极度自我的女明星，她有一个身兼助理的妹妹琦琦（茱丽娅•罗伯茨 饰），她对霸道的姐姐十分忍让，性格温和的琦琦一直暗恋着姐夫埃迪。当葛雯跟埃迪吵架，她总会出面安慰埃迪。葛雯与埃迪的婚姻已经濒临破裂，因为葛雯认识了新欢。而他们最后一次合作的电影《Time over Time》快要上画，这是高额制作的电影，电影公司十分紧张。但性情奇怪的导演哈尔不让任何人知道任何剧情。在电影快要上映期间，反目成仇的两人再次被拉到一起，他们在众多记者面前表现出十分和睦的一面，但私下他们却互不想让，虽然此时埃迪还是喜欢着妻子。经过这些天的相处后，埃迪终于明白自己爱的人到底是谁。©豆瓣', '朱莉娅·罗伯茨', '乔·罗斯', 6.3, 10772, 'tt0265029', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p946540659.jpg', 1.6, 11.9, 59, 22.5, 5, '0.200697,-0.267276,-0.608532,0.622661,0.126455,-0.316519,0.765407,0.169596,-0.567948,-0.212768,0.046401,0.880588,-0.528810,0.220159,0.037029,-0.106502,-0.371387,-0.672059,-0.093143,-0.028580,0.021435,-0.499762,-0.091473,-0.058261,-0.360085,-0.151759,0.609717,-0.144040,-0.146737,0.382886,0.448451,0.046923,0.102900,0.414090,0.013702,0.034539,-0.031926,-0.032663,-0.423011,0.019998,0.410796,0.159984,-0.262725,0.272183,0.005102,0.451432,0.413444,-0.204184,-0.275298,0.282616,0.367145,-0.280290,0.202360,0.201383,0.156155,-0.175340,0.471973,0.127588,-0.022310,-0.060157,-0.099611,0.077664,-0.781398,0.402921,0.119247,0.189867,-0.520550,0.381819,-0.180304,0.047056,0.050041,-0.292397,0.145925,0.346281,0.361698,0.200323,-0.285438,-0.186505,-0.605074,-0.042461,0.696438,0.309535,-0.092775,0.732949,-0.494707,-0.432298,-0.450479,-0.355444,-0.736490,0.174520,0.047798,-0.130957,0.003966,0.201617,-0.381122,0.083381,0.037256,-0.104310,0.003383,-0.694368,0.219465,-0.644638,-0.395196,-0.723582,-0.418600,-0.164556,-0.090389,-0.334338,0.657668,-0.891917,-0.023751,0.371877,0.279104,-0.480805,0.793138,0.403564,-0.130463,-0.202723,-0.126631,0.092456,0.031316,-0.179402,0.121286,0.373204,0.281478,-0.175879,-0.302664,0.515917', '4301278', '4275444', '1783461', '1456503');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304124', '龙腾四海', '喜剧', '台湾黑帮老大龙日夫遇袭，幸得智勇双全的义子龙一（邓光荣）舍命相救才保一命，事后，龙一被他推选为继承人，招来其亲生儿子龙二（任达华）和龙三的不满，后者更设法要置龙一于死地，令龙日夫忍痛命令龙二将他干掉，不想龙二掉头将龙日夫和他一起送上黄泉。紧接，龙二命其心腹小林（黎明）追杀龙一。小林虽忠于龙二，却也倾慕龙一，忠义两难的择决过后，他违命放了受伤的龙一及其妻子雪儿，令他们逃到香港，过起隐姓埋名的日子。龙一于无意间结识酒吧老板程丽及其弟大飞（刘德华），大飞虽是混混，却极有正义感，两人因某件事结下生死情谊。后来大飞与头醉鸡发生冲突，发誓不再涉足江湖的龙一为朋友再次出山，不想醉头鸡正是龙二所派。©豆瓣', '刘德华', '霍耀良', 6.7, 6614, 'tt0104755', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2548588476.jpg', 1.8, 8.5, 54.9, 24.7, 10.1, '-0.146703,-0.177385,-0.491359,0.424696,0.144900,-0.430634,0.505550,0.090341,-0.638675,-0.214654,0.150171,0.636165,0.069866,0.395201,0.135879,-0.120372,-0.045049,-0.483760,0.071446,0.178789,0.140356,-0.058698,-0.061792,-0.199742,-0.356601,0.116986,0.348875,0.006983,-0.063001,0.517190,0.432772,0.338528,-0.546906,0.445992,-0.151498,0.290213,-0.299077,0.136012,-0.547678,-0.026342,0.019350,-0.381514,-0.184262,0.394686,0.154371,0.463073,0.274120,-0.201680,-0.025103,-0.579687,0.145774,-0.382570,0.007453,0.034828,0.326106,-0.206663,0.189093,0.335564,0.011921,0.014978,-0.005257,0.120619,-0.603492,0.024505,0.121941,-0.077918,-0.466252,0.232020,-0.222536,0.097222,0.036457,-0.025687,-0.105208,0.141815,-0.004331,-0.232491,-0.214252,0.133089,-0.340545,0.011191,0.691316,-0.106419,0.327684,-0.083428,0.316332,-0.615756,0.330377,-0.290012,0.093060,-0.150609,0.558379,0.234958,-0.020599,0.199422,-0.205377,-0.407087,-0.142326,0.442216,-0.068793,-0.091691,0.146352,-0.021041,0.073462,-0.356728,-0.065703,0.170229,0.017407,-0.119064,0.408708,-0.621905,-0.147002,0.042519,0.477952,-0.703106,0.389425,0.126135,0.050569,-0.277883,0.059800,0.159748,0.374655,0.005725,0.426154,-0.049922,-0.022768,-0.108270,-0.000893,0.086247', '10604851', '25721544', '1295746', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304129', '德州电锯杀人狂', '惊悚', '一群年轻人驾车去墨西哥听演唱会。途径德州特拉维斯镇，他们的车子险些撞到一个女孩杰蔓。看到她遍体鳞伤的样子，大伙动了恻隐之心，准备送她回家。不想，她在车上突然饮弹自尽。为了妥善处理尸体，他们到就近的酒店询问警察局的地址。但是，他们到达后却发现此处已成废墟，阴暗潮湿、肮脏不堪。于是，情侣坎普（艾里克•巴弗尔 Eric Balfour 饰）与艾琳（杰西卡•贝尔 Jessica Biel 饰）决定去附近的住家寻求帮助，留下其他人守着尸体。他们来到了一处阴森恐怖的古宅，坎普神秘失踪。艾琳觉得蹊跷，慌忙跑回磨房搬来安迪当救兵，没想到两人落入了电锯杀人狂的魔爪。侥幸逃脱的艾琳跑回来报警，结果却迎来了目露凶光的探长霍伊特（R•李•艾尔米 R. Lee Ermey 饰），让他们更加恐惧……©豆瓣', '杰西卡·贝尔', '马库斯·尼斯佩尔', 6.9, 36200, 'tt0324216', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p976320432.jpg', 1.4, 7.4, 46.9, 32.7, 11.5, '0.362216,0.012639,-0.856978,0.031930,0.018249,-0.381393,0.822956,0.139397,-0.439256,-0.113965,0.288659,0.601339,-0.217178,0.248873,0.282960,0.086872,-0.601089,-0.230030,0.144178,-0.319913,-0.383923,-0.054332,-0.095713,-0.396288,0.098017,0.120845,0.217492,0.206650,-0.107580,0.601541,0.131547,0.252138,-0.330441,0.640809,-0.188640,0.206790,0.078095,-0.272216,-0.051238,0.239253,0.037505,-0.057812,-0.381132,0.035592,0.108180,0.248245,0.623982,0.125280,-0.116904,0.119733,-0.038792,-0.214176,0.120604,0.178561,0.201371,-0.370439,0.112523,-0.245912,-0.294522,-0.147395,0.239657,0.040859,-0.078437,0.371384,-0.288001,0.381662,-0.626605,0.106964,-0.229686,0.060489,0.191139,-0.586270,0.350416,0.118971,-0.016016,0.237275,-0.004348,-0.102242,-0.734151,-0.291941,0.518187,-0.222470,0.167799,0.075038,0.236155,-0.232562,0.121135,0.192690,-0.185144,-0.246433,0.757786,-0.075152,-0.114136,-0.263212,-0.591839,-0.323081,-0.495249,-0.175603,-0.219169,-0.315852,-0.093022,-0.522654,0.119020,0.226463,-0.133388,0.310854,-0.127905,0.095415,0.076928,-0.252744,0.166108,0.542519,0.279353,-0.290109,0.296282,-0.353849,0.162150,-0.095124,-0.015989,0.407946,0.248598,0.763102,0.289691,0.330632,-0.160945,-0.122212,-0.482719,0.224351', '3011051', '1306670', '1303462', '1298817');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304132', '无敌反斗星', '喜剧', '乌龙院里，小文（郝邵文 饰）等师徒五人经历了保卫易筋经之战后，终日习武度日，过着与世无争怡然自得的生活。小文在母亲生日时与师兄（吴孟达 饰）下山探望母亲，不料却被母亲赶走，伤心的小文终日流泪，师父（李名扬 饰）与师叔（刘洵 饰）为小文请来年轻女子阿真（叶全真 饰）作为其陪护，不料阿真居然偷走易筋经。小文、小龙（释小龙 饰）与师兄三人下山追索易筋经。三人于路结识擅于狂奔的昔日黑社会人士阿金（葛民辉 饰），在阿金的引领下，他们冲破了罗嘉鹰群的截击，经历了群鬼旅馆惊魂，逐渐接近了阿真藏匿的天魔古堡。一场为夺取易筋经的大战再次上演……©豆瓣', '郝劭文', '朱延平', 7.7, 26969, 'tt0114990', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2352229477.jpg', 0.3, 2.2, 30, 47, 20.6, '-0.084783,-0.165902,-0.545466,0.334465,0.173415,-0.448044,0.596271,0.062576,-0.389252,-0.400936,0.352310,0.338727,-0.104433,0.327817,0.198570,-0.236276,-0.142243,-0.510488,-0.118982,0.134952,-0.048733,0.075702,-0.111024,0.187987,-0.147549,-0.369219,0.399158,0.076954,-0.150308,0.628172,0.164038,0.043282,-0.571419,0.233351,-0.225441,0.279722,-0.000855,0.265907,-0.339261,0.003539,-0.132586,-0.520176,-0.314924,-0.201618,-0.034526,0.181002,0.680424,-0.215275,-0.035281,-0.127206,0.077226,-0.105049,0.001062,0.052801,0.122460,0.091679,0.390925,0.120186,-0.119188,0.048173,-0.037184,-0.167847,-0.165713,0.189150,0.393096,-0.107669,-0.513038,0.242311,-0.134973,0.150913,0.034849,-0.428008,0.018655,0.209375,0.052239,0.338400,-0.038573,-0.074846,-0.449444,0.352427,0.648114,-0.292350,0.368386,0.129704,0.305884,-0.268816,0.251646,-0.243093,-0.347440,0.003028,0.361243,-0.232287,-0.003345,0.154761,-0.506352,-0.066850,-0.327595,0.163222,-0.095297,0.016244,0.012486,-0.678645,0.043187,-0.355313,-0.185524,0.026074,0.008215,-0.245541,0.622953,-0.613698,0.318413,0.040989,0.006613,-0.478026,0.615748,-0.130516,0.251724,-0.043827,0.095252,0.248763,0.046152,0.378154,0.193742,0.327125,-0.065607,0.212650,-0.514523,0.123094', '3811356', '10466639', '26687241', '1291992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304141', '黑客帝国2：重装上阵', '动作', '上一部结尾，尼奥（基奴李维斯 饰）终于意识到自己的能力和使命，中弹复活后，变成了无所不能的“救世主”，他和女友崔妮蒂（凯莉·安·摩丝 饰），舰长墨菲斯（劳伦斯·菲什伯恩 饰）回到了人类的基地锡安，受到人们的热烈欢迎。此时，“母体”决定先下手为强，派出了两万五千只电子乌贼攻击锡安基地；墨菲斯、尼奥和崔妮蒂则再次进入“母体”，寻找“制钥者”，准备从内部破坏；而本该被尼奥消灭的特勤史密斯似乎出了点问题，脱离了“母体”的控制，拥有可怕的复制能力，阻碍尼奥他们的行动。©豆瓣', '基努·里维斯', '拉娜·沃卓斯基', 8.7, 380129, 'tt0234215', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p443461390.jpg', 0.2, 0.8, 11.2, 41.2, 46.6, '0.313714,0.397099,-0.313512,0.195230,-0.090782,-0.401211,0.563364,0.299793,-0.141461,-0.013494,0.245645,0.855019,-0.104112,-0.261225,0.415511,0.070849,-0.559682,-0.644468,0.053492,-0.185614,-0.329589,-0.656981,-0.549393,-0.169136,0.277423,-0.676327,0.608067,-0.005675,-0.251090,0.164788,-0.180001,0.580612,0.042129,0.576299,0.352450,0.139449,0.086461,-0.607120,-0.182879,0.406887,0.018637,-0.155956,0.007089,0.480700,-0.050711,0.308387,0.820471,-0.653390,0.084009,-0.598311,0.208523,-0.424192,-0.165233,-0.053283,0.200411,-0.045866,0.018593,-0.033371,0.024585,0.063196,-0.032728,-0.146808,-0.949705,-0.160762,-0.021078,0.346060,-0.495247,0.017313,-0.320485,0.271787,0.212387,-0.608433,0.263190,0.443638,0.115648,0.205722,-0.421384,0.051825,-0.564523,-0.234660,0.375142,-0.270654,-0.551950,0.063742,0.028672,-0.522381,-0.449564,-0.126535,-0.176809,-0.185208,0.451036,0.507675,-0.062167,0.055088,-0.732391,-0.332043,-0.592366,-0.485882,-0.357866,-0.300616,-0.014667,-0.892160,-0.063314,-0.091612,-0.184996,0.042067,-0.033437,-0.137847,0.542272,-0.791527,0.264105,0.687286,0.331761,-0.399700,0.166516,-0.345006,0.281698,-0.331814,0.018324,0.288808,-0.039114,0.570755,0.246162,0.392579,0.001592,-0.139734,-0.522941,0.547295', '25774050', '1308585', '1420088', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304199', '威龙猛探', '剧情', '当夜色笼罩纽约，这里又变成了一座犯罪猖獗的城市。华人警察黄比利（成龙 饰）和同事来到酒吧庆祝来美十周年，不料同事却被一群闯入的劫匪杀死，愤怒的比利将凶手正法，因此激怒了上司，被惩罚性质的派到大亨沙比路的时装展上维持治安，表演期间，沙比路的女儿罗娜被一群人劫走，而沙比路的保镖宾尼事发前曾向香港打过多个电话，种种迹象表明，沙比路和香港头号毒枭高伟洛（乔宏 饰）有过合作，而二人产生争执可能导致这次的绑架。比利和搭档丹尼（丹尼·埃洛 Danny Aiello 饰）前往香港，在这里找到了高伟洛昔日两名合作伙伴李兴以及何天的女儿何美芳（叶倩文 饰），希望对方能够提供线索。高伟洛迅速派人追杀比利和丹尼，以及昔日的合作伙伴。比利冲破重重阻碍，查清了高伟洛的巢穴，带领搭档向高发起了猛攻……©豆瓣', '成龙', '詹姆斯·格利肯豪斯', 6.3, 4612, 'tt0089847', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1386408968.jpg', 2.8, 15.2, 56.2, 17.6, 8.1, '0.309976,-0.237994,-0.567705,0.566428,0.158028,-0.383402,0.684839,0.182356,-0.377062,-0.101246,0.114462,0.473302,-0.111246,0.197997,0.589789,-0.282762,-0.331715,-0.703637,-0.078583,-0.179829,-0.341652,-0.398836,-0.308449,-0.290698,0.031918,-0.291628,0.290049,0.045337,-0.301774,0.749464,0.426830,0.365095,-0.423982,0.392973,0.066443,0.206355,0.500879,-0.141280,-0.520197,0.329173,-0.276937,-0.214700,0.005326,0.060828,0.065504,0.579992,0.476238,-0.026056,-0.137799,-0.293218,0.157595,-0.490306,0.247788,0.112680,0.595637,0.108960,0.254958,0.248836,-0.127069,-0.174109,0.111847,-0.074532,-0.547652,0.313450,0.043399,-0.049476,-0.584303,0.203070,-0.024287,-0.024125,-0.005833,-0.399221,0.267641,0.251412,0.150682,0.151035,0.083595,0.063370,-0.628229,-0.098145,0.852637,-0.170042,0.009077,-0.158345,0.121624,-0.134360,0.030833,-0.061457,-0.124824,-0.064444,0.576283,-0.278333,-0.056430,0.045272,-0.512417,-0.250374,-0.518172,-0.064635,-0.058422,-0.307581,-0.061834,-0.837999,-0.022925,-0.113487,-0.058630,0.177960,0.015948,-0.064897,0.299646,-0.674807,0.221098,0.646082,0.561039,-0.630490,0.649655,0.014006,0.146187,-0.104106,-0.022060,-0.051468,0.508647,0.320331,0.135758,0.167013,-0.266112,-0.149586,-0.203809,0.114808', '3147969', '3183490', '3326747', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304244', '我和春天有个约会', '剧情', '一代歌后姚小蝶（刘雅丽 饰）自加拿大返港，准备在即将拆除的丽花皇宫进行一场纪念演出，这里是当年她和露露（罗冠兰 饰）、莲茜（冯蔚蘅）、凤萍（苏玉华）三名姐妹歌唱事业起步的地方。六十年代，东南亚的战争阴云对香港也多有波及，此时的四姐妹在丽花皇宫刚刚开始自己的演唱之路，凤萍被烂赌的男友拖累，有孕在身却经常入不敷出，最后消失在混乱的南洋，为四姐妹无忧无虑的日子画上了句号。小蝶属意乐队萨克斯风手家豪（吴大维 饰），但后者意识到小蝶的前途会远比自己灿烂，遂留下一曲《我和春天有个约会》，消失在茫茫人海……本片根据香港话剧团名剧改编，演员基本由原版话剧班底组成。©豆瓣', '刘雅丽', '高志森', 8.1, 7825, 'tt0111739', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2352122301.jpg', 0.4, 1.5, 22.1, 46.8, 29.2, '0.040200,0.034272,-0.593992,0.341578,0.167183,-0.128596,0.625255,0.234426,-0.082316,-0.041552,0.414216,0.743620,-0.264272,0.168334,0.270906,-0.007888,-0.233916,-0.726729,0.130682,-0.102828,0.026493,-0.243176,-0.125971,0.186026,-0.270482,-0.338845,0.654336,0.218015,-0.113558,0.577095,0.222640,-0.119943,-0.306455,0.095246,-0.033314,0.200248,-0.004376,0.107773,-0.401734,0.053127,-0.148808,-0.251161,-0.284135,-0.209508,-0.006925,0.306930,0.768085,0.204025,0.109630,0.030177,0.508365,-0.220848,-0.047764,-0.128893,0.412138,-0.127795,0.123403,0.223771,-0.154936,-0.074628,-0.240351,-0.227731,-0.514697,0.194542,0.206614,0.057307,-0.516970,0.502004,-0.000605,-0.098346,0.100902,-0.233504,0.471165,0.347971,0.163064,0.319805,-0.196970,0.221582,-0.373360,0.667366,0.655294,-0.037565,-0.171683,0.447631,0.046716,-0.292763,-0.211813,-0.103184,-0.282193,0.026239,0.064252,-0.254759,0.035873,-0.005541,-0.536866,0.054909,-0.024222,-0.251682,0.074750,-0.336074,0.007793,-0.634150,-0.227304,-0.276836,-0.243774,-0.144740,0.088906,-0.215427,0.720311,-0.688013,0.237816,0.446704,0.162178,-0.434431,0.515028,0.106757,0.326586,-0.205353,0.047098,0.136635,-0.385731,0.133258,0.136335,0.196119,-0.150769,-0.122198,-0.531873,0.321287', '3811356', '3158990', '1908036', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304257', '旺角揸Fit人', '动作', '生命垂危的黑帮人叻君（吴镇宇 饰）讲述了他被出卖被背叛的一生：曾经天真的他被骗入黑社会，投身于无良黑帮大佬的门下，被朋友出卖，惹来了不少麻烦。叻君终于弃暗投明，来到大佬天生的帮派中间，却还是被朋友、情人相继背叛。叻君与大佬反目，逃亡日本娶妻生子，不料杀手团把已有身孕的妻子残忍杀掉。于是，今日的叻君之所以凶残无人性，皆因这一系列逼上梁山的遭际，是命运把他逼到绝境。当垂死的叻君从死神中挣脱回来时，他的叙述，有了一百八十度的转变：他天生残暴，每次作恶多端后都能大难不死，用为人不齿的手段和作风在江湖上混，他是个贱到十足的人渣，没有半丁点值得怜悯的地方。©豆瓣', '吴镇宇', '查传谊', 7.2, 9020, 'tt0117242', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2196633761.jpg', 1.2, 5.1, 38.4, 40.6, 14.6, '0.244452,-0.061842,-0.438982,0.410990,-0.308766,-0.066157,0.485373,-0.016142,-0.691554,0.050523,0.141695,0.684980,-0.223188,0.287543,0.240629,-0.161921,0.280514,-0.740898,-0.442345,-0.116659,-0.352350,-0.222866,-0.209107,-0.168844,-0.361565,-0.212875,0.629875,0.223912,-0.200330,0.210189,0.589555,0.340727,0.008245,0.495660,-0.280364,0.250712,0.044404,0.036328,-0.085226,0.125199,-0.107480,-0.250302,0.070176,0.311482,-0.232851,0.436253,0.579028,-0.391666,-0.224091,-0.198751,0.415042,-0.506412,-0.019708,0.350476,0.384740,-0.176776,0.069092,0.456881,-0.063570,-0.314942,0.099724,0.025974,-1.077152,-0.195967,0.070576,-0.294315,-0.800957,0.579922,-0.040091,0.157022,-0.080217,-0.098014,0.397281,0.096405,0.251169,0.336182,0.013752,0.056067,-0.356577,0.133215,0.800884,0.075098,-0.134204,0.171805,0.175174,-0.168709,-0.005789,-0.697581,-0.241157,-0.013110,0.372052,-0.270821,-0.466631,0.539309,-0.365665,-0.258995,-0.149796,0.318271,0.132846,-0.531570,-0.250789,-0.147795,-0.133308,-0.358374,-0.141134,0.333962,0.140809,-0.158666,0.787969,-0.953900,0.023887,0.598917,0.259294,-0.687046,0.697755,0.025035,-0.217366,-0.180025,-0.183551,0.181533,0.520763,0.261797,0.579166,0.346506,-0.189523,-0.089445,-0.065296,0.311140', '1877596', '26678784', '1793491', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304282', '百年好合', '喜剧', '富豪洪飞虎（古天乐 饰）因怪病找到峨嵋派掌门王凤（郑秀文 饰），她对飞虎的生性傲慢毫无好感，于是用尽各种奇怪的方法治疗飞虎。王凤的师姐李莫愁（李冰冰 饰）突然出现，并扬言要铲除峨嵋派。未免伤及无辜，王凤尽快医好了飞虎。知道了王凤的恶作剧之后，飞虎愤然离开了。为了与师姐决战，王凤急需练好“伤心断肠剑”，但从未经历伤心之苦的她 无法领悟“百年好合”这一招式的要领，王凤在众人的劝说下决定求助与飞虎。飞虎不计前嫌，用尽办法让王凤伤心，练好招式。王凤又能否成功？©豆瓣', '郑秀文', '杜琪峰', 6.1, 48357, 'tt0374009', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p489271793.jpg', 2.4, 15.6, 61.3, 16, 4.6, '0.040825,-0.071543,-0.251973,0.164237,-0.039106,-0.511949,0.218330,0.006648,-0.744137,-0.217384,0.526754,0.087902,0.354412,-0.211758,-0.038061,-0.150415,-0.049462,-0.583893,0.350391,0.078779,0.103732,-0.470866,-0.048820,0.044471,-0.085414,-0.543446,0.142139,-0.116711,-0.139481,0.798092,0.283738,0.246023,0.043796,0.554899,0.123079,0.123617,-0.235066,0.114855,-0.368828,0.276158,0.151205,-0.239763,-0.282828,0.317060,-0.262422,0.420881,0.177704,-0.003561,-0.173702,-0.171995,0.141663,-0.275564,0.094969,0.298030,-0.021330,0.082632,0.471168,-0.029055,-0.373545,-0.005632,-0.037540,0.265577,-0.735055,0.209993,0.295812,-0.041041,-0.682169,0.480234,-0.388569,-0.159368,0.295433,-0.542669,0.043609,0.350324,0.579417,-0.082267,-0.319393,-0.001570,-0.248020,0.158003,0.569648,-0.254793,0.179352,0.031085,0.368310,-0.207099,-0.011701,-0.419056,0.049650,0.010446,0.456627,0.278786,-0.249965,-0.014170,-0.104502,-0.087526,-0.298595,0.149168,-0.275681,0.007050,0.360690,-0.186289,-0.111923,-0.317592,-0.382155,-0.579923,0.218491,-0.149902,0.716232,-0.855401,0.265782,-0.102685,0.488364,-0.590070,0.060307,0.529996,-0.137320,-0.015567,-0.305864,0.050256,-0.294645,0.595258,0.302334,0.298852,0.165107,-0.081086,-0.396751,0.050534', '35030151', '1877596', '1306133', '1480318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304304', '朱丽叶与梁山伯', '剧情', '佐敦（吴镇宇饰）因为欠下元朗大哥新界安（任达华饰）十多万赌债，被迫逃跑。而同一时刻，孤女Judy（吴君如饰）也带着行李离开丈夫，返回元朗。佐敦好友嘉华（刘以达饰）在元朗遇见债主新界安，打电话给佐敦求救，佐敦赶往途中遇见Judy 在街上狂奔。Judy正赶往医院探望刚撞车的爷爷，佐敦好心相助，载她到医院后才去救嘉华。但一到便被殴至头破血流，入院疗伤又遇见Judy 。Judy自与丈夫分开后，对别人的爱已没半点希望，再加上癌症而割去一边乳房，自信心已全失。但当遇上佐敦后，封闭的心门慢慢敞开......©豆瓣', '吴君如', '叶伟信', 8.2, 25258, 'tt0260992', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p826794784.jpg', 0.3, 1.4, 16.6, 49.8, 32, '-0.102857,-0.214187,-0.604416,-0.005775,0.164546,-0.550638,0.527542,0.383097,-0.229738,-0.050999,0.164259,0.575119,0.083512,0.365932,0.375980,-0.064749,-0.196922,-0.326866,0.344425,-0.065420,-0.435525,-0.237180,0.160114,0.123929,0.013221,-0.075116,0.257260,0.063128,-0.188948,0.809925,0.259888,0.156244,-0.508882,0.608111,-0.379107,0.243876,-0.153238,0.197023,-0.324515,0.344753,0.305985,-0.397595,-0.163090,-0.147523,0.188035,0.388046,0.598849,0.003171,-0.004667,-0.018082,0.095325,-0.113112,0.015938,0.156506,0.181146,0.169882,0.314421,0.137090,-0.290815,0.265570,-0.009434,0.006713,-0.209107,0.238485,-0.039049,-0.076975,-0.634029,0.188284,-0.102593,0.124804,0.260612,-0.520105,0.276593,0.277231,-0.288854,0.198990,-0.261456,0.028355,-0.533756,-0.241570,0.610229,-0.247173,0.582970,0.454937,0.439172,-0.022211,0.528392,-0.102381,-0.397161,-0.072318,0.149640,0.079010,0.040189,-0.348812,-0.174663,-0.057331,-0.516470,0.030455,0.004346,0.094891,-0.056048,-0.370247,0.165810,0.003349,-0.063886,0.351137,0.033286,0.028157,0.090594,-0.513569,0.379220,0.333958,0.550006,-0.963663,0.624562,-0.104549,0.086248,-0.002875,0.154857,0.436254,0.366468,0.678650,0.055082,-0.050960,-0.274526,-0.032223,-0.295875,0.039794', '1451563', '1299182', '1305543', '1303485');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304309', '圣诞快乐', '喜剧', '光头佬麦sir（麦嘉 饰）早年丧偶，独力拉扯儿子（陈百强 饰）、女儿（李丽珍 饰）和小光头三个儿女。麦sir生日之时，同事集体整蛊他表示庆祝，老板为了表彰他的多年付出，更赠送汽车一辆，谁知送车的小伙子John（张国荣 饰）与麦sir发生摩擦，不明就里的麦sir将自己的新车拆了个七零八落。麦sir将小光头寄送在对门的歌手阿凤（徐小凤 饰）家中，而麦sir对阿凤实际早有情意，但苦于无法说破。另一方面，儿女辈的情事同样令麦sir头疼，害怕女儿早早芳心他属，可John的攻势一浪强似一浪；期望儿子潇洒人间，但Danny却十足纯情……在圣诞节的前夕，麦家人拉开了各自的爱情好戏。©豆瓣', '张国荣', '高志森', 7.8, 8729, 'tt0088106', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2534465893.jpg', 0.5, 2.1, 29.6, 42.6, 25.2, '0.057482,0.030387,-0.516102,0.446810,-0.129108,-0.128505,0.574991,0.447844,-0.266119,-0.298703,-0.087506,0.439637,-0.305527,0.310719,0.073287,-0.236419,0.035383,-0.554500,0.073547,0.152381,-0.233272,-0.097077,0.094984,-0.029339,-0.270740,0.185262,0.315238,-0.020224,-0.047407,0.458273,0.644536,0.041528,0.051806,0.452167,-0.146312,0.135968,0.104206,0.173397,-0.154598,-0.088716,0.053307,-0.296889,0.004557,0.140156,-0.023835,0.407751,0.868129,-0.175995,-0.017868,-0.138157,0.308718,0.105793,0.021194,0.147323,-0.009006,0.335159,-0.109317,-0.135311,-0.075305,-0.155717,0.323291,-0.100029,-0.335691,-0.076410,-0.066513,-0.289847,-0.603718,0.549201,-0.241691,0.306153,0.018896,-0.072788,0.183852,0.039295,-0.064410,0.354827,0.025971,0.104221,-0.685449,0.329307,0.505832,0.148697,0.157763,0.424036,-0.462286,-0.393365,0.204520,-0.177484,-0.843997,-0.159607,0.484893,-0.129197,0.029658,0.252651,-0.257722,-0.078480,-0.419542,0.210859,0.072543,-0.456692,0.147612,-0.190760,-0.085796,-0.442927,-0.204899,0.312339,0.101879,-0.136489,0.832087,-0.657237,0.102668,0.331025,0.215223,-0.274924,0.752637,0.239213,0.342617,-0.291527,-0.209730,0.139535,-0.017118,-0.096100,0.426202,0.255843,-0.173126,-0.292470,-0.000024,0.225073', '26348103', '3445516', '6518721', '25882279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304318', '神勇双响炮', '喜剧', '吴亚秋（吴耀汉 饰）和贝多芬（岑建勋 饰）是香港警署反黑组一对活宝警员，这对师兄弟吊儿郎当，不务正业，入行十多年还是初级警员。好在他们生性乐观，加上陈sir（陈欣建 饰）对二人多有照顾，因此他们倒也十分享受这样的逍遥生活。所谓傻人有傻福，亚秋阴差阳错还得到陈sir的女秘书安娜﹝叶德娴 饰﹞的垂青。他们受命调查从事不法勾当而暴富的商人夏正毅（陈龙 饰），只是对方分外狡猾，不露出任何马脚。夏的情妇掌握他各种犯罪勾当的账本，并以此作要挟。夏命手下杀害情妇，而亚秋和贝多芬则成为了尸体的最先发现者。夏正毅为了得到账本，于是向情妇的表妹伸出毒手，亚秋和贝多芬能否将罪犯绳之于法？©豆瓣', '吴耀汉', '张同祖', 7.1, 4792, 'tt0088105', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2590890065.jpg', 0.6, 4.4, 48.5, 33.8, 12.8, '0.134654,-0.388890,-0.333627,0.564599,-0.453612,-0.130235,0.652995,0.186329,-0.732543,-0.181427,0.035833,0.342832,-0.138449,-0.003183,0.164301,-0.048337,-0.406313,-0.632183,-0.093895,-0.047358,-0.173542,-0.431355,-0.162033,-0.444018,-0.295313,-0.044671,0.388125,0.152730,-0.206607,0.306199,0.577189,0.342601,-0.244715,0.311236,-0.226958,-0.055957,-0.158901,0.104409,-0.344617,0.015274,0.194724,-0.324456,-0.154816,0.001364,0.040317,0.335095,0.586049,-0.261911,-0.215509,-0.271213,0.192558,-0.368053,0.028354,-0.066614,0.129571,-0.086855,0.112734,0.179893,-0.099633,-0.046207,0.116184,-0.068575,-0.786242,-0.078195,0.175969,0.049248,-0.470677,0.187617,-0.074974,0.054927,-0.011875,-0.255178,0.181222,0.321614,0.174555,0.198292,-0.060185,0.078340,-0.687068,0.329983,0.245824,0.208796,0.033808,0.125439,-0.161200,-0.688284,0.047782,-0.313703,-0.221417,-0.038903,0.257473,-0.163404,0.245670,-0.035938,-0.324298,-0.289327,-0.009401,0.142775,0.148691,-0.580642,0.128184,-0.626579,-0.012401,-0.513776,-0.378790,0.123102,0.264748,-0.477488,0.479886,-0.841763,0.032148,0.251927,0.263590,-0.620935,0.572119,-0.052581,-0.030506,-0.355047,-0.360376,0.054396,0.389852,0.128113,0.307849,0.122838,0.098981,-0.283833,0.121695,-0.002375', '4301278', '1793491', '3811342', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304337', '台北晚九朝五', '剧情', '台北的每个晚上一群年轻人都在歌舞厅内夜夜笙歌，一夜情、吃迷幻药，喝酒狂欢每天都是他们沉迷的东西。刚回台北的Eva（杨谨华 饰）坚守着爱情的信念，十分抗拒婚前性行为，她的朋友Cindy白天是上班族，晚上则是十分豪放的一夜情女王。后来Eva跟在唱片公司工作的Ben，两人同居，可是Eva就是无法接受婚前性行为，Ben只好找Cindy解决生理需要。被Eva知道后只好忍痛离开。其实Cindy一直喜欢的是卖毒品的小马（黄立行 饰），小马患有癌症末期的父亲离世，Cindy也表达了对小马多年的情感。他们身边的朋友，为生活、为需要、为开心、为自己寻找着自己最喜欢的生活方式，成为了都市中的一个缩影。©豆瓣', '张兆志', '戴立忍', 6.8, 21233, 'tt0356148', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1592496738.jpg', 2, 9.6, 46.5, 32.7, 9.4, '0.272332,-0.186999,-0.526952,0.456269,-0.295431,-0.227205,0.618140,0.048723,-0.465715,-0.462902,0.083004,0.819824,0.146112,0.597779,0.225363,-0.006884,-0.184379,-0.720169,-0.035782,0.035964,-0.098312,-0.230729,0.083154,-0.090856,-0.399456,-0.133204,0.450191,0.145078,-0.008864,0.352454,0.456335,0.223749,-0.040145,0.552634,-0.155101,-0.454905,-0.086584,-0.082031,-0.572439,0.271518,0.129883,-0.130145,0.081767,0.207136,0.171495,0.109472,0.531993,-0.210680,-0.311607,-0.087354,0.343596,-0.167307,-0.226360,0.070284,0.183166,0.015061,0.514412,0.162197,-0.331185,0.230762,0.055067,0.092393,-0.900828,-0.040682,0.080024,0.153924,-0.758812,0.476966,0.049445,-0.215137,0.251873,-0.383443,0.422877,0.330881,0.213449,0.594712,-0.163984,0.126640,-0.609523,0.247970,0.871507,0.147400,0.001156,0.416940,-0.532826,-0.316873,0.135721,-0.296590,-0.453250,-0.082993,-0.431208,0.047666,-0.398048,0.102023,-0.611162,0.255129,0.137392,-0.373571,0.264122,-0.464126,-0.076461,-0.603307,0.084620,-0.564184,-0.242689,-0.002609,0.207887,-0.344532,0.649866,-1.000509,0.198091,0.648745,0.424464,-0.831951,0.957641,0.458526,-0.075231,-0.247788,0.068900,0.185034,-0.255571,0.008778,0.000378,0.279169,0.183143,-0.002009,-0.582439,0.654894', '4301278', '3055049', '1308805', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304338', '决战猩球', '动作', '未来，地球已经无法支持如此之多的人口，所以需要前往宇宙寻找其他适合居住的星球。在寻找适合的星球的途中，人类开始训练猩猩代替人类完成一些简单的工作。在一次飞行任务中，航天员里奥（马克·沃尔伯格 Mark Wahlberg 饰）的猩猩驾驶的飞船遭遇了宇宙风暴与太空站失去联系。为了搭救自己的搭档，里奥不顾阻拦独自一人驾驶飞船前往风暴中心。可是，最终飞船坠毁到了一个陌生的星球上。当里奥醒来时被一群人猿抓了起来。经过仔细的观察，发现在这个星球上，人猿拥有极高的智慧在星球上处于统治地位，而真正的人类却成为了人猿的奴隶。为了摆脱自己的困境，里奥受到了母人猿艾瑞（海伦娜·邦汉·卡特 Helena Bonham Carter 饰）的帮助开始了逃亡之路。在逃亡过程中，里奥携带的信号接收器逐渐收到了母船发出的信号。当大家按照信号的指引前行时，却发现目的地是人猿祖先最初诞生的地方，而里奥却辨认出这就是当初的母船。到底发生了什么事情？', '马克·沃尔伯格', '蒂姆·波顿', 6.9, 45110, 'tt0133152', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1593992535.jpg', 1.2, 7.2, 47.8, 34.4, 9.4, '0.361475,0.287458,-0.831095,0.662019,-0.053772,0.091145,0.641758,0.019984,-0.451683,-0.108926,0.209450,0.800961,0.156734,0.008040,0.282917,0.087465,-0.381211,-0.266839,0.120925,-0.097125,-0.592645,-0.612875,-0.461018,-0.201799,0.016068,-0.652664,0.872724,0.133570,-0.106073,0.391537,-0.130090,0.314031,-0.106283,0.421233,-0.278353,-0.132859,0.130579,-0.093834,-0.260475,0.311318,-0.289930,-0.076847,0.166716,0.317631,-0.171570,0.403688,0.695132,-0.481576,-0.035997,-0.335729,0.197207,-0.292759,0.167157,-0.201754,0.461369,-0.048703,-0.218361,-0.162093,0.076720,0.237209,0.004458,0.080717,-0.833527,-0.141619,0.016508,0.302010,-0.441452,0.069033,-0.138592,-0.157859,-0.051868,-0.389166,0.216705,0.630740,0.129322,0.278120,-0.242718,0.071495,-0.526875,-0.227302,0.670716,-0.241294,-0.477888,0.462573,-0.045729,-0.614223,-0.268571,-0.305410,-0.355547,-0.246169,0.215979,0.413457,-0.369929,0.288975,-0.736525,0.219365,-0.379395,-0.662426,0.010521,-0.350549,-0.227566,-0.783740,0.081055,-0.295561,-0.151879,0.231714,-0.054558,-0.292619,0.630613,-0.939289,0.309402,0.870875,0.472863,-0.522227,0.648678,-0.193805,0.259351,-0.429307,0.226842,0.294497,0.181855,0.519834,-0.183112,0.027768,0.126231,-0.048917,-0.583252,0.529627', '1420088', '6532822', '1294893', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304374', '百万英镑', '喜剧', '本片拍摄于1953年，根据马克·吐温的小说《一张百万英镑的钞票》改编。富豪之家的两兄弟，从银行取出面额为一百万英镑的钞票，想以此验证一个穷人拿到这张巨额钞票的结局。哥哥认为这张钞票对一个穷人毫无价值，最终他还是会穷困潦倒；而弟弟则认为他会因为这张钞票摆脱困境过上富足的生活。为了证明各自的理论的正确的，兄弟两人为此打起了赌。他们将这张钞票留给穷困潦倒的美国小伙子亨利·亚当斯（格利高里·派克 Gregory Peck 饰）后出国旅行了，留下对未来一片迷茫的亨利。人们对这位突然暴富的罕见富翁，竟拼命地拉拢他，从免费吃饭，买衣服，到免费住宿，一个个像乞丐一样讨好他，并不断提高他的社会地位。不仅如此，这位幸运的小伙子还取到了一位好妻子和三万英镑的银行利息，从此以后过着非常幸福的生活。©豆瓣', '格利高里·派克', '罗纳德·尼姆', 8.3, 41869, 'tt0046072', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1723037871.jpg', 0.1, 0.5, 14.9, 55.5, 29, '0.193001,0.056793,-0.199427,0.658391,-0.221651,-0.636327,0.684651,0.108280,-0.137558,-0.123573,0.329560,0.993988,0.087850,0.398788,0.365726,-0.087832,-0.134479,-0.484960,-0.216588,-0.289492,-0.144081,-0.406564,-0.405874,-0.359510,-0.360653,-0.162833,0.397565,0.000367,0.070185,0.440032,0.258495,0.014107,0.244739,0.066668,-0.323513,-0.015394,-0.316767,0.385774,-0.470794,0.250992,0.044248,-0.045656,-0.018177,0.121703,0.186159,0.303229,0.658429,-0.245498,-0.197261,0.261081,0.472481,-0.005725,-0.344782,0.127601,-0.017808,0.073626,0.163382,-0.215955,-0.250093,0.131346,0.148820,-0.127956,-0.921951,-0.333319,-0.044872,0.038999,-0.663023,0.496084,-0.349249,0.025377,0.044340,-0.401459,0.040629,0.424777,0.069272,0.344717,-0.325941,0.123671,-0.677258,0.652849,0.228101,-0.005270,-0.013756,0.358702,-0.480462,-0.305784,0.101154,-0.224068,-0.562649,-0.007884,0.567024,-0.246521,0.020576,0.039447,-0.860358,0.000331,-0.157809,-0.496741,0.286762,-0.326460,-0.191972,-0.231449,-0.220920,-0.271157,-0.093635,0.107249,0.283163,-0.463033,0.975600,-0.276772,-0.057407,0.529364,0.265145,-0.462526,0.587328,0.052432,-0.095427,-0.146831,-0.362217,0.071937,0.445317,0.359038,0.006956,0.063496,0.119218,-0.076076,-0.086591,0.756855', '27602116', '4267948', '1308585', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304382', '最佳损友', '喜剧', '徐家父亲逝世了，身在美国的徐定贵（刘德华 饰）应叔父的邀请回到了香港承继遗产。徐定贵有个同父异母的哥哥徐定富，定富对于这个前来分家产的弟弟十分不满，刚好叔父要求定贵在公司工作，并要求他表现良好才能顺利领得遗产。为了能独吞财富，假仁假义的定富故意招来了三位出名的损友，跟定贵成为朋友后把他教坏。意想不到的是这三位损友不但没有把定贵教坏，四人还成为了好友。当他们知道了定富的阴谋之后，决定联手对付卑鄙的定富。©豆瓣', '刘德华', '王晶', 6.8, 12707, 'tt0096512', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2623313201.jpg', 1.1, 7, 53.2, 28.7, 10.1, '0.114097,0.039606,-0.440619,0.546217,-0.423550,-0.306865,-0.030200,0.333071,-0.552718,-0.237104,0.029201,0.831506,0.187317,0.038340,0.239940,-0.181623,-0.072389,-0.411824,-0.094439,-0.368906,0.081842,-0.694811,-0.042948,-0.075637,-0.261754,-0.100888,0.164888,-0.016064,-0.076343,0.344929,0.577907,0.253969,0.047326,0.123252,-0.256822,0.097457,0.021093,0.149250,-0.518440,0.224027,-0.236216,-0.011039,0.257064,0.141122,0.365420,0.239496,0.276112,-0.024979,-0.286970,-0.141204,0.266294,-0.309147,0.067112,0.253826,0.264483,0.042245,0.333466,0.419458,-0.323295,-0.047755,0.069490,-0.218680,-1.135558,0.048221,0.210251,-0.292123,-0.588240,0.320344,-0.064623,-0.181957,-0.191323,-0.368354,0.365409,0.488561,0.136704,0.303591,-0.155144,0.360489,-0.394346,0.081898,0.563794,-0.182515,0.100652,0.090223,-0.038967,-0.342619,0.360903,-0.539339,-0.138074,0.248801,0.493758,0.159499,0.094264,-0.004662,-0.265882,-0.402187,-0.176594,-0.024072,0.331023,-0.645599,0.050135,-0.046399,-0.186268,-0.173589,-0.204007,0.141856,0.131132,-0.284922,0.863682,-0.664310,-0.017877,0.369415,0.588156,-0.960043,0.517589,0.275705,0.150375,-0.211442,-0.098323,-0.359243,0.298292,0.034965,0.148330,0.131684,0.119603,-0.474823,-0.089527,0.103051', '26678784', '30163500', '1877596', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304401', '杂家小子', '喜剧', '大宝（梁家仁 饰）和弟弟二宝（元彪 饰）孤苦无依，相依为命，彼此之间感情十分深厚。两人整日里游手好闲，不务正业，流连于赌场之中想要获取不义之财，却每每将少得可怜的家底输得一干二净。屡屡受人欺负，大宝和二宝产生了想要习武的念头，他们拜了在饭馆里偶然遇见的高手（刘家荣 饰）为师，开始了充满艰辛与汗水的习武之路。一次偶然之中，兄弟两人意外得知他们的师傅竟然是隐姓埋名的江洋大盗，师傅得知此事想要杀人灭口，二宝侥幸逃出，大宝却被师傅残忍杀害。悲愤交加的二宝想要替哥哥报仇，恰巧遇到了曾经有过一面之缘的乞丐（洪金宝 饰），哪只这乞丐的真实身份竟是江湖名捕，在他的调教之下，二宝的武艺突飞猛涨，最终手刃了仇人，报仇了雪恨。©豆瓣', '元彪', '洪金宝', 7.5, 4985, 'tt0080166', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1957204006.jpg', 0.3, 2.6, 37.6, 43.4, 16.1, '-0.008349,-0.100422,-0.580077,0.416300,-0.248429,-0.447358,0.455440,-0.046414,-0.881692,-0.163769,0.153870,0.794655,-0.009166,0.302912,-0.136340,-0.124396,0.090393,-0.490083,0.051876,-0.207122,0.093870,-0.319051,-0.485308,0.005112,-0.397287,0.024024,0.225362,0.119024,-0.113428,0.541509,0.254924,0.119116,-0.306556,0.196426,-0.355232,0.393475,-0.066295,0.209255,-0.359900,-0.141439,0.162578,-0.265463,-0.168403,-0.035294,0.027367,0.368763,0.462829,-0.177760,-0.170940,-0.249492,0.130480,-0.184953,-0.132713,0.160894,0.161179,0.034853,0.655240,0.294031,0.038472,-0.125685,0.137078,-0.029554,-0.585918,0.050237,0.484030,-0.196039,-0.738408,0.336087,-0.005864,0.026598,0.043223,-0.227997,0.164493,0.138932,0.078652,0.245804,-0.260952,-0.123724,-0.525554,0.295575,0.620982,-0.194829,0.268176,0.151484,0.088082,-0.005375,0.478456,-0.652370,-0.292021,0.228974,0.482146,-0.089635,-0.376506,0.427581,-0.411970,-0.031784,-0.254732,0.445683,-0.083215,-0.133571,-0.172993,-0.024338,-0.260093,-0.427990,-0.435174,-0.026294,-0.018364,-0.398579,0.560104,-0.980352,0.147405,0.275768,0.220669,-0.577525,0.543362,0.040832,0.155084,-0.005865,-0.026930,-0.119095,0.043245,0.167178,0.277541,0.210465,-0.143042,-0.117452,-0.276395,0.240541', '35030151', '1419416', '1306133', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304406', '天堂的颜色', '剧情', '八岁的墨曼（Mohsen Ramezani）是盲人学校里最用功的孩子，视障也没能妨碍他对美妙的自然万物的独特感受力，他时常虔诚地用双手去找寻心中的真主安拉。然而，命运却喜欢同他开玩笑，母亲离去多年后，父亲（Hossein Mahjoub） 为了再娶，决定甩掉他这个拖油瓶。父亲先把墨曼从盲人学校接回家，在家乡，墨曼从奶奶（Salameh Feyzi）与两个妹妹那里，得到真挚的爱，感受到了秀美风景里所藏的快乐，快乐总是暂时的，他接着就被父亲连拖带拽送到了一个盲人木匠处当学徒……©豆瓣', '侯赛因·马哈古', '马基德·马基迪', 8.7, 12605, 'tt0191043', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1484017510.jpg', 0.1, 0.6, 9.2, 44.4, 45.7, '0.306183,0.120593,-0.699677,0.547211,-0.491282,-0.342360,0.638804,0.010416,-0.401705,-0.109883,-0.010604,0.838635,0.273848,0.625353,0.047887,0.401008,-0.074310,-0.631044,0.036251,0.111739,-0.258164,-0.233268,-0.035206,0.039952,-0.119655,-0.040592,0.232573,-0.011815,0.014745,0.415558,0.150594,0.057528,-0.234764,0.341139,-0.527288,0.001013,-0.372217,0.084821,-0.322037,0.208197,0.396897,-0.087004,-0.129800,0.048812,0.025393,0.120295,0.558794,-0.172135,-0.092240,0.097606,0.288694,-0.115302,-0.160442,0.329170,-0.146418,0.087051,0.161122,0.134408,-0.229821,0.021637,0.069357,-0.216277,-0.559077,-0.069716,0.067415,-0.037909,-0.798207,0.355787,-0.046746,-0.303643,0.345912,-0.498582,0.474621,0.122463,-0.348083,0.626595,-0.358431,0.210163,-0.120279,0.214261,0.552210,-0.263770,0.028536,0.334377,-0.346895,-0.199619,0.354995,-0.278078,-0.566322,0.026831,0.131631,0.221553,-0.253106,-0.114775,-0.316780,0.038633,-0.069406,-0.036613,0.175062,-0.722109,-0.089832,0.040999,0.196609,-0.302748,-0.246533,0.026988,0.091141,-0.283519,0.724604,-0.576649,0.520856,0.584491,0.253644,-0.347161,0.896903,0.049545,0.215748,-0.282870,0.226850,0.317161,0.097214,0.383624,0.147932,0.322140,0.030828,0.090851,-0.583840,0.592415', '1292207', '1297606', '1456503', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304447', '记忆碎片', '剧情', '当记忆支离破碎后，你该怎样面对生活？本片的主人公就遭遇了这样的事情。莱纳•谢尔比（盖伊•皮尔斯 饰）在家遭到歹徒的袭击，妻子被残忍的奸杀，自己脑部也受到严重的伤害。醒来后，他发现自己患了罕见的“短期记忆丧失症”，他只能记住十几分钟前发生的事情，为了让生活继续下去，更为了替惨死的妻子报仇，他凭借纹身、纸条、宝丽来快照等零碎的小东西，保存记忆，收集线索，展开了艰难的调查。调查中，莱纳遇上粗俗的酒吧女招待娜塔莉娅(凯瑞•安妮•莫斯 饰)，她似乎知道一些莱昂纳多感兴趣的事；还有泰迪(乔•潘托利亚诺 饰)，自称是他以前好朋友，但看上去鬼鬼祟祟的，不怀好意。到底谁能相信？娜塔莉娅？泰迪？还是他自己？抽丝剥茧之后，真相呼之欲出，简单之至却又残酷无比，而莱纳是否有面对这一切的勇气？©豆瓣', '盖·皮尔斯', '克里斯托弗·诺兰', 8.7, 566630, 'tt0209144', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p641688453.jpg', 0.3, 0.9, 10.5, 41.7, 46.6, '0.125731,-0.044201,-0.396885,0.334192,-0.066761,-0.095926,0.741549,-0.220362,-0.420885,-0.467602,-0.010078,0.575183,-0.043909,0.158299,-0.010266,0.256086,-0.509481,-0.582663,0.373321,0.051824,-0.498285,-0.520944,-0.122248,-0.388653,0.146319,-0.185134,0.191152,0.164852,-0.162222,0.126568,0.281330,0.318005,0.137419,0.501110,0.048292,0.141235,-0.029249,0.145532,-0.029329,-0.033052,0.499874,-0.287724,0.037400,0.469119,0.105702,0.367894,0.473023,-0.096994,-0.344191,0.082361,0.324946,-0.264830,0.187479,0.261327,0.066047,-0.107122,0.094761,-0.013288,-0.331566,-0.199233,0.049621,0.128241,-0.781098,-0.150096,0.097979,0.120809,-0.407386,0.024024,-0.165411,0.266526,0.139879,-0.097476,0.153192,0.468476,0.459092,0.133992,-0.005910,-0.083985,-0.351366,0.009096,0.561206,-0.073337,-0.347821,0.322397,-0.261399,-0.464605,-0.036929,-0.313298,-0.267880,0.289435,0.204951,0.104960,-0.359733,0.404453,-0.221431,-0.277579,-0.370595,-0.058649,-0.259587,-0.277252,-0.287171,-0.169052,-0.319713,-0.379761,-0.523964,-0.042022,-0.170936,-0.403399,0.580119,-0.638386,0.192203,0.457417,0.313184,-0.547407,0.314834,0.061666,0.102918,-0.199620,0.004508,0.532903,0.143299,-0.035840,0.263138,0.112965,0.332757,-0.075499,-0.247759,0.546650', '26678784', '4820775', '30163500', '2036270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304469', '半支烟', '剧情', '下山豹（冯德伦）为了迷恋的舞女（舒淇）而与九纹龙（李灿森）在舞厅决斗，战败后流亡到巴西成为大厨，二十年过去，患了老年痴呆症的下山豹（曾志伟）回忆起自己这些年的寂寞生活，陪伴自己的只有邓丽君的国语老歌《我只在乎你》和装有舞女抽过的半支香烟的随身烟盒，决定回到香港寻找舞女。下山豹于街头结识了少年烟仔（谢霆锋），与他的痴情截然相反的是，烟仔认为哪怕是嘴上叼着的香烟都比爱情长久。看在金钱的份上，烟仔答应帮下山豹的忙，慢慢地，两段过去的浓情浪漫爱情故事开始燃烧。©豆瓣', '谢霆锋', '叶锦鸿', 7.3, 24717, 'tt0228048', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2512339351.jpg', 0.7, 4.4, 39.7, 40.1, 15.2, '0.341856,0.019434,-0.358999,0.376489,-0.098884,-0.422953,0.748200,0.047360,-0.164512,0.082624,0.158438,0.686240,0.118529,0.414059,0.267347,-0.097772,-0.015091,-0.866215,-0.054090,-0.130757,-0.247031,-0.202707,-0.108990,0.012082,-0.129212,-0.228746,0.640532,0.119268,-0.001175,0.633409,0.284954,0.129311,-0.116738,0.303585,-0.657660,0.116770,-0.466164,0.164497,-0.332978,0.123616,0.295878,-0.386600,-0.212393,-0.175276,0.050531,0.080185,0.754119,-0.146482,0.033087,-0.083465,0.214337,-0.273125,-0.096128,-0.085868,0.264322,0.310830,0.272203,0.129241,-0.200479,0.137779,-0.222523,-0.105770,-0.415101,0.129069,-0.100266,0.266839,-0.819501,0.698199,-0.118362,-0.002779,0.324367,-0.315899,0.188212,0.060928,0.051652,0.357045,-0.190358,-0.020358,-0.647397,0.500653,0.618008,0.063193,0.010020,0.398803,0.094310,-0.250851,-0.120295,-0.158152,-0.431663,-0.203868,0.322701,-0.100379,-0.278028,0.076820,-0.728057,-0.003478,-0.010458,-0.187277,0.457345,-0.303617,-0.118655,-0.463702,-0.165391,-0.438033,-0.059402,-0.113822,0.361089,-0.463106,0.689455,-0.541537,0.167522,0.464302,0.180894,-0.292339,0.764540,-0.156240,-0.031263,-0.076240,-0.078541,0.435532,0.182119,0.198247,0.297418,0.300031,-0.169309,0.137795,-0.715789,0.333761', '1307146', '21619567', '30162520', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304476', '独立时代', '剧情', 'Birdy（王也明）、Molly（倪淑君）、琪琪（陈湘琪）、小明（王维明）四个大学同学毕业后做着不同的工作，表面光鲜程度虽有异，都有身份转变（由学生到社会人）时期的尴尬。而这其中最难做人的，是夹在好友Molly与男友小明之间的琪琪，她只能暗自努力，以期好友、男友的事业与生活能有所改观，三人的关系能有所改善，却得到双方的误会。Molly的姐夫（阎鸿亚）在认定生活就是由若干玩笑构成的排列组合后，开始转身面向两千多年前的孔子，然而他自认重获精神家园之时，却收获了同琪琪一样的无奈——两人被认定不过是演技好的实力派而已。人生的荒谬与悖论就此呈现，表演只有迎合了旁观者（观众）的心里，才会被认定为“真实可信”。©豆瓣', '陈湘琪', '杨德昌', 8.8, 39062, 'tt0109685', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2416432789.jpg', 0.2, 0.7, 9, 39.1, 51.1, '0.566565,-0.136319,-0.586663,0.602080,-0.075620,-0.279265,0.580886,0.226401,-0.741942,-0.096381,0.118112,0.760249,-0.382499,0.240155,0.270598,-0.220388,-0.157248,-0.870059,-0.066161,-0.273252,-0.014453,-0.581200,-0.171981,-0.123962,-0.429025,-0.257674,0.681780,-0.006260,-0.112528,0.356030,0.302011,0.243713,0.036666,0.387557,-0.156140,-0.078951,-0.074092,0.142426,-0.390817,-0.054491,0.267873,-0.049697,-0.114148,0.380598,-0.104446,0.342033,0.700329,-0.070724,-0.453486,0.041482,0.430533,-0.170310,-0.125676,0.118897,0.220991,0.107888,0.398873,0.239944,0.211602,0.156613,-0.010948,0.020749,-0.842252,-0.005437,0.338783,0.098893,-0.540010,0.630487,0.133219,-0.446807,0.069878,-0.247580,0.121605,0.556299,0.495390,0.501118,-0.239276,0.013846,-0.471211,0.050153,0.708157,0.315224,-0.458501,0.663832,-0.401160,-0.421265,-0.043974,-0.222392,-0.324180,-0.041250,-0.012913,0.336618,-0.097662,0.194501,-0.592301,-0.017623,-0.028847,0.078651,0.133875,-0.703248,0.002140,-0.140484,-0.371037,-0.629800,-0.511568,0.056840,-0.022076,-0.520508,0.862503,-1.181767,-0.134272,0.147756,0.270621,-0.541814,0.812027,0.224090,0.081800,-0.356649,0.047600,-0.047015,-0.447538,0.256237,-0.016344,0.233607,0.103701,-0.266962,-0.453722,0.483687', '35030151', '1395231', '30345227', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304485', '穿越时空爱上你', '喜剧', '莱伯特（休•杰克曼 饰）是19世纪的一名落魄贵族公爵，在家人为他安排的相亲宴会上，他为了追踪一个陌生人，疯狂科学家斯图尔特，无意闯入时空隧道，来到了100多年后的21世纪，斯图尔特的意外住院使公爵面对陌生的环境举步维艰。机缘巧合下，他邂逅了斯图尔特的前女友凯特（梅格•瑞恩 饰）——一个野心勃勃、独立聪明的广告界女强人，一连串的事情，使二人互相吸引，谱写出一段跨越时空的浪漫恋曲......但是，穿越时空的情感注定不会一帆风顺。为了顺应历史的发展，出院的斯图尔特不得不把莱伯特送回属于他的年代，莱伯特和凯特刚刚开始的恋情面临时空分离的危机。两人是命定的缘分还是刹那的相逢？两人能否穿越时空的阻隔在一起？©豆瓣', '梅格·瑞恩', '詹姆斯·曼高德', 7.4, 71509, 'tt0035423', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p475932453.jpg', 0.3, 2.9, 36.9, 45.2, 14.7, '0.395777,-0.010690,-0.485441,0.514675,-0.151300,-0.173480,0.700583,0.015984,-0.539195,-0.291750,0.289377,0.884935,-0.391154,0.247974,0.553604,0.125996,-0.323837,-0.605105,0.103691,-0.217249,-0.320180,-0.425166,-0.450148,-0.232760,0.040193,-0.468673,0.725809,0.128749,-0.266032,0.287131,0.241227,0.448208,-0.381691,0.394979,-0.353749,0.029254,0.164383,0.077136,-0.688487,0.210978,-0.103328,-0.098969,-0.046069,0.136294,-0.206866,0.241844,0.488832,-0.415954,0.102144,0.029098,0.699221,-0.220473,-0.178696,-0.095271,0.265255,-0.116351,0.028239,0.320681,-0.164659,-0.108434,0.046438,-0.193814,-0.758432,0.010350,0.089319,0.202822,-0.483531,0.516489,0.110128,-0.188363,0.096887,-0.222180,0.156530,0.511271,0.623855,0.432934,-0.024324,0.034990,-0.281636,-0.023795,0.939489,0.035479,-0.539453,0.484681,-0.395098,-0.323603,-0.031630,-0.257565,-0.752127,-0.070454,0.325626,-0.047916,-0.009319,0.493017,-0.474211,-0.091533,-0.484149,0.098674,0.139791,-0.549199,-0.170000,-0.522212,-0.182155,-0.380923,-0.178149,0.206788,-0.046333,-0.310128,0.442948,-0.737390,0.217230,0.719724,0.225801,-0.339232,0.905495,0.132018,0.165836,-0.519125,0.073158,0.421751,-0.051319,0.153241,-0.018702,0.374888,0.073975,0.167394,-0.331084,0.529619', '30162520', '25721544', '34890458', '30402056');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304490', '大毒枭', '剧情', '虽然身为建筑工人的儿子，乔治荣格（约翰尼·德普 Johnny Depp 饰）却并不愿被低下的出身所束缚。怀着远大的理想，他来到了加利福尼亚追逐自己的梦想。很快，靠着贩卖大麻，荣格赚到了一笔不义之财，但也因此摊上了牢狱之灾。在狱中，荣格结识了他“同病相怜”的狱友，狱友将他介绍给了大毒枭艾斯科巴（克利夫·柯蒂斯 Cliff Curtis 饰）。很快，荣格成为了全美毒品运输的重要枢纽，而靠着贩毒，荣格赚取了金钱不计其数，他终于过上了他曾经向往的那种纸醉金迷的生活。可是，在内心里，对于自己所干的勾当，荣格深深的感到耻辱，再多的金钱也填补不了那不被亲人理解和接纳的痛苦，而在最后的最后，他也终究逃不过恢恢的法网。©豆瓣', '约翰尼·德普', '泰德·戴米', 7.9, 19061, 'tt0221027', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1322245019.jpg', 0.3, 1.8, 25.4, 49.5, 23, '0.354641,0.020366,-0.754561,0.522315,-0.270889,-0.622906,0.897010,0.130673,-0.648191,0.003693,0.068356,0.955668,0.051093,0.262009,-0.008324,0.105298,-0.104997,-0.521623,-0.017892,-0.237114,-0.209669,-0.609313,-0.431867,-0.304951,-0.355723,-0.090262,0.560703,0.235946,-0.045705,0.296771,0.399900,0.437912,0.383982,0.518882,-0.267639,0.100927,0.159826,0.098700,-0.226301,0.087831,0.116367,-0.436250,0.020258,0.408547,-0.068025,0.373980,0.509573,-0.379494,-0.149395,0.034971,0.246379,-0.557057,-0.132435,0.095511,-0.158450,0.022920,0.091724,0.235332,-0.331059,0.000583,0.169767,0.128507,-0.985614,-0.155093,0.122295,-0.072648,-0.874983,0.771046,-0.036051,-0.219694,-0.086720,-0.198577,0.195235,0.306256,0.074540,0.405202,-0.398172,0.049983,-0.615081,0.398046,0.713228,-0.088997,-0.298731,0.442503,-0.568978,-0.396201,0.045833,-0.532886,-0.320643,-0.200642,0.476912,0.279989,-0.292553,0.354940,-0.599165,0.000096,-0.232571,-0.241934,-0.040269,-0.488900,0.011069,-0.231393,-0.414173,-0.585002,-0.384621,0.069172,0.407869,-0.374026,0.707306,-0.767383,0.084879,0.678629,0.293062,-0.603270,0.616517,-0.015525,0.085323,0.020337,-0.204764,0.466649,0.085327,0.565054,0.295822,0.267586,0.134159,-0.290298,-0.149842,0.770821', '1299932', '1783461', '1793491', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304496', '红色星球', '动作', '时间进入2050年，现代文明的发展和人口数量的激增反而令地球不堪重负，原本美丽的星球已经不再适合人类居住。为了寻找新的生存之地，科学家们将目光所定在与地球环境最为相似的火星。在过去的几十年里，他们不断向火星发射无人飞船，试图运用现代科技来改善火星上相对恶劣的居住环境。然而当一切初见成果之时，火星上的机器却突然出现故障，移民火星的计划被迫停滞。地球的状况愈来愈让人担忧，为了尽快排除故障，由凯特·鲍曼（凯瑞-安·莫斯 Carrie-Anne Moss 饰）、罗比·加莱尔（方·基默 Val Kilmer 饰）等顶尖科研人员组成的探险队奉命前往人类从未涉足的红色星球。他们的旅程从一开始便注定充满磨难，队员们不仅要面对恶劣的外星环境，他们的友情和信任也承受着巨大的考验……©豆瓣', '方·基默', '安东尼·霍夫曼', 6.5, 5683, 'tt0199753', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2169045842.jpg', 1.5, 10.4, 54.7, 26.3, 7.2, '0.141058,0.189142,-1.006564,0.583720,0.025464,-0.089682,0.759770,-0.005650,-0.389262,-0.150839,0.223170,0.625107,-0.151941,0.041540,0.183674,-0.136495,-0.500278,-0.414621,-0.163066,-0.239001,-0.572470,-0.413429,-0.377483,-0.437717,-0.133792,-0.422692,0.720533,0.318132,-0.227162,0.401391,-0.270414,0.304288,-0.184040,0.574023,-0.239097,-0.490410,-0.086976,0.097133,-0.460631,0.011879,-0.218013,-0.229623,-0.065450,0.083586,0.018944,0.252259,0.793910,-0.449111,-0.042399,-0.278212,0.170576,-0.128495,0.104447,-0.031757,0.296737,-0.076756,-0.088465,-0.006087,-0.062708,0.090876,0.029754,-0.302065,-0.840562,-0.014284,0.067853,0.072540,-0.444485,0.301644,0.034599,-0.241200,-0.017515,-0.347779,0.121825,0.470386,0.337570,0.415411,-0.390534,0.018877,-0.127796,-0.027332,0.647655,0.069876,-0.606984,0.307138,-0.453843,-0.612095,-0.256973,-0.220518,-0.359496,-0.203102,0.281431,0.224983,-0.127763,0.572753,-0.920913,0.281792,-0.157714,-0.681487,0.132904,-0.258318,-0.139207,-0.859635,-0.084881,-0.371496,-0.341127,0.220927,0.138709,-0.143735,0.899635,-0.731381,0.102747,0.552908,0.357319,-0.622287,0.499288,-0.310717,0.088497,-0.305364,-0.077733,0.325615,-0.014019,0.707964,-0.077356,0.189423,-0.180120,0.251989,-0.349346,0.489783', '2159244', '3006772', '1292680', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304530', '男人四十', '剧情', '人到四十的香港某中学国文教师林耀国（张学友）是业已消失的“好好先生”。念书时是学校里有名才子的他，如今面对飞黄腾达、闲来便会打打高尔夫球的昔日同窗，只收获了一份难言的失落，但在他的“坏学生”胡彩蓝（林嘉欣）眼中，他却是有内涵的成熟魅力男。胡彩蓝身上有几分林耀国妻子文靖 （梅艳芳）当年的影子，她的大胆示爱令林耀国勾起一段深埋在心底的往事，触动心中伤痛，当年的浪漫诗意梦想渐渐只能压在箱底，而选择承担下的本不属他的责任却一背背了二十年。外加其它突如其来的事，一时令他无所适从，然而他却必须作出选择。©豆瓣', '张学友', '许鞍华', 8.1, 60192, 'tt0312886', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p894850389.jpg', 0.1, 1, 19.3, 54.8, 24.7, '0.234424,0.053191,-0.560355,0.608167,0.063700,-0.348828,0.731959,0.070146,-0.592055,-0.134868,0.149376,0.481273,-0.071514,0.648975,0.217305,0.116223,-0.010041,-0.656285,-0.153940,-0.262579,-0.022828,-0.419060,-0.336080,-0.208759,-0.178977,-0.106368,0.670772,0.376229,-0.252423,0.476906,0.441417,0.159243,0.061593,0.623725,-0.120759,-0.139365,-0.145361,0.113868,0.132715,-0.107831,0.299727,-0.441084,-0.341301,0.088208,-0.166744,0.571188,0.430857,0.142843,-0.203751,0.016405,0.438727,-0.112783,-0.128068,-0.055740,-0.081543,-0.054369,0.116909,0.241499,-0.173188,-0.003913,0.196374,-0.037293,-0.460263,-0.141772,0.171859,0.067720,-0.494143,0.390889,-0.081405,0.071751,0.099501,-0.213591,-0.132153,-0.413132,0.186515,0.402863,-0.175959,0.228618,-0.132784,0.311634,0.627540,0.016068,-0.315037,0.210983,-0.401117,-0.332993,-0.107404,-0.233393,-0.303327,0.082262,0.184465,0.244678,0.000828,0.197123,-0.306807,-0.028555,-0.043360,0.143274,-0.041564,-0.292498,-0.081727,0.018783,-0.176269,-0.362864,-0.523701,-0.072887,0.417209,-0.266351,0.831258,-0.779990,0.043665,0.429219,0.062309,-0.217987,0.553726,0.240583,0.030852,0.005106,-0.050706,0.300453,-0.516836,0.005210,-0.112379,0.248075,-0.228662,-0.228651,-0.273504,0.627472', '35030151', '25922902', '1466907', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304534', '香魂女', '剧情', '香二嫂（斯琴高娃 饰）是一位精明能干的女掌柜。她经营的香油厂获得了日本女商人的投资，可谓生意兴隆。但是，她有时也会黯然神伤，因为相夫教子令她寸断肝肠。老伴（雷恪生 饰）腿部有残疾是个酒鬼，孩子是天生的智障，这样的打击令她承受了巨大的精神压力。她唯一快乐的便是跟情人（陈宝国 饰）在一起的时光，但是他的怯懦与怕事，让她的希望逐渐破灭……为了给傻儿子讨一个好媳妇，她曾试图让媒婆牵线搭桥，但是应征的姑娘大多相中的是她的家产。最后，她出下策生生地拆散了一对情投意合的恋人，用金钱逼迫善良的女孩环环（伍宇娟 饰）就范。然而，事情的发展却远远出乎她的意料……本片获得1993年第43届柏林电影节最佳影片金熊奖。©豆瓣', '伍宇娟', '谢飞', 8.1, 7917, 'tt0108608', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2538910156.jpg', 0.4, 1, 17.8, 56.3, 24.5, '0.057707,-0.127200,-0.546381,0.555675,-0.374107,-0.322382,0.610817,0.342862,-0.422642,0.038550,0.269767,0.774415,-0.033776,0.061290,-0.038986,0.237433,0.328771,-0.536283,0.019660,0.042455,0.077526,-0.232811,-0.257550,-0.201285,-0.234507,-0.264151,0.664667,0.062397,-0.031093,0.188209,0.587858,0.063396,0.344065,0.286012,-0.323375,0.203223,-0.145563,0.223604,-0.121852,0.126990,0.032144,-0.255359,-0.077914,0.192127,-0.088967,0.462264,0.595345,-0.194232,-0.014066,-0.099968,0.467673,-0.276116,-0.096768,0.115053,-0.014623,-0.132950,0.344050,0.091359,-0.348154,-0.224571,0.328446,0.069800,-0.704220,-0.006930,0.487230,-0.103331,-0.777490,0.423817,0.072037,-0.021650,-0.049124,-0.174283,0.175769,0.265518,0.193500,0.401047,-0.312661,0.071513,-0.581688,0.447018,0.704757,0.056873,-0.370273,0.394219,-0.545785,-0.415418,0.153056,-0.664331,-0.685870,0.156813,0.167958,-0.008891,-0.176759,0.150881,-0.539180,-0.038828,-0.240444,0.188934,0.024811,-0.614843,0.002426,-0.175940,-0.052163,-0.434629,-0.378919,-0.100614,0.236779,-0.427550,0.952246,-0.593214,0.050054,0.644614,0.258829,-0.668939,0.904758,0.212304,0.036740,-0.134968,-0.126115,0.005787,-0.189570,-0.065894,0.121977,0.392427,-0.062241,-0.149433,-0.148844,0.422365', '1877596', '1456503', '1908036', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304536', '绝色神偷', '剧情', '英俊大盗洛子扬（张智霖）一年只有一个工作日，但每次都能满载金箔而归。一次执行计划时巧遇另一女神偷阿Cat（舒淇饰）与姐妹同来盗宝，二人一见倾心，结为情侣。二人相处一段时日越发难以沟通，最终以分手收场。三年后，Cat任职于某高科技公司，但内心深处 仍忘不了与子扬那段恋情。在一次与好朋友八爪（林熙蕾饰）聚会的时候， 却意外收到俄罗斯人交来的一段关于子扬的求救片段。 原来子扬答应俄罗斯黑手党偷取美国Megasoft最新发明之“电脑病毒 全能解除系统”（简称K.T.V.），软件正藏在阿Cat公司的保险库内，里面机关重重。子扬行动失败被掳，俄方威胁Cat七天内偷取K.T.V.换 人，否则子扬将被杀。 Cat情丝未断，不忍情郎被杀，准备再闯江湖，命八爪召集神偷七姐妹其余五人：马骝、蜘蛛、白鸽、金鱼与孔雀一起协救子杨。就在她们即将顺利完成任务时，却发现原来其中另有隐情……', '舒淇', '霍耀良', 6.3, 23138, 'tt0288480', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2188527750.jpg', 2.2, 13, 58.2, 20.9, 5.7, '0.238976,-0.002610,-0.329415,0.330473,0.265710,-0.431483,0.382787,-0.252352,-0.518030,-0.285332,0.035572,0.473786,-0.358269,0.012299,0.113586,-0.175974,-0.189757,-0.532531,0.075589,-0.436741,-0.087203,-0.336015,-0.141239,0.020351,-0.083695,-0.178728,0.633870,-0.052311,0.151976,0.621779,0.197116,0.189236,-0.582794,0.344708,-0.019692,-0.174019,0.256421,0.143231,-0.546463,0.328194,0.108474,-0.177219,0.046889,-0.024159,-0.077173,0.236125,0.606015,-0.243739,-0.121366,-0.290778,0.225720,-0.005048,-0.215634,0.029383,0.367928,0.145780,0.361240,0.500914,-0.322775,-0.084470,0.193900,0.027896,-0.356958,0.099048,0.108244,-0.074452,-0.273478,0.044896,-0.217905,0.327694,0.067915,-0.333774,0.062331,0.365938,0.752475,0.175125,-0.114307,0.094966,-0.416292,0.174399,0.742608,-0.234280,0.035757,0.178709,0.331029,-0.297332,0.319429,-0.133315,-0.137795,0.292133,0.224472,0.091692,-0.149936,0.132033,-0.649152,0.037235,-0.256836,0.235247,0.131559,-0.406827,0.004033,-0.710126,-0.190585,-0.009821,-0.231764,0.269653,0.431344,-0.084050,0.396715,-0.732941,0.226746,0.238856,0.338870,-0.428479,0.608334,0.359643,0.176560,-0.349438,0.169994,-0.172564,0.021144,0.288127,0.287449,0.126768,0.014952,-0.183014,-0.447420,-0.105109', '1507140', '26365262', '3147969', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304541', '时空访客', '喜剧', '康德公爵（让•雷诺 Jean Reno饰）是12世纪的贵族，这天他前来城堡与公主订婚，却遭到奸人迫害。他的酒杯里被投下巫婆的毒药，让他喝下了迷魂药。神志不清中，康德杀死了公主，被抓入大牢。仆人安德烈（克里斯汀•克拉维尔 Christian Clavier饰）去找巫师，让康德回到事件之前。但是，粗心的巫师却抓错了药，结果康德和安德烈去到了21世纪的芝加哥。他们遇上了康德的后人朱莉亚（克里斯蒂娜•艾伯盖特 Christina Applegate 饰），得知如果他们不及时回到12世纪，罗萨琳公主将无法复活，后人就会消失。但是安德烈却乐不思蜀了。他和一个女孩打得火热，并不大愿意回到12世纪。然而时间不等人，康德的归去越来越迫切，而安德烈却还在温柔乡里磨蹭。事情越来越棘手。©豆瓣', '让·雷诺', '让-马里·普瓦雷', 7.2, 7050, 'tt0189192', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p767910947.jpg', 0.8, 4.4, 44.6, 36.7, 13.5, '0.366266,0.210610,-0.412517,0.460982,-0.216252,-0.341511,1.069810,0.133822,-0.748427,-0.222843,0.234224,0.662301,-0.173975,-0.001328,0.408347,0.465861,-0.752054,-0.522280,0.400780,-0.335721,-0.198710,-0.497045,-0.123949,-0.277588,-0.045140,-0.412768,0.405631,0.012777,0.058923,0.283268,-0.026883,0.249925,0.077748,0.888391,-0.277280,0.390561,0.293785,-0.309428,0.143557,0.507098,0.462259,-0.360749,-0.166686,0.399852,0.081922,0.222718,0.213044,-0.417604,0.362096,-0.185458,0.155020,-0.444454,-0.200116,0.463410,0.368339,-0.296688,0.120751,0.166680,-0.186775,0.107850,0.004623,-0.023058,-0.233215,0.452033,-0.080833,0.238200,-0.933875,0.430650,-0.351101,-0.042023,-0.035818,-0.328989,0.313903,0.204737,0.229567,0.335418,-0.167610,-0.279953,-0.854052,-0.046162,0.766548,-0.038561,-0.005745,0.139420,-0.032243,-0.623608,-0.147097,-0.282883,-0.441098,0.039890,0.465520,0.009208,-0.274120,0.462205,-0.390906,-0.177270,-0.723178,-0.228727,0.064489,-0.366404,-0.147724,-0.404695,-0.028732,-0.183747,-0.219715,0.110217,0.136874,-0.214263,0.439190,-0.674697,0.158867,0.522572,0.500947,-0.285528,0.700562,-0.073493,-0.100472,0.005691,0.025005,0.193109,-0.016246,0.472149,0.384340,0.609972,0.194711,-0.147191,-0.139329,0.417335', '1308755', '1302384', '1578663', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304554', '史酷比', '喜剧', '鬼怪岛是一家以恐怖灵异为主题的游乐园，然而，某一日，这里却真的出现了灵异事件，导致顾客们纷纷四散奔逃，游乐园门可罗雀。游乐园老板找到了沙奇（马修·里沃德 Matthew Lillard 饰）和他的大狗史酷比（Neil Fanning 配音），希望他们能够前来降妖除魔。在机场，沙奇遇见了久违的弗雷德（小弗雷迪·普林兹 Freddie Prinze Jr. 饰）、威尔玛（琳达·卡德里尼 Linda Cardellini 饰）和蒂芙尼（莎拉·米歇尔·盖拉 Sarah Michelle Gellar 饰），曾经因为意见不合而分道扬镳的四人再度聚到了一起。在游乐园中，沙奇一行人遇到了有史以来最大的危机，并最终发现游乐园闹鬼的幕后黑手正是老板本人，他的阴谋究竟是什么呢？©豆瓣', '小弗雷迪·普林兹', '拉加·高斯内尔', 6.2, 6175, 'tt0267913', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195228747.jpg', 3.1, 14.7, 56, 19.6, 6.6, '0.520237,-0.095522,-0.724447,0.213615,0.333559,-0.216351,0.695516,0.156236,-0.550446,-0.331152,0.224103,0.790473,-0.419549,0.380109,0.349616,0.010983,-0.251036,-0.385150,0.125681,-0.198383,-0.273486,-0.462928,-0.250858,-0.296278,0.066288,-0.068564,-0.065119,0.333090,-0.004768,0.572171,0.690588,0.380803,-0.401178,0.395403,0.060536,-0.111562,0.295943,0.107895,-0.262348,0.202657,-0.095748,-0.083995,-0.371894,0.190459,0.246576,0.313107,0.382572,-0.400509,-0.083698,-0.094867,0.034791,-0.239111,0.148042,0.033746,0.361484,-0.168742,0.354096,0.217072,0.000458,-0.050100,0.197136,0.048986,-0.438920,0.198957,-0.049705,0.210469,-0.324982,0.078178,0.129737,-0.350815,0.200054,-0.266133,0.412681,0.263185,0.322931,0.061441,0.024857,-0.250470,-0.598534,-0.028307,0.742795,-0.086437,0.059209,0.306336,-0.082504,-0.423273,-0.052588,0.049860,-0.249029,0.194548,0.307946,0.065262,-0.194558,0.239731,-0.796886,-0.018080,-0.282937,-0.246160,-0.136117,-0.127778,0.003768,-0.858747,-0.026148,-0.215708,-0.162194,0.127930,-0.227313,0.040319,0.407812,-0.818344,0.145083,0.618189,0.216919,-0.478537,0.698979,-0.144569,-0.011231,-0.005655,-0.284977,0.079784,0.078561,0.255484,-0.072504,0.283662,0.242831,-0.426031,-0.395272,0.388211', '3147969', '1301686', '3326747', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304560', '二子开店', '剧情', '青年二子（陈佩斯 饰）待业在家，整天无所事事。哥们麻杆闻得居委会有意让他们几个待业青年合伙承包一家小客店，赶来和二子商量。二子觉得这个主意不错，于是和麻杆开始“招兵买马”，他们找来了失业在家的女生英子（张静林 饰）、父母都不在了的大虎和不堪忍受继父虐待的小豆（李楠 饰） 。在二子父母的资金和多方面支持下，这群年轻人终于领会了营业执照，将小客店包了下来。然而，开店后困难接踵而至，这群年轻人最后能否获得成功？©豆瓣', '陈强', '王秉林', 7.6, 21298, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2230047630.jpg', 0.4, 2, 31.9, 48.2, 17.6, '0.171185,-0.227124,-0.588643,-0.061118,-0.242527,-0.471473,0.295847,0.379180,-0.315492,-0.241541,-0.062094,0.523711,-0.032479,0.528019,0.034220,-0.263389,-0.297936,-0.323459,-0.342108,0.168881,-0.144945,-0.310568,0.207086,-0.229528,-0.233224,0.228543,0.041878,-0.152766,0.080212,0.427253,0.305581,-0.066421,-0.125605,-0.055970,-0.308157,0.279531,0.076841,-0.007749,-0.180784,-0.028588,-0.002637,0.172613,-0.204080,-0.214001,0.565917,0.302768,0.585449,0.173061,-0.240055,-0.167438,-0.001283,0.009073,-0.166296,0.170317,0.162793,0.016460,0.635212,-0.027468,-0.299315,0.029564,-0.013433,-0.138430,-0.383997,0.405859,-0.005879,-0.012138,-0.839123,0.352232,0.122457,-0.255890,-0.011777,-0.664932,0.116932,0.542235,-0.123108,0.439891,-0.142897,0.154336,-0.609788,0.218170,0.661719,-0.003828,0.102852,0.048063,0.239920,0.008959,0.064768,0.014802,-0.372020,-0.315511,0.470835,-0.074034,-0.483569,-0.144959,-0.600421,-0.006721,-0.002206,-0.025682,0.058133,-0.364311,-0.211386,-0.436139,-0.019079,-0.300660,-0.271029,0.345858,0.401032,-0.113616,0.782545,-0.672190,-0.026035,0.140808,0.376622,-0.620601,0.339943,0.131323,0.387659,-0.187377,-0.125665,-0.571663,0.112515,0.267803,0.481035,0.389481,-0.395698,-0.410683,-0.332001,0.010318', '1291565', '1419416', '1877596', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304585', 'BJ单身日记', '喜剧', '布里奇特•琼斯（蕾妮•齐维格 饰）是一个32岁的单身女子。她的工作及生活都是平淡无奇的，她唯一想得到一份真挚的爱情，就算有一众好友在身边及时安慰，布里奇特还是没有好过点。新的一年里，她要过一种新的生活。她选择用日记把自己生活里的点点滴滴都记录下来，她开始变得喜悦起来。这时在她与风流倜傥的上司丹尼尔•克里弗（休•格兰特 饰）产生了感情，丹尼尔原来早与女友订婚，使布里奇特伤心不已。高傲却真实的马克•达西（科林•菲尔斯 饰）也表示对她的爱慕之情。布里奇特周旋在两个男人之间，不知如何选择。©豆瓣', '蕾妮·齐薇格', '莎伦·马奎尔', 7.5, 210138, 'tt0243155', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p480932737.jpg', 0.6, 3.7, 34.1, 44.3, 17.4, '0.350819,-0.178982,-0.654346,0.821430,-0.176666,-0.474526,0.886687,-0.126892,-0.401610,-0.292355,-0.072622,0.732795,-0.357446,0.521790,0.225755,0.112507,-0.376273,-0.693423,0.048825,-0.375930,-0.146799,-0.564465,-0.421193,-0.301083,-0.299214,-0.328939,0.437715,-0.250864,0.146034,0.388984,0.370341,0.521232,0.358424,0.616284,-0.007619,0.056503,0.139389,-0.059059,-0.256088,-0.058780,0.198576,-0.057865,-0.217727,0.470907,0.117109,0.447640,0.676721,-0.256319,-0.089041,0.106693,0.319220,0.064455,0.142941,0.072754,0.011073,-0.401235,-0.067917,0.200795,-0.307034,0.015700,0.061460,-0.016685,-0.483556,-0.215431,-0.135515,0.220334,-0.668050,0.357096,-0.299749,-0.120288,0.214803,-0.380206,0.001939,0.283714,0.130183,0.356740,-0.018578,-0.128177,-0.454143,0.208370,0.671628,0.187727,-0.244286,0.375930,-0.613174,-0.356920,0.054907,-0.005148,-0.720102,-0.265313,0.012464,-0.120385,0.231621,0.450664,-0.469421,-0.051711,-0.345312,0.067368,-0.067056,-0.706897,0.043114,-0.427494,-0.193770,-0.606996,-0.586461,-0.108522,-0.034570,-0.430604,0.675394,-0.908227,0.250507,0.334002,0.274339,-0.354464,0.467009,0.349625,0.122513,-0.400040,-0.260350,0.509937,0.078979,-0.260940,0.244451,0.440379,0.202449,0.286042,-0.336235,0.890781', '24756472', '3230121', '1300754', '4058933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304600', '黄飞鸿对黄飞鸿', '喜剧', '一代宗师黄飞鸿（谭咏麟 饰）本想安安静静过日子，不料他的“佛山无影脚”名震佛山后，前来拜访的民众络绎不绝，令喜爱清净的飞鸿不堪烦扰。这日，省城的谢老爷（黄秋生 饰）邀请飞鸿前来一起为灾民筹款。本来喜爱清净的飞鸿不想前往，后在猪肉荣（曾志伟 饰）的劝说下隐瞒身份和一众弟子前往，迎来送往等事宜俱由猪肉荣以飞鸿的身份出面负责。飞鸿在广州邂逅了武艺高强的奇女子双番东（郑裕玲 饰），引发了连场爆笑场面。一次偶然飞鸿得悉了谢老板原来接筹款敛财，兴师问罪时发现谢老板居然找来了双番东女扮男装装作黄飞鸿和自己对质！黄飞鸿对黄飞鸿的好似上演了。©豆瓣', '谭咏麟', '李力持', 6.2, 6383, 'tt0107160', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2351999517.jpg', 2.7, 13.6, 60.4, 17.5, 5.8, '0.184523,-0.011721,-0.693349,0.303425,0.224165,-0.236603,0.041080,0.396292,-0.558299,-0.301397,0.280676,0.721771,-0.244874,-0.036006,0.295884,-0.163991,-0.279581,-0.569131,0.144696,-0.295133,0.051742,-0.240012,0.148523,-0.032642,-0.093164,-0.088403,-0.139066,0.005520,-0.032341,1.017626,0.402022,0.199653,-0.159008,0.492036,-0.146166,0.098884,0.161790,0.347606,-0.675964,0.130433,-0.098762,-0.470038,-0.395888,0.214341,0.030327,0.346852,0.327005,-0.203185,-0.005291,0.038023,-0.090348,-0.098169,0.109330,0.069672,0.192655,0.038289,0.363953,0.034089,-0.348951,0.140436,-0.079183,0.018903,-0.387148,0.153843,0.255092,0.065119,-0.525501,0.362192,0.000645,-0.028622,-0.300260,-0.399548,0.324438,0.345433,0.035684,0.193380,0.170354,0.304914,-0.238679,0.419923,0.681117,0.311538,0.384196,0.061453,0.111042,0.163761,0.474045,-0.273003,-0.244449,0.014625,0.047126,-0.169212,-0.052074,-0.116641,-0.554723,-0.235134,-0.511941,0.075257,0.052222,0.011858,-0.267932,-0.758587,0.060599,-0.365226,0.002959,-0.385380,0.297225,-0.045777,0.618270,-0.738047,-0.062427,0.038384,0.305579,-0.718429,0.562706,0.118464,0.147024,-0.035365,-0.259917,-0.551392,-0.029069,0.548196,0.171938,0.178885,-0.092890,-0.425084,-0.374256,-0.221504', '1451563', '26365262', '1303333', '25723081');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304602', '最终幻想：灵魂深处', '动作', '本片是以电视游戏《最终幻想》作为基础的原创CG动画电影。本片于2001年上映，在电影靠电脑绘画的道路上树立了一个新的里程碑。公元2065年，地球上充满了毁灭和混乱，城市荒芜，人口被大批残杀，整个世界造到外星生命的重创，他们通过独特的方式侵袭地球上的一切生命，少数生存下来的地球人开始反抗这些外星敌人。被毁灭的梦魇时刻缠绕着的天才女科学家罗丝是这场战争中拯救世界的关键人物，但她的计划要冒极大的危险，另一边掌握着高科技军队大权的将军也有一套自己的计划去打击外星敌人，但这个计划同样要对大自然造成更大的伤害，除非罗丝能成功……©豆瓣', '温明娜', '坂口博信', 6.9, 13822, 'tt0173840', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p454093866.jpg', 1.6, 8.9, 44.6, 31.8, 13.2, '-0.056623,0.452802,-0.642476,0.610021,-0.019861,0.377266,0.596155,-0.237099,-0.484883,0.049864,0.341654,0.832179,0.103812,-0.149189,0.052852,-0.081150,-0.265610,-0.480143,-0.280965,0.043128,-0.557199,-0.318166,-0.622990,-0.295561,-0.153649,-0.447262,1.033777,0.321143,-0.683575,-0.016584,-0.097309,0.415730,-0.006000,0.381274,-0.077650,-0.126065,-0.091145,-0.207480,-0.332672,0.315804,-0.249627,-0.177950,-0.098618,0.467488,-0.479946,0.083361,0.840789,-0.397775,-0.084465,-0.416551,0.649221,-0.712129,-0.273353,-0.109164,0.352346,0.095222,-0.068824,0.201119,0.204754,-0.029638,-0.005776,-0.280628,-1.141885,-0.468754,0.052481,-0.015227,-0.429240,0.469998,0.044960,0.014651,-0.162500,-0.220029,0.391390,0.362021,0.533283,0.358299,-0.264020,-0.023171,-0.609275,0.249902,0.554280,-0.227239,-0.540677,0.348503,-0.496157,-0.468329,-0.517192,-0.586287,-0.644972,-0.104820,0.319541,-0.006847,-0.336295,0.499867,-0.898624,0.332476,-0.146221,-0.553886,0.061682,-0.440657,-0.048749,-0.657092,-0.320783,-0.307054,-0.206456,0.182957,0.338947,-0.346876,1.097145,-0.629574,0.194421,0.794599,0.309629,-0.482433,0.670574,-0.009338,0.102848,-0.116393,-0.024860,0.290783,-0.222125,0.415034,-0.153480,0.155834,0.139706,0.065873,-0.389596,0.910180', '27602116', '26667010', '26759820', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304603', '小飞象', '动画', '丹波是马戏团的一只小象，因为样貌与众不同——它长着蓝色的眼睛和一双大得出奇的耳朵——而遭到大家都取笑。有一天，一个淘气的男孩子甚至作弄了丹波，象妈妈十分生气，就教训了他一顿，因此被马戏团老板关进了笼子。为了在马戏团立足，救出妈妈，丹波必须马上学会一门拿手绝活。四出学艺的 它却又四处碰壁，心灰意冷之际全靠好朋友老鼠帝莫给了它鼓励和温暖。一次意外，丹波掉进了一个大酒桶内被灌得酩酊大醉，却因此意外发现了自己的拿手绝活。©豆瓣', '詹姆斯·巴斯凯特', '宾·沙普斯坦', 8.3, 25731, 'tt0033563', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1833107201.jpg', 0.2, 0.8, 16.1, 47.5, 35.4, '0.104189,0.077822,-0.697203,0.263746,-0.243938,-0.161368,0.722559,0.189172,-0.240398,-0.115587,0.123016,0.637272,-0.355119,0.254594,-0.134170,0.207866,0.148701,-0.528026,0.035500,-0.049976,-0.062289,-0.070808,-0.264485,-0.046654,-0.057477,-0.159544,0.113620,-0.132761,-0.229253,0.383051,0.028906,-0.172596,0.316373,0.304135,-0.076650,0.085879,-0.073595,-0.063039,0.420946,0.101310,0.124992,-0.222611,-0.360477,0.099952,-0.012542,0.316097,0.602289,-0.324638,-0.567107,-0.276436,0.025723,-0.268340,-0.246263,0.315574,0.409004,0.025216,0.309312,-0.303866,-0.028824,0.214433,0.316904,-0.098882,-0.513027,0.003670,0.176369,-0.144021,-0.752519,0.515540,0.060601,-0.063819,0.106966,-0.573426,0.186136,0.000396,0.312503,0.520972,-0.352028,0.457632,-0.639399,-0.038451,0.432294,-0.183907,0.000091,0.346331,-0.110236,-0.293340,0.179927,-0.330155,-0.316859,0.127917,0.666363,-0.192667,-0.509450,0.098035,-0.382602,0.016855,-0.346270,-0.180423,-0.305992,-0.368747,-0.142317,-0.132704,0.233628,-0.235646,-0.273392,0.217058,-0.013832,-0.049788,0.699478,-0.675375,0.247813,0.707853,0.045571,-0.016956,0.433307,0.254279,0.005680,0.185390,-0.097906,-0.222245,0.352309,0.366162,0.551452,0.532950,-0.035485,-0.184418,-0.497975,0.323492', '1947080', '21619567', '1464907', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304607', '人面兽心', '喜剧', '胆小怕事、身体羸弱的马文·曼格（罗伯·施奈德 Rob Schneider 饰）却一心想成为父亲那样勇猛威武的警察，不过由于性格原因，他充其量只能在警察局证物科担当管理员。生活中他得不到任何尊重，同侪嘲笑，小孩戏弄，甚至连邻居家的狗也欺负他。某天，独自在警察局值班的马文接到报警电话，可是所有警察都去球场尽情玩乐。万般无奈之下，马文独自驾车出警，却遭遇一场严重的车祸，命悬一线。危难之时，他被一个神秘之人搭救，醒来时发现自己毫发无损。然而此后马文却显露出许多动物特有的习性，原来神秘人为其移植了动物器官。马文的生活由此发生巨大转变……©豆瓣', '罗伯·施奈德', '卢克·格林菲德', 6.4, 12751, 'tt0255798', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1502695280.jpg', 2.1, 10.4, 57.2, 23.8, 6.5, '0.122748,0.060421,-0.721030,0.308100,-0.375230,-0.023438,0.787275,0.144822,-0.542777,-0.407189,0.191972,0.694863,-0.058079,0.232313,0.047301,-0.278233,-0.033448,-0.345415,-0.025954,0.219550,-0.210287,-0.175006,-0.273459,-0.256001,0.020622,-0.151201,0.287453,0.138369,-0.249619,0.337316,0.105507,0.329517,-0.241435,0.615065,-0.024328,-0.048013,0.108042,-0.027492,0.044118,-0.180678,0.032247,-0.175982,-0.123159,0.318078,-0.107638,0.401405,0.436888,-0.184750,-0.554525,-0.366843,0.507482,-0.172378,-0.079239,0.014241,0.404698,-0.086796,0.108831,0.017739,0.017225,0.044849,0.050953,0.253680,-0.555771,0.066764,-0.243680,0.092724,-0.280286,0.162790,0.025227,0.169428,-0.058294,-0.341056,0.089240,0.022091,-0.022226,0.180953,-0.084019,-0.024743,-0.422456,-0.037570,0.649347,-0.076165,-0.474645,0.182094,-0.263936,-0.390073,0.287961,-0.374476,-0.482966,0.077435,0.184475,-0.042052,-0.364771,-0.010793,-0.219835,0.033567,-0.329189,0.078384,-0.348002,-0.254038,-0.240748,-0.464790,0.133558,-0.145370,-0.486818,0.181873,0.081022,-0.159907,0.393978,-0.649560,0.198822,0.541529,0.004946,-0.555378,0.366972,-0.064626,0.056260,-0.021652,-0.136580,0.550735,0.353231,0.299036,-0.022854,0.106140,-0.157066,-0.054601,-0.234360,0.257201', '1292064', '1309116', '1292217', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304608', '剑鱼行动', '动作', '间谍加布利尔（约翰•特拉沃塔 John Travolta）在多年特工生涯中，获知政府多年非法收敛了一笔公款。而加布利尔若想实现自己心中的梦想，钱是最关键的因素。正因如此，机智狡猾的加布利尔决定向这笔赃款下手。要想计划能顺利进行，加布利尔需要一名顶尖的电脑黑客。斯坦利（休•杰克曼 Hugh Jackman）正是地球上最顶级的黑客之一，多年前他就把FBI引以为豪的安全系统搞得天翻地覆，亦因此的引来牢狱之灾，妻子带着女儿远走他乡。出狱后一直被禁止使用电脑和其他电子产品。加布利尔派他的女搭档金吉尔（哈莉•贝瑞 Halle Berry）游说斯坦利出山，承诺成功后帮斯坦利取回女儿的抚养权并安排其远走高飞享受新生活。经不住诱惑，斯坦利再度出山。然而，事情并没有像预想中顺利……©豆瓣', '约翰·特拉沃尔塔', '多米尼克·塞纳', 7.5, 66273, 'tt0244244', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p847809863.jpg', 0.4, 2.8, 32.6, 48.6, 15.7, '-0.019686,0.216084,-0.528293,0.642959,-0.136162,-0.306322,0.314699,-0.155515,-0.565385,-0.162321,0.230081,0.766931,0.302790,0.210239,0.256346,0.220437,-0.601049,-0.387711,0.121001,-0.149908,-0.141795,-0.613179,-0.345497,-0.104181,-0.379806,-0.514554,0.416023,-0.148099,0.127107,0.168544,0.224235,0.408179,0.044803,0.161137,0.209391,-0.236679,0.350046,-0.148648,-0.567735,0.409640,0.108042,0.114837,-0.165871,0.190870,0.216884,0.227112,0.194817,-0.142440,0.068952,-0.166387,0.339116,-0.384314,0.170818,0.089055,0.049464,-0.030029,0.270141,0.451282,-0.381255,0.125884,0.050865,-0.178844,-0.821654,-0.129191,0.143711,-0.103211,-0.650483,0.111716,-0.517209,0.031478,0.010804,-0.256855,0.025137,0.454463,0.327980,0.138517,-0.123596,0.298192,-0.193812,0.156930,0.204354,-0.380877,-0.439366,0.150049,0.256997,-0.318040,0.184844,-0.518935,-0.398372,-0.024856,0.386748,0.128797,-0.159054,0.404545,-0.274277,-0.084825,-0.601580,-0.361175,0.162047,-0.152661,-0.093267,-0.566954,-0.101744,-0.070675,-0.256162,0.052529,0.069456,-0.347351,0.535085,-0.599033,0.123296,0.802633,0.278664,-0.401916,0.268263,0.023347,0.305927,-0.309140,-0.209465,0.185277,0.125630,0.430713,0.121803,0.101799,0.294099,-0.421987,-0.054793,0.578756', '1793491', '1307442', '3006783', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304609', '东宫西宫', '剧情', '北京某公园是同性恋晚上幽会的场所，该公园附近的派出所民警小史（胡军）值夜班值到无聊时，会到公园里抓一两个同性恋来审一审，在他们交待自己的种种“活动”时，他会打骂一番以消闲解闷。某晚又去抓人时，欲拒还迎的阿兰（司汗）被他铐回值班室。审问过程中，小史的言行不乏对阿兰的歧视和侮辱，但阿兰丝毫不为自己是同性恋难为情，反不动声色地讲起过往经历，并用死囚与刽子手的故事表达他对小史的爱恋，慢慢地，小史发现他的心中原来也藏有一座断背山。©豆瓣', '司汗', '张元', 6.8, 32513, 'tt0119007', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p944507896.jpg', 1.9, 9.6, 45.9, 32.3, 10.2, '0.510527,-0.130218,-0.535127,0.312009,-0.048959,-0.018931,0.817472,-0.053341,-0.552324,-0.096131,0.257066,0.517899,-0.282267,0.391344,0.277186,0.163279,-0.499434,-0.622285,-0.032875,0.022815,-0.299002,-0.447264,-0.074582,-0.280687,-0.117374,0.170471,-0.127232,-0.099668,-0.459478,0.275236,0.175729,0.318454,-0.091917,0.545913,-0.118056,0.082123,0.086613,0.090834,0.030467,0.116127,0.163759,-0.318928,-0.536281,-0.093585,-0.059283,0.417265,0.676449,0.064244,-0.314825,-0.047982,0.374642,-0.131478,-0.003738,0.210092,0.183172,0.020248,0.100845,0.316416,-0.193154,0.249191,0.142127,-0.028327,-0.304498,0.054484,-0.072913,0.017099,-0.577811,0.302367,0.085763,-0.023822,0.151975,-0.254804,0.170839,0.187662,0.096206,0.449645,0.079483,-0.244808,-0.387030,0.243933,0.402593,-0.000081,0.161855,0.084291,-0.180248,-0.517002,0.171341,0.212301,-0.401298,-0.322013,-0.033248,-0.149110,-0.384828,0.021678,-0.475965,-0.040032,-0.235829,0.029915,-0.058551,-0.352246,-0.139290,-0.542319,-0.010661,-0.331505,-0.314536,-0.139686,0.300479,0.059323,0.188643,-0.651927,0.238216,0.673478,0.193298,-0.408840,0.655328,0.370179,-0.233206,-0.037658,-0.168936,-0.011165,0.132423,0.541843,0.179704,0.481963,0.084197,-0.167492,-0.394545,0.389851', '1309172', '1908318', '21348112', '1298197');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304613', '吉娅', '剧情', '女孩吉亚（安吉丽娜•朱莉 Angelina Jolie 饰）自小就在父母的虐待中长大，不过不幸并没有一直伴随她，在她18岁那年，吉亚时来运转了。18岁那年，吉亚被模特经纪选中，搬到纽约成了一位职业模特。在经纪人的努力运作下，吉亚由一名不见经传的模特，渐渐成长为时装界的代表。吉亚的特殊风格，风靡了世界。然而，成名后的吉亚却感到无比空虚，无处发泄，渐渐的，她开始沉溺于毒品，事业也跟着一落千丈。吉亚最后究竟命运如何？©豆瓣', '安吉丽娜·朱莉', '迈克尔·克里斯托弗', 7.9, 20680, 'tt0123865', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1917873110.jpg', 0.3, 2.1, 24.5, 46.5, 26.6, '0.062416,0.080470,-0.656374,0.337302,-0.213046,-0.344195,0.620912,0.186365,-0.871386,-0.175468,0.224658,0.945442,-0.154910,0.334028,0.537179,0.221450,-0.266064,-0.609410,0.200709,-0.329058,-0.172019,-0.218456,-0.495339,0.182808,-0.180038,-0.458159,0.705242,0.033511,-0.020508,0.535004,0.173158,0.122618,0.228938,0.282926,-0.090874,0.120294,0.508787,0.057374,0.096682,0.208484,-0.144820,-0.324322,-0.151082,0.007588,-0.142843,0.424024,0.391291,-0.239908,0.365025,-0.385281,0.380617,0.080326,-0.302305,0.203485,0.123516,-0.156741,0.193438,0.066442,-0.370421,0.134928,-0.021486,-0.047678,-0.637252,0.035652,0.363423,0.092039,-0.806289,0.444037,-0.251935,-0.242658,0.158268,-0.424458,-0.480696,0.384209,0.425515,0.608030,-0.124898,0.165387,-0.536691,0.219329,0.655736,0.090536,-0.522130,0.410846,-0.268122,-0.259147,-0.079907,-0.472860,-0.431090,-0.240809,0.268183,0.121369,-0.229167,0.437849,-0.479699,0.036413,-0.099425,-0.266327,0.036734,-0.475823,-0.214612,-0.392262,-0.351862,-0.396233,-0.068277,-0.268324,0.048214,-0.263874,0.808397,-0.974891,0.388218,0.562213,0.014078,-0.469032,0.332320,0.245917,0.224542,-0.186045,-0.054809,0.586859,-0.098178,0.328722,0.043671,0.436382,-0.246047,-0.310591,-0.244927,0.648516', '35030151', '25721544', '1783461', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304624', '旺角卡门', '剧情', '香港九龙区旺角混混阿杰（刘德华）做事利落重情义，颇有老大风范，为了照顾做事冲动又好面子的小弟乌蝇（张学友），他不停地在各种大小麻烦中周旋，甚至不惜为乌蝇与黑道狠角色（万梓良）结仇。阿杰表妹阿娥（张曼玉）前来旺角看病暂住他家，两人慢慢互生情愫，但因为担心自己的身份最终会给阿娥带来伤害，阿杰选择了将心事埋藏。待阿杰明白真情抑压不住想对命运做番抵抗时，乌蝇却再次因好面子面临生命危险，于是一道友情与爱情必选其一的难题重又摆在阿杰面前。©豆瓣', '刘德华', '王家卫', 7.8, 198128, 'tt0096461', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2259568798.jpg', 0.2, 1.7, 26.2, 49.9, 21.9, '-0.085768,0.095172,-0.391978,0.355702,0.026482,-0.058701,0.454841,0.186636,-0.398791,-0.162257,0.230230,0.644015,0.206586,0.048853,0.061200,-0.407426,-0.100218,-0.645402,0.257140,-0.019270,-0.017778,-0.420413,-0.318934,-0.182651,-0.323768,0.155426,0.165027,-0.045629,-0.178254,0.349371,0.339865,0.259050,-0.089710,0.327997,-0.048868,-0.098093,-0.169947,-0.056695,-0.408149,-0.060822,0.277091,-0.175186,-0.043111,0.234149,0.248310,0.382050,0.442479,0.134088,-0.397659,-0.110599,0.241543,-0.087816,0.217867,0.121290,-0.077486,0.003010,0.429881,0.108676,-0.146117,-0.182651,0.189248,0.025209,-0.538206,-0.011551,0.201794,-0.008607,-0.628266,0.246296,-0.001965,-0.153067,-0.128611,-0.154776,0.079027,0.147650,0.578714,0.108648,-0.335484,0.093411,0.061891,-0.168866,0.650246,0.023224,0.269582,0.189698,-0.115496,-0.053622,0.175801,-0.288411,-0.320034,-0.216380,0.172624,0.059917,-0.066402,0.209447,-0.241906,-0.249110,-0.179253,0.268156,-0.162019,-0.546456,0.153306,0.082193,-0.246975,-0.129947,-0.207800,0.097691,0.201173,-0.022070,0.715599,-0.549857,0.127341,0.638553,0.413719,-0.828182,0.523475,0.429864,0.026637,-0.178861,-0.017194,0.028042,-0.131905,-0.170863,0.211321,0.010416,-0.150062,-0.194989,0.015405,-0.120379', '26678784', '1877596', '1421278', '1309033');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304641', '红磨坊', '剧情', '红磨坊日日歌舞升平。夜总会，康康舞，这是个男人们花天酒地的享乐国度。然而，这儿的爱情，却无比纯净动人。克里斯蒂安（伊万·麦戈雷格 Ewan McGregor 饰）是年轻的钢琴诗人，拥有美丽的歌喉。不顾父亲的反对，他来到了蒙马达小镇，这个“追求享乐”的地方。在这儿，他与莎婷（妮可·基德曼 Nicole Kidman 饰）意外 的相遇了。莎婷是红磨坊的当家花旦，被誉为“璀璨钻石”，受到很多人的青睐。然而她并不满足于卖唱的生活，想要借助公爵的力量，成为一名真正的巨星。克里斯蒂安的到来，打乱了她结识公爵的计划，却闯入了她的内心。英俊的少年用歌声，向莎婷诉说着“自由”、“美”、“真理”，并给她带来了她从未感受过的“爱”。莎婷找到了自己的梦想，渴望同她心爱的男人一同完成。然而，公爵的阻挠却让一切变得艰难。爱情，要怎样，与命运抗衡。©豆瓣', '妮可·基德曼', '巴兹·鲁赫曼', 7.9, 130303, 'tt0203009', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2454640615.jpg', 0.4, 2.5, 24.5, 47.8, 24.8, '0.145877,0.330478,-0.722865,0.750822,-0.429732,-0.132737,1.083972,0.155476,-0.346079,-0.195533,0.144998,0.785288,-0.110062,0.265308,0.284514,0.305042,-0.023535,-0.655234,0.092333,0.123596,0.133238,-0.247026,-0.367305,-0.194816,-0.165102,-0.462632,0.828856,0.305090,-0.239015,0.296832,0.400988,0.159665,0.084870,0.576571,-0.437611,-0.137188,0.176715,0.248201,-0.275090,0.178164,-0.166010,-0.301066,-0.145075,0.466527,-0.296303,0.097277,0.438184,-0.330283,-0.103145,-0.062027,0.399532,-0.228523,0.064265,0.125302,-0.033163,-0.155163,-0.041945,0.119465,-0.099565,-0.120950,0.148114,-0.101220,-0.935145,-0.003840,0.327541,0.194770,-0.504377,0.464022,-0.172618,-0.244361,0.061757,-0.073978,0.264457,0.050877,0.127867,0.389604,-0.109730,0.112849,-0.628229,0.293480,0.887499,0.037109,-0.456570,0.486160,-0.688938,-0.437521,-0.015617,-0.472952,-0.702608,-0.083079,0.027876,0.220800,-0.045784,0.208791,-0.536781,0.017669,-0.218850,-0.060574,0.108295,-0.690339,-0.151918,-0.571611,-0.261253,-0.639387,-0.326604,-0.065074,0.071335,-0.381609,0.861424,-0.951915,0.118448,0.715887,0.316285,-0.522721,0.864735,0.266948,-0.057596,-0.116010,-0.194860,0.567435,-0.025463,0.040081,-0.144512,0.333927,-0.083279,0.185663,-0.548001,0.836404', '35158375', '3230462', '247