INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304642', '尖峰时刻2', '喜剧', '李督察（成龙 饰）和从洛杉矶赶来香港度假的老搭档詹姆斯•卡特（克里斯•塔克 Chris Tucker 饰）真是一刻不得闲，因美国领事馆遭到炸弹袭击，两名工作人员身亡，李督察只得带上卡特去拜访三合会头目、也是自己父亲的昔日搭档邓力奇（尊龙 饰），邓力奇的手下胡莉（章子怡 饰）等人先后出面袭击李与卡特，不久李被美国方面禁止参与此案，而香港警局也遭到了炸弹袭击。失散的李和卡特分别来到了邓力奇的游艇，得知三合会出现了内讧，话音刚落，胡莉将邓力奇射杀在海中……暂时失去线索的二人奔赴洛杉矶，在当地大亨荣士勋家中发现了胡莉的踪迹和美国的卧底特工，原来邓、胡等人卷入了一场巨额假钞案，李与卡特决定拿回胡莉手中的印版……©豆瓣', '成龙', '布莱特·拉特纳', 7, 74324, 'tt0266915', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1513464612.jpg', 0.5, 4.4, 48.5, 35.4, 11.1, '0.218959,-0.204001,-0.838275,0.391049,0.085910,-0.431111,0.511279,0.227815,-0.469578,-0.425396,0.032934,0.691513,-0.276457,0.202316,0.409257,-0.232783,-0.480742,-0.706248,-0.097057,-0.106890,-0.513478,-0.494279,-0.066520,-0.522284,-0.000815,-0.021263,0.254787,0.218851,-0.209347,0.692604,0.412912,0.608733,-0.288143,0.640525,0.007477,0.360626,0.366161,-0.077111,-0.201290,0.321463,0.130537,-0.454228,0.059628,0.204550,0.462003,0.445349,0.607377,-0.048840,0.147538,-0.211003,-0.169617,-0.386432,0.055881,-0.103622,0.618979,0.046500,-0.043558,-0.019529,-0.437700,-0.054741,0.000941,-0.047728,-0.267742,0.182711,0.070256,0.118833,-0.475968,-0.039700,-0.433036,0.264668,-0.071466,-0.349141,0.265395,0.427501,0.176821,0.239293,0.193042,0.236535,-0.511891,0.127248,0.747225,-0.159755,-0.033024,-0.232050,0.239517,-0.275585,-0.144458,0.132862,0.105105,0.009570,0.778699,-0.284474,0.308776,-0.029879,-0.423451,-0.299915,-0.426341,-0.204791,-0.192708,-0.062897,-0.040617,-1.013195,0.163294,-0.173021,-0.108828,0.187696,0.001017,0.105409,0.263739,-0.464538,0.176451,0.260617,0.196587,-0.621944,0.426007,-0.065424,0.260943,-0.282725,0.033056,0.069898,0.764078,0.298185,0.399269,-0.055231,-0.229763,-0.333479,0.066628,-0.146494', '3147969', '21349734', '3871833', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304643', '侏罗纪公园3', '动作', '继索纳岛恐龙逃往事件过去已有八年，艾伦•格兰特博士（山姆•尼尔 Sam Neill 饰）无论如何也不愿再返回那个鬼地方。虽然发下重誓，但现状不得不让他收回誓言。他的一项史前动物研究陷入资金紧张的窘境。而这时，富有的商人保罗•科比（William H. Macy 饰）及其夫人阿曼达（Téa Leoni 饰）找到艾伦，邀请他作为向导带他们乘飞机前往索纳岛观光。一方面酬劳颇丰，一方面又得知不用着陆小岛，好了伤疤忘了疼的艾伦接受了他们的邀请。然而事情却朝相反的方向发展，他们的飞机最终迫降小岛。至此他才得知，原来科比夫妇来此的目的竟是为了寻找失踪的儿子。与此同时他还发现，经过八年的自然进化，恐龙中最聪明的速龙竟然拥有了自己赖以交流的语言。这一次他的对手不仅凶恶，而且更为狡猾……©豆瓣', '山姆·尼尔', '乔·庄斯顿', 7.3, 112641, 'tt0163025', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2249341027.jpg', 0.5, 3.8, 39.4, 41.1, 15.2, '0.130836,-0.132130,-0.616094,0.668662,-0.212451,-0.444811,0.403390,-0.165969,-0.566451,-0.407393,0.180631,0.545381,0.051403,-0.062079,0.149501,0.150422,-0.235118,-0.150655,0.256433,-0.267518,-0.222209,-0.501312,-0.360580,-0.364521,0.055540,-0.124726,0.560857,0.120674,-0.084050,0.380585,0.142705,0.282099,0.033135,0.533557,0.036666,0.026265,0.047607,0.152568,-0.158158,0.248077,0.187339,-0.237521,-0.130466,0.344654,-0.049040,0.460970,0.521390,-0.335785,-0.147250,-0.183908,0.136493,-0.373643,0.048536,0.182260,0.292609,-0.114487,0.187599,0.245871,-0.201911,-0.033745,-0.014685,0.110184,-0.485055,0.117300,-0.016304,-0.012476,-0.460113,0.163134,-0.171487,0.022480,-0.084809,-0.513951,0.091454,0.503968,0.226115,0.182162,-0.215025,-0.042293,-0.419678,-0.117262,0.577087,0.050096,-0.061471,0.067679,-0.113204,-0.696850,0.076145,-0.248751,-0.158583,0.133016,0.287576,0.206752,-0.251990,0.194417,-0.501962,-0.127495,-0.382217,-0.266290,-0.001434,-0.346623,-0.002653,-0.624379,0.123411,-0.277369,-0.216290,-0.111364,-0.000878,-0.253695,0.438326,-0.613592,0.014117,0.530324,0.280437,-0.568920,0.480885,-0.093856,0.019163,-0.425156,-0.107451,0.395691,0.036350,0.317315,0.106577,-0.009435,0.082877,-0.414581,-0.321583,0.430717', '34461680', '1420088', '1301022', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304646', '圣战骑士', '动作', '小伙子威廉（希思•莱吉尔Heath Ledger 饰）虽然出身于法国的平民家庭，但从小就梦想当一名骑士，从儿时起就苦练剑术和马术。然而当时的社会只有贵族才有资格当骑士，于是威廉只当了一名贵族骑士的侍从。 在一次马上长枪比武中，威廉的主人在场间休息时突然意外死去。威廉灵机一个，穿上了主人的铠甲，骑上他的坐骑，冒名顶替并赢得了这场比赛。捧着胜利的奖杯，威廉决定继续冒充自己的主人参加在伦敦举行的世界骑士锦标赛，通过赢得比赛使自己成为一名真正的骑士。威廉启程了！©豆瓣', '希斯·莱杰', '布莱恩·海尔格兰德', 7.4, 8587, 'tt0183790', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189574418.jpg', 0.6, 3.9, 36.7, 42.9, 15.9, '0.004186,0.220657,-0.419751,0.582890,-0.292505,-0.649007,0.426149,-0.030835,-0.174743,-0.427237,0.781184,1.071042,0.026308,0.298473,0.788908,-0.263451,-0.300897,-0.766582,-0.040945,-0.185517,-0.362887,-0.229504,-0.072914,-0.157037,-0.150879,-0.610128,0.949159,-0.125783,-0.233016,0.445676,0.420108,-0.031714,0.287632,0.340339,-0.238664,-0.451935,0.451012,0.128267,-0.260838,0.410606,-0.237292,-0.132291,-0.336326,0.131413,0.110532,0.023555,0.654570,-0.824179,0.240953,-0.291819,0.231482,-0.003282,0.027608,-0.022624,0.257804,0.162954,-0.061635,0.059643,0.414842,0.229400,-0.087418,-0.326628,-0.495640,0.085491,-0.058801,0.077020,-0.710555,0.650511,-0.177628,-0.130512,0.005430,-0.113734,0.122005,0.139599,0.135919,0.130009,-0.302522,0.128893,-0.564095,0.340995,0.701922,0.115905,-0.342986,0.032695,-0.118974,-0.774803,0.106352,-0.193701,-0.440601,-0.095683,0.394217,0.026492,0.010969,-0.022131,-0.539020,0.115774,-0.271321,-0.326698,0.069087,-0.249327,0.080325,-0.449373,0.266435,-0.030159,-0.142453,-0.125452,0.144060,-0.052402,0.903859,-0.947385,0.349679,0.420902,0.105360,-0.148682,0.471483,0.017295,0.391935,-0.101692,-0.291818,0.133162,0.095823,0.331992,-0.026923,0.435779,-0.077634,-0.318542,-0.008630,0.827195', '1870681', '26593587', '26615753', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304648', '自梳', '剧情', '一段穿越50年时空的真情。两个女人的苦难与爱恨，让人心碎却也心醉。现代女性阿慧（李绮虹饰）从美国学习建筑业归来，在香港与大陆间经营事业，是个新时代的女强人。其男友（赵文煊饰）也是其下属，二人感情渐淡，男友移情别恋。阿慧伤心却也无奈。阿慧父亲委托阿慧陪其幼年时的奶妈欢姑（归亚蕾饰）回乡探旧友，两人一见面就针锋相对，相处不太愉快。随着旅程的进行，二人矛盾不断，却也渐渐磨合。欢姑在开导感情脆弱的阿慧时，道出了一段隐藏在心底的往事。 40年代的广东顺德，女子还生活在男权制的枷锁下。年轻的意欢（杨采妮饰）被父亲卖于地主，她宁愿做自梳女，宁死不从。被途经路过的杏花楼妓女玉环（刘嘉玲饰）救下。玉环嫁给了当地织布厂厂主陈耀宗（董玮饰）做了八姨太，与其他太太明争暗斗不断，却将意欢认为知己，二人无话不谈。意欢与青梅竹马的恋人（钱嘉乐饰）两情相悦却难成眷属。玉环被丈夫出卖，成为军阀谈生意的筹码，愤怒之下，她离开了陈家。意欢对玉环不离不弃，令她十分感动，感情渐渐超越了友谊。而此时意欢与恋人在“买门槛”之夜出轨，玉环又担心又生气，终于忍不住告诉了意欢自己心底的秘密。有情人能否终成眷属？两个女人之间到底有什么秘密？阿慧能否度过情关？而欢姑苦苦寻找了50年的人又是谁？ 《自梳》是大导演张之亮的名作，朴实无华却感人肺腑，人性刻画深刻，对时代的敏感度也可见一二，是国产女同电影的最佳之作。', '刘嘉玲', '张之亮', 8.6, 51729, 'tt0133028', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1072049466.jpg', 0.1, 0.8, 13, 43.2, 42.8, '0.010494,0.002164,-0.527482,0.403096,0.080011,-0.334621,0.748113,-0.007743,-0.586661,-0.015904,0.155347,0.651975,-0.264305,0.223313,0.069012,0.010568,-0.003069,-0.748980,0.110473,-0.174582,-0.076788,-0.316375,-0.237408,-0.009118,-0.294784,-0.206681,0.527681,0.043918,-0.087173,0.283988,0.305759,0.085871,-0.305381,0.409238,-0.293765,-0.011237,0.022877,0.239529,-0.499263,-0.193203,0.022016,-0.291329,-0.231314,-0.046815,-0.127384,0.276821,0.563397,-0.164408,-0.065402,-0.020321,0.258998,-0.025039,-0.188927,0.090297,0.028754,-0.031042,0.243003,0.390327,-0.195487,-0.094478,0.040640,0.019118,-0.500230,0.225066,0.188954,0.102742,-0.572030,0.417927,-0.140146,-0.187477,0.001881,-0.274209,0.253797,0.266019,0.395101,0.396049,-0.378827,0.065403,-0.301233,0.362739,0.664045,0.261684,-0.119331,0.475593,-0.241629,-0.357910,0.038815,-0.098407,-0.537333,-0.092696,0.147716,0.072893,-0.138375,0.369081,-0.527588,0.036842,-0.142503,0.172302,0.195475,-0.606560,0.102637,-0.199447,-0.477583,-0.496902,-0.379054,0.015154,0.370280,-0.203087,0.763961,-0.663292,0.017629,0.364052,0.332856,-0.626810,0.704148,0.286776,0.099745,-0.340195,0.022803,0.191683,-0.286512,-0.045340,0.080403,0.336489,-0.089225,0.093384,-0.291155,0.311661', '30162520', '1418613', '1296569', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304665', 'X圣治', '悬疑', '东京连续发生数起离奇命案，所有尸体上皆刻上“X”符号，而在场的嫌犯都不记得自己所为，这令警察们大为困惑。刑警高部（役所广司饰）断定有人利用催眠术行凶，一名在海岸徘徊的半失忆青年间宫（荻原圣人饰）成为怀疑重点，与该青年接触过的教师、警察和女医生都这样杀了人。随后高部着手对间宫进行审讯，却总被他的言语打乱，调查毫无进展，再加上妻子因精神疾病住院，高部的情绪变得极为糟糕。高部的朋友心理学家佐久间劝他不要再和间宫接触，自己却被无意识使用催眠术的间宫逐渐操控。不久后，间宫从精神病院逃走，而佐久间被发现自杀身亡。高部来到以前间宫提过的一间废弃小屋中，遇到了间宫并将他杀死，对方满足地死去。然而一切并没有就此结束……©豆瓣', '役所广司', '黑泽清', 8.2, 13830, 'tt0123948', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2609671079.jpg', 0.8, 2.3, 17.4, 46.3, 33.2, '0.544806,-0.089273,-0.476840,0.343575,0.023745,-0.194099,0.947171,-0.181864,-0.559455,-0.663599,0.121596,0.411931,-0.335813,0.222422,0.067082,-0.232703,-0.098962,-0.606197,-0.124537,-0.020493,-0.352351,-0.381833,0.080988,-0.139406,-0.377070,-0.210708,0.696077,0.175760,-0.351427,0.196101,0.047445,0.231865,-0.097802,0.580554,0.128143,-0.038649,0.083378,-0.088107,0.006420,0.207051,0.076455,-0.271134,0.017994,0.274677,-0.060134,0.314682,0.635679,-0.150297,-0.412345,-0.049165,0.242330,-0.092353,-0.000325,0.367470,0.504498,0.269158,-0.045653,0.440501,-0.285731,-0.092954,-0.105574,0.163699,-0.349207,0.095650,0.035828,0.162376,-0.321228,-0.113654,-0.100874,0.088302,0.090885,-0.172950,0.167674,0.377777,0.278523,0.096787,-0.342749,-0.194141,-0.283130,0.206182,0.652424,-0.142190,-0.239099,0.120783,0.052531,-0.559396,0.106337,0.004266,-0.029618,0.093439,-0.184667,0.191586,-0.202756,0.181506,-0.046947,-0.200166,-0.409449,-0.067332,-0.129254,-0.354317,-0.094595,-0.576459,-0.060439,-0.041789,-0.602390,0.091542,0.088941,-0.164588,0.150674,-0.981678,0.273431,0.336579,0.326098,-0.209126,0.330970,-0.090550,-0.119467,-0.100277,-0.278826,0.347034,0.353863,0.523268,0.137505,0.361488,-0.120998,-0.137500,-0.324989,-0.000875', '3263169', '1308755', '27617348', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304676', '香港有个荷里活', '剧情', '这里可能是香港最后的一条穷街陋巷了，在特区政府的城建计划里，这里也很快会被高楼大厦所覆盖。故事就发生在这里--大磡村。村民朱家父子开着一个烧腊店，过着简单的生活。但是一名大陆女子的出现，扰乱了他们原本平静的生活。这个活泼俏丽的女子名叫东东（周迅饰），她就住在朱家的后面，一个号称“香港好莱坞”的豪华公寓里,她是，不仅与朱家天真无邪的小儿子阿细结成忘年之交，也勾起爸爸（陈英明饰）与哥哥阿明（何世文饰）禁锢已久的男性情欲，三父子平淡的感情生活掀起了巨浪。令朱家父子更想不到的是，因为这位女子带来的风波，再加上特区政府的重建计划，他们要无奈地被迫离开这个生活了半个世纪的家——大磡村......©豆瓣', '周迅', '陈果', 7.3, 23614, 'tt0290654', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2185907486.jpg', 1.1, 4.2, 36.5, 45.1, 13.2, '0.309289,0.054849,-0.698203,0.750624,-0.165455,-0.162038,0.869003,0.181811,-0.614301,-0.202109,0.012976,0.823886,-0.081623,0.593033,0.114452,0.118043,-0.090118,-0.433438,-0.290405,-0.189756,-0.058208,-0.231789,-0.235634,-0.205784,0.025107,-0.014555,0.346185,0.351695,-0.162997,0.330995,0.392912,0.102057,-0.342476,0.336597,-0.320749,0.120223,-0.086988,0.233813,-0.205601,0.131743,-0.171147,-0.227730,0.066065,0.187968,0.051440,0.242826,0.470561,0.000597,-0.356965,-0.094024,0.185318,-0.086455,-0.137853,0.132668,0.663907,-0.276825,0.278052,0.252581,-0.317508,-0.313038,-0.011009,-0.274683,-0.648785,0.174263,0.134858,0.019611,-0.659361,0.389315,0.143108,-0.249930,-0.193860,-0.224597,0.432614,0.513286,0.422818,0.267778,-0.153601,0.192213,-0.534022,0.195019,0.759174,0.005792,-0.298838,0.142732,-0.387215,-0.252377,-0.186333,-0.286440,-0.520238,-0.082390,0.256978,-0.019113,-0.103252,0.162898,-0.481857,0.107372,-0.217005,-0.133696,0.053271,-0.231860,-0.167052,-0.436257,-0.026299,-0.544349,-0.312553,0.240661,0.015869,-0.143921,0.674084,-0.631147,0.195490,0.226053,0.557203,-0.477638,0.686719,0.001874,0.244997,0.026625,-0.116451,0.061650,-0.114152,0.305224,0.230102,0.501726,-0.325703,-0.184903,-0.253487,0.549800', '3055049', '30162520', '25721544', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304677', '千王之王2000', '喜剧', '梁宽(张家辉饰）乃一低级警务人员，多次担任卧底小角色。郁郁不得志之时，长官忽派他调查大老千法拉利（王晶饰），宽遂找到自信。一日宽陪女友pizza（关秀媚饰）参加姐姐（吴君如饰）为姐夫大老千黄师虎（周星驰饰）短暂出狱期间举办的宴会。宽在宴会上态度嚣张，终被黄师虎整蛊，于是怀恨在心。宽卧底于法拉利周围，在沙滩上偶遇美女初恋（林熙蕾饰），被其美色所迷。宽自认得到法拉利信任，不料，还没找到犯罪证据，反而先落入初恋的美人计陷阱中，差点丢了工作。Pizza不计前嫌，与宽商量找姐夫帮忙，却不料姐夫早已为宽设下了无数难题......©豆瓣', '周星驰', '王晶', 6.9, 112260, 'tt0212864', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2355026833.jpg', 1.2, 7.5, 47.2, 31.4, 12.7, '-0.100246,0.098330,-0.443398,0.425923,-0.111011,-0.238089,0.213815,0.160010,-0.365555,-0.208400,0.249152,0.331611,-0.302159,-0.129540,0.025378,-0.151998,-0.102909,-0.543495,0.044341,0.008985,-0.162858,-0.536936,-0.258777,0.090437,0.011273,-0.028451,0.105100,0.050260,0.020706,0.425531,0.349837,-0.032459,-0.260321,0.190273,0.050962,-0.359980,0.161637,0.168219,-0.373006,0.039387,-0.323692,-0.331573,0.139808,-0.324361,-0.013940,0.476368,0.387429,-0.103387,-0.282481,-0.070474,0.295603,-0.111608,0.164995,-0.064792,0.193309,0.019635,0.401428,0.138600,-0.368197,-0.065600,0.299666,-0.283208,-0.219765,0.066724,-0.102410,-0.259933,-0.312834,0.457094,-0.310464,-0.072401,0.009372,-0.198817,0.054810,-0.108462,0.224251,-0.043841,0.143876,0.350730,0.057358,0.132319,0.530523,0.138302,0.189979,0.012262,0.292818,-0.067147,0.385699,-0.414022,-0.164784,0.039847,0.435904,-0.375447,0.033455,-0.121325,-0.302659,-0.123626,-0.375506,0.449039,0.105684,0.058939,-0.055666,-0.182192,0.081893,0.125830,-0.168014,0.113662,0.297166,-0.331080,0.223205,-0.493136,0.318597,0.211917,0.238969,-0.591499,0.721144,0.085069,-0.022424,-0.108850,-0.133998,-0.182824,-0.125470,0.114466,0.147058,0.001029,-0.178184,-0.630003,-0.419930,-0.277825', '25908042', '2080130', '1297924', '1291864');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304687', '午夜守门人', '剧情', '另类的爱情故事，肢体纠结的情色语言。1957年，原纳粹军官Max（Dirk  Bogarde 饰）隐姓埋名，在维也纳一家酒店当午夜守门人。某日，他遇到著名指挥家的妻子Lucia（Charlotte Rampling  饰），往事排山倒海而来。原来，Lucia是纳粹集中营的幸存者，当年是Max的性奴，也是他的情人，Max对她一直念念不忘。Max趁Lucia外出演出，和Lucia重逢，随即将她接到了自己的公寓，二人迅速恢复了往日的关系。于此同时，Max所属纳粹余孽小团体也在寻找Lucia，想除掉这个有力的证人，Lucia的丈夫也因为妻子失踪而报警。Max走投无路，只能囤积了大量食品在公寓里，和Lucia足不出户，靠性爱彼此安慰，忘记现实的困境，等待终将来临的救赎或者毁灭。©豆瓣', '德克·博加德', '莉莉安娜·卡瓦尼', 7.3, 15262, 'tt0071910', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1614957880.jpg', 1, 5.4, 37.9, 40.4, 15.2, '0.354925,0.016976,-0.618055,0.425085,0.012972,-0.167910,0.896076,-0.038540,-0.583527,-0.342222,0.157633,0.845780,0.009964,0.316047,0.224594,-0.023967,-0.184143,-0.787815,-0.145318,-0.101255,-0.127325,-0.448921,-0.194768,-0.259748,0.052081,-0.162285,0.674387,0.239088,-0.056468,0.476922,0.268518,0.362283,-0.237605,0.437419,-0.369186,-0.100644,0.016903,0.132429,-0.401788,0.126123,0.080375,-0.510453,-0.047185,0.113987,-0.127271,0.363851,0.617078,-0.118996,-0.106669,0.031688,0.320829,-0.411694,-0.150727,0.196652,0.308757,-0.094785,0.203189,0.222576,-0.292877,0.042012,-0.072834,-0.068645,-0.747129,-0.201630,0.127649,-0.034952,-0.507331,0.462942,-0.057004,0.131624,0.264900,-0.260089,0.465226,0.417297,0.060221,0.559816,-0.086599,-0.088357,-0.536472,0.400864,0.572618,-0.092236,-0.087212,0.299428,-0.190657,-0.266580,-0.037408,-0.210585,-0.424498,-0.169621,0.148219,0.095757,-0.293091,0.181957,-0.727312,-0.147105,-0.138785,-0.182695,0.251068,-0.438229,-0.183999,-0.582074,-0.234092,-0.225639,-0.183466,0.121156,0.148702,-0.111349,0.612576,-1.009340,0.281956,0.732366,0.374410,-0.673057,0.694838,0.121121,0.152008,-0.274866,0.195237,0.450770,0.028116,0.318405,0.093120,0.098435,-0.122664,0.030498,-0.567719,0.305224', '1308755', '30345227', '1301022', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304694', '马永贞', '剧情', '1898年山东大旱，无数难民涌入上海求生，人流中马永贞（金城武 饰）、马大祥（元华 饰）兄弟俩亦来到这片英国人掌控下的东方乐园，二马无技傍身，只好从码头苦力做起。马永贞机缘巧合结识上海码头之王谭四（元彪 饰），并凭借出色身手获得其欣赏。其时谭四与巡捕房支持的杨双连番血战，马永贞遭遇混战，为谭四的一壶春舞厅出手击退强敌，对卖场其中的歌女金铃子（宣萱 饰）一见钟情。谭四感佩马永贞义气，将一壶春和老板娘艳阳天一同赠送之。马永贞遂以一壶春为起点，率众攻占杨双地盘，激起上海滩无数杀伐。马永贞遭遇杨双暗算，命悬一线之际却再遇金铃子……©豆瓣', '金城武', '元奎', 6.9, 9539, 'tt0136242', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493513598.jpg', 0.7, 5.5, 50.7, 33.2, 9.9, '-0.039830,0.143083,-0.453807,0.337446,0.208641,-0.142819,0.256377,0.252585,-0.330854,0.038825,0.351012,0.456649,-0.055884,-0.001877,0.412358,-0.462193,0.119264,-0.628517,0.019000,-0.025424,0.185849,0.022487,-0.352392,0.127393,-0.316140,0.042741,0.250611,0.408088,-0.155279,0.761207,0.249264,0.078894,-0.436320,0.467625,0.025884,0.146147,-0.197902,-0.083084,-0.654570,0.165089,-0.375307,-0.350575,-0.273573,-0.269864,0.206996,0.066946,0.711822,-0.023726,-0.135844,-0.436981,0.147873,-0.130352,0.114525,-0.114924,0.247671,0.180841,0.052882,0.073001,-0.017947,0.017048,-0.203650,-0.030821,-0.357244,0.042636,0.208719,-0.371135,-0.533519,0.218697,-0.023675,-0.009350,-0.229713,-0.125105,-0.081536,0.287031,0.232280,0.200045,-0.048247,-0.135704,-0.306908,0.221764,0.548538,-0.105519,0.125983,-0.165393,0.154569,-0.328027,0.247840,-0.049179,-0.078259,-0.122582,0.310856,-0.125334,0.221985,0.116878,-0.652707,0.029192,-0.257881,0.146575,0.153405,0.281682,-0.064164,-0.789431,-0.155828,-0.109644,-0.037289,0.165162,0.301810,0.096936,0.434648,-0.338880,-0.002770,0.265532,0.383151,-0.326650,0.354834,-0.065072,0.158078,-0.052790,-0.134213,0.307455,0.124799,0.191923,-0.006967,0.149621,-0.427311,-0.205386,-0.154739,0.045493', '1292050', '26365262', '1451563', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304708', '游园惊梦', '剧情', '1930年代的苏州，以超凡脱俗的容貌和绝佳的昆曲造诣红极一时的得月楼歌妓翠花（宫泽里惠）嫁入当地豪门荣府，却遭遇荣家上下的冷落。荣兰（王祖贤）是荣家的亲戚，虽为女儿身却有男儿之志，一心想做巾帼英雄报效国家。翠花与荣兰结识后因合演昆曲《牡丹亭》生出情愫，终因越轨之举被荣家驱逐出门，被迫暂借荣兰处所安身。风流倜傥的邢志刚（吴彦祖）的到来为两个女人的生活带来意外波动。因为唤醒了原始冲动，荣兰对邢志刚一见倾心，可是世事无常，落花有情难保流水就有意。而翠花眼见荣兰的移情，也只能无可奈何地黯然身伤。©豆瓣', '王祖贤', '杨凡', 7.6, 64162, 'tt0279523', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1077911865.jpg', 0.6, 3.8, 31.5, 44.3, 19.9, '0.192745,0.052515,-0.588412,0.461942,-0.019285,-0.316768,0.675887,0.181701,-0.669881,-0.263909,0.268595,0.667692,-0.222555,0.122912,0.145549,0.061544,0.210192,-0.472021,0.006736,-0.186727,0.238871,-0.015927,-0.054517,0.098837,-0.255945,-0.125189,0.524621,0.211330,-0.269941,0.506209,0.198689,0.249242,-0.144025,0.266157,-0.192517,0.107884,-0.471650,0.205166,-0.356063,-0.076357,-0.081423,-0.427000,-0.309641,-0.136065,-0.114398,0.323483,0.492894,-0.014800,-0.065951,-0.391829,0.448997,0.062088,-0.056473,0.163448,0.277582,-0.065934,0.131476,0.292519,-0.201572,-0.229295,0.145651,-0.034882,-0.559055,0.206897,0.491903,-0.076357,-0.453452,0.413138,-0.059147,-0.358332,-0.227582,-0.100376,0.092522,0.091344,0.309770,0.529383,-0.131640,0.175565,-0.356511,0.077491,0.489773,0.203456,-0.204187,0.315329,-0.286229,-0.350563,0.331933,-0.436116,-0.453848,-0.067482,-0.007255,0.215138,-0.022598,0.358748,-0.224829,0.018772,-0.254606,0.419210,0.025145,-0.508806,-0.111455,-0.307578,-0.136020,-0.483421,-0.419087,-0.064185,0.609862,-0.129906,0.637997,-0.683487,0.068667,0.263202,0.224279,-0.751562,0.590535,0.264764,0.068705,0.112871,-0.232394,0.272811,-0.324863,0.048385,-0.022688,0.144428,-0.334676,-0.156961,-0.072147,0.148961', '3445516', '25721544', '1293265', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304726', '警察故事续集', '喜剧', '英雄警察陈家驹（成龙 饰）又回来了。不过，性格火爆、直言不讳的他这次因为不满意上司放走了一个极其危险的重犯而和上司吵翻了，愤然辞职。脱离了警察生活的家驹和女友去旅行期间，一间电话公司遭到了炸弹恐吓，本性难移的家驹马上赶到了现场，着手调查案件。岂料一波未平，一波又起。这个炸弹狂徒竟然炸毁了警局的大门，还绑架了家驹的女友，要求家驹携带大量赎款前往货仓交换人质。当家驹身带巨款抵达货仓时，发现这里已经布满了炸弹……©豆瓣', '成龙', '成龙', 7.7, 56409, 'tt0095403', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2408355680.jpg', 0.2, 1.3, 29.1, 50.1, 19.3, '0.277446,-0.113240,-0.531525,0.227315,-0.184566,-0.103901,0.626533,0.234341,-0.431809,-0.207039,0.296794,0.627995,-0.235151,-0.052166,0.421646,0.168030,-0.284170,-0.401986,-0.203380,-0.208649,-0.293359,-0.429350,0.031313,-0.078722,0.118721,-0.047484,0.223301,0.228318,-0.095696,0.707213,0.257081,0.115520,-0.171859,0.706377,-0.143548,0.227777,0.389421,0.047143,-0.081147,0.463287,0.027054,-0.157399,0.225493,0.227525,0.054239,0.611065,0.494786,0.160330,-0.353081,-0.114706,0.282922,-0.459528,-0.137992,0.072116,0.549859,0.065211,0.168010,0.005321,-0.391780,0.143642,0.073325,-0.249585,-0.333324,0.132568,-0.224470,-0.219282,-0.386494,0.205787,-0.397889,0.279712,-0.229561,-0.217340,0.535858,0.262500,0.020168,0.207329,-0.263679,0.084795,-0.683494,0.081785,0.584261,-0.271655,0.115838,0.076229,0.166928,-0.384076,0.148449,-0.142318,-0.284613,0.031073,0.504884,-0.182863,-0.321819,-0.108820,-0.521017,-0.184697,-0.586896,0.136842,-0.088799,-0.479708,-0.250306,-0.597313,0.094757,0.023403,-0.041298,0.227996,0.012367,0.014236,0.361808,-0.613068,-0.034560,0.434285,0.308527,-0.686848,0.360664,-0.128551,0.009240,-0.293562,0.013320,-0.288593,0.470106,0.612054,0.376314,0.314846,0.084807,-0.667450,-0.114020,-0.132742', '1296947', '1292633', '25908042', '1292590');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304730', '野鹅敢死队', '剧情', '福克纳上校（理查德·伯顿 Richard Burton 饰）受雇于著名银行家爱德华爵士（斯图尔特·格兰杰 Stewart Granger 饰），要去解救非洲自由斗士林班尼（Winston Ntshona 饰），然而，私下里，爱德华爵士和独裁者切恩有一个秘密的交易，要以林班尼来交换非洲某国的铜矿开采权。被蒙在鼓里的福克纳上校召集了昔日战友，组建了一支战斗力极强的敢死队，命名为野鹅敢死队，在经过了一系列紧张的训练后，一行人踌躇满志地踏上了他们的“战场”。在成功解救林班尼，准备撤离之时，福克纳上校却发现他们被本来该来接应的运输机放了鸽子。聪明的福克纳上校很快就明白了究竟发生了什么，现在最重要的，就是生存下去。©豆瓣', '理查德·伯顿', '安德鲁·麦克拉格伦', 8.1, 7070, 'tt0078492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2201840832.jpg', 0.3, 1.6, 20.1, 49.4, 28.6, '0.331647,-0.100358,-0.630700,0.444438,-0.148390,-0.365553,0.404342,0.060766,-0.399471,-0.140102,0.225615,0.900657,0.023022,-0.186191,0.491151,0.115148,-0.449054,-0.585091,-0.133200,-0.307060,-0.247273,-0.737352,-0.420216,-0.300755,0.208846,-0.322287,0.518060,0.036667,-0.018729,0.451330,0.207389,0.280107,0.121848,0.342764,-0.002685,-0.061011,0.532339,-0.316741,-0.356553,0.305745,-0.044079,-0.042289,-0.092147,0.103704,0.114668,0.416526,0.459231,-0.425679,0.040336,0.037883,0.026881,-0.439139,0.234129,0.102380,0.309855,-0.022889,-0.201678,0.236635,-0.042101,0.100589,0.004651,0.116247,-0.714491,0.060110,0.018257,0.253739,-0.828283,0.464001,-0.240424,0.259534,0.124646,-0.306628,0.401780,0.758550,0.097897,0.210055,0.157231,-0.039146,-0.569762,0.219519,0.691400,-0.168211,-0.118770,0.115095,-0.035820,-0.471659,0.225478,-0.246745,-0.086293,-0.278702,0.419977,-0.027509,-0.050173,0.050275,-0.643741,-0.147460,-0.321900,-0.335357,-0.086909,-0.459432,-0.065216,-0.464924,0.035654,-0.156994,-0.080908,0.197052,0.093850,0.043883,0.791341,-0.659507,0.125838,0.624299,0.114015,-0.430051,0.356877,-0.063448,0.078313,-0.215689,0.193702,-0.019080,0.321283,0.470850,0.186184,0.387544,0.213132,-0.533271,-0.424542,0.173248', '1309069', '3279069', '25908042', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304738', '运财五福星', '剧情', '赌王雷天在赌术大赛中因对手“赌花”上官飞花（宫雪花 饰）出千而失利，心有不甘的雷天自杀身亡。雷天在警队中的好友华叔于公于私都有惩治上官飞花的理由，于是请犀牛皮（冯淬帆 饰）召集其他几位福星罗汉果（曾志伟 饰）、大山地（吴耀汉 饰）和花旗参（苗侨伟 饰）参加赌术特训，以期能够战胜上官飞花。雷天之女雷慧琳（冯秀燕 饰）及其替身也一同受训，鹧鸪菜（洪金宝 饰）因受伤不能参加委托少林僧人清补凉代替。众位福星在赌术老师（郑佩佩 饰）和千王（陈百祥 饰）的调教下进步神速。华叔见时机已到，派出众福星和雷慧琳内应外合盗出上官飞花财产，并通过新一届赌术大赛要上官飞花身败名裂……©豆瓣', '曾志伟', '陈勋奇', 6.4, 5067, 'tt0116575', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1957200343.jpg', 2.2, 12.5, 56.5, 19.7, 9.2, '-0.379458,-0.355974,-0.216421,0.431143,-0.262606,0.318308,0.021919,0.137359,-0.559485,-0.228200,0.363214,0.782560,-0.053807,0.314578,0.384715,-0.171997,0.098023,-0.718038,-0.075774,-0.082778,0.035327,-0.392860,-0.075324,-0.067356,-0.006797,-0.011021,0.452199,0.015786,-0.104180,1.023988,0.439946,0.055173,-0.401626,0.003321,0.111674,-0.135023,0.154882,0.124395,-0.296516,0.407541,-0.394400,-0.077318,-0.294264,-0.111228,0.332224,0.379323,0.156400,-0.244555,0.376015,-0.139228,0.093836,-0.380878,0.313059,0.340732,-0.067327,0.031934,0.474997,0.458884,-0.044432,0.274132,0.043683,-0.247456,-0.667710,0.224966,0.533567,-0.197363,-0.694666,0.487669,-0.222239,-0.150374,-0.102609,0.013052,0.124997,0.259278,0.334606,-0.139749,-0.270685,-0.144188,-0.211346,0.401467,0.119644,-0.097788,0.214489,-0.242178,0.677702,-0.611428,-0.120970,-0.316798,0.193831,-0.001668,0.393263,0.090014,0.362806,-0.191777,-0.132920,-0.145405,0.160995,0.025544,-0.193930,0.063953,0.303029,-0.924529,0.148739,-0.411303,-0.398390,-0.059469,0.488464,-0.388952,0.702918,-0.723440,-0.019506,-0.021866,-0.034039,-0.725933,0.383769,0.350503,-0.083948,0.121434,-0.506157,0.021651,0.193669,0.305925,0.048251,0.439167,-0.098186,-0.391154,0.041321,-0.334097', '26365262', '25723905', '3811356', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304749', '浮云世事', '剧情', '爱娜（卡蒂·奥廷宁 Kati Outinen 饰）和凯瑞（Kari Väänänen 饰）是一对感情十分要好的夫妻，他们一个是餐厅经理，一个是电车司机，尽管经济并不宽裕，甚至有些“紧巴巴”，但很显然，照此发展，两人的未来充满了光明和希望。经济危机的到来让爱娜和凯瑞的家庭也陷入了危机，爱娜所在的餐厅破产倒闭，凯瑞在公司的“裁员抓阄”中不幸中彩，夫妻两人同时失去了工作，家里的贷款还未还完，生活露出了真实而残酷的面孔，爱娜和凯瑞不知该如何是好。虽然丢掉了工作，但夫妻两并没有丢掉斗志和尊严，为了生存，他们做出了种种努力，不幸的是，这些努力均以失败告终。在此走投无路之际，爱娜曾经的老板出现在了爱娜的面前，他带来了一个机会，它有可能坏的，但也有可能是好的。©豆瓣', '卡蒂·奥廷宁', '阿基·考里斯马基', 8.3, 11180, 'tt0116752', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1612645697.jpg', 0.2, 0.6, 11.9, 56.5, 30.9, '0.286116,0.045371,-0.618677,0.466128,-0.104784,-0.438301,0.819925,0.188114,-0.492999,-0.240642,0.144278,0.877470,-0.016605,0.279768,0.191152,0.006445,-0.232832,-0.633779,-0.080993,-0.112460,-0.257962,-0.593593,-0.378417,-0.162358,-0.408790,-0.041978,0.578277,0.203299,-0.008187,0.539991,0.325295,0.100913,0.057646,0.753749,-0.136302,0.107300,-0.081716,0.094628,-0.353720,0.075673,0.378810,-0.207082,-0.230115,0.533274,0.205665,0.506530,0.499105,-0.119061,-0.518487,0.104535,0.344636,-0.401224,-0.204854,0.277022,0.328477,-0.302138,0.215474,0.176255,-0.260185,0.008963,0.220322,0.140817,-1.231810,0.013770,-0.035619,0.105957,-0.775132,0.612571,0.027764,-0.209313,0.129559,-0.346820,0.372606,0.743045,0.442723,0.379321,-0.254926,-0.098541,-0.752399,0.050308,0.897577,0.020372,-0.309920,0.547059,-0.525919,-0.537638,-0.243048,-0.182676,-0.489331,-0.049472,0.247961,0.331909,-0.202178,0.100075,-0.500644,0.175074,-0.246050,-0.335195,-0.151351,-0.559097,0.039634,-0.434660,-0.191606,-0.934267,-0.667580,0.135312,-0.048310,-0.210889,0.644442,-1.153611,0.005304,0.242692,0.420120,-0.484225,0.809173,0.386966,0.270069,-0.058490,-0.180822,-0.169392,-0.330818,0.082837,0.238707,0.218490,0.226165,-0.189106,-0.190402,0.418976', '1793491', '1783461', '25917239', '1303112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304753', '人民英雄', '剧情', '一个平静的下午，神色紧张的青年阿小（梁朝伟 饰）与老妖走进了一家银行，他们为高利贷所迫，计划打劫还债，然而老妖突然病发，阿小慌忙之下泄露歹意，不得不仓促上阵，打伤警卫，将银行职员与顾客扣押为人质。岂料在人质中，居然有一名警方重大通缉犯古何阳（狄龙 饰），古何阳曾击杀警察，为警方所恨之入骨，他本欲逃离港岛，眼下却不得不从阿小手中控制了银行的局面，闻讯赶来的警察们将银行团团包围，古何阳的老对手陈警官（梁家辉 饰）到场，试图与古何阳谈判换得和平收场，但警队众人只想将古击毙。被困的古何阳执意要求带狱中的女友（金燕玲 饰）一同逃走，但是女友真的出现时，紧绷的情势迅速发生了变化……本片翻拍自美国影片《热天午后》。©豆瓣', '狄龙', '尔冬升', 7.8, 9157, 'tt0093845', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2493197693.jpg', 0.5, 2, 25.5, 52.4, 19.7, '0.172011,-0.000265,-0.400204,0.288916,0.106524,-0.163290,0.580953,0.117893,-0.451936,-0.497727,0.417762,0.398285,-0.166300,0.111338,0.375562,-0.287382,-0.216525,-0.676170,-0.303172,0.123336,-0.040078,-0.170062,-0.294837,-0.316854,-0.212330,-0.046054,0.678561,0.228287,-0.211064,0.466385,0.388630,0.387075,-0.486409,0.501869,0.132288,-0.185370,0.087444,-0.278712,-0.483713,0.212037,0.006371,-0.481185,-0.242228,0.178034,0.085913,0.609562,0.525123,-0.099963,-0.314307,0.057781,0.284540,-0.442445,-0.125458,0.166447,0.225790,0.124693,0.205502,0.049388,-0.284171,-0.095197,0.107817,-0.144383,-0.407845,0.454881,0.046342,0.005561,-0.482756,-0.182729,-0.340012,0.396211,0.084834,-0.106466,0.210861,0.457767,0.131038,0.095345,-0.053133,-0.076572,-0.496056,0.163183,0.608588,-0.241835,0.019262,-0.084953,0.079545,-0.372118,0.053653,-0.065048,-0.089938,0.012552,0.415510,0.005890,0.000436,0.159683,-0.347367,-0.370204,-0.514567,0.120251,-0.160862,-0.234554,-0.057228,-0.473413,0.009085,0.145983,-0.108644,0.289410,0.149635,0.139081,0.313630,-0.449439,0.036703,0.227525,0.246412,-0.644262,0.263568,-0.055766,0.123602,-0.119244,-0.253545,-0.137120,0.360406,0.450341,0.315433,0.011073,-0.227081,-0.250277,0.017043,-0.115920', '1295746', '4193254', '25908042', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304758', '细路祥', '剧情', '细路祥（姚月明 Yuet-Ming Yiu  饰）6岁了，他有一个嗜酒的父亲，一个好赌的母亲，一个深居简出的奶奶，还有一个被妈妈赶出了家门、从未见过的哥哥。细路祥家中经营茶楼，这天来了一个6岁的送外卖女孩阿芬。父亲不愿收下，把阿芬赶了出去，细路路祥暗中找到阿芬，和她一同送外卖，一同分享小费。二人有了童真的感情。细路祥向父亲打听哥哥下落，被父亲痛打一顿。这时阿芬也被发现了偷渡客的身份，被遣返大陆。九七临近，香港人的生活仍然是家长里短，琐碎八卦。细路祥听说奶奶和一个粤剧大师曾经有过一段旧情，自称奶奶男友的海叔有一个儿子，对细路祥特别好。日子就这样无惊无险的过。九七了。©豆瓣', '姚月明', '陈果', 8.6, 15621, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1889086570.jpg', 0.1, 0.6, 10.4, 49.3, 39.6, '0.388269,-0.184298,-0.480983,0.590644,-0.185987,-0.384360,0.540884,0.192811,-0.611771,-0.360931,-0.119235,0.920170,-0.176327,0.535034,0.221964,-0.018746,0.184403,-0.352064,-0.008689,-0.181022,-0.172640,-0.279612,0.143507,0.054281,-0.161025,-0.101004,-0.109204,-0.259977,0.252070,0.743296,0.251202,0.070062,-0.129245,0.408925,-0.480367,0.501812,0.187159,0.084462,-0.157893,0.113682,0.127692,-0.154934,0.264504,-0.011133,0.100234,0.362545,0.571188,0.136613,-0.217837,-0.079789,0.173214,-0.031477,-0.171016,0.068932,0.445749,-0.049145,0.110609,0.265339,-0.387486,-0.282227,-0.172311,-0.127787,-0.383462,0.096956,0.191937,-0.079796,-0.827766,0.317639,-0.137997,-0.097998,-0.066220,-0.281330,0.541582,0.425856,-0.020139,0.330193,-0.065054,-0.017937,-0.527811,0.286935,0.826038,-0.293596,0.390951,0.380610,-0.185073,-0.125086,0.481877,-0.190199,-0.540212,0.260078,0.252994,-0.437908,-0.410488,-0.225174,-0.446653,-0.170335,-0.188641,0.054072,0.277399,-0.530201,-0.035346,0.010001,-0.104072,-0.492886,-0.324496,0.243486,-0.004992,-0.070762,0.828422,-0.528114,0.392408,0.321798,0.551389,-0.598962,0.997015,0.080312,0.065583,-0.272453,0.356435,-0.074758,0.168026,0.077802,0.161830,0.419867,0.043327,-0.300536,-0.230440,0.022636', '1292720', '1306505', '30206431', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304771', '一个和八个', '剧情', '抗日时期，华北地区遍地烽火，中共领导下的八路军面对着敌人的步步紧逼勉力周旋。指导员王金（陶泽如 饰）本来从事敌后工作，因叛徒陷害而遭到组织怀疑，被和三名土匪、三名逃兵、一名奸细（谢园 饰）以及一名投毒犯放在一起关押。王金求助锄奸科长许志（陈道明 饰）重新查明自己的案情，但各部队失去联系，后有日军追兵，许志无法证明王金的清白。在王金和其他八名犯人的交往中，他用刚正忠诚的人格魅力打动了土匪头目大秃子（赵小锐 饰），以及逃兵中的老大哥老万头（魏宗万 饰）。不久，部队陷入日军包围，许志身负重伤，王金等人以待罪之身迎击日寇……©豆瓣', '陶泽如', '张军钊', 7.3, 5440, 'tt0086621', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2460455277.jpg', 0.8, 2.9, 38, 46.8, 11.5, '0.274999,-0.290548,-0.530481,0.482103,-0.075605,0.152901,0.603805,0.088115,-0.420965,-0.296853,0.517361,0.328744,0.369675,-0.184589,0.055547,-0.571735,-0.085549,-0.888337,-0.248516,-0.048570,-0.169995,-0.431678,-0.285425,-0.225136,-0.130900,-0.150157,0.748821,0.007479,-0.199143,0.389778,0.361218,0.413648,-0.040389,0.152050,0.143700,0.080609,0.284956,-0.528970,-0.386937,0.235348,-0.204208,-0.226727,-0.196016,-0.033286,-0.211889,0.398486,0.609709,-0.326492,0.032424,-0.288992,-0.033846,-0.320676,0.060241,0.279363,0.718480,0.162555,0.085293,0.217047,-0.137850,0.042006,-0.035356,0.246551,-0.613775,-0.226637,0.222220,0.255143,-0.481213,0.191908,0.101552,0.337319,0.229676,-0.018312,0.066314,0.482100,0.211422,0.033490,-0.092391,-0.103846,-0.429763,0.221690,0.493056,-0.125887,-0.047507,-0.499098,0.092407,-0.142299,0.188769,-0.220114,-0.287865,-0.161551,0.183042,-0.216096,-0.064973,0.008599,-0.482669,-0.099231,-0.159610,0.101465,-0.281067,-0.036459,-0.022930,-0.637078,-0.093779,-0.378636,-0.135821,0.376129,0.270896,0.105169,0.579930,-0.475199,-0.046848,0.266804,0.300279,-0.560406,0.323664,0.235536,0.055422,-0.123176,-0.180189,0.061984,0.358895,0.299772,0.410696,0.159415,-0.552303,-0.365411,-0.072020,-0.258202', '25723905', '3136507', '10467125', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304798', '火龙帝国', '动作', '在伦敦的某处，沈睡地底多年的喷火巨龙，因地下工程的施工而被唤醒并飞离洞穴，40多年后，巨龙与其繁殖的无数后代占领了地球，人类文明因而被摧毁殆尽，只能躲在废弃城堡的洞穴中，靠未被喷火龙摧毁的农作物为生。伦敦地区的人类领袖昆恩是一个自小母亲便死于巨龙火舌的孤儿，带领着该区仅存的人类与怪龙对抗；某日，来自外地的美国义勇军官范桑与他的军队前来援助，起初昆恩拒绝外来客的支持，后来才明白原来美国人一样饱受喷火龙摧残之苦，于是两支大军结合力量，计划消灭最早逃出的巨龙皇后，为人类的生存与希望而战。', '克里斯蒂安·贝尔', '罗伯·鲍曼', 6.1, 9543, 'tt0253556', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p895401769.jpg', 1.9, 16.5, 59.8, 17.1, 4.6, '0.129280,0.038058,-0.853464,0.692595,0.030109,-0.075596,0.663747,-0.237754,-0.453855,-0.131364,0.239104,0.701782,0.231564,0.211341,-0.030957,-0.219036,0.062622,-0.258301,-0.317656,0.036228,-0.414822,-0.193688,-0.457104,-0.277537,-0.084989,-0.569960,1.047549,0.377636,-0.160839,0.311262,-0.204101,0.268939,-0.414590,0.331772,-0.115416,-0.197295,-0.184167,-0.019663,-0.318623,0.297294,-0.331981,-0.214320,0.077152,0.130452,-0.311200,0.146373,0.836603,-0.659323,0.345387,-0.626601,0.033994,-0.654948,0.066602,0.216659,0.611955,-0.149481,0.237768,0.178332,-0.044282,0.073130,0.008352,-0.037127,-0.685252,-0.223512,-0.002588,-0.043767,-0.510388,0.598604,0.375366,0.053188,-0.130689,-0.434929,0.034721,0.443103,0.034283,0.546046,-0.384800,0.026378,-0.580677,0.058864,0.724048,-0.485425,-0.513904,-0.165483,-0.213584,-0.459253,0.098582,-0.295945,-0.186519,-0.494352,0.210169,0.213268,-0.381160,0.525726,-0.937746,0.168159,-0.553894,-0.348462,0.153792,-0.338567,-0.272722,-0.568195,0.007993,-0.112659,0.278712,0.400830,0.269380,0.016755,0.558764,-0.655726,0.238683,0.495667,0.597672,-0.574356,0.641321,-0.223547,0.127238,-0.093534,0.134753,0.569736,0.289227,0.360357,0.215028,-0.201211,-0.082326,0.056458,-0.418793,0.406922', '26290398', '24879819', '1578502', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304811', '关于一个男孩', '剧情', '威尔(休·格兰特 Hugh Grant 饰)是一个伦敦的有钱人。他继承了父亲的遗产，终日吃喝玩乐，游戏情场。然而，他内心却有着空虚和孤独。为了能够认识更多的女人，他想到了单亲家长会。那里单亲妈妈众多，他必然能游刃有余。带着这个目的，他假扮成单亲爸爸，加入了单亲家长会。马克斯（尼古拉斯·霍尔特 Nicholas Hoult 饰）的母亲也是家长会里的成员。母亲每天早晨醒来，都会开始沮丧、落泪，想自杀。马克斯家庭不幸，加上常常受人欺负，身处劣境的他寄希望于威尔，把威尔当作可依赖的对象。他经常造访威尔家，坐在威尔身边默默的看电视。起初这一切让威尔觉得十分打扰。但是慢慢的，两颗孤独的心开始找到依靠，威尔和小男孩之间的友谊渐渐升温。©豆瓣', '休·格兰特', '克里斯·韦兹', 7.3, 24420, 'tt0276751', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p934565618.jpg', 0.3, 3.2, 38.6, 44.6, 13.3, '0.201751,-0.080649,-0.727674,0.219756,-0.394032,-0.293255,0.692320,0.160108,-0.618736,-0.296909,-0.026116,1.019856,0.067345,0.575062,0.268112,0.094189,-0.092546,-0.410660,-0.003540,0.223706,0.071434,-0.532160,-0.174566,-0.388164,-0.140784,-0.117366,0.408758,0.034790,-0.163878,0.542807,0.103479,0.422296,0.216404,0.397408,0.052962,-0.232488,-0.036684,-0.198023,-0.005220,0.069104,0.080117,-0.033854,-0.091916,0.361660,0.085348,0.176061,0.346303,0.034402,0.011784,-0.133053,0.243723,-0.257331,-0.182168,0.017621,-0.026520,-0.042404,0.562530,0.112853,0.042860,-0.234172,0.121644,0.048199,-0.589191,0.109598,-0.111061,0.123928,-0.617936,0.266307,-0.053450,-0.249166,0.506075,-0.458792,0.258216,0.343251,-0.097808,0.373495,-0.473002,-0.105093,-0.570332,0.137045,0.521339,-0.112019,-0.217844,0.406508,-0.128344,-0.105459,0.354434,-0.347404,-0.603782,-0.093746,0.096206,0.025591,-0.318355,0.411637,-0.359976,0.115555,0.018450,-0.307931,0.071391,-0.495601,0.058611,-0.228560,-0.205035,-0.308727,-0.610031,-0.129210,-0.258338,-0.466098,0.511601,-1.027463,0.509099,0.526165,0.131307,-0.635465,0.725251,0.403171,0.177178,0.146056,0.038153,0.450363,-0.156866,0.115674,-0.042544,0.036908,0.078311,-0.047529,-0.549973,0.543319', '1302384', '1292720', '1783461', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304813', '公子多情', '喜剧', '富商施头（王青 饰）其貌不扬，在某次名流聚会上被美女Lychee（利智 饰）戏弄，怀恨在心，并扬言报复。偶然机会，施头遇见来自大陆的前进发（周润发 饰）、高佬伟（曾志伟 饰）和傻鸡（成奎安 饰）。他灵机一动，希望让前进发假扮贵公子勾引Lychee，并请出仪表教练Anita（梅艳芳 饰）对其进行贵族礼仪训练。苦于在香港不见出头之日，三人一口应承下来。经过一段时间的魔鬼训练，前进发在随后举行的印度弱智儿童基金晚宴上大出风头，将Lychee在内的一干美女迷得神魂颠倒，甚至连亲手将其调教出来的Anita也不能自已……©豆瓣', '周润发', '霍耀良', 7, 5477, 'tt0095236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2347616685.jpg', 1.6, 6.6, 46.9, 30.9, 14, '-0.105448,0.080867,-0.479325,0.431804,0.005461,0.026024,0.294813,-0.061065,-0.346922,-0.116377,0.262135,0.552496,-0.500870,0.083743,0.432574,-0.444507,-0.169406,-0.657050,-0.007446,-0.002648,-0.023053,-0.127330,0.104487,0.007938,-0.072968,-0.325186,0.247700,-0.234393,-0.188434,0.637250,0.559493,-0.068834,-0.103293,0.051276,-0.213899,-0.130422,-0.022057,0.009990,-0.274273,0.224149,-0.317438,-0.375085,-0.079778,-0.083007,0.120087,0.172102,0.502624,-0.215352,0.014776,-0.241801,0.228906,-0.208209,0.108212,0.158952,0.253131,0.068140,0.267093,0.132468,-0.025756,0.353244,0.230467,-0.142340,-0.409351,0.086084,0.189626,0.198938,-0.728181,0.449660,0.079219,0.116124,-0.352767,-0.242769,0.140234,0.156920,0.160453,-0.043810,0.127811,0.441241,-0.541784,0.342638,0.306210,0.071270,0.096579,-0.162950,0.085810,-0.306045,0.226724,-0.184409,-0.204772,-0.072921,0.198718,-0.111190,-0.133097,-0.169021,-0.404377,-0.190101,-0.150552,-0.165077,0.238947,-0.258397,-0.212357,-0.799980,0.251933,-0.152635,-0.164736,0.118625,0.199301,-0.209906,0.489308,-0.673354,0.122008,0.355670,0.357597,-0.578754,0.455711,0.233784,-0.077656,-0.099810,-0.408339,0.236540,0.288703,0.143402,-0.090182,0.344238,-0.248657,-0.262419,-0.312481,-0.001669', '25833539', '26365262', '24751811', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304826', '夜半歌声', '剧情', '1926年的上海，青年演员宋丹平（张国荣）因主演歌剧迷倒成千上万女性，但对她们他均不动心，单与清纯的富家少女杜云嫣（吴倩莲）坠入爱河。然而因为他的戏子身份，两人恋情曝光后遭到杜云嫣父亲的强行阻止，杜云嫣被禁闭在家，许配给某豪门显贵。与该权贵公子的订婚夜宴上，杜云嫣装病离席私会宋丹平，权贵公子发现后妒火中烧，派人毒打过宋丹平后放火焚烧了剧院，杜云嫣自此成为外人眼中的疯妇，而已成废墟的剧院因为每逢月圆之夜会传来虚无缥渺的歌声，被传是宋丹平的鬼魂作祟。十年后，某个小剧团暂住进被传有鬼的剧院，青年演员韦青（黄磊）遇到如幽灵的宋丹平，爱情悲歌随即再次上演。©豆瓣', '张国荣', '于仁泰', 7.9, 61630, 'tt0115016', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p971237356.jpg', 0.3, 1.8, 24.1, 50.1, 23.7, '0.392345,0.035425,-0.465189,0.088918,0.092968,-0.044159,0.998325,0.123927,-0.471715,-0.288459,0.250415,0.639483,-0.675808,0.483556,0.496511,-0.153418,-0.085290,-0.667580,-0.237220,-0.349520,0.129001,0.056121,0.321031,0.001609,-0.047894,-0.131201,0.655327,0.114035,-0.122085,0.280356,0.408992,0.259363,-0.262812,0.241908,-0.042971,0.108401,-0.016755,0.007599,-0.244443,0.346638,-0.164387,-0.276377,-0.081417,-0.331767,-0.346358,0.241568,0.475841,-0.196633,0.104523,-0.347027,0.559936,-0.171800,-0.177692,0.284830,0.251321,-0.090153,0.258108,0.153918,-0.022830,-0.252762,-0.050286,-0.198635,-0.123728,0.276506,0.318507,0.202483,-0.308039,0.334945,0.049530,0.056478,-0.161971,0.057858,0.151537,-0.075932,0.274039,0.218646,-0.042142,0.216927,-0.629913,0.293928,0.616583,0.226948,-0.235461,0.167747,0.087119,-0.554119,0.308257,-0.291941,-0.424800,0.137121,0.348294,-0.044920,-0.142110,0.304202,-0.227347,-0.276395,-0.166018,0.125344,0.048480,-0.311112,-0.502690,-0.616310,-0.268606,-0.168573,-0.011157,-0.033038,0.385915,-0.074731,0.408375,-0.798815,0.201144,0.281363,0.329448,-0.446622,0.548946,-0.114390,0.076619,0.123777,-0.170684,0.191955,0.138103,0.278463,-0.035830,0.102747,-0.366714,-0.251366,-0.305167,0.014837', '1301686', '1296534', '21348112', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304837', '爆裂刑警', '动作', '刑警Mike（吴镇宇 饰）和阿仁（古天乐 饰）是一对拍档兼好兄弟，两人一个性格孤僻、沉默寡言，一个玩世不恭、愤世嫉俗，均不得上司赏识。为了缉捕劫匪“毒龙”一伙，两人在独居老人四婆（罗兰 饰）家中布置了监控装置。期间，孤儿院长大的Mike结识了被男友遗弃的孕妇Jennifer（林美贞 饰），表示愿做孩子的父亲，而阿仁也结识靓妹阿Yen（郑雪儿 饰）。不久，Mike知晓自己身染绝症，来日已经不多，为了Jennifer以后的生活，他与“毒龙”私下进行交易获得鉅款。同时，不忘职责的他又将“毒龙”的行踪通知阿仁，并与之一起同“毒龙”展开搏杀。©豆瓣', '吴镇宇', '叶伟信', 7.6, 23977, 'tt0214555', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1226739925.jpg', 0.4, 3.1, 31.3, 47.6, 17.5, '0.229020,-0.394939,-0.354802,0.600242,-0.274900,-0.378559,0.667658,0.012908,-0.333339,-0.381823,0.158273,0.678207,-0.070214,0.093784,0.025762,-0.142332,-0.159013,-0.602662,-0.029440,-0.129676,-0.040152,-0.417277,-0.149642,-0.193491,-0.196115,-0.201502,0.461052,-0.263371,0.136319,0.503368,0.296307,0.157249,-0.398585,0.254561,-0.173685,-0.130724,0.068633,0.107871,-0.373794,0.103395,-0.049020,-0.168285,0.087917,0.153874,0.227076,0.394403,0.756803,-0.300619,-0.215399,-0.448993,0.081103,0.023492,0.177525,0.081811,0.381730,-0.003184,0.416301,0.388048,-0.257127,0.124872,0.037121,-0.123720,-0.402899,0.089381,0.308537,-0.005514,-0.370181,0.450479,-0.199894,-0.101459,-0.094280,-0.409157,0.105955,0.422177,0.431282,0.230863,-0.014361,0.035517,-0.393656,0.269848,0.718894,-0.181148,0.104257,0.384498,-0.149357,-0.433703,0.154111,-0.112488,-0.514472,-0.059722,0.227778,-0.146008,-0.152064,0.302029,-0.446707,-0.027047,-0.162946,0.268186,-0.108287,-0.314843,0.186153,-0.611172,-0.120159,-0.485430,-0.252979,0.123410,0.202880,-0.146317,0.598022,-0.905864,0.151820,0.291335,0.316709,-0.826898,0.657089,0.301087,0.297390,-0.403667,0.041921,-0.058228,0.416234,-0.001800,0.265044,0.178570,-0.088938,-0.073637,-0.195368,-0.039942', '1293265', '3445516', '1292219', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304854', '律政俏佳人', '喜剧', '艾丽（瑞茜•威瑟斯彭 Reese Witherspoon 饰）虽然拥有羡煞旁人的美貌——金发，白肤，高挑，精通打扮，就像一个精美的芭比娃娃。美貌和活泼的性格，让艾丽成为了一个完美的女生。她的男友沃纳（马修•戴维斯Matthew Davis饰）条件也不俗，拥有富贵的出身和出众的外表。两人十分般配，却想不到沃纳根本就没把艾丽当成终身伴侣，在他眼中，艾丽只是一个花瓶，除了漂亮别无所长，于是他考上哈佛法学院之后，甩了艾丽，与旧女友重拾旧爱。艾丽不甘心，千方百计也考上了哈佛，她要用行动来证明自己并非徒有外表。哈佛的学习生活非常枯燥，而且这个金发美人还处处受到歧视。令大家大跌眼镜的是，艾丽竟然机智的干了一番事业。©豆瓣', '瑞茜·威瑟斯彭', '罗伯特·路克蒂克', 7.5, 171370, 'tt0250494', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2201173343.jpg', 0.5, 3, 34.6, 44.8, 17.1, '0.376546,-0.232364,-0.620360,0.726879,-0.758884,-0.342954,0.752034,0.206214,-0.386016,-0.273456,-0.129978,0.564026,-0.247502,0.022150,0.175144,0.287730,-0.194636,-0.696699,0.148536,-0.070219,-0.006891,-0.414666,-0.362919,-0.055202,-0.270112,-0.393925,0.564985,-0.517873,-0.326202,0.588453,0.304706,0.088502,0.197002,0.232212,-0.402626,-0.164465,-0.036281,0.199494,0.243250,0.285445,0.199470,-0.027186,0.042740,0.362865,-0.118824,0.232687,0.581879,0.089364,0.000320,0.030884,0.489891,0.093540,-0.117986,0.252438,0.033838,-0.485386,0.084486,-0.260589,-0.140379,-0.036932,0.538934,-0.119204,-0.622485,-0.193202,0.325085,0.044665,-0.579226,0.494989,-0.173842,-0.365163,0.150107,-0.381041,-0.535367,-0.034743,0.276504,0.495075,0.269366,0.380722,-0.707063,0.214013,0.458695,0.592318,-0.674251,0.342188,-0.437826,-0.537956,-0.071430,-0.487194,-0.883444,0.109805,0.216944,-0.101513,0.240872,-0.000025,-0.416005,-0.010253,-0.370244,0.154343,-0.026303,-0.521191,-0.018029,-0.296122,-0.194453,-0.837986,-0.849172,-0.257088,0.020631,-0.364560,1.073515,-0.908974,-0.116577,0.280706,0.162884,-0.506243,0.648735,0.393388,0.252732,0.146371,-0.190442,0.113133,0.263028,-0.045885,-0.011453,0.565423,-0.034063,-0.461265,-0.410078,0.487188', '26348103', '24284209', '26354526', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304862', '不散', '剧情', '天下没有不散的宴席。然而主人的魅力以及客人心的属性，却可左右宴席的长短、有无。老电影院里，跛脚售票员（陈湘琪）虽有心设宴，年轻的放映员（李康生）却无心做客；电影《龙门客栈》里的剑客（石隽）在自己的旧影像里沉醉落泪，时间却早已无情的将其抛在身后；日本男子如幽灵般找寻着，然而并没同性想在他身边作长久的停留。即使电影院早已不见昔日的繁华，变得安静异常，却仍不能与家（哪怕旅馆）的功用相提并论。出入其间的，是或多或少想将自己在黑暗中隐藏封闭的人，他们有着天真而诡异的想法，可是时间是最靠不住的（人老会死，电影院老会被拆），相信它只会换来更多伤心。©豆瓣', '李康生', '蔡明亮', 7.7, 7283, 'tt0377556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2496658923.jpg', 0.8, 3.7, 27.2, 43.8, 24.5, '0.341318,0.198162,-0.861435,0.567525,-0.125169,-0.326168,1.197796,0.152727,-0.531822,-0.256165,0.122194,0.426853,-0.036244,0.288190,-0.157897,-0.061722,-0.257319,-0.511521,-0.261220,-0.253422,0.009531,-0.267362,-0.405442,-0.108725,-0.261329,-0.111732,0.613235,0.253450,-0.017382,0.162699,0.320923,-0.123651,-0.284234,0.652607,-0.380959,-0.263276,-0.162803,0.105335,-0.066509,0.087274,0.079400,-0.278004,-0.379862,0.242100,-0.053813,0.453223,0.534299,-0.347167,-0.239897,0.104133,0.313778,-0.064995,-0.104787,0.153366,0.037654,-0.029344,0.377373,0.025903,-0.286514,0.078319,0.094381,0.087448,-0.743606,0.286929,0.248220,0.439415,-0.440531,0.558362,-0.012520,-0.280229,-0.165367,-0.244155,0.377757,-0.278801,0.221252,0.275512,-0.125327,-0.242232,-0.512407,0.089241,0.669871,0.022460,-0.521139,0.529497,-0.263855,-0.359799,0.003600,-0.415775,-0.518254,-0.139846,-0.014754,0.274677,-0.149723,0.249540,-0.404975,0.346630,-0.089745,-0.075459,-0.293564,-0.352799,-0.188807,-0.484170,-0.048113,-0.497599,-0.323166,0.112241,0.254301,-0.083472,0.707441,-0.817292,0.121283,0.343888,0.396776,-0.248579,0.917678,0.022862,-0.002363,0.222418,-0.275247,0.234377,0.022172,0.266191,0.129195,0.256852,-0.311981,-0.241445,-0.578082,0.578189', '1417428', '1296370', '1292211', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304868', '幽灵世界', '剧情', '有这么一对好友，她们是同是20岁的伊尼德（索拉•伯奇 饰）与丽贝卡（斯嘉丽•约翰逊 饰）。虽然她们性格十分迥异，但她们还是常常待在一起，讨论发生在她们周遭的人与事物，她们向对方表达自己对现实生活的看法，或褒或贬。就这样一直如此，持续着她们的友谊。两人开始疏远是在高中毕业以后。丽贝卡开始工作了，伊尼德却想到另外一个地方继续学业，两人不太同步的生活开始令双方的价值观产生了变化，她们身边各自有不同的人出现，有各种不同的事情发生，现实把她们从彼此的生活中渐渐拉走了，生活又将会为她们带来些什么？©豆瓣', '索拉·伯奇', '泰利·茨威戈夫', 7.9, 12712, 'tt0162346', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p924741559.jpg', 0.5, 3.1, 24.9, 44.7, 26.8, '0.541825,-0.297182,-0.655635,0.648280,-0.139812,0.046417,0.983327,0.041414,-0.725700,-0.383714,-0.014020,0.876129,-0.623260,0.285713,0.082272,-0.281240,-0.687603,-0.807309,0.137123,-0.210723,-0.313782,-0.614558,0.307340,-0.178426,-0.455348,0.062741,0.584533,-0.311838,-0.180632,0.259815,0.103827,0.258983,-0.169593,0.829242,-0.191963,0.196989,-0.364776,0.023290,-0.249976,-0.152024,0.266651,-0.052469,-0.330026,0.153557,0.160393,0.199534,0.887893,-0.258867,-0.274221,0.032283,0.280088,0.032920,0.091644,0.144170,0.277905,-0.089051,0.204772,0.176720,-0.039243,-0.033805,-0.097431,0.092289,-0.433272,0.193684,0.001660,0.573275,-0.509584,0.233381,0.164481,-0.325282,0.093171,-0.288713,0.106421,0.753569,0.402366,0.170151,-0.245671,-0.435629,-0.754242,-0.284337,1.102805,0.191129,-0.217050,0.514632,-0.519893,-0.519500,-0.265635,0.064084,-0.362747,-0.157327,-0.126656,0.304863,-0.062070,0.597811,-0.740091,0.146441,0.226896,-0.313850,0.195451,-0.867341,0.098111,-0.636921,-0.176227,-1.085083,-0.813330,0.002465,0.005654,-0.341647,0.802313,-1.342503,-0.047671,0.234351,0.537727,-0.591926,0.589077,0.144090,0.323794,-0.221604,-0.056548,0.042296,-0.153148,-0.010690,0.242433,0.489756,0.221639,0.307816,-0.231701,0.494389', '21766698', '1308755', '1292219', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304879', '去年烟花特别多', '剧情', '九七香港回归使家贤（何华超）等5名已近不惑之年的华籍英兵成了“无用”的人，然而他们虽然深知无力与年轻一代争抢舞台，却仍在尽力给自己找寻新的位置，但许多事并非有心努力就能做成，朋友Bobby虽重新将自己确定，家贤却只能通过弟弟家璇（李灿森）的引荐铤而走险加入黑帮，等待命运将他捶打。无论性格还是社会地位，家璇都与家贤形成鲜明对比。家人明显更看重家璇、年轻女中学生对家贤等老兵恣意嘲笑奚落的同时对家璇作盲目崇拜等情节，或许暗喻了港人在新旧交替时刻的复杂心理。©豆瓣', '何华超', '陈果', 8.1, 15456, 'tt0189660', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p796235683.jpg', 0.2, 1.2, 17.6, 53, 28, '0.077893,0.208229,-0.427267,0.280166,-0.317495,-0.149780,0.085831,0.140166,-0.684794,0.007078,0.093763,0.377913,0.265970,0.028225,-0.043458,-0.388388,-0.163514,-0.616023,0.047585,-0.001537,-0.164760,-0.587491,-0.147563,-0.126511,-0.313574,-0.149031,0.738063,0.030584,-0.094469,0.154889,0.276122,0.308323,-0.152921,0.304433,-0.279870,-0.297217,0.352745,0.189665,-0.432545,-0.094562,-0.017305,-0.425480,-0.337979,0.319946,0.077604,0.457626,0.815958,-0.198384,-0.255895,0.219040,0.222187,-0.193983,0.051094,0.299255,0.312182,0.036324,0.326841,0.294441,-0.083796,0.068590,-0.121622,0.083719,-0.898712,-0.040524,0.488115,-0.126389,-0.420909,0.636546,-0.025387,-0.356899,-0.091546,-0.270112,0.259781,0.189268,0.177025,0.422194,-0.179825,0.137029,-0.144997,-0.006430,0.592810,0.338937,-0.204817,0.174636,-0.121754,-0.161756,0.189261,-0.384495,-0.412531,-0.281257,0.243701,0.395597,-0.159246,0.380949,-0.296142,0.020975,-0.300701,-0.018284,0.314146,-0.568910,0.085607,-0.044239,-0.340553,-0.398186,-0.066412,0.083681,0.141945,-0.209197,0.980440,-0.723855,0.086689,0.359091,0.504775,-0.681145,0.420737,0.315310,0.216447,-0.288841,-0.121499,-0.105249,-0.095914,-0.014934,0.087248,0.091842,-0.173434,-0.152677,-0.296041,0.351283', '27602116', '26678784', '24284209', '1308424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304898', '训练日', '剧情', '阿洛佐（丹泽尔•华盛顿 Denzel Washington饰）是美国毒品缉查部的黑人警探，经验丰富，查案出色，对毒品案件有着敏锐的嗅觉。人称“魔幻之眼”。这天阿洛佐的部门来了一个新同事杰克（伊桑•霍克 Ethan Hawke 饰），杰克跟随阿洛佐深入到街头的每一个阴暗角落，发现这个城市光怪陆离的同时，也慢慢见识了阿洛佐亦正亦邪的办案手法。阿洛佐虽然身为警探，手段却游走在法律边缘。他秉持“以毒攻毒”的原则，先把自己武装起来：没收罪犯的毒品自己服下，用枪指着杰克命令他跟着照做，他与贩毒分子甚至有着某种不寻常关系。但另一方面，他却奋力保护杰克这个年轻人，复杂的性格让杰克对这个神探上司捉摸不透。©豆瓣', '丹泽尔·华盛顿', '安东尼·福奎阿', 8, 82177, 'tt0139654', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1350561397.jpg', 0.2, 1.3, 19.9, 54, 24.6, '0.335958,-0.064414,-0.575473,0.738998,-0.312463,0.119326,0.721876,0.081442,-0.541251,-0.290351,0.251594,0.735783,0.063204,-0.182324,0.063933,0.145381,-0.352429,-0.584729,-0.188099,-0.041473,-0.318520,-0.567944,-0.619810,-0.244347,-0.092049,-0.084458,0.273236,-0.087250,-0.359586,0.362083,0.267832,0.287084,-0.021441,0.367950,-0.223268,-0.270866,0.370827,-0.347023,-0.109817,0.015149,0.190074,-0.265813,-0.094048,0.210717,0.026455,0.564489,0.414309,0.012863,-0.377796,-0.006864,0.208120,-0.329292,-0.175360,0.070854,0.260110,0.040225,-0.100048,0.107173,0.000177,0.007857,-0.077056,0.009244,-0.989506,-0.011494,0.081615,0.247880,-0.416597,-0.051188,-0.279782,-0.126832,-0.156471,-0.319640,0.064711,-0.021144,0.083837,0.190410,0.022984,0.028313,-0.360088,-0.066719,0.516710,0.243127,-0.302093,0.183072,-0.469172,-0.577605,-0.040662,-0.207664,-0.244409,-0.252909,0.230765,-0.196368,-0.220144,0.116910,-0.602448,0.101800,0.089002,-0.043452,-0.233480,-0.331069,0.065893,-0.521268,-0.301126,-0.699325,-0.350984,0.138186,0.032977,-0.113398,0.621761,-0.667297,-0.005968,0.725706,0.140294,-0.520387,0.645941,0.087557,0.003469,-0.233091,-0.318540,0.168786,0.457991,0.429306,-0.005340,0.604947,0.196380,-0.354211,-0.242311,0.385667', '3785918', '25932086', '1793491', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304899', '速度与激情', '动作', '洛杉矶的年轻人都热衷于街头赛车，在这里，只要你拥有速度，你就拥有一切。新晋警官布赖恩（保罗•沃克 Paul Walker 饰）为了破获最近屡屡发生的飞车党劫车案而充当卧底，打入这里活跃的飞车党帮派中，搜集证据以期将罪犯乘之于法。布赖恩凭借高超的车技很快赢得了飞车党老大多米尼克（范•迪塞尔 Vin Diesel 饰）的欣赏和信任，并且很快和多米尼克的妹妹米亚（乔丹娜•布鲁斯特 Jordana Brewster 饰）堕入爱河。然而飞车党的第二把手文斯却是对布赖恩充满敌意，原来文斯一直暗恋米亚，而且布赖恩的到来威胁着他二把手的地位。这时，飞车党的党员们开始怀疑他们内部藏有奸细，布赖恩的日子开始不好过。而且和多米尼克接触越久，他们之间的友谊就越加深厚，布赖恩开始进退两难。©豆瓣', '保罗·沃克', '罗伯·科恩', 7.9, 187673, 'tt0232500', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1033539605.jpg', 0.3, 1.7, 25.4, 48.7, 23.8, '0.437143,-0.163085,-0.610509,0.334306,-0.108397,-0.139632,0.481026,-0.062519,-0.630730,-0.190345,0.115997,0.462825,-0.157385,0.082277,0.407900,-0.021632,-0.636968,-0.784218,-0.054051,-0.246936,0.024866,-0.651649,-0.487343,-0.258064,-0.117447,-0.363893,0.365614,0.156993,-0.198719,0.596442,0.319530,0.324692,0.081275,0.276040,0.031361,-0.077660,0.376743,-0.176169,-0.334067,0.087750,0.160335,-0.001312,0.070916,-0.017162,0.326360,0.171794,0.310213,-0.251916,-0.079462,-0.176863,0.140719,-0.372235,0.140283,0.008925,0.461497,0.048159,0.231289,0.374900,-0.178132,-0.229177,-0.091135,-0.215814,-0.795533,0.196248,0.100059,0.051687,-0.267200,0.108733,-0.070806,-0.063015,0.228207,-0.011277,0.123574,0.331029,0.172354,0.178360,-0.014865,-0.079898,-0.544647,-0.200889,0.580653,-0.184709,-0.244312,-0.019029,0.066865,-0.248668,-0.167398,-0.237458,-0.234313,-0.169102,0.224847,0.002362,0.198159,0.415389,-0.302485,0.140376,-0.110776,0.018846,-0.055266,-0.448885,-0.106359,-0.681629,-0.218142,-0.403641,-0.106120,-0.090863,0.003346,-0.407461,0.569163,-0.804619,0.185656,0.420352,0.227678,-0.507803,0.434502,0.041205,0.012399,-0.285811,-0.567533,0.242153,0.287375,0.134261,0.215026,0.131966,-0.157810,-0.296520,0.106171,0.371762', '1307442', '4301278', '1793491', '24753477');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304915', '火腿，火腿', '剧情', '希尔维娅（Penélope Cruz 佩内洛普•克鲁兹 饰）是西班牙某小镇上参逊内裤厂的缝纫女工，她与厂主的儿子乔西相恋，并怀有对方的孩子。优柔寡断的乔西发誓迎娶希尔维娅，却遭到母亲的强烈反对。为了拆散两人，乔西的母亲雇佣健美的内裤模特卢去勾引希尔维娅，与此同时自己也臣服于卢年轻健硕的雄性魅力之下。隐约感到女友移情别恋的乔西伤心非常，继而从希尔维娅的母亲那里得到慰籍。脆弱的爱情，混乱的情欲，一切该将何去何从……本片荣获1992年威尼斯电影节银狮奖。©豆瓣', '斯特法尼娅·桑德雷莉', '比格斯·鲁纳', 6.6, 12626, 'tt0104545', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2255759966.jpg', 1.7, 10.2, 50.6, 28.9, 8.6, '0.300314,0.153166,-0.778411,0.377410,-0.013661,-0.419711,0.654535,0.134898,-0.197523,-0.270717,0.344717,0.652650,-0.168306,0.345196,0.165225,0.285281,-0.361804,-0.761636,-0.059195,0.230267,-0.164348,-0.226641,-0.150189,-0.178901,-0.046450,-0.153613,0.820020,0.095471,-0.183542,0.337773,0.792065,0.383458,0.027624,0.364046,-0.179900,0.144594,0.043836,-0.029951,-0.319942,0.011267,0.294605,-0.080315,0.089224,0.374890,-0.166759,0.210968,0.630804,-0.217672,0.118528,-0.178464,0.598934,0.065415,0.446976,0.075611,0.018776,-0.141022,-0.138967,0.040078,-0.231461,-0.180367,0.217158,0.110446,-0.420957,0.008784,0.165837,0.066272,-0.363914,0.089622,-0.285798,0.181668,0.210479,0.001574,-0.116922,0.120620,-0.101824,0.371653,-0.199624,0.256522,-0.199908,0.161980,0.433315,0.181144,-0.354278,-0.020789,-0.683775,-0.379955,-0.099778,-0.223325,-0.614827,0.003064,0.164832,0.001407,0.327505,0.494585,-0.427606,-0.390652,-0.209414,-0.027210,0.167733,-0.155679,-0.120618,-0.260907,0.103043,-0.253066,-0.334571,-0.374043,0.096110,-0.201732,0.512236,-0.643698,0.229057,0.504148,0.463923,-0.313777,0.580920,-0.169455,0.132860,-0.276883,-0.248214,0.718351,-0.090205,-0.683944,0.168824,0.139524,0.054487,0.009741,-0.303612,0.626168', '1296992', '6973376', '3001472', '6719716');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304920', '切腹', '剧情', '宽永七年德川幕府第三代将军家光时，当时由于实施中央集权，削弱了许多诸侯大名的权力，曾经叱咤一时的武士阶级很多失业沦为浪人。残酷的现实使得无所事事的浪人经常跑到诸侯家，表示要切腹自杀，而势力被削弱无力招揽更多浪人的诸侯只得用钱打发他们走，于是这成为当时流行的敲诈手段。一天井伊家来了一位名叫千千岩求女的浪人，他也提出相同要求，家臣决定将计就计，让他切腹，结果千千岩求女在极度痛苦中咬舌死去。几个月以后又有一名叫津云半四郎（仲代达矢饰）的老浪人前来要求借井伊家宝地切腹自杀。其原因也是不堪生活的困苦，井伊家老（三国连太郎饰）出面。在切腹之前，津云要求讲下自己这辈子的故事……©豆瓣', '仲代达矢', '小林正树', 9.4, 39108, 'tt0056058', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151748293.jpg', 0.2, 0.3, 3.6, 23.3, 72.6, '0.115680,0.000262,-0.347727,0.112639,-0.168374,-0.050854,0.321900,0.153515,-0.451037,-0.398676,0.378355,0.872731,0.075514,-0.055308,0.317297,-0.253126,-0.056680,-0.362603,-0.054682,-0.138532,-0.040112,-0.418541,0.193203,-0.306986,-0.368915,-0.221792,0.643273,0.095507,-0.316811,0.210393,0.265915,0.258464,0.054792,0.310264,0.057055,-0.008310,0.113451,-0.238524,-0.244876,0.106222,-0.258547,-0.309259,-0.240199,0.081903,-0.182731,0.264155,0.312693,-0.300017,-0.140049,-0.146891,0.296157,-0.260095,-0.571706,0.152353,0.505398,-0.133696,0.269005,0.237321,0.045686,-0.039770,0.095859,0.085859,-0.731842,0.057733,0.213149,-0.010896,-0.496571,0.179719,-0.024491,-0.051382,-0.049093,-0.390041,0.063168,0.393347,0.251149,0.090916,-0.294824,0.043097,-0.381808,0.426709,0.789297,0.066069,-0.187031,-0.242349,-0.079354,-0.124635,0.145365,-0.574546,-0.267455,-0.210058,0.201659,-0.164555,-0.252506,0.183339,-0.469645,-0.001233,-0.174015,-0.082366,0.345208,-0.127478,-0.043441,-0.261013,-0.207076,-0.185781,-0.079833,0.071025,0.615975,0.035021,0.927577,-0.644455,-0.101018,0.337783,0.646839,-0.652218,0.302446,0.235266,-0.024495,0.121197,-0.197713,0.071853,-0.037028,0.280793,0.062901,0.047747,-0.076260,-0.415428,-0.078026,0.048124', '27602116', '24284209', '26678784', '26711487');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304940', '蝶变', '动作', '武林在经历连番血战平静了三十年后，七十二路烽烟再起，掀起了又一轮征伐。其时有书生方红叶（刘兆铭 饰）撰写系列武林秘记《红叶手札》，专事披露武林秘史。某日，一家书店受托印制红叶手札，不想店长等人却招来杀身之祸，七十二路烽烟之十色旗主田风（黄树棠 饰）部下将杀害店长之凶手截杀。几日后，沈家堡堡主沈青（张国柱 饰）向田风求援，女侠青影子（米雪 饰）随田风等人赶至沈家堡，与先行受邀抵达的方红叶一同会见沈青。昔日兴旺的沈家堡已人去堡空，原来沈青幼年时，沈家受了杀人蝴蝶的诅咒，如今诅咒兑现，杀人蝴蝶潜入沈家堡各处行凶。田风等人出于江湖道义留下探究蝴蝶杀人之根由，却不知陷入了沈家堡与天雷堡的一场隐秘仇怨……©豆瓣', '刘兆铭', '徐克', 7.3, 6892, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2288156576.jpg', 0.5, 3.4, 37.8, 48.2, 10.2, '-0.104359,0.118747,-0.468607,0.296975,0.474963,0.040905,0.336511,0.264394,-0.490053,-0.428914,0.308827,0.419097,-0.014380,0.201423,0.185241,-0.115778,-0.017719,-0.607100,-0.042608,-0.556189,0.051585,0.101060,0.085225,-0.187148,0.174760,-0.082640,0.222704,0.632072,-0.242544,0.462078,-0.019380,0.153218,-0.622354,0.246302,-0.174812,0.111154,-0.074432,0.279728,-0.404429,-0.092433,-0.291702,-0.439255,-0.399474,0.013106,0.128693,0.423799,0.716195,-0.217719,-0.041843,-0.401674,-0.102497,-0.085244,0.186394,0.074100,0.617635,-0.174662,0.095661,0.472390,-0.104851,-0.517285,-0.267056,-0.000866,-0.312652,0.143681,0.489947,0.100420,-0.362787,0.427755,-0.420227,0.221339,-0.459125,-0.104556,0.095917,0.297543,0.378198,-0.269537,0.277377,-0.108757,-0.464872,0.454582,0.614531,-0.136874,0.194477,-0.331371,0.437255,-0.020977,0.261456,-0.084812,-0.058346,-0.160585,0.770452,-0.298628,0.218127,0.280148,-0.502514,-0.166064,-0.534106,0.067050,0.204926,-0.246442,-0.088853,-0.653853,-0.085540,0.029442,-0.202140,0.111471,0.387125,0.139945,0.323598,-0.491063,0.253891,-0.019974,0.104865,-0.631738,0.214469,-0.288701,-0.039343,-0.087578,0.033296,0.134582,0.436467,0.611514,0.289584,-0.093416,-0.160867,-0.174827,-0.078738,-0.108616', '1306490', '1292846', '26661191', '1301283');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304942', '两小无猜', '剧情', '这是一个纯真美好的初恋故事。丹尼尔（马克·莱斯特 Mark Lester 饰）是英国某小学的一名学童，家境殷实的他乖巧听话，同时也有叛逆的一面。他最好的朋友昂肖（杰克·瓦尔德 Jack Wild 饰），是一个叛逆乖张、专门捣蛋的小孩，丹尼尔和昂肖度过了许多个美好的放学时光。天真可爱的美乐蒂（特雷西·海德 Tracy Hyde 饰）跟丹尼尔同一所小学，原来并没有交集的二人，因为某一天在舞蹈室偶遇而相识，丹尼尔爱上了那个翩翩起舞的美乐蒂。在昂肖的帮助下，渐渐地，美乐蒂也喜欢上丹尼尔。二人不仅放学后约会，更有一次翘课去了海边玩耍。因此被老师家长知道他们的恋情，在大人们的多番教育下，他们却更加坚定要结婚。一天，丹尼尔的妈妈看到他留下的字条，校长发现班上的同学都不见了，原来同学们都去举行丹尼尔和美乐蒂的婚礼了……©豆瓣', '马克·莱斯特', '瓦里丝·侯赛因', 8.5, 42467, 'tt0067418', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1132971627.jpg', 0.2, 1, 13.4, 42.6, 42.7, '0.564106,-0.232681,-0.572497,0.603370,-0.306779,-0.525475,0.886423,0.009378,-0.310748,-0.283319,0.121362,0.840267,-0.265813,0.701350,0.216776,-0.036958,-0.276569,-0.612236,0.068123,-0.182289,-0.188311,-0.514270,-0.114872,0.026245,0.099660,-0.142934,0.335365,-0.214949,0.182490,0.860588,0.293033,-0.056301,0.087302,0.376244,-0.395532,0.073937,0.070814,0.250039,-0.017732,-0.022074,0.112695,-0.028510,-0.282875,-0.053665,0.192157,0.269343,0.727241,0.011608,-0.233213,-0.016399,0.470066,-0.082118,-0.034358,0.393129,0.392037,-0.018418,0.300157,0.087317,-0.114333,0.093026,-0.063170,-0.064897,-0.481103,0.175760,0.027607,0.147869,-0.421579,0.749502,0.172994,-0.168427,0.247933,-0.558415,0.085826,0.523051,0.078044,0.410408,-0.181986,0.104046,-0.419748,0.166058,0.799649,0.058703,-0.174715,0.478427,-0.319818,-0.269898,0.173258,0.011888,-0.707175,0.163590,0.304022,-0.229084,-0.281345,0.146920,-0.762336,-0.021056,-0.105643,-0.104075,-0.076263,-0.524483,-0.146318,-0.620884,0.001395,-0.473521,-0.513837,0.178488,-0.080546,-0.256935,1.101985,-1.061890,0.275754,0.580683,0.354905,-0.481254,0.843251,0.416880,0.051330,-0.034903,-0.073398,0.235509,0.061478,0.286670,-0.020510,0.716397,0.063684,-0.163834,-0.594204,0.471740', '1292219', '25922902', '1292720', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304961', '缘份', '剧情', '在新开通的地下铁中，青年陈保罗（张国荣 饰）对同车的莫妮卡（张曼玉 饰）一见钟情，不幸却被另一名乘客安妮（梅艳芳 饰）趁机捉弄。这几位年轻人很快散落在茫茫人海中，职场新丁陈保罗开始为工作奔忙，莫妮卡则为了厘清和上司的一段旧情而心神不宁。某日，保罗与莫妮卡再次相遇，而富家小姐安妮亦再度出现，半捉弄半挑逗地缠上了保罗。莫妮卡找到新工作，遭遇了好色新领导的骚扰，保罗则在安妮的暗中帮衬下正式追求莫妮卡，与后者的好色上司连番交手。莫妮卡考虑接受保罗的爱意但终于退缩，声称将他们的爱情交付给一场地铁中的缘分游戏。在离乱的人流中，保罗和安妮一起，去找寻消失的莫妮卡……©豆瓣', '张国荣', '黄泰来', 7.2, 25690, 'tt0086950', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2325329438.jpg', 1, 6.4, 41.6, 32.9, 18.1, '0.433145,0.153087,-0.645005,0.488143,-0.109680,-0.512646,0.755256,0.017683,-0.359231,-0.162042,0.299075,0.625341,-0.454193,0.315868,0.483339,-0.236458,-0.487211,-0.789801,-0.039901,0.012612,-0.286852,-0.474197,-0.197206,-0.133859,-0.224134,0.015409,0.648919,-0.021792,-0.118347,0.699118,0.433025,0.251420,-0.098203,0.510884,0.037654,0.081647,0.090855,0.103495,-0.309586,0.146688,0.169175,-0.563553,-0.055422,-0.031439,0.086905,0.384940,0.714406,-0.173279,0.245375,-0.053371,0.278739,-0.159146,0.229009,0.130039,0.298451,0.125265,0.222917,0.034375,-0.228853,-0.017697,-0.101610,0.053236,-0.477425,0.097151,0.025643,0.202387,-0.408799,0.329842,-0.053401,0.100384,0.107478,-0.213477,0.053081,0.358700,0.339014,0.242632,-0.099754,0.145719,-0.097691,0.000958,0.417265,0.204858,0.017808,0.198118,-0.063224,-0.231554,0.136107,0.183079,-0.507036,-0.370063,0.343899,0.022086,0.116872,0.313821,-0.702984,-0.087639,-0.222466,0.026615,-0.136409,-0.376409,-0.106553,-0.793121,-0.091355,-0.465824,-0.174721,0.058885,0.225510,-0.236950,0.432804,-0.829741,0.207414,0.553619,0.310216,-0.344624,0.584877,0.214309,0.395445,-0.269517,-0.162915,0.384971,-0.015124,0.142305,0.193327,0.322430,-0.186392,0.119450,-0.420565,0.336791', '20274039', '1292050', '3326747', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304970', '猫的报恩', '喜剧', '吉冈春（池胁千鹤 配音）是一个普普通通同时又有些迷糊的女高中生，某天放学的路上，她偶然救下了一只险些丧生车轮之下的小猫，谁曾想小猫竟然直立起来以人类的方式对女孩表示感谢。小春更想不到的是，她不经意的善举改变了自己的命运。原来小猫是猫王国的王子，为了报答小春的恩情，猫王国举国上下展开了令人啼笑皆非的报恩行动，只不过它们视为“上品”的老鼠令小春哭笑不得。不久后，小春接受王国的邀请前去做客，期间竟稀里糊涂答应成为王子的妃子。女孩眼看就彻底变成了一只猫，神秘的男爵（袴田吉彦 配音）成为她的救命稻草……本片亦被视为《侧耳倾听》的番外篇。©豆瓣', '池胁千鹤', '森田宏幸', 8.2, 201462, 'tt0347618', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453858009.jpg', 0.2, 1.3, 19.6, 47.1, 31.9, '0.218032,-0.024552,-0.454671,0.435770,-0.051150,-0.158099,0.424339,0.084223,-0.274343,-0.127355,0.609337,0.696518,-0.340977,0.125446,0.289077,0.097492,0.060888,-0.522503,-0.106814,0.033701,-0.054923,0.041834,-0.284890,-0.184228,-0.136097,-0.135002,0.628690,-0.254763,-0.081915,0.491303,0.241507,0.277396,-0.028237,0.287092,-0.183951,0.197401,0.101090,0.183771,0.138269,0.107473,-0.243274,-0.037253,-0.064986,0.252831,-0.415263,0.257328,0.514381,-0.768553,-0.128788,-0.446969,0.384385,-0.490027,0.007561,0.168312,0.363980,-0.004073,0.381083,-0.232149,-0.074525,-0.091974,0.376399,0.040882,-0.645619,0.193693,0.136577,0.126174,-0.357292,0.162338,0.065974,0.202216,0.241106,-0.380281,0.022146,0.219205,0.424582,0.408542,-0.113049,0.214679,-0.368527,0.020412,0.496335,0.026248,-0.373355,0.226961,-0.106471,-0.406459,0.339648,-0.259097,-0.312642,-0.040585,0.175000,-0.041408,-0.285850,0.252887,-0.643744,-0.213898,-0.500483,0.033835,0.238182,-0.526334,-0.150278,-0.108558,0.251221,-0.233188,-0.094656,-0.011466,0.480034,-0.417208,0.591486,-0.880376,0.194044,0.715832,0.090349,-0.159469,0.544127,-0.096149,-0.193664,-0.165327,0.068137,-0.012959,0.183312,0.262936,0.346992,0.230224,0.086709,-0.041436,-0.362956,0.340497', '3213270', '26759819', '1420088', '1305071');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304972', '太极旗飘扬', '剧情', '李镇泰（张东健饰）是生活在汉城的一个修鞋匠，一家人的生计就从修补鞋子的费用维持。虽然物质并不富裕，这却是一个十分温馨完整的家庭。妻子李英顺（李恩珠饰）和母亲开一间面馆，平日还要照顾下面的弟妹，弟弟李镇锡（元彬饰）是家中所有的希望，如今正在高中读书，考上大学是他的梦想，更是哥哥镇泰的寄托所在。然而随着1950年朝鲜战争突然爆发，平静的生活很快被打乱。战火蔓延汉城，镇泰决定带着家人到大邱去生活，躲避战乱。但在中途，他们却被强行征入军队，押上了开往洛东江前线的列车。从此一家人四分五裂。而在战场上的镇泰只剩下一个愿望：不顾一切用生命保护弟弟，当听说只要获得国家勋章就可以让弟弟免役时，他便疯子般冲在战斗最前沿。然而残酷的战场加上弄人的命运，他们的生命轨迹发生了无可避免的改变。©豆瓣', '张东健', '姜帝圭', 8.3, 82165, 'tt0386064', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p480212560.jpg', 0.7, 1.5, 15.5, 45.9, 36.5, '-0.037355,0.026701,-0.550673,0.537345,-0.128512,-0.305990,0.633096,0.306134,-0.374029,-0.117317,0.192349,0.685113,0.216137,0.213841,0.150606,-0.063892,-0.246259,-0.619420,0.060999,0.001886,-0.408127,-0.185091,0.070948,-0.281859,-0.095488,-0.274034,0.775190,0.329642,-0.069537,0.366666,0.002246,0.109538,-0.170059,0.563364,-0.429557,-0.067519,-0.332659,0.192728,-0.399340,0.054995,-0.103258,-0.159887,-0.072656,0.111714,0.173936,0.206895,0.889588,-0.079082,-0.028929,0.003086,0.146186,-0.221757,-0.145735,-0.051884,0.139839,-0.064320,0.036490,0.084112,-0.178115,-0.039670,-0.075185,-0.264724,-0.670024,-0.199143,0.140180,0.013948,-0.686142,0.709878,0.182909,0.069428,0.045111,-0.294402,0.249562,0.534676,-0.052071,0.450475,-0.530015,0.129297,-0.586287,0.323216,0.782789,-0.311231,-0.307695,0.450248,-0.344789,-0.197453,0.022650,-0.285043,-0.504214,-0.056713,0.062912,0.079278,-0.147855,0.185673,-0.442397,0.007950,-0.274102,-0.366932,0.338668,-0.486337,-0.025081,-0.459816,-0.043348,-0.341886,-0.309170,0.299009,-0.002982,-0.087790,0.750517,-0.700044,0.162856,0.392736,0.361376,-0.473877,0.603327,0.115582,0.316409,-0.241602,0.122530,0.236087,0.012855,0.464221,0.038869,0.198355,-0.162959,0.069983,-0.313017,0.784372', '10773239', '26021055', '1652618', '26418093');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304977', '贱精先生', '喜剧', '张俊辉（陈奕迅饰）是一个颇有成就的智能家居的设计师，为了能够赚到更多的钱，升上更高的职位，常常忽略了家人，除了跟公司内对手“歌师奶”（卢巧音饰）每天针锋相对以外，他更是一个自私自利，作风十分讨厌的贱精。他小时候便有一个小情人叫阿娇（钟欣桐饰），两人在一次意外车祸中重逢了。原来阿娇完成他们儿时当消防员的梦想，以助人为乐为己任。阿辉因为车祸得到了一种能读懂人心灵的力量，让他也感受下别人的痛苦，感同身受之后，他也对自己以前的种种行为感到内疚。他无意中发现了公司的一个大计划，并打算卖给一间韩国公司，就算阿娇如何屡劝未果，便决定离开，阿辉奋力追回她之际，为了救人，阿辉冲进了火场……©豆瓣', '陈奕迅', '关信辉', 6.4, 12003, 'tt0347230', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1657531262.jpg', 2.4, 13.4, 55.3, 21.6, 7.3, '0.065884,0.105895,-0.586956,0.688957,-0.331630,-0.401513,0.733252,-0.043305,-0.565700,-0.299330,0.057130,0.853770,-0.061680,0.178380,-0.072845,-0.048089,0.009298,-0.506681,0.016247,-0.082796,-0.143712,-0.310743,-0.233585,-0.218347,-0.354051,-0.012272,0.394926,0.144238,-0.146083,0.315182,0.395748,0.142794,0.021342,0.644739,-0.047979,0.036667,-0.116323,0.203330,-0.203988,0.103009,0.220384,-0.079180,-0.139384,0.260433,-0.071629,0.211014,0.542174,-0.069387,-0.410911,-0.186828,0.307856,-0.095275,0.010224,0.052357,-0.106898,-0.043629,0.391303,0.046247,-0.330932,0.150983,0.052020,0.104195,-0.961610,0.069859,-0.035503,-0.193557,-0.465399,0.263420,-0.066116,0.055582,0.248480,-0.355523,0.067441,0.244636,0.330576,0.392860,-0.519207,-0.074954,-0.480356,0.111872,0.777213,-0.188965,0.016395,0.642623,-0.177094,-0.241736,0.061203,-0.180448,-0.338143,0.144593,0.260642,0.166102,-0.242687,-0.005013,-0.373812,-0.039974,-0.204287,-0.091179,-0.162328,-0.564054,0.177402,-0.124141,-0.081912,-0.142474,-0.352854,0.068421,0.212127,-0.537945,0.535025,-0.788256,0.094062,0.530163,0.449400,-0.671656,0.523211,0.169979,0.027290,-0.168561,-0.124262,0.130610,-0.053122,0.141295,0.045356,0.260917,-0.085656,-0.325068,-0.344402,0.425539', '26678784', '1793491', '30163500', '1299649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304981', '半梦半醒的人生', '剧情', '青年学生维利•维金斯（Wiley Wiggins 饰）童年时曾从小伙伴那里得到这样一个预言：“梦即命运”。长大后，他在恍恍惚惚间来到了一座陌生的城市。维利走街串巷，经历各种各样的神奇体验，仿佛穿梭于不同的梦中。在此期间，他还遇到了各色人等：从开着船形汽车的司机到大学教授，从性感的金发美女到癫狂的眼睛男，从引火自焚的金发男子再到留着雷鬼头的四人团体……每个人都喋喋不休，谈论着人生、理想和哲学。而维利不发一言，俨然一个极具耐心的聆听者。本片由导演兼编剧理查德•林克莱特（Richard Linklater）采用DV真人拍摄，并用软件将其“动画化”。导演史蒂文•索德伯格（Steven Soderbergh）亦在片中出现。©豆瓣', '伊桑·霍克', '理查德·林克莱特', 8.1, 10865, 'tt0243017', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2193559859.jpg', 1.1, 3.8, 18.9, 38.9, 37.2, '0.130773,0.016506,-0.679445,0.635929,0.029660,-0.292967,0.961721,0.276288,-0.480188,-0.087665,0.219859,0.562269,-0.393860,0.298570,0.744460,-0.192595,-0.360495,-0.593584,-0.186502,0.108714,-0.169638,-0.324650,-0.053663,-0.152658,-0.150035,-0.572343,0.614839,-0.131484,-0.235264,0.126005,0.217283,0.125272,-0.335160,0.278195,-0.312436,0.101929,0.168718,0.176934,-0.077125,0.270137,-0.003384,-0.175348,-0.260598,-0.145877,-0.365237,0.125478,0.785768,-0.411593,-0.188361,0.355497,0.455741,0.013024,-0.056466,0.060011,0.092081,0.075416,0.087314,-0.194575,0.019337,0.086963,0.106851,-0.094113,-0.454195,-0.136684,-0.033016,0.420296,-0.499610,0.383654,0.041898,-0.021562,0.113827,-0.326615,0.041580,0.033060,0.349466,0.363420,0.039677,0.127349,-0.347282,0.542193,0.371266,0.361483,-0.472681,0.271582,-0.149829,-0.599572,-0.376375,0.070335,-0.638796,-0.065370,0.342789,-0.102321,-0.211907,0.165219,-0.597876,-0.024975,0.052726,-0.033538,-0.054970,-0.199561,-0.448488,-0.823919,0.113778,-0.230509,-0.045254,0.228349,0.025861,-0.237547,0.734264,-0.729915,0.228237,0.429914,-0.016036,0.149182,0.747382,-0.417735,0.176559,-0.357421,-0.362103,0.356488,0.275653,0.407125,0.142537,0.632508,-0.301316,0.094063,-0.359779,0.353008', '1467779', '10466639', '1322847', '4233625');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1304989', '爱君如梦', '爱情', '阿华（刘德华）是社交舞教师，他舞台上温文尔雅似君子，生活中却是十足的刻薄小人，跳舞对他渐成发家致富的手段，而无其它层面上的意义。阿金（吴君如）是舞会公司普通女侍应，因自知条件平常，虽过着繁忙劳碌的生活却并无怨言。阿华在某名媛舞会上以翩翩风度搭上了名媛Tina（梅艳芳），同时，他的潇洒帅气也吸引了同在舞会上的阿金的目光。翌日，阿金来到阿华任教的 “舞之林”学跳舞，却被阿华当作“肥羊”趁机骗财，阿金虽知他的心思，却也甘心上当，直到一片真心遭遇侮辱才羞怒而去，而此时的阿华，其实已在不知不觉间爱上了这个倔强痴情女子。©豆瓣', '刘德华', '刘伟强', 6.7, 17005, 'tt0306708', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1423780174.jpg', 1.1, 7.7, 54.9, 28.3, 8, '0.410469,0.263362,-0.631303,0.402459,-0.232928,-0.318014,1.011989,0.169916,-0.331417,0.053852,0.288658,0.523370,-0.029616,0.337891,0.136984,0.010605,-0.112028,-0.627830,-0.139115,-0.049701,0.058464,-0.289767,-0.108703,0.029322,-0.228115,-0.193984,0.318314,-0.007841,-0.179210,0.661606,0.446716,0.014100,0.029289,0.589308,-0.085759,-0.203846,-0.093530,0.288570,-0.030452,-0.006035,-0.111337,-0.434236,-0.299233,0.131643,-0.066439,0.519668,0.644855,-0.033685,-0.155416,-0.053213,0.383850,-0.183992,0.044536,0.231707,0.066667,-0.131098,0.179836,-0.036400,0.140703,-0.116310,-0.001157,-0.102632,-0.469555,0.115131,0.038739,0.309328,-0.390287,0.831508,-0.131597,-0.271490,-0.250361,-0.239392,0.011082,-0.385389,0.152663,0.205895,0.158939,0.233077,-0.286621,0.306402,0.583027,0.555963,-0.325207,0.541627,-0.443263,-0.371215,0.194928,-0.319548,-0.398403,-0.341439,0.127722,-0.041398,-0.146690,0.042937,-0.314188,0.259476,0.074048,0.164955,-0.113696,-0.318469,-0.065283,-0.511620,0.014192,-0.771302,-0.430135,-0.060883,0.264039,-0.212037,0.659750,-0.995850,0.145931,0.525361,0.244369,-0.237741,0.798831,0.194897,-0.109255,0.142264,-0.352155,0.208959,-0.088256,0.159291,-0.025818,0.314308,-0.166123,-0.115904,-0.315135,0.608899', '1307561', '1308755', '24839498', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305003', '杀手悲歌', '剧情', '这是导演的成名之作，罗伯特自掏腰包拍了这部低成本的黑色电影，结果一炮而红。影片讲述的是一名心狠手辣的罪犯成功越狱后，来到小镇伺机找他的仇家报仇，仇家的手下只知道那个罪犯将武器藏在吉他盒子里随身携带，而从来都没有见过他本人。一名流浪的吉他手（卡洛斯•加拉尔多 Carlos Gallardo 饰）凑巧这时来到小镇谋生，于是，莫名其妙的他就被卷入了一场不知所谓的追杀中。追杀的场面被导演演绎的笑料百出，黑色幽默表现的淋漓尽致。©豆瓣', 'Carlos Gallardo', '罗伯特·罗德里格兹', 7.4, 10076, 'tt0104815', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2576194287.jpg', 0.9, 4.3, 34.7, 44.5, 15.6, '0.283604,-0.216114,-0.527396,0.514587,-0.116653,-0.015402,0.900647,0.001215,-0.351171,-0.131537,0.398782,0.739284,-0.330743,0.083940,0.355755,-0.180420,-0.174627,-0.802499,-0.071614,-0.287929,-0.018077,-0.097996,-0.471313,-0.165180,-0.178212,-0.205268,0.585981,0.013646,-0.481733,0.345851,0.593004,0.191771,-0.112658,0.443101,-0.292322,0.200400,0.204384,-0.044326,0.115490,0.309444,-0.065279,-0.532258,-0.169802,0.109649,-0.214399,0.450467,0.710184,-0.170072,0.087121,0.060959,0.402635,-0.433867,-0.120439,0.073495,0.233928,0.117842,0.213143,0.123806,-0.128963,0.137089,0.068040,-0.195773,-1.131705,0.142232,0.034033,0.067319,-0.691579,0.272774,-0.114877,0.065527,0.068167,-0.134000,0.418378,0.004850,0.489128,0.141899,0.199407,0.062316,-0.498910,0.622221,0.538435,-0.326586,-0.080493,0.480276,0.153832,-0.238897,0.134835,-0.499338,-0.500997,0.091141,0.575080,-0.283915,-0.206787,-0.203703,-0.551187,-0.005158,-0.299340,-0.138740,-0.018594,-0.196589,-0.444798,-0.725373,-0.257070,-0.139804,-0.133389,-0.055083,-0.179736,-0.210886,0.610515,-0.498985,0.031648,0.424223,-0.096150,-0.349860,0.651773,0.051537,-0.132053,0.200670,-0.148622,0.074412,0.338125,0.464068,0.120118,0.357598,0.097005,-0.500946,-0.271144,0.310122', '3318306', '25928048', '34890458', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305010', '埃及艳后的任务', '喜剧', '埃及艳后的皇宫内，凯撒（Alain Chabat 亚伦·夏巴饰）公然嘲讽埃及人的堕落，忿忿的克丽奥佩特拉（Monica Bellucci 莫妮卡·贝鲁齐饰）于是和他立下赌誓，骄傲的艳后夸下海口，说3个月就能造出一座豪华宫殿，以此来证明埃及人民的智慧。这个任务派到设计师依尔维斯（Jamel Debbouze 加梅勒·杜布兹饰）的头上，他被命令在3个月内造出华宫，无法按时完成的话就要被喂鳄鱼。面对这个不可能的任务——走投无路的依尔维斯找到旧相识：高卢的魔法师，和魔法师的好朋友阿斯特瑞克斯、欧贝里克斯四人一起来到埃及。在魔法力量的帮助下，工程有条不紊地飞速进行。可是，艳后的祭祀阿蒙格菲斯却不断从中作梗，艳后的任务能如期完成吗？©豆瓣', '热拉尔·德帕迪约', '阿兰·夏巴', 7.1, 12745, 'tt0250223', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p840379775.jpg', 1.5, 7.4, 41.4, 36, 13.7, '0.474869,0.276012,-0.516112,0.773855,-0.164804,-0.342775,0.400817,-0.010205,-0.294647,-0.106233,0.523697,0.693212,-0.007442,-0.210317,0.288335,0.240829,-0.617199,-0.426730,0.088906,-0.254122,-0.179227,-0.648352,-0.089352,-0.273074,-0.161299,-0.375224,0.351036,-0.089846,0.300800,0.124058,0.120891,0.370176,0.205796,0.101902,-0.195043,-0.058661,0.388434,-0.442209,0.002811,0.623709,-0.007192,0.022786,-0.066454,0.192872,0.080024,0.091737,0.270450,-0.427118,0.186584,-0.167260,0.466190,-0.451315,0.283840,0.321630,0.194201,-0.141858,0.040531,0.026945,-0.090252,-0.214888,0.168165,-0.378370,-0.838248,0.037213,-0.141863,0.179228,-0.570904,0.440522,-0.263175,0.043397,0.153900,-0.464564,0.062401,0.369816,0.280813,0.537006,-0.307891,0.053965,-0.703965,-0.025072,0.413582,-0.112487,-0.329587,-0.017336,0.062319,-0.617029,-0.092226,-0.189520,-0.246051,-0.148690,0.245493,-0.013171,0.047127,0.184115,-0.833499,-0.087425,-0.672299,-0.131003,-0.036297,-0.357298,-0.027898,-0.737994,-0.017963,-0.180937,-0.068425,0.258949,0.415802,-0.144401,0.415824,-0.781431,0.308533,0.539380,0.609608,-0.190144,0.456593,0.050513,0.157988,-0.057035,-0.241863,0.428534,0.074572,0.539718,0.208899,0.620486,0.411303,-0.092375,-0.289672,0.379184', '1793491', '1420088', '24750460', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305016', '神勇飞虎霸王花', '喜剧', 'Amy（吴君如 饰）荣立功勋将Madam胡（胡慧中 饰）肆意整治，醒来后却发现是南柯一梦……霸王花队伍迎来了Susanna（叶子楣 饰）、Joey（罗美薇 饰）等新鲜血液，Amy与May（惠英红 饰）众人怎能放过拿新人寻开心的好机会？于是霸王花营地一时剑拔弩张，后经互相了解终于一致决定为Madam胡筹办生日宴会。飞虎队简Sir（冯淬帆 饰）对Madam胡一往情深，可惜嘴拙舌笨一直落于竞争者卢Sir（黄锦燊 饰）之后，这次生日宴自然是表现的大好机会，以阿南（楼南光 饰）为首的一班飞虎队亦对此次聚会兴致勃勃，搞出笑料连场。不久国际恐怖分子金毛狮一伙赴港搭救同伙，霸王花与飞虎队联袂出击，而简Sir终于在这次行动中迎来了自己的爱情……©豆瓣', '胡慧中', '钱升玮', 6.9, 7636, 'tt0098312', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2162153613.jpg', 0.7, 5.6, 53.1, 29.5, 11.2, '-0.268875,0.138948,-0.670535,0.508332,0.129754,-0.236233,0.239258,-0.075328,-0.511368,-0.232445,-0.163579,0.291462,-0.550355,0.258312,0.510997,-0.449607,-0.050442,-0.723328,-0.176193,0.007000,-0.284747,-0.243561,0.140967,-0.241938,0.026579,0.173422,0.103717,0.322897,-0.149217,0.760195,0.944608,0.180369,-0.147673,0.455951,0.128300,-0.274963,0.158552,0.225444,-0.380207,0.072559,-0.039157,-0.454089,-0.256093,0.034640,0.218991,0.245683,0.723733,-0.238087,-0.033237,-0.394829,0.072817,-0.219338,0.232670,-0.004536,0.422936,0.078203,0.213966,-0.077392,0.060317,0.251613,0.102027,-0.302290,-0.292345,0.190092,0.170683,-0.196283,-0.427746,0.218219,-0.101641,0.035718,-0.055274,-0.025531,0.259926,0.530356,0.677620,-0.190975,0.131854,0.204471,-0.316837,0.189974,0.429926,0.151450,0.180800,0.035806,0.122505,-0.673438,0.248238,0.054880,-0.064838,0.099028,0.301190,0.036938,0.327026,-0.156109,-0.418663,-0.457062,-0.210280,0.073035,0.277738,-0.257270,0.099931,-0.664877,0.023531,-0.310837,-0.295458,0.338388,-0.057976,-0.051786,0.379557,-0.576901,-0.121851,-0.020390,0.041865,-0.530640,0.409464,0.061827,0.129975,-0.304402,0.126636,-0.110160,0.069635,-0.046679,0.326459,0.121449,-0.194034,-0.333506,-0.024605,-0.125504', '3654340', '1432699', '5954505', '25856453');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305034', '红樱桃', '剧情', '1940年的冬天，中国孤儿楚楚（郭柯宇）和罗小蛮（徐啸力）被送入莫斯科近郊的伊万诺夫国际儿童院学习。课堂上，当楚楚讲述自己亲眼目睹父亲惨遭法西斯刽子手杀害的情景时，老师和同学都震惊不已，随后，她和罗小蛮过上一段相对平静的日子，两人后来因夏令营分头去了不同城市。德军入侵莫斯科令楚楚又一次亲眼目睹死亡，而她自己也被德军抓住，落入一个有在女性人体上纹身作画癖好的德国将军之手，噩梦自此不断，罗小蛮则在后方当上了递送阵亡通知的“黑色信使”。©豆瓣', '郭柯宇', '叶大鹰', 7.6, 33034, 'tt0114243', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2633679620.jpg', 0.6, 2.4, 31.7, 47.9, 17.4, '0.483533,-0.004043,-0.572241,0.438362,0.154555,-0.266879,0.715897,-0.079327,-0.601184,-0.123806,0.325944,0.681322,-0.252435,0.217708,0.163294,-0.105161,-0.292863,-0.781420,-0.211926,-0.253222,-0.406688,-0.288016,-0.166730,-0.162781,0.066534,-0.411555,0.478120,-0.325884,-0.170504,0.751547,0.162272,0.348264,-0.110082,0.487513,-0.096556,0.073348,0.202694,-0.031826,-0.255445,0.150429,-0.060768,-0.467102,-0.128320,0.116136,-0.232094,0.307981,0.981307,-0.066017,-0.032112,-0.409557,0.222402,-0.234088,-0.073096,0.092891,0.524533,0.216743,0.228963,0.285445,-0.189891,-0.081234,-0.111927,-0.013429,-0.230678,-0.060590,0.212179,-0.004599,-0.400142,0.466188,-0.016000,0.250312,0.147692,-0.498875,0.298884,0.464853,0.133335,0.487590,-0.224951,-0.095497,-0.326486,0.457891,0.800656,-0.076117,-0.075141,0.000813,-0.076722,-0.348109,0.247379,-0.247031,-0.400227,0.292015,0.207768,-0.093157,-0.245561,0.411569,-0.552085,0.083872,-0.449625,-0.288214,-0.165096,-0.206855,-0.210737,-0.616562,-0.104923,-0.215503,-0.383011,0.043726,0.012816,0.051727,0.732002,-0.626421,0.347698,0.301523,0.313041,-0.097275,0.541256,0.158404,0.014471,-0.138363,-0.127024,0.369478,0.093400,0.496504,-0.029544,0.264301,-0.323368,-0.074802,-0.379214,0.426412', '3811356', '2365260', '26687241', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305046', '双瞳', '剧情', '由于两年前揭发同僚贪污，台北警官黄火土（梁家辉）被上级报复调入冷门的外事组工作，利益也曾连带受损的新同事对他怒言相向，加上妻子清芳（刘若英）受不了他长期不回家要求离婚，黄火土感觉他的世界正在逐渐四分五裂。就在此时，三宗受害者的身份并无关联的震惊了台湾社会的离奇命案发生，法医（杨贵媚）验尸发现他们都是因中一种神秘的黑霉菌产生幻觉而死，因为缺乏此方面的人才，当局从美国请来此种案例的侦办专家凯文莱特（David Morse）协助破案，黄火土重被任用。随着一桩令所有人都目瞪口呆的事实的被发现，一场围绕政治利益与民众利益的斗争也在黄火土和办案伙伴李丰博（戴立忍）及整个警察队伍之间展开。©豆瓣', '梁家辉', '陈国富', 7.7, 121054, 'tt0284066', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2185662998.jpg', 0.7, 3.5, 27.5, 47.3, 20.9, '0.319022,-0.248588,-0.710136,0.367702,-0.092592,0.037576,0.699339,0.178728,-0.732254,-0.302056,0.239314,0.601391,-0.294480,-0.065868,0.205369,-0.295007,-0.154428,-0.779059,-0.099828,-0.113763,-0.124741,-0.581780,-0.123053,-0.296354,-0.285917,-0.296320,0.710999,0.054755,-0.387784,0.364642,0.174194,0.242418,-0.179204,0.592677,0.286629,-0.109743,0.185233,0.072030,-0.402385,-0.087533,0.182084,-0.330126,-0.017071,0.207231,-0.132578,0.347855,0.503636,-0.112520,-0.305432,-0.186732,0.414905,-0.463175,-0.102151,0.094294,0.640734,0.173260,0.074835,0.509541,-0.153173,-0.142069,-0.020225,0.284846,-0.699056,-0.038807,0.267041,0.343678,-0.295861,0.549957,-0.152452,-0.077462,-0.149117,-0.062934,0.260614,0.543754,0.268101,0.390543,-0.163221,0.045817,-0.370737,0.147617,0.713942,-0.094047,-0.244346,0.027171,-0.413816,-0.420237,-0.023565,-0.161519,-0.179291,-0.083065,0.121600,-0.018254,-0.220077,0.444491,-0.408184,-0.000858,-0.138552,-0.293507,-0.090781,-0.264063,0.161535,-0.527206,-0.325724,-0.272291,-0.209502,0.064462,0.343845,-0.191929,0.584875,-0.641073,-0.013051,0.409760,0.393768,-0.659202,0.465513,0.185125,0.096750,-0.350461,-0.338735,-0.013277,0.274488,0.384092,0.115470,0.038950,0.081871,-0.111746,0.015006,0.089299', '1293265', '25721544', '1301022', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305053', '红龙', '惊悚', '最近出现了一起凶徒连环杀人案，最令人恶心的是，凶徒每次作案后都将被害者的喉咙割走。FBI探员威尔（爱德华•诺顿 Edward Norton 饰）负责此案的侦察，经过详细调查，威尔分析此人每次都是将被害者的喉咙割走吃掉，然而却没有找到任何凶徒的蛛丝马迹。威尔向患有精神病的犯罪心理学家汉尼拔（安东尼•霍普金斯 Anthony Hopkins 饰）求助，希望汉尼拔能刻画出凶徒的犯罪心理以助破案。不料汉尼拔精神病发，意图伤害威尔，最后被关进了精神病监狱，此案也就不了了之。多年后，威尔又遇到了一起相同的谋杀案。虽确定了犯罪嫌疑人，但若想清楚推敲出此人的犯罪心理，以将其乘之于法，威尔只好再次找到了汉尼拔。©豆瓣', '安东尼·霍普金斯', '布莱特·拉特纳', 7.8, 112147, 'tt0289765', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1352782024.jpg', 0.2, 1.6, 25.4, 51.5, 21.3, '0.377354,-0.402387,-0.357684,0.166447,-0.141307,-0.291839,0.789797,-0.194558,-0.606688,0.000079,0.290242,0.429602,-0.230984,-0.231167,0.166794,0.162435,-0.356026,-0.831328,0.023701,-0.089410,-0.336697,-0.979686,-0.322731,-0.159964,0.201512,-0.010132,0.169782,0.167964,-0.347320,0.130988,0.099933,0.453978,-0.110444,0.368979,0.147657,-0.082860,0.177967,-0.507981,0.004908,0.374021,0.382448,-0.452124,0.082590,0.239142,-0.107679,0.695424,0.394869,-0.204504,-0.105266,0.193951,0.316520,-0.252312,-0.062339,0.186386,0.266477,0.086232,0.263066,0.553704,0.029146,-0.450935,0.144812,0.308578,-0.797119,-0.017927,-0.041102,0.397924,-0.389766,-0.045153,-0.307425,0.183164,0.117845,-0.243542,0.192417,0.232827,0.384384,0.017827,-0.152857,-0.117614,-0.536552,0.159152,0.069320,0.012879,-0.360345,-0.153880,-0.049457,-0.789648,0.277130,-0.200654,0.226220,0.171187,0.543742,0.225689,-0.479089,0.194114,-0.073541,-0.411565,-0.487610,-0.152302,-0.033788,-0.135644,-0.005645,-0.510358,-0.115210,0.106010,-0.642060,-0.244709,0.017819,-0.260223,0.065584,-0.547209,0.212197,0.763484,-0.179752,-0.355589,0.348785,0.020849,0.151941,0.288582,0.051357,0.242561,0.657163,0.712377,0.385559,0.407440,0.332351,-0.449216,-0.518589,0.100773', '25862560', '1296217', '1307442', '4132395');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305058', '精装难兄难弟', '喜剧', '王晶卫（黄子华 饰）是个九十年代前卫的香港导演，但十分轻视六十年代的粤语片。没想到他穿越时空回到了六十年代，他被大导演楚原告知，只要能在六十年代里拍一部受欢迎的电影便能回去。王晶卫虽然十分无奈，也认识了还没有成名时的李奇（罗嘉良 饰）和谢源（吴镇宇 饰）这对难兄难弟。由于王晶卫的特殊身份，便带领两人一举成名。李奇与谢源的各自的女友宝珠（张可颐 饰）与芳芳（舒淇 饰）都移情别恋钟情于王晶卫，十分倾慕他的才华。李奇与谢源得知情况后，与王晶为断绝了来往。而王晶卫所拍的电影，完全没有人欣赏，到底他又能否回到属于自己的时空呢？©豆瓣', '黄子华', '曹建南', 7.7, 13060, 'tt0285244', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2196633890.jpg', 0.7, 3.3, 29.3, 45.2, 21.6, '0.330844,-0.040686,-0.882456,0.658647,0.008332,-0.386823,0.653984,0.148763,-0.593645,-0.283929,0.177214,0.841559,-0.296369,0.109298,0.187096,0.003100,-0.373488,-0.700264,-0.010341,-0.260082,-0.191869,-0.304797,-0.585166,0.042414,-0.237176,-0.053562,0.534016,-0.004632,-0.443752,0.480593,0.431737,0.145167,0.035480,0.499084,-0.385782,0.214168,-0.147418,0.220835,-0.303956,0.151718,0.196046,-0.257930,-0.205011,0.082755,0.063673,0.418665,0.630620,-0.313027,-0.155790,0.135004,0.366979,-0.061119,-0.200137,0.241694,0.058644,0.124035,0.392172,0.152403,-0.248592,0.215705,-0.002309,0.051923,-0.723005,0.199891,0.151618,0.088298,-0.564496,0.571237,-0.104386,-0.299927,-0.064250,-0.517254,0.292456,0.258693,0.229182,0.424221,-0.069530,-0.116370,-0.470334,0.401518,0.420650,0.214206,-0.031751,0.520457,-0.030614,-0.659491,-0.363671,-0.101354,-0.502737,0.089597,0.269934,0.198270,-0.097546,-0.081838,-0.290833,0.086218,-0.144680,-0.036180,-0.133092,-0.427289,0.081503,-0.608811,-0.294919,-0.776979,-0.291361,-0.090445,0.355826,-0.166639,0.788433,-0.905791,-0.033843,-0.023611,0.275955,-0.667773,0.697373,0.287644,-0.098135,-0.177538,-0.106538,-0.089084,-0.080485,0.154354,0.164406,0.586074,0.005226,-0.506794,-0.230832,0.278752', '26354526', '1301022', '35144311', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305060', '正牌韦小宝之奉旨沟女', '喜剧', '康熙皇帝（汤镇业饰）病重，国师求法得知真命皇后尚未出现，致令龙体违和，唯今之计是命人去未来寻得真凤皇后与康熙匹配，皇上方能得救，此任务交予韦小宝（梁朝伟饰）执行，小宝遂乘坐罗刹国之高科技结晶——穿梭古今无敌浑天轮误到一九九三年的香港，并结识市井之徒亚超（张卫健饰），两人成为好友；另一方面，小宝认识小学教师霞女，对其渐生情愫，但此时以建宁公主（叶玉卿饰）为首的七位娇妻又来现代寻夫，引起连串趣事，再加上吴三桂派手下追杀小宝，以阻止他寻找皇后，小宝面对种种问题，如何决断呢？©豆瓣', '梁朝伟', '柯受良', 6.3, 23652, 'tt0108542', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167120459.jpg', 2.7, 13.8, 56.4, 20.1, 7, '0.024430,0.132163,-0.312190,0.487960,0.311649,0.083376,0.182886,0.132826,-0.573075,-0.387149,0.307037,0.356404,-0.122274,-0.049683,0.046485,-0.140220,-0.225121,-0.219475,0.240967,-0.070907,0.206412,-0.334541,-0.180106,0.147231,-0.163503,-0.168983,0.609283,-0.269105,0.032148,0.627740,0.220416,0.224781,-0.518510,0.458487,-0.098059,0.135519,-0.249973,0.069121,-0.233866,0.298548,0.108002,-0.138524,-0.264789,0.130848,-0.122607,0.182641,0.250509,-0.420626,0.215154,-0.278206,0.295758,0.013247,0.114033,0.047756,0.115626,-0.022630,0.056634,0.370403,-0.114355,0.069422,-0.153561,0.166637,-0.227792,-0.026428,0.178298,-0.106022,-0.204935,-0.372268,-0.136131,-0.192350,0.136415,-0.394813,0.191720,0.387800,0.157449,0.264258,-0.022801,0.043637,-0.366421,0.281778,0.334793,-0.194965,0.156992,-0.017696,0.379110,-0.317053,0.361985,-0.424232,-0.086412,0.031572,0.011914,0.216652,0.366627,0.195719,-0.070763,-0.055042,-0.590590,0.266785,0.281891,-0.090961,0.174825,-0.338506,-0.155343,-0.248669,-0.431747,-0.218721,0.438018,-0.301599,0.548172,-0.496870,0.068063,0.157994,0.116172,-0.826514,0.466358,0.089691,0.175216,-0.516734,-0.169396,-0.086214,-0.065494,-0.020199,-0.350769,-0.208157,0.038051,-0.155818,-0.383761,-0.314302', '1300060', '4735944', '1421278', '1294693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305065', '公主日记', '喜剧', '15岁的高中生米亚（安妮•海瑟薇 饰）与母亲生活在美国，但她十分不自信，也常常遭到同学的嘲笑。就在她16岁生日那天，她与祖母（茱莉•安德鲁 饰）见面后发现这个优雅的女士是欧洲小国吉诺维亚的女王，米亚正是这个国度的公主。刚开始米亚十分不愿，在母亲的调解下米亚的态度才有所缓 和。为了可以顺利继承王位，女王不得不对孙女进行一系列的改变，令平时生活便不拘小节的米亚十分困扰，甚至跟好朋友之间也发生了冲突。但米亚的身份被揭露了，她一下子受到了媒体的高度关注。突如其来的一切让米亚想逃避一切，幸好在父亲的日记里，她重拾了自信。米亚成为了公主，也找到了自己想要的爱情。©豆瓣', '朱莉·安德鲁斯', '盖瑞·马歇尔', 7.6, 312491, 'tt0247638', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169009638.jpg', 0.3, 2.2, 32.6, 47.5, 17.4, '0.456197,0.030993,-0.688799,0.637098,-0.198114,-0.376860,0.677699,0.028061,-0.764489,-0.272799,0.254070,0.952239,-0.367749,0.226934,0.448097,0.240444,-0.501472,-0.526488,0.024079,0.007221,-0.080235,-0.581684,-0.171041,-0.051959,-0.463903,-0.563887,0.584026,-0.229479,-0.096687,0.449876,-0.038894,0.278097,0.379415,0.632241,0.104302,-0.017567,-0.012467,-0.049792,-0.074490,0.183055,0.197989,-0.282292,-0.092716,0.775984,0.101238,0.405772,0.430136,-0.422422,-0.149039,0.011701,0.465296,-0.357582,0.128105,0.390255,0.150960,-0.231648,0.233169,0.352222,-0.347397,-0.322290,-0.035870,-0.079884,-0.511234,0.179897,0.104727,0.238202,-0.744524,0.563615,-0.303961,-0.301228,0.304319,-0.348493,0.227813,0.762103,0.223000,0.357171,-0.311927,-0.085335,-0.571466,-0.200991,0.735965,0.148897,-0.496002,0.366821,-0.420593,-0.424524,-0.024514,-0.230240,-0.639281,0.056441,-0.036629,0.062349,-0.182382,0.571545,-0.607682,-0.196409,-0.550045,-0.240433,0.246385,-0.716030,-0.043672,-0.442692,-0.362951,-0.709160,-0.553762,-0.206586,0.226339,-0.446785,0.712388,-1.278988,0.386113,0.541746,0.325999,-0.438987,0.521165,0.140727,0.033593,-0.139538,-0.051784,0.217633,-0.149977,0.271060,-0.072290,0.333652,0.328002,-0.346255,-0.243226,0.563600', '35030151', '7065238', '21766698', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305066', '亡命夺宝', '喜剧', '赌场老板（约翰·克里斯 饰）选中了六个幸运儿参加一项竞赛。他们中最早到达银城火车站的人将得到储物柜里的200万美金，而比赛的规则就是没有规则。六个人偕同各自亲友，八仙过海，各显神通。其实在这竞赛背后还有更大的赌博，几位富翁正以这些人作为他们赌博的对象。小人物为了两百万忙得不亦乐乎，大人物却正在幕后自鸣得意。然而，竞赛的最后有了戏剧性的转折。©豆瓣', '布瑞金·梅耶', '杰瑞·扎克', 7.9, 12081, 'tt0250687', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2606705418.jpg', 0.5, 2.9, 24.8, 45.8, 26.1, '0.349576,-0.039357,-0.633357,0.531694,-0.095166,-0.088630,0.627367,-0.092179,-0.553196,-0.184701,0.479495,0.748129,-0.324031,0.058662,0.345602,-0.185322,-0.258689,-0.556532,-0.393011,-0.372198,-0.396887,-0.437286,-0.167371,-0.249147,-0.107379,0.212052,0.337564,0.192292,0.009201,0.463554,0.527230,0.175147,-0.159630,0.315024,-0.223165,-0.023203,0.256209,0.040689,-0.242879,0.196704,-0.327020,-0.134318,-0.545942,0.153839,0.353174,0.536112,0.402199,-0.423844,0.112374,-0.066683,0.050178,-0.336995,-0.286250,0.019130,0.345290,0.109117,0.675510,0.094945,0.118279,0.144455,0.242539,-0.377744,-1.134499,0.180632,0.099111,0.305153,-0.229486,0.574488,-0.047371,-0.161532,0.045860,-0.015833,0.138607,0.363622,0.276625,0.068257,0.018858,-0.374181,-0.739316,0.302346,0.694623,-0.064494,-0.141372,0.235599,-0.097480,-0.520152,-0.011067,-0.630339,-0.014361,0.128675,0.476557,0.080615,0.117349,-0.075958,-0.663707,0.453773,0.243075,-0.402754,-0.089275,-0.535656,-0.110362,-0.918755,0.083712,0.013057,-0.197515,0.260300,0.252223,-0.356522,0.905649,-0.850626,0.038150,0.701190,0.163580,-0.553973,0.864730,-0.058037,0.203345,-0.467130,-0.432705,-0.550273,0.041400,0.445073,-0.031524,0.378291,-0.069885,-0.471433,-0.023158,0.517158', '1793491', '4301278', '3318306', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305067', '宇宙追缉令', '动作', '有一个这样的理论：宇宙中存在多个平行世界，而且每个平行世界里都有一个你存在，而且所有平行世界里面的自己会分摊整个宇宙中你所具备的能量。所以，只要平行世界中的你都消失了，那所有的能量将汇聚到最后的一个人身上。正是为了这个目的，夺取所有人的能量，在遥远的未来，名叫基比（李连杰 饰）的杀手穿越时空杀掉了123个平行世界中的自己，获得了超能力。而这时，世界中只剩下自己和另外一个平行世界中名叫盖伯瑞（李连杰 饰）的自己。而身处和平世界中的盖伯瑞，完全没有意识到大难临头。只是在突然的一天，发现自己速度极快、力大无穷，而且有一个和他一模一样的人在到处犯罪，作为警察的自己，必须挺身而出，阻止犯罪的同时也为了拯救自己。©豆瓣', '李连杰', '黄毅瑜', 6.2, 30953, 'tt0267804', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199459919.jpg', 2.6, 15.6, 55.7, 20, 6.1, '0.285153,0.588783,-1.136631,0.883290,-0.666318,0.146024,0.972830,-0.220942,-0.485925,-0.277335,0.041552,1.122698,0.063219,0.224719,0.136123,0.176531,0.085035,-0.893533,-0.265147,-0.512617,-0.901068,-0.601150,-0.727379,-0.208965,-0.286244,-0.334787,0.731497,0.219229,-0.145792,0.069805,0.108537,0.061710,-0.177701,0.813400,-0.347539,0.001961,0.063792,-0.051226,-0.112365,0.467459,-0.225976,0.076274,0.277478,0.495645,-0.695418,0.323307,0.781712,-0.818130,0.160757,-0.251576,0.498364,-0.295673,-0.406465,-0.081071,0.245780,-0.181826,0.341364,0.013374,-0.221381,0.165458,0.176804,-0.040882,-1.294472,-0.314491,0.207611,0.294852,-0.399741,0.145832,0.283274,-0.485928,0.048730,-0.121284,0.517103,0.189355,0.588896,0.464305,-0.552677,-0.314356,-0.553034,-0.142500,0.700628,-0.166653,-0.702749,0.531557,-0.316381,-0.287050,-0.446935,-0.128200,-0.366509,-0.203700,0.088631,0.359637,-0.223289,0.225383,-0.855090,0.424498,0.094241,-0.181164,-0.292828,-0.563282,-0.239402,-0.171432,-0.246952,-0.385594,-0.066422,0.253503,0.019650,-0.424912,0.912097,-0.910416,0.086679,0.694960,0.468184,-0.421109,1.073942,0.018836,0.301145,-0.496791,0.082419,0.094044,0.137494,0.492209,-0.150330,0.467253,-0.134009,0.147760,-0.630937,0.986372', '25932086', '25928048', '1308585', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305068', '美国派2', '喜剧', '在经历了高中毕业晚会激情一夜后，一年很快过去了。大一的暑假，吉姆（贾森•比格斯 Jason Biggs 饰）、凯文（托马斯•伊恩•尼古拉斯 Thomas Ian Nicholas 饰）、奥兹（克里斯•克莱因 Chris Klein 饰）和芬奇（艾迪•凯伊•托马斯 Eddie Kaye Thomas 饰）四个好友又聚在一起了，当然，还有不怎么讨人喜欢的史蒂夫（西恩•威廉•斯科特 Seann William Scott 饰）。四个好友决定摆脱史蒂夫，去过一个激情的暑假，庆祝他们顺利度过大一和伟大的友谊。但是史蒂夫在海边有一栋别墅，那是玩乐的最好场所，无奈他们只有带上史蒂夫一起驶往海边。经历了大学一年后，他们都比高中时更成熟了。海边美女如云，他们面临了更大的激情挑战，笑话百出。海边的狂欢舞会即将拉开，每人都在努力准备。©豆瓣', '贾森·比格斯', '詹姆斯·B·罗杰斯', 7.1, 49326, 'tt0252866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1446228716.jpg', 0.7, 4.8, 46.5, 35.4, 12.6, '0.228743,-0.234618,-0.616096,0.218575,0.092329,-0.633161,0.707219,0.160183,-0.218089,-0.240579,0.097395,0.643044,-0.435084,0.468065,0.503520,-0.224448,-0.693657,-0.490484,0.322308,-0.296541,-0.250763,-0.547295,-0.107585,-0.041435,0.210597,-0.274075,0.252498,-0.054632,0.426646,0.802681,0.315608,-0.136910,0.314899,0.329818,-0.249981,0.044217,0.489782,0.109301,-0.417883,0.255692,-0.087672,0.068081,-0.367471,-0.142833,0.460722,0.151718,0.586861,0.168645,-0.075786,0.030871,0.120906,0.052653,-0.111758,0.130857,0.389812,-0.077027,0.184546,0.210060,-0.070091,0.114401,0.039949,-0.236837,-0.332660,0.429469,-0.079864,-0.019925,-0.511459,0.676529,0.107816,-0.124675,0.342092,-0.241995,-0.085783,0.608964,0.137139,0.241413,-0.072744,-0.147109,-0.475089,0.215998,0.848725,-0.077147,-0.109794,0.477723,-0.180482,-0.205938,-0.034652,-0.060327,-0.389985,0.125588,0.382048,-0.113763,-0.142032,0.195913,-0.707987,-0.018250,-0.078381,-0.395322,0.120649,-0.323453,-0.057902,-1.130612,-0.053556,-0.347134,-0.312084,-0.021950,-0.119833,-0.142633,0.777119,-0.802738,0.206244,0.496578,0.322404,-0.216091,0.651034,0.161600,0.257581,-0.089610,0.199890,0.172562,-0.146187,0.276176,0.053793,0.757993,-0.037380,-0.070786,-0.476061,0.772908', '11541282', '3178770', '1296339', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305071', '猫狗大战', '喜剧', '猫狗自古就水火不容，这部动画更是将它们卷入一场势不两立的战斗当中。在这里，猫是最邪恶不过的动物，它们貌似平静温顺，却在暗中紧锣密鼓筹划着统治地球的阴谋。狗则是人类最忠实的保护者，他们忠心耿耿，要把危害人类的猫类“赶尽杀绝”。猎犬小卢正是这么一只身负重任的狗。因为，它得知了猫们正在野心勃勃，要毁灭狗类进而威胁人类。这只毫无战斗经验的小狗，临危受命担任起狗类的统帅，狗军师们帮他出谋划策。众狗各施所长，就连人类惯用的卧底招数也成为了这场猫狗大战的超级战术！看来小卢要在复杂的“战况”中鼓足斗志才行。©豆瓣', '杰夫·高布伦', '劳伦斯·哥特曼', 6.9, 38498, 'tt0239395', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2525537693.jpg', 1.2, 6.9, 50, 31.8, 10.2, '0.089556,-0.145571,-0.501343,0.569881,-0.075745,0.185538,0.500922,-0.194284,-0.380600,-0.044206,0.505205,0.376832,0.209994,-0.065867,-0.194439,-0.416053,-0.059670,-0.340194,-0.394205,0.227384,0.071683,-0.043305,-0.639824,-0.082316,-0.055130,-0.036971,0.796407,-0.144263,-0.419532,0.221634,0.322342,0.175782,-0.098925,0.315996,-0.202397,-0.142434,-0.054002,-0.171267,0.020247,-0.241632,-0.200335,0.017169,-0.041674,0.385853,-0.135221,0.004470,0.530781,-1.037690,-0.209715,-0.615691,0.169036,-0.573649,-0.027009,0.339994,0.620160,-0.180974,0.204491,-0.045148,0.304653,0.252861,-0.174394,-0.025372,-1.152382,-0.179236,-0.247472,0.367760,-0.358853,0.362346,0.296044,0.290265,0.254076,-0.148407,0.047050,0.255250,0.263216,0.212229,0.011247,0.140027,-0.655745,-0.052479,0.608512,-0.254756,-0.202242,0.205168,-0.095796,-0.515849,0.134026,-0.569460,-0.199570,-0.446388,0.233780,-0.201550,-0.447399,0.499767,-0.949140,0.100475,0.029344,-0.015765,-0.091735,-0.477413,0.077482,-0.496303,0.024209,-0.475662,-0.056591,0.334452,0.324770,-0.466585,0.814774,-0.967637,0.043420,0.687065,0.053742,-0.422157,0.381315,-0.179238,0.172984,-0.292718,-0.079238,0.123566,0.324830,0.213913,0.352676,0.354799,0.286221,-0.244917,-0.338984,0.723016', '3213270', '35377026', '3769423', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305080', '怒海沉尸', '剧情', '汤姆（阿兰·德龙 Alain Delon 饰）是一个穷小子，最近，一桩好差事找上了门，好友菲利普（莫里斯·荣内特 Maurice Ronet 饰）的富豪父亲找到了汤姆，希望他能够替自己找回成日在外风流潇洒的儿子，作为回报，汤姆将得到价值不菲的报酬。循着菲利普的踪迹，汤姆来到了拿布里，见到了菲利普和他的未婚妻玛奇（玛丽·拉福莱 Marie Laforêt 饰）。菲利普纸醉金迷的生活让汤姆十分羡慕，玛奇的美丽和温柔更是摄取了汤姆的心魄，一个邪恶的念头应运而生。一次出游中，汤姆设计杀死了菲利普，之后，为了掩盖罪行，汤姆又杀死了菲利普的好友。一个谎言，要用无数个谎言来掩盖，在得到了自己想要的一切后，汤姆终将面临审判。©豆瓣', '阿兰·德龙', '雷内·克莱芒', 8.1, 7940, 'tt0054189', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187325914.jpg', 0.2, 0.9, 18.2, 56.7, 24, '0.035480,0.168140,-0.313819,0.578305,-0.422263,-0.550459,0.821011,0.011873,-0.448779,-0.250789,0.002142,0.876988,-0.146396,0.328379,0.465368,0.217612,-0.380313,-0.722303,0.114416,-0.375629,-0.086942,-0.521887,-0.442597,-0.387583,-0.045015,-0.371209,0.356487,0.020080,0.051580,0.379641,0.344947,0.430462,0.259376,0.383717,-0.181009,0.065349,0.111490,-0.249680,-0.173092,0.499750,0.090574,-0.134154,0.031876,0.399669,-0.115834,0.353796,0.535228,-0.314286,0.046971,-0.120743,0.260288,-0.235198,0.092370,0.169058,-0.211690,0.058638,0.077017,0.242722,-0.422438,-0.141601,0.360140,-0.106208,-1.029930,-0.166461,-0.016728,0.141442,-0.738515,0.263262,-0.285116,-0.031709,0.188121,-0.444313,0.197784,0.032467,0.290446,0.346905,-0.105973,0.158488,-0.457855,0.117191,0.455444,-0.198427,0.063331,0.306096,-0.308926,-0.263328,0.268134,-0.171023,-0.448564,0.007560,0.517586,0.015531,0.156659,0.157770,-0.657586,-0.529525,-0.623635,-0.101087,0.091189,-0.536558,-0.092067,-0.392214,-0.163608,-0.105452,-0.363097,-0.163315,0.096165,-0.473523,0.700094,-0.798387,0.245505,0.605028,0.068042,-0.344546,0.466810,0.024507,0.167630,-0.156184,0.105134,0.058128,0.202760,0.368780,0.154752,0.182108,0.206687,-0.255685,-0.344572,0.635958', '1793491', '1308585', '1783461', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305084', '秘密', '剧情', '寒假里，直子（岸本加世子饰）和女儿藻奈美（広末涼子饰）去外地探望外公途中，长途客运车发生意外坠入山崖，直子不幸死去，藻奈美奇迹般地得救。醒来的藻奈美对着父亲（小林薰饰）却直呼其名，说自己是直子。自藻奈美的口中准确说出第一次约会的时间地点，甚至是2人做爱时的情景，平介不得不相信这真的是灵魂附体，可是接下来的生活该怎么过？面对“妻子-女儿”的双重身份，平介感到无所适从：一方面，两人再也无法过正常的夫妻生活，另一方面，直子似乎很乐意通过女儿的身份来体验校园生活，甚至包括恋爱。这让平介非常地不安。两人的相处渐渐成为一种折磨。©豆瓣', '广末凉子', '泷田洋二郎', 7.9, 24089, 'tt0211413', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1371691835.jpg', 0.7, 2.2, 24.7, 47.9, 24.4, '-0.074685,-0.049167,-0.709339,0.516664,-0.026660,-0.319670,0.479714,-0.103806,-0.735735,-0.470951,0.072979,0.412362,-0.239724,0.416633,0.460266,0.105060,-0.133550,-0.358311,0.032062,-0.030559,-0.347440,-0.324953,-0.013698,-0.176324,-0.055002,-0.180252,0.461687,0.012798,0.002705,0.515183,0.114068,0.464793,-0.092605,0.451577,-0.090054,-0.036905,-0.098227,0.323430,-0.311286,0.026017,0.156131,0.082158,-0.113380,0.217104,0.228558,0.272009,0.530124,-0.099226,-0.465217,0.035343,0.160971,-0.245615,-0.170266,0.215070,0.204405,0.090047,0.401932,0.112204,-0.225064,-0.029871,-0.043770,0.292102,-0.474288,0.202961,-0.000969,0.007467,-0.192262,-0.131617,-0.148973,-0.193817,0.090375,-0.414740,0.211781,0.184621,0.213827,0.429625,-0.415180,0.243132,-0.218959,-0.031961,1.113011,-0.001338,-0.253899,0.421064,-0.296042,-0.273583,0.083375,-0.237773,-0.492915,0.195663,-0.337981,0.225126,-0.303934,0.217193,-0.166263,-0.103301,-0.314095,0.087333,0.003839,-0.346946,0.231170,-0.229175,-0.031378,-0.657943,-0.386792,-0.021404,0.129723,-0.351063,0.486425,-0.706112,0.046091,0.328564,0.235817,-0.347080,0.321520,0.580740,-0.109436,-0.246187,0.007264,0.416846,-0.163634,-0.078327,-0.056548,0.129475,0.191680,0.077422,-0.462759,0.276865', '25721544', '1292064', '26320029', '2042219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305085', '盗马贼', '剧情', '1923年，藏民罗尔布（才项增仁 饰）游弋在高原上，以盗马维生。为了自己的孩子扎西，罗尔布放神羊为其祈福。头人的父亲死去，老阿妈对头人一家的善良感佩，同时又担心罗尔布因盗窃不能魂归于天。罗尔布与同伙抢劫了政府送给寺院的礼物，并打算用赃物为扎西向寺院还愿。抢劫事发，愤怒的头人将罗尔布一家驱逐，从此，罗尔布和妻子卓玛（旦枝姬 饰）、扎西只得在草原上流浪。扎西的病情不见好转并逐渐恶化，罗尔布用圣水为扎西沐浴、虔诚的求佛爷保佑却终于不能挽留自己的孩子。不久卓玛再次怀孕了，罗尔布和卓玛磕头为扎西还愿，但苦难并没有离他们而去……©豆瓣', '才项仁增', '田壮壮', 7.3, 6002, 'tt0090907', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2564339850.jpg', 0.9, 4.9, 35.6, 43.4, 15.1, '-0.101824,-0.165406,-0.518794,0.363612,-0.147175,-0.685295,0.688236,0.100027,-0.355617,-0.353261,0.036057,0.496607,0.284629,0.048858,0.109627,0.157753,-0.323660,-0.563452,-0.040338,-0.051397,-0.214345,-0.225919,0.225796,-0.316779,-0.305014,-0.411051,0.195029,0.294597,0.064958,0.361781,0.146993,0.110297,-0.147306,0.333769,-0.284268,0.146567,-0.429728,-0.039825,-0.204584,0.046444,0.071516,-0.362973,-0.294100,0.108109,0.197718,0.377934,0.472717,-0.349177,-0.122487,-0.200755,-0.091512,-0.186285,0.305468,0.196483,0.091041,-0.177598,0.227265,0.234586,-0.204265,-0.227953,0.122152,-0.178117,-0.456519,0.218795,0.101354,0.025286,-0.677898,0.411845,-0.123559,0.104963,-0.058003,-0.408714,0.229321,0.454779,-0.059219,0.466769,-0.315974,-0.059494,-0.289699,0.234741,0.400972,-0.146008,0.454279,0.133935,-0.238226,-0.495269,0.373143,0.164358,-0.474781,0.102307,0.331090,0.260002,-0.178836,0.257367,-0.301596,-0.333483,-0.565590,-0.348823,0.098644,-0.150124,0.098981,-0.231785,0.239182,-0.239089,-0.041343,-0.040616,0.389634,0.019809,0.364426,-0.489406,0.584004,0.497512,0.307206,-0.616962,0.470803,-0.080471,-0.025356,-0.300361,-0.237550,0.290965,0.017740,0.464596,0.323627,-0.113947,-0.041901,0.089050,-0.219349,0.248345', '1299965', '1844413', '1300043', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305086', '白色婚礼', '剧情', '中年的弗朗索瓦（布鲁诺·克雷默）是名哲学老师，他和风度怡人的妻在小镇里过着中规中距的生活。然而他的学生，17岁的少女玛蒂尔（凡妮莎·帕拉迪丝）出现了，带着少年人少有的成熟和不羁。弗朗索瓦带着挽救堕落少女的心情走近她，却难以抑制的被玛蒂尔的热情和聪慧所吸引。他们相爱了，激情四溢，刻骨铭心。可是当玛蒂尔要求弗朗索瓦离开妻，与她一起时，男人退缩了，他想到了年龄，婚姻，道德，身份，想到了太多的琐碎。再次绝望的玛蒂尔用激烈的方式破坏老师的生活，颠覆了他的事业与婚姻，然后消失的无影无踪。当人们再次发现她的时候，她的房间里写着“弗朗索瓦，这里就是海。”©豆瓣', '凡妮莎·帕拉迪丝', '让-克洛德·布里索', 8.2, 6296, 'tt0097995', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1181273150.jpg', 0.4, 2.2, 18.1, 46.6, 32.8, '0.370319,0.176103,-0.789566,0.640544,-0.630914,-0.381946,1.172340,0.039824,-0.528906,-0.032058,-0.027502,0.884428,-0.329330,0.575412,0.453475,0.241753,-0.393379,-0.826675,-0.212235,-0.215338,-0.035648,-0.445296,-0.035127,-0.109901,-0.242690,-0.476331,0.582780,-0.002671,-0.122968,0.566539,0.184868,0.036456,-0.038649,0.690934,-0.042885,0.065217,0.066332,0.016697,-0.013550,-0.042052,0.226812,-0.185929,-0.396847,0.259601,-0.167768,0.356187,0.646318,-0.213481,-0.153522,0.003848,0.377548,-0.140104,0.112900,0.396321,-0.056669,-0.085251,0.207766,0.142481,-0.128797,-0.277717,0.020355,-0.046440,-0.464283,0.159808,-0.073315,0.063618,-0.628167,0.626591,-0.155264,-0.237530,0.280011,-0.320265,0.105437,0.038449,0.247737,0.486128,-0.304266,-0.197506,-0.487872,0.204456,0.632951,-0.044369,-0.595465,0.307791,-0.588301,-0.472350,-0.151046,-0.222304,-0.628321,-0.292073,0.339828,0.246861,-0.218099,0.389791,-0.656673,-0.008309,-0.252495,-0.015284,-0.115935,-0.435788,-0.337965,-0.368993,-0.346178,-0.661160,-0.522355,0.040686,-0.089835,-0.340550,0.862879,-0.906802,0.211432,0.587499,0.520442,-0.235429,0.793515,0.057213,0.061450,0.073002,-0.207853,0.527048,-0.308621,0.262298,0.210439,0.572629,-0.251510,0.018871,-0.497212,0.871754', '1292062', '1309172', '1291877', '2131640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305092', '何处是我家', '剧情', '故事开始于1938年，即将爆发的战争阴影笼罩着每一个犹太人。为了避难，沃尔特（米勒·尼尼兹 Merab Ninidze 饰）带着妻子杰塔（茱莉安·柯勒 Juliane Köhler 饰）和女儿雷吉纳（莉·克卡 Lea Kurka 饰）远赴非洲大陆，希望能够在那里躲避战火，开始新的生活。刚开始，恶劣的自然环境和完全不同的生活方式让杰塔感到十分不适，背负着巨大压力的她将怒火和怨气全部发泄在了丈夫身上，夫妻两人之间的关系因此变得岌岌可危。然而，随着时间的推移和接二连三发生的意外，杰塔渐渐习惯了充满了辛苦但也洋溢着幸福的生活，亦懂得了珍惜眼前人。而年幼的雷吉纳更是融入了异域文化中，还在当地结交了许多好友。战争结束了，一家人的去留成为了最大的问题。©豆瓣', '茱莉安·柯勒', '卡罗莉内·林克', 8.2, 6886, 'tt0161860', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497595833.jpg', 0.3, 0.9, 16.2, 52.5, 30, '0.204148,0.025584,-0.794163,0.446201,0.284934,-0.271190,0.660365,0.186530,-0.547186,-0.308508,-0.193559,0.719054,-0.284202,0.174926,0.341312,-0.323846,-0.269491,-0.831495,-0.176979,-0.115943,-0.256503,-0.478022,-0.106202,-0.362884,-0.414928,-0.636745,0.593113,0.452773,-0.057704,0.630143,0.194556,0.350387,-0.130063,0.742292,-0.184932,-0.225245,-0.072375,0.000056,-0.481754,0.012111,0.140865,-0.185492,-0.047974,0.292414,-0.025592,0.364694,0.819482,-0.317086,-0.123987,-0.090829,0.361564,-0.169655,-0.037181,0.186287,0.112199,0.082101,0.129598,0.249283,-0.232613,-0.053382,0.103867,-0.322215,-0.628511,0.127396,0.102609,0.086785,-0.522699,0.702163,0.348446,-0.250232,0.241557,-0.293215,0.379757,0.511526,0.141407,0.490235,-0.481418,0.022142,-0.389848,-0.054044,0.892172,-0.158070,-0.466710,0.498030,-0.612791,-0.249848,-0.189734,-0.305661,-0.355299,-0.267761,0.158419,0.463467,-0.145485,0.623052,-0.773671,0.145937,-0.085419,-0.265487,0.093979,-0.582302,-0.006423,-0.450181,-0.585657,-0.551103,-0.311448,0.208217,-0.049371,-0.186762,0.772548,-0.830206,0.338082,0.388341,0.302665,-0.466251,0.506635,0.132688,0.219638,-0.082320,-0.140982,0.357189,-0.229449,0.152021,0.241251,0.269043,-0.313394,0.101528,-0.218609,0.660636', '35030151', '25721544', '1301022', '27040921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305096', '白头神探2½：恐怖的气味', '喜剧', '白宫晚宴上，总统布什招待各国首脑，因杀死一千名毒贩而受到嘉奖的白头神探弗兰克（莱斯利•尼尔森 Leslie Nielsen 饰）以及能源界的诸位领袖人物也一同出席，席间总统宣布由研究新能源的迈汉姆博士为政府的能源政策制定计划，这令靠石油、核能发家的能源界领袖们如临大敌。当夜迈汉姆博士的研究所就遭遇了炸弹袭击，弗兰克等人迅速赶到研究所，却不期然与已经分手的珍（普瑞希拉•普雷斯利 Priscilla Presley 饰）再相见，原来珍两年来一直在迈汉姆的研究所供职，并且有了新的男友——来自能源界的昆屯，在追查炸弹杀手的过程中，弗兰克发现其幕后老板居然是昆屯，此时的昆屯正在计划绑架迈汉姆博士后，用酷似博士的替身向总统进言发展核能，弗兰克再次出手，凭借自己搞砸一切的天赋挽救国家的未来……©豆瓣', '莱斯利·尼尔森', '大卫·扎克', 7.9, 17982, 'tt0102510', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1036751766.jpg', 0.4, 2, 24.6, 48.2, 24.8, '-0.104143,0.077968,-0.562536,0.398509,0.037151,-0.157816,0.075511,0.127886,-0.393419,-0.508794,0.295748,0.687577,-0.124989,0.070583,0.268838,-0.018155,-0.468760,-0.569295,-0.245770,-0.139033,-0.270331,-0.511636,0.007500,-0.283678,0.130169,-0.437873,0.718891,-0.085036,-0.246473,0.281737,0.073621,0.512616,-0.001512,0.330552,-0.062425,-0.258508,0.359484,-0.142639,-0.627387,0.242178,-0.065362,-0.173636,0.053212,0.093893,0.103689,0.323924,0.276715,-0.186188,0.051839,-0.314439,0.279871,-0.302228,0.156800,-0.074551,0.577727,0.138325,-0.137121,0.380769,-0.308940,-0.051054,0.164310,-0.199106,-0.919797,-0.079476,0.095218,0.153532,-0.435656,0.104520,-0.146537,0.223188,-0.142802,-0.123286,0.253610,0.643610,0.124847,0.233617,-0.003496,0.264585,-0.297748,0.120693,0.427633,-0.234576,-0.241462,0.096321,0.173364,-0.334014,-0.005223,-0.130839,-0.162837,-0.118906,0.104805,-0.059860,0.136478,0.427592,-0.666180,-0.058610,-0.523373,-0.236435,0.345852,-0.111752,-0.005709,-1.069107,0.059383,0.029061,-0.101439,0.167257,0.363961,-0.236547,0.654120,-0.586650,0.063763,0.468842,0.420478,-0.584144,0.514327,-0.196345,0.096939,-0.511997,-0.380656,0.033897,0.236222,0.386068,-0.212342,0.166666,0.319317,-0.414479,-0.196078,-0.013815', '2369613', '1293656', '4014397', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305114', '山村老尸', '恐怖', '小明（海俊杰）的四个朋友在黄山村玩过一次“招魂游戏”后先后离奇身亡，因直觉事有蹊跷，小明向当记者的姐姐CISSY（黎姿）求助，为获独家新闻，CISSY介绍对灵学颇有研究且暗恋自己的好友发毛（吴镇宇）给小明认识。发毛与小明赶赴黄山村调查时，了解到该村在百年前曾发生过离奇惨案，其时被丈夫密谋杀死后得知自己死因的粤剧名伶楚人美（施念慈）曾在三天内害死该村66条人命，而现在她的阴魂又现是因尸骨被新建的工程抛入山边的潭中。经过更加深入的调查，两人发现女鬼杀人的手法实则是让喝过潭水的人产生幻觉后离奇暴毙，但是此时CISSY及丈夫已经喝过潭水，为救CISSY，小明和发毛先后喝过潭水跳入深潭。©豆瓣', '吴镇宇', '梁鸿华', 6.9, 85849, 'tt0344290', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554609596.jpg', 2.5, 9.9, 41.9, 31, 14.8, '0.002935,-0.428131,-0.683430,0.290382,0.265293,-0.274504,0.833508,-0.184793,-0.870574,-0.370221,0.123449,0.424516,-0.448936,0.132281,0.187139,-0.170066,0.007741,-0.543557,-0.002480,-0.418812,-0.297337,-0.309354,-0.160912,0.019887,0.040940,-0.408055,0.254729,0.115601,-0.328412,0.365739,0.132747,0.322288,-0.349364,0.547646,-0.119521,0.168800,0.008136,0.260347,-0.309853,0.105945,0.076984,-0.309318,-0.085193,-0.034664,-0.054059,0.525537,0.545620,-0.124566,-0.720645,-0.297525,0.232140,-0.224519,-0.133705,-0.002016,0.556943,0.273152,0.183237,0.139889,-0.299828,-0.257331,-0.232941,0.191933,-0.459027,-0.057197,0.240669,0.218194,-0.637398,0.092847,0.046478,-0.004518,-0.061620,-0.197496,0.230656,0.209571,0.304985,0.430938,-0.172687,-0.078426,-0.270906,0.222617,0.841100,-0.082468,0.235862,0.399506,0.232378,-0.449047,0.189000,0.088721,0.054736,0.492773,0.234515,0.113501,-0.322824,0.439837,-0.216520,-0.311022,-0.199091,0.004289,0.059145,-0.167883,-0.398169,-0.346095,-0.156684,-0.027477,-0.246296,-0.096624,-0.125923,-0.422705,0.228091,-0.471329,0.324733,0.370144,0.076690,-0.402118,0.431315,0.178875,-0.076359,-0.118072,-0.014685,0.126659,0.315220,0.312457,0.198257,0.234037,-0.114196,-0.219074,-0.485550,-0.149849', '10508879', '1292064', '1309297', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305143', '西楚霸王', '动作', '大秦帝国灭亡，刘邦（张丰毅 饰）与项羽（吕良伟 饰）一起打拼却只能被册封为汉王，被调配至西蜀，而项羽则得到了虞姬（关之琳 饰）的独爱。刘邦之妻吕雉（巩俐 饰）不甘心屈居人下，怂恿刘邦入汉后广招人才，表面上与虞姬情同姐妹，但是却利用项羽对虞姬的感情从中挑拨，与此同时刘邦对 虞姬则关爱有加，这更引起了吕雉的妒忌。而此时此刻项羽不理朝政日夜笙歌，最终楚军大败，虞姬为了不让项羽分心而自尽，可是项羽最后还是一败涂地，在项羽乌江自刎后刘邦统一了天下，吕雉成为了他的王后。本片的监制是张艺谋，汇聚了两岸三地的实力派演员，主题曲为黄沾创作的《思归赋》，演唱者是腾格尔。©豆瓣', '吕良伟', '冼杞然', 7.1, 6900, 'tt0111760', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2172142214.jpg', 1, 4.5, 43.7, 37.9, 13, '-0.072996,0.119713,-0.688379,0.709124,0.253800,-0.352613,0.417024,0.498013,-0.450356,-0.066271,0.304828,0.619625,-0.153186,-0.003539,-0.241076,-0.099172,-0.244836,-0.823249,-0.084340,-0.008848,0.256722,-0.152148,-0.080996,0.062939,-0.608112,0.012025,1.058557,-0.013181,-0.142291,0.490737,0.530746,0.215269,0.149240,0.630737,0.079175,0.216386,-0.283549,-0.160644,-0.325642,0.235562,0.033634,-0.628622,-0.388983,0.259489,-0.444627,0.277286,0.379294,-0.356564,0.312928,-0.366688,0.393249,-0.393915,0.063144,-0.030897,0.182224,0.009553,0.226373,0.373578,0.008121,-0.012786,0.187848,0.094128,-0.757961,-0.183948,0.337965,0.053652,-0.704612,0.721659,-0.215129,-0.315534,0.057731,-0.195114,0.301996,0.407912,0.451667,0.116954,-0.358010,-0.220752,-0.447398,0.518877,0.579473,0.080947,0.028095,0.124845,-0.006621,-0.457886,0.262154,-0.323886,-0.374393,0.018501,0.232087,0.087395,0.430866,0.244647,-0.290623,-0.225519,-0.267227,0.268916,0.037088,-0.287989,0.214020,-0.239252,-0.318964,-0.345297,-0.087058,-0.030577,0.271935,-0.197433,0.698306,-0.723071,-0.212502,0.096428,0.330504,-0.896439,0.501081,0.405117,-0.027211,0.064772,-0.155849,0.275596,-0.094586,-0.170283,0.271930,-0.018852,-0.159332,-0.187546,-0.491856,0.268464', '6101834', '4723944', '4202326', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305164', '甜蜜蜜', '剧情', '改革开放初期，黎小军（黎明 饰）告别女友小婷（杨恭如 饰）从天津（国语版中为无锡）来到香港讨生活，期望有天挣到大钱把小婷接来与之风风光光地成婚，没料想日子会比想象中的难熬许多。黎小军在快餐店与同样从大陆到港讨生活但避讳谈自己身份的李翘（张曼玉 饰）结识后，因为共同喜爱邓丽君，两人人在异乡的孤独都有了某种程度的缓解，并在交往的过程中生出了真爱，可是世事难料，两人最终无奈分手，黎小军成了小婷的老公，李翘跟了在黑社会做事的豹哥（曾志伟 饰）。然而因为邓丽君，两人的缘分并没到此为止。©豆瓣', '黎明', '陈可辛', 8.9, 493684, 'tt0117905', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2223011274.jpg', 0.1, 0.4, 8, 37.4, 54, '0.227715,-0.054217,-0.870474,0.432912,-0.000295,-0.302967,0.698655,0.236073,-0.475044,-0.099804,0.056912,0.907177,-0.229141,0.283064,0.334172,-0.304008,-0.043344,-0.718011,0.283499,-0.322914,-0.174491,-0.430083,-0.143408,0.035216,-0.479211,-0.190516,0.534085,0.295821,-0.067927,0.668190,0.288989,-0.057666,-0.248249,0.551259,-0.527117,0.039524,0.012500,0.668783,-0.619761,0.080807,0.061747,-0.153915,-0.203645,0.012879,0.220373,0.245182,0.541411,-0.073244,-0.075490,0.382583,0.152932,-0.073228,-0.256116,-0.033636,0.272290,-0.101902,0.222509,0.436836,-0.197750,0.111209,0.015498,-0.013555,-0.556080,0.207381,0.139053,0.055464,-0.690758,0.576441,-0.039319,-0.307174,0.074880,-0.329951,0.392205,0.683339,0.156341,0.451834,-0.169362,0.113262,-0.557289,0.381072,0.784496,0.118809,-0.129667,0.629511,-0.014172,-0.473754,-0.087364,-0.179463,-0.347950,-0.038943,0.036595,-0.015323,-0.383407,0.290837,-0.513173,0.036597,0.105532,-0.079919,0.268284,-0.440479,0.003580,-0.572579,-0.327627,-0.818623,-0.312828,0.140990,0.203346,-0.291955,0.689472,-0.938090,0.161462,0.302234,0.309151,-0.532738,0.777005,0.271438,0.131615,-0.124106,0.046002,0.190811,-0.119123,0.162727,0.196129,0.347412,-0.228541,-0.115536,-0.375529,0.273993', '25721544', '1292219', '1306465', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305175', '漂亮妈妈', '剧情', '孙丽英（巩俐 饰）数年前与丈夫离婚了，独自抚养着天生失聪的儿子郑大，她耐心的教会儿子说话，教儿子识字，母子俩生活艰难，但她却没有埋怨丈夫移情别恋，埋怨上天对她的不公。孙丽英认为自己的儿子跟正常人没什么两样，可是儿子入学考试失败还是让她感到失落。郑大被其他孩子欺负的时候把助听器摔烂了，孙丽英想让前夫帮忙，却不得要领。生活还是要继续的，为了给儿子再买一个助听器，孙丽英除了派报纸，还兼职了几份钟点工。好朋友大贺与方老师都给她们俩母子提供了很大的帮助，孙丽英也对方老师产生了好感。经方老师的帮忙，郑大上学的事也有了希望。可是孙丽英却被雇佣她做钟点工的贾老板差点强奸了。她拿着本该属于自己的钱给郑大买了一个助听器，可郑大还是受到了歧视，孙丽英追逐着走在大街上的孩子。儿子问为何自己要戴助听器，孙丽英终于面对了现实，告诉儿子因为他是个聋子……©豆瓣', '巩俐', '孙周', 7.4, 13496, 'tt0236598', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1330477780.jpg', 0.4, 2.2, 38.7, 44.4, 14.3, '0.075734,-0.087397,-0.475707,0.681847,-0.628861,-0.588111,0.539085,0.098051,-0.501139,-0.316449,-0.185064,0.799090,0.153836,0.450152,-0.250449,0.074981,-0.153246,-0.541437,0.189117,0.095215,-0.397364,-0.510944,0.071113,-0.186191,-0.173598,-0.066281,0.139876,-0.251507,-0.144374,0.123780,0.387485,-0.171389,0.222193,0.562111,-0.373389,0.099854,-0.234429,0.163565,0.049216,0.032363,0.372765,-0.165862,-0.047233,0.298434,0.135086,0.426654,0.369245,0.102555,-0.263210,-0.133004,0.149010,-0.381840,0.140757,0.153574,0.021066,-0.016597,0.175726,-0.059894,-0.174316,-0.067189,0.262963,-0.051534,-0.666288,0.075865,0.077602,-0.201010,-0.993403,0.704754,-0.146739,-0.092435,0.057593,-0.218066,0.381229,0.282205,0.171842,0.586767,-0.441000,-0.028598,-0.532701,0.312235,0.605744,-0.105454,0.095668,0.302877,-0.336154,-0.244530,0.349064,-0.297383,-0.781415,0.232951,0.084238,0.046887,-0.421924,-0.046686,-0.349674,0.054000,-0.120404,-0.036353,-0.047600,-0.869749,0.281216,0.011879,0.068080,-0.322360,-0.584090,0.056196,0.283942,-0.447619,0.789585,-0.616419,0.264898,0.655790,0.637257,-0.846721,0.796765,0.314465,0.151274,-0.154095,-0.019850,-0.251171,-0.073221,0.221615,0.489656,0.153483,0.194426,-0.196544,-0.102668,0.422076', '1877596', '1307542', '1309033', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305179', '大丈夫', '剧情', '一天，郭天佑(曾志伟饰)、李永祥(陈小春饰)、徐娇(杜汶泽饰)及洪国波(贾宗超饰) 四人突然不约而同离开工作岗位，换上他们绝少穿着的黑色西装，搭上毫不起眼的普通的士，准备进行一项神秘行动：14小时的“偷食”行动。原来他们的老婆或恋人——一众太太团结伴到泰国拜佛，因而获得彻底自由的14小时。他们小心策划，部署一切，务求不会浪费时间。如期出发后，行动却意外频生、处处碰壁，大家开始怀疑意外并非偶然，而是有人暗中破坏，甚至怀疑四人中有告密者存在。与此同时，一辆神秘车子更是一直跟踪着他们。原来四人的太太女友突然折返，打算联手截击他们的“偷食”行动。 “偷食”行动能否如期进行，又将如何收场呢？©豆瓣', '曾志伟', '彭浩翔', 7.5, 43418, 'tt0380291', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359323547.jpg', 0.7, 3.6, 31.5, 46.9, 17.2, '0.215927,-0.046841,-0.673829,0.231138,0.033336,-0.176995,0.188128,0.065433,-0.471730,-0.369180,0.411652,0.276623,-0.173999,-0.217659,0.135892,-0.186349,-0.615625,-0.491640,0.264162,-0.034322,-0.209051,-0.231566,-0.096939,-0.389402,0.232442,0.057274,0.312032,0.200458,-0.021545,0.660231,0.396932,0.013475,-0.430035,0.603919,0.073579,-0.090947,0.130248,-0.270940,-0.224534,0.120719,-0.208712,-0.282892,-0.100059,0.153090,0.027643,0.442158,0.769530,-0.242900,-0.428136,-0.136800,0.346255,-0.219191,0.129781,0.204462,0.302672,0.210309,0.355197,0.286473,0.029084,0.084527,0.061934,0.012311,-0.243222,0.252429,0.025642,0.093123,-0.282640,0.008872,-0.134229,0.119707,0.076023,-0.266502,0.011198,0.626916,0.480584,-0.196522,0.087173,-0.099246,-0.330427,0.002853,0.630022,-0.036037,0.139164,0.070400,0.258135,-0.186808,0.115352,0.056041,-0.282864,-0.096050,0.318032,0.225688,0.169287,-0.115761,-0.160822,0.029255,-0.154691,-0.020971,0.060387,-0.188069,0.195822,-0.892779,0.216890,-0.084827,-0.245006,0.179027,-0.097151,0.061216,0.250118,-0.616946,0.173632,0.279057,0.480995,-0.568810,0.216732,-0.191964,0.223942,-0.318918,-0.190398,-0.170498,-0.165781,0.245783,0.217030,0.206996,-0.091698,0.114691,-0.167940,-0.135359', '1292846', '3871833', '3036464', '35287558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305182', '红河谷', '剧情', '一个男子（邵兵饰）救下了被乡民准备供奉给雨神的女子（应真饰），两个人一起流落到了一个藏族部落，开始了他们新的生活。在这里，他们认识了美丽的藏族公主（宁静饰）。后来，英国探险队在雪山遇险，琼斯（尼克饰）和罗克曼（波尔饰）也被藏民救下，留在西藏修养。在这段时间的相处中， 他们跨越了民族和肤色，培养除了深厚的感情。不久，伤养好后，英国人也离开了。没想到再一次重逢居然这么快，而且，是以这么一种残酷的方式。为了各自的信仰和立场，曾经的朋友站在了对立的两边，只有巍巍的雪山默默的见证着这一切。©豆瓣', '宁静', '冯小宁', 7.8, 55182, 'tt0223998', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2459387513.jpg', 0.5, 1.9, 24.9, 50, 22.7, '0.284512,-0.164459,-0.769279,0.848669,-0.230066,-0.463363,0.672997,0.265027,-0.633023,-0.134107,0.185082,1.006889,-0.078565,0.187263,0.365782,-0.123791,-0.538583,-0.687392,-0.217746,-0.350640,-0.568792,-0.238279,-0.141096,-0.140152,-0.241507,-0.380335,0.592230,0.070331,0.094306,0.665893,0.122633,-0.004243,-0.052985,0.360698,-0.589904,0.017165,0.025873,0.050154,-0.403854,0.395950,-0.090346,-0.123843,-0.049321,0.208182,-0.135293,0.294493,0.536802,-0.358664,-0.124798,-0.037792,0.092710,-0.215561,0.077702,0.200125,0.479237,-0.319116,0.308415,0.221202,-0.351705,-0.166497,0.057042,-0.165327,-0.647793,0.163931,0.007964,0.122742,-1.030672,0.773429,0.212974,-0.390160,0.058637,-0.384602,0.299478,0.717203,0.287255,0.370234,-0.097697,-0.236892,-0.529664,0.077212,0.905472,-0.106497,-0.060967,0.304556,-0.221758,-0.535383,-0.107096,-0.244214,-0.410089,-0.089200,0.285040,-0.115905,-0.173054,0.095541,-0.955428,0.140983,-0.149896,-0.162810,0.106999,-0.697711,-0.074630,-0.420327,-0.258327,-0.556657,-0.504135,0.268037,0.015790,-0.045873,0.959676,-0.923040,0.166202,0.488203,0.486440,-0.512023,0.762094,0.110974,0.161933,-0.033926,-0.044161,0.141609,0.061800,0.546946,0.315018,0.615828,-0.030003,0.214798,-0.556505,0.373296', '1292219', '1414808', '1293303', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305183', '神奇燕尾服', '喜剧', '出租车司机吉米·唐（成龙 饰）是个在自己心仪女子面前缺乏自信的家伙，所经反复排练但还是会在上阵时手足无措。飚出租车是他唯一所长，拥有因超速被九次吊扣执照的光荣记录，也因这一点被富翁戴弗林（Jason Isaacs 饰）的助手选中，担任戴弗林的司机。戴弗林的另一身份是情报局局长，此时正全力调查一宗饮用水公司的商业阴谋。唐被戴弗林优雅的举动深深折服，两人合作融洽，不料一日两人遭滑板炸弹袭击，戴弗林重伤，昏迷前将家中严禁触碰的燕尾服交予唐使用，并留下“沃特史崔达”的莫名词句。唐无奈之下只得扮演戴弗林的角色，接受安全部门的指令，但他很快发现那件燕尾服不同寻常！用腕表调控相关模式便可以让着衣者拥有超人般的身手。唐要仰仗这件高科技战衣与美丽的菜鸟探员黛儿·布兰妮（Jennifer Love Hewitt 饰）合作，用他们的乌龙方式查清班尼公司的真相……©豆瓣', '成龙', '凯文·多诺万', 6.4, 46343, 'tt0290095', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1969620072.jpg', 1.7, 11.9, 58.2, 21.6, 6.5, '0.257390,0.223583,-0.451653,0.466946,-0.274697,-0.211519,0.411618,0.052789,-0.729376,-0.491902,0.160064,0.673393,-0.323567,-0.043169,0.333034,-0.135644,-0.008512,-0.621420,-0.099151,0.152043,-0.321268,-0.483184,-0.062974,-0.301732,-0.037581,-0.125698,0.490530,0.070127,-0.272886,0.253742,0.453941,0.397092,-0.183606,0.358089,-0.175755,-0.193090,0.047169,-0.238972,-0.224859,0.250665,0.126897,-0.250296,0.152669,0.195123,-0.111220,0.351208,0.466363,-0.133876,-0.448418,-0.098509,0.413465,-0.222642,0.073708,-0.112763,0.403621,0.333029,-0.015839,0.038146,-0.201484,0.027949,0.295554,0.153145,-0.769452,-0.107013,0.092911,-0.019128,-0.565469,0.148494,-0.334492,0.012181,-0.010010,-0.297226,0.274181,0.212082,0.455806,0.112410,-0.030490,0.021225,-0.497279,0.247283,0.306429,0.312528,-0.189573,0.278129,-0.379079,-0.459674,-0.081807,-0.321429,-0.234205,0.038813,0.329818,0.140532,0.022645,-0.081431,-0.206490,-0.200020,-0.288382,0.036434,-0.314435,-0.457611,0.019958,-0.605686,-0.023757,-0.385193,-0.375288,-0.036414,0.167345,-0.135694,0.337149,-0.693143,0.003476,0.283223,0.056064,-0.248401,0.463793,-0.037982,0.184305,-0.100703,-0.099119,0.066746,0.350766,0.201686,0.095238,0.420837,0.017871,-0.227494,-0.112637,0.108302', '1793491', '1783461', '4301278', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305197', '97家有喜事', '喜剧', '老先生（乔宏 饰）有三个儿子。老大老良（黄百鸣 饰）整天忙于工作而忽略了老婆贤淑（伍咏薇 饰），贤淑每天在家中打点，却遭到老公误会她红杏出墙。次子老非利用读书逃避到投身社会，个性单纯，向往爱情却遭到伤害，之到后来认识了从北方来的小莲（吴倩莲 饰）。适逢老三老恭生日，平日老恭作恶多端，生性风流，两个哥哥以买彩票为名作为礼物送给老恭，其实那本来是一张过期的中奖彩票，他信以为真，因此欠下了巨债。祸不单行的他撞车脑震荡，变得疯疯癫癫……©豆瓣', '周星驰', '张坚庭', 7.7, 96761, 'tt0118591', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220261826.jpg', 0.4, 2.7, 31.4, 44.1, 21.4, '0.038497,0.010256,-0.418449,0.166808,-0.304621,-0.241198,0.478538,0.585390,-0.259873,-0.473727,0.099768,0.443527,0.235261,-0.031613,0.019573,-0.033117,0.281127,-0.063631,0.158726,0.178212,0.138591,-0.228197,0.125430,0.181743,-0.170479,-0.321006,0.089358,-0.092767,-0.304452,0.512152,0.288312,0.332957,0.216128,0.143637,-0.029659,0.056084,-0.208148,0.213214,-0.093703,-0.026909,-0.100489,-0.038011,0.098991,-0.053545,0.212766,0.227701,0.624459,0.236545,-0.304194,-0.169660,0.559983,-0.094931,-0.355537,-0.002208,0.188785,-0.103179,0.217291,0.047449,-0.202324,0.063784,0.238715,-0.087366,-0.351989,-0.076421,0.168016,-0.005801,-0.466564,0.323722,-0.198535,-0.074879,-0.110737,-0.349133,0.198901,0.366831,0.008251,0.214276,0.001728,0.247205,-0.547187,0.332126,0.621618,-0.134573,0.155582,0.534216,-0.078256,0.013231,0.439556,-0.411582,-0.560650,0.326054,-0.065095,-0.458999,-0.211078,0.125634,-0.433456,0.035554,0.040250,0.239380,0.144626,-0.535114,-0.304767,-0.227774,-0.188650,-0.321661,-0.379736,-0.107590,0.104532,-0.259203,0.499488,-0.457570,0.224482,0.548331,0.033052,-0.869841,0.464303,0.418605,-0.225052,-0.099785,0.063368,0.092895,0.209904,-0.151233,-0.165037,-0.266906,0.026748,-0.197358,-0.153448,0.112725', '1421278', '24879820', '1305915', '1309033');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305201', '黄飞鸿之铁鸡斗蜈蚣', '喜剧', '黄飞鸿也会做糗事：听信弟子梁宽（梁家仁 饰）及牙擦苏（张卫健 饰），他竟把宝芝林搬到了妓院旁边。但这令他的众弟子喜上眉梢。妓院老板黄狮虎（陈百祥 饰）将黄飞鸿视作偶像，一心想拜他为师，却不被理会，其妹妹（袁咏仪 饰）等妓女更是被他敬而远之。清廷命官雷一笑（徐忠信 饰）实是义和团余孽，他勾结上级官员及能仁寺花和尚掳掠女性，准备将她们贩卖到南洋。 剧情简介: 黄飞鸿得知雷的阴谋后，开始想办法将被抢女性解救，被雷视作眼中钉。不久他同梁宽、牙擦苏等人表演舞狮时，因之前为救治病人拿自己当实验品服用西药，双耳突然失聪，被雷及其手下装扮的蜈蚣击败。回佛山医治路上，他遇到将他误会的铁燕（张敏 饰）和其父亲，他们从四川来到广州找寻失踪的妹妹时，曾因听闻雷一笑与黄飞鸿的对话将两人视为一伙。©豆瓣', '李连杰', '王晶', 7.3, 50665, 'tt0108593', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2351999788.jpg', 0.5, 3.6, 41.8, 40.5, 13.6, '0.296972,-0.039139,-0.377878,0.388486,-0.118607,-0.064976,0.499076,0.097762,-0.617520,-0.235404,0.044984,0.506827,-0.290696,0.090505,0.210299,-0.094412,-0.008060,-0.753864,0.031188,-0.063458,-0.190683,-0.178938,-0.013717,-0.321338,-0.327236,-0.165993,0.153018,-0.044111,-0.337549,0.347596,0.422163,0.304976,-0.139475,0.431412,-0.166292,0.199416,-0.151147,0.021781,-0.104172,0.108568,-0.004808,-0.547544,-0.086783,0.105123,-0.085986,0.479661,0.534161,-0.105731,0.025997,-0.354348,0.118998,-0.305758,0.214750,0.251751,0.268277,0.097371,0.082881,0.139356,-0.238458,0.074092,0.202420,-0.016326,-0.402392,0.133032,0.204215,-0.126266,-0.670479,0.089009,-0.123177,0.278924,0.065843,-0.158541,0.328779,0.081119,0.091638,0.195894,0.097848,-0.070471,-0.457531,0.508335,0.541811,-0.340057,0.349307,-0.010156,0.274506,-0.433649,0.157951,-0.214708,-0.046275,0.083788,0.321340,-0.048888,-0.037626,-0.042613,-0.234397,-0.515571,-0.241961,-0.012636,0.022108,0.014873,-0.014168,-0.335961,0.125137,-0.281154,-0.144022,0.015457,0.315080,-0.087715,0.490576,-0.476494,-0.156134,0.091812,0.319881,-0.785084,0.565902,-0.128452,0.134324,-0.237834,-0.081666,-0.026023,0.425010,0.225836,0.379124,0.245215,-0.077360,-0.180758,-0.135995,0.081458', '1302110', '1293607', '1306249', '1366853');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305211', '逃学外传', '剧情', '育才书院F.4D是全校最顽劣的一班，不仅考试成绩不及格，还常常整蛊老师，不计其数的老师都被这群调皮捣蛋的学生给气走了。其中最为古灵精怪的要数小头目张一健（张卫健饰），他在校内横行无忌，甚至连秦主任（吴孟达饰）也不敢招惹他。而班级中的林志颖（林志颖饰）、阿隆（吴奇隆饰）和黎文诗（朱茵饰）也丝毫没把心思花在学习上。然而新来的张老师（张敏饰）却与众不同，她不仅美丽干练，还能躲过学生们的种种恶作剧。鬼灵精张一健当然不能放过这位女老师，使出各种怪招让她下不了台。突然有一天，张一健请了病假，张老师到他家访问才得知张一健根本没有生病，而是因欠了赌债去打工还债。与此同时，校内又发生了各种令人头疼的事端。©豆瓣', '张卫健', '朱延平', 6.9, 12691, 'tt0096222', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350529751.jpg', 0.9, 6.2, 52, 29.2, 11.6, '0.392811,-0.356776,-0.432933,0.387241,-0.407072,-0.372493,0.373174,-0.019124,-0.382888,-0.329179,-0.036327,0.305301,-0.279946,0.468018,0.021003,-0.333591,0.057246,-0.461422,0.021207,-0.119779,-0.236987,-0.273829,-0.072019,-0.042259,-0.042207,-0.251647,0.214184,-0.115771,-0.304271,0.333995,0.385295,0.006918,0.177805,0.404337,-0.315071,0.092337,0.008515,0.254530,0.532688,0.023436,0.331849,-0.583474,-0.394348,0.225168,0.405931,0.368661,0.597455,0.027081,-0.083898,-0.065346,0.431070,-0.292580,-0.048987,0.205427,0.302002,-0.190413,0.428009,0.122198,-0.110833,0.400777,0.211927,-0.073885,-0.490587,0.177569,0.112443,0.042418,-0.455073,0.318295,-0.007544,-0.339502,0.072687,-0.296704,0.164193,0.086345,-0.082355,0.150528,-0.173030,-0.072830,-0.468699,0.350756,0.396451,-0.025923,-0.200413,0.189241,-0.085370,-0.309957,0.192209,-0.443758,-0.408679,0.258388,0.098274,-0.136923,-0.104205,-0.037271,-0.393862,-0.099100,-0.063319,-0.150133,-0.320567,-0.331674,-0.102850,-0.508709,0.125087,-0.276863,-0.332352,0.105925,0.302291,-0.098214,0.822739,-0.762893,0.076731,0.377046,0.184880,-0.530346,0.635940,0.205806,-0.051252,0.175629,-0.402304,-0.259197,0.250316,0.518415,0.025885,0.586434,-0.022114,-0.636113,-0.036806,0.203453', '25922902', '1296770', '6963575', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305217', '鬼马小精灵', '喜剧', '某富豪过世，他将大部分财产捐给各种慈善机构，只给自己专横跋扈的继女凯丽根·克里坦顿（凯西·莫拉蒂  Cathy Moriarty 饰）留下一幢位于缅因州的别墅。这幢名为维普斯大府庄园的别墅拥有很久的历史，如今早已破败不堪，无法住人。凯丽根起初愤怒不已，但她偶然知晓别墅内可能藏着金银财宝，于是和律师帝布斯（Eric Idle 饰）欣然前往。令他们想不到的是，这里竟然还住着4个幽灵。财宝当前，贪心之人想方设法要把幽灵赶走……本片荣获1996年美国科幻与恐怖电影学院青年演员最佳表演奖（克里斯蒂娜·里奇 Christina Ricci）、1996年青年艺术家奖最佳表演（配音）奖（Malachi Pearson）。©豆瓣', '克里斯蒂娜·里奇', '布拉德·塞伯宁', 8.1, 24917, 'tt0112642', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2879220448.jpg', 0.2, 1.1, 20.3, 48.8, 29.6, '0.043084,-0.106965,-0.542879,0.445927,0.109233,-0.150419,0.621494,-0.109004,-0.821427,-0.469086,0.182558,0.730914,-0.041104,0.367833,0.326229,0.154444,-0.303994,-0.360762,-0.365107,-0.380838,0.099888,-0.404058,-0.315926,-0.284065,-0.143226,-0.397644,0.465647,0.020096,0.121490,0.172720,0.369058,0.416537,-0.159858,0.057317,-0.157560,0.124025,0.353293,-0.237696,-0.283252,0.314973,-0.205050,-0.167407,-0.096957,0.106572,0.116939,-0.009333,0.610442,-0.084943,-0.048451,-0.053477,0.385746,-0.144361,-0.178107,0.232635,0.183290,-0.380710,0.454769,0.241625,-0.211002,0.015695,0.294287,-0.347958,-0.494459,-0.024446,0.235216,-0.060932,-0.513640,0.431428,-0.135959,0.194843,-0.249424,-0.228815,0.265031,-0.074756,0.310362,0.160365,-0.057927,-0.077901,-0.705624,0.573116,0.394653,0.011293,-0.126455,0.014484,-0.324202,-0.486328,0.019430,-0.381701,-0.572313,0.195264,0.398033,0.120893,0.081036,0.126526,-0.357557,-0.058372,-0.212130,-0.264889,0.179332,-0.347664,-0.284992,-0.600533,-0.093317,-0.006915,-0.155019,-0.073159,0.011339,-0.122727,0.441904,-0.489351,0.212121,0.419720,0.396280,-0.205260,0.815647,-0.502553,0.137698,0.133418,-0.415807,0.061696,0.120445,0.225188,0.094062,0.160076,-0.208239,-0.618985,-0.210231,0.271683', '3055049', '1306860', '1302384', '5384590');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305224', '寻枪', '剧情', '马山（姜文）是西南地区某边陲小镇的一名普通警察，某晚参加妹妹婚宴时因喝得酩酊大醉被人送回家中，次日早晨醒来时，他发现从不离身的配枪不翼而飞。意识到偷枪人可用枪里的三颗子弹杀人时，马山不禁毛骨悚然，当晚所有参加妹妹婚礼的人都成了他的怀疑对象。在对重点嫌疑人，卖“羊肉粉”的刘结巴、送他回家的周小刚、突然出现在周小刚家的旧恋人李小萌（宁静）一番追踪后，马山依旧没能理出任何头绪，而对李小萌的怀疑里，又混杂了极为复杂的感情，此又导致其妻怀疑他移情别恋。正在这时，李小萌在周小刚家被人用枪打死，马山作为嫌疑人被拘禁。经过一番冷静思考，他终于将乱麻捋顺，开始了寻枪之路。©豆瓣', '姜文', '陆川', 7.8, 101194, 'tt0342778', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2184558984.jpg', 0.3, 1.6, 25.1, 54.4, 18.6, '0.276205,0.171428,-0.834820,0.089853,-0.187377,-0.131511,0.640541,0.055192,-0.611316,-0.183404,0.109009,0.394768,-0.339717,0.236678,0.385269,-0.114073,-0.297745,-0.730206,0.049159,-0.158091,-0.289184,-0.380064,-0.037179,-0.074616,0.141004,-0.070174,0.072220,0.018221,-0.156575,0.369806,0.238886,0.120099,0.034775,0.722151,-0.268150,0.217962,-0.158984,-0.162918,-0.044022,0.018255,-0.004567,-0.296626,-0.097892,0.182512,-0.056498,0.631279,0.650409,0.065963,-0.303177,-0.073096,0.277190,-0.202466,-0.200900,0.071922,0.446156,0.164703,-0.013106,0.030048,-0.240900,0.004762,0.211753,0.021255,-0.320286,0.133249,0.168324,0.219156,-0.495712,0.362965,-0.166562,0.019916,-0.129107,-0.217865,0.496185,0.247083,0.090068,0.285874,-0.119095,-0.151324,-0.321785,0.385814,0.504309,-0.307538,0.102774,0.220376,0.131892,-0.416829,0.341185,-0.122071,-0.109024,-0.071511,0.323460,0.291347,-0.283891,-0.017528,-0.346455,-0.217305,-0.059675,-0.208669,-0.068812,-0.339003,-0.236306,-0.293699,-0.005850,-0.242274,-0.246604,0.117679,0.037034,-0.071596,0.249724,-0.541904,0.178225,0.248915,0.018464,-0.255276,0.285145,-0.054386,-0.035561,-0.215051,-0.102201,0.145239,0.351990,0.422706,0.261803,0.293494,-0.293217,-0.200965,-0.389845,0.078382', '25870679', '1309297', '6722888', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305248', '来自地狱', '悬疑', '贫穷混乱的伦敦街头，混杂着妓女和各色人物，玛丽（海瑟•格拉汉姆 Heather Graham饰）、安妮（乔安娜•佩姬 Joanna Page 饰）和其他几个妓女在这滩浑水中结成深厚友谊。然而，罪恶的魔爪正在伸向她们——这个躲在暗处的杀手，绑架甚至杀害这些姑娘。探员艾伯林接手这宗案件，他天生拥有超能力，这对他破案有着不小的作用。艾伯林（约翰尼•德普 Johnny Depp 饰）来到案发地区，渐渐掌握了线索，同时他也被玛丽善良的品质深深吸引，与她共坠爱河。但凶手的行动令妓女们陷入了恐慌之中，能否查出真凶，成为摆在艾伯林面前的迫切难题，而艾伯林也堕入了一个更大的漩涡之中，危机四伏。©豆瓣', '约翰尼·德普', '艾尔伯特·休斯', 7.2, 29959, 'tt0120681', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p898216814.jpg', 0.6, 4.2, 40.7, 42, 12.5, '0.348531,0.058175,-0.591830,0.363166,-0.205499,0.087658,0.887014,0.059460,-0.454045,-0.283260,0.161520,0.705102,-0.081380,0.063534,0.112660,-0.046319,-0.353702,-0.760500,0.099297,-0.274192,-0.214077,-0.494609,-0.451072,-0.240189,-0.147489,-0.096160,0.642935,0.255774,-0.288898,0.332733,0.303413,0.573427,-0.524237,0.332524,-0.208295,0.043415,0.317282,-0.297778,-0.169658,0.201833,-0.081086,-0.184951,0.013847,0.165465,-0.016271,0.250732,0.696757,-0.406633,-0.129967,-0.018461,0.291449,-0.519715,-0.061360,0.261711,0.184169,-0.131809,0.083494,0.047116,-0.303910,-0.020207,0.197750,-0.165687,-0.718235,-0.011712,0.221697,0.194978,-0.469836,-0.064506,0.068155,-0.190536,-0.004099,0.015642,0.177595,0.260821,0.044751,0.233197,-0.134156,-0.145326,-0.567410,-0.100946,0.428253,0.110424,-0.275761,0.124658,-0.365490,-0.456575,-0.166282,-0.259110,-0.168545,-0.173448,0.477582,0.147243,0.008829,0.460062,-0.605798,0.118237,-0.206088,0.023284,-0.233225,-0.339983,-0.316001,-0.566696,-0.467916,-0.341164,-0.326058,-0.032237,0.056079,-0.244548,0.613654,-0.610781,0.113874,0.383509,0.141295,-0.418183,0.487684,0.049696,0.180338,-0.035214,-0.384755,0.382259,0.162102,0.093180,0.011644,0.171152,-0.275315,-0.055146,-0.303737,0.146404', '25828589', '21619567', '2988294', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305249', '完美盗贼', '剧情', '洛杉矶警察将正在打劫银行的乔（Bruce Willis 饰）与泰瑞（Billy Bob Thornton 饰）团团包围，断无脱身机会之时，两人昔日的经历一幕幕回放出现：崇尚行动的乔与喋喋不休的泰瑞服刑时临时起意越狱居然获得成功，两人为生计找来乔伊表弟哈维打算抢劫银行，他们打劫俄勒冈银行的奇特手法经媒体渲染后一时竟成为著名“过夜劫匪”，三人得手后分道扬镳。不久，被丈夫冷落而出走的红发女郎凯特（Cate Blanchett 饰）结识泰瑞，不知不觉融入乔一伙并与乔陷入热恋，泰瑞对凯特也颇有好感，经过笨拙的努力终于拉近了两人的距离。乔与泰瑞面临摊牌，但凯特表示他们两人在一起才是自己所爱，惬意的时光总嫌短暂，在不断打劫银行的行动中，乔和泰瑞走到了犯罪生涯的终点……本片根据真实故事改编，获2002年佛罗里达影评人协会奖最佳男主角、女配角奖。©豆瓣', '布鲁斯·威利斯', '巴瑞·莱文森', 7.5, 13068, 'tt0219965', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2529769312.jpg', 0.6, 3, 31.4, 48.3, 16.7, '0.142654,-0.121450,-0.558571,0.493979,0.209654,-0.410044,0.708110,0.005687,-0.442612,-0.333060,-0.040522,0.562090,-0.470330,0.289351,0.485073,-0.303786,-0.354918,-1.001918,-0.064584,-0.189634,-0.053424,-0.494775,-0.210337,-0.292543,-0.100853,-0.112057,0.426237,0.164531,-0.277489,0.447205,0.326574,0.191493,-0.533997,0.393401,-0.028894,0.085230,0.283681,0.027226,-0.525423,0.093904,0.056271,-0.247129,-0.219961,-0.156042,0.203635,0.300795,0.779643,-0.040185,-0.193600,0.092356,0.396530,-0.301692,-0.062776,0.028855,0.308220,0.122901,0.242878,-0.003596,-0.180943,0.118627,0.054886,-0.282564,-0.517858,0.208549,-0.028765,-0.055918,-0.432942,0.157391,0.123547,0.168287,-0.009024,-0.185795,0.044826,0.474338,0.490147,0.078455,0.060226,-0.101060,-0.433458,0.218048,0.670936,-0.160366,-0.209993,0.309707,-0.017055,-0.407011,-0.041412,-0.042418,-0.246530,-0.208509,0.576868,0.156043,0.042412,0.261506,-0.443773,-0.249081,-0.338149,-0.052861,0.064964,-0.259476,-0.015669,-0.911458,-0.231558,-0.394976,-0.238518,0.132409,-0.057345,-0.354192,0.345504,-0.595481,0.301804,0.541800,0.098838,-0.497513,0.490592,-0.109875,0.149053,-0.221384,-0.088758,0.355460,0.147259,0.030387,0.287762,0.081020,-0.329279,0.031878,-0.362636,0.272035', '25723905', '10466639',