INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305257', '金鸡2', '剧情', '时间来到了2046年，80多岁的阿金（吴君如 饰）来到了山顶，阻止了失恋青年（杜文泽 饰）服用可以删除记忆的药，并开始给他说起了自己的往事，回顾自己一生中最艰难的2003年。阿金回想到那年是香港经历“非典”的一年，每个人都人心慌慌，同时经济也受到了考验。在这一年之中，她遇到了生意失败想自杀的嫖客，遇到了努力寻找老婆的嫖客，遇到了“非典”期间走在医务前线的医生，也讲到了当年与表哥（张学友 饰）的一段情，与表哥的出卖。这些日子里充满了酸甜苦辣，但阿金还是非常庆幸自己还能拥有这些记忆。©豆瓣', '吴君如', '赵良骏', 7.3, 22290, 'tt0396030', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1590731286.jpg', 0.8, 4.7, 39.6, 40.8, 14.2, '0.137059,-0.214120,-0.413235,0.343928,-0.205479,-0.397390,0.686160,-0.334044,-0.852076,-0.291409,0.027506,0.553633,-0.129671,0.412351,0.292091,-0.105451,-0.126377,-0.708846,0.346375,-0.355355,-0.399414,-0.240769,-0.105593,-0.027099,-0.261879,-0.538102,0.371117,0.270444,0.096777,0.353634,0.068072,0.064429,0.149426,0.453501,-0.352245,0.348809,-0.067216,0.136127,-0.182262,0.206465,0.298406,-0.682168,-0.139942,0.173690,0.146731,0.364996,0.604951,0.062337,-0.348110,0.149997,0.307546,-0.311440,-0.301273,0.072268,0.313219,0.125057,0.208229,0.337221,-0.355113,0.124401,-0.203535,-0.120345,-0.657085,-0.079754,-0.087383,0.067883,-0.845111,0.460648,0.065975,0.179433,0.049135,-0.290696,0.347913,0.366353,0.233542,0.469779,-0.323927,-0.274925,-0.542166,0.508407,0.936251,-0.199651,-0.030818,0.637562,-0.079175,-0.467385,-0.061978,-0.195343,-0.363948,0.444112,0.056868,0.164494,-0.547104,0.379297,-0.625947,0.260032,-0.067225,-0.383526,0.026492,-0.300929,-0.137385,-0.286151,-0.425914,-0.630982,-0.417825,0.066659,0.010044,-0.440007,0.660285,-0.806171,0.185752,0.386408,0.375773,-0.538305,0.706440,0.032888,0.093104,-0.022989,0.275294,0.336359,-0.247859,0.353248,0.015972,0.389585,0.000636,-0.245578,-0.541584,0.452588', '25721544', '1299062', '2124718', '1304091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305261', '恐怖分子', '剧情', '老顾（顾宝明 饰）率领警察捣毁一个贼窝，唯一跳窗逃走的女孩淑安腿骨折断，被路过的男孩小强送去医院。淑安返家后，被母亲关在家中，无聊时四处打电话恶作剧，其中一个电话打给了一个叫周郁芳（缪骞人 饰）的女人，她假冒是周的丈夫在外面的女友，怀孕了要她出来谈判。周郁芬嫁给李立中（李立群 饰）已经有七年，丈夫是个安分守己的男人，在一家医院工作。结婚后她辞了工作，在家写作。匿名电话深深刺激了周郁芬，她对生活失去信心，而旧情人沈维彬（金士杰 饰）的出现也给了她希望，于是她暂时离开李立中，小说也获了奖。分居使得李立中十分苦恼，后来他得知妻子离去只是因为一个电话，急于解释但并不奏效，最后铤而走险……©豆瓣', '缪骞人', '杨德昌', 8.9, 55347, 'tt0091355', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2347245849.jpg', 0.2, 0.6, 6.6, 36.9, 55.7, '0.097739,0.123858,-0.554908,0.425485,-0.355618,-0.204542,0.718580,0.047608,-0.427382,-0.338929,-0.221159,0.685903,0.052779,0.299111,0.144168,0.071793,-0.201882,-0.505004,0.164472,-0.099159,-0.296852,-0.297813,0.113218,-0.290303,-0.026503,0.101811,0.215328,-0.013744,-0.078759,0.462452,0.171128,0.100302,0.023608,0.700474,-0.035752,0.458413,-0.068823,-0.047523,0.021622,0.298505,0.242447,-0.295787,-0.071204,0.293417,0.131513,0.379433,0.498486,0.150584,-0.213681,-0.197335,0.266532,-0.214182,-0.204069,0.070253,0.257530,0.087300,0.408136,0.022107,-0.380100,0.043077,0.071315,0.007408,-0.344828,0.104024,-0.098762,-0.056184,-0.605219,0.403284,-0.202904,0.141897,-0.015503,-0.318416,0.409769,0.278745,0.106092,0.293532,-0.214990,0.084617,-0.573906,0.292993,0.456030,-0.115736,0.219157,0.318940,-0.051968,-0.354511,0.126432,0.026755,-0.531396,0.004579,0.382400,0.010506,-0.455375,-0.395667,-0.185047,-0.169963,-0.275643,0.087601,-0.238651,-0.577011,-0.196797,-0.221624,0.002881,0.027859,-0.504323,0.098248,-0.052571,-0.181364,0.404213,-0.704436,0.196933,0.529262,0.461322,-0.719540,0.737563,0.240760,0.194036,-0.163919,0.427670,0.196830,0.092725,0.245935,0.107565,0.136734,-0.188110,-0.194698,-0.405098,0.231926', '1302384', '26718282', '2990737', '26420626');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305265', '河东狮吼', '喜剧', '月娥（张柏芝）是宋朝年间的烈女，武功了得，行侠仗义，追求专一的爱情和婚姻。一日在演诗会上偶遇一表人才的陈季常（古天乐），二人互生情愫。碰巧皇上为二人赐婚，成全了美好姻缘。但是考验二人感情的时候才刚刚开始——月娥为管住夫君，对季常管束甚严。但适得其反，季常在风流好友苏轼（许绍雄）的带领下经常去寻花问柳。月娥万般无奈，幸好用计试探，终得知季常仍深爱自己。但是，当月娥外出归来，却发现季常旧病复发，竟搭上了郡主（范冰冰）。月娥悲愤交加，喝下了忘情水。©豆瓣', '张柏芝', '马伟豪', 6.8, 188572, 'tt0368894', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p482182774.jpg', 1.3, 7.9, 49.2, 31.6, 10, '-0.112862,0.127585,-0.343459,0.479331,0.123457,-0.484292,0.253109,0.195323,-0.683276,-0.161427,0.459046,0.419666,-0.356209,0.147100,0.163665,-0.070752,-0.120333,-0.474218,0.292172,-0.191815,-0.034598,-0.265478,0.257400,0.309193,-0.291451,-0.222643,0.325701,-0.190409,0.174705,0.542795,0.148084,-0.160726,-0.153444,0.327816,0.061547,0.293657,-0.324945,0.051900,-0.482375,0.031744,0.235048,-0.348428,-0.487490,-0.031135,0.014712,0.471991,0.495670,-0.434629,-0.318660,-0.138308,0.503902,-0.123663,-0.005523,0.080176,0.005213,0.116175,0.205350,0.553758,-0.227956,-0.363141,-0.210212,-0.164341,-0.108649,0.493838,0.137804,-0.274748,-0.562301,0.596549,-0.125755,0.018816,-0.173180,-0.246477,-0.001063,0.413625,0.112703,0.351580,-0.402330,0.012052,-0.471874,0.221921,0.661626,0.028724,0.082281,0.636481,0.350244,-0.378531,0.204688,-0.291458,-0.312102,0.190807,-0.058527,0.157379,-0.252185,0.162433,-0.403514,0.065894,-0.475216,0.715881,0.286973,-0.405687,-0.001332,-0.155769,-0.276850,-0.353872,-0.545738,-0.096900,0.351519,-0.544835,0.567638,-0.802823,0.105721,0.352818,0.270772,-0.824496,0.771221,0.354345,-0.050110,-0.011420,-0.232870,0.377983,-0.285125,-0.270667,0.101776,0.158157,-0.182190,0.163576,-0.234992,-0.039624', '2124718', '3445516', '2052978', '1304091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305279', '色即是空', '喜剧', '服完兵役的高龄大学生恩植（任昌丁饰）就读于法律系，校园里满是对性充满好奇的年轻男女。可惜外表憨直的他没有什么女人缘，脑筋也是不大好使。一次偶然机会，恩植认识了学校健身俱乐部的头牌队员、校花级美女银孝（河智苑饰），他立马被对方的美貌性感吸引。恩植想尽办法接进银孝，博取好感，却都以失败告终，甚至引发许多误会，比如在公车上，他被银孝当成色狼一脚踢中要害。后来，银孝迷住了有钱的花花公子相旭（郑敏饰），甚至怀了孕，但最终被抛弃，伤心绝望。与此同时，恩植和银孝之间产关系有了微妙变化。©豆瓣', '任昌丁', '尹济均', 7.3, 115259, 'tt0341555', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1708333849.jpg', 1.2, 5.4, 37.8, 38.8, 16.7, '0.252681,-0.015838,-0.483559,0.347502,-0.446998,-0.140998,0.677770,-0.147211,-0.397794,-0.113369,0.017960,0.395927,-0.430221,0.086407,0.213885,-0.142979,0.263232,-0.487014,0.002496,-0.170355,-0.273095,-0.193234,-0.390092,0.027670,-0.227109,-0.405417,0.568019,0.051716,-0.462838,0.517341,0.446663,0.262756,0.073485,0.380070,0.011247,0.149550,0.201935,0.091766,0.073631,0.188227,-0.154487,-0.159672,-0.087105,0.116632,-0.163278,0.520629,0.572698,0.234042,-0.246482,-0.172121,0.529038,0.037568,-0.329694,0.258046,0.436511,-0.089533,0.323517,-0.098572,0.083523,-0.175006,0.314081,0.162800,-0.370582,0.097996,0.489512,-0.053049,-0.345218,0.768139,0.054102,-0.091076,-0.055541,0.155976,0.130266,-0.098901,0.228699,0.135020,0.057569,0.387957,-0.305832,0.102925,0.782413,0.168946,-0.368163,0.456727,-0.354579,-0.146492,0.177839,-0.383634,-0.453397,0.247535,0.187472,-0.006265,-0.283675,0.209918,-0.169775,-0.094735,-0.101682,0.258535,-0.141545,-0.249056,0.000916,-0.136615,-0.061643,-0.481566,-0.331258,-0.040270,0.033953,-0.149385,0.605731,-0.803155,-0.031171,0.367262,0.181151,-0.503589,0.788101,0.159737,-0.213728,-0.111259,-0.392955,0.027592,-0.012350,-0.192864,-0.065831,0.404731,-0.281754,-0.413475,-0.140939,0.385635', '35030151', '3445516', '1304989', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305294', '幸福的黄手帕', '剧情', '煤矿工人勇作（高仓健）失手将一名寻衅滋事的流氓打死后，被判刑入狱，在监狱里，他非常想念自己的妻子光枝（倍赏千惠子），却因害怕耽误她的生活和前途，主动提出离婚，并真心实意地劝她改嫁。刑满释放前，勇作给光枝写了一封信，说如果她还没有与他人结婚，仍在等待着他的归去，就在家门前的旗杆上挂上一块黄手帕，假如他看不到黄手帕，会就此远走他乡。归家途中，患得患失的勇作碰到一对驾车出行的年轻情侣（武田铁矢、桃井薰），搭乘他们的车游转了一些地方，之后，他才鼓足勇气回到家乡。©豆瓣', '高仓健', '山田洋次', 8.2, 12989, 'tt0076935', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1864688186.jpg', 0.3, 0.8, 16.8, 52.5, 29.6, '0.327509,0.056158,-0.751436,0.428164,-0.101220,-0.437347,0.919852,0.190598,-0.138378,0.011143,0.173671,0.770891,-0.081271,0.453820,0.150441,0.124314,-0.361201,-0.643419,0.140648,-0.131796,-0.248114,-0.285439,0.041562,0.146810,-0.386757,0.138544,0.550013,-0.006527,0.035402,0.536768,0.221694,-0.009398,-0.023640,0.517702,-0.346476,0.296287,-0.136253,0.377392,0.045363,0.169677,0.123621,-0.422587,-0.044536,0.139356,0.097185,0.411176,0.594091,0.048103,-0.253541,-0.088455,0.152478,-0.392286,0.046581,0.222452,0.347486,-0.037504,0.113939,0.319048,-0.549039,0.025042,0.003466,0.089492,-0.344257,-0.040245,-0.035279,0.046450,-0.712933,0.453268,-0.112601,0.075155,0.047834,-0.389796,0.230664,0.320427,-0.021285,0.195306,-0.206772,0.064216,-0.412120,0.192052,0.543553,-0.242684,0.150557,0.219863,-0.011871,-0.184140,0.274089,-0.141379,-0.785644,-0.100956,0.204723,-0.006045,-0.449976,-0.292309,-0.249161,-0.080638,-0.311059,0.059645,0.014050,-0.217642,0.074578,-0.349795,0.326406,-0.448047,-0.621327,0.155454,-0.015243,-0.205730,0.264240,-0.475305,0.382138,0.500110,0.482324,-0.496456,0.512550,0.380474,0.083272,0.017234,0.163589,0.240178,0.143710,0.437677,0.273829,0.178785,0.020285,0.100381,-0.223948,0.558755', '3111650', '25917973', '1292217', '1297606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305306', '心慌方2：超立方体', '科幻', '8个身份不同且互不相识的陌生人在同一时间醒来，发觉自己身处在一个立方体形状的房间内，没有人记得他们是怎么来到这的，也没有人知晓自己身处何方。几个人经过调查发现，立方体的上下左右四个面各有一道门，联通着另外一处相同的立方体，而不同的只是各个房间内的机关陷阱。整个建筑的结构 仿佛一个布满危机的魔方大厦，并且充斥着现代科学难解的超自然现象，8人历尽千难万险，陆续有人横遭不测，究竟谁才能从噩梦中挣脱？本片是小成本高口碑加拿大科幻惊悚片《立方体》（又名异次元杀阵）时隔四年后的续集，由好莱坞B级片王者狮门影业制作发行。影片延续了前代的故事架构，并进一步的引入了四维空间的概念，使得电影整体风格更加抽象和奇特。©豆瓣', '卡瑞·玛切特', '安德列·塞库拉', 6.8, 61866, 'tt0285492', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2199854810.jpg', 2, 10.6, 44.9, 31.1, 11.4, '0.197077,-0.011883,-0.803755,0.687189,0.151667,0.189140,0.974353,0.140833,-0.660992,-0.427785,0.314443,0.740802,-0.305260,-0.044388,-0.179992,-0.050296,-0.207000,-0.426142,-0.382988,-0.425108,-0.522358,-0.303878,-0.484237,-0.123297,0.015911,-0.191228,0.673782,0.218960,-0.414885,-0.043501,-0.037839,-0.064392,-0.559830,0.244301,-0.146490,0.029055,0.079429,0.089940,-0.199623,0.098999,-0.353861,-0.172190,-0.215470,0.114197,-0.372987,0.390359,0.695736,-0.457350,-0.098432,0.123810,0.590166,0.046970,-0.417392,0.001914,0.295039,0.148585,0.186132,0.010911,-0.197446,0.193091,0.075659,-0.308299,-0.844281,-0.086043,0.214490,0.356673,-0.374420,0.351055,0.010078,-0.313776,-0.307607,-0.388973,0.141929,0.206433,0.456203,0.487078,-0.031527,-0.129832,-0.718911,-0.038866,0.595734,0.106864,-0.679238,0.466408,-0.224743,-0.627967,-0.617492,-0.153419,-0.297691,-0.041886,0.424870,0.091863,-0.212609,0.061155,-0.752040,0.246316,-0.087592,-0.184898,-0.129525,-0.274726,-0.160696,-0.697204,-0.434189,-0.305288,-0.152209,0.146242,-0.189094,-0.105997,0.542626,-0.795964,0.216433,0.453681,0.089713,-0.282338,0.847082,-0.177296,-0.061395,-0.362446,-0.187449,-0.010352,0.111461,0.299040,-0.094476,0.473371,0.094483,-0.144932,-0.608714,0.215761', '3055049', '26715845', '35360296', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305308', '反斗神鹰', '喜剧', '出色的飞行员托伯•夏利（查理•辛 Charlie Sheen 饰）因违抗命令离开海军后，准备在印第安部落享受余生，然而海军突然将其召回参加一项名为“臭鼠”的任务。关于海军，托伯有太多回忆，他的父亲曾在飞行时失误导致同侪身亡，这成了托伯无法摆脱的心结，军中心理医生戴美达（瓦莱莉•高利诺 Valeria Golino 饰）出色的马术和体操给托伯留下了深刻印象，但这个美人却劝说精神状态不良的托伯退出。而托伯的被重新征召其实是军火商的一项邪恶计划，他们串通军中人士，准备利用托伯脆弱的心理造成飞机失事，以此要求政府升级机型。不久果然有飞行员坠机，但军火商并未达成所愿，他们继续在托伯和战友的任务中安插障碍……©豆瓣', '查理·辛', '吉姆·艾布拉姆斯', 7.3, 15060, 'tt0102059', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1338699344.jpg', 1.1, 6.3, 37.7, 38.9, 16.1, '0.244977,0.034111,-0.637426,0.554724,-0.033514,-0.200093,0.283072,0.033344,-0.585225,-0.408462,0.037161,0.558660,0.160481,-0.110937,0.282836,-0.279256,-0.417757,-0.569270,0.175714,-0.158633,-0.339675,-0.593662,-0.134051,-0.397824,-0.141293,-0.498491,0.689510,0.070854,-0.331369,0.459628,0.142320,0.539838,0.051631,0.462189,-0.117618,-0.131921,0.193546,-0.255174,-0.398041,0.217116,0.100492,-0.295641,0.056163,0.208079,0.092158,0.531036,0.706605,-0.405597,-0.211579,-0.106149,0.220748,-0.427453,0.237183,-0.013585,0.249399,0.174212,-0.146149,0.172047,-0.149510,-0.025803,0.143637,-0.092713,-0.821592,-0.286491,0.179094,-0.165100,-0.450369,0.404704,-0.290829,0.202392,-0.060370,-0.093530,0.105417,0.597213,0.232755,0.146477,-0.110529,0.306376,-0.295365,0.325702,0.675914,-0.111833,-0.261951,0.081839,-0.220684,-0.593644,0.060483,-0.476319,-0.199443,0.079997,0.308726,0.178729,-0.108661,0.128160,-0.518076,-0.096586,-0.491683,-0.304409,-0.038513,-0.256711,0.061181,-0.670098,-0.061857,-0.056860,-0.206717,0.131726,0.184788,-0.103670,0.619145,-0.886818,0.243870,0.515913,0.285304,-0.602232,0.495352,0.029071,0.331556,-0.113278,0.030142,0.108747,0.047692,0.099720,0.077553,0.152455,0.014605,-0.262667,-0.144810,0.093842', '1793491', '1420088', '1292829', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305309', '反斗神鹰2', '喜剧', '海湾战争导致一批美国军人与平民被伊拉克俘虏，美国总统汤玛斯·本森（劳埃德·布里奇斯 Lloyd Bridges 饰）亲自下令解救人质，然而无厘头枪战过后，是营救队反被俘虏。距离总统大选只剩十天，于是人质能否得救尤显紧要，传奇英雄托伯•夏利（查理•辛 Charlie Sheen 饰）临危受命，自远东丛林回国又匆匆前往波斯湾营救同胞，在出发前，将参与此次秘密营救的CIA美女米歇尔与托伯激情相聚，为英雄的情史再添华彩。一行人抵达中东，与担任联络员的戴美达（瓦莱莉•高利诺 Valeria Golino 饰）汇合，托伯重逢旧爱，然而却因人质中有戴美达的丈夫德达（罗温·艾金森 Rowan Atkinson 饰）而不能逾礼……©豆瓣', '查理·辛', '吉姆·艾布拉姆斯', 7.6, 9966, 'tt0107144', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2327819439.jpg', 0.8, 3.7, 30.9, 43.4, 21.1, '0.026140,0.019111,-0.436405,0.219375,0.355815,-0.313783,0.184980,0.094610,-0.334575,-0.373965,0.027644,0.563785,-0.139405,-0.145810,0.560927,-0.045070,-0.500138,-0.603707,0.108994,-0.158363,-0.101061,-0.425562,-0.011279,-0.277503,0.022480,-0.310985,0.556131,0.212307,0.067680,0.570342,0.457637,0.518692,-0.384672,0.436078,-0.029390,-0.237667,0.414814,-0.290781,-0.723778,0.272108,-0.121964,-0.200020,-0.019306,0.047183,0.008439,0.397728,0.636592,-0.206158,0.380519,-0.256986,0.009045,-0.357071,0.288805,-0.127932,0.237303,-0.032735,-0.045844,0.319223,-0.079381,-0.005907,0.060532,-0.248724,-0.313617,0.168584,-0.140049,0.037417,-0.418713,0.265135,-0.350874,0.192952,0.166273,0.022007,0.199430,0.539879,0.220813,-0.003119,0.131219,0.014236,-0.420444,0.116779,0.709128,-0.227355,0.100340,-0.009911,0.158384,-0.544862,0.393570,-0.397891,-0.171332,0.122346,0.220957,-0.141521,0.251315,0.116858,-0.597419,-0.208396,-0.736770,-0.021290,0.244459,-0.174376,0.030683,-0.720627,0.098729,-0.007643,-0.153071,0.345294,0.185274,0.212049,0.307063,-0.326422,0.169659,0.468051,0.474470,-0.409493,0.504373,0.148800,0.375181,-0.341987,0.134558,0.378104,0.321097,0.080344,0.208479,-0.171645,-0.246629,-0.218036,-0.059885,-0.141943', '3036464', '3871833', '3147969', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305324', '鬼水怪谈', '剧情', '虽然渴望幸福美满的家庭，但松原淑美（黑木瞳 饰）和丈夫滨田邦夫（小日向文世 饰）的婚姻仍旧无可避免地走向破败边缘。经过一番令人精疲力尽的拉锯战，淑美总算取得了5岁女儿郁子（菅野莉央 饰）的监护权。在此之后，母子二人通过中介搬到一所便宜、老旧的公寓，准备展开全新的人生。她们的生活起初充满快乐，但一切很快朝怪异的方向发展。莫名其妙的渗水、怪异莫测的声响时时刻刻困扰着母子二人，甚至郁子也开始出现奇怪的举动。似乎，有一个阴森的幽灵正慢慢侵入淑美母子的生活之中……本片根据鈴木光司的短篇作品改编，并荣获2002年布鲁塞尔国际奇幻电影节银鸦奖。©豆瓣', '黑木瞳', '中田秀夫', 6.9, 11567, 'tt0308379', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2407089202.jpg', 1.3, 7.1, 48.7, 33.6, 9.3, '0.248697,0.082157,-0.493661,0.469180,0.192152,-0.323250,0.780658,0.132833,-0.582505,-0.202109,0.383701,0.307411,-0.346512,0.187847,0.357600,0.147856,-0.398672,-0.513068,-0.162857,-0.033517,-0.012689,-0.313111,-0.262476,-0.212880,-0.034471,-0.281543,0.522808,0.238581,-0.009677,0.618571,0.084244,0.182796,-0.551324,0.374936,0.085823,-0.000461,-0.077297,0.264272,-0.379018,0.009869,-0.076740,-0.213713,-0.282912,0.042947,-0.002108,0.303993,0.864801,-0.305883,-0.348446,0.004434,0.562561,0.042176,-0.343311,0.340975,0.020503,0.244984,0.169820,-0.008068,-0.314561,-0.028014,-0.033765,-0.165842,-0.568363,0.243116,0.298227,0.094933,-0.221354,0.611519,0.031382,-0.105955,0.129230,-0.204945,0.122770,0.455455,0.515556,0.741658,-0.393275,0.409101,-0.281705,0.044822,0.540199,0.256697,-0.333274,0.272525,-0.485769,-0.460988,-0.242437,0.026674,-0.395054,-0.153254,0.439530,0.274926,0.059768,0.143248,-0.740511,0.274372,-0.065194,-0.203780,0.166654,-0.403031,0.013610,-0.719226,-0.120686,-0.447417,-0.334170,0.115775,-0.134909,-0.295044,0.569504,-0.401454,0.299342,0.226774,0.245364,-0.234013,0.421154,0.005984,-0.021579,-0.222217,-0.436863,0.387070,-0.336209,0.220005,0.006198,0.386981,-0.401654,-0.119530,-0.473823,0.449312', '10466639', '4706257', '2365260', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305327', '青梅竹马', '剧情', '少年棒球队国手出身的布店老板阿隆（侯孝贤饰），他和阿贞是青梅竹马。阿贞（蔡琴饰）是某企业的高级助理员工，她总是期想着能够尽快结婚移民美国，改变目前的生活处境，向往着美好未来。阿隆乐于帮助别人，像开出租车的少棒朋友阿钦（吴念真饰）等等。他有着浓郁的怀旧情结，常去棒球场边观看。面对周围激烈变化的社会，阿隆和阿贞交往的是不同人群，彼此不可避免地渐有远离，感情出现了裂缝。后来，阿隆被爱慕阿贞的一个年轻人刺伤，独自坐在路边等待。逐渐昏迷中，他仿佛重新看见了参加少棒比赛的记忆画面。©豆瓣', '侯孝贤', '杨德昌', 8, 21188, 'tt0089866', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2446309121.jpg', 0.2, 1.2, 20.5, 54.2, 23.8, '0.266340,-0.072829,-0.443698,0.412914,-0.031369,-0.119089,0.666544,0.270289,-0.456974,-0.277112,0.169546,0.673992,-0.144138,0.445228,0.145427,-0.255636,-0.241865,-0.610445,-0.095713,0.105480,-0.261582,-0.348847,-0.331636,-0.135361,-0.220230,-0.322535,0.681449,0.189811,-0.229309,0.602106,0.079046,0.261840,-0.221438,0.345745,-0.098228,-0.171362,0.222761,0.070130,-0.580924,-0.027024,-0.150159,-0.020028,0.010525,-0.064784,0.085047,0.175926,0.606927,0.027746,-0.089643,-0.022840,0.224037,0.130915,-0.146201,0.158355,0.187375,0.227665,0.166761,-0.090603,-0.025600,-0.212486,-0.231557,-0.078417,-0.266540,0.014094,0.107958,0.358804,-0.399179,0.398730,0.137524,-0.201200,0.198939,-0.213406,0.280647,0.186017,0.208504,0.190943,-0.070368,0.082794,-0.323362,0.065514,0.751331,0.136844,-0.226211,0.300016,-0.436452,-0.163730,0.057978,-0.232154,-0.427051,-0.005047,0.163940,-0.000713,-0.261765,0.264012,-0.333926,0.153182,0.166328,-0.161147,0.182916,-0.384474,-0.075475,-0.506162,-0.303646,-0.524627,-0.211436,-0.035868,-0.279734,-0.350000,0.794654,-0.804006,0.113772,0.528339,0.425621,-0.338140,0.757525,-0.090534,0.083158,-0.243246,-0.171748,0.359913,-0.330748,0.076004,-0.182714,0.240375,-0.165915,0.098984,-0.349945,0.409105', '3445516', '35030151', '3811356', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305333', '终结者3', '动作', '故事发生在《终结者2》10年之后，终结者又回来了。此时John Connor(Nick Stahl) 饰)已经22岁，他的母亲去世后，他过着隐姓埋名的生活，不愿意面对即将到来的命运。但是，命运并不以他的意志为转移，“天网”经历了两个失败之后，派出了更为先进的T-X终结者（Kristanna Loken 饰）来追杀他，人类也同样送回了T-800改良后的终结者T-850（Arnold Schwarzenegger饰）保护John。John巧遇了儿时的伙伴，兽医Kate Brewster（Claire Danes 饰)，Kate的父亲是美国军方“天网”系统的负责人，她本人也将成为人类叛军的副统领，理所当然成了T-X的打击对象。二人在T-850的保护下，开始了逃亡之路。同时，美国电脑系统病毒入侵，人类束手无策之下准备启用“天网”，一旦“天网”接管美国军方防御系统，人类将首当其冲的被消灭。面对已经发生的未来，John Connor和Kate Brewster决定奋起反抗，在T-850的帮助下，他们将又一次改变人类的命运。', '阿诺·施瓦辛格', '乔纳森·莫斯托', 7.4, 118361, 'tt0181852', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p818710721.jpg', 0.4, 3.7, 38.1, 42.3, 15.6, '0.163863,0.305067,-0.701288,0.629122,-0.222693,-0.101891,0.696337,-0.070910,-0.478628,-0.206509,0.265502,0.751712,0.149245,0.191690,0.217738,-0.156496,-0.291289,-0.722335,-0.177650,-0.079734,-0.573241,-0.319026,-0.399933,-0.193415,0.018204,-0.455747,0.936417,0.117723,-0.272674,0.186110,0.217717,0.335127,-0.017035,0.639319,-0.082535,0.033716,-0.045351,-0.109433,-0.312331,0.409457,-0.013942,-0.452955,0.166139,0.505550,-0.283434,0.343573,0.777691,-0.565953,-0.155007,-0.510715,0.386766,-0.562545,-0.022372,0.108191,0.492304,0.203760,-0.158634,0.339430,-0.169487,0.150401,-0.039655,0.112587,-1.128163,-0.093994,0.067546,-0.075707,-0.806859,0.286101,-0.143509,0.263467,-0.141925,-0.621667,0.297669,0.842026,0.389776,0.318114,-0.333064,0.143050,-0.540380,0.152330,1.057139,-0.212617,-0.381128,0.233082,-0.005372,-0.430384,-0.151613,-0.591751,-0.437387,0.076426,0.250724,0.345950,-0.248166,0.391743,-0.686722,-0.123626,-0.444891,-0.304289,-0.006674,-0.491827,0.169088,-0.610964,-0.245792,-0.364739,-0.450756,0.182278,0.063395,-0.224311,0.771357,-0.957392,0.144607,0.590706,0.549565,-0.819418,0.485037,0.062820,0.250156,-0.177393,0.400472,0.244189,0.123056,0.682518,0.119769,0.212674,0.220406,-0.163213,-0.250756,0.492809', '26678784', '1811755', '30163500', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305337', '他人之子', '剧情', '儿子的意外被杀让奥利维（奥利弗·古尔迈 Olivier Gourmet 饰）陷入了深深的痛苦之中，他一生都会记住这个混蛋，即便他也只是一个少年，即便他即将为自己的所作所为付出代价。时间匆匆流走，五年后，奥利维与一个名叫弗朗西斯（摩甘·马林纳 Morgan Ma rinne 饰）的男孩相遇了，而这位弗朗西斯不是别人，正是曾经杀害他儿子的凶手。弗朗西斯并没有认出奥利维，但这重逢却触痛了奥利维的心，也勾起了他心中压抑已久的感情，在一番波折和纠结之后，弗朗西斯成为了奥利维的“学生”，跟随着他学习木工。随着时间的流逝，一直以来形单影只的弗朗西斯在奥利维的身上看见了父亲的影子，而内心充满了痛苦的奥利维则选择说出了那个充满了毁灭性的秘密。©豆瓣', '奥利维埃·古尔梅', '让-皮埃尔·达内', 8.1, 5535, 'tt0291172', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2183209196.jpg', 0.3, 1.6, 18.8, 52.4, 26.9, '0.172458,0.090373,-0.877198,0.669762,-0.444683,-0.830169,1.238247,-0.037905,-0.738875,-0.252882,-0.015764,0.764086,-0.148105,0.202815,0.303119,0.103718,-0.279025,-0.843447,-0.198732,-0.473421,0.003591,-0.416737,-0.176442,-0.262065,-0.048146,-0.366989,0.610719,0.276654,0.036279,0.595851,0.457884,0.333157,0.259701,0.684103,-0.118382,0.130352,0.234652,-0.024566,0.005381,-0.029103,0.399335,-0.330806,-0.129544,0.472639,-0.350508,0.509376,0.449259,-0.292483,-0.158201,-0.110604,0.244040,-0.495702,0.006938,0.132751,-0.009313,0.015554,0.298333,0.195865,-0.295374,0.053922,0.022208,0.174465,-0.857732,0.028183,-0.058272,0.100459,-0.687212,0.652977,-0.100258,-0.386013,0.039840,-0.286529,0.303842,0.299499,0.457181,0.151945,-0.604053,-0.197200,-0.392744,0.039172,0.676887,-0.127322,-0.087518,0.345206,-0.268717,-0.425757,0.005625,-0.067471,-0.494193,0.023968,0.425833,0.341858,-0.385438,0.481880,-0.317759,-0.248595,-0.322032,-0.350866,-0.215785,-0.664881,-0.163792,-0.267381,-0.419310,-0.503296,-0.532119,0.005279,-0.129238,-0.308479,0.561339,-0.897262,0.472534,0.539152,0.298844,-0.222867,0.641880,0.254451,0.047263,-0.016685,-0.091382,0.458574,-0.150913,0.185762,0.193232,0.452070,0.101699,0.094181,-0.434931,0.886680', '1292211', '1417428', '2131640', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305343', '杀妻2人组', '喜剧', '阿B（钟镇涛饰）、阿发（周润发饰）都是足球好手。阿发来自大马，有个美丽风流的太太（王祖贤饰），常与男生调笑，令阿发又妒忌又焦虑。阿B的太太（梅艳芳饰）则是个脾气暴燥的女人，她时常埋怨阿B没有出息，而且还常常当众奚落他，使阿B面子尽失，自尊心受到伤害。一次阿B受可太太的气，到酒吧饮闷酒，遇到由大马来港的阿发，阿发也是不满太太对其他的男人太热情，还怀疑她红杏出墙。阿B、阿发互吐心事后，更觉同病相怜，大家酒醉后竟然发起杀妻之念，二人更密谋出不同的杀妻方法，其中尽情地发挥了小气男人的妒忌妻子的梦幻式惩治杀妻方法，可谓洋洋大观，笑话连篇。二人兴头一起，于是达成口头协议，二人各去对方家里杀掉对方的妻子......©豆瓣', '周润发', '钟镇涛', 6.5, 6561, 'tt0091935', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541795075.jpg', 1.5, 11.1, 56.4, 22, 9.1, '0.149723,-0.009827,-0.441544,0.561202,0.019028,-0.580675,0.575968,0.182321,-0.207667,-0.106579,0.234629,0.102281,-0.165437,0.137632,-0.009681,-0.292259,-0.186040,-0.372250,0.302214,0.019478,0.214459,-0.356968,0.261074,-0.185899,-0.280878,-0.312329,-0.081860,-0.274187,-0.357552,0.086081,0.503164,0.176920,0.147139,0.656821,-0.074537,0.222235,-0.173170,0.028942,-0.151511,-0.047228,0.245424,-0.077747,-0.110596,0.189887,0.020148,0.183272,0.701528,-0.141622,-0.171700,-0.439076,0.347226,0.000494,0.149322,0.195693,0.217125,-0.308995,0.286280,-0.266277,0.100790,-0.084454,0.304591,0.215387,-0.260335,0.027002,0.340886,-0.179189,-0.235588,0.159770,-0.106355,0.009537,-0.148414,-0.042873,-0.019220,-0.161600,0.433974,0.297086,-0.080827,0.272659,-0.469048,-0.140986,0.640131,0.166524,0.163201,0.006174,-0.412273,-0.439423,0.276683,-0.259791,-0.513600,0.053465,0.188319,-0.257612,0.222344,0.369253,-0.417185,-0.076404,-0.043912,0.503093,0.006327,-0.453741,0.251414,-0.289976,-0.062569,-0.288852,-0.102573,0.127538,0.436662,0.068995,0.430586,-0.325641,0.153212,0.388096,0.329671,-0.497916,0.546965,0.442109,-0.122816,-0.292870,-0.298338,-0.035348,-0.169656,-0.327974,0.195210,0.335886,-0.006877,0.070459,0.217066,0.134143', '1310175', '1917577', '1304309', '3036997');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305355', '审死官', '喜剧', '宋世杰（周星驰 饰）是一个清朝时期的著名大状，他出色的口才及能力让他敢于批评衙门的大官，也为很多人伸冤。就算他不满当时官场的腐败黑暗，但他还是收了不少贿赂，部分还是昧心钱，都报应在了自己的儿子上，十多个儿子都养不大。妻子（梅艳芳 饰）为了腹中的孩子，断然要求他就此封笔，不可再做大状。虽然宋世杰极其不愿意，还是答应了妻子的要求。妻子遇到了满肚冤情的寡妇（吴嘉丽 饰），处于对女人的同情，她要求丈夫宋世杰为这名寡妇打官司，因此宋世杰又被迫重出江湖。在为寡妇伸冤的过程中，他再次看到了官场的黑暗，还差点抄家、送命……©豆瓣', '周星驰', '杜琪峰', 7.9, 199421, 'tt0105385', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2265204834.jpg', 0.2, 1.7, 26.3, 47.3, 24.4, '-0.040468,0.142857,-0.575289,0.579917,-0.549492,-0.437411,0.625773,0.316922,-0.613391,-0.124373,0.344520,0.758298,0.171940,0.059642,-0.073688,-0.041816,-0.052724,-0.532053,0.084256,-0.095693,-0.221322,-0.386051,-0.053162,-0.265792,-0.437752,-0.118110,0.433935,0.063875,-0.089817,-0.129543,0.519991,0.184833,0.278508,0.510914,-0.334773,0.146138,-0.064517,-0.050045,-0.088853,-0.017189,0.035294,-0.462746,-0.217857,0.240898,-0.102705,0.452579,0.527873,0.027684,-0.291248,-0.237116,0.343463,-0.213952,-0.043608,0.268181,0.161364,-0.296019,0.464841,0.388755,-0.066027,-0.076145,0.095825,0.205082,-0.913384,0.067892,0.220673,0.001025,-0.696886,0.469783,-0.227352,0.036692,-0.129885,-0.248526,0.164220,0.101864,-0.007402,0.367494,-0.479589,0.062898,-0.496626,0.558708,0.391151,0.161410,0.018829,0.253077,-0.277123,-0.498766,0.256866,-0.451960,-0.656706,0.023011,0.196262,0.000596,-0.445977,0.245120,-0.306454,-0.072508,-0.205607,0.027745,-0.060201,-0.346743,0.207690,0.095111,-0.116916,-0.339609,-0.514519,-0.061745,0.318943,-0.103320,0.686138,-0.499133,0.059889,0.555466,0.309907,-0.802679,0.690063,0.353640,0.181407,-0.077801,-0.171321,-0.089852,0.036519,0.136983,0.083838,0.240645,0.280761,-0.538331,0.046988,0.596682', '30163500', '26678784', '3785918', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305363', '站直啰，别趴下', '喜剧', '老实巴交的作家高文（冯巩 饰）搬入新居，却碰上一个骠悍蛮横混不吝的邻居张勇武（牛振华 饰）。在此之前，张勇武夫妇因各种纠纷已经赶走四位邻居，如今在这栋楼里基本没人敢和他对着干。得知高文的职业，张对高一家还算客气，随后却因养狗扰民的问题和隔壁的刘干部（达式常 饰）发生冲突。不久，张勇武辞职回家，下海做起龙鱼的生意，生活水平直线提高。刘干部怀疑其从事不法活动，派女儿以找工作的名义到张家侦查。一段时间过去，张勇武的生意越做越火，刘干部还与这个昔日对头尽释前嫌，共同发财。高文将一切看在眼里，却又无法置身事外……©豆瓣', '达式常', '黄建新', 8.3, 22192, 'tt0108651', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2376169141.jpg', 0.1, 0.7, 14.3, 53.3, 31.6, '0.035814,0.129731,-0.563981,0.693270,-0.407105,-0.436196,0.530817,0.201399,-0.349873,-0.524680,-0.228700,0.279670,0.050531,0.569316,0.045568,-0.593373,0.012791,-0.489686,0.123262,0.045095,-0.018174,-0.462864,-0.241567,-0.316344,-0.434795,0.153866,0.151646,0.110583,-0.430179,0.216875,0.483122,-0.078346,-0.103567,0.280304,-0.200096,-0.095913,-0.217216,0.205226,-0.380266,-0.381988,-0.021963,-0.294140,-0.257435,-0.339846,0.579656,0.414362,0.422912,0.252939,-0.279373,0.021692,0.287540,0.086177,0.067366,0.058378,0.952798,-0.024179,-0.055053,-0.094183,-0.280928,-0.006151,-0.211451,-0.177600,-0.515352,0.022495,0.105187,-0.216425,-0.746289,0.121585,0.038891,0.138162,-0.193921,-0.343598,-0.150683,0.277130,0.079049,0.560143,0.287450,0.486822,-0.357266,0.322326,0.713520,0.160807,-0.068089,-0.239069,-0.005991,-0.536774,0.055797,-0.350691,-0.245438,-0.144985,0.371376,-0.364276,0.186955,-0.017333,-0.412631,-0.169981,0.021166,0.017951,0.213070,-0.093423,0.382874,-0.764158,0.018773,-0.519549,0.026648,0.364171,0.353237,-0.279352,0.363139,-0.488421,-0.235905,-0.153961,0.145965,-0.988063,0.604100,0.082001,0.382889,-0.255228,-0.107219,-0.189055,0.545003,0.156184,0.338690,0.240866,-0.026670,-0.261817,0.025561,0.329639', '1307577', '1297710', '1302110', '1482541');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305364', '烈火青春', '剧情', 'Pong（汤镇业 饰）在泳池认识了美丽可爱的Kathy（夏文汐 饰），几次见面之后两人迅速坠入了热恋。而Kathy有个在音像店打工的弟弟Louis（张国荣 饰）则邂逅了Tomato（叶童 饰），两人也成了一对情侣。四个青年人经常在一起作乐。不久，Kathy的前男友，日本人信介（翁世杰 饰）回到了香港。信介原来是日本的一个秘密组织“赤军”的成员，现在退出了，恐怕会遭到组织的追杀。Tomato在工作的时候认识了一个日本的女模特，女模特也迅速结识了Kathy等人。一次，数人相约一起出游，却没想到，这是一场血腥屠杀的开始......©豆瓣', '张国荣', '谭家明', 7.5, 6965, 'tt0084248', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2356944494.jpg', 1, 4.5, 33.3, 41.5, 19.7, '0.418530,-0.236332,-0.800283,0.446216,-0.133558,-0.436020,0.725598,0.306415,-0.490248,-0.007254,0.317975,0.892912,-0.488419,0.296469,0.303595,-0.134309,-0.081972,-0.862172,-0.123951,-0.299083,-0.370335,-0.170405,-0.117258,-0.105269,0.085074,-0.248814,0.326894,0.081659,0.090287,0.862321,0.521606,0.005443,-0.351711,0.423590,-0.278708,-0.008005,0.423852,0.200286,-0.229460,0.471348,-0.336558,-0.376492,0.023882,-0.206879,-0.109040,0.338407,0.943219,-0.038767,-0.132775,-0.059922,0.294997,-0.057272,-0.364642,0.103344,0.703457,-0.178452,0.416710,-0.101626,-0.277790,0.140500,0.158422,0.021214,-0.472529,0.330885,0.076957,0.208679,-0.681859,0.722694,0.193989,-0.117425,0.061397,-0.204153,0.310431,0.654768,0.247479,0.350876,0.087583,0.051166,-0.517375,0.406003,0.976861,0.083985,0.105071,0.520059,0.093815,-0.281651,-0.115266,0.074058,-0.309798,0.043300,0.476812,-0.443664,-0.277819,-0.083210,-0.912047,-0.017052,-0.193953,-0.040864,0.099692,-0.333694,-0.072768,-0.844863,-0.207737,-0.360762,-0.254207,0.398818,-0.098431,0.022198,0.855388,-0.982284,0.128969,0.628144,0.204721,-0.685263,0.688293,0.155898,-0.096380,-0.172911,0.239553,-0.040617,0.142978,0.181431,0.285139,0.603648,-0.235763,-0.100382,-0.421266,0.054844', '1292219', '26687241', '11541282', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305366', '鸦片战争', '剧情', '英国源源不断的鸦片输入令道光皇帝感到江山岌岌可危，虽害怕列强，他还是下诏委派湖广总督林则徐（鲍国安）为钦差大臣前往广州禁烟。但腐败官吏与英国商人的勾结将鸦片贸易变得错综复杂，林则徐的禁烟行动从一开始就面临重重困难，英国商人一面假装听命林则徐，一面策划更大的阴谋。道光十九年六月三日，林则徐在虎门海滩指挥销烟，百姓拍手称快。英国回国商人拿此事大做文章，装备精良的英军从珠江口直下塘沽，对华宣战。软弱无能的道光不派兵应战，反把一切怪罪到林则徐头上将他撤职，又派直隶总督琦善（林连昆）为钦差大臣前去与英方讲和，酿成历史悲剧。©豆瓣', '鲍国安', '谢晋', 7.6, 7468, 'tt0120538', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2608070151.jpg', 0.7, 2.2, 32.8, 46.1, 18.2, '0.095362,0.115574,-0.416722,0.551230,0.135741,0.160608,0.183992,0.351231,-0.699675,0.212738,0.238741,0.708365,-0.252969,-0.490883,0.160272,0.033371,-0.288145,-0.737205,-0.131116,-0.063532,0.171823,-0.499280,0.051248,-0.336386,-0.432740,-0.031465,0.673531,0.476226,-0.023404,0.331139,0.208316,0.128445,-0.041725,0.632298,-0.054861,-0.245722,-0.259733,-0.325833,-0.241490,-0.079490,0.262818,-0.799780,-0.221413,0.202620,0.065638,0.281066,0.283615,-0.273111,0.156172,-0.198399,0.333895,-0.474018,-0.076848,0.219509,0.589735,0.440533,-0.433789,0.473851,-0.238519,-0.171847,-0.094246,0.037160,-0.057064,-0.091550,0.010581,0.041721,-0.385804,0.238460,-0.388487,0.253758,-0.004901,-0.456254,0.083726,0.639220,-0.092124,0.212902,-0.146945,-0.000753,-0.374540,0.296072,0.633307,-0.190954,-0.052181,-0.532833,0.025513,-0.055548,0.388582,-0.143489,0.078260,-0.129012,0.269731,-0.527085,0.142159,0.472620,-0.507888,-0.123988,-0.553576,-0.211570,0.224333,0.060560,-0.030922,-0.320452,-0.104987,-0.005731,0.088616,-0.037648,0.507343,0.209472,0.392081,-0.358058,-0.164992,0.521383,0.484681,-0.711283,0.396190,0.303852,0.062442,-0.094265,0.062985,-0.009537,0.338287,0.463269,-0.031095,0.063663,-0.148713,-0.159035,0.199730,0.019850', '1366853', '34906611', '1305837', '1302705');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305386', '无限复活', '剧情', '李伯仁（郑伊健 饰）是澳门赌场的服务生，由于他技巧高超，所以两年来他的桌子一直赢钱，从未输过。不过，伯仁不甘心做一个小喽啰，希望能有朝一日去赌城拉斯维加斯风光。可是，当他把这个梦想告诉同伴，却遭到对方一阵奚落。偏偏此时，他又被女友抛弃，走投无路之际，他要同伴将保险箱的钱借给他做赌资，同伴开始并不同意，后被他慷慨激昂的演说打动，铤而走险。他们来到赌城，手风很顺，可到了终盘，却被一个长发男子击败。心灰意冷的伯仁接连遭遇不测。一场车祸后，伯仁在医院醒来，此时他见到了负责此案调查的美丽女干探提娜（张柏芝 饰）。在交往中，伯仁揭穿了提娜男友真面目，导致二人分手。与此同时，他们的命运竟然也因红番回头石而发生了翻转……©豆瓣', '郑伊健', '刘镇伟', 7.1, 14073, 'tt0286057', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p482190945.jpg', 1.2, 6.3, 40.4, 38, 14.1, '0.095343,0.195488,-0.611280,0.067943,-0.337196,-0.237502,0.799640,0.104030,-0.404057,-0.161075,0.169779,0.723003,-0.135378,0.228441,-0.040023,0.040986,-0.054048,-0.732641,0.092543,-0.031781,-0.012075,-0.127066,0.136535,0.027871,-0.166997,0.144494,0.462950,0.069620,-0.016680,0.505121,0.290434,0.015309,0.113068,0.705721,0.193514,0.279332,0.071576,0.051301,-0.084367,0.279384,0.190850,-0.641650,-0.330425,0.372152,-0.138533,0.478663,0.645227,0.148295,-0.256378,-0.121228,0.494690,-0.419757,-0.002091,0.250794,0.262966,0.067965,0.065417,0.149851,-0.180964,-0.200813,0.134179,0.079113,-0.575052,0.187516,-0.143194,-0.125983,-0.628889,0.384616,-0.381243,0.003630,-0.133191,-0.263869,0.300336,0.389552,0.213817,0.044162,-0.098353,-0.156883,-0.703909,0.328754,0.937735,-0.074920,0.216021,0.327986,0.057961,-0.307080,0.006591,-0.305421,-0.477620,0.138147,0.596992,0.099948,-0.260101,-0.050496,-0.235192,-0.101130,-0.459957,0.068977,-0.327489,-0.419395,-0.150795,-0.177408,-0.072132,-0.091268,-0.314909,0.216609,-0.061407,-0.305026,0.291895,-0.764915,0.264485,0.733802,0.475599,-0.434108,0.588054,0.431915,-0.133947,0.085390,0.074578,0.163814,0.275708,0.161503,0.195368,0.093576,0.330538,-0.195336,-0.307706,0.322622', '1309116', '1293142', '1308755', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305388', '世界奇妙物语 电影特别篇', '喜剧', '1.雪山凶灵飞机在雪山上失事，6个幸存者不顾伤势，向前方寻找栖身地，其中有一女子伤势特别严重，大家决定把她抛下。漫长的跋涉后，剩下的人终于找到了一间小木屋栖息，可是死亡的脚步并未因此放缓。（矢田亚希子饰）2.手机将军江户的内藏将军（中井贵一饰）玩忽职守，天天泡在情妇（奥菜惠饰）温柔乡里，某天他捡到了一部来自未来世界的手机，手机那头“预测”要发生的事在将军身上一一应验，将军还被告知自己的名字已载入300年后的史册中。3.棋幻人生世界象棋冠军（武田真治饰）战无不胜，却在一场和机器人的比赛中失手，从此一蹶不振。有一天，他被一位神秘的人邀请下棋，令人惊恐的是，棋盘上的棋子们都变成现实中活生生的人，一步棋即定一人生死。4.模拟结婚一对甜蜜的情侣打算注册结婚，发达的科学已经可以仅凭2人的DNA测出今后的相契程度，情侣们兴致勃勃地接受了这场测试。测试完后，他们却发现原本以为的固若金汤的感情受到了最严酷的考验。(柏原崇、稲森いずみ饰)', '中井贵一', '小椋久雄', 8.3, 8175, 'tt0293984', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p912715405.jpg', 0.2, 1.1, 15, 50.3, 33.3, '0.221996,0.165425,-0.666405,0.502941,-0.043376,-0.076128,0.647315,-0.101037,-0.368003,-0.085474,0.407091,0.691215,-0.320604,0.151258,0.386787,0.034701,-0.360189,-0.803852,-0.125293,-0.205987,-0.571024,-0.364351,-0.244463,-0.101055,0.008041,-0.212144,0.693325,0.322754,-0.125966,0.414972,-0.032729,-0.014572,-0.090953,0.454828,-0.218141,0.057122,-0.067085,0.072233,-0.145451,0.201503,-0.076400,-0.246698,-0.188406,0.202679,-0.041175,0.243642,0.676733,-0.388020,-0.115004,-0.101401,0.284463,-0.118617,-0.152171,0.085247,0.437762,0.071308,0.043546,0.241465,-0.272107,0.019252,0.128134,-0.006443,-0.654168,-0.192043,-0.109577,0.238774,-0.331467,0.569396,-0.059246,0.026199,0.017695,-0.298688,0.267454,0.178949,0.327305,0.390092,-0.147107,-0.118144,-0.455180,0.129050,0.576394,-0.041261,-0.183238,0.279734,0.036567,-0.562282,-0.064320,-0.277340,-0.565555,0.020030,0.343504,0.194255,-0.264736,0.179877,-0.407865,0.277523,-0.180694,-0.266957,-0.102783,-0.428663,-0.261457,-0.445431,-0.107856,-0.180445,-0.337057,0.182756,0.091338,-0.289839,0.695011,-0.540763,0.113711,0.441064,0.085242,-0.134172,0.622260,0.046367,0.139471,-0.139552,0.014389,0.040037,0.014329,0.469932,0.212272,0.268410,-0.156770,0.068159,-