INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305394', '亚特兰蒂斯：失落的帝国', '科幻', '希腊哲学家柏拉图曾经在公元前360年两度在他的著作【对话录】提及亚特兰提斯这个文明——“在一个分不清楚昼夜的晚上，亚特兰提斯沉入了深海。”1914年华盛顿的市立博物馆里，年轻的男主角迈罗是一位语言学家，对于亚特兰提斯的传说深信不已。迈罗希望自己能像祖父一样成为一位伟大的探险家。在得不到博物馆的资金赞助下，突然出现一位祖父生前怪怪的好友愿意提供迈罗资金，让他去探索亚特兰提斯存在的真假。迈罗领着专家组成最顶尖的探险队，出发前往深海寻找亚特兰提斯城。万万没想到，亚特兰提斯人居然仍然生活在地底的世界里。在亚特兰提斯的国度里，迈罗与探险队见到了亚特兰提斯二万岁高龄的国王以及八千五百岁的姬妲公主，他们对亚特兰提斯文明的未来感到忧虑，公主希望探险队可以帮助她的王国重新找回动力。不料整支探险队伍除了迈罗之外全都心怀不轨，他们全是为了金钱财富而来。探险队准备将公主绑架走，而姬妲公主是亚特兰提斯城生命的源头。此时迈罗必须依靠一己之力在亚特兰提斯人民的帮助下将公主救回。', '迈克尔·J·福克斯', '加里·特洛斯达勒', 7.6, 12409, 'tt0230011', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p452579358.jpg', 0.3, 3.1, 31.9, 44.6, 20, '0.100516,0.264232,-0.682201,0.747541,0.071929,-0.255769,0.720140,-0.079002,-0.511262,-0.265955,0.181267,0.729282,0.147514,0.140150,0.767535,0.053737,-0.522789,-0.231209,0.068112,-0.248006,-0.235940,-0.547330,-0.530257,-0.203973,-0.186559,-0.748747,0.582187,0.136425,-0.027224,0.248055,0.157603,0.544767,-0.298127,0.192552,-0.364650,-0.087641,0.198838,0.000257,-0.447280,0.523849,-0.152629,0.332764,-0.082631,0.314052,-0.058189,0.182756,0.243397,-0.692786,0.365596,0.012541,0.438518,-0.047809,0.173518,0.008109,0.371589,-0.072377,-0.130542,0.168673,-0.028219,-0.156932,0.139034,-0.228254,-0.808575,-0.145263,0.180667,0.311358,-0.862533,0.168321,-0.197998,0.003859,0.133804,-0.265689,0.064995,0.568556,0.300054,0.586161,-0.097515,0.031020,-0.626686,0.080110,0.544842,-0.296336,-0.363598,0.031867,-0.188936,-0.461314,-0.035771,-0.235686,-0.478190,-0.059778,0.177855,-0.136663,0.250754,0.565010,-0.676321,-0.075094,-0.394981,-0.576050,0.411161,-0.315713,-0.027772,-0.242370,0.059398,-0.040452,-0.115265,0.151343,0.333806,-0.307037,0.669775,-0.642121,0.460316,0.673457,0.496832,-0.604831,0.908185,-0.042215,0.137908,-0.081509,-0.039189,0.488682,0.346548,0.256451,-0.185915,0.339568,0.046332,-0.339506,-0.291559,0.416356', '6030611', '1793491', '3769423', '27000981');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305419', '午夜凶铃(美版)', '悬疑', '坊间流传着一个恐怖的传说，它和一盒神秘的录像带有关，传说中，凡是看过这盘录像带的人，会在七天之后死亡。理性至上的女记者凯勒（娜奥米·沃茨 Naomi Watts 饰）只将此当成是一个玩笑，可侄女凯蒂（爱波·塔布琳 Amber Tamblyn 饰）的死却让她的信仰产生了动摇。凯勒的姐姐告诉凯勒，凯蒂曾和三个同学一起看过一盘诡异的录像带，而这三位同学无一例外都死于了非命。凯勒决定着手调查此事，她找到了凯蒂曾经看过的录像带并看了录像带中的内容，之后，一个神秘的电话预示了凯勒死期已近。想要活命，凯勒就必须在七天之内找到录像带诅咒的真相，时间紧迫，凯勒最终能够成功脱险吗？©豆瓣', '娜奥米·沃茨', '戈尔·维宾斯基', 6.5, 16601, 'tt0298130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2565068431.jpg', 2.1, 11.2, 55.5, 24.3, 6.9, '0.218859,0.102726,-0.477681,0.614783,-0.084841,-0.145448,0.753202,-0.149721,-0.464860,-0.350989,-0.116918,0.736269,-0.237920,0.287121,0.165439,0.230019,-0.462879,-0.615757,-0.066140,-0.239253,-0.454557,-0.652371,-0.200361,-0.234239,0.125876,-0.273967,0.217290,0.051514,0.000901,0.396589,0.210091,-0.093046,-0.205301,0.331101,-0.201561,0.158168,0.154902,-0.065735,-0.189381,0.321465,0.239852,-0.162974,-0.078899,0.492352,0.084094,0.292015,0.374783,-0.322041,-0.140751,0.068641,0.400016,-0.161829,-0.095687,0.115821,0.249768,-0.047628,0.355474,0.286584,-0.390117,-0.091742,0.200013,0.066635,-0.994535,-0.079715,-0.133361,0.238403,-0.421026,0.324734,-0.154405,0.157669,0.034088,-0.193214,0.398160,0.182212,0.179370,0.130642,-0.153882,-0.386486,-0.504174,0.185183,0.393702,-0.158910,-0.178945,0.134066,0.193901,-0.538550,-0.085639,0.134222,-0.469242,0.376611,0.568618,0.295654,-0.235328,0.210550,-0.576199,-0.254963,-0.366085,-0.217842,-0.017013,-0.456871,-0.192732,-0.334385,-0.332433,-0.134822,-0.396955,-0.057944,0.086595,-0.358846,0.739206,-0.594047,0.495471,0.546555,0.026308,-0.360565,0.616846,0.256770,0.083779,-0.130609,0.045062,0.243491,0.233051,0.244629,0.233180,0.503616,0.320053,-0.381890,-0.620146,0.599892', '3785918', '1793491', '1308585', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305430', '愤怒管理', '喜剧', '戴夫（亚当·桑德勒 Adam Sandler 饰）有着温文尔雅的外表，和漂亮的女朋友琳达（玛丽莎·托梅 Marisa Tomei 饰）。但在一次飞行旅行中情绪失控，，被遣送去进行“情绪管理”训练。课程的负责人精神病医生巴迪（杰克·尼科尔森 Jack Nicholson 饰）本身就有点疯癫。一手创建了“情绪管理”理论和治疗中心，相关书畅销不衰。中心的病人个个脾气古怪，巴迪不断的逼迫戴夫去做一些近乎发疯的事情，让戴夫感到即使不疯也要快要被逼疯了。而法庭认为戴夫的进展过于缓慢要送他去监狱。被逼入绝境的戴夫，只好忍受巴迪的刺激疗法，戴夫感到自己的极限就要到来，他在退缩封闭自己的内心，还是勇敢面对完整的自己两个选择中，犹豫了……到底巴迪医生与病人戴夫的磨合调整，会是柳暗花明，还是陷入无尽的内心黑洞当中呢？©豆瓣', '亚当·桑德勒', '彼得·西格尔', 6.7, 7999, 'tt0305224', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568674602.jpg', 1.5, 10, 50.9, 29.3, 8.3, '-0.052363,-0.184130,-0.493013,0.384328,-0.275021,-0.042979,0.790501,0.062839,-0.421472,-0.384305,0.079956,0.552947,-0.179839,0.251695,0.280409,0.132514,-0.352097,-0.626263,-0.044797,0.202640,-0.230285,-0.475322,-0.116506,-0.279368,0.049848,-0.332349,0.549632,-0.062014,-0.408621,0.308283,0.126707,0.408844,0.176140,0.460278,0.142989,-0.086343,0.074354,-0.420730,0.042519,0.135392,0.569073,-0.139921,-0.069215,0.519582,0.257003,0.367630,0.543324,-0.030343,-0.128101,0.157355,0.257000,-0.286671,-0.122417,0.346046,0.007758,-0.030281,0.009011,0.060521,-0.339879,0.237822,0.079714,-0.029062,-0.912505,0.077144,0.150976,0.197245,-0.700174,0.181088,-0.188957,-0.056089,-0.014624,-0.364922,-0.036109,0.060318,0.237283,0.696829,-0.150158,-0.290397,-0.377413,-0.204667,0.514026,-0.114143,-0.403431,0.215535,-0.444163,-0.208807,-0.022666,-0.315561,-0.476211,-0.228517,0.178974,0.159177,-0.342140,0.380021,-0.445664,-0.029879,-0.410474,-0.263517,-0.484055,-0.380972,-0.016233,-0.422847,-0.086829,-0.343307,-0.171037,-0.198705,-0.153902,-0.165435,0.471825,-0.643251,0.210835,0.537466,0.200333,-0.522522,0.278223,0.284632,-0.028473,-0.157726,0.053235,0.287909,-0.049860,0.352983,0.071954,0.380147,0.209670,-0.138788,-0.440377,0.538977', '1793491', '25828589', '26857170', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305440', '亚飞与亚基', '喜剧', '成长在黑社会街区的亚飞（梁朝伟 饰）与阿基（张学友 饰）有着超过二十年的友情，胸怀黑社会之梦的二人平日却只是混事度日：砍人时临阵脱逃、从老大尸体上偷金表这些事他们做来毫不脸红，亚飞与阿基二人有着克死老大的神奇特质，他们的每一任老大下场都极其凄惨，尽数死于江湖大佬关公（汤镇业 饰）之手，一时间，二人“老大克星”的名头响彻江湖，连好友波哥（曾志伟 饰）也不敢收留。二人只好退出黑社会，借钱办起了贸易公司，但第一单生意居然是诓骗新加坡女子阿真（袁咏仪 饰）卖身，不忍逼良为娼的二人大闹黑社会，生死关头被关公手下带走，原来笃信命理的关公要借助二人的硬命渡过劫数，于是，在黑社会摸爬多年的二人终于迎来了翻身之日……©豆瓣', '梁朝伟', '柯受良', 7.7, 18828, 'tt0105864', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2327421659.jpg', 0.4, 2.7, 29.1, 46.7, 21.1, '0.047825,-0.304922,-0.512286,0.289156,-0.103270,-0.203279,0.211412,0.217919,-0.571573,-0.140598,0.314509,0.726564,-0.222076,0.063966,0.136439,-0.105997,0.150501,-0.735314,-0.113246,-0.079001,0.028143,-0.075430,-0.091281,-0.238102,-0.320980,-0.012923,0.346603,-0.099523,-0.181854,0.431661,0.534023,0.235939,-0.399516,0.083030,-0.309181,-0.051110,-0.077177,0.224551,-0.425096,-0.087123,-0.213100,-0.228515,0.028481,-0.156321,0.008114,0.162444,0.350579,-0.212563,-0.055626,-0.056563,0.227321,-0.264630,-0.276804,0.001353,0.249746,-0.352451,0.204760,0.363721,0.086054,-0.108966,0.333063,0.067261,-0.572644,0.002815,0.158888,-0.090304,-0.684176,0.347812,-0.059045,-0.031619,-0.279680,-0.205565,0.173158,0.196654,0.163296,0.279664,0.067329,-0.143230,-0.608544,0.242193,0.435306,0.146442,-0.028544,0.220117,0.113290,-0.277593,-0.049233,-0.470892,-0.247208,0.019477,0.406208,-0.250542,-0.053563,0.319395,-0.482657,-0.138442,-0.028818,0.139951,0.102962,-0.183540,-0.151756,-0.398316,-0.197530,-0.396242,-0.219835,0.284577,0.324290,0.032697,0.386199,-0.526761,0.006070,0.100931,-0.094542,-0.362672,0.599870,0.124464,-0.010036,-0.209274,-0.144028,-0.056353,0.396094,0.288660,0.334299,-0.068161,-0.255688,-0.100213,-0.068669,-0.002067', '4301278', '1299799', '1783461', '24307637');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305441', '人在纽约', '剧情', '来自两岸三地的三位中国女人，大陆女子赵虹（斯琴高娃 饰）、台湾女子黄雄屏（张艾嘉 饰）以及香港女人李凤娇（张曼玉 饰）因缘际会在他乡异地美国纽约相遇相知，很快成为了朋友。然而不同的出身背景以及思想观念让三人矛盾尽现。与美籍华人刚刚结婚的赵虹，对移民生活抱着无限憧憬与向往；在美国生活了十多年的黄雄屏，早已深受美式思想影响，醉心于舞台艺术，一心想跻身美国舞台，被美国人接受；而个性独立的香港移民李凤娇，则相信在任何地方都能生存下去，更要找到自己在美国的位置与价值。她们在异乡交流自己的感情与看法，却又不得不面对各自的问题。由关锦鹏执导，张艾嘉、张曼玉、斯琴高娃三大影后联袂主演的影片《人在纽约》，荣获第26届台湾金马奖最佳剧情片、最佳女主角、最佳摄影、最佳原著剧本在内的八项大奖。©豆瓣', '张艾嘉', '关锦鹏', 7.5, 6746, 'tt0098187', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2270159186.jpg', 0.3, 2.4, 33.8, 50.3, 13.2, '-0.150153,-0.011044,-0.848568,0.686420,0.139651,0.015218,0.426916,0.205702,-0.584102,-0.049641,0.128844,1.128767,-0.151793,0.112765,0.380683,-0.265400,-0.358416,-0.756294,-0.119246,-0.259435,-0.093593,-0.401962,-0.283917,-0.066247,-0.369308,-0.363436,0.951860,-0.004396,-0.359285,0.458359,0.491666,0.212630,-0.413405,0.309303,-0.241634,-0.181794,0.213030,0.224565,-0.902745,0.346272,-0.126895,-0.243383,-0.170008,0.063112,-0.077763,0.094246,0.705279,-0.034824,-0.023673,0.038951,0.279035,-0.120574,-0.210313,-0.138061,0.338137,-0.283071,0.477727,0.431978,0.041193,0.174422,0.064633,-0.180183,-0.626772,0.083766,0.389324,0.246362,-0.624236,0.474274,-0.014898,-0.195321,-0.129477,-0.029672,0.184081,0.301673,0.389732,0.311006,-0.170377,0.107193,-0.242591,0.634722,0.564493,0.116826,-0.314873,0.375620,-0.193985,-0.636256,-0.261683,-0.282355,-0.492379,-0.022258,0.113933,0.140873,-0.150577,0.158769,-0.521266,0.157426,0.235537,-0.154215,0.167840,-0.539931,0.266222,-0.848316,-0.183936,-0.438009,-0.089773,-0.102420,0.341037,-0.179096,1.009632,-0.734386,0.136702,0.303655,0.414179,-0.750051,0.882871,0.248539,0.126507,-0.635841,-0.248149,0.533953,-0.199799,-0.081781,-0.269651,0.193799,-0.295312,-0.096380,-0.308699,0.425798', '1780122', '4301278', '1870681', '2338019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305456', '不忠', '剧情', '爱德华（理查•吉尔 饰）与妻子康妮（黛安•莱恩 饰）是令人艳羡的一对，他们有一个8岁的儿子。他们结婚已有11年，日子过得平平淡淡却十分美满幸福。可是生活的一成不变是康妮开始有些厌倦了。正在此时，她邂逅了神秘男子（奥利佛•马提纳兹 饰），更一发不可收拾的爱上了这名陌生人。面对丈夫，康妮不得不一而再再而三的向丈夫撒谎，不知不觉间，她已陷身于危险之中。爱德华还是发现了妻子的异样，当他知道了妻子果真有越轨行为的时候，他疯狂得要知道妻子对他不忠的所以细节。无奈知道得越多越痛苦，接着他偷偷约见了妻子的情人……©豆瓣', '戴安·琳恩', '阿德里安·莱恩', 7.6, 58257, 'tt0250797', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1685566750.jpg', 0.4, 2.3, 31.8, 48.3, 17.3, '0.169719,-0.130951,-0.610818,0.396875,-0.105809,-0.294792,0.989619,-0.106041,-0.774790,-0.170933,0.161070,0.718862,-0.278966,0.440809,0.273338,0.196327,-0.145463,-0.740172,0.006667,-0.351908,-0.117614,-0.298939,-0.299495,-0.289933,-0.275981,-0.260696,0.306492,0.071358,0.165840,0.346200,0.446989,0.383246,0.271401,0.638413,-0.251232,0.147166,-0.054090,0.084314,-0.328530,-0.072525,0.334080,-0.253960,-0.325628,0.264876,-0.289392,0.457022,0.493021,-0.101388,-0.362463,-0.143640,0.481710,-0.072169,-0.075616,0.376696,0.147308,-0.087652,-0.068640,-0.027827,-0.192421,-0.270439,0.160641,0.058715,-0.486096,0.261809,-0.118156,0.229173,-0.483424,0.212871,-0.289794,-0.051255,0.266713,-0.501336,0.064124,0.220680,0.196015,0.427887,-0.330141,-0.067049,-0.418080,0.219663,0.765592,0.440224,-0.033235,0.589671,-0.387468,-0.468907,0.064036,-0.322503,-0.781120,0.032993,0.314652,0.183306,-0.265664,0.502645,-0.250659,-0.064166,-0.042077,-0.073412,-0.126493,-0.594303,-0.095981,-0.015940,-0.242716,-0.827578,-0.494299,0.208605,-0.225093,-0.331285,0.562856,-0.968806,0.383955,0.568926,0.410039,-0.512134,0.693678,0.342189,0.035848,-0.227102,-0.002625,0.380255,-0.166224,-0.041070,0.267296,0.393242,0.098916,-0.072238,-0.264738,0.550206', '4275444', '1296370', '1308755', '1389971');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305466', '开往春天的地铁', '剧情', '建斌（耿乐 饰）和小慧（徐静蕾 饰）来北京闯荡事业，二人一起生活了7年，虽没有了当初激情却还相濡以沫。不料建斌失业了，而且3个月来都未找到新工作，房租都快交不起了。建斌心情非常复杂，对小慧隐瞒了这个消息,自己每天到地铁来度过上班时间。在地铁里，他见到不少城市里的脸谱。女孩丽川（王宁 饰），则走进了他的生活。丽川在一次地铁事件中伤了眼睛失了视力，建斌冒充她的对象，天天去医院照顾丽川。而另一方面，小慧也面临着另一个人的追求，然而在她心中，还是对建斌有着不舍不弃的感情。但是当她得知建斌的秘密，这段感情是不是难免寿终正寝……©豆瓣', '耿乐', '张一白', 7, 40962, 'tt0365402', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1361521268.jpg', 1, 6, 45.8, 36.5, 10.7, '0.072883,-0.131625,-0.895367,0.438809,-0.187046,-0.497146,0.635469,0.191753,-0.518852,-0.243385,0.138347,0.374235,-0.097219,0.403321,0.092258,0.041045,-0.404050,-0.521755,0.280774,-0.458959,-0.371434,-0.248378,-0.173241,-0.059179,-0.094949,-0.048320,0.337070,0.045871,0.068609,0.591648,0.080699,0.005627,0.018844,0.683313,-0.185654,0.169070,0.040923,0.206637,-0.127507,0.023338,0.137689,-0.389667,-0.352731,0.289517,0.233345,0.358570,0.731432,0.117063,-0.275145,0.270287,0.266204,-0.279124,-0.138542,-0.076138,0.318114,0.054630,0.306214,0.338447,-0.402419,0.073443,0.007575,-0.189035,-0.523679,0.163979,-0.085551,0.122735,-0.694622,0.639110,-0.110723,-0.146817,-0.077381,-0.544396,0.219960,0.368696,0.091075,0.618821,-0.416674,0.038851,-0.609291,0.291810,0.700081,0.023091,0.061121,0.473950,-0.179988,-0.268061,-0.051879,-0.070403,-0.485265,-0.001458,0.013329,-0.128431,-0.633255,0.158530,-0.367847,0.315292,-0.124277,-0.021598,-0.028021,-0.387058,-0.097022,-0.592498,-0.231931,-0.591949,-0.381828,0.135873,0.091379,-0.189637,0.696438,-0.761409,0.071398,0.561689,0.344580,-0.803362,0.823626,0.279758,0.096120,-0.013364,0.030596,0.115256,-0.291627,0.443932,0.210512,0.212771,0.027451,-0.035817,-0.379487,0.442342', '2990737', '1308206', '10355329', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305487', '猫鼠游戏', '剧情', '弗兰克（莱昂纳多·迪卡普里奥 Leonardo DiCaprio饰）是FBI有史以来年龄最小的通缉犯。他的犯罪手段神通广大，伪装身份的能力超乎常人，全美各地几乎都留下他的犯罪足迹。乔装医生、律师、飞行员，统统都是他曾经的身份。当然，弗兰克凭着这个“本领”，骗取了高达几百万的金额。活得逍遥快乐的弗兰克这次又成功伪造了一份学历证明，去医院做起了大夫。弗兰克不但在这里认识了护士布雷达（艾米·亚当斯 Amy Adams饰），二人擦出爱火花，还通过布雷达的父亲得到了一份检察官助理的优差。然而，这只是暴风雨前夕——一双眼睛已经盯住了弗兰克，誓要把他绳之于法不可。这就是FBI探员卡尔（汤姆·汉克斯 Tom Hanks饰）。在研究追捕弗兰克的过程中，卡尔领教到这个犯罪天才的过人智商。他屡次被弗兰克这个黄毛小子捉弄，心里又恨又不得不佩服。每当弗兰克有惊无险地从他的精心布局中逃脱时，这个猫鼠游戏显得有趣起来……', '莱昂纳多·迪卡普里奥', '史蒂文·斯皮尔伯格', 9.1, 925051, 'tt0264464', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453924541.jpg', 0, 0.2, 5.1, 34.1, 60.5, '0.209126,0.088384,-0.544037,0.658796,-0.437517,-0.442547,0.472188,-0.046395,-0.582896,-0.113981,0.193978,0.665630,-0.187579,0.073034,0.256463,0.168473,-0.451040,-0.662870,-0.058033,-0.261258,-0.064249,-0.517018,-0.493762,-0.236170,0.054824,-0.231828,0.252492,0.048210,-0.103266,0.351648,0.224964,0.129559,0.326550,0.287014,-0.280673,0.026708,0.269013,-0.203865,-0.061665,0.128549,0.267987,-0.284727,-0.088963,0.423761,-0.113408,0.385241,0.441164,-0.090198,-0.115546,0.061188,0.372650,-0.369269,0.063966,0.141165,0.302639,-0.032198,0.120925,0.072858,-0.013396,0.010730,0.035068,0.081816,-1.026211,-0.028219,0.088002,0.043277,-0.425035,0.184718,-0.458818,0.170780,-0.101953,-0.242896,0.017042,0.010615,0.138300,0.337672,-0.184432,-0.088649,-0.504811,0.193548,0.451073,-0.142428,-0.113997,0.247177,-0.306999,-0.674377,-0.035203,-0.289057,-0.355668,0.039820,0.356916,-0.172698,-0.144918,0.250615,-0.548840,0.016543,-0.479983,-0.004693,-0.294104,-0.216131,0.001477,-0.356262,-0.323283,-0.463475,-0.384078,-0.029722,0.088056,-0.298817,0.503694,-0.490628,-0.083929,0.688625,0.029968,-0.121307,0.550203,0.068311,0.001264,-0.097082,-0.272169,-0.031174,0.187701,0.419469,0.149768,0.483652,0.391763,-0.340929,-0.209232,0.424980', '1793491', '3785918', '25932086', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305509', '好莱坞式结局', '喜剧', '这时瓦克斯曼（伍迪•艾伦 饰）的事业并不如意，生活有点潦倒。他常常想起当年自己的风采，那段峥嵘岁月里他曾得过两届的奥斯卡奖。他拼命在无奈的生活中挣扎，幸好有前妻艾丽为他推荐，有机会执导一部新电影。出资拍片的人正是艾丽的男友，但瓦克斯曼对这位大老板的身份感到十分不满。但为了能重新振作，再次冲击电影界，瓦克斯曼还是作好出击的准备。可是当一切都准备妥当的时候，他无端失明了，他又如何能导演好一部电影呢，疾病却不能阻止瓦克斯曼前进的步伐，他要隐瞒病情，把电影拍完。到头来，老板兼情敌又会否知道他的秘密呢？©豆瓣', '蒂娅·里欧妮', '伍迪·艾伦', 7.5, 11021, 'tt0278823', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190963166.jpg', 0.4, 2.7, 32.3, 49, 15.6, '-0.171283,0.090450,-0.640812,0.518546,0.070004,-0.444070,0.497659,0.125507,-0.403574,-0.442024,-0.009684,0.768421,-0.250738,0.317941,-0.033357,0.082470,-0.364780,-0.699889,0.258607,-0.081177,0.038910,-0.164737,-0.521863,-0.190626,-0.074242,-0.223402,0.397336,-0.027546,-0.324126,0.070805,0.263583,0.125792,0.387578,0.661982,-0.191415,0.212944,-0.087787,-0.042222,-0.415731,0.013288,0.595360,-0.429234,-0.364275,0.436575,0.305928,0.524427,0.448718,-0.105140,-0.277625,0.126301,0.410576,-0.054317,0.077525,0.030938,0.022839,0.117639,0.149796,0.140353,-0.135074,0.003668,-0.034555,-0.201761,-0.863935,0.030452,0.007030,0.187443,-0.664785,0.206873,-0.256840,0.322964,0.026244,-0.407846,0.016447,0.326132,0.419413,0.364235,-0.167368,0.017454,-0.426153,0.352415,0.820485,0.157484,-0.011737,0.693665,-0.333957,-0.286372,0.010277,-0.250737,-0.773221,0.108775,0.280785,0.012407,-0.166829,0.166505,-0.075110,-0.136034,-0.357126,-0.105178,-0.326102,-0.392089,0.114208,-0.280330,0.020822,-0.260058,-0.160018,-0.068211,-0.038511,-0.421602,0.466565,-0.678267,0.107649,0.551121,0.311969,-0.564160,0.490545,0.330062,-0.049930,-0.031013,-0.223096,0.130240,-0.302364,0.112501,0.263095,0.148121,0.127123,-0.562717,-0.326107,0.434211', '1304977', '1306916', '34890458', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305524', '深入敌后', '动作', '圣诞节前夕，波斯尼亚战争终于达成停火协议，亚得里亚海上的美军官兵们即将返回家乡。海军领航员伯纳中尉（Owen Wilson 饰）早已厌倦这场无意义的战争，长官莱斯利（Gene Hackman 饰）出面劝解却无济于事。圣诞当天，伯纳与搭档驾驶大黄蜂战机执行航拍任务，无意中瞥见非安全区中有武装人员行动，两人决定介入，却被对方的萨姆导弹击落，搭档被对方处死，伯纳侥幸脱险，但对方搜寻人员沿路追踪不舍。与此同时，接到伯纳求救信息的莱斯利苦于北约将军节制，在所谓顾全大局的考虑下无法介入非安全区搭救伯纳，莱斯利只好借助媒体力量甚至不惜盗用盟友设备，展开了一场对落入敌后下属的拯救行动。©豆瓣', '欧文·威尔逊', '约翰·摩尔', 7.4, 14422, 'tt0159273', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1578468324.jpg', 0.9, 3.8, 35.9, 44.7, 14.7, '0.238702,0.130492,-0.579466,0.482766,0.219085,-0.059592,0.237413,-0.217355,-0.261765,-0.158535,0.381392,0.398031,0.022889,-0.419126,0.265764,-0.258711,-0.755016,-0.628532,0.129235,0.110323,-0.134140,-0.629635,-0.385340,-0.281244,-0.073195,-0.225597,0.949074,0.326139,-0.380292,0.403121,0.102352,0.336185,-0.278330,0.680939,0.252146,-0.328062,0.268506,-0.311959,-0.574192,0.222056,-0.191316,-0.119230,-0.118677,0.179459,0.089927,0.680539,0.434622,-0.327413,0.178855,-0.259261,-0.074884,-0.512416,0.419861,0.191976,0.441821,0.186274,-0.241476,0.162539,0.016868,0.107657,-0.140571,0.124966,-0.426740,-0.069722,-0.049494,0.093876,-0.066058,0.245577,-0.493085,0.394935,-0.132425,-0.150058,0.126093,0.545773,0.290491,-0.244754,-0.178283,0.117755,-0.425330,0.000556,0.703828,-0.188037,-0.094295,-0.137840,0.001760,-0.373217,0.188656,-0.288611,-0.235238,-0.115295,0.326504,0.302525,0.071214,0.310871,-0.473334,-0.192435,-0.701076,-0.347487,-0.214280,-0.476577,0.104458,-1.006610,0.175182,0.163348,-0.280973,0.488435,0.221625,-0.003649,0.388203,-0.671407,-0.002083,0.526627,0.432443,-0.285747,0.278580,0.249569,0.278835,-0.381694,0.119954,0.303865,0.186950,0.300787,0.064274,-0.206336,-0.008695,-0.178116,-0.103437,0.023892', '2369613', '20274039', '2973528', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305529', '留级之王', '喜剧', '范•维尔德（瑞恩•雷诺兹 Ryan Reynolds 饰）迎来了他在库立吉学院的第七个新学年，这位留级之王是学院内的活跃人物，不定期拥有社团会长、校园运动发起者以及篮球社中场精神教父等多重身份。来自印度的交换生泰吉（卡尔•潘 Kal Penn 饰）羡慕美国学生的生活，于是投奔维尔德做了他的助理。维尔德的父亲不堪忍受儿子的不长进，毅然中断了对他的资助，原本风光的维尔德此时不得不为了两万美元分期交付的学费发愁。校刊记者葛文（塔拉•雷德 Tara Reid 饰）对维尔德大有兴趣，贴身采访撰写关于他的报道，困窘中的维尔德偶然接到有偿帮助组织舞会的要求，自此开始从事舞会经纪人以补贴学费，葛文的报道令维尔德声名鹊起，而两人的关系也越发密切，这激起了葛文男友的愤怒，他计划向维尔德发起报复……©豆瓣', '瑞安·雷诺兹', '沃尔特·拜克', 6.8, 9992, 'tt0283111', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1621723880.jpg', 1.6, 8.2, 49.9, 29.8, 10.5, '0.317258,-0.145966,-0.429215,0.555447,0.040051,-0.313285,0.267930,0.218787,-0.451404,-0.306194,0.124874,0.564028,-0.176167,0.307918,0.595958,-0.217190,-0.190558,-0.569635,-0.115301,-0.094152,-0.009732,-0.525888,-0.064566,-0.434823,-0.139835,-0.458208,0.523725,0.033348,-0.147306,0.492458,0.566630,0.566171,0.132370,0.211992,0.199137,-0.166999,0.352300,0.226784,-0.210269,0.278704,0.074676,-0.017334,-0.130031,0.187193,0.377698,0.439980,0.361531,0.152324,-0.001456,-0.336819,0.399329,-0.127524,0.161685,0.271821,0.428478,0.262767,0.176064,0.348628,-0.237593,-0.125114,-0.042641,-0.196704,-0.609576,-0.137354,0.143186,0.074794,-0.578203,0.428343,-0.403078,-0.123423,-0.010994,-0.205473,-0.086371,0.556412,0.148889,0.321185,0.111009,0.148672,-0.146985,0.328199,0.430322,-0.148502,-0.401029,0.051115,-0.159677,-0.262319,0.195378,-0.181106,-0.493252,-0.123466,0.244951,-0.043914,0.329995,0.295435,-0.371140,-0.061721,-0.133882,-0.418364,0.097129,-0.370156,-0.051031,-0.852846,-0.198458,-0.115331,-0.076271,-0.097810,0.160642,-0.101842,0.713777,-0.826850,0.093591,0.505051,0.385982,-0.576665,0.390245,0.146344,0.192467,-0.309629,-0.286614,0.143895,0.092176,0.266772,-0.001144,0.167887,0.204292,-0.506037,0.046966,0.489410', '2369613', '1316589', '25922902', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305530', '收件人不详', '剧情', '韩战初结束时期，某个美军驻韩基地附近的村镇里，多数居民的生活被战后的虚无、迷茫和绝望笼罩，出路难寻。皮肤黝黑的尚武（杨东根）因是母亲（方银珍）在战争期间与美国黑人士兵所生，自小受尽歧视，养成暴戾的性格，无处发泄时就会对母亲拳打脚踢；其母亲不甘接受命运的摆布，屡屡写信去美国，期望她的黑人丈夫能把她们母子接到美国，但每每只收回“收件人不详”的退信；而他靠画画谋生的好友恩吴（金英民），因体质纤弱，经常被混混欺负，心爱的女孩被人凌辱、委身美国大兵时，他也只能眼睁睁看着暗自抓狂。©豆瓣', '杨东根', '金基德', 8.3, 29610, 'tt0284815', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1173347335.jpg', 0.5, 1.3, 14.5, 50.4, 33.3, '0.142685,-0.142400,-0.640246,0.545354,-0.121764,-0.264654,0.479397,0.138226,-0.700933,-0.251483,0.018658,0.718852,-0.097850,0.556251,0.036656,0.028338,-0.101567,-0.680172,-0.354248,0.022231,-0.084063,-0.168583,-0.038140,-0.437171,-0.106094,-0.311337,0.701794,0.058711,-0.203989,0.414185,0.135039,0.474642,-0.213197,0.605902,-0.213830,-0.117493,-0.205424,-0.295301,-0.109507,-0.114090,0.102809,-0.333629,0.171138,0.000066,-0.146498,0.396044,0.895593,-0.133754,-0.088921,-0.528899,0.407231,-0.249918,-0.164015,0.489661,0.198168,-0.158786,0.189334,-0.028291,-0.171187,-0.010880,0.073000,0.096954,-0.367681,-0.098422,0.073629,-0.120063,-0.617400,0.586748,0.130972,0.151936,0.033832,-0.291021,0.295640,0.134055,-0.035245,0.531067,-0.205164,-0.040712,-0.273841,0.264970,0.713093,-0.135856,-0.152500,-0.083446,-0.411257,-0.311356,0.238844,-0.417258,-0.769367,-0.021084,0.233164,0.018351,-0.441492,0.165854,-0.354815,-0.030505,-0.171017,0.017687,-0.115933,-0.501364,-0.219165,-0.286411,0.039900,-0.381035,-0.326255,0.172819,0.155087,-0.071443,0.728092,-0.589550,0.270883,0.525447,0.565713,-0.510714,0.554511,0.131489,0.146868,-0.018126,0.024040,0.609251,0.116259,0.242625,0.226429,-0.017487,-0.288413,0.195844,-0.049162,0.444007', '3445516', '35030151', '4066127', '1945253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305536', '三少爷的剑', '剧情', '神剑山庄的三少爷谢晓峰（尔冬升 饰）当年凭借出神入化的追魂剑法名震江湖，被世人誉为“剑神”。有道是树大招风，各路豪杰为了争夺第一的称号相继登门挑战。早已厌倦了无休止的争斗，三少爷假装死亡，化名阿吉跑到妓院里做着最下贱的工作，在那里他遇到了美丽的女孩小丽（余安安 饰）。无奈为了保护老苗一家，三少爷再度出手，他依然在世的消息不胫而走，由此引来了多年前一直想和他一决雌雄的天下第一剑燕十三（凌云 饰）以及曾经被其背负婚约的慕容秋荻。一入江湖，身不由己，血雨腥风在所难免……本片根据武侠小说名家古龙的经典名作改编。©豆瓣', '尔冬升', '楚原', 7.4, 6425, 'tt0076660', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2342595694.jpg', 0.8, 3.7, 36.5, 43.3, 15.7, '0.114270,0.234885,-0.693594,0.498828,0.132888,-0.113609,0.258219,-0.133518,-0.558766,-0.498332,0.453945,0.746355,-0.031004,0.204547,0.348071,-0.165623,0.382255,-0.701853,-0.252002,-0.311866,-0.008157,-0.057168,-0.363657,0.165097,-0.258564,-0.044383,0.286138,0.076524,-0.326225,0.399072,0.325048,0.359673,-0.214021,0.008073,-0.314241,-0.008818,0.043825,0.251482,-0.544084,0.168408,-0.208854,-0.452719,-0.161967,0.140615,-0.151743,0.138497,0.217729,-0.488181,0.043404,-0.260683,0.301757,0.037771,-0.192179,-0.048360,0.311300,-0.090209,0.459596,0.382621,-0.182362,-0.136701,-0.190939,-0.031232,-0.848407,-0.020872,0.353323,0.054443,-0.473934,0.348887,-0.329295,-0.184554,-0.127927,-0.309431,0.237668,0.075492,0.354408,-0.146620,-0.085118,-0.052242,-0.462208,0.376017,0.500978,0.105891,-0.003659,-0.025777,0.498658,0.056398,0.081389,-0.700862,-0.318914,0.026919,0.507427,-0.186419,0.036941,0.548336,-0.346313,-0.116992,0.059390,-0.032984,0.095617,-0.003253,-0.077939,-0.442909,-0.195371,-0.331561,-0.047251,-0.237431,0.324900,-0.247894,0.886727,-0.866923,0.280252,0.044747,-0.008346,-0.607281,0.324811,0.208060,0.069292,-0.018296,-0.412550,0.230139,0.186813,0.398727,0.172203,0.269875,-0.041727,-0.307326,-0.353682,0.355544', '27602116', '24284209', '1438924', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305541', '缘分天注定', '喜剧', '缘分真的天注定？一个普通、忙乱的圣诞夜，乔纳森（约翰•库萨克 John Cusack 饰）和萨拉（凯特•贝金赛尔 Kate Beckinsale 饰）相遇了。认识的短短几个小时，他们就不可救药地爱上了对方。虽然，他们各自都有自己的生活圈子，自己伴侣。当他们幸福地在曼哈顿的街头漫步了一整个晚上后，黎明来临，他们不得不面对现实。萨拉拒绝了乔纳森互留号码的请求，并决定一切由老天决定。几年时光转瞬即逝，他们再也没有重遇。此时，乔纳森已准备踏入婚姻殿堂，而萨拉也收到了男友的求婚戒指。只是，一本书、一张电影海报，都能让他们不由自主的想起几年前的那个圣诞夜。乔纳森在婚礼前夕开始的依靠几年前留下来的线索找寻萨拉。©豆瓣', '约翰·库萨克', '彼德·切尔瑟姆', 7.5, 63744, 'tt0240890', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p484104631.jpg', 0.8, 3.7, 32.7, 42.8, 20, '0.247974,0.096970,-0.829481,0.437581,-0.161349,-0.535308,0.677656,-0.088476,-0.490783,-0.276997,0.084107,0.912460,-0.335054,0.371154,0.425135,-0.006628,-0.631417,-0.754345,0.243170,-0.480562,-0.266983,-0.422813,-0.058382,-0.183814,-0.046407,-0.050514,0.475005,0.122657,0.452220,0.660580,0.292361,-0.198628,0.135916,0.542353,-0.150193,0.045674,0.210433,0.060352,-0.384563,0.188800,0.033761,0.044690,-0.150201,0.319318,-0.055720,0.263858,0.567843,-0.124030,-0.120613,0.030765,0.239004,-0.126190,-0.241548,0.102799,0.297030,-0.164781,0.211247,0.370012,-0.293377,-0.097709,-0.048217,0.046301,-0.483686,0.300813,-0.336592,0.004945,-0.574678,0.499322,0.064197,0.041257,0.093082,-0.517003,0.077934,0.582965,0.341266,0.196543,-0.242280,-0.209070,-0.418991,0.300792,0.689127,-0.011079,-0.271731,0.646603,-0.026259,-0.425975,-0.236746,0.285977,-0.471106,0.024965,0.427860,0.138770,-0.238350,0.146866,-0.581699,-0.048150,-0.288806,-0.407260,0.227356,-0.590445,-0.137160,-0.601241,-0.172620,-0.187901,-0.589210,0.165311,-0.077540,-0.132823,0.436233,-0.736643,0.355931,0.491313,0.115043,-0.418833,0.732436,0.369752,0.175948,-0.148372,0.270082,0.495873,-0.103301,0.492794,0.185827,0.247260,0.163799,0.207685,-0.526361,0.689247', '1303333', '1309172', '1299433', '1297239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305543', '北京，你早', '剧情', '改革开放初期，在北京一个寒冷的清晨。天还没亮，99路汽车售票员艾红（马晓晴 饰），与每天骑自行车接她一起上班的王朗（金铁峰 饰）来到车场。李队长（李连义 饰）给他们介绍新来的司机邹永强（王全安 饰）。王朗售票时积极热情，艾红却相反。她跟刚来不久的邹永强走的越来越近 。当 王朗又在老地方等艾红上班时，她没有出现。王朗到了车场发现她和邹永强有说有笑的，对他却很冷淡，王朗心里很不好受。永强的哥们是倒爷，出手大方阔绰。羡慕物质生活的艾红，她决心要辞职去挣大钱。艾红遇到了自称是新加坡留学生的陈明克（贾宏声 饰），他请她听歌，又送录音机、新衣服，还邀她去游玩，贪慕虚荣的艾红立马沦陷。不久她向永强提出了分手，永强因失恋的打击开车分神出了事故。艾红发现怀了孕，去找陈明克时却意外得知他是假留学生......©豆瓣', '马晓晴', '张暖忻', 8.1, 6403, 'tt0101425', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2868144322.jpg', 0.3, 0.8, 17.8, 56.1, 25, '0.229216,0.016300,-0.822979,0.331438,-0.258825,-0.379794,0.657729,0.238285,-0.275239,-0.333157,0.123975,0.536232,-0.199742,0.261035,0.316267,0.055774,-0.316942,-0.307874,0.233779,-0.001558,-0.418411,-0.092572,0.097695,-0.058815,-0.137094,-0.012847,0.009304,0.051491,-0.216104,0.765591,0.309985,-0.006283,-0.036932,0.867736,-0.464253,0.175669,-0.139445,0.186580,0.040805,0.155212,0.202715,-0.289104,-0.345523,0.055631,0.213567,0.537102,0.278139,0.405329,-0.160620,0.304381,0.252770,-0.287466,-0.086470,-0.009912,0.364248,-0.010944,-0.025169,-0.229481,-0.321227,0.055109,-0.077269,-0.032560,-0.190563,0.313817,-0.148274,0.130270,-0.659304,0.389120,-0.235717,-0.015265,0.118117,-0.624703,0.242637,0.208753,-0.227542,0.534261,0.076445,0.030995,-0.585714,0.329246,0.785625,0.193731,0.151125,0.328503,0.089377,-0.296167,0.350194,0.197223,-0.345962,0.077063,0.285918,-0.189258,-0.159335,-0.406777,-0.345549,-0.083213,-0.073111,-0.002423,-0.023724,-0.297243,-0.004578,-0.642832,0.143787,-0.500527,-0.280774,0.244988,-0.104966,-0.008296,0.422816,-0.731223,0.059200,0.418618,0.546711,-0.675625,0.772442,-0.053413,-0.252561,-0.294376,0.083706,-0.081855,-0.107509,0.344011,0.238625,0.440170,0.034047,-0.197779,-0.273401,0.203385', '10355329', '2990737', '1877016', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305553', '真情假爱', '喜剧', '作为南加州最好的离婚官司律师，迈尔斯•马西（乔治•克鲁尼 饰）的精明之道令客户非常满意。而玛丽莲（凯瑟琳•泽塔-琼斯 饰）这个拜金女郎想利用自己的美色嫁入豪门后以离婚的名义取得高额的财产。而玛丽莲的丈夫请来了迈尔斯，以确保自己能在离婚官司中稳操胜券。玛丽莲的美丽吸引住了迈尔斯，但他还是帮自己的客户保全了家产。深深不忿的玛丽莲想要报复迈尔斯，便想假装与他结婚。他们一边算计对方，一边被对方吸引，到底爱情的力量又能否胜出呢？©豆瓣', '乔治·克鲁尼', '乔尔·科恩', 6.4, 13570, 'tt0138524', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p475794152.jpg', 1.4, 12.1, 55.4, 25.5, 5.8, '0.144218,0.338018,-0.428305,0.708353,-0.430227,-0.504446,0.441004,0.080800,-0.165403,-0.089069,0.224148,0.870926,0.078921,0.285296,0.205528,0.388302,-0.151920,-0.668683,0.310087,-0.091405,0.026150,-0.687963,-0.288494,-0.324917,-0.129777,0.101398,0.444782,-0.033445,-0.038564,0.139016,0.467623,0.278722,0.227272,0.396028,-0.037639,0.187700,-0.085718,-0.183310,-0.560188,0.281031,0.327116,-0.192206,-0.238968,0.360750,0.087013,0.457356,0.305011,0.021079,0.241545,-0.067516,0.238726,-0.286479,-0.004059,0.385752,0.034799,-0.135037,0.212525,0.110566,-0.349910,-0.279986,0.386418,0.047227,-0.843410,-0.106124,0.083217,-0.002309,-0.463271,0.215305,-0.326307,0.033329,0.195964,-0.064996,-0.093658,0.279965,0.247905,0.180697,-0.327826,-0.043169,-0.672066,0.203445,0.378024,0.088928,0.202124,0.251812,-0.456011,-0.349167,0.069640,-0.420692,-0.503021,-0.116754,0.623912,0.104430,0.250786,0.296983,-0.381097,-0.472345,-0.316533,-0.011164,-0.112195,-0.812755,0.239671,-0.273144,-0.468706,-0.339629,-0.242897,-0.010819,0.208899,-0.409685,0.656536,-0.701813,-0.254916,0.603983,0.428852,-0.883375,0.468770,0.417680,0.350491,-0.230053,-0.452951,0.121199,0.050514,-0.047739,0.058683,0.280711,0.321063,-0.188528,-0.171442,0.519875', '1304382', '26678784', '30163500', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305564', '八星报喜', '喜剧', '方家老大方剑辉（黄百鸣 饰）是一名烹饪主持人，成熟稳重的他对两名弟弟多般照顾，因此到三十岁都没有女朋友；老二方剑郎（周润发 饰）是个娘娘腔的花花公子，纵使有空姐女友天红（郑裕玲 饰），但他仍周旋与众多女友之间，后来更认识美艳的Beautiful（钟楚红 饰）后引发了一段 感情纠纷，郎最终还是浪子回头；小弟方剑笙（张学友 饰）是个单纯害羞的漫画家，偶然遇上了活泼少女莹莹（袁洁莹 饰）后发展了一段纯洁的爱情。一次偶然的电话故障，也让方剑辉认识离婚妇人吴芬芳（冯宝宝 饰），两人发展顺利，但却因为帮忙弟弟剑郎掩盖风流债，让芬芳误以为剑辉是个勾三搭四的人，众人决定帮剑辉挽回即将失去的爱情……©豆瓣', '周润发', '杜琪峰', 7.4, 26470, 'tt0094695', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167152345.jpg', 0.5, 3.1, 35.9, 45.4, 15, '0.238923,-0.017596,-0.340916,0.467534,-0.309041,-0.242478,0.692335,0.056085,-0.365321,-0.334280,0.130035,0.438920,-0.140694,0.176179,0.001315,-0.137109,0.084704,-0.517704,0.119749,0.045441,-0.057823,-0.275244,-0.172146,0.235708,-0.340015,-0.111741,0.559833,-0.081976,-0.189114,0.593222,0.420426,-0.088360,0.039843,0.318186,-0.043166,0.131661,0.124619,0.317079,-0.067750,0.017459,0.032110,-0.224612,-0.189218,0.186974,0.053648,0.590497,0.556743,-0.000414,-0.373312,-0.041610,0.431741,0.020435,-0.011769,0.075395,0.298758,-0.032347,0.310054,0.114208,-0.315139,-0.257333,0.036653,0.120209,-0.312942,0.204812,0.310444,0.097682,-0.383052,0.322167,0.051964,-0.245863,0.088559,-0.151019,0.120875,0.200222,0.374540,0.084171,-0.007580,0.144247,-0.362126,0.494001,0.725379,0.400422,-0.228120,0.595439,-0.288833,-0.382318,-0.043174,-0.192095,-0.731893,0.301046,0.166631,-0.182267,0.040986,0.152938,-0.465063,-0.048623,-0.229675,0.487047,-0.135371,-0.414607,0.033352,-0.236584,-0.376876,-0.526387,-0.354818,0.090844,-0.016248,-0.197406,0.803468,-0.791698,-0.022653,0.334532,0.082283,-0.671227,0.650874,0.238424,-0.044696,-0.411565,0.089548,0.177148,-0.116143,-0.419308,-0.139538,0.455769,-0.102074,-0.267173,-0.082754,-0.007932', '3445516', '6963575', '25922902', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305566', '撕裂的末日', '剧情', '世界核战争后，政府给每个人注射一种麻痹情感神经的药物，使人们封闭感情，变成行尸走肉。 约翰·普雷斯顿（克里斯蒂安·贝尔 Christian Bale 饰）是政府军事部门高级官员。他摧毁一切艺术品、工艺品，并将一切抗令不抛弃自己感情的人杀死，同事艾洛·帕特杰（肖恩·宾 Sean Bean 饰）因藏有一本违禁书籍也未曾幸免。一次行动中，约翰遇到玛丽·欧布莱恩（艾米丽·沃森 Emily Watson 饰）。她使得约翰开始断绝药物，试图体会有感情的生活究竟是一种什么样的滋味。他被那些第一次出现在他生命里的奇妙动人景象所陶醉了，也深深的为每天履行的破坏艺术的行为感到愧疚和内疚。 他的反常行为，被一直窥探其位置的新同事布兰特（泰雅·迪格斯 Taye Diggs 饰）看在眼里，于是想尽办法，试探约翰的虚实。在工作与道义之间，在危险与安逸之间，在情感与沦丧之间，约翰又会做出怎样的抉择呢？', '克里斯蒂安·贝尔', '科特·维莫', 7.5, 39577, 'tt0238380', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p528908542.jpg', 0.7, 3.8, 31.8, 46, 17.8, '0.176001,-0.000065,-0.682324,0.506503,-0.086356,-0.014546,0.785672,-0.055466,-0.773273,-0.468776,0.120996,0.594205,-0.269821,0.023381,0.179992,0.077319,-0.334831,-0.933098,0.022249,-0.020237,-0.282318,-0.508019,-0.315958,-0.527319,-0.000980,-0.456791,0.575459,0.086875,-0.345459,0.095421,-0.003659,0.660868,-0.070584,0.610316,0.238019,-0.107091,0.111672,-0.204361,-0.447452,-0.347352,0.164289,-0.153506,-0.073639,0.429746,-0.151426,0.283478,0.697844,-0.436752,-0.326210,-0.057816,0.271595,-0.246949,0.054400,0.156204,0.037196,-0.040990,-0.140672,0.236959,-0.242446,0.168437,0.270565,0.137320,-0.776701,-0.342353,-0.148471,0.362041,-0.350783,0.367488,-0.075119,0.145674,-0.036082,-0.314195,0.109201,0.184957,0.531666,0.331498,-0.168800,-0.248041,-0.274882,-0.164101,0.874044,-0.059371,-0.382897,0.285701,-0.851786,-0.245331,-0.185961,-0.151199,-0.445799,-0.034235,0.116483,0.268132,-0.062381,0.559603,-0.617490,-0.231585,-0.183291,0.032775,-0.059450,-0.564906,0.072591,-0.638801,-0.238497,-0.364077,-0.448776,-0.247907,0.162767,-0.349750,0.456267,-0.684230,0.184013,0.450978,0.092039,-0.482206,0.511300,0.055135,-0.166206,-0.253040,-0.268066,0.530820,0.085296,-0.004100,0.037200,0.230964,0.202361,0.350281,-0.069127,0.474710',