INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305579', '小毕的故事', '剧情', '朱小凡见证了邻居男孩毕楚佳（伊绳祖、郑传文、钮承泽、庹宗华）的成长过程。为了让小毕更好的成长，受骗怀孕又遭遗弃的毕妈妈（张纯芳）在他六岁时嫁给了从大陆到台的年近五十岁的公务员毕大顺（崔福生）。毕大顺对小毕视同己出，教他写字读书，准备把他培养成大学生。然而因为 被人看成“拖油瓶”，小毕与他的关系十分疏离，更不惜为了气他，做出偷漫画书、早恋、偷便当、和别人争强斗狠等举动。一件与钱有关的事，令毕大顺和小毕的关系降到最低点，毕妈妈在左右为难之际选择用极端方式激励小毕，让他看清更为丰硕的生命意义。©豆瓣', '崔福生', '陈坤厚', 8.3, 7235, 'tt0085695', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2327971610.jpg', 0.2, 0.6, 12.8, 54.7, 31.7, '0.208489,-0.133144,-0.700305,0.310688,-0.532564,-0.185749,0.512742,0.366391,-0.492735,-0.053592,-0.063923,0.512534,-0.290127,0.197502,0.401746,-0.377477,0.105401,-0.639786,-0.035815,-0.112096,-0.198811,-0.429875,0.136933,-0.099927,-0.521709,-0.471830,0.259170,-0.057523,-0.318046,0.087057,0.157791,0.095067,0.106909,0.271988,-0.040280,0.218541,-0.381997,0.092957,-0.413560,0.202809,0.231204,0.052088,-0.216813,0.207330,-0.045131,0.121059,0.904220,-0.001530,-0.199933,-0.402808,0.343760,-0.259107,-0.027241,0.027641,0.167818,0.207764,0.021434,0.444149,-0.048950,0.122160,0.235963,-0.169909,-0.620392,0.087679,0.134091,-0.116651,-0.482673,0.181180,-0.063449,-0.079805,0.371831,-0.531500,0.189449,0.490894,0.157796,0.516747,-0.302133,-0.029848,-0.708992,0.508370,0.718955,-0.078073,0.020029,0.467178,0.018754,-0.345363,0.325108,-0.435017,-0.284876,0.146979,0.225795,-0.005222,-0.151049,0.258364,-0.371146,-0.227872,0.057744,0.030050,0.198052,-0.594653,0.063669,-0.060463,-0.089547,-0.421767,-0.039066,0.110806,0.155684,-0.503413,0.646159,-0.510498,0.154269,0.265461,0.514474,-0.391355,0.391370,-0.047399,0.253886,-0.163099,-0.000417,0.126287,0.315010,0.214844,0.051626,-0.128980,0.115138,-0.147983,-0.129268,0.358031', '26418093', '1306530', '5446226', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305582', '超级学校霸王', '喜剧', '2043年7月1日，犯罪大王将军（卢惠光饰）被捕，一星期后由铁面无私的法官余铁雄（张卫健饰）主审。将军特派其黑社会爪牙健（郑伊健饰）返回50年前寻找铁雄，并将其洗脑使他无法进行审判。政府知情后特派飞龙特警铁面（刘德华饰）、扫帚头（张学友饰）及发达星（任达华饰）返回1993年去保护铁雄。时大雄为93年一中学长期留班生，常遭同学余忌安（许志安饰）作弄毒打，只有女友采妮（杨采妮饰）对他真心。飞龙三特警混进学校，扫帚头当上老师，铁面做大雄同学，星则任大雄跟班，帮大雄打赢忌安，并向他套取铁雄下落，但大雄却表示校内并无铁雄此人。在这时健亦扮成老师混入学校，另一边大雄母亲要改嫁理查德余……最终飞龙特警能完成任务吗？©豆瓣', '张卫健', '王晶', 7.5, 69413, 'tt0106545', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541350148.jpg', 0.7, 4.1, 32.6, 42.2, 20.3, '-0.265509,-0.105927,0.044389,-0.014196,0.158134,-0.108906,0.111385,0.076455,-0.408195,-0.374767,0.206904,0.289536,0.049079,0.139081,0.265668,0.000902,-0.573626,-0.640654,0.013323,-0.201781,-0.305874,-0.305374,0.255067,-0.176543,0.053358,-0.154269,0.337827,-0.140537,0.223639,0.646353,0.288047,0.174698,-0.131804,0.000701,0.089158,-0.037879,0.142838,-0.104442,-0.280710,0.174014,-0.139013,-0.177250,-0.292854,-0.148491,0.193080,0.235023,0.539035,-0.218031,-0.004511,-0.516642,0.175379,-0.146806,0.005266,-0.090495,0.338432,0.082473,0.064274,0.510776,0.000525,0.079118,0.042331,-0.296069,-0.249466,0.114569,-0.167499,-0.043486,-0.317075,0.193989,-0.202029,0.390607,0.013672,-0.199662,-0.142673,0.063731,-0.102593,0.099455,-0.194629,0.255975,-0.093578,0.556588,0.354848,0.057537,0.255140,-0.311070,0.209651,-0.377126,0.049147,-0.088809,-0.013992,0.013542,0.232362,0.091011,0.144051,-0.237712,-0.132590,-0.141549,-0.477378,0.189609,0.104680,-0.073179,-0.122199,-0.440286,0.333301,-0.062716,-0.030625,-0.042873,0.188100,-0.094147,0.428278,-0.723583,0.033904,0.318071,0.452172,-0.415161,0.369183,0.093958,-0.041591,-0.453385,-0.239693,0.049424,0.204328,0.423687,0.095142,-0.008710,0.051250,-0.513548,0.102879,-0.311077', '26365262', '4127270', '4202326', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305594', '黑马王子', '剧情', '冰（李嘉欣 饰）是一个上海著名企业家的女儿，为了寻找与自己的失散了十几年的亲生母亲，不惜瞒着父亲来到香港，并认识了“黑马王子”华弟（刘德华 饰），华弟好心收留了她，并与母亲一起帮她寻找生母。不料冰被人绑架，华弟协助警方救出了冰。冰受伤后，华弟更把自己的一部分肝脏捐给了冰。冰与父亲一起回到了上海，可是正在修养期间的她发现自己已经爱上了华弟。就在她生日那天，父亲说要介绍她认识一位“白马王子”……©豆瓣', '刘德华', '王晶', 6.2, 11674, 'tt0195185', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2354884281.jpg', 2.6, 13.9, 60.1, 17.3, 6.2, '-0.039732,0.023925,-0.507012,0.472248,-0.108602,-0.483704,0.497919,0.236679,-0.534545,-0.408214,-0.059092,1.018161,0.131913,0.353119,-0.044472,0.325153,-0.191030,-0.818957,-0.104583,-0.132257,-0.473588,-0.464165,0.011385,0.172126,-0.103364,-0.339151,0.162891,-0.065145,-0.035606,0.552320,0.332258,0.092807,-0.153352,0.501577,-0.363477,0.092479,-0.011820,0.362198,-0.296685,0.378417,0.098764,-0.211542,0.322848,0.228505,0.117682,0.407259,0.489985,-0.023101,0.127764,-0.339463,0.161392,-0.540751,0.192480,0.102176,0.450124,-0.069963,0.330212,0.332277,-0.455902,-0.118100,0.064593,-0.335491,-0.570543,0.111905,0.128398,-0.086241,-1.073940,0.598175,-0.017030,0.202133,0.105220,-0.359680,0.574899,0.378395,-0.176493,0.293921,-0.320253,-0.077137,-0.267425,0.379642,0.882677,-0.262950,0.548747,0.388111,-0.006482,-0.214467,0.097442,0.002825,-0.300721,0.144435,0.188718,0.076162,-0.493327,-0.063412,-0.444536,-0.388330,-0.414522,0.145171,0.246228,-0.538662,0.192800,-0.193761,-0.072067,-0.310983,-0.162860,0.067280,0.001611,-0.363504,0.560413,-0.848837,0.308357,0.597540,0.639230,-0.867144,0.686837,0.191609,-0.027251,-0.236414,0.123910,0.156371,0.273109,0.166040,0.147700,0.176471,0.019763,0.136505,-0.486381,0.037885', '1308035', '1293607', '1299965', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305595', '中华英雄', '动作', '国军的抗日战士小杰（李连杰 饰）经浴血奋战终于迎来抗战胜利，但是英雄的荣誉却属于美国军人。小杰赶到青岛投奔自己在军中的救命恩人张大哥（赵尔康 饰），其时张大哥刚把做陪酒女郎的女儿小蕊（宋佳 饰）赶出家门，小杰与张二人靠拉黄包车度日。在中国的美军飞扬跋扈，撞伤路人，小杰与美国军官汉斯对峙，引发群众将美军车辆烧毁。小杰在混乱的酒吧中响应美军挑战，登上拳台将对方击败。张大哥不堪女儿被美国兵调戏，却被对方殴打重伤。小杰为了给张大哥治伤筹钱，落入了美国兵的圈套，登上拳台做了人肉靶子。汉斯趁机再次向小杰挑战，二人混战之后张大哥和小蕊父女团聚，然而美国人的报复却仍然没有终止……©豆瓣', '李连杰', '李连杰', 6.4, 6082, 'tt0096507', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2501979120.jpg', 1.9, 12.4, 56.2, 21.5, 8, '0.333501,-0.180941,-0.403465,0.247602,0.006458,-0.498500,0.448424,0.035100,-0.273519,0.155052,0.429630,0.505335,0.132121,0.064910,0.259321,-0.170128,-0.342310,-0.720995,0.020799,0.287506,-0.157457,-0.265844,-0.213550,-0.083223,-0.112646,-0.115678,0.642086,0.039996,-0.299899,0.571578,0.204321,0.086703,-0.111632,0.505431,0.014622,0.258039,0.134823,-0.162114,-0.456375,0.177909,-0.241908,-0.426335,-0.278875,0.009783,0.096693,0.280607,0.651756,-0.133045,0.331387,-0.233165,-0.051714,-0.455972,0.069657,0.142133,0.150792,0.037426,0.183453,-0.003827,0.108373,-0.016677,0.046713,0.102400,-0.254190,0.321479,-0.031929,-0.225840,-0.587522,0.493508,-0.222003,0.263641,0.349420,-0.265424,0.251243,0.517473,0.161069,0.243816,-0.258719,0.013219,-0.587795,0.137491,0.654248,-0.345841,0.022020,-0.224038,-0.054188,-0.288349,0.419979,-0.410558,-0.289416,-0.073933,0.372110,-0.301188,-0.093539,-0.066747,-0.492056,-0.110282,-0.383151,-0.174688,-0.096739,-0.326932,-0.141109,-0.636203,0.028144,-0.020477,-0.199834,0.233517,0.049535,0.142958,0.665256,-0.542965,-0.150862,0.337851,0.432154,-0.439351,0.525863,0.019903,0.039986,-0.102996,-0.023527,0.052047,0.183569,0.494848,0.416160,0.201825,-0.258394,0.082062,-0.191503,0.198100', '26365262', '3811356', '1478066', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305605', '黄色潜水艇', '喜剧', '本片是一部将伟大的摇滚乐队披头士的音乐和波普视觉艺术完美结合而成的二维插画风格的动画片，整部片子中共穿插了披头士的15首经典歌曲。影片讲述了披头士成员保罗·麦卡特尼在半梦半醒之间来到花椒国，这是一个讨厌音乐的地方，正遭遇蓝色恶魔的侵略，老船长弗莱德召集披头士成员一同乘坐黄色潜水艇共同保卫花椒国。披头士音乐贯穿整个影片中：影片开头用George Martin（乔治·马丁，披头士音乐制作人）的弦乐描述祥和的花椒国，接着由Ringo Starr (林格·斯塔尔，披头士鼓手)演唱的“黄色潜水艇”(Yellow Submarine)则象征着花椒人民的朝气蓬勃。然而好景不长，坏蛋蓝心恶魔开始破坏花椒国的快乐与宁静，老船长征召披头士成员“一起来吧”(Come Together)，联手抗击蓝心恶魔，披头士成员装扮成花椒军士在“帕伯军士孤独之心俱乐部乐队”(Sgt Peppers Lonely Heart Club Band)的音乐中击溃了敌人，维护了他们的信念——“你需要的就是爱”（All You Need Is Love），拯救了花椒国。', 'The Beatles', '乔治·杜宁', 8.9, 11958, 'tt0063823', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1629215272.jpg', 0.2, 1, 9.1, 32.3, 57.4, '0.135991,-0.061743,-0.360251,0.809700,0.399916,0.014052,0.681218,0.393851,-0.278921,-0.076443,0.020005,0.607671,0.150802,0.124669,0.351791,0.087925,-0.484285,-0.671080,-0.369067,-0.097485,-0.018654,-0.208293,0.058836,-0.512713,0.025810,-0.424320,0.757378,0.038156,-0.278110,0.316862,0.440726,0.029463,-0.090622,-0.154510,0.173020,0.026187,0.459246,-0.442356,-0.391817,0.126616,-0.242682,-0.074821,-0.059357,0.066425,-0.232635,0.057421,0.693234,-0.644655,0.629752,-0.231437,0.248278,-0.200524,-0.040254,-0.380575,0.201046,0.312930,0.341530,0.274702,0.014505,0.029433,-0.222998,-0.362447,-0.647937,0.174391,0.013517,0.240299,-0.289172,0.414601,-0.089715,0.209588,0.374751,-0.009786,0.391829,0.005199,0.502032,0.559412,0.100952,0.004173,-0.316660,0.451739,0.756940,-0.093953,-0.389320,-0.029275,-0.389055,-0.423860,-0.351291,-0.432359,-0.327348,-0.208878,0.462377,-0.245304,0.539048,0.263717,-0.928981,0.014985,0.103596,-0.284744,0.188203,-0.300126,0.023811,-0.920794,0.025456,-0.074779,0.353445,0.113144,0.172105,0.051440,0.945618,-0.637105,0.186056,0.441738,0.057135,-0.120956,0.535623,-0.089213,-0.113931,-0.183733,-0.083007,0.379608,0.145499,0.044772,0.248005,0.443863,-0.078530,-0.039394,-0.459432,0.184706', '5403927', '26290398', '3811356', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305611', '异教徒', '悬疑', '20世纪70年代，苏格兰警官豪伊（ 爱德华·伍德华德 饰）收到一封信，信中称苏格兰西海岸的一个小岛——夏岛上的女孩罗恩·莫里森失踪已久，并向他求助破案。豪伊来到夏岛展开调查，发现岛上的氛围十分怪异。居民们先说不认识这个女孩，后又表示女孩已死。但豪伊没有找到女孩的尸体。失踪女孩的去向愈发不明。案件真相越来越扑朔迷离。豪伊又惊讶地发现岛上的居民是一群并不信仰耶稣基督的异教徒。夏岛勋爵（克里斯托弗·李 饰）更是似乎拥有极大的权力和声望。他们并不配合豪伊的调查。豪伊准备离开小岛时发现了小岛五月庆典中用活人来祭祀的传统，他准备一探究竟，然而他不知道危险正在向他靠近……', '爱德华·伍德华德', '罗宾·哈迪', 7.8, 6813, 'tt0070917', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1297560053.jpg', 0.8, 2.7, 24.8, 50.5, 21.2, '0.244258,-0.206540,-0.736916,0.397663,0.001813,-0.112004,0.872820,-0.228588,-0.538801,-0.489436,-0.093874,0.590384,-0.080608,0.142864,0.326514,0.268472,-0.559388,-0.409328,-0.039549,-0.331900,-0.357121,-0.666751,-0.293331,-0.502654,-0.083210,-0.100588,0.428072,0.274785,-0.120609,0.175727,0.092721,0.328530,-0.126376,0.857930,-0.173340,0.002051,0.165885,-0.099222,-0.092791,0.157172,0.074875,-0.144659,-0.513366,0.295221,0.165238,0.497292,0.532558,-0.320073,-0.239148,-0.254644,0.323463,-0.144407,0.064605,0.089166,0.467012,-0.032081,-0.115865,0.187683,-0.010057,-0.160750,-0.068848,-0.205636,-0.130562,0.420386,0.229793,0.462604,-0.338077,0.054220,-0.206897,-0.179715,-0.104004,-0.503953,0.265879,0.423034,0.168415,0.270291,0.125028,-0.069036,-0.495683,-0.217826,0.502129,0.153579,-0.103962,0.251720,-0.240155,-0.845391,-0.073984,0.204744,-0.299288,0.120859,0.125579,0.279614,-0.100292,0.022236,-0.407706,-0.168908,-0.224151,-0.301214,-0.164852,-0.461023,-0.232178,-0.652920,-0.094200,-0.192988,-0.175201,0.034667,0.043798,-0.017997,0.400598,-0.649832,0.141295,0.440157,0.396836,-0.281334,0.454720,-0.098991,-0.217003,-0.450919,-0.254147,0.424533,0.185707,0.240861,-0.039043,0.119257,0.073800,-0.388916,-0.103524,0.248357', '27617348', '35073565', '34614704', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305625', '千王1991', '喜剧', '台湾千术大师泰斗在与香港千王黄上千（黄百鸣 饰）一战中落败，从此与黄上千结下了仇怨。黄上千的徒弟阿伟（梁朝伟 饰）一日结识了从新加坡返港的寡妇苏茜，以为能从中大捞一笔，于是伙同任公子（任达华 饰）和师姐大波媚（叶子楣 饰）设局。岂料苏茜其实也是一个老千，阿伟他们不仅没能打捞一笔，反而落得一身债务。无奈之下阿伟只好请师傅黄大千出马，黄大千赢回了苏茜手上阿伟的签单后，与苏茜握手言和，并敲定一起合作对付奸商龙在天。他们轻而易举的把龙在天的两百万搞到了，龙在天不甘心就此被骗，于是请泰斗再次出战……©豆瓣', '梁朝伟', '于仁泰', 6.6, 5116, 'tt0102735', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510278963.jpg', 1.1, 8, 57.4, 25.3, 8.2, '-0.092307,0.229162,-0.277929,0.423746,0.023372,-0.475465,0.107722,0.038971,-0.257786,-0.097606,-0.281293,0.607837,-0.158383,0.233047,0.246731,-0.500201,0.028667,-0.561853,-0.134006,-0.163936,-0.134962,-0.735885,-0.186576,-0.085838,-0.254675,0.008303,0.258439,0.531397,-0.062922,0.580070,0.544419,-0.006480,-0.211941,0.275723,-0.318448,0.122451,0.061426,0.279150,-0.258294,0.317342,0.066406,-0.327093,0.111185,0.075566,0.330456,0.245480,0.399775,-0.352510,0.044681,0.087870,0.088081,-0.096847,-0.053415,0.221439,0.215637,-0.196124,0.430946,0.216135,-0.349125,-0.080183,0.489649,0.026676,-0.550475,0.200342,-0.115371,-0.142101,-0.765024,0.175418,-0.047044,0.154743,-0.201276,-0.235011,0.225974,0.491740,0.179211,0.023028,0.059083,0.029213,-0.721391,0.477964,0.564749,0.109634,0.365703,0.036792,0.483772,-0.460494,-0.195328,-0.212963,-0.083355,-0.109257,0.787883,-0.195476,0.138543,-0.281572,-0.475657,-0.268208,-0.168933,0.210628,-0.063548,-0.237307,0.233131,-0.174020,-0.258131,-0.199791,-0.123062,0.240369,0.165446,-0.293651,0.476739,-0.640730,-0.031823,-0.078597,0.399641,-0.547839,0.557599,0.095957,-0.009871,-0.062098,-0.013752,-0.485780,0.296156,0.399983,0.842654,0.351972,0.132017,-0.192628,0.271595,-0.118549', '1300857', '2084048', '1309069', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305655', '古镜怪谈', '剧情', '30年代的上海，马丽某年生日收到了表姐送来的一块古董梳妆台，可是表姐已在几年前被她设计迫害自杀了。她的丈夫是著名教授，可是两人年龄差异较大，丈夫有了外遇，对方竟是马丽的表姐，马丽愤怒设计杀死他们，最后自己也在那块镜子前自杀了。90年代的新加坡，律师詹辛为了丰厚的报酬，埋没良心为罪大恶极富家子辩护。他的妻子买来了一块古董梳妆台，每当他在镜前都会发生奇怪的事情。后来他因车祸毁容了，没想到整形医生拆开纱布的一刻他发现，自己的容貌跟富家子被杀害的人的模样。世纪末的香港，兰姨（罗兰饰）含辛茹苦独自带大孙子麦迪（谢霆锋饰），对他无比牵挂。可是孙子带回来洋气女友Ruby（林心如饰）令她很不满意。Ruby得知兰姨身价丰厚，便极力讨好她，杀害兰姨后嫁祸他人，她在新买回来的古董梳妆台中看到了幻觉，自杀身亡。©豆瓣', '谢霆锋', '刘晓光', 5.8, 16970, 'tt0206427', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2632136286.jpg', 4.9, 21.8, 55.1, 14, 4.2, '0.014903,0.064521,-0.662450,0.417558,-0.483479,-0.236140,0.737186,0.089448,-0.560155,-0.297057,0.525379,0.843282,-0.203540,0.250408,-0.001985,0.547757,-0.103591,-0.551611,0.136688,-0.294885,-0.369950,-0.333690,-0.464416,-0.318830,-0.031356,-0.179768,0.221575,-0.152894,-0.045680,0.254067,0.416663,0.004176,0.059851,0.445518,-0.397197,0.296137,0.085211,-0.016819,-0.025009,-0.103209,0.051945,-0.497670,0.063076,0.320095,-0.044966,0.397104,0.721163,0.123486,-0.180958,-0.046637,0.557005,-0.124860,-0.132894,0.213938,0.352717,0.082848,0.238435,0.151556,-0.364241,-0.309600,0.335114,-0.058577,-0.292114,0.012642,0.192952,0.040648,-0.715517,0.588818,-0.358492,0.236031,0.127050,-0.372364,0.297706,0.118619,0.085921,0.426777,-0.077161,-0.144122,-0.552520,0.490190,0.184600,-0.132141,0.342898,0.402751,-0.265749,-0.259960,0.135367,-0.323889,-0.544434,0.274237,0.310038,-0.183282,-0.338033,0.061905,-0.375372,-0.248547,-0.288117,-0.019774,0.051244,-0.297186,-0.229309,-0.103222,-0.196593,-0.369852,-0.473591,-0.080036,-0.042383,-0.373910,0.566555,-0.469454,0.202251,0.448800,0.266350,-0.526951,0.526005,0.040252,-0.155141,-0.107795,-0.107063,-0.073192,-0.036348,0.107474,0.211168,0.223939,0.048896,-0.085818,-0.174845,0.505582', '1292207', '3111650', '30140107', '1292780');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305662', '最佳拍档3：女皇密令', '喜剧', '黑猫（许冠杰 饰）身手敏捷，小有名气。一次，他在巴黎时忽然遭到不明身份的女杀手袭击，当他和对手一路打斗来到铁塔时，伏击在此的大钢牙和刚帽突然出击。措手不及的黑猫眼看性命不保，纵身跳下了塞纳河。当黑猫醒来的时候，一名自称占士邦的应该特工人员告诉他这是女皇对他的考验，现在他已通过考验，可以正式接受女皇的密令。信以为真的黑猫欣然应允，返港为女皇盗窃一枚极为贵重的宝石。当黑猫费尽九牛二虎之力完成任务后，发现事实并非如此。©豆瓣', '许冠杰', '徐克', 7.3, 14529, 'tt0088457', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1387576243.jpg', 0.6, 3.4, 42, 39.4, 14.5, '0.181783,0.224361,-0.780745,0.369435,-0.141869,-0.040792,0.677527,-0.090584,-0.470953,-0.393005,0.663053,0.910469,-0.217973,-0.179480,0.398899,-0.037097,-0.150009,-0.527355,-0.110257,-0.258305,-0.379535,-0.294570,-0.219737,0.104119,-0.037923,-0.239926,0.567630,0.206332,-0.202098,0.740400,0.484350,0.171700,-0.021925,0.435969,-0.333626,-0.278578,0.196419,0.057616,-0.100384,0.421249,-0.057096,-0.343012,-0.249421,0.247286,-0.221095,0.357156,0.413184,-0.525766,-0.359356,-0.226801,0.181934,-0.488108,0.084812,0.148588,0.336543,0.043362,0.143355,-0.094720,-0.066344,-0.000882,-0.051128,-0.133397,-0.740900,-0.028551,-0.123304,-0.024188,-0.601710,0.080956,-0.306875,0.218954,0.164401,-0.428582,0.010468,0.409323,-0.087924,0.224001,-0.182939,0.234440,-0.532522,-0.078672,0.499892,0.065428,-0.075781,0.256871,0.248360,-0.739889,0.177095,-0.203534,0.105111,0.063951,0.462794,0.350595,-0.375536,-0.091736,-0.297706,-0.173409,-0.532614,-0.020620,-0.163354,-0.441791,-0.314630,-0.562414,-0.015485,-0.234138,-0.164335,0.328879,-0.038104,-0.151416,0.470559,-0.895154,0.174280,0.369414,0.141051,-0.291399,0.430066,0.079578,-0.072583,-0.325663,-0.123039,0.013761,0.350368,0.404477,0.148159,0.237929,0.233387,-0.344208,-0.613261,0.270896', '1897368', '1420088', '35144311', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305666', '时时刻刻', '剧情', '跨越时空的三个女人，因为一个名字被联系起来----戴罗薇夫人。弗吉妮娅·伍尔芙(妮可·基德曼)，生活在上世纪20年代的伦敦郊区，正在完成她最后一部小说《戴罗薇夫人》。游走在虚构与现实生活边缘的她，承受着巨大的压力与被束缚感，内心甚至渴求着死亡。劳拉·布朗(朱丽安·摩尔)，生活在二战末期的洛杉矶家庭主妇。《戴罗薇夫人》引起她不断追问自己，什么才是更有意义的生活？日复一日的持家生活同样让她萌生自杀的愿望。克拉丽萨·沃甘(梅丽尔·斯特里普)，生活在90年代的纽约，正过着戴罗薇夫人式的生活。她深爱的朋友理查德，才华横溢却因艾滋病难以自理。好心的戴罗薇夫人担当起派对的主人，为每个人带来快乐，却难以化解内心的孤单与忧伤。不同的时空里，她们的内心深处，关于死亡的挣扎与抗争，没有停息，时时刻刻。©豆瓣', '梅丽尔·斯特里普', '史蒂芬·戴德利', 8.6, 147315, 'tt0274558', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1512031570.jpg', 0.4, 1.4, 12.6, 38.6, 47, '0.200902,0.165260,-0.626288,0.631232,-0.067873,-0.186258,1.241961,0.079736,-0.431541,-0.311801,0.215046,0.722957,-0.212132,0.397017,0.048242,0.116510,-0.370791,-0.475497,0.057109,0.264031,-0.022217,-0.348827,-0.270140,-0.279112,-0.371524,-0.381255,0.659642,0.000374,-0.097732,0.169098,0.059540,0.382216,-0.094594,0.487232,-0.285365,0.104884,0.070176,-0.063261,-0.461261,0.027933,0.349360,-0.050497,-0.113203,0.329209,-0.060604,0.000809,0.689232,-0.315933,0.130317,0.061549,0.492317,-0.129722,0.027734,0.160734,-0.061490,-0.059307,0.160683,0.175208,-0.095694,-0.176586,0.231639,0.058484,-0.684428,0.072996,0.318170,0.385880,-0.458618,0.456400,-0.297390,-0.121942,-0.136155,-0.358691,0.031795,0.253283,0.202461,0.440643,-0.424156,0.131569,-0.377102,0.278719,0.894351,-0.045249,-0.479085,0.237460,-0.566328,-0.242170,-0.080527,-0.294900,-0.983119,-0.264448,-0.010338,0.085635,-0.319016,0.699903,-0.612050,0.310813,-0.362324,-0.161379,0.034816,-0.589673,-0.128318,-0.485824,-0.324003,-0.269111,-0.321245,-0.199693,0.269004,-0.379052,0.632178,-0.805452,0.478460,0.692967,0.465094,-0.101555,0.609356,0.235711,0.137353,-0.155595,-0.005687,0.698107,-0.312596,0.136616,-0.044696,0.407858,-0.117948,0.476820,-0.337881,1.011531', '1291835', '1291877', '4275444', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305671', '拳王阿里', '剧情', '1964年，年轻的阿里（Will Smith 威尔• 史密斯 饰）凭着高超的拳术，坚韧的毅力战胜尼桑•里斯顿成为了新的拳王！时值越南战争期间，阿里拒绝服兵役，因为“越共没有管我叫黑鬼”。正因为阿里直率的性格，拒绝向自己认为错误的事屈服，阿里因此吃尽苦头：美国政府用尽方法企图将阿里投进监狱；拳击理事会剥夺了阿里拳王的金腰带，等等。在1964至1974这社会动荡的10年里，阿里表现出的坚忍不拔的毅力和决不屈服的独立性不仅对他个人，对拳击界甚至对整个社会都产生了巨大的回响，阿里亦因此成为黑人运动和反越战运动的精神领袖。最终在1974年，阿里凭着过人的毅力，以34岁的运动高龄，再次向拳王发出了挑战！©豆瓣', '威尔·史密斯', '迈克尔·曼', 7.3, 8333, 'tt0248667', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2208821206.jpg', 0.7, 4.3, 37.3, 44, 13.7, '0.111739,0.005706,-0.720025,0.683411,-0.360772,-0.506463,0.557714,0.241144,-0.295295,-0.286136,0.369427,0.572474,-0.038960,-0.339289,0.243896,-0.295752,0.121711,-0.833076,-0.110200,0.209436,-0.118443,-0.517435,-0.196952,-0.070528,-0.262120,-0.499341,0.584660,-0.074988,-0.567663,0.538728,0.334918,0.359233,0.611991,0.279417,0.090316,-0.279575,-0.033063,-0.076289,-0.314729,0.198682,0.217340,-0.231475,-0.145379,0.066675,-0.131819,0.272156,0.258954,-0.393101,-0.039566,-0.096799,0.453577,-0.261350,-0.168880,0.202016,0.197290,-0.048699,-0.086787,0.340003,-0.022954,-0.002890,0.131687,0.170370,-0.752356,-0.203955,0.131787,-0.068084,-0.813846,0.493511,-0.203774,-0.299889,0.123661,-0.201812,-0.379092,0.340038,0.068961,0.498209,-0.107734,0.148508,-0.367049,-0.221861,0.455291,-0.007379,-0.647666,-0.261110,-0.080176,-0.509537,-0.009928,-0.598083,-0.224351,-0.227336,0.122379,-0.136878,-0.161264,0.428971,-0.574112,0.074621,-0.057837,-0.430600,0.151236,-0.325013,-0.029833,-0.547042,-0.219456,-0.438272,-0.215778,-0.108255,0.230285,-0.415540,0.764833,-0.920103,0.341537,0.473308,0.387320,-0.292286,0.657017,-0.094887,-0.245101,-0.068776,-0.125393,0.336174,0.115145,0.248950,0.096314,0.327809,0.244734,-0.287021,-0.224153,0.589381', '35144311', '3006892', '2156945', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305686', '惩罚者', '剧情', '弗兰克·卡斯特（托马斯·简 Thomas Jane 饰）的生命中，绝大部分时间都在于死神赛跑。早年在海军陆战队服役，退役后又进入FBI。在枪炮火光中生活了多年之后，弗兰克不愿再整日收到死亡的威胁，家人整日为他担惊受怕。所以，他决定提前退休与妻儿享受平静的生活。可是，在最后的一次任务中，却因意外使一名无辜青年死亡。而这名青年的父亲却是坦帕市的大富商霍华德·桑特（约翰·特拉沃塔 John Travolta 饰）。为了给儿子报仇，霍华德向黑市发出了对弗兰克一家的绞杀令。不过弗兰克却侥幸在这场浩劫中存活下来。为了报仇，弗兰克不再寄望于法制，而是全副武装向霍华德发起挑战。面对霍华德组建的私人军队，弗兰克凭一己之力将如何应对？©豆瓣', '托马斯·简', '乔纳森·汉斯雷', 6.5, 16344, 'tt0330793', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1356756326.jpg', 2, 11.3, 54.2, 24.5, 8, '-0.171691,0.167031,-0.604404,0.642937,-0.304042,-0.541188,0.720573,-0.070606,-0.496422,-0.321158,0.110728,0.797315,0.215809,0.219590,0.254608,-0.291844,-0.190291,-0.619670,-0.195342,-0.140467,-0.282886,-0.409637,-0.300551,-0.336578,-0.107402,-0.327304,0.694382,0.199997,-0.066190,0.408144,0.307266,0.584812,0.061440,0.420325,0.026336,-0.209168,-0.069078,-0.061810,-0.548031,0.316079,0.101177,-0.309858,-0.321926,0.194999,0.240318,0.368593,0.646219,-0.325692,0.065451,-0.390707,0.038842,-0.157691,0.016137,0.216459,0.049866,-0.014675,0.055916,0.182779,-0.143495,0.090106,-0.020749,-0.087883,-0.827046,-0.036056,-0.178840,0.093081,-0.573605,0.417688,-0.128071,-0.027410,-0.068296,-0.275686,0.061889,0.437204,0.267530,0.310817,-0.455302,0.087599,-0.355433,0.104620,0.719565,-0.132385,-0.218487,-0.045089,-0.179378,-0.234259,0.152932,-0.314679,-0.489243,-0.197437,0.178446,0.060992,0.084269,0.395999,-0.429199,0.036782,-0.428096,-0.316947,-0.132816,-0.380771,-0.165150,-0.594508,0.203699,-0.047809,-0.258186,0.223198,0.201147,-0.198278,0.497423,-0.727345,0.355974,0.506498,0.335822,-0.341721,0.417015,0.196284,0.482581,-0.194480,0.008578,0.418813,0.184133,0.344622,0.269472,-0.040999,-0.023282,-0.159826,-0.110761,0.487198', '30345227', '25828589', '1482099', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305690', '阿飞正传', '剧情', '1960年代的香港，因生母在阿飞旭仔（张国荣）长大成人过程中的缺失，他把自己优雅地比喻为“无根鸟”，对生命中遇到的每一个女人都表现得放荡不羁，售票员苏丽珍（张曼玉）和舞女咪咪（刘嘉玲）先后令他感受过温暖，可是她们也只能当当小情人。为摆脱沉重和无力感，旭仔抛下一切去南洋找寻生母。暗恋过苏丽珍且目睹过她与旭仔情感一路变化的，曾是小巡警今在跑船的超仔（刘德华）在菲律宾又遇到旭仔，是缘分也是宿命，他参与、见证了阿飞命运被改写的过程。©豆瓣', '张国荣', '王家卫', 8.5, 473466, 'tt0101258', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2525770523.jpg', 0.2, 0.8, 12.8, 46.4, 39.9, '-0.045675,-0.010663,-0.555773,0.471525,-0.353606,-0.058419,0.798986,-0.052271,-0.650550,0.100509,0.210678,0.719400,-0.400844,0.185405,0.072047,0.115281,-0.136371,-0.830277,-0.098059,0.108890,-0.215147,-0.246580,-0.240975,-0.022374,-0.240988,-0.193960,0.563702,0.102953,-0.364885,0.327617,0.255042,0.011396,-0.314537,0.512005,-0.442870,0.257772,-0.182626,0.204994,-0.334963,-0.066838,0.091237,-0.425606,-0.199724,0.164965,-0.141774,0.242452,0.702351,-0.139616,0.026463,-0.154774,0.105401,0.018509,-0.189682,0.069283,0.096037,0.234141,0.147934,0.337066,-0.069748,-0.139934,0.088604,0.092633,-0.741896,0.136245,0.154470,0.155324,-0.597355,0.440599,-0.177005,-0.071775,0.229836,-0.448541,0.241112,-0.066934,0.260663,0.453059,-0.288303,-0.011302,-0.399597,0.351920,0.909925,0.122015,-0.168270,0.618848,-0.256757,-0.509149,-0.094993,-0.249657,-0.294296,0.280778,-0.126343,0.085522,-0.359629,0.488789,-0.533838,0.155551,-0.210852,-0.121909,-0.056940,-0.574953,-0.082443,-0.323780,-0.147061,-0.513297,-0.486557,0.109145,0.095653,-0.411158,0.650891,-0.708859,0.281629,0.705957,0.219498,-0.323751,0.926587,0.312504,0.029950,-0.276315,0.016058,0.435333,-0.267572,0.158077,0.192914,0.193531,-0.287292,0.000842,-0.424340,0.596428', '30162520', '3055049', '4604803', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305697', '桥', '动作', '1944年，德军投入重兵守卫南斯拉夫境内的一座大桥，党卫军上校霍夫曼博士处心积虑防止南游击队的攻击。同一时间，游击队少校“老虎”（Velimir ''Bata'' Zivojinovic 饰）接到上级命令：为阻止德军汇合，必须在七天之内找到建桥工程师将桥炸毁。老虎与老战友——爆破专家扎瓦多尼（Boris Dvornik 饰）以及他的助手班比诺、沉默寡言的战士狄希、曾参与建桥的游击队员曼纳，组成了一支行动小队。老虎从盖世太保手中救出工程师，在接近大桥的过程中与德国护卫军队发生激战，有游击队员与联络员牺牲了，但也有新的力量补充进来。在破解了德军的间谍渗入之后，游击队员们终于将大桥炸毁。©豆瓣', '韦利米尔·巴塔·日沃伊诺维奇', '哈伊鲁丁·克尔瓦瓦茨', 8.8, 21586, 'tt0074921', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2576327873.jpg', 0.3, 0.6, 9.5, 38.9, 50.8, '0.017905,-0.386652,-0.474785,0.494842,0.128960,-0.235077,0.536684,-0.252194,-0.399749,-0.144159,0.410728,0.324162,0.330576,-0.393775,0.305403,-0.334615,-0.377788,-0.754599,-0.163444,-0.022447,-0.275628,-0.636678,-0.241877,-0.371450,0.395418,-0.654907,0.821276,0.074673,-0.173185,0.343857,-0.145949,0.275287,-0.204103,0.292816,0.022260,0.011222,0.460601,-0.693725,-0.381871,0.087517,-0.232592,-0.088270,-0.011704,-0.301083,0.160173,0.335793,0.707221,-0.509792,0.191315,-0.024856,-0.204867,-0.319129,0.301063,0.071931,0.642575,0.321133,-0.146499,0.139706,-0.140596,0.080386,-0.254783,-0.028433,-0.315146,-0.202609,-0.025375,0.020191,-0.504427,0.343577,-0.121084,0.527503,0.231303,-0.279260,0.216417,0.729647,-0.195476,0.223910,-0.240657,0.019455,-0.614347,0.037796,0.690223,-0.307111,-0.155483,-0.405652,0.091523,-0.346974,0.077656,-0.199414,0.036009,-0.015943,0.166306,-0.157121,0.116109,0.107372,-0.831799,0.092028,-0.606478,-0.200892,0.121582,-0.112012,-0.235152,-0.928756,0.129780,0.189839,-0.012944,0.433503,-0.046128,0.224278,0.719219,-0.655062,0.003904,0.418862,0.424135,-0.081269,0.501141,-0.162338,0.155743,-0.260079,0.207194,0.076921,0.210414,0.856850,0.283550,0.356194,-0.285899,-0.533668,-0.141016,-0.300780', '1306809', '20274039', '1307897', '1449328');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305703', '一声叹息', '剧情', '梁亚洲（张国立 饰）掉进了一个关系里。一方面他是宋晓英（徐帆 饰）的丈夫，一个可爱女儿的父亲；而另一方面，他却是李小丹（刘蓓 饰）的男朋友——他们在海南有一段浪漫的回忆。当宋晓英知道了丈夫竟有婚外情，绝然离婚。然而顾念女儿年幼，两人决定先分居。梁亚洲觉得悲伤，因为他失 去了一个熟悉的亲人，然而他却也放不下另一边的柔情。事情从宋晓英摔伤开始有了变化。梁亚洲那段时间一直留在家里服侍妻子，照顾女儿，经历过这些日子，他才切身体会到了当妻子的不容易。他和李小丹的来往也少了，而有一天，当宋晓英跟对面的李小丹平静谈起自己和丈夫多年的生活时，李小丹似乎明白了什么，她转身离去。这个家庭似乎又找回了幸福的时光。然而，一个电话却使一切都变得可疑……©豆瓣', '张国立', '冯小刚', 7.6, 43384, 'tt0276504', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2415041576.jpg', 0.5, 1.8, 31.1, 49.3, 17.3, '0.254755,0.053727,-0.887799,0.624596,-0.267004,-0.590922,1.053664,0.026983,-0.521478,-0.422873,-0.072342,0.715341,0.061555,0.535173,0.055187,0.141253,-0.165246,-0.675987,0.265111,-0.090017,-0.235007,-0.361140,-0.230600,-0.227538,-0.027667,0.064585,0.316358,0.121525,0.031176,0.459290,0.362423,-0.083320,-0.003513,0.777002,-0.070258,0.244990,-0.119715,0.509501,-0.170491,-0.128232,0.323770,-0.310990,-0.295323,0.223855,0.106998,0.609437,0.410562,0.134722,-0.332334,0.145430,0.369664,-0.151191,-0.063646,0.167064,0.181360,0.060415,0.061890,-0.027450,-0.369672,-0.080375,0.000806,0.014134,-0.568046,0.005910,-0.033553,0.045093,-0.699775,0.535501,-0.016926,-0.187278,-0.019534,-0.263278,0.506214,0.386854,0.162817,0.541372,-0.321210,0.229640,-0.363605,0.335959,0.845257,-0.023834,-0.202520,0.599603,-0.226167,-0.510466,-0.136535,-0.117691,-0.579801,0.006722,0.235676,-0.031670,-0.283917,0.107858,-0.300844,-0.010833,-0.049889,-0.033373,-0.129976,-0.533585,0.136142,0.129792,-0.314013,-0.652573,-0.468553,0.246335,-0.126790,-0.377539,0.711692,-0.638393,0.289320,0.375313,0.286811,-0.888591,0.621668,0.419400,0.247789,-0.277652,0.202154,0.469037,-0.231380,0.006346,0.237204,0.204384,-0.123373,0.068839,-0.400726,0.488347', '26718282', '1308206', '10355329', '20388680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305713', '嫁个有钱人', '剧情', '阿Mi（郑秀文饰）的爸爸开了一间小小的煤气店，所以她需要帮助父亲打理生意，每天都要扛着重重煤气罐送货。看着流星滑过，许愿能嫁个有钱人，突然从天上掉下来一本叫《玻璃鞋》的书。原本并不富裕的阿Mi决定乘坐头等机舱希望能在飞往米兰的时候遇上有钱男子，遇到了学识渊博的富家子弟阿诞（任贤齐饰），两人在米兰共渡了一段浪漫时光，可是阿诞突然就失踪了。阿Mi很不甘心，决定要把阿诞找回来。阿Mi感到沮丧的时候，她的一个老朋友如今是城中的钻石王老五，并且找回阿Mi是决定跟她求婚的，可是阿Mi已经爱上了偶遇的阿诞。但她却不知道，其实阿诞也有不可告人的秘密。©豆瓣', '郑秀文', '谷德昭', 5.9, 50631, 'tt0311364', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p482185590.jpg', 2.9, 18.9, 62.6, 12.7, 2.8, '0.324246,0.072327,-0.576363,0.411093,0.002694,-0.507964,0.677380,0.191786,-0.143189,-0.383416,-0.000293,0.483180,0.058321,0.164530,0.060974,0.171176,-0.259300,-0.486948,0.164544,-0.478701,-0.271311,-0.376133,-0.151427,-0.206685,-0.161736,-0.019756,0.296516,0.180319,0.022921,0.249742,0.412209,0.149298,0.328330,0.569528,-0.514589,-0.127288,-0.041694,0.510722,-0.089918,0.253743,0.214060,-0.134154,0.060345,0.019452,0.330710,0.245885,0.469235,-0.136303,-0.128791,0.253272,0.086078,-0.050124,-0.037826,0.009947,0.149516,-0.033878,0.036926,-0.063787,-0.214764,-0.010142,0.416114,-0.179415,-0.299058,-0.038552,0.234508,0.103590,-0.778374,0.243262,-0.223889,-0.064179,0.033178,-0.661695,0.377068,0.375701,0.442063,0.507557,0.065293,0.201027,-0.850732,0.180544,0.827247,-0.000231,0.251455,0.594443,-0.385171,-0.622069,0.128577,0.099076,-0.550284,0.135180,0.404127,-0.140872,-0.191320,0.096230,-0.320491,-0.069946,-0.101750,0.008255,-0.066104,-0.594782,0.046942,-0.031402,-0.070982,-0.119588,-0.091078,0.349170,-0.006085,-0.176203,0.545185,-0.801364,0.213147,0.504376,0.339270,-0.313096,0.874227,0.122401,-0.235277,-0.272456,0.243633,-0.274598,-0.005075,0.126866,0.086564,0.386751,0.167346,-0.317520,-0.280777,0.324807', '1302384', '3055049', '26769480', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305720', '大太监李莲英', '剧情', '同治皇帝病重，李莲英（姜文 饰）力荐慈禧（刘晓庆 饰）二次垂帘听政，不久同治身亡，慈禧立载湉为帝，继续把持朝政。1882年，李莲英陪同醇亲王巡视北洋水师，返京后却遭都察院纠弹，被革职处理，在慈禧的主张下，李莲英官复后宫大总管原职。李莲英为使侄女有个好归宿，将其带入宫中， 岂料只落得奴婢下场，他心中充满愧疚。光绪日渐成长，不甘受慈禧摆布，试图从慈禧手中夺权却被强力镇压，李莲英畏惧慈禧淫威，奉命将珍妃处死。不久八国联军入侵，清军连战连败，李莲英随慈禧微服出逃，途中在农户家中落脚，农妇的一席话，令李莲英与慈禧若有所悟……©豆瓣', '姜文', '田壮壮', 7.3, 11052, 'tt0101641', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2293937058.jpg', 0.3, 3.1, 39.5, 44.6, 12.6, '-0.261582,0.205271,-0.622040,0.425499,0.006386,-0.001336,0.503958,0.646069,-0.856908,-0.180284,0.586757,0.477517,-0.483960,-0.071180,-0.067879,-0.168171,-0.329982,-0.366206,-0.037182,0.035639,0.209128,-0.142293,0.092827,-0.265882,-0.454354,-0.206940,0.741621,-0.008636,0.218703,0.141978,0.356275,0.264856,0.034447,0.593953,-0.103759,0.279633,-0.180602,-0.639742,0.017062,0.069486,0.162412,-0.915431,-0.416702,-0.041147,-0.004536,0.042135,0.206805,-0.459056,0.168336,-0.553748,0.263169,-0.084109,-0.207877,0.594017,0.232924,0.414506,-0.338358,0.577653,-0.345061,0.068949,-0.131423,-0.037219,-0.051002,-0.063440,0.198738,-0.118147,-0.198345,0.170664,-0.146336,0.142741,-0.235133,-0.345402,0.294661,0.504692,-0.012765,0.325480,-0.291207,0.305068,-0.223306,0.458590,0.443275,-0.326634,-0.190094,-0.381842,0.308375,-0.107132,0.595710,-0.334745,-0.034215,-0.025700,0.396724,0.020227,0.059523,0.508550,0.284668,-0.318538,-0.756757,0.386704,-0.019611,-0.051106,0.094460,-0.090503,-0.026269,-0.055676,-0.355742,-0.014533,0.517312,-0.038772,-0.061095,0.048831,0.443273,0.185873,0.167633,-0.648770,0.144857,0.045013,0.322457,0.135459,0.027583,0.120482,0.144000,0.027895,0.061823,-0.028702,-0.446927,-0.355329,-0.234466,-0.003514', '1301081', '1437318', '3412830', '1305366');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305724', 'X战警2', '动作', '第一集中，变异人在X教授的指挥下，将邪恶的万磁王打入冷宫，但是依然得不到社会的承认。在一次政治要人遭到暗杀后，所有的矛头又一次指向变异人。这一次，X教授也感到压力大增，以致于跟美国总统都要就此事进行磋商。一个拥有很高声誉的前将军，率领着反对变异人的联盟连续对x教授施压。万磁王在这种情况下，不得不寻找与X教授联手抵抗前将军的方式。金钢狼的身世也将在本集中进一步揭开。', '帕特里克·斯图尔特', '布莱恩·辛格', 7.7, 223557, 'tt0290334', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p726784568.jpg', 0.2, 1.4, 28.2, 52.7, 17.5, '0.084696,-0.226720,-0.802656,0.898776,-0.114620,-0.112670,0.552126,0.023106,-0.559171,-0.193693,0.565383,0.650559,-0.122887,-0.241407,0.223570,-0.376672,-0.275726,-0.659062,-0.128754,0.041102,-0.494350,-0.606753,-0.269287,-0.555373,-0.031392,-0.466433,0.691856,-0.074042,-0.600710,0.494685,0.209600,0.428526,0.195096,0.732224,0.006375,-0.042773,-0.028879,-0.169508,-0.303004,0.473262,0.456785,-0.144130,-0.208550,0.301104,0.048008,0.094133,0.630166,-0.740201,-0.272255,-0.175749,0.104646,-0.689692,-0.066943,0.243260,0.775431,0.211232,0.011435,0.668301,-0.177200,0.120001,-0.039061,0.322870,-0.994736,-0.166176,0.069005,0.085733,-0.782767,0.593902,0.005758,0.304371,-0.121192,-0.512467,0.073834,0.604715,0.137031,0.119953,-0.152477,-0.078163,-0.428437,-0.256464,0.939597,-0.018298,-0.300579,-0.062032,-0.097502,-0.409435,-0.125173,-0.355068,-0.304176,0.058079,0.019773,0.265341,-0.220621,0.500555,-0.696040,-0.012306,-0.393589,-0.307641,0.010126,-0.608587,0.141227,-0.532440,-0.210330,-0.167972,-0.359307,0.089692,0.304226,-0.175841,0.899415,-0.924944,0.183505,0.489140,0.621097,-0.523568,0.568267,0.188141,0.174605,-0.077290,-0.564477,-0.254976,0.320662,0.848230,0.078210,0.380472,0.232760,-0.369616,-0.341401,0.282003', '25917239', '30163500', '3755531', '26981174');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305725', '大卫·戈尔的一生', '剧情', '贝茜•布鲁姆（凯特温斯莱 Kate Winslet饰）是纽约某新闻杂志的知名记者，她接到了一个任务是去采访一名死刑犯大卫•戈尔（凯文•斯帕西 Kevin Spacey 饰）。戈尔的罪名是强奸并谋杀了康丝坦斯•哈拉维，并将于周五下午6点被处以死刑，那么布鲁姆将要采访并记录的就是戈尔人生最后的三天，而此前戈尔拒绝了一切采访。布鲁姆起初对这个任务很不以为然，但在和戈尔的接触过程中，她发现一切并非表面呈现的那么简单，于是布鲁姆决定用仅剩的三天开始寻找真相……电影《大卫戈尔的一生》的导演艾伦•帕克凭借该片提名2003年柏林国际电影节金熊奖。©豆瓣', '凯文·史派西', '艾伦·帕克', 8.6, 209223, 'tt0289992', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2186861098.jpg', 0.5, 1, 10.6, 44.4, 43.6, '0.244076,-0.031356,-0.343463,0.433579,0.046957,-0.387287,0.309862,0.240590,-0.593882,-0.417508,0.053548,0.855391,-0.437909,-0.252680,0.446573,-0.053033,-0.662149,-0.581540,0.105323,-0.164037,0.133242,-0.915140,-0.008826,-0.290705,0.108465,-0.289673,0.615179,-0.103665,0.013064,0.469404,0.458557,0.441556,0.268230,0.541558,-0.021256,0.001308,0.322082,-0.495139,-0.302418,0.598089,0.242983,0.054089,-0.208737,0.378795,0.148023,0.522953,0.299603,-0.159975,-0.287624,-0.004463,0.648428,-0.574813,0.024667,0.102161,0.377130,-0.002011,0.289872,0.504574,-0.177638,0.173992,0.074846,-0.165518,-0.529325,-0.204931,-0.121959,0.566601,-0.398262,0.277771,-0.266127,0.168862,-0.126504,-0.401787,0.008703,0.278627,0.230791,0.145635,0.097937,-0.263552,-0.494868,0.067735,0.274706,-0.082824,-0.053120,0.507335,-0.088878,-0.456125,-0.117235,0.141055,-0.243521,0.316222,0.274916,-0.021858,-0.195298,0.358824,-0.539697,-0.138642,-0.619135,-0.502694,-0.155847,-0.556277,-0.094631,-0.998336,0.078682,0.073606,-0.430164,-0.413615,0.134946,-0.181697,0.369619,-0.737890,0.410820,0.619615,0.206370,0.022645,0.517961,0.295521,0.004158,-0.169326,0.029521,0.483132,0.156703,0.200293,-0.065071,0.499940,0.401866,-0.616277,-0.459830,0.555009', '1484091', '1298616', '2028645', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305789', '新僵尸先生', '喜剧', '善良的道长林正英（林正英 饰）开设祭坛，供奉那些被母亲堕胎以致肉体毁灭无法投胎的灵婴。祭坛中的灵婴大多天真可爱，但有三个因三番五次被堕胎，戾气十足，邪恶无比。道长命徒儿秋生（钱小豪 饰）和文才（许冠英 饰）将婴灵的偶人送至师妹蔗姑（吴君如 饰）处供养，却不慎将尚未修炼完毕的邪恶灵婴放走，附在正英旧情人莲妹（关秀媚 饰）的身上。莲妹嫁给某军阀，军阀为怪病困扰，请来正英师徒。正英检查军阀家墓穴得知，军阀父亲已幻化成僵尸，尸毒为害子嗣。另一方面，正英偶然发现邪婴出现于帅府，知其中有变，遂急忙找来……©豆瓣', '钱小豪', '刘观伟', 7.9, 33980, 'tt0105857', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2457362230.jpg', 0.3, 2.1, 26.3, 45.4, 25.8, '0.067060,-0.052353,-0.170153,0.163130,-0.025328,-0.153288,0.640639,0.102352,-0.439873,-0.473238,0.025165,0.374799,0.079689,0.032998,-0.216167,-0.000454,0.352678,-0.278227,-0.082994,0.177256,-0.029404,-0.065610,-0.033065,0.149751,-0.272018,-0.557552,0.565743,0.101316,0.048829,0.162187,0.188887,0.578220,-0.562748,0.068397,-0.299648,0.274993,-0.331145,-0.159268,-0.125896,0.207401,-0.045386,-0.229328,0.208383,0.101784,-0.376905,0.337563,0.634767,-0.201039,-0.184685,-0.618639,0.570050,-0.050788,-0.154522,0.249193,0.258563,0.358235,0.241474,0.342556,-0.201270,-0.018564,0.329721,0.040732,-0.557193,0.129626,0.400414,0.065046,-0.223332,-0.016808,0.045245,-0.094974,-0.043304,-0.101048,0.387400,0.188102,-0.033164,0.138191,-0.238870,0.033799,-0.347770,0.027141,0.145762,-0.236623,0.156845,0.132676,0.093746,-0.287087,0.593102,-0.397266,-0.026224,0.106812,0.122847,0.162937,-0.107904,0.054162,-0.363076,-0.322055,-0.354107,0.457684,0.055672,0.010533,-0.144907,-0.199330,-0.279496,-0.016387,-0.054213,-0.124541,0.274632,-0.014837,0.596112,-0.387921,0.133477,0.089385,0.335289,-0.390828,0.387367,-0.234971,0.002746,-0.199449,-0.132220,0.133977,0.050688,0.352515,0.092447,0.036446,0.000762,-0.042444,-0.185133,-0.114399', '26759820', '26667010', '25774051', '1292523');
