INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305791', '王子与公主', '喜剧', '夜幕低垂，万籁俱静，六段穿梭时空的故事，古老而华丽的剧场，带领我们走进妙不可言的梦境里。这是一部独具特色的剪影动画，三个主创人物——老人、男孩和女孩聚在一个古老的剧场内，利用他们丰富的想象力以及一台神奇的制衣机器，一边设计服装、撰写剧情，一边创造角色、自行演绎，一则则别具一格的“王子与公主”寓言故事就此诞生。他们创作了六则故事，分别为《钻石公主》、《无花果少年》、《女巫城堡》、《老太太的外衣》、《残酷女王与法布鹭训练师》以及《王子与公主》。故事背景设定在不同时空里，从中世纪到公元三千年，从古埃及到古代日本，延续了古老寓言的同时又颠覆传统。本动画为芝加哥国际儿童影展最佳动画影片。©豆瓣', 'Arlette Mirapeu（voice）', '米歇尔·欧斯洛', 8.7, 15562, 'tt0229664', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p812841916.jpg', 0.2, 0.9, 11.1, 38.7, 49, '0.034074,0.245832,-0.313245,0.870591,0.254276,0.089598,0.682631,-0.104812,-0.431449,-0.405588,0.537196,0.684738,-0.171635,0.108076,0.529944,-0.129301,-0.672295,-0.407373,-0.272519,-0.261626,-0.177164,-0.237568,-0.211216,-0.246658,-0.035003,-0.480201,0.871925,-0.085021,-0.482713,0.147572,-0.004310,0.090699,-0.705062,-0.242970,-0.245020,-0.093656,0.190876,0.188895,-0.312076,0.272887,-0.332423,-0.072714,-0.067135,-0.139736,-0.311561,-0.127575,0.800590,-1.031763,0.271825,-0.092635,0.786585,0.180031,-0.479594,-0.025413,0.148446,0.113476,0.504585,0.076094,0.099803,0.007325,-0.101714,-0.618357,-0.803696,-0.115731,0.183396,0.125517,-0.323136,0.345536,-0.036985,-0.315267,0.401983,-0.394241,0.272779,-0.175490,0.878909,0.718143,0.130803,-0.053952,-0.229819,0.553484,0.275895,0.195913,-0.350210,0.353197,-0.185686,-0.566361,-0.272212,-0.259977,-0.413196,0.045968,0.124549,-0.229593,0.375584,0.314451,-0.927662,0.133173,-0.092700,-0.173337,0.317698,-0.379359,-0.212980,-0.781526,-0.030800,-0.097857,0.404773,-0.027286,0.365136,-0.208959,0.976264,-0.590016,0.189632,0.161650,-0.015444,-0.209360,0.630476,-0.372993,0.203852,-0.432188,-0.246624,0.138897,-0.153308,0.261783,-0.308675,0.657332,-0.222563,-0.098659,-0.685128,0.362420', '22265121', '1322847', '5938000', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305793', '活跳尸', '喜剧', '瑞典密斯科汤尼克医学院，年轻的学生肯恩（Bruce Abbott 饰）和院长的女儿梅根（Barbara Crampton 饰）暗中相恋，两人相约在肯恩毕业后正式结婚。不久，天才医师赫伯特•韦斯特（Jeffrey Combs 饰）自澳大利亚归来。在澳期间，他曾与另一位科学家研究一种令死者复活的药物，但该药物的副作用是复活后的人皆丧失心智，失性狂乱，他的研究伙伴即在一场事故中丧生。韦斯特找到肯恩的公寓，希望与之合租。他始终不忘复活药物的研究，并争取到肯恩的帮助。然医学院院长却因韦斯特在澳洲的事故而禁止相关研究，最终酿成一起惨案。另一方面，与韦斯特针锋相对希尔教授（David Gale 饰）也觊觎着这项惊世研究……©豆瓣', '杰弗瑞·考姆斯', '斯图尔特·戈登', 7.4, 8133, 'tt0089885', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1682645836.jpg', 1, 4.3, 36.5, 41.6, 16.6, '0.254282,-0.039837,-0.516950,0.419064,-0.001165,-0.535112,0.500217,0.005927,-0.502162,-0.638969,0.169323,0.628412,-0.104129,0.245676,0.158519,-0.199977,-0.381837,-0.617797,0.268573,-0.179157,-0.395412,-0.576546,-0.390395,-0.210083,-0.002331,-0.670208,0.653242,0.008504,-0.014542,0.576641,0.008723,0.391159,-0.072692,0.377166,0.083853,-0.142758,0.323486,0.134276,-0.544678,0.197208,0.285660,-0.330798,-0.147154,-0.038707,0.261348,0.319497,0.679914,-0.180654,-0.062589,-0.209366,0.244962,-0.225769,0.016174,0.147413,0.357832,0.073412,0.227417,0.488298,-0.213917,-0.089133,-0.001136,0.113828,-0.443380,-0.149834,0.280771,0.300312,-0.520247,0.476997,-0.094983,0.022222,-0.087466,-0.164105,-0.014738,0.554395,0.141276,0.417447,0.022207,-0.164217,-0.475930,0.269620,0.505837,-0.360018,-0.154322,0.199213,-0.105608,-0.665449,0.087287,-0.139743,-0.453032,0.096023,0.126229,0.103658,0.004989,0.308394,-0.496828,-0.148736,-0.463820,0.062286,-0.015464,-0.106324,0.176224,-0.895081,-0.011491,-0.195889,-0.390823,-0.128487,0.299029,-0.316174,0.603492,-0.933699,0.271885,0.335761,0.182348,-0.518397,0.540482,0.160921,0.388379,-0.481576,-0.368548,0.295479,0.057781,0.355932,-0.119644,0.326501,0.425758,-0.092230,-0.369501,0.280115', '2369613', '25723905', '20274039', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305804', '小姐好辣', '喜剧', '杰西卡（瑞秋·麦克亚当斯 Rachel McAdams 饰）是学校的性感辣妹，这天，她和好友艾宝一起去疯狂购物。杰西卡买了一对耳环，其实这是一对魔法耳环，假如两个人分别戴上一只耳环，他们的身体就会互相交换。当然，杰西卡现在还不知就里。同时，抢劫犯克里夫（罗伯·施奈德 Rob Schneider 饰）正在抢劫离购物中心不远的一座加油站，当他将油站的员工都制服后，购物完的杰西卡和艾宝开着车来加油了。她们误将克里夫当成了油站员工，克里夫为了避免引起麻烦，就装作油站员工帮她们加了油。不料离开时杰西卡刚买的耳环掉了一只在地上，被克里夫捡到了。第二天一早醒来，杰西卡的身体换成了克里夫的了！不知就里的她大摇大摆来到了学校……©豆瓣', '罗伯·施奈德', '汤姆·布拉迪', 6.9, 24511, 'tt0302640', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1267602847.jpg', 1.2, 7.2, 47.8, 32.6, 11.3, '0.583725,0.099877,-0.546728,0.076835,-0.189666,-0.503803,0.657938,0.402224,-0.067599,0.164183,0.216281,0.617584,-0.482327,0.220430,0.309898,0.240747,-0.576663,-0.615468,0.000047,-0.281638,-0.500513,-0.259504,0.001257,-0.272833,0.006490,-0.134371,0.076139,-0.302807,0.055949,0.624356,0.364908,-0.093526,-0.023147,0.545016,-0.333863,0.191882,0.161742,-0.214363,0.195530,0.457348,0.125941,-0.159246,0.123746,0.098765,0.428402,0.212905,0.741456,-0.026112,0.072261,0.013517,0.166285,-0.095103,0.193521,0.088689,0.372475,0.014732,0.195434,-0.184463,-0.339169,0.212716,0.454866,-0.124708,-0.383264,0.287128,-0.278013,-0.002943,-0.527563,0.488235,-0.179885,-0.001047,0.363608,-0.440195,0.430119,0.131621,0.130747,0.241567,0.072333,-0.006557,-0.732224,0.106071,0.423101,-0.004296,0.381315,0.370136,0.007686,-0.236941,-0.094201,0.292419,-0.283845,-0.185575,0.717567,-0.028280,0.001767,-0.275320,-0.782927,-0.254677,-0.321593,-0.267704,0.079459,-0.229673,-0.115901,-0.531063,0.176363,-0.259697,-0.196251,0.236193,0.071203,0.019901,0.438290,-0.517052,0.112381,0.722423,0.299704,-0.232488,0.633285,-0.390754,0.288730,0.070744,-0.057808,-0.193784,0.316114,0.601633,0.504300,0.671041,-0.031563,-0.044398,-0.239329,0.277926', '1316560', '1295324', '1298817', '1303462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305814', '小树的故事', '剧情', '八岁印第安小孩“小树”，在双亲逝世后，被送至田纳西州的史莫基山，与祖父母同住。小树与住在深山中的祖父母展开了一段新生活，他的新生活充满了探索与冒险，有欢笑有泪水，当然有胜利与挫折。同时，小树也认识了不少好朋友，包括神秘的奇拉几族先知——“柳树”约翰。1930年的美国，虽然经济萧条，生活困苦，但是对小树来说，却是最难忘的时光。', '约瑟夫·阿什顿', '理查德·弗雷登伯格', 8.6, 7341, 'tt0119052', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526007439.jpg', 0.3, 0.8, 11.4, 45.5, 42, '0.101395,-0.494327,-0.658480,0.578770,0.015600,-0.348549,0.959414,0.095517,-0.653939,-0.199551,-0.079158,0.710360,0.093566,0.647968,0.067524,-0.316277,-0.223866,-0.517367,0.045282,-0.231073,-0.487761,-0.372134,-0.180327,0.119757,-0.315624,-0.451379,0.801858,0.153288,0.067947,0.705401,-0.196917,0.324096,-0.085219,0.449117,-0.601185,-0.009729,-0.044497,0.358553,-0.775717,-0.023611,0.004258,-0.266562,-0.221274,-0.400948,0.133539,0.122273,0.616887,-0.327681,-0.329264,-0.162924,0.108717,-0.099515,-0.247870,0.120789,0.316540,0.056295,0.071410,0.312166,-0.198127,0.126572,0.026310,-0.395223,-0.700772,0.193247,0.075312,0.097472,-0.956703,0.701292,0.340334,-0.394353,-0.036517,-0.631849,0.298308,0.513784,0.103926,0.355638,-0.386653,0.230746,-0.431320,0.090286,0.962718,-0.000693,-0.231504,0.425705,-0.621993,-0.475121,0.155556,-0.056142,-0.541479,0.173394,0.152708,0.038970,-0.308229,0.524918,-0.779464,0.328067,-0.103905,-0.405235,0.434772,-0.666967,-0.418036,-0.484028,-0.494407,-0.711349,-0.490313,0.041822,0.357975,-0.381461,1.090844,-1.134021,0.422096,0.126065,0.403070,-0.426505,0.726944,0.043114,0.263419,-0.218251,0.056241,0.600913,-0.292135,0.395957,0.167896,0.080065,-0.224575,0.013743,-0.410300,0.516774', '35030151', '1292219', '25721544', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305817', '爱丽丝', '动画', '一日，小女孩爱丽丝（Kristýna Kohoutová 饰）在自己的房间玩耍，一只兔子闯入了她的玻璃橱柜，神色慌张地更衣赶路，爱丽丝跟随这只奇怪的兔子爬进抽屉，很快便从一个大水桶里掉入了另一个世界。然而，这并不是我们从童话里熟知的那个爱丽丝仙境，兔子肚子里竟然填满了木屑，需要吃木屑补充能量，它还有一把专门用来砍头的大剪刀；鱼缸里的鱼骨头会咬人；袜子虫长着假牙钻来钻去……这里的一切与其说是奇幻，不如说是诡怪，甚至有些残酷和肮脏。面对着预料之外的种种威胁，爱丽丝在“仙境”中探索前行，她最终将走到哪里，又将遇到些什么？同时她也在好奇，这个世界和自己的房间，究竟哪个才是现实，哪个才是“仙境”……本片曾获1989年安纳西国际动画电影节故事片奖。©豆瓣', '克里斯蒂娜·科荷多娃', '杨·史云梅耶', 8.5, 9286, 'tt0095715', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2492874983.jpg', 0.5, 1.8, 12.6, 42.3, 42.8, '0.337939,0.255355,-0.628025,0.517566,-0.202672,-0.111896,1.028096,0.166310,-0.240571,-0.174010,0.155500,0.691222,-0.297235,0.247011,-0.327684,0.296820,-0.460024,-0.526622,-0.437515,-0.377724,-0.572874,-0.100505,-0.640661,-0.062457,0.146646,0.130329,0.359289,0.152946,-0.292413,0.156068,0.183680,-0.170132,-0.311216,0.510542,-0.383473,0.158122,0.053266,0.274675,0.308922,-0.039063,0.088384,-0.287730,-0.248181,0.253225,0.037898,0.182355,0.620117,-0.463447,0.018262,0.017093,0.294380,-0.182396,-0.030492,0.161366,0.163636,-0.087314,0.070000,-0.174262,0.005583,0.539812,0.442339,-0.244420,-0.787507,-0.162998,-0.275200,0.291261,-0.598217,0.158004,0.039287,-0.068508,0.158310,-0.246533,0.253723,0.053885,0.139894,0.561317,-0.190054,-0.111721,-0.671156,0.091273,0.219563,-0.189783,-0.054488,0.418169,-0.075168,-0.452522,-0.066411,0.120445,-0.270474,-0.289777,0.533911,0.140779,-0.513880,-0.027789,-0.601403,0.378219,-0.169467,-0.329997,-0.124276,-0.164806,-0.345062,-0.368947,0.094085,-0.296183,-0.230307,-0.155320,0.165371,-0.039916,0.554801,-0.319816,0.239899,0.668332,0.171796,-0.073036,0.546415,-0.364282,-0.062885,0.001113,0.095082,0.178188,0.085209,0.463351,0.149763,0.785149,-0.030852,0.022630,-0.755148,0.439851', '1578663', '21619567', '1302133', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305829', '天与地', '剧情', '得一笔奖学金资助，张一鹏（刘德华）获得去法国留学深造的机会，学成归国后，他被任命为上海市禁烟（鸦片）行动的第一专员。张在法经西方文化与价值观熏陶，十分书生意气，刚携妻子（陈少霞）来到上海，便展开一系列动作，不知中国与西方国家国情有别，难有健全的法律体系及社会秩序：警察署长倪坤（顾宝明）和大毒枭戴济民（刘松仁）是拜把兄弟，两人一起控制着包括贩卖鸦片在内的上海所有的非法交易，见数次向张行贿无果，他们发毒誓要让张生不如死。©豆瓣', '刘德华', '黎大炜', 7.2, 6818, 'tt0111423', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2869995621.jpg', 1, 4.7, 41.9, 36.8, 15.6, '-0.079350,-0.061024,-0.677780,0.763410,0.129766,-0.388386,0.290451,0.106906,-0.461455,-0.128153,-0.181999,0.687230,-0.049415,0.237632,0.398123,-0.263956,-0.237651,-0.868764,-0.444716,-0.173037,-0.119055,-0.630269,-0.082013,0.068221,-0.473963,-0.102453,0.538213,-0.038916,-0.361148,0.381299,0.246485,0.151979,-0.258007,0.083444,-0.286828,-0.152841,-0.011971,-0.160239,-0.593809,-0.102065,0.300305,-0.439105,-0.403394,0.017546,0.178258,0.149066,0.523191,-0.085463,0.004489,-0.597286,0.420356,-0.205042,-0.197566,0.299856,0.160435,0.232540,0.314547,0.406124,-0.203496,0.111888,0.121309,-0.290083,-0.372258,-0.131988,0.116888,0.081126,-0.628669,0.164905,-0.231763,0.094638,-0.266957,-0.544212,-0.019506,0.573343,0.184098,0.554974,0.047420,0.183643,-0.439027,0.313287,0.681302,-0.096735,-0.073993,-0.266474,-0.070061,-0.657595,0.069511,-0.247218,-0.212381,-0.123648,0.288936,-0.048573,-0.063732,0.101933,-0.621721,-0.059495,-0.232632,-0.323791,0.172466,0.117026,0.226523,-0.909145,-0.177473,-0.432273,0.001397,0.414574,0.461679,-0.063637,0.581888,-0.661066,-0.035926,0.296967,0.469677,-0.932158,0.473202,0.138601,0.124373,-0.115194,-0.097245,-0.083944,0.354830,0.386861,0.079536,0.254898,0.095827,-0.164824,0.186704,0.143822', '1307762', '4301278', '3230195', '27608279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305837', '新碧血剑', '动作', '明朝末年奸臣当道，朝廷的忠义大将因受陷害被抄家，仅年幼的儿子袁承志（元彪  饰）逃出。十六年后，袁承志长大成人，无意中得到一份武功秘籍和藏宝图，开始了寻宝之路。期间，袁承志目睹明朝官匪勾结，百姓流离失所，又受父亲的影响，一直想寻求强国之路。旅途中，袁承志遇到志同道合的富商多尔衮，一路结伴同行。期间遭遇绑匪，被卷入江湖帮派与五毒教的恩怨之中。最终袁承志靠坦荡胸襟和高超的武艺化解了恩怨。为了削弱满清对明朝的威胁，袁承志决定刺杀皇太极，却发现多尔衮竟然是满清亲王。最后，根据藏宝图的记载，袁承志终于找到宝藏并献给了闯王，寄望闯王能重整明朝河山。可是，明朝皇帝胸无大志，袁承志又备受闯王手下排挤，满清势力日渐壮大。袁承志深感壮志难酬，心灰意冷之下，只得远走海外。©豆瓣', '元彪', '张海靖', 6.9, 17614, 'tt0108613', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508768538.jpg', 0.8, 5.1, 51.2, 32, 10.8, '-0.030053,0.065840,-0.466289,0.633343,0.394234,-0.236864,0.297865,0.047409,-0.844689,-0.300450,0.248347,0.429119,0.130146,0.031700,0.021102,-0.220115,-0.189518,-0.789728,0.024140,-0.162444,0.173763,-0.376236,-0.326480,-0.108961,-0.616164,-0.238711,0.827029,0.495836,-0.261647,0.408961,0.206871,0.184941,-0.291690,0.652760,-0.220368,0.244873,-0.079674,-0.098363,-0.495949,0.001365,0.030234,-0.634921,-0.245289,0.141231,-0.200923,0.141262,0.315631,-0.335798,0.208356,-0.336466,0.322502,-0.055169,-0.240466,0.156105,0.507304,0.241295,0.292417,0.632680,0.078165,-0.220974,-0.048722,0.117132,-0.361750,-0.332793,0.433285,-0.144028,-0.422459,0.284926,-0.011408,-0.047281,-0.105413,-0.317624,0.252075,0.434307,0.459085,0.066850,-0.157262,-0.047749,-0.544029,0.098243,0.486204,-0.476727,0.307100,-0.266513,0.166019,-0.338690,0.577001,-0.661957,0.038987,0.205197,0.391957,-0.127663,-0.033891,0.551227,-0.304912,-0.056972,-0.492200,0.231047,0.191759,-0.223561,0.182329,-0.249283,-0.388143,-0.272902,-0.257515,-0.046881,0.412209,-0.277055,0.531144,-0.463147,-0.176764,0.366031,0.231127,-0.780285,0.440761,0.138056,0.225576,0.137619,-0.177663,0.210112,0.081675,0.286782,-0.029849,-0.306533,-0.168533,-0.419845,-0.071518,0.195064', '10540066', '3264045', '1297223', '1296272');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305843', '目露凶光', '惊悚', '1967年，山景酒店发生灭门惨案，欧炳同因怀疑妻子有外遇，将其杀死后又与三岁儿子吞老鼠药自杀，三人的死状极其恐怖，房间的墙壁上写有“愿此刻永留”五个血字，留声机里正在重复播放“愿此刻永留”一曲。1999年，印刷业电脑专家马文信（刘青云）下班后被神秘匪徒绑架，但家人及其女友傅骞人（郭蔼明）均没收到任何勒索电话。两天后警察阿 Pit（梁家辉）在马文信座驾中发现神秘血渍，跟踪发现马文信被倒吊在山景酒店发生灭门惨案的那间房里，且浑身布满伤痕。自此，马文信像被欧炳同的鬼魂附体一般，不光终日对傅骞人疑神疑鬼，还时常对其目露凶光。©豆瓣', '刘青云', '林岭东', 7.2, 11295, 'tt0224345', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2624849842.jpg', 0.6, 4.1, 41.5, 43.9, 9.8, '0.078656,-0.080864,-0.568293,0.083418,0.147309,0.075659,0.779394,0.085196,-0.596469,-0.412527,0.193791,0.443727,-0.512128,0.294172,0.228454,-0.301485,0.012484,-0.592787,-0.112217,-0.234295,-0.334514,-0.192736,0.055579,-0.174616,0.099657,-0.273321,0.081802,0.102617,0.055882,0.450132,0.072608,0.178412,-0.452253,0.327476,0.033742,0.289038,-0.165464,0.076130,0.111984,-0.002031,-0.032790,-0.265735,0.077332,-0.106588,-0.157148,0.228014,0.665128,-0.116371,-0.327481,-0.185333,0.270880,-0.115237,-0.176802,0.320832,0.572598,0.187504,0.279811,0.401308,-0.322385,-0.211427,0.236213,0.187280,-0.147802,-0.211564,0.054946,0.220126,-0.198916,0.433222,-0.153321,0.228853,-0.159055,-0.207805,0.380522,-0.005708,0.099046,0.581265,0.235497,0.030310,-0.551122,0.035143,0.262339,-0.105511,0.154913,0.112902,0.140961,-0.107484,0.130909,-0.203534,-0.175705,0.220041,0.256652,0.187506,-0.340853,0.046314,-0.240293,-0.228752,-0.259787,0.049491,-0.136665,-0.223788,-0.410421,-0.551582,-0.208153,0.031436,-0.002763,0.296732,-0.131551,-0.097651,0.075929,-0.398660,0.457084,0.085020,0.197985,-0.245823,0.446208,-0.098990,-0.102341,0.173085,-0.114538,0.230307,0.491695,0.349416,0.120823,0.042817,-0.388582,-0.077476,-0.236536,0.060780', '10466639', '20451118', '21348112', '10608242');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305858', '无声言证', '悬疑', '天生不能说话的比莉（玛丽娜·奇蒂娜 Marina Zudina 饰）是一名道具师，她的工作是为小成本恐怖片提供道具，虽然身体上有缺憾，但有一个关心她的姐姐让她的生活充满了温暖。一天收工后，她为了取回落在拍摄现场的道具而折返，却被锁在了片场。无聊的她四处转悠，无意之间闯进了一部色情片的拍摄现场，令他没有想到的是，在转瞬间，色情变恐怖，女演员活生生的杀死了，而凶手手中的镜头，如实的拍下了这血腥的一幕。比莉报了警，警察前来搜索却一无所获，凶手坚称吓坏了的比莉将假戏看成了真做。事情并没有结束，原来，凶手系俄罗斯黑手党成员，专门拍摄这种真实的暴力电影来满足顾客的特殊需要。事件平息后，他们立刻展开了针对比莉的灭口行动。无法开口的比莉，只有通过自己的智慧和行动来揭开这场事件的真相。©豆瓣', '玛丽娜·奇蒂娜 Marina Zudina', '安东尼·威勒', 8, 28407, 'tt0110604', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2157014008.jpg', 0.5, 2, 20.5, 48.8, 28.2, '0.427087,0.123200,-0.674797,0.518561,-0.150210,-0.054676,0.989765,-0.087240,-0.329677,-0.326039,0.278772,0.678886,-0.318448,-0.084657,0.003155,0.058697,-0.425611,-0.612504,-0.217224,-0.193327,-0.406233,-0.310914,-0.252022,-0.323045,-0.047660,-0.255104,0.513041,0.064805,-0.452273,0.301018,0.517132,0.152445,0.084202,0.564851,-0.127507,0.066302,0.009231,-0.083043,-0.047714,0.419486,0.200460,-0.325622,-0.167669,0.449561,-0.087121,0.577191,0.774278,-0.190220,-0.265092,0.130860,0.422103,-0.416362,-0.050362,0.070053,0.243898,0.108437,0.137561,0.002528,-0.289696,-0.055494,0.062507,0.054538,-1.052128,0.060960,0.123323,0.184968,-0.440945,0.331107,-0.237681,0.050970,0.102894,-0.260201,0.259186,0.396706,0.369276,0.199825,0.140684,-0.069561,-0.477288,0.268306,0.660732,-0.162388,-0.229858,0.660662,-0.265621,-0.487810,-0.075341,-0.333453,-0.186046,0.089217,0.468479,0.091048,-0.245561,-0.001065,-0.538594,-0.127174,-0.263949,-0.307098,-0.199666,-0.459833,-0.201941,-0.582463,-0.135727,-0.214279,-0.371698,0.007197,0.038479,-0.512579,0.613059,-0.796061,0.124239,0.771863,0.114506,-0.533832,0.605976,0.070225,-0.050768,-0.088902,-0.234019,-0.099362,0.135807,0.683507,0.426810,0.406797,0.117003,-0.296583,-0.497795,0.327842', '3005387', '25928048', '4820775', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305902', '谁说我不在乎', '剧情', '谢雨婷（吕丽萍 饰）这天为了领取居委会模范夫妻的奖品，在家翻箱倒柜地寻找结婚证却没找到，被同事取笑说自己是非法同居。倔气上来的雨婷倒不罢休了，在家掀开战场，让老公顾明（冯巩 饰）和自己一起找，把老顾也折腾得够呛。女儿小文（李小萌 饰）是个懂事聪明的孩子，为了让父母休战， 和同学们凑钱去造了个假证，谁知掀起更大的风波，因为结婚证早已改头换面了。 害怕一回家就被老婆折腾的顾明是精神病院的医生，最近温柔体贴的助手小安对自己关心照顾，让顾明动了心。精神病院的病人逃了出来，跑到了顾明家，谢雨婷在中间好心办了坏事，两口子吵得更凶了。再也忍受不了的小文离家出走，顾明两夫妇才明白这段时间对小文的疏忽以及因为一张结婚证而引发的闹剧伤害了孩子。雨下得越来越大，小文到底去了哪儿呢？©豆瓣', '冯巩', '黄建新', 7.1, 19082, 'tt0308559', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2194256089.jpg', 0.6, 3.9, 46.5, 38.7, 10.3, '0.278042,-0.350449,-0.644517,0.172279,-0.335817,-0.579033,0.473359,0.112666,-0.317651,-0.083992,-0.078942,0.421595,-0.215690,0.330643,-0.042203,0.166928,-0.183661,-0.365943,-0.071420,-0.031694,-0.294601,-0.344774,0.070024,-0.028685,0.010363,0.096843,-0.006035,-0.148428,0.003665,0.273069,0.559324,-0.220963,0.129329,0.349572,-0.026095,0.299553,-0.240447,0.379911,0.121116,0.120814,0.368719,0.003617,-0.078115,0.201941,0.298709,0.239677,0.387055,0.086048,-0.113967,-0.122960,0.505658,-0.330304,-0.032690,0.178417,0.355946,-0.137761,0.323917,-0.119632,-0.390836,0.038355,0.284310,0.232503,-0.391618,0.431595,0.133482,-0.182538,-0.860650,0.452226,-0.110581,-0.185437,0.063045,-0.253654,0.519503,0.687317,-0.092036,0.693471,-0.210617,0.101729,-0.514849,0.234510,0.443340,-0.197709,0.308781,0.257074,-0.166123,-0.122401,0.305502,-0.447500,-0.444168,-0.010284,0.366371,-0.174410,-0.409744,-0.177640,-0.267491,-0.102166,-0.111777,-0.135714,-0.164834,-0.574975,-0.016345,-0.116162,-0.082058,-0.184318,-0.370893,0.146658,0.014052,-0.211110,0.577129,-0.394135,-0.013245,0.605334,0.341341,-0.851249,0.534204,0.299732,0.086314,-0.012369,0.339355,-0.316405,0.050448,0.511155,0.604904,0.393740,0.093853,-0.287626,-0.173846,0.159430', '1421278', '1305175', '1877596', '1303485');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305903', '心慌方', '科幻', '警司昆廷（莫里斯•迪恩•温特Maurice Dean Wint 饰）、监狱专家兼传感器专家伦尼斯（维尼•罗宾逊 Wayne Robson 饰）、医生霍洛韦（尼基•瓜达尼 Nicky Guadagni  饰）、建筑师沃思（戴维•休利特 David Hewlett）、数学系的大学生利文（尼科勒•德搏尔 Nicole de Boer  饰）和身患孤独症的学者卡赞（安德鲁•米勒 Andrew Miller 饰），六个素不相识的人，一觉醒来后发现一同身处于由一个个形状相同的立方体组成的结构复杂的高度精密迷宫中！他们唯一的出路只有逃离这座迷宫，然而，一个个立方体尽管外貌相同，然而里面的机关却各不一样，复杂异常。依靠利文数学知识的推理，他们终于以为发现迷宫的运行规律，凭此一次次解开各个机关，迷宫的边缘近在眼前。当他们正欲合力逃出迷宫之际，意外发生了。©豆瓣', '妮可·德波儿', '文森佐·纳塔利', 7.9, 208998, 'tt0123755', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554538282.jpg', 0.5, 2.3, 22.8, 49.3, 25.1, '0.426560,-0.209012,-0.561043,0.309722,0.081159,-0.178435,0.768078,0.006229,-0.646821,-0.306493,0.268709,0.536585,-0.246152,-0.180819,-0.002367,0.031560,-0.577278,-0.359544,-0.048776,-0.293687,-0.435702,-0.640000,-0.441551,-0.228612,0.105503,-0.408973,0.490717,-0.088159,0.115189,0.162509,-0.198767,0.335364,-0.398591,-0.120753,0.193782,0.010282,0.365965,-0.319462,-0.204506,-0.051505,-0.346868,0.352294,-0.195631,0.095074,-0.140180,0.568643,0.375185,-0.449692,0.341730,0.094366,0.190736,0.082826,-0.203384,0.105751,0.099985,-0.000516,-0.022428,-0.044254,-0.073337,0.116756,0.246780,-0.149784,-0.401017,-0.055203,0.262192,0.434895,-0.082473,-0.059176,-0.031075,-0.169460,-0.069335,-0.347530,-0.127547,0.066455,0.367441,0.305208,-0.095600,-0.151550,-0.506077,-0.284964,0.240323,0.019118,-0.682885,0.025048,-0.315425,-0.406836,-0.194210,-0.024520,-0.218831,-0.138651,0.320828,0.192554,-0.092162,0.044551,-0.512886,0.114733,-0.434538,0.144784,-0.445486,-0.066329,-0.055681,-0.853728,0.082400,-0.178925,-0.076522,-0.033905,-0.297263,-0.100974,0.369616,-0.480944,0.140413,0.178451,0.110009,0.129946,0.614268,-0.221222,0.161491,-0.370743,-0.126838,0.187076,0.153513,0.346450,-0.094618,0.543374,0.125677,-0.372314,-0.348307,0.302318', '1297659', 