INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305915', '开心鬼放暑假', '喜剧', '开心鬼（黄百鸣）转世投胎，摇身变作某女子中学教师，在他班上，几名爱捉弄人的调皮女生，戴卓仪（袁洁莹）、MAY（罗美薇）和姚琼（陈家玲），成立了以整人为乐的“卑鄙会”，开心鬼是她们最爱拿来开玩笑的对象。开心鬼喜欢上隔壁男校某名女教师，正欲展开攻势，发现该教师正被各方面条件都强于自己的某体育教师追求，相比形秽，开心鬼郁郁不得意，更受打击的是，他因掉入戴卓仪一众设的“陷阱”，遭校长误会被迫离开学校。戴卓仪一众后悔不迭，开始想办法弥补过错。©豆瓣', '黄百鸣', '高志森', 7.4, 27106, 'tt0089395', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1995005703.jpg', 0.4, 2.9, 38.8, 41.4, 16.5, '0.484754,-0.242914,-0.413387,0.092264,-0.390439,0.027587,0.467349,0.001504,-0.186134,-0.223704,0.190441,0.270868,-0.072685,0.374332,-0.152860,-0.003884,0.122638,-0.359307,-0.022033,-0.225778,0.090559,-0.169461,0.100850,-0.169896,-0.173431,-0.317294,0.056768,-0.096224,-0.062471,0.244941,0.762186,0.543928,-0.120648,0.144944,0.009761,0.111251,-0.146849,-0.181051,-0.020458,-0.111224,-0.236820,0.057043,-0.125927,0.040207,0.058803,0.072664,0.496192,0.143928,-0.432826,-0.375156,0.326505,-0.402304,-0.156826,0.471991,0.414012,-0.141189,0.222068,-0.189713,0.051318,0.090450,0.098712,-0.118799,-0.455545,0.074370,0.139326,0.052589,-0.251585,0.254969,0.153232,0.044338,0.197119,-0.076916,-0.061819,0.031229,0.244553,0.322046,0.140921,0.198454,-0.210762,0.273361,0.894556,0.044034,-0.040279,0.176359,-0.034069,-0.100337,0.300178,-0.377647,-0.328382,0.038610,0.119013,-0.227246,-0.017811,-0.027200,-0.130695,-0.079455,0.207433,0.473595,-0.138358,-0.280331,-0.056694,-0.178217,0.046411,0.004111,-0.103469,-0.005364,-0.190203,-0.437243,0.709495,-0.895433,0.232733,0.514445,0.520071,-0.915554,0.576206,0.303193,-0.056611,-0.292402,-0.284864,0.246433,0.027252,-0.033941,-0.152362,0.094023,0.026493,-0.332120,-0.274743,0.002577', '1877596', '1297710', '1293265', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305926', '炮制女朋友', '喜剧', '归国在上海发展的富商张天找到失散多年的女儿张宁（赵薇）后，因看不惯她的举止行为，请来失业很久的香港设计师阿祖（郑伊健）替她改头换面，以期她能女承父业。张宁与阿祖初接触时，别扭矛盾没少闹，但张宁终被炮制成其父心中的女性形象，两人在这一过程中，也慢慢互相倾心。张天的宴会上，张宁大方得体的表现吸引了某外交官的儿子的目光，后者对其展开追求。不等张宁做出选择，自卑的阿祖辞职返回香港。张宁随后也来到香港，试图劝阿祖振作。©豆瓣', '郑伊健', '叶伟民', 4.6, 21476, 'tt0369750', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486742575.jpg', 16.3, 43.1, 35.9, 3.4, 1.3, '0.388713,-0.004794,-0.723139,0.416470,-0.074477,-0.576085,0.455860,0.238376,-0.604244,-0.101514,0.228898,0.664762,-0.375186,0.312710,0.261893,0.082010,-0.401729,-0.547650,0.077612,0.020553,0.116685,-0.190334,-0.043249,-0.139561,-0.436722,-0.034820,0.412140,-0.141150,-0.189808,0.586500,0.258515,0.128198,0.118566,0.492099,-0.042389,0.156057,-0.034195,0.005366,-0.313410,0.243966,0.211674,-0.301521,-0.226129,0.136286,0.075409,0.475823,0.708265,0.203105,-0.056238,-0.121190,0.469979,-0.156663,0.060502,0.270744,0.207709,0.125936,0.206768,0.031568,-0.214964,-0.149587,0.049692,0.091691,-0.433263,0.086099,0.140078,0.001022,-0.508863,0.343566,-0.088973,-0.173584,0.030664,-0.429463,0.132084,0.465635,0.267244,0.082928,-0.068729,0.435913,-0.027870,0.233741,0.622777,0.224670,-0.227085,0.233459,-0.147871,-0.467548,0.139726,-0.256759,-0.449999,-0.200510,0.480844,0.150882,0.042360,0.124153,-0.396860,-0.209659,-0.072136,0.059892,0.175019,-0.204548,-0.027747,-0.521284,-0.356586,-0.650540,-0.302423,-0.283645,0.036482,-0.174928,0.633816,-0.678276,-0.089377,0.196088,0.404083,-0.627655,0.567422,0.173698,0.133539,-0.242067,-0.067229,0.116232,-0.208080,0.221578,0.074092,0.277904,-0.036147,-0.185458,-0.203907,0.204582', '1301022', '1292219', '3445516', '1306465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305934', '新婚告急', '喜剧', '莎拉（布莱特妮•墨菲 Brittany Murphy 饰）出身豪门，天生叛逆的她从来不想接受父母的安排：家人安排的高薪厚职她不屑一顾，反而当起了一名作家；对于他们安排的富有的“未来女婿”，她更是深恶痛绝。这天，莎拉偶遇了出身平凡的交通报道员汤姆（艾什顿•库彻 Ashton Kutcher 饰），两人很快堕入了爱河。然而莎拉的父母坚决反对，原因很简单，汤姆出身平民，平平无奇，这和他们心目中的乘龙快婿相去甚远，他们可不想这个平凡的男人成为家里的一份子。于是，在萨拉和汤姆婚后度蜜月时，一场旨在拆散这对小夫妻的闹剧上演了。加上两人出身的文化差异，萨拉和汤姆能否在新婚告急时共渡难关？©豆瓣', '阿什顿·库彻', '肖恩·利维', 6.3, 8652, 'tt0305711', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1376949810.jpg', 2.2, 12.5, 58.5, 21.4, 5.5, '0.570898,-0.129315,-0.619110,0.586252,-0.281454,-0.382406,0.722544,0.320670,-0.571588,-0.439670,0.057381,0.890542,-0.177179,0.140460,0.328124,0.076175,-0.578331,-0.538979,-0.026216,-0.118609,0.075337,-0.467703,-0.076850,-0.254138,-0.210446,-0.081869,0.388481,-0.230156,-0.131855,0.523459,0.445684,0.473919,0.026423,0.293376,-0.153532,0.164308,0.128366,0.228408,-0.413520,0.189245,-0.031579,0.229618,-0.183869,0.031572,0.211949,0.324921,0.481292,-0.309795,-0.179285,-0.104397,0.425540,-0.308065,-0.194446,0.347714,0.259214,-0.139720,0.227867,0.135947,-0.170467,-0.149426,0.044307,-0.085323,-0.742969,0.058283,0.118347,0.034912,-0.471339,0.669576,0.010950,-0.278892,-0.005000,-0.244412,0.057872,0.537769,0.165847,0.278987,0.011978,0.061695,-0.429018,0.248214,0.790548,0.387881,-0.270022,0.290223,-0.389073,-0.318567,0.202264,-0.263205,-0.805619,0.004897,0.389236,0.024702,-0.144355,0.357581,-0.326710,-0.225253,-0.268864,-0.049288,0.012179,-0.660971,-0.097781,-0.533112,-0.126627,-0.784665,-0.518618,-0.323413,0.162150,-0.149355,0.723179,-0.986925,0.070461,0.171780,0.242296,-0.593441,0.645031,0.379040,0.339974,-0.284755,-0.211016,0.095522,0.097601,0.018263,0.040347,0.229098,0.026961,-0.275777,-0.173698,0.382658', '1292219', '25721544', '1309161', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305952', '死囚之舞', '剧情', '影片讲述在种族偏见根深蒂固的美国南方小镇，白人男主人公汉克（比利·鲍勃·汤顿 饰）与黑人妇女莱茜娅（哈莉·贝瑞饰）一段纠缠在死亡与种族歧视下的爱情故事。汉克生长在极端种族主义的保守白人家庭，深受父亲影响。在父亲退休后，汉克接手负责执行死刑。在刚刚处死了一个黑人死囚后，汉克意想不到的邂逅了他的妻子莱茜娅。很快，两人坠入情网。可在种族观念保守僵化的环境下，这不可思议的命运交集，会像舞蹈般缠绵动人还是举步维艰呢？本片女主角哈莉·贝瑞荣获第74届奥斯卡金像奖(2002)最佳女主角。©豆瓣', '比利·鲍伯·松顿', '马克·福斯特', 7.4, 6961, 'tt0285742', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p901229106.jpg', 0.6, 2.4, 35.6, 47.5, 13.9, '0.080637,-0.032613,-0.546741,0.418632,-0.008713,0.025851,0.919120,0.292590,-0.437610,-0.074798,0.420495,0.806284,-0.189381,0.146018,0.485085,-0.158673,-0.588476,-0.540845,-0.201387,-0.181511,-0.316977,-0.492450,-0.068609,-0.257356,0.000934,-0.474818,0.762563,-0.194634,-0.320977,0.354048,0.456849,0.324198,-0.240606,0.086792,-0.242562,0.105403,0.400938,-0.023530,-0.549939,0.231530,0.055251,-0.115113,-0.013144,-0.111162,-0.279307,0.264658,0.668156,-0.171907,-0.261439,-0.180318,0.647870,0.004433,-0.302272,0.025797,0.489369,-0.355310,0.224698,0.304720,0.230276,-0.006451,0.026985,-0.076014,-0.469077,0.121538,0.041460,0.446082,-0.554810,0.551903,0.218244,0.109794,0.032590,-0.197506,-0.078729,0.317336,0.542483,0.429323,0.057750,0.116317,-0.175552,0.396698,0.582145,0.241650,-0.661104,0.278408,-0.579429,-0.522343,-0.164807,-0.172621,-0.662003,-0.109092,0.413232,-0.162678,-0.333897,0.438308,-0.427463,-0.068684,0.029100,0.066308,-0.091579,-0.438427,-0.180169,-0.659341,-0.177940,-0.434777,-0.243387,0.044417,0.079991,-0.058499,0.711109,-0.551273,0.350375,0.605626,0.235358,-0.438475,0.413553,0.220568,0.225928,-0.383783,-0.088954,0.601779,-0.015425,0.056851,-0.022581,0.399888,-0.261579,0.152185,-0.406769,0.293554', '1467779', '1296992', '35161768', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305964', '天地无限', '剧情', '故事发生在1882年的美国西部平原，在那片广阔的土地上，生活着名为“拓荒者”的人们，他们自由的选择土地，辛勤劳作，放牧牛羊，安居乐业，查理（凯文·科斯特纳 Kevin Costner 饰）、苏（安妮特·贝宁 Annette Bening 饰）、莫斯（亚布拉哈姆·本鲁比 Abraham Benrubi 饰）和斯皮尔曼（罗伯特·杜瓦尔 Robert Duvall 饰）正是其中的成员。可是，随着时间的推移，居民的增多，广袤的平原不再是能够自由驰骋的疆土，只是单纯善良的四人还没有注意到局势的变化。一次意外中，西部小镇的恶霸巴克斯特（金·寇兹 Kim Coates 饰）联手警长恶整了前来购买物资的莫斯并禁止“拓荒者”们再接近小镇，直到这时，查理一行人才意识到，是时候拿起武器为他们的尊严和自由而战了。©豆瓣', '罗伯特·杜瓦尔', '凯文·科斯特纳', 7.9, 5448, 'tt0316356', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p828432530.jpg', 0.3, 1.7, 23.9, 50, 24.1, '0.112107,0.091803,-0.809402,0.583985,0.067265,-0.140874,0.577505,0.042901,-0.507231,-0.122892,-0.035195,0.544667,0.107234,0.036771,0.500954,0.099293,-0.542966,-0.603643,0.041758,-0.247677,-0.304807,-0.607522,-0.414571,-0.530512,-0.258038,-0.520458,0.549992,0.266272,-0.144540,0.638305,0.007613,0.085632,-0.055168,0.495918,-0.159233,-0.088311,0.291764,-0.164493,-0.356991,0.081318,-0.383213,-0.061052,-0.394223,0.143441,0.425053,0.304485,0.813911,-0.452038,0.176649,-0.066175,0.242410,-0.139576,0.350914,-0.135766,0.323072,-0.386608,0.150843,0.230655,-0.106432,0.290563,0.126945,-0.334875,-0.437679,0.009380,-0.092103,0.377166,-0.644774,0.628458,-0.123851,-0.363133,-0.002784,-0.413530,0.264587,0.534567,0.187195,0.320352,0.032044,-0.201950,-0.519240,-0.014283,0.592725,0.078870,-0.309589,0.199802,-0.447867,-0.651270,-0.263901,-0.229802,-0.308974,-0.448826,0.320972,0.062245,-0.011525,0.434559,-0.820359,0.125468,-0.146051,-0.735704,0.208687,-0.053743,-0.286726,-0.590638,0.058727,-0.573226,-0.117129,0.262876,-0.029392,-0.094409,0.650666,-0.726141,0.211485,0.588130,0.414887,-0.264657,0.634072,-0.006408,0.226169,0.011640,-0.282389,0.396143,0.244698,0.441677,0.206869,0.032056,-0.113943,-0.291832,-0.143812,0.617566', '2159244', '3993588', '5361544', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305970', '星际旅行6：未来之城', '动作', '星际联邦的大敌克林贡帝国因为连年争战，经济及生态环境破坏殆尽，一位克林贡领袖遂在企业号太空船护送下前往地球谈和，中途却遭到阴谋份子暗杀，并且嫁祸企业号……', '威廉·夏特纳', '尼古拉斯·迈耶', 7.7, 7389, 'tt0102975', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209381781.jpg', 0.5, 2.3, 27.7, 49.4, 20.2, '-0.231010,0.773392,-0.906192,0.784309,0.668947,0.168388,0.164928,0.295464,-0.065529,-0.233437,0.238667,0.498664,0.578959,0.006333,0.583010,-0.304790,-0.351632,-0.370666,-0.010488,-0.088602,-0.457699,-0.283211,-0.318935,-0.209766,-0.285175,-0.527574,1.102981,0.169566,-0.772471,0.129558,-0.229316,0.575737,-0.253799,0.727174,-0.093221,-0.385891,0.670624,-0.094101,-0.517308,0.279171,-0.713805,-0.348700,0.235475,-0.312521,-0.075933,0.226446,0.439974,-0.261518,0.104230,-0.889547,0.309378,-0.419922,0.171344,-0.375093,1.187206,-0.102735,-0.116415,0.803232,-0.250182,-0.128465,0.413189,-0.110913,-0.856363,-0.045803,0.431659,-0.212677,-0.603116,0.466177,-0.316131,0.286657,-0.514484,0.066452,0.313267,1.439370,0.558605,0.129626,0.031371,0.619925,-0.505189,0.033089,1.069385,0.009986,-0.285945,-0.533639,0.412583,-0.302683,0.012539,-0.681693,-0.201762,-0.308180,0.232717,-0.584438,0.281301,0.886891,-1.021430,0.047154,-0.554179,-0.649491,0.568324,-0.345502,0.245729,-1.025127,0.127950,0.043663,0.049188,0.755389,0.528385,0.215328,0.677543,-0.534448,-0.114163,0.703932,0.578673,-1.386534,0.463257,0.226818,0.351364,-0.302736,-0.183188,0.145331,0.506807,0.648893,-0.233468,-0.183361,0.081429,-0.177524,0.214275,-0.236404', '1291824', '1293830', '25980500', '3074408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305978', '边城', '剧情', '本片根据沈从文同名小说改编。故事发生在民国初年，在湘西边境的一个小山城里，有一个老船夫（冯汉元 饰），守着一条渡船，帮来往的人渡河。他与外孙女翠翠（戴呐 饰）相依为命，17年前，翠翠的母亲与一名屯戍军士未婚生子，后来二人双双殉情。老船夫不想翠翠重蹈覆辙，一心希望把翠翠托付给一个可靠的人。茶峒城里的船总顺顺有两个儿子——大佬天保（刘魁 饰）和二佬傩送（石磊 饰）。他们同时爱上了翠翠，而翠翠爱的是二佬，三年前的端午节夜晚，翠翠偶然邂逅了二佬，感情的种子就在那时悄悄埋下。后来，兄弟俩决定用唱情歌的方式，让翠翠选择。但是因为各种原因，歌声再没有传来了。随后却传来了大佬被水淹死的噩耗。二佬虽仍爱着翠翠，但因为哥哥的死，赌气出走。在一个风雨交加的夜晚，老船夫抑郁而死。翠翠终于明白了许多事情，于是，她守着渡船，等待二佬回来……本片荣获加拿大第9届蒙特利尔国际电影节评委会荣誉奖。', '冯汉元', '凌子风', 8.2, 19406, 'tt0086878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2255490686.jpg', 0.2, 1.3, 18, 51.8, 28.7, '0.113205,-0.181510,-0.638332,0.515636,0.104820,-0.408312,0.691933,0.232383,-0.512070,-0.055475,0.168705,0.783531,0.107738,0.073970,0.136945,-0.072971,-0.267776,-0.470757,0.038108,-0.073422,-0.083564,-0.253821,0.127165,0.048895,-0.049445,-0.119101,0.386898,-0.043755,-0.055324,0.620433,0.181928,0.074030,-0.227854,0.225076,-0.282942,0.317472,0.134330,0.016680,-0.281258,0.198636,0.034939,-0.001604,-0.223253,-0.314108,-0.009594,0.214534,0.582722,-0.266480,-0.106679,0.065444,0.117880,-0.156214,-0.073206,-0.130064,0.294412,-0.117038,0.328812,0.245585,-0.274144,-0.031993,0.112253,0.140652,-0.264898,0.329757,0.153130,0.275384,-0.691953,0.421260,-0.018040,0.039621,-0.002010,-0.478315,0.353888,0.331535,0.003025,0.311859,-0.299232,0.082713,-0.605771,0.397399,0.759221,-0.017132,0.099448,0.177182,0.106688,-0.070935,0.189470,-0.131378,-0.508849,0.156418,0.346365,-0.221258,-0.436939,0.025464,-0.452842,0.055737,-0.164235,-0.133580,0.131992,-0.134494,-0.280935,-0.177953,-0.000998,-0.124011,-0.112912,0.092868,0.202705,0.030070,0.700784,-0.488290,0.404726,0.522568,0.216809,-0.344969,0.572602,0.427881,0.147864,-0.202632,0.029161,-0.098563,-0.249473,0.315192,0.272291,0.250185,-0.212846,-0.321017,-0.379032,0.016890', '1306505', '25721544', '1297606', '1291565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1305986', '远离天堂', '剧情', '1957年的秋天，凯茜（朱丽安•摩尔 饰）与丈夫弗兰克（丹尼斯 •奎德 饰）生活在美国康涅狄格州的一个小镇上，他们的生活舒适平静，有两个不到十岁的孩子。他们一家吸引了很多人的羡慕。令凯茜意想不到的是，她发现了自己的丈夫竟然与一名男人发生了关系，她感觉自己的世界将要沦陷了。她与教养甚好的黑人园丁雷蒙德（丹尼斯•海斯伯特 饰）交谈，雷蒙德的安慰让凯茜感觉到了鼓舞。但很快因为种族问题，众人开始用异样的眼光对待凯茜。凯西与丈夫害怕流言蜚语，因此他们一直勉强维持着双方的关系，但各自心中都各有爱人……©豆瓣', '朱丽安·摩尔', '托德·海因斯', 7.6, 8410, 'tt0297884', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1501322241.jpg', 0.3, 2.1, 29.3, 53.2, 15.1, '0.405824,-0.133383,-0.773225,0.570789,-0.134399,-0.237615,1.050935,0.284051,-0.778867,-0.283895,0.231146,0.869933,-0.319439,0.357407,0.192462,0.140527,-0.282938,-0.880025,0.076915,-0.167663,-0.312664,-0.356534,-0.365635,-0.469099,-0.315073,-0.338497,0.346549,-0.057113,0.008771,0.542269,0.143556,0.179637,0.153499,0.735586,-0.153006,0.069962,0.115777,0.033351,-0.128430,-0.064158,-0.026016,0.051809,-0.321204,0.310112,0.061127,0.580752,0.727149,-0.075319,-0.313811,0.076700,0.118397,-0.008405,0.091598,0.266415,0.234569,-0.221710,0.117919,0.037315,-0.163419,-0.184518,0.063110,0.206672,-0.604790,0.240693,-0.050918,0.274546,-0.516771,0.597429,0.003981,-0.227479,-0.065844,-0.343631,0.352053,0.383155,0.143535,0.475263,-0.299398,-0.060162,-0.536103,-0.037745,0.910839,0.048395,-0.374804,0.454701,-0.636401,-0.356250,-0.304047,-0.151253,-0.654034,-0.141050,0.212852,0.210550,-0.242159,0.252273,-0.622036,0.009316,-0.111017,-0.122941,-0.073261,-0.654260,0.121915,-0.476284,-0.283942,-0.837698,-0.631337,-0.063072,-0.005605,-0.195483,0.928765,-0.797364,0.184513,0.518616,0.272594,-0.473080,0.789108,0.057168,0.137417,-0.182501,-0.108088,0.489259,-0.173255,-0.067135,0.314593,0.454051,-0.216278,0.124277,-0.073113,0.591660', '30162520', '1309161', '4275444', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306002', '阿基尔，上帝的愤怒', '剧情', '16世纪在印加帝国毁灭后，一支西班牙征服者组成探险队，从秘鲁山脉南下至亚马逊河寻找黄金和财富。他们很快遇到了麻烦和危险，而阿奎尔，这个粗暴并贪婪的人成为了他们的领袖。他能够带领他们取得财富，还是将他们领向死亡？在此过程中，对西班牙的忠诚经受着考验，对权利的争夺也相继发生……', '克劳斯·金斯基', '沃纳·赫尔佐格', 8.3, 7905, 'tt0068182', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528956368.jpg', 0.5, 1.5, 15.3, 47.7, 35, '0.113603,0.333877,-1.148556,0.669036,-0.139294,-0.058105,0.749841,-0.064937,-0.555092,0.231429,0.246260,0.890718,0.205995,-0.245876,0.304118,-0.174236,-0.415684,-0.865180,0.026031,-0.274904,-0.464135,-0.386759,-0.334733,-0.492805,-0.091782,-0.537529,0.618973,0.405552,-0.383004,0.593529,0.254153,0.479716,-0.080015,0.810804,-0.534956,-0.096608,0.181528,0.012742,-0.529487,0.455180,-0.182724,-0.168977,-0.188496,0.218796,-0.000422,0.179931,0.621976,-0.608641,0.028629,-0.126556,-0.013127,-0.636617,0.143198,0.065665,0.489546,-0.062266,-0.137649,0.389542,-0.074057,0.083592,-0.147437,-0.312426,-1.130589,-0.223574,0.019334,0.259364,-0.658532,0.480237,0.192987,-0.170976,0.124536,-0.130053,0.242269,0.748707,0.355636,0.155919,-0.157679,-0.033625,-0.690207,0.053852,1.003788,-0.518974,-0.307400,-0.071759,-0.225602,-0.908338,-0.205039,-0.416378,-0.403242,-0.048740,0.623792,0.325586,0.123845,0.398294,-0.983893,0.325215,-0.128864,-0.530774,0.099075,-0.575488,0.154865,-0.477740,-0.223263,-0.412577,-0.386925,0.327740,0.000372,-0.071046,0.969105,-0.512513,0.217920,0.769977,0.979244,-0.537407,0.798949,-0.203128,0.207876,-0.253606,-0.013303,0.545110,0.054444,0.351033,0.041799,0.291354,0.263755,0.144742,-0.163515,0.633296', '25917239', '30163500', '1294941', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306004', '重返中世纪', '动作', '老教授爱德华·乔斯顿（比利·康诺利 Billy Connolly 饰）是一名致力于中世纪考古的历史学家，而发掘14世纪遗留下的拉洛克城堡一直是他的毕生心愿，然而直到今天，一家国际科技公司的总裁罗伯特（大卫•休里斯 David Thewlis 饰）愿意投资该项目，乔斯特的愿望才终于得以实现，他便马不停蹄地与儿子克里斯（保罗·沃克 Paul Walker 饰）一起组建了考古小组准备前往法国，探寻当年的古战场。然而考古小组成员在一次很平常的挖掘中，发现了一张1357年的求救纸条，署名竟然是乔斯顿教授，附近还发现了教授的眼镜，但距今已600多年。百思不得其解的组员们找到投资人罗伯特，方知野心勃勃的罗伯特竟秘密发明了一架时光机器，能穿越虫洞将人送回到1357年。面对着这个可怕而神奇的工具，克里斯决定带领成员一同重返中世纪，拯救父亲。然而他们谁也无从预测，在虫洞的另一头等待着他们的会是什么……本片改编自美国作家迈克尔·克莱顿（Michael Crichton）的同名小说。', '保罗·沃克', '理查德·唐纳', 6.4, 6278, 'tt0300556', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1878110577.jpg', 1.7, 12, 57.1, 23.5, 5.7, '0.134728,-0.176802,-0.463635,0.576980,-0.042164,-0.553732,0.230500,-0.123264,-0.693537,-0.488676,0.226793,0.742920,-0.018374,0.270223,0.244778,0.203826,-0.476926,-0.519994,-0.048314,-0.354013,-0.267887,-0.506748,-0.341938,-0.435383,0.156947,-0.300548,0.655754,0.113925,0.077582,0.333206,0.166611,0.296096,-0.233791,0.289446,-0.048099,-0.053790,0.446023,-0.046562,-0.318001,0.170108,-0.031381,-0.109728,-0.329255,0.001037,0.008984,0.159326,0.372783,-0.297659,0.037111,-0.099579,0.251738,-0.310793,-0.012618,-0.015580,0.406911,0.104316,0.156986,0.394787,-0.056909,0.021461,0.079067,-0.283925,-0.626540,0.082172,-0.021305,0.218579,-0.681735,0.243263,-0.228801,0.126199,-0.055651,-0.447748,0.228667,0.337924,0.322055,0.371068,0.019297,0.050202,-0.448177,0.270172,0.387765,-0.291562,-0.101736,0.280250,0.011845,-0.465627,-0.040158,-0.140955,-0.512174,0.068891,0.280007,0.145706,-0.186176,0.080528,-0.624013,0.011868,-0.533676,-0.202125,0.164722,-0.246150,-0.001564,-0.810910,-0.080060,-0.058305,0.002652,0.072513,-0.012116,-0.242089,0.690392,-0.640768,0.261596,0.550392,0.037530,-0.236810,0.739296,-0.136900,-0.112259,-0.311801,-0.044122,0.197991,-0.001139,0.453638,-0.022409,0.287190,0.232872,-0.496737,-0.262982,0.275409', '1293656', '6731985', '10763928', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306011', '最佳拍档', '喜剧', '飞贼黑猫（许冠杰 饰）抢夺国际犯罪组织的钻石后借助多种工具溜之大吉，黑猫在现场遗留的白手套让香港警方误认为作案者是国际大盗“白手套”，警方请到追捕白手套多年的美国光头神探（麦嘉 饰）查案，并派出干练女警何东诗（张艾嘉 饰）协助。另一方面，钻石主人——意大利黑帮要求白手套正身抵港取回钻石。光头神探与黑猫不打不相识，威逼利诱之下，黑猫决定协助神探拿获白手套。三人小组为找回遗失的钻石盲打误撞惹来连串麻烦，黑猫终于拿到钻石之际，潜伏的白手套也同时出现了……©豆瓣', '许冠杰', '曾志伟', 7.7, 32111, 'tt0084955', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2235503534.jpg', 0.4, 2, 29.3, 49.4, 18.9, '-0.004764,0.575972,-0.058295,0.326064,-0.013124,-0.016690,0.059264,0.228829,-0.153594,-0.132611,0.226586,0.429841,-0.230272,-0.131933,0.038760,0.062046,-0.368977,-0.761427,-0.082895,0.097440,-0.383761,-0.104966,-0.367771,-0.077022,0.047329,-0.241394,0.479338,0.281276,-0.031261,0.350559,0.636553,0.321511,-0.460748,0.045532,-0.086063,-0.563065,0.083455,0.322205,-0.394516,0.385386,-0.078169,-0.060264,0.457930,0.087645,0.129184,0.142468,0.505755,-0.111856,0.098104,-0.308946,0.408287,-0.212992,-0.094127,-0.431776,0.824905,0.242160,0.102755,-0.155972,-0.360945,0.184092,0.311989,0.093544,-0.562848,0.161729,0.310800,0.256895,-0.454261,-0.090169,-0.437764,0.394256,0.187230,-0.230335,0.149998,-0.011919,0.354909,-0.420053,0.450154,0.373269,-0.249910,0.486231,-0.060075,-0.124982,0.478834,-0.418955,0.144389,-0.492686,0.305504,0.057106,0.303293,-0.169669,0.619207,-0.324860,0.152654,-0.595365,-0.899399,-0.489721,-0.368537,0.100836,0.108799,-0.388124,0.094010,-0.725288,0.117026,-0.327141,0.160978,0.193589,0.602233,-0.163129,-0.008405,-0.461878,-0.113445,0.305367,-0.265697,-0.314623,0.169005,-0.210693,0.004536,-0.476090,-0.455238,-0.021279,0.438965,0.407482,0.233619,-0.005734,0.176324,-0.418109,-0.068877,-0.195814', '25723905', '1299790', '20274039', '1295547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306019', '大地之歌', '剧情', '在20世纪初印度孟加拉的一个小村庄里。生活的艰辛使得村里穷苦人家充满了苦闷、忧虑与不和。哈里哈尔写了一首首诗，一个个剧本，但到处碰壁，无法出版。六年过去了，哈里哈尔家的房子更加破败不堪，贫穷一步不舍地伴随着他们。无穷无尽的烦恼，纠缠着他们。富人丢了东西，就赖杜尔加偷走了，尽管妻子萨尔博加娅不愿忍受这种侮辱，却也只能拿孩子撒气。哈里哈尔希望通过一举成名来重振早已破落的“门第”，可是，他每月八个卢比的微薄收入，以及沉重的家庭负担，致使他始终无法实现其各种美好的计划，就连维持家里人填饱肚子也做不到。他只好去异地他乡寻找一条出路，进城去赚了一笔血汗钱，谁料回到家时，等待他的却是巨大的灾难：暴风雨把房子冲塌了，十二岁的女儿杜尔加也病死了，萨尔博加娅痛哭起来。见此凄惨情景，哈里哈尔只好带领着妻儿离开故乡，去另谋生路，只有杜尔加长眠在这里。', '卡奴·班纳杰', '萨蒂亚吉特·雷伊', 8.9, 8810, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2544551142.jpg', 0.3, 0.6, 7, 37.2, 55, '0.142901,-0.063932,-0.649363,0.331061,-0.251951,-0.576956,0.793113,0.164426,-0.378200,-0.076844,0.098764,0.595331,0.302370,0.325331,-0.110454,0.093087,-0.471382,-0.276708,0.063814,-0.260801,-0.088517,-0.336412,-0.072364,-0.297416,-0.345935,-0.060918,0.272922,0.276858,0.084091,0.287462,0.103741,0.162288,-0.098606,0.415823,-0.332187,0.128624,-0.257882,0.000964,-0.175585,-0.028863,0.058525,-0.129370,-0.402818,0.217747,0.238093,0.331708,0.609206,-0.107532,0.050958,0.069026,0.127074,-0.069072,-0.162047,0.260157,-0.015706,-0.208554,0.149314,0.020584,-0.465538,-0.043970,0.102860,-0.075292,-0.502275,0.096334,0.000361,0.061089,-0.852073,0.508501,-0.038866,-0.156760,0.121000,-0.510722,0.002716,0.217005,0.029374,0.611469,-0.272543,0.029422,-0.633059,0.230987,0.666827,-0.177433,-0.106802,0.092040,-0.325388,-0.110775,0.020525,-0.319231,-0.796324,-0.169337,0.413287,0.170471,-0.385817,0.212099,-0.565641,0.139205,-0.409114,-0.462175,0.140981,-0.438908,-0.132602,-0.317531,0.071100,-0.001544,-0.238117,0.150042,0.313078,-0.198233,0.655383,-0.195421,0.238533,0.592051,0.378414,-0.328337,0.442840,-0.063826,0.228655,0.090928,0.074913,0.425999,-0.175223,0.596817,0.424126,0.194291,-0.053772,0.104884,-0.188477,0.856014', '21619567', '1297606', '1308807', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306020', '情事', '剧情', '素贤（李美淑 饰）有一个美满的家庭，10岁大的儿子聪明可爱，丈夫是名事业有成的建筑师。纵然生活富裕不让素贤苦恼，但她的内心却感到了生活的苦闷。这时候，素贤妹妹的未婚夫宇因（李政宰 饰）出现了在她的生活中。这名比素贤小10岁的男孩子深深吸引住了素贤，宇因也对素贤有极大的好感，两人渐渐了解多了之后，竟然坠入了爱河，可是宇因即将要跟素贤的妹妹结婚了。他们将如何面对各自的丈夫与未婚妻呢？©豆瓣', '李政宰', '李在容', 7.5, 10213, 'tt0239510', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2596196998.jpg', 0.9, 3.8, 32.7, 43, 19.7, '0.107741,0.049948,-0.753078,0.559371,-0.319250,-0.280549,0.758665,0.173112,-0.456038,-0.109975,0.044321,0.930884,-0.252180,0.633483,0.099193,0.032497,0.094650,-0.742479,-0.078306,-0.117049,-0.349218,-0.266705,-0.305204,0.003049,-0.152300,-0.122755,0.397789,0.014432,0.153839,0.385867,0.370351,0.342279,0.114605,0.420223,-0.315625,0.358610,0.032060,0.225801,0.008535,-0.122778,-0.020072,-0.117250,-0.050181,0.223532,0.011636,0.589668,0.743050,-0.159304,-0.384446,-0.092434,0.494104,-0.064625,-0.205123,0.343203,0.026557,-0.063065,0.153937,-0.096221,-0.169485,-0.072699,-0.141238,-0.264225,-0.659975,0.193561,0.226481,-0.121687,-0.699802,0.571245,-0.045534,-0.476726,0.126348,-0.129698,0.257526,0.472037,0.039586,0.567376,-0.361639,0.199496,-0.224858,0.207415,0.765960,0.342147,-0.185243,0.591053,-0.516089,-0.498904,-0.070156,-0.355403,-0.838982,-0.004236,0.155085,0.144505,-0.229599,0.280774,-0.305122,0.071657,-0.339510,0.278683,0.025107,-0.580409,-0.149234,0.160663,-0.325042,-0.800996,-0.427097,0.236439,-0.000619,-0.383553,1.136698,-0.885200,0.126665,0.136286,0.541841,-0.654931,0.682150,0.299012,-0.025775,-0.095081,0.057140,0.252936,-0.335047,-0.253448,0.159002,0.309337,-0.307881,-0.268606,-0.420153,0.429519', '26348103', '1309161', '26283288', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306021', '山中传奇', '剧情', '落第举子何云青（石隽 饰）受高僧所托，前往经略府抄经书。云青所抄之书乃《大手印》，相传此经能沟通阴阳两界，超渡亡魂。途中云青三遇神秘吹笛女子，几经周折后他来到经略府，受到参军崔鸿至以及老大娘王婆的热情招待。当夜，云青受邀到王婆府上吃饭，结识了一位妙龄少女乐娘（徐枫 饰）。此时有个番僧闯上门来，云青认得他是跟了自己一路的人，王婆很快把他赶走。席间，乐娘击鼓助兴，云青在鼓声中渐渐昏迷。次日云青醒来，发现与乐娘共处一室，他不记得昨夜之事，乐娘却哭诉他们二人已经发生关系。王婆随即撮合二人成亲，结为夫妻后，云青与乐娘过上了神仙眷侣的日子，整天沉溺于床笫之欢中。然而这一切的背后，隐藏了一个极大的阴谋，王婆与乐娘，真实身份到底如何……©豆瓣', '石隽', '胡金铨', 8.3, 9471, 'tt0079886', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2263188547.jpg', 0.4, 1.6, 15.1, 46.6, 36.2, '0.287860,0.041951,-0.501766,0.142219,0.231336,-0.022973,0.411133,0.153624,-0.696365,-0.559895,0.066421,0.505335,-0.377959,0.282829,0.325716,-0.128125,-0.067621,-0.639494,-0.089429,-0.130399,-0.084260,-0.177247,0.219357,0.194631,-0.308766,-0.233973,0.026289,-0.054063,-0.057278,0.544530,0.083008,0.129831,-0.547226,0.355627,-0.353652,0.279778,0.082038,0.181461,-0.312990,-0.018095,0.002197,-0.483535,-0.392247,-0.129919,-0.180040,0.180906,0.508254,-0.285162,-0.122189,0.018562,-0.008431,0.063814,0.011624,0.244385,0.148542,0.072327,0.246471,0.270727,-0.054117,-0.040011,-0.250114,-0.006710,-0.092613,0.044007,0.228753,0.060372,-0.212160,0.191781,0.102434,-0.101182,-0.201477,-0.308565,0.287164,0.291480,0.118560,0.192788,0.070871,-0.203412,-0.474064,0.278084,0.855533,0.013183,0.280563,0.336263,0.295446,-0.169574,0.168472,-0.060574,-0.177570,0.155432,0.246964,0.132534,0.092232,0.200967,-0.265603,-0.185557,-0.345367,0.323487,0.077172,-0.199025,-0.030785,-0.347846,-0.309138,-0.368072,-0.234553,0.031284,0.243636,-0.042787,0.335585,-0.639028,0.145584,0.183861,0.166968,-0.442790,0.545761,-0.061410,0.296235,-0.184875,-0.020665,-0.232742,0.208233,0.217318,0.120488,0.230896,-0.024990,0.254498,-0.398361,-0.141418', '25721544', '1877016', '1294713', '1305084');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306029', '美丽心灵', '剧情', '本片是关于20世纪伟大数学家小约翰•福布斯-纳什的人物传记片。小约翰•福布斯-纳什（拉塞尔•克劳）在念研究生时，便发表了著名的博弈理论，该理论虽只有短短26页，却在经济、军事等领域产生了深远的影响。但就在小约翰•福布斯-纳什蜚声国际时，他的出众直觉因为精神分裂症受到困扰，然而这并没阻止他向学术上的最高层进军的步伐，在深爱他的妻子艾丽西亚（珍妮弗•康纳利）的鼓励和帮助下，他走得虽然艰缓，却始终没有停步，而最终，凭借十几年的不懈努力和顽强意志，他如愿以偿。©豆瓣', '罗素·克劳', '朗·霍华德', 9.1, 719145, 'tt0268978', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1665997400.jpg', 0.1, 0.3, 5.9, 33.9, 59.8, '0.199201,0.138963,-0.901889,0.759945,-0.020893,-0.385118,0.726723,0.159310,-0.579412,-0.280975,0.133867,0.788797,-0.192350,-0.170793,-0.009111,-0.026066,-0.235214,-0.775334,0.244334,-0.141437,-0.258546,-0.693131,-0.454348,-0.097276,-0.236674,-0.371618,0.766085,0.054288,-0.533849,0.279682,0.056531,0.167296,0.345329,0.676426,-0.241206,0.288373,0.261987,-0.021536,-0.091833,0.248927,0.475778,-0.367668,-0.305540,0.275083,-0.082132,0.327107,0.207217,-0.319346,0.023531,0.320634,0.369082,-0.275811,-0.132851,0.181094,0.296855,-0.119456,-0.035227,0.399657,-0.008815,-0.088238,-0.030956,-0.021447,-0.981107,-0.067454,-0.139409,0.389974,-0.789895,0.775727,-0.272771,-0.289166,-0.185273,-0.158386,-0.154669,0.400155,0.102142,0.428166,-0.186610,0.216759,-0.259007,0.117498,0.388094,0.336384,-0.589272,0.344094,-0.390823,-0.609395,-0.253806,-0.503574,-0.454958,-0.199619,0.336430,0.361333,-0.220894,0.209131,-0.219143,0.209938,-0.193684,-0.322060,-0.055618,-0.655341,-0.076626,-0.558943,-0.164999,-0.559574,-0.313654,-0.038949,-0.009293,-0.444266,1.028846,-0.883175,0.324104,0.600487,0.370960,-0.256917,0.956598,0.214035,-0.002717,-0.024982,-0.165975,0.596728,-0.160185,0.319084,0.037671,0.401722,0.329812,-0.149915,-0.286229,0.812684', '1870681', '27602116', '25932086', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306031', '天才一族', '剧情', 'Royal Tenenbaum（吉恩·哈克曼 Gene Hackman 饰）45岁那年夫妻分居，他一个人去住酒店，独自抚养孩子的妻子Etheline（安杰丽卡·休斯顿 Anjelica Huston 饰）把所有重心都放在了孩子才能的培养方面。不负众望，他们的三个孩子个个 都是天才，她以此写作了一本书——《天才一族》。大儿子Chas（本·斯蒂勒 Ben Stiller 饰）12岁时就对生意运筹帷幄，初中就购置不动产，对财务有着超同寻常的理解。二女儿Margot（格温妮斯·帕特洛 Gwyneth Paltrow 饰）两岁时被收养，这个话题被父亲叨叨终身以致Matgot有点神经质地耿耿于怀。这个天才剧作家9岁时就赢得了勇士奖。Richie（卢克·威尔逊 Luke Wilson 饰）从三年级起就是冠军网球选手，业余喜爱组乐队和收藏汽车模型以及绘画，17岁转做职业选手的他连续三年获得美国公开赛冠军。时间荏苒，父母分居过去20年，三个天才孩子长大成人，Chas在一次飞机失事失去妻子后从此和2个孩子惶惶度日，Matgot整日把自己锁在浴室不与丈夫交谈更是9年都没有新剧本面世，Richie在大海上准备一年的航行。这一切都被Royal的一个突然消息中止：他患上了癌症只剩下6个礼拜的生命，他想和家人共度最后的时光。这天才一家再度聚首，有趣的事层出不穷。', '吉恩·哈克曼', '韦斯·安德森', 8.1, 44113, 'tt0265666', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456224494.jpg', 0.3, 1.5, 18.9, 49.9, 29.3, '-0.076448,-0.241322,-0.522520,0.427132,-0.231458,-0.473888,0.464178,-0.031777,-0.506654,-0.401587,0.074468,0.925681,-0.200575,0.510018,0.094252,-0.073328,-0.220111,-0.868068,-0.062998,-0.339305,-0.352525,-0.307860,0.049628,-0.078940,-0.156694,-0.333494,0.488010,-0.250854,0.192987,0.409948,0.216470,-0.034497,0.241751,0.137203,-0.416124,0.053182,0.313939,0.128415,-0.065198,0.200116,-0.073536,0.019883,-0.153018,-0.053153,0.168203,0.127057,0.800627,-0.070828,-0.003966,-0.253435,0.332665,-0.123065,-0.375881,0.079827,0.508021,-0.032229,0.172410,0.180460,-0.252324,0.064783,0.040201,-0.299367,-0.574002,0.058481,-0.029831,-0.183599,-0.721959,0.595403,-0.219055,0.105118,0.026363,-0.260567,0.088912,0.460698,0.112524,0.537768,-0.323384,0.108263,-0.356591,0.556700,0.546853,-0.093199,-0.276801,0.444883,-0.001419,-0.559123,-0.109560,-0.468919,-0.522621,0.125130,0.281585,-0.058836,-0.043203,0.380120,-0.328269,0.080868,-0.156471,-0.338047,0.353921,-0.447359,-0.195199,-0.240580,0.060160,-0.144097,-0.504462,0.183282,0.248125,-0.259604,1.126485,-0.610025,0.216132,0.395947,0.139475,-0.495156,0.904005,-0.047672,0.377623,-0.337960,0.171300,0.109971,-0.146205,0.179275,0.061161,0.447319,-0.164263,-0.067286,-0.309275,0.459109', '1307146', '1308609', '1908036', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306032', '缺席的人', '剧情', '理发师艾迪（Billy Bob Thornton 饰）的生活平淡无奇，在百货店担任簿记的妻子多丽丝（Frances McDormand 饰）和他貌合神离，艾迪凭丈夫的直觉断定妻子与其老板戴夫有染。一日，艾迪接待的一位客人大肆吹嘘新兴的干洗生意，并拉拢艾迪投资，不甘在小镇寂寞一生的艾迪决意入股，并向戴夫发出了匿名威胁信勒索以获得资金。艾迪如愿收到封口费，但事情很快暴露，戴夫找到艾迪泄愤不成反被杀死。戴夫之死导致多丽丝入狱，艾迪反而未受怀疑，于是他超脱于事件之外，每日只靠少女贝蒂（Scarlett Johansson 饰）的琴声打发时光，不久一场车祸让事情急转直下……本片获2001年戛纳电影节最佳导演奖，2002年英国电影学院奖最佳摄影奖，伦敦电影协会年度男演员、最佳编剧等19项褒奖。©豆瓣', '比利·鲍伯·松顿', '乔尔·科恩', 8.3, 24793, 'tt0243133', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363366612.jpg', 0.6, 1.6, 15.8, 48.7, 33.3, '-0.258271,-0.157607,-0.326552,0.322274,-0.050891,-0.272320,0.248501,0.276195,-0.437151,-0.391153,0.096730,0.759796,-0.239748,-0.077631,0.516151,-0.173380,-0.203835,-0.522602,0.226735,-0.163897,0.419934,-0.513926,-0.055407,-0.343212,-0.260407,-0.511677,0.548307,-0.094017,-0.144864,0.567777,0.435639,0.195674,-0.134429,0.142426,0.173590,0.012211,0.222980,0.094931,-0.645779,0.601878,0.115479,-0.118665,-0.177445,-0.114535,0.106603,0.327711,0.436253,-0.006791,-0.123803,-0.060614,0.626527,-0.234071,0.039663,0.076708,0.248045,-0.216843,0.041417,0.298257,-0.546905,0.029621,0.396078,0.017989,-0.515445,-0.073422,-0.110685,0.010425,-0.424419,-0.001722,-0.153573,0.097873,-0.097666,-0.040172,0.034162,0.132873,0.477735,0.193340,0.054453,0.172777,-0.361732,0.355932,0.429493,-0.169553,-0.102693,0.240765,-0.013401,-0.367997,-0.072511,-0.344664,-0.527628,0.193195,0.350055,-0.077950,0.062240,0.083951,-0.236118,-0.400649,-0.233979,-0.371321,0.156553,-0.156410,0.140502,-0.698009,0.071012,0.227523,-0.260425,-0.290768,0.335955,-0.241974,0.264534,-0.316074,0.283789,0.639437,0.192622,-0.595120,0.505274,0.142802,0.215810,-0.299973,-0.209379,0.245517,0.315960,0.022861,0.065722,-0.150505,0.085598,-0.416455,-0.076685,0.261381', '1829654', '3275168', '1484091', '3077791');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306057', '龙的传人', '喜剧', '周小龙（周星驰 饰）与父亲周飞鸿（元华 饰）生活在大澳，与师妹毛毛（毛舜筠 饰）是一对单纯的欢喜冤家。某天，小龙的师叔毛仁（梁家仁 饰）到大澳躲债，飞鸿托阿仁把儿子小龙带到香港发展，阿仁意外发现了小龙高超的台球技术，变决定利用小龙进行赌博。黑帮龙哥看中了周家大澳的田地，便要求阿仁以地皮为赌注。小龙面对对方的世界级高手，压力巨大因此输掉了比赛。毛毛为了鼓励小龙，把自家的田地也作为赌注，决定要再次把自己的土地赢回来，但压力仍然困扰着小龙，比赛一度落后……©豆瓣', '周星驰', '李修贤', 7.3, 56720, 'tt0100047', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204523090.jpg', 0.5, 3.8, 42, 37.5, 16.2, '-0.195655,-0.120233,-0.377109,0.369531,0.061242,-0.416486,0.219855,0.302151,-0.414925,0.019949,0.604587,0.502899,-0.119785,0.083667,0.132652,-0.066491,0.005842,-0.542738,0.039013,0.121119,-0.041736,-0.617857,-0.149554,-0.095234,-0.043771,-0.010797,0.474074,0.005745,-0.344661,0.523980,0.238329,0.046403,-0.044976,0.367598,-0.039644,0.137479,-0.098809,-0.004052,-0.456628,0.206659,-0.034838,0.097471,-0.063301,0.469109,0.338785,0.200780,0.872319,-0.125782,-0.201744,-0.118501,0.174535,-0.044154,-0.153511,0.131088,0.179878,0.038602,0.254150,0.130549,-0.109161,0.208631,0.295582,-0.221037,-0.457205,0.362462,-0.030671,0.059213,-0.590284,0.375575,-0.004664,0.007099,-0.064829,-0.389847,-0.047353,0.256510,0.330499,0.225433,-0.678325,0.290833,-0.329100,0.282802,0.412379,-0.239809,0.323586,0.194772,0.049252,-0.251142,0.044677,-0.286249,-0.193278,-0.004823,0.592848,0.010179,-0.082673,0.073148,-0.752873,-0.220973,-0.115653,-0.224676,-0.046598,-0.345274,0.056868,-0.190312,-0.074745,-0.342838,-0.276792,-0.164760,0.066736,-0.344100,0.775034,-0.713143,-0.095595,0.519757,0.282699,-0.626505,0.362424,-0.065422,0.175798,-0.305415,-0.223388,-0.119164,-0.305300,0.252027,0.251328,0.193213,0.134523,-0.260653,0.007338,0.357888', '1292829', '4127270', '3445516', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306105', '木棉袈裟', '动作', '时为明朝末年，奸佞当道，世间离乱。强梁啸聚的锦衣卫雄霸一时，无奈江湖上少林中人扶危济贫，匡扶正义，令锦衣卫头目王澄（俞大陆 饰）恨之入骨。为此，他想出一条毒计，命得力手下祁天远（于荣光 饰）化名金光寺僧人了空，伺机潜入少林，图谋成为主持以号令天下。少林弟子惠能（徐向东 饰）得悉王澄阴谋，星夜赶回少林，途中在草原帮助少女林英（林秋萍 饰）一家勇拦惊马。与此同时，王澄率锦衣卫进入少林，逼迫住持圆慧让位祁天远。祁与圆慧比武，暗下毒手。关键时刻惠能及时赶到，并从住持手中得到象征少林正法的木棉袈裟。为有朝一日复兴少林，惠能保护袈裟遁走，而祁等紧追不舍。正邪对抗的千古传奇由此流传……©豆瓣', '徐向东', '徐小明', 6.9, 4473, 'tt0089637', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2359074380.jpg', 0.8, 5.5, 52.3, 32.6, 8.9, '-0.294179,0.319511,-0.366482,0.515125,0.241701,0.105467,-0.162595,0.295273,-0.553613,-0.504953,0.295590,0.381857,0.262626,-0.201113,0.122466,-0.148083,0.070003,-0.546978,0.095670,-0.258598,0.125626,-0.025766,0.106817,-0.163737,-0.249637,-0.132451,0.426205,0.611659,-0.307909,0.341602,0.267083,0.225008,-0.359477,0.200946,-0.173142,-0.221212,-0.118084,-0.029770,-0.392432,-0.064795,-0.586606,-0.595947,-0.109013,0.097896,-0.531186,0.154188,0.023635,-0.415097,0.135003,-0.303832,-0.019708,-0.089878,-0.194054,-0.047218,0.439451,0.212858,-0.008434,0.297393,0.082310,0.070151,-0.267128,-0.092941,-0.365401,-0.025805,0.574440,-0.050712,-0.281388,0.150245,-0.402891,-0.030222,-0.169924,-0.370078,0.063667,0.092569,0.350446,-0.174238,0.130937,0.044657,-0.534648,0.378214,0.333095,-0.387417,0.555650,-0.566788,0.321225,-0.080787,0.370495,-0.207102,0.253076,-0.092878,0.471982,-0.479625,0.433165,0.196299,-0.012422,-0.170554,-0.314523,0.512536,-0.017782,0.211733,0.075636,-0.477372,0.259987,0.249388,0.151264,-0.083444,0.371015,-0.104948,0.715904,-0.343669,0.084281,0.021316,0.100836,-0.515716,0.690284,-0.167233,0.413230,-0.276253,-0.274493,0.442293,0.301250,0.530319,-0.082405,0.004534,-0.118068,-0.000828,0.241711,-0.304608', '1297258', '6425116', '1299059', '6957273');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306123', '英雄', '剧情', '战国末期，燕、赵、楚、韩、魏、齐、秦七雄并起，惟秦国最为强大，急欲吞并六国一统天下，秦王（陈道明）因此成为六国大敌，各地不同的刺秦故事一直在上演，其中赵国刺客残剑（梁朝伟）、飞雪（张曼玉）、如月（章子怡）、长空（甄子丹）因名震天下的高超剑术，令秦王十年里没睡过一个安稳觉 。某日闻得长空已被名叫无名（李连杰）的秦国剑客杀死，秦王大喜急召其上殿相见，却也谨慎小心以防有诈，秦王和无名斗智斗勇的较量遂即展开。©豆瓣', '李连杰', '张艺谋', 7.6, 297379, 'tt0299977', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1774548839.jpg', 1.2, 5, 29.8, 40.2, 23.8, '-0.141640,0.392810,-0.641877,0.769544,0.657972,-0.184436,0.321811,-0.133157,-0.517088,-0.725526,-0.194517,0.397520,-0.430441,0.140624,0.209352,-0.368201,0.250463,-0.622031,-0.546080,-0.012360,-0.106077,-0.024423,-0.214578,-0.210613,-0.488849,0.219570,0.389915,0.210521,-0.372688,0.564125,0.381591,0.046153,-0.195845,0.712400,0.001399,0.178082,-0.432023,0.053170,-0.533243,0.102318,-0.087486,-0.505339,-0.302750,0.179955,0.163667,0.074013,0.155285,-0.376719,0.245484,-0.432150,0.367149,0.150086,-0.243654,-0.131432,0.474932,0.112109,0.073248,0.125652,0.252640,-0.166108,-0.223001,-0.296743,-0.464670,0.028479,0.282545,-0.186877,-0.303659,0.263515,-0.148129,0.023744,-0.271998,-0.061518,0.403326,0.372060,0.223751,-0.114213,-0.006448,-0.145097,-0.505609,0.460371,0.600678,0.200900,-0.293534,-0.394941,0.515593,-0.649974,-0.086546,-0.355754,0.142133,-0.068586,0.501205,-0.167750,0.344704,0.262061,-0.042607,-0.195980,-0.221840,0.348824,-0.102064,0.080984,0.221578,-0.395803,0.013880,-0.593581,-0.172542,0.166106,0.275462,-0.309795,0.604366,-0.616362,0.040413,-0.219021,0.345594,-0.368424,0.211954,0.178007,0.222831,0.046249,-0.242041,0.351263,0.188067,-0.027623,0.352097,0.208246,-0.549154,0.009477,-0.441183,0.090091', '1301022', '1307186', '25870679', '3564151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306130', '爱情麻辣烫', '剧情', '周建（王学兵）和夏蓓（刘婕）在繁琐的婚前准备过程中，与五段不同年龄段人的爱情故事迎面，在这些故事里，他们瞥见自己的过去、现在以及可能的未来。《声音》一段，他们见到的是少年人朦胧美好的初恋风情；《照片》一段，他们感受到的是青年人热恋的轰烈；《玩具》一段，年轻夫妇婚后平凡、平淡的生活与幻想世界的差距被他们尽收眼底；《十三香》一段，入他们眼的，是人到中年再次面对爱情考验时走上离婚之路的无奈和坚决；《麻将》一段，他们所见，则是步入人生黄昏之境的老年人沐浴夕阳之恋的温馨。©豆瓣', '高圆圆', '张杨', 7.5, 33251, 'tt0239220', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2184357657.jpg', 0.3, 2.5, 33.3, 47.8, 16.1, '0.419237,0.140938,-0.679008,0.582388,-0.180242,-0.066641,1.120105,-0.111416,-0.520608,-0.136070,0.250760,0.712089,-0.376218,0.394134,0.406817,-0.149089,-0.197920,-0.904882,0.002284,-0.255186,-0.256058,-0.329631,-0.402930,0.082746,-0.167044,-0.364500,0.907056,0.361735,-0.226702,0.588609,0.078875,0.096107,-0.460721,0.490891,-0.246596,0.007615,-0.046818,0.301199,-0.730599,-0.258954,-0.110400,-0.136961,-0.508358,-0.084487,-0.270693,-0.005540,0.875460,-0.223395,-0.319410,0.282003,0.515749,-0.094589,-0.451687,0.241321,0.276537,0.084215,0.310781,0.289279,-0.011003,-0.312017,-0.352454,-0.282100,-0.667629,0.031982,-0.182675,0.298375,-0.423737,0.542754,0.065014,-0.213576,0.497395,-0.240228,0.242185,0.248360,0.401631,1.030811,-0.198813,0.038151,-0.421297,0.368558,0.916923,0.417275,-0.398310,0.679369,-0.322452,-0.353136,-0.437709,-0.086606,-0.635175,0.194793,0.430315,0.159136,-0.211077,0.304285,-0.613679,0.292129,0.070404,-0.227154,0.072031,-0.620585,-0.299113,-0.552493,-0.257249,-0.840696,-0.632802,0.194556,0.372021,-0.344329,0.746039,-0.587198,0.263745,0.122479,0.188710,-0.189687,1.011862,0.039030,0.220280,-0.492139,-0.081563,0.338715,-0.345077,0.038461,0.232280,0.659089,-0.220010,0.481101,-0.731250,0.619019', '1291835', '5993185', '1296534', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306133', '呖咕呖咕新年财', '喜剧', '德华（刘德华饰）喜欢打牌，以打牌为生的他出名好牌技好牌品，与他相恋多年的咏琪（梁咏琪饰）因为牌品差，始终没能与德华结为连理，令她顿足。德华的弟弟天乐（古天乐饰）知道哥哥要以打牌为生养活患有痴呆症的母亲和正在读书的自己，决定跟青云（刘青云饰）打牌比试，谁知连连落败。一次牌局中，咏琪不甘被德华以牌品的问题多次推搪婚约，便咀咒他从此“一世摸烂牌”，跟着同样拜师不成的青云离开了。咀咒真的灵验了，使德华家道中落，但一向乐观的他深信自己的“好朋友”会回来的。在弟弟公司举行的麻将大赛中一路稳打稳扎，与青云再次对垒，最后能否获胜呢？©豆瓣', '刘德华', '杜琪峰', 6.7, 29713, 'tt0307034', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1122559210.jpg', 1.5, 10.2, 52.6, 25.9, 10, '0.158532,-0.142265,-0.600790,0.295379,-0.074628,-0.657138,0.202741,0.176965,-0.615631,0.097157,0.349917,1.072716,-0.070666,0.100252,-0.006078,0.073325,0.067238,-0.846262,0.259283,0.071771,0.047342,-0.582899,-0.179075,0.187215,-0.132737,-0.250874,0.142931,-0.189177,0.165062,0.813546,0.339495,0.151027,0.266067,0.214070,0.041939,-0.017126,-0.242967,0.217964,-0.610109,0.123404,0.257065,0.002418,-0.329974,-0.120596,0.344264,0.432325,0.311487,-0.070809,-0.202507,0.005030,0.212245,-0.163545,-0.392097,0.250833,0.057273,0.044140,0.620607,0.469929,-0.182623,0.006234,-0.131728,0.129242,-0.486417,0.344440,0.218834,0.002583,-0.617466,0.614244,-0.169005,-0.513532,-0.058521,-0.439793,-0.056219,0.340036,0.228423,0.304980,-0.378315,-0.031581,-0.422139,0.192220,0.703004,0.120122,-0.043914,0.269908,0.364947,0.029669,0.107343,-0.522841,-0.425663,-0.003659,0.139465,-0.029199,-0.217063,-0.031485,-0.464009,0.070441,-0.224543,0.169906,0.063861,-0.204960,-0.052582,-0.397462,0.000852,-0.508093,-0.439172,-0.194863,0.037409,-0.325801,0.705285,-1.127465,0.215081,0.263688,0.448754,-0.655899,0.624434,0.555432,0.130278,-0.028495,-0.289609,-0.133477,-0.287161,0.211460,0.288848,0.270466,0.419865,-0.303097,-0.407938,0.284599', '1292219', '1292720', '35030151', '22964524');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306140', '英雄好汉', '剧情', '阿勇（万梓良饰）、阿国（刘德华饰）兄弟俩浪迹香港街头，投靠了黑社会邦主剂哥（周润发饰）。由于阿国得到剂哥赏识，引起阿勇妒嫉，兄弟间产生隔阂。阿勇倒向朱老大，阿国却远去新加坡另谋生计。若干年后，阿勇羽翼丰满，逐杀朱老大自立邦主，又设计将剂哥帮派斩尽杀绝，剂哥遇难，孤身亡命新加坡寻找阿国，阿勇步步追杀，将剂哥妻子（刘嘉玲饰）、儿女惨杀，此刻悲痛、愤恨促使阿国重新出山，随剂哥返回香港以死相拼，报仇雪恨......©豆瓣', '周润发', '黄泰来', 7.2, 8702, 'tt0094356', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2557818615.jpg', 1, 5, 42.8, 36.8, 14.5, '-0.565804,-0.068316,-0.267352,0.486977,0.786598,-0.649546,-0.058547,0.289586,0.087963,-0.438636,-0.304615,-0.039164,0.159031,0.321783,0.003430,-0.277599,-0.342561,-0.172449,-0.046151,-0.093201,0.201745,0.078769,0.093338,-0.402395,-0.566445,0.141152,0.370506,0.265538,-0.312972,0.613113,0.601047,0.112340,-0.280338,0.277442,0.179691,0.263206,-0.091711,0.221906,-0.798887,-0.143858,0.163973,-0.184323,0.116205,-0.186904,0.358518,0.116853,0.667685,0.023710,0.207259,-0.546364,0.166273,-0.197886,0.006148,-0.303860,0.351698,-0.238835,-0.233650,0.177920,0.140500,-0.591864,0.190822,-0.066840,0.241041,0.112936,0.515478,-0.299166,-0.342014,-0.302716,-0.305540,0.303494,0.090552,-0.114624,0.449295,0.703963,0.386166,0.146341,0.071343,0.520852,-0.399514,0.440970,0.990588,0.100072,0.221248,-0.931996,0.310288,-0.503369,0.425477,-0.021648,-0.268967,-0.011042,0.354547,-0.679543,0.481970,0.451421,-0.158508,-0.470938,-0.154840,0.421411,0.331508,-0.199882,0.668727,-0.561453,0.073861,0.093778,0.244010,0.385836,0.002340,0.115558,0.246900,-0.084827,-0.005156,0.176160,0.802607,-0.589746,0.362804,-0.262915,-0.061009,-0.558752,-0.261943,0.340527,0.388267,-0.157128,0.289983,-0.210024,-0.330263,0.135288,0.225516,-0.369803', '1302705', '1291822', '1295344', '2084048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306154', '罗密欧与朱丽叶', '剧情', '罗密欧（莱昂纳多•迪卡普里奥 饰）与茱丽叶（克莱尔•丹妮丝 饰）在一个派对上一见钟情了，这个派对是为了庆祝茱丽叶找到了如意郎君。可是他们各自所在的家族是死对头，常常爆发冲突。罗密欧潜入了茱丽叶家的后院，两人互诉爱意，由于知道家族之间的不和是他们的障碍，所以他们在神父的帮 助下秘密完婚。茱丽叶的表兄泰华是个暴躁的人，他要跟罗密欧决斗可是罗密欧只想和平相处，罗密欧好友莫邱托想杀死泰华，却先被泰华杀死，罗密欧愤怒之下也把泰华杀了。罗密欧被驱逐出境，茱丽叶要另嫁他门。神父策划让茱丽叶假死，可是没有收到信件的罗密欧信以为真，在茱丽叶醒来之际，喝下了毒药……©豆瓣', '莱昂纳多·迪卡普里奥', '巴兹·鲁赫曼', 7.5, 92166, 'tt0117509', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1663002649.jpg', 0.6, 4.2, 34.3, 41.5, 19.5, '0.599431,-0.090198,-0.667692,0.512990,0.098356,-0.278319,0.829230,-0.006816,-0.331431,-0.128109,0.122142,1.014881,-0.229740,0.205424,0.046460,0.337788,-0.344970,-0.877091,0.122218,-0.251170,-0.180182,-0.551176,0.083284,-0.199097,-0.072894,-0.238089,0.583682,-0.145332,-0.362023,0.563169,0.444388,0.276529,-0.092874,0.520145,-0.149621,0.216740,0.360305,-0.282569,-0.526023,0.379543,0.038109,-0.100484,-0.239366,0.487644,0.186104,0.431879,0.289615,-0.313932,0.371339,0.062940,0.124207,-0.335261,0.089029,0.174618,0.148684,-0.244513,0.140891,0.379362,-0.222094,-0.327337,0.205713,-0.018871,-0.638394,0.272219,0.300881,0.157419,-0.766563,0.513071,-0.124399,-0.105507,0.390037,0.115366,0.370336,0.560334,0.391462,0.135174,-0.004917,-0.064839,-0.890398,-0.132594,0.947188,-0.132648,0.147938,0.490075,-0.091714,-0.401462,-0.059961,-0.216222,-0.509129,0.016643,0.483027,-0.089177,-0.182924,0.247625,-0.518559,-0.557288,-0.296419,0.227751,0.032620,-0.482010,0.011610,-0.499337,-0.416881,-0.253091,-0.346112,0.004443,0.091380,-0.136588,0.484438,-0.861551,0.112058,0.514352,0.425139,-0.428984,0.901444,0.315878,-0.091217,-0.274209,0.131794,-0.083039,0.302769,-0.011635,0.409063,0.458239,0.272241,0.034394,-0.562648,0.358042', '25721544', '1302384', '30162520', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306160', '新警察故事', '剧情', '陈国荣（成龙 饰）的所在那一组警察是警队精英，破案无数。阿祖（吴彦祖 饰）是总警师的儿子，却勾结了几个高官子弟( 蒋怡丶尹子维丶安志杰丶叶山豪)挑战警方。他们到银行抢劫，警钟敲响警察赶到时，就把阿荣及队员带进了一个早已设计好的空旷仓库里。警员都陷进了匪徒早已设计好的游戏程序里，残忍的被杀害，连阿荣女朋友可颐 （杨采妮 饰）的弟弟也被无法幸免。阿荣就此被停职，出于内疚也跟可颐分手了。 终日喝得烂醉的阿荣在酒吧遇到了阿锋（谢霆锋 饰），阿锋为了使阿荣振作起来，决定假扮警察告诉阿荣自己是上司派来要求得到阿荣协助翻案的新警员。 阿荣又遇到那群狠狠打击他的罪犯，与他们斗志斗勇，在警花莎莎（蔡卓妍 饰）的协助下知道匪徒当年的事件被编成了一部游戏，同时也知道了当年为何情报被泄漏的原因。©豆瓣', '成龙', '陈木胜', 7.8, 307760, 'tt0386005', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p481963295.jpg', 0.3, 1.9, 27.4, 49.9, 20.5, '0.364493,-0.120233,-0.357228,0.245384,-0.252897,-0.249212,0.542040,0.088427,-0.598511,-0.107517,0.263187,0.528626,-0.029888,0.081519,0.214359,-0.089729,-0.140908,-0.774165,-0.067967,-0.266725,-0.213283,-0.474247,-0.024090,-0.017438,0.175203,-0.223313,0.379003,-0.049737,-0.134649,0.344810,0.356164,0.318130,-0.216553,0.430261,0.017514,0.227286,0.337218,-0.213931,-0.175034,0.135429,-0.065077,-0.382062,0.168193,0.159446,-0.038051,0.407438,0.549684,-0.021069,-0.243923,-0.048253,0.216932,-0.397971,-0.103797,0.119044,0.486256,0.101701,0.219430,0.360251,-0.251659,0.139117,0.124264,0.018320,-0.728811,0.075730,0.125163,-0.059849,-0.745180,0.411325,-0.232932,0.118760,0.079777,-0.136893,0.456439,0.256624,0.176075,0.326681,-0.131393,-0.069424,-0.521697,0.280024,0.665304,-0.187674,0.292323,0.013488,-0.014432,-0.337028,0.107769,-0.193885,-0.312481,0.052082,0.471008,-0.207816,-0.317162,-0.133375,-0.467696,-0.157705,-0.287227,-0.013832,-0.260325,-0.377800,0.052349,-0.487408,-0.091408,-0.045973,-0.271326,0.172814,0.089776,-0.118711,0.609907,-0.821276,0.036073,0.486492,0.335582,-0.704864,0.453547,0.117378,0.060752,-0.016792,-0.082548,-0.215251,0.399501,0.389690,0.320879,0.378773,-0.089353,-0.607320,-0.297432,-0.227665', '1877596', '1301022', '1410695', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306161', '年轻的亚当', '剧情', '工人阶级出身的文学青年祖儿（伊万.麦克戈雷格 Ewan McGregor 饰）在驳船主里斯夫妇的船上打工并和夫妇二人一起生活在船上。一天，祖儿在岸边发现水里浮起了一具已经发白的女尸，惊慌的祖儿和里斯捞起了女尸。当晚，祖儿在和里斯夫妇吃饭的时候讲了白天捞起女尸的事情，并对女主人艾娜（蒂尔达.斯温顿 Tilda Swinton 饰）百般勾引，在丈夫身上得不到满足、平日阴沉抑郁的艾娜晚饭后就和祖儿搭上了。祖儿再一次提起了女尸的事情。原来，女尸生前曾是祖儿的情人。随着祖儿的回忆，事情一幕幕揭开……©豆瓣', '伊万·麦克格雷格', '大卫·马肯兹', 7.1, 6772, 'tt0289635', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p828649355.jpg', 0.7, 5.6, 41.9, 41.3, 10.5, '0.372816,-0.378684,-0.549328,0.289982,0.024307,-0.693255,0.987318,0.246117,-0.871198,-0.071542,0.143011,0.686824,-0.183089,0.304410,0.198845,0.226006,-0.593996,-0.900944,-0.118457,-0.147798,-0.323687,-0.486661,-0.113811,-0.134043,0.096475,-0.653149,0.162935,-0.333855,0.234916,0.889987,0.459554,-0.069945,-0.473852,0.638796,-0.049485,0.092517,-0.061061,0.319238,-0.251551,0.113757,0.157484,-0.295976,-0.078415,-0.137046,0.136650,0.530643,0.331571,-0.178850,-0.115596,0.025919,-0.099849,-0.072810,0.112337,0.227607,0.581657,-0.312002,0.186832,0.426246,-0.315086,-0.174968,0.102537,0.133030,-0.232211,-0.059700,-0.206129,0.402246,-0.912168,0.717511,-0.092215,0.038759,0.182598,-0.328058,0.430135,0.284176,-0.052865,0.286557,-0.105665,-0.060406,-0.499304,0.266157,0.140025,0.214576,0.473166,0.676981,-0.067195,-0.080238,-0.466329,0.106164,-0.334863,-0.116042,0.122288,0.224982,-0.498965,0.359824,-0.631606,-0.239184,-0.155504,-0.217013,-0.019106,-0.047714,-0.135390,-0.502642,-0.044910,-0.341634,-0.298573,-0.059978,0.141008,-0.352849,0.358827,-0.697060,0.516637,0.149783,0.291163,0.079074,0.491791,-0.051854,0.089274,-0.196600,-0.006209,-0.035415,0.013428,0.202883,0.382285,0.541088,-0.249074,-0.003410,-0.514970,0.753155', '3111650', '21348112', '1309172', '1301582');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306183', '茶泡饭之味', '剧情', '出身信州农村的佐竹茂吉（佐分利信 饰）与出身上流社会的千金小姐妙子（目暮实千代 饰）结婚，七、八年的婚姻生活并未弥合二人原本出身的差距，反而因生活习惯的差异使他们之间矛盾丛生。佐竹生活上不修边幅，抽便宜烟，吃茶泡饭，坐三等车厢。妙子受不了丈夫的“低级”生活习惯，时常背着他和学生时代的好友出玩游乐。两人的矛盾在对侄女婚事的看法上激化，妙子不辞而别，跑去神户同窗处散心。佐竹突然接到赴南美公干的任务，收到电报赶回的妙子发现家里已空无一人。当她终于感到失落时，飞机延误改为次日出发的佐竹却回到家中，夫妻二人共进一顿别样滋味的茶泡饭……©豆瓣', '木暮实千代', '小津安二郎', 8.1, 5852, 'tt0044982', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2018420870.jpg', 1.3, 0.8, 16.4, 53.3, 28.1, '0.499302,-0.055351,-0.474763,0.206551,0.286691,-0.444293,0.484199,0.499894,-0.462115,-0.562912,-0.021689,0.688374,-0.316923,0.295020,0.320589,-0.206747,-0.282752,-0.546769,0.069896,-0.235405,-0.000377,-0.456425,0.116708,-0.133343,-0.094968,-0.022099,0.448448,-0.195017,-0.128698,0.874098,0.109431,0.193937,-0.380274,0.410590,-0.217998,-0.013136,-0.055955,0.422483,-0.339478,-0.237898,-0.116286,-0.251408,-0.070584,-0.339620,0.370614,0.484186,0.624084,0.127843,-0.220453,-0.103496,0.111536,0.152831,-0.365668,0.127160,0.559008,-0.109330,0.089327,-0.005783,-0.194085,0.079812,-0.126006,-0.075983,0.023773,0.130424,0.233887,-0.090424,-0.270059,0.581617,-0.084731,-0.198923,0.027423,-0.385410,0.224900,0.399668,0.104475,0.543115,-0.078716,0.310611,-0.194292,-0.184976,0.747236,-0.066419,0.120104,0.053524,-0.323839,-0.222854,0.041057,-0.233423,-0.382548,-0.304049,0.102770,0.157548,-0.033489,0.167377,-0.513967,-0.035972,-0.073319,0.033956,0.501793,-0.022750,-0.039706,-0.628668,-0.022035,-0.615760,-0.446125,0.235787,0.371854,-0.057873,0.383105,-0.538435,0.089254,0.105426,0.122915,-0.432296,0.563273,0.141398,0.121810,-0.366723,-0.096385,0.168834,-0.157624,0.064974,0.015408,0.170942,-0.539913,0.100214,-0.334673,0.080734', '35256235', '26687241', '26365262', '3078390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306209', '江湖龙虎斗', '动作', '阿伦（邓光荣 饰）和阿天（周润发 饰）自小在澳门街头流浪长大，两人相依为命，情比兄弟，立志要闯出一番天地。就在二人终于出人头地，风生水起的时候，阿伦却因杀了黑帮老大高老四（谢贤 饰）的手下而在泰国遭到追杀。与此同时，阿天在儿时经常玩耍的修女院旧址，遇到了童年的玩伴卡希（夏文汐 饰），两人互生爱慕，订下终身。卡希希望阿天在结婚后转做正行，二人一起离开澳门，去香港生活。就在阿天准备和阿伦告别之时，高老四对阿伦的追杀愈演愈烈。大难当前，兄弟二人最终又会何去何从……©豆瓣', '周润发', '张同祖', 6.9, 5294, 'tt0093305', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204697044.jpg', 0.8, 5.9, 50.2, 31.2, 11.8, '0.036158,-0.270973,-0.767950,0.243213,0.059630,-0.641761,0.605159,0.338653,-0.339085,-0.020950,0.139413,0.854961,-0.093363,0.382024,0.338092,-0.162884,-0.200471,-0.794246,0.101450,-0.239753,-0.025754,-0.430059,-0.004362,0.139893,-0.096673,-0.148636,0.359291,-0.112747,0.040645,0.709867,0.208183,0.002988,-0.591965,0.262877,-0.344332,0.284321,0.081582,0.371701,-0.627950,0.002417,0.095590,-0.199184,-0.281929,-0.297934,0.274803,0.045741,0.642192,0.015668,0.063642,-0.128925,0.010475,0.076375,-0.029474,0.100156,0.435874,-0.144880,0.330494,0.196106,-0.091190,0.035072,-0.090909,0.032049,-0.094524,0.280081,0.287085,-0.100341,-0.823874,0.543876,0.202899,-0.117940,0.099238,-0.388744,0.145628,0.633382,0.134893,0.474017,-0.086763,0.073480,-0.353519,0.063745,0.843903,-0.027080,0.215314,0.008414,0.328860,-0.058935,0.056915,0.095734,-0.386606,-0.343057,0.520681,-0.075024,-0.208214,0.363105,-0.484558,0.013818,-0.158711,0.187266,0.279902,-0.337759,0.028695,-0.669561,-0.044640,-0.490500,-0.289275,0.331263,0.085522,-0.120965,0.614744,-0.917815,0.434146,0.441586,0.417643,-0.586313,0.543851,0.097544,0.278521,-0.197105,0.191690,0.135315,-0.064420,0.224012,0.270291,0.068786,-0.191953,0.037443,-0.333881,0.216496', '1292219', '1299062', '1308035', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306213', '初恋的回忆', '剧情', '杰米（曼迪·摩尔 Mandy Moore 饰）是一个学习优秀长相平凡的女生，身为牧师女儿的她信仰坚定，不为人所影响。兰顿（夏恩·韦斯特 Shane West饰）是典型的坏学生，不爱学习，吊儿郎当，瞧不起另类清高的杰米。因为一个过火的恶作剧，兰顿被罚到附属学校去做家教，并且要在一个舞台剧中扮演谦卑角色，而剧中的女主角正是他甚无好感的杰米。杰米对排练的投入渐渐感染了初到剧团的兰顿，兰顿开始投入角色，并对杰米有了改观。然而自信的杰米竟要兰顿立下约誓言，要他一定不能爱上自己。排练的日子相处磨合，男生女生间的感情还是悄悄滋长了。然而杰米却无法接受这个事实。面前这个不思进取的坏学生，怎么可能成为自己的恋人……©豆瓣', '曼迪·摩尔', '亚当·尚克曼', 7.6, 19356, 'tt0281358', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1077543791.jpg', 0.8, 4.3, 32.3, 41.3, 21.3, '0.419377,-0.051177,-0.489418,0.568476,-0.628015,-0.420862,0.797184,0.131968,-0.358292,-0.156128,0.207220,0.732623,-0.117480,0.134958,0.172353,0.228862,-0.211576,-0.683087,-0.017259,-0.124037,0.159460,-0.403633,-0.250256,-0.190520,-0.190375,-0.456579,0.497835,-0.177445,-0.166797,0.410350,0.353083,0.230969,0.280138,0.404751,0.125747,-0.137326,0.169696,0.065743,0.026560,0.035949,-0.095201,0.003241,-0.194146,0.280362,0.032062,0.489770,0.479005,0.015652,-0.381305,-0.099902,0.754938,-0.331416,-0.124735,0.200042,0.183430,-0.041860,0.145575,-0.054837,0.110661,0.123256,-0.262472,-0.225707,-0.896787,-0.072221,0.248964,0.251697,-0.606989,0.770793,-0.106062,-0.322685,-0.044092,-0.209704,-0.237423,0.009888,0.476494,0.595821,-0.248255,0.070729,-0.362736,0.085596,0.572485,0.038634,-0.470652,0.455949,-0.436369,-0.480585,0.090748,-0.326714,-0.677020,-0.082166,0.068041,-0.018740,-0.148835,0.263663,-0.318711,-0.115917,-0.189379,0.108064,-0.137485,-0.531026,0.048424,-0.405535,-0.208532,-0.579596,-0.436207,-0.099468,0.100430,-0.491217,0.767919,-1.173037,0.331461,0.694396,0.342682,-0.650025,0.527703,0.570567,-0.030079,-0.223938,-0.036104,0.391639,-0.280744,-0.036291,-0.047416,0.458588,0.098597,-0.376970,-0.187465,0.658258', '35030151', '4817024', '1390020', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306232', '咏春', '剧情', '云南某小镇。咏春（杨紫琼）年轻时被垂涎其美貌的恶霸逼婚，因不甘委身，她拜高人为师习得一身好武艺，回乡后不但将恶霸击退，还将时常骚扰乡邻的山贼打得落花流水，并从他们手中救下万艳娘（洪欣），后者被咏春开豆腐店的姑姑芳姑（苑琼丹）打扮成新一代豆腐西施招徕顾客。万艳娘的美貌将邻镇富商黄学州（李子雄）吸引，但对她心怀欲念同时，他也生出娶咏春作妻以保护家产的想法，殊不知对他钟情的只有芳姑。与咏春订下娃娃亲的梁博滔（甄子丹）千里迢迢来将她找，却误认万艳娘为未婚妻，咏春更因一身男儿打扮被他视作情敌，不过与万艳娘相处时，他总觉得哪里不太对劲。其后山贼头领夜入豆腐店欲掳万艳娘，只被咏春打成废人，山贼大王飞天猩猩为替他报仇，率领所有山贼策马入镇抢走万艳娘，咏春无奈只得应战。这刻令梁博滔恍然醒悟谁才是自己的爱侣。©豆瓣', '杨紫琼', '袁和平', 7, 10085, 'tt0111800', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2352118909.jpg', 0.6, 3.9, 50.2, 36.1, 9.2, '-0.001125,-0.231457,-0.385782,0.223250,-0.229889,-0.222828,0.353762,0.072848,-0.430577,-0.223342,0.355319,0.685024,-0.121466,0.071782,0.036364,0.163481,0.214619,-0.608580,-0.158576,-0.035692,0.098202,-0.035897,-0.125138,0.014573,-0.220481,-0.063561,0.288792,-0.143049,-0.268375,0.459359,0.378574,0.120199,0.013962,0.444245,-0.213477,0.180036,-0.252763,-0.174579,-0.094942,0.027708,-0.140110,-0.306733,-0.201192,-0.035494,-0.385740,0.430043,0.579780,-0.012294,-0.065532,-0.418743,0.106450,-0.279824,0.020209,0.250543,0.096580,-0.070321,0.082740,-0.105095,-0.081315,-0.145199,0.138754,0.055689,-0.422563,0.305981,0.297338,-0.346099,-0.642315,0.200209,-0.175787,-0.120179,-0.004045,-0.145893,-0.060866,-0.075232,0.218733,0.162575,-0.103041,0.100134,-0.429121,0.194732,0.583930,0.083524,0.162449,0.029660,-0.014900,-0.225531,0.548467,-0.369271,-0.238496,-0.031625,0.290233,-0.001380,0.007151,0.017957,-0.225959,-0.240295,-0.466018,0.315779,0.015961,-0.438406,-0.149008,-0.016696,-0.121625,-0.302028,-0.173413,-0.228958,0.531382,-0.086343,0.546243,-0.560297,0.014774,0.394929,0.369054,-0.610378,0.303755,0.040054,0.084857,0.060663,-0.256169,-0.045849,0.323528,0.240160,0.308955,0.161819,-0.270053,-0.086648,-0.121512,0.241799', '1301022', '1296978', '1877596', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306249', '唐伯虎点秋香', '喜剧', '唐伯虎（周星驰 饰）身为江南四大才子之首，却有道不尽的心酸。宁王想唐伯虎帮忙图谋作反，唐伯虎只好用内功改变脉象，令众人都相信他命不久矣。母亲埋怨他不应该把功夫暴露，因为他们家族一直被当年的仇人追杀。唐伯虎在与朋友出游时，遇到了貌若天仙的秋香并对她一见钟情，决心要到华府当 家丁以追求秋香，唐伯虎被取名华安。期间华太师遇到了宁王上门刁难，幸好有唐伯虎出面相助，并暴露了自己是唐伯虎的身份。秋香才知道华安是自己欣赏的唐伯虎。华夫人跟唐家有怨，因此二人便开始斗法。怎料宁王跟夺命书生再次上门，华夫人不是对手，幸得唐伯虎出手，华夫人也答应把秋香许配给唐伯虎。©豆瓣', '周星驰', '李力持', 8.7, 999340, 'tt0108289', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2357915564.jpg', 0.1, 0.6, 10.5, 41.4, 47.4, '0.298340,0.026151,-0.522968,0.377577,0.048791,-0.363423,0.506822,0.028724,-0.843896,-0.436463,0.199506,0.564872,-0.275513,0.154760,0.027260,-0.104301,0.039352,-0.669014,-0.000186,-0.185068,0.059900,-0.334132,0.236530,-0.022569,-0.343978,-0.058029,0.071127,0.017770,-0.336696,0.416351,0.387734,0.368448,0.058616,0.598581,-0.111658,0.176534,-0.328136,0.024132,-0.292919,0.086374,0.332381,-0.459302,-0.316524,0.192604,0.138713,0.298520,0.246642,-0.185294,-0.129912,-0.053081,0.144266,-0.345944,0.179290,0.220279,0.364204,-0.215254,0.146137,0.320922,-0.037209,-0.018080,-0.163261,-0.007478,-0.628989,0.272660,0.434943,-0.101438,-0.658190,0.029834,-0.186312,-0.294518,-0.320037,-0.377015,0.395810,0.221314,0.222760,-0.151764,0.025498,-0.107398,-0.752559,0.232268,0.766490,0.142168,0.339627,0.181376,0.126905,-0.306000,0.232483,-0.295353,-0.215664,0.331554,0.267669,0.043692,0.133498,-0.116666,-0.125870,-0.420390,-0.520463,0.362778,0.052593,-0.359764,0.163766,-0.110995,-0.159224,-0.348795,-0.272733,-0.111818,0.357959,-0.449172,0.618573,-0.846080,-0.067850,0.254452,0.502289,-0.904551,0.511941,0.064436,0.025431,-0.141647,-0.088318,-0.161304,0.062294,-0.088852,0.090981,0.074817,0.227391,-0.256876,-0.055291,0.115127', '1297710', '1877596', '1308805', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306254', '最后的城堡', '剧情', '一座由城堡改建而来的军事监狱中迎来了一位重量级犯人——陆军将军埃尔文（罗伯特·雷德福 Robert Redford 饰），监狱长温特（James Gandolfini 饰）笑脸迎接，但很快开始厌恶对方身上的军人傲骨。埃尔文在监狱中听闻诸多温特的劣迹，但抱着安心服刑的心态让他并未多事，很快，温特剥夺军人尊严的惩罚激怒了埃尔文，埃尔文开始用自己的方式令众犯人找回尊严，并顺理成章成为犯人的领袖，感到自己受到威胁的温特愈发不可理喻，下令射杀一名犯人导致双方矛盾升级。埃尔文决定组织实施监狱暴动，以使上级部门介入对温特的调查。这些昔日的军人、如今的犯人们抱着重新回到战场的觉悟，在高度组织和秘密的情况下完成了作战的准备，一次双重间谍的任务成功之后，犯人军团吹响了夺取监狱的号角！©豆瓣', '罗伯特·雷德福', '罗德·拉里', 7.8, 8743, 'tt0272020', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p860152130.jpg', 0.6, 2.6, 25.1, 47.9, 23.8, '0.282451,0.256703,-0.576035,0.548106,-0.347199,0.047672,0.717920,0.208528,-0.653299,-0.273052,0.416175,0.629989,0.049601,0.158303,0.348979,-0.386605,-0.426218,-0.741674,-0.237654,-0.151140,-0.364209,-0.504892,-0.153603,-0.514823,-0.087675,-0.479784,0.860275,0.055806,-0.269984,0.263859,0.421870,0.520853,0.211849,0.434744,0.025759,-0.297138,0.313188,-0.397908,-0.277983,0.302906,-0.012119,-0.087846,-0.227442,0.338311,-0.036072,0.335388,0.687742,-0.404381,-0.298721,-0.277183,0.301083,-0.437887,0.060211,0.328313,0.405713,0.226344,-0.344962,0.405781,-0.028395,0.065347,-0.056911,-0.205703,-0.717746,-0.380240,-0.002969,0.167558,-0.386025,0.171799,-0.210176,0.372399,0.121346,-0.104041,-0.020952,0.387312,0.282335,0.386868,-0.250844,0.056833,-0.478667,-0.079813,0.666412,-0.356534,-0.295637,-0.171791,-0.162120,-0.438987,0.046358,-0.358250,-0.208266,-0.200092,0.227424,0.067779,-0.014597,0.202114,-0.539791,-0.289520,-0.502711,-0.212352,-0.156254,-0.433811,0.048102,-0.684204,-0.090886,-0.044109,-0.204090,0.085688,0.041640,0.006439,0.503982,-0.715245,0.250096,0.509533,0.050583,-0.595403,0.050561,0.104754,0.222831,-0.265723,0.099916,0.248497,0.321755,0.515360,0.189881,0.136958,-0.219752,-0.267715,-0.061976,0.419031', '30345227', '26759819', '7051375', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306255', '人狼', '剧情', '二战后的十数年，日本从战败的阴影中逐渐走出，进入了经济高度增长的时代。然而强硬的经济政策也导致失业率的不断攀升，各种反政府武装势力不断抬头，安定的社会治安荡然无存。为了应对这一难题，政府建立了拥有高度自主权的首都圈治安警察机构，通过精良的装备和果断的武力来打击以“党派”为首的反政府组织。随着经济不断发展，崇尚暴力的首都圈警察和“党派”逐渐遭到民众的厌弃和孤立。在一次激烈血腥的交战中，隶属“党派”的少女阿川引爆炸弹自杀，目睹这一幕的首都圈警察成员伏一贵心灵受到前所未有的冲击。这一刻起，他的人生悄悄发生转变……本片荣获2000年每日电影最佳动画片奖、1999年葡萄牙国际奇幻电影节最佳动画片奖和评委会奖。©豆瓣', '藤木义胜', '冲浦启之', 8.6, 17338, 'tt0193253', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2543987719.jpg', 0.3, 1.1, 12, 39.6, 47, '-0.069762,0.027957,-0.764962,0.679759,0.375548,0.251229,0.393715,0.231929,-0.691966,0.079243,0.336030,0.576352,-0.302440,-0.254582,0.441438,-0.499282,-0.316186,-0.903205,-0.271330,0.002324,-0.120334,-0.277579,-0.482283,-0.317340,-0.206117,-0.388429,0.891174,0.247114,-0.664828,0.280496,0.178589,0.351530,-0.078941,0.387537,0.128022,-0.165948,0.262006,-0.385567,-0.347419,0.321251,0.002177,-0.516822,-0.060186,0.125158,-0.032981,0.192114,0.795561,-0.195427,-0.037342,-0.266595,0.774488,-0.322700,-0.645388,-0.053010,0.543958,0.212145,-0.077903,0.177550,0.056543,0.025940,-0.051652,-0.367282,-0.670319,-0.029962,0.133889,0.011005,-0.430879,0.486658,0.087173,0.118265,-0.089260,-0.031329,0.040498,0.776119,0.246623,0.489881,-0.411145,0.231584,-0.283593,0.212047,0.533960,-0.075448,-0.670698,-0.115853,-0.449984,-0.562863,-0.279324,-0.564947,-0.069225,-0.327737,0.370470,-0.045955,0.014663,0.592118,-0.789292,0.218046,-0.069461,-0.731402,0.096013,-0.210819,-0.094794,-0.835406,-0.305062,-0.297225,0.134249,0.169219,-0.136996,-0.044603,0.913525,-0.566796,-0.033874,0.661257,0.422289,-0.633971,0.399048,-0.221719,0.146645,-0.164159,-0.416252,0.071622,-0.057528,0.404460,-0.096110,0.180946,-0.198171,-0.228976,0.083633,0.200709', '25863940', '27602116', '2032143', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306303', '无主之地', '剧情', '波塞战争期间。雾色中，一队波斯尼亚士兵向塞尔维亚阵地接近，不幸天明时被对方发现，波斯尼亚士兵西基（Branko Djuric 饰）中弹滚入战壕，战友则全部牺牲。塞方派出新兵尼诺（Rene Bitorajac 饰）在一老兵带领下检视战场，老兵将弹式地雷塞入波方士兵尸体下面充作陷阱，找到了武器的西基突然出现，击毙老兵后将尼诺俘虏。不久“尸体”突然醒转，西基看着地雷上的战友无能为力，只好与尼诺二人在波塞阵地之间的无主地带请求帮助。联合国维和部队接到求助赶到现场，维和高层领导本着避免麻烦的原则拒绝施救，英国女记者珍妮获得这一消息后借媒体力量对维和指挥部施压。但是维和部队与媒体的介入，并没能扭转混乱战争中的又一悲剧事件。本片获2002年奥斯卡最佳外语片奖等二十余项褒奖。©豆瓣', '布兰科·德约里奇', '丹尼斯·塔诺维奇', 8.6, 29220, 'tt0283509', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192940679.jpg', 0.2, 0.6, 9.4, 49.2, 40.7, '0.127076,-0.155981,-0.443484,0.182726,0.519615,-0.110301,0.510299,-0.255146,-0.404787,0.149556,0.423260,0.511902,-0.043362,-0.257678,0.348367,-0.280069,-0.556057,-0.923898,-0.355093,-0.128479,-0.655513,-0.492643,-0.233920,-0.371446,0.002569,-0.537308,0.621945,0.197914,-0.082431,0.674448,0.158546,0.171585,-0.087743,0.689254,0.333952,0.090203,0.334597,-0.411853,-0.418276,0.389854,-0.324440,-0.364355,-0.334454,0.113994,0.125062,0.243590,0.843206,-0.440229,0.142073,-0.140926,-0.048973,-0.428471,0.187505,0.014413,0.610855,0.118341,0.282561,0.022084,0.024934,0.227067,-0.019220,0.091220,-0.189673,-0.023739,-0.162426,0.040453,-0.544713,0.288697,-0.024589,0.453069,0.145709,-0.032178,0.142644,0.406196,0.291799,0.146807,-0.343753,0.006023,-0.105829,0.029662,0.380609,-0.331869,-0.207296,-0.229248,-0.047910,-0.457231,0.261281,0.004252,0.046376,-0.004686,0.588078,0.107239,0.170469,0.122360,-0.474576,0.047717,-0.498039,-0.377732,-0.080375,-0.217464,-0.238389,-0.633667,0.097984,0.447606,-0.268253,0.460212,0.055915,0.374951,0.665613,-0.289129,0.054823,0.321121,0.366690,-0.179664,0.390271,-0.018264,0.151138,-0.144729,0.216921,0.131149,0.226935,0.501961,0.258255,-0.075106,-0.477033,-0.474131,-0.184384,-0.264065', '26375609', '26365262', '26788667', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306313', '杀手蝴蝶梦', '爱情', '不问江湖事多年的老张（关海山 饰）开了家临海的PUB，与女儿阿立（王祖贤 饰）及伙计阿列（钟镇涛 饰）过着简单快乐的生活，阿立与阿列是情侣。某日老张被旧搭档找上门，被迫战战兢兢出山，但事情中途还是突变，被他拉去做司机的阿列成杀人凶手。老张喊阿立同他及阿列一起偷渡时被抓，为救他，阿立 答应跟黑社会老大神爷（陈惠敏 饰），并哄骗阿列让他先去了菲律宾。6年后，阿列在菲律宾成为名杀手，阿立则一副大姐大做派，身边跟有忠实小弟阿祥（梁朝伟 饰）。神爷听闻昔日搭档将在法庭上指证他，派人找来杀手做掉了那人，该杀手正是阿列。而在行动中，阿列无意间与阿立重逢，虽6年里从没忘情阿立，阿列神情仍是冷漠。时间难敌爱意，得知当年事情真相后，阿列再牵亦是时时将他思念的阿立之手。不想重逢一幕被神爷的手下、一直想占阿立便宜的料哥（刘家辉 饰）尽收眼底。阿立收拾行装时，心存邪念的料哥冒了出来，但及时出现的阿详打碎了他的黄粱美梦，不过神爷亦因此被惊动。', '钟镇涛', '谭家明', 6.8, 6518, 'tt0093944', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2387503787.jpg', 0.9, 6.7, 51.6, 30.6, 10.2, '0.210227,-0.054060,-0.449291,0.142647,-0.277280,-0.306992,0.479451,0.017340,-0.730297,-0.206322,-0.071788,0.654322,-0.092182,0.176081,0.162432,0.194965,-0.299137,-0.711049,0.030561,-0.095469,-0.128274,-0.261340,0.003972,-0.133133,-0.193071,-0.014048,0.160540,-0.083673,0.011824,0.561948,0.406258,0.306316,-0.218910,0.496929,-0.093764,0.035897,-0.083801,0.046518,-0.299420,0.063906,0.003294,-0.369804,-0.222564,0.053422,-0.008025,0.432846,0.228821,-0.013463,0.021183,-0.092155,0.005532,-0.340751,0.153185,0.167751,0.258040,-0.011037,0.045334,0.301334,-0.250904,-0.094141,0.142858,0.111676,-0.489762,0.208779,0.075187,-0.051159,-0.773031,0.334314,-0.166544,-0.025448,0.088482,-0.368431,0.284231,0.095149,0.319036,0.178911,-0.050316,-0.095870,-0.415990,0.102320,0.572115,-0.081980,0.319507,0.138439,0.136411,-0.331003,0.149749,-0.331434,-0.311928,0.157758,0.219552,-0.004745,-0.313257,0.123022,-0.285930,-0.312677,-0.288369,-0.043950,-0.241431,-0.349899,-0.070261,-0.133459,-0.116400,-0.351845,-0.414949,0.105179,0.043630,-0.095166,0.429686,-0.591808,0.232860,0.337342,0.331849,-0.445410,0.626203,0.246030,0.053730,-0.092832,-0.068255,-0.048562,0.191500,0.239450,0.511173,0.207507,0.032620,-0.203022,-0.046302,0