INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306317', '美少年之恋', '剧情', 'MB Jet（冯德伦）倚仗年轻和出众外形，十分自负与玩世不恭，认为同不同男人之间的性交易不过是场游戏，但偶遇神秘男子Sam（吴彦祖）与女子Kana（舒淇）后，他被Sam的独特气质吸引，幻想能同Sam有真正的爱情，遭到同行阿青的警告。Jet又遇Sam，得到对方礼待，虽对两人纯洁的朋友关系疑惑，他却十分享用过程，想着有机会将两人关系升级。一次打球受伤事件令Jet与Sam遇见阿青，Sam刻意隐瞒的过去被逐层解开，Jet找到Sam的虚点，展开攻势，如愿以偿获得身心享受，但悲剧在两人激情过后紧接发生。©豆瓣', '冯德伦', '杨凡', 7.5, 92453, 'tt0168496', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p673858463.jpg', 0.5, 3.6, 33.5, 43.8, 18.6, '0.318414,0.023754,-0.609695,0.458976,-0.037939,0.114193,0.918631,-0.120272,-0.540994,-0.267790,0.024134,0.631365,-0.663069,-0.082683,0.252286,-0.408669,0.162035,-0.634208,0.259675,0.099728,0.026830,-0.409466,-0.278069,0.100619,-0.199870,-0.613462,0.750874,-0.038337,-0.528284,0.768047,0.229214,0.175360,-0.314988,0.668855,-0.299178,-0.267758,-0.189144,0.349066,-0.532865,0.263379,0.071983,-0.033573,-0.198504,0.022084,-0.088815,0.255701,0.799105,-0.000666,-0.526779,0.195658,0.300931,0.106332,0.032711,0.219454,0.101770,0.316102,0.104759,0.327296,0.126931,-0.295960,0.074893,0.005696,-0.495010,0.162345,0.247278,0.047561,-0.229886,0.504270,0.161293,-0.286325,0.091319,-0.247411,0.135350,0.181021,0.847328,0.075282,0.033371,0.095714,-0.513633,-0.257269,1.014283,0.232373,-0.272301,0.558726,-0.300398,-0.407633,0.049165,-0.451691,-0.201555,0.407883,0.002521,0.324344,-0.114219,0.126946,-0.505220,-0.058755,-0.103668,0.267906,0.003210,-0.672941,-0.009477,-0.604240,-0.423612,-0.544569,-0.672108,0.012714,0.034636,-0.658324,0.582873,-1.113284,0.048131,0.408306,0.412272,-0.673772,0.799298,0.283184,-0.014108,-0.426934,-0.113772,0.237302,0.181539,-0.569653,0.017240,0.260864,-0.507217,0.188770,-0.340142,0.143404', '1293265', '35030151', '1308755', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306319', '绝世好Bra', '喜剧', '日本著名胸围公司的香港区总裁Samantha（刘嘉玲 饰）破例聘请了Johnny（刘青云 饰）和Wayne（古天乐 饰）两名男设计师。他们的上司高级设计师Lena（梁咏琪 饰）觉得他们根本无法胜任这份工作，因此常常刁难他们。公司要求他们设计出一款“绝世好Bra”，可是多次失败。在工作的过程中，Johnny和Wayne分别与Smantha和Lena产生了感情，最后他们也在各自女友的帮忙下，才最终把“绝世好Bra”设计成功。©豆瓣', '古天乐', '陈庆嘉', 5.8, 44761, 'tt0306651', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p478500626.jpg', 3.5, 21.9, 60.3, 11.6, 2.8, '0.023775,0.057877,-0.600691,0.694280,-0.186750,-0.086017,0.244923,0.173457,-0.499033,-0.379259,0.132892,1.002557,-0.177937,0.227496,0.287557,-0.129818,-0.385488,-0.788006,-0.023241,-0.227496,-0.211216,-0.432429,-0.406883,-0.065285,-0.159911,-0.085573,0.655986,-0.113717,-0.120843,0.306779,0.486258,0.276283,-0.109821,0.339276,-0.014242,-0.168199,0.432386,-0.034133,-0.546835,0.259747,0.033833,-0.160980,0.096911,0.081840,0.292556,0.207568,0.604746,0.129851,-0.396926,0.041964,0.496350,-0.024237,0.319102,-0.075480,0.336289,0.145684,0.618992,0.385590,-0.289134,-0.074612,0.152692,-0.171067,-1.010600,0.060925,0.489681,-0.397302,-0.633175,0.404601,-0.284481,-0.087289,0.009407,-0.385260,0.177529,0.414924,0.594734,0.053813,-0.094381,0.148895,-0.406257,0.576658,0.638779,0.206282,-0.069516,0.066550,0.149684,-0.466038,-0.335478,-0.449149,-0.207482,0.096351,0.212024,0.211968,0.050920,-0.463634,-0.818956,-0.097945,-0.035176,-0.162276,0.022933,-0.452821,0.435421,-0.872045,0.079837,-0.425292,-0.546378,-0.172188,0.184555,-0.256355,0.806811,-0.853058,-0.045251,0.412417,0.574738,-0.800590,0.971046,0.050563,0.356910,-0.144295,-0.285699,-0.475994,-0.082626,0.139679,0.323180,0.593436,0.030564,-0.296367,-0.257170,0.005942', '4301278', '26678784', '1793491', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306326', '笼民', '剧情', '香港寸土寸金，一些底层民众无楼可住，只得栖聚于危楼屋舍之中的床位。这些老弱病残分别用铁丝网相互隔开，被称为笼民。其中，祖先生（乔宏 饰）的智障儿子（廖启智 饰）终日嬉戏耍闹。唐三（泰迪罗宾 饰）是占小便宜的货色，而且尖牙利齿嘴不饶人。老人在笼中度过百岁寿辰，一直贩卖杂货维持生计，还有算命先生整天念念有词于事无补。此地发生命案，警察前来调查，却始终无法改变困境。这时，古惑仔毛仔（黄家驹 饰）从狱中放出，无视CID老爸的责骂，而与昔日死党重新混在一起，并住进了笼中。这时，公寓管理人员说接到业主收回楼宇的信函，希望各位租住户可以搬出，引起群情激愤。笼民开始向正在竞选的徐、周两位议员申诉，而后者为了收买人心，都作出了体察民情的样子。暗地里，徐议员与业主勾结，用重金收买毛仔，骗得了笼民自愿搬出的签名……本片获得第22届香港电影金像奖最佳影片，最佳编剧。张之亮获得最佳导演，乔宏获最佳男配角奖。', '黄家驹', '张之亮', 8.9, 10374, 'tt0107461', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2650624850.jpg', 0.3, 0.5, 8, 36.6, 54.6, '0.113862,-0.126302,-0.294479,0.284335,-0.052250,-0.115353,0.655389,0.174862,-0.466582,-0.186235,0.030914,0.316424,-0.295381,0.369708,0.161748,-0.329917,-0.221817,-0.475834,-0.178792,-0.178963,-0.028248,-0.390244,-0.049964,-0.261644,-0.363805,0.050165,0.499869,0.074570,-0.150573,0.108685,0.569873,0.218699,-0.411370,0.135736,-0.053850,0.059061,-0.044066,-0.055895,-0.383066,0.186426,-0.161067,-0.364359,-0.206656,-0.170400,0.292932,0.394731,0.628373,-0.141732,0.139798,0.010672,0.264465,-0.060732,-0.086415,0.129650,0.323133,0.057700,0.346827,0.102934,-0.187082,0.355980,0.107014,-0.143801,-0.238017,0.024467,0.277331,0.150150,-0.326561,0.088130,0.207879,0.137470,-0.155562,-0.127719,0.393911,0.152743,0.112310,0.189650,0.014689,0.040586,-0.551314,0.305272,0.391278,-0.012156,-0.015063,-0.150347,-0.198638,-0.341871,0.209257,-0.247120,-0.298220,-0.128811,0.177943,-0.012288,0.187860,-0.057371,-0.314710,-0.277046,0.135746,-0.132648,0.156071,-0.203206,0.021436,-0.797371,0.041166,-0.069021,0.189466,0.066142,0.164848,-0.115840,0.382696,-0.521829,-0.028780,0.015082,0.398253,-0.216837,0.611024,-0.163472,0.307288,-0.100393,-0.180408,-0.077625,0.225088,0.379090,0.271732,-0.043848,-0.301741,-0.341147,-0.074527,-0.077060', '10466639'