INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306334', '行运超人', '喜剧', '叶孤红（杨千嬅饰）生性开朗乐观，纵使历年来经历了很多倒霉事，但都让她一笑置之，更常常研究各种术法转运。城中著名堪舆学家赖料布（梁朝伟饰），自小便得祖训不得与姓叶的人结缘，叶孤红为了能得其指点，便想尽办法接近料布，二人缘分也从此开始。料布算得原来一直有高人扰乱孤红的生活，那人便是赖料布的死对头段蟹（郑中基饰）。要把叶孤红置之死地的是她父亲的第二任妻子。赖料布抛开祖训，决心和孤红携手对付段蟹。©豆瓣', '杨千嬅', '谷德昭', 6.7, 33421, 'tt0380069', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2358921365.jpg', 1.2, 8, 53, 28.3, 9.5, '0.195088,-0.333196,-0.380286,0.784060,-0.192014,-0.192287,0.147257,-0.054955,-0.697361,-0.294982,0.037961,0.590071,-0.140017,0.223669,0.240862,0.079886,0.164150,-0.535643,0.092093,-0.224565,-0.126798,-0.383734,-0.230560,-0.218960,-0.300045,-0.333834,0.319782,0.345246,-0.141085,0.224777,0.288793,-0.031253,-0.116500,0.327548,-0.249129,-0.110761,-0.623022,0.161203,-0.360779,-0.299533,0.065036,-0.357712,-0.283965,0.143384,0.177231,0.103398,0.354375,-0.341112,-0.043660,-0.109158,0.303752,-0.195682,0.021689,0.176383,0.300937,-0.022279,0.433153,0.629595,-0.316061,-0.001147,0.082989,-0.009610,-0.642687,0.047582,0.355444,-0.193798,-0.687006,0.275398,0.058943,-0.081868,-0.293870,-0.237820,0.117590,0.311067,0.308659,0.312241,0.075630,-0.185274,-0.436322,0.426039,0.724175,0.011802,-0.021861,0.275179,0.004659,-0.369698,-0.227791,-0.401987,-0.292058,0.017421,0.283589,0.037308,-0.216109,0.502673,-0.401442,0.193987,-0.050073,0.239323,0.164974,-0.322799,0.131153,-0.420860,-0.039998,-0.594432,-0.098109,0.171555,0.290531,-0.403635,0.881889,-0.647170,0.035773,0.156476,0.051127,-0.814881,0.619342,0.332995,0.182419,-0.229411,-0.094394,0.186645,0.049291,0.087571,0.125221,0.275807,0.116252,-0.162398,-0.200993,0.277266', '1877596', '26283288', '27602116', '10561880');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306345', '回转寿尸', '喜剧', '本片由三个故事组成：故事一《头魂》：讲述年轻警察（林晓峰 饰）负责看守一宗无头女尸案的现场，竟然发现了案情的真相跟管理员七叔（林尚义 饰）有关。故事二《撞鬼》：年轻夫妇（徐锦江 饰）（江希文 饰）开车撞死人不顾而取，结果被鬼魂一直纠缠，把夫妻两捉弄得苦不堪言。故事三《最后晚餐》：老母亲（罗兰 饰）逝世了，她的儿子（黄秋生 饰）、媳妇（苑琼丹 饰）、孙子孙女便是十分不孝。母亲在三七之夜回到了家里，原来仍牵挂着自己的孩儿。众人才能感受到老母亲的爱，但已太迟。©豆瓣', '黄秋生', '叶伟信', 6.6, 5861, 'tt0280753', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2354363390.jpg', 1.3, 9, 55.5, 25.7, 8.5, '-0.047981,-0.409033,-0.530514,0.269175,0.064863,-0.444420,0.551321,0.203021,-0.637494,-0.440913,0.269864,0.417847,-0.218932,0.402365,0.136371,0.022614,-0.122869,-0.414307,-0.014261,0.010772,-0.137528,-0.336941,0.126225,-0.241116,-0.078599,0.057204,0.042537,-0.075333,0.195238,-0.023850,0.451415,0.150972,-0.516552,-0.060201,-0.114642,0.281064,0.082489,0.127770,-0.252179,-0.189356,0.015927,-0.078519,-0.021446,-0.038923,-0.106742,0.154790,0.756183,-0.373719,-0.148742,-0.282937,0.380867,0.114408,-0.099313,0.057105,0.309039,0.103468,0.511666,0.405410,-0.094918,-0.176842,0.126553,-0.013382,-0.158915,0.268037,0.128910,0.195836,-0.572527,0.033790,-0.248579,0.150419,0.087046,-0.316876,0.381466,0.121963,0.263196,0.510220,-0.262276,-0.009677,-0.286930,0.396306,0.388696,-0.038742,0.248851,0.239201,0.165668,-0.137977,-0.054003,-0.101462,-0.300621,0.259436,0.266476,-0.069050,-0.076679,0.136980,-0.298372,-0.484329,-0.158754,0.004950,0.055351,-0.129471,-0.104933,-0.188452,0.014351,-0.130302,-0.269602,0.183561,0.166934,-0.123073,0.651496,-0.209946,0.251581,0.106215,-0.030066,-0.693984,0.333251,0.267937,0.230919,-0.432087,0.082520,0.094323,0.070651,-0.154232,0.377518,0.081461,-0.331339,-0.215513,-0.341523,0.040635', '20470260', '1364764', '3179758', '4946963');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306367', '爱的蹦极', '剧情', '一个夏季的雨天，女生金太嬉（李银珠饰）走进男生徐仁友（李秉宪饰）的伞下避雨，男生对她一见钟情。大学里二人的感情逐步升温，雨夜，二人吵架又和好，感情浓得化不开。任友服兵役前一晚，没有等到答应前来送行的太嬉，就此缘悭一面。17年后，徐仁友已经有一个幸福的家庭，太太和小女儿让他的生活从容平静。在男校执教的他，发现班上一个17岁的男孩子的动作举止与当年的太嬉惊人相似，勾起了他埋藏多年的回忆，才发觉原来自己一直不能忘怀。而男学生面对仁友的感情，内心也起了波澜。甚至与小女朋友分手。太嬉，到底在哪里？17年前的谜团解开后，是一段极致的生死之恋。©豆瓣', '李秉宪', '金大胜', 7.4, 6144, 'tt0276818', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1052614642.jpg', 0.9, 4.3, 34.8, 42.1, 17.8, '0.287363,-0.219528,-0.564107,0.540337,-0.294474,-0.471461,0.964291,-0.012692,-0.479910,-0.191322,0.009222,0.676187,-0.272977,0.540824,0.337293,-0.084378,-0.099981,-0.843447,-0.108055,-0.231507,-0.113957,-0.301218,-0.166933,0.282591,-0.123414,-0.202372,0.585600,0.109556,0.071378,0.650520,0.245599,-0.192483,-0.102979,0.497741,-0.030104,-0.078493,-0.072281,0.516373,-0.218132,-0.084737,0.087997,-0.320580,-0.304719,-0.010695,-0.191924,0.312259,0.660265,-0.083380,-0.304330,0.136591,0.372428,-0.149616,-0.214105,0.089123,0.354303,-0.014158,0.125413,0.162010,-0.119937,-0.217836,-0.071163,-0.092276,-0.227952,0.216175,-0.010234,0.109628,-0.455842,0.665639,0.014416,-0.048231,0.066197,-0.339896,0.017954,0.197501,0.361161,0.451481,-0.510625,-0.025763,-0.163369,0.156171,0.686760,0.038033,-0.275178,0.484999,-0.470568,-0.330139,-0.117623,-0.097547,-0.743356,0.058419,-0.039634,0.117750,-0.279908,0.321738,-0.621290,0.087270,-0.068883,0.146926,0.178396,-0.435897,-0.159041,-0.358043,-0.416211,-0.636889,-0.400030,0.116811,0.165792,-0.254662,0.582007,-0.927837,0.191424,0.258586,0.382090,-0.318230,0.711759,0.127194,-0.065464,-0.228185,-0.000596,0.294433,-0.372969,0.089892,0.061159,0.586823,-0.275444,0.079602,-0.406704,0.367507', '4275444', '1292219', '1308755', '25911595');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306381', '摩登如来神掌', '喜剧', '广告公司任职的武德辉（刘德华 饰）与同事厉迟（陈百祥 饰）前往大陆公干，顺便走私出土文物。他们无意中发现了一个秘洞，得到了一本武功秘籍，并且救出了冷冻在山洞中的元朝云萝公主（王祖贤 饰）和侍女小蛮（梅小惠 饰），但是也无意中放出了邪派高手天残（元华 饰）。原本就精通多国语言的公主在 现代社会中如鱼得水，而阿辉与阿迟在两个古代女子的帮助下也分别练成如来神掌与七旋斩，成功地完成了屌丝到大侠的逆袭。但正当二人春风得意的时候，天残出现了，誓要抢走云萝公主。一次天残追杀到阿迟家中，幸亏他误把阿迟父亲（曹达华 饰）认成大侠龙剑飞才使云萝公主和小蛮成功逃走，但是阿辉和阿迟却被他抓住。在大陆特异功能人士（刘询 饰）的帮助下，阿辉终于练成了如来神掌的最后一式“万佛朝宗”，战胜了天残拯救了公主的命运。©豆瓣', '刘德华', '黄泰来', 6.6, 16419, 'tt0102365', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2349367183.jpg', 1.7, 10.5, 54.8, 24.4, 8.6, '0.204234,0.306488,-0.452330,0.776042,0.093313,-0.228549,0.390784,-0.110077,-0.316198,-0.107035,0.413659,0.616580,-0.070838,0.122893,0.393480,0.225710,0.041476,-0.672886,0.058426,-0.166368,-0.360541,-0.204839,-0.282320,0.063975,-0.167226,-0.522861,0.586633,0.013790,-0.102144,0.531591,0.063658,0.048642,-0.312108,0.540335,-0.365007,0.286212,0.111564,0.058719,-0.144982,0.540613,0.092060,-0.410515,-0.220045,0.263175,-0.092640,0.230587,0.427790,-0.465194,0.159364,-0.061677,0.174593,-0.162558,-0.282459,0.051233,0.349242,-0.126580,0.409330,0.236267,-0.133250,0.031480,0.137905,0.002137,-0.442166,0.026368,0.279103,-0.143342,-0.647672,0.326335,-0.261358,0.019976,-0.182179,-0.524038,0.396712,0.190626,0.193889,0.233818,-0.305286,-0.249475,-0.716780,0.260404,0.309899,-0.168885,0.024516,0.120938,0.379817,-0.422198,-0.154987,-0.339135,0.037102,-0.074159,0.506816,-0.187977,-0.156137,0.148552,-0.521647,-0.190022,-0.403043,0.170924,-0.089893,-0.416422,-0.049543,-0.281894,-0.084234,-0.287129,-0.260796,-0.155195,0.412205,-0.243476,0.733755,-0.933904,0.194734,0.141219,0.169949,-0.303137,0.669926,-0.123827,0.119905,-0.074365,-0.255016,-0.220014,0.036993,0.444469,0.154538,0.669818,-0.043957,-0.276217,-0.308448,0.171986', '4127270', '21360412', '22964524', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306392', '豪门夜宴', '喜剧', '开发商曾小智（曾志伟 饰）为人油嘴滑舌，为了买入楼盘谎话说尽，他的竞争对手洪大宝（洪金宝 饰）不遑多让，二人在经纪人学友（张学友 饰）的牵线下亦敌亦友。曾小智获悉科威特王子阿里巴巴（林子祥 饰）即将抵港，而王子手中握有一份重建海湾战争后家园的巨额开发计划，为了得到合同，曾小智决定请出自己多年没有探望过的老爸曾老伯（吴耀汉 饰）配合，打造自己的孝子形象迎合王子。小智和娇生惯养的妻子咪咪（郑裕玲 饰）将曾伯从小妹阿芝（关之琳 饰）和丈夫阿辉（梁家辉 饰）家中接出，并拟定多种训练对父亲进行“上层人”的改造。曾老伯苦不堪言，而宴会因洪大宝的介入一再出现状况，一心求财的曾小智能够如愿么？本片为帮助1991年大陆水灾筹备善款而拍摄，其中客串的明星多达上百位。©豆瓣', '曾志伟', '张坚庭', 7, 22168, 'tt0101999', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2534461167.jpg', 1.5, 7.8, 46.5, 28.2, 16, '-0.179266,-0.024055,-0.414602,0.463532,-0.098284,-0.191995,0.296384,0.108947,-0.570320,-0.303323,0.408611,0.619134,-0.124827,0.064274,0.209931,0.028821,0.000374,-0.474890,0.029543,0.059930,0.039870,-0.435732,-0.213566,-0.224742,-0.329659,-0.250396,0.442853,-0.159322,0.007634,0.402272,0.315269,0.152462,-0.125171,0.102980,-0.124265,-0.039107,0.009640,0.325429,-0.617741,0.161278,-0.101723,-0.250781,-0.172852,0.017213,0.227247,0.337175,0.506904,-0.241706,0.137463,-0.195394,0.365561,-0.187999,0.276915,-0.018249,0.100178,0.262448,0.495683,0.309905,-0.344911,-0.074537,0.192245,-0.266582,-0.659114,-0.039624,0.229200,0.020340,-0.524690,0.364485,-0.366103,0.060218,0.067395,-0.297371,0.149745,0.443123,0.204571,0.158521,-0.099828,0.059494,-0.225800,0.564235,0.331068,-0.083004,0.284013,0.149057,-0.070984,-0.425164,0.188378,-0.334874,-0.373326,0.151117,0.091952,-0.094288,0.073532,0.108392,-0.468903,-0.121526,-0.268956,-0.181364,0.263609,-0.300862,0.051735,-0.542847,-0.076642,-0.230715,-0.017408,0.070698,0.386438,-0.245085,0.658756,-0.717376,0.104266,0.227423,0.374716,-0.711249,0.466175,0.106368,-0.113730,-0.344898,-0.129300,-0.158347,-0.014108,0.000882,0.062528,-0.081623,0.032930,-0.339593,-0.181143,0.149581', '4301278', '26678784', '27602116', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306396', '东方秃鹰', '剧情', '越战硝烟散尽，但是战争的影响并未消失……为了摧毁军队留在越南的大批飞弹，美军挑选了十名包括杀人犯童明辛（洪金宝 饰）、走私犯任人熙（袁和平 饰）等在内的华裔犯人，组成一支特种小队，委托林上校（林正英 饰）领导。同时，特种小队兼负联络滞留越南的美军上校之兄杨龙的使命。此次任务代号为“东方秃鹰”在特种小队空降越南之时，任务负责人意外身亡，导致任务取消。幸有三名柬埔寨游击队员（高丽虹等 饰）在当地协助，林上校决定将任务完成，特种小队与杨龙及义子“老鼠杰”（元彪 饰）一行，在越共的层层围剿中，向美军的战时秘密军火库进发……©豆瓣', '洪金宝', '洪金宝', 7.6, 10144, 'tt0090956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204698541.jpg', 0.6, 3, 31.8, 45.8, 18.7, '-0.108982,-0.149247,-0.704160,0.563658,-0.073762,0.068768,0.205911,-0.046436,-0.406245,-0.420661,0.387048,0.476381,0.515363,-0.447963,0.265534,-0.561224,-0.254079,-0.701851,-0.682659,-0.321716,-0.509200,-0.538508,0.114013,-0.494966,0.182800,-0.367466,0.911556,0.253108,-0.272668,0.487030,0.475426,0.644369,-0.590816,0.324242,0.086778,-0.316964,0.749329,-0.470296,-0.383426,0.372883,-0.398282,-0.024523,-0.015130,-0.138086,0.236499,0.422473,1.128868,-0.311317,-0.022620,-0.501596,-0.388069,-0.494251,0.258169,-0.275499,0.589589,0.415103,0.062347,0.053224,0.104071,0.374010,-0.102977,-0.083177,-0.471401,-0.245560,0.272128,0.145810,-0.492913,0.322322,-0.423271,0.384449,0.150383,-0.087303,0.361833,0.731336,0.206010,0.050260,-0.078923,0.337552,-0.403001,0.505188,0.551199,-0.361054,-0.032594,-0.382950,0.115570,-0.565921,-0.037923,0.110714,0.134812,-0.065073,0.237082,-0.009774,0.502831,0.027747,-0.646261,-0.121220,-0.325222,-0.336110,-0.266925,-0.246912,0.176220,-1.112158,0.302447,0.207475,-0.032984,0.709772,0.140786,0.233530,0.516907,-0.554469,0.261773,0.194096,0.134416,-0.596490,0.035790,0.311821,0.367098,-0.554071,0.129563,0.064961,0.465218,0.406421,0.303062,0.255734,-0.254009,-0.677557,-0.153618,-0.277401', '2369613', '1306809', '1300371', '24746649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306403', '僵尸家族', '喜剧', '一次偶然中，古董商人郭敦煌（钟发 饰）和其徒弟发现了一座古墓，墓中躺着三具额头上贴有符纸的僵尸，在僵尸的身上，郭敦煌发现了生财之道，却在无意之中将镇压僵尸的符纸弄掉，引得僵尸复活，他的徒弟亦因为和僵尸搏斗而身负重伤。郭敦煌一行人找到了林医生（林正英 饰），求其救治，林医生告诉三人，僵尸十分危险，必须将其彻底消灭。然而，郭敦煌却并不愿意放弃好不容易弄到手的摇钱树，与此同时，警方亦闻风而动，情势十分混乱。男僵尸（张荣祥 饰）和女僵尸（王玉环 饰）千方百计寻找逃脱的办法，小僵尸（何建成 饰）却和人类小孩交起了朋友。©豆瓣', '元彪', '刘观伟', 7.4, 31189, 'tt0091293', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1994728933.jpg', 0.5, 3.8, 37.5, 38.8, 19.2, '-0.046524,-0.048532,-0.434970,0.379721,-0.108064,-0.233594,0.830162,-0.232218,-0.696525,-0.410373,-0.091744,0.147658,-0.253686,0.170542,-0.079591,-0.219599,0.097018,-0.319479,-0.139553,0.087399,-0.788720,-0.036414,-0.395108,-0.510446,-0.108042,-0.198509,0.565277,0.309155,-0.179751,0.134032,0.321936,0.169776,-0.553621,0.438021,-0.054027,0.007922,-0.336415,0.001626,-0.005864,0.217781,0.129638,-0.544280,0.086238,-0.081701,-0.079865,0.232547,0.720194,-0.432550,-0.002631,-0.154743,0.134646,-0.372236,-0.013813,-0.017845,0.366121,-0.259202,0.153751,-0.196175,-0.045831,-0.347655,0.323166,0.078802,-0.256315,0.054044,0.196434,0.304195,-0.574840,0.263241,0.214943,0.557751,-0.309695,-0.526471,0.522093,0.064858,0.145229,-0.182203,-0.011549,-0.228735,-0.779858,0.372365,0.192785,0.109512,0.176625,-0.184007,-0.032031,-0.847149,-0.140890,0.123698,-0.047271,0.054173,0.710997,0.235280,-0.274820,-0.190506,-0.494838,-0.460738,-0.427103,0.243047,-0.243166,-0.155139,0.276310,-0.409375,0.007625,-0.102668,-0.000201,0.126404,0.060415,-0.316053,0.526439,-0.622620,-0.064865,0.087944,0.463123,-0.055733,0.456556,-0.428192,0.146369,-0.300070,0.020661,0.208443,0.626371,0.433770,0.589224,0.253235,-0.291570,-0.200058,-0.339795,0.381449', '21619567', '1394470', '1294037', '1303407');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306421', '惊变28天', '科幻', '剑桥科研小组发现一种可以令传染者处于永久杀人状态的病毒，这种病毒传染速度极快，且无法抑止。动物保护组织成员不慎释放了实验室中一批携带该病毒的大猩猩后，繁华的伦敦于短短28天变成一座死城。自行车快递员（西连•墨菲）于28天后的某一个早晨醒来时，发现自己赤身裸体躺在一家破旧的医院里，周围一片狼藉，令他怀疑是在梦中。夜晚来临时，他受到被病毒传染了的人的袭击，危急时刻幸被施莲娜（内奥米•哈里斯）和麦克（诺厄•亨特利）搭救，他也才知晓伦敦发生的一切，而这座城市没被传染的人，仅剩极小部分伦敦居民和一些驻守在曼彻斯特外的军人。当三人费劲千辛万苦找寻到拯救未来的一线希望时，才发现真正恐怖的还不是病毒。©豆瓣', '基里安·墨菲', '丹尼·博伊尔', 7.2, 76422, 'tt0289043', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191905718.jpg', 1.3, 6, 39.3, 40.7, 12.7, '0.142365,0.127755,-0.736762,0.289278,-0.038689,0.237299,0.750827,-0.126885,-0.672232,-0.440529,0.319606,0.770132,-0.195151,0.199665,0.280892,-0.124619,-0.092943,-0.413575,-0.150128,-0.130350,-0.772498,-0.254193,-0.567060,-0.276317,0.011399,-0.445482,0.461406,0.407665,-0.202782,0.185851,-0.220385,0.453577,-0.155503,0.565968,-0.110095,-0.123482,0.157250,-0.308697,0.026055,0.344135,-0.026038,-0.247164,0.109636,0.184280,-0.240712,0.167580,0.817646,-0.386741,-0.264643,-0.350012,0.361498,-0.290268,-0.070549,0.097247,0.451448,-0.218899,-0.026319,-0.152273,-0.331181,-0.035055,0.135971,0.167907,-0.697157,-0.140767,0.068958,0.197711,-0.245362,0.420155,-0.080200,0.020662,0.013078,-0.348320,0.279672,0.309533,0.201390,0.532279,-0.045365,-0.252716,-0.642677,-0.173757,0.611658,-0.359027,-0.729842,0.358506,-0.288058,-0.372675,0.122206,-0.317666,-0.374572,0.090953,0.179342,0.288770,-0.398760,0.152791,-0.511667,0.031744,-0.347892,-0.278876,-0.353328,-0.104884,-0.400291,-0.740534,0.060587,-0.172600,0.159970,0.159051,0.018478,-0.091513,0.393932,-0.829909,0.416026,0.714366,0.189156,-0.301249,0.507027,-0.377088,0.164354,0.017101,0.020737,0.270031,0.229460,0.543607,0.164493,0.333962,-0.216384,-0.004091,-0.214592,0.383146', '3005387', '26718838', '2988294', '25728612');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306439', '迫在眉梢', '剧情', '生活并不富裕的约翰·Q·阿奇伯德（丹泽尔·华盛顿 Denzel Washington饰）是个工厂里卖命工作的工人。为了养家糊口，两夫妻感情日渐淡漠而导致婚姻濒临破裂。更加雪上加霜的是，不幸降临在了他们9岁的儿子迈克尔身上。一天，迈克尔突然在棒球场上昏倒，当约翰·Q把儿子送到医院后才得知：儿子患有严重的先天性心脏病，需要进行心脏移植手术才能保住性命，这高昂的手术费用远远超过他的医疗保险范围。约翰·Q几经沟通未果，医院主管决定把他们从等待移植者的名单中剔除。此举激怒了作为父亲的约翰·Q。他愤然持枪闯入了医院的急诊室，绑架了无辜的医护人员和病人做人质，要求院方立刻为儿子动手术。这场挑战道德与法律的人性之战，并非想象得如此简单……©豆瓣', '丹泽尔·华盛顿', '尼克·卡萨维蒂', 8.3, 53335, 'tt0251160', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2174974798.jpg', 0.3, 1.1, 15.8, 47.3, 35.5, '-0.034123,0.041611,-0.476270,0.200026,-0.197680,-0.297904,0.638023,0.181357,-0.430795,-0.230231,0.297442,0.625707,0.145577,0.255821,0.272039,-0.156853,-0.208960,-0.570675,-0.313161,0.019480,-0.586813,-0.601089,-0.006075,-0.450526,-0.133502,-0.446088,0.574145,-0.102247,-0.152608,0.327508,-0.000230,0.412792,0.283859,0.250834,-0.024254,-0.095294,0.113977,-0.089771,-0.295296,0.262570,0.349729,-0.329066,0.190691,0.292174,0.154810,0.608903,0.514102,0.063341,-0.403018,-0.255991,0.528569,-0.365354,-0.192361,0.330791,0.281702,-0.046454,0.251916,0.286219,-0.356830,-0.068929,0.035831,-0.140077,-0.933480,-0.219579,0.013034,0.058694,-0.565738,0.367591,-0.258961,0.188266,0.013271,-0.209016,0.198610,0.481541,0.063182,0.650047,-0.433919,-0.100589,-0.445737,0.085746,0.627097,-0.350356,-0.161814,0.304553,-0.326009,-0.575892,0.249399,-0.385231,-0.337284,-0.008828,0.347559,-0.005339,-0.239563,0.094931,-0.083519,-0.220605,-0.465706,-0.383915,-0.066392,-0.208739,0.029152,-0.344508,0.032781,-0.081330,-0.294055,0.074388,0.092320,-0.215826,0.588035,-0.536897,0.130441,0.534323,0.371530,-0.587206,0.499292,0.032693,0.519433,-0.209869,0.064456,0.154654,0.210649,0.563931,0.121158,0.065801,0.045639,-0.015530,-0.307269,0.362002', '26678784', '1793491', '30163500', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306442', '间接伤害', '剧情', '消防员戈登（阿诺•施瓦辛格 Arnold Schwarzenegger 饰）有一个美好幸福的小家庭。然而，却遭遇飞来横祸：哥伦比亚的恐怖分子为了自己的目的在洛山矶市的繁华路段炸毁了一栋大楼，迟到的戈登亲眼目睹了爆炸引起的大火将在大楼前等侯自己的妻儿活活烧死，然而美国官方只给了戈登四个字解释――间接伤害。虽然戈登四处奔走，呼吁将凶徒乘之于法，然而哥伦比亚官方称这是叛军所为，而这伙叛军已和政府军进行了长达10年的内战，政府也没有办法将匪徒缉拿归案。官方软弱的行为彻底激怒了戈登，戈登决心亲自前往哥伦比亚找出这伙恐怖分子让他们血债血偿！©豆瓣', '阿诺·施瓦辛格', '安德鲁·戴维斯', 6.4, 4891, 'tt0233469', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1322587808.jpg', 1.2, 10.4, 61.7, 21.7, 5, '0.083162,0.041100,-0.741038,0.496899,0.129447,-0.231277,0.856387,0.022167,-0.437871,0.047950,0.232744,0.578644,0.005970,-0.078520,0.117058,-0.163481,-0.193343,-0.580654,-0.224808,-0.103534,-0.299408,-0.543477,-0.104490,-0.433693,0.047984,-0.047547,0.535045,0.327177,-0.224130,0.248423,0.400023,0.312997,0.122226,0.537875,-0.002857,0.099005,0.160843,-0.451277,-0.238982,0.290833,-0.076078,-0.445270,-0.036396,0.357718,-0.131641,0.635107,0.686227,-0.183297,-0.112716,-0.137860,0.238521,-0.712595,0.061733,0.362162,0.399271,-0.076979,-0.043383,0.327105,-0.434698,-0.118896,0.182046,-0.088884,-0.734774,-0.017511,-0.054415,-0.141869,-0.529937,0.690548,-0.314984,0.284948,0.016068,-0.041350,0.423168,0.458589,0.300753,0.177110,-0.153862,-0.063433,-0.726468,0.071964,0.832796,-0.271121,-0.223979,0.001027,-0.120490,-0.361426,0.047913,-0.332211,-0.053340,-0.094402,0.446706,-0.215457,-0.248362,0.053558,-0.555707,-0.285844,-0.640349,-0.268319,-0.123647,-0.489868,-0.149561,-0.479665,-0.126559,-0.018703,-0.224890,0.126939,0.075552,0.117600,0.437811,-0.411150,0.030776,0.756648,0.239106,-0.614627,0.436388,0.038570,0.236027,0.219582,0.036439,0.065095,0.512862,0.702478,0.362910,0.106550,-0.023762,-0.476546,-0.105256,0.185569', '1309116', '1294941', '1292584', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306444', '哈特的战争', '剧情', '1944年，盟军已经登陆欧洲对纳粹展开反攻，在耶鲁学习法律的汤姆·哈特（柯林·法瑞尔 Colin Farrell 饰）由参议院父亲的安排下进入部队担任驻扎后方的中尉，一次护送任务中，哈特不幸被俘，被纳粹送往集中营中关押。在集中营里，出身军官世家的威廉·麦克纳马拉上校（布鲁斯·威利斯 Bruce Willis 饰）担任俘虏们的领导，他将可能出卖了盟军情报的哈特分配到士兵营房，又将两名黑人飞行员指派给哈特照顾，集中营中充斥种族歧视的气氛，哈特不得不尽力避免黑人飞行员遭受同袍的伤害，然而一名飞行员还是死于陷害，而剩下的另一名飞行员则卷入了谋杀，哈特决定为黑人辩护，向集中营中的歧视宣战……©豆瓣', '布鲁斯·威利斯', '格里高利·霍布里特', 7.5, 8693, 'tt0251114', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p958886709.jpg', 0.4, 2.8, 33.7, 48.4, 14.7, '0.285088,-0.298126,-0.487758,0.633546,-0.234457,-0.222707,0.712931,-0.078457,-0.407573,-0.246834,0.652080,0.700969,0.359089,0.045286,0.836363,-0.092265,-0.514863,-0.836023,-0.473915,-0.328996,-0.466445,-0.736545,-0.336338,-0.554395,0.003982,-0.582983,0.713039,0.007371,-0.298765,0.450160,0.143169,0.754744,-0.003381,0.284200,0.303742,-0.036204,0.550058,-0.738655,-0.264836,0.286338,-0.265179,-0.363429,-0.070985,-0.128384,0.332325,0.535098,0.734028,-0.426101,0.241413,-0.421872,-0.040464,-0.500450,0.040864,0.295863,0.444306,0.252537,0.012279,0.320400,-0.071894,0.286515,-0.156245,0.070680,-0.619071,-0.087468,0.070644,0.149528,-0.612555,0.352213,-0.345969,0.347606,0.099859,-0.043398,0.062879,0.240787,0.010336,0.564275,-0.110488,0.197716,-0.399742,0.048160,0.602953,-0.403413,-0.208427,-0.618130,-0.134629,-0.300282,0.377803,-0.196250,-0.330655,-0.340269,0.118613,-0.206707,0.161520,0.370331,-0.490788,-0.187650,-0.697964,-0.585859,-0.281004,-0.192298,-0.029198,-0.831282,0.103632,0.143448,-0.118163,0.258027,0.186744,0.235999,0.752634,-0.499124,0.239477,0.484556,0.423119,-0.482384,0.390569,0.335929,0.497146,0.029572,-0.144279,0.351105,0.494795,0.408141,0.123580,0.213052,-0.301470,-0.597844,-0.154647,-0.027942', '10467125', '1865012', '1293537', '26367579');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306449', '怒火青春', '剧情', '影片以1993年在巴黎18区发生的一起警察暴力的真实事件为背景：一名警察在巡逻期间枪杀了一名17岁的扎伊尔少年Makomé M''Bowolé。而在影片当中，巴黎街头，一群反政府青年。纠纷由其中一人被警察殴打重伤而起，众人怀恨在心。文兹（文森特·卡塞尔 Vincent Cassel饰）弄到一把真枪，决心还以颜色。他们的仇恨与愤怒随处可见，这场与警察之间的大规模冲突，一触即发。混战中，文兹被警察开枪打死，他的同党也颤抖着对准了警察的头，枪声响起……无论是警察还是街头混混，每个人都失去了控制。这青春期里的不安与躁动，就像失控的怒火一般，无人幸免。 导演马修·卡索维茨荣获第48届戛纳电影节(1995)主竞赛单元最佳导演奖。©豆瓣', '文森特·卡索', '马修·卡索维茨', 8.2, 15939, 'tt0113247', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494416659.jpg', 0.5, 2, 16.9, 47.6, 33, '0.300669,-0.174647,-0.750650,0.307100,0.115847,-0.093132,1.064304,-0.035545,-0.384287,0.045543,0.462339,0.620811,-0.375068,0.252130,0.537769,-0.344103,-0.363213,-1.082113,-0.233667,-0.029548,-0.168657,-0.119306,-0.201666,-0.187188,-0.205522,-0.285142,0.492917,0.082655,-0.279847,0.593720,0.655858,0.247646,-0.285476,0.333219,0.079556,-0.129964,0.231938,-0.410427,-0.197473,0.163701,-0.187544,-0.426049,-0.142195,0.046958,-0.083640,0.472386,0.705093,-0.221326,0.039561,0.014563,0.271576,-0.366693,-0.307488,0.349140,0.615354,0.012121,0.107321,-0.110703,0.031617,0.071399,-0.014697,0.108143,-0.417988,0.164225,-0.071552,0.380303,-0.581635,0.376233,-0.048025,0.167563,0.021205,0.169921,0.164807,0.106438,0.066488,0.247096,-0.259931,-0.405964,-0.468438,0.085301,0.742628,-0.051329,-0.406335,-0.244680,-0.269053,-0.472736,-0.193186,-0.374588,-0.462388,-0.069247,0.576741,-0.386946,-0.201760,0.300248,-0.394475,0.031574,-0.039992,-0.158635,-0.497702,-0.029332,-0.139768,-0.778094,0.098887,-0.175443,-0.173181,0.172780,0.168845,0.030059,0.508473,-0.611169,0.133883,0.590828,0.251973,-0.144705,0.275760,0.003688,0.162365,-0.034560,-0.518624,-0.158003,0.197718,0.439109,0.179792,0.457755,-0.325878,-0.242361,-0.063596,0.111054', '10466639', '1301686', '1316693', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306450', '童梦失魂夜', '科幻', '故事发生在一个雾气氤氲的奇幻城市中，怪博士格勒（丹尼尔·埃米尔福克 Daniel Emilfork 饰）因无法做梦而饱受折磨，痛苦的他唯有指示手下的克隆人（多米尼克·皮诺 Dominique Pinon 饰）绑架城中的孩童，通过一个怪异的机器来窃取他们的梦境。可是，所有的美梦到了他这儿，均变成了噩梦。阿一（朗·普尔曼 Ron Perlman 饰）天生巨大强壮，一日，相依为命的弟弟被怪博士掳走，善良的他为了救回弟弟，联手孤儿偷窃团的成员美蒂（嘉蒂斯·维泰特 Judith Vittet 饰），同怪博士展开了一场斗智斗勇的殊死搏斗。导演让-皮埃尔·热内 （Jean-Pierre Jeunet）用他一贯天马行空的想象力，为我们构筑了一个正邪混杂但善良不灭的华丽梦境。©豆瓣', '朗·普尔曼', '马克·卡罗', 7.9, 10254, 'tt0112682', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p660534785.jpg', 0.8, 3.4, 23.6, 45.5, 26.8, '0.252290,0.019338,-0.585940,0.598095,-0.246800,-0.367603,0.865301,0.123170,-0.447520,-0.270153,0.276318,0.602791,-0.081930,0.018315,0.160189,0.134764,-0.104090,-0.545294,-0.199505,-0.062296,-0.145750,-0.500704,-0.165106,-0.141377,0.126858,-0.423896,0.416166,0.030479,0.071001,0.288354,0.279600,0.461493,-0.200673,0.097417,0.046033,0.042097,0.087949,-0.118014,-0.102397,-0.121880,-0.221860,0.156517,0.081242,0.192627,-0.242951,0.224719,0.845059,-0.490738,0.091761,-0.400672,0.334199,-0.351197,-0.052409,0.080016,0.118267,0.016329,0.040689,0.035644,-0.133602,-0.185733,0.098246,0.063235,-0.870313,-0.125513,0.273197,0.150611,-0.378850,0.349352,0.112622,0.008144,0.105471,-0.082741,0.071455,0.167756,0.409100,0.478631,-0.016639,-0.045876,-0.523611,0.252885,0.572612,-0.186085,-0.419000,0.315362,-0.392883,-0.025020,0.039229,-0.385817,-0.580056,0.027560,0.146206,-0.363710,-0.271120,0.451579,-0.680536,-0.212796,-0.421599,0.142545,-0.248142,-0.440839,-0.198269,-0.405067,-0.099811,-0.126894,-0.234184,0.012301,-0.043321,-0.163004,0.661561,-0.617255,0.183085,0.706288,0.124449,-0.030669,0.345177,0.103508,0.097133,-0.116356,-0.083866,0.345721,0.256482,0.134694,0.182722,0.319963,0.048973,0.099231,-0.485785,0.263459', '21619567', '2988294', '3005387', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306454', '烈焰焚币', '剧情', '内勒（莱昂纳多·斯巴拉格利亚 Leonardo Sbaraglia 饰）和安吉尔（爱德华多·诺列加 Eduardo Noriega 饰）是一对被称为“双胞胎”的暴力匪徒，形影不离的他们实际上是同性恋人的关系。两人相识于一个同性恋出没的公共厕所，内勒把无家可归的安吉尔带回家，自此二人同居，一起生活，一起作案。安吉尔患有严重的幻听，时时听到聒噪的声音，受这些声音的支配，安吉尔开始拒绝内勒的触碰。隔阂渐渐在二人之间产生，内勒知道，只要他们再合作干一桩大案，就能重新找回“双胞胎”的感觉。他们参与了一桩由一名政府官员策划的抢劫案，两人以及同伙一起打劫了银行的运钞车。抢劫过程并不顺利，安吉尔中枪，内勒把警察都杀死了，他们犯下了惊天大案。为了逃避追捕，他们带着抢来的钱，展开了逃亡之旅。本片改编自1965年发生在阿根廷的真实犯罪事件。©豆瓣', '莱昂纳多·斯巴拉格利亚', '马西路·品尼路', 8.6, 20145, 'tt0227277', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p587156828.jpg', 0.4, 1.5, 14, 36.9, 47.2, '0.695592,-0.332382,-0.595276,0.273238,-0.049367,-0.113889,0.790769,0.039348,-0.340564,-0.166950,0.107363,0.743040,-0.330289,-0.045177,0.112732,-0.106069,-0.239846,-0.912635,0.118930,-0.151992,-0.270134,-0.529298,-0.026402,-0.233056,-0.324132,-0.104567,0.239200,-0.098366,-0.208123,0.518451,0.481278,0.131039,-0.204675,0.245591,-0.154945,0.054979,0.222209,-0.011730,-0.343513,0.138044,-0.021010,-0.083738,0.064534,0.046756,0.113879,0.281750,0.617292,-0.167469,0.071707,0.025603,0.273704,-0.199334,-0.013427,0.083155,0.420400,0.053084,0.147980,0.411989,-0.385094,-0.200025,0.371222,0.117510,-0.593931,0.148105,-0.023672,0.331079,-0.297539,0.248596,0.113697,0.132695,0.124462,-0.074601,0.251716,0.696317,0.340356,0.275651,-0.002017,-0.106715,-0.553073,-0.034626,0.962190,-0.345317,-0.111947,0.098861,-0.320865,-0.317076,-0.101478,-0.171051,-0.233679,-0.024348,0.382143,-0.157076,-0.369406,0.539857,-0.500693,-0.090673,-0.174945,0.060852,-0.062590,-0.369065,0.079736,-0.726763,-0.282962,-0.373155,-0.381079,0.269197,0.063957,-0.218522,0.230957,-0.560115,0.142914,0.770046,0.295681,-0.450884,0.514899,0.156044,0.087015,-0.137301,-0.049519,0.105821,0.399750,0.117996,0.395439,0.365490,0.113226,0.126890,0.025464,0.087325', '25978126', '3147969', '11541282', '2365079');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306464', '蝴蝶的舌头', '剧情', '1936年的西班牙夏天，8岁的莫曹第一天上课便拉尿，弄得全班哄堂大笑，唯有老师安慰解难，小莫曹才可释怀。友情亦从这天开始。二人走到效外扑蝶捕虫，在日光下讲文学说自然，不亦乐乎。日光再强也挡不住政治的阴霾——西班牙内战，老师的政见政绩，顷刻成为众矢之的……', '费尔南多·费尔南·戈麦斯', '何塞·路易斯·奎尔达', 8.8, 6367, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p562145754.jpg', 0.3, 0.5, 7.8, 44.1, 47.4, '0.223275,-0.040701,-0.270307,0.221315,0.086740,-0.503787,-0.000238,0.320029,-0.184506,-0.074005,-0.048590,0.157335,-0.618435,0.494214,0.372030,-0.523146,-0.113289,-0.597112,0.287752,-0.095580,-0.117286,-0.359324,0.194269,-0.047742,-0.198153,0.034862,0.244008,0.228991,-0.129638,0.343382,0.159937,-0.157104,0.322397,0.442351,0.170981,-0.385197,-0.269273,0.448493,-0.131597,-0.091376,-0.070918,-0.656135,-0.420533,-0.229345,0.214875,0.107476,0.180952,-0.231830,0.119792,0.363366,0.586667,-0.702430,0.074870,0.175977,0.605211,-0.080483,-0.106882,-0.050201,0.117178,0.123669,-0.339441,-0.109673,0.062625,0.294442,-0.162774,-0.169293,-0.258338,0.487918,0.224714,-0.048058,-0.036221,0.019500,0.311620,0.360988,-0.092857,0.512678,-0.153115,0.374160,-0.228039,0.116536,0.459802,-0.031792,-0.226247,-0.161169,-0.031911,-0.223637,0.317235,-0.127268,0.030986,-0.243583,0.059614,-0.204852,0.198747,0.262496,-0.391170,-0.023786,0.139063,-0.155180,-0.008057,-0.307646,0.021148,-0.400851,-0.301739,-0.291570,-0.276260,0.139147,0.516958,-0.160741,0.768730,-0.584652,0.082037,-0.062944,-0.102993,-0.288014,0.521452,0.123003,0.236179,-0.092592,-0.076238,0.393326,0.172745,0.337965,0.193575,0.382644,-0.218226,-0.170563,-0.014297,0.254579', '26790961', '25922902', '1307741', '26999591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306465', '夜奔', '剧情', '1930年代，自幼在美国生活与学习的大提琴家徐少东（黄磊）返回祖国准备与素未蒙面但一直有书信往来的未婚妻英儿（刘若英）成亲。可是在随英儿在自家戏院看过昆曲《夜奔》并结识其主演林冲（尹昭德）后，徐少东的感情天平开始更多地倾斜到林冲身上，但随后有关他与林冲的流言蜚语传出，顶不住世俗压力的他最终告别英儿回到美国。二战后，英儿赴美找到徐少东，二人谈起林冲为找徐少东的悲惨经历时，徐少东明白到他的内心会一直为英儿和林冲留有位置。©豆瓣', '黄磊', '徐立功', 8.2, 27335, 'tt0259744', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551409697.jpg', 0.3, 1.9, 18.9, 47.2, 31.7, '0.371844,0.051920,-0.884198,0.433711,0.190527,-0.504498,0.722106,0.020638,-0.746759,-0.464392,0.021109,0.760358,-0.189283,0.358967,0.236988,-0.156802,-0.266786,-0.904240,-0.005594,-0.218230,-0.231122,-0.443909,0.103617,-0.060918,-0.556696,-0.295085,0.635959,-0.015220,-0.225949,0.697821,0.266445,0.039235,-0.174958,0.643557,-0.432796,0.299582,-0.180026,0.248198,-0.817247,0.266186,0.452857,-0.178169,-0.425753,-0.078973,0.050625,0.290751,0.574430,0.034527,-0.011527,0.102391,0.332909,0.089269,0.042581,0.033781,0.302749,0.296429,0.038870,0.315708,-0.176696,0.272075,-0.224455,-0.004974,-0.206237,0.159468,-0.020003,0.209250,-0.773946,0.371382,-0.001858,-0.008310,0.055580,-0.572079,0.315117,0.492917,0.181080,0.340696,-0.259634,0.157447,-0.355106,0.109467,0.973942,-0.034946,0.103393,0.289300,0.133781,-0.353036,0.109769,0.012541,-0.238402,-0.019907,0.210997,0.359869,-0.266154,0.044406,-0.435500,0.002627,0.170240,-0.073672,0.154821,-0.351692,-0.060229,-0.696672,-0.667966,-0.794597,-0.299704,0.009571,0.161603,-0.425196,0.623423,-1.033688,0.196315,0.158579,0.216498,-0.632389,0.559967,0.251594,0.112528,-0.168576,-0.000378,0.424180,-0.239165,0.107053,0.043037,0.119489,-0.179757,-0.293172,-0.357470,0.173519', '1301022', '25721544', '35030151', '1480318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306470', '生死谍变', '剧情', '金明姬是朝鲜第八特别部队的特工，自1993年潜入韩国之后，暗杀了多名政要。她的行动引起了韩国特工机构的注意，并派特工崔相焕（韩石奎 饰）和李正希（宋康浩 饰）调查她的下落，可是她却销声匿迹了。1998年，金明姬又出现了，她让黑市军火商人林光超帮忙找新武器液体炸弹CTX，林贿赂国防部研究院的研究员金宗叔帮他偷，没有得手。事情暴露后，二人先后被金明姬杀害。因为金明姬的失败，朝鲜派出了以卜万坤（崔岷植 饰）为首的特工队伍，在韩国军队运送CTX参加军火展览途中将炸弹劫走，准备破坏即将举办的两国友谊足球比赛。这一切，让崔相焕、李正希和他们的上司高部长十分苦恼，他们发现，金明姬总能先他们一步找到目标，破坏他们的行动，金明姬就在他们身边，或许正是最亲近，最不设防的那个人。©豆瓣', '韩石圭', '姜帝圭', 7.4, 13545, 'tt0192657', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505959967.jpg', 0.6, 4.1, 35.8, 43.7, 15.8, '0.280637,-0.206744,-0.705381,0.513141,-0.009712,-0.133154,0.424930,-0.029341,-0.544237,-0.290174,0.168175,0.499402,-0.027576,-0.175657,0.239904,-0.051658,-0.344252,-0.747390,-0.214827,-0.218190,-0.540329,-0.201021,-0.205081,-0.399713,0.062546,-0.117920,0.620630,0.148514,-0.389123,0.441115,0.184485,0.335183,-0.001594,0.606123,-0.061619,-0.138740,0.454030,-0.159397,-0.191215,0.252231,-0.190155,-0.514507,-0.051081,0.286112,0.092700,0.501948,0.447681,-0.034350,0.023372,-0.271910,0.149192,-0.600264,-0.005578,-0.034385,0.648739,0.076093,-0.064576,0.276147,-0.277752,0.045721,0.101787,0.045832,-0.900734,0.108378,0.124803,0.057029,-0.622791,0.199819,-0.178560,0.305048,0.086993,-0.236554,0.544600,0.652723,0.199272,-0.242460,-0.093599,-0.093552,-0.679504,0.325145,0.700507,-0.180917,0.041279,-0.045860,-0.005366,-0.635914,0.178785,-0.347154,0.086609,0.145940,0.308736,-0.123339,0.022037,-0.059604,-0.566770,-0.147221,-0.240230,-0.377477,0.037890,-0.446563,0.143532,-0.857858,-0.144364,-0.270469,-0.476398,0.177595,0.066554,0.045769,0.625792,-0.591801,-0.000276,0.797365,0.453321,-0.780242,0.504234,-0.069671,-0.023428,-0.461497,-0.079675,-0.220088,0.346401,0.480091,0.138113,0.257728,0.062882,-0.594254,-0.239945,-0.089745', '1972701', '1296947', '5157137', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306471', '八月照相馆', '剧情', '在汉城郊外，独自一人的青年余永元（韩石圭饰），经营着一家从父亲接过来的小照相馆。他时常带着微笑，坦然面对生活，照相馆里挂着不同的照片。女交警金德琳（沈银河饰）由于工作的关系，每天都要到照相馆冲洗照片，由此认识了老实的永元。有时候她会抱怨照相馆门开得太晚，显得那么天真可爱，他们一起撑伞散步，讲些琐事，日久生情，永元与德琳都发觉自己不可收拾地爱上了对方。但永元却有着难言之隐，不能直诉给德琳。季节更替，八月过去。见不到永元的德琳写信给他，塞在照相馆的门缝中。冬天的雪地里，德琳在闭门的照相馆橱柜中，见到自己的照片……©豆瓣', '韩石圭', '许秦豪', 8, 57959, 'tt0140825', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2166541466.jpg', 0.3, 1.5, 23, 48.3, 27, '0.357052,0.068382,-0.655084,0.389966,-0.004564,-0.109561,0.640139,0.420045,-0.375125,-0.209510,0.074836,0.427076,-0.264655,0.585334,0.147535,0.047298,-0.408031,-0.417207,-0.137211,-0.364790,-0.324592,-0.225450,-0.118259,-0.131086,-0.224048,0.008606,0.212693,-0.102331,-0.006255,0.587349,0.051582,-0.272941,-0.184110,0.573865,-0.231600,0.137871,-0.369578,0.238325,-0.225593,0.030267,0.278730,-0.132571,-0.529999,-0.125335,0.298542,0.408805,0.624671,0.137333,-0.045051,0.270037,0.202868,0.187334,-0.064957,0.176956,0.425674,0.161097,0.143577,0.001258,-0.316367,0.197469,0.097499,0.013269,-0.464498,0.099695,0.117832,0.432135,-0.620459,0.445287,-0.074850,-0.131615,0.257371,-0.650051,0.123272,0.157642,-0.012772,0.464648,-0.034048,0.089364,-0.904856,0.204938,0.265119,0.006752,0.018003,0.617101,-0.292398,-0.019532,-0.063227,-0.010445,-0.616040,-0.111517,0.089363,-0.266066,-0.352932,0.016710,-0.539872,0.030607,0.187233,0.024814,0.002228,-0.000048,-0.415464,-0.499162,-0.074093,-0.776492,-0.333992,0.186068,-0.149496,0.000902,0.408228,-0.623529,0.126958,0.457769,0.474516,-0.078025,0.852812,0.308713,0.087234,-0.028583,-0.179810,0.085755,0.096002,0.444263,0.245004,0.406722,-0.205457,-0.241582,-0.536566,0.345258', '3055049', '1323746', '25876760', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306472', '晚餐游戏', '喜剧', '一班自命不凡、高人一等的狐朋狗友，相约星期三晚举行“白痴晚宴”。规则非常简单，即是各人只须携一名“白痴之最”共赴晚餐，便能获得丰富奖品。参与者之一皮埃尔（蒂埃里·莱尔米特 Thierry Lhermitte饰）打算带着新认识的皮侬（雅克·维列雷 Jacques Villeret饰）赴宴。皮埃尔本以为这个看似傻里傻气的皮侬，一定是最佳人选。然而他的如意算盘却完全落空，皮侬把关系颠倒了过来，反而让皮埃尔变成了被整的对象。于是，一场笑料百出的乌龙事情接踵发生。这部由法兰西斯·威柏编剧执导的喜剧电影《晚餐游戏》，改编自他写于1993年的舞台剧《假凤虚凰》。一波三折的喜剧情节和极具颠覆性的疯狂笑料，使得本片叫好又叫座。一举拿下1999年第24届凯撒奖，最佳男演员、最佳男配角和最佳剧本(原创或改编)大奖。©豆瓣', '蒂埃里·莱尔米特', '弗朗西斯·韦贝尔', 7.9, 8166, 'tt0119038', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553523153.jpg', 0.6, 2.4, 23.9, 49.1, 24, '0.185048,-0.123562,-0.475574,0.417027,0.148823,-0.102238,0.289843,0.066340,-0.185426,-0.177767,0.010391,0.649862,-0.671287,-0.182043,0.608109,-0.344607,-0.306668,-0.683668,-0.098781,-0.143466,0.223931,-0.288162,-0.252062,0.157457,-0.064668,-0.073194,0.434094,-0.040488,0.029009,0.378839,0.744610,0.179311,0.056733,0.106663,0.213841,0.018256,0.085286,-0.112997,-0.301860,0.358362,0.017232,-0.193955,-0.288048,0.105388,0.058851,0.264244,0.530088,-0.284266,0.075137,0.128423,0.520413,-0.339634,-0.149195,0.015813,-0.046907,0.101226,0.292913,0.202927,0.019769,0.260307,0.137513,-0.404428,-0.860286,0.175309,0.144948,0.057731,-0.221141,0.317832,-0.138627,0.012923,-0.076325,-0.066044,0.211956,0.160114,0.802635,0.244850,0.228624,-0.111931,-0.398829,0.401473,0.395409,0.221669,-0.273472,0.368458,0.030483,-0.380799,0.253309,-0.394429,-0.282028,0.277134,0.450779,-0.020984,0.263181,0.094747,-0.528909,-0.330822,-0.150832,-0.318615,0.077364,-0.309278,0.037689,-0.617648,-0.091801,-0.106616,-0.052381,-0.263198,0.311378,-0.400435,0.543847,-0.661767,0.131260,0.306455,-0.149128,-0.345850,0.385897,0.202909,0.124527,-0.131039,-0.221652,-0.163880,0.008122,-0.017432,0.024067,0.329397,0.114623,-0.428792,-0.404050,0.433905', '3318306', '4301278', '27073234', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306490', '侠女', '剧情', '没落书生顾省斋（石隽 饰）在小镇经营字画铺“代写书信春联”过活，奉养家中老母，偶然结识了家附近废屯堡新搬来的杨之云（徐枫 饰），与其暗生情愫。恰逢东厂人士欧阳年（田鹏 饰）前来打探，其与附近算命瞎子（白鹰 饰）动手，被顾生与其母遇见，遂将受伤的算命瞎子就近带到杨之云处， 从而得知他们的真正身份——因弹劾宦官魏忠贤而被杖毙的左副都御史杨涟之女杨慧贞；保卫忠良之后的石门樵将军。因二人都被朝廷通缉，东厂追杀，顾生就此在屯堡设下重重计谋，又得高僧慧圆（乔宏 饰）帮助，以期摆脱东厂追兵，逃出生天。电影根据蒲松龄《聊斋志异》中《侠女》一篇改编。©豆瓣', '徐枫', '胡金铨', 8.6, 25338, 'tt0064451', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2249959791.jpg', 0.3, 1.1, 11.3, 43.7, 43.6, '0.177307,-0.025529,-0.077883,0.315013,0.020773,0.032974,0.130303,0.301930,-0.606555,-0.495807,0.355258,0.350508,-0.044674,0.088600,0.054084,-0.241824,-0.034514,-0.524984,0.000858,-0.278922,-0.083527,-0.068293,-0.131821,-0.057442,-0.367668,-0.039512,0.291664,0.072791,-0.117255,0.401226,0.070051,0.461647,-0.592974,0.076819,-0.176146,0.281350,-0.050424,-0.257459,-0.220565,0.029214,-0.220383,-0.672482,-0.128499,-0.235031,-0.047236,0.200741,0.819033,-0.215724,-0.024561,-0.267465,0.199052,0.092829,0.106961,0.245918,0.321325,0.250879,0.128550,0.347909,-0.250006,-0.086511,0.026458,0.005512,-0.038954,0.055178,0.328639,-0.035041,-0.397415,0.186545,-0.184314,-0.012655,-0.390219,-0.361925,0.356691,0.201528,0.111760,0.184179,0.105932,-0.104170,-0.545722,0.370732,0.250885,-0.070433,0.306047,-0.325782,0.339836,-0.170740,0.466940,-0.204171,-0.062911,0.059432,0.598396,-0.159375,0.035359,-0.080783,-0.363039,-0.136073,-0.429153,0.497611,0.199881,-0.127824,0.025220,-0.662733,-0.125633,0.132471,-0.091209,-0.127080,0.368493,-0.133436,0.262894,-0.328857,0.108457,0.137145,0.047385,-0.672145,0.511517,-0.160662,0.182044,-0.003291,-0.043997,-0.099777,0.487134,0.492840,0.086024,-0.010712,-0.177233,-0.368203,-0.001417,0.083661', '4881604', '1301257', '1302654', '1294011');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306505', '红高粱', '剧情', '该片改编自莫言1986年发表的两部中篇小说《红高粱》和《高粱酒》。因为一匹骡子，“ 我奶奶”九儿（巩俐饰）的父母要她嫁给一位拥有一座酒坊的50岁麻风病人。九儿乘坐花轿出嫁时，在途中被一名强盗拦截。其中一名抬轿男子余占鳌（姜文饰）打退了强盗，九儿因而和他开始相互喜欢。3天后九儿回乡探望父母 。抬轿男子突然从高粱田里冲出来，抢走了九儿。他们在高粱田野外交合。九儿回到酒坊的时候发现麻风病的丈夫死了，“ 我奶奶”撑起李家的烧酒作坊，不久余占鳌正式成为 “我爷爷”，并独创酿制好酒十八红的方法。抗日战争期间，“我爷爷”和“我奶奶”连手谱写了一曲悲歌。©豆瓣', '巩俐', '张艺谋', 8.5, 243245, 'tt0093206', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2585499261.jpg', 0.2, 0.7, 11.8, 50.4, 36.9, '0.066413,-0.184831,-0.356157,0.295201,-0.039487,-0.436423,0.489486,0.170657,-0.436563,-0.222853,0.197582,0.671017,0.086893,0.389781,0.213698,0.117297,0.085299,-0.348326,0.272236,0.098586,-0.232903,0.094484,0.213451,-0.153669,-0.002841,-0.148772,0.349707,-0.110650,0.029189,0.436276,0.077430,-0.056728,-0.024286,0.143970,-0.295156,0.392391,-0.031957,-0.213300,-0.180308,0.366626,-0.282853,-0.268272,-0.233176,-0.330979,0.051232,0.222876,0.709253,-0.113184,-0.010131,-0.257752,0.232566,0.018426,0.131437,0.119566,0.198108,-0.127333,0.107528,0.317973,-0.232360,0.011515,-0.210042,-0.131229,-0.071874,0.133640,0.052334,-0.288469,-0.897995,0.410045,-0.020693,0.145576,0.128801,-0.286185,0.265404,0.277417,-0.229954,0.356120,-0.144059,0.002808,-0.735943,0.441169,0.685468,-0.153566,0.377890,0.105457,0.162093,-0.324221,0.099654,-0.018555,-0.305742,0.031038,0.344196,-0.098466,-0.075613,-0.150253,-0.492842,-0.184621,0.053325,-0.085671,0.309922,0.090190,-0.218711,-0.052727,0.021609,-0.196947,-0.014860,-0.047029,0.148088,-0.054823,0.551599,-0.252427,0.232805,0.028329,0.209884,-0.369004,0.695515,-0.033245,0.027245,-0.279007,-0.096210,-0.122077,-0.001044,0.109772,0.381775,0.252029,-0.046568,0.199409,-0.216487,0.248234', '2080130', '25731805', '1297606', '30206431');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306506', '阿Q正传', '剧情', '身形猥琐、其貌不扬的阿Q（严顺开 饰）是未庄一个靠打短工度日的小人物。他家徒四壁，穷得连姓都没有。虽然如此，阿Q却始终自我感觉良好，或瞧不起装模作样的假洋鬼子，或与地主赵太爷攀亲。当然换来的往往不是尊敬，而是鄙夷甚至一顿毒打。好在阿Q有着一套自我安慰的“精神胜利法”，所以肉体上吃亏的他最终能在精神上得到满足。自从被赵太爷打和调戏吴妈受罚之后，阿Q的日子愈加难过。万般无奈之下，他只得进城谋求生路。阴差阳错的一些事，竟让阿Q在未庄人眼里成了手握重权的革命党，这个憋屈半辈子的小人物总算暂时抖了起来……根据鲁迅同名小说改编，并荣获瑞士第2届国际喜剧电影节最佳男演员奖。©豆瓣', '严顺开', '岑范', 8.7, 31429, 'tt0081971', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2182153100.jpg', 0.1, 0.5, 9.5, 42.9, 47, '0.149784,0.091294,-0.550586,0.716536,-0.058848,-0.525755,0.367342,0.104813,-0.511564,-0.308773,0.051951,0.552586,-0.158418,0.231890,-0.288074,-0.450413,-0.035116,-0.429436,-0.018965,0.069958,0.041076,-0.353242,-0.292915,-0.142897,-0.464681,-0.082322,0.439747,0.181952,-0.264373,0.444006,0.628730,0.192934,0.373042,0.403374,-0.374535,-0.020028,-0.076849,0.114133,-0.298503,-0.022279,0.257181,-0.363944,-0.115303,0.156287,0.180504,0.401697,0.405906,-0.198439,-0.318898,0.065740,0.431283,-0.278562,-0.304048,0.185064,0.163202,-0.308739,0.287128,-0.062859,-0.030424,0.197968,0.283820,0.123718,-0.810741,-0.108576,0.255067,0.038004,-0.513611,0.453236,0.013133,0.019952,-0.226997,-0.196236,0.219291,0.083857,0.253290,0.333975,-0.317003,0.188337,-0.506561,0.503762,0.394090,0.214775,-0.371152,0.198322,-0.298384,-0.372091,0.301466,-0.618903,-0.298830,-0.049850,0.270550,-0.089326,-0.052167,0.170110,-0.276745,-0.124111,0.094109,0.088244,0.043875,-0.678489,0.033983,-0.264697,0.000763,-0.390521,-0.165143,0.058811,0.230750,-0.369504,0.497324,-0.579130,0.062262,0.161668,0.110168,-0.533045,0.477866,0.404987,0.088291,0.150544,-0.258625,0.002430,0.008650,0.137278,0.316506,0.189758,-0.112108,-0.242026,0.024892,0.598316', '3670447', '3318473', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306512', '亚特兰蒂斯之心', '剧情', '在父亲去世后，鲍比（安东·尤金 Anton Yelchin 饰）觉得自己不会再快乐了，尤其是11岁生日那天，他那刻薄而又小气的母亲居然只给了他一张免费的图书卡作为礼物的那一刻。但自从那个名叫泰德（安东尼·霍普金斯 Anthony Hopkins 饰）房客出现在了他的生命中后，一切开始变得不同起来。泰德租下了鲍比家的阁楼，整天躲在里面，不知道在捣鼓什么东西。他雇佣鲍比为他读报，报酬是一星期一美分。母亲告诫鲍比离这个奇怪的老头远一点，但鲍比并不当做一回事，因为在鲍比那里，他找到了久违的快乐和信任，泰德不仅让他得到了友情，还给予了鲍比一个人的成长中不可或缺的珍贵品质。©豆瓣', '安东尼·霍普金斯', '斯科特·希克斯', 8.1, 8368, 'tt0252501', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1420011408.jpg', 0.3, 1.3, 19.3, 49.7, 29.5, '0.434699,0.085912,-0.901285,0.625753,-0.506270,-0.570111,0.942235,0.133567,-0.430544,-0.220120,-0.018617,1.051185,-0.004166,0.284049,0.029029,0.514483,-0.147708,-0.395618,0.117555,-0.287629,-0.226038,-0.671666,-0.245035,-0.423855,-0.060720,-0.364595,0.176792,0.050760,0.103371,0.404491,0.391549,-0.069465,0.377753,0.554084,-0.307055,0.209462,0.207238,0.047276,0.000550,0.214754,0.076589,-0.189977,-0.050710,0.510295,0.146359,0.451559,0.409095,-0.159881,-0.405509,0.161476,0.353041,-0.185674,-0.088466,0.100832,0.187115,-0.105667,0.285350,0.098052,-0.432057,0.160947,0.022000,-0.133501,-0.777218,-0.049344,-0.124371,0.201527,-0.689307,0.581215,-0.263242,-0.098799,0.093437,-0.431999,0.355619,0.243714,-0.039639,0.442271,-0.351295,-0.258374,-0.603793,0.196369,0.693440,-0.248309,-0.140803,0.601363,-0.315332,-0.355941,-0.107295,-0.054357,-0.545657,0.014555,0.205176,0.113770,-0.138607,-0.070871,-0.447217,0.123660,-0.034461,-0.183312,-0.086509,-0.469994,-0.283848,0.016826,-0.073914,-0.451628,-0.516207,-0.041921,0.012493,-0.564846,0.729763,-0.901208,0.292896,0.531183,0.263146,-0.417895,0.651487,0.280231,0.033586,-0.097690,0.024395,-0.030445,0.173627,0.077237,0.240853,0.347020,0.274106,-0.134610,-0.280796,0.783386', '1783461', '1481233', '3230121', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306513', '终极细胞战', '喜剧', '弗兰克（比尔·默瑞 Bill Murray 饰）是一个普通的动物园管理人，某一天，他误食了一枚被猴子啃过的苹果，一种名叫瑞克斯（劳伦斯·菲什伯恩 Laurence Fishburne 配音）的病毒就这样来到了弗兰克的体内。同样是在这里，存在着一只名为奥兹（克里斯·洛克 Chris Rock 配音）的白血球，这是一只特立独行的白血球，它并不满足于平庸的日常，而是想要活出精彩，活出新意。奥兹的死对头是一枚名叫德雷克斯（大卫·海德·皮尔斯 David Hyde Pierce 饰）的感冒药片，它的存在就是为了制约不守规矩的奥兹，两人之间的关系很是紧张。然而，当瑞克斯出现在它们面前时，一切都改变了，奥兹和德雷克斯必须联起手来，才能保护弗兰克的健康不受到破坏。©豆瓣', '克里斯·洛克', '博比·法雷里', 8, 8219, 'tt0181739', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1453955007.jpg', 0.2, 1.1, 21, 54.1, 23.7, '0.621083,0.066988,-0.514033,0.493693,-0.209924,-0.463103,0.841261,0.130847,-0.215888,-0.308920,0.143029,0.654937,-0.199061,-0.081202,-0.069124,0.286944,-0.141035,-0.417833,-0.155485,-0.135179,-0.227787,-0.457365,-0.525081,-0.334389,-0.122994,-0.300081,0.558845,-0.122987,-0.157968,0.217420,0.248937,0.421903,0.319834,0.187207,-0.161826,-0.044793,-0.031385,-0.306452,0.017554,0.258162,0.084398,0.167897,0.078647,0.269205,0.115492,0.193366,0.366286,-0.433794,-0.099852,-0.283022,0.201595,-0.168965,0.079813,0.150661,0.221607,-0.287913,0.126544,-0.045425,-0.288932,0.229836,0.283380,-0.215425,-1.018495,-0.144329,-0.152895,0.714484,-0.409968,0.411430,-0.132368,-0.352656,0.046368,-0.371566,0.273589,0.345680,0.360739,0.432214,-0.115842,-0.059794,-0.557439,-0.149429,0.622981,0.123967,-0.477840,0.312806,-0.482370,-0.506558,-0.172713,-0.149672,-0.481639,0.004296,0.326745,0.121213,-0.108148,0.288098,-0.704771,0.103413,-0.252001,-0.101048,-0.166033,-0.360644,0.046331,-0.474078,0.094698,-0.437754,-0.415518,-0.014147,0.053688,-0.425117,0.564384,-0.787990,0.270920,0.637578,0.081984,0.106668,0.422854,0.030083,-0.016086,-0.171473,-0.085430,0.310906,0.349286,0.071708,0.173051,0.556662,0.442851,-0.023161,-0.102582,0.644478', '1793491', '1874704', '1308784', '3569911');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306518', '绿芥刑警', '喜剧', '警察埃布尔（让·雷诺 Jean Reno饰）一贯以英勇无畏、雷厉风行的形象呈于人前，他对待犯人的手段几近残忍，从不手软。可是硬汉的内心却隐藏了一段尘封已久的情伤——19年前，他的日本女友蜜子不告而别，埃布尔整整思念女友19年，不曾移情。某天，蜜子已逝的消息传来，而埃布尔成为爱人全部遗产的继承人，遗嘱的唯一要求是照顾女儿由美至成年。还没等埃布尔从震惊中回过神来，眼前已跳出一个吵吵闹闹、衣着怪异且出言不逊的十足“小太妹”，她就是由美（広末涼子饰）。埃布尔无意中发现蜜子的死因有蹊跷，而由美的银行账户上竟有2亿美元的巨额存款，由美也被黑道暗中盯梢，重重疑窦中，埃布尔开始探索真相。©豆瓣', '让·雷诺', '热拉尔·克瓦兹克', 7.1, 29920, 'tt0281364', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p823947361.jpg', 0.7, 5.4, 43.4, 37.6, 12.8, '0.054996,0.182778,-0.606280,0.445607,-0.266269,-0.319066,0.735531,-0.179716,-0.688322,-0.412641,0.163866,0.484587,-0.154609,0.361350,0.268238,0.287406,-0.111505,-0.699424,-0.376031,-0.297521,-0.217063,-0.254453,-0.258263,-0.197560,-0.201050,-0.192062,0.423565,0.065588,-0.096005,0.253577,0.383099,0.370652,-0.122083,0.426055,-0.040962,-0.069768,0.139807,0.169106,-0.029728,-0.132848,-0.127471,-0.455380,-0.155921,0.299212,-0.247325,0.607306,0.426706,-0.170198,-0.292422,-0.025460,0.421356,-0.162283,-0.224198,0.098262,0.262767,0.001237,0.204405,0.068125,-0.235130,-0.298046,0.001592,-0.026410,-0.558104,-0.057115,-0.184577,0.202270,-0.284631,0.229907,-0.365968,0.222795,0.105755,-0.231555,0.001218,-0.090506,0.245624,0.306030,-0.247989,0.129290,-0.279043,0.116186,0.246062,0.045347,-0.385522,0.176012,-0.184506,-0.422471,0.249989,-0.336984,-0.343425,-0.002475,0.180780,0.057995,-0.088111,0.255031,-0.256524,-0.107161,-0.423741,0.021044,-0.035368,-0.255845,-0.394510,-0.260526,-0.478041,-0.443573,-0.370528,0.145384,0.253448,-0.165191,0.685170,-0.619271,0.278135,0.358229,-0.006486,-0.422926,0.457220,0.074568,-0.183296,-0.085902,-0.016102,0.263605,0.037791,0.011960,0.038201,0.099243,-0.131487,-0.299977,-0.174544,0.267903', '3263169', '1301022', '1309297', '1308745');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306523', '赤桥下的暖流', '剧情', '笹野阳介（役所广司）被公司裁员裁掉后又被妻子抛弃，只得流浪街头，通过一位流浪老人之口，他来到遥远偏僻的能登半岛一幢位于河边赤桥下的房子，想找寻老人所说的藏有金佛的盒子，但没能如愿以偿，只遇见体质相当特殊的佐惠子（清水美砂）。佐惠子的特殊在于，当她与男性交合时，体内会分泌出神奇的“暖水”，该“暖水”能令过季的花儿盛开、能把大海的鱼群召到河里。而更重要的，是沐浴在佐惠子“暖水”下的男人，会重拾失去的信心和活力。如此，笹野阳介与佐惠子开始了一次次的交合。©豆瓣', '役所广司', '今村昌平', 6.8, 7970, 'tt0289054', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1370035484.jpg', 1.6, 8.7, 47.5, 33, 9.2, '0.161072,0.012987,-0.565661,0.426743,0.120884,-0.184863,0.754587,0.373777,-0.427836,-0.023401,0.131894,0.748586,0.036243,0.318344,0.188945,0.359272,0.072991,-0.578563,-0.328213,-0.051850,-0.408492,-0.496432,-0.193281,-0.004095,-0.127248,-0.427830,0.622975,0.195161,-0.179327,0.188517,0.106092,0.430301,-0.105740,0.381468,-0.333189,0.051999,-0.123266,0.149608,-0.038867,0.223691,0.073438,-0.331850,-0.052621,0.021336,0.182662,0.146136,0.820687,-0.105833,-0.269008,-0.043131,0.452903,-0.136139,0.030877,0.178679,0.299210,-0.174961,0.181682,0.126389,-0.331344,-0.277490,0.205408,-0.030483,-0.580354,-0.133523,0.148090,0.081853,-0.451118,0.068805,0.268586,-0.192418,0.407764,-0.535919,0.276255,0.187351,0.110360,0.393773,-0.227016,-0.176515,-0.529430,0.111111,0.700193,-0.083869,-0.033317,0.413709,-0.265086,-0.436181,-0.013649,-0.196008,-0.277479,0.065569,0.444883,0.321015,-0.247377,-0.054537,-0.614531,-0.080330,-0.343313,-0.058616,0.196367,-0.044693,-0.307667,-0.332758,-0.173561,-0.341194,-0.274829,0.313000,-0.023319,-0.209821,0.803123,-0.900473,0.089402,0.781615,0.167889,-0.165970,0.568620,-0.118259,-0.004245,-0.016503,0.001040,0.396019,-0.049606,0.481298,0.026238,0.636658,-0.099174,0.177381,-0.671578,0.058578', '3811356', '3005387', '3044878', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306524', '儿子的房间', '剧情', '伊凡尼（南尼·莫莱蒂 Nanni Moretti 饰）有一个和睦温暖的家庭，儿子安德烈和女儿艾琳更是让这个家庭乐也融融。而伊凡尼身为心理医生，常常接触到各式各样的心理病患者，从而更加珍惜目前的生活。然而生活的残酷随之而来，在一个看上去平常的早晨，却传来了一个令这个家庭为之崩溃的消息——儿子在潜水运动中遇上不测，不幸身亡。伊凡尼一家顿时陷入了一篇黑暗当中，母亲终日以泪洗脸，姐姐艾琳压抑着痛苦照顾悲伤的父母，而父亲，更是因为过度悲痛而不能继续工作。而儿子空空如也的房间，深深刺痛了每个家人的心。远方寄来一个女孩子的来信，来信成全了家人对儿子的追思，并令到这个家庭重新有了一丝生机。然而逝者如斯，各人内心的伤痛，只有时间能慢慢治疗。©豆瓣', '南尼·莫莱蒂', '南尼·莫莱蒂', 7.9, 8807, 'tt0208990', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2262756726.jpg', 0.4, 1.4, 23.9, 53.1, 21.2, '0.024345,0.075474,-0.732211,0.665532,0.036926,-0.550729,0.923868,0.449143,-0.581303,-0.402413,0.053297,0.676780,0.092440,0.681170,0.195601,-0.117420,-0.158258,-0.475381,-0.124665,-0.038323,-0.422393,-0.308386,0.072289,-0.465062,-0.147294,-0.429943,0.516224,0.133796,0.085125,0.469569,-0.045941,0.397366,0.203388,0.675982,-0.093076,0.032752,0.001755,-0.106202,-0.296284,0.000068,0.500165,-0.030938,-0.162722,0.423474,-0.194219,0.418311,0.855224,-0.166786,-0.246649,-0.065029,0.535637,-0.020555,-0.054349,0.089040,-0.114063,-0.086825,0.145171,-0.059710,-0.441696,0.072534,0.118491,-0.009520,-0.687999,-0.082831,0.110862,0.205786,-0.320377,0.271544,-0.116505,-0.129158,0.143060,-0.267168,0.334247,0.291505,-0.041021,0.725732,-0.703740,0.184764,-0.338073,-0.021826,0.723235,-0.200248,-0.143023,0.533295,-0.638651,-0.231622,0.248383,-0.152711,-0.799852,-0.099208,0.223947,0.115242,-0.233050,0.524051,-0.507880,-0.020106,-0.306799,-0.227850,-0.050507,-0.452017,-0.102192,-0.252308,-0.347825,-0.164878,-0.367411,0.075317,0.160326,-0.190805,0.891703,-0.720229,0.279043,0.425977,-0.060484,-0.521985,0.560582,0.212156,0.286962,-0.061959,0.061036,0.607040,0.015045,0.152084,-0.053651,0.168956,-0.200982,0.206736,-0.468136,0.649523', '10533913', '26348103', '25882279', '4724586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306526', '触不到的恋人', '爱情', '韩星贤（李政宰饰）搬到一个海边小屋，他为房屋取了一个意大利文的名字“Il Mare”，意思是“海”。整理房子时，他在信箱发现了一封内容很奇怪的信，信上写着“我是你搬来前的上一个房客，如果有收到我的信，请寄来”，更奇怪的是这封信寄出的日期是在1999年，也就是两年后——而星贤现在的时间是在1997年。星贤就立刻回信给这莫名其妙的人，询问是怎么回事。1999年的金恩珠（全智贤饰）是个配音员，她发现回信的内容后，就开始常常写信给两年以前的星贤。男朋友去美国后已很少和她联络，后来他从美国回来，却已订婚。心碎的恩珠写信给星贤，拜托星贤到当年她和男友最后见面的那一天，去改变他们的命运，但星贤觉得很痛苦，因为他已爱上了恩珠……©豆瓣', '全智贤', '李铉升', 7.9, 86063, 'tt0282599', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p701320928.jpg', 0.2, 1.7, 24.5, 50.2, 23.3, '0.272125,0.052104,-0.665315,0.608600,-0.141712,-0.348547,0.756050,-0.131883,-0.600253,-0.283626,-0.193700,0.697331,-0.168193,0.450381,0.129454,0.361923,-0.425150,-0.487363,0.055690,-0.614079,-0.552061,-0.385566,-0.047075,-0.168616,0.251451,-0.227704,0.138212,-0.007023,-0.052337,0.469205,0.330694,-0.056736,0.137689,0.653254,-0.413406,0.245535,-0.253733,0.259222,0.188101,0.093896,0.211224,-0.389547,-0.233478,0.264251,0.128147,0.561462,0.524159,0.205782,-0.418880,0.381381,0.488748,-0.095031,-0.132379,0.031761,0.422652,-0.008899,0.122918,0.267035,-0.529158,-0.102155,-0.261500,-0.026418,-0.677041,0.124168,-0.115083,0.260350,-0.672349,0.699179,-0.357450,0.112115,-0.122916,-0.713998,0.277143,0.494469,-0.131908,0.375687,-0.034204,-0.213079,-0.522161,0.355740,0.733180,-0.145816,0.179373,0.561364,0.106580,-0.463302,-0.035925,0.208929,-0.413291,0.322525,0.149283,0.035454,-0.392763,-0.441646,-0.648700,-0.186665,-0.126029,-0.266419,0.136480,-0.620575,-0.120874,-0.103009,-0.186441,-0.374630,-0.540534,0.050703,0.104715,-0.249409,0.678892,-0.607081,0.346934,0.568291,0.245872,-0.465764,0.901039,0.248792,-0.308463,-0.132020,0.379534,-0.117345,0.198177,0.433943,0.252914,0.344599,0.372058,-0.324300,-0.565488,0.620548', '3055049', '1783772', '2990737', '1294364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306530', '企业战士', '剧情', 'Yamakasi是由七个年轻人组成的. 他们每个人都有一项特异能力：冲刺的速度如火箭一样快、臂力惊人、身体如橡皮筋一样柔软、能够飞檐走壁....等等。Yamakasi七个人在城市中逍遥自在，无所不能，他们是大家心目中的传奇人物。有一天，一个贫困、患有心脏病的小男孩命在旦夕，如果12个小时内不能筹到手术费，获得一颗新的心脏接受手术，他将撒手人寰。Yamakasi决定抢救小男孩的性命，于是他们七个人决定利用有限的12小时劫富济贫，找有钱大老下手。而一直视他们为眼中钉的警察局，出动大批人马来阻止他们的行动，一场追逐大战就此展开……', 'Châu Belle Dinh', '阿里埃尔·泽图恩', 7.1, 4722, 'tt0267129', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2591201705.jpg', 1.1, 6.9, 41.5, 39.6, 10.9, '-0.117959,-0.142427,-0.589823,0.356738,-0.409898,0.034256,0.507588,-0.116251,-0.486863,-0.169025,0.333716,0.673723,0.015994,-0.102616,-0.027665,-0.228149,0.067112,-0.741088,-0.058620,-0.101878,-0.513275,-0.404618,-0.237864,-0.386710,0.027536,-0.234982,0.428323,0.200920,0.143122,0.348558,0.131145,-0.098862,0.215564,0.227301,-0.405298,-0.306238,-0.241360,-0.185256,-0.128616,0.523790,-0.184653,0.162609,-0.032504,0.115312,-0.075601,0.282110,0.621512,-0.116394,-0.144489,-0.307336,0.244668,-0.477300,-0.311660,-0.081537,0.423552,0.147743,0.368459,-0.065239,-0.211376,0.118895,0.052757,-0.266360,-0.912230,-0.005509,0.175872,0.063139,-0.809356,0.048280,0.011411,-0.036059,0.047853,-0.240193,-0.021668,0.297940,0.073438,0.397414,-0.226617,-0.175678,-0.770787,0.143748,0.957937,-0.162359,-0.570169,0.037711,0.005345,-0.351584,-0.008154,-0.566247,-0.213299,0.060265,0.117785,0.090191,-0.304798,-0.065115,-0.209043,0.334283,-0.338376,-0.218898,-0.160203,-0.485505,0.034586,-0.553299,0.267297,-0.107234,-0.225520,0.421979,0.218839,-0.212408,1.059558,-0.586555,0.029105,0.441956,0.337961,-0.665082,0.699079,-0.118624,0.076039,-0.285309,0.108321,0.069155,0.068455,0.196353,0.110025,0.160858,-0.250625,0.169154,-0.484973,0.211178', '1877596', '30163500', '24284209', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306541', '玻璃樽', '喜剧', '台湾一个小渔村，女孩阿北（舒淇 饰）一直在这里过着平静的生活。直到有一天，她在海边拣到了一个由香港飘过来的玻璃樽。玻璃樽里有一张香港男孩写的纸条：“我很寂寞，你呢？”，里面还留了他的住址和联系电话。于是，阿北开始在满怀憧憬中来到香港寻找这个男孩。根据地址，阿北找到了男孩阿波。阿波为阿北的勇气所折服，收留了她。经过一段时间的接触，阿北惊奇地发现阿波原来是个同性恋，根本不是自己心目中的白马王子。这时，阿北遇上了心中的白马王子――金融奇才阿祥（成龙 饰）。为了接近喜欢追求刺激的阿祥，阿北谎称自己是黑社会老大的女儿。于是，一场意想不到的经历发生了。©豆瓣', '成龙', '谷德昭', 6.5, 59226, 'tt0184526', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p629412760.jpg', 1.3, 9.1, 58.2, 24.5, 6.9, '0.267372,0.039448,-0.733933,0.449576,-0.274055,-0.147203,0.733059,-0.078736,-0.558630,-0.341126,0.120873,0.712173,-0.132671,0.583468,0.270333,0.407202,-0.320310,-0.765290,-0.039916,-0.247086,-0.162115,-0.304329,-0.394838,0.042517,-0.218980,-0.035131,0.301739,0.064424,0.013503,0.326613,0.226155,-0.014449,-0.015563,0.387888,-0.292547,0.170870,0.013562,0.093579,-0.110984,0.220535,0.222972,-0.180259,0.094129,0.125826,-0.034344,0.198446,0.568142,-0.104755,-0.303602,-0.010409,0.347272,-0.180061,-0.163473,-0.176775,0.221615,0.031326,0.176234,0.034183,-0.279549,-0.206232,0.120041,0.059029,-0.348069,-0.038454,0.085341,0.307254,-0.600331,0.349800,0.033346,-0.182698,0.240407,-0.361993,0.385576,0.270426,0.184175,0.358849,-0.248497,0.125698,-0.472335,0.146794,0.583093,-0.012111,0.128549,0.362852,-0.044893,-0.338746,0.257053,0.172682,-0.573526,0.258233,0.138494,-0.069913,-0.476335,-0.088709,-0.654068,0.163269,-0.127064,-0.040889,0.029885,-0.433609,-0.272103,-0.328925,-0.184526,-0.467039,-0.139304,-0.044082,-0.219334,-0.356110,0.777414,-0.709798,0.167366,0.564322,0.232717,-0.303232,0.694956,0.150133,-0.210592,-0.216507,0.121404,0.166853,-0.070866,0.196266,-0.116221,0.279302,0.044019,-0.213708,-0.459529,0.394022', '1307146', '30162520', '3055049', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306544', '女高怪谈1：死亡教室', '剧情', '绰号老狐狸的班主任朴老师任职于这座历史悠久的女校，这天早上，三年三班的学生们发现她被吊死在树上……许恩英（李美妍 饰）阔别九年后以教师的身份返回母校，学校仍有“疯狗”这样的老师动辄打骂学生，只是不会再有真珠的身影，而朴老师死前致电恩英，宣称真珠没有死，真珠回来了。恩英与真珠是学生时代的好友，两人的友情被老师阻挠不得不分开，而真珠在自己最爱的画室中意外死亡。三年三班的学生们似乎也经历着和恩英当年类似的青春，坐在曾经真珠座位上的智伍同样钟爱美术；同桌素英成绩优异但为人高傲；洁仪时常笨拙的表达自己对智伍的好感。恩英不久后发现，这所学校里有一名反复更换姓名但永不衰老的学生……©豆瓣', '李美妍', '朴歧炯', 6.3, 12878, 'tt0241073', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1655631631.jpg', 2.3, 12.9, 59.8, 19, 5.9, '0.332379,-0.110795,-0.509053,0.579948,-0.243320,-0.215101,0.549090,0.050174,-0.811046,-0.483040,0.147922,0.487243,-0.133895,0.778320,0.233592,-0.251079,-0.173709,-0.679496,-0.024381,-0.473813,-0.194075,-0.446785,0.060977,-0.094324,-0.291050,-0.266636,0.608327,-0.151981,0.007842,0.767870,0.207522,0.129688,0.175329,0.170022,-0.057890,0.019382,0.146402,0.215763,0.070069,0.062868,0.081231,-0.367868,-0.300582,-0.052874,0.146226,0.393357,0.666494,-0.066238,-0.254200,-0.167892,0.592941,-0.174080,-0.119483,0.324792,0.729300,0.241945,0.404547,0.171763,0.029839,0.065487,0.042098,-0.129957,-0.155032,-0.059310,0.045445,0.070214,-0.529220,0.806680,0.119218,-0.095791,0.169103,-0.310597,0.068886,0.037833,0.186919,0.327440,-0.213262,-0.021974,-0.211752,0.322797,0.611990,-0.072262,-0.225914,0.130647,-0.169447,-0.442790,0.127585,-0.184077,-0.715273,0.301791,-0.116834,0.136199,-0.100024,0.013505,-0.502443,-0.099741,-0.084903,0.144501,0.005706,-0.239091,-0.217335,-0.493135,-0.037653,-0.453788,-0.321928,0.072077,-0.004133,-0.183356,0.869502,-1.178102,0.301651,0.289314,0.436790,-0.300574,0.862581,0.102661,0.055671,-0.087071,-0.134457,0.181210,0.100910,0.308615,-0.153883,0.267907,-0.094125,-0.333538,-0.387769,0.314366', '25922902', '35030151', '3445516', '26999591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306548', '趣味游戏', '剧情', '这本该是一个平静美好的早晨，乔治（乌尔里希·穆埃 Ulrich Mühe 饰）和妻子安（苏珊娜·罗莎 Susanne Lothar 饰）带着儿子来到位于湖边的小屋度假，乔治和儿子前往湖边整理之后要使用的帆船，而安则在厨房里安置生活用品。一声尖锐的门铃划破的所有的平静，来者是一名看上去彬彬有礼的年轻人，他自称皮特（弗兰克·捷林 Frank Giering 饰），此行前来打扰是为了借一枚鸡蛋。皮特端正的外表取得了安的信任，但随后发生的事情却让安大跌眼镜。这时，一名叫保罗（亚诺·弗里斯奇 Arno Frisch 饰），外貌酷似皮特的男子敲响了安的房门，同时，乔治带着儿子也回家来了。演员都到齐了，一家三口怎么也无法想到的是，等待着他们的，将是来自这两个白衣恶魔的，毫无动机，毫无怜悯，毫无理智的凌虐。©豆瓣', '苏珊娜·洛塔尔', '迈克尔·哈内克', 7.3, 13052, 'tt0119167', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2499986770.jpg', 4.4, 5.8, 29.3, 41.5, 19, '0.369615,0.112150,-0.721915,0.706214,-0.459789,-0.536012,1.059335,0.356501,-0.356451,-0.370072,-0.065454,0.800573,-0.319956,0.320303,0.296111,0.356960,-0.292239,-0.618886,-0.471006,-0.158810,-0.323406,-0.527808,0.045882,-0.285408,0.077763,-0.009678,0.085139,0.042856,-0.031487,0.608931,0.651401,0.295523,-0.142931,0.680123,-0.297862,0.014107,-0.112433,-0.263029,-0.027950,0.108634,0.149016,-0.209693,-0.095946,0.438920,0.022916,0.430988,0.564412,-0.272970,-0.093747,0.114946,0.179093,-0.061290,0.119131,0.157081,0.345985,-0.044916,-0.273952,0.028707,-0.264816,0.227255,0.303681,-0.214615,-0.807071,0.035811,0.050809,0.240605,-0.715934,0.647610,-0.029589,-0.020195,0.176064,-0.322450,0.310145,0.296681,0.104878,0.406593,0.164616,0.104679,-0.605209,-0.127630,0.455406,0.027502,0.068377,0.387283,-0.517130,-0.471076,0.091969,-0.122315,-0.568694,-0.186423,0.283782,0.134977,0.177057,-0.264446,-0.363498,-0.199239,-0.105900,-0.251941,-0.151488,-0.493358,-0.214406,-0.521185,0.171635,-0.561215,-0.508535,0.246094,-0.117838,-0.155625,0.663383,-0.785337,0.155156,0.355664,0.167467,0.027129,0.659612,-0.261130,0.101602,0.009405,-0.113149,0.135298,0.305983,0.244722,0.229682,0.494983,-0.096006,-0.187629,-0.449720,0.405861', '3111650', '3119246', '1417428', '26648284');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306554', '跳跳虎历险记', '喜剧', '维尼（吉姆·库宁斯 Jim Cummings 配音）、小猪（约翰·菲尔德 John Fiedler 配音）、猫头鹰（Andre Stojka 配音）、小兔（Ken Sansom 配音）和跳跳虎（吉姆·库宁斯 Jim Cummings 配音）等朋友们正聚在一起，布置它们的新家，然而跳跳虎总是淘气的跳来跳去惹出一堆麻烦，于是小兔建议跳跳虎先去找其他的跳跳虎一起玩。然而，跳跳虎从来没有见过其他的跳跳虎，它甚至开始怀疑，这个世界里是否还有自己的同类。博学多识的猫头鹰告诉跳跳虎，在家族之树上刻有问题的答案，于是，在朋友们的陪伴和帮助下，跳跳虎踏上了寻根溯源的旅途。一路上，它们历经艰险和磨难，友情亦受到重重考验，最终，会有怎样的结局等待着它们呢？©豆瓣', '吉姆·卡明斯', '君·法尔克斯汀', 8.4, 4927, 'tt0220099', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1731326340.jpg', 0.4, 0.7, 12.9, 49.4, 36.7, '0.373352,-0.273234,-0.519360,0.407172,0.028656,-0.015592,0.352952,0.053179,-0.262457,-0.289414,-0.027479,0.467372,-0.068812,0.378070,0.058431,-0.321792,-0.475618,-0.449615,0.227812,0.054953,-0.169801,-0.464818,-0.209364,-0.118126,-0.042904,-0.088427,0.400696,-0.180687,0.112070,0.546689,0.253204,0.079908,-0.460694,0.215017,-0.147000,0.029391,0.257591,0.309997,-0.129408,0.126804,0.097117,0.097518,-0.120949,-0.000836,0.170708,0.074641,0.513615,-0.515937,-0.148778,0.033276,0.084572,-0.197564,0.471460,0.047418,0.184943,-0.016253,0.441218,0.148419,0.157849,0.230642,0.123049,-0.065436,-0.553169,-0.027895,0.055924,0.357319,-0.309846,0.065790,0.198407,-0.030242,0.138373,-0.265861,0.314982,0.450066,0.479680,0.169189,-0.126510,0.170756,-0.245905,-0.182977,0.438502,-0.094654,-0.079621,0.117486,0.001255,-0.280672,0.198825,-0.003333,-0.561431,0.047102,0.313294,0.202726,-0.394115,0.035058,-0.826883,0.241780,0.042322,-0.265352,0.141483,-0.426273,0.097031,-0.717673,0.160737,-0.291458,-0.293812,-0.034439,0.159432,-0.397150,0.829892,-0.658113,0.250498,0.419257,0.248776,-0.318726,0.608522,0.006765,0.074805,-0.042445,0.070576,0.131299,-0.015623,0.043895,-0.029601,0.069735,0.351440,-0.119793,-0.632146,0.268998', '4181031', '3811356', '5403927', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306562', '最佳拍档之醉街拍档', '喜剧', '性感妖娆的妙龄女子万玲（钟丽缇 饰）是个纵横江湖绝少失手的红颜神骗。某社团老大被万玲骗尽钱财，一气之下心脏病突发身亡。临终前，该老大将社团托付给在美国打拼的独子浩式（谭咏麟 饰），并命令他亲手杀死万玲为自己报仇。虽然一万个不情愿，但迫于老妈（Maria 饰）和社团同袍的压力，浩式最终接手社团，并在神枪手醉枪（梁朝伟 饰）督促下修炼枪法。两人尾随万玲，伺机行动，而浩式却在这一过程中渐渐迷上这个女子，因此他迟迟无法下手。另一方面，万玲曾用梵高的赝品和黑社会老大雷扬（吴镇宇 饰）交易，骗取对方现金200万，遂令雷扬暴跳如雷，不断派人追杀。几组人马凑在一起，场面越来越乱……©豆瓣', '梁朝伟', '钱嘉乐', 6.1, 3661, 'tt0184081', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2163392539.jpg', 3.3, 16.4, 57.3, 16.8, 6.2, '-0.102317,0.043663,-0.354449,0.332196,-0.025552,-0.147354,0.353255,0.073306,-0.450582,-0.216063,0.277310,0.501656,0.194585,0.002440,0.124505,-0.256434,-0.034642,-0.520581,-0.031309,0.028684,-0.016095,-0.181740,-0.103535,-0.133859,-0.222322,-0.089995,0.431717,-0.040385,-0.238712,0.460695,0.537915,0.304288,-0.144687,0.311756,0.010110,0.094333,0.054098,-0.142353,-0.033295,0.139376,-0.112554,-0.457550,-0.178877,0.216280,-0.035519,0.380058,0.487454,-0.015876,-0.099936,-0.127226,0.173129,-0.267888,-0.291199,-0.090643,0.303383,-0.124741,0.329446,0.294071,-0.148289,0.045959,0.148958,0.069436,-0.679141,0.024716,0.268683,0.049977,-0.559445,0.212536,-0.276250,0.260098,-0.164520,-0.041626,-0.015469,0.359632,0.106703,-0.071452,-0.249462,-0.033173,-0.510107,0.423447,0.470667,0.063176,0.256310,0.073657,-0.154511,-0.171896,-0.027654,-0.383858,-0.381627,-0.032817,0.425674,-0.062919,-0.074638,0.070668,-0.366737,-0.123628,-0.015114,0.065595,-0.194437,-0.291617,0.095287,-0.335177,-0.088372,-0.132770,-0.294181,0.099113,0.172848,0.030455,0.578519,-0.647715,-0.018027,0.387504,0.097624,-0.560881,0.313894,0.308781,-0.067763,-0.110457,-0.418288,0.000172,0.350694,0.112179,0.135175,0.273433,0.005605,-0.352476,-0.262562,0.079770', '1877596', '4301278', '1299649', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306564', '搭错车', '剧情', '退伍老兵哑叔（孙越）因捡回弃婴致使妻子别他而去，靠拾破烂，哑叔既当爸又做妈含辛茹苦将取名阿美（刘瑞琪）的弃婴养大成人。因为哑叔常在耳边吹奏美妙的乐曲，阿美自小就对音乐有特别的理解。高中毕业后，阿美去了某餐厅当歌手，有缘结识作曲家时君迈后，她的演唱技艺有了较大提高，被娱乐公司老板余广泰盯上。为了改善哑叔的生活，阿美在余广泰的引诱下签署赴东南亚演出的合约，不想被其当作摇钱树受到控制，在哑叔重病在床之际也无法抽身探望，只能在舞台上把思念愧疚之情化为歌声遥寄。©豆瓣', '孙越', '虞戡平', 8.3, 17274, 'tt0085388', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2527513159.jpg', 0.4, 1.6, 16.1, 47, 34.9, '0.085295,-0.007486,-0.739031,0.365044,-0.152057,-0.311244,0.512934,0.487801,-0.343317,0.053368,0.051565,0.676720,0.114793,0.403172,0.003984,-0.069703,-0.092975,-0.572075,0.043702,0.007819,-0.045850,-0.338073,0.172135,0.004836,-0.336369,-0.390781,0.475857,-0.259199,-0.312573,0.356488,0.224129,-0.008775,0.032033,0.254319,-0.362532,0.132141,-0.105594,0.203452,-0.276682,0.279518,0.146906,-0.348761,0.068552,-0.251861,0.099087,0.066296,0.731979,0.072297,0.044410,-0.146831,0.382800,-0.101383,0.156432,-0.185607,0.064980,0.194097,0.074808,0.109542,-0.610597,-0.006589,0.095127,-0.107543,-0.560349,0.147399,0.112229,-0.123866,-0.694924,0.441427,0.024947,-0.111649,0.203161,-0.286936,0.167258,0.253890,0.101872,0.473049,-0.128018,0.367198,-0.313733,0.247753,0.734849,-0.084068,-0.025953,0.285393,-0.313046,-0.271956,0.389899,-0.278029,-0.234227,-0.145167,0.251667,0.024549,-0.334779,-0.039245,-0.223752,-0.152235,-0.069072,-0.207361,0.123029,-0.494714,-0.067112,-0.383462,-0.078180,0.019309,-0.072852,-0.053516,0.300455,-0.365439,0.841516,-0.734698,0.337918,0.572616,0.364062,-0.290111,0.652390,0.093906,0.134341,0.006480,-0.070128,0.217992,-0.071762,0.363213,0.401988,-0.063568,-0.095747,0.078046,-0.505488,0.276632', '35048413', '1308609', '26021055', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306573', '江湖最后一个大佬', '剧情', '黑道大哥方叔（柯俊雄 饰）为人刚正耿直，忠勇仁义，为道上的兄弟所敬仰。当年他为保护兄弟，一个人顶下所有罪名，从此在监狱中度过了几十年岁月。出狱后，周围一切早已变了模样，当年的小弟们垂垂老矣，或退休，或经商，俨然与黑道没有任何干系。而黑社会的价值观也发生巨大改变，年轻的黑社会完全不把仁义放在眼里，在他们看来金钱胜过一切。方叔知道属于自己的时代早已远去，莫不如静下心来过好余下的日子。但他的女儿阿丽因疏于父爱而过分叛逆，成为一个小混混的马子。为了保护女儿，方叔不得不重新进入这已经变得十分陌生的纷乱江湖……©豆瓣', '周星驰', '沈威', 6.7, 11291, 'tt0121419', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2159690828.jpg', 1.5, 10.9, 52, 23.7, 12, '0.101614,0.065388,-0.526349,0.485309,-0.462057,-0.339142,0.680888,0.093389,-0.962597,-0.460557,0.043956,0.564379,0.269844,0.193995,0.139977,-0.212364,-0.203934,-0.796969,-0.395634,-0.121733,-0.085770,-0.479291,-0.097413,-0.172041,-0.413548,-0.201933,0.737759,0.200048,0.130174,0.335236,0.119764,0.101532,0.075386,0.280966,-0.279190,0.028042,-0.332583,0.086910,-0.610371,-0.292645,-0.286997,-0.078757,-0.122117,0.223686,-0.202428,0.116048,0.406254,-0.244034,-0.381025,-0.399485,0.472951,-0.192947,-0.167858,0.060938,0.105570,0.035278,0.262257,0.474532,0.007239,-0.084813,-0.056540,-0.111461,-0.751363,-0.141567,0.236857,0.092439,-0.761326,0.530206,0.034552,-0.283242,-0.182484,-0.200801,0.123703,0.170358,0.266340,0.432664,-0.264842,0.154227,-0.529336,0.160800,0.872296,0.090693,-0.325931,0.182225,-0.142248,-0.106711,0.059672,-0.527576,-0.441096,0.011163,-0.172598,0.018332,-0.269251,0.630926,-0.229544,0.082874,-0.028143,-0.035622,-0.054699,-0.618992,-0.144235,-0.226384,-0.390727,-0.509444,-0.331233,0.010993,0.191141,-0.265998,0.732683,-0.893237,0.279803,0.040480,0.116956,-0.715358,0.509905,0.110982,0.290501,-0.214924,-0.301005,0.177454,0.262480,0.323743,-0.040886,-0.100588,-0.297283,-0.169830,-0.074002,0.396073', '35030151', '1293265', '25721544', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306588', '27个遗失的吻', '剧情', '炙热的夏天，米奇（Shalva Iashvili）遇到了让他爱的五脏六腑都碎掉的女孩——西贝拉（Nutsa Kukhianidze ）。可是热情如火的西贝拉在跳下长途车，被亚历山大（Yevgeni Sidikhin ）抱个满怀的时候就爱上了这个老男人——米奇的爸爸。小镇里炙热的天气里，大人们对蠢蠢欲动的情欲遮遮掩掩，却还是难逃孩子们好奇的眼睛。西贝拉和米奇窥视着大人世界里林林种种的景象，萌动着少年人的春心。西贝拉答应米奇可以在这个夏天吻她一百下，然而她也大声的宣布她爱亚历山大。西贝拉的爱强烈奔放，米奇的爱执着细腻，他们奋力的追逐着心里的爱恋，直到西贝拉的离去，遗失给夏天二十七个吻。©豆瓣', '尼莎·库察尼婕', '娜娜·裘杨兹', 7.8, 8785, 'tt0246405', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p737077100.jpg', 0.7, 2.9, 27, 45.8, 23.6, '0.403629,0.216872,-1.051166,0.486244,-0.152917,-0.167235,0.840515,0.252778,-0.101699,0.441295,0.006809,0.438830,-0.465859,0.543791,0.224714,0.504924,-0.249193,-0.825053,-0.207928,-0.109743,-0.181549,-0.314738,-0.124412,-0.103857,0.047156,-0.148175,0.180100,0.338288,-0.119959,0.410400,0.518737,-0.000858,0.153587,0.563823,-0.241834,0.064706,0.062638,-0.193219,0.185097,0.026276,0.376858,0.223120,-0.247749,0.346809,-0.048481,0.342320,0.611965,-0.657113,0.050986,-0.102485,0.129058,-0.188795,0.191607,0.512247,-0.164610,0.185845,-0.057434,-0.217806,-0.002848,-0.135480,0.366278,0.060438,-0.367097,0.207321,-0.301280,0.182549,-0.692867,0.517500,-0.251103,0.156735,0.242645,-0.474547,0.131334,-0.126715,-0.174267,0.519837,-0.093509,-0.079225,-0.269737,-0.010075,0.676993,0.250598,-0.280868,0.108698,-0.641999,-0.241636,-0.003235,-0.088267,-0.851243,-0.326943,0.550854,0.027844,-0.327473,0.453249,-0.480933,0.354718,-0.143702,-0.288501,-0.075396,-0.167271,-0.265057,-0.222093,-0.251257,-0.530399,-0.302516,0.071981,-0.051256,-0.072309,0.876422,-0.662297,0.433389,1.020358,0.570378,-0.129059,0.636307,0.371381,-0.375219,0.076629,-0.371960,0.637951,-0.120762,0.208581,0.384726,0.533490,-0.271759,0.215085,-0.587042,0.797903', '1469111', '2002683', '1293372', '3534824');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306601', '吸血鬼女王', '恐怖', '吸血鬼莱斯塔特（斯图尔特·汤森 Stuart Townsend 饰）从长眠中苏醒，他不甘于趋于黑暗之中，于是他曝光于大众之下成为了一个摇滚歌手，一次意外莱斯塔特救了图书管理员杰西·瑞薇丝（玛格丽特·莫罗 Marguerite Moreau 饰），他的身份被杰西发现。莱斯塔特用他的歌声唤醒了传说中沉睡千年的吸血鬼女王阿卡沙（阿丽雅 Aaliyah 饰），阿卡沙与莱斯塔特展开了一场向旧仇人的报复计划，可他没有想到阿卡沙最终目的是想和他一起变人间为炼狱，统治全人类。与此同时杰西也爱上了莱斯塔特，莱斯塔特会怎么选择？本片与《夜访吸血鬼》一样改编自安妮·芮丝（Anne Rice）的畅销系列小说——《吸血鬼列传》(Vampire Chronicles)。©豆瓣', '阿丽雅', '迈克尔·瑞迈尔', 6.1, 8108, 'tt0238546', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1032505396.jpg', 5, 19.6, 48.8, 19.1, 7.5, '0.133805,0.265103,-0.352273,0.639737,0.200299,-0.492055,1.033112,-0.005617,-0.348789,-0.326468,-0.212347,0.854249,-0.182618,-0.150473,0.525424,0.291633,-0.865860,-0.848152,0.125758,-0.187687,-0.063548,-0.525016,-0.244022,-0.518791,-0.128074,-0.469898,0.324275,0.177207,-0.204963,0.318697,0.470466,0.671286,-0.057591,0.307528,0.170753,0.041778,0.342527,-0.187797,-0.174610,0.560654,0.204580,-0.182474,-0.084094,0.382799,0.168255,0.418789,0.306824,-0.685083,0.361673,-0.304271,0.247954,-0.299119,0.261860,0.082764,0.463669,-0.359041,0.118503,-0.003363,-0.216310,-0.185866,0.390048,-0.050328,-0.708339,-0.324932,-0.064622,0.306263,-0.434595,0.185622,0.120474,0.167865,0.125296,-0.100793,0.233355,0.060561,0.630556,0.099825,0.138292,-0.239048,-0.449577,0.125477,0.663887,0.257564,-0.270404,-0.073396,-0.166510,-0.742564,-0.346130,-0.124202,-0.531464,-0.125765,0.593208,0.198770,0.050871,0.847641,-0.630186,-0.360430,-0.664914,-0.127538,-0.326353,-0.402317,-0.159485,-0.390989,-0.016629,-0.220768,-0.283367,-0.068479,-0.069804,-0.285376,0.193622,-0.649875,0.382142,0.301432,0.219451,-0.006282,0.617249,-0.142061,-0.183939,-0.371221,0.266963,0.583945,0.273613,0.057967,0.487583,0.045767,0.252000,0.098205,-0.432545,0.751394', '26630714', '3157583', '1299327', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306605', '电影人生', '剧情', '1951年好莱坞，一切带有左翼观点的电影都深受“麦卡锡事件”影响，被列入所谓的黑名单中，众多无辜的电影人被迫害。刚入行的电影编剧彼得·阿普尔顿（金·凯瑞 Jim Carrey饰）本是好莱坞一位才华横溢的青年剧作家，可生不逢时的他因为一次在大学时的无心之举也被政府列入黑名 单之中。然而他的噩梦并没有结束，失业失恋的彼得在一次车祸中失去了所有的记忆。当彼得被好心人救起，带到一座名叫朗森的小镇时，小镇居民都把他误认成九年前在二战中牺牲的鲁克。而鲁克的父亲哈里（马丁·兰杜饰）更是欣喜若狂。彼得修复了哈里无心经营的电影院，也让他在电影中找到了生活的激情。鲁克原来的女友阿黛尔（劳瑞·霍尔登饰）更与彼得坠入情网。当一切都向着大团圆结局发展的时候，调查员却追踪到小镇，要求彼特立刻出庭。这部由著名导演弗兰克·德拉邦特执导，喜剧影星金·凯瑞主演的《电影人生》，是导演冲击奥斯卡的野心之作，然而票房口碑双双失利，却足够达到精益求精的完美水平。', '金·凯瑞', '弗兰克·德拉邦特', 8.2, 13502, 'tt0268995', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p585421852.jpg', 0.3, 1.7, 18, 48.1, 32, '0.061269,0.040376,-0.730712,0.543425,0.012924,-0.512200,0.805096,0.121261,-0.474997,-0.271901,0.322880,0.800276,-0.306201,0.144184,0.455332,-0.070094,-0.276447,-0.726676,-0.144518,-0.150336,-0.053613,-0.377066,-0.373240,-0.021034,-0.297429,-0.542303,0.802586,0.172237,-0.432607,0.248585,0.279631,0.264119,0.196694,0.362331,0.195574,0.221121,0.322402,-0.148432,-0.364745,0.397091,-0.054238,-0.226869,-0.164438,0.197787,-0.074090,0.331680,0.696501,-0.222479,-0.002370,-0.037710,0.493226,-0.367898,-0.077943,0.060795,0.253878,-0.039197,0.263699,0.291115,-0.141498,0.061130,0.002893,-0.159358,-0.841513,0.043254,0.160160,0.206915,-0.510063,0.494358,-0.172317,-0.004498,-0.051200,-0.205650,0.064353,0.000691,0.434992,0.433094,-0.192033,0.194628,-0.502555,0.467575,0.619677,0.113130,-0.338379,0.502608,-0.118384,-0.495922,-0.219423,-0.230473,-0.521766,0.273116,0.426824,-0.168043,-0.156507,0.481866,-0.515872,-0.128024,-0.352688,-0.311931,-0.153926,-0.217255,-0.048544,-0.808594,-0.111247,-0.127337,-0.160408,-0.314508,0.069343,-0.266076,0.741957,-0.545621,0.267666,0.448790,0.081113,-0.160230,0.774559,0.093571,0.101418,-0.097559,-0.112774,0.318182,0.092043,0.308174,0.123263,0.181602,-0.042831,-0.518631,-0.325995,0.769803', '25928048', '1322847', '1292925', '3597344');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306606', '我们曾是战士', '剧情', '本片根据越南战争中的真实战斗改编。1965年11月，越南战争升级至美军直接参与战争阶段。驻越美军人数不断上升。摩尔中校（梅尔吉布森 Mel Gibson 饰）受命把一群新兵训练为真正的战士，部队中同时涌入不少随军家属，军人们扮演着丈夫与战士的双重角色，温馨的气氛中掺杂着丝丝不安。为了缓解单调的军旅生活，部队举办了大型晚会。出征的时刻到了，摩尔在典礼上庄严承诺“带回每一名士兵”。摩尔与他的部队被空降在临近柬埔寨的河谷地带，这里是北越军的重兵所在，人数弱势的美军陷入了重重包围，伤亡惨重，最后在火炮、直升机的辅助下战局开始僵持。第二天，战斗推进到山丘但仍然无法突破包围，摩尔寻求空军帮助，由于双方距离过近，美军的汽油弹炸伤了部分地面部队。摄影记者乔（Barry Pepper 饰）记录下了战斗中一幕幕残酷的画面。第三天，美军正准备进行决定性的近身战斗，这时空军支援到位了，越军被全灭。', '梅尔·吉布森', '兰道尔·华莱士', 7.6, 15417, 'tt0277434', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2235487996.jpg', 1, 4, 28, 45.8, 21.2, '0.187520,0.063956,-0.802441,0.594571,0.308046,0.225756,0.745061,-0.106792,-0.460727,-0.107521,0.560613,0.342911,0.018466,-0.152718,0.390226,-0.624225,-0.533843,-0.720480,-0.317085,0.055809,-0.466161,-0.408995,-0.405174,-0.172831,-0.000536,-0.505962,0.900840,0.447451,-0.298265,0.441520,-0.238776,0.362157,-0.028054,0.538227,0.109676,-0.160493,0.253232,-0.666649,-0.241169,0.378660,-0.448176,-0.229129,-0.171386,-0.008888,0.134884,0.418602,1.062875,-0.393161,0.214564,-0.023202,-0.024394,-0.253778,0.055790,0.139203,0.566264,0.321115,0.064201,-0.188961,-0.023566,0.315744,-0.455459,-0.175240,-0.652330,0.076342,-0.128564,-0.007615,-0.397672,0.585088,-0.220654,0.309333,0.270749,-0.112603,0.041100,0.825642,0.092169,0.252011,-0.413839,-0.090965,-0.449414,0.099167,0.790259,-0.218793,-0.355171,-0.113920,-0.294825,-0.513098,-0.053376,-0.503024,-0.177828,-0.255190,0.450913,0.000093,0.282521,0.379860,-0.695467,0.323718,-0.323324,-0.657083,-0.208932,-0.156900,-0.150305,-1.040579,-0.056183,-0.345054,-0.195069,0.383379,-0.086930,0.166317,0.719461,-0.737145,0.129439,0.542369,0.262191,-0.001227,0.221055,0.202506,0.347878,-0.036904,0.144190,0.243743,-0.364275,0.524322,0.406318,0.277517,-0.470799,0.025751,-0.322609,0.288612', '2369613', '2159244', '20274039', '35058077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306607', 'K星异客', '剧情', '一位自称普洛特的戴墨镜男人（凯文•斯帕西 Keven Spacey 饰）突然出现在纽约中央公园车站。他自称来自天琴座附近距地球一千光年的K-PAX星，以超光速来到地球考察。普洛特被当作精神病人入住曼哈顿精神病院，受到马克•鲍威尔医生（杰夫•布里奇斯 Jeff Bridges 饰）的治疗。马克认为普洛特是妄想症患者，却又对普洛特的奇怪行为和不可思议的天文知识将信将疑。同时，普洛特的到来在病院中其他病人中造成轰动，人人都希望能被选中随普洛特回K-PAX星。马克医生竭尽全力希望找出普洛特的真实身份，却没想到自己竟在此过程中越来越被普洛特的理论所说服。普洛特的真实身份究竟为何？本片被提名美国科幻、幻想和恐怖电影协会最佳男主角（凯文•斯帕西）。©豆瓣', '凯文·史派西', '伊恩·索夫特雷', 8.5, 91204, 'tt0272152', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792526748.jpg', 0.3, 1.2, 12.4, 44.3, 41.8, '0.254864,0.107154,-0.685506,0.380391,0.355898,-0.019684,0.416961,0.153983,-0.382471,-0.630556,0.097827,0.673267,-0.386645,0.005624,0.369261,0.203159,-0.643737,-0.337696,0.044903,-0.479117,-0.392445,-0.557494,-0.337637,-0.228575,-0.006303,-0.575403,-0.060087,-0.063985,-0.049403,0.311286,0.197475,0.803824,0.135604,0.367800,-0.138569,0.137122,0.399921,-0.409100,-0.145128,0.344487,0.117028,0.232430,-0.053081,0.383558,0.124014,0.184673,0.489335,-0.168700,0.124508,0.054457,0.340470,-0.058998,0.318975,-0.005953,0.320125,-0.409495,-0.004686,-0.046705,-0.006920,0.123765,0.156469,-0.195648,-0.825925,0.135609,0.134830,0.387905,-0.296745,-0.064301,-0.398416,-0.002614,-0.177517,-0.024118,0.000576,0.216080,0.464805,0.339172,0.008770,-0.020598,-0.358432,-0.206127,0.374972,-0.014247,-0.658577,0.125465,-0.398036,-0.296852,-0.108467,-0.112178,-0.402963,0.039457,0.235562,-0.218849,0.193160,0.374254,-0.184851,-0.259288,-0.808525,-0.179858,-0.111787,-0.103477,-0.159044,-0.756931,0.224998,-0.028879,-0.029363,-0.083020,0.049063,-0.235493,0.493782,-0.647731,0.348768,0.522281,0.511522,-0.140393,0.593151,-0.024414,0.039123,-0.325279,-0.438847,0.628643,0.761722,0.190204,-0.069925,0.197077,0.109513,-0.228093,-0.079935,0.342285', '1858678', '22266126', '3231742', '2039711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306609', '时间机器', '动作', '亚历山大（盖·皮尔斯 Guy Pearce 饰）博士是一位狂热的科学爱好者，他一直想证明时间旅行是可行的，并将全部的精力都投放到了时间机器的研究中。可是一天，未婚妻的意外离世让他悲愤不已，并加紧了时间机器的研制，希望能重返过去，拯救未婚妻的生命。时光机研制成功，亚历山大成功穿越到了过去，亲眼目睹了未婚妻的意外事故。可是无论他回到过去多少次，都没有办法救回未婚妻，未婚妻都会因为各种意外事故身亡。问题，到底出在了什么地方？亚历山大为了解开这个谜，将寻找答案的希望放在了过去。不停的穿越，不停的前往未来寻找答案……直到八十万年后的地球，亚历山大发现，人类已经进化到跟现在完全不一样。而那时的地球上分为了两个派系爱好和平的伊莱人和好战的莫洛人，为了帮助伊莱人摆脱莫洛人的统治，亚历山大不惜毁掉时光机，而他也发现了最终的秘密。©豆瓣', '盖·皮尔斯', '西蒙·威尔斯', 7, 24481, 'tt0268695', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p732849181.jpg', 1.3, 7.2, 42.2, 36.4, 12.8, '0.037642,0.166114,-0.701508,0.419185,-0.176123,-0.350782,0.618833,-0.490596,-0.645045,-0.262047,-0.087192,0.512347,0.091976,0.120474,0.372624,0.127796,-0.292695,-0.630918,0.188045,-0.377349,-0.745419,-0.645487,-0.454681,-0.366729,-0.064021,-0.480291,0.692913,0.214582,0.019783,0.261573,0.215841,0.160138,-0.041978,0.680359,-0.275789,0.074774,-0.001691,0.028156,-0.268238,0.536398,0.117155,-0.238214,-0.162712,0.454793,-0.102225,0.394413,0.482457,-0.427939,-0.095283,0.040363,0.266605,-0.445414,-0.198566,0.009808,0.143553,0.093543,0.003075,0.285362,-0.051448,0.120345,0.150584,0.108907,-0.993866,-0.153186,0.032224,0.184519,-0.704169,0.455254,-0.081935,-0.114886,-0.038706,-0.526682,0.391209,0.544126,0.261000,0.390789,-0.565541,0.034143,-0.684000,0.200783,0.689804,-0.166079,-0.174050,0.594358,-0.013990,-0.343811,-0.302523,-0.235916,-0.349225,0.064977,0.167041,0.483783,-0.336240,0.333891,-0.530544,-0.089675,-0.275625,-0.347096,0.138708,-0.451501,0.027239,-0.238807,-0.111924,-0.053962,-0.240324,0.103251,0.087134,-0.581195,0.695795,-0.794641,0.223660,0.750011,0.332551,-0.650181,0.708797,0.097318,-0.081668,-0.401701,-0.093195,0.276047,0.170470,0.489018,-0.010360,0.271112,0.140556,-0.302481,-0.596618,0.613955', '1793491', '30163500', '3755531', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306610', '蝎子王', '动作', '在5000年前的古埃及，俄摩拉城因其城主曼侬（史蒂文·布兰德 Steven Brand 饰）手握重兵，并且统治非常残暴，使其称霸一方。为了反抗他的统治，领地里的其他部落组成联盟向其发动了多场战争。但是结果都是大败而归。原来，在曼侬身边有一位精通巫术 的神秘人物，她能预知未来，遇见部落联盟的战术安排，由此帮助曼侬百战百胜。在知晓这一情况后，部落联盟决定派出一位刺客先把这个神秘人物除掉。但是当刺客摩挲尤斯（道恩·强森 Dwayne Johnson 饰）深入城内准备暗杀那个神秘人物时，却发现这是一位漂亮的女人（胡凯莉 Kelly Hu 饰），而且是因为受到曼侬的威胁才被逼帮助曼侬。最终，他们的目标从这位神秘人物身上转到了直接刺杀曼侬，一场生死大战就此展开……©豆瓣', '道恩·强森', '查克·拉塞尔', 6.6, 34965, 'tt0277296', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1352576126.jpg', 1.1, 8.9, 56.8, 26, 7.2, '0.062752,0.240993,-0.585248,0.708176,0.020467,0.190128,0.364972,-0.123375,-0.424224,-0.432211,0.291159,0.632213,0.114579,-0.117077,0.254593,-0.231476,-0.188028,-0.622002,-0.049334,-0.150914,-0.550564,-0.267326,-0.577777,-0.103764,-0.128581,-0.319875,0.648763,0.148305,-0.645375,0.186876,0.299294,0.744119,-0.264756,0.323509,0.005504,-0.405846,0.210627,-0.148871,-0.405836,0.462105,-0.401543,-0.193132,-0.266726,0.347817,-0.169557,0.402476,0.509530,-0.569702,-0.115088,-0.387933,0.219836,-0.352812,-0.038565,-0.021675,0.683228,-0.001589,0.004827,0.293744,0.033466,-0.119226,-0.068374,-0.112384,-0.992187,-0.007858,0.338480,-0.016516,-0.537328,0.073515,-0.082004,-0.100820,-0.073979,-0.333522,0.252375,0.699454,0.390577,-0.129585,0.067703,0.123996,-0.575125,-0.212825,0.680483,-0.207338,-0.131758,0.051188,0.228598,-0.587773,-0.011092,-0.506390,-0.211600,0.206307,0.253586,0.012945,0.206746,0.375534,-0.534214,-0.203536,-0.318120,-0.130007,0.204317,-0.282781,0.014378,-0.510408,-0.322963,-0.056013,-0.299010,0.140528,0.036541,0.030369,0.804061,-0.732364,0.188600,0.437059,0.274353,-0.704358,0.381460,0.140454,0.281140,0.003432,-0.182041,0.215691,0.367721,-0.005881,0.073606,0.177510,-0.011033,-0.410223,-0.077890,0.320277', '1811755', '30163500', '26678784', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306612', '蜘蛛侠', '动作', '彼得 帕克（托比•马奎尔 Tobey Maguire 饰）只是美国一个平凡的高中生，当一次他被蜘蛛博物馆偷跑出来的变种蜘蛛咬了一口之后，彼得的生活彻底改变了。他变得和蜘蛛一样，拥有各种蜘蛛特有的超能力：从手指喷出粘力极强的蜘蛛丝、飞檐走壁等等。彼得兴奋异常，开始利用自己的超能力去赚钱。但当他最爱的叔叔被自己放走的罪犯杀死后，彼得发誓要用自己的超能力去打击犯罪。彼得好友哈利的父亲诺曼（威廉•达福 Willem Dafoe 饰）是一家生物科技公司的老板，因自己公司生产的飞行器没得到军方首脑赏识而苦恼不堪。一次意外诺曼吸入神经毒气而具有了超能力，引发了自身邪恶的本性，骑着自己研发的飞行器去到处破坏、杀人。彼得化身的蜘蛛侠开始出击了！©豆瓣', '托比·马奎尔', '山姆·雷米', 8, 353365, 'tt0145487', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p457050361.jpg', 0.2, 1.2, 23.2, 50.1, 25.3, '0.304691,-0.007548,-0.597925,0.568091,-0.424228,-0.294964,0.948560,0.126301,-0.233000,-0.167960,0.281446,0.810629,0.044597,0.011989,-0.070961,0.279818,-0.019869,-0.358595,0.188628,-0.072448,-0.220460,-0.243387,-0.339406,-0.398441,0.129454,-0.399750,0.561060,-0.093571,-0.392323,0.393799,0.153988,0.368415,0.312738,0.344375,-0.251841,-0.041489,0.022656,-0.324174,0.083379,0.130208,0.309427,-0.028000,0.085352,0.364562,-0.075733,0.137793,0.642031,-0.291396,0.120370,-0.510448,0.372430,-0.351114,0.168661,0.092285,0.310062,0.099399,0.005708,-0.229020,-0.019115,0.044638,0.231211,0.097423,-0.899801,-0.284573,-0.222158,0.087631,-0.533428,0.115023,-0.278675,0.118401,0.181761,-0.463131,-0.043448,0.100439,0.163584,0.268845,-0.053752,0.202328,-0.756397,0.068422,0.549181,-0.264836,-0.478045,0.334813,-0.329414,-0.290713,-0.095327,-0.281540,-0.292358,-0.261280,0.631186,-0.012052,-0.408456,0.305267,-0.711228,-0.122990,-0.360177,-0.100801,-0.138195,-0.200362,-0.146889,-0.602051,-0.131666,-0.262716,0.041010,-0.298719,0.025484,-0.328489,0.520012,-0.815763,0.113634,0.733957,0.154220,-0.407064,0.337421,-0.198196,0.019445,-0.108560,-0.101423,0.098329,0.358600,0.562036,0.269817,0.512995,0.501176,-0.051884,-0.193331,0.566967', '3005387', '21619567', '1793491', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306662', '死亡幻觉', '剧情', '丹尼•达可（杰克•盖伦霍尔 饰）患有精神疾病，某天晚  上他受到莫名的召唤，梦游，也因此逃避了一架飞机坠落在他房间天花板上，这样匪夷所思的事故。自此以后，他的生活就发生了变化，频频出现幻觉，他时常看见一个兔人弗兰克，后者告诉他世界将在28天6小时48分12秒以后毁灭；他得到了一本书，《时空旅行奥义书》，对书中提到的时空旅行、离线宇宙产生了强烈的好奇。随着世界末日的临近，杰克的生活越来约诡异，他新认识的女朋友和家人也被卷了进去。看来，杰克想实现拯救世界的愿望，需要付出更多的代价。©豆瓣', '杰克·吉伦哈尔', '理查德·凯利', 7.3, 78378, 'tt0246578', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p584631847.jpg', 2, 6.6, 33.8, 39, 18.6, '0.264052,0.133363,-0.751772,0.220411,-0.001557,-0.114259,0.809522,-0.055785,-0.122842,-0.098514,0.120362,0.836047,-0.430021,0.033991,0.323772,-0.031754,-0.245640,-0.375948,0.253194,-0.194309,-0.398347,-0.540021,-0.129234,-0.357039,0.182897,-0.438876,0.320696,0.002385,-0.130876,0.338711,0.077986,0.119932,0.153879,0.745035,-0.072269,0.058111,-0.117736,0.074133,0.036449,0.143809,0.112963,-0.034310,0.157444,0.304102,-0.332299,0.073985,0.473251,-0.206853,-0.478407,-0.130018,0.571257,-0.171811,-0.105798,-0.184426,0.206949,0.166454,-0.176243,0.044007,-0.084496,-0.128758,-0.019374,0.119743,-0.582023,0.090056,-0.238344,0.153858,-0.412716,0.158997,-0.062211,-0.098550,0.170666,-0.183616,0.234001,0.479313,0.420057,0.251445,-0.467023,-0.126853,-0.537266,0.163596,0.634669,-0.312621,-0.424226,0.437131,-0.289241,-0.354272,-0.349170,-0.032486,-0.389642,0.066655,0.311803,0.119217,-0.256178,0.217491,-0.395546,0.034445,-0.189670,-0.451729,-0.217570,-0.358917,-0.197248,-0.250756,-0.304137,0.086538,-0.423697,0.000439,0.076600,-0.564515,0.503227,-0.610012,0.412163,0.716081,0.525958,-0.330162,0.751770,0.036313,-0.222478,-0.196236,0.128661,0.423682,-0.170766,0.389432,0.101956,0.285159,0.206618,0.253926,-0.210341,0.687613', '1309172', '26718282', '1949005', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306663', '朋友', '剧情', '1978年的釜山，东洙（张东健饰）是─贫穷家庭的孩子，俊硕（刘五性饰）则─黑社会团体老大的儿子，特别勤奋的山泰和特别能言善的容贺。山泰常考全校第一，而东洙和俊硕却是到处惹麻烦的问题份子，但四个人却是好朋友。后来升入中学的东洙和俊硕，因为替山泰出头而被学校开除。1984年的汉城，进入大学后的山泰和容贺到处寻找两个朋友下落，但是这两位朋友如今已经加入了黑社会。一个在坐牢，一个在戒毒。1990年的秋天，留学美国的山泰回国度假，感慨着旧日友情。由于在帮派斗争中相互报复，东洙和俊硕却成了真正的敌人，他们该如何面对曾经的朋友？©豆瓣', '张东健', '郭景泽', 7.8, 25508, 'tt0281718', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1198614808.jpg', 0.3, 2, 27.6, 48.3, 21.7, '0.369086,-0.318353,-0.419063,0.523133,0.140775,-0.433994,0.403051,0.239443,-0.468326,-0.382366,-0.165316,0.609123,-0.106702,0.593350,0.266038,-0.046056,-0.005439,-0.757756,-0.052430,-0.507742,-0.203306,-0.301057,-0.197935,-0.089707,0.042740,-0.010693,0.714025,0.058148,0.083404,0.714615,0.379772,0.272721,-0.065096,0.231706,-0.114671,-0.223392,0.205632,0.223641,-0.332088,0.012361,0.019034,-0.281514,-0.301480,0.050965,0.207371,0.377563,0.688603,0.052629,-0.205562,-0.110150,0.244540,-0.420277,-0.381927,-0.107701,0.608035,-0.339794,0.291765,0.571337,0.104978,0.041280,-0.150350,-0.317744,-0.669769,0.010581,0.174981,-0.015375,-0.535610,0.742548,0.220693,-0.182575,-0.160759,-0.247960,0.364037,0.587472,-0.190557,0.441451,-0.465370,0.224895,-0.385375,0.379406,0.789017,0.069097,-0.007767,0.144787,-0.094214,-0.284220,-0.058619,-0.336768,-0.461741,0.151604,0.010414,-0.262864,-0.321844,0.011527,-0.594850,-0.017985,-0.141876,0.038440,-0.027800,-0.359318,-0.153357,-0.483981,-0.109261,-0.404831,-0.386670,0.179999,-0.047750,-0.065447,0.828364,-1.003558,-0.155281,0.470871,0.482214,-0.692676,0.684213,0.153874,-0.041709,-0.424381,-0.413995,-0.120226,0.207734,0.094916,0.041112,0.229003,-0.226727,-0.319482,-0.228912,0.201327', '35030151', '1826173', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306664', '共同警备区', '剧情', '板门店边界的共同警备区，一天，哨所里的朝鲜士兵（申河均饰）为来路不明的子弹所杀，引发双方枪战。而最有嫌疑的凶手是同在边界上的韩国士兵，但韩国一方却指责是朝鲜先调起事端，双方都认为对手应该对此负责。为了解决这一无头案件，南北双方同意由一个中立国来进行调查协调。瑞士国籍韩国女孩苏菲（李英爱饰）受派前来调查事件，韩国这边的李秀赫（李秉宪饰）始终保持沉默，而朝鲜一边的幸存者吴敬必（宋康昊饰）却表现出敌意，事情扑朔迷离。随着深入了解，苏菲发现事情隐藏著内幕，现场还另有其人……©豆瓣', '李英爱', '朴赞郁', 8.8, 90999, 'tt0260991', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1603485241.jpg', 0.1, 0.5, 7.8, 41.3, 50.2, '0.278316,-0.106392,-0.610633,0.530538,0.365772,0.277494,0.538526,-0.124984,-0.605567,-0.306898,0.147896,0.308569,0.135558,-0.286871,0.217417,-0.088669,-0.497116,-0.713806,-0.021288,-0.246625,-0.328134,-0.529012,-0.405462,-0.463409,-0.148097,0.010780,0.507822,0.310885,-0.384996,0.458983,0.466258,0.300074,-0.387589,0.409312,0.556377,-0.508675,0.026656,-0.071833,-0.424615,0.211306,-0.158736,-0.274347,-0.333470,0.316921,-0.045303,0.709772,0.500277,-0.144219,-0.048128,-0.246719,0.179752,-0.403302,0.078263,0.046021,0.737012,0.083622,0.309504,0.376236,-0.045417,0.060986,0.059564,0.203059,-0.551454,0.053589,0.205664,0.472175,-0.314626,0.375464,-0.126066,0.067111,0.118445,-0.216726,0.168630,0.537193,0.416844,-0.062717,-0.160437,-0.146948,-0.432437,-0.028267,0.696297,0.038488,-0.046771,-0.199828,-0.138007,-0.559472,-0.133452,-0.151066,-0.109479,0.072836,-0.178216,-0.090312,0.033513,0.193943,-0.374910,0.112215,-0.194064,-0.223460,-0.061278,-0.160481,0.305564,-0.739257,-0.084603,-0.180980,-0.403810,0.001733,0.107298,0.048557,0.526578,-0.522203,-0.262367,0.775073,0.386915,-0.650654,0.325361,0.406979,0.162773,-0.390384,-0.443618,-0.066227,0.171604,-0.036586,-0.213377,-0.006215,-0.138840,-0.540302,-0.121969,-0.189486', '25723905', '4193254', '1296947', '1299658');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306666', '黑店狂想曲', '喜剧', '一个虚构的年代背景，经济萧条，人人自危，甚至要以人肉为食物赖以生存。一幢破败的房子里住在屠夫一家。他们亦靠屠宰人肉为食。诡秘荒诞的色调下，屠夫挥舞着明晃晃的刀宰杀人肉。而这幢楼，还住着各式充满诡异色彩的人物：吃蜗牛的住客、对自杀非常迷恋的女人，爱切罐头的男子……他们说过，如果没有外来的食物补给，那么自己人的肉也不会放过，小丑路易（多米尼克•皮诺 Dominique Pinon 饰）前来打工，闯入了这个荒唐的世界，成为大家眼里的盘中餐。然而，屠夫的女儿（玛希罗蒂杜娜Marie-Laure Dougnac 饰）却爱上了他，并设法帮助他逃过大劫，这片世界开始陷入了混乱和崩溃之中。©豆瓣', '帕斯卡尔·贝内泽', '马克·卡罗', 8, 46955, 'tt0101700', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1969387376.jpg', 0.5, 2.5, 21.7, 48.1, 27.1, '0.210445,-0.003512,-0.616553,0.465224,-0.182609,-0.080593,1.036072,0.342397,-0.406627,-0.013889,0.249600,0.592273,-0.032485,0.137590,0.187540,0.084993,-0.209619,-0.371236,-0.018054,-0.157434,-0.126523,-0.251842,-0.323506,-0.495900,-0.041785,0.018919,0.466929,0.227645,-0.083661,0.089247,0.151289,-0.157614,0.069434,0.554192,-0.324297,-0.080384,-0.248604,-0.170700,-0.144760,0.098443,-0.202584,-0.155234,-0.026206,0.349581,-0.124726,0.259923,0.704449,-0.559896,-0.101212,-0.189181,0.102823,-0.228547,-0.142023,0.248406,0.108973,-0.228160,0.128503,0.033095,-0.198272,0.273252,0.229562,-0.072883,-0.880398,-0.122847,-0.042631,0.163849,-0.549227,0.499122,0.045398,0.032800,-0.114001,-0.300961,0.390500,-0.081507,0.425463,0.506692,-0.061512,-0.180686,-0.681716,0.173134,0.603923,-0.003052,-0.139223,0.173952,-0.504587,-0.361996,-0.102606,-0.273673,-0.572783,-0.201378,0.168938,0.024150,-0.349635,0.413804,-0.831625,0.078688,-0.082877,-0.214099,-0.120937,-0.259499,-0.347530,-0.434980,-0.003097,-0.231204,-0.193773,0.131766,0.153859,-0.110196,0.453417,-0.594156,0.160846,0.305324,0.487816,-0.154499,0.621714,-0.155994,-0.038846,0.022779,-0.590173,0.465452,0.153024,0.231530,0.196654,0.369215,-0.136226,-0.103564,-0.275433,0.574409', '21619567', '1293515', '1297996', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306670', '惊心食人族', '悬疑', '翠施（吉娜·菲利普斯 Gina Philips 饰）与戴利（贾斯汀·朗 Justin Long 饰）姐弟俩正驾车行驶在乡村公路上返家度假，无聊的二人彼此唇枪舌剑解闷，突然，一辆老旧肮脏的货车试图超车，令二人紧张一场。不久他们看到从货车上下来的人在路边小屋前，将一包带着血迹的东西丢入了一个管道，姐弟二人好奇心大起，不顾刚才被货车追逐的经历，悄悄返回小屋查看。戴利落入管道，发现包裹中居然是腹中被缝入了不明物体的活人，大惊失色的戴利与翠施迅速驾车离开，但一个长着翅膀的鬼影开始一路追踪他们。姐弟俩向路上遇到的各种人求助，这却使这场噩梦般的经历变得更加骇人……©豆瓣', '吉娜·菲利普斯', '维克多·萨尔瓦', 5.9, 9207, 'tt0263488', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1450528688.jpg', 7.6, 20.4, 47.1, 18.2, 6.8, '0.696330,-0.019499,-0.673930,0.446390,0.204522,-0.328707,1.186198,0.154641,-0.599083,0.089948,0.383984,0.596716,-0.547646,-0.000760,0.289365,-0.076532,-0.508146,-0.561397,-0.204568,0.026408,-0.536246,-0.321246,-0.200685,-0.189882,0.003587,-0.147427,0.290171,0.233314,0.127754,0.796283,0.324914,-0.017336,-0.693906,0.604981,-0.282785,0.193265,-0.195115,0.119545,0.111915,-0.164631,-0.110060,-0.511115,-0.088010,-0.103101,-0.155471,0.323941,0.884276,-0.023607,0.058268,-0.133268,-0.045348,-0.116373,0.018389,0.077509,0.292269,0.238434,-0.017240,-0.215993,-0.237401,0.072333,0.151305,0.166543,-0.308423,0.280221,-0.290863,0.161806,-0.811084,0.151445,-0.107850,-0.147871,0.181827,-0.520798,0.381528,0.178945,0.177744,0.293619,-0.118399,-0.266499,-0.696966,-0.346266,0.502768,-0.108528,-0.016819,0.362835,-0.250414,-0.170081,0.143529,0.240890,-0.395634,-0.349740,0.754318,0.088515,-0.348027,-0.058868,-0.817481,0.044930,-0.348621,-0.278661,0.067304,-0.127245,-0.321830,-0.819080,0.148622,-0.457309,-0.144543,0.359332,-0.188587,-0.126335,0.253370,-0.380323,0.067031,0.320400,0.090533,0.067478,0.521016,-0.573890,0.302975,0.048501,-0.017794,0.073255,0.178561,0.647503,0.272414,0.672863,-0.561520,0.309262,-0.497917,0.336681', '1578663', '10466639', '20451118', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306692', '枪王', '动作', 'Rick（张国荣饰）是个顶级射击手，自第一次参加IPSC实战枪击比赛起，已连获数届冠军，Rick的拿手好戏是double tap，即在最短时间内打出两枪，弹孔在同一点上。Rick还是个改良枪支的专家，经他改良后，枪的性能可发挥到最高点。苗志舜督查（方中信饰）同样是个射击好手，这一次，两人在IPSC比赛中各显身手，不相上下。附加赛中，一名炒股失败的警察突然精神失常，持枪威胁人群，危急关头，Rick果断地将其一枪击毙。枪杀他人给Rick带来了严重的心理负担，睡不着觉、头疼，甚至产生幻觉等症状让他寝食难安，而更可怖的是，心魔已经产生，他竟从杀人中获得了无与伦比的快感，任凭他如何努力摆脱，似乎依旧徒然……©豆瓣', '张国荣', '罗志良', 8.2, 73670, 'tt0258489', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1934400144.jpg', 0.2, 1.3, 18.7, 48.8, 30.9, '-0.065882,-0.010484,-0.669064,0.559446,-0.102647,-0.164390,0.819052,-0.311016,-0.305338,-0.194237,0.639165,0.590032,-0.293558,-0.087065,-0.002838,-0.388360,0.177154,-0.729302,-0.004148,0.128769,-0.646968,-0.275534,-0.449505,-0.014883,-0.075013,-0.214940,0.533976,0.100255,-0.601245,0.368318,0.263021,0.177139,0.403447,0.546468,-0.210718,-0.341469,-0.213865,-0.153518,0.032543,0.289896,0.253293,-0.728882,-0.257148,0.359066,-0.165589,0.213553,0.732347,-0.303011,-0.206753,-0.059844,0.505735,-0.195781,-0.267317,-0.014958,0.175531,0.154810,0.209670,-0.267370,-0.148282,0.306890,0.146233,0.142211,-0.791508,-0.091804,-0.122847,-0.148906,-0.438853,0.329922,-0.219227,0.045437,-0.093553,-0.018713,0.087208,0.069042,0.058707,0.254305,-0.636765,-0.239907,-0.463073,0.043117,0.607812,-0.222881,-0.325972,0.203915,-0.120755,-0.537912,-0.057845,-0.439725,-0.047090,-0.073117,0.528581,0.150731,-0.076791,0.167586,-0.295133,0.369533,-0.291653,-0.194407,-0.450304,-0.096683,0.089961,-0.454128,-0.089253,-0.174859,-0.496636,0.083314,0.103516,-0.302921,0.559160,-0.847542,-0.008358,0.385480,-0.127331,-0.109908,0.195566,0.116567,0.021040,-0.019674,-0.241572,-0.046493,0.191788,0.238622,0.196647,0.623748,0.006511,-0.116149,-0.260445,0.577654', '1301022', '1307800', '10486471', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306712', '开心鬼撞鬼', '喜剧', '生前是过气女歌星的女鬼徐半香（张曼玉），算准某名将要临盆的孕妇会于某间医院生产，准备投胎重新做人，不想，该孕妇被摇身变作某所高中教师的开心鬼（黄百鸣）送错医院，徐半香错过投胎时机。为泄心头之恨，徐半香开始想方设法捉弄开心鬼，最甚一次，她附身开心鬼班里女班长（袁洁莹），令她跑到夜总会稀里糊涂地大闹了一场，结果在该家夜总会寻欢作乐的一群流氓被抓，开心鬼受到无辜牵连，徐半香又得意又担忧之时，开心鬼却用爱来感化她，眼看皆大欢喜，出狱后的流氓不请自来。©豆瓣', '黄百鸣', '杜琪峰', 7.4, 39548, 'tt0091317', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1995010748.jpg', 0.4, 2.5, 37.7, 43.3, 16.1, '0.070597,-0.182711,-0.349006,-0.319778,-0.143613,-0.203040,0.588374,0.029357,-0.107327,-0.009601,0.169162,0.290786,-0.680765,0.435671,0.091499,0.059412,0.307522,-0.375396,0.170970,-0.159420,0.212403,0.494468,0.033832,-0.049020,-0.077877,-0.008482,-0.005921,0.080901,0.483856,0.237284,0.544579,0.381821,-0.096790,0.230217,-0.064745,-0.020290,-0.052997,-0.109760,0.186995,0.110452,0.084910,-0.115686,-0.104192,-0.032028,-0.197814,0.125174,0.517439,0.136837,-0.498814,-0.321544,0.620089,-0.351411,-0.160199,0.279761,0.252543,-0.295384,0.037613,-0.377586,0.041794,-0.172940,0.206118,-0.073992,-0.371341,0.172849,-0.018203,0.135984,-0.279400,0.273213,0.060480,0.350982,0.194134,-0.149981,0.051638,0.203785,0.424846,0.385175,-0.003630,0.115327,-0.296628,0.309927,0.689670,-0.198585,0.049741,0.453047,0.101395,-0.162508,0.664631,-0.394819,-0.325097,0.089162,0.385111,-0.176854,-0.398594,0.072879,0.035787,-0.397140,-0.089409,0.509611,-0.236105,-0.121477,-0.087564,-0.235722,0.054263,0.267775,0.093298,-0.020265,0.105088,-0.086694,0.234931,-0.491409,0.475390,0.670498,0.096634,-0.846520,0.374618,0.107669,-0.190154,-0.372850,-0.048530,0.161754,0.145050,0.378784,0.150079,0.134767,-0.279673,-0.302337,-0.449923,0.173668', '1305915', '1428876', '1309116', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306713', '丛林奇兵', '喜剧', '贝克（巨石 The Rock 饰）欠了比利一大笔高利贷，比利承诺只要贝克到亚马逊中部的黄金城把他辍学在外漂泊的儿子屈维斯（西恩•威廉•斯科特 Seann William Scott 饰）带回来即免除一切债务，贝克爽快地答应了。贝克在黄金城通过一名酒吧女招待玛丽安娜（罗莎里奥•道森 Rosario Dawson 饰）很快就找到了正在寻宝的屈维斯。就在他要带走屈维斯时，当地的黑社会老大赫切带着手下也来争夺屈维斯，原来屈维斯知道了当地的宝物“加托”的下落。贝克打跑他们后，带着屈维斯赶往机场回家。途中屈维斯企图开溜导致两人都落入了当地的叛军手中，原来玛丽安娜就是叛军首领，她也在寻找“加托”。为了顺利回家，他们只能答应先帮叛军找出“加托”……©豆瓣', '道恩·强森', '彼得·博格', 6.8, 10708, 'tt0327850', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2197177327.jpg', 0.9, 6.6, 54, 30.5, 8.1, '0.461712,0.073416,-0.485955,0.289921,0.166681,-0.761806,0.262256,0.291587,-0.237920,-0.153486,0.163323,0.711907,0.233046,0.064223,0.417206,0.432916,-0.740680,-0.380429,0.378933,-0.136356,-0.176603,-0.687852,-0.039559,0.027498,-0.110804,-0.165115,0.018095,-0.297215,0.100528,0.545990,0.262053,0.425075,0.207070,0.319964,-0.207345,0.281119,0.375926,-0.439441,-0.239606,0.171332,0.174801,-0.114662,-0.304380,-0.137863,0.591844,0.273174,0.378717,-0.137349,0.268922,0.078373,-0.391567,-0.231808,0.557660,0.153576,-0.057112,-0.411340,0.121617,0.129730,-0.526699,0.055023,0.309813,0.105016,-0.185847,0.193095,-0.214179,0.225792,-0.792817,0.134380,-0.274390,0.102272,0.353535,-0.372253,-0.122906,0.481436,-0.122452,0.019419,0.010817,-0.104821,-0.685721,-0.128122,0.365977,-0.200682,-0.203136,-0.353506,-0.008366,-0.136302,0.153983,0.144095,-0.274965,-0.275723,0.722858,0.082045,0.096062,0.033077,-0.679391,-0.215970,-0.618012,-0.280430,0.014723,-0.140690,-0.271873,-0.715841,0.054413,0.104861,-0.345676,-0.138640,-0.021139,0.112648,0.221491,-0.464359,0.428007,0.523187,0.224769,-0.456412,0.340802,0.238853,0.326626,-0.219836,-0.015604,0.072762,0.397364,0.753610,0.496771,0.221334,0.261510,-0.139599,-0.028697,0.586964', '1295684', '1292646', '1293511', '1418194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306723', '超人3', '动作', '超人又回来了！这次，超人克拉克（克里斯托弗•里夫 Christopher Reeve 饰）回家乡去参加高中同学聚会。聚会上，克拉克重遇了以前就一直心仪的女孩拉娜（安妮特•奥图勒 Annette O''Toole 饰）。爱火重燃的克拉克对拉娜展开了爱情攻势，两人很快就堕入了情网。正当两人浓情蜜意时，发生了一场灾难。本应马上出动的克拉克因为沉浸在和拉娜共处的时光而延误了救灾，导致了更多无辜的人们的伤亡，为此克拉克感到异常的自责。同时，野心勃勃的巨富利用气象卫星技术控制着世界各地的气候以此牟利，造成了很多地方天灾连连。他心知超人一定会来找自己的麻烦，于是不惜重金又制造出了一个超级电脑机器人用来对付超人。克拉克这次能否最终战胜邪恶？©豆瓣', '克里斯托弗·里夫', '理查德·莱斯特', 6.5, 5986, 'tt0086393', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2195975612.jpg', 2.3, 12.8, 54.3, 20.5, 10.1, '0.182651,0.032467,-0.613347,0.343507,0.055058,-0.413093,0.595949,0.023323,-0.209378,-0.265665,0.030231,0.677479,-0.210706,0.052922,0.301172,-0.262261,-0.518858,-0.520924,0.117246,-0.115371,-0.214683,-0.324995,-0.376109,-0.083063,0.158356,-0.325254,0.317736,0.112426,-0.140971,0.533546,0.131685,0.342066,0.244306,0.672908,0.115703,-0.127083,-0.018255,-0.029341,-0.186763,0.261056,0.096022,-0.188405,-0.066032,0.237826,-0.080462,0.229769,0.568288,-0.354042,-0.120330,-0.296618,0.386876,-0.384617,0.132910,-0.055639,0.209106,-0.074679,0.055991,-0.091859,-0.223194,0.099005,0.230539,0.053174,-0.715798,0.238220,-0.091173,-0.088918,-0.460429,0.225314,-0.002362,0.059931,0.063436,-0.256197,0.159888,0.593788,0.289974,0.154291,-0.281266,-0.136597,-0.537533,0.164663,0.787979,0.045431,-0.193635,0.190875,-0.098387,-0.348697,-0.012366,-0.227076,-0.336677,0.006477,0.589536,-0.071916,-0.079904,0.463656,-0.619388,-0.044665,-0.367131,-0.127482,-0.078100,-0.303826,0.081541,-0.896583,0.022068,-0.071590,-0.250741,-0.122759,0.127482,-0.172831,0.626700,-0.789738,0.093501,0.837480,0.282773,-0.372027,0.241039,0.018658,0.193143,-0.033323,0.023868,0.076641,-0.161721,0.413903,0.211400,0.250753,0.210583,-0.061525,-0.000279,0.549725', '11541282', '3178770', '3147969', '3735015');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306730', '钢琴教师', '剧情', '40岁的Erika Kohut（伊莎贝尔·于佩尔 Isabelle Huppert 饰）表面上是一个优雅的钢琴老师，外形独特、气质出众，但对学生却无比严厉。同时她的母亲专制又无理，无休止的折磨令Erika的各种欲望都无法发泄。于是Erika只好躲在厕所用剃刀伤害自己以求快感，嗅着内裤上的味道以发泄欲望，还去租看色情录像带。当18岁英俊冲动的Walter（伯努瓦·马吉梅 Benoît Magimel 饰）闯进她的生活时，一切都改变了。他们互相需索互相慰藉，Erika以为她终于找到了自己的幸福，然而年少的Walter有一日厌倦了这种关系……©豆瓣', '伊莎贝尔·于佩尔', '迈克尔·哈内克', 7.5, 61470, 'tt0254686', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195008349.jpg', 0.8, 4.1, 32.8, 44.2, 18, '0.280498,-0.055464,-0.499828,0.684784,-0.416028,-0.301968,0.829771,0.150270,-0.469305,-0.005197,0.116910,0.583577,-0.192383,0.469604,-0.113260,0.179258,-0.170230,-0.805896,-0.035691,0.139036,-0.098282,-0.148338,-0.202765,-0.089805,-0.023397,-0.285377,0.479893,-0.052950,-0.412495,0.316178,0.219163,0.002534,0.253725,0.734333,-0.349387,-0.277313,-0.174541,-0.046589,0.206278,-0.108901,0.239412,-0.501880,0.013807,0.417818,-0.144744,0.436013,0.809765,-0.250725,-0.228544,0.126207,0.522141,0.126087,-0.049371,0.637285,-0.060336,0.015201,0.000118,-0.070259,-0.274719,0.015796,0.165674,0.221648,-0.779629,-0.164947,-0.125771,0.026892,-0.497423,0.734469,-0.013293,-0.084020,0.173206,-0.138116,-0.090629,-0.186337,0.130914,0.462284,-0.374811,-0.090418,-0.472409,0.103416,0.620128,0.149388,-0.348773,0.365017,-0.751364,-0.294727,0.093680,-0.446144,-0.534941,-0.363671,0.092799,0.215499,-0.223666,-0.058843,-0.726774,0.109872,-0.028034,0.125344,-0.012531,-0.481167,-0.078204,-0.515327,-0.417316,-0.634176,-0.353201,-0.121837,0.194873,-0.322311,0.595884,-0.548637,0.054037,0.771822,0.236505,-0.400884,0.681187,0.155425,-0.235707,0.083067,-0.237702,0.549052,-0.269615,0.187976,0.252464,0.691692,0.025534,0.154728,-0.224218,0.746680', '35158375', '26754675', '30162520', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306733', '新精武门1991', '喜剧', '从小右臂就具神力的大陆青年刘晶（周星驰 饰）来港不久便接连遭遇倒霉事，先是钱包被偷，而后行李也遭人抢劫，不过也因此结识放荡不羁的潇洒（钟镇涛 饰）。刘晶四处寻找工作，却迟迟未定，甚至还卷入黑帮斗争之中。走投无路之际，刘晶和潇洒决定参加散打比赛，更阴差阳错拜入具有黑社会性质的赵东拳馆。在黑社会师傅（成奎安 饰）的带领下，二人随同前去夜袭霍家拳馆的霍环师傅，籍此机缘，刘晶得以拜入霍师傅门下。二人都对师傅的女儿嘉敏（张敏 饰）存有好感，也由此闹出不少笑话。然而门下大师兄（尹扬明 饰）嫉恨刘晶，设计陷害，致使刘晶被逐出师门。他的未来将何去何从……©豆瓣', '周星驰', '左颂升', 7.3, 50434, 'tt0103296', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2349523382.jpg', 0.6, 4.1, 41.2, 37.4, 16.7, '-0.084168,0.025018,-0.616417,0.386628,-0.109097,-0.361570,0.117323,0.160367,-0.556168,-0.275452,0.330649,0.634998,-0.072296,0.155185,0.198535,-0.146219,0.020969,-0.675979,0.086956,-0.056736,-0.202566,-0.129168,-0.097973,0.025347,-0.095709,-0.190454,0.340480,0.240156,-0.395916,0.684309,0.399806,0.158282,-0.411298,0.436160,-0.071385,0.268422,0.107350,0.463730,-0.225325,-0.086471,-0.139873,-0.478327,-0.062088,-0.135566,0.087251,0.347055,0.488950,0.123380,-0.233147,-0.415784,0.193056,-0.130213,-0.065954,0.152314,0.456969,0.268431,0.274860,0.409486,-0.080056,0.134334,0.086812,-0.019396,-0.325791,0.208659,0.334930,-0.311652,-0.485871,0.351243,-0.052766,-0.068570,-0.301051,-0.079557,0.166570,0.296827,0.229118,0.010461,-0.133331,0.033750,-0.349446,0.320298,0.371383,-0.232948,0.305767,-0.079734,0.147946,-0.237929,0.171612,-0.354723,-0.118476,0.047409,0.459278,-0.145564,0.051516,0.202992,-0.165277,-0.086710,-0.216000,0.301758,0.011781,-0.207150,0.290627,-0.603944,-0.060527,-0.026865,-0.274329,-0.110762,0.193425,-0.161636,0.604197,-0.374002,0.187314,0.109888,0.352213,-0.599243,0.400266,-0.006832,0.263590,-0.012059,-0.310242,0.065580,0.186770,0.175343,0.033747,0.192292,0.049454,-0.369161,0.062407,-0.132392', '26365262', '1294227', '25723081', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306737', '极限特工', '动作', '克桑德（范•迪塞尔 Vin Diesel 饰）是极限运动界的明星，但他离经叛道，总是以他的身手对社会上那些败类名流发出挑战，当地警方对他也经常无可奈何。特工头子奥古斯塔斯看上了克桑德，于是派人将他抓了回来，说服他前往捷克进行一项危险而艰巨的任务。捷克的地下犯罪组织头子尤里（马尔顿•索克斯 Marton Csokas 饰）正在进行一项疯狂的计划，他抓走了很多前苏联的科学家，利用他们研究一种威力无比的武器——毒气弹。他企图利用即将研制成功的武器引起世界大战，进而达到他统治世界的目的。克桑德以走私汽车贩子的身份前往捷克接近了尤里的组织，一场惊心动魄的行动展开了！©豆瓣', '范·迪塞尔', '罗伯·科恩', 7.3, 61002, 'tt0295701', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p972392728.jpg', 0.6, 4, 37.9, 43.4, 14.2, '0.347867,0.168327,-0.665663,0.657787,-0.283118,0.109064,0.455514,-0.116364,-0.507190,-0.026608,0.283401,0.488849,0.135368,-0.125175,0.251304,-0.158289,-0.339248,-0.618063,0.061968,0.000421,-0.363848,-0.388984,-0.507511,-0.506235,-0.077907,-0.226476,0.515553,0.070273,-0.548469,0.166336,0.321775,0.546305,0.247691,0.567752,0.019710,-0.376827,0.504596,-0.368000,-0.168829,0.313435,0.003928,-0.390573,-0.103287,0.391994,-0.128008,0.348124,0.563600,-0.239903,-0.020888,-0.407328,0.185912,-0.598417,-0.005300,0.102652,0.268447,0.181975,-0.201688,0.167644,0.068858,0.053920,0.031637,-0.129835,-0.740184,-0.111538,0.192296,-0.064872,-0.483448,0.063505,-0.394404,0.223727,-0.366174,-0.424888,0.108263,0.343124,0.425774,0.066742,-0.017799,-0.017379,-0.613176,0.150089,0.676859,-0.175202,-0.230868,-0.124152,-0.174768,-0.554982,-0.225132,-0.413294,-0.155976,-0.185353,0.607999,-0.402427,-0.137431,0.323324,-0.751165,0.002466,-0.398677,-0.352621,-0.176282,-0.236981,0.227288,-0.904049,0.008551,-0.338754,-0.359705,0.002601,0.296990,-0.268871,0.726920,-0.610503,-0.006047,0.874057,0.211633,-0.522814,0.173321,-0.106139,0.029569,-0.341694,-0.211104,0.211119,0.213058,0.382531,-0.018415,0.440267,0.372716,-0.267788,0.088388,0.668189', '1306723', '1309112', '4014397', '1292829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306755', '庙街十二少', '剧情', '黑社会大佬（吕良伟饰）跑路之前将自己刚出世的婴孩托付给契夫唐秋水（吴孟达饰），起名为唐十二（刘德华饰），从此人们都称他做十二少，因为他有十二个黑白两道的契父契妈，表面上他上天之骄子，但内心比谁都寂寞。养大他的契父唐秋水是庙街的百搭替工，还有一个可能是亲母的龟婆叫凤凰女（叶德娴饰），她是全庙街最麻烦的女人，当年同月同日舍弃了自己的儿子在庙街。他有一个世仇叫立令，是官涌的霸王，他比魔鬼还可怕。一天，十二少遇见一个来庙街传道的女子叫德兰（王祖贤饰），由第一眼开始，他便爱上她……©豆瓣', '刘德华', '蒋家骏', 6.4, 5644, 'tt0105174', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515744305.jpg', 1.4, 10.9, 60.4, 20.2, 7.1, '0.051752,-0.100960,-0.703779,0.492087,-0.450479,-0.388373,0.717738,0.049201,-0.437052,0.088410,0.184944,0.814454,0.106673,0.338254,0.009578,0.260392,0.194935,-0.546073,0.014397,-0.220262,-0.077714,-0.147728,-0.160184,-0.095028,-0.130015,-0.153948,0.132965,-0.007854,-0.140390,0.024539,0.685558,0.099066,0.123546,0.346567,-0.430602,0.093100,-0.318782,0.309555,0.156247,0.139099,-0.314757,-0.206237,-0.113858,0.127256,-0.133022,0.457836,0.288920,-0.365117,-0.061877,-0.386713,0.267450,-0.127590,-0.305700,0.121654,0.349343,-0.205368,0.086883,0.109432,-0.107473,-0.085967,0.098426,0.063070,-0.560459,-0.171851,0.162106,0.173802,-0.732236,0.365115,-0.156315,-0.043339,0.141566,-0.426068,0.290022,0.057119,0.064077,0.027925,0.010201,-0.155333,-0.695472,0.376026,0.624744,0.204728,-0.053675,0.185775,-0.062245,-0.450453,-0.082352,-0.336089,-0.547806,0.000978,0.290825,-0.307602,-0.017380,0.021393,-0.287260,0.061436,0.092118,-0.012775,-0.150657,-0.246114,0.090229,-0.128405,0.015247,-0.684498,-0.364954,-0.075544,0.231861,-0.487923,0.890591,-0.684281,0.403923,0.393250,0.081346,-0.555097,0.690505,0.227073,0.075850,-0.105272,-0.000805,0.043308,0.152991,0.210675,0.004786,0.589325,-0.232534,-0.000942,-0.161388,0.556389', '30162520', '1292720', '1783772', '5262027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306762', '十一罗汉', '喜剧', '赌城拉斯维加斯，除夕夜。轮盘赌盘在疯狂地旋转，纸牌的劈啪声愈发刺耳。老虎机鸣响，香槟酒气熏天。突然间，灯火骤熄，一片黑暗。这是一个多么完美的时刻，无论你是去偷吻香艳的女郎还是顺手牵羊地私密几张钞票。当然，对于丹尼·奥逊（弗兰克·辛纳特拉 Frank Sinatra饰）和他的十一个犯罪团伙来说，这更是一个偷天换日的绝佳盗窃机会。以丹尼为首的十一罗汉，均是二战退伍后最优秀的空降部队成员，个个身怀绝技。丹尼伙同山姆·哈蒙（迪恩·马丁 Dean Martin饰）、约什·霍华（小萨米·戴维斯 Sammy Davis Jr.饰）、吉米·福斯特（彼特·劳福德 Peter Lawford饰）和康纳斯（乔伊·毕晓普 Joey Bishop饰）等人，开始了一场有史以来最大的赌场抢劫案。然而这场看似天衣无缝的“完美”盗窃案，却纰漏百出、波澜起伏。由好莱坞著名导演刘易斯·迈尔斯通执导的1960版犯罪喜剧影片《十一罗汉》，荣获1961年美国制片人金桂冠奖提名及1961年美国编剧协会荧幕编剧奖提名。', '弗兰克·辛纳特拉', '刘易斯·迈尔斯通', 7.8, 4980, 'tt0054135', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171084378.jpg', 0.1, 1.7, 27, 49.1, 22.1, '0.071983,-0.034362,-0.557343,0.551989,0.234409,-0.306741,0.737314,0.131209,-0.342236,-0.117236,0.304216,0.783233,-0.472988,-0.095453,0.345922,0.079987,-0.339250,-0.633280,-0.169883,-0.082058,-0.068911,-0.407556,-0.335570,-0.068199,0.034964,-0.030421,0.278745,0.009941,-0.074697,0.310025,0.669643,0.175732,-0.003348,-0.034582,0.072454,-0.148187,0.433517,-0.118009,-0.247310,0.113986,-0.109333,-0.301331,-0.329127,-0.026945,-0.064878,0.198260,0.454137,-0.372689,0.257703,-0.047357,0.293529,-0.186992,-0.344702,-0.149760,0.148042,-0.106354,0.317957,0.155874,-0.022414,0.019364,0.197611,-0.081313,-0.582357,0.173237,0.185457,0.103486,-0.300595,0.166868,-0.375305,0.162751,0.052969,-0.133814,-0.080100,-0.042121,0.235108,0.237772,-0.017171,0.152012,-0.270305,0.349824,0.150329,0.087118,-0.335343,0.207297,-0.112715,-0.605058,-0.148377,-0.184089,-0.256424,0.019655,0.551610,-0.299084,0.400157,0.134126,-0.648946,0.040857,-0.219345,-0.277486,-0.174742,0.000793,-0.175266,-0.924593,-0.053472,-0.268413,-0.307661,-0.046691,0.063211,0.114870,0.568056,-0.391775,0.092264,0.429335,-0.337750,0.264257,0.454048,0.181611,0.062604,-0.252649,-0.350257,-0.057590,0.113012,0.000992,-0.014592,0.386869,0.020275,-0.272532,-0.017289,0.344021', '6517421', '3318306', '34961898', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306769', '宝莱坞生死恋', '剧情', '生在地主家的德夫达（沙鲁克‧可汗 Shahrukh Khan 饰）和平民女子帕罗（艾西瓦娅·雷 Aishwarya Rai 饰）从小青梅竹马，但由于德夫达被送到伦敦读书，二人一别多年。到了德夫达学成返乡，帕罗已经长成光彩照人的美貌少女，他们的爱火仍旧炙热，但是德夫达家人对于帕罗母亲的提亲表现出傲慢和轻蔑的姿态，深深伤了少女的心。德夫达迫于父命难为时，帕罗已经决定嫁给一个豪门鳏夫，追悔莫及的德夫达开始终日酗酒，流连花丛，相思成疾，而帕罗需要恪守妇道，只能把爱和遗憾埋在心里。自暴自弃的德夫达终于送掉自己性命，临死之前，他强撑到大门外想要再见帕罗一面……©豆瓣', '沙鲁克·汗', '桑杰·里拉·彭萨里', 8.3, 12785, 'tt0238936', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2196649876.jpg', 0.5, 2.1, 18.3, 41.9, 37.1, '0.013352,0.107963,-0.556392,0.306775,-0.260802,-0.585533,0.701136,0.187669,-0.505706,-0.081768,0.089374,0.819062,-0.081552,0.396343,0.397443,0.163129,-0.075155,-0.637104,-0.039682,-0.114440,0.080468,-0.453058,0.088227,-0.088294,-0.318055,-0.350590,0.643473,0.197962,0.193471,0.555609,0.198588,0.363768,0.042472,0.278113,-0.342645,-0.011052,-0.241025,0.025597,-0.303716,0.033788,0.209315,-0.236675,-0.312792,-0.041799,0.152261,0.381748,0.459548,-0.193130,-0.031518,-0.100552,0.306380,-0.024330,-0.047653,0.463506,0.046318,-0.299818,0.188429,-0.073203,-0.283443,-0.008319,0.048552,-0.181225,-0.257692,0.024099,0.117775,-0.062876,-0.647886,0.647489,-0.186150,-0.024690,0.191841,-0.379855,0.015584,-0.094600,-0.204295,0.378820,-0.556034,0.044252,-0.565447,-0.004285,0.412459,0.120838,-0.188855,0.201341,-0.159292,-0.235307,0.127888,-0.469421,-0.563519,-0.060194,0.189641,0.239295,-0.291415,0.326155,-0.376566,-0.264195,-0.266128,0.104182,0.058616,-0.441501,-0.296401,-0.099090,-0.186504,-0.425713,-0.351148,0.278192,0.193326,-0.084784,0.522990,-0.709678,0.405285,0.134067,0.229424,-0.515588,0.512489,0.234069,0.195838,0.079366,-0.103365,0.619063,-0.081157,0.116610,0.144237,0.166881,-0.225214,0.028054,-0.360262,0.439799', '3111650', '1292720', '1292207', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306785', '极地特快', '动画', '信则灵。小男孩始终坚信圣诞老人的存在，但周围的大人和玩伴都认为这只是他天真的一厢情愿。圣诞前夕，小男孩终于因为他的坚持而得到了回报，睡梦中的他忽然感到屋子颤抖起来了，一列长长的火车停在了他的家门口。当他战战兢兢打开房门时，和蔼的列车长邀请他参加北极的圣诞派对。惴惴不安的克 劳斯踏上了火车，发现很多和他一样的小伙伴们。于是，兴奋不已的小男孩开始了他的北极狂欢之旅。©豆瓣', '汤姆·汉克斯', '罗伯特·泽米吉斯', 7.7, 48928, 'tt0338348', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1493942019.jpg', 0.4, 3, 29.9, 43.6, 23.1, '0.439575,0.167805,-0.982348,0.355086,-0.024507,-0.281163,0.797804,0.094507,-0.411866,-0.078076,0.263286,0.876881,-0.476144,0.628906,0.516494,0.134856,-0.375762,-0.547193,-0.148441,-0.165799,-0.254292,-0.044522,-0.111441,-0.255022,-0.184598,-0.127758,0.454041,0.251513,0.145923,0.863389,0.408547,-0.051061,0.223678,0.603700,-0.409984,0.017442,-0.007898,0.093356,0.276942,-0.201828,-0.033263,-0.044549,-0.178037,0.407789,-0.009827,0.482293,0.404593,-0.498195,-0.190969,0.084220,0.228148,-0.430212,0.060051,0.138097,0.216135,0.376519,0.105475,-0.098961,0.088596,-0.192560,-0.087028,0.262928,-0.361752,0.220166,-0.104141,0.217466,-0.617560,0.470201,0.113121,0.053904,0.128812,-0.344208,0.360590,0.419933,-0.142655,0.373217,-0.322831,-0.216150,-0.491323,0.031433,0.436918,-0.133182,-0.194235,0.564313,-0.308528,-0.431970,0.211511,0.078223,-0.552228,-0.076256,0.265319,0.113576,-0.234160,-0.091286,-0.498623,-0.045706,-0.121907,-0.333997,-0.132817,-0.369430,-0.369061,-0.617196,0.196892,-0.252418,-0.088322,0.092209,-0.207412,-0.308421,0.658841,-0.819376,0.326471,0.610881,0.140127,-0.222281,0.801517,-0.049596,-0.199853,-0.110335,-0.034689,0.105833,-0.112913,0.519134,0.155829,0.565098,-0.192012,0.006272,-0.453949,0.607424', '1296534', '3111650', '1292211', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306795', '西蒙妮', '剧情', '好莱坞导演维克多（阿尔•帕西诺 饰）曾经大名鼎鼎，有过辉煌的历史。他的影片曾获过奥斯卡提名。然而，时运不济，一心追求艺术的他，却遭到大牌明星的罢演，就连一直支持他艺术的前妻也将他解雇。眼看着维克多的新片《日出日落》即将胎死腹中。也许是上帝的眷顾吧，一位天才程序设计师神秘地出现在维克多面前，交给他一套可以设计出高度逼真的三维动画的程序。利用它，维克多创造出了一个让全世界，无论是男人还是女人都狂热喜爱的“完美女人”——Simone。Simone一夜之间迅速走红，成为全世界追随的超级偶像。可是，人们并不知道，他们日夜追捧的“完美女人”，其实并不存在于现实世界。虚拟背后的危机，随之攀升……©豆瓣', '阿尔·帕西诺', '安德鲁·尼科尔', 7.3, 14467, 'tt0258153', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1348830808.jpg', 0.4, 3.6, 37.8, 44.7, 13.5, '0.005151,0.280449,-0.886187,0.710786,-0.247457,-0.065460,0.643297,-0.088947,-0.349550,-0.144133,0.417927,0.876353,-0.287329,0.137831,0.450654,0.151462,-0.162159,-0.787256,-0.148650,-0.078080,-0.073431,-0.289401,-0.641498,-0.273482,-0.226093,-0.380934,0.891279,0.076304,-0.323594,0.002714,0.606095,0.105040,0.089881,0.347863,-0.160519,-0.169162,0.133451,-0.016038,-0.434873,0.234926,-0.146666,-0.252398,-0.009742,0.210510,-0.476029,-0.119346,0.229729,-0.440144,-0.121080,-0.110271,0.799529,-0.299368,-0.097618,-0.047626,0.138389,-0.085806,0.216188,0.121228,0.186163,-0.069688,0.071375,-0.194573,-1.131923,-0.079740,0.224540,0.125191,-0.486220,0.410355,-0.099497,0.033189,-0.004739,-0.223190,0.102203,-0.181376,0.551297,0.286199,-0.141779,0.229636,-0.377715,0.516728,0.417845,0.246264,-0.572214,0.232554,-0.333141,-0.400933,-0.365321,-0.525844,-0.781152,0.277106,0.086810,0.060003,-0.098300,0.339390,-0.454707,0.117887,-0.026355,-0.183488,0.131412,-0.458841,-0.080776,-0.529410,-0.156193,-0.344794,-0.214705,-0.234963,0.012308,-0.578547,1.036060,-0.768438,0.275024,0.701781,0.240049,-0.590537,0.918070,0.101819,-0.191385,-0.212868,-0.289223,0.280665,-0.064548,0.073911,-0.155448,0.268701,0.142773,-0.242343,-0.162612,0.836616', '27602116', '30279170', '24284209', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306799', '恋战冲绳', '剧情', 'Jenny（王菲）意识到自己对身边的黑帮老大伊藤已无爱时，带着伊藤一大笔钱来到冲绳。这笔钱本是国际大盗唐杰（张国荣）帮伊藤在警察证物室偷回一本写满伊藤艳史的日记本的费用，Jenny的携带逃离令他无计可施。香港警局档案室探员罗宏达（梁家辉）和其女友Sandy（黎姿）在冲绳度假，认出唐杰是警方通缉的要犯，为获晋升机会，他佯装与唐杰合作爆窃冲绳一家银行，以便将其逮捕。计划中，要利用银行隔壁的房屋来进行爆破，而Jenny恰好就住在里面。因为两人都逐渐爱上Jenny，事情开始变得复杂。©豆瓣', '张国荣', '陈嘉上', 7.3, 40592, 'tt0258850', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p482168903.jpg', 0.7, 5.2, 38.7, 37.1, 18.3, '0.181170,-0.096206,-0.580825,0.515236,-0.172295,-0.084637,0.503862,0.028756,-0.529101,-0.171245,0.213124,0.740326,0.013059,0.372784,0.292358,0.162976,-0.292611,-0.709121,-0.149426,-0.390498,-0.103818,-0.516683,-0.162176,-0.258634,-0.134996,-0.015200,0.568070,0.150623,-0.226480,0.364827,0.191720,0.215704,-0.422156,0.533140,0.080955,-0.030893,0.218533,-0.143714,-0.330985,0.430749,0.101165,-0.396920,-0.053501,0.103234,0.227997,0.262887,0.625987,0.289934,0.019333,-0.017674,0.250912,-0.228801,-0.122351,0.020464,0.466548,0.051826,0.045946,0.296471,-0.650936,-0.037012,0.186562,-0.094007,-0.579865,-0.079508,0.080292,0.072423,-0.353292,0.141155,-0.491809,0.244587,0.209947,-0.337336,0.163294,0.408547,0.246779,0.208990,-0.122609,0.057965,-0.555867,0.134713,0.181301,-0.303665,0.387895,0.109742,0.049243,-0.434953,-0.145618,0.107264,-0.054777,-0.274385,0.358323,0.029082,-0.125626,-0.054863,-0.363362,-0.319426,-0.266493,-0.238411,-0.041981,-0.205757,-0.008480,-0.910499,-0.235921,-0.054585,-0.061397,0.212214,0.242129,-0.209969,0.215187,-0.557251,-0.097125,0.607987,0.398149,-0.375822,0.430680,-0.073087,0.076948,-0.280959,-0.204094,-0.154765,0.426261,0.679360,0.188635,0.101646,0.025035,-0.208413,-0.016809,0.258939', '25723905', '2028645', '1307897', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306801', '我聘请了职业杀手', '剧情', '在为公司勤勤恳恳工作了十五年之后，亨利（让-皮埃尔·利奥德 Jean-Pierre Léaud 饰）却落得了一个被解雇的悲惨下场。心中充满愤懑的他在生活里也四处碰壁，绝望之中，他想到了自杀。可是，无论他使用什么法子，都无法成功赴死，就在这时，他在报纸上看到了一间聚集着黑道分子和杀手的小酒馆，他决定去那里试一试。亨利雇佣了一名杀手（肯尼斯·考利 Kenneth Colley 饰），让他来取自己的性命，然而，在此之后，亨利意外的邂逅了名叫玛格丽特（Margi Clarke 饰）的美丽卖花女孩，两人迅速擦出爱情的火花。生命有了继续下去的意义，亨利不想死了，然而，他却怎么也找不到当初和他签订了合约的杀手，这也就意味着，从此刻开始，他随时都有可能遭到杀手的暗杀。©豆瓣', '让-皮埃尔·利奥德', '阿基·考里斯马基', 7.7, 5872, 'tt0099818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p842073336.jpg', 0.4, 1.7, 26.5, 54.8, 16.7, '0.201553,0.211532,-0.962049,0.487321,-0.402802,-0.406010,0.849942,0.041393,-0.421137,-0.047311,0.281537,0.835346,-0.068915,0.168104,0.110233,0.080463,-0.222511,-0.797414,0.175687,-0.285561,-0.420348,-0.405947,-0.251184,-0.417329,0.047233,-0.109073,0.465083,0.262083,-0.063710,0.244185,0.394498,0.344028,0.202378,0.749706,-0.153576,0.125313,0.070342,-0.005756,0.013541,0.317083,0.304380,-0.458912,-0.300136,0.381595,-0.108727,0.533194,0.507083,-0.125322,-0.093880,0.105037,0.195272,-0.274207,-0.037351,0.266596,0.273982,-0.200867,-0.060879,0.139061,-0.299210,-0.050068,0.124942,0.258429,-0.972680,0.074923,-0.103529,0.277693,-0.850348,0.588879,-0.281075,-0.066292,-0.037605,-0.371649,0.278251,0.151092,0.346465,0.177044,-0.221435,-0.107330,-0.729245,0.246993,0.825126,0.075120,-0.160118,0.302382,-0.105957,-0.379069,-0.186666,-0.300504,-0.289718,-0.082336,0.435877,0.056553,-0.403623,-0.009050,-0.589770,0.004716,-0.301624,-0.119650,-0.226295,-0.382914,-0.105656,-0.328338,-0.058481,-0.062496,-0.571849,0.254698,0.009367,-0.205382,0.632915,-0.783418,0.101763,0.637158,0.388299,-0.447664,0.696023,0.119283,-0.017965,0.061788,0.004151,0.138762,0.097895,0.504305,0.467990,0.282439,0.181872,-0.014587,-0.147290,0.616920', '1292584', '1299932', '1947080', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306802', '精灵鼠小弟2', '喜剧', '经过了两年的共同生活，如今斯图亚特和乔治一家过得融洽和睦，斯图亚特还是一如既往的聪明精灵，然而内心却为了一件事有点不安——乔治母亲添了小女儿，他们对这个千金宠爱有加，几乎花掉全部时间精力。而乔治功课也日渐繁忙，陪伴斯图亚特的时间也少了。斯图亚特有点落寞，直到它遇上了鸽子玛格罗。斯图亚特上演了一幕英雄救美，把玛格罗从危难中解救出来，并带她回家疗伤，心里对她暗暗倾慕。然而斯图亚特的恋爱并不是特别顺利，他不知道玛格罗有着不为人知的秘密，这只机智勇敢的小白鼠面临着又一次充满挑战的冒险。©豆瓣', '迈克尔·J·福克斯', '罗伯·明可夫', 7.3, 43883, 'tt0243585', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220872415.jpg', 0.3, 2.8, 44.5, 38.9, 13.6, '0.004295,-0.188756,-0.636052,0.458354,0.168586,-0.518164,0.927615,-0.161189,-0.730296,-0.363381,-0.100796,0.551043,-0.285180,0.343842,0.254934,0.039444,-0.522307,-0.376417,0.226803,-0.102199,-0.010574,-0.517493,-0.182906,-0.500195,-0.238103,-0.393183,0.244985,0.158201,0.224787,0.539802,0.262080,0.197617,0.257658,0.672080,-0.187201,-0.111895,0.032431,0.031419,-0.067713,-0.058148,0.572560,-0.087430,-0.331664,0.421290,0.454950,0.454448,0.395972,-0.257647,-0.185435,0.048864,0.258753,-0.472279,-0.143199,-0.026161,0.118253,-0.112304,-0.067979,0.093502,-0.184334,-0.015344,0.001035,-0.214741,-0.655351,0.164985,-0.183556,-0.056977,-0.401833,0.529209,0.055873,0.062187,0.206590,-0.346564,0.071365,0.307447,0.315888,0.284575,-0.303066,-0.023082,-0.491701,-0.086473,0.759569,-0.025377,0.005717,0.733929,-0.467322,-0.601530,0.115241,-0.413576,-0.441323,0.019854,0.199799,0.117249,0.084137,0.662288,-0.456595,0.171876,-0.385673,-0.357453,-0.006577,-0.644338,0.159684,-0.262449,-0.407451,-0.637072,-0.575571,0.035547,0.133346,-0.365346,0.567647,-0.724154,0.218944,0.395853,0.126948,-0.461617,0.489997,0.325957,0.200937,-0.074336,-0.104915,0.382992,-0.023331,0.128181,0.120937,0.271818,0.125924,-0.097418,-0.337563,0.573489', '3059036', '1308755', '35441371', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306808', '咒怨', '悬疑', '东京近郊一间屋被传是阴森鬼屋，说但凡拜访者进入，都会离奇毙命或神秘失踪。传说当年该屋的主人曾因突至的狂性大发斩死妻子，尔后自杀，其6岁的儿子从此失踪，至今下落不明，鬼屋自此怨气冲天，每一位到访者都会在瞬间被恐怖笼罩。大学女生理佳（奥菜惠）因做义工无意间闯入该屋，在遍寻不着要照顾的老人后，她于无意间瞥见一个神秘诡异男孩，但转眼男孩又失踪。自此，诸多恐怖怪事开始接二连三在理佳身上发生，其身边的亲朋好友也一一受到牵连。©豆瓣', '奥菜惠', '清水崇', 7.5, 144995, 'tt0364385', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2410260517.jpg', 1.3, 4.5, 31.7, 41.2, 21.3, '0.116687,-0.044995,-0.719449,0.069591,-0.067300,0.055103,0.940954,-0.033011,-0.733018,-0.552538,0.323405,0.871121,-0.434194,0.325891,0.271889,-0.055669,0.347932,-0.450709,-0.161082,-0.361144,-0.330794,0.055130,-0.073924,-0.186468,-0.112487,-0.441337,0.020061,0.181932,-0.203592,0.378814,0.321819,0.576523,-0.606880,0.403143,-0.371196,0.070988,0.047356,0.222528,0.149173,0.258765,-0.251521,-0.582316,-0.003344,-0.077586,-0.378491,0.267366,0.564332,0.065245,-0.482049,-0.281953,0.615877,0.096403,-0.256326,0.235663,0.739907,0.099472,0.460495,0.171454,-0.142589,-0.350725,0.103835,0.075692,-0.455341,0.027780,0.308502,0.121760,-0.264962,0.134865,0.185199,-0.027543,0.052094,-0.131569,0.343841,0.287276,0.010474,0.325218,0.073666,0.043048,-0.219076,0.264818,0.687597,-0.406599,-0.220784,0.083789,0.239210,-0.238261,0.334985,-0.184516,-0.375848,0.402615,0.332676,0.177628,-0.141519,0.424493,-0.161040,-0.071535,-0.303642,0.103667,-0.138109,-0.012228,-0.589359,-0.210560,-0.068488,0.027269,-0.172016,0.345588,-0.049552,-0.004213,0.353035,-0.643926,0.635996,0.331704,0.153669,-0.390388,0.429493,-0.188242,0.247730,0.077427,0.105320,0.338068,0.421854,0.294666,-0.070859,-0.011197,-0.041624,-0.106538,-0.306126,0.047759', '1296534', '1309297', '3011051', '30257386');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306809', '生化危机', '动作', '为军方研究生化武器的安布雷拉公司在浣熊市地下设有巨大的研究中心——蜂巢，由于一次意外事故导致可通过空气传播的生化武器泄露，负责蜂巢安保的电脑系统“红色女王”启动应急措施，却导致数百名工作人员罹难……四小时后，蜂巢安保人员爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）在蜂巢出口醒来，并且因为催眠气体而失忆。一支受命关闭红色女王的特种小队来到此处，与爱丽丝、自称警察的安德森，以及蜂巢工作人员帕克斯组队深入地下。一行人因任务目标与红色女王冲突而先后遭遇保卫系统和丧尸的连番袭击，而爱丽丝渐渐恢复的记忆揭示了她与同行者非同一般的联系。这场生化丧尸危机该如何解除？又或者根本是一曲绝望的前奏？本片是根据知名电子游戏《生化危机》改编而成系列电影的首部。©豆瓣', '米拉·乔沃维奇', '保罗·安德森', 8.2, 330544, 'tt0120804', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2174120073.jpg', 0.2, 1.2, 17.4, 49.4, 31.8, '0.161783,0.096038,-0.536417,0.408019,0.214069,0.111505,0.673782,0.006056,-0.421614,-0.368209,0.323545,0.406123,-0.212899,-0.287496,0.073918,-0.199708,-0.378698,-0.407624,-0.284173,-0.231207,-0.466443,-0.483775,-0.158805,-0.396460,0.412793,-0.527194,0.817875,0.170103,-0.405789,0.184726,0.001440,0.452042,-0.674558,0.217706,0.350260,-0.254987,0.178397,-0.260316,-0.264859,0.228720,-0.175612,-0.179583,0.167817,0.020665,-0.012452,0.307980,0.781403,-0.401038,-0.077892,-0.292819,0.339744,-0.403520,0.019999,-0.228724,0.629814,0.243892,0.106926,0.045599,-0.076830,0.165010,-0.000444,-0.096750,-0.546692,-0.144093,-0.123008,0.278807,-0.298126,0.029224,-0.227472,0.119736,0.152874,-0.083694,0.161553,0.529419,0.367098,0.254616,-0.156126,0.100406,-0.311107,0.114496,0.481159,-0.176987,-0.398739,0.110047,-0.023972,-0.576717,-0.237059,0.092361,-0.115439,-0.080454,0.297328,0.242377,-0.021596,0.169304,-0.869402,-0.038156,-0.473591,-0.438136,-0.106452,-0.131963,-0.029417,-1.249026,-0.049055,0.106853,-0.058951,0.125466,0.059826,0.012387,0.380851,-0.793027,0.402309,0.479853,-0.041822,-0.555069,0.022197,-0.168499,0.149959,-0.349151,-0.015184,0.171439,0.193054,0.546436,-0.064665,0.105095,0.083443,-0.312679,-0.423766,-0.106509', '2369613', '1307897', '20274039', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306830', '血色清晨', '剧情', '故事发生在地处偏远的贫穷山村之中，少女红杏（孔琳 饰）还未真正迎来自己的美好青春年华，便被两个哥哥李平娃（赵军 饰）和李狗娃（解衍 饰）以“换亲”的方式许配给了村里的万元户张强国（龚朝辉 饰）。新婚之夜，张强国指责红杏并非处女之身，将她退了回去，并且强行带走了作为交换的姐姐。愤怒的李平娃将红杏暴打一顿，却问不出个所以然了。平日里，小学教师李明光（胡亚捷 饰）和红杏交往甚密，李平娃觉得一定是这个衣冠禽兽夺走了红杏的贞洁，于是发出了“杀人预告”。然而，由于李平娃兄弟两人平日里懦弱无能，所以并没有村民相信他们会真的将威胁付诸于行动，悲剧就这样发生了。©豆瓣', '赵君', '李少红', 8, 7211, 'tt0105863', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1263506579.jpg', 0.6, 1.7, 18.6, 54.2, 25, '0.292720,0.258766,-0.545048,0.482085,-0.244248,-0.343984,0.764373,-0.150959,-0.417336,-0.164083,0.047685,0.303385,-0.192033,0.298837,-0.019253,-0.037665,-0.047126,-0.670579,-0.155058,-0.158501,-0.153244,-0.486875,0.018124,0.023052,-0.203692,0.085012,0.392451,0.050856,-0.455634,0.132497,0.281863,0.100624,0.065645,0.447608,-0.124554,0.216042,-0.225869,0.143231,-0.168344,-0.040525,0.196528,-0.627255,-0.200418,0.234399,0.104793,0.501110,0.478674,-0.525222,-0.138863,-0.102510,0.318312,-0.287836,-0.047090,0.330808,0.131025,-0.360501,0.173706,-0.117923,-0.117772,-0.095944,0.210247,-0.001755,-0.382515,0.300895,0.233051,0.053230,-0.674411,0.157621,-0.178228,0.065485,0.105986,-0.345133,0.295961,0.098801,0.501280,0.344142,-0.123122,0.041526,-0.615204,0.324430,0.636628,-0.011879,-0.274954,0.089012,-0.234662,-0.474442,0.151590,-0.213783,-0.293263,0.032992,0.403834,-0.012699,-0.091353,0.096360,-0.417786,-0.147103,-0.146612,0.045873,0.157046,-0.285431,-0.102718,-0.105122,0.012498,-0.406493,-0.393209,0.156191,0.238015,-0.071566,0.558664,-0.709549,0.062139,0.240335,0.423668,-0.503950,0.336454,0.111541,0.060448,0.075040,0.307710,-0.070892,0.034822,0.302774,0.397534,0.360464,-0.014573,-0.136372,-0.151149,0.325954', '1301022', '1308755', '3111650', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306860', '高斯福庄园', '剧情', '1932年11月的英国。高斯福德庄园是一个名流云集之地， William McCordle爵士和他的妻子Sylvia约请了亲朋好友进行了一个狩猎会。邀请的客人包罗万象：伯爵夫人、一战英雄、英国音乐偶像，以及正在拍摄《陈查利》影片的美国电影制片人。当客人们聚集在楼上金碧辉 煌的画室时，侍候他们的贴身男女仆人们排站在硕大的住宅内，而佣人们则挤满了厨房和楼下的走道。随着一声尖叫，爵士死了。在调查此案的过程中，发现各人与各人之间隐藏着深不可测的矛盾，而事实的真相不叫人惊讶，叫人惊讶的是所谓的名流背后那些不堪入目的真面目。©豆瓣', '玛吉·史密斯', '罗伯特·奥特曼', 7.8, 22004, 'tt0280707', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1452864263.jpg', 0.6, 2.8, 26.2, 49.3, 21.1, '0.384782,-0.174185,-0.506659,0.489301,0.151948,0.000626,0.855421,0.306838,-0.581845,-0.245224,0.278592,0.851881,-0.407960,0.349222,0.359981,-0.041801,-0.588946,-0.755354,-0.428912,-0.385036,-0.266095,-0.241043,-0.003351,-0.530116,-0.079430,-0.176217,0.224400,0.063482,-0.047323,0.515832,0.364831,0.175206,-0.255162,0.369737,-0.153443,-0.147815,0.451622,-0.200851,-0.151714,0.051327,-0.234657,-0.411008,-0.469014,0.126460,0.036255,0.153887,0.599196,-0.230488,0.035588,-0.082598,0.272935,-0.231342,0.078522,0.155699,0.269857,-0.198934,0.312942,0.272616,0.017907,-0.126910,-0.098637,-0.053039,-0.666311,0.172972,0.175120,0.316032,-0.545237,0.520965,-0.119305,-0.025322,0.066280,-0.237544,0.469149,0.193386,-0.152167,0.404356,-0.006710,-0.203831,-0.549284,0.374193,0.708830,0.131358,-0.047128,0.122392,-0.198291,-0.445682,-0.174812,0.089771,-0.650773,-0.214844,0.251193,0.076666,0.012389,0.128781,-0.535570,0.026733,0.020183,-0.467783,-0.025319,-0.353767,-0.395709,-1.050949,-0.276093,-0.338961,-0.024381,-0.013955,0.071699,0.168320,1.081538,-0.659132,-0.044967,0.387290,0.339338,-0.395974,1.144940,-0.341930,0.070965,-0.118897,-0.330761,-0.325827,0.114329,0.217555,-0.011267,0.548669,-0.188293,-0.290741,-0.541692,0.070881', '30162520', '3811356', '26611806', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306861', '我是山姆', '剧情', '在星巴克工作的山姆（西恩•潘 Sean Penn 饰），虽已成人，但智力水平只有7岁。一次偶然，他收留了一个流浪女。该女子帮山姆生下了一个女儿后消失得无影无踪。他给女儿取名叫露西（达科塔•范宁 Dakota Fanning 饰）,因为他最喜欢甲壳虫乐队的《天空中戴钻石的露西》。他非常疼爱自己的孩子。露西在山姆的细心呵护下慢慢地长大了，她发现爸爸不能看懂稍微复杂一些的故事。她在拒绝长大，希望和爸爸一样。父女两的生活是那么幸福。地区的教育官员发现了这个特殊的家庭，他们认为山姆没有能力照顾露西，于是把露西带走了。伤心极了的山姆一心要挣回露西的抚养权，于是他自以为是的去找该地区最好的律师……©豆瓣', '西恩·潘', '杰茜·尼尔森', 9, 314443, 'tt0277027', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p652417775.jpg', 0.1, 0.4, 7, 35, 57.4, '0.117319,0.002268,-0.654111,0.618379,-0.473139,-0.415606,0.733939,0.165449,-0.437412,-0.247385,0.002426,0.821644,0.218891,0.318050,0.118708,0.324606,-0.374637,-0.431287,0.243844,-0.230799,-0.357830,-0.558489,-0.054063,-0.305304,-0.134799,-0.175537,0.423161,-0.151125,0.197046,0.121904,0.076574,0.058975,0.341423,0.382733,-0.326432,0.228251,-0.037447,-0.048895,-0.138634,0.190711,0.235746,0.083683,-0.029569,0.277889,0.021788,0.161537,0.696581,0.002121,-0.153644,-0.047513,0.389729,-0.297621,0.038127,-0.001958,0.121714,-0.350754,0.217174,-0.223114,-0.254691,-0.116677,0.137633,-0.017212,-0.538028,0.008531,0.178455,0.214964,-0.904237,0.381844,-0.065662,-0.131184,0.193150,-0.474035,0.090999,0.567865,-0.037117,0.495446,-0.312622,0.158842,-0.552058,0.156652,0.523902,-0.041666,-0.055399,0.520925,-0.435852,-0.418328,0.152881,-0.250929,-0.739727,-0.046140,0.360699,-0.062130,-0.401144,0.144435,-0.365878,-0.289211,-0.016870,-0.188897,-0.107577,-0.694619,0.114437,-0.179365,-0.125523,-0.598554,-0.465707,-0.084538,-0.225485,-0.369268,1.011833,-0.904464,0.226762,0.434051,0.335991,-0.603894,0.655558,0.368179,0.146766,-0.260586,0.141926,0.341009,0.112058,-0.108182,0.209254,0.374286,0.252468,-0.145282,-0.370156,0.412116', '26348103', '1292720', '1309161', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306870', '猛龙过江', '剧情', '痴迷练拳的唐龙（李小龙 饰）不远万里来到罗马帮助深陷麻烦的陈清华（苗可秀 饰），因某大老板（Jon T. Benn 饰）看中了清华饭店的地皮，为逼其就范，派流氓日夜骚扰。阿龙一分钟就撂倒了四名流氓，后又收服了饭店众伙计，打晕了埋伏在公寓的枪手（Homan Tapsell 饰），制服了大老板及其十余手下，救回了被掳走的清华。贼心不死的大老板从美国请来空手道高手Colt（Chuck Norris 饰），并将阿龙诱骗至斗兽场……©豆瓣', '李小龙', '李小龙', 8.4, 42537, 'tt0068935', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2191163236.jpg', 0.3, 1, 14.1, 46.4, 38.2, '0.019534,-0.075446,-0.335029,0.208240,-0.460261,-0.313337,0.298169,0.454949,-0.261651,-0.170718,0.513882,0.489589,-0.094202,0.044501,0.448926,-0.051800,0.089115,-0.664169,-0.178142,-0.262551,-0.194586,-0.107219,-0.112346,-0.204996,0.269876,-0.337055,-0.043975,-0.039030,-0.406295,0.505149,0.353443,0.324975,-0.220853,0.020903,-0.253905,0.168783,0.291477,-0.321035,-0.109471,0.375554,-0.596006,-0.443334,0.105040,-0.146511,-0.100462,0.323581,0.706538,0.245900,-0.166354,-0.146137,0.083381,-0.191812,-0.223223,-0.019245,0.499475,-0.077386,0.136043,0.060036,-0.368401,0.200324,0.167628,0.097388,-0.632338,0.467121,0.110665,-0.290802,-0.931266,0.522430,0.024035,0.017073,-0.082630,-0.136084,-0.125118,0.122418,-0.153076,0.228303,0.318793,0.119978,-0.679937,0.305691,0.297130,-0.330997,0.477757,-0.062439,0.408915,-0.096151,0.355708,-0.178401,-0.029065,-0.243935,0.741712,-0.317566,-0.121625,-0.266082,-0.593983,-0.168432,-0.521442,-0.006541,0.080754,-0.212831,-0.127189,-0.711988,0.125621,0.086958,-0.004235,0.182646,0.338669,0.375987,0.778746,-0.385213,0.068817,0.544546,0.371123,-0.584833,0.483177,-0.117572,-0.116589,0.256675,-0.342857,-0.352202,0.548037,0.619344,0.397634,0.537344,-0.337978,-0.615393,-0.417555,-0.036378', '1300857', '1466273', '3148013', '1293658');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306885', '幻之光', '剧情', '由美子（江角真纪子饰）小时候，奶奶总是离家出走，执意要从城市回乡下终老，并且有一次一去不返。再后来，由美子结婚生子，过着清贫但是幸福美满的小生活，有一天丈夫郁夫（浅野忠信饰）却意外离去。由美子守寡几年后，带着年幼的儿子远嫁给民雄（内藤刚志饰），那是一处遥远的小村庄，依山傍海。从此过着平稳幸福的简单生活，日复一日。但是在她的心中，一直有个挥不去的疑问埋藏着，她不明白郁夫为什么会自杀。一连串的意外事件让由美子离家出走，来到海边的她苦思不得排遣，民雄追赶来到她身边，回答了由美子挥之不去的疑问。©豆瓣', '江角真纪子', '是枝裕和', 8.2, 20840, 'tt0113725', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2186795930.jpg', 0.3, 1.2, 16.4, 52.2, 30, '-0.048787,0.003003,-0.792401,0.323030,-0.016498,-0.315709,0.789035,0.036987,-0.395780,-0.485585,0.261570,0.682154,-0.058706,0.695883,-0.096293,0.456057,-0.266887,-0.160387,0.076645,-0.082735,-0.124919,-0.562203,0.255688,-0.195955,-0.220528,-0.025325,0.535548,0.195819,0.069033,0.491038,0.184296,0.128649,-0.217800,0.527852,-0.356682,0.207754,-0.237335,0.299550,-0.130818,0.099755,0.379173,-0.286041,-0.434877,-0.095519,0.194417,0.120467,0.590413,0.030543,-0.229643,0.129979,0.183526,-0.298303,-0.237159,0.191513,0.058371,-0.070081,0.077538,0.256790,-0.437647,-0.078968,0.065562,-0.172640,-0.030260,0.068894,-0.102857,0.272288,-0.731884,0.347690,-0.082535,-0.364498,0.292633,-0.639996,0.077601,0.411770,0.157036,0.446874,-0.492839,0.431612,-0.351578,0.320842,1.108237,0.010556,0.072808,0.157259,-0.226234,-0.280090,0.025150,-0.208577,-0.730165,-0.030827,-0.153877,0.058605,-0.429942,0.052231,-0.149548,0.100222,-0.223130,0.030233,0.426162,-0.431556,-0.332571,-0.005888,0.201511,-0.339100,-0.554570,0.363441,-0.097530,-0.328201,0.642294,-0.821519,0.424487,0.691624,0.471726,-0.384567,0.587994,0.405919,-0.049376,0.012765,0.235777,0.523422,-0.395598,0.290033,0.304096,0.171713,0.031403,-0.093482,-0.413340,0.254525', '25721544', '1292064', '4728584', '1297606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306893', '新基督山伯爵', '剧情', '年轻的船长爱德蒙（詹姆斯•卡维泽 James Caviezel 饰）准备和心爱的未婚妻美塞结婚，然而副船长费南德因嫉妒爱德蒙的一切而设计使他终身被关进了位于孤岛上防守最严密的监狱，美塞也投入了费南德的怀抱。13年的牢狱生涯，爱德蒙在狱中结识了一位狱友，在狱友的指点下爱德华制定了周密的逃跑计划，并且，爱德华获得了一张藏有巨大宝藏的地图。终于，一个月黑风高的晚上，爱德华冒着九死一生的危险成功从监狱出逃。找到了宝藏后，爱德蒙利用金钱为自己买了一个伯爵的头衔，称为基督山伯爵。改名换姓之后，爱德蒙开始踏上他的复仇之路。©豆瓣', '吉姆·卡维泽', '凯文·雷诺兹', 7.2, 17338, 'tt0245844', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2472670484.jpg', 1.4, 6.3, 36.5, 41, 14.9, '-0.033739,0.070956,-0.552866,0.637840,-0.218466,-0.602694,0.743294,0.165995,-0.321413,-0.204283,0.403735,0.784609,-0.011136,0.137163,0.388469,0.268471,-0.469983,-0.513419,-0.162351,-0.273903,-0.405226,-0.543232,-0.257567,-0.192676,0.013353,-0.415798,0.664910,0.310738,-0.024825,0.046287,0.191107,0.215755,0.099097,0.331444,-0.251566,0.054502,0.524846,-0.198780,-0.106365,0.234968,-0.123923,-0.269984,-0.047605,0.179914,0.036004,0.518277,0.643907,-0.291299,-0.115563,-0.062863,0.484324,-0.353048,0.069842,0.076561,0.091431,0.077249,-0.155586,0.203775,-0.356894,-0.233828,0.193032,-0.383586,-0.822651,-0.198616,0.034184,-0.255335,-0.662783,0.273725,-0.135516,0.183278,0.166687,-0.359473,0.149457,0.533115,0.125214,0.153092,-0.089634,0.200665,-0.566072,0.156775,0.327723,-0.423494,-0.007832,0.248913,0.048279,-0.524899,0.193530,-0.156983,-0.368544,-0.345773,0.795064,-0.100085,-0.186867,0.043608,-0.546081,-0.168910,-0.596691,-0.156220,0.170609,-0.348756,-0.342655,-0.548893,-0.228635,0.068421,-0.155108,0.055205,-0.010675,-0.286965,0.513965,-0.469301,0.342278,0.836632,-0.033516,-0.407949,0.581772,-0.083805,0.223792,-0.019639,0.131245,0.338856,0.245350,0.601365,0.222432,0.349680,-0.124432,-0.137651,-0.562972,0.644293', '1301345', '4206468', '1309069', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306894', '刀锋战士2', '动作', '自从阿伯拉罕（Kris Kristofferson 饰）被吸血鬼带走，日行者刀锋（韦斯利•斯奈普斯 Wesley Snipes 饰）就没有停止寻找这位父亲一样的老搭档，并终于在东欧将其救出。阿伯拉罕缺席的日子里，刀锋依靠新伙伴斯加德担任后勤支持。不久吸血鬼长老派人传递停战协议，只因吸血鬼中出现了新的变种——收割者，收割者同时以人类和吸血鬼为食，而且由于过快的新陈代谢导致他们需求惊人。刀锋为保全人类同意带领由长老之女内纱（Leonor Varela 饰）、雪人（甄子丹 饰）等组成的吸血鬼血帮部队，消灭收割者，但岂料这一切是吸血鬼的阴谋……©豆瓣', '韦斯利·斯奈普斯', '吉尔莫·德尔·托罗', 7, 48750, 'tt0187738', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1625398536.jpg', 0.7, 4.5, 48.1, 36.4, 10.4, '0.229418,-0.040787,-0.300338,0.336643,-0.005184,0.096608,0.425414,-0.032814,-0.324734,-0.419481,0.270267,0.590082,0.075465,-0.266392,0.198499,-0.364770,-0.205299,-0.472394,-0.077241,-0.100733,-0.372969,-0.157416,-0.185739,-0.370797,-0.204719,-0.578932,0.953124,-0.083157,-0.024355,0.586496,-0.048267,0.338569,-0.073644,0.140376,-0.096697,-0.087444,0.046049,-0.275070,-0.281636,0.332513,-0.082922,-0.107674,0.180580,-0.071818,-0.151471,0.462458,0.680802,-0.737615,0.317073,-0.605530,0.018454,-0.459700,0.146689,-0.031942,0.582277,0.074235,0.137814,0.366024,-0.108783,-0.066374,-0.148162,-0.314298,-0.896978,-0.179619,0.400033,0.232366,-0.371394,0.152763,0.059433,0.087049,0.304706,-0.089128,-0.063920,0.217435,0.318503,0.403353,0.102510,-0.205341,-0.316187,0.122130,0.550304,-0.495726,-0.668661,0.030532,-0.169154,-0.590583,0.080535,-0.430820,-0.085303,-0.000496,0.151434,0.438458,0.086820,0.599752,-0.679755,-0.042116,-0.371859,-0.038137,0.173862,-0.279208,-0.071278,-0.858517,0.093095,-0.113676,0.249904,0.417425,0.227927,-0.084360,0.526066,-0.767035,0.165285,0.186558,0.512685,-0.499063,0.428663,-0.375475,0.221531,-0.397213,0.080780,0.279262,0.562441,0.102664,0.279012,-0.101835,0.091269,-0.012762,0.028379,0.080505', '2369613', '26759819', '3861846', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306911', '战栗空间', '剧情', '梅格（朱迪·福斯特 Jodie Foster 饰）刚刚结束了一场失败的婚姻，为了离开容易勾起回忆的伤心地，梅格带着女儿莎拉（克里斯汀·斯图尔特 Kristen Stewart 饰）搬进了一幢位于纽约的大房子内。虽然这座建筑已经有些年头了，但是梅格和莎拉对他们的新家还是感到十分的满意。在屋子里，梅格发现了一间紧急避难所，里面除了有充足的食物和水外，还有一套完善的闭路监视系统。一天，三名强盗潜入了梅格家中，来寻找传说中隐藏在这里的财宝，梅格带着莎拉躲进了避难所里，留给她的时间并不多，如果不能够战胜穷凶极恶的劫匪，那么她和女儿将双双付出生命的代价。©豆瓣', '朱迪·福斯特', '大卫·芬奇', 7.2, 52055, 'tt0258000', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2448793889.jpg', 0.8, 4.1, 40.4, 43, 11.7, '0.277981,0.092993,-0.798502,0.391009,-0.269723,-0.262931,1.122317,-0.138645,-0.536617,-0.267554,0.205348,0.801069,-0.015143,0.149554,0.228464,0.218738,-0.665900,-0.306400,-0.197605,-0.586189,-0.429142,-0.608414,-0.429738,-0.286138,-0.067290,-0.467991,0.404287,0.310445,0.106994,0.438253,0.169373,0.043356,-0.092005,0.367380,-0.072420,0.051027,0.067350,-0.185382,-0.136770,0.422952,0.170915,0.015352,-0.118762,0.171177,0.196025,0.451323,0.652560,-0.253982,-0.012213,0.193576,-0.001203,-0.150934,-0.061727,0.185827,0.130954,-0.211686,0.168707,0.271446,-0.667920,0.046722,0.207706,-0.197272,-0.955211,-0.095059,0.235688,0.135200,-0.650636,0.583181,-0.038638,-0.004739,0.314313,-0.425808,0.303985,0.353948,0.182026,0.545095,-0.097802,-0.074681,-0.765604,-0.068726,0.417607,-0.404091,0.134416,0.357179,-0.258472,-0.458342,-0.156013,-0.089514,-0.486125,-0.064017,0.335457,0.126937,-0.133872,-0.070789,-0.709433,0.083776,-0.428009,-0.454180,-0.045672,-0.381507,-0.161287,-0.701702,0.016573,-0.367784,-0.250692,0.085367,-0.053227,-0.259467,0.539830,-0.812288,0.303063,0.486105,0.565874,-0.178983,0.659906,-0.179197,0.423400,0.034411,-0.015033,0.250375,-0.145593,0.373329,0.296992,0.485986,-0.105835,-0.415331,-0.555340,0.470104', '1297996', '26586766', '1309101', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306915', '一级重罪', '剧情', '旧金山女强人律师克莱尔•库比克（阿什莉•贾德 Ashley Judd 饰）的丈夫汤姆•库比克（詹姆斯•卡维泽 James Caviezel 饰）突然被FBI抓走，送往洛杉矶附近的军事法庭秘密受审，罪名则是在服役时于萨尔瓦多杀害9名平民。震惊的克莱尔不顾一切丢下工作来到洛杉矶，雇佣了当地军事法庭律师查尔斯•格瑞姆斯（摩根•弗里曼 Morgan Freeman 饰），共同与军方指派的年轻辩护律师中尉恩布里（亚当•斯科特 Adam Scott 饰）一起为汤姆辩护。三人的调查取证遭到军方层层阻隔，甚至克莱尔的人身安全也遭严重威胁。坚信丈夫无罪的克莱尔与格瑞姆斯竭尽全力，却发现案件背后真相的复杂度远远超过了众人的想象……©豆瓣', '艾什莉·贾德', '卡尔·弗兰克林', 6.9, 6526, 'tt0257756', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2536694560.jpg', 0.5, 4.1, 51.1, 37.4, 6.9, '-0.056540,-0.122378,-0.522951,0.333881,0.095788,-0.203694,0.575559,0.250154,-0.213751,-0.480979,0.306766,0.851996,-0.061900,0.041121,0.586063,0.130221,-0.603788,-0.801287,0.089896,-0.406083,-0.246213,-0.861900,-0.116751,-0.584301,0.047715,-0.257587,0.284618,-0.173288,-0.082076,0.464745,0.237280,0.616110,-0.115548,0.329828,0.091231,-0.031559,0.674308,-0.501164,-0.469215,0.107020,-0.099621,0.043878,0.078251,0.040357,0.148420,0.401057,0.453168,-0.125580,0.050104,-0.115823,0.274490,-0.423743,0.364532,0.223168,0.505378,-0.120999,-0.019815,0.345132,-0.250441,-0.138897,0.177032,0.052564,-0.602354,-0.060089,0.138883,0.057265,-0.325319,0.079424,-0.426363,0.321481,0.110842,-0.018726,0.173739,0.315428,-0.054875,0.450802,0.067521,0.138449,-0.402892,-0.169769,0.256656,0.060784,-0.046184,-0.408996,-0.309217,-0.343689,0.123724,-0.085516,-0.253797,-0.109478,0.344015,-0.167026,0.301055,0.512933,-0.264165,-0.563135,-0.523249,-0.011632,-0.072384,-0.258056,-0.034881,-0.858606,0.072832,-0.050369,-0.210312,0.086959,-0.008318,0.059803,0.292297,-0.234860,0.271733,0.560377,0.286810,-0.428620,0.330767,0.122581,0.372195,-0.178055,-0.263056,0.359554,0.569032,0.302362,0.175046,-0.064690,0.132792,-0.335462,-0.012858,0.192868', '6517421', '1293537', '3006781', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306916', '想飞', '爱情', '任职于网络公司的Joker（吴彦祖 饰）与孩子气的弟弟Kid（陈冠希 饰）及父亲（黄秋生 饰）居住在一起。Joker正在为公司设计Cyber girl，却一直没有灵感。一晚，他在酒吧中偶遇了做酒保的Ling（李心洁 饰），误吃了摇头丸的Joker看到了Ling打架的情况，就认定了Ling是他想要的Cyber girl——Princess D。与弟弟Kid一起游说Ling做他们的模特儿制作Princess D。Ling表面上是一个坏女孩，但实际上她肩负了照顾家庭的重担。父亲入狱，她照顾精神恍惚的母亲、不务正业的弟弟，还要为父亲欠下的巨款还债。Ling总是想自己有一天能够逃离这些残酷的现实，成为Joker的模特儿后她感觉自己的梦越走越进了。Joker恍恍惚惚间也跟Ling发生了感情，无奈Ling并不想连累Joker，就在Princess D正式面世的时候，Ling却不见了……', '李心洁', '张艾嘉', 6.7, 6301, 'tt0282860', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p664106769.jpg', 1.3, 10, 49.8, 28.9, 10.1, '0.205891,-0.073699,-0.735191,0.481954,-0.323882,-0.490887,0.878144,0.312395,-0.472211,-0.261787,0.120639,0.969871,-0.087752,0.408443,0.036644,0.147419,-0.253228,-0.870223,0.047916,-0.086846,-0.155450,-0.417030,-0.207057,-0.211569,-0.310218,-0.186775,0.473047,0.078956,-0.114896,0.258856,0.382393,-0.070239,-0.023484,0.672149,-0.330009,-0.079999,0.021915,0.342898,-0.190191,0.004065,0.285940,-0.404322,-0.025892,0.159376,0.255068,0.411119,0.462113,-0.042190,-0.284974,-0.082863,0.318013,-0.188946,0.012366,-0.013154,0.152332,0.020171,0.232364,0.078247,-0.364988,-0.099246,0.140020,-0.154667,-1.009326,0.064759,0.149245,0.092035,-0.817480,0.572826,-0.206044,-0.038618,0.180066,-0.362443,0.395546,0.479308,0.242697,0.522198,-0.256169,0.002566,-0.539591,0.416860,0.771433,0.058820,-0.030189,0.693585,-0.286298,-0.244011,0.021433,-0.289000,-0.354153,0.027490,0.044908,0.005364,-0.408063,0.138033,-0.354810,0.017638,-0.050375,-0.188110,-0.069384,-0.532680,0.016651,-0.176208,-0.197741,-0.610297,-0.429008,0.128995,0.050897,-0.356472,0.537556,-0.877493,0.258185,0.620926,0.456120,-0.836654,0.921873,0.260910,0.021157,0.038725,0.244020,-0.008753,-0.313187,0.277526,0.324496,0.320482,0.268904,-0.242179,-0.389523,0.458133', '1304977', '4604803', '1783461', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306935', '黑侠2', '剧情', '一个神秘的军事组织，通过改变基因将普通人改造为体能、反应和速度都远远高于常人的生物武器，并将它们贩卖给黑帮组织。强风（安志杰 饰）就是其中的一员，可是，善良的他并不愿意助纣为虐，而是选择逃离了组织的控制，化身为惩恶扬善的“黑侠”，在世界各地弘扬正义。军事组织的首领宙斯得知了强风逃跑的消息，派出了冷血残酷的杀手梁，想要将强风捉拿归案。与此同时，一位疯狂的科学家企图将人类和动物的基因结合在一起创造出新的物种，结果可想而知，他得到的是一群半人半兽的怪物。科学家得知强风的血液能够帮助他走出研究的困境，于是亦对强风展开了追捕。©豆瓣', '安志杰', '徐克', 5, 4396, 'tt0264429', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2295700489.jpg', 13.5, 35.8, 39.8, 7.6, 3.3, '0.466008,0.148956,-0.497329,0.811675,-0.267657,0.146450,0.617280,-0.019146,-0.531845,-0.350220,0.072036,0.495213,0.279475,-0.100575,0.046535,-0.316821,0.133039,-0.687808,-0.238038,-0.007458,-0.437150,-0.494814,-0.590079,-0.535263,0.045335,-0.585862,0.809511,0.002598,-0.503038,0.358090,0.220942,0.309144,-0.241361,0.409064,-0.310977,-0.388365,0.068139,-0.071758,-0.357546,0.394181,-0.127799,-0.358394,0.251899,0.278227,-0.416293,0.279190,0.752857,-0.579968,-0.006744,-0.376501,0.255228,-0.646241,0.107611,0.183488,0.552941,0.071131,-0.186858,0.238111,0.180012,0.196786,-0.006566,0.034808,-1.320112,-0.174914,0.165419,0.106108,-0.711812,0.162299,0.017085,-0.035142,-0.015221,-0.101426,0.061680,0.282037,0.336717,0.503777,-0.205639,0.137241,-0.604977,-0.101062,0.610948,-0.270097,-0.402618,0.135560,-0.387520,-0.761539,-0.201674,-0.397451,-0.027642,-0.271184,0.316032,0.353622,-0.347735,0.212526,-0.962170,0.086204,-0.345468,-0.148780,-0.097255,-0.392063,0.007044,-0.712737,-0.242557,-0.044786,-0.145935,0.087265,0.156216,-0.419675,0.983192,-0.707481,-0.032888,0.774511,0.362949,-0.883183,0.418468,-0.251664,-0.042377,-0.326619,0.021150,0.258875,0.393649,0.490873,0.007067,0.301190,0.031409,-0.316946,-0.149076,0.310440', '26678784', '1793491', '3769423', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306939', '推手', '剧情', '老朱（郎雄）被儿子晓生（王伯昭）从北京接到美国后，不但没享清福，反因与作家儿媳马莎（Deb Snyder）语言不通、在生活习性上有诸多差异，添出许多新愁（老朱对马莎的世界不好奇，马莎虽对老朱的世界好奇，却并不想作深入的理解，而是在好奇过后深深厌恶），倔强的老朱一片灰心（竟然在儿子家里尝到寄人篱下的滋味！），愤然离家出走。一次偶然事件令美国媒体对老朱的太极绝技称奇，晓生和马莎也在看过电视新闻后找到了老朱，但此时的老朱已明白，处境凄凉总好过晚节不保。©豆瓣', '郎雄', '李安', 8.4, 136368, 'tt0105652', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p753043026.jpg', 0.1, 0.5, 12.5, 53.3, 33.5, '0.019524,0.064413,-0.848914,0.489732,0.037364,-0.545711,0.686937,-0.094468,-0.687329,-0.363226,-0.488728,0.435489,-0.396522,0.698364,-0.163466,-0.292290,0.112387,-0.215325,-0.022635,-0.267662,-0.161058,-0.616929,-0.105268,-0.401221,-0.248806,-0.025500,0.226605,0.460664,-0.248354,0.371099,0.571497,0.148841,0.047892,0.877160,-0.261325,0.286287,0.121088,0.421487,-0.168252,-0.322629,0.621746,-0.196833,-0.129748,0.143095,0.244406,0.141283,0.585534,-0.212613,-0.429499,0.106539,0.336293,-0.073709,-0.037186,0.257013,0.489911,-0.072132,-0.111950,-0.149051,-0.040551,-0.143749,-0.015614,0.066428,-0.616078,0.328482,0.159966,-0.106122,-0.553350,0.333330,-0.059587,-0.141945,-0.475853,-0.400332,0.435924,0.179331,0.515123,0.507131,-0.012675,0.412580,-0.090585,0.147908,0.699072,0.296110,-0.223630,0.305478,-0.165985,-0.411838,0.067679,-0.262261,-0.425389,0.190506,0.316667,0.028042,-0.276401,0.129043,-0.260743,-0.099040,0.080325,-0.072720,0.163233,-0.284467,-0.063658,-0.200315,-0.152643,-0.739975,-0.327454,0.041511,0.153688,-0.185838,0.508131,-0.703066,0.403116,0.055734,-0.018233,-0.796121,0.843717,0.256521,-0.113982,-0.256108,-0.188597,0.478754,0.127832,0.044128,0.507906,0.296995,-0.227792,-0.208285,-0.032879,0.382127', '1303485', '25828521', '25870679', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306951', '鹿鼎记2：神龙教', '喜剧', '韦小宝（周星驰 饰）要护送建宁公主（邱淑贞 饰）嫁到云南，在途中遇到了独臂神尼的刺杀。小宝被抓走后，借口拜神尼为师，其实是想追求其徒弟阿珂（李嘉欣 饰）。不料韦小宝被神龙教圣女龙儿（林青霞 饰）抓走，想要报了之前在王宫里埋下的仇恨，却没想到遭到了平西王的陷害。韦小宝极力相救，龙儿以身相许更把绝世武功传于韦小宝。韦小宝与公主之间的事情被平西王发现了，平西王更提前造反，小宝将贪图富贵的冯锡范骗到东郊皇陵，没想大那里竟然饰大清龙脉……©豆瓣', '周星驰', '王晶', 8.1, 207945, 'tt0104771', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1655227895.jpg', 0.2, 1.3, 21.6, 47.3, 29.5, '0.260033,0.088732,-0.708464,0.585493,0.096314,-0.170882,0.378305,-0.008619,-0.619189,-0.316547,0.199993,0.518386,-0.210445,0.021737,-0.065572,0.345089,-0.041019,-0.499556,-0.046131,-0.328823,-0.190799,-0.378851,-0.106975,0.239566,-0.345412,-0.263822,0.280384,-0.044633,-0.140864,0.404563,0.492528,0.183471,-0.098379,0.388768,-0.262833,0.472267,0.143139,-0.075315,-0.023948,0.449313,0.026002,-0.579985,-0.035107,0.132014,-0.354806,0.273934,0.144788,-0.293083,0.157393,-0.232559,0.072763,-0.195130,-0.051051,0.347813,0.383834,-0.183834,0.265262,0.274059,-0.322526,-0.086627,0.625622,-0.171706,-0.325353,0.209899,0.359251,-0.199244,-0.661200,0.015455,-0.229247,0.119805,0.136275,-0.368500,0.293191,0.329404,0.110944,-0.144337,-0.173558,-0.164075,-0.759810,0.318198,0.543186,-0.359107,0.590648,0.131080,0.381767,-0.085357,0.463500,-0.325731,-0.104852,0.260553,0.388055,-0.092893,-0.227651,0.144169,-0.193181,-0.478899,-0.511325,0.420922,-0.074194,-0.200667,0.114072,-0.083744,-0.180987,-0.060765,-0.128774,0.074291,0.296331,-0.132839,0.306552,-0.706068,0.066510,0.371625,0.422244,-0.737087,0.457621,-0.007518,-0.067916,0.248670,-0.049664,-0.213943,0.169449,0.257795,0.315604,0.179626,-0.049424,-0.421151,-0.507681,0.253564', '1297710', '1306249', '35461732', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306955', '女孩要什么', '剧情', '17岁的达芙妮(阿曼达•伯恩斯饰)自小与母亲利比(凯莉•普雷斯顿饰)生活在一起，从小开始她便希望她的每个生日都能有父亲的出现。开朗活泼的她看到传统的父女共舞这一环节便会深深的黯然下来。她决定，到英国寻找身份地位显赫的父亲——亨利爵士（科林•菲尔什饰）。当年父亲不爱爵位爱美人，遭到了家族的不满，母亲也在父亲助手的欺骗下离开了那座美丽的城堡。寻找父亲的过程中，达芙妮也找到了自己的爱情。她的到来让父亲原本平静的参政生活带来了很多的冲击。她的到来威胁到了父亲的未婚妻及女儿的地位，就算她们想尽办法让达芙妮出糗，但她还是可以夺得最多的关注，成为焦点。为了父亲，她不得不改变自己的作风，她开始茫然了，男友也因为她的改变深感失望。最后，她能否如愿与父亲一起跳舞，而她的爱情又会否归来呢？©豆瓣', '阿曼达·贝尼斯', '丹尼·高顿', 6.8, 16032, 'tt0286788', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p977226462.jpg', 1, 6.7, 50.8, 32.2, 9.3, '0.223396,0.301440,-0.874035,0.817011,-0.407450,-0.469344,0.730684,0.235296,-0.545439,-0.244199,0.307365,0.957517,0.041164,0.517448,0.271362,0.165624,-0.280933,-0.594918,0.081257,-0.097255,-0.159814,-0.473448,-0.193259,-0.322361,-0.116713,-0.246588,0.648000,0.011909,-0.016751,0.396397,0.338842,0.198244,0.124408,0.604634,-0.258274,0.160916,-0.095479,0.041262,-0.289275,0.044230,0.187717,-0.237353,-0.056689,0.471162,0.009438,0.307595,0.588584,-0.170651,-0.179527,-0.113889,0.376318,-0.238720,0.130208,0.297960,0.174795,-0.079426,0.127628,0.270463,-0.153171,-0.077899,-0.168314,0.098253,-0.759632,0.111467,0.128783,0.141062,-0.640953,0.526203,-0.084555,-0.155674,0.135487,-0.304167,0.204517,0.506893,0.034563,0.260728,-0.536962,0.083637,-0.468540,0.139445,0.930500,-0.075034,-0.188581,0.220490,-0.407533,-0.281801,0.113035,-0.449761,-0.692352,0.076237,0.277963,0.231166,-0.137078,0.342546,-0.349806,-0.153944,-0.243277,-0.159575,0.118868,-0.670125,0.160628,-0.201069,-0.223260,-0.582323,-0.540159,-0.110464,-0.003212,-0.570944,0.780301,-0.871341,0.299341,0.503036,0.448437,-0.752466,0.605784,0.209664,0.203103,-0.177728,-0.217281,0.609000,-0.157547,0.140477,-0.224653,0.135222,0.185713,-0.000619,-0.441352,0.641508', '25721544', '1301022', '1296569', '1309177');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306969', '惊天核网', '剧情', '1973年的第四次中东战争中，一架携带着核武器的以色列战机在叙利亚被击毁，核弹随之便被时间和风沙掩埋。然而29年后，核弹却被一对平民夫妇掘起，并廉价变卖给军火商，最后兜售给了恐怖分子，而这些恐怖分子正在策划一场在美国繁华集会地点的核爆，并将其嫁祸给俄罗斯，意在挑起新一轮世界大战。年轻警觉的CIA情报分析师杰克·瑞恩（本·阿弗莱克 Ben Affleck 饰）在与俄罗斯新任总统会面时，隐约感到事有蹊跷，并通过眼线很快洞察了恐怖分子的惊天阴谋。然而瑞恩的判断却未能得到局里的重视，在一筹莫展之际，他得到了资深睿智的老分析顾问威廉·卡伯特（摩根·弗里曼 Morgan Freeman 饰）的信任与合作，然而仅凭他们二人之力，能否赶在恐怖分子下手前找到核弹，阻止这一毁灭性的悲剧发生呢？本片改编自美国军事作家汤姆·克兰西的同名小说。©豆瓣', 'Ian Mongrain', '菲尔·奥尔登·罗宾森', 6.8, 10545, 'tt0164184', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2237506504.jpg', 0.9, 6.6, 51.4, 32.6, 8.5, '0.228796,0.131652,-0.814088,0.519490,0.301990,-0.125729,0.484600,-0.153444,-0.466415,-0.247516,0.126813,0.696164,-0.304488,-0.250349,0.249846,-0.056837,-0.431269,-0.620756,-0.197188,-0.060399,-0.194861,-0.735544,-0.446833,-0.273541,0.060005,-0.306830,0.486495,0.262546,-0.293428,0.427443,0.243002,0.382489,-0.042088,0.577211,0.052814,-0.129888,0.248439,-0.218829,-0.554535,0.298520,0.063663,-0.371926,-0.074678,0.174701,-0.160778,0.473185,0.407575,-0.462421,0.021108,-0.119760,0.255348,-0.343643,0.129809,0.125004,0.363529,0.261428,-0.103840,0.243784,-0.174584,0.160204,0.119624,-0.001166,-0.645177,0.052937,-0.181951,0.143890,-0.301298,0.382171,-0.247978,0.164891,-0.057595,-0.112440,0.256417,0.435211,0.288660,0.109965,-0.156808,0.229817,-0.499535,0.026354,0.536729,-0.080509,-0.321878,0.264737,-0.060910,-0.433182,-0.020662,-0.272895,-0.076017,0.096491,0.574448,-0.036853,0.002847,0.400406,-0.579075,-0.020126,-0.463359,-0.192018,-0.014335,-0.308103,-0.120563,-0.952010,-0.261007,-0.201498,-0.368798,0.150619,0.345482,-0.069166,0.566521,-0.544193,0.047132,0.661334,0.127073,-0.307976,0.310787,-0.005805,0.045388,-0.132993,-0.304846,0.043151,0.281376,0.528312,0.261276,0.176159,0.126851,-0.545776,-0.011392,0.037172', '2973528', '3178770', '1307442', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306977', '法外情', '犯罪', '1961年，孤儿院出身的刘志鹏（刘德华 饰）在伦敦的法律学院以优异成绩毕业，携女友安妮（蓝洁瑛 饰）返回香港，并在女友父亲的安排下进入律师行工作。刘志鹏接手的第一件案子是一宗妓女杀人案，因为死者乃望族背景，众律师不便为嫌疑人辩护，刘志鹏挺身而出，与嫌疑人刘惠兰（叶德娴 饰）面谈后，实知死者是一名变态性癖患者，刘惠兰当夜因惊恐错手杀人。刘志鹏为案件多方奔走，收集证据，连安妮也被他冷落，两人关系出现裂痕。而刘惠兰因刘志鹏的怀表发现他是自己寄养在孤儿院的亲生儿子，原来当年刘惠兰不肯令儿子在自己的阴影下成长，化身“无名氏叔叔”在孤儿院外伴儿子长大，如今母子相见却不能相认，未知审判之后是否阴阳两隔……©豆瓣', '刘德华', '吴思远', 7.5, 7103, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1276458573.jpg', 0.4, 2.1, 35.1, 47.5, 14.8, '0.110911,-0.155587,-0.568070,0.318668,-0.110920,-0.151175,0.586911,0.378978,-0.727988,-0.614180,0.381712,0.707508,-0.125722,0.469415,0.010527,0.016743,-0.169282,-0.732704,0.170843,-0.283970,-0.183455,-0.444109,0.052553,-0.129175,-0.093396,-0.271477,0.709625,0.011325,0.070810,0.289925,0.301904,0.323687,-0.544470,0.222312,-0.215505,-0.052583,-0.030638,0.189600,-0.562664,0.200553,0.043523,-0.295360,-0.004260,-0.036941,0.155134,0.370775,0.678462,0.091949,-0.135106,-0.411549,0.523602,-0.100308,-0.060794,0.200246,0.555509,0.018748,0.333572,0.598897,-0.124362,-0.124350,-0.026305,-0.115408,-0.558539,-0.119463,0.328183,0.188228,-0.670261,0.323168,-0.443860,-0.047869,-0.066714,-0.381056,0.218177,0.424612,-0.014765,0.439725,-0.256238,0.154675,-0.403527,0.226322,0.523267,-0.221781,0.126505,0.156733,-0.001205,-0.387012,0.087566,-0.108841,-0.449254,0.157588,0.130418,0.077288,-0.168700,0.356706,-0.205353,-0.425671,-0.367261,0.117918,0.164055,-0.333179,0.014826,-0.211497,-0.021016,-0.072699,-0.509426,-0.027473,0.125223,-0.306143,0.382556,-0.728480,0.196087,0.469496,0.320445,-0.728350,0.725725,0.196932,0.340529,-0.451713,-0.117197,0.337570,0.313722,0.307906,-0.029123,-0.235059,0.045762,-0.073710,-0.241836,-0.021317', '30345227', '1307922', '1293265', '27621189');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306982', '吸血鬼猎人D', '动作', '吸血鬼猎人D是吸血鬼王和人类女子生的后代，他身手敏捷，是响当当的吸血鬼猎人。这次，埃尔邦家族的千金夏洛特被吸血鬼掳了去，庄园主请来了D和吸血鬼猎人马克思兄妹前往营救。途中，D和马克思兄妹因为争夺酬金而互相较量，弄得不欢而散。随后，D受到了贵族三杰的袭击，紧要关头D突然发病，危在旦夕之际马克思兄妹中的蕾拉救了D，他们相互约定日后谁先死对方就要前往其墓前献花。其后，他们查明了夏洛特并不是被吸血鬼掳走了，而是恋上了吸血鬼马埃尔，两人一起私奔，正前往吸血鬼伯爵夫人卡米拉的城堡搭乘卡米拉的飞船前往世外桃源“夜之都”开始他们的新生活。然而卡米拉只是将他们骗去，她的真正目的是吸干夏洛特的鲜血让自己复活。D及时赶到，和卡米拉展开了一场生死大战。©豆瓣', '田中秀幸', '川尻善昭', 8.9, 46307, 'tt0216651', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453851762.jpg', 0.2, 0.7, 9.5, 35.6, 54.1, '0.312096,-0.046893,-0.566107,0.297022,-0.113806,-0.393326,0.705129,-0.115582,-0.280432,-0.269115,0.226990,0.969865,-0.114493,0.175312,0.326886,0.066259,-0.406231,-0.626801,-0.052795,-0.158911,-0.431892,-0.318333,0.024547,-0.269359,0.181011,-0.150937,0.645269,-0.058408,-0.170082,0.574704,0.165166,0.291083,-0.496921,0.350345,-0.350622,0.119323,0.125514,-0.173947,-0.344600,0.306533,0.001484,-0.139159,-0.069333,0.097031,0.103511,0.373419,0.520976,-0.542603,0.332348,-0.497651,-0.135822,-0.665783,0.138858,0.150000,0.551171,-0.392846,0.338243,0.161185,0.376772,-0.266776,-0.004717,-0.203764,-0.573122,0.362362,0.055324,-0.008676,-0.654354,0.421589,-0.037756,0.059643,0.220278,-0.097371,0.408877,0.572982,0.198969,0.082363,0.061795,-0.279609,-0.636845,-0.074131,0.974373,-0.009683,0.061224,0.062129,-0.050426,-0.679081,-0.038029,-0.389389,-0.231537,0.042709,0.640335,0.167752,-0.136830,0.409902,-0.696079,-0.308745,-0.616296,0.130568,0.101441,-0.437389,0.132103,-0.727342,-0.029393,-0.278449,-0.155549,0.082622,0.154357,-0.296101,0.405772,-0.699381,0.058450,0.485003,0.630532,-0.736797,0.522567,-0.206037,0.282064,0.049085,0.106288,0.069531,0.369559,0.448792,0.426045,0.200796,0.030887,0.282267,-0.245674,0.322397', '25721544', '1294941', '25908042', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306983', '卫斯理之蓝血人', '动作', '卫斯理（刘德华）是联合国外星生物分析局的特别成员，负责处理地球上一切和外星生物有关的事件。某次在古董店参观一块奇异的蓝色“人骨”时，卫斯理遇到少时曾有过一面之缘的、外表看来和一般美女无异的、血液是蓝色的外星人方天涯（关芝琳），当他想将其留住时，方天涯消失了。古董店附近 发生了一宗外星生物突袭事件，美国隶属FBI的外星生物调查机构接到上级命令，派出队中精英白素（舒淇）和白奇伟（张耀扬）兄妹领队到现场调查，众人与具有A级战斗力的外星生物展开交战。闻得风声的卫斯理也前来助阵，无奈不敌强大的敌手身受重伤，方天涯及时现身以奇异力量救出卫斯理，两人就此开始一段离奇情缘。©豆瓣', '刘德华', '刘伟强', 5.3, 32619, 'tt0324518', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2460356790.jpg', 8.1, 30.6, 49.8, 8.7, 2.7, '0.399265,0.088802,-0.715337,0.486717,-0.046435,0.161342,0.513087,-0.202709,-0.583605,-0.377100,0.210185,0.580963,-0.128847,0.067489,0.116324,-0.273423,-0.186589,-0.416258,-0.187648,-0.179121,-0.316243,-0.373169,-0.496386,-0.282855,0.043136,-0.320695,0.517155,-0.040722,-0.396167,0.568873,0.093044,0.618192,-0.602680,0.539868,-0.153868,-0.187816,0.096958,0.258167,-0.380403,0.220412,-0.101591,-0.052301,0.012436,0.014207,-0.134273,0.218383,0.508912,-0.322730,-0.113322,-0.359680,0.252979,-0.252343,0.247358,-0.086586,0.920595,0.212457,0.126233,0.118566,0.034628,-0.134001,-0.103249,0.130020,-0.651172,-0.043381,0.211347,0.365357,-0.203578,-0.037929,-0.197602,0.113419,0.060208,-0.265961,0.331727,0.241859,0.428264,0.085957,0.232768,0.012267,-0.344946,0.042136,0.851099,-0.036939,-0.468894,-0.109647,0.023159,-0.595782,-0.242344,-0.173235,-0.059653,0.362330,0.216477,0.122355,-0.106035,0.217596,-0.985806,-0.043709,-0.224843,-0.062798,-0.252953,0.042111,0.038982,-0.914554,-0.248995,-0.271934,-0.403455,0.064753,0.241921,-0.175800,0.616559,-0.658472,-0.018253,0.309008,0.219898,-0.508640,0.589390,-0.239977,0.070661,-0.166195,0.129393,0.002281,0.300734,0.366890,0.026681,0.348421,0.120236,-0.068696,-0.137921,-0.121028', '3147969', '1306809', '3097525', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306984', '恐怖热线之大头怪婴', '恐怖', 'Ben（吴镇宇）是香港一档电台节目《恐怖热线》的监制，忙于工作的他日渐疏忽女友Helen（周丽淇）。Helen是一名护士，曾瞒着Ben做掉腹中胎儿，此事令她难以释怀，时常会看到幻象。Mavis（何超仪）是美国电视新闻网络记者，她及摄影师等一行五人到港拍摄有关香港电台文化的特别节目，第一个研究对象便是《恐》，但Ben并不友好，只准他们在直播室外拍摄。某晚，《恐》主持人接到自称Chris的男人来电，说1963年他与6个同学在西环踢足球时，无意中在球场附近的山洞内发现一只“大头怪婴”，当即吓得魂飞魄散，甚至信奉伊斯兰教的校长亦不能用手中的《可兰经》将之制服。Chris的电话引来始料未及的热烈回响，Ben与Mavis都决定对此展开深入调查，但两人新闻出发点有异。几乎同时，Helen所在的医院接收了受到过度惊吓的青少年Sam（李灿森），对他，Helen没像其他护士一样慌忙躲闪，相反亲爱有加。Mavis和Ben依据有限线索找到老校长的养女Connie（张佳佳），从她口中得知，Chris不久前曾同6个男人看过老校长。随后《恐》直播时，主持人再次接到Chris的电话，但这次却是对他们的诅咒。不久，Mavis的摄影师离奇死去，他拍下的影像显示，当晚直播间里多出一个人影。Mavis和Ben展开更进一步调查，发现1961年的确有孕妇生下骇人的“大头怪婴”，Chris的6个同学也早已集体自杀。而Ben在向Helen求婚之后，Helen的行为却在某夜发生异变，她来到医院，将Sam带到一陌生地。', '吴镇宇', '郑保瑞', 6.4, 8958, 'tt0305647', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2515812399.jpg', 3.5, 15.1, 46.7, 25.3, 9.4, '0.348780,-0.077127,-0.693543,0.478458,0.052116,-0.079718,0.786385,-0.095006,-0.521700,-0.312704,0.161644,0.707612,-0.536180,0.335790,0.253767,-0.166395,-0.169206,-0.617166,-0.191202,-0.044387,-0.311812,-0.363999,-0.111870,-0.063411,-0.108178,-0.274196,0.331510,-0.063926,-0.299789,0.526684,0.227388,0.101689,-0.182671,0.597884,0.060368,0.070032,-0.052703,0.032584,-0.029887,0.156874,0.334388,-0.411136,-0.187310,0.178613,0.006907,0.492985,0.574354,-0.205155,-0.397629,0.005300,0.540921,-0.254508,-0.066610,0.157254,0.436249,0.247403,0.319474,0.120073,-0.237411,0.033498,-0.055333,0.140875,-0.504411,0.121482,0.033730,0.251399,-0.320711,0.278735,-0.171128,0.095662,0.041908,-0.356328,0.283230,0.269200,0.028067,0.465720,-0.122763,0.041590,-0.234152,0.125003,0.568160,0.047181,-0.188342,0.253890,0.031193,-0.515631,0.111849,0.140997,-0.435949,0.198135,0.203617,0.105682,-0.260448,0.093871,-0.247003,-0.062937,-0.225103,-0.266502,-0.046762,-0.258628,-0.324535,-0.699447,-0.134848,-0.120673,-0.182965,0.157463,0.085439,-0.051752,0.628329,-0.828397,0.186354,0.339893,0.182469,-0.382289,0.723076,0.060763,0.064283,-0.138906,-0.089910,-0.034821,0.266002,0.456099,0.046328,0.164916,-0.143417,-0.471741,-0.414259,0.047980', '1302384', '1296534', '1309297', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1306998', '少女杀手阿墨', '剧情', '日本战国时期，各地诸侯征伐不断，百姓妻离子散，苦不堪言。直到德川幕府建立，国内才稍事安定。然而仍有诸侯野心不死，蠢蠢欲动，和平的表象下暗潮汹涌。战乱中痛失爱子的小幡月斋（原田芳雄 饰）在南光坊天海大师（佐藤慶 饰）的指点下成立杀手集团，旨在刺杀那些图谋造反的诸侯大名。失去父母的少女阿墨（上戸彩 饰）和九名男孩被月斋收养，并接受杀手训练。他们不仅需要拥有精湛绝伦的武艺，还要抛弃一切情感和价值观。经过数年的磨练，阿莫和幸存的朋友出师，开始他们充满鲜血和厮杀的杀手之路……本片荣获2004年日本电影金像奖年度新人奖（上戸彩）和最受欢迎演员奖、2004年波士顿独立电影节评委会特别奖、2004年费城电影节观众奖。©豆瓣', '上户彩', '北村龙平', 6.5, 6700, 'tt0384819', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2236500551.jpg', 2.8, 13, 51.3, 24.1, 8.8, '-0.287315,-0.030941,-0.312941,0.255978,0.319085,-0.050408,0.106341,0.001176,-0.629747,-0.335513,0.271397,0.620716,-0.151792,0.139025,0.315096,-0.331693,-0.427561,-0.791313,-0.127809,-0.223016,0.105381,-0.032991,-0.119180,-0.037149,-0.401773,-0.265725,0.976444,0.428604,0.039519,0.568724,0.266590,0.138886,-0.043529,0.036399,0.188149,-0.061275,0.033786,-0.091468,-0.611748,0.109267,-0.436036,-0.576690,-0.402200,-0.092529,0.184772,0.182603,0.492436,-0.228871,0.160390,-0.512631,0.368197,-0.362508,-0.275287,-0.057667,0.460384,0.191714,0.383001,0.396749,0.071018,-0.336204,-0.227784,-0.342474,-0.547027,-0.044920,0.498830,0.055263,-0.456653,0.455646,-0.009340,0.270443,-0.227412,-0.172980,-0.002489,0.334025,0.258890,0.181470,-0.128818,0.070845,-0.416625,0.413661,0.624969,-0.223900,-0.232976,-0.248368,0.059129,-0.693865,-0.157857,-0.734284,-0.172153,0.057319,0.230499,-0.118462,0.155197,0.283935,-0.361312,0.151171,-0.005166,-0.316062,0.260965,-0.138855,0.091738,-0.832218,-0.071968,-0.300112,-0.271182,0.075494,0.343927,-0.225988,1.007089,-0.818401,0.099574,0.306703,0.435924,-0.428452,0.461312,-0.087950,-0.052749,-0.068279,-0.424125,0.388541,-0.097550,0.057103,-0.055062,0.083000,-0.376105,-0.050526,-0.111173,0.052152', '2369613', '26615753', '3811356', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307014', '不见不散', '喜剧', '不是冤家不聚头，刘元（葛优 饰）和李清（徐帆 饰）正应了这句话。他们在美国初遇，那时候，李清刚到美国，替一个台湾朋友看屋，就碰上了接待中国剧组的刘元。几番来回，二人有了些粗浅的了解。刘元给了李清一张机票，劝她回国，前途会比这里好。李清却留在了美国，一年后还碰巧和刘元的车撞上了。机缘巧合，刘元让李清到他的旅行社工作，怎料旅行社搞非法移民的勾当，李清一身麻烦，一气之下叫刘元以后再也别联系自己。想不到，一年后他们重遇，又一起办起了补习班。两人就这样反复的重聚分开。直到老去的某天，才有了一个契机，让他们互诉衷情。©豆瓣', '葛优', '冯小刚', 7.9, 147367, 'tt0199354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2080749733.jpg', 0.2, 1.2, 23.7, 53.5, 21.3, '0.346702,0.025050,-0.744088,0.430015,-0.011123,-0.775918,0.330007,0.205527,-0.444891,0.090502,0.009573,0.763468,-0.367259,0.370793,0.133102,0.054021,-0.358818,-0.698877,0.191842,-0.279242,-0.496737,-0.350330,-0.010448,-0.095125,-0.232623,0.074190,0.061766,0.043360,-0.103404,0.380272,0.153718,-0.275919,0.122357,0.624467,-0.362120,0.283007,0.106491,0.363571,-0.133989,0.236226,0.193195,-0.359506,-0.192379,-0.014235,0.107639,0.362607,0.473760,0.613445,-0.221542,-0.026963,0.170790,-0.074568,-0.056526,-0.109357,0.487063,-0.123049,0.310311,0.096497,-0.510671,-0.153190,-0.036374,0.224397,-0.355375,0.202833,-0.228367,-0.208113,-0.708044,0.452428,0.064782,-0.017706,0.007786,-0.428903,0.386021,0.738432,0.278285,0.122366,0.099828,-0.083348,-0.372192,0.509837,0.694338,-0.135955,0.031688,0.453927,0.144077,-0.239569,0.007922,0.080197,-0.145724,-0.074920,0.452657,-0.229268,-0.390402,-0.212796,-0.499354,-0.038817,-0.153186,0.019367,-0.028034,-0.290466,0.297524,-0.514503,-0.149488,-0.435242,-0.417120,0.421707,0.191885,0.123688,0.583797,-0.455359,0.105706,0.585587,0.432810,-0.531921,0.548627,0.148467,0.153115,-0.054921,0.417299,-0.372494,-0.066601,0.461060,0.527712,0.598811,0.172629,0.018518,-0.249494,0.187291', '5262027', '2063528', '1299811', '1293303');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307023', '神话', '剧情', '骁勇善战的秦朝大将军蒙毅（成龙饰）受秦始皇所命，负责护送玉漱公主（金喜善饰）入秦为妃，一路上彼此情愫暗生，可蒙毅还是选择了效忠君主。秦始皇病危，蒙毅去拿长生不老药并战死沙场。而公主试药成功，在秦王死后被禁在秦王陵中……几千年后，梦中的神秘白衣女子缠绕考古学家Jack（成龙饰）多年，一次好友William（梁家辉饰）邀他一同前往印度探险，高僧告诉Jack他被一段前世缘分困扰，Jack来到古都，开始了寻梦之旅。Jack乘直升机到郦山上空，冒险跃入瀑布，情景一如梦境。但与此同时，却有歹人一直尾随。在秦王陵中又会有什么情景？千古神话能够延续吗？©豆瓣', '成龙', '唐季礼', 6.9, 247891, 'tt0365847', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p486725980.jpg', 1.5, 9.3, 46.5, 29.8, 13, '-0.168943,0.316810,-0.610405,0.534577,0.300316,-0.140494,0.467710,-0.002473,-0.830595,-0.316365,0.526130,0.589160,-0.216756,0.004180,0.250887,0.140568,-0.163510,-0.491967,0.201437,-0.278345,-0.055252,-0.000258,-0.014300,-0.088907,-0.151985,-0.442164,0.697259,0.160966,0.114486,0.479524,0.179740,0.200268,-0.674644,0.428782,-0.266953,-0.021340,-0.058428,0.087864,-0.369741,0.387899,-0.177962,-0.482455,-0.182716,0.052090,-0.119389,0.000130,0.346448,-0.705296,0.050977,-0.001155,0.167628,-0.099288,-0.048186,0.055391,0.086976,0.236206,-0.013110,0.416756,0.042344,0.088422,-0.193956,-0.180045,-0.032821,-0.017606,-0.081571,0.260679,-0.516453,0.419802,0.036451,-0.145853,0.003212,-0.356132,0.341765,-0.017922,0.390609,0.162750,-0.130965,-0.114852,-0.406251,0.445626,0.789383,-0.044455,0.178731,0.066836,0.215145,-0.425528,0.175668,-0.027764,-0.212716,0.308696,0.244438,-0.104943,0.010543,0.369983,-0.194342,-0.043166,-0.611551,0.361834,0.048463,-0.083242,0.061448,-0.186433,0.097784,-0.117228,0.026793,0.022023,0.205417,-0.391816,0.267964,-0.545245,0.268046,0.396464,0.052574,-0.672988,0.484058,-0.012446,-0.110468,-0.068620,-0.033608,0.570513,-0.116166,0.198889,-0.103932,0.029425,-0.221622,0.083016,-0.483924,-0.038304', '25721544', '1306021', '1366853', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307026', '画皮之阴阳法王', '动作', '落第书生王生（郑少秋饰）娶妻多年，一无所出。一日自城中赶路回家时，偶遇一明艳照人之少妇尤枫（王祖贤饰）。枫自称身世可怜，被逼嫁入某大户人当妾待，正室所虐，故冒死出走，王仗义相助，愿意让枫暂居于其书齌，当晚王欲与枫行鱼水之欢，天忽亮，枫推说身体不适，拒绝了王的要求。翌日， 王往城中购胭脂水粉，欲赠枫以讨其欢心，遇玉清道人（刘洵饰），后者指王邪气缠身，王置之不理。王返家，向妻子陈氏表明心意娶枫为妾，陈氏趁枫宽衣沐浴时，竟自窗外窥得枫取下脸皮，点画胭脂之骇人情景，吓得晕死过去，王连狂奔玉清道观，求道人除魔，玉清把一尘拂予王，嘱王把它挂在寝室门外，再作打算不料枫却潜入室内，向王申诉前生之辛酸遭遇......©豆瓣', '郑少秋', '胡金铨', 6.6, 12628, 'tt0104455', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1693515765.jpg', 1.6, 10.2, 54.2, 24.1, 9.8, '-0.238702,0.537670,-0.353891,0.258945,0.258013,-0.431676,0.307980,0.391706,-0.456587,-0.620828,-0.228482,0.255492,-0.254067,0.172480,0.071450,0.055217,0.249549,-0.195992,-0.239389,0.095662,0.025923,0.330381,0.469970,-0.072158,-0.468657,-0.083497,0.108632,0.067678,-0.143766,0.252319,0.273154,0.236873,-0.401724,0.480802,-0.030571,0.092142,-0.545166,0.070784,-0.386649,0.090900,0.090108,-0.362902,-0.318779,-0.302852,0.153649,0.226217,0.566674,-0.241782,-0.319657,-0.535765,0.347875,0.057818,0.246882,0.581750,0.142280,-0.109939,0.099317,0.074818,-0.139921,-0.214309,0.095741,-0.224475,-0.021763,0.139692,0.086951,-0.318689,-0.416643,0.037860,-0.429393,0.309838,-0.201627,-0.316131,0.351516,0.183293,-0.282862,-0.024737,0.080390,0.154415,-0.282317,0.500684,0.402324,0.413681,0.231333,0.012630,0.286344,-0.020562,0.504677,-0.097408,-0.159680,-0.029520,0.421465,0.075687,0.290273,-0.100968,0.183296,-0.405871,-0.617831,0.384306,0.135311,-0.073890,-0.139971,-0.151356,0.163617,0.082009,-0.179311,0.057220,0.399738,0.013483,0.089697,-0.291815,0.003720,-0.007941,0.408571,-0.504290,0.494113,-0.350958,0.064385,-0.053601,0.086883,0.241336,0.163771,0.200156,0.295002,0.262775,-0.343348,0.087930,-0.211360,-0.109747', '1304021', '1306490', '1300883', '3546019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307031', '星际牛仔：天国之门', '剧情', '2071年的万圣节前夕，火星上的大城市突然发生了令人惊叹的犯罪。高速公路上一辆油罐车爆炸了。事故发生现场的人们因不明原因病倒，死伤人数超过400人。这样大规模的杀人事件，似乎是不明来源的生物武器所为。为此，火星政府发布了3亿圆的赏金悬赏恐怖分子。目击事件的faye单独行动妄图独占赏金，艾德使用黑客技术找到线索，与Bebop号上的大家一起行动。四人一狗组合再次出动，但他们不知道，这3亿元的代价，是对抗前所未有的强大犯罪者。©豆瓣', '山寺宏一', '渡边信一郎', 9, 34971, 'tt0275277', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p454096953.jpg', 0.2, 0.6, 8.1, 33.4, 57.6, '0.453035,0.004609,-0.824124,0.250825,0.405365,0.248677,0.699561,-0.196160,-0.437689,-0.077822,0.478057,0.481147,-0.256651,-0.162754,0.130133,-0.253395,-0.302485,-0.507942,0.055285,-0.285731,-0.406458,-0.584191,-0.261892,-0.345888,0.074007,-0.098568,0.453039,0.428669,-0.305922,0.544003,0.358467,0.434017,-0.070645,0.631714,0.086387,-0.180011,-0.053170,-0.027490,0.024920,0.167972,-0.389442,-0.561897,0.018730,-0.038757,-0.060688,0.588900,0.582532,-0.280435,-0.318789,-0.358461,0.459857,-0.374859,0.025891,-0.067634,0.540964,0.284351,0.296452,0.277604,-0.073768,-0.293276,0.000432,0.169601,-0.871520,-0.102288,0.076251,0.242548,-0.336521,0.225395,-0.365430,0.122344,0.171009,0.003582,0.318630,0.563111,0.336105,-0.030993,-0.207270,-0.280425,-0.753504,-0.056455,0.979322,-0.265980,-0.266105,0.106514,-0.256484,-0.678471,-0.376707,-0.622660,0.049376,0.446471,0.201357,0.001742,0.033178,0.302229,-0.702381,0.004695,-0.191249,-0.473524,-0.410631,-0.006072,-0.203352,-0.980233,-0.219109,-0.193970,-0.408195,0.297713,0.020144,-0.295339,0.521660,-0.603983,-0.114467,0.718063,0.425338,-0.626760,0.576157,-0.158207,-0.101157,-0.003504,-0.150973,-0.305754,0.196990,0.338715,0.013966,0.020068,0.188109,-0.048038,-0.061444,0.243516', '3147969', '1294941', '1453067', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307043', '东京攻略', '剧情', 'Maise（陈慧琳 饰）与男友高桥裕二（仲村亨 饰）相恋多时，高桥却在结婚当天突然失踪了。Maise决定前往东京寻找高桥，同时装修师父毕大勇（郑伊健 饰）为了追逃Maise欠下的装修费用，便决定跟着她前往东京。互相不信任的二人到了高桥在东京的家，遇到了一直跟踪高桥的私家侦探林贵仁（梁朝伟 饰），原来高桥与黑帮伊藤（阿部宽 饰）的妻子有奸情，于是失踪了。三人最后联手起来，决定一定要找到失踪的高桥，与黑帮抗争。随着追踪的层层深入，Maise也知道了高桥、毕大勇还有林贵仁的真实身份。©豆瓣', '梁朝伟', '马楚成', 6.4, 64967, 'tt0233600', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2185886973.jpg', 1.4, 9.8, 60.5, 23.2, 5, '0.077131,-0.271949,-0.668228,0.228803,0.329457,-0.363667,0.369659,0.251843,-0.350955,-0.574828,0.190441,0.638537,-0.121539,0.267878,0.451186,-0.068734,-0.552947,-0.694356,-0.020262,-0.266543,-0.104382,-0.628526,-0.143781,-0.142249,-0.022163,0.124394,0.654616,0.415493,-0.151638,0.626981,0.571107,0.404343,-0.379072,0.163364,-0.073086,0.037530,0.142443,0.266306,-0.334548,0.374062,-0.126158,-0.118792,-0.030067,-0.101391,0.357795,0.456442,0.354867,-0.007246,-0.219218,0.267992,0.257086,-0.156461,0.230382,0.155458,0.394262,-0.025261,0.284212,0.479547,-0.557334,-0.037780,0.102116,0.016088,-0.461398,0.224476,0.293018,0.112428,-0.512073,0.298064,-0.254335,-0.487492,0.405914,-0.490993,0.074995,0.812097,0.445192,-0.027193,-0.248884,0.281457,-0.102972,-0.009979,0.811443,0.134550,0.676772,0.128807,0.352801,-0.550950,-0.541631,-0.134475,0.032681,-0.055935,0.311161,0.398109,-0.115809,-0.100725,-0.530360,-0.510014,0.030270,-0.019716,0.251571,-0.171082,0.182962,-0.861552,-0.268455,-0.459138,-0.218940,0.335440,0.003422,-0.109096,0.590711,-0.903030,0.065607,0.656593,0.303955,-0.740658,0.314167,0.354958,-0.232575,-0.432366,0.164017,-0.030763,0.325686,0.422290,0.174784,0.192380,-0.085769,-0.024568,-0.432813,-0.082470', '25723905', '2369613', '25978126', '6007281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307046', '双层公寓', '喜剧', '阿历克斯（本·斯蒂勒 Ben Stiller饰）和南希（德鲁·巴里摩尔 Drew Barrymore饰）这对夫妻搬进了一桩双层公寓。这个公寓虽然是装修古旧了些，却是一个美妙的生活居所。唯一的糟糕事情是，公寓的二楼住着一个叫康奈利太太（艾玲·伊丝儿Eileen Essel 饰）。这个年近一百岁的老人，竟然给这对夫妻带来了灾难性的麻烦。康奈利太太总是在不合时宜的时间干扰阿历克斯和南妮的生活：在阿历克斯专心写作的时候支使他帮忙处理繁杂的家务活，在夫妻生活正到酣甜处时在他们窗边露出一个可怕的身影，用强大的电视音量来干扰他们的睡眠。更为无可奈何的是，康奈利太太毁了这对夫妻的事业，阿历克斯的书稿被她毁于一旦，南希也因为她的不间断骚扰而丢掉饭碗。夫妻两人对这个可恶的康奈利太太已经忍无可忍，他们决定，用一个神不知鬼不觉的阴谋，狠狠处置把这个无法无天的老太太，还有她那只专做帮凶的鹦鹉……', '本·斯蒂勒', '丹尼·德维托', 6.7, 6335, 'tt0266489', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p861548512.jpg', 1.9, 8.8, 50.8, 31.1, 7.3, '0.514918,-0.039124,-0.562865,0.494574,-0.274257,-0.453823,1.194101,0.386724,-0.246640,-0.264719,0.250538,0.656975,-0.052653,0.238481,0.149594,0.182521,-0.241718,-0.476291,0.117331,-0.090510,-0.088949,-0.472130,-0.227383,-0.290494,0.110202,-0.280102,0.105816,-0.219725,-0.111735,0.324819,0.295333,0.135019,0.268038,0.480654,-0.344182,0.304128,0.014719,-0.004347,-0.032135,-0.018848,0.144215,-0.159954,-0.032830,0.213111,0.040624,0.362160,0.523014,-0.267393,-0.413851,0.191927,0.394789,-0.353774,-0.121373,0.390370,0.356139,-0.329131,-0.042327,-0.039601,-0.643992,-0.117956,0.103059,-0.005662,-0.997852,0.059541,-0.017765,0.000114,-0.677228,0.547106,-0.229120,-0.171174,-0.052627,-0.401894,0.274538,0.635211,0.025621,0.572731,-0.340758,0.088925,-0.659424,0.087305,0.373622,-0.064885,-0.044763,0.497271,-0.288751,-0.252142,-0.050693,-0.353811,-0.655541,-0.344813,0.323144,-0.370012,-0.007264,0.065942,-0.593578,0.014450,-0.200825,-0.311197,0.020015,-0.647967,-0.269932,-0.367111,-0.264813,-0.569632,-0.488521,0.123077,0.153336,-0.048790,0.631476,-0.556945,0.041969,0.754493,0.327084,-0.243921,0.789250,0.146280,0.359226,-0.052493,-0.260542,-0.174392,-0.112514,0.602974,0.468562,0.755096,0.349101,0.035272,-0.468543,0.457278', '26884422', '1417428', '1299932', '26648284');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307052', '托斯卡纳艳阳下', '剧情', '婚姻失败对于已经三十多岁的女作家法兰西斯(戴安·琳恩 Diane Lane饰)来说，是一个很残酷的打击。幸亏朋友体贴窝心，专程安排她到意大利托斯卡尼去旅行一趟。想不到，托斯卡尼这个美丽得令人窒息的城市，竟然改变了法兰西斯的后半生。法兰西斯在托斯卡尼看到了一个郊外别墅的广告。本来并无太多打算，然而接下来的种种巧合却让她和这幢房子接下了不解之缘。于是，这个来自美国的作家毅然决定放弃从前的一切，开始在异国他乡建立自己的新窝。法兰西斯布置自己的新房，大大小小的琐事令她皱眉，各式各样的新人和新事物也令这个新房客应接不暇，新的恋情也在眼前铺开。阳光明净的托斯卡尼，让法兰西斯的内心渐渐丰盈。©豆瓣', '戴安·琳恩', '奥黛丽·威尔斯', 8.1, 73861, 'tt0328589', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1361589750.jpg', 0.2, 1.7, 20, 47.4, 30.7, '0.522697,0.059467,-0.972709,0.724650,-0.045457,-0.251539,0.741780,0.293958,-0.494043,-0.431473,0.148409,0.741983,-0.224067,0.397723,0.477705,0.090891,-0.342140,-0.379154,-0.130922,-0.277411,-0.447147,-0.470184,-0.312866,-0.334540,0.000596,-0.158235,0.587692,0.303691,0.010722,0.435548,0.332166,0.265152,0.237294,0.467695,-0.197462,0.081109,0.139290,0.158232,-0.220275,0.143267,0.032817,-0.157876,-0.162630,0.554511,-0.078390,0.450411,0.610182,-0.337516,-0.404379,0.171513,0.443920,-0.211363,-0.046966,0.096185,0.142602,-0.142197,-0.004934,0.053707,-0.516880,0.018260,-0.045059,-0.262024,-0.788296,0.075790,0.244646,-0.079261,-0.511423,0.419109,-0.087542,0.029199,-0.005262,-0.393625,0.192064,0.448931,0.224530,0.612216,-0.060785,0.233718,-0.460426,0.166626,0.622838,0.163292,-0.291219,0.612101,-0.495700,-0.236748,-0.036533,-0.010788,-0.507434,0.092576,0.161917,-0.094590,-0.028537,0.187409,-0.777780,0.056700,-0.355703,-0.282806,0.078351,-0.621790,-0.062985,-0.581622,-0.305297,-0.251512,-0.389917,0.025387,0.103080,-0.121294,0.635466,-0.723191,0.078980,0.527528,-0.008692,-0.364230,0.517165,-0.082734,0.253897,-0.048558,-0.203286,0.390446,0.078920,0.408502,-0.042009,0.552607,0.063311,-0.186845,-0.576438,0.676653', '34461680', '2053515', '1907966', '1308197');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307067', '战争与和平', '剧情', '本片改编自俄国文豪托尔斯泰的同名作品《战争与和平》，围绕1812年俄国卫国战争为中心，以贵族小姐娜塔莎（柳德米拉·萨维里耶娃 Lyudmila Savelyeva饰）、贵族青年皮埃尔（谢尔盖·邦达尔丘克 Sergei Bondarchuk饰）和安德烈公爵（维亚切斯拉夫·吉洪诺夫 Vyacheslav Tikhonov饰）三人的情感故事为线索，反映了1805年至1820年的重大事件，展示了当时俄国社会的风貌。本部1968年前苏联版的《战争与和平》耗时五年完成，耗资高达5亿6000万美元，堪称影史上最昂贵的影片，在苏联电影史上有着举足轻重的地位。影片拍摄得到了苏联军方的大力协助，在世界影史上，本片成为动用临时演员最多的影片之一。这部长达六个半小时的宏伟巨制，以其宏大的场面和史诗般的镜头语言，完美地呈现了俄法战争时期俄罗斯大地广阔的历史画卷，也极其忠实地再现了托尔斯泰的长篇巨著。', '谢尔盖·邦达尔丘克', '谢尔盖·邦达尔丘克', 9.2, 11558, 'tt0063794', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548048318.jpg', 0.4, 0.7, 5.4, 23.8, 69.7, '-0.031650,0.220507,-0.596750,0.876214,0.696416,-0.105751,0.464370,-0.006966,-0.310053,-0.206832,0.449065,0.809848,-0.357296,-0.333286,0.545498,-0.079339,-0.615228,-0.759642,-0.335540,-0.114555,-0.054391,-0.283898,-0.444250,-0.216495,-0.270973,-0.427662,0.903823,0.097975,-0.208553,0.367340,0.180281,0.340436,0.294490,-0.102898,-0.193500,-0.116613,0.046992,-0.267620,-0.616359,0.152258,-0.226966,-0.299768,-0.087859,0.036532,-0.252736,-0.046795,0.581618,-0.407926,0.227599,-0.033879,0.741095,-0.182602,-0.256654,-0.163364,0.395888,0.031407,0.270348,0.420799,-0.169167,-0.035850,0.104162,-0.477895,-0.757460,-0.159213,0.044254,0.294582,-0.399797,0.678824,-0.230697,-0.020393,-0.009401,-0.072190,0.125830,0.518608,0.217184,0.444765,0.033399,0.050379,-0.626837,0.488535,0.193905,0.129962,-0.595119,0.096410,-0.288176,-0.762930,-0.378827,-0.809530,-0.259817,0.151829,0.124683,-0.419460,0.323259,0.520878,-1.050341,-0.033339,-0.320315,-0.564584,0.178524,-0.261111,-0.202337,-0.859511,-0.486434,-0.601185,-0.181411,-0.057295,0.137302,-0.233705,1.098709,-0.248532,0.012454,0.282677,0.316979,-0.016891,0.910273,-0.006197,-0.010445,-0.251789,-0.170251,0.352838,-0.165017,0.070502,-0.095653,0.174692,0.017947,-0.258473,-0.114566,0.523398', '22265121', '27602116', '1294048', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307100', '灵气逼人', '喜剧', '安琪（叶倩文 饰）为了完成主题为“中国迷信”的论文，由加拿大抵港实地调查，甫一下飞机，安琪便邂逅了“好色”警察周发（周润发 饰），所幸未被其进一步纠缠。安琪为租得便宜住所，结识油嘴滑舌的汽车经纪人Hansom王（黄百鸣 饰），Hansom王色胆更甚，帮助安琪安家后便以帮助其了解迷信文化为借口痴缠不休。安琪租住的房间虽然便宜，实际上却是凶宅一间，一位歌星因三角爱情自杀于此，冤魂驻留房间久久不散。Hansom王在凶宅中被女鬼整治，周发亦因关心安琪被卷入此事，两人力劝安琪搬离，但后者丝毫不为冤魂所动坚守凶宅，最终被女鬼上身。为解救安琪，汽车经纪人与警察请出法师助阵，与女鬼展开连番对抗……©豆瓣', '周润发', '于仁泰', 6.8, 5229, 'tt0087625', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2346227706.jpg', 1.6, 6.7, 51.2, 30, 10.5, '0.268335,0.316559,-0.469606,0.213364,0.154024,-0.196266,0.560862,0.026960,-0.473844,-0.453370,-0.037981,0.291142,-0.189257,-0.018523,0.104705,-0.179317,-0.126185,-0.197757,0.008560,0.297737,-0.093971,-0.125148,-0.053683,-0.096840,-0.423070,0.094440,0.522055,0.360635,-0.116576,0.172828,0.296545,0.299436,-0.286372,0.215001,0.126314,-0.163787,-0.115252,0.041468,-0.337836,0.185798,-0.054879,-0.357788,-0.064600,-0.018091,-0.207376,0.243825,0.639014,-0.026868,-0.166255,-0.300543,0.208721,-0.110379,0.058842,0.033398,0.061789,-0.126528,0.368379,0.193562,-0.250592,0.023408,0.264053,-0.057792,-0.357806,0.204125,0.272283,-0.122100,-0.249830,0.154591,-0.434379,0.006534,-0.202597,-0.062611,0.104013,0.235435,0.281314,0.140356,-0.202128,0.020503,-0.265587,0.214604,0.285410,0.212253,0.101873,-0.060463,-0.084149,-0.477556,0.246671,-0.049551,-0.172891,-0.107359,0.150354,0.082730,-0.074657,-0.061510,-0.426933,-0.445711,-0.403123,0.146522,0.000260,-0.329259,0.002360,-0.554703,0.054862,0.108693,0.199589,-0.076562,0.292818,-0.009529,0.199761,-0.597670,0.041121,0.259351,0.454780,-0.632346,0.426292,-0.144608,0.267146,-0.233242,-0.069533,0.171865,0.037432,0.073299,0.329227,0.087629,-0.111903,-0.268275,-0.154086,0.075211', '1293265', '1306809', '1295746', '1304665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307106', '无间道2', '剧情', '1991年，香港黑帮龙头倪坤被杀，倪氏家族旗下五大头目中除韩琛（曾志伟）外，均伺机背叛发难，不料却被倪家不起眼的第二代倪永孝（吴镇宇）不费一兵一卒牵制，此举引来重案祖督察黄志诚（黄秋生）的戒心，使其派出警校学生陈永仁（余文乐）渗入倪家进行长期的卧底工作，而韩琛为了巩固势力，早在警察内部安插了线人刘建明（陈冠希）。三年后，事业蒸蒸日上的倪永孝为安枕无忧，决意将五大头目一举歼灭，却因疏忽让韩琛成为漏网之鱼。1997年，大难不死的韩琛重出江湖，为替死去的同事报仇，黄志诚找到他商议合作除掉倪永孝的事宜，不久却发现此举铸成大错，而各自为自己的尴尬身份苦恼的陈永仁和刘建明，则在无间道的路上越行越远。©豆瓣', '陈冠希', '刘伟强', 8.7, 430794, 'tt0369060', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p958008320.jpg', 0.1, 0.6, 10.6, 41.6, 47.1, '0.045511,0.087506,-0.524564,0.239610,0.042230,-0.215927,0.309331,0.207270,-0.622668,-0.344718,0.163946,0.532644,0.127618,-0.098666,0.052267,-0.291510,-0.123127,-0.838416,0.022514,-0.227575,0.026625,-0.319361,-0.328306,-0.336262,-0.101050,-0.194493,0.808927,0.365377,-0.046324,0.486022,0.101747,0.238094,-0.183465,0.340375,0.222854,-0.021174,0.188852,-0.176650,-0.397059,0.075672,-0.304001,-0.575832,-0.194785,0.218580,-0.149861,0.657860,0.344169,0.261920,0.030165,-0.359208,0.096234,-0.771221,-0.131577,-0.224621,0.801079,0.155115,0.104256,0.628547,-0.350389,0.016327,-0.095805,-0.206779,-0.983808,0.060869,0.259203,-0.023689,-0.550311,0.542345,-0.164572,0.055194,-0.092181,-0.098939,0.131478,0.605277,0.198258,0.035506,-0.209449,0.396099,-0.410112,0.019068,0.734406,-0.164516,0.356079,-0.319339,0.427713,-0.256098,0.090893,-0.473297,-0.016465,-0.201735,0.360975,0.025468,0.142236,0.167747,-0.308403,-0.230872,-0.486670,0.253303,0.152133,-0.400095,0.076346,-0.612056,-0.159172,0.061099,-0.031419,0.011660,0.202791,-0.198703,0.601366,-0.617263,-0.003447,0.550290,0.489359,-1.031486,0.474365,0.089225,0.445242,-0.342649,-0.293616,-0.161592,0.196480,0.350786,0.341900,-0.118842,-0.321878,-0.429314,-0.150413,-0.360450', '26678784', '1484760', '1302110', '1296272');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307115', '楚留香', '剧情', '神水宫是江湖中的传说，它从来不参与江湖纷争，亦没有人知道它的真身究竟在何处。近日来，武林帮派的各大帮主接连因为中了神水宫的天一神水之毒而命丧黄泉，一向风流倜傥的楚留香（狄龙 饰）则被误会为了神水宫的帮凶而遭到唾弃。为了洗清冤情，楚留香决定和李红袖等人调查事件的真相，在一番波折之后，楚留香总算得以打入了神水宫的内部，却发现这里的确是清静之地。原来，所有的命案都系楚留香昔日的好友无花和尚所为，然而，当楚留香想要离开神水宫将真相公之于众时，却遭到了神水宫主的拒绝，只因为楚留香得知了她有一私生女的秘密。©豆瓣', '狄龙', '楚原', 7.8, 5509, 'tt0075833', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1693074036.jpg', 0.5, 1.7, 26.8, 51.7, 19.4, '0.231399,0.249084,-0.709388,0.469073,-0.071179,-0.300009,0.612758,-0.247244,-0.837535,-0.459177,0.099315,0.731751,-0.110559,0.003682,0.194115,0.087346,-0.036070,-0.689565,-0.173651,-0.606254,-0.245983,-0.209566,-0.315425,-0.069832,-0.195814,-0.011542,0.574524,0.353671,-0.357737,0.174292,0.389526,0.373091,-0.288866,0.642758,-0.151900,0.016099,-0.075252,0.244334,-0.172758,0.177394,0.025012,-0.694017,-0.300631,0.540698,-0.148899,0.461435,0.451450,-0.552840,-0.269391,-0.253762,0.204363,-0.447271,0.046013,0.013410,0.546141,-0.232547,0.305205,0.520327,-0.201666,-0.274475,0.164545,0.145683,-0.867835,-0.210109,0.502683,0.192539,-0.135196,0.296990,-0.207147,-0.231607,-0.269333,-0.261094,0.328996,0.419617,0.654986,-0.081809,-0.195028,-0.256642,-0.535144,0.189823,0.781525,-0.072660,0.146308,0.225309,0.205607,-0.379170,-0.010004,-0.303691,0.014022,0.132717,0.415814,0.216907,-0.203509,0.589095,-0.338048,-0.228326,-0.253174,-0.120555,-0.237702,-0.300642,-0.228167,-0.281724,-0.401187,-0.159154,-0.152724,-0.225460,0.311970,0.013897,0.598481,-0.980143,0.277949,0.396046,-0.147218,-0.794406,0.530378,0.136810,0.169978,-0.180545,-0.274076,0.147091,0.373815,0.521575,0.074703,0.127233,0.145186,-0.435616,-0.319943,-0.087108', '1293265', '1301022', '3811342', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307125', '父与子', '剧情', '本片讲述了一对父子之间朦胧迷离的感情。阿列克谢（阿里克谢·尼穆斯霍夫 Aleksei Nejmyshev 饰）的父亲（安德烈·薛提宁 Andrei Shchetinin 饰）是一个退伍军人，父子二人相依为命，父亲离不开儿子，儿子也非常依赖父亲。因为父亲的关系，阿列克 谢也进入了军校，他的父亲经常到军校探视他。某日，阿列克谢的女朋友来到军校向他提出分手，原因似乎就是她难以接受他们父子俩过于亲密的关系。阿列克谢常常做噩梦，醒来后他问母亲在哪里，父亲却无言以对。父亲表示，外地有一份更加高薪的工作等着他，但是父子二人谁也离不开谁。他们是父子，有些时候他们像兄弟，有些时候他们像情人。但是他们心里都清楚，终有一天他们会分开，父子俩该何去何从……©豆瓣', '安德烈·薛提宁', '亚历山大·索科洛夫', 7.4, 6339, 'tt0363249', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p865405320.jpg', 1.3, 5.9, 34.5, 38.1, 20.1, '0.130793,-0.436431,-0.974781,0.515329,-0.138355,-0.516488,0.572024,0.128615,-0.859752,-0.328088,0.032382,0.851705,-0.092757,0.438666,0.104367,0.139817,-0.352266,-0.577199,0.256707,-0.343766,-0.104722,-0.781602,0.074985,-0.340422,-0.066034,-0.001073,0.344966,-0.271099,0.088252,0.250262,0.305144,0.020749,-0.095802,0.739648,0.150347,0.143173,0.169661,0.403305,-0.443268,-0.263161,0.394769,0.145902,-0.443438,0.102204,0.160490,0.395529,0.240520,-0.014550,-0.316656,0.030520,-0.020366,-0.294991,0.035198,0.232767,0.397225,-0.085154,0.371770,0.260903,-0.062649,-0.190998,-0.297497,0.212736,-0.250889,0.352005,0.044290,0.058160,-0.578926,0.301234,-0.200425,-0.070026,0.104356,-0.479092,0.348282,0.609331,0.333763,0.480857,-0.274550,-0.205977,-0.609951,-0.066490,1.054729,0.018819,-0.120557,0.261980,-0.436805,-0.268257,-0.034343,-0.055908,-0.622512,0.167549,0.083954,-0.026958,-0.126676,0.273902,-0.176473,-0.123010,-0.139231,0.080109,-0.002414,-0.710351,0.444756,-0.086218,-0.160280,-0.767679,-0.650466,0.064662,0.061541,-0.352963,0.554080,-0.828208,0.077558,0.334923,0.544350,-0.574943,0.706028,0.316865,0.094710,-0.512340,0.057822,0.277433,0.029038,-0.316464,0.313964,0.059277,0.355013,0.251910,-0.012226,0.280231', '25721544', '1292869', '1292064', '27000061');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307144', '一见钟情', '爱情', '被丈夫遗弃的Ellen（张曼玉）与玩世不恭的网络公司创办人Mike（黎明饰）在美国旧金山一见钟情，开始了一段爱情攻防战争。女人的天性使Ellen不自觉地侵入了Mike的个人空间，令不羁的Mike产生抵抗情绪，可是也终被Ellen的无条件付出感动，两人携手一起生活。然而在激情和温馨过后，因为Mike的公司出现经济困境，两人开始不断的争吵，暴露出各自的世界观有巨大差异的事实。在极度失意下，Ellen 提出分手，但像香港城的沦陷成全了白流苏和范柳原一样，一年后旧金山发生的大地震，为他们的重新牵手提供了契机。©豆瓣', '张曼玉', '刘伟强', 7.4, 16109, 'tt0240880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2356031919.jpg', 0.7, 4.6, 35.5, 41.1, 18, '0.388725,0.271287,-0.940734,0.509965,0.066990,-0.164702,0.795273,0.333134,-0.439182,0.015395,0.086252,0.892425,-0.428833,0.234694,0.199129,-0.274831,-0.108358,-0.941657,-0.128269,-0.035256,-0.110636,-0.378782,0.063575,-0.235019,-0.049003,-0.310036,0.799900,0.346388,-0.185237,0.584171,0.217934,0.258829,-0.092251,0.745203,-0.078446,-0.032293,-0.045018,0.372762,-0.540556,0.026925,0.085789,-0.190460,0.016422,0.188373,-0.281258,0.231189,0.759805,-0.240830,-0.452551,-0.063905,0.707198,-0.239837,-0.070158,0.127489,0.153005,0.306487,0.092958,0.213965,-0.260820,-0.014107,0.265281,-0.017882,-0.663091,0.052575,-0.021265,0.056121,-0.523765,0.669977,0.216564,-0.141691,0.199461,-0.222837,0.105013,0.667293,0.646258,0.385923,-0.438351,0.051002,-0.590140,-0.027808,0.937164,-0.063784,-0.514492,0.535277,-0.454439,-0.306234,-0.204798,-0.220637,-0.439228,-0.277546,0.170486,0.148086,-0.338568,0.529285,-0.838213,0.085775,-0.089120,-0.222162,0.058467,-0.710957,-0.067733,-0.774337,-0.550652,-0.582965,-0.326968,0.059501,0.093614,-0.349413,0.755703,-1.136173,0.166576,0.646309,0.518146,-0.635660,0.589441,0.211126,0.029131,-0.182270,0.156640,0.408830,-0.277524,0.198029,0.307356,0.281483,-0.284369,0.409732,-0.442805,0.618619', '1301022', '35030151', '1308755', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307146', '女高怪谈2：交换日记', '剧情', '在一个女子高中里面，女孩们吵吵闹闹，女孩们嬉笑怒骂，女孩们交换著日记，日记里写满了自己年轻的心事和不为人知的秘密。带著阳刚气的孤僻田径队健将和才华洋溢的钢琴手之间就有一本交换日记。钢琴手在日记本中写满了秘密，在同学眼中的这两个边缘人发展出一段暧昧脆弱的同性恋情。然而田径健将对这份感情的闪避且最终提出分手伤了钢琴手的心。一天她从学校顶楼跳下身亡。自此学校怪事连连。©豆瓣', '金圭丽', '金泰勇', 6.5, 13473, 'tt0266075', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187309196.jpg', 2, 11.6, 54.3, 23.1, 8.9, '0.531463,-0.180009,-0.583469,0.559903,-0.000338,0.093819,0.818652,-0.059618,-0.236236,-0.185687,0.258798,0.788056,-0.277072,0.680118,0.111715,-0.164412,-0.233077,-1.158452,-0.223288,-0.495351,-0.369844,-0.347107,-0.047284,0.047130,-0.136972,-0.217569,0.553758,0.208126,-0.166148,0.553279,0.339488,-0.050609,-0.303103,0.003157,-0.357434,-0.151692,0.142913,0.137444,0.217877,-0.114560,0.137339,-0.162058,-0.357553,-0.111164,-0.023740,0.238776,0.788038,0.074917,0.006305,0.140030,0.418981,0.207334,-0.264244,0.073253,0.179988,0.298649,0.248060,0.210662,-0.088209,0.122590,0.377676,-0.129443,-0.311905,-0.030231,-0.239257,0.336931,-0.611544,0.536545,-0.195091,0.021403,0.125657,-0.127566,0.198126,-0.106667,0.061697,0.367890,-0.149192,0.244331,-0.146470,0.039333,0.166468,-0.024332,-0.013958,0.127740,-0.363740,-0.408312,-0.031715,0.053200,-0.375939,-0.028009,0.448007,-0.107892,-0.358125,0.239163,-0.535139,0.196774,0.180291,0.066766,0.039166,-0.482948,-0.397098,-0.504021,-0.199708,-0.177505,-0.349705,0.101813,0.074752,-0.191812,1.197193,-0.652530,0.133090,0.336835,-0.056960,-0.157785,0.683416,0.349150,-0.134216,-0.083526,-0.044444,0.309033,-0.188346,0.266025,0.115480,0.542890,-0.286489,0.046465,-0.542270,0.603365', '3811356', '1308609', '25922902', '1945253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307163', '棋王', '剧情', '故事发生在90年代的台湾，电视台女主持丁玉梅（杨林 饰）因为节目《神童世界》收视率不佳而面临被炒鱿鱼的危机，所以她请香港朋友程凌（岑建勋 饰）帮忙，计划做一期象棋神童的节目挽回收视率。这时，他们遇到了一个名叫王圣方的孩子，他具有预测未来的特异功能，这让众人看到了希望……在寻找小棋王的过程中，程凌时常被自己的回忆打断——在文革时期，他跟随表哥倪斌（金士杰 饰）参加轰轰烈烈的知识青年上山下乡运动。在列车上，他们结识了痴迷下棋的王一生（梁家辉 饰）和学美术出身的阿城（严浩 饰），此后他们在农场遇到了一系列的麻烦，后来王一生因为一次疏忽而锒铛入狱，幸亏倪斌用“传家宝”——一副元代象棋用来送礼疏通，才帮他度过难关。后来王一生在众人帮助下，参加了一场特殊的棋王大战，结果出人意料……本片根据著名作家阿城的同名小说改编。©豆瓣', '梁家辉', '严浩', 7.8, 20494, 'tt0095450', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2675557646.jpg', 0.7, 3.4, 24.4, 46.7, 24.8, '0.015200,0.167418,-0.597181,0.525267,0.006579,-0.115307,0.399131,0.103317,-0.556388,-0.459573,0.200942,0.715066,-0.309777,0.140816,0.201490,-0.423885,-0.192139,-0.525812,0.121557,0.184172,-0.387936,-0.184994,-0.142739,-0.173270,-0.112485,-0.274927,0.504051,0.249798,-0.389044,0.330436,0.329307,0.092590,0.049016,0.282568,-0.082413,0.041520,0.047366,0.263001,-0.351516,0.187568,0.053540,-0.403140,-0.195000,-0.096348,0.124750,0.164767,0.600973,-0.228365,-0.248404,-0.038643,0.462442,-0.354611,-0.032651,-0.119212,0.236672,0.036888,0.222600,0.117806,-0.225347,-0.296189,-0.018903,-0.185291,-0.710835,0.071354,0.209514,0.141191,-0.573194,0.360712,-0.055686,-0.000756,0.065817,-0.262401,0.418749,0.612663,0.609395,0.097391,-0.147366,-0.064534,-0.329990,0.703334,0.737489,-0.060005,-0.148552,0.188521,0.072436,-0.294044,-0.014729,-0.193874,-0.422333,0.447651,0.284079,-0.339108,-0.142360,0.102086,-0.262506,-0.227997,0.040813,-0.279524,0.082409,-0.459086,-0.070939,-0.617236,0.054613,-0.144388,-0.181449,-0.188090,0.229986,-0.474035,0.742971,-0.704876,0.110350,0.373058,0.016382,-0.476798,0.800296,-0.117990,0.041085,-0.423656,-0.036606,-0.054084,-0.054990,0.147597,0.147144,0.386064,0.064579,-0.229974,-0.227882,0.445194', '27602116', '4301278', '30162520', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307176', 'GO!大暴走', '剧情', '杉原（洼冢洋介 饰）是高中三年级生，性格暴戾好斗，拳术了得，而这些都来源于他父亲的教导。他的父亲三年前借着去夏威夷之名，暗中从朝鲜国籍换成了韩国国籍。但是，在日本的韩国人身份一直是生杉原的心结。杉原在学校交了不少猪朋狗友，大家一起打架玩乐。众朋友中，成绩好的只有正一，而在杉原心目中，正一才是他最亲密的朋友。女孩樱井（柴崎幸 饰）和杉原相恋。樱井把他带回家给父母认识，双方家长见面，并不十分融洽，而一对恋人只管偷偷的在房间里亲吻。日子就这样一天天流逝。直到正一意外被不良少年刺死，生活又起了波涛……©豆瓣', '洼冢洋介', '行定勋', 8.2, 15886, 'tt0299937', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2221153968.jpg', 0.3, 1.6, 19.4, 46.8, 31.9, '0.286858,-0.341008,-0.508435,0.476996,-0.334192,-0.288908,0.443321,0.138022,-0.669088,-0.223145,-0.090763,0.846096,-0.242492,0.520924,0.103419,0.057990,-0.086356,-0.925248,-0.132566,-0.225307,-0.129866,-0.385020,0.027724,-0.158641,-0.300381,-0.156302,0.583270,-0.175318,0.045163,0.544558,0.262546,0.213093,-0.111664,0.330045,-0.398602,-0.018432,-0.029748,0.277654,-0.251826,0.217454,-0.100601,-0.355230,-0.167930,0.190588,0.288934,0.222440,0.749255,0.206100,-0.006342,-0.054774,0.194463,-0.177852,-0.323260,0.193708,0.680151,-0.014285,0.523321,0.221398,-0.080422,-0.032952,-0.039909,-0.091599,-0.225801,0.221824,0.046560,0.097264,-0.697808,0.705033,0.022884,-0.295291,0.295681,-0.276187,0.258556,0.336744,-0.027545,0.232164,-0.300434,-0.154438,-0.301739,0.362441,0.850704,-0.088257,0.042321,0.455467,-0.406659,-0.392768,0.053729,-0.309974,-0.410672,-0.101448,0.060857,-0.056943,-0.319017,0.210904,-0.493548,0.142356,0.174539,-0.043772,0.135289,-0.495666,0.166479,-0.493414,-0.349344,-0.814505,-0.564226,0.075665,0.027123,-0.134624,0.969145,-0.923626,0.141958,0.535885,0.288592,-0.403013,0.707116,0.409140,-0.065729,-0.056250,0.028397,0.080083,0.185591,0.041175,0.074152,0.375917,-0.097622,-0.055574,-0.436268,0.504168', '1292219', '35030151', '1826173', '3212120');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307181', '律政俏佳人2', '喜剧', '一段奇妙的“哈佛之旅”让金发美女艾莉•伍兹（瑞茜•威瑟斯彭 饰）既得到了法学学位，又收获了甜蜜爱情。毕业之后，艾莉与帅气男友艾默特（卢克•威尔逊 饰）开始筹备他们盛大浪漫的婚礼。为了让她最亲密的朋友小狗Bruiser分享幸福，艾莉准备“邀请”它的父母一同参加婚礼。然而，此时此刻Bruiser的父母却被关在一个化妆品公司的实验室里，等待命运的审判。这件事激起了艾莉对于动物权利保护的意识。为了她的小狗朋友，也为了更多可爱的小生灵，天真的艾莉只身前往华盛顿，想向政府提交一份保护动物的议案，并希望国会能颁布法律保护动物。正当艾莉孤身一人，无计可施的时候，她幸运的遇到了认识好多上层人士的公寓看门人希德尼（鲍伯•纽哈特 饰）。在希德尼的热心帮助下，艾莉正一步步向自己的目标迈进……©豆瓣', '瑞茜·威瑟斯彭', '查尔斯·赫曼-温菲尔德', 6.6, 57412, 'tt0333780', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1554758912.jpg', 1.5, 10.4, 53.1, 26.3, 8.7, '0.139539,-0.080237,-0.593990,0.562259,-0.202051,-0.152182,0.671666,0.226499,-0.339822,-0.145685,0.063378,0.470111,-0.194857,0.266809,0.630730,0.006956,-0.301908,-0.467211,0.155625,-0.083674,-0.320688,-0.474451,-0.334178,-0.393535,-0.093818,-0.271205,0.591167,-0.032305,0.187563,0.556011,0.287456,0.129797,-0.161287,0.442784,0.205976,-0.314076,0.411120,0.178103,-0.346055,0.154043,0.083223,0.074774,-0.047511,0.302875,0.121518,0.111325,0.545261,-0.251001,0.034783,-0.295752,0.231766,0.019196,0.268690,0.286138,0.003501,-0.155022,0.149119,0.010663,-0.050007,-0.160243,0.299252,-0.186856,-0.703090,0.020456,0.003741,0.033876,-0.325470,0.253807,-0.151363,0.362804,0.232040,-0.466002,0.024762,0.585510,0.440145,0.420495,-0.066588,0.359058,-0.409966,0.062619,0.672150,-0.050730,-0.089466,0.274565,-0.461953,-0.352045,0.097994,0.135125,-0.598914,0.014478,0.426441,0.098936,-0.081327,0.200652,-0.576347,-0.229320,-0.277123,-0.199576,0.175271,-0.455514,0.155794,-0.667478,0.029606,0.064101,-0.293823,-0.116930,0.122095,-0.371397,0.852422,-0.702154,0.271233,0.808146,0.438874,-0.457382,0.711367,0.151994,0.372408,-0.207731,-0.160629,0.444726,0.146009,0.228613,0.034121,0.219750,0.172091,-0.369698,-0.301165,0.481172', '3811356', '3005387', '2053515', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307186', '飞鹰', '动作', '2009年，好打抱不平的女侠飞鹰（杨紫琼）时常有惩奸除恶之举，深受市民爱戴，她的表面身份是名媛淑女鹭鹭。警察局长认为飞鹰的气焰有损警队威严，找来神探文仁（任贤齐）捉拿飞鹰。行动中，文仁巧遇师妹鹭鹭，因久未见面不知对方生活，两人重逢时他没立即将鹭鹭与飞鹰联系在一起。某日，鹭鹭的一名追求者何聪博士遭女贼（李冰冰）绑架，鹭鹭穷追不舍，终没抵过对手，她的举动引来文仁的怀疑。文仁从何聪助手身上探究线索，断定此案与太阳国的夏木集团主席夏木俊有关。解救何聪的行动中，鹭鹭又一次显露非凡身手，文仁开始将飞鹰与她作更为丰富的一体联想，双方关系亦变得十分微妙。©豆瓣', '杨紫琼', '马楚成', 5.3, 20021, 'tt0357894', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192300438.jpg', 9, 32.2, 47.7, 8.5, 2.6, '0.257085,-0.286897,-0.622043,0.638882,-0.131554,-0.116124,0.406342,0.057693,-0.571400,-0.438556,0.334782,0.611238,-0.426293,0.046970,0.257155,-0.078090,-0.015209,-0.750353,-0.055870,-0.059098,0.294433,-0.507928,-0.319334,-0.198557,-0.303604,-0.206679,0.487013,-0.185444,-0.338840,0.953519,0.190000,0.016927,-0.233700,0.543861,-0.126779,-0.208633,-0.056204,0.185722,-0.308314,0.005286,0.009948,-0.283964,-0.127540,0.196489,0.060672,0.449365,0.503658,-0.048890,-0.073437,-0.257054,0.285618,-0.036159,0.260185,0.124712,0.650251,0.035265,0.000555,0.309444,-0.091722,-0.163911,-0.136726,-0.005715,-0.459289,0.184060,0.111887,0.309718,-0.128252,0.145988,-0.285146,-0.044007,0.091606,-0.278606,0.134460,0.300956,0.433670,0.117773,0.212785,0.138028,-0.265791,-0.123413,0.805660,0.019245,0.055884,0.040144,-0.146694,-0.344820,0.245509,-0.080597,-0.122694,0.038694,0.129136,0.053677,-0.027197,0.437124,-0.392225,-0.120068,-0.367269,0.412180,-0.132214,-0.177875,0.067762,-0.632591,-0.384050,-0.356707,-0.125445,-0.186103,0.118243,-0.298425,0.618183,-0.938290,-0.073817,0.076279,0.355433,-0.551296,0.385025,0.068230,-0.133054,-0.306530,-0.319918,-0.071547,0.119528,0.134968,0.125926,0.281393,-0.162032,-0.088317,0.005195,-0.338514', '35030151', '26365262', '25723081', '1480318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307187', '情归阿拉巴马', '喜剧', '梅兰妮（瑞茜•威瑟斯彭 Reese Witherspoon 饰）是纽约炙手可热的设计师之一，年轻貌美的她拥有众多追求者，其中不乏像纽约最有名的钻石王老五、市长的儿子安德鲁这样人物。可是梅兰妮虽然和安德鲁订了婚，却一连三次拒绝了他花费天价的求婚。众人一时都摸不着头脑。其实，梅兰妮有自己的苦处：她本来是阿拉巴马州一个平凡的女孩，早已嫁给了当地一个纯朴的小伙子，但梅兰妮不甘心于小镇平凡无奇的生活，于是几年前独自来到纽约打拼。她必须回家乡办好离婚手续才能返回纽约开始她和安德鲁的新生活。梅兰妮带着一种优越感回到了家乡，回到了之前她不屑一顾的生活的地方。此时，她才猛然醒悟，原来自己一直都没有改变，这里才是她的家！©豆瓣', '瑞茜·威瑟斯彭', '安迪·坦纳特', 6.9, 18513, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1499775170.jpg', 1.1, 6.2, 48.8, 33, 10.9, '0.280715,0.142477,-0.895814,0.440859,-0.143838,-0.528446,0.619709,0.081774,-0.439018,-0.519903,-0.020182,0.612580,-0.078512,0.437722,0.296567,0.341586,-0.538027,-0.461846,0.192873,-0.373492,-0.061708,-0.183112,-0.227714,-0.211383,-0.108054,-0.041857,0.413604,0.067687,0.044536,0.227727,0.308638,0.322207,0.255112,0.635022,-0.260172,0.043088,0.300190,0.261539,-0.252980,0.149584,-0.050222,-0.122506,-0.080490,0.090312,0.356953,0.259240,0.377937,0.018387,-0.227813,-0.076819,0.344821,-0.140017,-0.274649,-0.043422,0.113801,-0.364339,0.319973,-0.028576,-0.169438,-0.164779,0.299472,-0.167845,-0.485319,-0.020221,0.038863,0.060963,-0.763459,0.354347,-0.098599,-0.157224,-0.225726,-0.486436,0.328749,0.406833,-0.084240,0.286722,0.023629,0.180280,-0.591329,0.343321,0.864799,0.307893,-0.178419,0.243928,-0.495585,-0.684365,0.056723,-0.151356,-0.506799,0.009672,0.213735,-0.032924,-0.042849,-0.040261,-0.230161,-0.226117,-0.397931,-0.122020,0.077575,-0.618603,-0.146670,-0.427333,-0.010989,-0.681188,-0.503475,-0.219851,0.019749,-0.216773,0.691485,-0.798330,0.146576,0.290847,0.383778,-0.553807,0.532820,0.016485,0.180040,-0.424848,0.058421,0.263068,-0.129378,0.315717,0.045574,0.352439,-0.001306,0.054652,-0.137310,0.742276', '1303112', '25721544', '1870682', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307200', '机遇之歌', '剧情', '20世纪80年代的波兰，医学院青年实习生威特克（Boguslaw Linda 饰）急于搭乘火车前往另一个城市。当他赶到车站时，火车已经开动。威特克奋力追赶，命运由此分出三条支流。第一种命运，他赶上了火车，并在车上认识一名老党员。二人相识相知，老人竟鼓励和引荐威特克入党，成为一名政府工作人员；第二种命运，他因站内警察阻挡错过了火车，因此被投入监狱，狱中他结识一个反党分子，日后更积极参与地下反抗运动；第三种命运，他错过了火车，却巧遇曾经的女同学，两人相恋、结婚，过着似乎美满幸福的生活……本片荣获1987年波兰电影节最佳男主角（Boguslaw Linda）和银狮奖。©豆瓣', '博古斯瓦夫·林达', '克日什托夫·基耶斯洛夫斯基', 8.6, 10711, 'tt0084549', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2504900419.jpg', 0.2, 1, 10.7, 43.5, 44.6, '0.099708,-0.022384,-0.562471,0.336972,0.160884,-0.278866,0.585012,0.001901,-0.158450,-0.063121,0.175080,0.746643,-0.035143,0.164714,0.645614,-0.208027,-0.549398,-0.583383,0.293834,-0.046439,-0.297640,-0.225945,-0.133017,-0.055618,-0.046048,-0.059417,0.854971,0.162360,-0.009118,0.725228,0.267062,-0.090348,-0.098099,0.296664,-0.359139,0.154236,0.362659,-0.121466,-0.366251,0.070730,-0.281125,0.023943,-0.023261,-0.106667,0.089460,0.280253,0.514703,-0.015983,0.124856,-0.113732,0.311524,-0.119506,0.109028,-0.201033,0.493163,0.109206,0.100502,0.296743,0.116997,-0.023980,-0.112575,0.064503,-0.194653,0.264053,-0.257614,-0.178244,-0.503399,0.216642,0.097097,0.097534,-0.208052,-0.112226,0.075910,0.599343,0.233856,0.143429,-0.129145,-0.208118,-0.506081,0.345809,0.834985,-0.199289,-0.364462,0.272858,-0.170229,-0.423193,0.072426,-0.158574,-0.251736,-0.099244,0.371346,-0.100839,-0.131940,0.194891,-0.271978,0.132875,-0.358473,0.133391,0.152664,-0.071959,-0.073591,-0.751377,0.210157,0.158453,-0.142589,0.220291,-0.181404,-0.132616,0.440627,-0.291155,0.108829,0.687654,0.494362,-0.518459,1.071183,0.162297,0.290173,-0.528927,0.136937,0.656831,-0.087292,0.287478,-0.105093,0.256879,-0.235255,0.220476,-0.095077,0.295202', '1780122', '1291558', '1291992', '1829654');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307201', '血战台儿庄', '历史', '1938年，日寇占领民国首府南京之后，计划由南北两面包抄津浦路遇陇海路的枢纽——华东重镇徐州，以实现对华东的全面占领。国民党第五战区司令长官李宗仁（邰宏来 饰）临危受命，指挥保卫徐州、抵抗日寇。日寇入侵山东，陆军上将韩复榘畏战逃跑，将济南拱手让与日军，蒋介石（赵恒多 饰）整饬军纪将韩某枪决。为了增强作战实力，李宗仁将四处受排挤的川军将士纳入麾下，又力劝蒋介石恢复张自忠指挥权，构筑了强有力的抗日统一战线。与此同时，日寇矶谷师团南下临沂，屠杀当地百姓，张自忠为一雪前耻，率部奔赴临沂，与庞炳勋部死战日军，拉开了台儿庄大捷的序幕……©豆瓣', '邵宏来', '杨光远', 8.6, 10272, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2357475129.jpg', 0.4, 1, 12.7, 41.6, 44.5, '0.030050,-0.065396,-0.597425,0.621302,0.397099,0.210833,-0.160628,0.287445,-0.517978,0.482761,-0.107270,0.234830,0.599769,-0.733619,0.103997,-0.247782,-0.330257,-1.077148,-0.427746,0.112151,0.233669,-0.415640,-0.233585,-0.140613,0.005984,-0.035732,0.947225,0.577145,-0.320499,0.480252,0.091048,0.180142,0.151654,0.561134,0.485007,0.226876,-0.124167,-0.871200,-0.620351,0.297424,-0.295624,-0.341158,-0.148118,0.074604,-0.030498,0.337934,0.857620,-0.375184,0.265000,-0.311590,-0.266634,-0.422463,0.131380,0.187460,0.448127,0.472323,-0.305502,0.194344,-0.235650,0.080062,-0.252077,-0.072967,-0.139872,-0.476748,-0.002681,-0.313676,-0.202984,0.507624,-0.207458,0.683175,0.380072,-0.375536,-0.036251,1.460500,0.040716,-0.010726,-0.296996,0.077537,-0.240813,0.219224,0.514972,-0.450146,-0.052448,-0.914816,0.156505,0.000526,0.494699,-0.445709,0.075744,-0.128733,-0.044231,-0.493605,0.816425,0.134393,-0.613268,-0.308309,-0.622480,-0.217685,0.084507,0.316637,0.024018,-0.542998,0.020890,-0.006895,-0.145345,0.294145,0.266778,0.573489,0.405627,-0.722900,-0.509873,0.205532,0.700174,-0.598258,0.090315,0.504039,0.208554,-0.151678,0.506941,0.366018,0.028889,0.945124,0.374760,0.180252,-0.722788,-0.184690,-0.189455,0.236128', '2006172', '30454698', '1424552', '26852888');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307210', '失眠症', '剧情', 'Will Dormer（阿尔·帕西诺 Al Pacino 饰）与搭档Hap Eckhart（马丁·唐文 Martin Donovan 饰）来到远离洛杉矶一处日不落的小镇阿拉斯加，调查一名17岁少女被活活殴打致死的案件。阿拉斯加一名女警察llie Burr（希拉里·斯万克 Hilary Swank 饰）对Dormer的办案手法由衷感到敬畏，努力在查案过程中学习。而此刻的多莫其实已经麻烦缠身，他在洛杉矶抓获了一个案件嫌疑人，因为要将其定罪，不得不捏造了假证据，此事已被内务部调查。Hap想向内务部坦诚真相并认为对Dormer也是好事，不过Dormer不这样想。在引诱真凶的围捕中，Dormer在大雾中失误打死Hap，Hap临死前认为Dormer是故意打死自己的。在陈述事件时Dormer本能性地说那枪是凶手开的。然而在良心的压力和日不落的环境下，他患上了严重的失眠症。这时有人开始给他打电话，声称看见了雾中的一切。Dormer最后将凶手锁定在侦探小说作家Walter Finch（罗宾·威廉斯 Robin Williams 饰）身上，对方也没打算和他捉迷藏的游戏。一场心理和良心的对决开始了。', '阿尔·帕西诺', '克里斯托弗·诺兰', 7.5, 51510, 'tt0278504', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1150166738.jpg', 0.3, 2, 33, 50.2, 14.6, '0.330433,-0.038126,-0.797412,0.572645,-0.290789,0.078355,0.873112,-0.166941,-0.573683,-0.328062,0.168703,0.776309,-0.203784,0.072996,0.295776,0.067698,-0.322814,-0.811796,-0.075634,-0.132382,-0.397301,-0.685918,-0.228056,-0.439125,-0.123134,-0.151147,0.337254,0.249265,-0.408240,0.322969,0.341804,0.527042,0.040068,0.552917,-0.145372,-0.154731,0.111779,-0.263683,-0.192468,0.445413,0.286306,-0.588290,-0.114637,0.542796,-0.077037,0.471482,0.669157,-0.191904,-0.342142,0.137997,0.326216,-0.570321,0.200796,0.349153,0.473397,0.023964,0.213096,0.248651,-0.251433,0.017043,0.044599,-0.090506,-0.845299,-0.062151,-0.046894,0.268071,-0.542717,0.329245,-0.287647,0.066743,0.006693,-0.123174,0.275114,0.222041,0.302205,0.224499,-0.143542,-0.100348,-0.654649,-0.065734,0.625071,-0.035688,0.067853,0.304738,-0.034496,-0.395311,-0.139810,-0.025621,-0.205965,-0.045169,0.416487,-0.049298,-0.389282,0.183052,-0.336219,-0.239901,-0.267552,-0.224423,-0.426184,-0.375850,-0.094915,-0.063132,-0.194251,-0.368033,-0.398680,0.015143,0.120978,-0.256108,0.301197,-0.810433,0.165449,0.784681,0.229282,-0.446823,0.518229,0.380086,0.019454,-0.142448,-0.122994,-0.028098,0.341264,0.309474,0.390799,0.388753,0.262527,-0.452006,-0.454678,0.328809', '35073886', '1947080', '1295733', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307263', '西班牙公寓', '剧情', '巴黎，有一个自小梦想当个作家的年轻人，在老爸的安排下学了经济，并去财政部找老爸的熟人谋求一个在政府里的职务，可是这个位置要求通晓西班牙语和西班牙的经济形势，于是可怜的扎维尔只得告别老妈，丢下女友，动身出发前往巴塞罗那，并在那里完成他经济学硕士的学业。剧情于是开始了，下面的事情于是变得有点趣味了：出门在外，当然会遇上新人新朋友，会有什么浪漫的事情发生吗？身处异乡的男男女女，品尝着留学的滋味，或者说体会当留学生的苦辣酸甜，可是除了学习之外，生活中的其他人和事也许更加重要。这帮在外求学的各国年轻人们由于在巴塞罗那一时找不到更好的房子，不得不大家挤在一套大公寓房里，有法国人，英国人，德国人，意大利人……©豆瓣', '罗曼·杜里斯', '塞德里克·克拉皮斯', 8, 12117, 'tt0283900', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1164307509.jpg', 0.3, 1.8, 23.1, 48.2, 26.5, '0.488827,-0.271021,-0.630493,0.506277,-0.210720,-0.341236,0.255760,0.159026,-0.565230,-0.521400,-0.133698,0.788773,0.125761,0.394408,0.292210,-0.093921,-0.478913,-0.574733,0.144117,-0.176118,-0.305724,-0.522410,-0.143222,-0.380388,-0.059655,0.006005,0.465798,0.064966,-0.189358,0.221868,0.213707,0.062237,0.083654,0.478440,-0.221784,-0.130798,0.207614,0.238140,-0.315724,0.167438,0.202865,-0.054122,-0.224855,-0.066453,0.322286,0.325248,0.319039,-0.001191,-0.209021,0.039244,0.340954,-0.133167,-0.065046,0.065529,0.222103,-0.115681,0.282787,0.147892,-0.070203,0.348659,-0.099154,-0.220912,-0.432691,0.004916,0.100665,0.100929,-0.553512,0.402767,0.111520,-0.195930,-0.006668,-0.502590,0.216581,0.575450,-0.026745,0.424809,0.011370,0.112676,-0.553268,0.163708,0.779364,0.039594,-0.133926,0.177675,-0.123598,-0.276892,0.044685,-0.146111,-0.378840,0.019850,0.103031,-0.082163,-0.261121,0.038373,-0.602790,0.174339,0.215390,-0.424312,0.163937,-0.391483,-0.020222,-0.577296,0.161751,-0.382661,-0.291232,-0.105730,0.165768,-0.071521,0.822598,-0.824039,-0.030507,0.582637,0.190742,-0.804923,0.653372,0.219726,0.267971,-0.156662,-0.197616,0.098828,-0.305718,0.293219,-0.140825,0.226834,-0.019977,-0.507289,-0.327028,0.356043', '25721544', '1296770', '4301278', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307265', '晚春', '剧情', '居住在镰仓的大学教授曾宫周吉（笠志众 饰）早年丧偶，他与女儿纪子（原节子 饰）相依为命。纪子从小担负起家庭的重担，悉心照顾父亲的生活起居。转眼间，纪子已二十七岁，依旧待字闺中。纪子的姑姑（杉村春子 饰）和朋友（月丘梦路 饰）都很关心她的婚事，然而她却因为对父亲的依恋，不愿谈婚论嫁。不久姑姑为周吉介绍一名独身女子三轮秋子（三宅邦子 饰），周吉欣然同意。得知此事的纪子心中感到无限的怅然……本片为当年日本《电影旬报》评选十佳电影第一名。©豆瓣', '笠智众', '小津安二郎', 8.7, 22883, 'tt0041154', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1994505696.jpg', 0.7, 0.6, 8.3, 45.1, 45.3, '-0.112264,-0.197740,-0.397601,0.636297,-0.106761,-0.472605,0.557913,0.399299,-0.744637,-0.686526,0.545234,0.643800,0.068020,0.449525,0.438791,-0.012311,-0.147061,-0.364675,0.020615,-0.088105,0.167733,-0.242802,0.100257,-0.060818,-0.414189,-0.228872,0.944919,-0.133171,0.544477,0.745100,0.099646,0.203587,-0.175664,0.150930,0.272808,0.075184,-0.019400,0.243317,-0.487894,0.037314,-0.508842,-0.099369,-0.155688,-0.084538,0.048607,0.420178,0.587365,0.075656,-0.099709,-0.581723,0.594922,-0.034090,0.185601,0.190868,0.312863,0.279233,0.397667,0.187829,-0.555986,-0.110603,0.021206,-0.318481,-0.093452,0.129590,0.530464,0.008909,-0.559775,0.480119,-0.452909,-0.370771,0.311423,-0.311193,-0.088344,0.380785,0.235797,0.598191,-0.369623,0.486228,0.026767,0.468409,0.508288,-0.141846,0.176712,0.354493,-0.082021,-0.357194,0.055842,-0.100457,-0.677874,0.175450,-0.272813,0.301459,-0.164579,0.256439,0.038652,0.036976,0.222119,0.055885,0.548632,-0.649809,0.118952,-0.443028,-0.185349,-0.443634,-0.200958,-0.158734,0.225477,-0.161251,0.872917,-0.634740,0.095374,0.065803,0.262219,-0.492351,0.497588,0.432510,-0.009261,-0.423157,0.010400,0.588116,-0.208911,-0.059982,-0.187938,0.133934,0.146406,-0.240591,-0.228624,0.000343', '3445516', '25922902', '6963575', '6973376');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307289', '我的野蛮初恋', '剧情', '日美（孙艺珍 Ye-jin Son 饰）的母亲在临盆当天死于难产，日美的父亲朱荣大（于东健 YuDong-Geun 饰）独立一人抚养女儿长大，把她视作掌上明珠。和日美青梅竹马的孙太一（车太贤 Tae-hyun Cha 饰）是釜山高中出名的差生，虽然行为大胆，性格叛逆，多次违反校规校纪，却把日美视为今生的唯一。在他向日美表白后，他的班主任，日美的爸爸朱大荣提出了以成绩超过日美为条件的公开招亲来激励太一。而太一决定，为了日美而洗心革面，发奋读书考上了法律学院。原以为到此就可以与日美结婚的太一，又被朱父的软硬兼施逼迫许下承诺，保护日美的处子之身直到他通过初级司法考试。为了考试而专注学习的太一一再的压抑自己对日美的欲望，甚至努力去忽视日美千方百计的示好。然而当埋头苦读的太一终于通过了考试之时，却听说了心爱的日美要与他人结婚的讯息，于是太一开始了挽救初恋的疯狂行动…', '车太贤', '吴钟禄', 6.4, 5828, 'tt0364262', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1302516201.jpg', 3.1, 13.9, 50.8, 22.6, 9.6, '-0.039439,0.006261,-0.822099,0.724099,-0.212519,-0.489914,0.385582,-0.096102,-0.252455,-0.123169,-0.123124,0.759795,-0.095897,0.501383,0.427426,-0.135372,0.217144,-0.817200,-0.014343,-0.120459,-0.222169,-0.448049,0.180175,-0.002261,-0.175568,-0.667582,0.596188,0.005312,-0.130206,0.469639,0.267181,-0.054945,0.271167,0.263760,-0.141255,-0.495777,-0.207640,0.391655,-0.359817,0.394034,-0.042797,-0.354786,-0.269916,0.298351,-0.064368,0.248856,0.758430,-0.321299,-0.450573,-0.439141,0.760883,-0.579246,-0.382552,0.570706,0.334311,0.009472,0.120427,0.366568,-0.524930,0.022053,0.063858,-0.383011,-0.748329,-0.078778,0.012301,-0.309777,-0.395499,0.385968,-0.265535,0.022404,0.183695,-0.442307,-0.149584,0.335835,0.004409,0.415166,-0.423149,0.066320,-0.084163,0.243551,0.755127,0.097189,-0.194808,0.258196,0.137283,-0.346737,0.382766,-0.285412,-0.444634,0.143292,0.257975,0.042435,-0.195030,0.012137,-0.501089,-0.393536,-0.298525,-0.071517,0.183246,-0.513779,-0.049457,-0.106873,-0.018326,-0.354159,-0.469621,0.214847,0.251153,-0.447698,0.823334,-0.979563,0.226769,0.648378,0.384949,-0.992241,0.641887,0.564578,0.157285,-0.027727,0.079501,0.161719,-0.090826,0.159342,-0.156258,0.369942,0.022043,-0.114630,-0.512687,0.517373', '30345227', '1296569', '1482072', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307305', '为你钟情', '剧情', '福水（张国荣 饰）是一个唱片骑师，风流不凡。与表弟海胆、好友沙皮组成了“求爱敢死队”，福水为求帮助两名单身男子寻找爱情。福水某日遇到了一个名叫余丽珍的美丽女孩，福水对阿珍一见钟情，展开了热烈的追求，花样百出。阿珍最后的防守被甜蜜的攻势感动，与福水相恋。这时忠厚老实的沙皮最终找到了自己的爱情，对方便是福水的妹妹。福水抗拒不已，与沙皮大打出手，才发现沙皮有不可告人的秘密……©豆瓣', '张国荣', '冯世雄', 7.5, 13100, 'tt0090304', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626267846.jpg', 0.5, 3.5, 37.4, 37.3, 21.4, '0.217384,-0.284736,-0.447652,0.555944,-0.060827,-0.156615,0.734994,0.068875,-0.286425,-0.073114,0.388387,0.705828,-0.362518,0.151754,0.227562,0.117050,0.170798,-0.703554,-0.039407,0.061258,0.041089,-0.169414,-0.504918,0.177685,-0.169789,-0.174675,0.536339,-0.139707,-0.244030,0.696286,0.622944,0.461675,-0.164872,0.359880,-0.198608,0.059449,0.273876,0.050192,-0.342474,0.129584,-0.201177,-0.142688,-0.091187,0.241298,-0.459797,0.360246,0.757653,-0.247239,-0.128997,-0.226785,0.209081,-0.266066,0.027047,0.141492,-0.007525,0.030414,0.283264,0.175437,-0.207232,-0.177955,0.116780,0.059160,-0.637185,0.047303,0.303262,0.072364,-0.451186,0.332252,-0.011431,-0.391348,0.316214,-0.320834,0.153359,0.352987,0.257566,0.187711,-0.224527,0.047152,-0.361096,0.223749,0.623316,0.136627,-0.098177,0.350453,-0.264080,-0.418230,0.331355,-0.099898,-0.357624,0.054474,0.377439,0.268679,-0.021788,-0.033253,-0.871385,0.059798,-0.309984,0.271411,0.183675,-0.513620,-0.423390,-0.342878,-0.367519,-0.480569,-0.314149,-0.023653,-0.010344,-0.284212,0.980198,-0.787646,-0.175620,0.456007,0.260342,-0.453368,0.643746,0.317555,-0.188398,-0.257700,-0.105326,0.067170,-0.271507,-0.082560,-0.100424,0.297930,-0.232410,-0.088509,-0.284664,0.206971', '3811356', '4127270', '4301278', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307306', '黄昏的清兵卫', '剧情', '幕府末年的海阪藩，下级武士清兵卫（真田广之）在妻子病逝后，以微薄薪俸独自照料痴呆老母和两个年幼女儿，由于每日结束工作后都是匆匆回家从不参加应酬，他被同僚们戏称为“黄昏的清兵卫”。与清兵卫青梅竹马的朋江（宫泽里惠）同丈夫离婚回到娘家后，常到清兵卫家代他照顾母亲和女儿，招来不少蜚言蜚语。清兵卫显露高超剑技击退了无理纠缠的朋江的前夫，然而当朋江的哥哥建议他迎娶朋江时，他却因不想让朋江吃苦婉拒了好意，致使朋江自此绝迹于他家。藩主得知清兵卫的才能后，强命他前去处决一名力敌数人据守不出的反叛武士。临行前，清兵卫向朋江表白了隐藏心底已久的爱意，不想对方已经答应另一门亲事，清兵卫黯然踏上生死未卜之途。©豆瓣', '真田广之', '山田洋次', 8.8, 30364, 'tt0351817', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1529771932.jpg', 0.2, 0.4, 7.8, 41.8, 49.8, '0.062722,-0.077947,-0.597725,0.653058,-0.029673,-0.191525,0.632573,-0.023153,-0.709171,-0.498293,0.138069,0.451314,0.319900,0.546335,0.344627,-0.530776,-0.016533,-0.618184,-0.126579,-0.110638,-0.372983,-0.147961,0.249432,-0.292432,-0.557477,-0.152541,0.653657,0.254766,0.075560,0.459810,0.337546,0.220391,-0.180178,0.538766,-0.082637,0.327432,-0.160008,-0.080879,-0.129782,0.041839,0.101086,-0.450537,-0.199887,-0.153114,0.372258,0.440755,0.634133,-0.106527,0.113058,-0.286081,-0.034768,-0.013234,0.241528,0.401353,0.308397,0.137344,0.168032,0.081586,-0.093820,-0.029485,-0.270385,-0.097130,-0.318768,0.053760,0.344410,-0.444764,-0.852245,0.434601,-0.210444,0.025445,-0.090596,-0.322340,0.005153,0.535822,-0.097894,0.199425,-0.162408,0.139925,-0.430643,0.555577,0.713844,0.070989,0.100072,-0.185772,0.051475,-0.281113,0.316097,-0.453689,-0.374943,0.101048,0.297433,0.088642,0.099832,0.160416,-0.158436,-0.397708,-0.307345,0.183684,0.101392,-0.395270,0.065659,-0.215079,0.222830,-0.376082,-0.091399,0.486656,0.231529,0.024010,0.428900,-0.758254,0.154344,-0.073407,0.458192,-0.892443,0.512861,0.098058,0.343115,-0.096854,0.403935,0.381374,0.296872,0.113128,0.388053,0.081331,-0.221076,-0.026855,-0.321980,0.141896', '1301022', '1293265', '1295746', '1872133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307311', '超胆侠', '动作', '律师马特（本•阿弗莱克 Ben Affleck 饰）在数年前为了救一命险些被货车撞倒的老人时，意外接触了一种放射性物质，这使得他双目失明，不过马特的其他器官却因此变得比常人灵敏百倍，即使不靠双眼，他也能洞悉身边发生的一切。马特有一名漂亮的女友，希腊大使的养女伊莱莎（珍妮弗•加纳 Jennifer Garner 饰），两人过着甜蜜的日子。一次，马特的父亲不幸受到歹徒加害而罹难了，马特伤心之余，决定靠自己的力量去讨回公道。于是，这个罪恶的城市里多了一个与罪恶交锋的勇士——夜魔侠。然而，由于黑暗已经笼罩了整个城市，马特在挑战黑暗势力时，内心也经历着黑暗的冲击。©豆瓣', '本·阿弗莱克', '马克·斯蒂文·约翰逊', 5.9, 29388, 'tt0287978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p620678534.jpg', 4.3, 22, 54.2, 14.4, 5.1, '0.208062,0.169079,-0.786719,0.653908,0.031751,-0.338868,0.991695,0.212659,-0.511985,-0.364311,0.205852,0.726170,-0.094627,0.181571,0.236555,-0.086932,-0.104847,-0.592968,-0.157736,-0.112915,-0.371851,-0.297759,-0.300327,-0.221236,-0.052228,-0.535756,0.503078,0.232314,-0.112569,0.356442,0.147433,0.168222,0.063721,0.523302,-0.082793,-0.103746,-0.036539,-0.070096,-0.229854,0.053650,0.047199,-0.201541,-0.060087,0.177075,-0.112513,0.257118,0.593505,-0.267625,-0.242324,-0.302947,0.467602,-0.132880,0.165581,0.189316,0.083088,-0.042936,0.162952,0.000758,-0.089070,-0.134303,0.289940,0.100146,-0.826785,0.083446,0.026165,0.017556,-0.582371,0.454736,0.031923,0.082556,-0.019094,-0.087281,0.127081,0.301311,0.012972,0.250303,-0.262200,0.018502,-0.430104,-0.074433,0.885368,-0.115202,-0.414412,0.294183,-0.352446,-0.485577,-0.289022,-0.248810,-0.541136,0.106071,0.495499,0.035319,-0.164537,0.659902,-0.554190,0.002165,-0.298959,-0.121610,-0.285433,-0.169872,-0.139766,-0.380745,-0.292664,-0.413789,-0.266079,0.023922,0.108163,-0.120307,0.539757,-0.604916,0.248823,0.596703,0.243973,-0.228031,0.506102,-0.094239,0.240497,0.022889,-0.163443,0.488545,0.053363,0.331487,0.211874,0.321625,-0.137920,0.082035,-0.324499,0.524563', '25828589', '26245360', '3014557', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307315', '哪吒闹海', '动画', '商末时期，陈塘关总兵李靖的夫人怀胎3年6个月，最终生下一个肉球，肉球中跳出一个伶俐可爱的男孩。李靖原当他是妖孽欲杀之而后快，幸太乙真人前来收之为徒，赐名哪吒，并赐以乾坤圈和混天绫两件宝贝。某年，天下大旱，甘露未降。哪吒和家将到东海洗澡玩耍。他用混天绫搅动海水，撼动龙宫，惹出巡海夜叉李艮和龙王三太子敖丙。几番言语不和，哪吒杀此二人，由此闯下通天大祸。四海龙王齐聚陈塘关索命，为救一方百姓，哪吒决定交出生命……本片根据《封神演义》故事改编，并荣获1980年电影百花奖最佳美术片奖；文化部1979年优秀影片奖、青年优秀创作奖；1983年菲律宾马尼拉国际电影节特别奖；1988年法国布尔波拉斯文化俱乐部青年国际动画电影节评委奖和宽银幕长动画片奖。©豆瓣', '梁正晖', '王树忱', 9.1, 239271, 'tt0354770', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2532803206.jpg', 0.1, 0.4, 6.3, 28.4, 64.8, '-0.401725,0.127927,-0.307394,0.521999,0.294948,-0.052293,0.083231,-0.046381,-0.512942,0.221960,-0.008919,0.640205,-0.318081,-0.151687,0.184177,0.094969,-0.159559,-0.434410,-0.190344,-0.024799,0.267838,0.027662,-0.155997,0.264402,-0.199349,-0.289088,0.684977,-0.234587,0.411044,0.495440,0.436629,-0.106642,-0.270263,-0.037964,-0.068424,0.310680,-0.215315,0.183978,-0.038521,0.475504,-0.342797,-0.132420,-0.469944,-0.088740,0.142553,0.039487,0.313302,-0.523455,0.037216,-0.360983,0.483489,-0.272124,-0.236407,-0.136272,0.300768,-0.159252,0.201585,0.299387,0.002348,0.175398,0.002583,-0.399735,-0.054085,0.079904,0.147117,-0.206623,-0.368479,0.241779,-0.010346,0.276328,-0.105325,-0.231187,0.131126,0.139324,0.082381,0.294377,-0.102015,0.162917,-0.305803,0.606804,0.298773,-0.218122,-0.039563,-0.327705,0.103272,-0.466148,-0.179325,-0.396385,-0.112757,0.327146,0.477018,-0.160977,0.183851,0.226118,-0.165183,-0.252064,-0.243014,0.053960,0.143511,0.064730,-0.139002,-0.216724,0.186527,0.007342,-0.065490,-0.583129,0.381312,-0.015912,0.767615,-0.246626,0.033048,0.317954,0.190316,-0.230314,0.841841,0.048585,0.128422,-0.229586,-0.158534,-0.004354,-0.052249,-0.031202,-0.094975,0.162591,-0.191980,-0.082116,-0.023563,-0.115098', '1418019', '1908036', '1780256', '2338019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307319', '醉拳2', '喜剧', '本片讲述的是一代宗师黄飞鸿年少时代一段历险。民初年间，年轻的黄飞鸿（成龙 饰）自学了一套威力无穷的拳法——醉拳。但是每次打出这套拳法，都要先喝得酩酊大醉，利用醉态打破一切武学定律，才能发挥出醉拳的威力。因为这样，黄飞鸿父亲黄麒英严禁儿子练这种有伤风雅、而且违背习武强身法则的拳法。年少顽皮的飞鸿常常背着父亲在练习醉拳，并以此打败了众多强手。这天，飞鸿和父亲一起上东北办事。半途上，父子俩遇上了一伙外国强盗，他们暗中将国宝玉玺偷运出境。为了阻止这伙强盗、夺回国宝，飞鸿只好使出他的拿手绝活——醉拳！©豆瓣', '成龙', '刘家良', 8, 70677, 'tt0111512', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2530261355.jpg', 0.2, 1.3, 24, 49.1, 25.4, '0.201910,-0.280434,-0.340290,0.561081,-0.052969,-0.238781,-0.176235,-0.257029,-0.227518,-0.596456,0.427507,0.743666,0.072192,-0.161322,0.008683,-0.335694,0.078256,-0.513424,0.306928,0.192167,0.177029,-0.339914,-0.289434,0.273148,-0.230381,-0.268312,0.172310,-0.257181,-0.448351,0.458747,0.055965,-0.169339,-0.034130,-0.082401,-0.228343,-0.027265,-0.236148,-0.064200,-0.310384,0.227560,0.177838,-0.334422,-0.255534,0.233770,-0.148013,0.025169,0.363522,-0.146539,0.050713,-0.168576,0.298493,-0.098391,-0.461843,-0.142528,0.193529,0.132468,0.398405,0.148439,0.163965,0.003521,-0.246888,0.038231,-0.661196,-0.070785,0.395145,-0.442353,-0.428420,0.143015,-0.191842,0.041340,-0.318409,-0.669886,0.046379,0.156620,0.306415,0.293208,-0.150656,-0.147088,-0.622148,0.274522,0.359769,-0.438316,0.017695,0.262942,-0.029887,0.208083,0.069017,-0.834879,0.000801,0.041468,0.204924,-0.135385,-0.192465,0.031290,-0.472914,0.064869,-0.201882,0.409763,-0.127066,0.007834,-0.082358,-0.535324,0.053894,-0.533868,-0.271824,-0.313786,0.314364,-0.228647,0.794945,-0.602646,-0.023771,0.303544,0.075734,-0.225491,0.280146,0.015678,0.155364,0.054154,-0.255210,-0.247614,0.096447,0.180666,0.097584,0.729098,0.133319,-0.206262,-0.221758,0.412607', '27602116', '24284209', '30465281', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307320', '人·鬼·情', '剧情', '中国北方的五十年代，童年秋云（王飞飞 饰），其父母都是行走江湖的戏班子演员，搭档唱传统剧目《钟馗嫁妹》。唱花旦的母亲（王长君 饰）跟男人私奔，这件事给父亲（李保田 饰）留下不可磨灭的阴影，他自此认为唱花旦就是女人不正经的象征。就是小秋云聪明伶俐，暗地里偷着学戏。成长为少女的秋云（贡琳 饰）在一次救场演出中被众人发现是一块“天生唱戏的好料子”。可父亲老秋却担心女儿步她母亲的后尘，执意要女儿离开戏班，但秋云直言宁愿从此唱男角也要继续唱戏。无奈，老秋只好教她唱生角，她很快成了戏班的台柱。长成大姑娘进入省剧团的秋云（徐守莉 饰）暗自爱慕着恩师张老师（姬麒麟 饰），但张老师在乡下有老婆孩子。人言可畏，张老师为了秋云的前途，被迫离开了剧团。“文革”结束后，已是两个孩子母亲的秋云决心重返舞台，重唱《钟馗嫁妹》，终于以精湛的技艺蜚声国内外。但艺术上的成功却掩盖不了秋云情感上的痛苦......', '裴艳玲', '黄蜀芹', 8.5, 10844, 'tt0093844', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2337272317.jpg', 0.2, 0.8, 11.4, 49.5, 38.1, '-0.048903,-0.057962,-0.310454,0.497362,-0.207599,-0.343081,0.468606,0.132092,-0.576590,-0.154694,0.227211,0.627658,0.116720,0.328340,-0.013134,-0.022092,-0.218382,-0.563305,0.151228,0.057050,-0.011179,-0.209957,0.286841,-0.065530,-0.341976,-0.137421,0.465315,0.084454,-0.129328,0.266686,0.611677,-0.059814,-0.085069,0.082912,-0.263374,0.105645,-0.177009,-0.000147,-0.158324,-0.011029,0.027048,-0.219072,-0.209338,-0.158572,-0.026157,0.153166,0.536352,-0.071163,0.166243,-0.072193,0.413979,-0.126139,0.007476,0.082033,0.120181,0.049998,0.296914,0.147497,-0.238510,-0.030564,-0.131989,-0.220571,-0.325502,0.235346,0.442411,0.035692,-0.648484,0.499885,-0.020937,-0.094612,-0.036587,-0.240420,0.282294,-0.189889,0.330364,0.376417,-0.126285,0.172154,-0.274043,0.492563,0.476718,0.013321,0.060742,0.361008,-0.064972,-0.289978,0.078606,-0.349477,-0.521639,0.183646,0.067637,-0.088350,-0.150361,-0.057258,-0.193937,-0.215894,-0.094629,0.132461,0.028085,-0.466666,0.028485,-0.135564,-0.068034,-0.267656,-0.194559,-0.058812,0.121244,-0.278984,0.820607,-0.653920,0.211200,0.362114,0.047866,-0.450216,0.682101,0.096005,0.219551,-0.186838,-0.055135,0.227668,-0.459969,-0.026354,0.027472,0.356480,-0.007291,-0.202802,-0.099226,0.320792', '3445516', '1908036', '6963575', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307322', '式日', '剧情', '人烟寥落，阴霾苍凉。在这个与大都会形成鲜明对比的萧索小镇，两个有着不同背景的男女相遇了。一个是在东京小有成就的电影导演（岩井俊二 饰），然而他无法直视莫大的空虚与失落，渴望暂时逃离名利场，寻找创作的动力与激情；女孩（藤谷文子 饰）身着红色雨衣，在晴天里也打着雨伞，永远宣称明天是她的生日。仿佛受到命运的驱使，导演走近女孩的生活，并将镜头对准了这个藏着万千心事和愁绪的精灵。他跟随她走过废墟大楼的楼顶，以及其赖以栖身的地下室。烦躁、憎恶、忧愁、悲伤、喜悦、失落，各种情绪交错，不由分说将他们紧紧缠绕在一起……本片根据女主角藤谷文子的小说《逃避梦》改编。©豆瓣', '岩井俊二', '庵野秀明', 7.5, 5680, 'tt0269856', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2617318418.jpg', 1.5, 5.8, 31.9, 36.7, 24.2, '0.223028,-0.002492,-0.688340,0.580600,0.278668,-0.036735,1.102865,0.376323,-0.416394,-0.311795,0.308879,0.627083,-0.076602,0.439755,-0.027024,-0.078659,-0.343481,-0.734476,-0.232037,-0.042963,0.071009,-0.280104,-0.238353,-0.144236,0.020157,-0.355170,0.992839,0.256619,-0.169318,0.701902,0.417318,0.288512,-0.652196,0.656229,-0.165138,-0.292520,-0.062202,0.003597,-0.301948,0.067285,-0.298964,-0.227288,-0.083729,0.139229,-0.293642,0.224271,0.971441,-0.041723,-0.163204,0.368723,0.351786,-0.240186,-0.116522,0.199891,-0.049837,0.042215,-0.038931,-0.028041,-0.299483,0.060130,0.060076,-0.187546,-0.703311,-0.076669,0.013368,0.526291,-0.540409,0.652877,0.124355,-0.404679,0.251256,-0.113770,0.370112,-0.053874,0.190486,0.394311,-0.378157,0.164431,-0.280243,0.336024,0.392386,0.088080,-0.098684,0.427484,-0.571063,-0.092608,-0.266944,0.251932,-0.760846,-0.328043,0.339754,0.189436,-0.185378,0.163476,-0.775407,0.093607,0.160743,0.001696,-0.129098,-0.651579,-0.164678,-0.504864,-0.241730,-0.319229,-0.317698,-0.089252,0.133890,-0.055166,0.632126,-0.664223,0.356095,0.416715,0.287568,-0.028931,0.676885,-0.059562,-0.046331,-0.122780,-0.118098,0.669230,-0.243647,0.282001,0.061388,0.419417,-0.390484,0.347687,-0.675336,0.586624', '1467779', '21619567', '3097044', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307323', '天下无双', '喜剧', '正德皇帝（张震）与其御妹无双（王菲）均厌倦了皇宫的单调生活，想偷偷溜出宫去看看外面的世界。无双女扮男装先行一步来到江南的梅龙镇，结识在此开店的阿龙（梁朝伟）阿凤（赵薇）兄妹后被阿龙喜欢上，她也爱上了阿龙。无双身份暴露被带回皇宫时，正德皇帝微服来到梅龙镇，并在阿凤遭遇歹徒挑衅时拔刀相助，两人结识后经过一段日子相处产生感情。因无法忍受对阿龙的思念，无双再次从宫里逃回梅龙镇，四人在店中相会，并在误会尽除后私定终生，不料遭到太后的阻拦。©豆瓣', '梁朝伟', '刘镇伟', 7.2, 184602, 'tt0311913', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2205490720.jpg', 1, 6.4, 41.1, 35.3, 16.2, '0.558822,0.124295,-0.611043,0.250275,0.226647,-0.332002,0.716263,0.185607,-0.882186,-0.071159,0.321580,0.605143,-0.435041,0.127433,0.389642,0.011641,-0.369441,-0.599544,0.072501,-0.603910,0.080632,-0.245826,0.348002,0.031222,-0.254589,-0.288988,0.414520,-0.183254,-0.029907,0.867798,0.169426,0.097177,-0.431315,0.705801,-0.142157,0.213585,0.032312,0.163269,-0.567139,0.352518,0.091455,-0.392919,-0.197665,0.006368,-0.114794,-0.111326,0.489733,-0.284472,-0.156150,-0.243041,0.290647,0.133567,-0.013845,0.116922,0.257212,0.070186,0.148970,0.444003,-0.346884,0.181924,-0.232483,0.052494,-0.090663,0.281752,0.044196,-0.121783,-0.417104,0.531551,0.029178,-0.226101,0.017715,-0.400122,0.341756,0.322050,0.212512,0.035984,-0.164988,0.243573,-0.330272,0.028067,0.853852,-0.139428,0.140992,0.254601,0.470033,-0.017817,0.163137,0.013301,-0.396973,0.042106,0.097203,0.123737,-0.359106,0.170419,-0.366090,0.152979,-0.454014,0.141982,0.187706,-0.126277,-0.245822,-0.628550,-0.469222,-0.417903,-0.383310,-0.151152,0.152189,-0.121730,0.123604,-0.825921,0.358113,0.255084,0.403916,-0.612933,0.599072,0.037416,0.077310,-0.057831,-0.312058,0.344173,0.065893,0.352359,-0.045582,0.295654,-0.207707,-0.080449,-0.485553,0.120692', '25856453', '25721544', '1308755', '1306465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307332', '冷山', '剧情', '美国南北战争时期，连连征战和南方军队的节节败退令士兵Inman（Jude Law 饰）心灰意冷，为了再见情人Ada（Nicole Kidman饰），他离开部队，踏上了漫漫回家路。在他的家乡，偏僻的冷山镇，Ada也饱受生活的折磨和等待的痛苦。父亲的去世和奴隶的离开，使养尊处优的Ada生活难以为继，在山区女孩Ruby Thewes（Renée Zellweger 饰）的帮助下，Ada渐渐学学会与周围粗砺尖锐的生活对抗挣扎，期待Inman的归来。穿越连绵战火，冷山，是他们之间唯一的连系，在这里，即使旧日所有的信仰天堂都已破灭，却仍能让你疗伤止痛。©豆瓣', '裘德·洛', '安东尼·明格拉', 8.2, 131673, 'tt0159365', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1944306007.jpg', 0.1, 1.2, 18.2, 49.9, 30.5, '-0.045616,-0.070381,-0.776764,0.535947,0.255968,-0.256290,0.727783,0.126339,-0.381804,-0.158598,0.064855,0.631797,0.237116,0.215095,0.099268,-0.233220,-0.231313,-0.616399,-0.104722,0.069063,-0.180380,-0.145332,-0.338608,-0.210759,-0.216302,-0.397294,0.869276,0.539551,-0.116784,0.725682,0.050207,0.165066,-0.143757,0.524259,-0.580564,-0.221312,-0.240478,0.166334,-0.531315,-0.084395,-0.126248,-0.231311,-0.073516,-0.033015,0.139869,0.222042,0.658803,-0.173107,-0.050334,0.021512,0.074044,-0.315141,-0.113913,0.144998,0.137988,-0.070524,0.100300,0.292678,-0.148055,0.151280,-0.241634,0.017581,-0.662966,0.018179,0.216920,-0.045465,-0.770413,0.566659,0.229523,-0.162551,0.125951,-0.407211,0.472043,0.606338,0.058921,0.708853,-0.331837,0.157479,-0.472599,0.224781,1.018686,-0.219876,-0.314795,-0.001767,-0.265533,-0.241873,-0.014876,-0.334763,-0.715120,-0.270775,-0.078029,0.001100,-0.302004,0.376442,-0.696977,0.208957,-0.042869,-0.359373,0.120683,-0.534982,-0.135459,-0.480386,-0.062992,-0.492826,-0.234423,0.362883,0.057008,-0.086107,0.681039,-0.664082,0.433984,0.355257,0.601345,-0.634839,0.665144,0.231332,0.180755,0.008315,0.103759,0.980156,-0.097766,0.579812,0.127816,0.015340,-0.214308,0.361175,-0.476126,0.568573', '25721544', '4728584', '30209018', '35287908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307345', '古惑仔情义篇之洪兴十三妹', '剧情', '钵兰街的大姐大洪兴十三妹（吴君如饰）从东星混混花弗（敖志君饰）手中救回女友SASA（植敬雯饰）。不料SASA早暗地里与花弗串通陷害十三妹，十三妹一怒之下对其家法处置。属下韩宾（尹阳明）一直对十三妹忠心耿耿，更把爱意放在心底。一次韩宾陪同十三妹拜祭亡父阿达（吴孟达饰），遂让十三妹回忆起昔年往事。十三妹原名崔小小，其父是洪兴一名小混混，她与好友张美润（杨恭如）整日混迹于玻澜街，一起为东星打手卓可乐（方中信）神魂颠倒。岂料恶霸咸湿（程东）杀死了吹水达，十三妹决定为父报仇……©豆瓣', '吴君如', '叶伟民', 7.2, 36324, 'tt0148631', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1519913207.jpg', 0.7, 4.5, 42, 37.8, 15.1, '-0.395945,-0.425748,-0.240425,0.479571,-0.170887,-0.563047,0.047130,0.110271,-0.560580,-0.229169,0.003553,0.133448,-0.286391,0.420062,0.107253,-0.171979,0.043323,-0.661722,-0.356249,0.123228,-0.020532,-0.449699,0.147696,0.183946,-0.163867,0.141047,0.045828,-0.281234,-0.169997,0.561475,0.550677,0.504843,-0.572850,0.059721,0.054185,0.180002,0.060643,-0.206901,-0.188148,-0.156814,-0.040334,-0.355189,-0.007059,-0.082441,0.221140,0.063556,0.701048,-0.184469,0.267491,-0.447402,-0.058509,0.085482,-0.294394,-0.216145,0.071641,-0.380788,0.101804,0.410308,0.158445,-0.072521,0.015824,-0.272378,-0.115491,0.079665,-0.128721,-0.281211,-0.904778,0.029427,-0.565634,0.355268,0.171389,0.003629,0.079244,-0.010608,0.298745,0.147727,-0.192503,0.067605,-0.123785,0.194520,0.321073,0.244127,0.504213,-0.027776,0.715568,0.027194,0.105572,-0.062663,-0.123301,0.174667,0.081062,-0.247869,0.141562,0.338320,-0.362011,-0.594932,-0.348537,0.383316,0.456992,-0.070585,0.025307,-0.127737,-0.230872,-0.449164,-0.232089,-0.317856,0.441207,-0.218245,0.637037,-0.609614,0.329213,-0.055852,0.076657,-0.561201,0.314989,0.326357,-0.226319,-0.270238,-0.305081,-0.430162,0.520783,-0.054912,0.447445,0.223412,-0.462616,-0.462720,-0.194262,-0.338475', '27621189', '1296196', '26730542', '4946963');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307354', '绿巨人浩克', '剧情', '冷战时期，布鲁斯·班纳（艾瑞克·巴纳 Eric Bana 饰）的父亲是美军的一位科学家，致力于研究通过基因改造让人类获得超强的能力，想以此为美军打造超级士兵。可是他的项目没有获得美军的支持，不能进行人体试验，疯狂的父亲为了完成试验就在刚出生的班纳身上进行基因试验。多年后，班纳成为了出色的科学家，专职为军方开发新型的高能炸弹。在一次例行的试验中，由于操作失误，班纳为了保护同事，受到了一场伽马射线的强力辐射。常人如果在这场射线爆炸下肯定必死无疑，可是班纳却活了下来。多年前，父亲在其身上做的试验也因这场核辐射生效。一旦班纳发怒时，就会诱发身体里的神秘力量，变为毫无意识的绿巨人，拥有超强的破坏力和反抗意识。因此，美国军方为了深入研究，开始围追堵截绿巨人……©豆瓣', '艾瑞克·巴纳', '李安', 6.8, 115401, 'tt0286716', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2407903929.jpg', 1.1, 7.9, 51.7, 29.7, 9.6, '-0.087533,0.134658,-0.760252,0.654989,-0.358155,-0.149540,0.563762,-0.327525,-0.531364,-0.442707,0.357746,0.611642,-0.189401,-0.093642,-0.352471,-0.235465,-0.332490,-0.524440,-0.218303,0.265494,-0.652429,-0.471073,-0.565889,-0.248632,-0.051579,-0.706834,0.837145,-0.063408,-0.537665,-0.095720,-0.035904,0.425111,0.172652,0.314739,0.165092,-0.436298,0.080483,-0.131655,-0.358570,0.554336,0.336295,-0.287612,0.271723,0.231579,0.139740,0.174282,0.596367,-0.378094,-0.158017,-0.548600,0.455602,-0.226209,0.081926,0.032449,0.465915,0.352537,0.044776,-0.055125,-0.014812,0.024509,0.204040,0.094359,-1.247493,-0.337357,0.015533,-0.208290,-0.429842,0.234953,-0.208933,-0.003158,-0.085381,-0.190263,-0.035091,0.504845,0.456164,0.297937,-0.487528,0.195922,-0.215587,0.027932,0.652119,-0.260059,-0.702145,0.296190,-0.330475,-0.577930,-0.039479,-0.488238,-0.052391,-0.035840,0.114833,0.432042,-0.155878,0.379111,-0.577400,0.155412,-0.594801,-0.352530,-0.047147,0.042754,0.032280,-0.853648,-0.106951,-0.205926,-0.205993,0.119385,0.178648,-0.656616,0.751458,-0.845996,0.252693,0.627148,0.260530,-0.475297,0.123053,-0.040732,0.044595,-0.297824,0.083698,0.046817,-0.079035,0.341168,0.221156,0.146351,0.364529,-0.088992,-0.238155,0.558960', '1793491', '27073234', '1811755', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307363', '十日拍拖手册', '喜剧', '美女安蒂(凯特•哈德森饰)是一家时尚杂志的专栏作家，负责撰写“恋爱指南”之类的情感文章。某天，主编给她派了一个棘手的任务：搜集怎样甩掉男人的第一手资料。因此，安蒂必须在十天之内找到一个男朋友，然后再甩掉他。安蒂看上了在广告代理公司工作的本杰明(马修•麦康纳饰)，磨刀霍霍，准备实施她的计划；谁知道，本杰明是一个典型的花花公子，游戏人间的他正在和老板打赌：十天之内让一个女人彻底爱上他。干柴烈火，一拍即合，他们开始了真真假假的爱情游戏。©豆瓣', '凯特·哈德森', '唐纳德·皮特里', 6.7, 23862, 'tt0251127', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p892393680.jpg', 1, 6.8, 54.1, 30.3, 7.9, '0.247920,-0.003537,-0.397595,0.579746,-0.387816,-0.289545,0.339687,0.001174,-0.237916,-0.116272,-0.063931,0.565591,-0.134984,0.206472,0.337166,0.115884,-0.371041,-0.768034,-0.003264,-0.333948,-0.200627,-0.537018,-0.284788,-0.310087,0.276106,-0.050453,0.471380,-0.234819,0.035152,0.089295,0.480718,0.058833,0.099138,0.296304,-0.136057,-0.017716,0.274336,-0.285568,-0.276265,0.446617,0.080439,0.019963,0.066729,0.162873,-0.126326,0.336911,0.587943,-0.084314,-0.228541,0.055515,0.585086,-0.269196,-0.093170,0.078165,0.144546,-0.135598,0.118037,0.167726,-0.400816,-0.104802,0.104754,-0.076159,-0.721795,-0.277477,-0.351521,0.208406,-0.503295,0.402168,-0.286833,0.275211,-0.064952,-0.496877,0.026598,0.360595,0.334395,0.049270,0.081502,0.020935,-0.567857,0.384133,0.412443,0.191258,0.198392,0.428343,0.117030,-0.233936,-0.127943,0.055937,-0.547491,-0.192413,0.396282,-0.223492,-0.218328,-0.162997,-0.607732,-0.025793,-0.204105,-0.247556,0.033359,-0.587477,-0.194767,-0.633732,-0.181195,0.018567,-0.422944,-0.214083,0.242420,-0.374710,0.783223,-0.804858,0.130509,0.855053,0.077998,-0.567293,0.678125,0.328680,0.074849,-0.341222,-0.052569,-0.090405,0.209622,0.428142,0.050775,0.490760,0.238766,-0.319833,-0.461073,0.590622', '3785918', '4301278', '24733428', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307371', '开心鬼', '喜剧', '清朝，连考十多次也没能中上状元后，朱秀才（黄百鸣）气死了老爹、气走了老婆，自己也含冤于某一寺庙悬梁自杀，结果无法投胎，灵魂被附在了他自杀时所用的麻绳上。时间来到1980年代，香港高中女生林小花（李丽珍）、林青青（罗明珠）和颜如玉（林珊珊）暑期旅行的路上遭遇暴风雨，为避雨，她们闯进朱秀才自杀的寺庙，雨毕，林青青于慌乱中将附有朱秀才灵魂的那根麻绳带进住室，惹来一片惊声尖叫，但随着交流的深入，她们慢慢与朱秀才成为无话不谈的朋友，而彼此通过对方的鼓励，更加清楚了接下来要走的路——当然，这一过程中，没少闹笑话。©豆瓣', '黄百鸣', '高志森', 7.6, 52791, 'tt0087528', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1995000284.jpg', 0.3, 2.3, 34, 45.9, 17.5, '-0.026116,-0.139883,-0.522993,0.475795,0.032894,-0.695425,0.593227,0.134071,-0.591091,-0.179529,-0.336894,0.369377,-0.528792,0.348296,0.140866,-0.377790,-0.057170,-0.436227,-0.071076,-0.150849,-0.459186,-0.287720,0.274841,-0.199500,-0.324483,0.135634,0.283442,0.145939,-0.357249,0.166896,0.394898,0.141129,-0.112876,0.442484,-0.146328,0.354311,0.020300,-0.005894,-0.239924,0.162076,0.360587,-0.306081,-0.037287,-0.209980,0.060866,0.099424,0.801229,-0.109356,-0.011547,-0.028138,0.453192,-0.211316,-0.147818,0.214999,0.415943,-0.133422,0.166763,-0.261251,-0.104602,0.034704,0.325831,-0.113101,-0.190334,0.197106,0.120114,-0.143767,-0.400893,-0.058465,0.184875,0.281472,-0.023369,-0.364210,0.514038,0.357202,0.409144,0.036991,-0.372692,-0.065015,-0.481871,0.472328,0.690413,0.099977,0.153193,0.147974,-0.255283,-0.483830,0.161283,-0.022820,-0.290686,-0.034164,0.748964,0.105401,-0.140671,-0.020502,-0.098117,-0.394712,-0.179404,-0.033685,-0.192570,-0.344736,-0.153946,-0.183714,-0.084032,-0.392553,-0.085589,0.040185,0.102481,-0.174879,0.308727,-0.476862,0.115181,0.219531,0.036341,-0.296493,0.623070,-0.163918,0.242026,-0.124521,0.295414,0.133683,0.119852,0.648144,0.532152,0.490105,-0.181258,0.054440,-0.239396,0.391603', '24753687', '1293142', '3036997', '1296266');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307372', '一个字头的诞生', '喜剧', '阿狗（刘青云饰）是三十多岁的黑社会马仔，他处于艰难的抉择中，要么继续浑浑噩噩的在黑道上混下去，要么轰轰烈烈的大干一场。于是发生了两个截然不同的故事结局。他跟随黑帮偷运货车，但由于乌合之众组织不善，阿狗也在他乡不幸命丧黄泉。第二个故事，有着大团圆的结局：阿狗因为英雄神武，为人果断机警，行动屡屡成功，被阿猫看中，邀他一同去台湾当杀手，在台湾威霸一方，阿狗的“大志”得以实现。©豆瓣', '刘青云', '韦家辉', 8.3, 51908, 'tt0120541', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2553131199.jpg', 0.4, 1.7, 15.8, 47.8, 34.3, '0.247216,0.094392,-0.600810,0.173700,-0.134326,-0.045386,0.350098,0.140409,-0.670315,0.015358,0.493408,0.778937,0.353351,-0.128996,0.263591,-0.315937,-0.142955,-0.640214,0.091608,0.066392,-0.096724,-0.292266,-0.236627,-0.216219,-0.091734,0.022543,0.705730,0.065624,-0.134710,0.512393,0.409839,0.339043,-0.296671,0.348521,-0.157262,0.066280,0.031471,-0.170100,-0.520476,0.151378,-0.278324,-0.342970,-0.212514,0.036199,-0.088647,0.355013,0.478666,-0.302751,-0.207227,0.094727,0.167396,-0.419951,-0.681310,0.039500,0.404219,-0.146566,0.000353,0.273885,0.080547,-0.222398,-0.054807,0.092979,-0.822591,-0.092904,0.174198,0.325977,-0.519844,0.521240,0.233610,-0.049615,0.119972,-0.259311,0.079913,0.381505,0.550992,0.003216,-0.018495,0.199038,-0.471621,0.375203,0.939161,0.228131,-0.006907,0.109833,0.221402,-0.321729,0.044561,-0.629955,-0.341221,0.035711,0.376746,-0.194607,-0.514009,0.049846,-0.488710,-0.004339,0.014003,0.133752,-0.314210,-0.285661,-0.088716,-0.269834,-0.154633,-0.196684,-0.195701,0.087264,-0.022194,-0.163136,0.743677,-0.764459,0.089759,0.585405,0.066745,-0.597642,0.690744,0.213531,0.130878,-0.326883,-0.017886,0.260751,0.259069,0.234763,0.205766,0.213732,-0.288565,-0.215726,-0.131678,0.280800', '25721544', '26678784', '35030151', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307389', '憨豆特工', '喜剧', '英国皇室的珠宝被盗，引起了高度紧张。情报局随即派出了最顶尖的特工——“天字第一号”去追查珠宝案，然而，案件未查出半点头绪，“天字第一号”就被人谋杀了。在“天字第一号”的葬礼上，英国情报局的顶级特工遭到了炸弹袭击，全部牺牲了。不久，情报局收到消息，这伙坏蛋准备打英国皇冠的主意。但是情报局的顶级特工都牺牲了，无奈之下，只好派出菜鸟特工——强尼•英格利（罗温•艾金森 Rowan Atkinson 饰），绰号“特务憨J”。强尼智勇皆无，不过他有先进武器、“八卦”的本领，强尼最后能否捍卫英国皇室的尊严？©豆瓣', '罗温·艾金森', '彼得·休伊特', 7.7, 113126, 'tt0274166', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2521404612.jpg', 0.3, 2.4, 29.2, 48.7, 19.3, '0.212171,0.038662,-0.738247,0.400022,0.033348,-0.106917,0.096378,0.070505,-0.580696,-0.171040,0.312471,0.516266,0.015858,-0.413607,0.082648,-0.030562,-0.516861,-0.630532,-0.110021,-0.498040,-0.357944,-0.559082,-0.220292,-0.460514,0.063687,-0.211672,0.493100,0.202946,-0.190131,0.133599,0.504357,0.521408,0.050399,0.395093,-0.137687,-0.047904,0.820740,-0.240898,-0.053643,0.257568,-0.121582,-0.433028,0.060433,0.424685,0.103458,0.466111,0.184594,-0.149258,0.187579,-0.366511,0.272932,-0.483777,-0.136263,-0.070441,0.730642,0.049818,-0.079087,0.327217,-0.007945,-0.185671,0.458789,0.184819,-0.825421,-0.048000,0.256870,0.153156,-0.501758,0.313694,-0.567416,0.139405,-0.091350,-0.066317,0.666070,0.178684,0.135537,-0.112396,0.268181,0.339259,-0.611827,0.274742,0.411645,-0.099794,-0.044524,-0.227022,0.058879,-0.519851,0.099679,-0.699276,0.115752,0.024131,0.409960,-0.332755,-0.016564,0.036277,-0.483043,-0.250267,-0.324542,-0.234434,-0.154980,-0.267500,-0.015338,-0.726332,0.017784,-0.119780,-0.370749,0.204074,0.263251,0.251266,0.815726,-0.522447,-0.026688,0.745610,0.056503,-0.502838,0.432477,-0.018802,-0.014040,-0.090388,-0.160144,-0.120903,0.365395,0.497295,0.212470,0.102490,-0.076926,-0.788541,0.119102,-0.210400', '10463953', '1306470', '1298155', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307394', '千年女优', '剧情', '60岁的立花源也和28岁的摄影师井田恭二不远千里跋山涉水上门去拜访隐居了三十年的一代影星藤原千代子，为了给她拍摄一生自传的纪录片。款款前来的千代子虽然已界75岁高龄，但仍然优雅美丽，左眼下标志性的小痣也仍然俏皮。立花双手递上一把钥匙，千代子深受震动，称这把钥匙是开启一个 秘密的关键，当年她不慎丢失，今日竟还能再回手中。千代子的思绪飞到老远。1926年9月1日，藤原千代子呱呱坠地，水灵清秀的她16岁就被星探发掘，然而直到遇上一个画家，她救他于乱世中，藏于自家仓库内，他赠她一把钥匙，说这是开启秘密的关键，并承诺再与她重逢时带她去看北海道的雪。然而次日千代子放学归家时画家已经因为逃开追捕逃离远去。千代子自此进入电影圈，只因为画家最后说他会去满洲作战，而第一部电影承诺会去满洲取景。从此千代子的银幕生涯拉开，拍摄了代表日本战国、幕府、大正及昭和等四个不同时期的大时代爱情故事。在每一个故事里，千代子都在奔跑，追寻着自己的真爱。场景与她本身的故事糅合在一起，虚实难分。立花和井田紧随其后身临其境，时而变成故事中人物。然而千代子丢失了钥匙，心灰意冷的她嫁给了一直追求她的导演大泷。到后来她发现一切是一个精心布下的骗局，千代子认清事实后决意继续找寻自己少女时代的所爱。', '庄司美代子', '今敏', 8.8, 238476, 'tt0291350', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2215102596.jpg', 0.3, 0.8, 9.8, 36.2, 52.9, '-0.014174,0.318290,-0.581718,0.354881,-0.151047,-0.259801,0.446778,-0.080433,-0.251818,-0.389729,0.159149,0.783283,-0.051845,0.463645,0.299261,0.233346,-0.151862,-0.745429,-0.109978,-0.201893,-0.114013,-0.083527,-0.105932,0.085583,-0.214504,-0.095731,0.725472,0.187605,-0.097297,0.415986,0.216994,0.059236,-0.351760,0.247349,-0.130686,0.198471,-0.196366,0.110539,0.010492,0.354845,-0.251297,-0.467799,-0.253667,0.055377,-0.076369,0.508064,0.496268,-0.241730,0.034968,-0.132166,0.380128,-0.156502,-0.406277,0.303645,0.151621,0.113377,0.192399,0.160833,-0.407669,-0.052524,-0.085895,-0.332691,-0.418935,0.126571,-0.063064,0.130696,-0.689462,0.335433,-0.148676,-0.216347,0.342106,-0.401083,0.035910,0.213166,0.218098,0.132795,-0.226944,0.216816,-0.274722,0.197501,0.393744,-0.106341,-0.124859,0.344212,0.251456,-0.364643,-0.237282,-0.420358,-0.346597,0.120621,0.346867,0.171553,-0.178429,-0.038684,-0.423130,-0.079236,-0.296211,0.039105,0.294140,-0.157029,-0.216204,-0.473083,0.010190,-0.455827,-0.419199,0.065643,0.208651,-0.442275,0.736396,-0.552100,0.083770,0.557146,0.216524,-0.171187,0.5