INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307404', '愈快乐愈堕落', '剧情', '年轻的男同性恋阿哲（柯宇伦）对同龄人不感兴趣，爱上在游泳馆游泳时总是一言不发旁若无人的已婚男人冯伟（陈锦鸿），然而因为自信的缺失，他没敢同冯伟表白，而是借助与冯伟的妻子月纹（邱淑贞）发生性关系，在想象中完成与他的肌肤之亲。月纹的意外死亡令冯伟想起之前两人冷淡的关系，明白到月纹在心中所占分量，陷入自责中不能自拔，陪在他身边暗恋他的基佬（曾志伟）虽心疼却也不敢表示出太过直白的关心，只能规劝凡事想开慢慢会好。阿哲亦觉自己应为月纹的死负一定责任，愧疚地逃到台北，偶遇外形同月纹不差的rose（邱淑贞），借醉酒将自己的压抑吐出之后，rose要他对心诚实，可是她又有着怎样的心事，又是如何排解，却是无人能知。©豆瓣', '邱淑贞', '关锦鹏', 7.3, 10514, 'tt0144029', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363126351.jpg', 0.7, 4, 40.4, 41.7, 13.3, '0.100204,0.197569,-0.828323,0.310023,-0.211730,-0.283353,0.776293,-0.114959,-0.609362,0.083846,0.227341,0.413080,-0.291118,0.242636,0.176620,-0.081499,-0.110855,-0.512047,0.266543,-0.265205,-0.077511,-0.649628,-0.191860,0.008166,-0.237362,-0.257629,0.495839,0.145767,-0.192069,0.198268,0.412377,0.342520,-0.072455,0.636400,0.095365,-0.065036,-0.477386,0.220430,-0.224654,-0.237370,0.266199,-0.249407,-0.282431,0.139896,0.021850,0.304825,0.622662,-0.153488,-0.396238,0.029784,0.493296,-0.198598,-0.141802,0.048961,-0.151301,0.225038,0.174368,0.093613,-0.073630,-0.252600,-0.005350,0.137342,-0.358030,0.066901,0.167928,0.294372,-0.522809,0.451119,-0.153392,-0.070169,0.154013,-0.140942,-0.105338,0.295270,0.194547,0.415886,-0.392746,0.200076,-0.354996,-0.050297,0.671885,0.340072,-0.206768,0.216380,-0.167228,-0.346029,-0.091637,-0.300877,-0.353885,0.132264,-0.128423,0.460051,-0.316295,0.118691,0.007815,-0.012875,0.089178,0.194600,0.062074,-0.506814,-0.080343,-0.218213,-0.228023,-0.633055,-0.284198,-0.099284,0.169667,-0.321590,0.354524,-0.842937,0.317570,0.356086,0.524482,-0.505714,0.441809,0.478859,-0.165845,-0.305322,-0.291944,0.478013,-0.295073,-0.084144,0.192388,0.262163,0.073712,0.156782,-0.395479,0.187556', '1301022', '1308047', '25870679', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307427', '泳池情杀案', '剧情', '早已功成名就的女性神秘小说家莎拉•莫顿（Charlotte Rampling 夏洛特•汉普林 饰）却为新作烦恼不已，在出版商约翰•布兰德（Charles Dance 查理士•当斯 饰）的建议下，她来到约翰的家乡别墅，一面休养，一面寻找灵感。乡间的悠哉生活使莎拉从久居伦敦的疲惫中解脱出来，尽情享受着难得的休闲时光。某晚，自称约翰女儿的茱莉（Ludivine Sagnier 卢蒂文•萨尼埃 饰）不宣而至，茱莉开朗、张扬、放荡，与古板莎拉格格不入。莎拉的创作计划被打乱，而一丝不祥的气息也悄然弥漫开来……本片荣获2003年欧洲电影界最佳女主角奖（夏洛特•汉普林）、2003年曼谷国际电影节最佳影片奖。©豆瓣', '夏洛特·兰普林', '弗朗索瓦·欧容', 7.4, 22664, 'tt0324133', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193661074.jpg', 0.6, 3.1, 34.3, 49.1, 12.9, '-0.011883,0.073527,-0.496155,0.522640,0.091711,-0.388722,0.690538,0.077701,-0.528620,-0.305233,0.307839,0.653253,-0.388509,0.310939,0.572942,0.272875,-0.559478,-0.495970,-0.096638,-0.127410,0.248958,-0.161063,-0.466270,-0.089473,-0.278754,-0.588959,0.400785,0.081219,0.094302,0.647007,0.299256,0.319176,-0.211727,0.309622,-0.086817,-0.141034,0.134695,-0.056318,-0.381005,0.207894,0.098884,-0.346232,-0.471121,-0.018366,0.133307,0.142965,0.799736,-0.077634,0.061195,0.046881,0.607613,-0.036165,0.019370,-0.020797,0.033090,-0.184231,0.080789,0.058619,-0.173181,0.149619,0.019583,-0.178336,-0.397412,0.287147,-0.001105,0.289414,-0.195606,0.370769,-0.111019,-0.114424,0.216314,-0.461793,0.021012,-0.006966,0.176513,0.298515,-0.014241,0.420164,-0.236459,0.425569,0.368562,0.169204,-0.398875,0.297578,-0.699542,-0.301153,0.044552,-0.059249,-0.688692,-0.490718,0.181319,0.058193,0.199420,0.291338,-0.653281,-0.120358,-0.107960,-0.134496,0.005484,-0.050878,-0.115224,-0.776027,-0.285497,-0.064629,0.010999,-0.175955,0.127370,-0.140282,0.524107,-0.514705,0.507613,0.563496,-0.073278,-0.104932,0.538886,-0.123643,0.072980,-0.182035,-0.299836,0.674765,-0.227847,0.075495,-0.084628,0.447574,-0.336196,-0.182744,-0.479279,0.559758', '1308069', '4706257', '25925764', '2968813');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307442', '速度与激情2', '动作', '迈阿密狡猾的商人卡特（科尔•豪瑟 Cole Hauser 饰）利用自己的贸易公司做幌子，暗中进行着国际洗钱活动。虽然FBI对他监视已久，但是卡特平日十分小心谨慎，几乎与世隔绝，所以一直没找到他的犯罪证据。FBI获悉了卡特十分喜欢地下赛车，是当地飞车党的头目。为了获得他的 犯罪证据，只好找上一集中成功破获洛杉矶飞车党劫车案的布赖恩（保罗•沃克 Paul Walker 饰）重新出山。布赖恩凭借出色的车技、和飞车党一起进行犯罪活动很快就赢得了卡特的信任，并和他成了好朋友。同时，另一名同为飞车党卧底的女警梦妮卡（伊娃•门德斯 Eva Mendes 饰）闯进了布赖恩的生活，布赖恩不知不觉中爱上了梦妮卡。梦妮卡已经获得了不少卡特的犯罪证据，但是她和卡特之间的暧昧关系却说不清道不明。©豆瓣', '保罗·沃克', '约翰·辛格顿', 7.5, 142142, 'tt0322259', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2234440406.jpg', 0.4, 3.5, 36, 41.9, 18.2, '0.430715,0.013908,-0.687212,0.629718,-0.156913,-0.363961,0.587082,0.038414,-0.483421,-0.082419,-0.085812,0.613658,-0.118673,0.037125,0.336627,0.149049,-0.550064,-0.984645,0.014005,-0.116003,-0.147296,-0.808417,-0.344564,-0.214936,-0.281152,-0.261883,0.378336,0.170975,-0.170870,0.304302,0.322081,0.372272,0.001244,0.422792,0.050698,-0.185959,0.266515,-0.424871,-0.338572,0.258847,0.005759,-0.139548,-0.015372,0.183015,0.426232,0.542960,0.232545,-0.056633,-0.023935,0.057143,0.042105,-0.365826,0.164088,-0.095710,0.274581,0.039264,0.281197,0.274960,-0.264119,-0.171228,0.098655,-0.232714,-1.119831,0.039532,0.056009,0.077674,-0.364279,0.296869,-0.286238,0.176550,-0.128215,-0.170186,0.085484,0.331427,0.274891,-0.066350,0.015483,0.284206,-0.575656,-0.054500,0.488147,0.094381,-0.137359,0.099291,-0.136873,-0.365070,-0.040229,-0.266971,-0.015569,-0.104644,0.464835,-0.044240,-0.052300,0.067462,-0.610998,-0.059621,-0.353058,-0.254397,-0.008448,-0.317169,0.189401,-0.825072,-0.101919,-0.508864,-0.459343,-0.068468,0.050080,-0.332200,0.419353,-0.885641,0.102803,0.823684,0.206408,-0.438785,0.492499,0.118627,0.095726,-0.016315,-0.422937,0.140871,0.285711,0.329323,0.503791,0.206926,0.078021,-0.378995,-0.121801,0.494530', '1793491', '6790253', '3428500', '1418190');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307449', '六楼后座', '剧情', '六个死党，Candy(卢巧音 饰)、Karena(林嘉欣 饰)、梁Wing(周俊伟 饰)、Jean(邓健泓 饰)、Leo(周永恒 饰)、美颜宝(森美 饰)，偶然遇到了一间租约为一年的单位，租金十分便宜，六人租了这六楼后座。在这里面，他们最常玩的是“True or Dare”，游戏开始，他们便要卸下面具，勇敢面对问题，青春的荷尔蒙使然，让他们敢于面对这一切。新的一年即将来临，6个人立志要实现自己的理想，一年后无法达成的就要面临吃屎的惩罚。但订下了这个约定以后，每人都忙着发生在自己身上的事：Wing面临回美国读书；Jean被骗了所有积蓄；美颜宝与最爱重逢;Candy面对多角恋爱；Karena与素未谋面的老总谈情，更要面对Leo的暗恋。期限也即将来临，到底谁要接受惩罚呢？©豆瓣', '林嘉欣', '黄真真', 7.4, 16666, 'tt0379874', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2456242037.jpg', 0.9, 4.3, 34.2, 44.4, 16.2, '-0.003516,-0.073700,-0.546804,0.276230,-0.135836,-0.076421,0.546175,0.003965,-0.172525,-0.323949,0.090666,0.598195,-0.084431,0.295881,0.203635,0.036752,-0.103145,-0.628891,0.103459,-0.317983,-0.308120,-0.275817,-0.078146,0.018465,-0.181888,0.187053,0.499309,0.151061,-0.017087,0.305016,0.796276,0.136226,0.263707,0.314522,-0.211229,-0.204629,-0.009297,0.324990,-0.331028,0.192162,0.133841,-0.136011,-0.031165,0.191943,0.121074,0.132740,0.523115,-0.065061,-0.255718,-0.136307,0.292544,-0.239217,-0.073916,0.289328,0.129465,0.030070,0.141683,0.360810,-0.314582,0.201100,0.183159,-0.125326,-0.835246,-0.005744,0.096562,-0.065221,-0.674345,0.328333,0.044779,0.069187,0.104100,-0.080815,0.141982,0.537859,0.361447,0.422088,-0.241940,-0.194090,-0.618668,0.180225,0.782166,-0.173563,0.144372,0.401654,-0.144496,-0.307402,0.079703,-0.440945,-0.478427,0.225506,-0.130083,0.252890,-0.077408,0.011714,-0.683642,0.063991,0.117124,-0.101322,0.140233,-0.573385,-0.095104,-0.435393,-0.206199,-0.557366,-0.337816,0.395764,0.230362,-0.320789,0.679533,-0.763916,0.059953,0.314497,0.539666,-0.857053,0.620207,0.600732,0.215618,-0.433297,0.205674,-0.022962,-0.137538,0.221202,-0.088479,0.165797,0.229226,0.062863,-0.429742,0.553287', '4301278', '1877596', '26678784', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307456', '一本漫画闯天涯', '剧情', '经常沉醉在漫画世界中的酒吧侍应生阿星（周星驰 饰）很崇拜黑社会人物，机缘巧合，他被黑帮老大韦杰（杨群 饰）收为手下，并与其义子阿俊（林俊贤 饰）成为莫逆之交，两人同韦杰另一手下朱标（成奎安 饰）搭档做事时配合无间建了许多奇功，以致韦杰打算退休之前从手下众人中找一接班人时，三人成为首选。三人被 派赴泰国金三角进行毒品交易，不想中途生出诸多波折，好不容易完成任务回到香港后，朱标遭人杀害，阿星被疑为凶手不得不藏匿起，阿俊虽相信他是清白却也无计可施。某日阿星电话约出阿俊见面，不想一名杀手尾随而至。©豆瓣', '周星驰', '梁家仁', 6.8, 33952, 'tt0100983', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2624994568.jpg', 1.3, 9.3, 49.6, 26.7, 13.1, '0.102324,0.041951,-0.511477,0.295724,-0.100899,-0.234960,0.267158,0.124345,-0.820609,-0.426890,0.044433,0.629698,-0.027713,0.326927,0.267193,-0.256143,-0.247161,-0.536367,-0.035375,-0.204008,0.007849,-0.186116,-0.105311,-0.019809,-0.368165,-0.068113,0.414697,0.027337,-0.223653,0.460679,0.349267,0.439412,-0.517937,0.376880,-0.038215,-0.086596,0.297555,-0.019639,-0.490706,0.377583,-0.160202,-0.152402,-0.085630,0.012808,-0.150040,0.154843,0.459015,0.107542,-0.052292,-0.535645,0.070462,-0.247355,-0.166495,-0.093928,0.397464,0.268290,0.337548,0.357221,-0.124625,0.016920,0.052164,-0.123715,-0.576079,0.200687,0.057748,-0.015689,-0.311053,-0.076799,-0.260317,0.079122,-0.157878,-0.269617,0.166742,0.180844,0.532910,-0.106539,-0.175584,0.143760,-0.270186,0.279006,0.735913,0.032137,0.303215,0.020174,0.257499,-0.355335,0.446672,-0.173156,-0.110224,0.102751,0.419469,0.003003,0.084325,0.042399,-0.194185,-0.278844,-0.401072,0.011513,0.040061,-0.113002,0.025318,-0.549247,0.025261,0.039467,-0.260050,0.106618,0.010134,-0.121979,0.368855,-0.763607,0.158675,0.253953,0.152952,-0.552087,0.317443,0.074733,0.168040,-0.375649,-0.018105,0.070977,0.210111,0.074190,0.166331,-0.056218,-0.291975,-0.389430,-0.305010,-0.017603', '1293265', '35030151', '30345227', '1308655');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307463', '太阳泪', '剧情', '美国海军下属“海豹”特种突击队队长沃特斯（布鲁斯·威利斯 Bruce Willis 饰）带领一支小分队前往非洲密林执行命令：把在当地进行紧急医护工作的莱娜医生（莫妮卡·贝鲁齐 Monica Bellucci 饰）营救出来。小分队很快找到了莱娜医生，但在最后关头莱娜医生提出要把这里的70个难民一起转移的要求，否则自己也不会离开。沃特斯犯难了，非洲原始丛林天险众多，而且有剧毒莫测的野生动物，小分队人数不够，如何带着70个老弱病残逃离？然而人道主义最终打了胜仗，这支小分队在前有丛林、后有追兵的情况下带领这浩浩荡荡几十人开始了转移的道路，一个接一个的士兵倒下，生命的价值在这里人人平等。©豆瓣', '布鲁斯·威利斯', '安东尼·福奎阿', 7.3, 40055, 'tt0314353', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1130375661.jpg', 0.9, 4.4, 36.3, 43.5, 14.9, '0.377940,-0.052051,-0.617429,0.633109,-0.090373,-0.180714,0.471123,-0.043985,-0.356296,-0.075349,0.388580,0.610803,0.453456,-0.047665,0.060632,-0.129659,-0.552187,-0.258748,-0.191212,-0.163625,-0.591076,-0.439586,-0.268760,-0.297636,0.102892,-0.113363,0.583822,0.074315,-0.062681,0.599222,0.098102,0.178973,-0.042589,0.461001,-0.233840,0.056027,0.402061,-0.483327,-0.157050,0.529619,0.134408,-0.054277,-0.196829,0.025496,0.158984,0.396528,0.784393,-0.156266,0.103648,0.088602,-0.047075,-0.459729,0.149506,-0.056600,0.629612,0.016727,-0.156978,-0.055110,-0.011432,0.252187,-0.195820,0.037008,-0.663961,-0.126934,-0.082056,0.184355,-0.808092,0.063133,-0.102993,0.159726,0.201018,-0.334855,0.203621,0.588394,0.075446,-0.063843,-0.111886,-0.041630,-0.726742,-0.020020,0.700613,-0.325706,-0.099550,-0.131055,-0.222263,-0.599587,0.188477,-0.134718,-0.228117,-0.093437,0.257348,-0.184329,-0.273229,-0.339916,-0.709960,0.146657,-0.266203,-0.348444,-0.369846,-0.269403,-0.173928,-0.597164,0.311112,0.045277,-0.268589,0.363024,-0.049724,0.478562,0.931364,-0.452036,-0.112053,0.672401,0.359365,-0.359957,0.448491,-0.130832,0.238901,0.068424,0.310831,0.081455,0.137965,0.651473,0.453125,0.395082,-0.217320,-0.309861,-0.191063,-0.055074', '1302661', '2977870', '1300303', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307474', '极地恋人', '剧情', '女孩雅娜（纳瓦·尼姆利 Najwa Nimri 饰）自幼丧父，男孩奥图（费雷·马丁内兹 Fele Martínez 饰）父母之间的感情也以破裂告终，两个孤独的人相识在8岁的那一年。机缘巧合之下，雅娜的母亲和奥图的父亲组成了新的家庭，雅娜和奥图亦成为了兄妹。随着年岁的增长，两人的感情日益加深，终于越过了那条伦理的界限。奥图的母亲在孤独中割腕自杀，这带给了奥图毁灭性的打击，心碎的他远走他乡成为了一名飞行员，不久，伤心的雅娜也和他人组成了家庭。在街道上，在车流间，在天空中，两个相爱的人被命运捉弄，一次次的擦肩而过，但他们的感情却没有半分折损。数年之后，雅娜离开丈夫，来到地球的极点，她相信，在那个太阳永远不会落下的地方，她和奥图一定会再次的相遇。©豆瓣', '纳瓦·尼姆利', '胡里奥·密谭', 8.2, 13080, 'tt0133363', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p917899915.jpg', 0.4, 2, 18.6, 45.4, 33.6, '0.320180,0.052975,-1.031719,0.699664,-0.102008,-0.604992,1.062633,0.302076,-0.448283,0.011539,0.328493,1.138048,-0.130058,0.388696,0.300570,-0.058743,-0.167511,-0.758369,0.042991,-0.418328,-0.399729,-0.530081,-0.320501,-0.001933,-0.168582,-0.480155,0.781504,0.084487,0.042364,0.588799,0.243355,0.168478,-0.090604,0.548110,-0.306417,0.340360,0.085108,0.175777,-0.317173,0.076718,-0.187907,-0.097350,0.020906,-0.041074,-0.311565,0.406941,0.837276,-0.291474,0.098194,-0.165087,0.462989,-0.260442,-0.054659,0.118594,0.360091,-0.124352,0.172327,0.277204,-0.363915,-0.034359,0.050932,0.128218,-0.604447,0.071899,0.168641,0.125926,-0.800488,0.735258,0.019213,-0.463516,0.070790,-0.265235,0.195380,0.542261,0.087305,0.533756,-0.523705,-0.115249,-0.399912,-0.114708,0.921665,-0.008501,-0.555960,0.328407,-0.386841,-0.372548,-0.187402,-0.238408,-0.587015,-0.128416,0.471268,0.223491,-0.311394,0.541190,-0.652201,0.059660,-0.351672,0.020037,-0.155156,-0.557354,-0.032800,-0.581168,-0.211265,-0.884388,-0.567163,0.183011,-0.196722,-0.179143,0.676259,-0.834608,0.374229,0.329549,0.550543,-0.186977,0.733014,0.292774,0.277257,-0.076053,-0.017219,0.636320,-0.228399,0.130605,0.128507,0.337780,0.068065,0.384116,-0.272570,0.632773', '3111650', '30162520', '25723780', '3014557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307488', '三更', '爱情', '该片由香港、韩国与泰国三位导演陈可辛、金知云与Nonzee Nimibutr的三部短片《回家》、《失忆》与《轮回》组成。《回家》讲于辉（黎明）鉴于以往经验，深信用中药泡澡能令自己死亡三年的妻子（原丽淇）复活，但因行为诡异致使警察邻居（曾志伟）警觉，引发悲剧。《失忆》讲妻子（金慧秀）死后的灵魂回忆其被丈夫（郑普硕）杀害的过程。《轮回》则是借泰国两种截然不同的传统艺术，通过街头艺人哥东（舒伟烈）的一系列离奇遭遇，讲述了“不是不报，时候未到”的因果报应。©豆瓣', '黎明', '金知云', 7.4, 31306, 'tt0324242', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165832992.jpg', 0.8, 3.7, 36.1, 44.1, 15.3, '0.289224,-0.135727,-0.223855,0.358778,0.018105,0.069355,0.509402,-0.028019,-0.551177,-0.523351,0.065643,0.640506,-0.067230,0.072885,0.115009,-0.195167,-0.059029,-0.518894,-0.115930,0.222991,-0.133438,-0.446963,-0.167386,-0.054859,-0.226543,-0.283689,0.494477,0.012728,-0.298433,0.369364,0.179264,0.509984,-0.358798,0.002600,-0.011029,0.234190,-0.056173,0.225613,-0.523399,0.105825,0.082529,-0.364785,0.122845,0.022085,-0.219886,0.314065,0.505018,0.015183,-0.441634,-0.310028,0.822123,-0.230131,-0.308663,0.015580,0.292796,0.388076,0.493741,0.550799,-0.017278,-0.003856,-0.271877,0.068709,-0.713041,0.007898,0.185287,-0.062203,-0.258553,0.238415,-0.035743,0.001689,0.029764,-0.043406,0.214444,0.288778,0.582835,0.526790,-0.000779,-0.410538,-0.206797,0.370821,0.790822,-0.161144,-0.236582,0.416998,-0.219132,-0.301882,0.033233,-0.294344,-0.245023,0.582353,-0.034351,0.128380,-0.203304,0.417662,-0.511090,-0.061621,-0.086803,-0.014509,-0.112280,0.040305,0.032938,-0.757574,-0.255283,-0.248226,-0.220096,-0.340498,0.242363,-0.324877,0.536714,-0.513592,0.372003,0.404788,0.308843,-0.787936,0.471983,0.227343,0.192370,-0.513029,0.252002,0.345045,0.029393,-0.094296,0.024052,-0.034463,-0.060780,0.175344,-0.416505,0.232772', '26678784', '25918677', '4301278', '25921830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307490', '秘书', '剧情', 'Lee Holloway（玛吉·吉伦哈尔 Maggie Gyllenhaal 饰）生活在一个不和谐的家庭里，从小就有“自毁”的行为，在精神治疗中心治疗一段时间回到家后，她要重新融入正常人的生活。于是她学习了打字，在一家律师事务所找到了一份打字员的工作。一开始，Lee打字出现了很多毛病，被她的雇主E. Edward Grey（詹姆斯·斯派德 James Spader 饰）发现，Grey把Lee叫到了他的办公室，为了让Lee深刻记得她的错误，他让Lee趴在书桌上，然后他开始拿起皮鞭对她进行性虐待。久而久之，两人产生了一种奇妙的情感，这也从另一方面减弱了Lee的“自毁”倾向。Lee爱上了Grey，然而Grey却羞于让人知道他的怪癖，于是他解雇了Lee。Lee的男友Peter（杰瑞米·戴维斯 Jeremy Davies 饰）向她求婚，她答应了，然而在婚礼当天，她却逃到了Grey的办公室.....', '詹姆斯·斯派德', '史蒂芬·西恩博格', 7.1, 34197, 'tt0274812', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p795564201.jpg', 1.6, 7.2, 40.9, 36.6, 13.7, '0.552696,0.326445,-0.879798,0.660836,-0.481205,-0.330437,0.852259,0.365030,-0.456325,-0.045559,0.191494,0.960046,-0.239632,0.232237,0.324923,0.197332,-0.207443,-0.757845,0.183975,-0.087267,-0.499490,-0.510407,-0.036636,-0.399302,-0.090179,-0.419816,0.196387,-0.053415,-0.230923,0.272964,0.056744,0.160248,0.420837,0.768568,-0.082188,0.265396,-0.103838,-0.059369,0.093433,0.211063,0.569210,-0.529468,-0.125342,0.514359,-0.026719,0.526267,0.793653,-0.057070,-0.405721,0.061348,0.557026,-0.260678,-0.204719,0.155198,0.089938,0.039148,-0.225872,0.150045,-0.457072,0.155586,0.037605,0.098403,-0.586984,-0.126444,-0.204562,0.175615,-0.753523,0.599300,-0.346256,-0.020153,-0.032672,-0.524185,-0.011482,0.397365,0.044029,0.300193,-0.181225,0.040375,-0.626540,0.263885,0.671129,-0.139432,-0.228857,0.618789,-0.297676,-0.388372,-0.217039,-0.013661,-0.545937,-0.415294,0.530135,0.059716,-0.449238,-0.140771,-0.710914,-0.107482,-0.171370,-0.391996,-0.122952,-0.572709,-0.118146,-0.325701,-0.279316,-0.214468,-0.447797,0.007896,-0.203793,-0.333495,0.726935,-1.001992,0.175937,0.784840,0.283406,-0.562020,0.627130,0.035040,-0.019693,-0.143976,0.176080,0.148366,0.074092,0.651414,0.423999,0.575582,0.114969,0.006370,-0.643535,0.675478', '10576419', '21360412', '1866424', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307493', '失控陪审团', '剧情', '一名证券经纪人在儿子生日那天因枪击事件死在公司。两年后，死者遗孀控告枪支制造商维克斯堡，索取巨额赔偿，拥有三十多年从业经验的代理律师洛尔（达斯汀·霍夫曼 Dustin Hoffman 饰）宁肯凭借个人经验选择陪审团成员，但还是接受与陪审团筛选顾问劳伦斯合作，因为此类控告枪支公司的案例胜少败多。另一方面，枪支公司聘请著名陪审团筛选顾问蓝金（Gene Hackman 饰），全面调查陪审团成员背景，以期掌控陪审团。青年尼克（John Cusack 饰）入选陪审团，但他的目的一开始看来就不单纯，尼克运用多种手段，在陪审团内部和蓝金的力量展开争夺，尼克的搭档玛丽（Rachel Weisz 饰）同时向洛尔与蓝金发出信号，承诺他们出钱就可以控制陪审团。蓝金在和尼克的争夺中焦头烂额之际，他的部下发现了尼克真正的意图……©豆瓣', '约翰·库萨克', '加里·弗莱德', 8, 18686, 'tt0313542', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2550984699.jpg', 0.3, 1.2, 19.6, 55.6, 23.3, '0.110467,0.028453,-0.416327,0.349620,-0.098994,-0.232125,0.436902,0.011438,-0.449273,-0.304931,0.435278,0.612673,0.104530,-0.017109,0.431946,-0.200248,-0.374216,-0.592497,0.052464,-0.074723,-0.130509,-0.970087,-0.098319,-0.402222,-0.047219,-0.472362,0.826935,-0.199721,-0.175112,0.262483,0.194910,0.287181,-0.061838,0.172667,0.353462,-0.364478,0.642411,-0.182479,-0.585324,0.264054,-0.101429,-0.284844,-0.152791,0.064152,0.280938,0.447919,0.359437,-0.173137,-0.046659,-0.254269,0.275045,-0.227286,0.071249,0.174044,0.341157,0.158808,0.323341,0.684998,-0.205289,-0.169991,-0.028254,0.071460,-0.828930,-0.291521,0.155502,0.139925,-0.573247,0.259257,-0.424647,0.214924,-0.094698,-0.128981,-0.096051,0.360566,0.126315,0.091208,-0.110609,-0.073543,-0.527648,0.220239,0.432083,-0.249550,-0.115195,-0.160253,-0.138632,-0.548077,-0.320257,-0.151702,-0.095041,-0.186066,0.243399,-0.061033,0.132094,0.250652,-0.529967,-0.062134,-0.188208,-0.335936,0.117769,-0.202028,0.196137,-0.835749,-0.152089,0.004002,-0.354469,-0.082137,0.207286,-0.350083,0.611630,-0.696548,-0.156697,0.500819,0.502859,-0.390944,0.564650,0.063283,0.251518,-0.511974,-0.205974,-0.141970,0.435829,0.095240,0.140867,0.089036,0.478315,-0.423175,0.129297,0.106028', '3006781', '1305096', '1293989', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307507', '黄飞鸿之五：龙城歼霸', '动作', '八国联军入京，朝廷出奔，举国局势一度混乱。黄飞鸿（赵文卓 饰）与父亲黄麒英（刘询 饰）、十四姨（王静莹 饰）、徒弟梁宽（莫少聪 饰）、鬼脚七（熊欣欣 饰）一行人南下番禹，欲与十三姨（关之琳 饰）、猪肉荣（郑则仕 饰）、牙擦苏（郭晋安 饰）汇合。师徒于路同担心海盗夺粮的南粤米仓发生误会，两帮人不打不相识，黄飞鸿助其将盗米贼扭送衙门，惊觉盗米竟是差役领班谢四（张铁林 饰）指使。原来南海海盗趁局势混乱，活动频繁，使番禹一地早无官员统制，差役不得已靠偷盗维持口粮。黄飞鸿有感谢四等人忠义，遂放弃赴港计划，与当地海盗单眼英、张玉麟、张保仔等人展开连场搏杀……本片是徐克执导黄飞鸿系列的第五部。©豆瓣', '赵文卓', '徐克', 6.8, 15052, 'tt0110073', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2208250362.jpg', 0.8, 6.1, 54.5, 29.2, 9.4, '-0.076985,-0.346873,-0.404213,0.196835,0.539445,0.123808,0.212347,0.404589,-0.551480,-0.183774,0.196303,0.231504,-0.168475,-0.313069,0.238318,-0.244429,-0.300993,-0.510895,-0.095806,0.072361,0.152252,-0.244876,-0.125407,-0.358359,-0.317876,-0.070104,0.218065,0.250868,-0.153237,0.520367,0.386460,0.112461,-0.537195,0.185003,0.208933,0.223338,-0.028798,-0.183378,-0.477647,-0.340546,-0.510408,-0.481416,-0.274961,-0.167726,0.321063,0.382181,0.724688,-0.249535,0.088494,-0.268923,-0.061659,-0.154148,-0.173737,-0.174241,0.193140,0.029562,0.018244,0.171721,0.081979,0.129236,0.041878,-0.145737,-0.108614,0.352014,0.307438,-0.174386,-0.256588,0.318175,-0.277862,0.135909,-0.049460,-0.177365,0.099904,0.422983,0.290974,-0.252507,0.213504,-0.081853,-0.250698,0.590859,0.393303,-0.044689,0.292948,-0.250979,0.360654,-0.535323,-0.039820,-0.165130,-0.068661,0.099950,0.312222,-0.371896,0.067548,0.089028,-0.219850,-0.350678,-0.377994,0.190200,0.007431,0.272968,0.165458,-0.542031,0.077735,-0.272108,0.004934,0.057779,0.309826,0.126785,0.124364,-0.243672,-0.069367,0.107018,0.223575,-0.642812,0.239733,-0.083424,0.025931,-0.362169,-0.139846,-0.160160,0.272607,-0.111380,0.347541,0.010228,-0.385301,-0.112027,0.069950,-0.420559', '3626416', '26826398', '4082544', '1292846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307508', '指环王', '剧情', '这部影片改编自一部全球知名的小说《指环王》（The Lord of the Rings）。它出自名作家J.R.R. Tolkien之手，由三个各自独立而又相互关联的故事组成。这部小说至少已有1亿5百万人通读过，而浏览过的更是不计其数，可以说它是近100年来少有的一部经典巨作。近几十年来，这一故事曾多次被搬上银幕但均未获得较大的成功，只有1979年拍摄的动画版才获得了一点点好评。这部片子作为70年代的动画大作，画质算是比较不错了。其风格与迪斯尼自是大不相同，似乎有点中国水墨的影子。网上影评协会(OFCS)影史百部动画佳片之90', 'Christopher Guard', '拉尔夫·巴克希', 8.8, 6590, 'tt0077869', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2642856162.jpg', 0.3, 0.8, 10.8, 36.2, 51.9, '0.158367,-0.147045,-0.550919,0.806490,0.700846,0.076944,0.477230,-0.260647,-0.542851,-0.200732,-0.024478,0.784339,-0.443051,-0.040349,-0.149020,-0.288975,-0.155000,-0.324307,-0.327999,-0.662100,0.028508,-0.098284,-0.821622,0.205065,-0.528298,-0.171707,0.959241,0.126661,-0.496163,0.199040,0.286152,0.087251,-0.097267,0.030907,-0.241166,0.207942,-0.109314,0.044155,-0.232699,0.437566,-0.078790,-0.134499,-0.353625,-0.143662,-0.315624,0.256955,0.701677,-0.164424,-0.330097,0.364715,0.775506,0.046408,-0.378482,-0.349162,0.219267,0.477054,0.812579,0.249986,-0.075053,0.304625,-0.349764,-0.376856,-1.084426,-0.047558,0.285379,0.161780,-0.374087,0.354165,-0.205945,-0.145527,-0.201174,-0.241752,0.041940,0.034515,0.627398,0.303330,0.155748,-0.072286,-0.472239,0.831937,0.265640,0.198617,-0.608115,0.696033,-0.099294,-0.575116,-0.254770,-0.562999,-0.280512,0.445338,0.402661,-0.127396,0.239789,-0.008015,-0.739694,0.208425,-0.093481,-0.561808,0.167223,-0.258529,0.224280,-0.909072,-0.437978,-0.425585,0.035287,-0.356489,0.420224,-0.583218,1.295807,-0.518955,0.160818,0.189977,-0.070710,-0.428103,0.705887,0.010787,-0.172852,0.198058,0.073053,0.157410,-0.030094,0.172687,0.181987,0.164974,0.319716,-0.737890,-0.496139,0.664219', '27602116', '22265121', '3318306', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307514', '征婚启事', '剧情', '男友的多日失踪打破了台北某所大医院的眼科医生杜家珍（刘若英）以往的平静生活，为走出心情的低谷，她心血来潮在报纸的分类广告栏刊登了一则征婚启事，期望通过另一段新的恋情安慰自己。启事一出，招来众多远远超出杜家珍的过往生活经验所能想象的奇形怪状各怀目的的应征者（王朝明、纽承泽等），但在同他们一一面谈之后，杜家珍发现这些人要的只是各种各样的“欲”，而自己面对他们时的喟叹，更多是对过往情伤的不甘心。当杜家珍决定为曾经的爱情做最后一次挽救的努力时，却得到对她来说十分意外或是最后一丝希望破灭或是解脱的消息。©豆瓣', '刘若英', '陈国富', 7.8, 19547, 'tt0212423', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2873896881.jpg', 0.3, 1.9, 24.7, 52.8, 20.2, '0.225180,0.252681,-0.608126,0.629036,0.238277,-0.217708,0.686296,-0.045508,-0.646129,-0.366964,-0.257479,0.676787,-0.245550,0.488765,-0.038092,-0.274221,-0.258855,-0.592609,0.025032,-0.376508,-0.245246,-0.317852,-0.107355,-0.245951,-0.255707,-0.125334,0.730264,0.440765,-0.304827,0.274803,0.323393,0.448343,-0.106646,0.533702,-0.188447,-0.031503,-0.074824,0.411573,-0.485827,-0.022819,0.218239,-0.165337,-0.449843,0.518264,-0.072607,0.318879,0.699890,-0.154880,-0.508588,0.077370,0.426259,-0.211849,0.057590,0.036893,0.099531,0.153375,0.073228,0.337416,-0.213930,-0.006718,-0.146636,0.046550,-1.027714,-0.109638,0.127770,0.149941,-0.478173,0.435020,-0.021959,0.268886,0.031984,-0.100679,0.382197,0.586862,0.167567,0.313405,-0.448990,-0.061682,-0.497802,0.231852,0.826018,0.118397,-0.059634,0.652685,-0.530072,-0.224446,0.093689,-0.171561,-0.458870,0.154718,0.090766,0.328688,-0.261479,0.225597,-0.328510,-0.062357,-0.425909,-0.057993,0.186068,-0.679934,-0.179700,-0.704480,-0.132892,-0.332535,-0.348305,-0.012736,0.157686,-0.468887,0.928367,-0.732829,-0.010139,0.162991,0.165442,-0.761933,0.636880,0.064485,0.039148,-0.210043,-0.002839,0.210282,-0.048858,0.104280,-0.144551,-0.041496,-0.003705,-0.278060,-0.441697,0.534046', '26678784', '30163500', '4301278', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307527', '黑夜传说', '动作', '地球上一直存在着一个黑暗的地下世界。那里，两大种族――吸血鬼和狼人――在斗得你死我活，每一方都以消灭对方种族为最终目标。一次，吸血鬼族的“月神”西丽妮（凯特•贝金赛尔 Kate Beckinsale 饰）在追杀几个落败的狼人时发现，狼人正在密谋绑架人类的一名医生麦克尔 （斯科特•斯比德曼 Scott Speedman 饰）。心知狼人必有所图，西丽妮独自前往狼窝查探。不料中了狼人的埋伏，身负重伤之际幸得麦克尔相救。在麦克尔送西丽妮回吸血鬼营地的途中，他意外被一只狼人咬伤了，由此揭开了麦克尔的身世之谜和狼人的阴谋……©豆瓣', '凯特·贝金赛尔', '伦·怀斯曼', 7.5, 93153, 'tt0320691', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1671355869.jpg', 0.5, 3.6, 32.7, 47, 16.2, '0.210225,0.073666,-0.586162,0.395815,0.135777,-0.083005,0.695695,-0.011764,-0.492429,-0.298280,0.407289,0.645841,0.022557,-0.103525,0.334921,-0.159478,-0.251252,-0.362814,0.075981,-0.284260,-0.548313,-0.023514,-0.626033,-0.449545,0.120543,-0.418303,0.330728,0.073498,-0.020361,0.394870,-0.004555,0.438960,-0.625498,0.171030,0.053248,0.172086,0.150821,-0.248178,-0.074285,0.252661,-0.444275,0.157384,-0.421616,0.144178,-0.434579,0.318203,0.732538,-0.832517,0.180135,-0.662437,-0.115916,-0.485001,0.159955,0.066397,0.748293,-0.531189,0.272336,0.212924,0.291949,-0.235111,0.249161,0.198628,-0.757406,0.001105,-0.137139,0.468409,-0.473976,0.391528,-0.023111,0.364703,0.055970,-0.202373,-0.083624,0.447828,0.245961,0.198647,0.279131,-0.184377,-0.729422,-0.238537,0.698706,-0.033049,-0.052759,-0.108913,0.164696,-0.511522,-0.252874,-0.225760,-0.304083,-0.183620,0.689686,-0.014988,-0.533735,0.387480,-0.701205,0.067791,-0.558040,0.037818,-0.258412,-0.355864,-0.060468,-0.678699,-0.015940,-0.074795,-0.156188,0.277063,0.096088,-0.016615,0.414333,-0.732768,0.355673,0.673595,0.295608,-0.169782,0.697448,-0.219058,-0.003712,-0.203688,-0.177971,0.310142,0.583935,0.158310,0.230084,0.217985,-0.198287,0.057588,-0.299256,0.276777', '7056398', '10756744', '3990098', '1305071');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307535', '奔腾年代', '剧情', '大萧条时期，每个人都要守住一个梦想，以此来度过最黑暗的时光，生活失意的汽车制造商查尔斯•霍华德（杰夫•布里吉斯 Jeff Bridges 饰）也不例外。他买了一匹小个子赛马，名为“海饼干”，并笼络了一批同样有梦想的人，意图进入赛马圈。第一个发现海饼干天赋的是训练师 汤姆•史密斯（克里斯•库珀 Chris Cooper 饰），他认为这匹马虽然个头矮小，腿脚也不太灵光，天性中却藏着十足的执拗和倔强，这有可能使其成为赛马圈的王者。他们找来前拳击冠军瑞德•波拉德（托比•马奎尔 Tobey Maguire饰）作为海饼干的骑师，三个人一匹马在共同的征程中重新找到了生活的方向。©豆瓣', '托比·马奎尔', '盖瑞·罗斯', 8.4, 35474, 'tt0329575', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p845519371.jpg', 0.2, 1, 14.1, 48.4, 36.4, '0.044069,0.041883,-0.466165,0.667075,-0.045636,-0.342430,0.646961,0.036778,-0.343265,-0.435618,0.176411,0.621703,0.430789,-0.159929,0.117095,-0.027237,-0.307104,-0.233113,0.079619,-0.111148,-0.376325,-0.152705,-0.231033,-0.160616,-0.001142,-0.189466,0.564444,-0.045288,-0.152843,0.452898,0.435643,0.327225,0.240824,0.229329,-0.265223,0.074829,0.204046,-0.072703,-0.018859,0.215439,-0.393343,0.112759,-0.307551,-0.012148,0.238102,0.131070,0.561690,-0.209871,0.121336,-0.069319,-0.147512,-0.184184,-0.167286,-0.267712,0.175178,-0.126345,0.127820,-0.045498,-0.024850,0.318197,0.081040,-0.146549,-0.733553,-0.026116,0.053532,0.205765,-0.564555,0.320608,0.042169,-0.199358,-0.120109,-0.195804,-0.015734,0.041831,0.156019,0.073844,0.147688,0.127309,-0.645252,-0.018847,0.582367,-0.007149,-0.348823,0.093437,-0.479226,-0.540356,-0.082470,-0.252172,-0.400604,-0.181969,0.467681,0.100759,-0.082898,0.173321,-0.736033,0.367948,-0.148665,-0.170131,0.142330,-0.265986,0.048811,-0.479806,0.303139,-0.423744,-0.229327,-0.111228,-0.046081,-0.226790,0.671970,-0.597419,0.158938,0.487722,-0.001240,-0.227175,0.687136,0.074907,0.200880,-0.374510,-0.102755,0.382446,0.057152,0.077552,-0.079721,0.440297,-0.117579,-0.156612,-0.331597,0.840754', '3055049', '1870681', '1303542', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307542', '火柴人', '剧情', '罗伊（尼古拉斯·凯奇 Nicolas Cage饰）是一个手段高超的职业骗子，他有一个大胆且贪心的伙伴法兰克(萨姆·罗克韦尔 Sam Rockwell饰)，他们一起搭档了很多年，几乎没有失过手。同时，罗伊亦是一个精神强迫症患者。他爱干净，不允许别人穿着鞋走进他家；他谨慎，每次出门都要三番五次检查煤气和电源开关。法兰克为此帮他找了一位心理医生。在心理医生的帮助下，罗伊找到了他失散多年的女儿安吉拉(艾莉森·洛曼 Alison Lohman饰)。女儿的出现改变了他的生活，让他慢慢感到了做父亲的乐趣。但他并不想让女儿知道他的职业。但是纸毕竟包不住火，女儿知道了他的秘密，并展现出极其出色的欺骗才能，罗伊决定将他一身的本领都传给女儿。很快，一庄“大买卖”来了，父女、伙伴齐上阵，结果将如何呢？©豆瓣', '尼古拉斯·凯奇', '雷德利·斯科特', 8.2, 141430, 'tt0325805', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1757301336.jpg', 0.1, 0.8, 16, 55, 28.1, '0.277339,-0.036072,-0.559266,0.702439,-0.653772,-0.403872,0.436946,0.091860,-0.601963,-0.399340,0.151939,0.940812,0.199223,0.115986,-0.116792,0.166336,-0.092459,-0.682530,0.233436,-0.054742,-0.394343,-0.475434,-0.294361,-0.361075,-0.083665,-0.221612,0.214620,-0.237522,0.099230,0.118361,0.491501,0.007121,0.294952,0.515950,-0.124417,0.055528,-0.009033,-0.072062,-0.025076,0.264119,0.190351,-0.080158,-0.026960,0.491315,0.043779,0.371976,0.535023,-0.057798,-0.197923,-0.110538,0.405489,0.012951,0.193514,0.268200,0.073545,-0.058593,-0.000089,0.128327,0.006709,-0.063754,0.240403,0.168095,-0.842775,0.046765,0.131090,-0.005335,-0.949264,0.378450,-0.340859,-0.103825,-0.134110,-0.414447,0.036071,0.214489,0.362355,0.265488,-0.213848,-0.095781,-0.481701,0.240965,0.617418,0.079256,0.021091,0.374466,-0.553375,-0.347973,0.063385,-0.393425,-0.526313,-0.014804,0.397858,-0.016562,-0.288350,0.028093,-0.303440,-0.073791,-0.236114,-0.022282,-0.100202,-0.465496,0.283735,-0.192409,-0.091304,-0.385729,-0.438997,-0.011084,-0.082830,-0.346586,0.749407,-0.732840,0.022914,0.651798,0.290764,-0.692929,0.671609,0.104296,0.047868,-0.156608,-0.023018,0.067558,0.172940,0.177698,0.447689,0.433909,0.234713,-0.023525,-0.203918,0.330055', '1877596', '1309069', '30163500', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307545', '向左爱·向右爱', '剧情', '一封封的匿名信，勾起了志焕（车太贤 饰）对昔日两位好友的思念。五年前志焕在咖啡店做兼职，一天他忙里偷闲在拍照，秀仁（孙艺珍 饰）和景喜（李恩珠 饰）走进他的镜头，也从此走进了他的生活。因为他对秀仁一见钟情了，可是当志焕向秀仁表白时却遭到了秀仁婉转拒绝了。但志焕没有放弃，他再一次在大庭广众之下恳求秀仁给他一次机会。秀仁跟景喜都喜欢志焕率直的性格，此后三人常常走在一起，建立起了友谊，三人都十分珍惜他们之间的友情。可是当他们同时感觉到了彼此之间模模糊糊的爱意时，秀仁跟景喜向志焕表示了三人行的尴尬，因此两名女孩便离开了志焕。时过境迁，志焕仍无法面对她们的离开。而匿名信的出现，也让他有了寻找秀仁与景喜的冲动，就在这时，他知道了一个鲜为人知的秘密……©豆瓣', '车太贤', '李翰', 7.6, 22407, 'tt0328675', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2166630611.jpg', 0.4, 2.7, 33.8, 43.2, 19.9, '0.372915,0.001111,-0.919656,0.722763,-0.171639,-0.333656,0.852910,0.182098,-0.421340,-0.042719,0.089031,0.847279,-0.227250,0.346133,0.148357,-0.114521,-0.120859,-0.783543,0.069565,-0.378554,-0.135155,-0.405910,-0.144819,-0.212648,-0.217923,-0.167374,0.358065,0.013484,-0.276938,0.551116,0.374460,-0.006697,-0.123607,0.856030,-0.177615,0.097379,0.039393,0.339890,-0.255182,0.227108,0.255336,-0.614738,-0.381493,0.232649,-0.058211,0.401925,0.624003,-0.248813,-0.340360,0.318974,0.115538,-0.212845,-0.112344,0.282263,0.097931,-0.044635,0.137703,0.319076,-0.412176,0.044443,0.078976,0.100891,-0.552684,0.134231,-0.245517,0.194682,-0.728216,0.731925,-0.183988,-0.274209,0.189767,-0.459687,0.195648,0.350366,0.320478,0.155634,-0.467827,-0.029622,-0.511441,0.133559,0.813267,0.204720,0.006093,0.604007,-0.226550,-0.471127,-0.159404,0.002581,-0.467682,-0.063706,0.412392,0.183957,-0.339360,-0.024891,-0.572061,-0.086816,-0.120965,-0.065581,-0.082685,-0.728275,-0.007458,-0.518961,-0.280898,-0.512561,-0.575795,0.330420,0.041833,-0.201042,0.716146,-0.837939,0.221990,0.397677,0.515792,-0.643772,0.914582,0.289617,-0.137268,-0.076206,0.177881,0.148285,0.024118,0.290628,0.442082,0.468398,-0.054413,0.099923,-0.437720,0.410852', '1302384', '2990737', '1301022', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307547', '星际宝贝', '喜剧', '5岁的女孩丽洛一直梦想养一只宠物狗，这天她终于得偿所愿，在姐姐的帮助下收养了一只流浪小狗，并帮他取名史迪。其实史迪并不是什么流浪狗，他是外太空的危险分子，长有六条腿，在流放中偷跑到了地球。为了隐瞒身份，史迪一直将他的另外两只脚藏起来，外表和其他的小狗一样。在朝夕相处中，史迪和丽洛慢慢建立了深厚的感情。然而此时，追捕史迪的外星人发现了史迪藏身地球，为了逼他就范，他们绑架了丽洛。为了救回好朋友，史迪决定尽力一拼！©豆瓣', '黛维·切斯', '克里斯·桑德斯', 8.5, 62384, 'tt0275847', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510798502.jpg', 0.2, 0.9, 14.3, 43.2, 41.4, '0.117920,-0.118714,-0.679819,0.450156,-0.441367,-0.066991,0.604079,-0.078887,-0.440055,-0.243868,0.164963,0.759965,0.073682,0.478420,-0.112679,0.215616,-0.049483,-0.454365,0.109688,-0.194361,-0.285396,-0.364993,-0.372030,-0.125481,-0.174282,0.062920,0.645167,-0.124271,-0.097584,0.469041,0.202382,-0.089902,-0.195956,0.189120,-0.420251,-0.054360,-0.351403,0.039149,-0.045075,0.168520,-0.160645,0.087169,0.213481,0.218511,0.106337,0.382909,0.519373,-0.534672,-0.142602,-0.307778,0.199421,-0.414967,0.135190,0.016328,0.474485,-0.195236,0.181909,0.079277,-0.110555,-0.001428,0.185086,-0.263997,-0.700547,-0.261251,-0.044676,0.218784,-0.678021,0.394421,0.058519,0.036804,0.270584,-0.339853,-0.038465,0.381425,-0.036799,0.265369,-0.286535,0.309566,-0.589478,-0.049706,0.603692,-0.247641,0.097227,0.393302,-0.208707,-0.278472,0.197665,-0.150305,-0.113623,-0.355680,0.258005,0.139119,-0.750814,0.236267,-0.400338,-0.149641,-0.124132,0.252144,-0.152554,-0.667070,0.184657,-0.038038,-0.033971,-0.288888,-0.019431,0.133962,0.045125,-0.546667,0.503087,-0.804078,0.463688,0.812757,0.554836,-0.416199,0.530769,0.006467,0.174154,-0.156085,0.040274,0.497506,0.279292,0.295352,0.239514,0.074154,0.166696,-0.045240,-0.566626,0.396425', '1949005', '3755531', '1866424', '1296698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307561', '青少年哪吒', '剧情', '拿着退来的补习费用逃离压抑的补习班后，小康（李康生）开始漫无目的的在西门町晃荡，偶遇有着另一种身份过着另一种日子的“不良少年”阿泽（陈昭荣），被其吸引，渴望融入其生活。但阿泽只是表面看来光鲜，打电动、开一辆重型机车在街上呼啸只因可以暂时让自己看起来像个胜利者，内心却一样是封闭孤独的。在跟踪阿泽的过程中，小康渐发觉自己的性向可能与大多数人有别，也发现阿泽生活的单调与苦闷。但好过小康的是，阿泽虽也几乎不知何为亲情，却有“好兄弟”阿彬（任长彬）常陪左右，有阿桂（王渝文）暂当女友，来过“当天和尚撞天钟”的生活。©豆瓣', '李康生', '蔡明亮', 8, 23998, 'tt0103935', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194480884.jpg', 0.3, 1.3, 19.5, 54.4, 24.5, '0.274109,-0.075129,-0.528363,0.410118,-0.094647,-0.032778,1.029103,0.151973,-0.561359,-0.175295,0.145858,0.476921,-0.072742,0.334677,0.137095,0.031886,-0.136891,-0.370566,0.027232,-0.025692,-0.095500,-0.285212,-0.248676,-0.109474,-0.288206,-0.189252,0.496164,-0.032599,-0.146824,0.560051,0.150586,0.107573,-0.245050,0.693262,-0.451048,-0.109062,-0.306122,0.185629,-0.079497,-0.070971,0.073701,-0.226800,-0.123631,-0.096218,0.019977,0.402642,0.639699,-0.005380,-0.268058,0.206301,0.217662,0.093682,-0.173451,-0.029724,0.140161,0.225643,0.006787,-0.035884,0.037042,0.279898,-0.019457,0.084648,-0.435826,0.014324,0.092351,0.030565,-0.588462,0.749432,0.133991,-0.335637,-0.075416,-0.414387,0.243339,0.059143,0.049630,0.464422,-0.246358,0.194184,-0.577744,0.119067,0.826894,0.050867,-0.413462,0.496678,-0.533931,-0.305732,0.001246,-0.173756,-0.571312,-0.290196,0.095126,0.204674,-0.362213,0.035548,-0.516311,0.325462,0.035848,0.025452,-0.112237,-0.547085,-0.106467,-0.318392,-0.061756,-0.759189,-0.402802,0.073484,0.076986,-0.308124,0.521101,-0.897719,0.232071,0.519466,0.160137,-0.251064,0.654193,0.215624,-0.060252,-0.029297,-0.174621,0.283944,-0.109806,0.358407,0.072982,0.373449,-0.169719,0.017222,-0.508658,0.541265', '1308755', '1304989', '1296370', '1861411');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307577', '唐山大兄', '动作', '因家乡年景不好，青年郑潮安（李小龙 饰）跟随三叔远赴泰国，郑在当地华工许剑（田俊 饰）的帮助下，得到了一份冰厂的工作。许剑为人仗义好打抱不平，时常卷入争斗，郑潮安虽也学得一身功夫，但碍于母亲的劝诫不能出手。华工们工作的这家冰厂为牟取利益，在冰中藏匿毒品贩运，不久，两名华工因为偶然拾到了冰中的毒品，被厂长和老板杀害，许剑向老板要人，反被对方派众打手于家中残忍杀害。工友们寻找失踪的华工和许剑无获，于是罢工抗议，厂长和监工们痛打工人，郑潮安仗义出手，厂长畏惧升其为领导，众工人称呼郑为“唐山大兄”。老板方面见笼络郑潮安不成，杀害了所有华工，郑潮安冲到老板家中，欲令其血债血偿……©豆瓣', '李小龙', '罗维', 7.8, 22394, 'tt0067824', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2338774082.jpg', 0.6, 2.7, 27, 45.7, 24, '0.261214,-0.399008,-0.327257,0.260758,-0.323548,-0.308864,0.411600,0.264567,-0.565941,-0.524060,0.042486,0.384332,0.172078,0.360887,0.108135,-0.228601,-0.016071,-0.313425,-0.231552,0.211283,0.122407,-0.249169,-0.001244,-0.466776,-0.481714,0.120252,0.033391,0.120030,-0.175582,0.503553,0.292642,0.375360,-0.024568,0.426767,-0.065918,0.176377,0.063599,-0.144643,-0.269073,-0.071402,0.058780,-0.510444,-0.150627,-0.040172,0.292664,0.592953,0.466128,0.390295,-0.135878,-0.271215,0.213203,-0.256127,0.284941,0.112274,0.509227,0.028700,0.199775,0.123079,-0.267055,-0.083853,0.159721,0.025162,-0.388015,0.033065,0.309212,-0.159608,-0.781668,0.067633,-0.081065,0.168523,-0.224359,-0.289348,0.205819,0.292161,0.068222,0.205854,0.100010,-0.037569,-0.491625,0.562722,0.851020,-0.125462,0.188893,-0.428378,0.043318,-0.432417,0.249460,-0.202968,-0.128206,-0.124290,0.327084,-0.252717,0.176941,-0.090995,-0.504486,-0.313730,-0.116967,-0.050500,0.098562,-0.077765,-0.001049,-0.611780,-0.005002,-0.435448,-0.218817,0.044230,0.239962,-0.047785,0.653817,-0.483861,-0.101550,0.208165,0.354072,-0.941461,0.616193,0.110913,0.316669,-0.077332,-0.070525,-0.371624,0.459614,0.424521,0.353409,0.055084,-0.157445,-0.188507,0.282035,-0.180271', '1308035', '26646649', '1421278', '1305201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307582', '最佳拍档2：大显神通', '喜剧', '金刚（许冠杰 饰）成功降服白手袜之后，白手袜之兄黑手袜受黑手党指派继续交易钻石并向金刚复仇，金刚与黑手袜的高级机器人大战数合终于侥幸胜利，却马上又落入了牛牛、悠悠兄妹犯罪团伙的骗局，卷入银行抢劫案成为嫌犯，金刚逃亡路上将拍档光头神探（麦嘉 饰）与何东诗（张艾嘉 饰）的婚礼搅得一塌糊涂。所幸光头神探义字当先合力与金刚对抗牛牛、黑手袜，却不料金刚再次被悠悠戏弄，光头神探也只落得被严妻整治。最佳拍档被牛牛团伙胁迫，不得不出面抢夺钻石，而黑手袜方面再次出动高级机器人应战，早有准备的金刚取出机器人特工队，混战一触即发……本片是最佳拍档系列的第二集。©豆瓣', '许冠杰', '曾志伟', 7.6, 15214, 'tt0086646', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1995061184.jpg', 0.5, 2.7, 32.1, 46.8, 18, '-0.154616,-0.138261,-0.360028,0.056861,0.118887,-0.210627,0.161405,0.390246,-0.029427,0.017185,0.630950,0.349082,-0.210985,-0.384594,-0.055654,-0.284418,-0.126653,-0.673597,-0.092168,0.341643,0.002140,-0.031178,-0.304208,0.163715,0.169869,-0.281737,0.540000,0.027955,-0.328074,0.441544,0.813109,0.366452,-0.336952,0.206638,-0.040668,-0.022160,0.174674,-0.185288,-0.276629,0.364532,-0.327840,-0.102580,0.062301,0.044136,-0.152815,0.233689,0.574750,-0.590815,0.065356,-0.377813,0.139050,-0.401819,-0.404747,0.081064,0.528218,0.018985,0.239350,0.009082,0.167431,0.183182,0.390801,-0.202144,-0.763589,0.011085,0.135165,-0.176206,-0.554892,-0.008421,-0.158235,0.329033,0.101339,0.052214,-0.017644,-0.067882,0.641955,-0.034365,0.037177,0.280013,-0.512064,0.418923,0.163368,-0.039371,0.111555,0.141645,0.464580,-0.561372,-0.050732,-0.344276,0.279454,-0.167593,0.883302,-0.152930,0.127564,0.053462,-0.496390,-0.172710,-0.606368,0.194815,-0.116714,-0.257495,0.056565,-0.507118,0.128381,0.029097,0.197470,0.141288,0.297315,-0.066652,0.423171,-0.500144,0.096001,0.347348,0.011768,-0.200363,0.325614,-0.179410,0.252846,-0.314887,-0.169064,-0.245153,0.295469,0.361460,0.481621,0.215781,-0.148088,-0.305339,-0.012032,0.069018', '26665875', '25662337', '1300324', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307584', '与男孩同车', '剧情', 'Beverly（德鲁·巴里摩尔 饰）是一个怀揣作家梦的少女。她的父亲是一名警察，而男朋友Ray却是一个瘾君子。当男友得知Beverly怀了自己的孩子后，便毅然决定和她结婚。然而婚姻并不能改变Ray，他不上进，不顾家，甚至因为吸毒而花掉了本应给儿子治病的钱。Beverly再也无法忍受让这个男人来继续破坏自己和儿子的生活，于是与其分手。可年幼的儿子却并不能理解母亲的所作所为，母子间的隔阂也越来越大。然而生活的一团糟并没有击垮Beverly，当挚友Fay也离她而去之后，她仍坚持着自己最初的梦想。同时，与儿子同父亲的关系也在慢慢的改善中……©豆瓣', '德鲁·巴里摩尔', '潘妮·马歇尔', 8.2, 6284, 'tt0200027', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2027432227.jpg', 0.3, 1.5, 17.6, 51, 29.6, '0.221233,-0.028183,-0.748410,0.729795,-0.439111,-0.785436,1.113560,0.091394,-0.488711,-0.319397,-0.106782,0.810385,0.319978,0.468160,0.155138,0.119324,-0.262076,-0.788407,0.104219,-0.056059,-0.303359,-0.585128,-0.051886,-0.206339,-0.264336,-0.037233,0.882195,-0.069440,-0.136462,0.321186,0.371104,-0.104163,0.107722,0.859587,-0.265615,0.195309,-0.267091,0.329572,-0.211234,0.098688,0.335918,-0.151601,-0.097450,0.464849,0.036370,0.510605,0.454572,-0.365333,-0.136918,-0.242592,0.171204,-0.239292,-0.103282,0.198072,-0.046021,-0.176176,0.459132,0.151606,-0.243335,-0.096917,0.018282,-0.012144,-0.764602,0.167576,0.089185,-0.025855,-0.698958,0.607041,-0.082077,-0.158917,0.018431,-0.283580,0.189264,0.415576,0.150279,0.543992,-0.889686,-0.077686,-0.642617,0.230671,0.821038,0.099980,-0.104870,0.549255,-0.374454,-0.281879,-0.111378,-0.327760,-0.797260,-0.034232,-0.069252,0.393098,-0.517395,0.281335,-0.300884,-0.043260,-0.480138,-0.045107,0.136240,-0.648459,0.287588,-0.064532,-0.095490,-0.385490,-0.519608,0.051140,0.159645,-0.550615,0.620627,-0.888580,0.249788,0.631244,0.554848,-0.791572,0.661906,0.454415,0.305328,-0.277136,-0.228071,0.396372,-0.020848,0.276112,0.068526,0.157334,0.101049,-0.057397,-0.126555,0.688425', '4275444', '2075721', '1304977', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307597', '黑天使', '剧情', '莉威亚（安娜·加列娜 Anna Galiena 饰）年轻美丽，嫁给了年长28岁的文化权贵卡罗（Antonio Salines 饰），过大的年龄差距，令莉威亚一直在情感和情欲上感到不满足。一次话剧演出，莉威亚认识了年轻英俊的纳粹军官哈罗特（加布埃尔·加科 Gabriel Garko 饰），迅速与他坠入情网。莉威亚的爱浓烈且毫无保留，始终对哈罗特欲火炽热，而哈罗特却只是逢场作戏，贪图她的身体和金钱。这个纳粹军官其实内心深深厌恶和咒骂战争，因此只想从女人身上骗到钱，退役过好生活，但也无法阻止莉威亚的爱和欲望将两人带向毁灭……©豆瓣', '安娜·加列娜', '丁度·巴拉斯', 6.7, 7982, 'tt0267261', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1047887810.jpg', 1.9, 9.8, 50.8, 27, 10.4, '0.333525,-0.110298,-0.819884,0.450743,0.185171,-0.479070,1.077668,0.037050,-0.195740,-0.243520,-0.321877,0.434278,-0.086385,0.176647,0.285016,0.093639,-0.255998,-0.804414,0.059632,0.108154,-0.369075,-0.485510,0.027727,-0.413896,-0.350165,-0.707661,0.498597,0.175272,-0.071182,0.702181,0.477794,0.586840,0.342931,0.715961,-0.090409,-0.445289,0.081855,-0.388337,-0.103242,0.072404,0.039408,-0.279512,0.030621,0.328006,-0.136813,0.303370,0.700461,-0.161472,0.055809,0.056438,0.226402,-0.401445,-0.075520,0.077323,-0.043990,-0.242012,-0.094611,-0.149326,0.216346,-0.099591,0.041673,-0.365880,-0.580627,-0.336186,-0.052464,0.120921,-0.542998,0.499870,-0.214804,-0.007991,0.160587,-0.050474,0.108316,-0.255586,-0.187290,0.437649,-0.408423,0.216255,-0.497655,0.128320,0.327308,0.379339,-0.145695,0.378120,-0.814244,-0.462602,-0.019629,-0.458604,-0.493683,-0.090247,0.075016,0.209245,0.238635,0.246866,-0.571505,-0.164877,-0.194239,0.035082,0.074150,-0.694621,0.076187,-0.263260,-0.782455,-0.734468,-0.300118,-0.025860,0.113870,-0.269922,0.789142,-0.834836,0.111729,0.759064,0.602336,-0.356256,0.616104,0.280496,-0.053308,-0.020709,-0.340633,0.523523,-0.046985,-0.329094,0.032402,0.454813,0.084321,0.098712,-0.033119,0.522169', '2131640', '3059036', '25911595', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307639', '最卑贱的人', '剧情', '本片主人公（爱米尔·强宁斯 Emil Jannings 饰）是一所大旅馆的看门人，一直以来他都为这份体面的工作感到自豪。当他下班后穿着神气的制服，回到自己所居住的贫民区时，邻居们都会向他投来羡慕的眼光。新一天开始了，如常上班的他却被告知老板要辞退他，因为他年纪太大了。但念在他工作多年的份上，老板把他调去打扫厕所，还要收 回他的金边制服。他一下子从神气十足的看门人变成了低三下四的厕所清洁工。不能接受这个事实的他，夜里潜入旅馆把制服偷了回来。他穿着制服去参加侄女的婚礼，没有把被调职一事告诉亲朋好友。很快，他的秘密被别人知道了，大家纷纷嘲笑他。他再也没有颜面去面对别人了，于是跑回旅馆归还了制服，失魂落魄地坐在厕所中。然而故事并没有就此结束……影片改编自果戈里的小说《外套》。©豆瓣', '埃米尔·雅宁斯', 'F·W·茂瑙', 8.7, 6720, 'tt0015064', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205341979.jpg', 0.2, 0.6, 8, 44.7, 46.6, '0.344883,0.098152,-0.771198,0.238027,-0.709919,-0.338456,0.612689,0.191314,-0.447691,-0.238664,0.175217,0.876791,-0.064693,0.316070,0.122978,0.233586,-0.371051,-0.667551,0.091536,-0.272991,-0.300489,-0.129593,-0.011102,-0.256730,-0.027345,-0.143922,0.181284,0.016143,-0.180247,0.349157,0.419146,0.052924,0.271182,0.866202,-0.248678,0.123022,-0.075944,-0.036846,0.292195,0.281303,0.067214,-0.280546,-0.189273,0.393829,0.196663,0.407698,0.664718,0.049811,-0.279067,0.173039,0.563496,-0.167866,-0.013116,0.339504,0.135126,-0.022316,-0.048584,0.251414,-0.288795,0.125989,0.133905,0.007167,-0.466528,-0.011614,-0.175251,0.177239,-0.925905,0.785565,-0.320561,0.045799,0.046292,-0.540542,0.193842,0.027040,-0.093311,0.518084,0.091226,-0.009834,-0.702920,0.501298,0.626100,0.007214,0.156561,0.333030,-0.105287,-0.073590,0.215547,-0.115928,-0.452062,0.007881,0.434976,-0.029556,-0.315680,-0.163076,-0.397881,-0.294577,-0.201202,-0.485037,-0.019403,-0.513711,-0.236251,-0.442692,0.025719,-0.281149,-0.269469,-0.107491,-0.042708,-0.151921,0.495897,-0.662844,0.106144,0.539641,0.403778,-0.660570,0.907102,0.003779,0.229814,0.169074,0.054075,-0.042085,0.172760,0.908122,0.422560,0.477232,0.065817,-0.264993,-0.475287,0.372699', '26678509', '2063528', '2990737', '1293607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307649', '女魔头', '剧情', '沃诺斯（查理兹·塞隆 Charlize Theron 饰）童年的不幸把她推向了罪孽深重的人生。她的母亲离她而去，对待她的是无休止的谩骂和虐打。沃诺斯为了满足毒瘾和生计，十来岁就开始了卖淫的生活。她在公路上为司机们提供低级的性服务，无望的生活无穷无尽。然而，年轻女孩西尔比 （克里斯蒂娜·里奇 Christina Ricci 饰）的出现让她心中有了亮光，两人开始了一段恋情，住在一起。西尔比对于金钱的需求很大，这使得沃诺斯心甘情愿为爱人奔波赚钱。她去面试了好几份工作，却因为知识的匮乏和粗鲁的男性化性格而被拒之门外。她只能重操旧业，在公路上遇见了一个变态的嫖客，一怒之下把他杀死，夺走了他的钱和车。从此，沃诺斯开始频频犯罪，成为公路上的心狠手辣的女魔头。©豆瓣', '查理兹·塞隆', '派蒂·杰金斯', 7.7, 31256, 'tt0340855', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1384540432.jpg', 0.4, 2.4, 27.6, 48.7, 20.8, '0.482535,0.041461,-0.659996,0.637341,-0.455013,-0.311935,0.840011,0.221704,-0.350095,-0.005439,0.155868,0.829707,0.112661,0.349425,0.241696,0.046610,-0.227872,-0.706069,0.123062,-0.153728,-0.402728,-0.472636,-0.095766,-0.272370,-0.171776,-0.506755,0.364078,0.036455,-0.173987,0.354697,0.245369,0.272066,0.331323,0.417935,-0.256998,0.137635,0.014512,-0.218444,0.006718,0.109237,-0.123619,-0.311657,-0.064311,0.129862,0.150422,0.475678,0.571816,-0.167942,-0.174818,-0.050034,0.354302,-0.586687,0.014651,0.267919,0.011440,-0.133864,0.129846,0.094861,-0.495202,-0.045046,0.143434,-0.246664,-0.947201,-0.007153,-0.229946,0.104451,-0.772765,0.475964,-0.291062,-0.084985,0.131613,-0.473422,-0.017348,0.311721,0.053314,0.385375,-0.053727,-0.022172,-0.517296,0.081792,0.797649,0.059365,-0.300070,0.344632,-0.430150,-0.128290,0.089613,-0.444450,-0.547355,-0.363283,0.448667,-0.066092,-0.348357,0.363990,-0.672696,0.161355,-0.260587,-0.320639,-0.008553,-0.411266,-0.316062,-0.522721,-0.206157,-0.675963,-0.486845,0.022837,0.125735,-0.610541,0.794157,-0.856211,0.119360,0.788791,0.487524,-0.447148,0.720992,0.066469,0.078164,0.044882,-0.116517,0.333925,0.096934,0.403686,0.227312,0.273492,-0.055446,0.193420,-0.365604,0.944792', '35158375', '25763555', '30162520', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307657', '古墓丽影2', '动作', '罗拉•克劳福特（安吉丽娜•朱莉 饰）这名勇于挑战的探险家继续她的探索之路。这次是寻找早已沉入大海的月神庙。根据资料显示，月神庙内埋藏了传说中的“潘朵拉魔盒”。而一股巨大的能量正存在与这个魔盒当中，同时间邪恶的势力也对这个股力量虎视眈眈。因为这股力量的巨大能足以摧毁整个人类世界，邪恶的势力企图利用的话后果不堪设想。罗拉一边寻找这股传说中的神奇力量，一边与香港黑帮的头目斗智斗勇。到底罗拉能不能顺利获得这股力量，保卫整个人类世界的安全呢？©豆瓣', '安吉丽娜·朱莉', '扬·德·邦特', 6.6, 59074, 'tt0325703', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1678090020.jpg', 1.6, 9.8, 52.8, 27.2, 8.5, '-0.060644,0.320748,-0.912200,0.772947,-0.114004,0.253198,0.855146,-0.121132,-0.756103,-0.106785,0.031474,0.531840,0.023376,0.016937,0.066019,0.172354,-0.234576,-0.532744,-0.203995,-0.245903,-0.302114,-0.179393,-0.753674,-0.188809,-0.018472,-0.548010,0.712372,0.478867,-0.480245,-0.041614,-0.018505,0.538812,-0.337765,0.481713,-0.123660,-0.311138,0.083222,-0.169942,-0.275709,0.280246,0.148843,0.076780,0.151641,0.502631,-0.218532,-0.096955,0.473347,-0.565551,0.236030,-0.343365,0.348875,-0.225716,-0.258204,0.008335,0.228674,0.026065,0.188545,-0.014114,0.057163,-0.325285,0.339315,-0.378696,-1.115115,-0.353122,-0.158017,0.245820,-0.088947,-0.227157,0.239879,-0.155846,0.148482,-0.016653,-0.015239,0.245141,0.217871,0.408856,-0.272189,-0.150954,-0.417016,-0.223931,0.455648,-0.414547,-0.492953,0.331122,-0.143413,-0.409787,-0.500555,-0.147256,-0.301999,-0.216665,0.389008,0.629292,0.057631,0.454618,-0.860620,0.356339,-0.236221,-0.250512,-0.107270,-0.345176,-0.063809,-0.565430,-0.671722,-0.128162,0.194440,0.314406,0.453329,-0.092967,0.741612,-0.510913,0.241558,0.876362,0.508095,-0.464158,0.350639,-0.143178,0.197050,-0.319822,-0.170781,0.354688,-0.099491,0.531681,0.102667,0.611838,0.220022,-0.097771,-0.345719,0.552480', '1308784', '26667010', '1308585', '30368448');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307675', '上海正午2：上海骑士', '喜剧', '1887年，在西部某镇担任治安官的强（成龙 饰）忽然收到一封家信，惊闻看护玉玺的父亲被人杀死，玉玺失踪，妹妹铃（范文芳 饰）追踪犯人一路到了英国。于是强匆忙奔赴纽约，寻找老友罗伊（欧文•威尔逊 饰），强本想用上次得来的皇家黄金帮助自己，岂料风流兼吹牛成性的罗伊早将黄金豪赌一空，如今落魄成了一个偶尔卖身的侍应。强虽无奈，还是带着罗伊一起到了英国。先期抵达英国的铃跟踪仇人雷斯本多日，在后者身上，隐藏着一宗涉及清、英两国的重大阴谋。原来私生子出身的皇帝之弟吴超（甄子丹 饰），为了夺取皇位同雷斯本联手，抢夺玉玺计划发动兵变。匆忙赶到的强，为了复仇和家族荣誉，决定不惜一切阻止吴超。©豆瓣', '成龙', '大卫·道金', 6.5, 16828, 'tt0300471', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546318083.jpg', 1.2, 9, 58.8, 24.3, 6.7, '0.121233,0.271673,-0.691849,0.513152,0.005292,-0.056046,0.094017,0.200045,-0.490110,-0.405766,0.277276,0.557066,0.100200,-0.280727,0.164412,0.135862,-0.203058,-0.554325,-0.092939,-0.076336,-0.231564,-0.407226,-0.385987,-0.122105,-0.221628,-0.310171,0.373594,0.121618,0.025847,0.568534,0.444521,0.276176,-0.298880,0.165017,-0.156220,-0.026848,0.148837,0.104789,-0.335996,0.478377,0.057934,-0.277576,-0.232997,0.088636,0.273277,0.330442,0.360287,-0.156509,0.148745,-0.063581,0.281612,-0.209895,-0.205150,-0.030617,0.380324,0.285853,-0.144249,0.271968,-0.397268,-0.006853,0.125860,-0.141815,-0.651458,0.094998,0.142044,-0.196637,-0.441392,0.270546,-0.291296,0.073257,0.069206,-0.440777,0.255289,0.448349,-0.144422,0.190439,-0.158096,0.080290,-0.526007,0.350622,0.590429,-0.130373,0.106390,-0.274393,0.270078,-0.095509,0.093668,-0.523770,-0.111572,-0.013235,0.646920,-0.135069,0.126463,0.125719,-0.395286,-0.282116,-0.455654,0.301469,0.280809,-0.182774,-0.040782,-0.404399,0.047533,0.068531,-0.034622,0.147631,0.144680,-0.224766,0.576340,-0.531072,0.185271,0.689850,0.474059,-0.702951,0.191049,-0.015154,0.124422,-0.193994,-0.240174,0.142903,0.479721,0.225096,0.209410,-0.194151,-0.161865,-0.356191,-0.203284,0.086241', '5973984', '26678784', '1304382', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307678', '墨西哥往事', '动作', '吉他手埃尔（安东尼奥•班德拉斯 Antonio Banderas 饰）是墨西哥荒漠上最令人闻风丧胆的神枪手，他曾经摧毁了一个又一个当地的毒枭、黑帮，因此也八面树敌。在痛失爱妻之后，心灰意冷的埃尔背着他的吉他开始四处流浪，从此销声匿迹。现今，大毒枭巴罗瑞（威廉•达福 Willem Dafoe 饰）逐渐建立起了他的毒品王国，野心勃勃的他甚至还在密谋刺杀总统，推翻墨西哥政权。CIA探员桑德斯（约翰尼•德普 Johnny Depp 饰）得知了巴罗瑞的阴谋，于是，他找到了埃尔。曾经的铁血战士埃尔当然不会袖手旁观，他终于重出江湖。但是，事情并没有表面的那么简单，墨西哥荒漠上一出传奇正在徐徐上演。©豆瓣', '安东尼奥·班德拉斯', '罗伯特·罗德里格兹', 7.4, 24018, 'tt0285823', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541169158.jpg', 0.8, 5.3, 35.2, 42.6, 16, '0.261961,0.028227,-0.799499,0.585431,0.144146,-0.350773,0.813662,0.143092,-0.556281,-0.164308,0.232684,0.819540,0.060875,-0.202130,0.333506,0.238509,-0.604332,-0.731221,0.054720,-0.176132,-0.016366,-0.468660,-0.457584,-0.495834,-0.053555,-0.222873,0.382534,0.163067,-0.146078,0.187219,0.352447,0.260206,0.157903,0.319134,-0.204669,-0.010569,0.270835,-0.227001,-0.224868,0.211172,-0.011250,-0.218698,-0.236357,0.463177,-0.160207,0.431190,0.363116,-0.425067,0.272925,-0.338971,0.284343,-0.382771,-0.107136,-0.270606,0.402241,-0.095035,0.045961,0.329369,0.039178,-0.242743,0.091563,0.106625,-0.588729,0.041003,-0.095285,0.318624,-0.473481,0.495714,-0.022819,0.140979,-0.065859,-0.223032,0.177474,0.336278,0.128616,-0.055922,0.010917,0.044666,-0.729410,0.164916,0.605733,0.142903,-0.034857,-0.087006,-0.008938,-0.551995,-0.015217,-0.530358,-0.372466,-0.210007,0.385196,-0.455431,0.016865,0.499483,-0.546936,-0.043224,-0.576901,-0.247699,0.064211,-0.091679,0.025731,-0.580361,-0.135852,-0.174894,-0.233794,0.006063,-0.051268,-0.153372,0.491619,-0.755930,0.367160,0.604668,0.048308,-0.219403,0.231217,0.035769,0.011599,-0.111155,-0.197001,0.451796,0.116291,0.352429,0.196759,0.217666,0.138207,-0.491982,0.111435,0.424188', '1947080', '10774184', '1301686', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307679', '不夜城', '剧情', '刘健一（金城武饰）是新宿歌舞伎町的混混，身为台湾与日本人的残留孤儿，混血的他被叫作半唐番，不为社会所容纳。歌舞伎町有着上海帮、福建帮、北京帮、台湾帮等，各方力量形成复杂的角力形势。年关将至，似乎是因为健一的前度拍档吴富春（椎名桔平饰）返回歌舞伎町，他因杀死元成贵（曾志伟饰）的手下而逃亡，元成贵遂限令健一在三日内交出富春，否则二人便只有死路一条。此时左藤夏美（山本未来饰）出现，她称与有过节，为了活命甘愿出卖一切，健一被她吸引。富春终于现身，偷袭元成贵的情妇黄秀红的夜总会“上海滩”，令健一陷入绝境。所有人都劝他离开歌舞伎町，但真相并不是那么简单，命运并没有眷顾二人……©豆瓣', '金城武', '李志毅', 8.3, 25582, 'tt0169929', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p643108501.jpg', 0.3, 1.6, 17.9, 45.5, 34.7, '0.127017,0.104838,-0.619571,0.175690,-0.039057,-0.160484,0.457637,0.181597,-0.333735,-0.306532,0.145890,0.836942,0.046384,-0.134810,-0.003255,0.187884,-0.192768,-0.551761,-0.017782,-0.125180,0.058692,-0.328901,-0.026723,-0.189152,-0.385028,-0.055943,0.576050,0.393459,-0.198978,0.402872,0.356795,0.374099,-0.267594,0.388085,-0.080783,-0.071072,-0.207727,-0.161350,-0.447705,0.332955,-0.386923,-0.400110,-0.171297,0.165130,0.017138,0.391585,0.400080,-0.164246,-0.133975,-0.223096,0.098802,-0.492488,-0.289714,0.125333,0.328288,-0.256656,0.113767,0.262628,-0.512882,0.041738,-0.034799,0.010349,-0.769245,0.027934,0.336963,0.134635,-0.349885,0.166030,-0.213327,-0.305770,0.103269,-0.188289,0.176868,0.312149,0.231468,0.029118,-0.202634,0.088562,-0.413263,0.079132,0.841178,-0.113164,0.069126,-0.028389,-0.046106,-0.415665,-0.060517,-0.388275,0.025838,-0.034830,-0.141870,0.061647,-0.019735,-0.139429,-0.336834,-0.368346,-0.199408,-0.150459,0.213094,-0.283213,-0.048353,-0.505877,0.009680,-0.310380,-0.293172,0.089134,0.396398,-0.020693,0.543887,-0.765332,0.134791,0.520865,0.604337,-0.609502,0.627002,0.074514,0.074773,0.008150,-0.122781,-0.000355,0.243204,0.182523,0.187583,0.110682,-0.114997,-0.261406,-0.218284,0.140065', '25721544', '26678784', '4301278', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307681', '榴莲飘飘', '剧情', '学了九年京剧却在内地没有出路的阿燕（秦海璐）不得已来到旺角理智地化为妓女挣快钱，并给自己定下（做到双程护照到期的）期限，在所住小巷结识同样来自大陆但是非法入境的少女阿芬（麦惠芬）后，她被阿芬在逆境中的乐观与单纯打动，两人在异乡成为朋友。返回牡丹江小镇换作另一种身份决定好好生活时，阿燕发现周围世界已与她所理解的大不相同，见识到现实中另外的（不同于在港时的）残酷与无情，心生失落，而当收到阿芬寄来的榴莲时，各种复杂滋味涌上她心头。©豆瓣', '秦海璐', '陈果', 7.7, 35339, 'tt0255327', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p582402863.jpg', 0.4, 1.8, 27.2, 53.5, 17.2, '0.261553,0.373034,-0.792104,0.533882,-0.099195,-0.066590,0.775160,-0.112815,-0.652010,-0.168838,-0.018807,0.735136,0.060602,0.415628,0.420807,-0.122187,-0.202777,-0.575042,0.057642,-0.563739,-0.160525,-0.427276,-0.108623,0.012760,-0.289526,-0.335993,0.890545,0.303958,-0.181339,0.456334,0.078168,0.356457,-0.348513,0.575066,-0.397300,-0.009355,-0.119981,0.115087,-0.610930,0.132207,0.093568,0.077346,-0.280703,0.167409,0.047843,0.293262,0.754069,-0.138370,-0.323345,0.314730,0.426839,-0.010561,-0.215567,0.024535,-0.053113,0.076494,0.157258,0.059550,-0.335390,0.265479,0.021733,-0.000150,-0.538668,0.004890,0.065788,0.003298,-0.590665,0.353249,-0.089894,-0.226771,-0.048741,-0.466047,0.176076,0.180066,0.279207,0.627290,-0.253250,-0.013953,-0.353466,0.072943,1.055381,0.121908,-0.422622,0.323938,-0.266274,-0.357273,0.173039,-0.245550,-0.158537,-0.011625,0.154949,0.392212,-0.456887,0.292602,-0.589302,-0.045736,-0.070598,0.029675,0.168709,-0.638089,-0.376094,-0.471589,-0.293665,-0.302709,-0.189967,0.036603,0.321162,-0.389568,0.535336,-1.026510,0.424883,0.234315,0.327496,-0.416147,0.670109,0.074371,0.087247,-0.264283,-0.199802,0.548415,0.110139,0.329393,-0.035294,0.108564,-0.457660,0.111547,-0.479821,0.488521', '25721544', '35030151', '1870682', '4728584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307684', '爱比死更冷', '喜剧', '慕尼黑青年弗兰茨（赖纳·维尔纳·法斯宾德 Rainer Werner Fassbinder 饰）出狱后，决定金盆洗手。但他转眼就被黑社会组织盯上，想要诱使他重新犯罪，但是弗兰茨意志坚定，拒绝就范。他回到慕尼黑找到女友乔安娜（汉娜·许古拉 Hanna Schygulla 饰），两人住在一起。弗兰茨整天无所事事，靠着乔安娜的接客钱生活，但是乔安娜一直渴望与他结婚，过上平静的生活。不久，弗兰茨的狱友布鲁诺（尤利·隆美尔 Ulli Lommel 饰）来到慕尼黑找到弗兰茨，跟他们住在一起。布鲁诺其实是黑社会组织成员，他设计了几个陷阱试图让弗兰茨重回犯罪之路，但是弗兰茨毫不知情，甚至让自己的女友去陪布鲁诺。虽然弗兰茨对乔安娜毫不在意，一心爱着弗兰兹的乔安娜在布鲁诺再次陷害他的时候报了警，乱枪中布鲁诺被打死，弗兰兹和乔安娜试图逃跑，但是他们面前的死亡之路似乎无法逾越。', '尤利·隆美尔', '赖纳·维尔纳·法斯宾德', 7.2, 7782, 'tt0064588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2549044702.jpg', 1, 5.8, 39, 40.5, 13.7, '0.267854,0.081526,-0.696537,0.589635,-0.358333,-0.453840,0.850194,-0.094455,-0.445805,-0.345834,-0.289463,0.779190,-0.068764,0.710434,0.368923,0.033051,-0.515712,-0.731773,0.343062,-0.011729,-0.223981,-0.760133,0.076594,-0.463898,-0.198635,0.150293,0.477735,0.085685,-0.075522,0.417889,0.294498,0.330462,-0.008414,0.678088,0.094993,0.158582,0.306853,-0.212394,-0.230661,0.117315,0.326110,-0.184570,-0.179456,0.400100,0.402148,0.375575,0.343365,-0.306763,0.143981,-0.102185,0.108756,-0.372264,0.198476,0.387701,0.157163,-0.087750,0.130362,0.004956,-0.013261,-0.042528,0.069927,-0.183739,-0.344153,0.183091,-0.108261,-0.073086,-0.557719,0.137657,-0.187755,0.224464,-0.026072,-0.282977,0.159428,0.470248,0.424143,0.100084,-0.208432,0.078565,-0.720899,-0.245380,0.578470,0.109392,-0.189086,0.158936,-0.186993,-0.276606,-0.077730,-0.115432,-0.551450,-0.139664,0.404444,-0.029385,-0.083980,0.183490,-0.419726,-0.466234,-0.241025,0.201240,-0.217651,-0.367922,-0.076984,-0.561973,-0.092523,-0.399761,-0.337012,0.188215,-0.266852,-0.466878,0.243790,-0.623103,0.215765,0.425597,0.479064,-0.614170,0.560850,0.075085,0.168804,-0.038915,0.166908,0.791715,0.409108,-0.022264,0.573558,0.245875,-0.043987,0.034538,-0.111934,0.476377', '1293145', '2075721', '1292328', '3364223');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307687', '叶塞尼亚', '剧情', '19世纪热情洋溢的墨西哥小镇，吉普赛女郎叶塞尼亚（杰奎琳·安德瑞 Jacqueline Andere 饰）和伙伴们畅快淋漓歌舞，她高傲聪慧，宛若一株带刺的玫瑰，由于时常遭到白人的歧视，因此叶塞尼亚偶尔会偷钱惩治这帮势力眼，却不知道自己拥有怎样曲折的身世。某天，叶塞尼亚在酒馆算命，结识了自信满满的白人军官奥斯瓦尔多（Jorge Lavat 饰）。一来二去的交往，这对有情男女坠入爱河。爱情的甜蜜与苦涩，令他们饱受折磨。勇敢的奥斯瓦尔多请求吉普赛头人同意他们的结合，在叶塞尼亚外婆的点拨和撮合下，这个狂野女郎最终如愿和奥斯瓦尔多结为夫妇。幸福总是短暂易逝，叶塞尼亚和丈夫迎来了长时间的生离死别，他们的爱情也经历了严峻的考验……©豆瓣', '杰奎琳·安德瑞', '阿尔弗雷多·克雷维纳', 8.2, 7752, 'tt0245580', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560631154.jpg', 0.1, 0.7, 17.3, 51.9, 29.9, '0.187394,-0.003093,-0.652901,0.362872,-0.006926,-0.169810,0.893434,0.010454,-0.266294,0.027095,0.234971,0.722336,-0.176476,0.129809,0.241831,-0.105532,-0.571014,-0.385724,0.117056,-0.055045,0.081395,-0.336125,-0.154158,-0.038802,0.115076,-0.389516,0.353167,0.257742,-0.017995,0.657614,0.181488,0.393472,-0.068444,0.143302,-0.321127,0.047926,0.301002,0.081327,-0.319355,-0.149002,0.069135,0.258733,-0.595939,0.004239,0.022003,0.195499,0.449774,-0.219454,-0.282463,0.065596,0.376371,-0.098201,0.214700,0.225840,0.089099,-0.161527,0.253462,0.164540,-0.175879,-0.307721,0.015613,0.054945,-0.617854,0.089235,0.145430,0.104694,-0.664353,0.478584,-0.036430,-0.224603,-0.005604,0.157332,0.019878,0.478553,0.265263,0.469441,0.083724,0.028626,-0.381117,0.068938,0.910447,0.313503,-0.624203,0.026134,-0.639679,-0.363579,0.015331,-0.379503,-0.514253,-0.168346,0.520753,-0.209609,-0.110412,0.703480,-0.710546,0.391944,-0.276930,-0.030509,0.093943,-0.510304,-0.261720,-0.537444,-0.334584,-0.600640,-0.341621,0.107966,0.090626,-0.024349,0.964902,-0.633582,0.377474,0.431113,0.575635,-0.264220,0.813037,0.469488,-0.237206,-0.312416,-0.314984,0.828986,0.029947,-0.319942,0.227632,0.456243,0.012488,0.174499,-0.411946,0.343177', '26348103', '25882279', '30162520', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307690', '顽主', '剧情', '于观（张国立饰）、杨重（葛优饰）和马青（梁天饰）三人在北京开了一家“替人排优、替人解难、替人受过”的三T公司，专门替人解难、解闷、受过。他们碰到了形形色色的怪人和怪事，啼笑皆非，但都给应付了过去，公司业务兴隆，生意火爆。一个要与女友分手又怕看女友掉泪的人找于观求助，于观受托约见刘美萍（马晓晴饰），十分含蓄地讲出问题并不断责备自己，泪流满面的刘美萍破涕为笑。后来，法院送来传票，勒令三T公司停业整顿，他们三人掏尽了所有的钱打发上门讨饭的顾客亲属，突然，马青说想要打人。大街上，他们肆意冲撞地些郁郁寡欢的中年人，可这些人只顾赶路，毫无反应。©豆瓣', '张国立', '米家山', 8.4, 87529, 'tt0276615', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568766751.jpg', 0.2, 0.9, 13.5, 49.1, 36.4, '0.160618,-0.192026,-0.317657,0.240990,0.008844,-0.358669,0.585983,0.182528,-0.393096,-0.256118,-0.193493,0.558100,-0.218427,0.289523,0.335268,-0.066713,0.009198,-0.363930,0.149024,-0.011582,-0.065674,-0.264292,0.210938,-0.357060,-0.341776,0.237537,-0.242806,-0.171614,-0.113261,0.401048,0.495927,0.084068,-0.125483,0.323195,-0.190985,0.156332,-0.234760,0.206169,-0.116057,-0.077264,-0.027560,-0.361838,-0.373628,0.169356,0.244652,0.525414,0.329833,0.235255,-0.194555,-0.026900,0.067453,-0.192782,0.163675,0.139778,0.266915,0.050443,0.506537,-0.050180,-0.332999,0.036229,0.152656,0.041781,-0.489214,0.052941,-0.042821,-0.089467,-0.718007,0.276651,-0.079413,0.011438,-0.329793,-0.547609,0.241534,0.269846,0.003903,0.361175,-0.070334,-0.151947,-0.579447,0.377766,0.380363,0.124147,0.170790,0.252963,0.016043,-0.047631,0.300651,-0.274026,-0.275267,-0.022956,0.236114,-0.025667,-0.224407,-0.358219,-0.435359,-0.046797,-0.082666,-0.362915,-0.114945,-0.381737,-0.097814,-0.745342,0.095927,-0.247151,-0.300182,0.234034,0.253234,-0.020727,0.212251,-0.366042,-0.079389,0.448247,0.305297,-0.772054,0.619518,0.207496,0.061707,-0.024330,-0.488043,-0.383373,0.277079,0.570604,0.306137,0.115931,-0.006697,-0.207675,-0.002030,-0.097007', '4300640', '3183490', '1293658', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307694', '无间道3：终极无间', '剧情', '刘建明（刘德华）在陈永仁（梁朝伟）被杀10个月后接受警队内部调查，被架空职权，加上家庭的变故，他的精神状态每况愈下，但他坚信局面很快就会扭转。年轻警司杨锦荣（黎明）在同事看来是怪人一个，他正凭着过人的业绩迈向警队最高层。为了搞清楚杨锦荣的真实身份，刘建明开始对其调查。刘建明渐渐发现韩琛旧日的生意拍档沈澄（陈道明）与杨锦荣有着千丝万缕的关系，为了置杨锦荣于死地，也为了不让自己的身份曝光，渴望做个好人已久的刘建明开始千辛万苦地找寻一个又一个证据，可是他总在最接近真相时功亏一篑。©豆瓣', '梁朝伟', '刘伟强', 8.2, 319984, 'tt0374339', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2527603461.jpg', 0.3, 1.8, 19.8, 44.6, 33.5, '0.224768,0.165953,-0.480962,0.484298,-0.300008,-0.108518,0.541114,0.154488,-0.751004,-0.488252,0.293979,0.848657,-0.090322,0.176591,0.078117,-0.159970,-0.206195,-0.776622,0.162669,-0.169876,-0.124083,-0.605327,-0.433381,-0.115913,-0.174607,0.006485,0.915272,0.162764,-0.265238,-0.022394,0.328674,0.103990,-0.035081,0.456143,0.036219,-0.245837,0.095928,-0.036797,-0.485380,0.272155,0.259770,-0.418007,-0.227657,0.408154,-0.281907,0.435124,0.503755,-0.026737,-0.410636,-0.087693,0.515843,-0.384205,-0.150224,-0.024490,0.530255,0.094936,0.076346,0.453810,-0.366890,-0.029153,-0.038428,-0.056640,-0.961697,0.041447,0.261086,0.241533,-0.556052,0.150791,0.054437,-0.008384,0.150939,-0.319276,0.087382,0.537472,0.294630,0.391035,-0.329420,0.191634,-0.609431,-0.071591,0.732682,0.060688,-0.114599,0.421168,0.021194,-0.343723,-0.060294,-0.164493,-0.329901,-0.163186,0.227359,0.154781,-0.329514,0.186078,-0.292673,-0.028468,-0.355273,0.164691,-0.146894,-0.492783,0.014589,-0.090685,-0.505522,-0.301053,-0.170938,0.057956,-0.020551,-0.494107,0.532215,-0.803730,-0.067545,0.703313,0.126697,-0.884059,0.464619,0.394538,-0.038977,-0.439240,-0.331325,0.190202,0.173627,0.266421,-0.093318,-0.014442,-0.019813,-0.366108,-0.220276,0.253179', '26678784', '30345227', '3811342', '34929897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307696', '午夜凶铃', '悬疑', '女高中生友子和同学共同看了一盘来历不明的录像带，七天后，她和她的同学相继死去，这引起了女记者浅川（松岛菜菜子 饰）的关注，她决定调查这个事件的真相。浅川了解到友子死前曾因看一盘录像带惊吓过度而住院，于是她找到了出租那盘录像带的旅店，也租了那盘没有名字的带子，打开录像机，极度恐怖的画面让浅川情绪几近崩溃。浅川的前夫高山（真田广之 饰）此时来到了她的身边，并且复制了一盘录象带决定和她一起研究。而他们只有在七天之内揭开录像带的秘密才能活下去……©豆瓣', '松岛菜菜子', '中田秀夫', 7.6, 119731, 'tt0178868', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1324520469.jpg', 0.8, 3.6, 32.1, 44, 19.5, '0.240725,-0.103462,-0.556396,0.432363,-0.221673,-0.143874,0.736168,0.278392,-0.345708,-0.259687,-0.010264,0.695821,-0.146368,0.554825,0.251019,-0.015664,-0.483473,-0.868848,-0.233650,-0.329988,-0.556677,-0.339820,-0.052776,-0.438473,0.145652,0.046461,0.642413,0.039326,-0.022649,0.285817,0.284499,-0.193925,-0.017689,0.384632,-0.004857,0.384047,0.096150,-0.045276,-0.122569,0.400683,0.177331,-0.505705,0.036786,0.544474,0.249835,0.439345,0.816074,-0.180270,-0.355488,-0.000198,0.190772,-0.298892,-0.170766,0.118209,0.363033,0.144194,0.230518,-0.021244,-0.621115,-0.302557,0.187398,0.101100,-0.387701,-0.145091,0.065696,0.281410,-0.445151,0.443289,-0.155363,0.097340,0.190382,-0.259590,0.214772,0.197136,0.400282,0.139369,-0.059531,-0.156591,-0.382015,0.325122,0.459925,0.012330,0.237522,0.298259,-0.041197,-0.433114,-0.209540,-0.099382,-0.294890,0.183869,0.436741,0.411519,-0.282497,-0.058420,-0.531347,-0.357961,0.038805,-0.333900,0.221870,-0.407419,-0.308327,-0.611511,-0.415701,-0.212977,-0.272635,0.042075,-0.042133,-0.258184,0.697558,-0.551909,0.172395,0.431982,0.166694,-0.307015,0.573937,-0.035890,-0.182780,-0.206357,0.188376,0.024333,-0.023030,0.569166,0.315002,0.378286,0.089367,-0.224433,-0.811880,0.360724', '1307146', '3158990', '3811356', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307697', '芝加哥', '喜剧', '两个女人，有着相似的经历，甚至是相似的心计，展开了为求成名的争夺战。维尔玛（凯瑟琳•泽塔-琼斯 Catherine Zeta-Jones饰）是一个夜总会舞女，名气不大。因为一怒之下枪杀了出轨丈夫而被关进大牢。比利（理查德•基尔Richard Gere饰）是当地一个靠打谋杀案官司而提升知名度的律师，他受理了这桩案件，心中有着自己的打算。他借助媒体炒作维尔玛的案子，一方面维尔玛瞬间成为红人，而他自己也声名大振。然而洛克茜（芮妮·齐薇格 Renée Zellweger 饰）的案件却让比利转移了注意力。梦想成为歌星的洛克茜也是因为怒杀男友而身负罪名，比利决定要把她包装成楚楚可怜的受害者，令媒体更疯狂的大肆报道。维尔玛觉察形势不妙，为了成名，她跟洛克茜之间的斗法不可避免的开始了。©豆瓣', '泰雅·迪格斯', '罗伯·马歇尔', 8.9, 144009, 'tt0299658', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2454020352.jpg', 0.2, 0.7, 8.5, 35.7, 54.9, '0.419263,-0.125130,-0.536281,0.502318,0.065173,-0.146581,0.642300,0.301389,-0.465063,-0.127730,0.288426,0.771361,-0.428008,0.095963,0.223130,0.205836,-0.411231,-1.007913,0.337065,-0.071567,0.013891,-0.650403,-0.223749,-0.428972,-0.061583,-0.450752,0.336154,-0.006210,-0.280375,0.269828,0.636651,0.480791,0.200159,0.393108,0.318108,-0.064442,0.064384,-0.459576,0.033530,0.263408,-0.016827,-0.095590,-0.137024,0.429839,0.201255,0.501646,0.372430,-0.166060,0.088536,-0.147590,0.397035,-0.578965,0.000043,0.286293,0.134706,-0.219461,0.113709,0.131707,-0.303780,-0.246979,0.486161,-0.184373,-0.814148,0.488831,-0.000475,0.118979,-0.555061,0.167378,-0.404499,-0.013960,-0.036111,0.010082,-0.018456,0.229442,0.180280,0.058972,-0.039223,-0.097133,-0.511643,0.007433,0.725453,0.050986,0.009683,0.254942,-0.227221,-0.299389,-0.388057,-0.476543,-0.292332,-0.023585,0.515287,-0.234029,0.026417,0.542241,-0.612483,-0.325326,-0.585952,-0.175085,-0.080920,-0.253764,0.022262,-0.369774,-0.526179,-0.380568,-0.416951,-0.333250,0.064954,-0.295661,0.619536,-0.722472,-0.074747,0.615347,0.094545,-0.657485,0.380787,0.019473,0.142736,-0.008059,-0.227671,0.202449,0.241134,0.099437,0.102966,0.153680,0.082070,-0.273053,-0.150986,0.657210', '1307442', '4301278', '1293829', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307698', '父与子', '喜剧', '青年二子（陈佩斯 饰）赋闲在家，父亲老奎（陈强 饰）怕二子浪费光阴，于是每日第一件事就是督促二子复习功课，准备高考。老奎怕儿子出外乱窜，荒废学业，经常把他锁在房内复习。虽然父亲一番心意，无奈二子无心学习，在屋内如坐针毡。街坊老友顺子（刘佩琦 饰）想找二子和自己一起做生意，二子虽然十分乐意，但是父命难为，只得作罢。这日，顺子西装革履的出现在了大家面前，并带回了一大批新潮的服装和新款的计算器。二子见状，偷偷和顺子做起了生意……©豆瓣', '陈佩斯', '王秉林', 7.7, 7523, 'tt0350967', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2764577093.jpg', 0.3, 1.4, 30.3, 50.4, 17.6, '-0.090009,-0.031121,-0.706954,0.196062,-0.067193,-0.586460,0.142830,0.293174,-0.642204,-0.609891,-0.180762,0.570739,0.016734,0.518243,0.231971,-0.240514,-0.322515,-0.357014,-0.306456,0.234479,-0.076124,-0.056323,0.416806,-0.329850,-0.324686,-0.004188,-0.003621,0.027315,0.084807,0.366138,0.393487,0.063218,-0.232421,-0.087190,0.010600,-0.073831,-0.357988,0.189443,-0.150145,-0.346416,-0.096937,-0.146144,-0.388453,-0.307841,0.938196,0.278896,0.511704,0.045601,-0.130442,-0.042150,0.080409,0.076124,-0.144087,0.241711,0.090628,0.352374,0.558806,0.142605,-0.219540,-0.058752,-0.018282,-0.329161,-0.247529,0.312728,-0.134120,-0.099659,-0.701478,0.437844,-0.229098,-0.366546,-0.135318,-0.540915,-0.167000,0.204740,-0.102319,0.150674,-0.080120,0.134454,-0.207234,0.354107,0.222522,0.216992,0.399165,0.284389,0.316921,0.128156,0.170544,-0.283035,-0.150595,-0.300855,0.453824,0.135450,-0.115370,-0.030412,-0.226638,-0.109448,-0.074428,-0.119189,0.213534,-0.108472,-0.114393,-0.466281,0.385898,-0.392275,-0.512276,0.148194,0.549427,-0.175634,0.438609,-0.550609,0.074747,0.083703,-0.010931,-0.655337,0.380533,0.052810,0.294131,-0.238162,-0.168629,-0.514605,-0.169129,0.302173,0.523814,0.398423,-0.181664,-0.579769,-0.472552,0.113312', '1303485', '1304560', '1295316', '1855131');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307702', '和你在一起', '剧情', '普通百姓刘成（刘佩琦）为让从小拉小提琴的儿子刘小春（唐韵）的小提琴技艺有较大提升，带着他从江南来到北京，拜了性格怪异的江老师（王志文）为师，在学习过程中，刘小春逐渐与江老师成为忘年好友。风情万种的莉莉（陈红）与刘成父子俩住得很近，她让刘小春逐渐萌发生出莫名的爱恋。刘成偶然聆听过一位年轻人的精彩演奏后，登门拜访了其恩师余教授（陈凯歌），并说服对方收下刘小春为徒。刘小春怀着无奈与遗憾离开了江老师，投身余教授门下，却只收获了束缚与压抑，他开始怀疑“父亲的选择”，与父亲的关系越变越紧张。©豆瓣', '唐韵', '陈凯歌', 7.9, 44829, 'tt0332639', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2394990566.jpg', 0.5, 2.4, 23.5, 48.2, 25.3, '-0.076358,-0.078064,-0.538380,0.625467,-0.035733,-0.723767,0.697875,0.177196,-0.632792,-0.417781,-0.284566,0.412864,-0.414264,0.617541,0.271083,-0.353471,-0.264465,-0.392797,-0.044391,0.248033,-0.196447,-0.532904,0.181157,-0.417820,-0.463145,-0.057099,0.423629,0.189914,-0.439103,0.543725,0.291260,0.187740,-0.067443,0.704817,-0.044852,0.316593,0.061868,0.156480,-0.167895,-0.151507,0.524038,-0.332826,-0.207804,-0.095478,0.088311,0.157036,0.644267,0.218000,-0.177059,0.089978,0.201526,-0.095210,0.005613,-0.164119,0.120424,0.305323,-0.219348,-0.176707,-0.231090,0.095615,-0.115944,-0.219640,-0.368685,0.254433,0.284808,-0.102549,-0.723571,0.126602,0.142421,-0.041432,0.157109,-0.483925,-0.008580,0.265421,0.113172,0.378271,-0.222782,0.191042,-0.130583,0.310516,0.485051,0.050986,0.194760,-0.003108,-0.378120,-0.812752,0.241637,0.128522,-0.440427,0.108136,0.405511,0.235479,0.264746,0.157791,-0.340260,-0.513250,0.023794,0.332094,-0.025312,-0.500467,0.168301,-0.320527,0.017023,-0.533320,-0.284646,-0.423803,0.014936,-0.602297,0.846246,-0.833351,0.237069,-0.079975,0.139502,-0.341259,0.544946,0.038021,0.257828,-0.274274,-0.094072,0.159388,-0.248277,0.403009,0.714004,0.590003,-0.042249,0.070564,-0.035705,0.490392', '1292219', '1308228', '27135473', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307704', '至尊计状元才', '剧情', '在美国赌坛叱咤风云的至尊雷力（谭咏麟 饰）接受台湾赌王蔡山河（陈松勇 饰）的挑战，两个赌坛传奇准备在澳门展开风云对决。赴约途中，雷力先去香港探望多年未见的表妹，结果遭遇小老千莱斯利（陈百祥 饰）和大弟（刘德华 饰），二人合谋骗去雷力的钱财，并害其身陷囹圄。在得知雷力身份后，利欲熏心的他们更胆大包天冒充至尊前往澳门。另一方面，蔡的手下图谋不轨，私下招兵买马，欲借此机会除掉老大和雷力。毫不知情的莱斯利和大弟惹出一堆笑话。不久，雷力尾随而至。他将计就计，命令莱斯利二人继续演戏，相机而动。风云对决尚未开始，火药味早已四处弥漫……©豆瓣', '谭咏麟', '黄泰来', 6.5, 4839, 'tt0101011', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554468884.jpg', 1.9, 10.6, 56.7, 21.1, 9.6, '-0.006888,0.044025,-0.811344,0.396275,-0.018431,-0.079330,0.087600,0.407035,-0.457352,-0.387377,0.042034,0.568077,-0.163650,0.302297,0.245273,-0.449024,-0.187562,-0.585359,-0.011251,-0.029260,0.234067,-0.296119,-0.239946,-0.061811,-0.073853,-0.193231,0.383556,0.058499,-0.371024,0.573661,0.531961,0.179617,-0.473941,0.310055,-0.234970,-0.049823,0.034430,0.199092,-0.681735,0.435181,-0.072355,-0.366781,-0.144010,0.024636,-0.007517,0.252332,0.537846,-0.012216,0.446040,-0.136369,0.273275,-0.404314,0.099625,0.142818,0.410397,-0.057408,0.153099,0.149058,-0.053248,0.074834,0.025395,-0.166909,-0.509637,0.074575,0.084947,0.140649,-0.233327,0.027345,-0.120558,0.045496,-0.082964,-0.189646,0.181829,0.509516,0.031066,-0.197704,-0.091573,-0.060029,-0.552706,0.094393,0.729931,0.195532,0.423819,-0.024445,0.503099,-0.113547,-0.004719,-0.298054,-0.147199,-0.229997,0.546404,-0.014032,0.422782,0.152694,-0.496345,-0.292375,-0.084186,0.174438,-0.041504,-0.056820,0.308672,-0.800387,-0.344872,-0.197036,0.007909,0.011479,0.253814,0.003516,0.359228,-0.413505,0.121931,0.189790,0.369237,-0.740842,0.405745,0.183200,0.052336,-0.217305,-0.084605,-0.230038,0.453934,0.204281,0.115589,0.196088,-0.073881,-0.068853,-0.067173,-0.054438', '35287558', '3871833', '4193254', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307706', '恋爱行星', '剧情', '热爱音乐的高风（谢霆锋 饰）理想是当一名音乐家，年幼时父亲离世，因为过度伤心而大病一场，康复后便就此失去了听觉。他一下子变得孤僻起来。后来他邂逅了喜欢跳舞的陈静（林嘉欣 饰），陈静性格开朗，对生活充满了憧憬。但好景不长，陈静因为车祸死去了。但七天后她就要参加一场舞蹈比赛的决赛，她希望可以借高风的身体让自己的灵魂寄居，让她可以参加比赛，高风答应了、高风也因为把身体借给了陈静，再次听到了音乐，却不肯弹奏音乐。鬼差要把陈静带走，高风誓死挽回。决赛当晚，静出场跳舞时由于体力不支倒下了，高风决定为她弹奏曲目……©豆瓣', '谢霆锋', '林超贤', 6.9, 6612, 'tt0348214', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187311264.jpg', 1.6, 7.9, 45.5, 31.9, 13.1, '-0.079027,0.340279,-0.466123,0.341711,-0.169671,-0.643119,0.708189,0.072467,-0.536099,-0.227399,0.081684,0.821468,-0.306847,0.355736,0.101024,-0.192642,-0.085696,-0.814734,-0.045959,0.284338,-0.219951,-0.137201,0.441583,-0.103802,-0.262997,-0.393564,0.667198,0.128775,-0.272974,0.849249,0.269745,-0.169651,0.525456,0.391854,0.071383,-0.166350,-0.178971,0.153939,-0.128401,0.309317,0.317062,-0.354106,-0.322407,0.387394,0.036024,0.174821,0.696558,0.050329,-0.094839,-0.243196,0.426705,-0.326244,0.028036,0.108738,0.010663,0.231395,0.303346,0.084700,-0.338310,0.041356,-0.166542,0.010858,-0.448210,0.472517,-0.100834,0.004908,-0.449880,0.520901,-0.100793,0.051455,0.103902,-0.131265,0.265929,0.334056,0.427923,0.249593,-0.377019,-0.133248,-0.201891,0.438236,1.013192,-0.310601,-0.161353,0.631327,-0.162543,-0.684410,0.096905,-0.242573,-0.440250,0.251727,0.293046,0.173291,-0.288907,-0.031842,-0.265268,-0.243841,-0.195267,-0.344041,-0.223641,-0.348831,0.172030,-0.185419,-0.178553,-0.106187,-0.308846,-0.209537,-0.199651,-0.381821,0.743795,-1.014134,0.523903,0.607540,0.120635,-0.403486,0.283957,0.247422,0.092747,0.035463,0.368803,0.327043,-0.447100,0.063733,0.175405,0.376910,0.013156,0.025569,-0.667185,0.695202', '35030151', '1292219', '30345227', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307708', '马路天使', '剧情', '1930年代，小云、小红（周璇）姐妹被人骗到上海卖给琴师和妓院老鸨夫妇，小云被迫做了暗娼，小红年纪尚小，又天生有一副好嗓子，便随琴师去茶楼终日卖唱。姐妹两人住在贫民窟，在她们对面，住的分别是报贩老王和吹鼓手陈少平（赵丹）。因为闲来无事时陈少平常同小红对窗玩闹，两人渐生感情。小红卖唱时被流氓古成龙缠上，对方欲强霸她为妾，小红找陈少平商量对策，两人本想借助律师将正义伸张，不想律师双眼只认钱，无奈之下只得逃走，而这一过程中，老王对小云由怜生爱，可是小云却因自卑不敢正视。琴师偶知陈少平与小红下落，放风给古成龙，古成龙赶到小红住处时，屋里只有她和小云，两人生命危在旦夕。©豆瓣', '周璇', '袁牧之', 8.6, 26040, 'tt0183828', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194956092.jpg', 0.1, 0.6, 10.4, 48.2, 40.7, '0.326024,-0.098819,-0.512778,0.170782,-0.088417,-0.476647,0.610151,0.133421,-0.767277,-0.148579,-0.113642,0.524945,-0.168276,0.297797,0.095406,0.033406,-0.225029,-0.464336,-0.197265,0.082385,-0.021706,-0.254343,0.270244,-0.162773,-0.302313,0.110797,0.177022,-0.191592,-0.160932,0.435482,0.309683,0.095680,-0.454821,0.244024,-0.070006,0.264147,-0.065079,-0.118740,-0.247469,0.305495,0.168257,-0.082926,-0.369668,-0.104090,0.172404,0.159741,0.507323,-0.080641,0.084829,-0.236402,-0.036049,0.084889,-0.031965,0.065827,0.054292,-0.254973,0.472164,-0.156818,-0.222053,0.002673,0.063464,-0.046516,-0.148056,0.416685,0.170740,-0.146904,-0.620537,0.243435,-0.059461,-0.113269,0.200297,-0.382215,0.219718,0.033530,0.128814,0.326982,-0.163369,-0.130661,-0.471542,0.153073,0.624373,0.429704,0.448793,0.327087,-0.010396,-0.302150,0.042908,-0.207717,-0.305590,-0.173336,0.275161,0.125487,-0.294888,-0.241380,-0.343772,-0.190193,-0.031160,0.339444,0.005909,-0.370308,0.018645,-0.158413,-0.057294,-0.393618,-0.204632,0.034955,0.210374,-0.049124,0.492602,-0.659789,0.172143,0.213608,0.429558,-0.344231,0.800397,-0.108600,0.110993,-0.212462,0.051057,-0.168005,0.100194,0.338332,0.492654,0.112503,-0.158176,0.054701,-0.245548,0.052662', '1302384', '3055049', '2052978', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307724', '天涯海角', '剧情', '少女琳（陈慧琳）患有血癌，就在她迷失于生与死的边缘时，结识了成熟稳重的苏格兰船员阿德（王敏德），听过阿德所讲的关于他故乡天涯海角的故事后，琳感觉到一份莫名的缘分，然而突然间阿德消失，失落之际，琳碰到专门替人寻找失物的阿虫（金城武），聘请下他寻找阿德，经过阿虫的辛苦努力，琳与阿德终又见面，原来阿德准备回故乡定居。阿德走后，琳和阿虫一起做事时获得一种从没有过的充实和快乐，然而她的心里始终惦念着天涯海角，并决定在生命结束之前，一定要去那里一趟。©豆瓣', '金城武', '李志毅', 8, 10954, 'tt0117904', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2544056767.jpg', 0.3, 2.4, 23.6, 44.7, 28.9, '0.049378,0.095025,-0.963964,0.483102,-0.063588,-0.631155,0.538444,-0.221094,-0.252750,-0.271369,-0.174983,0.897486,-0.129891,0.489351,0.504632,0.105149,-0.634721,-0.554750,0.091062,-0.340774,-0.386233,-0.445185,0.151176,0.098385,-0.301893,-0.152613,0.472676,-0.005263,0.064798,0.757855,-0.097264,0.227018,-0.428068,0.647146,-0.008857,-0.023779,0.153386,0.205230,-0.340447,-0.038132,0.740004,0.101022,-0.311478,0.104328,0.238346,0.183560,0.450246,-0.251937,0.081998,0.264658,0.282477,0.128606,0.348043,-0.063008,-0.020193,0.008284,0.190490,0.074693,-0.416616,-0.133706,-0.059535,-0.148829,-0.441641,0.026657,0.180573,0.043623,-0.504435,0.194258,0.063804,0.164179,0.104230,-0.408916,0.388442,0.546739,0.261216,0.468544,-0.219844,0.036915,-0.242519,-0.204920,0.976484,-0.001026,-0.165096,0.234047,0.115705,-0.368870,0.174730,0.360025,-0.385023,-0.001071,0.122560,0.297885,-0.326267,0.011558,-0.627808,0.043937,-0.412754,0.131494,-0.042302,-0.234913,-0.234219,-0.394169,0.002328,-0.300706,-0.231490,0.171759,0.079169,-0.407363,0.466400,-0.820053,0.487329,0.584598,0.323868,-0.335020,0.484724,-0.208090,0.251434,-0.344282,-0.073057,0.678671,-0.056443,0.203425,0.261210,0.293997,-0.147710,0.068445,-0.610436,0.605833', '1299433', '34461680', '1303333', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307729', '大决战之平津战役', '剧情', '20世纪40年代末，古老的中华民族迎来了决定命运的重要时刻。国共两党的抗争进入攻坚阶段，辽沈战役和淮海战役后，蒋介石（赵恒多 饰）受到极大触动，意图撤回华北六十万国军进入淮海，构筑一条坚固的江淮防线。在此危急关头，毛泽东主席（古月 饰）在西柏坡发出指令，授意林彪（马绍信 饰）率领东北野战军秘密跨越长城，会同聂荣臻的华北野战军发起平津战役，分割傅作义（李定保 饰）军团以作各个歼灭。傅一面婉拒美国势力入住华北的请求，一面说服总统打消军队南撤的念头，顺利在华北取得空前的权力。谁知在此期间，解放军已悄悄完成对平津的包围。傅作义感到大势已去，决定通过身为共产党员的女儿冬菊（陈红梅 饰）与对手和谈。只是和平的果实来之不易，在此之前还要经受更多的考验……本片为中国共产党诞生七十周年纪念作品，是大决战三部曲的第三部。©豆瓣', '古月', '李俊', 8.7, 14217, 'tt0099340', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2523612693.jpg', 0.9, 0.9, 12.1, 31.9, 54.2, '-0.244558,0.206085,-0.798899,0.626918,0.200668,0.232890,0.078486,0.159399,-0.320293,0.060696,0.251828,0.467226,0.105685,-0.342989,0.270146,-0.421177,-0.189394,-0.672732,-0.036486,0.033354,0.049241,-0.434791,-0.378594,-0.195817,-0.005043,-0.194947,0.953977,0.660267,-0.443244,0.208337,0.380276,0.278017,-0.050083,0.407163,0.204164,-0.153277,0.031560,-0.300612,-0.715622,0.267162,-0.176531,-0.129156,-0.211339,0.193541,-0.041967,0.202959,0.411640,-0.414522,0.040164,-0.133698,0.196093,-0.382479,-0.149406,-0.041351,0.396301,0.338365,-0.101501,0.289562,-0.186789,0.310695,-0.231970,-0.370113,-0.406964,-0.346694,0.367030,0.014332,-0.518918,0.354294,-0.135984,0.675673,0.120336,-0.558697,-0.028135,0.918717,0.179790,0.165685,-0.195457,0.160824,-0.292474,0.169001,0.609116,-0.351594,-0.186393,-0.449748,-0.143973,-0.267873,0.149562,-0.323648,0.083843,-0.042467,-0.078301,-0.045811,0.506550,0.105542,-0.642619,-0.142777,-0.353074,-0.202935,0.349099,-0.281040,0.200675,-0.605177,-0.228969,-0.001824,-0.073322,0.390252,0.065809,-0.118744,0.729663,-0.621038,0.078256,-0.096059,0.402722,-0.397684,0.377614,0.626394,0.096433,-0.461116,0.412716,0.453659,-0.313142,0.351873,-0.090589,-0.101218,-0.323478,-0.363231,-0.244637,0.216413', '1424552', '1424551', '26852888', '1316511');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307739', '国产凌凌漆', '喜剧', '一代著名特工凌凌漆（周星驰 饰）长期被上级弃用，沦为卖肉摊主。一具价值连城的恐龙骨架被一个浑身盔甲的金枪客盗去，因为线索少任务危险，凌凌漆又被高层领导委以重任。 凌凌漆依循线索来到香港，与联络人香琴（袁咏仪 饰）碰头，不想香琴处心积虑找机会要将凌凌漆杀死，原来她的另一身份是金枪客派来的杀手，但经历过出生入死的战斗后，香琴与凌凌漆渐生出了真情。而此时，金枪客的真实身份也被曝光，发现自己掉进某个阴谋里的凌凌漆开始奋力与敌手较量。©豆瓣', '周星驰', '李力持', 8.4, 378546, 'tt0109962', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2585823759.jpg', 0.2, 1, 15.4, 44.9, 38.5, '0.159103,0.049929,-0.651653,0.343232,-0.133959,-0.077330,0.875059,-0.169048,-0.604996,-0.423542,0.199896,0.939297,-0.209580,-0.057708,0.100707,-0.129941,0.128204,-0.824952,0.064313,-0.325839,-0.334769,-0.208072,-0.256741,-0.097608,-0.063837,0.056796,0.551074,0.019609,-0.259049,0.464103,0.522181,0.375877,-0.250295,0.428753,-0.309885,-0.225961,0.120001,-0.137585,-0.122108,0.465335,0.096623,-0.257723,-0.123711,0.403166,-0.242858,0.359508,0.595013,-0.197899,-0.145643,-0.187779,0.179129,-0.193793,-0.027664,0.295309,0.436389,0.234159,0.187906,0.304123,-0.022430,0.228318,0.346199,-0.054284,-0.857691,0.029251,0.019053,0.226115,-0.664444,0.342688,-0.221490,-0.035036,-0.400824,-0.373530,0.620227,-0.023659,0.400448,-0.066777,-0.161870,0.007993,-0.650169,0.166402,0.667770,0.001905,0.056675,0.201872,0.225336,-0.309146,0.105686,-0.478950,0.018209,-0.071114,0.456008,0.125844,-0.260545,-0.003816,-0.845449,-0.069642,-0.491822,0.106694,-0.355401,-0.121432,-0.187108,-0.206649,-0.408226,-0.220559,-0.234230,0.279552,0.026152,-0.209202,0.540472,-0.720615,-0.057992,0.467290,0.271297,-0.625845,0.544739,0.033809,0.140407,-0.135086,-0.036888,0.071687,0.365673,0.311071,0.212547,0.158306,-0.203660,-0.380786,-0.340812,0.059809', '2988294', '1292584', '25828589', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307740', '千机变', '喜剧', 'Reeve（郑伊健饰）是一个僵尸猎人，每次出动前都要喝下药水变得半人半僵尸才能发挥功力。他的前搭档Lila（何超仪饰）因一次行动中丧生，由Gypsy（钟欣桐饰）来接替。她的到来令Reeve的妹妹Helen（蔡卓妍饰）很不满，两女更大打出手。僵尸王子Kazaf（陈冠希饰）与仆人Prada（黄秋生饰）靠父亲僵尸王寄来的血浆生活，他生性善良，从来不会伤害无辜。Helen邂逅了帅气的Kazaf。一天Kazaf被僵尸伯爵追杀受伤，Helen得知他的身份后，毅然帮他到医院偷血，还把他带回家。原来僵尸圣典《Day for Night》就在Kazaf手上。Reeve因一次行动后找不到解药，因此变成了僵尸，还差点杀掉了自己的妹妹，迫于无奈之下，Gypsy把心爱的Reeve杀掉，Helen也为着要救回落入僵尸伯爵手中的Kazaf，与Gypsy联手进攻。©豆瓣', '钟欣潼', '林超贤', 5.9, 92279, 'tt0351887', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1969877241.jpg', 4.9, 20.9, 53.1, 15.8, 5.3, '-0.112345,-0.084922,-0.422433,0.431662,-0.154282,-0.286348,0.725477,-0.076880,-0.264106,-0.202763,0.357124,0.613116,0.064300,0.151452,0.115035,-0.104130,0.080054,-0.604508,-0.212443,0.121488,-0.391228,-0.050382,-0.403885,-0.109241,-0.077730,-0.540977,0.484539,-0.037591,-0.054690,0.406367,0.354205,0.277497,-0.095552,0.406112,-0.104974,0.001177,-0.193236,-0.191477,0.067396,0.517363,0.292275,-0.400130,0.301078,0.259246,-0.037923,0.281617,0.817017,-0.283670,-0.045818,-0.560450,0.136268,-0.398589,0.011488,0.300582,0.377141,-0.107973,0.367035,0.173932,-0.244293,0.131436,0.164278,0.112425,-0.816510,0.110998,0.117250,0.041832,-0.851166,0.355937,-0.180025,0.211029,0.207745,-0.398086,0.252824,0.176040,0.323298,0.109889,-0.210547,-0.089670,-0.592322,0.078674,0.678762,-0.058131,0.155451,0.194747,0.074860,-0.365592,0.119061,-0.490619,-0.258418,0.239593,0.241823,0.215951,-0.143644,0.157797,-0.605472,-0.386747,-0.548052,0.186287,-0.009878,-0.213662,0.048243,-0.215778,0.043850,-0.073989,-0.239574,0.017975,0.139810,-0.278616,0.461558,-0.550359,0.134408,0.405412,0.544142,-0.360564,0.286886,0.072452,0.047990,0.052748,0.091509,0.044762,0.349588,0.233787,0.222856,0.168144,0.043588,-0.127715,-0.324224,0.319517', '21619567', '2032339', '2988294', '26857170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307741', '我的野蛮同学', '喜剧', '在一间教学素质低下的学校里，有一个不成文的传统：学生们凡是遇到了争执，都不能告诉老师家长，只能自己用拳头解决。石头（谢霆锋 饰）是最能打的一个同学，一次帮助富家子Edward（冯德伦 饰）解围，彼此成为朋友，二人也因此得罪了学校里的好战分子。阿凤（容祖儿 饰）一直暗恋既帅气学习有出色的Edward，而Edward认为学生最紧要是学习，会考时间逼近，Edward便义务帮助石头与阿凤补习。由于家境富有，Edward竟然在考试当天被绑架了，石头决心把他救回……©豆瓣', '谢霆锋', '王晶', 6.1, 8941, 'tt0295461', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1527663908.jpg', 3.4, 16.8, 56.3, 16.9, 6.6, '0.370044,-0.405569,-0.228892,0.524448,-0.421468,-0.125586,0.243317,0.023469,-0.309491,-0.460784,0.228658,0.490582,0.019472,0.359781,0.048098,-0.460295,0.137046,-0.661882,0.180128,-0.117048,-0.418170,-0.566882,-0.179893,-0.110545,-0.269418,-0.397118,0.416918,-0.099393,-0.238402,0.535951,0.312652,0.100225,0.107963,0.157876,-0.119637,-0.496575,0.196622,0.229179,-0.135599,0.136619,-0.031843,-0.103251,-0.033704,-0.079918,0.340974,0.419252,0.489770,0.166780,-0.136372,-0.049886,0.386794,-0.385296,-0.262661,0.211728,0.561864,0.084229,0.327842,0.419169,-0.170628,0.305426,0.037594,-0.219060,-0.522609,-0.075554,0.271619,-0.129043,-0.628938,0.602305,0.279158,-0.315949,-0.016480,-0.233001,0.230929,0.027852,0.131688,0.222286,-0.141316,0.031113,-0.303793,0.105340,0.787974,-0.280967,0.128591,0.075520,-0.254939,-0.256731,0.467471,-0.281579,-0.292662,0.204881,0.072997,-0.151061,-0.307228,-0.107993,-0.392748,-0.071200,-0.197102,-0.036413,0.227568,-0.612452,0.141368,-0.434956,0.122434,-0.121837,-0.474540,0.194274,-0.044739,-0.214304,1.249011,-1.021062,-0.225926,0.375947,0.429905,-0.592098,0.818978,0.276008,0.264854,-0.105505,0.035581,-0.186597,0.112918,0.055444,-0.278635,0.400431,-0.028949,-0.387885,-0.267325,0.273377', '25922902', '6963575', '35048413', '30159456');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307747', '情圣', '喜剧', '程胜（周星驰 饰）乃一游手好闲之徒，终日坑蒙拐骗，无恶不作。一日装瞎子行骗，遇遇女骗子（毛舜筠 饰）被追债的贵利工打手排骨（元华 饰）欺负，胜一时看不过眼出手相救，不料却被债务转嫁弄了自己一屁股债。另一方面。老江湖凌万蜂（午马 饰）同样欠下了贵利王（张耀扬饰）的债务，无力还清。他想办法找到自己的旧情人生萍姐（恬妞 饰）和妓女Apple（叶子楣 饰）合谋冒充一富户人家向一阔少诈骗。不料被骗的阔少正是胜所扮，他也想骗这一富户。阴差阳错的骗局，笑料百出……©豆瓣', '周星驰', '李力持', 7.6, 96878, 'tt0102737', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2233066980.jpg', 0.4, 3.1, 34.4, 41.9, 20.3, '0.136285,-0.226643,-0.400480,-0.014603,-0.292869,-0.442153,0.566731,0.157062,-0.355923,0.016285,0.158328,0.586941,-0.139376,-0.057038,0.097723,0.125111,0.135289,-0.327082,0.201678,-0.101944,0.152962,-0.177603,-0.143863,-0.019658,-0.264035,0.013175,0.065837,0.087997,-0.177392,0.307402,0.753575,0.007046,-0.033512,0.129901,0.041048,0.363605,-0.035750,0.005678,0.064839,0.004947,-0.243176,-0.625190,-0.157486,0.059841,-0.333671,0.649717,0.359669,0.048332,0.210798,-0.263103,0.076409,-0.354002,-0.272263,0.127920,-0.098538,-0.311801,0.304613,0.134605,-0.383513,-0.164515,0.685120,0.023317,-0.662332,-0.075316,0.035810,-0.254614,-0.551683,0.078461,-0.088890,0.108231,-0.367106,0.014481,-0.009315,0.110178,0.401594,0.115250,-0.163287,0.012868,-0.891858,0.694067,0.209021,0.042706,0.198789,0.472408,0.013869,-0.084390,0.348512,-0.546528,-0.328300,-0.222354,0.552758,-0.540194,-0.264122,-0.174017,-0.433601,-0.185178,-0.153572,0.466449,-0.252855,-0.229351,-0.258957,0.133995,-0.297679,-0.095489,-0.366998,0.184815,0.269019,-0.119975,0.251174,-0.550291,-0.272407,0.506862,0.302151,-0.528051,0.441641,0.273641,-0.260859,0.207692,-0.236756,-0.212389,0.415441,0.299130,0.567684,0.044054,0.101658,-0.522781,0.170019,-0.044748', '25926267', '1293908', '10527288', '1298667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307748', '神秘河', '剧情', '吉米（西恩•潘 Sean Penn  饰）、戴夫（蒂姆•罗宾斯 Tim Robbins 饰）和西恩（凯文•贝肯 Kevin Bacon 饰）是儿时最要好的玩伴。戴夫10岁那年的一桩事件却改变了单纯美好的童年和友谊。尚且年幼的戴夫被歹徒绑架，对他施以性虐待，这个羞辱的经历从此改变了戴夫的人生。他变得与别人越来越疏离，三人的友谊在慢慢消融。三人各奔东西，却因为吉米的女儿遭杀害而重新有了联系。因为负责这个案件的，碰巧是西恩，此时他已是一名警探，面对好友女儿的被害，心急要找出真凶，却意外发现所有证据的矛头都指向了那个曾经亲密无间的伙伴——戴夫。关系变得剑拔弩张，而过去的友谊，如今的对立，都在拉扯着每个当事人的心。©豆瓣', '西恩·潘', '克林特·伊斯特伍德', 7.9, 68794, 'tt0327056', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p852967070.jpg', 0.6, 2, 22.1, 53.1, 22.3, '0.462660,-0.209465,-0.683482,0.537629,-0.040948,-0.546342,1.307063,0.091555,-0.406840,-0.290083,0.075411,0.732070,-0.247902,0.316013,0.354528,-0.111756,-0.200244,-0.945167,0.097709,-0.037904,-0.170158,-0.580175,-0.279194,-0.237529,-0.043629,-0.261452,0.609263,-0.008197,-0.144707,0.629438,0.486384,0.224302,-0.022360,0.397521,-0.081876,0.279739,0.070305,0.040933,-0.418520,-0.197629,-0.024714,-0.196286,-0.117814,0.400974,-0.165905,0.777651,0.724977,-0.126494,-0.425421,0.021790,0.389628,-0.272466,0.017512,0.262604,0.372039,0.004652,-0.060621,0.292935,-0.197949,-0.312040,0.019091,0.091597,-0.843404,0.088544,0.198297,0.284574,-0.565874,0.447953,-0.044085,-0.014956,-0.025604,-0.258942,0.280872,0.599500,0.118570,0.415503,-0.255504,-0.178008,-0.479463,0.053505,0.914228,-0.112430,-0.307631,0.490221,-0.395785,-0.253489,-0.129366,-0.169191,-0.569500,0.004201,0.505725,-0.080781,-0.152866,0.660367,-0.561713,-0.185668,-0.232042,0.089291,0.018720,-0.649524,0.128660,-0.306515,-0.442395,-0.632606,-0.549769,0.068776,-0.149790,-0.345160,0.721028,-0.777909,0.168335,0.462971,0.223713,-0.521100,0.424192,0.475367,0.175385,-0.260980,-0.195294,0.445391,0.213426,0.101642,0.094785,0.272542,0.110111,0.111652,-0.384002,0.426234', '25911595', '2131640', '25828589', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307749', '怒海争锋', '剧情', '1805年，拿破仑在欧陆纵横，而海战方面，只有英国舰队可以与之匹敌。英军杰克（Russell Crowe 饰）船长与自己的军舰惊奇号受命拦截法方军舰地狱号进入南太平洋，两舰在巴西北海岸初次相遇，地狱号凭借优势火力与厚甲将惊奇号击败，杰克依靠浓雾天气勉强得脱。虽然初战不利，但曾经跟随纳尔逊将军的杰克对自己的军舰充满信心，拒绝返航并着手研究对手。不久两舰再次相遇，杰克使用诱饵战术扭转了局势，一路追踪到暴风雨肆虐的合恩角，杰克的执着引起好友船医斯蒂芬的反对，但是杰克拥有一支精英的团队，在种种不利之中，船员们将针对性的训练坚持了下来。斯蒂芬意外受伤让杰克停止追逐，暂留小岛休整，此行意外的为杰克提供了战斗灵感，很快地狱号再次出现，两舰终于迎来了宿命般的对决……本片获2004年奥斯卡最佳摄影奖、音效奖等十余项褒奖。©豆瓣', '罗素·克劳', '彼得·威尔', 7.9, 32538, 'tt0311113', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1341139321.jpg', 0.2, 2, 25.1, 48.8, 23.9, '-0.073750,0.059793,-0.624548,0.686228,0.238332,-0.093745,0.453065,-0.020607,-0.277004,-0.038713,0.414614,0.631408,0.059840,-0.252887,0.317630,-0.238724,-0.438120,-0.516824,0.048438,-0.040172,-0.270772,-0.512663,-0.347335,-0.248728,0.126862,-0.555282,0.803334,0.243099,-0.237508,0.759382,0.140675,0.271080,0.067765,0.652960,-0.111247,-0.291298,0.057155,-0.190863,-0.456239,0.501388,-0.355199,0.004261,-0.120921,0.220596,0.140140,0.231368,0.861470,-0.490747,-0.204239,0.086218,-0.030315,-0.322740,0.260616,-0.083839,0.513760,0.155607,-0.278703,0.015520,0.064684,0.234535,-0.259343,0.095926,-0.461728,0.120971,-0.166253,-0.273350,-0.374645,0.118324,-0.327266,0.207226,-0.135729,-0.109229,0.036631,0.478121,0.395084,0.178272,-0.299154,0.279063,-0.290723,0.060207,0.634337,-0.290032,-0.408017,0.071145,0.218146,-0.445149,-0.055032,-0.468578,-0.190804,-0.028813,0.431197,0.157771,0.158103,0.293141,-0.714036,0.145194,-0.436625,-0.404867,-0.232827,-0.334482,0.167083,-0.909669,-0.074088,-0.017224,-0.169699,0.165660,0.041787,-0.102849,0.615224,-0.588173,0.206267,0.598924,0.232294,-0.262555,0.516660,-0.007612,0.047287,-0.305709,0.115839,0.501586,0.032736,0.226688,0.099654,0.395677,0.039974,-0.045261,-0.229725,0.292998', '2159244', '20274039', '2369613', '26365262'