INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307755', '恋爱写真', '剧情', '诚人（松田龙平 饰）是一名在边缘挣扎的摄影师，有一天，他收到前女友静流（广末凉子 饰）的来信，信中说自己要在纽约开摄影展了。回忆的匣子打开了，三年前大学里两人的故事从一个美丽的橘子开始，两人的分裂却源于静流叫诚人教她摄影，原本只是单纯想融入诚人的世界的静流却显示出极高的天赋，迅速在摄影比赛中捧回新人奖，这让诚人心生嫉妒，进而提出分手，静流说会等他有一天成为一名专业的摄影师再和他见面。时光荏苒，两人未曾有过任何联系，可是同学会上竟传来静流早就在一年前死去的消息。诚人无法相信这是真的，他登上了飞往纽约的航班寻找静流……©豆瓣', '广末凉子', '堤幸彦', 7.6, 20216, 'tt0370425', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1397862677.jpg', 0.7, 4.4, 29.7, 42.3, 22.8, '0.140392,0.192408,-0.765929,0.454497,-0.050848,-0.389276,0.589956,-0.098179,-0.447271,-0.014244,0.089635,0.967590,-0.277652,0.179957,0.082196,0.136188,-0.271137,-0.776241,0.143740,-0.382909,-0.125312,-0.354775,-0.075802,0.074318,-0.032892,-0.302379,0.711186,-0.066013,-0.232810,0.510600,0.012789,0.060928,-0.026579,0.422793,-0.423460,0.038721,0.139564,0.299235,-0.171816,0.320839,0.143336,-0.333190,-0.239016,0.079131,0.085685,0.340903,0.543646,0.026408,-0.312828,0.339010,0.430033,-0.175281,-0.307002,-0.004722,0.384146,0.232841,0.081110,0.250016,-0.282378,-0.096747,-0.066063,0.082722,-0.515946,0.075104,-0.188017,0.314152,-0.421560,0.501069,-0.080554,-0.158623,0.145575,-0.364418,0.285579,0.375858,-0.057244,0.159475,-0.190254,0.055074,-0.225113,0.269481,0.630834,-0.053982,-0.103052,0.590234,-0.149088,-0.409390,-0.172217,0.114095,-0.289658,-0.006019,0.222339,-0.003068,-0.177342,-0.070951,-0.589292,0.057775,-0.149011,-0.078724,0.140338,-0.330061,-0.307263,-0.445608,-0.033776,-0.292000,-0.426647,-0.017961,0.158886,-0.323556,0.845880,-1.015617,0.274862,0.425929,0.356150,-0.317542,0.698799,0.265828,-0.133992,-0.109943,0.279376,0.137003,-0.353397,0.427990,-0.024107,0.358267,0.119629,-0.208206,-0.687474,0.208551', '1292219', '1915403', '1292720', '1395231');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307762', '赤裸特工', '剧情', '本片是程小东于2002年导演的香港动作惊悚片，该片当年在香港上映第一周就获得了价值70000多美元的票房。Madame M集团在世界各地专门诱拐十二、三貌美少女，将她们软禁在荒岛上进行地狱式的特训，钻研各类型的战斗知识及暗杀技巧。从小训练她们成为既出色又性感的特工。通过六年非生即死的选拔最后只剩下三名非常出色的杀手Charlene（Maggie Q 饰）、Katt（安雅 饰）及Jing。CIA专案小组指挥Jack（吴彦祖 饰）一直致力捣破Madame M的杀人集团，在香港举行的一场龙舟竞渡中偶遇Charlene，两个大大出手，但在了解Charlene和进一步相处后这对兵贼渐渐互生情愫。Madame M拉拢日本赤军龙三郎（连凯 饰）合作更大的非法勾当。改邪归正的Charlene和Jack一起手刃敌人后在同一座庙里求到了同一只签……©豆瓣', '李美琪', '程小东', 6.4, 90441, 'tt0341495', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1037604601.jpg', 2.4, 13.1, 53.9, 23.9, 6.8, '-0.065006,-0.050640,-0.626231,0.682266,0.116955,-0.061401,0.231302,0.000056,-0.331400,-0.232018,0.303815,0.618872,-0.221127,0.024080,0.154240,-0.347912,-0.139095,-0.779245,-0.282488,-0.267773,-0.157571,-0.348612,-0.338474,-0.072061,-0.074319,-0.218533,0.743038,0.059160,-0.142303,0.560285,0.349083,0.201496,-0.255517,-0.027877,-0.176978,-0.306716,0.251228,0.020495,-0.431622,0.338333,-0.229173,-0.265527,-0.072101,-0.318991,0.148060,0.276006,0.636240,-0.217849,-0.089530,-0.166621,0.329479,-0.208897,-0.300573,0.061325,0.567432,0.103723,0.312979,0.311548,-0.316321,0.122713,-0.170222,-0.211367,-0.819351,-0.018839,0.225094,-0.037257,-0.621467,0.441791,0.026577,0.114737,-0.030922,-0.137783,0.020396,0.490135,0.191334,0.228882,-0.025130,0.092433,-0.531037,0.364389,0.688109,-0.074230,-0.075169,0.130917,0.238467,-0.455144,-0.129412,-0.496094,0.091120,-0.038404,0.149413,-0.218277,0.033087,0.114326,-0.787998,0.070339,-0.044776,-0.056046,0.073287,-0.350943,0.220835,-1.031970,-0.181888,-0.516285,-0.316978,0.117038,0.345077,-0.336030,0.807661,-0.856073,0.071444,0.452123,0.290880,-0.632837,0.626421,0.163626,0.215757,-0.100524,-0.237195,0.018618,0.102032,0.055962,0.066533,0.509004,-0.079210,-0.143467,-0.329576,0.235127', '2369613', '4301278', '3811356', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307766', '那山那人那狗', '剧情', '儿子（刘烨）高考落榜不得已回到大山中的家后，做了大半辈子山村邮递员的父亲（滕汝骏）提前退休，安排儿子接下自己的工作。儿子上班第一天，父亲千叮咛万嘱咐之后仍不放心，带上长年在其左右的忠实老狗决定陪儿子再走一趟送信之旅。起初，父子两人因为长期隔膜只默默走路，渐渐地，通过与不同村民尤其一个漂亮女孩（陈好）的接触，两人渐渐打开话匣，对彼此有了深一层的认识和了解。秀美如画的风景中，儿子慢慢明白了父亲工作的辛苦和意义，父亲也渐渐体会到他二十几年来对家庭的亏欠。©豆瓣', '滕汝骏', '霍建起', 8.7, 113916, 'tt0210916', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p798810224.jpg', 0.1, 0.5, 9.5, 42.7, 47.2, '0.160810,-0.251048,-0.576128,0.467683,-0.237618,-0.460641,0.369177,0.147315,-0.688761,-0.271741,0.067756,0.909353,0.001683,0.480063,0.263417,-0.218276,-0.398705,-0.574139,-0.014132,-0.370276,-0.284415,-0.509010,0.062704,-0.044894,-0.132773,-0.115084,0.414049,0.001864,0.148669,0.521605,-0.069586,-0.227342,-0.188902,0.455757,-0.149873,0.168181,-0.128007,0.175647,-0.388430,0.025470,0.325224,-0.021761,-0.206621,-0.076490,0.356009,0.343291,0.730928,-0.084147,-0.419346,-0.033317,0.206674,-0.035952,-0.148517,0.112555,0.230086,0.243871,0.353048,0.440118,-0.325983,-0.146940,-0.323014,-0.151674,-0.229069,-0.024911,0.153979,-0.108046,-0.808524,0.467448,0.147579,-0.378786,0.129918,-0.575258,0.354017,0.485520,-0.077463,0.642073,-0.331085,0.125874,-0.073242,0.168333,0.793955,-0.007947,0.033514,0.371415,-0.154325,-0.019163,0.147038,-0.175741,-0.396340,-0.072277,0.102115,0.328542,-0.359549,0.014715,-0.376221,-0.072482,-0.068552,-0.189154,0.108881,-0.731735,0.103651,-0.202377,-0.309991,-0.576412,-0.147193,0.198197,-0.147536,-0.385303,0.521769,-0.621139,0.317098,0.259296,0.385148,-0.598735,0.820539,0.032264,0.274843,-0.439879,0.223447,0.063767,-0.081216,0.285987,0.332340,0.240652,-0.217126,0.073670,-0.241243,0.127331', '2080130', '35048413', '2990737', '1300202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307775', '蜀山：新蜀山剑侠', '剧情', '五胡乱华时代，西蜀兵探子狄明奇（元彪 饰）幸得南海派丁引（郑少秋 饰）相救才没误入魔教，见丁引武艺高强，他大力劝其挺身而出救助天上苍生，并想拜其为师，遭丁引拒绝。丁引师弟昆仑派掌门人晓如（刘松仁 饰）在与魔教护法的打斗中被血魔附身，丁引决定带他到瑶池仙堡疗伤。因丁引是能让堡中冰焰 不灭的有缘人，正在闭关修行的堡主（林青霞 饰）出关救下晓如。而丁引不慎被血魔所伤后，堡主却因救晓如耗尽元气无力救助，只能将冰镜打破，冻住血魔，但众人也皆被冰封住，仅有狄明奇、晓如徒弟一真（孟海 饰）与仙堡女弟子（李赛凤 饰）逃脱。为普救天下苍生，三人决定到天刀峰寻找李亦奇女侠（翁倩玉 饰）与紫青双剑。©豆瓣', '郑少秋', '徐克', 7.1, 22310, 'tt0086308', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2190736863.jpg', 1.1, 5.9, 44.1, 36.3, 12.6, '-0.314583,0.045457,-0.262996,0.306330,0.096913,-0.181306,0.256143,0.082230,-0.487946,-0.288056,0.340782,0.524853,-0.066650,-0.000739,0.056184,-0.009161,0.328811,-0.446767,-0.181013,-0.022127,-0.186028,0.094825,-0.108540,0.198495,-0.397192,-0.523932,0.661744,0.247523,-0.146472,0.168090,0.154919,0.344841,-0.499917,0.351907,-0.238498,0.013959,-0.352471,-0.029072,-0.201305,0.323061,-0.254162,-0.350158,-0.239022,0.304616,-0.272564,0.500909,0.260399,-0.320630,0.016062,-0.302399,-0.265177,-0.331046,0.118850,0.161342,0.179471,-0.005174,0.362483,0.317901,-0.194962,-0.012402,0.008094,-0.016751,-0.515799,0.138644,0.522499,0.127167,-0.375450,0.356255,-0.200970,0.024672,-0.267940,-0.425082,-0.048132,0.184636,0.175888,0.010852,-0.209658,-0.470510,-0.445794,0.209827,0.382496,-0.349665,0.263430,0.172132,0.430242,-0.258598,0.190403,-0.395090,0.084806,0.009354,0.358198,0.220972,0.200120,0.196870,-0.338095,-0.393271,-0.409324,0.153875,-0.295743,-0.081993,0.135438,-0.255743,-0.117306,0.097090,-0.139907,-0.039257,0.452358,-0.003932,0.626165,-0.795645,0.198314,0.037349,0.187264,-0.489758,0.555615,-0.139474,0.004364,-0.134762,-0.105587,0.280286,0.282447,0.566400,0.261776,0.143982,-0.039058,0.023991,-0.373698,-0.374076', '35030151', '24875409', '3445516', '2153579');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307781', '大城小事', '剧情', '周谦（黎明 饰）是一名出诊医生，行事谨小慎微；小月（王菲 饰）在家公关公司作主理人，生活和工作一样特立独行，他们曾是一对相爱的情侣。小月接手一笔大生意，为即将八十岁的富商孟仕存筹办一场惊喜寿宴。小月为此竭尽全力，倾其所有投入到当前的计划之中，然而却在一次接洽过程中意外遭遇周谦。周谦是孟先生的私人看护，他从孟老的身体状况考虑认为小月的安排欠妥，小月认定是周谦从中作梗。孟老的助手马时法（陈建斌 饰）要求小月在一个月的时间内修改计划，而且递给他周谦的名片，让两个人沟通避免新的计划中出现错误。由相濡以沫到水火不容，如今又要变成合作者，两人能否再续前缘谱出美丽城市中一段新鲜的浪漫恋曲？本片由黎明主演并担任监制。©豆瓣', '王菲', '叶伟信', 6.3, 29556, 'tt0386590', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1326135380.jpg', 2, 13.4, 57.3, 21.3, 6, '-0.079838,0.149384,-0.375371,0.385939,-0.279275,-0.163429,0.421467,0.051096,-0.545407,-0.384599,0.324707,0.497753,-0.164854,0.142879,0.457447,-0.129932,-0.096513,-0.634641,0.032178,-0.123505,-0.120468,-0.522668,-0.157028,-0.264676,-0.226727,-0.230790,0.458904,0.163769,-0.054591,0.330157,0.319297,-0.021528,-0.376023,0.174066,0.122619,-0.226982,0.078616,0.124191,-0.648747,0.134700,-0.106393,-0.023348,-0.220573,0.054172,0.267855,0.462141,0.605601,-0.058375,-0.387328,-0.016014,0.500223,-0.114511,0.007606,-0.083678,0.318032,0.327672,0.202244,0.301734,-0.513356,0.028566,-0.305628,-0.340467,-0.703971,0.103885,0.134344,0.196641,-0.575459,0.267339,-0.006592,-0.029390,0.016749,-0.370932,0.106398,0.472907,0.474520,0.430618,-0.030770,0.133057,-0.074577,0.344394,0.705243,0.013559,-0.070373,0.410578,-0.175279,-0.212391,0.065716,-0.117055,-0.396581,0.150211,-0.058781,-0.150931,0.050768,0.166386,-0.315720,0.041299,-0.294236,-0.095296,0.177061,-0.268273,0.084256,-0.702662,-0.072266,-0.198956,-0.239299,0.118098,0.238278,-0.391100,0.568560,-0.592323,-0.026119,0.281197,0.128926,-0.527768,0.643364,0.304784,0.292785,-0.510023,0.107222,-0.150994,-0.138024,-0.136822,-0.069048,0.010654,0.115747,-0.166428,-0.423931,0.013670', '4301278', '26678784', '10876425', '1308424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307790', '没有过去的男人', '剧情', '这个男人M（马库·佩尔托拉 Markku Peltola饰）是一个失忆的流浪汉，没有名字，亦没有过去。因为失忆，他无法拥有合理的身份证明，无法找到住处和工作。一个精明的治安员把废弃的集装箱出租给流浪人士作为居所，收取租金，男人也住了进去。在这里，各种同样苦难却心地善良 的人们，为男人的生活投射进来一缕温暖的阳光。男人更是得到了救助站姑娘厄玛（卡蒂·奥廷宁 Kati Outinen饰）的热心帮助，两人的爱情也在苦难的日子中悄然萌芽。男人似乎可以重新开始生活，却意外牵涉进一桩银行劫案。警察的追查不但让男人陷入了麻烦的境地，还让他得知自己的身世，以及自己曾经拥有的家庭。男人找到自己的妻子，却不知如何在本来已经消逝的过去和眼前的现实之间做出抉择。©豆瓣', '马库·佩尔托拉', '阿基·考里斯马基', 8.5, 16868, 'tt0311519', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2607313031.jpg', 0.2, 0.7, 11.1, 49.2, 38.7, '0.395092,0.170341,-0.658592,0.543493,-0.593201,-0.317924,1.053001,0.015809,-0.611495,-0.328530,0.255383,0.615164,0.160368,0.180858,0.284093,0.282513,-0.382212,-0.706236,0.085963,-0.205902,-0.386249,-0.446332,-0.385563,-0.253665,-0.169314,-0.155126,0.799332,0.210543,-0.019800,0.063084,0.142872,0.299461,-0.118840,0.709008,-0.402162,0.043469,-0.084291,0.108285,-0.325616,0.171277,-0.007754,-0.330375,-0.151430,0.212749,-0.100773,0.308604,0.678053,-0.266067,-0.373485,0.085189,0.368228,-0.082443,-0.069590,0.024979,0.157943,-0.107372,0.357365,0.032299,-0.275449,-0.079361,0.200750,0.070895,-0.773610,-0.023149,0.184985,0.165279,-0.649155,0.352652,-0.058866,-0.137566,0.066888,-0.493530,0.119286,0.215977,0.280082,0.608652,-0.358509,0.059673,-0.683198,0.152404,0.646449,0.006138,-0.334320,0.415119,-0.527056,-0.447618,-0.103424,-0.195100,-0.524479,0.028818,0.257282,0.147859,-0.452219,0.359569,-0.396965,0.061350,-0.315339,-0.242505,0.041396,-0.543982,-0.239942,-0.287662,-0.261249,-0.159745,-0.456910,0.071591,0.158994,-0.232766,0.620870,-0.840596,0.153557,0.624383,0.366754,-0.515468,0.765210,0.051202,0.191729,-0.229556,-0.181697,0.269002,0.013724,0.462558,0.105507,0.273953,-0.093615,0.097135,-0.321056,0.445083', '1296370', '21619567', '1308755', '25917973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307793', '燕尾蝶', '剧情', '母亲死后，原本生活在被大量外国移民视为淘金天堂的“元都”少女被送到妓女固力果（卓娜）处，将少女暂时收留后，固力果依据纹在胸前的蝴蝶给她取名凤蝶（伊藤步）。不久，凤蝶在固力果的带领下于名为“青空”的废品安置区兼汽车修理站，结识了火飞鸿、狼朗等来自不同国家的“元盗”，并逐渐与他们熟识成为好友。一盘录有美国歌曲《My Way》并隐藏有制造伪钞磁性感应资料的磁带令众人一夜致富，而在发财后，他们也开始走上不同道路，其中有出色演唱天赋的固力果被唱片公司签下，并在公司逼迫下与大伙断了关系。而磁带的主人，黑社会老大刘梁魁（江口洋介）得知磁带下落后，开始派手下追杀火飞鸿、固力果等人，众人的命运开始相互牵制。©豆瓣', '恰拉', '岩井俊二', 8.7, 155115, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2563987203.jpg', 0.3, 1.1, 11.7, 37.6, 49.2, '0.289570,0.117244,-0.494428,0.424268,0.051767,0.015034,0.291225,0.354263,-0.519652,-0.038348,0.139659,0.667687,-0.056172,0.162553,0.153885,-0.050279,-0.238922,-0.731228,-0.018550,-0.247085,-0.244110,-0.383159,0.010016,-0.130342,-0.125847,-0.429967,0.708808,-0.013781,-0.150700,0.621655,0.161930,0.166468,-0.345633,0.238827,-0.306280,0.089419,0.073658,-0.046387,-0.325171,0.334523,-0.338250,-0.194646,0.022250,-0.075035,0.090537,0.272205,0.664732,-0.185184,0.025870,-0.093264,0.129712,-0.051029,-0.073684,-0.076483,0.365453,0.307544,0.207856,0.430834,-0.462214,0.114102,-0.112227,0.029973,-0.695646,0.051110,0.281677,0.159268,-0.494552,0.392167,0.080830,0.022626,-0.020549,-0.203734,0.213588,0.225768,0.161264,0.390013,-0.002825,0.151808,-0.410504,0.128342,0.596137,-0.173144,-0.103893,0.181132,0.098851,-0.287118,-0.101983,0.011254,0.050526,-0.105026,0.344928,0.342935,-0.017097,-0.019913,-0.782654,0.101236,-0.054909,-0.076585,0.210344,-0.497716,-0.182437,-0.776462,-0.203973,-0.188466,-0.105502,-0.011825,0.243936,-0.166457,0.792143,-0.611151,0.170311,0.388168,0.399288,-0.459206,0.419272,-0.313337,0.182654,-0.189372,-0.164225,0.069008,0.216928,0.451312,0.163799,0.015661,-0.164010,0.026932,-0.271091,0.106186', '3811356', '26365262', '20274039', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307800', '铁男1：金属兽', '科幻', '一位普通白领青年（田口智朗饰）在地铁站被手上有着铁爪的神秘女人（叶冈伸饰）袭击追杀。一番打斗后返家，他在色情幻想中发现自己的身体竟正在钢铁化，下身变为巨大的钻头，拥有了极其可怕的力量，他的女友（藤原京饰）成为了变身的祭品，而他最终变为一个金属的怪物。这时来历不明的男子（冢本晋也饰）出现，原来他在青年造成的车祸中大难不死，并因此获得超能力，他的憎恨力量导致了以上所有事情的发生。一个由钢铁打造的躯体，一个神秘的超能力者，他们将展开可怕的对决。©豆瓣', '田口智朗', '冢本晋也', 7.2, 5894, 'tt0096251', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1967145707.jpg', 3.2, 8.5, 32.9, 34.9, 20.5, '0.240824,0.137763,-0.667010,0.577578,-0.341854,0.117827,1.316842,0.069766,-0.292339,-0.454657,0.690488,0.832060,-0.253101,0.178995,0.016248,-0.105550,0.385760,-0.729176,-0.142882,0.045159,-0.576802,-0.042570,-0.573663,-0.045284,0.037181,-0.548410,0.905914,0.059413,-0.271854,0.307747,0.248992,0.354321,-0.073896,0.453271,-0.227505,-0.138669,0.055664,0.067405,0.170488,0.370683,-0.288216,-0.364393,0.303464,0.518377,-0.734751,0.248605,0.955407,-0.429460,-0.095802,-0.332812,0.597854,-0.197535,-0.090595,0.165455,0.377141,0.335484,-0.013390,-0.180885,-0.147988,0.127548,0.335541,-0.033906,-0.871004,-0.262726,-0.028522,0.258735,-0.433111,0.358898,0.146046,-0.151292,0.050324,-0.314612,0.023081,0.074489,0.324808,0.304523,-0.346767,0.071512,-0.528964,0.027180,0.532997,-0.204117,-0.673517,0.339485,-0.210293,-0.499683,-0.379026,-0.364218,-0.207787,-0.181310,0.292178,0.288557,-0.124421,0.217764,-0.845801,-0.121640,-0.217724,0.072727,-0.284632,-0.025908,-0.397413,-0.526639,-0.229004,-0.400682,-0.240300,0.212872,0.006915,-0.268776,0.642599,-0.734592,0.151823,0.658813,0.315498,-0.292426,0.291561,-0.397952,0.135477,-0.087491,-0.233551,0.128314,0.183615,0.261550,0.138247,0.421963,-0.144612,0.087895,-0.388049,0.697802', '21619567', '1467779', '25884436', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307807', 'Office有鬼', '剧情', '这是一部关于办公室鬼故事的电影。新人阿Pat（莫文蔚 饰）刚来这栋大楼的一间公司上班，遇到了前男友阿Ken（冯德伦 饰）。两人聊了一会儿，随后阿Pat乘电梯回公司。电梯内一名只有白衣女子，她蹲在地上不停说“对不起”，阿Pat觉得十分诡异。同事说可能是鬼节将至造成…阿Pat在厕所发现隔壁公司的秘书Connie在不停和最后一格的人说话，当时没有留意。之后女厕内突然传来一声尖叫，当众人赶到时，Connie已经在厕所上吊自杀身亡，她的脸上还挂着一个奇怪的笑容。Ken在大堂也看到了白衣女子，身边还有一个红衣女子。红衣女子对他说，白衣女子是鬼，正在逼她跳楼…©豆瓣', '陈小春', '麦子善', 6.8, 41181, 'tt0339464', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2461323420.jpg', 1.1, 8, 51.2, 31.3, 8.4, '0.256078,0.152791,-0.814573,0.348664,0.017923,-0.499282,1.307086,0.419961,-0.038077,-0.458327,0.367858,0.379498,-0.392049,0.295399,0.203103,-0.040758,-0.293006,-0.495224,-0.337192,-0.570431,-0.533370,0.064301,0.286554,-0.041905,-0.110832,-0.234212,-0.045482,-0.025446,-0.218252,0.410858,0.532109,0.089129,-0.136738,0.721752,-0.298191,0.041987,0.201038,0.075863,0.182293,0.311465,0.208360,-0.378015,-0.258314,-0.246484,-0.086706,0.120226,0.546866,-0.080176,-0.170968,0.231768,0.296018,0.284616,0.035566,-0.111485,0.689716,-0.247273,0.210846,-0.110687,-0.233952,-0.044930,0.318329,0.015823,-0.143068,0.193461,-0.255841,0.525580,-0.542213,0.326165,-0.270089,0.187319,0.554110,-0.399139,0.277169,0.003811,0.266081,0.561295,0.056461,0.347482,-0.748357,0.160943,0.269486,0.298169,0.160892,0.621415,0.066873,-0.585498,-0.050739,0.565089,-0.248389,-0.151412,0.226510,-0.410873,0.078345,-0.488907,-0.032249,0.025413,0.217601,-0.096653,-0.194395,-0.311122,-0.415336,-0.636677,-0.147361,0.053013,-0.058998,0.393224,-0.356931,0.229462,0.448424,-0.634258,0.192662,0.530211,0.463798,-0.036107,0.940310,-0.085549,0.074923,0.007324,-0.048801,-0.118065,0.103719,0.555012,0.219731,0.725862,-0.329793,-0.000189,-0.371890,-0.038285', '20451118', '35073565', '1578663', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307811', '魔女宅急便', '动画', '琪琪今年13岁了，按照魔法界的规矩，魔法少女年满13岁就要出外进行为期一年的修行。所以琪琪带着宠物黑猫吉吉踏上了修行之旅。然而，修行之旅开始得并不顺利，当琪琪来到海边一座大城市时，人们并没有欢迎她的到来，人人都不搭理她。幸亏琪琪有一颗善良的心，当她拾到了一件别人的失物时，热心的琪琪找到了失主。她的善良赢得了面包店老板娘的好感，琪琪就在面包店开始了她用飞行魔法为客人服务的快递业务。琪琪很快适应了新环境，一次，一个热衷于飞机制造的男孩邀请琪琪去参加飞行俱乐部的聚会，途中琪琪因为帮一位老大娘送东西而被雨淋了。从此，琪琪突然发现自己的魔法正在一天天变弱。©豆瓣', '高山南', '宫崎骏', 8.7, 427211, 'tt0097814', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456676352.jpg', 0.1, 0.4, 10.3, 43.1, 46.1, '0.442043,0.063952,-0.491612,0.181628,-0.389053,-0.335332,0.249344,0.211985,-0.312617,-0.187916,0.261370,0.733643,-0.082101,0.317821,0.250372,0.314365,-0.282476,-0.320650,0.300799,-0.218529,-0.260065,-0.152555,0.130013,0.073575,0.026969,-0.394472,0.341615,-0.040864,-0.040426,0.558399,-0.244862,-0.259081,0.266013,0.510108,-0.239947,-0.118303,0.438502,0.067733,0.101528,0.505467,-0.022515,-0.074834,-0.102002,0.162935,0.060639,0.251955,0.746720,-0.138247,-0.261043,0.007360,0.394855,-0.130671,0.056240,0.042336,0.224483,0.062622,0.100967,-0.115315,-0.124394,0.369170,-0.004332,-0.348219,-0.435411,0.209729,-0.063914,0.011635,-0.477040,0.409966,-0.142146,0.029250,-0.012116,-0.640834,-0.060618,0.449363,-0.103187,0.398829,-0.219386,0.139150,-0.485707,0.163331,0.701598,-0.210113,-0.169466,0.757218,-0.169903,-0.364255,0.329435,-0.019678,-0.530361,-0.104863,0.316948,0.182532,-0.347791,0.055528,-0.918635,0.325617,-0.253890,-0.325529,0.171482,0.012523,-0.370168,-0.503408,0.090757,-0.255305,-0.184646,-0.197589,0.070033,-0.232324,0.863649,-1.033183,0.407102,0.774481,0.285346,-0.481084,0.811117,-0.112443,0.136717,-0.042651,-0.030398,-0.082883,-0.243681,0.840340,0.044568,0.384647,0.178217,-0.206243,-0.173336,0.367471', '1292219', '3044878', '4830911', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307812', '双旗镇刀客', '动作', '中国西部，黄沙漫天，马嘶人怒。自幼跟随父亲操练关西无极刀法的孩哥（高伟 饰）遵照父亲的遗嘱，来到双旗镇寻找指腹为婚的妻子好妹（赵玛娜 饰）。只叹人情冷暖，世态炎凉，好妹及其父亲瘸子（常江 饰）毫不待见这个男孩。婚期无望，孩哥只得暂时在瘸子的店里当小伙计。一日，土匪二爷意欲强暴好妹，结果为孩哥所杀。此举惹恼了长年盘踞双旗镇的土匪头子一刀仙（孙海英 饰）。由此惹得滚滚狂沙中刀光剑影，鲜血四溅……本片荣获1991年中国电影金鸡奖最佳美术奖、1992年东京第三届夕张国际惊险与科幻电影节最佳影片大奖、1992年第五届《中时晚报》电影奖商业映演类年度大陆优秀电影奖、1993年柏林电影节国际影评奖。©豆瓣', '高一玮', '何平', 8.3, 41593, 'tt0102917', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2553119558.jpg', 0.4, 1.2, 15, 48.9, 34.5, '-0.553538,-0.033724,-0.315729,0.342992,0.556425,-0.094408,-0.167229,0.130391,-0.455848,-0.128246,0.272806,0.663846,-0.141331,-0.034304,0.291076,-0.086920,0.083681,-0.612115,-0.169918,-0.144795,0.380816,0.039486,-0.164382,0.033066,-0.298824,-0.288567,0.619986,0.095615,-0.032600,0.496145,0.465731,0.164352,-0.264387,-0.226251,-0.132378,0.159278,0.195667,0.020157,-0.501013,0.130870,-0.269835,-0.255180,-0.415324,-0.147395,0.101315,-0.027660,0.546609,-0.085430,-0.021648,-0.297473,0.548726,-0.434178,-0.161627,-0.279223,0.415421,-0.265696,0.339650,0.333845,0.119178,-0.065386,-0.105627,-0.237483,-0.160547,0.107489,0.265243,-0.190904,-0.467738,0.417609,-0.246575,0.218164,-0.469961,0.019035,0.371587,0.022932,0.095360,0.162658,0.009067,0.178055,-0.214709,0.885778,0.415313,-0.106799,0.125631,0.064709,-0.068802,-0.101767,-0.025101,-0.507983,-0.240009,0.311512,0.377169,-0.231855,-0.117759,0.144610,-0.221706,-0.081087,-0.072907,0.077599,0.144972,0.062959,-0.214533,-0.337675,0.053981,0.040160,-0.035333,-0.342149,0.035962,0.226963,0.587086,-0.248062,0.243728,0.240792,0.063881,-0.115053,0.620477,0.121321,-0.112896,-0.040981,-0.109767,0.027788,0.010648,0.179130,-0.202243,0.101367,-0.084127,-0.562985,0.100781,0.142074', '1302279', '1388176', '1780122', '1297368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307821', '刺马', '剧情', '清朝乱世，草莽中人张汶祥（姜大卫）、黄纵（陈观泰）与马新贻（狄龙）不打不相识，结拜为异姓兄弟，马新贻被推为大哥，张汶祥做了三弟。马新贻的勃勃野心引来黄纵妻子米兰（井莉）的爱慕眼光，但因力求上进的雄心和道德观念的约束，马新贻没接受米兰的爱，到升任两江总督后，马新贻变得为达目的不择手段，并在道德和感情防线彻底崩溃的情形下占有了米兰，同时设计杀害了粗豪鲁莽一心向他的黄纵。张汶祥查出二哥的真实死因后，一改平日的跳脱灵动，郑重地约为女人舍弃好兄弟的马新贻出来清账。©豆瓣', '狄龙', '张彻', 7.7, 6397, 'tt0069881', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2333895141.jpg', 0.6, 2.3, 27.7, 48.1, 21.3, '0.057406,-0.004302,-0.610224,0.540999,-0.089793,-0.422437,0.342988,0.521586,-0.544379,-0.111707,0.056468,0.330134,0.065224,-0.053425,0.364940,-0.238091,-0.077523,-0.678545,-0.249469,-0.091199,0.043540,-0.533232,-0.004829,-0.071338,-0.293665,-0.250758,0.529063,0.038925,-0.128655,0.373967,0.378401,0.258432,0.252163,0.381964,0.093613,0.290275,-0.217631,-0.087631,-0.656910,-0.203056,-0.075210,-0.051279,-0.265891,0.083108,-0.234763,0.422752,0.563510,-0.153206,-0.157881,-0.385046,0.376868,-0.123588,0.175058,0.083955,0.076277,0.089780,-0.098651,0.376649,-0.051864,-0.008091,-0.131482,-0.065893,-0.896795,-0.082956,0.151400,-0.109016,-0.348954,0.473875,-0.333748,-0.170847,0.042971,-0.361755,-0.068322,0.139420,0.283364,0.216183,-0.176716,0.150454,-0.433861,0.049373,0.610574,0.122094,0.096699,0.045290,-0.089163,-0.258641,0.254875,-0.466054,-0.281748,-0.086770,0.232864,-0.014076,-0.017347,0.394282,-0.246499,-0.238818,-0.242337,0.265225,0.101545,-0.309905,-0.012978,0.023539,-0.245401,-0.448716,-0.103897,-0.236093,0.163195,-0.351043,0.540518,-0.696209,0.063773,0.245361,0.258385,-0.858975,0.470556,0.274585,0.017769,-0.188913,-0.097551,0.126402,0.288707,0.105073,0.144003,0.105858,-0.170207,-0.065286,-0.162357,0.219897', '26678784', '1293265', '1877596', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307836', '黑郁金香', '喜剧', '法国大革命时期，传奇侠客“黑郁金香”（阿兰·德隆饰）劫富济贫让贵族们日日惶恐不安。“黑郁金香”以蒙面示人，真实身份其实是吉尧姆伯爵，为民请命其实是为了一己私欲。警察局长设下圈套引他现身，混战中刺伤了他的左脸，留下一道疤痕，这就成了抓捕“黑郁金香”的有力证据，全城搜捕。为避免身份暴露，吉尧姆伯爵不得已找来自己的孪生弟弟朱利安（阿兰·德隆饰）顶替自己参加政治会议。朱利安不屑哥哥的所作所为，于是他以“黑郁金香”的名义挺身而出，跟随民众一起战斗。但在一次战斗中朱利安失手被抓，身处绝境。吉尧姆伯爵终于良心发现，舍命营救却也不幸被捕。就在马上要处决吉尧姆伯爵的生死关头，“黑郁金香”再次出现，谱写了正义之士的英雄神话。©豆瓣', '阿兰·德龙', '克里斯蒂昂-雅克', 7.8, 5785, 'tt0058692', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2431631340.jpg', 0.3, 1.3, 27.2, 51.1, 20.1, '0.033568,0.219797,-0.195054,0.380423,-0.242502,-0.192925,0.297969,0.097603,-0.309482,-0.315106,0.734090,0.690339,-0.008063,0.186084,0.217001,0.029387,-0.221154,-0.730200,-0.079123,-0.055343,-0.106758,-0.236833,-0.458001,-0.238898,-0.075153,-0.252008,0.560178,0.241879,-0.266224,0.263754,0.499622,0.479009,-0.075835,0.225275,-0.019269,-0.275946,0.118895,-0.308879,-0.329511,0.113216,-0.223507,-0.292332,-0.083829,0.197849,-0.032579,0.532361,0.215933,-0.414073,0.219413,-0.373099,0.315697,-0.543303,0.033918,0.288459,0.436588,-0.101928,0.119935,0.046167,0.043597,-0.092545,-0.072944,-0.099786,-0.766530,0.212485,0.073871,0.280289,-0.485497,0.345009,-0.311181,-0.183841,0.251380,-0.004613,0.155281,0.147263,0.333534,-0.163955,0.016626,0.106696,-0.380907,0.136458,0.564401,-0.101942,-0.096988,-0.207759,-0.174162,0.054363,0.485591,-0.399960,-0.096100,-0.132946,0.284271,-0.223884,0.166547,0.367497,-0.532881,-0.413576,-0.557814,0.061740,-0.024928,-0.211128,-0.109617,-0.223829,-0.275618,-0.038136,-0.123119,0.066184,0.093714,-0.099331,0.319027,-0.581765,0.104827,0.373933,0.223276,-0.590909,0.402793,0.252573,0.023398,-0.030306,-0.110752,0.183536,0.256031,0.191908,0.062170,-0.043275,0.157669,-0.288086,-0.304634,0.319763', '26678784', '4301278', '27073234', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307840', '菊花香', '剧情', '成浩（朴海日 饰）一直暗恋自己的学姐姬载（张真英 饰），可是当时姬载已经有了亲密爱人。但后来在一次意外中姬载同时失去了双亲与恋人。痛苦不已的姬载得到了成浩的百般照顾，终于成浩在苦等七年后与姬载结婚了。日子还算幸福，姬载更怀上了孩子。天意弄人的是此时姬载被诊断为胃癌。她本想独自面对疾病带来的痛苦，默默的离开成浩。深深爱着姬载的成浩却一直不离不弃，要陪伴爱妻走完最后的路。至于孩子，若姬载要生下孩子，便意味着缩短自己的寿命，而她义无反顾的要把孩子生下来……©豆瓣', '张真英', '이정욱', 7.3, 8701, 'tt0349517', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1172193151.jpg', 0.7, 4.6, 41.3, 37.9, 15.5, '-0.317289,-0.214506,-0.564618,0.419396,0.006126,-0.668684,0.640432,0.167155,-0.674963,-0.100848,0.116472,0.685513,-0.253865,0.519338,0.025444,0.083710,-0.217345,-0.634802,0.155059,-0.132542,-0.527604,-0.395076,0.072437,-0.126696,-0.136553,-0.242351,0.753367,-0.081306,0.406595,0.311437,0.254829,0.023117,0.063543,0.663162,-0.459102,0.250165,-0.141420,-0.036861,-0.276960,0.168352,0.516274,-0.329883,-0.270507,0.103051,-0.014460,0.208806,0.599644,-0.166813,-0.352105,-0.133967,0.268825,-0.254829,-0.097796,0.155560,-0.014170,-0.067578,0.489483,0.361408,-0.410565,0.009567,0.174583,-0.106882,-0.480465,0.061879,0.095671,0.002460,-0.854432,0.687005,-0.100866,-0.001612,0.406542,-0.309457,0.218785,0.505601,0.178534,0.564897,-0.883663,-0.078066,-0.275883,0.104807,0.849504,-0.162187,-0.031800,0.622660,-0.177029,-0.308770,0.041777,-0.307992,-0.622554,0.294644,0.173504,0.499992,-0.465477,0.250057,0.009297,-0.065194,-0.291146,0.008902,0.022186,-0.603794,-0.105296,0.075864,-0.069005,-0.361328,-0.378499,0.297634,-0.031984,-0.447250,0.785769,-0.675131,0.392688,0.329310,0.394589,-0.741727,0.711348,0.280222,0.107091,-0.250356,0.244214,0.478328,-0.465916,0.086058,0.417498,0.167625,-0.123823,0.201520,-0.395052,0.353836', '4861627', '25721544', '1296569', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307849', '老鼠爱上猫', '喜剧', '北宋年间，太平盛世令开封府渐成虚设，尾随包拯（黄秋生）的展昭（刘德华）因整日无所事事怀念起过去云游四海的侠义生活，幻想有天重新披上黑衣。某次化身做他人的行动中，展昭遇上锦毛鼠白玉堂（张柏芝），被其言行举止深深吸引。五鼠大闹开封府，夺去展昭与襄阳王之妹（李冰冰）的订婚信物，展昭奉皇命追至五鼠老窝陷空岛劝降，吸引了情窦初开的原本是女儿身的白玉堂，然而因展昭身负御赐婚约，两情没能相悦，可是他们的缘分并没到此终止。©豆瓣', '刘德华', '陈嘉上', 5.6, 58806, 'tt0366720', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2162213251.jpg', 5.2, 25.2, 57.2, 9.6, 2.9, '0.419192,0.309407,-0.370612,0.264686,-0.024052,-0.175827,0.472173,0.156951,-0.445323,-0.381498,0.353436,0.569715,-0.371155,0.221302,0.167184,0.022556,0.040309,-0.735088,-0.212469,-0.125699,0.182713,-0.031170,-0.033056,0.224181,-0.428240,0.042062,0.565598,0.196259,0.068613,0.704553,0.415596,0.185765,-0.626261,0.349678,-0.326159,0.133414,-0.347396,0.100447,-0.308875,0.135526,-0.137146,-0.353818,-0.352971,0.244257,-0.262301,0.327540,0.417777,-0.269588,-0.136431,-0.346467,0.540935,-0.060557,0.113553,0.069952,0.108259,0.295933,-0.187053,0.044850,-0.262842,-0.104498,-0.136486,0.179869,-0.021845,0.097215,0.152679,0.165682,-0.073664,0.240096,-0.031245,0.105846,-0.264078,-0.335528,0.043163,0.156806,0.374882,-0.117546,0.130588,0.058992,-0.578713,0.532164,0.658582,-0.194840,-0.003344,0.101117,0.223154,-0.135033,0.321205,-0.131675,-0.150269,-0.075413,0.168036,0.169884,0.147334,0.454034,-0.255361,0.013772,-0.318046,0.539148,-0.116520,-0.034379,-0.224424,-0.411688,-0.182663,-0.349400,-0.310149,-0.073013,0.337611,-0.170465,0.180098,-0.589673,-0.203795,0.460228,0.096498,-0.417598,0.474097,0.049761,0.216604,-0.048868,-0.011373,0.207619,0.158477,0.137396,0.335241,0.082419,-0.307154,0.038951,-0.644444,0.374832', '1773217', '1306021', '35256235', '1292506');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307853', '8英里', '剧情', '1995年冬天的底特律，每逢周末乐手们都会聚在一家名为The Shelter的Hip-Hop俱乐部进行一对一的为时一分钟的表演比赛，吉米•史密斯（艾米纳姆）是众多黑人乐手中另类的白，虽然他很有实力，却在每次上台表演时都会卡壳，只得到一片喝倒彩的嘲笑声。除了要勇敢面对被起哄的人群轰下台的尴尬，吉米•史密斯还要应付与母亲（金•贝辛格）及同母异父的妹妹一起生活在狭小局促的拖车里的难堪。而母亲的男友、黑人与白人的平行线关系、他的工作和感情等等，也皆是他的压力。他试图冲破家庭与团体的束缚，用音乐表达出对生活的愤怒和不满，然而他首先要解决的，是战胜怯弱的自己。©豆瓣', '埃米纳姆', '柯蒂斯·汉森', 8.3, 95445, 'tt0298203', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1055645725.jpg', 0.2, 1.3, 17.9, 44.7, 35.9, '0.246071,-0.093957,-0.525482,0.593106,-0.124056,-0.267401,0.785951,0.175579,-0.277433,-0.189428,0.028166,0.615064,-0.253022,0.389968,0.192574,-0.243382,-0.123231,-0.894297,-0.183315,0.118693,-0.204779,-0.507304,-0.142358,-0.505061,-0.168646,-0.387785,0.548391,0.009397,-0.393215,0.478759,0.489216,0.245428,0.125114,0.629346,-0.244469,-0.237190,-0.077713,0.133428,-0.280957,-0.134373,0.012307,-0.222720,-0.266515,0.258147,0.190133,0.455013,0.642503,-0.034019,-0.038759,0.209435,0.219408,-0.245895,0.037086,0.233616,0.294359,-0.193555,0.241639,0.140307,-0.083989,0.135054,-0.030439,-0.050238,-0.910470,0.258692,0.152211,0.141729,-0.608877,0.575401,0.140391,-0.054693,0.166203,-0.046129,0.172110,0.343018,0.135531,0.575112,-0.352890,-0.034709,-0.416886,0.086924,0.854522,0.161932,-0.170020,0.141313,-0.498432,-0.413894,-0.116261,-0.318920,-0.568141,-0.228573,0.203481,0.045373,-0.094742,0.146159,-0.759344,-0.026936,0.160553,-0.336111,-0.113368,-0.707888,0.018393,-0.768903,-0.019813,-0.588164,-0.309538,0.125743,0.157288,-0.318676,0.875615,-0.967682,0.083994,0.351015,0.358424,-0.365569,0.836563,0.344839,0.131745,-0.152474,-0.312816,0.034733,-0.059282,-0.034042,0.059576,0.481238,-0.031631,0.011032,-0.370796,0.633445', '4301278', '10876425', '4127270', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307856', '背靠背，脸对脸', '剧情', '王双立（牛振华 饰）是某地文化馆的代馆长，这个馆长一代就是好几年，想升也升不上去，却也没有其他变动。不料一天，来了新的文化馆长老马（雷恪生 饰），这让王双立离正馆长的距离更远了。新馆长老马原是个副乡长，王双立认为他是个土包子，心里很是不以为然，利用自己对文化馆人际关系熟 悉的优势，想方设法给老马出难题。经过几轮较量，老马终于被挤走，王双立又成了代馆长，再次受领导重用，岂料，螳螂捕蝉黄雀在后，秘书小阎（李强 饰）成了新一任馆长。王双立不甘心，再次和小阎斗法，想将对方挤走，这次王双立还能如愿与偿吗？电影《背靠背，脸对脸》获得第二届大学生电影节最佳故事片和最佳男主角奖、东京国际电影节最佳男主角奖、第15届金鸡奖最佳导演和最佳合作片奖、第14届香港电影金像奖十大华语片。©豆瓣', '牛振华', '黄建新', 9.5, 110935, 'tt0109235', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505048077.jpg', 0.1, 0.1, 2.1, 21.7, 76, '-0.109560,0.071477,-0.467784,0.545254,0.047856,-0.373050,0.281488,0.020572,-0.327659,-0.164256,0.015745,0.840494,-0.511135,-0.095149,0.149173,0.064173,-0.235247,-0.644555,-0.193244,-0.236764,-0.017308,-0.348672,-0.320256,0.374000,-0.224862,0.159002,0.514240,-0.251658,-0.231251,0.362143,0.786123,-0.088450,0.368758,0.072902,-0.338797,0.224106,0.256758,-0.274046,-0.157500,0.477120,0.244080,-0.259370,-0.234702,0.099876,0.275727,0.183959,0.454442,0.025525,-0.176779,0.075677,0.341010,-0.454296,-0.159898,0.082991,0.489650,-0.115936,0.317479,0.021769,-0.038631,0.252680,0.102317,-0.230448,-0.650372,0.391018,0.108631,0.113430,-0.437119,0.331891,0.134133,-0.112369,-0.044874,-0.107913,0.422895,0.296303,0.338853,0.101715,-0.099499,0.036990,-0.280907,0.433308,0.512465,0.204029,-0.120847,0.184541,0.182493,-0.567328,0.132960,-0.418052,-0.237482,-0.045322,0.404945,-0.080058,0.298680,-0.174361,-0.310871,0.044351,-0.175719,0.113771,-0.030145,-0.333575,0.380298,-0.374957,-0.257899,-0.258582,0.232525,-0.146615,0.112830,-0.454624,0.543680,-0.683215,0.265787,0.271790,0.206468,-0.431128,0.609595,0.460667,-0.029677,-0.355383,0.022305,-0.593534,-0.075783,0.512207,0.171621,0.453850,0.089982,-0.789910,0.037723,0.197894', '4301278', '1996313', '2997404', '1292626');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307862', '与龙共舞', '剧情', '龙家俊（刘德华饰）出身大富之家，事业有成，不仅是公司的董事长，还拥有数亿身价。只是感情方面一片空白，面对表妹（翁虹饰）的迷恋无动于衷，却对一个偶然在路上看到的女子月光（张敏饰）动了心。原来月光与老妈（叶德娴饰）在大屿山经营茶餐厅，老妈有时候靠打麻将出千赚点不义之财。无 独有偶，月光又碰巧进了龙家俊的公司，成了他公司的女员工。一次龙家俊和表妹游船河发生争执，被踢下海偶然混进偷渡客中，被警察追赶，误打误撞进了月光的家。他于是将计就计扮成大陆偷渡客在月光的小店里打起了工，而此时龙家俊的助手（吴孟达饰）正到处找他......©豆瓣', '刘德华', '王晶', 7.4, 19094, 'tt0103314', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167122954.jpg', 0.6, 3.6, 38.5, 40.7, 16.6, '0.371389,0.007219,-0.667142,0.399122,-0.357702,-0.436416,0.619284,0.358457,-0.476583,-0.174499,0.241043,0.686973,0.053651,0.445386,0.283813,0.175465,-0.110721,-0.485177,0.167830,-0.278828,-0.103677,-0.159787,-0.362222,0.065915,-0.271616,-0.108759,0.314495,0.174962,-0.175399,0.375099,0.406820,0.079885,-0.135759,0.280708,-0.360023,-0.131983,0.002050,0.160057,-0.168428,0.259105,-0.202544,-0.326354,-0.138303,-0.318989,0.210230,0.329881,0.698128,-0.048111,-0.063786,-0.063482,0.182345,-0.279995,-0.031617,-0.124272,0.493150,-0.030536,0.347844,-0.071239,-0.127661,-0.156742,0.203483,-0.069384,-0.524710,0.289628,0.158976,0.017561,-0.601957,0.306317,0.117272,-0.228248,-0.078340,-0.272110,0.156728,0.016412,0.004455,0.373851,-0.137994,0.088218,-0.756823,0.285494,0.341048,0.264615,0.086306,0.573856,-0.078766,-0.042635,0.288379,-0.090335,-0.292010,-0.006916,0.448122,-0.368851,-0.221963,-0.078899,-0.580114,0.241902,-0.170787,-0.048154,-0.190351,-0.418682,-0.211888,-0.553485,-0.141676,-0.273218,-0.045562,0.160261,0.295012,-0.030181,0.411655,-0.838682,-0.250801,0.429931,0.396502,-0.406406,0.775080,-0.252048,-0.170301,-0.019259,-0.121621,-0.209246,0.260886,0.290956,0.033639,0.341399,-0.152005,-0.075335,-0.245684,-0.025126', '3055049', '1302384', '2052978', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307868', '决战紫禁之巅', '喜剧', '大内密探龙龙九（张家辉）被“剑圣”叶孤城（刘德华）要求代约“剑神”西门吹雪（郑伊健）于九月十五日在紫禁之巅禁宫太和殿上比剑，决出谁是世上剑法第一人。“剑神”“剑圣”比剑一事一号，马上震动武林，江湖中人皆以此为赌资，一时赌风弥漫。朝廷为免滋生事端，派出龙龙九及御妹金燕子（赵薇）共同阻止此次比剑事宜。金燕子对叶孤城向来倾慕，行动中忘了目的。而龙龙九查得正有一股神秘力量在策划大阴谋，正等九月十五日这个时机。©豆瓣', '刘德华', '刘伟强', 5.9, 50849, 'tt0243876', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1316664618.jpg', 3.8, 21.2, 56.3, 14.4, 4.2, '-0.171608,0.241715,-0.513884,0.546079,0.034641,0.123753,-0.116262,-0.121664,-0.524677,-0.480520,0.376448,0.465818,-0.341132,-0.047680,0.378894,-0.181298,0.392766,-0.751200,-0.257616,-0.388948,0.084980,-0.215268,-0.045676,0.128086,-0.116495,-0.116440,0.299578,0.249347,-0.045393,0.334292,0.406774,0.115036,-0.387333,0.532355,0.276136,-0.440321,0.136483,-0.103384,-0.421207,0.382649,-0.336882,-0.514550,-0.461223,0.303196,-0.289895,0.462337,0.214458,-0.331511,0.115218,-0.421869,0.226012,-0.098466,-0.039157,0.134441,0.547965,-0.094980,0.102758,0.348553,0.119640,-0.002831,-0.186691,-0.272116,-0.336804,0.009259,0.284856,-0.068825,-0.019826,0.279432,-0.480741,-0.133693,-0.117956,-0.156448,0.052020,0.302752,0.310606,-0.240082,-0.043155,-0.313927,-0.172371,0.127726,0.502084,0.001741,0.219945,-0.041753,0.513219,-0.458128,-0.127734,-0.129555,-0.001768,-0.165115,0.468700,-0.125890,0.362559,0.393208,-0.189376,0.131796,0.086357,0.225337,-0.095395,0.097729,0.177691,-0.486236,-0.040031,-0.188924,0.131501,-0.036946,0.680567,-0.171553,0.358839,-0.692146,0.027257,0.192958,0.063489,-0.442163,0.227275,0.159986,0.107717,-0.002107,-0.298037,-0.269592,0.020411,0.257378,0.002317,0.305554,-0.027051,-0.249853,-0.262377,-0.003404', '25723905', '1307186', '1301022', '6041191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307873', '辣手回春', '喜剧', '8年前Yan进医院割盲肠时遇到了Joe（郑伊健 饰）与Jim（陈小春 饰）两位医生，都给她留下了深刻的印象，也是她决心成为医生的缘故，她更打算嫁给他们其中一个。当她进入他们所在的医院当医生的时候，发现Jim变成了一个市侩、没有责任心的医生，Joe更因为不满现今的医疗管制而不当医生了。Yan失望之余决定要把他们拉回原来的职位，继续做一个有责任感的医生，Yan的热诚确实使一众医护人员改变不少。©豆瓣', '郑伊健', '杜琪峰', 6.3, 9053, 'tt0250313', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513323926.jpg', 2.5, 13.9, 56.7, 20.4, 6.6, '0.302093,-0.056893,-0.440043,0.430940,-0.464357,-0.442515,0.867597,0.140683,-0.553955,-0.528330,0.054047,0.642168,0.275944,0.351983,0.149771,-0.113697,-0.222114,-0.501961,0.056340,-0.107080,-0.531859,-0.460382,-0.287081,-0.140141,-0.022203,-0.247600,0.348757,-0.101051,-0.256290,0.341372,0.270574,0.249246,0.448953,0.642402,-0.159506,0.102108,0.093641,-0.193056,-0.200724,0.214349,0.380854,-0.168217,-0.160605,0.206675,0.030168,0.577431,0.506582,0.088941,-0.545482,-0.211574,0.372933,-0.332225,-0.152142,0.132437,0.030852,0.270746,0.074617,0.231573,-0.245924,0.048977,0.079478,0.007025,-0.891627,0.085226,0.226477,0.201268,-0.763813,0.397894,-0.148968,-0.209047,-0.013626,-0.493764,0.394564,0.085403,-0.058629,0.404936,-0.322017,-0.024277,-0.548755,0.154227,0.822866,-0.152250,-0.033866,0.398545,-0.110291,-0.682896,0.364175,-0.032584,-0.358651,0.294597,0.084337,0.095726,-0.311774,-0.277673,-0.290064,-0.207508,-0.282550,-0.273010,-0.253548,-0.367226,0.285745,-0.230563,-0.015057,-0.230495,-0.423595,-0.041834,-0.030607,-0.020222,0.877107,-0.635646,0.151297,0.201667,0.406725,-1.014674,0.862963,0.155494,0.253996,-0.051800,0.005436,0.025135,-0.004355,0.425883,0.116572,0.422339,-0.018763,-0.473197,-0.275467,0.160726', '26678784', '1308206', '1877596', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307876', '一碌蔗', '剧情', '阿凡（余文乐饰）自小便没有了父母，为了生活与好友阿明（黄又南饰）在戏院门口卖蔗。一天他们看到在街头上大打狮鼓的阿蓝（蔡卓妍饰）。阿明对阿蓝一见钟情，决定与阿凡一起到阿蓝父亲（葛民辉饰）的武馆以学艺为名接近阿蓝，阿蓝却对阿凡有意，阿凡决定成全好朋友，渐渐与阿蓝生疏了。在一个丧礼上，阿凡遇到了一个从小在尼姑庵长大的女孩——“灭绝师太“（钟欣桐饰），阿凡被她的美貌深深吸引，每天都偷偷跟着她到山上去。女孩终于发现了他，并对他产生了情愫，想让阿凡带她走出尼姑庵，去看看那个多彩的世界，出走后，便从此消失于阿凡的身边。阿明利用老电影的剧本，得到了阿蓝的欢心，可是阿凡心里还是念念不忘他的“灭绝师太”。©豆瓣', '余文乐', '叶锦鸿', 6.8, 8242, 'tt0348448', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2358645284.jpg', 1.7, 10, 45.7, 30.5, 12.1, '0.247782,0.046872,-0.673044,0.625189,-0.188597,-0.574823,0.819752,0.076543,-0.450208,-0.121297,0.028904,0.887536,-0.256191,0.556878,0.160492,0.111568,-0.315527,-0.666960,-0.086938,-0.236976,-0.383391,-0.254413,-0.014758,-0.086298,-0.181969,0.009285,0.419235,-0.079380,-0.067517,0.692834,0.370299,0.001856,-0.118343,0.599901,-0.271509,0.272934,-0.075886,0.140070,-0.192018,0.103342,0.341791,-0.318216,-0.319671,0.002540,0.078301,0.100630,0.601072,-0.091181,-0.157795,-0.016469,0.014774,0.044803,0.048453,0.034131,0.121233,-0.030048,0.174896,-0.010936,-0.334480,0.032570,-0.068563,-0.014760,-0.146283,0.150388,0.160520,-0.107170,-0.663876,0.485679,-0.022909,-0.191988,0.219298,-0.672719,0.141295,0.178147,0.124112,0.385737,-0.328066,0.032770,-0.368755,0.061580,0.564495,0.057559,0.255510,0.449422,0.046482,-0.348990,0.031119,0.175393,-0.371632,0.027117,0.447654,-0.032041,-0.318099,-0.081925,-0.527081,-0.130458,-0.082932,-0.169912,0.019602,-0.588747,0.142820,-0.364982,-0.254003,-0.455500,-0.345473,0.246808,-0.042342,-0.264170,0.723421,-0.929667,0.412993,0.428203,0.359307,-0.655540,0.693415,0.024149,0.022566,-0.132980,0.043572,0.317795,-0.122193,0.375945,0.270104,0.394881,-0.045621,0.096018,-0.519441,0.468172', '1292219', '1292720', '3111650', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307884', '午夜凶铃3：贞相大白', '剧情', '“诅咒录像带”的传言甚嚣尘上，人们既好奇又恐惧，然而始终无人了解山村贞子的身世和悲惨经历：贞子（仲間由紀恵 饰）的母亲志津子（雅子 饰）即是一个灵能者，最终却死状凄惨。继承了母亲的灵能力的贞子生活中同样充满坎坷，长大后她辗转来到东京，在名为“飞翔”的剧团努力打拼。不久，剧团当家花旦叶月爱子（奥貫薫 饰）离奇身亡，贞子则匪夷所思取代了她的位置。因其与生俱来的诡异神秘气质，贞子受到团员的猜疑和疏离，唯有负责音响效果的远山博（田辺誠一 饰）对她心存友善。只是，渺小不堪的温暖无法拯救贞子悲惨的人生……本片根据鈴木光司原作改编，是《午夜凶铃》系列的第三部。©豆瓣', '仲间由纪惠', '鹤田法男', 6.7, 12944, 'tt0235712', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1002384337.jpg', 2, 9.2, 51.3, 26.2, 11.3, '-0.002833,0.076459,-0.499315,0.494694,0.048403,0.027035,0.854067,0.109299,-0.503148,-0.335760,0.323322,0.761724,-0.038829,0.384254,-0.043322,0.020899,-0.250370,-0.432550,-0.212821,0.090282,0.042990,-0.269617,-0.246785,-0.193818,-0.064520,-0.366406,0.811230,0.281638,-0.259807,0.528681,0.252678,0.511622,-0.522104,0.124847,0.008409,0.225274,-0.000717,0.237530,-0.304785,-0.033203,0.069404,-0.297416,-0.139600,0.228190,-0.220369,0.339781,0.861073,-0.344686,-0.567924,-0.061101,0.728797,-0.112030,-0.312238,0.188703,0.172753,-0.024423,0.006684,0.137903,-0.173095,-0.083092,0.032720,0.164177,-1.021199,-0.137761,0.446549,0.251555,-0.196614,0.419618,0.001024,-0.114885,0.247324,-0.093459,0.119691,-0.216541,0.289478,0.537225,-0.232634,0.220499,0.018744,0.393375,0.637494,0.071196,-0.420229,0.436322,-0.383900,-0.337360,-0.211461,-0.438275,-0.770200,0.149794,0.255335,0.197428,-0.056073,0.396348,-0.404069,-0.061108,-0.224352,0.094258,-0.030843,-0.199654,-0.098377,-0.386243,-0.209312,-0.596673,-0.327551,-0.045563,0.083667,-0.431960,0.749357,-0.798040,0.296706,0.353115,0.085521,-0.269639,0.259782,-0.000235,-0.130364,-0.223805,-0.038050,0.651551,-0.131850,0.099148,0.142186,0.043245,-0.120930,-0.019154,-0.393723,0.434547', '26667010', '24284209', '26759820', '6974439');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307897', '回忆三部曲', '科幻', '本片由三段互无关联的故事组成。《她的回忆》：2092年，由伊瓦诺夫领导的太空垃圾回收飞船在返航途中接收到来自“宇宙坟场”的求救信号，特殊的是，信号中掺杂着歌剧《蝴蝶夫人》的唱段。队员汉兹与米格尔前往施救，却进入了一位歌剧演员艾娃的回忆，这些栩栩如生的回忆场景对船员们产生了威胁；《最臭兵器》：供职于制药公司的小职员田中信男拖着病体赶回公司，无意中服用了公司与军方合作的实验药品。自此信男成为了制造致命臭气的肉身工厂，对此毫不自知的信男却按照上司命令将药品样本送往东京总部，一路上引起大面积恐慌，军方不得不派出大批军队半路截杀信男；《大炮之街》：在一座由蒸汽驱动的城市中，一家三口展开了一天的生活。母亲去制造炮弹的工厂上班，父亲在炮台担任装填手，小儿子在学校里学习与大炮相关的知识。炮台不停开炮，但敌人的身影却始终没有出现……©豆瓣', '矶部勉', '森本晃司', 8.9, 54843, 'tt0113799', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198104415.jpg', 0.2, 0.6, 8, 37, 54.2, '0.099251,-0.055003,-0.604071,0.520730,0.120295,0.094761,0.678830,0.118959,-0.516617,-0.281803,0.176193,0.548597,0.146949,0.067716,0.079372,-0.295722,-0.295046,-0.332669,-0.206443,-0.127475,-0.299173,-0.508879,-0.087388,-0.340359,0.030800,-0.480603,0.715393,0.163400,-0.400289,0.288100,-0.093596,0.329685,-0.380065,0.393485,-0.157846,-0.089948,0.138020,-0.086520,-0.234627,0.257539,-0.131288,-0.258359,-0.034909,-0.147499,0.214192,0.350818,0.845561,-0.053830,-0.024849,-0.102838,0.142939,-0.167190,0.106238,-0.099942,0.411344,0.302856,-0.103153,0.064821,-0.291487,0.049121,0.023331,-0.067757,-0.589758,-0.275117,0.036318,0.172171,-0.538994,0.265855,-0.254406,0.237221,-0.034083,-0.383744,0.346958,0.194573,0.057571,0.351272,-0.188943,0.174730,-0.615145,0.267959,0.420759,-0.167394,-0.251747,0.100256,-0.200893,-0.269449,-0.241985,-0.166408,-0.369028,-0.223470,0.163574,0.131091,-0.014443,0.243826,-0.782960,0.085299,-0.250735,-0.455772,0.207441,-0.191389,-0.032476,-1.160516,0.265923,-0.012370,-0.170685,0.175678,0.281086,0.117733,0.734989,-0.676644,0.056237,0.529039,0.396113,-0.352977,0.554305,-0.093868,0.145522,-0.238335,0.105396,0.057740,0.320536,0.540452,0.159084,0.361589,-0.125169,-0.306648,-0.385608,0.049605', '2369613', '1306809', '1294917', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307898', '迎春阁之风波', '剧情', '元朝未年，朱元璋率众反抗元朝统治，其部下沈天松企图将朱的布兵图献给蒙古王爷李察罕。李察罕率高手前往陕西接头，反元志士与陕西迎春阁客栈主人万人迷商量对策，并乔装打扮，严阵以待，准备捉拿内奸并夺回布兵图。李察罕也带人住进迎春阁客栈，沈天松献图后即被活捉。女侠黑牡丹前往李察罕  处盗取布兵图，却误取了另一文件；她的同党小辣椒在将文件放回原处时遭到杀害。李察罕查觉后亲自查看，双方斗智斗力，短兵相接，展开一场鏖战。', '李丽华', '胡金铨', 8.1, 7098, 'tt0070942', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200936263.jpg', 0.4, 1.2, 17.8, 54.5, 26, '0.187043,0.485616,-0.433427,0.370636,0.465548,-0.016970,0.392383,0.320999,-0.512739,-0.128985,0.078834,0.334127,0.201719,-0.164744,0.215240,-0.052056,-0.517386,-0.730752,-0.178635,-0.260712,-0.268196,0.068054,0.117021,-0.138459,-0.112026,-0.123470,0.292121,0.133569,-0.314884,0.273898,0.201546,-0.114712,-0.580983,0.651560,0.116468,0.045086,-0.290124,-0.327738,-0.526076,0.396077,-0.219454,-0.453072,-0.421278,-0.078178,0.172071,0.273239,0.833428,-0.444935,0.230973,-0.303713,-0.165039,-0.012889,0.019219,0.251447,0.241349,0.180605,-0.203259,0.271049,-0.299397,-0.113472,-0.008208,-0.279710,-0.341185,-0.049084,0.343374,-0.121193,-0.370957,0.099101,-0.152454,0.497666,-0.106776,-0.265865,0.229505,0.741359,0.132209,-0.320314,0.329974,-0.182449,-0.625821,0.123281,0.183845,-0.361878,0.555762,-0.489044,0.520056,-0.491856,0.250683,-0.058437,0.237370,-0.075747,0.541909,-0.107807,0.422408,-0.369091,-0.536324,-0.387436,-0.600647,0.136128,0.154158,-0.299854,-0.057995,-0.611858,0.120576,0.319443,-0.227660,0.037242,0.380023,0.396788,0.136138,-0.430422,-0.028520,0.353240,0.315074,-0.618054,0.151567,-0.135978,0.067416,-0.221544,-0.209029,0.116637,0.606319,0.891725,0.311293,0.097810,-0.318310,-0.195767,-0.356219,0.044182', '30454698', '1307201', '1466273', '1306490');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307906', '孤男寡女', '喜剧', '华少（刘德华 饰）是一个潇洒风流的电脑公司高层，公司里的一个小职员令他十分头痛。小职员命叫Kinki（郑秀文 饰），每当她的神经质发作便会到处清洁，她一心想得到美满的爱情，实际却令她失望。后来Kinki做了华少的助理，乐于帮助他人的她引来了很多事端，华少不得不每次都帮她解围。导致公司的人都以为他们有染。华少的前女友看不过眼，便决定介绍少年富豪Roger（黄浩然 饰）给Kinki认识，Roger对Kinki一见钟情，可是此时华少对Kinki表现出了过分的关心，让女友觉得他喜欢了Kinki。Roger逼着Kinki跟她结婚，Kinki打电话给华少求助，船在华少赶到前已经开出。一天华少在公司的大堂里，看到了一个熟悉的身影……©豆瓣', '刘德华', '杜琪峰', 7, 51744, 'tt0244092', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2440378793.jpg', 0.5, 5, 50.9, 33, 10.5, '0.245792,0.097511,-0.699876,0.499018,-0.350644,-0.284213,0.671697,0.110195,-0.530235,-0.124300,0.123679,0.731689,-0.296753,0.399913,0.349525,0.073597,0.043533,-0.417534,-0.074244,-0.160631,-0.179125,-0.270193,-0.177238,-0.354612,-0.229198,-0.149657,0.074260,0.047893,-0.189896,0.537165,0.456470,-0.094574,0.216540,0.602252,0.055393,0.105025,0.061004,0.150034,-0.060127,-0.052646,0.076794,-0.302032,0.032822,0.347906,0.068039,0.503972,0.297556,0.060325,-0.402211,-0.025396,0.435170,-0.239199,0.135783,0.108572,0.209652,0.041620,0.357189,-0.080612,-0.478678,-0.045913,-0.080093,0.219513,-0.815695,0.279651,0.091393,0.065136,-0.809359,0.456805,-0.229597,0.018447,0.208929,-0.402587,0.354406,0.141654,0.267182,0.324319,-0.020636,0.204222,-0.476743,0.250311,0.770025,0.175394,0.034589,0.307945,-0.208077,-0.165712,0.027074,0.046467,-0.498246,0.057411,0.091466,-0.333667,-0.155565,-0.144343,-0.225205,-0.092796,-0.027995,-0.009983,-0.006370,-0.510615,-0.071825,-0.268222,-0.070070,-0.223999,-0.217504,0.258074,0.038931,-0.232230,0.663564,-0.799477,-0.082282,0.557954,0.596256,-0.684319,0.768766,0.200849,-0.032926,-0.261182,-0.050178,-0.161283,0.109901,0.183950,0.133754,0.389192,0.017319,-0.404840,-0.287796,0.121269', '1308805', '2990737', '1299649', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307914', '无间道', '剧情', '1991年，香港黑帮三合会会员刘健明（刘德华）听从老大韩琛（曾志伟）的吩咐，加入警察部队成为黑帮卧底，韩琛许诺刘健明会帮其在七年后晋升为见习督察。1992年，警察训练学校优秀学员陈永仁（梁朝伟）被上级要求深入到三合会做卧底，终极目标是成为韩琛身边的红人。2002年，两人都不负重望，也都身背重压，刘健明渐想成为一个真正的好人，陈永仁则盼着尽快回归警察身份。重案组从陈永仁手中获悉一批毒品交易情报，锁紧目标人物韩琛，没料情报被刘健明泄出，双方行动均告失败。但此事将双方均有卧底的事实暴露，引发双方高层清除内鬼的决心。命运迥异又相似的刘健明和陈永仁开始在无间道的旅程中接受严峻考验。©豆瓣', '刘德华', '刘伟强', 9.3, 1253847, 'tt0338564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564556863.jpg', 0.1, 0.2, 4, 27.2, 68.6, '0.123347,0.004949,-0.220001,0.296857,-0.065826,0.166986,0.149449,-0.057392,-0.570791,-0.160643,0.440297,0.616200,-0.019718,-0.006644,0.430945,-0.327756,-0.319315,-0.909392,-0.089873,-0.281749,-0.031701,-0.512251,-0.123460,-0.222342,-0.043815,-0.132386,0.811325,0.000977,-0.018765,0.330584,0.334082,0.304118,-0.185546,0.113181,0.093998,-0.214881,0.539363,-0.216084,-0.574094,0.255771,-0.175097,-0.216993,-0.115998,0.067687,0.036648,0.290284,0.337657,0.111760,-0.173631,-0.119327,0.125266,-0.544382,-0.159095,-0.097337,0.783332,0.510689,-0.049511,0.696264,-0.028655,0.145830,-0.245615,-0.091747,-0.736983,-0.215455,0.338828,0.178750,-0.236034,0.125712,-0.223109,0.181302,-0.134139,-0.109629,0.074683,0.304050,0.296918,0.041391,-0.142535,0.229518,-0.441448,0.237548,0.685742,-0.111718,-0.057598,-0.419412,0.211554,-0.557083,-0.101245,-0.401527,-0.142497,0.115541,0.080577,0.042705,0.019208,0.322942,-0.317372,-0.118554,-0.168967,-0.065884,0.019683,-0.254511,0.105351,-0.579108,-0.357926,0.064099,-0.270920,0.177994,0.015433,-0.331063,0.732347,-0.672177,-0.006061,0.571349,0.216482,-0.808977,0.395653,0.144287,0.286678,-0.660068,0.035827,-0.064579,0.239778,0.354458,0.202494,0.126078,-0.255946,-0.399185,0.064437,-0.250991', '4301278', '1307106', '26615753', '26375028');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307917', '绝地战警2', '喜剧', '本片是《坏小子》的续篇，故事仍发生在迈阿密。迈阿密的毒品交易于一夜之间变得异常猖獗泛滥，各个贩毒集团之间的火拼也接连不断，为了调查贩毒集团内部的重重矛盾，迈阿密警局的一对“黄金”搭档，潇洒的劳瑞（威尔•史密斯）和神叨的宾纳（马丁•劳伦斯）再度临危授命，很快，两人摸清事情的来龙去脉：一股外来的贩毒势力正在侵入迈阿密的毒品市场，为首的毒枭野心勃勃，意图控制整个美国乃至欧洲的毒品交易，建立贩毒王国。警方展开行动围剿贩毒集团时，一位DEA的女卧底西德妮（盖布瑞亚•尤妮恩）被毒贩劫持，对方开出的条件是，劳瑞和宾纳必须去干违法的事，这可难倒了两人，因为漂亮的西德妮不但是宾纳的亲妹妹，还是劳瑞的情人。©豆瓣', '马丁·劳伦斯', '迈克尔·贝', 7.5, 36688, 'tt0172156', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p686551036.jpg', 0.4, 2.3, 33.7, 48.1, 15.6, '0.518960,-0.148941,-0.711440,0.407875,0.185405,-0.218688,0.691498,0.165238,-0.484705,-0.131089,-0.013176,0.526021,-0.185992,-0.310449,0.268825,0.099449,-0.372131,-0.800296,-0.201164,-0.018984,-0.084447,-0.552276,-0.423823,-0.448058,0.031918,-0.049759,0.404318,0.179981,-0.452145,0.179218,0.417714,0.554049,-0.262990,0.264691,0.005441,-0.311637,0.468492,-0.140024,-0.441628,0.239783,-0.087954,-0.024143,0.008296,-0.025858,0.173729,0.517980,0.423517,-0.161128,-0.009242,-0.265801,0.168993,-0.418836,-0.083718,-0.075755,0.493002,-0.074341,0.206908,0.318975,-0.193997,-0.329990,0.283611,-0.101711,-0.723274,-0.089385,0.170040,0.320452,-0.375352,0.219326,-0.157578,0.069241,-0.003839,-0.206142,0.176368,0.697465,0.106262,0.053189,0.116759,0.124054,-0.648303,-0.072754,0.855381,0.138193,-0.120081,-0.067714,-0.124410,-0.571569,-0.246560,-0.128577,-0.144889,-0.061912,0.423514,-0.332288,-0.034932,0.593549,-0.709545,-0.241104,-0.334749,-0.222117,-0.127659,-0.356983,0.174588,-0.759532,-0.374197,-0.398044,-0.041712,0.083603,0.276437,0.123476,0.313563,-0.690151,-0.061606,0.657525,0.183565,-0.443080,0.123866,0.163483,0.146686,-0.348987,-0.443578,0.096976,0.365643,0.151447,0.143122,0.465388,0.144585,-0.354080,0.006196,0.329359', '1306454', '1307442', '25828589', '25978126');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307921', '远方', '剧情', '已过不惑之年的马赫穆特（Muzaffer Özdemir 饰）是一名来自土耳其乡村的独立摄影师，经过多年打拼他终于在伊斯坦布尔谋得一席之地，在和妻子分手后，他独自过着平静而自在的生活。某日，来自老家的表弟尤瑟夫（Emin Toprak 饰）闯入了马赫穆特的世界。老家工厂 倒闭让内向的尤瑟夫丢掉工作，为了贴补家用并给母亲治病，他独自来到大都市闯荡，在此期间暂居表兄的公寓中。多年的分离和不同的生活轨迹让这对表兄弟没有任何共同语言，而马赫穆特却越来越厌烦尤瑟夫对他个人世界的侵扰，一份尴尬在兄弟间悄然而生……©豆瓣', '穆扎菲·奥德默', '努里·比格·锡兰', 8.3, 11939, 'tt0346094', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2462142810.jpg', 0.3, 1.1, 13.6, 53, 32, '0.091808,-0.016962,-0.744890,0.672407,-0.246038,-0.536736,0.843957,0.312832,-0.709235,-0.229741,-0.137577,0.954383,0.064614,0.357296,0.488857,-0.050775,-0.175639,-0.569217,-0.116763,-0.397384,-0.134077,-0.611210,-0.199025,-0.276929,-0.303026,-0.446617,0.555072,0.169823,-0.076681,0.363216,0.197495,0.206206,-0.405361,0.786347,-0.335644,-0.095176,0.052165,0.359949,-0.388785,0.119548,0.146065,-0.162577,-0.219560,0.095770,0.153584,0.281363,0.734524,-0.117135,-0.187038,0.075961,0.279777,0.074229,-0.071657,-0.059633,0.241620,-0.316322,0.089669,0.349579,-0.298696,0.158864,-0.059855,-0.327435,-0.593235,-0.100182,0.163969,0.042591,-0.955722,0.642938,0.049852,-0.381744,-0.051321,-0.352266,0.293312,0.634398,0.137417,0.639371,-0.133613,0.130133,-0.468762,0.383600,0.635748,0.000192,-0.213092,0.321081,-0.385539,-0.385354,0.106463,-0.080034,-0.721689,-0.447616,0.178774,-0.205722,0.006345,0.285030,-0.814151,0.249120,-0.247278,-0.237803,0.132298,-0.451283,0.006599,-0.483688,-0.216738,-0.550531,-0.138588,0.353300,0.115691,-0.152754,0.460181,-1.105996,0.467096,0.525597,0.329022,-0.285597,0.741557,0.320188,0.161366,-0.491409,-0.113463,0.607623,0.121933,0.389988,0.076847,0.131841,-0.036089,-0.055811,-0.527007,0.578729', '1299965', '24698878', '1302384', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307922', '九龙冰室', '剧情', '九纹龙（郑伊健 饰）曾经叱咤江湖，这号风云人物却被人出卖，在泰国被拘捕。多年后他回到香港，在“九龙冰室”当侍应，打算就此在江湖销声匿迹。怎料一名6岁的男孩直呼自己爸爸，原来这个叫兆龙的男孩是当年他远赴泰国后女友Helen（莫文蔚 饰）生下的儿子。当年纹龙为了女友的安全 ，狠心不辞而别。兆龙的出现使纹龙的生活再次泛起波澜，他的气质吸引的儿子的班主任阿蒙（李彩桦 饰）。纹龙的身份还是被江湖之人发现了，并希望他能重振雄风。Helen再次见到的纹龙已经风光不再，她积极为纹龙的复出铺路，纹龙却不想再过问江湖事……©豆瓣', '郑伊健', '马楚成', 6.7, 26907, 'tt0304098', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567214237.jpg', 1.2, 9.2, 52.9, 26.9, 9.8, '0.013049,0.169918,-0.803150,0.622826,-0.401490,-0.396161,0.591647,0.058538,-0.703487,-0.414853,0.207613,1.002968,-0.102765,0.468208,0.060995,0.132295,0.133308,-0.916368,0.337130,-0.157599,0.004760,0.075012,-0.263287,-0.079945,-0.193587,-0.322966,0.577891,0.145913,0.019295,0.433902,0.491788,0.134948,-0.119903,0.529431,-0.479918,0.017508,-0.095581,0.355744,-0.348370,0.114054,-0.060348,-0.474712,-0.070809,0.337274,-0.105522,0.272457,0.598143,-0.003872,-0.157125,0.005312,0.501782,-0.273319,-0.114542,-0.005813,0.246736,-0.155372,0.160247,0.231737,-0.070685,-0.103458,-0.100499,-0.096903,-0.497138,0.093716,0.044119,0.264803,-0.630524,0.626892,-0.374891,-0.093211,-0.080535,-0.251092,0.122348,0.143113,0.039127,0.112613,-0.143689,0.340938,-0.334759,0.379097,0.550208,0.014921,-0.065219,0.358074,0.141740,-0.335772,0.139197,-0.378903,-0.284837,0.118655,0.398675,-0.049638,-0.209128,0.166029,-0.398516,-0.324303,-0.251344,0.068515,0.143311,-0.168902,-0.175691,-0.098570,-0.253104,-0.452450,-0.249880,0.124579,-0.100787,-0.239466,0.450547,-0.911711,0.290226,0.396445,0.217959,-0.869211,0.603827,0.186664,0.020761,-0.232885,-0.194138,0.262130,0.001511,0.376344,-0.002644,0.139325,-0.121271,-0.404731,-0.345708,0.205762', '1301022', '30345227', '1293607', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307931', '小飞侠彼得潘', '剧情', '这是一个小女孩的冒险故事，生活在维多利亚时代的女孩温迪（雷切尔·霍伍德 饰），出生在压抑的环境中，还整天被一个呆板顽固的父亲，扼杀她童年的快乐和梦想。温迪的好朋友约翰和米高，也遭受着同样的痛苦，他们梦想着有一天，能够学会在天上飞，这样他们就可以飞离令他们讨厌的家了。终于有一个黑暗的夜晚，长着乳牙的小飞侠彼得·潘（杰里米·森普特 饰），飞到了他们的窗前，说要教会他们飞翔，带他们去一个美丽的地方。温迪、约翰和米高都高兴极了，于是，他们很快就跟着小飞侠学会了飞，而且飞到了一个美丽的海岛——梦幻岛。原来，小飞侠是梦幻岛上永远也长不大的调皮小孩，他和小仙子一起生活在这个岛上，但两个人觉得多少有点寂寞，于是就请来了云蒂他们三个梦想飞的人类小孩。飞到梦幻岛，温迪立刻被这个美丽而神秘的海岛吸引住了，这里有茂密的丛林、高大的树木，还有野蛮的印第安人，以及横行附近海面的坏蛋海盗。小飞侠带着温迪他们找到了六、七个隐蔽的树洞，这就是他们在梦幻岛上的家，平时他们在海盗的深处探险，晚上累了就回到树洞休息游戏。温迪、约翰和米高本来可以在梦幻岛开心地嬉戏玩乐，和小飞侠与小仙女两位神秘朋友快乐的生活，优哉游哉，岂料，无恶不作的海盗铁钩船长（詹森·艾萨克 饰）带着他的一帮海盗前来大肆破坏。勇敢的小飞侠，这次要营救他的好朋友离开梦幻岛，为此他要与铁钩船长展开一轮激战……', '杰瑞米·桑普特', 'P·J·霍根', 8.2, 48065, 'tt0316396', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1261953713.jpg', 0.3, 1.7, 20.6, 45.1, 32.3, '0.338374,-0.110016,-0.777014,0.655910,-0.279273,-0.246852,0.890792,0.046586,-0.250683,0.061628,0.112196,0.891409,-0.103158,0.509696,0.154981,0.303769,-0.426370,-0.510583,-0.244352,-0.126959,-0.348322,-0.426298,-0.224331,-0.514456,-0.073182,-0.133172,0.330975,0.067804,0.021464,0.610558,0.181207,0.012445,-0.193499,0.414490,-0.714060,0.047922,0.037238,0.017538,-0.031524,0.212609,-0.058091,0.061144,-0.109792,-0.004614,0.145616,0.190136,0.739548,-0.236393,-0.194484,0.001988,-0.113976,-0.320033,0.059430,0.058508,0.366771,-0.397947,0.086104,-0.149113,-0.054902,0.015228,0.035738,-0.307757,-0.535403,0.165128,-0.005261,0.083658,-0.603310,0.528880,0.187011,-0.147000,0.413088,-0.345456,0.135041,0.269410,-0.026049,0.346437,-0.067886,0.126236,-0.693274,0.122286,0.735145,-0.015594,-0.254729,0.211651,-0.237381,-0.403077,-0.204247,-0.099878,-0.576166,-0.266056,0.621278,-0.234742,-0.366629,0.100209,-0.847202,0.220709,-0.160530,-0.119326,-0.230777,-0.486466,-0.219909,-0.420118,0.173482,-0.533245,-0.307471,0.263023,-0.128049,-0.130778,0.890679,-0.745010,0.512598,0.719005,0.313384,-0.296892,0.809765,0.039657,0.070181,-0.008498,-0.070805,0.216914,-0.012975,0.390645,0.302560,0.507951,-0.172035,-0.020965,-0.569237,0.471315', '3055049', '30162520', '1783772', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307955', '辣妈辣妹', '喜剧', '黛丝（杰米•李•柯蒂斯 饰）是一个心理医生也是一个单亲母亲，独自抚养女儿安娜（林赛•洛翰 饰）与小儿子。但黛丝跟安娜的关系一直不好，两人都看不惯对方的做法。这天她们再次争吵：为安娜乐队及母亲再婚的事，表示如果换做是对方，事情就会有好的结果。没想到她们读了一位奇怪老婆婆所给的小纸条后，竟然互换了身份。惊恐中她们不得不接受事实，互相配合做好各自的事，这期间经历的事，才让母女认识到各自的生活，理解到各自的感受。但黛丝的婚礼就要进行了，身份还没法换回……©豆瓣', '杰米·李·柯蒂斯', 'Mark Waters', 7.4, 56053, 'tt0322330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p899519652.jpg', 0.3, 2.7, 37.9, 45.3, 13.9, '0.288623,-0.128723,-0.629682,0.663195,-0.175936,-0.440116,0.447323,-0.040813,-0.550695,-0.532288,0.177201,0.671406,-0.127350,0.403548,0.106560,0.193670,-0.560251,-0.917520,0.160732,-0.114870,-0.493137,-0.573163,0.046053,-0.277916,-0.212006,-0.052817,0.154795,-0.278757,-0.168080,0.310802,0.535019,0.115296,-0.100581,0.619135,-0.000867,0.122056,0.098312,0.375544,-0.428549,0.009086,0.271468,0.005380,-0.225635,0.295093,0.325156,0.464397,0.495148,-0.243255,-0.267005,-0.133685,0.012470,-0.024368,-0.003445,0.418561,0.265527,-0.036295,0.542837,0.147026,-0.349123,0.213723,0.086318,0.126235,-0.674406,0.138300,0.236718,0.028101,-0.666637,0.153758,-0.224755,-0.392862,0.337902,-0.477922,0.015331,0.395515,0.424018,0.593524,-0.166015,-0.092137,-0.333505,0.021958,0.950174,0.174961,-0.122999,0.399661,-0.205353,-0.317439,-0.062575,-0.108289,-0.411789,0.321270,-0.174072,0.288729,0.028687,0.215946,-0.214441,-0.308125,-0.195027,-0.225108,0.219427,-0.641108,0.256931,-0.334072,-0.139996,-0.406706,-0.620950,0.116704,0.103954,-0.207165,0.655311,-0.651472,0.175126,0.134496,0.262513,-0.803859,0.471508,0.410498,0.318351,-0.422735,0.076602,-0.290703,-0.307516,0.079854,0.370973,0.228942,0.276844,-0.174193,-0.196014,0.379508', '1418613', '1301022', '1949320', '4145476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307956', '死神来了2', '惊悚', '少女金伯莉（A.J. Cook 饰）与好友驱车去郊外游玩，途中她预见一场严重的连环交通事故，而自己和朋友也将命丧其中。猛然惊醒的金伯莉将车横在路中央，阻挡了后面的车辆。然而车祸仍然发生，金伯莉侥幸逃过一劫，另有六人从灾难中逃生。这奇异的经历让众人想起180号航班幸存者的故事。正如他们预料的那样，死神不会放过任何一个逃跑者。这些幸存者按照他们本该在车祸中死去的顺序一个接一个在各种巧合和意外中死去，金伯莉成为最后的生者。她得知180航班幸存者克莉尔（Ali Larter 饰）仍然健在，她希望从克莉尔那里得到逃脱死神魔爪的办法……©豆瓣', '艾丽·拉特', '大卫·R·艾里斯', 7.5, 162502, 'tt0309593', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p498462827.jpg', 0.3, 2.7, 35.4, 45.9, 15.6, '0.439183,0.028925,-0.699839,0.291887,0.200526,0.121742,1.016876,-0.410805,-0.457068,-0.204394,0.476518,0.911418,-0.145368,0.222674,0.419436,-0.343594,-0.326451,-0.508215,0.118963,0.016375,-0.529891,-0.300057,-0.294244,-0.158872,0.045270,-0.136394,0.698411,0.471786,0.021425,0.877308,0.088379,0.209520,-0.628602,0.437752,-0.160232,0.200040,-0.131123,0.170112,-0.201923,0.358688,-0.125133,-0.502404,-0.013499,0.405054,-0.130994,0.483522,0.659304,-0.385733,-0.232862,0.040145,0.197645,-0.404686,0.037576,0.095339,0.214755,0.056605,0.099179,0.154226,-0.092063,-0.085924,0.007521,0.309255,-0.649320,-0.171865,0.060302,0.370582,-0.599081,0.204444,0.059326,-0.035281,0.172695,-0.176082,0.394401,0.259200,0.319359,0.007559,-0.445165,-0.207106,-0.698387,0.092920,0.983097,-0.299007,-0.219924,0.131638,-0.083418,-0.405045,-0.027253,-0.043771,-0.231161,0.386812,0.289929,0.253729,-0.311649,0.109662,-0.116266,0.002851,-0.363180,-0.013860,-0.502474,-0.319657,-0.201254,-0.644973,0.424031,0.069919,-0.329937,0.276009,-0.121584,-0.268041,0.359283,-0.527345,0.271012,0.455736,0.412857,-0.302255,0.621584,-0.110567,0.409574,-0.205149,0.146698,0.408118,0.183434,0.255136,-0.059339,0.157494,-0.138598,-0.035570,-0.335608,0.150030', '25721544', '1773217', '3011051', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307979', '京都球侠', '喜剧', '清朝末年，欧洲足球队海盗队来华时和驻华外国使馆联队进行了一场比赛。比赛引来了大批民众和朝廷官员观看，海盗队获胜后，队长哈里为博取女友詹尼一笑，竟然用力将球踢向围观的群众和朝廷官员。就在一众外国人哈哈大笑之时，人群中窜出一名大汉，他叫周天（张丰毅 饰），他以高强的球技回敬了哈里。詹尼见此教唆哈里向中方挑战，于是一场中外足球赛大战在即。原来周天是一位曾留学牛津大学并曾担任清朝翰林院编修的进步青年，他深知中、外足球水平的据，单凭一己之力很难为中国人出一口气。于是，周天踏上了访寻民间球侠、为国增光的道路。©豆瓣', '张丰毅', '谢洪', 6.8, 6924, 'tt0333682', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1953099924.jpg', 1.5, 7, 50.5, 32, 9.1, '0.149524,-0.214965,-0.418677,0.761265,0.029913,-0.255457,0.267465,-0.003760,-0.731424,0.151703,0.287316,0.710222,-0.240003,-0.070262,0.516657,-0.382252,-0.289729,-0.991301,-0.421888,-0.017754,-0.199935,-0.245430,-0.294249,-0.069710,-0.442588,-0.256823,0.553776,0.165975,-0.311594,0.512242,0.107514,0.449039,0.039190,0.345724,-0.003021,0.074469,0.308174,-0.210798,-0.054582,0.155571,-0.256254,-0.444348,-0.488475,-0.026713,0.073146,0.135670,0.544210,-0.137499,0.375006,-0.490729,0.178350,-0.185779,0.096876,0.350336,0.411145,0.258666,0.390413,0.169579,0.290619,0.078932,-0.315677,-0.203719,-0.304122,0.167262,-0.091831,-0.170139,-0.408260,0.424497,-0.099064,-0.041166,0.014870,0.013903,-0.096893,0.558866,0.051240,0.032359,-0.086806,-0.135998,-0.313951,0.202706,0.547201,0.040818,-0.287198,-0.226156,0.118779,-0.542826,0.018016,-0.228002,-0.013529,-0.028102,0.529957,-0.282603,0.292389,0.066839,-0.429247,0.123305,-0.245033,-0.319199,0.094898,-0.014061,-0.067021,-0.737434,0.340909,-0.112670,-0.168802,-0.040251,0.252527,0.065283,0.776497,-0.744385,-0.194577,0.548312,0.240302,-0.328317,0.688245,-0.220177,0.159347,-0.027900,-0.187065,-0.129520,0.105691,0.385223,-0.189534,0.443038,-0.156022,-0.504613,0.026747,0.081170', '26365262', '25723905', '3811356', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307990', '龙潭虎穴', '剧情', '世间最珍贵的宝石非钻石莫属，引无数侠盗尽折腰，然而黑钻石的价值更是无可估量。以安东尼（DMX 饰）为首的侠盗帮正在潜入一幢大厦窃取稀世黑钻石，以交中间人并转卖给神秘买家，而他们的电话却被在另一头的台湾特工苏（李连杰 饰）所窃听，并前来争夺黑钻。令安东尼始料不及的是，黑钻到手却使他们陷入四面楚歌的危险境地，业已谈妥的中间人被苏手刃，各方势力对黑钻又虎视眈眈，钻石的原主人还绑架了他女儿，以要挟他交出钻石，而最关键的钻石却已再度被盗走。如今唯一的办法只有夺回钻石，力量薄弱的安东尼不得不与苏通力合作，然而面对眼前牵一发而动全身的局面，二人能否险中取胜？©豆瓣', '李连杰', '安德泽·巴特科维卡', 6.4, 9308, 'tt0306685', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1651430700.jpg', 1.8, 11.3, 59.4, 20.9, 6.7, '-0.032714,0.323914,-0.351287,0.520662,-0.111476,-0.235180,0.364110,0.241192,-0.254493,-0.147600,0.109457,0.420693,-0.257612,-0.089436,0.074058,0.173006,0.110309,-0.366480,-0.210431,-0.355712,-0.259112,-0.498587,-0.673979,-0.145688,0.056329,0.327900,0.865696,0.515148,-0.407619,-0.047830,0.628486,0.433292,-0.166217,0.496033,-0.083917,-0.527964,-0.335114,0.145052,-0.451053,0.031540,-0.102662,-0.411238,0.043301,0.330557,0.073688,0.310296,0.275552,-0.530935,0.195280,-0.040902,0.327947,-0.409496,0.000301,0.028994,0.226511,0.013704,-0.002636,-0.143461,-0.325318,0.039778,0.452885,0.005493,-0.881904,0.158621,0.389229,-0.026439,-0.357444,0.115001,-0.106940,0.144167,0.063839,-0.078224,0.236274,0.293317,0.233143,-0.021699,-0.132008,-0.004729,-0.592871,-0.081640,0.323282,-0.169100,-0.007394,0.094619,0.125521,-0.591289,0.065231,-0.325753,-0.031368,-0.221380,0.654981,0.215225,0.258519,-0.066324,-0.771769,-0.098773,-0.352498,-0.154334,0.047930,-0.379959,0.016836,-0.396140,-0.185395,-0.252536,-0.146340,0.402304,0.317414,-0.210851,0.488264,-0.177861,-0.147972,0.222635,0.073241,-0.719942,0.415724,-0.169155,0.109412,-0.325209,-0.606877,0.389305,0.577852,0.462327,-0.020048,-0.188017,-0.136806,-0.280136,-0.387117,0.230382', '3670447', '3001114', '7155241', '35377026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1307991', '洞', '剧情', '新世纪来临前的台湾某区，大雨连降导致某种传染病爆发，无力防护的政府要求疫区居民撤离，但还剩楼上楼下一男（李康生）一女（杨贵媚）留在一幢犹如监狱的大楼里，各自过着与世隔绝的日子，没有撤离的迹象。水电工补修水管时为两人留下一下洞，自此，他们借助此洞，开始偷窥对方的生活，试探对方的反应，并在幻想的暗恋中（华丽梦幻的歌舞场景）完成唯一的交流。此洞亦是他们各自所处的（生活）洞穴的出口，相互试探的过程亦是他们爬向出口的过程。——尽管人类世界只剩一男一女，不一定会做亚当与夏娃，但从同类身上获得某种安慰赶走内心深处的孤独，却是人类的天性，他们当然也不例外。©豆瓣', '李康生', '蔡明亮', 8.1, 7188, 'tt0156610', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2158046146.jpg', 0.6, 1.6, 18.7, 48.8, 30.2, '0.251194,-0.001768,-0.732536,0.431097,0.027001,0.103951,0.928909,-0.044465,-0.422371,-0.250101,0.347484,0.432783,-0.183349,0.079391,-0.038272,-0.149121,-0.368583,-0.312901,-0.101015,0.024449,-0.401377,-0.224938,-0.073988,-0.304529,-0.070833,-0.148308,0.811676,0.310742,-0.406372,0.138503,-0.112215,0.103246,-0.396376,0.538592,-0.187295,-0.092686,-0.122880,0.124035,-0.372288,0.175486,-0.121704,-0.083272,-0.275818,0.093195,-0.002201,0.457473,0.675841,-0.247834,-0.211019,0.083392,0.128478,-0.180610,-0.081965,0.176935,0.284318,-0.023029,0.310178,0.307602,0.189860,0.147210,-0.026151,0.001733,-0.658186,-0.045241,0.159703,0.255758,-0.180851,0.451746,0.190598,-0.150750,-0.034491,-0.207311,0.146909,0.254911,0.233619,0.411032,-0.400563,-0.016285,-0.657474,-0.017503,0.640926,-0.155779,-0.505109,0.450646,-0.307232,-0.648033,-0.115764,0.119609,-0.303078,-0.260331,0.017736,0.403742,-0.411197,0.067200,-0.605598,0.149473,-0.138944,-0.400406,0.066601,-0.376988,-0.064119,-0.662917,-0.125480,-0.317529,-0.319932,0.011984,0.093230,-0.144039,0.404002,-0.715246,0.192104,0.471030,0.393189,-0.331574,0.625605,0.090727,0.123184,-0.155343,0.056165,0.441412,0.016248,0.297737,0.028473,0.222147,-0.139010,0.088367,-0.469545,0.335286', '21619567', '3005387', '1304862', '26715845');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308005', '周渔的火车', '剧情', '周渔（巩俐 饰）在小镇上从事陶艺工作，美丽善良的她遇上诗人陈清（梁家辉 饰）后，对他的眷恋油然而生。尽管陈清在另一镇上做图书管理员，生活清贫，爱情的力量还是让周渔甘心劳苦，来往于两地只为照顾陈清。慢慢地，她变得有点疲倦。火车上经常有同车人张强（孙红雷 饰）。张强暗暗为周渔美丽的气质所打动，二人由起初的争拗渐变理解。张强总是在周渔失落烦恼之时为她解忧，帮她找寻陈清诗中所写的湖，感情在暗涌，周渔也在两地、两个男人之间矛盾的徘徊。在张强身上，她感受到强烈的男子气魄和欲望，然而却也离不开孱弱的陈清。一天陈清告诉周渔，说他要去边疆支教。这一决定最终成全了周渔和张强，还是让周渔看清了该如何决断？©豆瓣', '巩俐', '孙周', 6.7, 27034, 'tt0354243', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2510633037.jpg', 1.2, 9.5, 52, 29.1, 8.2, '0.067973,0.111572,-0.822441,0.578622,0.030520,-0.418032,0.755808,0.317304,-0.667484,-0.060920,0.097667,0.579817,-0.062131,0.342452,0.177330,0.000682,-0.213055,-0.437953,0.125324,0.096819,-0.123470,-0.443151,-0.295093,-0.090953,-0.304491,-0.182614,0.445344,0.301548,-0.204077,0.380587,0.270975,0.073082,-0.209283,0.652168,-0.132489,-0.183161,-0.174718,0.125743,-0.222610,-0.278548,0.157123,-0.281245,-0.400688,0.002137,-0.146865,0.210973,0.698243,0.083735,-0.365747,0.257878,0.232970,-0.018685,0.060723,-0.042018,-0.193741,0.001957,0.044356,0.055841,-0.465170,-0.027803,0.081804,0.190424,-0.525125,-0.044955,0.084078,0.330168,-0.607656,0.531816,-0.049691,-0.289665,0.273942,-0.480316,0.024459,0.092899,0.207753,0.592287,-0.145184,0.021996,-0.193365,0.217631,0.825329,0.203695,-0.065013,0.361197,-0.358136,-0.233010,0.061054,-0.044239,-0.467866,-0.114726,0.025570,0.108034,-0.331518,-0.036806,-0.461686,-0.011320,0.005951,0.038159,-0.197203,-0.543316,0.138620,-0.236540,-0.244596,-0.499391,-0.267158,0.059823,0.277104,-0.340239,0.777788,-0.656323,0.189083,0.513187,0.153878,-0.526538,0.601564,0.265003,-0.012526,-0.172399,-0.072116,0.350283,-0.155155,0.104879,0.134109,0.401078,-0.107067,0.086698,-0.370664,0.551381', '4058933', '4861627', '2081098', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308006', '动物农场', '剧情', '在一个农场内，饲养着各种牲畜，它们都是农场主人的私有财产，等待他们的只有一生劳动以及最后被卖掉和被吃掉的下场。农场里的一头猪在提出了“人类剥削牲畜，牲畜须革命”的理论之后死去，不久农场便掀起了一场由猪领导的革命，原来的剥削者──农场主被赶走，牲畜们实现了“当家作主”的愿望，尝到了革命果实的甘美，农场更名为“动物农场”并且制定了农场的宪法── 七诫。但是不久，作为领导革命的猪们内部发生了分裂，一头猪被宣布为革命的敌人。此后，获取了领导权的猪拥有了越来越大的权力和越来越多的特别待遇，逐渐脱离了其他动物，最终蜕变成为和人类完全一样的牲畜剥削者，动物农场的名字也被放弃。本片乔治·奥威尔（George Orwell）1945年出版的同名小说《动物农庄》改编，同时是英国第一部影院动画电影长片。©豆瓣', '戈登·希斯', '约翰·哈拉斯', 8.5, 7395, 'tt0047834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2511279779.jpg', 0.4, 1.5, 12.4, 44.3, 41.4, '0.225240,-0.031508,-0.526373,0.504988,-0.141716,-0.247919,0.439530,0.145904,-0.344625,0.133833,-0.056026,0.777325,-0.121338,0.055161,-0.097442,-0.277928,-0.148824,-0.457115,-0.380587,-0.024591,-0.170174,-0.203268,-0.271924,-0.296184,-0.186833,-0.251147,1.003495,0.018539,-0.155907,0.109114,0.154046,0.086848,0.143519,0.102019,-0.167351,0.202251,0.292789,-0.028654,-0.182923,0.165621,-0.213640,-0.088207,0.133798,-0.145328,-0.093747,0.194052,0.762679,-0.632917,-0.253399,-0.747550,0.537115,-0.322692,0.026128,0.245221,0.541194,0.081655,0.117462,0.359194,-0.140246,0.119995,0.062332,-0.246002,-0.799384,-0.333035,-0.026932,0.008393,-0.601916,0.421985,0.380871,0.226157,0.154881,-0.322277,0.293867,0.395359,0.269789,0.756778,-0.188979,0.136777,-0.808061,0.380824,0.702465,-0.247078,-0.435737,0.189730,-0.483106,-0.655758,0.103545,-0.431577,-0.147133,-0.253004,0.353337,0.115572,-0.567952,0.317712,-1.125908,-0.050292,-0.095528,-0.742072,0.200788,-0.285169,-0.156068,-0.560774,-0.090149,-0.258653,0.019122,0.133079,0.340685,-0.334207,0.934434,-0.755845,0.180336,0.459793,0.344507,-0.662987,0.447997,-0.395998,0.212848,-0.077342,0.000409,0.090696,0.267026,0.500276,0.488086,0.212195,-0.074034,-0.282429,-0.311957,0.633239', '26290398', '2977870', '26759820', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308010', '谈谈情跳跳舞', '剧情', '中年男子杉山正平（役所广司饰）是名普通的上班族，他工作认真，事业有成，却发觉朝九晚五的生活空虚无味。一天下班，疲劳的杉山偶然透过车窗看到车站对面，一家贴有“岸川舞蹈学校”字样的楼房窗旁，有一位相貌清秀女子的身影，看着那女子凝望远方，杉山被她那寂寞的表情所深深地吸引。数日之后，抑制不住好奇心的杉山走进了这家舞蹈学校，开始学习交谊舞。他所看到的那个女子正是这个舞蹈教室的老师岸川舞（草刈民代饰）。杉山渐渐地真心喜欢上了跳舞，一样享受舞蹈带来的快乐还有青木（竹中直人饰）等人。他们在指导下进行舞蹈大会前的特训，而舞老师也再次燃起对舞蹈的热爱……©豆瓣', '役所广司', '周防正行', 8.2, 18610, 'tt0117615', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1696723957.jpg', 0.2, 0.9, 16, 52.2, 30.7, '0.217863,0.064252,-0.398341,0.361561,-0.360164,-0.269235,0.663413,0.359795,-0.345180,-0.215964,0.433459,0.733083,-0.124499,0.644471,0.262618,0.157878,-0.376162,-0.797746,-0.259002,-0.148744,-0.206006,-0.056995,0.268700,-0.090485,-0.041142,-0.291274,0.597150,0.005543,0.084431,1.020385,0.083326,-0.031377,0.198878,0.277964,-0.186516,-0.188464,0.202590,0.161481,0.170507,-0.028115,-0.131521,-0.526226,-0.351621,-0.038015,0.009331,0.089060,0.764648,0.189038,-0.364992,0.025845,0.197805,0.006986,-0.025014,0.204882,0.287242,0.202604,0.164017,-0.257110,-0.326601,-0.042802,-0.448406,-0.012508,-0.348921,-0.147769,0.088309,0.290220,-0.169005,0.545533,0.100823,-0.267602,0.238004,-0.286925,-0.048402,0.124597,0.273070,0.526202,-0.144137,0.168712,-0.189571,0.252719,0.411339,0.233341,-0.172605,0.480834,-0.611809,-0.285521,0.058884,0.131177,-0.217942,-0.294510,0.100998,0.084845,0.079455,-0.398334,-0.487662,0.275353,0.163358,-0.132638,-0.120433,-0.235410,-0.376190,-0.872992,-0.049071,-0.504251,-0.361566,0.017043,0.053859,-0.318142,0.868795,-0.855892,0.358776,0.537676,0.254466,0.160570,0.772080,-0.088819,-0.390915,0.020741,-0.377705,0.302350,-0.104727,0.405781,-0.235013,0.835154,-0.279171,0.135354,-0.723915,0.605940', '3811356', '26365262', '25922902', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308034', '黑白森林', '剧情', '同是警察的黄姜（黄秋生）和七喜（刘青云）情同手足，然而两人行事上却有天壤之别，黄姜刚正不阿，七喜却与黑帮老大盲超（吴镇宇）是结拜兄弟，某次行动中，黄姜迫于无奈将七喜连同盲超击毙，事后也没解释原因，令七喜老婆对其生出误会。十多年后，七喜的儿子（黄浩然）与盲超的儿子阿威（陈小春）长大成人，并各自继承父业分别成了警察和黑帮老大。阿威一直想报父仇，可乐在不了解事情的真相前也有这样的打算，但在知晓事实后，开始为选黑还是选白犯难。©豆瓣', '黄秋生', '王晶', 6.6, 25059, 'tt0375669', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2542485725.jpg', 1.5, 9.1, 55.3, 27.8, 6.4, '0.317404,-0.164479,-0.660211,0.410153,0.029677,-0.272611,0.596290,0.071049,-0.896360,-0.196511,-0.047266,0.667827,-0.046363,0.104115,0.063534,-0.062221,-0.317652,-0.682455,-0.125454,-0.188875,-0.002609,-0.660086,-0.135778,-0.109802,-0.267287,0.104377,0.552103,-0.199932,-0.193854,0.417343,0.512948,0.233580,-0.197950,0.525948,0.039539,0.297938,-0.170424,0.101242,-0.471586,-0.030511,0.327574,-0.256673,-0.204681,0.266442,0.216879,0.620067,0.162251,-0.132196,-0.254960,-0.212310,-0.148627,-0.301880,-0.212236,0.062180,0.383196,-0.102358,0.405023,0.376689,-0.016425,-0.255477,-0.121257,0.213257,-0.590089,0.102052,0.315803,0.074306,-0.714373,0.411744,-0.237233,-0.279659,0.130354,-0.419048,0.240722,0.436698,0.386421,0.266919,-0.074449,-0.066312,-0.499200,-0.087135,0.794382,0.130248,0.083383,0.233866,0.021325,-0.386820,-0.061445,-0.285142,-0.199527,0.147000,-0.095642,0.341604,-0.132598,0.173098,-0.342759,-0.109610,-0.114572,0.183832,0.057693,-0.424268,0.078556,0.077841,-0.190964,-0.553053,-0.458314,-0.054128,0.162602,-0.357409,0.495379,-0.961128,-0.065438,-0.019313,0.320297,-0.538546,0.526280,0.361922,0.079908,-0.466929,-0.002962,-0.383725,-0.014865,-0.000611,0.355778,0.182924,0.072629,-0.500605,-0.281978,-0.112625', '35030151', '1301022', '25721544', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308035', '顺流逆流', '剧情', '年轻人阿政（谢霆锋饰）总想着能有不一样的生活，向往去南美。一次偶然，他邂逅卧底女警察（徐子淇饰），当上了“准爸爸”。为了筹钱抚养女方肚中的孩子，阿杰辞掉了酒吧招待的工作，跟随吉叔（黄秋生饰）做起了保镖。 阿杰（伍佰饰）多年来在南美担任雇佣兵，在经历枪林弹雨的战火生活后， 他想着洗手告别过去，回到香港娶了慧（卢巧音饰），她是香港有权势的黑社会老大的女儿。一次阿杰无意中结识了阿政。 而阿杰为了照顾妻子，独吞了钱财，昔日战友们很快追到香港，一场恶战在所难免。©豆瓣', '谢霆锋', '徐克', 7.6, 15763, 'tt0251433', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524402943.jpg', 0.9, 4.4, 30, 45.6, 19.1, '-0.055065,-0.225950,-0.560517,0.179097,-0.397031,-0.506229,0.389408,0.211896,-0.526369,-0.229680,0.314094,0.829189,0.238156,0.336718,0.209504,-0.064678,-0.162750,-0.530244,0.150590,-0.088880,-0.259798,-0.156334,-0.069473,-0.219437,-0.103450,-0.075721,0.299381,-0.100558,0.063432,0.425753,0.335610,0.097454,-0.033752,0.285420,-0.379085,0.131920,0.137696,0.407302,-0.653330,0.288568,0.060136,-0.190977,-0.254624,-0.147786,0.475222,0.010747,0.575223,0.298799,0.217484,-0.164604,0.222390,-0.071257,-0.062492,-0.272669,0.269067,0.126047,0.078291,0.173461,-0.227963,-0.129591,-0.092329,-0.295237,-0.365938,0.053680,-0.013984,0.056570,-0.831177,0.379872,0.112967,0.018497,0.146572,-0.209447,0.256520,0.445945,0.035067,0.236597,0.026405,0.282866,-0.414583,0.606744,1.044437,-0.016985,0.221205,0.297666,0.030386,-0.011420,0.374142,-0.292723,-0.609188,0.131823,0.326942,-0.405376,-0.414016,0.152580,-0.282805,-0.227775,-0.179338,0.030267,0.233857,-0.338603,-0.006809,-0.425377,-0.193443,-0.324361,-0.166962,0.029060,-0.046378,-0.192046,0.651624,-0.889466,0.046596,0.595283,0.242842,-0.857157,0.726251,0.059880,0.180118,-0.332359,0.349474,0.177809,0.009412,0.111081,0.088313,0.042232,-0.200237,0.052794,-0.137902,-0.074812', '1296978', '1299062', '25721544', '1419416');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308038', '牧马人', '剧情', '1970年代末，在西北敕勒川牧场做了小半辈子牧马人的小学教师许灵均（朱时茂）一路风尘来到北京饭店，与30年未曾谋面的父亲、旅美华侨企业家许景由（刘琼）见面。当年，追求个人自由的许景由无法忍受与妻子的错误婚姻，丢下妻儿去了美国。此次归来，他有心带许灵均回美国继承事业。交谈中，许灵均不认为将自己融在集体中、时时以国家利益为重的行为是思想陈旧的表现，对于父亲的舒适生活，他并不艳羡。回顾自己几十年来所走的道路，虽有幼年成为弃儿、青年被打成右派下放牧场的悲惨经历，却也数次从牧区质朴、善良的乡民身上感受到人间温情，而在艰难岁月中与四川苦命女李秀芝（丛珊）结为夫妻后，许灵均更是尝到苦尽甘来的心酸与甜美。他认为，国家在好不容易迈过“文革”这个大坎之后，个人更应该同亲朋一起，不离不弃地跟着她走向新生。©豆瓣', '朱时茂', '谢晋', 9.1, 64081, 'tt0084363', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517627958.jpg', 0.2, 0.4, 6.2, 30.4, 62.8, '0.129866,-0.066916,-0.677528,0.504875,-0.137168,-0.367017,0.659456,-0.018932,-0.746624,-0.145431,0.078923,0.761659,0.172939,0.473607,0.345276,-0.110142,-0.090103,-0.564731,-0.187892,-0.118625,-0.240678,-0.382594,-0.089632,-0.088673,-0.474456,-0.029014,0.695775,0.216739,-0.162252,0.461055,0.162625,0.108771,-0.272089,0.400081,-0.329660,-0.108964,-0.089815,0.425107,-0.602032,-0.203369,0.029910,-0.335811,-0.282468,-0.059901,0.046547,0.133938,0.600480,-0.219251,-0.119451,-0.316294,0.287681,-0.098409,0.077734,0.174774,0.173635,0.116665,0.232599,0.445423,-0.020604,0.036239,-0.045307,-0.241226,-0.456925,0.085563,0.142288,-0.040332,-0.600994,0.419452,0.084176,-0.125741,0.084854,-0.345674,0.090612,0.429439,0.407171,0.422513,-0.318257,0.247526,-0.178142,0.311918,0.931123,0.035169,-0.318821,0.123354,-0.326438,-0.367862,0.253073,-0.283453,-0.509865,-0.100297,0.065557,0.214222,-0.121052,0.464097,-0.401610,0.070099,-0.091376,-0.013608,0.220846,-0.412790,-0.026562,-0.272399,-0.353582,-0.668431,-0.173739,0.067033,0.311167,-0.451133,0.618827,-0.635807,0.086735,0.085956,0.477573,-0.687623,0.805483,0.043658,0.259143,-0.389499,0.179444,0.671594,-0.149939,0.188676,0.094864,0.018159,-0.224941,0.127493,-0.233450,0.320531', '25721544', '6890343', '4145476', '4728584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308047', '蔷花，红莲', '剧情', '蔷花（林秀晶 饰）和红莲（文根英 饰）是一对如花似玉的姐妹。在一个充满阳光的午后被父亲开车带到了位于郊外的别墅居住。然而她们对居住在这里的继母心生排斥，红莲夜晚看见鬼魂，继母养的小鸟被毒死，但是在蔷花的眼中，继母一直企图伤害自己和红莲。自己懂得保护自己不紧要，但是妹妹红莲尚且不懂得反抗，蔷花十分强悍地捍卫着妹妹的利益。但父亲却处处责怪自己，不明白整件事情都是继母的所为。蔷花与父亲的争吵越发激烈，直到一天父亲说出了真相……©豆瓣', '林秀晶', '金知云', 7.2, 62088, 'tt0365376', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p457610525.jpg', 1.1, 5.8, 40.2, 39.5, 13.4, '0.236053,-0.136936,-0.946784,0.661026,-0.285776,0.017045,0.851383,0.183622,-0.636421,-0.378891,0.438410,0.679821,-0.069758,0.225704,-0.095498,0.313295,0.040466,-0.340001,-0.070513,0.139270,-0.077868,-0.598268,-0.040312,-0.203777,-0.146206,-0.176739,0.707307,0.142803,-0.288556,0.150884,0.153000,0.356988,-0.059554,0.469932,-0.083375,0.021133,-0.153916,0.153970,0.111737,0.188500,0.039609,-0.237381,-0.255453,0.360535,-0.032371,0.397930,0.777645,-0.284036,-0.351249,-0.219249,0.321072,-0.355263,0.065445,0.436249,0.157275,-0.316809,0.454059,0.232411,-0.326288,-0.024375,0.063843,-0.077376,-0.504217,0.069862,0.339397,0.046865,-0.830704,0.509629,-0.051465,-0.204996,0.266495,-0.367799,0.514501,0.122226,-0.154920,0.622712,-0.563956,-0.125832,-0.753839,-0.054783,0.863672,-0.084724,0.252462,0.502995,-0.489344,-0.216237,-0.040081,-0.278120,-0.736749,-0.042648,0.031508,0.266514,-0.300650,0.294496,-0.326289,-0.226827,-0.063266,0.064749,0.062143,-0.927385,0.051751,-0.028521,-0.369502,-0.818212,-0.360676,0.037798,-0.047695,-0.253932,0.667984,-1.081109,0.402087,0.225469,0.383138,-0.577529,0.707161,0.321650,0.021314,-0.073983,0.020994,0.291420,0.073959,-0.171001,0.123763,0.030913,0.108106,-0.020995,-0.268593,0.170714', '21766698', '1308635', '2052978', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308050', '我的老婆是大佬2', '喜剧', '叱咤黑道的大佬车恩珍（申恩庆 饰）在一场意外中头部受伤，失去了曾经的所有记忆，包括自己的身份。中餐馆老板杰超（朴俊奎 饰）发现了流落在街头的车恩珍，善良的他收留了这个一无所有的女子。就这样，曾经的黑道大佬，如今成为了在餐馆里送外卖的送餐小妹。很快，车恩珍就发现了自己身上不同寻常的地方，对刀具过于熟练的使用让车恩珍开始怀疑起自己的真实身份。与此同时，因为车恩珍的存在，餐厅里的生意日渐火爆，她和杰超之间也日久生情。某天在送外卖的时候，车恩珍遇到了一帮劫匪正在抢银行，正义感的趋势之下，车恩珍出手制服了劫匪，因此而获得了“勇敢市民奖”。车恩珍的出名让她的仇家发现了她并没有死的事实。©豆瓣', '申恩庆', 'Heung-sun Jeong/郑多顺', 6.1, 6821, 'tt0364447', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2262653412.jpg', 2.5, 16.2, 61.5, 15.3, 4.4, '0.617874,0.264145,-0.793381,0.437291,-0.395677,-0.075291,0.828414,0.025018,-0.794385,-0.243418,0.232753,0.967963,-0.010535,0.266203,0.296849,-0.021412,-0.029123,-0.867951,-0.180845,-0.284208,-0.414526,-0.281802,-0.483861,-0.175402,-0.205342,-0.290491,0.463270,0.267590,-0.360266,0.585235,0.346504,-0.034876,0.128219,0.639520,-0.332130,0.091959,0.099439,0.044320,-0.052884,0.249978,0.088346,-0.586157,0.123854,0.528934,-0.029368,0.499586,0.545481,-0.262500,-0.350526,-0.026488,0.376758,-0.215987,-0.156228,0.106897,0.436536,-0.008918,0.295339,-0.028552,-0.305213,0.038861,0.094909,0.228040,-0.861350,-0.018074,0.191039,0.171789,-0.895294,0.467960,-0.140043,-0.148335,-0.010361,-0.342924,0.468642,0.086786,0.229987,0.253625,-0.029161,-0.138416,-0.542181,0.223562,0.788036,-0.056836,-0.064775,0.379706,-0.259700,-0.388852,-0.069505,-0.390972,-0.340112,-0.038014,0.308313,0.082728,-0.312164,0.292718,-0.601316,0.145634,-0.039625,-0.098236,-0.173876,-0.203295,-0.244590,-0.416083,-0.293533,-0.517461,-0.291273,0.064285,-0.119212,-0.158778,0.731914,-1.064116,0.226801,0.613627,0.475716,-0.483972,0.668124,-0.006130,0.027423,-0.048193,-0.306139,-0.061173,0.160276,0.314013,0.151238,0.313071,-0.234546,-0.475874,-0.249229,0.474571', '35030151', '1301022', '1783461', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308069', '尸骨无存', '惊悚', '毕业在即，某大学5名好友：杰夫（乔伊·卡恩 Joey Kern 饰）、卡伦（乔登·蕾德 Jordan Ladd 饰）、保罗（雷德·斯壮 Rider Strong 饰）、玛茜（席瑞娜·文森 Cerina Vincent 饰）和伯特（詹姆斯·德贝洛 James DeBello 饰）相约远离城市喧嚣，一起来到深山中的小屋度假狂欢。但是他们的欢乐很快为恐慌所取代，在山上他们遇见一个血肉模糊、全身溃烂的男子。此后不久，卡伦的身上也出现类似症状，她似乎被之前那个男人身上的病毒所感染，很快便死于非命。死神遽然降临，这群年轻人的生命和友情受到莫大考验……本片荣获2003年葡萄牙亚洲奇幻电影节最佳国际影片第三名、2002年Sitges – Catalonian国际电影节最佳化妆奖。©豆瓣', '莱德尔·斯特朗', '伊莱·罗斯', 6.1, 8117, 'tt0303816', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1689533294.jpg', 4, 17.3, 53.9, 18.6, 6.2, '0.077845,0.025432,-0.639608,0.293175,0.316774,-0.201604,0.668017,0.196744,-0.373426,-0.392809,0.252171,0.849732,-0.668696,0.216205,0.420482,0.043760,-0.381260,-0.643398,0.045215,-0.300795,-0.281693,-0.090944,-0.243764,-0.070604,-0.086232,-0.433047,0.721165,0.175298,0.014066,0.756895,0.284392,0.344099,-0.022267,0.237535,-0.052224,-0.044973,0.259425,-0.194142,-0.335299,0.235217,-0.159719,-0.248813,-0.058428,0.042462,-0.023407,0.118223,0.748893,-0.112872,-0.063247,-0.303296,0.401199,-0.252948,0.132906,0.027423,0.265366,-0.204285,0.395176,0.125738,0.026741,0.111458,0.002423,-0.233703,-0.310628,0.221518,0.020539,0.174090,-0.090826,0.326929,-0.002175,0.100429,-0.120202,-0.039476,0.174988,0.232778,0.328875,0.214358,-0.104237,0.192464,-0.362666,0.149076,0.542734,-0.089222,-0.463086,0.186930,-0.224557,-0.384946,-0.118735,0.007672,-0.375015,0.140319,0.266678,0.115835,0.022865,0.362627,-0.682149,0.005390,-0.292301,-0.194050,-0.125798,0.030518,-0.148623,-0.982431,-0.200634,-0.146396,-0.245249,-0.085911,0.007004,-0.017876,0.492643,-0.509169,0.555459,0.351621,0.293680,-0.119570,0.347106,-0.325935,0.195160,-0.233901,-0.322030,0.704042,0.139947,0.115578,-0.137733,0.174751,-0.155632,0.017260,-0.269368,0.541800', '26365262', '20274039', '24751811', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308074', '回归', '剧情', '消失了12个年头之后，父亲重新回到家中，而两个儿子——安德列（Vladimir Garin 饰）和伊万（Ivan Dobronravov 饰）已经长大。他们虽时时刻刻思念父亲，然真正相会时却产生了隔膜感。父亲带着两个儿子去俄罗斯北部的小岛度假，一路上他们遇到各种困难， 父亲皆能轻松解决，然而父子间的距离却始终没有拉近。他对待儿子们格外严厉，大儿子安德列对此只能小心应付，小儿子伊万却桀骜不驯。这次旅行，是否能成为父子间的疗伤之旅呢？本片荣获2004年金球奖最佳外语片提名、2003年俄罗斯影评人协会最佳剧本、最佳新人和最佳电影奖，2003年威尼斯电影节最佳处女作、金狮奖等。©豆瓣', '弗拉迪米尔·加林', '安德烈·兹维亚金采夫', 8.6, 27111, 'tt0376968', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2493692221.jpg', 0.3, 1, 10.7, 42, 46, '-0.246199,-0.061722,-0.654220,0.598098,0.287967,-0.423914,0.403365,0.118746,-0.730197,-0.365845,-0.096549,0.837110,-0.145714,0.156991,0.165119,-0.257184,-0.496282,-0.604741,-0.007000,-0.280244,-0.095452,-0.253155,-0.486701,0.044469,-0.422694,-0.192363,0.511186,-0.069696,0.090537,0.657439,0.322714,-0.025884,-0.079930,0.296710,-0.204045,-0.057937,0.394231,0.109748,-0.471610,0.417815,0.189438,-0.015840,-0.440818,-0.000111,0.254328,0.336226,0.707954,-0.021556,-0.111311,0.003130,0.243712,-0.312261,-0.223219,0.112647,0.038947,-0.154979,0.399294,0.253393,-0.090796,0.004295,-0.061137,-0.413421,-0.476250,0.307532,0.026191,-0.015956,-0.412625,0.241032,0.042109,0.119472,-0.151023,-0.313346,0.307165,0.456510,0.246298,0.324974,-0.379631,0.079913,-0.255811,0.296563,0.788608,-0.062289,-0.323786,0.201715,-0.161148,-0.430453,0.172329,-0.418573,-0.427102,0.129304,0.404194,0.270105,0.136121,0.064037,-0.285088,-0.062382,-0.288406,-0.108690,0.213762,-0.431790,0.207051,-0.785679,0.034286,-0.412768,-0.387855,0.059214,-0.088058,-0.316331,0.719694,-0.494852,0.449460,0.334899,0.084594,-0.479449,0.770780,0.185014,0.284459,-0.368401,-0.150227,0.246683,-0.330151,-0.064935,0.053793,-0.022571,-0.191315,-0.270678,-0.172418,0.260482', '1829654', '30162520', '4301278', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308076', '蓝宇', '剧情', '陈捍东（胡军）和蓝宇（刘烨）的爱情始于一场性交易，其时，蓝宇是为生活所迫决定出卖自己肉体的清纯大学生，陈捍东则是情场老手，惯做“花花公子”的他虽对特别的蓝宇怦然心动，却也认为蓝宇不过是他众多玩伴中的一个。慢慢地，随着两人交往的深入，陈捍东发现自己的心已在不知不觉间被蓝宇充满。可是他又不敢肯定，试图通过与女人结婚证明自己的“正常”，当求证到那不过是错觉一场时，蓝宇早已消失在茫茫人海。真正的爱情故事总是令旁观者唏嘘感叹，无论它是异性间还是同性间的。而令旁观者感动的爱情，往往又是同勇敢、固执、单纯等简单却难拥有的质量联系在一起的，蓝宇（和捍东）正属稀少的那类人，所以他们的爱情才显珍贵。©豆瓣', '胡军', '关锦鹏', 8.4, 283747, 'tt0292066', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p471812775.jpg', 0.2, 1.1, 15.2, 45.1, 38.5, '0.430679,0.135545,-0.810090,0.501031,-0.307139,-0.215746,0.931262,-0.185872,-0.555617,-0.123346,0.187651,0.779718,-0.176194,0.144108,0.087687,-0.046121,0.032016,-0.650327,-0.093711,-0.149974,-0.019052,-0.362280,-0.506460,-0.065352,-0.409934,-0.052986,0.789079,0.218553,-0.352023,0.366926,0.406689,0.191498,-0.031682,0.537645,-0.214173,-0.245568,-0.109294,0.360334,-0.340822,-0.121975,0.086292,-0.140031,-0.253820,0.291932,-0.196789,0.377389,0.525962,-0.176539,-0.305267,0.218953,0.467055,-0.205749,-0.290710,-0.025678,0.112875,0.095138,0.104594,-0.033843,-0.165035,-0.046755,-0.097889,0.224064,-0.952394,-0.135295,0.324008,0.045183,-0.444943,0.551209,0.262381,-0.216949,0.149628,-0.325641,0.089418,0.187671,0.365947,0.552574,-0.118365,-0.066174,-0.222747,0.148918,0.911967,0.504144,-0.509066,0.617697,-0.457664,-0.537630,0.032956,-0.176320,-0.569743,-0.094205,0.046794,0.130518,-0.192435,0.250674,-0.523192,0.212236,-0.140375,0.056870,-0.068376,-0.684140,0.003550,-0.200638,-0.355183,-0.860094,-0.345980,0.092470,0.132362,-0.614278,0.726916,-1.071188,0.033420,0.569687,0.046085,-0.445789,0.656426,0.354875,-0.139597,-0.261526,-0.214225,0.339601,-0.144867,-0.069626,0.044766,0.359762,0.094193,0.153752,-0.489165,0.535166', '1296370', '35030151', '24756472', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308077', '青春', '剧情', '正读高三的志孝（金来沅 饰）从首尔转校来，就与美丽的女学生汉娜（尹智慧 饰）谈起了恋爱。热恋中的两人发生了关系，可是两人的关系并没有进一步发展，而是深感不安。志孝因此有意无意的躲着汉娜，受到冷落的汉娜也十分伤心。没想到汉娜竟然用死来让男友永远记住自己。此后，志孝开始对男欢女爱感到反感，越来越放纵自己了。志孝的好友苏永（金正铉 饰）深深喜欢上了自己的老师，但老师与学生之间的鸿沟太大了。长大后的两人，有着各异的性格与各异的生活态度。©豆瓣', '金来沅', '郭志均', 6.6, 6722, 'tt0266855', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2290529821.jpg', 2, 10.4, 52.3, 26.4, 8.8, '0.598323,-0.284405,-0.677274,0.627549,0.039355,-0.312929,0.940209,0.037429,-0.678847,-0.111472,-0.129901,0.656802,-0.482415,0.344343,0.302047,-0.206703,-0.115881,-0.845990,-0.032070,-0.107655,-0.220502,-0.613974,0.030747,0.085414,-0.362996,-0.160585,0.561760,-0.202500,-0.299961,0.623955,0.348754,0.086682,-0.018086,0.714115,0.005560,0.007091,-0.207201,0.314352,-0.085539,-0.150740,0.242155,-0.183226,-0.059885,0.182285,0.093467,0.306119,0.717016,-0.256439,-0.305500,-0.063945,0.403349,-0.039112,-0.109423,0.334881,0.375473,0.074578,0.188687,0.122836,-0.062241,-0.039596,0.045231,-0.030602,-0.554418,0.211865,0.135893,0.107158,-0.419964,0.632412,0.198115,-0.412767,0.181758,-0.268420,0.170678,0.409184,0.406662,0.176727,-0.405655,-0.103768,-0.245957,-0.003651,0.695784,0.259634,-0.246894,0.307553,-0.522215,-0.450599,-0.233192,-0.121254,-0.595515,0.039017,-0.011315,0.258107,-0.250381,0.410689,-0.622714,-0.057044,-0.047252,0.031344,0.011356,-0.645415,0.167293,-0.431403,-0.213004,-0.824069,-0.598091,0.068199,0.106980,-0.448397,0.724644,-1.094634,0.142499,0.216200,0.497697,-0.465960,0.723607,0.210244,0.068701,-0.105614,-0.312552,0.255455,-0.058958,0.040953,0.110449,0.457970,0.078743,-0.105773,-0.076806,0.351194', '1308755', '1292219', '35030151', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308078', '紫日', '剧情', '二战即将结束时，忠厚老实的中国老百姓杨玉福（富大龙）被苏联红军从日本人的屠刀下救出。向后方转移的路上，苏军误入日军军营，一场激战过后，杨玉福和女军医娜佳（安娜•捷尼拉洛娃）逃进林区，碰上与日军失散的少女秋叶子（前田知惠）。由于一直被灌输军国主义思想，秋叶子一心要置杨玉福和娜佳于死地。几次险境过后，娜佳无法忍受秋叶子的作为，让杨玉福杀了她，但后者不忍下手。茫茫林区里，语言不通的三人经过一系列磨难，渐渐产生情谊，秋叶子意识到自己之前行为的荒谬，展露出纯真一面。然而，欢笑只是暂时，战争并没将他们遗忘，悲剧在不久后发生。©豆瓣', '富大龙', '冯小宁', 8.4, 61792, 'tt0303260', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1946863252.jpg', 0.4, 1.4, 14, 43.6, 40.5, '0.397286,0.202319,-0.508415,0.206827,0.339788,-0.029216,0.644304,-0.150517,-0.477944,-0.158693,-0.002742,0.399687,-0.181064,0.111596,0.117442,-0.168469,-0.469540,-0.802146,-0.171798,-0.038991,-0.332986,-0.365006,-0.030323,-0.020571,-0.294207,-0.315319,0.581482,0.394313,-0.216932,0.667872,0.068462,0.304813,-0.187598,0.917593,0.261264,0.350574,-0.189377,-0.248115,-0.405848,-0.077558,0.072447,-0.339347,-0.413852,0.223042,0.079857,0.437296,0.947766,-0.432196,0.020196,-0.423054,0.405704,-0.455385,0.001814,0.199380,0.504444,-0.229645,0.018566,0.043737,-0.136568,0.023228,-0.038848,-0.037477,-0.291978,0.117585,-0.153211,-0.128133,-0.572995,0.126265,0.378631,0.399294,0.105081,-0.107973,0.236633,0.404384,0.342540,0.010398,-0.410596,-0.116302,-0.238198,0.026966,0.895891,0.079002,-0.014947,0.105061,-0.201891,-0.524027,0.029180,-0.102478,-0.309599,-0.014227,0.432830,-0.062397,-0.320090,0.127983,-0.458482,-0.274032,-0.570066,-0.163321,0.035181,-0.452299,-0.463523,-0.301780,-0.081730,-0.510823,-0.458322,0.260477,-0.285220,-0.111642,0.497164,-0.760216,0.151955,0.541557,0.179995,-0.171079,0.218426,0.007872,-0.009210,-0.062938,-0.075143,0.740335,-0.254108,0.192633,0.335980,0.258142,-0.217800,0.228882,-0.164653,0.293446', '1301022', '21348112', '26418093', '1299433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308086', '昨天', '剧情', '本片是对演员贾宏声在上世纪九十年代整十年不堪回首岁月的真实再现，并由贾宏声本人及其家人回归各自相应身份参与回首。贾宏声本是年轻有为的优秀演员，从1987年到1993年，他主演了《夏日的期待》、《银蛇谋杀案》、《北京你早》和《周末情人》等将近十部电影，渐渐小有名气。这期间，他接触并疯狂爱上了摇滚乐，视BEATLES乐队的约翰•列侬为精神之父，然而同时，他也接触了并非摇滚精神内核的大麻和软性毒品。自此，他不再接戏，性格变得极端、偏执和歇斯底里，无法再与其他人相处。其远在东北四平的父母为了不让儿子继续沉沦，提前退休把整个家搬到北京，随后的一切，都像一场似乎没有尽头的战争。贾宏声于2010年7月5日下午坠楼身亡，时年43岁。©豆瓣', '贾宏声', '张杨', 8.6, 36619, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2871315616.jpg', 0.5, 1.2, 11.4, 39.9, 47, '0.160924,-0.106213,-0.665167,0.223902,-0.086761,-0.269937,0.563502,0.000102,-0.804918,-0.342083,-0.151695,0.700631,-0.331289,0.260213,0.223990,-0.260174,-0.258955,-0.868657,-0.227868,-0.231796,-0.052656,-0.330479,0.040917,-0.082876,-0.121993,-0.402153,0.594540,0.089248,0.062035,0.650947,0.176593,0.161871,0.019409,0.301116,-0.038406,-0.056178,-0.083709,0.148367,-0.431759,0.199303,0.123468,-0.406384,-0.072498,-0.005781,-0.052479,0.328444,0.618157,-0.009750,-0.210551,-0.144926,0.552778,-0.170533,-0.397933,0.132421,0.310193,0.020624,0.247479,0.665087,-0.109384,-0.060495,-0.288639,-0.234949,-0.565159,0.247492,-0.022322,0.074667,-0.422944,0.599111,-0.127264,-0.034423,-0.010778,-0.256409,0.229324,0.300563,0.124648,0.460860,-0.300777,-0.069963,-0.227907,0.570709,1.021803,0.135936,-0.324619,0.563367,0.023390,-0.529167,-0.261763,-0.395946,-0.379181,0.157784,0.022377,0.298518,-0.154804,0.375137,-0.572689,0.124679,0.070846,-0.309076,0.262137,-0.253122,0.000901,-0.441429,-0.411467,-0.661537,-0.021300,0.009527,0.101322,-0.318427,0.643544,-0.759414,0.360044,0.410045,0.353609,-0.527017,0.779963,-0.023833,-0.064432,-0.159578,0.325930,0.331695,-0.176043,0.229462,0.104295,0.136305,-0.068637,0.030330,-0.298698,0.421954', '25721544', '35030151', '1870682', '3212120');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308101', '处女心经', '剧情', '电视台里，编剧秀贞（李恩珠 饰）爱上了有妇之夫的制片永硕（文成根 饰）。永硕的独立电影需要投资，秀贞便与永硕来到了永硕朋友杰勋（韩明求 饰）的画廊。这位朋友却对秀贞很感兴趣，更希望秀贞能成为自己的女朋友。秀贞开始与杰勋交往，一开始相处还算融洽，不久杰勋便想进一步与秀贞发展。仍是处女的秀贞对于性这件事颇为介意，杰勋见无法进一步得到秀贞，大感无奈。秀贞一直爱着的永硕也对秀贞示爱了，秀贞不知该把自己的身体交给哪一个男人。©豆瓣', '李恩珠', '洪常秀', 7.2, 9507, 'tt0253378', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p606117883.jpg', 1.6, 6, 36.9, 42.4, 13, '0.180217,-0.117252,-0.487240,0.476661,-0.089519,-0.360958,0.373689,-0.049753,-0.527501,-0.410499,-0.060688,0.720456,-0.370646,0.343833,0.133495,-0.016248,-0.076421,-0.628694,0.255501,-0.150416,-0.246514,-0.487209,-0.157676,0.096336,-0.502712,0.129026,0.620545,-0.030191,-0.056449,0.346848,0.315608,0.143252,0.005860,0.650272,-0.079533,0.089625,-0.253494,0.145987,-0.505085,0.120272,0.227696,-0.002586,0.058068,0.152851,0.277574,0.082195,0.217465,0.139740,-0.353968,0.081397,0.249879,-0.044135,0.139577,-0.164978,0.136623,0.104121,0.298735,0.274176,-0.194169,0.013137,0.021684,-0.246286,-0.532656,0.227543,0.181512,0.075037,-0.690699,0.073561,-0.239996,-0.044370,0.079394,-0.437320,0.326724,0.535132,0.538699,0.524308,-0.201653,0.319131,-0.380193,0.272018,0.533951,0.344369,0.095495,0.457173,0.077361,-0.412471,-0.231048,0.138904,-0.438376,0.047025,-0.023668,0.287411,-0.003874,0.167992,-0.369888,0.237609,0.243282,-0.108729,-0.020932,-0.518099,0.481070,-0.138106,-0.265335,-0.516918,-0.094268,0.113845,0.288804,-0.464543,0.640334,-0.838938,-0.009462,0.035925,0.409594,-0.830554,0.636136,0.204968,-0.174463,-0.430586,-0.024893,0.163943,-0.307901,-0.104832,0.024306,0.386119,0.213643,-0.765961,-0.518915,0.043095', '1418613', '1299649', '1410695', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308110', '飞龙再生', '喜剧', '《飞龙再生》由英皇多媒体集团（EMG）投资及制作，制作经费高达3亿港元，破香港影坛纪录。传说只要得到“再生龙章”的力量，死后便变成永远不灭的“不死人”。国际人蛇集团主脑“蛇魔”要绑架神秘华籍小孩Jai，其手下李斯（黄秋生 饰）与香港特警阿狄（成龙 饰）两度交锋，最终掳走Jai。阿狄远赴爱尔兰追捕李斯，在前女友妮歌（克莱尔·弗兰妮 Claire Forlani 饰）穿针引线下，到英国与屈逊（李·伊万斯 Lee Evans 饰）再度携手合作。查得李斯的货船抵达码头，众人一番混战后，舍身保住Jai的性命，自己却被淹死。而Jai身上的铁章却让另一个阿狄出现，并且拥有伤口瞬间自愈的能力，而且自己已经拥有超乎常人的体能。但“蛇魔”再次将Jai掳去并夺去他的“龙章”，获得了再生力量，超能力已超越阿狄……©豆瓣', '成龙', '陈嘉上', 6.1, 23421, 'tt0288045', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1971070670.jpg', 3.2, 18.4, 56.7, 16.2, 5.5, '-0.286688,0.351841,-0.589425,0.580288,0.035134,-0.309271,0.390093,0.123677,-0.174506,-0.280137,0.269199,0.570455,-0.041157,0.028988,0.055387,-0.211300,-0.103923,-0.572768,0.104246,0.032526,-0.452927,-0.107576,-0.357931,-0.101807,-0.199157,-0.335067,0.725858,0.211613,-0.227407,0.142020,0.079158,0.390256,-0.196470,0.456607,-0.293508,0.092392,-0.135953,-0.141023,-0.205449,0.378214,-0.148942,-0.082879,0.095888,0.063221,-0.106629,0.059280,0.602614,-0.316350,0.134353,-0.421311,0.291739,-0.309845,0.102481,-0.191983,0.293086,0.060285,0.210380,0.009354,-0.333390,-0.121755,0.166258,0.024139,-0.921061,-0.095128,0.095443,0.016106,-0.378860,-0.072567,-0.218071,0.297910,-0.107961,-0.123713,-0.114356,0.254439,0.218272,0.183862,-0.040572,0.083442,-0.650607,-0.021036,0.686552,-0.187242,-0.283447,0.093210,-0.038374,-0.558726,-0.257959,-0.418492,0.228125,0.006334,0.385612,0.158150,0.176772,0.290634,-0.566868,-0.367888,-0.362508,0.165625,-0.014208,-0.182353,0.145593,-0.594181,-0.130921,-0.074479,-0.163470,0.131552,0.378844,-0.344878,0.340016,-0.494327,0.052143,0.342644,0.364059,-0.438674,0.456840,-0.423869,0.224235,-0.173152,-0.195428,0.337417,0.388880,0.208282,0.130133,0.147505,-0.044682,-0.022593,-0.332504,0.354099', '1793491', '27073234', '7051375', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308111', '钟无艳', '喜剧', '春秋战国时期，一向昏庸好色的齐宣王（梅艳芳饰）误闯夜叉山，碰上了美丽的寨主钟无艳（郑秀文饰），齐宣王决定把钟无艳娶为皇后，可是一直倾心于钟无艳的“狐狸精”（张柏芝饰）出手阻挠，只要钟无艳爱上其他的人，脸上便会无缘无故多出一块难看的红斑。狐狸精后来化身夏迎春勾引齐宣王，齐宣王终日沉醉温柔乡。而钟无艳为了夫君出生入死、南征北战。齐宣王只会有事求助于钟无艳时才好言相向。齐宣王十分好赌，竟然把钟无艳作为作为筹码输掉了，钟无艳愤怒离开，脸上红斑也自然消失。夏迎春得逞后也离开了皇宫，齐宣王才发现自己最爱为何人，浪子回头。在受到叛徒攻击时，还是爱着齐宣王的钟无艳，赶到了皇宫，帮忙驱走外敌……©豆瓣', '郑秀文', '杜琪峰', 7, 95950, 'tt0272362', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p549909097.jpg', 1.1, 6.8, 45.2, 34.4, 12.5, '-0.197548,0.084111,-0.345156,0.358356,-0.086835,-0.373697,0.389420,0.260822,-0.411395,-0.301941,0.146537,0.458476,-0.326786,0.182980,0.105553,0.004249,0.093899,-0.297499,-0.218621,-0.131625,0.059393,-0.015061,0.122318,-0.331053,-0.086047,-0.025315,0.464027,0.175004,-0.144240,0.200991,0.534387,0.061970,-0.243710,0.535778,0.050730,-0.158755,-0.478396,-0.126368,-0.163697,0.107862,-0.042600,-0.243002,-0.278328,-0.027428,-0.190268,0.026978,0.320389,-0.273235,-0.112753,-0.442112,0.481358,-0.166432,0.071297,0.114129,0.163902,-0.280157,0.261455,0.186990,-0.115000,0.127389,0.215347,-0.225763,-0.306592,0.237436,-0.015850,-0.203793,-0.395170,0.170951,-0.018647,-0.034238,0.045079,-0.263227,0.542301,0.215848,0.254626,-0.014229,-0.279233,0.102492,-0.349037,0.102577,0.378204,0.103834,0.065894,-0.087505,0.331339,-0.325692,0.300913,-0.336362,-0.159552,0.106067,0.160900,-0.083473,-0.004897,0.075461,-0.255921,-0.416990,-0.348262,0.302858,0.075253,-0.208857,0.038803,0.045006,-0.151026,-0.116249,-0.377443,0.213524,0.135891,-0.082357,0.478449,-0.567951,0.307730,0.235706,0.467997,-0.677672,0.421449,0.058559,-0.234534,-0.156171,-0.279195,0.470074,0.139271,-0.115487,-0.005909,-0.129204,-0.225208,-0.067695,0.008989,0.144724', '1305915', '1308206', '2153579', '2135981');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308120', '暗战2', '动作', '高级督察何尚生（刘青云）被劫持人质的劫匪伊健（郑伊健）点名到案发现场进行谈判，眼见伊健在现场的嚣张，何尚生斗意昂扬欲将其拿下，但被其逃脱。挫败激起何尚生的战意和好奇心，开始同伊健玩起“取赎金的游戏”来。何尚生收到伊健寄来的数件艺术品的残骸，在国际刑警Ruby（黄卓玲）的帮助下发现被破坏艺术品均在同一间国际级保险公司承保，猜想伊健意图勒索该保险公司，遂前往展开调查，而此时伊健恰好致电该公司高层Teresa（林熙蕾）勒索一千万，尚生即刻接手案件，却发现事情远非想象的那么简单。©豆瓣', '郑伊健', '杜琪峰', 6.6, 45015, 'tt0295578', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2430567742.jpg', 1.8, 11.3, 49.6, 28.1, 9.1, '0.473409,0.179381,-0.776171,0.152553,0.108311,-0.041488,0.437389,0.078951,-0.202508,-0.201269,0.256699,0.434232,-0.362087,-0.120034,0.258930,-0.226350,-0.109419,-0.546426,-0.076857,-0.061827,-0.072687,-0.502346,-0.164424,-0.173865,0.065949,-0.155487,0.478073,0.129978,-0.289529,0.596373,0.467037,0.419625,-0.243706,0.575642,0.022985,-0.188785,0.146873,0.000296,-0.340903,0.379492,-0.053572,-0.258526,0.110943,0.243001,-0.153653,0.533776,0.589717,0.073059,-0.248907,0.148089,0.475046,-0.285531,0.207148,0.145232,0.411114,0.434103,-0.236954,0.124623,-0.558754,0.059370,0.178835,-0.008890,-0.511403,-0.133097,0.034780,0.199536,-0.373996,-0.012312,-0.341344,0.231082,0.071906,-0.240714,-0.004491,0.364785,0.091679,0.180988,0.167561,-0.016062,-0.562934,0.139904,0.593192,-0.263687,0.262084,0.164163,0.152515,-0.583404,0.068099,-0.318846,0.034290,-0.019727,0.363020,0.092159,0.093779,-0.052074,-0.465796,-0.464794,-0.206514,0.100835,-0.233224,-0.300433,-0.128361,-0.646978,-0.164327,0.132129,-0.437554,0.176032,0.349914,-0.302445,0.289841,-0.620825,-0.054011,0.431864,0.299251,-0.534476,0.146303,-0.120259,-0.109870,-0.059441,-0.405490,-0.043628,0.663680,0.389985,0.179057,-0.006501,-0.223691,-0.564085,-0.233971,0.054938', '1296947', '25908042', '35073886', '2357711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308127', '鲸骑士', '剧情', '佩（凯莎·卡斯特-休伊斯 Keisha Castle-Hughes饰）是新西兰海岸上古老部落的酋长孙女。母亲曾经诞下龙凤胎，但不幸她和男婴都死去了，心灰意冷的父亲远走他方，剩下孤女佩给祖父母抚养成人。奶奶非常疼爱佩，而酋长寇罗（拉维里·帕拉特恩Rawiri Paratene饰）却一度认为孙女是不祥之人。现今更令寇罗头痛的是继承人的问题。这个部落的有着严格的信条：继承人必须是男性。而眼看自己的儿子无法继承家业，寇罗万分苦恼。他从族人中间选出壮健男子，希望可以培养成为领袖，结果很不如意。而他的孙女佩，却在练习各式武艺，一心要接过爷爷的担子。寇罗却执意遵从族人规条，不允许女性当上领袖位置。直到一条鲸鱼搁浅在此处的海岸，事情才开始峰回路转。佩凭着出色的勇气和能力，让爷爷改变了决定。©豆瓣', '凯莎·卡斯特-休伊斯', '妮琪·卡罗', 8, 7529, 'tt0298228', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318519841.jpg', 0.3, 1.9, 22.2, 49, 26.6, '-0.171075,0.063268,-0.685997,0.800198,-0.160909,-0.351958,0.478081,0.168168,-0.796101,-0.354937,0.286330,0.890974,0.543713,0.382511,0.209383,0.235708,-0.003609,-0.469980,0.048293,-0.133846,-0.329602,-0.488635,0.021483,-0.405438,-0.187556,-0.554178,0.833346,-0.017385,0.017718,0.237848,0.311442,0.285548,0.035455,0.248546,-0.302049,-0.189205,-0.174783,0.019562,-0.276360,-0.070930,0.045196,-0.042875,-0.056352,0.371762,0.111441,0.422734,0.508895,-0.457582,-0.012700,-0.476105,0.245635,-0.101302,-0.011350,0.110202,0.462498,-0.121024,0.231969,0.304125,0.022125,-0.497755,0.019329,-0.132394,-0.573452,-0.163494,0.434012,0.169305,-0.853625,0.471670,-0.196270,-0.000905,0.055569,-0.300767,0.162808,0.142593,0.042411,0.378796,-0.102003,0.147316,-0.376995,0.074585,0.537064,-0.133273,-0.185887,0.029087,-0.356378,-0.541449,0.299295,-0.673480,-0.566643,0.093864,0.239476,0.291327,0.107480,0.289616,-0.157557,0.040582,-0.352425,0.003203,0.338230,-0.609464,0.143432,0.180739,0.141159,-0.224747,-0.224851,0.166534,-0.012469,-0.369464,0.939921,-0.622358,0.048930,0.278699,0.281387,-0.573894,0.694860,-0.055533,0.245311,-0.540720,-0.021888,0.298307,-0.068690,-0.193033,0.026202,-0.026936,0.119579,-0.167708,-0.268112,0.429571', '26593587', '1870681', '35048413', '1456503');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308129', '赌侠大战拉斯维加斯', '喜剧', '合力击败马交文之后，king（刘德华 饰）与化骨龙（张家辉 饰）联合化骨龙的表哥阿叻（陈百祥 饰）骗取了恶人大眼文一笔钱。当他们打算享受一番之际，大眼文把化骨龙抓走了。King与阿叻则被警方带到与中方高层见面，他们被派往拉斯维加斯捉拿大老千Peter朱（万梓良 饰）。为了得到巨款拯救化骨龙，king接受了这次任务，前往拉斯维加斯。在拉斯维加斯，小心（郁芳 饰）与阿扁（林熙蕾 饰）一心想找到金龟婿，后来加入了king的老千行列。终于他们遇到了Peter，两人互相欺骗更多次交手，敌意渐生。King用阿扁做饵勾引Peter成功，他们经由沙漠公路到洛杉矶，途中Peter极力逃脱。众人在沙漠奋力搏斗。Peter的手下竟然用直升机拯救，幸好king神机妙算，顺利把Peter带回香港。©豆瓣', '刘德华', '王晶', 6.4, 34837, 'tt0208871', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2355305020.jpg', 2.2, 12, 55.3, 22.5, 8, '-0.047518,0.152292,-0.700249,0.320365,0.004995,-0.183709,0.183223,-0.111227,-0.349485,-0.005600,0.145411,0.651819,-0.278921,-0.096115,0.371115,-0.277693,-0.338298,-0.602125,0.168039,-0.026640,-0.259146,-0.281223,-0.247607,-0.047703,-0.070882,-0.131944,0.359824,0.270510,-0.248014,0.656647,0.422678,0.338133,-0.422853,0.321752,-0.123179,0.080265,0.281979,0.024197,-0.542203,0.547337,-0.179444,-0.297011,-0.137067,-0.055606,0.156981,0.363049,0.687280,-0.078008,-0.094882,-0.039049,-0.100024,-0.529576,-0.000637,0.073515,0.193370,-0.057100,0.254578,0.277691,-0.369489,0.085718,0.258231,-0.192340,-0.713383,0.196169,0.056395,-0.332436,-0.632925,-0.133808,-0.156188,0.166712,0.025769,-0.268374,0.271523,0.447591,0.332638,0.033892,-0.114097,0.029869,-0.596117,0.182118,0.890235,-0.292801,0.436002,-0.032799,0.541268,-0.324097,0.236991,-0.300160,0.156789,0.068272,0.751892,-0.054313,-0.132447,-0.163807,-0.630831,-0.420573,-0.321700,-0.126014,0.337053,-0.419861,0.206606,-0.657129,-0.046017,-0.010896,-0.169096,0.228724,0.156487,-0.175476,0.339412,-0.570054,0.047026,0.449754,0.480113,-0.725132,0.538033,0.015375,0.094587,-0.102002,-0.087633,-0.257931,0.500729,0.379105,0.556411,0.139721,-0.166493,-0.127893,-0.309421,-0.113210', '25908042', '3147969', '2084048', '1307704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308146', '光阴的故事', '剧情', '该片被誉为台湾“新电影”的开山之作。四位导演拍摄的四段故事（《小龙头》、《指望》、《跳蛙》、《报上名来》）构成了童年（小学）、少年（中学）、青年（大学）、成年（社会）四个人生时期（阶段）。每个阶段都有相应的梦幻世界的快乐和现实世界的烦恼，只是随着年岁增长，两者比例会有所变化。童年因某个好伙伴的离去而忧伤的小朋友（《小龙人》），成人结婚后的烦恼，可能会是因钥匙丢在房里只能穿着短裤在外面晃动（《报上名来》）。而青春期时被帅气强壮的大学生房客吸引了目光的女孩（《指望》），进了大学未尝不会变成另一种模样（《跳蛙》）。——人生充满多种可能，阶段的人生也没有好坏之分，只过就好。©豆瓣', '张艾嘉', '杨德昌', 7.7, 14295, 'tt0085626', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2298312787.jpg', 0.2, 1.7, 28, 54.6, 15.5, '0.154933,0.101183,-0.531142,0.281182,-0.302566,-0.107397,0.664348,0.268052,-0.392608,-0.134251,0.070867,0.659237,-0.028486,0.417385,0.219558,-0.217221,0.000179,-0.557219,0.034196,-0.301548,-0.341852,-0.063425,-0.168610,-0.034970,-0.085273,-0.608830,0.841511,0.106957,-0.176598,0.403389,0.211280,-0.075211,-0.060002,0.200107,-0.351736,-0.051598,0.040600,0.168144,-0.127705,0.063456,-0.196237,0.248110,0.033043,-0.003378,-0.197164,0.007504,1.103660,0.143740,-0.246745,-0.018206,0.699922,0.357783,-0.390951,-0.142177,0.428876,0.014681,0.298130,0.062017,0.268857,0.039164,-0.199875,-0.212855,-0.500102,-0.072618,0.124229,0.222243,-0.306500,0.488770,0.291652,-0.246199,0.228932,-0.166340,-0.125361,0.117436,0.579360,0.619126,0.123498,0.044044,-0.311580,0.513855,0.394638,-0.146099,-0.677335,0.532231,-0.454663,-0.394937,-0.418366,-0.293279,-0.476805,0.076255,0.281136,0.141597,-0.450037,0.314161,-0.322245,0.421556,-0.064461,-0.103417,0.126042,-0.363792,-0.253024,-0.234617,0.045117,-0.436014,-0.372385,-0.013049,0.183601,-0.208022,1.014539,-0.755237,0.182402,0.378945,0.159440,-0.359741,0.925913,0.102082,0.172117,-0.463065,0.154358,0.215855,-0.512917,-0.008495,-0.192367,0.281242,-0.334448,0.041895,-0.445652,0.557292', '10174444', '3811356', '25882279', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308156', '的士速递3', '喜剧', '圣诞节期间，一伙盗贼假扮圣诞老人大肆行窃，对此，警察局长吉伯（伯纳尔·法西）决定亲自部署清剿活动，而此时一个混血记者秋（白灵）来到警局采访，时时黏在他身边，处处问寒问暖。警察艾米（佛瑞德瑞克·迪分索 ）正为案件烦心，不想女友贝特拉捧着怀孕八个月的肚子驾到。艾米和好友丹尼尔（萨米·纳塞利）在出租车里倾诉一夜，原来丹尼尔的女友莉莉也怀孕了。就在他们决定为了爱情收山归心时，犯罪团伙的马脚露到了他们面前。他们一路追击，不想艾米再次跌入垃圾桶。艾米被犯罪团伙绑架，再次睁眼时，眼前正是那个美丽的混血记者......©豆瓣', '萨米·纳塞利', '热拉尔·克瓦兹克', 7.4, 37400, 'tt0295721', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2529661996.jpg', 0.5, 4, 37.7, 42.5, 15.3, '0.578557,-0.171135,-0.493917,0.014502,-0.174524,-0.535677,0.526647,0.170333,-0.498388,-0.257672,0.141084,0.369742,-0.549835,0.195828,0.410811,0.162889,-0.644910,-0.557652,0.009254,-0.149450,-0.064540,-0.276889,-0.082571,-0.327135,-0.042025,-0.096329,0.311270,-0.265636,0.148373,0.588548,0.420806,0.186796,-0.287324,0.424940,0.110369,0.119462,0.497177,-0.404536,-0.150671,0.293038,-0.166910,-0.043640,-0.183554,0.198081,0.111139,0.169970,0.613864,-0.229065,0.096112,-0.230859,0.159812,-0.494415,0.187739,0.103650,0.476920,-0.077809,0.504659,0.025349,-0.086378,-0.216538,0.198014,-0.073594,-0.001064,0.265904,-0.186844,0.008667,-0.428640,0.135203,-0.353064,0.334125,0.378083,-0.388315,0.130545,0.454801,0.106361,0.187108,0.030851,0.015523,-0.314549,-0.016302,0.398543,0.046586,0.388804,0.071370,-0.076580,-0.126585,0.141151,0.210164,-0.425270,0.032896,0.456985,-0.206428,-0.303397,0.279388,-0.218415,-0.191178,-0.604618,-0.004900,0.077168,-0.179651,-0.294525,-0.693233,-0.106857,0.128069,-0.011041,-0.002653,-0.139393,0.189298,0.147490,-0.565528,0.521900,0.699732,0.247426,-0.259827,0.434350,0.242350,0.046577,-0.285882,-0.183919,0.233315,0.169888,0.500943,0.096401,0.202988,-0.121317,-0.108577,-0.202141,0.093719', '1819460', '1309110', '2075345', '3735015');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308157', '机Boy小子之真假威龙', '喜剧', '黑社会大哥八爷身患绝症，弥留之际将社团事务托付给即将由意大利回港的义子九纹龙黄九弟（刘德华 饰），并委托兄弟七爷（吴孟达 饰）和保镖小朱（郭富城 饰）尽力辅佐。权利旁落令社团实力人物龙爷（袁和平 饰）和后起之秀啸天心中颇为不满。与此同时，在印度的机场，侏儒黄九弟与和其面貌一样，但是只有儿童心智的心算天才李小灵阴差阳错的交换了身份，李以九纹龙的身份被七爷和小朱接回，但是徒有成人外貌的李终日只将精力放在游戏上，李因手下的暴力行为被带入警局，心地善良的李与警方达成共识，承诺将社团改造为维护治安的力量。李对龙爷之女静莹（关之琳 饰）一见钟情，龙爷却趁此联络啸天，意图在婚礼期间置李于死地……©豆瓣', '关之琳', '陈嘉上', 6.4, 5958, 'tt0102155', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167122802.jpg', 3.1, 13.6, 53.3, 19.9, 10.1, '0.034488,0.176721,-0.341005,0.546545,-0.312840,-0.157782,0.335299,0.399363,-0.673181,-0.386336,0.210978,0.627567,-0.004376,0.114662,0.143391,-0.336907,-0.145208,-0.821610,-0.236806,-0.056558,-0.021344,-0.748778,-0.022720,-0.052908,-0.331824,-0.184904,0.702985,-0.285644,-0.199293,0.459616,0.438626,0.259909,-0.390231,0.283407,-0.145274,-0.160532,0.061801,-0.072852,-0.654138,0.102767,-0.001336,-0.307397,0.084465,0.139743,-0.020646,0.210324,0.696352,-0.147556,-0.059142,-0.318423,0.162920,-0.314342,0.057943,0.082559,0.363131,0.203934,0.300245,0.377887,-0.107135,0.036281,0.167267,-0.271406,-0.586864,0.040670,0.389498,0.079351,-0.552052,0.309050,-0.262474,0.038470,-0.036831,-0.404990,0.192569,0.337679,0.236316,0.212463,-0.176234,0.289487,-0.392048,0.076327,0.494742,0.014405,0.186723,-0.067679,0.031530,-0.541881,-0.087350,-0.217089,-0.135707,-0.028147,0.124357,0.041377,0.094193,0.282055,-0.545201,-0.154111,-0.168532,0.123908,0.127754,-0.505713,0.377822,-0.515479,-0.290265,-0.393065,-0.076452,-0.020007,0.536798,-0.024764,0.748467,-0.831258,-0.196011,0.127551,0.415807,-0.561057,0.527713,0.107746,0.208823,-0.366014,-0.178940,-0.166464,0.284596,0.186872,0.043314,0.179422,-0.067833,-0.332730,-0.347624,0.037142', '30345227', '4301278', '4127270', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308162', '女人，四十', '剧情', '家住旧楼、性情火爆的孙太阿娥（萧芳芳）每日奔走于家庭、公司之间，为家人、公司处处精打细算。她家中有做驾证考官的丈夫（罗家英）、正念大学的儿子（丁子峻）、待她若亲生女儿的婆婆及军人出身的臭脾气专横公公（乔宏）。丈夫弟妹一个住在富人区，一个远嫁台湾，平日与他们疏于联络。婆婆的突然病逝令公公变作痴呆老人，他脑里只有旧事若干、眼前只识阿娥一人，所做的荒唐事一件接连一件，阿娥一家疲于应对，在家安心做主妇的弟媳又不愿伸手相帮。阿娥与丈夫试过送公公去日间老人看护所、老人院，却一样不能省心。而给阿娥带来诸多乐趣的工作也因碰上年纪轻她、能力强她的对手令她烦心。但公公亦用自己的方式对人到40日渐有心无力的阿娥表示着感激。©豆瓣', '萧芳芳', '许鞍华', 8.9, 45088, 'tt0111767', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2441944656.jpg', 0.1, 0.4, 6.8, 39.5, 53.2, '0.093898,-0.155564,-0.279823,0.576438,-0.346445,-0.356337,0.602383,0.527289,-0.649932,-0.556313,0.154595,0.625744,0.211941,0.317192,-0.003049,-0.098299,0.169871,-0.212801,-0.028569,0.099961,0.187340,-0.168170,0.153390,-0.305964,-0.271163,-0.143050,0.174742,-0.272893,0.209856,0.133077,0.261838,0.088390,-0.036643,0.320128,-0.080388,0.062725,-0.257010,-0.008674,-0.355122,-0.200655,0.275790,-0.028529,-0.248144,-0.014556,0.165674,0.245869,0.468929,0.056763,-0.340695,-0.285078,0.614765,0.222534,0.213789,0.195985,0.166638,-0.064843,0.240898,0.120192,-0.160155,0.041721,0.102601,-0.031037,-0.523121,0.183303,0.458090,-0.231687,-0.563545,0.241534,-0.261338,-0.017055,-0.177441,-0.481898,0.092973,0.294424,-0.004113,0.393038,-0.318420,0.159245,-0.218690,0.441797,0.565231,0.011922,-0.056292,0.194935,-0.224385,-0.106884,0.315682,-0.498418,-0.712151,0.039534,-0.074895,-0.145000,-0.138478,0.217550,-0.054171,0.154305,-0.274785,0.062483,0.082272,-0.441899,0.011487,-0.173923,-0.010023,-0.384436,-0.299428,0.031296,0.457316,-0.106322,0.542304,-0.440143,-0.031635,0.359822,0.230341,-0.633726,0.683371,0.053056,0.423706,-0.224385,-0.141878,0.001368,-0.081553,0.113306,0.094036,0.123750,0.010023,-0.064248,0.024272,-0.018513', '24879820', '4004731', '5364952', '1421278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308174', '初缠恋后的2人世界', '剧情', '风格别致的伪自传片，由两个故事组成。第一个故事的主角是一个梦游少女（李维维 饰），她每晚梦游都会游走于不同的地方，一天她突发奇想在头上装了一个摄像头，于是她白天的所有事就变成了观看她与神经质男孩（金城武 饰）在夜晚的奇遇，渐渐地他们相爱了，但是各有问题的两个人能不能走在一起呢？第二段故事讲的是李一平（葛民辉 饰）经过了不成功的初恋，对初恋情人赵美娜（莫文蔚 饰）又爱又恨不能忘怀，他带着负罪感躲藏了多年，但是有一天还是被美娜发现了行踪，害怕被暗杀的一平陷入了焦虑。本片是葛民辉自导自演的处女作，值得一提的是本片的监制是王家卫，摄影是杜可风，编剧是日后转作导演的叶念琛，全片风格深得王家卫真传。©豆瓣', '葛民辉', '葛民辉', 7.8, 8311, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1997859181.jpg', 1, 4, 25.6, 44.1, 25.4, '0.141973,-0.241728,-0.503351,0.613193,-0.089858,-0.072667,0.764931,0.097143,-0.452933,-0.088672,0.239557,0.826312,-0.381748,0.261871,-0.123822,0.038537,-0.253257,-0.750223,-0.069640,-0.121944,-0.190465,-0.529018,-0.168408,-0.125780,-0.088125,-0.214246,0.449938,0.022193,-0.304498,0.097729,0.666400,0.060357,-0.145482,0.427669,-0.206526,0.061765,0.110296,0.101211,0.063133,0.211999,0.009445,-0.485964,-0.196240,0.169722,-0.233619,0.286928,0.701146,-0.042779,-0.193524,0.237301,0.344923,-0.275516,-0.333705,-0.019020,0.259550,0.004483,0.358117,0.165316,-0.160199,0.080476,0.110156,-0.080476,-0.651788,-0.074211,0.324499,0.396519,-0.718181,0.440173,-0.093170,-0.293141,0.100299,-0.259958,0.302887,0.039339,0.552585,0.461137,0.127245,-0.121102,-0.411897,0.327224,0.603883,0.079803,-0.236980,0.705026,-0.207892,-0.446408,-0.175626,-0.120000,-0.457083,0.205665,0.246691,-0.217964,-0.153803,0.032336,-0.595641,0.146786,-0.020956,-0.082556,-0.301052,-0.489923,0.009524,-0.310090,-0.088296,-0.609587,-0.215474,0.139123,-0.020942,-0.282359,0.815517,-0.739893,0.289236,0.529876,-0.053246,-0.529197,0.788423,0.343038,-0.263645,-0.169763,0.364615,0.043202,-0.260490,-0.020338,0.323208,0.529878,-0.018850,-0.142308,-0.570027,0.348197', '30162520', '3230462', '4301278', '1456503');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308191', '二手狮王', '剧情', '暑假刚刚开始，14岁的男孩沃尔特（海利·乔·奥斯蒙 Haley Joel Osment 饰）就在百般的不情愿中被母亲玫（凯拉·塞吉维克 Kyra Sedgwick 饰）打发到了位于乡下的两个伯父家，他们分别是贾斯（迈克尔·凯恩 Michael Caine 饰）和哈勃（罗伯特·杜瓦尔 Robert Duvall 饰）。初来乍到的沃尔特十分不习惯乡下的生活，对于两个个性古怪的伯父，他更是敬而远之。一张神秘的照片的出现拉近了沃尔特和伯父们的关系，追寻着照片里的线索，伯父们向沃尔特讲述起了他们当年的故事。那时一个充满了梦想和激情的年代，伯父们的故事为沃尔特打开了新世界的大门，与此同时，通过回忆往昔，贾斯和哈勃两个有故事的男人也找到了各自人生的意义和快乐所在。©豆瓣', '迈克尔·凯恩', '蒂姆·麦肯莱斯', 8.5, 16455, 'tt0327137', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1626609748.jpg', 0.3, 1, 13.8, 44.8, 40.1, '0.659854,-0.196351,-0.577761,0.681236,-0.307505,-0.448536,1.022672,0.096659,-0.610468,-0.375379,-0.085498,0.799166,-0.122881,0.476980,0.242124,0.137277,-0.413857,-0.724963,-0.141945,-0.260418,-0.183804,-0.627684,-0.288881,-0.126879,-0.138366,-0.331114,0.254447,-0.298411,-0.016377,0.681961,0.206405,0.409059,-0.180596,0.135747,-0.273186,0.229705,0.286501,0.149447,-0.410990,0.016345,0.083270,0.110191,-0.267200,0.116063,-0.039194,0.295034,0.723284,-0.248006,-0.086892,-0.031857,0.113315,0.042556,-0.110719,0.213274,0.150464,0.019564,0.178756,0.370068,-0.225740,0.046236,-0.141979,-0.026437,-0.611316,0.080658,0.182475,0.392875,-0.674074,0.482305,-0.174475,-0.306613,0.208682,-0.519114,0.234713,0.391295,0.136353,0.448183,-0.239013,-0.057412,-0.597820,-0.021177,0.571928,0.031715,-0.228323,0.616279,-0.336027,-0.233153,-0.137662,0.247223,-0.680206,-0.060676,0.483647,-0.117637,-0.056110,0.293174,-0.912609,-0.120242,-0.087117,-0.392274,0.081515,-0.458854,-0.128975,-0.615162,-0.416898,-0.740564,-0.292053,-0.009349,-0.093854,-0.261464,1.024501,-0.669672,0.209555,0.295691,0.063585,-0.246542,0.743645,0.237739,0.226133,-0.299428,0.071669,-0.014525,0.051893,0.102311,-0.017320,0.445394,-0.108122,-0.196321,-0.654263,0.713398', '26677495', '1307146', '5977789', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308197', '遇见波莉', '喜剧', '鲁本（本·斯蒂勒 Ben Stiller饰）的职业名称简直在讽刺他的性格——风险分析师。因为，鲁本是一个平凡甚至有点窝囊的人，不敢冒一丁点生活的险，可以说，他就像一辆僵直的列车，规规矩矩沿着铁轨开往人生终点。这样的人，生活还是要给他一点打击。本来可以和新娶的老婆平平静静过两口子生活，不料蜜月期就遭到婚变，可怜的鲁本亲眼看到老婆和一个法国肌肉男缠绵悱恻。懦弱的他，默默的回到自己原本一个人的生活，过去的阴影令这个男人更加灰心。波莉（詹妮弗·安妮斯顿 Jennifer Aniston饰）的出现，在他糟糕的人生里投下了一缕明快的阳光。波莉带着他尝试着这个世上种种的精彩之事，这些疯狂的举动，鲁本过去连想像的勇气的没有。如今，他像一个刚刚见识到世界如何缤纷多彩的孩子，在波莉的带领下重新发现了生活的乐趣，二人的爱意也在迅速萌芽。©豆瓣', '本·斯蒂勒', '约翰·汉博格', 6.4, 7815, 'tt0343135', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p792601795.jpg', 1.1, 10.7, 60.2, 22.7, 5.3, '0.293415,0.090738,-1.013044,0.804002,-0.488720,-0.278401,1.066816,0.185339,-0.586357,-0.043659,0.181017,0.795287,-0.163195,0.221336,0.285286,0.061264,-0.179973,-0.600803,0.063230,-0.112984,-0.303910,-0.284234,-0.262092,-0.310161,-0.104652,-0.294253,0.570001,0.174251,-0.188623,0.243597,0.233689,0.057033,0.180960,0.637837,-0.406918,0.108760,-0.148768,0.250288,-0.129618,0.070360,0.083336,-0.110953,-0.150469,0.209043,-0.259465,0.253402,0.683542,-0.230534,-0.427883,0.005165,0.440562,-0.195809,-0.189572,0.114640,0.119879,-0.251492,0.109658,-0.097035,-0.136650,0.131056,0.054159,-0.095239,-0.900779,-0.132505,-0.206577,0.192602,-0.703720,0.558360,0.045638,-0.177612,0.106703,-0.424733,0.102676,0.173353,0.106230,0.463039,-0.428022,0.034681,-0.532826,0.305631,0.713335,0.220225,-0.441361,0.678922,-0.299925,-0.180165,-0.305858,-0.211322,-0.826938,-0.096254,0.251704,-0.112687,-0.543809,0.174997,-0.607128,0.228080,-0.100091,-0.197621,-0.169550,-0.539203,-0.132394,-0.182220,0.028461,-0.501003,-0.523187,0.211955,-0.029327,-0.389999,0.652362,-0.672523,0.153154,0.575983,0.138188,-0.486831,0.600834,0.264446,0.040099,-0.025177,-0.043542,0.428259,-0.054090,0.297685,0.129518,0.675780,-0.122497,0.163511,-0.314432,0.764689', '24756472', '1291877', '26884422',