INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308201', '绝种铁金刚', '喜剧', '著名影星詹二帮（梁家辉饰）常常出演一些英雄类人物的角色，但现实生活中却胆小如鼠，使深爱的妻子曼琼（余安安饰）离开了他，自此他便跟两个女儿忌廉（钟欣桐饰）与脆皮一起生活了。铁男（陈小春饰）与Janet（田朴珺饰）均是国际刑警，得知恐怖分子龙一（徐锦江饰）将到香港去取另外的生化武器，在香港与恐怖分子交手的过程中，误入了二帮的家里，铁男被注射了智力退化的病毒，智商只有4岁儿童的程度。曼琼从好莱坞回来打算跟二帮商议合作的事情，却遭到恐怖分子的闯入，他们得知丢失的病毒就在二帮家中。在与恐怖分子斗争的过程中，二帮为了女儿为了前妻，显现出以往少有的勇敢才智，顺利抓拿犯罪分子以为，还赢回了家庭团员。©豆瓣', '梁家辉', '王晶', 5.7, 7963, 'tt0385599', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2359387001.jpg', 6.3, 25.4, 50.8, 12.6, 5, '0.093744,-0.033630,-0.466175,0.425282,-0.173794,-0.186510,0.656746,0.031003,-0.465424,-0.350649,0.124458,0.824092,-0.135381,0.025303,0.151913,-0.278807,-0.195693,-0.769073,-0.162975,-0.049489,-0.274048,-0.244549,-0.280043,-0.137657,-0.075743,-0.403299,0.691362,-0.044692,-0.370774,0.288789,0.332640,0.262816,-0.418522,0.207782,-0.239669,-0.010378,0.005301,0.115844,-0.513212,0.253156,0.048614,-0.277196,0.111110,0.023612,0.094888,0.285313,0.812407,-0.184497,-0.010314,-0.106664,0.223330,-0.200480,-0.143331,0.138395,0.392502,0.061595,0.291510,0.297020,0.011278,0.014151,0.173335,-0.091170,-0.671347,0.026186,0.319179,0.062964,-0.487171,0.317065,-0.108595,-0.029167,0.142363,-0.040062,0.230321,0.222754,0.354778,0.276149,-0.157108,-0.026362,-0.540129,0.353572,0.593009,0.028908,-0.063625,0.178675,0.083119,-0.776399,-0.112777,-0.464815,-0.288684,0.082276,0.244440,-0.006589,-0.428679,0.322964,-0.648451,0.025185,-0.134996,0.092678,0.084874,-0.139535,0.090057,-0.665655,-0.118350,-0.421915,-0.319901,0.125347,0.300104,-0.246111,0.694833,-0.782571,0.093813,0.426986,0.357781,-0.697868,0.541650,-0.016513,0.176624,-0.244934,-0.054335,-0.053998,0.251533,0.120132,0.103838,0.261191,-0.406425,-0.334245,-0.272688,0.234057', '4301278', '3811356', '1996313', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308206', '绿鱼', '剧情', '刚服完兵役的莫东（韩石圭 饰）坐火车回家的路上认识了美爱（沈惠珍 饰）。不知为何，莫东感觉自己以后的生活都会跟美爱有牵连。回家后的莫东正找工作，他再次遇到了美爱，美爱是在夜总会唱歌的，更是黑帮老大（文成根 饰）的女友。莫东也因为美爱的关系加入了黑社会。忠心耿耿的莫东对美爱却有一丝丝的好感，而美爱冷酷的外表后面是一颗炽热的心。没想到，他们的组织面临解散，莫东打算付出自己的所有以及心爱的女人，他却得不到应有的回报……©豆瓣', '韩石圭', '李沧东', 7.8, 13285, 'tt0126838', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1453451101.jpg', 0.2, 1.3, 25.7, 54.5, 18.3, '0.153001,-0.087477,-0.700841,0.426866,-0.273501,-0.358709,0.716680,0.311312,-0.406069,-0.192046,0.059465,0.659525,-0.057665,0.258525,0.164944,0.030778,-0.086905,-0.637413,-0.115119,-0.196533,-0.208013,-0.264640,-0.277024,-0.086689,-0.041637,-0.023790,0.481332,0.141545,-0.179492,0.560510,0.554615,0.271127,0.261443,0.827813,-0.122782,-0.100285,-0.064766,0.118729,-0.063129,-0.076612,0.174278,-0.046725,-0.157319,0.228282,0.131699,0.433462,0.451863,0.187708,-0.271866,-0.105080,0.287571,-0.129330,0.113067,-0.028950,0.280393,0.167757,0.157731,0.283604,-0.218679,-0.077049,0.134638,0.132227,-0.863081,-0.165331,0.129949,0.289370,-0.684850,0.466548,-0.028853,-0.056121,0.098615,-0.366841,0.433615,0.253434,0.182768,0.403280,-0.117539,0.026317,-0.571160,0.041100,0.839399,-0.064414,0.016019,0.296233,-0.305897,-0.385783,-0.083070,0.042405,-0.471919,-0.073491,0.065966,-0.031337,-0.233953,0.111632,-0.409461,0.008403,-0.038293,-0.039895,-0.036524,-0.430648,0.026398,-0.426235,-0.168855,-0.722896,-0.420835,0.326258,0.134994,-0.021105,0.836237,-0.868958,0.224233,0.634828,0.468396,-0.910721,0.522035,0.329050,-0.119801,-0.118814,-0.084897,0.185894,-0.065145,0.260358,0.093444,0.285661,-0.021142,-0.228801,-0.172806,0.408136', '1301022', '1877596', '6874741', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308207', '惊声尖笑2', '喜剧', '经历了高中万圣节的杀人惨剧，辛蒂（Anna Faris 饰）和好友们进入大学校门，大学快乐悠闲的生活让他们渐渐忘记万圣节的恐怖经历。热衷于超自然学的教授奥德曼（Tim Curry 饰）计划到一年前曾发生恐怖事件的鬼屋做试验，需要拥有濒死体验的人做沟通灵异的媒介。助手歪头（David Cross 饰）得知辛蒂等人的经历，将他们集中起来，以获得优等成绩为诱饵请他们参加一个关于失眠的课题研究。众人怀着玩乐的心情随奥德曼教授和歪头来到了阴森诡异的鬼屋，却经历了极为难忘和恐怖的一夜……©豆瓣', '安娜·法瑞丝', '基伦·埃弗瑞·韦恩斯', 6.7, 35934, 'tt0257106', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1231137736.jpg', 1.9, 10.1, 48.5, 28.3, 11.2, '0.460290,-0.441858,-0.377843,0.328192,-0.010545,-0.070676,0.709526,-0.275213,-0.586843,-0.569947,0.160126,0.536924,-0.561667,0.304116,0.654793,-0.417511,-0.133065,-0.739436,0.197049,-0.054103,-0.195421,-0.297625,-0.246329,-0.189812,-0.002048,-0.547498,0.397056,0.115774,-0.040089,0.776132,0.019136,0.332029,-0.050872,0.127622,-0.232254,-0.169834,0.043748,0.443908,-0.492007,-0.080084,0.185882,-0.286701,-0.350943,-0.154498,0.408877,-0.061014,0.722918,-0.090252,-0.564620,-0.129819,0.522300,-0.226485,-0.226828,0.074328,0.127434,0.638935,0.003723,0.350899,-0.038823,0.149306,-0.062372,-0.222482,-0.835810,0.191916,0.189144,-0.027774,-0.464747,0.342322,0.199969,-0.040566,0.317653,-0.159455,0.319824,0.413171,0.229475,0.576526,0.224291,0.073283,-0.185366,0.549972,0.888285,-0.360769,-0.317933,0.261655,-0.182442,-0.400533,0.105486,-0.368489,-0.186802,0.472611,-0.192838,0.152961,-0.348496,0.290844,-0.690764,-0.096618,0.036349,-0.476102,0.235072,-0.256110,-0.299510,-1.079786,-0.345610,-0.083026,-0.289119,0.089688,-0.104942,-0.665685,0.588076,-0.980479,0.220650,0.228026,0.286198,-0.510547,0.767373,-0.093213,0.041180,-0.182763,0.075021,0.164173,-0.182462,0.396574,-0.130211,0.451889,0.153994,-0.022157,-0.634770,0.504235', '11541282', '24751811', '3139191', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308219', '我老婆不是人', '喜剧', '建筑师托尼（梁家辉 饰）的个性十分木讷老实，以至于他暗恋同时艾琳（陈雅伦 饰）多年，却总也鼓不起勇气表白，更糟的是，艾琳已有一位感情亲密的男友，托尼的单恋似乎注定不会有结果。一次偶然中，托尼被猛鬼缠身，索性得到名为嘉嘉（关之琳 饰）的女鬼相助才得以脱身，也正因为这件事，托尼拥有了能与嘉嘉心意相通的特异功能。得知了托尼的苦恋，热心的嘉嘉决定帮他一把，一番波折之后，艾琳终于离开了男友，投入了托尼的怀抱，可是，直到这时，托尼才发现自己其实早已经深深的爱上了嘉嘉，无奈人鬼殊途，无法承受分离之苦的托尼竟然决定殉情。©豆瓣', '梁家辉', '陈德森', 6.7, 4223, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2462197495.jpg', 1, 7.3, 56.9, 26, 9, '0.205538,0.157158,-0.663188,0.191694,0.008722,-0.652428,0.587756,-0.099844,-0.471520,-0.250044,0.177470,0.535424,-0.168239,0.424706,0.055579,0.020051,-0.147941,-0.689763,0.124060,-0.033557,-0.377779,-0.441126,-0.389887,0.134776,-0.098017,-0.097038,0.595978,0.053620,-0.122075,0.194856,0.430942,0.417798,0.154150,0.654208,0.104388,0.093124,0.229946,0.302124,-0.315085,-0.034474,0.313938,-0.308328,-0.000480,0.370817,-0.024558,0.423192,0.299012,-0.368227,-0.386772,0.017541,0.335340,-0.078568,-0.045387,0.175573,-0.064844,0.059593,0.441953,0.112491,-0.213064,-0.143196,0.152541,0.113937,-0.415773,0.122883,0.092298,-0.089471,-0.419677,0.157956,-0.193208,-0.069175,0.013726,-0.407024,-0.038047,0.368505,0.436326,0.193525,-0.341856,0.156252,-0.189164,-0.023828,0.678189,0.215197,-0.197559,0.610086,-0.080895,-0.364018,0.075113,-0.205383,-0.445476,-0.002285,0.410514,0.208042,-0.089008,0.263142,-0.225517,-0.237579,-0.510214,0.277794,-0.008785,-0.294595,0.154227,-0.122475,-0.362842,-0.268268,-0.262518,0.088733,-0.103207,-0.242605,0.506417,-0.769530,0.302949,0.294839,0.044168,-0.339070,0.409931,0.193680,-0.018913,-0.270942,0.270570,0.471616,-0.426309,-0.001113,0.335718,0.164492,0.282415,-0.239738,-0.458712,0.398053', '1301022', '1308254', '1308755', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308228', '鲁冰花', '剧情', '年轻气盛的美术老师郭云天（于寒）从大城市调到水城乡小学后，发现其它老师眼中的“坏学生”古阿明（黄坤玄）是个绘画天才，加上调查后得知古阿明家境贫困，郭云天开始对他照顾有加，时常为他不惜同其它老师发生冲突。校长委托郭云天挑选一名美术选手代表学校参加比赛，郭云天力荐古阿明，遭到其它老师的反对，据理力争一番，郭云天终没抵过众人之口，心怀对古阿明的歉意带着他的一幅绘画离开了水城乡。而落选后的古阿明因为伤心外加营养长期不良，患上肝病不治身亡，不知他送给郭云天作纪念的那张画已为他赢得了世界性的荣誉。©豆瓣', '黄坤玄', '杨立国', 8.8, 15592, 'tt0097791', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233267812.jpg', 0.2, 0.7, 9, 37.8, 52.4, '0.159074,-0.146522,-0.359754,0.546578,-0.268113,-0.347173,0.275669,-0.060203,-0.794411,-0.541554,-0.095418,0.490659,-0.236867,0.649783,0.142127,-0.356644,0.007165,-0.318060,-0.290987,0.069035,-0.663896,-0.493500,0.233069,-0.396195,-0.332848,-0.114701,0.255502,0.066552,-0.264942,0.720370,0.217881,0.115089,0.217392,0.301437,0.152531,0.009378,-0.150677,-0.060670,0.004340,0.160548,0.239749,0.009058,-0.075070,0.020669,0.415709,0.358537,0.448023,0.288573,0.181025,-0.036805,0.394956,-0.386785,0.299280,0.169278,0.200870,0.071395,0.026518,0.013882,-0.238853,-0.090627,-0.171277,-0.147477,-0.251641,-0.042353,0.218069,0.141108,-0.423661,0.427713,0.036561,0.010877,-0.059818,-0.220553,-0.002441,0.273624,0.144181,0.138634,-0.001439,0.048232,-0.262237,0.460959,0.518404,-0.150452,0.276420,-0.230683,-0.068352,-0.471991,0.167307,-0.123756,-0.120113,0.073114,0.375113,-0.146316,0.397034,-0.119908,-0.245853,-0.643019,0.058789,-0.046060,0.210902,0.042176,0.087593,-0.582831,0.149579,-0.335689,-0.326453,-0.265134,0.159743,-0.423701,1.005115,-1.132818,0.206690,-0.097341,0.086008,-0.647250,0.501857,0.130725,0.078875,-0.147138,-0.078816,0.350863,0.505940,0.271370,-0.015404,0.365408,0.107547,-0.498396,0.039795,0.172922', '25922902', '1306544', '6963575', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308232', '新扎师妹2', '喜剧', '方丽娟（杨千嬅饰）每天都与区海文（吴彦祖饰）过着打情骂俏的生活，当丽娟努力训练自己成为一个好媳妇讨好未来公公时，接受了另外一个新任务——保护某国即将到港的王妃，可是遇到了资金问题，丽娟请求海文的帮助，惹来海文的不满，两人因此冷战。丽娟甚至以为王妃勾引海文，与王妃大打出手，被勒令停职处分。原来警方是想让丽娟接受另一个卧底任务，到国内以名媛的身份接近盗窃集团首脑韩洋并取得他的犯罪证据。海文不放心跟到了上海，却与丽娟双双落入了韩洋的手里，韩洋威胁丽娟需要用价值连成的红酒交换海文，而身为警察的丽娟陷入了两难的状态……©豆瓣', '杨千嬅', '马伟豪', 6.5, 46689, 'tt0375934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2515686674.jpg', 1.5, 11.7, 53.2, 25.1, 8.5, '0.321724,0.126695,-0.429088,0.416809,-0.144241,-0.416692,0.352501,0.370458,-0.445517,-0.096588,0.386447,0.514295,0.148839,0.080119,0.329744,-0.000699,-0.269904,-0.703183,0.094061,-0.050335,-0.284442,-0.662428,-0.067035,-0.163022,-0.033510,-0.247358,0.294027,-0.076674,-0.182247,0.383516,0.096337,0.324476,-0.161112,0.457171,0.097900,-0.064300,0.393343,-0.071657,-0.585185,0.396597,0.129535,0.012783,-0.142507,0.280961,0.220776,0.453603,0.496606,-0.127687,-0.405101,-0.272827,0.198683,-0.512244,-0.081444,0.165354,0.157455,0.062016,0.299214,0.202705,-0.343556,0.204777,0.146544,-0.031282,-0.868869,0.083927,0.122865,0.110523,-0.604036,0.340704,-0.362438,-0.255906,-0.067713,-0.370306,0.468171,0.719519,0.006820,0.326618,-0.408106,0.245883,-0.683879,0.109105,0.508238,0.093055,-0.165805,-0.079824,0.129541,-0.346598,0.131406,-0.346668,-0.330915,0.096718,-0.079672,0.108906,-0.117774,-0.021852,-0.482008,-0.099010,-0.368323,-0.106422,0.125737,-0.639261,-0.139140,-0.390000,-0.156125,-0.105142,-0.311584,0.057334,0.282810,-0.246466,0.471931,-0.765417,0.005551,0.457312,0.474935,-0.743713,0.476523,0.341164,-0.016693,-0.445972,-0.242784,-0.349536,0.040566,0.317976,0.168422,0.081799,0.117989,-0.417589,-0.225558,0.058365', '26678784', '1877596', '1297862', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308237', '魔翡翠', '喜剧', '代号猎鹰的安迪（刘德华 饰）是知名冒险专家，连警方也常拜托他出面解决棘手问题。安迪与搭档碰撞球（王晶 饰）总能利用身手与技术完美达成任务。安迪的朋友沈昆因找到魔翡翠遭到苏联克格勃的追杀，遂在希腊向安迪求助。安迪与小外甥彬彬（小彬彬 饰）、碰撞球一行来到雅典，却阴差阳错与沈昆错过，后者将魔翡翠落在小小彬手中。另一方面，为了阻止克格勃抢夺魔翡翠，国际刑警组织的探员一直与精通中国文化和功夫的克格勃首领力战。小小彬无意中发现了魔翡翠具有语言能力和超能力，并与其成为了朋友。在安迪、克格勃和国际刑警三方的争夺中，他们发现魔翡翠原来是属于外星人……©豆瓣', '刘德华', '王晶', 6.4, 6232, 'tt0091532', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2233465316.jpg', 2, 12.2, 58.5, 19.7, 7.7, '0.086497,-0.015599,-0.439497,0.469905,-0.135468,0.013165,0.233854,-0.236455,-0.599563,-0.537243,-0.027002,0.821686,-0.136035,-0.384642,0.070390,-0.151388,-0.046692,-0.796038,0.055023,-0.035529,-0.122340,-0.489439,-0.416577,-0.035103,-0.128043,-0.337042,0.591835,-0.108607,-0.476151,0.523582,0.168221,0.557474,-0.662114,0.185588,0.036839,-0.106512,0.096535,-0.191666,-0.664864,0.316496,-0.138174,0.106602,0.066762,0.154214,0.073877,0.174507,0.453873,-0.484805,0.097143,-0.197994,-0.106824,-0.412563,-0.123270,-0.013681,0.398530,0.042500,0.321805,0.177005,-0.122060,-0.009695,0.092768,0.024729,-0.651146,0.158839,0.175220,0.136127,-0.440511,0.401168,0.065152,0.147728,0.087275,-0.282690,0.320084,0.266475,0.134653,0.117792,-0.144770,-0.161990,-0.342260,-0.039844,0.345760,0.040590,0.105483,0.154916,0.147664,-0.541285,-0.059227,-0.271850,0.138066,0.092775,0.363748,0.136875,0.084110,0.188297,-0.953342,-0.208103,-0.275146,0.173640,0.156260,-0.503602,0.291208,-0.738295,0.031837,-0.225142,-0.417718,0.139366,-0.123709,-0.275736,0.567284,-1.028112,-0.036779,0.379306,0.423825,-0.295630,0.594405,-0.115453,-0.007957,-0.452318,-0.245327,-0.146556,0.496898,-0.078664,-0.099777,0.069976,0.107963,-0.312571,-0.249719,-0.086553', '1420088', '25723905', '4301278', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308247', '非常小特务2', '喜剧', '国际特工组织OSS将朱尼和卡门姐弟俩派到迪斯尼乐园里完成一件重要任务，事情是这样的：总统的独生女亚历克桑德拉因为长久以来得不到父亲的关爱而心生怨言，于是偷走了被称作“TRANSMOOKER”的国家防御系统电脑芯片，紧接着，许许多多的追杀跟随而至……', '达里尔·沙巴拉', '罗伯特·罗德里格兹', 6.5, 7046, 'tt0287717', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2577355796.jpg', 1.8, 11, 57.5, 21.1, 8.6, '0.368106,0.091200,-1.063719,1.017157,-0.319746,0.016713,0.559443,0.082419,-0.689645,-0.349287,0.131927,0.802861,0.280356,0.285554,0.522838,-0.095752,-0.043546,-0.619126,-0.034500,-0.552470,-0.464704,-0.596084,-0.262026,-0.663372,-0.186365,-0.576628,0.786263,0.220256,-0.159523,0.318528,0.472174,0.854391,-0.123981,0.437397,0.155838,-0.284709,0.369453,-0.003105,-0.368429,0.522429,-0.006535,0.074727,0.022782,0.405996,-0.019289,0.535195,0.300306,-0.500563,-0.255451,-0.380785,0.424525,-0.813894,0.062316,-0.281759,0.508744,0.250374,0.065909,0.521971,-0.209607,-0.096809,0.314496,-0.149271,-0.840247,-0.335746,0.192011,0.182724,-0.904186,0.257818,-0.555466,-0.061313,0.025386,-0.480322,0.393184,0.460501,-0.071232,0.376740,-0.177274,0.344513,-0.387034,0.187781,0.913891,-0.521454,-0.022824,0.199918,0.093669,-0.220169,0.171240,-0.578690,-0.328999,0.101784,-0.058150,0.291248,0.186165,0.294748,-0.522228,-0.131330,-0.352009,-0.312940,0.000386,-0.831569,0.089729,-0.552153,-0.025636,-0.228751,-0.249681,0.130144,0.260142,-0.171257,0.838164,-0.837640,0.190578,0.528987,0.209290,-0.864443,0.452893,0.106036,0.537082,-0.305582,-0.004065,-0.058817,0.384379,0.282016,-0.146642,0.035369,0.257030,-0.491679,-0.265242,0.227872', '30163500', '34968329', '1482072', '30396443');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308248', '我爱夜来香', '喜剧', '二战时期，纳粹铁蹄蹂躏世界每一个角落。德国科学家研制出一种铀分裂的超级武器，该武器可导致人类灭亡。犹太人科学家哈巴枸偷偷将超级武器的图纸带出德国，逃往美利坚，得知消息的希特勒派出盖世太保追杀。哈巴枸只得转道香港，与美国特工接头。为了确保这张代号为“野兽”的图纸安全交接，中国最高间谍“天字第一号”（林青霞 饰）委托夜来香事务所的私人侦探夜来香（林子祥 饰）为哈巴枸保驾护航。正愁无米下锅的夜来香认为这是一个赚钱的好机会，但等待他的则是一场紧张刺激却又笑料不断的图纸争夺战……©豆瓣', '林子祥', '泰迪·罗宾', 7.5, 5779, 'tt0086594', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2345263280.jpg', 0.7, 3.3, 34.9, 43.4, 17.6, '-0.116433,0.088029,-0.299075,0.514436,0.111807,0.037266,0.150015,-0.079036,-0.275555,-0.304834,0.400976,0.579332,0.224622,-0.120032,0.176458,0.108992,-0.211788,-0.512333,-0.052679,-0.179150,-0.168896,-0.290350,-0.466556,-0.372014,-0.012461,-0.085581,0.481235,0.052195,-0.376735,0.176974,0.253176,0.413048,-0.117782,-0.033585,0.040839,-0.516213,0.358009,-0.277681,-0.476580,0.155425,-0.217744,-0.153401,0.025333,0.062027,-0.074582,0.352686,0.523480,-0.175424,0.167422,-0.460308,0.321456,-0.237377,-0.069540,-0.238001,0.314441,0.099816,-0.014445,-0.071383,0.011711,0.187358,0.170722,0.116317,-0.856394,-0.049548,0.171551,0.157669,-0.278372,0.160991,-0.300211,0.228380,0.056646,-0.187157,0.405898,0.304118,0.383032,0.392715,-0.147513,0.331412,-0.473795,0.295113,0.130803,-0.330623,0.015796,-0.055932,-0.122802,-0.378367,0.314575,-0.385015,-0.143119,-0.183895,0.096211,-0.212295,-0.051594,0.103138,-0.942139,0.006263,-0.417902,-0.248906,0.385769,-0.151409,-0.041406,-0.798629,0.111700,0.192530,-0.017758,0.197628,0.278526,-0.071055,0.761614,-0.168031,-0.053249,0.687803,0.056283,-0.483649,0.182436,0.129749,-0.012697,-0.366574,-0.057983,0.183937,0.318223,0.319569,-0.167771,0.049245,0.230868,-0.415305,-0.097970,0.052305', '7155241', '3318306', '26290398', '1309112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308252', '江湖告急', '喜剧', '纵横江湖二十年的黑帮大佬任因久（梁家辉 饰）树敌无数，因此屡遭他人暗算，并得知有人要在24小时内取他性命。任因久即刻以“江湖告急”的名义，传令召开江湖大会，势必找出谁要害他。©豆瓣', '梁家辉', '林超贤', 7.6, 47347, 'tt0266703', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2614173295.jpg', 0.5, 3, 29.1, 48.7, 18.6, '-0.451503,0.436645,-0.313275,0.069604,-0.083323,0.424337,-0.579527,-0.372630,-0.822968,-0.063959,0.388035,0.575266,-0.101455,-0.229527,0.038171,-0.072029,0.302433,-0.861205,0.378401,-0.667451,0.143131,-0.057467,-0.299815,-0.412649,0.075027,-0.148985,0.424794,0.469643,0.182168,0.435106,0.097735,0.003644,-0.186970,0.529494,-0.024689,-0.052584,-0.155888,-0.036886,-0.559707,-0.262886,-0.152656,-0.839819,-0.355996,-0.247159,0.126218,0.374860,0.057945,0.211706,-0.164022,0.245444,0.790063,-0.606181,-0.098601,-0.316300,0.962762,-0.056803,0.105001,0.819449,0.022823,0.247889,-0.024981,0.180382,-0.312116,-0.188955,0.048127,-0.079065,-0.513856,0.555932,-0.486302,-0.003464,-0.629324,0.372751,-0.122543,0.696797,-0.001029,-0.544758,0.170822,-0.094742,-0.320399,0.624617,0.898682,0.038007,0.137838,-0.634138,0.727150,-0.285987,0.316663,-0.855476,0.079370,-0.175972,0.652744,-0.598588,-0.390255,0.345703,0.015535,-0.048861,-0.026813,0.011912,0.564423,0.081705,-0.239123,-0.699904,-0.172767,0.017758,0.079848,-0.116490,0.130057,0.222539,0.448121,-0.652471,0.232251,0.391257,-0.004258,-0.867140,0.748916,0.184369,0.147064,0.002385,-0.258757,0.234830,0.312777,0.558319,0.103729,-0.352949,0.067595,-0.073101,-0.367323,-0.412764', '1296272', '1439400', '1307106', '1297863');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308254', '侠骨仁心', '剧情', 'Lawrence（梁朝伟 饰）是一位颇有建树的脑科医生，Paul（钟镇涛 饰）是其同事兼好友。不幸的是，脑科医生Paul的女友Jackie（李嘉欣 饰）却在一次意外中脑部受伤，成了植物人。Paul日复一日的守在昏迷的女友身边，盼望她能够突然转醒。终于有一天，Jackie 苏醒了，但是令她醒来的却是Lawrence。苏醒后的Jackie性格大异于前，不仅拒绝疏远Paul，还想找寻一个新的环境重新开始。Lawrence同意Jackie与他合住直至Jackie找到新工作。两人在同一屋檐下，日久生情，一段新的恋情就此展开。但不幸却再次降临，Jackie脑部竟出现肿瘤，随时有可能因此丧命。Jackie能再次从病魔手中逃走吗？面对不幸，Lawrence和Jackie爱情会发生什么变化？©豆瓣', '梁朝伟', '邓特希', 6.8, 5084, 'tt0266067', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2629196193.jpg', 1.5, 9.3, 49.7, 27.8, 11.6, '-0.052149,0.123535,-0.640108,0.215785,0.104881,-0.242669,0.864246,0.018893,-0.764120,-0.370148,0.235666,0.672544,-0.305904,0.417410,0.168037,-0.161823,-0.097178,-0.854803,0.087110,0.100665,-0.670596,-0.226121,-0.484012,-0.111487,-0.048343,-0.351622,0.694917,0.147502,-0.212839,0.426964,0.176828,0.317387,-0.145255,0.806813,-0.264099,-0.069288,-0.033094,0.228840,-0.351713,0.202438,0.359531,-0.411598,-0.134780,0.057375,0.005634,0.357370,0.622196,-0.061649,-0.515203,0.105291,0.516739,-0.117970,-0.192580,0.055024,0.421997,0.168985,0.298061,0.047966,-0.241868,-0.013298,-0.128809,0.157226,-0.623902,-0.016524,0.080158,0.434795,-0.460959,0.268921,0.045973,-0.107119,-0.048983,-0.457336,0.242755,0.547322,0.253556,0.442164,-0.151877,0.031398,-0.439619,-0.151233,0.742239,-0.051295,-0.564537,0.618811,-0.078005,-0.524563,0.020291,0.022701,-0.282327,0.136163,0.203745,0.412448,-0.278693,0.109118,-0.329651,-0.025794,-0.430119,0.096269,-0.063407,-0.266731,-0.087524,-0.301596,0.016559,-0.149821,-0.392098,0.201619,0.016712,-0.382747,0.596559,-1.031777,0.491925,0.316442,0.171762,-0.477958,0.541338,0.301299,0.184224,-0.087568,0.094980,0.345769,-0.196708,0.224142,-0.060569,0.163740,0.063986,0.036657,-0.534855,0.097791', '1301022', '1308755', '1937946', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308269', '字典情人', '剧情', '1936年，英国小伙子蔡斯科特（休•丹西 Hugh Dancy 饰）遵从父命来到了英属殖民地沙月拉，这里的土著首领别兰塞以盛情款待了这个异乡人，并且给他派了一位特殊的女仆——“字典情人”希丽玛（杰西卡•阿尔芭 Jessica Alba 饰），她除了服侍他的衣食起居之外， 还要担任他的语言教师，两个人在相处中逐渐产生了感情。当蔡斯科特跟英国长官亨利（鲍勃•霍斯金斯 Bob Hoskins 饰）谈论“字典情人”的时候，对方却言辞激烈地劝他不要以身试法。此后，父母为他圈定了一桩婚事，未婚妻来到了这片土地，并且开始进入他的生活。究竟是遵循惯例，还是突破传统，蔡斯科特面临痛苦的抉择……©豆瓣', '杰西卡·阿尔芭', '盖·简金', 7, 6761, 'tt0242888', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2623637546.jpg', 1.1, 7, 44.9, 36.3, 10.7, '0.162178,0.078129,-0.526811,0.777850,-0.321160,-0.378285,0.619339,0.291024,-0.566087,-0.407701,-0.000217,0.457872,-0.075978,0.178850,0.334148,-0.079237,-0.372431,-0.752627,-0.048501,0.000680,-0.266560,-0.409324,0.011896,-0.505641,-0.312554,-0.118978,0.347583,0.078897,-0.134840,0.099522,0.060509,0.304655,0.080429,0.447343,-0.141109,0.038126,0.363313,-0.032702,-0.289893,0.058542,0.011482,-0.220583,-0.047072,-0.046575,0.294505,0.523759,0.482939,-0.108750,0.084764,-0.113438,0.103244,-0.098387,0.175858,0.162244,0.341730,-0.287119,-0.077721,0.146149,-0.045712,0.165111,-0.038109,-0.229661,-0.318048,-0.021443,-0.059304,-0.085089,-0.691648,0.234844,-0.181027,0.119641,-0.165229,-0.366772,0.164146,0.283176,0.166880,0.185431,0.086982,0.111661,-0.329130,0.338018,0.603069,-0.029202,-0.061287,-0.048271,-0.497851,-0.639026,-0.075015,-0.119305,-0.544531,-0.218608,0.261473,-0.153341,-0.023585,0.231600,-0.428460,-0.387442,-0.197925,-0.238556,0.149394,-0.532026,0.198847,-0.492839,-0.125851,-0.500156,-0.108306,-0.016959,0.009284,-0.057051,0.656828,-0.562515,0.253505,0.289837,0.260745,-0.679557,0.622951,0.402051,0.298749,-0.287804,0.198639,0.371160,0.040618,0.173412,0.050836,0.241989,0.305580,0.217739,-0.154099,0.334719', '4842877', '1301022', '1872133', '1309177');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308281', '熊的传说', '动画', '远古时期的太平洋西北部大陆，父母双亡的印第安人三兄弟相依为命，靠打猎为生。一次，大哥在打猎时误闯了熊的家，母熊以为大哥要来伤害她的孩子，将大哥打死了。剩下的兄弟俩由此对熊充满了怨恨，发誓要杀光森林里的熊。克纳瞒着二哥德纳米跑到森林里，当他历经千辛万苦终于杀死了一只熊时，他的行为触怒了森林的神秘力量，克纳竟然被变成了一只熊。变成熊地克纳遇到了来森林里寻找弟弟的德纳米，德纳米以为弟弟也被熊杀死了，疯狂的追杀变了熊的克纳。为了恢复原貌，克纳必须出发找到大地与极光相接的地方。途中，他遇上了一只孤苦伶仃的小熊柯达，他们一起踏上了这趟神秘的旅程。©豆瓣', '华金·菲尼克斯', '亚伦·布莱斯', 7.9, 8145, 'tt0328880', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1361595813.jpg', 0.3, 1.6, 24.7, 48.7, 24.7, '0.067302,-0.023893,-0.742750,0.629179,-0.007739,-0.360928,0.407295,-0.111363,-0.245722,-0.158306,-0.209291,0.634933,0.100902,0.437086,0.015130,-0.026135,-0.024440,-0.225844,-0.381998,-0.113919,-0.507115,-0.067846,-0.492552,-0.126788,0.251241,-0.264756,0.372605,0.249329,-0.193679,0.359503,0.115825,0.349735,-0.201208,0.273163,-0.567807,0.275966,-0.134990,0.096765,-0.116520,0.350147,-0.188917,0.149656,0.159695,0.207634,-0.044927,0.181332,0.976374,-0.398457,0.072115,-0.622104,0.082831,-0.225911,0.079317,0.152624,0.524065,-0.117919,0.129352,0.284965,-0.122386,0.075238,0.249879,-0.260063,-0.674695,0.132099,-0.070865,-0.018002,-0.882598,0.219530,0.164868,-0.018787,0.177507,-0.097733,0.335632,0.423788,0.015614,0.408435,0.013766,0.180865,-0.541618,-0.273014,0.819710,-0.665735,-0.016970,0.188546,0.321197,-0.253412,0.337376,-0.365571,-0.350118,-0.129434,0.395601,-0.057001,-0.612454,0.297792,-0.779116,-0.223045,-0.381575,-0.012678,-0.126563,-0.284053,-0.311620,-0.090933,0.225928,-0.336342,-0.201019,0.396814,-0.087939,-0.076173,0.435174,-0.482704,0.345379,0.437145,0.462384,-0.281715,0.623232,-0.367276,-0.011898,-0.237110,0.344912,-0.028619,0.280665,0.391150,0.627632,0.216192,-0.026790,-0.090427,-0.406517,0.746161', '1310175', '1306505', '1309135', '33391824');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308288', '我爱你', '爱情', '本片改编自王朔小说《过把瘾就死》。杜小桔（徐静蕾）和王毅（佟大为）结婚后，相识、恋爱中被遮蔽在阴影里的问题全曝光在了阳光下。杜小桔认为爱情高于一切，婚姻更是爱情的立方级，“神经兮兮”地整日要王毅说“我爱你”，王毅认为爱情同请客吃饭没本质区别，结了婚爱情有或没有是一回事，最烦的事是张嘴对杜小桔说出“我爱你”。于是，杜小桔的吃醋和找茬成了一剂剂调节两人平淡婚姻生活的佐料，而她的反目和出走，则是不想让日子越流越成死水。©豆瓣', '徐静蕾', '张元', 7.1, 30179, 'tt0342555', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486563269.jpg', 0.8, 6, 44, 37.6, 11.6, '0.606307,-0.131613,-0.600308,0.695609,-0.196373,-0.287394,1.056307,-0.040902,-0.313934,-0.065399,-0.205901,0.631242,-0.468632,0.015046,0.027556,-0.094094,-0.140225,-0.764544,-0.172912,-0.067599,-0.055789,-0.689370,-0.011626,-0.111190,-0.243464,-0.220391,0.555639,0.085802,-0.279829,0.244844,0.550321,0.237690,0.230890,0.331733,-0.035399,0.112522,-0.392749,0.515316,-0.428342,0.162398,0.294497,-0.146193,-0.046004,0.232370,0.003162,0.058566,0.208539,-0.071515,-0.060044,0.035434,0.325962,-0.437297,-0.193571,0.017963,0.300774,-0.258470,0.617997,0.313281,-0.228992,0.081985,0.284897,0.150437,-0.531687,-0.053911,-0.008558,0.348326,-0.480330,0.566629,0.095435,-0.249417,0.247432,-0.026111,0.298371,0.202600,0.580154,0.520347,-0.278153,-0.247254,-0.657018,0.419899,0.731743,0.096776,-0.172997,0.491875,-0.296189,-0.183045,-0.009964,-0.159550,-0.286488,-0.126592,-0.039471,0.071449,-0.389570,0.351445,-0.388870,0.039566,0.347973,-0.165189,0.076970,-0.516657,0.003755,-0.118722,-0.361535,-0.598219,-0.447871,0.206943,0.054907,-0.639198,0.503356,-0.895357,0.172001,-0.078947,0.284838,-0.819029,0.839277,0.793074,-0.242980,-0.277851,0.466384,0.142432,-0.253978,-0.102830,0.337569,0.246013,0.109577,0.031270,-0.278726,0.551803', '1308755', '1302384', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308290', '98古惑仔之龙争虎斗', '动作', '1998年，香港回归后发生了天翻地覆的变化。而此时的铜锣湾亦发生了天翻地覆的变化，这个洪兴设陈浩南（郑伊健 饰）揸Fit的地盘来了两个新人物，一个是东升社的司徒浩南（郑浩南 饰），一个是湾仔区的新任高级督察李Sir( 李修贤 饰) 。 司徒浩南野心勃勃，一直意欲取代陈浩南在铜锣湾的位置，将其赶出铜锣湾。马来西亚一拿督（秦沛 饰）要搞赌船，主动找到陈浩南要求合作，其实暗中勾结司徒浩南，整蛊陈浩南。另一方面，李Sir在追查陈浩南的过程中，生出了少许英雄识英雄的感情。 一山不能容二虎，两个浩南最终的决斗开始了！©豆瓣', '郑伊健', '刘伟强', 7.3, 58933, 'tt0163511', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2607350439.jpg', 0.8, 4.2, 39.1, 39.7, 16.3, '0.063840,0.067962,-0.664591,0.749569,0.166626,-0.107212,0.657247,0.155478,-0.563971,-0.459950,0.121039,0.538543,-0.144626,0.325648,0.253022,-0.082451,0.001889,-0.733167,-0.009802,-0.127553,-0.266067,-0.421422,-0.307459,-0.053012,-0.406852,0.190385,0.475754,0.020787,-0.079286,0.492017,0.639350,0.131978,-0.117150,0.490498,-0.032832,0.019909,0.333413,0.163861,-0.308741,0.279275,-0.201464,-0.365293,-0.175353,0.171928,0.102367,0.451767,0.611386,-0.193874,-0.167889,-0.199558,0.373469,-0.336993,-0.286564,-0.058930,0.531350,-0.121300,0.031747,0.213772,-0.407150,-0.079433,0.144230,-0.002310,-0.719520,-0.025606,0.364968,0.244683,-0.601307,0.289689,-0.222550,-0.165043,-0.150714,-0.315583,0.349354,0.521853,0.374189,0.026996,-0.059625,-0.065575,-0.600314,0.039273,0.765301,0.022131,-0.154998,0.048384,0.246054,-0.325163,-0.378062,-0.259573,0.010657,-0.171839,0.447019,-0.149027,-0.079101,0.226114,-0.347933,-0.327641,-0.059254,0.062343,0.094280,-0.200025,0.092550,-0.447107,-0.265038,-0.549886,-0.037754,0.019237,-0.027806,-0.258716,0.510672,-0.780210,-0.138051,0.050306,-0.072475,-0.938585,0.327807,0.222065,0.075970,-0.242243,-0.129735,-0.258817,0.250863,0.338446,0.099301,0.618025,0.038498,-0.347880,-0.024346,0.026018', '1301022', '1297710', '1293265', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308295', '再见阿郎', '剧情', '张东郎（刘青云饰）从狱中出来，女人已卷走一切钱财。昔日手下已经另投他主，威风八面不复存在。年轻的寡妇小雪（黄卓菱饰）打理丈夫留下来的国际饭店，她有一个刚上小学的儿子。那残旧的小旅店“国际饭店”便成了张东郎的窝，暂时休喘。但他拿不着钱，因而交不出房租，只好在店里打打零工，对母子二人的感情愈来愈深，但他们的表达是含蓄而温馨的。后来，脾气火爆的张东郎得罪了警察肥九（林雪饰），对方开始刁难小雪的国际饭店甚至是恐吓小孩子。东郎愤怒出手，但小雪面对各种压力只得让他离开。没有家的东郎能走向何方？结下梁子的肥九又会轻易放过他们吗？©豆瓣', '刘青云', '杜琪峰', 7.8, 10708, 'tt0202682', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2169026426.jpg', 0.4, 2, 26, 52, 19.7, '0.464241,0.033324,-0.520161,0.253804,-0.505893,-0.221538,0.549603,0.376717,-0.343157,0.057941,0.268437,0.535004,0.136973,0.232974,-0.273946,0.081758,0.014455,-0.403810,0.030449,-0.037423,-0.044097,-0.410696,0.069600,-0.226136,-0.143116,0.197960,0.223875,0.043491,-0.070628,0.269962,0.395442,-0.066118,-0.043100,0.431976,-0.292980,0.104015,-0.178497,0.045849,-0.005270,0.168771,0.086754,-0.139865,-0.204185,0.188320,0.197051,0.560368,0.481283,0.004521,-0.344520,0.097271,0.280733,-0.307764,-0.247630,0.271733,0.147035,-0.107686,0.207939,0.037162,-0.242305,-0.206027,0.026877,0.093454,-0.374309,0.384640,-0.045592,0.027125,-0.730060,0.489446,-0.098691,-0.035084,0.050726,-0.328623,0.194883,0.178530,-0.145827,0.250370,-0.057229,0.027656,-0.581486,-0.003797,0.599537,-0.189836,-0.071875,0.219224,-0.241164,-0.152717,0.119325,-0.424948,-0.482818,-0.132215,0.235828,-0.033771,-0.173047,-0.040953,-0.416518,0.011355,-0.131030,0.162563,0.080325,-0.506202,-0.161320,-0.255501,-0.269494,-0.554107,-0.449246,-0.057195,0.185738,-0.153792,0.654892,-0.574528,0.065381,0.290468,0.491204,-0.589559,0.661073,0.038495,-0.010489,0.206004,-0.086232,0.026037,-0.042429,0.269357,0.337679,0.228674,-0.008175,-0.225266,-0.032517,0.282695', '1303112', '1308805', '1308206', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308304', '客途秋恨', '剧情', '晓恩（张曼玉 饰）留学归来参加妹妹的婚礼，期间发觉与母亲葵子（陆小芬 饰）的隔阂与矛盾只增不减。直到陪母亲回日本探亲时，她才真正开始了解自己的母亲。原来在抗日期间到满洲投靠哥哥的母亲，结识了当时身为军官的父亲（李子雄 饰），并与其结婚，战后决定随丈夫一起搬到澳门生活。因 生活习惯和文化等各方面的差异，令母亲与公婆同女儿之间的隔阂与误解不断。然而在母女俩终于取得了沟通与谅解之时，却从大陆传来了从小带大晓恩的祖父中风不良于行的消息, 向来和他们不和的母亲却要求忙拍戏的女儿一定要去......©豆瓣', '陆小芬', '许鞍华', 8.5, 18549, 'tt0099927', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2197624980.jpg', 0.2, 0.5, 11.4, 49.6, 38.4, '0.045401,-0.030595,-0.927065,0.601509,0.140738,-0.515956,0.474642,0.313944,-0.708802,-0.416310,-0.197356,0.816989,0.022120,0.424873,0.470445,-0.351221,-0.336650,-0.771165,0.136308,-0.080344,-0.334851,-0.383030,-0.100141,-0.004394,-0.284619,-0.446764,0.553907,-0.062210,-0.273332,0.772484,0.028412,0.223717,-0.412873,0.676651,-0.138208,-0.153359,-0.154409,0.576574,-0.783368,-0.097760,0.477708,-0.123252,-0.116220,-0.110550,0.249424,0.469514,0.550566,-0.323041,-0.153102,-0.142717,0.111983,0.025042,-0.035901,0.264540,0.198473,-0.058516,0.489924,0.602096,-0.117158,0.106797,-0.229649,-0.178016,-0.251733,0.103352,0.357852,-0.024610,-0.803823,0.591894,-0.118921,-0.241291,0.118826,-0.371393,0.346269,0.969688,-0.249639,0.646914,-0.397842,0.074471,-0.274626,0.116585,0.956964,-0.009775,0.227545,0.239887,0.112070,-0.404149,0.111178,-0.218738,-0.332839,0.156417,-0.194515,0.107036,-0.245123,0.283941,-0.571484,-0.302422,-0.087536,-0.005361,0.496753,-0.657794,0.361367,-0.490902,-0.128134,-0.712944,-0.162525,0.164075,0.387251,-0.120845,0.711561,-1.021125,0.293149,0.131757,0.526142,-1.010247,0.746174,0.249766,0.282086,-0.577102,0.086430,-0.010681,-0.001064,0.090294,-0.070567,-0.001728,0.199728,-0.090961,-0.388250,0.217037', '6890343', '25721544', '4145476', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308306', '林则徐', '传记', '18世纪中叶，日不落帝国英吉利将触角伸向古老的中国，并通过大量输入鸦片来掠夺钱财。白银大量流向国外，中国人民却被鸦片毒害得愈加羸弱。在清廷内部，以穆扎阿（夏天 饰）为首的投降派和以林则徐（赵丹 饰）为首的抵抗派针锋相对，斗争激烈。道光皇帝眼见天朝因鸦片所害渐渐羸弱，因而大力支持林则徐的禁烟政策，并任命其为钦差大臣前往广州查禁鸦片。林则徐来到广州后雷厉风行，令行禁止，让一度轻视他的英国鸦片商人大为惊恐。经过一段时间的治理，当地海防得到整顿，英商也被迫交出鸦片。最终，林则徐在虎门销毁两万多箱鸦片，取得禁烟的重大胜利。然而，不堪受挫的英国随即挑起鸦片战争，朝廷内部的投降派也不失时机广进谗言，林则徐的改革之路顿陷困境……©豆瓣', '赵丹', '郑君里', 7.4, 6524, 'tt0053010', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2504646738.jpg', 0.6, 2.4, 37.1, 45.9, 14, '0.067051,0.329743,-0.540303,0.418064,0.210448,-0.175220,0.254505,0.244847,-0.735308,0.055477,0.095652,0.360680,0.176806,-0.415073,0.014405,-0.131604,-0.168388,-0.473456,-0.291347,-0.004250,0.080948,-0.348587,-0.289828,-0.306890,-0.507539,-0.300242,0.637447,0.426965,-0.352042,0.366421,0.206408,0.304445,0.117359,0.467117,-0.053583,-0.246066,0.118137,-0.402480,-0.277981,0.075094,-0.034094,-0.630258,-0.108774,0.198290,-0.032245,0.426360,0.418282,-0.324235,0.147862,-0.425744,0.598078,-0.257004,-0.278844,0.089807,0.485317,0.637321,-0.086722,0.419475,-0.528425,0.055808,-0.098318,0.060162,-0.249772,-0.252975,0.042894,0.022031,-0.323234,0.440580,0.098987,0.139197,-0.153526,-0.400303,0.019286,0.788523,0.106762,0.319205,-0.143758,0.154041,-0.364894,0.375395,0.482799,-0.267051,-0.231020,-0.352188,-0.185334,-0.314964,0.430424,-0.519134,0.093157,-0.360263,0.417471,-0.192244,0.156647,0.499035,-0.691118,-0.016406,-0.447723,-0.373277,0.309475,0.260564,0.109946,-0.687024,-0.253041,-0.243846,0.038067,0.251304,0.377725,0.190539,0.318775,-0.346379,-0.064777,0.518587,0.406185,-0.816481,0.153309,0.162019,-0.135528,-0.015788,-0.351726,0.452134,0.504280,0.401991,-0.177613,0.110427,-0.000872,-0.321331,0.134672,0.279793', '1305970', '1419005', '1305366', '1448751');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308314', '邦尼和琼', '剧情', '邦尼（艾丹•奎因 Aidan Quinn 饰）在汽车修理厂工作。他有一个智障的妹妹琼（玛丽•斯图尔特•马斯特森 Mary Stuart Masterson 饰）令他非常操心。为了照顾妹妹，邦尼一直单身，因为他不想把琼送到专门的疗养院。某一天，邦尼和琼遇到了一个不速之客——邦尼朋友的远房亲戚萨姆（约翰尼•德普 Johnny Depp 饰）。这个萨姆行为古怪，他在酒吧里可以用面包玩出花样，还会模仿经典影片的桥段，逗大家开心。于是，邦尼邀请他做自己妹妹的保姆。在相处中，两个年轻人渐渐建立了一种特殊的感情。同时，邦尼也遇到了心上人路西（朱丽安•摩尔 Julianne Moore 饰），但是对妹妹的责任感让他对这段恋情有所忌惮。或许是出于对妹妹的爱，他拒绝萨姆的请求，结果萨姆带着琼私奔了。但是，因为改变环境，琼开始发疯，她被强制送进了医院……©豆瓣', '约翰尼·德普', '耶利米·S·谢奇克', 8.5, 22164, 'tt0106387', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p511366698.jpg', 0.2, 1, 14.3, 43.5, 41.1, '0.305563,-0.032895,-0.698658,0.472579,-0.262275,-0.214713,0.724290,0.121319,-0.545428,-0.319066,-0.084576,0.800909,-0.235634,0.350632,0.318547,0.235247,-0.192585,-0.440035,0.165458,-0.127294,-0.204543,-0.574275,-0.056259,-0.427395,-0.056316,-0.303656,0.249467,-0.404356,-0.043690,0.349717,0.330585,0.341988,0.039882,0.306755,-0.094563,0.117638,0.091605,-0.177214,-0.151851,0.138340,0.213739,0.022028,0.023358,0.212521,0.238600,0.304165,0.596853,-0.241344,-0.397273,0.018961,-0.052645,-0.176081,0.066781,0.015912,0.157071,-0.251781,0.173972,0.097036,-0.340346,-0.106584,0.104194,-0.145967,-0.556721,0.155884,-0.079646,0.029424,-0.636950,0.390422,-0.166369,-0.113833,0.056923,-0.320576,0.215815,0.317910,0.238017,0.204889,-0.153788,0.009747,-0.404784,-0.012575,0.535573,-0.029674,0.011968,0.492063,-0.605497,0.057126,0.130891,-0.159851,-0.641240,0.065003,0.277064,-0.163948,-0.305929,0.039855,-0.463505,-0.146935,-0.298195,0.078543,-0.009750,-0.501313,0.076570,-0.458320,0.026780,-0.514332,-0.185700,-0.140907,-0.045973,-0.259845,0.665558,-1.091874,0.175127,0.541206,0.390730,-0.683040,0.617409,0.295949,-0.082131,-0.284857,-0.067158,0.281052,-0.012724,-0.259647,0.218678,0.334800,0.348916,-0.159284,-0.256965,0.325875', '1292219', '2052978', 