INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308331', '拳神', '动作', '政府研发了一项秘密武器——拳神手套，它能够激活人类大脑中那未被使用的百分之九十部分，从而使使用者爆发超人的能量，十分危险，警察战廿一（张耀扬 饰）成为了手套的首批试用者中的一份子，然而，他的内心不满自己沦为政府操纵的木偶，于是偷走了手套，并且销毁了和手套相关的一切资料。阿风（元彪 饰）和Dark（郑伊健 饰）企图阻止战廿一的阴谋，最终，阿风和战廿一以及拳神手套均失去了踪迹。一晃眼数年过去，战廿一重出江湖，被洗脑的阿风则成为了他的帮手助纣为虐，战廿一企图利用拳神手套的威力统治世界，却遭到了阿虎（王力宏 饰）和铁男（冯德伦 饰）等人的阻挠，两帮人就此结下梁子。©豆瓣', '王力宏', '元奎', 5.3, 3858, 'tt0260136', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2474108561.jpg', 12.1, 30.1, 43.3, 10, 4.5, '0.104850,0.244901,-0.484105,0.471968,-0.113322,0.003828,0.289191,0.164104,-0.338254,-0.287350,0.201376,0.539030,-0.123241,-0.136936,-0.131526,-0.344123,-0.119430,-0.837983,0.016975,-0.076274,-0.535236,-0.133316,-0.404201,0.220475,-0.064230,-0.473408,0.762956,0.009499,-0.518407,0.192444,0.330849,0.227854,-0.019504,0.479187,0.033211,-0.151158,0.132566,-0.298664,-0.155722,0.305712,-0.198761,-0.199923,0.216390,0.329650,-0.298127,0.373281,0.885882,-0.622023,0.113823,-0.453025,0.363229,-0.284718,-0.157448,0.064749,0.253654,0.546227,-0.010890,0.250338,-0.229850,-0.012497,0.416440,-0.009590,-0.795157,-0.086603,0.043330,-0.003445,-0.535697,0.405729,-0.293916,0.198071,-0.037311,-0.170945,0.354225,0.270151,0.329096,0.020682,-0.173579,-0.185847,-0.574224,0.250704,0.270176,-0.278015,-0.376786,0.021035,0.140475,-0.430350,-0.501385,-0.147428,-0.172274,-0.246884,0.678519,0.207111,-0.001277,0.227908,-0.768194,-0.038883,-0.277818,0.154970,-0.068456,-0.371097,0.203674,-0.720127,-0.238318,-0.420223,-0.164345,0.068164,0.366613,-0.213632,0.679717,-0.672211,0.019136,0.153901,0.269368,-0.392996,0.287933,0.041649,0.164809,-0.272092,-0.142003,0.010858,0.098784,0.362909,0.611136,0.498456,0.153327,-0.022965,-0.077348,0.366177', '26759820', '25774050', '10467125', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308338', '蜀山传', '剧情', '蜀山群山之中的昆仑山，掌门孤月大师（张柏芝饰）与徒弟玄天宗（郑伊健饰）相恋，事先预感邪恶的幽泉血魔会进攻昆仑，自知无力抵抗的她，为保天宗性命而借故赶他下山，并将昆仑秘藏武器“日月金轮”交付天宗，而自己则为血魔所杀，昆仑山灵气尽被吸去。二百年后，邪恶力量再次侵犯正派，峨嵋开山祖师峨嵋真人（洪金宝饰），惟恐此战伤及凡间，乃派大弟子丹辰子（古天乐饰）前往山下疏离凡间正在交战的军队，在途中与程乐天（章子怡饰）、玄天宗相遇，却意外发现血魔的秘密，并因而落入陷阱。在生死之际峨嵋真人率弟子前来救援，玄天宗赫然发现其中一名女弟子李英奇（张柏芝饰），样子竟酷似师傅孤月大师。同时，峨嵋真人发觉中了血魔诡计，一场更为凶险的正邪大战即将展开……©豆瓣', '郑伊健', '徐克', 6.9, 81759, 'tt0286098', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1245072901.jpg', 2.5, 11.5, 40.9, 30, 15.2, '-0.094850,0.220288,-0.229486,0.676040,0.337718,-0.122592,-0.006036,0.275864,-0.621986,-0.320544,0.207895,0.540233,0.140120,0.030068,-0.019430,-0.099701,0.374879,-0.511508,-0.322093,-0.246985,-0.041486,0.232836,-0.055465,0.204551,-0.139067,-0.650547,0.714199,0.628780,-0.152952,0.411111,0.296541,0.047740,-0.826651,0.525682,0.248161,-0.178692,-0.156193,0.207257,-0.299880,0.211629,-0.571843,-0.129008,-0.065094,0.491297,-0.433552,0.677249,0.239822,-0.192572,-0.200790,-0.350392,-0.230931,-0.041580,0.019876,0.239868,0.598680,0.289426,0.368961,0.373714,0.029880,0.106738,-0.192596,-0.082688,-0.207130,0.092552,0.425814,0.012866,0.068008,0.490023,-0.206412,0.296601,-0.251818,-0.298413,-0.183093,0.266661,0.360348,-0.328015,-0.286331,-0.538055,-0.275171,0.081612,0.517233,-0.482311,0.593839,0.029765,0.440836,-0.338096,-0.195296,-0.478546,0.136457,0.268628,0.529935,-0.024610,0.218751,0.665164,-0.317501,-0.104763,-0.296334,0.630064,-0.379710,0.105114,0.222982,-0.611773,0.171595,0.129510,-0.398312,-0.202105,0.232218,0.283749,0.578891,-0.390104,0.298092,0.112396,0.093585,-0.169877,0.471593,-0.321179,-0.175169,-0.158841,-0.537565,0.625053,0.275824,0.673127,-0.040606,0.124640,-0.180350,0.029764,0.016598,-0.180653', '26661191', '1763916', '25779217', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308345', '野兽之瞳', '剧情', '冲（吴彦祖 饰）和瞳（古天乐 饰）是同卵双胞胎，自小冲就生活在哥哥瞳的光芒之下。岂料在冲26岁生日那天，收到了瞳的死讯。冲在瞳的遗物中找到了一条钥匙，由此走进了瞳的世界。瞳结识女友阿陆（谷祖琳 饰）时，曾教训了阿陆的前古惑仔男友阿文（谭耀文 饰）。阿文领教完瞳的重拳后，发现瞳天生就是拳击界的冠军，于是担任起瞳的经纪人，带着瞳去参加黑市拳比赛。瞳所向披靡，由此他和阿文成了莫逆。阿陆、瞳、阿文三人过着风光的生活。岂料瞳因破坏黑市拳集团的游戏规则，被集团请来的黑人拳手活活打死。阿文在冲身上又看到了瞳的影子，他的引领下，冲日夜训练，渴望打败那名黑人拳手，为瞳报仇……©豆瓣', '古天乐', '梁柏坚', 6.6, 8758, 'tt0287155', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2564382337.jpg', 1.3, 10.1, 53.3, 26.7, 8.6, '-0.100760,-0.017313,-0.209028,0.465498,0.093470,0.052380,0.226372,0.212842,-0.021215,-0.134640,0.172187,0.689309,-0.154653,0.578182,0.596145,-0.007903,-0.006964,-0.824750,-0.520630,-0.034048,-0.292553,-0.203568,-0.046992,0.398986,0.369789,-0.570266,0.720266,-0.221531,-0.456907,0.838881,0.285259,0.267089,0.160471,0.105743,-0.428353,-0.162627,0.199559,0.166290,0.066285,0.360588,0.076341,-0.268735,-0.325096,0.168238,0.210050,0.121225,0.550247,-0.397081,-0.068738,-0.159767,0.246538,-0.238901,-0.252097,-0.171268,0.071485,-0.036373,0.200609,0.162199,0.078119,0.018626,0.079886,-0.201378,-0.665609,0.098887,0.194115,-0.108585,-0.885769,0.333358,-0.096522,0.228474,-0.014656,0.048530,0.326677,0.147352,-0.230322,0.251562,-0.119029,0.202028,-0.390696,0.324448,0.619181,-0.276217,0.084509,0.150822,0.065744,-0.153689,-0.193004,0.480876,0.027146,-0.176390,0.792313,-0.204296,-0.386991,0.050679,-0.552569,-0.267671,-0.306339,0.168312,0.218980,-0.200278,-0.312803,-0.675970,-0.217644,-0.624502,-0.144042,0.395935,-0.289572,-0.119472,0.404390,-0.927660,0.218951,0.291828,0.589191,-0.090650,1.156993,-0.345975,-0.113144,-0.425345,-0.101000,-0.062508,0.230429,0.034343,0.218916,0.523018,0.115912,-0.076529,-0.421874,0.101096', '1897368', '2124718', '3139191', '2046839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308355', '猛鬼食人胎', '剧情', '故事发生在清末民初，徐大帅（徐锦江 饰）于古墓之中获得了五魔瓦盅，将其连同镇压它们的金佛一同收入囊中，起初，由于金佛的镇压，五魔不敢轻举妄动，然而，管家见金佛起了贪念，将它偷走，这下五魔终于重获自由，蠢蠢欲动准备兴风作浪。徐大帅有四房太太，五魔附身在徐大帅体内，将它们的胎种种在了四位女子体内，府内的厨师初六（张锦程 饰）和其恋人小鱼（吴辰君 饰）亦不能幸免，之后，五魔残忍的将已经没有用处的徐大帅杀死。驱魔法师青海（黄秋生 饰）得知此事，联手初六发誓要将五魔降服，几场惊心动魄的大战之后，青海身负重伤性命不保。©豆瓣', '吴辰君', '梁宏发', 6, 4861, 'tt0327628', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2002248594.jpg', 4.3, 19.3, 53.5, 15.6, 7.2, '-0.034668,0.293879,-0.617247,0.501697,0.017734,-0.183170,0.754607,-0.063855,-0.376151,-0.212508,-0.111724,0.242451,-0.348690,-0.007909,0.065036,-0.353964,0.212316,-0.628231,-0.366006,-0.020600,-0.259271,-0.220310,-0.322976,-0.055514,-0.185958,-0.295168,0.424273,0.199306,-0.156414,0.165978,0.346381,0.265085,-0.307306,0.197351,-0.209092,0.267267,-0.421006,-0.035180,-0.215463,0.285458,-0.011825,-0.484467,0.086278,0.317060,0.268125,0.042034,0.776937,-0.536831,0.000421,-0.289340,0.202629,0.035399,-0.117447,0.200271,0.415101,0.180881,0.015420,0.166104,-0.436996,-0.003512,0.241832,0.130219,-0.620876,-0.061048,0.277107,0.020782,-0.420993,0.039478,0.068526,0.356514,-0.252080,-0.257931,0.252920,0.497368,0.021042,-0.161654,0.091850,-0.189446,-0.640279,0.298327,0.552558,-0.360732,0.099883,-0.220276,0.337375,-0.461612,-0.078589,-0.225795,-0.090057,0.025169,0.688814,0.356618,0.172828,0.285864,-0.372121,-0.700117,-0.320866,-0.093772,-0.014646,0.161729,0.241901,-0.100992,-0.151778,-0.242744,-0.144173,-0.056675,0.411296,-0.050169,0.616434,-0.674451,0.454708,0.083485,0.202794,-0.547961,0.357412,-0.071319,0.456268,-0.080319,0.206300,-0.206342,0.298558,0.420187,0.616570,0.467628,-0.272600,-0.076151,-0.276696,0.263734', '21619567', '1293035', '1301022', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308366', '国王与小鸟', '动画', '塔基卡迪国建立在一片荒漠中。现在正值第三加第五等于第八加八等于第十六代夏尔国王掌权。夏尔国王不喜欢人民，人民也不喜欢他。国王住在200多层城堡的最高处，而人民则被强迫住在不见阳光的地下，做着苦活。城堡里四处都是国王的雕像，画像和眼线。掌握集权和他人生死的国王也有自己的烦心事，他爱上了迷人的牧羊姑娘。但姑娘却追随着扫烟囱的少年，想要逃离这座城堡。二人的出走得到了小鸟的支持。虽然小鸟极尽帮助，但牧羊姑娘还是被国王逮住，而扫烟囱的少年和小鸟则被关进了狮群。暗无天日的环境让狮子们丧失了斗志，但在小鸟一番煽动下，终于恢复了往日的雄风。于是狮群和小鸟们向着国王的婚礼进发。最终扫烟囱的少年能否救回牧羊姑娘，夏尔国王的集权世界又能否被打破。国王与小鸟，压迫与自由的故事就此上演。©豆瓣', '让·马丹', '保罗·格里莫尔', 8.7, 12349, 'tt0079820', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2589218453.jpg', 0.3, 1, 12.5, 37.6, 48.7, '0.223070,0.059490,-0.618193,0.743181,-0.058102,-0.178132,0.765563,0.264340,-0.400463,0.175453,0.358784,0.688592,-0.014265,0.169447,0.223686,0.282832,-0.344552,-0.721458,-0.310958,-0.066253,-0.075913,-0.384759,-0.208184,-0.189025,-0.011388,-0.331553,0.808568,0.141656,0.070304,0.195831,0.115114,0.017283,-0.063500,0.377611,-0.327665,-0.192838,-0.064642,-0.051627,-0.083006,0.316475,-0.134384,-0.394751,-0.241975,0.252956,-0.018489,0.148662,0.679887,-0.952168,0.091213,-0.236797,0.094645,-0.300586,0.095489,0.370162,0.332890,-0.278892,0.060262,0.170595,-0.046016,0.033334,-0.008958,-0.291316,-0.335081,-0.029819,0.019225,0.366763,-0.680708,0.740247,0.011475,-0.179783,0.125328,-0.270132,0.286782,0.066528,0.124165,0.560914,-0.233917,0.115138,-0.692628,-0.116598,0.537665,0.148054,-0.245417,0.012660,-0.284179,-0.446829,-0.000112,-0.213748,-0.374117,-0.311526,0.411729,0.159212,-0.236770,0.335491,-0.795172,-0.063379,-0.446198,-0.459510,-0.025123,-0.674701,-0.251278,-0.396315,-0.068747,-0.361835,0.067197,0.161976,0.305771,-0.270806,0.529287,-1.024070,0.295240,0.285494,0.447300,-0.353930,0.783991,0.003882,0.109251,0.033268,-0.174416,0.107421,0.129957,0.670694,0.381569,0.189402,-0.330142,-0.341180,-0.523393,0.515783', '3055049', '21619567', '1417036', '4217526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308367', '儿女一箩筐', '喜剧', '这个家庭有着一对父母、十二个孩子和一堆宠物，热闹混乱的局面反而为家庭增添快乐。尤其是那些性格不一、年龄各异的儿女们，就像活宝一样深得父母欢喜。现在，这家人正面临着前所未有的变化：因为父亲汤姆（史蒂夫·马丁 Steve Martin 饰）要去大城市的高校球队任教，他们要搬往那里生活了，这亦意味着，孩子们会有更好的教育和更广阔的发展空间；当然，父母日渐繁忙的工作也会削减他们和孩子沟通的时间。母亲凯特（邦尼·亨特 Bonnie Hunt 饰）的作家事业也如日中天，甚至要离家宣传新书。孩子们已经和父母日渐生疏，大城市的生活让这个家庭得到了日渐光鲜的地位，却失去了内在的情感纽带。看来，汤姆和凯特要重新思考和抉择了。©豆瓣', '史蒂夫·马丁', '肖恩·利维', 7.1, 15062, 'tt0349205', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1526583464.jpg', 0.5, 3.7, 48.2, 37.3, 10.2, '0.099375,-0.291748,-0.580278,0.563783,-0.024190,-0.386778,0.706357,0.527971,-0.713738,-0.245641,-0.028814,0.835087,0.056711,0.419256,0.098299,-0.092714,-0.517392,-0.663041,-0.071956,0.025578,-0.184972,-0.393789,-0.238400,-0.464478,-0.222166,-0.204045,0.624902,-0.103158,-0.052984,0.384563,0.074404,0.043881,0.094983,0.429146,-0.300650,-0.032348,-0.002878,0.229913,-0.292030,-0.108325,0.156450,0.216147,-0.115394,0.134514,0.364808,0.242196,0.712033,0.033967,-0.324859,-0.218540,0.427795,0.010839,-0.160883,0.239543,0.360875,-0.291340,0.297456,0.185291,-0.141169,0.053749,-0.101708,-0.357386,-0.866171,0.161467,0.285434,0.096573,-0.709882,0.434530,0.239562,-0.321717,0.108263,-0.243878,0.228598,0.767273,0.035831,0.629839,-0.265360,-0.162745,-0.528616,0.244745,0.751787,-0.057873,-0.270772,0.409575,-0.869932,-0.268395,-0.315472,-0.445502,-0.765866,-0.123578,0.254402,0.181679,-0.241175,0.564400,-0.587445,0.168030,0.000200,-0.351141,0.084102,-0.633675,0.187544,-0.566133,-0.142230,-0.722348,-0.458629,-0.037443,0.234267,-0.246304,1.288635,-0.894127,-0.034039,0.344448,0.363521,-0.987770,0.763939,0.176616,0.370837,-0.313487,0.040918,0.148585,-0.347589,0.020515,-0.168047,0.166397,-0.014098,-0.168501,-0.191323,0.606101', '26348103', '25882279', '24284209', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308379', '阴阳师2', '动作', '平安时代，百鬼夜行，封鬼仪式正在右大臣藤原安麻吕府邸进行。安麻吕之女日美子（深田恭子 饰）戎装登场，一箭命中靶心，引来全场惊叹。这位被喻为“连鬼都不敢接近”的公主，却令源博雅（伊藤英明 饰）暗自倾心。天现异象，京都骚动，魍魉横行。平安京已有四人遇害，民间出现驱鬼术士幻角（中井贵一 饰），日美子亦在异象后开始梦游。博雅为此替右大臣来请安倍晴明（野村万斋 饰）商谈。与此同时，宫廷供奉的出云三神器之一草薙剑也出现了异动。晴明受天皇所托，与博雅开始调查种种异况背后出云与大和的隐秘渊源。博雅和夜弹琵琶的神秘少年须佐（市原隼人 饰）相识为乐友，须佐负伤被日美子所救，三人在右大臣府邸相逢。同一时刻，右大臣主动找到晴明，坦白了十八年前天现异象时，大和攻打出云的事实……本片为电影《阴阳师》续作。©豆瓣', '野村万斋', '泷田洋二郎', 7.7, 18284, 'tt0383543', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p991080197.jpg', 0.5, 3, 29, 44.7, 22.8, '-0.193910,-0.114767,-0.398589,0.128478,0.503696,0.090225,0.351548,0.289653,-0.399654,-0.464902,0.641414,0.464801,-0.471786,0.013255,0.387590,0.060188,-0.099857,-0.642746,-0.027850,-0.034665,-0.034405,-0.278261,0.041961,-0.129791,-0.168242,-0.425180,0.264431,0.064152,0.076942,0.602399,0.095319,0.501458,-0.436957,0.090361,-0.092690,-0.001179,0.010993,0.152626,-0.278038,0.122027,-0.502320,-0.382005,-0.354014,0.083886,-0.109804,0.181135,0.295499,-0.383752,0.077426,-0.314503,0.205635,0.050744,-0.054063,0.234352,0.490446,0.074279,0.082903,0.205878,-0.053415,0.019561,-0.140465,0.276694,-0.230423,0.290916,0.137578,0.106302,-0.158153,0.407249,-0.172877,-0.124122,0.071025,-0.456900,0.249604,0.219629,0.266618,-0.075398,-0.220429,0.113016,-0.079974,-0.040829,0.409095,-0.038610,-0.043330,-0.096805,0.256604,-0.492273,-0.338633,-0.024394,-0.035816,0.118230,0.199042,0.054040,0.211254,0.566013,-0.199393,-0.253382,-0.260188,0.066437,0.309798,0.165034,-0.251246,-0.649784,0.040984,-0.210335,-0.209900,-0.050498,0.560486,0.003250,0.596211,-0.598315,0.067427,0.290627,0.218800,-0.247492,0.529792,-0.066948,0.033386,-0.034157,-0.336789,-0.184045,0.175494,0.460659,0.115891,0.127071,-0.186581,-0.173710,-0.424205,-0.281890', '25723905', '26365262', '2357711', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308384', '爱情梦幻号', '爱情', '富家子弟学津（刘德华 饰）自命不凡，多次恋爱后均迅速对对方无感觉，经常在订婚分手。这次，学津看上了来自上海的女服务生文青（瞿颖 饰），文青大方得体，和学津以及他的家人朋友都很聊得来。于是，学津准备与文青一起乘豪华邮轮作远洋旅游，并在船上举行盛大的订婚仪式。学津有所不知的是，文青的大方得体、学识广博其实是她每晚都努力准备好次日的聊天话题的结果，而文青也开始逐渐厌恶这种生活，她感到十分疲累。两人上船后，文青邂逅了服务生乐文（黄磊 饰）；而学津则在和一个叫红叶（石田光 饰）的女生针锋相对后，学津发现自己疯狂的爱上了对方。两人能否在船上找到属于自己的梦幻爱情？©豆瓣', '刘德华', '邱礼涛', 5.8, 13792, 'tt0188615', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2226449093.jpg', 5.7, 23.7, 51.8, 13.6, 5.2, '0.407922,0.058263,-0.728417,0.402923,-0.110470,-0.415841,0.546552,0.199264,-0.537755,-0.223030,0.104851,0.671340,-0.294628,0.281065,0.371591,0.083270,-0.545870,-0.703450,-0.041752,-0.014127,-0.266262,-0.409085,0.277120,0.035357,-0.179179,-0.044810,0.087045,-0.069818,0.070755,0.871038,0.369971,0.122413,-0.146678,0.736825,-0.178956,-0.150148,0.025404,0.107907,-0.366180,-0.095110,-0.163957,0.047455,-0.195485,0.282186,0.194163,0.353982,0.671341,-0.017819,-0.388245,0.150908,0.427090,0.033417,-0.030383,0.033249,0.259063,0.196902,0.321610,0.045008,-0.207375,-0.031925,0.040839,0.016237,-0.537000,0.243770,0.114582,0.116651,0.018018,0.779549,0.038046,-0.049606,0.085489,-0.517977,0.200841,0.258117,0.359293,0.103216,0.103185,0.196044,-0.254871,0.364287,0.815687,0.406274,0.198633,0.455796,-0.336255,-0.292700,0.041222,-0.094177,-0.395464,-0.196316,0.071433,0.070174,0.171615,-0.142923,-0.656711,0.127846,0.116164,0.248168,0.085583,-0.288163,-0.010129,-0.693732,-0.155979,-0.598707,-0.249396,-0.057702,0.013141,-0.322644,0.628410,-0.950213,0.179723,0.401888,0.322193,-0.331866,0.698172,0.194129,-0.098433,-0.205116,-0.092022,-0.127266,-0.205922,0.043724,0.108622,0.585346,-0.043354,-0.097846,-0.270443,0.466048', '3139191', '1292219', '1301562', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308424', 'BEYOND日记之莫欺少年穷', '喜剧', '家驹（黄家驹 饰）、自强（黄家强 饰）、世荣（叶世荣 饰）以及贯中（黄贯中 饰）四个年青人自组乐队，醉心于音乐，但他们每个人都有自己的梦想。世荣深爱女友马莉（王菲 饰），但身为医学教授的未来岳父加能却不赞同他从事音乐，加能固执的令晕血的世荣进入医科学习；梦想成为警察的贯中因身体素质不过关，全靠诚意打动了警方考官，得以从不起眼的交通督导员做起；家驹一家希望移民美国开餐馆，为了这个目标，全家展开赚钱比赛，家驹身兼数职，一刻不得闲；初入职场的自强豪情万丈，自信能够凭借努力成为第一流的经纪人。四个年青人为了理想打拼，一路经历诸多坎坷欺骗，他们的梦想能否成真？©豆瓣', '黄家驹', '宋豪辉', 8.2, 9217, 'tt0101439', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1209935896.jpg', 0.6, 2.1, 21.5, 40.4, 35.4, '-0.038011,0.060153,-0.330240,0.239250,-0.318547,-0.429280,0.209715,0.057531,-0.478718,-0.365636,0.354247,0.555576,0.343417,0.178691,0.032758,-0.215777,0.090479,-0.521608,0.297625,0.041022,0.271489,-0.316562,-0.103490,-0.064802,-0.314571,-0.238799,0.624955,0.103422,-0.107747,0.505003,0.215084,0.148675,0.093434,-0.194434,0.007366,-0.069841,0.377208,-0.055272,-0.632362,0.031018,-0.198510,0.100989,-0.100884,-0.033533,-0.137777,0.090832,0.438298,0.151021,-0.143436,-0.017371,0.388037,-0.256487,-0.202550,0.092205,0.028012,0.355100,0.228949,0.261799,-0.031508,0.023764,-0.144188,-0.096729,-1.013682,0.016769,0.256827,0.097931,-0.442443,0.398808,-0.054566,-0.295702,-0.073430,-0.311976,-0.046976,0.233372,0.281816,0.425615,-0.250033,0.455035,-0.336736,0.335509,0.806644,-0.143230,-0.253535,0.412294,-0.270362,-0.096186,0.222402,-0.399405,-0.588546,0.038849,-0.029795,-0.018014,0.038031,-0.090036,-0.414808,0.232401,-0.139304,0.072417,0.176248,-0.281094,0.022096,-0.373488,-0.052570,-0.315451,-0.155427,-0.264297,0.020957,-0.604505,1.088193,-0.719068,-0.113022,0.300302,0.002658,-0.716307,0.688528,0.250207,0.043078,-0.197161,-0.129163,0.319914,-0.160031,0.117623,-0.299689,0.233590,-0.086781,-0.431965,-0.334045,0.276700', '24284209', '27602116', '26678784', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308429', '美国派3：美国婚礼', '喜剧', '这帮高中时候就一起计划怎么脱离处男身的老友们现今已经长大，就在他们即将踏出大学校门的时候，传来了吉姆（贾森·比格斯 Jason Biggs 饰）和米歇尔（艾丽森·汉妮根 Alyson Hannigan 饰）即将举行婚礼的消息，更加碰巧的是婚礼和他们的成人礼巧合在同一日。 于是，这帮死党相约为吉姆举行最后一次单身派对，当然史蒂夫（西恩·威廉·斯科特 Seann William Scott 饰）其实是不想放过婚礼上漂亮的女傧相。芬奇担忧自己性感漂亮的妹妹柯登斯落入了史蒂夫的手中，于是也来到参加吉姆的单身派对，一连串妙趣横生的场面自然让你笑破肚皮。©豆瓣', '贾森·比格斯', '杰西·迪伦', 7.1, 40370, 'tt0328828', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1335098268.jpg', 0.8, 5.3, 46.8, 34.1, 13, '0.196104,-0.153485,-0.781647,0.278415,-0.129528,-0.511665,0.470481,0.122535,-0.167664,-0.093238,0.181122,0.839945,-0.547156,0.454621,0.410888,0.019100,-0.423346,-0.704762,0.111854,-0.146336,-0.271712,-0.399538,0.127235,-0.053889,0.233294,-0.258353,0.407918,-0.009590,0.072189,0.774999,0.631537,0.198224,-0.067441,0.402058,-0.323042,-0.334995,0.335512,0.164739,-0.362168,0.073009,-0.020360,0.067478,-0.200659,0.018159,0.276116,0.220884,0.449316,-0.111145,-0.013851,-0.117752,0.211754,-0.248809,0.005729,0.354845,0.208998,-0.094004,0.407877,0.257026,-0.253563,0.067747,-0.039404,-0.284027,-0.371481,0.480819,-0.014294,0.049995,-0.673830,0.463881,-0.116033,-0.242629,0.331658,-0.311681,0.324630,0.607933,0.256293,0.177703,-0.039877,-0.020602,-0.351452,-0.119489,0.936554,0.109146,-0.034902,0.274969,0.173228,-0.377029,0.063971,0.045015,-0.366881,0.403349,0.163111,-0.253776,-0.030872,0.222538,-0.332893,-0.294194,-0.084811,-0.239761,0.154590,-0.297174,-0.229316,-0.825375,0.073885,-0.153810,-0.407522,0.036692,-0.027059,-0.058164,0.538558,-0.835189,0.347411,0.254797,0.196435,-0.351171,0.738660,0.296362,0.258711,-0.221288,-0.180624,-0.225114,-0.032978,0.102895,-0.076898,0.494900,0.244553,-0.406733,-0.300897,0.671571', '26687241', '11541282', '1297239', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308457', '美食家', '喜剧', '美食杂志主编Charles Duchemin（Louis de Funès）具有天赋异禀的嗅觉和味觉，食物经他的鼻子一闻、嘴巴一品，是否真如传说中美味便可得知。为了让读者品尝到真正可口的食物，他常乔装打扮潜入各大饭店、旅馆品尝食物，好的，他会在杂志上极力推荐，差的，则痛快骂之。因此，他成了饭店、旅馆老板眼中的魔鬼，却也是读者心中的上帝。因为年事已高，Charles Duchemin很想让在嗅觉和味觉上也有超人天赋的儿子Gérard Duchemin（Coluche）子承父业，无奈后者只对马戏感兴趣，经常瞒着他去马戏团做小丑，笑话于是迭出。但一位妄想吞没法国餐饮业的快餐大亨令父子两人最终联起手来。©豆瓣', '路易·德·菲奈斯', '克洛德·齐迪', 8.4, 8967, 'tt0074103', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2164361020.jpg', 0.2, 0.8, 15.8, 47.8, 35.5, '0.353695,0.210423,-0.532365,0.563432,0.134141,-0.117007,0.549139,0.361866,-0.620847,0.054554,0.121304,0.879763,-0.312142,0.169088,0.099495,0.051356,-0.071458,-0.454485,0.090662,-0.122619,-0.031050,-0.223399,-0.336146,-0.256510,-0.055528,-0.017882,0.090422,-0.012983,-0.430293,0.141075,0.104267,-0.191445,0.161776,0.397975,-0.319863,-0.124332,0.015678,0.008885,-0.166690,0.097356,0.365495,-0.231253,-0.156693,0.306505,0.180492,-0.050635,0.335480,-0.058282,-0.554579,-0.097322,-0.012274,-0.283981,0.204370,0.193483,0.103445,0.056460,0.398365,-0.167692,0.061269,0.105490,-0.214547,0.169090,-1.019970,-0.165583,0.137789,-0.130844,-0.389714,0.322803,-0.024037,-0.127547,0.030047,-0.353438,0.150021,-0.111208,0.170889,0.579402,0.209928,0.177645,-0.634472,0.152954,0.480700,0.301183,0.021964,0.085362,-0.312624,-0.641797,0.096137,-0.342195,-0.214908,0.016881,0.219775,0.318190,-0.152503,0.204382,-0.739219,0.208672,0.020912,-0.231125,0.278268,-0.229413,-0.020558,-0.510694,-0.077782,-0.287523,-0.111226,-0.167639,0.495803,-0.419305,0.861747,-0.653486,-0.023750,0.606248,0.057807,-0.469104,0.829487,0.017256,-0.225005,0.120122,-0.368423,0.153743,0.292100,0.005464,0.192367,0.421289,0.231903,-0.342845,-0.358696,0.260996', '1793491', '27602116', '24284209', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308476', '人咬狗', '剧情', '热爱吟诵诗歌且幽默健谈的杀手贝罗特（Benoît Poelvoorde 饰）自费请来一支摄制组为他拍摄纪录片。在镜头前，他毫无保留且毫无隐讳地展现每次行凶的全过程，并悉心讲解不同的杀人技巧。摄制组成员从最初的观众逐渐演变成贝罗特的帮凶，这一种疯狂之人仿佛失控的汽车，飞速向毁灭的终点驶去……本片成本仅为15000美元，却成为比利时当年商业上最成功的影片，并且荣获1992年戛纳电影节SACD奖最佳影片和青年特别奖、1993年法国电影评论协会奖最佳外语片奖、1992年Sitges – Catalonian国际电影节最佳男主角（Benoît Poelvoorde）和最佳影片奖、1992年多伦多国际电影节Metro媒体奖。本片导演Rémy Belvaux于2006年9月4日去世，享年40岁。©豆瓣', '伯努瓦·波尔沃德', 'Rémy Belvaux', 8, 7506, 'tt0103905', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204694302.jpg', 1.3, 3.6, 18.9, 44.7, 31.6, '-0.486685,-0.102111,-0.470384,0.766877,0.431595,-0.009747,0.344417,-0.222270,-0.511241,0.026165,0.274558,0.853123,-0.495318,0.030736,0.720795,-0.352283,-0.378096,-0.850961,-0.320641,-0.229706,0.068863,-0.072986,-0.274152,-0.053307,-0.344765,-0.270168,0.829640,0.027241,-0.114824,0.669773,0.522190,0.025029,0.126207,-0.053767,0.141726,-0.108785,0.343697,-0.036128,-0.470913,0.389336,-0.121337,-0.657430,-0.482030,-0.130787,0.032305,0.141523,0.857390,-0.154218,0.001348,-0.035532,0.953528,-0.500178,-0.184457,-0.257254,0.226821,0.248934,0.365551,0.188068,0.119039,0.064338,-0.108646,-0.620431,-0.773592,0.048382,0.064717,-0.041798,-0.295819,0.506828,-0.126087,0.580800,-0.246234,-0.212125,0.009987,0.018667,0.195292,0.164881,-0.197544,-0.007693,-0.174574,0.850812,0.339807,-0.004012,-0.592808,0.353259,-0.063878,-0.828071,-0.232380,-0.451103,-0.281033,0.242663,0.335921,0.010632,0.189014,0.223567,-0.377621,-0.074901,0.099336,-0.495996,0.164589,-0.119968,-0.092310,-1.041462,0.076319,-0.196756,0.183570,-0.327243,0.052381,-0.305156,0.918776,-0.517951,0.395779,0.503275,0.195081,-0.157206,0.837852,-0.221258,-0.119483,-0.257165,-0.600294,0.246476,-0.258010,0.040538,-0.269524,0.209948,-0.133152,-0.283572,-0.108000,0.350616', '30397916', '22265121', '2027945', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308480', '那时花开', '爱情', '他们的故事发生在大学期间，最美丽的岁月和最难忘的画面，都在迅速铺开。高举（夏雨 饰）在女朋友出国后迎来了一个乐队合伙人张扬（朴树 饰）。他们生性自由散漫，一天在礼堂顶上看着刚入学的新生，遇见了欢子（周迅 饰）。欢子在人群中耀眼的美丽让他们倾心，并开始了攻势。高举出于友谊第一的考虑，同意只在周六才和欢子一起。三人之间依稀的感情始终在青葱岁月里暗暗流动，他们在青春里，或许都有自己随心所欲的率性和幻想。“后来，我们分道扬镳，发誓不再提起往事。欢子就象从我们手指间流走的那种叫作岁月的东西一样，偶而还会涌上心头。”在高举他们心中，这就是最好的时光。©豆瓣', '周迅', '高晓松', 7, 20539, 'tt0385893', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2506732620.jpg', 2.5, 8.8, 38.9, 34.5, 15.3, '0.246616,-0.012054,-0.882275,0.540515,-0.020766,-0.295978,1.012684,0.111707,-0.291767,0.004272,0.084887,0.555021,-0.326956,0.423624,0.304300,-0.333507,-0.327962,-0.884322,-0.101692,-0.409875,-0.100279,-0.329381,-0.021722,0.001509,0.125882,-0.297147,0.657899,-0.032764,-0.008949,0.738581,0.229021,-0.048117,-0.231572,0.439226,-0.363840,-0.022439,-0.089886,0.672683,-0.317015,-0.100223,0.136446,-0.478079,-0.108421,-0.017534,-0.099999,0.024271,0.761736,-0.321093,-0.045687,0.225962,0.162381,-0.093134,-0.138700,0.125247,0.316745,0.021064,0.246883,0.324677,-0.389121,0.271601,-0.154014,-0.109504,-0.501703,-0.054628,0.004876,0.291545,-0.677414,0.619532,0.218339,-0.178736,0.393931,-0.440983,0.208908,0.223397,0.194869,0.304545,-0.292405,-0.084282,-0.446464,0.272750,0.804171,0.101590,-0.180833,0.532453,-0.211335,-0.210170,-0.269595,0.364927,-0.310718,-0.154482,0.256974,0.099819,-0.196479,0.304441,-0.743247,0.228200,0.286068,-0.283103,0.245499,-0.521593,-0.194470,-0.459795,-0.298237,-0.565501,-0.407807,0.299062,-0.012122,-0.142351,0.787339,-0.945702,0.345441,0.358617,0.142014,-0.111072,0.830331,0.322756,0.050465,0.014748,0.011770,0.358638,-0.120049,0.411348,-0.028941,0.526904,-0.162754,0.154478,-0.363672,0.684944', '1292211', '3111650', '34973399', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308482', '双雄', '惊悚', '自负能干的“保护要员组”警员李文健（郑伊健 饰）因性格问题与女友Brenda（林嘉欣 饰）的感情亮起红灯。因为一起棘手案件，他与正在监狱服役的原警方心理组的催眠师黎尚正（黎明 饰）打上交道。尽管知晓黎尚正厉害的李文健表现得异常谨慎，却仍被黎尚正神不知鬼不觉的催眠，助其盗 走了要保护的南非宝钻。在寻回宝钻的过程中，李文健发现黎尚正盗钻实属无奈，他其实是一个正直、善良、忍辱负重的真男儿，决意协助他来共同对抗拿其妻子（徐静蕾 饰）和好友一双儿女的性命进行威胁的黑帮大枭欧阳锐（吴镇宇 饰），并在此过程中回归了与Brenda的感情。©豆瓣', '黎明', '陈木胜', 6.4, 38626, 'tt0379985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486795274.jpg', 1.2, 9.7, 60, 23.9, 5.2, '-0.067402,-0.066575,-0.321880,0.584178,-0.282657,-0.061335,0.521578,0.080381,-0.594358,-0.231996,0.199593,0.599793,-0.092260,0.120069,0.012141,-0.056955,-0.233359,-0.625548,-0.312010,0.198423,-0.133998,-0.571867,-0.209837,0.061322,-0.138101,-0.168876,0.659945,0.006279,-0.305319,0.496270,0.166660,0.262833,-0.343499,0.387319,0.080244,-0.373634,-0.050698,0.277626,-0.206132,-0.114077,-0.028662,-0.311451,-0.182913,0.156640,0.221001,0.482074,0.585138,-0.289253,-0.016158,-0.176870,0.204834,-0.315609,-0.145280,0.073216,0.168660,0.222037,0.229715,0.172088,0.013236,0.013500,0.134041,-0.115976,-0.847791,-0.279061,0.396050,0.030658,-0.523942,0.298742,-0.284810,0.100084,0.119552,-0.041320,0.082591,0.366818,0.066330,0.246522,-0.269853,0.182089,-0.407515,0.116146,0.370060,-0.103743,0.082729,0.209379,-0.017825,-0.594617,0.082296,0.022339,-0.181382,-0.330422,0.306352,-0.112273,0.043967,0.031075,-0.382499,0.063233,-0.111523,0.154144,-0.011579,-0.405823,-0.001876,-0.439405,-0.091281,-0.601374,-0.373453,0.289289,-0.028422,-0.125678,0.559641,-0.577830,-0.000662,0.319807,0.120127,-0.640324,0.569438,0.252478,0.046972,-0.380941,-0.361658,0.268758,0.015036,0.149011,0.127843,0.206986,-0.277839,-0.273606,-0.458609,0.073170', '3670447', '26678784', '4301278', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308484', '奇招尽出', '喜剧', '从看到阿曼达（克里斯蒂娜·里奇 Christina Ricci 饰）第一眼起，杰瑞（贾森·比格斯 Jason Biggs 饰）就深深的爱上了她，尽管此时的杰瑞身边已有佳人相伴而阿曼达亦名花有主，但这残酷的事实依旧无法阻挡杰瑞渴求阿曼达的心。并且，撇开世俗道德不谈，两人也确实是天设地造的一对。就这样，都并非“自由身”的两人走到了一起，而他们之间的私情很快就东窗事发了，杰瑞的女友和阿曼达的男友选择退出，杰瑞终于可以名正言顺的和阿曼达出双入对了。如果你以为故事到这里就结束了那可真是大错特错，好不容易在一起的杰瑞和阿曼达之间发生了巨大的分歧和矛盾，两人之间的感情眼看着岌岌可危，为此，杰瑞向自己的导师大卫（伍迪·艾伦 Woody Allen 饰）求助，殊不知，这个在自己眼中无坚不摧的男人，在生活上其实也千疮百孔。©豆瓣', '贾森·比格斯', '伍迪·艾伦', 7.1, 7630, 'tt0313792', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1073936274.jpg', 0.6, 5.8, 43.2, 37.5, 13, '0.688385,-0.170376,-0.863171,0.460160,-0.181903,-0.676274,0.792826,0.127715,-0.415818,0.012050,0.061729,0.714250,-0.450081,0.161608,0.293766,0.049321,-0.529483,-0.929993,-0.247185,-0.409196,-0.195565,-0.735650,-0.195864,-0.002789,-0.242736,-0.066497,0.561503,-0.280450,-0.004607,0.607370,0.304517,0.148729,0.066895,0.579103,-0.046998,-0.005383,0.040733,0.038438,-0.218855,0.136198,0.317116,0.013517,0.044390,0.342028,-0.148837,0.354955,0.476497,-0.457038,-0.048365,0.061372,0.138247,-0.147170,0.329416,0.319431,0.193730,-0.325536,0.272697,0.213445,-0.243250,-0.120703,0.218251,0.155679,-0.687005,0.258025,-0.140711,0.107069,-0.440125,0.630747,-0.145926,-0.395220,0.303995,-0.314605,0.202147,0.436835,0.174939,0.316878,-0.510470,-0.217128,-0.738561,-0.230668,0.621990,0.365413,-0.137896,0.200749,-0.186426,-0.451623,-0.402703,0.007172,-0.385820,-0.332895,0.301140,0.266227,-0.014766,0.306885,-0.516741,0.085904,-0.289062,0.141625,-0.139358,-0.593953,0.184004,-0.388070,-0.243200,-0.732018,-0.444914,0.120384,0.037787,-0.431165,0.574142,-0.682704,0.292270,0.489668,0.520218,-0.063077,0.711189,0.095537,0.069221,-0.179081,-0.099124,0.335464,-0.253232,0.301793,0.475291,0.497493,0.229157,-0.119887,-0.317317,0.698459', '1292211', '25837574', '1301582', '1308974');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308491', '中毒', '剧情', '浩真（李臬 饰）和恩淑（李美妍 饰）两夫妻过着幸福的日子。浩真有个弟弟大真（李秉宪 饰），热爱赛车。一天大真正在赛车，浩真赶往赛场观看，二人同时在不同的地方出了车祸。首先醒来的是大真。奇怪的事情连连出现。大真竟然一反出事前的性格，好像完全成为了浩真——他的性格，举止，谈话，回忆，全部都像是浩真附了体。浩真尚在昏迷中，悲伤的恩淑对大真的变化非常奇怪的同时，也不禁相信有着某种超自然的存在，慢慢接受大真变成了丈夫浩真。医院宣布浩真脑死亡的时候，恩淑相信其实丈夫并没有死去，他时刻在身边。然而，一条项链的出现，却让一切变得可疑——大真有着不可告人的秘密。©豆瓣', '李秉宪', '朴英勋', 7, 12270, 'tt0336678', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1655803827.jpg', 0.8, 5.2, 45.5, 37.8, 10.7, '0.115022,0.088517,-0.935184,0.431796,0.060272,-0.072144,0.572424,-0.056336,-0.579701,-0.400236,0.181482,0.694032,-0.582285,0.100725,-0.022535,-0.226043,-0.132269,-0.721422,-0.254258,-0.219977,-0.555538,-0.614183,-0.136277,0.019366,0.115042,-0.450899,0.341915,0.075179,-0.259737,0.370333,0.261055,0.258515,-0.130216,0.539363,-0.232754,-0.108988,-0.110264,0.560623,-0.128632,-0.222445,0.277480,0.193822,-0.127767,0.325142,0.086355,0.309065,0.446057,-0.646187,-0.688394,0.073522,0.226489,-0.021188,-0.206755,-0.139990,0.039615,0.069039,0.192485,0.152328,-0.287654,0.066026,0.055498,-0.012549,-0.685886,0.203434,-0.026327,0.300875,-0.241320,0.247060,0.118448,-0.348316,0.120856,-0.367737,0.376163,0.355121,0.251911,0.545954,-0.205194,0.107549,-0.735387,-0.220970,0.592003,0.175329,-0.352070,0.601081,-0.359558,-0.369651,-0.401135,0.123017,-0.260262,0.250144,0.066535,0.063360,-0.290403,0.296924,-0.262465,0.120888,-0.117188,0.005873,-0.051361,-0.291234,-0.219736,-0.280867,0.018448,-0.319471,-0.348902,0.215988,-0.097470,-0.423747,0.665199,-1.026046,0.286582,0.173591,0.219046,-0.675511,0.343817,0.222994,-0.238599,-0.274888,-0.429773,0.168225,-0.091501,-0.140424,0.286301,0.225949,-0.131676,-0.088978,-0.500539,0.503169', '1297052', '1301022', '35073886', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308498', '暖', '剧情', '住在偏远山村的少女暖（李佳 饰）水灵俏皮，清纯美丽，是青年男子们倾慕的对象，这点对于和暖青梅竹马的林井和（郭晓东 饰）来说更不例外。外面的世界五彩缤纷，暖一心等待偶然驻留于此的戏班英俊武生带她离开这个山村，然而等待她的只有失望。在和井河荡秋千的时候，暖摔伤了腿，不久后井河也离开家乡，两人从此失去联系。10年后，井河从北京回到家乡，见到了阔别已久的暖。此时的暖跛着腿，形容枯槁，已经嫁给村中的哑巴（香川照之 饰）。一种别样的情感袭上心头……根据莫言小说《白狗秋千架》改编，并荣获第16届东京国际电影节金麒麟大奖、最佳男演员奖和第23届中国电影金鸡奖最佳故事片奖、最佳编剧奖。©豆瓣', '郭晓东', '霍建起', 8, 19000, 'tt0390311', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2405091384.jpg', 0.4, 1.5, 22, 50.9, 25.1, '0.107179,-0.001185,-0.711317,0.529936,0.088739,-0.110323,0.539722,0.203451,-0.502825,0.096488,0.101063,0.799671,-0.211397,0.307124,0.222258,0.075057,-0.132167,-0.585552,-0.235529,-0.373713,0.058869,-0.065000,-0.310602,0.542688,-0.197134,-0.264049,0.727114,0.080834,0.044402,0.928036,0.484556,0.042221,-0.136763,0.307281,-0.331865,-0.063611,0.002801,0.139357,-0.320018,0.490098,0.034246,0.016561,-0.147572,-0.083600,-0.042952,0.089126,0.618214,-0.247137,-0.233719,-0.142599,0.355817,0.022889,-0.233495,-0.004468,0.213909,-0.109007,0.300075,-0.027719,-0.123981,0.327842,0.083445,-0.104599,-0.286207,0.177172,0.365582,0.249275,-0.497622,0.474138,0.007410,0.068659,0.165116,-0.090834,0.248976,0.172298,0.135802,0.343896,-0.071530,0.329150,-0.259059,0.333739,0.260055,0.250382,-0.308905,0.482685,-0.226944,-0.427475,0.269122,0.107730,-0.445959,0.085522,0.326339,0.133125,-0.099803,-0.230676,-0.404008,0.223203,0.209279,-0.109863,0.282437,-0.341888,-0.085493,-0.492236,-0.144480,-0.337149,-0.199897,-0.030077,0.168903,-0.303019,0.648412,-0.666452,0.613682,0.301182,0.037902,-0.154376,0.617202,0.070058,0.058281,-0.210179,-0.146668,0.588630,-0.418227,0.403034,-0.241848,0.370331,-0.658584,-0.040715,-0.530811,0.363237', '25723081', '26365262', '1780122', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308499', '女高怪谈3：狐狸阶梯', '剧情', '某女子高中内，流传着一则恐怖灵异的传说：在通往宿舍的路上有一条狐狸阶梯，共28级，当你走到顶端发现有29级台阶时，狐仙便会出现，并实现你心中的愿望。珍胜（宋智孝 饰）和晓熙（朴寒星 饰）是一对同窗好友。晓熙家境良好，学习优异，为人和善。相比之下，虽然珍胜也很优秀，但似乎总是处于晓熙的阴影之下。随着时间的推移，她们的友情开始变质，珍胜愈加嫉妒这个近乎完美的朋友。某天，老师通知一个国际芭蕾舞大赛即将举行，同在芭蕾舞班的珍胜和晓熙都成为了参赛候选人。自知实力稍弱的珍胜不愿看到晓熙一路风光，她决定借助狐仙之手争取参赛的机会，却不曾想……©豆瓣', '宋智孝', '尹载然', 6.7, 30466, 'tt0370082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1059523651.jpg', 1.3, 9.4, 52.6, 28, 8.7, '0.103744,0.048228,-0.602545,0.753543,0.061245,-0.039724,0.418044,0.111135,-0.293496,-0.287069,0.244357,0.519180,-0.221372,0.395754,0.471353,-0.374166,-0.066551,-0.482824,0.013043,-0.499980,-0.355867,-0.227981,-0.402879,0.076307,-0.214345,-0.301067,0.864515,0.261528,-0.287868,0.592927,0.229783,0.074473,0.013740,0.200575,-0.362810,-0.409280,0.134798,0.127478,-0.063574,0.123438,-0.061448,0.005650,0.036913,-0.091482,0.062075,0.143537,0.454849,-0.191326,-0.214879,0.086772,0.455997,-0.133928,-0.044057,-0.007667,0.514896,0.017197,0.148595,0.192471,-0.013988,0.157330,-0.086488,-0.269208,-0.777304,0.297603,0.172746,0.048542,-0.353541,0.397624,0.206217,-0.209553,0.244382,-0.165812,0.066952,0.166120,0.087046,0.122298,-0.239813,0.168011,-0.396147,0.177585,0.591137,0.203226,-0.310278,0.250715,-0.009739,-0.522225,0.105697,-0.202125,-0.179290,0.070294,0.123755,0.260934,0.079034,0.018114,-0.451604,0.080535,-0.036977,-0.064622,0.041390,-0.413660,-0.005007,-0.506875,-0.108109,-0.220416,-0.289395,0.242628,-0.114068,-0.541700,0.980169,-1.008708,0.251376,0.372399,0.428908,-0.461823,1.005661,0.197000,0.071650,-0.207888,-0.320477,0.127297,-0.186081,0.212250,-0.334588,0.293558,-0.119939,-0.265453,-0.469322,0.581554', '25880986', '35262731', '27602116', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308504', '淘气少女求爱记', '剧情', '孔姬智（张娜拉 饰）是一个活泼开朗，充满古怪招数的女生，自从看到旅行社高层金贤俊（朴正哲 饰）后，芳心暗许，认定了他就是自己的白马王子，展开了离奇古怪的求爱大攻势！姬智潜入金贤俊的酒店，偷走他的笔记本，并因此闹出了一场场笑话。还未夺得美男欢心，她决定不达目的誓不罢休，古灵精怪的求爱招数层出不穷。就像是金贤俊的影子，无论他在哪里，姬智都会随时出现，让金贤俊头痛之余，也认识到姬智善良可爱的一面，金贤俊情不自禁对这个主动得过分的女生隐隐心动。然而，姬智的求爱计划就这么轻而易举的成功了吗？要抱得美男归，恐怕还要有点曲折和考验呢。©豆瓣', '张娜拉', '尹学烈', 6.4, 7393, 'tt0357978', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171164889.jpg', 2.1, 12.3, 56.4, 23, 6.2, '0.109535,-0.049019,-0.812050,0.586176,-0.312371,-0.022885,0.516773,-0.106410,-0.361967,0.100714,0.191852,0.512361,-0.475973,0.209828,0.252887,0.112186,-0.016669,-0.698245,-0.177543,-0.056086,-0.134954,-0.331285,-0.294853,-0.160215,0.077434,-0.317928,0.196787,0.200716,-0.363807,0.253428,0.618958,0.066968,0.008512,0.641302,-0.249748,-0.070798,-0.134545,0.319026,0.174577,0.002573,0.107481,-0.252976,-0.297341,0.420435,-0.238228,0.398669,0.400870,-0.201237,-0.359521,0.102912,0.375960,-0.314395,-0.100548,0.240230,0.205438,-0.218233,0.249741,-0.308826,-0.294431,0.048028,0.296009,0.028470,-0.811752,0.181800,0.179333,-0.146000,-0.492594,0.091836,-0.095131,0.038454,0.224811,-0.376860,-0.075846,0.203862,0.197817,0.336086,-0.046277,0.091919,-0.577317,0.142965,0.582440,0.133670,-0.153988,0.584334,-0.047058,-0.502806,-0.076584,-0.388183,-0.400241,0.137526,0.449815,-0.029153,-0.103911,0.041474,-0.404221,-0.104871,-0.237012,0.104240,0.013659,-0.562860,-0.073824,-0.242780,-0.189216,-0.285142,-0.241980,0.357206,0.012956,-0.238881,0.758268,-0.918894,0.212425,0.538916,-0.013205,-0.756090,0.501644,0.376587,-0.436149,0.079089,-0.269629,0.008178,-0.099472,0.105563,-0.019845,0.519167,0.148987,-0.482785,-0.329607,0.456965', '1877596', '1301022', '1299649', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308520', '恋上你的床', '喜剧', '屈小乔（郑秀文 饰）是一名杂志记者，每次遇男友分手，都要拿回自己的床褥。杂志总编安排她跟进警方代言人高志强（古天乐饰）性无能的消息。其实志强在一次追踪犯人的时候，产生了阴影因此不举。小乔多次试探仍无进展却爱上了志强，得知志强的过去后，小乔认为他们的爱情不一定需要性来维持。但小乔却找到自己的前男友Raymond( 刘青云 饰)解决自己的生理需要。Raymond在法院邂逅只得18岁的阿塔（蔡卓妍饰），因Raymond认为阿塔只是个小女孩，故也不能从小女友身上得到需要。 高志强性无能的事被揭发，志强认为是小乔告诉了自己的老板，只好分手。二人复合后，高志强重遇了当年令他产生阴影的匪徒，一枪声响，阴影尽消。©豆瓣', '郑秀文', '陈庆嘉', 5.9, 41550, 'tt0379871', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p486541740.jpg', 3, 20.1, 60.9, 12.5, 3.5, '0.478110,-0.198562,-0.631303,0.237517,-0.280677,-0.333784,0.565607,0.190365,-0.428424,-0.286732,0.482460,0.539674,-0.004798,0.071050,-0.099778,0.183822,-0.286190,-0.670245,0.320451,-0.123103,-0.148654,-0.429240,-0.087246,0.127962,-0.185460,-0.187969,0.469700,-0.255889,-0.154917,0.396849,0.207797,0.220048,0.235708,0.577745,0.123713,0.129514,0.004816,-0.026800,-0.353886,0.295526,0.338668,-0.223475,-0.120111,0.192410,-0.111877,0.423678,0.536549,-0.043947,-0.249486,0.091877,0.438416,-0.319008,0.085968,0.065674,0.177081,0.042551,0.360811,0.338413,-0.395649,-0.056593,0.139881,0.326703,-0.560846,0.069552,0.108567,0.274263,-0.455430,0.409174,-0.435474,-0.073468,0.164112,-0.535614,0.097963,0.161620,0.273362,0.185882,-0.294691,0.011894,-0.491384,0.120365,0.609672,-0.022232,-0.028621,0.373603,-0.117505,-0.071865,-0.011865,0.079666,-0.490148,0.225448,0.133491,0.013636,-0.377728,0.000966,-0.280941,-0.171454,-0.450998,0.149497,0.035404,-0.333779,-0.328419,-0.131277,-0.260540,-0.125992,-0.313281,-0.268668,0.184762,-0.195680,0.429242,-0.853395,0.139705,0.480971,0.201404,-0.518719,0.573151,0.384509,-0.057011,-0.344634,0.150779,-0.169315,-0.069462,0.247765,0.127067,0.149108,0.322758,-0.407596,-0.255224,0.057377', '1301022', '1308755', '35030151', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308523', '月光游侠', '剧情', '1999年12月31日，全世界的人都欢欣鼓舞地等待迎接新世纪。受到诅咒拥有不死身的留嘉（丰川悦司 饰）以和阿敬（HYD E饰）正被警察追缉。虚弱的留嘉希望结束自己的生命，两人来到海边，唱着歌的留嘉在朝日的阳光下化成火焰。2014年，经济萧条日本瓦解，许多人移民海外。在马勒巴，八岁的阿翔与哥哥信士和好友阿彦靠偷窃度日。一天，意外遇见了昏倒的阿敬。2025年。19岁的阿翔（Gackt 饰）、阿敬和阿彦（山本太郎 饰）打算偷袭地方帮会“义心会”遇上对帮会心怀怨恨的阿孙（王力宏 饰）变成好友。阿孙为了替受到凌虐的妹妹怡洁（郭善璵 饰）报仇。阿翔对从小就得了失语症但仍在公园画壁画的怡洁一见钟情，但她喜欢上了阿敬。但在怡洁完成壁画的那一天，“义心会”的杀手们来报复了……©豆瓣', '宝井秀人', '濑濑敬久', 7.1, 5678, 'tt0365514', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2605222642.jpg', 2.7, 9.2, 38.4, 31.1, 18.5, '0.111099,-0.113576,-0.457209,0.173149,0.071853,-0.176859,0.484733,0.110262,-0.467696,-0.075191,0.203630,0.482722,-0.264085,0.413735,0.376685,-0.039416,-0.235554,-0.700182,-0.000870,-0.050101,-0.253354,-0.234076,-0.081204,-0.351679,-0.113624,-0.477058,0.495553,0.320147,0.160585,0.626049,0.123949,0.221126,0.126425,0.289447,-0.206490,-0.026492,-0.168053,0.076758,-0.097592,0.248079,-0.186265,-0.389089,-0.101459,-0.016422,-0.111918,0.232881,0.748959,-0.112420,-0.134827,-0.233146,0.268037,-0.412725,-0.019414,0.117359,0.360478,-0.040845,0.074966,0.261159,-0.179306,-0.197699,0.063682,-0.288656,-0.385875,0.116836,0.263482,0.071620,-0.506938,0.646521,-0.048212,0.124823,0.047280,-0.376562,0.160925,0.316803,0.197896,0.527121,-0.333556,0.115335,-0.570249,0.131788,0.589238,-0.146439,-0.044865,0.108242,-0.082605,-0.283484,-0.129900,-0.274903,-0.295912,0.013712,0.122330,-0.054825,-0.261710,0.038272,-0.758729,-0.092794,-0.129288,-0.161476,0.068085,-0.380678,-0.159101,-0.506663,-0.055868,-0.390989,-0.203586,0.328375,0.192332,-0.204924,0.720419,-0.758606,0.502354,0.351842,0.368400,-0.387889,0.662908,0.053664,-0.272482,-0.081156,-0.172836,0.289139,-0.051957,0.118536,0.134522,0.097535,-0.075896,0.045188,-0.294909,0.154558', '1826173', '3811356', '3041753', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308524', '海岸线', '剧情', '韩朝对峙时期，海岸线旁的两国军事状况高度紧张。姜汉泽（张东健）是韩国海岸警备队尽职尽责的上等兵，他的职责是负责看守海岸线，以防可疑人士潜入。由于一心一意想抓间谍，他在工作时一丝不苟很是认真。某次，他将发现的可疑目标当场击毙，事后才知受害者不过是醉酒后与女友亲热的平民。自此，姜汉泽和受害者的女友美英（朴智娥）的生活进入绝境，两人心灵上都背上无法承受的重压，而此事件更影响到整个海岸警备队，尤其是该队成员金上士（金泰宇）。©豆瓣', '张东健', '金基德', 7.3, 9887, 'tt0341384', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1788658280.jpg', 0.8, 4.8, 37.1, 43.1, 14.2, '0.197603,-0.232024,-0.746162,0.517993,0.122205,0.166383,0.558347,0.045224,-0.762906,-0.143954,0.339986,0.506841,-0.025836,0.017025,0.333868,0.088859,-0.400720,-0.799590,-0.209470,-0.111829,-0.473617,-0.476193,-0.296596,-0.228881,-0.334032,-0.347868,0.573011,-0.079470,-0.445387,0.319755,0.181058,0.496852,-0.256455,0.540567,-0.050017,-0.330989,0.093734,-0.331231,-0.200172,-0.074405,-0.220999,-0.385980,-0.075621,0.332747,0.139241,0.582597,0.822708,-0.149500,-0.383917,-0.100862,0.210861,-0.465137,-0.051622,0.157701,0.747996,-0.015081,0.218920,0.114636,-0.084733,-0.023664,0.018608,-0.052819,-0.403498,-0.180956,0.196458,0.198734,-0.367377,0.515215,-0.076899,-0.004001,0.241922,-0.165100,0.209163,0.553566,0.040103,0.161427,-0.002683,0.038732,-0.230749,-0.001368,0.712402,0.114446,-0.139498,0.119653,-0.114837,-0.513679,-0.122440,-0.303228,-0.259386,-0.074447,0.035546,0.024860,0.015202,0.144412,-0.387202,0.126107,-0.318321,-0.154473,-0.279336,-0.231713,-0.020640,-0.504144,-0.027567,-0.472286,-0.311538,0.103658,-0.121962,-0.172591,0.525981,-0.698346,-0.051728,0.604301,0.265641,-0.424723,0.562557,0.290746,0.180070,-0.227393,-0.051695,0.103354,0.222434,0.356581,0.020125,0.198127,-0.290711,-0.075542,-0.099608,0.171358', '26418093', '1301022', '25870679', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308543', '爱的捆绑', '剧情', '作家由纪夫（丰川悦司）由于整日忙于写作，与妻子萌宝（山口智子）渐渐生出一层隔膜，而两人原本平淡简单恩爱的生活，也因为这层隔膜于不知不觉间被打破，只是由纪夫从没察觉到。某天，由纪夫诧异地发现家里的很多东西都被萌宝用绳子捆绑了起来，甚至，她经常企图把自己也绑在绳中。意识到问题的严重性后，由纪夫带萌宝去看医生，得知她患上的是一种无法进行医学治疗的学名为“强迫性紧缚症候群”的精神病——似乎他可以做的，只有按萌宝的要求，用用绳索将她紧紧捆绑起来。©豆瓣', '丰川悦司', '岩井俊二', 7.4, 25244, 'tt0111555', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2457805700.jpg', 0.8, 4.8, 37.2, 39.4, 17.8, '0.435218,-0.021039,-0.614741,0.498893,-0.143175,-0.058942,0.825504,-0.034027,-0.550354,-0.321507,-0.034363,0.604609,-0.237253,0.267117,0.144364,0.048442,-0.143922,-0.949801,0.141283,-0.027528,-0.529789,-0.535176,-0.301190,-0.217297,-0.386550,-0.488946,0.500250,0.008877,-0.107270,0.209001,0.204710,0.382027,-0.014143,0.620891,-0.049337,-0.071511,-0.093984,-0.238736,-0.007658,-0.053201,0.203125,-0.283305,0.120373,0.437166,-0.081060,0.353269,0.786408,-0.307324,-0.165547,0.224979,0.264547,-0.199617,-0.183385,0.233287,0.194271,0.421642,0.158632,0.325660,-0.371428,0.010433,0.356512,0.077403,-0.571305,0.097288,-0.075314,0.420015,-0.293718,0.288498,0.053873,-0.134334,-0.277294,-0.689500,0.186821,0.248495,0.210414,0.471106,-0.490850,-0.042159,-0.335271,0.174311,0.532117,0.096316,-0.174511,0.462244,-0.414720,-0.163747,-0.023465,-0.062182,-0.129647,-0.393569,0.257352,0.424038,-0.691250,0.173289,-0.400412,-0.128964,-0.042726,-0.196650,-0.030099,-0.585042,-0.004463,-0.229371,-0.211379,-0.441961,-0.248249,0.051375,0.208329,-0.438591,0.417904,-0.789325,0.255368,0.382172,0.257079,-0.077253,0.464246,-0.076014,-0.034288,0.065099,-0.205114,0.054744,0.011321,0.542846,0.552600,0.501067,-0.055645,0.186393,-0.393119,0.583944', '1937946', '21348112', '2027925', '1417304');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308554', '咒怨2', '恐怖', '女演员原濑京子（酒井法子饰）和她的未婚夫石仓将志在回家的路上发生了一起车祸。自此，将志失去了意识陷入了昏迷，京子也不幸流产。但是过不久，京子仍然感觉不适，于是再去检查，竟然被告知腹中的孩子仍然正常存在！在电视台担任报道员的三浦朋香(新山千春饰)，每天晚上总是在自己的公寓里听到奇怪令人害怕的声音，于是她把男友山下典孝(堀江庆饰)叫来寻找原因。剧组的拍摄依然在继续，但是奇怪的事情接二连三的发生,剧组人员的先后失踪或是时常让大家惶惶不安……©豆瓣', '酒井法子', '清水崇', 7.5, 52836, 'tt0367913', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2410260419.jpg', 1, 4.3, 34, 39.9, 20.7, '0.289702,0.057978,-0.715516,0.036078,0.172062,-0.028617,0.567363,0.148284,-0.821524,-0.567349,0.044723,0.698280,-0.426639,0.330678,0.182160,0.060171,-0.350477,-0.689560,-0.019906,0.026769,-0.401757,-0.292434,0.170292,-0.159812,-0.056211,-0.352168,0.416986,0.116573,-0.170136,0.604780,0.202071,0.235883,-0.256431,0.991853,0.218515,0.279276,0.189877,0.115346,0.152982,0.153564,0.407476,-0.516060,-0.078537,0.254251,0.367481,0.431702,0.671311,0.017467,-0.536470,0.270983,0.486410,-0.025703,-0.037315,0.254957,0.503066,0.239173,0.210995,0.239769,-0.479809,0.042488,0.116114,0.273907,-0.527588,0.232844,0.190366,0.252735,-0.473201,0.291031,-0.072628,0.068678,0.358018,-0.196197,0.601496,0.558971,0.318748,0.423606,-0.292501,0.060398,-0.237864,0.053451,0.871929,-0.223988,-0.156465,0.308800,0.095218,-0.362732,-0.128714,-0.028854,-0.296514,0.348755,-0.081603,0.321982,-0.613932,-0.051088,-0.352634,-0.115526,-0.107352,-0.371842,-0.208512,-0.212003,-0.105855,-0.562428,0.236772,-0.110127,-0.317866,-0.102969,-0.139198,-0.033223,0.504442,-0.769744,0.446403,0.724411,0.259217,-0.483758,0.605209,0.061105,0.114463,-0.118764,0.071422,0.254792,0.042263,0.411842,0.362205,0.215556,-0.292968,-0.106030,-0.438962,0.027400', '1292064', '1877016', '25870679', '1293142');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308567', '失乐园', '剧情', '久木祥一郎（役所广司饰）是一家出版社的高级编辑，妻子久木文枝（星野知子饰）做设计陶制品，已成年的女儿在医院工作，很少回家。祥一朗感到家庭生活乏味，夫妻间总是客客气气。祥一郎有个情人，业余书法教师松原凛子（黑木瞳饰）。凛子气质高雅，是个聪慧女子。可惜嫁了个毫无情趣的医生丈夫松原晴彦。他冷冰冰的，导致二人婚姻空虚。一次他坚决地告诉凛子决不会和她离婚，他掌握有妻子偷情的证据，并揭发了事情。另一边文枝却默默承受，最终也只能离婚。冬季到来，祥一郎和凛子怎么才能永远的和对方长相厮守呢？©豆瓣', '役所广司', '森田芳光', 7.4, 36164, 'tt0120120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2157654546.jpg', 0.7, 3.4, 35.6, 44.1, 16.1, '0.068623,-0.250761,-0.315090,0.341662,-0.291263,-0.399415,0.505976,0.167172,-0.380314,-0.608101,0.098195,0.621439,-0.007722,0.365757,0.054791,0.120909,-0.045885,-0.546147,0.291457,0.134512,0.049871,-0.415870,0.179257,-0.243216,-0.166556,0.147406,0.678208,-0.132306,-0.080544,0.255338,0.220618,0.178608,-0.097004,0.274569,0.048318,-0.062498,0.139779,0.290161,-0.377842,0.078534,0.044733,-0.064181,-0.130487,0.036986,0.210354,0.300985,0.378804,0.145602,-0.345231,0.004165,0.370850,-0.093068,-0.209817,0.267608,0.235090,-0.215608,0.033401,0.348033,-0.375175,-0.191939,0.136399,-0.005883,-0.470849,-0.083318,0.190303,-0.053050,-0.255991,0.442639,-0.145236,-0.044130,0.208142,-0.485742,0.056924,0.181255,0.265219,0.401094,-0.266049,0.256257,-0.374810,0.253896,0.563743,0.341677,-0.071004,0.300025,-0.518054,-0.388913,0.022855,-0.428662,-0.757499,0.100576,-0.322480,0.110036,-0.315989,0.031109,-0.087279,-0.112129,-0.078223,0.127088,0.238718,-0.460495,0.219599,-0.262957,0.045723,-0.494067,-0.617430,0.104583,0.140211,-0.386220,0.679768,-0.621848,0.007876,0.462115,0.336212,-0.632034,0.676765,0.471638,0.032080,-0.251896,0.181006,0.244886,-0.098323,0.025844,0.143171,0.107742,0.184652,-0.090323,-0.090234,0.300533', '3445516', '1858876', '1292720', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308570', '蜘蛛侠2', '动作', '大战绿妖之后，蜘蛛侠帕克（托比•马奎尔 Tobey Maguire 饰）忍痛拒绝了他唯一的挚爱玛丽（克尔斯滕•邓斯特 Kirsten Dunst 饰），因为蜘蛛侠的身份会为自己和亲人带来巨大危险，帕克决定独立承担起蜘蛛侠的责任。帕克一直在忙于应付各种挑战：学习超能力的灵活运用；在超级英雄与平凡大学生的双重身份下隐藏自我、小心翼翼地生活等等。帕克对玛丽越来越难以自拔，但是作为蜘蛛侠又不能对玛丽展开心扉。好友哈利因为误会蜘蛛侠而一直处处与其为作对；唯一的亲人婶婶也对蜘蛛侠的真实身份产生了怀疑。同时，新的挑战又出现了：邪恶而强大的章鱼博士。帕克在种种压力下肩负起蜘蛛侠的使命。©豆瓣', '托比·马奎尔', '山姆·雷米', 7.8, 262753, 'tt0316654', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1617867110.jpg', 0.2, 1.7, 29.4, 46.8, 21.9, '0.030500,-0.023613,-0.480729,0.694220,-0.106037,-0.285137,0.792512,0.191328,-0.485420,-0.453732,0.275552,0.925817,0.078642,0.032193,0.163190,-0.230297,-0.237310,-0.655953,0.047474,0.132413,-0.282693,-0.503030,-0.387522,-0.484933,-0.146687,-0.407280,0.547496,-0.059203,-0.361284,0.208058,0.451898,0.558894,-0.038233,0.447334,0.035654,-0.009893,-0.043395,0.046653,-0.470971,0.174326,0.270317,0.036866,0.019266,0.485615,-0.071740,0.041810,0.563769,-0.622843,-0.248327,-0.285492,0.333981,-0.337853,0.122896,0.139491,0.155420,-0.150854,-0.014899,0.048406,0.046597,0.077918,0.145775,0.006785,-0.947471,-0.059635,0.024948,0.240622,-0.592424,0.216012,-0.275365,-0.046863,0.374696,-0.247920,-0.198457,0.208774,0.369102,0.306003,-0.361819,0.184429,-0.175606,-0.035104,0.528600,0.039268,-0.244706,0.061990,-0.419598,-0.180236,-0.090668,-0.262914,-0.582347,-0.263551,0.109254,0.331524,-0.005458,0.496792,-0.648849,-0.089046,-0.144998,-0.046917,-0.041412,-0.613347,0.102324,-0.488539,-0.193615,-0.281890,-0.173187,-0.163622,0.038164,-0.546847,0.632596,-1.018261,0.309026,0.564656,0.247525,-0.545210,0.379647,0.151490,0.202000,-0.374316,-0.218723,0.423272,0.013758,0.174818,0.068924,0.121326,0.285677,0.045321,-0.063357,0.607704', '3769423', '30345227', '1793491', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308573', '卡拉是条狗', '剧情', '卡拉虽说是一条杂种狗，老二（葛优 饰）却十分爱惜它，在老二心中，为了生活他处处要讨人欢喜，只有卡拉才会想办法讨他高兴。但是老二的运气却糟糕透顶——他妻子玉兰遛狗的时候，警察因为卡拉无证，把它抓走。要换回卡拉，必须要掏5000块钱办一个养狗证件。对于卡拉一家，5000块钱需要省吃俭用才能存下，老二决定先跑跑关系。儿子亮亮找来了同学帮忙，因为他的老爸有点手腕。然而人家却不肯帮这个忙。老二急中生智，想起卡拉是老同事杨丽的狗下的崽。他找来杨丽的狗证，却被警察识破。老二和杨丽费劲周章，各种办法都要不回卡拉，还被玉兰误会二人相好。更糟糕的是，儿子亮亮又犯了事被拉进警察局，一家三口和卡拉竟然以这种方式在警察局相遇……©豆瓣', '葛优', '路学长', 7.4, 56854, 'tt0366655', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2378852609.jpg', 0.3, 2.7, 36.5, 47.1, 13.4, '0.247647,-0.296668,-0.358823,0.193251,-0.414555,-0.472588,0.503269,0.050333,-0.671188,-0.098363,0.107250,0.476733,0.020045,0.149494,0.094516,0.369790,-0.255366,-0.269810,0.420557,0.073033,0.106446,-0.335287,-0.207516,0.084376,-0.056441,0.253867,-0.095592,-0.418971,0.070924,0.112186,0.214151,0.278726,0.065116,0.310198,-0.104915,0.107840,-0.216318,-0.172296,-0.052649,0.147939,0.440377,0.085410,-0.173588,0.225999,0.382516,0.418491,0.166042,0.189288,-0.065387,0.026930,0.036110,-0.149736,-0.130322,0.297682,0.088694,-0.393008,0.497165,0.061406,-0.310024,-0.010021,0.263156,0.006703,-0.890175,0.457919,0.008108,0.053483,-0.775780,0.140568,-0.285242,-0.054908,0.187475,-0.557193,0.268860,0.453920,0.141698,0.479038,-0.342840,-0.140961,-0.568836,-0.082186,0.653656,-0.212898,0.393366,0.218992,-0.050304,-0.156959,0.382470,-0.181902,-0.461299,0.014602,0.332212,-0.005372,-0.411259,-0.213197,-0.431608,-0.184889,-0.207254,-0.184634,0.080376,-0.332338,0.067757,0.157461,0.041535,-0.321118,-0.300666,0.124823,0.220867,-0.164160,0.381149,-0.641045,-0.110500,0.649479,0.445827,-0.518062,0.458878,0.235193,-0.025735,-0.234689,0.007653,-0.460791,0.109953,0.463974,0.428772,0.204324,0.405670,-0.651405,0.014327,0.274551', '1877596', '1793491', '1299649', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308575', '蓝色大门', '剧情', '高中生孟克柔（桂纶镁 饰）与林月珍（梁淑慧饰）是无话不谈的好友，月珍告诉克柔，说自己喜欢上了一个叫张士豪（陈柏霖 饰）的男生，便常常要求克柔帮她接近张士豪，帮忙认识他、帮忙传递情书。没想到张士豪以为喜欢自己的是孟克柔，所以也常常借故接近她，跟她在一起。传递情书的事，被张贴出来，原来林月珍是以孟克柔的名义给张士豪写信，孟克柔非常生气而从而跟林月珍的关系疏远了。另一边厢孟克柔极不愿意承认她与张士豪之间是恋人的关系，可是张士豪已深深喜欢上她。孟克柔想跟男生接吻，因为她想清楚一件事，原来她心里，喜欢的是另外一个人。©豆瓣', '陈柏霖', '易智言', 8.4, 400517, 'tt0333764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2562341754.jpg', 0.2, 1.1, 16.1, 44.9, 37.6, '0.678761,-0.184136,-0.607890,0.909466,-0.289316,-0.020278,0.569615,-0.049955,-0.596841,-0.256727,-0.291598,0.861785,-0.035755,0.207614,0.055018,0.338576,-0.113343,-0.786905,0.210711,-0.237641,-0.189759,-0.695111,-0.003668,0.021059,-0.176279,-0.194333,0.146597,-0.159110,-0.437078,0.600392,0.522432,0.286272,-0.038215,0.549745,0.010057,-0.238013,-0.318118,0.303548,-0.156484,0.023525,0.077947,-0.114083,0.001777,0.224156,0.080641,0.423483,0.116604,0.068929,-0.257044,0.210391,0.243309,-0.280244,0.133610,0.229343,0.149083,0.145290,0.617939,0.061695,-0.274562,-0.098819,0.141648,0.092825,-0.641386,0.282103,0.168338,-0.013247,-0.665386,0.488403,-0.288912,-0.276926,0.352795,-0.448996,0.348613,0.270171,0.147449,0.216524,-0.181251,-0.066795,-0.512413,-0.051738,0.880169,0.209483,0.246903,0.415428,-0.206051,-0.203866,-0.084240,-0.080016,-0.402756,0.280097,-0.262157,0.018057,-0.167598,-0.170488,-0.343313,-0.075483,0.065868,0.167362,0.081968,-0.681664,0.071197,0.117721,-0.394252,-0.542255,-0.347207,-0.044297,-0.057248,-0.556558,0.680785,-0.895088,0.244788,0.622006,0.664195,-0.882943,0.960332,0.677283,-0.345010,-0.507185,0.049874,-0.407253,0.130680,-0.244287,0.257653,0.279949,0.401348,-0.329668,-0.437935,0.304194', '1418613', '1308805', '1456503', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308579', '简爱', '剧情', '父母早亡的简爱（苏珊娜·约克 Susannah York 饰）寄住在舅舅家，舅舅病逝后，她受尽舅妈的歧视和虐待，最终被送进孤儿院。教规严厉的孤儿院让简爱继续受到精神和肉体的摧残，为了离开这里，她登了广告去谋求家庭教师职位。桑菲尔德庄园聘用她作男主人罗切斯特先生（乔治·C·斯科特 George C. Scott 饰）女儿的家庭教师。罗切斯特先生长年在外，空旷的房子阴森悚然。当脾气怪异的罗切斯特先生回来后，他对待简爱的态度时好时坏，但很显然他被清新独特的简爱所吸引，简爱也在与他的多次接触中渐渐爱上了他。在一次盛大家庭宴会中，罗切斯特向她求婚，简爱答应了他。正在婚礼举行时，有人指出罗切斯特早已结婚，古堡顶楼小屋里的疯女人正是他的妻子。伤心失望的简爱离开了庄园，历尽磨难寻找新出路，最终在牧师约翰的帮助下找到了一个乡村教师的职业。当牧师约翰向简爱求婚时，她依然无法忘怀罗切斯特，便拒绝了约翰，立刻赶回桑菲尔德庄园，却发现庄园已被烧成废墟……', '乔治·C·斯科特', '德尔伯特·曼', 8.1, 5765, 'tt0065911', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1590432187.jpg', 0.4, 1.3, 20.3, 47.7, 30.4, '0.234483,0.209693,-0.568321,0.370873,-0.193906,-0.566122,0.807869,0.186525,-0.451496,-0.428984,0.107706,0.783509,-0.080731,0.560590,0.219135,0.289775,-0.266384,-0.395288,-0.190184,-0.017438,-0.109735,-0.407321,0.043498,-0.259548,0.054725,-0.296468,0.351438,0.059675,-0.155273,0.319444,0.172225,0.225728,0.022825,0.569850,-0.183324,0.139625,0.183818,-0.094265,-0.297106,0.206929,0.178709,-0.149725,-0.176039,0.190860,0.241485,0.349993,0.500212,-0.051590,-0.192487,-0.096043,0.402716,-0.102106,0.124814,0.341840,0.282300,-0.060513,0.217056,0.155860,-0.209747,-0.021010,-0.054418,-0.165958,-0.257686,0.196486,0.062087,-0.045327,-0.582859,0.512608,-0.096873,0.036743,0.027196,-0.451892,0.189105,-0.010001,0.052699,0.394850,-0.287325,0.278118,-0.219438,0.166073,0.648304,-0.003255,-0.080691,0.068632,-0.395559,-0.356054,0.343048,-0.084180,-0.649538,0.069980,0.425538,0.050278,-0.140433,0.083340,-0.436919,-0.480306,-0.399892,-0.216379,0.010233,-0.384070,-0.085741,-0.692664,-0.013684,-0.076668,-0.243972,-0.082128,-0.202020,-0.128871,0.286911,-0.718736,0.432773,0.382871,0.530016,-0.393779,0.651076,-0.098166,0.110470,0.053150,0.060332,0.437127,0.096864,0.399152,0.285429,0.267646,0.090493,-0.068012,-