INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308582', '爱是妥协', '喜剧', '年过半百的哈利·兰格（杰克·尼科尔森饰）是位事业有成的音乐制作人，非但毫无老态龙钟之态，反而神采奕奕、精力旺盛。更准确的说——性欲旺盛。哈利的女朋友各个都年轻貌美，他现任的女朋友玛琳（阿曼达·比蒂饰）更是火辣性感。一次旅行之后，哈利来到玛琳母亲艾丽卡（黛安娜·基顿饰）的海滨别墅。本来浪漫的度假，哈利却突发心脏病。而玛琳有事返回纽约，只能由母亲艾丽卡和医生（基努·里维斯饰）照顾。离婚多年的艾丽卡是纽约著名剧作家，独自一人抚养女儿长大。这位迷人知性的女性深深的吸引着哈利，他不得不承认已经不可自拔的爱上了女朋友的妈妈。正当哈利犹豫不决时，他才发觉梦中女神艾丽卡已经和年轻帅气的医生相爱了。到底谁才能赢得美人芳心，抱得美人归呢？女主角黛安·基顿因本片荣获第76届奥斯卡金像奖奥斯卡奖-最佳女主角提名等多项大奖。©豆瓣', '杰克·尼科尔森', '南希·迈耶斯', 7.5, 17340, 'tt0337741', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p849329178.jpg', 0.5, 3.1, 33.6, 46.3, 16.5, '-0.206553,-0.198379,-0.499582,0.408734,-0.174450,-0.541346,0.524974,0.108852,-0.353213,-0.166643,0.135923,0.802197,-0.334690,0.530382,0.411808,0.419855,-0.479993,-0.408464,-0.031044,0.108345,0.019041,-0.378152,-0.360441,0.098475,0.119252,-0.213451,0.403139,-0.377403,0.078525,0.442881,0.479458,0.106812,0.033425,0.189082,-0.086878,0.059462,0.429946,0.066077,-0.290511,0.241540,0.116970,-0.145175,-0.199751,0.079361,0.042946,0.248078,0.496296,-0.067690,-0.116777,0.080265,0.603800,-0.125958,0.020576,0.121201,0.048938,-0.274371,0.330249,0.111116,-0.038740,0.032602,0.081472,-0.147707,-0.344796,0.296337,0.047646,0.023120,-0.233812,0.303043,-0.205624,-0.028496,0.352201,-0.286585,0.071510,0.076360,-0.093788,0.251211,0.028594,0.254113,-0.250245,0.326010,0.317220,0.216904,-0.267961,0.252282,-0.403650,-0.524211,0.176750,-0.339550,-0.784187,0.244829,0.293809,0.082997,0.201623,0.074414,-0.163394,-0.236346,-0.422152,0.012598,-0.039226,-0.189219,-0.077175,-0.520656,-0.003467,-0.325914,-0.095994,-0.156360,0.034125,-0.275938,0.674280,-0.513016,0.262417,0.529876,0.081284,-0.415800,0.444361,0.233659,0.102611,-0.286668,-0.371116,0.658832,-0.238913,-0.072292,-0.095304,0.329602,0.018118,-0.109591,-0.421755,0.357088', '1292720', '4233625', '26856202', '2968813');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308585', '非常小特务3', '喜剧', '这一回，聪明勇敢的卡门（阿丽夏·潘娜维加 Alexa PenaVega 饰）遭遇到了前所未有的危机，她的精神被一位疯狂的玩具制造商（西尔维斯特·史泰龙 Sylvester Stallone 饰）困在了他一手制造的虚拟游戏世界中。为了救出卡门，朱尼（达里尔·沙巴拉 Daryl Sabara 饰）英勇的挺身而出，他加入了一个以攻略此游戏为目标而组建的游戏测试小组之中，这里汇聚了很多和他一样厉害的孩子们。进入了虚拟的世界，朱尼不仅要面对游戏中一个又一个古怪而又艰巨的关卡任务，更得时时留意幕后黑手玩具制造商所分裂出来的五种迥然不同的人格。最终，在祖父（里卡多·蒙特尔班 Ricardo Montalban 饰）和朋友们的帮助下，朱尼是否能够战胜强大的对手，救回卡门呢？©豆瓣', '达里尔·沙巴拉', '罗伯特·罗德里格兹', 6.2, 7379, 'tt0338459', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1282025421.jpg', 3.7, 16.8, 53, 17.7, 8.7, '0.160618,0.247600,-0.520471,0.667061,-0.391363,-0.139457,0.627307,0.000454,-0.350282,-0.104573,0.320809,0.933043,-0.140084,0.031621,0.215361,0.013821,-0.161389,-0.576462,-0.070881,-0.073726,-0.325755,-0.398801,-0.665364,-0.277451,-0.007986,-0.280453,0.598448,0.021754,-0.154779,0.304273,0.298986,0.511687,-0.154442,0.344210,-0.112812,-0.237630,0.180196,-0.103700,-0.011047,0.367762,-0.269246,0.117889,-0.124206,0.410721,-0.008191,0.254600,0.709216,-0.486291,0.008922,-0.256117,0.348335,-0.191869,-0.008607,-0.020125,0.152132,0.031659,0.041172,0.023204,-0.059232,0.223920,0.032760,-0.282679,-1.177504,-0.271554,0.239523,-0.064854,-0.513789,0.058991,-0.097675,-0.183713,0.063906,-0.047091,-0.051493,0.513279,0.439295,0.347959,-0.334838,-0.053932,-0.421166,0.141348,0.439225,-0.307481,-0.257074,0.203889,-0.122759,-0.390100,-0.177575,-0.427723,-0.411825,-0.052256,0.371023,0.122316,-0.039053,0.256773,-0.932152,0.085002,-0.320172,-0.112714,-0.232870,-0.389504,-0.001464,-0.575956,-0.030798,-0.005953,-0.194703,0.072525,0.044097,-0.289498,0.912345,-0.740305,0.151326,0.713561,0.155818,-0.403596,0.378134,0.301392,0.268360,-0.340648,-0.153699,0.116386,0.070430,0.249219,-0.018274,0.501185,-0.032278,-0.192021,-0.575541,0.628484', '25928048', '3769423', '1793491', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308587', '向左走·向右走', '爱情', '小提琴家刘智康（金城武）和翻译家蔡嘉仪（梁咏琪）的房间仅相隔一堵墙，然而由于总是在同一时刻同一地点一个向左一个向右走，他们从没遇见过。某天因为来到同一所公园，他们终于在一片水池的一端相遇，并且一见如故。一个快乐又甜蜜的下午很快过去，快黄昏时突降倾盆大雨，两人于匆忙分手时交换了电话号码，不料到家后发现写有号码的纸片已被雨水打湿成模糊一团。为了让刘智康和蔡嘉仪今生都不能再见面，分别暗恋他们的小红和胡医生想出诡计，加上两人相遇的公园正在清拆，他们开始相信彼此之间真的没有缘分。©豆瓣', '金城武', '杜琪峰', 6.9, 112245, 'tt0367174', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486572158.jpg', 0.7, 6, 49.5, 33.3, 10.6, '0.522440,0.042763,-0.929306,0.617709,0.327262,-0.509332,1.020958,0.038268,-0.031539,-0.461198,0.071302,0.623524,-0.618182,0.279889,0.282681,-0.371339,-0.158710,-0.822455,-0.084537,-0.350903,-0.832520,-0.461014,-0.093394,0.149945,0.008251,0.137268,0.394000,0.249371,0.098746,0.537517,0.190472,-0.147324,-0.535988,0.501572,-0.363640,-0.047584,-0.052214,0.413711,-0.504893,0.155514,0.011378,0.129681,-0.163145,-0.142689,-0.252486,0.412139,0.675690,-0.152994,-0.333288,0.280994,0.312218,0.022550,0.091193,-0.014065,0.587806,-0.015138,0.418082,-0.204527,-0.174920,-0.012393,-0.088330,0.029249,-0.371122,0.422286,-0.020051,0.115465,-0.241824,0.574291,0.092573,-0.207344,0.201480,-0.592189,0.260221,0.400567,0.420149,0.556495,-0.297120,-0.071494,-0.609922,-0.201146,0.904014,0.148689,-0.092247,0.672547,0.037581,-0.135083,0.079963,0.174065,-0.211768,0.193311,0.326836,0.081722,-0.206389,-0.071231,-0.623269,0.004298,-0.072832,-0.036927,0.292969,-0.406133,-0.196565,-0.229614,-0.196660,-0.189316,-0.403117,0.575511,-0.193606,-0.140234,0.513589,-0.780686,0.338076,0.278028,0.039047,-0.157215,0.809163,0.376086,-0.128433,-0.156661,0.217751,0.238982,0.246426,0.582932,0.422559,0.428865,-0.197931,0.187568,-0.567520,0.209981', '1296534', '1292211', '26687241', '26715845');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308590', '玉女添丁', '喜剧', '方丽娟（杨千嬅 饰）在一家广告公司任职，她一直受到上司Monica的歧视。Monica只想寻找机会把方丽娟解雇。公司老板的儿子胡启明（陈冠希 饰）从外国回来接手爸爸的生意，但他的兴趣是在制作甜点，所以他每天下班都会去学做蛋糕，回到家就要欺骗爸爸自己去了应酬。丽娟十分不满Monica对她的苛刻，错手把一个丑化Monica的动画发到了Monica的邮箱，Monica要求启明解雇丽娟，启明只好服从。绝望之际丽娟得知任何公司都不能解雇孕妇，所以她决定假扮孕妇。没想到正好有一个立功的机会，却被Monica识穿了她假扮孕妇的事，令一直疼爱她的客户十分失望……©豆瓣', '杨千嬅', '麦启光', 6.1, 11718, 'tt0313812', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2488778548.jpg', 2.1, 16.2, 60.7, 15.6, 5.3, '0.065483,0.046215,-0.521540,0.351036,-0.397310,-0.389172,0.269416,0.480944,-0.382128,-0.284754,0.196585,0.612372,0.208407,0.295542,0.092082,0.215169,-0.122338,-0.429706,0.219800,-0.114247,-0.023132,-0.443125,0.218679,-0.322669,0.029382,0.003258,0.255459,-0.317907,-0.269113,0.133905,0.312218,-0.076263,0.272523,0.789436,-0.005229,0.034464,0.057075,-0.218220,-0.256540,0.082212,0.290806,-0.222916,-0.050742,0.282137,0.318483,0.423412,0.369316,0.268253,-0.630565,-0.011667,0.556932,-0.270367,-0.038987,0.106516,0.311148,0.031067,0.160990,0.248864,-0.423518,0.260731,0.157554,0.078377,-0.670367,0.018360,0.103577,0.047163,-0.768900,0.362351,-0.269450,0.134952,-0.009706,-0.652795,0.233198,0.119446,-0.108397,0.339195,-0.118277,0.437417,-0.629185,0.329995,0.528029,-0.131808,0.282087,0.191411,-0.049924,0.021840,0.217185,-0.252597,-0.624316,0.105292,0.014248,-0.182179,-0.407302,-0.157206,-0.420472,-0.380925,-0.120465,-0.221620,0.071500,-0.520727,0.140505,-0.360424,0.112994,-0.021443,-0.398118,0.065777,0.226249,-0.261171,0.656909,-0.683710,0.164547,0.652353,0.524132,-0.839683,0.693683,0.277646,-0.006105,-0.268586,-0.145343,-0.125402,0.001185,0.326990,0.076865,0.113863,0.490705,-0.465228,-0.112846,0.115266', '1421278', '1417543', '1877596', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308596', '我的野蛮女老师', '喜剧', '婉秀（金荷娜 饰）这名大二的学生因为家中经济条件的问题，不得不赚钱打工。婉秀找到了家教的工作，她的学生吉勋（权相佑 饰）是家中的少爷，读书不勤奋以致他即便与婉秀同年如今也只读高中。吉勋娇生惯养性格暴躁，与婉秀见面便不断争吵。吉勋面对衣着老土的婉秀很不满意，但在长时间的相处以来，他才发现婉秀的纯真善良。同样，婉秀也发现吉勋即便是个公子哥儿，但他十分重情重意的。两个人的故事又将如何继续呢？©豆瓣', '权相宇', '金庆炯', 6.6, 25307, 'tt0348591', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p739988253.jpg', 1.2, 8.8, 55.9, 26.2, 7.9, '0.422172,-0.192376,-0.527165,0.506995,-0.390701,-0.389127,0.409055,-0.004842,-0.707482,-0.563658,0.204973,0.525498,-0.002930,0.311629,-0.107190,0.092774,-0.055202,-0.452390,0.240281,-0.032898,-0.027788,-0.392653,0.043744,0.048264,-0.149328,-0.234897,0.388331,-0.192877,0.074868,0.486770,-0.114089,0.198437,0.280664,0.486726,-0.187025,-0.228618,-0.027553,0.321099,0.308492,-0.158995,0.135317,-0.208859,-0.371948,0.123782,0.284255,0.578987,0.775455,0.173136,-0.344463,0.141325,0.577669,-0.192866,-0.332384,0.147795,0.429255,-0.041199,0.462931,0.370866,-0.199008,0.055517,-0.314352,-0.107918,-0.522201,0.131460,0.454296,0.113099,-0.486946,0.668082,0.084178,-0.566464,-0.372050,-0.365376,-0.285761,0.266495,0.295562,0.442754,-0.276939,0.138023,-0.501007,0.126189,0.632387,0.223471,-0.320498,0.654831,-0.390613,-0.673051,0.267261,-0.613978,-0.838649,-0.020036,-0.345254,-0.057660,-0.232892,0.096193,-0.297614,0.321433,-0.129429,0.187890,0.014094,-0.451927,-0.110896,-0.257548,-0.169969,-0.828218,-0.644969,0.031994,0.101974,-0.284681,1.231841,-1.014037,-0.293076,0.368092,0.278529,-0.771779,0.708465,0.316801,0.018408,-0.233455,-0.241212,0.032474,-0.044746,-0.235684,-0.021390,0.460635,-0.047646,-0.657510,-0.165240,0.537012', '6963575', '26348103', '25922902', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308599', '21克', '剧情', '保罗（西恩•潘 饰），一位大学数学教授，患有严重的心脏病，生命垂危，幸运的是，成功的心脏移植手术使他死里逃生，可是，他和妻子的关系并没有因此而重获新生。杰克（本尼西奥•德•托罗 饰），曾经是酒鬼和犯罪分子，在一名牧师的帮助下，他重建了自己的生活，不仅成为青少年咨询顾问，还是正直善良的好父亲，可他的妻子有时候却暗暗期盼他能保留一点过去的性格。事实上，杰克对往事充满愧疚，背负着沉重的心理负担，努力寻找新生活的希望。克里斯汀（娜奥米•沃茨 饰），她曾经沉溺于毒品和派对，生活一塌糊涂。当她幡然悔悟，改过自新后，却因一起灾难性的事件，生活发生可怕的逆转，重新陷入了困顿。她经受不住这样的打击，回到了过去，并且拒绝改变。一桩交通意外将这三个人的生活联系在了一起，随着而来的，是苦难、复仇，还有爱和救赎。©豆瓣', '西恩·潘', '亚历杭德罗·冈萨雷斯·伊纳里图', 7.8, 51352, 'tt0315733', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p523110913.jpg', 0.6, 2.5, 25.4, 49.9, 21.6, '-0.001119,-0.092796,-0.624657,0.449590,-0.077036,-0.347234,1.007257,0.035735,-0.549400,-0.333765,0.178059,0.639021,0.077920,0.261558,0.192408,-0.049977,-0.228790,-0.683728,0.279506,0.161345,-0.350905,-0.478623,-0.268715,-0.293979,-0.203055,-0.587260,0.686002,0.208933,-0.177233,0.504780,0.149042,0.568069,0.331197,0.563009,-0.264835,0.126633,-0.023058,0.041035,-0.366844,0.005597,0.374230,-0.160681,-0.094546,0.427135,0.188999,0.307111,0.536291,-0.160178,-0.410392,-0.079216,0.409619,-0.378147,-0.042391,0.170586,0.009988,0.021775,0.068314,0.209882,-0.205420,-0.147824,0.139456,-0.106863,-0.922963,-0.100909,0.142498,0.230286,-0.726876,0.540086,-0.032164,0.032265,-0.012799,-0.027256,0.045740,0.457108,0.250756,0.457007,-0.287198,0.231136,-0.302678,0.164978,0.974363,-0.028516,-0.415278,0.414400,-0.680569,-0.209711,-0.049317,-0.216620,-0.638820,0.099230,0.215742,0.049130,-0.249596,0.372441,-0.315884,-0.087906,-0.337823,-0.108716,0.072294,-0.461372,0.025319,-0.407716,-0.193498,-0.368413,-0.505014,-0.097596,-0.084579,-0.540139,0.731093,-0.886742,0.324416,0.513065,0.280975,-0.756313,0.578168,0.306812,0.108574,-0.235007,0.076164,0.697581,-0.220953,0.156877,0.155610,0.238123,0.098825,0.172669,-0.280565,0.638512', '25721544', '6874741', '35030151', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308607', '稻草人', '喜剧', '日本统治台湾末期，田里的壮年男人都被拉去南洋当兵，佃农阿发（张柏舟 饰）、阔嘴（吴炳南 饰）两兄弟因为母亲（文英 饰）的偏方造成沙眼而幸免。但没当成兵的日子也好不到哪去。上有老母亲要养，中有一个疯了的妹妹，下有成群的儿女要顾，自己种的那几亩地收成又不好。坏上加坏的事是，地主决定把这几亩地收回来给卖掉。这可愁坏了两兄弟。孩子们体会不到父亲的担忧，依旧在田里玩耍。某一天在地里意外发现了未爆炸的炸弹。两兄弟颇为得意的把炸弹挖出，送到当地刑警那。刑警想借机向上级邀功，拉着二兄弟，让其护送炸弹去“呈现天皇”。一路上有惊无险，总算安全送达，结果惹得上级惊慌失措，视炸弹为“烫手山芋”。本想借机得点好处的两兄弟失望的把炸弹扔到海里，结果引爆的炸弹炸起一群鱼，可谓应祸得福，有悲有喜。©豆瓣', '卓胜利', '王童', 8.6, 8923, 'tt0092829', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2531300808.jpg', 0.2, 0.6, 8.3, 52.1, 38.8, '0.000189,-0.345819,-0.401707,0.262290,-0.163080,-0.160709,0.477457,0.212580,-0.218810,0.162429,0.179899,0.208675,-0.082872,-0.014304,0.016740,-0.020510,-0.212751,-0.279834,-0.189043,-0.121904,-0.309639,-0.239357,-0.265982,-0.263617,-0.175709,-0.021384,0.173950,-0.083907,0.176722,0.298202,0.076082,0.292736,0.051610,0.306120,-0.450027,0.366836,-0.360227,0.060611,-0.153236,0.357190,-0.040222,-0.238018,-0.000336,0.038306,0.285297,0.496978,0.707463,-0.072379,0.029490,-0.062095,0.110039,-0.046267,-0.066291,0.160114,0.370169,-0.044073,0.090285,-0.188912,-0.213639,0.103708,0.539390,0.095548,-0.330496,-0.091582,0.107418,-0.047550,-0.839245,0.396641,0.047189,-0.088053,-0.063568,-0.184020,0.426553,0.306665,-0.184921,0.586774,-0.381236,0.286988,-0.612785,0.193952,0.564646,-0.433251,0.182672,0.071062,0.025890,-0.182353,0.352695,-0.424668,-0.329503,-0.133404,0.502257,-0.018906,-0.300132,0.252938,-0.488283,-0.040100,-0.173752,-0.237438,-0.024331,-0.365022,-0.177563,-0.031181,0.352004,-0.171413,-0.255804,0.380201,0.410746,-0.052780,0.724089,-0.096220,0.093794,0.425070,0.117118,-0.586122,0.440230,0.149645,0.218719,-0.209685,-0.228472,-0.409517,0.396535,0.399356,0.518283,0.147898,-0.236769,-0.473724,-0.153510,-0.098135', '1306505', '1303637', '1432825', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308609', '压路机和小提琴', '剧情', '从五岁就开始学习小提琴的小男孩萨沙（Igor Fomchenko 饰）每天花大量的时间练琴，他和小朋友宛如生活在两个世界，有的淘气鬼甚至戏称他为“音乐家”。萨沙很苦闷，还要尽力躲开孩子们的奚落。有一天年轻的压路机驾驶员瑟黎卡（Vladimir Zamansky 饰）帮萨沙解了围，他们很快成为好朋友，开始了仅有半天的友谊。瑟黎卡约萨沙晚上去看电影《夏伯阳》，严厉的母亲得知后，将萨沙锁在家中，他们的约定最终未能成行……安德烈•塔科夫斯基处女作，亦是他在苏联国立电影学院的毕业作品，曾获纽约学生影展首奖。©豆瓣', '伊戈尔·福姆琴科', '安德烈·塔可夫斯基', 8.7, 16463, 'tt0053987', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2600107278.jpg', 0.2, 0.4, 8.5, 47.1, 43.8, '0.019464,-0.176802,-0.638457,0.455077,-0.204050,-0.253380,0.511250,0.077449,-0.342676,-0.178112,0.180885,0.832351,-0.309595,0.538351,0.062615,-0.151810,-0.435339,-0.811090,0.048786,-0.268269,-0.255752,-0.319325,-0.004203,-0.188638,-0.070463,-0.570235,0.541410,-0.226379,0.217259,0.335442,0.154810,-0.065209,0.127990,0.412518,-0.546603,0.164560,0.212226,-0.019156,-0.102670,0.159698,0.135197,-0.201075,-0.392093,-0.177969,0.254637,0.240626,0.776013,0.113480,-0.022001,0.060582,0.489619,-0.151770,0.079219,-0.020964,0.470495,0.009984,0.284541,0.077391,-0.137870,0.201090,-0.082987,-0.193153,-0.350988,0.112591,0.284699,-0.040827,-0.792042,0.644694,0.029529,-0.046972,0.085724,-0.271544,0.058007,0.493986,-0.108850,0.412546,0.008812,0.097159,-0.486780,0.417155,0.537670,-0.164646,-0.179305,0.381138,-0.005288,-0.370365,-0.015255,-0.191713,-0.372305,-0.064648,0.481367,-0.157670,-0.298847,0.097951,-0.505014,-0.101667,-0.180977,-0.321808,0.109460,-0.511884,0.006222,-0.742177,0.155608,-0.303182,-0.249382,0.000194,0.080326,-0.328649,1.184217,-0.899956,0.217472,0.455586,0.346824,-0.277461,0.892660,0.081661,0.000705,-0.089810,0.109999,0.260795,-0.164518,0.293919,0.268734,0.443096,0.039317,-0.219713,-0.336300,0.614170', '1307146', '25922902', '3811356', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308620', '摇滚校园', '喜剧', '杜威•费恩（Jack Black 杰克•布莱克 饰）是一名已过而立之年，却仍在为理想打拼的摇滚音乐人。他不屑于那种粗制滥造、充满向商业谄媚味道的虚伪乐曲，一心追逐真情实感的纯粹摇滚乐。为此，他和无数支乐队分道扬镳，至今事业无成，还面临被房东赶出去的窘境。杜威的男房东兼老友内德•斯尼勃利（Mike White 麦克•怀特 饰）此前曾是狂热躁动的死亡摇滚乐手，如今摇身一变成为了居家好男人以及代课老师。杜威闲赋家中时，偶然接到一通来自某中学的招聘电话，对方邀请内德迅速来学校代课。穷极无聊兼为生计所迫的杜威偷梁换柱，以内德的身份进入这所校风极为严谨的名门中学教学。学生们的死气沉沉一度让他倍感无聊，某天，杜威无意中发现孩子们的音乐天赋。于是，他瞒天过海，带领这群只知道读书的孩子们进入一个全新且乐趣无穷的摇滚世界……©豆瓣', '杰克·布莱克', '理查德·林克莱特', 7.9, 58719, 'tt0332379', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2635289668.jpg', 0.3, 2.1, 25, 48.7, 24, '0.126649,-0.014989,-0.542496,0.497782,-0.189499,-0.176523,0.542840,0.057839,-0.688214,-0.692030,-0.039777,0.539115,-0.108642,0.597152,0.348259,-0.162322,-0.186519,-0.623666,-0.239293,-0.147360,0.054984,-0.184191,-0.238778,-0.246024,-0.353549,-0.168211,0.428699,0.129888,-0.292522,0.417255,0.275802,0.594529,0.039708,0.363650,-0.286779,-0.005191,0.144363,-0.054088,-0.142909,-0.051703,-0.073378,-0.028919,-0.340233,-0.024290,-0.017426,0.321640,0.736329,-0.007055,0.022826,-0.315470,0.495038,-0.106063,-0.267913,0.195168,0.231639,0.097021,0.248228,0.177510,-0.056340,0.217912,-0.209318,-0.206956,-0.569810,-0.034300,-0.170329,0.072052,-0.250786,0.351580,0.094765,-0.181996,0.013924,-0.082194,-0.057977,-0.039493,0.051534,0.514468,-0.039445,0.267274,-0.291769,0.167977,0.729204,0.147960,-0.358192,0.246495,-0.223300,-0.276569,0.268847,-0.254931,-0.638551,-0.218360,0.120815,0.104367,0.132228,0.182727,-0.644341,-0.030564,-0.232615,-0.022370,0.096553,-0.255904,-0.222046,-0.800399,-0.005405,-0.237597,-0.279994,0.005089,0.043034,-0.211463,0.793968,-0.838078,0.102811,0.205107,-0.015023,-0.489884,0.521636,0.181090,0.250794,-0.187527,-0.335603,0.181433,0.255198,0.326238,-0.084531,0.259250,-0.230862,-0.262343,-0.181872,0.475076', '3811356', '25922902', '10174444', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308632', '心灵驿站', '剧情', '芬巴·麦克布赖德（彼特·丁拉基 Peter Dinklage 饰），一个一心只想安安静静过日子的普通男人，而他天生四尺五寸的矮小个头却格外引人注目。在众人的指指点点和嘲笑声中，芬巴只得避开人群，把所有时间和精力都花在研究各式火车上面。当唯一的好友过世，芬巴决定离开原本熟悉的环境，搬到纽泽西乡下朋友留给他的废弃火车库房独自生活。然而接二连三出现的意外访客，让原本希望离群索居的芬巴不情愿地开始了他的邻里生活。刚刚遭遇丧子之痛的中年女画家奥利维亚·哈里斯（派翠西娅·克拉克森 Patricia Clarkson 饰），健谈热情的热狗小贩乔·奥拉马斯（鲍比·卡纳威 Bobby Cannavale 饰），以及其他新朋友。渐渐地，在他们的温暖关怀下，拒人千里之外的芬巴开始敞开心扉，他的生活也在不经意间有了微妙的变化。©豆瓣', '彼特·丁拉基', '汤姆·麦卡锡', 8.1, 9020, 'tt0340377', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p831480464.jpg', 0.3, 1.1, 18.9, 53, 26.8, '0.474573,-0.017201,-0.740030,0.541728,-0.035686,-0.366883,0.937898,0.382670,-0.306335,-0.430350,0.019810,0.583030,-0.036094,0.421055,0.173712,-0.063686,-0.355936,-0.511428,-0.219634,-0.040510,-0.340046,-0.376764,-0.158172,-0.637090,-0.190003,-0.215709,0.324169,0.176095,0.112838,0.553770,0.128907,0.194365,-0.000036,0.524846,-0.429226,-0.003093,0.182560,-0.047623,-0.189924,-0.205671,-0.025521,-0.178809,-0.192443,0.283594,0.276566,0.488141,0.794234,-0.124947,-0.155672,0.315302,0.133857,0.162983,0.126508,0.118058,0.105288,-0.080460,0.148986,-0.085421,-0.232523,0.138513,0.034712,-0.112870,-0.281449,0.032566,-0.065849,0.223776,-0.424097,0.567954,0.039018,-0.028722,0.056296,-0.259046,0.167871,0.079086,0.049282,0.355301,-0.131370,0.137997,-0.337904,0.008705,0.619952,0.100630,-0.348692,0.426555,-0.539095,-0.285590,-0.036320,-0.125263,-0.451191,-0.375481,0.392906,0.000416,-0.110423,0.232884,-0.689760,0.117629,-0.022241,-0.140287,-0.000457,-0.359388,-0.202804,-0.642528,-0.092307,-0.537167,-0.361771,0.176548,-0.117698,-0.160021,0.637377,-0.539746,0.256080,0.309971,0.164682,-0.183708,0.715808,-0.105609,0.302276,-0.153431,-0.197890,0.482751,0.125894,0.203023,0.140646,0.396792,-0.298856,0.137505,-0.408821,0.503108', '21619567', '1296534', '3055049', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308635', '春琴抄', '剧情', '大阪修道街药商的女儿春琴（山口百惠 饰）生的美丽动人，但小时候因为眼疾而失明，却在三弦琴上练就出一番造化，生性清高的她不愿被人瞧不起，性格也愈发古怪起来。照顾她日常起居的是比她大四岁的仆人佐助（三浦友和 饰），伴随着春琴的佐助对小姐的照顾可谓无微不至，追随春琴学习三弦的他和春琴的接触与日俱增，逐渐心生爱意。二人的微妙关系，春琴却不为承认，直到春琴因为意外被毁容。为了不让春琴感到难过，佐助选择了刺瞎自己的双眼，这样，留在他脑海里的便是小姐永远美貌的样子。二人自此再没有什么间隙，永远的生活在了一起……本片改编自谷崎润一郎的同名小说。©豆瓣', '山口百惠', '西河克己', 7.8, 6896, 'tt0076560', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p537085118.jpg', 0.4, 1.7, 24.9, 50.8, 22.1, '0.187904,-0.070026,-0.645216,0.572659,-0.103472,-0.553355,0.820132,0.194748,-0.623140,-0.344963,0.112797,0.678953,-0.173093,0.137239,-0.136997,0.101913,-0.027665,-0.586772,-0.217624,-0.118703,-0.007392,-0.326397,0.173910,-0.134415,-0.167377,-0.327488,0.611673,0.032883,-0.167843,0.477508,0.206238,0.179227,0.113756,0.298627,-0.123581,0.037638,-0.384013,-0.036025,0.067929,-0.076391,0.146924,-0.252822,-0.209283,0.189121,0.024522,0.235048,0.685278,-0.210428,-0.291029,-0.171857,0.396550,-0.146351,-0.062660,0.059415,0.082935,-0.042368,0.258591,0.116453,-0.335467,-0.089809,0.007539,0.036429,-0.599131,0.167144,0.436790,0.182858,-0.623966,0.477198,-0.190842,-0.293027,0.172537,-0.242265,0.177838,0.113480,0.216958,0.400093,-0.494930,0.177105,-0.275050,0.114707,0.643590,-0.030448,0.021563,0.489090,-0.480497,-0.201663,-0.043929,-0.424795,-0.705496,-0.130409,-0.002277,0.125113,-0.342643,0.343862,-0.260862,-0.016662,0.005340,0.170015,-0.045613,-0.583216,0.042585,-0.225650,-0.223895,-0.806822,-0.395139,0.025356,0.126526,-0.308320,0.802857,-1.008236,0.283216,0.507467,0.234780,-0.422947,0.601547,0.199032,-0.170918,-0.004243,-0.127620,0.354912,-0.028627,0.007678,0.169208,0.403851,0.095988,0.173256,-0.301273,0.498274', '35030151', '3445516', '26354526', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308637', '总统千金欧游记', '喜剧', '美国女孩安娜（迪•摩尔 Mandy Moore 饰）和其他18岁女孩看起来没什么不一样，一样的青春无敌、精力充沛，不过，她有一个当总统的父亲。因为她是第一女儿，所以她必须时时刻刻保持完美形象，生活永远在镁光灯下。而且福斯特总统对她很严厉，身边总有一队保镖贴身保护，安娜完全没有一点自由。这次，安娜随父亲一起访问欧洲。本以为处处顺从父亲就能换来一点自由:晚上自由自在和好友加布里――法国驻美大使的女儿――去泡吧。没想到，性感火辣的两个美女在吧里竟然无人问津，原来又是父亲派来了保镖暗中护花。愤怒的安娜乔装打扮后撇下保镖逃出了酒吧，就此展开了她的“逃亡之旅”。©豆瓣', '曼迪·摩尔', '安迪·卡帝夫', 6.4, 9812, 'tt0360139', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1128801876.jpg', 1.7, 11.4, 57.3, 23.1, 6.5, '0.013455,-0.095620,-0.705443,0.513561,-0.456876,-0.365584,0.636687,0.085574,-0.558172,-0.301885,0.233238,1.004347,-0.044933,0.157687,0.250008,0.177260,-0.571833,-0.574517,-0.297167,-0.100518,-0.172414,-0.350243,-0.058309,0.054474,-0.243310,-0.202290,0.536255,-0.384751,0.173131,0.516782,0.290562,-0.035790,-0.002604,0.470600,-0.298991,-0.116611,0.333326,-0.252902,-0.211484,0.385871,0.230269,0.022596,0.061001,0.303667,0.264558,0.075928,0.342322,-0.386990,-0.134970,-0.199426,0.272124,0.052055,-0.088341,0.156057,0.088092,-0.255962,0.458046,-0.027057,-0.246670,-0.221981,0.132404,-0.176881,-0.488205,0.315168,0.128662,0.118432,-0.546686,0.337291,-0.124864,-0.133094,0.336809,-0.366339,0.186078,0.409170,0.142116,0.053618,-0.036136,0.172877,-0.522900,0.099659,0.810201,0.277591,-0.189155,0.222774,-0.415282,0.068173,0.114533,-0.331907,-0.630420,0.014848,-0.124427,-0.165250,-0.203931,0.041391,-0.202034,0.091274,-0.355303,0.120046,-0.175066,-0.583759,0.011214,-0.524884,0.122341,-0.444200,-0.128539,-0.010653,0.024372,-0.161273,0.809856,-1.079944,0.278757,0.625956,0.602672,-0.512883,0.680834,0.374397,0.002515,-0.187170,0.088930,0.275438,0.305417,0.077900,0.180494,0.380729,-0.121952,-0.004372,-0.139696,0.380317', '35030151', '1292720', '1292219', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308655', '新扎师妹', '喜剧', '方丽娟（杨千嬅饰）一直想成为一名警察，几经失败才考近了警校。虽然她在警校中刻苦学习，可是她天生并不是当警察的料，成绩不理想以外还常常笑料百出。毕业后，被调配到失物认领处工作，令她心里很不是滋味。刚好重案组在计划一宗缉拿黑帮的案子中需要一名生面孔的卧底，丽娟误打误撞被任命执行这次的任务。行动的过程中，她与黑帮老大区海文（吴彦祖饰）结缘，刚开始海文觉得丽娟的身世可怜，打算给予帮助。谁料两人后来互生爱意，阿祖百般体贴，令方丽娟觉得左右为难，没想到自己假戏真做了，方丽娟最后选择了什么样的决定呢？©豆瓣', '杨千嬅', '马伟豪', 7.9, 107707, 'tt0367104', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2625448949.jpg', 0.3, 2.2, 25.2, 45, 27.2, '0.293112,-0.053499,-0.686559,0.461183,-0.255925,-0.314312,0.334353,-0.096790,-0.795940,-0.436445,0.122242,0.602525,-0.167521,0.251268,0.122354,-0.037853,-0.282352,-0.731207,0.025012,-0.337856,-0.304283,-0.366272,-0.152336,-0.027616,-0.261909,0.071772,0.683543,0.159965,0.019408,0.280267,0.264968,0.248981,0.023494,0.336745,-0.020829,-0.233508,0.544886,0.110907,-0.186868,0.036134,0.256856,-0.261310,-0.214230,0.252353,0.159748,0.469623,0.541467,0.119263,-0.227956,-0.187518,0.163254,-0.342634,-0.032619,0.029404,0.481910,0.131103,0.368703,0.210956,-0.045751,0.103725,-0.056624,-0.351142,-0.768486,-0.123771,0.230669,0.078553,-0.419224,0.164763,-0.267154,-0.005965,0.031777,-0.349368,0.025265,0.339596,0.544586,0.366677,-0.242081,0.005665,-0.372128,0.220924,0.693307,-0.084764,-0.028289,0.396226,0.117748,-0.469168,0.297069,-0.182845,-0.180361,0.177015,0.000257,0.200478,-0.228325,-0.074939,-0.268722,0.062155,-0.236029,0.072712,-0.255605,-0.369016,0.035744,-0.277396,-0.046421,-0.169637,-0.437239,-0.062445,-0.017316,-0.256358,0.499481,-1.025139,-0.060015,0.566971,0.123028,-0.715052,0.340344,0.477684,0.045156,-0.490741,-0.068987,-0.211760,-0.083936,0.192651,0.292940,0.377702,0.012996,-0.669527,-0.242320,0.220135', '30345227', '35030151', '1293265', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308660', '我的军中情人', '剧情', '清晨，白雪覆盖的山区，一对以色列士兵正在营房附近挖掘土坑掩埋大量腐败的食品。队长尤斯（Ohad Knoller 饰）与战士里奥外出巡视，里奥长相俊美，同袍们用某位明星的名字——积加（Yehuda Levi 饰）来称呼他。尤斯与积加是一对秘密的同性恋人，他们很快把巡逻变成了一场雪地中的约会，即将退伍的积加把将来的旅行计划透露给尤斯……军官祖路带同两名女兵高迪与叶莉来到营房，布置了当晚的伏击任务，军人们吃过了匆匆拼凑的午餐，席间有人说着同性恋的笑话。叶莉属意积加但一直没有表白，熟悉内情的战士试图提出警告以便接近叶莉却没有收效。傍晚时分，小分队出动执行任务，夜色中突发的交火带来了悲伤的结局……本片根据真实故事改编，获2003年米兰、都灵国际同性恋电影节观众奖等褒奖。©豆瓣', '欧哈德·诺勒', '伊藤·福克斯', 7.7, 15256, 'tt0334754', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1815857435.jpg', 0.4, 2.6, 30.3, 43, 23.6, '0.251571,-0.267192,-0.470941,0.516050,-0.027152,0.088038,0.631717,0.021766,-0.355686,-0.143251,0.370744,0.493168,-0.200688,-0.007806,0.387727,-0.304301,-0.596691,-0.705327,-0.102948,-0.214195,-0.174406,-0.415320,-0.170732,-0.353459,0.047832,-0.325062,0.527785,0.095889,-0.154126,0.483981,0.155427,0.027409,-0.177467,0.471745,-0.155830,-0.005587,0.447283,-0.052184,-0.134150,0.147552,-0.425790,-0.223500,-0.337008,-0.055706,0.068338,0.568822,0.800095,-0.295622,-0.046287,-0.162819,0.129247,-0.261614,0.272322,0.074928,0.430339,0.168940,0.281960,0.166270,0.145410,-0.009000,-0.319809,-0.131202,-0.408601,-0.013034,0.210374,0.041444,-0.480719,0.386884,-0.176787,0.187346,0.261046,-0.118086,0.344557,0.176755,0.137568,0.325657,0.241876,0.039809,-0.451983,0.341655,0.474615,-0.247799,-0.069525,0.006064,-0.338607,-0.422179,0.190414,0.068212,-0.424331,0.104088,0.231249,-0.146433,0.016966,0.100594,-0.608190,-0.092173,-0.152940,-0.481503,-0.075777,-0.169396,-0.289884,-0.800123,0.113483,-0.074296,-0.222145,0.202732,0.000221,0.246217,0.559725,-0.506907,0.071846,0.417153,0.224570,-0.375499,0.528790,-0.000107,0.143153,-0.175676,0.013524,-0.011894,-0.044165,0.268276,0.281669,0.480768,-0.216808,-0.185763,-0.489955,0.220776', '2159244', '1294917', '5403927', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308672', '恋之风景', '剧情', '曼儿（林嘉欣 饰）为了寻找男友德森（郑伊健 饰）生前的一幅画来到了青岛。男友因为遗传性的疾病而离开了她，曼儿一直想找到这个画中的景象。青岛是德森小时候生活的地方，她想在这里能找到线索。来到青岛后的她认识了乐于助人的邮差小烈（刘烨 饰），小烈更乐于帮助曼儿寻找画中景象。但没想到的是小烈与曼儿之间的感情发生了微妙的变化，使曼儿不知所措，百般滋味在心头……©豆瓣', '林嘉欣', '黎妙雪', 6.8, 16249, 'tt0377923', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p916241813.jpg', 0.8, 7.1, 51.3, 31.1, 9.7, '0.378092,-0.190288,-0.769552,0.548186,0.087415,-0.344493,0.770760,0.086379,-0.859673,-0.350526,-0.022322,0.698274,-0.265210,0.378915,0.243805,0.281177,-0.284772,-0.654635,0.273036,-0.340409,-0.125405,-0.394706,-0.424027,-0.217404,-0.037551,-0.286220,0.527021,0.089035,0.085748,0.497197,0.253977,0.230684,-0.131152,0.425011,-0.266946,-0.061308,-0.048833,0.111292,-0.295894,0.210135,0.202118,-0.237982,-0.000981,0.322244,0.018841,0.185562,0.736780,-0.146500,-0.394924,0.161368,0.142723,-0.020767,0.155105,0.110904,-0.055167,-0.283900,0.261404,0.012087,-0.388150,-0.019500,0.258220,-0.101466,-0.429841,0.135170,0.110996,0.534348,-0.520375,0.235117,-0.154150,-0.320476,0.214743,-0.619114,0.588886,0.557485,0.375826,0.479937,-0.196088,-0.039146,-0.572871,-0.101279,0.768427,-0.042768,-0.013494,0.686356,-0.403715,-0.261951,-0.060757,0.090522,-0.213594,0.262790,0.033700,0.315195,-0.408024,-0.104271,-0.742220,0.028655,-0.120339,0.131058,-0.225046,-0.353143,-0.209702,-0.438601,-0.474339,-0.599894,-0.288588,-0.179653,-0.242179,-0.455328,0.608580,-0.949210,0.143150,0.344115,0.228841,-0.685815,0.667792,0.268903,-0.274370,-0.179063,0.063258,0.337533,-0.331793,0.220686,-0.199237,0.212264,0.134139,-0.172385,-0.426553,0.313611', '1301022', '25810920', '1308755', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308675', '超级名模', '喜剧', '励精图治的马来西亚新总理上台，令滥用童工的各大美国服装集团颇感压力，这班时装界巨头谋划选出最无知愚蠢的男模刺杀马来西亚总理……戴瑞克•祖兰德（本•斯蒂勒 Ben Stiller 饰）是蝉联三届最佳男模的超级模特，但是在最近的模特盛典上，祖兰德的第四次荣誉被新人汉瑟尔（欧文•威尔逊 Owen Wilson 饰）夺走，失落的祖兰德又遭遇了三位死党意外身亡，连续打击之下，祖兰德返回矿区的家乡，但这里的一切已经不再适合养尊处优的超级名模。时装界的超级设计师穆格图（威尔•法瑞尔 Will Ferrell 饰）此时向祖兰德抛出了橄榄枝，邀请后者与自己合作最新设计。《时代》杂志记者雯达（克里斯蒂娜•泰勒 Christine Taylor 饰）追查之下发现穆格图的真实意图是将祖兰德改造成行刺马来西亚总理的杀手……©豆瓣', '本·斯蒂勒', '本·斯蒂勒', 5.8, 7680, 'tt0196229', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1583953970.jpg', 6.8, 24.4, 46.6, 16, 6.1, '0.262821,0.078565,-0.372121,0.203113,0.254272,-0.297615,0.129354,0.206176,-0.722129,-0.306710,0.406520,0.867461,-0.424311,-0.211943,0.374783,0.298657,-0.149221,-0.559244,-0.174676,-0.315853,0.182757,-0.590190,-0.535598,-0.058105,0.054169,-0.464082,0.623953,-0.251477,-0.417540,0.363161,0.684894,0.428224,0.372541,0.227832,-0.053793,-0.093846,0.557596,-0.103277,-0.333673,0.298170,-0.140208,-0.276977,0.125113,0.478236,0.095510,0.244191,0.234919,-0.184450,0.173136,-0.358344,0.440099,-0.221709,-0.125039,0.067470,0.301919,0.206734,0.159781,0.325694,0.001393,-0.079384,0.079357,0.047506,-0.629184,0.044248,0.210744,0.174265,-0.495040,0.503651,-0.295444,-0.032505,-0.061475,-0.341052,0.209898,0.277249,0.204079,0.050249,0.152014,0.122548,-0.280824,0.388507,0.444159,0.120062,-0.223884,-0.097263,-0.112042,-0.368352,0.029860,-0.473681,-0.170829,0.150099,0.140966,-0.072961,0.231878,0.533132,-0.519146,-0.186192,-0.640151,0.019114,-0.049929,-0.203108,-0.109260,-0.906373,0.044148,-0.140639,-0.020569,-0.500430,0.278626,-0.068061,0.522530,-0.647505,0.189850,0.410281,0.307447,-0.034754,0.603179,0.147550,0.074470,-0.337635,-0.447395,0.011897,-0.079312,0.270979,-0.189823,0.213481,-0.028576,-0.600935,-0.068037,0.105587', '26990609', '24751811', '3077791', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308685', '烟花', '剧情', '小学生典道（山崎裕太）与佑价（反田孝幸）等同伴们就烟花升腾而起时是扁是圆展开争论，无果后，众人困惑起来，为了将困惑解决，他们决定趁夏季花火大会的机会去燃放烟花的灯塔上一探究竟。典道和佑价同时暗恋的同学，早熟的少女奈砂（奥菜惠）因为父母离异怀起心事。一场在典道和佑价之间进行的五十米游泳比赛结束后，奈砂单约胜利者佑价陪她去看烟花，不想对方最终决定同大伙一起去灯塔。奈砂最终拉上比赛失败的典道上路，目的地却变成了火车站甚至更远的东京。©豆瓣', '山崎裕太', '岩井俊二', 8.3, 28173, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2505448947.jpg', 0.1, 1, 17.1, 47.6, 34.3, '0.139457,-0.048895,-0.685649,0.116303,0.055379,-0.287367,0.387961,0.029979,-0.040003,0.076752,-0.012958,0.507696,-0.414911,0.361072,0.157118,-0.280380,-0.498958,-0.715130,-0.028707,-0.207496,-0.213951,-0.563736,0.316164,0.056425,0.176735,0.253624,0.644199,0.153277,0.138077,0.513880,0.366517,-0.196230,-0.203439,0.435311,0.035768,-0.172549,-0.273368,0.067259,-0.276252,0.283946,0.011823,-0.158545,-0.546031,0.126003,0.325086,0.139094,0.800078,-0.077951,0.091438,-0.239007,0.041712,-0.315420,0.078686,0.299218,0.329390,0.122610,0.055050,-0.176881,0.026949,-0.075729,-0.200666,0.059527,-0.197131,0.563914,0.057740,0.016174,-0.358037,0.488801,0.219436,-0.151189,0.278887,-0.428897,0.049993,0.397706,0.447827,-0.003062,-0.441358,-0.074368,-0.101581,-0.081378,0.907984,0.041978,0.376501,0.273083,0.064932,-0.267354,-0.097190,-0.109321,-0.263274,-0.078685,0.372311,0.127895,-0.285555,0.005257,-0.519427,-0.266341,-0.302656,-0.304203,0.067364,-0.246417,0.064746,-0.534614,0.277920,0.073120,-0.322129,0.181168,-0.085400,-0.189100,0.483884,-0.624930,0.058653,0.744527,0.364520,-0.297391,0.493957,0.105789,0.115004,-0.129191,0.133257,-0.030124,-0.207458,0.363959,-0.035213,0.070546,-0.017347,0.003069,-0.441589,0.220930', '26418093', '26930504', '1298346', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308699', '绿茶', '剧情', '不停相亲的比较文学专业女硕士吴芳（赵薇）每次和相亲对象约会时都会点一杯绿茶，在与新的相亲对象陈明亮（姜文）约会时，她告诉对方点绿茶的原因是曾被一名叫朗朗（赵薇）的女孩告知，从一杯茶可以预测一个人的爱情，对此，自信对女人很有研究的陈明亮认为纯属胡说八道，开始向吴芳分析说女人不外乎森林型和罗马型两种。带着各自对爱情的理解，吴芳和陈明亮开始了爱情角逐游戏。而随着两人的交往，朗朗也逐渐浮出水面，与刻板老土的吴芳形成对比的是，朗朗有着万众风情，然而陈明亮总觉得，她俩其实是一个人。©豆瓣', '赵薇 Wei Zhao', '张元', 6.3, 37851, 'tt0382821', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486702640.jpg', 2.5, 15.5, 51.7, 23.4, 6.9, '0.393913,0.078812,-0.601036,0.899173,-0.263982,-0.089308,0.885231,-0.069036,-0.493373,-0.184812,-0.173368,0.708842,-0.592318,0.201106,0.270647,-0.388158,0.045684,-0.629491,-0.194373,0.125252,-0.300755,-0.732890,-0.047910,-0.152830,-0.165417,-0.079556,0.285208,-0.053562,-0.497668,0.489845,0.448916,0.167850,-0.002569,0.708776,-0.002288,-0.341786,-0.272248,0.237006,-0.272414,0.125137,0.310843,-0.238952,-0.224319,-0.065640,0.014523,0.423403,0.612769,-0.104443,-0.262140,0.005140,0.350686,-0.282545,-0.132405,0.065024,0.270062,-0.020339,0.162321,-0.071097,0.021691,-0.361424,-0.108390,-0.206832,-0.459307,0.164900,0.197129,0.214268,-0.411064,0.245763,-0.002282,-0.222632,0.482587,-0.133274,0.363793,0.183608,0.453995,0.544130,0.145518,-0.100038,-0.489803,0.356234,0.605193,0.483220,-0.087978,0.413505,-0.568893,-0.581042,-0.071418,0.381400,-0.364412,0.048836,0.173051,-0.047641,0.102525,-0.060379,-0.672995,-0.004811,0.509850,-0.068445,0.231803,-0.653467,-0.029351,-0.423527,-0.209290,-0.629911,-0.418871,0.114493,-0.082659,-0.355170,0.767756,-1.160395,0.067365,0.237059,0.051395,-0.540829,0.949193,0.237333,-0.209837,-0.561235,0.119364,0.051884,-0.049509,-0.243731,0.148723,0.892217,0.056320,0.080984,-0.318413,0.399639', '2052978', '21766698', '1302384', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308709', '热舞甜心', '剧情', '热爱舞蹈的美国女孩哈尼•丹尼尔斯（杰西卡•艾尔芭 饰）性格开朗。她梦想自己能站在舞台上展现自己，也希望得到大家的赞许。这个梦想便一直激励着哈尼向前走。但哈尼的父母及男友都怀疑她的付出能否得到回报。对舞蹈十分执着的她决心一个人为理想奋斗。于是她搬离父母家，自己来到脏乱的街道居住，虽然那里的噪音不绝于耳，但这一切都影响不到她的灵感来源。哈尼为了理想，一直不懈努力。她白天教孩子们跳舞，晚上便到酒吧上班。她也在夜总会的舞台上表现自己，当她站在舞台中央的时候，她充满了活力。终于机会来了，一名导演看到了她的舞蹈后，想让她在节目中担当配舞演员。或许这正是帮助她实现梦想的一个好机会。可是路上充满了荆棘，命运不断向哈尼发出挑战，到底她最后又能否如愿呢？©豆瓣', '杰西卡·阿尔芭', '比勒·沃道夫', 7.3, 17626, 'tt0322589', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p515052159.jpg', 0.5, 4.1, 40.2, 40.9, 14.2, '-0.083680,0.233154,-0.952992,0.594990,-0.376061,-0.424371,0.696156,0.144561,-0.196903,0.085150,0.351984,0.627219,0.055863,0.439170,0.261338,0.081949,-0.495231,-0.716027,0.345949,-0.048038,-0.171171,-0.138105,-0.226746,-0.428072,-0.259047,-0.192260,0.577113,0.063242,0.023917,0.294892,0.350223,-0.188514,0.196393,0.696491,-0.205692,-0.101965,0.246810,0.067172,-0.037356,0.189034,0.074973,-0.287917,-0.440074,0.427187,-0.058566,0.182360,0.581147,-0.150419,-0.119842,0.090815,0.242309,-0.218550,0.306765,0.247743,-0.081290,-0.071888,0.237040,0.103281,-0.025942,-0.079522,-0.277315,-0.029586,-0.832643,-0.113384,0.052808,0.137866,-0.706948,0.509364,0.052980,-0.288765,0.299935,-0.398284,0.100309,0.171199,0.294135,0.272853,-0.591979,-0.002249,-0.463315,0.236522,0.616412,-0.120721,-0.092774,0.551387,-0.371461,-0.519846,-0.044009,0.077488,-0.724899,-0.178573,0.131551,0.040027,-0.064103,-0.233421,-0.438818,0.098711,-0.097749,-0.337563,-0.110846,-0.592333,0.067056,-0.471420,-0.086762,-0.207608,-0.381361,-0.042625,-0.087070,-0.569511,1.002909,-0.850953,0.143787,0.869744,0.276610,-0.503392,0.826411,0.197651,0.082487,-0.192991,-0.347782,0.391928,-0.502476,0.389521,-0.115097,0.352273,0.138272,0.038023,-0.586302,0.896544', '3230462', '4058933', '26021055', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308713', '拳霸', '动作', '身怀绝技的青年阿天（托尼·贾 Tony Jaa 饰）生活在泰国一座平静的村落——巴都村，他自幼跟随师傅学习泰拳。某晚，村中不成器的青年巴端打伤阿天的师傅，并将村民们虔诚以待的佛像之首盗走。肩负村民的嘱托和众望，阿天踏上寻找巴端和佛首的道路。几经辗转，他找到在曼谷混事的同乡阿含莱，岂料对方只是一个见钱眼开的小混混，根本无心帮忙，反而利用阿天的身手在黑市拳台大赚钱财。阿天在黑市拳台名震一方，不过他念念不忘村中的佛首，仍一门心思追查。不可避免，他将与作恶多端的文物犯罪集团展开连番较量……本片荣获2004年第六届法国多维尔亚洲电影节“亚洲动作单元奖”和2003年Sitges – Catalonian国际电影节Orient Express奖。©豆瓣', '托尼·贾', '普拉奇亚·平克尧', 7.9, 26474, 'tt0368909', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1071485041.jpg', 0.4, 2, 24.4, 50.8, 22.4, '-0.031875,-0.258931,-0.553185,0.517769,-0.022526,-0.267001,0.420350,-0.057400,-0.434370,-0.201367,0.247584,0.799509,0.001236,0.122732,0.158001,-0.134094,-0.062755,-0.599477,-0.149684,-0.007161,0.098395,-0.318191,-0.180930,-0.331983,-0.253630,-0.261269,0.494595,0.086153,-0.204621,0.531544,0.283553,0.019282,-0.161559,0.172188,-0.350403,-0.096527,0.029439,-0.029218,-0.271162,0.033891,-0.132723,-0.504860,-0.460693,0.050287,0.195046,0.388626,0.611959,-0.220546,0.027000,-0.060524,0.189623,-0.377406,-0.008365,-0.165515,0.348865,-0.070886,-0.067710,0.298971,0.019752,0.020452,0.219325,-0.248300,-0.365578,-0.018692,0.384234,0.015112,-0.722372,0.656313,0.118800,0.267939,-0.481081,-0.291286,0.167515,0.269451,0.034120,0.054683,0.027690,0.030706,-0.409629,0.413019,0.447249,-0.022205,-0.051016,0.075730,0.059324,-0.631316,-0.017431,-0.306524,-0.302721,-0.071317,0.403607,-0.181055,-0.139689,0.041369,-0.448478,-0.097565,-0.094876,-0.224052,-0.196290,-0.298191,-0.006410,-0.660539,0.027240,-0.286007,-0.169089,-0.045861,0.090707,-0.167503,0.726034,-0.675254,0.136683,0.649733,0.253537,-0.251337,0.691067,-0.083463,0.031088,-0.170583,-0.536016,0.129274,0.304758,0.170615,-0.051619,0.291771,-0.176705,-0.069746,-0.088283,0.329595', '3811356', '3804656', '1308609', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308715', '记忆裂痕', '动作', '工程师詹宁斯（本·阿弗莱克 Ben Affleck饰）是个高科技天才。他屡屡受聘于各种项目研究，获得丰厚酬劳，但为了高度保密，条件是完工后他必须被删掉大脑中的短期记忆。此次詹宁斯的任务报酬达到了天价，而他必须花费长达几年的时间投身于这个新产品研发。当产品完工后，令人意外的事情发生了。詹宁斯竟然没有得到承诺的报酬，取而代之的是一个信封，里面装着一封他自愿放弃酬劳的声明。詹宁斯大为惊讶，当他要查个水落石出时，却发觉麻烦惹得越来越大了。联邦调查局和公司的老板都对他穷追不舍，要把他置于死地。这一系列神秘的事件，更让詹宁斯相信，背后肯定有着不为人知的真相。果然，一场周密的阴谋随着他的追查渐渐浮出水面。©豆瓣', '本·阿弗莱克', '吴宇森', 7.3, 44524, 'tt0338337', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2021574101.jpg', 0.5, 4, 39.4, 44, 12, '-0.122895,0.239969,-0.587188,0.610063,-0.242859,-0.134787,0.397737,-0.195816,-0.499045,-0.341181,-0.003870,0.709895,-0.145586,-0.243453,0.015405,-0.104037,-0.104026,-0.510011,-0.019026,-0.472120,-0.235753,-0.697737,-0.368650,-0.433547,-0.142579,-0.097681,0.552415,0.220008,-0.230001,0.113014,0.323172,0.151753,0.321534,0.441922,0.006051,-0.200002,0.221081,0.035215,-0.055763,0.133149,0.291685,-0.328919,-0.138048,0.267861,0.086650,0.474449,0.374764,0.031830,-0.635626,-0.005850,0.630031,-0.422828,0.113791,-0.120508,0.092787,0.202766,0.000313,0.494166,-0.548128,-0.156904,0.302577,-0.213848,-1.103485,-0.177640,0.166597,0.106575,-0.365845,-0.024381,-0.324795,0.194617,-0.028907,-0.343452,0.045353,0.442633,0.509299,0.061411,-0.202385,0.123260,-0.698237,0.218070,0.384877,-0.053812,-0.098515,0.364454,-0.260281,-0.514295,0.037256,-0.341368,-0.148609,0.382898,0.369576,0.198128,-0.027358,0.302536,-0.315222,-0.069923,-0.371023,-0.480894,-0.246066,-0.350453,-0.167424,-0.449100,-0.252153,-0.102402,-0.412222,-0.070776,0.113531,-0.447330,0.677907,-0.471612,-0.080313,0.657048,0.125660,-0.639588,0.475009,0.065955,0.107213,-0.246312,-0.084622,-0.329534,0.059459,0.234531,0.020668,0.168882,0.482589,-0.541544,-0.218445,0.527056', '26678784', '6844861', '3785918', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308722', '十面埋伏', '剧情', '唐大中十三年，民间涌现不少反昏君反腐官的组织，其中以打着“杀富济贫推翻朝廷”旗号的飞刀门的势力最大。飞刀门总部设在靠近都城长安的奉天县境内，为保长安安全，朝廷下令奉天县府将飞刀门成员悉数剿灭。奉天县两大捕头刘捕头（刘德华）与金捕头（金城武）收到限期缉拿飞刀门新任帮主归案的命令。因怀疑牡丹坊的舞妓小妹（章子怡）是飞刀门前帮主的女儿，刘捕头设计将她拿下押入天牢，后又与金捕头再度设下圈套令金捕头化身义士将她救出，想骗取她的信任查出飞刀门的巢穴，但他不知的是，除了在公务上与金捕头和小妹打交道外，私情上也会与他们有番纠缠。©豆瓣', '金城武', '张艺谋', 6.3, 198278, 'tt0385004', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2160809605.jpg', 3.7, 15.9, 48.2, 24.4, 7.9, '0.091646,0.243897,-0.113293,0.462772,0.251789,0.088435,0.492199,0.446207,-0.499607,-0.205140,0.296510,0.292786,0.144042,-0.085155,0.208737,-0.165181,0.046424,-0.775390,-0.458369,-0.454900,-0.122386,-0.229620,-0.025893,-0.228712,-0.171712,0.082741,0.426604,0.230740,-0.232059,0.412241,0.322834,0.125441,-0.403154,0.332205,0.020646,0.087346,0.054181,-0.239415,-0.406902,0.112029,-0.164278,-0.475350,-0.111399,-0.083794,0.245463,0.324010,0.360964,-0.150001,0.176027,-0.345110,0.002910,-0.037133,-0.100091,-0.032638,0.586875,0.437868,-0.048435,0.406847,-0.440368,-0.258489,0.018233,-0.323556,-0.537407,-0.024546,0.324634,-0.131949,-0.599852,-0.035484,-0.236664,0.022230,-0.099414,-0.536697,0.283810,0.263155,-0.097201,-0.111098,-0.119507,-0.016134,-0.764693,0.412026,0.538209,-0.331158,0.097375,-0.721835,0.548876,-0.333503,0.112052,-0.212428,0.101732,-0.034074,0.428869,-0.375835,0.346145,0.090327,-0.317769,-0.310045,-0.629892,0.246675,0.058902,-0.174961,0.051038,-0.241841,-0.082407,0.026439,-0.162637,-0.237966,0.377913,0.305767,0.229612,-0.963129,-0.112409,0.263268,0.456280,-0.612911,0.697008,0.232232,0.311346,-0.190432,-0.311965,-0.478058,0.737603,0.758053,0.255343,0.401739,-0.157296,-0.514255,-0.152039,-0.258539', '2124718', '2052978', '1410695', '1419416');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308738', '冰雪女王', '剧情', '一场意外让恶魔之镜碎裂散落人间，其中的一小片不幸落入了小男孩凯（Jeremy Guilbaut 饰）的眼中，因为碎片的魔力，凯的个性开始变得古怪起来，世间的一切在他眼中都丑陋无比，他也因此远离了朋友和家人，封闭起了自己的内心。某日，冰雪王后（布里吉特·芳达 Bridget Fonda 饰）出现了，她将离群索居的凯带回了自己的国度。格尔达（切尔西·汉德勒 Chelsea Hobbs 饰）是凯的青梅竹马，两人从小玩到大，彼此之间感情十分要好。对于凯的下落不明，格尔达感到十分焦急。当得知凯来身处冰雪王后的宫殿之时，格尔达毅然决然地踏上了充满危险的旅程。最终，她能否顺利抵达目的地，救回被冰雪王后迷惑了心智的凯呢？©豆瓣', '布里吉特·芳达', '胡大为', 7.5, 5353, 'tt0210294', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2183210587.jpg', 0.6, 3.1, 35.9, 43.3, 17.1, '0.211553,0.320385,-0.875140,0.492002,0.180224,-0.116742,0.748892,0.186706,-0.360391,-0.236944,0.118205,0.812691,-0.382272,0.246351,0.307816,0.159367,-0.352561,-0.591314,-0.328657,-0.369298,-0.271338,-0.389297,-0.167957,-0.110684,-0.189125,-0.546708,0.647808,0.402357,0.118290,0.491893,0.130444,0.407649,-0.129111,0.402802,-0.174006,-0.019655,-0.044343,-0.156761,-0.133857,-0.014829,0.205411,-0.084850,-0.035922,0.707201,-0.121100,0.361570,0.860068,-0.439529,-0.063863,0.019027,0.262530,-0.330688,0.110395,0.150267,0.065354,-0.156757,-0.133602,0.178097,-0.243222,-0.074880,0.195523,-0.050647,-0.586747,0.014257,0.200698,0.192282,-0.421700,0.341334,0.090140,-0.018222,0.006689,-0.432001,0.304083,0.208920,0.096420,0.372596,-0.238035,0.016923,-0.339758,-0.214626,0.754828,-0.063794,-0.291483,0.314792,-0.390302,-0.393023,-0.070176,-0.064294,-0.511430,-0.106090,0.608983,0.296338,-0.025842,0.574568,-0.863958,-0.224447,-0.523568,0.003096,-0.203100,-0.328391,-0.145633,-0.146015,-0.218799,-0.446355,-0.412222,0.096828,-0.289191,-0.189859,0.598626,-0.852488,0.321811,0.340436,0.318790,-0.026697,0.349814,-0.161479,0.033586,-0.190169,-0.072301,0.371885,0.080162,0.069316,0.168713,0.376016,-0.201913,0.110941,-0.521611,0.560706', '2032339', '1438591', '3626364', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308741', '独自等待', '剧情', '繁华都市之中，年轻的陈文（夏雨饰）和他的一班好友怀揣各自的梦想，终日徘徊在等待与寻觅的地平线上。在偶然邂逅理想中的爱情目标刘荣（李冰冰饰）之后，陈文渴望爱情的激情被瞬间点燃。在好友们（高旗、吴超、高亚麟等饰）的百般怂恿之下，经由绰号“孙子”（涂松岩饰）的所谓“恋爱专家”点拨，陈文不顾一切地是展出五花八门的求爱攻略，演绎出一幕幕颇具喜剧色彩的浪漫情节。然而此时，在他身旁暗中相助的多年玩伴李静（龚蓓苾饰），却在心中默默隐藏着对陈文的真爱。 在独自等待的人生旅途中，每一个青涩生命不断努力实践着梦想，在不知不觉中体味到成长的真实滋味……©豆瓣', '夏雨', '伍仕贤', 8.2, 199153, 'tt0311041', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486667524.jpg', 0.3, 1.5, 18.6, 46.4, 33.3, '0.202496,0.240591,-1.010500,0.754197,0.120359,-0.089754,0.934608,-0.073296,-0.567736,-0.065309,0.401470,0.558352,-0.320805,0.590334,0.313054,-0.388883,-0.256333,-0.884664,-0.167939,0.024113,-0.078345,-0.332852,-0.525809,0.034533,-0.361364,-0.169204,0.789127,0.215536,0.035097,0.597953,0.408244,0.290624,-0.282598,0.300921,-0.338168,-0.016343,0.319674,0.254460,-0.381977,0.130720,-0.004727,-0.507603,-0.227968,-0.055730,-0.385682,0.152122,0.974248,-0.445403,0.008809,0.279975,0.353464,-0.188923,-0.022245,0.183303,-0.048923,0.224397,0.202689,0.114251,-0.139906,0.031148,-0.089456,-0.081461,-0.804988,-0.406661,0.239648,0.387695,-0.570312,0.623571,0.317107,-0.199002,0.430019,-0.264439,0.001045,-0.046205,0.284835,0.416431,-0.370870,-0.110787,-0.102691,0.542140,0.471103,0.070186,-0.145165,0.540097,-0.337717,-0.192988,-0.039796,0.092230,-0.717224,-0.439665,0.356201,0.315386,-0.171863,0.282217,-0.644198,0.330851,0.072362,0.046489,0.197320,-0.508923,-0.306663,-0.596035,-0.296567,-0.542952,-0.212331,0.182566,-0.076650,-0.388523,0.836896,-0.887822,0.360697,0.610681,-0.166622,-0.213013,0.638974,0.335565,-0.012232,-0.277118,-0.081597,0.536717,-0.222492,0.118814,-0.129996,0.360544,-0.446547,0.348739,-0.830901,0.683869', '10467125', '3097044', '1307146', '10467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308742', '魔幻厨房', '喜剧', '慕容优（郑秀文饰）经营一家私房菜馆，对前男友传佑（刘德华饰）仍念念不忘，也完全没有注意到助手小可（言承旭饰）的心仪她已久的心意。她一直认为与传佑感情的凋谢是因为当年母亲婚姻失败的一个诅咒，后来慕容优的好友傅薇（Maggic Q饰）与传佑拍拖，她就更深感困恼。默默无闻的小可一直鼓励慕容优走出母亲的阴影，大胆创出属于自己的人生。当慕容优前往日本参加一场电视烹饪比赛的时候，现场表达了自己内心最深出的声音，而慕容优最后能否跟痴情的小可的结局又是如何。©豆瓣', '郑秀文', '李志毅', 5.6, 28885, 'tt0396735', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1728514460.jpg', 5, 26.5, 54.5, 10.7, 3.2, '-0.053255,0.272588,-0.570458,0.659503,-0.181448,-0.335190,0.808442,-0.014185,-0.758191,-0.392283,0.359713,0.529792,-0.073179,0.286366,0.193690,0.134980,-0.085305,-0.783183,-0.109496,0.159019,-0.240913,-0.280396,-0.349415,0.054965,-0.454642,-0.001011,0.596580,0.281883,-0.146688,0.437170,0.345072,0.184757,-0.072619,0.401692,0.158751,0.150641,0.085156,0.598948,-0.408648,0.058359,0.157015,-0.371994,-0.387068,0.203672,0.134688,0.311629,0.661317,-0.081808,-0.095552,-0.113208,0.096932,-0.387902,-0.153969,0.365544,-0.168474,-0.245009,0.744084,0.168689,-0.144793,-0.287657,-0.241784,0.140227,-0.584976,-0.043873,0.110127,0.095307,-0.329885,0.315103,-0.715265,-0.144161,0.304201,-0.514679,0.111504,0.137424,0.500144,0.358240,-0.692090,-0.081338,-0.279009,0.180598,0.646282,0.265972,0.137168,0.222317,-0.235426,-0.453922,-0.034672,-0.061047,-0.407816,0.068338,0.097867,0.110830,0.040971,0.155492,-0.352785,-0.347598,0.006816,-0.130434,0.465999,-0.755538,-0.146748,-0.419295,-0.077146,-0.746710,-0.311354,-0.319611,0.194990,-0.548986,0.752727,-0.989625,0.220042,0.041733,0.163477,-0.595275,0.526624,0.203576,0.093967,-0.075677,0.058197,0.280128,-0.408121,-0.201275,-0.218044,0.323328,0.194326,-0.125328,-0.573643,0.567792', '26354526', '1301022', '35030151', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308745', '玉观音', '剧情', '云南边陲小镇南德的缉毒女警安心（赵薇）的生命中一共出现过4个男人，铁军（陈建斌）、毛杰（谢霆锋）、杨瑞（柳云龙）先后令她的心泛起过涟漪，而作为长辈的潘队（孙海英），则始终当她是孩子，对她的生活照顾有加。在平静的外表下，安心内藏一颗汹涌澎湃的心，她渴望激情却要考虑理智与责任，于是逐渐身陷进退维谷，有意无意之间令自己和铁军、毛杰等人的命运变得无法掌控。——安心的多重身份（警察、妻子、母亲、情人等）令她复杂，而这种复杂同她所追求的简单作对比时折射出“宿命”意味。©豆瓣', '赵薇 Wei Zhao', '许鞍华', 6.3, 27397, 'tt0413515', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p970235094.jpg', 2.2, 14.3, 56.2, 20.7, 6.6, '-0.019030,0.053619,-0.892681,0.657406,-0.293800,0.011522,0.852638,0.358164,-0.926938,0.087725,0.301044,0.525525,-0.019924,0.375100,0.116391,-0.041428,-0.329014,-0.616453,-0.219743,0.024381,-0.042379,-0.356713,-0.334528,-0.185888,-0.183924,-0.246066,0.585732,0.247207,0.209537,0.330654,0.070720,0.246131,-0.107360,0.563709,0.082603,-0.168470,-0.168499,0.006775,-0.484066,-0.025942,0.216018,0.047354,-0.175022,0.355184,-0.128269,0.431610,0.679744,-0.066596,-0.363182,-0.120586,0.114988,-0.027533,-0.097625,0.140793,-0.206770,0.139687,0.116555,0.116664,-0.187840,-0.036853,-0.072526,0.079218,-0.825033,-0.094696,0.130912,0.244741,-0.447507,0.378005,-0.080936,-0.077333,0.030967,-0.194157,0.207011,0.046319,0.247585,0.317400,-0.597675,0.020524,0.110538,0.295109,0.684799,0.089452,-0.381381,0.479289,-0.557876,-0.214906,0.175706,-0.067257,-0.664321,-0.090310,0.101809,0.384120,-0.130271,0.380110,-0.246713,-0.023109,-0.220287,0.174189,-0.207910,-0.709116,0.051602,-0.005485,-0.389637,-0.573122,-0.303275,0.095298,0.091712,-0.127522,0.650375,-0.814093,0.246960,0.356169,0.226761,-0.404900,0.323081,0.207347,0.137000,-0.314879,-0.118145,0.497372,-0.211470,0.087593,-0.078354,0.188677,-0.324569,0.253229,-0.171310,0.296818', '1301022', '35030151', '25810920', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308746', '恋爱中的宝贝', '剧情', '生于1979年的宝贝（周迅）少时总梦见自己会飞，当她对自己从何处来感到困惑时，通过母亲之口知晓被捡于垃圾箱，这令她自此不断生出奇思怪想。在中国改革开放的进程中，宝贵渐渐长大，见证城市的飞速发展。某天，一头乱发的宝贝捡到一卷“自拍带”，发现带子中的男人和她一样也“想飞”后，她开始满世界寻找他，期望用自己的精神拯救他的灵魂，两人能有美好的未来。“自拍带”中的男人叫刘志（黄觉），是个每日在都市中辛苦讨生活的白领，精灵古怪的宝贝的出现令他早已麻木的心重新点燃激情，两人迅速坠入爱河，然而，生活中除了风花雪夜的浪漫爱情，更多是零零碎碎的平庸无聊。©豆瓣', '黄觉', '李少红', 6.3, 19048, 'tt0415116', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209582667.jpg', 4.2, 17.6, 47.8, 21.9, 8.5, '0.118999,0.084776,-0.695427,0.361275,-0.161498,-0.128690,0.763188,-0.239085,-0.627709,0.119371,0.113659,0.768071,-0.173183,0.371845,0.192513,0.048706,-0.259179,-0.640374,0.013746,-0.120920,-0.289051,-0.160529,-0.473711,-0.169829,-0.314228,-0.273873,0.576892,0.241154,0.069671,0.387389,0.198443,0.133506,-0.146207,0.559439,-0.503296,-0.003876,-0.098973,0.292885,0.128921,0.045004,-0.039285,-0.250398,-0.166511,0.100513,-0.175802,0.254762,0.731062,-0.241347,-0.081045,-0.080749,0.453754,-0.092559,-0.397990,0.054913,-0.037577,0.239648,0.004408,-0.037996,-0.283034,0.106250,0.066539,-0.146545,-0.635060,-0.124249,0.197436,0.191350,-0.440762,0.187447,0.136195,-0.142591,0.435948,-0.338455,0.253339,0.001222,0.219981,0.706583,-0.230976,0.004094,-0.244054,0.371985,0.428538,-0.134291,-0.298049,0.447704,-0.334012,-0.242407,0.230674,-0.102605,-0.535232,-0.246301,0.205242,0.272440,-0.404460,0.396540,-0.652507,0.364144,0.057372,-0.325566,-0.062805,-0.468041,-0.486642,-0.113873,-0.291615,-0.566340,-0.114579,-0.001431,0.120177,-0.394645,0.903998,-0.679689,0.341363,0.398463,0.084184,-0.278283,0.646136,-0.042586,-0.051636,-0.111195,-0.058479,0.404656,-0.092009,0.307711,0.010753,0.275457,-0.325222,0.126225,-0.520214,0.592068', '2357162', '2081098', '4724586', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308747', '手机', '剧情', '著名电视谈话节目《有一说一》的主持人严守一（葛优）在去电视台录节目时，把手机忘在家中，手机中所藏的他与情人的秘密被妻子余文娟发现，后者想起他人前人后的两张脸时，觉得婚姻失去意义，提出离婚。不久，戏剧学院台词课教师沈雪（徐帆）成为严守一新女友，两人度过一段快乐时光后，沈雪发现严守一的手机响铃方式由震铃改成了震动，产生猜疑和嫉妒。原来严守一一直割舍不掉秘密情人——某出版社女编辑武月（范冰冰）。武月在火车餐车上与严守一偶然相遇后，开始对他穷追不舍，要他为出版社写书。因为武月能帮下岗的妻子余文娟找工作，严守一答应下来，不久两人成为情人。而为了不让沈雪发现武月的存在，严守一开始不断对沈雪说谎，生活朝一团糟糕方向发展。©豆瓣', '张国立', '冯小刚', 7.4, 197110, 'tt0399650', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1930481609.jpg', 1, 2.8, 34.8, 48.2, 13.2, '0.293973,0.087108,-0.733909,0.561669,0.120740,-0.106873,0.785850,0.061719,-0.423505,-0.281075,-0.075403,0.734825,-0.425855,0.265005,0.230537,-0.107576,-0.251385,-0.923975,0.282177,-0.123334,-0.205612,-0.300160,0.285790,-0.202886,-0.141429,-0.185124,0.544433,-0.103576,-0.199706,0.384408,0.275436,0.077792,-0.214843,0.449356,0.115033,0.159535,-0.035874,0.232445,-0.433480,0.285911,0.291537,-0.008230,-0.188972,0.007839,-0.075288,0.062611,0.620338,0.229583,-0.312608,-0.006495,0.469341,-0.164252,-0.277369,-0.007851,0.420440,0.276509,0.248579,0.047047,-0.313706,-0.087004,0.105767,-0.128712,-0.267057,0.026497,-0.268522,0.250101,-0.352658,0.214040,-0.329160,0.107570,0.256754,-0.502243,0.325410,0.359167,0.482545,0.448335,-0.183793,0.144541,-0.215456,0.342803,0.541231,0.013269,0.139526,0.647505,0.068590,-0.181126,-0.028487,0.276067,-0.527503,0.039211,0.309487,0.016606,-0.318165,-0.029196,-0.396299,-0.258542,0.077968,-0.122353,0.186726,-0.657996,-0.274030,-0.488118,-0.339833,0.017101,-0.159017,-0.045038,-0.061199,-0.497780,0.616344,-0.991911,0.221512,0.418386,0.318127,-0.561967,0.715791,0.278433,0.023376,-0.449981,0.173913,0.099210,-0.011038,0.294139,0.208156,0.000873,-0.103506,-0.129422,-0.388467,0.241744', '2052978', '2027925', '30345227', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308748', '地下铁', '爱情', '海约（杨千嬅饰）是一个盲女，误打误撞认识了婚姻介绍所的老板旭明（梁朝伟饰）。旭明是个普通的男人，还没找到真爱，却也意外的失了明。在黑暗的世界中，是海约让色彩重新在他心中刷亮，他们一起用独特的方式去感受这个多彩缤纷的世界，在单纯的快乐中二人相恋了。董玲（董洁饰）是一个在上海地铁工作的女孩，一直喜欢的男子结婚了，她内心受伤。此时偶然收到了一封来自台北的贺卡。于是，和贺卡主人钟程（张震饰）一段互相寻找爱的故事开始了。然而自从旭明吃下了一颗诡异的圣诞糖果，他和海约的关系便有了令人不安的转折。同时，钟程和董玲也在地铁里苦苦找寻着地铁46号出口……©豆瓣', '杨千嬅', '马伟豪', 6.4, 40116, 'tt0395991', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486659308.jpg', 1.2, 10.8, 61, 21.7, 5.3, '0.432730,0.257063,-0.839509,0.772123,-0.235847,-0.216118,0.923652,0.035312,-0.444895,0.088402,0.026194,0.854054,-0.327456,0.275278,0.069840,0.347586,-0.228329,-0.704058,0.027378,-0.268664,-0.227948,-0.551260,-0.317516,0.047664,-0.070933,-0.203828,0.469063,0.232829,0.012963,0.638028,0.348497,-0.016225,-0.163384,0.731401,-0.475103,0.149961,0.075966,0.174695,-0.166176,0.170740,0.169398,-0.246156,-0.153454,0.422220,-0.007293,0.424301,0.686823,-0.196704,-0.232754,0.154400,0.280551,0.013981,-0.226277,0.004922,0.298427,-0.010605,0.358623,0.178080,-0.351530,0.184990,0.099848,0.203558,-0.744789,-0.057858,0.018357,0.262983,-0.545782,0.629945,-0.053928,-0.401703,0.181137,-0.397480,0.495637,0.178776,0.215280,0.536248,-0.107593,-0.078859,-0.475444,0.256890,0.774139,0.162793,-0.166153,0.710564,-0.360824,-0.431091,-0.099437,0.159924,-0.466467,0.013262,0.387792,0.093465,-0.449916,-0.124358,-0.835734,0.293046,0.069514,-0.058392,0.123481,-0.523028,-0.332494,-0.327741,-0.155482,-0.562461,-0.330987,0.027649,-0.060506,-0.200131,0.775126,-0.934496,0.191082,0.657412,0.302781,-0.305654,0.975126,0.277324,-0.066312,-0.139331,0.140854,-0.057263,-0.225081,0.393203,0.189758,0.619267,0.009094,0.098967,-0.527504,0.577414', '3055049', '24756472', '30162520', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308749', '忘不了', '剧情', '阿文（古天乐 饰）是一个小巴司机，在一次交通意外中丧生了，他的新婚妻子小慧（张栢芝 饰）强忍伤痛也要继续生活下去，还要照顾阿文与前妻生下的儿子乐乐（原岛大地 饰）。她开着阿文生前用过的小巴开始新的生活，可是行内的人都看不起这个女小巴司机，踌躇满志却处处碰壁。大辉（刘青云 饰）同情她的遭遇，便开始教授她一些在行内需要注意的行规以及竞争的方法。迫于生活的压力，小慧想让乐乐过上好生活，便打算把乐乐交给他的生母抚养，大辉出面阻止，并承诺帮忙抚养乐乐，但其实大辉心中也有不少解不开的结，两个同样心事重重的人，走到了一起。©豆瓣', '张柏芝', '尔冬升', 7.8, 66295, 'tt0390272', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554388802.jpg', 0.2, 1.5, 26.6, 52.6, 19.1, '0.156298,-0.093839,-0.507376,0.467879,-0.228430,-0.351768,0.588603,0.210208,-0.525186,-0.294620,0.091363,0.657137,0.181999,0.451398,0.045350,-0.076735,-0.177869,-0.411372,0.192706,0.191189,-0.233792,-0.299261,0.088656,-0.268779,-0.263163,-0.122239,0.508161,-0.095102,0.062072,0.478356,0.248623,-0.071173,0.006544,0.484917,-0.264253,0.212322,-0.220412,-0.094088,-0.326161,-0.152807,0.187680,-0.176132,-0.149255,0.211583,0.466388,0.188943,0.575778,0.015412,-0.237921,-0.017158,0.078272,-0.203662,-0.095407,0.078308,0.058838,0.142101,0.244982,0.225133,-0.175377,0.173415,0.038666,-0.016869,-0.595082,0.096739,0.081353,-0.007035,-0.717841,0.349503,0.058371,-0.085519,-0.053018,-0.522196,0.273084,0.314223,0.116881,0.401682,-0.292301,0.254561,-0.170366,0.209153,0.717457,-0.177393,0.160253,0.359966,-0.317328,-0.076453,0.077427,-0.057833,-0.776971,0.015788,0.014975,0.031791,-0.402645,0.047211,-0.496841,0.122874,-0.320648,-0.106088,0.042838,-0.512006,0.246153,-0.336159,-0.038411,-0.454659,-0.376672,0.235144,0.261986,-0.400192,0.646283,-0.632936,0.129787,0.091781,0.535500,-0.660170,0.443929,0.332541,0.176324,-0.241689,-0.108970,0.278836,-0.178945,0.124584,-0.073226,0.238822,0.149197,-0.116933,-0.313630,0.227973', '1291586', '3445516', '1299965', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308751', '特洛伊', '动作', '在浪漫壮观、引人遐思的古希腊，奥林匹亚众神与人类之间的爱恨传奇至今为人津津乐道，而在这其中，荷马史诗《伊里亚特》所记录的特洛伊之战更是后世剧作家与观者反复演绎的经典作品。当特洛伊王子帕里斯（奥兰多·布鲁姆 Orlando Bloom 饰）受希腊斯巴达国王之邀赴宴之际，却迷恋上了国王的妻子海伦（黛安·克鲁格 Diane Kruger 饰），对方倾国倾城的容貌让他不能自已，遂将海伦带回自己的国家。此举引发了希腊诸国的愤怒，在迈锡尼国王阿伽门侬（布莱恩·考克斯 Brian Cox 饰）的号召下，一支强大的联军浩浩荡荡向特洛伊挺进。在随后长达十年的战争中，阿喀琉斯（布拉德·皮特 Brad Pitt 饰）、奥德修斯（肖恩·宾 Sean Bean 饰）、赫克托尔（艾瑞克·巴纳 Eric Bana 饰）等英雄各逞英豪，谱写了荡气回肠却又令人扼腕唏嘘的传奇史诗……本片荣获2004年青年选择奖最佳男主角奖（Brad Pitt）。', '布拉德·皮特', '沃尔夫冈·彼德森', 7.5, 138215, 'tt0332452', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p727373711.jpg', 0.5, 3.2, 32.8, 45.3, 18.2, '0.031829,0.202519,-0.694714,0.614645,0.459684,-0.286171,0.764475,-0.140262,-0.452351,-0.048908,0.378124,0.880568,-0.496337,-0.091990,0.555212,0.012242,-0.573309,-0.742311,-0.096858,-0.194502,0.026474,-0.149827,-0.443214,-0.082324,-0.167419,-0.449923,0.537995,-0.120329,-0.090854,0.477054,0.232236,0.478247,-0.056255,0.037763,-0.171713,0.152318,0.111605,-0.158329,-0.302343,0.110207,-0.179203,-0.330517,-0.427387,0.352565,-0.401283,0.176235,0.500379,-0.683707,0.359223,-0.143702,0.401152,-0.129714,0.114295,0.144654,0.020642,-0.207796,0.012589,0.089533,0.038225,-0.092754,0.250117,-0.048798,-0.725070,0.135180,0.065309,0.277584,-0.306551,0.642639,-0.269779,0.072723,0.235626,0.059598,0.031298,0.161738,0.397106,0.381188,0.181838,-0.105246,-0.200661,0.420107,0.499022,0.231787,-0.451677,-0.102509,-0.262405,-0.688919,-0.093753,-0.317248,-0.681399,-0.024811,0.436286,-0.035155,0.702184,0.601688,-0.627936,-0.145960,-0.371211,-0.031848,0.008740,-0.103795,-0.090955,-0.583722,-0.097745,-0.369961,-0.146864,-0.026837,0.332852,0.015770,0.714310,-0.315599,0.088648,0.482214,0.214734,-0.111222,0.576001,-0.055863,0.131171,0.069526,-0.258673,0.604841,0.066990,0.018948,0.107605,0.331448,-0.058851,-0.176992,-0.387931,0.434835', '30162520', '26647163', '1299663', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308752', '生化危机2：启示录', '动作', 'T病毒在蜂巢中肆虐并很快打破了地面上浣熊市的平静，丧尸开始在人群中出现，安布雷拉公司将整个城市封锁，计划使用核武器摧毁城市以掩盖病毒外泄的事实。被安布雷拉注射T病毒使身体能力远超常人的爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）由昏睡中醒来，她在混乱的浣熊市与防卫队员瓦伦汀（Sienna Guillory 饰）、记者泰莉等人组成队伍，试图找到脱身之法。另一方面，安布雷拉公司的科学家艾肯佛博士为搭救被公司抛弃在城中的女儿安琪拉，以提供逃生方式为代价请求爱丽丝和防卫人员卡洛斯（Oded Fehr 饰）两组人马帮助。而安布雷拉公司派出了由环保分子麦特所改造成的“复仇邪神”阻止这一切……本片获2005年加拿大吉尼奖最佳音效剪辑奖、金盘奖。是生化危机系列电影的第二部。©豆瓣', '米拉·乔沃维奇', '亚历山大·维特', 7.9, 246266, 'tt0318627', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1212493067.jpg', 0.2, 1.6, 23.3, 50.3, 24.6, '0.017102,0.307739,-0.455845,0.354280,0.073097,0.193653,0.494665,0.047193,-0.467275,-0.213807,-0.076302,0.479852,-0.061870,-0.184850,0.131468,-0.012093,-0.590204,-0.574179,-0.207922,-0.036739,-0.290044,-0.371862,-0.338217,-0.530089,0.121785,-0.752522,0.748538,0.266297,-0.078963,0.127078,0.004544,0.469264,-0.328007,0.207401,0.372181,0.004466,0.025135,-0.583808,-0.546141,0.470708,-0.307412,-0.340221,0.047882,0.120785,0.095587,0.160580,0.737190,-0.157627,0.224195,-0.423070,0.287798,-0.480514,0.077021,-0.263220,0.365360,-0.064500,0.093772,0.105147,-0.265148,0.079085,0.256417,-0.212060,-0.831584,-0.179513,0.338713,0.070884,-0.415431,0.007442,-0.257673,0.418444,0.028656,-0.171579,-0.013443,0.257578,0.298117,0.249041,-0.009434,0.097382,-0.510159,0.088487,0.365365,-0.360998,-0.417510,0.041031,-0.205909,-0.434936,-0.176680,-0.226708,-0.134742,-0.103629,0.299324,0.213025,0.044786,0.147754,-0.520671,-0.159278,-0.403858,-0.466683,-0.138094,-0.320239,0.049576,-1.015955,-0.013480,0.281061,-0.038502,-0.029013,-0.033523,-0.225033,0.398965,-0.735073,0.153103,0.626757,0.254149,-0.420485,0.333081,-0.462287,0.283553,-0.208733,-0.013189,0.146127,0.051169,0.515107,0.052605,0.089357,0.038349,-0.257502,-0.345860,0.187667', '2369613', '1306809', '4014397', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308753', '公主日记2', '喜剧', '公主米亚（安妮•海瑟薇 饰）大学毕业后再次回到了吉诺维亚。公主的到来轰动了全国，米亚也为此十分兴奋。可是，在一次皇家听证会上，大法官宣布公主必须成婚了才能继承王位。米亚必须在30天内订婚，否则她就不得不让出王位。王后（茱莉•安德鲁 饰）只好与助手们匆忙地帮米亚挑选夫婿。几经选择，米亚终于跟一个年轻帅气的贵族男子订婚。与她争夺王位的年轻男孩尼可拉斯（克里斯•派恩 饰）跟米亚之间却有了说不出的情愫，男孩的姨丈想让尼可拉斯勾引米亚，让她在一个月内无法完婚，两个年轻人之间却产生了真感情。©豆瓣', '安妮·海瑟薇', '盖瑞·马歇尔', 7, 155682, 'tt0368933', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1358441454.jpg', 0.6, 6, 49.4, 32.8, 11.2, '0.171014,0.117238,-0.477824,0.602332,0.041245,-0.855615,0.556093,0.110442,-0.469103,-0.100009,0.301454,0.700149,-0.356675,0.206281,0.555941,0.332385,-0.680330,-0.523816,0.184742,-0.230428,-0.128441,-0.619580,0.014244,-0.056885,-0.354298,-0.592686,0.802081,-0.343346,0.320496,0.373532,0.388703,0.106515,0.158488,0.403399,0.180194,-0.146139,0.486963,-0.115779,-0.284110,0.391885,-0.051487,-0.148253,-0.198024,0.404330,0.362968,0.222881,0.215406,-0.524866,0.454067,-0.127387,0.298897,-0.049784,0.005470,0.395906,-0.091906,-0.235438,0.425341,0.297517,-0.448335,-0.433737,0.186797,-0.163063,-0.105702,0.424368,0.012099,0.200086,-0.767675,0.340363,-0.347298,-0.337118,0.380466,-0.381765,0.141092,0.568915,0.090825,0.298835,-0.134670,0.171437,-0.605487,-0.384853,0.497477,0.240031,-0.300964,-0.076554,-0.071980,-0.575185,0.092504,-0.160653,-0.587254,0.009658,0.403872,0.034008,0.172696,0.493768,-0.421947,-0.355435,-0.920121,-0.112969,0.310053,-0.575843,0.029275,-0.394514,0.047077,-0.323090,-0.438719,-0.153956,0.469084,-0.183892,0.679951,-0.910804,0.257677,0.358195,0.359315,-0.472960,0.338514,0.351063,0.417066,-0.252772,-0.204249,0.196738,-0.216484,0.277451,0.097814,0.377676,0.047909,-0.129964,-0.336540,0.583873', '6875263', '1304646', '26593587', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308754', '天空上尉与明日世界', '动作', '这是一部科幻动作片。在将来的某一天，纽约遭到了不明来历的攻击，天空上尉飞行员约瑟夫•苏立文（裘德洛饰）收到求救信号出手相助，在经过激烈的较量后，纽约迎来了暂时的平静，天空上尉也在这次战斗中偶遇并且救下了身为记者的旧情人波莉(格温妮斯•帕特洛饰)。原来波莉所调查的事件和这次袭击有着千丝万缕的联系，背后有一个巨大的阴谋。为了迎接即将到来的恶战，保卫世界，他们向海军女子特谴队队长弗兰姬•库克(安吉莉娜•朱丽饰)和技术专家戴克斯(吉奥瓦尼•瑞比西饰)寻求了帮助。一场正义与邪恶的较量揭开了序幕……©豆瓣', '格温妮斯·帕特洛', '克里·孔兰', 6.6, 10439, 'tt0346156', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p968810651.jpg', 1.9, 12, 49.9, 27.6, 8.6, '0.065168,-0.135484,-0.668513,0.484092,0.391506,-0.136103,0.520221,0.018425,-0.409985,-0.364820,0.479009,0.627162,-0.281982,-0.284798,0.710347,-0.197376,-0.552338,-0.671523,0.011465,-0.150763,-0.349206,-0.470863,-0.593857,-0.094333,0.263661,-0.611341,0.625626,0.185515,-0.362464,0.772612,0.342437,0.537425,-0.243877,0.394543,0.143339,-0.217525,0.237934,-0.055935,-0.624047,0.388760,0.051539,0.063853,-0.131877,0.106173,0.045544,0.418199,0.525761,-0.408067,0.180372,-0.013234,0.123795,-0.319409,0.343383,0.149024,0.395414,0.046498,-0.058760,0.290252,-0.063968,-0.093271,-0.002219,-0.206749,-0.719065,0.049963,-0.108809,0.347324,-0.382311,0.428789,-0.212160,-0.096486,0.201244,0.077724,0.267891,0.806841,0.374536,0.186244,0.054122,0.040737,-0.340172,-0.128707,0.614151,0.143494,-0.006188,0.170932,-0.054821,-0.266636,-0.068336,-0.144709,-0.377053,0.112574,0.562548,-0.163360,0.077010,0.418916,-0.776395,-0.186516,-0.496112,-0.057803,0.058548,-0.353129,-0.030802,-0.952804,-0.181047,-0.130331,-0.205819,0.063145,0.059389,-0.004221,0.645550,-1.019374,0.233502,0.445576,0.364456,0.006400,0.454249,0.154506,0.097273,-0.354748,-0.115942,0.044935,0.229996,0.249292,-0.009747,0.208845,0.193282,-0.205356,-0.105574,0.042875', '20274039', '11541282', '2369613', '1293656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308755', '僵尸肖恩', '喜剧', '肖恩（西蒙·佩吉 Simon Pegg 饰）事业不如意，爱情也不怎么顺心。认识了一帮同样游手好闲的朋友，整天和他们厮混，包括皮特，和只会打机和讨人厌的艾德。难得肖恩为了女朋友振作一次，却遭到同事嘲笑，女友也不能会意，肖恩只有继续和朋友醉酒纵乐。但这天整个城市却有了翻天覆地的变化。僵尸入侵了，只要是被他们咬到的人，都会随之变成僵尸。而肖恩正和艾德在酒吧里豪饮，却发现陷入僵尸的重重包围中。现在肖恩必须拿出英雄气概，去捍卫家人朋友。©豆瓣', '西蒙·佩吉', '埃德加·赖特', 7.7, 190613, 'tt0365748', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1429482773.jpg', 1, 3.8, 27.8, 46.3, 21.1, '0.420346,-0.355209,-0.657473,0.308792,-0.295706,-0.471481,1.065497,0.120399,-0.627347,-0.190688,-0.078023,0.755834,-0.240507,0.220775,0.281758,-0.182440,-0.388885,-0.744478,-0.002128,-0.055150,-0.205994,-0.347547,-0.395534,-0.449942,-0.079930,-0.311556,0.437088,-0.070470,-0.176605,0.581099,0.238910,0.239672,-0.116097,0.745321,-0.214575,0.128170,-0.077929,-0.021040,-0.296751,0.033565,0.192164,-0.095741,-0.213005,0.286687,0.308901,0.337597,0.501725,-0.292163,-0.138943,-0.042151,-0.044295,-0.362745,-0.152422,0.092539,0.311864,-0.221214,0.586958,0.124201,0.132142,-0.021453,-0.104625,0.031839,-0.582908,0.128168,0.121779,0.275761,-0.491408,0.634566,0.219007,-0.193973,0.135742,-0.193134,0.248384,0.226729,0.278267,0.343217,-0.036716,0.039672,-0.659839,-0.087466,0.919568,0.121816,-0.081104,0.353643,-0.132258,-0.269717,-0.136431,-0.252888,-0.500547,-0.107628,0.104417,0.086174,-0.223179,0.332013,-0.524762,0.051773,-0.054926,-0.113663,0.004935,-0.514215,-0.028032,-0.476884,-0.108826,-0.497661,-0.268726,0.243252,-0.083668,-0.216343,0.574772,-1.199802,0.211158,0.459923,0.415471,-0.547179,0.705492,0.090199,-0.025833,-0.211737,0.007034,-0.022130,0.245157,0.279037,0.364449,0.121754,0.065594,-0.238866,-0.115920,0.462767', '1296370', '25721544', '35030151', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308757', '鲨鱼黑帮', '喜剧', '在大洋深处的南礁，以大白鲨里诺（罗伯特•德•尼罗 Robert De Niro 饰）为首的鲨鱼黑帮横行霸道，不可一世，其他鱼类对他们又恨又怕，时刻希望有人（鱼？）出来主持公道，消灭这群恶棍。里诺虽然邪恶，不过却格外疼爱他的儿子弗兰奇（Michael Imperioli 配音）和兰尼（杰克•布莱克 Jack Black 配音）。与凶暴的父亲和哥哥不同，兰尼心地善良，平易近鱼，甚至还是个素食主义者。吊儿郎当的清洗店小职员奥斯卡（威尔•史密斯 Will Smith 饰）欠下老板钱财，债台高筑。被五花大绑的他遭到弗兰奇的追杀，而弗兰奇却被突然出现的铁锚砸死。喜好吹牛的奥斯卡因此宣称弗兰奇死于他之手，他还间接和兰尼成为朋友。然而，这却引起鲨鱼黑帮的愤怒……©豆瓣', '威尔·史密斯', '毕鲍·鲍格朗', 7.1, 42169, 'tt0307453', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2249253977.jpg', 0.6, 4.8, 45.3, 38.8, 10.6, '0.156813,-0.134821,-0.581149,0.378301,-0.211341,-0.379286,0.964890,0.153466,-0.239111,-0.007677,0.242328,0.628174,-0.029473,0.165537,0.103440,0.072645,-0.109585,-0.322474,0.023573,0.032234,0.157503,-0.206359,-0.444599,-0.226153,-0.034940,-0.158596,0.421862,-0.030993,-0.235453,0.437665,0.430474,0.376974,0.012640,0.542068,-0.164075,0.188585,0.069015,-0.194869,0.101424,-0.109253,-0.170523,-0.097033,-0.061168,0.349149,0.019181,0.565298,0.394750,-0.318646,-0.087239,-0.294625,0.160504,-0.546823,0.136463,0.286413,0.312954,-0.248270,0.231657,0.035868,0.103447,-0.151691,0.138815,0.063761,-0.784167,0.098022,-0.168227,0.183547,-0.390767,0.251680,-0.148042,0.245428,-0.023990,-0.108164,-0.068622,-0.199102,0.149237,0.312258,-0.183206,0.244142,-0.645215,-0.167360,0.520387,-0.108786,-0.148564,-0.076811,-0.085493,-0.343724,0.369360,-0.481265,-0.321555,-0.155857,0.457356,-0.336642,-0.081005,0.372009,-0.619481,-0.149482,-0.241860,-0.106977,-0.081749,-0.246291,-0.238109,-0.547464,0.070436,-0.410676,-0.212768,-0.034519,0.200141,-0.143461,0.680118,-0.628506,0.074034,0.592657,0.295813,-0.497085,0.381071,0.073628,-0.029900,-0.087923,-0.506991,0.230767,0.634117,-0.043968,0.273724,0.119928,0.118436,-0.332246,-0.088661,0.488482', '3005387', '1301686', '1293515', '1298442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308762', '借刀杀人', '剧情', '夜幕低垂，麦克斯（杰米·福克斯 Jamie Foxx 饰）接了一位注定要改变他人生的客人――文森特（汤姆·克鲁斯 Tom Cruise 饰）。文森特受雇于一家跨国贩毒集团，这晚来到洛杉矶要干掉五名重要证人。他与我们经常看到的杀手大不一样，他天生喜欢唠叨，在他挟持 麦克斯去帮他完成杀人工作时，还振振有词――“我又不是卢旺达大屠杀，我杀人本来就不是好人，可以说是替天行道，你有什么可以指责我的？”麦克斯也一时语塞。这晚要杀的最后一个人是助理检查官，她曾是麦克斯的顾客。麦克斯决心保护她……©豆瓣', '汤姆·克鲁斯', '迈克尔·曼', 7.5, 62429, 'tt0369339', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2160803474.jpg', 0.4, 3.1, 33.8, 47.5, 15.2, '0.187144,-0.079727,-0.381342,0.244439,-0.642792,-0.253384,0.731166,0.069341,-0.327501,-0.128512,0.176741,0.809234,0.130156,0.166545,0.168339,0.362448,-0.274161,-0.426278,0.352629,-0.010259,0.056920,-0.657133,-0.175407,-0.548195,0.082779,-0.162899,0.177709,-0.027177,-0.275963,0.031013,0.479325,0.189662,0.142481,0.462079,-0.349281,-0.116056,-0.024293,-0.180386,-0.342615,0.296672,0.028193,-0.172341,-0.327957,0.324443,0.166800,0.475259,-0.080581,0.191172,-0.065744,0.140135,0.145003,-0.540299,-0.016848,0.097606,0.062686,-0.455566,0.007451,0.231491,-0.094754,-0.151413,-0.050341,0.009296,-0.766444,-0.044022,-0.013413,0.154459,-0.623228,0.365118,-0.303518,0.130241,0.115055,-0.198488,0.127306,0.132642,-0.001065,0.196543,0.397466,-0.136757,-0.839307,0.445595,0.958109,0.019518,0.195749,0.184338,0.096737,-0.259210,0.066829,-0.136106,-0.303539,0.116494,0.203798,-0.441030,-0.238280,-0.198758,-0.308550,-0.306739,-0.234430,0.021006,-0.235159,-0.500099,0.182333,-0.233821,0.282412,-0.268049,-0.319018,0.075068,0.017447,-0.295189,0.467655,-0.996137,0.224388,0.821439,0.416765,-0.625482,0.716157,0.485250,-0.088941,-0.313281,0.065256,-0.080580,0.153025,0.141508,0.199035,0.143133,0.697630,-0.153208,-0.051579,0.229424', '1308755', '1877596', '25721544', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308763', '温布尔登', '剧情', '温布尔登是英国有名的网球公开赛，这里的选手呈现着网球的最高水平和精彩战况，是网球选手施展拳脚的绝佳舞台。梦想着在温布尔登实现网球事业巅峰的，还有片中的男主角彼特（保罗·贝坦尼 Paul Bettany饰）。无奈温布尔登的辉煌不是轻而易举就能收归囊下，他像无数怀揣着梦想来到这里的选手那样，终究要黯淡离去，现在他正准备作收山一战，怎料事情来了个峰回路转。来自美国的种子选手利兹（克尔斯滕·邓斯特 Kirsten Dunst饰）有着优异的成绩和漂亮迷人的相貌身材，有着与众不同的个性，深深吸引着彼特的心。爱情的滋润令彼特得到神奇的力量，在赛场上所向披靡，成绩骄人。网球生涯的光明前景在彼特面前徐徐铺开，然而爱情的狂热似乎只为他带来好运，却令到利兹耽于爱情而分了赛场的心。对于利兹来说，放弃原本辉煌的战绩未免牺牲太大，她选择离去。这对因网球结缘的情人，却即将要因网球而分离，除非上天再次给事情一个神奇的转机。', '克斯汀·邓斯特', '理查德·隆克瑞恩', 6.9, 5960, 'tt0360201', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p827502412.jpg', 0.5, 6.4, 51.9, 31.5, 9.6, '-0.118720,0.193031,-0.672155,0.785538,-0.203523,-0.336967,0.580871,0.205755,-0.442263,-0.049094,0.243855,0.701488,-0.197033,0.059165,0.422649,-0.120522,-0.001388,-0.807383,-0.261299,-0.048951,-0.168865,-0.477628,-0.518931,-0.066706,-0.196952,-0.358598,0.851054,0.210329,-0.345184,0.733217,0.374548,0.191601,0.401931,0.060402,-0.210285,-0.278551,0.045552,0.311928,-0.342242,0.224905,0.068802,0.017603,-0.294481,0.288982,-0.110046,-0.024720,0.490765,-0.199437,-0.075629,-0.084584,0.495204,-0.279111,-0.041250,0.169354,0.201096,0.098366,0.008031,-0.183950,-0.104452,0.256971,0.219409,-0.254648,-0.909652,-0.094599,-0.027726,0.208467,-0.460151,0.713471,-0.083833,-0.295351,0.270782,-0.147209,-0.114557,0.046946,0.400486,0.266402,-0.104567,0.058158,-0.318259,0.211585,0.831228,0.055409,-0.353276,0.329384,-0.394374,-0.404427,-0.222843,-0.382880,-0.485546,0.109046,0.380022,0.191829,0.301958,0.320153,-0.373360,0.111378,-0.059525,-0.161845,-0.118370,-0.442328,-0.012687,-0.463428,-0.103284,-0.472754,-0.598427,0.151415,-0.058999,-0.247794,1.035850,-0.986893,0.099509,0.752742,0.110575,-0.181784,0.617865,0.133068,0.161996,-0.115791,-0.433504,0.494733,-0.257517,0.238661,-0.142669,0.427989,-0.029892,-0.298770,-0.482352,0