INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308764', '灰姑娘的故事', '喜剧', '一个现代版的灰姑娘故事。珊曼（希拉里·达芙 Hilary Duff饰）在父亲的童话故事中长大，不料却成为了童话中的灰姑娘。父亲过世后，继母和同父异母姊妹的侮辱和亏待，令她的日子过得苦不堪言。她想考取普林斯顿大学，想逃离这个龌龊的小世界，珊曼把她的梦想和苦恼都诉说给一个亲密的网友，他是她心灵的依托，是她的白马王子。万圣节的相见摧毁了吉娜的梦。眼前的网友，竟然是学校里有名的帅哥运动员奥斯汀（查德·迈克尔·墨瑞 Chad Michael Murray饰）。一个是平凡黯淡的女孩，一个是闪亮耀目的男生。幸好吉娜乔装打扮，没被人奥斯汀认出。二人如此不登对，心虚的吉娜落荒而逃，不小心遗下一部手机。就像玻璃鞋被王子拣到之后的故事，奥斯丁拿着手机寻找自己的灰姑娘，而吉娜，却无法相信自己怎会像灰姑娘般幸运。于是这出爱情故事，注定充满曲折而窝心的波澜起伏。©豆瓣', '希拉里·达芙', 'Mark Rosman', 6.8, 47871, 'tt0356470', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p802390374.jpg', 0.9, 7.9, 52.8, 28.6, 9.7, '0.488467,-0.001328,-0.663128,0.715950,-0.248720,-0.180850,1.019587,-0.064413,-0.470048,-0.035723,0.275041,0.918734,-0.430112,0.361027,0.092003,0.460811,-0.204294,-0.821651,-0.062032,-0.182875,-0.063142,-0.379732,-0.353688,-0.113528,-0.014705,-0.213027,0.541749,-0.041465,-0.068939,0.477416,0.348032,0.058359,-0.010363,0.444850,-0.302149,0.300537,-0.039789,0.371406,0.036804,0.000301,0.055901,-0.037823,-0.016921,0.302504,-0.263137,0.340689,0.509944,-0.338880,0.035762,-0.003353,0.444690,-0.276214,-0.131961,0.273486,0.088905,0.001482,0.184857,-0.218587,-0.123073,-0.094425,0.250132,-0.074354,-0.721427,0.095966,0.219190,0.164381,-0.624673,0.481852,-0.122214,-0.247505,0.299827,-0.147333,0.214794,-0.099200,0.430257,0.624047,-0.025087,0.155459,-0.386188,0.491046,0.507433,0.054850,-0.443834,0.622374,-0.323899,-0.266584,0.090359,-0.237769,-0.841275,0.125911,0.418026,-0.186269,-0.273613,0.265765,-0.505034,-0.024382,-0.417977,0.011260,-0.154592,-0.647932,-0.349609,-0.085934,-0.137735,-0.524368,-0.440740,0.016174,-0.004470,-0.384246,0.894340,-0.695198,0.158955,0.501991,0.220183,-0.289390,0.797136,0.146527,-0.103946,-0.032973,0.150876,0.337729,-0.076593,-0.051652,0.090375,0.357789,-0.055406,-0.060110,-0.638254,0.583479', '26884422', '4847665', '30162520', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308767', '谍影重重2', '动作', '经过上一集的腥风血雨之后，伯恩（马特·达蒙 饰）和女朋友玛丽（弗兰卡·泼坦特 饰）隐居在印度偏僻的海边小镇，想忘记以前的生活。一天，神秘组织的杀手来到小镇，打破了伯恩二人世界的宁静，女友玛丽在逃亡途中被枪杀。为了查出真相，伯恩重新开始战斗，他发现以前工作的中情局开始重新寻找他，自己被卷入了一场刺杀活动中，被人诬陷破坏了中情局的一次情报交易，杀害特工。伯恩别无选择，他只能找到冒充自己的人，才能洗刷清白，为女友报仇。©豆瓣', '马特·达蒙', '保罗·格林格拉斯', 8.7, 329852, 'tt0372183', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p667644866.jpg', 0.1, 0.5, 10.1, 43.4, 45.8, '0.180787,0.048790,-0.549145,0.358976,-0.413429,-0.180956,0.509623,-0.002450,-0.642902,-0.109673,0.333873,0.756790,-0.027168,0.102497,0.596804,0.272510,-0.456727,-0.837971,0.350565,-0.284586,-0.332592,-0.490383,-0.376254,-0.355819,0.124135,-0.322868,0.578896,0.329950,-0.299824,0.195562,-0.026162,0.418676,-0.322546,0.367311,-0.053361,-0.041922,0.393322,-0.268103,-0.391775,0.283466,-0.282144,-0.437655,-0.199564,0.270334,0.028849,0.399319,0.714614,-0.067192,-0.031543,-0.261211,0.272671,-0.400485,0.027876,-0.096175,0.456123,-0.006564,0.396489,0.444625,-0.313105,-0.319608,-0.056773,-0.216787,-0.563714,0.192098,-0.018495,0.057831,-0.605488,0.325031,-0.193101,0.128465,0.077147,-0.301321,0.342654,0.524369,0.548015,0.098096,-0.055677,-0.089171,-0.456482,0.199120,0.889218,-0.221258,0.142635,0.152092,0.272935,-0.067937,0.183191,-0.340534,-0.358053,0.088299,0.446622,-0.247404,-0.430369,0.248761,-0.659430,-0.176554,-0.640604,-0.407290,0.050935,-0.364472,-0.241012,-0.682119,-0.386307,0.296584,-0.219743,-0.106107,-0.181674,-0.323815,0.211427,-0.906884,0.442073,0.829302,0.055352,-0.657807,0.333481,0.069742,0.207756,-0.180459,0.126524,0.420926,0.318177,0.493762,0.130000,0.067695,0.028667,0.040505,-0.431622,0.358144', '30345227', '1293829', '11541282', '1652618');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308769', '异形大战铁血战士', '动作', '2004年，专事搜寻矿藏的PS-12号卫星在南极洲14区探测到不明热源，并发现这里有未知文明的遗迹存在。为了抢在他人之前探明真相，PS-12所属公司老板查尔斯·比绍普·韦兰德（兰斯·亨里特森 Lance Henriksen 饰）随即召集格瑞米·米勒（埃文·布莱姆纳 Ewen Bremner 饰）、艾莉莎·伍兹（桑娜·莱瑟 Sanaa Lathan 饰）等一众科学精英组成探险队，朝着人类从未践足的布维岛挺进。探险队下到地下2000公尺的地洞内，杂糅了各种文明的遗迹令他们目瞪口呆。更令探险队想不到的是，在他们之外来自外星的铁血战士也盯上了这里。他们将和埋藏于此的异形进行宿命的决斗，弱小的人类探险队被迫卷入其中……©豆瓣', '桑娜·莱瑟', '保罗·安德森', 7, 61047, 'tt0370263', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1529816649.jpg', 1.1, 7, 46, 34.1, 11.8, '0.400487,-0.085701,-0.862313,0.498628,0.255726,0.135010,0.582447,-0.297713,-0.506262,-0.203005,0.233408,0.620404,-0.115468,-0.015523,0.213679,0.017795,-0.544677,-0.370366,-0.438693,-0.605358,-0.694700,-0.490921,-0.509312,-0.387491,-0.037077,-0.338179,0.517285,0.243886,-0.336966,0.218456,0.038044,0.669732,-0.455506,0.278236,-0.137203,0.042562,0.398440,-0.182481,-0.279841,0.084024,-0.369628,0.086034,-0.114127,0.171513,0.039620,0.344807,0.547041,-0.648153,0.262922,-0.187703,-0.028956,-0.260135,-0.004749,-0.307716,0.485730,-0.300696,-0.223083,0.136250,0.020807,0.183256,0.226142,0.077790,-0.709810,-0.126272,0.115413,0.319181,-0.208240,0.043928,0.052684,0.124777,0.024044,-0.200891,0.241980,0.365923,0.156247,0.140250,0.215055,-0.092950,-0.500221,0.027276,0.451139,-0.066475,-0.286783,-0.321776,-0.252335,-0.703966,-0.210635,-0.091092,-0.258811,-0.172836,0.386743,0.281082,0.116274,0.487653,-0.910695,0.064385,-0.282468,-0.404761,0.150055,-0.299681,-0.192864,-0.834426,0.024504,-0.224296,-0.134633,0.344253,-0.015867,-0.128437,0.440466,-0.532509,0.204191,0.535894,0.444695,-0.343061,0.696012,-0.422470,0.139574,-0.233756,-0.159260,0.395770,0.450673,0.485088,-0.007721,0.311161,0.161106,-0.152450,-0.384724,0.155266', '1309056', '1298405', '11502973', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308771', '猫女', '动作', '帕蒂恩斯（哈莉•贝瑞 Halle Berry 饰）原本过着平凡满足的日子，她在一家化妆品公司担任美术设计师，是众人眼中潇洒的未婚白领。然而，在这座充满罪恶的城市，厄运正慢慢向帕蒂恩斯袭来。一次偶然，帕蒂恩斯发现了公司的老板乔治（兰伯特•威尔逊 Lambert Wilson 饰）和他的妻子劳雷尔（莎朗•斯通 Sharon Stone 饰）从事的罪恶勾当，随后劳雷尔派出杀手将帕蒂恩斯杀人灭口了。这时，奇迹发生了，帕蒂恩斯曾经救过的一直埃及猫出现了在她眼前，原来这只猫竟然是猫神！猫神为了报答帕蒂恩斯，用魔法将她复活了。帕蒂恩斯复活后发现自己的身体有了巨大的变化，她获得了一股神秘的力量，不仅动作敏捷、触觉灵敏，她还变得身怀绝技。于是，帕蒂恩斯化身为猫女，向这个城市的罪恶宣战。©豆瓣', '哈莉·贝瑞', '皮托夫', 5.9, 27495, 'tt0327554', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p781062466.jpg', 5.1, 21.7, 51.4, 16.1, 5.6, '0.244052,0.036772,-0.648193,0.442992,-0.118553,-0.232742,0.852186,0.090613,-0.656037,-0.247502,0.507244,0.934508,-0.212737,0.177862,0.390823,0.445658,-0.321510,-0.543710,0.047990,-0.105034,-0.122021,-0.318629,-0.525704,-0.163502,0.120536,-0.687991,0.216097,-0.099992,0.213699,0.606861,0.200240,0.152135,0.142050,0.364739,-0.003079,0.150659,0.270625,-0.120746,0.060975,0.295581,-0.023172,-0.208542,-0.288914,0.348013,-0.241064,0.321602,0.455225,-0.257832,-0.022146,-0.429415,0.298141,-0.241785,0.097688,0.179098,-0.090270,-0.258984,-0.019723,0.002725,-0.077255,-0.065124,0.245617,0.023335,-0.615573,0.055457,-0.264947,0.350773,-0.709991,0.271746,-0.493583,-0.134643,0.142985,-0.649860,-0.221964,0.092814,0.156934,0.240447,-0.086694,0.352973,-0.555615,-0.022864,0.394087,0.042969,-0.525708,0.307622,-0.189705,-0.619756,-0.219487,-0.016760,-0.199406,-0.158144,0.344962,0.080020,-0.107234,0.427002,-0.826759,-0.140501,-0.229625,-0.204408,-0.103255,-0.105272,-0.415594,-0.483840,-0.158843,-0.215317,-0.226859,-0.201805,-0.110282,-0.394636,0.367833,-0.822057,0.357906,0.774384,0.138152,-0.072450,0.427974,-0.355697,0.079521,-0.096227,-0.208713,0.205139,0.145473,0.556667,0.339391,0.376251,0.221699,-0.112959,-0.071568,0.703873', '1482077', '1309193', '1309172', '4126925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308772', '环游地球八十天', '喜剧', '19世纪后半期，科技发展持续推动着工业的进步。在伦敦，醉心发明的科学家福格（Steve Coogan 饰）经常进行疯狂的运输工具实验，尽管，他得不到皇家科学院的认可，只是一名业余爱好者，仆人也因过于危险的实验离他而去。来自中国的刘星（成龙 饰）为取回家乡的宝物“玉佛像”，打劫了英格兰银行。招来了英国警方与中国犯罪组织黑蝎集团的无休无止追捕，无奈之下只得化名“路路通”担任福格的仆人。福格为取代古板不堪的科学院院长，赌上全部家当与前途，要在80天内环游世界。而路路通认为可借这次旅行将佛像送回家乡。两人出发后在巴黎遇见痴迷印象派的业余女画家罗切（Cécile De France 饰）要求同行，他们怀着不同的目的乘上“东方快车”号。虽然前路有土耳其王子（Arnold Schwarzenegger 饰）、黑蝎芳将军（莫文蔚 饰）与手下（吴彦祖 饰）的重重拦截，但怀揣梦想的三人不会畏惧任何险阻。', '成龙', '弗兰克·克拉斯', 6.2, 40927, 'tt0327437', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p977243162.jpg', 2.8, 15.8, 56, 19.8, 5.5, '0.191254,0.002987,-0.619520,0.655757,0.099082,-0.207615,0.444632,0.026201,-0.490311,-0.446944,0.267661,0.576259,0.335447,-0.003926,0.319488,-0.126993,-0.308210,-0.398938,-0.087781,-0.182263,-0.191533,-0.567755,-0.175739,-0.328943,-0.251345,-0.295178,0.720077,0.185171,-0.324101,0.613540,0.322364,0.428179,-0.114592,0.186729,-0.168260,-0.336702,0.177531,0.086583,-0.478992,0.280743,0.036612,-0.148292,-0.020765,0.066294,0.076192,0.195668,0.500349,-0.217896,0.066518,-0.165584,0.333086,-0.299742,0.033936,-0.085054,0.243047,0.276515,-0.047053,0.303833,-0.091132,0.072789,0.151138,-0.115037,-0.727119,-0.052475,0.410501,0.079129,-0.713400,0.369292,-0.129187,-0.037847,-0.166593,-0.244067,0.252742,0.353766,0.212910,0.284570,0.085719,0.125876,-0.531166,0.333633,0.660328,-0.133614,-0.117002,-0.024680,-0.185390,-0.339525,0.007635,-0.342065,-0.349246,-0.179414,0.042978,0.036410,0.094680,0.197133,-0.659615,0.130923,-0.302480,-0.121260,0.139215,-0.291032,0.219799,-0.702755,0.208963,-0.349039,-0.105162,0.108836,0.305764,-0.131608,0.693325,-0.661132,0.207038,0.581087,0.393284,-0.544919,0.752874,-0.048335,0.003412,-0.397635,-0.327646,0.233808,-0.043485,0.290552,-0.170096,0.162683,0.140163,-0.433324,-0.259406,0.162073', '1307762', '1793491', '4301278', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308776', '加菲猫', '喜剧', '加菲猫从小到大的生活都沉浸在――高热量的食物，睡觉，捉弄愚蠢的狗狗和主人乔恩•阿卜(布瑞金•梅耶 Breckin Meyer  饰)的宠爱中，加菲觉得这就是完美的生活。直到有一天，乔恩带加菲去宠物医院时，受美女兽医所托领养了小狗欧弟，加菲的生活彻底改变。欧弟的到来意味着要和加菲分享食物和阿卜的宠爱，更让加菲嫉妒的是阿卜和美女兽医约会竟然带欧弟而不带它。加菲恨不得将欧弟赶出家门。一晚，加菲将欧弟关在门外，原只想惩罚一下欧弟，没想到欧弟走失了。阿卜四出寻找欧弟未果。加菲通过调查，得知欧弟被残忍的训狗师捉走了。加菲决定大展身手，只身前往救出欧弟。©豆瓣', '布瑞金·梅耶', '彼得·休伊特', 7.7, 145773, 'tt0356634', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209546367.jpg', 0.3, 2.2, 28.7, 48.2, 20.5, '0.162625,-0.286283,-0.492401,0.366917,-0.207539,-0.168923,0.556476,0.272940,-0.351572,0.030897,0.009164,0.580509,-0.183423,0.366542,0.230841,0.260296,-0.239862,-0.389632,-0.020498,0.103953,-0.204478,-0.231573,-0.019704,-0.234355,0.114555,-0.362353,0.364660,-0.127685,-0.080637,0.543712,0.388857,-0.010435,-0.186576,0.397074,-0.255416,0.248023,0.236238,0.134780,-0.113354,0.091204,0.176223,-0.137573,0.028881,0.112801,0.213119,0.055281,0.547986,-0.250331,-0.139662,-0.191322,0.105171,-0.431865,-0.144108,0.167537,0.012161,-0.062093,0.195008,-0.095773,-0.295607,0.097474,0.172546,-0.141964,-0.630292,0.019383,0.101334,-0.029567,-0.455648,0.265229,-0.028201,0.200143,0.530004,-0.304552,0.175551,0.292993,0.018298,0.589516,0.203870,0.262450,-0.417555,0.082726,0.519078,-0.458760,0.199021,0.249560,-0.128987,-0.271433,0.454797,-0.081147,-0.433991,-0.035702,0.172605,0.208324,-0.446956,0.186646,-0.470637,-0.200295,-0.132849,-0.234434,0.206854,-0.532985,-0.304163,-0.474763,-0.096626,-0.398299,-0.065768,0.057947,0.229988,-0.273284,0.465445,-0.772987,0.402505,0.389046,0.264902,-0.568226,0.839266,0.019443,-0.063451,-0.055037,0.303239,0.126353,0.247648,0.072554,0.406545,0.285835,0.061938,-0.226902,-0.681557,0.360792', '3055049', '1302384', '2990737', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308777', '暖暖内含光', '剧情', '内向沉稳的约尔•巴瑞斯（金•凯瑞 饰）在一次聚会中认识了率真随性的克莱门汀•克罗斯基（凯特•温丝莱特 饰），二人成为情侣。和普通的情侣一样，他们的日子也在甜蜜和争吵中度过。2004年情人节前夕，当约尔精心准备好礼物，为不久前一次争吵找到克莱门汀道歉时，他惊讶地发现，克莱门汀根本都不记得他了。原来冲动的克莱门汀受不了二人交往中争吵的痛苦，到“忘情诊所”，把关于约尔的记忆删除得一干二净。约尔无法原谅克莱门汀的任性，也无法忍受失去她的痛苦，所以他也到了“忘情诊所”，请求医生霍华德博士（汤姆•维尔金森 饰）消除关于克莱门汀的记忆。记忆清除程序开始启动，约尔在自己的记忆中游走，他发现和克莱斯汀一起度过的那些时光，无论是痛苦还是甜蜜，都弥足珍贵，他并不想忘记这个自己深爱的女人。但是，程序一旦启动就无法逆转，约尔只能想尽办法把克莱斯汀藏到记忆最深的地方，那些现实中克莱斯汀本来没有出现过的时间角落，以保存这份爱情……', '金·凯瑞', '米歇尔·贡德里', 8.5, 234082, 'tt0338013', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p479565065.jpg', 0.3, 1.4, 14.2, 42.1, 42, '0.620993,0.134740,-0.817822,0.319282,-0.294267,-0.457001,0.967117,-0.184830,-0.687901,-0.237098,0.035686,0.458485,-0.047237,0.419259,0.282425,0.092422,-0.657427,-0.673573,0.218954,-0.271461,-0.279732,-0.649942,-0.127677,-0.090941,-0.247023,-0.643514,0.406700,0.046600,-0.013761,0.322152,0.069422,0.094547,0.013540,0.514372,0.139914,0.135831,0.187843,0.010997,-0.323332,0.092319,0.186892,0.021548,-0.095448,0.235944,0.184957,0.222393,0.491331,-0.260243,-0.050804,0.333713,0.313890,-0.053560,-0.050978,0.228100,-0.151712,-0.067250,0.323782,0.217418,-0.334813,-0.044514,-0.050287,0.153845,-0.744827,0.187971,-0.084638,0.268461,-0.537396,0.385712,-0.152621,0.164498,0.183257,-0.555086,-0.072218,0.186196,0.535206,0.272034,-0.410284,-0.112654,-0.430540,0.022414,0.739564,-0.121238,-0.339961,0.435325,-0.278304,-0.190038,-0.124016,-0.182101,-0.501947,0.089813,0.172433,0.229433,-0.390172,0.531641,-0.419551,-0.111698,-0.260467,-0.262343,-0.067518,-0.315255,-0.084647,-0.501630,-0.492987,-0.480641,-0.449151,-0.258847,-0.006235,-0.399183,0.468103,-0.620460,0.456873,0.640799,0.237194,-0.107609,0.510704,0.208304,0.104975,-0.326270,0.109128,0.618834,0.021871,0.273518,0.284844,0.434403,0.174528,0.116088,-0.642307,0.585305', '1309172', '1292211', '1291835', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308779', '后天', '科幻', '美国气候学家杰克（丹尼斯•奎德 Dennis Quaid 饰）认为，温室效应正在引发地球的大灾难，北极冰川的融化，会让地球回到冰河世纪那样的劫难。他的提醒并没有引起美国当局的重视，一切都已经太晚：飓风、冰雹、洪水、冰山融化、极度严寒，一系列的地球巨变引发了一场不可挽救的灾难。美国政府组织北纬30度的民众转移到赤道周围，场面一片混乱。更糟糕的是，杰克的儿子，正困在曼哈顿的图书馆里，靠烧书生火来维持体温。大家怎样才能逃过这场灭顶的灾祸？冰天雪地的地球何时才能回暖？©豆瓣', '丹尼斯·奎德', '罗兰·艾默里奇', 8.3, 461992, 'tt0319262', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209602029.jpg', 0.1, 0.8, 15.6, 50.4, 33, '-0.077341,-0.026411,-0.792226,0.250633,-0.011706,0.183575,0.659442,0.085905,-0.286141,0.089550,0.371108,0.556524,-0.484179,0.004676,0.095178,0.066194,-0.254175,-0.516617,-0.318568,0.099331,-0.398944,-0.156547,-0.651425,-0.039288,0.020259,-0.454833,0.554296,0.585334,-0.396322,0.032311,-0.358399,0.072602,0.026008,0.989097,-0.233355,-0.172212,-0.360018,0.217614,-0.446830,0.166731,0.043180,-0.135495,-0.073091,0.493635,-0.159485,0.328942,0.438213,-0.353769,-0.110148,-0.101908,0.665971,-0.834411,-0.133150,0.149838,0.881960,-0.462759,-0.192415,0.074362,-0.001572,-0.001581,-0.077836,0.107468,-0.277562,0.189660,0.096601,0.312670,-0.126419,0.342026,0.104525,-0.036349,-0.191921,-0.001826,0.284580,0.447716,0.192634,0.610771,-0.493316,-0.128793,-0.298955,0.215498,0.922260,-0.203932,-0.748709,0.289546,-0.454612,-0.289794,-0.095771,-0.105123,-0.460914,-0.143030,0.348328,-0.163485,-0.255073,0.821943,-0.665786,0.003995,-0.351370,-0.844709,-0.203358,-0.009276,-0.281141,-0.650467,-0.273362,-0.245698,0.174763,0.016274,0.229997,0.010331,0.498201,-0.262495,0.223649,0.678480,0.111735,-0.074389,-0.101442,-0.114812,-0.087119,-0.113003,0.056277,0.402243,-0.188388,0.721733,-0.087523,0.282715,0.132660,0.193548,-0.035066,0.586406', '26169607', '25786077', '1473795', '2059276');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308784', '狂蟒之灾2', '动作', '故事发生在位于婆罗洲的原始丛林中，比尔（约翰尼·梅辛纳 Johnny Messner 饰）带领着他的探险小队穿行于其中，寻找着一种名为“血兰”的珍稀植物。在记载中，血兰拥有着能够使人长生不老的神秘力量，“几乎从未有人获得过它”的传闻也令血兰逐渐成为了传说。这一次，受一家著名的医药公司所托，比尔一行人决定揭开血兰的神秘面纱。在离目标越来越近的同时，危险也不期而至。血兰的力量没有使人类返老还童，却将一群蛇类变得凶猛而恐怖，为了挪动巨大的身体，它们不得不吃下比以往多达数倍的食物，而此时冒昧来访的人类，成为了它们最好的猎物。一边是丛林中恶劣的生态环境，一边是穷凶极恶的食人恶兽，同伴们一个接着一个的悲惨死去，比尔最终能够自保，并且挽救更多的生命吗？©豆瓣', '约翰尼·梅辛纳', '德怀特·H·里特', 6.4, 27499, 'tt0366174', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1513060022.jpg', 1.6, 11.2, 57.7, 22.5, 7, '0.240784,0.083932,-0.693271,0.878967,-0.085171,0.105391,0.958037,-0.003083,-0.502741,-0.129074,0.258390,0.581398,0.133138,0.211940,-0.173907,-0.167709,0.166727,-0.247010,-0.159664,-0.042823,-0.417515,-0.224650,-0.790817,-0.290437,-0.159236,-0.417024,0.593807,0.287331,-0.368731,0.312774,0.019674,0.295929,-0.088511,0.310527,-0.636425,-0.297048,0.033355,-0.151822,-0.293941,0.418126,-0.023333,-0.186892,-0.144717,0.298209,-0.243659,0.032699,0.616651,-0.662663,-0.277911,-0.196599,0.349314,-0.244630,0.168167,0.070312,0.388373,0.026049,0.158559,0.039926,-0.168698,0.171613,0.148880,-0.017608,-1.262854,-0.045556,0.050507,0.350678,-0.490948,0.217546,0.149868,-0.043713,0.238016,-0.443649,0.181550,0.185404,0.194031,0.195478,-0.147059,-0.088566,-0.587030,-0.082573,0.829439,-0.066497,-0.399660,0.287365,-0.342234,-0.490506,-0.162042,-0.299834,-0.301585,-0.020223,0.438564,0.367031,-0.137596,0.414363,-0.910276,0.229531,-0.182924,-0.430622,-0.013498,-0.067985,-0.365932,-0.445008,-0.104386,-0.339243,-0.186689,0.175815,0.143962,-0.314458,0.909492,-0.588714,0.343050,0.811193,0.117511,-0.338680,0.360460,-0.263600,0.114149,0.099624,-0.330317,0.446790,0.199916,0.448130,0.099290,0.317797,0.029947,0.052532,-0.469728,0.538691', '26667010', '3769423', '1308585', '4820775');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308790', '暗流2：末日天使', '动作', '阿尔卑斯山案件后尼曼警长（让·雷诺 Jean Reno 饰）凭借自己出众办案能力晋升为警察局长。他在拉波迪修道院的墙壁里发现埋着一具尸体，刻画死者身边那些玄奥符号以及发生死者身上奇怪祭礼似乎隐藏着不同寻常含义。年轻警长勒达（伯努瓦·马吉梅 Benoît Magimel 饰）在教堂边发现并救助起一位半死形象酷似耶稣男子时，以为自己遇到只一个宗教幻想狂，但很快就发现这件事和尼曼斯所负责案子之间有着紧密联系。尼曼斯和勒达眼前迷雾重重，直到他们终于发现每一位受害者都有着与基督十二使徒有着同样名字和职业。女警员、宗教史学专家玛丽（卡米尔·娜塔 Camille Natta 饰）帮助下尼曼斯和勒达力图揭穿这起令人难以置信的阴谋的真相。尼曼斯和勒达决心找出所有问题答案，但为此们必须深入冒险去发掘一个已经埋藏了几个世纪秘密……©豆瓣', '让·雷诺', '奥利维埃·达昂', 6.6, 6867, 'tt0337103', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p936349495.jpg', 0.9, 9.5, 54, 28.2, 7.4, '0.033994,-0.070782,-0.596371,0.381092,0.111156,-0.045859,0.895469,-0.170074,-0.333664,-0.666675,0.202504,0.539039,-0.135296,0.161390,0.367397,-0.044578,-0.602750,-0.636144,0.085713,-0.285521,-0.433103,-0.769620,-0.397940,-0.184100,-0.217194,-0.451430,0.454149,0.032242,-0.174537,0.210832,0.188445,0.580818,-0.556391,0.278792,-0.012969,-0.285853,0.426007,-0.346207,-0.103689,-0.118031,-0.064614,0.120631,-0.276910,0.154114,-0.215600,0.248267,0.286930,-0.428794,-0.321177,-0.046594,0.058840,-0.115006,0.033425,0.128156,0.306519,0.056824,0.161804,0.302575,0.098527,-0.153910,0.311235,-0.055544,-0.682899,-0.124281,0.187985,0.550353,-0.284607,-0.124485,-0.130273,-0.089047,0.091963,-0.142768,0.142039,0.105380,0.335521,0.262403,-0.061949,0.015922,-0.594947,-0.313166,0.194005,0.135411,-0.320574,0.121297,-0.221111,-0.339540,-0.082869,0.075395,-0.030146,0.238122,0.143609,0.241023,-0.076741,0.163756,-0.462533,-0.174688,-0.339041,-0.102004,0.009558,-0.203445,-0.042399,-0.581030,-0.415164,-0.064131,-0.467789,-0.166167,-0.012669,-0.140639,0.659029,-0.485560,0.409885,0.378727,-0.051352,-0.141435,0.461724,-0.002422,0.074136,-0.221737,-0.279884,0.233913,0.349558,0.156556,-0.180853,0.394361,-0.112932,-0.222782,-0.314923,0.214497', '1316693', '25909236', '35017064', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308792', '咒怨(美版)', '悬疑', '作为一名来日本念书的美国学生，嘉云（莎拉·米歇尔·盖拉 Sarah Michelle Gellar 饰）一直过着半工半读的生活。这一次，她接受了一份看护患了僵直症的老人艾玛（Grace Zabriskie 饰）的工作。艾玛独自居住在一间大宅里，这里的破败和荒芜充分显示了它和老人被时间遗忘的痕迹，而对于艾玛诡异的行为举止，嘉云也仅仅觉得是她的神经出了问题罢了。随着时间的推移，嘉云感到似乎有某些极为可怕的东西藏在这所房子的阴影中。无人的楼梯上传来声响，长相怪异的男孩忽闪忽现，所有的迹象都指向一点——在这所古老的房子里，她是那个不受欢迎的人。身边的人连遭厄运，这里究竟发生过怎样的故事才导致了如今的咒怨作祟？嘉云决心调查到底。©豆瓣', '莎拉·米歇尔·盖拉', '清水崇', 6.3, 16370, 'tt0391198', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200535582.jpg', 3.2, 14, 54, 20.9, 8, '0.277012,-0.074839,-0.933909,0.559678,-0.136140,-0.073695,1.100633,0.037708,-0.661536,-0.437465,0.243814,0.531389,-0.191297,0.294342,0.120396,0.132877,-0.353933,-0.441574,-0.134526,-0.421970,-0.430788,-0.292375,-0.507669,-0.218518,-0.052191,-0.300266,0.446058,0.284428,-0.199598,0.263885,0.217958,0.223558,0.064559,0.573794,-0.255385,0.004122,-0.006398,0.018184,0.224387,-0.218311,0.176352,-0.427796,-0.104538,0.269286,-0.011205,0.519823,0.662353,-0.303830,-0.281795,0.004953,0.357387,-0.023080,-0.181171,0.130710,0.327435,-0.106771,0.242151,0.129976,-0.395475,-0.034722,-0.126127,0.052396,-0.829108,-0.056101,0.192620,0.370501,-0.507509,0.531414,-0.025850,-0.327099,-0.147080,-0.449735,0.351517,0.156523,0.209572,0.397714,-0.270351,-0.128004,-0.442187,-0.132836,0.685365,-0.061459,-0.410806,0.500587,-0.561149,-0.529517,-0.206779,-0.121050,-0.345954,-0.034296,0.058962,0.083321,-0.350912,0.077216,-0.515681,0.204035,-0.093974,-0.359091,-0.289186,-0.381439,-0.461971,-0.395254,-0.163707,-0.647200,-0.317088,-0.030806,-0.058240,-0.101759,0.647732,-0.795840,0.200175,0.573619,0.238750,-0.201609,0.642864,-0.019750,0.151211,0.049222,-0.328700,0.134522,-0.025007,0.401051,0.096248,0.443283,0.117226,-0.142758,-0.444054,0.574647', '1304862', '1296370', '1417428', '1297996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308797', '救命', '剧情', '风雨交加的夜晚，一场盛大的婚礼正在某豪华星级酒店举行时，突发骇人听闻惨案，伴娘子清（李心洁）成为唯一目击证人。在警署，子清一口咬定疑凶是闭路电视上的神秘人孙玲（林嘉欣）。得知孙玲与自己的男友有着不同寻常的隐情后，因肾脏有问题一直觉得亏欠男友的子清几乎崩溃。子清受到凶徒袭击，幸得孙玲及时出手救援才捡回一命。与孙玲相处时，子清渐生宽恕和感激之心。就在两人的友谊日渐成熟之时，一直逍遥在外的真凶开始向她们逼近。©豆瓣', '林嘉欣', '罗志良', 6.6, 20464, 'tt0408970', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1440717591.jpg', 1.3, 9.4, 54.5, 27.9, 6.9, '-0.072249,0.123749,-0.794376,0.104574,0.426190,-0.144554,0.691591,-0.011137,-0.750081,-0.420992,0.317358,0.529786,-0.504094,0.307300,0.528432,-0.137100,-0.103739,-0.601012,-0.192301,-0.184885,-0.189213,-0.417022,-0.034505,0.106931,-0.095510,-0.262633,0.484386,0.199127,-0.163286,0.514432,0.226052,0.333242,-0.454178,0.553133,-0.150282,-0.200798,-0.097508,0.067863,-0.734168,0.127744,0.289364,-0.088753,-0.179920,0.050035,-0.176008,0.440937,0.538368,-0.169494,-0.560135,-0.079555,0.413074,-0.164246,0.059262,0.202643,0.283942,0.081555,0.414412,0.334567,-0.189571,-0.158946,0.002401,-0.019971,-0.484397,0.063600,0.265011,0.055944,-0.259014,0.222831,-0.185956,-0.172769,0.291943,-0.271231,0.294373,0.469569,0.024935,0.318596,-0.306066,0.189364,-0.430784,-0.259317,0.886602,0.028736,-0.079935,0.329082,0.257875,-0.422387,0.128100,-0.103949,-0.190536,0.299358,0.228377,0.178030,0.002329,0.279795,-0.380094,-0.141010,-0.425624,0.124733,0.125346,0.001996,-0.211601,-0.626298,-0.032074,-0.096134,-0.291605,0.185967,0.107881,-0.441393,0.434190,-0.868908,0.460727,0.403622,0.369382,-0.421404,0.529389,0.130945,0.192099,-0.250150,-0.399801,0.087148,-0.058610,0.211821,0.089434,-0.010603,-0.372561,-0.024705,-0.279969,-0.012589', '25856453', '25721544', '1308755', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308798', '情牵一线', '爱情', '滨海大学的大三女生颜小佳（梁咏琪 饰）暗恋着体育积极分子闻涛（佟大为 饰），一次阴差阳错，她把一个无线电带回了家里，却从一个夜晚传来了呼叫的声音。对方男生说自己叫闻家辉（朱孝天 饰），喜欢玩短波，希望听到的人能回应。两人惊奇地发现彼此就读于同一所大学，约定次日见面。然而二人都沮丧地发现对方失约了。闻家辉被大雨淋了个透彻，质问颜小佳时却令小佳感觉愤怒——当天下午明明没有雨。正当双方都认为对方是骗子的时候，闻家辉发现自己的无线电没有插电……他们开始重新匹配资料，发现他们竟然是横跨了20年的存在！他们的友谊穿越了时空的界限，二人都享受着这难得的缘分，直到一天闻家辉说出了一件事情……©豆瓣', '梁咏琪', '滕华涛', 6.5, 5346, 'tt0406110', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486613467.jpg', 1.7, 11.7, 55.9, 23.5, 7.2, '0.432184,0.038585,-0.901424,0.662448,-0.075451,-0.205925,0.537798,-0.084310,-0.523455,-0.450695,-0.050801,0.480911,-0.616689,0.254919,0.107456,-0.160260,-0.148728,-0.813773,0.147395,-0.271295,-0.291261,-0.402179,-0.084994,-0.063852,0.005905,-0.139872,0.183420,0.167003,-0.105375,0.718669,0.093919,-0.177576,0.097677,0.807537,-0.186601,-0.139652,0.313420,0.354322,0.047262,0.012756,-0.165522,-0.121173,-0.104304,0.298956,-0.129211,0.591147,0.528949,-0.014966,-0.195357,0.298142,0.410842,-0.093124,-0.149299,0.128688,0.438292,-0.033624,0.148621,0.006332,0.049229,-0.129278,0.064766,0.235584,-0.386928,0.192435,-0.213170,0.086694,-0.181673,0.617041,-0.210950,0.060454,-0.059495,-0.315223,0.342260,0.227601,0.361167,0.622139,-0.161811,0.060027,-0.569625,0.056335,0.677802,-0.232605,-0.159035,0.560069,-0.194223,-0.619808,-0.036110,0.155031,-0.350268,0.049340,0.302884,0.325836,-0.379920,-0.036570,-0.420610,-0.013514,0.016140,-0.030805,0.096042,-0.642007,-0.223982,-0.535654,-0.144880,-0.390225,-0.554847,0.339026,-0.242202,-0.246271,0.648867,-0.755225,0.020353,0.531140,0.260409,-0.256574,0.829270,0.174986,-0.166032,-0.260920,0.219396,0.029380,-0.101850,0.323370,0.437823,0.515848,-0.154471,-0.084789,-0.350171,0.330725', '34973399', '3401409', '1292211', '25837574');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308799', '一个陌生女人的来信', '剧情', '1948年的深冬，作家（姜文）在41岁生日的晚上收到一封厚厚来信，此信出自一个濒死女人之手，所言是她对他将近20年的爱恋，但他却一无所知。18年前，13岁的女孩爱上了住在隔壁的作家，因家变搬到了别处后，女孩并没对作家忘情。几年过去，女孩变成女学生（徐静蕾）回到原来的住处，如愿以偿与作家有了交往，但作家对眼前曾住在其隔壁的女学生没有任何印象。作家有事离开，自此音信全无，女学生在绝望的等待中生下她与作家的结晶，并为让孩子过上优越生活变作依附有钱男人的交际花。又过几年，女学生变成女人，再遇她深爱多年的作家时，对方仍没把她认出。©豆瓣', '徐静蕾', '徐静蕾', 7.6, 132670, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2528852561.jpg', 0.8, 3.9, 31.6, 43.9, 19.7, '0.256340,-0.213167,-0.606976,0.249058,-0.448258,-0.169289,0.913323,-0.190652,-0.852888,-0.371752,0.123689,0.798155,-0.311106,0.560870,0.353547,0.035338,-0.111053,-0.665143,-0.045768,-0.464656,-0.221763,-0.337966,-0.018202,0.071177,-0.277922,-0.485514,0.680514,-0.082315,0.205362,0.320119,0.201388,-0.086473,0.049298,0.629504,-0.300633,0.267140,0.016522,0.286254,-0.185151,0.486643,-0.023387,-0.320888,-0.154036,-0.177645,-0.111582,0.165229,0.720942,-0.241431,-0.234182,0.030671,0.567437,-0.089297,-0.451683,0.157676,0.469177,0.024441,0.296208,0.102093,-0.054495,-0.277006,-0.241698,-0.259151,-0.073718,0.137915,0.196084,0.108105,-0.846955,0.740574,-0.179572,-0.022752,-0.116060,-0.596335,0.082676,-0.067625,-0.005153,0.412544,0.010534,0.232502,-0.271524,0.498594,0.643191,0.296394,-0.278888,0.315689,-0.146988,-0.585976,0.036717,-0.334376,-0.721141,0.356122,-0.041303,0.188603,-0.455210,-0.035550,-0.379749,-0.028641,-0.149762,0.056674,0.338602,-0.478337,-0.470872,-0.175106,-0.191721,-0.207911,-0.240201,0.095397,0.335766,-0.502138,0.951489,-1.107000,0.389488,0.349559,0.591538,-0.402724,1.104136,0.045416,-0.147352,-0.203585,-0.070983,0.397113,0.116488,0.270821,-0.078458,0.217449,-0.386210,-0.066086,-0.220852,0.408708', '1302384', '1306544', '3445516', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308802', '汉城大劫案', '动作', '韩国银行被一个五人骗子团伙劫走五十亿元，然而案发当场这个犯罪团伙即有一人身亡，一人被捕。金探长（千浩振 饰）负责此案，他迅速展开对其余三人的调查与追索，案情也随之渐渐浮出水面……刚刑满释放的蔡常赫（朴信阳 饰）策划用银行支票套取韩国银行巨款，为此他找到诈骗老手金先生（白允植 饰），金先生团伙曾经在四年前用计令两位教师倾家荡产身败名裂，不想轻易再出手的金先生被常赫的计划打动，找来老搭档诈骗犯“大嘴”和有暴力倾向的“燕子”，以及伪造票据的高手“汽油”三人，五人团伙正式组成。金先生的情妇徐任晶（廉晶雅 饰）与常赫接触日久生情，两人在金先生眼皮底下暧昧不清。常赫在案发现场身亡后，徐任晶入住常赫之弟常虎的书店中，不知其意欲何为。而此次劫案之所以失败，背后的隐情令人震惊……©豆瓣', '朴新阳', '崔东勋', 7.3, 9789, 'tt0402842', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220124865.jpg', 0.7, 3.4, 38.1, 46, 11.8, '0.073515,0.116954,-0.555827,0.313292,0.157644,-0.117510,0.529569,0.028356,-0.189000,-0.279429,0.124980,0.515223,-0.079702,0.044346,0.395091,-0.339457,-0.018913,-0.632160,-0.197450,-0.314798,-0.260440,-0.748690,-0.150865,-0.183241,-0.090357,0.113673,0.303882,0.224466,-0.133537,0.594862,0.606649,0.496335,-0.529732,-0.007767,0.206785,-0.155320,0.260995,0.176045,-0.418848,0.287099,0.027491,-0.249256,0.119393,-0.174578,-0.012520,0.385441,0.566533,-0.011038,-0.132485,-0.046561,0.341733,-0.131620,0.035231,-0.092662,0.407052,0.131336,0.400158,0.301979,-0.377978,-0.204474,0.280906,0.079184,-0.703984,-0.007986,0.069199,0.144553,-0.358017,-0.181101,-0.210883,0.181744,-0.126529,-0.093576,0.005410,0.590255,0.310842,-0.169477,0.053472,0.080549,-0.531508,0.251916,0.383003,0.053199,-0.033330,-0.106829,0.278579,-0.477923,0.062843,-0.034020,0.132643,0.131344,0.516877,-0.180850,0.103857,-0.082930,-0.513059,-0.271793,-0.260551,0.221644,0.143942,0.068096,-0.001823,-0.521162,-0.225776,-0.012684,-0.206051,0.161488,0.295340,-0.047779,0.295237,-0.513697,0.081707,0.235979,0.297852,-0.526255,0.493254,0.054864,-0.029056,-0.221262,-0.196638,-0.365348,0.612641,0.319763,0.427875,0.024742,-0.017230,-0.316265,-0.056512,-0.203063', '1307442', '26747274', '26678784', '1867408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308803', '大佬爱美丽', '喜剧', '洪一是黑帮老大，对儿子Georgie（吴彦祖 饰）又爱又恨——因为他的身上有一个不能告人的秘密，这个秘密将严重影响到自己的江湖地位。无奈下洪一让Georgie离港生活。直到洪一过世，Georgie终于得以回港。他的室友Sam（陈奕迅 饰）对Georgie非常佩服，因为Georgie追女仔屡试不爽，人又风度翩翩，Sam立志要成为有出息之人。终于机会来到了。洪一亲信把Sam误当Georgie拉回香港，百般保护这个“继承人”。Sam玩世不恭的态度令他们非常苦恼，而Georgie也乐得清静，不去揭穿这个秘密。Sam傻人有傻福，屡次打破对头的奸计，还恋上了对头的女儿Julie（莫文蔚 饰）。然而事情真的有那么平静顺利吗？©豆瓣', '吴彦祖', '冯德伦', 6.2, 13593, 'tt0407708', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p946825030.jpg', 2.4, 14.1, 57.7, 20.6, 5.2, '-0.077843,0.013264,-0.621273,0.559400,-0.223491,-0.100762,0.590387,0.148597,-0.836809,-0.153686,0.075123,0.741116,0.075250,0.226570,0.235974,0.131364,-0.174459,-0.591764,0.228747,-0.330317,-0.147085,-0.438548,-0.284769,-0.256722,-0.262809,-0.231596,0.501762,0.228365,-0.105283,0.321425,0.437625,0.407996,0.147072,0.736082,-0.313907,0.028096,-0.052846,0.246245,-0.104252,0.042072,0.143523,-0.299916,0.049748,0.443461,-0.046072,0.316538,0.374263,-0.174632,-0.615630,0.029742,0.272235,-0.586755,-0.266657,0.149794,0.228364,-0.221716,0.105429,0.216179,-0.321023,-0.089870,-0.018800,-0.012966,-0.804052,-0.032835,0.272102,-0.088674,-0.448743,0.342218,-0.155561,-0.270762,-0.183864,-0.236902,0.359236,0.359004,0.436427,0.290636,-0.326580,0.315084,-0.409139,-0.106527,0.662110,-0.082358,0.120135,0.340081,-0.022620,-0.324824,0.208779,-0.693353,-0.428113,0.020523,0.131234,0.158103,-0.132154,0.121973,-0.276868,-0.055887,-0.059885,0.140081,-0.015772,-0.684289,0.168059,0.033425,-0.272868,-0.313640,-0.275109,0.181805,-0.033568,-0.459720,0.825795,-0.869120,0.214677,0.474619,0.337046,-0.864433,0.559939,0.325859,0.005048,-0.427000,-0.155308,0.198755,-0.015548,-0.025193,0.011398,0.185921,-0.095482,-0.597736,-0.108625,0.241068', '1877596', '1308805', '11525705', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308804', '我脑中的橡皮擦', '剧情', '秀真（孙艺珍饰）是一个富家女，跟男友出走却被抛弃，在便利店内与在建筑公司当工人的哲洙（郑宇成饰）相遇。未来的日子里，他们一次又一次相遇，最终彼此相爱了。哲洙知道自己与秀真的身份悬殊，所以不敢轻易表白情谊，秀真向哲洙求婚。就算秀真父母阻拦，他们爱情的力量还是说服了父母。婚后生活甜蜜，秀真还帮忙修复了哲洙与母亲的关系。可是好景不长，秀真的记忆力开始一天比一天衰退，得了阿滋海默氏症，大脑在逐渐死亡。病魔深深折磨这相爱的两人，秀真有完全忘记一切的一天，可是哲洙却无法从此丢下秀真。他们的爱，能帮他们跨越记忆的考验吗©豆瓣', '郑雨盛', '李宰汉', 8, 245326, 'tt0428870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1198204419.jpg', 0.3, 2.2, 23.3, 46.4, 27.8, '-0.189839,0.023557,-0.604330,0.368279,-0.104527,-0.529770,0.702212,-0.016026,-0.388983,-0.245879,0.016294,0.731183,-0.142457,0.411267,-0.031214,-0.146996,-0.219852,-0.791800,0.410267,-0.099390,-0.273028,-0.503701,-0.081214,-0.176699,-0.111422,-0.289198,0.683464,0.249305,-0.143127,0.288843,0.138138,-0.044750,-0.185389,0.460364,-0.217586,0.063380,0.053189,0.487255,-0.687607,0.026338,0.158965,-0.135589,-0.089658,0.210394,-0.128117,0.144598,0.453303,-0.171945,-0.339513,0.038374,0.320131,-0.186111,-0.268838,0.228757,0.250337,-0.140315,0.355883,0.343568,-0.325605,-0.111848,-0.073998,0.110957,-0.632133,0.028070,-0.011345,-0.049889,-0.648177,0.576193,0.098094,-0.084454,0.012414,-0.225807,0.129330,0.420775,0.431914,0.427362,-0.545801,-0.201936,-0.442486,-0.025988,1.217079,-0.123757,-0.165213,0.696095,-0.236661,-0.179419,-0.182559,-0.089598,-0.674165,0.315715,0.068944,0.277958,-0.412107,0.369224,-0.447122,-0.129539,-0.405457,0.132611,0.055492,-0.585604,0.274039,-0.286670,-0.322387,-0.513880,-0.432760,0.347172,-0.020799,-0.419249,0.530648,-0.715700,0.201950,0.445331,0.626000,-0.778662,0.798014,0.512796,-0.077719,-0.177527,0.185134,0.331368,-0.233150,0.060649,0.409251,0.206620,0.212585,0.297450,-0.356450,0.400990', '25721544', '4145476', '4728584', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308805', '绝世好宾', '喜剧', '亿万富豪万国立请来了曾是警队中精英的陈志杰（刘青云饰）来保护他的独生女儿Jennifer（梁咏琪饰）。由于Jennifer不喜欢有人监视她，所以志杰必须假扮成一个服侍Jennifer的菲律宾男佣Mario从而得到丰厚的酬劳。与Jennifer相处的过程中，志杰发现她是一个非常单纯的女孩子，身边没有朋友，全部都是冲着她的钱来的，她每天更是挥霍无度。因此她的父亲万国立决定以病重及破产为理由，以欺骗女儿，好让她学会自立更新。Jennifer刚开始搬到一般草根阶层居住的小区时，非常不习惯，当她困于生活，需要样样亲历亲为的时候，她发现了父亲白手起家的不容易，她誓要把病重的父亲治好，努力挣钱。她与Mario同共患难，彼此间有了深厚的感情，当她知道原来一切都是好心欺骗她的时候，她也正好面对了自己对志杰的感情。©豆瓣', '刘青云', '阮世生', 6.3, 8620, 'tt0431733', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486578505.jpg', 2.3, 13.3, 56.9, 20.7, 6.8, '0.158156,0.005607,-0.728683,0.600524,-0.500969,-0.150020,0.496916,0.025687,-0.614141,-0.315334,0.127172,0.723157,0.293017,0.227407,0.127249,0.089698,-0.008237,-0.604691,-0.087995,-0.098436,-0.289434,-0.375435,-0.291830,-0.261855,-0.443282,-0.206484,0.320776,-0.038372,-0.074637,0.208044,0.089555,0.230043,0.453056,0.518974,-0.293435,-0.076404,-0.134268,0.064968,-0.090841,0.067564,-0.014571,-0.278786,-0.118200,0.252511,0.223601,0.515821,0.374963,-0.107470,-0.266005,-0.143842,0.385847,-0.246759,0.028370,-0.011218,0.110740,-0.018593,0.383555,0.246750,-0.427866,0.023685,-0.069707,-0.231221,-0.920245,-0.178443,0.327141,-0.111245,-0.759052,0.355750,-0.099403,-0.160210,0.107828,-0.379290,0.132067,0.405638,0.062499,0.311583,-0.160597,-0.085198,-0.640667,0.455204,0.933807,0.004456,-0.094400,0.462918,-0.270785,-0.240116,0.252162,-0.524582,-0.539050,0.035097,-0.007701,0.020290,-0.266089,0.048708,-0.240980,-0.196196,-0.160558,-0.105587,0.123985,-0.608356,0.088013,-0.105895,-0.252229,-0.578012,-0.360153,-0.035255,-0.088042,-0.564418,0.764216,-1.037923,0.150366,0.543885,0.444040,-0.906855,0.835598,0.265372,0.029829,-0.129335,-0.033051,0.004901,0.038442,0.243786,0.138820,0.113371,0.206448,-0.055497,-0.320609,0.530215', '1877596', '1303112', '5985887', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308806', '情归新泽西', '剧情', '26岁的青年安德鲁（扎克·布拉夫 Zach Braff 饰）独自在洛杉矶打拼9年，他志愿成为一名演员，不过时至今日仍默默无名，平常依靠在餐馆打工维持营生。一通电话，将安德鲁带回阔别已久的新泽西老家。多年来，他因某些原因与家人绝少联系，常年服用抗抑郁药物又使得他对周遭的一切都漠不关心，即便如今日，瘫痪多年的母亲意外去世。在故乡，他重新见到身为精神科医生的父亲以及当年的狐朋狗友，一切似乎没变，一切有发生了很大改变。在父亲的建议下，安德鲁前往医院诊疗困扰自己多时头痛，却在此结识了美丽但有些神经质的女孩萨曼（娜塔莉·波曼 饰），有如死水的绝望生活由此发生了转变……©豆瓣', '扎克·布拉夫', '扎克·布拉夫', 7.4, 7420, 'tt0333766', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p776138967.jpg', 0.7, 3.9, 36.2, 43, 16.2, '0.064913,-0.055983,-0.596316,0.197698,-0.232114,-0.278155,0.724196,0.055204,-0.824382,-0.620591,0.145281,0.794879,-0.131513,0.416730,0.150697,-0.118783,-0.158554,-0.567657,0.091578,-0.073000,-0.051331,-0.425023,-0.379743,-0.142165,-0.148864,-0.605888,0.371307,-0.039946,0.130965,0.396399,-0.092642,0.256719,-0.033158,0.479742,-0.027881,-0.080448,0.063508,0.148607,-0.243240,0.075040,0.175732,-0.376488,-0.187784,0.163401,0.177787,0.468838,0.426149,0.062029,-0.504221,0.016017,0.361421,-0.060782,-0.132300,0.100985,0.338108,0.018783,-0.046576,0.237794,-0.429798,-0.288566,-0.089986,0.067748,-0.430745,0.020319,0.104454,0.251203,-0.725708,0.606977,-0.059838,-0.049936,-0.124977,-0.500240,0.146256,0.539309,0.113362,0.424611,-0.098767,0.156474,-0.327156,0.323724,0.950309,0.013980,-0.557832,0.307685,-0.361551,-0.192586,0.026966,-0.202634,-0.543619,0.126540,-0.047643,-0.028995,-0.259924,0.406611,-0.143529,-0.069592,-0.399174,-0.260283,0.090575,-0.095529,-0.184243,-0.448742,-0.138881,-0.327319,-0.293310,-0.079140,0.157511,-0.288834,0.584201,-0.923312,0.405198,0.309841,0.023100,-0.605882,0.625115,-0.004667,0.152721,-0.280813,0.020693,0.646389,-0.030758,0.262712,-0.016967,0.025515,-0.098203,0.222902,-0.288685,0.361986', '25721544', '35030151', '1308755', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308807', '哈尔的移动城堡', '动画', '继母因无力负担生活，将苏菲和她的两个妹妹都送到了制帽店去当学徒。两个妹妹很快先后就离开了制帽店去追寻各自的梦想，只有苏菲坚持了下来。一天，小镇旁边来了一座移动堡垒，传说堡垒的主人哈尔专吸取年青姑娘的灵魂，所以小镇的姑娘都不敢靠近。一个恶毒的巫婆为了报复苏菲与哈尔见面，用巫术把她变成了一个80岁的老太婆，而且苏菲还不能对别人说出自己身中的巫术。无奈，苏菲决定独自一人逃离小镇。天黑了，虚弱的苏菲没走多远，来到了移动城堡。心想自己已经是老太婆了，苏菲壮着胆子走进了城堡。不想，遇到了和她遭遇相同的火焰魔。两人约定彼此帮助对方打破各自的咒语……©豆瓣', '倍赏千惠子', '宫崎骏', 9.1, 944363, 'tt0347149', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2174346180.jpg', 0.1, 0.4, 6.3, 29.8, 63.4, '0.414914,0.094354,-0.597171,0.514190,-0.305775,-0.321011,0.852529,0.154473,-0.420731,-0.056140,0.461261,0.726556,-0.038791,0.167523,0.068840,0.122605,-0.119770,-0.367178,0.131750,-0.335292,-0.321910,-0.426295,-0.056521,-0.195332,-0.114145,-0.318223,0.364693,-0.044556,-0.037592,0.231463,0.217730,-0.103735,-0.168898,0.431220,-0.351775,0.172789,0.117479,-0.237139,-0.020219,0.444440,0.023225,0.142957,-0.105944,0.149993,-0.168046,0.265136,0.753851,-0.124675,-0.022781,-0.219003,0.097442,-0.133245,0.013076,0.193276,0.156542,-0.241474,0.242337,-0.008429,-0.282066,-0.011280,-0.082922,0.139176,-0.342923,0.455457,0.079540,-0.067474,-0.983460,0.355190,-0.038984,-0.126894,0.109326,-0.461690,0.134344,0.341017,0.317696,0.211070,-0.267770,0.042342,-0.659304,-0.244726,0.541042,-0.212652,-0.234550,0.475414,0.073913,-0.172512,-0.104852,0.034654,-0.486620,-0.150766,0.309337,0.107973,-0.459744,-0.047523,-0.778031,-0.126223,-0.565720,-0.245589,0.322848,-0.365955,-0.097073,-0.443063,-0.034072,-0.053147,-0.171619,0.128791,-0.182743,0.016508,0.641308,-0.597244,0.306926,0.563887,0.601825,-0.418836,0.539456,-0.138345,0.079576,-0.261529,0.193416,0.424089,-0.200081,0.730756,0.384574,0.490715,0.050447,0.206654,-0.360153,0.660468', '21619567', '1299965', '1578663', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308808', 'S日记', '喜剧', '每次恋爱智妮（金善雅 饰）都会全身心投入，可是在她面临第4次失恋的时候，她的男友却表示从来没有爱过她。伤心不已的智你回想着自己前三次的爱恋，从初恋开始。她的日记里都记载着她的一个个的恋爱故事。她不断想，所有的男友都真的没有爱过她吗？为了确定这个问题，她找到了前男友们。但那些男孩子们都不再是她记忆中的样子了，一张张曾经熟悉的面孔，都否定了智妮曾经的爱。日记还在，与前男友的记忆也在，智妮默默流泪，她心又不甘，她根据自己的日记，向前男友们各人写了一封“索赔信”……©豆瓣', '金宣儿', '权宗官', 7, 6045, 'tt0426196', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2232880534.jpg', 0.9, 6.3, 46.5, 34.3, 12, '0.136317,0.062630,-1.012396,0.960353,-0.211377,-0.428843,1.029160,-0.441725,-0.295866,-0.202042,-0.004151,0.624836,0.022614,0.766453,-0.156551,0.146171,-0.161073,-0.943771,-0.057563,-0.254099,-0.306837,-0.362761,-0.220923,-0.141842,-0.118236,-0.213741,0.523628,-0.112216,-0.141128,0.060101,0.335529,-0.013674,0.211775,0.596303,-0.261556,0.437431,-0.086389,0.392809,0.190028,-0.275176,0.241209,-0.366710,-0.414012,0.540233,-0.062199,0.499572,0.779167,-0.301787,-0.339990,0.408564,0.369200,-0.098305,-0.177859,0.331008,0.050901,0.012790,0.252534,0.205661,-0.039516,-0.006500,0.085675,0.265759,-0.929910,-0.411719,-0.086778,0.406912,-0.648395,0.556234,-0.383751,0.336340,0.148530,-0.378321,0.141219,0.095953,0.102552,0.287054,-0.400522,-0.236107,-0.344242,0.829410,0.705971,0.240765,-0.172853,0.635579,-0.417842,-0.406406,-0.260958,0.092187,-0.828718,0.338682,0.098485,0.090779,-0.615312,0.258843,-0.556582,0.145854,0.023735,-0.358903,-0.047602,-0.342241,-0.035911,-0.218454,-0.407699,-0.496947,-0.563220,-0.110290,-0.211482,-0.434464,0.900166,-0.737005,0.412226,0.569984,0.040689,-0.807289,0.703533,0.776566,-0.532748,-0.012535,-0.014949,0.518152,-0.099469,0.295145,0.103513,0.321410,0.257347,0.123120,-0.483611,0.981826', '1308197', '26677495', '24756472', '1299802');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308811', '千机变Ⅱ花都大战', '喜剧', '女帝（瞿颖饰）为了一个“两生花开，帝王星现”乾坤倒转，天下大乱”的传说深感不安，于是让亲信尉缭（吴彦祖饰）派出玄机使蓝翎（钟欣桐饰）和红鸎（范冰冰饰），与叛军首领（甄子丹饰）明争暗斗，极力寻找“帝王孤星”。从小跟着义父黑木爷（梁家辉饰）卖艺为生的炭头（房祖明饰）与柴头（陈柏霖饰），无意中从桃桃（陈冠希饰）手上得到了一块藏宝石板，都被误以为是“帝王孤星”。被蓝翎一直追踪，后来他们两个被以贩卖男奴为生的春十三少（蔡卓妍饰）看中了，四人便开始了一起寻宝的旅途，并开始了各自的恋情。他们到来了藏宝的地点，最后也看到了“帝王孤星”的真身，让他们没人都惊讶不已。©豆瓣', '钟欣潼', '元奎', 5.4, 82646, 'tt0398373', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1630830476.jpg', 8.3, 29.5, 48.5, 10.4, 3.3, '0.214830,-0.018369,-0.471115,0.550555,0.150593,-0.308634,0.444108,0.218443,-0.611779,-0.142712,0.237551,0.723145,-0.449212,0.005854,0.000655,0.205543,-0.133373,-0.572524,-0.305890,-0.331406,-0.083462,-0.124592,-0.232915,0.072462,-0.344616,-0.059237,0.532882,0.017840,0.113382,0.673149,0.583486,0.139520,-0.330735,0.198112,-0.341512,0.125343,0.071614,-0.098888,-0.120491,0.152583,-0.202849,-0.374466,-0.255347,0.173056,-0.135093,0.331723,0.549910,-0.405482,0.187087,-0.264984,0.018733,-0.077954,-0.147191,0.206861,0.223480,-0.057286,0.294310,0.189245,-0.186476,0.236509,0.237577,0.176948,-0.666723,0.189234,0.236479,0.204972,-0.496217,0.307207,-0.058026,-0.250793,0.090210,-0.313042,0.616300,0.303094,0.422058,-0.102142,-0.187203,-0.300478,-0.488766,0.258420,0.403419,-0.046622,0.263340,0.252452,0.166870,-0.445717,-0.015805,0.024771,-0.166821,-0.005207,0.642875,0.176960,0.094708,0.068489,-0.780461,0.065485,-0.114411,-0.097846,-0.048920,-0.289961,0.023022,-0.444666,-0.142179,-0.541816,-0.305536,0.039397,0.155575,0.010836,0.611390,-0.559803,0.173493,0.229669,0.153481,-0.553259,0.351852,-0.060981,0.094250,-0.238978,-0.162245,-0.113651,0.184129,0.537961,0.268440,0.380314,-0.175134,-0.189153,-0.450095,0.167507', '4301278', '26290398', '1303781', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308813', '孝子洞理发师', '剧情', '故事以一个孩子的角度，回顾了他的父亲——理发店师傅宋汉默（宋康昊 饰）的一生。汉默没有什么学问，人送绰号“豆腐“，专靠替人理发养家糊口，年轻时跟自己的女学徒（文素丽 饰）情投意合，喜结连理。汉默的理发店在青瓦台总统官邸的附近，因此他也见证了韩国总统更替的诸多历史事件。在韩国发生”4.19革命“那天，汉默的儿子降生了，取名乐安。一次偶然的机会，汉默结识了韩国中央情报局的头目（孙秉浩 饰），他举荐宋做了总统（赵勇进 饰）的理发师。此后12年间，汉默得以有机会在总统身边服务，而且还幸运地陪同总统出访美国。不过，由于一次马库斯热传染病的牵连，汉默的儿子被保密局的官员带走了，严刑拷打造成了孩子双腿残疾。为了给孩子治病，汉默到处托关系找路子却屡屡碰壁，最后他独自背着孩子踏上了寻医问药之路……©豆瓣', '宋康昊', '林赞相', 8.2, 13294, 'tt0406853', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p492298813.jpg', 0.1, 0.9, 17.2, 54.6, 27.1, '-0.140748,-0.147462,-0.670401,0.545693,-0.442104,-0.344639,0.316187,0.262883,-0.788846,-0.252988,0.228696,0.799974,-0.100813,0.163302,0.286537,0.108959,-0.231815,-0.489100,0.175209,0.000699,-0.399003,-0.348671,-0.333155,-0.416071,-0.219931,-0.216433,0.325003,0.000424,0.013430,0.310027,0.372510,0.083538,0.096183,0.306768,-0.319974,0.070057,0.315383,-0.079553,-0.273198,0.125215,-0.014573,-0.470509,-0.083035,-0.008985,0.111631,0.441499,0.409855,-0.046650,0.033786,-0.413614,0.422157,-0.123583,0.134669,0.055691,0.387104,0.072269,0.291292,0.344666,0.056158,-0.371291,0.233134,-0.078139,-0.398647,0.051127,0.011552,0.074309,-0.681999,0.608140,-0.196112,0.003736,-0.126723,-0.246231,0.293241,0.311035,0.051242,0.167792,-0.121205,0.128268,-0.428656,0.450556,0.475561,-0.016460,-0.131430,0.297224,-0.087537,-0.295484,0.286326,-0.224941,-0.405222,0.193157,0.447572,-0.360464,-0.369252,0.085975,-0.261446,-0.182729,-0.424468,-0.068662,0.025840,-0.115142,0.146414,-0.490311,0.221015,-0.144650,-0.240131,-0.017793,0.158878,-0.058799,0.587997,-0.432803,0.101765,0.793532,0.228180,-0.677959,0.822610,0.147072,0.319405,-0.253422,-0.006415,0.018286,0.149644,0.359768,0.094581,0.224104,-0.034366,-0.297341,-0.203908,0.227158', '1293607', '1309069', '1307922', '6972876');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308815', '胜利之光', '剧情', '在德克萨斯州一个名为敖德萨的小城上，种族的歧视和经济的萧条让小城了无生气。唯有每个周五的晚上，沸腾的莱特利弗体育场才会燃起整个小城的生机和活力，所有人的目光都集中在帕米亚高中橄榄球队的队员们身上。帕米亚球队早就向全国证明了自己的实力与成功，他们势要赢得建队30年以来的第五个州冠军。然而球队出现了经济危机，他们不仅要为荣誉而战，更要通过这次比赛向赞助商证明自己的实力，以让赞助商继续投资。球队灵魂教练加里·贾恩斯（比利·鲍伯·松顿 Billy Bob Thornton 饰）以他的铁腕手段率领球队一路拼杀，他说：完美就是能够正视你的朋友，不让他们失望。敖德萨小城人民对他们的支持就是最大的动力，为了捍卫这座小城，队员们将会拼尽全力。影片根据作家H·G·Bissinger的小说改编而成。©豆瓣', '比利·鲍伯·松顿', '彼得·博格', 8.1, 8407, 'tt0390022', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2398151156.jpg', 0.4, 1.7, 19.7, 47.3, 30.8, '-0.110688,0.002839,-0.529505,0.800256,0.077331,-0.364480,0.317169,0.021294,-0.532024,0.093647,0.262858,0.817626,-0.004710,0.121732,0.173660,-0.237792,-0.159996,-1.000591,-0.336927,-0.027029,-0.333950,-0.493450,-0.207769,-0.379203,-0.183627,-0.401734,0.700816,0.161018,-0.149344,0.338135,0.339863,0.258256,0.307309,0.142154,0.099574,-0.284669,-0.026239,-0.352055,-0.467535,0.411784,-0.110771,0.030452,-0.393189,0.450359,0.237235,0.075762,0.822563,-0.053916,0.126712,-0.156251,0.310988,-0.340003,0.174947,0.205153,0.048009,-0.210469,0.285971,0.258321,0.007292,-0.006935,-0.162989,-0.415670,-1.039228,0.018507,0.162004,0.186637,-0.692551,0.650859,-0.066214,-0.157593,0.111207,-0.130097,0.237749,0.441630,0.172213,0.339889,-0.235161,-0.165061,-0.403430,0.075044,0.607917,-0.110023,-0.307805,-0.012456,-0.329998,-0.389850,-0.195134,-0.254207,-0.548529,0.111985,0.236564,0.126536,0.344159,0.320146,-0.924959,0.043231,-0.116746,-0.781381,0.240974,-0.409945,0.294288,-0.548702,-0.036803,-0.217214,-0.209180,0.174798,0.041648,-0.281167,0.935491,-0.890678,-0.122259,0.733428,0.374900,-0.407364,0.688086,-0.235231,0.178372,-0.110513,-0.165371,0.128380,-0.037411,0.485570,0.135534,0.304293,0.041587,-0.185906,-0.250228,0.856526', '24733428', '25928048', '27602116', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308816', '泽西女孩', '剧情', '身为一名颇有名气的乐评人，奥利（本·阿弗莱克 Ben Affleck 饰）在职场上可谓是风生水起，除了事业上的成功外，美丽的妻子和可爱的女儿格蒂（雷奎尔·卡斯特罗 Raquel Castro 饰）也让他觉得生活几近完美。可是，妻子的突然辞世让这些美好都成为了泡影，祸不单行，不久之后，情绪低落的奥利丢掉了原本收入颇丰的工作。无奈之下，奥利只得带着格蒂回到了位于新泽西的老家。乡下宜人的风景和闲散的生活并没有治愈奥利受伤的心灵，反倒是格蒂感到如鱼得水，不仅仅是因为这里的好气候，更是因为从前忙碌的父亲如今有了更多的时间陪伴自己。机缘巧合之下，奥利遇见了名叫玛雅（丽芙·泰勒 Liv Tyler 饰）的女孩，而这珍贵的相遇终于让他明白了，究竟什么才是生命中最重要的东西。©豆瓣', '本·阿弗莱克', '凯文·史密斯', 7.2, 8530, 'tt0300051', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1195380728.jpg', 0.3, 4.4, 41.1, 41.1, 13, '0.092026,-0.153163,-0.786143,0.658842,-0.088885,-0.465860,0.775874,0.131075,-0.638746,-0.232521,0.024505,0.748793,0.021222,0.426137,0.343617,0.153962,-0.300761,-0.501843,-0.146649,-0.220428,-0.294633,-0.504948,-0.480438,0.023101,-0.164967,-0.495628,0.374205,0.135815,0.156592,0.453783,0.402746,0.328452,0.118912,0.469172,-0.232408,0.082113,-0.012377,0.193500,-0.144821,-0.022297,0.270564,-0.125008,-0.170474,0.249686,0.220137,0.367315,0.463716,-0.235534,-0.299505,-0.141479,0.459912,-0.150850,-0.063417,0.129465,-0.036985,-0.178600,0.219294,-0.057802,-0.505158,0.015810,0.083682,-0.001837,-0.900907,0.100951,0.284814,-0.044185,-0.497334,0.343440,0.017118,-0.396914,-0.015805,-0.470764,0.403862,0.436171,0.163546,0.366704,-0.165833,0.103755,-0.472774,0.057583,0.655132,0.084726,-0.447649,0.480711,-0.476724,-0.341607,0.115156,-0.496612,-0.337274,0.041625,0.103253,0.411934,0.106793,0.201823,-0.548476,0.206727,-0.285226,-0.386322,0.013902,-0.354046,-0.196445,-0.335007,-0.099145,-0.609536,-0.544613,-0.134252,0.024021,-0.301943,0.860949,-0.778965,0.280864,0.330427,0.171831,-0.279170,0.519675,0.142755,0.385498,0.089560,-0.293888,0.459993,-0.030282,0.266884,0.047733,0.290091,-0.094437,-0.511486,-0.396239,0.738658', '24284209', '1793491', '26283288', '5323380');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308817', '两小无猜', '剧情', '当一个人问另一个人“敢不敢”的时候，另一个人必须说“敢”，这就是游戏的规则。小男孩于连和小女孩苏菲的相遇即开始于这样一场孩童的闹剧，一个精美的铁盒子就是他们游戏的见证。说脏话，扰乱课堂，在校长室小便，内衣外穿……一个游戏两人一玩十多年，他们什么都敢，除了承认彼此相爱。苏菲（玛丽昂·歌迪亚 Marion Cotillard 饰）提议两人分别四年，挑战的内容是于连（吉约姆·卡内 Guillaume Canet 饰）敢不敢伤害苏菲。恍惚四年逝去，于连找到苏菲，为了游戏的进行他决定另娶她人，邀请苏菲做伴娘。受到伤害的苏菲在于连的婚礼上抛出铁盒子“你敢悔婚么？”原本最最亲密的朋友相互伤害最深。同样心痛的两个人相约再次分别十年。十年里，于连拥有了一切，家庭、事业、朋友，只是没了苏菲宛如没了心，原来丧失激情的生活这般索然无味。终于十年过去，“Love me, if you dare...”', '吉约姆·卡内', '杨·塞谬尔', 7.9, 441182, 'tt0364517', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2403888231.jpg', 2.2, 4.9, 21.8, 38.5, 32.6, '0.331879,-0.105201,-0.605955,0.548335,-0.445585,-0.273147,0.592674,-0.044256,-0.729693,-0.137114,0.020063,0.831251,-0.457601,0.100126,0.227813,-0.111451,-0.215280,-0.680411,-0.040872,-0.201837,-0.278005,-0.529762,0.010721,-0.276252,-0.108430,-0.117685,0.537452,-0.275244,-0.137338,0.286708,0.502646,0.142002,-0.167000,0.250238,-0.125771,-0.092682,-0.097636,0.281469,-0.587346,0.122859,-0.186031,0.087907,-0.182233,0.121806,-0.149366,0.171140,0.494314,-0.191316,-0.102584,-0.285089,0.449178,0.024497,-0.210514,0.041604,-0.048416,-0.129512,0.663394,0.167658,0.069212,-0.036265,0.504855,-0.160637,-0.569631,0.153761,-0.083413,0.027405,-0.374217,0.565977,-0.055269,-0.162945,0.185917,-0.036752,0.085296,0.296474,0.257346,0.309365,-0.289864,-0.223393,-0.490316,0.180328,0.547640,0.126840,-0.302533,0.537351,0.084866,-0.322612,-0.213542,-0.200719,-0.398573,0.323775,0.043521,0.027112,-0.438118,0.055033,-0.637362,-0.011380,-0.039144,-0.144489,0.365532,-0.692962,-0.211840,-0.554271,-0.048502,-0.223130,-0.404817,0.245386,0.033889,-0.249969,0.650810,-1.010191,0.158507,0.347493,0.371366,-0.544696,0.704488,0.506624,-0.049134,-0.179865,0.123162,0.160219,-0.146340,0.060351,0.246727,0.148158,0.102224,0.466309,-0.268582,0.474565', 