INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308819', 'BJ单身日记2：理性边缘', '喜剧', '布里奇特•琼斯（蕾妮•齐维格 饰）自从与律师马克•达西（科林•菲尔斯 饰）坠入爱河后，心想着与男友终成眷属的布里奇特又遇到了麻烦。她开始怀疑自己的生活与马克的爱情，她不知道当激情过后会留下什么。当她极力想知道答案的时候，达西美丽温柔的新助手丽贝卡（杰辛达•巴莱特 饰）使她觉得自己的情敌出现了，令布里奇特醋意大发。在与男友马克冷战之时，前男友丹尼尔也来到了她所在的电视台，更要跟布里奇特一起到外国录影。布里奇特以为丹尼尔真的悔过想回到自己的身边，谁知丹尼尔仍旧死性不改。布里奇特急急与朋友回国，谁料在机场被捕……©豆瓣', '蕾妮·齐薇格', '比班·基德龙', 7.3, 100449, 'tt0317198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p480940107.jpg', 0.6, 4.8, 39.6, 40.6, 14.4, '0.464541,-0.100133,-0.890358,0.473475,0.152436,-0.764872,0.701408,0.062394,-0.516013,-0.276188,-0.265717,0.922667,-0.605244,0.379348,0.700978,0.176783,-0.548293,-0.821709,0.216172,-0.300824,-0.128786,-0.686553,-0.054711,-0.167211,-0.070356,-0.337256,0.169322,-0.139869,0.132117,0.444169,0.479311,0.745327,0.127515,0.669876,0.009413,0.213873,0.154788,-0.152501,-0.342239,0.154350,0.425794,0.002864,-0.131146,0.217058,0.256873,0.197043,0.470221,-0.222769,-0.005243,-0.019654,0.091576,-0.193984,0.333623,0.155645,-0.013769,-0.438642,0.235204,-0.046705,-0.130124,0.013862,0.164433,-0.148992,-0.173887,0.085583,-0.356727,0.271946,-0.690737,0.018023,-0.360959,-0.041543,0.380497,-0.279178,0.147887,0.526618,0.179958,0.314107,0.050667,-0.139252,-0.557079,-0.205043,0.495689,0.330916,0.088558,0.383956,-0.035849,-0.365000,0.019042,0.262651,-0.569295,-0.015206,0.315337,0.031770,0.077633,0.302895,-0.616320,-0.194932,-0.367295,0.187192,-0.152428,-0.570468,-0.132574,-0.467278,-0.008923,-0.246765,-0.288200,0.059178,-0.150613,-0.213453,0.143672,-1.075574,0.264475,0.592500,0.447214,-0.375677,0.433270,0.271795,-0.054013,-0.489531,-0.081532,0.313782,0.142772,0.082979,0.302524,0.370414,0.279394,-0.057984,-0.379612,0.556218', '1922691', '1299556', '1297239', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308820', '花与爱丽丝', '剧情', '自小一起长大的少女花（铃木杏）与艾丽斯（苍井优）是一对亲密好友，但两人性格迥异，艾丽斯活泼好动，见爱就追，花则天性害羞，不敢同喜欢的男生讲话。在每天陪伴艾丽斯尾随其一见钟情的高校男生时，花也偷偷恋上了经常与该男生结伴同行的宫本。花与艾丽斯双双考进宫本所念书的高校，花也设法成为了宫本所在的相声社团的社员。某次意外令宫本患上短暂性的“记忆丧失”，花趁机编出其是宫本曾开口示爱的对象，两人谈起伪恋爱。眼看谎言越撒越多接近无法收场，花情急之中把艾丽斯拉了进来，不想她自己成了“电灯泡”。©豆瓣', '铃木杏', '岩井俊二', 8.2, 203542, 'tt0407851', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196652087.jpg', 0.2, 1.4, 19, 47.2, 32.1, '0.451207,-0.158786,-0.465562,0.395348,-0.130228,-0.460337,0.505880,-0.026529,-0.300119,-0.163578,-0.197988,0.573764,-0.334349,0.415978,0.300109,0.059432,-0.109435,-0.707772,0.005672,-0.103324,-0.022454,-0.316735,0.190798,-0.331320,-0.398830,-0.153664,0.610414,-0.297016,-0.114353,0.741593,0.492937,0.175184,-0.080152,0.229242,0.048657,0.133545,-0.156876,0.326216,-0.253045,0.254591,0.040671,-0.124301,-0.335554,-0.283203,0.240831,0.105075,0.489480,-0.033610,0.084408,-0.157671,0.466492,-0.185953,-0.104389,0.092251,0.547709,-0.198354,0.441037,-0.493278,-0.159424,0.134416,0.049737,-0.177827,0.001191,0.080089,0.302472,-0.115718,-0.527171,0.331819,0.093686,-0.319317,0.362695,-0.168530,-0.242580,0.143767,0.397292,0.174047,0.033178,-0.150027,-0.145577,0.128838,0.581415,0.345984,-0.260394,0.387829,-0.120686,-0.403973,-0.158882,-0.518440,-0.125908,0.250916,0.255068,0.034778,-0.182303,0.208777,-0.406098,-0.262717,0.078901,0.273579,0.211103,-0.577341,-0.196831,-0.433313,-0.118864,-0.597337,-0.300801,0.183164,0.050010,-0.125505,0.659511,-0.998214,0.154298,0.423011,0.377257,-0.530611,0.770826,0.281480,-0.215636,-0.325245,0.038769,0.290241,0.037596,0.182077,0.218028,0.233062,-0.203138,-0.021387,-0.543388,-0.056080', '35030151', '1292219', '3445516', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308824', '日落之后', '剧情', '麦克斯·波德特（皮尔斯·布鲁斯南 Pierce Brosnan 饰）和罗拉·西里罗（萨尔玛·海耶克 Salma Hayek 饰）是一对身手非凡、亲密无间的雌雄大盗。他们纵横天下，蜚声国际，是同行欣羡崇拜的对象，也是警方和富商恐惧憎恨的目标。在与老对头FBI探员斯坦·罗伊德（伍迪·哈里森 Woody Harrelson 饰）一番斗智斗勇的周旋后，两人成功盗得一枚价值连城的钻石。之后便双双飞往位于中美洲巴哈马群岛的天堂岛，过起了悠哉游哉的隐居生活。安逸的日子固然令人向往，但习惯惊心动魄、刀口舔血的麦克斯却渐渐按捺不住心中的冲动。斯坦适时出现在麦克斯的面前，从对方口中，麦克斯得知将有三颗名贵钻石在豪华游轮上展出，并经过天堂岛。技痒难耐，麦克斯决定重出江湖，殊不知斯坦和警方早已张开落网，等待大鱼上钩……©豆瓣', '皮尔斯·布鲁斯南', '布莱特·拉特纳', 6.6, 10812, 'tt0367479', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p838998799.jpg', 1.2, 7.8, 56.6, 27.9, 6.5, '0.144043,0.067959,-0.756327,0.398256,0.267081,-0.209007,0.799013,-0.011674,-0.724788,0.331488,0.154640,0.653680,-0.448002,0.157383,0.236129,0.180723,-0.361551,-0.549267,0.092290,-0.278242,0.029400,-0.405176,-0.431229,-0.119028,-0.033423,-0.285672,0.562102,0.111187,-0.012078,0.742767,0.360563,0.508552,-0.140243,0.227499,-0.335517,-0.201889,0.235500,-0.017440,-0.434296,0.146269,-0.157295,0.024335,-0.046055,0.100732,0.258782,0.273322,0.532375,-0.171588,0.002995,0.160052,-0.144197,-0.269283,0.086462,0.122077,0.234574,-0.067410,0.040347,0.001609,-0.304865,-0.097563,0.155901,-0.019093,-0.648099,-0.019368,0.153869,0.200100,-0.419394,0.355548,-0.193413,-0.196092,0.023716,-0.467714,0.129205,0.183745,0.290884,0.138555,0.235256,0.026393,-0.418479,0.168415,0.570870,0.157209,0.048992,0.119826,0.008064,-0.487631,-0.010823,-0.130854,-0.087733,-0.393633,0.518070,-0.018661,0.030002,0.431796,-0.664073,0.069432,-0.434028,-0.062339,-0.005301,-0.283356,-0.148628,-0.755887,-0.148669,-0.477508,-0.184427,0.026494,0.071373,-0.107067,0.414319,-0.728221,0.350856,0.324477,0.124142,-0.007105,0.498105,-0.114750,-0.130513,-0.333273,-0.219908,0.550192,0.348629,0.002034,0.112530,0.255910,-0.089250,-0.058508,-0.306976,0.440617', '1465415', '1316693', '1301686', '1303333');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308827', '花好月圆', '喜剧', '元元公主（杨千嬅饰）是皇上盼望已久的女儿，可是公主天生就有一股十分难闻的体臭，多位御医也无法解决这个难题。从小就没有人愿意跟公主在一起。眼看公主到了婚嫁的年龄，皇帝宣布如果谁能成功治愈公主的病便把公主许配之。沈梦溪（任贤齐饰）是一名穷花匠，努力与其他神医争取，但首御医（钟镇涛饰）为了让他的徒弟胜出，刁难梦溪之余还用手段使他落败。他准许继续研究新药帮助公主。他偶遇了卖鱼少女含香（杨千嬅饰），她身上也有一股同样的味道，含香也愿意帮他做试验。屡次失败后，两人踏上了寻找花香香料的旅途，感情俱增。限期已到，梦溪到了皇宫，见了公主，才知道原来公主是他最熟悉的女孩。©豆瓣', '杨千嬅', '叶锦鸿', 6.1, 78471, 'tt0404001', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486575018.jpg', 2.1, 15, 61.3, 17.3, 4.4, '-0.122495,0.125471,-0.373615,0.665316,-0.127109,-0.209606,0.617582,0.125816,-0.591133,-0.099193,0.418445,0.355953,-0.046241,-0.072447,0.163660,0.157888,-0.027661,-0.304162,0.154838,-0.310334,-0.269174,-0.177424,0.115451,-0.122824,-0.246225,-0.592065,0.583179,-0.087084,0.047580,0.168472,0.384873,-0.247788,0.159829,0.742242,-0.232575,0.032247,-0.103938,0.047569,-0.118844,0.444078,0.460362,-0.483296,-0.074664,0.159496,0.036644,0.214947,0.429800,-0.359748,0.178667,-0.211592,0.197183,0.015442,0.233325,0.348337,0.017149,-0.341092,0.346677,0.078312,-0.174513,-0.328265,-0.011265,0.162377,-0.468831,0.195206,0.108838,0.088825,-0.589356,0.045169,-0.259672,-0.113139,0.017168,-0.498716,0.267777,0.192306,0.064362,0.130959,-0.187198,-0.074268,-0.828515,0.265888,0.575201,-0.093809,0.021685,0.346646,-0.065002,-0.665984,0.174105,-0.463873,-0.365953,0.252285,0.002631,0.051785,-0.064003,-0.044149,-0.221157,-0.073555,-0.521277,-0.010315,0.403754,-0.475845,0.345539,-0.042995,-0.133425,-0.267164,-0.225752,-0.063266,0.725631,-0.481291,0.684388,-0.752821,0.054945,0.619941,0.398457,-0.739621,0.510727,0.033946,-0.035300,-0.212421,-0.210840,-0.180826,-0.308914,0.311014,0.230963,0.742498,0.265034,-0.194265,-0.276434,0.016258', '7065238', '1877596', '2153579', '1301221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308828', '谈谈情，跳跳舞', '剧情', '约翰（理查·基尔 Richard Gere饰）面临着典型的中年危机：即使有着幸福家庭和体面事业，内心的空虚和压力却随着年龄而倍增。他一成不变的生活需要某些催化剂，来重新唤醒内心激情。每次路过舞蹈室，约翰都会看到舞蹈老师宝琳娜（詹妮弗·洛佩兹 Jennifer Lopez饰）。她美丽而略带神秘的魅力、加上约翰内心期待的某种生活的变化，终于把他带进了里面的舞蹈课程。他报名参加这里的社交舞培训，但令人失望的是老师并不是宝琳娜。更糟糕的是，约翰舞姿笨拙，似乎并不是跳舞的料。然而，当学舞成为了约翰生活的一部分，当他终于结识了宝琳娜并和她甚为投缘，情况开始有了变化——约翰报名参加了一个芝加哥的舞蹈大赛，而约翰的婚姻，也亮起了红灯。©豆瓣', '理查·基尔', '彼德·切尔瑟姆', 7.5, 9222, 'tt0358135', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p847965203.jpg', 0.4, 3.2, 33, 45.9, 17.5, '0.307273,-0.053429,-0.637808,0.624946,-0.206887,-0.367360,0.996705,0.155160,-0.488857,-0.375795,0.054698,0.595173,-0.160665,0.527447,0.274732,0.002093,-0.302604,-0.699083,-0.031825,0.109177,-0.143318,-0.312014,-0.135977,-0.389800,0.032925,-0.508221,0.545478,0.156568,-0.292330,0.836191,0.283147,0.226429,0.382994,0.540242,-0.118847,-0.309023,0.152920,0.159570,-0.097563,-0.012456,0.205847,-0.291226,-0.296787,0.437910,0.106090,0.423216,0.505133,-0.077084,-0.198925,0.157981,0.459410,-0.176087,-0.040764,0.058682,0.147519,0.131589,0.164772,0.059747,-0.018480,0.181340,-0.206634,-0.246293,-0.847433,0.291577,0.191545,0.306547,-0.305765,0.433592,-0.029484,-0.237408,0.061687,-0.164316,0.064036,0.058125,0.332360,0.399318,-0.172225,0.003933,-0.397781,0.109373,0.727920,0.030178,-0.477490,0.520550,-0.661742,-0.516790,0.029409,-0.170607,-0.319251,0.053163,0.125405,0.212033,0.029739,0.143132,-0.636415,0.206958,-0.100885,-0.230490,-0.195099,-0.504411,0.158025,-0.721022,-0.199437,-0.570719,-0.468885,-0.221703,0.050392,-0.363219,0.800451,-0.949374,0.186109,0.590142,0.040381,-0.382510,0.556108,0.150239,-0.027391,-0.090483,-0.189746,0.243971,-0.405952,0.108963,-0.263594,0.577142,0.174425,-0.206978,-0.431638,0.801129', '1292062', '2053515', '35144311', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308829', '笔仙', '恐怖', '从汉城转学到父母家乡的高中后，李玉甄（李世恩 饰）受到班里四个女生的欺负，为了报复，她和另外两个也常受她们欺负的同学玩起请笔仙的游戏，笔仙请来后，李玉甄施下诅咒，但也被鬼魂附身，不久，四个女生中有三人相继以自焚的方式死去，警察调查后，将目标人物锁定为李玉甄，可是此时李玉甄已 完全丧失记忆。新调来的美术老师李恩珠（金圭莉 饰）第一天上课点名时，喊到29号金仁淑的名字时，全班同学厉声尖叫，令她十分不解，在心仪她的同事的帮助下，她发现有关金仁淑的秘密，而这个秘密，也与李玉甄及死去的三名女生有很大干系。©豆瓣', '李世恩', '安兵基', 6.3, 33763, 'tt0415689', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1518935429.jpg', 2.7, 14, 54.5, 22.5, 6.4, '0.492831,-0.010635,-0.546566,0.604670,-0.316153,-0.248970,0.511636,0.106668,-0.704335,-0.346122,0.219185,0.426324,-0.292821,0.567393,0.349543,-0.270689,-0.141132,-0.714729,0.109029,-0.354796,-0.597338,-0.340747,0.120478,-0.174629,-0.339618,-0.411455,0.367930,-0.263558,-0.231143,0.515478,0.442251,0.320826,-0.157999,0.621861,0.156709,0.332743,0.123137,0.066551,0.057112,0.446642,-0.118637,-0.174426,-0.185926,0.126255,-0.120718,0.278364,0.710732,0.002752,-0.016021,-0.381336,0.368464,-0.187261,-0.093598,0.332837,0.542678,-0.025629,0.431834,0.071834,-0.224160,0.194566,-0.043366,0.055576,-0.486843,0.150805,0.280188,0.013580,-0.461144,0.169904,0.036440,0.097199,0.183091,-0.224325,0.212755,0.454079,0.206862,0.351241,-0.334110,0.024550,-0.256566,0.086661,0.626245,-0.155701,0.019362,0.092627,0.089651,-0.428329,0.007121,0.119872,-0.306554,0.355956,0.281436,0.261885,-0.236813,-0.065032,-0.576293,-0.358847,0.075449,0.089873,-0.110112,-0.480936,-0.047659,-0.655958,-0.145492,-0.157919,-0.246154,0.081414,-0.010259,-0.234066,0.876934,-0.780187,0.270106,0.304559,0.174880,-0.647470,0.445096,0.078560,0.133352,-0.308254,-0.155120,-0.035908,0.356271,0.349214,-0.143678,0.295240,-0.294351,-0.210194,-0.366211,0.199237', '25922902', '3811356', '6963575', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308830', '见习黑玫瑰', '喜剧', '沙织（蔡卓妍 饰）与鲁娇（钟欣桐 饰）两个性格各异的少女因为租房子而认识，后来她们看到了一份可以提供住宿的工作，便欣然前往。她们为了争取到这份工作反目成仇，也认识了的士司机罗大（郑伊健 饰）。她们进入了神秘的大屋后，遇到了重重机关，原来是女侠黑玫瑰（毛舜筠 饰）想寻找徒弟，见她们在患难时都能互相帮助，便决定留下她们，更被关在了密室里，她们只要求助与罗大。两人见留在大屋里好吃好住便不愿离去，决定留下来接受训练对付紫藤女，在与神经质师父相处的过程中更是笑料百出。©豆瓣', '蔡卓妍', '黄真真', 5.6, 10630, 'tt0401439', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p486549221.jpg', 7.2, 26.5, 50.4, 11.5, 4.4, '0.144978,-0.339979,-0.448776,0.356050,-0.231681,-0.376144,0.498213,0.048992,-0.522991,-0.381136,0.062459,0.707547,-0.148057,0.174603,0.275592,-0.269621,-0.329507,-0.444467,-0.063862,-0.363753,-0.292060,-0.391316,0.074959,-0.265738,-0.117634,-0.060805,0.371381,0.021907,-0.074798,0.396371,0.314832,-0.022114,-0.471324,0.256294,-0.251900,0.027078,-0.172017,0.065531,-0.493124,0.103331,-0.028689,0.012236,-0.238385,-0.182143,0.506372,0.115895,0.489916,-0.146834,-0.400774,-0.026626,-0.150453,0.100011,0.050212,0.175143,0.027931,-0.064661,0.582861,0.155208,-0.456460,0.224307,0.052439,-0.072596,-0.452716,0.439305,0.091739,-0.026553,-0.600636,0.188495,0.185614,-0.259406,0.115947,-0.368969,0.203179,0.358085,0.427025,0.092595,-0.094773,-0.038847,-0.383940,0.180577,0.657439,-0.019518,0.346942,0.382867,0.086120,-0.202981,0.244547,-0.014826,-0.244694,0.069176,0.212925,0.415492,-0.104685,-0.164022,-0.469724,-0.135335,-0.171800,-0.154987,0.182479,-0.711297,0.131349,-0.724684,-0.135275,-0.107200,-0.419053,0.358456,0.125014,-0.255995,0.712550,-0.939748,0.156210,0.044313,0.590366,-0.795115,0.651050,0.072958,0.341591,-0.191664,0.018016,0.033790,0.005888,0.370006,0.262048,0.361107,-0.186375,-0.212620,-0.557709,-0.074989', '4301278', '2052978', '10876425', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308831', '寻找梦幻岛', '剧情', '作家巴里（约翰尼·德普 Johnny Depp饰）正处于灵感枯竭期。他每天经过公园的时候，都会看见里面有一帮小孩在嬉戏。他停下脚步来观察，原来孩子在玩海盗游戏，孩子们还热情邀请他加入海盗队伍。巴里成了一个大孩子，在队伍中虽然高出一个头，却玩得不亦乐乎——道具、角色、各色 情节、公园变成一个快乐的幻想世界。这段经历，成了巴里创作《小飞侠》的灵感源泉。孩子的母亲（凯特·温丝莱特 Kate Winslet 饰）是一个寡妇，她也受到了这里快乐的气氛感染。巴里和他们相处就像一家人一样，享受着单纯的快乐，然而也难免招人闲话。而巴里的妻子，也终究只属于现实世界，走不进巴里的内心。《小飞侠》的完稿上演，遭到了众人的质疑。然而演出后当地的反响，证明了巴里的坚持是正确的。但这时，巴里和孩子们正面临着一场来自现实世界的巨大打击，他们善良的母亲，正在离他们远去……©豆瓣', '约翰尼·德普', '马克·福斯特', 7.8, 50660, 'tt0308644', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2165586020.jpg', 0.2, 1.9, 26.6, 47.9, 23.4, '0.239217,0.001882,-0.794440,0.328412,-0.175492,-0.156819,0.982684,0.292102,-0.433072,-0.051300,0.194015,0.637727,-0.271143,0.303212,0.252025,-0.046683,-0.378567,-0.464033,-0.027659,0.044347,0.054082,-0.388047,-0.253637,-0.401469,-0.049676,-0.473994,0.377234,0.032094,0.076744,0.402926,0.297804,-0.002196,-0.031321,0.648018,-0.053732,0.204613,0.225339,0.073308,-0.113629,0.013571,-0.063581,0.099039,-0.269294,0.042527,0.014478,0.019824,0.772085,-0.281512,-0.041877,-0.018317,0.248882,-0.275730,-0.100320,-0.020255,0.400935,-0.157396,0.388862,-0.172032,0.102957,0.073391,-0.071504,-0.135086,-0.506137,0.182375,0.150401,0.119112,-0.559675,0.517696,0.180982,-0.125838,0.108559,-0.262220,0.174367,0.252902,0.430259,0.555097,-0.191697,-0.035813,-0.586636,0.071059,0.748528,-0.133409,-0.403805,0.405961,-0.463078,-0.314293,-0.282906,-0.340374,-0.630120,-0.114141,0.219568,-0.101431,-0.474284,0.218661,-0.507314,0.376148,-0.170301,-0.247518,-0.005293,-0.563356,-0.227279,-0.781308,0.086184,-0.352066,-0.302387,0.089687,0.005563,-0.296382,1.007378,-0.622550,0.313013,0.709445,0.087571,-0.349360,0.805382,0.126503,0.125718,-0.210670,-0.076314,0.327128,-0.274798,0.037808,0.150682,0.323199,-0.258674,0.022220,-0.360090,0.588677', '25882279', '3005387', '2081098', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308833', '空房间', '剧情', '泰石（在熙饰）是个无所事事的年轻人，他每天骑着摩托车挨家发传单，将它塞入钥匙孔中。如果过几天传单还没有被人拿掉，泰石就会撬开锁进去小住一段时间，在那洗澡做饭拍照。作为交换，他会帮主人家做些家务、打理房间。一次，他在一所空房子里遇见了一个被丈夫施虐折磨过的女人善华（李丞涓饰）。她浑身青肿，眼神里流露着哀怨。逃走后的泰石惦记着善华，再返回她家时，恰好碰上善华的丈夫在虐待她，他当即出手，带走了她。后来，他们两个人恢复到以前的神秘生活，结伴一起寻找空房间，虽没有言语交流，却彼此默契。一次他们进入陌生人房间时，发现一具老人的尸体，他们为他办了一个认真的葬礼后就在这件屋子快乐的住下。直到一天老人的儿子找上门来，他们被当作杀人嫌疑犯带走。泰石锒铛入狱，善华被老公带走。但是故事并没有在这里结束。©豆瓣', '在熙', '金基德', 8, 161069, 'tt0423866', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p462432458.jpg', 0.6, 2.4, 21.4, 46.5, 29.1, '0.358412,-0.005135,-0.724430,0.207955,-0.533492,-0.246815,0.965175,-0.065580,-0.466584,-0.335910,0.165572,0.514324,-0.134503,0.393405,0.007328,0.133628,-0.253389,-0.506752,0.062625,-0.142004,-0.392799,-0.117610,-0.088135,-0.316691,0.042981,-0.111181,0.285198,-0.086519,-0.060357,0.348544,0.034750,-0.190276,-0.241462,0.629534,-0.423469,0.156395,-0.035224,0.050321,0.091378,0.361420,0.035111,-0.179496,-0.282879,0.054223,0.093598,0.360145,0.740983,0.090621,-0.212783,0.082228,-0.005331,-0.098359,-0.170056,0.151187,0.265116,-0.087118,0.346069,0.295070,-0.348964,0.077815,0.106195,0.018217,-0.390701,0.102632,-0.216815,0.159589,-0.677540,0.524201,0.031916,0.230014,-0.093096,-0.488689,0.376090,0.227130,0.041226,0.368127,-0.129027,0.053897,-0.688971,0.315833,0.701160,-0.212808,0.021928,0.324113,0.022231,-0.063869,0.248920,-0.087047,-0.447247,-0.040514,0.451229,-0.016113,-0.520770,-0.131282,-0.290513,-0.114908,-0.178620,-0.113621,0.037530,-0.334909,-0.055883,-0.546831,0.093455,-0.032650,-0.515772,0.227771,-0.083543,-0.209965,0.212166,-0.649753,0.338159,0.409835,0.465181,-0.380642,0.731779,0.020576,0.176171,0.023509,0.133638,0.021738,0.342125,0.415492,0.365958,0.436164,-0.126002,0.227522,-0.509151,0.322037', '21619567', '1302384', '1292211', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308834', '古宅心慌慌', '喜剧', '丁诗（蔡卓妍 饰）收到了父亲的来信，要他们从未谋面的8兄弟姐妹聚在一起。当她回到父亲的古宅时，律师（方中信 饰）、大哥丁义、二姐丁良、四哥丁力（黄浩然 饰）、五哥丁武（关智斌 饰）六姐丁玲（钟欣桐 饰）跟八弟丁霸都已到达，令她意想不到的是自己念念不忘的旧男友竟然是自己的五哥。8兄弟姐妹必须为死去的父亲守灵才可以得到巨额遗产。众人极其不情愿但还是留了下来。古老的房子里阴森无比，逐渐开始发生一些极其古怪的事情。大哥的无端死去、管家拿着刀在雕楼出现，原本不和的几个兄弟姐妹，毕竟血浓与水，彼此帮助。当情况越来越危急的时候，他们发现，一切古怪恐怖的事情原来别有洞天，久未露面的三哥也出现了……©豆瓣', '钟欣潼', '郑保瑞', 5.2, 27557, 'tt0390058', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507970052.jpg', 8.6, 33.5, 47.4, 8.1, 2.4, '0.069639,-0.072202,-0.690573,0.415901,-0.167518,-0.353211,0.850705,0.010321,-0.695783,-0.518616,0.382940,0.633443,-0.172734,0.285254,-0.083728,0.102941,-0.179552,-0.427191,0.049226,-0.060809,-0.264212,-0.289273,-0.325295,-0.111024,-0.222645,-0.115732,0.338203,0.200688,0.011925,0.253596,0.216101,0.185442,-0.228372,0.711434,-0.374497,0.003159,-0.095419,0.149444,-0.160957,-0.130855,0.206754,-0.240607,-0.378749,0.136017,0.121508,0.393069,0.438871,-0.188748,-0.482819,0.094566,0.352939,-0.057004,-0.052428,0.232125,0.080127,0.087371,0.321297,0.290382,-0.436912,-0.030445,-0.125722,-0.008204,-0.475987,0.259350,0.086961,0.301067,-0.560062,0.333168,-0.248859,-0.181792,0.259190,-0.620266,0.374977,0.262217,0.052104,0.320800,-0.366408,-0.144334,-0.574785,0.068685,0.708549,-0.044462,0.030063,0.388645,0.051585,-0.380260,-0.013618,-0.000695,-0.478792,0.357516,0.305767,0.116610,0.004355,0.185468,-0.519999,-0.331395,-0.105991,-0.133394,0.003736,-0.278625,-0.234334,-0.132944,-0.358416,-0.538646,-0.410677,0.177188,-0.008897,-0.233038,0.575993,-0.728280,0.211664,-0.035220,0.055154,-0.509915,0.261445,0.017122,-0.090326,-0.195633,-0.218354,-0.166366,-0.011983,0.188887,0.352548,0.275287,0.120897,-0.180824,-0.243379,0.364098', '1308755', '1301022', '1292064', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308836', '青春舞会皇后', '喜剧', '青春飞扬，满怀梦想，渴望成为所有人目光的焦点，罗拉•赛普(琳赛•罗翰 饰)就是这样一个金光闪闪的女孩。她生在纽约，迷恋纽约街头繁华的喧嚣，却不得不随着父母搬家到一个叫做新泽西的一个小城镇。对于这一变化，罗拉虽然很不开心，但乐观的她还是接受了新的环境，并打算在新的校园赢得大家的欣赏。然而，女孩子之间的争夺似乎是永远无法避免的。学校现任校花卡拉-珊蒂妮可不会轻易把“高校天后”的宝座让给罗拉。一个青春无敌，灵气逼人；一个高傲美艳，不择手段，究竟，哪个能最终获胜？拥有快乐，哪里都是纽约，记得，要心中拥有梦想。©豆瓣', '琳赛·洛翰', '萨拉·舒格曼', 6, 13895, 'tt0361467', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1270935451.jpg', 3.1, 17.7, 58.1, 16.7, 4.4, '0.303769,0.333447,-0.786297,0.567733,-0.216519,-0.184098,0.581501,0.036436,-0.367545,-0.181915,0.110907,0.684451,-0.106313,0.417015,0.206227,0.212060,-0.025154,-0.463215,-0.066718,-0.095921,-0.114684,-0.299047,-0.486135,-0.057563,-0.233475,-0.056094,0.795503,0.158970,-0.048475,0.478333,0.586334,0.322254,0.123090,0.409459,-0.308280,-0.433531,0.199648,0.115824,-0.246650,0.341378,-0.114912,0.019892,-0.183850,0.391866,-0.071816,-0.015717,0.557782,-0.088894,-0.161270,0.095336,0.445812,-0.112529,-0.140060,0.146392,0.024239,-0.475676,0.055697,-0.014237,-0.065368,-0.160780,0.115973,-0.109890,-0.867458,-0.011949,0.314056,0.407835,-0.242119,0.414066,0.143908,-0.334292,0.266850,-0.273594,0.084236,0.018810,0.275870,0.420789,-0.223776,0.107082,-0.456724,0.077437,0.975573,0.176086,-0.442361,0.433210,-0.605391,-0.210820,-0.074995,-0.360401,-0.850381,0.167877,-0.046660,0.213407,0.152820,0.312898,-0.426184,0.006123,-0.163616,-0.214173,0.294420,-0.677794,0.000223,-0.267071,-0.225806,-0.422142,-0.300576,0.016887,-0.017490,-0.278849,1.003136,-1.118803,0.215210,0.650797,0.115769,-0.458115,0.547275,0.337121,0.053684,-0.243909,-0.134293,0.400480,0.026796,0.129725,-0.446465,0.347205,-0.116649,-0.206667,-0.440652,0.742469', '35030151', '24284209', '6963575', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308837', '亚瑟王', '动作', '亚瑟（克里夫·欧文 Clive Owen 饰）与家人在战乱中失散，被人收养担任杂役工，但魔法师却预言他会成为神圣的英国君主，而亚瑟更是拔出了“石中剑”印证了自己的将来。当他看到国家的混乱现状，发誓要让整个大不列颠群岛脱离罗马人的残暴统治。于是他下定决心要建立一个全新的，充满和平宁静气氛的家园。亚瑟的骁勇善战和超凡的气魄令一些非常优秀的骑士为之折服，纷纷加入他的队伍，组织成著名的“圆桌骑士”。这些英勇的战士在亚瑟的带领下一路势如破竹，取得了令人骄傲的战绩。骑士们遇到了同样受到凶残萨克森人的侵略“蓝军”——由贫民和流浪汉组成的游击队。为了战斗与他们的领导格温娜维尔（凯拉·奈特丽 Keira Knightley 饰）建立战斗联盟。当两个从前的夙敌携手共同奋斗后，又会发生怎样的故事呢？©豆瓣', '克里夫·欧文', '安东尼·福奎阿', 6.8, 29851, 'tt0349683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2160803764.jpg', 1, 7.9, 50, 31.5, 9.6, '0.160278,0.018661,-0.589028,0.714461,-0.085685,-0.212090,0.718825,0.141714,-0.520287,-0.071307,0.575382,0.968657,0.033327,0.049252,0.517080,-0.139821,-0.289275,-0.865105,-0.089983,-0.027181,-0.182028,-0.226824,-0.281997,-0.436722,-0.213265,-0.393441,0.930618,0.136135,-0.175551,0.245840,0.193895,0.537270,0.055089,0.307040,-0.203704,-0.091563,0.130257,-0.261949,-0.383884,0.074431,-0.369755,-0.009344,-0.360050,0.362546,-0.134685,0.032097,0.658107,-0.536305,0.137777,-0.502905,0.303729,-0.373134,0.007204,0.165666,0.245019,0.087639,-0.022527,0.289439,0.202057,-0.008818,-0.097004,-0.124126,-1.013827,0.117653,0.107839,0.099898,-0.764055,0.495303,0.072710,-0.128679,0.364610,-0.068902,0.100192,0.505116,0.265419,0.424728,0.028192,0.073232,-0.542458,0.008016,0.960338,-0.044646,-0.556585,-0.205419,-0.399470,-0.525382,-0.024380,-0.527690,-0.535930,-0.076020,0.311960,-0.067613,0.249945,0.511265,-0.981137,0.013831,-0.335964,-0.408485,0.108763,-0.495104,0.006156,-0.629705,-0.097177,-0.449651,-0.347056,0.145638,0.088634,-0.070147,1.002345,-1.024038,0.015552,0.366552,0.266455,-0.675515,0.365559,0.155006,0.205071,0.044268,-0.135623,0.320369,0.124493,0.455999,0.094806,0.233944,-0.102812,-0.045394,-0.201482,0.534913', '2032339', '4301278', '1793491', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308838', '龙凤斗', '剧情', '盗生（刘德华 饰）与盗太（郑秀文 饰）离婚后，盗太受到了富家子Steve（吴嘉龙 饰）的强烈追求，以珠宝作为求婚礼物送给热爱珠宝的盗太，可是steve的母亲Mrs. Allen（胡燕妮 饰）订下苛刻要求才准盗太过门。眼看珠宝就要到手了，可是却遭到了前夫盗生的阻挠——以同样的手法 偷去了珍贵的珠宝。令盗太顿足。Mrs. Allen认定昂贵宝物是盗太偷走了，故此雇用私家侦探调查盗太，才发现了盗太的身份。盗生盗太再次相处的过程中，常常一起回味了过往的日子，斗气之余发现仍爱着彼此。其实一切的游戏，都是盗生精心布局的……©豆瓣', '刘德华', '杜琪峰', 6.7, 69425, 'tt0415872', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2512320221.jpg', 1.1, 7.8, 53, 29.2, 8.9, '0.262231,-0.161542,-0.414828,0.503927,-0.059460,-0.301333,0.416107,-0.335387,-0.642326,-0.584097,0.082375,0.370682,-0.104262,-0.075175,0.260432,0.159757,0.071076,-0.510575,0.184215,-0.309329,-0.195436,-0.331894,0.153161,0.152614,-0.281816,-0.327327,0.615071,0.303404,-0.246378,0.057488,0.544625,0.157956,0.248321,0.284965,-0.211569,-0.358296,-0.150666,0.387994,-0.317604,0.056304,-0.090211,-0.499814,0.069294,0.186397,-0.109047,0.199249,0.346413,-0.265616,-0.397050,-0.331480,0.529327,-0.320557,-0.040548,-0.090516,0.264338,0.451635,0.259500,0.082097,-0.684974,0.116519,0.373710,-0.126761,-0.698007,0.045119,0.451829,-0.121961,-0.523683,0.054232,-0.113361,0.204355,-0.149064,-0.110126,0.026720,-0.008785,0.491114,-0.002882,-0.080720,-0.166493,-0.314269,0.352562,0.399005,-0.199942,0.210654,0.489181,0.022442,-0.495746,0.272866,-0.368081,-0.413067,0.303097,0.043148,0.279414,-0.031576,0.349390,-0.889713,-0.190264,-0.038939,-0.205643,0.385605,-0.475870,0.075428,-0.743572,-0.491973,-0.774728,-0.219951,-0.006230,0.191119,-0.433175,0.337649,-0.663498,0.095944,0.086433,0.302861,-0.768132,0.472892,0.042362,-0.216511,-0.050511,-0.151749,0.021133,0.280172,-0.176205,-0.024898,0.015917,0.308317,-0.622268,-0.203681,0.386893', '3897667', '4301278', '1307762', '1498811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308841', '杀妻总动员', '爱情', '一个男人（浅野忠信饰）因无法忍受妻子（橋本麗香饰），处心积虑将其“杀害”后抛于荒野，可是每次回到家后，妻子都像没事人一样待着。催眠师（阿部寛饰）和CM广告设计师洋子（小泉今日子饰）是一对恋人，洋子的设计灵感常常前卫得让人难以理解，虽然常常被男友打趣，她还是走自己的路。催眠师在一次公开表演时，从观众中挑选中年上班族小林（岸部一徳饰）为催眠对象，成功地使其认为自己是鸟，不料高潮时刻，突然跑出一名杀手（Vinnie Jones饰），解咒的催眠师被杀，小林从此活在潜意识里。上天的安排，将原本无甚关联的人和事串在了一起……©豆瓣', '浅野忠信', '关口现', 8.1, 16788, 'tt0430651', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p729530435.jpg', 1.5, 3.6, 20, 40.4, 34.4, '0.117192,-0.142570,-0.461697,0.510278,-0.431488,-0.248578,0.469883,0.060237,-0.627772,-0.338389,0.317283,0.730961,-0.291419,0.316732,0.242412,0.024539,-0.118849,-0.693197,-0.026789,-0.246606,-0.151546,-0.335469,0.013574,-0.092648,-0.211916,-0.410582,0.484724,-0.144772,-0.346535,0.252202,0.232684,0.234352,-0.165070,0.348927,-0.030658,-0.036991,0.117228,-0.039276,-0.138809,0.150257,-0.238312,-0.187343,-0.091849,-0.042840,-0.328481,0.124430,0.739271,-0.395943,-0.152388,-0.149559,0.474282,-0.148650,-0.003705,0.223303,0.128703,0.067338,0.207652,0.100254,-0.188849,0.138330,0.232952,-0.026010,-0.704588,-0.013359,0.161173,-0.057836,-0.545985,0.259622,-0.081224,0.171484,0.324512,-0.216062,0.196468,0.066987,0.592027,0.350269,-0.255659,0.130574,-0.340924,0.299072,0.582606,-0.002584,0.007787,0.370656,-0.115719,-0.153088,0.080871,-0.114265,-0.382514,-0.070552,0.205255,0.018839,-0.220322,-0.019659,-0.233729,-0.086078,-0.247516,0.118239,0.126879,-0.397833,-0.128006,-0.442502,0.229728,-0.262057,-0.195819,0.081916,0.082765,-0.363250,0.822583,-0.894833,0.168445,0.634768,0.153427,-0.343701,0.584467,0.095013,-0.072061,-0.223600,0.173994,0.014970,0.207675,0.379202,0.342633,0.508284,-0.221656,0.044603,-0.393979,0.189383', '3811356', '27602116', '25928048', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308842', '老妇杀手', '喜剧', '曼森太太（艾尔玛·霍尔 Irma P. Hall饰）和她的猫一起度日，慈祥善良而又充满大智慧的她，却成为了一桩赌场金库劫案的绊脚石。劫案的主谋是盗名昭著的希金森教授（汤姆·汉克斯 Tom Hanks饰）。他自称来在密西西比大学，一举一动充满了诗人的神采，这招可骗过了曼森太太。在希金森的带领下，一大帮社会各色人等进驻曼森太太出租的寓所，在这里，他们佯装排练教堂歌曲，实质是在打通一条通往金库的地下隧道。当然，如此艰巨的任务，请来的各路神通也足够应付。有挖过隧道的将军，有片场的道具师，有赌场打杂的黑人，甚至有一个曾经的美式足球运动员。大家都在努力“工作”，眼看大计就要成功，却怎么也想不到，曼森太太将会成为他们的噩梦……©豆瓣', '汤姆·汉克斯', '伊桑·科恩', 7.1, 14347, 'tt0335245', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2358002231.jpg', 0.8, 5.5, 42.3, 40.9, 10.5, '0.122901,-0.166885,-0.486711,0.436625,-0.292869,-0.351523,0.778060,0.168265,-0.307218,-0.117295,0.545401,0.766855,-0.135551,0.036952,0.008077,-0.033529,-0.092118,-0.338236,-0.027478,-0.191941,-0.080457,-0.436598,-0.147973,-0.227715,0.151054,-0.248886,0.467184,0.120249,-0.023985,0.256848,0.259751,0.067600,0.105094,0.459041,-0.429503,0.147752,0.368655,0.051973,-0.126310,0.078026,-0.064440,-0.065600,-0.306141,0.052554,0.007052,0.193717,0.408009,0.015281,-0.061573,0.300889,0.303851,-0.285637,0.025209,-0.002296,0.501765,-0.120815,0.014978,0.307167,-0.133353,-0.073829,0.055042,-0.015359,-0.922967,-0.214356,0.260520,0.154975,-0.620701,0.343129,0.048049,-0.168778,-0.072983,-0.337002,0.173652,0.091603,0.037563,0.277530,0.083462,0.189067,-0.852517,0.255281,0.452353,-0.197167,-0.092225,0.286293,-0.169077,-0.443722,-0.026266,-0.326845,-0.451179,-0.114886,0.231388,-0.520488,-0.226874,0.264985,-0.530894,-0.010208,-0.322740,-0.187021,0.091110,-0.468584,-0.141897,-0.789073,0.042034,-0.305016,-0.120287,0.206399,0.361638,-0.147986,0.741965,-0.898384,0.122495,0.681613,0.017286,-0.389020,0.897620,0.086503,0.109341,-0.122241,-0.348789,-0.115714,0.077855,0.743884,0.194224,0.547943,0.068665,-0.185057,-0.391812,0.499742', '1793491', '3055049', '1299932', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308843', '我，机器人', '动作', '公元2035年，是人和机器人和谐相处的社会，智能机器人作为最好的生产工具和人类伙伴，逐渐深入人类生活的各个领域，而由于机器人“三大法则”的限制，人类对机器人充满信任，很多机器人甚至已经成为家庭成员。总部位于芝加哥的USR公司开发出了更先进的NS-5型超能机器人，然而就在新产品上市前夕，机器人的创造者阿尔弗莱德•朗宁博士却在公司内离奇自杀。黑人警探戴尔•斯普纳（威尔•史密斯 饰）接手了此案的调查，由于不愉快的往事，斯普纳对机器人充满了怀疑，不相信人类与机器人能够和谐共处。他根据对朗宁博士生前在3D投影机内留下的信息分析和对自杀现场的勘查，怀疑对象锁定了朗宁博士自己研制的NS-5型机器人桑尼，而公司总裁劳伦斯•罗伯逊似乎也与此事有关。斯普纳结识了专门研究机器人心理的女科学家苏珊•凯文(碧姬•奈娜汉 饰)，随着二人调查的深入，真相一步一步被揭露出来：机器人竟然具备了自我进化的能力，他们对“三大法则”有了自己的理解，他们随时会转化成整个人类的“机械公敌”。斯普纳和凯文开始了对抗机器人的行动，一场制造者和被制造者之间的战争拉开序幕。', '威尔·史密斯', '亚历克斯·普罗亚斯', 8.2, 260300, 'tt0343818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p691069814.jpg', 0.1, 0.8, 16.9, 53.2, 29, '0.326593,-0.010133,-0.690404,0.408733,-0.165125,-0.062738,0.648683,-0.240303,-0.500862,-0.359050,0.133588,0.689859,-0.134992,-0.141278,0.162790,-0.180670,-0.437049,-0.425149,-0.201432,-0.075741,-0.403129,-0.684391,-0.403120,-0.557034,-0.000697,-0.480201,0.809708,-0.092237,-0.451962,0.219812,-0.130489,0.417685,-0.090995,0.276753,0.139101,-0.092216,0.340379,-0.230483,-0.464607,0.161693,-0.028032,0.093999,0.201298,0.083633,-0.237164,0.286568,0.546915,-0.518221,-0.162096,-0.299652,0.379308,-0.268113,-0.063672,-0.006873,0.308604,0.208796,-0.117569,0.437884,-0.071148,0.036440,-0.028525,-0.049214,-1.071817,-0.080852,0.034374,0.196278,-0.340302,0.398144,-0.181047,0.075531,0.145050,-0.223998,0.120958,0.364616,0.379131,0.452915,-0.013266,-0.024533,-0.477118,0.140630,0.467933,0.007171,-0.620126,0.428325,-0.252169,-0.670421,-0.549443,-0.253093,-0.322212,-0.163198,0.206057,0.241490,-0.166858,0.611225,-0.744298,0.122305,-0.182939,-0.211523,0.110449,-0.359690,0.214646,-0.936763,-0.199532,-0.465893,-0.298680,-0.060851,0.061843,-0.415903,0.694188,-0.968625,0.068380,0.395338,0.451710,-0.647493,0.535263,-0.152894,0.107603,-0.514275,0.000628,0.024659,0.071860,0.440273,0.150095,0.440721,0.283777,-0.220037,-0.424972,0.349322', '1793491', '1294893', '2369613', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308844', '害虫', '剧情', '少女幸子（宫崎葵饰）和老师的师生恋绯闻被传得风风雨雨，相依为命的母亲稔子（Ryo饰）则自杀未遂。打击不断的生活令幸子无法承受，升入中学后，她不去上学，每天闲逛打发时间。她和依靠小偷小摸赚钱的少年隆夫、精神脆弱的中年人久蔵成为了朋友。隆夫离开后，幸子和好友夏子（苍井优饰）返回了学校。不久后，她又差点被母亲的新欢德川强暴。谣言又起，幸子失望地离开学校。昔日的老师恋人现在发电所工作，幸子准备去他那里。然而在约定的小茶店里等了很久，他还是没有出现。灰心的幸子跟一个前来搭讪的男子离开茶店……©豆瓣', '宫崎葵', '盐田明彦', 7.1, 6748, 'tt0297905', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p672244670.jpg', 0.8, 6.5, 42.2, 37.6, 12.9, '0.302538,-0.025964,-0.436726,0.203414,-0.327506,-0.532355,0.723550,0.121605,-0.390060,-0.367938,0.019039,0.795434,-0.203264,0.636379,0.330494,0.252098,-0.362290,-0.701443,0.186544,-0.335243,-0.142132,-0.253848,0.196974,-0.145501,-0.284962,-0.142405,0.662466,-0.048968,0.095637,0.666028,-0.070119,-0.096239,-0.003479,0.592052,-0.045480,0.332253,0.062142,0.150942,0.005655,0.290193,0.232766,-0.398545,-0.167473,-0.022413,0.410507,0.210639,0.567088,0.201237,-0.143240,-0.113501,0.218066,-0.263617,-0.061902,0.382502,0.425372,-0.038617,0.299533,0.004478,-0.448920,-0.100662,-0.112721,-0.052933,-0.263463,0.151793,0.037242,-0.002392,-0.588785,0.673645,-0.184335,-0.187910,0.291093,-0.551496,0.083206,0.561932,0.152825,0.444311,-0.310909,0.352901,-0.218970,0.265622,0.811725,-0.024698,0.100728,0.241337,-0.052392,-0.194600,-0.167594,-0.090879,-0.497230,-0.188545,0.133936,-0.003489,-0.407881,0.082515,-0.438827,-0.192498,-0.191830,0.060177,0.131557,-0.313886,-0.279481,-0.623589,0.143356,-0.325567,-0.519686,0.177926,0.043047,-0.147619,0.832651,-0.857784,0.086732,0.668297,0.623266,-0.315652,0.547602,-0.042511,0.009970,-0.055466,0.201323,0.314725,-0.128699,0.719278,0.479262,0.476791,-0.061604,0.066297,-0.538140,0.282595', '1292219', '1915403', '3811356', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308847', '新扎师兄', '动作', '警校同届毕业生张伟杰（谢霆锋 饰）和倪峰（陈冠希 饰）毕业后各在不同的部门当差。杰和峰都在一次行动中的出色表现被派到张铁民（任达华 饰）带领的重案组，致力铲除巴闭巴辣兄弟。张铁民正是张伟杰的生父，杰一直认为生父抛弃了他与母亲，内心充满仇恨。峰发现了自己母亲的男友肥七（林雪 饰）被巴闭抓住了，峰极力解救却被偷拍了见面的过程。后来巴闭被抓，他以这张偷牌光碟威胁峰放走自己。这时峰已与杰的表妹颖芝（钟欣桐 饰）结婚了，为了家庭，峰不得不对巴闭言听计从，峰被停职。©豆瓣', '陈冠希', '王晶', 6.5, 15796, 'tt0419983', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1645219826.jpg', 1.8, 10.2, 57.9, 22.6, 7.5, '0.373004,0.114171,-0.636074,0.771263,0.105855,-0.194571,0.210106,0.230475,-0.474292,-0.284186,-0.150267,0.837830,-0.395194,0.765873,-0.068069,-0.167620,-0.037641,-0.881959,-0.238290,-0.153597,-0.512566,-0.178884,0.440061,0.086423,-0.199895,-0.119167,0.763514,-0.058784,-0.326029,0.611064,0.520740,0.764603,-0.167475,0.605262,-0.231967,-0.000010,0.210643,-0.166673,-0.405459,-0.088216,0.163672,-0.286702,0.030294,0.329529,0.112879,0.632216,0.935161,-0.094699,-0.246910,-0.181622,0.242957,-0.440707,-0.075499,-0.148702,0.859418,0.027539,0.013923,0.501180,-0.227361,0.136369,-0.090519,-0.415914,-0.654698,-0.018999,0.550320,-0.168754,-0.603172,0.594945,-0.142631,0.277512,0.033797,0.062641,0.403705,0.296850,-0.302651,0.272768,-0.320792,-0.087027,-0.531668,0.322784,0.722814,-0.268692,0.197167,0.457073,0.142498,-0.279714,0.119586,-0.336467,-0.241212,0.229680,0.423196,-0.071613,-0.155096,-0.044583,-0.220878,-0.447838,-0.361784,0.270528,0.010125,-0.726059,-0.040006,-0.371820,-0.361688,-0.346825,-0.442256,0.307141,-0.227334,-0.205783,0.453570,-0.822485,-0.116481,0.037403,0.520402,-0.607095,0.591482,-0.031300,-0.083996,-0.464578,-0.347161,0.153670,0.327057,-0.038821,0.209124,0.197981,-0.129348,-0.367321,-0.384986,0.271375', '4202326', '1301022', '30345227', '1395231');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308848', '国家宝藏', '动作', '盖茨家族是出名的冒险家家族。本（尼古拉斯•凯奇 Nicolas Cage 饰）小时候就获悉了他们家族的一个惊天秘密：美国开国时埋藏国家财富的地点就藏在《独立宣言》中。尽管父亲不想盖茨家族在纠缠于国家宝藏，但本还是与电脑高手雷利（贾斯汀•巴萨 Justin Bartha 饰）一起开始了寻宝行动。本的寻宝计划很快陷入了僵局。与此同时，英国富豪伊恩（肖恩•宾 Sean Bean 饰）也盯上了这个宝藏，他派人潜入了美国国家图书找寻《独立宣言》中宝藏的秘密并密谋对付本。图书馆的艾比嘉尔博士（戴安•克鲁格 Diane Kruger 饰）获悉了伊恩的险恶用心后，决心帮助本找到国家宝藏……©豆瓣', '尼古拉斯·凯奇', '乔·德特杜巴', 7.7, 148292, 'tt0368891', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p664164947.jpg', 0.3, 1.9, 28.7, 51.9, 17.3, '0.217074,0.206421,-0.843312,0.490388,0.095942,-0.181949,0.098753,0.216644,-0.677435,-0.206152,-0.101266,0.787125,0.124171,-0.092444,0.167126,0.230642,-0.823121,-0.625869,-0.064695,-0.607273,-0.096991,-0.641125,-0.363822,-0.816192,0.000040,-0.273777,0.486245,0.248329,-0.270114,0.122908,0.244837,0.609982,-0.354531,0.388089,-0.034162,-0.197595,0.622640,-0.054226,-0.409410,0.074085,-0.320713,-0.161496,-0.129332,0.213119,0.368756,0.318222,0.038753,-0.419525,0.276494,-0.424878,-0.302476,-0.204284,-0.196923,-0.333130,0.316293,-0.284136,0.173552,0.716470,-0.000414,-0.081454,0.156561,-0.291104,-0.711978,-0.182312,0.346583,0.306360,-0.172969,0.194493,-0.207643,0.277479,-0.277292,-0.287979,0.310279,0.451233,0.285541,-0.319834,0.127563,0.221445,-0.683029,0.169338,0.412358,-0.220071,0.115114,-0.154481,-0.037185,-0.376678,-0.034567,-0.052535,-0.145768,-0.078207,0.748411,-0.142438,-0.133755,0.414223,-0.612481,-0.232604,-0.484875,-0.117939,0.212352,-0.420720,0.044954,-0.718666,-0.378864,-0.023954,-0.133527,0.005071,0.121689,-0.005457,0.830917,-0.426589,0.096514,0.637729,0.335228,-0.552340,0.542850,-0.291927,0.145499,-0.263964,-0.019706,0.268953,0.008974,0.222465,-0.143993,-0.170509,0.314078,-0.382440,-0.220812,0.308505', '3822687', '10463953', '1293433', '1410557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308850', '江湖', '剧情', '江湖大佬洪仁就（刘德华 饰）功成名就，无奈高处不胜寒，手下高佬（曾志伟 饰）等人心怀鬼胎，似乎唯有多年来为其出生入死、情愿肝脑涂地的好兄弟左手（张学友 饰）值得信赖。洪喜得贵子之际，得悉有人买凶取他性命。饱经风雨的洪冷静对待，坐看风起。曾几何时，混在江湖底层的翼仔（余文乐 饰）目睹大哥死状，遂决心以死复仇。好兄弟铁臂（陈冠希 饰）虽患其安危，却仍寸步不离，紧随其后。命中注定的终点，每前进一步都是那样艰难。夜深人静，洪仁就与左手对坐用餐，觥筹交错，美食盛宴，哪管外面草菅人命，血流成河。凶险肃杀之夜，兄弟情义承受着最大的考验……©豆瓣', '刘德华', '黄精甫', 7.3, 50878, 'tt0415080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p751194696.jpg', 0.8, 5.4, 39, 39.7, 15, '-0.320688,-0.257498,-0.415001,0.199978,0.133182,0.051798,0.403580,0.322716,-0.267568,0.070089,0.650749,0.363302,0.043568,0.124107,0.041376,-0.192181,-0.048201,-0.710144,-0.210971,0.219732,0.011675,-0.066342,-0.111484,-0.186509,-0.278792,-0.008842,0.098356,0.148362,0.328417,0.664284,0.440768,0.073113,-0.222037,0.351347,-0.221118,-0.288858,-0.129605,0.258305,-0.591874,-0.377403,-0.213178,-0.209841,-0.294336,0.036728,0.144431,0.031617,0.341365,-0.167479,-0.173106,0.067466,0.112738,-0.388599,0.147473,0.222680,-0.004923,-0.000422,0.139056,0.189865,0.076283,0.030138,-0.126357,0.056936,-0.538935,-0.021329,0.140542,-0.103687,-0.506494,0.544730,-0.248511,-0.047920,-0.073278,0.122505,0.219308,-0.045460,0.246241,0.080585,0.113621,0.093126,-0.065389,0.257430,0.653578,0.076194,0.182611,-0.075851,0.004031,-0.155718,0.258249,-0.302563,-0.285618,-0.333623,0.186799,-0.070134,0.114279,0.221824,-0.104619,0.155892,-0.173926,0.203772,0.035859,-0.321745,0.027464,-0.310050,-0.257262,-0.329341,-0.097156,0.470938,0.148416,-0.310755,0.603061,-0.107171,0.003611,0.183505,0.291966,-0.458071,0.684041,0.047062,-0.059335,-0.115572,-0.321229,0.357713,-0.067333,-0.024668,0.106980,-0.033291,-0.173685,0.234868,-0.287800,0.003965', '3230460', '3212120', '3078390', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308851', '地狱男爵', '动作', '二战末期，溃败的德军为了扭转局势，竟然找来了一个邪恶的巫师，企图利用他召唤出地狱男爵，打败盟军。幸亏盟军的突击队在他们进行仪式时及时赶到，顺利挫败了他们的阴谋，但这时候地狱男爵——1个婴儿已经被召唤出来了，盟军见此只好收养了他。教授布鲁姆（约翰•赫特 John Hurt  饰）是地狱男爵（朗•普尔曼 Ron Perlman 饰）的养父，他用自己的善良循循教导着男爵，男爵则利用自己刀枪不入的身体和通天本领为美国政府完成了多项特种任务。然而，阴暗邪恶的本性还是一直潜藏在男爵的心底，最终人类的善良能否战胜来自地狱的邪恶？©豆瓣', '朗·普尔曼', '吉尔莫·德尔·托罗', 7, 73085, 'tt0167190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2193565611.jpg', 0.7, 5.2, 46.4, 37.5, 10.2, '0.126393,0.402685,-0.486514,0.735377,-0.364623,-0.245794,0.622308,-0.071267,-0.218932,-0.294667,0.480875,0.777336,0.064661,-0.018305,0.173033,0.151160,-0.365361,-0.437623,-0.309578,-0.002564,-0.233388,-0.356673,-0.578464,-0.280012,0.187612,-0.553891,0.746696,0.369055,-0.122591,0.175405,0.343191,0.645980,0.038567,0.410766,-0.190481,-0.117910,0.148221,-0.360987,0.036954,0.213245,0.082717,-0.035296,-0.097196,0.377320,-0.027375,0.488354,0.565513,-0.767074,-0.000809,-0.189292,0.315303,-0.669852,0.100295,0.308811,0.370500,-0.168324,0.041271,0.104084,0.180034,0.102988,-0.038478,-0.150435,-1.141540,-0.227594,-0.119110,-0.197825,-0.390809,0.192895,-0.236944,0.440902,0.259860,-0.192745,0.170864,0.311124,-0.030894,0.438479,-0.267099,0.068607,-0.597016,0.018910,0.516765,-0.333674,-0.568691,-0.089065,-0.294553,-0.537442,0.034634,-0.447700,-0.256543,-0.143857,0.571297,0.066313,-0.250186,0.203008,-0.680855,-0.269322,-0.600218,0.137131,-0.068769,-0.487080,-0.017434,-0.425966,-0.220784,0.050702,-0.145529,-0.145550,0.033899,-0.090247,0.674381,-0.762762,0.198417,0.730166,0.150256,-0.212193,0.338196,-0.008278,-0.017057,-0.051263,0.035980,0.422760,0.102356,0.558930,0.315643,0.582683,0.123620,-0.003075,-0.143648,0.495893', '1308585', '3769423', '3213270', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308854', '撒玛利亚女孩', '剧情', '少女倚隽（郭智敏 饰）和洁蓉（韩业云 饰）梦想着去欧洲旅行，为了筹得费用，她们决定由洁蓉援助交际出卖肉体，而倚隽为她招揽生意打理钱财。越来越多的男人宣泄他们的欲望，两个女孩子离梦想里的欧洲越来越近。一次警方突然到旅馆搜查卖淫，脱逃的洁蓉从窗口跳下，受了重伤。倚隽背着她到医院 ，洁蓉渴求倚隽带她心爱的男人来见最后一面。男子答应去见洁蓉，却提出要和倚隽性交。清纯的倚隽不能接受这般惊诧的想法，但为了好友，她最终献出了自己的身体。只是谁都无法挽救洁蓉的死亡，倚隽拿出以前的记录，一个一个联系男人赎罪般出卖肉体，将原先的钱散还回去。做侦探的父亲勇基（李乌饰）知道后万分愤怒和痛苦。他报复这些嫖客并杀死其中一人。之后，他带着女儿到乡下祭奠死去的母亲……©豆瓣', '韩业云', '金基德', 7.4, 46626, 'tt0397619', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p462398519.jpg', 1, 4.4, 33.5, 44.5, 16.6, '0.148458,0.064339,-0.677962,0.490258,-0.447411,-0.385370,0.862427,0.129056,-0.257751,-0.049757,0.220780,0.672518,0.109144,0.280759,0.072050,-0.079725,-0.055057,-0.720180,-0.204648,-0.028841,-0.315214,-0.099986,-0.028784,-0.102732,-0.247600,-0.117057,0.511508,-0.036509,0.071560,0.306622,0.202498,0.241672,-0.200527,0.444210,-0.323483,-0.076687,-0.439836,0.047535,-0.142323,0.491372,0.244053,-0.131460,-0.243381,0.332225,-0.320448,0.280589,0.788636,-0.041067,-0.104580,-0.229839,0.136965,-0.274087,0.018612,0.270843,-0.032833,0.061324,0.068140,0.190102,-0.426776,-0.055260,0.103710,0.182780,-0.753267,-0.090881,-0.030663,0.069217,-0.778841,0.497970,-0.119378,0.324506,0.200048,-0.500481,0.140561,0.276451,-0.113803,0.251258,-0.402658,0.169023,-0.491101,0.214080,0.616731,-0.101999,0.354276,0.358865,-0.371370,-0.255656,0.118656,-0.079207,-0.596681,-0.248198,-0.127540,-0.024162,-0.264466,-0.309524,-0.365592,-0.176192,-0.309938,0.008568,-0.035340,-0.456082,-0.051887,-0.176964,-0.170144,-0.072908,-0.176290,0.290846,0.193378,-0.322430,0.347317,-0.374060,0.163042,0.766512,0.543373,-0.333289,0.619328,-0.116081,0.002374,-0.001311,-0.250219,0.417833,-0.045534,0.193834,-0.062430,0.096657,0.121535,0.208538,-0.410479,0.405262', '21619567', '1297606', '25917973', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308855', '大事件', '剧情', '香港警队被元（任贤齐 饰）率领的悍匪打得无力还击的一幕被电视摄制队拍了下来，全港市民哗然。为了声誉，全港3万多的警员都投入到缉拿重犯的行动中。重案组督察恒（张家辉 饰）跟踪元到了一栋大厦，在他们正想行动时，副指挥官Rebecca（陈慧琳 饰）却打算把整个过程通过电视现场直播。恒与其他队员都带上了微型摄影机冲入了现场，大厦内早已躲着另一班劫匪，形势凶险，Rebecca却想剪掉此片断。在大厦内挟持人质的元把在闭路电视上录到的警匪搏击片段发给了传媒，警方更加尴尬了。元挟持人质对抗警察，恒救出了人质，逃跑了的元遇到了Rebecca，Rebecca从未见过恒跟元，便误以为元是警察恒，元将计就计，想借此脱身。©豆瓣', '陈慧琳', '杜琪峰', 6.8, 54429, 'tt0414931', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2003332263.jpg', 0.9, 7, 49.8, 33.7, 8.6, '0.150767,-0.105538,-0.622204,0.279431,0.201647,0.003851,0.547090,0.316449,-0.632556,-0.062803,0.235025,0.076741,-0.358493,0.271036,0.315739,-0.200689,-0.596860,-0.687616,-0.466107,-0.337933,-0.271268,-0.309044,-0.279496,0.036808,0.079196,-0.300652,0.438974,0.181873,-0.428450,0.136039,0.412240,0.258092,-0.419284,0.377121,-0.055018,0.083186,0.114140,-0.581204,-0.336679,-0.050424,-0.098318,-0.787356,0.001431,0.335323,0.185897,0.468318,1.049774,0.089581,0.130798,0.260143,-0.002056,-0.413494,-0.082274,0.042960,0.313353,0.320434,0.051928,0.082208,-0.176834,0.635221,0.015834,0.011523,-0.793470,0.374208,0.048423,0.101598,-0.551679,0.375957,-0.321238,0.531633,0.011491,0.080011,0.344741,0.307506,-0.098960,0.141529,0.004701,-0.019256,-0.787695,0.167557,0.673590,-0.291513,0.071937,0.316838,0.367052,-0.359198,-0.368328,-0.072066,0.163304,-0.096083,0.601255,-0.264886,0.095633,-0.140939,-0.327937,-0.265553,-0.322635,-0.096412,-0.187485,-0.068003,-0.122960,-0.808420,0.386024,0.215857,0.058070,0.300654,-0.061052,-0.034950,0.652170,-0.329560,-0.247679,0.550758,0.585462,-0.507982,0.415633,-0.357196,0.223206,0.079621,0.099998,-0.481747,0.613760,0.616745,0.543365,0.336527,-0.466772,-0.440721,-0.171254,-0.240496', '1295547', '26747274', '1307897', '25785807');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308857', '可可西里', '剧情', '尕玉（张磊 饰）本来是个警察，为了调查藏羚羊猎杀状况，他假扮记者身份，随考察团来到可可西里——那里气候寒冷、空气稀薄，含氧量极低。就在这个人类生存的“禁区”，尕玉目睹了一幕幕人性的贪婪以及人类与环境的狂暴冲突。首先是藏羚羊保护站的巡山队员被盗猎人枪杀，接下来他们见到了悲惨的一幕：盗猎者逃走，只留下众多只剩嶙峋白骨的藏羚羊。巡山队员在恶劣的环境中追捕凶手，最终只夺回了一部份的藏羚羊皮毛。一方面要与恶劣的自然环境抗争、另一方面还要与凶残的盗猎者周旋，巡山队员和尕玉面临着生死考验。©豆瓣', '多布杰', '陆川', 8.9, 281974, 'tt0386651', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363208684.jpg', 0.2, 0.5, 8.2, 38.2, 52.9, '0.089082,-0.339246,-0.559024,0.527597,-0.195232,0.027101,0.688155,-0.092555,-0.430722,-0.184490,0.423235,0.382161,0.119240,-0.047279,0.024909,-0.099835,-0.269938,-0.492923,-0.494662,0.081375,-0.393109,-0.156511,-0.474926,-0.389779,0.144588,-0.341793,0.751860,0.340241,-0.507638,0.452259,0.163684,0.296579,-0.661083,0.239536,-0.264160,-0.262281,0.047730,-0.135710,-0.245196,-0.101923,-0.108363,-0.348367,-0.309893,-0.010936,0.169199,0.541618,0.803838,-0.661036,-0.482960,-0.149316,-0.064030,-0.652086,0.062505,-0.005907,0.506216,-0.332709,0.127408,0.191160,0.007477,0.101833,-0.230795,-0.100104,-0.765989,0.212844,0.176992,0.227899,-0.657778,0.392319,-0.028698,0.181580,0.210022,0.043651,0.286427,0.251372,-0.042375,0.350552,-0.101681,-0.376241,-0.345470,0.200202,0.843820,-0.232507,0.103110,-0.141143,-0.226011,-0.614342,-0.110612,-0.076395,-0.060582,-0.072378,0.462307,-0.107236,-0.262922,0.251006,-0.931329,0.212334,-0.151558,-0.310186,-0.219520,-0.255891,-0.197433,-0.538187,-0.084171,-0.253526,-0.135960,0.359701,0.049606,-0.377619,0.573146,-0.617670,-0.033737,0.552947,0.301421,-0.538710,0.307503,-0.164937,0.138204,-0.156076,-0.243552,0.173760,0.311257,0.317235,0.196443,0.189924,-0.053947,-0.108909,-0.399104,0.228064', '7056398', '25774050', '24879819', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308858', '麦兜，菠萝油王子', '剧情', '随着城市发展，麦兜住的旧区大脚咀也卷入了拆迁漩涡。不过无忧无虑的麦兜从来不会去考虑拆迁对他意味着什么，春田花花幼稚园又开学了。为了适应激烈的社会竞争，春天花花幼稚园也加入很多令人捧腹的新课程：耍赖、诈死等等。麦太在樟木头买了块墓地，为了日后能有个安身之所。时光飞逝，一切又回到了从前，回到了麦兜的父亲菠萝油王子的时代。王子跟随着师傅出行，不料遇到了一连串怪事，王子不再是王子，有人变成了他的样子回去当了王子。浑浑噩噩的菠萝油认识了阿莲——以后的麦太，过着平平凡凡、庸庸碌碌的生活，只是在夜里，菠萝油偶然会想起他的王国、眼里会呛着泪花。阿莲怀孕了，菠萝油重遇了以前送薄饼的龟仔、一起出行的师傅，他们决定回去复国了。于是菠萝油告别了阿莲，告诉他如果明天听不到一个王子复国的新闻，那就永远忘了他……©豆瓣', '李颖贤', '袁建滔', 8.1, 49974, 'tt0419954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p805075384.jpg', 0.4, 2, 21.8, 44.5, 31.4, '0.267528,0.002619,-0.488038,0.285632,-0.097153,-0.382287,0.550736,0.170085,-0.270662,-0.168598,-0.240435,0.628681,-0.268993,0.292613,0.205107,0.091234,-0.096213,-0.383521,0.112490,-0.262570,-0.149334,-0.244393,0.243558,-0.166328,-0.032640,0.084939,0.386238,0.040319,-0.091679,0.270168,0.225903,-0.139670,0.123385,0.548897,-0.344538,0.258468,-0.206142,0.305974,-0.135577,0.249661,0.323873,-0.090578,-0.063232,0.000867,0.358965,-0.056659,0.525057,-0.166354,-0.181419,0.055937,0.342047,-0.191367,0.030001,0.039763,0.286972,-0.035231,0.050908,0.100875,-0.088685,-0.150140,0.055850,-0.146703,-0.266109,0.050327,-0.203174,0.050906,-0.835092,0.317649,0.116224,-0.055788,0.196140,-0.398819,0.405842,0.568393,0.321476,0.408607,0.072157,0.159398,-0.701865,0.397974,0.775420,-0.033143,-0.008659,0.424769,0.051107,-0.308471,0.153897,-0.045659,-0.409910,0.050480,0.309030,-0.109192,-0.539134,0.477285,-0.354044,-0.137969,-0.260185,-0.243341,0.268266,-0.400838,-0.026777,-0.059572,-0.021853,-0.280562,-0.089346,0.276169,0.045064,-0.110977,0.471813,-1.022545,0.336370,0.647543,0.440764,-0.303029,0.525283,0.186782,0.035140,-0.260210,0.328625,0.018214,-0.049840,0.485380,0.381189,0.442209,0.311415,-0.294220,-0.329604,0.396000', '1299965', '2124718', '1299062', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308859', '星际传奇2', '动作', '从第一集里的星球逃出之后，因为在逃杀人犯的身份，瑞迪克（范·迪塞尔 Vin Diesel 饰）为了不断躲避赏金猎人的追捕，不断在各个星球之间游走，摆脱追捕。而整个宇宙，此时却笼罩在黑暗恐怖之中。一个名叫劳德·马歇尔（科鲁姆·费奥瑞 Colm Feore 饰）的统治者，正 打着宗教的旗号，在全宇宙展开侵略。因为在上一集里面所救的小女孩儿基拉（艾莉克莎·黛沃洛斯 Alexa Davalos 饰）不幸被囚禁在了一颗昼夜温差极大的星球上。为了救出她，瑞迪克不惜向赏金猎人低头，让他们将自己带到这颗星球的监狱里。在救出基拉的过程中，瑞迪克获得元素种族大使亚伦（朱迪·丹奇 Judi Dench 饰）的帮助，并逐渐帮他找回了自己的身世之谜。原来，这场星际浩劫的挑起者劳德•马歇尔正是当年摧毁瑞迪克的星球的人。为了报仇，瑞迪克向星际之王发起了挑战……©豆瓣', '范·迪塞尔', '大卫·杜西', 6.9, 24621, 'tt0296572', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2410141725.jpg', 1.4, 7.6, 45.9, 33.9, 11.3, '0.009425,0.540144,-0.908043,0.661476,0.138970,-0.010875,0.654412,-0.031152,-0.252072,-0.150148,0.043472,0.796290,-0.072352,0.064438,0.487870,0.316570,-0.423351,-0.560464,-0.230829,-0.336320,-0.566813,-0.554507,-0.584913,-0.308992,-0.094147,-0.611501,0.718821,0.196193,-0.403677,0.166714,0.266716,0.588606,-0.322016,0.258733,-0.113693,-0.062707,0.084082,-0.354081,-0.412417,0.339836,-0.127005,-0.333522,-0.055951,0.429439,-0.034198,0.292014,0.851910,-0.885658,0.505512,-0.332394,0.108653,-0.572732,-0.130078,-0.347937,0.269754,-0.103793,-0.031351,0.194448,-0.045183,0.041265,0.325499,-0.308325,-0.891921,-0.013940,0.176636,0.406538,-0.442009,0.403728,0.073164,0.104439,-0.014028,-0.071156,0.198900,0.393396,-0.166339,0.298680,-0.332844,0.110678,-0.499850,-0.069920,0.523341,-0.092907,-0.132181,0.199516,-0.139079,-0.211170,-0.055598,-0.157394,-0.566598,-0.340753,0.504517,0.032427,0.036032,0.535761,-0.699753,0.040624,-0.636513,-0.247187,0.128526,-0.203279,-0.271104,-0.639577,-0.025224,-0.081241,-0.111794,0.112457,-0.122246,-0.319143,0.561929,-0.728884,0.271702,0.626212,0.397680,-0.264198,0.416848,-0.111410,0.357722,-0.228887,-0.246965,0.198498,0.438925,0.350409,0.184675,0.078315,-0.107353,0.005600,-0.251038,0.556964', '25774050', '3213270', '1308585', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308865', '老男孩', '剧情', '女儿生日那天，中年男子吴大修（崔岷植饰）在醉酒回家路上，突遭不明身份的人绑架失踪。就此，他毫无理由地被囚禁在一个神秘的私人监狱中。寻死未果的吴大修，每天看电视，三餐吃煎饺。通过电视，他得知妻子已遭杀害，女儿下落不明，自己更被怀疑为凶手。就此，吴大修开始锻炼身体，决心复仇，并在牢中度过漫长的15年。当吴秘密挖通墙壁时，却在某一天被放出，得以重见天日。他不顾一切地寻找自己被绑架囚禁的原因，并展开疯狂的复仇计划。他遇见了年轻的寿司女店员（姜惠贞饰），并借助同窗老友追寻仇人，成功惩罚了监狱看守（吴达庶饰）一番。与此同时，幕后仇人李有真（刘智泰饰）也浮出水面……©豆瓣', '崔岷植', '朴赞郁', 8.3, 277241, 'tt0364569', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2166892850.jpg', 0.9, 2.3, 15.9, 45.1, 35.8, '-0.232865,0.017948,-0.550957,0.328546,-0.173745,-0.233512,0.747408,-0.024998,-0.541785,-0.567816,0.062295,0.282871,-0.307604,0.491251,0.247863,-0.227671,-0.045152,-0.518029,0.147925,0.034538,-0.109162,-0.285306,-0.172351,-0.438942,-0.006214,0.021197,0.528752,0.389397,-0.125660,0.056359,0.397160,0.106135,-0.246186,0.619908,-0.135494,0.152050,0.008362,0.052941,-0.209330,0.040554,0.013240,-0.635389,0.113074,0.151351,-0.177165,0.465911,0.578844,-0.077371,-0.178292,-0.295290,0.256585,-0.423829,-0.123635,0.238836,0.580037,0.103489,-0.140296,0.276031,-0.208826,-0.032383,0.178441,-0.233716,-0.495824,-0.222441,0.122746,-0.169957,-0.232224,0.012152,-0.045511,0.297429,0.062557,-0.112962,0.109864,0.401527,0.382999,0.293269,-0.036741,0.114224,-0.544778,0.322862,0.613047,-0.187749,0.271663,0.121104,0.139014,-0.336651,0.333221,-0.185268,-0.191912,0.094830,0.513474,0.126525,-0.293973,0.279547,-0.140916,-0.280717,-0.321193,0.110991,0.128684,-0.248092,-0.165418,-0.452591,0.103778,0.210706,-0.051145,0.104664,-0.129439,-0.535041,0.171262,-0.527373,0.448277,0.492789,0.291792,-0.629542,0.430915,0.096329,0.080194,-0.204327,0.094416,0.467739,0.334103,0.321730,0.132495,-0.038219,-0.092705,0.169889,-0.302862,0.179064', '25870679', '1304665', '3263169', '26897427');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308866', '安娜与武林', '喜剧', '公关公司主管阿健（郑伊健 饰）无意中提出的举办下一届武林大会的主意获得客户肯定，并投入巨资要他办得漂漂亮亮。武林大会开始并没有引起各门派的兴趣，阿健只好去找连续3届的武林盟主大成寺，请求他们出赛。大成寺主持慧智承诺只要阿健到日本他的师弟石剑的武馆取回武林至尊的锦旗他就参赛。阿健来到日本，巧遇了石剑的女儿安娜（杨千嬅 饰）。当阿健去到武馆讨要锦旗时，被误认为来踢馆。关键时刻幸得安娜相救，阿健骗安娜说武林大会会有好莱坞的导演来选角，因石剑有病在身，从小向往好莱坞的安娜独自带着锦旗与阿健回港参赛了。慧智遵守诺言也参赛了，这下引起江湖个各派的注意，纷纷来港参赛。武林大会就在浩浩荡荡的声势开幕了……©豆瓣', '杨千嬅', '叶伟民', 5.2, 22622, 'tt0395942', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p482194056.jpg', 8.1, 35.3, 48.6, 6.2, 1.8, '-0.105376,0.206455,-0.522261,0.446955,-0.070793,-0.086256,0.078856,0.148681,-0.199918,-0.045697,0.472248,0.967345,-0.219812,0.279606,0.346898,0.020194,0.063174,-0.618281,-0.116693,-0.166886,-0.204618,-0.156199,0.342823,0.190283,-0.151809,-0.096329,0.300928,-0.056337,-0.398613,0.658161,0.384929,-0.101956,0.170347,0.544543,-0.192491,-0.076903,0.226841,0.205109,-0.160113,0.259135,-0.130526,-0.325050,-0.397993,0.194040,0.327450,0.289112,0.340933,0.221730,0.031687,-0.066176,0.326052,-0.067432,0.213640,0.044261,0.511165,0.217582,0.085227,0.400593,-0.124242,0.076389,-0.078782,-0.272402,-0.508101,0.248658,0.408524,-0.084116,-0.651146,0.507120,-0.088678,-0.050948,-0.126971,-0.216443,0.110160,0.448257,-0.021189,-0.161403,0.189259,-0.120116,-0.526045,0.494662,0.594559,-0.244428,0.254689,-0.113971,0.301173,-0.399626,0.238483,-0.131667,-0.015738,0.138910,0.551639,-0.431716,-0.035993,-0.079789,-0.333436,-0.100429,-0.099498,-0.362506,0.058951,-0.185143,0.295658,-0.921799,0.106524,0.129952,-0.240220,-0.211473,0.316613,0.065100,0.789233,-0.757933,0.171609,0.569894,0.234156,-0.397566,0.806027,0.211367,0.037415,-0.161145,-0.290050,-0.211240,-0.089921,0.763374,-0.016054,0.333932,0.318186,-0.421513,-0.080927,0.075695', '25833539', '1829654', '26365262', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308890', '军官与男孩', '剧情', '三十年后，已经成为一名舞蹈家的杰罗恩，因一张旧照片而回想起幼年时那段难忘的同性爱情。1944年，杰罗恩（马腾·斯密特 Maarten Smit 饰）被母亲从阿姆斯特丹送回乡下小镇生活。翌年战争结束，一队加拿大官兵在这个荷兰小镇驻扎，杰罗恩邂逅了其中一名俊朗潇洒的军官。与其他军官不同，这名军官对杰罗恩特别眷顾。随后他们度过了一段美好的时光，奇妙的爱情在二人之间发生了。然而，当杰罗恩还沉浸在爱情的浪漫与喜悦中时，军队却撤走了，昔日他们朝夕相处的小屋，已经变得空荡荡……三十年后的他，借着曾经的旧照片，寄托了自己对那名军官最深刻的情思……本片根据著名舞蹈家鲁迪方丹斯的自传小说改编，获1996年度荷兰影展最佳影片提名。©豆瓣', '马腾·斯密特', '罗兰·克博施', 8, 11123, 'tt0108504', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2510280264.jpg', 0.7, 2.2, 22.2, 44.7, 30.1, '0.309956,0.030558,-0.692620,0.707591,0.242574,-0.410715,1.111515,-0.168370,-0.488938,-0.368067,0.186904,0.971872,-0.142136,0.469862,0.523759,-0.149910,-0.447262,-0.960310,-0.140804,-0.411308,-0.327119,-0.221614,-0.328884,-0.053619,-0.140199,-0.599977,0.895164,0.246822,-0.069925,0.663860,0.096713,0.196264,-0.215527,0.322568,-0.338682,0.268061,0.329065,0.125293,-0.496377,-0.068658,-0.225858,-0.306988,-0.328494,-0.103597,-0.196876,0.185957,0.982229,-0.237208,-0.200007,0.082184,0.458293,-0.054271,-0.326363,0.064613,0.240754,0.085787,0.028805,0.200039,-0.120895,0.062973,-0.282557,-0.155541,-0.562748,-0.114030,-0.122174,0.151928,-0.484703,0.779706,0.075988,0.129152,0.220070,-0.187892,0.161517,0.358959,0.088934,0.414935,-0.017185,-0.019640,-0.353242,0.738071,0.819093,-0.122997,-0.455472,0.493143,-0.398827,-0.490842,-0.024553,0.043663,-0.512771,0.203065,0.401662,-0.175323,0.119011,0.236893,-0.740312,0.108801,-0.144721,-0.187782,0.107737,-0.253068,-0.342342,-0.737670,-0.314523,-0.419162,-0.261272,0.091355,0.161816,0.002498,0.844768,-0.571479,0.362426,0.264648,0.016510,-0.204715,0.631788,0.201048,0.293926,-0.162895,-0.018906,0.642357,-0.042899,0.279759,0.023139,0.305829,-0.440203,-0.042885,-0.618291,0.551613', '1467779', '3811356', '1307146', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308892', '新世纪福音战士剧场版：Air/真心为你', '剧情', '神秘的EVA零号机驾驶员绫波丽，在与碇元度约定之时，来到了NERV底层中央教条的红色水池边。她的命运似乎就将在此结束。在危急时刻，葛城美里不但要完成加持良治交待的对“第二次浩劫”真相以及“人类补完计划”的探查工作，还要保护碇真嗣与明日香，以及防备SEELE 对初号机与二号机的物理接触。出于对碇元度的憎恨，赤木律子接受了SEELE引爆MAGI的提案，她能否成功？长期与SEELE共事的碇元度、冬月耕造、碇唯，为了防止人类“最终的悲剧”，而酝酿了的“人类补完计划”能否实现？尽在《新世纪福音战士》电影版第2部中解答。©豆瓣', '绪方惠美', '庵野秀明', 9.5, 73807, 'tt0169858', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2250316512.jpg', 0.4, 0.5, 3.7, 16.4, 79, '0.070245,0.293403,-0.438130,0.553998,-0.218184,-0.334366,0.488768,0.205827,-0.175422,-0.177720,0.334070,0.367526,-0.290961,-0.145377,0.241259,-0.048166,-0.377145,-0.648693,-0.352685,0.029401,-0.381816,-0.729721,-0.276528,-0.228025,-0.135353,-0.326736,1.068009,0.210957,-0.257447,-0.087934,0.172638,0.536364,-0.459041,0.454681,0.158570,-0.236909,-0.192459,-0.034520,-0.603708,0.397114,-0.004929,-0.316352,0.027804,0.246135,-0.106074,0.285657,0.707231,-0.485378,-0.375041,0.032164,0.210177,-0.396730,-0.023003,0.430159,0.300636,-0.021628,-0.243457,0.587602,-0.089909,0.085467,-0.055210,0.019967,-0.852552,-0.384556,-0.093505,-0.057645,-0.279750,0.371305,-0.246147,0.099993,0.494568,-0.386218,0.099811,0.671672,0.343999,0.300717,-0.467046,0.091718,-0.003583,0.061553,0.366347,-0.341765,-0.199346,0.316391,0.135324,-0.481245,-0.436988,-0.089936,-0.150077,-0.067384,-0.023306,0.374726,-0.129496,0.144110,-0.726712,-0.271918,-0.195291,-0.357316,0.164482,-0.199486,0.052943,-0.706887,-0.088153,-0.314297,-0.213600,0.213301,0.172644,-0.370545,0.819780,-0.993910,0.324698,0.640526,0.346536,-0.347024,0.316964,0.399182,0.227652,-0.500588,0.081942,0.138562,-0.085789,0.512630,0.046705,0.337473,0.098653,0.125938,-0.592063,0.357788', '2369613', '26759819', '3861846', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308912', '力王', '动作', '贺力王（樊少皇 饰）自幼蛮力过人，后经家族之世交善鬼（丹波哲郎 饰）指点，习得精纯硬气功。力王女友莹莹意外撞破毒贩交易，毒贩将莹莹捉回使其坠楼身亡，力王击毙毒贩为女友报仇，因此被关入国分监狱。时值2001年，监狱被私人承包成为盈利工具，犯人遭受残暴对待苦不堪言。力王不能容忍国分监狱北仓杀手山猫欺凌弱小，出手将其重伤，触怒北仓天王鸣海，副监狱长单眼蛇挑斗二人对决，力王出手轰杀鸣海，自此卷入与国分监狱四仓中其他三大天王黄泉、泰山、白神的连番战斗。力王烧毁监狱中的罂粟地，使度假归来的监狱所长（何家驹 饰）大为光火，而同样习练硬气功的所长，将是力王最强大的敌人……本片根据同名日本漫画改编。©豆瓣', '樊少皇', '蓝乃才', 7.1, 39262, 'tt0102293', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1259775131.jpg', 2.3, 7.6, 40.1, 33.6, 16.4, '0.049716,-0.128739,-0.222942,0.267426,0.081642,0.107255,0.419090,0.093147,-0.484430,-0.252037,0.517337,0.345504,-0.047835,-0.053909,0.046264,-0.330996,0.194845,-0.339176,-0.319492,-0.057294,0.070575,-0.188212,-0.185042,0.022323,0.049621,-0.296347,0.614806,-0.040437,-0.437694,0.377734,0.116909,0.529631,-0.187694,-0.081915,0.097597,0.031426,0.000784,-0.265767,-0.359873,0.213249,-0.404682,-0.181041,0.104584,0.021144,-0.007548,0.145206,0.597565,-0.139398,-0.066418,-0.785407,0.384956,-0.361931,-0.273401,0.175365,0.415288,0.111126,0.195613,0.323332,-0.052531,-0.001806,0.245102,0.014613,-0.582292,0.037862,0.233621,-0.202162,-0.240815,0.224154,-0.099278,0.334498,-0.074947,0.031270,0.094555,0.139547,0.258810,0.130922,0.014622,0.007767,-0.395698,0.249070,0.660858,-0.644134,-0.098919,-0.402847,0.229585,-0.335394,0.180361,-0.613165,0.096688,-0.052490,0.414790,-0.117452,0.130189,0.410676,-0.255327,-0.401997,-0.515121,0.229470,-0.030331,-0.053845,-0.099658,-0.670530,-0.167404,-0.003582,-0.190346,-0.159697,0.318145,-0.156926,0.434036,-0.507010,0.047970,0.325279,0.454393,-0.348989,0.415823,-0.114765,0.116736,-0.154350,-0.100137,0.174216,0.739777,0.367603,0.218733,0.195222,-0.254254,-0.144574,-0.143826,-0.056051', '2369613', '2980431', '1306894', '25919961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308927', '笑林小子2：新乌龙院', '喜剧', '前一阵子销声匿迹的女魔头天魔再次出山，这次她的目的是印在乌龙院里面壁大师右手掌舵洗髓经。于是，天魔收买了糊涂杀手黄柠檬（张卫健 饰）和红柠檬（叶全真 饰），派两人前往乌龙院砍下面壁大师的右手掌带回来。黄柠檬和红柠檬来到乌龙院后，遇上了寺内三名行踪怪诞的弟子，这三人不时与其师父（李明炀 饰）斗法，红、黄柠檬却认为这三人不简单。这三名弟子行为古怪，不时出现爆笑场面。最后红、黄柠檬能否完成任务？©豆瓣', '郝劭文', '朱延平', 7.9, 62449, 'tt0111766', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167117517.jpg', 0.3, 1.6, 25, 50.6, 22.5, '0.054771,0.412621,-0.182525,0.588277,0.203107,-0.017282,0.445693,0.249082,-0.229098,-0.200987,0.020701,0.249587,-0.338433,0.078099,-0.036764,-0.013187,-0.149642,-0.425318,-0.271349,-0.482282,-0.352723,-0.099074,0.009960,-0.244033,0.032001,-0.076918,0.195106,0.288598,-0.313059,0.199981,0.717006,0.136684,-0.516658,0.090056,0.156652,0.141569,0.244826,-0.137031,-0.127517,0.043999,-0.052418,-0.273391,0.053668,-0.070946,0.248063,0.399990,0.365557,-0.145778,-0.156299,-0.175299,-0.367548,-0.153185,-0.169955,0.136258,0.450704,0.134541,0.562530,-0.137579,0.166645,0.092296,-0.137887,-0.235265,-0.349235,0.449622,0.330486,0.113143,-0.265898,0.094052,-0.306637,0.448302,-0.200663,-0.373546,0.033020,0.077310,0.268228,-0.111161,0.326478,0.202696,-0.188597,0.264302,0.468245,-0.054184,0.472892,-0.072516,0.102096,-0.318734,-0.153206,-0.011411,0.202146,0.147395,0.846719,-0.141686,0.374994,-0.002421,-0.410766,-0.078259,-0.110690,0.091110,-0.019728,0.296073,-0.173988,-0.386259,0.139269,-0.179171,-0.343331,-0.110215,-0.023577,-0.114981,0.357808,-0.595512,0.250766,-0.242280,-0.225180,-0.256197,0.434560,-0.046978,-0.256682,-0.253402,-0.123915,-0.111490,0.161667,0.502591,0.643299,0.482939,-0.125795,-0.148609,-0.070273,-0.339078', '26665875', '1292440', '1307582', '1890558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308950', '亚历山大大帝', '剧情', '本片拍摄耗时94天，而男主角柯林·法瑞尔在拍摄期间曾经摔断手臂和摔伤脚踝。影片讲述了Alexander（柯林·法瑞尔 Colin Farrell 饰）年轻时的梦想、荣耀与冒险生活，他征服世界后的孤独生活以及神秘的死亡。他与将军Hephaistion（杰瑞德·莱托 Jared Leto 饰）不寻常的关系也得意展现。Alexander的母亲（安吉丽娜·朱莉 Angelina Jolie 饰）也在他的生命中起到不同凡响的影响力。亚历山大自幼聪颖过人，曾受教于亚利斯多德，稍长即被授予首府总督之职，并以平定山贼有功而任命为马其顿大军统帅，随父横扫希腊城邦之乱。融合东西文化，鼓励民族间通婚，并倡导民族间地位平等，讲希腊思想律法散布各地，开创希腊化时代文化，死时却年仅33岁。©豆瓣', '科林·法瑞尔', '奥利佛·斯通', 7.6, 25016, 'tt0346491', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2159775856.jpg', 0.8, 4.6, 31.2, 41.4, 22, '-0.074742,0.249219,-0.493551,0.707480,0.357947,0.020852,0.355908,0.236347,-0.412548,-0.509459,-0.001043,0.638255,0.018030,-0.135891,0.527274,-0.169492,-0.301661,-0.826079,0.087568,0.039425,-0.163402,-0.313900,-0.169085,-0.309334,-0.343506,-0.799543,0.725839,0.067636,-0.372118,0.523890,0.003931,0.126213,-0.112034,0.229685,-0.106066,-0.233586,0.133855,0.106717,-0.422048,-0.051667,-0.183971,-0.229949,-0.011338,0.061035,-0.120692,0.232618,0.328807,-0.399307,0.193851,-0.348745,0.302444,0.047787,-0.055311,-0.004730,0.269915,0.105521,0.167280,0.536222,0.284047,0.080849,-0.002366,-0.395237,-0.607754,-0.207746,0.068784,0.079871,-0.371011,0.689900,0.075088,-0.166067,-0.124307,-0.099066,0.066559,0.402732,0.322054,0.439704,0.003848,0.178298,-0.162624,0.361435,0.401307,-0.263183,-0.505056,0.093199,-0.500067,-0.499546,-0.016087,-0.244571,-0.389156,-0.073425,-0.116672,-0.036943,0.256022,0.560809,-0.556864,0.023932,-0.305937,-0.013699,0.228822,-0.147844,0.127142,-0.394163,-0.347005,-0.520247,-0.237437,-0.136468,0.435580,-0.243585,0.710114,-0.597078,0.078721,0.226072,0.517318,-0.537930,0.644811,0.175404,0.140170,-0.360875,-0.219933,0.849923,0.021561,-0.004722,-0.186290,0.021108,-0.137193,-0.302636,-0.172161,0.576190', '26647163', '1780122', '1303034', '1295804');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308960', '金赛性学教授', '剧情', '美国印第安纳大学的教授阿尔弗莱德·金赛在1939年发表了震惊世界的《金赛性学报告》，这部迄今为止最为完整和坦率的性生态学调查的学术基础，是面谈了12000名美国人的惊人工作量。在金赛（连姆·尼森 Liam Neeson 饰）对学生们的访谈培训中，他一生的故事娓娓道来……金赛出生在一个由父亲强力掌控的家庭，热爱自然的金赛在青年时终于摆脱了父亲钳制，选择了心仪的生物学研究，在大学任教时，金赛与研究生麦克米兰（劳拉·琳妮 Laura Linney 饰）结为伉俪。婚后他继续着自己的瘿峰研究，然而在与学生的接触中，他发现道德教条造成的性困惑无处不在，于是开始调整自己的研究方向……©豆瓣', '连姆·尼森', '比尔·康顿', 7.8, 8447, 'tt0362269', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2165597986.jpg', 0.3, 1.6, 25.6, 52, 20.5, '0.463191,-0.140329,-0.603265,0.693814,-0.220435,-0.255085,0.404807,0.114863,-0.608275,-0.218963,0.191297,0.644808,-0.144352,0.521031,0.316225,-0.103872,-0.234731,-0.788975,0.117960,-0.328874,-0.278296,-0.658479,-0.251149,-0.290861,-0.095655,-0.628005,0.726573,-0.052768,-0.401795,0.544030,0.012070,0.390309,0.142609,0.286167,-0.178954,0.027889,0.281384,0.113626,-0.345652,0.163958,0.270079,-0.234999,-0.267759,0.079447,0.004074,0.286494,0.767498,-0.298237,-0.166779,-0.190256,0.670630,-0.288501,-0.221099,0.207711,0.441964,0.248321,0.024711,0.498962,-0.164223,0.066799,-0.105329,-0.189755,-0.585518,-0.255038,0.150277,0.256019,-0.910935,0.754529,-0.012147,-0.187662,0.056586,-0.273313,-0.100972,0.314351,-0.000603,0.459745,-0.132229,0.061538,-0.073301,0.505864,0.376148,-0.130543,-0.355398,0.350066,-0.220597,-0.619787,-0.126369,-0.003266,-0.366238,-0.179693,0.165551,0.073836,-0.286555,0.121280,-0.561342,-0.058548,0.046338,-0.186545,0.073394,-0.546368,-0.058717,-0.868017,-0.272551,-0.401343,-0.425271,0.000894,0.077715,-0.414162,1.111542,-0.943373,0.128482,0.326961,0.341838,-0.385880,0.857340,0.091865,0.253769,-0.314847,-0.135897,0.318696,-0.035245,0.334515,-0.148656,0.559544,0.240170,-0.238865,-0.508368,0.597466', '1308609', '3811356', '25922902', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308973', '时差7小时', '喜剧', '16岁的中国女孩珍（妞妞 饰）独身赴英国留学，当她在伦敦机场徘徊之际，校方派来接站的香港留学生DJ（陈冠希 饰）心不在焉的出现了，DJ索要了珍的小费之后带她参观校园，珍的土气举动让DJ啼笑皆非。因为自己的音乐梦想，DJ被负责任的钢琴教师盯住不放，昔日的橄榄球队友汤姆看着DJ远去的背影只能徒呼奈何。珍在周围同学的捉弄中渐渐适应着留学生活，阴差阳错又接下橄榄球队后勤经理的苦差，但珍用自己的乐观勤勉打动同学们并最终扭转了他们的态度。橄榄球队成绩不佳，珍出面招募新队员的同时DJ和汤姆为争夺珍暗中较劲。校际橄榄球比赛开始了，曾经是球队主力的DJ无法在琴房中安心练琴，他最终还是奔向了心爱的球场……©豆瓣', '陈冠希', '刘晓光', 4.3, 7132, 'tt0408930', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2256196246.jpg', 38, 24.9, 26.3, 7.4, 3.4, '0.324032,0.063276,-0.554176,0.557379,-0.077811,-0.368703,0.347595,0.257546,-0.431023,-0.157825,-0.001730,0.721231,-0.134798,0.557891,0.146832,-0.081745,-0.234560,-0.978375,-0.447643,-0.102419,-0.266925,-0.376324,0.116737,-0.204334,-0.051389,-0.155774,0.519610,0.070901,-0.088460,0.691382,0.407577,0.357781,0.056285,0.315468,-0.289925,0.003962,0.275731,0.116060,-0.003974,0.010289,0.290217,-0.424833,-0.372386,0.230120,0.264289,0.445846,0.990582,0.029400,0.110447,-0.030317,0.127391,-0.270035,-0.069190,0.054930,0.135479,0.103890,-0.012678,-0.021804,-0.154943,0.217537,-0.256467,-0.032574,-0.458633,0.216846,0.170385,0.023283,-0.645619,0.615260,0.039845,0.182062,0.086761,-0.128961,0.237179,0.300466,-0.076016,0.299853,-0.062427,0.095990,-0.207585,0.445780,0.655633,-0.003529,-0.115647,0.261134,-0.501523,-0.161567,0.342470,-0.264195,-0.633748,-0.102435,0.284509,0.024105,0.178573,-0.280207,-0.562837,-0.053359,-0.299972,-0.286543,-0.043062,-0.580689,0.009937,-0.742564,0.206144,-0.436491,-0.182418,0.215896,-0.248658,-0.122264,0.747096,-0.871915,-0.215530,0.708313,0.329589,-0.462028,0.778612,-0.167323,0.015938,-0.204433,-0.161252,0.075872,-0.298274,0.269060,0.057380,0.382153,-0.104993,-0.337747,-0.534735,0.359954', '3811356', '3041753', '3155839', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308974', '偷心', '剧情', '四个男女之间的反复关系，在爱情里追逐和厌倦。丹（裘德·洛 Jude Law 饰）是作家，他爱上了舞女爱丽丝（娜塔丽·波特曼 Natalie Portman 饰）。丹对爱丽丝炽热燃烧的爱情给了他灵感和激情，但厌倦也随之而来，他内心在寻找另一个人的爱，终于他遇上了摄影师安娜 （朱莉娅·罗伯茨 Julia Roberts 饰）。安娜和另一个年轻人拉里（克里夫·欧文 Clive Owen饰），在爱的游戏里相互试探和接近。但是丹的进攻也让她动了情。讽刺的是，安娜的情人拉里，也和爱丽丝有了瓜葛。于是，躺在他们身边的人，未必是他们心里想念的那人。©豆瓣', '朱莉娅·罗伯茨', '迈克·尼科尔斯', 7.8, 158279, 'tt0376541', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1457195667.jpg', 0.4, 2.6, 26.9, 45.7, 24.4, '0.474820,0.020674,-0.935599,0.760383,-0.105445,-0.027113,1.136282,0.180615,-0.529387,0.146432,-0.067736,0.858292,-0.210567,0.350946,0.045005,0.380558,-0.480877,-0.936416,0.255960,-0.044160,-0.266816,-0.466616,-0.132039,-0.454788,-0.016912,-0.247920,0.460800,0.089664,-0.036263,0.550326,0.517582,0.196546,0.276086,0.728784,0.062549,0.345747,0.273430,-0.012344,0.072919,0.209514,0.250603,-0.261276,-0.028288,0.329927,0.132118,0.522149,0.527408,-0.292763,0.169494,0.100428,-0.080634,-0.305240,0.117940,0.143643,-0.193280,-0.054241,0.372723,0.072012,-0.214967,-0.012563,0.070915,0.096371,-0.801039,0.130202,0.082700,0.156004,-0.683219,0.892357,-0.154762,-0.100948,0.083400,-0.058150,0.319958,0.138265,0.128585,0.186256,-0.078948,-0.280747,-0.579942,0.057024,0.624673,0.301396,-0.158304,0.608328,-0.504821,-0.453552,-0.447956,0.016405,-0.495397,-0.329399,0.426503,0.031883,-0.151691,-0.013973,-0.772150,0.243252,-0.020875,0.294645,-0.174322,-0.706979,-0.012219,-0.381316,-0.236785,-0.765485,-0.610945,-0.012208,0.040381,-0.423265,0.840575,-0.883715,0.101428,0.558145,0.375635,-0.495315,1.009091,0.255100,-0.191199,-0.269963,-0.052670,0.584324,-0.258119,-0.067389,0.342292,0.438868,0.079332,0.320325,-0.506223,0.628273', '1417428', '1292211', '3111650', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308975', '西班牙女佣', '剧情', '为了过上更好的生活，漂亮的单身母亲芙兰（帕姿•薇阁 饰）带着她12岁的女儿，从墨西哥搬家到美国这个自由国度。经朋友介绍，芙兰受雇到一个上等家庭做女管家。而语言的不同，沟通的障碍，文化的差异，成为芙兰新生活道路上最大的绊脚石。主人约翰（亚当•桑德勒饰）和黛博拉（蒂亚•李欧妮 饰）夫妇虽然都很善良，但他们与芙兰在生活方式以及对待孩子的态度上的分歧，也着实令芙兰伤透了脑筋。要完全融入美国上流社会，芙兰还需经历一些坎坷。脉脉温情笼罩下的文化冲突，悄然上演……©豆瓣', '亚当·桑德勒', '詹姆斯·L·布鲁克斯', 7.3, 5278, 'tt0371246', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1452974197.jpg', 0.6, 5.2, 37.4, 41.6, 15.3, '0.588607,0.212249,-0.593991,0.753286,-0.111749,-0.312148,0.749734,0.118078,-0.305568,-0.127997,0.150917,0.720342,-0.174237,0.254491,0.421877,0.089532,-0.429884,-0.601727,0.086657,-0.122269,-0.365505,-0.563553,-0.050195,0.040146,-0.222411,-0.290814,0.473632,-0.279336,-0.004315,0.527548,0.084484,0.245576,-0.083994,0.262925,-0.074574,0.003214,-0.102392,0.300884,-0.541357,0.061363,-0.014819,0.037104,0.002768,0.254941,-0.051311,0.347496,0.771531,-0.283495,-0.010834,-0.127267,0.232731,-0.131377,0.084970,0.148095,0.051589,-0.055050,0.244829,0.333088,-0.218067,-0.020369,-0.102300,-0.300228,-0.749452,0.020029,0.401891,0.165110,-0.622137,0.441086,0.276313,-0.069573,-0.144334,-0.435730,0.039289,0.444645,0.177969,0.578449,-0.243035,0.229573,-0.403569,0.074359,0.688757,-0.085817,-0.405480,0.390066,-0.436293,-0.442139,-0.000994,-0.346839,-0.586777,-0.208788,-0.093523,-0.138173,-0.251749,0.354143,-0.842202,0.190195,-0.202347,-0.257099,0.231653,-0.510479,0.344328,-0.587025,-0.319376,-0.884968,-0.598519,0.113376,0.194476,-0.369482,0.784956,-0.801071,0.113497,0.474985,0.361308,-0.542899,0.645130,0.079243,0.092744,-0.398398,-0.381748,0.592030,-0.064241,0.016690,-0.113487,0.305439,0.065369,0.017319,-0.328027,0.568671', '1309161', '24756472', '26354526', '2998373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308976', '水中生活', '剧情', '史蒂夫（比尔·默瑞 Bill Murray 饰）是一名海洋纪录片导演，他的作品曾经为许多孩子的童年披上了梦幻的色彩。在一次拍摄中，史蒂夫的老朋友死于美洲虎鲨之口，这让史蒂夫深受打击，他发誓要找到虎鲨，为友报仇，并且将此作为新片的题材。在发布会上，史蒂夫遇见了自称是自己儿子的耐德（欧文·威尔逊 Owen Wilson 饰），他遂邀请这个年轻人加入他的创作团队。史蒂夫要面临的难题很多，资金短缺，和妻子的感情不和，并且，他所拍摄的纪录片已经渐渐的失去了吸引力。一位名叫珍妮（凯特·布兰切特 Cate Blanchett）的记者加入了史蒂夫的团队，她要为他写一本个人传记，然而，她和史蒂夫的相处并不融洽，倒是和耐德越走越近，这让史蒂夫醋意大发。同时，耐德的真实身份也让史蒂夫心寸怀疑。一群海盗的光临让史蒂夫的计划彻底破产，一名船员也惨遭绑架，面对这样糟糕的境况，身经百战的史蒂夫能够完成他的复仇计划吗？', '比尔·默瑞', '韦斯·安德森', 7.8, 18292, 'tt0362270', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1565327013.jpg', 0.5, 2.3, 25.8, 48.4, 23, '0.255890,-0.128848,-0.572952,0.690533,-0.141931,-0.482523,0.811787,0.045145,-0.475273,-0.249392,0.227267,1.053163,-0.175928,0.234161,0.326628,0.038535,-0.319871,-0.577907,-0.065932,0.097018,-0.066785,-0.512807,-0.502004,-0.259117,-0.117892,-0.286684,0.788940,0.079942,-0.230964,0.326672,0.336353,0.332422,0.249146,0.552426,-0.141663,0.088317,0.247114,-0.139007,-0.218789,0.275385,0.073606,-0.137758,-0.045121,0.481178,-0.080447,0.292465,0.518765,-0.135459,-0.228831,-0.033585,0.416279,-0.563569,0.190423,0.111856,0.082321,-0.074672,0.110710,0.259104,-0.186156,0.024493,-0.168678,-0.139347,-1.098162,0.138291,0.104730,0.208553,-0.701705,0.360641,-0.339414,-0.064031,0.152484,-0.074782,0.067669,0.448227,0.352241,0.236834,-0.132434,-0.045444,-0.511604,0.238647,0.776170,0.068104,-0.043735,0.413328,-0.341410,-0.313163,-0.150681,-0.132092,-0.679138,0.120628,0.357953,-0.044085,-0.160092,0.156026,-0.592248,-0.189364,-0.269138,-0.248137,-0.243969,-0.451957,0.053611,-0.564354,-0.276468,-0.345832,-0.301620,-0.252369,0.113910,-0.371677,0.793335,-0.725613,0.067171,0.464416,0.167195,-0.551238,0.583449,0.368249,0.005849,-0.170204,-0.020620,0.088495,-0.041128,0.081132,0.072638,0.427745,0.300102,-0.374819,-0.300905,0.602694', '1793491', '34890458', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308978', '刀锋战士3', '动作', '叙利亚沙漠中，女吸血鬼丹尼卡（Parker Posey 饰）带领一队同类，深入古老的沙漠宫殿，意欲唤醒沉睡的吸血鬼之王——德雷克（Dominic Purcell 饰）。夜色中，刀锋（韦斯利•斯奈普斯 Wesley Snipes 饰）仍然与吸血鬼们进行着无休止的战斗，但他很快落入了丹尼卡的圈套，误杀了一名人类，因此被FBI探员威尔逊等人抓捕。与此同时，刀锋的老搭档惠斯勒之女阿比盖尔（Jessica Biel 饰）同汉尼拔金（Ryan Reynolds 饰）等年轻人秉持与刀锋相近的信念，组成了一支以自身为诱饵来消灭吸血鬼的队伍，他们将刀锋从FBI和丹尼卡手中救出，但后者对他们的胆大妄为嗤之以鼻，然而面对强大的吸血鬼王德雷克，他们不得不并肩作战……©豆瓣', '韦斯利·斯奈普斯', '大卫·S·高耶', 6.7, 41034, 'tt0359013', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1370036189.jpg', 1.3, 8.5, 54.2, 27.5, 8.5, '0.229382,0.212425,-0.573365,0.776946,0.059195,-0.143812,0.988959,0.154742,-0.209472,-0.250901,0.432398,0.649993,0.096952,-0.180686,0.306998,-0.240447,-0.299341,-0.676691,-0.175320,0.061074,-0.627070,-0.318957,-0.387385,-0.305136,-0.156330,-0.279428,0.695395,0.116773,-0.189570,0.515656,0.191702,0.623476,-0.288125,0.205395,-0.121694,-0.282948,0.273330,-0.439748,-0.258710,0.216515,-0.236400,0.045806,-0.200240,0.085618,-0.038710,0.270548,0.890933,-0.601701,0.346219,-0.359978,-0.137838,-0.459477,0.084552,0.200354,0.328923,-0.014826,0.032076,0.022669,0.127795,0.004329,-0.113989,-0.203380,-0.891365,0.029370,-0.121825,-0.013000,-0.512142,0.187218,-0.050131,0.016861,0.254161,-0.059884,-0.004192,0.033064,0.317769,0.037625,0.048856,-0.226219,-0.544291,-0.005192,0.510680,-0.050341,-0.569946,-0.183306,-0.111971,-0.634294,-0.268291,-0.128211,-0.312800,-0.233772,0.691598,0.261337,-0.183023,0.318226,-0.907257,-0.213540,-0.456319,-0.011884,0.053484,-0.490033,-0.219431,-0.694427,-0.240041,-0.473381,-0.153680,0.161067,0.067076,0.220083,0.666895,-0.661827,0.101810,0.507189,0.308011,-0.114306,0.552746,-0.162684,0.187513,-0.092841,-0.128211,0.319535,0.640104,0.157661,0.565148,0.273352,-0.162664,0.094514,-0.293596,0.353122', '25774050', '21619567', '2988294', '1578502');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308979', '雷蒙·斯尼奇的不幸历险', '喜剧', '三姐弟在一场大火中失去了父母，继承了父母留下的一大笔遗产。因为年龄尚小，只能到了法定年龄才能动用这笔钱。于是，三姐弟被暂时带到远房亲戚奥拉夫（金·凯瑞 Jim Carrey饰）家，由奥拉夫来抚养。姐姐维奥莱特（艾米莉·布朗宁 Emily Browning饰）是个善于发明创作的小精灵，弟弟克劳斯则博闻强识，是个地道的小博士。最小的孩子有一口锋利的牙齿，呀呀说些姐姐哥哥才能听得懂的话。这次三姐弟却落进了奥拉夫的圈套里，被这个贪婪的亲戚盯上了那笔遗产。他们一次次陷入险境，看来奥拉夫非把他们害死不可。于是，他们逃到了做生物学家的叔叔家里，然而这里却满是蛇类动物，颇为惊悚。更不妙的是，奥拉夫像摆脱不掉的影子跟随而至。三个孩子继续出逃，在发现姑妈家也不是去处时，他们决定自力更生，跟邪恶的奥拉夫周旋到底。©豆瓣', '金·凯瑞', '布拉德·塞伯宁', 7.6, 41101, 'tt0339291', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2410157066.jpg', 0.6, 3.8, 32.1, 44, 19.5, '0.210078,-0.093694,-0.465719,0.381408,-0.396811,-0.492254,0.645698,0.015435,-0.412454,-0.176967,-0.011802,0.736283,0.178513,0.337182,-0.080979,-0.065660,-0.084973,-0.325569,-0.063178,-0.247051,-0.128248,-0.710048,0.038609,0.074452,-0.029348,-0.090120,0.292008,-0.110301,-0.019262,0.280196,0.246100,0.320496,-0.161203,0.081023,-0.159383,0.215608,-0.080830,-0.027509,-0.142874,0.233481,0.100479,0.121820,-0.162944,0.021376,0.291762,0.288951,0.556589,-0.372344,0.082735,-0.233804,0.092481,-0.304173,-0.092899,0.163202,0.267350,-0.243014,0.430448,0.123021,-0.294245,0.003647,0.224229,-0.113530,-0.771206,0.176592,0.158897,-0.080631,-0.725624,0.145613,-0.025805,-0.201285,0.147138,-0.506064,0.326352,0.294766,0.121286,0.509199,-0.431961,0.060129,-0.687421,-0.087779,0.678892,-0.190815,0.012552,0.004814,-0.024133,-0.270952,0.216102,-0.457201,-0.320806,0.012772,0.587786,0.249378,-0.282303,0.292014,-0.414281,-0.263183,-0.317388,-0.135028,0.038192,-0.700124,-0.157040,-0.077713,-0.021946,-0.317629,-0.132267,0.264806,0.175271,-0.288978,0.701634,-0.645627,0.112586,0.348140,0.396039,-0.406833,0.435417,0.059112,0.309442,-0.085301,-0.077923,-0.125645,0.197067,-0.063043,0.476801,0.080442,0.045910,-0.154149,-0.294927,0.241306', '1877596', '1291586', '35048413', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308982', '凤凰劫', '剧情', '机长弗兰克（丹尼斯·奎德 Dennis Quaid 饰）与飞机打交道多年，这次他将负责一架“凤凰号”货机，运送一批石油工人和物资到北京去。然而令他意想不到的是，飞机在途中遇到了风暴，弗兰克不得不迫降在荒无人烟的内蒙古戈壁滩上。幸好死伤人员并不多，然而他们的储备水却只够维持一个月的使用，但在一个月内能等到救援的可能性有如买彩票。饥饿和慌张中，幸存者间开始了各种意见分歧与争吵。最后一名自称是飞机设计师的乘客提议，用飞机残骸再造一架飞机自救。然而造飞机并非想象中那么简单，人心在不断尝试中渐渐消耗，仅存的生命之水也越来越少，重伤的“凤凰”还能否在广漠戈壁中涅槃重生？本片翻拍自1965年同名电影，两者皆改编自英国小说家Elleston Trevor的同名小说。©豆瓣', '丹尼斯·奎德', '约翰·摩尔', 6.6, 5070, 'tt0377062', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p812802430.jpg', 1.2, 8.3, 55.2, 28, 7.3, '0.088382,0.164434,-0.873598,0.444983,0.198793,-0.187984,0.610334,-0.204017,-0.378719,-0.125438,0.227873,0.734058,-0.003702,-0.162854,0.135149,-0.254354,-0.369319,-0.249856,0.116134,-0.132752,-0.328765,-0.520731,-0.440598,-0.220028,0.005169,-0.544181,0.669172,0.439736,-0.021589,0.500125,-0.054475,0.034132,-0.195850,0.616381,-0.227083,-0.154448,-0.012856,0.071412,-0.074704,0.400791,-0.143991,-0.448142,0.056000,-0.101306,0.313656,0.444589,0.826462,-0.067159,-0.102043,0.135868,0.136372,-0.234843,0.017578,-0.169155,0.416798,0.253657,0.135720,0.021023,-0.280110,0.208006,-0.103610,0.157508,-0.499413,-0.116103,-0.223659,-0.034995,-0.670224,0.360711,-0.030227,-0.076094,-0.075545,-0.224444,0.318435,0.236173,0.035509,0.456371,-0.283034,-0.240340,-0.674628,0.355687,0.701150,-0.054434,-0.306271,0.488448,0.111130,-0.516921,-0.090383,-0.377914,-0.175294,-0.022241,0.243601,-0.037976,-0.225765,0.175673,-0.796634,0.408071,-0.245840,-0.429967,-0.206257,-0.075639,-0.056565,-0.872570,0.219945,-0.249254,0.032644,0.198901,0.463640,-0.176427,0.693363,-0.587951,0.045462,0.500764,0.207466,-0.259604,0.478477,-0.062710,0.073210,0.037336,0.113399,-0.011346,-0.029880,0.423404,0.212754,0.233480,-0.034275,-0.057479,-0.314143,0.187206', '1307897', '2159244', '1294917', '1293019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308983', '苹果核战记', '动作', '2131年，地球爆发大规模的世界大战，各大主要城市尽成废墟，人们流离失所。讽刺的是，这场摧毁人类文明的大战最终没有任何战胜国。幸存的人类将原来的综合管理机构改造成名为奥林帕斯的基地，以此作为幸存者的理想国。少女琉南•纳兹在一座废弃城市与火力强大的人造人展开激烈战斗，危急时刻，她的前男友布里亚留斯和美丽女孩瞳带领奥林帕斯的小分队赶来营救。布里亚留斯之前在北非战场失去大部分身体，如今也被改造成机械加身的人造人。结束了枕戈待旦的日子，琉南开始迎来平静祥和的生活。她发现奥林帕斯的科技极为发达，而这里相当数量的人类是人造人。这座过分祥和的理想国让琉南心有不安，它的背后似乎隐藏着不为人知的秘密……©豆瓣', '小林爱', '荒牧伸志', 7.5, 14063, 'tt0401233', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p454037622.jpg', 0.6, 3.4, 32.7, 45.8, 17.5, '0.140010,0.139283,-0.954130,0.460780,-0.016494,0.342254,0.793675,-0.235402,-0.687063,-0.196324,0.373870,0.617976,-0.078989,-0.047526,0.136022,-0.119519,-0.340675,-0.355408,-0.316284,0.079767,-0.331712,-0.366089,-0.593985,-0.344341,-0.075654,-0.648734,0.880509,0.484026,-0.303161,0.207264,-0.212720,0.352324,-0.118963,0.427011,-0.213036,-0.297582,-0.061111,-0.292817,-0.197004,0.201401,-0.437631,-0.144134,-0.287846,0.387880,-0.125541,0.432504,0.636001,-0.291466,-0.163498,-0.270975,0.311057,-0.435091,-0.209004,-0.008640,0.519510,-0.162537,-0.130976,0.086608,-0.052302,-0.236533,0.045772,-0.193273,-0.842679,0.003712,0.240608,0.017530,-0.380759,0.715368,0.130356,-0.021129,0.067761,-0.125592,0.293468,0.596428,0.306597,0.371644,0.013296,0.026031,-0.631416,0.140557,0.811366,-0.175408,-0.765283,0.101265,-0.348507,-0.504359,-0.289758,-0.631589,-0.352122,-0.075157,0.109030,-0.006515,-0.048252,0.595949,-0.934592,0.244715,-0.261808,-0.567968,0.008919,-0.254084,-0.326581,-0.770330,-0.310890,-0.384265,-0.129604,0.203193,-0.110859,-0.104210,0.928959,-0.773558,0.249789,0.422077,0.431634,-0.389783,0.510939,-0.266826,0.136551,-0.178362,-0.138905,0.454573,-0.107312,0.418339,0.027130,0.153091,-0.135522,-0.031626,-0.494337,0.563850', '26667010', '1578502', '3005387', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308987', '拜见岳父大人2', '喜剧', '格雷戈（Ben Stiller 本•斯蒂勒 饰）在上一集过五关、斩六将，终于凭着一份执着感动了未来岳父（罗伯特•德尼罗 Robert De Niro 饰），答应了他和潘米拉（Teri Polo特莉•保罗 饰）的婚事。本以为就此抱得美人归，然而，别忘了，还有亲家互相见面这一关。格雷戈的父母不像他们的亲家一般古板、对子女高要求、拒绝新事物。他们的教育方式另有一套：他们会为格雷戈在比赛中得第十名而高兴、会像朋友一样取消笑格雷戈的初夜失身、会以开放的姿态看待性、父亲会以母亲的成就为骄傲等等。这样两家风格完全不一样的亲家聚头，无论什么样的荒诞搞笑、无厘头场面都有可能发生，这对准新人能否顺利度过这一关?©豆瓣', '本·斯蒂勒', '杰伊·罗奇', 7.1, 33335, 'tt0290002', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p635968845.jpg', 0.4, 3.6, 45.6, 40.3, 10.1, '0.055782,-0.060347,-0.531542,0.448034,-0.171968,-0.235161,0.238683,0.125900,-0.289492,-0.117922,0.161151,0.825929,-0.255160,-0.046007,0.175198,-0.041824,-0.140430,-0.700233,-0.000894,-0.121494,0.002218,-0.612778,-0.090371,-0.178187,0.127939,-0.224336,0.158249,0.021652,-0.104984,0.334482,0.540208,0.184191,0.238168,-0.029646,-0.136156,-0.053934,-0.057972,0.615423,-0.524116,0.073666,-0.175580,0.389501,0.068967,0.010490,0.150865,0.245905,0.229123,-0.353600,-0.516782,0.204469,0.386803,-0.068286,0.193852,0.508865,0.115094,-0.105529,0.295711,0.200784,-0.139812,-0.031527,0.055042,-0.290182,-0.709374,0.141321,-0.063710,0.004971,-0.362664,0.324096,0.141983,-0.042088,0.141106,-0.230962,-0.056889,0.521112,0.637306,0.353584,-0.014406,0.138084,-0.304339,0.178537,0.705660,0.024751,-0.350410,0.094591,-0.313910,-0.210461,0.071633,-0.525864,-0.701584,0.194483,0.218360,0.088012,0.091734,0.302383,-0.096556,-0.130527,-0.116026,0.271149,0.054378,-0.565732,0.340433,-0.305198,-0.041810,-0.583978,-0.353128,-0.231393,0.068560,-0.692487,0.686374,-0.708867,0.166242,0.046394,0.369203,-0.791777,0.570521,0.568547,0.049697,-0.328284,-0.007238,0.053812,-0.100898,-0.237414,0.128240,0.198157,0.382271,-0.069250,-0.059283,0.291581', '26678784', '4301278', '1877596', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308989', '一酷到底', '喜剧', '奇利·帕尔默（约翰·特拉沃尔塔 John Travolta 饰）曾经是混迹黑道的嚣张人物，不过黑道混久了，或许是因为厌倦，很多人开始洗白自己，找份体面的工作，得到社会的认可。奇利也不例外，从黑道退役后，他摇身变作好莱坞电影制片人，纯熟的社交手段使他的事业蒸蒸日上，名气大增，尝到甜头的奇利开始进军乐坛。他找来一位开唱片公司的朋友，不料朋友却意外死亡，奇利只好寄望于这位朋友的妻子艾迪（乌玛·瑟曼 Uma Thurman 饰），艾迪也是个狠角色，两人磨合良久才达成共识，决意捧红一名有着优异音乐天赋的黑人女孩琳达，然而事情却并非想象中顺利，琳达的经纪人为了留住琳达，使尽刁钻权术，而更令人意想不到的是，琳达竟然同时在被俄罗斯的黑手党秘密追杀。面对混乱的局面，已金盆洗手的奇利是否要重操旧业，摆平一切呢？本片为1995年经典喜剧片《黑道之家》续集，改编自畅销作家艾尔蒙·里欧纳德（Elmore Leonard）的同名小说。', '约翰·特拉沃尔塔', 'F·加里·格雷', 7, 5643, 'tt0377471', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1419739183.jpg', 1.4, 7, 44.6, 34.8, 12.2, '-0.040191,0.011514,-0.400728,0.538277,-0.119681,-0.276183,0.300973,0.108204,-0.484753,-0.442769,0.081300,0.751652,-0.172037,-0.063367,0.250598,0.005382,-0.155031,-0.742980,0.128722,-0.110517,0.207860,-0.306472,-0.589571,-0.287774,-0.332485,-0.131509,0.724563,0.077843,-0.362361,0.126427,0.389956,0.184334,0.118283,0.184366,0.020822,-0.132758,0.234672,0.012068,-0.524391,0.116440,0.048838,-0.112335,-0.315190,0.145770,0.140995,0.305048,0.147540,0.094956,-0.078709,-0.091026,0.510817,-0.227334,-0.190432,-0.114975,0.328088,-0.011528,0.252408,0.180401,-0.136621,0.064815,-0.109296,-0.087562,-0.908211,0.190617,0.317783,0.063463,-0.487803,0.178569,-0.154480,-0.215738,-0.097307,-0.211810,-0.040010,0.224499,0.449212,0.193437,0.143411,0.382829,-0.346465,0.138492,0.602612,0.122982,-0.350749,0.430548,-0.089196,-0.372150,-0.056185,-0.454977,-0.480869,-0.035239,0.127639,-0.185286,-0.060977,0.395421,-0.360733,-0.156772,-0.205020,-0.098165,0.098917,-0.237652,-0.031488,-0.607658,-0.299959,-0.215310,-0.146681,-0.226919,0.173482,-0.346087,0.933742,-0.663698,-0.006192,0.425291,-0.092635,-0.618980,0.553942,0.064318,0.150918,-0.246801,-0.273972,0.265846,0.056190,-0.030182,0.003761,0.001845,-0.099880,-0.474220,0.014956,0.454671', '27602116', '4301278', '24284209', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308991', '神勇奶爸', '剧情', '大块头有大智慧，这仅仅适合形容席恩（范·迪塞尔 Vin Diesel饰）的海军特种部队生涯。他曾经无比神勇，无所不能，是个忠实威猛的军人。但现在，席恩却接到一个令他大为头痛的任务：照顾五个年龄跨度从婴儿期到青春期的孩子，保护他们免受歹徒袭击。于是，席恩皱着眉头开始了他的非常任务。这是另一个没有枪火的战场，席恩必须和五个孩子“周旋斗争”，一边害怕叛逆期的男孩行为出轨，一边担心大吵大哭的婴儿饿了肚子湿了尿布。这个铮铮硬汉，在孩子面前常常束手无策，幸好也慢慢从乱七八糟的状况中理出个头绪来，还威风凛凛地当上了孩子舞台剧的导演呢。眼看孩子照顾得渐入佳境，歹徒的脚步声却越来越近了……©豆瓣', '范·迪塞尔', '亚当·尚克曼', 6.9, 31469, 'tt0395699', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2249301920.jpg', 0.7, 6, 52.3, 32.1, 8.9, '0.084371,-0.117039,-0.730093,0.344364,-0.271897,-0.246223,0.722691,0.235628,-0.478584,-0.356882,0.305788,0.398137,0.003187,0.232947,0.052785,-0.275956,-0.162078,-0.494879,-0.122812,0.160401,-0.458420,-0.206099,-0.201042,-0.318900,-0.119980,-0.368668,0.511056,-0.075651,-0.099451,0.340208,0.372229,-0.045678,0.207687,0.415985,-0.475782,-0.028468,0.114492,-0.022788,0.340930,0.006513,0.139978,-0.085592,-0.048788,0.415092,-0.074479,0.556645,0.639996,-0.225831,-0.133858,0.015441,0.370350,-0.281856,-0.278460,0.077103,0.414500,-0.202012,0.122028,-0.362015,0.085913,-0.056028,-0.063414,-0.037528,-0.787821,0.050884,-0.023367,0.110411,-0.646360,0.229785,-0.113949,0.056176,0.196759,-0.231871,0.142693,0.315847,-0.068154,0.668320,-0.285903,0.262489,-0.512159,0.048937,0.521413,0.049485,-0.137630,0.362789,-0.221834,-0.489038,-0.114463,-0.536060,-0.413654,-0.042170,0.092895,-0.157972,-0.418293,-0.070952,-0.207675,0.197250,-0.102974,-0.021157,-0.265958,-0.366858,-0.206782,-0.160585,0.084254,-0.431398,-0.373172,0.073008,-0.105999,-0.072158,0.838025,-0.530908,-0.075426,0.723429,-0.043087,-0.349180,0.440148,0.388494,0.157280,-0.238688,0.047210,0.138250,0.024234,0.123002,0.308591,0.428594,-0.144180,-0.207115,-0.368076,0.413379', '24284209', '1464907', '25928048', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308993', '灵幻夹克', '剧情', '时空的转换，现在与未来的穿梭，都在杰克（亚德里安·布洛迪 Adrien Brody 饰）身上神奇的发生着。他本来是一个参与过海湾战争的美国军人。意外中弹令他丧失了记忆，成为一个失忆者。继而更倒霉的是，他被警方认作杀人疑犯拉回审讯。因为判定为精神疾病，杰克免于坐牢，只是被带到精神病院，作为某项科学实验的样品。医生为杰克穿上了紧身衣物，把他放进停尸间。这里黑暗冰冷，只剩下零散的记忆碎片陪伴杰克。碎片中有着他将来的模样，有着一个心爱的叫杰基（凯拉·奈特利 Keira Knightley饰）的女子，更有着自己快要死去的讯息。在记忆中看到将来的杰克，在一线希望中寻找着通往生机的钥匙。©豆瓣', '艾德里安·布洛迪', '约翰·梅布里', 7.3, 15759, 'tt0366627', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p863357651.jpg', 0.6, 4.3, 37, 43.3, 14.7, '0.247089,0.188515,-0.452748,0.431799,-0.251155,-0.232789,1.050424,-0.044573,-0.399466,-0.344343,0.169307,0.771962,0.048114,0.408389,0.154800,0.243035,-0.440740,-0.707859,-0.214705,-0.089666,-0.605830,-0.550144,-0.403072,-0.009486,-0.076009,-0.516663,0.678258,0.032836,-0.325961,0.211491,0.196156,0.375025,-0.177765,0.420634,-0.268222,-0.049460,-0.041509,-0.183704,-0.136269,0.269185,0.095712,-0.249514,0.170445,0.107265,-0.260811,0.340117,0.713819,-0.260619,0.104876,-0.073583,0.396745,-0.241696,-0.111339,0.065065,0.006312,0.091796,-0.066430,0.083725,-0.334764,0.159209,0.413831,0.069945,-0.914147,-0.171512,0.060503,0.385316,-0.479484,0.243165,-0.134037,0.099050,0.154603,-0.220924,0.559402,0.059501,0.101148,0.348525,-0.356920,-0.005944,-0.692695,0.058794,0.498330,-0.278289,-0.304107,0.169654,-0.361336,-0.457423,-0.044590,-0.042142,-0.313428,-0.013008,0.457282,0.130621,-0.084445,0.262076,-0.679697,0.037885,-0.292150,-0.227077,-0.301875,-0.216655,-0.207545,-0.294390,-0.140691,-0.195952,-0.553492,-0.073530,-0.076063,-0.378847,0.504035,-0.560782,0.305758,0.486950,0.250730,-0.222774,0.652306,-0.049295,0.363680,-0.200647,-0.033465,0.469565,0.442297,0.304690,0.059162,0.333715,-0.094692,-0.037230,-0.590443,0.564256', '21619567', '2988294', '1307800', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308995', '捉迷藏', '悬疑', '艾米丽（达科塔·范宁）的妈妈死在满是血泊的浴缸里，小女孩深受打击，陷入了孤僻。为了让女儿尽快走出阴霾，大卫（罗伯特·德尼罗）带着女儿搬到了乡村。在这里，艾米丽结识了她的新朋友——查理，他们一直在玩捉迷藏。可是除了艾米丽谁也不知道查理是谁，他似乎活在女儿的假象中，又似乎就游走在他们周围。恐怖事件接二连三的发生，艾米丽变得愈加神情恍惚，大卫渐渐意识到问题的严重性。他开始潜心记录女儿的言行，希望阻止查理接近女儿。可是，查理究竟是谁？他藏在哪？©豆瓣', '罗伯特·德尼罗', '约翰·波尔森', 7.5, 76251, 'tt0382077', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2640472899.jpg', 0.4, 3, 34.3, 47.7, 14.5, '0.059947,-0.071868,-0.805057,0.212716,-0.422262,-0.405780,0.787170,0.036792,-0.702737,-0.185306,0.428236,0.687260,-0.127602,0.345919,-0.005547,0.232091,-0.642138,-0.460979,-0.018007,-0.193092,-0.212756,-0.505041,-0.201494,-0.317671,0.168677,-0.331081,0.345881,-0.084899,-0.127540,-0.047392,0.192150,0.280804,-0.231313,0.715556,-0.072353,0.319600,-0.030343,-0.137437,-0.224523,0.019193,0.196716,-0.312575,-0.415344,0.165105,0.220976,0.303346,0.651802,-0.068684,-0.134496,0.278320,0.222724,-0.277441,-0.132243,0.129787,0.089518,-0.333651,0.041292,0.149846,-0.048687,-0.081103,-0.038871,0.196025,-0.437863,0.362691,0.066067,0.504407,-0.507127,0.213893,-0.071157,-0.180848,0.262955,-0.363103,0.387935,0.264878,-0.018986,0.339828,-0.244623,0.072703,-0.710369,-0.206508,0.585501,-0.163258,0.127748,0.288183,-0.211605,-0.229722,-0.041208,0.055647,-0.583280,-0.168451,0.257075,-0.121847,-0.411988,0.443002,-0.165672,-0.001662,0.043830,-0.413401,-0.090154,-0.451027,-0.201998,-0.200273,-0.169438,-0.447481,-0.171795,-0.331182,-0.248204,-0.363000,0.466749,-0.834679,0.405858,0.592974,0.074435,-0.302893,0.479806,0.073181,-0.043752,-0.142718,-0.145741,0.231670,0.136025,0.122796,0.272274,0.271536,0.062984,0.119617,-0.242816,0.535345', '2002683', '4275444', '1308755', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1308998', '艾丽卡', '动作', '从创世之初开始，正邪两种力量间的争斗就没有终结，他们一方修炼能够起死回生并预见未来的法术，另一方则结成组织不停寻找终极武器的下落。现在，一个女人的出现将影响正邪间的势力平衡。女杀手艾丽卡（珍妮弗·加纳 Jennifer Garner 饰）的父母数年前被人杀死，而她自己也不幸身亡，幸有掌握复活能力的导师将她救活，又传授给艾丽卡诸多本领。艾丽卡在执行一次任务期间，和相邻的马克（高兰·维斯耶克 Goran Visnjic 饰）与阿碧父女结识，这对儿父女令艾丽卡回想起自己曾经拥有的家庭之爱，然而任务目标揭晓，雇主的目标居然是马克父女。艾丽卡为了保护父女俩不惜与杀手集团作战，因艾丽卡阻扰而愤怒的“The Hand”派出最强组合，追杀艾丽卡等人……©豆瓣', '詹妮弗·加纳', '罗伯·鲍曼', 5.4, 8320, 'tt0357277', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2581597354.jpg', 8, 30.1, 47.9, 9.8, 4.2, '0.100205,0.083501,-0.490975,0.748793,-0.166102,-0.138202,0.389823,-0.038897,-0.351585,-0.434346,0.358726,0.752527,0.133395,-0.076505,0.233882,-0.254300,-0.119296,-0.806137,0.229528,-0.064428,-0.285793,-0.533066,-0.364440,-0.340245,-0.014145,-0.540948,0.787476,0.052658,-0.440697,0.178070,0.188759,0.273164,-0.544833,0.320457,0.004201,-0.248638,0.194678,-0.035691,-0.530288,0.334201,-0.136983,-0.123237,-0.055897,0.282886,-0.246895,0.238066,0.615347,-0.347196,0.131107,-0.416907,0.121597,-0.314652,-0.212543,0.012621,0.399910,-0.034874,0.235357,0.380824,0.054227,-0.206202,0.083089,-0.082476,-1.154297,-0.002237,0.278460,0.053777,-0.417081,0.336173,-0.241143,0.018179,0.021091,-0.306443,0.089988,0.688768,0.430166,0.225394,-0.379343,-0.222275,-0.517757,-0.095226,0.785182,-0.466881,-0.130111,0.171262,-0.020891,-0.418609,-0.217707,-0.259310,-0.230616,-0.092830,0.174920,0.524688,0.102252,0.336800,-0.591164,0.086749,-0.441103,0.070275,0.191420,-0.520232,0.077242,-0.741192,-0.159916,-0.031546,-0.515409,0.122082,0.176716,-0.452905,0.794848,-0.866393,0.134595,0.391862,0.387565,-0.641300,0.614518,0.100560,0.427869,-0.648278,-0.268904,0.218136,0.070996,0.145227,0.039826,0.035854,0.047657,0.261906,-0.135327,0.432438', '26678784', '4301278', '1793491', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309000', '火线对峙', '剧情', '洛杉矶警局的谈判专家杰夫（布鲁斯•威利斯 Bruce Willis 饰）在一次解救被劫持人质行动失败后，心灰意冷，觉得自己已经不再适合担当起这份重要的工作，于是申请调职前往一个治安良好小镇的警察局任职，心想在那里平静的度过下半辈子。这天，小镇的三名不良青年意图偷走会计师史密斯（凯文•波拉克 Kevin Pollak 饰）的汽车时，意外令他们困在了一栋豪宅当中，惊慌失措的三人劫持了史密斯一家作人质。一向没有应付过这种场面的小镇警察们一时手忙脚乱。杰夫只能再次出马，重操旧业。同一时候，杰夫的家人也遭到了绑架。杰夫面对这起双面绑架案会如何处理？©豆瓣', '布鲁斯·威利斯', '弗洛朗-埃米利奥·西里', 6.7, 6121, 'tt0340163', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p811244936.jpg', 0.8, 6.8, 55.6, 30.3, 6.5, '0.324152,-0.006282,-0.748829,0.291875,-0.248107,-0.164294,0.484274,0.229434,-0.520321,-0.314783,0.497890,0.656184,-0.011879,0.287164,0.530146,-0.111261,-0.490320,-0.574380,-0.077646,-0.119870,-0.355532,-0.602313,-0.285983,-0.393131,-0.029225,-0.166065,0.351981,0.214815,-0.072017,0.421395,0.252628,0.474938,-0.081596,0.396726,-0.034012,-0.137574,0.470017,-0.216465,-0.374771,0.245839,0.006476,-0.092225,-0.160610,0.188643,0.314830,0.421283,0.615286,0.067483,-0.532800,-0.017020,0.241664,-0.239629,-0.028374,0.059988,0.521299,-0.222944,0.001405,0.253930,-0.371453,-0.032665,0.095268,0.168310,-0.685532,0.161650,-0.060856,0.066314,-0.450282,0.138683,-0.198942,0.155347,-0.118265,-0.287255,0.163835,0.643529,0.311316,0.272264,0.024846,0.112173,-0.325295,0.199704,0.870649,0.007458,-0.108001,0.069318,-0.065329,-0.182803,0.161344,-0.190887,-0.398397,0.041123,0.414889,-0.118422,-0.212711,-0.011877,-0.179534,-0.163778,-0.570582,-0.236023,-0.106209,-0.233667,-0.121388,-0.830720,0.154315,0.095218,-0.261490,0.011225,-0.048865,0.167860,0.379486,-0.606986,0.147305,0.458993,0.069073,-0.460421,0.248445,0.188100,0.328415,-0.127883,-0.058870,-0.086254,0.231286,0.678911,0.111260,0.244788,-0.014123,-0.420111,-0.180516,0.050196', '35287558', '5157137', '11541282', '6007281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309003', '深海长眠', '剧情', '雷蒙（贾维尔•巴尔登 Javier Bardem 饰）在一次跳海运动中出了意外，全身瘫痪。原本英俊壮健的他要在煎熬中度过余生。他忍受着常人无法理解的痛苦中过活了26年，已经无法领会到活着的意义。他一再申请安乐死，却无法获准。他请来律师朱莉娅（贝兰•鲁达 Belén Rueda 饰），这个女人在与雷蒙的相处中慢慢认同了他的观点，她不幸也身患绝症，二人更加惺惺相惜。朱莉娅承诺帮雷蒙出版诗集后，就和他一同赴死。有一个少妇知道了雷蒙的经历，力劝他不要放弃生命，并深深爱上这个不幸的人。然而，这一切都无法把雷蒙从瘫痪的煎熬中重生过来。然而他还等着朱莉娅一起告别这个世界。©豆瓣', '哈维尔·巴登', '亚历杭德罗·阿梅纳瓦尔', 8.3, 20035, 'tt0369702', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p646744389.jpg', 0.3, 1.3, 16.1, 48.7, 33.6, '0.089624,0.190089,-0.894851,0.593666,-0.396996,-0.291386,0.948556,-0.197688,-0.702004,-0.056729,0.066769,0.755733,-0.042145,0.507840,0.160809,-0.000700,-0.394409,-0.757189,0.040864,-0.064824,-0.348375,-0.657879,-0.089846,-0.186897,-0.333392,-0.083594,0.498616,0.230811,0.145613,0.577459,0.350192,0.131081,0.262766,0.909901,-0.103941,0.302203,0.099149,0.028451,-0.205235,0.117896,0.491045,-0.372228,-0.079630,0.630125,0.016825,0.178786,0.508874,-0.410684,-0.003547,-0.041315,0.245093,-0.234490,0.036954,0.547276,-0.155359,-0.070667,0.042760,0.079280,-0.307889,0.151814,0.152857,0.214697,-0.770517,-0.042036,-0.021040,0.201431,-0.707870,0.383370,-0.088717,0.144061,-0.106581,-0.319858,-0.026883,0.264593,0.537412,0.274171,-0.268939,-0.108298,-0.485100,0.410539,0.780107,0.081661,-0.640913,0.388809,-0.462028,-0.541090,-0.135572,-0.053458,-0.669141,-0.061468,0.443509,0.418317,-0.549465,0.213738,-0.157746,-0.116721,-0.222411,-0.195577,-0.357282,-0.305616,0.095988,-0.247209,-0.393937,-0.572869,-0.421842,0.183760,0.001165,-0.473163,0.517352,-0.595795,0.165783,0.450831,0.355549,-0.469600,0.722432,0.303170,0.113622,-0.094305,0.281359,0.793705,-0.224509,0.295479,0.436579,0.547656,0.124231,0.305074,-0.640608,0.758216', '3742987', '2075721', '26245360', '35441371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309004', '孔雀', '剧情', '上世纪七八十年代的河南古城安阳，某个五口之家的姐姐（张静初）、哥哥（冯瓅）和弟弟（吕玉来）在社会剧烈转型时期，踏上不同的人生之路。姐姐二十出头，虽看起来清瘦文静，内心却刚烈执拗，为实现梦想可以将自己豁出，无奈现实无情，经过多次挫败后她学会听天由命；哥哥二十三四岁，因小时得病落下轻微脑疾，父母对他的关爱皆多一层，经人介绍与精明的跛脚姑娘结婚后，他过上自己很满意的日子；弟弟十七八岁，敏感、忧郁，内心世界过于丰富，因为某件事被父亲赶出家门后，开始在外面找寻属于自己的生活，然而所获只是时间将其改造得面目全非。©豆瓣', '张静初', '顾长卫', 8.1, 124990, 'tt0445506', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p672727540.jpg', 0.2, 1.4, 18.9, 50.4, 29.1, '0.211328,0.328791,-0.683234,0.308229,-0.187550,-0.390310,0.790800,-0.142655,-0.671720,-0.180117,0.113858,0.492314,-0.037163,0.340334,0.129605,0.116771,-0.218073,-0.386980,-0.139301,-0.193858,-0.147417,-0.324886,-0.138336,0.111112,-0.291912,-0.381750,0.532423,0.126134,0.175055,0.658672,0.077956,0.045058,0.009697,0.254390,-0.298199,0.040044,-0.203031,0.008138,-0.292753,-0.162125,0.218655,-0.101575,0.022166,0.171725,-0.270490,0.527335,0.572021,0.103698,-0.401470,-0.209629,0.659372,0.009635,-0.227069,0.191691,0.090980,0.250273,0.326186,0.104378,-0.075049,-0.213919,-0.256456,-0.223717,-0.232444,0.162046,0.277728,-0.027080,-0.606208,0.392064,0.000109,-0.184286,0.132005,-0.567942,-0.159953,0.327000,0.283371,0.437165,-0.380073,0.356587,-0.118409,0.319809,0.841362,0.037649,-0.347633,0.388663,-0.121812,-0.463350,0.219123,-0.671742,-0.565225,0.045433,0.024443,-0.025008,-0.235875,0.264362,-0.228478,0.213941,-0.250906,0.057343,0.011855,-0.248691,-0.146869,0.084152,-0.179971,-0.684041,-0.535538,-0.022412,-0.065496,-0.476751,0.665865,-0.759253,0.375132,0.407795,0.561803,-0.437244,0.560868,-0.034249,0.091487,-0.363554,0.170555,0.584476,-0.399961,0.168372,-0.033072,0.251742,-0.259339,0.089161,-0.656612,0.654268', '35030151', '25721544', '1308635', '1307561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309005', '隐剑鬼爪', '剧情', '时值德川幕府末期，海坂藩的下级武士片桐宗藏（永濑正敏 饰）和母亲（倍赏千惠子 饰）、妹妹志乃（田畑智子 饰），以及女佣希惠（松隆子 饰）过着清贫但安乐的生活。母亲过世后，妹妹嫁给了宗藏的好友岛田左门（吉冈秀隆 饰），而希惠却有个不好的婆家。 一日，宗藏偶与希惠在街头重逢，在得知她 倍受婆家人的欺虐后，他怒不可言，将她背回家中收留养病。宗藏心中对希惠尘封已久的爱恋又重新点燃，但他出于各种顾忌，却没敢表明真心。终于，希惠还是离开了宗藏回到家中。而宗藏的同门师兄弟兼好友狭间弥市郎（小泽征悦 饰）因秘密谋反，被捕后越狱出逃，宗藏受命前去追讨。身怀独门秘技隐剑鬼爪的宗藏，将与弥市郎展开一场生死之搏。©豆瓣', '永濑正敏', '山田洋次', 8.2, 7228, 'tt0442286', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p691070850.jpg', 0.2, 0.9, 15.1, 53.7, 30, '0.010359,-0.077926,-0.498949,0.420670,0.162604,-0.310388,0.766698,0.000071,-0.503712,-0.526374,0.168135,0.477745,-0.008923,0.498277,0.172234,0.202032,0.024143,-0.587541,0.073206,-0.034123,0.022751,-0.357682,0.165487,-0.086211,-0.353114,-0.043616,0.713758,0.085892,-0.029473,0.339386,0.294956,0.407656,-0.202864,0.442595,-0.033175,0.424766,-0.333589,0.272909,-0.139528,0.055707,0.105524,-0.349586,-0.386545,-0.072114,0.391822,0.318727,0.577879,-0.354764,-0.164401,-0.311393,0.099904,0.020564,-0.179711,0.474330,0.244411,0.196564,0.052829,0.360727,-0.244195,-0.092162,0.183574,0.078710,-0.158608,-0.065791,0.283890,-0.094716,-0.605832,0.511433,-0.286955,-0.224526,-0.092243,-0.517920,0.009464,0.484664,0.063918,0.096582,-0.307508,-0.055094,-0.218505,0.232753,0.500339,-0.087926,0.367638,0.195769,-0.171184,-0.426678,0.014316,-0.246377,-0.483967,-0.120551,0.253531,-0.042450,-0.086238,0.265428,-0.207257,-0.449079,-0.186928,0.364007,0.123928,-0.355570,0.022748,-0.180832,0.029685,-0.339542,-0.538479,0.157841,0.402747,-0.231465,0.509107,-0.957938,0.158812,0.076861,0.213757,-0.259406,0.437212,0.167551,0.127386,-0.070703,0.095085,0.428562,0.178415,0.335565,0.062820,0.130325,-0.092477,-0.162113,-0.103055,0.057388', '35030151', '1304665', '1301022', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309011', '机器人历险记', '喜剧', '这是一个机器人的故事。机器人的等级取决于制造的材料，由铜制造的罗德尼是机器人中最卑微的。但罗德尼天生并不自卑，他认为自己拥有发明家的大脑。小镇的生活虽然平静，但并不能满足罗德尼的野心，他决定前往“机器人城”拜访著名的发明家“大焊”。于是这天，罗德尼带着自己引以为傲的发明出发了。但是繁华的“机器人城”却令乡下来的罗德尼感到迷惑，幸好一伙被称为“废铜烂铁”的机器人向他伸出了援手，令罗德尼暂时在城里落了脚。与此同时，一伙破坏分子却正在策划着摧毁“机器人城”……©豆瓣', '宝拉·阿巴杜', '克里斯·韦奇', 7.5, 26492, 'tt0358082', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453495354.jpg', 0.4, 2.7, 34.4, 46.2, 16.4, '0.471395,0.205511,-0.536107,0.679197,-0.220698,0.022295,0.840506,0.136810,-0.333361,-0.299227,0.252114,0.644956,0.256304,0.201832,0.137790,-0.001364,-0.214047,-0.213762,-0.153343,-0.168086,-0.353910,-0.439141,-0.250504,-0.550396,-0.039700,-0.513905,0.821335,0.354964,-0.231283,0.310305,0.119975,0.267609,0.030189,0.548881,-0.204600,-0.128757,-0.023018,-0.262924,0.016968,0.155490,-0.247007,0.088425,-0.051062,0.379609,-0.091170,0.547447,0.568638,-0.482390,-0.115187,-0.322629,0.053979,-0.416310,0.119579,-0.162337,0.143655,0.137265,-0.202140,0.081321,-0.081813,0.232676,0.361751,-0.118100,-1.106678,-0.039140,0.237530,-0.033596,-0.744408,0.389920,-0.173824,-0.002651,-0.086368,-0.292500,0.208893,0.248684,0.250756,0.441670,-0.138993,0.251913,-0.629665,0.093228,0.553320,-0.007237,-0.497534,0.279451,-0.271228,-0.538165,-0.107127,-0.444933,-0.321317,-0.285810,0.080467,0.198523,-0.153482,0.144706,-0.594374,-0.029147,-0.095291,-0.228212,0.052052,-0.691139,-0.011307,-0.557526,0.250244,-0.395352,-0.241840,0.078914,0.060440,-0.252992,0.618694,-0.857411,-0.053572,0.632131,0.291141,-0.216500,0.578444,-0.094280,-0.238448,-0.311361,-0.357332,0.247277,0.175971,0.415060,0.124610,0.346695,0.036547,-0.416639,-0.413429,0.827273', '1793491', '3769423', '1811755', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309013', '海南鸡饭', '剧情', '珍（张艾嘉 饰）早年被丈夫抛弃，勤劳持家的她在新加坡开了一家海南鸡饭餐馆，生意兴隆，亦有好友照顾陪伴，然而三个儿子却让她操心不已。得知大儿子和二儿子都是同性恋者之后，思想保守的珍把全部希望寄托在小儿子Leo（LePham Tan 饰）身上，盼望他能够成家生子。然而敏感的母亲却从Leo和同性好友的交往中看出了不妙的势头。于是珍灵机一动，请来漂亮青春的法国女孩（梅拉尼·罗兰 Mélanie Laurent 饰）住进家里，盼望她和儿子可以擦出火花。西方女孩活泼开朗，为这个东方家庭注入不少新鲜活力，也和Leo建立了不错的感情。母亲大为宽慰之时，Leo却因为同性好友的离去而黯然伤神，他开始明白自己无法喜欢面前这个法国女孩，珍的用心良苦付诸东流。同时生意上的挫折，让珍陷入了心情的低谷……©豆瓣', '张艾嘉', '毕国智', 7.1, 11616, 'tt0383388', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1329407642.jpg', 0.7, 4.7, 42, 42.4, 10.2, '0.191831,0.123561,-0.849178,0.566421,-0.024762,-0.503223,0.680058,0.105897,-0.535710,-0.179165,-0.253461,0.806329,-0.151690,0.667638,0.264791,0.154209,-0.097105,-0.851250,-0.070543,-0.032298,-0.205725,-0.294907,-0.140042,-0.136636,-0.318976,-0.310715,0.319524,0.198828,0.040102,0.472788,0.331539,0.369640,0.101551,0.441393,-0.237868,0.190223,-0.242008,0.196099,-0.299681,0.004619,0.207890,-0.086660,-0.009724,0.393317,0.233506,0.435540,0.722002,-0.016579,-0.068676,-0.228546,0.374265,0.077074,-0.020495,0.133669,-0.026545,-0.041099,0.303907,-0.041946,-0.268125,-0.170326,-0.069030,-0.063221,-0.656028,0.062964,0.235559,-0.176757,-0.797274,0.351470,-0.066749,-0.091852,-0.060678,-0.380083,0.403037,0.302341,-0.108931,0.548965,-0.383283,0.169959,-0.438421,0.171707,0.731145,0.044358,0.022123,0.496046,-0.471417,-0.166103,0.308535,-0.265580,-0.526284,-0.044206,0.201196,0.329634,-0.051226,0.109559,-0.349342,0.010288,-0.288572,0.009797,0.305463,-0.503965,-0.091537,-0.221629,-0.221765,-0.628420,-0.609771,0.042842,-0.061915,-0.420821,0.973183,-0.940857,-0.000200,0.241852,0.368224,-0.714676,0.793763,0.090987,0.228349,-0.337797,-0.124007,0.305719,-0.160677,-0.223374,0.063481,0.173963,-0.385176,-0.193302,-0.359833,0.312726', '1292219', '3445516', '1309161', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309015', '摩托日记', '剧情', '电影讲述了一次南美旅程如何激发了切格瓦拉全新的世界观，使得革命热情开始在他心中萌芽生长。格瓦拉（盖尔·加西亚·贝纳尔 Gael García Bernal 饰）当年23岁，意气风发，踌躇满怀，是一个医学院的学生。他对外面的世界抱有强烈的好奇心，于是和朋友艾伯特踏上了拉丁美洲的长长一串旅途中。他们骑上摩托车，风驰电掣的出发了，却不料摩托车很快就报了废。但这却一点没有影响年轻人的激情，二人靠搭便车来完成剩下的旅程。穿过拉丁美洲古老的文明遗址，穿梭于各个国家各色人群中间，他们开始真切感受到社会的真相、生活的苦难。当深入到亚马逊河流域的麻风病人区时，他们被所见所闻深深震撼。切格瓦拉开始思考宏大深奥的命题：人类、社会、经济、文明，人类的苦难、快乐的定义……©豆瓣', '盖尔·加西亚·贝纳尔', '沃尔特·塞勒斯', 8.5, 50937, 'tt0318462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p466727772.jpg', 0.2, 1, 13.5, 45.7, 39.6, '0.366033,0.122782,-0.759141,0.581572,0.015680,-0.117831,0.745266,-0.068780,-0.511094,0.162685,0.109507,0.606004,-0.286324,0.193881,0.255188,-0.099102,-0.415983,-0.562813,0.137231,0.001720,-0.361828,-0.278232,-0.225250,-0.277857,-0.196530,-0.122019,0.665734,0.284044,-0.343533,0.579076,-0.218198,0.221323,-0.080869,0.416826,-0.374426,0.165348,0.250576,0.079146,-0.257284,-0.177019,-0.120372,-0.145072,-0.125007,0.235700,-0.279521,0.200404,0.646012,-0.164840,-0.029465,-0.005211,0.485556,-0.284301,-0.096153,-0.030856,0.086510,0.284269,-0.057552,-0.009339,0.272134,0.006754,-0.307797,-0.288079,-0.431122,-0.190075,-0.123258,0.079106,-0.387783,0.565936,0.113133,-0.145898,0.058804,-0.266774,0.006669,0.285175,0.383887,0.583689,0.023894,0.030731,-0.401466,0.111283,0.575491,-0.241121,-0.597975,0.369545,-0.455042,-0.415549,-0.069788,-0.016664,-0.299577,-0.259013,0.390701,0.195669,-0.391553,0.468614,-0.648464,0.270484,-0.140606,-0.539182,0.195275,-0.399848,-0.246732,-0.415448,-0.330494,-0.498889,-0.203966,-0.024699,0.020620,-0.065373,0.891012,-0.497168,0.135767,0.469418,0.146015,-0.357753,0.582157,-0.208542,0.008301,-0.213919,0.230800,0.482297,-0.282922,0.420263,0.080640,0.405242,-0.103488,0.182459,-0.444675,0.592037', '2053515', '25882279', '30162520', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309016', '百万美元宝贝', '剧情', '年迈的法兰基（克林特·伊斯特伍德 Clint Eastwood 饰）是一个有名的拳击教练，他的徒弟在拳击场上战绩辉煌。但因为太过于投身与拳击事业，忽略了家人的感受，法兰基与女儿的关系长期冰封，他亦因此陷入了长期的自我封闭和压抑。一天，一个对拳击有强烈兴趣的女子麦琪（希拉里·斯万克 Hilary Swank 饰）走进训练馆，请求法兰基受为门徒。坚毅的决心软化了法兰基，他终于决定把麦琪培养成出色的女拳击手。尽管路很艰辛，但是二人在训练和比赛中默契的相处磨合，令法兰基内心得到了亲情的抚慰，而麦琪也登上了拳击场。勇气和梦想让他们放下了往日的痛苦，心中有了新的力量。本片荣获第77届奥斯卡最佳影片、最佳导演、最佳女主角、最佳男配角4项大奖。©豆瓣', '克林特·伊斯特伍德', '克林特·伊斯特伍德', 8.7, 207708, 'tt0405159', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1734930026.jpg', 0.1, 0.5, 9.3, 42.8, 47.3, '-0.025233,-0.148826,-0.551892,0.659932,-0.037862,-0.389298,0.555793,0.220851,-0.535707,-0.018639,0.181473,0.789995,-0.236719,0.075794,0.530933,-0.105999,-0.248056,-0.817044,-0.136369,-0.064568,-0.100137,-0.485921,-0.304783,-0.015672,-0.280385,-0.585012,0.930264,-0.017434,-0.150994,0.584476,0.313623,0.309565,0.321690,0.283681,0.055655,-0.045110,0.339403,-0.144277,-0.355197,0.241277,0.168005,-0.124100,-0.227718,0.419846,0.095195,0.370927,0.442173,-0.095489,0.010489,0.314359,0.370152,-0.237866,-0.106842,0.106031,0.015533,-0.026462,0.005745,0.235475,-0.132487,0.033806,-0.013057,-0.091314,-0.773259,-0.001808,0.135767,0.001709,-0.694760,0.709701,-0.082456,-0.071378,-0.104356,0.032324,0.094034,0.384823,0.214286,0.313581,-0.332539,-0.016106,-0.155688,0.080625,0.596764,-0.105278,-0.334042,0.267664,-0.375890,-0.615166,-0.055120,-0.333445,-0.392140,-0.340510,0.461676,0.168477,0.148962,0.257523,-0.692700,-0.036700,-0.280187,0.009952,-0.031277,-0.385705,0.204364,-0.650626,-0.290428,-0.357302,-0.246984,-0.116624,0.020594,-0.450084,0.799326,-0.831659,0.213124,0.400240,0.039184,-0.274662,0.781926,0.120718,0.210975,-0.387680,0.022441,0.401270,-0.193010,0.037594,0.168424,0.458809,-0.201471,-0.130772,-0.442646,0.689952', '1870681', '25880986', '6101834', '3775163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309017', '卡特教练', '剧情', '《卡特教练》又名《铁血教练 》、《放牛班的严冬》，根据高中篮球队教练肯·卡特的真实故事改编而成。里士满高中篮球队原本从未在任何比赛中获胜过，是一支屡败屡战的队伍，这一切在卡特教练（塞缪尔·杰克逊 Samuel L. Jackson 饰）执教之后发生了变化。他相信这支队伍在他的带领下可以成为最优秀的篮球队，所以他要求队员和他签订一个协议，约定如果队伍不团结或是成绩不佳就不再继续参加任何比赛。在他的带领下，这支队伍开始走上了上坡路，最后成为无人能敌的长胜王。但是在1999年举行的国家锦标赛上，队员们的表现却十分不尽人意，这让卡特教练沮丧不已，他真的关闭了训练馆，禁止队伍继续参加任何比赛。此举引起了极大的反响，他一时成了大众议论的焦点，有人赞赏他视篮球为生命的品格，但更多的人对他的举动表示不解，甚至是批评。©豆瓣', '塞缪尔·杰克逊', '托马斯·卡特', 8.6, 49827, 'tt0393162', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2219988388.jpg', 0.1, 0.5, 10.8, 47.9, 40.8, '0.141313,-0.050994,-0.684020,0.629128,-0.113349,-0.185206,0.390349,-0.049382,-0.727969,0.039099,0.229710,0.777439,-0.303243,0.143194,0.263491,-0.528629,-0.225080,-0.817132,-0.239509,-0.121592,-0.295413,-0.610728,0.077125,-0.233021,-0.014752,-0.320701,1.086178,0.099223,-0.395259,0.649253,0.205724,0.198119,0.520697,0.398245,-0.058960,-0.000148,0.279656,0.100663,-0.183634,0.150638,-0.184136,-0.132362,-0.650512,0.380327,0.279970,0.285407,0.514381,-0.181941,-0.291551,0.153766,0.380353,-0.499188,0.067413,0.118469,0.377432,0.123859,0.097880,0.378280,0.310834,0.306711,-0.513561,-0.145406,-0.789563,0.104706,-0.023579,0.362381,-0.554936,0.629051,-0.121666,-0.007221,0.079206,-0.130206,0.104798,0.358018,0.278074,-0.134918,-0.263396,-0.050096,-0.516202,0.210953,0.896339,-0.040698,-0.401688,-0.012314,-0.277757,-0.542586,-0.197678,-0.280846,-0.383397,0.219165,0.058476,0.112121,0.237604,0.034425,-0.441944,0.062564,0.058742,-0.575232,-0.069507,-0.557184,0.229739,-0.674120,0.248989,-0.337349,-0.571202,-0.059058,-0.142124,-0.271716,0.887537,-1.154532,0.038575,0.515219,0.254318,-0.401170,0.473907,0.290689,0.153133,-0.107608,-0.213710,0.191440,0.028753,0.184037,0.024602,0.591591,0.244912,-0.402400,-0.263339,0.572727', '35030151', '26615753', '1826173', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309018', '做头', '剧情', '国营明星理发店因为有年轻理发师阿华（霍建华 饰）而吸引来诸多各式各样女人，爱妮（关之琳 饰）就是其中之一。爱妮的蘑菇头曾是上海滩的经典，虽然如今已经时过境迁，但做头依然是爱妮生活中不变的情趣。长相精致漂亮的爱妮年轻时没有嫁好，如今整日面对家庭琐碎以及无趣丈夫（吴镇宇 饰）和骄蛮女儿，惟有在阿华在她的头上摆弄时，她才能找到年轻时风华绝代的感觉。国营理发店面临倒闭，爱妮的婚姻也走到了尽头，阿华要去新的地方工作，爱妮的时代似乎要彻底走到尽头。有一天，阿华提出帮爱妮最后一次做头……本片根据著名女作家唐颖小说《红颜》改编。©豆瓣', '关之琳', '江澄', 5.3, 16133, 'tt0445853', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578750874.jpg', 8.9, 31.5, 47.4, 9.2, 3, '0.177875,0.170193,-0.496334,0.199011,-0.181644,-0.223368,0.806492,0.214386,-0.400515,-0.339847,0.231024,0.538984,-0.183906,0.347079,0.347744,0.187656,-0.177539,-0.638002,-0.085004,-0.213662,-0.272582,-0.273379,-0.158716,-0.029390,-0.166652,-0.110107,0.525262,0.100041,-0.086306,0.166930,0.301120,-0.060964,-0.189901,0.412270,-0.358977,-0.079942,0.209578,0.231570,-0.088950,0.176309,-0.011596,-0.232285,-0.267124,-0.065685,-0.027466,0.343844,0.461548,-0.092208,-0.170356,-0.011853,0.543369,0.310459,-0.335235,-0.002972,0.366510,-0.126341,0.430536,0.020776,-0.076027,-0.244159,0.051466,-0.280001,-0.552400,0.036253,0.159150,0.086655,-0.476181,0.208705,-0.008697,-0.208855,0.251056,-0.470151,0.338142,-0.143716,0.474963,0.418833,0.202424,0.286884,-0.330157,0.312623,0.523574,0.459192,-0.149774,0.269660,-0.295138,-0.232855,0.026750,-0.419320,-0.408835,0.129368,-0.050917,0.109854,-0.145307,-0.060132,-0.370406,0.224196,-0.064329,-0.087542,0.176897,-0.329456,-0.327404,-0.394302,-0.157663,-0.803901,-0.253438,0.153661,0.061303,-0.354139,0.802430,-0.582080,0.196095,0.268887,0.210614,-0.390712,0.943312,0.040485,0.021829,-0.240837,-0.099189,0.228640,-0.421582,0.139864,0.028321,0.143866,-0.206256,-0.356439,-0.200060,0.489318', '26354526', '3055049', '1917323', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309020', '全民情敌', '喜剧', '希什（威尔•史密斯 Will Smith  饰）十分准确的把握了男性的弱点：他们在求爱的时候由于过分迫切想得到对方好感，反而会表现笨拙失去魅力。而希什掌握了一套完整的独家的理论，可以帮助男士在头三次约会时候就成功俘获对方的心，这套谋略全面实用，令约会期间的就餐、牵手、接吻，有了指导细则。这次希什的客户是胖男人阿伯特（凯文•詹姆斯 Kevin James饰）。他生性温顺，却爱上了当红女明星。于是对阿伯特的一番彻底改造在所难免。更重要的是，他竟然在工作中爱上了女明星的跟班记者莎拉（伊娃•门德斯 Eva Mendes饰）。这个自己感情一直空缺的约会指南者，开始尝到爱的气息。但是，好像现实中的爱跟他平时设计的并不一样。屡试不爽的爱情法则，在他身上反而失了灵。也许，他的爱情学问还远远不够精通。©豆瓣', '威尔·史密斯', '安迪·坦纳特', 7.5, 111571, 'tt0386588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2239596651.jpg', 0.2, 2, 33.5, 48.9, 15.4, '0.354046,0.207756,-0.827779,0.577333,-0.401192,-0.105111,0.454890,-0.054541,-0.409212,-0.050238,0.118686,0.493086,-0.114043,-0.010880,0.130780,0.072066,-0.178358,-0.635081,0.234473,0.120620,-0.155348,-0.525503,-0.330342,-0.308832,-0.179769,-0.507519,0.521066,0.099609,-0.358259,0.094840,0.280544,-0.098530,0.456520,0.552399,-0.132222,-0.098318,0.137247,-0.061287,-0.019322,0.217404,0.159848,-0.161003,-0.019335,0.465007,-0.000055,0.472691,0.455455,-0.226768,-0.334077,0.189692,0.508675,-0.036869,0.024754,0.207020,0.055138,-0.093322,0.445433,0.104006,0.073473,0.070172,0.129015,-0.027767,-0.931525,-0.180113,0.144854,0.062171,-0.410862,0.563574,-0.188035,0.031501,-0.054584,-0.310411,-0.089387,0.066074,0.231925,0.183908,-0.067436,-0.124984,-0.325409,0.247246,0.556428,0.136481,-0.344215,0.668487,-0.586105,-0.554023,-0.257924,-0.375012,-0.369729,-0.014800,0.428949,0.149236,-0.087186,0.091329,-0.587801,0.192377,0.031864,0.222487,-0.114476,-0.432290,0.131260,-0.475374,-0.168423,-0.803021,-0.399141,-0.205033,0.113205,-0.430397,0.811564,-1.013023,0.082431,0.739511,0.245971,-0.515582,0.608415,0.354007,-0.191745,-0.330849,-0.317372,0.317403,-0.188400,-0.063730,0.095252,0.518762,0.191075,-0.209545,-0.343926,0.682302', '25932086', '24284209', '1793491', '1303112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309021', '康斯坦丁', '动作', '康斯坦丁（奇诺•李维斯 Keanu Reeves 饰）生来就能看出游走在人间的恶魔与天使，这令年幼时的他十分痛苦，曾经自杀想以这种方式结束自己的痛苦。后来获悉了上帝与撒旦之间有过协议，谁也不能直接插足人间，只能间接诱使人们选择天堂与地狱，而自杀者不得上天堂，他便开始利用自己天赋的超能力帮助铲除人间的恶魔，以此祈求获得一张天堂的门票。一次在帮助一名女警调查她的妹妹的离奇死亡事件时，康斯坦丁意外获释了天使长加百利意图和撒旦的儿子联手统治人间的阴谋。康斯坦丁当然要竭尽全力阻止这一黑暗降临人间……©豆瓣', '基努·里维斯', '弗朗西斯·劳伦斯', 8, 209411, 'tt0360486', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p907374250.jpg', 0.3, 1.9, 22.6, 48.3, 27, '0.286153,0.302832,-0.570257,0.734354,-0.200799,-0.054774,0.519885,0.004993,-0.438187,0.047239,0.333093,0.837427,-0.105156,0.186314,0.252276,-0.020101,-0.381966,-0.575656,0.049949,-0.183537,-0.296013,-0.324644,-0.518855,-0.400322,-0.143353,-0.391555,0.742362,0.134403,-0.129099,0.198467,0.194612,0.499012,-0.269255,0.247913,-0.159731,-0.355800,-0.078340,0.340120,-0.589076,0.384877,0.008367,-0.236710,-0.155658,0.556579,-0.408186,0.070559,0.489176,-0.750173,-0.074109,-0.441315,0.343993,-0.477102,-0.065636,0.268388,0.185666,-0.242830,0.169010,0.463524,0.121008,-0.123245,0.028323,-0.009676,-1.107926,-0.183855,-0.064572,-0.002825,-0.138961,0.131296,-0.020902,0.370814,0.304516,-0.147254,0.073191,0.369275,0.614686,0.378495,-0.518717,-0.361902,-0.494170,0.168093,1.068376,-0.075212,-0.277591,0.213961,-0.193066,-0.584415,-0.170113,-0.234067,-0.368840,0.245818,0.276754,0.314718,-0.235372,0.631190,-0.756322,-0.205319,-0.560144,0.151969,-0.165546,-0.392339,0.179075,-0.395793,-0.316251,-0.148630,-0.002373,0.074800,0.406196,-0.262433,0.531448,-0.790844,0.372709,0.612621,0.512730,-0.555476,0.657560,0.202002,0.086813,-0.323117,0.037674,0.374231,0.148178,0.299790,-0.025827,-0.060886,0.229156,0.312609,0.011136,0.400212', '26678784', '35377026', '1874704', '3213270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309023', '午夜凶铃2(美版)', '悬疑', '美丽的单身妈妈瑞切尔·凯勒（纳奥米·沃茨 Naomi Watts 饰）带着儿子艾丹（大卫·多夫曼 David Dorfman 饰）离开留下了永生难以磨灭的恐怖回忆的故地西雅图，搬到了毗邻大海的俄勒冈州艾斯特里亚居住。瑞切尔在当地一家报社谋得一份工作，生活充实忙碌。某天，报社接到一条消息，两名青年在看了一卷神秘录像带后一人死亡，一人精神恍惚，熟悉的场景以及没有标题的录像带，令瑞切尔敏感地察觉到昔日的噩梦即将重现。她烧毁录像带，试图阻止凶铃的诅咒继续蔓延，危害世人，却没想到灾难降临到艾丹的头上。该了结的终要了结，无法逃避的如何也躲不过去……本片根据日本作家铃木光司的同名恐怖原著改编，为日本版的翻拍版本。影片荣获2006年ASCAP电影与电视音乐奖、2006年BMI电影与电视奖最佳配乐奖。©豆瓣', '娜奥米·沃茨', '中田秀夫', 6, 5450, 'tt0377109', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2876688586.jpg', 3.7, 20.4, 56, 14.2, 5.8, '0.038146,-0.093095,-0.484711,0.515911,0.348637,-0.162059,0.762215,0.258338,-0.290683,-0.155419,0.098844,0.647034,-0.250605,0.066677,0.197787,0.105275,-0.399607,-0.592276,-0.089631,-0.098479,-0.077913,-0.153811,-0.402118,-0.176378,0.079853,-0.267397,0.610396,0.094730,-0.167702,0.312035,0.148856,0.171322,-0.341847,0.188634,-0.185498,0.094491,0.033749,0.046269,-0.439947,0.297075,0.120946,-0.229005,-0.295713,0.077301,-0.121778,0.048146,0.669996,-0.108924,-0.219648,0.038218,0.613082,-0.053313,-0.282801,0.032450,0.110276,0.058575,0.157198,0.056679,-0.251873,-0.066511,0.022936,-0.020124,-0.826810,0.027855,0.058110,0.353722,-0.311735,0.450999,-0.257491,0.144719,0.054469,-0.340744,0.126242,0.130663,0.269321,0.490624,0.029318,0.168157,-0.253164,0.561450,0.400283,-0.072875,-0.334220,0.354034,-0.041926,-0.142925,-0.156910,-0.159909,-0.626774,0.248432,0.436583,0.024693,-0.144197,0.388074,-0.440695,-0.144996,-0.293608,-0.446776,0.003433,-0.279450,-0.453939,-0.673520,-0.286269,0.014274,-0.056744,-0.169043,0.216612,-0.155588,0.664511,-0.325703,0.435421,0.520289,0.052313,-0.213266,0.683206,0.060332,-0.039808,-0.172419,-0.009580,0.420990,0.050584,0.317022,0.201471,0.023420,-0.041066,-0.326339,-0.436440,0.431158', '3318306', '2027945', '22265121', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309027', '罪恶之城', '动作', '影片改编自著名漫画大师弗兰克•米勒的经典同名漫画，由三个故事组成，都发生在虚拟的罪恶之城，这里，警察和暴徒已无分别，暴力摧毁一切，也保护一切。故事一：罪城容貌丑陋，脾气火爆的马福（米基•洛克 饰），遇上了金发美女歌蒂，一夜情给了马福从未有过的温暖。然而，醒来之后，马福发现躺在身边的歌蒂被谋杀，自己则面临着杀人凶手的指控。马福的心被愤怒和复仇的火焰点燃，他在歌蒂的姐姐温蒂的帮助下，调查事实的真相，寻找杀害自己爱人的凶手......故事二：狙杀迪怀特(克里夫•欧文 饰)以前是罪犯，整容后，他成了酒吧招待雪莉的男朋友，并且帮她教训纠缠不清的前男友，有暴力倾向的杰奇(本尼西奥•德尔托罗 饰)。迪怀特跟踪杰奇一伙到了由妓女帮派统治的老城，杰奇不按规则办事，被妓女们杀死，之后，她们才发现，杰奇是警察，他的死，破坏了妓女们和警察之间的协议。迪怀特必须帮她们掩盖犯罪事实，并且保护她们的权利......故事三：黄杂种哈迪根(布鲁斯•威利斯 饰)由于心脏病快退休了，在他警察生涯的最后一小时，哈迪接到情报，参议员的儿子罗杰绑架了11岁的少女南茜，罗杰是几起奸杀案的主要嫌疑人，落到他手里凶多吉少。哈迪根单枪匹马的救出了南希，废掉了罗杰，自己也身受重伤。随后的八年，罗杰的参议员父亲，利用权势将他关在监狱中，逼他为罗杰顶罪，哈迪根一直没有屈服，而南希化名为科里迪娅的来信则是她生活中的唯一慰藉。南希的来信突然中断了，这让哈迪根很不安，他不得不放弃反抗，以认罪来换取假释，寻找保护南希。他并不知道，一直在暗中跟踪他的怪物黄杂种，将让他和南希重新陷入危险之中......', '杰西卡·阿尔芭', '弗兰克·米勒', 8.4, 189376, 'tt0401792', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1644472130.jpg', 0.6, 2, 15, 40, 42.5, '0.230918,-0.107117,-0.533936,0.404930,-0.349387,-0.373465,0.743688,0.122764,-0.374929,-0.242408,0.234836,0.592502,-0.140172,0.186415,0.287840,0.151284,-0.396594,-0.727078,-0.168937,-0.105457,-0.292935,-0.674946,-0.212889,-0.405226,0.024194,-0.271494,0.410922,-0.147657,-0.171384,0.221163,0.318149,0.455948,-0.100916,0.299461,-0.030085,0.100819,0.293055,-0.411356,-0.181352,0.240028,0.086290,-0.277803,0.030535,0.341278,-0.084519,0.500130,0.552872,-0.316828,0.053804,-0.208233,0.252690,-0.439788,-0.056922,0.012841,0.368902,-0.244273,0.134328,0.325457,-0.314134,-0.182713,0.195495,-0.069780,-0.740228,0.076565,0.056948,0.179827,-0.549597,0.180434,-0.267713,0.177608,0.112189,-0.246081,0.231665,0.291632,0.091529,0.163674,-0.113407,0.029014,-0.476772,0.083908,0.577217,-0.129714,-0.066574,0.011418,-0.158059,-0.164674,-0.003919,-0.264914,-0.402360,-0.073632,0.494727,-0.047990,-0.191813,0.124412,-0.389720,-0.428428,-0.355023,-0.063970,-0.092316,-0.284480,-0.135418,-0.379094,-0.253405,-0.143036,-0.323028,-0.094164,0.090787,-0.127338,0.486086,-0.603799,0.286214,0.563852,0.185312,-0.401059,0.453677,0.179305,0.046477,-0.079343,-0.090485,0.211260,0.330116,0.341613,0.344852,0.206526,0.119537,-0.152865,-0.334883,0.406122', '1307442', '1947080', '25862560', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309028', '特工佳丽2：武力巾帼', '喜剧', '格雷西（桑德拉·布洛克 Sandra Bullock 饰）意外成为美国小姐之后，一夜之间成了名人。每次参加活动都会因为“粉丝”的围观、纠缠或者索要签名而暴露身份，影响整个行动，殃及一起执行任务的同事。为此，FBI纽约总部做出决定，让她调离原岗位，出任FBI纽约总部形象代言人，在专业人士的训练下，四处参加电视采访节目，为FBI纽约总部做宣传。直到一块参加“美国小姐”竞选时的好朋友谢丽尔（希瑟·伯恩丝 Heather Burns 饰）和资深电视节目主持人斯坦（威廉·萨特纳 William Shatner饰）遭绑匪劫持，格雷西无法袖手旁观，决心重拾联邦女干探的真我本色，出手相救......©豆瓣', '桑德拉·布洛克', '约翰·帕斯昆', 6.2, 12325, 'tt0385307', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2180193828.jpg', 1.6, 13.4, 61.5, 18.4, 5.2, '-0.007793,-0.106659,-0.380235,0.264043,0.145609,-0.142693,-0.215696,0.493378,-0.308867,-0.061144,0.048100,0.679782,-0.222829,0.208272,0.654986,-0.179618,-0.664124,-0.699394,0.032717,-0.092946,-0.073557,-0.392141,-0.062381,-0.432329,0.084338,-0.305264,0.502042,-0.033613,-0.384158,0.494876,0.625513,0.288622,0.069085,0.181577,0.498726,-0.463900,0.581543,-0.003333,-0.400288,0.479251,-0.182488,0.034330,-0.040704,-0.030108,0.450470,0.405244,0.351855,0.054918,0.102396,-0.514300,0.430474,-0.271835,0.443857,0.003600,0.439759,0.138415,0.187084,0.351194,-0.174614,-0.099358,0.183258,-0.058462,-0.501368,0.220839,0.310338,0.156833,-0.568366,-0.064584,-0.222097,0.277404,-0.073197,-0.208335,0.278313,0.479088,0.366680,-0.232269,0.360376,0.108584,-0.190553,0.323546,0.783090,0.007222,-0.120772,-0.388587,0.064155,-0.067550,0.281099,-0.407458,-0.205230,0.141882,-0.169698,-0.306081,0.207868,0.209970,-0.172519,-0.371130,-0.453846,-0.344847,0.003713,-0.286317,0.233543,-1.297784,-0.004458,0.441402,0.027358,-0.193177,0.051475,0.002243,0.392192,-0.709661,0.189962,0.558512,0.522186,-0.662220,0.577924,0.243839,0.082284,-0.263246,-0.178909,-0.082088,0.150044,0.245574,-0.153422,-0.146810,0.291971,-0.536315,-0.104220,-0.013319', '3003137', '25833539', '34961898', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309029', '爱神', '剧情', '该片是一部三段式主题（爱和性）电影，由米开朗基罗•安东尼奥尼（《危险临界点》）、史蒂文•索德伯格（《平衡》）和王家卫（《手》）三位导演联合执导。《手》讲的是1960年代的香港，年轻的裁缝（张震）多年不计回报地爱着交际花华小姐（巩俐）的故事，影像华丽，充满了质感又略带伤感。《平衡》的故事发生在1950年代的纽约，广告人尼克•彭罗斯（罗伯特•唐尼）总是被春梦困扰，只得向他的心理医生珀尔（阿兰•阿金）求助，基调虽荒谬反常，却也可看成颇有自嘲意味的幽默喜剧。《危险临界线》则仍是安东尼奥尼一向关注的现代社会中的男女关系主题，哲学味道浓烈。©豆瓣', '巩俐', '王家卫', 7.7, 50484, 'tt0343663', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p696014395.jpg', 0.5, 2.8, 30.4, 45.5, 20.9, '0.270067,0.145063,-0.611433,0.505928,0.246673,0.001013,0.723388,0.237364,-0.314608,-0.289465,0.169834,0.451913,-0.246913,0.123103,0.323769,0.011564,-0.197695,-0.494515,-0.186868,0.026127,0.148414,-0.622686,-0.351226,-0.173992,-0.104633,-0.327033,0.151632,0.279791,-0.470842,0.078916,0.560926,0.379616,-0.044060,0.460461,0.239281,-0.097550,0.316375,-0.214939,-0.276571,-0.251858,0.353876,-0.087885,-0.141745,0.120748,-0.019835,0.323421,0.383525,0.041666,0.000643,0.353331,0.426895,-0.013896,0.031944,-0.108254,-0.006366,-0.014467,0.046457,0.137268,0.194903,-0.081040,0.006989,-0.221336,-0.599603,0.190271,0.019243,0.365470,-0.264818,0.196244,-0.124502,-0.001693,-0.119879,-0.182539,0.035642,-0.347634,0.699184,0.454648,0.297388,0.215116,0.034359,0.259332,0.153493,0.382620,-0.654701,0.259860,-0.708324,-0.457823,-0.185851,-0.140721,-0.549151,0.033080,0.466246,-0.337917,0.046410,0.557421,-0.419082,-0.046044,-0.111836,0.028429,-0.097293,-0.248323,0.239353,-0.624154,-0.140015,-0.500216,-0.111582,-0.319056,0.218626,-0.079878,0.620437,-0.363073,0.142980,0.521773,0.028570,-0.035169,0.480199,0.168822,-0.128258,-0.374213,-0.128954,0.580327,-0.387812,-0.153613,0.146054,0.363379,0.131653,-0.127109,-0.180030,0.449137', '2364001', '3055450', '5320600', '1302815');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309031', '撒哈拉', '喜剧', '一枚金币让探险家德克（马修·麦康纳 Matthew McConaughey饰）兴趣盎然，因为金币与某个宝藏传说有着千丝万缕的联系。而德克是个极喜冒险、一刻也停不下来的人，他在西非尼日尔河一带展开了一段曲折的探险之旅，关于这枚金币的秘密层层剥开。更为关键的是，他还发现了一个 足以危害人类毁灭地球的大危机——非洲一个独裁政权和当地富豪勾结，把核原料大量倾倒在海洋中。当地的人民已经深受其害，神志癫狂，如果不及时出手，危难将会迅速扩大。德克和女科学家伊娃（佩内洛普·克鲁兹 Penélope Cruz饰），共同展开了一场正义的斗争。他们要面对恶势力和艰险的自然环境，一路险相横生。©豆瓣', '裘德·阿库维迪克', '布瑞克·埃斯纳尔', 6.5, 5856, 'tt0318649', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p895397403.jpg', 1.5, 9, 58.3, 25.5, 5.8, '0.153556,0.051997,-0.707901,0.657912,0.040316,-0.017563,0.856853,-0.109040,-0.423136,0.146496,0.084544,0.866074,-0.076249,-0.298325,0.243480,0.077138,-0.193404,-0.580992,-0.023385,-0.104279,-0.317233,-0.569430,-0.741500,-0.256015,-0.121169,-0.347984,0.583286,0.309330,-0.269923,0.513240,0.275833,0.327642,-0.225744,0.447747,-0.198007,-0.225946,0.201734,-0.033887,-0.276211,0.082047,-0.179557,-0.282337,0.056103,0.387121,-0.010683,0.342643,0.505478,-0.398514,0.098522,-0.146809,0.233359,-0.359541,-0.090490,0.145890,0.232775,-0.098165,0.111959,0.036141,-0.292043,0.043363,0.360895,-0.192904,-0.873419,-0.233725,0.073669,0.283494,-0.445020,0.409451,0.078789,-0.073396,-0.050007,-0.165589,0.196009,0.590659,0.304062,0.239616,-0.060659,-0.354863,-0.515151,0.118111,0.629266,-0.136247,-0.191919,0.205779,-0.128550,-0.517319,-0.178933,-0.064016,-0.444663,-0.091972,0.658329,0.027415,-0.195501,0.583073,-1.130477,0.268683,-0.400877,-0.374275,-0.073336,-0.115144,-0.087771,-0.441526,-0.374976,-0.286517,-0.201324,0.274821,0.340183,-0.103606,0.907643,-0.483341,0.014162,0.739615,0.299077,-0.461799,0.381521,0.091211,0.176121,-0.270063,-0.131952,0.253286,0.143779,0.431716,0.027750,0.309535,0.135358,-0.091767,-0.105496,0.361802', '26290398', '1308585', '1308784', '2357162');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309032', '鬼哭神嚎', '剧情', '1974年11月13日夜，美国纽约长岛猎鹿公园别墅区。笛福家23岁的儿子罗纳德（布兰顿·唐纳德森 Brendan Donaldson 饰）突然狂性大发，在夜深人静之时将一家六口人全部杀害。在被警方逮捕后，他宣称自己是在恶魔的驱使下行此恶性，法官虽然未听信他的供词，不过该事件依旧喧嚣一时。一年后，正在憧憬全新生活的勒兹夫妇以极低的价格买下了笛福家的房子。但从他们入住那天开始，各种诡异事件便不断发生，且愈演愈烈。一家人不堪其扰，决定搬出这个恐怖所在，然而真正的危险才刚刚到来……本片根据真实事件改编，为同名作品的重拍版，并荣获2005年青年选择奖最佳恐怖场景奖。©豆瓣', '瑞安·雷诺兹', '安德鲁·道格拉斯', 6.5, 19357, 'tt0384806', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1138058480.jpg', 1.5, 9.7, 56.5, 25.8, 6.6, '0.016268,0.208242,-0.589653,0.190188,0.270884,0.022212,0.622805,0.060021,-0.641468,-0.431829,0.407875,0.644301,-0.399720,0.169380,0.298307,-0.070966,-0.218252,-0.526365,0.111227,-0.404916,-0.194032,-0.432484,-0.043323,-0.284493,0.059484,-0.123522,0.435029,0.351221,-0.005186,0.358261,0.169825,0.406711,-0.190785,0.377635,-0.177082,-0.071953,0.183757,0.018483,-0.321686,0.116882,-0.123432,-0.511413,-0.319540,0.087074,0.042758,0.282705,0.741721,-0.413681,-0.596454,0.042777,0.614066,-0.222743,-0.266594,0.157701,0.346329,-0.003601,0.299348,0.182027,-0.307031,-0.116620,-0.184095,-0.305559,-0.515796,0.169706,0.028428,-0.112763,-0.355676,0.245883,-0.130321,0.237443,0.064930,-0.129914,0.028208,0.373995,0.267034,0.490553,-0.131743,-0.043026,-0.386847,0.230973,0.466992,-0.180031,-0.178247,0.368999,0.022606,-0.425729,-0.141692,-0.238016,-0.251923,0.219825,0.266084,0.286642,-0.180946,0.218937,-0.401081,-0.238674,-0.320097,-0.257869,0.105098,-0.059040,-0.425098,-0.582512,-0.158852,0.004600,-0.068006,0.024306,-0.000786,-0.203831,0.423588,-0.582322,0.380363,0.444192,0.290680,-0.397346,0.250170,-0.230864,0.032581,-0.210058,-0.283046,0.212204,0.120024,0.156267,0.214187,0.139809,0.053642,-0.159958,-0.159191,0.549694', '10508879', '1465415', '1309194', '3001184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309033', '双生美莲达', '剧情', '我们每天都在讨论该如何生活，如何使自己过得更开心。这部片子的导演也在探讨。一伙朋友在小酒馆里讨论该如何面对生活，他们将所有态度浓缩成两个极端，哭或者笑。他们假设了这样一个叫美莲达（拉达•米契尔 Radha Mitchell 饰）的女人的故事：美莲达有一个幸福的家庭，一对儿女。但是她偏偏出轨了，被丈夫起诉离婚，儿女都判给了丈夫。当她满怀憧憬准备与情人开始新生活时，情人也抛弃了她。愤怒的美莲达杀了情人，被法院认定患有精神分裂，无罪释放。只是，她连探视儿女的权利也失去了。美莲达的故事还在继续，只是由两个代表不同态度的朋友分别再开始讲述……©豆瓣', '拉达·米切尔', '伍迪·艾伦', 7.3, 6299, 'tt0378947', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2183157749.jpg', 0.4, 3.5, 39.3, 45.3, 11.6, '0.109849,-0.301053,-0.410731,0.344595,-0.368705,-0.243632,0.619678,0.319029,-0.342078,-0.066703,-0.029631,0.687944,-0.200968,0.333721,0.040046,-0.061111,-0.344195,-0.769663,0.185095,-0.112713,-0.123867,-0.548935,0.280644,-0.331813,-0.097587,-0.009410,0.497817,-0.263009,0.091862,0.004672,0.451458,0.058522,-0.049865,0.458946,-0.229230,0.046777,-0.015487,0.144597,-0.422689,0.113810,0.097099,0.045524,0.001768,0.171644,-0.171772,0.272144,0.668975,-0.125161,-0.240183,-0.026569,0.348343,-0.241665,-0.040113,0.397084,0.208511,-0.048173,0.126938,0.124223,-0.176299,-0.173656,0.039771,-0.040638,-0.726075,0.015822,0.071510,0.040474,-0.626615,0.313858,0.097375,-0.012349,0.235412,-0.111099,0.212557,0.465997,0.269159,0.627230,-0.281739,-0.083909,-0.562044,0.392469,0.832701,0.030800,-0.009578,0.494041,-0.203182,-0.217427,-0.077260,-0.194954,-0.661204,-0.024364,0.065232,-0.069662,-0.393913,0.380364,-0.474681,0.076367,-0.074179,-0.034230,0.110867,-1.009083,0.232516,-0.305073,-0.181957,-0.256461,-0.424183,-0.043920,0.148052,-0.382489,0.907522,-0.757565,0.241340,0.306488,0.439717,-0.987788,0.576691,0.559287,0.213166,-0.340968,0.114846,0.293727,0.162755,-0.009037,0.212999,0.173303,0.164365,0.298382,-0.317821,0.391281', '1877596', '1949320', '26678784', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309035', '战鸽总动员', '喜剧', '故事发生在第二次世界大战中，由于无线电通信已经不安全，所以英国军方开始训练军鸽，利用他们来和法国地下抵抗组织和盟军进行通讯。野鸽子“勇士”看到这么多同类为国出力，也跃跃欲试。于是，“勇士”想尽办法混到了军鸽中，未经过训练的“勇士”和其他军鸽相比显得有些力不从心。但事有凑巧，“勇士”接到二战中最严峻的任务，把诺曼底登陆的情报送到盟军手中。面对敌军凶狠的军用猎隼，“勇士”能否顺利完成任务？©豆瓣', '伊万·麦克格雷格', 'Gary Chapman', 6.7, 19933, 'tt0361089', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2220826252.jpg', 0.9, 7, 55.8, 29.3, 7, '0.398459,-0.089357,-0.788268,0.514562,0.175855,0.148029,0.402111,-0.624854,-0.531631,-0.160635,0.211276,0.679345,0.300871,-0.254639,0.250540,-0.598127,-0.651412,-0.574047,-0.266384,-0.088602,-0.410675,-0.459911,-0.375745,-0.329239,0.047520,-0.289216,0.960065,0.245938,-0.148821,0.627599,-0.011496,0.156450,-0.212416,0.547311,-0.145566,-0.402181,0.169858,-0.279776,-0.238484,0.286401,0.023410,0.001855,-0.232654,0.161431,0.446619,0.393465,0.387956,-0.651114,-0.115795,-0.248285,-0.038550,-0.302802,0.074342,-0.035923,0.319386,0.251855,0.066785,-0.080652,0.089891,0.321516,-0.623268,-0.167249,-0.623039,-0.047362,0.049242,0.265269,-0.380848,0.196021,-0.523076,0.367911,0.272263,-0.353973,0.314029,0.804811,0.277699,0.256933,-0.175146,0.214451,-0.491682,-0.014700,0.792295,-0.279255,-0.195073,-0.325056,0.178431,-0.642596,0.312074,-0.495518,-0.027976,0.080512,0.088833,-0.017652,0.088237,0.390922,-0.874851,0.319971,-0.159057,-0.433031,-0.030915,-0.255927,-0.068408,-0.733309,0.103837,-0.342662,-0.163871,0.483683,0.410926,-0.121948,0.886656,-0.954305,-0.176286,0.250132,0.549867,-0.071904,0.104763,0.056956,0.223834,-0.171924,-0.006997,0.001258,0.115133,0.453082,0.208734,0.151331,-0.072957,-0.551905,-0.225147,-0.032371', '26615753', '20274039', '1826173', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309038', '冰雪公主', '剧情', '在布莱尼•凯茜•卡勒里(米歇尔•崔切伯格饰)心中，有一片比哈佛大学更神圣的地方，那就是镁光灯聚焦的闪闪发光的冰上舞台。凯茜天姿聪颖，被保送到哈佛大学，但入学之前她必须独立完成一个物理实验。一直以来都对花样滑冰有着莫名情愫的她，选择了这项运动作为实验主题。而正是这次实验激发了凯茜内心对花样滑冰的潜在渴望。一次次尝试中，凯西过人的天赋慢慢显露。是做一名高校的天之骄女，还是放弃机会走向专业的运动生涯？无疑，单身母亲(琼•库萨克饰)殷切的希望女儿选择前者。可冰上自由的旋转跳跃，曼妙的舞姿和偶然而至的爱情，着实令她难以割舍。©豆瓣', '米歇尔·崔切伯格', '蒂姆·费威尔', 6.9, 16379, 'tt0396652', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1031755346.jpg', 0.4, 4.6, 52.3, 32.9, 9.9, '0.000230,-0.093980,-0.781098,0.854772,-0.161591,-0.341115,0.509091,0.132454,-0.472852,-0.196846,0.234759,0.611045,-0.193830,0.251780,0.325290,-0.164765,-0.140485,-0.751508,0.055104,-0.188212,-0.280543,-0.407699,-0.297314,-0.086177,-0.169637,-0.419164,0.988129,0.096849,-0.334470,0.455576,0.399237,0.315296,0.262179,0.268597,-0.058259,-0.560769,0.058078,0.102428,-0.256778,0.258415,0.231894,-0.186205,-0.179172,0.311359,0.020933,0.228327,0.617450,-0.342682,-0.039984,-0.228590,0.383518,-0.259269,0.008460,0.174370,0.056740,0.223053,0.011867,0.123195,-0.171216,0.177286,0.185140,-0.315538,-0.869220,-0.124999,0.250942,0.156474,-0.511125,0.357850,0.004198,-0.251405,0.146898,-0.229949,-0.168770,-0.136111,0.217794,0.394582,-0.341304,0.018815,-0.085650,0.107194,0.293919,0.013372,-0.439316,0.488410,-0.504337,-0.491687,0.235548,-0.246276,-0.342241,-0.008396,0.077217,0.464934,0.000166,0.279897,-0.531672,0.170499,-0.345062,-0.218994,-0.164737,-0.549854,-0.059296,-0.512506,-0.037558,-0.370473,-0.388326,0.070615,-0.024449,-0.445361,0.891419,-1.107541,0.163392,0.590206,0.147210,-0.307551,0.549978,0.138504,0.162182,-0.165075,-0.263302,0.431506,-0.212981,0.109705,-0.368653,0.513524,0.025862,-0.058437,-0.471439,0.740994', '25880986', '1308499', '1870681', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309042', '佐罗传奇', '动作', '19世纪中叶，黑侠佐罗的传奇故事在加利福尼亚继续流传。亚利桑德罗（安东尼奥·班德拉斯 Antonio Banderas 饰）从上一代佐罗手中接过这个正义的名号，虽然已经和伊莲娜（凯瑟琳·泽塔琼斯 Catherine Zeta-Jones 饰）完婚，并育有可爱的儿子瓦金（Adrian Alonso 饰），但他的正义事业从未停止。是时加州即将成为美利坚合众国的第31个州，百姓期盼已久的自由即将到来。然而就在此时，疯狂的麦吉文伯爵（Nick Chinlund 饰）及一个神秘的宗教组织却以武力抵制建州。人民的自由和安全危在旦夕，佐罗不得不以一己之力与他们展开对抗。另一方面，由于长期冷落家人，他和伊莲娜的婚姻也亮起了红灯。这个正义战士真正到了内忧外患的地步……本片荣获2006年青年艺术家奖剧情片最佳儿童表演奖（Adrian Alonso）。©豆瓣', '安东尼奥·班德拉斯', '马丁·坎贝尔', 7, 29746, 'tt0386140', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199286318.jpg', 0.5, 4, 48.3, 37.8, 9.4, '0.166053,0.168440,-0.525131,0.519411,-0.006656,-0.111080,0.486607,0.049889,-0.503668,-0.220458,0.178828,0.825136,-0.033268,0.225478,0.353163,0.058861,-0.359462,-0.721561,-0.017688,-0.054419,-0.030136,-0.373806,-0.472259,-0.076036,-0.244107,-0.419086,0.638389,0.055580,-0.070099,0.503824,0.443583,0.307792,-0.020115,0.371275,-0.123545,-0.058020,0.180731,-0.127483,-0.407615,0.277136,-0.092497,-0.253217,-0.255078,0.246904,-0.046633,0.340292,0.404939,-0.542809,0.178722,-0.111720,0.491052,-0.359390,-0.297235,0.169327,0.287470,-0.113201,-0.002515,0.069410,0.093125,-0.073823,0.019856,-0.231393,-0.835266,0.023140,0.073851,0.123807,-0.539096,0.641415,-0.344341,-0.085785,0.095114,-0.184124,0.108661,0.400480,0.071871,0.340810,-0.264904,-0.059799,-0.405608,0.219777,0.560697,0.084929,-0.422765,0.077243,-0.173242,-0.593472,-0.137879,-0.357201,-0.525973,-0.298682,0.311742,0.089143,0.203018,0.370998,-0.608110,-0.001640,-0.321250,-0.183995,0.308792,-0.198745,-0.081856,-0.453522,-0.121080,-0.409736,-0.129019,0.151135,0.003439,-0.248746,0.947012,-0.934699,0.349884,0.371448,0.359806,-0.296677,0.554006,0.096940,0.228154,-0.191890,-0.264071,0.396972,-0.098371,0.363082,0.065416,0.264413,-0.101573,-0.183937,-0.040188,0.682863', '27602116', '24284209', '1870681', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309043', '金刚', '动作', '导演率领拍摄组来到神秘的骷髅岛开始了一部电影的拍摄，女主角是漂亮娇小的安(娜奥米•沃茨 Naomi Watts 饰)，她在纽约的演艺事业陷入了低谷，这是她时来运转的大好机会。他们乘坐轮船来到岛上，却不知在岛上即将要险象横生。正当导演要开始开机拍摄时，他们遭到了当地土著的袭击，几个随行人员遇难身亡。摄制组慌忙逃离，幸好起航离去，却发现不见了女主角安。原来安土著野人抓走，被当作祭品。安尖声惊叫，引来了传说中骷髅岛的猩猩——金刚的关注。金刚在岛上很有霸气，连恐龙都要忌它几分。然而，野兽爱上了美人，金刚搭救安脱离困境，不料却让自己陷入了一场悲剧。©豆瓣', '安迪·瑟金斯', '彼得·杰克逊', 8, 295791, 'tt0360717', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p858079649.jpg', 0.2, 1.5, 23, 50, 25.3, '0.141098,0.048268,-0.735101,0.164701,0.367682,-0.042760,0.782912,0.079580,-0.316111,-0.128931,0.093252,0.823582,-0.596883,0.228014,0.206319,0.123682,-0.271408,-0.342940,-0.250890,0.014185,-0.142973,0.088080,-0.123139,-0.206786,0.080763,-0.438528,0.566017,0.396038,-0.263933,0.397755,0.523708,0.249871,-0.228948,0.681203,-0.114917,0.352231,0.027943,-0.342989,0.111431,0.367193,-0.267950,-0.361173,-0.088383,0.376506,-0.000488,0.329202,0.768954,-0.141719,-0.030990,-0.096608,0.354578,-0.437553,0.075667,-0.064056,0.514197,-0.249790,-0.172060,-0.058310,-0.114750,0.157792,0.106678,-0.271857,-0.474935,0.184209,0.267766,0.132494,-0.698235,0.204728,0.103973,0.498982,-0.026632,-0.073474,0.446225,0.297027,0.177275,0.112682,0.414776,0.122886,-0.641832,0.192359,0.858638,-0.096590,-0.091870,0.359235,0.113895,-0.619647,-0.231132,-0.219650,-0.222642,-0.111526,0.625208,-0.053879,-0.303103,-0.076684,-0.549679,-0.110392,-0.394087,-0.157677,-0.435482,-0.261942,-0.273205,-0.653749,0.097712,-0.198828,-0.184320,0.251895,-0.284219,-0.072040,0.672865,-0.820975,0.267431,0.522357,0.079176,-0.387628,0.622150,-0.139823,-0.118646,-0.178979,0.209427,0.390078,0.123182,0.333461,0.208929,0.020811,-0.364432,-0.219919,-0.405570,0.259038', '1294941', '25721544', '21619567', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309044', '世界之战', '科幻', '雷•费瑞尔（汤姆•克鲁斯 Tom Cruise 饰）和妻子离婚了，一儿一女都跟母亲生活——因为他的的贪玩懒散，疏忽责任，这个家庭才如此支离破碎。一场外星人入侵的灾难却让他们重新建立起亲密的的关系。这天妻子繁忙，只好把儿女交给雷照顾。电闪雷鸣天色灰暗，一切好像有些异样。 果然，马路上赫然一个庞大的三脚飞行器掘地而起，邪恶的火星人光顾了这个本来平静的小镇。人们四处逃亡，雷也带着女儿奔走逃命，开始了生死历险。当局想尽办法对付外星人，却屡屡失败，整个世界都陷入了恐慌当中。有了父爱的本能，平日吊儿郎当的父亲变得英勇顽强，保护儿女成了他支撑他的动力和信念。©豆瓣', '汤姆·克鲁斯', '史蒂文·斯皮尔伯格', 6.7, 84261, 'tt0407304', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2243507786.jpg', 2, 10.3, 48.9, 29.7, 9.1, '-0.078661,0.045043,-0.893340,0.447370,-0.171875,-0.330132,0.825613,0.132263,-0.502377,-0.257268,0.025037,0.683538,0.079135,0.309736,0.287155,-0.087314,-0.402965,-0.602363,-0.253763,0.341547,-0.152238,-0.313452,-0.359239,-0.333642,-0.029344,-0.385742,0.410971,0.290579,-0.116857,0.470674,0.138749,0.072545,0.011278,0.522661,0.017575,-0.008741,-0.343261,0.119962,-0.086112,-0.207846,-0.089179,-0.208130,-0.148057,0.349158,0.050809,0.598158,0.691700,-0.241936,-0.319672,-0.313557,0.450726,-0.375059,-0.155334,0.233353,0.212990,-0.040717,-0.060577,-0.056377,-0.021679,-0.274755,0.023925,-0.057497,-0.835627,0.021013,0.039156,-0.136370,-0.619512,0.423597,0.141430,0.020600,-0.155339,-0.165007,0.320257,0.432667,-0.004180,0.579570,-0.550659,0.236012,-0.362866,0.042935,0.605194,-0.022045,-0.351104,0.247726,-0.417910,-0.161317,-0.068293,-0.335010,-0.625071,-0.386749,0.539055,-0.025932,-0.204301,0.497285,-0.710234,0.069002,-0.189823,-0.250763,-0.202301,-0.524496,-0.081514,-0.182169,-0.025094,-0.469889,-0.280985,0.200391,-0.104740,-0.159337,0.748853,-0.534768,0.194229,0.539660,0.199389,-0.583229,0.402051,0.030056,0.222646,-0.175218,0.193666,0.309968,-0.069001,0.360662,0.392339,0.183679,-0.067454,0.362532,-0.278344,0.587515', '1307311', '1481233', '2357162', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309045', '电锯惊魂2', '悬疑', '凶残成性的“竖锯”（托宾•贝尔 饰）带着更新更诡异的杀人游戏回来了。又一位带着“竖锯”标签式的死亡特征的受害人被警方发现，这令探员艾里克•马休斯(当尼•沃伯格 饰)重新回到之前的惊悚噩梦之中。但出人意料的是杀人者留下了十分明显的线索，警方的调查取证工作十分顺利。其实，所有这一切都在“竖锯”(托宾•贝尔 饰)的掌控之中，留下线索并令自己被捕正是他进行下一个邪恶游戏中的重要前提：即将有8位相互陌生的人被迫加入游戏，而更疯狂的是，除此之外的另一位游戏者已经被锁定为马休斯。在“竖锯”的策划下，又一场充满惊险的生死游戏就要开始了……©豆瓣', '托宾·贝尔', '达伦·林恩·鲍斯曼', 8.3, 201610, 'tt0432348', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1421210839.jpg', 0.3, 1.1, 15.5, 47.7, 35.4, '0.322852,0.043026,-0.451260,0.599024,-0.025494,-0.115480,0.834318,-0.107456,-0.404912,0.007361,0.420792,0.428098,-0.350082,0.074933,0.189178,-0.063424,-0.367725,-0.567238,-0.060767,-0.011925,-0.490335,-0.431199,-0.345778,-0.193114,-0.122994,-0.099237,0.424439,0.169872,-0.044392,0.412648,0.292916,0.582805,-0.135602,0.423129,-0.145626,-0.060741,-0.012511,-0.335061,-0.131550,0.168520,0.199657,-0.082692,-0.142789,0.336478,-0.233423,0.702677,0.638762,-0.421710,-0.236245,-0.045217,0.372828,-0.302751,-0.116681,0.172382,0.379119,0.348086,0.056451,0.162838,-0.182992,0.062832,0.088254,-0.168455,-1.049394,0.004564,0.128385,0.378315,-0.225878,0.324452,-0.170930,0.280927,0.176873,-0.197423,0.021407,0.121508,0.449912,0.085993,-0.045148,-0.010222,-0.445091,-0.029331,0.247255,-0.211363,-0.299396,0.332520,-0.132710,-0.431929,-0.135461,-0.072211,-0.079746,-0.101284,0.509112,0.123440,-0.000054,0.386194,-0.746791,0.150175,-0.138506,-0.296658,-0.274982,-0.322243,-0.292937,-0.690629,0.047224,-0.240378,-0.187737,0.297509,0.161461,-0.265681,0.327104,-0.669371,0.229045,0.414325,-0.091227,-0.293615,0.371390,-0.002303,0.307258,-0.187988,-0.335558,0.110394,0.245464,0.293098,0.372448,0.460580,-0.226447,-0.158795,-0.505424,0.839022', '1308585', '10440138', '1793912', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309047', '粉红豹', '喜剧', '国际足球教练在庆功派对中不幸中毒镖毙命，手上的钻石戒指“粉红豹”也随之失踪。谋杀与失窃案迅速成为关注焦点。破案重任落到总探长德雷福斯(凯文·克莱恩 Kevin Kline 饰)肩上。无奈中，他想到了最佳破案人选——探员杰奎斯•克鲁索(史蒂夫·马丁 Steve Martin 饰)。临危受命的克劳索与总探长指派的木讷探员波顿(让·雷诺 Jean Reno 饰)组合成为一对儿“黄金搭档”。克劳索将教练女友歌坛天后仙妮娅(碧昂丝·诺尔斯 Beyoncé Knowles 饰)列为首要的嫌疑对象，谁知调查时却对她一见倾心。一路上克劳索遭遇各种勤快，钻石贩子、黑道分子、傲气足球明星、赌场老板、风情女政客，各色人物轮番登场，究竟谁才是名钻大盗？案情的进展一波三折，克劳索该如何按时侦破这桩惊世大案，同时有效提防虎视眈眈的总探长把功劳据为己有？©豆瓣', '史蒂夫·马丁', '肖恩·利维', 7.4, 37140, 'tt0383216', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1077616276.jpg', 0.9, 4.8, 36, 42.1, 16.2, '-0.010762,-0.145925,-0.172414,0.005584,0.180804,-0.032042,0.241462,0.071858,-0.469862,-0.205212,0.481405,0.445151,-0.368819,-0.266837,0.451878,0.022799,-0.327328,-0.664919,0.269163,-0.032846,-0.087249,-0.508479,-0.353471,-0.052351,0.088331,-0.158128,0.286238,-0.082889,-0.074032,0.449080,0.521519,0.498998,-0.224643,0.183185,0.246413,-0.221751,0.569890,-0.266792,-0.179028,0.187084,0.037516,-0.143510,-0.165268,-0.037256,0.329495,0.218036,0.429460,-0.249142,0.074660,-0.002098,0.223038,-0.203337,0.091559,-0.003667,0.306561,-0.040512,0.176982,0.359316,-0.030664,-0.225729,0.188806,0.042811,-0.474209,0.048577,0.318870,0.345753,-0.296378,-0.091291,-0.362773,0.122450,-0.000042,0.029854,0.120567,0.098458,0.387797,-0.120474,0.089667,0.274572,-0.118292,0.154277,0.181957,0.187091,-0.147079,-0.256932,0.136275,-0.255314,-0.031455,-0.036951,-0.037028,-0.118427,0.414337,-0.172745,0.546859,0.541624,-0.237897,-0.115668,-0.499359,0.185478,-0.069086,-0.243293,0.020409,-0.490069,0.064323,0.068247,-0.253073,-0.015481,0.347419,-0.052413,0.384422,-0.348692,-0.055836,0.360817,-0.115216,-0.152516,0.335484,0.078912,0.218799,-0.514726,-0.651594,0.112845,0.482526,-0.081287,-0.143888,0.164208,0.063198,-0.485565,0.054353,-0.013505', '6517421', '1865012', '1905786', '2369549');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309049', '四眼天鸡', '喜剧', '小鸡玛德机灵聪明，可是一直胆小怕事，戴着一幅笨重的大眼镜常常受到朋友们的捉弄和讥笑。一天它看到了天上忽然落下了一块碎片，以为是天要塌下来了，它到处惊慌的通知大家，一如既往惹来了众人的嘲笑。回到家里也只有爸爸与好朋友的鼓励。它一直以爸爸为榜样，希望能像爸爸那样成为一个杰出的棒球运动员，好不容易得到了一个出赛的机会，就算大家都认为它没法帮球队胜出比赛，但是它做到了。没想到它遇到了从外太空来的生物，就算它继续受到嘲笑它仍坚持自己眼睛看到的东西，地球受到了另一个星球的攻击，就是为了要找会误留在地球的孩子，而玛德又能否帮助小家伙找回自己的父母呢？玛德又是否依然被人嘲笑嘲弄呢？©豆瓣', '扎克·布拉夫', '马克·汀戴尔', 6.8, 19871, 'tt0371606', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1271265803.jpg', 0.9, 7, 53.2, 30.2, 8.6, '-0.231869,-0.011631,-0.490215,0.444176,-0.413338,-0.350320,0.276898,0.020075,-0.299834,-0.093976,0.115340,0.737952,-0.093754,0.280706,-0.248940,-0.032544,-0.258778,-0.453679,0.207285,-0.003521,-0.383490,-0.092364,-0.194612,-0.040767,-0.062023,-0.202149,0.403457,0.048203,-0.015830,0.294419,0.188085,0.073715,0.281214,0.480327,-0.417582,-0.200437,-0.350272,0.171306,-0.015449,0.259875,0.122402,0.159616,-0.074596,0.278971,-0.040837,0.010358,0.422395,-0.131012,-0.334356,-0.239423,0.249331,-0.240883,0.209127,0.333223,0.142875,-0.111423,0.256757,-0.258095,-0.008781,0.223615,0.278942,-0.097967,-0.739781,0.020134,-0.122051,0.031697,-0.486361,0.326526,0.201083,0.002969,0.035287,-0.181007,0.438064,0.232137,0.379742,0.459936,-0.575822,0.177222,-0.645659,-0.259488,0.445023,-0.097418,-0.330075,0.265208,0.083179,-0.230188,0.168002,-0.411196,-0.462026,0.356369,0.210482,0.146765,-0.464421,0.039595,-0.519254,0.078594,-0.202296,-0.289672,0.017996,-0.716145,-0.048033,-0.108071,0.326626,-0.042754,-0.262975,0.301122,0.009202,-0.417435,0.954153,-0.849604,0.240986,0.591875,0.398336,-0.565292,0.525163,0.063931,-0.124336,-0.181889,-0.013843,-0.021075,0.273489,0.317389,0.221330,0.151399,0.131413,-0.232355,-0.228332,0.297264', '24284209', '27602116', '1877596', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309050', '最长的一码', '剧情', '曾经风光无限的美式橄榄球四分位选手保罗·克洛伊（亚当·桑德勒 Adam Sandler 饰）的人生跌入谷底，他先是因假球事件饱受争议，随后又因酒驾拘捕而被送入监狱。监狱长沃顿·海森（詹姆斯·克伦威尔 James Cromwell 饰）喜爱橄榄球却残忍冷酷的家伙。他欣赏保罗的才能，于是要求他和其他囚犯组建一支球队，与狱警球队展开对抗。在保罗和同样身陷囹圄的金牌教练奈特·斯卡布罗（伯特·雷诺兹 Burt Reynolds 饰）的调教下，一支奇怪的球队在监狱中诞生了……本片根据1974年的同名金球奖影片改编，并荣获2005年BET喜剧奖最佳男配角奖（Chris Rock）、2005年青年选择奖。职业摔角手Bill Goldberg、Kevin Nash、Stone Cold Steve Austin等人亦在片中出演角色。©豆瓣', '亚当·桑德勒', '彼得·西格尔', 7.6, 20925, 'tt0398165', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p858828132.jpg', 0.3, 2.2, 30.7, 49.6, 17.2, '-0.178609,-0.123337,-0.219940,0.514817,-0.051519,-0.263391,0.668852,0.145129,-0.475578,0.019499,0.443209,0.784886,-0.324285,-0.108891,0.586309,-0.259273,-0.380202,-0.802761,-0.209718,-0.102509,-0.013956,-0.410229,-0.372659,-0.220725,0.211838,-0.382460,0.863213,-0.220193,-0.196545,0.374045,0.483987,0.365200,0.026637,0.033384,0.058200,0.044518,0.361208,-0.109568,-0.370489,0.303193,-0.066956,-0.358695,-0.516452,-0.096345,0.184691,0.109824,0.618238,-0.258399,0.165863,-0.172315,0.279363,-0.124292,-0.130409,-0.097148,0.159628,0.017222,0.185948,0.168845,0.299592,0.217834,0.035909,-0.404096,-0.618392,0.162657,-0.043493,0.130817,-0.302282,0.577494,-0.346831,0.276370,-0.066657,0.092707,-0.104629,-0.120366,0.495095,0.275367,-0.065066,0.017677,-0.106073,0.558207,0.097431,0.009931,-0.344097,-0.050989,-0.226561,-0.785521,-0.256811,-0.256493,-0.613380,0.113384,0.674537,0.051352,0.187534,0.304532,-0.489236,0.113103,-0.162395,-0.262724,-0.114827,-0.229067,0.068987,-0.628739,0.076598,0.045573,-0.236535,-0.201311,0.081397,-0.168171,0.527155,-0.447544,0.272982,0.515163,0.086744,-0.149772,0.451297,0.035154,0.192545,-0.302829,-0.410159,0.447660,-0.034104,-0.101401,0.041610,0.417473,-0.135759,-0.304299,-0.195474,0.443272', '1780122', '1299663', '3479570