INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309051', '红眼航班', '惊悚', '夜间班机因旅客大都熬夜熬得双眼通红，故得名为红眼班机。勒克斯大西洋酒店的高级行政人员丽莎（瑞秋•麦克亚当斯 Rachel McAdams 饰）今天不得不搭乘她最不喜欢的红眼班机，因为她必须在参加完祖母的丧礼后明天就赶回酒店工作。丽莎的运气还不错，在机场遇到了英俊潇洒的杰克逊（希里安•墨菲 Cillian Murphy 饰），两日相谈甚欢。更让丽莎惊喜的是，两人搭乘的是同一班红眼班机，而且还相邻而坐。本以为一段美好的缘分就此展开时，丽莎万万没有想到，原本温文尔雅的杰克逊露出了他的狰狞面目。原来杰克逊是恐怖分子的一员，他正要前往刺杀住在勒克斯大西洋酒店的安全部的高官。现在，恐怖分子绑架了丽莎的父亲，要求身为该酒店主管的丽莎协助杰克逊完成这一刺杀任务。在恐怖分子的要挟下，丽莎将何去何从？©豆瓣', '瑞秋·麦克亚当斯', '韦斯·克雷文', 6.8, 20729, 'tt0421239', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2153063340.jpg', 0.8, 6.3, 51.9, 33.6, 7.5, '0.390632,0.064231,-0.810468,0.314293,-0.054316,-0.489217,0.422885,0.301663,-0.381354,-0.263283,0.484275,0.825680,-0.227700,0.061255,0.420587,0.308666,-0.523683,-0.377902,-0.003377,-0.272285,-0.261180,-0.600032,0.029944,-0.001232,0.387490,-0.323116,0.297371,-0.069624,0.162720,0.536516,0.251639,0.065566,0.079799,0.400053,-0.121549,-0.250283,0.278014,-0.154405,-0.146004,0.382455,0.229902,-0.057706,-0.162686,0.111380,0.250296,0.387686,0.534738,0.053720,-0.160515,-0.066300,0.126202,-0.411616,0.047586,0.005277,0.488479,-0.320769,0.120802,0.249630,-0.229058,0.085595,0.196779,0.092663,-0.834230,0.236475,-0.074520,0.113574,-0.456650,0.442732,-0.490700,-0.017211,0.323904,-0.530922,0.281764,0.740557,-0.097981,0.332969,0.101483,0.071100,-0.638634,0.194228,0.761693,0.175031,0.143327,0.165421,-0.108740,-0.332473,0.222442,-0.050334,-0.378889,0.049780,0.260030,-0.162600,-0.080341,-0.004474,-0.377886,-0.189329,-0.341922,-0.138998,-0.022459,-0.382549,-0.218604,-0.845215,0.350672,-0.241775,-0.188214,-0.042890,0.143662,0.086563,0.397882,-0.944750,0.219171,0.528077,0.254128,-0.296517,0.652558,0.233363,0.220433,0.030571,-0.091478,-0.079232,0.119038,0.583182,0.124813,0.364889,0.016613,-0.342586,-0.345554,0.246381', '3178770', '11541282', '10519331', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309052', '纳尼亚传奇1：狮子、女巫和魔衣橱', '剧情', '二战期间，四个小孩子随着父母来到乡下避战。这些乡村住宅古色古香，其中有一个房间里摆着一个大衣柜。一天，几个小孩子玩捉迷藏，露西（乔基·亨莉 Georgie Henley 饰）躲进了衣柜里，眼前却意外出现了一个神奇的世界——那里白雪皑皑，荒无人烟。她在雪地上走着走着，遇上了 人羊怪物。其他孩子也一一进入这个魔法衣橱。他们得知里面的王国叫纳尼亚，正在被一个邪恶的女巫所统治。女巫想把这几个外来者一网打尽，同时这些孩子得知纳尼亚正在女巫的黑暗统治后，和雄狮亚斯兰并肩作战，帮助纳尼亚开始了复国之举。©豆瓣', '乔芝·韩莉', '安德鲁·亚当森', 7.5, 175097, 'tt0363771', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p815647942.jpg', 0.7, 4, 33.4, 42.6, 19.3, '0.675224,0.179514,-0.598870,0.582386,-0.067598,-0.098554,1.011916,-0.057846,-0.381690,-0.559599,-0.018420,0.734148,-0.106997,0.521006,-0.040485,0.090391,-0.533005,-0.431899,-0.477215,-0.377185,-0.581843,-0.243914,-0.396082,-0.147947,-0.199409,-0.011947,0.320162,0.023515,0.065427,0.327102,0.215731,-0.002354,-0.530996,0.143455,-0.386253,0.041142,0.289772,-0.179475,-0.012917,0.326418,-0.321069,-0.013988,-0.153923,0.127078,-0.046275,-0.076634,0.764683,-0.523876,0.129665,-0.422779,0.363283,-0.054739,-0.286909,0.181888,0.384875,-0.153620,0.189592,-0.101267,0.086330,0.114270,0.100453,-0.300385,-0.440387,-0.017704,-0.226109,0.125568,-0.800957,0.162068,0.243337,-0.147115,0.170243,-0.237703,0.429686,0.357220,0.178591,0.449358,-0.078457,0.106863,-0.770426,-0.264170,0.488311,-0.268445,-0.001188,0.068849,0.030201,-0.305981,0.198005,0.193601,-0.451883,-0.212299,0.310000,-0.266346,-0.180577,0.026301,-0.932714,0.532742,-0.289447,-0.153567,0.026694,-0.249347,-0.381232,-0.487502,-0.086744,0.057737,-0.391694,0.272939,-0.179554,-0.047753,0.649724,-0.456962,0.372840,0.491402,0.388967,-0.109928,0.564621,-0.250500,0.453057,-0.034141,0.033967,0.212736,0.214271,0.359424,0.067764,0.652989,-0.188390,-0.097805,-0.528231,0.332442', '21619567', '1467779', '1578663', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309053', '格林兄弟', '喜剧', '威尔·格林（马特·达蒙 Matt Damon 饰）和杰克·格林（希斯·莱杰 Heath Ledger 饰）是一对游手好闲、靠诈骗为生的骗子。他们经常在不同地方雇人扮演妖魔鬼怪进行大肆的破坏，然后自己以驱魔人的身份出现“消灭”妖怪，以此来骗取村民们的报酬。由于这样的手法屡屡得逞，格林兄弟驱魔人的名声越来越大，甚至被法国国王召见，邀请他们前往被诅咒的森林里面揭开失踪少女之谜。这下，格林兄弟只得硬着头皮前往魔法森林。在森林里，灰姑娘、小红帽这些原本童话里面的人物悉数登场……最后，他们发现原来是因为女魔头镜子皇后（莫妮卡·贝鲁奇 Monica Bellucci 饰）为了保持青春，必须杀死年轻的女性，并用她们的血肉来回复青春。于是，格林兄弟与女魔头的世纪大战就此拉开……他们能否获得童话般的美好结局呢？©豆瓣', '马特·达蒙', '特瑞·吉列姆', 6.6, 32253, 'tt0355295', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p457109215.jpg', 1.3, 10.1, 54.4, 27.5, 6.7, '0.219927,0.050101,-0.384962,0.389039,-0.164421,0.024972,0.570375,-0.124352,-0.417585,-0.310051,0.242845,0.657276,-0.227544,0.035900,0.246611,-0.060402,-0.582231,-0.325624,-0.109285,-0.233535,-0.073415,-0.236729,-0.447782,-0.193970,-0.021263,-0.282942,0.666489,-0.011512,-0.289341,0.270927,0.328581,0.389408,-0.276099,0.048373,-0.111792,0.014263,0.057632,-0.206720,-0.268007,0.283041,-0.137066,-0.131937,-0.101698,0.023163,-0.132836,0.140069,0.658214,-0.485601,0.216407,-0.268723,0.269983,-0.335641,0.013171,0.086927,0.300652,-0.210721,0.481718,0.198354,0.072271,-0.060452,0.194895,-0.226937,-0.531378,0.232727,0.144275,0.152778,-0.349155,0.046133,0.110822,0.058909,0.294419,-0.303765,0.165714,0.259489,0.530927,0.092760,0.025536,-0.021406,-0.654040,0.040129,0.478397,-0.091206,-0.065940,0.151546,-0.221987,-0.303006,0.055173,-0.409433,-0.351636,0.017214,0.399622,-0.111180,-0.094953,0.310338,-0.751899,-0.326044,-0.326156,-0.091590,0.207139,-0.286704,-0.265133,-0.885951,-0.022609,-0.104547,-0.134962,-0.021901,0.074472,-0.182467,0.557942,-0.591145,0.221340,0.399019,0.217670,-0.451176,0.477360,-0.045920,0.170022,-0.067835,-0.347404,0.367445,0.309058,0.306336,0.060811,-0.022817,-0.038198,-0.085062,-0.281217,0.356125', '1294917', '2369613', '20274039', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309054', '天气预报员', '剧情', '戴维（尼古拉斯·凯奇 饰）是名天气预报员，可是他没有专业知识能用在工作上，当预报的天气并不理想时，观众们会在街上肆意向他丢垃圾。戴维对自己的生活感到灰暗，与妻子（霍普·戴维斯 饰）离婚更是对他的一个打击。如今他得到一个前往纽约重新工作的机会，可是他必须要面对与孩子们并不融洽的关系。儿子迈克被戒毒时认识的辅导员性骚扰；女儿雪丽的肥胖被学校的同学耻笑，性格忧郁。更令戴维伤心的是，他的小说家父亲罗伯特（迈克尔·凯恩 饰）患上了绝症。戴维希望父亲能看到他的成功，他更想与前妻复合，一家人到纽约重新生活。无论做了多大的努力，他与家人的关系并没得到和缓，他依然遭到观众的垃圾袭击，他更开始抗拒前往纽约。此时他看到父亲平静面对死亡的态度，并在与父亲相处的最后时光中，戴维被授予了很多人生的道理。©豆瓣', '尼古拉斯·凯奇', '戈尔·维宾斯基', 7.7, 54760, 'tt0384680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2446344963.jpg', 0.3, 2.3, 28.6, 49.1, 19.8, '0.241513,-0.006199,-0.745859,0.568565,-0.217244,-0.394164,0.940387,0.096739,-0.689512,-0.297186,0.034082,0.913382,-0.142716,0.329999,0.041508,0.025301,-0.377675,-0.730367,0.086597,0.066431,-0.187216,-0.556856,-0.175366,-0.229286,-0.293519,-0.280205,0.529763,-0.039532,-0.073667,0.380732,0.232219,0.243720,0.286749,0.778718,-0.259253,-0.114819,-0.012315,0.063737,-0.355576,0.171269,0.310983,-0.124747,-0.188462,0.323480,0.128396,0.394819,0.553457,0.070526,-0.352158,-0.057910,0.266385,-0.178433,0.062539,0.351681,0.207515,-0.109243,0.191993,0.363173,-0.091273,-0.019656,-0.043686,-0.066817,-0.696687,0.139854,0.000420,0.276318,-0.478162,0.519270,-0.218139,-0.048956,0.103528,-0.404796,0.229259,0.299012,0.179262,0.449567,-0.360326,-0.024660,-0.434267,0.151995,0.889625,0.014481,-0.112022,0.523850,-0.485265,-0.378525,-0.073368,-0.277134,-0.593345,0.190513,0.275960,0.152535,-0.270232,0.344074,-0.403110,-0.024603,-0.188731,-0.230934,-0.197754,-0.502675,0.093945,-0.364982,0.030923,-0.486990,-0.614120,0.026734,0.019428,-0.493508,0.659042,-0.906686,0.138564,0.401032,0.461188,-0.641166,0.590557,0.413615,-0.008641,-0.204132,-0.091335,0.343365,0.001988,0.253540,0.128046,0.226712,0.146402,-0.193944,-0.215614,0.703461', '1308755', '4275444', '25721544', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309055', '哈利·波特与火焰杯', '悬疑', '这是一个不同寻常的学期，魔法学校的盛事：三强争霸赛在霍格沃茨举行。学生们争先报名，希翼获得永恒无上的荣誉。火焰杯在选出三所学校的三名勇士后，竟将未足年龄的哈利也挑选出来。哈利（Daniel Radcliffe饰）的当选引起其他学生的嫉妒连连，就连铁哥们罗恩（Rupert Grint饰）也首次和他闹起了别扭，哈利感到孤立无援，还好有教父小天狼星和赫敏一直支持他。可总有些好事者如记者丽塔等着看他的好戏。天知道这场比赛是何等艰辛危险，在龙的眼皮下偷蛋，潜入湖底救人，在迷宫中探险……一不小心，甚至可能付出生命的代价。黑魔王伏地魔的威胁渐渐显现，每一天都险象环生，动人心弦。©豆瓣', '丹尼尔·雷德克里夫', '迈克·内威尔', 8.7, 593543, 'tt0330373', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735391084.jpg', 0.1, 0.6, 10.5, 39.6, 49.2, '-0.064564,-0.157182,-0.620818,0.301485,0.143362,-0.172429,0.591107,-0.102673,-0.368349,0.057184,0.369825,0.682474,-0.504627,0.423975,0.261591,-0.272897,-0.258303,-0.621355,-0.267579,-0.223882,-0.257715,-0.204984,-0.262997,-0.143882,0.023546,-0.471137,0.470658,0.295155,-0.170779,0.396118,0.391630,0.020426,0.073453,0.386305,-0.065962,-0.180171,0.152627,0.171446,0.181166,0.019596,0.021118,-0.089958,-0.578550,0.250127,0.250884,0.296419,0.468228,-0.421242,-0.055706,-0.003059,0.502898,-0.371843,-0.116365,0.282106,0.337578,-0.007676,0.065032,0.101152,0.265580,0.232458,0.002751,0.086524,-0.842687,0.119168,0.165333,0.382681,-0.529472,0.585233,0.210255,-0.000861,0.235058,-0.031755,-0.007646,0.201641,0.006448,0.149575,-0.346607,-0.086976,-0.541192,0.159839,0.550183,-0.165584,-0.320233,-0.151728,-0.176737,-0.525238,-0.007686,-0.109914,-0.386677,-0.021190,0.506191,-0.034824,0.290022,0.299729,-0.622393,-0.057932,-0.079156,-0.430674,-0.160756,-0.354280,-0.081158,-0.629959,0.121242,-0.093138,-0.324626,0.003545,0.221236,-0.440411,0.770433,-0.630426,0.158869,0.552551,0.152837,-0.215921,0.622399,-0.036192,0.208610,-0.032488,-0.292008,0.138341,-0.038998,0.359840,0.022628,0.430715,0.156326,-0.081873,-0.133292,0.527438', '27602116', '1793491', '25928048', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309056', '魔窟', '动作', '杰克（科尔•豪瑟 Cole Hauser 饰）与泰勒（艾迪•斯比安 Eddie Cibrian 饰）两兄弟是两个酷爱探险的洞窟专家，在生物专家尼古拉（Marcel Iures 饰）和詹妮丝博士（Lena Headey 饰）的邀请下，他们携经验丰富的团队来到罗马尼亚卡尔巴阡山 脉，准备对偶然在这里发现的巨大洞穴以及其中的古教堂进行勘查。探险队员布里格斯（Rick Ravanello 饰）最先入水勘测，但通讯后不久便和队友失去联系。为了安全起见，杰克与泰勒决定全体出发寻找。沿途他们见到各种前所未见的古怪生物，原来在这座封闭的山洞里，竟有着一个完全独立的古生物系统。但是这些发现并未给他们带来太多惊喜，这群探险者已被困在山洞里，而来自未知生物的威胁正渐渐逼向他们……©豆瓣', '科尔·豪瑟', 'Bruce Hunt', 6.3, 11516, 'tt0402901', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165824447.jpg', 2.4, 15.1, 54.9, 21.8, 5.9, '0.306047,-0.251712,-0.726765,0.534776,0.063441,-0.225760,0.973717,-0.224926,-0.697896,-0.441905,0.048442,0.684835,-0.131354,0.040677,0.238547,-0.097592,-0.608767,-0.335234,-0.230216,-0.350891,-0.519606,-0.527041,-0.339856,-0.332657,0.044722,-0.385569,0.664307,0.076390,-0.214523,0.531122,0.027334,0.478486,-0.550904,0.500984,-0.101618,-0.050058,0.141257,-0.028134,-0.348680,0.265664,-0.156741,0.104351,-0.248344,0.087940,0.131139,0.307984,0.544006,-0.527353,-0.246500,0.047428,0.077053,-0.121018,0.163025,0.108706,0.386861,0.000118,0.285909,-0.028236,-0.134670,0.133690,0.016654,-0.162165,-0.595388,0.118142,0.134849,0.251884,-0.404138,0.067923,0.086424,-0.167351,0.063327,-0.338066,0.187753,0.397664,0.188618,0.250481,-0.093614,-0.030083,-0.370443,-0.319245,0.304967,-0.175428,0.021528,0.067783,-0.046997,-0.601290,0.007311,0.209950,-0.328264,-0.059225,0.299786,0.362540,-0.029006,0.053554,-0.993284,0.136019,-0.178940,-0.387321,0.071360,-0.261345,-0.113606,-1.008469,-0.020158,-0.197322,-0.219612,0.349425,-0.005328,-0.009255,0.507714,-0.810562,0.355700,0.312286,0.109580,-0.383611,0.688405,-0.355381,0.129143,-0.267033,-0.089108,0.168582,0.345427,0.512963,0.096651,0.453770,0.002032,-0.284552,-0.483255,0.094076', '1297659', '1306809', '10466639', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309057', '疯狂金车', '喜剧', '少女玛姬（琳赛·露安 Lindsay Lohan 饰）来自一个赛车手世家，爷爷和爸爸都曾是NASCAR的冠军，玛姬的血液里自然也流淌着对赛车的热情，然而因为几年前的一次意外，玛姬的父亲开始阻拦她成为一名职业赛车手。一个偶然的机会，玛姬在汽车废弃场廉价购入了一辆破旧的甲壳虫贺比，竟不知不觉地开启了她的奇幻赛车之旅：贺比显然不是普通的汽车，它先是让玛姬误打误撞参加了NASCAR挑战赛，更是在险要关头帮玛姬跑赢了卫冕冠军墨菲（马特·狄龙 Matt Dillon 饰），种种迹象让玛姬意识到，贺比其实是一辆有灵性的疯狂汽车，它不仅和玛姬一样有着夺冠的职业理想，还爱管闲事，乐于撮合有情人。然而激速的赛车场并非儿戏，年轻的玛姬和上了年纪的贺比究竟能走多远？本片翻拍自迪士尼1968年的经典冒险喜剧电影《万能金龟车》，金龟车“贺比”诞生后很快便跻身迪士尼经典形象的行列。', '琳赛·洛翰', '安吉拉·罗宾森', 6.7, 6873, 'tt0400497', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p899504956.jpg', 1.2, 8.1, 54.8, 27.6, 8.3, '0.318170,0.234749,-0.676617,0.586502,-0.031239,-0.365300,0.675230,-0.110997,-0.393445,-0.076549,0.212301,0.879483,-0.175919,0.091770,0.156763,-0.047015,-0.051676,-0.360836,-0.093975,-0.085733,-0.335783,-0.350039,-0.435225,-0.116684,0.116931,-0.336737,0.507282,0.234592,-0.439770,0.593189,0.481398,0.012144,-0.020963,0.397040,-0.291870,-0.077797,0.306259,0.343783,-0.054956,0.135636,-0.155038,-0.293338,-0.063607,-0.069411,0.157908,0.332714,0.467309,-0.230325,-0.121978,0.276709,0.403182,-0.100260,0.009590,-0.128439,0.231467,0.042418,0.086441,0.030227,0.046530,0.001540,0.019995,-0.142619,-0.743331,0.109769,-0.046446,-0.124261,-0.574914,0.525447,-0.044433,-0.222546,0.038088,-0.202245,0.234628,-0.024310,0.202616,0.196687,-0.103820,0.034495,-0.584736,0.258461,0.717726,0.062370,-0.322865,0.591490,-0.148517,-0.657455,-0.133216,-0.362546,-0.544310,0.062408,0.523888,-0.101656,-0.019363,0.070557,-0.598329,0.181534,-0.314440,-0.089774,-0.191808,-0.038200,0.057602,-0.387695,0.076521,-0.515931,-0.094350,-0.000756,-0.144410,-0.372453,0.675799,-0.681931,0.233186,0.499050,0.051722,-0.351337,0.712213,-0.076403,0.095065,-0.033035,-0.149241,0.258870,-0.137210,0.212335,0.091179,0.500689,-0.013081,-0.278250,-0.184924,0.581089', '30162520', '35144311', '34890458', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309059', '艺伎回忆录', '剧情', '根据美国作家阿瑟-高顿的同名小说改编。故事以第一人称展开，时代背景从1929年开始延续到二战结束，女主人公回忆了自己从小拼命挣扎、历尽荣辱的人生经历。有着一双蓝灰色眼睛的小百合（章子怡饰）出生于贫穷小渔村，被卖到京都一家知名的艺伎馆。小百合在那里学习了舞蹈、茶艺等，渐渐成为当地头牌艺伎，同时也不断受到京都第一红伎初桃（巩俐饰）的压迫与挑战。一个偶然的机会，全日本最美丽、知名的艺伎真美羽（杨紫琼饰）要认小百合为“妹妹”，此举从此改变了小百合的一生……©豆瓣', '章子怡', '罗伯·马歇尔', 7.6, 249558, 'tt0397535', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453716919.jpg', 0.5, 3.4, 30.5, 45.2, 20.3, '0.024218,0.199946,-0.438152,0.536614,0.363568,-0.149644,0.357613,0.098305,-0.206919,-0.303949,0.262750,0.739083,-0.195866,0.250604,0.351860,-0.181064,-0.031715,-0.479617,-0.048677,-0.280131,-0.173650,-0.103554,-0.153182,0.225772,-0.213928,-0.115605,0.635487,-0.009051,-0.427473,0.494397,0.388124,0.077849,-0.037102,-0.305325,-0.131914,0.092909,0.058839,-0.106377,-0.362958,0.150732,-0.093276,-0.341485,-0.128929,-0.364529,-0.031350,-0.117632,0.914784,-0.527477,0.032146,-0.301750,0.567519,0.034607,-0.187889,0.114452,0.063817,0.143450,0.174888,0.021657,-0.151908,-0.027498,0.191709,-0.397103,-0.495541,-0.003472,0.378573,0.312987,-0.425284,0.162342,0.214247,-0.211764,0.250792,-0.368498,-0.115150,0.114179,0.396656,0.331275,-0.169700,0.230485,-0.263527,0.516481,0.445862,0.188204,-0.222650,0.405119,-0.103125,-0.255202,0.136392,-0.319353,-0.338854,0.039461,0.299999,-0.105703,-0.247380,0.435674,-0.656251,0.037358,0.022052,-0.393531,0.423846,-0.193545,-0.126066,-0.621477,-0.347000,-0.367268,0.128599,0.092981,0.284463,-0.121180,1.004932,-0.779726,0.323120,0.464029,0.024153,-0.226674,0.404486,0.071653,0.109643,0.119476,-0.124579,0.344793,0.121914,0.372899,-0.217112,0.220143,-0.247753,0.031393,-0.408764,0.182611', '3811356', '5403927', '27602116', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309060', '僵尸新娘', '剧情', '维克多的父母为儿子安排了一场婚姻，未婚妻是没落贵族小姐维多利亚。维克多内向敏感，不善表达，于是婚礼前夜来到小树林中暗暗排练宣誓仪式。然而，意外发生了。当他把戒指套进地上一根树枝上面时，愕然发现树枝竟然变成了一根腐烂了的手指！维克多惊魂未定，地动山摇间眼前竟然出现了一个僵尸新娘。而这个腐烂的手指，正是长在她的身上。僵尸新娘情真意切的说自己就是维克多的合法妻子。维克多惊异万分，慢慢得知原来这个女子死于一个新婚之夜，她一直在这里等她丈夫的到来。在小树林里维克多不但认识了这个女子，还看到这片死人世界一片欢乐和睦的气氛，他被眼前的情景深深感染，畏惧渐渐散去。然而，在两个世界，两个新娘之间，维克多该如何抉择。©豆瓣', '约翰尼·德普', '蒂姆·波顿', 8.3, 353187, 'tt0121164', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p735361409.jpg', 0.1, 1, 16.7, 48.9, 33.3, '0.285070,0.224542,-0.832815,0.305059,-0.227174,-0.205456,0.927067,0.002258,-0.326903,-0.294954,0.406576,0.824730,-0.547523,0.374190,0.258792,0.219295,-0.036123,-0.833997,-0.164186,-0.172570,-0.418802,-0.217409,-0.204532,-0.268921,0.005990,-0.039813,0.500489,0.269817,0.218369,0.577649,0.375704,-0.138877,-0.274592,0.481853,-0.281163,-0.002423,0.248437,-0.138714,-0.022210,-0.109735,-0.074315,-0.200145,-0.005787,0.332079,-0.479044,0.324798,0.745483,-0.167923,-0.214757,-0.279424,0.368692,-0.210604,-0.109369,0.421639,0.360486,-0.089898,0.127020,-0.173103,-0.113292,-0.079164,0.178886,-0.013770,-0.331441,0.211714,-0.341669,0.422244,-0.622440,0.385248,0.009810,-0.149288,-0.006550,-0.410218,0.681018,0.069500,0.333162,0.489527,-0.401490,-0.192434,-0.305188,-0.039786,0.443080,0.059724,-0.157887,0.379410,-0.209270,-0.327400,0.079603,0.256151,-0.474538,-0.158171,0.193785,0.040133,-0.333348,0.238326,-0.333328,-0.116448,-0.355756,-0.142625,-0.065714,-0.536141,-0.385224,-0.153510,-0.391511,-0.136842,-0.291009,0.078451,-0.252901,-0.186439,0.347667,-0.537148,0.356605,0.336400,0.154602,-0.093679,0.343850,0.175225,0.195048,-0.200603,-0.083908,0.198082,0.035787,-0.036708,0.213387,0.362071,-0.234806,0.211125,-0.562470,0.442040', '1296534', '21348112', '3111650', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309063', '征婚广告', '喜剧', '经历过婚姻失败的莎拉（戴安·琳恩 Diane Lane饰）对感情失去了信心，大半年以来一直都是单身，与陌生男士的约会结果一次比一次糟糕。可这急坏了她的好姐妹，她们热心的四处张罗莎拉的终身大事，帮她寻觅约会对象。杂志、网络，各种类型的男士都成为了候选人士。妹妹还在征友网站上登出莎拉的资料和征友条件：这个男人必须是爱狗人士。杰克（约翰·库萨克 John Cusack饰）就在这个时候出现了，他除了爱狗以外，其他条件都不大理想。同时，刚离婚的鲍勃似乎是个完美情人，他的应征令亲友们都眼前一亮。但是，情人眼里出西施，经历了众多失败的约会之后，对感情已经灰心的莎拉，竟然发现了杰克独特的魅力，两人因为一只圣百纳宠物狗而情牵一线……©豆瓣', '戴安·琳恩', '加里·戴维·古德伯格', 6.7, 6096, 'tt0417001', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p966761705.jpg', 0.7, 6.6, 55.6, 30.3, 6.7, '0.196851,-0.222130,-0.765827,0.593789,-0.213400,-0.314216,0.642423,-0.181874,-0.479741,-0.125779,0.104431,0.666236,-0.408883,0.398550,0.225952,0.035748,-0.207910,-0.836147,0.215956,-0.174713,-0.354916,-0.415645,-0.366738,-0.200063,-0.159091,-0.452270,0.420228,-0.104345,-0.109294,0.402682,0.466293,-0.210344,0.105508,0.554143,-0.064758,0.100087,0.239859,0.175027,-0.317440,0.055574,0.032478,0.040350,-0.020060,0.296884,0.078156,0.511253,0.514204,-0.095825,-0.356367,0.110244,0.332144,-0.085780,0.010896,0.187004,0.414458,-0.093934,0.363263,0.128078,-0.075126,-0.216213,-0.036254,0.057487,-0.770861,0.158869,0.082389,0.091031,-0.550059,0.639587,-0.233032,-0.084522,0.034591,-0.238870,0.264029,0.266048,0.249641,0.318067,-0.127647,0.157818,-0.327365,0.344139,0.742227,0.241368,-0.147856,0.531951,-0.345793,-0.510497,-0.123784,-0.104976,-0.569389,0.222807,0.104276,0.013561,-0.314745,0.235773,-0.644039,0.208581,-0.114260,-0.121768,0.008121,-0.455512,-0.053946,-0.499492,-0.206447,-0.561407,-0.474412,0.125264,0.069482,-0.384990,0.921325,-0.823080,0.054206,0.516914,0.263569,-0.840947,0.973047,0.311174,0.114990,-0.197376,-0.155002,0.152459,-0.012682,0.053403,0.146269,0.277253,0.253034,-0.290744,-0.417292,0.622273', '4301278', '1418613', '30162520', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309064', '八面埋伏', '剧情', '莎拉（凯瑟琳·莫瑞斯 Kathryn Morris 饰）、妮可（帕翠西娅·维拉奎兹 Patricia Velasquez 饰）、卢卡斯（约翰尼·李·米勒 Jonny Lee Miller 饰）等七名FBI成员在资深教官杰克·哈里斯（方·基默 Val Kilmer 饰）的 带领下，来到离加州不远的弗涅戈小岛，他们将在岛上的虚拟小镇中进行演练，通过推理来找出绰号为“木偶师”的连环杀手。这群探员业务精湛，自命不凡，与世隔绝的小岛之行对他们来说更像一个无聊难耐的假期。但是，他们的狂妄并未持续太久。原本看似平常的推理演习，竟然开始出现死者，所有的逃生之路被切断，众人完全孤立在小岛之上。演习随即演变成一场精心策划的杀戮游戏……©豆瓣', '凯瑟琳·莫里斯', '雷尼·哈林', 7.6, 83786, 'tt0297284', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p854543139.jpg', 0.5, 2.9, 29.9, 50.8, 15.9, '0.316452,0.011746,-0.833460,0.537421,-0.160702,0.017604,0.642437,-0.229704,-0.423843,-0.279257,0.437673,0.410620,-0.451009,0.082945,0.284165,-0.374350,-0.498694,-0.541828,-0.231564,-0.291883,-0.305524,-0.539040,-0.201631,-0.297172,-0.169073,-0.209831,0.619767,0.151334,-0.216600,0.318190,0.072616,0.330579,-0.078317,0.387461,-0.184493,-0.105405,0.324345,-0.211270,-0.176570,0.231764,-0.250843,-0.007001,-0.087898,0.039078,0.185596,0.327453,0.862682,-0.532361,-0.064946,-0.106365,0.132755,-0.357729,0.013841,-0.046154,0.411234,0.067534,0.053737,-0.058684,-0.107749,0.185395,-0.009040,-0.349356,-0.459851,0.209070,0.151179,0.164614,-0.239468,0.277155,-0.198666,-0.113264,-0.055531,-0.232558,-0.045462,0.232235,0.583253,0.124291,0.076440,0.157200,-0.356789,0.084960,0.571952,0.159048,-0.409120,0.030149,0.011721,-0.582722,-0.192695,-0.091340,-0.052755,-0.201775,0.289894,-0.389071,0.123868,0.161926,-0.685649,-0.034319,-0.270200,-0.272830,-0.233613,-0.352977,-0.244717,-1.171408,0.214195,-0.204754,-0.135185,0.091266,-0.016466,-0.284082,0.506233,-0.723984,0.353590,0.291968,0.039348,-0.110420,0.314479,-0.006037,0.354682,-0.213156,-0.135557,0.475725,0.223801,0.539879,0.279744,0.479320,-0.158191,-0.031636,-0.351837,0.459000', '1306809', '2159244', '2369613', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309065', '魔力女战士', '动作', '21世纪初，一场瘟疫夺去了99%的人类生命，幸存者们依靠科学家古德查德的发明，建造孤城布瑞拉格维系文明。时间过去四百年后，部分市民不满古德查德政权独裁统治与持续发生的失踪案，组建武装力量魔力党（Monicans）对抗。女战士伊恩（查理兹·塞隆 Charlize Theron 饰）是魔力党中实力顶尖的人物，在完成破坏古德查德监控系统的任务中，伊恩目睹了被对方杀害的亲妹遗体，伊恩在怒火添胸时得到了刺杀古德查德首脑特雷弗的指令，但当她与特雷弗面对面时，对方呼唤“凯瑟琳”这个名字让她陷入混乱的记忆无法行动。伊恩脱身后着手调查这座城市的真相，发现一直以来的失踪案与克隆计划息息相关，而布瑞拉格运行的基础便是复制人类。伊恩的发现很快引起连锁反应，将各方势力卷入其中……©豆瓣', '查理兹·塞隆', '卡瑞恩·库萨马', 5.7, 15375, 'tt0402022', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p827467017.jpg', 5.3, 25.8, 52.1, 12.6, 4.2, '0.132321,0.195389,-0.646680,0.363567,0.045657,-0.072907,0.591041,-0.098910,-0.487902,-0.429043,0.172347,0.467389,-0.117013,-0.097231,0.279483,-0.236913,-0.611574,-0.848146,0.101983,-0.205278,-0.287587,-0.441926,-0.383419,-0.346124,-0.068845,-0.803277,0.674551,0.053155,-0.422620,0.064223,-0.158561,0.648756,-0.143547,0.180269,0.203482,-0.029927,0.526089,-0.560998,-0.408897,0.165170,-0.147755,-0.058095,-0.064624,0.351007,-0.087071,0.361594,0.653031,-0.502646,0.161166,-0.259088,0.281961,-0.355803,-0.075114,-0.033171,0.490235,0.138315,-0.214914,0.279303,-0.113042,0.024917,0.044470,-0.081420,-0.800448,-0.032285,0.014098,0.441256,-0.315671,0.116087,-0.237809,0.156588,-0.145321,-0.209277,0.171367,0.554343,0.346909,0.243464,-0.199546,0.065083,-0.451082,-0.133490,0.565051,-0.264973,-0.529273,0.143737,-0.314884,-0.576483,-0.323877,-0.293496,-0.270167,-0.156050,0.226308,0.227212,0.166846,0.848700,-0.602195,-0.304950,-0.586154,-0.178169,0.085963,-0.195080,-0.069776,-0.847616,-0.490011,0.028061,-0.156973,-0.104325,0.020060,-0.255453,0.654296,-0.639384,0.052878,0.499548,0.417362,-0.278035,0.363604,-0.091767,0.299223,-0.219131,0.088017,0.405778,0.152087,0.299604,0.075269,0.214464,0.246093,-0.106498,-0.269558,0.435489', '2369613', '1293656', '5308201', '1946776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309066', '我心遗忘的节奏', '剧情', '汤姆（罗曼·杜里斯 Romain Duris 饰）继承了父亲的地下的房地产事业，为了驱赶钉子户，他想出了各种变态的点子：放老鼠闹鼠灾、断水断电赶人、用球棒捣毁房屋设备，打伤毫不相干的人……，同时他还需要出面帮助父亲摆平各种麻烦。当他耍这些流氓手段时，心中丝毫没有怜悯。一个晚上，汤姆突然发现生活还有另外一种方向。他偶遇了去世的钢琴家母亲的经纪人，这让他想起了小时候练习钢琴的美丽时光，那是一段被现实毁掉的美好。汤姆想起优雅的母亲，试图重新拾回心中遗忘的节奏。他遇到一位教钢琴的华人女孩，虽然彼此语言不通，他还是跟她学起了钢琴。音乐让他们之间的交流越来越顺畅。汤姆沉迷练琴而耽误了房地产的工作，父亲与朋友对他越来越不满意。是跟随心中的节奏继续前行，还是被父亲的枷锁捆绑永远生活在暗无天日中，汤姆能做出自己的选择吗？本片获得2005柏林影展最佳配乐。©豆瓣', '罗曼·杜里斯', '雅克·欧迪亚', 7.6, 6000, 'tt0411270', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p450264802.jpg', 0.4, 2.9, 30.2, 48.5, 18, '0.225608,-0.063789,-0.556165,0.556650,-0.296739,-0.349536,0.876936,-0.070466,-0.447031,-0.266429,0.129314,0.680563,-0.014897,0.290812,0.177134,-0.027009,-0.379768,-0.792989,0.169253,0.068560,-0.130584,-0.389938,-0.199506,-0.323309,-0.198672,-0.177926,0.580642,0.070430,-0.226036,0.238597,0.062055,0.113586,0.128909,0.326389,-0.286854,0.092914,-0.044173,-0.077629,-0.058949,0.009366,0.225793,-0.325713,-0.087261,0.186632,-0.007684,0.336101,0.522532,0.060381,-0.169033,-0.026329,0.333745,-0.186594,-0.072610,-0.037465,-0.008655,-0.018624,0.052522,0.155506,-0.318286,-0.076571,0.079476,-0.079053,-0.727315,0.179895,-0.097527,-0.006962,-0.560035,0.235680,-0.042586,0.041444,0.118374,-0.417388,0.264117,0.223510,0.510554,0.363511,-0.232296,0.086186,-0.333380,0.282144,0.737519,-0.175166,-0.210030,0.404509,-0.373552,-0.192312,0.019225,-0.329832,-0.396134,-0.119622,0.245568,0.061373,-0.252611,0.153849,-0.506562,-0.027641,-0.060407,-0.058306,0.043416,-0.597861,0.007730,-0.502407,-0.068546,-0.384067,-0.122493,-0.127103,0.090112,-0.373485,0.692995,-0.748915,0.194296,0.590636,0.263003,-0.427728,0.531450,0.149820,0.016460,-0.075475,0.017907,0.177974,-0.055795,0.297822,0.098787,0.337609,0.301397,0.005539,-0.396320,0.486462', '30162520', '2053515', '3230462', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309067', '家有仙妻', '喜剧', '喜剧演员杰克（威尔•法瑞尔 Will Ferrell 饰）事业开始下滑，在经纪人的建议下，杰克准备翻拍经典搞笑连续剧《神仙俏女巫》。同时，为了巩固自己在该剧的地位，杰克必须找一名新人在他的剧集里演他的妻子，女巫萨曼纱。在面试了数百人后，迷人可爱而且还会和女巫一样耸鼻子的伊莎贝拉（妮可•基德曼 Nicole Kidman 饰）进入了杰克的视线。在杰克鼓动了自己的三寸不烂之舌后，伊莎贝拉终于同意和他一起出演该剧。该剧试播后反响强烈，为了和伊莎贝拉长久合作下去，杰克决定假戏真做，向伊莎贝拉展开了爱情攻势。只是，他有所不知道是，伊莎贝拉真的是一名法力高强的女巫，杰克以后的日子可不好过了。©豆瓣', '妮可·基德曼', '诺拉·艾芙隆', 6, 19928, 'tt0374536', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2417702110.jpg', 3.2, 18.5, 57.3, 16.7, 4.3, '0.138284,-0.056683,-0.562636,0.644459,-0.085143,-0.321658,0.750299,0.288904,-0.234120,0.109963,0.357419,0.811646,-0.133383,0.119988,0.210280,0.122990,-0.671481,-0.724611,-0.154752,-0.139223,-0.118108,-0.455231,-0.224587,-0.157140,-0.157956,-0.495594,0.550233,-0.177113,-0.316835,0.156134,0.640413,-0.023186,0.159642,0.137593,-0.191943,0.221372,0.143445,-0.289958,-0.264171,0.518663,0.504977,-0.205767,-0.252485,0.168638,0.061017,0.184916,0.508709,-0.138453,-0.015279,0.148411,0.189990,-0.248469,0.103434,0.303397,0.223011,-0.057265,0.457508,0.079486,-0.044135,0.106124,0.122037,-0.147266,-0.749208,0.219358,-0.110734,0.222726,-0.682306,0.422961,-0.099194,-0.095423,0.283740,-0.466460,-0.021549,0.329732,0.343850,0.065614,-0.082979,0.204636,-0.290875,0.389920,0.448563,0.363589,-0.063794,0.536628,-0.120088,-0.448514,-0.425022,0.024091,-0.621293,-0.159065,0.663890,-0.104820,-0.074205,0.230752,-0.418399,-0.230944,-0.265773,-0.171803,-0.196492,-0.299547,0.180671,-0.610963,-0.349473,-0.446732,-0.117800,-0.202542,0.038018,-0.307229,0.740630,-1.054807,0.134623,0.587394,0.306023,-0.395511,0.464336,0.128161,0.014806,-0.080202,0.060223,0.086678,-0.108341,0.262160,0.463784,0.531316,0.287085,-0.246657,-0.282352,0.516829', '20277433', '1299556', '4301278', '1986338');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309068', '冲出宁静号', '动作', '遥远的未来，人类离开不堪负荷的地球，在新的星系延续了文明，那些星系中心的星球组成联盟，不断尝试将偏远的蛮荒星球纳入势力范围。少女瑞娃（Summer Glau 饰）在联盟的这一政策下被改造成为感觉敏锐、身手矫健的战斗机器。瑞娃之兄西蒙将其救出，带到了前抵抗组织成员——马尔 （Nathan Fillion 饰）的运输飞船——“宁静号”上。另一方面，联盟议会为防止瑞娃可能掌握的情报外泄，派出手段毒辣的特使追索不休。马尔一行因瑞娃的战斗模式被联盟唤醒而多次陷入险境，船员们不得不在毫无理性的宇宙掠夺者和联盟的阻击中艰难前往边缘之地——摩兰达，在那里，埋藏着一段联盟不愿示人的罪恶往事……本片为电视剧集《Firefly》的后续和结局，获2006年土星奖最佳女配角等专业褒奖。©豆瓣', '内森·菲利安', '乔斯·韦登', 7.2, 26878, 'tt0379786', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p785405431.jpg', 1.1, 6.5, 39.5, 36.6, 16.3, '0.049722,0.610904,-0.938571,0.904247,0.120640,0.192647,0.496170,-0.052495,-0.422784,0.123061,0.177294,0.666810,0.154226,-0.049376,0.329780,-0.249495,-0.262690,-0.676378,-0.490318,-0.332389,-0.585109,-0.359659,-0.609399,-0.268805,-0.251066,-0.652051,0.949194,0.393632,-0.471841,0.229222,0.051234,0.514068,-0.447472,0.262883,-0.034020,-0.362118,0.306055,-0.186829,-0.604052,0.307594,-0.514070,-0.139231,-0.016221,0.225896,-0.198866,0.309601,0.902000,-0.547735,0.028866,-0.415300,0.339511,-0.493944,-0.137324,-0.318844,0.757611,0.145835,-0.156902,0.234732,-0.134020,0.125739,0.029093,-0.257594,-1.138640,-0.230096,0.273388,0.203685,-0.560371,0.235358,-0.128374,0.004652,-0.162760,-0.281724,0.222811,0.702772,0.435685,0.169650,-0.005407,0.136951,-0.338246,0.124890,0.758446,-0.216498,-0.528565,-0.131608,-0.142624,-0.673253,-0.186038,-0.678709,-0.395409,-0.341123,0.264916,-0.026892,0.133135,0.594277,-0.889257,0.255663,-0.240261,-0.710818,0.144482,-0.357154,0.069532,-0.735286,-0.128564,-0.223029,-0.153851,0.333243,0.030950,0.058056,0.864528,-0.720586,0.303438,0.768916,0.455237,-0.638793,0.698422,0.004448,0.296454,-0.198525,0.041119,0.401137,0.099745,0.503600,0.093827,0.180227,-0.178565,-0.131024,-0.606980,0.344766', '3001114', '26667010', '25928048', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309069', '蝙蝠侠：侠影之谜', '剧情', '布鲁斯 韦恩（克里斯汀•贝尔 Christian Bale 饰）童年亲眼目睹了父母在高谭市街头被歹徒枪杀，韦恩充满怒火。在继承了父亲亿万家产后，韦恩开始环游世界，希望凭自己的力量复仇和打击犯罪！韦恩为了了解罪犯的心理，在亚洲他亲自体现了犯罪的感觉，最后被捕入狱。他在狱中遇到了武艺高强的杜卡，杜卡传授了韦恩高强的武艺和坚韧的意志力。韦恩很快被神秘的影忍者盟看上，忍者大师一直想邀他加入。韦恩不久发现影忍者盟对自己的家乡高谭市另有企图，他毅然回到了故乡。韦恩在自己的庄园发现了一个地下室，从此他多了一个身份—蝙蝠侠。蝙蝠侠开始了对抗笼罩在高谭市的黑暗。©豆瓣', '克里斯蒂安·贝尔', '克里斯托弗·诺兰', 8.5, 372395, 'tt0372784', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1563566300.jpg', 0.1, 0.5, 11.5, 47.8, 40.1, '0.190870,0.148546,-0.821560,0.542615,-0.382484,-0.301980,0.564716,0.124600,-0.469833,-0.359430,0.401716,1.283702,0.102156,0.361756,-0.052895,0.089235,-0.254360,-0.808507,-0.057371,-0.293338,-0.274249,-0.577661,-0.247552,-0.195016,0.126436,-0.458048,0.347937,0.309214,-0.087478,0.333157,0.137116,0.327427,0.096336,0.327728,-0.229247,0.190018,0.289548,-0.200520,-0.061982,0.425095,0.115441,-0.186232,-0.054141,0.328905,-0.088520,0.272429,0.537452,-0.020102,-0.168490,-0.045731,0.352889,-0.106851,-0.065658,0.090778,0.450477,-0.231796,-0.132988,0.255368,-0.092623,-0.262384,-0.080590,0.076567,-0.887464,-0.115893,-0.156499,-0.071551,-0.914110,0.603703,-0.210059,-0.125014,0.166923,-0.228482,-0.113985,0.087921,-0.112843,0.257361,0.000713,0.061735,-0.598753,0.057602,0.708486,-0.185207,-0.211227,0.051021,-0.128734,-0.195432,-0.286137,-0.186821,-0.186434,-0.366227,0.877565,-0.039119,-0.306698,0.266729,-0.505567,-0.031282,-0.267179,0.095855,-0.316262,-0.271829,-0.042426,-0.455943,-0.362342,-0.315725,-0.060736,-0.208202,-0.186951,-0.439438,0.758318,-0.886129,0.369760,0.802189,0.422451,-0.556722,0.522071,-0.136656,-0.133398,0.046081,-0.072699,0.447474,0.281180,0.422241,0.546565,0.301040,-0.198458,-0.087258,-0.470550,0.524238', '30162520', '34890458', '1783461', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309070', '飞行家', '剧情', '本片依据Howard Hughes的生平改编。Howard Hughes（Leonardo DiCaprio 饰）出生于美国德州休士顿，18岁时，他继承父亲德州油井的财富，心怀电影梦想移居好莱坞。1926年他买入125家戏院的控制权，砸下数百万美金拍了实景空战史诗电影《地狱天使》，成为著名的制片人；1939年，他入主环球航空公司，他迅速使公司扭亏为盈，二战期间与美国军方合作，主持了蓝云杉飞机的发明和改进。Howard Hughes在事业上取得巨大成功的同时，他也饱受了忧郁症和精神官能强迫症的折磨；他的感情生活波折重重，Katharine Hepburn（Cate Blanchett 饰）、Ava Gardner（Kate Beckinsale 饰）先后离开他，让他备受打击。影片选取Howard Hughes重要的生活事件，真实地再现了他的传奇。', '莱昂纳多·迪卡普里奥', '马丁·斯科塞斯', 8.1, 129565, 'tt0338751', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2215458280.jpg', 0.2, 1.2, 18.6, 51.5, 28.5, '-0.260863,0.187190,-0.604514,0.602020,0.353755,-0.291268,0.419771,0.134951,-0.172879,0.041533,0.399181,0.875993,-0.175907,0.156880,0.248691,0.111846,-0.240386,-0.781560,-0.045671,-0.015847,-0.098664,-0.223342,-0.485340,-0.198024,-0.105033,-0.318111,0.689273,0.184658,-0.393496,0.356089,0.175552,0.361200,0.192487,0.171071,-0.185863,0.068947,0.033127,0.156862,-0.474141,0.292957,-0.099107,-0.427761,-0.042121,0.057790,0.002169,0.292760,0.597659,-0.110679,-0.043253,-0.286923,0.661650,-0.224014,-0.352956,0.056055,0.217313,0.281396,0.007073,0.322539,-0.265741,-0.026931,-0.048193,-0.118827,-0.728547,-0.368753,0.068889,-0.186927,-0.600867,0.568741,-0.241623,0.264900,-0.101747,-0.078053,0.059067,0.323781,0.210969,0.395973,-0.155077,0.349871,-0.383332,0.725799,0.625323,-0.274561,-0.289468,0.208596,-0.152104,-0.485680,-0.336231,-0.616691,-0.225061,-0.006780,0.479974,-0.273338,-0.016597,0.293008,-0.575246,0.070004,-0.288717,-0.500283,0.127050,-0.150005,0.106929,-0.738507,-0.326324,-0.416541,-0.440343,-0.286015,0.223111,-0.289509,0.817785,-0.409056,0.019322,0.651519,0.362338,-0.509090,0.830331,0.011929,-0.044499,-0.195360,0.082841,0.267677,-0.243287,0.291502,-0.109234,0.151029,-0.007970,-0.016218,-0.243080,0.640080', '22265121',