INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309071', '天国王朝', '剧情', '《天国王朝》大部分角色基于历史人物而改编，哥伦比亚大学的Hamid Dabashi教授为该片的首席学术顾问。十二世纪的法国，青年铁匠贝里昂（奥兰多·布鲁姆 Orlando Bloom 饰）无意间知道自己是十字军将领戈弗雷（连姆·尼森 Liam Neeson 饰）失散多 年的私生子。为了寻找救赎，贝里昂跟随父亲前往耶路撒冷。骁勇善战加上品格高尚，贝里昂几经征战成为赫赫有名的武士，不但深受国王赏识，美丽的公主西贝拉（伊娃·格林 Eva Green 饰）也对他芳心暗许。而他也深深地被当地陌生而奇特的文化吸引，然而随着战役增加，带来无尽的杀戮和掠夺，贝里昂终于领会父亲训言中和平的真义与生命的真爱。耶路撒冷王故去，新王继位。好战的新王挑起战争，萨拉丁率领撒萨拉逊骑士要收复他们的圣地——耶路撒冷。危急之时，贝里昂挺身而出，誓言捍卫“天国王朝”……©豆瓣', '奥兰多·布鲁姆', '雷德利·斯科特', 8.6, 101844, 'tt0320661', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p460797308.jpg', 0.2, 1.1, 12.6, 40.8, 45.3, '-0.218495,0.208106,-0.506790,0.846948,0.345189,-0.257742,0.344954,-0.033462,-0.385453,-0.574200,0.108908,0.718034,-0.069466,-0.119949,0.756354,-0.048512,-0.073121,-0.531143,-0.231510,0.014985,-0.124791,-0.353244,-0.363335,-0.422441,-0.288413,-0.533648,0.781955,0.247590,-0.229349,0.497039,0.316015,0.625290,0.076049,0.153674,-0.008113,-0.109437,0.083836,-0.176089,-0.398815,0.080941,-0.048544,-0.083756,-0.130370,0.224254,0.031073,0.122577,0.316479,-0.644863,0.431386,-0.519631,0.293534,-0.380291,0.007552,-0.155376,0.351395,0.038934,-0.128876,0.354458,0.342422,-0.443704,-0.073400,-0.340277,-0.545256,-0.255855,0.126860,0.011027,-0.447829,0.312602,-0.013550,0.089482,0.125143,-0.146517,0.230801,0.493329,0.376234,0.208573,0.133703,-0.090444,-0.417210,0.289566,0.653510,-0.138377,-0.236187,-0.244699,-0.472810,-0.566283,0.209268,-0.530243,-0.593403,0.051516,0.256964,-0.131585,0.616543,0.627690,-0.516111,-0.198860,-0.567582,-0.215012,0.411500,-0.435818,0.158359,-0.569430,-0.298141,-0.345188,0.020139,0.123792,0.117447,-0.085251,0.917244,-0.794080,0.381957,0.395101,0.405270,-0.601626,0.515984,0.065242,0.155886,-0.410884,-0.295998,0.896838,0.371593,0.001062,-0.184772,-0.193592,-0.263606,-0.205494,-0.271053,0.254060', '26357307', '1482099', '5308201', '27608279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309078', '星球大战前传3：西斯的复仇', '动作', '克隆战争已经进行了三年，共和国即将胜利，分裂联盟的格非特将军和杜库伯爵（克里斯托弗•李 Christopher Lee 饰）劫持议会首相帕尔帕庭（伊恩·迈克蒂安米德Ian McDiarmid 饰）潜逃，绝地武士欧比-旺•肯诺比（伊万•麦克格雷格 Ewan McGregor 饰）和阿纳金（海登·克里斯滕森 Hayden Christensen 饰）奉长老院命前去营救，阿纳金杀死杜库伯爵救出帕尔帕庭，但格非特将军逃匿。阿纳金梦见妻子阿米达拉（娜塔丽·波特曼 Natalie Portman 饰）将死于难产，困惑中求助于帕尔帕庭，后者趁此机会离间阿纳金与绝地长老院。随着阿纳金向帕尔帕庭的靠拢，一场针对绝地武士与其所捍卫之民主的阴谋逐渐展开。本片提名2006年第78界奥斯卡最佳化妆奖，并提名格莱美最佳电影电视等视觉媒体原创音乐奖。©豆瓣', '伊万·麦克格雷格', '乔治·卢卡斯', 8.5, 100346, 'tt0121766', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p533908031.jpg', 0.3, 1.1, 14.1, 44.4, 40, '-0.328233,-0.085287,-0.261656,0.580762,0.283181,-0.259784,0.356823,0.107687,-0.163448,-0.276522,0.265555,0.799707,-0.139626,-0.104091,0.700636,-0.045090,-0.513322,-0.467926,-0.057202,-0.007357,0.152395,-0.519606,-0.349391,-0.253181,-0.131000,-0.594172,0.884130,-0.266077,-0.105381,0.431805,0.551555,0.434423,-0.232343,0.043963,0.641030,0.210507,0.597900,-0.523904,-0.885283,0.429827,0.038150,-0.020765,-0.278665,0.180440,0.163889,0.300066,0.316343,-0.695749,0.410162,-0.367524,0.285221,-0.440267,-0.029535,0.163291,0.530496,-0.179718,0.089341,0.551814,0.311734,-0.035925,-0.128387,-0.125918,-0.462213,0.132416,0.336469,0.163686,-0.274682,-0.021555,-0.401118,0.231378,0.067720,0.131680,0.038884,0.609326,0.301496,-0.089504,0.112574,-0.191854,-0.252138,0.349103,0.049982,0.080825,-0.201435,-0.133013,0.191243,-0.512703,0.237785,-0.206949,-0.362415,-0.014814,0.573373,-0.214560,0.543547,0.620654,-0.384839,-0.300711,-0.480381,-0.157359,0.220952,-0.174413,0.277637,-0.800750,-0.031970,0.258120,0.120988,-0.125707,0.071563,-0.100773,0.221970,-0.369368,0.226500,0.325771,0.379515,-0.007429,0.419144,-0.112138,0.099881,-0.246287,-0.195033,0.313686,0.205615,0.296236,0.241353,0.223761,0.307472,-0.374002,-0.248144,-0.006978', '1298616', '26990609', '1439286', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309079', '茶之味', '剧情', '春野一家人住在宁静祥和的小山村，他们的生活恬淡幸福，不过家族成员却各有各的烦恼。祖父（我修院達也 饰）性格古怪，行为乖张，醉心于私动画的制作；父亲（三浦友和 饰）是一位驻家催眠治疗师，他专心工作，无暇他顾；妻子美子（手塚理美 饰）总算暂时从育子的繁忙生活中解脱出来，于是决定重拾餐桌卡的绘画工作。夫妻俩鲜少交流，隔阂暗生；就读中学的长子阿一（佐藤貴広 饰）恋上新来的转校生，他徘徊犹豫，始终不敢表达；刚上小学的女儿幸子（坂野真弥 饰）总以为自己的头颅在不断变大，这个奇怪的幻想让她倍感困扰。吊儿郎当的叔叔（浅野忠信 饰）从东京回来，为这个平凡却又有些奇怪的家庭吹进一丝生气……©豆瓣', '浅野忠信', '石井克人', 8.2, 6687, 'tt0413893', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p661324770.jpg', 0.7, 2.4, 18.3, 43.5, 35, '0.221409,0.015572,-0.485728,0.413921,-0.243882,-0.325360,0.651205,0.326574,-0.439980,-0.606672,0.203649,0.581981,0.005785,0.443820,0.092786,0.035655,-0.202505,-0.391551,0.142422,0.022435,0.177702,-0.176230,-0.036214,-0.154759,-0.235432,-0.163776,0.581779,0.087101,-0.024535,0.511245,0.083825,0.325761,-0.203774,0.202115,-0.046634,-0.142598,-0.229268,0.221368,-0.026814,-0.394067,-0.147584,-0.064348,-0.252705,0.193427,0.447025,0.447110,0.752772,0.146549,-0.444705,0.093577,0.336232,0.023098,-0.217873,0.177039,0.130429,0.115857,-0.135795,-0.101338,-0.352990,-0.031409,-0.153836,-0.019514,-0.601333,0.052066,0.190652,0.313491,-0.305988,0.503650,0.067948,-0.359557,0.135282,-0.154179,-0.042765,0.179938,0.160847,0.496160,-0.267610,0.428837,-0.070108,0.260238,0.467391,-0.076046,-0.212060,0.284167,-0.598892,-0.166578,0.067942,-0.211555,-0.655676,-0.285458,-0.150373,-0.052724,-0.081492,0.182577,-0.397077,-0.057442,-0.040304,0.061590,0.191370,-0.522349,0.174051,-0.359480,-0.007397,-0.364698,-0.461446,0.002297,0.201825,-0.253528,0.800830,-0.916195,0.125572,0.286780,0.092601,-0.431530,0.373694,0.483951,-0.085744,-0.345110,-0.137103,0.507435,-0.153795,0.177342,-0.059450,0.442474,-0.013762,-0.042852,-0.415342,0.318212', '3445516', '25922902', '4817024', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309080', '谜情公寓', '剧情', '马修（乔什•哈奈特 饰）是个年轻有为的广告公司人员，与女友也到了谈婚论嫁的阶段。当他在一次生意洽谈的会晤中，他无意间听到了往日挚爱——莉萨（黛安•克鲁格 饰）的声音。那时两人正处热恋，可是莉萨无端在他的生活中消失了。而一直以来，马修都无法忘记莉萨。他正怀疑那名女子正是莉萨，他决定要留下来寻找这名女子，因为他在电话亭里发现了女子的住址。马修进入了女子的寓所，她发现了一切属于莉萨的特征，可是出现的却是另一个人，另一个叫莉萨（萝丝•拜恩 饰）的女人。马修依然不停止寻找真正爱人的脚步，但他不知道的是他早已进入了一个圈套内……©豆瓣', '乔什·哈奈特', '保罗·麦圭根', 7.5, 18590, 'tt0324554', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p452586025.jpg', 0.8, 3.9, 33, 44.5, 17.9, '0.367049,0.105557,-0.904631,0.629220,-0.490342,-0.378046,1.149503,-0.041186,-0.619693,-0.485847,0.361918,0.972776,-0.123216,0.368883,0.306982,0.392200,-0.160382,-0.754056,0.011236,-0.360369,-0.313479,-0.348586,-0.336393,-0.224498,-0.257572,-0.144699,0.668723,0.123872,-0.233788,0.194913,0.319843,0.126826,-0.027233,0.781789,-0.244484,0.041665,0.230818,-0.200246,0.000914,0.277815,-0.023573,-0.377513,-0.274490,0.382763,-0.110894,0.569336,0.582430,-0.306772,-0.062194,0.120015,0.248103,-0.075295,-0.131522,0.148509,0.251310,-0.170418,0.174034,0.089917,-0.324138,-0.073119,0.067793,-0.058022,-0.528438,0.192593,-0.107519,0.596736,-0.595246,0.387146,-0.215392,-0.126765,0.067072,-0.479456,0.171752,0.082696,0.135082,0.339454,-0.241429,-0.134923,-0.642049,0.120242,0.633782,0.158171,-0.244662,0.687199,-0.086105,-0.653646,-0.161474,-0.030568,-0.647152,-0.111257,0.166254,0.244995,-0.303648,0.145013,-0.329355,0.049415,-0.261080,-0.118124,-0.289085,-0.464572,-0.287539,-0.511131,-0.282206,-0.485460,-0.485754,0.263000,-0.168773,-0.292649,0.583606,-1.135730,0.149426,0.604509,0.121380,-0.449723,0.786110,0.044976,0.166882,-0.315120,-0.031494,0.363989,0.055061,0.136333,0.044313,0.410418,-0.156311,-0.137685,-0.444981,0.467485', '4275444', '1308755', '1302384', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309083', '阿尔菲', '剧情', '这是一个看似荒诞的爱情悲喜剧。阿尔菲（裘德洛饰）是一个豪华房车司机。英俊不凡的外表，让他在风月场上如鱼得水。身边的女人换了一个又一个，阿尔菲却总在真爱降临的时候临阵逃脱，继续下一轮的风流快活。当有一天，因为某些原因，他急切想要的回头，曾经的爱情还在那里吗？仍然是热闹的节日，阿尔菲是会热闹温馨的拥有爱，还是会一个人孤独的缩在大衣里抵挡城市里迷乱而寒冷的风。他爱这座城市，这座从不缺少爱的城市，会给他留下什么呢？©豆瓣', '裘德·洛', '查尔斯·谢尔', 6.9, 13786, 'tt0375173', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571703741.jpg', 0.9, 7.5, 49, 33.1, 9.6, '0.391666,0.403348,-0.787382,0.613385,-0.227664,-0.202837,1.117084,0.256906,-0.387851,-0.007138,0.438271,0.679700,0.074460,0.304466,0.090422,0.560978,-0.367225,-0.509480,0.018978,-0.116730,-0.186653,-0.214237,-0.669473,-0.167866,-0.031739,-0.205733,0.393976,0.411560,-0.075582,0.241438,0.467006,0.165997,0.088644,0.700806,-0.459029,-0.215313,0.130250,0.150835,0.052351,0.394346,-0.079113,-0.139554,-0.334150,0.355962,-0.279387,0.248197,0.510917,-0.154365,-0.340130,0.068114,0.347936,0.000190,-0.065604,-0.121738,0.026113,-0.574604,0.168203,-0.003322,-0.220093,0.214501,0.168291,0.107223,-0.736989,-0.164712,0.159954,0.363360,-0.577321,0.670658,-0.019304,-0.457785,0.129356,-0.321758,0.094591,0.032609,0.346154,0.665435,0.009802,0.138433,-0.482219,0.228377,0.938781,0.249222,-0.440866,0.450620,-0.614883,-0.302552,-0.017217,-0.282879,-0.925644,-0.124385,0.138117,-0.302537,0.037147,0.164080,-0.678904,0.588458,-0.057611,0.120383,-0.262915,-0.466778,-0.244124,-0.135605,0.067791,-0.581535,-0.329328,0.064384,-0.036710,-0.002110,0.634755,-0.760878,0.413332,0.754024,0.332618,-0.269644,0.770174,0.467953,-0.123784,0.107376,-0.014673,0.204819,-0.187326,0.276235,-0.195727,0.450094,0.163131,-0.014988,-0.610713,0.758724', '1307561', '1296370', '4275444', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309084', '贱女孩', '喜剧', '凯蒂(林赛•洛韩 饰)青春活泼，单纯可人。因为父母的工作关系，她从小在非洲长大，接受家庭式教育。同时，她在那个原始开阔的地方，凯蒂养成了隐忍坚强性格。15岁的这一年，凯蒂随父母搬到伊利诺斯州，开始了她人生第一次的校园生活。可令人不愉快的是，凯蒂的与新同学的相处根本不是她原本想象的样子。女孩儿们的世界，表面平静和睦，却波涛暗涌。为了适应新的环境，凯蒂暗自学习“生存法则”并很快凭着可人的外表加入了学校很光鲜的一个小圈子。她温顺的性格，也似乎为她赢来了一群要好的朋友。然而，一切平静，都在她爱上男孩亚伦(乔纳森•本尼特 饰)的那一刻发生了变化。原来，亚伦是学校最惹眼的女孩Regina (瑞秋•麦克亚当斯 饰)的前任男友，虽然她们已经分手，可是霸道又自负的Regina根本不能容许凯蒂的介入。于是，一场女孩之间的战争悄然开始。关于友情，关于尊严，关于诚恳，关于信任。一切的一切，女孩儿们将如何学会，如何长大。', '琳赛·洛翰', '马克·沃特斯', 7, 141740, 'tt0377092', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p726855595.jpg', 0.6, 5.3, 48.4, 34.5, 11.2, '0.466765,0.222762,-0.658392,0.432673,-0.533793,-0.233836,0.590386,0.085504,-0.578484,-0.302324,-0.011681,0.602665,-0.002785,0.245502,0.145728,0.065852,-0.345419,-0.510068,0.078775,-0.018761,0.060279,-0.469989,-0.115902,-0.192874,-0.032896,-0.422764,0.592839,-0.006273,0.014725,0.444040,0.193808,0.042778,0.060434,0.455942,-0.053590,-0.246042,0.031588,0.188009,-0.255973,-0.151182,0.034047,0.052368,-0.149265,0.271194,0.142643,0.363148,0.610679,-0.256416,-0.394312,0.074301,0.461622,0.051740,-0.172947,0.170148,0.186382,-0.192282,0.096582,0.176385,-0.031823,-0.038057,-0.048460,-0.246450,-0.456958,-0.045654,0.125769,0.133909,-0.439989,0.563762,0.082088,-0.268778,0.078549,-0.364572,-0.128217,0.447251,0.230823,0.428573,-0.252743,0.114239,-0.229572,0.087395,0.951225,0.268613,-0.501270,0.666478,-0.581312,-0.412433,-0.192584,-0.417130,-0.636657,0.117980,0.069877,0.038973,-0.343796,0.463163,-0.489189,0.044604,0.011324,-0.032819,0.055683,-0.766800,-0.029718,-0.383943,-0.382072,-0.780977,-0.465829,-0.340918,-0.161988,-0.334560,0.967160,-0.958737,0.231270,0.386163,0.043933,-0.522399,0.457972,0.299748,0.108335,-0.317355,-0.074546,0.541174,-0.129663,0.084740,-0.029968,0.389186,-0.022040,-0.024572,-0.259923,0.745727', '1309161', '35030151', '6963575', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309085', '灵魂歌王', '剧情', '这是一部传记电影。雷•查尔斯（杰米•福克斯 Jamie Foxx 饰）出生在一个贫穷的黑人家庭，因缺乏必要医疗条件，年少的查尔斯就因青光眼丧失了视力。然而，在母亲言传身教下，小查尔斯没有从此自暴自弃，而是很快熟悉了盲文，并通过盲文接触了他人生的第一个乐谱。查尔斯很快就在音乐上展现出了他过人的天赋。他的很多乐器演奏功力早已超出了很多视力正常的音乐家的高度。母亲过世后，年少的查尔斯辍学开始了他的巡回演唱会。60年代，他带来了他独创的将乡村、爵士、管弦和教会音乐融合为一体的骚灵音乐，引起了音乐界巨大的反响……©豆瓣', '杰米·福克斯', '泰勒·海克福德', 8.4, 19512, 'tt0350258', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2216531651.jpg', 0.1, 0.7, 14, 49.2, 36, '0.505842,0.267427,-0.642457,0.682214,-0.240203,-0.275635,0.778859,0.263800,-0.552660,-0.382179,0.023749,0.900991,-0.101252,0.344999,-0.057812,-0.159212,-0.303389,-0.710513,0.013786,0.035632,-0.307589,-0.377695,-0.127600,-0.210202,-0.355641,-0.642110,0.546300,-0.054056,-0.441713,0.297081,-0.056359,-0.151896,0.327066,0.297795,-0.257233,0.203542,0.078740,-0.071332,-0.009407,0.143130,0.072967,-0.405296,0.123579,0.209910,-0.204951,0.335202,0.691304,-0.171710,-0.081005,-0.180446,0.681928,-0.000937,0.022160,-0.006261,0.320834,0.184744,0.073767,0.152839,-0.214700,0.074390,-0.286605,-0.064470,-0.880205,0.072581,0.059075,0.074843,-0.384021,0.643949,-0.070843,-0.301743,-0.182809,-0.332501,0.082868,0.121836,0.164775,0.398836,-0.150594,-0.014044,-0.312396,0.437072,0.750855,-0.007178,-0.558677,0.693438,-0.588734,-0.712875,-0.379605,-0.329109,-0.412483,0.005920,0.537236,0.090876,-0.203255,0.093308,-0.530816,0.089839,-0.060146,-0.301896,-0.183906,-0.202510,0.112926,-0.661980,-0.181474,-0.426400,-0.321010,-0.197469,0.048899,-0.332825,1.058097,-0.986578,0.261545,0.565833,0.176529,-0.263991,0.495749,-0.151780,-0.014280,0.087282,0.040750,0.424056,-0.121258,0.282196,0.073375,0.408426,0.186074,-0.189310,-0.345220,1.015206', '27602116', '1870681', '2053515', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309086', '女孩梦三十', '喜剧', '13岁的吉娜(珍妮弗·加纳 Jennifer Garner饰)充满对大人世界的憧憬。她渴望散发媚惑的女人味，和梦中情人那样约会，得到男孩们的青睐。但这一切都只是她的白日梦，事实上吉娜在异性男孩中间似乎没什么吸引力，并被朋友捉弄了一番。跟邻家哥哥马特（马克·鲁弗洛 Mark Ruffalo饰）大闹一场之后，吉娜已经完全厌恶了这乏味的童年，她要赶快长大成人！想不到，吉娜梦想成真了。她竟在第二天变成了一个30岁的熟女，有体面的工作和优厚的收入，人生翻开了春风得意的新篇章。虽然吉娜一头雾水，却也开始投入这上帝赐予的幸福生活。然而，步入了大人世界的吉娜真的获得了她梦寐以求的东西么？30岁的她理所当然要面对成人复杂的世界，这让她怅然若失；更不妙的是，她心爱的男孩马特，此时要成为别人的丈夫了。失去了童年和白马王子的吉娜，开始乾坤大逆转，她要找回丢失了的东西…©豆瓣', '詹妮弗·加纳', '盖瑞·温尼克', 7.1, 41809, 'tt0337563', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1544469508.jpg', 0.7, 5.3, 46.2, 36, 11.9, '0.312738,0.215907,-0.720647,0.448128,-0.546493,-0.501221,1.018238,0.093799,-0.486106,-0.007668,0.083946,0.803116,-0.295224,0.419096,0.334868,0.437292,-0.345198,-0.751071,-0.007512,-0.220405,-0.158201,-0.414462,-0.409619,-0.051289,-0.138229,-0.441950,0.546889,-0.060591,0.095117,0.394645,0.392229,0.077801,0.405053,0.737150,-0.364483,0.242936,0.115312,0.273393,-0.034045,0.090507,0.111098,0.038276,-0.045699,0.509712,-0.155620,0.317541,0.432472,-0.249130,-0.210208,-0.068572,0.502236,-0.117691,-0.104174,0.257593,-0.002654,-0.117421,-0.044620,-0.194278,-0.064146,-0.167679,0.132419,-0.105495,-0.839118,-0.014674,0.325600,0.079474,-0.523056,0.464284,0.073733,-0.055973,0.205725,-0.179793,0.081150,0.428392,0.156461,0.548502,-0.232522,-0.005579,-0.604255,0.296325,0.536818,0.018206,-0.308516,0.712226,-0.491142,-0.468929,-0.083154,-0.210830,-0.570715,0.132886,0.400881,0.167595,-0.199995,0.274864,-0.655863,-0.086734,-0.059168,-0.056965,-0.138484,-0.663084,-0.156412,-0.138105,-0.247498,-0.666738,-0.488718,-0.070936,0.221466,-0.403176,0.891944,-0.808713,0.254590,0.599329,0.260803,-0.435657,0.761425,0.140409,-0.042312,-0.386925,-0.057669,0.368897,-0.322178,0.237972,0.090692,0.476538,0.072812,-0.036968,-0.634359,0.926593', '1292062', '3