INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309087', '世界', '剧情', '身为北京世界公园民俗村的一名舞蹈演员，赵小桃（赵涛）对身边微缩的世界早已厌倦，渴望有天同也在民俗村做保安队长的男友成太生（成泰燊）一起坐飞机去看看外面真实的世界。前任男友的到访，令赵小桃想起她同成太生刻骨铭心的初遇以及目前两人过的平庸日子，明白昔日的理想早被粉碎，而刚结识的一见如故的俄罗斯姑娘安娜的突然离去，加深了她对现实生活意义的怀疑，认识到她和成太生对彼此的忠贞，是生活里所剩的唯有美好。然而人心是最能琢磨的，成太生悄无声息地把心给了另一个即将去巴黎的女人，但他显然没有领会民俗村以外的现实世界里流行的情感游戏规则，只能黯然回归自己的卑微身份。©豆瓣', '赵涛', '贾樟柯', 7.5, 25725, 'tt0423176', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p520165154.jpg', 0.7, 3.7, 33.3, 45, 17.3, '0.504634,0.355418,-0.762697,0.494140,-0.194528,-0.101935,0.704278,-0.063508,-0.522195,-0.147791,0.125014,0.774698,0.004639,0.344067,0.327756,0.250155,0.018475,-0.685398,-0.163303,-0.278890,-0.197831,-0.537504,-0.406511,-0.035277,-0.220111,-0.261291,0.506994,0.208888,-0.115978,0.469403,0.307366,0.128168,0.043166,0.560149,-0.263322,0.038820,0.015186,0.144100,-0.512505,-0.079652,0.169037,-0.029130,-0.138783,0.188700,-0.225385,0.307870,0.539318,-0.249250,-0.253598,-0.007476,0.436999,-0.079229,-0.247763,0.118840,0.188479,0.159646,-0.039325,0.074772,-0.088789,0.023316,0.010926,0.029168,-0.807200,0.102955,0.203124,0.016169,-0.545974,0.539943,0.026310,-0.342743,0.210596,-0.227953,0.404046,0.119990,0.403775,0.566361,-0.086812,0.030178,-0.221789,0.203318,0.734070,0.178017,-0.350645,0.494133,-0.434912,-0.313630,-0.210632,-0.259902,-0.427684,-0.117716,0.018989,0.140432,-0.377387,0.111354,-0.417121,0.254942,-0.132554,-0.190660,0.158739,-0.630413,-0.166505,-0.197785,-0.401366,-0.650257,-0.171420,-0.105832,0.166502,-0.394628,0.825250,-0.884937,0.214042,0.398082,0.297206,-0.678258,0.856271,0.297990,0.024544,-0.341898,0.060750,0.464802,-0.190197,0.116189,-0.084289,0.399253,-0.299269,0.002379,-0.497788,0.542553', '26283288', '3230462', '1418613', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309088', '活死人黎明', '动作', '看似平凡的一天，护士安娜（莎拉·波利 Sarah Polley 饰）正准备和丈夫路易斯（Justin Louis 饰）共享快乐的周末，却不知一场恐怖、致命的瘟疫正在大肆蔓延。被瘟疫感染的丧失人性，转而变成嗜血如命、残暴无情的活死人。安娜的丈夫和女儿薇薇安（Hannah Lochner 饰）无一幸免，她侥幸从家中逃生，却发现整个城市都已变成活死人的天下，幸存者所剩无几，眼前的世界宛如人间地狱。是时瘟疫蔓延全球，各国都已陷入瘫痪状态之中。安娜驾车一路逃亡，最终与警察肯尼斯（文·雷姆斯 Ving Rhames 饰）以及其他几名幸存者躲在一家购物中心内。然而这终究不是一个长久的避难场所，活死人闻风而至，时刻都有冲进来的危险。安娜他们必须团结一心，逃出生天……©豆瓣', '萨拉·波莉', '扎克·施奈德', 7.5, 88494, 'tt0363547', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2493796125.jpg', 0.7, 3.5, 32.3, 46.4, 17.1, '0.122434,0.007720,-0.504265,0.030960,0.062263,0.065511,1.001444,-0.025384,-0.411425,-0.113011,0.439292,0.496826,-0.233352,0.218657,0.095693,-0.107828,-0.292602,-0.592196,-0.293000,-0.086961,-0.239113,-0.085990,-0.424188,-0.127627,0.086116,-0.252174,0.532882,0.327277,0.040587,0.398650,0.012427,0.355111,-0.378230,0.638602,-0.023269,-0.073236,0.054478,-0.320349,-0.277477,0.077486,-0.158672,-0.105579,-0.139028,0.222662,-0.156395,0.353794,0.745161,-0.478706,0.128354,-0.322444,0.260909,-0.257577,-0.156488,0.265656,0.288903,-0.241509,0.186842,-0.028258,-0.017232,-0.053430,0.210907,0.116466,-0.582825,0.036997,0.330829,0.258132,-0.287178,0.331480,0.084271,-0.006375,0.107490,-0.234046,0.163170,0.158638,0.177154,0.493460,-0.102753,0.012391,-0.642351,-0.036885,0.802031,-0.180379,-0.674155,0.202930,-0.230765,-0.400867,0.085001,-0.211599,-0.415729,-0.260183,0.293147,0.246842,-0.331313,0.483871,-0.497077,0.278754,-0.438368,-0.244553,-0.312804,-0.076713,-0.403900,-0.747306,0.036648,-0.138729,-0.089622,0.261221,-0.029698,0.028483,0.597087,-0.463373,0.413035,0.335792,0.148005,-0.517574,0.379508,-0.065992,0.275797,0.033796,-0.180658,0.648159,0.142432,0.580917,0.081434,0.038114,-0.497286,0.066935,-0.256081,0.567076', '10466639', '21619567', '25884436', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309091', '的士飚花', '喜剧', '话唠贝尔(奎恩·拉提法 Queen Latifah 饰)是一个典型黑人女人，有一个感情稳定的男友杰西(亨利·西蒙斯 Henry Simmons 饰)。因为厌倦了送外卖的工作加上自己车速一流，贝尔决定改行开的士。不久以后，她就因为时速超过135英里而出名了。沃施本警官(吉米·法伦 Jimmy Fallon 饰)做事不利索加上 运气不好，自从搞砸了一件毒品案，上司玛塔(珍妮弗·艾斯波西多 Jennifer Esposito 饰)对他的态度就怎么友好了。为了挽回自己的形象，他一心想立一场功。纽约城内，美女劫匪(吉赛尔·邦辰 Gisele Bündchen 饰)接连抢劫银行，而警察们却对她的车速望尘莫及。偶然的机会，沃施本看到了贝莉的高超车速，决定请她帮忙逮捕银行劫匪。于是，计程车女司机贝尔就此和女劫匪开始了一场公路大比拼……©豆瓣', '奎恩·拉提法', '蒂姆·斯托瑞', 6.5, 7154, 'tt0316732', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2261463470.jpg', 2.1, 10, 54.9, 26, 6.9, '0.426620,-0.075006,-0.452249,0.486357,-0.373238,-0.417495,0.543644,0.208367,-0.347803,-0.073033,0.280298,0.670015,-0.249271,-0.164064,0.381929,0.166248,-0.390907,-0.464535,0.354534,0.027686,-0.216070,-0.386626,-0.249321,-0.380529,-0.100516,-0.071240,0.077102,-0.118430,-0.051577,0.328823,0.246511,0.037504,0.402754,0.331823,-0.016342,0.167323,0.225775,-0.253949,0.017874,0.213700,0.032440,-0.037341,0.008077,0.130687,0.186330,0.467542,0.404412,0.143353,-0.138082,0.040886,0.062544,-0.265465,0.086034,-0.074447,0.319966,-0.157484,0.320689,0.033351,-0.134150,-0.261149,0.162388,0.071069,-0.376578,0.402741,-0.290317,-0.029700,-0.544834,0.397862,-0.655961,-0.098185,-0.088921,-0.359519,-0.198410,0.127280,0.384122,-0.046373,0.037095,-0.110256,-0.347856,0.118790,0.502157,0.135565,-0.167505,0.551837,-0.006827,-0.264121,-0.004476,-0.050925,-0.389632,-0.140664,0.464455,-0.390335,-0.140322,0.004560,-0.293997,-0.241950,-0.606460,-0.178787,-0.288560,-0.161922,0.011433,-0.274727,0.285796,-0.331790,-0.078041,0.025561,0.165144,0.152721,0.496710,-0.554880,-0.003464,0.591525,0.211116,-0.617243,0.423603,-0.082375,0.079143,-0.208625,-0.062140,-0.071620,-0.124997,0.230503,0.235452,0.456495,0.104296,-0.368282,0.082396,0.462612', '1309069', '30162520', '1292217', '26022182');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309099', '法兰基，我的爱', '剧情', '法兰基（杰克•麦克艾尔 饰）随母亲莉兹（艾米莉•莫迪默 饰）与外婆搬到了苏格兰。九岁的他是个失聪儿童，聪明懂事，对父亲充满期待。他经常给船员父亲写信，还挂着父亲所在的船的航海图。可是他不知道，一切都是母亲的善意的谎言，虚构了父亲的一切，事实上他们到处搬家就是想要摆脱父亲残酷的家庭暴力。而每一封“父亲的回信”都是莉兹所写的，为了就是不让儿子难过。法兰基得知父亲的船即将靠岸了，想见父亲一面。莉兹没想到真的有这样的一艘船存在又不忍心告诉儿子所有真相，只好在朋友的帮助下找了一名陌生男子（杰拉德•巴特勒 饰）假扮父亲，可爱的法兰基很讨他的喜欢。他们三人相处愉快，正当“丈夫”要离开，莉兹告诉了他法兰基的失聪是因为真正丈夫的施暴。而他们之间也似乎有着若有似无的感情。莉兹拒绝了即将逝世的丈夫戴维要见儿子的要求，不久她便告诉法兰基，父亲已经逝世了。莉兹又取得了儿子的信，原来聪明的法兰基已洞悉一切……', '艾米莉·莫迪默', '肖娜·奥尔巴赫', 8.4, 7860, 'tt0377752', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1129637109.jpg', 0.2, 0.6, 12.5, 50.2, 36.5, '0.089321,-0.266297,-0.713127,0.576950,-0.297261,-0.453609,0.523703,-0.082091,-0.485181,-0.317436,-0.003459,0.797506,0.122301,0.390140,0.195153,0.345306,-0.289000,-0.481627,-0.005571,-0.192370,-0.141252,-0.730285,-0.113680,-0.209270,-0.117838,-0.379117,0.310892,-0.043435,0.044676,0.237329,0.339130,0.262954,0.018623,0.363274,-0.126896,0.165947,-0.223650,0.041246,-0.344778,-0.062066,0.233293,0.059656,-0.071481,0.436647,-0.052912,0.540116,0.320818,-0.212852,-0.110524,0.147539,0.349573,-0.349412,0.203075,0.153440,0.130015,-0.095530,-0.000407,0.147181,-0.347605,-0.315565,0.026020,-0.074543,-0.701465,-0.001756,0.041865,0.089177,-0.533279,0.348160,-0.269142,-0.066083,0.165067,-0.306018,0.326893,0.491080,0.045323,0.491798,-0.209504,0.081308,-0.382086,-0.043534,0.719959,0.021652,-0.022903,0.396814,-0.325930,-0.140736,0.237303,-0.283786,-0.641769,0.354826,0.134240,-0.030818,-0.174432,0.204691,-0.180310,-0.370794,-0.511878,0.047320,0.148999,-0.575828,0.064099,-0.082841,-0.089262,-0.412552,-0.331871,-0.018935,-0.039856,-0.249961,0.619697,-0.846789,0.404349,0.553763,0.312536,-0.668687,0.524300,0.334698,0.018163,-0.477657,0.142512,0.376061,0.152730,-0.060407,0.148444,0.023699,0.392699,-0.257225,-0.419734,0.448150', '1877596', '1308805', '27056396', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309101', '查理和巧克力工厂', '喜剧', '威利•王卡（强尼•戴普 饰）是一位伟大的巧克力发明人和制造商，经营着全世界最大的巧克力工厂——王卡巧克力工厂。那是座神秘的工厂，大门紧锁，15年来，从来没有看见有工人从大门进去或出来过，可是却能闻到浓郁的巧克力香味。工厂出产的旺卡牌巧克力销往世界各地，深受孩子们的喜爱。有一天，威利•旺卡先生贴出告示：他在出产的巧克力里面埋藏了五张金券，谁吃到了，就有机会参观工厂，还能得到足够吃一辈子的巧克力糖和其他糖果。小孩子们疯狂抢购，最终五个小客人成为幸运儿。其中有一个小客人叫查理（弗莱迪•海默 饰），家庭非常贫寒，在经历两次失败后，他发现了最后一张金券，巧克力工厂的大门因此为他打开。五个孩子开始在这个魔幻工厂中冒险，吸引他们的除了神奇壮观的巧克力制造世界之外，还有威利•王卡的“神秘礼物”……©豆瓣', '约翰尼·德普', '蒂姆·波顿', 8.3, 463620, 'tt0367594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453925617.jpg', 0.2, 1.4, 17.7, 46.5, 34.2, '0.095144,0.169147,-0.604511,0.347790,-0.245176,-0.053411,1.010035,0.165674,-0.449333,-0.059708,0.082255,0.807399,-0.104909,0.277157,-0.044584,0.114259,-0.057105,-0.219832,-0.153310,-0.484217,-0.491881,-0.031883,-0.342192,-0.352990,-0.192133,-0.266215,0.256252,0.074682,0.022756,0.015466,0.274344,-0.068341,-0.113522,0.192242,-0.419463,0.099773,0.234431,-0.037398,-0.378721,0.141143,-0.252299,0.096098,-0.212348,0.010239,0.405371,0.146464,0.396034,-0.153084,-0.254529,0.004184,0.179171,0.185179,-0.225590,-0.085721,0.034798,0.240912,0.113203,-0.092537,-0.364978,0.212556,0.222955,-0.044539,-0.665419,-0.239641,-0.121952,0.113720,-0.519995,0.404684,0.013778,-0.189480,0.157713,-0.530068,0.257624,-0.047793,-0.033135,0.339253,0.108798,0.165097,-0.957284,0.250167,0.497726,-0.294848,-0.141561,0.219603,-0.310602,-0.423094,0.222394,-0.317009,-0.482825,0.306849,0.443405,0.217851,-0.006734,-0.084356,-1.028674,0.161475,0.038678,-0.559311,0.508669,-0.024022,-0.453598,-0.810714,0.009948,-0.083256,-0.201855,0.278275,0.095111,-0.288641,0.959167,-0.581000,0.190601,0.420901,0.345772,-0.266787,0.835188,-0.212619,-0.206842,0.139490,-0.226763,0.013749,0.251601,0.188001,0.252842,0.571374,0.022331,-0.325629,-0.275568,0.349326', '4944008', '1394176', '21350559', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309103', '神奇四侠', '动作', '理查德博士（尤安•格瑞福德 Ioan Gruffudd 饰）的科学梦想即将实现！他将飞往宇宙风暴的中心，揭开人类基因的密码。同行的还有，项目赞助人冯•杜姆（朱利安•麦克马洪 Julian McMahon 饰）、宇航员本•格林姆（麦克•切克里斯 Michael Chiklis  饰）、博士的前女友苏•斯通（杰西卡•阿尔芭 Jessica Alba 饰）以及她弟弟约翰尼•斯通（克里斯•埃文斯 Chris Evans 饰）。不料，飞船接近风暴中心时，由于计算错误，导致飞船被宇宙射线所吞没！大难逃生返回地球后，组员们的基因因宇宙射线的影响，发生了变异，他们具有了各个不同的超能力。理查德、苏、约翰尼和本组成了“神奇四侠”，利用宇宙射线所赋予的超能力去打击黑暗势力、帮助世界。杜姆获得超能力后变身成为了“毁灭钢眼博士”，正在实施他的邪恶计划。神奇四侠出击了！©豆瓣', '艾恩·格拉法德', '蒂姆·斯托瑞', 6.7, 150727, 'tt0120667', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2180195792.jpg', 0.9, 7.5, 54.9, 29, 7.7, '0.151891,0.102754,-0.663331,0.536031,-0.005556,-0.106290,0.572920,0.173718,-0.044519,-0.417892,-0.037639,0.409768,-0.110197,-0.000385,0.360960,0.084545,-0.408994,-0.378374,-0.115826,-0.113695,-0.571336,-0.795452,-0.452669,-0.398718,0.329064,-0.623895,0.654962,0.059533,-0.328971,0.078107,0.078484,0.513062,-0.120029,0.473755,0.212768,0.134108,0.200995,-0.268294,-0.382297,0.264010,-0.011013,0.106259,0.219934,-0.050820,-0.107583,0.097023,0.586041,-0.612977,0.356594,-0.497048,0.304552,-0.325134,0.272572,-0.080804,0.247015,-0.013322,-0.250371,-0.192506,0.099813,0.197257,0.268130,-0.147485,-0.568351,-0.125126,-0.037384,-0.048818,-0.223927,-0.043855,-0.136918,0.112712,0.027791,-0.118031,-0.036216,0.332402,0.468218,0.083870,-0.132943,0.262833,-0.350260,-0.078247,0.352803,-0.256302,-0.498867,0.137374,-0.320555,-0.448968,-0.503770,0.049610,-0.200839,-0.040033,0.709731,0.266228,0.234906,0.555806,-0.813828,-0.315833,-0.451861,-0.154538,-0.064701,-0.111497,-0.007750,-0.993882,-0.035531,0.057436,0.007095,-0.143661,-0.048145,-0.360347,0.606612,-0.551146,0.345748,0.554439,0.186760,-0.503101,0.350265,-0.188326,0.271477,-0.380096,-0.033002,0.538238,0.178641,0.545690,0.021372,0.242602,0.345058,-0.021228,0.036325,0.494338', '1306809', '4014396', '1309064', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309109', '杜玛', '剧情', '广袤野性的南非草原。入夜，一只迷路的印度豹幼崽跌跌撞撞地闯进高速公路。幸运的是，彼得（坎贝尔·斯科特 Campbell Scott饰）父子救下了它。当两父子把这个小家伙带回家时，儿子赞恩（亚历克斯·迈克尔罗特 Alex Michaeletos饰）仍旧紧紧地搂着小豹仔，他终于有了一个可以一起长大的朋友了。他给小豹仔取名杜玛。可随着杜玛一天天的长大，赞恩必须要让他的这个动物朋友回归到自然中。于是他带着杜玛只身横穿整个南非。蛮荒的南非大地上危机重重，潜伏的非洲狮，暗藏在河流中的鳄鱼，还有那个试图抓杜玛卖钱的神秘流浪汉。赞恩和杜玛的大冒险就这样开始了。赞恩经历千辛万苦，终于把杜玛送回野外。可到达这次旅程终点的时候，也该是赞恩和杜玛道别的一刻。本片是由华纳公司推出的一部以动物与人为题材的电影，执导过《黑神驹》和《伴你高飞》的电影导演拉罗尔·巴尔兰德再次执导该片。', 'Alex Michaeletos', '卡罗尔·巴拉德', 8.3, 8463, 'tt0361715', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2055341783.jpg', 0.2, 1, 16.2, 49.1, 33.5, '0.261035,-0.027682,-0.731551,0.678235,0.075012,-0.431999,0.712763,-0.134540,-0.428011,0.114301,0.130632,0.873819,-0.236696,0.279837,0.247594,0.382815,-0.494523,-0.509829,-0.160263,0.015468,-0.210381,-0.257970,-0.536260,0.017944,-0.072325,0.023127,0.617999,-0.085262,0.004732,0.577207,0.272331,0.077146,-0.076781,0.348190,-0.368804,0.230271,-0.025454,-0.066124,-0.189587,0.385079,0.146701,-0.120938,-0.177058,-0.076687,0.030479,0.266812,0.681536,-0.348638,0.084110,-0.048566,0.117675,-0.432382,-0.072447,0.039399,0.133245,-0.114285,0.308298,0.091207,-0.204232,0.259323,-0.010124,-0.337752,-0.505130,0.045796,-0.125213,0.213957,-0.702303,0.157721,0.046808,-0.058223,0.250133,-0.450955,0.177684,0.191335,-0.035726,0.445227,-0.143703,0.108166,-0.477061,0.020145,0.594445,-0.231331,-0.120576,0.111656,0.105312,-0.614620,0.137069,-0.116491,-0.484453,0.001216,0.545194,-0.046782,-0.471535,0.227196,-0.890013,0.097693,-0.262329,-0.334106,-0.191083,-0.233515,0.026986,-0.459807,0.037019,-0.567600,-0.006560,0.123539,0.033218,-0.175941,0.527745,-0.513240,0.324202,0.535600,0.333742,-0.076500,0.596615,-0.006436,0.335763,0.025066,0.050987,0.158130,-0.018544,0.357724,0.399224,0.500916,0.217066,-0.247590,-0.451998,0.538070', '34461680', '3055049', '3431336', '1316560');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309110', '地铁惊魂', '悬疑', '英国伦敦，某地正在举行热闹的派对。单身女子凯特（Franka Potente 饰）得知好莱坞明星乔治•克鲁尼到访伦敦，于是决定提前离开去找心仪的明星签名。由于酒精的作用，凯特在等地铁时沉沉睡去。当她再次醒来时，四下空无一人，不久最后一班地铁到达。地铁的气氛诡异非常，正当凯特不知所措之际，她的同事盖伊（Jeremy Sheffield 饰）出现在车厢中。心术不正的盖伊扑向凯特，突然地铁门打开，盖伊被不明生物拖出车厢，随即惨叫声响起。凯特仓皇失措逃出车厢，找到流浪汉吉米（Paul Rattray 饰）寻求帮助。两人一起前去查看情况，可就在刚离开不久时，吉米的女友曼迪（Kelly Scott 饰）也遭到袭击。噩梦一样的神秘人，在这一晚掌握着所有人的命运……©豆瓣', 'Franka Potente', '克里斯托弗·史密斯', 5.8, 5734, 'tt0381966', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2399512287.jpg', 5.8, 21.2, 53.6, 15.1, 4.3, '0.437837,0.185878,-0.871088,0.030525,0.299335,-0.340441,0.838602,0.421832,-0.419752,-0.377557,0.320551,0.501745,-0.597782,0.282786,0.600122,0.031222,-0.601694,-0.558446,0.111771,-0.229313,-0.454793,-0.135613,-0.105909,-0.351719,0.177586,-0.368889,0.391837,0.058779,0.011592,0.615847,0.264233,0.171266,-0.327694,0.762262,-0.206952,-0.042739,0.166357,-0.048883,-0.278580,0.330601,-0.041172,-0.343704,-0.222068,-0.307952,0.038072,0.081206,0.545509,-0.150718,0.083816,0.226778,0.269193,-0.030212,-0.090175,0.205114,0.383142,0.045926,0.019603,-0.087084,-0.186123,0.239684,0.023861,0.159946,-0.020138,0.364296,-0.237464,0.279143,-0.467142,0.033703,-0.159750,0.062439,0.367327,-0.467752,0.223952,0.272234,-0.089369,0.478818,0.060604,0.209678,-0.513198,-0.345007,0.454634,0.104597,0.172417,0.280008,0.127623,-0.430806,0.151687,0.295411,-0.261907,-0.166129,0.644435,-0.009446,-0.166004,-0.181668,-0.438990,-0.181357,-0.177805,-0.404007,-0.053425,-0.146948,-0.372886,-1.178979,0.110627,0.167569,-0.020607,0.220950,-0.186420,0.032858,0.311490,-0.664980,0.201297,0.637829,0.242383,-0.006618,0.657877,-0.356653,0.169493,-0.022135,-0.020265,0.283100,0.139989,0.660199,-0.011408,0.172283,-0.250963,0.146496,-0.543423,0.111806', '10466639', '2075345', '3735015', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309112', '美国战队：世界警察', '喜剧', '这是好莱坞继《南方公园》后又一部开涮力作。原来，美国有一个奋力维护世界和平的组织在保护我们的世界，那就是――环球特警组！这次，环球特警组又将重拳出击。特警组总部收到了可靠消息，世界某个角落里的一名患有“权力饥渴症”的类似于希特勒的独裁者正在向世界各地的恐怖组织兜售大规模杀伤性武器，企图以此制造混乱从中谋利。 特警组的队员很多已为人所熟悉，所以特警组决定招募新人去完成这次的间谍任务。这个名额自然落到了极具表演天赋的百老汇演员加里（催•帕克 Trey Parker 饰）身上。加里首次出战就成功潜入了一个军火交易商的基地。他发现恐怖分子已经开始大量购得大规模杀伤性武器，而黑幕后的独裁者竟然是……©豆瓣', '崔·帕克', '崔·帕克', 7.7, 10690, 'tt0372588', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453476294.jpg', 1.5, 4.9, 26.3, 41.8, 25.5, '0.004176,0.156120,-0.501036,0.559681,-0.070814,0.010631,0.331429,-0.107173,-0.444593,-0.099189,0.151238,0.801684,0.151697,-0.053859,0.326700,-0.010236,-0.258798,-0.590248,-0.263607,-0.389551,-0.425361,-0.344030,-0.611619,-0.405484,0.055576,-0.409936,0.795349,0.253587,-0.479316,0.112930,0.393775,0.408016,-0.190824,0.524946,-0.036932,-0.376219,0.524134,-0.179460,-0.387138,0.355945,-0.136993,-0.273733,-0.121348,0.187563,-0.024362,0.231041,0.655687,-0.203600,-0.065307,-0.471357,0.546046,-0.214657,-0.066788,-0.159013,0.480068,0.243170,0.120711,0.136595,0.012573,0.143078,-0.022348,-0.234493,-0.883192,-0.139083,0.147869,-0.029879,-0.354805,0.150827,-0.164878,0.055669,-0.100057,-0.048606,0.338386,0.483627,0.412309,0.154112,-0.194257,0.161507,-0.364575,0.250262,0.321495,-0.079658,-0.236876,0.081282,0.154154,-0.539578,0.046924,-0.160749,-0.182005,-0.204188,0.365441,-0.274934,0.017584,-0.032564,-0.819136,0.137669,-0.289307,-0.381906,0.151193,-0.200565,0.028350,-1.034130,0.065718,0.114801,0.007019,0.214069,0.307051,0.000688,0.764079,-0.778614,0.062629,0.893055,0.314981,-0.638682,0.282058,-0.126396,0.242247,-0.234870,-0.131257,0.014409,0.098115,0.501095,-0.069070,0.266438,0.124121,-0.524478,-0.103461,0.310864', '2369613', '20274039', '4014397', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309115', '帝国的毁灭', '剧情', '这是一部纪实性电影，逼真地反映了希特勒人生的最后12天，第三帝国最后的日子。苏联红军已经攻入柏林，希特勒（布鲁诺·甘茨 Bruno Ganz 饰）和情妇爱娃（茱莉安·柯勒 Juliane Köhler 饰）也躲到了掩体下。爱娃知道自己是来陪希特勒一起共赴黄泉的，但她并 不后悔。即使在她向希特勒为妹夫求情遭拒绝后，她也和希特勒一起举办了最后一次的婚礼。希特勒的忠实追随者戈倍尔（乌尔里希·马特斯 Ulrich Matthes 饰）决心全家一起陪着元首殉葬。他共有7个孩子，他和妻子坚决不让自己的孩子们在没有帝国的天空生长，在希特勒和爱娃自杀后也一同自杀。令人不胜感慨。历史的真实通过镜头一幕幕重现。©豆瓣', '布鲁诺·冈茨', '奥利弗·希施比格尔', 8.9, 92852, 'tt0363163', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2191978526.jpg', 0.1, 0.4, 7.5, 40, 52, '-0.106478,-0.037121,-1.000557,0.852350,0.113133,-0.316640,0.702835,0.147929,-0.367481,0.125981,0.238946,0.822139,-0.139303,0.235089,0.156748,0.098151,-0.597197,-0.789564,-0.083170,0.051238,-0.300433,-0.518224,-0.043825,-0.351044,-0.161972,-0.045047,0.612423,-0.047801,0.166265,0.387010,0.484232,0.086445,0.252034,0.553230,-0.116686,0.101608,0.113765,-0.060148,-0.312678,0.105985,0.353121,-0.188618,-0.307265,0.342864,0.082109,0.194456,0.412209,-0.433012,0.179862,0.030672,0.184163,-0.441770,0.008343,0.305469,0.110814,-0.180499,0.182368,0.357506,-0.002679,-0.073566,0.017022,0.158742,-0.586575,0.006027,-0.037520,-0.027918,-0.662636,0.556099,-0.227913,0.106296,0.194796,-0.375821,0.299074,0.611520,0.218844,0.332848,-0.264261,-0.097803,-0.432162,0.349844,0.768447,0.092889,-0.084995,0.226357,-0.185754,-0.247424,-0.178600,-0.200696,-0.597701,0.087643,0.161301,-0.200761,-0.189398,0.327969,-0.545660,-0.302306,-0.414567,-0.284923,0.035888,-0.450771,0.004076,-0.471066,-0.131996,-0.340852,-0.422049,0.066641,0.000047,-0.274118,0.636509,-0.542605,0.334581,0.585428,0.328929,-0.450951,0.962474,0.356866,-0.072620,-0.056498,0.233327,0.290740,-0.124950,0.272088,0.266631,0.305130,0.288843,0.059695,-0.393658,0.264069', '1456503', '3055049', '30162520', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309116', '怒火救援', '剧情', '克雷塞（丹泽尔•华盛顿 Denzel Washington 饰）曾经是一名杀人不眨眼的特种兵，但是退役后的他却常常被自己杀人的梦魇惊醒，无法忍受痛苦的他只好求助于酒精来麻痹自己的神经。好友见长此以往不是办法，遂推荐他到墨西哥去担任一名私人保镖。墨西哥城是世界高犯罪率城市，绑架事件频发，不管有没有钱都可能遭到绑架。克雷塞保护的是一名百万富翁的女儿皮塔（达科塔•范宁 Dakota Fanning 饰）。10岁的平塔活泼可爱，她快乐的心很快就感染了克雷塞，她成了克雷塞生活中的天使。但是，好景不长，皮塔遭到了绑票并被撕票了！克雷塞大受打击，怒火中烧的他决定只身去找绑匪为皮塔报仇。©豆瓣', '丹泽尔·华盛顿', '托尼·斯科特', 8.1, 75569, 'tt0328107', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1673558925.jpg', 0.4, 1.8, 19.6, 49.2, 29.1, '0.097304,-0.070904,-0.622009,0.357449,-0.448613,-0.095295,0.846109,-0.007523,-0.464185,-0.212011,0.183688,0.813790,0.150308,0.300305,0.286485,0.126988,-0.026856,-0.714314,0.071575,-0.246877,-0.361099,-0.242872,-0.263332,-0.266513,0.060205,-0.357422,0.443632,-0.011339,-0.209982,0.336641,0.427373,0.485029,0.359426,0.618475,-0.223594,0.092250,0.112234,-0.226026,0.115909,0.184129,0.005851,-0.345134,-0.114544,0.282851,-0.050678,0.504162,0.441661,0.030775,-0.209604,-0.151787,0.333087,-0.488155,-0.063049,0.032188,0.351989,-0.092139,-0.019998,-0.027278,-0.201581,0.040038,0.178745,0.067158,-0.763520,0.155784,0.103537,0.025268,-0.563661,0.186277,-0.077391,0.011053,-0.025245,-0.169435,0.133369,0.084292,0.122506,0.347730,-0.221764,0.059053,-0.515644,0.311500,1.010846,-0.126135,-0.223801,0.143425,-0.300319,-0.340055,0.099758,-0.463950,-0.436545,-0.000329,0.330770,-0.079687,-0.457038,0.045150,-0.297024,-0.204313,-0.428167,-0.247707,-0.245513,-0.302907,0.057720,-0.217903,-0.192099,-0.253379,-0.064913,0.144410,0.035413,-0.288149,0.547416,-0.581233,0.255453,0.828581,0.291227,-0.784433,0.465942,0.251498,-0.054477,0.069366,0.108935,0.310792,0.282603,0.421011,0.063203,0.089034,0.105081,-0.112028,-0.140960,0.350917', '26718282', '1292064', '1294941', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309118', '满洲候选人', '剧情', '荣获了诸多荣誉和奖章的本·马高（丹泽尔·华盛顿 Denzel Washington 饰）当年曾是一名海军陆战队上尉，第一次海湾战争期间，他所在的小分队夜晚执行搜查任务时遭到伏击，凭借战友雷蒙德·萧中士（利夫·史列巴 Liev Schreiber 饰）的机智与果敢，整个小 队最终化 险为夷，失去知觉的本也多亏雷蒙德才死里逃生。十年后，本在无数个场合讲过这段过去，并大力盛赞雷蒙德的果敢。由于战争期间的出色表现，雷蒙德的仕途一片光明，在参议院的母亲伊丽娜（梅丽尔·斯特里普 Meryl Streep 饰）的协助下，他如今已然成为副总统的候选人。然而就在此时，本却倍感焦虑，在他的心中不断质疑着当年发生的一切，似乎那晚的袭击事件有着另一个不为人知的版本……本片根据1962年约翰·弗兰克海默的同名经典影片改编。©豆瓣', '杰弗里·怀特', '乔纳森·戴米', 6.8, 5136, 'tt0368008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p854283154.jpg', 1.1, 6.1, 52.9, 33.4, 6.5, '0.019369,0.060551,-0.809575,0.795561,0.102155,-0.335124,0.521926,-0.080474,-0.525970,-0.651463,0.326983,0.810909,-0.254001,0.201883,0.594454,-0.222288,-0.255201,-0.670286,-0.335740,-0.197311,-0.227961,-0.606139,-0.495307,-0.218769,-0.062534,-0.380420,0.735988,0.087534,-0.273034,0.490549,0.298703,0.457055,0.041917,0.360997,0.026849,-0.035643,0.225818,0.006260,-0.187110,-0.083969,0.145089,-0.374698,-0.337820,0.095731,0.171380,0.454741,0.430685,-0.575808,-0.175130,-0.068071,0.401358,-0.135838,0.248232,-0.074412,0.348660,0.041707,0.154118,0.330333,-0.142634,0.100885,-0.005693,-0.176757,-0.709140,-0.077528,-0.035087,0.004678,-0.473017,0.466981,-0.118300,0.224633,0.077372,-0.193228,-0.020520,0.454978,0.141993,0.295536,-0.218637,0.088297,-0.316747,0.097904,0.649507,0.150205,-0.339115,0.021989,-0.103447,-0.394109,-0.130842,-0.148595,-0.285687,0.188950,0.323272,-0.029967,0.066887,0.398408,-0.502046,-0.098669,-0.372759,-0.147112,-0.105837,-0.104933,-0.056006,-0.767356,-0.148439,-0.309685,-0.262892,0.045739,0.031239,-0.170977,0.616025,-0.809259,0.382683,0.268088,-0.239257,-0.449303,0.348704,0.462899,0.281829,-0.090204,-0.143637,0.433187,0.173143,0.150981,0.197000,0.290844,-0.122243,-0.273905,-0.317850,0.401952', '3284768', '1301022', '1295120', '34968329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309120', '小姐好白', '喜剧', '黑人警探马库斯（马龙•韦恩斯 Marlon Wayans 饰）和凯文（肖恩•韦恩斯 Shawn Wayans 饰）在一次扫毒行动中假扮小店老板，准备抓拿前来的毒贩，但是由于没人支援，这一行动搞砸了。为了挽回在上司和同事面前的面子，这两个黑人警探决定挑战一项艰巨的任务：那就是伪装成富有的白人姐妹——威尔顿姐妹，亲身引诱企图绑架这两姐妹的穷凶极恶的绑匪现身。在涂上了厚厚的白粉，浓妆艳抹后，这两个黑人小伙摇身变成了性感漂亮的白人姐妹。于是，一连串爆笑惊险的场面上演了。©豆瓣', '肖恩·韦恩斯', '基伦·埃弗瑞·韦恩斯', 7.2, 55406, 'tt0381707', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p915897391.jpg', 1.3, 6.1, 39.2, 37.9, 15.6, '0.336117,-0.261043,-0.481735,0.495834,-0.386277,-0.391881,0.908134,0.111984,-0.227777,-0.122394,0.519760,0.522508,-0.316518,-0.013188,0.550702,-0.149140,-0.495119,-0.603909,-0.262248,0.082206,-0.385061,-0.347648,-0.315220,-0.345903,0.029761,-0.239494,0.262432,-0.135833,-0.168834,0.632147,0.685275,-0.032973,-0.181331,0.119491,-0.081057,0.299891,0.416982,-0.222127,-0.185407,0.100957,-0.053850,-0.190610,-0.032889,0.311414,0.179896,0.706233,0.636375,-0.271408,-0.004654,-0.180333,0.113525,-0.362460,0.059257,0.213130,0.229916,-0.233662,0.340054,-0.079914,-0.022599,-0.293280,0.222797,-0.103107,-0.756550,0.288651,0.069292,0.052843,-0.578216,0.441427,-0.230245,0.117759,0.061482,-0.151949,0.006279,0.308039,0.242914,0.165834,0.326098,0.118628,-0.449284,0.255256,0.599493,0.227193,-0.050246,0.087770,-0.245299,-0.327875,-0.055347,-0.327384,-0.175392,-0.028785,0.606919,-0.277983,-0.175959,-0.065961,-0.572865,-0.185859,-0.328011,0.082430,-0.179818,-0.231366,-0.363575,-0.662668,0.036245,-0.248139,-0.329317,0.287390,-0.055651,-0.010123,0.650476,-0.596630,-0.065038,0.550789,0.251694,-0.354043,0.357724,0.356121,0.282009,-0.152627,-0.401818,-0.390717,0.397148,0.314396,0.358095,0.563708,-0.256527,-0.147431,-0.268352,0.121523', '1301686', '1578663', '1316693', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309121', '威尼斯商人', '剧情', '年轻人巴萨尼奥（约瑟夫·费因斯 Joseph Fiennes饰）一心要向富商千金鲍西娅小姐（琳恩·柯林斯 Lynn Collins饰）求婚，为了这个愿望，他必须付出三千达克特，无奈中他只好向热心肠的商人安东尼奥（杰里米·艾恩斯 Jeremy Irons饰）借钱。碰巧的是，安东尼奥因为生意周转的问题，只能问犹太人夏洛克（阿尔·帕西诺 Al Pacino饰）借来这笔钱。安东尼奥对犹太人历来抱有强烈的厌恶感，而夏洛克则提出了让人吃惊的要求：安东尼奥必须如期如数的归还这笔钱，否则，他将会切下安东尼奥身上的一磅肉。巴萨尼奥终于如愿以偿的娶回了鲍西娅，安东尼奥却因为生意失败，在夏洛克的讨债中陷入困境。夏洛克还要趁这个机会，一雪安东尼奥对犹太人侮辱之耻。安东尼奥那一磅肉，看来非割不可了，聪明的鲍西娅却用绝妙一招，化险为夷。©豆瓣', '阿尔·帕西诺', '迈克尔·莱德福', 7.7, 14508, 'tt0379889', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p851338375.jpg', 0.4, 2.4, 29, 49.3, 18.8, '-0.120330,0.215243,-0.377556,0.349874,-0.275242,-0.658715,0.575742,0.009947,-0.255423,-0.033718,0.163029,0.773181,0.180890,-0.124597,0.446706,0.297966,-0.386710,-0.458041,0.253485,-0.171265,0.000763,-0.684133,-0.252309,-0.350445,-0.179314,0.027952,0.150447,-0.019290,0.023706,0.311109,0.470652,0.290241,0.581762,0.363478,0.007193,-0.016901,0.055595,-0.199173,-0.328993,0.390725,0.241963,-0.104405,-0.270875,0.298740,0.219252,0.536618,0.146666,-0.233589,0.175158,-0.082095,0.263395,-0.072311,0.159629,0.364336,-0.222936,-0.124371,0.170524,-0.044106,-0.263952,-0.075041,0.326417,-0.073687,-0.734169,-0.102263,-0.006424,0.034681,-0.638608,0.177328,-0.352625,0.082234,0.012388,-0.409859,-0.197343,0.264710,0.288099,0.166932,-0.213652,0.008394,-0.383196,-0.033207,0.179473,0.077138,0.066840,0.148541,-0.327329,-0.395685,0.247540,-0.120281,-0.373446,-0.022969,0.542565,-0.033627,0.188480,0.219819,-0.398487,-0.290444,-0.348267,-0.251785,-0.069625,-0.202000,-0.003740,-0.285181,0.015873,-0.153420,-0.282920,0.010033,0.266314,-0.146999,0.423097,-0.241542,0.006837,0.807590,0.566812,-0.149331,0.305817,0.069558,0.074337,-0.230536,-0.298794,0.117463,0.024804,0.110043,0.231617,0.162457,0.485688,-0.295210,0.063760,0.610698', '1292646', '5973984', '1469353', '26995719');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309124', '王子与我', '喜剧', '又一部讲述灰姑娘故事的爱情轻喜剧电影。这回的女主角叫佩吉（朱莉娅·斯黛尔斯 Julia Stiles 饰），同样有着朴实的家境、美丽的容貌和渴望真命天子快点出现的萌动春心。她遇上了一个叫艾迪（卢克·梅伯利 Luke Mably 饰）的小伙子，他来自丹麦王室，前来寻找印象中的狂野的美国大学生活。二人因误会相识，从冰火不容慢慢变得言语投契，相互扶持，感情日渐深厚。佩吉更是邀请艾迪前来家乡过田园生活，爱情在鸟语花香中生根发芽。然而，艾迪身为丹麦王子，和佩吉这个美国平民丫头终究身份悬殊。当佩吉好不容易进入了丹麦皇室，准备和王子长相厮守时，皇宫的繁文缛节却让她十分不适。佩吉再三考虑，决定和艾迪道别，回到美国继续念书。灰姑娘和王子难道注定属于不同的世界？©豆瓣', '朱丽娅·斯蒂尔斯', '玛莎·库利奇', 6.6, 20485, 'tt0337697', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1453119862.jpg', 1.1, 8.9, 56.9, 25.9, 7.2, '0.273176,-0.013617,-0.567290,0.730565,-0.081731,-0.332278,0.737260,0.278032,-0.645662,-0.347662,-0.016828,0.720680,-0.263727,0.140931,0.407107,-0.073334,-0.488398,-0.364059,0.075112,0.037185,0.247501,-0.426739,-0.151359,0.074748,-0.205057,-0.344532,0.712230,-0.219233,-0.223940,0.837818,0.059685,0.223404,-0.215737,0.255919,-0.092355,0.045830,0.127339,0.322490,-0.616404,0.157990,0.111605,0.140327,-0.070011,-0.059933,0.032831,0.225077,0.503575,-0.361124,0.213514,-0.120131,0.400617,0.125168,-0.046289,0.333503,0.105167,-0.066965,0.155825,0.211258,-0.083661,-0.087468,-0.059124,-0.225673,-0.369587,0.173619,0.246413,0.086367,-0.572177,0.261175,-0.018821,-0.398752,0.141006,-0.273952,0.135187,0.276135,0.563457,0.359354,0.072324,0.039207,-0.336357,0.001553,0.751036,0.274369,-0.334194,0.412929,-0.395049,-0.515755,-0.035186,-0.050219,-0.734287,-0.001765,0.125958,0.066122,-0.162496,0.480056,-0.649391,-0.131267,-0.135691,-0.114943,0.283607,-0.626982,0.105400,-0.467761,-0.326645,-0.448560,-0.175541,-0.148859,0.187575,-0.059001,0.820844,-0.717214,0.219910,0.384781,0.299267,-0.573042,0.613265,0.347728,0.032235,-0.217826,-0.161235,0.772411,0.010030,-0.159761,-0.205491,0.229171,-0.228684,0.135882,-0.417200,0.344811', '3445516', '25721544', '1292720', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309125', '见鬼2', '剧情', '失恋的郑嘉文（舒淇 饰）在泰国自杀未遂，捡回了性命。回到香港后，她准备忘记过去重新开始，却发现自己怀孕了，经过深思熟虑，她决定把孩子生下来。一天，在地铁站，嘉文目睹一个女子跳轨道自杀，周围的人却什么也没有看见，警方调查也一无所获，嘉文自己也百思不得其解。而从那以后，怪事接二连三地发生在她身上。嘉文在的士里与没有脸的厉鬼同坐，在公交车站等车碰到跳楼自杀的母子，她甚至看见同在医院待产的周太太，身边也有鬼魂如影随形。嘉文惊恐之余，认定这一切和地铁里自杀的女子有关，为了孩子，她开始调查事情的真相……©豆瓣', '舒淇', '彭发', 6.2, 8031, 'tt0405061', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1716312811.jpg', 1.9, 13.4, 59.8, 20, 4.8, '0.320683,-0.014171,-1.126903,0.225536,-0.119273,-0.458603,1.061469,-0.238652,-0.625966,-0.344095,0.278369,0.759326,-0.554617,0.359869,0.174757,-0.038063,-0.463122,-0.736197,0.117539,-0.211161,-0.486604,-0.346649,0.073056,-0.233863,-0.095749,0.026469,0.469986,0.238288,0.228571,0.325875,0.378055,-0.132559,-0.255025,0.640436,-0.334183,0.345144,-0.291398,0.057930,-0.015776,0.131938,0.391798,-0.557652,-0.297677,0.374563,0.179865,0.347389,0.573068,-0.076845,-0.242447,0.021232,0.320249,-0.270310,-0.005473,0.102847,0.506428,-0.002488,0.153930,0.041506,-0.324857,-0.286115,0.187682,0.381342,-0.285038,0.121424,-0.130278,0.407930,-0.742395,0.272936,-0.242369,0.153102,0.117513,-0.571362,0.337807,0.388708,0.043611,0.239442,-0.250467,-0.118869,-0.651296,0.033618,0.872652,-0.077061,0.050242,0.454206,0.185681,-0.321764,-0.027574,0.068431,-0.245650,0.073595,0.288882,0.157831,-0.629359,0.167820,-0.138716,-0.120556,-0.290692,-0.183913,-0.333396,-0.323696,-0.215523,-0.350223,-0.000280,-0.273847,-0.452681,0.198532,-0.140591,-0.282255,0.220506,-0.806969,0.207366,0.414370,0.354529,-0.607539,0.548593,-0.198927,0.158892,-0.114813,0.157341,0.255679,0.056367,0.593826,0.175016,0.286035,-0.174663,0.225738,-0.498237,0.329015', '25870679', '3011051', '10355329', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309132', '威震八方', '动作', '俗话说恶人自有恶人磨。恶霸汉密尔顿（尼尔•麦克唐纳 Neal McDonough 饰）纠集了一帮恶棍在华盛顿州的一个小镇横行多年、压榨乡邻，甚至连当地的警察也拿他们没有办法。这天，特种兵克里斯（巨石 The Rock 饰）退役回到了家乡小镇。一心想着集成父亲的木料场安居乐业的克里斯发现这里已经不是自己服役前那个宁静美丽的小镇了，父亲的木料场被汉密尔顿霸占用作了赌场，高中女友也在恶势力的威逼下成了艳舞女郎。怒不可遏的克里斯当上了小镇的治安官，决定凭着这些年在特种部队的所学的非常手段将这群恶棍赶出家乡！©豆瓣', '道恩·强森', '凯文·布瑞', 6.3, 6904, 'tt0351977', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2193564128.jpg', 1.6, 12.9, 60.1, 19.5, 6, '0.444696,-0.106294,-0.530435,0.510781,-0.370278,-0.344484,0.518255,0.254459,-0.550501,-0.159547,0.201239,0.690483,-0.109286,0.195037,0.150919,0.012055,-0.225257,-0.563588,-0.247422,-0.355782,-0.168967,-0.264745,-0.325804,-0.328202,-0.231089,-0.278590,0.458768,0.089190,0.176863,0.310432,0.244270,0.109517,0.205744,0.167694,-0.451509,0.121911,0.230721,-0.127722,-0.176389,0.262575,-0.311153,-0.266101,-0.218515,-0.095608,0.220860,0.327020,0.756956,0.021929,0.056258,-0.213056,0.074432,-0.163634,-0.085191,0.207356,0.557649,-0.393966,-0.105044,0.094563,-0.181333,-0.034179,0.224134,-0.164613,-0.555237,-0.084859,-0.039786,-0.107936,-0.849513,0.502062,-0.182006,-0.053620,-0.212464,-0.442444,0.282409,0.110460,-0.001959,0.421945,0.060185,-0.090549,-0.679568,0.366574,0.560432,-0.147838,-0.166037,0.116418,-0.289532,-0.279753,0.107709,-0.447481,-0.312020,-0.304461,0.428165,-0.470797,-0.398347,-0.195569,-0.621212,-0.133459,-0.123299,-0.357567,0.174513,-0.271060,-0.339005,-0.539637,-0.083350,-0.269213,-0.144960,0.201661,0.034023,0.169093,0.662199,-0.766401,0.155127,0.689567,-0.025970,-0.410319,0.440246,-0.002801,0.040290,0.208967,-0.147331,0.041035,0.295582,0.789349,0.288944,0.444328,-0.169352,-0.434180,0.010159,0.575176', '3285642', '1292829', '1308842', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309135', '虎兄虎弟', '剧情', '老虎古玛和桑哈出生在印度支那的原始森林里，本来正是无忧无虑的童年期，但是这里的古老石窟却招惹来一帮西方来的探险队。他们枪杀了他们的父亲。不幸的古玛被他们抬走了，剩下桑哈跟母亲慌乱逃生。古玛给辗转卖到了马戏团，被迫每天练习跳火圈之类的把戏。他想念家人，还不习惯被驯养的生活，境 况非常悲凉。而他的兄弟桑哈，也没能逃脱被人类抓捕的命运。幸亏长官的儿子非常宠爱它，把它留在家中一起生活，让他免于颠簸的生活。然而，它毕竟是一只有野性的老虎，当家人发现了危险的苗头时，可怜的桑哈还是被送到了动物园。几个月后，一场斗虎比赛开始了。两兄弟竟然意外被安排成竞技场上的对手。这次重逢让兄弟俩喜出望外，并开始了他们的逃脱计划。©豆瓣', '盖·皮尔斯', '让-雅克·阿诺', 8.6, 26207, 'tt0338512', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p817094477.jpg', 0.2, 0.7, 12.1, 44, 43, '0.456808,-0.101994,-0.698575,0.404773,-0.251905,-0.301761,0.634043,0.104350,-0.620626,-0.116283,0.126402,0.776037,-0.191737,0.257958,-0.100973,0.056385,-0.128454,-0.490231,-0.044582,0.012246,-0.210070,-0.097404,-0.134606,-0.190607,-0.011634,-0.196893,0.482197,0.120232,-0.049276,0.552391,-0.030123,0.074868,-0.122794,0.500613,-0.424908,0.064704,-0.044979,-0.105197,0.023113,0.141981,-0.045755,-0.135514,-0.028882,0.271661,0.159027,0.314761,0.719150,-0.181813,-0.196945,-0.237708,0.167401,-0.414687,-0.140234,0.311310,0.437403,-0.113192,0.070540,0.065364,-0.027688,0.004381,0.024412,-0.116196,-0.826833,0.327479,-0.090343,-0.083833,-0.771060,0.447775,0.165831,-0.046363,0.001235,-0.248239,0.446876,0.466657,0.195240,0.308763,-0.216637,0.021096,-0.689731,-0.014198,0.882481,-0.586956,-0.100977,0.280101,-0.028520,-0.517349,0.104903,-0.407918,-0.319986,0.002725,0.374423,0.042543,-0.524244,0.103641,-0.637037,0.149348,-0.332466,-0.222899,-0.286926,-0.568628,-0.080937,-0.271311,-0.095393,-0.439512,-0.554288,0.130139,0.102618,-0.178849,0.550174,-0.647710,0.260907,0.532211,0.296793,-0.394033,0.666796,0.070281,0.051369,0.041111,0.044518,0.169053,0.049088,0.345621,0.513494,0.351944,-0.080637,-0.054645,-0.355642,0.437014', '25721544', '1866424', '3055049', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309136', '范海辛', '剧情', '十九世纪，罗马尼亚存在着一个人鬼共存的神秘地带――特兰西尼亚古镇。镇上有一支邪恶势力在天黑后统治着该地区，那就是吸血鬼德古拉（理查德•劳斯伯格 Richard Roxburgh 饰）领导下妖魔鬼怪。他们一到日黑就出来大肆杀戮，手段异常残忍。更加恐怖的是，这个队伍在不断壮大中，噬血的科学怪人也不远万里投靠了德古拉。罗马尼亚的天主教在多次征剿失利后，远赴美国请来了吸血鬼猎人范海辛（休•杰克曼 Hugh Jackman 饰）。范海辛带着助手前往特兰西尼亚途中，巧合下救了另一位吸血鬼女猎人――安娜（凯特•贝金赛尔 Kate Beckinsale 饰）。安娜因为家族世代受到德古拉的诅咒而家破人亡，从小练就了一套猎鬼本领。安娜和范海辛一拍即合，共同前往对付德古拉……©豆瓣', '休·杰克曼', '斯蒂芬·索莫斯', 7.2, 95756, 'tt0338526', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1827627208.jpg', 0.7, 5.1, 40.6, 40.2, 13.5, '0.112924,0.132831,-0.617534,0.282073,0.158302,-0.032284,0.518175,0.041126,-0.537052,-0.300594,0.266404,0.771312,0.075735,0.003377,0.474580,0.198488,-0.671041,-0.172274,0.075065,-0.196655,-0.292253,-0.363584,-0.373056,-0.238324,0.070028,-0.609273,0.089182,0.157331,-0.168396,0.416329,0.146765,0.600841,-0.276344,0.020634,-0.030419,0.079728,0.371132,-0.384470,-0.244681,0.358591,0.071145,0.233631,-0.389064,0.007175,-0.048524,0.303326,0.400945,-0.512645,0.288117,-0.426060,0.059198,-0.309124,0.060099,0.084682,0.439994,-0.297275,0.131319,0.234587,0.095063,-0.035686,-0.073559,-0.103450,-0.758220,0.230618,0.064122,0.256193,-0.614317,0.439853,-0.169560,-0.204539,0.153306,-0.402597,-0.110272,0.540232,0.167604,0.167959,0.141412,-0.179644,-0.638886,-0.165268,0.534252,-0.094455,-0.301306,-0.149769,-0.233483,-0.467559,-0.240907,-0.300897,-0.336038,-0.394066,0.666435,-0.276759,0.023631,0.681429,-0.801076,-0.141777,-0.425327,0.128368,0.097998,0.071917,-0.096304,-0.667212,0.082289,-0.251288,-0.036398,0.126742,-0.014825,0.153533,0.537471,-0.588180,0.295371,0.715777,0.605589,-0.201385,0.299442,-0.207626,0.181757,-0.071953,-0.253611,0.473784,0.266295,0.339753,0.477116,0.303263,0.178925,-0.245786,-0.055535,0.451943', '1306723', '24750460', '1309069', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309145', '机动杀人', '悬疑', '又一具无法辨认身份的尸体被发现，当地警方在对于案件调查毫无进展的情况下邀请特别探员伊莲娜·斯科特（安吉丽娜·朱莉 Angelina Jolie 饰）协助调查。斯科特不按常理出牌的办案方式惹来同事皮卡特的不满，但是凭借敏锐的直觉和超常的洞察力，斯科特还是很快便理出头绪：罪犯嫌疑人马丁·阿什20年来以扮演他人生活为目的，每次行凶后都会扮演死者身份开始一段新的目活。康斯塔（伊桑·霍克 Ethan Hawke饰）是最后一次凶案的目击者，在配合斯科工作时两人互生好感，但介于警员身份，斯科特始终与他保持距离。在这宗连环凶案终结当日，两人内心深埋的感情最终迸发。就在两人发生关系的第二天，斯科特目睹詹姆斯于电梯中杀死嫌犯母亲，此时她才发觉自己正在掉入一个陷阱……本片根据英国小说家迈克尔·派伊（Michael Pye）的同名小说改编。©豆瓣', '安吉丽娜·朱莉', 'D·J·卡卢索', 7, 22215, 'tt0364045', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p817155717.jpg', 0.6, 5.3, 45.8, 38.6, 9.7, '0.328740,-0.101350,-0.556180,0.542586,-0.150041,-0.075913,0.585129,-0.004459,-0.559921,-0.698642,0.225057,0.615970,-0.339355,-0.144214,0.185078,-0.280174,-0.520589,-0.748045,0.042323,-0.069558,-0.221760,-0.768195,-0.234618,-0.299803,-0.030037,-0.132803,0.457510,-0.094172,-0.324614,0.292010,0.152091,0.575980,-0.518216,0.427765,0.023865,-0.232589,0.450471,-0.148571,-0.303917,0.285159,0.214965,-0.260509,-0.202778,0.088198,-0.011111,0.625627,0.664628,-0.182452,-0.449242,0.179806,0.186418,-0.163322,0.153252,0.074400,0.564583,-0.071389,0.127557,0.399341,-0.020241,0.056367,-0.016157,-0.034831,-0.781543,0.010983,0.091891,0.303311,-0.340354,0.054355,-0.357267,0.014048,0.058031,-0.374628,0.081698,0.271059,0.484229,0.152358,-0.070583,-0.119357,-0.268595,-0.212598,0.585528,0.121982,-0.263435,0.427385,-0.403685,-0.573327,-0.204571,0.064041,-0.101244,0.181330,0.279923,0.186678,-0.114233,0.307693,-0.189656,-0.301041,-0.444557,-0.068963,-0.275306,-0.372333,0.170654,-0.734263,-0.431876,-0.259667,-0.300926,-0.098440,-0.013716,-0.295838,0.186860,-0.714839,0.045683,0.435245,-0.155434,-0.496828,0.445269,0.221818,-0.111471,-0.415559,-0.101879,0.202234,0.280454,0.074106,-0.015259,0.179494,0.211868,-0.233490,-0.159510,0.253462', '25723905', '1307442', '27126336', '1301161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309153', '神秘村', '悬疑', '1897年，宾夕法尼亚州有一座名为考明顿的小村庄。这里风光秀美，景色宜人，村民间更是团结友爱，和善为亲，过着平静自在的生活。然而，考明顿村民的心中却有着一个挥之不去的梦魇。传说在村子周围的丛林中隐藏着残忍而恐怖的怪物，它们和村民间似乎有着一道不可僭越的约定，双方守在各自的领地，秋毫无犯。但是近一段时间种种迹象表明，盘踞在森林中的怪物正试图践足人类的领地。人们对此无计可施，只能用古老的办法——在树干漆上黄色——来阻退怪物。为了医治母亲的病，年青人路西斯（杰昆·菲尼克斯 Joaquin Phoenix 饰）决心去森林另一边的城镇采购药品。这一举动彻底改变了考明顿的命运……©豆瓣', '布莱丝·达拉斯·霍华德', 'M·奈特·沙马兰', 7, 14828, 'tt0368447', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2161515392.jpg', 1.7, 7.2, 42.4, 36.9, 11.9, '0.141313,0.023034,-0.588922,0.753858,0.227172,0.221734,0.923360,0.187190,-0.736819,-0.123682,0.286137,0.344708,0.126899,0.192885,-0.113835,-0.120715,-0.278889,-0.061724,-0.198918,-0.295894,-0.317166,-0.122589,-0.454839,-0.575071,-0.066078,-0.368535,0.690812,0.405332,0.029991,0.286055,-0.092048,0.332715,-0.353134,0.337194,-0.379589,-0.280054,-0.116368,-0.057326,-0.308786,-0.043450,-0.268557,-0.032700,-0.441371,0.117185,-0.037682,0.336721,0.814048,-0.328149,-0.398459,0.085890,0.265773,0.039198,0.145108,0.105681,0.724234,-0.327833,0.136389,0.093316,-0.020546,-0.110034,-0.015755,-0.209606,-0.633193,-0.047802,0.130944,0.255868,-0.441627,0.510517,0.319268,-0.206369,-0.003602,-0.586016,0.113798,0.082709,0.203353,0.299395,-0.158903,-0.026004,-0.685109,-0.000677,0.604922,-0.066863,-0.321596,0.194743,-0.528489,-0.405537,-0.466078,-0.263337,-0.597129,-0.284020,0.265874,0.101221,-0.560958,0.325314,-0.731857,0.132287,-0.161416,-0.298200,0.086428,-0.264378,-0.391227,-0.420946,0.006590,-0.299487,-0.274426,0.362844,-0.020120,0.116383,0.689975,-0.597479,0.290159,0.760771,0.285868,-0.224871,0.667922,-0.216923,0.083030,-0.023209,-0.347316,0.531072,-0.020889,0.443029,0.202399,0.246312,-0.242479,-0.006246,-0.411238,0.588927', '21619567', '24879819', '1293515', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309156', '海绵宝宝历险记', '喜剧', '蟹堡王毗邻本店的二号店即将开张了！海绵宝宝满心期待，以为分店经理一职非自己莫属，然而蟹老板却以他不够成熟为理由，将分店交给章鱼哥打理。同时看着蟹堡王做大的痞老板再出毒计，他偷走了海王星国王的王冠，并嫁祸蟹老板，盛怒的海王星要处死蟹老板，但为了拿回王冠，给忠诚的海绵宝宝和派大星六天时间，让他们去无人能够生还的贝壳城取回王冠。而痞老板得逞后偷走了蟹老板的蟹黄堡配方，生意迅速大热，他趁机把能够操纵思想的头盔赠送给顾客们，要通过控制海洋生物称霸世界。另一面，海绵宝宝和派大星踏上了无厘头又凶险万分的寻冠之路，前往传说中独眼巨人栖息的贝壳城……©豆瓣', '汤姆·肯尼', '史蒂芬·海伦伯格', 8.5, 41094, 'tt0345950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p476254131.jpg', 0.3, 1.2, 14.1, 42.1, 42.4, '-0.144157,0.401263,-0.331068,0.393419,-0.017757,-0.100913,0.326156,0.456129,-0.309049,-0.093659,0.040710,0.480103,-0.032627,0.070716,0.013187,0.317128,-0.125113,-0.200912,-0.072018,-0.181238,-0.193891,0.015482,-0.058986,-0.215974,0.038013,-0.016445,0.354147,0.089546,0.104239,0.222762,0.205066,0.112743,-0.001401,0.404758,-0.227497,-0.202048,-0.143132,-0.181023,-0.348514,0.391383,-0.028476,0.095806,0.044812,0.240194,0.430755,0.115446,0.602798,-0.407512,-0.225067,-0.408412,0.102019,-0.276080,0.125844,0.043351,0.130459,0.161417,0.030255,-0.041725,-0.414983,-0.008805,0.492664,-0.380386,-0.833828,-0.078384,0.064657,0.014159,-0.750224,0.056128,-0.102724,0.243738,0.196828,-0.534941,0.412639,0.212425,0.177279,0.327461,0.138934,0.229886,-0.738519,0.163548,0.471252,-0.226713,0.201246,-0.100786,0.227813,-0.371863,0.281602,-0.215551,-0.091881,0.037391,0.603487,0.070652,-0.065879,0.149052,-0.691270,-0.176623,-0.360156,-0.327711,0.396142,-0.388942,-0.165031,-0.306799,0.338566,-0.019408,0.172939,0.052826,0.358618,0.025786,0.489917,-0.677376,0.056830,0.494334,0.407567,-0.448508,0.602542,-0.224421,-0.137610,-0.404715,-0.341091,-0.415976,0.411280,0.459461,0.207871,0.270195,0.251014,-0.466945,-0.375002,0.185664', '1793491', '1473562', '30387441', '6030611');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309160', '机械师', '剧情', '特拉沃（克里斯汀•贝尔 Christian Bale  饰）是一个机械师，他的工作内容繁忙机械，日复一日，令他日渐消瘦，连睡眠都出现了严重的问题。长达一年里，特拉沃成为了无法睡眠的怪人。怪事也从此陆续发生：他在公寓里面发现了一张神秘纸条；总是感觉有一个共事的工友，在一次意外中工友失去了一只手，所有的同事都把这个意外归咎于特拉沃，令特拉沃众叛亲离，唯有身边当应召女郎的女友一直在支持自己。然而，事实又好像并不是这样，那张纸条，那个工友，似乎都不是现实的事情，特拉沃陷入了巨大的谜团当中。©豆瓣', '克里斯蒂安·贝尔', '布拉德·安德森', 7.6, 106555, 'tt0361862', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p453944400.jpg', 0.5, 2.7, 30.1, 49.6, 17, '0.400555,-0.104390,-0.432968,0.353326,0.056576,-0.168351,1.073903,0.075772,-0.878573,-0.329735,0.159240,0.796729,-0.279331,0.460477,0.018787,0.087784,-0.353268,-0.817711,-0.042901,-0.250467,-0.478793,-0.545593,-0.291888,-0.129675,-0.063353,-0.409859,0.410931,-0.056854,0.015103,0.515569,0.153920,0.242358,0.146955,0.833224,0.060213,0.124769,0.265210,-0.059179,0.340382,-0.078561,0.108837,-0.220300,0.079480,0.335860,0.138066,0.478327,0.517551,-0.359455,-0.471911,-0.003222,0.315414,-0.114389,-0.171080,0.209235,0.286651,-0.212703,0.082770,0.038867,-0.413413,0.132264,0.161168,-0.096669,-0.730374,-0.223558,-0.211606,0.526837,-0.762429,0.378195,-0.166304,-0.148754,0.083819,-0.170792,0.362189,0.305129,0.330960,0.371545,-0.173850,-0.163432,-0.459025,0.195920,0.355071,0.054906,-0.548617,0.596472,-0.397957,-0.344085,-0.320702,-0.088875,-0.377302,0.077464,0.066603,0.121120,-0.131036,0.528776,-0.507106,0.228872,-0.137683,-0.339685,-0.342770,-0.368222,-0.335070,-0.226115,-0.069671,-0.279606,-0.401221,0.224870,-0.150833,-0.179429,0.476763,-0.726735,0.236966,0.705986,0.137916,0.107766,0.554885,0.227385,0.146399,-0.194766,-0.259748,0.268355,0.115724,0.350494,0.365084,0.394348,0.003525,-0.169630,-0.430695,0.623285', '1309172', '21348112', '3059036', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309161', '辣身舞2：情迷哈瓦那', '剧情', '1958年，本生活在哈瓦斯的18岁姑娘凯蒂•米勒（萝玛拉•嘉瑞  饰）随父母来到了古巴，只懂一点点西班牙文的她在这里开始了新生活。她的父亲有一份优厚的工作，生活无忧的她十分好学。本来对舞蹈就十分热爱的她遇到了英俊的侍应生杰威尔（迭戈•鲁纳 饰），杰威尔同样是一名舞蹈好手。很快他们因彼此的舞技互相吸引，可是动荡的政治环境让凯蒂的父母有了把女儿带走的念头，这对热恋中的情侣受到了考验。这里有凯蒂热爱的舞蹈，有自己深爱的恋人，凯蒂将如何面对景况呢？©豆瓣', '迭戈·卢纳', '盖·费尔兰德', 8, 6775, 'tt0338096', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1592305170.jpg', 0.4, 2.1, 23.5, 44.5, 29.6, '0.512454,-0.153155,-0.637619,0.412035,-0.225560,-0.221426,0.666601,0.188638,-0.379518,-0.203186,0.295734,0.997516,-0.191322,0.155075,0.277448,0.209332,-0.220418,-0.719386,0.007014,-0.096437,-0.094472,-0.459327,-0.137366,-0.077209,-0.183326,-0.407689,0.391589,-0.226658,-0.040714,0.399716,-0.086712,0.326613,0.357702,0.410856,-0.280605,0.183728,0.190149,-0.064535,-0.178786,0.096440,0.259448,-0.172878,-0.177772,0.195514,0.051078,0.267917,0.903012,-0.361235,-0.118264,0.053091,0.279661,-0.133265,-0.126889,-0.045464,-0.039194,-0.219421,-0.014366,0.194930,-0.228738,-0.107193,-0.055521,-0.281388,-0.561183,0.022330,0.026773,0.149138,-0.504387,0.470540,-0.064102,-0.218707,0.199664,-0.376826,0.070779,0.391305,0.111134,0.306589,-0.097468,-0.062849,-0.423031,0.144307,0.798687,0.161543,-0.364877,0.566949,-0.779511,-0.532524,-0.016945,-0.245171,-0.662886,-0.140805,0.312953,-0.051906,-0.125227,0.164401,-0.569196,0.220390,-0.156660,-0.197817,0.143380,-0.657661,-0.211456,-0.455196,-0.281830,-0.816071,-0.548135,-0.312380,-0.088617,-0.378198,1.117166,-1.061724,0.200961,0.516933,0.184656,-0.540746,0.830621,0.142002,0.132056,0.021540,-0.234536,0.273005,-0.268925,0.104318,0.141377,0.431492,0.099045,0.011515,-0.274414,0.541076', '1292219', '1292720', '3445516', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309162', '巴黎烟云', '剧情', '1933年的一个雨夜，英国剑桥大学的一名一年级学生盖伊（斯图尔特·汤森德 Stuart Townsend 饰）的寝室里，突然闯入了一位美艳动人的女子吉尔达（查理兹·塞隆 Charlize Theron 饰），盖伊好心收留她过夜，而后两人迅速坠入爱河。几年后，吉尔达成为了一名时尚摄影师，邀请盖伊前去她巴黎的豪宅相聚，并与她的模特兼密友米娅（佩妮洛普·克鲁兹 Penélope Cruz 饰）三人一起享受着时髦与欢乐的时光。然而，就在吉尔达的事业如日中天之时，第二次世界大战爆发了，三个好朋友因对于此持不同看法而分道扬镳，盖伊和米娅决定去往前线支援，而吉尔达则留了下来。6年的抗战之后，盖伊回到了日思夜想的巴黎，得知爱人吉尔达已成为千夫所指的德国军官情妇，却不知她其实是一名地下间谍。而此时的吉尔达已面临生死关头，一方面，她的间谍身份行将暴露，另一方面，巴黎的民众恨不得杀她而后快，两个有情人的命运还能否相交……本片曾获2005年米兰国际电影节最佳影片奖。', '查理兹·塞隆', '约翰·杜根', 7.9, 19329, 'tt0338097', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p811292040.jpg', 0.3, 1.9, 23.1, 50.2, 24.4, '0.229965,0.025479,-0.480177,0.516168,0.017885,-0.580885,0.787022,0.265646,-0.416642,-0.231738,0.222949,0.830992,-0.118557,0.377045,0.712579,0.118811,-0.293821,-0.867283,-0.008230,-0.222254,-0.039037,-0.222944,-0.303488,-0.078749,-0.171209,-0.262096,0.628541,0.039503,0.050867,0.552112,0.485755,0.326528,-0.179111,0.356942,-0.147974,-0.163404,0.289894,0.045083,-0.461451,0.273585,-0.053787,-0.308429,-0.256611,0.029453,-0.027729,0.222603,0.588077,-0.140645,0.137591,-0.111846,0.390969,-0.125811,0.004732,0.259600,0.343260,-0.099544,0.212494,0.146196,-0.175725,0.074451,0.020658,-0.198407,-0.537185,0.230684,-0.057789,-0.060827,-0.450548,0.572938,-0.148748,-0.014792,0.010233,-0.224958,0.061621,0.323426,0.132219,0.301439,-0.110798,-0.060545,-0.304008,0.238425,0.740135,0.034972,-0.162048,0.200858,-0.088186,-0.426105,-0.015379,-0.148035,-0.536404,-0.055308,0.382640,0.041751,0.007490,0.235775,-0.538703,-0.189725,-0.558044,-0.125589,-0.091137,-0.256776,-0.161170,-0.564481,-0.130002,-0.276550,-0.261709,0.028826,0.151087,0.008875,0.647252,-0.797843,0.318892,0.466837,0.166641,-0.519599,0.684807,0.070867,0.447460,-0.127651,-0.054900,0.470114,-0.049135,0.095057,-0.061712,0.320261,-0.301991,-0.178003,-0.348572,0.359884', '30162520', '11541282', '26687241', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309163', '恋恋笔记本', '剧情', '一个浸润着鲜红与纯白的爱情故事，写在一本洒满昏黄的笔记本上，被一位老先生(詹姆斯·加纳 饰)，一遍一遍的讲述。老太太(吉娜·罗兰兹 饰)总是静静的听着，好奇的追问结果。在一家疗养院，这样不变的场景每天都会上演。笔记本上，秀美的字迹，记载着发生在那个夏天的爱情。艾莉(瑞秋·麦克亚当斯 饰)是富有人家的千金，她随家人来到小镇避暑。在一个充满梦幻的游乐场，邂逅了诺亚(瑞恩·高斯林 饰)。诺亚没有钱，却活的很快乐。艾莉在他那学会了自由，得到了欢笑，两人很快热恋起来。然而在艾莉父母的阻挠下，相爱的两个人，就被分开在夏天结束的那一刻。随着诺亚的365封信被偷偷藏起，艾莉在7年后终于放弃了等待。就在她要步入教堂的前一天，突然在报纸上看到了诺亚曾许诺给自己建造的白色房子。一切记忆，全部苏醒……也许，应该苏醒的，不是故事中的，而是听故事的人。©豆瓣', '瑞恩·高斯林', '尼克·卡萨维蒂', 8.6, 625723, 'tt0332280', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p483604864.jpg', 0.3, 1.3, 13.4, 40.4, 44.6, '0.509965,0.162186,-0.822335,0.674260,-0.111988,-0.374179,1.176747,0.164253,-0.427932,-0.059214,0.300269,0.595230,-0.429251,0.376171,0.356662,0.156114,-0.447974,-0.616431,0.006366,-0.163318,-0.281848,-0.669138,-0.065652,-0.030818,0.046201,-0.282515,0.310149,-0.023566,0.023112,0.401394,0.176660,0.022621,-0.126032,0.424060,-0.354902,0.176478,-0.037996,0.092963,-0.023397,0.274327,0.129275,-0.383168,-0.254075,0.090689,-0.170726,0.060734,0.802776,-0.271997,0.001709,0.359314,0.346494,-0.057534,-0.074638,0.219589,0.266350,0.113282,0.005977,0.047909,-0.350995,-0.111921,0.160204,-0.046479,-0.521679,-0.072991,-0.064041,0.673604,-0.750456,0.669256,-0.162809,0.047674,0.123258,-0.617263,0.295537,0.357435,0.237984,0.570390,-0.002000,0.020919,-0.726655,0.381954,0.430280,0.087665,-0.101338,0.502576,-0.165472,-0.260754,-0.207312,0.254121,-0.814306,0.008730,0.603392,-0.047345,-0.284857,0.155614,-0.720341,-0.073557,-0.092536,-0.669605,0.145455,-0.393644,-0.246994,-0.639872,-0.316903,-0.304241,-0.501702,0.151309,-0.120926,-0.368706,0.733735,-0.795752,0.555404,0.445007,0.004504,-0.028887,0.551383,0.090118,0.040109,0.052012,0.043002,0.379528,0.177302,0.465327,0.308036,0.597849,0.083981,0.120317,-0.706701,0.833896', '1302133', '21619567', '26677495', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309170', '大人物拿破仑', '剧情', '爱达荷州普林斯顿高中生拿破仑（乔恩•海德 Jon Heder 饰）是个衰蛋，带着厚厚的眼镜，不酷不帅，还总是搞怪。他和奶奶以及失业的哥哥凯普相依为命。他在学校不受同学待见，还经常被老师修理。他不合群，只能孤独地跟风车球使劲儿。后来，他结识了同学佩德罗（艾弗连•莱米雷斯 Efren Ramirez  饰），两人成了朋友。在佩德罗参加学生会主席竞选时，拿破仑贡献了自己的力量。一次，拿破仑在家扮沙发土豆时，有女孩黛比（蒂娜•米乔里诺 Tina Majorino 饰）上门推销。他于是对这个女孩产生了好感，但是没有勇气追求，只能想出一些拙劣的鬼点子，结果总是不欢而散。凯普看电视购物，被防身术教练深深吸引了，拉着拿破仑两人参加了俱乐部，没想到大失所望……©豆瓣', '乔恩·海德', '杰瑞德·赫斯', 7.6, 7199, 'tt0374900', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2540518828.jpg', 1.8, 4.6, 28.5, 40.9, 24.2, '0.435538,-0.253371,-0.431736,0.348905,-0.354912,-0.478774,0.362409,0.376475,-0.389635,-0.082393,-0.013674,0.695443,-0.396819,0.483149,0.118569,0.192949,-0.459108,-0.621092,0.198402,0.135068,-0.088851,-0.455763,-0.098062,-0.149423,-0.128362,-0.224554,0.119667,-0.373144,-0.120572,0.370978,0.337877,0.085452,0.332411,0.479194,-0.122509,0.148727,0.347557,0.066639,0.006819,0.098058,0.301905,-0.181290,-0.230473,-0.058875,0.266960,0.199687,0.403160,0.150652,0.121414,-0.159431,0.171364,-0.161286,0.004004,0.126003,0.207416,-0.008893,0.261800,-0.122459,0.156020,0.064213,0.398860,-0.243580,-0.073790,0.163147,0.027703,0.011861,-0.548472,0.616519,-0.230637,-0.107195,0.111857,-0.302810,-0.096979,0.149298,0.215741,0.211487,-0.137822,0.012444,-0.424320,0.185514,0.501300,0.059401,-0.171687,0.169452,-0.338034,-0.160017,0.210359,-0.268532,-0.494909,0.168506,0.327987,-0.283352,-0.052829,0.095842,-0.502150,-0.062958,-0.143005,-0.024055,0.031877,-0.365423,-0.048504,-0.509584,0.011227,-0.316363,-0.289227,-0.021979,-0.023891,-0.120190,0.630146,-0.763525,0.158446,0.577942,0.448795,-0.208709,0.719283,0.174276,-0.210727,-0.061113,0.038475,-0.002492,-0.238192,0.126977,0.235432,0.621396,0.321596,-0.391614,-0.064981,0.301070', '5327188', '1292219', '1915403', '4739952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309171', '秘窗', '悬疑', '雷尼（约翰尼·德普 Johnny Depp 饰）的妻子出了轨，他发现她和另一个男人躺在床上，他提出了离婚。然而，婚姻的阴影并没能使雷尼恢复原气。他的文笔开始暗淡无光，找不到从前的创作激情。于是，他来到了一个湖畔小屋疗伤创作。然而这个小屋，却给他带来了新的麻烦。首先是一个陌生人的造访令他十分恼火。那人声称雷尼抄袭了他的作品，雷尼百般解释也不能让他信服。于是雷尼翻箱倒柜，想找出原稿，却发现原稿离奇失踪。惊悚事件陆续有来，整个小屋，好像出于某种危险的情势中，雷尼非常害怕，然而却查不出缘由。是不是前妻和她的情人在作怪？他们到底有何目的？然而，真相却让雷尼自己都不敢相信。©豆瓣', '约翰尼·德普', '大卫·凯普', 7, 40848, 'tt0363988', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1087667647.jpg', 0.7, 5.9, 46.3, 36.1, 11.1, '0.330233,-0.078442,-0.956737,0.516968,-0.214720,-0.216781,1.016740,0.121564,-0.632278,-0.434422,0.084341,0.639974,0.053760,0.244945,-0.068319,0.242390,-0.267452,-0.511455,0.278417,-0.298070,-0.211203,-0.416926,-0.255938,-0.340726,-0.068720,-0.049422,0.351489,-0.074018,-0.236538,0.097839,0.451862,0.290779,0.091703,0.871065,0.014349,0.167693,0.053605,0.098974,0.078372,0.048416,0.187573,-0.204889,-0.502597,0.696435,-0.152503,0.711866,0.389622,-0.116861,-0.417293,0.234385,0.460688,-0.402687,0.058708,0.208894,0.017463,-0.077692,0.155913,-0.066543,-0.200880,-0.201366,0.174370,0.231147,-0.709045,0.213990,0.111471,0.278504,-0.501692,0.111347,-0.202474,-0.136445,0.016518,-0.328827,0.200909,0.223365,0.360485,0.178001,-0.253388,-0.125543,-0.681443,-0.058967,0.436187,0.033172,-0.328666,0.471642,-0.198162,-0.308808,0.049723,0.090119,-0.437728,-0.054340,0.459877,0.193488,-0.295332,-0.145162,-0.446579,-0.113081,-0.425546,-0.176742,-0.285573,-0.567045,-0.048559,-0.097369,-0.324533,-0.018254,-0.337081,-0.214026,0.041671,-0.317104,0.484183,-0.625732,0.092659,0.717787,0.123817,-0.517984,0.435686,0.282701,-0.102983,-0.162215,-0.044391,0.247980,-0.004133,0.220218,0.006363,0.385004,0.286098,-0.097139,-0.677425,0.443026', '35441371', '1947080', '1421570', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309172', '初恋50次', '喜剧', '亨利·罗斯（亚当·桑德勒）是个典型的花花公子，他最擅长的事就是以不同的身份，让美女迷恋上他，并在事后，迅速从关系中脱身。身为夏威夷海洋馆的兽医，亨利有着无尽的浪漫情怀来感染到此休闲的美女，这一次他看上了在餐馆独自用餐的露西(德鲁·巴里摩尔饰)。他们在一起谈天说地，用百吉饼搭建小房子，笑声不断。亨利对女孩恋恋不舍，相约明晨再次一起用餐。然而，第二天清晨，当亨利热情的与露西打招呼时，露西却宛如陌生人一般冷淡。原来女孩由于车祸患上了奇怪的短期记忆丧失症，记忆永远停留在车祸的前一天。情圣亨利遇到了自己的难题，他坠入的情网，却爱上一个不断对爱情失忆的女孩儿……©豆瓣', '亚当·桑德勒', '彼得·西格尔', 7.9, 275079, 'tt0343660', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p480949516.jpg', 0.2, 1.5, 24.1, 49.4, 24.7, '0.471892,0.133592,-0.615768,0.426450,-0.259382,-0.389156,1.087787,0.198214,-0.557910,-0.239084,0.276221,0.940452,-0.230278,0.292944,0.164555,0.084757,-0.497354,-0.688525,0.029172,-0.023688,-0.418725,-0.490812,-0.073464,-0.098488,0.014625,-0.267807,0.261891,-0.154418,-0.083080,0.638592,0.221546,0.225182,-0.090832,0.792752,-0.145506,0.017909,0.105453,0.136496,-0.254065,0.234738,-0.014956,-0.185065,-0.087185,0.145243,-0.034726,0.270630,0.626529,-0.262038,-0.072616,-0.069354,0.201454,-0.050188,-0.066115,0.213349,0.201603,-0.170931,0.387380,-0.155668,-0.224220,-0.212564,-0.020866,0.021696,-0.478121,0.038915,0.004741,0.328327,-0.431781,0.533826,0.104950,-0.120306,0.263985,-0.399193,-0.043429,0.130629,0.185846,0.355339,-0.113819,0.101582,-0.313169,0.027504,0.632987,0.279944,-0.253787,0.613776,-0.346864,-0.284498,-0.021885,-0.011066,-0.583912,-0.067734,0.230492,-0.023905,-0.166697,0.221967,-0.583662,-0.050371,0.029281,-0.008705,-0.189332,-0.244880,-0.210938,-0.674286,-0.098399,-0.477030,-0.312879,-0.029371,-0.014830,-0.091484,0.444162,-0.887187,0.357392,0.782648,0.162138,-0.134695,0.740037,0.136790,-0.032359,-0.294835,-0.256399,0.586440,0.009836,0.158134,-0.016127,0.553163,-0.047431,0.163515,-0.521408,0.799813', '1296534', '4275444', '1291877', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309173', '名利场', '剧情', '故事发生在十九世纪的英国，贝姬（瑞茜·威瑟斯彭 Reese Witherspoon 饰）出生于贫寒家庭，但是，野心勃勃的她做梦都想要能够跻身上流社会，为此，贝姬来到了爵士彼得考利（鲍勃·霍斯金斯 Bob Hoskins 饰）家中，担任起了家庭教师的职务。聪明伶俐的贝姬很快就获得了姑妈玛蒂尔达（艾琳·阿特金斯 Eileen Atkins 饰）的认可和信任，之后，贝姬跟随玛蒂尔达来到了梦寐以求的伦敦。在伦敦，贝姬同曾经的好友艾米利亚（萝玛拉·嘉瑞 Romola Garai 饰）重逢了。艾米利亚深爱着军官乔治（乔纳森·莱斯·梅耶斯 Jonathan Rhys Meyers 饰），为了同他结婚不惜背弃了家庭，与此同时，贝姬亦同考利家的继承人罗顿（杰姆斯·鲍弗 James Purefoy 饰）秘密踏入了婚姻的殿堂。然而，等待着他们的并非光明的前程，而是残酷的战争。', '瑞茜·威瑟斯彭', '米拉·奈尔', 6.9, 14070, 'tt0241025', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2578836203.jpg', 0.7, 6.6, 48.4, 34.5, 9.7, '0.266160,0.134905,-0.646247,0.482218,-0.056699,-0.585606,0.456037,0.382516,-0.493195,-0.540071,0.165716,0.804277,-0.072526,0.223179,0.472501,0.047302,-0.398048,-0.739894,-0.027133,-0.278784,-0.029488,-0.592112,-0.152979,-0.263812,-0.165203,-0.516615,0.322773,-0.045974,-0.033768,0.368559,0.433992,0.482839,0.149687,0.058249,-0.115583,0.128172,0.391048,0.232081,-0.623924,0.077462,0.014768,0.145926,0.005444,0.118990,0.196119,0.152533,0.343708,-0.518767,0.256763,-0.172750,0.398468,-0.101959,0.316110,0.129380,0.222167,-0.044301,0.075621,0.469842,-0.126427,0.023209,0.310923,-0.178116,-0.551237,0.224110,0.101493,0.135163,-0.515674,0.547999,-0.211313,-0.180519,0.135336,-0.121967,0.058315,0.573560,0.168034,0.244463,-0.157827,0.087283,-0.697793,0.167585,0.532880,-0.055117,-0.222450,0.171233,-0.476760,-0.508146,-0.113491,-0.298645,-0.632277,-0.174827,0.487130,0.104321,0.285494,0.516671,-0.457498,-0.319375,-0.468644,0.082499,0.349307,-0.411632,-0.089367,-0.586412,-0.126137,-0.254755,-0.207613,-0.020036,-0.176960,-0.430577,0.561840,-0.794489,0.348058,0.376410,0.452166,-0.288210,0.729939,-0.062838,0.265575,-0.182440,0.170828,0.771025,0.178766,0.155730,-0.079301,0.121824,-0.043592,-0.205939,-0.229073,0.516890', '1292720', '1578475'