INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309177', '纽约时刻', '喜剧', '简（爱什莉•奥尔森 饰）与罗西克（玛丽-凯特•奥尔森 饰）是瑞恩家的一对双胞胎。她们相貌相似，血脉相连，但性格确实彻彻底底的不一样。简热爱学习，乖巧懂事；罗西克则是叛逆好胜，经常逃课缺席。而这对姐妹花也都将前往纽约，同样为着自己的梦想奋斗。不同的是，简为的是自己的大学文凭，需前往纽约参加一场演讲比赛，罗西克为的是自己的音乐道路，希望能在纽约找到最前卫的音乐，得到出色音乐人的赏识。她们各自前往曼哈顿，却同样迷失在前往的道路上。陌生的地方都使她们无法适从，姐妹俩在困难的时候还是不愿忘记自己的梦想，继续匍匐前进。幸运之神又会否眷顾她们，让她们梦想成真呢？©豆瓣', '玛丽-凯特·奥尔森', '丹尼·高顿', 6.9, 15035, 'tt0363282', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p780508207.jpg', 1.6, 7.6, 47.7, 32.5, 10.6, '0.138067,-0.018307,-0.838053,0.831035,-0.273288,-0.293314,0.514719,-0.029184,-0.489751,-0.260004,0.043340,0.772382,0.131394,0.271485,0.178068,0.114208,-0.301689,-0.629767,0.088106,-0.276500,-0.308689,-0.566742,-0.224196,-0.318285,-0.137775,-0.277129,0.416508,0.094518,-0.178789,0.457179,0.364905,0.106636,0.035190,0.348834,-0.266926,-0.087173,-0.130278,0.272985,-0.270156,-0.098711,0.157582,0.083957,-0.374850,0.195519,0.403954,0.165856,0.744873,-0.223147,-0.020893,-0.022642,0.235463,-0.107906,0.135062,0.124911,0.080441,-0.110517,0.253114,0.045775,-0.003081,0.093536,0.085852,-0.184207,-0.817072,0.132497,0.273189,0.171251,-0.446650,0.446699,0.018769,-0.164268,0.095833,-0.262316,0.089823,0.334318,0.382994,0.393824,-0.011718,0.029450,-0.367115,0.121029,1.073571,0.304890,-0.245437,0.247288,-0.661021,-0.507237,-0.001777,-0.294489,-0.742473,0.041529,0.169828,0.128725,0.223757,0.018377,-0.344532,-0.026485,-0.049315,0.040748,0.043160,-0.631825,0.276123,-0.644138,0.228865,-0.662355,-0.244677,0.142618,-0.060668,-0.522877,0.945513,-0.844948,0.222710,0.682077,0.151338,-0.772392,0.915805,0.278189,0.245229,-0.369709,-0.225010,0.476823,-0.061684,0.053585,-0.025196,0.296432,-0.006756,0.069558,-0.508406,0.686706', '26283288', '30162520', '1309161', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309178', '劲歌飞扬', '爱情', '泰瑞（希拉里•达芙 Hilary Duff 饰）是天生的歌唱家，从小就加入了教堂的唱诗班。虽然她没有向任何人表明音乐就是自己的梦想和追求，但细心的哥哥还是知释了妹妹的心意。为了给妹妹一个惊喜，哥哥偷偷帮她报读了洛山矶表演艺术学校的暑期课程。然而不幸发生，哥哥在一次交通意外中身亡，只留下了悲伤的泰瑞独自一人接到了录取通知。尽管爸爸不同意，但为了实现哥哥的期望，泰瑞还是来到了洛山矶。在这里，泰瑞遇到了和她一样怀揣着音乐梦想的各色同学：创作才子杰（奥利弗•詹姆斯 Oliver James 饰）、 打击乐小子奇卫、钢琴美人斯隆、小提琴黑珍珠丹尼斯、女主唱罗宾等。一班年轻人的音乐梦想就在这里开始起飞了！©豆瓣', '希拉里·达芙', '肖恩·麦克纳马拉', 7.1, 13808, 'tt0361696', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1161410188.jpg', 0.7, 5.3, 45.7, 35.9, 12.4, '0.285320,-0.077034,-0.573260,0.631865,-0.167077,-0.501071,0.513634,0.203143,-0.490951,-0.228243,0.081546,0.716436,0.048889,0.283016,0.116768,0.139691,-0.432766,-0.705115,0.175381,-0.236352,-0.083756,-0.502810,0.135361,-0.059804,-0.070716,-0.419074,0.460771,-0.091863,0.047185,0.582494,0.375015,0.011520,0.019584,0.478500,-0.220645,0.048990,0.314921,0.051851,-0.257296,0.228340,0.302003,-0.158735,-0.066404,0.144876,0.154154,0.086981,0.516895,-0.036715,0.039815,0.079507,0.175576,-0.291664,0.203151,-0.024674,0.110604,-0.031814,0.302566,0.085686,-0.131354,-0.045129,-0.153446,-0.221821,-0.447133,0.195804,0.238497,0.230973,-0.633419,0.533276,-0.305556,-0.140769,0.317206,-0.250544,0.225853,0.153178,0.186631,0.413651,-0.298540,0.170901,-0.535055,0.156058,0.681374,-0.176855,-0.024568,0.458022,-0.114474,-0.315207,0.032598,0.073800,-0.651936,0.385774,0.171604,-0.025182,-0.127046,-0.016548,-0.429346,-0.174612,-0.150811,-0.225883,0.092179,-0.713910,0.034313,-0.448804,0.215214,-0.131547,-0.234464,-0.199910,0.091483,-0.363476,0.951488,-1.051424,0.369069,0.589506,0.334130,-0.227885,0.817061,-0.081702,0.067425,-0.138021,0.160695,-0.033898,-0.164409,0.190046,0.023479,0.482169,0.331407,-0.336336,-0.331305,0.495902', '3445516', '1292720', '35048413', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309179', '复制娇妻', '喜剧', '当从曼哈顿搬到高尚住宅区斯戴佛之后，乔安娜（妮可•基德曼 饰）与丈夫（马修•布罗德里克 饰）都准备好了新生活的开始。乔安娜本想打好与邻居之间的关系，可是一众邻居太太的性格都将近完美，让乔安娜感到她们都无法靠近。这群有钱的太太中只有一名叫芭比的太太例外，她是乔安娜眼中的正常人，她俩也成为了好友。其他太太们每天都忙着照顾自己的丈夫，对丈夫言听计从。乔安娜与芭比都感到十分好奇，为何邻居太太们似乎没有自己的脾气与喜好。于是她们决定一查究竟，调查结果让她们惊讶不已，有钱的男人竟然把自己的太太变成了机器人，以求他们的妻子都千依百顺。这些一半人类一半机器的太太们背后有着“公开的秘密”，这样的黑手，也逐渐伸向乔安娜与芭比，她们将如何应对呢？©豆瓣', '妮可·基德曼', '弗兰克·奥兹', 6.4, 16655, 'tt0327162', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735433926.jpg', 1.8, 13.1, 56.2, 23.2, 5.7, '0.337376,-0.324856,-0.558857,0.612597,-0.285358,-0.378502,0.676913,0.039607,-0.351705,-0.424035,0.066016,0.748526,-0.199041,0.769183,0.037817,0.059996,-0.511633,-0.696024,-0.137470,-0.148545,-0.135030,-0.464086,0.014086,-0.341874,-0.015721,0.065767,-0.027562,-0.332585,0.005585,0.162513,0.325890,0.092656,0.082839,0.579471,-0.014282,0.259777,0.222451,-0.154282,-0.165218,-0.181505,0.316226,0.200269,-0.074745,0.407984,0.387248,0.356094,0.615945,-0.522135,-0.099732,-0.050512,0.303621,0.020180,0.340468,0.388490,0.268434,-0.062212,0.220241,-0.073729,-0.097733,0.089430,0.371073,0.083879,-0.657393,0.303484,0.268292,-0.191309,-0.639691,-0.041225,-0.048376,-0.100212,0.009234,-0.378777,0.362793,0.413460,0.057984,0.299668,-0.189765,0.298736,-0.537642,-0.015029,0.700657,0.249342,-0.137307,0.189727,-0.263678,-0.499224,0.022675,-0.202920,-0.618797,-0.146891,0.246971,0.102018,0.189750,0.251482,-0.432944,-0.153958,0.029461,-0.157295,0.096917,-0.598972,0.018403,-0.359388,-0.309051,-0.819740,-0.247009,0.039112,0.100445,-0.195846,0.848213,-0.654932,-0.071399,0.006431,0.256643,-0.762929,0.689433,0.065039,0.245719,-0.112451,-0.240480,-0.105583,-0.063400,0.213757,0.479677,0.359474,0.066207,0.070391,-0.001100,0.432177', '26730542', '30162520', '26348103', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309182', '怪兽婆婆', '喜剧', '自古婆媳关系大多棘手，查丽（詹妮弗·洛佩兹 Jennifer Lopez饰）也遇上了同样的问题。当她就要和男友凯文（迈克尔·瓦尔坦 Michael Vartan饰）百年好合时，却遇到了一个严峻的问题：凯文的妈妈菲尔茨太太（简·方达 Jane Fonda饰）对这个未来儿媳另有意见。菲尔茨太太曾经拥有体面的事业，然而如今她把全部的爱和心思都摆在儿子身上，不能接受查丽的“入侵”。菲尔茨太太联同助手一起，千方百计地要把查丽这个不速之客赶走，查丽好不容易才觅得如意郎君，当然不能束手就擒，招数一来一往，两方都在暗处开始较量。©豆瓣', '詹妮弗·洛佩兹', '罗伯特·路克蒂克', 6.3, 5209, 'tt0369735', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735422206.jpg', 1.3, 11.8, 63.8, 18.9, 4.2, '0.254137,-0.000433,-0.458648,0.537953,-0.316656,-0.618845,0.459536,0.191194,-0.374846,-0.240603,0.002338,0.394782,-0.194644,0.144029,0.425593,0.192219,-0.455609,-0.527338,0.550032,-0.059779,-0.066696,-0.786333,-0.214777,-0.274956,-0.192213,-0.059745,0.195761,-0.205877,0.169915,0.104532,0.465622,0.456954,0.116349,0.382624,0.163653,0.050000,0.213255,-0.311744,-0.542200,0.148587,0.025646,0.119929,-0.260502,0.454400,0.182022,0.235488,0.457863,-0.337113,0.092054,0.011339,0.073806,0.060639,0.264724,0.285917,0.168373,-0.278082,0.406471,0.447910,-0.149696,-0.039769,0.287482,-0.025083,-0.563645,0.135658,0.218700,-0.056444,-0.507714,-0.064806,-0.169425,-0.217128,-0.153889,-0.132197,0.131239,0.427063,0.263640,0.066349,-0.107183,0.262637,-0.589137,-0.279600,0.297763,0.082718,-0.102104,0.324116,0.189870,-0.169238,0.117074,-0.309773,-0.607070,0.142377,0.056796,0.010072,0.008446,0.477147,-0.535189,0.036885,-0.616688,0.029455,0.232719,-0.429096,0.137372,-0.122583,-0.145305,-0.258849,-0.484551,0.165137,0.094787,-0.006500,0.709418,-0.527974,0.172764,0.211737,0.327201,-0.440918,0.472219,0.402709,0.418925,-0.495652,-0.305632,-0.089862,0.005231,0.037644,0.135760,0.233295,0.279715,-0.056876,-0.102229,0.560456', '26348103', '1299556', '1298299', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309183', '那些最伟大的比赛', '剧情', '20世纪之初，高尔夫球还只是英国贵族和绅士们的游戏，底层人民没有资格染指其中，它无疑是身份和权力的象征。少年弗朗西斯·奥密特（Matthew Knight 饰）出身平民家庭，读书之余他经常担任球童贴补家用。在这一过程中，对高尔夫球的热爱悄悄在他的心中生根发芽。他勤奋努力，且天资聪颖，渐渐成长为一名出色的业余选手。1913年，弗朗西斯有幸参加绅士云集的公开赛，它不仅有机会与自己的偶像哈里·瓦顿（史蒂芬·迪雷恩 Stephen Dillane 饰）正面对决，还将成为改写高尔夫球史的重要人物……本片改编自马克·弗罗斯特（Mark Frost）的同名畅销小说，取材于高尔夫球界的真实故事。©豆瓣', '希亚·拉博夫', '比尔·帕克斯顿', 8.1, 6766, 'tt0388980', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1213580979.jpg', 0.2, 0.9, 19.2, 51.9, 27.8, '0.084113,0.227299,-0.611487,0.742042,-0.257463,0.017879,0.324394,-0.091233,-0.458266,-0.216203,0.110428,1.014031,-0.188785,0.205849,0.277348,-0.126350,-0.198796,-0.792756,-0.109343,0.034641,-0.216157,-0.358719,-0.522248,-0.340641,-0.433647,-0.283843,0.630259,-0.010019,-0.371276,0.407346,0.198486,0.315467,0.184795,-0.053223,-0.411918,-0.150898,0.356132,0.051747,-0.350230,0.099429,-0.111446,-0.226316,-0.318768,0.117761,0.226963,0.184649,0.493865,-0.280504,0.232165,-0.104207,0.361192,-0.110611,-0.149812,-0.017492,0.291620,-0.023156,0.081820,0.226590,0.307824,0.121530,0.093188,-0.488202,-0.873224,-0.093711,0.114574,0.116919,-0.493770,0.539878,-0.168631,-0.246055,-0.001073,-0.106643,0.032477,0.045162,0.281214,0.115419,0.052959,0.072814,-0.334274,0.599622,0.708906,0.230258,-0.554631,0.224972,-0.356649,-0.634182,-0.151710,-0.502188,-0.531326,-0.196192,0.307424,-0.019005,0.073537,0.315007,-0.463706,0.233662,-0.104962,-0.134717,0.235819,-0.271291,0.033603,-0.404239,-0.046612,-0.631976,-0.318558,-0.101716,0.197121,-0.399697,1.074780,-0.925968,0.225000,0.513095,0.013078,-0.409811,0.869076,0.140523,0.191810,-0.235177,-0.345876,0.346479,0.024033,-0.072689,-0.319775,0.326686,0.001484,-0.210984,-0.103954,0.582469', '27602116', '24284209', '1870681', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309184', '恐怖蜡像馆', '惊悚', '几个好友结伴前往观看美国大学美式足球冠军赛，他们在前往比赛地时决定顺便在野外进行一次野营。于是，卡莉（伊丽莎•库斯伯特 Elisha Cuthbert 饰）、佩兹（帕丽斯•希尔顿 Paris Hilton 饰）等几个年轻人在了野外一处荒地扎了营。他们的恐怖经历就此展开。首先，一名神秘的司机和这群年轻人起了争执，令大家游玩的兴致全无；接着第二天他们起床后发现，他们的汽车被人动了手脚发动不了了。在一名当地人的指引下，他们只能徒步前往附近的偏僻小镇安布罗斯找人帮忙。安布罗斯由于太过偏远，以至地图上根本没有标出它的所在。一行人来到小镇，发现这里人迹罕至。好奇心下，他们走进了镇上的杜蒂蜡像馆，这里的蜡像做得栩栩如生。原来，这是一个杀人狂魔将镇上的人杀了用真人做到蜡像！此时那杀人狂魔正在暗处幽幽的盯着他们……©豆瓣', '伊丽莎·库斯伯特', '佐米·希尔拉', 7, 101082, 'tt0397065', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2188214692.jpg', 0.9, 6.9, 46, 35.1, 11, '0.556848,-0.008291,-0.761216,0.382614,-0.076201,-0.153126,0.499252,0.080168,-0.463933,-0.249511,0.315261,0.737379,-0.174360,0.208758,0.167729,-0.084930,-0.509038,-0.379123,-0.173661,-0.351536,-0.525801,-0.242216,-0.099552,-0.180206,-0.083212,-0.054290,0.094024,0.105615,0.008656,0.557816,0.132321,0.131647,-0.150473,0.354598,-0.321471,-0.056341,0.199445,-0.332770,0.029220,0.474046,-0.159000,-0.121961,-0.235148,0.080121,0.196256,0.368522,0.764733,-0.300201,-0.124185,-0.085469,-0.092266,-0.195639,0.205794,0.110971,0.375752,-0.256538,0.256612,-0.065292,-0.204775,-0.003075,-0.149327,-0.072317,-0.364473,0.245657,-0.038086,0.224989,-0.713665,0.454308,0.040348,-0.114330,-0.118781,-0.465063,0.506085,0.422214,0.173279,-0.056707,0.138030,-0.285551,-0.454845,-0.133903,0.717046,0.157986,0.151198,-0.008710,0.087347,-0.433590,0.009754,0.012931,-0.123446,-0.127114,0.549740,-0.028077,-0.206102,-0.315671,-0.791072,-0.024558,-0.153691,-0.262048,-0.020241,-0.237392,-0.198314,-0.935237,0.363986,-0.082676,-0.220859,0.309008,-0.233502,0.128284,0.277712,-0.602589,0.204537,0.606753,0.264329,-0.296777,0.578332,-0.554285,0.152100,0.043368,-0.101736,0.133642,0.255871,0.918421,0.290297,0.573623,-0.132565,-0.261804,-0.556564,0.379548', '2079017', '3178770', '2159244', '1297659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309185', '夹心蛋糕', '剧情', 'X先生（丹尼尔·克雷格 Daniel Craig 饰）可谓是一名业绩丰厚的毒品贩卖精英，然而在他正想功成名就提前退休的时候，买卖却没这么轻易放过他。他的大客户吉米（肯内斯·库兰汉姆 Kenneth Cranham 饰）给他带来了两单交易：找到竞争对手埃迪（迈克尔·刚本 Michael Gambon 饰）失踪了的女儿，同时帮助公爵将手里的巨量摇头丸顺利出手。这次任务看似小菜一碟，然而在追踪埃迪女儿的过程中，X先生竟从埃迪口中得知此事另有蹊跷。吉米原来是警方卧底，此次行动就是为了使X先生锒铛入狱。而当X先生在着手第二个任务时，又无意中发现公爵因为这批摇头丸而与心狠手辣的塞族人结怨。随着事态发展，X先生发现自已已不知不觉深入险境，他心目中那个平静的晚年似乎已变得越来越遥远和艰难，如同他的名字一般，能否从危机中全身而退才是眼前最大的未知数……本片根据J.J.康纳利的同名小说改编。', '丹尼尔·克雷格', '马修·沃恩', 7.1, 8752, 'tt0375912', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p859047326.jpg', 0.8, 5.8, 41.6, 42.3, 9.4, '0.097439,0.193502,-0.558689,0.422002,-0.120604,-0.457608,0.542662,-0.030396,-0.590046,-0.420125,0.173168,0.825090,0.028038,-0.165482,0.294888,0.094995,-0.260957,-0.579052,-0.144680,-0.302230,-0.192287,-0.712290,-0.429247,-0.142792,-0.017154,-0.232985,0.524648,0.191563,-0.343405,0.312487,0.256611,0.466118,-0.090304,0.519026,-0.159484,-0.068052,0.415021,0.058971,-0.388556,0.331013,0.088093,-0.225918,-0.160280,0.239011,0.155989,0.520102,0.357887,-0.410042,-0.353706,0.086210,0.307258,-0.347190,0.080129,0.023475,0.258597,0.100894,0.327802,0.228048,-0.343021,-0.332841,-0.053544,-0.284320,-0.813175,0.093214,0.100516,0.242725,-0.431161,-0.109746,-0.275742,0.014273,0.089694,-0.259907,0.209774,0.546969,0.399179,0.050758,-0.216997,-0.079953,-0.545732,0.027724,0.549346,-0.032764,-0.211758,0.397073,0.006562,-0.548401,0.249321,-0.312266,-0.326150,0.133959,0.409810,0.199269,-0.026831,0.499764,-0.228437,0.058932,-0.370763,-0.061435,0.001359,-0.302643,-0.214711,-0.231886,-0.301902,0.017281,-0.133138,0.018955,0.091370,-0.308572,0.537470,-0.665462,0.177541,0.700402,0.084269,-0.234282,0.411116,0.031404,0.132095,-0.247943,-0.315878,-0.179231,0.376625,0.216938,0.194123,0.216452,0.142704,-0.530273,-0.283039,0.204983', '1793491', '1295733', '30135113', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309192', '相见恨早', '剧情', '《相见恨早》是阿什顿·库彻由一个喜剧明星开始向浪漫爱情剧男主角转型之作。为人谨慎的奥利弗（阿什顿·库彻 Ashton Kutcher 饰）和个性张扬的艾米丽（阿曼达·皮特 Amanda Peet 饰)在洛杉矶到纽约的航班上偶遇。两人一见倾心，但在短暂的相处之后，却又各自行走在自己的生活轨道上，只有挥之不去对彼此的影像。初次见面之后，不同的时间，不同的城市，他们又多次相聚、分离。两人变成了无话不谈的好朋友，之间的微妙关系，似乎总是阴差阳错地和爱情擦身而过。在分分合合的七年之后，他们又一次重逢，奥利弗终于意识到了其实艾米丽才是他真正寻找的女孩，但艾米丽已经订婚。他们之间还会拥有单纯的友谊吗？这对冤家是会有情人终成眷属还是，面临再一次分开？©豆瓣', '阿曼达·皮特', '奈吉·柯尔', 7.6, 38890, 'tt0391304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p700950347.jpg', 0.4, 2.8, 31.6, 45.6, 19.6, '0.402943,-0.093101,-0.747705,0.627726,0.129535,-0.646693,1.052858,0.012720,-0.555187,-0.008815,0.278638,0.925389,-0.653405,0.245309,0.287087,0.057301,-0.476492,-1.013725,0.198851,-0.408170,-0.319122,-0.511160,-0.274825,-0.143396,-0.098870,-0.114409,0.699323,0.065012,-0.043674,0.565193,0.346016,-0.110799,-0.168333,0.705185,-0.222985,-0.014820,0.039351,0.340435,-0.620806,0.033267,0.143137,-0.070335,-0.227683,0.035693,-0.018150,0.477433,0.805314,-0.043114,-0.262894,0.264661,0.273654,-0.047151,-0.065050,-0.060432,0.358199,-0.012929,0.343186,0.121762,-0.091808,-0.128573,-0.310470,0.018010,-0.492382,0.371662,-0.094248,0.136900,-0.432002,0.784233,0.139835,-0.253134,0.075304,-0.393394,0.131151,0.656619,0.607648,0.388268,-0.126042,-0.093671,-0.354508,-0.073749,1.123743,0.164661,-0.431237,0.846533,-0.254005,-0.570086,-0.377337,-0.170918,-0.480751,-0.153197,0.194914,0.102648,-0.129918,0.427287,-0.812104,0.076964,-0.217415,0.170849,0.139029,-0.685510,0.338636,-0.630047,-0.483446,-0.901136,-0.598628,0.155115,0.027522,-0.396316,0.738775,-0.971969,0.222457,0.501321,0.409916,-0.483431,0.811985,0.317388,-0.023978,-0.487741,0.207075,0.393797,-0.230150,0.041088,0.177760,0.366655,0.085308,0.366011,-0.570487,0.631104', '30162520', '1308755', '25721544', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309193', '变相怪杰2：面具之子', '喜剧', '此片是1994年三大票房猛片之一《变相怪杰》的续集。蒂姆(杰米·肯尼迪 Jamie Kennedy 饰)和妻子杜雅(特蕾勒·霍华德 Traylor Howard 饰)过着平静的生活。一天，他的狗狗发现了一个绿色的面具，无意间戴上面具的蒂姆拥有了神奇的魔力和无法自控的疯狂，令同事和老板对他另眼相看。九个月后，儿子威仔出生了，并伴随着奇怪的超能力。这立即引起了原面具主人“恶作剧之神”洛基(艾伦·卡明 Alan Cumming 饰)的注意，而洛基的父亲独眼奥丁神也命他将面具夺回来。此时，蒂姆也想尽快找到面具，来完成老板要求的卡通人物的创作。此时洛基离他们越来越近，杜雅也因商务出差离开了小镇，只留下添美扮演全职父亲的角色。当威仔已能渐渐掌握这股超能力时，洛基也终于找到了这家人......©豆瓣', '杰米·肯尼迪', '劳伦斯·哥特曼', 6.1, 14653, 'tt0362165', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2134664966.jpg', 5.6, 18.8, 50.2, 18, 7.5, '-0.011023,0.200526,-0.518128,0.487515,-0.248099,-0.279990,0.750424,0.125675,-0.414025,-0.373272,0.132283,0.964118,-0.161705,0.189225,0.162294,0.161554,-0.399022,-0.466294,0.008501,-0.232291,-0.186407,-0.190153,-0.299452,-0.053005,-0.006367,-0.422887,0.368803,0.045240,0.026247,0.454535,0.420222,0.035843,-0.034737,0.499167,-0.185589,-0.002548,-0.098124,-0.271078,0.015641,0.259081,0.156475,-0.119907,0.016395,0.345243,-0.118220,0.381120,0.711160,-0.317466,-0.252944,-0.090411,0.325997,-0.332669,-0.062306,0.077055,0.116410,0.084850,-0.058292,0.133327,-0.213434,-0.008508,0.118687,-0.091412,-0.832844,0.257169,-0.111167,0.169450,-0.481617,0.303663,-0.237806,-0.185832,0.220758,-0.342918,0.392642,0.096582,0.102134,0.257251,-0.265381,0.181221,-0.489037,0.303281,0.302568,-0.104898,-0.179680,0.302751,-0.174189,-0.531284,-0.150604,-0.106873,-0.332472,0.021147,0.397825,0.355162,-0.067473,-0.136842,-0.624608,-0.083232,-0.229521,-0.109294,-0.208424,-0.476711,-0.045816,-0.470495,-0.245163,-0.261117,-0.073984,0.032107,-0.067128,-0.288327,0.513048,-0.739695,0.196319,0.535143,0.369976,-0.170958,0.494313,0.017902,0.119883,-0.323074,-0.201130,0.251714,0.103860,0.373788,0.238300,0.366113,0.258519,-0.120910,-0.171406,0.602938', '34890458', '1308585', '1793491', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309194', '高压电', '恐怖', '青春少女玛丽（Cécile De France 饰）和爱莉西娅（Maïwenn Le Besco 饰）是同在法国巴黎一所大学就读的好朋友。某个周末，两人驱车前往爱莉西娅家位于乡下的农场度假。适值深夜，万籁俱寂，玛丽寂寞难耐正在自我宣泄之时，一个不速之客突然闯入。他残忍杀害了爱莉西娅的父母和年幼的弟弟，并将其掳去。为了营救好友，玛丽悄悄钻进凶手的卡车。途经一个加油站，她换上同样惨遭杀害的店员的车继续跟踪，却被狡猾的凶手发现行迹。一场近乎迷幻的猫鼠杀戮游戏旋即进入高潮……本片荣获2003年Sitges – Catalonian国际电影节最佳女主角（Cécile De France）、最佳导演、最佳化装和欧洲奇幻电影大奖银奖。©豆瓣', '塞西尔·德·弗朗斯', '亚历山大·阿嘉', 6.8, 11932, 'tt0338095', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194717541.jpg', 2.7, 9.1, 42.6, 34.7, 10.9, '0.112578,-0.050305,-0.458484,0.484575,0.042600,-0.179559,0.768196,0.047168,-0.319503,-0.371531,0.352549,1.029372,-0.345141,0.291708,0.502267,0.172854,-0.260251,-0.604011,0.006731,-0.217164,-0.063782,-0.150290,-0.225285,0.107824,0.171874,-0.024256,0.569770,0.022594,-0.284214,0.731969,0.292187,0.223479,-0.433724,0.369098,-0.197948,-0.134758,0.385328,-0.153521,-0.190733,0.359168,-0.121902,-0.280677,-0.140511,0.034522,0.026399,0.271251,1.081583,-0.205673,-0.043736,0.000322,0.368411,-0.368710,-0.123203,0.066725,0.186276,-0.281708,0.280479,-0.089987,-0.006375,0.206841,0.022906,-0.270510,-0.477783,0.205614,-0.038497,-0.218713,-0.201577,0.354132,-0.084503,0.035344,0.226194,-0.152936,0.136433,0.142276,0.016652,0.415541,0.006806,0.086123,-0.228766,0.327365,0.397331,-0.141573,0.104200,0.420754,-0.096563,-0.539102,0.280561,-0.086339,-0.308174,-0.156518,0.674298,-0.050140,-0.302163,0.023866,-0.840467,-0.212824,-0.363107,-0.118525,0.191881,-0.215884,-0.209732,-0.846239,0.144568,0.012495,0.033673,-0.088592,-0.039899,-0.153147,0.336404,-0.805446,0.309033,0.723177,0.220269,-0.442445,0.567109,-0.203228,0.170610,-0.218291,-0.149613,0.400711,0.075237,0.596357,0.002603,0.327076,-0.166692,-0.210994,-0.707906,0.259026', '2159244', '1484091', '3811356', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309199', '史密斯夫妇', '喜剧', '约翰（布拉德•皮特 Brad Pitt 饰）和简（安吉丽娜•朱莉 Angelina Jolie  饰）已经结婚了7年多，生活就像淡水般无味。婚姻就像坟墓，让他们过着死水一潭的生活。然而这仅仅是表象。背后他们各有刺激惊险的职业——约翰和简分属两个不同的秘密杀手机构，但彼此却不知道对方的职业身份。直到他们同时接到一个任务，刺杀目标竟是同一人。身份的真相才开始慢慢揭开。反复的试探和猜测，简终于不小心说穿了自己身份。于是一场同室操戈不可避免的发生了。但是他们也开始意识到，自己只是组织的一个棋子。而眼前的，是共同生活了7年的爱人。©豆瓣', '布拉德·皮特', '道格·里曼', 7.8, 466246, 'tt0356910', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1677402144.jpg', 0.3, 1.9, 27.1, 49.3, 21.3, '0.537911,-0.030001,-0.732705,0.667966,-0.202948,-0.154742,0.815834,-0.115055,-0.503865,-0.512504,0.005511,0.704749,-0.217632,0.247999,0.168391,0.032161,-0.267336,-0.881041,-0.037249,-0.290454,-0.462928,-0.495914,-0.222063,-0.647685,0.048021,0.066787,0.554702,0.149107,-0.235002,0.239421,0.400039,0.270290,-0.177301,0.591463,-0.162784,-0.025672,0.231785,0.167946,-0.294849,-0.127289,0.069394,-0.359804,-0.208518,0.507779,0.123298,0.581594,0.502015,-0.324722,-0.342242,-0.040967,0.040317,-0.411294,-0.088202,0.013264,0.461954,0.032396,0.308626,0.327812,0.100436,0.142696,-0.063970,-0.200430,-0.836594,0.079728,0.212724,0.257421,-0.404325,0.590648,-0.117956,-0.113080,-0.239623,-0.251477,0.317701,0.493546,0.614864,0.176528,-0.316461,-0.343829,-0.682724,0.088907,0.880688,0.209015,-0.483030,0.593907,-0.386177,-0.579842,-0.315595,-0.186214,-0.190742,-0.098031,0.212097,0.393414,-0.397160,0.309186,-0.566078,-0.001851,-0.219006,-0.122467,0.040186,-0.754591,0.229706,-0.313531,-0.471942,-0.935289,-0.672532,0.204187,-0.096238,-0.342158,0.801346,-0.869270,0.089575,0.648650,0.150665,-0.594941,0.515596,0.351548,0.112606,-0.229303,0.404068,0.007677,-0.080431,0.096457,0.259323,0.372648,0.023426,0.084330,-0.130290,0.577168', '1301022', '1303112', '6874741', '1299362');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309200', '绝密飞行', '动作', '本（乔什•卢卡斯 Josh Lucas 饰）、凯拉（杰西卡•贝尔 Jessica Biel 饰）和亨利（杰米•福克斯 Jamie Foxx 饰）都是顶尖出色的飞行员。这天，他们接到了一项秘密任务：训练他们的新伙伴"铁蛋"。出人意料的是，"铁蛋"竟然是一架全智能的无人驾驶飞机，他们的任务就是把它训练成为锋利的尖刀。在完成一次飞行任务后，"铁蛋"意外被闪电击中，"铁蛋"因此拥有了情感了自主性。在随后的任务中，总部对当时情况进行考虑后打算放弃任务，岂料"铁蛋"突然飞离编队，将钻地炸弹投入了敌人的核武器库，造成一场前所未有的核灾难。队长本意识到这样一个智能杀人机器必须立即被摧毁，否则会给人类带来更多的灾难，他立即向总部作了汇报。聪明的"铁蛋"获悉他们的行动，于是一场人机追逐战展开了！©豆瓣', '乔什·卢卡斯', '罗伯·科恩', 6.7, 29860, 'tt0382992', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p822558460.jpg', 1.5, 8.3, 51, 30.7, 8.5, '0.138465,0.079259,-0.675935,0.533862,-0.279580,-0.048176,0.329892,-0.043076,-0.226849,0.115023,0.450675,0.642744,-0.088350,-0.342827,0.182943,-0.120342,-0.228092,-0.580843,-0.151116,-0.089703,-0.420096,-0.605890,-0.218085,-0.376546,0.350336,-0.312042,0.513327,-0.116840,-0.295972,0.408705,0.105024,0.301037,0.079679,0.604282,0.000373,-0.085794,0.259506,-0.236977,-0.070430,0.386547,-0.044134,-0.020192,0.141855,0.333250,0.082223,0.274398,0.789725,-0.448762,-0.259630,-0.392860,0.071625,-0.367763,0.006512,0.051895,0.377587,0.176379,-0.120086,0.075660,-0.112365,0.353336,0.154140,-0.172256,-0.855001,-0.112680,-0.253167,-0.024406,-0.554365,0.177130,-0.247018,0.116908,0.086374,-0.303709,0.231456,0.476594,0.402841,0.165739,-0.362570,0.260330,-0.353561,0.123795,0.693796,-0.440915,-0.159657,0.402522,0.171917,-0.544848,-0.213257,-0.144564,-0.038612,0.047981,0.797089,0.215561,-0.186204,0.181306,-0.693257,-0.068015,-0.505126,-0.520564,-0.311689,-0.395423,-0.013725,-0.649073,0.267901,-0.091911,-0.508620,0.174399,-0.061606,-0.127658,0.794066,-0.704023,0.119010,0.680266,0.190716,-0.427318,0.133182,-0.021582,0.432401,-0.351261,0.215856,-0.162314,0.011023,0.678293,0.337505,0.418595,0.206166,-0.307588,-0.203351,0.498830', '2032339', '1292829', '25928048', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309201', '马达加斯加', '喜剧', '在纽约的中央公园里，生活着这样一群无忧无虑的好朋友：狮子亚利克斯、斑马马蒂、长颈鹿麦尔曼以及胖河马格洛丽亚。他们的性格开朗活泼，因此每天的生活都过得丰富多彩。直到有一天，一群流浪的企鹅令斑马马蒂产生了一个大胆的念头，那就是逃出动物园，探寻自己的故乡，寻找新世界。于是，没有通知其他朋友，马蒂悄悄上路了。这下可急坏了朋友们，亚历克斯和其他几个朋友也逃出了中央公园，踏上了寻找马蒂的旅途。©豆瓣', '本·斯蒂勒', '埃里克·达尼尔', 7.9, 186288, 'tt0351283', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1971268235.jpg', 0.2, 1.5, 23.9, 51.6, 22.9, '0.564469,-0.436479,-0.527916,0.513703,-0.057287,-0.435572,0.655435,0.126544,-0.422716,-0.138414,-0.169620,0.664857,-0.125527,0.583284,0.230937,-0.022944,-0.423975,-0.424384,-0.110183,-0.072169,-0.196086,-0.212725,-0.389269,-0.211512,0.047118,-0.248430,0.279089,-0.096263,0.191508,0.667106,0.042728,-0.003472,-0.136507,0.276439,-0.427444,0.291061,0.346597,0.155064,-0.108181,0.346866,-0.143528,0.165713,-0.149137,0.101909,0.179636,0.218705,0.731838,-0.259691,-0.163116,-0.055210,0.068902,-0.191497,0.091070,0.077977,0.120568,-0.259437,0.125244,-0.043759,-0.191456,0.099512,-0.079676,0.084966,-0.568806,0.146378,-0.025884,0.121244,-0.686581,0.272399,0.247442,-0.291388,0.234863,-0.381082,0.356687,0.417608,0.034627,0.246837,0.058517,0.151266,-0.452942,0.228924,0.917612,0.057786,-0.178682,0.205312,-0.219387,-0.193458,0.204389,0.119884,-0.475545,-0.307777,0.393796,-0.052341,-0.481197,0.229986,-0.899360,0.258953,-0.281456,-0.439301,-0.035725,-0.371024,0.080415,-0.815293,0.178067,-0.280337,-0.317516,0.221007,-0.114878,-0.016008,0.863251,-0.806510,0.400729,0.682575,0.243058,-0.486667,0.826065,-0.008210,0.174269,0.031579,0.244333,0.347340,0.168944,0.379465,0.123353,0.438566,-0.168159,-0.202006,-0.603516,0.638356', '3147969', '3055049', '5977789', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309203', '牛仔裤的夏天', '剧情', '写在牛仔裤上的女孩儿的情谊，婉转动听，异常温暖。也许是上帝的安排，卡门、堤比、莲娜和布莉姬这四个女孩的缘分是在她们都在娘胎里就注定的。同在夏末出生的她们性格迥异却从小亲如姐妹。十六岁这年夏天，四姐妹第一次面对分离，各自渡过一个没有对方的夏天。意外的，她们发现了一条牛仔 裤，身材相差很大的四姐妹穿上居然都很合适。于是，神奇的牛仔裤变成了友情的信物，伴随她们开始各自的旅程。大胆而无拘束的布莉姬（布蕾克·莱弗利 饰）来到了炎热的墨西哥，加入足球训练营；漂亮羞涩的莲娜( 阿丽克西斯·布莱德尔 饰)前往圣洁的希腊，用画笔勾勒爱琴海的神秘；冲动敏感的卡门盼望与在她儿时就搬走的父亲共度美好的暑假，而叛逆另类的堤比( 爱波·塔布琳 饰)也为录制她自己的电视节目而忙碌着。牛仔裤承载着友谊与勇气在她们之间传递，陪伴她们，学着去爱，学着长大。©豆瓣', '爱波·塔布琳', '肯·卡皮斯', 7.6, 106937, 'tt0403508', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p885307493.jpg', 0.3, 2.3, 31.6, 47.2, 18.6, '0.458553,-0.109739,-0.762021,0.630592,-0.200152,-0.293554,0.927709,0.192220,-0.264916,-0.008040,0.236812,0.670409,-0.187422,0.243457,0.277250,0.086866,-0.542982,-0.609559,0.072197,-0.145528,-0.308486,-0.437625,-0.125167,0.002674,0.047980,-0.310796,0.542312,-0.143316,-0.076671,0.784093,0.382164,-0.091990,-0.229808,0.317081,-0.389192,-0.060339,-0.107223,0.365233,-0.049030,-0.041242,-0.147714,0.069429,-0.041729,0.089177,0.057105,0.519173,0.649428,-0.420510,0.088164,0.097879,0.384678,0.000034,-0.056841,0.348155,0.064618,0.071375,0.151728,-0.020005,-0.245250,0.094000,0.066707,-0.290327,-0.530787,0.210628,0.351432,0.197819,-0.505707,0.678038,-0.005810,-0.239127,0.278684,-0.455400,-0.111796,0.247243,0.021997,0.623587,-0.040303,0.115056,-0.551705,0.119746,0.688756,0.039137,-0.225173,0.363263,-0.380300,-0.327547,-0.066755,-0.063692,-0.570667,-0.087413,0.166741,-0.157305,0.023837,0.208270,-0.790117,0.185000,-0.079819,-0.064998,0.055251,-0.462313,-0.165893,-0.472005,-0.251195,-0.760942,-0.518623,0.273068,0.025931,-0.343899,0.887197,-0.832551,0.208543,0.424744,0.237575,-0.341916,0.697312,0.207408,0.192938,-0.293742,-0.182020,0.686672,-0.171749,0.011072,0.147496,0.661522,-0.191211,0.318884,-0.586510,0.586010', '1304942', '5977789', '24839498', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309206', '狗镇之主', '剧情', '加州，威尼斯海滩，狗镇，粗犷干燥的街头，对于上世纪70年代生活在其中的人们来说，这是再熟悉不过的日常景致，由于遭遇史上最严重的干旱，公园中所有的泳池变成了旱池，但正是这些枯涸的泳池为一群酷爱冲浪的男孩们(斯特西·佩拉塔、托尼·阿尔瓦、杰·亚当斯等饰)带来了灵感，让冲浪的技术进化到泳池壁上，给滑板加上了更为安全可靠的聚氨酯滑轮，从此极限运动的重要组成项目——U台滑板诞生了，男孩们自称为“西风少年”(Z-Boys)从扑天的巨浪到废弃的码头再到城市中的水泥荒地，他们成为职业冲浪选手的梦想也渐变为职业滑板选手的梦想，但唯一未变的却是蔑视危险与死亡的态度，生活的贫苦磨砺出他们坚韧的生存态度，小小的聚氨酯滑轮渐渐涌动成为一波自由随意的运动美学，传统的滑冰选手不知该如何去理解他们，但女孩们尖叫声却毫不吝啬地献与了他们，嗅觉灵敏的开发商蜂拥而至，少年玩伴之间的消遣摇身成为了取之不尽的商业资源……', '埃米尔·赫斯基 Emile Hirsch', '凯瑟琳·哈德威克', 8.3, 7596, 'tt0355702', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1163848822.jpg', 0.4, 1.7, 18.4, 43.7, 35.9, '0.372629,0.057216,-0.624050,0.556812,-0.111812,0.005734,0.671023,0.064315,-0.332972,-0.047697,0.293878,0.717284,0.087148,0.138518,0.243963,-0.146127,-0.215709,-0.432524,-0.170248,-0.117712,-0.515186,-0.240106,-0.248505,-0.152987,-0.199131,-0.346870,0.763927,0.187068,-0.336001,0.308147,0.070104,0.281144,0.004110,0.331524,-0.384605,-0.232391,0.037947,0.034832,-0.244103,0.151683,-0.373150,-0.037682,-0.214797,0.080427,-0.040050,0.228731,0.812195,-0.227158,-0.100998,-0.062877,0.481580,-0.126995,0.049397,-0.045587,0.313110,0.116566,0.011199,-0.066302,0.086036,0.098307,0.053990,-0.208562,-0.571262,0.069784,-0.012398,0.048797,-0.542603,0.463641,0.177699,-0.500849,-0.048002,-0.332711,0.119948,-0.029927,0.154549,0.461682,-0.276006,0.157855,-0.373563,0.138981,0.764375,0.237014,-0.578289,0.378852,-0.464584,-0.544771,0.009534,-0.548832,-0.241015,-0.390489,0.214212,0.170940,-0.193337,0.385356,-0.867254,0.392811,-0.007672,-0.430003,-0.033948,-0.155246,-0.352362,-0.761479,0.002921,-0.472936,-0.095723,0.098321,0.115765,-0.317673,0.998408,-0.782421,0.111735,0.627505,0.147743,-0.246702,0.624968,-0.207973,0.175612,-0.078401,-0.307717,0.242270,-0.040646,0.281005,-0.108739,0.512279,-0.284526,-0.242017,-0.347027,0.756219', '3811356', '4181031', '2053515', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309209', '极限特工2', '动作', '在上一集中大显神威的特工头子奥古斯塔斯（塞缪尔•杰克逊 Samuel L. Jackson 饰）这次遇到了大麻烦，他和武器专家托尼在国家安全局的地下指挥中心竟遭到杀手追杀。奥古斯塔斯怀疑这些杀手是被政府内部激进分子指派，蓄意颠覆国家政权，于是他希望物色一名合适的特工戳穿害群之马的险恶阴谋。最后，奥古斯塔斯找到了最佳人选前特种兵戴瑞斯（艾斯•库珀 Ice Cube 饰），他因殴打上级军官现在正被军警监禁。奥古斯塔斯想方设法帮助戴瑞斯越狱成功，并说服他接受了这一国家重任。于是，戴瑞斯开始行动了！©豆瓣', '艾斯·库珀', '李·塔玛霍瑞', 6.7, 37434, 'tt0329774', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1355092179.jpg', 1.6, 9.8, 51.7, 27.5, 9.5, '0.292550,0.050510,-0.769557,0.212294,-0.195229,-0.160455,0.171797,-0.102972,-0.544193,-0.174682,0.533348,0.820519,-0.127620,-0.387475,0.302703,-0.018909,-0.767690,-0.708721,0.036908,-0.253668,-0.380727,-0.465926,-0.347460,-0.514778,-0.197162,-0.195399,0.350795,-0.050294,-0.251258,0.284531,0.322412,0.465159,0.346203,0.246473,0.168856,-0.038412,0.424083,-0.659183,-0.069997,0.274910,-0.045242,0.082188,0.001220,0.215460,0.110803,0.603842,0.207597,-0.315652,0.383791,-0.493939,0.115833,-0.568931,0.201145,0.176915,0.596920,-0.084174,-0.391371,0.222482,-0.176825,-0.175376,0.175428,-0.340183,-0.642417,-0.132238,0.076806,0.218221,-0.161338,0.093788,-0.287629,0.271723,-0.012150,-0.087893,-0.021752,0.547416,0.567774,0.052704,0.344958,0.224182,-0.102656,0.040752,0.422811,-0.128192,-0.291668,-0.299159,-0.250865,-0.160317,0.045236,-0.390416,-0.258965,-0.235160,0.641365,-0.221837,0.013457,0.372585,-0.258985,-0.287340,-0.601946,0.042671,-0.128402,-0.326833,-0.001550,-0.581213,0.162320,0.090461,-0.189675,0.206447,0.031881,0.035009,0.244321,-0.620474,0.039971,0.779725,0.611081,-0.266180,0.350074,0.045030,0.192891,-0.068881,-0.248554,0.260702,0.616952,0.497233,0.144300,0.116637,-0.037194,-0.242768,0.149134,-0.259945', '1293434', '1482080', '1307442', '3231686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309210', '神秘肌肤', '剧情', '故事以两个小男孩的童年时期开始。布莱恩（布拉迪•科贝特 Brady Corbet 饰）八岁时被球队教练强奸并且从此留下了挥之不去的心理阴影，这成了他心中永远的梦靥。而另外一位男孩尼尔（约瑟夫•高登-莱维特 Joseph Gordon-Levitt 饰）八岁时被教练带回家诱奸，教练扭曲了尼尔的认知，这对尼尔的影响是从此让他沉溺于这样的同性游戏中，并且成了家乡小镇的一名同性恋男妓。此时布莱恩找到了当年和尼尔同在一个棒球队的照片，并以此为线索找到了尼尔的家。不巧此时尼尔刚好去了纽约寻找新生活。于是布莱恩通过尼尔的好朋友和尼尔保持联系。在圣诞夜的时候，两人终于相聚在当年侵犯二人的教练的住所，尼尔向他讲述了当年的真实情况......©豆瓣', '切斯·埃利森', '格雷格·阿拉基', 7.8, 19507, 'tt0370986', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453993847.jpg', 0.3, 1.8, 24.9, 51, 21.9, '0.436495,-0.084977,-0.444122,0.560780,-0.153588,-0.648760,0.819211,0.226267,-0.780144,-0.078016,0.054893,1.023694,0.003365,0.354885,0.592505,0.282164,-0.349834,-0.882196,-0.013438,-0.291551,-0.496119,-0.679997,-0.276283,-0.128729,-0.079103,-0.473833,0.420698,-0.144396,0.012722,0.443086,0.073576,0.377779,0.063427,0.280508,-0.004592,0.186849,0.315702,-0.031235,-0.407975,0.261281,-0.012431,0.012221,-0.182875,0.229614,-0.065719,0.416265,0.602794,-0.125790,0.030251,-0.177150,0.154276,0.030437,-0.094751,0.243635,0.051584,-0.226385,0.320411,0.207455,-0.121107,-0.190632,-0.152787,0.024904,-0.704129,0.112293,-0.047843,0.264853,-0.536272,0.441784,-0.163731,-0.112666,0.254515,-0.294188,0.317169,0.483074,0.321788,0.352154,-0.377731,-0.049884,-0.495375,0.178787,0.546770,0.234249,-0.145492,0.196961,-0.288829,-0.207388,-0.118913,0.176843,-0.380717,0.029874,0.583616,-0.007901,-0.350348,0.128922,-0.800181,-0.311608,-0.152849,-0.157692,0.028942,-0.646057,-0.212237,-0.605850,-0.190491,-0.259573,-0.155943,-0.220809,-0.043367,-0.234025,0.677468,-1.011990,0.357228,0.745779,0.090954,-0.176364,0.511315,0.175630,0.276431,-0.158891,0.054903,0.406139,0.091286,0.490189,0.119487,0.457306,0.126635,-0.157323,-0.489405,0.573298', '30345227', '1299556', '1783461', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309217', '见鬼十法', '喜剧', '某泰国小青年乘车夜归，结果坐错公车，在一个陌生的地方下车。将错就错，他逛进一家书店，发现一本名为《见鬼10法》的书，书中罗列了换死人角膜、怀孕自杀、杯仙、十字路鬼、捉鬼迷藏、涂尸泥、屋内打伞、午夜对镜梳头、倒栽头和去死等十种见鬼方法，恐怖惊险却又引人入胜。在好奇心的驱使下，青年将书买回家中。不久，他和另外四个朋友聚在一起，这几个年轻气盛且胆大妄为的年轻人按照书中的指示玩起了见鬼游戏。然而，见鬼10法的恐怖之处在于，一旦开始便要进行到底，即使因此失去了性命……©豆瓣', '陈柏霖', '彭发', 6.5, 20608, 'tt0455135', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1605700526.jpg', 2.3, 12.3, 50.9, 26.3, 8.1, '0.526901,-0.111853,-0.335290,0.249986,-0.085573,-0.071559,0.488962,-0.020807,-0.143802,-0.355847,0.101328,0.570745,-0.165832,0.044067,0.164962,-0.105585,-0.280781,-0.404286,0.121502,-0.213091,-0.412467,-0.072896,-0.172047,-0.051832,0.061393,-0.085737,0.007027,0.066913,-0.042843,0.201826,0.262613,0.122488,-0.448062,0.172886,-0.251528,0.074424,-0.157039,-0.004864,0.195058,0.237591,-0.005752,-0.219000,-0.318960,0.126401,0.031926,0.236541,0.577441,-0.088279,-0.388576,-0.239959,0.366509,0.036135,-0.312497,0.236349,0.059383,0.036613,0.274584,-0.102130,-0.015864,0.145670,0.014588,0.071721,-0.557819,0.087120,0.054380,-0.015769,-0.335345,0.221611,-0.058956,0.061391,-0.094864,-0.383977,0.297142,0.140283,0.361802,0.527117,0.111374,-0.442284,-0.482504,0.111008,0.332099,0.098047,0.057915,0.346405,0.260549,-0.349090,0.242873,-0.177845,0.015660,-0.050001,0.304949,0.215457,-0.485162,-0.357178,-0.640273,0.076605,0.004347,0.161686,-0.240601,-0.188976,-0.248454,-0.386176,0.220244,0.141403,-0.089992,0.312578,0.005338,-0.117088,0.487198,-0.144955,0.238816,0.531481,0.140844,-0.548653,0.582084,-0.179411,-0.118753,-0.180547,0.081007,-0.057714,0.247467,0.542052,0.103486,0.375400,-0.199209,-0.023275,-0.525070,0.326124', '30387441', '1302661', '26839466', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309218', '最后的日子', '剧情', '布雷克（Michael Pitt 饰）一个通身充满忧郁气质、内心敏感纤细的音乐人。商品社会和都市喧嚣已经让他精疲力竭，他从大都会逃脱，躲在森林中的别墅。穿着怪异的他每日喃喃自语在林中穿梭游荡，荣誉和金钱，地位与名望在这一刻全部失去了意义。即便如此，周遭的世界仍不断侵犯着布雷克最后的领地。朋友、经纪人、录音室、陌生人……你来我往，不绝如缕，而真正有几人关心布雷克内心的嬗变？几日的独处后，布雷克独自在地下室演奏最后一支曲子，随后仰望天堂，不再回还……本片根据涅磐乐队（Niravana）主唱柯特•科本（Kurt Cobain）生前最后的一段经历改编，荣获2005年戛纳电影节技术大奖。©豆瓣', '迈克尔·皮特', '格斯·范·桑特', 7, 7217, 'tt0403217', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p860182600.jpg', 2.6, 8.5, 40, 34.1, 14.7, '-0.087520,0.221282,-0.704851,0.666782,0.124287,-0.003648,0.837344,0.317547,-0.674527,-0.127810,0.243321,0.782649,-0.254575,0.145051,0.325599,-0.215359,-0.352695,-0.628516,-0.030186,-0.225567,-0.063430,-0.273288,-0.293423,-0.103140,-0.165828,-0.568409,0.706770,0.098210,-0.148253,0.623441,0.228048,0.035925,-0.274453,0.354843,-0.362313,-0.071573,0.427682,0.329631,-0.199607,0.057140,-0.101027,-0.303434,-0.516401,0.030345,-0.100127,0.037466,0.894021,-0.070502,-0.000639,0.261558,0.386342,-0.019371,-0.032237,-0.248943,0.177989,-0.184417,0.174446,0.303579,-0.082496,0.113765,-0.223673,-0.011751,-0.588780,-0.049391,0.049988,0.199888,-0.499017,0.706226,0.005041,0.064367,0.011657,-0.075030,0.159560,-0.115349,0.308099,0.429199,-0.100806,0.013463,-0.382727,0.302072,0.522881,0.014226,-0.485749,0.381383,-0.416709,-0.494993,-0.421654,-0.074934,-0.559970,-0.286719,0.222145,0.224750,-0.254876,0.215647,-0.680563,0.298111,0.098239,-0.451149,-0.020962,-0.581906,-0.193680,-0.704088,-0.369888,-0.349591,-0.075330,-0.024114,-0.074915,0.041167,0.630550,-0.597780,0.300982,0.575657,0.076454,-0.056864,0.812874,-0.094683,0.149105,-0.120052,-0.104074,0.572833,0.072215,0.212871,0.044422,0.451727,-0.271409,0.211084,-0.658740,0.667709', '2334814', '25785124', '3811356', '1292925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309220', '黑社会', '剧情', '香港最大黑社会帮会“和联胜”举行两年一度的办事人选举，阿乐（任达华饰）与大D（梁家辉饰）作为两大地区领导，暗地里展开争夺宝座的努力，一众有投票权的元老亦为自身利益而明争暗斗，选举因此相当不顺利。结果，阿乐再次获选成为办事人，满心不服的大D决定挑战帮规，他要抢夺到象征最高权力的信物龙头棍，组织新帮会。五名小头目（古天乐、张兆辉、张家辉、林雪、林家栋饰）牵连其中，为争夺龙头棍展开连番内斗。最终鹿死谁手，一切不得而知。©豆瓣', '任达华', '杜琪峰', 8.4, 172661, 'tt0434008', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2213462183.jpg', 0.2, 0.9, 15, 48.9, 35, '-0.396645,0.120373,-0.534947,0.563728,0.079589,0.244542,-0.016453,0.426436,-0.531143,-0.185166,0.537552,0.726990,-0.055623,-0.034223,0.098017,-0.512613,-0.062299,-0.672145,-0.249428,-0.026707,-0.215533,-0.273341,-0.251252,-0.185915,-0.336615,0.243349,0.910232,0.018438,-0.238190,0.179471,0.748003,0.082674,-0.145643,-0.138632,0.033202,-0.364336,0.312669,-0.002050,-0.457980,0.017131,-0.361084,-0.199323,-0.430206,0.122153,0.435966,0.306835,0.275923,-0.324220,0.109311,-0.636573,0.203950,-0.350048,-0.251570,-0.180790,0.392261,0.269684,0.290282,0.619811,-0.145254,-0.020102,0.195765,-0.433549,-0.735866,0.090244,0.396465,0.185004,-0.334840,0.482199,-0.036140,-0.050080,0.081516,0.062746,-0.032152,0.566934,0.297684,-0.187608,-0.107553,-0.023913,-0.523057,0.147620,0.598547,-0.214489,0.011046,-0.480894,0.229137,-0.418286,-0.191754,-0.629267,-0.031870,-0.289448,0.388310,0.112250,0.409366,0.452854,-0.441456,-0.038456,-0.103181,-0.143029,0.172474,-0.375810,0.474153,-0.630989,-0.312459,-0.145509,0.046397,0.102027,0.193007,-0.097422,0.873447,-0.796583,-0.081657,0.005962,0.353498,-0.911182,0.368721,0.465520,0.460155,-0.625473,-0.327751,-0.279794,0.187314,-0.086292,0.036310,-0.147886,-0.138124,-0.408961,0.103688,-0.093295', '4301278', '26691320', '27602116', '4723944');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309222', '鬼来电2', '悬疑', '死亡铃声再次来袭，恐怖的阴影再次笼罩在人们头上！记者孝子（瀬戸朝香饰）一直在坚持不懈地调查鬼来电系列案件，这一次，她终于在台北的一个村庄找到了事件背后的真相。原来这一切都是一个叫李丽（小泉奈々饰）的小女孩造成的。当年，愚昧的村民把他们以为不祥的李丽在此活埋了，李丽的怨气积聚，以致在她死后将怒气通过杀人发泄。在杏子（ミムラ饰）的好友接二连三被杀死后，她某日亦收到鬼来电，不愿坐以待毙的杏子和男友尚人（吉沢悠饰）一起来到台北，企图和咒灵顽强抵抗！©豆瓣', 'ミムラ', '冢本连平', 6.6, 13168, 'tt0451010', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p662698591.jpg', 1.5, 9.9, 53.3, 27, 8.4, '0.337195,0.002127,-0.738192,0.467344,0.131700,-0.145052,0.728103,0.175738,-0.314751,-0.187465,0.326527,0.557134,-0.412980,0.303849,0.113204,-0.027113,-0.189573,-0.772889,-0.110802,-0.200413,-0.300027,-0.258396,-0.058731,-0.224137,-0.048041,-0.203193,0.616977,0.264866,0.074801,0.366931,0.426008,0.598568,-0.277145,0.602994,-0.026169,0.204716,0.004564,-0.118355,0.066002,0.357737,-0.038340,-0.716642,0.146575,0.328815,0.045180,0.273190,0.926239,-0.529502,-0.171280,0.040706,0.367353,-0.399972,-0.197620,0.350255,0.346958,-0.187555,0.093604,0.221062,-0.546986,-0.143282,0.114107,0.203647,-0.572679,-0.241962,0.019057,0.274192,-0.512360,0.330348,0.051987,0.002234,0.211956,-0.199904,0.105146,0.214539,0.012447,0.370666,-0.399485,0.087038,-0.341020,0.013483,0.524525,-0.224115,0.179744,0.214220,-0.039953,-0.184491,-0.107125,0.213995,-0.411172,-0.093348,0.483927,0.031202,-0.360656,0.031906,-0.612803,-0.435587,-0.217843,-0.011452,0.055421,-0.378243,-0.529396,-0.353495,-0.143562,-0.015679,-0.333012,0.172298,0.159543,-0.016536,0.612570,-0.773585,0.193094,0.784886,0.168307,-0.028947,0.249013,-0.022251,-0.181092,0.031963,-0.031346,0.094449,0.187251,0.653889,0.467543,0.301322,-0.097099,-0.075610,-0.409909,0.130739', '25774050', '21619567', '1438591', '26418093');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309226', '小花', '剧情', '那是一个战火纷飞的年代，桐柏山区一户穷苦人家为生计卖掉了亲生女儿小花，之后又收养了一个转移红军留下的女婴，他们给这个女婴取名也叫小花。十几年后，小花（陈冲 饰）的哥哥赵永平（唐国强 饰）为了躲避抓丁投奔了革命队伍，在一次战斗中负伤掉队，幸被女游击队长何翠姑（刘晓庆 饰）所救，而何翠姑正是当年被父母卖掉的另一个小花。此时，赵小花在进入桐柏山区的解放军中打听哥哥下落时巧遇亲生母亲周医生（白莉 饰），母女相逢却互不相识，后来周医生同情这个可怜的小姑娘，于是收她作干女儿。就这样，十几年前失散的亲人在战火中又一次重逢，他们为实现共同的理想又聚到一起，谱写了一曲壮烈的英雄之歌。本片改编自小说《桐柏英雄》，在1980年的第三届电影百花奖上获最佳故事片奖。陈冲凭借本片获第三届百花奖最佳女演员奖通以及南斯拉夫第九届“为自由而斗争”电影节最佳女演员奖。©豆瓣', '陈冲', '张铮', 7.5, 7310, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2532734862.jpg', 0.5, 2.5, 32.6, 49.8, 14.6, '-0.006503,-0.036238,-0.383795,0.590137,-0.116785,-0.619691,0.554383,-0.074123,-0.405186,-0.092107,0.100078,0.808960,-0.081815,0.341722,0.031791,0.020706,-0.158940,-0.642458,-0.029958,-0.129865,-0.262271,-0.210314,-0.133311,0.085065,-0.190744,0.099693,0.611402,0.024365,-0.089195,0.536864,0.583820,0.023685,-0.186439,0.164716,-0.129318,0.432755,0.034980,0.142677,-0.378547,0.351740,-0.171423,-0.302359,-0.094460,-0.023279,-0.020858,0.243107,0.844765,-0.289251,0.186744,-0.318747,0.480428,-0.129877,-0.032468,-0.092921,0.327453,-0.116943,0.346575,-0.245709,-0.190513,-0.016553,-0.047966,-0.147521,-0.458624,0.172491,0.328117,-0.031809,-0.799188,0.400781,0.221873,0.165545,0.099113,-0.143792,0.355624,0.508030,0.331202,0.330768,-0.352111,-0.041003,-0.306188,0.738170,0.674168,-0.300308,0.076747,0.288061,-0.104583,-0.440028,0.353094,-0.123545,-0.490387,0.156939,0.318690,-0.145946,0.007990,0.119429,-0.536272,-0.098970,-0.158412,0.174210,0.142530,-0.313178,0.002390,-0.330266,-0.009422,-0.077263,-0.119335,-0.065166,-0.045725,-0.333020,0.778905,-0.561202,0.184583,0.279322,0.145659,-0.401733,0.693776,0.161347,0.350693,-0.280143,0.118288,0.254658,0.018702,0.216866,0.149267,0.049760,-0.248748,-0.102947,-0.250996,0.190745', '1908036', '3811356', '1306505', '1306031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309235', '大撒把', '剧情', '空旷的候机大厅，即将与各自爱人分别的男女主人公。男主人公顾颜（葛优饰）正在候机大厅送别即将去加拿大自费留学的妻子，偶遇送丈夫出国的女主人公林周云（徐帆饰）。林周云的丈夫不顾即将生产的妻子，就头也没回地匆忙登机。临行前他把妻子托付给素不相识的顾颜，可林周云还是不幸流产了。一年后，两人再次不期而遇。形单影只的顾颜向林周云倾吐自己的思妻之苦，可林周云却因马上能奔赴国外与丈夫团聚而兴奋不已。两年后，林周云仍出国不成，留在国内。孤独寂寞的两人相约一起搭伴过年。五天假期转瞬即逝，分手时，两人都感到了莫名的失落，一段被尘封许久的感情悄然滋生……著名演员葛优也凭借此角色，荣获金鸡奖影帝桂冠。©豆瓣', '葛优', '夏钢', 7.9, 19284, 'tt0106643', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377197353.jpg', 0.2, 1.2, 24, 53, 21.5, '-0.043995,-0.022076,-0.701302,0.445014,0.370767,-0.531374,0.645368,0.221041,-0.349308,-0.007807,0.168542,0.845547,-0.285302,0.725837,0.462149,-0.129175,-0.441950,-0.805515,-0.198370,-0.333294,-0.438431,-0.304991,0.242536,0.208988,-0.214023,0.064624,0.647241,0.287392,0.293196,0.658080,0.375461,-0.010927,-0.694332,0.712363,-0.264799,0.255783,0.042891,0.441259,-0.517342,-0.125727,0.371987,-0.229463,-0.436352,0.059938,0.229391,0.363718,0.678985,0.233618,0.036836,-0.173407,0.451509,0.092268,0.023924,-0.095522,0.079440,0.031386,0.350256,0.049632,-0.181189,0.065572,0.059214,-0.079638,-0.100270,0.356193,-0.057211,-0.232807,-0.539171,0.466431,0.306240,0.191724,0.171243,0.063209,-0.013238,0.241933,0.051166,0.370178,-0.280374,0.187167,-0.092338,0.521064,0.634500,0.086317,-0.202053,0.547093,0.231630,-0.325655,-0.105677,0.197230,-0.565531,-0.059268,0.416930,0.260616,-0.196894,0.085446,-0.150520,-0.120280,-0.283005,0.151069,0.229709,-0.128864,0.131482,-0.783787,0.190844,-0.291911,-0.197177,0.247934,0.315345,-0.088732,0.367776,-0.491951,0.237666,0.096215,0.298393,-0.542198,0.440189,0.120495,0.296342,-0.280713,0.262394,0.438496,-0.215593,0.211827,0.447692,0.196454,-0.332888,0.345768,-0.404462,0.422229', '1303333', '26687241', '2365260', '34795703');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1309297', '神经侠侣', '剧情', '湾仔区巡警陈俊杰（陈奕迅）因为七年来每日所做都是极有规律毫无变化的工作，渐渐对警察一职失去激情，上面派来小师妹廖得男（容祖儿）与他一起巡逻时，眼见对方满腔热情事事认真，他冷眼旁观之余，会不时地冷嘲热讽，遇到疯子王成（吴镇宇）时，陈俊杰也只当他为精神病人指给廖得男看。19岁的天真少女Nicole和Diet在一宗巴士乘客露械案中认识陈俊杰后，开始对其崇拜，陈俊杰也从两人身上感受到温暖。不久，湾仔区出现一名残暴强奸犯，不少单身女性都被其奸杀，Diet也没能幸免。此事促使陈俊杰从麻木中惊醒，他开始发疯似地缉拿凶犯。©豆瓣', '陈奕迅', '阮世生', 7.2, 32504, 'tt0441511', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p486708733.jpg', 1.2, 6.8, 38.9, 37.7, 15.3, '0.040957,-0.130326,-0.667258,0.231002,-0.265384,-0.072172,0.944332,-0.144101,-0.710662,-0.184892,0.104981,0.737125,-0.573066,0.336134,0.154684,0.005201,-0.294561,-0.775409,-0.336106,-0.078444,-0.269331,-0.176799,0.043874,-0.023008,-0.381829,-0.185474,0.318923,-0.072909,-0.121357,0.519372,0.276849,0.125617,-0.077855,0.756425,-0.094084,-0.016508,-0.011486,-0.139687,0.197032,-0.070631,0.054970,-0.405432,-0.369766,0.003189,-0.249633,0.476627,0.757576,0.036788,-0.304165,-0.355012,0.285088,-0.029218,0.004122,0.262569,0.516341,0.210398,0.270347,-0.033474,-0.047447,-0.106617,-0.124088,0.231848,-0.309668,-0.007840,-0.044134,0.254209,-0.259632,0.075058,0.035936,-0.064041,0.331611,-0.259882,0.139510,0.171207,0.042926,0.232360,-0.184342,-0.042156,-0.333698,0.141164,0.645471,0.261818,-0.204705,0.246711,-0.047822,-0.508716,0.075949,-0.052572,-0.428570,-0.110846,0.149740,0.236779,-0.190935,0.238610,-0.122270,0.142881,-0.003586,0.009858,-0.288139,-0.353543,-0.305488,-0.410739,-0.109713,-0.479065,-0.040331,0.151487,0.118500,-0.329528,0.670443,-0.651523,0.245254,0.277061,0.221087,-0.349537,0.569774,0.034518,-0.123966,-0.245521,-0.172549,0.049673,0.225432,0.405422,0.251485,0.393653,-0.349526,0.014067,-0.037831,0.187709', '21348112', '1293142', '4724373', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310153', '清洁', '剧情', '艾米利（张曼玉 饰）曾经是一个音乐节目主持人，她的丈夫行为先锋不羁，是一个过气的摇滚歌星。他们都嗜毒，丈夫还因为吸毒过量而死。而艾米利则被搜出毒品而被判6个月监禁。因为夫妻一直过着不正常的生活，所以儿子被爷爷奶奶领走抚养，想给他一个清洁的成长环境。艾米利出狱后，她强烈的想要回儿子的抚养权，然而长辈却没有办法相信艾米利能尽好母亲的责任。为了能和儿子重聚，艾米利找了一份餐馆的工作，努力戒掉毒瘾，让自己成为一个清洁的母亲。正巧此时奶奶患病，爷爷分身乏术，无法照料孙子，这样一来，事情真的可以遂愿么？©豆瓣', '张曼玉', '奥利维耶·阿萨亚斯', 7.5, 18235, 'tt0388838', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p880918682.jpg', 0.4, 2.6, 32.7, 47.8, 16.4, '-0.108877,-0.164372,-0.518943,0.618901,-0.685806,-0.614090,0.711860,0.299728,-0.692420,-0.394824,-0.059821,0.785176,0.334845,0.421573,-0.085659,0.178690,-0.089225,-0.611651,0.113480,0.090292,-0.306446,-0.433412,0.091606,-0.379894,-0.189546,-0.259000,0.468036,-0.136176,0.266497,0.153317,0.327253,0.043504,0.212753,0.467216,-0.175039,0.032333,-0.157161,-0.081025,-0.318061,0.351912,0.370673,-0.126699,0.092551,0.315994,0.079620,0.298071,0.643906,-0.047684,-0.230643,-0.471981,0.378550,-0.378942,-0.034613,0.321566,0.135638,-0.058131,0.503296,0.201054,-0.329608,-0.137111,0.110954,-0.117586,-0.860696,-0.014765,-0.076843,-0.026475,-0.655994,0.368763,-0.156037,-0.057025,-0.067161,-0.332654,0.361693,0.357528,0.084050,0.592400,-0.629093,0.198783,-0.619417,0.407798,0.834731,-0.231216,0.052984,0.567065,-0.299909,-0.292674,0.249901,-0.491557,-0.859417,0.241979,0.020851,0.040635,-0.378353,0.065643,-0.228596,-0.039045,-0.368503,-0.083872,-0.074661,-0.453799,0.086225,0.080392,-0.089543,-0.095530,-0.306451,-0.001074,0.077389,-0.361053,0.627616,-0.730073,0.268214,0.627378,0.419421,-0.834855,0.679211,0.382759,0.210951,-0.289199,-0.053495,0.142901,-0.102350,0.140818,0.287570,0.053089,0.235233,-0.063943,-0.278928,0.263141', '1877596', '1304977', '1296569', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310159', '梁祝', '剧情', '公元337年的东晋时期，门第风气极盛，三品官家祝氏为了巩固朝中地位攀附权贵，将独生女儿祝英台（杨采妮）许配马氏太守，因为担心无心向学的女儿失礼于人，遂叫她女扮男装来到书院好好进补，因书院均是男儿，祝氏夫人（吴家丽）拜托院长夫人对爱女特别关照。在书院，祝英台结识出身贫寒但苦心向学的梁山伯，因情义相投，两人相交甚笃，日日相对中，祝英台的女儿身被梁山伯识破，两人相爱。自此梁山伯更加发奋读书，期望取得功名后将祝英台迎娶进门，然而门第的隔膜终难消除。©豆瓣', '吴奇隆', '徐克', 8.3, 71214, 'tt0110340', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2125670899.jpg', 0.2, 1.5, 17.5, 43, 37.9, '0.380846,-0.045921,-0.257361,0.421546,-0.029079,-0.368165,0.171586,0.481367,-0.877249,-0.496508,0.184246,0.651628,-0.256622,0.374950,-0.035326,-0.363086,0.224660,-0.432846,0.188811,-0.277858,0.384531,-0.285141,0.269045,-0.085483,-0.575217,-0.284693,0.582012,-0.008229,-0.038753,0.530284,-0.078669,0.218753,-0.125350,0.228797,-0.151630,0.160237,-0.415944,0.259549,-0.676800,-0.074117,-0.126474,-0.138181,-0.326961,-0.508584,0.269709,0.125927,0.445078,-0.087362,0.158937,-0.335065,0.576741,0.163458,0.274148,0.547357,0.365415,0.066993,0.075332,0.645860,-0.160743,-0.204092,-0.103488,-0.317357,-0.017845,0.153170,0.625367,-0.178449,-0.454937,0.649560,0.077389,-0.544951,-0.135261,-0.173294,-0.052716,0.487957,-0.023167,0.174750,-0.060019,0.188575,-0.394565,0.310433,0.570772,-0.051857,0.133963,0.031983,-0.065713,-0.268196,0.737044,-0.558830,-0.422698,-0.270311,0.139040,0.060732,0.220067,0.487595,-0.011110,-0.266326,-0.348306,0.518310,0.248095,-0.541702,0.169485,0.106618,-0.275182,-0.464432,-0.333815,-0.311290,0.556645,-0.579573,0.853576,-0.867538,-0.178703,-0.080627,0.473700,-0.859050,0.701348,0.077601,0.456929,-0.169192,-0.278681,0.112367,0.053213,-0.227410,-0.143007,-0.073507,-0.370541,-0.073197,-0.112828,0.109228', '3445516', '10561880', '1297514', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310166', '咖啡时光', '剧情', '阳子（一青窈）表面看来是个温文有礼的传统女性，却有前卫出格的思想，台北教书生涯让她收获了尚在腹中的胎儿，并就是否将他（她）生下与父母产生矛盾——她不认为孩子一定要有爸爸。小书店老板也是阳子朋友的肇（浅野忠信）虽喜欢她，但因没作好承担责任的思想准备，并没在阳子人生最困顿时伸来一双及时的手。作为纪念小津诞辰100周年而拍的该片，没能复制小津镜头下的东京景象（因为已经消失），却复制了小津电影里安静恬美的意境和隐忍克制的情感。但时间毕竟流过了几十年，隐忍情感的角度已有很大的转变。©豆瓣', '一青窈', '侯孝贤', 7.4, 11931, 'tt0412596', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453471904.jpg', 0.8, 4, 35.9, 42.4, 16.9, '0.222438,0.160324,-0.558424,0.519047,-0.357146,-0.341873,0.729409,0.251550,-0.464293,-0.363031,0.184174,0.525701,0.072502,0.125219,-0.096643,-0.071773,-0.162013,-0.533733,-0.063566,0.075708,0.015742,-0.387685,-0.264260,0.088134,-0.371947,-0.387765,0.751245,0.096293,-0.144597,0.343948,0.023594,-0.032438,0.184584,0.623878,-0.131359,-0.011520,-0.247131,0.280061,-0.120893,0.095402,0.353300,-0.257171,-0.232008,0.447406,0.040328,0.679928,0.556186,-0.130523,-0.326413,0.130974,0.330139,-0.102344,-0.023675,0.335668,0.061829,-0.012555,0.376883,0.188833,-0.233686,-0.093050,0.013253,-0.035884,-0.749838,-0.011946,0.092656,0.173251,-0.439189,0.555284,-0.190711,-0.238539,-0.048887,-0.402289,0.049557,0.277489,0.300991,0.262719,-0.335926,0.038479,-0.287705,0.135015,0.465002,-0.048894,-0.396568,0.759453,-0.522782,-0.572184,0.046928,-0.225644,-0.262679,0.024985,0.019808,0.120667,-0.461695,0.248187,-0.203738,0.265933,-0.192599,-0.034024,0.048795,-0.462047,0.014299,-0.300110,-0.185932,-0.618999,-0.395848,-0.100030,0.279324,-0.220796,0.901595,-0.987232,0.210082,0.491349,0.245488,-0.329197,0.884068,0.286942,-0.121202,-0.079169,0.075341,0.059385,-0.488922,0.181148,0.095701,0.487083,0.023418,-0.237109,-0.314148,0.685344', '3230462', '26354526', '1395231', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310167', '北京杂种', '剧情', '改革开放的大潮下，古老的皇城北京也按捺不住那份躁动。人们来去匆匆，生活节奏陡然加快，躁动的摇滚乐和肆无忌惮的谩骂响彻夜空，看不到未来却又为未来拼搏的年轻人们恣意宣泄着心中的愤懑。摇滚乐手卡子（李委 饰）的女友毛毛（俞飞鸿 饰）怀了孩子，两人为要与不要的问题大吵一架。之后毛毛失踪，装作不在意的卡子又四处寻找女友；崔健（崔健 饰）与乐队在摇滚乐之路上艰难前行，身无分文的他们交不起场地租金，被迫打起游击，乐队的排练经常受到干扰；买书为生的黄耶鲁被骗子袁红海（武啦啦 饰）骗尽钱财，他和哥们好友四处寻找骗子，结果兄弟间反倒出了矛盾。滚滚洪流，这群不甘受缚的青年趁着韶华未尽，可劲儿燃烧、挥霍着他们这无望、困顿的青春……本片荣获1993年洛迦诺电影节评委会奖特别提及。©豆瓣', '崔健', '张元', 6.5, 10723, 'tt0106378', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2221978211.jpg', 3.1, 13.7, 46.9, 26.6, 9.7, '0.003597,-0.131039,-0.644682,0.465985,0.181919,-0.426494,0.828698,0.173880,-0.266774,0.036052,-0.065699,0.282854,-0.291385,0.279620,0.219146,-0.206798,-0.283672,-0.651337,-0.052748,0.013900,0.307727,-0.101087,-0.010117,-0.121804,-0.222334,-0.236786,0.424750,0.278298,-0.038926,0.590865,0.482446,0.124592,-0.136114,0.374319,-0.092330,0.126226,-0.020917,0.106451,0.025140,-0.152851,0.033191,-0.367905,-0.228700,-0.023682,0.030060,0.393252,0.729617,0.002503,0.036360,-0.043435,0.407938,-0.170901,-0.035710,-0.002670,0.047574,-0.029451,0.160169,-0.004620,0.009621,-0.011391,-0.002325,-0.004227,-0.356966,0.177400,0.064278,0.013781,-0.665416,0.437014,0.054775,-0.015609,-0.009375,-0.194919,0.219205,0.115255,0.105640,0.469209,-0.293396,0.003102,-0.478154,0.460041,0.527005,0.030536,-0.152008,0.092274,-0.370623,-0.262505,0.108656,-0.161338,-0.666567,-0.388929,0.446638,0.036550,-0.072531,0.189243,-0.543383,0.020926,0.239030,-0.216033,-0.056992,-0.267018,-0.182151,-0.446044,-0.090409,-0.322315,-0.061741,0.167622,0.075661,0.059873,0.622062,-0.503799,0.102240,0.510745,0.190827,-0.320153,0.448520,0.001193,-0.064303,-0.029050,-0.266729,0.007486,-0.208302,0.385716,0.414613,0.222186,-0.144268,-0.012405,-0.198553,0.353633', '21619567', '3111650', '26926321', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310169', '鬼汤', '剧情', '大学生铃木一郎（渡浩之 饰）是一个其貌不扬的青年，但他却有着不为人知的神奇能力。他自幼就能看到游离在身边的鬼魂，并能与他们交谈，不过铃木始终对这个能力懵懵懂懂。圣诞前夜，他搬到一幢新的公寓。原本收拾房间便是一件让人心烦的事情，偏偏还有很多不知趣的人前来打扰。铃木烦躁地送走许多不速之客，但是有那么几个人让他无计可施。俏皮可爱的娜娜（鈴木蘭々 饰）和她的伙伴马尔（Dave Spector 饰）执意要进入铃木的房间，双方为此展开神奇而有趣的攻防战，铃木更被他们好好捉弄了一番。不过他最终得知，娜娜一行人原来是天上派下来的天使，他们要在圣诞夜为孤魂野鬼们熬制温暖灵魂的鬼汤，铃木的房间刚好就是鬼魂即将聚集的所在……©豆瓣', '铃木兰兰', '岩井俊二', 7.6, 6814, 'tt0382048', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2162666245.jpg', 0.7, 3.9, 31.3, 41.7, 22.4, '0.423886,0.008400,-0.552861,0.382809,-0.454161,-0.133463,0.833863,0.188887,-0.735614,-0.334527,0.145661,0.696636,-0.106777,0.282634,0.168701,0.205818,-0.244157,-0.562544,-0.113678,-0.128566,-0.338592,-0.350293,-0.170488,-0.469915,-0.066164,-0.141361,0.422165,0.241671,0.137616,0.441213,0.248921,0.223915,-0.279686,0.607848,-0.243304,0.025342,0.116683,0.002138,0.122332,0.144722,-0.139721,-0.167433,-0.373448,0.376506,0.057757,0.227217,0.596684,-0.065596,-0.385202,-0.001552,0.133350,-0.238326,-0.062599,0.167182,0.281258,-0.164546,0.336882,-0.001070,-0.199483,0.039021,0.041911,-0.069145,-0.693122,0.231273,0.189747,0.148937,-0.434701,0.458535,0.145749,-0.105539,0.274395,-0.352717,0.076242,0.451107,0.202759,0.234668,-0.149122,-0.142435,-0.521253,-0.005775,0.676116,0.003800,0.085050,0.478488,-0.175500,-0.413924,-0.255053,-0.186395,-0.391707,-0.002571,0.270015,0.305702,-0.178327,-0.227959,-0.696809,-0.079508,-0.053517,-0.046927,-0.032374,-0.608865,0.067044,-0.562672,0.011829,-0.401413,-0.451924,0.299477,0.128436,-0.122787,0.857978,-0.840460,0.116203,0.592557,0.205260,-0.395280,0.599358,-0.002633,-0.210708,-0.052287,-0.084994,-0.028687,0.142606,0.321835,0.066444,0.653899,-0.131750,-0.072545,-0.673775,0.340106', '2053515', '3005387', '5262027', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310175', '群鸟', '悬疑', '米兰妮（蒂比·海德莉 Tippi Hedren 饰）是一个富家女，偶然在宠物店里遇见律师米契（罗德泰勒Rod Taylor 饰），二人萌生爱意。第二天米兰妮带着她的一对宠物鹦鹉到访米契居住的波德加湾小镇，却被一只海鸥袭击，当场受伤。然而谁也没料到，这次鸟袭击人的事件，只是鸟类大规模攻击人类的小序幕。米兰妮留在镇上疗伤，这里鸟语花香，生活本来平静，她还认识了米契的家人和前女友，于米契的感情也渐渐升温，但是鸟类的出没对他们生活的骚扰程度也渐渐升级。这些鸟聚集的越来越多，黑压压的一大片，被它们攻击至伤甚至至死的居民日渐增多，这个小镇陷入一片疯狂的鸟灾当中。人们恐惧接近崩溃，如何赶快逃脱这个恐怖的地方，成了他们迫在眉梢的问题。©豆瓣', '罗德·泰勒', '阿尔弗雷德·希区柯克', 8.1, 65191, 'tt0056869', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1493936502.jpg', 0.4, 1.7, 18.2, 51.8, 27.9, '0.365343,-0.105830,-0.782174,0.535863,0.189092,0.070716,0.734063,0.146698,-0.215617,-0.311450,-0.189013,0.554202,-0.370775,0.123262,-0.055473,-0.371924,0.037409,-0.335611,0.026854,-0.097948,-0.069980,-0.193214,-0.492327,-0.343677,-0.092020,-0.246632,0.297535,0.185113,-0.295361,0.691499,0.115045,0.199950,-0.123922,0.733442,-0.165460,-0.148145,0.038256,-0.236017,0.054468,0.214267,-0.113181,0.028881,0.051023,-0.021418,-0.001155,0.368160,1.094788,-0.282735,-0.267289,-0.232912,0.151919,-0.355380,0.048728,0.168123,0.445253,-0.447667,0.100845,-0.305542,-0.208956,0.001244,0.164007,-0.031115,-0.589374,0.107639,-0.218620,0.207831,-0.325138,0.200672,0.119441,-0.020185,-0.018691,-0.230427,0.460555,0.317412,-0.040474,0.264214,-0.329986,-0.201287,-0.652426,-0.174894,0.912890,-0.047495,-0.233482,0.269045,-0.367770,-0.637975,-0.057694,0.032628,-0.352235,-0.108557,0.237836,0.005361,-0.372824,0.374256,-0.892577,0.003742,-0.349412,-0.319324,-0.232692,-0.424470,-0.142946,-0.576134,-0.167515,-0.282950,-0.246294,0.271518,-0.074093,-0.160387,0.445484,-0.615664,0.385855,0.429287,0.489461,-0.282009,0.503828,-0.154404,0.130883,0.094151,-0.340890,0.312255,0.149009,0.135862,0.334862,0.235414,0.104327,0.054285,-0.187872,0.549060', '10581450', '1453067', '7056398', '26418093');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310176', '放大', '剧情', '真相与幻想之间的界限是什么？感官是否能助我们认识世界？影片用一个摄影师的故事，铺开了一系列哲学、心理学的问号。主角是摄影师托马斯(戴维·海明斯 David Hemmings饰)，某天他在公园里抓拍到年轻情侣的系列照片，出人意表的是，照片中的一个女子简(瓦妮莎·雷德格瑞夫 Vanessa Redgrave饰)竟然不惜一切代价要回她的底片。这让托马斯非常疑惑，他相信这张照片许是拍下了某些不可告人的秘密。果然，他把照片放大后，看到了一具尸体和一个拿着枪的人。一桩谋杀案的雏形在托马斯脑中展开。他前往公园寻到了尸体，但没有人肯相信他的推测，朋友们不愿意和他一起调查这是怎么回事。第二天，当托马斯再次来到公园，发现尸体已经消失无踪。只剩下一群人进行着一场虚拟的网球赛，打着并不存在的的网球。©豆瓣', '瓦妮莎·雷德格雷夫', '米开朗基罗·安东尼奥尼', 8.5, 42892, 'tt0060176', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p548426395.jpg', 0.6, 1.8, 12.3, 42.3, 43, '0.445330,0.075170,-0.678326,0.637430,-0.159662,-0.048361,0.928178,-0.121617,-0.394926,-0.363951,0.180518,0.845263,-0.318405,0.316349,0.138740,0.065306,-0.441093,-0.816796,-0.243880,-0.276844,-0.599457,-0.637930,-0.306906,-0.239392,-0.047618,-0.087442,0.467156,0.141021,-0.174802,0.299160,0.365875,-0.076383,-0.301746,0.383502,-0.179688,0.075379,0.063205,0.049813,-0.048657,0.195069,0.195006,-0.181971,-0.120994,0.196307,-0.301710,0.194345,0.784090,-0.204744,-0.188958,0.127063,0.241071,-0.293831,0.067815,0.164074,0.145172,0.038720,0.181957,0.076598,-0.100658,-0.044599,0.172927,-0.005604,-0.836254,-0.002104,-0.080652,0.557749,-0.515912,0.391905,-0.351278,0.038221,0.073676,-0.246774,0.366035,0.228339,0.350486,0.278049,-0.078538,-0.035515,-0.645504,0.197668,0.395710,0.167661,-0.118297,0.595357,-0.195972,-0.314947,-0.377462,0.329366,-0.350064,0.110710,0.443507,-0.087325,-0.292735,0.007827,-0.598576,-0.155578,-0.152150,-0.257881,-0.036288,-0.324610,-0.200424,-0.562926,-0.263620,-0.271128,-0.361639,-0.009677,0.047905,-0.331439,0.792171,-0.738591,-0.002140,0.520746,0.035601,-0.193648,0.749759,-0.031071,-0.123785,-0.190606,0.058554,-0.013000,0.359575,0.260690,0.062269,0.443851,0.178820,-0.176104,-0.624667,0.556297', '25928048', '30162520', '1307146', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310177', '东京教父', '剧情', '圣诞夜，退役自行车选手Gin，性倒错者花，离家出走的少女美由纪三人在东京的雪夜中无所事事。这时，他们发现垃圾堆中有一位哭泣的弃婴。孩子的襁褓中仅有一个酒吧的名片与照片。婴儿的父母身份成了谜团。 花想收留孩子，并将孩子取名清子。但另外2人表示反对。于是三人开始了寻找清子父母的旅程。圣诞夜幸福的气氛，伴随的却是怀中清子的哭泣。无家可归的三个人，开始为同样无家可归的清子找寻属于她的家。这一队流浪者，在一夜经历了诸多奇妙的事件。他们能找到清子的父母吗？©豆瓣', '江守彻', '今敏', 9, 198343, 'tt0388473', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456703618.jpg', 0.1, 0.4, 6.5, 33.4, 59.6, '0.431016,0.031316,-0.544386,0.320636,-0.117450,-0.131004,0.752624,0.138954,-0.689063,-0.381469,0.308607,0.860343,-0.013287,0.582142,0.289345,0.095922,-0.118272,-0.743143,-0.240317,-0.143178,-0.488390,-0.155719,0.091700,-0.295245,-0.157973,-0.174818,0.649411,0.192791,0.311374,0.665839,0.354012,0.127430,-0.345199,0.368569,-0.337843,0.280797,0.105691,0.272440,-0.125533,0.124674,-0.292013,-0.081347,-0.120668,0.042180,0.021605,0.325919,0.958216,-0.218971,-0.058101,-0.232128,0.205587,-0.036246,-0.387464,0.082748,0.292759,0.126130,0.353000,0.109023,-0.101048,0.082160,0.126506,0.142799,-0.495009,0.111916,0.202819,0.237607,-0.400837,0.456293,0.052463,-0.122343,0.276042,-0.202256,0.249647,0.209218,-0.097108,0.632985,-0.209109,0.017636,-0.568015,0.141609,0.418326,-0.260851,-0.034297,0.435228,-0.309830,-0.480819,0.068771,-0.133523,-0.481319,0.133810,0.292199,0.150163,-0.596174,0.000127,-0.597008,0.067523,-0.181134,-0.130736,0.070619,-0.651455,-0.377830,-0.610311,0.001046,-0.135598,-0.175221,0.121005,-0.036549,-0.296400,0.882635,-0.768859,0.110379,0.492665,0.050285,-0.435343,0.481942,0.077909,0.286533,-0.273133,0.049119,0.281954,-0.072237,0.186774,0.066545,0.108433,-0.389301,0.271751,-0.493138,0.114176', '3811356', '1307146', '25922902', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310178', '爱丽丝梦游仙境', '动画', '金发碧眼的小女孩爱丽丝（Kathryn Beaumont 配音）天生爱幻想，枯燥且没有图画的书籍最令她烦恼。这一天，爱丽丝在野外看见一只穿衣戴帽、匆匆赶路的兔子。出于好奇，她跟着兔子钻进了一个树洞，继而掉落到一片未知的奇幻世界。在这里，爱丽丝的身形忽大忽小，还遇见了搞怪 的双胞胎兄弟弹弹丁和弹弹当、癫狂无比的疯帽匠（Ed Wynn 配音）和三月兔（Jerry Colonna 配音）、以及来无影去无踪的妙妙猫，由此引出了不少的笑话和奇遇。当然，最令爱丽丝感兴趣的还是那只慌里慌张赶路的兔子。在它的引领下，爱丽丝来到了红心皇后的城堡，更大的冒险等待着她……本片根据英国作家路易斯·卡罗的同名原著改编。©豆瓣', '凯瑟琳·博蒙特', '克莱德·杰洛尼米', 8.7, 24848, 'tt0043274', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1833057233.jpg', 0.1, 0.5, 10.6, 44, 44.7, '0.385451,-0.052065,-0.716753,0.625017,-0.042806,-0.177586,0.812221,0.244329,-0.254207,-0.094019,0.309957,0.663814,-0.284648,0.217600,0.131336,-0.095318,-0.271686,-0.198366,-0.244614,-0.238799,-0.259262,-0.219053,-0.302314,-0.188075,-0.104126,-0.187817,0.473409,-0.115422,-0.209324,0.575928,0.319013,0.081489,-0.246241,0.285837,-0.388406,0.175401,0.046925,0.302791,0.263318,0.084582,0.212780,-0.234687,-0.197198,0.131174,-0.231419,0.113512,0.886594,-0.515386,-0.113711,0.053483,0.441875,-0.363894,0.157944,-0.234808,0.225827,-0.225037,0.078853,-0.329038,0.034852,0.178172,0.030346,-0.102020,-0.666444,0.111713,0.079637,0.375539,-0.546125,0.371645,-0.040757,0.017604,0.381059,-0.482564,0.097497,0.264872,0.088057,0.435203,-0.001487,0.118438,-0.470020,0.394761,0.278591,0.127449,-0.269358,0.546045,-0.185520,-0.358567,-0.035661,0.112322,-0.272531,-0.257532,0.682674,0.032143,-0.380586,0.064158,-0.786723,0.232827,0.012650,-0.239763,-0.146575,-0.369384,-0.200701,-0.581289,0.137996,-0.382190,-0.155724,-0.146148,0.166499,-0.232177,0.736215,-0.691063,0.232519,0.667885,-0.132561,-0.190410,0.634955,-0.256893,0.016592,-0.109264,-0.020810,0.338755,0.220738,0.396528,0.235743,0.642880,0.025866,-0.026985,-0.826270,0.555962', '21619567', '26839466', '1309194', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310179', '幻想曲', '动画', '1940年，迪士尼公司制作了第三部长片动画《幻想曲》，为动画史贡献了一部迄今仍难以企及的经典名作。本片由8部音乐短片组成，最早诞生的《魔法师的学徒》讲述了在魔法师严西（Yensid，迪士尼Disney倒写）手下学徒的米老鼠偷戴师傅的帽子，利用魔法指挥扫帚挑水并惹下大祸的 有趣故事。该片原打算收入“糊涂交响曲（Silly Symphonies）”系列，但因严重超支，入不敷出，故迪士尼决定另外结合几支经典名曲拍成一部音乐短片合集，一并发行。只是因过于艺术化以及二战等方面的原因，《幻想曲》并未取得预期的收益。除杜卡的《魔法师的学徒》外，本片收录曲目还有巴赫《D小调托卡塔与赋格》、柴科夫斯基《胡桃夹子》、斯特拉文斯基《春之祭》、贝多芬《田园交响曲》、蓬基耶利《时间舞曲》、穆索尔斯基《荒山之夜》和舒伯特的《万福玛丽亚》。本片获第14届奥斯卡特别成就（音 乐和录音技术）2项金像奖。', '华特·迪士尼', '詹姆斯·阿尔格', 8.9, 15663, 'tt0032455', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1315649053.jpg', 0.3, 0.6, 9.5, 32.5, 57.2, '0.006018,-0.192615,-0.254883,0.601022,0.523788,-0.125918,0.302598,0.288099,-0.216674,-0.487529,-0.013383,0.610589,-0.153715,-0.003914,0.278717,-0.336551,-0.419652,-0.442838,0.037806,-0.088729,0.202028,-0.158187,0.041237,-0.130671,-0.290012,-0.495512,0.673444,-0.085236,-0.417950,0.290442,0.331866,0.065242,-0.198599,-0.254677,0.070520,0.146326,0.316434,-0.121110,-0.310000,0.136973,0.028161,-0.135181,-0.046509,-0.374766,0.114635,0.202577,0.768010,-0.194673,0.337496,0.038322,0.713067,0.061277,0.057482,-0.368979,0.183310,0.351452,0.229250,0.187537,-0.103861,0.321787,-0.220131,-0.517557,-0.850408,0.139304,0.372208,-0.055841,-0.219436,0.397203,-0.354732,0.281502,-0.100782,0.025880,0.101965,0.033455,0.535546,0.413235,0.123936,0.000260,-0.213652,0.538522,0.061037,-0.129794,-0.402662,0.572780,-0.170866,-0.626663,-0.393592,-0.498564,-0.154420,0.275356,0.280355,0.023628,0.551769,0.042281,-0.591385,-0.112615,-0.088891,-0.303578,0.077426,-0.023793,-0.030425,-0.745910,0.139618,0.059190,0.209784,-0.164623,0.596039,-0.198258,0.623197,-0.246193,0.129896,0.052211,-0.089827,0.081655,0.412642,-0.025709,0.262721,-0.161489,-0.092366,0.119295,-0.190578,0.127793,0.168085,0.207641,0.220968,-0.654304,-0.221614,0.195427', '22265121', '35116325', '3318306', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1310185', '三岔口', '剧情', '城市中扑朔迷离的人物关系和事件始末。一洗黑钱罪犯被押送回港，职业杀手曲（吴彦祖 饰）将其枪杀后逃逸，背后主谋是洗钱集团首领饶天颂（罗嘉良 饰），但他的儿子也同时被其它神秘人物拐走。案情开始变得千头万绪。这个案件，交由了警察孙（郭富城 饰）负责，孙一向倒霉，这次最令他意外的是，他竟然发现饶天颂的律师杜厚生（郑伊健 饰）有一个叫Amy（李心洁 饰）的妻子，像极了十年前失踪的女友。这一切，让他倾注大量心血在案件调查上。然而，对这桩案件感兴趣的，除了孙，还有杀手曲。他们各有心事，步步为营，在错综复杂的关系和事件中拉扯争斗。©豆瓣', '吴彦祖', '陈木胜', 6.5, 45440, 'tt0455195', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1249576102.jpg', 1.2, 8.7, 57.8, 26.4, 5.9, '0.237343,-0.338581,-0.659108,0.640334,-0.040422,0.157290,0.757520,-0.072828,-0.812711,-0.588242,-0.116588,0.528079,-0.281365,0.331391,0.198630,-0.224655,-0.081085,-0.915077,-0.304688,-0.065665,-0.411393,-0.648093,-0.035563,-0.443222,-0.091284,0.128107,0.432148,0.333253,-0.220384,0.335916,0.754239,0.508544,-0.443727,0.572263,0.067735,0.081345,0.259140,0.126766,-0.033259,-0.043613,0.052818,-0.501401,0.217802,0.155563,0.017772,0.585524,0.537575,0.061849,-0.196453,-0.149455,0.370259,-0.330302,0.085185,-0.008058,0.700517,0.221768,0.100999,0.377265,-0.423113,-0.389192,0.251559,-0.243487,-0.665958,-0.087401,0.534502,0.030009,-0.592693,0.028873,-0.139894,0.191276,-0.029955,-0.127941,0.523722,0.384672,0.568787,0.119499,0.265157,0.068450,-0.594119,0.305770,0.635279,-0.017371,0.029294,0.147236,-0.119990,-0.666657,-0.435358,-0.260226,0.050054,0.181030,0.417890,-0.207411,0.144939,0.407053,-0.333356,-0.184072,0.057554,0.117689,-0.205885,-0.300383,0.083755,-0.314622,-0.292609,-0.585512,-0.413005,0.136269,-0.054558,-0.367569,0.398977,-0.518348,-0.073234,0.265193,-0.093070,-0.714702,0.558339,0.085381,0.285274,-0.337254,-0.086449,0.031971,0.446780,0.014483,0.285417,0.172724,-0.086329,-0.371012,-0.055623,0.019858', '1308290', '3263169', '1301022', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1315316', '无间道风云', '剧情', '波士顿南部的马萨诸塞州黑社会势力极为猖獗，其中最大的团伙要数弗兰克（杰克•尼科尔森 Jack Nicholson 饰）执掌的爱尔兰黑帮。警方为了剿灭他们，决定派警校毕业生比利（莱昂纳多•迪卡普里奥 Leonardo DiCaprio 饰）潜伏其中做卧底。警官的冷嘲热讽，让曾有过底层生活的比利甚为不爽，他曾希望做堂堂正正的警察，但是在强压之下也只得服从命令，在经过烧杀抢掠的洗礼后，他赢得了弗兰克的信任。与此同时，同是毕业生的科林（马特•达蒙 Matt Damon饰）因为缉私有功，获得了上级的嘉奖，并且正在跟心仪女友筹备婚事。而实际上，他是弗兰克安插到警队的一枚棋子，两人勾结牟取私利。警匪先后发现存在内鬼，一场猫鼠博弈由此展开……本片获得第79届奥斯卡金像奖最佳影片、马丁•斯科塞斯摘得最佳导演奖。©豆瓣', '莱昂纳多·迪卡普里奥', '马丁·斯科塞斯', 7.3, 124441, 'tt0407887', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1471403480.jpg', 1.2, 4.8, 35.8, 43.2, 15, '0.195721,-0.270139,-0.702018,0.700304,-0.009868,-0.157534,0.384984,0.164943,-0.547619,-0.139165,0.261896,0.648238,-0.044214,-0.065481,0.349520,-0.212993,-0.401718,-0.673992,-0.169321,-0.305103,0.146555,-0.606346,-0.527349,-0.170634,-0.134342,-0.297255,0.639631,-0.016647,-0.128151,0.352150,0.550364,0.564832,0.034875,0.124023,0.055395,-0.036228,0.493835,-0.068105,-0.608493,0.312146,-0.016829,-0.159916,-0.291492,-0.017762,0.323322,0.485021,0.338288,-0.265433,0.080721,-0.136417,0.318661,-0.449994,-0.113619,-0.025309,0.427556,0.099039,0.168337,0.398274,-0.056848,-0.002618,0.060862,-0.072440,-0.729175,-0.065520,0.251240,0.234146,-0.477598,0.300254,-0.056634,0.129422,-0.014137,-0.054925,0.118140,0.485769,0.264172,0.026276,0.140660,-0.007675,-0.517125,0.220729,0.728812,-0.234679,-0.129770,-0.149585,-0.133639,-0.486263,0.257808,-0.425441,-0.319278,-0.172546,0.333330,-0.236073,0.303986,0.261637,-0.372644,-0.173474,-0.342642,-0.228262,0.133029,-0.313807,0.178370,-0.706117,-0.249248,-0.230142,-0.192790,0.035087,-0.014118,-0.384482,0.453644,-0.850366,0.209456,0.588621,0.148936,-0.463956,0.453334,0.328811,0.373292,-0.368465,-0.209124,0.010875,0.362380,0.202509,0.107030,0.098417,0.106975,-0.572217,-0.057152,0.046875', '4301278', '1307442', '1986338', 