INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1315570', '在世界中心呼唤爱', '剧情', '强烈台风吹袭日本，朔太郎（大泽隆夫 饰）发现未婚妻律子（柴崎幸 饰）留下数字便失踪了，他一路寻找未婚妻的过程中，竟然也走进了高中时的记忆中，少年时代的他（森山未来饰）还有她的初恋女友亚纪（长泽雅美 饰）。那是他深藏的痛。他们是同班同学，亚纪是个跑步好手，对憨憨的朔太郎逐渐有了好感，二人一起投稿到电台节目，交换录音日记，一起去旅行等等，纯纯的爱使他们都倍感幸福。可是好景不长，亚纪发现自己患上了癌症，病魔的折磨仍防碍不了两人的交往，他们甚至一起拍了一辑唯美的婚纱照。亚纪也不久人世了。原来未婚妻就是因为知道了这些往事出走的，但她听到了整个故事后深深的被感动了，并与朔太郎一起到了亚纪生前最想去的世界中心。©豆瓣', '大泽隆夫', '行定勋', 7.6, 45952, 'tt0424430', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1308221260.jpg', 0.6, 3.4, 31.4, 42.9, 21.7, '0.259851,-0.064909,-0.748196,0.441487,0.017754,-0.461842,0.613705,0.070601,-0.387587,-0.211716,0.038985,0.647580,-0.194637,0.449524,0.144805,0.258186,-0.222618,-0.874713,-0.132293,-0.312184,-0.412920,-0.407909,0.038830,0.116095,-0.248948,-0.155650,0.471530,0.016260,0.125048,0.699050,0.262855,0.214468,-0.147206,0.497951,-0.094353,0.422060,0.121741,0.165194,-0.159791,0.015312,0.188498,-0.253936,-0.085789,0.362693,-0.096890,0.411797,0.692427,-0.036695,-0.195716,0.025378,0.208244,-0.205833,-0.276592,0.167453,0.361269,0.110936,0.297330,0.261689,-0.189627,-0.218810,0.042908,0.245079,-0.395031,0.095843,0.026817,0.180183,-0.260492,0.414110,-0.048309,-0.167541,0.234262,-0.212831,0.409987,0.225226,0.281038,0.299784,-0.413720,-0.044321,-0.122855,0.368117,0.785584,-0.112101,-0.026529,0.599855,-0.289369,-0.181207,-0.198652,0.010986,-0.365662,0.084577,0.085728,0.148249,-0.357033,0.131431,-0.488851,0.021105,-0.179086,-0.013876,-0.078410,-0.330060,0.101462,-0.455360,-0.312346,-0.583908,-0.347890,0.157584,0.074926,-0.299032,0.737788,-0.713743,0.152996,0.697485,0.418757,-0.292931,0.554162,0.067670,-0.230222,0.000941,0.153289,0.204795,-0.144530,0.208501,0.190150,0.538981,0.076732,-0.140608,-0.658904,0.512282', '3811356', '5977789', '30162520', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1315574', '加勒比海盗2：聚魂棺', '动作', '迷人的杰克（约翰尼•戴普 饰）船长又回来了，这次，他遇到了更为强大的敌人——传说中的不死人大卫•琼斯(比尔•奈伊 饰)，他驾驶着让人恐惧的“飞行荷兰人”号快船，在速度与装备上，没有任何船能够超越它。杰克船长欠下琼斯一个血债，他必须赶在最后时限到来之前，找到破解的方法，否则他会永远背负血债，并且在余生永远成为琼斯的奴隶。当然，杰克船长的好朋友威尔•特纳（奥兰多•布鲁姆 饰）也被卷入了他的坏运气当中。因为杰克，威尔和伊丽莎白（凯拉•奈特莉 饰）的婚礼被迫取消，伊丽莎白还被关进了监狱，威尔为了救她，只能去寻找杰克。这次两个好朋友遇到了巨大神秘的海洋怪物、不友善的小岛土著、打扮华丽的占卜者戴尔玛，威尔失散多年的父亲--“拉靴带”比尔•特纳(斯特兰•斯卡斯加德)在关键时刻离奇现身，成为全局的转折点……©豆瓣', '约翰尼·德普', '戈尔·维宾斯基', 8.4, 394435, 'tt0383574', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1076822803.jpg', 0.1, 0.8, 14.5, 48.5, 36, '0.020541,-0.011889,-0.540677,0.277419,-0.376051,-0.348064,0.823938,0.039980,-0.203367,-0.088862,0.256480,0.889732,0.174866,-0.216388,0.337616,0.336828,-0.480363,-0.291731,0.224858,0.035693,-0.299151,-0.558982,-0.231680,-0.410583,-0.014504,-0.427710,0.388925,-0.011074,-0.122568,0.291473,0.165577,0.340688,0.084461,0.478950,-0.081484,0.057901,0.222533,-0.448231,-0.043442,0.453138,-0.105255,0.027303,0.066929,0.315061,0.060783,0.188787,0.416262,-0.226894,0.198193,0.059937,-0.082083,-0.384641,0.124878,-0.030618,0.044981,-0.397836,0.006149,0.271118,-0.021222,-0.234767,0.191503,-0.054427,-0.872874,0.211392,-0.185687,0.123809,-0.503867,0.295846,-0.297168,0.040742,0.239802,-0.377720,0.193857,0.080528,0.145980,-0.024250,-0.049242,-0.000983,-0.673181,0.110863,0.508962,0.053105,-0.224188,0.006289,-0.128883,-0.445568,-0.117820,-0.320110,-0.511127,0.109881,0.776436,0.002330,-0.171963,0.343099,-0.524857,-0.049189,-0.438495,-0.139273,-0.240608,-0.330906,0.002805,-0.612858,0.021022,-0.289990,-0.496315,-0.133553,-0.188176,-0.215115,0.388021,-0.564954,0.490325,0.742966,0.157060,-0.219431,0.643073,0.116714,0.288499,-0.074339,-0.003205,0.424377,0.140501,0.441982,0.272866,0.206048,0.314509,-0.109709,-0.278940,0.733160', '4944008', '1299628', '1301345', '1949005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316499', '极度寒冷', '剧情', '青年前卫艺术家齐雷（贾宏声）的一项行为艺术引来众多媒体、同行及过路客的关注。该行为艺术的前三部分，立秋日模拟土葬、冬至日模拟溺葬、立春日作象征性的火葬完成后，齐雷宣布为与社会的冷酷对抗，他将在最后一部分，即在夏至日用尽自己的体温融化一块巨大的冰（冰葬）时，真正结束自己的 生命。齐雷女友（马晓晴）和朋友们得知后，竭力阻止。他们不知的是，执意要赴黄泉路的齐雷不过是幕后推手手中的一枚棋子，他所实施的行为艺术只是另一项包含阴谋的更大的“行为艺术”的一部分。©豆瓣', '贾宏声', '王小帅', 7.3, 6615, 'tt0125279', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2378468915.jpg', 1.7, 6.6, 34.1, 41, 16.7, '0.263577,0.121870,-0.559358,0.571132,-0.092581,0.043266,0.647471,0.132240,-0.222346,-0.147104,0.414230,0.688357,-0.233851,0.064336,0.143117,-0.304525,-0.036151,-0.695946,-0.494831,0.030332,-0.357771,-0.468943,-0.206620,0.052927,-0.343707,-0.047145,0.726242,0.115269,-0.065650,0.219264,0.370138,0.189727,-0.061657,0.291092,-0.177296,-0.221816,-0.116075,0.047122,-0.166750,0.239082,0.164651,-0.297343,-0.306720,0.250034,-0.252160,0.475202,0.633135,-0.266845,-0.010513,-0.272324,0.525621,-0.386243,-0.033919,0.266189,0.169104,0.284090,0.056163,0.313768,-0.286541,0.029881,0.108595,-0.101789,-0.852339,-0.124077,0.089049,-0.029965,-0.486352,0.539263,0.063351,-0.063508,0.000994,-0.374478,0.358707,0.479304,0.132379,0.203377,-0.208711,-0.253888,-0.324055,0.419943,0.669354,-0.037064,-0.243950,0.188296,-0.129782,-0.459503,-0.123292,-0.081733,-0.144285,-0.155136,0.276653,0.217327,-0.088737,0.136784,-0.808907,-0.181467,-0.280763,-0.193211,0.091032,-0.370103,-0.205815,-0.598043,-0.045379,-0.158841,-0.045709,0.173237,0.413189,-0.353030,0.867482,-0.874461,0.211101,0.544530,0.017543,-0.382857,0.482488,0.109273,0.273873,-0.212160,-0.191128,-0.130162,0.069364,0.204943,0.099479,0.438063,0.072877,0.070676,-0.485401,0.350063', '27602116', '25928048', '2053515', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316510', '射雕英雄传之东成西就', '喜剧', '金轮国王妃（叶玉卿 饰）与表哥欧阳锋（梁朝伟 饰）有染，为霸占江山，他们毒死了国王，但没找到传国玉玺。得知玉玺在前往九宫山找寻其师父求助的三公主（林青霞 饰）手里后，欧阳锋企图抢到手但没成功。糊涂国师（张曼玉 饰）在淫威下屈服，查出三公主的具体下落，欧阳锋乘火箭金靴追赶 ，却误脱落一只插死刚出关的王重阳（钟镇涛 饰），奄奄一息的王重阳恳求适逢路过的三公主找到其师弟周伯通（刘嘉玲 饰）代为报仇。逃到九宫山的三公主邀得师弟黄药师（张国荣 饰）与师妹（王祖贤 饰）相助，再加上前来寻找表妹的洪七（张学友 饰）、找到真心人才能成仙的段智兴（梁家辉 饰），一场与欧阳锋的生死恶战蓄势待发……©豆瓣', '梁朝伟', '刘镇伟', 8.7, 594158, 'tt0108074', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2609063925.jpg', 0.6, 1.6, 11.3, 33.3, 53.3, '-0.148578,0.085630,-0.450839,0.462456,0.164935,-0.123662,0.332205,0.029254,-0.205271,-0.297211,0.391085,0.464385,-0.216979,-0.041529,-0.020392,0.096029,0.072427,-0.431199,0.098181,-0.013871,-0.069645,-0.270896,-0.339153,0.133149,-0.363269,-0.169707,0.743707,-0.155030,-0.073461,0.613493,0.425635,-0.045642,-0.399380,0.217517,-0.320125,0.193723,-0.275399,0.278029,-0.363704,0.480510,0.082010,-0.365806,-0.189342,-0.044748,-0.044569,0.468242,0.309219,-0.349664,0.368866,-0.045409,0.137772,-0.170535,0.073201,0.145509,0.087593,0.031964,0.058233,0.198192,-0.324039,-0.091574,0.162873,0.071555,-0.085545,0.187969,0.317744,0.139242,-0.493786,0.096476,-0.507965,0.009419,-0.100642,-0.540174,0.365676,0.385928,-0.022693,-0.113865,-0.135572,-0.132987,-0.706408,0.280231,0.417121,-0.112903,0.487148,-0.047450,0.768660,-0.275789,0.426632,-0.286900,-0.068328,0.137633,0.661105,-0.086796,0.092597,-0.050103,-0.212201,-0.532971,-0.541670,0.323051,0.094837,-0.243120,0.182388,-0.382678,-0.013631,-0.152473,0.068534,-0.072231,0.303754,-0.353123,0.451070,-0.413808,0.099968,0.034638,0.045414,-0.589725,0.440492,0.050259,0.057540,-0.186408,-0.347636,0.104580,0.233919,-0.005221,0.069486,0.006429,0.079279,-0.162780,-0.438538,-0.370278', '1294011', '1968502', '1295469', '1295485');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316511', '我的1919', '剧情', '1919年，随着第一次世界大战结束，被战火蹂躏的欧洲尚未恢复元气，旨在解决战争遗留问题和奠定和平基础的巴黎和会准备召开，中国作为战胜国之一，派出了时任驻美公使、全权代表顾维钧（陈道明 饰）等五人组成的代表团参加和会。然而在欧美各国以及日本等列强意欲重新划分势力范围的大环境下，中国代表团人数遭到削减、德国在山东的利益眼看也要落入日本之手。顾维钧在会议上慷慨陈词，驳斥日方无理要求，然而公理在利益面前显得多么脆弱。顾维钧好友肖克俭（何政军 饰）之妻梅（许晴 饰）专程赶赴巴黎，寻找投身爱国工人运动的克俭。克俭在法国的活动、以及国内浩大的群众呼声令和会中的顾维钧等感受到责任重大。©豆瓣', '陈道明', '黄健中', 8.6, 41641, 'tt0441912', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2461241975.jpg', 0.2, 0.9, 12.3, 43.7, 42.8, '0.152093,0.276259,-0.906330,0.441821,0.292868,-0.112180,0.072742,0.380319,-0.304622,-0.044492,0.231820,0.629499,-0.140334,-0.164756,0.550188,-0.325826,-0.368680,-0.892150,-0.261894,0.151086,-0.123310,-0.591087,-0.190685,-0.163284,-0.268238,-0.112022,0.694530,0.387226,-0.330070,0.664344,0.192286,0.304292,0.077011,0.397491,0.188084,-0.436039,0.377056,-0.191134,-0.640412,0.150716,-0.088108,-0.459704,-0.114863,0.095724,-0.060212,0.269334,0.484988,-0.186434,0.199137,-0.385538,0.314699,-0.462235,-0.110487,0.201227,0.381438,0.254480,0.125128,0.486670,-0.233174,0.073425,-0.045883,-0.276861,-0.439106,0.149663,0.108409,0.315442,-0.273003,0.696606,-0.024970,0.018389,-0.126954,-0.315178,0.209709,0.994460,0.034255,0.498458,-0.021813,0.163293,-0.303407,0.202985,0.706239,-0.226704,-0.191160,-0.331730,-0.019438,-0.317948,0.207894,-0.497252,-0.059093,-0.280803,0.062182,-0.224752,0.109894,0.187564,-0.842071,0.104444,-0.247494,-0.638567,0.376428,-0.103625,0.183837,-0.884412,-0.401594,-0.375497,-0.229644,0.190749,0.276249,0.051905,0.920780,-0.640626,-0.111363,0.215508,0.601381,-0.469543,0.492463,0.311903,0.087466,-0.098457,-0.058451,0.053415,0.053747,0.339275,-0.145816,0.029991,-0.081632,-0.383898,-0.150688,-0.069880', '1424552', '3078390', '26365262', '3074408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316513', '我的兄弟姐妹', '家庭', '女指挥家齐思甜（梁咏琪 饰）首次回国演出，她想趁着这次机会找回失散多年的兄弟姐妹们。20年前，齐家父亲（崔健 饰）是一个音乐老师，家中虽然清贫但也算是幸福。母亲（张健新 饰）长年来积劳成疾，突然病重。父亲在大暴雪的夜里送母亲到医院，却遇上了车祸。忆苦、思甜、天、妙四个孩子也成为了孤儿。表叔好心要求收留他们，但表叔家里也不富裕，更受到了表婶的强烈反对，大哥忆苦只好忍痛把弟弟妹妹都送给他人收养。4兄弟姐妹自此失散，但每人手里都拿着一张全家福。20年后的各人都有了各自的生活，或苦或甜，思甜苦苦追查也只找到了弟弟妹妹，忆苦碍于自己的寒微而不敢与思甜相认。演出如期到来，忆苦缺席了……©豆瓣', '梁咏琪', '俞钟', 7.4, 38207, 'tt0304641', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2019228473.jpg', 0.5, 3.4, 36.5, 43.5, 16.2, '-0.015004,-0.115718,-0.364288,0.242860,-0.027337,-0.552665,0.346527,0.143704,-0.588595,-0.196886,0.199753,0.821058,0.179589,0.622845,-0.127812,0.032777,-0.165175,-0.424964,0.351929,0.030956,-0.153082,-0.386524,0.108488,0.155263,0.015382,-0.120464,0.189375,-0.255096,0.233264,0.604087,0.218426,-0.027553,-0.032893,0.462278,-0.203548,0.278680,-0.060645,0.161691,-0.278948,0.046993,0.096395,-0.136428,-0.411125,0.182053,0.424522,0.399423,0.502748,-0.077795,-0.262789,-0.177975,0.215927,-0.215703,-0.093558,0.121521,0.198065,0.065974,0.628394,0.461179,-0.229573,0.010058,-0.063141,0.086637,-0.404690,0.359579,0.314105,-0.146457,-0.718394,0.402203,-0.208004,-0.210703,0.018915,-0.431413,0.415373,0.426353,-0.102282,0.293221,-0.550904,0.093663,-0.390102,0.382801,0.666423,-0.200179,0.063986,0.273234,-0.130587,-0.144796,0.357591,-0.357638,-0.721392,0.327548,0.043438,0.095329,-0.282328,0.018382,-0.394659,0.006735,-0.257239,0.037117,0.269916,-0.344822,-0.035056,-0.067030,-0.086702,-0.063385,-0.545862,-0.050667,0.209191,-0.168091,0.901944,-0.577605,0.227141,0.275254,0.294165,-0.627890,0.596579,0.313073,0.141243,0.006608,0.045371,-0.189587,-0.076267,0.230914,0.150898,0.062360,0.009417,-0.293603,-0.163528,0.138935', '1292720', '3445516', '1292219', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316524', '阿尔法城', '剧情', '这是一座死寂冰冷的未来都市，一座无爱无情的“死城”。一切都必须遵循一台名为“阿尔法60”超级计算机统治下的“逻辑”，若有违反者，都会被枪决。生活在这里的人们表情木讷，生活思维受到严格的控制，丧失了一切人性本该拥有的喜怒哀乐。来自另外世界的密探雷米·柯雄（埃迪·康斯坦丁 Eddie Constantine饰）开始了对阿尔法城的探索，他的主要目的就是将这座城市的设计者万布翰博士（霍华德·沃侬 Howard Vernon饰）带回自己的世界。在探访的过程中，他结识了万布翰博士的女儿娜达莎（安娜·卡里娜 Anna Karina饰），两人相爱了。然而娜达莎仍然没有能够完全摆脱“阿尔伐60”的控制，约翰也被逮捕了，判为死刑。©豆瓣', '埃迪·康斯坦丁', '让-吕克·戈达尔', 7.8, 7798, 'tt0058898', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1361783869.jpg', 0.7, 3.4, 25.3, 46.8, 23.8, '0.266348,0.239435,-0.618740,0.617997,-0.308934,0.031594,0.728224,0.135602,-0.431071,-0.162441,0.386079,0.671247,0.111047,0.104675,0.276228,0.241965,-0.481529,-0.625196,-0.183478,-0.311727,-0.226730,-0.702318,-0.166519,-0.377529,-0.024733,-0.441875,0.840999,0.175424,-0.162926,0.108867,-0.096761,0.280612,0.039028,0.393995,-0.165441,-0.084918,0.227793,-0.421857,-0.265302,0.214670,-0.160704,0.065101,0.060779,0.549128,-0.238862,0.368174,0.766659,-0.623717,-0.208625,-0.035573,0.286670,-0.377324,-0.006994,0.249719,0.106589,-0.219640,-0.123280,0.524858,-0.251880,0.076391,0.249293,-0.278027,-0.934091,-0.295838,0.218228,0.098192,-0.361119,0.511732,-0.025085,-0.114820,-0.207645,-0.221208,0.357229,0.111122,0.504556,0.610092,-0.062302,0.017019,-0.440621,0.064584,0.469977,-0.259704,-0.535909,0.291926,-0.482004,-0.517144,-0.400186,-0.316754,-0.468239,-0.090925,0.164316,0.156648,-0.284845,0.459730,-0.573687,0.155766,-0.344331,-0.374839,-0.087282,-0.621267,-0.214140,-0.489252,-0.167241,-0.272714,-0.149787,-0.015805,0.007279,-0.235239,0.571139,-0.878372,0.214602,0.475441,0.351824,-0.472085,0.613611,0.057565,0.027456,-0.295947,0.027988,0.573983,0.151983,0.669796,0.057799,0.225513,0.103507,0.070186,-0.385178,0.873277', '26759819', '10440076', '6534248', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316525', '虎度门', '剧情', '“虎度门”指粤剧里演员出场的台口，跨过虎度门，意味着全身心交予戏。冷剑心（萧芳芳 饰）是一代粤剧名伶，驰骋舞台三十载，粉丝簇拥众多，而今面对丈夫事业失败，想带全家移民澳洲，剑心要面临是否就此离开舞台的抉择。同时剑心也被家务事缠身，女儿竟然谈了个“女朋友”，就算她在台上反串生角，也难以接受这个事实。此时又恰逢剧团新晋小花旦叶玉霜（袁咏仪 饰），剑心看重她的潜质，又目睹她被养父打骂，起了怜惜之心收下她做干女儿，而从加拿大追着前来看望玉霜的小男友阿俊（陈晓东 饰），被证实是剑心当年在南洋的私生子，带出她当年为了舞台放弃抚养儿子的旧事……告别场演出，台下坐着并不知情的儿子，哽咽着无法上台的冷剑心，终于收下泪水踏出虎度门……©豆瓣', '萧芳芳', '舒琪', 8.2, 8025, 'tt0116576', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524364171.jpg', 0.2, 0.8, 16.7, 52.4, 29.9, '-0.102992,0.271040,-0.721928,0.376039,-0.154925,-0.168822,0.474141,0.329714,-0.098472,-0.079920,0.361479,0.695444,0.012197,0.393002,0.233378,-0.099581,0.049494,-0.595967,-0.038075,-0.135167,-0.163183,-0.013828,0.137272,0.000022,-0.342683,-0.119857,0.628153,0.081532,-0.145987,0.377959,0.863051,0.080796,0.028172,0.112474,-0.145014,0.061057,-0.004523,0.161389,-0.232173,0.094693,-0.197350,-0.326175,-0.192657,0.108418,-0.052809,0.137481,0.578942,0.039400,0.189660,-0.230963,0.145101,-0.307770,0.066951,0.240739,0.266941,0.417396,0.104866,0.200360,-0.234346,0.089886,0.043393,-0.270258,-0.548620,0.272830,0.215572,0.052438,-0.843547,0.329711,-0.328643,-0.082299,-0.038880,-0.262469,0.138855,0.012203,0.034670,0.434624,-0.369185,0.009586,-0.295170,0.322952,0.677489,-0.040121,0.258123,0.276258,0.254251,-0.189853,0.260454,-0.308383,-0.387734,0.084603,0.212090,0.004246,-0.062179,0.233184,-0.018572,-0.031954,-0.305934,-0.007432,0.094462,-0.649517,0.113348,-0.250327,-0.207285,0.029748,-0.043975,-0.054544,0.013791,-0.165282,0.821832,-0.505548,0.103128,0.215126,0.309011,-0.589982,0.663327,0.267751,0.138530,-0.313059,-0.040717,0.328393,-0.210573,0.183527,-0.018797,0.086762,-0.085859,-0.280227,-0.215381,0.092366', '1456503', '30140107', '26021055', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316560', '列宁格勒牛仔征美记', '喜剧', '列宁格勒牛仔摇滚乐队的几个成员装扮怪异，戴大墨镜，烫飞机头，夸张的火箭鞋就是他们的标志。可在他们的家乡看不见事业成功的希望，于是他们决定转战美国寻求机会，在即将出发的前夜，贝斯手却被冻死，尽管如此，队员们还是将他装入了放满冰块的木箱中带上了旅途。此时同村的一个怪异的哑巴 偷偷跟随乐队来到了纽约。纽约的机会并不如他们想象的丰富，困窘的生活仍在继续，在他们走投无路之时，得到了一个来自墨西哥的婚宴演出机会。于是他们用仅剩的钱从一个美国售货员（吉姆•贾木许 Jim Jarmusch 饰）手中买了一辆旧车后继续向墨西哥进发，那里有他们最后的梦想……©豆瓣', '马蒂·佩龙帕', '阿基·考里斯马基', 8.4, 16718, 'tt0097728', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1652557747.jpg', 0.3, 1.1, 13, 47.6, 38, '0.216487,0.191397,-0.622972,0.456521,-0.186237,-0.384605,0.813377,0.187288,-0.293107,0.039109,0.289199,0.905121,0.032286,0.126255,0.166057,-0.109344,-0.457303,-0.746812,-0.039607,-0.225631,-0.540418,-0.126426,-0.123985,-0.169315,-0.007813,-0.025063,0.557029,0.242945,0.029037,0.734178,0.338303,-0.126537,-0.114169,0.556750,-0.527711,-0.144397,0.108924,-0.143443,-0.125871,0.358439,-0.135518,-0.088129,-0.120713,0.233255,0.233337,0.333645,0.824960,-0.048982,-0.045837,0.153818,-0.000419,-0.027747,-0.034239,0.290859,0.092270,0.080333,0.038592,-0.163417,-0.046393,0.074173,-0.003777,0.097990,-0.731997,0.183153,-0.208276,0.157543,-0.824582,0.570274,-0.008070,-0.037226,0.043833,-0.411833,0.291856,0.304120,0.138217,0.267447,-0.167421,0.092589,-0.625790,0.281307,0.561090,-0.017866,-0.029019,0.283015,-0.122328,-0.395875,0.038037,0.050169,-0.411211,-0.152763,0.717341,-0.056834,-0.154223,-0.262246,-0.900377,0.050611,-0.075051,-0.477649,0.103162,-0.312747,-0.047142,-0.668527,0.334766,-0.301134,-0.214805,0.340308,0.106997,0.062907,0.739061,-0.514876,0.161980,0.744175,0.310811,-0.329162,0.613728,-0.113850,0.232175,-0.118579,-0.142008,0.094111,0.036953,0.587316,0.348532,0.593050,-0.252027,-0.232269,-0.522552,0.361955', '21619567', '1309194', '30162520', '1295324');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316565', '世界上最疼我的那个人去了', '剧情', '母亲辞世，50多岁的女作家诃（司琴高娃 饰）想起最后和母亲（黄素影 饰）相处那些的日子，突然明白过来世界上最疼她的人去了。忙于自己事业和家庭的诃看到母亲老态龙钟的步态，恍惚的神情以及几乎失明的视力，突然意识到母亲老了。诃带母亲到医院检查，接着做完了脑部手术。手术很成功，视力很快恢复，可是母亲的情况却并未好转。由于缺乏锻炼，母亲的脑萎缩越来越严重，为了让母亲的病情得以控制，诃给母亲买回跑步机让母亲开始锻炼身体，母亲积极配合着诃各种近乎苛刻的要求，然而母亲的情况还是越来越糟……影片根据当代女作家张洁的同名长篇散文改编。©豆瓣', '斯琴高娃', '马俪文', 8.4, 11663, 'tt0390054', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1473885895.jpg', 0.3, 1.2, 15.3, 43, 40.2, '-0.060538,-0.000082,-0.657205,0.549346,0.066465,-0.638385,0.710319,0.432321,-0.574882,-0.659349,0.166615,0.380057,-0.052620,0.250673,0.188912,0.102668,-0.585533,-0.487746,-0.011802,0.216553,-0.424854,-0.390271,-0.020855,-0.051365,-0.119910,-0.687629,0.311455,-0.092231,-0.168102,0.366187,0.027389,0.380894,0.289415,0.481238,-0.168171,0.143887,-0.283534,-0.276422,-0.297190,-0.057484,0.781623,-0.138317,-0.202462,0.294579,-0.033747,0.438378,0.630770,-0.106995,-0.496478,-0.080124,0.599652,0.127187,-0.048637,-0.030869,0.283615,0.235580,0.469807,0.090860,-0.416164,0.124490,-0.208598,0.115446,-0.415224,0.176859,0.183764,0.149672,-0.692641,0.036852,-0.316210,-0.054494,0.235942,-0.430293,0.202445,0.609565,-0.189908,0.829981,-0.374462,0.194626,-0.258061,-0.013169,0.434418,-0.149866,-0.333164,0.744561,-0.050378,-0.403548,0.045952,-0.533854,-0.147165,0.250893,-0.072068,0.209105,-0.384275,0.249850,-0.144239,-0.107398,-0.247956,-0.540649,-0.007532,-0.327366,-0.017725,-0.318224,-0.078799,-0.350609,-0.274386,-0.189685,-0.017396,-0.396529,0.675241,-0.725881,0.216402,0.252217,0.019623,-0.518882,0.149706,-0.032676,0.090713,-0.152087,-0.060913,0.305984,-0.176572,0.340512,0.098823,0.222771,0.085276,0.117147,-0.490717,0.672302', '1302488', '26791452', '4724586', '3077680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316572', '导盲犬小Q', '剧情', '一只可爱的拉布拉多犬被选去接受导盲犬的培训。为了让它与人类建立感情，它被寄养在一对夫妇的家里，因为身上有一个棕色的胎记，像一只飞翔的海鸥，便给它取名小Q。训练十分艰苦，但小Q还是成为了导盲犬，认识了第一位主人渡边先生，可是渡边先生却怀疑。情况刚有了好转，渡边先生却病倒了，小Q只好回到了训练中心。小Q已经在训练中心度过了7年，这时它又能回到了“养父母”的家了，可是它却患病了……©豆瓣', '小林薰', '崔洋一', 8.5, 135847, 'tt0400761', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1233612794.jpg', 0.1, 0.8, 14.1, 45.6, 39.2, '0.030463,0.051109,-0.395872,0.399059,-0.151340,-0.572606,0.584205,0.230765,-0.526462,-0.311215,0.208337,0.665651,0.097363,0.646806,-0.151444,0.270857,-0.140669,-0.400077,0.119095,-0.143195,-0.321483,-0.273390,-0.377260,0.013734,-0.082035,-0.143446,0.652364,-0.112524,-0.275459,0.485791,0.150523,-0.159785,0.225045,0.321315,-0.409444,-0.040468,-0.114234,0.010202,0.182107,0.165649,0.086607,-0.103553,-0.069371,-0.153989,0.422077,0.414413,0.798889,-0.575242,-0.448751,-0.439455,0.128323,-0.348237,0.065100,0.247366,0.344125,0.240219,0.173976,-0.276075,-0.370728,0.187088,-0.003623,-0.320367,-0.593298,0.116107,-0.242718,0.207901,-0.792127,0.459097,-0.067996,-0.351136,0.189461,-0.644722,0.181503,0.375169,-0.038847,0.527174,-0.329262,0.389201,-0.370466,-0.131413,0.649126,-0.119933,-0.353911,0.347004,-0.123726,-0.801265,0.139458,-0.182449,-0.048691,-0.058034,0.284877,0.229610,-0.555691,0.255082,-0.677120,0.097572,-0.525635,-0.221184,-0.094996,-0.482369,-0.016343,-0.131951,0.091355,-0.370597,-0.274141,0.133943,0.169407,-0.266513,0.894665,-1.182720,0.289437,0.448356,0.328592,-0.192489,0.390766,0.014944,0.116443,-0.013801,0.108341,-0.017509,0.078274,0.593036,0.540936,0.476918,-0.016745,-0.292401,-0.712875,0.354318', '1292219', '3044878', '1420088', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316580', '春夏秋冬又一春', '剧情', '春天，贪玩的童僧拿着石头，绑在鱼、青蛙和蛇身上，捉弄着小生灵们。老僧（吴永洙饰）发现后，用同样的手法惩罚他，告诫他不可胡来。夏天，十七岁的少僧（徐在京饰）为久居深山的修行日子苦闷不已。有一天，一名患病少女（何丽珍饰）在母亲陪同下，来到寺庙拜佛求平安，并留下疗养。少年开 始忍受不住异性相吸所带来的诱惑……秋天，青年（金永敏饰）在外面杀人后重返寺庙，请求谅解。老僧命其刻写心经，去掉罪孽，同时，追捕逃犯的警察也赶到寺庙……冬天，服完刑期的中年男子（金基德饰）回到山中寺庙，重新开始修行苦练。一名妇女突然探访寺庙，并留下了一个男婴，希望能被收留。之后，又一个春天到来。©豆瓣', '吴永洙', '金基德', 8.5, 112865, 'tt0374546', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2554626580.jpg', 0.4, 1.1, 12, 44.7, 41.8, '-0.193014,-0.057832,-0.323661,0.247115,-0.069042,-0.204472,0.695895,0.220047,-0.382722,-0.314830,0.305769,0.406170,-0.106074,0.622209,0.065657,-0.285407,-0.278933,-0.188724,-0.010615,-0.411976,-0.419059,0.116481,0.177636,-0.049574,-0.114058,-0.481010,0.455488,0.329028,0.064817,0.368965,0.168804,-0.001623,-0.075485,0.250219,-0.641976,-0.249191,-0.110767,0.022840,-0.002766,0.308776,-0.106174,-0.384012,-0.246801,-0.146813,-0.214568,0.168972,0.641763,-0.352473,-0.272378,-0.278767,0.280501,-0.023862,0.056987,0.210407,0.146412,-0.001084,0.156208,0.184487,-0.130183,0.313696,0.107782,-0.371740,-0.090096,0.084577,0.022257,0.183213,-0.552003,0.209471,0.154059,0.092207,-0.107936,-0.513807,-0.115509,0.175859,0.140378,0.518259,-0.243437,0.098533,-0.489262,0.213604,0.374421,-0.340030,0.068485,0.169863,-0.216146,-0.323770,0.562016,-0.037689,-0.399727,-0.177291,0.149466,-0.004690,-0.340890,-0.037047,-0.199737,-0.053599,-0.302453,-0.117906,0.113575,-0.025233,-0.381527,-0.443312,0.226437,0.124958,-0.216247,0.142903,0.420867,-0.073353,0.590829,-0.433489,0.576231,0.546237,0.239551,-0.291974,0.559483,-0.194415,0.127989,-0.160983,-0.074843,0.481055,0.047989,0.653440,0.194735,0.208748,-0.525307,0.122146,-0.479097,0.084209', '21619567', '1401900', '1467779', '1297188');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316581', '自娱自乐', '喜剧', '在一个风物宜人的小山村里，单身汉米继红（尊龙 饰）中意妹妹阿莲（陶虹 饰）的好友芦花（李玟 饰），但芦花身为村长的女儿，又是村里的文艺骨干，这让米继红怯于开口。爱好表演的芦花参加某剧组试镜惨遭淘汰，不忍芦花伤心的米继红异想天开，决定自己邀请芦花出演武侠电视剧来满足后者的明星梦。米继红自己担任摄像和导演，又找来投资人——村里饭店的老板，编剧兼道具——村里的木匠组成了班底，此外，阿莲的两个追求者，王胜利（夏雨 饰）和二狗亦当仁不让加入剧组。面对武侠剧拍摄中的种种难题，米继红带领大家先后破解，而他和芦花的感情问题，却是更难解的谜题……©豆瓣', '尊龙', '李欣', 6.1, 6447, 'tt0404808', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2365612034.jpg', 7, 20.8, 44, 19.1, 9.2, '-0.016214,-0.264226,-0.177178,0.500358,0.066025,-0.221567,0.507969,0.356254,-0.335503,-0.216490,0.083218,0.527169,-0.262918,0.365248,0.342575,-0.272859,-0.312709,-0.330517,-0.071015,0.021511,0.176467,-0.090305,-0.272317,-0.289609,-0.021598,0.167741,0.447833,-0.121439,-0.193612,0.531694,0.593875,0.037935,-0.096214,0.286687,-0.019024,0.185563,0.155486,0.080535,-0.295239,0.091746,-0.212194,0.004721,-0.223682,-0.130495,0.280715,0.425341,0.679307,0.032418,-0.164705,-0.085546,0.318992,-0.286049,0.087250,-0.085379,0.218685,-0.040956,0.540656,-0.112531,-0.010773,0.048868,0.191818,-0.292264,-0.612061,0.168110,0.537694,0.123757,-0.375969,0.079137,-0.070523,-0.175848,0.175843,-0.241494,0.056199,0.109538,0.459158,0.407052,-0.341730,0.116060,-0.342896,0.624167,0.462760,0.138727,0.048838,0.025893,-0.103262,-0.635137,0.137159,-0.112466,-0.420726,0.202556,0.115515,-0.239060,0.170402,0.049884,-0.781112,-0.147229,0.098288,-0.011615,0.083989,-0.467560,0.147715,-0.681740,0.033844,-0.120401,-0.178752,-0.168087,0.434004,-0.204138,0.827950,-0.444519,0.079089,0.241017,0.364138,-0.307123,0.883842,0.230792,0.207586,-0.334914,-0.015349,-0.253252,-0.307667,0.191564,-0.107938,0.586949,-0.011025,-0.534973,-0.353213,0.034533', '1302661', '1322847', '3811356', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316589', '69', '剧情', 'KEN（妻夫木聪 饰）是日本高三学生，作风懒散叛逆成为所有老师的眼中钉。他有两个死党同学山田正（安藤政信 饰）和岩濑学（金井勇太 饰），亦是问题少年，他们的口头禅是“解放少女”，喜欢偷窥女生做操，追求漂亮美眉。三人甚至成立了一个“伊亚亚”俱乐部，举办 演唱会，拍实验电影，请心仪的女生来担任主角。拍摄那天，他们干脆在学校天台挂上横幅“想象力正在夺权”。原本只是出于拍摄和追女仔需要的一帮少年，此时以外引发了一场骚动，成为了一次误打误撞的革命运动。风雨再大，少年们仍然自觉胜利，他们心中的实验电影还在继续呢。©豆瓣', '妻夫木聪', '李相日', 7.5, 6525, 'tt0408470', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453454438.jpg', 0.8, 4.1, 33.4, 43.5, 18.2, '0.064658,-0.207592,-0.329728,0.152746,-0.113619,-0.141863,0.333568,0.238563,-0.228879,-0.193661,0.314784,0.452504,-0.300232,0.386654,0.213831,-0.269666,-0.367960,-0.724681,-0.132858,0.071208,-0.057478,-0.228187,-0.049638,-0.088221,-0.110500,-0.239072,0.710413,-0.148587,-0.331491,0.550485,0.634063,0.042895,-0.026719,0.166557,-0.130139,-0.238349,0.061123,0.069718,-0.154784,0.097947,-0.224653,-0.157076,-0.358580,-0.154175,0.122968,0.365164,0.577245,0.004071,-0.096049,-0.199089,0.411950,-0.315619,-0.188219,0.257722,0.392720,0.029600,0.330645,0.003007,0.205017,0.167966,0.031767,-0.260145,-0.397307,0.041458,-0.015730,0.142821,-0.364813,0.561821,0.151007,-0.120207,0.373684,-0.141303,0.027782,0.217346,0.328763,0.282512,0.024478,0.147324,-0.138902,0.353310,0.631471,0.072492,-0.027621,0.371203,-0.168803,-0.316741,-0.109484,-0.139132,-0.316733,0.168655,0.096071,-0.328981,0.139769,-0.052763,-0.524874,0.030227,0.011258,-0.254223,0.209457,-0.332221,-0.063272,-0.872379,0.100662,-0.072099,-0.288908,-0.057522,0.137225,-0.359868,0.999142,-1.045196,-0.017776,0.516852,0.179466,-0.520877,0.612453,0.311439,-0.051322,-0.201423,-0.228198,-0.188524,-0.174071,0.166809,-0.152627,0.417758,-0.207807,-0.313331,-0.320091,0.076521', '25922902', '3811356', '1826173', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316627', '极地重生', '剧情', '二战末期，德国军人科利基文斯（米高·文度 Michael Mendl）在战争中沦为战俘，被处以25年的刑期，而此时他怀孕的妻子和女儿则完全没有他的消息，只能求神保佑他还能活着回来。经过漫长的跋涉，一行战俘被送到了一个劳改场，那里没有围墙也没有栅栏，然而极度的严寒和千里冰原则成了难以逾越的屏障。这里位于西伯利亚东部，初到之时，由于天气和疾病，很多人都不幸死去，然而非人的矿工生活，才是真正的炼狱。科利基文斯从来没有忘记远方的亲人，一次失败的逃亡让他饱受看守的虐待，然而这却更加坚定了他要逃出这里的决心。后来在年迈的医生的帮助下，科利基文斯才得以逃离劳改场，从此获得回家的希望。可是在他面前的，将是长达14000公里的“死亡之地”，在被积雪覆盖的千里冰原，科利孤身一开始了漫长的回家之路……本片曾获多项国际大奖，其情节源自一个真实的逃亡故事。©豆瓣', '迈克尔·门德尔', '哈迪·马汀斯', 8.3, 10714, 'tt0277327', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2642856425.jpg', 0.5, 1.4, 15.9, 46.9, 35.3, '0.088788,-0.079987,-0.944660,0.665452,-0.052775,-0.257475,0.924633,-0.023027,-0.610699,-0.220677,0.159380,0.718905,-0.014589,0.094312,0.104224,0.018443,-0.106143,-0.589058,-0.260625,-0.209042,-0.532017,-0.276613,-0.429409,-0.006919,-0.362883,-0.364174,0.678100,0.475780,-0.048927,0.512937,0.030466,0.088584,0.117408,0.688998,-0.529272,0.006143,0.067297,-0.049094,-0.263650,0.324293,0.034486,-0.305984,-0.231560,0.370500,-0.041594,0.377769,0.751888,-0.253805,-0.147998,0.035988,0.321592,-0.615945,-0.026185,0.123544,0.429370,-0.191803,0.283037,0.303880,-0.136965,0.012080,0.041190,-0.216481,-0.720922,-0.134410,-0.065643,0.094342,-0.606508,0.650596,-0.158764,-0.068725,-0.033355,-0.438761,0.238559,0.388608,0.143276,0.652225,-0.377633,-0.212633,-0.768701,0.198800,1.025641,-0.154141,-0.432839,0.162707,-0.221612,-0.562705,0.035197,-0.452513,-0.508745,0.090175,0.413538,0.145882,-0.596427,0.262330,-0.550905,0.147639,-0.475558,-0.398873,-0.172407,-0.325782,-0.360867,-0.318476,-0.029591,-0.387996,-0.426632,0.218793,-0.110473,-0.270315,0.567151,-0.701144,0.634515,0.522132,0.429238,-0.475458,0.788003,0.321903,0.329804,0.192914,0.247040,0.450447,-0.049558,0.736558,0.226032,0.208701,-0.130772,-0.078421,-0.530604,0.567665', '25721544', '3055049', '21619567', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316693', '心慌方·零', '剧情', '冰冷血腥、精密恐怖的立方体外部，埃瑞克·韦恩（扎卡里·贝内特 Zachary Bennett 饰）和多德（戴维·哈本德 David Huband 饰）两名看守者百无聊赖应否手头的工作，偶尔一瞥屏幕中受困者的行动。这一次，美丽干练的妈妈卡珊德拉•瑞恩斯（史蒂芬·穆尔 Stephanie Moore 饰）和女儿安娜在林间遭到袭击。当她醒来时，发现自己丧失部分记忆，身处一个隔绝密闭的空间。她好不容易找到另外四名受困的陌生人，并和他们策划逃脱，谁知设施内杀机四伏，稍不留意便会毙命。另一边，埃瑞克对受困者渐渐产生同情，他似乎试图破坏这座充满阴谋的杀人机器……本片荣获2004年纽约恐怖电影节最佳特效奖、2004年尖叫电影节最佳化妆和最佳特效奖。©豆瓣', '扎卡里·贝内特', '厄尼·巴巴拉什', 7.1, 52702, 'tt0377713', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2160803511.jpg', 1.2, 6.5, 41.9, 37.1, 13.3, '0.070257,0.020371,-0.634422,0.350503,0.138757,0.139787,1.087655,-0.030323,-0.288642,-0.407623,0.244261,0.642349,-0.335771,-0.026734,0.249308,0.078261,-0.660326,-0.647981,-0.041007,-0.029324,-0.227839,-0.323220,-0.560611,-0.175423,0.023724,-0.465920,0.508222,0.054021,-0.206552,0.507525,0.082997,0.291934,-0.232632,0.415698,0.272679,0.032224,0.248798,-0.387791,-0.140943,0.243089,-0.058047,-0.241923,-0.196223,0.263798,0.099705,0.527941,0.618359,-0.228991,0.076828,0.040372,0.300971,-0.184005,-0.013332,0.078823,0.047981,-0.162886,0.003994,-0.115188,-0.301652,0.195170,0.025644,-0.205248,-0.632205,0.079365,0.007565,0.031843,-0.160363,0.186625,-0.071568,0.150627,-0.094561,0.043281,0.030880,-0.065695,0.182953,0.168303,-0.100693,0.119057,-0.158848,-0.029154,0.101787,-0.227465,-0.368055,0.294245,-0.109464,-0.354070,-0.117188,-0.198379,-0.288549,-0.150607,0.614754,0.194396,0.128802,0.132449,-0.513559,0.108561,-0.294801,-0.245651,-0.332769,0.038136,-0.310133,-0.920131,-0.112473,-0.110176,-0.217880,0.133415,-0.357249,-0.186863,0.283697,-0.406749,0.367910,0.377967,0.226961,-0.077020,0.436414,-0.093178,0.207362,-0.248850,-0.360802,0.438923,0.092030,0.156901,0.098481,0.201281,-0.101099,0.009229,-0.303780,0.387096', '10466639', '20451118', '1301686', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1316698', '马拉松', '剧情', '从外表上看起来，喜欢斑马和巧克力的楚元和同龄孩子没什么两样，一样的活泼可爱，招人喜欢。但他却被诊断出患有自闭症，妈妈庆淑（金美淑饰）听到消息后绝望地晕了过去。之后，妈妈为了减少病症对孩子的影响，投入大量心血，请了教练（李基英饰）训练儿子跑步，希望他能在真正的马拉松赛比赛中跑玩全程。随着时光的推移，楚元（曹承佑饰）长成了20岁的小伙子，但是智力仍停留在5岁孩子的水平上。他会把弟弟当成老师般尊敬，一听见音乐就不分场合、地点的手舞足蹈，但这一切并没有影响他的目标，在良母恩师的支持鼓励下，他朝着马拉松比赛的冠军不断奔跑。©豆瓣', '曹承佑', '郑胤澈', 8.3, 14647, 'tt0448621', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p632331750.jpg', 0.1, 0.6, 15.8, 50.5, 32.9, '-0.018564,-0.000527,-0.463151,0.384720,-0.370325,-0.361172,0.648630,0.036755,-0.494359,-0.011164,0.021614,0.660739,-0.283790,0.161211,0.061651,-0.213048,-0.181359,-0.689045,-0.241919,-0.056671,-0.306368,-0.559774,0.212403,-0.103269,-0.051357,-0.571256,0.346544,-0.250360,-0.152342,0.608098,0.216187,-0.135137,0.230769,0.437385,-0.204063,0.084360,-0.116064,0.096284,0.051836,0.343715,0.130686,-0.012053,0.003214,-0.031034,0.174379,0.028131,0.813304,-0.376890,-0.033484,-0.063213,0.344038,0.023775,0.004855,0.201674,0.220262,0.121375,0.394715,-0.014735,-0.003370,0.059455,-0.223515,-0.344428,-0.525657,0.048233,0.022260,0.254743,-0.697746,0.620398,0.100366,-0.072402,0.189718,-0.303795,0.295869,0.348475,-0.095982,0.632064,-0.513787,0.097674,-0.348483,0.164762,0.585990,-0.130654,-0.241101,0.551969,-0.528467,-0.374649,-0.088866,-0.260043,-0.371618,0.091983,0.130672,0.197987,-0.406448,0.049921,-0.114157,0.321305,0.059916,-0.268291,-0.136776,-0.363530,-0.126762,-0.300701,0.324918,-0.551197,-0.257632,-0.146704,-0.042280,-0.386092,1.139160,-0.857849,0.175867,0.579128,0.307226,-0.293423,0.694302,-0.032340,-0.146344,-0.228799,-0.032706,0.200890,-0.134993,0.124179,0.103070,0.491891,-0.043993,-0.361284,-0.353703,0.592479', '26348103', '25922902', '3811356', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1322674', '捕鼠者', '剧情', '故事发生在1973年的格拉斯哥，对于男孩詹姆斯（威廉·艾迪 William Eadie 饰）来说，这个夏天并不好过，炎炎的烈日让人怎么都打不起精神，而清洁工人的大罢工让街道瞬间变成了堆满了腐臭垃圾的垃圾场。当然，这些都不是最重要的，最让詹姆斯寝食难安的是自己的朋友赖安（Thomas McTaggart 饰）的死亡，是他的死和自己有着千丝万缕的联系。透过詹姆斯的眼睛，我们看到了肮脏不堪的世界，但同时，他茫然踌躇的目光里依然饱含着对未来的憧憬和对爱的渴望。在谁也不知道的地方，一颗幼小的灵魂不断的被痛苦纠缠着，磨砺着，作为代价，它将绽放出最最让人惊诧的纯净光芒。©豆瓣', '汤米·弗拉纳根', '琳恩·拉姆塞', 8.2, 6557, 'tt0171685', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2522884596.jpg', 0.5, 1.9, 16.2, 50.6, 30.8, '0.251855,-0.071711,-1.017848,0.711844,-0.384446,-0.167947,1.233898,0.023236,-0.499369,0.019739,0.212479,0.726906,-0.164665,0.440417,-0.065079,0.056967,-0.031013,-0.679876,-0.227787,-0.418157,-0.458403,-0.695163,-0.276899,-0.059244,-0.045324,-0.442270,0.681014,0.409211,0.016670,0.233296,0.446736,0.247830,0.340170,0.746598,-0.249561,-0.255148,-0.272238,0.071382,-0.007437,-0.005145,0.353562,-0.277996,-0.202351,0.498532,-0.260608,0.217711,0.716917,-0.476427,-0.229130,-0.105744,0.315614,-0.460338,-0.021386,0.321971,0.019027,-0.144369,-0.025107,0.094667,-0.185930,-0.065340,0.329679,0.231576,-1.116781,0.116459,0.109258,0.400179,-0.848635,0.718911,-0.043893,-0.325173,0.275802,-0.343497,0.576769,0.116969,0.174333,0.706268,-0.430751,0.071146,-0.657260,0.012831,0.590418,0.115918,-0.246239,0.502116,-0.763487,-0.257511,-0.144069,-0.146535,-0.665727,-0.107973,0.289568,0.162251,-0.409146,0.465854,-0.628881,0.342737,0.248325,-0.534572,-0.123911,-0.638104,-0.268923,-0.232893,-0.314080,-0.846245,-0.401617,0.148451,0.150919,-0.222920,1.001655,-0.805781,0.176265,0.645684,0.322165,-0.219386,0.843732,0.025486,-0.136360,-0.155334,-0.336202,0.227925,0.296908,0.303812,0.304876,0.586364,0.054438,0.128145,-0.335291,0.813798', '1303077', '1417428', '6745433', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1322847', '果酱', '剧情', '《果酱短片集》由七位日本影坛一线导演拍摄而成，共七部短片。《地狱使者》由北村龙平导演，被称为“The messenger”的黑衣女子神代忧子（鱼谷佳苗饰）出现在报废的大厦房间时，独身强盗权藤（北村一辉饰）的命运由此受到了冲击，极富魔幻色彩；《正义》行定勋导演描写一个正值青春期的男生东条（妻夫木聪饰）被操场上体育课的女生所吸引的故事；《阿里塔》由岩井俊二导演，讲述女孩（广末凉子饰）跟自己幻想出来的“阿里塔”之间的成长故事；以及筱原哲雄执导的《剑玉》、坂田让治导演的《冰冻》、堤辛彦导演的《羊栖菜》和望月六郎导演的《潘朵拉》。七部短片各自取材编排，情节各异。也有众多日本著名演员参演，共同演绎这七部电影，七处生活。©豆瓣', '广末凉子', '北村龙平', 7.5, 6948, 'tt0385791', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2364386556.jpg', 0.7, 2.8, 33, 45.9, 17.6, '0.171952,-0.203598,-0.315112,0.488194,0.283857,-0.012794,0.666995,0.456219,-0.104565,-0.199056,0.411976,0.705058,-0.550422,0.110028,0.392248,-0.189528,-0.381412,-0.607727,-0.336259,0.084303,0.050820,-0.115817,0.007292,0.128809,-0.149799,-0.432400,1.026638,0.023173,-0.325500,0.131571,0.424363,0.168848,-0.264623,0.024208,0.163032,0.359290,0.235345,-0.165054,-0.261595,0.201464,-0.391590,-0.061467,-0.188396,0.086899,-0.280529,0.122776,0.778421,-0.242228,0.091754,-0.032609,0.572509,-0.097993,-0.193139,-0.133472,0.406437,0.189735,0.319335,0.152544,-0.013921,0.117034,-0.104170,-0.093708,-0.671998,-0.094073,0.404377,0.230754,-0.235418,0.271345,0.188393,-0.052972,0.320174,0.020002,0.021307,0.039535,0.633013,0.236107,0.077804,-0.008937,-0.226212,0.583241,0.341113,0.002151,-0.284427,0.277662,-0.245895,-0.430075,-0.326840,-0.122703,-0.472995,0.213121,0.150213,-0.372818,0.066390,-0.011223,-0.576436,-0.097824,0.084722,-0.099969,-0.003622,-0.236559,-0.028672,-1.090036,-0.167862,-0.131683,0.102494,-0.201798,0.320930,-0.073967,1.060697,-0.493680,0.032586,0.355434,0.230436,-0.044792,0.781811,0.033509,-0.177851,-0.203757,-0.094424,0.080579,0.061634,0.216553,0.089856,0.542022,-0.155250,-0.193138,-0.289277,0.321029', '5403927', '2369613', '3318306', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1322848', '奇爱博士', '剧情', '美国空军将领杰克•瑞（斯特林·海登 Sterling Hayden 饰）怀疑苏共的“腐朽思想”正在毒害“正直善良”的美国人民，他于是下令携带核弹头的飞行部队前往苏联，对敌人进行毁灭性的核打击。苏联方面得知此事，立即致电美国总统墨尔金•马夫雷（彼得·塞勒斯 Peter Sellers 饰），并威胁如若领土遭到攻击，苏联将不惜一切代价按下“世界末日装置”。该装置的威力足以摧毁地球上所有的生命。一场有关全人类乃至整个地球命运的战争就这样悄然且荒诞地拉开了序幕……影片根据彼得•乔治1958年的小说《红色警戒（Red Alert）》改编而成，与《2001漫游太空》、《发条橙》并称为“未来三部曲”。©豆瓣', '彼得·塞勒斯', '斯坦利·库布里克', 8.9, 87784, 'tt0057012', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p835946292.jpg', 0.3, 0.9, 8.9, 35.8, 54.2, '0.031403,0.389814,-0.589228,0.678836,0.380294,0.202655,0.365661,-0.159307,-0.174168,-0.123137,0.057185,0.589376,0.093748,-0.407153,0.200752,0.005020,-0.543396,-0.636193,-0.407876,0.192196,-0.292852,-0.607308,-0.125833,-0.421496,0.183142,-0.414623,0.786506,0.165392,-0.405666,0.216020,0.115893,0.550206,0.075805,0.385910,0.116168,-0.071304,-0.075934,-0.383829,-0.665469,0.134824,-0.164568,-0.062269,0.324267,0.442911,-0.240954,-0.008886,0.513960,-0.559637,0.067975,-0.358265,0.459972,-0.363854,0.117574,0.098741,0.369015,0.190974,-0.208624,0.340839,0.173519,0.293403,0.128264,-0.101183,-0.649207,-0.368219,-0.215742,-0.143182,-0.104847,0.105946,-0.404277,0.525411,-0.166875,-0.019002,0.121075,0.462916,0.402922,0.194104,-0.278760,0.061499,-0.273911,0.097070,0.558482,-0.188591,-0.390585,0.058937,-0.168164,-0.249393,-0.200900,-0.302283,-0.241022,0.122144,0.321947,-0.136812,0.171603,0.635114,-0.751105,-0.094721,-0.579412,-0.464295,0.228372,-0.135088,0.241073,-0.959799,-0.088190,-0.303496,-0.234780,0.086182,0.267212,0.093797,0.692150,-0.229258,0.099467,0.522937,0.283072,-0.436929,0.103492,0.023971,0.082479,-0.227597,0.070694,0.601833,0.044707,0.492191,-0.191195,-0.057131,0.364611,-0.101240,0.252738,0.250569', '2369613', '20274039', '1298911', '26990609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1322851', '青红', '剧情', '青红（高圆圆 饰）出生于贵州，但其实她的家人是60年代才迁往这里，支援三线建设的上海人。父母很是希望回到故土，然而青红已把这里看成家乡。她19岁，遇上当地农民出身的小伙子小根（李滨 饰）。青红和小根之间纯洁的初恋却被父母阻止。父亲的高压管束，令青红心中绝望不已。青红的初恋就这样充满了苦涩，她对家庭充满反抗和叛逆，绝食来对抗父亲的强硬态度。但都无法改变父亲的铁石心肠，不但如此，父亲已经决定不顾一切要回去上海，全家搬迁的日子近在咫尺。青红和小根的分离也成了必然。他们来到后山，小根面对满怀心事而显得冷淡的青红，爱恨交织，把她占有。小根受到了残酷的惩罚，而这段初恋，这个年代，也毁了青红的一生。©豆瓣', '高圆圆', '王小帅', 7.1, 50379, 'tt0456658', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p900374555.jpg', 0.7, 4.4, 42.9, 41.7, 10.3, '0.129637,-0.103656,-0.737794,0.407359,-0.176121,-0.313027,0.651563,0.049123,-0.529176,-0.114949,-0.039246,0.731815,0.081215,0.477543,0.156823,0.144475,0.024646,-0.589901,-0.055337,-0.102781,-0.029821,-0.428668,-0.093729,-0.060643,-0.032594,-0.102751,0.798840,0.284383,0.018314,0.579880,0.325408,0.298441,-0.000135,0.607489,-0.149591,0.029903,-0.385312,0.049820,-0.391230,-0.046698,0.155982,-0.129894,-0.086623,0.269139,-0.170738,0.536065,0.464734,0.021855,-0.317291,-0.134208,0.288842,-0.509851,-0.271013,0.429542,0.155087,-0.096516,0.166788,0.198441,-0.260387,-0.157881,0.064811,0.112298,-0.479504,0.299615,0.307740,-0.030864,-0.718387,0.479760,0.068456,-0.125081,0.029459,-0.391803,0.409732,0.385696,0.280829,0.479305,-0.414186,-0.104812,-0.543001,0.063968,0.795753,-0.190961,-0.175329,0.119662,-0.563887,-0.077757,0.075062,-0.496867,-0.596198,0.004511,-0.090490,0.203167,-0.460667,0.375129,-0.492050,-0.104641,-0.169975,-0.047490,0.089400,-0.502675,0.003703,-0.139450,-0.341336,-0.553436,-0.584894,0.018536,0.239502,-0.150420,0.579642,-0.773677,0.199613,0.142451,0.530958,-0.605452,0.557064,0.390102,-0.079516,-0.170876,0.049779,0.426570,0.009106,0.119728,-0.000951,0.075590,-0.068721,0.132011,-0.214162,0.612116', '35030151', '25721544', '1301022', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1323746', '小城之春', '剧情', '1948年前后，中国某个平常的遍处皆是断垣颓壁的南方小城里，年轻少妇周玉纹（韦伟 饰）与生病的丈夫戴礼言（石羽 饰）过着索然寡味的日子。战争不仅令礼言失去了家产，也使他丧失了生活的信念。而玉纹每日做的，是在早晨出门买菜、给礼言抓药，在城头踱步好大一会后伤神地复回到家中，将药丢于他时与他对话不过三两句，剩下大半时日，是坐在妹妹戴秀（张鸿眉 饰）房间绣花独自喟叹——除了早晨出门徘徊的城墙头，这是她认为的小城唯剩的有生气之地。章志忱（李纬 饰）的到来打破了死气沉沉的一切。他是礼言昔日好友，却也是玉纹的旧时情人。与礼言死气的阴郁形成对比的是，志忱年轻健康有朝气，这令本是小城异类的戴秀对他暗生情愫，但志忱心中一直没忘玉纹，而他无疑也是玉纹内心的渴望和呼唤。发乎情止于礼，志忱和玉纹之间欲迎还拒、欲拒还迎的心理角逐游戏连番上演时，礼言和戴秀窥见了个中端倪。©豆瓣', '李纬', '费穆', 8.7, 50746, 'tt0189219', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2029605819.jpg', 0.2, 0.7, 10, 43.5, 45.6, '0.119780,-0.039038,-0.674500,0.365631,-0.127684,-0.111037,0.738875,0.237986,-0.557894,-0.181373,0.014206,0.611443,-0.254711,0.353719,0.170469,-0.164590,-0.124281,-0.728259,-0.250878,-0.030744,-0.129782,-0.125262,-0.083263,-0.102758,-0.157825,-0.482291,0.391310,0.179361,-0.202306,0.521920,0.243052,0.191693,-0.054629,0.593599,-0.336505,0.025832,-0.360220,0.161781,-0.129960,-0.052047,0.108459,-0.333670,-0.470688,0.058149,-0.002698,0.472779,0.623816,-0.113622,-0.216197,0.061496,0.235356,-0.203454,0.042268,0.165163,0.098937,-0.030637,0.059212,0.245408,-0.268456,0.116279,0.127317,-0.016573,-0.409857,0.079474,0.133660,-0.025402,-0.634699,0.733023,-0.007493,-0.310299,0.069208,-0.220090,0.268544,0.227223,0.011344,0.493612,0.060379,-0.144636,-0.697886,0.155517,0.452629,0.185210,-0.194678,0.434660,-0.270056,-0.391519,0.095150,-0.239285,-0.367780,-0.164935,0.091140,0.153738,-0.054533,0.028520,-0.540890,0.254224,-0.100747,-0.153513,0.222239,-0.438864,-0.312891,-0.330491,-0.238168,-0.754227,-0.465562,0.146336,0.192361,-0.025006,0.592583,-0.735469,0.171485,0.319490,0.243154,-0.480706,0.835205,0.149839,-0.019515,0.036400,0.184983,0.025306,-0.231737,0.250830,0.227354,0.271345,-0.259549,0.040202,-0.559030,0.492402', '24839498', '1304989', '3055049', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1323749', '青春梦工场', '剧情', '名大学生阿肥（周振辉饰）、胶布（曾国祥饰）、Jason（黄又南饰）与志安（周俊伟饰）还有几个月就要毕业离校了，但他们并没有想到工作和社会的事情。他们一个同学阿乐，因为“借拍戏沟女事件”，传遍整个电影学院，惊动了校方，竟在临毕业前被勒令退学。四人忽发奇想，决定重搬演练，大搞一番。他们打算筹到三十万，从日本请得一个心爱的AV女星（天宫真奈美饰）过来，然后通过拍戏和她发生关系。四人尝试一切方法，申请青少年自雇计划贷款、学生奖学金、卖出摄制职位等模式去筹募资金，进行他们“假拍片、打真军”的疯狂计划，最终他们能够成功吗？©豆瓣', '黄又南', '彭浩翔', 8, 48674, 'tt0452931', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164738461.jpg', 0.5, 2.4, 22, 48.9, 26.2, '-0.083534,-0.020569,-0.446207,0.280957,-0.061524,-0.183354,0.064474,-0.070823,-0.183945,-0.511782,-0.276346,0.365341,-0.313464,0.155728,0.153085,-0.398349,-0.411387,-0.724288,0.210308,-0.276995,-0.240497,-0.248110,0.367320,-0.147845,-0.183855,0.041810,0.542363,-0.006414,0.048604,0.356895,0.191902,-0.088842,-0.033366,0.188096,0.070750,-0.115302,0.297751,0.118252,-0.439477,0.441625,-0.028094,-0.054301,-0.303258,-0.078013,0.475927,0.236065,0.524155,0.354940,-0.256866,0.116948,0.259955,-0.128753,-0.150414,0.237637,0.431660,0.263799,0.300318,0.217913,-0.303067,0.152532,0.117164,-0.384756,-0.435670,0.046345,-0.070344,-0.047725,-0.377067,0.213552,-0.037932,0.292304,-0.138154,-0.409976,-0.176609,0.559519,0.288094,0.253767,-0.031375,0.112727,-0.332186,0.417812,0.628632,-0.299568,-0.011790,0.298419,0.212142,-0.390487,-0.110709,0.072625,0.037761,0.235303,0.286545,-0.089800,-0.272240,-0.042808,-0.245898,-0.239976,-0.235337,-0.417467,-0.081664,-0.158360,0.184431,-0.789373,0.079982,0.151923,-0.310151,0.188443,0.301654,-0.197848,0.426961,-0.607311,-0.034231,0.442417,0.408650,-0.918584,0.255842,0.181918,0.199464,-0.172346,-0.059799,-0.414603,-0.005235,0.550742,0.218210,0.171642,0.084626,-0.344280,-0.051846,0.060321', '25723905', '2369613', '1482541', '4193254');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1325005', '大鸿米店', '剧情', '五龙（陶泽如 饰）逃荒进城凭着一身蛮力做了大鸿米店的伙计，食量惊人的他惹来了米店冯老板和大女儿绮云（杨昆 饰）的百般刁难，而自小便作了六爷姘妇的小女儿织云（石兰 饰）却见他总是笑逐颜开，白天到处受人欺负的五龙只有晚上躺在米仓里大口大口的嚼生米时才能感觉到踏实。偶然一次机会，让五龙发现织云和六爷的手下阿保在一起鬼混，为了报复阿保平日里对自己的欺辱，五龙偷偷向六爷告发，后来阿保就被人给捅了。初尝报复带来的快感让五龙兴奋的彻夜无眠，而生性风流的织云对他的百般勾引又令他完全迷失。从此，五龙便开始对身边欺负自己的一个个城里人疯狂的报复……本片由著名作家苏童的小说《米》改编，于1995年摄制完成后因被认为宣扬人性恶论而被称为灰色电影，雪藏七年后才得以解禁。©豆瓣', '陶泽如', '黄健中', 6.9, 23495, 'tt0456911', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554575054.jpg', 2, 9.5, 41.8, 33.9, 12.8, '0.029603,-0.043820,-0.633225,0.455637,-0.236318,-0.428479,0.564898,0.294766,-0.772552,0.013789,0.154817,0.586677,-0.377224,0.183215,0.334542,0.107697,0.060819,-0.749319,-0.047462,-0.113963,-0.096790,-0.081719,-0.075465,-0.183565,-0.018791,-0.170400,0.041507,0.000402,-0.236625,0.523618,0.329535,0.103904,0.060638,0.393716,-0.151065,0.049105,-0.172576,-0.068421,0.101932,0.204111,0.151494,-0.533645,-0.148379,0.136620,-0.134627,0.214186,0.680474,-0.356566,-0.262261,-0.350433,0.348791,-0.192482,-0.116544,0.230476,0.143216,-0.064319,0.315987,0.068895,-0.273897,0.079954,0.172151,0.108162,-0.661076,0.191386,0.091091,-0.084344,-0.581863,0.499841,0.069788,-0.054504,0.148709,-0.347946,0.158255,0.259912,0.180618,0.441836,-0.241706,-0.041515,-0.572506,0.270173,0.379776,-0.247795,0.151866,0.247331,-0.003181,0.080182,0.244521,-0.360634,-0.411503,-0.148238,0.329981,0.083898,-0.265639,0.036849,-0.474822,-0.022485,-0.193036,-0.131953,0.083337,-0.208658,-0.179918,-0.446265,-0.265196,-0.399834,0.005711,0.061552,0.164002,-0.170412,0.536316,-0.593723,0.430849,0.550607,0.306435,-0.613718,0.515584,0.092675,-0.136876,0.035265,0.060920,-0.128648,0.232921,0.400712,0.417465,0.394396,-0.125093,-0.064562,-0.247517,0.348663', '1301022', '3111650', '21360412', '1293607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1325399', '狼的诱惑', '剧情', '苦命女孩郑汉景（李青儿 饰）父母早年离异，一起生活的父亲突然病故，所以她孤身一人来到汉城投靠妈妈。不想，她却在地铁站里目睹了两股校园帮派的火拚，为首的两个帅哥竟然先后走入了她的生活中。其中，霸道蛮横的班海沅（赵瀚宣 饰）是个花花公子，但是因为汉景的出现使其性格发生了转变。温文尔雅的郑泰成（姜东元 饰）是个懂得体贴的谦谦君子，对汉景关怀备至。两个帅哥为了争夺女孩展开了一场拉锯战，不但醋意十足，而且大打出手。一时间，女孩成为学校间的风云人物，遭到了不少异性的排挤和非议。单纯的汉景经常会产生幻想和错觉，然而当两个追求者的身份曝光后，女孩才发现了现实竟然如此巧合，又如此残酷……©豆瓣', '姜栋元', '金泰均', 6.9, 51674, 'tt0416073', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1219015659.jpg', 1.4, 8.4, 48.3, 29.6, 12.3, '0.415977,0.062111,-0.664545,0.526774,-0.239665,-0.152162,0.949585,0.177492,-0.685733,-0.382470,0.242502,0.657468,-0.367315,0.349355,0.266442,-0.310302,0.050071,-0.703708,-0.245048,-0.077784,-0.189357,-0.154111,-0.340690,0.090047,-0.267113,-0.206583,0.480621,-0.041516,-0.301893,0.408705,0.514301,0.320409,-0.177199,0.583737,-0.174033,-0.001067,0.103749,0.402984,-0.102509,0.089349,-0.107860,-0.263516,-0.083235,0.150682,-0.268868,0.153108,0.785538,-0.198282,-0.275705,-0.324555,0.671797,-0.081503,-0.378586,0.121224,0.451435,-0.067980,0.473353,-0.142428,-0.044414,-0.164595,0.090203,-0.016017,-0.373462,0.210859,0.171871,-0.008224,-0.564292,0.224303,0.232445,-0.259975,0.001393,-0.198940,0.036542,0.300065,0.420051,0.324648,-0.168687,0.084226,-0.380422,-0.117392,0.873181,-0.010198,-0.401643,0.425788,-0.328373,-0.278500,0.165028,-0.368070,-0.620172,0.175063,0.074280,-0.252890,-0.011451,0.383111,-0.552089,0.031921,-0.370152,0.318842,0.042898,-0.419911,-0.287204,-0.409872,-0.364147,-0.498376,-0.296895,0.201799,-0.076809,-0.167287,0.796678,-1.012141,0.099039,0.371252,0.167239,-0.818190,0.554942,0.219051,-0.092209,-0.262138,-0.056520,0.175292,0.032569,-0.203920,-0.078582,0.458395,-0.266669,-0.065845,-0.064433,0.291785', '1301022', '1308755', '1293265', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1325958', '蒂凡尼的早餐', '剧情', '清晨的纽约街头，相貌清丽的女子霍莉（奥黛丽·赫本 Audrey Hepburn饰）在橱窗前徜徉，她就是纽约上流社会的交际花。对金钱和物质的崇拜，同时却不失天真善良的霍莉，就像是纽约的“茶花女”，靠着每小时五十、一百的费用来获得交际收入。在她心里，还有一个重要的目标，那就是嫁得金龟婿。霍莉的新邻居是一个作家保罗（乔治·佩帕德 George Peppard饰），梦想着成名，却也是依靠富太太的供给度日。遇见霍莉的保罗堕入情网，千方百计让霍莉过回正常生活，并向她求婚。然而，霍莉似乎并不愿意，在她心中，嫁给这么一个人，放弃她之前的努力，未免太不值。然而，霍莉在寻找幸福路上跌跌撞撞，直到有一天才突然明白了幸福的含义。©豆瓣', '奥黛丽·赫本', '布莱克·爱德华兹', 8.1, 223605, 'tt0054698', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1114467603.jpg', 0.3, 1.7, 20.8, 47.8, 29.4, '0.048588,0.143333,-0.697369,0.539287,-0.218292,-0.517492,0.939929,0.069589,-0.287962,-0.117071,0.159561,0.690358,0.022711,0.320072,0.346679,0.289176,-0.171639,-0.462469,0.079417,-0.323392,-0.002260,-0.425478,-0.313602,-0.271316,0.012097,-0.316649,0.555587,0.211737,0.089525,0.444348,0.400061,0.221993,0.222713,0.548733,-0.453337,0.042960,0.002607,0.114900,-0.246810,0.240180,-0.021705,-0.129888,-0.189746,0.046744,0.000153,0.288621,0.477320,-0.107488,-0.202220,0.197749,0.478642,-0.137867,-0.176522,0.017909,0.081797,-0.123702,0.239195,0.053824,-0.187035,0.087459,0.214869,-0.149936,-0.761607,0.013935,0.117867,0.221284,-0.635087,0.411777,-0.064616,-0.206073,0.105114,-0.276361,0.058076,0.024484,0.069482,0.422233,-0.166290,0.326528,-0.695837,0.326674,0.613994,0.199085,-0.252707,0.680139,-0.437962,-0.500364,-0.004703,-0.355067,-0.614770,-0.066829,0.068254,0.061049,-0.013921,-0.003867,-0.470913,0.250760,-0.128449,-0.107914,0.243751,-0.659847,-0.155297,-0.373672,-0.087492,-0.427423,-0.405976,0.189868,0.089321,-0.411281,0.823899,-0.766113,0.196836,0.881237,0.349527,-0.424019,0.837963,0.154523,0.065082,-0.112793,-0.011413,0.317917,-0.072529,0.216154,-0.207720,0.309450,-0.037619,0.051039,-0.407840,0.745251', '3230462', '1304641', '1432669', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1326208', '一线声机', '动作', '高中自然课女教师杰西卡（金•贝辛格 Kim Basinger 饰）被绑架了，幸好歹徒囚禁她的地方放置有一部老式的拨号电话。杰西卡慌乱之中随便拨了一个号码进行求救，她的求救电话打到了小伙子瑞恩（克里斯•埃文斯 Chris Evans 饰）的手机上。瑞恩一开始以为是恶作剧，但随后歹徒发现了杰西卡在向外求救，砸坏了电话。听到歹徒的吼叫和杰西卡惊呼，瑞恩才意识到事态严重。杰西卡在歹徒走后利用她的自然课知识重新拼装好了电话，重新和瑞恩取得了联系。通过她的讲述，瑞恩得知歹徒很快就会对她的丈夫和儿子下毒手，而杰西卡连自己身处的位置都不知道。留给瑞恩的时间已不多，何况他的手机电量有限。瑞恩必须尽一切努力去挽救杰西卡一家的性命。©豆瓣', '卡罗琳·阿隆', '大卫·R·艾里斯', 7.3, 25305, 'tt0337921', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p848105485.jpg', 0.5, 3, 38.2, 46.6, 11.6, '0.255858,0.105170,-0.591067,0.540575,-0.231767,-0.229257,0.558505,-0.122726,-0.088257,-0.200673,0.053500,0.589165,0.094452,0.190514,0.254585,0.025038,-0.479522,-0.768204,0.104441,-0.130843,-0.572552,-0.629617,-0.222627,-0.197818,0.141752,-0.268142,-0.058646,-0.231799,-0.316149,0.338057,0.067623,0.062863,-0.076789,0.671598,0.110718,0.406351,0.003042,-0.256021,0.031226,0.133854,0.272995,-0.472150,-0.047896,0.282913,0.172087,0.691465,0.512412,-0.037248,0.064448,0.061171,0.196523,-0.070976,-0.177211,0.036376,0.330848,0.175853,0.167162,-0.149882,-0.513996,0.080303,0.276656,0.155414,-0.400536,0.078727,-0.354574,0.030117,-0.373728,0.318206,-0.388502,0.225476,0.183829,-0.383671,0.328919,0.153488,-0.075827,0.367160,-0.055095,-0.029830,-0.453589,0.055581,0.221609,0.009222,0.152084,0.410284,0.178378,-0.316294,-0.177201,0.103526,-0.633957,-0.058440,0.853693,0.143043,-0.387335,-0.194214,-0.250718,-0.282015,-0.312062,-0.391184,0.111651,-0.644962,-0.388683,-0.583828,-0.186168,-0.016081,-0.357329,0.000950,-0.104801,-0.249157,0.714145,-0.926586,-0.231805,0.524428,0.115188,-0.252212,0.473937,-0.052988,0.079686,-0.062309,0.203990,0.073661,0.235166,0.670216,0.289618,0.125898,-0.171662,-0.123230,-0.499231,0.299631', '21360417', '3044878', '2976072', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1328665', '笑之大学', '剧情', '故事发生在1940年秋的日本。政府在战时为了加强文化监管，在警察局设立了演剧检查科。刚从中国东北伪满洲国调来的审查官向坂（役所广司 饰）是个不苟言笑、不通情理的铁面判官，他掌握着演剧剧本的生杀大权。笑之大学剧团的喜剧作家椿一（稻垣吾郎 饰）带着他的剧本来到了向坂的调查室，一场喜剧剧本的搞笑升级拉锯战由此拉开了帷幕。故事发生在七天的时间里，每天向坂的恶意刁难都层层升级，一个个无理的要求向编剧椿一逐个抛出，椿一见招拆招努力应对的同时却创造出了前所未有的精彩喜剧剧本。连一向厌恶喜剧、希望喜剧从地球上消失的向坂都迷失了初衷，渐渐陶醉在椿一搞笑故事中。甚至帮助椿一修改剧本，使剧本的搞笑程度达到了又一个高峰。然而俩人的政治立场决定二人最终走向了对立，向坂向椿一使出了杀手锏，椿一是否能完成这个不可能完成的任务呢......本片在2005年的日本电影学院奖上获得了最佳编剧和最佳男演员的提名。', '役所广司', '星护', 8.5, 19234, 'tt0436886', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p886358101.jpg', 0.5, 1.3, 12.7, 41.7, 43.9, '0.215123,0.048330,-0.601222,0.794672,0.254837,-0.267015,0.634082,0.087008,-0.116832,0.047774,0.256946,0.787354,-0.462259,-0.078119,0.415397,-0.079955,-0.332879,-0.809581,-0.384569,-0.162861,-0.337823,-0.434003,-0.240412,-0.107495,-0.117639,-0.446956,0.508814,0.047877,-0.385168,0.135647,0.563769,0.029269,-0.056141,0.227007,0.305722,0.052568,0.110405,-0.029678,-0.029600,0.413810,0.053757,-0.403982,-0.481425,0.157752,0.007202,0.400482,0.950021,-0.269400,-0.293357,0.195840,0.489470,-0.313168,-0.374015,0.119273,0.170524,0.036388,-0.022930,0.201281,-0.175828,0.253155,-0.019323,-0.274760,-1.104090,-0.160482,-0.167906,0.338715,-0.362463,0.287687,-0.114437,0.091063,-0.015625,-0.535168,0.197207,0.470226,0.438124,0.565640,-0.427675,0.188676,-0.285274,0.535642,0.494164,0.114066,-0.368844,0.496242,-0.211963,-0.492208,-0.400290,-0.030500,-0.217305,-0.205016,0.534421,-0.194605,0.035770,-0.086214,-0.452144,-0.171361,0.083386,-0.389518,0.021795,-0.407632,0.023168,-0.578301,-0.044377,-0.194207,-0.294246,0.027505,0.139270,-0.347147,1.043062,-0.735332,0.013514,0.617488,0.044438,-0.331999,0.525939,0.261887,0.039621,-0.021143,0.125327,-0.148543,0.006777,0.546695,0.300013,0.698190,-0.050947,-0.490080,-0.455220,0.409641', '27602116', '25928048', '24284209', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1329286', '公主复仇记', '剧情', '周筱兰（陶红饰）在KTV工作，与男友阿ken（吴彦祖饰）感情甚浓。一天晚上，有一个年轻女仔找她，原来是Ken的前女友陈蕙贞。陈蕙贞向周筱兰大吐苦水，并想让周了解Ken的用情不专及恶劣行为。开始周筱兰对陈蕙贞的话还是半信半疑的，但后来出于同样是女性的考虑，周筱兰开始渐渐相信陈蕙贞的话，并且联合一起对付负心汉阿ken，令阿Ken处处碰壁。阿Ken得到惩罚后，陈蕙贞向周筱兰说出了所有事情背后的真相。©豆瓣', '钟欣潼', '彭浩翔', 6.8, 25727, 'tt0440445', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1405113348.jpg', 1.2, 8.4, 47.1, 34.6, 8.7, '0.211748,0.012149,-0.660625,0.733278,-0.018690,-0.295095,0.386672,-0.203985,-0.535864,-0.714475,-0.383242,0.106519,-0.181971,0.264040,-0.099484,-0.131474,-0.311907,-0.519385,-0.073540,-0.176826,-0.389371,-0.928525,0.288397,-0.355204,-0.404725,-0.038994,0.375963,0.207456,-0.551561,0.163304,0.596529,0.445318,0.359699,0.764854,0.151801,-0.425800,0.022673,0.325159,-0.333030,0.226557,0.626543,-0.117166,0.051009,0.377542,0.062196,0.387054,0.420423,-0.264737,-0.526596,0.028670,0.519242,-0.209671,0.135973,0.146038,0.478776,-0.070616,0.276290,0.103504,-0.131730,-0.154149,0.172703,0.019170,-0.421575,-0.157754,0.315892,-0.099187,-0.540513,-0.264429,-0.091880,-0.006916,0.149401,-0.078623,0.315781,0.526027,0.715572,0.373888,0.187103,0.123459,-0.425556,-0.150127,0.953646,0.261807,0.118361,0.158681,-0.130930,-0.671042,0.102299,0.169003,-0.232657,0.332087,-0.234010,0.095361,0.055957,0.380049,-0.197026,-0.074078,0.007880,0.118230,0.236429,-0.815231,0.226146,-0.116421,-0.289923,-0.365543,-0.139768,0.045939,0.116744,-0.391852,0.728204,-1.043706,0.259036,0.435551,0.544046,-0.917424,0.631257,0.393975,-0.209949,-0.497435,0.215643,0.149557,-0.050632,-0.433983,0.319801,0.194970,0.320879,-0.238901,-0.013406,0.285229', '27000061', '1293265', '1305915', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1329562', '头文字D', '剧情', '每天清晨都有一辆AE86在秋名山上漂移，而且速度快得惊人，这辆AE86属于藤原豆腐店。藤原拓海（周杰伦 饰）每天清晨都要帮父亲藤原文太（黄秋生 饰）把自家店里的豆腐送到秋名山上的旅店，但这并不是拓海想做的一件事。拓海还会在阿木（杜文泽 饰）家开的加油站做兼职。中里毅（余文乐 饰）向阿木的车队挑战，当中里毅在秋名山练习的时候，竟然被一辆AE86轻易爬过头，中里毅决定打听这辆AE86的消息，要跟他比赛一番。©豆瓣', '周杰伦', '刘伟强', 7.7, 367554, 'tt0439630', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171302998.jpg', 0.6, 3.4, 29.6, 41.3, 25.1, '0.518949,0.209279,-0.294064,0.371575,0.158543,-0.311779,0.144866,0.141908,-0.531508,-0.366409,0.038361,0.408780,-0.218073,0.077404,0.161849,0.050447,-0.201207,-0.508382,0.036683,-0.067484,-0.404706,-0.309110,0.169041,-0.180771,0.160230,0.261920,0.146267,0.092104,-0.107978,0.349279,0.415494,-0.074750,0.071586,0.315431,-0.231816,-0.067461,-0.179807,0.207133,0.253194,0.384787,-0.197025,-0.511797,-0.118354,0.054608,0.454504,0.213790,0.624811,0.119417,-0.400582,0.040140,-0.012091,-0.036277,0.204532,0.045436,0.290840,-0.103949,0.087820,0.157639,-0.109911,0.117331,0.095067,-0.098788,-0.581883,0.060267,-0.061764,-0.125129,-0.790672,-0.008125,-0.280695,-0.019571,-0.007989,-0.708018,0.325845,0.120212,0.108191,0.211625,-0.241203,-0.185891,-0.476019,0.233694,0.510710,0.073054,0.340664,0.357513,-0.183871,-0.248755,-0.361849,-0.139881,-0.434169,-0.091534,0.146680,-0.086831,-0.002523,-0.383308,-0.504236,-0.095947,0.112760,-0.362819,-0.116263,-0.037539,-0.097899,-0.525601,0.538579,-0.626385,-0.172804,0.394363,0.131639,-0.102730,0.286538,-0.603941,0.240205,0.437796,0.125704,-0.198075,0.716518,-0.372370,-0.196811,-0.093467,-0.173922,-0.082915,-0.009560,0.216724,-0.095771,0.545934,0.124940,-0.448122,-0.488549,0.436887', '26769480', '2080130', '2124718', '26322792');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1329936', '大内密探零零发', '喜剧', '零零恭、零零喜、零零发（周星驰 饰）、零零财是宫廷四大高手，专职保卫皇帝（张达明 饰）的安全。虽号称四大高手之一，零零发实际上只会搞些小发明完全不会武功，某次因为未完成皇帝交办的捉拿江湖四大怪杰的任务，他被开除出宫。回家后，零零发开了一家妇科诊所，时常会用一些小发明讨得老婆（刘嘉玲 饰）心花怒放，日子也算怡然自乐。 金国以“天外飞仙”尸体为由将皇帝从宫中骗出，并伺机杀死了紧跟皇帝的三大高手，关键时刻，零零发用他发明的“直升机”和“机关枪”救皇帝一命。不死心的敌手随后派来名妓琴操（李若彤 饰）引诱零零发，零零发与老婆将计就计演起双簧。©豆瓣', '周星驰', '谷德昭', 8, 353077, 'tt0116014', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2455844666.jpg', 0.2, 1.6, 23.2, 48.9, 26, '-0.017531,0.034609,-0.200614,0.706214,-0.120930,0.146219,0.105476,0.109131,-0.590825,-0.484031,0.342025,0.657080,-0.211515,-0.249566,0.171594,-0.271565,0.045321,-0.371738,-0.029578,-0.177114,0.027554,0.007120,-0.157367,-0.421001,-0.274744,-0.217458,0.374943,-0.129107,-0.009554,0.286210,0.439911,0.295156,-0.152419,0.071482,-0.249488,-0.037567,-0.121500,-0.134680,-0.109806,0.516447,-0.198354,-0.482906,-0.100235,-0.096950,0.012660,0.266216,0.303271,-0.050158,0.139949,-0.215259,0.007312,-0.211551,-0.101962,-0.104926,0.307026,-0.159317,0.298957,0.351993,-0.058303,0.147009,0.130390,-0.019120,-0.841568,0.085772,0.314298,-0.282448,-0.397949,0.132807,-0.556909,0.125164,-0.156491,0.016711,0.391919,0.286978,0.340970,0.252018,-0.012840,0.091563,-0.575531,0.481915,0.272482,-0.143970,0.304856,0.207435,0.450469,-0.259669,0.096815,-0.677129,0.063260,0.022871,0.185292,-0.132972,-0.012170,0.041438,-0.151657,-0.367735,-0.185099,0.061135,0.163898,-0.115583,0.265408,-0.393649,0.405833,-0.219970,-0.086308,-0.022676,0.428543,-0.187708,0.552710,-0.466396,-0.009173,0.255779,-0.099005,-0.879036,0.403456,0.120133,0.113207,-0.220201,-0.179797,-0.360849,0.294627,0.317349,0.366666,0.435287,-0.092939,-0.753303,-0.126603,0.021631', '3670447', '1302110', '1304382', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1329938', '美人依旧', '剧情', '因为父亲的遗嘱，离家十五年的小菲（周迅 饰）被同父异母的姐姐璎子（邬君梅 饰）派人接回了家。小菲母亲的低微出身让小菲从小便立誓要作一个有出息的女人，然尔姐姐那种高高在上的贵族气质对小菲同样充满了诱惑，小菲慢慢的习惯了有姐姐的日子，她似乎又找到了家的感觉。当小菲得知姐姐只是想利用她拿到遗产然后和自己的爱人黄先生（王志文 饰）出国时，小菲陷入深深的失望，她不想失去姐姐和失而复得的家。此时，多情的黄先生流露出的暧昧让小菲找到了报复的缺口，然而报复和欲望并没有带给她所期望快感……©豆瓣', '周迅', '胡安', 6.1, 7153, 'tt0399048', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2374874111.jpg', 3.6, 16.9, 53.7, 20.2, 5.5, '0.297019,0.050330,-0.580727,0.716697,-0.365001,-0.518757,0.866699,0.193403,-0.633586,-0.262236,-0.001666,0.720706,0.121412,0.470608,-0.049016,0.324655,0.000276,-0.604922,-0.102671,-0.152459,-0.052805,-0.357151,-0.027854,-0.074526,0.098103,-0.420521,0.628168,0.046238,-0.188661,0.442135,0.162735,0.216487,0.092542,0.584494,-0.276952,0.138340,-0.141893,0.328191,-0.389839,0.053121,0.347895,-0.074759,0.019831,0.414246,-0.012509,0.244772,0.501366,-0.179053,-0.210758,-0.059547,0.271533,-0.118123,0.022907,0.059697,-0.121904,-0.087895,0.157937,0.132132,-0.328915,-0.289130,0.239395,-0.020777,-0.660501,0.087120,0.356608,-0.126026,-0.572937,0.458953,-0.125155,-0.134334,0.285549,-0.222828,0.332030,0.192184,0.083466,0.463960,-0.505097,0.121630,-0.584202,0.098032,0.680471,-0.157211,0.123666,0.289656,-0.334337,-0.288694,0.270849,-0.318356,-0.561606,0.233612,0.222037,0.225964,-0.418457,0.135920,-0.536774,-0.272384,-0.086390,0.043862,0.135505,-0.869206,0.041718,-0.033566,-0.445849,-0.493032,-0.359656,0.016565,0.136648,-0.346470,0.712063,-0.856428,0.471021,0.309449,0.386285,-0.835128,0.708326,0.109892,-0.320838,-0.293965,-0.143623,0.213742,-0.204190,-0.084841,0.266025,0.157331,-0.213567,-0.037730,-0.305804,0.490360', '1949320', '1296569', '25721544', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1329950', '达·芬奇密码', '悬疑', '卢浮宫博物馆馆长被人杀害在卢浮宫内，临死前他费力的留下骇人的符号，从而惊动了符号专家罗伯特·兰登（汤姆·汉克斯）。在破案过程中，兰登结识了死者的孙女，索菲（奥黛丽·塔图），俩人几次遇险，九死一生，逐渐产生爱慕之情。随着案情的深入，他们渐渐发现这起谋杀案后隐藏着天大的秘密，甚至牵连到隐匿多年的神秘组织——峋山隐修会。兰登按图索骥，发现所有的解密的密码都藏在达芬奇的作品中，而最让人震惊的是，索菲的身世一时间随之复杂起来，她究竟是谁？峋山隐修会再现江湖想要达到什么目的？©豆瓣', '汤姆·汉克斯', '朗·霍华德', 7.4, 236461, 'tt0382625', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p453938430.jpg', 0.5, 3.7, 35.6, 44.1, 16.1, '0.317968,-0.104263,-0.853922,0.584711,-0.026290,0.023774,0.688111,-0.251936,-0.898098,-0.337568,0.334176,0.597547,-0.390871,0.130279,0.014718,0.049850,-0.271695,-0.568471,0.056455,-0.601997,-0.466016,-0.610602,-0.446915,-0.331067,0.048513,-0.394605,0.322504,0.303783,-0.116065,0.034293,-0.023626,0.491092,-0.612174,0.240798,0.141133,0.184205,0.372568,-0.258595,-0.178969,-0.049858,-0.030557,-0.197646,-0.405841,0.223980,-0.316802,0.387061,0.529493,-0.211485,-0.252807,0.228412,0.288302,-0.377978,-0.145515,-0.113416,0.166188,-0.019448,-0.002232,0.544606,-0.273421,-0.116807,0.085527,0.278022,-0.794171,0.031645,0.277218,0.427506,-0.249934,0.217872,-0.109407,-0.115384,-0.045127,-0.318669,0.244307,0.256677,-0.004106,0.076530,0.082561,-0.067936,-0.436953,0.175913,0.287976,-0.152849,-0.141818,0.204285,-0.195687,-0.216067,-0.123832,-0.072003,-0.206446,-0.025155,0.554719,0.078320,-0.057641,0.594751,-0.440843,-0.214621,-0.223856,-0.130702,-0.095292,-0.192730,-0.177571,-0.525536,-0.588648,-0.108585,-0.111681,-0.347295,-0.208678,-0.352134,0.640936,-0.540829,0.379150,0.690757,-0.146162,-0.257997,0.451865,-0.146992,-0.133059,0.051026,-0.545813,0.068888,0.305682,0.304467,-0.035581,0.254620,0.154596,-0.122642,-0.213267,0.254988', '25932086', '26908280', '1947080', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1329962', '早熟', '剧情', '出生于草根家庭的家富（房祖名饰）父亲（曾志伟饰）是小巴司机，母亲（毛舜筠饰）是一个酒楼接待员。虽然出身寒微，却享受了家庭温暖。他跟同学去了一所女子名校，无意间看到了若男（薛凯琪饰），更假扮名校学生到该女校联谊。若男的父亲（黄秋生饰）是一个律师，母亲（余安安饰）是公益积极 分子。一直对若男管教严厉，也很少留在女儿身边。当若男遇到了好动的家富后，便很快被他吸引了。在若男18生日当晚，他们两人到郊外露营，偷吃了禁果。若男得知自己怀孕后，便与家富商量要打掉孩子，眼看着那些恐怖的工具，与家人大吵一架后，决定躲到好友的祖屋直到孩子出生。独自生活后家富才发现供养一个家庭的不容易，两人开始有了分歧。家富父母好不容易找到了两人，可是若男父亲要状告家富强奸未成年少女，看着不足月出生的外孙，他又会否手下留情呢？©豆瓣', '房祖名', '尔冬升', 6.7, 65716, 'tt0457004', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486587306.jpg', 1.1, 8.3, 54.6, 29.2, 6.9, '-0.011725,-0.242342,-0.471204,0.244767,-0.337676,-0.408886,0.690132,0.315675,-0.556615,-0.149249,0.111652,0.721646,-0.113851,0.441780,0.393240,0.185071,-0.233704,-0.463416,0.115803,-0.292005,-0.372236,-0.148361,0.188220,-0.054072,0.000238,-0.179422,0.337949,-0.232212,0.042364,0.269525,0.293838,-0.000996,-0.206767,0.385216,-0.390489,-0.048423,-0.131268,0.252140,-0.186309,0.262726,0.123463,-0.176187,-0.137314,-0.151807,0.179930,0.342908,0.661521,-0.065663,-0.184338,-0.333048,0.207838,0.047685,-0.111585,0.308638,0.431928,-0.211784,0.606889,0.100164,0.003337,-0.195010,0.142484,-0.057423,-0.093297,0.184542,0.300575,-0.178773,-0.445853,0.492199,0.194035,-0.293486,0.060609,-0.262550,0.092821,0.295179,-0.064358,0.377828,-0.218758,0.030213,-0.347923,0.319745,0.562995,0.060587,0.090919,0.236876,0.100680,-0.438205,0.281046,-0.147921,-0.752821,0.224035,0.276893,0.123897,-0.393287,0.009229,-0.191403,-0.039544,-0.115624,0.304243,0.203996,-0.419107,-0.008330,-0.275542,0.078164,-0.088728,-0.278623,0.294716,0.297706,-0.046375,0.769486,-0.904162,0.106853,0.423668,0.444001,-0.812288,0.490991,0.043055,0.193801,-0.271891,-0.006930,-0.026353,0.127378,0.237978,0.006975,0.357235,-0.153567,-0.337609,0.050088,0.073948', '3445516', '6963575', '1292219', '4739952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1340517', '初吻', '喜剧', '薇卡（苏菲•玛索 饰）是个13岁的女孩，不同于班上的其他同学父母离异的状况，她拥有一个完整的家庭，虽然她总是觉得被母亲忽略，伴随青春期到来的，除却敏感的对父母之爱的需要，还有对异性情感的渴望。然而，父母的感情出现了裂痕，母亲与薇卡的德语老师燃起了爱火花；而在舞会上认识的拉乌尔，让她感受到初恋的美好同时也领会了爱情的伤害。有了初吻之后，爱情就能保鲜吗？13岁的初恋能持续到多久？苏菲•玛索凭借此片成为欧洲影坛著名的小明星。©豆瓣', '克洛德·布拉瑟', '克洛德·皮诺托', 8.1, 137870, 'tt0082100', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1467014754.jpg', 0.3, 1.5, 21.3, 48.7, 28.2, '0.474276,0.092067,-0.884218,0.730650,-0.241523,-0.066704,0.941712,0.043890,-0.256014,-0.088429,0.256855,0.856513,-0.385106,0.567189,0.271484,0.015378,0.173623,-0.906275,0.214886,-0.266551,-0.422347,-0.446226,-0.152071,0.208222,-0.305842,-0.589859,0.640860,-0.021700,-0.155811,0.469920,0.218793,0.128475,0.165208,0.479107,-0.077686,0.055542,0.027560,0.272069,-0.276038,0.173101,0.270637,0.082182,0.228040,0.314644,-0.281575,0.353945,0.774056,-0.282581,-0.116414,0.217792,0.615975,-0.125446,0.028578,0.171892,0.139665,0.041730,0.210044,-0.000698,-0.160999,0.009780,-0.025923,-0.011560,-0.793136,-0.061163,0.058106,0.151285,-0.657663,0.657523,-0.009567,-0.280244,0.263260,-0.186692,0.215736,0.194263,-0.059037,0.787362,-0.384377,0.182490,-0.288397,0.167644,0.780584,-0.178136,-0.741771,0.790551,-0.687977,-0.433149,-0.219842,-0.341436,-0.780842,0.180591,0.060181,0.228757,-0.290052,0.104582,-0.558327,0.000134,-0.087412,-0.049873,0.412857,-0.464050,-0.237376,-0.305751,-0.510567,-0.704026,-0.513190,-0.029600,0.101205,-0.557602,1.099614,-1.106405,0.255093,0.674704,0.406906,-0.464150,0.964168,0.335379,-0.244037,-0.164719,-0.079940,0.631363,-0.255413,-0.132981,-0.057763,0.139525,-0.074122,0.075617,-0.343869,0.724823', '1309161', '1292720', '26354526', '4817024');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1353725', '常在我心', '爱情', '富家女君儿(蔡卓妍饰)身患重症，因家中缺乏温暖令她放弃了治疗，并决定由小段（陈奕迅饰）筹备她自己的丧礼。小段尝试鼓励君儿珍惜生命，但君儿仍坚持在他陪同下前往美国寻找适合的墓地。相处的时间中，小段生活处处照顾君儿，令君儿感动因而产生了感情，并答应小段好好治病。可是小段对她若即若离，令她深感疑惑，在她用情越来越深的时候，小段突然消失了。最后君儿也终于发现，小段对她若即若离的原因。©豆瓣', '陈奕迅', '马伟豪', 7.6, 7206, 'tt0313579', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2552299122.jpg', 0.7, 3.4, 31.4, 43.5, 21, '-0.410310,-0.044224,-0.727858,0.333114,-0.064122,-0.295172,0.409159,-0.149572,-0.707764,-0.485745,0.259923,0.346398,-0.162176,0.509372,-0.036209,0.085992,0.057858,-0.374410,0.102439,-0.238670,-0.349201,-0.480996,-0.308164,-0.142997,-0.361650,-0.236964,0.438597,0.115445,-0.237914,0.400058,0.014478,-0.297138,0.073236,0.899792,0.134628,-0.196214,-0.261109,0.065874,-0.237201,-0.400526,0.568257,-0.305707,-0.135899,-0.010240,0.607089,0.347331,0.717390,-0.314635,-0.297513,-0.053463,0.243406,-0.402433,0.080999,-0.126670,-0.097260,0.192504,0.078412,0.401539,-0.702922,-0.089835,-0.157888,-0.298805,-0.227164,0.171627,0.044031,-0.309860,-0.761601,0.451868,0.082442,-0.275827,0.302780,-0.560629,0.067135,0.374209,0.283936,0.466506,-0.298867,0.044551,0.159477,0.265532,0.441228,-0.114229,-0.254665,0.511662,-0.386842,-0.337827,0.017238,0.024438,-0.363619,-0.071576,0.136793,0.289958,-0.467125,0.287857,0.033119,0.236246,-0.377349,-0.174680,0.105921,-0.657939,0.207985,-0.526422,-0.119818,-0.360642,-0.201306,-0.032077,0.132817,-0.500944,0.679781,-0.781469,0.395238,0.554937,0.484518,-0.845856,0.456586,0.638767,0.104472,-0.098581,-0.006215,0.669927,-0.273093,-0.003641,0.284323,0.054668,-0.277271,0.485578,-0.630515,0.225286', '1303485', '26718282', '1421278', '1300572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1353745', '精疲力尽', '剧情', '本片和特吕弗的《四百击》同被誉为法国电影新浪潮的开山之作。身无分文的街头混混米歇尔（让-保罗•贝尔蒙多）从马赛偷了一辆小汽车，驶往巴黎的路上，他因超速行驶被警察逮住，为了脱身，他开枪打死一名警察，来到巴黎后，他躲进当记者的女友帕特丽夏（Jean Seberg）处（躲避警方的通缉之外，他还想方设法讨回一笔卖车赚来的钱）。帕特丽夏去报社时，遇到警长，对方要她一有米歇尔的消息就打电话相告。对米歇尔，帕特丽夏心态复杂，一面深深为他对一切都无所谓的劲儿着迷，一面却嫌弃他太吊儿郎当。©豆瓣', '珍·茜宝', '让-吕克·戈达尔', 8.4, 53125, 'tt0053472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167119775.jpg', 0.3, 1.3, 13.6, 47.8, 37, '0.243569,-0.202818,-0.462485,0.275105,-0.292788,-0.333786,0.599516,-0.143608,-0.283518,-0.026577,0.175585,0.736392,-0.214014,0.005527,0.408932,0.129209,-0.316907,-0.514409,0.347269,-0.072975,0.077034,-0.224905,-0.342303,-0.196529,-0.077136,-0.069813,0.189953,0.044013,-0.085114,0.356573,0.317252,0.155542,0.130132,0.531966,-0.238008,0.169815,-0.044856,-0.206592,0.084324,0.094073,0.130951,-0.437906,-0.128855,0.221948,0.038900,0.441554,0.456065,0.174649,0.004318,0.152063,0.198324,-0.442602,0.143833,0.128062,0.148047,-0.223124,0.127742,-0.018643,-0.221976,-0.102886,0.052315,0.201641,-0.539059,0.086549,-0.246344,0.109665,-0.723113,0.258716,-0.385306,0.281258,0.048112,-0.430984,0.031736,0.043248,-0.061602,0.045513,0.028202,-0.162287,-0.573127,0.155629,0.434829,-0.100693,0.190792,0.133925,-0.110409,-0.104600,0.236543,-0.232872,-0.500247,-0.079646,0.620584,-0.425018,-0.159965,-0.158774,-0.268693,-0.234929,-0.432479,-0.144984,-0.197344,-0.255365,-0.160563,-0.605591,0.169000,-0.192883,-0.122273,0.093241,0.160754,-0.192873,0.253048,-0.156048,0.071942,0.797489,0.498836,-0.277920,0.686265,0.010391,-0.137317,-0.117793,-0.238376,0.086647,0.433851,0.382416,0.102197,0.276749,0.104961,-0.384928,0.166806,0.490597', '1301345', '1293511', '1293908', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1358386', '预言', '恐怖', '适逢假期，高中教师里见英树（三上博史 饰）驾车带着妻子绫香（酒井法子 饰）和女儿奈奈去岳母家度假。快乐的假期很快结束，返程途中，他们的汽车出现故障。英树在电话亭打电话求助时，发现一张神秘的报纸碎片，上面竟然清晰写着女儿死亡的消息。正当他惶恐诧异之时，一辆失控的卡车撞向他们的汽车并引发爆炸，奈奈果然如报纸所写的那样葬身火海。这起事故摧毁了里见家的幸福生活，在此之后不久英树便和绫香离婚。3年后，一个连环杀手横行于世。过着平凡无聊生活的英树某日竟然再次收到预测死亡的信息，而预言的死者正是他班上的学生沙百合（堀北真希 饰）……©豆瓣', '堀北真希', '鹤田法男', 6.7, 7516, 'tt0419280', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p990829173.jpg', 1.5, 9.3, 50.1, 30.3, 8.7, '-0.018241,0.144557,-0.630685,0.436551,0.148131,-0.163003,0.659957,0.119654,-0.196819,-0.428742,0.150833,0.663294,-0.400444,0.696795,0.448511,0.159059,-0.334056,-0.643065,0.075248,-0.248486,-0.440768,-0.219625,-0.024945,-0.122053,0.226624,-0.280143,0.356468,0.252525,-0.053833,0.855090,0.097185,-0.001859,-0.458142,0.540448,-0.141008,0.124134,-0.007144,0.336754,-0.065852,-0.045489,-0.041623,-0.380333,0.001799,-0.017092,0.013188,0.343224,0.807303,-0.241006,-0.359332,-0.142589,0.478197,-0.171370,-0.097426,0.226777,0.564202,0.280285,0.129408,0.035537,-0.228226,-0.115287,0.074204,0.159976,-0.277755,-0.047282,-0.325298,0.174521,-0.300617,0.401368,-0.181317,0.140961,0.139766,-0.234125,0.352833,0.268935,0.069594,0.376583,-0.423951,0.181377,-0.203810,0.260500,0.428148,-0.134296,-0.135381,0.384215,-0.027477,-0.256702,0.062708,0.024790,-0.565367,0.144380,0.456866,0.047072,-0.086462,0.054211,-0.455701,-0.274145,-0.235699,-0.064501,0.055598,-0.131032,-0.448524,-0.767033,0.260871,-0.151093,-0.406324,0.258134,-0.052846,-0.117755,0.705060,-0.427015,0.278553,0.464596,0.345354,-0.124510,0.448511,-0.116835,-0.123692,-0.087280,-0.001083,0.204099,0.157413,0.559176,0.043537,0.186946,-0.196781,-0.103940,-0.360893,0.449325', '3811356', '10466639', '26365262', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1358468', '六壮士', '喜剧', '失意的发型师吹牛强（李克勤 饰）与三个好友：阿狼（郑伊健 饰）、阿柴（杜汶泽 饰）和米高（许志安 饰）相约跳楼，然而在警方将他们团团围绕之际，同幢楼里失足坠楼的青年矢野（谭俊彦 饰）却打乱了他们的计划。生活继续的四人只得面对各自的烦恼：吹牛强难耐女友（卢巧音 饰）的土气考虑分手但又放不下后者的体贴跟帮助，阿狼被老板（林子祥 饰）整日压榨但又找不到发作的机会，阿柴不满工作狂女友（黄奕 饰）的长期缺位试图与前女友丁丁（林嘉欣 饰）重修旧好，而米高在接到自己有了孩子的电话后就失去了沟女的能力。四个大男人怎样解决自己的问题呢？©豆瓣', '林子祥', '黄真真', 6, 4079, 'tt0440595', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2359608683.jpg', 3.5, 16.7, 58, 17.5, 4.3, '0.180122,-0.057059,-0.535820,0.415612,-0.187696,-0.181534,0.623724,0.346513,-0.333632,-0.187120,0.000939,0.541019,-0.130994,0.235221,0.052178,-0.247540,-0.089389,-0.843172,0.213410,0.214803,-0.193174,-0.568062,-0.169660,-0.250903,-0.200329,-0.063157,0.333821,-0.042967,-0.062035,0.399256,0.476961,0.155541,-0.151275,0.446192,-0.083175,-0.004705,-0.028811,0.172243,0.005074,0.263491,0.305930,-0.159309,-0.127412,0.023501,0.073030,0.560302,0.614570,0.090160,-0.323271,0.110016,0.262552,-0.246711,-0.076056,0.060246,0.255745,-0.118228,0.361304,-0.062669,-0.225068,-0.086163,0.335736,0.091782,-0.407756,0.231754,0.158849,-0.123337,-0.491485,0.457655,-0.254350,-0.170832,0.217185,-0.238132,0.020178,0.335064,0.264806,0.313545,-0.302880,-0.110766,-0.439649,0.313646,0.472008,0.279543,-0.016532,0.178505,0.084419,-0.310145,-0.340390,-0.132436,-0.475685,-0.139918,0.362733,0.115353,-0.187506,-0.158355,-0.619242,0.014639,-0.332682,0.161120,-0.191430,-0.451590,-0.035224,-0.309140,-0.014458,-0.347735,-0.275693,0.289703,0.222601,-0.173827,0.663580,-0.696245,0.186711,0.339926,0.465390,-0.733183,0.512366,0.115342,0.088174,-0.298551,-0.043021,-0.010799,-0.179055,-0.041902,0.287945,0.242554,-0.209129,-0.197184,-0.544153,0.097348', '1301022', '25777330', '1418613', '26730542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1361252', '夜', '剧情', '这是发生在米兰的一对夫妻的故事。Giovanni Pontano（马塞洛•马斯楚安尼 Marcello Mastroianni 饰）是一个有名的作家，他有一个美丽的妻子Lidia（让娜•莫罗 Jeanne Moreau 饰）。他们来到医院看望Giovanni身患重病的朋友Tommaso，Tommmso对Giovanni的新书暂不绝口，然而疾病给他带来的疼痛让他十分痛苦。Lidia无法忍受看着这样一个病人，先离开了，Giovanni却被一个女病人所引诱。Giovanni再次见到Lidia时，两人间的气氛显得十分异样。两人先是去参加了出版社举办的Giovanni的新书发布会，随后又受邀去参加一个晚会。在豪宅的晚会上，Giovanni和主人的女儿Valentina Gherardini（莫尼卡•维蒂 Monica Vitti 饰）打得火热，两人接吻的场面被Lidia看到了。随后Lidia也和另外一个男人跳起舞来......这对夫妻的婚姻将走向何方？本片获1961年柏林电影节金熊奖。', '马塞洛·马斯楚安尼', '米开朗基罗·安东尼奥尼', 8.8, 12524, 'tt0054130', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2376274685.jpg', 0.3, 0.9, 8.5, 38.4, 51.9, '0.432225,-0.192734,-0.658396,0.668286,0.009776,-0.288249,1.111182,0.338824,-0.312696,-0.057922,0.290491,1.201461,-0.660582,0.388155,0.355941,0.069542,-0.093334,-0.719589,-0.171523,-0.053799,-0.288570,-0.190220,0.060374,-0.103715,0.039820,-0.121580,0.445095,0.036163,0.028163,0.833696,0.454207,0.266831,-0.012582,0.709133,-0.326724,-0.072467,0.063604,0.157891,-0.058204,0.441492,0.261418,-0.395560,-0.223736,0.232376,-0.134721,0.252914,0.754498,-0.259259,-0.119122,0.059942,0.566189,-0.265263,0.076554,0.273618,0.102940,-0.047265,0.115259,0.105420,-0.513032,0.052560,0.161136,-0.282242,-0.716021,0.381409,0.053629,0.324459,-0.763851,0.773025,-0.176445,-0.202316,0.189569,-0.287234,0.454851,0.533705,0.061982,0.503601,-0.173623,0.114857,-0.530157,0.055523,0.922185,0.041258,-0.122028,0.436547,-0.266335,-0.566916,-0.002053,-0.101799,-0.529558,0.108663,0.304443,-0.169200,-0.062700,-0.165227,-0.788233,-0.166614,-0.163699,-0.447272,-0.153588,-0.461627,-0.098683,-0.635358,-0.138058,-0.230666,-0.367641,0.021158,0.196962,-0.243345,0.757405,-0.791876,0.076727,0.500089,0.355786,-0.488888,1.025639,0.168045,0.192497,-0.002955,-0.171930,0.022188,0.053783,0.274804,0.071770,0