INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1361276', '八部半', '剧情', '电影导演圭多（马塞洛·马斯楚安尼 Marcello Mastroianni 饰）在完成了一部影片之后感到筋疲力尽，他来到一处疗养地休息，同时开始构思下一部电影。他受到恶梦的困扰，精神不振，灵感也陷入停滞。他让情妇卡拉（桑德拉·米洛 Sandra Milo 饰）也来到疗养地和他作伴，但卡拉的到来反而增添了他的烦恼。此时，充满朝气的年轻女郎克劳迪娅（克劳迪娅·卡汀娜 Claudia Cardinale 饰）的出现，令圭多压抑的世界乍现出一抹亮色。然而随着圭多妻子路易莎（阿努克·艾梅 Anouk Aimée 饰）以及许多电影圈人士纷纷来到疗养地，圭多不堪忍受个人感情生活的混乱与电影拍摄的双重压力，他的精神危机愈演愈烈，梦境与幻觉不断侵入他的现实生活……本片荣获1964年奥斯卡最佳外语片和最佳服装设计（黑白片）两项大奖。©豆瓣', '马塞洛·马斯楚安尼', '费德里科·费里尼', 8.6, 53395, 'tt0056801', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2161627049.jpg', 0.8, 1.8, 12, 37.3, 48.1, '-0.029307,0.120927,-0.622907,0.475167,0.518015,-0.184112,1.045057,0.278068,-0.405549,-0.338715,0.394483,0.875135,-0.666099,0.283327,0.516307,-0.208053,-0.623412,-0.610553,0.136647,0.115674,0.052851,-0.177375,-0.163673,-0.157042,-0.123925,-0.644255,0.737048,0.145250,-0.313854,0.487008,0.134342,0.172485,-0.006326,0.437355,0.432834,0.197455,0.045502,-0.302880,-0.262787,0.278557,0.394598,-0.091179,-0.273237,0.227065,0.033990,0.107528,0.748814,-0.083394,-0.087880,0.405818,0.614612,-0.311306,0.014007,-0.002390,-0.332451,-0.104253,0.096514,-0.181834,-0.230858,0.188660,-0.092362,-0.048381,-0.619983,0.371451,0.199098,0.231510,-0.297173,0.307691,-0.252853,-0.079368,-0.021713,-0.237962,0.002735,0.311020,0.244653,0.456303,-0.416319,0.136101,-0.317059,0.213851,0.390637,-0.017001,-0.455544,0.365553,-0.384761,-0.439082,-0.311383,-0.023900,-0.454635,-0.077405,0.491079,0.000214,0.145098,0.487632,-0.795353,-0.049501,-0.173697,-0.447506,-0.207832,-0.198657,-0.174775,-0.722173,-0.347175,-0.022309,-0.201451,0.003417,0.155720,-0.289845,0.416472,-0.654950,0.326303,0.474808,-0.021064,-0.056917,0.543687,-0.350007,0.133927,-0.193445,-0.130249,0.645657,-0.219410,0.042822,0.132417,0.306120,-0.283698,-0.008421,-0.447482,0.475572', '1316693', '1467779', '1308069', '1309194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1364764', '精武家庭', '喜剧', '余小宝（黄秋生 饰）拥有一身好武功，随着年龄增长也有点力不从心，经营一家老式铁打医官。他妻子早逝，身兼母职照顾儿子Nicky（冯德伦 饰）和女儿Natalie（钟欣桐 饰），可是家里总是缺少和睦，哥哥和妹妹常常吵架，而孩子们都听厌了父亲不停讲述当年的英勇。Nicky一直喜欢妹妹的好朋友Ella（蔡卓妍 饰），而Nataile的男友Jason（吴彦祖 饰）则是个音乐人。Rocco（王敏德 饰）抓走了余小宝要求说出当年加害Rocco使之从此瘫痪的戴子龙，兄妹俩不得不一起救回爸爸。至此他们才发现了爸爸、Jason以及戴子龙的真事身份，使他们惊讶不已。©豆瓣', '黄秋生', '冯德伦', 5.7, 25604, 'tt0435026', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486539979.jpg', 4.8, 24.7, 55.4, 11.8, 3.2, '-0.323833,-0.528748,-0.246789,0.461305,-0.187000,-0.372529,0.329797,0.222476,-0.887748,-0.566026,0.015520,0.653782,0.058981,0.557419,0.090278,-0.121080,-0.210120,-0.553040,0.189684,0.195861,0.054989,-0.388994,-0.083315,-0.236071,-0.260993,-0.350911,0.238254,-0.231631,0.146074,0.520588,0.318482,0.066085,-0.210552,0.182009,-0.054887,0.219186,-0.253272,0.265845,-0.172592,-0.184955,0.149740,0.182365,0.138683,-0.097575,0.200657,0.251715,0.517953,-0.178100,-0.115914,-0.506057,0.461814,-0.134885,0.093694,-0.011356,0.118845,0.140916,0.809529,0.101727,-0.306887,0.020157,0.119583,0.031200,-0.284907,0.290497,0.600405,-0.346492,-0.614541,0.188642,-0.159392,-0.082650,0.235402,-0.415527,0.292696,0.311185,0.183821,0.565951,-0.407505,0.062688,-0.279948,0.102711,0.547484,-0.048496,0.216522,0.110663,0.018372,-0.134983,0.187060,-0.338201,-0.400641,0.183138,-0.184833,0.117030,0.145942,0.081058,-0.248006,-0.165568,0.111991,0.163807,0.066401,-0.551242,0.277498,-0.105029,0.065483,-0.642993,-0.080888,-0.055895,-0.005890,-0.288073,0.880319,-0.639399,0.131084,-0.042832,0.373046,-0.800316,0.453031,0.169008,0.164563,-0.344716,-0.057257,0.142443,-0.029389,-0.438869,0.111636,0.063286,-0.070066,-0.108163,-0.146646,0.077045', '1424743', '6963575', '3445516', '1758336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1366165', '死者田园祭', '剧情', '“我”（菅貫太郎 饰）是一名电影导演，当前正在拍摄一部带有自传性质的影片，影片的情节如下：童年的“我”（高野浩幸 饰）生活在一个偏远山村，与母亲过着孤单辛苦的生活。父亲早年过世，“我”只能通过巫术叫出父亲的鬼魂与他对话。隔壁的少妇（八千草薫 饰）美艳动人，我深深为之着迷。某日，一支流动马戏团来到“我”的村庄，从他们的口中，“我”得知外面大千世界的精彩。于是在某个夜晚，“我”和隔壁的少妇整理行囊，偷偷离开了家乡。影片进行到这里，“我”却突然陷入瓶颈。那天，“我”遇到了童年的自己，藉着对童年时代的回溯，“我”发现影片中竟然有着如此多的虚伪和不真实。“我”找到了真实的过去，以及所有被刻意遗忘的残酷回忆……©豆瓣', '菅贯太郎', '寺山修司', 8.9, 19116, 'tt0071406', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2141520557.jpg', 0.5, 1.1, 7.8, 33.5, 57.2, '0.275039,0.216381,-0.712640,0.670942,-0.127778,-0.187669,1.077437,-0.041618,-0.374939,-0.339565,0.127429,0.792811,-0.096284,0.630642,0.119369,0.278718,-0.417034,-0.588431,-0.166608,-0.124170,-0.225505,-0.224564,-0.314695,-0.012536,-0.017567,-0.239862,0.424116,0.346757,-0.398576,0.248632,-0.040668,0.256425,-0.357525,0.332836,-0.269975,0.229432,-0.143879,0.147303,-0.290136,0.030979,0.236643,-0.296834,-0.187819,0.031561,-0.147052,0.129150,0.790347,-0.212333,-0.428967,0.196207,0.598560,-0.110969,-0.096904,0.086256,-0.040592,0.097499,0.317156,0.222046,-0.137400,0.247752,-0.385317,-0.196582,-0.802284,0.019026,-0.050345,0.191045,-0.481002,0.303080,-0.115929,-0.157061,0.431681,-0.588165,0.215000,0.161566,0.168964,0.450762,-0.278220,-0.065447,-0.449842,0.555702,0.678541,0.033707,-0.125707,0.426345,-0.083799,-0.394111,-0.141870,-0.089825,-0.551906,0.262816,0.325321,-0.218639,-0.293964,0.058361,-0.692942,0.086827,0.109355,-0.392913,0.075707,-0.301567,-0.145103,-0.592384,-0.275950,-0.502525,-0.421508,-0.106927,0.065587,-0.381939,0.779706,-0.730602,0.390821,0.646526,0.171478,-0.372896,0.551676,0.064949,0.064797,0.021929,0.142042,0.374870,-0.010448,0.456603,0.086181,0.346966,-0.029255,0.114012,-0.862358,0.423848', '3005387', '21619567', '1296534', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1366853', '旺角黑夜', '剧情', '一个在24小时以内的故事。发生为了寻找失踪女友，来福（吴彦祖饰）从内地移民至香港，在旺角找了一份差事，误入歧途成了一名杀手，卷入了黑社会的腥风血雨中。提携他的是奸诈的老六，他混迹于黑白两道，是警方的线人，来福因此踏上亡命之途。其间遇到妓女丹（张柏芝饰），相似的身世令二人相见如故，丹决心帮来福找回女友，同时要改过自身。警方多次抓捕来福未果，眼看江湖恩怨渐渐平息，正打算就此作罢，来福和丹似乎可以喘一口气了，但是事情又出现了意外的转折，夜幕下的旺角始终处处暗涌。©豆瓣', '张柏芝', '尔冬升', 7.4, 54381, 'tt0430772', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1052419765.jpg', 0.4, 3.2, 35.9, 46.6, 13.8, '0.050208,0.055804,-0.394603,0.444974,0.192677,-0.044308,0.389565,0.103626,-0.791345,-0.211560,-0.022081,0.562919,-0.177500,0.018270,0.177549,-0.272739,-0.110337,-0.747372,0.192305,-0.209736,-0.144119,-0.176999,-0.136974,-0.041495,-0.232634,-0.127424,0.432236,0.479753,-0.014831,0.406856,0.307754,0.320298,-0.245463,0.420529,-0.133811,0.107326,0.053642,0.128570,-0.352880,0.235436,-0.009152,-0.537646,-0.072616,-0.074936,0.156463,0.396811,0.611304,0.195741,-0.227000,0.024750,0.200657,-0.220375,-0.223142,-0.018934,0.282679,0.188750,0.087199,0.281850,-0.311532,-0.059197,0.025740,-0.114495,-0.506328,0.061167,0.078958,0.133088,-0.654786,0.317347,-0.033576,0.055844,-0.267156,-0.187917,0.199211,0.422987,0.132024,0.041462,0.003748,0.161369,-0.574756,0.186672,0.746483,0.177236,0.016263,0.308605,0.124608,-0.434773,-0.005725,-0.229470,-0.055679,-0.149671,0.446252,0.023735,-0.312417,0.284276,-0.379786,-0.188043,-0.419732,0.010569,-0.011424,-0.256856,-0.115510,-0.426609,-0.260685,-0.310955,-0.104600,0.212823,-0.060870,-0.257682,0.347849,-0.593802,0.142801,0.453099,-0.003189,-0.668217,0.641082,0.084040,0.233477,-0.322388,-0.105885,0.149372,-0.174647,0.400776,0.212237,0.001065,-0.088147,-0.270649,-0.258459,-0.017529', '25908042', '1301022', '3811342', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1370237', '我要做Model', '喜剧', 'Mandom（郑中基 饰）、Condom（李灿森 饰）、Freedom（陈子聪 饰）都是扬名国际的超级名模。一天，Mandom收到威胁他不得参加“Model皇战衣争夺战”的恐吓，避免波及安危，Mandom报警后警方派出了女警张铁柱（林嘉欣 饰）的贴身保护。但铁柱一直看不起只注重外表Model。Mandom也不喜欢张铁柱的不修边幅，两人成了斗气冤家。新人王范特西（森美 饰）也在经理人柯尔温（钟镇涛 饰）与拍档罗曼蒂（李彩桦 饰）的帮助下，名气迅速增长。Mandom在巧合下与范特西碰头，铁柱也误打误撞成为了Mandom的拍档，经过训练后，铁柱才明白了模特儿的辛酸。铁柱脱胎换骨，更被Mandom的自信魅力吸引，两人互生爱意。“Model皇战衣”的比赛即将来临，Mandom有会否有生命危险呢？©豆瓣', '郑中基', '谷德昭', 5.8, 5955, 'tt0440935', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2359626273.jpg', 7.4, 23.7, 47, 16.1, 5.8, '-0.085485,-0.038914,-0.588739,0.297129,-0.024129,0.009528,0.317805,0.258899,-0.275799,-0.024191,0.599388,0.725971,-0.381311,0.022962,0.032268,-0.014046,-0.036467,-0.656893,0.156541,-0.084876,-0.184618,-0.306274,-0.443122,0.069006,0.040802,-0.543322,0.471243,-0.023526,-0.386981,0.698299,0.504298,-0.019845,0.137975,0.395389,-0.091963,-0.034771,0.022298,0.208167,-0.102168,0.142543,-0.053322,-0.067462,-0.015214,0.242987,0.074907,0.299581,0.450966,-0.158906,0.000102,-0.046759,0.474656,-0.230635,0.068926,0.118063,0.393348,-0.076553,0.220992,0.347255,-0.220411,0.276345,0.050790,0.149772,-0.779646,0.147600,0.236563,0.112519,-0.671933,0.571809,-0.105379,-0.386866,-0.098813,-0.224707,0.196532,0.162643,0.239413,0.176059,-0.217668,0.118840,-0.388855,0.140051,0.547568,0.059461,-0.197058,0.182753,-0.017917,-0.336539,-0.146544,-0.302689,-0.320830,-0.069482,0.234963,0.146883,0.174313,-0.150644,-0.739778,0.030513,-0.178777,0.199281,-0.226118,-0.444451,0.173937,-0.547024,-0.186785,-0.662467,-0.415492,0.035182,0.239970,-0.151323,0.735235,-0.656796,0.129037,0.495832,0.383422,-0.593595,0.613441,0.168364,0.079391,-0.234577,-0.144875,-0.133704,-0.094127,0.023278,0.171169,0.438626,-0.023579,-0.401765,-0.192399,0.139246', '4301278', '35144311', '3006892', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1370276', '勇敢者的游戏2：太空飞行棋', '动作', '父亲因为工作需要出门，姐姐莉莎（克里斯汀•斯图尔特 Kristen Stewart 饰）作为老大不得已担负起照顾两个弟弟丹尼和沃特的责任。然而莉莎偷懒留下丹尼（乔纳什•波波 Jonah Bobo 饰）和沃特（乔什•哈切森 Josh Hutcherson 饰）这两个生性好动，年幼顽皮的的家伙自己上楼去睡觉。无聊至极的二人只得自娱自乐，但二人不断的争吵让丹尼赌气离开，独自来到地下室淘宝，意外的发现了一套太空飞行棋。好奇心起的丹尼开启了游戏的开关，并邀请哥哥沃特参与到游戏中来。不断的流星雨和外星人侵袭让这场游戏越发的惊心动魄，而中途加入的神秘太空人真实的身份更是让人大跌眼镜。渐渐他们意识到，这不是一盘普通的游戏棋，而一旦开启了游戏的开关，如若不能到达游戏的终点扎图拉行星，等待他们的将是永远滞留在外太空。那么两兄弟能否在这场真实的冒险中尽释前嫌，联手度过难关？该片为《勇敢者的游戏》第二部，改编自著名作家克里斯•范•奥斯博格的同名作品。', '乔纳·波波', '乔恩·费儒', 6.9, 29434, 'tt0406375', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p825924444.jpg', 1.3, 7.7, 47, 32.3, 11.8, '0.355280,0.159232,-0.653133,0.464740,-0.066413,-0.197693,0.593928,0.249192,-0.476098,-0.231111,0.090326,0.675865,-0.154038,0.062177,0.330065,-0.011640,-0.514711,-0.382980,-0.062256,-0.051855,-0.383820,-0.482395,0.086916,-0.354764,0.027984,-0.215665,0.447265,0.048535,-0.185914,0.469163,0.308930,0.250277,-0.330244,0.407356,0.058166,0.076159,-0.006166,-0.021015,-0.258585,0.298768,0.057376,0.091145,-0.230119,0.179310,0.241399,0.239716,0.647596,-0.401173,-0.009322,0.057291,0.210026,-0.353061,-0.111676,-0.199974,0.107085,-0.115648,0.036193,-0.061474,-0.004741,0.286386,0.123392,-0.241488,-0.731748,0.235510,-0.007949,0.050135,-0.270890,0.146354,-0.143870,-0.138936,0.144149,-0.112998,0.052039,0.448279,0.388893,0.198200,-0.276360,-0.046490,-0.436739,0.095883,0.455429,-0.035043,-0.173246,0.509273,-0.091721,-0.230727,-0.199345,-0.257782,-0.507012,-0.172654,0.409075,0.103341,-0.118612,0.250872,-0.752801,0.063276,-0.229297,-0.235173,-0.141984,-0.519154,0.138674,-0.785543,-0.045456,-0.207854,-0.165468,0.002964,-0.092203,-0.368801,0.512425,-0.823368,0.225587,0.704340,0.173847,-0.315447,0.540801,0.118330,0.235481,-0.103274,0.024499,0.309231,0.269204,0.026404,0.012021,0.466048,0.044215,0.014614,-0.420758,0.349981', '3178770', '1420088', '11541282', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1381964', '云的彼端，约定的地方', '剧情', '战争之后，日本被分为南北两个部分。美军统治下的青森县，少年藤泽浩纪和白川拓也都喜欢同年级的同学泽度佐由理。他们的心中都有佐由理，还有那个东西——边境以北的津轻海峡，日本北海道联盟建立的高耸云端的“塔”。巨大而神秘的的塔，是三位少年少女的向往，他们约定，建造小型飞机，飞向 塔去一探究竟。中学三年级佐由理转学到东京。两位少年放弃了制造飞机的打算。浩纪考进东京的高中，拓也继续留在青森的高中就学，彼此在各自的道路上越走越远。但是，多年后，佐由理在医院中陷入沉睡！这突如其来的病症让三人再次聚在一起。沉睡的病症，与塔的力量有神秘的联系，而塔本身，似乎也成了日本南北开战的据点。卷入战争与爱情的三人，到底是救佐由理，还是救世界！命运的解答，似乎就在云的那一端，他们曾经约定的地方。©豆瓣', '吉冈秀隆', '新海诚', 7.7, 77394, 'tt0381348', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1071335065.jpg', 0.7, 3.8, 29, 42.7, 23.8, '0.349164,0.042307,-0.881560,0.791883,0.022454,-0.130528,0.564078,0.022264,-0.154653,-0.001214,0.161853,0.795051,-0.097407,0.520128,0.227283,0.115624,-0.244900,-0.861463,-0.048220,-0.491154,-0.684218,-0.401543,-0.171372,-0.169501,0.082364,-0.257474,0.953174,0.386911,-0.189613,0.322403,0.179023,0.215995,-0.403720,0.495071,-0.293166,-0.152652,-0.060486,0.149313,-0.250849,0.111153,-0.275613,-0.125464,-0.252446,0.203535,0.164410,0.395676,0.814172,-0.143921,0.043595,-0.032884,0.043264,-0.200747,-0.177596,-0.049082,0.676536,-0.012460,-0.104508,0.207490,-0.239246,0.003791,-0.002490,-0.083969,-0.416828,0.012213,0.136236,0.026742,-0.489025,0.572597,0.327446,-0.288263,0.127337,-0.233345,0.226035,0.653001,0.227374,0.411415,-0.179600,0.024320,-0.439057,-0.130961,0.791172,-0.142532,-0.364735,0.022180,-0.086819,-0.505994,-0.296049,-0.178483,-0.132733,-0.066362,0.330649,-0.085590,-0.161321,0.216335,-0.659046,0.099766,-0.106330,-0.382107,0.074406,-0.469665,-0.052926,-0.663268,-0.162388,-0.518572,-0.138273,0.276194,0.164857,0.081849,0.846592,-0.764153,0.074796,0.555472,0.436060,-0.464357,0.707623,0.151356,0.115613,-0.199717,-0.055070,0.232750,-0.141796,0.473630,0.039163,0.420766,0.013724,0.072070,-0.585188,0.531349', '1478066', '1826173', '3158990', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1385567', '富贵再逼人', '喜剧', '在报馆任职的骠叔（董骠 饰）因为工作的关系带着全家到加拿大工作。一家五口都全身心投入新环境新生活中，骠叔却因得罪上司被解雇了。由于大女儿、二女儿（李丽珍 饰）已开始了学业，他唯有带着妻子骠婶（沈殿霞 饰）与最小的女儿回到香港继续生活，生活却比以前更艰难了。骠婶无意中发现了一张加拿大的头奖彩票，奖金是两千万加币。由于不够钱到加国，骠叔硬着头皮向旧上司借。同样受到经济危机的上司设法要夺取骠叔的彩票。骠叔一家顽强对抗，保住了彩票，却无法在领奖时限截止前赶到。一家人伤心流泪，悲伤之中发现时间上出现了时差，领奖的时间还没截止。©豆瓣', '沈殿霞', '高志森', 7.4, 16241, 'tt0093055', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2347412589.jpg', 0.3, 2.4, 38.2, 44, 15.2, '-0.250810,0.120422,-0.627397,0.360034,0.000812,-0.534697,0.674806,0.351389,-0.437534,-0.287631,0.129547,0.557242,-0.005581,0.335176,0.139034,-0.316428,-0.184713,-0.450797,-0.097932,-0.065110,-0.365474,-0.282300,-0.023769,0.116650,-0.517005,-0.011501,0.457122,0.088419,-0.109830,0.475274,0.096857,0.088919,-0.076887,0.447199,-0.254732,0.022264,0.104097,0.248666,-0.389907,0.251657,0.307900,-0.282144,-0.228386,-0.082552,0.488403,0.441563,0.669078,0.219017,-0.239109,-0.014809,0.302073,-0.010739,-0.473613,0.168342,0.297798,0.160795,0.234780,-0.127994,-0.495121,0.100022,-0.048722,-0.251132,-0.669052,0.086368,-0.042534,0.259103,-0.478235,0.513846,-0.212941,0.012379,0.057047,-0.491376,0.145827,0.390734,-0.108718,0.371943,-0.228199,0.128298,-0.547631,0.308188,0.578942,-0.202720,-0.000980,0.420636,-0.134678,-0.300494,0.057119,-0.440210,-0.482900,0.072402,0.170051,0.186067,-0.132207,0.292208,-0.637379,0.081542,-0.148756,-0.410929,0.133140,-0.330442,-0.030935,-0.504327,-0.055607,-0.326411,-0.200774,0.337879,0.237615,-0.342692,0.480889,-0.648685,0.155152,0.520858,0.639705,-0.476863,0.592838,0.151784,0.275773,-0.102427,0.086226,0.066172,-0.044906,0.451828,0.296353,-0.090666,-0.203455,-0.309787,-0.316597,0.594799', '3055049', '1299965', '1308755', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1388175', '下妻物语', '喜剧', '17岁的龙崎桃子（深田恭子饰）住在茨城县下妻，她喜欢洛可可风格的打扮，并向往中世纪的法国。和桃子同校的高二女生白百合草莓（土屋安娜饰），是一个整天骑着重型摩托车的“飙车帮恶女”。一次机缘巧合，桃子和草莓偶然结识对方，她们对彼此充满了好奇，而且都不明白在这小地方怎么会 有对方这样的女孩。此后草莓经常来拜访桃子，她关注桃子，并对她的装扮评头论足，但坚持己见的桃子不为所动。草莓需要去一趟专为大姐头制作特攻服的服装店见识下，她希望自己可以穿上特攻服参加一个前辈的隐退仪式。她们没能找到，但桃子竟然特意为草莓缝制特攻服，成为莫逆之交的她们还会遇到什么困难呢？©豆瓣', '深田恭子', '中岛哲也', 8, 65763, 'tt0416220', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p832922781.jpg', 0.5, 2.3, 22, 44.6, 30.6, '0.323776,-0.072176,-0.344466,0.481306,-0.353650,-0.067280,0.422588,0.127371,-0.235570,-0.233822,0.205677,0.695637,-0.215260,0.168611,-0.054383,0.170623,-0.277031,-0.228958,0.200801,-0.171285,-0.403663,-0.221407,-0.283456,-0.087609,-0.034332,-0.080042,0.380634,-0.027890,-0.042955,0.518475,0.538501,-0.098946,0.212427,0.403320,-0.436475,-0.125540,-0.034367,0.258153,0.019426,0.269891,-0.184446,0.006974,-0.019635,0.052174,0.327039,0.194914,0.480061,-0.195637,-0.184944,-0.282498,0.132767,0.243662,0.080833,0.201203,0.258219,-0.069078,0.263266,-0.360490,0.098352,0.163870,0.054213,-0.125116,-0.386743,0.259448,0.133876,0.162338,-0.586341,0.414544,0.007161,-0.149941,0.163279,-0.405183,-0.002511,0.244622,0.462709,0.180243,0.048134,0.117380,-0.687509,0.259630,0.654841,0.178923,0.131052,0.438322,-0.458381,-0.352049,0.231195,-0.216534,-0.465755,0.266988,0.001842,-0.080247,-0.155145,-0.419953,-0.587263,0.010487,0.068349,-0.062676,0.272176,-0.355638,-0.176844,-0.478513,0.142715,-0.712860,-0.358613,-0.018900,0.295017,-0.377899,0.698588,-1.049118,0.117670,0.311696,0.262535,-0.579138,0.640046,0.200083,-0.253990,-0.264689,-0.428555,0.052682,-0.101627,0.058538,0.117992,0.668430,0.157588,-0.230619,-0.385056,0.011521', '1292219', '21766698', '1419416', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1388176', '血与骨', '剧情', '“骨受之于父，血受之于母”。20世纪20年代，年轻的朝鲜人金俊平（北野武 饰）随无数同胞从济州岛飘洋过海来至日本大阪。底层艰苦的生活令金俊平养成粗暴蛮横的性格，他强行占有了寡妇英姬（铃木京香 饰），然而家庭并未改变他的行事风格。金俊平，这个连黑道都惧怕三分的男人，以其强悍的作风统治着妻子、儿女乃至整个朝鲜人聚集区……本片根据梁石日同名自传体小说改编，并荣获2005年日本电影学院奖最佳女主角（铃木京香）、最佳导演、最佳剧本和最佳男配角（小田切让）四个奖项；2005年蓝丝带最佳男配角奖；2005年电影旬报最佳男主角（北野武）、最佳导演、最佳剧本和最佳男配角（小田切让）四个奖项；2005年每日电影最佳男主角、最佳影片、最佳男配角（小田切让）和最佳女配角（田畑智子）四个奖项。©豆瓣', '北野武', '崔洋一', 8.1, 6377, 'tt0419515', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p764037381.jpg', 0.6, 1.6, 19.6, 48.3, 29.9, '-0.422700,-0.075947,-0.170546,0.788243,0.295812,-0.041572,0.387235,0.111681,-0.509170,-0.320538,0.103733,1.019460,-0.165191,-0.242673,0.423446,-0.075137,-0.256649,-0.755261,-0.564233,-0.012487,0.116909,-0.162584,-0.310422,0.067721,-0.440986,-0.305052,1.125507,-0.456343,-0.153580,0.374928,0.868048,0.058012,-0.120345,-0.378653,0.068993,0.213066,0.145765,-0.288103,-0.547819,0.809382,-0.097456,-0.371909,-0.392621,0.184723,-0.043325,0.242899,0.854725,-0.081468,-0.206481,0.032788,0.949881,-0.263869,-0.705044,0.108206,0.309814,-0.526521,0.397818,0.287600,0.015184,0.321029,0.038392,-0.366904,-0.760845,-0.003151,0.234139,-0.041334,-0.484111,0.208776,-0.023478,0.053551,-0.021697,0.001091,-0.000533,0.110817,0.345847,0.098885,-0.311561,0.006636,0.165643,1.060283,0.261635,0.186250,-0.460321,0.320829,-0.150059,-0.752749,-0.298193,-0.542751,-0.667686,0.136704,0.342866,0.021579,0.052586,-0.056699,-0.368439,0.084751,0.176838,-0.168762,0.293243,-0.096046,0.204012,-0.837691,-0.175086,-0.343624,-0.104316,-0.114714,0.126817,-0.228309,0.953605,-0.440417,0.102110,0.550528,-0.135685,-0.528070,0.813933,0.048115,-0.054833,-0.547016,-0.105000,0.178916,-0.159728,-0.053388,0.007896,0.271780,-0.311562,-0.435035,-0.232592,0.436165', '22265121', '4135443', '1780122', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1388180', '哭泣的草原', '剧情', '1919年，俄国内战。为躲避战火，斯拜罗斯（Vassilis Kolovos 饰）带着妻子戴娜（Thalia Argirioua 饰）和一双儿女，随着难民潮辗转来到希腊。十几年过去，俄国难民不断聚集，最终形成一个名为“新敖德萨”的小村庄。斯拜罗斯的养女艾莉妮（Alexa ndra Aidini 饰）如今已长成落落大方的漂亮姑娘，并和心爱的小伙同时也是她的非血缘兄长埃里克西斯（Nikos Poursanidis 饰）生下一对双胞胎。为了逃避养父的控制与霸占，艾莉妮与爱人开始漫无止境的逃亡。时间进入1936年，一家人暂时得以安定。为追寻音乐梦想，埃里克西斯告别妻儿远赴美国。在此之后，战争统治着这个世界，也摧毁了艾莉妮苦心经营的家庭。在混乱的大时代的背景下，他们随波逐流，生离死别……本片是“希腊三部曲”第一部，并荣获2004年欧洲电影节国际影评人费比西奖。', '亚历山德拉·艾迪尼', '西奥·安哲罗普洛斯', 9, 12308, 'tt0366721', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2546247180.jpg', 0.3, 0.8, 7.3, 32.7, 58.8, '-0.157450,0.118047,-0.474503,0.372573,0.249118,-0.309551,0.581678,-0.036404,-0.348341,-0.374196,-0.053993,0.699283,-0.128252,0.127783,0.254401,0.028384,-0.434880,-0.652628,-0.032222,-0.036611,-0.084356,-0.379887,-0.278609,-0.137171,-0.270340,-0.383315,0.655110,0.249798,0.085976,0.396512,0.232511,0.103043,-0.137814,-0.072705,-0.069543,0.042410,-0.160313,-0.019080,-0.600313,0.198152,-0.107663,0.009016,-0.305419,-0.130723,0.088325,0.174155,0.683031,-0.386026,0.414570,-0.283140,0.179365,-0.137804,-0.046089,-0.014648,0.175088,-0.201591,0.160895,0.169198,-0.219226,-0.129674,0.132084,-0.335325,-0.429882,0.210017,0.153792,-0.051621,-0.533962,0.531146,-0.016987,-0.071111,-0.027028,-0.354439,0.081145,0.534171,0.119050,0.473835,-0.220189,0.338720,-0.290383,0.149602,0.586212,0.124594,-0.241341,0.086372,-0.387869,-0.349578,-0.203169,-0.346266,-0.694315,-0.262587,0.346556,-0.017135,0.123215,0.787525,-0.753752,0.000474,-0.469121,-0.238917,0.327857,-0.453965,0.093070,-0.432721,-0.086114,-0.256905,-0.044161,0.309739,0.002083,-0.136515,0.708061,-0.591758,0.418859,0.580374,0.398835,-0.529215,0.571104,0.117358,0.419199,-0.151419,-0.183363,0.881260,-0.099442,0.051746,-0.057718,-0.072298,-0.270627,-0.018512,-0.294636,0.455564', '4889554', '1460341', '35161768', '21937450');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1388196', '绝种好男人', '喜剧', '因忍受不了男友Moses（任贤齐）的平凡，阿Mi狠心与他分手，塞翁失马焉知祸福，Moses在老人院做义工时，与怪脾气老头蛤蚧王成为忘年之交，后者死后，给他留下巨额遗产。蛤蚧王的此举招致其律师Allen的不满，他在夜总会发泄时无意中将此事告诉了小姐Didi（张柏芝）。为将Moses钓到手，Didi使出浑身解数，无奈均不奏效。发现Moses是绝种好男人后，Didi对他动了真心，两人开始热恋，不久，Allen将Didi的原来身份相告Moses，令他异常伤心，此时，阿Mi又前来要与他复合。©豆瓣', '任贤齐', '王晶', 5.8, 30430, 'tt0395969', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486543085.jpg', 3.5, 20.5, 60.5, 12.1, 3.5, '0.012730,0.231321,-0.636157,0.327407,0.015075,-0.440524,0.620697,0.034790,-0.468244,-0.262498,-0.103573,0.523469,-0.224728,0.105879,0.022918,0.015833,-0.056501,-0.404421,0.063839,0.056026,0.034720,-0.327885,0.136474,-0.118057,-0.452582,-0.232743,0.416828,0.043019,-0.221204,0.139271,0.584908,0.341963,0.258786,0.595469,-0.078993,0.200509,-0.349460,0.086103,-0.395357,0.277970,0.431338,-0.298078,-0.231312,0.184902,-0.072017,0.302527,0.739833,-0.224490,-0.397125,-0.239955,0.386182,-0.374517,0.052048,0.329735,0.065544,-0.132971,0.166186,0.023035,-0.426231,-0.208853,0.250237,0.174291,-0.546309,-0.104053,0.144808,-0.160262,-0.625260,-0.039324,-0.520732,-0.038593,0.133930,-0.415258,0.267562,0.381564,0.218107,0.056930,0.001282,0.168252,-0.406494,0.159918,0.882936,0.239295,0.162660,0.053735,0.040416,-0.606488,0.304138,-0.269755,-0.313582,0.230645,0.274994,0.203319,-0.033614,0.257299,-0.270166,-0.514504,-0.213417,0.216212,0.019193,-0.713502,-0.145687,-0.057639,-0.215677,-0.188106,-0.303846,-0.161252,0.180346,-0.217157,0.429400,-0.849792,0.066302,0.093793,0.420352,-0.506843,0.780203,0.109541,-0.039886,-0.519210,-0.092711,-0.123258,0.168754,0.184156,0.640649,0.085032,0.201481,0.114142,-0.251604,0.181326', '2990737', '3036997', '1302384', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1388216', '撞车', '剧情', '一个黑人电视导演和他的妻子，莫名其妙地因为莫须有的违章驾驶受到了白人警察的侮辱；看似该受到谴责的警察却在最危急关头挽救了那名曾遭他侮辱的黑人妇女；老实巴交的波斯商店店主，却差点谋杀了有着刺青的墨西哥修锁匠(迈克尔•佩纳Michael Pena饰)；地区检察官（布兰登•费舍尔Brendan Fraser 饰）和他的妻子（桑德拉•布洛克Sandra Bullock饰）被抢吉普车后只能把怨气发泄到无辜的修锁匠身上；黑人警察（唐•钱德尔 Don Cheadle 饰）在承受着上司的威胁和焦急地寻找自己的弟弟。这一切看似无关的琐事，却在36小时内以一种出人意料的方式绞缠在一起，在这个以暴力，性，金钱闻名的多民族、多文化聚集的大城市—洛杉矶街头一幕幕上演……©豆瓣', '桑德拉·布洛克', '保罗·哈吉斯', 8.6, 285356, 'tt0375679', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2075132390.jpg', 0.3, 1, 12, 43.4, 43.4, '0.477804,-0.124942,-0.538500,0.574179,-0.301008,-0.301270,0.955452,0.315860,-0.471842,-0.130941,0.428758,0.717817,-0.148989,0.180431,0.205494,-0.006692,-0.130846,-0.675242,-0.113669,0.007885,-0.273173,-0.507825,-0.247146,-0.351575,-0.228183,-0.252510,0.376166,-0.059418,-0.141395,0.221811,0.398569,0.334389,0.071403,0.547887,-0.224976,0.065339,0.169367,-0.267973,-0.034805,-0.070082,0.164739,-0.458173,0.108210,0.214891,-0.236320,0.413966,0.653011,-0.082398,0.028524,0.003823,0.368034,-0.218371,-0.027312,0.087909,0.168092,-0.325455,0.098837,0.015642,-0.064819,-0.139473,0.386320,0.140797,-0.640039,-0.105664,-0.098466,0.262738,-0.815070,0.623654,-0.167687,0.082732,0.005058,-0.217853,0.058683,0.080646,0.045995,0.487526,-0.122471,-0.193953,-0.529529,0.330985,0.442207,0.100265,-0.225091,0.198530,-0.518869,-0.304310,-0.143979,-0.407257,-0.675545,-0.271707,0.467407,-0.323744,-0.262387,0.100413,-0.692859,-0.112665,-0.102508,-0.083723,-0.097352,-0.319829,-0.218828,-0.687696,0.026705,-0.657589,-0.248939,0.040411,0.253368,-0.032861,0.767612,-0.708068,-0.144519,0.765576,0.412384,-0.403291,0.568597,0.024232,0.000762,-0.037755,-0.548005,0.307576,0.200254,0.444201,0.183959,0.447833,-0.033024,0.036980,-0.180358,0.545462', '4233625', '21619567', '30162520', '26677495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1388219', '飞侠小白龙', '喜剧', '明朝，贵族学校才貌双全的女子黑凤（张柏芝）最大心愿是嫁给皇子成为皇妃，凭容貌及一流弹奏技艺，她赢得二皇子（安志杰）的倾心。某日，人称“一地鸡毛”的杀手盲侠（吴镇宇）欲行刺校长，但被清洁大婶发现，她本是名闻江湖的大侠“白龙”。两人大占数十回合，“白龙”不敌“一地鸡毛”受重伤，被黑凤救下。“白侠”自知所剩时辰不多，不由分说将毕生所学传给黑凤，黑凤受到巨大冲击体内起异变，面部长出细小带白的脓疮，消解办法惟有行善积德。为了能以最完美面貌嫁给二皇子，黑凤开始身穿白衣面蒙黑布在城内内劫富济贫，渐渐被人以“飞侠小白龙”敬称。得知二皇子是“一地鸡毛”新的刺杀目标时，黑凤以“小白龙”身份向他提出挑战，却意外受伤，令黑凤意外的是，“一地鸡毛”并没将她杀死反贴心照料起。两人渐渐互生情愫。©豆瓣', '张柏芝', '叶伟信', 5.9, 8470, 'tt0441263', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p486833961.jpg', 5.4, 22.7, 47.8, 17.3, 6.7, '-0.070374,0.212374,-0.364247,0.159899,-0.162302,-0.135511,0.448673,-0.021708,-0.454332,-0.447040,0.381872,0.361535,-0.138109,-0.082470,0.031446,-0.124776,0.332228,-0.504021,-0.237238,-0.077502,-0.016967,-0.271075,-0.057108,-0.038713,-0.284229,-0.523282,0.527155,0.031908,-0.187794,0.428947,0.502773,0.212109,-0.125972,0.311810,-0.248753,0.169556,-0.335081,-0.300211,-0.081554,0.295507,-0.076017,-0.415534,-0.023496,0.096274,-0.363511,0.230089,0.697202,-0.372979,0.160062,-0.573089,0.475880,-0.066159,0.042681,0.156893,0.413370,0.056451,0.321905,0.104418,0.034365,-0.137649,0.338386,0.001728,-0.240666,0.094054,0.195386,0.134858,-0.554810,0.401836,-0.333184,-0.183155,0.041447,-0.316506,0.173626,-0.254747,0.147685,-0.004875,-0.300082,0.061195,-0.562643,0.086078,0.568925,0.270683,0.091408,-0.061925,0.046721,-0.366676,0.234323,-0.668014,0.168596,0.109250,0.244643,0.293600,0.214315,0.284852,-0.162621,-0.104519,-0.462456,0.022906,0.079155,-0.267580,-0.076205,-0.028540,-0.203070,0.023188,-0.178499,-0.030739,0.221980,-0.357357,0.619959,-0.674094,-0.084677,0.220871,0.242507,-0.253155,0.423917,0.029273,0.277885,0.087688,-0.343659,-0.209696,0.071749,0.098067,0.251918,0.208478,-0.422251,0.073564,-0.243218,-0.123521', '35030151', '1826173', '1297747', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389915', '一江春水向东流', '剧情', '一九三零年代的上海顺和纱厂，女工素芬（白杨 饰）与妇女补习学校教员张忠良（陶金 饰）喜结连理。 一九三七年七月七日，素芬诞下一子。忠良为子取名抗生后不久，便加入救护队离开上海，并机智地在南京大屠杀中幸存下来。 一九三八年，忠良母（吴茵 饰）带素芬和抗生回到丹阳乡下。但是乡下也不太平，忠良弟忠民（高正 饰）不肯做走狗，上山打起了游击。 一九四零年，侵略者吊死了忠良父。素芬只得背子随婆回到上海，以对忠良的思念和期盼为支撑，在苦难中挣扎求生。 一九四一年，被俘后成功逃脱的忠良辗转到达重庆，困苦中只得投靠故交王丽珍（舒绣文 饰），并慢慢被堕落的物质生活所引诱，开始迷失自己。 一九四五年，日本投降，忠良和丽珍先后回到上海，住进丽珍表姐何文艳（上官云珠 饰）家。就在忠良与文艳厮混时，走投无路的素芬歪打正着被招入文艳家帮佣……©豆瓣', '白杨', '蔡楚生', 8.5, 15007, 'tt0040009', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503175729.jpg', 0.2, 0.5, 11.8, 47.9, 39.6, '0.080182,0.042579,-0.482348,0.088746,0.066186,-0.501651,0.256609,0.093150,-0.632321,-0.201496,0.111833,0.512875,-0.010426,0.272005,0.014108,0.074427,-0.414350,-0.648449,0.190447,-0.271326,0.044119,-0.377224,0.076470,0.001798,-0.165987,0.045788,0.613663,0.284923,0.170442,0.686385,0.179271,0.158765,-0.089103,0.251264,-0.124306,0.321053,-0.285816,-0.102972,-0.476662,0.126190,-0.182285,-0.514854,-0.214220,-0.420224,0.140882,0.066160,0.814159,-0.313299,0.119486,-0.499637,0.124493,-0.109969,-0.393063,0.466766,0.385032,0.231786,0.189052,0.501527,-0.331957,0.232315,-0.155124,0.067037,-0.251602,-0.021455,0.137076,-0.058821,-0.602480,0.324066,-0.043518,-0.000869,-0.016245,-0.550039,0.193091,0.415263,0.026815,0.560305,-0.446576,0.148250,-0.283440,0.256762,0.427390,-0.334280,-0.011097,-0.068819,0.310256,-0.285363,0.557148,-0.220771,-0.216077,-0.173897,0.022439,0.104008,-0.112493,0.179953,-0.623286,-0.025878,-0.575167,0.060102,0.304048,0.047172,-0.209115,-0.306548,-0.090771,-0.137289,-0.171825,0.192335,0.273085,-0.181930,0.503605,-0.745466,0.320088,0.090413,0.605611,-0.464516,0.319468,0.053842,0.155390,-0.107814,0.083415,0.408818,0.053358,0.577851,0.028248,0.063443,-0.446744,-0.053382,-0.119257,0.037141', '1451563', '34869495', '30345227', '1301562');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389918', '大公司小老板', '剧情', '51岁的霍丹（丹尼斯•奎德 饰）是一本美国权威杂志的广告部总监，事业得意的他家庭也十分美满。两名女儿非常出色以外，妻子最近又怀孕了。可是，霍丹的生活，因为事业上的突然转变，有了翻天覆地的改变。他的公司被大财团收购了，而他的职位将有一名叫卡达（托弗•戈瑞斯 饰）所替代， 而这位新人只有26岁，没有一点广告经验，这使霍丹气愤不已。为了家庭，霍丹不能就此辞职。与霍丹相反的是，卡达早已与妻子离婚，了无牵挂。两个男人也开始了办公室里的明争暗斗，令人意想不到的是，因为霍丹女儿爱丽斯（斯嘉丽•约翰逊 饰），使两位男士改变了自己的态度……©豆瓣', '丹尼斯·奎德', '保罗·韦兹', 6.7, 6461, 'tt0385267', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p725300224.jpg', 0.8, 8.7, 53, 29.4, 8.1, '0.297249,-0.174016,-0.649467,0.601437,-0.221063,-0.530395,0.781548,0.308359,-0.707570,-0.290518,-0.062040,1.035594,-0.126060,0.317847,0.194859,0.155707,0.004350,-0.820177,-0.140796,-0.252744,-0.146390,-0.482851,-0.313692,-0.272525,-0.418662,-0.287707,0.663700,-0.086375,-0.106694,0.417234,0.351745,0.309234,0.309841,0.589568,-0.036429,0.061368,0.192821,0.041732,-0.145241,0.005681,0.212759,-0.266982,-0.073783,0.611319,0.044164,0.612465,0.368137,-0.104367,-0.398165,-0.266487,0.651524,-0.165337,-0.087539,-0.037413,0.316436,-0.089684,0.110594,0.302662,-0.273436,-0.351094,0.167400,-0.165897,-0.858933,0.092645,0.143339,0.193401,-0.752512,0.457579,-0.401029,-0.358592,0.180283,-0.326336,0.217509,0.487034,0.291550,0.364147,-0.226433,0.001362,-0.543404,0.194253,0.628650,0.210673,-0.402093,0.402940,-0.595764,-0.297547,-0.072271,-0.457199,-0.572429,-0.048753,0.172037,0.110866,0.044366,0.164170,-0.321273,0.139319,-0.293086,-0.136900,-0.161862,-0.547700,-0.003870,-0.362165,-0.304067,-0.480082,-0.531498,-0.112418,0.250480,-0.381553,0.871112,-1.016538,-0.043333,0.404878,0.387406,-0.571973,0.872461,0.032726,0.177520,-0.214713,0.039451,-0.077448,-0.207517,-0.019598,-0.057426,0.424082,0.180261,-0.378551,-0.112749,0.560442', '1783461', '35030151', '1292720', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389923', '奇遇', '剧情', '安娜（蕾雅·马萨利 Lea Massari 饰）在与外交官父亲的一席不愉快的谈话之后，气愤地和女友克劳迪娅（莫尼卡·维蒂 Monica Vitti 饰）驾车去找男友桑德罗（加比利艾尔·费泽蒂 Gabriele Ferzetti 饰）。安娜犹豫着进了男友的公寓，留下克劳迪娅一人在外面等候。安娜虽然和桑德罗谈婚论嫁，但两人早已貌合神离。他们与一群朋友驾着游艇出海时，两人之间的矛盾越发尖锐。众人来到一个荒岛上休息，安娜与桑德罗言谈不和，两人不欢而散。正当众人准备返航时，却发现安娜神秘地失踪了。大家寻遍整个小岛，却不见安娜任何踪迹。在找寻安娜的过程中，克劳迪亚和桑德罗相互产生了暧昧，虽然克劳迪亚努力克制心中的悸动，但在桑德罗的热情追求下，她坠入了情网。内疚的克劳迪娅一直无法摆脱安娜的阴影，无法心无旁骛地与桑德罗在一起。而当她下定决心与桑德罗建立关系时，却发现他与别的女人在一起。影片获得1960年戛纳电影节评审团奖。', '加布里埃尔·费泽蒂', '米开朗基罗·安东尼奥尼', 8.2, 14072, 'tt0053619', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2620583227.jpg', 0.5, 1.8, 16.5, 48, 33.3, '0.546400,0.186821,-0.913827,0.528416,0.383830,-0.584882,1.070071,0.129877,-0.468112,-0.316967,-0.003635,1.000362,-0.466445,0.191633,0.314493,0.233057,-1.012304,-0.916777,0.176422,-0.115225,-0.182298,-0.624607,0.022136,-0.000708,-0.374970,-0.268576,0.564402,-0.008166,0.032869,0.838334,0.228149,0.164659,-0.291052,0.691385,0.006878,0.164928,0.253351,-0.163471,-0.336453,0.135412,0.292302,0.121722,-0.494090,0.098722,0.507718,0.290466,0.766270,-0.335279,0.081304,0.355730,-0.065629,-0.061577,0.219387,0.105088,0.011102,-0.258946,0.410203,0.050921,-0.249538,-0.043074,0.128665,0.038920,-0.365978,0.402670,0.088096,0.196717,-0.477213,0.432743,-0.146407,-0.127907,0.218849,-0.378078,0.048452,0.519392,0.059669,0.334905,-0.318886,-0.026362,-0.496835,-0.382085,0.657921,0.297372,-0.073253,0.322555,-0.249757,-0.365787,-0.577166,0.218678,-0.539797,-0.266555,0.462632,0.275897,-0.106781,0.419830,-0.743059,-0.172545,-0.491460,-0.008115,-0.096369,-0.646552,-0.128449,-0.864863,-0.062497,-0.337305,-0.418545,0.056943,-0.046094,-0.089326,0.436111,-0.933820,0.281051,0.367007,0.520756,-0.168873,0.822236,0.060515,0.257340,-0.276416,-0.178104,0.476415,-0.106828,-0.007510,0.305247,0.534969,-0.213008,0.304394,-0.717311,0.284590', '1296534', '1297239', '1301686', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389937', '珍妮和朱诺', '喜剧', '验孕棒告诉了十五岁的珍妮（朴敏智 饰）一个坏消息：她怀孕了。惊慌的她到学校找来同龄男友朱诺（金彗星 饰），两人不知所措。朱诺起初非常逃避，还是勇敢的珍妮带动他积极面对这一切，他们决定把这个小生命带到人间。但是，若大人知道此事，胎儿就比不能保住，于是他们要一同隐藏这个秘密。为了能让珍妮养好胎儿，朱诺慢慢担当起男人的责任。他送报纸，买丰富好吃的食物给珍妮，半夜跑到珍妮家探望她，令珍妮大为感动，保住孩子的决心也日渐坚定。未出世的孩子，让二人度过了提心吊胆而又快乐单纯的时光。纸包不住火，珍妮渐渐变大的肚子还是暴露了秘密，大人的责备也朝珍妮和朱诺纷纷袭来。她的孩子，她的感情，都面临着一次严峻的考验。©豆瓣', '金彗星', '金浩俊', 6.8, 13281, 'tt0453115', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1773994652.jpg', 1.1, 7.7, 50.2, 30.9, 10.1, '-0.023432,-0.042365,-0.750847,0.379556,-0.445510,-0.367977,0.644403,0.156280,-0.318881,0.030705,0.211902,0.584117,0.103061,0.337136,0.062252,0.122221,-0.327409,-0.371825,0.131354,-0.064801,-0.348868,-0.349220,-0.117854,-0.350007,-0.029100,-0.285424,0.295782,-0.153296,0.017632,0.403062,0.235652,-0.088695,0.027914,0.567574,-0.171706,0.107968,-0.175841,0.081592,-0.200117,0.228119,0.468785,-0.141292,-0.272934,0.464553,0.217592,0.425555,0.593730,-0.089986,-0.222804,0.025829,0.368986,-0.355600,-0.089036,0.124050,0.018116,-0.032508,-0.105597,-0.070387,-0.304426,-0.078809,0.120757,-0.055788,-0.648871,0.172206,0.124913,0.079464,-0.666018,0.259587,-0.124658,0.170115,0.331711,-0.413018,0.105248,0.460224,-0.030744,0.378871,-0.382091,0.110791,-0.478007,0.132265,0.577015,-0.201679,-0.038193,0.320226,-0.300156,-0.215578,0.319211,-0.233376,-0.664492,0.086917,0.354066,0.209411,-0.258303,0.342069,-0.261155,-0.135277,-0.365122,-0.265180,0.012909,-0.488491,0.044565,-0.064937,-0.155120,-0.221094,-0.339851,0.014155,0.144264,-0.178968,0.971452,-0.535620,0.167330,0.658154,0.256418,-0.677709,0.393912,0.118059,0.170230,-0.311428,0.027309,0.187516,-0.295572,0.176662,0.190165,0.364126,0.083119,0.051865,-0.566309,0.400662', '26348103', '24284209', '30163500', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389949', '日瓦戈医生', '剧情', '幼年丧母的日瓦戈（Omar Sharif 饰）被过继给母亲的朋友，自此与继母一家的小女儿冬妮娅一同成长，并顺利修完医学专业，成为了一名优秀的医生。在另一条平行的生命线上，出生于裁缝之家的拉娜（Julie Christie 饰）正是十七岁的金色年华，母亲的情人维克多不时骚扰她，热衷于工人革命的未婚夫帕夏更让拉娜日日为其担忧。在工人运动风起云涌的日子里，日瓦戈目睹了当局对工人的残酷镇压，拉娜则因帕夏被卷入工人运动而遭到维克多的玷污，由于维克多的关系，日瓦戈与拉娜的人生终于汇合，在不久后混乱的一战中，他们终于不顾各自的伴侣陷入了热恋……不久布尔什维克掌握政权，返回家乡与冬妮娅团聚的日瓦戈发现生活却每况愈下，以至他们不得不远赴乡村谋生，岂料在遥远的北方村落，日瓦戈再次与拉娜相遇……本片根据Pasternak的同名小说改编，获1966年奥斯卡最佳美术指导、最佳摄影等多项专业褒奖。', '奥马尔·沙里夫', '大卫·里恩', 8.5, 18665, 'tt0059113', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2201838179.jpg', 0.4, 1.3, 12.6, 42.8, 42.9, '0.331160,-0.152268,-0.550029,0.625407,0.079134,-0.600006,0.648120,0.213190,-0.521061,-0.281862,0.256252,0.818345,-0.137537,0.185229,0.407516,-0.046752,-0.356398,-0.828586,-0.148101,-0.204045,-0.180120,-0.447955,-0.302262,-0.134677,-0.175826,-0.403701,0.714783,0.100775,-0.143490,0.554941,0.059348,0.232954,-0.303807,0.157757,-0.332448,0.052868,0.036189,-0.044587,-0.613342,0.317512,-0.066635,-0.232258,-0.105428,-0.179554,-0.054793,0.395453,0.865182,-0.238571,-0.055938,-0.168700,0.637124,-0.125388,-0.113098,0.209482,0.433720,0.100748,0.207059,0.118808,-0.397426,0.038355,-0.238078,-0.300697,-0.760864,0.047728,0.125385,0.042675,-0.614180,0.605085,0.250832,-0.126100,0.200077,-0.224530,0.277760,0.653063,0.059459,0.678751,-0.198823,0.120456,-0.142657,0.351385,0.748155,-0.241135,-0.223630,0.287242,-0.119519,-0.356480,0.292522,-0.302594,-0.534521,-0.162202,0.424190,0.057213,-0.072486,0.347583,-0.521593,-0.131268,-0.362843,-0.223952,0.221680,-0.174197,0.088297,-0.607014,-0.060588,-0.278716,-0.142223,0.120205,0.054883,-0.233721,0.766448,-0.813448,0.513121,0.396047,0.281562,-0.578308,0.668014,0.106138,0.475089,-0.296165,-0.194291,0.703032,0.140862,0.344755,0.063146,0.118316,-0.133943,-0.186934,-0.348694,0.343593', '303