INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389971', '恋爱进行时', '爱情', '生长在单亲家庭的敏雅（林秀晶 饰）是个酷爱摇滚音乐的高中生，她并不是“不良少女”但却会吸烟喝酒。她是个浪漫主义的人，希望自己的爱情能够一帆风顺。一天，在敏雅楼下搬来了一名英俊的大学生英宰（金来沅 饰）。英宰直言不讳说自己对敏雅一见钟情，继而展开一系列的追求攻势，企盼能得到敏雅的欢心。虽然敏雅觉得英宰并不讨厌，可是她依然怀疑英宰的为人，她甚至跟踪英宰，想知道英宰结识的是什么朋友。经过英宰多番的努力，敏雅才向他敞开了心扉，两人开始了爱情故事。当敏雅向母亲诉说恋爱感受的时候，她对自己的这次初恋依然模糊。©豆瓣', '林秀晶', '李彦禧', 7.6, 13280, 'tt0381838', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p466516170.jpg', 0.4, 2.8, 34.8, 42.5, 19.5, '0.366438,-0.073953,-0.648403,0.641318,-0.347865,-0.225894,0.980951,-0.062785,-0.497271,-0.174006,0.189801,0.739794,-0.062529,0.355129,-0.011726,0.324701,-0.112195,-0.761187,0.102827,0.047877,-0.134944,-0.367581,-0.111678,-0.160710,-0.164247,-0.197802,0.473883,0.188360,-0.303539,0.365522,0.481015,-0.021809,0.332365,0.698893,-0.183550,-0.026335,-0.112892,0.131953,-0.125649,0.034484,0.221622,-0.326922,-0.343859,0.412752,-0.130662,0.410862,0.527482,-0.122148,-0.285614,0.179189,0.372920,-0.259283,0.131602,0.295495,0.174503,0.020694,0.181783,0.180662,-0.053262,-0.064967,-0.192955,0.027275,-0.624101,-0.161157,0.077449,0.241103,-0.467085,0.622607,-0.112855,-0.163799,0.090666,-0.249290,-0.026121,0.297396,0.122009,0.419901,-0.378978,0.130665,-0.480812,0.242407,0.786865,0.141370,-0.241696,0.929404,-0.450218,-0.422174,-0.217050,0.018669,-0.751460,0.047081,0.015988,0.103021,-0.324974,0.014413,-0.297839,0.068846,-0.025523,-0.026306,-0.031228,-0.670627,-0.068009,-0.186466,-0.173252,-0.606325,-0.340430,0.029807,-0.105459,-0.553840,0.888570,-1.157438,0.002565,0.686810,0.410544,-0.650976,0.819573,0.371510,-0.490762,-0.229628,-0.182901,0.472454,-0.239211,-0.136663,0.048739,0.521042,0.295930,-0.217290,-0.375019,0.406438', '3230462', '4275444', '21766698', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389980', '谁都有秘密', '喜剧', '性感美丽的美英（金孝珍 饰）在酒吧里当歌手，她吸引了无数的男人，也摔开了无数男人，男人对于她来说不过是件玩偶。直到秀铉（李秉宪 饰）的出现，让她彻底改变了不羁的性格，死心塌地爱上了秀铉。秀铉的出现，除了让美英疯狂以外，也包括了她的两名姐姐。美英的大姐珍英（秋相美 饰）是一名家庭主妇，她觉得她已过来恋爱的时期，生活平淡无奇。二姐善英（崔智友 饰）则是一名研究生，名副其实的书呆子，男欢女爱她都是从书本中认识到的。这两名姐姐同是都迷上了秀铉，情场老手秀铉周旋与这三名性格各异的姐妹当中，不亦乐乎。渐渐的，原本和睦的姐妹关系发生了变化，虽然美英还蒙在鼓里，但两名姐姐都心知肚明，既自责又嫉妒。©豆瓣', '李秉宪', '张贤洙', 6.3, 9922, 'tt0416080', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p687342830.jpg', 2.1, 13.7, 55.6, 22.9, 5.7, '0.410557,-0.263021,-0.648278,0.515014,-0.353728,-0.205449,1.052162,0.012981,-0.398056,-0.142275,0.338175,0.523829,-0.201700,0.183490,0.337282,-0.098425,0.046520,-0.781056,-0.211581,-0.265743,-0.094095,-0.189056,-0.337881,0.096862,-0.216453,-0.410496,0.419718,-0.225982,-0.161410,0.473762,0.509328,0.128159,-0.140256,0.423211,-0.033707,0.048812,0.087952,0.180613,-0.086370,-0.190706,-0.228049,-0.175157,-0.005872,0.189179,-0.060548,0.389659,0.704766,-0.207685,-0.082909,-0.030893,0.257856,-0.014008,-0.237169,0.176112,0.323540,0.003593,0.253528,0.057882,-0.132842,0.015351,0.012731,0.225241,-0.505728,0.348641,0.324715,0.213643,-0.499082,0.646147,0.129902,-0.322085,0.015395,-0.252047,0.280123,0.134624,0.163661,0.400306,-0.099063,0.102301,-0.575604,0.366513,0.706109,0.314619,-0.251501,0.504831,-0.242299,-0.378291,-0.105819,-0.292213,-0.525639,-0.024031,-0.042916,-0.228130,-0.107063,0.306047,-0.466196,0.177049,0.133988,-0.030258,-0.190245,-0.528684,0.083188,-0.205192,-0.348080,-0.798044,-0.469868,0.152920,0.145223,-0.254710,0.969198,-0.802612,0.059557,0.288722,0.096553,-0.533088,0.660351,0.342122,-0.010359,-0.066205,-0.318803,0.161347,0.060070,-0.192146,-0.050894,0.703305,-0.074054,-0.299785,-0.240790,0.374275', '24839498', '26354526', '26283288', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1389982', '实尾岛', '剧情', '60年代末朝鲜半岛南北局势紧张，双方都展开了疯狂的间谍与刺杀行动。1968年1月，康仁灿（薛景求饰）因谋杀罪名成立而被判死刑的，在行刑前突然被召到拘留室，与特种部队军官讨论替代死刑的条件，他将被送到西南部荒岛实尾岛接受特别军事训练。同时，另外30名死囚也接受了特种部队军官的条件，被征召到实尾岛执行特别任务。这31名死囚乘坐渔船到达实尾岛后，便在上级崔在贤中尉（安圣基饰）宣布下，组成了以刺杀朝鲜元首金日成为目标的“684北派部队”，并随即接受一连串地狱式的体能和军事训练。可是在三年后，由于韩国政府国策的改变，“684北派部队”的计划被取消，31名队员则前途未卜。他们纷感被国家出卖，只能设法自救……©豆瓣', '薛景求', '康佑硕', 8.1, 36926, 'tt0387596', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2265612013.jpg', 0.4, 1.8, 19.1, 49.7, 29, '0.061139,0.053765,-0.549964,0.447908,0.053084,0.076364,0.283824,0.104215,-0.415323,-0.063457,0.451636,0.469381,0.115457,-0.194197,0.652199,-0.440768,-0.476462,-0.885912,-0.281243,-0.314615,-0.509572,-0.669540,0.258181,-0.203408,-0.055340,-0.341442,0.947114,0.024066,-0.084571,0.366293,0.264442,0.324015,0.031882,0.341345,0.037389,-0.131954,0.468732,-0.442701,-0.330760,0.131771,-0.264664,-0.473378,-0.070051,-0.108373,0.028185,0.549317,0.768950,-0.474804,-0.268202,-0.322013,0.114535,-0.478349,-0.137355,0.167427,0.495995,0.291854,-0.098708,0.433393,0.024375,0.190525,-0.113233,-0.254740,-0.542410,0.091277,0.172062,-0.069843,-0.436087,0.362009,-0.381123,0.410458,-0.092547,-0.215269,0.111645,0.609406,0.174892,0.510072,-0.311196,0.130052,-0.345678,0.217961,0.541138,-0.217102,-0.427930,-0.358245,-0.118984,-0.695088,0.074620,-0.364057,0.165649,-0.036727,0.234785,0.035408,0.001986,0.120128,-0.436316,-0.063022,-0.176796,-0.410555,-0.096377,-0.354252,-0.036254,-0.742588,0.172022,0.183372,-0.235567,0.310855,0.349250,0.143308,0.488330,-0.666771,0.111133,0.317783,0.378604,-0.655075,0.304605,0.249754,0.354440,-0.221279,0.014282,0.088355,0.255120,0.692027,0.229716,0.190222,-0.229610,-0.235843,-0.164953,0.090630', '3266509', '25723905', '1449328', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1390006', '少林三十六房', '剧情', '清朝时，广州一地的反清复明义士积极与台湾郑成功一脉联络，以图驱逐异族。义士段将军与何老师等人为了营救反清同志，先后被广州将军天达镇压，何老师的学生刘裕德（刘家辉 饰）因积极参与反清，举家被天达手下鹰犬唐三要所害，刘裕德孤身逃脱，历尽艰苦抵达少林寺，希望能够习得少林功夫，救助苦难百姓，兼报家仇。其时少林寺设有三十五房，其中三十四房分别锻炼体力或拳脚兵器，法号三德的刘裕德天资过人，历经五年苦学，遍通三十四房，学成之际，刘裕德向方丈提出开设少林第三十六房，旨在接纳俗家弟子，传播少林武学。刘裕德离乡七年后重返广州，收洪熙官、陆阿采等青年为徒，与清廷鹰犬展开了连番激战……本片获1978年亚洲影展最佳动作效果奖。©豆瓣', '刘家辉', '刘家良', 7.6, 8162, 'tt0078243', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2181403020.jpg', 0.4, 1.7, 29.8, 51.1, 16.9, '-0.129256,-0.145205,-0.241053,0.363019,0.605894,-0.244636,-0.390929,0.106689,-0.578565,-0.620050,-0.084144,0.184489,-0.095253,0.135735,0.161230,-0.346851,0.132012,-0.386450,-0.211559,-0.118798,-0.139936,-0.305733,0.103926,-0.228826,-0.384213,-0.333243,0.517268,0.420709,-0.031225,0.480977,0.165504,0.153560,-0.116723,0.029014,0.134979,0.105033,0.014081,-0.204165,-0.684950,-0.044988,-0.250812,-0.605371,-0.339090,-0.288428,0.002372,0.275193,0.539850,0.074147,0.149017,-0.268457,-0.051491,0.001109,-0.186957,0.006731,0.397712,0.181325,0.109604,0.798595,0.284486,-0.069842,-0.273204,-0.149879,-0.040134,-0.163546,0.510941,-0.323791,-0.249486,0.379145,-0.315180,0.274288,-0.401838,-0.101696,-0.441901,0.508353,-0.032319,0.175856,0.187300,0.006032,-0.281101,0.427167,0.447941,-0.503210,0.013861,-0.145845,0.301855,-0.377732,0.444858,-0.372418,-0.096472,0.150836,0.190308,-0.050629,0.329278,0.124935,-0.130538,-0.302381,-0.659910,0.360397,0.124849,0.272190,0.107555,-0.661053,0.142244,0.177111,-0.093277,-0.072569,0.315331,0.081669,0.748700,-0.396527,-0.095491,-0.042480,0.259349,-0.467921,0.426310,-0.219205,0.347306,-0.141735,-0.139550,-0.032821,0.235122,0.357185,0.263228,0.055173,-0.378457,-0.100680,-0.131601,-0.262022', '1306998', '34964056', '1483630', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1390011', '富贵黄金屋', '喜剧', '骠叔（董骠 饰）与妻子骠婶（沈殿霞 饰）、二女儿（李丽珍 饰）、小女儿住在公屋里，已经结婚了的大女儿与女婿希望能搬到骠叔家同住。但本来骠叔家中就地方狭小，现在又迎来即将生育的大女儿与女婿。加上现居的周遭环境复杂，对妻子女儿们的出入造成很多的困扰。本来经济环境不算太好的骠叔，决定在香港楼价不稳定的状态下搬家。在寻找新家的过程中，好不容易找到了一层廉价的住房。一家六口兴高采烈的搬进了新家，心想就此安居乐业了。但没想到地产发展商看中了附近的地皮用作商业用途，企图牟取暴利。地产商用卑鄙手段试图赶走骠叔，骠叔一家决定与邻居一起抵抗地产商，誓要捍卫家园。©豆瓣', '董骠', '高志森', 7.6, 8471, 'tt0104310', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2577495823.jpg', 0.4, 2.4, 34.8, 43.7, 18.7, '0.147449,0.054921,-0.757699,0.371810,-0.101620,-0.167009,0.451229,0.423741,-0.462128,-0.375072,0.041840,0.623580,0.065070,0.355201,-0.035698,-0.003282,-0.106208,-0.268500,-0.071963,-0.053423,-0.220404,-0.494109,-0.269717,-0.383325,-0.161220,-0.210300,0.362644,0.316474,-0.184805,0.081752,0.158838,-0.017003,-0.125038,0.206273,-0.279114,-0.073356,-0.024715,0.249051,-0.660965,0.398085,-0.158790,-0.067602,-0.011710,0.030397,0.365395,0.389454,0.743178,-0.101350,-0.244358,-0.072867,0.144398,0.123889,-0.185342,0.281310,0.284730,-0.199965,0.503108,0.043299,-0.573304,-0.156163,0.228724,-0.330610,-0.545965,0.236830,0.297291,-0.326740,-0.693221,0.460996,0.066539,-0.223237,-0.165111,-0.540970,0.448615,0.410778,0.120980,0.596005,-0.212458,0.227749,-0.414299,-0.041881,0.688748,-0.004674,0.061239,0.275651,-0.313545,-0.156601,0.140002,-0.443525,-0.502532,-0.294820,0.154559,0.189738,-0.372649,0.058927,-0.524609,-0.050614,-0.360685,-0.087449,0.443176,-0.487266,0.170503,-0.405259,-0.098011,-0.252449,0.111591,0.166696,0.255807,-0.227882,0.455323,-0.693017,0.045865,0.184488,0.609267,-0.691530,0.594824,-0.058050,0.410740,-0.057034,-0.107722,-0.395782,0.014188,0.260399,0.225214,0.059637,-0.277284,-0.329372,-0.289869,0.366805', '1299965', '6890343', '1308035', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1390020', '那小子真帅', '喜剧', '智银圣（宋承宪 饰）是尚高的高中生，相貌英俊，性格暴躁，是尚高著名的四大天王之一，在周围高中，尤其是女子高中，声名显赫；韩千穗（郑多彬 饰）是普通的女高学生，长相平凡，但是性格善良可爱，充满活力。快开学了，千穗在网上游荡，偶然在学校留言板上看到了署名“智银圣”的人对全校同学的挑衅，千穗毫不留情地进行了反击，随后她接到了智银圣的恐吓电话，并莫名其妙地成了他的女朋友。在和智银圣的交往中，千穗慢慢了解到他桀骜不驯的外表下脆弱的内心世界，对情亲的渴望和对朋友的忠诚，二人之间有了真正的感情。©豆瓣', '宋承宪', '李焕庆', 6.8, 82152, 'tt0415819', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2173213167.jpg', 1.3, 8.1, 49.8, 29.3, 11.4, '0.566594,-0.000876,-0.640953,0.719318,-0.430052,0.043054,0.764398,0.154727,-0.497940,0.058207,0.142088,0.804285,-0.325443,0.315567,0.150242,0.074114,0.004031,-0.774202,-0.305371,-0.257782,-0.181598,-0.473123,-0.359530,0.019472,-0.071546,-0.604385,0.369533,-0.030675,-0.306229,0.811602,0.406768,0.138853,0.092649,0.453546,-0.377209,-0.122976,0.011016,0.188366,0.053476,0.123438,-0.024729,-0.241730,-0.046944,0.282703,0.036729,0.598729,0.594430,-0.025286,-0.410203,0.157718,0.539018,-0.123010,-0.228639,0.271947,0.683991,0.026797,0.352227,0.059151,0.032766,-0.046988,-0.101204,-0.078594,-0.528595,-0.025775,0.097957,0.198826,-0.540353,1.053215,0.028145,-0.338995,0.324798,-0.351617,0.102185,-0.113800,0.034491,0.478146,0.198710,0.189089,-0.106824,0.118206,0.557128,0.433061,-0.487531,0.416685,-0.449001,-0.519137,-0.168037,-0.421375,-0.601143,0.027509,0.268280,-0.127537,-0.209323,0.072680,-0.469171,0.028608,0.162509,0.236436,-0.046034,-0.640142,-0.338937,-0.334258,-0.324917,-0.980386,-0.528098,0.022559,-0.035305,-0.347938,1.222461,-1.303669,-0.036644,0.519626,0.399114,-0.451753,0.813504,0.271072,-0.318466,-0.069606,-0.121178,0.166000,0.183172,0.186316,-0.083929,0.546950,-0.212935,-0.255110,-0.508251,0.547882', '1292219', '6963575', '1826173', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1390021', '我的小小新娘', '喜剧', '24岁的大学生尚明（金来沅 饰）从爷爷那里接来一道不可思议的命令：他必须和16岁的中学生宝恩（文根英 饰）结婚。话说这是上一代人承诺，却让这两个相差八岁、不同世界的两个人莫名其妙的踏上了婚姻殿堂。这个太早到来的婚姻让宝恩非常不习惯。她本来喜欢着棒球队的男生，结了婚还偷偷跑出来和他约会。尚明还算是有责任心的男人，无论如何都想照顾好小妻子，直到他到宝恩学校担任实习老师，尴尬事一桩桩接连到来！他既不能让别人知道自己有个16岁妻子，又要招架年轻女老师的追求，和宝恩的婚姻更是吉凶未卜。©豆瓣', '金来沅', '金浩俊', 7.1, 61194, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p731909187.jpg', 0.6, 4.6, 46.7, 36.2, 11.9, '0.366726,-0.180856,-0.698412,0.418044,-0.436162,-0.406287,0.614634,0.112479,-0.405295,-0.305899,0.120556,0.679725,-0.181462,0.577561,0.167938,0.137675,-0.038419,-0.520707,0.118481,-0.186033,-0.397179,-0.392582,0.085352,0.101545,-0.217461,-0.123992,0.283210,-0.144767,-0.007529,0.429777,0.559502,-0.173115,0.347367,0.495323,-0.362333,0.053701,0.041766,0.418358,-0.001369,-0.000479,0.087931,-0.084158,-0.157620,0.120155,-0.112158,0.436965,0.348621,0.189309,-0.209460,-0.025329,0.462362,-0.371618,-0.213959,0.192904,0.276443,-0.120240,0.173595,0.199602,-0.075546,-0.050826,-0.016416,-0.175447,-0.552222,0.254466,0.093515,0.023943,-0.793144,0.487050,-0.034033,-0.125598,0.375253,-0.385680,-0.023384,0.404822,-0.064786,0.558295,-0.418431,0.116316,-0.693953,0.292283,0.866956,0.045633,-0.295449,0.358501,-0.176566,-0.423669,0.052358,-0.224998,-0.705785,0.213878,-0.071720,-0.221030,-0.215665,-0.152148,-0.236623,0.099665,0.002753,0.025249,0.063940,-0.626482,0.084767,-0.140722,-0.203214,-0.550267,-0.647137,0.290666,0.123573,-0.246568,0.861400,-0.715895,-0.052233,0.494980,0.571578,-0.420954,0.950802,0.615140,0.102050,-0.438368,0.007051,-0.028090,-0.308812,0.236103,-0.092710,0.471225,0.170089,-0.144004,-0.541705,0.453425', '1292720', '1456503', '1302384', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1393479', '韩城攻略', '剧情', '刑警林贵仁（梁朝伟饰），隶属日本国防外务科特别侦缉组。美国政府悬红三千万美元追查号称“复仇者”的美金伪钞电版，林获知电版到了香港，便孤身深入黑帮内部盗取，却碰上美艳动人的女飞贼JJ（舒淇饰）。二人合力偷出电版，在最后关头JJ却出卖林，挟着电版逃脱。JJ得手后喜悦地打开铁箱一看，里面却早已被掉包。贵仁持着真的电版送往美国领事馆领赏，接待他的是领事馆职员Owen（任贤齐饰）。Owen带走电版称找专家验收，林却突然醉酒昏倒，醒来才知电版竟被Owen设计骗走。林贵仁于是追踪Owen到韩国，展开一场斗智斗勇的追逐战。其后不但引来JJ的介入，林贵仁更要面对伪钞集团龙头“北极熊”的连番狙击。©豆瓣', '梁朝伟', '马楚成', 6.1, 74329, 'tt0455116', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2192081890.jpg', 2.3, 15.1, 61.7, 17.3, 3.6, '-0.013873,0.174744,-0.587068,0.299682,0.108882,-0.383190,0.496594,-0.088946,-0.148075,-0.224080,0.183473,0.091943,-0.259096,0.095895,0.205132,-0.165887,-0.178149,-0.585771,-0.357203,-0.121970,-0.172699,0.014682,-0.378662,-0.224108,0.089936,0.066254,0.571831,0.369845,-0.523781,0.167290,0.529877,0.277126,-0.455418,0.469012,0.076516,-0.055548,0.290001,0.078822,-0.128168,0.243806,0.052792,-0.499201,-0.075333,-0.103903,0.219844,0.318154,0.502471,-0.196041,0.048025,-0.175864,0.352861,-0.380770,-0.107645,-0.301831,0.659000,0.229174,-0.055025,-0.046974,-0.461911,0.063447,0.358555,0.063189,-0.488934,0.230722,0.331156,0.081364,-0.313682,-0.247546,-0.321351,0.553665,-0.035544,-0.137171,0.222583,0.294140,0.181199,0.066411,0.279290,0.229004,-0.582427,0.309712,0.399396,-0.125257,0.073050,-0.319559,0.180397,-0.477450,0.298654,-0.194048,0.258116,-0.067118,0.509958,-0.160761,0.207018,-0.105859,-0.453266,-0.241888,-0.443040,0.028080,-0.180347,-0.243687,0.369979,-0.968013,0.014677,-0.024074,-0.114383,0.452413,0.213940,0.004647,0.232210,-0.207617,-0.019329,0.480144,0.337571,-0.254268,0.161817,-0.002777,-0.184699,-0.204571,-0.238642,0.128755,0.585155,0.414215,0.101002,0.136804,-0.104685,-0.416501,-0.114258,-0.105709', '4014397', '2973528', '25723905', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394163', '呆佬拜寿', '剧情', '招福（刘青云 饰）原本是个不可一世的少爷，母亲是个寡妇，一心想儿子可以成家。招积（黄子华 饰）是招福的堂弟，也是招家的第二继承人。招积一直对招福不满，于是在街头游说在街头卖艺的望弟（吴倩莲 饰）与招福结婚以骗取聘礼。成亲当天，招积故意让招福在高处坠下，招福自此变成了痴呆，望弟与父亲（元华 饰）趁机逃走了。不久，望弟遇到了流落街头的招福，处于内疚与同情，望弟收留了招福。在望弟的细心照顾下招福日渐康复，两人日久生情。另一方面招家上下都无法容忍招积的行为，便请来了太叔公（乔宏 饰）重选当家，望弟觉得招福有权利争取到自己的一切，便努力训练招福……©豆瓣', '刘青云', '谷德昭', 7.6, 34020, 'tt0112779', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2407176748.jpg', 0.3, 1.9, 31.8, 48.5, 17.4, '0.086074,-0.148489,-0.490807,0.172021,-0.084550,-0.314100,0.368471,0.292055,-0.530128,-0.064719,0.368157,0.767600,-0.021023,0.279340,0.169363,0.062571,-0.033623,-0.526332,0.061231,-0.027602,0.033373,-0.491802,-0.131290,-0.071919,-0.227824,-0.294883,0.239995,0.057445,-0.046882,0.570670,0.374308,0.159624,0.103220,0.240010,-0.243682,0.242271,-0.318458,0.017356,-0.336401,0.075221,-0.018664,-0.237311,-0.150910,-0.033839,0.133563,0.295413,0.597907,-0.200166,-0.194076,-0.194673,0.197314,-0.179565,-0.011443,0.412921,0.399107,-0.269377,0.209349,0.284076,-0.523974,0.079091,0.146614,0.117174,-0.688061,0.137995,0.185209,0.108348,-0.752198,0.349697,-0.031347,-0.236970,0.051475,-0.566097,0.347647,0.341024,0.082134,0.512439,-0.323547,-0.000770,-0.583873,0.138208,0.475053,0.134697,0.190128,0.271558,0.236475,-0.037528,0.175415,-0.297397,-0.493098,-0.197029,0.248645,-0.012892,-0.151769,0.185959,-0.256130,-0.099703,-0.240611,-0.117699,0.293669,-0.369534,0.111811,-0.145160,-0.182679,-0.489902,-0.165212,0.072715,0.299550,-0.282846,0.488582,-0.900481,0.120046,0.196837,0.444917,-0.696953,0.530199,0.346324,0.225598,-0.276732,-0.045201,-0.243723,-0.108403,0.155692,0.155716,0.207608,0.023752,-0.160734,-0.342590,0.172427', '1299965', '1877596', '1306133', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394176', '咖啡与香烟', '剧情', '本片是由11个黑白短片综合而成的短篇集，每个短片都围绕咖啡与香烟展开。一。罗伯托·贝尼尼（罗伯托·贝尼尼 Roberto Benigni 饰）坐在一家咖啡馆喝着咖啡，史蒂夫·赖特（史蒂夫·赖特 Steven Wright 饰）过来与他攀谈，然而两人似乎没有什么共同语言 ，只在重复表达对咖啡与香烟的热爱……二。一家咖啡厅里坐着一对黑人双胞胎兄妹，咖啡厅服务员突然对他们很感兴趣，即坐下与之热情交谈，然而兄妹俩似乎对这个不知所云的人毫无兴趣，只在继续抽烟喝咖啡……三。加利福尼亚某处的一家咖啡馆，流行歌手伊基·波普（伊基·波普 Iggy Pop 饰）与汤姆·威兹（汤姆·威兹 Tom Waits 饰）正在以抽烟的方式庆祝他们戒烟成功。该短片曾获1993年戛纳电影节短片单元金棕榈奖。……十一。这天夜里，喝着速溶咖啡、抽着卷烟的两个老人William Rice（William Rice 饰）与Taylor Mead（Taylor Mead 饰）谈论起过去的音乐。在这个有些忧伤的话题进行到一半时，Taylor像孩子般熟睡过去了……', '罗伯托·贝尼尼', '吉姆·贾木许', 8, 10625, 'tt0379217', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p462534831.jpg', 0.5, 2.1, 22, 48.8, 26.5, '0.539757,0.013090,-0.640366,0.434682,0.202975,-0.545089,1.123653,0.382571,-0.289136,-0.119265,-0.114220,0.843821,-0.423885,0.327006,0.464047,-0.119655,-0.363522,-0.728681,-0.054684,0.037314,-0.087663,-0.476388,-0.071699,-0.033654,-0.162302,0.067095,-0.203806,-0.365782,-0.072301,0.534072,0.385446,0.111274,-0.259970,0.375225,-0.095944,-0.164500,0.125287,-0.016005,-0.339319,0.094976,0.141453,-0.165918,-0.513198,-0.088421,0.206184,0.088505,0.738580,-0.354562,-0.207436,0.073589,0.027608,-0.173372,-0.069502,0.054719,0.350046,0.106491,0.359813,-0.085199,-0.069634,0.264003,-0.214961,-0.251728,-0.310282,0.152140,-0.354905,0.429430,-0.412771,0.708986,-0.097673,-0.217083,0.101088,-0.370377,0.106158,0.158401,0.160688,0.458774,-0.062152,-0.162790,-0.756088,-0.069016,0.235154,0.436586,-0.205734,0.586684,-0.143278,-0.243573,-0.377220,0.147306,-0.472553,-0.237942,0.285442,0.024381,0.252963,-0.178865,-0.956158,-0.043702,0.202869,-0.343814,0.485268,-0.203622,-0.172252,-1.035077,-0.012070,-0.366334,-0.080359,-0.017318,0.218225,-0.138514,0.686941,-0.617298,0.092319,0.358848,-0.151708,-0.104224,0.671503,0.058385,0.037771,-0.244676,-0.214383,0.002005,0.01271