INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394218', '桃色公寓', '剧情', 'C. C. Baxter（杰克·莱蒙 Jack Lemmon饰）是纽约一个大公司的小职员，他的单身公寓经常被公司的高层们用去当作幽会的场所，Baxter也因此获得不少升迁的机会。Baxter暗恋着公司的电梯女郎Fran Kubelik（雪莉·麦克雷恩 Shirley MacLaine 饰），这天他终于鼓起勇气约了她晚上一起去看一出戏剧。然而Baxter等了一晚却未见Fran的踪影，原来Fran是公司的高管有妇之夫Jeffery Sheldrake（弗莱德·麦克莫瑞 Fred MacMurray饰）的地下情人，那晚他们还在Baxter的公寓幽会。Jeffery信誓旦旦向Fran表示，他将和他的妻子离婚然后和她名正言顺地在一起。Fran相信了，然而几个星期后她又从Jeffery的上一任情人知晓了Jeffery所说的不过是个谎言。另一方面，在一个夜里，当Baxter回到他家的时候，意外地发现Fran竟倒在他的床上，并且服了很多安眠药企图自杀......本片获1960年奥斯卡十项提名，赢得包括最佳导演、最佳影片在内的五项大奖。', '杰克·莱蒙', '比利·怀尔德', 8.8, 43070, 'tt0053604', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501319736.jpg', 0.1, 0.5, 8, 42.7, 48.7, '0.344851,0.198260,-0.854301,0.531882,-0.326977,-0.423633,0.652967,0.223312,-0.453768,-0.146325,0.135924,0.946377,-0.447040,0.339521,0.245239,0.051715,-0.334684,-0.807793,-0.249017,-0.331747,-0.350005,-0.441544,-0.171292,-0.081926,-0.045577,-0.140688,0.424929,-0.039547,0.099286,0.430931,0.505988,0.009104,0.112377,0.473277,-0.223460,0.030501,0.298377,0.204101,-0.123689,0.572553,0.097606,-0.343578,-0.328350,0.156961,0.295342,0.386678,0.507245,-0.027030,-0.131615,0.044246,0.379603,-0.121390,0.003687,0.115019,0.403993,-0.055959,0.414363,0.277687,-0.335440,-0.044077,0.181261,0.027349,-0.790609,0.132686,0.064814,-0.021409,-0.744225,0.498876,-0.106727,-0.021672,-0.051651,-0.391546,0.323798,0.365951,0.009691,0.329865,-0.151225,0.158752,-0.727937,0.271824,0.515153,0.085958,0.022872,0.411174,0.225342,-0.504079,-0.117545,0.098958,-0.442778,-0.036769,0.477840,-0.120201,-0.280642,-0.279271,-0.514696,-0.158367,-0.330779,-0.345366,-0.023322,-0.388947,0.040706,-0.640768,0.080245,-0.231387,-0.236558,0.083670,0.183135,-0.209877,0.559064,-0.826869,0.235298,0.621565,0.216201,-0.549511,0.945380,0.091597,0.117881,-0.055202,0.076244,-0.099469,0.107064,0.263748,0.308770,0.502957,-0.001250,-0.331168,-0.505322,0.363660', '3055049', '1783461', '30162520', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394315', '甲午风云', '历史', '1894年，蓄谋侵华已久的日军在中国领海内肆意制造事端，昏庸胆小的西太后为息事宁人，委派北洋大臣李鸿章（王秋颖）及其亲信、“济远”号管带方伯谦（周文彬）等人去与日军讲和，傲慢无礼的日军却将中国商船击落。以“致远”号管带邓世昌（李默然）为代表的爱国官兵两次请命同日军作战，李鸿章均拒绝，并借邓世昌揭露方伯谦渎职之机将其革职。日军不宣而战，民愤四起，顶不住压力的李鸿章重新启用邓世昌。海战中，贪生怕死的北洋水师右翼总兵刘步蟾（李颉）打错旗号，致使北洋舰队出师失利，旗舰被日军击沉。邓世昌见势立即挂起帅旗，替代旗舰指挥作战，率领“致远”号官兵与日军展开殊死大战，行为可歌可泣。©豆瓣', '浦克', '林农', 7.6, 8424, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2197403024.jpg', 0.9, 2.2, 29.4, 49.2, 18.3, '0.094429,-0.105006,-0.617138,0.597139,0.288949,0.143529,0.229620,0.018163,-0.542570,0.270834,0.361998,0.351261,0.573399,-0.572857,0.259546,-0.163066,-0.506038,-0.852741,-0.101241,0.204406,0.213498,-0.478412,0.072553,-0.249119,-0.001263,-0.094292,0.817957,0.010479,-0.185945,0.587277,0.259844,0.224463,0.407173,0.802882,0.333419,0.237261,-0.132256,-0.839191,-0.271811,-0.173657,-0.419626,-0.391709,-0.161213,-0.148963,-0.148206,0.349177,0.691157,-0.559580,0.165434,-0.338996,-0.191909,-0.367770,0.179699,0.142448,0.575618,0.466029,-0.263112,0.313467,0.025095,0.215527,-0.217185,0.508946,-0.074396,-0.247580,-0.208124,-0.290114,0.209103,0.534372,-0.459009,0.657896,0.040574,0.024753,-0.197535,0.626846,-0.173083,0.030045,-0.440816,0.254204,-0.272524,0.324650,0.312029,-0.188921,0.017521,-0.514050,0.296461,0.186466,0.488292,-0.763469,0.108562,-0.226218,0.105587,-0.444814,0.417764,0.243526,-0.660013,-0.046098,-0.589490,-0.162442,-0.023388,-0.020313,-0.202937,-0.621343,0.127316,-0.103525,-0.242010,0.346654,0.250292,0.470758,0.466299,-0.276452,-0.267499,0.278020,0.119124,-0.572850,0.355168,0.675642,-0.068567,-0.071581,0.130499,0.074493,0.026222,0.591710,0.064333,0.052469,-0.169342,-0.363188,0.122574,-0.219831', '1307201', '7065161', '1917171', '1424551');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394324', '东方不败之风云再起', '动作', '水师提督顾长风（于荣光饰）奉朝廷之命带领西班牙舰队探访黑木崖，过程中西班牙领队欲打开东方不败的棺木与视东方不败为偶像的顾长风发生争执。正在此时黑木崖上忽然现身一怪人（刘洵饰），可以以掌接西班牙火枪子弹。顾长风被怪人所救，却身受内伤，坚信其便是东方不败，坚持要一见其真面目 ，虽死无憾。怪人一偿所愿，让其看自己的庐山真面目，正是当年风采依旧的东方不败（林青霞饰）。顾长风告诉东方不败江湖上有很多人正在冒充他的名号为非作歹，东方不败于是决定留其性命，让他看着自己重出江湖。与此同时，东方不败旧时爱妾雪千寻（王祖贤饰）正率领着一群苗人打着东方不败的旗号与日本倭寇就海域问题谈判，雪千寻痴心不改，重组神教只是为了等待爱人归来......©豆瓣', '林青霞', '李惠民', 7.4, 97758, 'tt0105655', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2024262361.jpg', 1.1, 5.7, 33.7, 40.5, 19, '-0.207235,0.221059,-0.560597,0.497727,0.070963,-0.532081,0.494198,0.092669,-0.621176,-0.153557,0.145448,0.549036,0.092919,0.216253,0.140919,0.067240,-0.121811,-0.771533,-0.522239,-0.094731,-0.292252,-0.053842,-0.121525,-0.328017,-0.285781,0.095230,0.590205,0.131372,-0.152306,0.378286,0.523239,0.183289,-0.075237,0.642160,-0.293247,-0.185024,-0.280114,-0.192501,-0.419972,0.129082,0.048615,-0.459318,-0.498395,0.325141,-0.323084,0.249146,0.498027,-0.211183,0.036406,-0.491689,-0.122474,-0.191146,0.385350,-0.071516,0.295487,0.032059,0.111177,-0.001418,0.128393,-0.002919,-0.061408,0.007838,-0.305633,-0.050490,0.060161,0.004020,-0.331317,0.120079,-0.368744,0.131431,-0.059768,-0.349164,-0.071574,0.163421,0.376652,-0.214001,-0.097290,-0.116842,-0.445449,0.389981,0.317266,0.185939,0.224319,0.004173,0.174184,-0.144339,0.264636,-0.212607,-0.209567,-0.143184,0.495745,-0.130500,0.226983,0.105063,-0.052436,-0.121511,-0.421499,0.187397,-0.210483,-0.213799,0.035922,-0.441802,-0.140692,-0.166222,-0.031234,0.208975,0.312778,0.068556,0.500398,-0.533458,0.006904,0.246855,-0.016651,-0.378891,0.300581,0.236341,-0.036709,-0.167058,-0.229047,0.336357,0.186985,0.265425,0.028175,0.006946,0.120619,0.042090,-0.346418,0.061879', '1301022', '1307922', '1309297', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394342', '通往绞刑架的电梯', '剧情', '前伞兵军官朱里安•塔维尼（Maurice Ronet 饰）退役后在一家军火公司上班，期间他和老板西蒙•卡瑞拉（Jean Wall 饰）的妻子弗洛伦丝（Jeanne Moreau 饰）陷入热恋。为了扫清障碍，他和情妇制定了一条看似天衣无缝的谋杀计划。计划起初进展顺利，但在刺杀之后却因细微的差错偏离当初的设想，朱里安更被困在大楼的电梯之中。所谓祸不单行，一对青年男女偷走了朱里安的车，事态开始朝着混乱的方向发展……本片为左岸派元老路易•马勒的长片处女作，荣获1957年路易•德吕克奖©豆瓣', '让娜·莫罗', '路易·马勒', 8.3, 8255, 'tt0051378', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2174125862.jpg', 0.2, 0.9, 14.7, 53.7, 30.5, '0.044853,-0.000314,-0.628017,0.506069,0.247404,-0.451062,0.716355,0.264205,-0.326186,-0.227651,0.094309,0.293986,-0.247598,-0.119666,0.597692,-0.162223,-0.572797,-0.647980,-0.082294,-0.088002,-0.115498,-0.511500,-0.140617,-0.517915,-0.090974,-0.264129,0.676817,0.384455,-0.177280,0.179349,0.335009,0.173817,-0.277928,0.127842,0.194393,0.054706,0.592030,-0.071605,-0.327529,0.176670,-0.004354,-0.276395,-0.022250,0.008140,0.241127,0.653869,0.577659,-0.209500,-0.036354,0.028601,0.224401,-0.200821,0.093607,-0.123539,0.511969,0.052363,0.057062,0.190380,-0.176578,-0.050397,0.003655,-0.393997,-0.550711,0.034951,0.221830,-0.040207,-0.723988,0.236089,-0.150937,0.257357,0.010987,-0.447979,0.155418,0.530076,0.611863,0.123381,-0.069229,0.199797,-0.512192,0.147015,0.469045,-0.149803,-0.182073,0.324909,-0.029399,-0.598826,-0.246778,0.203486,-0.331175,-0.104238,0.589809,-0.117871,0.269727,0.263722,-0.236088,-0.290532,-0.321745,-0.088745,-0.177157,-0.313875,-0.209003,-0.559859,0.221701,-0.223745,-0.037402,-0.069169,-0.193766,-0.066877,-0.040019,-0.591997,0.246804,0.265730,0.107520,-0.468119,0.581507,-0.157964,0.176496,-0.374558,-0.252309,0.191518,0.054272,0.189182,0.206629,0.254157,-0.062073,-0.358930,-0.102371,0.352179', '1298197', '1305249', '1293936', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394424', '弓', '剧情', '在一望无际的大海上有两艘渔船，主人是一位年过花甲的老人（全成焕饰），他依靠两艘船谋生，陆上的人们来这边钓鱼或看风景。老人和一位少女（韩业云饰）一起生活，她是10年前老人在岸上捡到的，此后少女再没有上过陆地。老人等着少女年满17岁时就会与之结婚。来钓鱼的男人们经常想占女 孩的便宜，老人为保护女孩不得不用利箭来警示对方。一天，和父亲一起来钓鱼的大学生（徐智锡饰）在船上为神秘的少女所吸引。老人觉得事情不妙，每天监视少女并不允许她靠近大学生，而16岁的少女也逐渐对外面的事物产生好奇。大学生得知女孩儿将要和老人结婚，就决定带上少女逃到陆地……©豆瓣', '韩业云', '金基德', 7.7, 46044, 'tt0456470', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2197627924.jpg', 1.1, 3.5, 27.2, 46, 22.1, '0.051945,-0.445438,-0.740597,0.394555,-0.529715,-0.222072,1.014166,-0.190480,-0.625248,0.086257,0.281430,0.856362,-0.024636,0.575519,0.572929,0.332556,-0.313840,-0.334452,-0.099280,-0.260517,-0.483199,-0.300435,-0.080562,-0.224692,-0.266325,-0.393841,0.616773,0.014264,-0.034085,0.425708,0.024361,-0.320371,-0.206759,0.682809,-0.402945,-0.138832,-0.242103,-0.050606,0.042098,0.276458,-0.166580,-0.204728,-0.347929,-0.056101,-0.118114,0.398476,0.818008,-0.166869,-0.068403,-0.109829,0.038271,0.090905,0.127396,-0.019282,0.582485,-0.178993,0.047985,-0.239428,0.017281,-0.278002,-0.095938,-0.049818,0.118099,0.176659,0.126402,0.303275,-0.601261,0.270771,0.057064,-0.145277,0.136046,-0.610638,0.004078,0.085047,-0.054669,0.379210,-0.028947,-0.027508,-0.583545,0.452797,0.771766,0.331939,-0.104974,0.299879,-0.228252,-0.273661,-0.136354,-0.378024,-0.675877,-0.075852,0.107363,0.011698,-0.407443,0.064555,-0.237192,0.179386,-0.007785,-0.163471,0.051213,-0.277119,-0.335967,-0.426660,0.285059,-0.346975,-0.029765,0.492931,0.371117,-0.299807,0.980002,-0.761267,0.194235,0.822392,0.493596,-0.268106,0.920242,-0.347681,0.113708,-0.388669,-0.176781,-0.083370,-0.139303,0.237310,-0.030583,0.324359,-0.140140,-0.095958,-0.186921,0.150208', '2081098', '1302384', '1783772', '1308831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394466', '黑狱断肠歌之砌生猪肉', '犯罪', '六十年代的香港警界贪污成风，导致黑狱重重，《正报》记者程安（梁朝伟 饰）撰文揭露警界黑幕，被探长张耀祖（吴毅将 饰）视为眼中钉。张耀祖陷害程安藏毒，使其入狱，更将程的女友小慈（张文慈 饰）玷污。程安在狱中作为帮派人士之外的“羊”，虽有羊头飞机木（吴孟达 饰）看顾，也受尽大佬们侮辱。程安凭借正气与知识为犯人声张权利，逐渐获得大佬们尊重，狱中生活有所好转。不久看守“无人性”（林国斌 饰）将犯人“三只脚”（徐锦江 饰）害死，程安借报界朋友使三只脚冤仇得雪。小慈依靠另一探长势力将张耀祖下狱，沦为犯人的张耀祖计划在狱中报复程安，两人的对决在所难免……©豆瓣', '梁朝伟', '邓衍成', 7.2, 9872, 'tt0154321', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510465622.jpg', 0.7, 3.6, 43.4, 39.5, 12.9, '-0.042519,-0.190599,-0.009028,0.062770,0.100428,0.032501,0.545647,0.383108,-0.634138,-0.159803,0.432690,0.360644,0.109220,0.295602,0.075242,-0.441216,-0.121506,-0.581039,0.108126,0.035488,0.074266,-0.367657,-0.211951,-0.020492,-0.184678,-0.165288,0.559283,-0.067268,-0.473966,0.244630,0.145590,0.195215,-0.184475,0.025189,0.183457,0.101082,0.045403,-0.240532,-0.462290,-0.243748,-0.188920,-0.327420,-0.157352,-0.051721,0.023655,0.208863,0.533921,-0.195552,-0.070655,-0.594363,0.350808,-0.451816,0.014083,0.265020,0.412033,0.236221,0.246691,0.430187,-0.278047,0.146200,0.355284,0.015066,-0.473582,0.072293,0.401600,0.116456,-0.324324,0.191565,-0.129712,0.325709,-0.020262,0.027538,0.050992,0.078398,0.056847,0.174111,-0.032472,0.215998,-0.308107,0.270095,0.263948,-0.238155,0.141286,-0.472427,0.261746,-0.249507,0.075065,-0.351514,-0.151591,-0.312559,0.458649,-0.247586,0.007282,0.351607,-0.403558,-0.219831,-0.180872,0.199252,0.039705,-0.046353,0.001680,-0.431789,-0.175932,-0.022166,0.041828,0.102302,0.444266,-0.235187,0.687254,-0.375272,0.134723,0.007839,0.236601,-0.727968,0.245210,0.067385,0.108220,-0.246489,-0.083987,-0.024013,0.592436,0.245585,0.187134,-0.105121,-0.227937,-0.351954,0.243509,-0.087849', '34957970', '6557030', '1293265', '1302110');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394470', '生化寿尸', '喜剧', '无敌（陈小春 饰）和丧B（李灿森 饰）是两个无所事事的小混混，他俩平常在商场的VCD专柜打工，插科打诨，悠哉度日。某天两人奉老板之命外出取车，回来的路上撞到一个西装革履的黑帮分子。该男子身上藏有一种最新的生化武器，可以将人类变为强大无比的丧尸。两人阴差阳错将药水灌进男子的嘴里，又载着男子带回了商场。入夜，商场内鸦雀无声。喝下药水的黑帮分子终于变成了丧尸，四处残害无辜之人，而被他咬过的人也一一变成丧尸的同类。无敌和丧B怎样才能逃脱这些恶魔的追逐呢？©豆瓣', '陈小春', '叶伟信', 6.7, 11114, 'tt0277605', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2043311681.jpg', 1.8, 9.5, 51.4, 28.3, 9, '0.453028,0.047148,-0.390708,0.255932,-0.192323,-0.013764,1.142657,0.049126,-0.376379,0.178323,0.290792,0.658783,-0.260697,0.192039,0.555019,-0.072448,0.086471,-0.556214,-0.211355,-0.045389,-0.270849,0.012194,-0.547736,-0.351547,-0.068562,-0.129589,0.566418,-0.025783,0.014130,0.453171,0.289938,0.333233,-0.425669,0.462183,-0.519480,0.025224,-0.089945,-0.268788,0.130805,0.183047,-0.018077,-0.496551,0.022681,0.038623,-0.148722,-0.162668,0.988520,-0.153592,-0.035698,-0.336096,0.116641,-0.300771,-0.218526,0.107894,0.432981,0.047067,0.258368,-0.029468,0.229939,0.062389,0.229224,0.212573,-0.459518,-0.229381,-0.144790,0.188660,-0.609681,0.537647,0.109609,0.111097,0.064989,-0.411044,0.084120,0.004942,-0.005477,0.499513,0.093855,-0.261902,-0.951045,0.223513,0.521429,-0.185614,-0.193595,0.215405,-0.055810,-0.427379,0.092487,-0.418257,-0.387392,-0.228027,0.510038,0.048167,-0.419043,0.083808,-0.916444,0.093655,-0.127530,-0.150660,-0.043770,-0.108857,-0.481922,-0.573664,-0.068296,-0.391726,-0.063295,0.417034,0.171560,0.107053,0.500980,-0.662349,0.005674,0.434247,0.170813,-0.365113,0.518071,-0.480354,0.098305,0.150440,-0.230395,-0.192466,0.504023,0.606047,0.305318,0.645015,-0.327950,0.166249,-0.257363,0.145697', '21619567', '1467779', '1578663', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394490', '浪荡子', '剧情', '故事发生在17世纪的英国，诗人约翰·威尔默特（约翰尼·德普 Johnny Depp 饰）以其满溢的才华和不羁的性格成为查尔斯二世（约翰·马尔科维奇 John Malkovich 饰）的宠臣。他古怪的行事风格遭人非议，还时常大写淫秽诗篇讽刺贵族的淫乱生活，他天生不羁蔑视社会伦理，结识了特立独行的女演员伊丽莎白·巴里（萨曼莎·莫顿 Samantha Morton 饰）坠入爱河，又和男演员道恩斯（鲁珀特·佛兰德 Rupert Friend 饰）发生暧昧关系。但长期纵欲和酗酒，加之触怒皇室被多次流放，过度燃烧了诗人的生命，他开始饱受失明、关节炎、臆想症的困扰，最终证实身患梅毒，在33岁时黯然逝去。©豆瓣', '约翰尼·德普', 'Laurence Dunmore', 7.5, 6917, 'tt0375920', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1087664145.jpg', 0.7, 5.2, 33.8, 40.2, 20.1, '0.119163,-0.067315,-0.362223,0.293692,-0.141214,-0.070805,0.999936,0.344578,-0.712546,-0.246162,0.286323,0.824889,-0.439451,0.098957,0.493848,0.070783,-0.355902,-0.543645,0.199056,0.103762,0.278341,-0.609303,-0.107810,-0.250232,-0.174911,-0.861669,0.421910,-0.040911,-0.308149,0.434185,0.112505,0.741575,0.073859,0.367671,-0.058483,0.036824,0.018032,-0.057200,0.001614,-0.234432,0.189701,-0.278189,-0.190309,-0.053864,-0.355709,0.395259,0.479737,-0.140106,-0.051357,-0.217488,0.630547,-0.262219,-0.231685,0.256128,0.240285,-0.152090,0.110241,0.463961,0.102027,-0.141287,0.093708,0.153465,-0.436926,-0.021082,-0.051895,0.356718,-0.235024,0.611232,-0.162457,-0.174891,-0.068464,0.126743,-0.009490,0.085858,0.431181,0.302171,0.004354,-0.028761,-0.449749,0.322185,0.402628,0.180230,-0.769868,0.311055,-0.544473,-0.370037,-0.037873,-0.491034,-0.687393,-0.144951,0.298986,-0.248684,-0.297271,0.765197,-0.577533,-0.020390,-0.187125,0.044080,-0.134436,-0.144553,-0.339613,-0.598067,-0.456139,-0.536539,-0.239652,-0.327262,0.280324,-0.178590,0.474944,-0.678967,0.378410,0.282858,0.019084,-0.634551,0.539300,0.190081,-0.214147,-0.089284,-0.340961,1.002439,-0.071959,-0.164480,-0.137467,0.237229,-0.084764,-0.000109,-0.157631,0.524576', '1298095', '1296992', '3718460', '1293124');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394520', 'B型男友', '喜剧', '夏美（韩智慧 饰）是A型血型，非常胆小，而她非常期待能有一段浪漫的爱情。每天祈祷的她终于在某天遇到了梦中情人。迎彬（李东健 饰）是一名年轻的男孩，面子对他很重要。B型血的他表面上落落大方，实际上他是自私幼稚的。夏美遇到了迎彬一系列浪漫的追求，不顾家人反对的夏美与这位白马王子走到了一起。恋爱一开始是甜蜜的，但时间长了，夏美便发现了自己男友存在的缺点。终于无法忍受，夏美只好忍痛分手。到底迎彬还是意识到自己的问题，便决心改过缺点以能重新得到夏美的欢心。但夏美是个做了决定便不愿回头的人，迎彬将会如何面对固执的夏美呢？©豆瓣', '李东健', '崔锡元', 6.2, 15156, 'tt0452972', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166628738.jpg', 1.8, 12.9, 63.6, 17.9, 3.8, '0.203313,0.064513,-0.674189,0.477576,-0.423040,-0.304016,0.856994,-0.083582,-0.457477,-0.127454,0.131397,0.702908,-0.247899,0.392105,0.170961,0.189519,-0.068315,-0.626702,0.073759,-0.105959,-0.279849,-0.486672,-0.102892,-0.186837,-0.149687,-0.164173,0.556314,0.099318,-0.085383,0.106727,0.649335,0.232401,0.267867,0.727091,-0.223728,-0.040943,-0.067040,0.137351,-0.016504,0.085484,0.184100,-0.244348,-0.181248,0.500299,0.005945,0.325649,0.527584,-0.220340,-0.426620,0.163843,0.551316,-0.364392,-0.111605,0.280533,0.146259,-0.168420,0.066886,0.140205,-0.101792,-0.282291,0.068149,0.028827,-0.806543,-0.114413,0.103507,0.155595,-0.736295,0.376936,-0.015814,-0.181750,0.272899,-0.497123,0.213759,0.081653,0.449571,0.275164,-0.228051,-0.034769,-0.377531,0.177886,0.736417,0.335235,-0.224650,0.740789,-0.554937,-0.481634,-0.108296,-0.228418,-0.497059,-0.053144,0.140080,0.103627,-0.253855,-0.004506,-0.263059,-0.036954,-0.091440,-0.015760,0.027401,-0.540785,-0.022992,0.097523,-0.239769,-0.754971,-0.435896,0.191898,-0.100965,-0.530656,0.961867,-1.036457,-0.116082,0.632403,0.277864,-0.630501,0.633333,0.530018,-0.288515,-0.199704,0.227500,0.318060,-0.391376,-0.222699,0.042127,0.401502,0.031702,-0.114106,-0.470743,0.435437', '1303112', '1389971', '3230462', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394543', '鸳鸯蝴蝶', '剧情', '生活在北京的阿秦（陈坤 饰）来到了杭州，来到了小语（周迅 饰）的咖啡馆。两人交谈之下发觉有很多东西都是跟彼此相似的，两个人心里起了波澜，可是双方都已经有了爱侣。小语因为一次交通意外认识了小佟，成为好朋友后小佟也成为了小语的倾诉对象，可是小佟却一直爱着小语，愿意在她身边付出。阿秦与女友分手，刚好小语到北京找阿秦，她的出现让阿秦惊喜不已，他们也成为了恋人。同居的过程中，他们也看到了对方的缺点，感情经历到考验，小语最后离开北京回到了杭州……©豆瓣', '周迅', '严浩', 7.1, 7746, 'tt0453323', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1417316527.jpg', 4.1, 6.4, 38.5, 33.1, 17.9, '0.263819,0.013897,-1.030425,0.501920,-0.155468,-0.560325,0.805813,-0.039714,-0.545546,-0.196748,-0.081763,0.718166,-0.356059,0.552688,0.191905,-0.109693,-0.103281,-0.887747,0.082133,-0.448293,-0.446438,-0.500908,-0.109809,-0.118480,-0.282585,-0.068998,0.181946,0.086212,-0.140784,0.498064,0.456636,-0.233500,-0.235699,0.810722,-0.206446,0.317676,0.004690,0.340286,-0.448387,0.071802,0.150150,-0.205069,-0.062958,0.023399,0.312526,0.243781,0.632679,0.076114,-0.344215,0.250142,0.023443,-0.180046,-0.074549,-0.062392,0.249204,0.034294,0.411745,-0.052027,-0.135641,0.071442,-0.039950,0.036709,-0.385126,0.389983,-0.024488,0.065734,-0.713396,0.566701,0.053280,-0.173302,-0.046350,-0.590943,0.541437,0.352644,0.411006,0.261928,-0.384887,0.103981,-0.555627,-0.054381,1.030115,0.083747,-0.056774,0.331174,-0.136061,-0.582957,-0.027366,0.117468,-0.123677,0.172871,0.165374,0.096059,-0.193805,0.114221,-0.687219,-0.012010,0.003116,0.004335,0.062932,-0.685385,0.303713,-0.496648,-0.370153,-0.692192,-0.655145,0.385407,-0.059052,-0.588588,0.806223,-1.041993,0.259476,0.354690,0.614543,-0.750574,0.860423,0.171615,0.214001,-0.117826,0.337269,0.308538,-0.244032,0.242662,0.406100,0.298101,-0.300109,0.027310,-0.654916,0.417125', '1301022', '1308755', '2990737', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394626', '寻找周杰伦', '爱情', 'CD里周杰伦一首隐藏的歌令武汉女生蒲蒲（浦蒲）开始一段恋情，却也是在这首歌的陪伴下失恋。来到香港帮欲临盘的姐姐看热带鱼店时，为了寻回失落的爱，蒲蒲决定不惜一切代价寻找对她来说是最遥远也是最明亮的梦的收有这首隐藏的歌的“周杰伦的某张神秘唱片”。找寻唱片的过程中，蒲蒲先后 遇上二手唱片店店主宇仔（余文乐）、水晶店老板Paul（陈奕迅）、书店老板阿祖（吴大维）、时常变换名字的女的士司机和警察（吴彦祖）等等奇形怪状的人，通过他们，她逐渐对爱情哲学有了思考和感悟。©豆瓣', '浦蒲', '林爱华', 5.1, 19318, 'tt0389845', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2376794662.jpg', 14.4, 34.9, 37.8, 8, 4.9, '0.291767,-0.114279,-0.477504,0.709275,-0.027793,-0.079082,0.787135,0.025483,-0.480376,-0.098738,0.290754,0.761004,-0.179116,0.299226,0.146373,0.222305,-0.331138,-0.457286,0.058937,-0.103034,-0.120887,-0.395261,-0.201422,-0.117627,-0.138942,-0.115046,0.596961,0.333936,-0.246701,0.286773,0.287961,-0.095514,-0.176551,0.380331,-0.154908,0.146908,-0.040078,0.089933,-0.194515,0.044020,0.098448,-0.324814,-0.192729,-0.031252,-0.043994,0.302258,0.732893,-0.051517,0.010155,0.175713,0.321040,-0.225887,-0.232102,-0.362983,0.117522,0.206857,0.366347,0.037107,-0.441521,-0.204247,-0.523970,0.043906,-0.830270,0.098157,0.360404,0.196147,-0.451443,0.365963,-0.094042,0.038545,0.451294,-0.320399,0.325697,-0.063816,0.426603,0.335885,0.093865,-0.093885,-0.279244,0.362739,0.496777,0.027119,0.039563,0.714226,-0.315253,-0.440949,-0.217827,0.091313,-0.566094,0.086458,0.137824,-0.014113,-0.076038,-0.226503,-0.724854,-0.094044,0.209754,-0.290915,0.139192,-0.523876,-0.298277,-0.586965,-0.057846,-0.241552,0.077355,-0.086519,0.225720,-0.331531,0.921119,-0.829454,0.143347,0.479032,0.232341,-0.284950,0.809488,-0.120440,-0.119101,-0.333890,-0.238799,0.245815,-0.217464,0.091443,-0.210804,0.298914,0.162300,-0.052981,-0.622119,0.523386', '2053515', '25880986', '27602116', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394825', '11:14', '悬疑', '杰克（亨利•托马斯 Henry Thomas 饰）夜间酒后驾驶，并用手机打电话聊天，却没曾想在穿过立交天桥时，一具尸体从天而降。便利店员达菲（萧恩•哈特西 Shawn Hatosy 饰）因女友雪莉（瑞切尔•蕾•库克 Rachel Leigh Cook 饰）怀孕打胎一事向同事步兹（希拉里•斯万克 Hillary Swank 饰）借钱，假扮便利店被劫。而此前，一群少年从便利店买了过期的甜甜圈，夜晚飙车并向他人投掷甜甜圈取乐。已打算和达菲分手的雪莉不顾父亲弗兰克（帕特里克•斯韦兹 Patrick Swayze 饰）的劝阻，擅自出门与新男友艾伦（布雷克• 海仑Blake Heron 饰）偷欢。所有一切的松散事件，都在11：14分相互交织，互为因果，让结局出人意料，不可思议。©豆瓣', '亨利·托马斯', '格雷格·马克斯', 7.6, 36456, 'tt0331811', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1423752342.jpg', 0.3, 2, 29.3, 52.8, 15.7, '0.300604,-0.221147,-0.401367,0.085041,0.098313,-0.470051,0.752657,0.262801,-0.094428,-0.243907,0.066296,0.397787,-0.374562,-0.164246,0.496829,0.024491,-0.345621,-0.468191,0.379310,-0.074022,-0.177465,-0.476605,-0.122757,-0.162083,-0.011334,-0.132468,0.099541,-0.554319,-0.015485,0.640518,0.494437,0.418820,-0.494098,0.411260,0.065070,0.109260,0.273623,-0.143201,-0.192485,0.141470,-0.008854,-0.201409,-0.137519,0.039709,0.229365,0.320280,0.811067,-0.114748,-0.005754,0.013068,0.109510,0.185679,0.263810,0.117211,0.247026,-0.010284,0.249589,-0.016458,-0.053590,-0.105365,0.373895,0.242498,-0.071554,0.151457,-0.344233,0.105094,-0.448889,0.176516,-0.334648,0.166397,0.374394,-0.477107,0.055806,0.235336,-0.124938,0.372085,-0.033362,-0.208550,-0.388905,0.204021,0.077141,0.290094,-0.070985,0.421468,-0.045188,0.043076,0.181050,0.366250,-0.604186,0.042760,0.465536,-0.142212,0.023459,0.199600,-0.621788,-0.177699,-0.432935,-0.082653,0.165585,0.087798,-0.226464,-0.716161,0.175884,0.054796,-0.119784,0.050178,-0.100968,0.272037,0.078759,-0.480814,0.263806,0.435963,0.277645,-0.245876,0.417541,0.020007,0.123432,-0.135473,-0.057218,0.099649,0.288553,0.290026,0.152249,0.382012,0.265951,-0.092594,-0.448631,0.102449', '10466639', '1394176', '1309194', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1394968', '举起手来！', '喜剧', '我姥姥（刘薇 饰）上学的年代正是闹鬼子的时候，学校里经常有鬼子来抓爱国学生，而被抓走的学生又大多没有回来过。一天，姥姥被鬼子盯上，慌乱之中钻进大木箱被日本鬼子抬上了列车。出站驶入山区时列车遭到游击队员袭击，队长将大木箱子交给一个赶着驴车回村的农夫（郭达 饰），不想就遇到一队 鬼子兵。巧妙地骗过搜查，农夫却被强令带路进入石桥村。进入石桥村，村里老小都加入到解救的队伍中来。不仅如此，村里埋设的地雷、老奶奶喂养的大公鸡、农夫拉车的驴也都让鬼子出尽了洋相、吃尽了苦头，尤其是个“罗圈腿”（潘长江 饰）。经过一天的巧妙周旋，姥姥和农夫配合打回村里的游击队员全歼了鬼子的小分队……©豆瓣', '郭达', '冯小宁', 7.2, 141012, 'tt11070812', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2628450928.jpg', 3.9, 7.2, 33.1, 37.1, 18.7, '0.501705,-0.541772,-0.407799,0.103816,-0.287610,-0.306878,0.574338,-0.210809,-0.384368,0.108684,0.328870,0.213565,0.033624,0.095817,0.068586,-0.122175,-0.164047,-0.258877,0.023206,-0.083341,-0.448449,-0.078627,-0.052198,-0.109484,0.172010,-0.077640,0.223478,0.170686,-0.063661,0.517636,0.019471,-0.077832,-0.084272,0.356250,-0.278404,0.477263,0.100315,-0.362696,0.345570,0.039876,-0.385165,-0.328348,-0.067400,-0.366933,0.279677,0.370780,0.944682,-0.075778,-0.059551,-0.091316,-0.098665,-0.130900,-0.022075,0.126238,0.672774,0.171938,0.123539,-0.003802,-0.003177,0.214670,0.015474,-0.078916,-0.120367,0.342084,0.026841,-0.253834,-0.906467,0.379988,0.294732,0.226838,0.093573,-0.239679,0.431866,0.107956,0.162542,0.460961,0.032172,0.106417,-0.677114,0.132216,0.665734,-0.600085,0.234648,-0.095389,0.074893,-0.008079,0.536016,-0.363277,-0.185569,0.057564,0.446693,-0.480524,-0.521776,-0.142581,-0.559503,0.253891,-0.427692,-0.310985,-0.073001,-0.092817,-0.330805,-0.603915,0.571074,-0.082991,-0.130229,0.663291,0.113822,0.337760,0.650592,-0.232265,0.192709,0.479333,0.355275,-0.159447,0.570352,-0.291696,0.018657,-0.084085,0.081177,-0.159306,0.398450,0.820197,0.481383,0.378538,-0.571887,-0.443473,-0.226148,0.014054', '1466273', '1432825', '21619567', '4009651');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395091', '未麻的部屋', '动画', '当红三人少女偶像团体Charming Bird面临解散，核心成员雾越未麻在事务所的安排下不得不退出团体，转型成为一名电视剧演员。万事开头难，对于偶像歌手转型而来的未麻尤其如此，她在工作中承受着压力，闷闷不乐。与此同时，各种恐吓信不断、经纪人田所先生遇袭以及以自己的口吻在网站上写日记的神秘人都让未麻焦虑不已，恍惚间她甚至看到另一个自己。未麻的苦恼无人知晓，贪婪的田所甚至同意剧组的剧本，要求未麻出演一场尺度极大的强暴戏。这次演出成为未麻演艺事业的转折点，她的出镜率开始攀升，甚至还拍摄了裸露的写真。与此相对，电视剧编剧涩谷和曾给未麻拍下裸照摄影师村野接连遇害。未麻的生活变得混乱不堪，真相究竟如何？本片荣获1997年亚洲奇幻电影节最佳亚洲影片。©豆瓣', '岩男润子', '今敏', 9.1, 297840, 'tt0156887', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1351050722.jpg', 0.2, 0.5, 6.4, 32.1, 60.7, '-0.071951,-0.067252,-0.569251,0.607322,0.413096,0.026285,0.560966,0.192258,-0.320127,-0.442862,0.315993,0.686680,-0.543999,0.271001,0.487407,-0.307568,-0.319915,-0.712734,-0.451964,0.012853,-0.028084,-0.202540,-0.406408,-0.161877,-0.235271,-0.279274,1.000473,0.164821,-0.526398,0.232087,0.551565,0.284447,-0.182373,0.228173,0.184961,0.078210,0.173387,0.100356,-0.353262,0.187829,0.050777,-0.441294,-0.221273,0.097427,0.015334,0.217848,0.615430,-0.033838,-0.274106,0.061138,0.660088,-0.319146,-0.193246,0.109318,0.200390,0.184641,0.454532,0.157699,-0.172259,0.244300,-0.162269,-0.183758,-0.885495,0.114728,0.313805,0.279284,-0.412293,0.023577,-0.144909,0.155393,0.108515,-0.170446,-0.077257,0.344151,0.422263,0.384868,-0.249520,0.282965,-0.202127,0.533041,0.671054,0.369952,-0.219999,0.178894,-0.059876,-0.436747,-0.255991,-0.254494,-0.565641,0.158271,-0.008318,-0.072736,0.121960,0.264459,-0.430003,-0.090898,0.112259,-0.410077,0.022177,-0.276413,-0.197222,-0.904910,-0.228398,-0.001914,-0.068089,-0.173212,0.317125,-0.405565,0.908748,-0.617669,0.238654,0.419454,0.225252,-0.416397,0.423735,0.104200,0.056008,-0.212236,-0.494710,0.048849,-0.058339,0.135291,-0.022657,0.129068,-0.319339,-0.344692,-0.374610,0.337572', '3318306', '1322847', '2369613', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395231', '马粥街残酷史', '剧情', '本来是一名模范生的铉洙（权相佑 饰）来到一所出了名黑暗的学校，对校内的情况十分不满，校内的教师对学生十分不尊重，出口辱骂之余还对学生拳打脚踢。铉洙是校内唯一一名读书的学生，也没有其他朋友。但他不久后却跟一名不良学生金佑植（李正振 饰）成为了好朋友，两个男生更同时喜欢上一 名叫江恩珠的女孩（韩佳人 饰）。铉洙性格内敛，总是羞涩与向恩珠表达爱意，在恋爱方面输给了佑植。随后打击铉洙的事再次发生了，佑植与恩珠都消失在铉洙的生活中，因为一向好胜的佑植与他人决斗的时候败给对方了。这些事情让铉洙性情大变，他变得好斗了，并努力练习双节棍，希望帮好友打败当年的敌人。©豆瓣', '权相宇', '庾河', 8, 31104, 'tt0390205', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2160809781.jpg', 0.3, 2, 23.2, 46.6, 27.8, '0.270530,-0.323082,-0.407572,0.740583,-0.331882,-0.154174,0.625704,0.242423,-0.506636,-0.411172,0.136313,0.876955,-0.363189,0.196047,0.165629,-0.352999,-0.161709,-0.848961,-0.068702,-0.194776,-0.115108,-0.345741,0.333417,0.110771,-0.288953,-0.440949,0.754887,0.062112,-0.382916,0.629243,0.206980,0.433540,0.225948,0.583734,-0.003439,-0.121880,-0.041965,0.325729,0.052903,0.083950,0.065804,-0.205428,-0.345683,0.472994,0.214304,0.410435,0.838388,-0.161960,-0.395960,-0.129340,0.144956,-0.387886,-0.252727,0.076206,0.279287,0.030596,0.423922,0.167138,0.010756,0.299599,-0.215126,-0.089663,-0.668272,-0.161279,-0.043614,-0.152541,-0.333659,0.616697,0.165860,-0.140189,0.081784,-0.252025,0.181709,0.204930,-0.098298,0.231514,-0.362074,0.162311,-0.272129,0.094067,0.837968,0.175096,-0.142918,0.572390,-0.355564,-0.455535,-0.279620,-0.141030,-0.654529,-0.017499,-0.122823,0.013947,-0.004355,0.155070,-0.388447,0.000459,0.019798,0.107448,-0.016217,-0.563495,0.023557,-0.254820,0.098355,-0.368142,-0.390436,0.069436,-0.128556,-0.318471,1.026755,-1.275062,-0.114113,0.113424,0.658416,-0.507576,0.702364,0.223453,-0.160036,-0.327079,-0.404902,-0.036727,0.234478,-0.087866,-0.055763,0.481365,0.160180,-0.453538,-0.214829,0.330876', '35030151', '1292219', '3445516', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395445', '花木兰2', '喜剧', '本片是迪士尼第36部经典动画《花木兰》衍生剧情，当花木兰（温明娜 配音）和李翔准备完婚之际，他们却突然接到一份密旨：为了抵抗强大的匈奴，护送三位公主下嫁和番，维持边疆和平。于是他们立即启程动身，插科打诨的木须龙和蟋蟀当然也一起跟来。但是在途中木兰发现公主们其实不愿外嫁异族，更糟糕的是居然还爱上了别人，这别人正是上次立功而久久被别的女孩拒绝的三个护卫。一向崇尚女子自由意志的木兰，因此决定冒杀头大罪的危险帮助公主逃跑，已经都快到番邦边境，所护驾的公主们却失踪，这样的发展实在超出李翔的意料之外，更出乎意料的是，木须竟然为了自己的权益而挑拨木兰和李翔的关系。在路上，李翔出现意外，为了救木兰而坠下深谷，木兰将会怎么完成自己的任务和拯救自己的心上人呢……©豆瓣', '刘玉玲', '达雷尔·鲁尼', 6.4, 19081, 'tt0279967', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2443063944.jpg', 3.5, 14, 49.5, 23.3, 9.7, '0.273806,0.074235,-0.675630,0.688981,-0.046408,-0.366287,0.373115,0.106332,-0.440730,-0.251114,0.237953,0.669334,-0.018096,-0.027699,0.227935,-0.012741,-0.302743,-0.471609,-0.026967,0.004231,-0.235142,-0.354831,-0.053192,-0.247238,-0.156638,-0.179604,0.679073,0.057778,-0.283689,0.623513,0.391680,-0.024215,-0.243879,0.690188,-0.090949,0.076918,0.011997,0.119174,-0.087883,0.142675,0.151486,-0.291094,-0.244708,0.370115,0.091854,0.386359,0.275076,-0.524409,-0.131724,-0.280544,0.288122,-0.526252,0.113568,0.057937,0.149095,-0.284812,0.412259,0.158934,-0.068015,0.029933,-0.112609,-0.110222,-0.736399,0.218374,0.045836,0.016394,-0.561189,0.057410,0.071448,-0.156869,0.266271,-0.460014,0.179752,0.675032,0.178832,0.188441,-0.615520,-0.226530,-0.564799,0.065615,0.919009,-0.029657,-0.133513,0.053536,0.203179,-0.429150,0.057355,-0.246619,-0.291229,0.138862,0.080936,0.139081,0.076052,0.037382,-0.483773,-0.051783,-0.434855,-0.091408,0.037831,-0.535798,0.074313,-0.436654,0.074940,-0.318038,-0.329416,0.185027,0.479248,-0.228154,0.620283,-0.710215,0.166577,0.412674,0.422270,-1.001993,0.321362,0.292727,0.082898,-0.082125,-0.244940,-0.025146,0.000915,0.318442,-0.001869,0.114426,0.063986,-0.190291,-0.428730,0.348569', '1308206', '25721544', '1295746', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395455', '逃学威凤', '喜剧', '才茵（金善雅 饰）这名女警精明泼辣，因为追查黑帮的任务，让她不得不重新回到校园，做会高中生。阔别校园多年了，才茵的知识面当然跟不上其他人，而且处处保护自己怕被人看穿。班里一名大姐头慧玲（洪秀儿 饰）也看才茵不顺眼，处处为难才茵。碍于自己的卧底身份，才茵只好忍气吞声。让才茵从阻滞中颇感开心的是她对班上一名叫鲁荣（孔俞 饰）有好感了，可是想到自己的真实身份与年龄，才茵的心中感到沮丧。行动好不容易得到了进展，追查对象开始相信才茵，她更取得了重要的线索，但行动又发生了变数。©豆瓣', '金宣儿', '朴光椿', 6.6, 9433, 'tt0456999', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1100537154.jpg', 1.3, 9, 56.2, 25.7, 7.7, '0.156717,0.179544,-0.714037,0.562451,-0.197432,-0.247994,0.337117,-0.168353,-0.453921,-0.306000,-0.020730,0.527665,-0.284612,0.122698,0.001765,0.043135,-0.312325,-0.756108,0.139569,-0.338603,-0.347608,-0.447753,-0.136601,-0.369686,-0.113974,-0.172725,0.330456,0.296726,-0.245358,0.287046,0.521431,0.314998,0.066541,0.718583,0.157455,-0.131991,0.168980,0.201557,0.264777,-0.163151,0.204134,-0.414307,-0.211591,0.637617,0.309900,0.607204,0.662665,-0.020711,-0.689974,0.047642,0.296113,-0.387969,-0.043739,0.005624,0.484579,-0.177691,-0.035269,0.093436,-0.202285,0.061347,-0.257932,-0.005192,-0.815553,0.268218,0.517353,-0.029861,-0.473736,0.066978,-0.098887,-0.364469,-0.141905,-0.274709,0.134400,0.371899,0.463935,0.199441,-0.121188,0.146171,-0.304491,-0.177878,0.626643,0.055883,-0.300992,0.310436,-0.268837,-0.380390,-0.011914,-0.188548,-0.363852,0.167274,0.229817,0.100688,-0.008556,-0.056178,-0.153321,-0.137956,-0.300753,-0.060575,-0.148048,-0.542172,0.129053,-0.114456,-0.186432,-0.519178,-0.518665,-0.024187,-0.007484,-0.540697,0.747237,-0.790601,-0.046628,0.518920,0.260268,-0.965196,0.377584,0.026996,0.007274,-0.355813,-0.057483,0.210743,-0.098824,-0.081853,0.210231,0.239196,-0.119501,-0.588774,-0.007376,0.220410', '35073886', '26678784', '1308206', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395459', '花腰新娘', '爱情', '彝族姑娘凤美（张静初）嫁给舞龙高手阿龙（印小天）的当晚，因破坏古老族规令阿龙很没面子，不久，凤美想方设法混进阿龙的舞龙队当起龙头，因积极改革舞龙模式将阿龙颜面扫尽，而凤美当着自己的面与暗恋她的酒吧小老板阿聪（崔哲铭）“眉来眼去”，则将阿龙的坏情绪推到高潮，忍无可忍之下，他按风俗与凤美退婚，此举令他失去舞龙队姑娘们的尊重。事后，阿龙追悔莫及，为发泄心中郁闷，他于醉酒后跳上屋顶舞起惊人心魄的醉舞龙，众人惊叹不已之际，凤美也重新对他认识。©豆瓣', '张静初', '章家瑞', 6.8, 11444, 'tt0464660', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155369787.jpg', 1.1, 7.5, 51, 32.5, 7.9, '0.186476,0.098783,-0.653598,0.336962,0.115755,-0.182163,0.505875,-0.044997,-0.534191,-0.005347,0.291794,0.440943,-0.423019,0.434603,0.446770,-0.154793,-0.090668,-0.594929,-0.111759,0.195190,0.095520,-0.032988,0.172085,-0.083367,-0.405906,-0.123938,0.292398,-0.094093,-0.327145,0.514857,0.436761,0.310285,-0.051064,0.109102,-0.050670,0.139566,-0.163350,-0.102815,-0.161859,-0.100256,0.038718,-0.358229,-0.194368,0.346669,-0.070027,0.144034,0.520655,-0.228052,-0.308006,-0.299300,0.349639,-0.199301,-0.073346,0.270368,0.152633,0.181885,0.007419,0.092334,-0.237360,-0.039428,0.048433,0.073058,-0.378453,0.229787,0.025350,-0.261567,-0.492689,0.282191,-0.189300,-0.035138,0.176317,-0.220798,-0.008851,0.049585,0.263667,0.133241,-0.292163,0.166686,-0.175085,0.027490,0.733930,0.144203,0.227176,-0.076898,-0.007344,-0.199087,0.277048,-0.073855,-0.054239,-0.149273,0.360153,0.180215,0.089804,0.171667,-0.222295,-0.128288,-0.197090,-0.033473,-0.043769,-0.260334,-0.151175,-0.217530,-0.202247,-0.094004,-0.067811,-0.052799,0.061623,-0.024885,0.527592,-0.512746,0.013881,0.089515,0.343282,-0.370790,0.200078,0.142796,-0.045508,-0.113725,-0.252457,-0.166340,-0.003872,0.190007,0.193142,0.209141,-0.203566,-0.144619,-0.198917,0.302350', '35030151', '1301022', '25721544', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395546', '伯尔尼的奇迹', '剧情', '1954年德国，德国国家足球队在瑞士打入世界杯决赛。德国鲁尔区埃森，人们都聚在理查德·鲁班斯基（彼得·罗美尔 Peter Lohmeyer饰）经营的小酒馆里欣赏电视转播。店主理查德曾在苏联的战俘营被关押了11年，性格保守固执。他的小儿子马蒂亚斯（路易斯·克拉姆罗特 Lo uis Klamroth饰）把德国球员赫尔穆特视为偶像，千方百计想去瑞士为他捧场。与此同时，《南德意志报》的体育记者保罗·阿克尔曼（卢卡斯·格雷戈霍威茨 Lukas Gregorowicz饰）正与未婚妻筹备婚礼，突然接到赴伯尔尼采访的任务，于是将蜜月旅行改在瑞士。7月4日德国队和匈牙利队进行最后决赛的前夜，父亲终于带着儿子前往伯尔尼，感受这场发生在伯尔尼的奇迹。这部触动人心的运动题材电影《伯尔尼的奇迹》，不仅是一部让人热泪盈眶的温暖家庭剧，更是一部见证德国战后重建历史，以足球比赛帮助民族走出创痛、弥合裂痕、重拾自信的动人故事。故事围绕着1954年德国出其不意战胜匈牙利、夺得世界杯冠军的真实事件改编。本片荣获2003年第16届欧洲电影奖最佳摄影提名。', '路易斯·克拉姆罗特', '宋克·沃特曼', 8.1, 7340, 'tt0326429', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151302724.jpg', 0.6, 1.7, 19.4, 48.4, 29.9, '-0.361222,0.036313,-0.513867,0.569242,0.245918,-0.315461,0.138082,0.025185,-0.515980,-0.089135,-0.004765,0.662484,-0.502975,0.114909,0.577631,-0.150218,-0.465207,-0.741649,-0.115425,-0.026911,-0.067186,-0.399049,-0.355318,-0.281689,0.090359,-0.365361,0.655626,0.119202,-0.269292,0.366857,0.273806,0.350155,0.108011,0.136346,-0.110130,-0.028656,0.194234,0.055991,-0.597112,0.317687,0.017328,-0.149786,-0.410436,-0.091298,0.166942,0.069917,0.451524,-0.203982,0.355791,-0.074408,0.517940,-0.245466,-0.128987,0.098366,0.071709,0.152849,0.024801,0.293022,-0.134882,-0.007758,-0.096102,-0.525251,-0.285839,0.111063,0.079384,0.153071,-0.386609,0.578521,-0.445000,0.516213,0.105432,-0.105918,0.068970,0.428469,0.297794,0.357616,0.215425,0.110494,-0.323466,0.416599,0.610290,-0.266254,-0.188940,-0.142333,-0.181918,-0.391651,0.169695,-0.237430,-0.330185,0.256293,0.419064,-0.351496,0.275142,0.379886,-0.506070,-0.045995,-0.205618,-0.435736,0.180486,-0.204281,0.222813,-1.018865,-0.141117,0.026770,0.021241,-0.117052,-0.068768,-0.149867,0.752342,-0.351935,0.332607,0.742172,0.236916,0.029990,0.757927,-0.013650,0.091918,-0.420295,-0.085437,0.598812,-0.110097,-0.054523,-0.155945,0.328454,0.005244,-0.174009,-0.120336,0.519891', '24751811', '30397916', '34961898', '1293656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1395776', '逃出克隆岛', '动作', '林肯（伊万•麦克格雷格 Ewan McGregor饰）和乔丹（斯嘉丽•约翰逊 Scarlett Johansson饰）以为他们生活在一个与世隔绝的社区里。据科学家说，他们是地球最后一批存活的人类。而在他们这个群体里面，将会抽签决定人选，派去一个世外桃源的小岛上面生活。然 而在没选中之前，他们得忍受没有自由、备受监管的生活。当林肯和乔丹“幸运”当选后，他们却发现了一个惊人的秘密——原来所谓的世外桃源岛根本不存在，而他们本身，也只是岛上居民克隆版本；他们前往小岛，迎接来的不是美丽生活，而是掏出他们的鲜活的器官，用以拯救人类。而林肯亲眼目睹了他的朋友，如何在手术刀下被解剖。于是，林肯毅然决定和女友乔丹，踏上逃亡之路……©豆瓣', '伊万·麦克格雷格', '迈克尔·贝', 7.2, 118999, 'tt0399201', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2238267655.jpg', 0.4, 3.8, 40.6, 43.2, 12, '0.272111,0.068339,-0.861636,0.848696,-0.466941,-0.058877,0.885405,-0.016227,-0.566831,-0.194854,0.114983,0.991249,0.048569,0.162982,0.047776,0.026275,-0.380923,-0.457369,0.023860,-0.274468,-0.585992,-0.336452,-0.328989,-0.501335,-0.041445,-0.212732,0.870163,0.162059,-0.038180,0.379520,0.085215,0.268464,-0.109293,0.378833,-0.520846,-0.056850,0.173985,0.251119,-0.336771,0.408723,-0.259378,-0.070522,-0.056608,0.458091,0.077838,0.371737,0.661281,-0.472604,-0.071765,-0.224249,-0.081165,-0.483038,-0.021821,0.042733,0.334715,-0.273703,0.176824,0.223845,-0.067648,0.041876,0.062124,-0.228516,-0.853398,-0.039560,-0.005055,0.172556,-0.535898,0.465625,-0.115989,-0.264467,-0.152900,-0.401428,0.388098,0.398258,0.361565,0.284152,-0.027595,-0.190052,-0.706917,0.246511,0.909474,-0.102957,-0.437592,0.456193,-0.264621,-0.511210,-0.027739,-0.233783,-0.557914,-0.012214,0.254542,-0.017004,-0.331859,-0.104605,-0.694042,0.280472,-0.147863,-0.264603,0.024662,-0.621335,-0.139739,-0.751275,0.146226,-0.351438,-0.214360,-0.042461,-0.052096,-0.270180,0.782343,-0.819584,0.209089,0.510801,0.287214,-0.766600,0.869473,0.029860,0.183178,-0.211841,0.117751,0.275701,0.161536,0.563924,0.025508,0.219842,-0.046459,-0.152374,-0.500590,0.559272', '3055049', '25721544', '1456503', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1396313', '恋爱地图', '爱情', '东京尧远（陈柏林饰）从台湾来到东京深造，梦想是成为电脑动画师。但是苦于没有灵感，创作枯燥。一天在大街上偶遇一个浑身散发着哀戚气息的女子，尧远对她一见倾心。女子是年轻的画家美智子，最近正在遭逢失恋的痛楚。而因为爱情的感染，尧远重新激发了创作的欲望，为美智子画下一张张画……台北阿苏（范晓萱饰）彻夜不眠，组装书架。厚重的零件让她招架不来，便找来好友阿铁。阿铁第一次来台北，不懂中文。本以为可以发展一夜情的他看见只是干粗活，不过善良的他也痛快地帮起忙来。天亮了，阿苏请求他去跟前男友传个信，可是等来的回复从一句中文也不懂的阿铁嘴里说出来，已经支离破碎。阿苏哭了。坐在阿铁的摩托车背后穿越长长的隧道时，她紧紧抱住了他。上海云（李小璐饰）是一个爱打瞌睡的女孩子，和母亲相依为命。自从日本美少年修平来到上海并租了他们家一间房间后，云的感情就起了变化。她开始关注他，可是他对日本的恋人还念念不忘……', '陈柏霖', '下山天', 7.3, 36897, 'tt0456821', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321271784.jpg', 0.5, 4.2, 38.4, 43.3, 13.6, '0.177786,0.074347,-0.657452,0.513615,-0.219565,-0.401440,0.872565,-0.016369,-0.289058,-0.052904,0.066902,0.650213,-0.140693,0.464615,0.002639,0.399743,-0.244138,-0.629212,0.044325,-0.148081,-0.270122,-0.350427,0.028212,-0.094704,-0.123458,-0.048672,0.214034,0.086605,-0.193087,0.412394,0.245315,-0.085673,-0.016529,0.678418,-0.299038,0.029617,-0.235137,0.182690,0.165583,0.034630,0.196665,-0.406587,-0.171371,0.242211,0.044894,0.210750,0.563124,0.051222,0.080152,0.066672,0.255320,-0.000162,0.015020,0.030020,0.202947,0.099464,0.118272,-0.102688,-0.173692,-0.031217,-0.048298,-0.129649,-0.429064,0.142888,-0.105482,0.218418,-0.593686,0.451335,-0.292549,-0.183789,0.030819,-0.470103,0.124525,0.200556,0.077725,0.438034,-0.146034,0.309531,-0.490581,0.281346,0.416870,-0.024532,-0.087923,0.600235,-0.111658,-0.318483,-0.043832,0.037122,-0.400497,-0.150888,0.023244,-0.145434,-0.259183,-0.337328,-0.423786,0.015001,-0.073675,-0.040917,0.011099,-0.242392,-0.085584,-0.344754,-0.127273,-0.312945,-0.177390,0.063811,0.135564,-0.158721,0.658440,-0.583876,0.140616,0.609876,0.278429,-0.367121,0.642083,0.102060,-0.228948,-0.055632,0.171532,0.274706,-0.124427,0.384227,0.320768,0.444497,0.106740,0.031804,-0.346103,0.438748', '1783772', '1309172', '2375763', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1397546', '追随', '悬疑', '比尔（杰里米•希尔伯德 Jeremy Theobald 饰）是个游手好闲的作家，借跟踪陌生人打发时间。这让他体验到形形色色的人生，很神秘，也很刺激。不过，有一次，比尔盯上了一个西服革履的家伙克布（艾利克斯•浩尔 Alex Haw 饰）。尾随到餐厅之后，他却被对方识破，只得摊牌。克布是个贩卖盗版光碟的商贩，此外还做拧门撬锁的勾当。克布带着比尔潜入了陌生人家中，但比尔发现克布根本不取财物，而是寻找主人蓄意掩盖的隐私。同时，克布还提醒比尔要注意仪表。后来，比尔认识了一个神秘的金发女人（露西•拉塞尔 Lucy Russell 饰）。在酒吧，比尔主动与她调情，但是对方冷若冰霜。原来她是黑社会大佬的女人，但是不可遏制的激情让比尔失去了理智，从而堕入了万劫不复的深渊……©豆瓣', '杰里米·西奥伯德', '克里斯托弗·诺兰', 8.9, 171434, 'tt0154506', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561545031.jpg', 0.2, 0.5, 7, 37.3, 55, '0.481621,-0.117896,-0.458472,0.512158,-0.437867,-0.435124,0.783029,0.178251,-0.486108,-0.242620,0.089552,0.548355,-0.215312,0.089500,0.228382,0.274902,-0.309857,-0.574715,0.234276,-0.214915,-0.219769,-0.273391,-0.254820,-0.336629,-0.172437,-0.234754,0.291976,0.019279,-0.284650,0.131883,0.253893,0.160878,0.101739,0.657288,-0.032246,0.010261,0.212263,-0.269691,0.067734,0.231294,0.052966,-0.111030,-0.208872,0.435473,-0.099815,0.612002,0.368282,-0.279451,-0.018623,0.114369,0.277450,-0.301055,0.015461,0.111729,0.242160,-0.323988,-0.060803,0.114605,-0.282077,0.069363,0.211575,0.166202,-0.571819,0.131321,0.017515,0.255312,-0.483074,0.275674,-0.041621,0.053148,-0.079065,-0.155341,-0.011319,0.084384,0.306589,0.080630,0.193434,-0.153670,-0.670127,0.017665,0.323291,0.041551,-0.189688,0.439407,-0.186860,-0.338785,0.041452,-0.233007,-0.423737,-0.158828,0.319748,0.002135,-0.263284,0.176816,-0.612106,-0.149369,-0.286775,0.114516,-0.234272,-0.484001,-0.183445,-0.700478,-0.295203,-0.334706,-0.302516,0.114840,0.054673,-0.164958,0.363686,-0.638993,-0.044318,0.977617,0.156324,-0.380053,0.686852,-0.050579,-0.283334,-0.083009,-0.172684,0.245731,0.544841,0.133413,0.090209,0.434659,0.103478,-0.357501,-0.042999,0.431646', '1947080', '6875451', '3326747', '1509868');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1397550', '我是你爸爸', '剧情', '独自抚养儿子长大的马林生（冯小刚 饰）是某机关的工会主席，他装腔作势，自命清高，在家中也趾高气扬，他在儿子马车面前摆足了父亲的谱儿。但是这一切除了让他自我感觉良好外，没有起到任何实质作用。令行禁止的家教无法让儿子臣服，马车始终与之背道而驰。在学校里，他顶撞老师，挤兑同学，三番五次被请家长，马林生因此生头疼不已。在一次失败的暴力家教过后，他想尽办法和儿子搞好关系，然而他也痛苦地认识到：父子之间的鸿沟越来越深……本片由王朔根据自己早年小说《我是你爸爸》改编，并荣获2000年瑞士洛迦诺国际电影节最佳影片奖、青年评委会奖、堂吉诃德将特别提及。©豆瓣', '冯小刚', '王朔', 7.8, 26746, 'tt0256630', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220667165.jpg', 0.5, 2, 25, 50.8, 21.8, '0.020409,-0.151453,-0.825676,0.813107,-0.272204,-0.286786,0.472771,0.082720,-0.806355,-0.105888,0.068625,0.847285,-0.166203,0.176788,-0.057215,-0.269382,-0.136799,-0.649980,-0.089513,-0.062280,0.003176,-0.601178,0.008085,-0.132865,-0.348716,-0.260696,0.670759,-0.199413,-0.109402,0.380139,0.358290,-0.038537,0.024529,0.372218,-0.278090,0.182649,0.034016,0.089548,-0.295521,0.052922,0.365457,-0.222896,-0.284936,0.323521,0.221629,0.257929,0.485739,-0.136624,-0.321043,-0.087435,0.530996,-0.289499,-0.036522,0.159335,0.281401,-0.144672,0.255512,0.415015,0.004123,0.045290,0.023826,-0.066322,-0.457781,0.015348,0.044936,-0.061828,-0.691595,0.654156,-0.052054,-0.238009,-0.049059,-0.293458,0.228834,0.101763,0.120431,0.248092,-0.389564,0.040922,-0.390226,0.225994,0.555278,0.055020,-0.290725,0.231317,-0.331467,-0.327742,0.196865,-0.542421,-0.556681,0.063950,0.153558,0.072132,-0.316783,0.062884,-0.177618,0.066939,-0.052395,0.038868,-0.065780,-0.622189,0.158067,-0.305293,-0.063173,-0.423126,-0.301843,-0.082297,0.014829,-0.394695,0.565961,-0.759347,0.231303,0.397510,0.496448,-0.395030,0.744599,0.330426,0.101155,-0.049642,-0.238656,-0.053659,0.011502,0.226393,0.138832,0.249421,0.145080,-0.120202,-0.218597,0.322209', '35030151', '1456503', '25907086', '1307922');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400240', '去年在马里昂巴德', '剧情', '本片用一种现实与记忆穿插的方式勾勒了男主人公X（吉奥吉欧·艾伯塔基 Giorgio Albertazzi 饰）与女主人公A（德菲因·塞里格 Delphine Seyrig 饰）公剪不断理还乱的情感纠葛。X的记忆中对于巴洛克宫殿里的亭台楼阁如数家珍，在他的描述性旁白中，人们 得以感受到他内心巨大的波澜。在剧场舞台上，戏子正在表演着离愁别绪的桥段。观众席上X跟贵妇A对视良久。歇息之时，剧场响起舞曲，X向A邀舞，两人在近距离表达了对彼此的感受。A觉得这个X是个关注自己的陌生人，但是X却讲述了去年与她发生的一段鲜为人知的故事。期间，还穿插了X跟A丈夫M（莎查•皮托夫 Sacha Pitoëff 饰）游戏对决的场景……©豆瓣', '德菲因·塞里格', '阿伦·雷乃', 8.3, 20268, 'tt0054632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2186651056.jpg', 1, 2.5, 16.4, 41.6, 38.4, '0.473239,0.066416,-0.599063,0.790574,0.249397,0.007092,1.131419,0.034675,-0.601340,0.000213,0.178191,0.682200,-0.787506,0.164573,0.435193,-0.017001,-0.422222,-1.029806,-0.040634,0.109558,0.015427,-0.418988,-0.258112,-0.059676,-0.205745,-0.459861,0.470119,-0.010825,-0.467302,0.451579,0.155090,0.159681,-0.498804,0.390029,0.030788,-0.021134,-0.036927,0.265798,-0.148795,-0.238317,0.030460,-0.574150,-0.273893,0.084751,-0.188575,0.355377,1.059299,-0.406744,0.037714,0.404951,0.256162,0.135195,-0.036216,0.287942,-0.053667,0.064468,0.253086,0.206379,0.077617,-0.144960,-0.091618,-0.029129,-0.523392,-0.148401,-0.019083,0.558994,-0.289594,0.669788,-0.019768,-0.130227,0.176723,-0.101168,0.217341,-0.176502,0.331617,0.513901,-0.347339,-0.355897,-0.226565,0.313713,0.447281,0.268122,-0.378020,0.634234,-0.389863,-0.581585,-0.499541,0.168928,-0.565332,-0.317932,0.136429,0.208693,-0.278842,0.234709,-0.771284,0.089311,0.087778,-0.381679,0.065439,-0.590302,-0.122217,-0.847252,-0.503646,-0.680846,-0.340065,-0.024675,0.152809,-0.191778,0.604732,-0.732546,0.151317,0.553851,-0.009914,0.082993,0.817640,-0.011020,0.023137,-0.024566,-0.051537,0.055389,-0.231949,0.027378,0.136975,0.570732,-0.315561,-0.060236,-0.787781,0.570289', '1467779', '24839498', '10466639', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400665', '济公', '喜剧', '天上降龙罗汉（周星驰）与众仙打赌，称在凡间会令三名凡人于一定时限内为他人作出牺牲，否则他愿再受轮回之苦。伏虎罗汉化身和尚济公来到人间，边游戏人间边普渡为生的间隙，他选中被老天所罚的九世乞丐（黄秋生）、遭男人欺女人辱的妓女（张曼玉）、杀人如麻的大盗（黄志强）为实验品。凭 借鬼马机智巧妙安排一番后，济公与三人建立了良好的关系，而最终，九世乞丐与大盗被济公感化作出为他人牺牲之举，妓女更是一往情深爱上他，令他开始为是否自动放弃神仙身份留在凡间而烦恼。©豆瓣', '周星驰', '杜琪峰', 7.5, 138522, 'tt0106538', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2878698596.jpg', 0.5, 3.5, 34.4, 42.1, 19.6, '-0.125604,0.049037,-0.312223,0.339456,-0.375030,-0.202549,0.298177,0.103337,-0.369338,-0.011414,0.232730,0.728592,-0.066293,0.028306,0.214606,-0.150630,0.045894,-0.683328,-0.070258,-0.057561,0.024368,-0.193564,0.052775,-0.242876,-0.486570,-0.270470,0.593592,-0.038686,-0.027094,-0.201851,0.466552,0.300738,-0.162552,0.119828,-0.225476,0.033851,-0.288723,0.053282,-0.420814,0.394376,-0.170407,-0.419194,-0.052432,-0.145421,-0.704052,0.067064,0.550772,-0.585299,-0.472071,-0.698025,0.356536,-0.269686,0.018984,0.187142,-0.104063,-0.007184,0.313456,0.501695,0.134080,-0.009895,0.467695,-0.175362,-0.443933,-0.073126,0.239970,-0.287577,-0.345445,0.282323,-0.133993,0.111756,0.086519,-0.283030,-0.028249,-0.042237,0.699510,0.250093,-0.246621,-0.274043,-0.290731,0.255566,0.554715,0.224865,0.063104,0.202091,0.237283,-0.259468,0.260350,-0.410480,-0.226869,0.078756,0.055684,-0.079399,0.220611,0.431524,-0.330108,-0.327332,-0.398584,0.452876,-0.070767,-0.298776,-0.056792,-0.335534,0.100265,0.082016,-0.044552,-0.050513,0.541107,-0.469141,0.482438,-0.626680,0.355294,0.390773,0.125823,-0.756821,0.752089,-0.074329,0.312590,-0.195038,-0.184349,0.428210,0.215678,0.512752,0.083386,-0.264789,-0.125397,0.305465,0.025871,-0.120988', '30345227', '1295469', '4301278', '4723944');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400666', '最佳女婿', '喜剧', '美发师纪阿开（张学友）、服装设计师大眼龙（莫少聪）和风水师赖布丁（周星驰）三个死党合伙开了一家新潮美发店，不料开业当天就与隔壁理发店老板发生争执，幸得店老板女儿亚英（张敏）及时出手风波平息，过程中，三人皆被亚英魅力吸引，为赢其芳心，开始频频登其家门献殷勤。某次晚餐聚会后，三人烂醉与亚英误睡一室，导致亚英怀孕，为与亚英一起生活，三人争先恐后将准父亲一职往自己身上揽，又因三人血型相同，医院也无法验出谁在冒名，亚英父母决定先考察三人表现，为争当最佳女婿，三人使尽浑身解数展开激烈角逐。©豆瓣', '张学友', '黄华麒', 6.7, 26469, 'tt0121922', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2179237032.jpg', 1.5, 9.5, 54.1, 24.3, 10.6, '0.039486,-0.073149,-0.463446,0.146526,0.099430,-0.245128,0.213705,0.380424,-0.436338,-0.266415,0.040894,0.705698,-0.453646,0.349132,0.473865,-0.330638,-0.252610,-0.759638,-0.049003,0.397330,-0.149090,-0.083968,0.376616,-0.093171,-0.231804,0.151036,0.212721,-0.143497,0.051450,0.572029,0.483532,0.064970,-0.591897,0.222005,0.083163,-0.002835,0.117771,0.046550,-0.701924,0.511907,0.006386,-0.307020,-0.274350,-0.046378,0.179629,0.063448,0.645496,0.288244,-0.148524,-0.246299,0.205438,0.128832,-0.025074,0.316859,0.352865,0.046327,0.582747,0.068669,-0.107762,0.086150,0.023821,0.129441,-0.314001,0.250723,0.230814,-0.481578,-0.447520,0.127338,-0.058116,-0.084235,0.124743,-0.178017,0.170941,0.249643,0.127819,0.174111,-0.059751,0.136919,-0.262540,-0.011878,0.559844,-0.058315,0.400329,0.281127,0.157933,-0.195390,0.273144,-0.142530,-0.190547,0.159791,0.196168,0.354173,0.062042,-0.055716,-0.321576,-0.253345,-0.251222,-0.167212,0.276250,-0.097425,0.119469,-0.713297,-0.235992,0.025175,-0.048323,0.013171,0.229068,0.058380,0.224277,-0.542619,-0.031131,-0.007376,0.074945,-0.561527,0.616324,0.048512,0.448606,-0.282224,-0.074518,-0.442555,0.139806,0.061771,0.115711,0.324283,-0.169212,0.125717,-0.315417,-0.128765', '1303333', '1292050', '1296978', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400667', '小偷阿星', '剧情', '阿龙（陈观泰 饰）是警方是卧底，但因为身份被曝露而被打伤，身受重伤导致失去记忆。但在他手上五千多万的公款不翼而飞了。此时他正受到黑帮的追杀，又使警方怀疑他私吞了公款而被通缉，两面受困。阿星（周星驰 饰）是一名小偷，在一次偷窃中被阿龙搞砸了，两人就此结识了。失去记忆的阿龙误以为阿星是自己的亲人，终日都要跟随在阿星的身边。阿星希望尽力帮助阿龙恢复记忆，让他想起五千万巨款的下落。终于，他们遇到了探长（曾江 饰），当探长把他们带到一个仓库中的时候，阿龙突然想起来了一切……©豆瓣', '周星驰', '楚原', 6.6, 16591, 'tt0100970', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2423249292.jpg', 1.9, 11.9, 53.7, 21.2, 11.3, '0.222594,0.098028,-0.597163,0.262816,-0.336198,-0.424909,0.863713,-0.097818,-0.721361,-0.261949,0.209950,0.821709,0.037855,0.223957,0.040115,0.099347,-0.021432,-0.870194,-0.098404,-0.145401,-0.379026,-0.446429,-0.208125,0.112700,-0.381530,-0.337831,0.560302,0.162661,-0.360660,0.488629,0.374437,0.381218,-0.036947,0.503156,-0.217215,0.297000,0.195908,-0.260864,-0.000956,0.389767,0.220240,-0.686933,0.051511,0.598100,-0.082052,0.344483,0.738936,0.106669,-0.298066,-0.003071,0.176302,-0.582269,-0.080059,0.084906,0.431279,0.209656,0.252790,0.082395,-0.517837,-0.128621,0.392794,0.164255,-0.905187,0.024040,0.079237,0.195565,-0.817395,0.207974,-0.217562,0.128939,0.036999,-0.212567,0.547232,0.311762,0.340664,0.057639,-0.245687,-0.345747,-0.835905,0.091110,0.872402,-0.356466,0.062481,0.290788,0.017957,-0.130738,-0.035141,-0.137198,-0.203729,0.165339,0.513405,-0.018846,-0.431264,0.106375,-0.377208,-0.076803,-0.405805,-0.206978,-0.505821,-0.309150,-0.036036,-0.206389,-0.510681,-0.260615,-0.368665,0.099402,-0.039688,-0.382136,0.418604,-0.849038,0.357009,0.686232,0.284225,-0.562725,0.461086,0.043673,0.083077,-0.016569,0.192687,-0.195594,0.461223,0.247838,0.517980,-0.052777,-0.114026,-0.315478,-0.374877,0.244866', '1292584', '1305386', '1301022', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400668', '无敌幸运星', '喜剧', '富商巢老爷临终立下遗嘱，将所有遗产都传给远在法国的女儿飞飞（吴君如 饰），遗嘱由巢二爷保管。巢老爷的不肖子秋千方百计想修改遗嘱，而二爷的不肖子大傻亦想取得遗嘱私自修改。一晚，幸运星（周星驰 饰）到巢家偷窃时被大傻抓住，见他偷窃有一手，大傻命令幸运星帮助自己偷遗嘱。而阿秋 亦无意中发现在垃圾场专门捡垃圾的垃圾凤（吴君如 饰）样貌竟然和他妹妹飞飞一模一样，于是命令阿凤假扮其妹骗取二爷掌管的遗产。就在二爷去迎接从法国回来的假飞飞（阿凤）的晚上，幸运星按大傻吩咐潜到了巢家大宅去偷遗嘱。不料事情败露，被二爷抓个正着。情急之下，幸运星谎称自己是飞飞多年前的男友，企图蒙混过关。而不知就里的阿凤怕露出马脚，也承认了幸运星是她的男友。于是一场笑料百出的遗产争夺战开始了。©豆瓣', '周星驰', '陈友', 7.2, 63140, 'tt0100959', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p973618186.jpg', 0.5, 4.5, 44.9, 34.5, 15.6, '0.114543,0.169349,-0.573962,0.208778,-0.382091,-0.494073,0.170035,0.199313,-0.264262,-0.082590,0.303315,0.745467,-0.022671,0.060113,-0.029253,0.453326,-0.086417,-0.384996,-0.186223,-0.054353,-0.090451,-0.592621,0.089269,-0.035805,0.046074,-0.190236,-0.004274,-0.338771,-0.134036,0.117184,0.462926,-0.159378,-0.304391,-0.045141,-0.286532,0.314943,-0.049168,0.130171,-0.186494,0.106087,0.125386,-0.258481,-0.212603,-0.108087,0.212731,0.255133,0.448511,-0.267173,-0.164506,0.041818,0.411880,-0.260536,0.024106,0.224101,0.328729,0.117326,0.040974,0.267671,-0.408480,0.020659,0.309782,0.000269,-0.491113,0.109243,0.021650,0.009295,-0.491831,0.307620,-0.239283,0.143890,0.152089,-0.527339,0.384339,0.159657,-0.091281,0.088802,-0.332198,0.107550,-0.569717,0.340013,0.083321,-0.336528,0.340844,0.146149,0.559102,-0.054041,0.417544,-0.240707,-0.312415,0.139278,0.504627,-0.142114,-0.276838,0.072398,-0.443249,-0.210838,-0.518235,0.019824,0.040383,-0.303581,-0.393714,-0.011042,-0.189421,0.161606,-0.117808,0.081498,0.300187,-0.201529,0.559890,-0.360360,0.361916,0.469755,0.169852,-0.649879,0.367727,0.102856,-0.062626,-0.055528,-0.006010,-0.307488,0.324290,0.392899,0.274896,0.003505,0.110101,-0.503435,-0.321328,0.052698', '1309069', '5973984', '1300857', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400673', '漫画威龙', '喜剧', '本片是《新精武门》的续集。牛皮（陈百祥 饰）为刘晶（周星驰 饰）在擂台上的英姿折服，自此苦缠拜师，却引起小敏（张敏 饰）对刘晶误会。刘晶获得的巨额奖金被师父们全部输光，更卷入了潇洒（钟镇涛 饰）与一女孩的纠葛，小敏对他的误会也日益加深，刘晶运气一时衰到了极点。阿威之大哥横刀（元华 饰）为替弟报仇，将刘晶的神力右手打残，幸有牛皮之姑牛牡丹（萧芳芳 饰）危急关头蒙面救走刘晶。于是刘晶在牛家休养，邂逅和小敏相貌一样的牛皮表妹——婉君（张敏 饰），不久横刀找上门来，将牛皮与婉君掳走，牛牡丹为保住牛家血脉，只得将牛家祖传的“电角神拳”传授于刘晶……©豆瓣', '周星驰', '左颂升', 7.1, 27726, 'tt0102386', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2545699410.jpg', 0.7, 5.6, 47.4, 31.5, 14.7, '-0.123472,-0.069638,-0.259425,0.369880,-0.221143,-0.402294,0.523566,0.243419,-0.249630,-0.114291,0.359800,0.660771,-0.249103,-0.025514,0.132687,-0.014322,0.306539,-0.691800,0.086424,0.145707,-0.174477,-0.213402,-0.028056,0.279629,-0.239355,-0.323837,0.394526,-0.144438,-0.352410,0.641034,0.492239,0.091228,-0.010318,0.171677,-0.200246,0.282880,-0.330651,0.083620,-0.259779,0.101628,-0.051779,-0.250531,-0.035451,0.159076,-0.106999,0.052253,0.756784,0.009857,0.048913,-0.230183,0.274373,-0.159665,-0.007238,0.049293,0.083404,0.205745,0.144171,0.265864,-0.451938,0.155177,0.431829,0.004506,-0.449576,0.213747,0.227429,-0.026697,-0.654515,0.311835,-0.225054,-0.187498,0.015865,-0.318246,0.029143,0.033422,0.207768,0.197898,-0.250286,-0.089107,-0.374603,0.189800,0.252492,-0.226893,0.427407,0.190603,0.070156,-0.083100,0.109646,0.037793,-0.195834,-0.137775,0.525080,-0.072519,0.224307,-0.041271,-0.501284,-0.269548,-0.206090,0.100977,-0.093937,-0.400947,0.027122,-0.226929,-0.263052,-0.381823,-0.290201,-0.169706,0.227567,-0.291412,0.694502,-0.319526,0.049266,0.119342,0.249293,-0.469024,0.357428,0.156796,0.194153,-0.044273,-0.160556,-0.088145,0.099527,0.174440,0.296362,0.303750,-0.046568,-0.364498,-0.206072,0.216864', '1307146', '3811356', '3155839', '3262050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400829', '我的舅舅', '喜剧', '于洛先生（雅克·塔蒂 Jacques Tati 饰）从乡下来，到了巴黎的姐姐（阿德里安娜·色万提 Adrienne Servantie 饰）家里小住，对姐姐家中各种现代化设备极其不适应，经常被搞得手忙脚乱。还好小侄子杰拉德喜欢这个舅舅，和他到处去玩，杰拉德同样不喜欢家里的现代化设备，因此于洛还带他去郊区老屋玩耍。于洛的姐夫阿尔贝勒先生（让·皮埃尔·佐拉 Jean-Pierre Zola 饰）帮于洛在自己工厂找了一份工作，可是于洛同样不适应现代化的操作机器，搞砸了许多事情，闹了许多笑话，姐夫对他忍无可忍，决定介绍另一份工作打发他离开，而于洛开心地同小侄子话别，只当结束了一个不同寻常的假期……本片是雅克·塔蒂“于洛先生三部曲”的第二部。©豆瓣', '让·皮埃尔·佐拉', '雅克·塔蒂', 8.6, 16008, 'tt0050706', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p685838678.jpg', 0.3, 1.1, 11.3, 44, 43.3, '0.199449,-0.250901,-0.550808,0.350014,-0.145735,-0.202405,0.465481,0.020721,-0.322285,-0.551278,-0.324059,0.624282,-0.082752,0.315057,0.236011,0.212193,-0.469074,-0.012222,0.233710,0.091282,-0.250709,-0.649838,-0.001457,-0.436281,-0.112857,-0.008689,-0.054122,0.015734,-0.102577,0.234002,0.181198,-0.026487,0.071641,0.556837,-0.289548,0.180757,0.004456,-0.100963,-0.071347,0.078242,0.294619,0.064984,-0.167998,0.039539,0.709248,0.128086,0.651251,0.112458,-0.036362,0.058977,0.361347,-0.145331,0.322754,-0.019122,-0.034073,-0.151023,0.133820,-0.070158,-0.342503,0.109870,0.124593,-0.455534,-0.228672,0.431323,0.121637,-0.119872,-0.668772,0.419443,-0.307348,0.023565,-0.159746,-0.401524,0.388095,0.253717,-0.031604,0.359559,0.129263,0.193450,-0.471688,0.096916,0.469866,0.100144,0.241680,0.495909,-0.111959,-0.191728,0.069033,-0.080414,-0.438291,-0.109419,0.095706,-0.437602,-0.002519,-0.031177,-0.381748,-0.244188,-0.107977,-0.236150,-0.023647,-0.571744,0.054849,-0.428078,0.138984,-0.450243,0.004856,0.094676,0.107616,-0.174714,0.482454,-0.543148,-0.034511,0.293145,0.217341,-0.527947,0.513557,0.073919,0.200750,-0.336793,0.096266,-0.104326,0.126784,0.056335,0.484180,0.523584,0.349087,-0.224104,-0.260896,0.220078', '1292337', '1299965', '1302384', '1301221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400868', '警察故事', '喜剧', '受过特警训练的警察陈家驹（成龙）为人正直办案拼命，时常将女友（张曼玉）忽略。某次围剿行动中陈家驹拘捕了大毒枭朱滔，但因证人（朱滔的秘书）莎莲娜（林青霞）的突然失踪，未能将其绳之于法，陈家驹因此受降职处分。事后含恨在心的朱滔为了报复陈家驹，设计将其诱至囚禁莎莲娜的别墅，并派手下杀死一名警察嫁祸其身，令陈家驹在警方的通辑令下只能四处流亡。而侥幸逃脱的莎莲娜明白到朱滔为人不择手段的本质，为求自保，冒险潜入朱滔办公室偷得证据，却被其手下追杀至商场，陈家驹及时赶到，与朱滔手下展开激战。©豆瓣', '成龙', '成龙', 8.1, 105283, 'tt0089374', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1748521747.jpg', 0.2, 0.8, 19.6, 52.8, 26.5, '0.234836,-0.073411,-0.484089,0.420539,-0.137660,0.044046,0.298927,-0.013396,-0.666915,-0.449765,0.645759,0.423355,0.208703,-0.022427,0.373892,-0.149683,-0.311536,-0.688759,-0.061483,-0.088484,-0.122729,-0.381273,0.069775,-0.025069,-0.083859,-0.001860,0.512946,0.001386,-0.149817,0.635275,0.314526,0.312306,-0.500983,0.406167,0.257558,0.331469,-0.036522,-0.390860,-0.323980,0.173288,-0.078087,-0.305969,-0.416465,0.177015,0.093219,0.455180,0.687682,-0.262370,-0.246064,-0.287325,-0.021295,-0.551579,0.260877,-0.012000,0.389027,0.102921,0.172571,0.435684,-0.310452,-0.007562,-0.030353,0.013483,-0.571282,0.144685,0.310652,-0.186231,-0.218426,-0.103344,-0.275306,0.254692,-0.197702,-0.041404,0.003246,0.395115,-0.122459,0.190715,-0.077872,0.220010,-0.770390,-0.026686,0.401904,-0.452717,0.024458,-0.362850,0.097710,-0.039758,0.235459,-0.350819,-0.110694,-0.101310,0.675464,0.025994,-0.285057,0.215400,-0.086406,-0.250864,-0.820101,0.173694,-0.175390,-0.159236,-0.019282,-0.544770,0.125507,0.185336,-0.164371,-0.014837,0.056375,-0.121985,0.226467,-0.727116,-0.220998,0.525100,0.525711,-0.687901,0.065244,-0.090854,0.241149,-0.110899,-0.380458,0.184516,0.916409,0.297827,0.308794,-0.006063,-0.316267,-0.313693,-0.268756,-0.096917', '27046740', '1292633', '1299335', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1400869', '少林木人巷', '动作', '少林哑徒弟（成龙 饰）为了报杀父之仇而学武，从挑水砍柴做起，苦熬内功基础，打出木人巷学成武功的情形时时出现在他的梦中，父亲被害的惨状和客居少林的五枚师太的开解令他在疲乏时咬紧牙关坚持。哑徒弟在少林禁地发现了被锁住的老怪人法愚，法愚不似少林僧人，但有感于哑徒弟的照顾，法愚指点尚不具备学习少林武术资格的哑徒弟武功，期间哑徒弟师兄闯入木人巷却实力不济铩羽而归。五枚师太见独自温习武功的哑徒弟出招狠辣，随传授蛇翼八步调理其心性，经法愚调教，哑徒弟成功打出木人巷，得以学成下山，法愚令其携带信物联络江湖帮派，引发江湖搏杀，而哑徒弟又发现了法愚的真实身份……©豆瓣', '成龙', '陈志华', 6.5, 3646, 'tt0075201', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2156818458.jpg', 1.4, 8.6, 61.5, 20.3, 8.2, '-0.512564,-0.014779,-0.437920,0.657347,-0.406719,-0.299137,0.121617,0.020018,-0.472253,-0.695083,0.339770,0.664621,0.164068,0.000406,0.020118,-0.453002,0.673314,-0.422010,0.160810,-0.018369,0.017343,-0.294737,0.101888,-0.024647,-0.362792,-0.872384,0.343445,0.179127,-0.530847,0.270371,0.265573,-0.172098,-0.150999,-0.018361,-0.178651,-0.086101,-0.019512,0.064151,-0.055664,-0.130947,0.134273,-0.302050,-0.134598,-0.398918,-0.281584,0.497891,0.348601,0.304642,-0.132728,-0.203562,0.100346,-0.105785,-0.355858,-0.068589,0.315735,0.272821,0.002369,0.165730,-0.045781,0.194007,-0.438905,0.060727,-0.572484,0.203616,0.899815,-0.215080,-0.671571,0.243558,-0.368135,-0.049632,-0.835995,-0.224164,-0.166616,0.058643,0.167260,0.208375,0.092633,-0.126291,-0.453177,0.066087,0.195528,-0.663843,0.273517,0.410183,0.248093,-0.470103,0.459229,-0.987363,-0.042167,0.104780,-0.011920,0.021843,-0.530987,-0.113397,0.129376,-0.256105,-0.148111,0.255106,-0.290021,-0.190266,-0.053325,-0.424603,0.085963,-0.003636,-0.190626,-0.203247,0.128927,-0.460619,0.808602,-0.793728,-0.149058,-0.045489,-0.012260,-0.073919,0.642548,-0.234922,0.096190,-0.117206,-0.189825,0.163010,0.117358,0.385718,0.420858,0.392101,-0.065425,0.101187,-0.544398,-0.034901', '35262731', '1441602', '26593587', '1307319');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401118', '黄金三镖客', '西部', '故事发生在美国南北战争时期。图科（埃里•瓦拉赫 Eli Wallach 饰）是一个图财害命的江洋大盗，因此他被镇上悬赏通缉。布兰迪（克林特•伊斯特伍德 Clint Eastwood  饰）是一个除暴安良的牛仔，他无意中抓住了图科，但嫌赏金不够又掳走了他。在荒漠中，布兰迪惩罚图科让其自生自灭。但是诡诈的图科居然逃过了一劫，并纠集一些帮凶在客栈捉住了布兰迪。正当图科以牙还牙折磨布兰迪的时候，他劫持了一个名叫卡森的士兵。后者临死前留下了宝藏的秘密，图科和布兰迪分别获得了一半信息。与此同时，一个狡猾的杀手桑坦萨（李•范•克里夫 Lee Van Cleef 饰）也通过其他渠道发现了宝藏的秘密。于是，在寻宝的道路上，三个人使出浑身解数，上演了一场场对决的好戏……©豆瓣', '克林特·伊斯特伍德', '赛尔乔·莱昂内', 9.2, 112550, 'tt0060196', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2178150710.jpg', 0.2, 0.4, 5, 26.5, 67.9, '0.232515,0.104087,-0.573702,0.607913,-0.148128,-0.455923,0.715002,0.039570,-0.246639,-0.211476,-0.047624,0.517500,-0.247776,-0.040579,0.377363,-0.011567,-0.228593,-0.585030,0.096747,-0.274146,-0.474977,-0.588987,-0.483507,-0.480726,0.021786,-0.505905,0.269041,0.230745,-0.390647,0.206177,0.474827,0.346109,0.004527,0.424584,-0.195498,0.248393,0.392851,-0.238715,0.236066,0.359808,-0.137815,-0.431217,-0.231552,0.324650,0.054851,0.577484,0.543077,-0.463177,0.130695,-0.007388,0.002715,-0.433558,0.007789,-0.060214,0.342573,-0.400276,0.038959,-0.118433,-0.202168,-0.142529,0.377328,-0.017461,-0.754615,-0.209354,-0.006117,0.189184,-0.583877,0.234889,-0.305403,0.187049,-0.144511,-0.397914,0.328983,0.473159,0.287346,-0.037363,0.119317,-0.335256,-0.699569,0.121674,0.619648,-0.086411,0.205185,0.062221,-0.376499,-0.708200,-0.134661,-0.235356,-0.306832,-0.014366,0.809202,-0.304353,-0.034312,0.387447,-0.516803,-0.209710,-0.388817,-0.115204,-0.474383,-0.437251,0.143888,-0.575984,-0.209469,0.038478,-0.380505,0.134535,-0.003488,-0.114639,0.514089,-0.619805,0.288379,0.819023,0.129227,-0.058716,0.515176,0.074075,0.351472,0.125237,-0.123628,0.081211,0.721637,0.121323,0.293501,0.509865,-0.026139,-0.276628,-0.317174,0.640788', '1301345', '1947080', '1300324', '2338069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401137', '长腿叔叔', '剧情', '在孤儿英美（河智苑 饰）的生命中，有这么一位“长腿叔叔”：他为她资助学费，年年送她温暖的问候和礼物。英美总是期待能和长腿叔叔见面，感谢他的帮助。然而长腿叔叔却总是神秘地藏在她生活的背后。大学毕业的英美进入电台担任编剧，并在以前同事的一间宿舍里住下。在这位旧同事留下的电脑中，她发现了一封未寄发出去的邮件，从邮件中，英美得知这是一个感人肺腑的爱情故事，故事的主人公默默地爱着另一个人，10年来爱意从未间断。如今，写信人患病了，将会慢慢失却记忆……英美决定要像长腿叔叔那样，帮助那些善良而无助的人，她要为那位陌生的同事找到意中人。同时，英美也遇上了自己的白马王子，那就是电台同事俊浩（延正勋 饰）。当二人的感情浪漫铺开时，英美却发现了一个意想不到的秘密……©豆瓣', '河智苑', '孔正植', 6.7, 10797, 'tt0453125', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167477128.jpg', 1.4, 9.1, 53.1, 27, 9.4, '0.279801,-0.049475,-0.533448,0.701569,-0.141293,-0.348422,0.751134,-0.006482,-0.601231,-0.357873,0.063848,0.677748,0.031899,0.418174,0.099941,0.116538,-0.270033,-0.741887,0.030339,-0.238803,-0.254001,-0.258307,-0.403222,-0.112858,0.053400,-0.195304,0.514175,0.036880,-0.081963,0.579616,0.138453,0.097018,-0.168617,0.482809,-0.309310,0.174006,0.175435,0.252637,-0.349526,0.118401,-0.043021,-0.234802,-0.018405,0.121726,-0.037018,0.312157,0.460176,-0.074519,-0.166673,0.094431,0.432944,0.076148,-0.061031,0.081852,0.201147,0.325000,0.485965,0.166609,-0.299230,0.036909,0.046353,-0.253503,-0.579079,-0.070623,-0.200665,0.419235,-0.539069,0.450971,-0.199940,0.191939,0.204395,-0.355478,0.157586,0.191635,0.061042,0.488039,-0.349081,0.276420,-0.274660,0.317145,0.538406,-0.050558,-0.077953,0.455194,-0.335509,-0.247390,0.258291,0.072106,-0.520833,0.124680,0.188320,0.024162,-0.270950,0.123522,-0.575908,-0.036656,-0.070624,0.192931,0.084662,-0.549764,-0.223950,-0.481565,-0.225357,-0.296379,-0.200291,0.227382,0.100951,-0.174423,0.952834,-0.737338,0.263026,0.451850,0.523554,-0.473209,0.839355,0.408491,-0.089815,-0.040102,0.014547,0.215065,-0.069971,0.207380,0.018895,0.234172,-0.121085,-0.131686,-0.571703,0.207424', '1307146', '3445516', '26283288', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401196', '神迹', '剧情', '影片根据真实故事改编，讲述白人医生阿尔佛雷德·布雷拉克（阿伦·瑞克曼 Alan Rickman饰）与黑人合作伙伴维文·托马斯（茅斯·达夫 Mos Def饰）打破种族界限，协力合作开创心脏手术先河，成为心脏外科手术先驱者的故事。医生布雷拉克在事业上雄心勃勃并且眼光独特，他发现了托马斯在医学方面的天赋，开始传授他医学相关的知识。起先托马斯用狗作为实验对象，天分过人的他很快就掌握了医学理论与手术实践上的技艺。他们一起攻克了法洛四联症（又称紫绀婴儿），可他并没有公开托马斯为此做出的贡献。在托马斯因为肤色而遭受不公正待遇的时候，他选择了沉默。两人亦主亦仆、亦师亦友，在长达三十四年的合作中，维系着这份微妙的友情。当最后托马斯终于受到肯定获奖的时候，他默默的注视着医生布雷拉克的画像，泪流满面。©豆瓣', '艾伦·瑞克曼', '约瑟夫·萨金特', 8.7, 10402, 'tt0386792', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2480753692.jpg', 0.1, 0.5, 9.8, 43.2, 46.4, '0.050872,0.024562,-0.555968,0.632561,0.126195,-0.180254,0.327417,0.091233,-0.371050,-0.447578,0.223817,0.660227,0.079984,-0.028128,0.260634,-0.028827,-0.596869,-0.812158,0.174582,-0.020743,-0.417816,-0.824066,-0.305889,-0.410331,-0.216280,-0.498125,0.675227,-0.289582,-0.382678,0.286426,-0.142078,0.095169,0.379669,0.124640,0.006342,-0.034295,0.447306,-0.235415,-0.462404,0.128105,0.414800,0.083655,-0.187751,0.227792,0.049240,0.454383,0.443676,-0.435498,-0.053119,0.019977,0.275588,-0.167203,0.109403,0.105221,0.320487,0.192458,0.241755,0.336175,-0.230007,-0.067345,0.019757,0.126538,-0.779711,-0.259201,0.162041,0.348732,-0.370106,0.513252,-0.253283,0.039401,-0.056617,-0.234943,-0.133155,0.246659,0.492722,0.355758,-0.062966,-0.039650,-0.272901,0.150011,0.226039,0.246761,-0.480352,0.401678,-0.408399,-0.563646,-0.172192,-0.252474,-0.190158,-0.160695,0.257286,0.038465,-0.082356,0.473586,-0.388528,0.034516,-0.235143,-0.061379,0.100339,-0.169831,0.056125,-0.824059,-0.162451,-0.176974,-0.403080,-0.182028,0.028528,-0.459684,0.847453,-0.794550,0.110421,0.375539,0.032321,-0.279734,0.723018,0.039891,0.155094,-0.459830,-0.316804,0.323351,-0.093964,0.254259,0.021908,0.351163,0.281886,-0.077822,-0.115853,0.629550', '27602116', '1870681', '1301172', '3012032');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401205', '七剑', '剧情', '满清军队在风火连城（孙红雷饰）的率领下逼近武庄，欲将关内隐藏的反抗力量斩尽杀绝，而武庄更是围剿的重点。武庄表面上住了一批庄稼人，实则是反清组织天地会分舵人马，全庄上下整备应敌，但却力量有限。危险逼进，路见不平的侠医傅青主（刘家良饰）为了解武庄之危，带了两位武庄青年武元英（杨采妮饰）和韩志邦（陆毅饰）上天山求助。擅于铸剑的世外高人晦明大师住在万里冰封的天山上，他珍藏七把剑中珍品。座下有大弟子楚昭南（甄子丹饰），二弟子杨云聪（黎明饰），三弟子辛龙子（戴立吾饰）以及四弟子穆郎（周群达饰），晦明大师认为武元英和韩志邦也是可塑之材，加上傅青主本人，把毕生修为炼成的七把宝剑分赠七人，是为“七剑下天山”的武林传奇。©豆瓣', '甄子丹', '徐克', 6, 62750, 'tt0429078', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2573911238.jpg', 3.7, 19.1, 55.7, 17.3, 4.2, '0.138679,-0.148473,-0.411936,0.734493,0.106931,0.046141,0.288391,0.061455,-0.635265,-0.084349,0.398051,0.507328,0.220317,0.015828,0.106739,-0.077417,0.318687,-0.658550,-0.448510,-0.152087,-0.158219,-0.318186,-0.343663,0.154092,-0.158657,-0.286398,0.390501,0.505629,-0.261766,0.348616,0.140366,0.230936,-0.245856,0.181935,-0.177365,-0.091105,-0.275561,-0.258059,-0.167116,0.403379,-0.403273,-0.241123,-0.163160,0.115549,-0.036035,0.430001,0.332644,-0.150813,0.270279,-0.221408,-0.249756,-0.009469,-0.138469,0.018407,0.369030,0.118256,0.141762,0.342711,-0.066978,0.052448,-0.091838,-0.123059,-0.597954,0.061399,0.457955,-0.111312,-0.889641,0.506277,-0.210002,-0.249560,-0.376367,-0.433805,-0.051584,0.136655,0.042724,-0.087735,0.018204,-0.154369,-0.392244,0.241731,0.209326,-0.095305,0.263854,-0.186394,0.194436,-0.343036,-0.067260,-0.616655,-0.062202,-0.167137,0.383464,-0.003681,0.331564,0.130619,-0.314417,-0.031841,-0.228885,0.002175,-0.198072,0.031416,0.011082,-0.434805,0.190938,-0.233980,-0.304236,-0.225101,0.639858,-0.188448,1.066171,-0.505671,0.046547,-0.013497,0.127213,-0.409485,0.514885,-0.154063,0.095898,0.014438,-0.443603,-0.018920,0.130888,0.486693,0.341565,0.455504,-0.446525,-0.333367,-0.238368,-0.037860', '27602116', '26348103', '24284209', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401209', '小英雄托托', '剧情', '平民家庭的托托（Thomas Godet 饰）与隔壁富人家庭的阿尔弗雷德（Hugo Harold Harrison 饰）在同一家医院同一天内出生。托托坚信，因为医院的一场大火，导致他们两个婴儿被父母抱错。本该属于他的优渥生活被阿尔弗雷德夺去，当然，每当他提及此事时不免遭受阿尔弗雷德的一顿老拳。随着父亲的意外去世，托托对阿尔弗雷德一家的嫉恨逐渐加深。憎恨并未令他得到满足与补偿，反而使他的一生永远笼罩在阴影之中……本片荣获1991年戛纳电影节青年奖最佳外语片奖、1992年法国凯撒奖最佳外语片奖、1991年欧洲电影节最佳男主角（Michel Bouquet），最佳摄影，最佳剧本和青年电影奖、1992年葡萄牙奇幻国际电影节最佳影片和最佳剧本。©豆瓣', '米歇尔·布凯', '雅克·范·多梅尔', 8.5, 6340, 'tt0103105', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2211514719.jpg', 0.3, 1, 13.7, 45.8, 39.1, '-0.197535,-0.015891,-0.711827,0.534423,0.415006,-0.321001,0.472624,0.074716,-0.627620,-0.278690,0.139695,1.166624,-0.362725,0.136457,0.502395,-0.087797,-0.380145,-0.764982,-0.054275,-0.062617,-0.059053,-0.093313,-0.396952,-0.155698,-0.336685,-0.442084,0.828473,0.081322,-0.056069,0.639991,0.564141,0.340697,-0.018802,0.000135,0.140130,0.092840,0.395824,0.047621,-0.620209,0.478628,0.169068,-0.355919,-0.322389,0.093397,0.274875,0.208804,0.749446,-0.131851,-0.179513,-0.221806,0.694246,-0.325413,-0.388380,0.012088,0.085405,-0.247485,0.246643,0.381632,-0.162099,0.187235,0.041401,-0.364345,-0.655986,0.034322,0.394809,-0.141486,-0.471346,0.634245,-0.009633,0.192129,-0.083509,0.136495,0.203694,0.263874,0.276214,0.394068,-0.437447,-0.073049,-0.280204,0.633251,0.418442,-0.160640,-0.248241,0.202450,-0.394960,-0.653109,-0.097913,-0.242338,-0.531227,0.381650,0.484453,0.140698,0.056888,0.426524,-0.321706,-0.151949,-0.198456,-0.281358,0.212404,-0.130692,-0.049858,-0.796439,0.033254,-0.089557,-0.340775,-0.161103,-0.083033,-0.159925,0.512480,-0.502135,0.561855,0.322306,0.364735,-0.249880,0.834842,0.069592,0.336323,-0.361881,-0.237493,0.348720,-0.133486,-0.281613,-0.051635,-0.169877,-0.261578,-0.269796,-0.044927,0.467304', '1780122', '1829654', '34795703', '1297368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401261', '游戏规则', '剧情', '克里斯汀（诺拉•格雷格 Nora Gregor 饰）跟女仆杰西（安•梅因 Anne Mayen 饰）探讨了男女之间友谊的话题。二人意见相左，但克里斯汀坚信异性友谊。因为她确有一位蓝颜知己——飞行员朱利（罗兰德•陶腾 Roland Toutain 饰）。他因为完成了23小 时飞越大西洋的壮举，成为了国家英雄，并公开表示出对克里斯汀的感情。朱利的朋友奥克塔夫对此颇有微词，因此叮嘱他千万不要在聚会越界。聚会是由克里斯汀的丈夫罗伯特（马塞尔•达里奥 Marcel Dalio 饰）主办的，但她却想要跟朱利私奔，这个事让罗伯特勃然大怒；杰西的丈夫对于主人在猎场新收的家丁怀有敌意，当他目睹妻子与其偷情，更是怒不可遏，一场闹剧就此开场……©豆瓣', '诺拉·格雷戈尔', '让·雷诺阿', 8.4, 11050, 'tt0031885', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p863429327.jpg', 0.4, 1.6, 14.9, 44.8, 38.3, '0.379544,-0.083763,-0.415042,0.521209,0.049403,-0.200991,0.602700,0.072320,-0.598594,-0.223978,0.223672,0.704904,-0.463845,0.105449,0.381980,0.091711,-0.401330,-0.743478,0.358217,-0.164572,-0.043345,-0.677252,0.157968,-0.369210,-0.377156,-0.283602,0.379483,-0.279967,-0.291784,0.312974,0.334588,0.363930,0.047466,0.364313,0.324068,-0.016605,0.248793,0.143837,-0.519375,0.034005,-0.031758,0.074435,-0.232938,0.264840,0.280768,0.481488,0.442338,-0.406943,-0.074683,-0.046619,0.063435,-0.248127,0.455461,0.158840,0.106132,-0.240282,0.114457,0.315290,0.085875,-0.140849,0.304557,-0.111168,-0.351820,0.381190,-0.198976,0.236810,-0.418274,0.427591,-0.201919,-0.011584,0.130903,0.111596,-0.050783,0.242040,0.212853,-0.004233,-0.126466,0.164374,-0.166354,-0.032292,0.453487,0.294325,0.079975,0.304885,-0.457663,-0.396512,-0.043863,0.102463,-0.542586,-0.097051,0.190519,-0.122319,-0.033575,0.520597,-0.378203,-0.336358,-0.381342,0.079915,0.121883,-0.453201,0.308810,-0.581997,0.071014,-0.394604,-0.486412,-0.188788,0.210847,-0.320825,0.602162,-0.870012,-0.014674,0.540402,0.337278,-0.491945,0.549063,0.402874,0.140692,-0.514495,-0.045336,0.361949,-0.062665,-0.314626,0.242936,0.229900,0.339081,-0.204416,0.013029,0.429009', '1299556', '24325856', '1308314', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401269', '早春二月', '剧情', '1926年，青年知识分子肖涧秋（孙道临 饰）应老同学陶慕侃（高博 饰）之邀，来到浙东小镇中学任教。在前往赴教的轮船上他遇到了丈夫死于广州起义的文嫂（上官云珠 饰），顿生同情之心。在陶慕侃为其举行的欢迎家宴上，他认识了陶的妹妹，活泼大方的陶岚（谢芳 饰）。交谈中方知在轮船上遇到的孤儿寡母竟是老同学李志浩的家小。出于正义和同情，肖涧秋经常资助造访文嫂家，这引起了周围人议论。而肖的正义品格却赢得了陶岚的爱慕，此时的肖涧秋陷入了巨大矛盾之中。他爱陶岚，更同情饥寒交迫的文嫂一家，考虑再三他决定娶文嫂为妻。陶岚无比震惊，指责他这不是爱情是因为同情。此时，一直暗恋陶岚的钱正兴（王培 饰）来到肖的宿舍，表示愿意出钱资助他与文嫂结婚，并希望他把陶岚让给自己。肖涧秋闻言怒不可遏......©豆瓣', '孙道临', '谢铁骊', 8.2, 10673, 'tt0057713', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2039220228.jpg', 0.2, 1, 15.3, 55.2, 28.3, '0.171185,0.038732,-0.750689,0.287752,-0.089707,-0.384457,0.584928,0.249702,-0.445922,-0.280581,0.053841,0.547574,0.007377,0.381710,0.243540,-0.305347,-0.075520,-0.385407,-0.046861,-0.164455,-0.024420,-0.522547,0.147628,-0.245689,-0.277772,-0.000024,0.186181,0.366729,-0.163656,0.902418,0.545820,0.338789,0.199444,0.560961,0.105390,0.002177,-0.273838,0.405160,-0.346713,-0.066327,-0.204490,-0.186682,-0.123971,0.083634,-0.058315,0.400779,0.477989,0.047722,-0.102478,-0.213355,0.369029,-0.335492,0.214757,0.153786,0.252618,-0.017140,0.074656,0.010869,-0.336850,0.061220,0.094242,-0.009942,-0.378487,-0.045780,0.192241,0.035556,-0.583383,0.507557,-0.039790,-0.192136,-0.005122,-0.289065,0.295063,0.193736,0.123041,0.263513,-0.167316,0.129852,-0.235334,0.337372,0.794222,0.015650,0.307250,0.034152,-0.456672,-0.407435,0.246929,-0.053563,-0.441442,-0.138882,0.155969,0.127850,0.142987,0.059476,-0.412250,-0.298998,0.094996,0.208854,0.214817,-0.529097,0.037046,-0.382050,-0.233924,-0.333962,-0.223620,-0.023990,0.018004,-0.461725,0.646343,-0.922699,0.220241,0.186734,0.620812,-0.644156,0.727576,0.325085,0.013804,-0.223048,-0.106425,0.315564,0.000692,0.006697,-0.208733,0.012746,-0.089418,-0.081523,-0.232100,0.160728', '35030151', '1292219', '2990737', '2079632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401282', '长大成人', '剧情', '1976年北京的夏天，男孩周青（殷宗杰 饰）带着被父亲剃了一半的头发，和朋友小莫跑向了一截长城的遗址，在那里周青拾到一本残缺的小人书——《钢铁是怎样炼成的》。周青在地震期间看到男青年纪文（李强 饰）的吉它，以及纪文还在上高中的女友绍英（朱洁 饰）。不久四人帮倒台，周青开始在纪文的乐队中担任乐手，这段少年生活很快在纪文与绍英的纷争中宣告结束。周青进入了货运站开始强劳动力的工人生活，强壮火车司机朱赫莱（田壮壮 饰）成为了他心中的榜样，两人的相识以朱赫莱用自己的腿骨挽救遭遇事故的周青结束。一晃多年，八十年代末，周青（朱洪茂 饰）结束在海外的学艺回到北京，面对使他倍感陌生的北京摇滚圈，理想主义者周青无所适从，只能凭借寻找朱赫莱的执念在城市中继续游走……©豆瓣', '朱洪茂', '路学长', 8, 12166, 'tt0470617', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2360255403.jpg', 0.3, 2.1, 22.5, 49.4, 25.8, '0.348463,0.017081,-0.772092,0.408526,-0.161012,-0.453717,0.618935,0.055844,-0.567090,-0.103125,0.363559,0.740808,-0.416403,0.471997,0.309800,-0.113466,-0.228855,-0.706414,-0.002368,-0.123762,-0.368544,-0.271716,-0.205974,-0.041712,-0.242255,-0.260492,0.684014,0.239401,-0.086764,0.555567,0.189710,-0.032447,-0.114789,0.394015,-0.359232,0.112463,-0.135804,0.024961,-0.278187,0.093109,0.184850,-0.530495,-0.231984,-0.105798,-0.086470,0.216025,0.837993,0.038814,0.075719,0.010447,0.413620,-0.133488,-0.349830,-0.119417,0.481481,0.302431,0.023021,0.162491,-0.298959,0.154667,-0.010196,-0.222962,-0.205753,-0.111996,0.000533,0.258801,-0.708777,0.721779,0.050411,-0.023189,0.142082,-0.586609,0.191046,0.394490,-0.057490,0.751949,-0.184162,0.030144,-0.448779,0.439291,0.593639,0.053270,-0.288128,0.104094,0.136249,-0.392264,-0.217890,-0.086055,-0.268827,-0.126406,0.305505,-0.146409,-0.189669,0.078219,-0.686537,0.046154,-0.025219,-0.216088,0.058485,-0.128984,-0.324434,-0.591868,0.005025,-0.563984,-0.065464,0.107703,0.068243,-0.332153,0.622797,-0.829272,0.196550,0.284709,0.329609,-0.141848,0.518564,-0.143222,0.271943,-0.260786,-0.003544,0.261714,-0.198174,0.461486,0.379192,0.337035,-0.291169,-0.132072,-0.450426,0.400129', '3155839', '1292219', '2027925', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401338', '蓝色爱情', '剧情', '刑警邰林（潘粤明 饰）偶遇自杀女孩刘云（袁泉 饰），急忙上前施救，刘云告诉他，因男友欺骗自己感情她已结束其生命，但后来的结果却是个令人哭笑不得的闹剧。原来刘云是个话剧演员，为体验生活出来找灵感，邰林对她既生气又喜欢。几天后，邰林如约来到老地方见面，刘云央他帮忙寻找曾经救 过自己命的男人白驹（王刚 饰）。处于职业习惯，邰林对刘云的身世也做了一番调査，知道她没有父亲。又过一段时间，刘云带邰林一起去见自己的母亲李文竹（崔敏捷 饰），此时李文竹神情恍惚，已不谙世事。通过调査，邰林发现白驹与一桩多年前的凶杀案有扯不清的联系，邰林陷入苦闷之中，他不知刘云与白驹是什么关系，在偶然看到的一份杂志上，他推断出白驹就是刘云的父亲......©豆瓣', '潘粤明', '霍建起', 7.8, 8500, 'tt0373081', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537403949.jpg', 0.3, 2.2, 26.8, 46.2, 24.5, '0.176959,0.077865,-0.611107,0.494506,-0.243432,-0.443709,0.846483,-0.400161,-0.586170,-0.547532,0.009222,0.549236,-0.302941,0.411171,0.168827,-0.040346,-0.241428,-0.593802,0.156840,-0.103543,-0.244738,-0.383397,-0.301513,-0.019640,-0.100419,0.094641,0.391305,-0.063425,-0.181481,0.481353,0.356125,0.091013,-0.109080,0.543158,0.027846,0.221988,-0.242244,0.341748,-0.320548,-0.064907,0.367843,-0.373393,-0.456414,0.056745,-0.025288,0.436367,0.381999,0.035486,-0.367895,0.027009,0.359365,-0.095369,0.121682,-0.074596,0.263562,0.000622,0.101475,-0.100164,-0.319367,-0.168629,-0.070103,0.137486,-0.408729,0.208921,0.098299,0.151499,-0.464569,0.102289,-0.251537,-0.083205,0.000906,-0.616554,0.154708,0.243012,0.343058,0.412888,-0.140847,-0.016341,-0.263483,0.254445,0.705899,0.210936,0.116479,0.404572,-0.119771,-0.374138,0.190585,-0.071121,-0.169510,0.173708,0.014074,0.026752,-0.144654,-0.042096,-0.186749,-0.176648,-0.113646,0.157158,-0.087783,-0.268104,-0.019376,-0.242516,-0.139609,-0.391363,-0.244634,-0.058901,0.035251,-0.426106,0.255792,-0.691837,0.149855,0.213388,0.093836,-0.700168,0.629405,0.135809,-0.023909,-0.370413,0.136588,0.202837,-0.028868,0.166643,0.274257,0.178174,0.166550,-0.080660,-0.218841,0.289239', '1308755', '1302384', '25858759', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401383', '甜蜜的人生', '剧情', '善宇（李秉宪 饰）对黑帮老大姜老板忠心耿耿，做事认真妥当的他也深得姜老板的信任与厚爱。姜老板更将自己的餐厅交给了善宇打理。姜老板出名无情冷酷，谁都不能破坏他定下的规矩。最近他感觉到自己的情人熙秀（申敏儿 饰）可能有了别的男人，姜老板便把心腹善宇安排在了熙秀的身边，当查明熙秀红杏出墙时，善宇便将熙秀处死。果不其然，善宇发现熙秀真的另有情人，但善宇竟然放走了他们……©豆瓣', '李秉宪', '金知云', 7.4, 13246, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p837948451.jpg', 1.1, 5.3, 34.8, 41.5, 17.3, '0.145787,0.116476,-0.388288,0.495723,-0.341834,-0.255433,0.721643,0.309042,-0.366872,-0.254028,0.131935,0.450697,-0.039887,0.277402,0.456071,0.325997,-0.145547,-0.484757,-0.288743,-0.121983,-0.349085,-0.643326,-0.129620,-0.460341,-0.074622,0.246618,-0.006847,0.028241,-0.170986,0.094888,0.747784,-0.028049,0.095310,0.790068,-0.057936,0.323127,0.107439,-0.001442,-0.256339,-0.130983,0.226120,-0.184777,0.045091,0.341874,0.140386,0.241143,0.136204,-0.084608,-0.425500,-0.114989,0.322682,-0.114529,0.304076,0.220602,0.434144,-0.064425,-0.005679,0.337295,-0.364648,-0.123322,-0.006902,0.071067,-0.535461,0.118566,0.239221,-0.291743,-0.694304,0.276490,0.037246,0.103551,-0.091757,-0.306183,0.292284,0.102770,0.372323,-0.004180,0.120243,0.243989,-0.304662,0.036626,0.486793,-0.051503,0.180239,0.044615,0.201050,-0.528722,-0.023204,-0.075382,-0.267122,0.114368,0.313118,-0.044874,0.138107,-0.015836,-0.228145,-0.491064,0.011826,0.220471,0.224970,-0.556320,0.195306,-0.169582,0.020063,-0.538342,-0.401495,0.297849,0.108642,-0.352834,0.691853,-0.557042,-0.020156,0.333667,0.314793,-0.933635,0.555004,0.025063,0.123201,-0.501148,-0.186709,0.057134,0.577461,0.304058,0.645860,0.360281,-0.068479,-0.114838,0.079603,0.278974', '1302110', '1308206', '3074415', '26718282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401385', '彗星美人', '剧情', '今年的萨拉·西登斯奖得主是年轻的伊芙·哈灵顿（安妮·巴克斯特 饰）。然而在去年十月，伊芙还只是一个连续数周默默注视名角玛戈·钱宁（贝蒂·戴维斯 饰）的戏迷。被玛戈的朋友凯伦·理查兹（塞莱斯特·霍姆 饰）带到玛戈面前后，伊芙讲述的经历打动了众人。玛戈收留了无依无靠的伊芙，伊芙也尽心尽力地打理玛戈的生活和工作，但是玛戈的侍伴伯迪·库南（塞尔玛·里特 饰）不喜欢研究玛戈的伊芙。热爱表演的伊芙当然不满足于做玛戈的助理，那么伊芙是怎样获得表演机会的？©豆瓣', '贝蒂·戴维斯', '约瑟夫·L·曼凯维奇', 8.7, 24188, 'tt0042192', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p456699730.jpg', 0.2, 0.6, 9.2, 44.9, 45.2, '-0.002031,-0.257365,-0.419277,0.590841,0.008860,-0.381109,0.582938,0.089597,0.430602,-0.177733,0.224325,0.654097,-0.283162,0.366942,0.790905,0.429383,-0.471312,-0.626080,0.125029,-0.050464,-0.363339,-1.056925,0.372458,-0.538866,-0.059870,-0.206006,0.699044,-0.391615,0.274235,0.650376,0.408753,0.443355,-0.231960,0.617318,0.101990,0.373209,0.497091,-0.399418,-0.239880,0.316480,0.021958,0.184772,-0.162494,0.626942,0.539171,0.302244,0.408268,-0.581675,0.338053,0.095381,0.189071,0.066878,0.513193,-0.180733,-0.093961,-0.224136,0.334380,0.141154,-0.324687,0.088013,-0.150206,-0.283984,-0.210172,0.059701,0.581351,0.258971,-0.673140,0.354521,-0.075738,-0.235320,-0.249850,0.252671,-0.225109,0.597371,0.061396,0.570804,0.109469,0.208993,-0.586020,-0.411653,-0.080143,-0.085856,-0.230235,0.904140,0.229468,-0.307427,-0.007190,0.077396,-0.722079,0.171507,-0.257870,-0.080023,0.043569,0.317910,-0.557825,-0.149092,-0.644690,0.007041,0.320337,-0.396064,-0.329527,-0.431293,0.245902,-0.680416,-0.925552,-0.644237,-0.006920,-0.391496,0.643262,-1.088124,-0.056166,0.352179,0.173496,-0.001580,0.304773,0.062959,0.301397,0.025184,-0.428973,0.537350,0.177443,-0.016106,0.445831,0.525835,0.155033,-0.326089,-0.229007,0.471060', '21766698', '4043647', '1922691', '25908065');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401390', '有情饮水饱', '喜剧', '马须仁(梁朝伟 饰)专门为上市公司提供重组合并方案，是一个年轻有为的钻石王老五；但他的为人却十分刻薄吝啬，女友为了报复将他的信用卡及银行支票全部挂失，恰巧又遇上公众假期，银行都停业了，他突然之间变成了身无分文的“穷人”。这时，马须仁邂逅亚彩(舒淇 饰)，更在亚彩面前大出洋相，笑话百出。亚彩以为他假装扮成有钱人，于是劝马须仁应当脚踏实地做人，两日在交往中渐渐坠入爱河。亚彩由于父亲炮仗叔(黄一飞 饰)逼她嫁给乡长之子，无奈下向父亲辩称已跟一个富家子弟相恋，并安排马须仁与父亲见面。本来就是有钱人的马须仁表现得游刃有余，但他的真正身份终给亚彩揭破，亚彩认为他是故意玩弄他，一怒之下出走了……©豆瓣', '梁朝伟', '王晶', 6.3, 12388, 'tt0338565', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486549799.jpg', 1.5, 11.3, 62.3, 20, 4.8, '0.118785,-0.010414,-0.454344,0.341569,-0.210782,-0.149613,0.174506,0.247301,-0.231733,-0.420127,0.180590,0.697708,-0.141031,0.140412,0.258214,-0.081575,-0.050841,-0.548404,-0.025292,-0.141253,0.102560,-0.385810,0.126391,0.006599,-0.243391,0.182195,0.342258,-0.010097,-0.046372,0.339463,0.510251,0.123610,-0.130304,0.372927,-0.070306,0.010309,-0.022150,0.091275,-0.320892,-0.097563,0.065371,-0.134163,-0.082397,0.140601,-0.008912,0.418994,0.286814,-0.050294,-0.316093,-0.185418,0.473492,-0.228116,-0.120564,0.033740,0.022363,-0.017898,0.322258,0.182365,-0.234548,0.097842,0.203886,0.086722,-0.588573,-0.084124,-0.033825,-0.129989,-0.386472,0.389898,0.000626,-0.047016,-0.096371,-0.239734,0.097243,0.097977,0.152452,0.236004,-0.211578,-0.040698,-0.521535,0.256229,0.492072,0.215532,-0.153258,0.536125,-0.147511,-0.193131,0.278466,-0.225265,-0.540715,-0.036661,-0.070012,-0.104197,-0.095465,0.171757,-0.300922,-0.302648,-0.279376,0.308060,0.132127,-0.558507,0.011856,-0.107373,-0.181255,-0.329644,-0.288542,0.158376,0.045292,-0.433844,0.282326,-0.514096,-0.015459,0.413701,0.479336,-0.577330,0.410765,0.260880,-0.073906,-0.362076,-0.065741,-0.242523,0.400752,0.034870,0.120341,-0.079149,-0.082610,-0.230325,-0.246082,0.225118', '6778650', '3215099', '1304977', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401487', '生死劫', '剧情', '嫣妮（周迅 饰）的父亲是一名农民，她的母亲在下放的时候嫁到了当地。母亲没有让她在农村长大，不到一岁就把她送到北京，让姥姥带大。因为从小就离开了妈妈，让她感觉自己的存在似乎不是那么重要，生活在姥姥家中更是觉得寄人篱下。性格也变得孤僻起来，沉默寡言。大学的录取通知书让她感觉自己的生活有了新的景象，可是他遇到了木玉（吴军忱 饰）——一名小货车司机。她被木玉细致入微的呵护和突如其来的爱情冲昏了头脑。直到后来，她才知道自己的赌注下大了，木玉只想利用她生小孩，然后卖掉小孩换钱。嫣妮面对如此打击并没有就此放弃，而是坚强地活下去……©豆瓣', '周迅', '李少红', 7.7, 6484, 'tt0457472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513588834.jpg', 0.7, 3.4, 26.2, 47.2, 22.4, '0.141012,0.110598,-0.852997,0.707930,-0.657137,-0.389431,1.046367,0.218481,-0.355474,-0.128035,0.193256,0.955617,0.107476,0.418226,0.046327,0.249940,-0.011563,-0.647609,0.114449,-0.110113,-0.334522,-0.338706,-0.210198,-0.060288,-0.161301,-0.148191,0.650445,-0.033358,-0.348690,0.180592,-0.017485,-0.034499,0.623047,0.727367,-0.469107,0.225379,-0.117806,0.291720,0.189515,-0.047541,0.295987,-0.308207,-0.171778,0.491907,0.102097,0.293294,0.638233,-0.108065,-0.280791,-0.106231,0.244129,-0.222118,-0.283051,0.160553,0.027733,-0.145845,0.067147,-0.010900,-0.484121,0.097173,0.172705,0.099187,-0.555545,0.205887,0.059333,0.030924,-0.917839,0.380512,-0.153621,-0.124172,0.140527,-0.559149,0.207779,0.319254,0.034143,0.649105,-0.314220,-0.058360,-0.631235,0.368984,0.905526,-0.339778,-0.238443,0.603617,-0.457247,-0.411383,0.156101,-0.449355,-0.628912,0.005204,0.177372,0.050444,-0.618135,0.151302,-0.364068,-0.023893,-0.237945,-0.299980,-0.018353,-0.705527,-0.089505,0.013641,-0.196895,-0.646581,-0.545426,0.005348,-0.070567,-0.444673,0.907015,-0.820684,0.212641,0.708216,0.405333,-0.779357,0.592793,0.261150,-0.074326,0.026262,0.180427,0.190663,-0.184100,0.465154,0.350013,0.326214,-0.032236,-0.169280,-0.222620,0.805253', '26718282', '1299965', '4275444', '2036270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401520', '抛掉书本上街去', '剧情', '少年北村英明（佐々木英明 饰）生活在一个充满绝望、腐烂气息的家庭中。48岁的父亲（斎藤正治 饰）曾是陆军的上等兵，退伍后整天呆在家里无所事事，沉湎于自渎的堕落快感中；祖母（田中筆子 饰）老年痴呆，不问家务，还有偷窃的毛病；妹妹（小林由起子 饰）与周围的人完全没有交流，却和心爱的兔子发展出异乎寻常的亲密关系。校足球队的教练近江（平泉征 饰）对英明青眼有加，通过近江的引领，英明在花街柳巷献出了自己的第一次。妹妹和兔子的关系引起家人的焦虑，隔壁的金先生（下馬二五七 饰）偷偷杀掉兔子。绝望的妹妹勾引校足球的队员，结果反被球员们轮暴。黯淡的青春破碎滴血，没有希望。©豆瓣', '佐佐木英明', '寺山修司', 8.5, 7489, 'tt0228853', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506950717.jpg', 0.7, 1.9, 12.9, 40, 44.6, '0.071539,-0.215200,-0.508468,0.498521,-0.280537,-0.306462,0.652870,0.297331,-0.543519,-0.307583,0.091587,0.511471,-0.083985,0.324125,0.095944,-0.114068,-0.029656,-0.790075,-0.350368,0.087031,-0.080051,-0.407793,-0.158258,-0.165021,-0.178144,-0.319648,0.632906,0.074812,-0.117068,0.628938,0.287309,0.358604,0.031060,0.205027,-0.050483,0.000672,0.060127,0.246482,-0.194666,-0.116872,-0.047744,-0.091861,0.065939,-0.061378,0.191833,0.270958,0.636443,-0.439650,-0.051480,-0.351336,0.252387,0.150419,-0.017388,0.365218,0.272273,-0.069729,0.125639,-0.000773,-0.169810,-0.105096,0.133885,0.094381,-0.608595,-0.025570,0.227402,0.248777,-0.583964,0.488829,-0.030613,0.030997,0.399923,-0.202702,0.219374,0.097237,-0.012977,0.530183,-0.253366,0.144899,-0.181400,0.295387,0.560474,-0.092437,-0.181096,0.074440,-0.367943,-0.126814,0.089759,-0.251523,-0.534663,-0.053498,0.063110,-0.000576,-0.089612,0.259510,-0.577833,0.041964,0.088405,-0.018203,0.074199,-0.213513,-0.164098,-0.395619,0.017744,-0.445537,-0.300530,0.198777,0.173181,-0.092580,0.681286,-0.788847,0.192685,0.275298,0.212793,-0.539453,0.762992,0.105249,-0.127271,-0.203582,-0.133327,0.154924,0.138801,0.197690,0.074621,0.406001,-0.222175,-0.086870,-0.381125,0.323759', '3445516', '35030151', '26809007', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401522', '再见箱舟', '悬疑', '偏远隔绝的日本山村，财主时任家的少爷大作（原田芳雄 饰）偷走村里所有住户的钟，将其埋在地下。从此，村中失去时间的概念，止步不前。多年之后，大作的堂弟舍吉（山崎努 饰）和堂妹惠子（新高けい子 饰）结婚，然而惠子的父亲当年为防止不伦之事而给女儿戴上了贞操带。婚后多年，舍吉夫妻因性事甚为苦恼，而舍吉也因没有子女而被村人嘲笑。某天，愤怒的舍吉忍无可忍，刺死了嘲笑他的大作。在此之后，夫妻二人选择逃亡，不过最终还是返回了村中。从此，舍吉便经常能够看到大作的鬼魂，并渐渐开始忘却周遭事物的名称，心性失常。在这个恍如孤岛的村落，怪诞的事情接连发生，从未停止……本片为先锋导演寺山修司遗作。©豆瓣', '山崎努', '寺山修司', 8.1, 6997, 'tt0088041', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561918107.jpg', 1.5, 2.9, 18.4, 43.9, 33.3, '0.159114,-0.059834,-0.548699,0.524881,0.081417,-0.418459,0.619022,0.023246,-0.609711,-0.515716,-0.041712,0.559891,-0.205944,0.293397,0.160670,-0.061156,-0.030577,-0.639142,-0.104022,-0.124236,-0.100173,-0.310322,0.215730,-0.243476,-0.264471,-0.287904,0.440234,0.218522,0.002189,0.373462,0.310118,0.378929,-0.284892,0.223222,0.124864,0.238785,-0.257604,0.122732,-0.367914,0.123022,-0.219885,-0.164127,0.008859,-0.006720,-0.090066,0.487686,0.754858,-0.344152,-0.343540,-0.209960,0.386716,-0.156969,-0.277784,0.157177,0.469008,0.019561,0.208188,0.174285,-0.432829,-0.138614,0.065372,0.039390,-0.333515,0.077365,0.280085,-0.121639,-0.460147,0.449839,0.083142,-0.131580,-0.071657,-0.258677,0.389082,0.417469,0.229875,0.307651,-0.217095,0.008917,-0.227056,0.228509,0.650900,-0.203192,-0.125975,0.289974,-0.171663,-0.148733,0.136992,-0.389195,-0.459963,-0.046675,0.056137,0.227918,-0.257813,0.250707,-0.275022,-0.218939,-0.290173,-0.157313,0.298512,-0.310047,-0.263067,-0.346956,-0.157919,-0.422931,-0.102810,0.297915,0.039629,-0.115737,0.440384,-0.835283,0.330380,0.269779,0.159053,-0.157124,0.452522,-0.065958,0.059422,-0.157983,-0.097834,0.177909,0.067220,0.423254,0.174060,-0.113755,-0.218765,-0.237654,-0.242073,0.288526', '35030151', '30345227', '1301022', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401523', '下女', '剧情', '某纺织厂的音乐部教师东植对锦川发生的一起杀人事件表示出极大的兴趣。某天，东植从女工郭善英处收到一封情书，并向舍监告发，善英被工厂开除。曾鼓励善英写信的朋友赵庆熙借着钢琴辅导的契机开始出入东植家。为了贴补家计，东植妻子做了很多裁缝活儿，身体越来越虚弱。东植委托庆熙寻找到一名合适的下女，帮助持家。妻子怀孕回娘家的当下，庆熙借机向东植表达了爱意，却受到辱蔑被撵了出去。这一切都被窗外的下女看到眼里。下女借机诱惑东植，并与之发生了肉体关系。三个月后，下女怀孕。东植的妻子知道真相后，将下女推下楼梯，导致流产。失去孩子的下女怒火中烧，性情开始变得暴烈。结果，下女将东植夫妇俩的孩子也推下楼梯，藏了起来。下女以向工厂曝光所有事实相要挟。为了保住整个家庭，东植将二层的房间让给下女。最后，准备和下女一起吃耗子药自杀的东植看到死在台阶上的下女，毅然抛弃了她，重新回到了妻子身边。这时，电影画面再次回到东植夫妇看着有关那起杀人新闻的画面，东植不禁说道：这样的事情有可能发生在任何一个人的身上。', '金振奎', '金绮泳', 7.1, 5937, 'tt0150980', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p483116745.jpg', 1.5, 6, 38.2, 42.9, 11.4, '0.299278,0.195235,-0.551585,0.255798,-0.079846,-0.239513,0.765051,0.088052,-0.215612,-0.294978,0.177656,0.628127,-0.288078,0.400222,0.418182,-0.264776,-0.335836,-0.687179,-0.282356,-0.140797,-0.396217,-0.341944,0.171573,0.185369,-0.247680,-0.247208,0.393662,-0.036243,-0.064301,0.266348,0.443065,0.311213,0.011911,0.306794,0.027308,0.273922,-0.339890,-0.147458,-0.214416,0.342396,0.230100,-0.361218,-0.129744,-0.006626,0.090478,0.078990,0.602397,-0.186387,-0.269478,-0.462340,0.529920,0.077409,0.018989,0.231900,0.282862,0.256537,0.235423,0.336800,-0.358118,-0.224003,0.286876,0.102746,-0.474680,0.137664,0.052752,0.157772,-0.650089,-0.105183,0.107015,0.061305,0.148666,-0.527912,0.217327,0.313207,0.295884,0.384114,-0.539677,0.419639,-0.299889,-0.122684,0.735961,0.214164,0.099753,0.144010,0.015773,-0.107273,0.209451,-0.072456,-0.210219,0.077288,0.409152,0.303978,-0.240762,0.010161,-0.207449,-0.236752,-0.227967,-0.236635,0.144563,-0.355053,-0.106831,-0.468234,-0.006612,0.130986,-0.464695,0.186982,0.283750,-0.411786,0.455742,-0.641404,0.215986,0.417056,0.647293,-0.455461,0.378620,-0.110445,0.247554,0.100368,-0.116333,-0.006327,0.215283,0.560491,0.015076,0.334190,-0.398703,-0.208515,-0.384023,0.120936', '30345227', '1301022', '1292533', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401524', 'X战警3：背水一战', '动作', '琴（法米克·詹森 Famke Janssen 饰）的死亡在X战警中造成了持续的影响，斯科特和金刚狼罗根（休•杰克曼 Hugh Jackman 饰）恍然若失。学院的教学任务落在了风暴女（哈莉•贝瑞 Halle Berry 饰）和金刚狼等人的肩上，异种人在这里才能得到身份的认同。某公司从一名异种人儿童的基因中提取出了还原变异的X基因的“解药”，可以令异种人的身体与常人无异，解药的问世在异种人中引起了强烈反响，万磁王（伊安•麦克莱恩 Ian McKellen 饰）四处联系不愿改变体质的异种人，试图用暴力反抗人类社会的不公平待遇。金刚狼等人发现琴并未死去，而且她被唤醒的第二重人格拥有极为强大的力量，X教授（帕特里克•斯图尔特 Patrick Stewart 饰）和万磁王各自争取琴，她成为了改变异种人世界的关键人物…©豆瓣', '休·杰克曼', '布莱特·拉特纳', 7.7, 221240, 'tt0376994', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2230029851.jpg', 0.3, 2.2, 30.1, 49.3, 18, '0.079211,0.168777,-0.627577,0.577625,-0.339518,0.152567,0.657573,0.064287,-0.540920,-0.222837,0.165330,0.618891,-0.013852,-0.137268,0.179943,-0.095524,-0.119248,-0.390491,0.015134,-0.041597,-0.640426,-0.167440,-0.380148,-0.401607,-0.066626,-0.991976,0.643724,-0.093957,-0.493705,0.181802,0.015410,0.575615,-0.128309,0.318963,-0.065189,0.109314,-0.038352,-0.064749,-0.080514,0.266696,0.057564,0.001603,-0.004371,0.202728,-0.096293,0.014218,0.935091,-0.578106,-0.066374,-0.420581,0.321237,-0.102244,-0.044859,-0.039638,0.500204,-0.075072,0.083476,0.269902,-0.010567,0.110659,0.175538,0.195516,-0.924882,-0.152131,0.020727,0.351297,-0.332186,0.678628,0.052209,0.111744,-0.244597,-0.149847,0.119513,0.040054,0.052300,0.254040,-0.011085,-0.273652,-0.679159,0.130641,0.346652,-0.100693,-0.637383,0.293211,-0.530120,-0.709849,-0.570663,-0.485288,-0.153545,-0.196377,0.431087,0.451376,-0.426680,0.259347,-0.621740,-0.215588,-0.264542,-0.058335,-0.216042,-0.387711,-0.055218,-0.646123,-0.172210,-0.298079,-0.150385,0.074077,0.214909,-0.315704,0.927532,-0.935781,0.078498,0.536876,0.415956,-0.352660,0.671967,-0.421687,0.109498,-0.397191,-0.122436,0.101657,0.163701,0.292465,0.385691,0.486960,0.167198,0.143849,-0.292734,0.592201', '24284209', '1295250', '3769423', '6038071');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401533', '碟中谍3', '动作', '伊森（汤姆·克鲁斯 Tom Cruise 饰）曾是任职于特殊部门的秘密特工，自从一位名叫茱莉亚（米歇尔·莫娜汉 Michelle Monaghan 饰）的美丽女子出现在他的生命里后，伊森决定金盆洗手，卸甲归田。遗憾的是，好景不长，幸福的生活还没过多久，伊森便接到了徒弟林德赛（凯丽·拉塞尔 Keri Russell 饰）被死对头戴维恩（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）掳走的消息。戴维恩冷酷又凶残，林德赛落入他的手中可谓是凶多吉少。为了解救林德赛，伊森重操旧业，他组织了一支精干的特工小组，向着目标人物发起了进攻。让伊森没有想到的是，戴维恩的真正目标并不是林德赛，而是茱莉亚，当爱妻落入敌手之时，伊森会做出怎样的反击？©豆瓣', '汤姆·克鲁斯', 'J·J·艾布拉姆斯', 7.6, 182017, 'tt0317919', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p802439727.jpg', 0.2, 2, 31.9, 48.6, 17.3, '-0.021917,0.188246,-0.648326,0.662581,-0.512537,-0.321106,0.780193,0.026366,-0.896232,-0.318030,0.157456,0.530906,0.207303,0.201315,0.549239,-0.103699,-0.029412,-0.617011,-0.105090,-0.195302,-0.237790,-0.514642,-0.525955,-0.493394,0.139498,-0.389389,0.505957,0.184239,-0.291377,0.087836,0.779199,0.526351,-0.132152,0.656972,0.010902,-0.036891,0.054640,-0.099220,-0.462869,0.392701,0.067632,-0.390902,-0.103486,0.144938,0.003470,0.368491,0.475749,-0.153302,-0.123217,-0.363325,0.153687,-0.343951,0.131000,-0.107815,0.449000,-0.031741,-0.142415,-0.140526,-0.096090,-0.121544,0.411470,-0.203659,-0.796537,-0.003238,0.253612,0.196963,-0.534496,0.018450,-0.513989,0.075802,0.170039,-0.391472,0.135071,0.348000,0.555938,-0.001483,0.204546,0.177799,-0.303462,0.184625,0.574099,0.186389,-0.248194,-0.076922,-0.015842,-0.602152,0.051583,-0.011805,-0.335063,0.216792,0.665614,0.243743,0.068658,0.306654,-0.225608,-0.236283,-0.373395,0.019992,0.022481,-0.436404,0.043590,-0.657739,0.127327,-0.191343,-0.292544,0.203664,-0.122240,-0.145013,0.487035,-0.923996,0.371413,0.288137,0.004751,-0.217467,0.246812,-0.085685,-0.001879,-0.325365,0.229438,0.568463,0.324573,0.247026,0.004956,0.205655,0.167691,-0.437054,-0.206529,0.532255', '1301022', '1294616', '25870679', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401535', '虎胆龙威4', '动作', '某年7月4日，周末，正在休假的约翰•麦卡伦（布鲁斯•威利斯 饰）接到一个新任务：逮捕黑客马特•法莱尔（贾斯汀•朗 饰），然后送到FBI那里接受审讯。其实，事情并没有看上去那么简单：极端恐怖分子经过周密策划之后，准备利用黑客技术，在美国独立日当天让全美国的计算机系统集体瘫痪，从而达到他们控制全球的阴谋。而且，幕后黑手托马斯•加布里埃尔（提摩西•欧里芬特 饰）为了阻止麦卡伦插手这件事情，为他准备了一大堆机关障碍，其中包括绑架他的女儿露西。老英雄遇上了新问题，在马特•法莱尔的帮助下，麦卡伦继续“生猛”……©豆瓣', '布鲁斯·威利斯', '伦·怀斯曼', 7.7, 74662, 'tt0337978', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p916787060.jpg', 0.3, 2.1, 28.4, 51.5, 17.6, '0.122381,0.071089,-0.424978,0.217338,0.002100,-0.143126,0.206070,0.042314,-0.440726,-0.578980,-0.004788,0.220797,0.103958,0.039884,0.525375,-0.283259,-0.829952,-0.452305,0.265401,-0.102043,-0.436410,-0.725832,-0.150038,-0.402657,0.052420,-0.377173,0.235530,0.023573,0.054333,0.086823,0.203760,0.390839,0.004056,0.269871,0.418378,-0.205829,0.460028,-0.323764,-0.463799,0.391530,-0.154713,0.156211,-0.095319,0.098511,0.190946,0.360347,0.154676,-0.275224,-0.111520,-0.346268,0.278263,-0.299060,0.011152,0.042717,0.329228,0.014471,0.148923,0.362682,-0.344451,-0.050990,0.263131,-0.258736,-0.874568,-0.109689,0.055851,-0.008741,-0.231275,-0.046817,-0.369945,0.202484,-0.067881,-0.434355,-0.129250,0.721196,0.479926,0.107987,0.040952,0.159636,-0.247217,-0.015620,0.323227,-0.114320,-0.171772,0.194092,0.234586,-0.134891,0.067487,-0.214690,0.201748,0.088911,0.251653,0.005945,-0.044380,0.136798,-0.298966,-0.354120,-0.363596,-0.045839,-0.090129,-0.309695,-0.121522,-0.840470,0.170679,0.178612,-0.125655,0.034686,0.160464,-0.057143,0.281552,-0.704159,0.335684,0.613722,0.187742,-0.423251,0.135089,0.070725,0.321651,-0.354847,-0.230280,-0.088826,0.172942,0.418044,0.043443,0.334228,0.284668,-0.499079,0.018238,0.073807', '1292573', '3006781', '1298635', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401536', '机动战士高达 逆袭的夏亚', '剧情', '宇宙世紀(U.C.)0093年，成為新吉恩總帥的夏亚·阿兹纳布尔對於依然被地球重力所束縛的人類靈魂感到絕望，決心以激烈的手段加以肅正。查知此事的地球聯邦軍王牌駕駛阿姆罗·雷與其所屬的朗德·贝尔艦隊一起與夏亚所領導的新吉恩軍展開最後的決戰...', '古谷彻', '富野由悠季', 9.2, 7798, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p546980785.jpg', 0.5, 0.7, 6.7, 24.8, 67.2, '0.239261,0.315330,-0.586354,1.157542,0.018391,-0.171528,0.509920,0.026641,-0.684836,-0.475271,0.163944,0.855162,-0.051616,0.134984,0.447248,0.328785,-0.461834,-0.384695,-0.115191,0.116263,-0.326230,-0.786586,-0.521092,-0.131687,-0.437656,-0.436816,0.685704,0.043338,0.284627,-0.014255,-0.003934,0.667797,0.227360,0.463707,0.271829,-0.015005,0.008430,-0.263289,-0.248533,-0.178409,-0.219183,-0.066581,-0.115156,0.489326,-0.269162,-0.001039,0.358541,-0.376935,0.460773,-0.428241,0.718783,-0.145682,0.421335,-0.214335,0.550513,-0.192688,-0.280053,0.055614,-0.023060,0.049805,0.312721,0.228771,-0.997177,-0.186715,-0.048553,-0.230569,-0.097374,0.361418,-0.457432,-0.091368,-0.151911,-0.023041,-0.389557,0.729513,0.479280,0.181870,-0.701658,-0.009708,0.026025,-0.430741,0.247267,0.105775,-0.941287,-0.008023,-0.330795,-0.649679,-0.195964,-0.341217,-0.458128,-0.133064,0.682413,0.535604,0.172144,0.952143,-1.160697,-0.356989,-0.432054,-0.475933,0.050874,-0.091987,-0.076827,-1.026147,-0.280089,-0.733783,-0.224886,-0.442685,0.501434,-0.083425,0.499882,-0.796262,0.160183,0.614697,-0.068333,-0.203720,0.228423,-0.199008,0.365194,-0.096160,-0.233680,0.424264,0.034410,0.439579,0.265236,0.679433,0.452018,-0.008816,-0.196207,0.807681', '1293433', '1416898', '27163278', '10440138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401587', '绑架门口狗', '喜剧', '大学讲师元俊（李成宰 饰）因为不懂巴结上司而失去了晋升的机会，加上家中唠叨的妻子，都使他烦心不已。邻家的狗总是叫个不停，本来心烦意乱的他听到狗吠声后更加不耐烦了，竟然把人家的狗捉走了，藏在地牢里。邻居寻狗的启事第二天便张贴了出来。秘书千男（裴斗娜 饰）看到了这则启事后便加入了寻狗的行列。她十分厌倦平日办公室的工作，只想有上电视的机会。一次元俊又听到了狗吠声，当他到地牢一看时，他藏起来的那只狗不见了。©豆瓣', '李成宰', '奉俊昊', 7.5, 13024, 'tt0269743', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164398528.jpg', 0.4, 2.8, 31.9, 50.5, 14.4, '0.480157,-0.040614,-0.768578,0.598694,-0.114090,-0.563891,0.666694,0.342960,-0.495891,0.110396,-0.149109,0.453400,-0.384808,0.441704,0.115902,-0.014130,-0.353218,-0.512732,-0.207124,-0.430918,-0.282011,0.026566,-0.158823,-0.171863,-0.147955,-0.203317,0.071679,-0.097595,-0.177571,0.316233,0.276721,-0.045648,0.311738,0.714319,-0.265168,0.348294,0.162487,0.216107,0.415223,-0.225643,0.256639,-0.243335,-0.243466,0.076489,0.099351,0.220126,0.493734,-0.102012,-0.196565,-0.144785,0.383065,0.039241,0.040604,0.029141,0.354956,0.018950,0.252718,0.120554,-0.302408,0.091427,-0.049840,0.193226,-0.550649,0.303720,-0.197834,0.080990,-0.407034,0.341471,-0.109248,0.113046,0.102135,-0.504301,0.210974,0.215932,-0.081283,0.302989,-0.162988,0.040037,-0.807447,0.296526,0.379390,-0.103419,0.074501,0.578521,0.206013,-0.403730,0.334620,-0.010011,-0.359580,-0.356745,0.567650,-0.028939,-0.561827,-0.361424,-0.364329,-0.157106,-0.094899,-0.289715,-0.159116,-0.419979,-0.387642,-0.334357,-0.119583,-0.138384,-0.280245,0.295116,0.083548,-0.086466,0.619774,-0.672522,0.190538,0.454961,0.085034,-0.317248,0.730534,-0.206182,0.025420,-0.060038,0.128024,-0.161140,0.315303,0.753491,0.485153,0.301219,-0.189299,-0.485634,-0.357084,0.655538', '25728612', '35073565', '1298291', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401588', '法外之徒', '剧情', '在一个英语学习班上，法国姑娘奥迪尔（安娜·卡里娜 Anna Karina 饰）认识了两名男子阿瑟和弗朗茨，他们是两个着迷于美式文化的年轻人，向往着惊险的传奇故事。奥迪尔很快就被风流的阿瑟吸引，渐渐地爱上他，他们三人开始常常混在一起，坐在敞篷跑车里兜风。奥迪尔寄宿在一所豪华大宅里，她告诉弗朗茨，这所屋子里存放着巨额现金。阿瑟和弗朗茨便策划着要入屋行窃，后来奥迪尔想要退缩，然而阿瑟他们坚持要行动，并计划好了具体时间。到了那一天，事情却进行得并不顺利，奥迪尔一而再地要求他们取消行动，但是阿瑟表示明天再来，甚至动手打了奥迪尔。第二次的行动，会带来怎么样的灾难性后果？©豆瓣', '安娜·卡里娜', '让-吕克·戈达尔', 8.6, 22653, 'tt0057869', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2161319925.jpg', 0.3, 0.9, 10.7, 44.5, 43.5, '0.412077,0.389466,-0.689977,0.533020,0.144641,-0.211719,0.670902,-0.015847,-0.322494,-0.326491,0.117332,0.616570,0.128161,0.236543,0.367426,0.316790,-0.981317,-0.398041,0.246998,-0.188129,-0.335496,-0.556577,0.137899,-0.471830,0.227748,-0.020265,0.101602,0.147006,-0.035655,0.703342,0.201770,-0.239873,0.013149,0.499650,0.016056,-0.085454,0.235130,-0.214485,-0.133270,0.040023,0.111288,-0.401990,-0.179267,0.005560,0.414285,0.144188,0.586487,-0.207226,0.031214,0.001472,-0.121112,-0.389726,0.179150,0.116263,-0.119675,-0.089921,0.424548,0.306493,-0.153922,0.200101,0.002210,-0.231972,-0.443103,0.271986,-0.441470,0.245050,-0.473225,0.441295,-0.483851,0.068310,-0.137986,-0.293748,-0.150531,0.101124,0.189208,0.220522,-0.010767,-0.092944,-0.829164,-0.187699,0.874378,-0.046874,-0.099673,0.227974,0.094168,-0.464324,-0.228998,-0.102411,-0.562378,-0.037839,0.540701,-0.063129,-0.070203,0.116221,-0.572589,-0.144638,-0.210743,-0.158941,-0.097628,-0.197124,0.038586,-0.585157,0.207517,-0.297624,-0.517609,0.291341,-0.125689,-0.068583,0.456945,-0.657114,0.111468,0.448974,0.634282,-0.506166,0.634816,-0.101826,0.179876,-0.078978,-0.222770,0.010269,-0.187694,0.253617,0.467518,0.574240,0.203826,-0.162702,-0.179535,0.461732', '3055049', '1296538', '2079017', '27053945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401600', '小美人鱼2：重返大海', '动画', '美人鱼爱丽儿和王子埃里克结婚后过着幸福美满的生活，不久，两人的女儿麦乐迪也出生了。小家伙天性调皮，和妈妈正好相反的是，她一直向往着海底绚丽多彩的世界，爱丽儿也一直没有告诉她自己的身世。上一集企图加害爱丽儿的巫婆的妹妹莫嘎纳为了帮姐姐报仇，骗麦乐迪说能帮她变成美人鱼，乐不可支的麦乐迪就这样跟着莫嘎纳前往了海底。丢失了爱女的爱丽儿和埃里克异常焦急，为了寻找爱女下落，爱丽儿决定重回大海。©豆瓣', '裘蒂·班森 Jodi Benson/爱丽儿', 'Jim Kammerud', 7.4, 10809, 'tt0240684', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1839966699.jpg', 0.6, 4.5, 37.1, 37.9, 19.8, '0.047839,-0.093983,-0.779216,0.771950,-0.352146,-0.422032,0.770519,-0.060443,-0.620614,-0.036661,-0.177609,0.793443,0.078747,0.436478,0.108616,0.531865,-0.624174,-0.438417,-0.081176,-0.093637,-0.124589,-0.507187,-0.209515,-0.026647,0.120926,-0.229345,0.582833,-0.206768,0.051444,0.615276,0.261654,0.022353,-0.160271,0.613497,-0.443301,0.097580,-0.469530,0.293239,-0.252701,0.245228,0.308777,-0.046495,-0.000348,0.205781,0.124898,0.250704,0.550967,-0.430761,0.074316,-0.196958,0.121674,-0.444062,0.252967,0.170692,0.240212,-0.279182,0.496479,0.111036,-0.260201,-0.258714,0.177575,-0.352109,-0.650353,0.086246,0.212669,0.129997,-0.750355,0.152346,-0.036443,-0.234248,0.550110,-0.473396,0.518395,0.538233,0.055069,0.484765,-0.429603,-0.040509,-0.644713,0.227247,0.699095,-0.074763,0.249143,0.292006,0.096509,-0.191484,0.181170,-0.160062,-0.683113,0.064314,0.285252,0.224211,-0.539851,0.250591,-0.453970,0.075758,-0.278713,-0.230818,0.073852,-0.721366,-0.012179,0.024310,-0.018455,-0.352668,-0.118897,-0.124085,-0.158012,-0.489932,0.745687,-0.960644,0.380160,0.507283,0.691000,-0.651589,0.867994,0.239144,0.049862,-0.402088,0.082123,0.242451,-0.232117,0.240608,0.104074,0.195914,0.276478,0.105924,-0.400093,0.476780', '1302384', '2990737', '1308637', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401603', '星际宝贝史迪奇', '喜剧', '本片剧情接续原本电影，叙述在史迪奇这“626号实验品”之前，强霸博士已有好几百个失败实验产物，如今强霸居然把这些实验产物全都偷偷走私到地球。心怀不轨的越狱者仓鼠飞轮和被开除而怀恨在心的刚图舰长联手，绑架了强霸博士，并且要去寻回之前的625个实验品，再次创造出全新的小魔星?这些希奇古怪的星际宝贝实验品包括有能发出强力电波的第221号实验品、懒惰却能做出美味三明治的第625号实验品等等。如今，夏威夷七岁小女孩Lilo（莉萝）和星际宝贝Stitch（史迪奇）要协助星际联盟，在夏威夷群岛做地毯式搜索，抢在坏蛋之前找到625个实验品，并且还要帮这些星际宝贝都找到各自温暖的家！', '黛维·切斯', '托尼·克莱格', 8.7, 10670, 'tt0348124', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239563445.jpg', 0.2, 0.6, 11, 41.3, 47, '0.100933,0.118089,-0.574586,0.526188,-0.041716,-0.332942,0.304270,-0.272164,-0.305066,-0.128947,0.026842,0.336051,0.050576,0.181173,0.029896,0.195564,-0.313401,-0.269420,-0.145069,-0.417937,-0.468391,-0.318179,-0.366127,0.025792,0.054703,-0.330424,0.567720,-0.263665,-0.195035,-0.090766,0.353426,0.194957,-0.117836,-0.021839,-0.489097,-0.050009,0.214243,0.078942,-0.450396,0.449004,-0.152805,0.166195,0.179744,-0.078786,0.025211,0.116213,0.852181,-0.343859,0.011646,-0.358603,0.375055,-0.161644,-0.215472,-0.039252,0.402128,0.218046,-0.053839,0.016526,0.078722,0.172399,0.177236,-0.027275,-0.922126,-0.290031,0.034378,-0.114156,-0.308756,-0.211533,-0.249163,0.438260,0.172478,-0.227630,0.420777,0.457639,0.257510,0.370104,-0.060447,0.421099,-0.548633,0.207331,0.335435,-0.047700,-0.144198,0.116336,0.175161,-0.416679,0.281774,-0.602068,-0.132201,0.285166,0.341948,-0.128604,-0.218600,0.411075,-0.962402,0.000568,-0.162343,-0.293745,0.412440,-0.246492,-0.186239,-0.750310,0.097239,0.226217,0.074327,0.321364,0.260845,-0.239588,0.737255,-0.515992,0.331362,0.775696,0.003500,-0.524153,0.226199,0.111320,-0.003486,-0.339561,-0.031187,-0.241868,0.362399,0.870252,0.035212,0.279046,0.365617,-0.447882,-0.475763,-0.048109', '7155241', '26290398', '1292680', '1308248');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401604', '狮子王3', '喜剧', '该片是狮子王的外传，讲述了狮子王辛巴不为人知的成长历程。当年辛巴的父亲木法沙被奸人迫害而死，小辛巴为了躲过一劫，逃离了动物王国。在逃亡过程中，辛巴遇上了一对搞笑活宝——丁满和彭彭。丁满和彭彭与辛巴成了好朋友，他们在丛林中开始了他们惬意的生活。辛巴在丛林中慢慢长大，最终长成了雄壮的雄狮，并邂逅了自己美丽的公主。由于有了丁满和彭彭这对活宝，使得平凡的生活也笑料百出。©豆瓣', '内森·连恩', '布拉德利·雷蒙德', 8, 34553, 'tt0318403', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2024090266.jpg', 0.5, 2.3, 23.5, 46.3, 27.4, '0.152894,-0.194258,-0.553614,0.634692,0.108014,0.049806,0.902577,0.163116,-0.731237,-0.173494,-0.166315,0.637455,-0.279993,0.491217,0.282046,-0.282543,-0.125326,-0.561562,-0.041910,0.147884,-0.208997,-0.242893,-0.210170,-0.595113,-0.115636,-0.157346,0.414226,0.298086,-0.251113,0.662317,0.359086,0.208365,-0.349351,0.524111,-0.434986,0.632675,0.027681,0.291158,-0.017901,-0.191048,0.161941,-0.551642,0.291402,0.065861,0.330721,0.152594,0.601578,-0.545770,-0.186473,-0.321735,0.166883,-0.282157,0.228982,0.153264,0.409636,-0.396816,0.193504,-0.011891,0.046318,-0.118328,0.027291,-0.397883,-0.716136,0.103451,-0.101743,-0.220591,-0.951351,0.552321,0.383951,0.099162,0.442351,-0.177918,0.446277,0.591980,0.501648,0.288306,0.104946,0.145979,-0.698283,0.364980,0.698275,0.121942,-0.304405,0.170180,-0.241842,-0.818545,-0.432456,-0.248816,-0.280040,-0.166046,0.850461,0.109923,-0.474640,0.119978,-0.597760,0.039737,0.005798,-0.160142,-0.153897,-0.679572,-0.178794,-0.469068,-0.094173,-1.152601,-0.206702,0.091246,-0.390641,-0.576570,0.757077,-0.961595,0.040898,0.460587,0.092514,-0.523566,0.634743,-0.062402,0.172446,-0.173642,0.298061,0.395099,0.264666,0.156091,0.761873,0.408188,-0.255082,0.376839,-0.398895,0.493616', '26354526', '7065238', '1438708', '1301516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401618', '乡村牧师日记', '剧情', '一个青年牧师在日记中向上帝袒露心声。年轻的牧师（Claude Laydu 饰）初到村庄，感受到这里的寒冷和孤苦，他怀着一腔热忱，希望用自己的力量教化众生，令人们更加虔诚，但和村人接触之下他才发现，他们浅薄、功利，有的村民连妻子葬礼都不肯花钱，大多数人根本不关心自己的灵魂是否被拯救，反倒质疑他的献身精神。唯有一位伯爵夫人，因为难以纾解丧子之痛，找来牧师长谈，从而得到开解。但在村子的大环境下，他仍时时感到徒劳无功，他自己的迷茫和痛苦连上帝都解救不了。长期抑郁之下，牧师渐渐吃不下东西，最后发现自己得了胃癌，终于孤独地死去。©豆瓣', '克罗德·莱杜', '罗伯特·布列松', 8.2, 8496, 'tt0042619', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2206687140.jpg', 0.5, 1.5, 18.9, 45.6, 33.4, '-0.053217,0.017352,-0.809102,0.500631,-0.254182,-0.266668,0.678114,0.017553,-0.631549,-0.303752,0.295547,0.775975,0.027817,0.441041,-0.068529,-0.001805,-0.215833,-0.437569,-0.091295,0.202287,-0.311239,-0.255467,-0.208214,-0.400757,-0.425253,-0.404268,0.578057,0.406854,-0.057080,-0.012143,0.167634,0.416668,0.251852,0.788573,-0.153369,-0.169073,-0.082203,-0.037723,-0.004058,-0.088971,0.211056,-0.330131,-0.308440,0.561416,-0.353397,0.390164,0.464108,-0.264778,-0.339656,-0.072518,0.441769,-0.089102,0.161336,0.271670,-0.146770,-0.217299,0.203692,-0.017662,0.023096,-0.006964,0.033501,0.281465,-0.763667,0.061936,0.207144,0.155519,-0.517684,0.521035,0.056766,-0.087119,0.007952,-0.279891,0.139707,0.058236,0.057056,0.528817,-0.526906,-0.211389,-0.380286,0.283972,0.746027,-0.006567,-0.448904,0.285978,-0.727694,-0.433603,0.135135,-0.465960,-0.789959,-0.004807,0.009127,0.597822,-0.416831,0.249081,-0.436729,0.008026,-0.129647,-0.264229,-0.104165,-0.425378,-0.000701,-0.380702,-0.172404,-0.261635,-0.402074,-0.039764,0.282274,-0.295065,0.870444,-0.659788,0.319480,0.574199,0.286472,-0.477074,0.748817,0.050568,-0.167623,-0.000030,-0.250218,0.642267,-0.121806,0.376213,0.486411,0.032751,-0.323345,0.294445,-0.275306,0.465800', '25882279', '3504940', '26348103', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401619', '驴子巴特萨', '剧情', '电影史上极其异类的电影.全片的主角竟是一头驴。透过驴的眼睛，冷冷地注视着这个世界。驴在不同人的手中被虐待、被贩卖，最终被杀，透露出来的却是同样的主题。', '安妮·维亚泽姆斯基', '罗伯特·布列松', 8.4, 7249, 'tt0060138', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1370491619.jpg', 0.5, 1.5, 15.4, 44.8, 37.8, '0.644421,0.252923,-0.716921,1.006622,0.031361,-0.089424,1.039603,0.086138,-0.345079,0.173007,0.461963,0.718025,-0.561672,0.221345,0.567851,0.023596,0.073411,-0.426042,-0.694410,-0.152815,-0.222787,-0.448505,-0.545968,0.711257,-0.008538,0.165289,0.890733,-0.093408,-0.620774,0.495617,0.547229,0.379202,0.220979,0.265081,-0.454602,0.151427,-0.301475,-0.497417,0.626867,-0.009414,0.161345,-0.378374,0.081271,0.135411,-0.786345,0.068777,1.074068,-0.644050,0.065251,-0.289982,0.696916,-0.299588,-0.101588,0.403572,0.358834,0.008595,0.273263,0.099529,0.159840,0.042919,0.475811,0.079703,-0.965676,-0.053274,-0.033311,0.559960,-0.707478,0.621876,0.254254,0.135314,-0.128605,0.174233,0.416224,-0.406133,0.353402,0.920883,-0.239832,0.124278,-0.706441,0.054001,0.103467,0.100219,-0.170810,0.308427,-0.268490,-0.514998,-0.228275,-0.630113,-0.344386,-0.095599,0.909147,-0.066305,-0.928920,0.119723,-0.377150,-0.057611,0.072514,-0.498464,-0.163085,-0.546573,-0.504415,-0.572893,-0.111334,-0.579759,-0.236205,0.386035,0.111474,-0.013491,0.358940,-0.453826,-0.083293,0.560809,-0.036861,0.290138,0.875163,-0.250327,-0.082765,0.007053,-0.570581,0.093553,0.892854,0.380677,0.281311,0.627269,0.000058,0.011000,-0.458527,0.721104', '21619567', '1467779', '1294434', '26369884');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401842', '麦秋', '剧情', '上了岁数的植物学家间宫周吉（菅井一郎 饰）及其家人住在北镰仓一带，长子康一（笠智衆 饰）是东京某医院的医生，女儿纪子（原节子 饰）在东京丸内贸易公司供职，担任经理佐竹宗太郎（佐野周二 饰）的秘书。年轻貌美、落落大方的纪子已到适婚年龄，周围的好友也都相继成家，她却依旧待字闺中。父母兄长为了纪子的婚事各自用心，佐竹经理亦将出身名门的前辈真锅介绍给她。但是，纪子却独独倾心哥哥的同事矢部谦吉（二本柳寛 饰）——一个丧偶带着三岁女儿且捉襟见肘的男子……本片荣获1952年蓝丝带最佳女主角（原节子）、最佳摄影、最佳导演和最佳女配角（杉村春子）等四项大奖；1952年电影旬报最佳影片；1952年每日电影最佳女主角和最佳影片。©豆瓣', '原节子', '小津安二郎', 8.7, 11278, 'tt0043313', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2556753059.jpg', 1, 0.6, 7.5, 43.8, 47.2, '-0.180803,-0.230313,-0.049340,0.589605,0.144075,-0.392519,0.248328,0.486941,-0.506475,-0.536807,0.311834,0.614409,-0.034836,0.332305,0.335340,0.190647,-0.262787,-0.576698,-0.270173,-0.079439,0.101603,-0.291347,0.093619,0.108392,-0.278834,-0.039287,0.705247,-0.260262,0.473288,0.643183,0.413402,-0.115006,-0.241363,0.033889,0.206450,0.329234,0.276856,-0.061657,-0.426354,0.486298,-0.200309,-0.338363,-0.162924,-0.058010,0.468497,0.409649,0.680787,0.047135,0.117358,-0.098469,0.444737,-0.072925,-0.057221,0.307686,0.409562,-0.130761,0.452853,0.194013,-0.334807,0.000599,0.044926,-0.197535,-0.348645,0.106412,0.410612,0.028077,-0.434235,0.514488,-0.226057,0.010001,0.002903,-0.217089,0.042410,0.104626,0.047640,0.082887,-0.376805,0.243567,0.048428,0.578605,0.111281,0.072969,0.000229,0.109837,-0.140110,-0.676378,-0.186083,-0.217544,-0.566930,0.014115,0.097476,0.030065,0.166529,-0.190361,-0.111688,-0.056438,0.047217,0.061007,0.392256,-0.098135,0.075768,-0.587212,0.246044,-0.475145,-0.169776,-0.001523,0.373511,-0.093500,0.850356,-0.455976,-0.128524,0.294473,0.208246,-0.259513,0.724401,0.011920,-0.045134,-0.409883,-0.253535,-0.020609,-0.162957,0.304408,0.086866,0.333620,-0.180754,-0.385732,-0.223387,-0.141160', '3811356', '2338019', '1908036', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401843', '秋日和', '剧情', '平凡的人家，正在为去世的男主人三轮举行七周年忌。三轮生前的好友间宫宗一（佐分利信 饰）、田口秀三（中村伸郎 饰）平山精一郎（北龙二 饰）如期而至，回首往事自是唏嘘不已。未亡人秋子（原节子 饰）独自拉扯女儿文子（司叶子 饰）长大。而如今女儿已到了适婚年龄，秋子拜托间宫等人 帮文子张罗对象。经间宫介绍，文子认识了其部下后藤庄太郎（佐田啓二 饰）。可是她担心婚后母亲孤苦伶仃，无论如何也不能下定决心独自寻找幸福。也许该忘记过去向前走一步，也许该为了女儿和自己的幸福尽力去争取。长久思念着亡夫的秋子，沉湎在往日的幸福中苦守寂寞……©豆瓣', '原节子', '小津安二郎', 8.4, 7454, 'tt0053579', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2310251305.jpg', 1.2, 0.9, 10.8, 51.5, 35.6, '-0.364765,0.082541,-0.319696,0.074575,0.067945,-0.426058,0.336604,0.316709,-0.337911,-0.479502,0.032254,0.319704,0.226732,0.506073,0.359661,0.059043,-0.095875,-0.234178,0.049134,-0.051388,0.047008,-0.094597,0.212962,-0.276669,-0.285072,0.114244,0.399394,0.265122,0.402880,0.397125,0.375034,0.221928,-0.274879,0.079703,0.067250,0.191887,-0.216108,0.221143,-0.364432,-0.109428,-0.211694,-0.085904,-0.062143,0.027086,0.236795,0.044249,0.604504,0.032643,-0.054657,-0.339858,0.248908,0.064338,0.001562,0.392538,0.150264,-0.005108,0.136397,0.200419,-0.243456,-0.150945,0.085175,-0.048758,-0.420084,0.173478,0.263809,-0.104142,-0.639821,0.152423,-0.227428,-0.313026,0.406527,-0.354179,0.109002,0.523503,0.248079,0.178662,-0.389959,0.142288,0.058521,0.523151,0.595773,-0.053203,0.252960,0.023429,0.161481,-0.138883,0.066986,-0.134331,-0.567901,-0.082853,0.068877,0.270518,-0.015145,0.055660,0.090932,-0.216892,-0.132056,0.004501,0.333824,-0.464575,0.037827,-0.169474,0.152800,-0.422968,-0.333001,0.145781,0.132840,-0.349933,0.411953,-0.402904,0.460215,0.305269,0.124531,-0.534309,0.327963,0.369380,0.174487,-0.426315,0.127449,0.402385,-0.177614,0.067326,0.124637,-0.072690,-0.197618,0.176616,-0.346293,-0.038661', '1308035', '24879820', '1877596', '1297606');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401894', '天堂孤影', '喜剧', '环卫公司垃圾车驾驶员尼卡德（Matti Pellonpää 饰）的老同事计划筹资组建自己的环卫公司，邀请尼卡德技术入股，但老同事不久急病突发身亡，尼卡德的生活重回一潭死水状态。尼卡德心有不甘借酒滋事，在被拘留的时候结识日后的同事米卡拉。米卡拉偶而会不识趣的妨碍尼卡德暗地追求超市售货员伊罗娜（Kati Outinen 饰），但他仍是尼卡德最可依赖的朋友。伊罗娜为报复超市经理偷走了钱盒，尼卡德帮助她找到服装店的新工作，服装店经理夹到尼卡德与伊罗娜的关系中间，但尼卡德最终夺回了自己的爱人。本片获1987年芬兰电影尤西奖最佳影片奖。是导演郭立斯马基（Aki Kaurismäki）无产阶级三部曲的第一部。©豆瓣', '马蒂·佩龙帕', '阿基·考里斯马基', 8.2, 6238, 'tt0092149', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2276728353.jpg', 0.2, 0.6, 15.8, 57.2, 26.2, '0.332172,-0.115959,-0.485056,0.280616,0.355404,-0.605968,0.230692,0.659654,-0.076060,-0.407661,0.162339,0.450042,0.015273,0.095631,0.441519,-0.002133,-0.413497,-0.185727,0.390247,-0.266588,-0.108068,-0.790539,-0.163855,-0.445596,-0.282699,-0.432821,0.422668,-0.047903,0.020970,0.363536,0.332996,0.443937,0.354274,0.317747,0.197402,0.041608,0.630033,-0.615552,-0.604498,0.252072,0.282999,-0.085380,-0.230962,0.184068,0.329888,0.484922,0.380226,-0.087117,0.254635,-0.040562,0.026594,-0.026821,0.227065,-0.348303,0.246156,-0.294832,0.035881,0.397852,-0.452586,-0.032977,0.155813,-0.260923,-0.335435,-0.172501,0.224233,0.067241,-0.445327,-0.003351,-0.360485,0.580735,0.077069,0.067270,-0.077091,0.326917,0.427075,0.208917,0.174444,0.095845,-0.733684,-0.052393,0.351905,-0.255267,-0.294303,0.507221,-0.486742,-0.154952,-0.070009,-0.191407,-0.765782,-0.030479,0.172160,-0.230319,0.049055,0.371481,-0.598292,-0.280742,-0.438286,0.052506,0.393985,-0.080876,0.034609,-0.664631,-0.029950,0.182574,-0.326914,-0.287958,-0.082535,-0.047192,0.538388,-0.469559,0.030096,0.593087,0.247797,-0.172017,0.823472,-0.292065,0.026599,-0.142905,-0.332988,0.308070,0.425703,0.176579,0.210828,0.068603,0.256866,-0.340373,-0.189574,0.263257', '3183490', '1302271', '1293656', '3006781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401900', '蜂巢幽灵', '剧情', '1940年，一辆放映车驶入卡斯蒂利亚高原的某个村子，孩子们马上围拢了上去。放映的电影是《科学怪人》，座位上有女童安娜（Ana Torrent 饰）和她的小姐姐伊莎贝尔（Isabel Tellería 饰）。放映室外，父亲痴迷于自己的新蜂房，他掏出怀表，结束了今天的工作。母亲正在写一封信，尽管对方收到信的可能渺茫，母亲在信纸上倾诉思念之情，在火车站将信投递。安娜久久不能忘记科学怪人，伊莎贝尔向她虚构出荒原上一座孤立的砖房是怪人的出没之地。安娜惊慌逃开，但从此不时返回砖房查看。伊莎贝尔似乎洞悉了某种秘密，她装死、跳过火堆，诸如此类。不久一名受伤军人躲进砖房被安娜发现，当晚军人中枪死亡。父亲来到村公所拿走军人的物品，包括一只怀表。安娜独自一个跑出村子，夜里她在湖边遇到了科学怪人……本片获1973年圣塞巴斯蒂安国际电影节金贝壳奖等多项褒奖。©豆瓣', '费尔南多·费尔南·戈麦斯', '维克多·艾里斯', 8.5, 7889, 'tt0070040', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p680070993.jpg', 0.5, 1.8, 12.3, 41.2, 44.2, '0.433761,0.203839,-0.504684,0.228030,0.091370,0.021963,0.782010,-0.132932,-0.411069,-0.044180,0.438483,0.629720,-0.076509,0.267440,0.007189,0.157552,-0.501602,-0.515709,-0.019831,-0.367540,-0.381572,-0.338778,-0.251347,-0.105885,-0.010283,-0.237060,0.397534,0.004246,-0.054996,0.397287,0.173098,-0.098350,-0.280928,0.250430,-0.104910,0.130506,0.036962,-0.036022,-0.023734,0.155319,-0.106373,-0.218702,-0.168784,-0.007362,0.071346,0.162483,0.841879,-0.121528,-0.004237,0.087130,0.499072,-0.002810,-0.015703,-0.026522,0.207362,0.092430,-0.183017,-0.051364,-0.042116,0.098910,0.007477,-0.024242,0.003535,0.051730,-0.153282,0.409557,-0.494405,0.346432,-0.230811,0.074159,-0.022484,-0.544590,0.146131,-0.026346,0.032444,0.490965,-0.007528,0.107370,-0.549221,0.149607,0.165748,-0.152816,-0.029689,0.127375,-0.180971,-0.411891,-0.020456,0.162580,-0.430586,-0.055715,0.646671,-0.130275,-0.269586,-0.200745,-0.435282,0.009655,-0.274301,-0.298708,0.166156,-0.144482,-0.371689,-0.604788,0.231671,0.012671,-0.193404,-0.072279,-0.029374,-0.093326,0.564238,-0.348390,0.353551,0.449840,0.224014,-0.117218,0.718276,-0.339888,-0.055819,-0.176328,0.154839,0.516096,0.132494,0.464207,0.055158,0.169847,-0.179149,-0.024597,-0.382607,0.200295', '21619567', '1467779', '10466639', '1309194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401904', '鼹鼠', '西部', '神秘莫测、枪法绝伦的独行杀手“鼹鼠”（亚历桑德罗•佐杜洛夫斯基 Alejandro Jodorowsky 饰）和他年仅7岁、赤身裸体的儿子（布朗提斯•佐杜洛夫斯基 Brontis Jodorowsky 饰）骑马漫步在墨西哥炎热的沙漠之中。他们路过一个被匪徒“上校”及其爪牙血洗过的村庄，鼹鼠按照垂死村民提供的线索一路追踪，将上校一伙一网打尽。在此之后，他将儿子留在一座寺院，带着他解救的女人继续踏上旅途。女人向鼹鼠讲述了四大高手的传说，这个好胜心切的男人向四大高手发起挑战，他凭借高超的枪法和精巧的计谋一次次得逞，却也在这一过程中若有所悟。本片荣获1972年墨西哥金羊奖最佳摄影奖、1974年意大利阿索罗美术和美术家电影节评委会特别奖。©豆瓣', '亚历桑德罗·佐杜洛夫斯基', '亚历桑德罗·佐杜洛夫斯基', 8.2, 6644, 'tt0067866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p559758975.jpg', 1.1, 2.9, 16.6, 43.9, 35.5, '-0.019998,-0.456102,-0.501698,0.718223,-0.084350,-0.027592,0.565150,-0.103648,-0.636215,-0.122453,0.318661,0.783980,-0.080550,-0.162022,0.492984,-0.143197,-0.319058,-0.497397,-0.120153,-0.291052,-0.205422,-0.274761,-0.373649,-0.251443,0.056223,-0.537187,0.632124,0.044342,-0.256584,0.564967,0.192960,0.073729,-0.221635,0.127804,-0.254538,0.110504,0.189998,-0.230020,-0.216198,0.572809,-0.280324,-0.340080,-0.414587,-0.061420,-0.192426,0.343233,0.685687,-0.251788,0.202709,-0.088187,-0.037079,-0.419044,-0.048100,0.020384,0.358043,-0.347985,-0.050373,0.319508,0.073787,-0.050772,-0.037915,-0.253629,-0.677119,0.023912,0.098463,0.046680,-0.703085,0.330493,-0.102284,0.249809,-0.106967,-0.393896,-0.048986,0.096204,0.139453,0.167490,0.033623,-0.008047,-0.664674,0.207001,0.352965,-0.038748,-0.011739,0.056259,0.014336,-0.499016,-0.117190,-0.440116,-0.382011,-0.082788,0.499536,-0.203663,-0.014850,0.123183,-0.563333,-0.013404,-0.071128,-0.208632,-0.085990,-0.293406,-0.197076,-0.434639,0.226194,-0.175926,-0.323505,0.138585,0.055389,-0.198983,0.737286,-0.563071,0.287343,0.675038,0.279571,-0.031898,0.809591,-0.267206,0.114696,-0.175252,-0.384468,0.368388,0.373876,0.214675,0.139714,0.687397,-0.220627,-0.272449,-0.158491,0.170180', '1414808', '1302661', '1292925', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401905', '圣山', '奇幻', '一位貌似耶稣的小偷（Horácio Salinas 饰）从儿童们的石块击打中醒来，与一个无手无脚的侏儒结伴进入城市。城中正进行一场疯狂的庆典，一些人被杀死，鸟雀从他们的枪口中飞出，大量蟾蜍穿着印第安人以及欧洲殖民者的服装在混战中被炸的粉碎。小偷从几个罗马士兵打扮的人手中接过十字架，又被他们将自身的形象制造成无数模型……小偷在众目睽睽下爬上了一座能生产黄金的高塔，塔内的术士从小偷的粪便中提炼出了金子。术士用占星术确认了几位门徒，他们是生产面具的商人、武器商、艺术家、玩具商、政府顾问、军队长官和建筑师，七人分别代表不同的行星。术士把这些掌控国家的人物积聚一起，抛弃一切之后向传说中的圣山进发寻找不朽的秘密。©豆瓣', '亚历桑德罗·佐杜洛夫斯基', '亚历桑德罗·佐杜洛夫斯基', 8.7, 19491, 'tt0071615', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171940379.jpg', 1.2, 1.9, 11.1, 32.1, 53.7, '0.450587,-0.126526,-0.389305,0.532501,-0.286021,0.119385,0.821101,-0.123768,-0.323678,-0.102554,0.512910,0.905335,-0.271219,0.105311,0.116631,-0.033736,-0.182557,-0.760603,-0.396219,-0.219098,-0.573679,-0.146558,-0.386716,-0.230505,-0.273699,-0.299340,0.860621,0.117037,-0.231371,0.158409,0.076188,0.197851,-0.405594,0.131427,-0.397081,-0.247952,0.140427,-0.207856,0.048088,0.281437,-0.534175,-0.335098,0.131601,0.033013,-0.167324,0.255367,0.902728,-0.593016,0.489476,-0.392606,0.223823,-0.186165,0.020045,0.342723,0.364912,0.251259,-0.076277,-0.087773,-0.011238,0.070652,0.282260,-0.220165,-0.609987,-0.291474,0.115598,0.209822,-0.837212,0.430273,0.122025,0.033788,-0.002475,-0.243032,0.511063,0.127217,0.017434,0.490068,-0.057738,-0.206329,-0.816807,0.304100,0.324640,-0.186237,-0.342088,-0.064591,-0.136307,-0.567073,-0.121378,-0.098563,-0.150932,-0.388777,0.635434,-0.160195,-0.064462,0.153531,-1.060097,0.130387,-0.217998,-0.460998,-0.100697,-0.083128,-0.313580,-0.735964,0.132960,-0.221672,-0.009701,0.112518,0.206145,0.055168,0.908960,-0.506806,-0.017822,0.405541,0.342692,-0.103979,0.557994,-0.515762,0.224051,-0.107456,-0.226823,-0.101666,0.483593,0.566852,0.201821,0.604843,-0.182214,-0.108604,-0.217879,0.286315', '26290398', '21619567', '1294917', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401915', '红圈', '剧情', '由马迪警督押送的嫌疑犯威高（吉昂•马利亚•沃隆特 Gian Maria Volonté 饰）从火车上逃跑，马迪马上联络总部在各处设置路障，并且出动警力大力搜捕威高。科里（阿兰•德龙 Alain Delon 饰）提前从监狱里被释放，当晚找到了昔日旧友里克敲诈得到了钱和枪，随后买了车离开此地。威高死里逃生巧合之下躲进了科里的后备箱里。科里经过路障检查时帮助威高蒙混过关，两人就此结识。他们途中被劫匪抢劫，两人相互配合杀死了劫匪。马迪警官判断威高逃跑会投靠酒吧店主桑提，于是找到桑提要求他当线人并提供线索，桑提拒绝后被拘留。而此时威高和科里找到了被革职的警察简森（伊夫•蒙当 Yves Montand 饰），三人合谋计划一次珠宝抢劫案……©豆瓣', '阿兰·德龙', '让-皮埃尔·梅尔维尔', 8.3, 9992, 'tt0065531', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554599861.jpg', 0.4, 1.5, 15.1, 49.2, 33.8, '0.389024,-0.123686,-0.473353,0.013157,0.139418,-0.265661,0.414603,0.119291,-0.548420,-0.011708,0.264690,0.478186,-0.181164,0.031847,0.508676,0.044850,-0.704515,-0.660062,0.227032,-0.189894,-0.455201,-0.484917,-0.143970,-0.389034,0.077993,-0.161194,-0.016776,0.212080,-0.029713,0.680962,0.018260,0.206349,-0.272838,0.398098,-0.059753,0.202044,0.421428,-0.377912,-0.187475,0.522335,-0.048730,-0.281291,-0.023282,-0.152840,0.288204,0.577217,0.428729,-0.003056,0.076996,-0.117369,-0.241791,-0.259237,0.092096,0.044824,0.201209,0.302775,0.094893,0.420676,-0.445023,0.058762,0.166449,0.113232,-0.371725,0.082548,-0.206907,-0.218661,-0.616068,-0.067667,-0.157303,0.383176,0.090161,-0.196750,0.297766,0.249106,0.243632,-0.184228,0.209831,-0.183168,-0.740724,-0.046643,0.399521,-0.461316,0.176548,0.012485,0.149070,-0.306861,0.233857,0.044128,0.138568,-0.006240,0.653191,0.081840,0.001351,-0.220141,-0.440165,-0.263476,-0.709621,0.223452,-0.204114,-0.066237,-0.175958,-0.770330,0.069588,0.407484,-0.357817,0.123050,-0.122798,0.077522,0.136613,-0.450801,0.048097,0.369046,0.579185,-0.392777,0.408231,-0.408615,0.166881,-0.025757,0.158747,-0.204156,0.567091,0.706989,0.313891,0.288940,-0.367113,-0.391430,-0.140655,-0.083043', '1292214', '1297659', '1292699', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401962', '刀', '剧情', '炼锋号铸刀厂大弟子定安（赵文卓饰）被师父选为继承人，后来他知晓了父亲乃惨死于马贼恶汉飞龙（熊欣欣饰）刀下，大殿供奉的断刀正是亡父的遗物。定安带断刀出走，师父女儿向灵（桑妮饰）为爱而追寻，却被马贼所掳，定安舍身相救时竟不幸右手被斩堕下山崖。断手后定安自思报仇无望，本想就此退隐江湖，不料又拾得半本绝世刀谱，于是决心秘密练刀为父报仇。可又因刀谱残缺无法练成，最后定安苦思之后自创独臂断刀刀法，他能否救得了危难中的炼锋号并手刃杀父仇人飞龙？©豆瓣', '赵文卓', '徐克', 8.1, 41215, 'tt0112800', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165557623.jpg', 0.5, 2, 19.5, 48.7, 29.2, '-0.363567,-0.127252,-0.179250,0.180947,0.116169,-0.485597,0.121700,0.141470,-0.396932,-0.175702,0.550817,0.613467,0.447098,0.175093,0.007209,0.119787,0.329978,-0.734679,0.225191,-0.226755,-0.127404,-0.133403,-0.129092,0.053060,-0.180407,-0.045125,0.475176,0.154239,0.144491,0.312382,0.384313,0.442372,-0.148510,0.110644,-0.526388,0.006884,-0.243080,-0.159142,-0.222327,-0.007333,-0.184424,-0.482258,-0.054334,0.376401,-0.447223,0.302664,0.497120,-0.243254,0.356077,-0.559145,0.091845,0.116402,0.027554,0.041952,0.175643,0.130796,0.051475,0.467675,-0.137614,-0.227883,0.035582,-0.159328,-0.692870,0.066505,0.167100,-0.269547,-0.680833,0.367575,-0.407943,0.040073,-0.250664,-0.201129,0.097130,-0.183536,0.365564,-0.150895,-0.302347,-0.301425,-0.283262,0.337029,0.399724,-0.403365,0.403205,0.063093,0.581283,-0.086743,0.330714,-0.647993,0.011933,0.052995,0.684706,0.317212,-0.241237,0.366481,-0.014603,-0.107454,-0.828254,0.576654,-0.183886,0.005024,-0.354922,0.242156,0.147908,0.409233,-0.045166,-0.288512,0.195515,-0.010483,0.578547,-0.522398,0.249908,0.092113,-0.081291,-0.511483,0.461656,0.249837,0.136458,0.032565,0.047421,0.160254,0.256822,0.584489,0.250493,-0.273592,0.034891,-0.239176,-0.479743,0.183597', '1297979', '35489675', '26635323', '24756658');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1401966', '九人禁闭室', '剧情', '9个表面上毫不相关的陌生人被绑架到一间房子里。一个神父，一个警察，一个舞蹈演员，还有作曲家和他的妻子，一个时装设计师，一个网球明星，一个犯人，还有一个黑人。无奈之下展开了一场相互残杀的赌命游戏：9个人被抓到了一间封闭而没有出口的屋子里，并被告知：愿与不愿都要互相展开一场人性游戏大战。唯一活着的人，就能走出这间屋子，并能获得500万美金的奖励，但也意味着要杀死其他的8个人，于是在绝望和希望并存中开始了一系列人性的大暴露。在金钱与利益面前，人，总是把持不住。当最后一人以为游戏结束，带上500万走出房子时，殊不知，走进了另一个深渊。究竟他们会如何抉择呢？©豆瓣', '凯莉·布鲁克', '史蒂文·R·蒙若尔', 6, 12474, 'tt0395585', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2514691242.jpg', 5.2, 19.9, 51.1, 18.6, 5.2, '0.704808,0.223367,-0.692833,0.619421,-0.304510,-0.255504,1.045000,-0.065470,-0.258436,-0.268017,0.166433,0.937864,-0.296388,0.237686,0.159853,-0.176149,-0.160463,-0.694941,-0.342150,-0.188990,-0.471891,-0.396213,-0.250348,-0.306738,-0.205424,0.175100,0.662711,0.255268,-0.087041,0.391847,0.440396,0.033060,-0.182138,0.348274,-0.072896,-0.019352,0.228383,0.126233,-0.171039,0.603593,-0.106916,0.053336,-0.054673,0.337997,-0.330153,0.317307,0.678492,-0.430431,-0.060508,0.002207,0.257907,-0.118775,-0.234266,0.371674,0.074531,-0.197772,0.298780,0.207369,-0.176513,0.281639,0.273219,-0.134122,-0.906478,-0.092487,-0.135670,0.161242,-0.446458,0.514612,0.183555,-0.095683,-0.052638,-0.249599,0.132155,0.271979,0.481637,0.612106,-0.449413,-0.235447,-0.910415,0.070857,0.786389,-0.136068,-0.138421,0.376481,-0.049379,-0.535487,-0.028330,-0.277189,-0.436972,-0.104075,0.501067,0.075642,-0.218464,-0.227145,-0.761154,0.248743,-0.231083,-0.089300,-0.103823,-0.764862,-0.009203,-0.354769,-0.164757,0.023221,-0.286870,0.590064,0.149943,-0.310504,0.657532,-0.825220,0.073045,0.534308,0.430118,-0.491637,0.719068,0.335918,0.433471,-0.009663,0.013791,-0.190841,0.199997,0.368137,0.110819,0.402904,-0.148619,-0.106214,-0.405394,0.176911', '21619567', '3055049', '3119246', '1867335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1408122', '整蛊王', '喜剧', '“整蛊王”高兴（刘青云 饰）与两名助手刘血（葛民辉 饰）、毕止（林海峰 饰）开设了一家整人公司。无良富家子史松（黄伟文 饰）雇佣高兴整蛊抗议的工人，被不做不义之事的高兴拒绝。史松恼羞成怒，请来“玩人大帝”刘家拎（罗家英 饰）整蛊高兴。原来暗箭伤人的刘家拎与明刀明枪的高兴是整人界的世仇，全神贯注迎敌的高兴不慎撞了一名等待手术的盲女阿梅（袁咏仪 饰），出于歉意和同情，高兴将阿梅与其表妹阿莲一起接回公司暂住。五个年轻人同处一室，擦出了爱慕的火花。另一方面，史松对刘家拎的整人进度大为不满，而此时，高兴已经掉入了刘家拎的圈套……©豆瓣', '刘青云', '李力持', 6.2, 5541, 'tt0115050', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352211564.jpg', 1.9, 13.6, 60.8, 17.7, 6, '0.276126,-0.044239,-0.403461,-0.052212,-0.055300,-0.105406,0.180296,0.239987,-0.226784,-0.116365,0.190218,0.199629,-0.118631,0.147126,-0.056052,-0.091541,0.034858,-0.306044,-0.059860,0.096536,-0.001167,-0.072575,-0.154688,-0.469379,-0.210966,-0.130911,-0.202030,-0.194505,-0.176715,0.707813,0.885101,0.569256,-0.180883,0.144026,-0.043527,-0.040621,-0.039183,-0.000933,-0.195874,-0.087025,-0.259108,0.004657,0.182264,-0.090195,0.356630,0.485174,0.421079,0.048083,-0.116299,-0.051570,0.401038,-0.473589,-0.181275,0.163593,0.274126,0.104799,-0.065957,-0.226068,-0.300324,-0.014062,0.135710,-0.238272,-0.616703,0.196194,0.159830,-0.120651,-0.536118,0.608876,-0.200175,-0.023553,0.187238,-0.079023,0.298434,0.191945,0.249509,0.388454,0.273794,0.160884,-0.147804,0.253052,0.280272,-0.505365,0.384689,0.227824,0.049767,-0.068276,0.226752,-0.112647,-0.223118,-0.247721,0.494331,-0.168741,0.309213,-0.311556,-0.121908,-0.283463,-0.089715,0.333301,0.292377,-0.372569,-0.159703,-0.064827,-0.030686,-0.158747,-0.182953,-0.186130,0.295138,0.162920,0.348796,-0.201551,0.106789,-0.106164,0.050959,-0.668739,0.396517,0.177582,-0.011877,-0.210747,-0.082452,-0.151530,0.227189,0.000420,0.314048,0.369975,-0.196097,-0.029182,-0.109320,-0.433822', '1302110', '3074415', '26425062', '1316525');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1408130', '大三元', '喜剧', '钟国强（张国荣饰）是名教堂的神父，某日妓女白雪花（袁咏仪饰）逃债至告解室，白雪花在底层挣扎的悲惨命运打动了神父，他决定开始挽救这群迷途羔羊的肉体和灵魂。同时，和白雪花的夜总会挂钩的黑帮老大“恐龙”成为警方的目标，警察大哥（刘青云饰）和手下（陈锦鸿饰）打算将白雪花设为突破点，开始了对其一行人长时期的盯梢。白雪花等人在神父的悉心引导下渐渐回归正途，她们找了新工作，还开始组乐团唱歌……欣慰的神父悄悄地重返教堂，却不知随后白雪花又被迫回到“娱乐界”。神父再次出山，联手警方开展了一场营救行动！©豆瓣', '张国荣', '徐克', 7.4, 12219, 'tt0116001', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p975168557.jpg', 0.7, 4.4, 40.3, 35.5, 19.1, '0.008563,0.132136,-0.408173,0.296015,-0.004122,-0.384435,0.434942,0.258238,-0.141833,-0.084804,0.411672,0.459752,-0.137570,0.349047,0.304756,-0.069207,-0.534505,-0.797745,-0.017703,-0.181151,-0.349629,-0.239597,0.029172,-0.216429,-0.095888,-0.109564,0.679078,0.203235,0.191296,0.497189,0.243001,0.065555,0.022766,0.223315,-0.193166,0.086941,0.208069,-0.060744,-0.378769,0.121995,-0.041883,-0.252021,-0.302167,-0.124056,0.006291,0.278166,0.664874,-0.103264,0.244614,-0.171793,0.295597,-0.319517,0.226945,0.133669,0.445132,0.037905,0.052123,0.043872,-0.168626,-0.069387,-0.004669,-0.183705,-0.453633,0.106099,0.210876,0.091519,-0.681258,0.310783,-0.124756,0.152853,0.248762,-0.311480,0.125730,0.278870,0.306854,0.473593,0.135025,-0.043410,-0.263492,0.337247,0.447183,0.068668,-0.011507,0.293500,-0.014629,-0.356086,-0.112346,0.092723,0.010465,-0.248517,0.624699,-0.093592,-0.058671,0.064758,-0.771330,-0.242904,-0.174066,-0.197632,0.027317,-0.412052,-0.083983,-0.713796,-0.197715,-0.085670,0.128706,0.178774,0.148508,-0.124079,0.699135,-0.775017,0.204930,0.638714,0.217370,-0.562684,0.287708,-0.041493,0.134672,-0.256494,-0.092190,0.163788,0.003769,0.836033,0.308035,0.231109,-0.128669,0.065502,-0.317108,-0.068353', '20274039', '26365262', '25723905', '1292829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1408298', '伦文叙老点柳先开', '喜剧', '伦文叙（张卫健 饰）跟柳先开（郭富城 饰）都是誉满全城的才子，由于性格各异常常发生口舌之战。某年他俩一起参加乡试，伦文叙侥幸高中令柳先开深深不忿，誓要与他再分高下。伦文叙其实一点都不喜欢念书，母亲威逼利诱他到了省城的书院上学。柳先开也在同一所书院，两人成了同学。校长向钱汉（吴孟达 饰）贪图钱财，女儿及外甥女程情（周慧敏 饰）也在院内学习。伦文叙跟柳先开共同追求貌美的程情，书院成了他们争斗的地方，闹出笑话连篇。一年一度的校际比赛又来了，面对邻校的嚣张气焰，身为精英的他们誓要能为学院争光。©豆瓣', '郭富城', '罗文', 7, 13438, 'tt0107460', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2523847648.jpg', 0.9, 6, 46.8, 33.1, 13.3, '0.328591,-0.131763,-0.423769,0.399629,0.049906,-0.295235,0.245203,0.175493,-0.388993,-0.088299,-0.255152,0.547561,-0.156612,0.622239,0.270015,-0.511520,0.129007,-0.515161,0.190061,-0.133758,-0.098313,-0.424277,0.227685,0.007920,-0.096065,0.012894,0.370521,-0.033139,-0.270277,0.566170,0.439054,0.259522,-0.104160,0.250647,-0.261791,-0.039610,-0.123836,0.547797,-0.204900,-0.176289,-0.101924,-0.258984,-0.449846,-0.215962,0.566346,0.253038,0.574888,0.329402,-0.060145,0.125427,0.128012,0.057623,0.055406,0.199133,0.531250,-0.188131,0.412235,0.196133,0.091927,0.105399,-0.275160,-0.043971,-0.068357,0.260365,0.559805,-0.102324,-0.504984,0.871815,0.130961,-0.332995,-0.111189,-0.108545,0.157635,0.438828,0.236764,0.160537,-0.033980,-0.191446,-0.412454,0.590943,0.733037,0.178111,0.089710,-0.095473,0.147768,-0.305556,0.172538,-0.376128,-0.203933,0.154346,0.133359,-0.215175,0.193349,0.252945,-0.298178,-0.266806,0.017787,0.144633,0.352265,-0.500058,0.209290,-0.502315,-0.039841,-0.516957,-0.320758,0.111151,0.545022,-0.194197,0.667310,-0.772398,-0.216252,0.186920,0.204242,-0.701889,0.856779,0.287332,0.301873,-0.134799,-0.020648,-0.082631,0.009451,0.260547,0.043736,0.687778,0.155955,-0.187162,-0.218596,0.148456', '3139191', '3212120', '4739952', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1408312', '笑林小子', '喜剧', '香港某高中学生四毛（林志颖 饰）爱上校长的孙女安妮（徐若瑄 饰），此举惹怒安妮男友铁鹰（张震岳 饰），令其开始对四毛百般刁难。在好友珍珠（徐濠萦 饰）和小皮（郝劭文 饰）的帮助下，四毛没有知难而退反是越挫越勇，发誓要与安妮约会，但终没抵过铁鹰。四毛随出差大陆的父亲游玩时，邂逅功夫了得的少林小子（释小龙 饰），并在他的帮助下练成武功。回到香港后，四毛偶知铁鹰的父亲心谋不轨想霸占校产，计划让铁鹰强占安妮以便要挟校长，开始在来港访问的少林小子的帮助下与铁鹰一伙展开恶战。©豆瓣', '林志颖', '朱延平', 7.9, 124571, 'tt0111765', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2352121968.jpg', 0.2, 1.4, 23.1, 52.2, 23.1, '0.082829,-0.198141,-0.572065,0.524834,0.039877,-0.434270,0.304239,0.308389,-0.332259,0.019400,0.422518,0.539317,-0.026062,0.123670,0.216114,-0.098717,-0.247652,-0.656672,0.144439,-0.061706,-0.015300,-0.455393,-0.215203,-0.124055,0.009803,-0.325475,0.426509,-0.172409,-0.237733,0.627681,0.147615,0.022956,-0.070784,0.334296,-0.145539,0.158836,0.054557,0.061926,-0.480660,0.451565,0.267192,-0.155772,-0.103938,0.202550,0.061104,0.157801,0.653987,-0.068467,-0.043920,-0.296071,0.012437,-0.184748,0.072619,-0.055797,0.368400,-0.000578,0.368243,0.327442,-0.284146,0.108735,0.276453,0.020961,-0.346003,0.226902,0.206663,0.020971,-0.652498,0.404147,-0.454444,0.003609,0.307434,-0.295772,0.044310,0.562316,0.082103,0.074044,-0.069867,0.209393,-0.362871,0.274148,0.563792,-0.097395,0.489764,-0.053152,0.438353,-0.081284,0.334590,0.014480,-0.182521,-0.006350,0.277807,-0.126977,-0.018470,-0.003512,-0.524168,-0.248983,-0.339764,0.221543,-0.113757,-0.295716,0.054701,-0.560843,-0.097161,-0.317379,-0.037254,-0.118752,0.272768,-0.089919,0.554252,-0.981339,0.041103,0.252127,0.496566,-0.581152,0.489009,0.292017,-0.129800,-0.121409,-0.126098,-0.066036,-0.025664,0.239737,0.188985,0.313293,0.291203,-0.462588,-0.299359,0.070321', '30345227', '35030151', '1292219', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1408315', '霸王花', '动作', '香港以前本来没有女子特警队，但因为Madam胡（胡慧中 饰）和Madam罗（罗芙洛 饰）两名女警长的出色表现，令到警局高层决定以她们为班底，组建有史以来第一支女子特警队——霸王花。Madam胡和Madam罗分别担任队长带队训练。女子特警队的训练一点也不比飞虎队轻松，在两人的严格训练下，霸王花很快就能出动执行任务了。岂料在和飞虎队一起执行一次保护珠宝任务时，Madam胡领军的霸王花被飞虎队均被国际大盗制伏。紧要关头，Madam罗率队赶到！©豆瓣', '胡慧中', '钱升玮', 6.9, 16341, 'tt0094694', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2081177319.jpg', 0.7, 5, 52.6, 31.5, 10.3, '-0.026306,-0.072367,-0.753644,0.847054,-0.297600,-0.319768,0.171796,-0.092605,-0.474065,-0.516100,0.125270,0.424226,-0.149567,0.008242,0.455449,-0.669715,-0.167999,-0.706542,-0.527400,-0.180155,-0.534904,-0.339025,0.087159,-0.508654,-0.114306,-0.015299,0.696300,0.116590,-0.233822,0.617397,0.735204,0.287051,-0.152780,0.459565,-0.038119,-0.458975,0.595982,-0.037941,-0.058153,0.228110,0.116470,-0.371828,-0.048077,-0.137428,0.569374,0.394001,0.538059,-0.097043,-0.145766,-0.403652,-0.165506,-0.070501,0.256635,-0.330362,0.792535,-0.178279,0.020983,-0.140892,-0.061247,0.169472,-0.095014,-0.469846,-0.650810,0.094679,0.351805,-0.140336,-0.818672,-0.031188,-0.364121,0.457335,0.236800,-0.140735,0.171629,0.563783,0.521792,-0.003984,0.313737,0.265792,-0.654710,0.515837,0.871541,0.174890,-0.144785,-0.288084,-0.143806,-0.692778,-0.315630,-0.212528,0.033985,0.291227,0.183439,-0.224451,0.331657,-0.298020,-0.297685,-0.404355,-0.007246,0.089283,-0.381240,-0.420313,0.252157,-0.967121,0.303681,-0.228072,-0.180763,0.418436,0.104634,-0.033740,0.684785,-1.074957,-0.123280,-0.134472,0.190970,-0.664282,0.494474,0.204954,0.348141,-0.532072,0.169753,-0.082325,0.567164,0.381064,0.727010,0.701397,-0.500611,-0.377570,-0.034942,0.037891', '25723905', '3230195', '1307762', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1410556', '终结者2018', '动作', '2018年，天网系统与人类的战争使世界陷入了末世般的境况，反抗军精神领袖约翰·康纳（克里斯蒂安·贝尔 Christian Bale 饰）带队执行一次任务的过程中获得了战胜天网的新思路，而天网系统适时推出了新的目标排名，康纳位居次席，榜首上康纳此时尚年青的父亲凯尔·瑞斯赫 然在列。与此同时，一名遗忘了自身过去经历的强壮男子马库斯（萨姆·沃辛顿 Sam Worthington 饰）出现在洛杉矶的废墟中，他与反抗军战士瑞斯偶然结识，并组队前往反抗军总部，不料途中遭机械人袭击，瑞斯被俘。落单的马库斯经由反抗军女战士布莱尔引路，迎来了与康纳命中注定的相遇，但人与机械的对立让康纳不得不视对方为敌人……瑞斯在天网中心生死未卜，同时反抗军高层不肯推迟强行进攻计划，留给康纳的时间不再充裕，他只能选择进行一场赌上性命与荣誉的潜入行动。©豆瓣', '克里斯蒂安·贝尔', '约瑟夫·麦克金提·尼彻', 6.7, 95469, 'tt0438488', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1769708758.jpg', 1.2, 8.3, 51.6, 30.7, 8.2, '0.066503,0.148548,-0.664718,0.540487,-0.059302,-0.314075,0.634358,-0.050370,-0.401226,-0.223079,0.533940,0.741946,0.286194,-0.181218,0.571060,-0.244028,-0.521605,-0.629753,-0.031959,-0.141696,-0.274157,-0.426296,-0.441915,-0.340096,-0.001208,-0.675606,0.971154,0.065283,-0.187990,0.432439,0.016976,0.506028,-0.259642,0.376132,0.108012,-0.021932,0.474313,-0.397827,-0.540662,0.480801,-0.203835,0.060017,-0.379887,0.128848,-0.027260,0.371205,0.688296,-0.472764,0.207658,-0.360420,0.121641,-0.475300,0.042710,-0.008466,0.470558,0.081473,0.098560,0.375008,0.108558,0.198631,-0.034189,-0.248998,-0.723006,0.062083,-0.023764,0.138007,-0.369313,0.460324,-0.439191,0.075931,0.089643,-0.284141,0.036505,0.586738,0.540054,0.014136,-0.251959,-0.126002,-0.369592,-0.098591,0.700032,0.054771,-0.455333,-0.116570,-0.053672,-0.529581,-0.056541,-0.384358,-0.309668,-0.057012,0.476247,0.246196,-0.071048,0.738089,-0.676536,-0.026229,-0.714008,-0.368516,-0.024364,-0.321618,-0.074747,-0.878917,-0.101032,0.060714,-0.214216,0.198359,-0.015404,-0.091120,0.488326,-0.910321,0.148641,0.524826,0.440666,-0.238288,0.466290,0.067317,0.490455,-0.233839,0.044066,0.239923,0.215106,0.521067,0.165942,0.032766,-0.091855,-0.079307,-0.390183,0.245460', '2369613', '26759819', '7051375', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1410557', '碧海追踪', '动作', '风暴之夜，一架飞机在海上失事，坠入无边的大海深处……碧水蓝天的巴哈马海域上，失业潜水员杰拉德（保罗·沃克 Paul Walker 饰）和女友萨曼（杰西卡·阿尔芭 Jessica Alba 饰）预备寻宝深海的沉船宝藏，然而破旧的小船和竞争对手贝茨的打压让他们难以如愿，幸好律师好友布莱斯和女友阿曼达来到，于是四人出海，竟意外的发现了著名海盗的宝藏线索以及一架载满毒品的飞机。布莱斯与阿曼达打起了毒品的主意，但一心挖掘宝藏的杰拉德劝说好友远离毒品。不久，杰拉德陷入财政危机，布莱斯要杰拉德不顾萨曼的劝告以毒品获利支持发掘。而贝茨和毒枭的眼镜，也在暗中盯上了这几个寻宝的好友……©豆瓣', '杰西卡·阿尔芭', '约翰·斯托克韦尔', 6.7, 8456, 'tt0378109', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p849678382.jpg', 0.9, 7.6, 54.3, 28.6, 8.6, '0.266222,-0.255690,-0.777001,0.713388,0.187678,-0.482360,0.687017,0.164431,-0.690612,0.015065,0.126971,0.779258,0.010167,-0.137964,0.333739,0.182040,-0.656961,-0.507471,0.039099,-0.165174,-0.140836,-0.708517,-0.476226,-0.278787,0.190732,-0.268510,0.563867,0.117180,-0.029264,0.626296,0.148828,0.259341,-0.212342,0.521224,-0.055815,0.011359,0.189985,0.024140,-0.347045,0.349322,-0.287725,-0.124925,-0.012100,-0.048217,0.242740,0.418012,0.528258,-0.146298,0.083366,-0.005630,-0.093722,-0.457156,0.342632,0.017400,0.510556,-0.219774,0.114322,0.044696,-0.273476,-0.093819,0.299529,0.072077,-0.398276,0.013294,-0.174573,0.177551,-0.467895,0.152556,-0.141915,0.075482,-0.157992,-0.252360,0.231332,0.350809,0.067494,0.095172,-0.154072,0.034006,-0.635246,-0.007660,0.397359,-0.070844,0.245548,0.009481,0.088260,-0.432564,-0.179417,-0.020645,-0.432504,-0.218821,0.943513,0.010444,-0.214778,0.286640,-0.947836,-0.044209,-0.429749,-0.364429,-0.355263,-0.214587,-0.120324,-0.769700,-0.067820,-0.066097,-0.018707,0.171220,0.139638,-0.117857,0.281479,-0.493857,0.307095,0.702513,0.139654,-0.215180,0.567612,-0.084628,0.094734,-0.379679,-0.197628,0.252301,0.040956,0.291527,0.007077,0.135670,-0.063199,-0.297838,-0.282044,-0.014587', '34461680', '3008263', '3011051', '1309056');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1410695', '阿嫂', '剧情', '菲比（刘心悠 饰）的父亲阿九（廖启智 饰）在18年前因杀死合作的兄弟被对方遗孀洛华（林嘉欣 饰）追杀，菲比也成为了孤儿。幸好得到了领导人百德（曾志伟 饰）的照顾，收作养女，更扬言以后要娶菲比为妻，不让洛华对菲比作出进一步报复。18年后的一天，就在百德打算退隐的时候，却遭到了别人的暗杀。于是，社团内的大风（黄秋生 饰）也想借此机会独揽大权。但百德临终前已经交托辰哥（任达华 饰）要协助菲比成为社团的最高领导，成为大家的“阿嫂”。但社团里还是内藏暗涌，辰哥与花哥（方中信 饰）为菲比找来了保镖向东（刘烨 饰）。而这时江湖上也盛传杀死的百德的主使者是洛华及其助手（谢君豪 饰）。双方仇恨更加结深一层了……©豆瓣', '林嘉欣', '黄精甫', 5.3, 9144, 'tt0452581', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2154877843.jpg', 10.2, 30.1, 48, 9.1, 2.6, '0.007132,-0.032945,-0.471185,0.434932,-0.061644,-0.245933,0.358864,0.244625,-0.549042,-0.252059,0.211327,0.651612,-0.075360,0.162277,0.372331,0.018632,-0.147887,-0.741699,0.089242,-0.213222,-0.211728,-0.427394,-0.179069,-0.168178,-0.131299,-0.091233,0.578688,0.141394,-0.179370,0.453590,0.361305,0.256315,0.023557,0.260237,-0.069057,0.037561,0.104215,-0.018098,-0.336979,0.259685,0.008059,-0.281175,-0.025063,0.011665,0.096387,0.429245,0.388770,-0.118563,0.112338,-0.222443,0.049418,-0.355192,0.026185,-0.039970,0.349968,0.030695,0.224674,0.597527,-0.351579,0.062382,0.159993,-0.179692,-0.704142,0.089937,0.394990,0.020341,-0.654616,0.362229,-0.141604,-0.029399,0.096749,-0.126138,0.233095,0.313214,0.067784,0.157619,-0.115200,0.099429,-0.494244,0.233428,0.551022,0.008267,0.295717,0.045805,0.154706,-0.258196,0.018536,-0.217078,-0.318462,-0.065448,0.153828,0.104594,0.026578,0.187093,-0.459654,-0.328845,-0.355418,0.023627,0.121343,-0.365071,0.240129,-0.379890,-0.153831,-0.268717,-0.150323,0.034771,0.130040,-0.333935,0.648004,-0.873870,0.197863,0.095095,0.434904,-0.772620,0.512226,0.136970,0.275443,-0.132508,-0.012943,-0.157037,0.201287,0.109247,0.161369,0.076992,0.090517,-0.523698,-0.030054,0.075509', '1877596', '30345227', '1301022', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1410822', '雀圣', '喜剧', '麻雀、啤牌等赌博方式一样不落的超级大赌徒自摸西（元华）躲高利债到一家茶餐厅，遇到有超强记忆力的伙计阿旺（郭晋安），灵机一动准备将他训练成麻雀高手帮助自己赢大钱，不想被老板娘十三飞（元秋）狠狠教训了一顿，但阿旺终瞒着十三飞跟自摸西游走于大小赌场，帮自摸西赚了个盆满钵满。阿旺与靓女雪儿（傅颖）偶然相遇，其后两人生出真情，但阿旺不知她是澳门财大气粗的黑帮老大天九哥（王晶）的情妇，后与自摸西拜访天九哥时，他被打成脑残。向来疼爱阿旺的十三飞见此，决定重出江湖，原来她是退隐江湖多年的“雀后”。©豆瓣', '元华', '王晶', 5.9, 17144, 'tt0468771', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2175107394.jpg', 4.1, 19.7, 58.4, 13.7, 4.2, '0.122429,-0.237748,-0.381174,0.101235,-0.029856,-0.362687,0.272610,0.271177,-0.200229,0.197621,0.330326,0.679402,-0.284896,0.039730,0.072415,0.036233,0.214128,-0.436033,-0.041108,-0.086929,0.253796,-0.203612,-0.204725,0.233290,-0.186224,0.211967,-0.199704,-0.160434,-0.024126,0.451663,0.318629,0.243222,-0.138281,-0.228067,-0.079509,0.268372,-0.052709,0.264968,-0.303210,0.190764,-0.146394,0.134928,-0.230886,-0.093284,0.380732,0.266818,0.438979,-0.122855,0.028509,-0.176456,-0.061331,-0.178103,-0.448048,0.132021,-0.041914,-0.063868,0.332515,0.123362,0.132712,-0.169291,0.086188,-0.116961,-0.514744,0.136426,-0.119664,-0.206403,-0.817339,0.342293,-0.167680,-0.048329,-0.155459,-0.365403,0.013560,0.152339,0.358384,-0.107475,-0.045518,0.176740,-0.615438,0.056750,0.532944,0.018837,0.121391,0.118562,0.194902,-0.140663,0.354669,-0.420182,-0.068890,-0.025237,0.443631,-0.213408,-0.449077,-0.037479,-0.245791,0.140971,-0.406441,-0.050025,0.030968,-0.102522,-0.326067,-0.349194,-0.348638,-0.557580,-0.362336,-0.064541,0.305615,-0.191384,0.485046,-0.688001,0.123070,0.333509,0.064864,-0.379285,0.698260,0.121206,-0.217274,-0.147448,0.004493,-0.473442,0.021865,0.279474,0.381023,0.113055,-0.234907,-0.466139,-0.025364,0.038325', '1419416', '2124718', '1306505', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1412579', '亲切的金子', '剧情', '金子（李英爱饰）20岁时，就因被控“诱拐儿童”入狱而成为头条新闻，人们惊诧于她的美貌、她的年轻。在13年的牢狱生活中，有着天使般容貌的她是狱中绝对的模范。金子尽心尽力地帮助身边的每一个人，因此狱友们都称她为“亲切的金子”。表面上金子似乎比谁都诚实守纪，但内心里的复仇火焰一天也没有熄灭。当金子出狱后，她还是马上展开复仇计划——它已经暗中策划准备了13年之久的，而狱友们也都在不同的地方帮助着她。金子的仇人是当年让她入狱的白老师（崔岷植饰），那是什么让他们在13年前结怨呢？金子又将怎样复仇呢？能否成功？©豆瓣', '李英爱', '朴赞郁', 7.6, 159344, 'tt0451094', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2561799537.jpg', 0.5, 3, 29.7, 47.8, 19, '-0.133193,0.119388,-0.591878,0.538246,-0.457817,-0.329879,0.747281,-0.052720,-0.436120,-0.011518,0.259909,0.607312,-0.125873,0.286835,-0.069594,0.176194,-0.259128,-0.800323,-0.225676,-0.307896,-0.289590,-0.198992,-0.451840,-0.264662,-0.222610,-0.158358,0.469212,0.207307,0.346069,0.315246,0.374431,0.007425,0.255183,0.380906,-0.221207,-0.088816,-0.035520,0.344973,0.017087,0.013451,-0.009089,-0.476617,-0.286834,0.290749,-0.009391,0.402866,0.437991,-0.266180,-0.143378,-0.291193,0.337065,-0.309375,0.131945,0.384315,0.306269,0.059009,0.150792,0.124222,-0.240564,-0.018817,0.070087,-0.044742,-0.869342,-0.145888,0.208433,0.050405,-0.656215,0.472853,0.001685,0.160711,0.034762,-0.153451,0.178721,0.297894,0.209119,0.380530,-0.496018,-0.102975,-0.653667,0.311267,0.610104,0.249973,-0.156846,0.176832,-0.313534,-0.576422,-0.009033,-0.158977,-0.449157,0.033259,0.181118,0.142585,-0.197745,0.294008,-0.615559,0.081940,-0.291049,0.048697,-0.070647,-0.426199,-0.114153,-0.260719,0.021321,-0.621586,-0.457211,0.044937,0.256391,-0.393251,1.000105,-0.643094,0.291966,0.603879,0.332312,-0.665224,0.655320,0.101489,-0.062865,0.009976,-0.190615,-0.035188,0.122252,0.342422,0.106554,0.355676,0.049273,-0.049789,-0.205267,0.796093', '30163500', '27602116', '1432669', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1414803', '守夜人', '动作', '影片是根据谢尔盖·卢科扬涅科的三部曲中的第一部《守夜人》改编。光明军队与黑暗军队签订了一项为期一千年的免战合约。一千年后，两支军队的首领格谢尔(符拉季米尔·门少夫 Vladimir Menshov 饰)和扎乌龙(维克多尔·维尔热宾茨基 Valeri Zolotukhin 饰)生活在今日的莫斯科。守夜人跟踪黑暗的异己势力，维持善与恶之间的平衡；而守日人则是监视光明力量的活动，一旦善恶比例失衡就会引起战争、革命、毁灭甚至全世界的灾难。菜鸟守夜人安东·格洛节茨基(康斯坦丁·哈宾斯基 Konstantin Khabenskiy 饰)的监视对象是吸血鬼科斯佳(阿雷克西·查多夫 Aleksey Chadov 饰)。小男孩叶戈尔出现了，他拥有着打破光明黑暗两派平衡的力量，谁得到他都会取得最后的胜利。为了争夺终极力量的人魔大战开始了，自此世界开始崩溃……叶戈尔将走向光明还是走向黑暗？', '康斯坦丁·哈宾斯基', '提莫·贝克曼贝托夫', 6.9, 12566, 'tt0403358', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1571366610.jpg', 2.4, 9.3, 39.9, 35.5, 12.9, '0.019524,0.295424,-0.419338,0.348560,0.147964,0.052152,0.454907,0.214702,-0.367493,-0.123492,0.290331,0.507279,0.055357,-0.159063,0.401550,0.011228,-0.470710,-0.837720,-0.121867,-0.033512,-0.189655,-0.314698,-0.549199,-0.330290,0.004385,-0.660818,0.663500,0.357913,-0.422984,0.015583,0.092168,0.353071,-0.196236,0.288144,0.116916,-0.159101,-0.048135,-0.415545,-0.430589,0.177477,-0.216171,-0.024302,-0.319625,0.086105,-0.091688,0.158055,0.452098,-0.673196,0.267702,-0.332109,0.329035,-0.371970,-0.193885,0.043284,0.333134,0.016201,0.073507,0.409035,-0.020845,0.210077,-0.109557,-0.161747,-0.843137,0.170109,-0.130761,0.370233,-0.284649,0.570676,0.027554,0.124717,0.129876,-0.045288,0.004517,0.629437,0.408634,0.167590,-0.152677,-0.200062,-0.525986,-0.301079,0.485975,-0.471935,-0.517129,-0.002990,-0.171485,-0.513117,-0.587101,-0.281957,-0.381750,-0.214613,0.529612,0.062298,0.410363,0.466464,-0.872849,-0.113566,-0.294999,-0.258021,0.029252,-0.211752,0.084089,-0.669827,-0.267434,-0.054280,-0.247128,0.067546,0.154745,-0.219144,0.618170,-0.699390,0.276447,0.444211,0.365615,-0.423953,0.537938,-0.034727,0.189994,-0.457145,0.088664,0.564314,0.093898,0.305745,0.149244,0.122908,0.152204,0.068440,0.087856,0.613553', '26759