INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1414808', '热带疾病', '剧情', '泰国的小乡村迎来了一批军人在此驻扎。其中，有一个叫做KENG（班洛浦•罗蒙内Banlop Lomnoi 饰）的士兵跟乡村孩子TONG（萨克达•凯伍布迪 Sakda Kaewbuadee 饰）相识。开始，TONG和一个女孩眉目传情，但终究擦肩而过。在工厂帮忙的TONG，向 KENG学开车，两人由此建立了深厚的感情…… KENG和TONG的感情慢慢从友情开始升华。TONG的妈妈无意中发现了TONG对KENG示好的卡片。为了不让儿子越陷越深，她带领两人穿越地下隧道拜佛祈求神佑。在茂密的丛林中，两人无意中听到一个古老的传说——爱意会让情人的灵魂幻化成老虎。没想到竟然一语成谶…… 本片荣获第57届戛纳电影节评审团奖。©豆瓣', '班罗普·洛罗伊', '阿彼察邦·韦拉斯哈古', 8, 7368, 'tt0381668', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1686081822.jpg', 1.3, 3.6, 20.8, 43.7, 30.7, '0.314207,-0.164129,-0.787114,0.925440,0.008261,-0.235340,0.729886,0.116635,-0.543507,-0.029179,0.106673,0.871350,-0.347724,0.146604,0.192313,-0.125435,-0.212754,-0.617572,-0.173238,-0.208497,-0.286975,-0.320050,-0.220328,-0.012364,-0.127045,-0.328022,0.557854,0.098551,-0.211266,0.707734,0.382650,0.244664,-0.346416,0.084236,-0.448942,-0.036087,0.230755,0.232732,-0.417830,0.362464,-0.242212,-0.118748,-0.225731,-0.176781,-0.150705,0.213622,0.817060,-0.101225,-0.043268,0.057368,0.382864,-0.081855,-0.039833,-0.054851,0.410765,0.099844,0.305087,0.074928,-0.004264,0.138207,0.037628,-0.199439,-0.569768,0.075559,-0.032356,0.081372,-0.661330,0.530341,0.288712,-0.208170,0.237627,-0.270799,0.277277,0.274216,0.235820,0.528974,-0.179894,-0.050985,-0.607544,-0.037147,0.475305,-0.145417,-0.162873,0.549661,-0.047834,-0.491269,0.236803,0.062571,-0.336193,-0.003578,0.241793,-0.053380,-0.189822,0.177956,-0.812427,0.032398,-0.096324,-0.023534,0.192275,-0.519773,-0.191392,-0.417935,-0.210848,-0.245451,-0.139251,0.191558,0.052766,-0.180849,0.895185,-0.887330,0.364919,0.436873,0.312805,-0.417211,0.864596,0.144355,-0.046081,-0.243539,0.061849,0.137444,0.058972,0.210837,0.174230,0.403932,-0.238179,-0.045402,-0.341783,0.159433', '3055049', '1292219', '3445516', '26958479');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1415573', '我的哥哥', '剧情', '星铉（申河均 饰）有个比自己小一岁的弟弟宗铉（元彬 饰），两人性格各异。他们跟着守寡的母亲生活，温和听话的哥哥星铉深得母亲的厚爱，弟弟宗铉对母亲的表现耿耿于怀，所以他只会叫哥哥全名，甚至有时候会欺负哥哥。兄弟俩读高中的时候，喜欢上了同一个女孩子，女孩是有名的校花美玲（李宝英 饰）。羞涩的星铉在自己的画册里不断画着美玲的样子，写着没有送出去的情书。宗铉则是想尽办法吸引美玲的注意。一日，宗铉看到了星铉的画与诗，竟然当作是自己的作品送给了美玲，自此美玲也喜欢上了宗铉，星铉只管自己默默的痛苦。©豆瓣', '元斌', '安权太', 7.7, 5609, 'tt0423461', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p465614873.jpg', 0.3, 2, 30.1, 49.4, 18.3, '0.311114,-0.292904,-0.513948,0.761364,-0.297455,-0.374945,0.625361,0.310285,-0.452800,0.022828,0.502550,0.755000,-0.069138,0.392731,-0.024697,0.335734,-0.217090,-0.718887,-0.089436,-0.036945,-0.108108,-0.411558,-0.094430,0.186394,-0.040747,-0.432340,0.134527,-0.486793,-0.179405,0.627987,0.252282,0.046129,0.006099,0.344875,-0.175312,0.097116,-0.232307,0.020331,0.046622,-0.048168,0.135301,-0.043465,-0.122901,-0.038722,0.177034,0.252679,0.778471,-0.243318,-0.296068,-0.093776,0.411566,-0.100755,-0.177192,0.141887,-0.064699,-0.060332,0.614149,-0.045265,-0.225269,-0.131324,0.034431,-0.014677,-0.450612,0.027695,0.358749,0.276794,-0.727946,0.769433,-0.126745,-0.148215,0.446180,-0.490064,0.343932,0.166026,-0.201195,0.470626,-0.285824,0.119683,-0.355405,0.315504,0.373207,0.149641,0.248956,0.388970,-0.246569,-0.022245,0.104709,-0.376922,-0.915968,0.347168,-0.063802,-0.180740,-0.221317,0.072935,-0.403610,-0.067568,0.236354,0.171344,0.224519,-0.585819,-0.262874,-0.012762,-0.016400,-0.735192,-0.363290,-0.150503,-0.198667,-0.417403,1.251281,-0.754259,0.310841,0.236794,0.343701,-0.427332,0.753428,0.372269,-0.199764,-0.099713,-0.180219,-0.104405,-0.218437,0.049365,0.051239,0.538913,0.277710,-0.396692,-0.422734,0.543127', '26348103', '6963575', '3445516', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416301', '凶榜', '恐怖', '妻子小兰（余绮霞）怀孕之后，张劲强（秦祥林）每份工所做时长都很有限，考虑到自己学历低、技能少，他并没多在意，只在又一次失业后更加勤力地找新工，无奈运气不佳。两人为小兰越来越大的肚子发愁之际，一张无端端出现的报纸将张劲强领到一幢大厦成了保安，汉叔（詹森）、肥仔（郑则仕）、香港先生（王青）及小丁（许炳森）是他的同事。开工伊始，他在听汉叔交代相关工作时，发现电梯有异况，但汉叔只要他做事大胆莫疑神信鬼。不久，他与肥仔夜间巡逻时，被汉叔告知小兰来急电，因等不及入厕的肥仔独自乘电梯下楼，不想电梯失控直将他带到地下室，骇人一幕出现。惊魂甫定，他将所见讲给同事听，大家都不相信，因为随后下来的肥仔并无异样，而汉叔也并未通知他下楼。紧接，一帮人围在监控室吃宵夜，说到刚刚的事，香港先生表示任何状况都吓不倒他，话音未落，电路即出现异常，香港先生也被一块狗骨头卡到，送至医院不治身亡。香港先生出殡之日，法师兼风水先生（岳华）瞅见张劲强瞬间吃了一惊，再见汉叔则暗叫不好，但他未作声张，不久汉叔毙命于自家屋中。汉叔丧礼上，张劲强告知肥仔他们工作的大厦是冤魂集结处，并拿出旧报纸作证。随后法师入室行礼，并在与他们攀谈时要了张劲强的生辰八字，他原是最易被鬼魂上身之人，但却未被鬼上身。肥仔替张劲强送小兰去医院检查，大狗狂吠不止；医生替小兰体检，感觉到一丝异常；小兰越来越奇怪的举动……越来越多迹象表明，小兰所怀的，是鬼胎。', '秦祥林', '余允抗', 7.2, 8989, 'tt0083347', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2493714680.jpg', 1.2, 5.5, 39.9, 39.7, 13.8, '0.400451,-0.155409,-0.688826,0.005461,-0.024557,-0.315839,0.722019,0.266631,-0.407636,-0.231709,0.188845,0.512910,-0.327635,0.081122,0.022842,-0.216356,-0.204445,-0.291633,0.071338,-0.169298,-0.301437,-0.274915,0.213401,-0.167618,-0.206843,-0.272147,0.015655,-0.121805,-0.120225,0.345366,0.021955,-0.028791,-0.072515,0.775060,-0.056001,0.139884,-0.083223,0.077403,0.076277,0.084464,0.217425,-0.296767,-0.329660,0.174863,0.132386,0.392785,0.359543,0.107688,-0.527917,-0.004414,0.304122,-0.079909,0.053602,-0.005661,0.407332,0.114141,0.073674,0.169606,-0.267537,0.113686,-0.020663,0.181821,-0.184241,0.246968,-0.135137,0.216563,-0.417466,0.168596,-0.360752,0.029720,0.056855,-0.499529,0.232445,0.185978,-0.088239,0.162026,0.017341,-0.035460,-0.491302,0.083961,0.409397,0.038216,0.095061,0.354633,0.182704,-0.448330,0.177440,0.279428,-0.113685,0.055585,0.203893,0.222313,-0.283994,-0.150772,-0.134034,-0.078262,-0.177370,-0.282882,-0.253966,-0.236796,-0.088188,-0.469264,0.033248,-0.021061,-0.169756,0.190549,0.186254,0.021133,0.283191,-0.509350,0.121320,0.253282,0.343556,-0.364590,0.478964,-0.128993,0.008306,-0.038481,-0.003309,-0.174776,0.272080,0.520289,0.381536,0.375995,-0.063928,-0.191567,-0.345492,0.117677', '27617348', '35073565', '1309125', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416435', '破碎之花', '剧情', '年过半百的唐·琼斯顿（比尔·默瑞 Bill Murray 饰）一生拥有数不尽的浪漫恋情和风流韵事，但他从来无意组建家庭，只愿享受热恋的激情，任凭一个个出色的女性从身边流走，展开别样的人生。这一天，唐收到一封某前女友的来信，信中称继承了他血脉的儿子离家出走，正踏上一段寻父旅程。万千情愫，难以言喻，唐也展开一段倒溯之旅。他先后拜访了劳拉（莎朗·斯通 Sharon Stone 饰）、朵拉（弗兰西丝·康罗伊 Frances Conroy 饰）、卡门（杰西卡·兰格 Jessica Lange 饰）和派妮（蒂尔达·斯文顿 Tilda Swinton 饰）。人有百种，花有千姿，曾经的孟浪，蓦然回首，凋零的岂是那逝去的青春。这究竟是一段追索真相的旅程，还是关于情感与记忆的祭奠……本片荣获2005年戛纳电影节评委会大奖。©豆瓣', '比尔·默瑞', '吉姆·贾木许', 7.7, 18426, 'tt0412019', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p850786456.jpg', 0.3, 2.1, 26.9, 52.3, 18.4, '-0.048934,-0.026600,-0.388370,0.769588,0.114805,-0.568771,0.632535,-0.048868,-0.503987,-0.304913,-0.326647,0.513537,-0.501332,0.304510,0.491082,0.115892,-0.081558,-0.660701,0.060777,-0.074020,0.021603,-0.261372,-0.315081,-0.139257,0.268837,-0.294449,0.654616,0.208141,-0.176412,0.677399,0.566678,0.506520,-0.190050,0.143054,-0.231059,0.237655,0.043909,0.433766,-0.567004,0.046634,-0.033900,-0.271481,-0.115007,-0.161110,-0.091202,0.122041,0.576151,-0.168847,-0.102626,0.116310,0.550843,-0.189732,-0.034626,-0.160791,0.115216,0.176489,0.019477,0.269976,-0.110895,-0.165700,0.135992,-0.210891,-0.501607,-0.205496,0.031884,0.133395,-0.424164,0.210030,-0.003167,0.056568,-0.035385,-0.103393,0.106688,0.384797,0.270695,0.191417,0.054667,-0.076299,-0.376550,0.469864,0.491170,0.059825,-0.255321,0.386463,-0.449479,-0.425115,-0.144420,-0.047054,-0.453426,0.188553,0.314307,0.129302,0.132687,0.434396,-0.523329,-0.154259,-0.225497,-0.084558,0.198939,-0.494260,0.122965,-0.661225,-0.307200,-0.502487,-0.527299,-0.100607,0.427381,-0.135202,0.566663,-0.421646,0.523540,0.188533,0.027037,-0.245464,0.592797,0.232868,-0.065066,-0.190428,0.099581,0.868354,-0.082620,-0.108862,-0.113547,0.268608,-0.213781,0.102723,-0.522232,0.372431', '1296992', '1299663', '6973376', '1303074');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416722', '蜡笔小小生', '剧情', '可爱搞怪的小生（郝绍文 饰）因受不了父亲娶了新妻子而责骂自己，便离家出走。一路游荡，接着小生认识了校工达叔（吴孟达 饰），纠缠达叔收留他。达叔一直喜欢一个卖花的盲女（朱茵 饰），并假装有钱人天天在她的花摊买花，希望尽绵力帮忙她。达叔所任职的学校有一群顽劣的学生，没有老师能够把他们教好，校长只好悬赏50万聘请老师。达叔知道盲女的手术费正好是50万，面对顽劣的学生，达叔决定跟小生一起到乌龙寺学艺。学成归来的达叔果然把学生教的十分守规矩。但为了让学生阿武（金城武 饰）在情敌面前出口气，帮阿武催眠打架，达叔被学校赶走了。小生出主意到自己家里偷出50万，可惜失败了，为了使达叔能逃走，小生被父亲抓住……©豆瓣', '郝劭文', '朱延平', 7.5, 16556, 'tt0113588', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352212355.jpg', 0.5, 2.9, 37.6, 40.9, 18.2, '0.299736,-0.186528,-0.194709,0.211731,-0.532139,-0.444786,0.246924,0.042074,-0.486944,-0.359295,0.085266,0.654616,0.006646,0.460846,0.130388,-0.066873,0.189803,-0.342774,-0.072056,-0.063673,-0.031276,-0.373351,0.096697,-0.099701,-0.294302,-0.154885,0.205276,-0.049765,-0.037656,0.499516,0.426362,0.064924,-0.005606,0.121776,-0.243501,0.131571,-0.106575,0.093124,-0.070838,0.107151,0.072721,-0.154668,-0.052018,-0.059093,0.288363,0.190097,0.605632,0.103115,-0.118409,-0.111856,0.312481,-0.232859,0.042515,0.054139,0.090441,0.023906,0.359079,-0.012341,-0.109282,0.025827,0.216408,-0.238597,-0.291802,0.150043,0.129679,-0.174703,-0.609311,0.143865,0.120440,-0.073274,0.174896,-0.266070,0.070274,0.114188,0.031168,0.206255,-0.199086,0.015713,-0.411565,0.350106,0.419813,-0.183430,0.297226,0.235456,-0.135185,-0.104763,0.349543,-0.428897,-0.479900,0.323710,0.155156,-0.283017,-0.417585,-0.221220,-0.245490,-0.374352,-0.184954,0.072794,-0.074420,-0.473960,0.021558,-0.088721,0.144258,-0.031064,-0.247252,0.042801,0.083981,-0.227066,0.717815,-0.853390,0.112431,0.591908,0.478231,-0.601395,0.656172,0.190947,-0.111138,-0.159170,-0.116467,-0.132048,0.218651,0.356900,0.241468,0.235989,0.029816,-0.442003,-0.310793,0.046908', '3445516', '1292720', '1877596', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416728', '花田喜事', '喜剧', '富家子弟周通（许冠杰 饰）武功高强，到处仗势凌人，其妹妹周吉（吴君如 饰）也十分无理取闹。他们的母亲太君（许冠英 饰）一直想他们定性并能够成家立室。可是在周吉的新婚之夜，夫君林嘉声（黄百鸣 饰）忍受不了周吉而逃走了。自此，太君便茶饭不思，周通于是为母亲办寿筵冲喜，更想请 著名魔术师大围高栢飞（张国荣 饰）助兴。与此同时白雪仙（关之琳 饰）乔装出来逛花市，与高栢飞一见钟情。白父（吴孟达 饰）得知事情后以为女儿已怀孕，便找到高柏飞提亲，却误以为周通就是高栢飞。当周通见过白雪仙之后，便誓要得到美人。母夜叉（毛舜筠 饰）从逃难的高栢飞与雪仙口中得知了他们的遭遇后，便假扮新娘教训周通。周吉的丈夫林嘉声成为了状元，周吉想与夫君和好，却遭到了林嘉声拒绝……©豆瓣', '张国荣', '高志森', 7.6, 78763, 'tt0107159', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p940240959.jpg', 0.5, 2.9, 31.5, 45.3, 19.9, '-0.277987,-0.105960,-0.308634,0.447052,-0.096033,-0.227237,0.305990,0.198117,-0.398497,-0.194794,0.163721,0.663490,-0.397678,0.273658,0.196942,0.191537,-0.077680,-0.595172,0.165752,-0.224224,-0.128385,-0.115465,0.172732,-0.203880,-0.208429,0.016163,0.213779,-0.113115,-0.068056,0.579036,0.342093,-0.020917,-0.183097,0.390566,-0.483779,0.291414,-0.182822,0.405346,-0.210406,0.156793,0.066968,-0.126272,-0.155419,-0.078077,0.141166,0.173384,0.321435,-0.294167,0.026249,-0.210459,0.080726,-0.051095,0.244447,0.413124,0.235936,-0.185581,0.478101,0.264803,-0.267940,-0.049101,-0.068110,0.069668,-0.277284,0.275496,0.132526,-0.318253,-0.441620,0.322882,-0.317260,0.027702,-0.038463,-0.216686,0.115155,0.112927,-0.037183,0.174376,-0.133681,0.006851,-0.420338,0.320371,0.495506,0.210078,0.135770,0.255409,0.304333,-0.337158,0.174801,-0.047004,-0.019613,0.050945,0.507650,0.143613,0.078088,-0.102928,-0.000123,-0.378327,-0.604840,0.052283,0.084604,-0.072648,-0.173097,-0.011175,-0.039951,-0.337264,-0.365546,-0.124150,0.127811,-0.227815,0.502592,-0.656874,0.265108,0.089889,0.285759,-0.854809,0.405509,-0.057813,0.131375,-0.240441,-0.090906,0.008385,-0.207165,0.317642,0.032422,0.171686,-0.079662,-0.428669,-0.204558,0.043595', '1307922', '1297710', '3998385', '1410695');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416895', '生命是个奇迹', '剧情', '1992年南斯拉夫内战前夕，塞尔维亚工程师卢卡（Slavko Stimac 饰）为了修建一条旅游线路，带着痴迷歌剧的老婆嘉德兰卡（Vesna Trivalic 饰）和梦想成为足球运动员的儿子米罗（Vuk Kostic 饰）来到波斯尼亚地区的山上安营扎寨。卢卡不去理会妻子的抱怨和战争的传闻，一心投入线路的设计中。不久，战争爆发，米罗应征入伍，而嘉德兰卡也不堪忍受乡间的生活与情人私奔，失意的卢卡在隆隆炮火中等待着妻儿的归来。偶然机会，卢卡从士兵手中救下穆族女子撒巴哈（Natasa Solak 饰）。原本打算将其作为交换被俘虏的儿子的砝码，但卢卡却渐渐与撒巴哈产生了感情……本片荣获2004年戛纳国际电影节法国国家教育系统电影奖金、2005年凯撒电影节欧盟最佳影片奖。©豆瓣', '斯拉夫科·斯提马科', '埃米尔·库斯图里卡', 8.7, 7336, 'tt0322420', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2563026264.jpg', 0.5, 1.3, 10, 38.7, 49.6, '-0.111387,-0.075350,-0.547099,0.733063,0.235975,-0.361777,0.441109,0.049146,-0.288160,-0.071835,0.119727,0.673835,-0.123289,-0.109148,0.534258,-0.135009,-0.529848,-0.805005,-0.083439,-0.167922,-0.009334,-0.376964,-0.094329,-0.230643,-0.248851,-0.588900,0.809002,-0.040561,-0.010063,0.586541,0.288261,0.295230,-0.193360,0.184014,0.100855,-0.139914,0.145115,-0.094872,-0.566039,0.287907,-0.153530,-0.110841,-0.169328,-0.085949,0.293863,0.303868,0.717279,-0.261067,0.525954,-0.284437,0.238054,-0.207947,0.148865,0.064122,0.078444,0.051095,0.137318,0.223008,-0.069250,0.038156,0.209620,-0.500163,-0.331368,-0.081135,-0.172510,0.054586,-0.540101,0.559367,-0.283127,0.179693,-0.004808,-0.195413,0.249972,0.361826,0.253799,0.349260,-0.229601,0.161741,-0.448721,0.292462,0.396026,-0.350883,-0.252368,0.088493,-0.126520,-0.436221,0.115349,-0.187399,-0.685576,-0.073323,0.337529,-0.085472,-0.129387,0.530361,-0.648248,0.045202,-0.330821,-0.437627,0.283950,-0.094368,-0.022695,-0.712855,0.000530,-0.205389,-0.109245,-0.019998,0.065565,-0.018214,0.571323,-0.585454,0.229386,0.581953,0.529646,-0.188882,0.582223,0.002373,0.309767,-0.233611,-0.169620,0.464948,-0.179819,0.062698,-0.019994,0.088575,-0.113526,-0.297364,-0.042117,0.455045', '1780122', '6843843', '26365262', '1302050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416898', '鲸鱼马戏团', '剧情', '一个位于匈牙利平原上的小镇迎来了一个马戏团，最为独特的是这个马戏团有一条鲸鱼的尸体和一个神秘的王子。自从这个马戏团来到这个小镇，所有的秩序都收到干扰，最终爆发了一场暴利与善良的冲突……幕后制作前后制作长达四年，只有39个镜头，却与七个不同的摄影师合作，从美国、匈牙利、德国、法国等，以不同摄影师的独特风格创造出不同的精采片段，剧情以轮转式的从某一个角色的观点游移到另一个角色，鲸鱼马戏团在小镇上的出现，超过六百名的非职业临时演员，融合了早期纪录剧情片式的真实，加上精准的场面调度及强烈的视觉风格，以表现出东欧社会的现况，一块身处在欧洲社会的中央，却是国际社会最边缘局外的景况。', '拉尔斯·鲁道夫', '贝拉·塔尔', 8.8, 10190, 'tt0249241', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p726224656.jpg', 1, 1.9, 9.4, 32, 55.8, '0.502440,0.236241,-0.675471,1.076550,-0.073265,0.034261,0.871085,0.054779,-0.258039,-0.245758,0.425601,1.021566,-0.253690,0.124788,0.245865,-0.320584,-0.018780,-0.550725,-0.381362,-0.172419,-0.354174,-0.422235,-0.533239,-0.006363,-0.159494,-0.157414,0.839404,-0.051950,-0.617167,0.307159,0.384504,0.280584,-0.125672,0.138672,-0.468080,-0.384050,0.097952,0.041701,-0.226901,0.258755,-0.209683,-0.128712,0.108885,0.061842,-0.335024,0.376199,1.023638,-0.464739,-0.148393,0.041883,0.895983,-0.027520,-0.310313,-0.022240,0.485002,-0.025966,-0.031594,-0.152060,-0.210265,0.134392,-0.164469,-0.253451,-1.079206,-0.239954,0.157566,0.304222,-0.548574,0.406736,0.170504,-0.564187,0.025018,-0.205449,0.123590,0.383363,0.377958,0.544511,-0.017779,0.074419,-0.373380,-0.078166,0.698072,0.061010,-0.880325,0.380157,-0.351743,-0.714664,-0.184613,-0.337040,-0.145880,-0.058046,0.293139,-0.400940,-0.028178,0.127633,-1.137294,0.318475,-0.038505,-0.466546,0.182661,-0.278411,-0.262661,-0.970869,-0.333331,-0.563870,-0.150151,0.172307,0.194487,-0.090783,0.860225,-0.762314,0.058978,0.576695,-0.002385,-0.256565,0.794685,0.125240,0.101182,-0.410687,-0.185871,0.233047,0.070205,0.308600,-0.333105,0.626527,-0.143841,-0.217690,-0.633633,0.672441', '22265121', '26290398', '2053515', '1294434');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416905', '冰雪勇士', '剧情', '1944年，二战已经接近尾声，穷途末路的德国纳粹变得格外残忍，众多盟军士兵在缴械后惨遭杀害。美军士兵迪克（Corbin Allred 饰）、斯蒂文（Alexander Polinsky 饰）、谢尔（Larry Bagby 饰）和戈登（Peter Asle Holden 饰）四人从纳粹的屠杀中侥幸逃脱，曾经在德国担任神父的迪克通晓德语，加之出色的枪法令他成为四人中颇为依赖的战力，然而此时的迪克身陷厌战症的困扰，频频出现在眼前的黑影不知是敌人的身形还是死神的召唤？四人在暂时栖身的木屋中恰巧听闻了德军的情报，于是赶在德军之前救出了一位英军飞行员温利。温利身负传递德军布阵情报的重要使命，为了让情报顺利传达挽救盟军将士生命，迪克等四人与温利一同踏上穿越德军封锁线的征途……©豆瓣', '柯宾·艾瑞特', '瑞恩·雷特尔', 7.1, 5679, 'tt0373283', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p474952398.jpg', 0.8, 4.8, 43.9, 39.5, 11.1, '0.276524,-0.131495,-0.635230,0.488880,0.010037,-0.110020,0.542499,-0.233443,-0.598882,-0.106478,0.611736,0.708850,0.301117,-0.220715,0.419398,-0.298845,-0.440630,-0.691196,-0.111224,-0.193054,-0.283980,-0.532952,-0.488404,-0.387647,-0.102185,-0.789546,0.819027,0.352903,-0.209514,0.499753,0.063040,0.304365,-0.123440,0.384923,-0.036873,-0.099581,0.360619,-0.514580,-0.293655,0.230109,-0.358081,-0.468489,-0.256727,0.154448,-0.159356,0.407454,0.722945,-0.414629,0.101864,-0.051315,0.156818,-0.419028,0.106047,0.105509,0.326035,0.209164,-0.033119,0.054832,-0.164852,0.018748,-0.294833,0.165618,-0.709293,0.028422,-0.057045,0.187008,-0.440384,0.435065,-0.326810,0.233052,0.371158,-0.292869,0.137551,0.540553,-0.086991,0.161012,-0.257494,-0.045743,-0.465846,0.046870,0.514709,-0.351848,-0.411532,-0.050804,-0.164968,-0.428720,0.039766,-0.059082,-0.115392,-0.261401,0.506352,0.212173,0.003003,0.384453,-0.490626,0.059329,-0.447094,-0.266570,-0.149163,-0.088647,-0.352760,-0.863158,-0.179142,-0.350052,-0.268443,0.332738,-0.070535,0.270192,0.820988,-0.559412,0.303940,0.309362,0.036681,-0.089453,0.474209,0.099053,0.132029,-0.082006,0.022650,0.540893,-0.015668,0.439429,0.232095,0.231144,-0.221530,-0.183905,-0.356918,0.299344', '2369613', '10467125', '3811356', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1416942', '希特勒的男孩', '剧情', '1942年的德国，17岁的少年Friedrich（马克思·雷迈特 Max Riemelt 饰）努力训练自己，梦想有朝一日能够加入纳粹的训练营。在通过重重考试之后，他获得了机会，然而他的父亲却极力反对，于是他伪造父亲在文书上签名，成功成为了训练营的一名成员，开始了每天艰苦的训练。在其中，他认识了Albrecht（汤姆·希林 Tom Schilling 饰），一个德国军官的儿子，两人建立了深厚的友情。然而Albrecht却不热衷于纳粹，反而更喜欢文学和写作。Albrecht的父亲却希望儿子跟他一样，以后成为一名纳粹军官，两人矛盾不断。在训练营里，Friedrich和Albrecht发现了许多丑恶的现象，Friedrich的信仰开始有所动摇。而在一次水中训练中，Albrecht却再也没有从水中出来......本片获2003德国电影奖最佳原创剧本奖。©豆瓣', '马克思·雷迈特', '丹尼斯·甘塞尔', 8.2, 28851, 'tt0384369', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1635671945.jpg', 0.2, 1, 16.5, 51.8, 30.5, '0.103678,0.172194,-0.889447,0.826413,-0.083849,-0.425533,0.580648,-0.260392,-0.683188,-0.098806,0.049890,0.932169,0.029707,0.244337,0.028290,-0.262019,-0.376585,-0.937546,0.009601,-0.110551,-0.344207,-0.312651,-0.342771,-0.297150,-0.359241,-0.446061,0.910853,0.116645,-0.171475,0.503718,0.247036,0.118161,0.276606,0.472116,-0.157008,-0.111041,0.341788,-0.078083,-0.140836,0.261325,0.061939,-0.334785,-0.484122,0.248974,0.177078,0.336277,0.584250,-0.232376,-0.156406,0.027264,0.564692,-0.271841,-0.163117,0.158235,0.305549,0.233915,0.218127,0.239830,0.143407,0.112191,-0.269420,-0.281289,-0.708875,-0.321094,0.010080,0.354415,-0.735078,0.563385,-0.139695,0.151467,0.072372,-0.268115,-0.079033,0.333775,0.134378,0.264792,-0.427791,-0.077316,-0.648504,0.619456,0.608942,-0.099339,-0.380001,0.302131,-0.259778,-0.515031,-0.180055,-0.233782,-0.354047,-0.089551,0.466003,0.028744,-0.281085,0.156890,-0.547904,0.041405,-0.167166,-0.227525,-0.160180,-0.297735,0.048881,-0.585266,-0.158474,-0.242979,-0.413706,0.058099,-0.099748,-0.557705,1.051111,-1.043289,0.313159,0.640789,0.268087,-0.480512,0.639281,0.239026,0.147781,-0.146234,0.087603,0.137431,-0.029778,0.153482,0.188183,0.527392,-0.028850,-0.198053,-0.263546,0.609103', '27602116', '1870681', '35030151', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417036', '下弦之月', '剧情', '月圆之夜，望月美月（栗山千明 饰）邂逅吉他手亚当（宝井秀人 饰），被他的兰色眼眸和弹奏出的优美旋律所吸引，离开了自己讨厌的家，与亚当同居。月缺时，她终于决定与亚当私奔，一起离开日本，但却遇到了交通意外。学生荧荧（黑川智花 饰）为找小猫露露而遭遇车祸，之后一直梦见在一个四周都是栅栏的地方，一位长发的少女帮她寻找露露。之后在一座废弃的大屋里，荧荧见到了梦中的少女，单除了她之外，谁都看不见那为少女，且少女已经失去了记忆，荧荧和她的伙伴决定帮少女实现她的愿望——找到她的恋人亚当。孩子们发现了少女就是因车祸而昏迷的美月，单美月逐渐恢复的记忆，却属于另一个人……©豆瓣', '栗山千明', '二階健', 6.8, 5607, 'tt0440532', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2613134215.jpg', 2, 10.6, 45.3, 28.7, 13.5, '0.131144,-0.096845,-0.530859,0.494898,-0.302675,-0.446550,0.943250,0.057563,-0.436847,-0.291242,0.221976,0.647012,-0.116467,0.428819,0.284940,0.324139,-0.274819,-0.863053,0.041957,-0.271950,-0.398767,-0.393012,-0.013868,0.013579,0.119489,-0.276640,0.913998,0.177879,0.116836,0.428847,0.079014,-0.064492,-0.237363,0.377153,-0.121108,-0.049649,-0.088725,0.022085,0.013230,0.323412,-0.193272,-0.300439,-0.199738,0.116075,-0.212764,0.278759,0.928618,-0.364321,-0.107856,-0.205202,0.207487,-0.097193,0.016005,0.052154,0.101277,0.003851,0.290608,-0.004146,-0.280704,-0.435546,0.166838,-0.080983,-0.368895,0.388941,0.184918,0.269941,-0.484317,0.352557,-0.001008,-0.035432,0.404642,-0.234032,0.260479,0.131099,0.277313,0.463383,-0.322491,0.171556,-0.442463,0.187803,0.505775,0.025027,-0.201652,0.486745,-0.196760,-0.415203,-0.153747,0.065996,-0.219860,0.200566,0.025272,0.241368,-0.405626,0.125649,-0.516409,0.030548,-0.283133,-0.005428,-0.097963,-0.448482,-0.307972,-0.529798,-0.070923,-0.233629,-0.259001,0.146516,0.050673,-0.185133,0.628609,-0.955456,0.408856,0.580569,0.344459,-0.247677,0.732116,-0.180368,0.020181,-0.239839,-0.009055,0.399754,-0.135249,0.210253,0.089339,0.177344,-0.222774,0.226993,-0.585786,0.226340', '1467779', '2301363', '21619567', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417073', '最后的吸血鬼', '动作', '该片是押井守参与制作的一部动画电影。获2002年斯图加特国际动画电影节最佳长篇奖，获2001年日本文化厅文化厅MEDIA艺术祭动画大赏。1966年秋天，越南战争期间，在日本国内的美国空军横田基地内，不时可见F4幻影战斗机频繁起降，空气中充斥着一股杀戮的气氛；就在此时，基地附近的市区连续发生了离奇的命案。 地下铁，银座线，正驶著通往浅草的最后一班列车，一名少女出现在空荡的车厢内，她拥有令大人感到刺眼的眼神，紧闭着双存欲诉说她内心的真正意念，她的名字叫小夜(SAYA)；她是“组织”为了打倒潜伏于人类社会里的吸血鬼“翼手”，因而派遣至人类社会的救世主。 穿着水手服的小夜，手持日本武士刀作为武器，潜入了基地内的美国学校。一柄冷血无情的武士刀，是她消除邪魔、保护人类的武器。而她身体里这一半的人性，可能就是她打败敌人的秘诀……©豆瓣', '工藤夕贵', '北久保弘之', 7.7, 10173, 'tt0275230', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p454191636.jpg', 0.6, 2.9, 29.2, 43.4, 23.8, '0.028928,0.184168,-0.651772,0.652977,0.152404,0.286247,0.644286,-0.070969,-0.328805,-0.206840,0.450425,0.480557,0.057310,0.079916,0.111421,-0.070947,-0.103165,-0.609280,-0.353433,-0.272822,-0.249956,0.027422,-0.462814,-0.295166,-0.077191,-0.364152,0.823597,0.345731,-0.242752,0.283003,0.104950,0.317003,-0.122016,0.246069,-0.071273,-0.328669,0.220670,-0.157487,-0.011168,0.305502,-0.283369,-0.289042,-0.108586,0.233041,-0.145271,0.185270,0.813931,-0.171587,0.059303,-0.342074,0.463245,-0.157591,-0.195534,-0.170228,0.377487,0.119146,0.040365,0.131612,-0.076974,0.135453,0.011237,-0.114481,-0.597588,-0.050984,-0.197355,0.126980,-0.249837,0.433318,-0.226265,0.077191,0.057460,-0.243874,0.231719,-0.123547,0.251918,0.260332,-0.182376,0.067551,-0.443964,0.306620,0.574233,-0.398611,-0.552586,0.207674,-0.432009,-0.495688,-0.395467,-0.279392,-0.282298,-0.352139,0.229217,-0.079375,-0.102286,0.292993,-0.552128,0.239091,-0.017070,-0.287796,-0.041531,-0.037020,-0.114374,-0.714557,-0.080402,-0.380639,-0.090686,0.039679,0.110103,-0.001221,0.696935,-0.619503,0.161575,0.791238,0.260413,-0.110894,0.612287,-0.077108,0.047271,0.070863,-0.232496,0.254200,-0.013091,0.443971,-0.094535,0.359092,-0.087154,-0.087094,-0.253731,0.421486', '3811356', '10467125', '1322847', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417084', '黑暗扫描仪', '科幻', '不久的未来，毒品泛滥已经失去控制，一种极易上瘾的非法药品“D药丸”在美国境内流行，政府当局只好利用高科技监视系统对抗失控的局面。卧底的缉毒探员弗瑞德（基努•里维斯 饰）化名巴布•亚特，试图追踪毒品来源，这样，他与小毒贩唐娜•霍桑（薇诺娜•瑞德饰）、吸毒者吉姆•贝芮斯（小罗伯特•唐尼饰）、厄尼•洛克曼（伍迪•哈里逊饰）、查尔斯•费克（罗瑞•考克兰饰）等人住在一起。但实际上，弗瑞德也被“D药丸”的毒瘾深深吸引。随着毒瘾越来越深，他逐渐模糊现实与虚假间的界线，失去神智的弗瑞德，不断追寻大毒枭的隐藏之处，毫不知情自己一直置身于幕后黑手的摆弄。©豆瓣', '罗利·科奇瑞恩', '理查德·林克莱特', 7.2, 8658, 'tt0405296', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193981166.jpg', 1.1, 5.9, 37.9, 40.9, 14.3, '0.254723,0.027819,-0.551535,0.400373,0.017260,-0.089624,0.803469,0.163112,-0.489174,-0.208981,0.169263,0.527225,-0.117438,-0.246160,-0.002081,0.186006,-0.601613,-0.631824,0.026492,-0.043925,-0.154714,-0.539781,-0.726054,-0.245321,-0.255150,-0.199590,0.470119,0.060490,-0.313749,0.128404,0.162323,0.516837,-0.138330,0.163520,0.265982,-0.216795,0.545261,-0.575336,-0.235532,-0.171753,0.245843,-0.196042,0.013035,0.055944,-0.005142,0.418225,0.489744,-0.343984,0.042188,-0.293054,0.098965,-0.361541,-0.117412,-0.073489,0.036222,-0.011753,-0.121248,-0.105833,-0.384373,-0.063806,0.133899,0.144989,-0.503403,0.094887,-0.031024,0.351840,-0.106397,-0.023662,-0.224719,0.047662,0.048588,-0.340727,-0.068243,0.276766,0.156834,-0.001446,-0.104028,-0.131499,-0.459025,0.019810,0.289937,-0.072350,-0.504265,0.132589,-0.352666,-0.398838,-0.146098,-0.090412,-0.432695,-0.217099,0.581163,-0.091746,-0.269248,0.803087,-0.437362,-0.018975,-0.551390,-0.160388,-0.204421,-0.027911,-0.095256,-0.652592,-0.379770,-0.319673,0.061461,-0.038582,0.160776,-0.024158,0.301523,-0.587592,0.308027,0.680530,0.066067,-0.177503,0.066020,-0.159634,0.038452,-0.448510,-0.508013,0.558275,0.237879,0.234685,0.374282,0.363838,0.047312,0.027152,-0.112264,0.185093', '1316693', '2091015', '1292528', '25955779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417304', '无味神探', '剧情', '警员阿海（刘青云 饰）事业上精明能干，但与妻子（李若彤 饰）的关系十分恶劣，妻子更怀上了别人的孩子，婚姻濒临破裂。阿海在与歹徒搏斗的时候脑部中枪，自此失去了味觉。妻子全力照顾，两人的关系也开始转好。没想到该歹徒逃脱成功，并绑架了阿海的妻子要挟阿海出现，在枪林弹雨中与歹徒时，阿海才发现自己一生中最爱的人还是自己的妻子。歹徒挟持着妻子，并告诉阿海房间内已充满了煤气，只要阿海开枪便会爆炸，事实上阿海已经失去了味觉……©豆瓣', '刘青云', '杜琪峰', 6.7, 6101, 'tt0114991', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1925461823.jpg', 0.8, 6.4, 55.2, 30.5, 7, '0.080153,-0.217766,-0.498346,0.281348,-0.127663,-0.459609,0.898017,-0.039750,-0.652806,-0.285451,0.219211,0.651414,0.054616,0.224357,0.334366,0.043753,-0.246491,-1.027047,-0.067344,0.171486,-0.586199,-0.381716,-0.012108,-0.097289,-0.115818,-0.249240,0.608640,-0.045349,-0.159093,0.227666,0.183692,-0.133941,-0.195141,0.770483,0.037995,0.186019,-0.162914,-0.109513,-0.519429,0.119972,0.181606,-0.311188,0.229965,0.438915,-0.333832,0.450737,0.540157,-0.293326,-0.132845,-0.466418,0.112003,-0.013707,-0.084726,0.131897,0.307483,-0.111357,0.412734,0.161629,-0.181214,-0.080444,0.067712,0.138158,-0.428033,-0.002309,0.039573,-0.155070,-0.623884,0.331482,0.004551,0.179926,0.210718,-0.131238,0.285246,0.224681,0.112419,0.256651,-0.652807,-0.229638,-0.405118,-0.075122,0.569523,-0.237546,0.120216,0.429550,-0.147104,-0.463423,-0.057036,-0.207054,-0.522313,0.080465,0.265874,0.465053,-0.564368,0.388771,-0.167326,0.075365,-0.207904,0.229316,-0.266885,-0.400944,0.154641,-0.269276,-0.197575,-0.315631,-0.407334,0.306708,-0.094885,-0.262765,0.393680,-0.971063,0.201406,0.212339,0.388882,-0.369685,0.300920,0.187198,0.208998,-0.519670,-0.210400,0.308955,-0.010170,0.013007,0.130700,0.077215,-0.197547,-0.016064,-0.101448,0.404518', '30345227', '1308755', '1301022', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417309', '剧场前', '剧情', '怀才不遇的导演金东秀（金相庆 饰）每天都流连在戏院前，沉醉在自己的思维里。最近他刚好看了好友的一部电影，他会觉得电影的情节便是自己的故事。与此同时。他遇到了电影中的女主角崔英实（严智媛 饰）。后来东秀在出席一个电影人聚会的路上，再次遇到了崔英实。英实正被影迷索要签名，东秀终于鼓起勇气上前问候。©豆瓣', '李己雨', '洪常秀', 7.4, 5778, 'tt0461795', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p606123335.jpg', 0.7, 4.9, 33.8, 45.1, 15.4, '0.276452,-0.071999,-0.556463,0.594663,0.559503,-0.328685,0.733873,0.169135,-0.290432,-0.155982,0.389858,0.866304,-0.466404,0.375822,0.432638,-0.095356,-0.422969,-0.903905,-0.209552,0.029069,-0.182643,0.094040,-0.270860,-0.011909,0.086642,-0.142462,0.493193,0.046734,-0.248474,0.407307,0.432568,-0.057535,-0.027370,0.532834,-0.044169,0.393701,0.237521,0.235645,-0.046771,0.200395,0.268289,-0.537346,-0.196178,0.084891,0.009574,0.363702,0.651188,-0.039278,-0.008963,0.103270,0.444992,-0.088787,-0.081341,0.049530,0.015718,0.429128,0.705234,-0.102201,-0.160608,0.328014,-0.213314,-0.109956,-0.721525,0.189218,0.143181,0.372695,-0.466694,0.454503,0.052999,0.124107,0.091109,-0.324046,0.298369,-0.050215,0.487161,0.270735,-0.122643,-0.150731,-0.225594,0.676600,0.390965,0.304918,0.130152,0.820134,-0.186812,-0.416918,-0.082211,0.118855,-0.594769,0.257154,0.433453,-0.307609,-0.145844,-0.023726,-0.517886,-0.061440,0.232340,-0.281307,0.045825,-0.263784,-0.129121,-0.934876,-0.031174,-0.279890,-0.013060,-0.172907,0.057093,-0.301514,0.679060,-0.578539,-0.039690,0.712688,0.205224,-0.404571,1.033684,0.024115,-0.204649,0.125076,0.129284,0.007726,-0.210729,0.407871,0.147049,0.401981,-0.079876,-0.470298,-0.540308,0.569268', '2027945', '30162520', '3318306', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417428', '蓝', '剧情', '导演德里克·贾曼的辞世遗作《蓝》，记录下了他罹患艾滋后的最后岁月。此时的贾曼已经双目失明，面对他的是死亡的颜色——这忧郁的蓝。影片从始至终都是满眼的蓝色，也是唯一的颜色。无画面无情节，也没有对白没有人物，除了诗性的背景音乐和贾曼宁静安详的自白。贾曼用这种极端的“反电影”形式，向我们讲述他最后的岁月：是嘈杂烦躁的医院声，也是岸边孤独深沉的海浪声；是他面对死亡时毫无怨言的沉默，也是他不舍离开深爱恋人的不忍与决绝。他说：“我献给你们这宇宙的蓝色，蓝色，是通往灵魂的一扇门，无尽的可能将变为现实”，这也是贾曼与世长辞时，留给我们最后的“蓝色”。©豆瓣', '约翰·昆汀', '德里克·贾曼', 8.6, 8310, 'tt0106438', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2042159738.jpg', 1.3, 1.7, 11.8, 36.4, 48.8, '-0.011147,0.183603,-0.723081,0.969226,-0.059413,-0.108931,1.508995,0.169701,-0.528721,-0.058040,0.089749,0.674986,-0.040254,0.194283,-0.125743,0.306761,-0.463319,-0.790499,-0.409331,-0.030029,-0.264415,-0.573305,-0.292752,-0.104868,0.108773,-0.228644,0.792999,0.535032,-0.283604,0.314649,0.502817,0.362500,-0.071262,0.767858,-0.098086,0.019828,-0.332706,0.131642,-0.005197,-0.070033,0.238217,-0.205190,-0.186322,0.309042,-0.182239,0.597687,0.518173,-0.011870,-0.246828,0.245022,0.336576,-0.376700,-0.115991,0.116821,0.084954,-0.274530,0.243827,0.206298,-0.086340,-0.340177,-0.127773,0.290652,-1.082154,0.169385,-0.054865,0.535956,-0.487125,0.750694,-0.120731,-0.459895,0.218943,-0.116747,0.328504,-0.107339,0.294165,0.401715,-0.078590,-0.194257,-0.342607,0.412609,0.535209,0.167082,-0.566527,0.640171,-0.618966,-0.497591,-0.245221,-0.349196,-0.445426,0.062561,0.360538,0.362606,-0.220590,0.175060,-0.596958,0.085667,0.028932,-0.481328,-0.255629,-0.480727,-0.227890,-0.257248,-0.149111,-0.846352,-0.835462,-0.013625,-0.000259,-0.163036,0.691458,-0.686077,0.375560,0.201305,0.184907,-0.306415,1.029689,0.083616,-0.288047,0.076526,0.191987,0.414404,-0.221846,0.383331,0.351738,0.411179,0.257721,0.223446,-0.588063,0.728962', '1304862', '1303077', '2131640', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417543', '情迷大话王', '喜剧', 'OK赖（黎明 饰）以说谎话而为人所知，一天他在便利商店认识了Wonderful（张栢芝 饰）。OK是一名地产经纪，到Wonderful所在的公司洽谈业务，却被Wonderful及其朋友误以为OK是公司老板的一位身家斐然的表弟。OK将计就计，决定要骗着Wonderful，一边跟公司老板的妹妹谈情。Wonderful的父亲欠下了赌债，OK发散了朋友帮助Wonderful还债，令Wonderful感动不已。纸包不住火，最终Wonderful都知道了OK的谎言，伤心离开。OK为了挽留她，承诺以后不再说慌。在Wonderful将要原谅OK之际，OK却被诱惑假结婚以得到高额的报酬……©豆瓣', '黎明', '王晶', 6.1, 6562, 'tt0355323', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2531745552.jpg', 2.3, 15.6, 60.4, 16.3, 5.5, '0.000914,0.144921,-0.510769,0.448795,-0.234631,-0.487212,0.314700,0.425914,-0.354146,-0.164882,0.119184,0.717988,0.065395,0.402108,0.306030,-0.077574,0.229471,-0.276301,0.170383,-0.440705,0.127492,-0.724958,0.191993,0.059464,-0.377035,-0.237468,0.308224,0.130889,-0.314992,0.241794,0.612983,0.133803,0.034660,0.395261,0.092432,-0.182288,-0.012797,0.301786,-0.574364,0.137873,0.225216,-0.381472,0.012603,0.204985,0.261044,0.359993,0.225050,0.028300,-0.277008,0.098480,0.310457,-0.464488,0.355690,0.105193,0.182773,-0.020151,0.395785,0.311764,-0.668396,-0.187612,0.296681,0.013700,-0.935306,-0.066917,0.159174,0.034721,-1.021275,0.292759,-0.284463,0.127753,0.092985,-0.479596,0.290164,0.406410,0.162692,0.304044,-0.004958,0.264115,-0.746777,0.360124,0.728381,0.034152,0.250420,0.416319,0.037702,-0.123820,-0.027241,-0.079358,-0.492586,0.038788,-0.024466,-0.025113,-0.174362,-0.209680,-0.379351,-0.372906,-0.242468,-0.222334,0.136489,-0.714120,-0.002287,-0.041543,-0.240955,0.055373,0.071422,0.297403,0.175921,-0.339220,0.541639,-0.834709,-0.105855,0.737379,0.768146,-0.876411,0.726609,0.243860,-0.061587,-0.312072,0.034689,-0.153177,0.176063,0.128644,0.345890,-0.095634,0.317574,-0.258491,-0.189027,0.013150', '1877596', '1299649', '1304382', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417555', '冬荫功', '剧情', '纯朴善良的青年阿锦（托尼·贾 Tony Jaa 饰）自幼生长在泰国一个原始丛林中，村民们日出而作，日落而息，过着平和安静的生活。他们以大象作为交通工具和助手，人与动物间建立了深厚的友情。阿锦的父亲曾是一名皇家护卫，他在闲暇之余教儿子学习泰拳，好有朝一日进宫保卫国王。父亲精心饲养大象，在泼水节当天拜托村长将大象献给国王。谁知村长图谋不轨，将大象转手卖给黑帮，企图销往澳洲牟取暴利。他们不择手段，还打伤了阿锦的父亲。愤怒的年轻人只身闯入黑帮老巢，与这群不法之徒展开大战。当得知大象正被送往悉尼，阿锦毫不犹豫，只身前往，由此踏上一条充满死亡危险的道路……©豆瓣', '托尼·贾', '普拉奇亚·平克尧', 7.4, 21207, 'tt0427954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2029269446.jpg', 0.8, 4.7, 34.6, 44.3, 15.6, '0.039156,-0.062653,-0.650026,0.596119,-0.162948,-0.104871,0.555697,-0.112906,-0.510737,-0.115909,0.295879,0.702590,0.177350,0.145173,0.333759,-0.090046,-0.166590,-0.347094,-0.308882,0.099486,-0.105995,-0.249743,-0.284374,-0.380629,-0.056196,-0.297475,0.447559,-0.197898,-0.312192,0.625768,-0.006687,0.283710,-0.390991,0.166457,-0.640655,-0.088922,0.019558,-0.063212,-0.411037,0.022202,-0.260893,-0.201785,-0.095649,-0.176805,0.083107,0.136301,0.647174,-0.290387,-0.130472,-0.391326,0.152819,-0.202111,0.130403,0.254180,0.386504,-0.029712,0.060653,0.205966,-0.066971,0.067760,-0.099118,-0.430797,-0.335830,-0.244161,-0.089849,-0.043686,-0.736401,0.337194,0.156083,0.049443,0.233139,-0.408504,0.213857,0.330310,-0.074053,0.368235,0.225862,0.262318,-0.523810,0.184132,0.997649,-0.214950,0.110610,-0.276044,-0.107002,-0.426333,0.404461,-0.244280,-0.432250,-0.160662,0.498933,-0.289757,-0.294367,0.181542,-0.728889,-0.171943,-0.147177,-0.081841,0.292269,-0.214634,-0.177504,-0.494164,0.222422,-0.270480,-0.170929,0.174957,0.185265,-0.206976,0.739821,-0.685684,0.443613,0.447022,0.351267,-0.500872,0.520611,-0.268535,0.252183,-0.169137,-0.234534,0.128722,0.517177,0.451413,0.251934,0.135201,-0.209397,-0.028109,-0.182529,0.237260', '25721544', '26280899', '1308035', '1458900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417598', '电锯惊魂', '悬疑', '一觉醒来的亚当（雷•沃纳尔 Leigh Whannell饰）发现自己被困在一个废弃的厕所里。他的对面是同样命运的劳伦斯（加利•艾尔维斯 Cary Elwes 饰）——他们被人用铁链绑住了腿，并吃惊发现二人中间横亘着一个恐怖的死人。死人鲜血淋漓，左手拿录放机右手拿枪。亚 当兜里被人放进来一盘磁带，他赶紧放到录放机里。磁带里说，劳伦斯必须在今晚6点前杀死亚当，否则二人将同归于尽，劳伦斯的家人也不能幸免。而面前死人流出来的血，剧毒无比。一个血腥的死亡游戏开始了。在剩下不多的时间里，他们必须找到线索，逃出地狱。在最后关头，当他们以为重见天日的时候，新一轮的噩梦才刚刚开始。©豆瓣', '雷·沃纳尔', '温子仁', 8.8, 492905, 'tt0387564', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p726839485.jpg', 0.4, 0.9, 10.5, 37.3, 50.9, '0.225771,0.194354,-0.803635,0.266587,-0.228738,-0.230460,1.029257,-0.167707,-0.223828,-0.146170,0.269082,0.709341,-0.097996,0.294642,0.050249,-0.000367,-0.194644,-0.770231,-0.124178,-0.302246,-0.832483,-0.201680,-0.337642,-0.122965,0.099822,-0.028478,0.389587,0.185064,0.061555,0.415772,0.336340,-0.136619,-0.066892,0.443594,-0.257346,0.041296,-0.207583,-0.420434,-0.017332,0.277420,0.025489,-0.242094,-0.046689,0.482539,-0.025877,0.384778,0.648443,-0.423980,0.281463,-0.073336,0.126996,-0.341677,-0.369814,0.092409,0.285603,0.020524,0.243761,-0.042356,-0.374478,0.197279,0.387104,0.025737,-0.847232,-0.034391,-0.471971,0.367863,-0.482550,0.259168,-0.107515,0.223163,0.050651,-0.227273,0.508322,-0.123430,0.277791,0.282205,-0.348892,-0.294952,-0.675915,-0.128535,0.441375,-0.414330,0.029625,0.127055,0.094542,-0.207996,-0.068004,-0.256734,-0.166037,-0.225850,0.565461,0.134803,-0.429162,0.002876,-0.441236,-0.060160,-0.068048,-0.027552,-0.207936,-0.263557,-0.337461,-0.335583,-0.031528,0.041382,-0.243677,0.371149,-0.180784,-0.250369,0.430810,-0.188155,0.213890,0.444891,0.312959,0.178109,0.507463,0.004072,0.292189,0.045246,-0.045812,0.130835,0.458975,0.509742,0.696069,0.390778,-0.099005,0.023935,-0.662371,0.557392', '1297996', '21619567', '26342391', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417728', '我的邻居山田君', '喜剧', '住在山野市的山田家共有五口人：一家之主山田隆年届不惑，是一间小公司杂物课的职员。他有些大男子主义，经常为了些琐事和老婆吵吵闹闹，却又被丈母娘压得抬不起头来；阿隆的妻子松子和丈夫同岁，是个全职的家庭主妇，每天忙忙碌碌，照顾一大家子人的饮食起居，却又迷迷糊糊，经常丢三落四；松子的母亲年近古稀，然而精神矍铄，这位老人家一向特立独行，讲话毒辣，连暴走组也全不畏惧；长子阿升是个长相和学习都平平的中学生，他继承了母亲迷糊的性格，生活中乐事不断；小女儿野野子还是个小学三年级学生，瘦瘦小小的她碰上一群脑瓜秀逗的家人，经常成为被遗忘的对象。就是这样一个平凡的山田家，每日里上演着妙趣横生、欢乐无穷的精彩生活秀。本片根据石井壽一（いしい ひさいち）四格漫画《ホーホケキョ となりの山田くん》改编。©豆瓣', '朝丘雪路', '高畑勋', 8.8, 50803, 'tt0206013', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p462372509.jpg', 0.2, 0.8, 10.6, 36.9, 51.5, '0.297007,-0.329602,-0.459082,0.399554,-0.477757,-0.273966,0.583319,0.302156,-0.518699,-0.481254,0.043711,0.688186,-0.167330,0.695847,-0.011636,-0.065166,-0.033159,-0.364441,-0.265921,0.096998,0.139261,-0.134309,0.000979,-0.195454,-0.200075,-0.074158,0.347021,-0.270628,0.019425,0.340816,0.180550,0.097208,0.042929,0.180514,-0.283268,0.134241,-0.080101,0.043955,0.292814,-0.093007,-0.142944,-0.004024,-0.280190,-0.057949,0.177509,0.356704,0.565154,0.074884,-0.226175,-0.143478,0.403667,-0.121769,-0.316805,0.348228,0.656000,-0.174985,0.340994,-0.013422,-0.138751,0.230824,-0.055387,-0.209542,-0.558744,-0.038024,0.317775,0.073223,-0.656939,0.583809,0.198180,-0.292880,-0.068505,-0.263625,0.135358,0.059767,0.056316,0.711253,-0.102493,0.268062,-0.288097,0.351272,0.564572,0.145495,-0.226347,0.262609,-0.299340,-0.082177,0.300014,-0.595724,-0.717061,-0.035931,-0.054026,-0.334552,-0.062226,0.175991,-0.325937,0.262239,0.153362,-0.147634,-0.088812,-0.463922,-0.170373,-0.404466,0.109229,-0.570376,-0.220407,0.094770,0.255170,-0.252547,0.875114,-0.782788,0.005189,0.457906,0.005898,-0.306594,0.791470,0.174929,0.018163,-0.259324,-0.145491,-0.111775,0.169001,0.058845,0.108123,0.580582,-0.203412,-0.263298,-0.234176,0.412785', '26348103', '1292720', '25738406', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417753', '舞女纯情', '剧情', '永塞（朴建衡 饰）在一次舞蹈比赛中被对手故意弄伤，自此被迫放弃跳舞事业，终日无所事事。经营舞蹈室的老板不忍永塞浪费了才华，邀请永塞重出江湖，更安排了一名从中国吉林的朝鲜族女孩张彩敏作为永塞的舞伴。永塞十分重视舞伴的到来，他也希望这是他重振名声的机会。当他亲自迎接舞伴时，到来的却是彩敏的妹妹彩琳（文根英 饰），因为姐姐快要出嫁了，彩琳便代替了姐姐。令永塞十分震惊的是，彩琳对舞蹈一窍不通，感觉被骗了的永塞愤怒之极。距离全国大赛只有三个月的时间，永塞决定将彩琳训练为舞蹈的高手……©豆瓣', '文根英', '朴英勋', 6.8, 15863, 'tt0464636', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1247929204.jpg', 0.7, 6.4, 52, 32, 8.9, '-0.196638,-0.050174,-0.392154,0.482429,-0.242906,-0.357690,0.264188,0.086523,-0.614293,-0.343146,0.216322,0.635756,-0.321383,0.312479,0.340557,-0.185150,0.005600,-0.755321,-0.119053,-0.213805,-0.136197,-0.030526,0.224442,0.014134,-0.092211,-0.410574,0.591121,-0.037268,-0.234596,0.603253,0.403429,-0.105522,0.285258,0.402517,-0.033211,-0.300223,0.144000,-0.085532,-0.183574,0.257235,-0.032257,-0.305878,-0.045054,0.243990,0.038237,0.184429,0.754633,0.010156,-0.033611,-0.289392,0.416739,-0.272881,0.107772,0.202480,0.200637,0.021295,0.250508,0.102571,-0.161107,-0.064304,0.007610,-0.311307,-0.855214,0.452524,0.173672,-0.084228,-0.710786,0.551908,-0.191998,-0.076049,0.044187,-0.208168,0.293211,0.373844,0.269344,0.265822,-0.308486,0.107595,-0.283288,0.241666,0.673181,-0.021722,0.202226,0.417924,-0.076705,-0.359991,0.278134,-0.318310,-0.281688,0.109635,0.072039,0.022163,0.083384,-0.036364,-0.363880,-0.145383,-0.127723,-0.238920,0.077747,-0.635297,0.114866,-0.514012,0.130064,-0.092424,-0.276805,0.102541,0.130107,-0.200950,0.809636,-0.889806,0.055102,0.413510,0.348087,-0.469164,0.751116,0.224083,0.017205,-0.170400,-0.090145,0.023682,-0.210462,0.068130,0.053093,0.454483,0.110994,-0.412782,-0.461609,0.436045', '4127270', '35030151', '3811356', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1417999', '父子老爷车', '喜剧', '忠厚老实的老奎（陈强 饰）和儿子（陈佩斯 饰）在改革的浪潮中下海了。岂料父子俩开店不成，在下海浪潮中被呛得人仰马翻。不甘心失败的老奎拿出了积蓄的两千元，买来了一辆四十年代老车，准备干出租。谁知好不容易买回来的车子竟然不能办理营运执照，父子俩再次傻了眼。恰巧这时某特区的任总经理想用老奎父子俩的车子开办旅游项目，于是和他们签订了特区开发合同。父子俩在特区人生地不熟，开着那辆老旧的汽车，上演了一幕幕既搞笑、又心酸的闹剧……©豆瓣', '陈强', '刘国权', 7.3, 9825, 'tt0350968', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2230073755.jpg', 0.6, 3.2, 40.4, 42.7, 13.1, '0.421356,0.138765,-0.799823,0.176652,0.092934,-0.474118,0.314386,0.412365,-0.478926,0.058561,0.217932,0.571695,-0.150069,0.051033,0.325389,-0.052042,-0.245062,-0.442437,-0.100720,-0.085151,0.048691,-0.236155,-0.130356,-0.214394,0.090125,0.065001,0.284462,0.287576,-0.008299,0.469592,0.453888,-0.000702,-0.341374,0.234685,-0.213807,0.185997,0.186348,0.217555,-0.082335,0.092571,-0.109579,-0.399427,0.110043,-0.344707,0.413096,0.422119,0.620079,0.274489,-0.092015,-0.060914,0.223786,-0.254520,-0.173633,-0.009122,0.087067,0.387719,0.142579,-0.033733,-0.380954,-0.105331,0.235477,0.008555,-0.380262,0.071296,-0.405278,-0.197882,-0.935302,0.427714,-0.233694,-0.082939,-0.213459,-0.291743,0.417102,0.281431,0.313631,0.784822,0.102845,0.251834,-0.765479,0.443914,0.640342,-0.032522,0.066722,0.560154,-0.001082,-0.096974,0.125843,-0.283950,-0.300577,-0.380143,0.703877,-0.285105,-0.148304,-0.239533,-0.669545,-0.053480,-0.288618,-0.313015,0.069719,-0.082587,-0.270712,-0.556804,0.031846,-0.216986,0.122278,0.256972,-0.029096,0.032688,0.292577,-0.545388,-0.201227,0.227626,0.291535,-0.396901,0.421214,-0.026734,0.097061,-0.038911,0.118096,-0.545498,0.078318,0.628301,0.358729,0.294299,-0.071941,-0.386961,-0.286869,0.141870', '1306505', '1299965', '25837175', '1303462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418019', '大闹天宫', '剧情', '话说在东土傲来国有一座花果山，山上有一尊石猴吸收日精月华化身为一只神猴（邱岳峰 音），统领着山中的猴子猴孙。为求得一件称心的宝贝，神猴孙大圣潜入龙宫，强硬求来大禹治水时的定海神针如意金箍棒。东海龙王（毕克 音）心有不甘，于是上天将此事诉诸玉帝（富润生 音）。玉皇大帝命令太白金星（尚华 音）下界招安，许以爵位。不知有诈的孙大圣欣然前往，却发现只是负责养马的弼马温。得知受骗的猴王反下天庭，与天兵天将在花果山展开大战……本片根据古典名著《西游记》中的故事改编，前后历时4年创作，并荣获1962年捷克斯洛伐克卡罗维发利国际电影节短片特别奖、1978年英国伦敦国际电影节年度杰出电影奖、1982年厄瓜多尔第四届国际儿童电影节三等奖、第二届中国电影“百花奖”最佳美术片奖。©豆瓣', '邱岳峰', '万籁鸣', 9.4, 399566, 'tt0059855', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2184505167.jpg', 0.1, 0.3, 4.1, 21.4, 74, '-0.245143,0.259357,-0.390757,0.817283,0.593334,0.074151,0.060257,0.000035,-0.467543,-0.081109,0.039874,0.660098,-0.327459,-0.111901,-0.023350,0.162977,-0.206471,-0.346717,-0.048050,-0.026932,0.431435,-0.038570,-0.154766,0.153023,-0.268823,-0.162551,0.595188,-0.094671,0.042083,0.404009,0.364790,-0.052097,-0.054874,-0.123497,-0.207183,0.296774,-0.097516,0.309340,-0.002849,0.316607,-0.244386,-0.246555,-0.455138,-0.091455,0.165363,0.097398,0.283776,-0.432825,-0.016100,-0.220188,0.550587,-0.237753,-0.051289,-0.309818,0.355227,0.253503,0.111208,0.442498,-0.085339,0.194740,0.145542,-0.433429,-0.124179,0.050943,-0.139021,0.140375,-0.081844,0.294860,0.032280,0.428527,-0.283820,-0.251498,0.193848,0.126760,0.300291,0.393205,0.084932,0.144567,-0.372345,0.640200,0.363736,-0.289253,-0.117808,-0.019256,0.169259,-0.701544,-0.023817,-0.309251,-0.064030,0.166756,0.380531,-0.146706,0.073121,0.142877,-0.192469,-0.223404,-0.129791,0.019545,-0.029421,-0.123301,-0.077821,-0.491367,-0.029034,0.190282,0.036172,-0.499625,0.396722,0.100634,0.668354,-0.387742,0.188332,0.353782,0.135632,0.017210,0.837164,-0.105258,-0.025910,-0.233486,-0.110892,0.070495,-0.361986,0.091653,-0.074560,0.009016,0.040535,-0.326436,-0.073234,-0.118858', '1307315', '1302279', '22265121', '2338019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418070', '如果·爱', '剧情', '想演戏的孙纳（周迅 饰）与想导戏的林见东（金城武 饰）初遇见时，两人都正处于生活与事业的低谷，在相互鼓励和扶携中，他们渐渐有了共同的可以看见希望的未来，然而孙纳更想把现在的可能抓到手，狠心与林见东分了手，跟了可以给她戏的导演聂文（张学友 饰），成为人人艳羡的大明星。天意弄人，十年后孙纳与也做了演员的林见东因为一部合拍戏又重遇。虽努力说服自己忘记过去，却欺骗不了自己的心，孙纳陷入两难中。而更戏剧的是，孙纳、林见东和聂文要同演一出剧情与他们之间情恨纠葛惊人相似的戏。©豆瓣', '金城武', '陈可辛', 7.7, 231424, 'tt0454914', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p461379838.jpg', 0.5, 2.9, 28.9, 45, 22.8, '0.260365,-0.099250,-0.742857,0.619974,0.340623,-0.350511,0.793541,0.101441,-0.346326,-0.025957,-0.198125,0.762883,-0.304679,0.035192,0.420782,-0.213154,-0.472084,-1.191892,-0.100061,0.081572,-0.297262,-0.454556,-0.397454,0.034744,-0.380162,0.023091,0.616765,0.343047,-0.302392,0.509637,0.525437,0.228919,-0.130367,0.402181,-0.114913,-0.059097,-0.379089,0.316877,-0.490980,0.062285,0.233767,-0.274558,-0.487695,0.304673,0.034066,0.366731,0.499471,-0.249635,-0.080416,0.194173,-0.037723,-0.380684,-0.289227,0.170938,-0.035002,0.031783,0.517978,0.095577,-0.296863,0.054660,0.044738,-0.158508,-1.024342,0.259519,0.049133,0.053857,-0.550386,0.492065,0.232816,-0.198220,0.188437,-0.147590,0.292738,0.370273,0.390608,0.476755,-0.319041,-0.289871,-0.433080,0.292176,0.730371,0.268459,0.009767,0.576081,0.113225,-0.371958,-0.285262,-0.307038,-0.408048,0.102930,0.217277,0.269363,-0.135200,0.213547,-0.418149,0.134747,-0.171046,0.017048,0.010513,-0.770376,0.084189,-0.306950,-0.293288,-0.686141,-0.170123,0.212936,0.289123,-0.497687,0.698648,-0.850678,-0.041450,0.005934,0.511109,-0.624394,0.850634,0.332936,0.023915,-0.175191,-0.142018,-0.181564,-0.346859,0.138189,0.573310,0.308612,-0.077473,-0.196003,-0.595356,0.345110', '4301278', '1418613', '25777330', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418076', '天堂回信', '剧情', '1990年代，北京。晨晨（石晨 饰）的爸妈在国外工作，他平日与爷爷（李丁 饰）一起生活。爷爷干了一辈子邮政工作，退休后与孙儿相依为命。一天，祖孙俩把一封已故去的收信人的信件系在风筝上放飞天空，爷爷告诉晨晨：他在天堂会收到的。不久，妈妈（肖雄 饰）从国外回来了，她看不惯公公对晨晨的放任，每天给晨晨布置了英语、钢琴等课程，原有的平静不见了，爷爷搬回了自己的旧居。晨晨日夜思念爷爷，他恨透了什么英语钢琴，整天哭闹不休，妈妈见此若有所思。爷爷的生日到了，晨晨与好伙伴琳琳送来生日贺卡祝福，爷爷带他们外出放风筝，劳累一天后，在孩子们的欢笑声中，爷爷竟然永远“睡”去了......本片获德国第43届柏林国际电影节国际青少年儿童影视中心奖；美国第10届芝加哥儿童电影节最佳影片奖；荷兰第7届儿童电影节最佳影片大奖；伊朗第25届伊斯法罕儿童电电影节最佳导演金蝴蝶奖。©豆瓣', '石晨', '王君正', 9.2, 37818, 'tt0334505', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2869825054.jpg', 0.2, 0.4, 6.4, 27.2, 65.9, '-0.348277,-0.105593,-0.847372,0.466618,0.120284,-0.483745,0.024368,0.281533,-0.479457,0.049855,-0.026755,0.806925,-0.004008,0.544953,0.199138,0.029166,-0.431712,-0.515969,-0.024207,-0.180314,-0.082151,-0.210884,0.164096,0.155145,0.058150,-0.156174,0.069253,-0.350916,0.356488,0.690190,0.325127,-0.237705,-0.087726,0.078353,-0.219443,0.194102,0.278110,0.244030,-0.535656,0.225567,0.222527,-0.000921,-0.021041,-0.274960,0.507447,-0.313170,0.744197,0.124069,0.140670,-0.022976,0.530760,-0.133366,-0.287066,-0.106440,0.390324,0.117028,0.314629,0.226456,-0.134934,0.264854,-0.254275,-0.154013,0.068082,0.009554,-0.012572,0.026279,-0.595957,0.514347,-0.186887,0.244590,0.013711,-0.395511,0.568357,0.377728,-0.205579,0.277828,0.048904,0.201854,-0.136789,0.612689,0.337645,-0.326410,0.015120,0.027027,0.024797,-0.065073,0.285899,-0.141182,-0.443013,0.300144,0.249213,-0.322479,-0.270077,0.100296,-0.419981,-0.116355,0.119671,-0.365205,0.170307,-0.253092,-0.081977,-0.561578,0.342479,-0.274314,-0.081860,-0.106023,0.146565,-0.044134,0.758785,-0.445876,0.715406,0.325501,0.316390,-0.116075,0.654062,0.099549,0.184490,-0.094509,0.246810,-0.061591,-0.244764,0.398085,0.041725,0.164476,0.134452,0.002930,-0.312318,0.198064', '6814906', '1291976', '1308609', '3155839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418179', '电车男', '喜剧', '网名“电车男”（山田孝之 饰）的他是一个热爱漫画和卡通的大男孩，他在一家公司做推销员，为人羞涩内向，业余时间或者流连于秋叶原的游戏店，或者在家登陆单身留言板和同好聊天。某天傍晚，在乘电车回家的路上，一个美丽的女孩（中谷美纪 饰）被醉酒的大叔（大杉涟 饰）骚扰，电车男出手相助。在此之后，女孩出于感激送给电车男一套名贵的爱马仕茶具。电车男虽然对女孩颇有好感，却没有任何恋爱经验。万般无奈之下，他求教留言板上的好友。网友们你言我语，出谋划策。在网友们的支持下，电车男向心仪的女孩展开笨拙的恋爱攻势……本片根据真实事件改编，并先后改编成电视剧、电影、舞台剧。©豆瓣', '山田孝之', '村上正典', 6.9, 8687, 'tt0456121', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p670884989.jpg', 1.1, 8.1, 47.8, 32.5, 10.5, '0.356803,-0.066527,-0.422648,0.510745,0.159907,-0.026513,0.660429,0.145624,-0.161366,-0.283473,0.332817,0.618102,-0.343106,0.328579,0.246334,-0.064146,-0.291366,-0.545744,-0.066814,-0.003913,-0.000053,-0.258739,-0.246625,0.020244,-0.154905,-0.184823,0.517120,-0.037475,-0.287067,0.567185,0.627136,0.215462,-0.199802,0.274562,-0.024593,0.100300,-0.069665,0.037733,-0.168578,0.077039,-0.338108,-0.204599,-0.202919,0.005300,0.115680,0.381443,0.877065,-0.204223,-0.450326,-0.012000,0.586447,0.021284,0.083191,0.035410,0.208045,0.090047,0.515654,0.062291,0.079580,0.168850,0.069921,-0.060900,-0.518606,0.044587,0.096388,0.181973,-0.470300,0.484097,-0.260812,-0.133658,0.082313,-0.403800,-0.196159,-0.086991,0.232572,0.173686,0.002338,0.255626,-0.134007,0.469643,0.264986,0.381952,-0.084477,0.553144,-0.137681,-0.150513,-0.107182,-0.067079,-0.618934,0.058546,0.147071,-0.217706,-0.114185,-0.078444,-0.723038,0.009507,0.146275,-0.124379,0.194141,-0.247282,-0.155539,-0.889291,0.132705,-0.257474,-0.384787,-0.239531,0.385246,-0.165341,1.056192,-0.952817,-0.053865,0.501864,0.339932,-0.619687,0.792028,0.215491,-0.258599,-0.085412,-0.328065,0.043890,0.067948,-0.024146,-0.078712,0.348690,-0.177815,-0.221212,-0.487740,0.185247', '3811356', '25922902', '1316589', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418187', '忍者神龟', '剧情', '将施奈德回老家之后，四只原本亲如兄弟的神龟由于没有了敌人，于是不再想以往一样一起战斗，而是各自在喜欢的领域内钻研，以往一起行动的忍者神龟们变成了四个独来独往的“独行侠”！这时，纽约市中发生一连窜的怪事。原来实业家马克西米林安•J•威特斯意图征服纽约市，秘密培养了一支远古怪兽组成的军队，加上恶名昭彰的忍者组织Foot Clan，各种黑暗势力又在城市的角落里蠢蠢欲动！神龟们又处于备战状态了！他们再次联合起来，准备向黑暗势力出击！©豆瓣', '诺兰·诺斯', '凯文·门罗', 6.5, 32397, 'tt0453556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199290432.jpg', 1.9, 11.2, 55.1, 24, 7.7, '0.752662,-0.102485,-0.950011,0.714081,0.243252,-0.230992,0.685349,0.052215,-0.474683,-0.211631,0.187152,0.530305,0.088461,0.120371,-0.157997,-0.509925,-0.337306,-0.931608,-0.391331,-0.298611,-0.251497,-0.167729,-0.415105,-0.280413,-0.084084,-0.288561,0.649690,-0.038430,-0.070556,0.176569,0.137793,0.288506,-0.134138,0.262401,-0.046378,-0.196080,0.165635,-0.116029,-0.342820,0.393510,-0.303030,0.073011,-0.302755,0.298261,0.255387,0.072106,0.714744,-0.649982,0.300035,-0.598760,-0.000381,0.014771,-0.148151,0.142366,0.742960,0.182208,0.272713,-0.076874,0.126385,0.149032,-0.086854,-0.036313,-0.624227,0.085780,0.066074,0.296949,-0.460688,0.096390,0.236791,-0.039815,0.038024,-0.355699,0.113822,0.626939,0.397421,0.015851,0.045969,0.148539,-0.477952,-0.160856,0.749937,-0.034862,-0.357781,0.018046,-0.022685,-0.328479,-0.338601,-0.235774,-0.238660,-0.471216,0.418434,0.079457,-0.170157,0.619567,-0.903003,0.090776,-0.011249,-0.373103,-0.156572,-0.211604,-0.130493,-0.762657,-0.086633,-0.124595,-0.039846,0.220924,0.012899,0.349677,0.751488,-0.919747,0.159198,0.419149,0.271791,-0.471572,0.254750,-0.325380,0.129740,-0.095790,0.238574,-0.019107,0.198843,0.511059,0.296732,0.332990,-0.234082,-0.102663,-0.491331,0.411151', '26316956', '25774050', '2032339', '5361544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418189', '蜘蛛侠3', '动作', '蜘蛛侠（托比•马奎尔 Tobey Maguire 饰）在经历了重重考验之后，成为了人人敬仰的正义英雄，抱得美人归。但是，光环下蜘蛛侠，也有自己的心病：他在第一集时放走了小偷导致最亲爱的叔叔被小偷杀死，帕克一直耿耿于怀。生活顺意的帕克开始变得目中无人，当他再次抓到那个小偷时，残忍地看着他从楼上摔下致死，过后才发现自己惩罚错了人，真凶是“沙人”。当帕克将“沙人”残忍杀死后，帕克心内的阴暗面渐渐在帕克的身体内占据了上风，蜘蛛侠最终演变成邪恶的“毒蜘蛛”！糟糕的是，帕克没有察觉到自身的变化，帕克最终如何摆脱自身的邪恶？©豆瓣', '托比·马奎尔', '山姆·雷米', 7.6, 238663, 'tt0413300', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1344981868.jpg', 0.4, 3, 32.9, 43, 20.7, '0.316805,0.217670,-0.626741,0.281400,-0.200775,-0.354737,1.018579,-0.004489,-0.369025,0.023980,0.441439,0.602401,-0.338590,0.143990,0.141854,0.088310,-0.199494,-0.854563,-0.201455,-0.042102,-0.539716,-0.358045,-0.502213,-0.017374,-0.083948,-0.210612,0.594751,0.267032,-0.257844,0.063255,0.297294,0.314036,0.222519,0.557567,-0.156852,0.306987,0.094013,-0.290385,-0.029386,0.256281,0.228967,-0.491716,-0.075050,0.297751,-0.334624,0.226996,0.636521,-0.656818,-0.221599,-0.169718,0.394383,-0.540491,-0.281787,0.199338,0.222513,-0.242906,-0.066806,-0.055272,-0.039049,-0.049161,0.157659,0.173634,-0.784456,-0.047821,-0.183260,0.117661,-0.671670,0.441895,-0.077654,0.146397,0.231604,-0.380818,0.131592,0.140013,0.211358,0.165705,-0.274367,-0.028417,-0.347950,-0.128859,0.548896,-0.142929,-0.523855,0.143405,-0.115099,-0.359172,0.160672,-0.530660,-0.185611,-0.227192,0.704014,0.474538,-0.338212,0.490828,-0.331502,-0.184537,-0.219620,0.011412,-0.339062,-0.447634,-0.383126,-0.153519,-0.364351,-0.295963,-0.112322,-0.164842,-0.312695,-0.529173,0.507746,-0.879121,0.327067,0.537456,0.211590,-0.221654,0.364985,-0.120596,0.107036,0.200617,-0.150057,0.184430,0.121443,0.514545,0.460948,0.402369,-0.085947,-0.086547,-0.104112,0.795817', '25828589', '25917973', '1307800', '10486471');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418190', '007：大战皇家赌场', '剧情', '英国军情六处特工詹姆斯•邦德（丹尼尔•克雷格饰）这一次的任务是在赌场上赢取俄罗斯间谍手中的巨额财富，让其背后的恐怖组织势力无法达成阴谋并且击垮恐怖组织。这次，邦德有了一个漂亮的得力女助手琳德（伊娃•格林饰）。邦德经过了赌场上的种种训练，最终来到了皇家赌场。随着赌注越来越大，这场赌局也愈来愈显示出背后交错的阴谋。邦德甚至险些死于非命。在共同的合作中，邦德和琳德不知不觉拥有了信任和默契，这种感情，将会何去何从呢？©豆瓣', '丹尼尔·克雷格', '马丁·坎贝尔', 7.7, 182109, 'tt0381061', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p790087797.jpg', 0.3, 2.2, 28.4, 48.7, 20.4, '0.153694,0.267765,-0.683271,0.630135,0.281993,-0.269848,0.568243,-0.026129,-0.481823,-0.003879,0.491052,0.640398,-0.099798,-0.158559,0.217219,-0.236112,-0.424206,-0.955821,-0.455492,-0.325096,-0.356229,-0.807060,-0.479847,-0.293598,-0.166324,-0.034829,0.439277,0.194395,-0.073478,0.375429,0.508265,0.352871,-0.110423,0.150436,-0.015922,-0.101683,0.739696,-0.100538,-0.468068,0.163948,0.055159,-0.175858,-0.015472,0.210668,0.038501,0.449160,0.440405,-0.367427,0.027005,-0.302024,0.275607,-0.169081,-0.029682,-0.043361,0.399519,0.172921,0.145390,0.266741,-0.279362,-0.112550,0.161910,-0.099372,-0.981338,-0.046159,0.137103,0.226702,-0.390822,0.185076,-0.216722,0.009207,0.014435,-0.070865,0.055658,0.557064,0.549062,-0.200179,-0.077692,0.320332,-0.521625,-0.077364,0.692969,-0.043791,-0.146059,-0.054278,-0.354617,-0.516158,-0.249301,-0.311952,-0.110871,-0.136163,0.676266,-0.175471,0.278113,0.394650,-0.771252,0.065231,-0.342684,-0.088667,0.046458,-0.389521,0.270309,-0.834397,-0.431707,-0.323041,-0.302325,0.318551,0.195224,-0.073875,0.594597,-0.778752,-0.098393,0.685212,0.226663,-0.206014,0.353001,0.166849,0.228945,-0.253052,-0.228701,-0.039482,0.248187,0.090873,0.055035,0.331036,0.125357,-0.222306,-0.143522,0.319189', '1307442', '3775167', '4301278', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418191', '超人归来', '动作', '一直想寻根的超人（Brandon Routh饰）返回了氪星，希望可以找到其他同伴，但那里的一切早已不复存在。而这一去便是5年。5年后，超人回到了地球，但是周遭的一切已经改变。他发现地球已经习惯了没有超人的保护，他一直爱慕的路易丝（Kate Bosworth饰）因为馔写了一篇“为什么世界不需要超人”的报道而获得普利策大奖。更令他心碎的是，她已经与主编的侄子订婚，而且是一个5岁孩子的母亲了。另一边，他的死对头莱克斯（Kevin Spacey饰）利用卑鄙手段骗取了巨额遗产，企图卷土重来。在南极莱克斯找到了超人父亲的线索，以及一块含有超级能量的水晶，妄想借助水晶的力量控制地球。超人能否战胜心魔，再一次挽救地球于水火？©豆瓣', '布兰登·罗斯', '布莱恩·辛格', 6.7, 77453, 'tt0348150', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p457079860.jpg', 1.2, 7.8, 54.8, 28.1, 8.1, '-0.095965,0.123916,-0.577898,0.634455,-0.365054,-0.288843,0.443196,-0.030727,-0.528393,-0.271145,-0.065658,0.805543,0.032836,0.073041,0.029004,0.142814,-0.088122,-0.650435,0.179896,-0.297095,-0.411628,-0.539358,-0.579652,-0.203223,-0.049996,-0.588640,0.852586,0.293945,-0.012539,0.259470,0.058810,0.049544,0.096261,0.472954,-0.261189,-0.122362,-0.150491,0.160742,-0.325312,0.391753,0.083314,-0.029024,0.204517,0.504307,-0.220944,0.158115,0.527345,-0.469963,-0.065041,-0.282200,0.431774,-0.332254,-0.052064,0.085439,0.212103,-0.158033,0.120032,0.129314,-0.230868,-0.119310,0.267294,0.010987,-0.975539,-0.288714,0.005184,-0.017939,-0.579508,0.418630,-0.176801,0.035214,-0.113104,-0.249596,0.293160,0.356458,0.147999,0.436667,-0.266385,-0.342771,-0.552095,0.158498,0.504790,-0.193567,-0.311465,0.655557,-0.075437,-0.254366,-0.327236,-0.287494,-0.324752,0.278199,0.209088,0.393838,-0.345953,0.138163,-0.624706,-0.050001,-0.319467,-0.144930,0.195621,-0.553683,-0.046196,-0.373356,-0.315525,-0.201634,-0.158667,-0.152081,0.176714,-0.371342,0.933420,-0.864180,0.279093,0.681915,0.388117,-0.749505,0.763318,-0.060949,-0.133596,-0.264706,0.176431,0.142723,0.000184,0.434612,0.054295,0.142685,0.237410,-0.233620,-0.341600,0.564859', '30163500', '25932086', '1793491', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418192', '加勒比海盗3：世界的尽头', '动作', '被大章鱼吞下去的杰克船长（强尼·戴普）进入了戴维·琼斯控制的“死界”——世界的尽头。为了拯救杰克，威尔·特纳（奥兰多·布鲁姆）、伊丽莎白（凯拉·奈特莉）和女巫等一行人也来到了“死界”。找到杰克，他们一行人解开迷咒，逃出了世界尽头。而此时狡猾的卡特勒·贝凯特（汤姆·霍兰德）已经得到了戴维·琼斯（比尔·奈伊）的心脏，由此挟持戴维·琼斯，掌控所有的公海海盗，为东印度公司攫取利益。为了应对危难，各地海盗头目秘密集会，展开是否释放女海神，杀掉戴维·琼斯的争论。原来女海神正是戴维·琼斯的旧情人，两人之间的微妙关系，成了双方交锋的关键。在平静的海面上，风雨降将至，最终的对决即将展开。每个人面临着怎样的命运？当最后的审判结束，大海能否重归往日的宁静？©豆瓣', '约翰尼·德普', '戈尔·维宾斯基', 8.3, 368626, 'tt0449088', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2407916208.jpg', 0.2, 1.2, 16.3, 46.5, 35.8, '0.205081,0.272238,-0.717609,0.260018,-0.018994,-0.511211,0.749811,0.259624,-0.269495,-0.063278,0.198533,0.593782,-0.366243,-0.128861,0.619268,0.185545,-0.605170,-0.655436,-0.183306,0.018130,-0.213658,-0.581749,-0.443512,-0.326034,0.086748,-0.323812,0.562306,0.258262,-0.028425,0.171714,0.251958,0.388321,-0.227765,0.425559,0.101226,0.051688,0.185664,-0.483979,-0.501380,0.221698,-0.319629,0.030741,-0.015981,0.239470,0.015833,0.376010,0.604107,-0.596369,0.308432,-0.127853,-0.004598,-0.555789,0.023685,-0.008802,0.271132,-0.172962,-0.134234,0.185348,0.073857,-0.327255,-0.064452,-0.041989,-0.640460,0.132846,-0.107283,0.351346,-0.233668,0.186098,-0.001644,0.090630,0.044566,-0.287286,0.089766,0.319227,0.348462,0.201071,-0.015826,-0.042354,-0.442675,-0.386988,0.760739,-0.221390,-0.188095,-0.085781,-0.132120,-0.510690,-0.189390,-0.230332,-0.237907,-0.198213,0.742806,0.222945,0.015726,0.500905,-0.488304,-0.225798,-0.443486,-0.210458,-0.043554,-0.470398,-0.013380,-0.882899,-0.064006,-0.117474,-0.116163,-0.156534,-0.080322,-0.131124,0.568125,-0.568854,0.405958,0.632052,0.216041,-0.077391,0.376628,0.038282,0.384147,-0.330073,-0.128565,0.520212,0.358697,0.416417,0.228923,0.096867,-0.060266,0.201784,-0.142694,0.595707', '1306723', '1316693', '11541282', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418194', '雾都孤儿', '剧情', '本片根据英国作家狄更斯1838年的名著《雾都孤儿》改编。孤儿奥利弗（巴尼•克拉克 Barney Clark 饰）由教会抚养长大，9岁时被送去童工厂拣填絮，后被卖给棺材铺当学徒，屡受欺侮。奥利弗从棺材铺逃跑，步行七十英里到达伦敦，遇见小偷“机灵鬼”（哈利•伊登 Harry Eden 饰），并被收入犹太老头费金（本•金斯利 Ben Kinsley 饰）的盗窃团伙。奥利弗第一次出徒便被诬陷偷窃布朗罗先生（爱德华•哈德威克 Edward Hardwicke饰）的丝帕，并被打昏在地。被好心的布朗罗先生带回家收养，却在替布朗罗先生跑差途中被费金的同僚比尔（杰米•福尔曼 Jamie Foreman饰）抓获。比尔逼迫奥利弗协助他与同伙托比（马克•斯特朗 Mark Strong 饰）入夜行窃布朗罗先生家。小奥利弗不从，眼看命在旦夕……©豆瓣', '巴内·克拉克', '罗曼·波兰斯基', 8, 37973, 'tt0380599', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p853427696.jpg', 0.2, 1.1, 21.2, 54.4, 23.2, '0.285633,-0.178814,-0.233617,0.025435,-0.225156,-0.572895,0.495032,0.246418,-0.310596,-0.316294,0.044064,0.744946,-0.300942,0.062344,0.293562,0.236620,-0.333045,-0.360295,0.033222,-0.213335,-0.189164,-0.525048,0.008964,-0.334902,-0.089952,-0.188411,0.093934,-0.040966,-0.031076,0.380471,0.091543,0.401517,-0.056727,0.020966,-0.217000,0.231736,0.410532,-0.226121,0.056034,0.255153,-0.298306,-0.233546,0.084754,-0.382399,0.315510,0.386674,0.597110,-0.002773,0.427169,-0.173736,0.048723,-0.133783,0.103966,0.172148,0.272937,-0.155543,-0.072302,0.181979,-0.010757,0.048170,0.352657,-0.444782,-0.369116,0.267171,0.053784,-0.177070,-0.840472,0.275957,-0.403169,0.283598,0.032541,-0.229026,-0.015046,0.158974,-0.063508,0.238583,0.192719,0.101040,-0.674236,0.096829,-0.060684,-0.304002,0.140638,0.001239,0.040515,-0.335634,0.547957,0.026618,-0.127097,0.049119,0.608807,-0.288372,-0.191255,-0.011146,-0.620831,-0.406058,-0.567621,-0.129229,0.104879,-0.170850,-0.216106,-0.711311,-0.005041,-0.032987,-0.125271,-0.117899,0.073546,0.056278,0.258452,-0.056376,0.517875,0.327276,0.197944,-0.049271,0.420296,-0.198075,0.053308,-0.117923,-0.225039,0.296268,0.636875,0.430188,0.552939,0.094245,0.065171,-0.313199,-0.076162,0.164412', '1300044', '1294948', '1295684', '1432825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418200', '傲慢与偏见', '剧情', '根据简·奥斯汀同名小说改编。伊丽莎白·班纳特(凯拉·奈特丽 饰)出身于小地主家庭，有四个姐妹，母亲班纳特太太整天操心着为女儿物色称心如意的丈夫。新来的邻居宾格来先生和他的朋友达西（马修·麦克菲迪恩 饰）打破了她们一家人单调的乡村生活。宾格来和伊丽莎白的姐姐简·班纳特互生情愫；达西对善良聪明的伊丽莎白产生了好感，而伊丽莎白却对达西不可一世的傲慢心存偏见，不接受他的感情。然而，世事难料，宾格来和简·班纳特因为误会，关系危在旦夕；达西的种种作为，展示了性格中和伊丽莎白相同的善良一面，逐渐赢得了伊丽莎白的好感。两对有情人能否终成眷属？班纳特姐妹们能否得到自己想要的生活？简·奥斯汀笔下十九世纪初英国乡村生活和社会风貌，重新展现在大银幕上。©豆瓣', '凯拉·奈特莉', '乔·赖特', 8.7, 737669, 'tt0414387', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2016401659.jpg', 0.2, 0.8, 10.9, 40.8, 47.3, '0.285249,-0.151912,-0.536876,0.827791,-0.308609,-0.482997,0.850743,0.167475,-0.523840,-0.342117,-0.267196,0.788157,-0.281212,0.378534,0.412179,0.041078,-0.381005,-0.399509,-0.046143,0.061248,0.060000,-0.656744,-0.235641,-0.563164,-0.127485,-0.163653,0.256356,-0.151112,-0.298654,0.479984,0.278138,0.455783,-0.006470,0.205057,-0.135678,0.141521,-0.108001,0.207451,-0.560763,-0.187077,0.005645,0.136247,-0.077698,0.124713,0.314850,0.231901,0.654525,-0.271269,-0.015999,-0.243124,0.301926,0.211901,0.266425,0.158363,0.130766,-0.132596,0.189374,0.194752,0.110467,-0.260277,-0.113535,-0.312019,-0.544469,0.091654,0.109008,0.046196,-0.567739,0.631075,-0.155575,-0.311036,-0.064171,-0.324055,0.021589,0.155171,0.351709,0.211156,-0.008204,0.067891,-0.282602,-0.035911,0.706584,0.343882,-0.248848,0.333308,-0.745399,-0.331580,-0.044746,0.034520,-0.896034,-0.165052,0.236782,-0.082161,-0.010299,0.460678,-0.583031,-0.324604,-0.314933,0.133545,0.355309,-0.816522,0.325201,-0.670032,-0.424306,-0.995680,-0.572591,-0.434149,0.227458,-0.477010,1.093278,-0.962766,0.163575,0.326175,0.315490,-0.768441,0.745083,0.584134,0.128931,-0.200336,-0.259472,0.375804,-0.223563,-0.209263,0.013873,0.190469,-0.066414,0.066488,-0.156630,0.669810', '26348103', '1309161', '6963575', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418270', '本能2', '悬疑', '一个夜晚，美艳而富有的女作家凯瑟琳（莎朗•斯通 Sharon Stone 饰）与某球星狂欢后驾车落入水中，结果该球星死亡而凯瑟琳却安然无恙。警方怀疑这是一起谋杀案，委派精神病医生格拉斯（大卫·莫利塞 David Morrissey饰）对凯瑟琳进行精神鉴定。因为其他原因，凯瑟琳被无罪释放了。但此后她却要求格拉斯对其进行精神治疗，格拉斯也想通过凯瑟琳这个案例完成一篇学术论文。在这个过程中，格拉斯被凯瑟琳的美丽与智慧所吸引，渐渐忘记了医生与病人的原则，陷入了无法自拔的情爱之中。就在这时，他感觉身边的一切都发生了可怕的变化，而这些又都与凯瑟琳有关。他仿佛生活在这个女人所编织的无形的网中。那么他能够逃离这个危险女人的掌控吗？他该如何抉择？©豆瓣', '莎朗·斯通', '迈克尔·卡顿-琼斯', 5.7, 21651, 'tt0430912', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2359584324.jpg', 6.2, 26.6, 47.9, 14.7, 4.5, '0.347107,0.131714,-0.624178,0.440505,-0.152429,-0.139604,1.014357,0.065355,-0.557171,-0.342357,0.167869,0.733065,-0.262669,0.169625,0.311192,0.235325,-0.498083,-0.782982,0.169441,-0.004837,-0.284562,-0.489694,-0.384340,-0.290518,0.078207,-0.208481,0.590364,0.034283,-0.170076,0.196826,0.045542,0.389515,-0.040048,0.620459,0.123310,0.017476,0.254840,-0.161321,-0.212393,0.297124,0.285566,-0.201803,-0.046510,0.457216,-0.154789,0.216652,0.672973,-0.401308,-0.383185,-0.249295,0.428410,-0.333439,0.029998,0.498098,-0.092884,-0.052071,0.145278,0.173589,-0.102344,-0.119181,0.060280,0.173991,-0.816389,0.064060,-0.021447,0.455430,-0.341113,0.089029,-0.227142,-0.045216,-0.097451,-0.278514,0.152915,0.389694,0.257675,0.269500,-0.359756,-0.262724,-0.410813,0.051425,0.597283,-0.134419,-0.558800,0.400935,-0.409033,-0.562518,-0.041645,-0.014527,-0.389025,0.005263,0.160976,0.469415,-0.188159,0.426248,-0.471436,0.021605,-0.226137,-0.146387,-0.406774,-0.462964,-0.168034,-0.447365,-0.254785,-0.318762,-0.500103,-0.144217,0.128541,-0.112994,0.694754,-0.642627,0.357822,0.651049,0.255665,-0.487288,0.367771,0.180504,0.238460,-0.078621,-0.211731,0.400937,-0.068959,0.303869,-0.006450,0.513207,0.233166,0.024812,-0.405838,0.607659', '25828589', '3005387', '25909236', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418519', '铁拳男人', '剧情', '布洛克（罗素·克劳 Russell Crowe 饰）除了是一名过气的拳击手，还是三个孩子的父亲。当他的拳击生涯走下坡路后，紧接着而来的是生活的拮据和入不敷出的家庭状况。幸好有贤惠美丽的妻子梅（芮妮·齐薇格 Renée Zellweger 饰）理解支持，她的从不埋怨和勤劳持家，令这个家庭不至于毫无生机。布洛克放下自尊去排队领取救济金，却挡不住严冬的即将来临，家里食物短缺，生存问题迫在眉睫。布洛克终于决定重上拳击台，这是他可以挽救家人的唯一办法。他的复出引来了民众的关注，成为了人们心中的平民英雄。他在比赛中英勇挥拳，为了男人的尊严，为了家人的生存。©豆瓣', '罗素·克劳', '朗·霍华德', 8.8, 49083, 'tt0352248', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456421395.jpg', 0.1, 0.4, 8.7, 42, 48.8, '0.122201,0.001784,-0.593351,0.330461,-0.370465,-0.306194,0.777064,0.229552,-0.426671,-0.193099,0.316948,0.657954,0.351948,0.268926,0.245935,-0.131307,-0.185414,-0.499415,-0.132386,0.191932,-0.288762,-0.217468,-0.403425,-0.339439,-0.416015,-0.310649,0.736226,0.033518,-0.251922,0.378253,0.346050,0.440922,0.440219,0.433567,-0.268898,-0.038561,-0.095055,-0.001675,-0.376446,0.162568,0.089318,-0.130255,-0.275607,0.416756,0.267465,0.555385,0.461430,-0.010815,-0.114935,-0.104905,0.370873,-0.241731,-0.061230,0.205059,0.035802,-0.143167,0.168225,0.056642,-0.105904,-0.044868,0.076990,-0.128352,-0.946785,-0.193685,0.246345,0.170253,-0.747641,0.611674,-0.124793,-0.321242,-0.014665,-0.249957,0.152764,0.274167,0.070633,0.438405,-0.338995,0.054266,-0.399711,0.377093,0.838831,-0.030587,-0.417273,0.284015,-0.469000,-0.397013,0.106024,-0.554960,-0.666366,-0.207486,0.123179,0.243929,-0.084113,0.263850,-0.436474,0.228695,-0.306956,-0.360135,0.052069,-0.399129,-0.078148,-0.237038,0.043672,-0.531075,-0.522911,0.096943,0.167768,-0.353217,0.990650,-0.838062,0.085614,0.477889,0.363079,-0.600497,0.599931,0.293168,0.259426,-0.140643,-0.117619,0.369841,-0.094235,0.141466,-0.137153,-0.025237,-0.001073,-0.259922,-0.023083,0.684787', '24284209', '1877596', '30163500', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418570', '孩子', '剧情', '布鲁诺（杰瑞米•雷尼尔 饰）是一名20岁的街头混混，过活的营生是各种合法、非法的地下交易，他的女友，18岁的索尼亚（黛博拉•弗朗西斯 饰）也没正当的工作，平日靠微薄的救济津贴和他度日。索尼亚怀孕期间，依靠钻政府政策的空子过了一段不错的日子，但在生下孩子后，生活又陷捉襟见肘境地 ，好在，布鲁诺看起来也很开心他们的生活中多出一个小生命。但索尼亚不知的是，布鲁诺的高兴劲只是佯装，他在伺机把婴儿卖掉换得一笔收入，因为他认为自己根本没能力担负起父亲的责任。©豆瓣', '杰瑞米·雷乃', '让-皮埃尔·达内', 7.9, 8470, 'tt0456396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1509446756.jpg', 0.3, 1.2, 22.2, 54.9, 21.4, '0.138750,-0.014270,-0.547681,0.469936,-0.616613,-0.277421,0.632468,0.196759,-0.562227,-0.185455,0.140079,0.744817,0.210048,0.197961,-0.046768,0.111601,-0.129078,-0.493246,0.056236,-0.174551,-0.181201,-0.524797,-0.359974,-0.300053,-0.442688,-0.492844,0.546378,-0.178838,0.158589,0.263887,0.243069,0.107342,0.362259,0.402130,-0.370427,0.042810,-0.038227,0.159600,0.001481,0.037037,0.103148,-0.302286,-0.211516,0.130921,0.475266,0.609348,0.694892,-0.138477,-0.055661,0.173452,0.298183,-0.164032,-0.284697,0.130328,0.280761,-0.145479,0.156873,-0.021163,-0.458584,-0.019592,0.246948,-0.131768,-0.676218,-0.121141,0.088470,0.116136,-0.707157,0.534724,-0.068749,-0.011008,-0.066586,-0.534650,-0.081524,0.604061,-0.031733,0.512945,-0.256984,0.129085,-0.811459,0.372637,0.584368,-0.175448,-0.362111,0.609556,-0.592308,-0.509103,-0.098540,-0.482679,-0.442335,-0.373889,0.188587,-0.232058,-0.397860,0.130509,-0.457475,0.188527,-0.239334,-0.272072,-0.159588,-0.355304,-0.171944,-0.249649,-0.189237,-0.604140,-0.449690,0.093354,0.157689,-0.436538,0.600750,-0.797811,0.051478,0.607068,0.334618,-0.451252,0.845987,0.195785,0.312411,0.016500,-0.188272,0.232607,-0.034462,-0.018574,0.246817,0.208878,0.029316,-0.291381,-0.146609,0.552508', '3055049', '1783461', '1303112', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418605', '夜宴', '剧情', '五代十国，纷纷扰扰，争斗不休。先帝离奇驾崩，厉帝（葛优 饰）篡位，把先帝美丽的皇后（章子怡 饰）占为己有。皇后为求自保，惟有奉承于厉帝膝下。然而，她的心中有着更大的，不为人知的野心。太子（吴彦祖 饰）是先帝的儿子，亡父之痛让他决心放弃艺术家的生活，开始了复仇之路。然而，犹豫不决的天性让他在复仇路上走得伤痕累累，作为后母的皇后更是  让他充满了感情的纠缠。青女（周迅 饰）已被许为太子的妻子，她对太子痴心不二，最后却断送了青春年华。青女哥哥（黄晓明 饰）年轻气盛，与妹妹感情甚笃，深深陷入了这场斗争。这天，厉帝开设夜宴，众人出席，暗涌翻滚，杀机四伏。©豆瓣', '章子怡', '冯小刚', 6, 172671, 'tt0465676', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537499351.jpg', 4.8, 21.3, 49.6, 18.7, 5.6, '-0.261099,0.170699,-0.569287,0.672582,0.407079,-0.252499,0.856770,0.423764,-0.652117,-0.193657,0.585199,0.538697,-0.339482,0.090577,0.099088,-0.133333,-0.020226,-0.415272,-0.162456,0.122391,0.251360,-0.264770,-0.041304,-0.084521,-0.522857,-0.164891,1.042948,0.109344,0.046576,0.322916,0.571048,0.284218,0.009919,0.482954,-0.036528,0.018662,-0.290572,-0.097787,-0.477587,-0.220665,0.207990,-0.563658,-0.278221,0.275078,-0.243708,0.356343,0.442702,-0.298992,0.193450,-0.428437,0.494234,-0.350291,-0.090376,0.392975,-0.127758,0.025012,0.089886,0.479899,-0.066129,-0.263683,0.164426,0.032643,-0.277847,0.040797,0.197133,0.137525,-0.412461,0.501704,-0.159694,-0.093206,0.151470,-0.082731,0.244618,0.003057,0.066428,0.062575,-0.236331,0.029729,-0.389341,0.222516,0.602098,-0.022048,-0.054920,0.213199,-0.082667,-0.259477,0.123961,-0.304256,-0.465325,-0.321195,0.411821,-0.029043,-0.026958,0.801812,-0.450072,-0.138597,-0.308403,0.211005,0.288193,-0.493595,0.019529,0.031948,-0.355581,-0.535395,-0.513261,0.041376,0.366188,-0.405415,0.558234,-0.690566,0.076521,0.321935,0.156086,-0.804379,0.420305,0.182466,0.097718,-0.011768,-0.077336,0.349739,-0.467254,-0.122021,-0.013188,0.042662,-0.266846,0.052757,-0.514018,0.407110', '1293265', '35287908', '1763916', '6900094');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418613', '后备甜心', '爱情', '餐厅经理Jill（林嘉欣 饰）一直是志安（胡兵 饰）的后备情人，Jill为了爱情，只好默默守在志安的身边。Jill的合伙人Jason（曾志伟 饰）快要退休，找来了厨师Jack（郑伊健 饰）接班。刚开始Jill对这位新合伙人好感不大，认为他也叫自己的爱人伤心。但经过了解才知道，原来Jack的女友Grace（陈文媛 饰）也跟志安一样一脚踏两船，Jack跟Jill一样都是后备情人。两个有着类似情感经历的人，在互相扶持的过程中对彼此产生了感情。两人的关系将要进一步发展的时候，志安却想专一对待Jill……©豆瓣', '林嘉欣', '李明文', 6.3, 5315, 'tt0453097', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2198161679.jpg', 2.1, 14.7, 56.2, 19.4, 7.7, '0.322147,-0.178347,-0.745040,0.541151,-0.081601,-0.247743,0.666474,0.133396,-0.539301,-0.380056,0.186483,0.794907,-0.200299,0.149204,0.037571,-0.009605,-0.208296,-0.986891,-0.106925,-0.138454,-0.262886,-0.554537,-0.189368,-0.083898,-0.231758,-0.081912,0.431393,-0.135491,-0.092598,0.385350,0.515546,0.116121,0.104230,0.468555,-0.055671,-0.102643,0.221418,0.343859,-0.522043,-0.204577,0.055095,-0.032889,0.050166,-0.001172,0.050367,0.398477,0.333997,-0.141996,-0.316459,0.046438,0.067802,0.045567,0.059285,0.074917,0.482514,0.063187,0.392459,0.224773,-0.211088,0.075150,-0.007185,-0.043113,-0.862720,0.010313,0.228670,0.127817,-0.663570,0.454677,0.078905,-0.213433,0.237166,-0.295580,0.239745,0.369434,0.422540,0.482867,-0.253125,-0.039218,-0.299118,0.149177,0.732715,0.181434,-0.068380,0.602686,-0.303925,-0.231671,-0.236329,0.103586,-0.520207,-0.115827,-0.102980,0.165745,-0.247708,0.074455,-0.535581,0.263596,0.072239,0.137275,0.181139,-0.578396,0.242413,-0.430268,-0.272897,-0.758833,-0.301506,0.118769,0.104207,-0.343486,0.828516,-0.970232,0.177948,0.411376,0.415151,-0.949037,0.752200,0.439064,-0.162457,-0.535168,-0.050347,0.139447,-0.248663,-0.140088,0.077465,0.288391,0.038050,-0.146080,-0.058829,0.253981', '4301278', '1301022', '1949320', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418640', '听到涛声', '剧情', '高二那年夏天，美丽的女孩武藤里伽子（坂本洋子 配音）随母亲离开大都会东京，来到了古朴幽静的高知。聪慧美丽的里伽子在这个偏僻的小地方如此靓丽，引来了男孩们的爱恋的目光，而她孤高的性格又让女孩们颇多微词。与她同班的班长松野丰（関俊彦 饰）偷偷喜欢着她，而松野的好友杜崎拓（飛田展男 饰）似乎也对里伽子颇为关注。在黄金周中，里伽子约上拓一同返回东京，拓也第一次感知到这个看似冰冷的女孩内心中最脆弱的情感。他们仿佛走得更近，又仿佛相隔更远……本片为电视电影，根据氷室冴子的原作改编，由擅长纯爱题材动画的望月智充执导，其代表作有《相聚一刻》、《橙路》等。©豆瓣', '飞田展男', '望月智充', 8.2, 78448, 'tt0108432', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1137709479.jpg', 0.4, 1.7, 19.8, 43.7, 34.5, '0.329291,0.035583,-0.815355,0.722647,0.131863,-0.192945,0.897104,0.136235,-0.287174,-0.281207,0.158124,0.762734,-0.318349,0.505182,0.262034,0.099957,-0.353259,-0.375945,-0.477000,-0.521765,-0.060443,-0.194083,-0.248636,0.198714,-0.227555,-0.037377,0.637942,0.101804,-0.174775,0.413724,0.117895,0.083154,-0.130194,0.254993,-0.207271,-0.143100,-0.100968,0.263111,0.146529,0.217428,0.035173,-0.268157,-0.398948,-0.046701,0.002423,0.367787,0.913860,-0.230414,-0.325224,0.112080,0.428315,0.093090,-0.195710,0.109051,0.252578,-0.022157,0.449061,-0.045569,-0.281282,0.190377,-0.212407,-0.113503,-0.238696,0.374456,0.173757,0.142187,-0.307204,0.412218,-0.039819,-0.346007,0.449716,-0.416104,0.098266,-0.249269,0.137404,0.332398,-0.205111,0.153913,-0.021429,-0.027676,0.472991,0.309487,-0.214854,0.334446,-0.410069,-0.515023,-0.044224,-0.282673,-0.534473,-0.024630,0.150825,-0.114013,0.055215,0.210753,-0.681117,0.215513,0.038807,0.224562,-0.056320,-0.311544,-0.139417,-0.757956,-0.002740,-0.717523,-0.138611,0.060881,0.208508,-0.221078,1.037685,-0.645270,0.100923,0.447547,0.297740,-0.240186,0.638789,0.053767,-0.058580,-0.023104,-0.231703,0.337076,-0.092059,0.245900,-0.087515,0.600909,-0.347458,-0.447146,-0.639486,0.427134', '3811356', '4181031', '5403927', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418671', '真假公主', '剧情', '1917年，俄国革命爆发，沙皇和他的家族被捕处死。但越来越多谣传说沙皇最小的女儿——最高贵的公主殿下安娜斯塔西亚（英格丽·褒曼 Ingrid Bergman饰）依旧侥幸存活着。安娜公主将是王朝在英国银行巨额存款一千万美元的唯一继承人。1928年，俄国将军波宁（尤·伯连纳 Yul Brynner饰）受流亡在北欧的俄国皇太后（海伦·海丝 Helen Hayes饰）之托，开始寻找公主的下落。几经波折仍寻公主无果，忽然一个精神错乱的女人（英格丽·褒曼 Ingrid Bergman饰）被波宁在一家精神病院发现。她有着与公主安娜惊人相似的容貌。经过波宁亲自监督的毫无人情味的训练下，她完成了从灰姑娘到贵夫人的转变。然而流亡丹麦的皇太后不为所动，任凭她如何努力都不相信她是真正的公主。由安纳托尔·李维克执导，英格丽·褒曼和尤·伯连纳联袂主演的经典电影《真假公主》，荣获1957年奥斯卡金像奖最佳女主角，使女主角英格丽·褒曼成功在好莱坞复出。', '英格丽·褒曼', '安纳托尔·李维克', 7.9, 6372, 'tt0048947', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2100228215.jpg', 0.3, 1.5, 23.6, 49.6, 24.9, '-0.092732,0.308526,-0.581527,0.712224,0.217220,-0.331634,0.761287,0.078173,-0.377511,-0.362942,0.501186,0.721957,-0.349828,-0.167630,0.280385,0.143679,-0.483465,-0.204268,-0.119108,-0.068407,0.047717,-0.569870,-0.137748,-0.167235,-0.352926,-0.479636,0.622537,-0.126544,0.004120,0.285546,0.536215,0.083561,0.020754,0.375804,-0.003085,0.151597,0.254792,-0.019817,-0.077097,0.372294,0.387762,-0.557501,-0.239588,0.123411,0.092254,0.347471,0.322567,-0.528762,0.430187,0.039565,0.489527,-0.139768,-0.040601,0.226816,0.280359,-0.310399,-0.005134,0.129543,-0.194474,-0.309128,0.203241,-0.163167,-0.389727,0.108032,0.304028,0.172740,-0.627712,0.279263,-0.433507,0.039707,-0.011987,-0.367321,0.047906,0.595540,0.083598,0.159766,-0.131967,0.138598,-0.670815,0.320335,0.505080,0.030995,-0.379189,-0.093745,-0.195207,-0.920550,-0.016827,-0.603962,-0.520274,0.058710,0.307918,-0.300397,0.236060,0.457680,-0.325153,-0.237865,-0.518386,-0.226480,0.203074,-0.442236,0.152245,-0.302486,-0.213440,-0.498799,-0.097421,-0.017095,0.394110,-0.347867,0.717304,-0.809665,0.285462,0.465471,0.370039,-0.355623,0.637651,-0.110202,-0.046878,-0.244945,-0.318796,0.551725,0.060361,0.044860,0.217764,0.404093,0.017989,-0.126975,-