INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418677', '狗狗心事', '家庭', '11段狗狗心事，在日本上映時號稱「號泣指數突破90%」，口碑極佳，引發一波關懷生命的反思與迴響，甚至獲得文部科學省認定推薦。第二集確定開拍，目前正緊鑼密鼓籌畫中，預計將於2006年暑假上映。1. 狗狗的一生：歡笑有時 by黑田昌郎2. 我的狗狗一級棒！ By禰津哲久3. 我的狗廣告，人生大迷惘！ By黑田秀樹4. 波奇與我：童年的回憶 By 犬童一心5. 可羅，墜入情網～ By佐藤信介6. 波奇大冒險の愛的信差 By 犬童一心7. 狗狗快譯通的天機不可洩漏！ By永井聰8. 波奇大冒險の病院守候 By 犬童一心9. 掰掰，波奇…… By 犬童一心10.狗狗的一生：悲傷有時 By黑田昌郎11.毛毛，請聽我說… By真田敦', '天海祐希', '犬童一心', 7.9, 6116, 'tt0475974', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2545323848.jpg', 0.8, 3, 25.4, 43.7, 27.2, '-0.309766,-0.384135,-0.448136,0.321961,-0.071161,-0.351710,0.097149,0.063728,-0.039370,-0.298580,0.194439,0.351569,-0.128237,0.412800,-0.045279,-0.075123,0.159925,-0.463420,0.023354,0.244030,0.302574,0.021959,-0.318069,-0.177964,-0.250272,-0.168015,0.862626,0.096098,0.475459,0.109288,0.062003,0.130230,-0.230236,-0.013985,0.323919,0.501970,0.122189,-0.009840,-0.059412,-0.316456,-0.112250,-0.304079,-0.144341,-0.063570,0.113359,0.003349,0.604102,-0.265647,0.117854,-0.186974,0.331863,-0.167827,-0.167183,-0.046522,0.178408,-0.168839,-0.095097,0.166448,-0.175580,0.042528,-0.080948,-0.201008,-0.288103,-0.755074,-0.134878,0.123729,-0.234574,0.465729,-0.071663,0.017847,0.823537,-0.382272,-0.486922,-0.007098,0.077646,0.430380,-0.128932,0.509786,-0.133069,0.313305,0.478806,-0.513715,0.169850,0.390890,0.006764,-0.317128,-0.218138,-0.015018,-0.558158,-0.088516,0.350624,-0.334746,-0.518707,0.399427,-0.164060,0.248520,0.199338,-0.259544,0.003691,-0.082166,0.100215,-0.393863,0.563960,-0.631022,-0.103508,-0.079762,0.464188,-0.416989,0.946614,-0.657002,0.171733,0.829115,-0.088547,-0.132317,0.753284,0.103155,-0.133236,-0.100379,0.408375,0.383064,-0.051262,-0.138716,0.409658,0.044676,-0.031777,0.217416,-0.459125,0.713125', '1908036', '25922902', '3811356', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418691', '心碎往事', '剧情', '父亲的突然去世让汤米（安东·尤金 Anton Yelchin 饰）一家人陷入了混乱，家庭无人照料一片狼藉，母亲终日哭泣郁郁寡欢，就在这样一种糟糕的情况下，汤米迎来了自己躁动又不安的青春，无处发泄的他只能通过调皮捣蛋来纾解心中的积怨。辍学后的汤米在一家熟食店打工，负责送货。汤米和朋友帕鲁帕斯（罗宾·威廉斯 Robin Williams 饰）成天厮混在一起，帕鲁帕斯是一个外表成熟但心智幼稚的“大龄儿童”，两人之间的感情真挚又深厚。一次意外中，汤米结识了妓女蕾蒂（Erykah Badu 饰），后者带领他进入了成年人的世界，享受了爱情的甜蜜与苦涩。一场意外的发生摧毁了汤米自由的生活，它不仅终结了汤米的现在，也波及到了他的未来。©豆瓣', '安东·叶利钦', '大卫·杜楚尼', 8.2, 8651, 'tt0372334', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p839905155.jpg', 0.4, 1.5, 17.3, 50.3, 30.6, '0.390752,-0.007269,-0.869515,0.440647,-0.205389,-0.453857,0.820942,0.320107,-0.357517,-0.044040,0.271915,0.660822,-0.309043,0.489867,0.159459,0.008701,-0.353894,-0.693983,0.159628,-0.207235,-0.087423,-0.318801,-0.259527,-0.387689,-0.147089,-0.241434,0.477138,0.152750,-0.041955,0.541070,-0.006031,0.195296,0.153434,0.537109,-0.099206,0.139156,0.154047,-0.041968,-0.148626,-0.054906,0.201329,-0.132719,-0.013737,0.206389,0.159626,0.466247,0.827597,-0.233987,-0.207238,0.074937,0.308041,-0.022433,-0.060516,0.132327,0.164060,-0.208970,-0.014457,-0.140625,-0.396804,-0.029737,0.067077,0.187221,-0.567779,0.060150,-0.141956,-0.020293,-0.492773,0.551071,0.152420,-0.121955,0.157658,-0.274514,0.119043,0.418946,0.302113,0.612307,-0.295003,0.098084,-0.186624,0.202586,0.970045,0.028329,-0.473876,0.533840,-0.715056,-0.242587,-0.116083,-0.264010,-0.821251,-0.346656,0.401773,-0.047781,-0.257598,0.515311,-0.532238,0.076236,-0.282458,0.164530,-0.196398,-0.394739,0.001724,-0.426513,-0.387771,-0.383692,-0.509845,-0.023392,0.177397,-0.271786,0.655471,-0.705096,0.240040,0.588603,0.164325,-0.353563,0.482357,0.149684,0.148896,-0.069098,0.016562,0.567182,-0.189893,0.210165,0.259371,0.427316,-0.188138,0.396982,-0.350897,0.418555', '30209018', '2365260', '26687241', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418752', '万能钥匙', '剧情', '年轻的姑娘卡罗琳（凯特•哈德森 Kate Hudson 饰）受雇于老妇人维奥莱特（吉娜•罗兰兹 Gena Rowlands 饰），前往她家照顾她卧病在床的丈夫本（约翰•赫特 John Hurt 饰）。维奥莱特的大房子坐落于以神秘习俗和宗教仪式闻名的地区，卡罗琳刚到这里就觉得阴森诡异。随着日子一天天过去，卡罗琳渐渐对这件大房子和古怪的维奥莱特起疑。一次偶然，她从维奥莱特那里得到了一把万能钥匙，用它可以打开这座大房子的所有房间。当卡罗琳走进了隐藏在顶楼的房间时，她看到了令人惊悚的一幕，直觉告诉她，本的卧病在床和维奥莱特以及这间房间有着莫大的关系，她决心揭开这个迷！©豆瓣', '凯特·哈德森', '伊恩·索夫特雷', 8, 337956, 'tt0397101', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p810384382.jpg', 0.4, 1.8, 21.1, 49.3, 27.3, '0.450662,0.233659,-0.723862,0.284180,-0.071264,-0.225704,0.942580,0.333546,-0.517984,-0.432068,0.126085,0.714138,-0.309592,0.305731,0.517444,0.368323,-0.492217,-0.480802,-0.165138,-0.396755,-0.278826,-0.391160,-0.341868,-0.350299,-0.010793,-0.350039,0.026994,-0.085908,-0.095373,0.536577,0.262357,0.584571,-0.101633,0.234224,-0.255582,-0.183714,0.132186,-0.068111,-0.083239,0.056800,0.172679,0.161942,-0.242196,0.032699,0.170986,0.093558,0.215731,-0.361285,-0.060427,0.100416,0.118425,0.209376,0.081695,0.152655,0.019059,-0.253632,0.050845,0.032759,-0.427855,-0.267895,0.183156,-0.235540,-0.350968,0.203930,-0.175059,0.041307,-0.421828,0.162958,-0.199354,-0.230759,0.296167,-0.509935,0.117517,0.214374,-0.018948,0.571359,-0.083416,0.058878,-0.452649,-0.183736,0.141627,0.096732,-0.169201,0.233245,-0.265119,-0.245110,-0.080556,0.123290,-0.483786,0.047113,0.468550,-0.000456,0.131071,0.287527,-0.439400,-0.255198,-0.442988,-0.306408,0.156637,-0.254741,-0.426532,-0.699771,-0.292532,-0.224581,-0.265740,-0.054412,-0.101722,0.074536,0.391641,-0.705022,0.341998,0.258313,0.199214,-0.071941,0.605146,-0.159221,0.290397,0.135789,-0.269619,0.296095,0.129890,0.337275,0.270504,0.685496,0.157599,-0.141858,-0.587659,0.756739', '1302133', '1301686', '1296534', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418834', '断背山', '剧情', '美国怀俄明州的西部，沉默寡言的农夫恩尼斯（希斯•莱杰饰）和热情开朗的牛仔杰克（杰克•吉伦希尔饰)一道被派到山上牧羊，那里人迹罕至，他们只有与羊群为伴，生活单调无味。一个天寒地冻的夜晚，在酒精与荷尔蒙的作用下，他们做了“不该做的事情”，也就此他们在断背山上度过了人生中最美好的时光。季节性放牧结束，迫于世俗压力，杰克和恩尼斯不舍地与对方分离并各自结婚生子。恩尼斯迎娶了自幼相识的阿尔玛，并有了两个可爱的女儿；杰克到了德州，在妻子露琳家族的扶植下事业顺利，还有了个儿子。虽然彼此真心相应，他们只能每年定期约会。一边知情的阿尔玛痛苦无比，而他们又无法满足一年只有几天的团聚。这时意外发生……©豆瓣', '希斯·莱杰', '李安', 8.8, 668912, 'tt0388795', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2604889017.jpg', 0.3, 0.7, 9.6, 35.7, 53.8, '0.458236,-0.148799,-0.724781,0.414286,-0.002769,-0.218515,0.795496,0.166231,-0.373765,-0.086008,0.079866,0.963333,-0.002476,0.404032,0.176938,0.000978,-0.530598,-0.660895,0.159644,-0.266821,-0.161679,-0.430515,-0.064114,-0.142944,-0.132451,-0.346294,0.351184,0.096125,0.306727,0.627344,0.217557,0.069581,-0.140190,0.530786,-0.179981,0.019134,0.131258,0.106031,-0.485438,0.141477,0.042177,-0.135424,-0.214765,0.104710,0.306768,0.321319,0.540294,-0.205519,-0.127611,-0.222015,0.041949,-0.123345,-0.026209,0.268243,0.098787,-0.214591,0.279941,0.409287,-0.096011,-0.119266,-0.013897,-0.175775,-0.734335,0.177110,0.012437,0.164736,-0.621437,0.567004,0.096997,-0.338770,0.092925,-0.607798,0.120938,0.608107,0.191093,0.268377,-0.374180,0.010487,-0.578869,0.148271,0.940991,0.040600,-0.342033,0.280557,-0.369917,-0.405018,0.052320,-0.196034,-0.607159,-0.103802,0.300609,0.108060,-0.227001,0.393304,-0.693578,0.298383,-0.147693,-0.401873,-0.059920,-0.523107,0.104578,-0.530836,-0.174439,-0.696180,-0.615902,0.103268,0.244095,-0.256639,0.665846,-0.709644,0.216547,0.452272,0.515987,-0.256475,0.477840,0.220765,0.396050,-0.202761,0.107421,0.282809,-0.211487,0.174660,0.322709,0.405444,0.016573,0.203545,-0.556271,0.533930', '25721544', '30162520', '24325798', '3014557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1418919', '饺子', '剧情', '过气女星艾青青（杨千嬅 饰）为了爱情嫁给了比自己年长的李姓商人（梁家辉 饰）。青青日益衰老，丈夫也周旋在众多年轻女子身边。青青为了挽回婚姻，千辛万苦找到了媚姨（白灵 饰），她用婴胎做馅所包的饺子，据说吃了之后能使人恢复青春。刚开始青青还是有很大的抗拒感，可是渐渐她就习惯了，但丈夫还是无动于衷，她要求媚姨找到效果更好的极品。这时一个被父亲强奸的女孩来到要求媚姨帮忙打掉孩子，婴儿正是刚好5个月的“极品”，正合青青的意思。但当丈夫重新回到青青怀抱的时候，青青的身上莫名散发着难闻的腥臭味……©豆瓣', '杨千嬅', '陈果', 6.7, 48222, 'tt0472458', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p934865027.jpg', 1.3, 8.8, 51.5, 30.5, 7.9, '0.026257,0.246699,-0.468398,0.138371,-0.436478,-0.569033,0.457436,0.310210,-0.560652,-0.162016,0.231945,0.421357,-0.099133,0.048805,-0.156540,0.246635,-0.181279,-0.380683,0.092904,-0.153276,-0.208289,-0.117400,-0.122319,0.225135,-0.112143,-0.420283,0.638936,-0.349072,-0.071068,0.259589,0.238089,-0.102641,0.266987,0.480872,-0.332483,0.035537,0.056419,-0.114459,-0.321007,0.271530,0.271355,-0.125206,-0.142027,-0.003016,-0.138338,0.429216,0.668024,-0.263486,-0.294242,-0.222536,0.180466,0.093928,-0.078344,-0.040399,-0.019673,0.109886,0.497470,0.030488,-0.275722,-0.073695,0.302428,-0.084752,-0.182373,0.300997,0.241283,0.168886,-0.336291,0.213038,-0.054580,-0.077358,0.403325,-0.514267,0.169804,0.045102,-0.004578,0.489001,-0.349665,0.265934,-0.721936,0.208967,0.408348,0.040114,0.147767,0.675883,-0.321652,-0.210580,0.438847,-0.290264,-0.373149,0.103097,0.202478,0.260922,-0.329928,-0.028583,-0.517318,0.227981,-0.312298,0.128938,0.141617,-0.341303,-0.272204,-0.025230,-0.419373,-0.093281,-0.174504,-0.149555,0.102828,-0.227813,0.919903,-0.671441,0.300308,0.385739,0.346191,-0.410595,0.203014,-0.011811,-0.078816,-0.215766,-0.247940,0.146303,-0.347315,0.206429,0.258718,0.378928,-0.194043,-0.110688,-0.170113,0.320386', '25738406', '26593587', '25922902', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419005', '阿尔及尔之战', '剧情', '一九五四年十月一日，以法属阿尔及利亚首都阿尔及尔的卡斯巴为中心，爆发了阿尔及利亚人反抗运动，这是由于阿拉伯人憎恨法国人长期统治而引起的。人们四处搞破坏，法国政府发觉事态严重，便于一九五七年十月七日，派马丘将军率领四十万大军驻于斯拉姆地区。但是暴乱仍层出不穷，法国人的镇压行动开始升级。', 'Brahim Hadjadj', '吉洛·彭泰科沃', 8.6, 8007, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204588570.jpg', 0.4, 1, 10.2, 44.3, 44.1, '0.069667,-0.167419,-0.711824,0.108000,0.365891,0.450573,-0.110319,0.092405,-0.585648,-0.306130,0.095879,0.079085,-0.056263,-0.464043,0.323429,-0.051167,-0.260360,-0.520115,0.058205,0.060114,0.278622,-0.222675,-0.075972,-0.403466,-0.034531,-0.551181,0.584230,0.483879,-0.219435,0.416572,-0.182132,0.230962,0.229714,0.492138,0.422786,-0.347012,-0.084869,-0.589946,-0.067658,0.377406,-0.380682,-0.407833,-0.279493,0.118155,0.137080,0.690937,0.475287,-0.423459,0.097179,-0.468997,0.492024,-0.433135,-0.261023,0.243677,0.502793,0.142996,-0.016603,0.147073,0.000053,0.034885,-0.238347,0.012858,0.028637,0.034659,0.051090,-0.374755,-0.040925,0.198336,-0.097007,-0.018533,-0.073715,-0.248038,-0.061798,0.995725,-0.244719,0.127790,-0.069812,-0.214892,-0.432187,-0.202616,0.555785,-0.513112,-0.541138,-0.405577,0.129314,-0.404104,0.049462,-0.313712,-0.137423,-0.307080,-0.180284,-0.020123,0.087738,0.626674,-0.765851,0.272377,-0.504404,-0.674980,0.160538,0.373021,-0.073707,-0.765646,-0.106640,-0.040196,0.127330,0.090458,0.255636,0.219890,0.342254,-0.468921,0.298698,0.585695,0.499294,-0.506590,-0.058132,0.000788,0.020778,-0.081570,0.043520,0.591755,0.075105,0.281462,-0.035862,-0.045147,-0.077122,0.024512,0.024282,0.343270', '1291824', '26356488', '3871833', '1293830');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419416', '喜马拉亚星', '剧情', '在喜玛拉雅山长大的亚星（郑中基）练有一身瑜伽好功夫，某日奉父母之命下山参加印度西施家族举办的瑜伽选夫比赛的途中，被恨嫁的大家姐（应采儿）缠住。为了阻止亚星参加比赛，大家姐想出把他变成人见人厌的坏小子的狠招，不想联合三大恶人也没能将亚星改变，不甘心之下，大家姐又找来以坏混世的大胆叔叔（吴镇宇）。可惜大胆叔叔与朋友惊青舅父（刘青云）及其两个外甥已不幸被印度催眠术催眠，连自己是谁都不再晓得，然而亚星总算找到了领门人，赌场的两头神蛇把他教成了沉迷于赌博和吸毒的坏小子，此时，大家姐发现还是原来的亚星比较好，决定陪其一同喝下“印度神奇油”回到从前。©豆瓣', '郑中基', '韦家辉', 5.6, 52063, 'tt0441303', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486984236.jpg', 9.8, 26.4, 42.6, 14.5, 6.7, '0.199354,-0.171882,-0.424309,0.247211,-0.130526,-0.202727,0.021727,-0.025900,-0.337614,-0.154376,-0.081385,0.556413,-0.182494,0.097138,0.143195,0.055826,0.006821,-0.503343,0.001857,0.161438,0.131061,-0.332815,0.035481,-0.011425,-0.148665,-0.140751,0.198914,-0.129672,0.013267,0.439071,0.443797,0.117190,-0.060950,0.041712,-0.129245,0.096723,-0.156913,-0.022768,-0.184091,0.378207,0.220468,-0.011836,-0.103342,-0.107233,0.331327,0.167987,0.208720,-0.188775,-0.001722,-0.267428,0.221716,-0.299098,0.000217,0.118267,0.009219,-0.170906,0.201385,0.316273,-0.077405,0.030303,0.048176,-0.042982,-0.360435,0.370432,0.465010,-0.230255,-0.675445,0.223953,0.007408,-0.152376,-0.155132,-0.444396,0.200227,0.306915,0.222524,0.039931,0.127503,0.098946,-0.383846,0.085250,0.800788,-0.162838,-0.011659,0.034258,0.448239,-0.140633,0.245420,-0.574301,-0.293862,0.393125,-0.020109,-0.120231,-0.183882,-0.048396,-0.431507,-0.242527,-0.095003,-0.217396,0.134140,-0.274532,0.116376,-0.261630,-0.027496,-0.073624,-0.282151,-0.052040,0.068691,-0.163464,0.592104,-0.932829,0.164077,0.215701,0.237673,-0.563994,0.579341,0.108761,-0.159911,-0.075885,-0.013687,-0.161150,0.239673,0.223312,0.360921,0.398424,0.119675,-0.165987,-0.336374,-0.144110', '1877596', '35030151', '1299062', '1296978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419479', '女人步上楼梯时', '剧情', '妈妈桑圭子（高峰秀子 饰）是银座Club的老板娘，年届三十，正值人生转折期，面对着再婚与事业的抉择犹豫不决。圭子早年丧夫，婚姻一直没有起色，事业方面生意也日渐冷清，心境萧条的她只将生活重心放在照顾年轻一代的公关小姐純子、雪子们身上。Club年轻的经理（仲达代矢 饰）暗恋圭子，但以事业为重的他不愿表白，则通过与雪子的肉体关系来淡化心里对圭子的情愫。然而，难以控制的情感让他最终鼓起勇气表白，心境苍凉的圭子会接受吗？ 战后日本大众悱恻的心境在大师成濑巳喜男冷静的长镜头下表露无遗，该片风格是浓重的现实主义色彩，以一个女人的独白贯穿始末，具有浓郁的文化气息。©豆瓣', '高峰秀子', '成濑巳喜男', 9.1, 17882, 'tt0054144', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1805354637.jpg', 0.2, 0.2, 4.5, 32.3, 62.8, '-0.046580,0.160571,-0.573857,0.708053,-0.113141,-0.261649,0.805982,0.343384,-0.405544,-0.479665,0.207817,0.506585,0.023979,0.319669,0.180125,0.020489,0.039372,-0.753247,-0.063694,0.261875,0.158695,-0.424341,-0.219559,0.094039,-0.447898,-0.295522,1.074445,0.215195,-0.421498,0.341375,0.159422,0.186117,0.030583,0.387536,0.030151,-0.376019,-0.179997,0.053148,-0.517891,-0.077257,0.225729,-0.260603,-0.037614,0.311491,-0.152768,0.305220,0.693734,0.124255,-0.356299,0.115308,0.617495,-0.059942,-0.142811,0.220482,0.117514,0.126923,0.196740,0.287422,-0.232004,-0.110647,-0.073367,-0.050971,-0.640447,-0.024750,0.154644,0.189880,-0.546826,0.585468,-0.110125,-0.306371,-0.067708,-0.387881,-0.057400,0.097184,0.260491,0.584643,-0.265324,0.170512,-0.141805,0.073881,0.711887,0.201599,-0.341078,0.566769,-0.594360,-0.329181,-0.107280,-0.458269,-0.586612,-0.102081,-0.128897,0.291296,-0.196280,0.417399,-0.466007,0.044067,-0.059756,-0.019792,0.090036,-0.485627,0.052390,-0.325048,-0.623530,-0.752607,-0.329847,-0.069894,0.375528,-0.280939,0.777524,-0.769653,0.015719,0.387583,0.227012,-0.484254,0.630434,0.123092,-0.052982,-0.202855,-0.149178,0.508251,-0.513219,-0.053332,-0.136243,0.275697,-0.225784,0.005855,-0.337598,0.482765', '35287908', '26354526', '25880986', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419581', '千杯不醉', '喜剧', '小敏（杨千嬅饰）身为一个啤酒女郎，看尽了很多男人喝醉酒时的糗态，所以对男人甚有戒心，而黑社会老大九哥（方中信饰）对她情有独钟。厨师米高（吴彦祖饰）因为辛苦经营的餐厅结业，酒量甚浅的他醉倒在小敏的面前。两人互诉心声之余还互相鼓励，小敏为了减轻米高的负担，租下了米高经营不善的餐厅，两人一起经营咖啡屋。米高受到的饮食界女王赵洁（胡静饰）的青睐，小敏知道是米高翻身的好机会，不敢阻止之余并决定把小餐厅结业。惟利是图的赵洁无法忍受，想回到小敏身边，本来千杯不醉的小敏，也在朋友的刻意计划下醉倒了，酒后吐真言，使米高惊讶。©豆瓣', '杨千嬅', '尔冬升', 6.3, 37031, 'tt0475534', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p486768171.jpg', 1.5, 12.2, 60.7, 20.3, 5.3, '0.226978,0.067743,-0.669283,0.387699,-0.192256,-0.202488,0.513920,0.284992,-0.415338,-0.091450,0.009599,0.636830,-0.168911,0.352690,0.101504,-0.261907,-0.039542,-0.608028,-0.100992,-0.113084,-0.095228,-0.436653,-0.109033,-0.230110,-0.587655,0.040136,-0.223722,-0.134694,-0.174327,0.449581,0.336766,-0.437842,0.383668,0.377454,-0.031430,-0.243893,-0.084123,-0.002686,-0.224565,0.213396,0.160815,-0.043359,0.015523,-0.016164,0.568663,0.162318,0.508204,0.072334,-0.721962,-0.037553,0.219007,-0.186884,0.116886,-0.142804,0.254495,-0.108931,0.396615,-0.356196,-0.067771,-0.010827,0.349512,-0.027311,-0.356075,0.100371,0.089954,-0.442889,-0.369505,0.618890,-0.171491,-0.207908,0.292116,-0.279114,-0.232119,0.171861,0.451001,0.292335,-0.199679,0.276193,-0.552508,0.061852,0.613519,0.460941,0.108867,0.208665,-0.310275,-0.546084,-0.261464,-0.043963,-0.316328,-0.082113,0.163761,0.037211,0.115567,0.180888,-0.370372,-0.074974,-0.206598,0.104952,0.017502,-0.289733,-0.051377,-0.261502,-0.007204,-0.323505,-0.094512,0.081112,0.168104,-0.344895,0.701141,-0.549537,0.345370,0.427734,0.722653,-0.498572,0.728576,0.025152,0.029519,-0.076802,-0.338206,0.198830,-0.240099,0.024084,0.214692,0.498503,-0.137263,-0.390934,-0.508966,-0.044005', '3055049', '3212120', '25907086', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419582', '东京塔', '剧情', '21岁的透（冈田准一饰）爱上了母亲的朋友、年长他二十岁的已婚妇女诗史（黑木瞳饰），他们一见钟情并开始了地下恋情。透的好朋友耕二（松本润饰）也与家庭主妇喜美子（寺岛忍饰）有不伦关系，但情感十分复杂难解，他同时还有一位女友。三年来透听诗史喜欢的音乐，看诗史喜欢的书，每天下午在家等诗史打来的电话。他不能主动打给她，这是两人的约定。渐渐地，他越来越不能满足这样的关系，他向诗史提出了一起生活的要求。诗史是理性的，她清楚所拥有的一切都是丈夫给予的，离开丈夫意味着什么诗史清楚不过，所以对于透提出的要求她一直模糊回避。不过，当透在派对上不顾一切地当着众人的面向她表白并离去后，诗史终于做出了决定……©豆瓣', '黑木瞳', '源孝志', 7.5, 13871, 'tt0475760', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1879777049.jpg', 0.6, 3.8, 34.1, 43.9, 17.5, '0.362849,-0.036393,-0.662067,0.698125,-0.298430,-0.157140,0.558132,0.083849,-0.601397,-0.266178,-0.167657,0.844736,-0.193392,0.205942,0.194660,0.224959,-0.279149,-0.784495,0.066456,-0.158471,-0.081584,-0.582787,0.238100,-0.030216,-0.199357,0.083244,0.527515,0.131521,-0.066290,0.410528,0.323192,0.281417,0.262433,0.736309,-0.157264,-0.080321,-0.332727,0.022470,-0.342996,0.131020,0.326538,0.013489,-0.137252,0.132493,-0.082816,0.433398,0.222476,0.014750,-0.419607,0.195806,0.366193,-0.138366,-0.086949,0.361482,0.206906,0.271785,0.352202,0.253377,-0.082761,0.008049,-0.241033,0.134517,-0.385469,0.138342,0.173608,0.184618,-0.420341,0.411687,-0.077468,-0.082270,0.095848,-0.247106,0.035385,0.119563,0.327530,0.439577,-0.084531,0.114178,-0.416594,-0.047670,0.529354,0.150189,-0.038273,0.637698,-0.372916,-0.488804,-0.083310,-0.233706,-0.366110,0.101033,-0.099265,0.186763,-0.227053,-0.041010,-0.248671,-0.260738,0.118730,-0.185917,0.239867,-0.753749,-0.056992,-0.162282,-0.262383,-0.563502,-0.401172,0.072263,0.065752,-0.438251,0.708538,-0.967874,0.145872,0.399572,0.446783,-0.691453,0.762034,0.386823,-0.161637,-0.300800,0.075660,0.336480,-0.067433,0.116060,0.172344,0.209319,0.248523,-0.065243,-0.360969,0.356215', '2052978', '1297052', '1418613', '1389971');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419584', '龙咁威2', '剧情', '龙威（郑中基 饰）及好兄弟吴树喜（李灿森 饰）、黄金舟（张达明 饰）已成为警察2年了，但仍然沉迷游乐。他们几个来到了皇母瑶池村泡温泉，竟然破坏了飞虎队的围捕计划，原来是该村村民猫屎强偷走了镇村之宝的皇母娘娘像。为了平息民愤，警队决定把龙威几个派到该村当警长。村民们都觉得他们是瘟神，处处为难他们。龙威喜欢上了村中女孩小柔（杨爱瑾 饰），小柔父亲见龙威的骨骼精奇，便决定教会龙威咏春。龙威学有所成，打败了临村恶霸。因为龙威等人的善良，村民们也消除了对他们的成见。一年一度的皇母娘娘诞又来了，警方认为猫屎强会再次回到该村偷另一尊佛像，决定这次要将他绳之于法，但龙威却觉得猫屎强的到来是另有原因……©豆瓣', '郑中基', '谷德昭', 6.3, 4072, 'tt0471243', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2360061431.jpg', 3.9, 15.2, 51.3, 19.8, 9.8, '0.101021,-0.184540,-0.430521,0.321258,-0.118910,-0.227145,0.442796,0.159070,-0.664165,-0.248274,0.273212,0.440498,-0.042946,0.234958,-0.169299,0.000150,-0.215990,-0.415548,-0.135440,-0.131448,-0.077206,0.100401,-0.013774,-0.199365,-0.065588,-0.180941,0.219733,0.084630,-0.003812,0.257194,0.422438,0.100545,0.008424,0.254657,-0.090426,0.105425,-0.116600,-0.068756,-0.162837,0.120624,-0.244451,-0.070604,-0.155807,0.238989,0.111351,0.249735,0.526918,-0.317101,-0.428270,-0.269147,0.159910,-0.312423,0.035299,0.279231,0.413225,0.111063,0.172516,0.226581,-0.094477,-0.063689,0.142333,-0.162968,-0.329905,0.126700,0.060861,0.054422,-0.422024,0.228388,0.073694,0.063721,-0.165717,-0.285247,0.204664,-0.055457,-0.000969,0.449764,-0.138426,0.079386,-0.548670,0.197299,0.736870,-0.338606,-0.070322,-0.105690,-0.046134,-0.395523,0.157247,-0.209399,0.134168,-0.016559,0.512575,0.020661,-0.160342,-0.000870,-0.556780,-0.209511,-0.299918,0.107983,-0.250445,-0.309308,0.126566,-0.259643,0.044092,-0.198660,-0.149558,0.210423,0.197624,-0.101536,0.600541,-0.474520,0.257048,0.522548,0.303262,-0.662987,0.335127,-0.214261,-0.228992,-0.280135,-0.131887,-0.130734,0.126567,0.288548,0.481216,0.245343,-0.194837,-0.364751,-0.176779,0.080172', '25721544', '26280899', '1305915', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419856', '不朽的园丁', '剧情', '英国驻肯尼亚大使馆的外交官贾斯汀（拉尔夫·费因斯 Ralph Fiennes 饰）为人随和、生活平淡，平日只爱在自己的园子里打理花草树木。然而，有一天，厄运降临到这名超然物外的男人身上。他的妻子泰莎（蕾切尔·薇兹 Rachel Weisz 饰）――一名主持正义的律师，被发 现陈尸郊外，调查结果为被其情人杀害。贾斯汀遭此晴天霹雳，愤怒过后的他仔细考虑，觉得官方的说法漏洞百出，于是这名平和温柔的男人誓要找出妻子身亡的真相。泰勒经过重重困难取证，终于逐渐接近事件的真相，原来泰莎发现了这里一间有着深厚政治背景的英国药厂在这里利用爱滋病人试验他们的新药，并导致了数以百计的艾滋病患者惨死！©豆瓣', '拉尔夫·费因斯', '费尔南多·梅里尔斯', 7.9, 27159, 'tt0387131', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p824408304.jpg', 0.3, 1.8, 22.4, 51.2, 24.2, '0.159854,0.075412,-0.558994,0.436155,-0.155943,-0.021653,0.663591,0.146916,-0.654045,-0.380714,0.262233,0.586235,-0.126111,0.144101,0.306070,0.153776,-0.340273,-0.646431,-0.068456,-0.214393,-0.199896,-0.542929,-0.178138,-0.323586,-0.030851,-0.272426,0.252591,0.088067,0.008978,0.318494,0.246789,0.644813,0.017393,0.551600,0.108130,-0.058618,0.209554,-0.292350,-0.034188,0.071530,0.133517,-0.256831,-0.021167,0.150937,-0.125977,0.556482,0.506723,0.031722,-0.238021,-0.226233,0.515891,-0.178731,0.108032,0.148844,0.410894,-0.125065,0.023785,0.273086,-0.242760,-0.242012,0.064676,-0.094397,-0.657986,-0.056273,0.036577,0.144922,-0.354328,0.164358,-0.133866,0.121916,-0.088812,-0.124097,0.274736,0.301463,0.346072,0.336806,-0.029624,0.169156,-0.402219,0.147549,0.486538,0.055859,-0.315274,0.232908,-0.529104,-0.379338,0.063603,-0.207307,-0.407188,-0.016481,0.349167,-0.127747,-0.227417,0.132924,-0.335399,-0.227595,-0.367790,-0.192756,-0.108823,-0.127880,-0.246209,-0.553481,-0.304209,-0.262182,-0.396952,-0.176642,-0.063346,-0.224073,0.592865,-0.540406,0.158103,0.434228,0.117367,-0.461781,0.395621,-0.108327,0.220549,-0.170173,-0.267250,0.578481,0.315571,0.196510,0.049340,0.108848,-0.155591,-0.019170,-0.321252,0.170695', '30143939', '1301022', '3263169', '4132395');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419901', '超级无敌掌门狗：人兔的诅咒', '喜剧', '村民们要参加一年一度的蔬菜大赛啦，他们培育出来的蔬菜超级棒，不料却招来了害虫——野兔的骚扰。野兔身材高大，神出鬼没，村民们一筹莫展，唯有请来捉兔专家华理士。当然，华理士的爱狗勒密特也在捉兔队伍之列。华理士和勒密特设计出各色各样的捉兔工具，村民以为大可放心时，华理士却犯了一个严重的错误：他竟然错误操作机器，让自己和野兔的思想发生对调，闹剧更加轰轰烈烈。互换了身份的华理士和野兔，如何让自己回到原来的世界，而野兔就注定要被除掉吗？©豆瓣', '彼得·萨利斯', '斯蒂夫·博克斯', 8.3, 32228, 'tt0312004', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p449654474.jpg', 0.2, 1.1, 17.7, 47.2, 33.8, '0.209698,-0.097131,-0.219629,0.192753,-0.119426,0.003929,0.227371,0.274328,-0.122642,-0.068341,0.107880,0.537302,-0.008885,-0.050647,0.061078,-0.070318,0.096026,-0.631786,0.059727,-0.019610,-0.338528,0.189253,-0.237027,-0.394856,-0.028732,-0.342237,0.291643,0.132394,-0.358712,0.215192,0.328204,-0.081123,0.012190,0.236370,-0.126775,-0.033364,0.216596,-0.021561,0.040034,0.025471,-0.124192,-0.138097,-0.358056,0.168267,0.063195,0.202165,0.861996,-0.399650,-0.208539,-0.221193,0.185917,-0.439292,0.217493,0.032420,0.465773,-0.003530,0.215781,-0.212276,0.142109,0.229838,0.021907,-0.112838,-1.032130,0.191190,-0.090950,0.045370,-0.447854,0.158964,0.138760,0.221615,0.255300,-0.073900,0.242986,0.127302,0.054830,0.408316,0.151744,-0.151677,-0.561145,0.256546,0.656931,-0.153356,-0.013340,-0.046499,-0.003447,-0.552343,0.179990,-0.526118,-0.036316,-0.116948,0.457945,-0.148978,-0.590196,0.208970,-0.582962,0.109353,-0.196650,-0.268803,0.081498,-0.122797,-0.148823,-0.315011,0.648490,-0.111708,-0.396295,0.161118,0.419958,-0.281649,0.859127,-0.840909,0.246438,0.503761,-0.185011,-0.618877,0.340234,-0.436218,0.249272,-0.116160,-0.286252,-0.413322,0.476972,0.472628,0.561576,0.321270,0.152420,-0.580220,-0.323988,0.341046', '3718665', '24284209', '26678784', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419903', '血溅13号警署', '剧情', '卧底探员杰克·罗尼克（Ethan Hawke 饰）为执行任务期间两位搭档的身亡而自责，于是调离了原岗担任13号警署的警长，心理医师艾丽科斯定期为他辅导，但杰克用玩世不恭的态度掩饰苦闷。新年夜里，大雪骤降，13号警署只有杰克、老警员贾斯帕和秘书爱丽丝三人值班，新近落网的黑帮头目毕绍普（Laurence Fishburne 饰）与另外三名罪犯正在押解的途中，由于大雪封路，押解车拐入13号警署暂歇，艾丽科斯也不得不滞留警署。两名押解警加入了庆祝新年的小型聚会，突然之间形势急转直下，押解警中弹身亡，数十名武装人员包围了13号警署并切断了杰克等人与外界的联系，杰克从入侵者的身上搜出警员证件，发现对方是长期与毕绍普合作的警队败类，现在为防止事情败露欲杀人灭口，杰克只好借助四名犯人的力量，和全副武装的警队败类们展开连番激战。本片翻拍自1976年由卡朋特指导的同名影片，获2005年加拿大导演协会最佳音效剪辑奖。', '伊桑·霍克', '让-弗朗索瓦·雷切', 6.9, 9828, 'tt0398712', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p850901507.jpg', 0.8, 5.8, 50.1, 35, 8.2, '0.089325,-0.384479,-0.306917,0.272691,0.092352,-0.177706,0.531315,0.333092,-0.476790,-0.416872,0.412010,0.353880,-0.078482,0.070898,0.619213,-0.371300,-0.715366,-0.804306,-0.136811,-0.181706,-0.412353,-0.318132,0.081461,-0.482206,0.146652,-0.447226,0.443819,0.008727,-0.181297,0.609187,0.389273,0.466969,-0.406723,0.404728,0.117056,-0.240355,0.526102,-0.449845,-0.317784,0.238219,-0.152276,-0.258028,-0.161045,-0.293297,0.241310,0.631569,0.639691,0.158699,-0.138343,-0.065983,0.028509,-0.397865,0.034544,-0.117283,0.596697,0.293528,-0.005004,0.203673,-0.160159,-0.006582,-0.152836,0.008988,-0.519112,0.294910,-0.078699,0.032492,-0.272922,0.139320,-0.362162,0.255811,0.120683,-0.129326,0.118482,0.340230,0.028084,0.284629,0.141470,0.055540,-0.322291,0.189293,0.572283,-0.185398,-0.116687,-0.182046,0.069535,-0.429585,-0.025429,0.062408,-0.193200,-0.018255,0.241921,-0.112695,0.062822,0.086291,-0.441818,-0.120468,-0.501319,-0.160804,-0.216262,-0.163582,0.091554,-1.143622,0.050820,0.127903,-0.114702,0.077506,0.243813,0.304509,0.414458,-0.470612,0.233095,0.456237,0.119569,-0.580096,0.389897,0.178837,0.263140,-0.315693,-0.073624,-0.165602,0.543039,0.622819,0.201734,0.288890,-0.151444,-0.390405,-0.101196,-0.175848', '6517421', '25723905', '1293572', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419904', '龙在少林', '喜剧', '小龙（释小龙 饰）被师父派下山寻找佛缘，第一次来到大城市的他，不幸与师兄失散。还好遇到了流浪儿肥虫（郝邵文 饰），才不至于挨饿受冻。肥虫见小龙武功高强，便决定追随他。随后二人又碰到了英雄救美的古董爱好者一山（元彪 饰），一山被小龙的执着精神打动，决定帮助他一起寻找佛缘。原来一山的兄弟（徐锦江 饰）正是某个倒卖文物团伙的头目，而他们正在倒卖的，正是小龙师父的寺院丢失了的佛首，小龙三人得知后，便和被一山救下的少女小萱（徐若瑄 饰），一起踏上了寻回佛首之路……©豆瓣', '释小龙', '朱延平', 6.9, 20530, 'tt0116135', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2591009147.jpg', 0.7, 5.3, 52.2, 31.6, 10.3, '0.441159,-0.276001,-0.484279,0.402019,0.105783,-0.656668,0.487041,0.035922,-0.420134,-0.173897,0.487940,0.705394,-0.158473,0.236862,0.076625,0.054508,-0.067298,-0.443088,0.004739,-0.108426,-0.197680,-0.234014,-0.217214,0.252680,-0.190295,-0.127809,0.572895,0.115805,0.004716,0.811440,0.273904,0.139114,-0.485789,0.356782,-0.430942,0.369839,0.084207,0.203987,-0.309104,0.093206,0.085950,-0.242795,0.115107,-0.021833,-0.193992,0.126012,0.667833,-0.189659,-0.100345,-0.146425,0.087340,-0.168969,0.144448,0.108704,0.167848,0.174979,0.487124,0.373724,-0.198455,0.004984,0.249281,-0.135085,-0.270245,0.242121,0.447033,-0.025719,-0.640953,0.022756,0.082831,-0.093806,0.062737,-0.422537,0.127685,0.222819,0.206969,0.160834,-0.074363,-0.213229,-0.356127,0.151136,0.482799,-0.521249,0.379155,0.137185,0.455749,-0.364264,0.512756,-0.140824,0.064942,0.178481,0.540200,-0.124244,-0.268212,-0.109010,-0.735562,-0.059730,-0.343860,0.095684,0.024380,-0.068449,0.043919,-0.536373,-0.088140,-0.250739,-0.154030,0.207591,0.198467,-0.202251,0.676765,-0.763916,0.192569,0.492280,0.280783,-0.741393,0.650054,-0.504752,0.008495,-0.186660,0.013738,0.108940,-0.066828,0.330033,0.077579,0.171929,0.001216,-0.343810,-0.275401,0.148213', '3445516', '35256235', '2976123', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419918', '天若有情3烽火佳人', '剧情', '抗日战争初期，武汉军政界世家刘家二公子刘天伟（刘德华 饰）在空军部门任飞行少尉。在一次执行任务时他碰上了火力猛劲的日军，虽然成功逃脱但是受伤不轻，迫降在一个小山村中，被村姑小禾（吴倩莲 饰）救回。在小禾悉心照料下天伟日渐康复，两人相爱了，但是遭到了村长的反对。天伟决定带小禾一起离开村庄，可是小禾却没能赶上飞机。在回基地途中又再次遇到了敌机，两架飞机被日军击落，同僚们觉得天伟连累了大家，但是家人却给他举行了盛大的欢迎仪式，这让天伟非常难受。此时国民政府决定前往重庆，为保护大部队空军将执行一次死亡任务，即轰炸日军基地。天伟决定不顾家人反对参加，大队长（方中信 饰）先是反对后在天伟坚持下被感动，同僚之间误解化除。此时小禾也来到了武汉找到了天伟，并且表示无论如何也会等天伟回来。行动开始后，小禾和伟母一起在基地等待天伟，却只等来天伟殉国的消息，小禾不顾阻挠坚持清理机场等待奇迹，所有人都被感动了，最后天伟真的奇迹般的飞回了基地。', '刘德华', '杜琪峰', 7.1, 11156, 'tt0117072', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352280675.jpg', 0.8, 5.2, 47.1, 33.1, 13.8, '0.088452,0.196936,-0.883929,0.196200,0.218114,-0.220715,0.305858,0.125786,-0.474753,0.024247,0.284039,0.621960,-0.053902,-0.024763,0.019312,-0.271209,-0.335168,-0.479131,-0.011404,-0.128538,-0.433429,-0.377698,0.225784,-0.175353,-0.049065,-0.020883,0.556491,0.280397,0.059730,0.593752,0.080997,0.161536,0.103640,0.789316,-0.115792,-0.007508,0.188212,-0.186764,-0.297378,0.471214,0.068700,-0.136693,-0.113963,0.261140,0.213357,0.256363,0.609230,0.042480,-0.162902,-0.179025,-0.191601,-0.475341,0.166430,0.191336,0.412967,0.018957,0.035412,0.222803,-0.256045,0.106048,-0.063537,0.109829,-0.331799,0.194230,0.064834,-0.051636,-0.739815,0.260955,-0.229490,0.148750,-0.022148,-0.459661,0.385142,0.745797,0.234982,0.206801,-0.422693,0.316672,-0.499583,0.091684,0.888079,-0.277904,-0.046311,0.112596,0.086436,-0.316768,0.136917,-0.152673,-0.168155,0.109659,0.081833,0.096179,-0.179191,-0.044535,-0.376110,-0.130196,-0.584601,-0.375099,-0.221128,-0.422605,-0.106017,-0.645704,0.173538,0.113955,-0.449972,0.433667,0.037733,-0.024181,0.602626,-0.772528,0.095647,0.438442,0.400092,-0.591256,0.444864,0.296144,0.124388,-0.035042,0.360639,-0.001600,0.000287,0.476832,0.400129,0.213764,-0.235153,-0.223395,-0.194126,