INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419924', '师兄撞鬼', '喜剧', '探员张骠（董骠 饰）在调查一起制毒案时被毒枭邓立洋（方刚 饰）杀害，邓将现场伪装成张骠因赌债自杀。死后的张骠不甘名誉受损，贿赂阴间法官得以还阳，由此开始寻找救星雪恨。这边厢，警队新人阿星（周星驰 饰）与张骠老搭档李锦（冯淬帆 饰）搭配成新的小组，张骠因阿星是自己命定救星，遂附身于枪上，施法帮助阿星接近李锦之女阿玉（陈德容 饰），以使其帮助自己报仇。邓立洋预感张骠返阳，请出张骠命定克星邪法师助阵。习练茅山道术的李锦被张骠阿星二人整治，心怀不满伺机报复，却被邪法师利用，将张骠鬼魂封印。经茅山祖师指点，阿星与李锦准备了破法灵药，更请出祖师附身与邓立洋、邪法师决战。©豆瓣', '周星驰', '刘仕裕', 7.2, 30166, 'tt0100600', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2281804284.jpg', 0.6, 4.9, 45.8, 33.4, 15.3, '-0.190032,-0.046222,0.079950,0.473310,-0.235948,-0.353962,0.356732,0.035455,-0.164529,-0.437004,0.165823,0.182239,0.091263,0.281956,-0.072412,-0.177496,-0.072511,-0.485381,0.123113,-0.060623,-0.280804,-0.263659,-0.326920,0.039427,-0.287786,-0.421554,0.396723,0.074138,-0.540333,0.138213,0.314143,0.384719,-0.333148,0.011700,-0.064340,-0.128027,-0.271010,0.010228,-0.203407,-0.131928,-0.084145,-0.517958,-0.112101,-0.094365,-0.088784,0.116957,0.432058,-0.189091,-0.022055,-0.421977,0.176593,-0.391315,0.085130,0.198697,0.162061,0.169237,0.192599,-0.019593,-0.211421,-0.341468,-0.002832,0.003362,-0.598005,0.142597,0.186062,-0.194091,-0.370089,-0.055803,-0.258474,0.452531,0.085799,-0.243695,0.163435,0.162639,0.254521,0.126744,-0.049396,-0.196610,-0.349568,0.346017,0.139231,-0.287146,0.357156,-0.315023,0.233287,-0.590097,0.077814,0.052357,0.096443,-0.011621,0.640662,-0.187930,0.275299,0.123466,-0.280384,-0.288277,-0.309318,0.539740,-0.106038,0.244088,0.325588,-0.765644,-0.179321,0.302381,0.131631,0.077754,0.434114,-0.406857,0.555077,-0.252489,0.226450,0.113350,0.218441,-0.475436,0.472558,-0.098689,0.113510,-0.492824,-0.041894,-0.063556,0.342623,0.361597,0.355755,0.234065,0.088054,0.344391,-0.046420,0.107141', '3318306', '2369613', '26275494', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419933', '伊丽莎白镇', '剧情', '德鲁（奥兰多·布鲁姆 Orlando Bloom饰）陷入了人生的谷底期，他为公司带来了数亿元的损失，逃不过被老板炒鱿、被女友甩掉的命运。万念俱灰中，他设计了一系列完美却又搞笑的自杀计划，企图一死了之。一串电话铃声，中止了他的自杀进程——父亲的死讯给德鲁带来了迫在眉睫的任务，他必须尽快回到遥远的伊丽莎白镇去处理后事。于是，接下来的事情就像一连串奇妙的隐喻，让德鲁从谷底里重新看到希望。他在飞机上遇见空姐克莱尔（克尔斯滕·邓斯特 Kirsten Dunst饰），她美丽大方，善解人意，总是在德鲁最寂寞低落的时候给予窝心的慰藉。而德鲁的母亲，虽然总是神经兮兮，对生活的热忱和乐观却深深感染了儿子。在爱情和亲情的温泽下，德鲁渐渐重拾生活的信心日渐坚壮，带他走出生命低谷。©豆瓣', '奥兰多·布鲁姆', '卡梅伦·克罗', 7.4, 52574, 'tt0368709', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p583220507.jpg', 0.6, 4.7, 35.7, 40.7, 18.3, '0.059590,0.374696,-0.642802,0.557664,-0.351413,-0.349164,0.946781,0.302779,-0.479544,0.081045,-0.002394,0.748369,-0.005578,0.131635,0.467153,0.049919,-0.541901,-0.721110,0.120997,0.034200,-0.201609,-0.484861,-0.338222,-0.253768,0.075604,-0.395361,0.504062,0.414974,-0.162528,0.417104,0.007250,0.538712,0.178741,0.746733,-0.053365,0.257507,0.051862,0.106451,-0.099005,-0.039855,0.333766,-0.154253,-0.071998,0.425477,-0.045841,0.378421,0.508544,-0.027306,-0.421173,0.054132,0.353447,-0.352688,0.156376,0.079654,0.095214,0.123765,0.070613,0.053955,-0.609054,-0.039695,0.001973,-0.059285,-0.843136,0.061247,-0.049190,0.040878,-0.512098,0.445105,-0.207539,0.177767,0.414887,-0.263868,0.073899,0.429198,0.445784,0.668502,-0.340316,0.062658,-0.146907,0.171064,0.722377,-0.156304,-0.129140,0.390523,-0.189218,-0.261962,0.064407,-0.200062,-0.493435,-0.181257,0.550776,0.166502,-0.199079,0.307626,-0.434240,-0.045636,-0.352780,-0.454342,-0.265091,-0.625697,-0.138563,-0.340808,-0.146676,-0.291413,-0.395143,-0.084793,0.010896,-0.250102,0.680172,-0.679468,0.471102,0.465476,0.129725,-0.460265,0.269053,0.123575,0.229584,-0.183117,0.087053,0.434905,-0.144172,0.360157,0.204375,0.334929,-0.036345,-0.021529,-0.537483,0.967842', '35158375', '25763555', '25828589', '6745433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419934', '空中危机', '剧情', '凯尔·普拉特(茱迪·福斯特饰)的丈夫坠楼身亡，满心创痛的她只想尽快带着6岁的女儿赶回温暖的家，登上从柏林飞往纽约的飞机。然而飞机起飞后女儿不翼而飞。所有的证据都证明她的女儿没有登机，所有的人都怀疑凯尔的神经有问题，但是作为一个母亲，她深信不疑自己的女儿就在这架飞机上，并 且誓要把莫名失踪的女儿找回来。凯尔是飞机的设计者，对于飞机的每一个内部构造都了然于心，带领观众揭开飞机每一个构造的时候，也纷纷揭开了一个惊天的阴谋。最终飞机爆炸，紧急迫降。当被疏散的乘客和机组人员看见飞机上走下抱着女儿的凯尔时，对母亲的决心和信心涤荡起从心而起的尊敬。©豆瓣', '朱迪·福斯特', '罗伯特·斯文克', 7.1, 32299, 'tt0408790', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2191674732.jpg', 0.5, 4.4, 44.2, 40.2, 10.7, '0.226403,0.037390,-1.004227,0.648214,-0.137965,-0.284032,0.851721,0.093805,-0.403970,-0.007282,0.374798,0.894356,-0.022235,0.450361,0.391100,0.220910,-0.563007,-0.653049,-0.161083,-0.222894,-0.529167,-0.516982,-0.054919,-0.180898,0.157713,-0.216879,0.450933,0.163380,0.077541,0.542594,0.359088,0.035287,0.108448,0.678721,-0.355631,0.022542,-0.238250,-0.065732,0.010380,0.243620,0.133061,-0.157675,0.102549,0.338026,-0.130717,0.589680,0.682816,-0.266605,-0.040107,-0.081155,0.169813,-0.368903,0.205004,0.307169,0.151712,0.280460,-0.124437,0.084201,-0.300835,0.013728,0.282635,0.209999,-0.706572,-0.066476,-0.119387,-0.113692,-0.770944,0.348184,-0.466385,0.036323,0.109916,-0.380812,0.500138,0.335523,-0.241879,0.470393,-0.501654,0.121764,-0.574500,-0.077648,0.622448,-0.112302,-0.066117,0.268756,-0.123809,-0.442367,0.004261,-0.122362,-0.408755,-0.078276,0.387171,0.211556,-0.142257,-0.014147,-0.326538,0.090453,-0.366425,-0.560713,-0.119717,-0.541976,-0.064876,-0.419197,0.010722,-0.182430,-0.323842,0.086687,0.067887,-0.130226,0.835793,-0.601698,0.281473,0.446029,0.126421,-0.481612,0.603020,0.006077,0.053544,-0.207850,-0.009101,0.130568,-0.087403,0.555879,-0.134161,0.412031,-0.067282,-0.067953,-0.333874,0.491859', '3111650', '1866424', '1306801', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419936', '战争之王', '剧情', '本来美国移民尤瑞（尼古拉斯•凯奇 Nicolas Cage 饰）的家族生意是开饭馆。但是一个偶然的机会令他踏入了军火生意的大门，从此开始了贩卖武器的“职业生涯”。尤瑞遇事机智，胆大心细，这不仅让他成功俘获了美女埃娃的心，还使得他在地下军火生意中愈战愈勇。但是，不顺心的事情也随之而来：出现了生意上的死对头和一名老是盯着他的国际警察；弟弟染上毒瘾，并在一单生意交易中丧了命，而且，尽管他在竭力维护自己在家庭里的正义形象，但却掩盖不了真相。尤瑞开始反省自己生意的正义性，拷问自己的良心，但一切太迟，他已经众叛亲离……©豆瓣', '尼古拉斯·凯奇', '安德鲁·尼科尔', 8.7, 340659, 'tt0399295', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p792282381.jpg', 0.1, 0.6, 10.1, 43, 46.2, '0.024741,0.270529,-0.642883,0.535529,-0.287368,-0.345825,0.556806,0.282499,-0.537731,-0.150287,0.301265,0.744443,-0.004516,0.042259,0.157716,0.271241,-0.194925,-0.712423,0.253296,-0.160347,-0.112441,-0.319244,-0.317531,-0.510664,-0.373767,-0.156991,0.533513,0.400358,-0.131349,0.104826,0.151396,-0.160961,0.269225,0.492691,-0.182159,-0.075018,0.083981,-0.063090,-0.178799,-0.051374,0.179190,-0.501154,-0.057239,0.548112,0.161626,0.765058,0.339541,-0.135734,-0.298775,0.131859,0.131714,-0.413362,-0.039464,0.249791,0.324963,-0.047814,0.141091,0.221200,-0.364565,-0.104469,0.077347,0.028112,-0.746821,-0.143631,-0.166297,0.172180,-0.833901,0.624028,-0.094996,0.142579,-0.311360,-0.254721,0.095749,0.183886,0.097896,0.282056,-0.319705,0.201607,-0.791237,0.125455,0.715907,-0.107183,0.101050,0.717508,-0.297897,-0.478952,-0.315459,-0.473888,-0.404899,-0.261862,0.424745,-0.265030,-0.247597,0.387195,-0.608190,-0.005969,-0.132344,-0.086459,-0.336264,-0.246821,-0.019393,-0.284776,-0.197426,-0.412547,-0.498934,0.276429,0.200841,-0.276216,0.423878,-0.921359,-0.167916,0.684625,0.284785,-0.648294,0.542251,0.125178,0.263948,0.051532,-0.456227,0.025966,-0.037201,0.246493,0.166184,0.324058,0.205521,-0.415584,-0.077927,0.701083', '1299965', '1783461', '10774184', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419939', '超完美男人', '喜剧', '单亲妈妈简（海瑟•洛克莱尔 Heather Locklear 饰）带着两个女儿霍莉（希拉里•达芙 Hilary Duff 饰）和佐伊一起生活。简虽然在照顾两个女儿方面得心应手，可是在处理自己的感情方面却弄得一塌糊涂，她总是和一个不怎么样的男人开始同居，然后很快出现问题，最后分手。简走马灯似的换男友可苦了两个女儿，她们跟着妈妈一起老是居无定所，从一个男友家搬到另一个男友家，从一座城市搬到另一座城市。为了能过上正常人的生活，霍莉决定用自己的力量帮妈妈寻找一个可靠的完美男人。当发现简的同事心地善良的兰尼开始追求简时，霍莉正式开始行动了。她暗中以兰尼的名义给妈妈送花、发email、写情书，然而老实巴交不懂情趣的兰尼却迟迟未能赢得简的芳心。霍莉的行动进一步升级，然而，事情却开始慢慢失去控制。©豆瓣', '希拉里·达芙', 'Mark Rosman', 6.4, 15025, 'tt0380623', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1452557189.jpg', 1.3, 10, 60.3, 22.7, 5.6, '0.234667,-0.070114,-0.469774,0.550687,-0.275635,-0.436502,0.540669,0.169887,-0.250791,-0.465358,-0.259625,0.628268,-0.097264,0.492054,0.144156,0.057658,-0.298709,-0.576906,0.190792,0.060386,-0.392513,-0.522655,0.086077,-0.335221,-0.181578,0.009936,0.355152,-0.372462,-0.000662,0.268163,0.276112,0.077724,-0.195830,0.388567,-0.210789,0.015001,-0.032600,0.006045,-0.256607,0.217765,0.134895,0.155444,-0.079400,0.058616,0.260306,0.289521,0.635203,0.018651,-0.049200,-0.054856,0.336446,0.083137,-0.178861,-0.094264,0.157011,-0.026806,0.196590,-0.099724,-0.210999,-0.110477,0.248404,-0.469918,-0.428143,0.046974,0.305266,0.099110,-0.560866,0.093983,-0.083171,0.163556,0.073188,-0.368312,-0.009549,0.415535,0.071144,0.427266,-0.349334,0.288477,-0.401483,0.061397,0.542478,0.024274,-0.097036,0.442137,-0.045947,-0.100093,0.161767,-0.076097,-0.543650,0.027220,0.008833,-0.011507,-0.130547,-0.014477,-0.568456,-0.105570,-0.304924,0.072935,0.261042,-0.701456,-0.023557,-0.404027,-0.112246,-0.335123,-0.347683,0.222813,-0.205764,-0.294203,0.783921,-0.723542,0.077091,0.391545,0.222455,-0.678929,0.393452,0.193092,0.275191,-0.410782,0.144849,0.191661,-0.023939,0.199869,0.236684,0.238013,-0.118288,0.139807,-0.388708,0.463783', '26730542', '1309033', '35048413', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419953', '逃之夭夭', '剧情', '安东尼•齐默是洗黑钱高手，但他手法高超，警方想方设法也无法将其抓获。而另外一个似乎毫不相关的浪漫故事在法国南部上演。弗朗索瓦(伊万•阿达勒Yvan Attal  饰)刚刚与女友分手，坐在开往蓝色海岸的火车上，旅游散心。怎料一段艳遇完美上演——风情万种的吉雅拉（苏菲•玛索 Sophie Marceau 饰）上前搭讪，邀他共度周末。短暂的浪漫过后，吉雅拉无故失踪。弗朗索瓦千里寻芳踪，在辗转反复的寻找过程中，他发现了吉雅拉不可告人的秘密。可是，更大的秘密，恐怕是安东尼和弗朗索瓦自己的故事……©豆瓣', '苏菲·玛索', '热罗姆·萨尔', 6.9, 18244, 'tt0411118', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1134697661.jpg', 0.8, 7, 48.9, 33.9, 9.4, '0.276943,0.054986,-0.661084,0.520792,0.310605,-0.211071,0.638202,0.079612,-0.510318,-0.163161,-0.202243,0.490845,-0.310586,0.016639,0.532640,0.172824,-0.512061,-0.783778,0.350802,-0.055333,-0.336312,-0.697789,-0.189933,-0.275332,0.141980,-0.234956,0.124288,-0.134581,-0.204271,0.336240,0.291229,0.484071,-0.561367,0.544782,-0.027048,-0.051934,0.223572,0.034388,-0.251760,0.391446,-0.076525,-0.407259,-0.144174,0.005886,-0.082595,0.353959,0.884336,-0.125707,0.100089,0.186590,0.178330,-0.319974,-0.231768,-0.074248,-0.021309,-0.131296,0.133488,0.230936,-0.251453,-0.276702,0.207718,-0.247626,-0.522586,-0.001732,0.108292,0.166744,-0.252154,0.349238,-0.042529,0.118090,0.187543,-0.426373,0.087007,0.497983,0.299244,0.050873,0.164661,0.106685,-0.455854,0.192883,0.598141,0.129509,0.275267,0.432129,-0.210087,-0.258277,0.185694,-0.018787,-0.249231,-0.062523,0.302333,-0.170026,0.030333,0.111802,-0.549980,-0.237541,-0.654761,0.185326,-0.056320,-0.316669,-0.280359,-0.700136,-0.148209,-0.484818,-0.290804,-0.046729,0.041901,-0.169413,0.443713,-0.527162,0.217650,0.826053,0.025793,0.035927,0.630736,0.111145,0.040615,-0.392544,-0.226609,0.401416,-0.127523,0.170101,0.077274,0.180366,-0.029346,-0.017015,-0.649301,0.353295', '1305249', '1309194', '1298197', '1298346');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419969', '无极', '剧情', '穷女孩受到命运女神满神（陈红）的特殊眷顾，长大成人后做了集万般宠爱于一身的王妃倾城（张柏芝），但是因此也成了被命运咒语所诅咒的“永远得不到真爱，除非时光倒流，人死复生”之人。在与北宫爵无欢（谢霆峰）、大将军光明（真田广之）等人进行的爱情角力中，倾城一次次被对方当作筹码，咒语灵验。但是身分卑微的奴隶昆仑奴（张东健）却是真心爱着倾城。他期望用自己接近光速的奔跑来打破加诸在倾城身上的命运锁链，好让她返回人生的起点重获选择的权利。©豆瓣', '张东健', '陈凯歌', 5.4, 204290, 'tt0417976', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167475807.jpg', 16.9, 26, 33.5, 15.1, 8.5, '-0.208356,0.410959,-0.469644,0.449564,-0.400402,-0.155419,0.545029,0.138307,-0.408048,0.087796,0.803555,0.809999,0.192983,0.105568,0.141871,0.221049,-0.042616,-0.675629,0.309411,-0.001470,-0.026701,-0.262724,-0.035268,0.008826,-0.207962,-0.545287,0.789917,-0.076369,0.022179,0.116592,0.298865,0.066958,-0.043263,0.385934,-0.193902,0.106732,-0.081886,-0.079385,-0.457307,0.308152,0.041321,-0.174972,-0.176160,0.358192,-0.539607,-0.104141,0.682233,-0.628789,-0.106962,-0.360229,0.536931,-0.628222,-0.050443,0.373420,-0.396886,0.082561,0.318848,0.302437,-0.016551,-0.022312,0.220116,0.185170,-0.819001,-0.168810,0.233456,0.079916,-0.414199,0.452243,-0.364077,-0.147823,0.147043,-0.480222,0.297066,-0.181946,0.602617,0.485689,-0.703566,-0.118286,-0.452577,0.084796,0.592677,-0.009835,-0.644065,0.122173,-0.249822,-0.247152,-0.084589,-0.494594,-0.670223,-0.007371,0.153425,0.505204,-0.033661,0.576012,-0.668597,0.059094,-0.291517,0.195540,0.097572,-0.750241,-0.192490,-0.027912,-0.199298,-0.323469,-0.366264,0.039917,0.375848,-0.544885,0.856322,-0.688599,0.485105,0.565065,0.566141,-0.717440,0.646054,0.388361,0.226323,0.036048,-0.070242,0.426332,-0.210328,0.430709,-0.010736,-0.008200,-0.056751,0.226805,-0.446665,0.585559', '26759820', '30163500', '24284209', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419974', '玩命快递2', '动作', '超强押运人弗兰克·马丁（杰森·斯坦森 Jason Statham 饰）近期的工作是接送缉毒官员比林斯先生的小儿子杰克，弗兰克与杰克母子相处和谐，但一伙歹徒的突然出现打破了平静，弗拉克与他们在医院首次交手顺利脱险，可为了杰克的安全着想，弗兰克不得不把孩子送到对方手中，并因此被警方确认为绑架嫌犯。弗兰克发觉这次绑架另有深意，策划此次事件的幕后贩毒集团意在通过小杰克将致命病毒传染给参加国际会议的各国缉毒组织高官，以便为自己的犯罪行为扫清障碍。弗兰克承担着杰克母亲奥黛丽的信任，在警方与贩毒集团的追夹中，逐渐逼近幕后策划者詹尼（Alessandro Gassman 饰），并与同样身手不凡的詹尼展开天上水下的连场搏杀。©豆瓣', '杰森·斯坦森', '路易斯·莱特里尔', 7.4, 87487, 'tt0388482', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1439362483.jpg', 0.4, 3.2, 37.2, 44.7, 14.4, '0.180694,-0.128219,-0.488437,0.386560,-0.000938,-0.057113,0.594339,-0.026701,-0.566379,-0.247236,0.304826,0.604616,-0.032911,-0.014556,0.445546,-0.085598,-0.423779,-0.711203,-0.210372,0.030908,-0.141502,-0.746401,-0.393235,-0.398981,0.069984,-0.296785,0.436802,-0.016996,-0.195472,0.585327,0.272911,0.331018,-0.391975,0.388529,0.064931,-0.197884,0.163996,-0.368908,-0.600156,0.163423,0.181523,-0.161854,-0.111402,0.136139,0.190610,0.511862,0.546129,-0.266639,-0.109365,-0.105431,0.248240,-0.668318,0.270383,0.042062,0.392879,0.211465,0.136733,0.519720,-0.115498,-0.141792,0.107980,-0.055420,-0.694449,0.158963,0.149389,0.083753,-0.345796,0.182847,-0.300450,0.178609,0.171800,0.035091,0.196557,0.677327,0.309942,0.011440,-0.094439,0.072754,-0.380574,-0.141178,0.650687,-0.287853,-0.066030,-0.183476,-0.128918,-0.428550,0.131421,-0.169981,-0.121819,-0.029896,0.493254,0.004359,0.041459,0.306069,-0.314748,-0.231263,-0.462525,-0.106075,-0.076023,-0.341014,0.081152,-0.884018,-0.145010,-0.211492,-0.216820,0.068146,0.031234,-0.275976,0.277297,-0.743943,0.101611,0.720147,0.238989,-0.364049,0.362616,0.021174,0.284791,-0.405846,-0.468434,-0.031896,0.469598,0.247280,0.137208,0.231321,-0.057094,-0.237941,-0.090754,-0.127311', '1307442', '25723905', '27126336', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419976', '四兄弟', '剧情', '慈祥的老妇人伊芙琳在一次超市劫案中不幸罹难，她的四个养子：鲍比（马克•沃尔伯格 Mark Wahlberg 饰）、安格（泰瑞斯•吉布森 Tyrese Gibson 饰）、杰克（加内特•赫德兰 Garrett Hedlund 饰）以及耶利米（安德雷•本杰明 André Benjamin）纷纷回到小镇，为母亲料理后事。原来，伊芙琳在年轻时热衷慈善，她将当年那四个性格顽劣的孤儿留在自己家中，用悉心的爱和教导抚育他们长大。四个肤色不同的兄弟决定避过警方，自己抓到劫犯为母亲报仇，然而虽然他们枪决了当天行凶的杀手，却发现母亲的遇害另有隐情，耶利米因为财务问题似乎卷入了与当地黑社会的纠纷……究竟是谁杀害了母亲，四兄弟要拼出一个真相……©豆瓣', '马克·沃尔伯格', '约翰·辛格顿', 7.2, 20488, 'tt0430105', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1606100126.jpg', 0.5, 4, 43.6, 40.6, 11.2, '0.124315,-0.035738,-0.541163,0.422694,-0.261828,-0.503764,0.799171,0.244302,-0.371499,-0.531474,0.192218,0.722279,0.093605,0.376541,0.244699,0.114954,-0.257497,-0.565153,0.047996,-0.130147,-0.316427,-0.811838,-0.092995,-0.508927,0.063814,-0.214768,0.233481,-0.058998,0.176554,0.398190,0.382790,0.512249,-0.429033,0.084090,-0.122641,0.157492,0.249476,-0.056620,-0.421065,0.001206,-0.046142,-0.018638,-0.263077,0.170564,0.188174,0.535865,0.586588,-0.218505,-0.061367,-0.240270,0.156643,-0.163133,-0.016622,0.261607,0.388220,-0.254633,0.133867,0.436922,-0.172238,-0.038321,-0.009931,-0.060751,-0.524183,-0.146484,0.185594,0.074887,-0.722562,0.288019,-0.218916,-0.054480,-0.113365,-0.345148,0.090567,0.577189,-0.015729,0.353702,-0.000097,-0.011549,-0.489038,-0.013903,0.705756,-0.137124,0.047877,0.167954,-0.118667,-0.222118,0.084047,-0.200150,-0.276822,0.259166,0.554998,-0.331657,-0.046616,0.414905,-0.182128,-0.451998,-0.460104,0.011346,-0.102927,-0.300341,-0.117337,-0.387699,0.030643,-0.320039,-0.515108,-0.079086,-0.065476,-0.093755,0.624464,-0.768314,0.236174,0.361880,-0.015042,-0.651263,0.369547,0.218398,0.361319,-0.354820,-0.283822,0.229658,0.477234,-0.164380,0.153920,0.104655,0.082229,-0.153889,-0.277149,0.163955', '1301022', '1303036', '10546747', '1293145');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419985', '猛龙', '动作', '黑帮社会错综复杂，黑帮首脑金度升（米高边 饰）越狱成功，让香港警方更是陷入了高度戒备。更棘手的是，金度升正在实施一套复仇计划，把警方头号通缉犯段边虎劫持并杀害。他的下一个目标，正是段边虎的弟弟段边豹。这个险境环生的黑帮世界，竟然牵连进来了一个善良的女子游静。游静是段边虎的女友，却从来没有想过，自己其实只是一个被利用的人，更因此而卷入金度升的复仇计划。眼看香港即将迎来一场风起云卷的杀机，“猛龙”特警队的一众成员（任达华、吴建豪、余文乐、夏雨、周俊杰、黄圣依等饰）开始了惊心动魄的行动。©豆瓣', '吴建豪', '李仁港', 5.8, 9911, 'tt0446313', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1099162167.jpg', 7.2, 23.2, 48.4, 16.2, 5, '0.239096,-0.072234,-0.464523,0.721716,-0.114496,-0.118201,0.537367,0.025253,-0.456599,-0.075215,0.514089,0.525480,-0.164460,0.016657,0.228305,-0.130572,0.024908,-0.731403,-0.081811,0.088140,-0.018579,-0.380274,-0.456725,-0.122750,0.016787,0.000249,0.756245,0.199949,-0.258197,0.463866,0.459290,0.203947,-0.161135,0.802286,0.054178,-0.106414,0.230348,-0.300281,-0.099069,0.055229,-0.243017,-0.429429,-0.040596,0.379259,-0.039363,0.428437,0.664501,-0.267902,-0.018275,-0.489352,0.293036,-0.554109,-0.224604,-0.044887,0.821219,-0.204560,-0.176439,0.256672,0.112019,0.008052,-0.023985,-0.043094,-0.874819,0.194775,-0.028487,0.126157,-0.433588,0.364146,-0.157138,0.184531,0.033495,0.015714,0.021960,0.296751,0.197727,0.189434,-0.275857,0.138345,-0.458513,0.073050,0.777003,-0.160183,0.046629,0.053618,0.041604,-0.526987,-0.219706,0.059289,-0.166086,-0.154171,0.680615,-0.254866,-0.370662,0.232064,-0.431857,-0.091798,-0.421138,-0.109603,-0.058952,-0.405038,-0.122989,-0.447650,-0.103731,-0.216241,-0.236755,0.060474,0.075605,-0.337180,0.451187,-0.642648,0.038161,0.495424,0.156272,-0.814052,0.191292,0.194922,0.227632,-0.214432,-0.182246,0.122826,0.032034,0.380780,0.150460,0.295536,-0.288107,-0.364639,0.065987,0.318813', '26678784', '1301022', '1917313', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419992', '潮涨海岸', '剧情', '纽约的近郊铁路旁，女孩洛斯（祖蒂•弗兰 Jodelle Ferland 饰）整天在破旧的机车里坐着自己的白日梦，她用身边的玩偶编织爱丽丝的行程，而现实却是另一番光景。洛斯的父亲在酒吧里驻唱，收入微薄，嗜酒如命，而且还是一个瘾君子。洛斯的母亲肥硕之极，终因吸食海洛因过量而丧命。为了逃避警察和债主，父亲决定带着洛斯远走高飞，从纽约搬到乡下的农场。途中，父亲的诸般恶习令洛斯忍无可忍，只剩下四个残破的芭比娃娃陪她玩耍。正当她觉得生活无望之时，一个带着养蜂人面纱的女邻居戴尔（珍妮•麦克蒂尔 Janet McTeer 饰）闯入了她的生活。她们同样有一颗向往童话的心。两个人在相互扶持中，重构了那个美好的图景，然而好景不长，一场争斗由此展开……©豆瓣', '祖蒂·弗兰', '特瑞·吉列姆', 7.3, 6482, 'tt0410764', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p802575662.jpg', 1.9, 7.6, 34.1, 35.8, 20.6, '0.329427,-0.130637,-0.655084,0.454995,-0.233149,-0.300761,1.107661,0.377139,-0.540528,-0.146035,0.404359,0.795059,0.037124,0.416408,0.312852,0.250554,-0.456606,-0.423086,-0.054243,-0.069043,-0.043886,-0.207742,-0.342214,-0.072439,-0.166986,-0.158655,0.272441,-0.029534,0.172963,0.489789,0.155286,0.078732,-0.300041,0.309507,-0.105781,-0.098143,-0.007289,-0.041498,0.029574,0.074745,-0.027574,-0.151314,-0.151234,-0.157824,-0.146812,0.299642,0.763948,-0.311543,0.331242,-0.242249,0.058881,-0.240576,-0.238895,0.266357,-0.169257,-0.134361,0.190372,-0.065596,-0.474648,-0.035964,0.276508,-0.020213,-0.653384,0.091554,-0.214905,0.279248,-0.603686,0.471262,-0.104157,0.038909,0.260231,-0.380961,0.035352,0.227301,0.167286,0.454576,-0.185751,-0.047724,-0.540437,0.122744,0.572222,-0.070257,-0.274470,0.285877,-0.341282,-0.076013,0.017034,-0.123748,-0.717147,-0.371307,0.241161,-0.136162,-0.221044,0.172484,-0.884869,0.166549,-0.243191,-0.242572,0.133838,-0.259473,-0.447665,-0.649643,0.032032,-0.472335,-0.281930,-0.005796,0.222483,-0.140560,0.558756,-0.592360,0.248973,0.550074,0.028387,-0.229440,0.563352,0.117586,0.288369,-0.130932,-0.154910,0.439831,-0.094692,0.446541,0.088760,0.333479,-0.194861,0.164847,-0.603423,0.626908', '21619567', '1302133', '1296534', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1419993', '一个烂赌的传说', '剧情', '舒奇是一个天生的赌徒，到澳门赌钱，每次都大起大落，因为一次糊里糊涂与艺员雪发生关系，得到三千块，后投注站买马赢了十五万，他便往卡拉OK消遣，认识了逢赌必输、有一个「玻璃骨」症弟弟的妈妈桑——公主。因为欠债，舒奇被禁锢，公主于是致电卡拉OK熟客莫UNCLE求助，莫UNCLE答应了付五十万，但要公主陪他一个月。之后莫UNCLE突然离奇死亡。混乱中，两人在债主FACE哥手中逃出，不久，却再次遇到莫UNCLE，原来他没有死去……香港一贯赌片甚多，但像本片这样，集中描写一个烂赌鬼的特性，以及他的传奇命运，就很罕见，还奇在拍得不落俗套。本片没有像通常的赌片那样卖弄赌术，没有精美包装和名牌格调，因此并未引起影迷注意，实际上这一部是不错的赌片。', '吴镇宇', '麦子善', 7.9, 8477, 'tt0445841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2196633376.jpg', 0.4, 2.4, 24.2, 48.4, 24.6, '0.345217,-0.076677,-0.708759,0.495174,-0.064714,-0.210903,1.047858,-0.120291,-0.326541,-0.387003,0.034096,0.632918,-0.390051,0.134179,0.197813,-0.215658,-0.083158,-0.374986,0.018403,-0.127927,-0.233136,-0.285154,-0.064165,-0.067697,-0.444913,-0.177253,0.323182,0.191393,-0.353482,0.486838,0.220413,0.251425,0.212024,0.591297,-0.299537,0.153564,-0.114737,0.331465,0.013228,0.394936,0.332345,-0.199613,-0.059517,0.199947,0.433234,0.466458,0.413785,-0.554927,-0.162041,0.331034,0.455341,-0.203763,-0.064328,0.069339,0.299746,-0.067601,0.385752,-0.240170,-0.433658,-0.031049,0.133960,-0.207578,-0.467489,-0.090010,0.140556,0.005402,-0.537684,0.280018,-0.123451,0.039995,-0.181910,-0.116973,0.355819,0.231920,0.509668,-0.027034,0.031669,-0.002366,-0.749738,0.178979,0.844358,0.239792,-0.220166,0.404531,-0.068553,-0.635623,-0.230104,-0.447299,-0.273716,0.257456,0.381134,-0.325167,-0.045914,0.021189,-0.280959,-0.203275,-0.001324,-0.129658,-0.057206,-0.416992,-0.202251,-0.259278,-0.058748,-0.554100,-0.103038,0.089045,0.070437,-0.386207,0.588522,-0.774700,0.134121,0.209056,0.086307,-0.577309,0.667961,-0.033111,-0.222345,-0.017351,0.121608,0.012394,0.431126,0.180927,0.573301,0.355682,0.044818,-0.128691,0.052447,0.597379', '1308755', '1296370', '25721544', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1420080', '悲惨世界', '剧情', '十九世纪的巴黎，贫困的冉•阿让（Jean Gabin）因为偷一块面包被判处十九年的苦役。出狱后，走投无路的他被好心的主教（René Fleur）收留过夜，可是他却偷走了主教的银器。警察将他抓获，准备再次将他投入监狱，临危之际，主教的谎言将他拯救，他也得到感化，化名开始了洗心革面的生活。十年过去，冉•阿让通过努力成为成功的商人并当上市长，得知妓女芳汀的悲惨遭遇后，他担负起照顾其私生女儿柯赛特的责任。他没想到的是，多年后会重遇以前缉拿过他的警长沙威（Bernard Blier），对方不信他已改邪归正，一心要找他的麻烦，只因证据不足迟迟没能得手，然而，他的好运没能持续到八年之后。©豆瓣', '让·迦本', '让-保罗·勒沙努瓦', 8.8, 7883, 'tt0050709', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2164568451.jpg', 0.2, 0.6, 9.2, 38.9, 51.2, '0.190038,0.408597,-0.717490,0.343165,-0.550938,-0.376532,0.461184,-0.071161,-0.446004,-0.237379,0.101487,0.677914,-0.075258,0.358404,0.107580,0.238552,-0.175458,-0.825143,0.081598,-0.151052,-0.320885,-0.321324,-0.272767,-0.116453,-0.380144,-0.221191,0.534276,0.332632,0.065285,0.149083,0.091599,0.149223,0.311692,0.645536,-0.339128,0.239374,0.050928,-0.101858,-0.154025,0.415387,0.383829,-0.529930,-0.069703,0.345449,0.018815,0.523194,0.555059,-0.153906,-0.077668,-0.077081,0.435113,-0.421604,0.057255,0.174079,0.239394,0.044890,-0.101850,0.374362,-0.325660,-0.185446,0.091161,-0.075034,-0.680623,-0.002633,-0.146940,-0.100037,-0.627965,0.366036,-0.347073,0.310852,-0.142935,-0.355627,0.054527,0.371077,-0.027076,0.265978,-0.288663,0.052025,-0.708141,0.528191,0.832359,-0.304564,-0.289339,0.209412,0.052799,-0.412232,0.371403,-0.520516,-0.294318,0.105771,0.387869,0.089578,-0.332252,-0.015042,-0.192609,-0.283998,-0.778891,0.016476,0.015109,-0.316722,-0.187801,-0.150955,-0.133491,-0.093009,-0.311517,0.079210,0.087596,-0.402792,0.296049,-0.767383,0.274270,0.676709,0.375167,-0.610407,0.610608,0.037615,0.024089,0.062163,0.034752,0.223310,0.321709,0.521962,0.540575,0.166812,0.209819,-0.149298,-0.240839,0.263091', '1305386', '1309116', '25908042', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1420088', '精灵宝可梦：超梦的逆袭', '动作', '被人类用基因技术克隆出来的最强宠物小精灵超梦（市村正亲 配音）带着对自我身份的疑惑和对人类强大的愤怒逃离了科研所，它宣布要对制造出自己的人类进行复仇。已经得到了八个勋章的小智（松本梨香 配音），以成为宠物小精灵训练大师为目标而不断的旅行，他带着皮卡丘（大谷育江 配音）和同伴小霞（饭冢雅弓 配音）小刚（上田佑司 配音）刚结束了和训练家的对战，接着收到了一封神秘人的邀请函，邀请他们参加世上最强的小精灵训练家的宴会。地点是新岛宠物小精灵城，这是最强训练家的邀请。他们很痛快的答应了，小智一行人穿过了狂风暴雨的海岸终于到达了新岛。一位叫乔伊的医生带领他们来到了宠物小精灵城，介绍最强的宠物小精灵训练家出场。没想到出现在大家面前的竟然是超梦。超梦的报复究竟是什么呢，一场大战即将开始......©豆瓣', '松本梨香', '汤山邦彦', 8.1, 20362, 'tt0190641', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2171957340.jpg', 0.4, 1.6, 21.3, 44, 32.7, '0.135528,-0.129527,-0.383176,0.716476,-0.194354,-0.088226,0.202042,-0.106079,-0.339528,-0.336993,0.344516,0.893113,-0.176310,0.305062,0.249435,-0.173760,-0.114605,-0.393980,-0.234528,-0.090220,-0.453462,-0.235539,-0.001473,-0.176346,0.237873,-0.331453,0.534724,-0.056488,-0.241920,0.544941,0.355343,0.142142,-0.324256,0.250114,-0.224629,-0.015144,0.346785,-0.016910,-0.165657,0.391687,-0.095842,0.035403,-0.170138,0.256122,0.179140,0.138739,0.862591,-0.484705,-0.002473,-0.269796,0.177227,-0.475398,0.013389,0.043785,0.352418,0.118771,0.157958,-0.001052,0.109373,0.148982,-0.200534,-0.332149,-0.997225,0.077747,-0.060482,-0.041969,-0.416643,0.337279,-0.071962,-0.040374,0.590375,-0.310658,0.242367,0.394183,0.159726,0.496130,-0.234585,0.034508,-0.382875,0.117949,0.504981,-0.357792,-0.111479,0.200785,-0.037449,-0.783096,-0.004460,-0.300045,-0.233891,0.015639,0.167863,0.317104,-0.237953,-0.045485,-0.867273,-0.183288,-0.184124,-0.397000,0.264128,-0.680654,-0.110944,-0.944056,0.096714,-0.263360,-0.228452,0.180066,0.081822,-0.130941,0.917368,-1.269042,0.124852,0.559413,0.325603,-0.478828,0.394691,-0.218831,-0.097763,-0.406263,0.151657,-0.179772,0.310281,0.409060,0.366598,0.462156,0.177849,-0.011810,-0.520368,0.521750', '3044878', '4127270', '1793491', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421275', '地狱解剖', '剧情', '昏暗迷离的某同志酒吧，一个美丽性感却面带忧愁的女子（Amira Casar 饰）在厕所割腕自杀，但随后便被一个男同性恋（Rocco Siffredi 饰）救下。经过一番交谈，女人和男人之间达成一笔交易，女人付费，男人则陪她度过四个夜晚。在这短短的四天里，男人和女人就两性关系展开了针锋相对且危险诡秘的对话。他们最终的结局将会如何？本片荣获2004年费城电影节最佳影片奖。©豆瓣', '洛可·希佛帝', '凯瑟琳·布雷亚', 6.4, 15867, 'tt0348529', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2313578412.jpg', 3.6, 14.9, 49.3, 22.9, 9.2, '-0.066604,0.103030,-0.433363,0.453069,-0.101180,-0.174163,0.971853,0.076266,-0.190135,0.052966,0.477403,0.554548,-0.585057,0.096229,0.458609,-0.067654,-0.409610,-0.773039,-0.153346,-0.388682,-0.203306,-0.249403,-0.237309,-0.289120,0.272918,-0.153578,0.757446,0.173118,0.171234,0.456579,0.481833,-0.206044,-0.626299,0.553469,-0.073170,-0.176986,0.284179,0.297027,-0.370705,0.457378,0.039347,-0.346974,-0.248796,-0.255967,-0.143403,0.253334,0.839685,-0.241233,-0.230355,0.040455,0.225441,-0.072968,-0.381281,0.066588,0.183527,-0.306919,0.559163,0.362930,-0.278527,-0.215802,-0.013234,-0.054955,-0.302638,0.464501,0.117915,0.031087,-0.251727,0.510032,0.085030,0.070425,0.076616,-0.061402,0.007105,0.172309,0.586240,0.420157,0.047368,0.269951,-0.322068,0.144748,0.349323,0.157029,-0.183815,0.416529,-0.288863,-0.441978,-0.110178,-0.064794,-0.326104,-0.062510,0.275902,-0.329652,-0.026937,-0.113150,-0.718825,0.092780,-0.080225,0.044298,0.044769,-0.465875,-0.299023,-0.501306,-0.042768,-0.166166,-0.419826,0.426460,0.229715,0.045089,0.568286,-0.565566,0.149153,0.530772,0.387751,-0.321493,0.897177,0.222762,0.232553,-0.425123,-0.057731,0.238671,-0.143199,-0.148968,0.054703,0.533527,-0.490889,0.466346,-0.525069,0.359977', '1467779', '10466639', '1417036', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421278', '面子', '剧情', '年轻医生Wil（杨雅慧 饰）是个美国华裔。她事业如意，工作干炼，但就是不爱打扮，不喜欢结交男朋友，这令到母亲（陈冲 饰）非常操心。母亲刻意拉女儿到一些华人圈子的聚会，帮女儿物色对象，却总是一无所获。不料母亲的生活也开始混乱——她怀上了孩子，却不愿公开谁是孩子父亲。为了面子问题，Wil的外公外婆把母亲赶出家门，责令她一定要找个人嫁出去。于是，妈妈投奔到女儿的门下，暂时寄宿在此，女儿开始四处网罗男人相亲。除了母亲的事情让Wil烦恼，她还有一个秘密需要苦心遮掩——自己女同的身份恐怕会让思想传统的母亲接受不了，于是，Wil和女朋友开始转战地下，二人爱得偷偷摸摸。人人为了面子，都有一个自己的心结，不知何时打开。©豆瓣', '杨雅慧', '伍思薇', 8.8, 69561, 'tt0384504', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2047680236.jpg', 0.1, 0.6, 9.5, 39.4, 50.3, '-0.072891,-0.054329,-0.658338,0.332869,-0.686012,-0.236212,0.218841,0.071053,-0.674777,-0.417124,0.003015,0.601288,0.346632,0.474519,0.087511,0.222189,-0.215065,-0.498099,0.432088,-0.102366,-0.228839,-0.314265,-0.040539,-0.491521,-0.230846,-0.159432,0.450996,-0.101497,0.020012,-0.116417,0.320775,0.233361,-0.080757,0.442206,-0.299172,-0.009273,-0.187712,0.211073,-0.340097,0.142133,0.166765,-0.056920,-0.223517,0.298591,0.142840,0.404248,0.455283,0.196832,-0.150502,-0.101625,0.345444,-0.127260,0.007554,0.192609,0.179478,-0.213088,0.522523,0.293585,-0.151853,-0.014956,-0.004936,-0.154807,-0.286871,0.152331,0.341057,-0.037628,-0.761661,0.150312,-0.287299,-0.232928,-0.022712,-0.595861,0.120777,0.306010,-0.014340,0.418033,-0.327795,0.262494,-0.432775,0.231108,0.762291,-0.006536,0.366072,0.355851,-0.184267,0.037775,0.326843,-0.504664,-0.685835,0.139275,-0.010851,-0.079018,-0.201552,0.137595,-0.127275,-0.165335,-0.175201,-0.006336,0.336947,-0.713048,0.151292,0.292559,-0.054045,-0.061436,-0.317241,-0.099858,0.051764,-0.225258,0.773852,-0.740213,0.111294,0.655352,0.356758,-1.238782,0.696547,0.385839,0.259793,-0.571191,0.063394,-0.076366,-0.037673,0.051422,-0.104367,-0.048746,0.170383,-0.302654,-0.265954,0.089532', '1877596', '1428876', '24879820', '1305915');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421309', '双姝奇缘', '剧情', '影片分成四个小片段，讲述了持有不同价值观和生活方式的两个女孩的友情。单纯、热情的蕾妮特（若埃勒·米凯尔 Joëlle Miquel 饰）是一个乡下女孩，慵懒、阴暗的米拉贝（杰西卡·福德 Jessica Forde 饰）则来自巴黎城里。第一段故事名为“蓝色时光”，讲述了她 们的相遇。米拉贝骑车去乡下游玩，结果自行车坏了，乡下姑娘蕾妮特帮她修好了自行车。两个女孩互相产生好感，交谈甚欢，决定一起去巴黎上大学。第二段故事发生在一个咖啡馆中。蕾妮特被侍应误认为女骗子，对她处处刁难，米拉贝到来之后帮她解围，两人对待此事有着截然不同的解决办法。第三段故事中，她们对社会边缘人乞丐、小偷、骗子进行了不同观点的讨论。最后一段故事中，她们打了一个赌：蕾妮特能否坚持一天不说话。结果，蕾妮特假装成哑巴少女，米拉贝成功地将她的画卖给一个艺术品经销商。©豆瓣', 'Joëlle Miquel', '埃里克·侯麦', 8.7, 20664, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1602411185.jpg', 0.2, 0.5, 8.8, 47.2, 43.3, '0.579656,0.106759,-0.386985,0.636905,0.181561,-0.159577,0.749022,0.045927,-0.150269,-0.174597,-0.167903,0.280771,-0.532069,0.160954,0.428103,0.036920,-0.781981,-0.646910,0.297348,-0.358955,-0.245509,-0.438678,0.161469,-0.257648,-0.149814,-0.031720,0.015155,-0.271033,-0.055330,0.368889,0.287725,0.471837,-0.274421,0.221338,0.176649,-0.010502,0.263318,-0.169417,-0.064895,0.229343,-0.154841,0.123042,0.089242,0.104073,0.233503,0.302437,1.029766,-0.378228,0.142312,-0.235964,0.157614,0.112141,0.009170,-0.204883,0.093129,-0.303909,0.432080,-0.164708,0.146257,-0.192378,0.214068,-0.491858,-0.122975,-0.130816,-0.169051,0.193256,-0.512796,-0.047906,0.333291,0.142188,0.033539,-0.312078,0.152303,0.217758,0.529657,0.394665,0.205064,-0.092890,-0.473716,0.156863,0.666840,0.171835,-0.010962,0.474407,-0.672938,-0.182585,0.097883,0.063699,-0.532787,0.005530,0.403786,-0.420650,0.026752,0.077535,-0.600840,-0.280803,-0.209257,0.239695,-0.067055,-0.697942,0.112525,-0.697667,-0.038867,-0.385545,-0.395945,-0.071277,-0.142525,-0.216365,0.712835,-0.585525,0.139900,0.452972,0.469975,-0.135643,0.512219,0.167015,0.221423,-0.519928,-0.007655,0.325698,-0.049889,-0.292082,-0.010858,0.346590,0.016500,0.242467,-0.390232,0.449813', '5403927', '3041753', '4706257', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421480', '龙凤茶楼', '剧情', '阿龙（莫少聪 饰）服刑四年终于出狱，由于对江湖生活心生倦意，阿龙选择龙凤茶楼栖身，但好兄弟垃圾池（周星驰 饰）很快拜访，又让他开始游走在帮派的边缘。为帮垃圾池的舞女情人出头，阿龙邂逅了舞小姐凤（陈雅伦 饰）和June（陈加玲 饰），凤出污泥而不染的气质令阿龙着迷，自此用心追求，不惜付出鲜血代价，终于以诚心抱得美人归。同时，越来越功利化的帮派不再以义气为先，阿龙为保老大坚叔（吴孟达 饰）受伤，却只落得被其他大佬埋怨，不得不以道歉收场，所幸身边还有垃圾池的支持，虽然此人口不择言，总惹凤气闷……阿龙与凤之间的隔阂分歧不仅此而已，这对儿终于走到一起的情侣，还要面临太多的考验……©豆瓣', '周星驰', '潘文杰', 6.7, 11706, 'tt0100045', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2602190660.jpg', 1.5, 9, 53.4, 23.8, 12.3, '0.052672,0.031040,-0.251527,0.204003,0.299944,-0.624280,0.486744,0.187571,-0.431857,-0.072323,0.064220,0.375602,-0.197520,0.298556,-0.009088,-0.260389,-0.188434,-0.581794,-0.224984,0.052919,-0.168861,-0.328327,0.125943,-0.267540,-0.542795,0.026566,0.589905,0.197682,-0.045377,0.479236,0.570880,0.086311,-0.140779,0.413494,-0.355489,-0.274554,-0.187532,0.297517,-0.529401,-0.102870,0.131263,-0.352789,-0.104100,0.000873,0.060358,0.199634,0.537939,-0.167795,-0.172506,-0.194372,0.293650,-0.227547,0.087483,-0.127975,0.197582,-0.087856,0.437589,0.178870,-0.031052,0.038832,0.003374,-0.347766,-0.552602,0.017929,0.486762,0.003471,-0.548828,0.320621,-0.068147,-0.172558,0.249495,0.044525,0.040481,0.280079,0.307442,0.102297,-0.566694,-0.031768,-0.320340,-0.078879,0.717026,0.082962,0.221477,0.222669,-0.049927,-0.384873,0.211401,-0.279650,-0.041376,-0.076315,0.028540,0.025608,0.277931,0.124765,-0.521038,-0.183925,-0.182148,0.217677,-0.054332,-0.622938,0.348104,-0.296294,-0.406230,-0.277032,0.011863,0.291875,0.272810,-0.257702,0.507008,-0.710106,-0.033833,0.165503,0.425610,-0.666542,0.472166,0.078871,0.024262,-0.389579,-0.238136,0.415079,-0.241996,-0.045746,0.010015,0.134914,-0.080933,-0.026518,-0.146522,0.088572', '30345227', '1293265', '1949320', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421548', '希特勒：恶魔的崛起', '剧情', '1889年，希特勒出生于奥地利布劳瑙镇一个公务员家庭。青年时期处于第一次世界大战的阿道夫·希特勒，在动荡不安的乱世中，他的出现与崛起是希望的开端、还是灾难的开始？这个看似平凡的小男孩，长大后却指挥了德国军队大规模入侵各国，掀起了惨烈的第二次世界大战。', '罗伯特·卡莱尔', '克里斯丁·杜瓦', 7.5, 8636, 'tt0346293', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1426186373.jpg', 1.9, 5.1, 29.4, 41.6, 21.9, '0.229102,0.379665,-0.822989,0.635406,0.051453,-0.098102,0.839982,-0.270830,-0.689573,-0.224224,0.329573,0.879674,-0.087899,0.281381,0.408586,-0.071818,-0.353765,-0.884598,-0.335334,0.255625,-0.154414,0.066670,-0.662100,-0.182226,-0.339278,-0.347156,1.058553,0.539569,-0.454286,0.380485,0.034651,0.411801,0.147144,0.452201,-0.262800,-0.261780,-0.106035,-0.139357,-0.600597,0.161537,-0.220172,-0.548528,-0.320550,0.277692,-0.270197,0.420637,0.580237,-0.465414,0.126648,-0.212813,0.832126,-0.439348,-0.760343,0.196834,0.510533,0.137935,-0.175705,-0.003541,0.167229,-0.094899,-0.427636,-0.335292,-0.495699,-0.106958,-0.192588,0.480927,-0.496302,0.932309,0.027796,0.022968,-0.003700,-0.240690,0.060795,1.066414,0.179674,0.707466,-0.277159,0.330486,-0.587735,0.125094,0.859900,-0.111656,-1.109728,0.036442,-0.425929,-0.719757,-0.044100,-0.644433,-0.498907,-0.164593,0.253469,-0.545369,-0.229955,0.879460,-0.793135,0.248855,-0.401243,-0.496195,0.258400,0.117208,-0.601989,-0.389834,-0.258316,-0.631371,-0.747868,0.251863,-0.079941,-0.158914,0.994850,-1.003137,0.128363,0.554380,0.248623,-0.199770,0.506645,0.203423,0.295094,-0.163898,-0.010809,0.487372,-0.402549,0.091584,-0.316773,0.290575,-0.193310,-0.252680,0.048214,0.457104', '27040921', '25721544', '26615753', '1849026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421570', '有你我不怕', '剧情', '九岁的小男孩米歇尔（乔瑟培·克里斯提亚诺 Giuseppe Cristiano饰）一日在玩耍的时候，无意间发现了地穴里的一个秘密。他惊讶的发现在这口地穴中囚禁着一个与他年纪相仿的金发男孩菲利普（马悌亚·狄·皮耶 Mattia Di Pierro饰），他被铁铐牢牢地锁着，弱小而无助。被震惊了的米歇尔立刻逃回家中，然而在好奇心的驱使下，他又一次前往地穴。他们都是用童话与想像化解着内心的恐惧，慢慢变成了好朋友。米歇尔隐瞒了这个秘密，并在心里做了各种各样的奇异猜想。一天晚上，米歇尔的家中住进了一位面目可憎的男人。在谈话中，米歇尔听到了一个惊人的秘密。菲利普其实是全村的大人们一同绑架来的，其中也包括自己的父母，米歇尔陷入了巨大的迷惑与恐惧之中。©豆瓣', 'Giuseppe Cristiano', '加布里埃莱·萨尔瓦托雷斯', 8.2, 8308, 'tt0326977', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2565039399.jpg', 0.3, 1.4, 17.7, 51.3, 29.3, '0.477761,0.210678,-1.039537,0.605479,-0.330615,-0.137069,1.232435,-0.079611,-0.511175,-0.288204,0.099366,0.823756,-0.354117,0.639932,0.138783,0.189659,-0.186396,-0.701894,-0.246752,-0.308937,-0.357675,-0.553085,-0.446208,-0.291572,0.095828,-0.272970,0.327439,0.207240,-0.138017,0.484350,0.416914,0.190830,-0.141919,0.717094,-0.272524,0.101517,0.198271,-0.185058,0.303219,0.157857,-0.062087,-0.354630,-0.169972,0.448820,-0.153951,0.560883,0.641132,-0.506117,-0.241231,0.059276,0.095024,-0.112478,-0.163835,0.213946,0.356271,0.037495,0.034231,-0.031568,-0.411395,0.205630,0.201680,0.030220,-0.743584,0.072194,0.064626,0.253377,-0.823486,0.546761,0.162670,-0.126942,0.226834,-0.295832,0.249043,0.040271,0.071786,0.538103,-0.181032,-0.031415,-0.563958,-0.002922,0.574778,-0.155984,-0.198554,0.127580,-0.255048,-0.322534,-0.076133,-0.011398,-0.575504,-0.169434,0.546160,0.222237,-0.508538,0.298794,-0.450073,0.035798,-0.286180,-0.054841,-0.422267,-0.522891,-0.194179,-0.401092,-0.226316,-0.384045,-0.396871,0.071260,-0.002751,-0.288291,0.695861,-0.692218,0.353954,0.572970,0.174157,-0.213893,0.637768,0.006884,0.192007,0.110355,-0.101671,0.208436,0.068256,0.144888,0.295219,0.616140,-0.121284,0.014121,-0.569978,0.669728', '21619567', '3111650', '1292211', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421673', '太太万岁', '喜剧', '秀外慧中的好媳妇陈思珍（蒋天流饰）自与丈夫唐志远（张伐饰）结婚后，便把家里的人际关系处理得很好，持家有道。一日，思珍的弟弟陈思瑞（韩非饰）从台湾到上海省亲，邂逅志远的妹妹唐志琴（汪漪饰），两人一见钟情。然而因为陈父（石挥饰）不肯资助自己筹办公司的志远，却极力反对这桩亲事。思珍只得谎称唐家存有金条美钞，陈父才同意资助志远办起公司。不料发迹致富的志远却有了外遇，与姨太太（上官云珠饰）有染。思珍为了顾全丈夫名誉，只得委曲求全。未几，志远破产，谎言败露，两家人也因此闹翻。终于，思珍决定与志远离婚，却在律师事务遇见了秘密登记结婚的思瑞、志琴两人。面对真心相爱的一对有情人，思珍该何去何从。由中国著名导演桑弧执导于1947年摄制的黑白影片《太太万岁》是小说家张爱玲的电影经典剧作。桑弧含蓄细腻的电影风格与张爱玲的剧作交相辉映。©豆瓣', '蒋天流', '桑弧', 8.4, 14472, 'tt0477890', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2593519474.jpg', 0.1, 0.6, 11, 54.4, 33.8, '0.160782,-0.228061,-0.594706,0.226840,0.111588,-0.632344,0.254012,0.424278,-0.417616,-0.200080,0.410457,0.795897,-0.133734,0.110839,0.116116,0.091315,-0.231858,-0.554982,0.356920,-0.008547,0.350479,-0.542812,0.246044,0.085619,-0.174240,0.194557,0.464910,-0.067698,0.027738,0.291106,0.213152,0.128487,-0.041742,0.088070,-0.013684,0.186838,-0.111769,0.168824,-0.904856,-0.033540,0.262227,0.009471,-0.240933,-0.084144,0.044981,0.277348,0.313394,-0.001823,-0.171235,0.072257,0.524713,-0.249892,-0.007123,0.116301,0.261525,0.227450,0.411726,0.671410,-0.491850,-0.196374,0.044787,0.032692,-0.351221,0.260858,0.404334,0.084756,-0.469028,0.276435,-0.138787,-0.139402,-0.060962,-0.475807,0.213873,0.388884,0.079470,0.277907,-0.371967,0.355821,-0.378852,0.460826,0.540560,0.191158,0.105182,0.216747,0.014045,-0.175691,0.240835,-0.245209,-0.621002,0.077953,0.135796,-0.093144,0.000462,0.206742,-0.333538,-0.133725,-0.278580,0.274825,0.395668,-0.452288,0.060942,-0.265296,-0.381568,-0.392764,-0.486567,-0.143690,0.380577,-0.058296,0.570986,-0.682897,-0.067731,0.056440,0.401076,-0.715164,0.588420,0.194099,0.207382,-0.263880,0.130324,-0.124889,-0.257048,-0.038505,-0.029585,0.023196,0.230366,-0.321393,0.014647,-0.028122', '1306133', '1299624', '1308035', '6890343');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421733', '伊豆的舞女', '剧情', '本片改编自川端康成著名小说《伊豆的舞女》。即将就读东京某高等学校的川岛（三浦友和）趁开学前的暑假前往伊豆旅行，在乍晴乍雨的山道上，他遇到一群巡回卖艺的歌舞伎艺人，因被其中一个梳着古代发髻、背着大鼓的娇小玲珑舞娘吸引，他决定与他们一起上路，路上，他得知该舞娘叫熏（山口百惠）。川岛不计歌舞伎艺人地位卑微，常邀请他们到他住的旅馆玩耍，而在和熏有过单独相处后，他更被其纯洁无瑕的美震撼，陷入矛盾中，一面为自己难以抑制的冲动而苦恼，一面为她在表演时可能受到侮辱惴惴不安。熏在两人的交往中，也渐渐生出真情。可是两人也只能是彼此生命中的过客。©豆瓣', '山口百惠', '西河克己', 8.6, 23876, 'tt0391249', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p939020358.jpg', 0.1, 0.6, 10.4, 45.9, 43, '0.384524,0.021359,-0.788787,0.502844,0.113848,-0.201599,0.788626,0.163414,-0.383748,-0.167215,0.290523,0.685268,-0.459074,0.401977,0.355239,-0.037080,-0.209396,-0.763937,-0.077401,-0.130458,-0.102603,0.062366,0.015955,-0.065443,-0.300659,-0.158571,0.663625,0.065099,-0.198257,0.682243,0.359554,0.360315,-0.421974,0.428266,-0.203084,0.047381,0.108460,0.108926,-0.113958,0.155328,-0.027919,-0.339494,-0.194722,0.139033,0.002370,0.258481,0.731911,-0.222220,-0.281215,-0.053548,0.256248,-0.161047,-0.061689,0.276868,0.262062,-0.072647,0.305071,-0.212970,-0.276853,0.311055,-0.004628,0.114551,-0.348077,0.137800,0.248914,0.163529,-0.517119,0.514879,0.242183,-0.222185,0.259218,-0.191152,0.080105,0.025756,0.256525,0.264718,-0.050832,-0.045246,-0.383005,0.416031,0.917718,0.091170,-0.011968,0.297358,-0.454689,-0.215182,0.209462,-0.334431,-0.351375,-0.099059,0.118820,-0.013002,-0.208825,0.047996,-0.477363,-0.053407,-0.107695,-0.060816,-0.085297,-0.399996,-0.047529,-0.589946,-0.140344,-0.635171,-0.276311,0.158507,0.186725,-0.269986,0.682713,-0.849017,0.171619,0.722862,0.289049,-0.345368,0.663717,0.177473,0.044936,0.210512,-0.073438,0.245481,-0.123274,0.132833,0.071780,0.513311,-0.372998,0.194103,-0.527870,0.287822', '35030151', '26687241', '3811356', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421734', '麻辣教师电影版', '剧情', '麻辣教师鬼冢英吉（反町隆史 饰）受邀来到北海道的一个美丽古朴的小镇——幌比内，在北文馆学苑2年C组担当为期三周的代课老师。时间虽短，却问题多多。首先是两个自杀倾向的学生，害羞内向的市川乐（笠原秀辛 饰）单恋同班同学桂木绫乃（田中丽奈 饰）不成，希望一死了之；绫乃因其富家女身份而受到孤立，倍感绝望。鬼冢以其独特的教育方式，化解了一个又一个难题。另一方面，女记者喜多岛薰（藤原纪香 饰）错将鬼冢当作通缉犯，时刻跟踪侦查，令鬼冢又气又无奈。短短的三周转瞬即逝，一切重新归于平静，又与当初有着些许不同……©豆瓣', '反町隆史', '铃木雅之', 7.5, 7338, 'tt0315870', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1740406621.jpg', 0.8, 4.8, 34, 40.7, 19.7, '-0.113802,0.004751,-0.159053,0.438995,-0.002235,-0.075128,0.542072,0.215053,-0.358494,-0.465069,0.098220,0.322881,-0.300018,0.252145,0.184751,-0.158764,-0.114496,-0.489960,-0.046454,-0.461449,-0.017735,-0.176950,-0.094156,0.023172,-0.230974,-0.290264,0.824507,0.027060,0.010756,0.445205,0.400588,0.524685,-0.234280,0.239369,0.083828,-0.161037,-0.071599,0.040494,-0.009872,0.054688,-0.269428,-0.153099,-0.305648,0.292307,-0.055582,0.502420,0.911291,-0.028509,-0.384735,-0.140085,0.524208,-0.105123,-0.266727,-0.021776,0.527597,-0.096506,0.112736,0.173206,-0.469391,0.034244,0.195012,-0.066522,-0.476737,0.020477,0.339290,0.005986,-0.190443,0.437050,-0.003343,-0.333012,0.128559,-0.223413,-0.248992,0.225725,0.459130,0.400156,-0.223482,0.181635,0.186414,0.093711,0.549320,-0.023577,-0.284463,0.273333,-0.123134,-0.353643,0.015354,-0.185542,-0.132116,-0.102513,0.022118,0.043415,0.125109,0.138853,-0.446735,-0.058606,-0.290900,0.137904,0.054572,-0.477765,0.079085,-0.510450,0.216725,-0.136641,-0.131098,0.153282,0.258273,-0.019144,0.666602,-0.723188,0.081696,0.437734,-0.114541,-0.425295,0.307100,0.338464,-0.071761,-0.331856,-0.140688,0.200940,0.182477,0.146540,-0.040604,0.448412,-0.026211,-0.144762,-0.257338,0.103632', '10174444', '5403927', '26759820', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421807', '死亡论文', '悬疑', '女大学生安吉拉（安娜·托伦特 Ana Torrent 饰）正在撰写一篇关于视听暴力的论文，她的教授在为她收集资料的时候心脏病突发死亡。安吉拉觉得事有蹊跷，偷偷从案发现场拿走了教授死亡前正在看的一卷录像带。切玛（费雷·马丁内兹 Fele Martínez 饰）对暴力录像研究颇深，安吉拉带着录像带向他求助。他告诉安吉拉，其中录制的惨绝人寰的暴力行径为真实拍摄，并且受害者很可能就是他们失踪已久的校友凡妮莎。为了得到真相，安吉拉和切玛四处奔波渐渐产生了感情。他们找到了凡妮莎的男友博斯克（爱德华多·诺列加 Eduardo Noriega 饰），没想到博斯克却把矛头指向了切玛。夹在两个男人之间的安吉拉究竟应该相信谁？一个小小的细节暴露了全部真相，当恶魔展现出他的真正面目，“天使”安吉拉还能够幸免于难吗？©豆瓣', '安娜·托伦特', '亚历杭德罗·阿梅纳瓦尔', 7.4, 10882, 'tt0117883', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203874111.jpg', 0.9, 4.1, 32.5, 47.2, 15.4, '0.247592,-0.056238,-0.340818,0.313482,-0.184948,-0.064228,0.614576,-0.239357,-0.400215,-0.267278,0.330762,0.647575,-0.160442,0.055219,0.217488,0.030503,-0.589353,-0.748126,0.018239,-0.090625,-0.388686,-0.560780,-0.232527,-0.132098,0.190619,-0.312045,0.355424,-0.293212,-0.153285,0.078082,0.315998,0.309738,-0.160519,0.143966,0.085298,0.111391,0.140522,-0.118350,-0.184309,0.112971,0.366905,-0.125511,-0.181435,0.311728,-0.099631,0.258937,0.637318,-0.238931,-0.116861,0.010586,0.406704,-0.147415,0.162081,0.210278,0.028386,0.137118,0.154704,0.148252,-0.239473,-0.081550,0.102550,0.212150,-0.720907,0.060401,0.008827,0.392855,-0.181964,0.163495,-0.342401,0.061854,0.488291,-0.408794,-0.036332,0.409709,0.417224,0.199734,-0.116395,-0.249576,-0.342518,0.035393,0.160604,-0.073182,-0.036526,0.412213,-0.279101,-0.331349,-0.109889,0.211761,-0.411553,0.199487,0.494389,0.128139,-0.088277,0.465113,-0.514127,-0.309616,-0.172488,-0.161949,0.124404,-0.427793,-0.286584,-0.457459,-0.300444,-0.003300,-0.222395,-0.263268,0.050996,-0.370322,0.651793,-0.520603,0.263463,0.522769,0.086307,-0.282554,0.314746,0.108524,-0.187052,-0.229165,-0.291966,0.272124,0.299240,0.332619,0.098985,0.330693,0.300304,-0.501269,-0.405369,0.396155', '25928048', '1308585', '2988294', '24733