INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421809', '最好的时光', '剧情', '该片是侯孝贤对自己电影生涯所作的一次总结。三段故事里男（张震）女（舒淇）主角表达情感的方式及所处时代背景，都能在侯孝贤各个时期的影片里找到对应。《恋爱梦》纯净，似不可抵达的梦的彼岸；《自由梦》感人，却是接近天国的更遥远的梦境；《青春梦》冰冷，却是现实。冒失说出侯孝贤眼中“最好的时光（或最好的电影时光）”是哪一段并无太大意义，因为所有的时光都是被辜负被浪费的，也只有在辜负浪费之后，才能从记忆里将某一段拎出，拍拍上面沉积的灰尘，感叹它是最好的时光。©豆瓣', '舒淇', '侯孝贤', 7.6, 94568, 'tt0459666', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p478164460.jpg', 0.5, 2.8, 30.2, 47.8, 18.7, '0.009559,0.305711,-0.357469,0.643293,0.155602,-0.270783,1.037760,-0.295441,-0.524921,-0.159982,0.017508,0.386786,-0.092008,0.165010,0.095683,-0.067507,-0.254857,-0.781504,-0.246952,-0.268392,-0.118711,-0.391043,-0.296517,0.281589,-0.200985,-0.347033,0.874556,0.256554,-0.554146,-0.028735,0.281977,0.132085,-0.165280,0.139891,-0.317649,-0.152466,-0.382340,0.430572,-0.590470,0.027475,-0.015298,-0.148243,-0.088978,0.148265,-0.189994,0.082018,0.783950,-0.375699,-0.331840,0.447283,0.655100,-0.384132,-0.251513,-0.092579,-0.219870,0.099074,0.333583,0.276182,-0.030634,0.120397,-0.183237,-0.178394,-1.162556,-0.285038,0.085571,0.234196,-0.331619,0.649590,0.351924,-0.301148,0.497478,-0.230061,0.327638,-0.142516,0.780056,0.550940,-0.263718,-0.166567,-0.135733,0.629004,0.576640,-0.013240,-0.417363,0.939504,-0.392090,-0.488264,-0.219416,-0.085556,-0.348194,0.336120,0.035180,0.155868,-0.322889,0.554251,-0.537976,0.227915,-0.062335,-0.331674,0.139004,-0.541563,-0.173562,-0.389077,-0.073094,-0.477406,-0.456204,-0.167294,0.218313,-0.444817,0.798190,-0.524950,0.365296,0.539109,-0.118010,-0.025269,0.831827,0.246919,0.013931,-0.201619,0.346919,0.572106,-0.054011,0.206558,-0.222701,0.197060,-0.270358,0.046682,-0.820802,0.652978', '6844861', '35360296', '1422088', '26315728');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421823', '娜娜', '剧情', '另一个译名是：世上的另一个我。小松奈奈（宫崎葵饰）要去见男朋友，在通往东京的火车上，她遇到了另一个Nana——大崎娜娜（中岛美嘉饰），娜娜希望去东京重组Black Stone乐队。两个nana一见如故，到达了东京有两人再次相遇，并且一同搬进了出租屋707。两人虽然有着同样的名字，却有着迥异的性格，在二人同居的生活期间，她们都受到了感情的创伤，她们在扶持中更加了解彼此，感情也越来越深，一路鼓励对方寻找自己的理想。©豆瓣', '中岛美嘉', '大谷健太郎', 7.8, 123795, 'tt0471834', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2256750022.jpg', 0.5, 3.1, 26.7, 44.4, 25.2, '0.483330,-0.086440,-0.744096,0.653834,-0.081338,-0.388197,0.787265,0.214910,-0.469641,-0.112804,0.273047,0.819886,0.032938,0.245313,-0.076642,-0.166979,-0.324167,-0.545838,0.185411,-0.351650,-0.395586,-0.544383,-0.151388,0.064047,-0.186426,0.042984,0.535041,-0.046435,-0.128847,0.572664,0.240603,0.015046,-0.412985,0.681825,-0.289164,0.168890,0.130043,0.149748,-0.370142,0.344940,-0.075347,0.045002,0.008148,0.092341,-0.120206,0.402065,0.615368,0.077757,-0.246527,0.072696,0.285394,0.143090,-0.180685,0.106867,0.377321,-0.064061,0.239270,0.212110,-0.390407,-0.005902,-0.143800,0.032642,-0.553951,0.202432,0.191419,0.296663,-0.543117,0.653068,0.250346,-0.455101,0.308014,-0.427394,0.079876,0.524986,0.249391,0.314509,-0.361221,0.120786,-0.338180,-0.297636,1.104724,0.145651,-0.040279,0.317483,-0.371282,-0.408271,-0.080356,0.110509,-0.344741,-0.072694,0.180809,0.027045,-0.171140,0.016546,-0.790149,0.332536,-0.001202,0.065046,0.101059,-0.523199,0.257139,-0.823327,-0.146445,-0.713104,-0.408830,0.127662,0.019859,-0.321521,0.837805,-0.963804,0.098676,0.512474,0.438402,-0.621302,0.802923,0.370085,0.027509,-0.242016,0.211187,0.465301,-0.166962,0.282004,-0.035505,0.463122,-0.103714,0.281351,-0.693351,0.468989', '25721544', '1292219', '3055049', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421884', '兽兵卫忍风帖', '动作', '在一个风雨交加的晚上，一伙神秘的人策马狂奔向下田村的方向，之后这个村子就爆发了一场瘟疫，所有的村民都死了。在望月番番主的首肯下，甲贺组众忍者前往该村调查，不料路上遇到一个刀枪不入的彪形大汉的袭击，只有忍女阳炎（筱原惠美 配音）在一个男子的帮助下虎口逃生。帮助阳炎的这个人 就是牙神兽兵卫（山寺宏一 配音）， 不久之后他中了那个大汉的埋伏，两人一场血斗，最后兽兵卫险胜。这时一个自称是将军手下公义的小老头浊庵（青野武 配音）出现在兽兵卫面前，原来被杀死的大汉是鬼门八人众之一，将军对头的手下，浊庵等公义一直在跟踪他们，但其他公义都被杀了，只有浊庵一直跟踪到这里。浊庵的连哄带骗加诡计，以一百两雇兽兵卫协助他掉查此事，而且据他说鬼门八人众的头是已经被兽兵卫亲手杀死的冰室弦马（乡里大辅 配音），难道死人还能复活？在与鬼门八人众的交手中，阳炎再次出现并且救了兽兵卫，但她说这只是为了报恩。真的是这样吗……', '山寺宏一', '川尻善昭', 8.7, 16199, 'tt0107692', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456518164.jpg', 0.2, 0.7, 10, 42.6, 46.5, '0.309496,-0.161044,-0.462430,0.422073,-0.322341,-0.112846,0.706836,-0.147973,-0.511712,-0.303888,0.465329,0.596877,-0.025863,0.125330,0.232140,-0.110086,0.006173,-0.577802,-0.377085,-0.143266,-0.465689,-0.175842,0.006428,-0.204393,-0.122827,-0.123356,0.534868,0.358634,-0.032876,0.353502,0.374261,0.189765,-0.200627,0.451782,-0.357824,0.304300,0.081120,-0.308366,0.326727,0.481740,-0.076984,-0.448949,-0.159423,0.295795,-0.061460,0.491796,0.529472,-0.313869,-0.082717,-0.057967,-0.100629,-0.450162,0.004730,0.165620,0.580661,-0.150548,0.213126,0.112924,-0.005342,-0.081949,-0.142849,0.104150,-0.807389,-0.036716,0.113059,0.027586,-0.677486,0.251604,0.095445,-0.007308,0.062100,0.030860,0.372576,0.454617,0.251724,0.048923,-0.202295,-0.148518,-0.777943,0.157513,0.748194,-0.156393,-0.049883,-0.103681,0.244640,-0.550387,-0.049095,-0.168443,-0.100642,-0.009380,0.304879,-0.098346,-0.104199,-0.306927,-0.378462,0.020008,-0.219584,0.100592,-0.264488,-0.302276,-0.207104,-0.316072,0.010655,-0.275667,-0.039538,0.419553,0.129012,-0.128912,0.419522,-0.763431,0.030350,0.446840,0.415538,-0.340869,0.559024,0.022653,-0.056458,0.068113,0.025136,-0.146166,0.430502,0.431235,0.440043,0.398307,0.019307,-0.223711,-0.417058,0.108305', '1793491', '1292584', '25721544', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1421976', '宛如天堂', '喜剧', '单身男子大卫（马克·鲁弗洛 Mark Ruffalo饰）为了忘掉伤心事，决定出租自己的公寓。怪事开始发生：一个叫伊丽莎白（瑞茜·威瑟斯彭 Reese Witherspoon饰）的姑娘闯入了大卫的生活，声称这是她的房子。伊丽莎白似乎拥有超乎凡人的能力，她能随时出现在各个处所，纠缠大卫逼他搬走。然而，她却不知道这背后隐藏着一个残酷的事实——其实伊丽莎白只是一具鬼魂。她生前是一个工作狂，在一场车祸中遇难。大卫请来驱鬼人，伊丽莎白渐渐知晓自己的身份。在这个过程中，大卫和伊丽莎白之间产生了人鬼之恋，伊丽莎白生前和大卫一段错过的缘分，伴随着这段无果的恋情显得倍加唏嘘。©豆瓣', '瑞茜·威瑟斯彭', 'Mark Waters', 7.2, 15417, 'tt0425123', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1071843938.jpg', 0.5, 3.7, 43.8, 39.9, 12.1, '0.416761,0.058636,-0.761238,0.516075,-0.351095,-0.032377,1.098985,-0.098524,-0.572817,-0.565458,0.281759,0.769791,-0.273306,0.197669,0.136680,0.099242,-0.422560,-0.439496,0.264070,-0.219617,-0.219943,-0.403496,-0.206995,-0.336748,-0.111479,-0.198646,0.402184,0.046883,-0.148473,0.337544,0.290545,0.483949,-0.004385,0.482293,-0.130081,0.326034,0.168992,0.042502,-0.142640,0.037310,0.054328,-0.199488,-0.117631,0.367785,-0.137606,0.303210,0.421417,-0.282709,-0.135217,0.031920,0.324497,-0.187096,0.060889,0.243145,0.152029,-0.199318,0.178397,0.203868,-0.270336,-0.111724,0.199062,0.057619,-0.701060,0.109058,0.134243,0.346864,-0.428738,0.339278,-0.155592,0.138856,-0.119112,-0.234203,0.089694,0.307364,0.377933,0.199448,-0.023972,-0.119559,-0.839146,0.061597,0.844281,-0.077959,-0.332794,0.431609,-0.334244,-0.355162,-0.350125,0.007341,-0.758523,-0.064742,0.215367,-0.047662,-0.218738,0.398347,-0.373264,-0.048517,-0.162120,0.118378,-0.252903,-0.435907,-0.232041,-0.564648,-0.338496,-0.610721,-0.252810,-0.184243,-0.113929,-0.452597,0.491128,-0.648988,0.150493,0.491710,0.218895,-0.247289,0.688450,0.246081,0.256801,-0.304410,-0.150237,0.359982,0.071693,0.010312,0.263521,0.326099,0.204518,0.135509,-0.513384,0.564930', '4275444', '1296534', '25909236', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422020', '我这一辈子', '剧情', '清朝末年，才二十出头的“我”（石挥 饰）就失业了，多亏邻居巡警赵大爷的帮助，我也当上了一名巡警，也就是人们常说的“臭脚巡”。从这绰号您就知道，这个差事不好干。况且那些年兵荒马乱，民不聊生，清政府、军阀、洋人、爱国青年、国民党……你方唱罢我登场，把个老北京城搅得沸沸扬扬。我曾在秦大人府上当差，官老爷的奢侈腐败算是看了个尽。五四运动时还结识了学生领袖申远，他们为了新中国的崛起而不懈努力。我呢，一个社会底层的小老百姓，只求守着老婆孩子过上几天安稳日子。但处在这个倒霉时代下，老百姓哪有什么安生日子可言啊？本片根据老舍同名原著改编。©豆瓣', '石挥', '石挥', 8.8, 12013, 'tt0043139', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2046265383.jpg', 0.2, 0.6, 8.2, 41.2, 49.8, '0.301511,-0.201427,-0.257168,0.133050,-0.289638,-0.393022,0.225261,-0.025320,-0.508338,-0.306434,0.018773,0.344987,0.028108,0.333978,0.150220,-0.056568,-0.299064,-0.400082,0.005048,-0.141186,-0.045145,-0.031159,-0.245924,-0.144716,-0.265619,-0.136539,0.198103,0.145575,0.065477,-0.005784,0.355516,-0.188779,0.360034,0.071065,-0.480182,0.200751,-0.068262,0.101231,-0.159615,-0.129663,-0.023724,-0.479284,-0.147662,-0.294832,0.266833,-0.021275,0.232847,-0.237561,-0.174940,-0.108870,0.414180,-0.145479,-0.304512,0.129540,0.268654,-0.147087,0.088361,0.165650,-0.023949,-0.208405,-0.395093,-0.130196,-0.286384,0.079353,-0.108630,-0.014894,-0.606064,0.442235,0.217910,-0.145657,-0.261608,-0.278538,0.430353,0.445422,-0.015614,0.324692,-0.141531,0.108671,-0.484253,0.827359,0.658266,-0.050128,-0.214650,0.073707,0.033031,-0.375734,0.234995,-0.269006,-0.604381,0.011014,-0.094476,-0.789448,-0.278104,0.227403,-0.291009,0.149496,-0.136822,-0.255675,0.021589,-0.003009,0.001056,0.011293,-0.155358,-0.284966,-0.196755,0.221360,0.339815,-0.099358,0.889354,-0.463839,0.166189,0.607351,0.180450,-0.721366,0.791181,0.291114,0.113650,-0.125694,-0.296518,-0.248196,0.179526,0.307833,0.233074,0.345899,-0.145497,-0.539256,0.162164,0.245290', '1908036', '24751763', '1308035', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422039', '煎酿三宝', '喜剧', '龙雁飞（许冠文 饰）是一个著名的武侠小说家，十年了都没有新的作品面世了，不过以往的畅销作品仍然带给他客观的收入，生活无忧。他的女儿Sophia（杨千嬅 饰）是个早已到了适婚年龄，但她恋爱运甚差，只想找一个真正可以过日子的人结婚，其实她一直暗恋自己的上司——花花公子Frankie（刘青云 饰）。Frankie因为意外要搬到Sophia的家住，龙雁飞看见自己心爱的女儿被Frankie当工人使唤，心里很不是滋味，便对Frankie充满了敌意，但在后来的相处中，两个男人又成了知己……©豆瓣', '杨千嬅', '马伟豪', 5.7, 6436, 'tt0440361', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486999558.jpg', 5.6, 24.2, 55.1, 11.6, 3.5, '0.385714,-0.150212,-0.649152,0.693161,-0.466399,-0.485933,0.949344,0.016908,-0.565369,-0.255074,0.077644,0.814261,-0.090401,0.474423,0.012813,0.435916,0.074961,-0.742310,-0.004237,-0.356943,-0.131455,-0.220524,-0.351009,-0.220336,-0.312155,-0.122376,0.683650,-0.121492,-0.088829,0.220350,0.334572,0.109056,0.431702,0.617083,-0.692953,0.139425,0.033860,0.216476,-0.166847,0.241269,0.000780,-0.247944,-0.207128,0.360387,0.018293,0.472537,0.689155,-0.019675,-0.310110,0.262173,0.424392,-0.132937,-0.229065,0.016658,0.194754,-0.045375,0.270998,0.147245,-0.198532,0.092882,0.006093,-0.108655,-0.803417,-0.011143,0.171873,0.048843,-0.676600,0.727012,-0.063546,-0.217493,-0.090958,-0.320497,0.389235,0.005296,0.135075,0.620565,-0.286619,0.128378,-0.749108,0.542162,0.771912,0.091996,-0.203983,0.828260,-0.355333,-0.361926,-0.005590,-0.388899,-0.756823,0.025876,0.105917,0.097350,-0.393130,0.062637,-0.642024,0.232191,-0.034717,-0.062599,0.065499,-0.668049,0.119377,-0.179643,-0.483858,-0.740284,-0.617886,-0.030168,0.162547,-0.456699,0.886006,-0.845612,0.114521,0.436365,0.103842,-0.792465,0.957893,0.497169,-0.197521,-0.205166,0.117277,0.076775,-0.181512,0.068597,0.067764,0.481735,0.081920,-0.269044,-0.454410,0.794432', '3230462', '24756472', '1301974', '3927750');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422063', '最终幻想7：圣子降临', '动作', '赛菲罗斯的事件已经过去2年了，人类从巨大陨石的灾难之下逃脱。曾经繁荣的都市虽然满目疮痍，但人们已经开始投入重建家园的工作之中。而拯救世界的英雄克劳德，却过着与世隔绝的生活。但是，神秘的疾病“星痕症候群”在世界蔓延。蒂法•洛克哈特决定找寻克劳德。但当她找到克劳德之时，眼前这个人，只是一个为艾利斯之死郁郁寡欢的落魄男子。以继承赛菲罗斯的遗志而组成的白发三人组出现在人们眼前，文森特不得不再次挥动双枪，保护大家。而世界的英雄，克劳德，能否再次振作，守护这个世界呢？©豆瓣', '樱井孝宏', '野村哲也', 8.3, 56492, 'tt0385700', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2221176547.jpg', 0.5, 1.8, 17.8, 42.2, 37.7, '-0.158107,0.339010,-0.613139,0.516915,-0.251132,-0.513501,0.797793,0.146525,-0.399446,-0.352395,0.309839,0.750124,-0.003562,0.380353,0.483909,0.241550,-0.236547,-0.734420,0.021112,-0.117265,-0.297614,-0.318116,-0.521090,-0.574154,-0.218278,-0.528745,1.023127,0.398661,-0.051641,0.111812,0.001874,0.452663,-0.191489,0.743903,-0.325685,-0.249293,-0.069064,-0.066316,-0.486271,0.173997,-0.142684,-0.231858,-0.302823,0.555737,-0.353549,0.169171,0.671560,-0.738928,-0.044569,-0.400458,0.352189,-0.341375,-0.252170,-0.128864,0.283236,-0.131731,0.048930,-0.033108,0.168197,-0.217276,-0.041932,-0.217978,-0.635302,-0.040413,0.021803,0.333026,-0.610092,0.210870,-0.043029,-0.143570,-0.093666,-0.314243,0.235385,0.351898,0.397579,0.396598,-0.509482,0.076112,-0.334333,0.025792,0.567732,-0.042070,-0.640753,0.327092,-0.378946,-0.418097,-0.278600,-0.142478,-0.615302,-0.052577,0.040845,0.231872,-0.240420,0.683752,-0.859358,0.036760,-0.515017,-0.381975,-0.103824,-0.340028,-0.471662,-0.610748,-0.309099,-0.058025,-0.262770,-0.062951,-0.078989,-0.266137,0.891636,-0.885805,0.349003,0.543619,0.068601,-0.351495,0.611434,-0.013307,0.216417,-0.266389,-0.256503,0.645716,-0.082685,0.423381,-0.154581,0.012489,-0.061660,-0.096097,-0.451131,0.834057', '26759819', '1308837', '10569150', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422067', '庐山恋', '剧情', '中美建交后，侨居美国的国民党将军周振武的女儿周筠（张瑜 饰）回到祖国观光，在庐山游玩的途中，她巧遇有志青年耿桦（郭凯敏 饰）。两个对祖国怀有无限热爱且充满远大志向的青年走到一起，经过短短几天的相处，他们渐渐产生了感情。然而很快耿桦便因此受到审查，周筠也郁郁离开。十年浩劫结束后，已是清华研究生的耿桦在庐山和周筠重逢，这对相爱之人不愿再被分开，彼此约定婚期。而当耿桦的父亲得知周筠的身世时，却对这门婚事断然拒绝……女主角张瑜凭借本片当选第一届金鸡奖和同年百花奖的“双料影后”。©豆瓣', '张瑜', '黄祖模', 7.6, 14574, 'tt3508268', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2272144735.jpg', 0.6, 2.5, 30.5, 47.4, 19, '0.163914,-0.138488,-0.807257,0.632872,0.129458,-0.547761,0.522172,0.010912,-0.588512,-0.164422,0.160242,1.026952,-0.484081,0.366080,0.336924,-0.167696,-0.254993,-0.817085,-0.076999,-0.392090,-0.001727,-0.403962,0.118321,0.294826,-0.235361,-0.128003,0.911828,0.025147,0.008389,0.922062,0.242571,0.007676,-0.199348,0.638616,-0.146369,0.280074,0.126907,0.319343,-0.604684,0.308240,0.185765,-0.100176,-0.294074,-0.153473,-0.199637,0.158576,0.699488,-0.038821,-0.198115,-0.140607,0.507140,-0.274479,-0.079367,0.311718,0.351668,0.212474,0.113072,0.515270,-0.427151,-0.031718,-0.122653,-0.161685,-0.113639,0.207979,0.120408,0.060094,-0.553948,0.666086,0.118903,-0.270312,0.195708,-0.230569,0.142464,0.509611,0.227144,0.304497,-0.142035,0.155204,-0.329039,0.280386,0.829457,-0.151925,-0.096136,0.320219,-0.106744,-0.489660,0.274549,-0.010425,-0.418095,-0.127690,0.190538,0.143461,-0.044338,0.182472,-0.464171,-0.065959,-0.235813,0.030723,0.257434,-0.430829,0.202400,-0.529851,-0.447864,-0.654217,-0.386940,0.097597,0.203350,-0.251542,0.754980,-0.925659,0.216778,0.149802,0.431428,-0.544375,0.702024,0.279487,0.234971,-0.294626,-0.054942,0.409297,-0.197301,0.211353,-0.069173,0.346140,-0.043308,-0.027209,-0.442611,0.288444', '26365262', '35030151', '1292219', '1780122');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422086', '五月之恋', '爱情', '十九岁阿磊（陈柏霖 饰）跟很多时代年轻人一样喜欢追星，他与几个死党都喜欢五月天这个乐队，更一起维护属于五月天的网页，他们竟然充当乐队的成员给其他歌迷回信。阿磊在网络上以虚拟的身份结识了同样喜欢五月天的瑄瑄（刘亦菲 饰），瑄瑄是哈尔滨京剧团的学生，她趁着随团到台北表演的机会偷偷到了三义。瑄瑄要求与阿磊见面，更要求阿磊能带她到三义去，更不可思议的是当他们来到了三义，瑄瑄要求阿磊闯入一位老妇人的住宅里。两人双双被带到警察局。这时候阿磊才知道她是来自哈尔滨的，却不明白她要到三义去的原因，对于瑄瑄的行为也深感困惑。然而，短短的数天相处中两人的情感更加深厚了。瑄瑄还是离开了台北，阿磊却与她失去了联系。日夜想念瑄瑄的同时，阿磊也决定到三义，去发掘瑄瑄的秘密……©豆瓣', '刘亦菲', '徐小明', 6.9, 37772, 'tt0464758', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p506576148.jpg', 1.9, 8.3, 46.8, 27, 16, '0.265642,-0.040900,-0.824260,0.400224,-0.075836,-0.156557,0.525975,0.118766,-0.734208,-0.182642,0.238638,0.717306,-0.058341,0.234061,0.234103,-0.143765,-0.273044,-0.608658,0.101326,-0.550964,-0.177700,-0.527142,-0.022282,0.120913,-0.111284,-0.046831,0.513965,-0.098804,-0.266675,0.638225,0.363995,0.033273,-0.219085,0.616283,-0.239648,0.306776,0.167864,0.034980,-0.295982,0.241574,0.127141,-0.226901,-0.264235,0.150646,0.145701,0.230664,0.698059,-0.012797,-0.129185,0.092758,0.074510,-0.290683,-0.111314,0.024080,0.348463,-0.056564,0.214744,0.281807,-0.354207,0.520590,-0.392175,-0.037693,-0.689619,0.316117,0.215576,0.256410,-0.697845,0.357350,-0.138622,-0.385597,0.177463,-0.623291,0.266589,0.112365,-0.047356,0.431850,-0.170612,-0.014095,-0.310579,0.013596,0.721394,0.055138,0.102340,0.432924,-0.093180,-0.406622,-0.193339,0.014679,-0.457882,0.076568,0.114208,0.047420,-0.166993,0.019575,-0.584404,-0.164215,0.067987,-0.148444,0.031705,-0.450273,0.310580,-0.482548,-0.164416,-0.471270,-0.104167,0.198165,0.087300,-0.463098,0.832221,-0.992968,0.143087,0.382610,0.616919,-0.681944,0.540207,0.290605,0.007925,-0.092008,0.007614,-0.057227,0.061150,0.313004,0.095741,0.307137,0.051358,-0.317611,-0.657646,0.182300', '35030151', '1301022', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422088', '撒旦探戈', '剧情', '“片长七小时却每一分钟皆雷霆万钧，引人入胜。但愿在我有生之年，年年都重看一遍。”——苏珊‧桑塔格 开场八分钟的推轨镜头，已道出此片的史诗气魄。牛群从牛棚涌出，摄影机隔着一列破旧的农居追踪，有趣的是牠们一路盲目前冲，一路还试图交配。塔可夫斯基式的画面，却是教人屏息的典型塔尔风格，妙笔一挥预告一个集体农场如何走向灭亡。故事始于传闻已死的骗子重临村子，他要骗走农场收入 ，却给村民认定是大救星。接着上演一个悲剧，然后是一个讽刺故事。全片十二章的结构正如 Krashnahorkai 的原著，启发自六步踏前、六步退后的探戈舞，不同视角有时重复同一剧情。农场最终的命运暗喻九十年代初共产主义的破产，同时也是人类共同命运的观照。 全片最精彩两段，一是担当叙事者的医生偷偷记录村民活动，他蹒跚买醉的跟镜，成为最感人的观影存在体验。另一段女孩虐猫，亦写下影史上有数的伤感时刻。没有故弄玄虚，一种交代故事的坦率，让演员在真实时间存在，让观众随他们的情态同步呼吸，个中有导演对电影最大的深情与敬意。七个半小时的每个镜头，个个都是不朽──没有想当然的静止，而是自有一种有机的内在节奏。像小津和德莱叶，塔尔深谙长镜头的真谛。这是必须去经历的，一生难逢的观影经验。', '米哈伊·维格', '贝拉·塔尔', 9, 8050, 'tt0111341', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2327374507.jpg', 1.3, 1.5, 7.7, 26.4, 63.1, '0.122505,-0.152111,-0.444458,0.619960,0.176555,0.008479,0.783482,-0.107847,-0.319958,-0.136120,0.331793,0.509392,-0.338782,-0.069705,0.188577,-0.201061,-0.175554,-0.517457,-0.322272,-0.101408,-0.119487,-0.274857,-0.252463,-0.133849,0.065244,-0.297003,0.408567,0.127405,-0.354822,0.147320,0.286280,0.069610,-0.227695,0.004058,-0.238792,0.003201,-0.110383,0.013263,-0.305847,0.032112,-0.221059,-0.127795,-0.351523,-0.004090,-0.410379,0.249911,0.632249,-0.281508,-0.197425,0.342208,0.534420,-0.127157,-0.325835,-0.142864,0.064804,0.027282,0.240677,0.312916,0.155031,0.133185,-0.151656,-0.108905,-0.982842,-0.103163,0.091970,0.191481,-0.400036,0.392032,0.099048,-0.066836,0.143303,-0.104310,-0.056323,0.069999,0.461885,0.514384,-0.096069,-0.125453,-0.258584,0.292814,0.551765,0.201187,-0.534316,0.461652,-0.238813,-0.485473,-0.191365,-0.233526,-0.352704,0.007721,0.221366,0.077369,-0.076603,0.238928,-0.495746,0.213768,0.005029,-0.285278,0.105994,-0.559464,-0.084004,-0.556290,0.071449,-0.315997,-0.084806,0.053966,0.138322,-0.303941,0.922447,-0.296997,0.265023,0.429722,-0.091221,-0.275300,0.817719,0.079876,-0.161094,-0.222795,0.079358,0.295312,-0.023718,0.283389,-0.073458,0.418224,-0.087243,-0.118618,-0.505519,0.553730', '27602116', '2027945', '3318306', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422089', '外出', '剧情', '音乐会正在进行，灯光指导仁书（裴勇俊饰）把工作交给了助手后仓促离开。他是得知妻子秀真（林尚孝饰）出了车祸，赶到江原道三陟市手术室外的走廊上，在那里他遇到了舒英（孙艺珍饰）。原来舒英的丈夫京浩（柳承洙饰）也在同一部车上，这是婚外情。这对仁书和舒英来说比致命车祸更难接受，他们谴责爱人的出轨，但也祈祷秀真和京浩可以平安康复。背叛婚姻情感的秀真和京浩因重伤昏迷成为植物人，而仁书和舒英也在处理事故的过程中意识到了两人之间的情感跳动，渐渐被对方所吸引。他们在汽车旅馆里住下，最终堕入情网。同病相怜的他们感受到了痛苦。就在此时，秀真苏醒……©豆瓣', '裴勇俊', '许秦豪', 6.6, 25958, 'tt0448663', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1532672988.jpg', 1.3, 9.9, 53.1, 26.8, 8.9, '0.271175,0.002967,-0.784546,0.219101,0.015914,-0.196168,0.819248,0.129896,-0.384924,-0.282635,0.302455,0.682297,-0.204986,0.328190,0.280153,-0.126369,-0.471104,-0.858699,-0.038458,-0.011698,-0.606685,-0.539101,-0.072469,0.039966,-0.127772,-0.296496,0.587893,0.217685,-0.330977,0.554511,0.121538,0.303704,-0.305380,0.592405,-0.148076,0.196227,-0.044130,0.129865,-0.332123,0.230991,0.207461,-0.362957,0.095268,0.232749,0.068811,0.255712,0.652517,-0.233001,-0.159329,0.092720,0.173336,-0.362501,-0.077850,0.310241,0.273599,0.057559,0.228880,0.262874,-0.532713,0.035872,-0.075412,0.088327,-0.761619,0.063609,-0.062340,0.218659,-0.679297,0.499680,0.041732,-0.134021,0.229470,-0.283486,0.519156,0.366091,0.101452,0.566756,-0.628922,-0.066547,-0.576995,-0.097858,0.739814,-0.044852,-0.040640,0.432058,-0.173811,-0.485655,-0.167986,-0.101214,-0.253299,-0.006522,0.229864,0.328671,-0.337079,0.052717,-0.241575,-0.146151,-0.004093,-0.101489,-0.253427,-0.497977,-0.026653,-0.674521,-0.259085,-0.379501,-0.487726,0.112953,0.015525,-0.479860,0.469625,-0.779769,0.232497,0.328670,0.400677,-0.408472,0.772090,0.094331,0.225887,0.014728,0.005886,0.241392,-0.038021,0.308949,0.318667,0.314646,-0.284298,0.185546,-0.542647,0.309307', '1292211', '34925598', '3055049', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422091', '情迷意乱', '剧情', '小镇里，一家超级市场的宣传车四处开动，正在播放着周年庆大减价的消息，森田屋的礼子（高峰秀子 饰）却很苦恼。这家家庭式百货商店是礼子婆家的店，结婚不久后，丈夫于战场战死，家里只剩下上了年纪的婆婆（三益爱子 饰）和年纪尚幼的小叔幸司（加山雄三 饰）。礼子一人扛下经营的重担，一晃十八年，而现在却遭到超级市场的大冲击。礼子的小姑们——久子（草笛光子 饰）和隆子（白川由美 饰）想要借森田屋这块地皮改造成超级市场，而改建计划里却没有礼子的位置。知晓实情后的礼子借再婚之名决定离开森田屋。而另一方面，幸司终于按捺不住自己对礼子的爱意，倾诉了他的想法。礼子平静的生活被这告白扰乱，变得心绪不宁，正好借森田屋改建之事离开这个是非之地。在幸司送礼子回老家的路途上，面对离别，礼子流露出不舍，她对幸司其实也怀抱爱意只是碍于叔嫂的身份而无法表露。离老家越来越近，等待幸司和礼子的是爱意的互通还是更深的悲剧……', '高峰秀子', '成濑巳喜男', 9.1, 11816, 'tt0058349', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1449763371.jpg', 0.2, 0.4, 4.5, 33.9, 60.9, '0.169418,0.179967,-0.738493,0.433551,-0.090034,-0.438107,0.810974,0.245475,-0.373281,-0.362853,-0.011877,0.564028,-0.145406,0.389217,0.010642,0.178960,-0.081425,-0.473738,-0.017424,-0.270237,0.081748,-0.520674,0.006048,-0.175132,-0.264482,0.025443,0.690389,0.247233,-0.127537,0.455875,0.450305,0.318451,-0.089704,0.496926,-0.161366,0.015901,-0.147953,0.200623,-0.340631,0.190375,-0.114559,-0.256440,-0.204511,0.297600,0.133154,0.582090,0.611117,0.071728,-0.208067,-0.051423,0.049610,-0.055304,-0.140945,0.321661,0.358034,0.075378,0.224076,0.164524,-0.623786,-0.091145,0.108320,-0.115198,-0.338911,0.021521,0.204491,0.179200,-0.587363,0.295959,-0.237084,-0.166564,0.134105,-0.364960,0.194772,0.272446,0.101327,0.466284,-0.355104,0.200023,-0.210284,-0.106378,0.544836,-0.116606,0.074841,0.406715,-0.254013,-0.150655,0.128741,-0.210441,-0.513968,-0.195895,-0.025804,0.205405,-0.098017,-0.045303,-0.453313,-0.062915,-0.296155,-0.397074,0.153315,-0.368062,-0.166877,-0.415886,0.044808,-0.681137,-0.429455,0.154090,0.342835,-0.091509,0.519898,-0.768773,0.187547,0.212938,0.323135,-0.433894,0.479240,0.108541,-0.094676,-0.205424,-0.034730,0.219284,-0.500225,0.186961,0.094942,0.209827,-0.101007,-0.245235,-0.640612,0.510734', '3111650', '4275444', '25911595', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422106', '尖峰时刻3', '喜剧', '严肃机警的李探长（成龙 饰）和贫嘴的警探James Carter (Chris Tucker饰)，在成功完成两次的跨国任务之后，这次又迎来了更加艰巨的任务。调查“三和会”犯罪证据的韩领事被人暗杀，深感自责的李警官疯狂追击杀手，却被贬职当交警的James Carter帮了一个倒忙，理所当然，他们二日的奇特组合又开始一方面，按照韩领事的线索，他们到了巴黎——这个“三和会”千方百计隐藏的心脏地带，克服重重困难，探索真相；另一方面，他们还要保护韩领事长大成人的女儿苏阳（张静初），而杀手，却是李探长小时候在孤儿院的好兄弟Kenji（Hiroyuki Sanada 饰）。重重危机之下，二人如何应对？尖峰时刻，李探长的中国功夫将扭转乾坤。©豆瓣', '克里斯·塔克', '布莱特·拉特纳', 6.8, 55088, 'tt0293564', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p457005429.jpg', 1, 7.2, 53.3, 28.6, 9.9, '0.110751,0.015851,-0.514226,0.623076,-0.204860,-0.448360,0.565585,-0.088527,-0.512496,-0.387673,0.243774,0.195299,-0.177644,0.093655,0.302752,-0.396356,-0.260607,-0.684223,-0.055726,0.191790,-0.455723,-0.339875,-0.320522,-0.488611,-0.008110,0.137908,0.442073,0.543646,-0.097602,0.177086,0.361738,0.362532,-0.141209,0.593959,0.028455,0.106671,0.308983,0.008192,-0.238285,0.075626,0.517390,-0.661940,-0.030700,0.274626,0.155280,0.545485,0.688721,-0.100608,-0.304169,-0.045924,0.175705,-0.644801,-0.008261,0.049207,0.329262,-0.124149,-0.256495,0.008060,-0.098564,-0.293042,-0.126471,-0.288829,-0.836078,-0.066493,0.331694,0.016456,-0.407553,-0.035845,-0.370013,0.360773,-0.087643,-0.511665,0.133412,0.574450,0.286239,0.145505,-0.099595,0.128511,-0.558152,0.395108,0.640356,0.085817,-0.014562,-0.289458,-0.078741,-0.714056,0.058454,-0.241811,-0.161005,0.210158,0.733264,-0.203985,0.079884,-0.027561,-0.454549,-0.248616,-0.307009,0.022996,-0.350830,-0.557018,0.240092,-0.552264,0.083223,-0.273793,-0.092107,0.125473,0.066145,-0.314325,0.472477,-0.648014,-0.003315,0.348355,0.214681,-0.515523,0.152886,0.065927,0.272096,-0.533552,-0.033470,-0.074736,0.248813,0.498934,0.410445,0.415824,-0.028507,-0.134970,-0.295361,0.112981', '24756658', '1419985', '1301022', '26897427');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422186', '自己去看', '剧情', '这是一部很特殊的战争题材电影，它真实地描写了德占区人民的悲惨遭遇和场面，以及人们面对突如其来的灾难的恐惧，反映了战争的真实面目。它既不同于《斯大林格勒保卫战》、《攻占柏林》这些正面战场的血肉横飞、排山倒海、摧枯拉朽，也不同与《这里的黎明静悄悄》、《星》所描写的局部战斗中体现的平凡悲壮，更不是战地浪漫曲，而是降临在平民百姓头上血淋淋的残酷。影片的事件和恐怖场面远超过任何一部描写德军集中营的电影，令人毛骨悚然，提醒胆小和心软者慎看。', '阿列克谢·克拉夫琴科', '依莱姆·克里莫夫', 8.8, 13788, 'tt0091251', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2181115350.jpg', 0.7, 1.5, 9.5, 35.7, 52.6, '0.323619,-0.005005,-0.618632,0.669182,0.560154,0.472719,1.072351,-0.074566,-0.277333,-0.070501,0.325757,0.715120,-0.342118,-0.156838,0.173985,-0.321611,-0.352312,-0.605150,-0.423638,0.287640,-0.212239,-0.048326,-0.465703,-0.230816,0.083565,-0.350881,0.825902,0.615905,-0.979240,0.402983,0.040268,0.463497,-0.080192,0.502695,0.055536,-0.294637,-0.423532,0.042295,-0.348193,-0.288882,-0.078753,-0.171597,-0.425585,0.737028,-0.366531,0.214916,0.740064,-0.745671,-0.399840,-0.069889,0.763380,-0.379440,-0.123995,0.191037,-0.131274,-0.165101,0.234210,-0.080552,0.333541,0.252898,-0.208273,0.040026,-1.197758,-0.002613,0.062331,0.259979,-0.306946,0.565220,0.054952,0.009234,0.225000,0.203461,0.379409,0.159237,0.228937,0.712726,-0.244252,-0.352479,-0.369402,0.407919,0.709326,0.103503,-0.799248,0.336804,-0.468585,-0.534935,-0.113962,-0.571042,-0.324003,0.404303,0.172136,-0.178998,-0.164218,0.506450,-0.776572,0.085808,-0.226331,-0.527796,-0.428621,-0.435752,-0.241262,-0.873576,-0.372829,-0.690556,-0.368016,-0.126094,0.189291,-0.194908,0.749196,-0.492767,-0.166874,0.322431,0.082343,-0.195887,0.322617,0.146741,-0.216211,-0.061342,-0.187902,0.462914,-0.085156,0.333287,-0.033920,0.262258,0.078355,-0.042986,-0.239937,0.891632', '26667010', '1292881', '35360296', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422283', '高山下的花环', '剧情', '驻扎在四川广元的九连长梁三喜（吕晓禾 饰）为了从军政治部调来的指导员赵蒙生（唐国强 饰）推迟了探亲假，可出身高干家庭吃不了苦的蒙生打算只干几个月就走。1979年，赵母吴爽（刘燕生 饰）得知蒙生部队将要赴越作战，加紧督办调动之事。耿直的炮排长靳开来（何伟 饰）听说后火冒三丈，扬言要自费上北京告状。部队开赴云南边境，吴爽孤注一掷请求军长雷震（童超 饰）将蒙生调回后方……©豆瓣', '吕晓禾', '谢晋', 9.5, 56374, 'tt0090340', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2319879389.jpg', 0.2, 0.3, 3.5, 18.6, 77.5, '-0.005290,-0.213729,-0.684467,0.298426,0.088415,-0.152486,-0.055112,0.288887,-0.358444,-0.096123,-0.161001,0.044577,0.197947,-0.216681,0.189749,-0.217173,-0.180591,-0.494139,-0.122358,-0.199826,-0.031766,-0.532118,0.204851,-0.079711,-0.017489,0.074915,0.245706,-0.048055,0.217344,0.585174,0.276421,0.296829,0.139732,0.308430,0.104090,-0.000268,0.019367,-0.112082,-0.343021,0.167396,0.084548,-0.260856,-0.110128,-0.247843,0.374785,0.151365,0.258699,0.287283,0.096459,-0.242545,-0.132554,-0.083774,-0.201022,-0.097396,0.543919,0.401486,-0.036336,0.110062,-0.155298,0.194168,-0.092965,-0.070675,0.101880,0.099672,-0.031356,-0.229587,-0.749694,0.113407,-0.188562,0.315700,-0.016799,-0.587145,0.080898,0.623656,-0.172909,0.093531,-0.213196,0.141225,-0.312175,0.497640,0.573842,-0.292316,0.271451,-0.480222,0.270844,-0.144549,0.411879,-0.109909,-0.256439,0.123209,-0.135611,-0.111732,0.255320,-0.203435,-0.214981,-0.011825,-0.312467,-0.037050,0.153933,0.193376,-0.037602,-0.331669,0.186383,-0.053501,-0.141897,0.318449,0.438170,0.194166,0.328238,-0.392964,0.064144,0.027681,0.423689,-0.821191,0.230395,0.279493,0.186708,-0.237111,0.328900,-0.056895,-0.183441,0.574575,0.269783,0.255767,-0.307869,-0.732768,0.010481,-0.017802', '1439400', '1303485', '1297710', '1482541');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422286', '冰山上的来客', '剧情', '1951年夏，新疆帕米尔高原。边疆军民的生活正受到特务组织的威胁。从外地娶来的新娘子古兰丹姆实际是女特务古里巴儿（谷毓英饰）假扮。她的到来勾起了解放军哨所战士阿米尔（阿木都力力提饰）的心酸回忆，本来是青梅竹马的一对，彼此却在早年失去联系。当假古兰丹姆得知这段童年往事之后，对阿米尔格外亲昵，以刺探军事情报。这一反常举动引起杨排长（梁音饰）的高度警觉。不久，敌人得寸进尺，偷越边防袭击哨所。可敌人的千算万算却没有逃过我军设下的天罗地网。杨排长将计就计，不仅揭穿了假古兰丹姆的真实面目，更是把这伙狡猾的特务一网打尽。阿米尔终于和真古兰丹姆（阿依夏木饰）再次重逢，在胜利的凯歌中迎接旭日东升。片中主题曲“花儿为什么这样红”成为经典曲目，传唱至今。©豆瓣', '梁音', '赵心水', 8, 11088, 'tt6635034', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2642079391.jpg', 0.8, 1.5, 22.5, 49, 26.3, '0.211565,-0.052030,-0.636451,0.481669,-0.074090,-0.229750,0.390508,-0.305351,-0.694217,-0.225832,0.054509,0.188623,-0.349297,-0.101330,0.239052,-0.128426,-0.292351,-0.548649,-0.146904,-0.098769,-0.209576,-0.274009,-0.414103,-0.241842,-0.225731,-0.319593,0.303650,0.240358,-0.370359,0.569685,0.204452,0.189243,-0.081377,0.446793,0.084510,0.217747,-0.003562,-0.163238,-0.276267,0.019118,0.036269,-0.327452,-0.459974,0.071447,-0.013713,0.453071,0.485696,-0.498747,0.017906,0.094552,0.202854,-0.433099,-0.031113,0.074374,0.465684,-0.252259,-0.065628,-0.158147,-0.240300,0.052746,-0.166628,0.073836,-0.413026,0.071884,0.118656,0.127475,-0.332123,0.051309,-0.060724,0.297770,0.349786,-0.264103,0.211663,0.471499,0.400089,0.178948,-0.105253,0.123184,-0.384215,0.106998,0.711476,0.033261,-0.118061,-0.102580,-0.402491,-0.486441,0.040446,-0.111975,-0.239139,0.024691,0.212275,-0.292251,0.246906,0.328471,-0.469193,-0.228291,-0.308478,0.091231,0.046692,-0.272786,-0.216972,-0.423537,-0.325583,-0.432622,-0.104600,0.372413,0.084938,-0.160985,0.464446,-0.590117,0.208517,0.276834,0.237555,-0.205465,0.238401,0.186471,-0.078167,-0.160421,0.016035,0.499360,0.292848,0.155108,0.108585,0.140921,-0.122782,-0.063580,-0.168951,0.295640', '1307186', '30166972', '1870682', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422306', '死路', '悬疑', '又一年圣诞节来到，弗兰克·哈灵顿（Ray Wise 饰）带着妻子劳拉（Lin Shaye 饰）、儿子理查德（Mick Cain 饰）、女儿玛丽安（Alexandra Holden 饰）及其男友布莱德（Billy Asher 饰）驱车前往亲戚家度假。夜晚的旅途困顿乏味，弗兰克还险些出了车祸。在极度压抑的情况下，他决定放弃那条走了20年的州际公路，转而奔上从未走过的小路。但是这却是一个糟糕的决定，路上出现的白衣女子和黑色房车将海灵顿一家引向死途……本片荣获2003年布鲁塞尔国际奇幻电影节欧洲奇幻电影银奖和佩格萨斯观众奖、2003年亚洲奇幻电影节评委会奖最佳影片、2003年圣•塞巴斯蒂安恐怖与奇幻电影节观众奖最佳影片。©豆瓣', '亚历山德拉·霍尔登', '让-巴普蒂斯特·安德烈', 7.3, 24575, 'tt0308152', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1487044062.jpg', 1.5, 5, 36.6, 43, 14, '-0.144224,-0.174842,-0.405800,0.573791,0.588147,-0.258804,0.563282,0.122730,-0.589714,-0.043728,0.282527,0.857962,-0.635500,0.180473,0.811136,0.132828,-0.612549,-0.612588,0.030432,-0.191813,-0.124447,-0.178792,-0.237968,-0.054950,0.080363,-0.367338,0.636615,0.329525,0.082114,0.807331,0.544937,0.210390,-0.223511,0.219827,-0.191559,0.156692,0.287303,0.175793,-0.326404,0.298908,-0.034594,-0.517428,-0.478061,0.065282,0.271384,0.106481,0.676356,-0.192145,-0.039261,0.221219,0.428957,-0.352690,-0.254795,-0.185260,0.054315,-0.060270,0.138408,0.266576,-0.054168,0.106509,0.073097,-0.395770,-0.127365,0.498660,-0.149939,0.076477,-0.636912,0.328373,-0.178632,0.271952,-0.033623,-0.369541,0.180139,-0.167509,0.153063,0.261655,0.129482,0.152729,-0.297614,0.520645,0.517397,0.028220,-0.292930,0.097052,-0.267504,-0.501288,-0.223557,-0.189098,-0.455120,0.277791,0.444509,-0.096961,0.087905,0.175279,-0.564812,0.031708,-0.131381,-0.454154,0.020967,-0.008838,-0.208303,-0.758217,0.265731,-0.138914,-0.216782,-0.060539,-0.173779,0.038011,0.423643,-0.286215,0.433615,0.410666,0.385361,-0.173397,0.902660,-0.330926,0.092992,-0.123091,-0.271399,0.353602,-0.474321,0.146367,-0.140340,0.283921,-0.186563,-0.218556,-0.339012,0.409763', '1780122', '1302279', '1829654', '3011997');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422889', '长恨歌', '剧情', '王琦瑶（郑秀文 饰）与同学蒋丽莉（苏岩 饰）到片场参观，认识了摄影师程先生（梁家辉 饰）。程先生为琦瑶拍照并倾心于她，后来更推荐琦瑶参加“上海小姐“的选举。王琦瑶的风姿不仅使她赢得了第三名，还令掌握军政大权的李主任（胡军 饰）义无反顾的爱上了她。王琦瑶也全身心投入，可是李主任遭到了追杀后便销声匿迹了，王琦瑶倍感伤痛。期间她最好的朋友蒋丽莉也离开上海了。富家子康明逊（吴彦祖 饰）的出现使琦瑶的生活起来波澜，琦瑶更怀上了他的孩子，由于上海局势不定康明逊必须离开，王琦瑶只好用钱买来一段婚姻以换取给予孩子的名分。十年后，她遇到了与自己女儿相仿的男孩老克，并与老克有了一段忘年恋，可是这个年轻人即将要离开上海了……©豆瓣', '郑秀文', '关锦鹏', 6, 20975, 'tt0475263', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p537026298.jpg', 4.9, 20.9, 49.4, 19.5, 5.2, '0.043408,0.078513,-0.485263,0.411337,-0.039418,-0.571353,0.405861,0.137029,-0.320089,-0.198287,0.015381,0.666760,-0.180155,0.326587,0.284603,-0.159406,-0.166050,-0.656736,0.009696,-0.256491,-0.239746,-0.335685,-0.046009,0.097947,-0.174176,-0.030225,0.612778,0.038757,-0.085802,0.475117,0.281636,-0.040548,0.117143,0.569398,-0.142298,0.163910,-0.049730,0.236328,-0.451845,0.067794,0.419226,-0.582116,-0.030530,0.208545,0.178845,0.213989,0.623473,-0.143205,-0.138970,-0.073291,0.336330,-0.216906,-0.160931,-0.095496,0.129870,-0.028174,0.136146,0.352093,-0.241647,-0.007118,0.031012,-0.252532,-0.259501,0.200042,0.106453,0.117191,-0.541890,0.307261,-0.084082,0.159529,-0.083265,-0.361777,0.236801,0.421962,-0.073945,0.191128,-0.473755,-0.131482,-0.331278,0.481883,0.713174,-0.001276,0.000347,0.307262,-0.152549,-0.481716,0.120188,-0.132171,-0.417330,0.150762,0.183933,-0.080637,-0.007416,0.072378,-0.345649,-0.056113,-0.371193,-0.088615,0.027603,-0.453540,0.242365,-0.506889,-0.144350,-0.356559,-0.258937,-0.057563,0.259659,-0.384090,0.776462,-0.803417,0.039802,0.333894,0.677440,-0.705909,0.459268,-0.015009,0.310596,-0.269625,-0.040625,0.176870,-0.182189,0.255106,0.080074,0.241583,-0.117745,-0.218962,-0.155954,0.288052', '30345227', '3445516', '1301022', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422908', '鬼打鬼', '喜剧', '车夫张大胆（洪金宝 饰）自称胆识过人，神鬼不怕，经常与别人打赌练胆。某天他提前收工，发现老婆（梁雪薇 饰）与别人私通，而对方竟是大胆的雇主谭老板（黄蝦 饰）。谭老板为掩盖真相，派师爷（太保 饰）寻茅山道士钱真人（陈龙 饰）设坛杀害大胆。钱真人设下圈套，借打赌之名将张大胆诱至马家祠堂，施法唤出僵尸追杀大胆。钱之师弟许真人（钟发 饰）不满师兄图财害命、伤天害理恶举。他暗中协助大胆，使之最终逃过此劫。然而谭老板祸心不死，一计不成，再施一计，非置大胆于死地不可……©豆瓣', '洪金宝', '洪金宝', 7.6, 26963, 'tt0080827', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2003619127.jpg', 0.4, 2.6, 32.1, 44.3, 20.7, '-0.428193,-0.031910,-0.059436,0.635967,-0.425790,0.042427,0.188901,0.033703,-0.249490,-0.458295,0.101050,0.203727,0.002876,0.124873,0.061900,-0.181498,0.294678,-0.159646,0.008763,0.189018,0.108276,-0.595970,-0.033491,-0.310853,-0.384336,0.150940,-0.325505,0.310902,-0.276493,0.079319,0.796976,-0.018403,-0.540504,0.153055,0.257828,0.116417,-0.040522,0.087694,-0.398791,-0.061342,-0.188312,-0.439716,0.028445,0.163902,-0.058374,0.561335,0.189027,-0.050276,-0.472405,-0.390578,0.354514,0.195206,0.281155,0.070615,0.065385,-0.075007,0.415690,-0.029253,-0.000473,-0.092526,0.299509,0.202996,-0.098085,0.313849,0.393064,-0.877403,-0.133794,-0.487608,-0.182106,0.616306,-0.422278,-0.381693,-0.214321,0.010517,0.460936,-0.353108,0.341082,-0.185306,-0.238003,0.321020,0.317779,-0.010833,0.498348,-0.262718,0.624237,-0.208994,0.617504,-0.402440,-0.084285,0.329211,0.514447,-0.552295,0.273711,0.050233,0.097740,-0.464445,-0.267718,1.033042,0.161643,0.070236,0.299054,-0.132581,0.178315,0.201588,-0.105773,0.292816,0.346806,-0.350933,0.000341,-0.196998,-0.079842,0.246050,0.154608,-0.664749,0.365182,-0.275462,-0.369778,0.034115,-0.239577,-0.163894,0.653019,0.380004,0.301383,-0.005053,0.237790,-0.126358,0.324426,-0.521119', '1301946', '3546019', '26797419', '1304021');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422909', '新抢钱夫妻', '喜剧', '一间大公司的小职员迪克（金•凯瑞 Jim Carrey 饰）终于时来运转，被总裁杰克提拔当上了副总裁。终于出人投地的迪克尽情享受着生活，妻子简（蒂娅•里欧妮 Tea Leoni 饰）也辞去了工作在家当起了全职主妇。岂料，迪克只是公司的牺牲品，不久公司就传出财务丑闻，总裁杰克也携巨款潜逃。由于迪克的所有积蓄之前都买了公司的股票，这下，他刹那间就变得一文不值。生活逼人，迪克和简铤而走险当起了“雌雄大盗”。迪克和简有时会打劫咖啡店，只为了两杯咖啡和两块点心；晚上迪克也会跑去每个邻居的院子偷一小块草皮然后铺到自己的院子，夫妻俩的生活虽然贫困却也洋溢着幸福。这天，迪克和简决定向侵吞了巨款的杰克下手。事情有没有他们设想的简单？©豆瓣', '金·凯瑞', '迪恩·帕里索', 7.1, 35703, 'tt0369441', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p827010613.jpg', 0.5, 4.6, 45.9, 37.7, 11.2, '0.087394,0.001905,-0.492021,0.297700,-0.275268,-0.691176,0.584724,0.560773,-0.235718,-0.193144,-0.062761,0.838575,-0.051552,0.334223,0.406385,0.386496,-0.349155,-0.548500,-0.117582,-0.080748,-0.108428,-0.395969,-0.180752,-0.518805,-0.061382,0.017164,-0.075875,0.093614,-0.161430,0.222239,0.533319,0.045240,-0.063814,0.427746,-0.065635,0.013429,0.150407,0.055193,-0.215119,-0.117030,0.126854,-0.175125,-0.139091,-0.057506,0.726009,0.226736,0.396155,0.141545,-0.041984,-0.116143,0.077094,-0.200896,0.011162,-0.145127,0.390623,0.071966,0.288749,0.249749,-0.343832,-0.038799,0.078475,-0.149249,-0.749995,0.059884,-0.135710,-0.103081,-0.608113,0.297806,-0.073889,0.008525,0.094161,-0.411276,0.124200,0.277125,-0.044332,0.328105,-0.038032,0.176756,-0.809513,0.396469,0.296631,0.009524,-0.075410,0.353756,-0.064008,-0.182966,-0.186017,0.077675,-0.351489,-0.318751,0.545260,0.012299,-0.041179,0.174358,-0.652665,-0.181773,-0.461286,-0.473376,0.394014,-0.373630,-0.154315,-0.676265,0.018195,-0.129432,-0.516959,0.006107,0.182449,-0.044706,0.477225,-0.530273,0.094599,0.400333,0.157770,-0.392736,0.496078,-0.194658,0.163243,-0.015762,-0.117559,-0.174147,0.088545,0.596683,0.518714,0.377015,-0.008630,-0.131757,-0.234527,0.584457', '4944008', '26678509', '1309101', '1308842');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422911', '流言蜚语', '喜剧', '本片是经典电影《毕业生》的外传，情节围绕女主角的身世之谜展开的。该片也是詹妮弗·安妮斯顿和前夫布拉德·皮特离婚之后推出的首部影片。sarah(詹妮弗·安妮斯顿 Jennifer Aniston 饰）是一名专门撰写讣告的女记者，在一次偶然的机会中，她发现自己的祖母很可能是经典电影《毕业生》中“罗宾逊太太”的原型，而她从来不知道自己的父亲是谁。于是，她决定回老家把自己的身世查清楚。在此过程中，她遇到了那位神秘的风流倜傥的老帅哥Mr.Burroughs(凯文·科斯特纳 Kevin Costner 饰)，却也不知不觉被他吸引，还有了一夜风流。sarah的未婚夫无法接受sarah的出轨而与她发生争执。随着真相浮出水面，似乎家中的老少三代的女人竟然都和同一个男人“有染”，简直令人无法接受……©豆瓣', '詹妮弗·安妮斯顿', '罗伯·莱纳', 6.4, 8730, 'tt0398375', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p808344961.jpg', 2.4, 11.6, 57.4, 22.6, 5.9, '0.426341,-0.142954,-0.796162,0.683323,-0.288189,-0.126338,0.803286,-0.133585,-0.578988,-0.208403,0.207607,1.029562,-0.191954,0.366007,0.126939,0.248097,-0.164318,-0.765687,0.004847,-0.309132,-0.193245,-0.449593,-0.358771,-0.097925,-0.049578,-0.223529,0.611523,-0.083505,-0.201264,0.174782,0.635054,0.334098,0.002351,0.440527,-0.052314,0.288697,0.105311,0.026586,-0.086836,0.231371,0.328395,-0.368347,-0.076415,0.257136,-0.189114,0.449006,0.561664,-0.218602,-0.081585,0.004370,0.634827,-0.294799,-0.049893,0.239579,0.283579,-0.062042,0.320293,0.393506,-0.081694,-0.243566,0.075817,0.129066,-0.644056,0.165675,0.355657,0.354574,-0.546762,0.192132,-0.183031,-0.037810,0.002711,-0.327417,0.196266,0.074295,0.283698,0.192366,-0.198690,-0.122196,-0.457555,0.444416,0.575203,0.238352,-0.255703,0.387230,-0.262857,-0.420834,-0.201770,-0.259156,-0.714064,0.197913,0.235577,0.122467,-0.179572,0.332662,-0.250113,-0.159190,-0.357752,-0.139636,-0.226663,-0.439561,-0.075114,-0.368613,-0.249612,-0.491317,-0.311084,-0.178764,0.128457,-0.388896,0.680477,-0.771963,0.169945,0.538974,0.218772,-0.492019,0.827567,0.287605,0.036600,-0.226239,-0.136147,0.051056,0.146246,-0.030956,-0.010678,0.441058,0.159044,-0.248850,-0.421947,0.496426', '34890458', '30162520', '1456503', '1292207');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422912', '吉屋出租', '剧情', '一栋老旧楼房顶层的简陋公寓中，住着两个为了艺术而挣扎的室友：罗杰(Adam Pascal 亚当•帕斯考 饰)和马克（Anthony Rapp 安东尼•雷普 饰）。马克最近失恋了，他的女友莫琳因为喜欢同性的乔安妮而抛弃了他。马克之前的另一位室友汤姆(Jesse L. Martin 杰西•L•马丁 饰)――一个电脑奇才，也是艾滋病毒的携带者，不幸路遇抢劫，遍体鳞伤之时被同性恋街头鼓手安琪(Wilson Jermaine Heredia 威尔森•杰梅因•贺雷迪亚 饰)接回了这栋公寓，他们很快走到了一起。罗杰认识了前来借用火柴的邻居咪咪(罗萨里奥•道森 Rosario Dawson 饰)，咪咪是个脱衣舞女。不久，罗杰就发现咪咪跟自己有着相同的秘密和疾病――艾滋病，二人同病相爱。三对有情人由于没钱交房租，即将度过一个没有暖气、没有电力，只靠蜡烛取暖的圣诞夜。', '安东尼·拉普', '克里斯·哥伦布', 8.4, 9771, 'tt0294870', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2734541834.jpg', 0.4, 2.3, 15.7, 39, 42.6, '0.541567,-0.190937,-0.549981,0.282418,-0.208554,-0.333027,1.079613,0.214627,-0.262187,-0.452125,0.157430,0.841925,-0.196358,0.493371,0.105945,0.273649,-0.212764,-0.576109,0.107771,-0.036405,-0.444115,-0.503850,-0.168242,-0.159456,-0.100553,-0.112281,0.239346,-0.060208,0.133469,0.515341,0.238148,0.316753,-0.051131,0.181293,-0.252202,0.265423,0.389735,-0.068900,-0.191887,0.267386,-0.070717,0.112246,0.132892,0.052498,-0.040277,0.384737,0.506085,-0.165094,0.117941,0.100348,0.154497,0.012488,-0.185260,0.113953,0.452140,-0.156501,0.397086,-0.025864,-0.146930,0.065465,0.355917,-0.083275,-0.413602,0.113487,-0.047523,0.016098,-0.380003,0.769662,-0.327231,-0.032415,0.153269,-0.128822,0.187829,0.350516,0.095344,0.388829,-0.104413,-0.038190,-0.587048,-0.044430,0.440198,-0.045781,-0.103249,0.566899,-0.546041,-0.202552,0.050746,-0.010684,-0.598704,0.005330,0.634503,-0.208766,-0.015040,-0.075685,-0.669256,-0.052000,-0.259683,0.124129,-0.026810,-0.093064,-0.098602,-0.596320,-0.104083,-0.482403,-0.168228,0.077287,-0.153207,-0.196327,0.363435,-0.785927,0.106416,0.418953,0.256866,-0.263563,0.739297,-0.104215,0.177071,-0.033431,0.103556,0.138106,0.025977,0.228573,0.291383,0.554241,0.103900,-0.114918,-0.385440,0.385079', '1301686', '1296534', '1394176', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422913', '超人高校', '喜剧', '威尔的爸爸妈妈都是超人界定天皇巨星，理所当然，少年威尔（迈克尔•安格拉诺 Michael Angarano 饰）进入了超人的摇篮——超人高校学习。进校的第一天就要进行超能力测试，拥有超能力的优质学生将进入英雄组，其他人则会被分到吃力不讨好的助手组。很不幸，威尔进入了助手组。从此，威尔的日子相当不好过，他不仅被超人组队同学整蛊，就连啦啦队的美女们都取笑他，而且可怜的他还要尽力向超人父母隐瞒他在学校的悲惨遭遇。屋漏偏逢连夜雨，此时，一只罪恶的黑手伸向了超人学校……©豆瓣', '迈克尔·安格拉诺', '迈克·米切尔', 6.3, 22332, 'tt0405325', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199305406.jpg', 2, 14, 57.7, 20.4, 6, '0.295872,-0.374276,-0.168468,0.052722,-0.414633,-0.086600,0.373323,0.301503,-0.332546,-0.105738,0.337006,0.483322,-0.211852,0.156207,0.373155,-0.086284,-0.254342,-0.601541,-0.164399,0.064830,-0.191842,-0.426384,-0.177552,-0.113593,0.078329,-0.418702,0.571364,-0.307826,-0.386826,0.214556,0.224328,0.302289,0.174087,0.132362,-0.068326,-0.102632,0.143779,-0.150876,0.203328,0.248047,-0.212322,-0.049123,0.046288,0.027840,0.276770,0.039353,0.782428,-0.081033,0.167391,-0.030234,0.365041,-0.352477,-0.145320,0.054760,0.465362,-0.163641,0.129137,0.276006,0.422767,-0.086954,-0.065323,-0.245845,-0.887144,0.105189,0.137638,0.045934,-0.541264,0.376640,-0.149930,0.220838,0.380099,-0.339740,0.034102,0.328732,-0.038674,0.463913,-0.070143,-0.122077,-0.396414,0.496037,0.494722,-0.039669,-0.101004,0.140589,0.066548,-0.588481,-0.217163,-0.162512,-0.550015,0.030559,0.484888,-0.040669,-0.064342,0.225973,-0.515767,-0.059281,-0.075960,-0.284873,-0.122806,-0.269147,0.122001,-0.658016,0.329278,0.068771,-0.485791,0.032579,0.039290,-0.313219,0.789369,-0.968410,0.222648,0.580100,-0.023307,-0.501797,0.578179,-0.147311,0.189140,-0.107319,-0.200966,0.316687,0.258819,0.600680,0.336437,0.585388,-0.042776,-0.484704,-0.259891,0.349674', '1420088', '1793491', '4127270', '3044878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422917', '暴力史', '剧情', '暴力对于生活的秩序，对于各种不同处境的人，如何在亦正亦邪的界限徘徊？汤姆（维果·莫特森 Viggo Mortensen饰）是小镇上再平凡不过的一家之主，开着一间小店谋生。某日遇上前来抢劫的歹徒，为了保住伙计的生命，汤姆奋而干掉了这帮不速之客，他的英勇神武成为了人们津津乐道的话题。媒体对此事的报道，也把汤姆一家赤裸裸地放置在公众视线里。这件事到底是改变了原本的汤姆，还是让汤姆回到本来的自己，这个谁也说不清——因为，汤姆的过往随之而渐渐浮出水面。黑道老大带着手下找上门来，这意味着汤姆将不能再隐藏自己曾经跟暴力亲密接触过的身份。妻子艾迪（玛丽亚·贝罗 Maria Bello饰）得知丈夫的秘密，非常生气；更糟糕的是，汤姆看到暴力的阴霾正渐渐笼罩上自己的儿子；暴力又一次彻底地潜入本来风平浪静的生活。©豆瓣', '维果·莫腾森', '大卫·柯南伯格', 7.5, 25155, 'tt0399146', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1689185157.jpg', 0.6, 3.5, 32.3, 49.3, 14.4, '0.509129,-0.023074,-0.553154,0.492476,-0.289430,-0.177513,0.831854,0.083073,-0.672407,-0.257727,0.329326,0.700839,-0.166670,0.270378,0.285640,-0.046885,-0.391986,-0.670721,0.042836,-0.109691,-0.139093,-0.518578,-0.415742,-0.380788,-0.031669,-0.185971,0.585612,0.201657,-0.304686,0.156452,0.373317,0.365953,-0.041698,0.528110,-0.220540,-0.124773,-0.133025,-0.105421,-0.189736,0.080049,0.118708,-0.324483,-0.086285,0.224366,0.053644,0.399723,0.723759,-0.377954,-0.322106,0.156479,0.363732,-0.362997,-0.195625,0.225856,0.085632,-0.111104,0.114443,0.220134,-0.159479,-0.162670,-0.065086,0.129096,-0.682728,0.172335,-0.038761,0.268871,-0.460092,0.293840,-0.076172,-0.089459,0.109045,-0.280851,0.218216,0.289939,0.215989,0.278532,-0.136400,0.218754,-0.411393,-0.165489,0.826672,0.105259,-0.037725,0.354005,-0.297352,-0.174447,-0.058280,-0.328001,-0.419018,-0.131661,0.187410,0.056644,-0.127125,0.492897,-0.637825,-0.043904,-0.184998,-0.239462,0.155552,-0.329103,-0.082248,-0.419751,-0.285643,-0.454535,-0.304150,-0.044205,0.063051,-0.212478,0.664125,-0.853755,0.144023,0.500459,0.231135,-0.582387,0.574590,0.185015,0.172471,-0.142601,-0.316929,0.170647,0.246835,0.471416,-0.038033,0.327008,0.131786,-0.281953,-0.114175,0.532979', '1308755', '1301022', '25721544', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422920', '黑夜传说2：进化', '动作', '狼人和吸血鬼之间的大战还在继续。当麦克尔（斯科特•斯比德曼 Scott Speedman 饰）和西丽妮（凯特•贝金赛尔 Kate Beckinsale 饰）还在企图以自己薄弱的能力阻止这场大战时，阴谋家们的杰作又诞生了――狼人和吸血鬼融合的具有超强能力的种族――“血族”。马克思（托尼•库兰 Tony Curran 饰）便是便是这个种族的第二代。他杀死了父亲，夺取了密钥和西丽妮的记忆，救出了一个是狼人、一个是吸血鬼的被囚禁千年的孪生兄弟，企图一统狼人、吸血鬼和人类三大种族。麦克尔和西丽妮这对恋人为了爱，他们必须挫败马克思的阴谋、打败囚禁千年的孪生兄弟……©豆瓣', '凯特·贝金赛尔', '伦·怀斯曼', 7.4, 70660, 'tt0401855', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1660344450.jpg', 0.4, 3.6, 37.3, 44.4, 14.4, '0.160770,-0.002136,-0.578891,0.813782,-0.087341,-0.275429,0.754968,-0.160588,-0.327963,-0.280029,0.072165,0.952743,0.003416,-0.001442,0.274637,-0.007266,-0.314700,-0.687691,0.013277,0.020235,-0.395801,-0.429899,-0.731598,-0.388994,0.156909,-0.680847,0.675949,-0.140247,-0.463418,0.323678,0.234402,0.410654,-0.353338,0.104778,-0.287821,0.061464,0.028941,-0.234757,-0.357473,0.161308,-0.162291,0.172753,-0.082208,0.233531,-0.242120,0.203274,0.440683,-0.781756,0.281230,-0.450792,-0.092378,-0.544032,-0.123289,0.367520,0.476114,-0.467185,0.216930,0.452969,0.243489,-0.175366,0.290553,-0.091718,-1.342142,-0.201736,-0.080304,0.117122,-0.474662,0.612462,0.078666,0.011740,0.371440,-0.091788,0.064873,0.546595,0.133033,0.586814,0.003157,-0.348119,-0.719132,-0.080420,0.624396,-0.103824,-0.440859,0.127908,-0.015247,-0.668417,-0.489439,-0.468054,-0.312468,-0.096244,0.549791,0.076279,-0.161795,0.653629,-1.098547,-0.101454,-0.414014,0.034419,0.104191,-0.388561,0.184361,-0.546724,-0.344315,-0.556622,-0.213049,0.167436,0.175111,-0.325432,0.876644,-0.989093,0.189120,0.574679,0.659093,-0.411593,0.680929,0.197716,0.046662,-0.293486,-0.204032,0.301128,0.250775,0.174740,0.190148,0.306052,0.365843,0.117800,-0.340147,0.547769', '1793491', '3769423', '1308585', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422922', '与歌同行', '剧情', '约翰·卡什（杰昆·菲尼克斯 Joaquin Phoenix 饰）本是个阿肯色州乡村小子，儿时一场意外令他弟弟身故，从此他便活在父亲（罗伯特·帕特里克 Robert Patrick 饰）的谴责和嘲讽下无力翻身。爱音乐的他慢慢以乡村歌手成名，也有了自己的家庭，但外出巡演时偶然接触到毒品慢慢令他不能自拔，将他带入深渊。吸毒令妻子薇薇安（詹妮弗·古德温 Ginnifer Goodwin 饰）带着孩子离开了他，他只好去找心仪已久、但因婚姻在身无法在一起的女歌手琼·卡特（莉丝·威瑟斯彭 Reese Witherspoon 饰），后者给予他援手，帮助他戒毒，却也一次次拒绝了他的求爱。戒毒成功的卡什得以重启事业，和卡特的爱情也在两人的舞台上终成正果。©豆瓣', '华金·菲尼克斯', '詹姆斯·曼高德', 7.7, 16236, 'tt0358273', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p813134114.jpg', 0.4, 2.4, 27.2, 50.2, 19.9, '0.008760,0.217013,-0.744184,0.589301,-0.146033,-0.411833,0.752790,0.255561,-0.413994,0.126793,0.151953,0.901723,-0.032956,0.231794,0.199653,0.151898,-0.346000,-0.780902,0.257360,0.116479,-0.276203,-0.337735,-0.116920,-0.169673,-0.192037,-0.306459,0.729027,0.015155,-0.126863,0.423132,0.287156,0.224875,0.117426,0.617400,-0.298677,0.274029,-0.046455,0.081866,-0.165402,0.228860,0.213521,-0.534652,-0.283672,0.249297,0.062576,0.317972,0.538352,-0.200429,0.048686,0.022001,0.173766,-0.265201,0.064153,0.184285,0.001967,-0.210340,0.065885,0.264347,-0.356608,-0.035134,0.256488,0.092451,-0.595954,0.125943,-0.143079,-0.018127,-0.637790,0.503030,-0.080715,0.107949,0.064139,-0.209061,-0.083052,0.299244,0.085108,0.198369,-0.383715,0.108517,-0.412626,0.378389,0.546858,0.149951,-0.170672,0.339305,-0.383820,-0.459538,-0.165764,-0.204904,-0.576626,-0.242040,0.620216,0.104787,-0.262912,0.174545,-0.506479,-0.239631,-0.327400,-0.010363,-0.161662,-0.399597,0.127687,-0.583225,-0.161110,-0.247803,-0.382848,-0.162571,0.092975,-0.519181,0.527111,-0.716698,0.253582,0.785051,0.249151,-0.399005,0.773626,0.182475,0.278274,-0.087110,-0.024716,0.604785,-0.101853,0.191729,0.335804,0.411547,0.104926,0.287844,-0.243475,0.580392', '30162520', '1309069', '34890458', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422925', '小鬼当家4', '喜剧', '《小鬼当家》是约翰.休斯1990年推出的假日强档节目。它不仅为广大电影爱好者带来了无限快乐，也使此片成了美国电影史上总票房排名第九的影片。这是美国有史以来拍得最好的喜剧片。两年之后，休斯编写导演的《小鬼当家》的续集《小鬼当街》，同样成为热卖的喜剧片。在这一集里，小鬼凯文的爸爸和妈妈离了婚，爸爸和一位新的女友搬到了新家。在他俩一起出去庆祝圣诞节的时候，那些可爱的匪徒又要来抢夺小朋友满怀希望的神秘装置，小鬼凯文再次抵挡这两个匪徒，不惜天翻地覆，引发连场刺激爆笑的场面。', '弗伦奇·斯图尔特', '罗德·丹尼尔', 6.8, 19217, 'tt0329200', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2237597347.jpg', 2.2, 9.1, 47.3, 28.3, 13.1, '-0.050656,-0.110569,-0.560491,0.391338,0.115964,-0.325698,0.575514,-0.064615,-0.202537,0.085539,0.272703,0.606852,-0.473069,0.408409,0.411453,0.133989,-0.319761,-0.547393,-0.142146,-0.150517,-0.118003,0.126668,-0.470425,-0.008501,0.000327,-0.270105,0.477166,-0.230294,-0.209274,0.313360,0.411081,0.051123,0.110565,0.130251,-0.094931,0.411346,0.060821,-0.152170,-0.429364,0.420674,0.078686,-0.208828,-0.195864,0.032937,0.061916,-0.009285,0.751353,-0.151491,0.019921,0.042887,0.718292,-0.239714,-0.483011,-0.112134,0.182405,0.035541,0.654839,-0.006283,-0.048658,0.025001,0.075256,-0.264720,-0.679102,0.233246,-0.019112,-0.029836,-0.370754,0.357765,-0.043558,0.147065,0.254253,-0.266036,0.177325,0.283605,0.176695,0.591626,-0.133210,0.112043,-0.277178,0.485996,0.666976,-0.145136,-0.031174,0.226337,-0.030342,-0.136253,0.008618,-0.567659,-0.623925,0.320743,0.437873,-0.360686,-0.046439,0.224867,-0.743707,0.015539,-0.132414,-0.332335,0.002261,-0.223647,-0.052243,-0.893548,-0.046703,-0.137786,0.085228,-0.177694,0.231417,-0.338609,0.826737,-0.558825,0.237819,0.577264,0.187120,-0.261563,0.566311,0.201177,0.031044,-0.024402,-0.097375,-0.409507,-0.042289,0.470161,0.225200,0.435859,0.112650,-0.323232,-0.288444,0.557807', '3318306', '5403927', '3811356', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422927', '痴男怨女', '剧情', '根据王尔德的戏剧《温夫人的扇子》改编而成。艾琳夫人（Helen Hunt饰）是一朵美艳的交际花，她从容地周旋在各类男人间，享受着女神的尊贵待遇，也被他们的妻子视为洪水猛兽，在真正的名媛淑女中臭名昭著。受到30年代美国经济萧条的影响，艾琳来到意大利寻找新机遇，她的出现照例如同投入湖面的一块巨石，搅乱了众人原来的平静生活。其中便包括良家妇女梅格（Scarlett Johansson饰）和丈夫温德米尔，梅格对丈夫的出轨愤怒不已，她决心以其人之道还治其人之身，一场关乎爱情和道德的角力赛已然展开。©豆瓣', '海伦·亨特', '麦克·巴克', 8.1, 9264, 'tt0379306', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1089242126.jpg', 0.2, 1, 19.2, 51.4, 28.2, '0.427981,0.229169,-0.762408,0.701206,-0.151252,-0.029284,0.951365,0.315224,-0.352257,-0.054219,0.644408,0.781180,-0.310412,0.116381,0.499601,0.205552,-0.152376,-0.842905,-0.288272,0.116780,0.194438,-0.266638,-0.411615,-0.120614,-0.192468,-0.343324,0.444394,-0.022791,-0.166196,0.395858,0.177081,0.178994,-0.004917,0.429188,-0.094155,0.006977,-0.012226,0.114841,-0.472608,0.095502,0.029676,-0.200294,-0.090790,0.146929,-0.042998,0.054007,0.770613,-0.517650,0.155110,-0.034697,0.570983,-0.105129,0.116776,0.455178,0.331245,-0.042033,-0.097449,0.200419,-0.228135,-0.057802,0.410507,-0.261228,-0.550185,-0.249473,0.403238,0.432401,-0.393288,0.763278,-0.077872,-0.087689,-0.012615,-0.162492,0.148904,0.093069,0.265688,0.530642,-0.063268,0.011979,-0.434300,0.302640,0.366327,0.262535,-0.373428,0.169392,-0.572465,-0.332571,-0.060752,-0.354811,-0.566876,-0.459128,0.256249,-0.058355,-0.083771,0.604794,-0.748682,-0.002969,-0.221270,-0.155312,-0.070226,-0.466928,-0.261809,-0.666843,-0.173398,-0.641632,-0.122548,0.030743,0.061781,-0.332349,0.800445,-0.674260,0.191671,0.320972,0.071951,-0.349514,0.582279,0.027061,0.060379,-0.225787,-0.304113,0.442521,-0.095552,0.174379,-0.053864,0.345462,-0.076952,0.046103,-0.073773,0.560863', '1307146', '5029050', '24839498', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422938', '星河战队2：联邦英雄', '动作', '在虫族突袭布宜诺斯艾利斯之后，联邦军队发动反攻，在坦戈约里击溃虫族，并在P行星虏获虫族首领。在此之后，联邦军队乘胜追击，派大军杀向虫族隔离区。残酷的战斗没有止境，机动部队第6战队遭到虫族围攻，苦盼救援部队不得，眼看灭亡在即。关键时刻，第6战队首领夏普德将军（埃德·劳特 Ed Lauter 饰）与几名士兵吸引虫族，命令霍顿（Jason-Shane Scott 饰）、珊蒂余下的战士前往最近的祖鲁角哨站避难。此前，该哨站已经废止，所有人员全部死亡，只有一名中尉幸存。在这个隔绝之地，战士们进行最后的抵抗……本片为《星河舰队》的第一部续集，拍摄完毕后直接发行DVD。©豆瓣', '比利·布朗', '菲尔·蒂贝特', 5.4, 15437, 'tt0367093', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2128531690.jpg', 11.7, 29.2, 40.8, 12.5, 5.9, '-0.060925,0.172855,-0.800840,0.596527,0.445766,0.231889,0.483314,-0.096544,-0.133137,-0.141809,0.431095,0.281365,0.477961,-0.385353,0.421163,-0.620153,-0.455999,-0.493827,-0.455706,-0.146129,-0.452184,0.046162,-0.255888,-0.269175,0.334180,-0.745313,1.259287,0.258842,-0.208228,0.225383,0.097363,0.407263,-0.280653,0.476259,0.350264,-0.050296,0.476936,-0.794116,-0.484280,0.516456,-0.959513,0.153980,-0.214646,-0.173682,-0.071789,0.202188,0.827111,-0.629015,0.340205,-0.346390,-0.217518,-0.427083,0.065187,-0.077851,0.929139,-0.070925,-0.101153,0.003954,0.294605,0.455813,-0.489578,0.041104,-0.864442,-0.220620,-0.032493,0.092500,-0.449929,0.274814,-0.290285,0.546825,0.190500,-0.124996,0.019126,1.067141,0.028796,-0.097970,0.048934,0.110099,-0.485052,0.061965,0.739011,-0.431697,-0.363372,-0.451581,0.296100,-0.588940,-0.054943,-0.512997,-0.207151,-0.075849,0.093835,0.021962,0.355438,0.483576,-0.928122,0.165136,-0.443013,-0.706048,0.135516,-0.247327,-0.048758,-1.179851,0.286301,0.160764,-0.022048,0.627655,0.120008,0.530917,0.787332,-0.537273,0.269288,0.378724,0.431307,-0.622689,0.177678,0.145324,0.270347,0.063830,0.155464,0.415580,0.359365,0.925405,0.327613,0.113739,-0.224102,-0.509775,-0.157338,-0.056457', '2369613', '1300371', '1306809', '24746649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422947', '未竟一生', '剧情', '艾纳（罗伯特·雷德福 Robert Redford 饰）拥有一段伤感的过去，车祸夺走了儿子格里芬（Trevor Moss 饰）的性命，而这车祸的始作俑者不是别人，正是自己的儿媳简（詹妮弗·洛佩兹 Jennifer Lopez 饰）。愤怒的艾纳无法原谅简的过失，无奈之下，简只得带着腹中的胎儿远走高飞。如今的艾纳生活在怀俄明牧场里，除了放牧，他还担负起了照顾被熊所伤的老朋友米特（摩根·弗里曼 Morgan Freeman 饰）饮食起居的责任。曾经的悲伤未曾消逝，但一对老友相互扶持，生活倒也宁静祥和。琼的再度到来打破了这难得的宁静，同时到来的，还有11岁的艾纳的孙女格瑞芙（Becca Gardner 饰）。出于同情，艾纳收留了母女两，但往日的冤仇并未完全化解。同时，导致米特受伤的灰熊被捉拿归案等待处置。面对曾经的仇恨，两个老人会做出怎样的选择？©豆瓣', '罗伯特·雷德福', '拉斯·霍尔斯道姆', 7.8, 5773, 'tt0350261', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p808172073.jpg', 0.2, 1.7, 25.6, 50.9, 21.6, '0.122083,0.027699,-0.644753,0.472128,-0.169918,-0.579786,0.924322,0.268441,-0.522406,-0.405550,0.140165,0.561322,0.067434,0.336977,0.156879,-0.039082,-0.116597,-0.567116,-0.204539,0.080816,-0.201254,-0.496806,-0.135971,-0.157610,-0.110677,-0.320501,0.474940,0.114966,0.109993,0.495635,0.312649,0.550014,-0.191083,0.401107,-0.106350,0.128610,-0.210705,0.045650,-0.375584,-0.034553,0.115891,-0.245246,-0.068827,0.317874,0.105102,0.524401,0.719250,-0.389619,-0.108047,-0.220714,0.201854,-0.251751,0.160805,0.144433,0.106638,-0.067160,0.210188,0.327578,-0.334810,-0.084099,0.215487,-0.068265,-0.694552,0.235136,0.166254,0.202427,-0.681217,0.529868,0.003283,-0.189991,0.031583,-0.164571,0.244829,0.484035,0.202679,0.506016,-0.307000,0.155499,-0.528664,-0.121494,0.567755,-0.207937,-0.299396,0.342980,-0.552390,-0.220305,0.013420,-0.435845,-0.671015,0.065611,0.298164,0.235636,-0.097143,0.420231,-0.359331,-0.275617,-0.453379,0.009539,-0.163696,-0.547138,-0.043276,-0.445778,-0.073784,-0.553207,-0.447398,0.008769,0.198516,-0.221014,0.439966,-0.652464,0.336488,0.104935,0.181135,-0.401670,0.388872,0.298726,0.241968,-0.114377,-0.096505,0.603267,-0.021416,-0.061972,0.270359,-0.013118,0.016345,0.035015,-0.375210,0.514941', '1307748', '4301215', '26245360', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422948', '足球流氓', '剧情', '哈佛新闻系学生马特（Elijah Wood 饰）由于舍友在他的衣柜里藏毒，被校方开除，无助的马特无法联系远在喀布尔的父亲，只好打包投奔伦敦的姐姐。姐夫斯蒂夫态度很不友好，把马特塞给了弟弟皮特（Charlie Hunnam 饰），皮特是西汉姆联队球迷组织GSE的领袖，他很快让美国佬马特见识了英国球迷的热血，马特体内的懦弱伴随着他挥向敌对球迷的拳头消失了，皮特让他逐渐融入这充满啤酒跟暴力的环境。GSE成员包瓦为人极端，始终对马特怀有敌意，当他发现马特以及马特的父亲都与球迷组织最为厌恶的记者身份有关联时，不惜一切代价要驱逐马特。而此时，马特正惊奇的发现姐夫是GSE前任领袖，在酒馆外，一场球迷间的暴力冲突正在酝酿……©豆瓣', 'Elijah Wood', 'Lexi Alexander', 8, 7828, 'tt0385002', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1592044397.jpg', 0.6, 2, 20.2, 49, 28.3, '0.383328,-0.135131,-0.590617,0.507245,-0.280502,-0.205544,0.741186,0.273884,-0.812518,0.008452,0.209110,0.789420,-0.142474,0.017565,0.343086,-0.166723,-0.264802,-0.776015,-0.321244,-0.084510,-0.147205,-0.505303,-0.003480,-0.590739,0.011925,-0.466052,0.569523,0.061382,-0.288561,0.386797,0.239971,0.388950,0.160434,0.680972,0.043432,0.108338,0.220247,-0.213839,-0.262796,0.048999,0.237334,-0.146983,-0.028484,0.305517,0.067938,0.369756,0.678295,-0.123748,0.178633,-0.117254,0.270235,-0.288337,0.004446,0.199208,0.322860,0.035239,0.134868,-0.000636,0.132249,-0.244070,-0.201889,0.040205,-0.509292,0.194882,0.169606,0.127872,-0.587870,0.862263,-0.266076,0.172598,0.372419,-0.098814,0.049856,0.102939,-0.074107,0.270455,-0.026068,-0.177977,-0.321685,-0.026062,0.794298,-0.094498,0.025610,-0.000487,-0.785346,-0.394991,-0.149417,-0.143464,-0.552952,-0.169665,0.488013,-0.018900,0.081192,0.466358,-0.584656,-0.181915,0.018794,-0.248270,0.086596,-0.615587,-0.053383,-0.553171,-0.233481,-0.204776,0.123239,-0.066896,-0.109606,0.175833,0.858968,-0.931351,0.001658,0.630687,0.423318,-0.275523,0.632789,-0.104027,-0.137665,-0.346734,-0.284863,0.188673,0.112417,0.206181,0.281174,0.417586,0.151117,-0.260103,-0.120657,0.322056', '35030151', '25721544', '1308755', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422950', '豺狼计划', '悬疑', '“狼吃羊”的游戏有三条准则：一是避免怀疑；二是欺骗朋友；三是消灭朋友。欧文•马修斯(朱利安•莫里斯 饰)转到了西湖中学学习，在这里，他认识了新朋友，道喆(林迪•布斯饰)、急性子的汤姆(杰尔德•帕达勒基饰)等人。这些人都是一个“撒谎俱乐部”的成员，他们经常玩一个“狼吃羊”的游戏。这个游戏强调伪装与欺骗。一天，一名年轻女子在学校附近被杀害，警方无任何线索。“撒谎俱乐部”决定把这个故事演变成一个“校园怪谈”。他们在网络上发布假消息，虚构出一个绰号“恶狼”的变态杀人犯，并称“下一个被害者将是学校里的同学。”“撒谎俱乐部”的各位深深沉醉在编造谎言的快感之中，却不想谎言居然成真！同学一个个遭遇不幸。究竟“恶狼”是谁？©豆瓣', '朱利安·莫里斯', '杰夫·瓦德洛', 7.2, 38068, 'tt0384286', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p824370081.jpg', 0.8, 4.7, 38.9, 44.1, 11.4, '0.488739,-0.135514,-0.218083,0.588497,-0.355314,-0.036222,0.464525,-0.168058,-0.314980,-0.307071,0.131832,0.592692,-0.217385,0.313535,-0.027439,-0.153039,-0.220681,-0.548930,0.066777,-0.297203,-0.129147,-0.425336,-0.207666,-0.302936,0.013126,0.025675,0.378269,-0.136333,-0.251000,0.315044,0.364124,0.286504,-0.219326,0.189685,-0.017027,0.039394,0.342672,-0.033286,-0.048111,0.200645,-0.270571,0.112965,0.088280,0.196964,0.162540,0.244094,0.630175,-0.136883,-0.297321,-0.186224,0.360076,-0.404856,0.011057,-0.006848,0.409124,-0.330307,0.325872,0.177008,0.158366,-0.072817,-0.124597,0.057660,-0.759954,-0.104268,-0.011808,0.301000,-0.217006,0.257900,-0.115844,0.034304,-0.138765,-0.057721,0.239926,0.029250,0.450669,0.096609,0.156972,0.064762,-0.569935,0.225574,0.699081,-0.181236,-0.098202,0.009762,-0.083726,-0.121127,0.165061,0.008368,-0.294846,0.103888,0.116584,-0.367531,-0.369335,0.146020,-0.692392,-0.194151,-0.083463,-0.091951,0.131982,-0.455856,-0.208615,-0.492002,0.074606,0.008690,-0.313021,0.042665,0.153918,-0.303544,0.638807,-0.825006,0.082810,0.768337,0.257045,-0.451072,0.720741,0.019785,-0.042807,-0.083044,-0.051390,0.022539,0.557989,-0.078003,-0.013110,0.398687,0.066284,-0.166821,-0.362317,0.357947', '3785918', '1793491', '4301278', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422952', '千里走单骑', '剧情', '两对父子，隔膜与疏离，沟通与理解，都在他们人生中上演着。儿子健一(中井贵一饰)病危，却因与父子关系恶劣而拒绝与父亲最后的沟通。父亲高田(高仓健饰)却为了完成儿子的意愿，从日本赶往云南拍摄李加民唱的傩戏《千里走单骑》。千里迢迢终于赶到云南，高田艰难与当地居民沟通，得知李加民犯事入了狱。原来李加民也有着与他儿子的一段心酸往事，并因此被判了罪。高田千辛万苦找到狱中的李加民，请求他唱戏。怎料李加民听完高田与儿子的故事后，也想到了被自己抛弃的私生子，戏唱到一半，便泣不成声。高田决定回去找他的儿子前来探狱，路上二人相互谈心照顾，感情甚笃，然而儿子与李加民之间的感情冰层，却怎么也打不破。而正当李加民再次演唱的时候，高田接到电话，儿子已经含笑而死，并原谅了自己。©豆瓣', '高仓健', '张艺谋', 7.4, 52206, 'tt0437447', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p659660201.jpg', 0.5, 3.2, 37.4, 45.4, 13.4, '-0.121256,-0.040541,-0.624740,0.546124,0.123969,-0.498114,0.564750,0.109141,-0.489255,-0.250117,-0.085199,0.726429,-0.194319,0.307891,0.284711,-0.169349,-0.381090,-0.820863,0.151155,-0.050395,-0.157707,-0.551750,0.007709,-0.042171,-0.076955,-0.106961,0.457121,0.138024,-0.143235,0.572170,0.195948,0.148008,-0.466268,0.627936,0.032125,0.180279,-0.158232,0.339543,-0.439284,-0.095173,0.211453,-0.118156,-0.149428,0.108552,0.033707,0.604894,0.421893,-0.251734,-0.297628,-0.033416,0.018144,-0.286070,0.074278,0.303952,0.191161,0.115476,0.341720,0.497108,-0.323787,-0.125259,-0.077817,-0.012637,-0.461542,0.216602,-0.167645,-0.098592,-0.416436,0.361965,-0.010043,-0.194345,0.031022,-0.357222,0.339803,0.409339,0.264188,0.578971,-0.721755,-0.020268,-0.221935,0.025978,0.769856,-0.150044,0.118712,0.242757,0.135840,-0.379496,0.184150,-0.115580,-0.179890,0.051232,0.097883,0.285360,-0.201859,0.095047,-0.350268,-0.224240,-0.407735,0.158807,0.234942,-0.703197,0.263162,-0.390745,-0.136356,-0.203154,-0.434231,0.100181,0.293213,-0.250281,0.503383,-0.536954,0.123073,0.265970,0.494241,-0.629415,0.507440,0.318370,0.177795,-0.284384,0.196670,0.256976,0.117348,0.223858,0.349295,-0.042705,-0.119105,0.078252,-0.357715,0.237047', '1949320', '35461732', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422954', '吮拇指的人', '剧情', '每个人的青春期都或多或少的有过迷茫，躁动，愤怒和困惑。电影主人公贾斯汀（卢•泰勒•普奇 Lou Taylor Pucci饰）有着吮拇指的幼稚习惯。贾斯汀一直想要克服这个难缠的习惯，其实这个习惯只是一个青少年青春期困惑的一个缩影，其他的困惑还包括性和家庭等。在改变这个习惯的意愿下隐藏的，是贾斯汀对成长的不自觉的渴望。每个人成年人都可以在这部电影中找到自己曾经的影子，这个故事中的严肃，真挚，诙谐，都是那段青春时光不可抵抗的魅力。©豆瓣', '本杰明·布拉特', '迈克·米尔斯', 7.2, 7506, 'tt0318761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1563658637.jpg', 0.8, 5.3, 40.8, 40.9, 12.3, '0.566382,0.115977,-0.909806,0.825467,-0.340742,-0.071753,1.054546,-0.188041,-0.603063,-0.395077,-0.256851,0.425502,-0.253376,0.714568,0.039673,-0.054023,-0.104080,-0.734919,-0.428864,-0.026153,-0.262851,-0.533831,-0.553679,-0.404486,-0.202057,-0.279246,0.449933,0.332714,-0.356434,0.743881,0.658641,0.275521,-0.054805,0.642076,-0.059019,0.078203,-0.128236,-0.139117,0.080435,-0.366113,0.033230,-0.058207,0.149778,0.327593,0.056565,0.734658,0.462453,-0.034767,-0.429266,0.279217,0.318975,-0.165790,-0.412278,0.574599,0.127527,-0.046247,-0.119958,-0.267171,0.020647,0.250191,-0.385856,0.037005,-1.637430,-0.327818,0.255882,0.478498,-0.679285,0.392845,0.287076,-0.396162,-0.106551,-0.354619,0.126826,0.152538,0.546183,0.546793,-0.046634,0.110529,-0.276839,0.357194,0.688424,0.246294,-0.735878,0.468999,-0.952458,-0.469357,-0.386973,0.016281,-0.956110,0.058916,0.150913,0.059148,-0.191886,0.370562,-0.613667,0.121747,0.346215,-0.101937,-0.031338,-0.675824,0.042183,-0.413929,-0.288412,-1.132165,-0.473606,0.081963,0.060080,-0.426640,1.027636,-0.909460,0.288886,0.632241,0.196711,-0.486064,0.744229,0.463571,-0.046617,-0.129510,-0.208647,0.705022,-0.110671,-0.135730,-0.137386,0.575782,-0.029020,0.064417,-0.777214,0.644991', '1303077', '24284209', '1793491', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422957', '卡波特', '剧情', '电影重现了饱受争议的同性恋作家卡波特写作小说《In Cold Blood》的历程，深入到卡波特敏感而又残酷的内心世界。小说主角的原型是1959年美国一个凶残杀手佩里（克利夫顿·克林斯 Clifton Collins Jr.饰），他为了区区100美金而杀害了一家四口。敏感的卡波特（菲利普·塞默·霍夫曼 Philip Seymour Hoffman饰）嗅到了这桩新闻的写作价值，他得到了杂志社的帮助，前往案发地调查关于杀手的一切，一篇纪实文学在卡波特心里酝酿，而功成利就的欲望也在他内心翻滚。然而，当他和佩里展开长时间的访问接触，却发现眼前这个凶手和自己惊人的相似。佩里把卡波特视为知己，一次次把希望寄托在他身上。然而，在卡波特心里，佩里也只能让位于他的作品，他的名利。佩里沦为自己深信的人手中的一颗棋，而卡波特，也在作品成名后，终生无法为自己的残忍而释怀。', '菲利普·塞默·霍夫曼', '贝尼特·米勒', 7.9, 18041, 'tt0379725', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2454182493.jpg', 0.4, 2, 24, 51.6, 22, '0.383484,0.236230,-0.776623,0.966202,0.150598,-0.470900,0.907303,0.062003,-0.331304,-0.110282,0.262636,0.844488,-0.337386,0.247317,0.291031,0.256687,-0.207810,-0.869638,0.219401,-0.096168,-0.231365,-0.522179,-0.493357,-0.479920,-0.156224,-0.358865,0.494979,0.358416,-0.343173,0.142598,0.405360,0.489997,0.029885,0.258534,0.026898,0.011400,-0.046366,-0.277688,-0.176097,0.241409,0.269236,-0.189791,-0.099300,0.446491,0.117593,0.411415,0.750567,-0.242949,-0.304811,0.394507,0.499631,-0.421586,-0.105365,0.138858,-0.079232,0.051992,0.025406,0.105459,-0.217548,0.097220,-0.023590,0.029219,-1.219425,-0.151231,-0.137633,0.176733,-0.495873,0.658717,-0.463984,0.123643,-0.032331,-0.392260,0.002450,0.001034,0.218702,0.335332,-0.166267,-0.019008,-0.398592,0.306768,0.390833,-0.173052,-0.399038,0.271739,-0.273257,-0.498024,-0.077099,-0.292788,-0.472881,-0.036390,0.561584,0.161164,-0.222875,0.444309,-0.614327,0.023033,-0.538506,-0.219691,0.115095,-0.441993,-0.071318,-0.361550,-0.501308,-0.237469,-0.254156,-0.105845,0.122463,-0.593668,0.840161,-0.575671,0.361586,0.749232,0.088444,-0.068224,0.726614,0.153524,-0.085164,0.011348,-0.249862,0.475990,0.308310,0.284287,0.246825,0.043546,0.320350,-0.113889,-0.292595,0.849763', '3785918', '25932086', 