INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1422992', '简爱', '剧情', '本片根据英国作家据夏洛蒂·勃朗特同名原著改编。从小失去父母的简·爱（夏洛特·甘斯布 Charlotte Gainsbourg 饰）寄居在舅妈家，自幼受尽表兄欺辱和舅妈冷眼，稍大些后即被送入管教严格的教会女子学校。在冷漠、刻板环境中长大的简·爱并没有成为心理扭曲的女孩， 而是自立自强，还积累了不凡的学识修养，成年后她成为桑菲尔德贵族庄园的家庭教师。男主人罗切斯特先生（威廉·赫特 William Hurt 饰）个性暴燥，行事神秘。开始简并不喜欢这男主人，可随着二人慢慢熟悉，罗切斯特先生体会到简·爱的与众不同，并渐渐爱上她，简·爱亦受到罗切斯特先生的强烈吸引，但是大宅夜晚总会发生一些怪事，这个庄园中似乎隐藏着惊人的秘密…©豆瓣', '夏洛特·甘斯布', '佛朗哥·泽菲雷里', 8, 26130, 'tt0116684', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1590450816.jpg', 0.2, 1.8, 22.3, 50, 25.7, '0.266749,0.081956,-0.652094,0.588324,-0.244179,-0.343865,0.745705,0.140962,-0.596316,-0.545763,-0.125717,0.664636,-0.018463,0.424026,0.321796,0.245496,-0.051988,-0.374916,-0.207908,-0.067032,0.011516,-0.577501,-0.018816,-0.442117,-0.121551,-0.581711,0.312656,0.151647,-0.449808,0.301175,0.089164,0.435700,-0.216605,0.297179,-0.177920,0.048915,0.076751,0.099190,-0.252531,-0.082324,0.224448,0.127593,-0.002004,-0.048613,0.252206,0.157902,0.538935,-0.228833,-0.459528,-0.249804,0.475900,0.185948,-0.169108,0.100899,0.339949,-0.000490,0.146381,0.425099,0.016603,0.130143,-0.279354,-0.283261,-0.266403,-0.236999,0.448118,-0.095108,-0.312120,0.471685,0.001625,-0.337304,-0.136071,-0.195897,0.033000,-0.006297,0.209317,0.105160,0.010144,0.180925,-0.257702,0.109463,0.516476,0.194382,-0.491479,0.169248,-0.543380,-0.396007,0.210230,-0.395897,-0.721413,0.221498,0.103930,0.238682,-0.155550,0.415290,-0.090504,-0.125839,-0.083765,0.089199,0.196116,-0.632929,-0.199300,-0.571686,-0.424727,-0.678878,-0.030245,-0.014873,-0.234525,-0.279952,0.772539,-0.842295,0.551205,0.237206,0.259494,-0.398413,0.440682,-0.116257,-0.044428,-0.256903,-0.248085,0.607265,0.194187,-0.083883,-0.005506,0.087074,-0.085272,-0.037748,-0.319976,0.571813', '26348103', '3073073', '1292720', '1308635');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1423021', '食人狂魔', '剧情', '黄利辉（段奕宏 饰）曾经是一名怯于在战场上同日军搏杀的抗日战士，战争过去，中国大地又陷入了新的纷争。1946年，在家乡难以生存的利辉听从母亲的安排，带着她赠送的小刀，远赴泰国投奔亲戚。然而语言不通，又有哮喘病的利辉在雇主家没做多久，便因为老板娘的无礼愤而出走，利辉拖着虚弱的身体，在泰国工人的嘲笑戏弄中，做苦力谋生，异国女童的微小善意此时也成了他唯一的心灵慰藉，可昔日战场上的恐怖记忆萦绕在他心头，令他在睡梦中铸下大错……流落泰国乡间的利辉整日被几个孩子骚扰，终于，他心中的魔恣意爆发，令一切不可挽回……©豆瓣', '段奕宏', '布朗尼·拉齐塞邦', 7.5, 11183, 'tt0471977', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2565939453.jpg', 0.9, 3.9, 31.5, 45.3, 18.4, '0.141148,0.076133,-0.822350,0.566327,-0.095221,-0.208927,0.699422,0.091146,-0.494684,-0.085998,0.312212,0.691125,0.038232,0.245756,0.098486,0.000051,-0.018598,-0.703264,-0.268420,0.070431,-0.341290,-0.098537,-0.203048,-0.278499,-0.297786,-0.302789,0.557001,0.405815,-0.187212,0.351728,0.057408,0.179581,-0.001737,0.497772,-0.420634,0.044891,-0.165705,0.079045,-0.067180,-0.025045,0.219655,-0.524726,-0.310489,0.196889,-0.096387,0.421102,0.641902,-0.213744,-0.073615,0.000125,0.297276,-0.217322,0.049905,0.065567,0.162278,-0.018363,0.034764,0.115627,-0.271896,0.012733,0.107256,0.168985,-0.705408,0.072353,-0.088947,0.043254,-0.682339,0.606872,-0.025074,-0.115871,0.147903,-0.249267,0.177338,0.344314,-0.027154,0.433352,-0.308138,0.089493,-0.458750,0.404751,0.870576,-0.011693,-0.398925,0.011072,-0.302023,-0.330441,0.124741,-0.498250,-0.496501,-0.226920,0.147561,-0.040121,-0.462104,0.313878,-0.537321,0.107968,-0.202360,-0.247661,-0.004143,-0.245009,-0.230357,-0.366523,-0.319032,-0.451286,-0.225628,0.118927,0.306236,0.051753,0.736813,-0.724710,0.259093,0.709416,0.158529,-0.397385,0.556741,0.072712,0.134685,0.105596,0.015965,0.290844,-0.123706,0.461178,0.402696,0.229597,-0.163913,0.211353,-0.314450,0.400895', '1870682', '30162520', '25721544', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1423031', '星际宝贝2：史迪奇有问题', '喜剧', '在经历了种种波折和磨难之后，星际宝贝史迪奇（克里斯·桑德斯 Chris Sanders 配音）总算取得了“地球常住客”的身份，成为了莉洛（达科塔·范宁 Dakota Fanning 配音）家庭中的一份子。一年一度的草裙舞大赛即将拉开序幕，莉洛的妈妈曾经在比赛中夺得头筹，莉洛想要参加这届比赛，再现妈妈的风采。就在莉洛为了参加比赛努力训练之时，史迪奇的身体开始出现一些奇怪的征兆，这些征兆从小小的麻烦演变成为了大大的混乱，再发展下去，甚至有可能威胁到史迪奇的生命安全！为了保护心爱的家人，莉洛决定去寻找发明了史迪奇的博士贾巴（大卫·奥根·斯提尔斯 David Ogden Stiers 配音），这位聪敏智慧的博士能否解决史迪奇身上的麻烦呢？©豆瓣', '克里斯·桑德斯', '迈克尔·拉巴什', 8.1, 8730, 'tt0457993', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239566475.jpg', 0.5, 2, 22.8, 44.1, 30.7, '-0.040804,0.194820,-0.373020,0.251334,0.015287,-0.464450,0.160552,-0.093996,-0.291703,-0.321408,0.146456,0.648572,-0.179129,0.113997,0.366843,-0.178808,-0.215438,-0.599631,0.046257,-0.150333,-0.384413,-0.302073,-0.401179,0.027684,0.160348,-0.550016,0.640755,0.117176,-0.326221,0.597480,0.227619,0.112695,0.133707,0.247449,-0.010215,-0.148758,0.173949,0.268683,-0.492552,0.389411,-0.018810,-0.053265,-0.226740,0.030127,0.370016,0.100307,0.537808,-0.265501,-0.170173,-0.106940,0.439909,-0.101186,0.150525,0.243370,0.113497,0.295669,0.186038,0.271468,-0.093060,0.001653,0.056341,-0.419889,-0.938089,0.150868,0.020622,0.292866,-0.370648,0.172522,-0.027242,-0.157737,0.084337,-0.226509,0.351061,0.579138,0.342615,0.156680,-0.303189,0.297498,-0.148841,0.111063,0.708820,-0.418201,-0.096828,0.170513,0.288498,-0.233503,0.192514,-0.335824,-0.294642,0.248393,0.356776,0.015970,0.015500,0.348570,-0.595044,0.043036,-0.306774,-0.461125,0.076613,-0.171190,0.031755,-0.477214,-0.052643,0.117858,-0.203891,-0.174023,0.146932,-0.472423,0.896475,-0.870543,0.439924,0.565371,0.085171,-0.402191,0.273911,0.127606,0.317525,-0.242085,-0.087332,0.112255,-0.179201,0.264416,-0.276567,0.288453,0.289218,-0.289846,-0.403662,0.469915', '27602116', '24284209', '1793491', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1423035', '感染', '剧情', '某破旧医院，在改造过程中由于经费紧张而濒临倒闭，院长随后也下落不明。这里的医疗环境极其恶劣，为了节约经费竟然将用过的针头重复使用。病患得不到良好的照顾，医护人员和病人都处于焦躁不安的状态。在这种慌乱的情况下，医疗事故不可避免地发生了。一次抢救过程中，小护士安积圆（星野真里 饰）忙中出错将氯化钾当成氯化钙注入病人体内，最终致使病人死亡。经过一番激烈争论，参加抢救的鱼住大夫（高嶋政伸 饰）、秋叶大夫（佐藤浩市 饰）和护士们达成共识，决定将这起医疗事故隐瞒下来。一切看似从未发生，一切仿佛无人知晓。但这只是一系列恐怖事件的开始。此后不久，一种神秘致命病毒开始在濒临崩溃的医院内传播……©豆瓣', '佐藤浩市', '落合正幸', 7.1, 10512, 'tt0418778', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p990592243.jpg', 1.9, 8.2, 39, 36.4, 14.5, '0.133645,0.158789,-0.512152,-0.098896,0.074356,0.090615,0.795748,0.040257,-0.641558,-0.620674,0.490511,0.023167,-0.298471,0.103668,0.203312,-0.288145,-0.267946,-0.622646,-0.153934,0.273008,-0.613650,-0.396264,-0.245632,-0.165141,-0.139637,-0.497161,0.375067,0.250214,-0.220708,0.298477,-0.225576,0.526504,-0.135712,0.372610,0.213865,-0.216842,0.055711,-0.267942,-0.448561,0.284723,0.517583,-0.325396,-0.076227,0.263813,0.360430,0.460333,0.699992,-0.264942,-0.474056,0.006268,0.471614,-0.152894,-0.196770,0.210978,0.338704,0.424117,0.221668,0.093949,-0.500934,0.027308,0.172771,0.155356,-0.502391,-0.068954,0.076309,0.378496,-0.323521,0.324374,0.056495,0.086895,-0.101508,-0.387449,0.171966,0.320291,0.403688,0.396138,-0.434293,-0.152776,-0.395168,0.034326,0.706598,-0.246361,-0.486308,0.323744,-0.421358,-0.513367,-0.051770,-0.246514,-0.130767,0.144439,0.086343,0.322639,-0.488129,0.454425,-0.188222,0.003848,-0.411180,-0.475812,-0.231946,0.037073,-0.139452,-0.623749,-0.056932,-0.064853,-0.356244,-0.099678,-0.007731,-0.081171,0.486810,-0.602316,0.280403,0.295991,-0.046785,-0.353942,0.034418,0.011312,0.241964,-0.045858,-0.177720,0.050709,-0.027501,0.708427,0.277303,0.180848,-0.216516,0.168022,-0.406207,-0.002433', '1304665', '26235349', '4845723', '4023433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424218', '锅盖头', '剧情', '20世纪90年代初，中东战火一触即发，著名的“沙漠风暴”正在酝酿之中。20岁的小伙子安东尼·斯沃福德（杰克·吉伦哈尔 Jake Gyllenhaal 饰）出身于军人世家，他的祖父父亲、叔父是历次战场上走下来的英雄。安东尼从小耳濡目染，立志成为一名在战场上立下莫大功勋的光荣军人。经过无数残酷训练，他终于被派往海军陆战队第七陆战远征旅第二营，正式投身中东战场。安东尼踌躇满志，却发现战争的残酷远远出乎他的意料。在此期间，家乡的女友不忠出轨，恐惧、空虚、压抑则时刻折磨他的神经，战争的真正意义更令他陷入沉思与矛盾之中……本片根据前美国海军陆战队队员安东尼·斯沃福德（Anthony Swofford）2003年的畅销书改编，并荣获2005年圣地亚哥影评人协会特别奖。©豆瓣', '杰克·吉伦哈尔', '萨姆·门德斯', 7.5, 31727, 'tt0418763', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1084788534.jpg', 0.4, 2.8, 33.1, 48.7, 15.1, '-0.000424,0.070859,-0.769722,0.495671,0.351880,-0.200763,0.479464,-0.126431,-0.736795,-0.241843,0.283626,0.731225,0.043908,0.075540,0.429860,-0.299836,-0.329072,-0.864870,-0.496982,-0.109137,-0.073005,-0.206957,-0.409476,0.037690,-0.184716,-0.394251,0.999714,0.182338,-0.205810,0.543265,0.212544,0.449724,0.213704,0.454149,0.121069,-0.051626,0.517128,-0.052084,-0.535473,-0.181968,-0.292138,-0.215004,-0.181405,0.047423,0.089934,0.086594,0.661762,-0.341497,0.218234,-0.310499,0.290082,-0.139325,-0.332689,-0.107014,0.586254,0.199239,-0.021771,0.303946,0.361998,0.135381,-0.452881,-0.272574,-0.506867,-0.201237,0.064366,0.003464,-0.490537,0.646247,-0.121011,0.199961,-0.053126,-0.028156,0.134440,0.462003,0.266705,0.301786,-0.206121,0.050938,-0.002771,0.380680,0.810963,-0.120325,-0.401115,-0.146672,-0.295542,-0.476798,0.105515,-0.646873,-0.504496,0.049841,0.188285,-0.127563,-0.020893,0.521203,-0.423755,0.152592,-0.264002,-0.277605,0.006769,-0.129632,-0.160132,-0.543040,-0.293965,-0.447234,-0.241801,0.047814,-0.009437,0.036896,0.638965,-0.565049,0.204636,0.308037,0.021030,-0.204364,0.422474,0.141273,0.075337,-0.445968,-0.019955,0.755745,-0.253384,0.305133,-0.157026,0.223795,-0.306686,-0.146515,-0.055277,0.546325', '1780122', '26615753', '4202326', '1482099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424334', '洞', '剧情', '1947年，法国康复监狱。在押犯克劳德（马克·米歇尔 Marc Michel饰）刚搬入11号牢房时，受到其他四位狱友的排挤，谨慎小心的马努（菲利普·雷罗伊 Philippe Leroy饰）、狡猾奸诈的罗蓝德（吉恩·克劳迪 Jean Keraudy饰）、凶悍强壮的吉奥（迈克尔·康斯坦丁 Michel Constantin饰）和心机深重的“阁下”（雷蒙德·缪涅尔 Raymond Meunier饰）。很快，彬彬有礼的克劳德获得了四人的认可与接纳，并让他加入到正在精心谋划的一场惊心动魄的越狱行动中。五人准备掘地三尺挖个地洞逃出去，然而此时克劳德却得到了获得自由的好消息。由法国犯罪片大师雅克·贝克执导的经典越狱片《洞》，堪称电影史上关于越狱题材最伟大的影片。这部雅克·贝克生前的最后一部作品，入围1960年第13届戛纳电影节金棕榈奖、荣获法国电影评论协会最佳影片奖、英国电影学院奖最佳外语片和最佳外国男演员提名、法国《电影手册》十大佳片之一等多项殊荣。', '马克·米歇尔', '雅克·贝克', 9.2, 46764, 'tt0054407', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2497389079.jpg', 0.2, 0.4, 4.3, 28.2, 67, '-0.150182,-0.013999,-0.569121,0.694194,0.359220,-0.201761,0.448966,-0.078126,-0.311308,-0.123742,0.088221,0.778701,-0.353551,-0.012518,0.419890,-0.052230,-0.652347,-0.523709,-0.300515,-0.261534,0.013477,-0.299514,-0.604642,0.012204,-0.148069,-0.496974,0.747620,0.001387,-0.223162,0.493599,0.582565,0.211441,0.118252,-0.189132,0.076944,0.034147,0.500462,-0.150323,-0.529328,0.466511,-0.089687,-0.158271,-0.395104,0.013660,0.219768,0.318141,0.458007,-0.247915,-0.086515,0.032508,0.663758,-0.324622,-0.089969,0.125961,0.235027,-0.010495,0.247106,0.383037,0.052150,0.271896,0.043375,-0.327155,-0.890293,-0.012651,0.283491,0.012046,-0.303489,0.219306,-0.240065,0.301522,-0.026203,-0.134208,-0.026222,0.103092,0.364700,0.061655,0.041316,0.183001,-0.313334,0.360295,0.267539,-0.163080,-0.322035,0.022725,0.172198,-0.748791,0.025571,-0.396115,-0.280502,0.106929,0.717486,-0.073267,0.298728,-0.078291,-0.480909,-0.114401,-0.250643,-0.397409,0.013092,-0.053820,0.173099,-1.083720,-0.011023,-0.057846,-0.062084,-0.220021,0.081482,-0.296392,0.652433,-0.151447,0.441620,0.268247,-0.020637,-0.293685,0.745719,0.031679,0.075052,-0.175129,-0.233649,0.279853,0.215029,-0.049240,-0.029417,0.418896,-0.046717,-0.598480,-0.367686,0.339200', '3318306', '26275494', '1293433', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424551', '大决战之淮海战役', '剧情', '1948年9—10月间，辽沈战役和济南战役相继胜利，标志着解放战争决定性转折点的到来。在此危急关头，蒋介石（赵恒多 饰）紧急调配旗下三个兵团17万人的优势兵力固守中原，同年11月，华东野战军向黄百韬（许还山 饰）兵团发动攻击，最大规模的淮海战役正式打响。地下党员何张防线的临场起义，为时间占下风的粟裕（谢伟才 饰）赢得战机，顺利切断了黄百韬的退路。在此之后，国共双方调兵遣将，各逞其能，中原战场顿时变成规模宏大、破坏力极强的巨大漩涡，淮海战役朝向令人始料未及的规模迅速扩大。这是一场决定中华民族命运的关键战役，势将永远载入史册……本片为中国共产党诞生七十周年纪念作品，是大决战三部曲的第二部。©豆瓣', '古月', '李俊', 8.8, 16691, 'tt0099339', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2529748124.jpg', 0.9, 1, 10.5, 31.8, 55.8, '-0.348548,0.247922,-0.795557,0.574397,0.543767,0.184593,0.144701,-0.109248,-0.115780,0.202787,0.409097,0.470231,0.023101,-0.517322,0.285152,-0.556633,0.056023,-0.931219,-0.223580,0.137680,-0.185848,-0.222086,-0.491701,0.023964,0.155123,-0.141697,1.006754,0.603800,-0.238976,0.354173,0.297188,0.101169,0.140333,0.306467,0.393494,-0.112934,-0.279005,-0.644256,-0.570563,0.296177,-0.539668,-0.270167,-0.427838,0.173837,-0.222301,0.148546,1.006906,-0.409140,-0.030677,-0.304683,0.380528,-0.420845,-0.174755,-0.095731,0.611102,0.247427,-0.022876,0.116643,-0.097463,0.124847,-0.276351,-0.414165,-0.739777,-0.022178,0.077197,-0.027396,-0.342412,0.561804,-0.101876,0.335211,0.157486,-0.324930,-0.100886,1.055701,0.383232,0.012390,-0.554569,0.126042,-0.223462,0.262184,0.420974,-0.215534,-0.459552,-0.166303,0.075848,-0.272154,-0.060578,-0.574138,0.183621,0.055719,0.141779,0.018059,0.606046,0.354234,-0.791354,0.045673,-0.326905,-0.314708,0.210856,-0.321801,0.077776,-0.648478,-0.363438,0.016363,-0.190033,0.426971,0.082540,0.072423,0.754436,-0.553313,-0.144778,0.195347,0.190163,-0.056194,0.318448,0.238996,0.195746,-0.219514,0.332540,0.183931,-0.409577,0.241210,0.020306,0.191726,-0.097051,-0.147261,0.047640,0.422416', '1424552', '26852888', '3074408', '35058077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424552', '大决战之辽沈战役', '剧情', '1945年8月，日本帝国主义宣布投降，饱经战乱之苦的中华民族在短暂的胜利喜悦过后，即将迎来决定民族命运的重要时刻。随着蒋介石（赵恒多 饰）撕毁停战协定，国共两党内战全面爆发。经过两年的正面对决，国共双方的差距逐渐缩小，战局终于迎来决定性的时刻。1948年初，毛泽东（古月 饰）、周恩来、任弼时等共产党重要领导人离开陕北根据地，与刘少奇、朱德率领的中央工作委员会在河北会合。经过一番审慎的考量与讨论，领导人们命令林彪（马绍信 饰）所率领的五十万东北野战军全面发起夺取东北辽沈战役。对东北去留举棋不定的蒋介石被迫应战，中华民族的命运之战拉开序幕……本片为中国共产党诞生七十周年纪念作品，是大决战三部曲的第一部。©豆瓣', '古月', '李俊', 9, 21030, 'tt0099338', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2461997775.jpg', 0.7, 0.8, 8.9, 28.2, 61.5, '-0.172174,0.206411,-0.937185,0.308110,0.482685,-0.020809,-0.084857,0.132488,-0.271607,0.037695,0.384251,0.565695,-0.153185,-0.238763,0.376747,-0.680358,-0.280533,-0.937211,-0.143380,0.219086,0.125122,-0.498701,-0.106720,-0.073401,-0.131861,-0.064119,1.066238,0.683508,-0.120577,0.467723,0.435056,0.191768,0.026461,0.374452,0.403008,-0.394184,0.167487,-0.264389,-1.035407,0.207164,-0.163858,-0.243685,-0.422708,0.205173,-0.093101,0.180002,0.674503,-0.595076,-0.051665,-0.224234,0.522757,-0.471650,-0.350172,0.136412,0.669989,0.521307,0.071095,0.630248,-0.045013,0.038186,-0.556748,-0.400617,-0.112923,-0.183732,0.103121,0.122876,-0.402354,0.749676,-0.002270,0.424591,0.404328,-0.324963,0.012997,1.350341,0.408229,0.355538,-0.229951,0.089006,0.054037,0.200101,0.626378,-0.348662,-0.297633,-0.315216,0.077346,-0.321226,0.155596,-0.430670,0.039872,-0.107858,0.050868,-0.078087,0.321379,0.429728,-0.823929,-0.015261,-0.342800,-0.546600,0.489440,-0.196417,0.191461,-0.734835,-0.467867,-0.257206,-0.084836,0.343424,0.160107,0.062920,0.850746,-0.599265,0.055690,0.059438,0.255504,-0.487316,0.203122,0.601936,0.227245,-0.576051,0.337247,0.493196,-0.342541,0.263310,-0.237717,-0.091961,-0.045430,0.159240,-0.034930,0.285478', '26852888', '1424551', '1316511', '3074408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424582', '红颜', '剧情', '四川某县城里，还在上中学的小云意外怀孕了，她和男孩同时被学校开除，对方远走他乡，小云只能独立承受来自社会家庭的压力和歧视。小云母亲（李克纯饰）是名小学老师，她告知小云，孩子在生下的当天就死了。十年后，小云（刘谊饰）成了县川剧团的当家花旦。一天，小云偶遇了一个十岁男孩小勇（黄兴绕饰），聪明调皮的男孩很快成了她的好朋友。小勇被云姐的美丽吸引，他每天追逐她，偷看她甚至保护她。一直被周围人歧视的小云在小勇身上找到了纯真的友谊和感动。就在此时，小云母亲却告诉小云一个让她震惊的秘密……©豆瓣', '刘谊', '李玉', 8, 13360, 'tt0477719', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1747654259.jpg', 0.4, 1.6, 20.9, 52.7, 24.5, '0.330982,0.120856,-0.798496,0.169006,-0.555779,-0.165612,0.589632,0.089137,-0.431489,0.139386,0.118231,0.668573,-0.090525,0.583247,-0.085220,0.351080,-0.148392,-0.776942,-0.075475,-0.137358,-0.334166,-0.298038,-0.074937,-0.097415,0.001997,-0.325400,0.260224,-0.125500,0.019141,0.555345,0.134140,-0.085160,-0.110558,0.674202,-0.334202,0.456889,0.105967,-0.007226,0.171629,0.122297,0.024738,-0.289060,0.075434,0.225131,-0.005551,0.368971,0.739800,0.110901,-0.249665,-0.144692,0.262286,-0.266688,-0.136324,0.121575,0.367186,-0.326593,0.387854,-0.022801,-0.378450,-0.102178,0.073359,0.112435,-0.455369,0.114247,0.336575,0.060318,-0.817874,0.677512,0.095925,-0.094375,0.221207,-0.451661,0.174490,0.172633,-0.220248,0.697762,-0.361904,0.254641,-0.375339,0.317308,0.692368,-0.236924,-0.228706,0.162666,-0.275956,-0.160373,0.058181,-0.168814,-0.647474,0.241214,0.350285,-0.111417,-0.526476,-0.004358,-0.408865,-0.230568,-0.205388,0.055316,-0.217592,-0.623851,-0.132976,-0.036091,-0.078030,-0.446287,-0.526247,-0.046063,-0.001424,-0.331091,0.971441,-0.828101,0.291901,0.648010,0.523218,-0.509438,0.658481,0.182821,0.140067,-0.105655,0.133375,0.112285,-0.185365,0.200133,0.286096,0.542088,-0.036040,0.065306,-0.352116,0.493352', '1292219', '5262027', '1308609', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424627', '乌鸦与麻雀', '剧情', '1948年冬，上海林森路仁康里23号的二层石库门老房。该房本属于报馆校对孔有文（魏鹤龄 饰），抗战时期被汉奸侯义伯（李天济 饰）霸占，孔由房主沦为房客。抗战后，侯摇身一变，成为南京国防部科长，每周六到上海“买进卖出”。除孔之外，小商贩萧老板（赵丹 饰）一家和中正第一中学教员华洁之（孙道临 饰）一家也是这里的房客。三家房客相聚商议，却不齐心，只得各谋出路。 华到学校求房，因不愿出卖朋友而拒绝了校长（李保罗 饰）的拉拢，不久便因罢教事件牵连被捕。华妻（上官云珠 饰）四处奔走无果，无奈向侯求助，侯却趁机勾引。 孔找房未果，无处可搬。侯买通流氓（章志直 饰），连打带砸。 萧向侯借高利贷“轧金子，顶房子”，先被众人围殴，随后金价上涨，鸡飞蛋打。 三家房客走投无路，终于团结起来与恶势力抗争。©豆瓣', '赵丹', '郑君里', 8.7, 9570, 'tt0042054', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2582290536.jpg', 0.1, 0.5, 7.9, 47.3, 44.1, '0.118708,-0.119147,-0.218194,0.082681,0.066454,-0.359315,0.454290,0.456097,-0.159427,-0.372798,0.015847,0.356946,-0.178660,0.352899,0.145641,-0.150200,0.008452,-0.406003,0.061266,-0.080006,-0.054735,-0.281570,0.132321,-0.324855,-0.091336,0.655408,0.312781,0.264373,-0.161359,0.317299,0.534613,0.275519,-0.086573,0.272824,0.091187,0.273005,0.140006,0.056882,-0.154653,-0.012695,-0.111409,-0.320547,-0.012040,-0.339282,0.458378,0.398327,0.358121,0.171557,0.179782,-0.274648,-0.009595,-0.013358,-0.080436,0.411159,0.585226,-0.015921,0.320950,0.050822,-0.240727,-0.325713,0.215909,0.089054,-0.097324,0.253639,0.440998,-0.184147,-0.313661,0.202031,-0.032758,0.290931,-0.269152,-0.139233,0.215635,0.372221,0.056227,0.255896,0.112599,0.002146,-0.327674,0.395961,0.250279,-0.169264,0.005103,-0.304229,0.232004,-0.074310,0.383543,-0.161062,-0.217353,-0.289800,0.232945,-0.058140,0.271849,-0.314964,-0.499704,-0.447248,-0.295660,0.156246,0.289841,-0.336542,0.150140,-0.594377,-0.017036,-0.067646,0.026951,0.178477,0.381808,0.082850,0.022600,-0.275155,-0.138980,0.004323,0.321477,-0.646208,0.467522,-0.166738,0.161131,-0.096412,0.320691,-0.242991,0.334339,0.526366,0.257021,0.031728,-0.240358,-0.353774,0.034360,-0.012257', '1307690', '25833539', '20472857', '5332621');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424629', '林家铺子', '剧情', '1931年“九一八”事变后的冬天，浙江某小镇也和全国各地一样，掀起了抵制日货的运动。镇上“林源记”老板的女儿林明秀（马薇 饰），因穿了一件日本面料的旗袍而受到同学的鄙视。她回到家中哭闹，责怪父亲尽卖些东洋货。此时林老板（谢添 饰） 也正为县党部勒令停售东洋货伤透脑筋。不得已他只好把东洋货冠以“国货”的标签出售。年关将至，正是讨债用钱的时候，各商铺纷纷以打折甩货来相互倾轧。“一.二八”沪战爆发的消息使林老板添了新的忧虑，因为他还欠着上海某商行的货款，此时上海客人（陈述 饰）来催债, 林老板只好跟钱庄借贷，然而钱庄非但不肯，反而要求他还清陈债，幸好伙计寿生从乡下收帐回来，才打发走了上海客人。而此时“林源记” 的竞争对手“裕昌祥” 放出了林老板准备携款逃走的谣言，小股东们纷纷上门讨要本钱，林老板只好求余会长（韩涛 饰）帮忙辟谣，余会长却借机提出让林的女儿做警察局长的姨太太，林老板闻言仨魂吓跑了俩魂半.......', '谢添', '水华', 8.3, 8683, 'tt0470423', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2315583740.jpg', 0.1, 0.4, 13.2, 55.5, 30.7, '0.059768,0.094346,-0.408058,0.212701,-0.018518,-0.634022,0.194962,0.464975,-0.421808,-0.271747,-0.164281,0.300824,-0.052265,0.365183,0.346364,-0.159367,-0.074845,-0.299391,-0.062188,-0.193582,-0.100220,-0.119026,0.319442,-0.541876,-0.333553,0.134716,-0.159789,0.325739,-0.328270,0.135442,0.662272,0.110914,0.086397,0.593988,-0.001863,0.070008,-0.046582,0.131847,-0.307863,0.171022,0.069134,-0.321372,-0.134910,-0.071160,0.601134,0.482954,0.477851,-0.040758,-0.162869,-0.181924,0.492149,-0.079790,0.151959,0.043810,0.481217,0.150430,0.234856,-0.138350,-0.491508,-0.112462,0.333712,-0.017752,-0.205009,0.083657,0.171223,-0.199160,-0.663987,0.122807,-0.060094,0.324942,-0.242156,-0.538044,0.382836,0.298944,-0.056519,-0.040697,0.081638,0.060226,-0.539142,0.442048,0.412259,0.205686,0.276493,-0.201433,-0.206110,-0.261973,0.236579,0.015425,-0.195182,-0.137559,0.327320,-0.097635,0.176224,-0.085454,-0.503285,-0.427501,-0.174051,-0.314372,0.182752,-0.226068,0.053770,-0.464988,0.078591,-0.205226,0.136136,0.261736,0.592099,0.333535,0.356401,-0.439799,-0.141412,0.364767,0.620016,-0.517235,0.347979,-0.287441,0.043186,-0.262607,-0.189948,-0.505776,0.169020,0.567319,0.355614,0.169504,-0.111790,-0.403615,0.203581,0.174683', '1754628', '1303485', '1966121', '1422909');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424630', '红色娘子军', '战争', '海南贫家女吴琼花（祝希娟）被残暴的恶霸南霸天活活打个半死昏倒在地，幸得装扮成华侨富商的红军干部洪常青（王心刚）和他手下的及时相救，她才保全性命。伤好后，吴琼花立志投身革命，如愿以偿成为一员娘子军战士。南霸天的寿辰日，洪常青混在众人中来到南府向他贺寿，见来者一身华侨富商打扮并奉上贵重寿礼，南霸天没对洪常青起任何疑心。夜深，吴琼花带领一名女战士化装成丫头潜入南府，准备见机和洪常青以及外面的同志配合一举拿下南霸天，但关键时刻，对南霸天恨之入骨的吴琼花贸然采取了行动。©豆瓣', '祝希娟', '谢晋', 7.3, 10431, 'tt0472622', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2044374611.jpg', 1.6, 3.2, 36.7, 43.1, 15.4, '-0.183469,0.032579,-0.391091,0.351843,-0.213375,-0.455812,0.233404,0.030541,-0.504725,-0.256536,0.195562,0.272769,-0.215022,0.072009,0.597267,-0.349012,-0.121310,-0.493654,-0.303033,0.154567,-0.276062,-0.074605,-0.007541,-0.280657,-0.216018,0.238187,0.355903,0.008832,-0.237989,0.709457,0.389444,0.316654,-0.133229,0.419296,-0.078527,0.148137,0.037494,-0.398488,-0.556808,0.215693,-0.095799,-0.607247,-0.213348,-0.042085,0.036759,0.254145,0.274823,-0.209330,-0.081841,-0.388018,0.271681,-0.219786,0.248250,0.281261,0.633624,0.033943,-0.243721,-0.159648,-0.094399,0.233906,-0.163126,-0.421499,-0.251309,0.284663,0.275986,-0.256671,-0.781442,-0.029735,0.164177,0.317481,-0.079124,-0.294493,0.296414,0.235467,-0.037591,0.022898,-0.000098,0.228093,-0.677825,0.181658,0.518147,0.075097,0.265009,-0.442797,0.249469,-0.351656,0.430325,0.057690,-0.136301,0.010607,0.469341,-0.319420,0.355628,-0.222610,-0.293364,-0.282122,-0.409263,0.069867,-0.075399,0.236312,-0.007427,-0.488415,0.080870,-0.167404,-0.130755,0.061439,0.140455,-0.011179,0.670842,-0.468708,0.048720,-0.075144,0.379352,-0.605861,0.173122,-0.115628,0.411384,-0.052675,-0.141438,-0.062651,0.522992,0.406728,0.558378,0.292372,-0.482989,-0.139851,0.225017,-0.190026', '1451563', '3227266', '1301283', '1474336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424631', '大李小李和老李', '剧情', '上海某肉联加工厂工会主席大李（刘侠声）是个热心人，却有个不雅的“气象台”绰号：他工作虽积极，身体却由于不运动十分糟糕，一到阴雨天就会腰酸腿疼，邻居只要见他手拿雨伞出门，效仿着准没错。车间主任老李（范哈哈）认为工作远比体育重要百倍，很是不满成日嚷嚷要在厂里搞种种体育活动的儿子小李（姚德冰）。厂里职工大力士（关宏达）自认力气大过天，对体育活动也是一脸不屑。小李和其他热爱体育的同事商量，决定选出一个体协主席带领大伙展开锻炼。老李听闻，和大力士一合计，有心推选大李做主席，一来不得罪儿子，二来体育活动很快就会有始无终。哪想大李竟然新官上任三把火，烧得老李很是尴尬。可是老李认死了体育无用，哪怕大李老婆、五个孩子的妈妈秀梅（昔日与他站在一条战线）积极投身锻炼，他也不为所动。©豆瓣', '刘侠声', '谢晋', 8.1, 6903, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2459539322.jpg', 0.2, 1.4, 18.9, 49.7, 29.8, '0.044519,-0.522014,-0.598097,0.203004,-0.248331,-0.327856,0.321777,0.176306,-0.440277,-0.274077,0.065759,0.314289,-0.243029,0.287716,-0.049970,-0.361906,-0.108326,-0.305023,-0.129174,0.353214,-0.179817,-0.385193,-0.014730,-0.218676,-0.383149,0.077855,0.108031,-0.216711,-0.175701,0.228422,0.367666,-0.132810,0.564317,0.306755,-0.279032,-0.264006,0.007806,0.128024,0.079052,-0.021219,0.326836,-0.129860,-0.214444,0.003322,0.550147,0.422339,0.159645,0.205850,-0.254790,-0.226523,0.236206,-0.286004,-0.066100,0.063224,0.534441,-0.019126,0.201137,-0.085124,-0.048464,-0.053804,-0.018037,-0.340997,-0.441695,0.232958,0.226055,-0.034854,-0.692700,0.226059,-0.000571,-0.117792,-0.082766,-0.494281,0.089421,0.312978,0.000847,0.430101,0.144879,0.208625,-0.347534,0.210037,0.542135,0.120663,-0.091953,0.220532,-0.151400,-0.272213,0.208208,-0.083346,-0.285632,-0.161557,-0.072258,-0.366156,0.096856,-0.038375,-0.108672,0.187011,0.183674,-0.149869,-0.015540,-0.342043,0.183609,-0.227944,0.168812,-0.227534,-0.054513,0.263862,0.228390,-0.139000,0.727921,-0.791841,-0.218868,0.021506,0.160854,-0.669022,0.551056,0.299840,0.059080,-0.436924,0.202723,-0.310063,0.028975,0.171363,0.304935,0.444136,0.108842,-0.590334,0.055736,0.137267', '1877596', '1307741', '1419416', '4739952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424633', '盲女72小时', '剧情', '阿香（叶玉卿 饰）从美国动完眼疾手术归来，暂时失去视力三天。丈夫Jack（陈友 饰）是心脏科医生，要去澳门开一个重要研讨会，遂留妻子与仆人阿梅独自在家。 阿梅出去买哮喘药时，神秘男子朱森（黄秋生 饰）在后院内借机与阿香搭讪，说自己是Jack的小学同学，天真的阿香于是请他入屋坐。 朱森坐了一会就告辞。天开始下雨，阿香小睡片刻就有人敲门，她以为是阿梅，却不料朱森又折了回来，说是叫不到出租车。 阿香于是让他换上自己丈夫的干净衣服，朱森告诉阿香自己是印刷工，与老婆感情本来很好，却不知为什么从某个日子开始老婆开始不让他碰。气急败坏的他越说越激动，阿香感到害怕，请他离开。惭愧的朱森再次告辞。 盲阿香摸索着到浴室洗澡，却不料朱森正在哪里等着她……©豆瓣', '叶玉卿', '陈荣照', 6.4, 11944, 'tt0104807', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204658638.jpg', 2.4, 11.9, 56, 22.9, 6.7, '0.199605,0.062450,-0.633352,0.045143,-0.331670,-0.500411,0.575616,0.229936,-0.295878,-0.344015,-0.057990,0.534716,-0.140615,0.470814,-0.025110,0.395711,-0.470815,-0.363545,0.336921,-0.073070,-0.509630,-0.035135,0.328154,-0.097465,-0.038478,-0.114297,-0.029465,-0.222949,-0.071593,0.306667,0.174153,-0.048326,0.091853,0.861940,-0.326796,0.208094,-0.209179,0.047203,-0.132951,0.242279,0.587479,-0.320641,-0.489633,0.056522,0.105934,0.126660,0.078200,0.123556,-0.107013,0.269576,0.186981,-0.223328,0.058400,0.051688,0.225767,-0.002699,0.068688,0.015071,-0.289958,0.126369,0.001398,0.214498,0.080087,0.432892,-0.262882,0.045962,-0.804654,0.175599,-0.365337,-0.022970,0.311131,-0.699721,0.258603,0.369512,-0.086549,0.358516,-0.070177,0.057314,-0.537179,0.092745,0.454515,0.092125,0.480426,0.427874,0.343886,-0.418759,0.322844,0.294243,-0.403390,-0.219033,0.218887,0.001825,-0.223846,-0.566180,-0.189009,-0.040416,-0.285894,-0.228091,0.030268,-0.220745,0.022324,0.026470,0.014063,-0.031676,-0.282938,0.112396,-0.051344,-0.148827,0.381194,-0.603918,0.265516,0.443425,0.327072,-0.661250,0.416068,0.129706,-0.135692,-0.066669,0.243021,-0.021494,-0.194595,0.439489,0.492258,0.563947,0.028533,0.091373,-0.345254,0.083047', '1303485', '1292286', '1305543', '1416301');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424661', '狼溪', '恐怖', '1999年，澳洲布鲁姆。澳洲男青年班恩（内森·菲利普斯 Nathan Phillips 饰）与两名英国女孩克莉斯（凯斯蒂·莫拉希 Kestie Morassi 饰）和莉兹（卡桑德拉·玛格拉斯 Cassandra Magrath 饰）驱车前往狼溪国家公园游玩。经过两天的旅程，汽车穿过荒凉的澳洲无人区终于到达了目的地。巨大的陨石坑带给三人的喜悦转瞬即逝，当三人想驾车返回时却发现汽车抛锚。深夜，一位好心人麦克（ John Jarratt 饰）出现，并答应带他们回自己的营地并且免费帮他们修车。麦克把三个年青人带到一座废弃的矿场里，三个在麦克爽朗的笑声里很快睡着了。莉兹醒来后，发现自己被关在一间仓库里，并且手脚都被绑了起来。莉兹挣脱绳索企图逃跑之时隔壁的房间里传来克利斯痛苦的叫喊声，克利斯正在遭受“好心人”麦克的虐待。此时班恩不知去往，莉兹必须设法救出克利斯。在澳洲中部远离人烟的矿场，三个年青人的美妙旅程竟然变成恐怖的梦魇……本片根据上个世纪末在澳大利亚休姆高速公路沿途发生的“背包族凶杀案”改编。', '约翰·贾瑞特', '克瑞格·麦克林恩', 5.9, 7372, 'tt0416315', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1467752743.jpg', 5.2, 21.9, 50.5, 15.9, 6.5, '0.194136,0.066342,-0.753174,0.223920,0.350431,-0.300501,0.941924,0.029233,-0.211957,-0.359022,0.159823,0.642697,-0.112538,0.377611,0.479121,0.205793,-0.588145,-0.451102,-0.024971,-0.310092,-0.422114,-0.415705,-0.301575,-0.162417,0.093363,-0.165286,0.172771,0.286215,0.066116,0.685123,0.008811,0.164398,-0.311383,0.361616,-0.278293,0.049717,0.319223,-0.050500,-0.100149,0.257946,-0.270512,-0.104860,-0.092918,-0.253180,0.221437,0.270605,0.760988,-0.124429,0.201901,0.116278,-0.026545,0.010097,-0.095407,0.052174,0.253823,-0.106717,0.015950,0.026548,-0.509074,0.152150,-0.022743,-0.271657,-0.234353,0.262477,-0.354532,0.061702,-0.466159,0.071254,-0.034631,0.114889,0.092813,-0.533499,0.247440,0.192759,0.015568,0.499191,-0.083051,0.218550,-0.417833,-0.429782,0.692933,-0.251836,-0.062078,0.057373,0.098354,-0.339713,0.059337,0.238184,-0.411938,-0.124109,0.453008,-0.115489,-0.203610,-0.026423,-0.637116,-0.115605,-0.638702,-0.424146,-0.088898,0.077457,-0.417860,-1.023888,0.112189,0.061091,-0.000044,0.314502,-0.235621,0.131724,0.220871,-0.380485,0.485104,0.424254,0.177341,-0.094587,0.414954,-0.295676,0.432050,-0.127843,-0.071807,0.499617,0.260312,0.524129,0.024626,