INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424743', '这个阿爸真爆炸', '喜剧', '任慕英（梁家辉 饰）是一个单亲爸爸，以教授钢琴来抚养女儿Ellen（蔡卓妍 饰）长大。可是女儿升上Band 5后就变得越来越不听话，令任慕英十分担心。Ellen一直觉得爸爸十分“娘娘腔”，觉得自己就算有什么麻烦，爸爸也是不可靠的人。Ellen的同学都误会了她的爸爸是个江湖高手——慕夜飞鹰，相继要求拜为师傅，此时Ellen才对爸爸改观。但任慕英被误以为是绝招的身手，不过是在照顾女儿的时候练出来的。女儿开始觉得爸爸老了，可她还是到处惹祸，更被慕夜飞鹰的仇家胁持，任慕英为了救回女儿，独自女儿被困的地方……©豆瓣', '梁家辉', '邱礼涛', 6.1, 5662, 'tt0405827', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2871641201.jpg', 3.5, 17.3, 56.4, 16.9, 5.9, '-0.112206,-0.599145,-0.479489,0.520818,-0.424093,-0.484752,0.449506,0.111884,-0.896029,-0.378655,0.176524,0.735788,0.154056,0.320144,0.038324,0.206954,-0.047999,-0.382869,0.165131,-0.230471,-0.168651,-0.444460,0.011883,-0.018621,-0.162787,-0.304204,0.277077,-0.208352,-0.053826,0.052710,0.362315,0.012208,0.309643,0.520105,-0.259832,0.070370,-0.308612,0.062276,0.063152,-0.058253,0.233905,-0.008862,-0.048416,0.064681,0.102817,0.134450,0.460673,0.123083,-0.290863,-0.321998,0.202992,-0.314590,-0.056636,0.037024,0.418558,-0.065445,0.571081,0.017613,-0.183502,-0.052389,-0.000413,0.025649,-0.524855,0.382763,0.575435,-0.080867,-0.751190,0.167119,-0.174063,-0.357274,0.026689,-0.556252,0.416111,0.154812,0.062366,0.488156,-0.394572,0.058137,-0.538815,-0.210297,0.638575,-0.109920,0.289784,0.323100,0.028953,-0.302163,0.250081,-0.388831,-0.654983,0.441306,-0.319282,-0.233376,-0.365129,0.153178,-0.204504,-0.055793,-0.086541,-0.046341,-0.252433,-0.686893,0.077840,0.368431,0.116827,-0.300630,-0.127347,-0.050043,-0.126491,-0.428840,0.951558,-1.026810,0.155242,0.216534,0.358417,-0.610713,0.619184,0.282534,-0.123517,-0.278788,0.009992,-0.203034,0.030980,-0.070693,0.212862,0.189846,0.299236,-0.445333,0.091668,0.244788', '1877596', '3445516', '6963575', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424746', '花魁杜十娘', '喜剧', '杜十娘（李嘉欣 饰）是城中有名的绝色佳丽，性格却孤傲清高，无数男人都垂涎其美色，十娘心中却只期盼找到一个真心爱护自己的人并从此离开这风月场所。直到杜十娘遇到了李甲（吴彦祖 饰），中意于李甲。穷酸秀才李甲愿意用钱赎回杜十娘的自由身。杜十娘由此跟随着李甲归家，途中李甲偶遇故交孙福，孙福是个富家子弟，平日就游手好闲贪恋美色，一见杜十娘便与李甲商量要用五千两白银换十娘。此时的李甲一边因为落榜很是失落，另一面散尽身边财物更是无言归家见父母，多番考虑后，竟同意了孙福的想法，两人达成交易。杜十娘知道这些勾当之后，心如死灰，怒沉百宝箱并投水自尽……©豆瓣', '李嘉欣', '杜国威', 5.5, 14037, 'tt0403306', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554024854.jpg', 8.2, 28.9, 47.2, 11.7, 4.1, '0.055875,0.071304,-0.401225,0.209701,-0.151388,-0.418594,0.689091,0.038928,-0.692151,-0.313732,0.091848,0.568884,-0.140097,0.232210,0.011584,0.108728,-0.154249,-0.509101,-0.209708,-0.365593,0.270055,-0.340489,-0.036798,-0.031194,-0.358449,0.035310,0.419578,0.039271,-0.033756,0.656544,0.692908,0.200901,-0.299076,0.552870,-0.161012,0.008626,-0.265026,0.264032,-0.370356,-0.164379,-0.117955,-0.059746,-0.331780,-0.132049,0.072310,0.175565,0.389583,0.009454,-0.209440,-0.129298,0.111379,0.102383,0.039987,0.224650,-0.001917,-0.152997,0.337107,0.072348,-0.264437,0.088120,0.103049,0.252018,-0.356156,-0.071153,0.182736,-0.034890,-0.369357,0.113166,-0.039165,-0.160614,-0.181783,-0.283548,0.030846,-0.102852,0.258973,0.235409,-0.146369,-0.076287,-0.409933,0.581673,0.430884,0.208359,0.121189,0.438011,-0.083300,-0.406664,0.333892,-0.188355,-0.310065,0.025158,0.094986,0.412126,0.111454,0.085892,-0.329847,0.037793,-0.231519,0.383570,0.011883,-0.342770,-0.099962,-0.238334,-0.279241,-0.315516,-0.447830,0.183032,0.301017,-0.101340,0.553833,-0.591816,-0.038300,0.338693,0.288051,-0.841409,0.414890,0.219238,0.002152,-0.123427,-0.060547,0.180435,0.064037,-0.124290,-0.190798,0.007075,-0.055592,-0.257957,-0.171331,0.359209', '1308206', '1293265', '1304091', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1424748', '第一次的亲密接触', '剧情', '正当网络开始风行的大学校园里，外型并不出众的痞子蔡（陈小春饰）对感情认真保守，但他在网络上又表现出热情自信的另一面，能言善道。好友阿泰（张震饰）在不断追逐异性中获得乐趣，颇有心得。后来痞子蔡在网上邂逅了代号为“轻舞飞扬”的女孩（马千珊饰），之前他从不敢奢望真爱会降临在自己身上。及时行乐的阿泰提醒他网络是虛幻的，劝他不要动情。身陷矛盾的痞子蔡还是选择了与“轻舞飞扬”相见，彼此倍感知心，然而世事难料……©豆瓣', '张震', '金国钊', 5.4, 5505, 'tt0355449', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870768867.jpg', 9.4, 27, 49.4, 10.7, 3.5, '0.469334,0.242863,-0.752495,0.601580,-0.197006,-0.107187,0.660852,-0.032295,-0.689432,0.173767,0.099128,0.425993,-0.348133,0.370091,0.101859,0.016580,-0.247133,-0.698526,0.101193,-0.079845,0.273006,-0.562182,-0.363613,-0.082620,-0.417899,-0.195344,0.550901,-0.040271,-0.405897,0.673081,0.312272,0.183900,-0.199839,0.751228,-0.227445,-0.048032,-0.176404,0.345816,-0.241703,-0.136777,0.298111,-0.399783,-0.217275,0.254015,0.066885,0.442817,0.677005,-0.170633,-0.280365,0.226122,0.477580,0.045189,0.030852,0.056228,0.249152,0.030001,0.300099,0.068084,0.205146,0.038174,-0.310505,0.104890,-0.494090,-0.003558,0.092227,0.253800,-0.479734,0.593204,-0.253518,-0.033337,0.097561,-0.141175,-0.033380,-0.112915,0.465884,0.166037,-0.114706,0.154729,-0.302845,0.120838,0.532160,0.485031,-0.250470,0.565865,-0.391383,-0.304235,-0.032169,-0.149699,-0.547899,-0.238475,0.178479,0.060761,-0.234870,0.131773,-0.581880,0.208762,0.011729,0.262802,-0.055185,-0.385126,-0.141873,-0.383653,-0.420761,-0.725650,-0.397165,-0.067152,0.033438,-0.469302,0.948500,-1.206566,-0.018995,0.455777,0.215659,-0.396087,0.742944,0.390021,-0.149588,-0.197609,-0.127077,0.164538,-0.261766,0.024237,0.080999,0.381585,-0.109715,-0.116123,-0.249513,0.425735', '35030151', '26354526', '3445516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1426819', '虫不知', '爱情', '少女小月（梁洛施 饰）拥有跟昆虫沟通的能力，后来她也认识了一众跟她一样有着超能力的朋友，他们都由一个青春永葆的姑姑（钟欣桐 饰）带领着。小月一直都暗恋比她大几岁的高原（陈柏霖 饰），她的小昆虫葛吱一直鼓励她出动表达爱意，小月也按着葛吱给她的方式接近高原，可是事与愿违，高原拒绝了她。十分生气的小月迁怒于葛吱，葛吱与它的昆虫朋友们都意想不到人类的复杂行为便就此失踪，小月也从此听不到了昆虫的话语。自然界忽然出现了大变化，姑姑召集所有拥有超能力的少年，寻找小昆虫们……©豆瓣', '梁洛施', '罗志良', 5.8, 12230, 'tt0470263', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2871627034.jpg', 5.9, 22.4, 52.1, 14.2, 5.4, '0.128384,-0.138961,-0.691970,0.740176,-0.283041,-0.014868,0.689307,-0.069683,-0.388686,-0.183655,0.112629,0.593396,-0.261792,0.347555,-0.188470,-0.155010,-0.283119,-0.461371,-0.026786,-0.093310,-0.252114,-0.262133,-0.257567,-0.103525,-0.157796,-0.150285,0.364777,-0.265565,-0.354502,0.455623,0.310711,-0.154785,0.029682,0.396937,-0.163947,0.075322,-0.192475,0.150360,0.001266,-0.253850,-0.042422,0.097656,-0.126464,-0.015135,-0.080359,0.235174,0.622306,-0.528216,-0.152923,-0.252366,0.066105,-0.222953,0.261684,0.086950,0.328299,0.021920,0.176836,-0.004694,-0.121766,0.105937,-0.026637,0.062806,-0.617254,0.385734,0.124242,0.268964,-0.494146,0.187180,0.207880,-0.106326,0.290029,-0.421679,0.010290,0.137199,-0.042972,0.341980,-0.254675,0.100466,-0.423151,0.133589,0.500628,0.012801,-0.362319,0.289115,-0.414750,-0.651969,-0.239148,-0.112580,-0.421384,0.040332,-0.065651,0.212772,-0.338594,0.374938,-0.665785,0.168974,0.027020,-0.198362,-0.013821,-0.483593,0.087242,-0.543334,-0.059489,-0.577725,-0.330826,0.198196,0.412890,-0.073949,1.110992,-0.719981,0.161200,0.284161,0.565683,-0.615239,0.457727,0.015440,-0.131696,-0.110968,-0.274910,0.303374,-0.147948,0.197668,0.258321,0.340825,0.168300,0.023768,-0.368620,0.309649', '26348103', '24284209', '27602116', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1426842', '恋情告急', '喜剧', '王启明（古天乐饰）是一个银行经理，毫无浪漫细胞的他竟然在情人节带着女友Annie（梁咏琪饰）排长队吃火锅，令女友十分生气，感情进入冰冻期。王启明在网上找到一个爱情顾问欧阳心结（蔡卓妍饰），希望能得到她的帮助，挽回与女友的爱情。当启明知道心结竟是个只有19岁重来没有谈过恋爱的女孩，对她的能力深感怀疑。这边厢Annie邂逅了两个有妇之夫，都是无法发展感情的人。接着她又遇到了一个商业大亨Victor（甄子丹饰），他有钱有学识，更向Annie求婚，Annie想到自己的男友，左右为难。启明知道自己的位置受到威胁，在心结的帮助下，寻找了自己的缺乏的东西，启明想到了当年的历任女友，才发觉了自己的错误。他与女友相约的期限到了，他们在大街上跳了一只舞后各自转身离去，难过的泪流满脸，双双决定回头看看。©豆瓣', '古天乐', '陈庆嘉', 5.9, 8111, 'tt0409016', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486582248.jpg', 3.9, 21.8, 55.8, 13.7, 4.8, '0.237544,0.018710,-0.799684,0.462303,-0.203187,-0.427739,0.759269,0.159209,-0.423296,-0.184797,0.371721,0.795591,-0.252349,0.261147,0.188757,-0.030067,-0.023164,-0.630394,0.207527,-0.109696,-0.210529,-0.375788,-0.276230,0.060425,-0.136922,-0.244143,0.581683,-0.112340,-0.177088,0.435836,0.397456,0.105763,0.233278,0.618357,-0.239028,0.286156,0.079011,0.265980,-0.467753,0.274546,0.165204,-0.129687,-0.114069,0.271203,-0.236252,0.340165,0.605052,-0.094434,-0.364127,0.124280,0.451014,-0.260406,-0.147683,0.215148,0.177598,-0.020780,0.058360,0.115148,-0.272061,-0.160783,0.323807,0.136460,-0.763920,0.001820,-0.003982,0.420142,-0.662899,0.429226,-0.319706,-0.286982,0.171937,-0.596411,0.305121,0.362638,0.128954,0.322075,-0.420497,-0.000349,-0.689694,0.253946,0.712551,0.219853,-0.020815,0.449843,-0.076670,-0.326295,-0.020733,0.025731,-0.466062,0.066774,0.197629,0.076035,-0.256115,-0.088219,-0.531307,0.080264,-0.156853,-0.062408,0.112607,-0.766954,-0.044568,-0.286608,-0.311720,-0.368963,-0.328735,-0.014028,0.118256,-0.499106,0.666634,-0.966926,-0.005474,0.480327,0.565739,-0.704437,0.877503,0.351856,-0.180024,-0.363552,-0.042768,0.179471,-0.282090,0.258740,0.077201,0.404527,0.049381,-0.133461,-0.355177,0.242354', '1302384', '2990737', '1296569', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1427038', '啤酒谋杀案', '爱情', '根据阿加莎·克里斯蒂同名小说《啤酒谋杀案》改编而成。14年前，画家艾米亚斯（Aidan Gillen饰）中毒身亡，妻子卡罗琳（Rachael Stirling饰）则以谋杀罪被判绞刑。14年后，他们的女儿路希找到大侦探波洛（David Suchet饰），恳请他调查这桩案件的真相——路希相信母亲绝不可能谋杀了父亲。事过境迁，一切罪证业已湮灭无踪，波洛找到了当初聚会上的其他5人：夫妇俩的密友菲利普和梅雷迪思、艾米亚斯的模特兼情妇埃尔莎、卡罗琳的妹妹安吉拉以及她的家庭教师塞西莉亚，请他们回忆案发当日的情形，并最终从他们各自的点滴回忆中揭开了这桩“啤酒谋杀案”的谜底。©豆瓣', '大卫·苏切', '保罗·安文', 8.6, 8306, 'tt0392952', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2219829130.jpg', 0.1, 0.4, 11.9, 45.9, 41.7, '0.276871,-0.149530,-0.284014,0.224175,0.159933,-0.370095,0.670228,0.046185,-0.619802,-0.437371,0.291751,0.860146,-0.137039,0.216368,0.408478,0.106672,-0.735283,-0.815906,0.062057,-0.406638,-0.218348,-0.633449,-0.161690,-0.219855,0.098492,0.108239,0.297193,-0.095542,0.136562,0.325161,0.112213,0.313777,-0.383694,0.036821,0.317995,0.297790,0.103894,0.023400,-0.375100,0.065122,0.161387,-0.215101,0.161060,-0.018515,0.089046,0.489873,0.566837,-0.448358,0.044727,-0.132434,0.295868,-0.237518,0.069227,0.248028,0.065513,0.059687,0.266374,0.488776,-0.199771,-0.478278,-0.074265,-0.024740,-0.494190,0.004037,0.196346,0.227716,-0.194942,0.241750,-0.480610,0.248514,0.083621,-0.292612,0.048390,0.286803,0.174919,0.253831,-0.195261,-0.186934,-0.386377,0.449098,0.178393,0.094210,-0.034005,0.105490,-0.259636,-0.293267,-0.115270,0.031844,-0.190125,0.420941,0.447398,0.150143,-0.078662,0.696671,-0.397038,-0.654313,-0.486941,0.029147,0.150154,-0.028503,-0.062721,-0.588796,-0.227731,0.041783,-0.281508,-0.481349,0.201601,-0.291269,0.397889,-0.511282,0.217574,0.443752,-0.082439,-0.407246,0.406197,0.055146,0.229145,-0.264775,0.012457,0.307400,0.182864,0.022629,-0.037307,0.170072,0.372948,-0.189386,-0.330815,0.113996', '3104794', '1293145', '1306915', '1298095');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1427266', '超时空要塞：可曾记得爱', '爱情', '在1999年，一艘外星宇宙战舰坠落到了地球，人们用了了十年的时间修复并取名为"MACROSS"。2009年，MACROSS要塞正在举办一场偶像歌星林明美（饭岛真理 配音）的演唱会，突然空袭警报响起，要塞开始了变形。战斗中，一条辉（长谷有洋 配音）驾驶着变形战斗救下一名少女，战机却由于速度过快撞进外层舱室。安定后，辉发现救得是林明美。俩人相识后，为使明美高兴，辉偷开教练机带着明美去兜风。敌人趁机出现，好在朋友这时挺身相救，经过一场混战，辉和早濑未沙（土井美加 配音）醒过来，发现在一个荒芜的星球上。他们了解到，五十万年前，一个叫"普罗多"的古代文明发展到顶盛时，已经可以借遗传密码无性繁殖后代，于是国家分裂为由男性组成的"杰特拉帝"和由女性组成的"赫而特兰帝"开始了长达数万年的战争。在战争中文明急剧衰退了，曾经伟大的文化被遗忘殆尽，退化成了只会战斗的种族，为了维护和平，他们将会采取怎样的行动……《超時空要塞》是1982至83年间播出的一部电视动画，本片在其基础上精简改编而成。', '长谷有洋', '石黑升', 8.9, 6679, 'tt0087660', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2544458848.jpg', 0.7, 0.9, 9.7, 31.2, 57.6, '-0.005620,0.339915,-0.687529,0.465652,0.267327,-0.129386,0.577086,-0.112517,-0.143609,-0.130867,0.167867,0.482712,-0.266062,0.081760,0.350217,-0.228987,-0.237555,-0.536316,-0.218680,-0.080574,-0.581882,-0.269755,-0.078742,-0.155055,-0.106205,-0.626363,0.717549,0.146865,-0.186738,0.290518,0.003157,0.138762,-0.073879,0.222196,-0.090707,-0.021197,-0.132916,-0.183077,-0.311425,0.232684,-0.314429,-0.265075,-0.054659,-0.059164,-0.234483,0.293455,0.810338,-0.283855,-0.018132,-0.195772,0.341791,-0.332229,-0.230555,-0.304598,0.603509,0.084258,-0.114523,-0.028105,-0.101851,0.126472,-0.187086,-0.147664,-0.593495,-0.049501,-0.119873,0.072690,-0.373305,0.460129,-0.004788,-0.060523,-0.067261,-0.232681,0.159037,0.538423,0.206794,0.368811,-0.160413,0.276572,-0.415351,0.238137,0.792696,-0.088525,-0.486321,0.449246,0.034653,-0.448483,-0.248481,-0.436011,-0.234814,-0.159302,0.303755,-0.159526,0.196301,0.243540,-0.814225,0.056096,-0.358295,-0.435995,0.171468,-0.178860,-0.143297,-0.520196,-0.133623,-0.210785,-0.059794,0.414792,-0.122496,-0.364539,0.804553,-0.722111,0.055770,0.475720,0.397605,-0.329210,0.479098,-0.238298,-0.023640,-0.249126,0.056374,0.192685,-0.045843,0.302606,