INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1427319', '偷穿高跟鞋', '剧情', '一对姐妹花。姐姐罗斯（托妮•科莱特 Toni Collette  饰）有点肥胖，朴实不晓打扮，律师的职业让她生性严谨保守，难以俘获男人的心，买回来的高跟鞋只敢收藏在家——正因为这样，她沉浸在爱情小说里。她的妹妹麦琪（卡梅隆•迪亚茨 Cameron Diaz 饰）则相反，虽然同穿一个码数的高跟鞋，麦琪却光艳照人得多，男人从来逃不过她的手掌。这天被后母赶出家门的麦琪投靠到姐姐门下，姐姐虽知麦琪任性，却也收留。不料麦琪竟然和自己的男友搭上。姐妹裂痕更深，二人形同陌路。麦琪流离失所，来到佛罗里达的祖母家。她和祖母素未谋面，却在那里得到了很多珍贵的提示，姐妹本是同根生……©豆瓣', '卡梅隆·迪亚兹', '柯蒂斯·汉森', 6.8, 17477, 'tt0388125', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p946550089.jpg', 0.7, 6.6, 50.8, 33.4, 8.5, '0.518536,0.017415,-0.770554,0.466053,-0.293591,-0.493047,0.741316,0.235762,-0.402517,-0.096349,0.221903,0.604890,-0.167556,0.332659,0.042917,0.381368,-0.158927,-0.342918,0.015168,-0.054003,-0.149616,-0.175277,-0.098626,0.047994,-0.195581,-0.223036,0.414815,-0.060970,-0.068035,0.358582,0.221083,0.063574,-0.024491,0.397949,-0.418421,0.168629,-0.102854,0.168753,-0.046943,0.022502,0.052700,0.024471,-0.161003,0.267112,0.044187,0.284431,0.490546,-0.235863,0.008103,-0.030243,0.487203,0.037755,0.050242,0.065547,0.132780,-0.137292,0.505384,0.004108,-0.121838,-0.010805,0.140545,-0.145036,-0.360528,0.281071,0.247070,0.124157,-0.721257,0.425830,-0.366933,-0.026844,-0.037315,-0.566896,0.057465,-0.018729,-0.175376,0.372041,-0.212719,0.068102,-0.548452,0.068317,0.449054,0.192607,0.103468,0.252796,-0.388237,-0.275362,0.148350,-0.232773,-0.716390,-0.099724,0.272621,-0.228273,-0.026695,0.154180,-0.402017,0.075283,-0.264617,0.121336,0.020253,-0.574750,-0.035940,-0.152674,0.055483,-0.640236,-0.498096,0.286715,0.206898,-0.253631,0.650885,-0.722312,0.215951,0.190026,0.324953,-0.444060,0.706410,0.266752,0.089308,-0.048990,-0.296182,0.248767,0.071337,-0.161050,0.198639,0.413086,-0.024028,-0.016754,-0.364496,0.333673', '1301221', '1302384', '1308047', '3796613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1427789', '假发', '剧情', '一场交通意外令智贤（柳善）变成哑巴，但性格开朗的她并没因此失掉对生活的信心。她的妹妹秀贤（蔡敏瑞）与她相反，因为癌症化疗失掉满头秀发，她十分阴郁消沉。某日智贤为秀贤买得一顶漂亮的假发，她以为秀贤会自此重拾活着的勇气。秀贤戴上后的确与之前判若两人，但还没能开朗起来，她的举止已与之前迥异，随后，一系列令人毛骨悚然的恐怖事件发生。原来，这顶假发里藏有一个含冤而死的女子的阴魂。©豆瓣', '蔡敏瑞', '元新渊', 6.1, 19149, 'tt0475590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p656378667.jpg', 2.7, 17.4, 58.3, 17, 4.5, '0.071868,0.054075,-0.714304,0.599742,-0.318283,-0.319217,1.066020,-0.054932,-0.531696,-0.233976,0.034710,0.621384,-0.238158,0.124529,0.265410,-0.102237,-0.365307,-0.610561,0.111467,0.085755,-0.193273,-0.299567,-0.396122,0.056042,-0.303194,-0.400355,0.548087,0.122323,-0.096892,0.750640,0.256117,-0.097052,0.160952,0.573147,-0.196167,-0.056611,-0.515899,0.328626,0.217612,-0.082970,0.483923,-0.159798,-0.038873,0.582942,-0.233458,0.455924,0.503115,-0.215936,-0.499403,-0.152944,0.477737,-0.112001,-0.081932,0.454821,-0.006840,0.097814,0.266683,-0.178556,-0.226772,-0.173825,0.366170,0.117314,-0.410055,0.329064,0.120689,0.085631,-0.162657,0.479516,-0.058271,0.052063,0.013481,-0.335921,0.106486,0.285057,0.544681,0.287267,-0.230137,-0.001723,-0.530129,0.187546,0.587202,0.102254,-0.471529,0.541547,-0.399750,-0.487911,-0.063239,-0.101613,-0.576521,0.340392,-0.131483,-0.148029,-0.153741,0.043938,-0.429926,0.065421,-0.301811,0.168354,-0.402988,-0.096985,-0.155182,-0.033262,-0.213129,-0.833370,-0.449476,-0.117702,0.130916,-0.292520,0.255613,-0.795172,0.199190,0.004145,0.060829,-0.407185,0.214743,0.051380,0.128671,-0.002013,-0.391398,0.280504,-0.113653,0.015907,0.152824,0.402855,-0.106492,-0.085418,-0.361170,0.460505', '2131640', '4275444', '21348112', '10484041');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1427834', '童梦奇缘', '剧情', '一夜长大恐怕是每个小孩的梦想，长大了就能自由自在。12岁的光仔更是比其他小孩都渴望长大，因为他的妈妈刚刚意外自杀身亡，爸爸找来了一个新妈妈。光仔吃惊地发现自此妈妈死后自己就不再长高，一切都是爸爸和新妈妈的错，光仔心里一直这么认为。一天，光仔在公园遇到了一个神秘人。神秘人自称有一种神奇药水，能让光仔一夜长大。光仔真的就一夜之间变成了一个20多岁的年轻人，光仔（刘德华 饰）终于梦想成真，终于能够摆脱爸爸和新妈妈了。兴奋不已的光仔开始追求他的梦中情人――学校老师Miss Lee（应采儿 饰）。没想到大人外表儿童内心的光仔很快就和Miss Lee打得火热，但是光仔却发现了一个大问题――自己现在一天长大10岁。©豆瓣', '刘德华', '陈德森', 6.5, 43668, 'tt0477898', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486824798.jpg', 1.3, 10.6, 55.7, 25.4, 6.9, '-0.029610,-0.148307,-0.472899,0.235415,-0.397170,-0.554951,0.596756,-0.173224,-0.741954,-0.425934,-0.021157,0.756638,-0.255128,0.739015,0.122552,0.180872,-0.206369,-0.549063,0.129631,-0.280342,-0.314508,-0.322977,-0.314406,-0.126558,0.021994,-0.211212,0.331909,-0.102400,0.254204,0.544146,0.197405,-0.104217,0.214938,0.323179,-0.332643,0.359300,0.145933,0.204593,0.025642,0.088017,0.076271,0.176442,0.104430,0.226118,-0.062174,0.043991,0.435862,-0.027817,-0.447334,-0.210344,0.305248,-0.040128,-0.314911,0.060117,0.320878,-0.067918,0.486078,0.017822,-0.182360,-0.024099,-0.169540,0.022154,-0.363701,0.058618,0.182005,-0.015866,-0.451835,0.202291,0.194091,-0.303348,0.254492,-0.609445,0.094998,0.235762,0.169722,0.818271,-0.354416,0.084298,-0.575363,0.133289,0.716313,-0.164287,-0.191565,0.540659,0.103748,-0.269804,0.026030,-0.135514,-0.574869,0.484881,-0.070467,0.039770,-0.520036,0.223396,-0.449658,0.321758,-0.290240,0.120586,-0.065772,-0.435958,-0.149201,0.111371,-0.083532,-0.210760,-0.177631,0.351114,-0.175813,-0.381262,1.037357,-0.883452,0.434725,0.245867,0.227594,-0.432260,0.410669,0.170812,-0.182245,-0.352182,0.303098,0.097729,-0.289762,0.108593,0.030918,0.230939,-0.116073,-0.086191,-0.355766,0.318598', '1292219', '1292720', '25738406', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1427947', '甲贺忍法帖', '剧情', '本片改编自日本作家山田风太郎的同名巨著《甲贺忍法帖》。于2005年9月在日本上映，总投资达15亿日元。1614年德川家康主宰天下期间，两个长久以来处于敌对的忍者村落——伊贺与甲贺，为了维护和平，二方祖先便订立了约定，互不往来但定期比武决胜负。两个忍者村落的个别继承人胧（仲间由纪惠 饰）与弦之介（小田切让 饰）在偶然不知彼此身分之下相遇认识，进而坠入情网，但悲惨的宿命却正等候着他们两人。德川为了确实掌握政权，于是展开政治密谋，挑起两边村落间的冲突与对立，进而消灭对方的种族。此时胧与弦之介将被迫成为敌人，两人必须背负起家族使命展开决斗……©豆瓣', '仲间由纪惠', '下山天', 6.7, 17006, 'tt0475723', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1039040009.jpg', 1.9, 10.1, 47.7, 30.3, 10, '0.098116,0.104870,-0.177309,0.402933,0.510630,-0.198664,0.322404,0.152343,-0.316092,-0.379124,0.172943,0.608254,0.058207,0.067563,0.243498,-0.382058,-0.173715,-1.041335,-0.238180,-0.252894,0.064334,-0.497899,-0.089725,-0.207541,-0.540864,-0.132011,1.093566,0.200123,-0.345290,0.329260,0.247742,0.352604,-0.571847,0.049222,0.048737,-0.335494,-0.013002,-0.079284,-0.799663,0.210996,-0.523591,-0.105577,-0.286960,0.032031,-0.038080,0.342774,0.702893,-0.653223,0.014144,-0.515454,0.092085,-0.042768,-0.234395,0.162854,0.586054,0.193290,0.204592,0.531406,0.002050,-0.130159,0.102746,0.061112,-0.473116,0.224779,0.162250,0.232524,-0.249301,0.586207,-0.038102,-0.130060,0.171218,-0.128382,0.065380,0.780144,0.721544,-0.098539,-0.458847,0.018749,-0.364022,-0.158913,0.852052,0.024889,0.002171,-0.155208,-0.103445,-0.522863,-0.516448,-0.299574,-0.126938,-0.355335,0.236737,-0.023192,0.284507,0.435668,-0.624524,-0.128042,0.031100,0.102983,0.413446,-0.482548,0.347867,-0.812902,-0.073216,-0.329093,-0.324934,0.414109,0.454726,-0.245695,0.690094,-0.808470,0.059830,0.454445,0.488607,-0.248166,0.467872,0.306004,0.131724,-0.278525,-0.175507,0.198841,0.110385,0.167268,0.206174,0.095224,-0.178131,0.339390,-0.100331,0.024293', '26615753', '30345227', '1780122', '26852888');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428051', '夺宝奇兵4', '动作', '19年后，印第安纳琼斯博士（Harrison Ford饰）再次启程，旨在将埃克托王国遗失的水晶骷髅头骨归还原地——传说中，归还圣物者将被赐予巨大力量。在琼斯的老友奥克斯发现水晶头骨前，这一切还只是传说。可奥克斯之后却不知何故丧失了心智，并落入苏联特工队的手中。为首的冷酷女间谍艾瑞娜（Cate Blanchett饰）深深着迷于所谓的神秘力量，她胁迫琼斯一行人与其共同前往亚马逊流域，找寻失落的黄金城埃克托王国。在秘鲁密林，琼斯等人和苏军展开酣畅淋漓的战斗，其间还伴随着沼泽、食人蚁、原始土著攻击等致命威胁，在他们历经千难万险，最终踏入密室的那一刻，世界上最奇异的景象出现了……©豆瓣', '哈里森·福特', '史蒂文·斯皮尔伯格', 7.2, 56056, 'tt0367882', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1703349212.jpg', 0.7, 4.7, 40.8, 40.4, 13.5, '0.011625,0.340806,-0.817071,0.486847,0.223702,-0.196708,0.872925,0.065476,-0.634169,-0.096075,0.141001,0.553315,-0.106768,-0.090217,0.199319,0.132211,-0.362366,-0.453590,-0.309443,-0.175804,-0.464588,-0.223051,-0.470625,-0.107817,-0.018186,-0.627701,0.549589,0.316716,-0.103237,0.401857,0.034604,0.382510,-0.255741,0.398246,-0.224327,-0.088951,0.212054,-0.119982,-0.471228,0.143372,-0.148842,-0.330805,-0.060539,0.252699,-0.251691,-0.020966,0.747871,-0.640314,0.287898,-0.260567,-0.015030,-0.458852,0.005723,0.135123,0.201748,-0.013352,0.005233,0.175924,-0.133640,-0.040946,0.163649,-0.170639,-0.631832,-0.053065,-0.025909,0.264928,-0.378307,0.432183,0.064268,0.097939,0.005774,-0.341042,0.239584,0.145303,0.327925,0.076374,-0.016725,-0.182915,-0.398604,-0.077147,0.306666,-0.340300,-0.379513,-0.015258,0.038090,-0.715093,-0.111873,-0.081782,-0.156988,-0.032306,0.513751,0.481248,-0.050048,0.329714,-0.852500,-0.000407,-0.423774,-0.282426,-0.030837,-0.385399,-0.365623,-0.572060,-0.166206,-0.122329,-0.350546,0.173733,0.051552,0.162354,0.451005,-0.397191,0.479539,0.536632,0.243348,0.104929,0.527195,-0.275065,0.014731,-0.136199,-0.131740,0.580315,0.368639,0.445058,0.137951,0.242872,-0.024664,0.233342,-0.309885,0.488973', '30336307', '21619567', '26309788', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428054', '惊声尖笑4', '喜剧', '经历了好友之死和几多悲惨恐怖的过去，辛蒂•坎贝尔（Anna Faris 饰）决心开始新的人生。她受聘来到一所闹鬼的房子里照顾一位行动不便的老妇人，笨手笨脚的辛蒂好心办坏事，使得老妇人灾难连连。而这座鬼屋也绝非徒有虚名，一个因被杀而冤魂不散的男孩不时出现，希望辛蒂帮他找到真正的凶手。在这所房子的旁边住着失败的父亲汤姆•瑞恩（Craig Bierko 饰），他正和一双儿女共度周末。一来二去的交谈过后，汤姆与辛蒂坠入爱河。就在此时，恐怖的外星人入侵地球，他们欲将人类彻底消灭。辛蒂和汤姆如何才能逃出生天？©豆瓣', '安娜·法瑞丝', '大卫·扎克', 6.7, 34003, 'tt0362120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1231156425.jpg', 1.9, 10.2, 48.6, 28, 11.2, '0.168636,0.000685,-0.717349,0.325067,-0.188708,-0.229391,1.143466,0.017042,-0.315945,-0.273486,0.226438,0.665424,-0.107162,0.468999,0.305739,-0.022371,-0.142984,-0.531454,-0.080192,-0.034927,-0.403438,-0.317935,-0.437449,-0.231861,0.096619,-0.108455,0.460566,0.289391,0.025239,0.392107,0.160359,0.413009,-0.254627,0.396220,-0.202820,0.087104,-0.066330,0.030914,-0.316189,0.189466,-0.001842,-0.137145,-0.057460,0.122308,-0.206783,0.139505,0.703856,-0.564266,-0.138172,-0.093333,0.301590,-0.369770,-0.041353,0.393878,0.097832,-0.014531,0.123140,0.170786,-0.217331,0.002406,0.104382,-0.205360,-0.700523,0.100429,0.035713,0.074043,-0.497912,0.429823,0.081878,-0.162919,0.014701,-0.315973,0.157342,0.344911,0.218775,0.588384,-0.284031,0.159452,-0.634397,0.065321,0.773577,-0.032549,0.080636,0.311402,0.050046,-0.298663,0.068302,-0.166073,-0.579293,0.048231,0.476191,-0.038307,-0.261104,0.269510,-0.583944,-0.087922,-0.487624,0.012328,-0.186152,-0.337636,-0.247228,-0.422769,-0.131088,-0.099914,-0.336003,0.060107,-0.011657,-0.384751,0.636285,-0.717580,0.246482,0.611411,0.335762,-0.357429,0.515390,-0.094470,0.453684,-0.079994,-0.065422,0.360207,0.134985,0.410487,0.259193,0.290572,-0.015850,0.078809,-0.365066,0.425101', '21619567', '3005387', '1296534', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428055', '罪恶之城2', '动作', '德怀特（乔什·布洛林 Josh Brolin 饰）是一名身材强壮的私家侦探，某日，他接到了前妻爱娃（爱娃·格林 Eva Green 饰）打来的电话约其见面，曾经，爱娃背叛了德怀特，嫁给了富有的商人达米安（马尔顿·索克斯 Marton Csokas 饰），这成为了德怀特心中永恒的伤痛，而如今，许久了无音讯的爱娃再度找到德怀特，究竟欲意何为呢？通过爱娃的叙述，德怀特得知她的生活并不美好，而一直紧紧跟随和监视着爱娃的司机马努特（丹尼斯·海斯伯特 Dennis Haysbert 饰）亦让爱娃显得更加楚楚可怜。忘记了曾经的伤痛，德怀特决定解救爱娃，他伙同曾经的好友马维（米基·洛克 Mickey Rourke 饰）一起前往达米安家，然而，等待着他们的却是爱娃亲手编织的重重陷阱。©豆瓣', '米基·洛克', '罗伯特·罗德里格兹', 6.9, 48306, 'tt0458481', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193680612.jpg', 1.2, 9, 46.6, 32.2, 11, '0.208098,-0.079973,-0.523020,0.598188,-0.042521,-0.656488,0.608691,0.132374,-0.481521,-0.410224,0.010943,0.564085,-0.052300,0.195538,0.347570,0.160226,-0.398597,-0.645344,-0.041391,-0.004360,-0.089323,-0.529756,-0.336098,-0.101339,0.241731,-0.418956,0.364135,-0.156537,0.183183,0.561896,0.410703,0.533493,-0.014647,0.248014,-0.035037,0.328466,0.181148,-0.096960,-0.320294,0.187505,0.120308,-0.110651,-0.010497,0.156126,0.063077,0.394838,0.261918,-0.320252,-0.051374,0.017772,0.272744,-0.243612,0.282710,-0.038009,-0.003833,-0.011999,0.063001,0.199523,-0.317161,0.128690,0.346782,-0.159518,-0.387435,0.287293,-0.033816,0.171936,-0.588171,0.227769,-0.345996,0.052387,-0.039293,-0.345755,0.252614,0.381134,0.048027,0.023074,-0.022768,0.033920,-0.420285,0.130659,0.461320,0.083327,0.182688,-0.088549,-0.230945,-0.197937,0.113591,-0.080617,-0.641901,0.051732,0.516785,0.335332,-0.060185,0.176503,-0.455212,-0.291651,-0.398434,0.055485,-0.099261,-0.478644,-0.066253,-0.644245,-0.242025,-0.399241,-0.216859,0.085687,-0.094556,-0.162123,0.236491,-0.748521,0.423773,0.337796,0.165670,-0.201993,0.351771,0.157463,0.038996,-0.143017,0.107003,0.704699,0.274543,0.024557,0.058205,0.173323,-0.003097,0.077755,-0.518532,0.566070', '2034997', '1945337', '26340522', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428068', '疯狂农庄', '喜剧', '农场里的小动物温顺乖巧。听话的小狗，可爱的小鸡，成群结队的绵羊，在农夫的细心照顾下，健康的生活着。可是，每当农夫不在的时候，他们就会突然站起来，疯狂玩闹。唱歌跳舞，喝啤酒，开Party，他们甚至会去模仿人类，捉弄人类。奶牛奥蒂斯（Otis）就是他们当中最捣蛋的一个，竟玩起了高山滑雪。奥蒂斯的父亲本（Ben）是小动物们的领袖，每天兢兢业业的为他们站岗放哨，保护小动物不受野狼的袭击。大家都敬畏并信任他。本一天天的变老，他希望儿子奥蒂斯能像自己一样，担起责任，保护好农场。可是奥蒂斯玩心太重，总是令本失望。一次，奥蒂斯为了一参加个Party，求父亲替他站岗。也就是这次，本为了保护小鸡，牺牲了自己。奥蒂斯深深地自责，一度灰心丧气。本在天上看着奥蒂斯，看着他努力去做好领袖，变成真正的男人……©豆瓣', '凯文·詹姆斯', '史蒂夫·欧德科克', 7, 11558, 'tt0414853', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1108753913.jpg', 1, 6.2, 45.7, 35, 12.1, '0.086902,-0.216003,-0.748952,0.398987,-0.557592,-0.101537,0.624249,0.127675,-0.308921,0.035461,0.297269,0.783094,0.253728,0.518750,-0.077679,0.037396,-0.456284,-0.452591,-0.342269,0.147572,-0.154593,-0.209641,-0.274204,-0.654155,0.013336,-0.269274,0.300331,-0.230538,0.054982,0.368331,0.255445,-0.114195,0.203811,0.311500,-0.266629,-0.174771,-0.153145,0.006930,0.243887,-0.174393,-0.075385,0.061873,-0.258863,0.054895,0.230054,0.159736,0.476326,-0.680039,-0.347041,-0.627781,0.013074,-0.289306,0.285551,0.273834,0.015612,-0.234793,0.276912,-0.197960,-0.088034,0.274547,0.146546,-0.284040,-0.773246,-0.099867,-0.044923,0.249929,-0.701463,0.302919,0.275767,0.065266,0.383198,-0.462116,0.023270,0.331159,0.090585,0.501942,-0.387784,0.272840,-0.401621,-0.015360,0.751399,0.071718,-0.236050,0.213292,-0.371822,-0.096488,0.257850,-0.284597,-0.827759,-0.283334,0.174309,-0.147284,-0.339362,0.203865,-0.541615,0.146781,0.018283,-0.316459,-0.282122,-0.450172,0.007123,-0.112080,0.340986,-0.427470,-0.258228,0.218531,0.124437,-0.452913,1.050288,-0.765578,0.386704,0.762906,0.314678,-0.628379,0.509064,0.169276,-0.040038,0.040638,-0.171191,0.276339,-0.024129,0.231577,0.242956,0.296273,0.069805,-0.020248,-0.402492,0.538578', '24284209', '26348103', '1877596', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428069', '春心荡漾', '剧情', '37岁的拉菲（乌玛•瑟曼 饰）不久前离异了，伤心难过的她向心理医生丽莎（梅丽尔•斯特里普 饰）倾诉心事。一次偶遇，她认识了23岁的小伙子达夫（布莱恩•加连保格 饰），他迅速爱上了拉菲。由于年龄上的差异，使拉菲心存顾忌。此间，拉菲常常与心理医生丽莎提及男友的事，丽莎给了她很多鼓励与支持，才让拉菲决定与达夫开展新恋情。丽莎也遇到了儿子给予的难题，儿子爱上了一个比自己年长的女人，更没想到的是她的儿子——达夫爱上的是自己的病人拉菲……©豆瓣', '梅丽尔·斯特里普', '本·杨格尔', 7.3, 9114, 'tt0387514', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456952645.jpg', 0.5, 3.9, 39, 42.7, 14, '0.184704,-0.259709,-0.560438,0.283602,-0.425663,-0.707866,0.822299,0.133781,-0.611178,-0.113434,0.202978,0.969037,-0.194386,0.178877,0.222104,0.175280,-0.122136,-0.625194,0.541999,-0.283895,-0.086648,-0.532763,-0.323334,0.103268,0.053622,-0.546019,0.222293,-0.650899,0.027236,0.373428,0.221719,0.477472,0.502051,0.422559,0.067351,0.257726,0.109700,-0.139965,-0.369217,0.252472,0.122318,-0.017085,-0.099419,0.241903,-0.060711,0.517981,0.648046,-0.002940,-0.269059,-0.184000,0.297438,-0.170406,0.100673,0.209489,0.120800,-0.039291,0.191418,0.175728,-0.309977,-0.270060,-0.140753,0.076849,-0.373897,0.045538,0.194470,0.200875,-0.882364,0.353358,-0.558003,-0.192589,0.268334,-0.357492,0.038659,0.501057,0.048667,0.369479,-0.320202,-0.168038,-0.533171,0.059305,0.454691,0.242152,-0.163982,0.553029,-0.387903,-0.253937,0.108022,-0.096875,-0.732652,0.284288,0.146124,-0.140870,-0.129620,0.493584,-0.481147,-0.098124,-0.530454,-0.013179,0.123335,-0.338347,-0.029379,-0.173131,-0.300742,-0.363956,-0.401775,-0.607793,0.072986,-0.329990,0.841636,-0.600103,0.187772,0.829720,0.554710,-0.442548,0.819272,0.321305,-0.014068,-0.155205,-0.046562,0.229947,-0.405827,-0.302906,-0.201872,0.393531,0.214075,-0.334384,-0.211581,0.318704', '1292720', '1292207', '1297606', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428108', '异教徒', '悬疑', '警官爱德华（尼古拉斯•凯奇 Nicolas Cage饰）在高速公路上巡逻时，亲眼目睹了一个悲惨的交通事故。他尽力去营救车内的女孩儿，结果被炸伤。在休息的日子里，爱德华经常会产生关于那个女孩儿的幻觉，他只能依靠药物来治疗。一天，爱德华收到了多年前不辞而别的女友薇萝的来信。信中说她一直生活在一个隐秘的小岛上，最近她的女儿罗恩失踪了，但岛上没有人愿意帮她，她只得求助爱德华。而巧合的是女儿的照片和车祸中的女孩儿几乎一模一样。爱德华带着疑惑来到了那座偏僻的小岛。经过调查，他发现似乎岛上的居民都在故意隐瞒罗恩的存在，而一切证据似乎都跟当地的一种神秘的祭祀仪式有关……©豆瓣', '尼古拉斯·凯奇', '尼尔·拉布特', 5.6, 10532, 'tt0450345', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2346736278.jpg', 7.7, 25.7, 47.4, 15, 4.3, '0.440610,-0.074998,-0.857918,0.695432,-0.199915,-0.046751,0.878525,-0.153813,-0.698634,-0.315305,0.408193,0.820182,-0.063084,0.438296,0.166850,0.231005,-0.418176,-0.567463,0.051495,-0.293624,-0.554876,-0.613220,-0.235941,-0.421244,0.021612,-0.371719,0.190532,0.121089,-0.025937,0.441494,0.039895,0.077741,-0.274686,0.655877,-0.225576,0.082590,0.101949,-0.041345,0.007894,0.162156,0.195019,-0.357839,-0.085673,0.382980,0.141310,0.645015,0.639121,-0.329823,-0.278770,0.155816,0.167909,-0.216320,0.150384,0.127621,0.454882,-0.049899,0.256742,0.226966,-0.354306,-0.308854,0.014711,0.129547,-0.545817,-0.021069,0.037839,0.345089,-0.669398,0.677191,-0.032078,0.096796,0.030770,-0.436558,0.524275,0.286842,0.090387,0.226222,-0.122970,-0.022138,-0.410777,0.153391,0.644647,-0.058888,-0.109199,0.433277,-0.363102,-0.296484,-0.229997,-0.049801,-0.591008,0.261674,0.262169,-0.197904,-0.480920,0.027805,-0.483368,-0.152314,-0.365897,-0.183619,-0.172524,-0.225409,-0.260000,-0.564204,0.067171,-0.387162,-0.262827,0.015227,-0.078276,-0.266077,0.467667,-0.722043,0.351120,0.805635,0.255695,-0.471143,0.674913,0.097397,0.041414,-0.126280,-0.204929,0.302822,-0.030905,0.403899,0.121783,0.257469,0.198471,-0.080897,-0.525929,0.446270', '1309172', '1866424', '3111650', '1292217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428175', '血钻', '剧情', '九十年代非洲塞拉利昂，连连战火使这片土地饱受摧残，非法钻石贸易日益猖獗。阿彻（莱昂纳多•迪卡普里奥 饰）是一个地道的战争贩子，靠倒卖战区钻石为生，他在监狱中无意得知渔夫所罗门手里有极品粉钻。意识到这是自己离开非洲的机会，出狱后，他找到所罗门，准备和他一起找出钻石，离开非洲。所罗门是普通的渔民，因为内战和家人分离，被叛军强制开采钻石，他发现一颗极品粉钻，藏了起来；战乱来临，所罗门进了监狱，后被阿彻救出，并在战地记者麦迪•鲍文(珍妮弗•康纳利 饰)的帮助下，找到了失散的家人，此时，他的儿子迪亚却被叛军带走，生死未卜。悲愤的所罗门答应和阿彻合作，在叛军的控制范围内寻找钻石，并寻找儿子。两个截然不同的人，因为一颗血钻将命运联系在了一起。©豆瓣', '莱昂纳多·迪卡普里奥', '爱德华·兹威克', 8.7, 353922, 'tt0450259', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1244017073.jpg', 0.1, 0.4, 9.3, 45.4, 44.8, '0.118186,0.148666,-0.638649,0.280911,0.005265,-0.200008,0.743058,0.055896,-0.483098,0.126975,0.020349,0.731047,-0.215902,-0.027159,-0.224520,0.313517,-0.376213,-0.579163,-0.122645,-0.217284,-0.292951,-0.424974,-0.429476,0.014425,-0.168886,-0.307567,0.749786,0.170999,-0.108354,0.410210,0.122346,0.215542,-0.010492,0.412394,-0.300063,0.065378,0.147677,-0.213592,-0.363541,0.414751,-0.135763,-0.129922,0.211291,0.081179,0.411110,0.326099,0.569819,-0.191500,0.391785,-0.055333,0.124855,-0.251644,-0.130528,0.237401,0.238781,-0.030011,-0.075070,0.013876,-0.348870,0.028722,0.486178,-0.044499,-0.589029,-0.017221,0.125424,0.241127,-0.680067,0.249952,-0.005725,0.118503,0.030959,-0.342048,0.402295,0.484180,0.081178,0.068040,-0.213762,0.019536,-0.678036,0.111238,0.653527,-0.569922,0.134786,0.037058,-0.047530,-0.453938,0.101630,-0.021088,-0.193430,-0.295523,0.576357,-0.012595,-0.274098,0.116645,-0.703108,-0.036367,-0.328925,-0.347592,0.076156,-0.166100,-0.157423,-0.499731,-0.310628,-0.231597,-0.411948,0.140439,-0.018738,-0.135337,0.428674,-0.464759,0.160211,0.621009,0.553651,-0.374538,0.498474,-0.052333,0.177672,-0.224098,0.063177,0.559998,0.484955,0.349720,0.166684,0.205328,-0.133633,0.001036,-0.480828,0.273496', '21619567', '25828589', '1316560', '1295324');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428178', '丛林大反攻', '喜剧', '棕熊布哥是个幸运儿，他被收养者宠得一塌糊涂，生活安逸舒适。然而现在他却被放归森林，对大自然的艰苦极不习惯的布哥一心想回城，黑尾鹿艾略特的出现却改变了他的计划。艾略特被猎人撞断了一只角，绑在车中运往镇里。布哥犹豫再三，终于救走了艾略特。这个决定让布哥再不能顺利的回到以前的生活。艾略特拜恩人布哥为兄弟，跟着布哥一起前行，并且引诱他来到野丛林好好“享受”。布哥来到丛林，才发现这里的条件太恶劣了，根本不像城里舒服。而且，他们还犯了一个错误，让动物们陷入狩猎区当中，重重危险面前，布哥的野性被逐渐唤醒，他和动物们组成兵团抗击敌人，上演一场轰烈的家园保卫战。©豆瓣', '马丁·劳伦斯', '罗杰·阿勒斯', 7.2, 25929, 'tt0400717', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2221540442.jpg', 0.5, 3.9, 44, 39.9, 11.7, '0.446634,0.118347,-0.633735,0.293121,0.006917,-0.144609,0.696363,-0.054298,-0.450923,-0.059137,0.164863,0.691959,-0.092023,0.087990,0.102531,0.054793,-0.330728,-0.438391,-0.080541,0.140352,-0.298969,-0.093061,-0.116408,-0.082387,-0.132170,-0.160585,0.668402,0.238008,-0.162394,0.508169,-0.082088,0.221693,-0.044713,0.531971,-0.367491,0.148980,0.139210,-0.103895,-0.007118,0.291115,-0.167585,-0.130128,-0.131373,0.021465,0.192044,0.097840,0.780408,-0.387460,-0.360247,-0.133107,0.075212,-0.356379,-0.144641,0.175921,0.348977,-0.226614,-0.001484,-0.022953,-0.159099,0.196998,-0.142044,-0.128294,-0.685585,0.049144,-0.053320,-0.111236,-0.771248,0.120828,0.265918,-0.099032,-0.017122,-0.324143,0.209265,0.418055,0.333586,0.383348,-0.152651,0.146979,-0.403607,-0.181967,0.933230,-0.372088,-0.263131,0.165137,-0.241743,-0.432582,0.249674,-0.341795,-0.418438,-0.254731,0.330625,-0.015705,-0.489649,0.048376,-0.742125,0.020558,-0.240806,-0.383529,-0.197463,-0.473863,-0.211345,-0.288988,-0.068984,-0.359573,-0.320940,0.400715,-0.027813,-0.128769,0.292330,-0.744153,0.321296,0.438191,0.261894,-0.500169,0.455043,-0.018207,0.034958,0.022901,0.264258,0.414413,0.090866,0.262752,0.476467,0.308843,-0.126985,-0.190116,-0.579024,0.431563', '2032339', '21619567', '25721544', '1309135');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428208', '青春祭', '剧情', '文革期间，女知青李纯(李凤绪 饰)来到了新鲜而陌生的傣乡插队落户，初来乍到对这里的风土人情和傣家话很不适应。多亏房东大爹（松涛 饰）和老奶奶(玉甩 饰)的关心照顾，看到傣家姑娘伊波（玉妲 饰）穿着漂亮的筒裙，姑娘与小伙子的对歌，自己衣着松垮破旧，与她们格格不入，也激起她爱美的心灵。于是穿上了用床单改成的筒子裙，戴上了耳环，变成了漂亮的傣族姑娘。受到了傣族姑娘们的赞美。在一次赶集时，遇到临寨的知青，开朗博学的任佳（冯远征 饰），之后他们慢慢成了好朋友。在全寨庆祝大丰收的夜晚，她跟任佳和村民们围着篝火戴歌戴舞。房东家的大哥（郭建国 饰）喝醉了酒，跟任佳打了起来。她才发现大哥爱上自己，因无法接受，决定离开善良的傣寨乡亲们，去了别的山区当了小学老师......©豆瓣', '李凤绪', '张暖忻', 8.2, 5235, 'tt0089864', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2518230434.jpg', 0.4, 1, 16, 50.7, 31.9, '0.384658,-0.265503,-0.445690,0.169323,-0.348998,-0.311084,0.600621,0.178433,-0.533259,-0.102321,0.003511,0.533778,-0.273285,0.294267,0.362113,0.233431,-0.380801,-0.491927,0.130426,0.070649,-0.400652,-0.163562,0.073328,0.058690,-0.120542,-0.389671,-0.013195,-0.027750,-0.159762,0.679922,0.318621,0.007847,0.098557,0.308966,-0.396196,0.160796,-0.175897,0.120811,-0.178618,0.140256,-0.063529,-0.037829,-0.073646,0.036202,0.141775,0.256153,0.675655,-0.255881,-0.278868,-0.017325,0.240293,-0.060857,0.175069,0.283868,0.175843,0.117318,0.286063,-0.095955,-0.167013,-0.106863,0.101841,-0.202340,0.107729,0.436075,0.319241,0.030055,-0.786311,0.679564,0.033388,-0.295942,0.017416,-0.432229,0.312350,0.134823,0.065612,0.351821,-0.002616,-0.004192,-0.449836,0.306899,0.583740,0.302189,0.074410,0.323524,-0.377403,-0.236356,0.223315,0.105729,-0.350118,0.089626,0.158702,-0.128838,-0.070480,-0.176184,-0.779022,-0.070440,-0.102864,-0.259075,0.184060,-0.316074,-0.304732,-0.164154,-0.192965,-0.643866,-0.308270,0.169370,0.072196,-0.025904,0.734867,-0.877748,0.033135,0.023274,0.377701,-0.445873,0.534393,-0.008689,0.030735,-0.034326,-0.090257,-0.215727,-0.036643,0.281254,0.391167,0.581504,-0.419448,-0.219893,-0.500236,0.098994', '1292219', '24839498', '3155839', '1295295');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428239', '英俊少年', '音乐', '“小小少年，很少烦恼，眼望四周阳光照……”少年海因切（Heintje Simons）虽自幼丧母，却从没失掉过对生活的乐观，他与父亲卡尔（Heinz Reincke）一起过着平静幸福的生活，每日，他都会对“不听话”的父亲“管教”一番。“但有一天，风波突起，忧虑烦恼都到了……”海因切的外公贝特霍德（Paul Dahlke）是一名大实业家，早在海因切未出生时，他就因反对女儿和卡尔结婚与女儿切断了关系，某银行家的儿子为敲诈他将一笔银行失窃款栽赃到卡尔身上时，他视而不见，结果卡尔入狱，海因切在法律的帮助下来到他身边。渐渐地，贝特霍德感受到海因切带给他的温暖，而父亲被人冤枉的事，海因切也于无意间得知。©豆瓣', '海因切·西蒙斯', '汉斯·海因里希', 8.3, 6341, 'tt0064411', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541654845.jpg', 0.2, 0.6, 15.7, 48.5, 35, '0.105338,0.051148,-0.823641,0.615917,-0.371132,-0.493520,0.731097,0.251281,-0.500768,-0.165228,0.144257,0.737279,-0.156815,0.391767,0.457399,0.224031,-0.230448,-0.534242,0.191845,-0.189350,-0.213425,-0.611807,-0.268658,-0.413143,-0.221229,-0.509674,0.419655,0.055484,-0.111025,0.258725,0.298307,0.224665,0.123586,0.777024,-0.226547,0.217515,-0.102282,0.361360,-0.190359,-0.048906,0.147093,-0.268997,-0.246026,0.240377,0.287916,0.374076,0.470028,-0.162263,-0.064692,-0.055513,0.191533,-0.086040,0.250766,0.372289,0.354666,0.073754,0.075794,0.356859,-0.278849,-0.078815,-0.127669,-0.135863,-0.343377,-0.208611,-0.128605,0.020875,-0.511235,0.447384,-0.292202,-0.108694,0.064143,-0.394705,-0.048084,0.192106,-0.032217,0.648563,-0.191731,0.060876,-0.448030,0.038844,0.642434,-0.161391,-0.203716,0.312944,-0.289626,-0.062070,0.041839,-0.192846,-0.650015,-0.108239,0.456638,-0.001528,-0.348583,0.620855,-0.228869,-0.026461,-0.281300,-0.339738,0.074782,-0.409070,-0.058470,-0.025469,-0.146562,-0.454766,-0.526862,0.135709,0.055730,-0.473326,0.506649,-0.623926,0.428500,0.561381,0.208602,-0.366932,0.618805,0.130218,0.156326,-0.043209,-0.031256,0.394062,0.344274,-0.044384,0.400239,0.237029,0.005753,0.019361,-0.134772,0.555919', '26245360', '4275444', '2075721', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428291', 'Jose与虎与鱼们', '剧情', '某个清晨的街道，一个老婆婆失手让推着的婴儿车从斜坡滚下，这时，麻将馆收工的恒夫（妻夫木聡饰）恰好路过，他上前查看，惊讶地发现婴儿车里竟然有个年纪不小的女孩子（池脇千鹤饰）！原来，女孩子是老婆婆的孙女，从小双腿残疾，婆婆觉得丢人，就把她藏在家里，只在清早带她出去散心。令恒夫惊讶的是，这个女孩子的身上不仅没有流露脆弱或自卑，反而有些特别的地方：她烧得一手好菜，她读各种各样从垃圾里捡回的书，她自己给自己取名叫Jozee，她想着从黑市买Tokarev手枪自卫，和恒夫出去逛街时，她无比眷恋地说想把天空的云彩带回家。虽然恒夫已经有了女朋友（上野樹里饰），他还是不知不觉被Jozee吸引过去……©豆瓣', '妻夫木聪', '犬童一心', 8.3, 16611, 'tt0416881', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560227054.jpg', 0.3, 1.3, 16, 47.6, 34.7, '0.479409,-0.025444,-0.768054,0.321041,-0.424339,-0.252912,0.848293,0.012348,-0.294112,-0.160656,0.255902,0.712618,-0.348948,0.369928,0.026642,0.333163,-0.160989,-0.553025,-0.136608,-0.012848,-0.588547,0.016016,-0.207013,-0.023264,-0.362265,0.113978,0.291198,0.079651,-0.259554,0.356168,0.115079,0.014737,0.062161,0.669572,-0.630979,0.215651,-0.448631,0.084239,0.506367,0.025329,0.055586,-0.427730,-0.217214,0.066409,0.315736,0.318408,0.720804,0.084293,-0.027165,0.101414,0.193293,0.063145,-0.142328,0.035193,0.146736,-0.059492,0.091642,-0.440331,-0.289825,-0.059957,0.301443,-0.081003,-0.367007,0.172045,-0.077801,0.032987,-0.800602,0.299722,-0.092185,0.002077,0.346304,-0.377342,0.306494,-0.131036,-0.347019,0.440859,-0.077868,0.083771,-0.573382,0.055350,0.107810,-0.173811,0.163150,0.412178,-0.349558,-0.192720,0.287011,0.055514,-0.276865,-0.104266,0.482537,-0.182205,-0.397950,-0.191367,-0.454356,0.086777,0.022412,-0.164638,-0.114158,-0.376083,-0.403847,-0.063239,0.255008,-0.394804,-0.352324,0.091667,0.029417,-0.055655,0.615389,-0.503240,0.210134,0.442868,0.143613,-0.131970,0.602659,-0.204407,-0.230096,-0.030142,-0.160451,0.069300,0.039194,0.416130,0.466826,0.728810,-0.164146,-0.047833,-0.538217,0.417181', '21619567', '1783772', '1421570', '1396313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428378', '镜子面具', '剧情', '海伦（斯蒂芬妮·莱昂尼达斯 Stephanie Leonidas 饰）从小在马戏团长大，可是身边那些让所有孩子兴奋的事物却只能让她感到厌倦，她想逃离这种不真实的生活，因此和父母发生冲突。不幸接踵而至，先是妈妈（乔安妮·坎贝尔 Joanne Campbell 饰）在表演中倒下，住进医院，接着父亲透露马戏团经营陷入危机。心怀压抑和愧疚的海伦进入一场梦境，那里由光明女皇和黑暗女皇同时统治，但是光明女皇病倒了，世界的平衡被打破，海伦受托去寻找“镜面具”，以拯救这个梦中世界。在小丑瓦伦丁（贾森·巴瑞 Jason Barry 饰）的陪伴下，海伦踏上寻找“镜面具”的路途，似乎只有先拯救梦境，才可以拯救现实……©豆瓣', '斯蒂芬妮·莱昂尼达斯 Stephanie Leonidas', '戴夫·马卡基', 7.5, 11247, 'tt0366780', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p828588059.jpg', 1.1, 5.5, 32.3, 40, 21, '-0.005400,0.467492,-0.483304,0.413674,0.047571,-0.295561,0.800469,0.276723,-0.341390,-0.541788,0.206149,0.692986,-0.030609,0.346232,0.214791,0.256305,-0.715538,-0.523717,-0.047172,-0.017830,-0.328138,-0.316384,-0.087594,-0.274489,-0.165233,-0.422106,0.833736,0.206489,-0.410143,0.277798,0.193579,0.500811,-0.256267,0.442956,-0.069955,-0.203737,0.122173,-0.000979,-0.618686,0.176669,0.064663,0.089862,-0.176582,0.486135,0.065781,-0.196728,0.625147,-0.627151,-0.070133,-0.147919,0.330978,-0.366299,-0.095687,-0.059389,-0.185676,-0.119236,-0.115590,-0.240066,-0.153750,0.063260,0.161421,-0.037602,-0.701215,0.161311,0.061072,0.164232,-0.592605,-0.039576,0.112554,0.045715,0.326395,-0.088995,0.356206,0.387236,0.287719,0.553824,-0.275334,0.144829,-0.450001,-0.053551,0.743870,-0.173653,-0.303203,0.105661,-0.371525,-0.250110,-0.018490,0.092768,-0.558109,0.063430,0.290074,0.010306,-0.133444,0.567762,-0.456823,-0.145008,-0.471183,-0.275197,0.085870,-0.733604,-0.106950,-0.485063,-0.218986,-0.062223,-0.338871,-0.237937,-0.007080,-0.276168,0.419207,-0.789529,0.681653,0.476542,0.152806,-0.375437,0.647263,0.215730,0.157700,-0.525484,0.069657,0.886187,-0.018654,0.246078,-0.029974,-0.120623,0.006026,0.360452,-0.616815,0.502019', '1291835', '26649687', '35287908', '26588308');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428421', '请别相信她', '喜剧', '表面上看来，英珠（金荷娜 饰）只是一个平凡的女孩，有着人见人爱的可爱外表和开朗性格，然而，真实的英珠却是个油头滑脑谎话连篇的女骗子。某日，她带着心爱的木雕前往釜山参加姐姐的婚礼，途中，英珠结识了名为熙哲（姜东元 饰）的男子。熙哲的天真和单纯吸引了英珠的注意，所以，当他准备送给女朋友的传家戒指被盗之后，英珠决心出手相助。可是人算不如天算，英珠不仅因此损失惨重，更是在误打误撞之下被误认为熙哲的女友，住进了熙哲家，并迅速和熙哲的家人们打成了一片。随着时间的推移，在虚假身份掩护下的英珠竟然真的爱上了熙哲，她该如何处理自己的感情？©豆瓣', '金荷娜', '裴炯俊', 7.2, 18432, 'tt0390042', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p710890157.jpg', 0.5, 4.8, 43.5, 37.5, 13.7, '0.165815,0.297135,-0.530445,0.660985,-0.278479,-0.167212,0.422155,0.097956,-0.174058,-0.385797,0.140166,0.627475,-0.117471,0.331690,0.315750,0.158361,-0.227819,-0.582073,-0.196331,-0.306583,-0.327677,-0.417911,-0.139057,0.202195,-0.037266,-0.367039,0.508503,0.122027,-0.116914,0.549812,0.446687,0.181377,-0.083193,0.395268,-0.297288,0.048115,-0.186313,0.062183,-0.056430,0.064520,0.203776,-0.105865,0.021561,0.529424,-0.058741,0.474101,0.825144,-0.515567,-0.256855,0.017264,0.458149,-0.390986,0.026014,0.052416,0.142411,-0.039374,0.161857,0.041797,-0.292465,-0.024197,0.154483,-0.133626,-0.696162,0.174306,0.165661,-0.154451,-0.458979,0.379237,0.094559,-0.018231,-0.101833,-0.253717,0.430844,0.238621,-0.084080,0.143685,-0.318514,0.031496,-0.251864,-0.013838,0.587443,0.226078,0.003540,0.734561,-0.158649,-0.162733,0.092068,-0.266421,-0.503808,0.194964,0.079588,-0.116583,-0.102363,-0.107048,-0.398784,-0.181195,-0.391365,0.203722,0.090986,-0.498228,-0.137742,-0.269843,-0.119145,-0.585708,-0.451540,-0.059287,-0.268920,-0.184883,0.783875,-0.845267,-0.058727,0.437517,0.209263,-0.616226,0.451854,-0.036097,-0.167541,0.007642,-0.372724,-0.001897,0.189586,-0.202356,-0.018190,0.413394,-0.120706,-0.259386,-0.350032,0.310723', '1395231', '3811356', '1292219', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428535', '大赢家', '喜剧', '香港著名骗子黄大千（许冠杰 饰）骗术高超，几十年来凭借狡黠的智慧暴敛钱财。被骗者虽为贪心或疏忽使然，却无不捶胸顿足，后悔莫及。人送绰号“笨蛋”的光头神探（麦嘉 饰）二十年来与黄大千斗智斗勇，大玩猫鼠游戏，可惜这只笨猫总也斗不过狡猾的老鼠。居住在香港的少女吴宝苍（容祖儿 饰）的父亲被黄大千所骗，几度欲跳楼了解此生。宝苍从警方处了解到黄大千已经逃到新加坡，于是起身前去追踪。在这里她碰巧遇见了曾被人骗财骗情于是转而骗人的富家子弟法拉利（谢霆锋 饰）以及呆头呆脑的私人侦探助理施笙紫（苏有朋 饰）。三个年轻人决定联手打败行踪诡异的黄大千……©豆瓣', '许冠杰', '高志森', 5.6, 3873, 'tt0380290', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2355519759.jpg', 6.3, 26.3, 51.9, 9.8, 5.7, '0.022357,0.228128,-0.422896,0.287659,-0.352401,-0.177558,0.272945,0.005811,-0.359693,-0.136018,-0.047624,0.433598,-0.104583,0.005167,0.093217,0.034666,0.095374,-0.423582,-0.164860,-0.313394,-0.089824,-0.389896,-0.338882,-0.080397,0.030229,-0.046343,0.052034,0.383225,-0.335842,0.466271,0.534772,0.052151,-0.261371,0.070813,-0.179988,0.111283,-0.082325,0.191524,-0.015664,-0.152877,-0.206209,-0.325701,0.016090,-0.078895,-0.119060,0.208127,0.355750,-0.186359,-0.310625,-0.185506,0.302630,-0.200642,-0.187650,-0.075148,0.412633,-0.142884,0.408796,-0.124274,-0.077608,0.214860,0.173458,0.200612,-0.720163,0.304632,0.101558,-0.057462,-0.343767,0.044123,-0.103025,0.037781,-0.024662,-0.094282,-0.016940,-0.043572,0.190308,0.007348,0.284139,0.244413,-0.439130,0.369552,0.413677,0.154463,0.044654,-0.027345,0.311742,-0.374348,-0.091756,-0.162785,-0.175267,-0.058870,0.532631,-0.265870,-0.211002,-0.085844,-0.556513,-0.062759,0.035686,0.517091,-0.135175,-0.087026,-0.010446,-0.365640,-0.123800,-0.360347,-0.189838,0.053171,0.191133,-0.279813,0.577176,-0.645362,0.257940,0.478322,0.165411,-0.471196,0.708824,-0.105668,-0.208379,-0.222451,-0.211623,0.209505,0.512180,0.455043,0.211241,0.262991,-0.063795,-0.299201,-0.123590,0.052702', '4301278', '1793491', '3785918', '1308457');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428581', '天书奇谭', '动画', '天庭有珍奇书籍“天书”，被锁在石龛门里三千年。看守天书的袁公对天书的内容好奇不已，他乘无人之际，偷偷拿出观看。原来，天书上记录了一百〇八条法术，袁公偷偷下凡，把天书上的内容刻在石壁上。但本意造福人类的袁公此举却触犯了天条，遭到了玉帝的惩罚。炼丹炉里的仙丹不慎被三条狐狸偷吃了，她们变成精下凡骗人钱财，还假扮仙姑和官府勾结，欺压百姓，祸害人间。袁公便指引天赋异禀的蛋生——一个从蛋里跳出来的孩子修习天书上的法术，和狐狸精斗智斗勇，为民除害。©豆瓣', '丁建华', '王树忱', 9.2, 262353, 'tt6035092', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2700138245.jpg', 0.2, 0.4, 5.3, 26.2, 67.9, '0.581534,0.157621,-0.509178,0.838279,-0.049047,0.106924,0.265212,0.013541,-0.516852,0.154778,0.080396,0.658183,-0.367461,0.006135,-0.494914,0.340973,-0.130065,-0.376791,0.049848,-0.427660,-0.240302,-0.231428,-0.230412,0.057238,-0.260851,-0.478627,0.271800,-0.115840,-0.312848,-0.023221,0.187160,-0.079408,-0.234308,-0.232914,-0.442334,0.175063,-0.172082,0.230261,0.607935,0.139230,-0.103908,-0.524516,0.018981,0.040679,-0.249973,0.200640,0.493553,-0.378091,0.014480,-0.097510,0.409448,-0.298546,-0.163538,0.300154,0.320888,0.469234,0.027613,0.188042,-0.174324,0.147451,0.228373,-0.097531,-0.637464,-0.552648,0.099659,0.299218,-0.190566,0.367101,-0.055750,0.426552,-0.317154,-0.451805,0.218626,-0.020814,0.080339,0.311861,-0.115545,-0.497114,-0.831567,0.102284,-0.045140,-0.269923,0.278841,0.324228,0.228262,-0.481369,0.095056,-0.306928,0.066736,-0.062739,0.733367,-0.117086,-0.207027,-0.024157,-0.679756,0.142018,-0.169491,0.167107,-0.430701,-0.188754,-0.309547,-0.359293,-0.081245,-0.087621,-0.502849,-0.035222,0.489744,-0.438931,0.914525,-0.268101,0.215799,0.291223,-0.104736,-0.345007,0.933081,-0.212598,-0.214311,-0.000094,-0.058606,-0.064471,0.618066,0.834746,0.055734,0.262788,0.162709,0.152030,-0.488480,0.342645', '1302661', '1438924', '22265121', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428602', '杀破狼', '剧情', '刘国忠（任达华 饰）是一个身患绝症的警察，他的前途暗淡无光，他接到任务要保护一个证人的女儿。督察马军（甄子丹 饰）是身手了得的武术家，一心要接替忠的位置。忠派去黑道大哥宝爷（洪金宝 饰）身边的卧底意外死亡，原因不明，忠怀疑是宝爷所为。于是把宝爷押送到警局盘问，苦于没有证 据，忠迫不得已开始捏造证据控告宝爷，全警局都深谙此道，只有军蒙在鼓里。然而，证据神秘消失，宝爷走出警局时，扬言要杀掉忠的所有手下，果然他身边的冷血杀手Jack（吴京 饰）干掉了忠一帮下属，马军意外发现，忠的下属和宝爷之间原来还另有恩怨，马军怒火中烧，决定与宝爷和Jack决一死战。©豆瓣', '甄子丹', '叶伟信', 7.6, 134616, 'tt0478024', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2250158341.jpg', 0.6, 2.9, 31.1, 47.1, 18.3, '0.170962,-0.057876,-0.542858,0.415307,-0.106738,-0.037600,0.245887,0.242497,-0.552705,-0.513991,0.129374,0.359346,0.223067,0.026841,0.154275,-0.122501,-0.411091,-0.740317,-0.425076,-0.268142,-0.300545,-0.628473,-0.026876,-0.306104,0.018087,0.026102,0.461993,0.006039,-0.173086,0.510282,0.672673,0.242355,-0.307891,0.275049,-0.091488,0.209035,0.251287,-0.240947,-0.506187,-0.099293,0.044495,-0.082004,-0.123835,0.329608,0.069242,0.464661,0.288563,0.019948,-0.246451,-0.132268,0.217679,-0.468277,0.082285,-0.061423,0.402177,0.055403,0.101112,0.512794,0.011260,-0.027270,0.192909,0.078089,-0.939504,-0.164075,0.078349,0.173117,-0.435024,0.246669,-0.147805,0.054250,0.062864,-0.185767,0.507822,0.065302,-0.094256,0.159032,0.032341,-0.117515,-0.582701,0.132637,0.602901,-0.102809,0.245190,-0.075448,0.281801,-0.212994,0.110305,-0.222251,-0.212522,0.189538,0.179914,-0.081508,-0.003762,-0.298065,-0.084003,-0.323362,-0.397047,0.419982,-0.110973,-0.381268,0.085318,-0.199148,-0.013193,-0.156525,-0.394710,0.466477,-0.134840,-0.133525,0.323924,-0.654590,-0.052798,0.403312,0.329688,-0.908280,0.426340,0.316540,0.022784,-0.548747,-0.090149,-0.248971,0.600252,0.267414,0.229035,-0.114502,-0.163107,-0.506699,-0.289501,-0.169423', '1302110', '26678784', '3811342', '1297862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428876', '决不让步', '剧情', '乔西（查理兹·塞隆 Charlize Theron 饰）与丈夫分居后，带着两个孩子回到明尼苏达老家，为了生计，决定不顾父亲反对去当地矿上工作。入职后乔西才明白为什么家里人对她的决定如此反对——矿上工作的女人每日要承受男职工们大量的性侮辱、性骚扰，就算忍气吞声，也要被男矿  工的妻子们当成婊子，甚至在公共场合受到辱骂。不堪忍受这一切都乔西决定出头把矿业公司告上法庭。这个念头让乔西受到前所未有压力，在公司里得到的羞辱变本加厉，还连累其他女员工，令她们都和她反目；在家里，从外面承受人言的孩子们也开始怀疑母亲的清白。乔西扛住这一切，只为让男人们知道不尊重女性的应有下场……本片根据1988年发生的真实事件改编，是美国历史上第一桩起诉成功的性骚扰官司。©豆瓣', '查理兹·塞隆', '妮琪·卡罗', 8.1, 10309, 'tt0395972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1764377963.jpg', 0.2, 1.2, 19.3, 52.7, 26.6, '-0.123070,-0.080853,-0.750374,0.109550,-0.294646,0.033054,0.469580,0.079405,-0.520886,-0.215196,0.047439,0.651053,-0.006022,0.433185,0.134988,-0.228487,-0.296018,-0.586622,-0.106527,-0.040564,-0.175408,-0.424019,0.368480,-0.336545,-0.369608,-0.166426,0.351211,-0.132917,-0.273087,0.140382,0.518624,0.289783,0.094998,0.343910,0.004405,0.096718,-0.139102,0.071374,-0.372701,0.109032,0.185803,0.070393,-0.128666,0.271835,0.212747,0.222600,0.493931,-0.129987,-0.360602,-0.305457,0.435634,-0.284533,0.068818,0.575447,0.193374,-0.090687,0.200171,0.486437,-0.461671,0.016023,0.242357,0.102407,-0.686635,-0.097068,0.059986,-0.045124,-0.697039,0.111229,-0.047037,0.090065,-0.029391,-0.293971,0.136481,0.212678,0.157212,0.544063,-0.388841,0.155158,-0.419583,0.059431,0.938492,-0.147180,-0.110511,-0.112389,-0.299550,0.037785,0.077683,-0.536743,-0.559033,0.002856,-0.224375,0.033631,-0.180783,0.322982,-0.238505,-0.337184,-0.121493,-0.377560,0.062099,-0.541598,-0.042259,-0.461500,-0.143054,-0.120373,-0.332172,0.092983,0.299893,-0.315961,0.523805,-0.653732,0.243486,0.570265,0.628032,-1.072222,0.517865,0.443202,0.409885,-0.090658,-0.289231,0.051284,0.419567,0.073159,0.037062,-0.035939,0.044234,-0.018144,0.054496,0.220283', '1305915', '1421278', '1877596', '4145476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428877', '魔法保姆麦克菲', '喜剧', '布朗(科林•菲尔什 饰)的妻子在一年前去世，留下了七个古灵精怪的孩子。整天在工作上疲于奔命的布朗，回到家里还要应付这些捣蛋鬼。为此，布朗前前后后找了16任保姆，可没有一个能应付这些鬼精灵。雪上加霜的是，布朗专横的姑妈向他下了最后通牒，如果他不能在一个月内再给孩子们找到一个母亲，就不再资助他们生活费。负债累累的布朗如果得不到姑妈的资助，就很可能会锒铛入狱。此时，生活陷入绝境。正在布朗感到绝望的时候，一个长相极为丑陋的女人出现在他家门口。女人告诉布朗她叫南茜•麦克菲(艾玛•汤普森 饰)，并毛遂自荐当上孩子们的保姆。麦克菲拥有神奇的魔力，无论孩子们怎么计划好要戏弄她，都无法成功。孩子的恶作剧有时甚至会报应在自己身上。在麦克菲的细心的调教下，孩子们一天天变乖，而布朗的处境也日益好转，就连魔法保姆自己的面容，也在发生变化…©豆瓣', '艾玛·汤普森', '柯克·琼斯', 7.6, 60106, 'tt0396752', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p815638869.jpg', 0.3, 2.2, 31.2, 47.8, 18.4, '0.075595,-0.199149,-0.658519,0.476366,-0.591966,-0.434297,0.651584,0.133342,-0.511921,-0.366238,0.002748,0.673897,-0.027658,0.560071,0.021844,-0.050426,-0.434527,-0.717789,-0.001051,-0.120988,-0.348508,-0.537481,-0.093743,-0.552543,-0.152897,-0.452836,0.192106,-0.018377,0.148410,0.035809,0.337379,0.094073,0.270169,0.359280,-0.343169,0.083091,-0.110628,-0.071657,0.071309,0.220065,0.263514,-0.089506,-0.083784,0.299408,0.312523,0.230643,0.638022,-0.191421,0.002845,-0.190391,0.202667,-0.142445,0.009915,0.224111,0.186627,-0.441385,0.205174,-0.000787,-0.425038,0.047057,0.080050,-0.020205,-0.784481,0.207899,-0.219444,0.173113,-0.870010,0.179924,-0.063769,0.178592,-0.037316,-0.567448,0.077366,0.439821,-0.147060,0.558962,-0.310178,-0.001315,-0.646180,0.082600,0.631559,0.104941,-0.101094,0.383251,-0.264357,-0.215765,-0.012459,-0.264715,-0.741062,0.045974,0.145568,0.018033,-0.226191,0.173817,-0.245665,0.105839,-0.360561,-0.269052,-0.137287,-0.476617,-0.071899,-0.505853,0.065646,-0.309560,-0.559918,0.231182,-0.045425,-0.267442,0.834933,-0.756468,0.324884,0.420707,0.330116,-0.636733,0.535391,0.213250,0.163269,-0.117333,-0.183420,0.205316,0.036475,0.066656,0.367997,0.346056,0.016450,-0.057180,-0.036969,0.632144', '1877596', '1783461', '1299965', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1428878', '赛车总动员', '喜剧', '汽车世界中，一年一度的活塞杯再次拉开序幕。红色跑车“闪电”麦坤和“冠军”、“路霸”是冠军最有力的竞争者。作为新人，麦坤具有极高的天赋，同时也是一个目空一切的家伙。经过紧张激烈的对抗，这三辆车同时冲过终点线。由于无法判定最终优胜者，组委会决定一个月后在加州洛杉矶召开一次只有这三辆车参加的殊死战，只有最后的胜者才能捧得活塞杯。信心满满麦坤和搭档拖车麦大叔早早启程。但是长时间的疲劳驾驶，令麦大叔不慎将麦坤丢在半路。麦坤东闯西撞，无意间来到了被众车遗忘的油车水镇。因躲避警长的追捕，麦坤毁坏了小镇的马路。在法官哈迪逊韩大夫和律师保时捷莎莉的裁决下，他被迫留在这里修路。短短几天相处，麦坤和小镇的居民渐渐融洽起来，同时他也爱上了美丽的莎莉。只不过，路终有修完的时候，未完的比赛仍在等待着他……©豆瓣', '欧文·威尔逊', '约翰·拉塞特', 8.1, 176946, 'tt0317219', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p593931509.jpg', 0.2, 1.4, 21.3, 49.6, 27.6, '0.111298,0.245031,-0.614123,0.531927,0.029669,-0.288272,0.671416,0.131887,-0.535119,0.055667,0.385369,0.818900,-0.339718,0.086650,0.496333,-0.249494,-0.275078,-0.570465,-0.129355,-0.200896,-0.524771,-0.554220,0.020834,-0.017525,0.163344,-0.215432,0.501815,0.146063,0.043601,0.608961,0.378790,-0.155960,-0.017060,0.590345,-0.287050,-0.004136,0.158117,-0.120034,-0.198113,0.298581,0.075694,-0.310805,-0.093625,-0.065285,0.191075,0.268551,0.683406,-0.103586,-0.229346,0.117288,0.104747,-0.287998,-0.006150,-0.158249,0.388525,0.024114,0.095325,0.128840,0.020252,-0.011355,0.006756,-0.047830,-0.592438,0.134481,-0.234122,-0.111844,-0.650405,0.792047,-0.097657,0.000391,0.038136,-0.283431,0.216737,0.270095,0.237242,0.196880,-0.045871,-0.003753,-0.509373,0.133810,0.777693,0.094181,-0.218184,0.369209,-0.025618,-0.540716,0.086673,-0.410110,-0.389648,-0.102975,0.626717,0.111314,0.031535,-0.074386,-0.469990,0.093983,-0.307863,-0.366373,-0.002591,-0.222012,-0.002142,-0.532712,0.152576,-0.377388,-0.024700,0.239935,-0.254059,-0.003043,0.614740,-0.932462,0.231417,0.425804,0.261745,0.074868,0.599766,-0.034831,0.160440,-0.196331,-0.105316,0.016800,-0.111095,0.690207,0.305668,0.471481,-0.107769,-0.216341,-0.484343,0.456815', '1292219', '35030151', '21766698', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1431617', '晚安，好运', '剧情', '这部电影记载了上世纪中叶美国一场轰烈的政治抗争，此次对抗冲突是美国新闻界和政治史册上不可或缺的一页。在冷战的背景下，参议员约瑟夫•麦卡锡（Joseph McCarthy Himself）作为新兴政治人物崛起，他以反共产主义的政治立场而闻名。麦卡锡用强硬的手腕，搜集国会内的共产主义分子资料，实行高压的政治迫害，意欲掀起席卷政坛的反共风潮。美国哥伦比亚电视台的新闻记者爱德华（大卫·斯特雷泽恩 David Strathairn饰）和他的同事们对这个政治阴谋坚决抗争。他们用自己的新闻理想、新闻阵地，毫无退缩地与麦卡锡主义对抗到底，并把这个丑陋的政客拉下政治舞台。爱德华和他的同事，成为了美国历史上的传奇人物。©豆瓣', '大卫·斯特雷泽恩', '乔治·克鲁尼', 7.8, 8890, 'tt0433383', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1461762516.jpg', 0.5, 2.3, 24.1, 50.6, 22.6, '0.533294,0.033497,-0.614537,0.903693,0.267519,0.120181,0.452208,0.165625,-0.344255,-0.007496,0.227104,0.938338,-0.182949,-0.037440,0.192093,-0.102694,-0.431697,-1.154446,-0.299773,0.209577,-0.159285,-0.429246,-0.652205,-0.280083,-0.344997,0.206877,1.012566,0.192534,-0.738636,0.447956,0.428781,0.359448,0.248017,0.421229,-0.048898,-0.034491,-0.062817,-0.096953,-0.426965,0.134988,0.269984,-0.309429,-0.185310,0.352055,-0.066291,0.382007,0.106983,-0.308171,0.473613,-0.324082,0.628997,-0.544763,-0.283851,0.330470,0.532196,0.235779,-0.107297,0.543035,0.079964,-0.306788,0.002649,-0.107354,-0.773679,-0.246975,-0.161801,0.310656,-0.575282,0.577844,-0.202684,0.025196,-0.180120,0.035862,0.066476,0.487101,0.118207,0.343277,0.139535,0.082646,-0.231796,0.293947,0.418680,0.201374,-0.472502,-0.172632,-0.438439,-0.365575,-0.205489,-0.668762,-0.324765,-0.441199,0.342501,-0.522937,-0.067060,0.573220,-0.846998,0.075596,-0.061672,-0.313667,0.203528,-0.308268,0.071816,-0.910400,-0.515826,-0.570663,-0.296503,-0.165868,0.235128,-0.190057,0.879296,-0.678166,-0.120157,0.595829,0.392083,-0.462676,0.777788,0.196774,-0.061921,-0.141005,-0.237733,0.262634,-0.026603,0.422718,-0.147846,0.253116,0.258720,-0.150326,-0.022024,0.562733', '1780122', '25880986', '26990609', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1431648', '闪亮的日子', '剧情', '克里斯蒂安（韦斯利•拉姆齐Wes Ramsey 饰）是个同性恋者，他年轻英俊、风流倜傥，经常在朋友面前炫耀自己的风流史。这天，有四位年轻英俊的摩门教徒搬进克里斯蒂安的公寓。乐不可支的克里斯蒂安拿着一箱啤酒去窜门，可是他同性恋的身份一眼就被看穿了，被他们赶了出来。克里斯蒂安发誓一定要追到其中的一位英俊小伙阿隆（史蒂夫•山德沃斯 Steve Sandvoss 饰），一雪前耻。克里斯蒂安经常撞见帮同伴洗衣服的阿隆，一次，他假装伤的很重，将好心的阿隆骗到了自己的公寓，两人的第一次就这样开始了。完事后，阿隆惊慌得不知所措，因为摩门教规禁止同性恋，可是克里斯蒂安却不以为然，阿隆气愤得大骂。这次之后，克里斯蒂安开始反思自己的人生，渐渐地，他发现生活除了游戏和性，还有其他更丰富的东西，他也发现，自己开始爱上了阿隆……©豆瓣', '史蒂夫·山德沃斯', 'C·杰·寇科斯', 7.7, 12667, 'tt0345551', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2454489502.jpg', 0.7, 4.2, 30.1, 40.9, 24.1, '0.427825,-0.019277,-0.614971,0.409808,-0.521037,-0.576488,0.705927,-0.001297,-0.255063,-0.261383,0.086086,0.928182,-0.351132,0.571444,0.201681,0.261199,-0.184571,-0.571785,-0.045913,-0.121682,-0.379473,-0.240678,-0.183163,-0.234751,-0.067375,-0.349802,0.155212,-0.129650,-0.093887,0.448859,0.322360,0.035258,0.194152,0.466266,-0.371462,0.266316,0.035702,-0.101763,0.186566,0.129818,0.213559,-0.228165,-0.367503,0.500294,0.005112,0.425715,0.414845,0.233836,-0.381050,0.136056,0.353874,-0.135453,-0.017433,0.297111,0.330059,-0.153307,-0.037406,-0.159854,-0.063586,0.013341,-0.027604,0.084391,-0.423699,0.091603,-0.138869,-0.059855,-0.686671,0.546579,-0.230517,-0.067700,0.096566,-0.376905,-0.041266,0.131599,0.140930,0.338287,-0.083246,0.013937,-0.740189,0.120862,0.490252,0.103551,0.070544,0.320508,-0.074214,-0.154769,0.087782,-0.070850,-0.449593,0.038877,0.623260,-0.120808,-0.099377,0.086317,-0.469368,-0.067173,-0.232068,-0.058080,-0.110393,-0.240655,-0.248329,-0.298824,-0.184015,-0.449389,-0.302085,0.077147,-0.073007,-0.190849,0.584161,-0.555809,0.206020,0.624215,0.162727,-0.515435,0.528839,0.166000,-0.091910,0.036895,-0.124036,0.035738,0.290716,0.152034,0.425873,0.679098,-0.085561,-0.388689,-0.351082,0.451962', '1309069', '30162520', '1292207', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1431690', '雷雨', '剧情', '周家馆里的大老爷周朴园（孙道临 饰）经营的是煤矿生意，和自己的续弦繁漪（顾永菲 饰）生下了自己的第二个儿子周冲（钟浩 饰），而大儿子周萍（马晓伟 饰）的生母，周朴园只说早早过世了。年轻貌美的繁漪忍受不了周家馆的死气沉沉和周朴园的阴郁脾气，和大儿子周萍发展成了乱伦关系。这段禁忌之恋最终因为周萍的懦弱而夭折，周萍转而把注意力投入到了家里的侍女四凤（张瑜 饰）身上。周萍和四凤的关系让繁漪精神衰弱，于是找来了四凤的母亲希望把四凤辞退。走入到周公馆的侍萍（秦怡 饰），原来就是三十年前被周朴园抛弃的，最后被周家的管家鲁贵所救的周萍的亲生母亲。得知真相的侍萍无法接受自己女儿和儿子在不知情的情况下相恋的事实，而悲剧却已无法阻止……本片改编自作家曹禺的同名话剧。曾多次被搬上荧屏，至今仍活跃在话剧的舞台上。©豆瓣', '孙道临', '孙道临', 8, 16184, 'tt2304741', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2750953560.jpg', 0.3, 1.3, 19.9, 53.7, 24.8, '0.440615,0.191242,-0.801130,0.546057,-0.182872,-0.543952,0.758682,0.330992,-0.600332,-0.217654,0.222923,0.833817,-0.130303,0.503240,0.134933,0.117117,-0.066551,-0.623128,-0.173440,-0.029003,-0.193306,-0.587717,-0.026488,-0.140879,-0.207113,-0.109766,0.507252,0.125023,-0.159000,0.349659,0.615087,0.215175,-0.094931,0.344323,-0.095793,0.441333,-0.081530,0.057212,-0.193572,0.133024,0.151588,-0.343885,-0.042334,0.235632,0.180042,0.388415,0.605555,-0.145851,0.025841,-0.230543,0.475486,-0.206800,-0.120742,0.350198,0.466177,0.006072,0.233395,0.463317,-0.436401,-0.187502,0.106975,-0.052955,-0.705287,0.187632,0.396130,0.116803,-1.002784,0.616359,-0.098487,-0.163646,-0.073364,-0.320760,0.411478,0.300349,0.198989,0.562727,-0.386144,-0.057567,-0.503789,0.404223,0.550162,-0.082924,-0.070025,0.473465,0.003408,-0.180313,-0.087166,-0.477409,-0.555136,0.124426,0.355039,0.153396,-0.345267,0.096613,-0.316590,-0.381953,-0.201362,-0.038520,0.078531,-0.384640,-0.058114,-0.230309,-0.388525,-0.584891,-0.354034,0.010609,0.114658,-0.372696,0.642935,-0.574320,0.152544,0.158198,0.309697,-0.586874,0.581378,0.232425,0.273412,-0.153884,0.090193,0.084727,-0.087883,0.245384,0.243790,0.260269,-0.162033,-0.212706,-0.308370,0.356928', '1299965', '3111650', '1316525', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1431694', '永不消逝的电波', '剧情', '1938年，我地下党组织在上海的电台被敌人破坏后，延安解放区电台政委李侠（孙道临）来到上海，白天他是一名商人，晚上则躲在阁楼间收发电报，为了进一步做好保密工作，党组织同时安排纱厂女工何兰芬（袁霞）与他假扮成夫妻。两人在工作中产生真情，结为真夫妻。日军通过一系列手段发现 了阁楼间的电台，李侠被捕，虽遭受了非人的折磨，他始终守口如瓶，致使日军以为他仅是为商业电台工作，将他释放。日军投降后，李侠夫妇又同国民党展开了斗争。解放战争即将取得胜利时，电台被国民党发现，李侠接到到紧急撤退的通知，但此时，他又收到两份极为重要的情报。©豆瓣', '孙道临', '王苹', 8.1, 14080, 'tt0352008', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2693881679.jpg', 1, 1.4, 19.6, 49.3, 28.6, '0.261212,0.025107,-0.759421,0.443005,0.155674,0.070183,0.331708,0.189189,-0.589672,-0.120424,0.267924,0.456390,-0.137363,-0.002380,0.044337,-0.345261,-0.468477,-0.816071,-0.169358,-0.110374,-0.136824,-0.434053,-0.109095,-0.062098,-0.195601,-0.136784,0.578087,0.272820,-0.127973,0.199798,0.043086,0.126420,-0.183823,0.664847,0.213321,0.144924,0.332955,-0.353740,-0.442452,0.235884,0.253763,-0.368593,-0.131816,0.126888,-0.021176,0.369171,0.588935,0.020863,-0.264757,-0.139331,0.284208,-0.146159,-0.050566,0.244370,0.600690,0.354508,-0.003667,0.355177,-0.478796,0.125564,-0.143644,0.135754,-0.329448,-0.069296,-0.153827,0.005010,-0.488108,0.245899,-0.300125,0.413921,0.131592,-0.524036,0.256592,0.793510,0.090277,0.305895,-0.348716,0.155104,-0.538088,0.084992,0.666161,-0.122512,0.008441,0.056914,0.088435,-0.412093,0.256557,-0.029687,0.063496,-0.174126,0.120237,-0.112990,0.046788,-0.070309,-0.529782,-0.245402,-0.172957,-0.094747,0.046755,-0.407381,-0.253227,-0.994352,-0.122288,-0.205134,-0.391757,0.461127,0.099476,0.022487,0.513534,-0.830377,0.066717,0.425734,0.123368,-0.363560,0.518480,0.027324,0.226034,-0.193354,0.244323,0.029448,0.077584,0.701184,0.462184,0.107919,-0.273881,-0.227823,-0.175944,0.064795', '25723905', '1297715', '6041191', '6007281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1431755', '粉红色高跟鞋', '剧情', '性情温顺的眼科医生善彩（金惠秀）发现丈夫与人偷情，忍泪带着女儿太秀（朴妍儿）离开家住进一间破旧的房子，并租下一处地方欲开私人诊所。温柔开朗的大男孩仁哲（金宋苏）是她雇请的室内设计师，两人短暂接触生出感情。善彩的人生看似要得以改变，但一切不过是她刻意经营的假像，这假像又因一双被她偶然拾于地铁的被诅咒的粉红色高跟鞋更加扑朔迷离：学跳芭蕾的太秀也被高跟鞋深深吸引，母女争鞋时几乎成敌人；仁哲真心待她，却从没注意到两人温存时她那可怕的眼神。善彩已将高跟鞋视作她所执导、参演的人生大戏的一个重要道具。©豆瓣', '金惠秀', '金容钧', 6.2, 23426, 'tt0468683', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1584401953.jpg', 2.5, 15.5, 56, 20.2, 5.8, '0.274086,0.003699,-0.661677,0.416431,-0.062957,-0.121311,1.047218,0.201089,-0.404249,-0.234440,0.273040,0.724488,-0.369906,0.129895,0.137170,0.323262,-0.116070,-0.578854,-0.051210,-0.067898,-0.085305,-0.140964,-0.187567,0.068210,0.009172,-0.146722,0.408583,0.311101,-0.290369,0.314655,0.213091,-0.024275,-0.056441,0.458380,-0.131221,-0.068764,-0.181278,0.135477,-0.070465,-0.035087,-0.121434,-0.138955,-0.177184,0.144610,-0.336147,0.438547,0.643203,-0.076733,-0.360173,0.024498,0.409725,0.011291,-0.028199,0.259160,0.086623,0.078718,0.204655,0.102022,-0.299095,0.080780,0.371446,-0.219298,-0.475750,0.158758,0.152668,-0.033185,-0.405430,0.523884,0.024388,-0.175108,0.070920,-0.286762,0.196202,-0.269177,0.129197,0.324836,-0.195398,0.171644,-0.458136,0.164192,0.460325,0.064342,-0.302477,0.601468,-0.399648,-0.479096,0.030380,-0.333051,-0.387501,0.027872,0.344499,0.097826,-0.288870,-0.006800,-0.425479,0.053996,-0.309890,0.015346,-0.089742,-0.614409,-0.067916,-0.447424,-0.116462,-0.643497,-0.383228,0.101747,-0.072141,-0.355797,0.385881,-0.659104,0.168196,0.472311,0.191686,-0.373046,0.641097,-0.110627,0.163275,0.028044,-0.186943,0.370293,-0.094785,0.080896,0.186195,0.420425,-0.321041,0.237684,-0.417256,0.449512', '1296534', '1417428', '21348112', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432146', '钢铁侠', '动作', '斯塔克军火公司是美军在全球范围内第一大军火供应商，其新任掌门人托尼•斯塔克（小罗伯特·唐尼 Robert Downey Jr. 饰）风流倜傥，天资聪颖。他与公司元老俄巴迪亚•斯坦（杰夫·布里吉斯 Jeff Bridges 饰）合作无间，共同将斯塔克公司的业务推向顶峰。现 实生活中的托尼热衷收集名贵跑车，搞点儿发明创造，当然露水姻缘更不可少。所幸他身边有维吉尼亚•波茨（格温妮斯·帕特洛 Gwyneth Paltrow 饰）这样的好助手细心打理一切，才让他能自由自在过着贵公子的生活。在前往中东为军方展示新型武器的途中，托尼一众遭到恐怖分子袭击。他被弹片击中险些丧命，在英森博士的帮助下，托尼体内移植了一颗核动力的人工心脏。恐怖分子要求托尼制造强大的杀伤性武器，他和英森虚与委蛇，暗中制造了一套由聚变能源驱动的钢铁盔甲。穿上盔甲托尼大闹恐怖分子的基地，回到美国后又对其进行了改进。却不知，接下来有更为黑暗的阴谋等着他……', '小罗伯特·唐尼', '乔恩·费儒', 8.4, 559663, 'tt0371746', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p725871968.jpg', 0.2, 0.8, 15.2, 47.2, 36.5, '0.048874,0.020134,-0.647354,0.491872,-0.074184,-0.184714,0.579924,0.046122,-0.359866,-0.281450,0.404356,0.663702,-0.072375,-0.128330,-0.148820,0.097971,-0.557818,-0.386939,-0.104009,-0.071875,-0.342923,-0.447466,-0.515090,-0.253599,-0.128541,-0.316303,0.461373,-0.118234,-0.193018,0.037277,0.054273,0.449243,0.174538,0.392458,-0.092393,-0.282824,0.192432,-0.209400,-0.247906,0.293906,0.026232,-0.178834,0.196536,0.137050,0.151015,0.243853,0.447530,-0.157777,0.203713,-0.381402,0.249794,-0.028281,0.363973,-0.071425,0.272677,0.173090,-0.114270,0.092250,-0.407474,0.073216,0.420762,-0.109990,-0.761900,-0.289769,0.037221,-0.151716,-0.601956,0.299140,-0.437716,0.056706,-0.007424,-0.412323,0.076930,0.410855,0.431487,0.052015,-0.101294,0.251494,-0.563336,0.232834,0.425165,-0.127462,-0.341173,0.113382,-0.214555,-0.317525,-0.073547,-0.421696,-0.308510,-0.385910,0.488471,-0.074071,0.281060,0.468992,-0.603630,0.072015,-0.388426,-0.293458,-0.015220,-0.068928,0.006744,-0.825339,-0.023971,-0.353881,-0.275764,0.124406,0.247540,-0.102162,0.580976,-0.597871,-0.039018,0.496341,0.417374,-0.250267,0.280347,-0.298360,0.280333,-0.059653,-0.365616,0.018732,0.152753,0.396439,0.176828,0.460453,0.261135,-0.237943,-0.195089,0.187389', '1293433', '3178770', '1307897', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432180', '生死停留', '剧情', '一部超出想象的心理惊悚电影。一向上进的大学生亨利·拉萨姆（瑞恩·高斯林 Ryan Gosling 饰）突然扬言要自杀，心理医生山姆·福斯特（伊万·麦克格雷格 Ewan McGregor 饰）为了挽救亨利，开始对其进行治疗。奇怪的事情发生了，医生山姆发现亨利经常会说出一些 骇人听闻的语言，更加令人不安的是，这些预言竟然一一应验。究竟是什么神秘的力量在操控着亨利？生死一线，中间真的能够停留吗？在女友丽拉·库尔佩（娜奥米·沃茨 Naomi Watts 饰）的支持和帮助下，山姆能否找到答案，拯救一切？©豆瓣', '伊万·麦克格雷格', '马克·福斯特', 7.5, 72629, 'tt0371257', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p844629390.jpg', 0.9, 3.8, 31.1, 46.8, 17.4, '0.082087,-0.026993,-0.410395,0.444837,-0.007366,-0.109669,0.441502,-0.180948,-0.434224,-0.638540,0.048500,0.399279,-0.285963,0.032009,0.213048,0.061534,-0.484986,-0.555095,0.271947,0.142898,-0.366905,-0.829077,-0.490770,-0.432559,-0.049497,-0.495626,0.168100,0.186378,-0.374095,-0.022583,0.409195,0.528150,0.158926,0.224821,0.092121,0.036313,0.184882,-0.124788,-0.511833,0.326895,0.436946,0.010492,-0.192515,0.441125,0.049139,0.203520,0.281731,-0.367408,-0.190972,0.240871,0.508147,-0.253645,0.310180,0.177846,0.041902,-0.027415,-0.052168,-0.024444,-0.126430,0.168570,0.226645,-0.019812,-0.869216,-0.003249,-0.007785,0.458000,-0.474203,-0.220275,-0.244607,0.066012,0.257004,-0.367403,0.004308,0.437887,0.360415,0.191765,-0.206523,-0.287526,-0.471985,-0.128660,0.593332,0.125556,-0.283079,0.330094,-0.177774,-0.429144,-0.298641,0.263520,-0.440916,0.321715,0.201314,0.031995,0.104177,0.432502,-0.236759,-0.250801,-0.336987,-0.037839,-0.089624,-0.357270,0.077803,-0.676242,0.090567,-0.165945,-0.090133,-0.171930,-0.030461,-0.441175,0.585020,-0.704206,0.063136,0.481882,0.251893,-0.227080,0.181397,-0.030543,-0.088106,-0.283464,-0.168496,0.509819,0.137497,-0.117251,-0.029832,0.275337,0.476748,-0.233943,-0.233271,0.529709', '3006783', '1793491', '1811755', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432436', '鲁邦三世：卡里奥斯特罗城', '爱情', '卡里奥斯特罗，一个位于欧洲人口只有3500人的小国家，却是世界上最逼真的伪钞——山羊之钞的发源地。其伪钞之真，连鲁邦三世这样的大盗都险些被其蒙蔽。鲁邦和伙伴旅行至此，恰巧遇见正被一伙暴徒追赶的美丽少女克拉丽斯。鲁邦出手相救，却从少女遗留下的戒指上若有所悟。原来是多年前鲁邦曾来此寻找过山羊之钞的下落，并在此结识还是孩童的克拉丽斯及其身为大公的父亲。如今物是人非，七年前的一场大火烧毁了大公的城堡，克拉丽斯的父母皆在大火中身亡。孤苦伶仃的克拉丽斯无依无靠，而摄政王卡里奥斯特罗伯爵则逼迫少女与之成亲。鲁邦决定从伯爵手中救出女孩，同时探究戒指背后所隐藏的关于宝藏的秘密……©豆瓣', '山田康雄', '宫崎骏', 8.4, 25929, 'tt0079833', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1446259907.jpg', 0.1, 0.9, 16, 44.8, 38.1, '0.099549,-0.104039,-0.708406,0.358457,-0.279067,-0.355625,1.058320,-0.108105,-0.472690,-0.255369,0.610119,0.821822,-0.143657,0.111871,0.602245,0.415530,-0.248177,-0.495616,-0.241400,-0.430458,0.026745,-0.484307,-0.616854,0.299284,-0.193830,-0.397042,0.564818,0.172480,0.064362,0.318884,0.035862,0.344867,-0.398317,0.295668,0.079951,-0.098256,0.063936,-0.007474,-0.136525,0.068579,-0.113548,-0.123498,-0.055132,0.050076,-0.187326,0.395580,0.612250,-0.533055,0.321509,-0.307385,0.217089,-0.142848,0.129826,-0.016792,0.233004,-0.125748,0.506758,0.203974,-0.033497,-0.366231,0.313956,0.036687,-0.523015,0.179292,0.444701,0.271539,-0.490036,0.326912,-0.315700,0.062645,0.056905,-0.170575,0.075118,0.367365,0.158941,0.151496,-0.277400,-0.277549,-0.558654,0.080628,0.299383,-0.030326,-0.113693,-0.087354,0.102448,-0.502729,0.249338,-0.194999,-0.381656,0.184832,0.437742,0.113575,0.052963,0.861371,-0.663242,-0.032678,-0.746190,0.080169,0.357260,-0.146592,-0.321019,-0.456715,-0.043250,-0.078163,-0.060683,0.138630,0.585674,-0.234976,0.513152,-0.424544,0.245257,0.382649,0.289867,-0.190688,0.485733,-0.220947,0.187930,-0.109267,-0.325227,0.396142,0.350279,0.379540,-0.312511,0.094547,0.134807,-0.390249,-0.385447,0.400830', '21619567', '1578663', '25884436', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432509', '电影往事', '剧情', '那是一个电影的黄金年代，喜欢看电影想当电影演员的女播音员江雪华（姜宏波 饰）未婚先孕，生下了同样喜欢看电影的女儿玲玲。江玲玲（关晓彤 饰童年版）上小学的时候认识坏孩子毛小兵（王正佳 饰），毛小兵有架神奇的望远镜，这架望远镜里能看到任何想看的电影，两个人因为电影成为好朋友，毛小兵走的时候把望远镜送给了江玲玲。后来同样是因为电影结缘，江雪华和电影放映员潘大任（李海滨 饰）结婚，不久便生下了儿子兵兵，玲玲（张懿靖 饰少年版）感觉自己在这个家的地位受到了威胁。后来一次意外，和玲玲爬上楼顶看电影的弟弟不慎坠落身亡，爸爸的一记耳光让玲玲离家出走。毛小兵已经长成了毛大兵（夏雨 饰），一次意外又让他遇到了几乎失聪还有精神不稳定的玲玲（齐中旸 饰青年版），从而揭开了一段尘封已久的往事。本片被誉为中国版的《天堂电影院》，曾获第7届长春电影节评委大奖以及其他多项国内外大奖。', '夏雨', '小江', 7.8, 10034, 'tt0424273', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1236264310.jpg', 1.8, 3.4, 24, 46, 24.8, '0.090338,-0.084331,-0.419461,0.386276,-0.029903,-0.408875,0.485276,0.169917,-0.403560,-0.061374,0.160155,0.715277,-0.417090,0.155283,-0.057047,0.186303,-0.275719,-0.749866,-0.108961,0.027788,-0.259945,-0.077314,-0.177513,0.021146,0.138207,-0.218306,0.433043,-0.205684,-0.225181,0.553769,0.369924,-0.071273,0.111983,0.080752,-0.113879,0.356918,0.072418,0.070724,-0.131630,0.244948,0.146407,-0.191364,0.002224,-0.019150,0.006720,0.184247,0.860825,0.050082,-0.145410,-0.222838,0.528187,-0.001374,-0.277206,-0.107784,0.207450,0.183123,0.437178,-0.310185,0.172691,0.070731,0.139386,0.010444,-0.285591,0.175114,0.155954,0.220020,-0.415969,0.455951,-0.166030,0.039238,0.167371,-0.192772,0.384092,-0.010977,0.343872,0.531213,-0.246305,0.267912,-0.449747,0.564374,0.458290,0.171062,0.040626,0.372648,0.123304,-0.435872,-0.104771,-0.093379,-0.547752,0.548009,0.578154,-0.248855,-0.195491,-0.003477,-0.505342,0.052841,-0.129419,-0.004029,-0.028108,-0.245288,-0.150159,-0.358922,-0.068527,-0.385379,-0.158116,-0.038663,-0.008195,-0.332049,0.696245,-0.486526,0.088416,0.250476,0.338621,-0.216843,0.865449,0.142106,-0.174294,-0.105906,0.192037,-0.042331,-0.182704,0.345928,0.094927,0.223985,-0.191668,-0.612481,-0.259305,0.328650', '3811356', '1307146', '1291564', '1306031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432669', '我是古巴', '剧情', '这是一部最伟大的电影，这是有史以来最具艺术性的电影，这是“诗电影”的最高境界。我是古巴，我是哈瓦那，我是退潮后礁石上千万干涸的泡沫。我是古巴，我是甘蔗，我是那连同家园一起燃烧的大片甘蔗。我是古巴，我是姑娘，我爱上了卖水果的小伙子，他开朗又善良，他每天欢快的歌唱，可我是妓女。我是古巴，我是雪茄，我热爱生活，热爱每天亲吻我的人，我不停地燃烧。我是古巴，我是音乐，一点点丰收的喜悦就值得我纵情歌唱，可谁又能听见我的悲伤？我是古巴，我们的身边不是海洋... 是抑制不住的泪，它流了下来，变成了鲜血。我是古巴，我是革命！我是掠夺者打不死的墙！我是古巴，我是解放。。。。。。这是一部64年拍摄的影片，但是却是一部超前了好几代的电影，由于政治原因，以致于当弗朗西斯·福特 科波拉和马丁·西塞克斯在2002年看到这部上个世纪的电影时，禁不住高呼，这是一部近十年来最伟大的电影，这是一部永远改变了人们对电影看法的电影！视觉上最美丽的电影，壮观的令人晕倒的电影，眼花缭乱的让人窒息的电影，优美高雅却让人流泪的电影，从技术上说这可以是一部无人能够超过的电影，从艺术上说这是诗电影的最高境界，但更重要的是 这是一部革命的史诗 共产主义的战歌，他虽然是上个世纪的产物但在今天 他却让人们对世界有了更新更清楚地认识。让所有被压迫的人手挽手地走在一起吧！让他们高举起共产主义的旗帜。共同为这世界谋求幸福吧！ 那些产生巨大影响的思想往往是极其朴素的：如果那些剥削者聚集在一起 可以形成一股力量的话，那么被剥削者也应该这样做，道理就这样简单。', '塞吉欧·柯瑞里', '米哈伊尔·卡拉托佐夫', 9.1, 11265, 'tt0058604', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2232357924.jpg', 0.4, 0.7, 5.3, 28.6, 64.9, '0.140945,0.014483,-0.623023,0.604373,-0.094781,-0.116042,0.885407,0.021412,-0.447893,0.347018,0.123364,0.786080,-0.064407,0.101959,-0.241498,0.485475,-0.227890,-0.667828,-0.097706,-0.045714,-0.074664,-0.167522,-0.241633,-0.090621,-0.039072,-0.257896,0.511969,0.244368,-0.566028,-0.035894,0.324835,0.137110,0.435221,0.379922,-0.308004,-0.069081,-0.319524,-0.158580,-0.061828,0.063698,0.201961,-0.321871,-0.117382,0.313322,-0.086420,0.146769,0.304540,0.015122,-0.161881,0.077252,0.469455,-0.409370,-0.052185,-0.035421,-0.195275,-0.146137,0.249070,0.193241,0.090861,-0.064382,-0.160129,-0.057163,-1.067452,0.002080,-0.059132,0.269859,-0.752680,0.603077,-0.143110,-0.228731,0.292082,-0.294976,0.386388,0.034108,0.147124,0.429635,-0.051844,-0.241727,-0.734811,0.564116,0.875342,0.181106,-0.271322,0.527145,-0.560460,-0.502984,-0.274678,-0.257512,-0.503315,0.070184,0.124217,-0.241945,-0.100376,0.074405,-0.668363,0.215602,0.131955,-0.503505,-0.018530,-0.489201,0.133599,-0.297233,-0.173179,-0.704733,-0.364278,-0.195922,0.063368,-0.556521,1.178784,-0.618000,0.078679,0.768907,0.261947,-0.291462,1.020821,0.221510,-0.421809,0.145843,0.145831,0.083929,-0.270210,0.204949,0.224131,0.499734,0.504165,-0.059925,-0.436527,0.872242', '27602116', '30162520', '26283288', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432699', '琳达！琳达！琳达！', '剧情', '芝崎高校2004年第34届文化祭开幕在即！几名女生为最后一天的演出而组建乐队，却因成员身上发生的意外临时换人，日语不甚灵光的韩国学生宋（裴斗娜 饰）被拉进队中任主唱一职，演唱歌曲也终于确定为THE BLUE HEARTS乐队的《LINDA LINDA》。自此孤傲冷艳的吉它手立花惠（香椎由宇 饰）、温柔的鼓手山田响子（前田亚季 饰）、闷声的贝斯手白河望（关根史织 饰）在业余时间勤加练习。平静的日子中不时有宋遭遇日本男生用蹩脚韩语表白，惠在前男友面前束手束脚等轻快的情节点缀，看似散漫的学校生活里记录下了年轻人的误会与默契，复合与分裂。乐队终于在大雨中登台，女孩们奉献出了心底的音乐……本片获2004年《电影旬报》十佳电影第六名。©豆瓣', '裴斗娜', '山下敦弘', 7.8, 7025, 'tt0468795', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p981572203.jpg', 0.6, 2.3, 28.8, 44.5, 23.8, '0.134783,-0.017019,-0.246103,0.557608,0.253737,-0.065792,0.581600,0.007863,-0.291348,-0.360848,0.101069,0.317377,-0.443434,0.348078,0.432560,-0.451616,-0.232438,-1.009135,-0.105557,0.027307,-0.026622,-0.114601,0.054650,-0.047486,-0.219167,-0.125615,0.607757,0.118440,-0.031874,0.719712,0.416493,0.137824,-0.089636,0.007140,0.078196,-0.166654,0.169271,0.310777,0.165750,0.078220,-0.150773,-0.710156,-0.340540,-0.237274,0.270364,0.312800,0.793431,0.047893,0.191474,0.036030,0.462313,-0.032130,-0.091537,-0.017562,0.279185,0.377735,0.255476,0.180836,-0.063916,0.132625,-0.309708,-0.319865,-0.454443,0.246088,0.224528,0.178291,-0.307838,0.643024,0.031111,-0.046027,0.222277,0.135741,0.100847,-0.056235,0.727848,0.355215,-0.076999,0.343136,0.037092,0.343914,0.342182,0.024427,-0.289140,0.321985,-0.205006,-0.600996,-0.190345,-0.100625,-0.264467,0.080195,-0.130873,-0.039678,0.398086,0.016499,-0.533959,-0.177976,0.235022,-0.022288,0.017398,-0.204731,-0.094707,-0.808992,0.183097,-0.234245,-0.055539,0.054535,0.084355,-0.007165,0.817281,-0.691270,0.122936,0.112344,0.063159,-0.143464,0.483743,0.126575,0.038865,-0.143304,-0.007697,0.119728,-0.170431,0.094167,0.143998,0.432685,-0.412994,-0.231064,-0.147648,0.242260', '5403927', '3811356', '26365262', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432825', '白毛女', '剧情', '在华北农村，佃户杨白老(张守维 饰)的女儿喜儿（田华 饰）和青年王大春（李白万 饰）正在相爱。地主黄世仁（陈强 饰）看中了喜儿，设下圈套，逼杨白劳把欠他家的六斗谷子年前连本带利还清。杨白老拿一冬的血汗钱七块五毛到黄家还利，被逼本利全清，否则用喜儿抵债。并硬逼他在女儿的卖身契上按了手印，除夕夜杨白老含恨喝下卤水自杀了，初一悲痛中的喜儿被抢进了黄家，不久被黄世仁奸污了，大春配合张二婶（管林仆 饰）搭救喜儿被发现，逃跑投奔了红军。后来二婶再次帮喜儿逃出了黄家，藏进了深山丛林里，喜儿靠捡奶奶庙的贡品和吃野果活命。非人的生活使喜儿的头发慢慢成满头白发。村子里有人看见，传说成收贡品的白毛仙姑。之后大春随部队回到家乡，展开减租减息运动，黄世仁利用白毛仙姑的传说企图动摇民心，为粉碎地主阴谋，大春带领乡亲夜间潜伏在奶奶庙，寻找白毛仙姑......©豆瓣', '陈强', '王滨', 7.3, 4954, 'tt0483468', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2495693786.jpg', 1.6, 4, 38.1, 38.6, 17.7, '0.012415,-0.098673,-0.257064,-0.030956,-0.276971,-0.473218,0.295259,0.393982,-0.294469,0.118706,0.200155,0.298801,0.005495,0.142797,-0.234642,0.118680,0.064911,-0.224477,-0.134267,-0.008437,-0.141051,-0.059381,0.036708,0.031040,-0.134744,0.061420,0.026828,-0.038768,-0.102284,0.336049,0.106582,-0.029977,-0.007414,-0.096979,-0.222813,0.553191,-0.088081,-0.196036,-0.183612,0.242261,-0.099895,-0.211613,-0.061015,-0.329509,0.169000,0.362411,0.687138,-0.248828,0.080878,-0.244172,0.037980,-0.042116,-0.288326,0.316195,0.125729,-0.026986,0.203828,0.039795,-0.307784,-0.103817,0.146137,-0.110547,-0.135546,0.168954,0.197399,-0.066947,-0.799293,0.095996,0.095875,0.237238,0.114017,-0.397271,0.338326,0.168133,0.037752,0.351765,-0.239074,0.038551,-0.756548,0.518427,0.217213,-0.468293,0.520509,0.068399,0.156711,-0.020230,0.509109,-0.137472,-0.186923,0.035946,0.423271,-0.293101,-0.261831,0.067917,-0.603704,-0.092219,-0.290274,-0.003125,0.183663,-0.075224,-0.427153,-0.158561,-0.339873,-0.046927,-0.059447,0.135399,0.315593,0.118187,0.410894,-0.052474,0.334308,0.196511,0.240668,-0.222066,0.336735,-0.213424,0.175691,-0.035487,0.109095,-0.241846,0.205504,0.645032,0.600528,0.176762,-0.310495,-0.093874,-0.108051,0.061399', '1306505', '1754628', '1394968', '1466273');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1432972', '妈妈再爱我一次', '剧情', '黄秋霞（杨贵媚 饰）与富家子弟林国荣（李小飞 饰）真心相爱，并已珠胎暗结，但在谈婚论嫁时两人被林母以黄秋霞身家不清白为由强行拆散，林国荣另娶了门当户对女子为妻，黄秋霞则投靠乡下姨母生下志强（谢小鱼、孙亚东 饰）独立抚养。 几年后，林国荣之妻被证实不能生育，林家父母为了延续香火，办法施尽令志强离开黄秋霞回到了林家认祖归宗，然而年幼的志强却无法接受没有母亲的生活，屡次试图重回母亲身边，却在某次尝试中遭遇大雨导致生命垂危，黄秋霞因为此事激动，失足跌下楼梯成为疯妇。©豆瓣', '杨贵媚', '陈朱煌', 8.3, 50897, 'tt0185520', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2196346882.jpg', 1, 2.2, 17.5, 40, 39.3, '0.152360,0.229247,-0.540975,0.087982,-0.256897,-0.551388,0.437679,0.201525,-0.774648,-0.486419,0.108699,0.621962,0.147103,0.338873,-0.098779,-0.014885,-0.129040,-0.336820,0.468262,0.050179,-0.123117,-0.395281,0.361868,0.075144,-0.392793,0.071130,0.672582,-0.171118,-0.080021,0.462507,0.012053,0.360507,-0.200402,0.206445,-0.213125,0.318961,-0.281221,0.215428,-0.774146,0.269716,-0.071265,-0.249937,-0.123665,-0.002908,-0.075228,0.221269,0.444166,-0.143434,0.142435,-0.613403,0.405594,-0.112963,-0.114815,0.499480,0.148162,0.047695,0.331508,0.347353,-0.369324,-0.127243,0.255707,-0.087125,-0.407982,0.304047,0.263606,-0.010284,-0.711392,0.301963,-0.184847,-0.227074,0.002036,-0.253564,0.104957,0.450409,0.232184,0.309437,-0.536452,0.267478,-0.444298,-0.000261,0.828878,0.080661,-0.088329,0.168440,-0.086230,-0.189785,0.609316,-0.495776,-0.505984,0.257724,0.029074,0.527495,-0.258436,0.343951,-0.007663,-0.040403,-0.594178,0.315958,0.142710,-0.443072,-0.227879,0.024968,-0.171802,-0.116894,-0.385938,-0.059574,0.043060,-0.499858,0.311369,-0.641529,0.190032,-0.138815,0.610816,-0.827819,0.404867,0.312866,0.434655,-0.318282,0.155492,0.333985,-0.239043,0.122759,0.048256,-0.331918,-0.338020,-0.004568,-0.174787,0.048196', '1302874', '1296978', '1308035', '1293315');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433156', '小曼哈顿', '喜剧', '和所有小学五年纪的小男生一样，住在纽约的10岁男孩Gabe（乔什·哈切森 Josh Hutcherson 饰）正遇到自己的小问题。首先，父母正在闹离婚，却因为美国法律不得不依然同住在一个屋檐下。其次，虽然之前Gabe总觉得同龄的女孩是这个世界上最可怕的生物之一，认为只要被她们触碰到身上机会长虱子，甚至相信只要被女孩碰了就会有倒霉的事情发生。但命运弄人，在参加空手道训练课时，他竟然坠入爱河，对分配给他的搭档兼他的同班同学Rosemary（查理·雷 Charlie Ray 饰）产生了好感。Gabe是否能够挽回父母的感情？他又会因为喜欢Rosemary做出什么疯狂的举动呢？©豆瓣', '乔什·哈切森', '马克·莱温', 8.2, 12595, 'tt0412922', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2212629650.jpg', 0.2, 1.2, 18.8, 48.7, 31, '0.208824,0.007923,-0.922268,0.278365,-0.453559,-0.083544,0.650211,0.062849,-0.451254,-0.290189,0.067981,0.860108,-0.312440,0.404392,0.167620,-0.090678,-0.001443,-0.744535,0.196033,-0.111473,-0.502217,-0.393101,-0.094093,-0.101526,-0.006528,-0.218149,0.526456,-0.072690,-0.374012,0.011957,0.367122,0.187322,0.155312,0.536272,-0.223086,-0.197579,-0.021524,0.359704,-0.059632,0.000224,0.070252,0.034797,0.073988,0.060575,0.033150,0.378453,0.519212,-0.302533,-0.516726,-0.211904,0.380763,-0.150911,-0.017713,0.242176,0.363972,-0.153571,0.426655,0.101210,0.054711,0.011277,0.336341,0.007091,-0.680398,0.205678,0.201654,0.107736,-0.626656,0.274783,0.132197,-0.077598,0.005696,-0.197129,0.196656,0.382116,0.359814,0.345519,-0.443253,-0.061980,-0.394193,-0.187734,0.815922,0.027284,-0.360172,0.368097,-0.288818,-0.322108,-0.148852,-0.323444,-0.329683,0.277084,0.019368,0.023821,-0.349314,0.161421,-0.249595,-0.036843,0.097996,0.025986,0.093104,-0.498386,-0.084158,-0.166857,0.011276,-0.559427,-0.612609,0.129241,0.229486,-0.439232,0.674424,-0.950930,0.200631,0.652796,0.566726,-0.575902,0.719384,0.532585,-0.084335,-0.266628,-0.111275,0.245544,-0.106087,-0.068866,-0.038062,0.216468,0.016783,-0.355263,-0.025295,0.561264', '1301022', '1308805', '4861627', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433232', '再说一次我爱你', '剧情', '高公乐（刘德华）原本是一名医生，由于太投入工作常常会将家庭忽略，直到妻子梁紫晴（蔡卓妍）因一次意外身亡，他才明白到家庭对他的重要，转职做了救护员，过上了有规律的生活，但对妻子的思念之情一直没有减少。阿Sam（杨采尼）患有严重心脏病，高太身亡后捐出的心脏令她获得新生，却也自此开始对丈夫Derek（刘德华）疑神疑鬼，终导致对方无法忍受弃她而去。阿Sam移植过来的心脏出现大问题生命垂危，高公乐偶尔发现她与几年前的自己十分相似后，决定替她寻回Derek的下落，而高公乐的举动，也令阿Sam明白了何为真爱。©豆瓣', '刘德华', '余伟国', 6.2, 24821, 'tt0483957', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p486988362.jpg', 2, 14, 60.3, 18.8, 4.9, '-0.109354,0.203637,-0.854427,0.336344,-0.071143,-0.405569,0.820156,-0.069821,-0.554578,-0.441113,0.065783,0.528252,-0.118953,0.189277,0.172697,-0.033108,0.031828,-0.588080,-0.003561,-0.163320,-0.600951,-0.341384,0.006255,-0.300004,-0.322425,-0.568267,0.547622,0.115274,-0.305503,0.302486,0.174393,0.366749,0.602025,0.720850,0.104271,0.218380,-0.244495,0.247717,-0.141190,0.130288,0.685469,-0.424840,-0.057396,0.368230,-0.017563,0.462995,0.772566,-0.141509,-0.519346,-0.161485,0.523706,-0.218301,0.039810,0.036407,0.291951,0.163374,0.065961,-0.105507,-0.323854,-0.060997,0.093436,0.298615,-0.610620,-0.114318,0.158037,0.053602,-0.624859,0.156936,-0.230838,-0.068749,0.007644,-0.489318,0.184928,0.496190,0.417802,0.460461,-0.258375,0.103014,-0.224352,0.112468,0.966974,-0.175014,-0.229385,0.480040,-0.416869,-0.700975,0.061832,-0.202924,-0.340676,0.115936,0.111261,0.186426,-0.106297,0.320784,0.004372,-0.081030,-0.319697,-0.175972,-0.023477,-0.296922,0.060221,-0.064294,-0.071524,-0.232124,-0.245414,-0.048180,0.013826,-0.519758,0.617799,-0.796815,0.552302,0.502799,0.330158,-0.816313,0.537568,0.280877,0.110982,-0.425134,0.086486,0.424099,0.071249,0.076868,0.196657,-0.180818,0.010900,-0.030294,-0.290377,0.293612', '1292064', '4861627', '1301022', '1494897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433330', '哈利·波特与混血王子', '奇幻', '这一集中，食死徒开始肆无忌惮横行于麻瓜和魔法两个世界中，霍格沃茨内忧外患，危机重重。邓不利多（迈克尔·甘本 Michael Gambon 饰）带着哈利（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）辗转找到隐居多年的霍拉斯·斯拉格霍恩，请他出山接替斯内普（艾伦 ·里克曼 Alan Rickman 饰）担任魔药学的老师。霍拉斯曾经教授过无数优秀的学生，而汤姆·里德尔——伏地魔——正是他最出色的一名弟子。邓不利多深信霍拉斯保有伏地魔不死身的秘密，他希望哈利能够说服霍拉斯。另一方面，德拉科·马尔福（汤姆·费尔顿 Tom Felton 饰）宣誓效忠伏地魔，他想方设法将食死徒引入霍格沃茨。而此时，罗恩（鲁伯特·格林特 Rupert Grint 饰）、赫敏（艾玛·沃特森 Emma Watson 饰）他们却还沉浸在青春的躁动中，全然不知黑暗正渐渐逼近……', '丹尼尔·雷德克里夫', '大卫·叶茨', 8.2, 488337, 'tt0417741', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1108070214.jpg', 0.4, 2.3, 20, 39.3, 38, '0.188666,-0.098916,-0.463338,0.587389,-0.007963,-0.436595,0.507376,-0.142738,-0.412908,-0.539433,0.126319,0.531555,-0.030186,0.362428,0.090956,0.105705,-0.512431,-0.583222,0.078003,-0.034867,-0.212089,-0.622581,-0.448749,-0.591250,-0.509024,-0.569363,0.267910,0.102299,-0.069190,0.169135,0.254115,0.689097,0.177915,0.109245,0.268908,-0.154343,0.403269,-0.246526,-0.150398,0.204128,0.100329,0.134163,-0.371370,0.245496,0.194685,0.169375,0.334452,-0.481038,0.301900,-0.139285,0.183125,-0.280869,0.053444,0.248779,0.296060,-0.213679,-0.024487,0.049608,-0.088728,-0.097095,-0.310220,-0.110445,-0.431172,-0.072523,0.019285,0.407193,-0.408441,0.314259,-0.106515,0.339586,0.379435,-0.257968,-0.554189,0.165678,0.099838,-0.108284,0.054314,-0.121044,-0.158758,-0.103524,0.202678,-0.214747,-0.311259,-0.162356,-0.518389,-0.281330,0.178233,0.044377,-0.582039,-0.271196,0.394313,-0.103505,0.478572,0.749560,-0.436346,-0.363888,-0.546265,-0.030053,0.032065,-0.097461,-0.141517,-0.800856,0.095108,-0.178785,-0.001134,-0.172331,-0.137698,-0.256057,0.722709,-0.632581,0.513268,0.382267,0.058286,-0.100151,0.502801,-0.210405,0.342446,-0.257473,-0.348243,0.767303,0.450707,0.094868,0.265896,0.069016,0.195448,-0.020465,-0.211951,0.449703', '6560058', '25955779', '2132932', '3075921');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433360', '雏菊', '剧情', '阿姆斯特丹，两个男人爱上了同一个女人，注定了一段纠缠的故事。惠瑛（全智贤饰）是画家，每天到广场帮路人画肖像，而像她一样风雨不改的，还有某人送来的一盘雏菊。每天雏菊总是准时送到，让她心里悸动而好奇。一天，匆匆而过的正佑(李成宰 饰)遇上了画家。他本是国际警察，来这个城市追捕杀手，然而却迷上了温婉动人的惠瑛，他让惠瑛帮他描肖像，他们的爱情在萌发盛开。这些情景，送花人看在眼里，痛在心里。他的身份注定了他必须给正佑让出位置，对惠瑛默默付出。因为，他就是正佑所寻找的杀手朴义(郑宇成 饰)。但是，强烈的爱终究让他不再躲在暗处，他决心争取幸福。二人在法律上，感情上的鲜明对立，注定了不能完满的结局，鲜血在惠瑛描有雏菊的花布上蔓延开来……©豆瓣', '全智贤', '刘伟强', 8.1, 250012, 'tt0468704', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200540002.jpg', 0.3, 1.8, 21.3, 46.3, 30.3, '0.176826,0.137396,-0.775861,0.530488,-0.249028,-0.150240,0.780120,0.247840,-0.332278,0.295725,0.360417,0.649720,-0.099673,0.228299,0.172384,0.203753,-0.128140,-0.666435,0.192943,-0.258432,-0.170771,-0.247227,-0.170718,-0.404741,-0.025858,-0.158918,0.688475,0.169986,0.124615,0.419934,0.461902,0.033613,-0.088002,0.457766,-0.270369,-0.106812,0.071623,-0.061209,-0.132575,0.030862,0.031802,-0.500733,-0.153705,0.303890,-0.313473,0.254042,0.577686,-0.161024,-0.190624,0.121627,0.384592,-0.502429,-0.038892,0.045746,0.036938,-0.009050,0.138179,-0.085445,-0.344479,-0.109320,0.116565,0.002063,-0.563972,-0.093455,0.319978,0.374341,-0.668611,0.729990,-0.143118,-0.081457,0.176694,-0.376489,0.214577,-0.144300,0.258609,0.152201,-0.210434,-0.118968,-0.560925,0.322239,0.761967,0.305651,-0.115620,0.474096,-0.416264,-0.004567,-0.118486,-0.235948,-0.388709,-0.006863,0.261158,-0.223908,-0.249634,-0.037205,-0.590795,0.090733,-0.045449,-0.008450,0.025327,-0.572804,-0.106258,-0.264713,-0.235095,-0.444439,-0.394219,0.171357,0.062201,-0.318508,0.789975,-0.717627,0.346984,0.795119,0.141295,-0.485483,0.775092,0.283934,-0.152656,-0.101828,0.158853,0.274706,-0.103370,0.236551,0.101637,0.297350,-0.178909,0.259885,-0.445021,0.514993', '3230462', '30162520', '1783772', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433556', '欢迎来到东莫村', '剧情', '朝鲜战争期间，在江原道附近一个叫东莫村的偏僻小山村。那里的人们与外界隔绝，过着自给自足的生活，他们竟不知外面有发生战争。韩国国军的表铉哲（申河均饰）和卫生员文尚相（徐宰庆饰）由于逃营和掉队，来到东莫村。与此同时，朝鲜人民军的李秀华（郑在泳饰）和老兵张荣熙（林河龙饰）以及少年兵徐泽基也到了东莫村。而在此之前，因为飞机坠毁，美国飞行员史密斯大尉（斯蒂芬•泰休勒饰）也来到了村子。当双方士兵碰面时，剑拔弩张，后来才由紧张对峙渐渐平和下来，互不侵犯，但还是有很大敌意。在与淳朴的村民接触中，士兵们习惯了东莫村安宁的生活。后来战火即便降临到村子头上，双方的士兵们决定肩负起保卫东莫村的任务。©豆瓣', '申河均', '朴光铉', 8.2, 60483, 'tt0475783', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1171939157.jpg', 0.4, 1.9, 18.3, 48, 31.5, '0.403384,-0.189020,-0.845732,0.202805,0.195890,-0.052687,0.747609,-0.002266,-0.679142,-0.145506,0.370292,0.564480,0.049296,0.135553,0.362662,-0.422239,-0.548786,-0.675606,-0.329222,-0.105307,-0.396854,-0.284477,-0.252383,-0.144637,-0.447878,-0.391901,0.646766,0.260363,-0.196548,0.698436,0.061288,0.156956,-0.314684,0.525551,-0.131479,-0.097212,0.066758,-0.066471,-0.472509,-0.205779,-0.231012,-0.142987,-0.473698,-0.126707,0.472009,0.476405,0.740794,-0.270089,-0.397802,0.098964,-0.222314,-0.060002,-0.055743,-0.015656,0.653442,0.010894,0.163154,0.070186,0.195247,0.171513,-0.457698,-0.009258,-0.095255,0.334363,-0.074062,0.162370,-0.499774,0.686654,0.267709,-0.225163,-0.009375,-0.421147,0.399683,0.612190,0.028348,0.228033,-0.387102,-0.010250,-0.371569,0.039720,1.051132,0.014095,-0.401473,-0.074724,-0.432527,-0.528956,-0.130650,-0.236872,-0.564339,0.072645,0.192478,-0.123908,-0.149044,0.275060,-0.659197,0.181806,-0.219618,-0.371118,0.033868,-0.207566,-0.171388,-0.744717,-0.045791,-0.545276,-0.274519,0.504978,-0.039735,0.268068,0.775986,-0.916876,0.171716,0.226123,0.420951,-0.291818,0.401265,-0.056649,0.310454,-0.115794,-0.106961,0.186346,-0.076923,0.562033,0.306794,0.224441,-0.444950,-0.001874,-0.184605,0.089589', '25721544', '35030151', '1826173', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433557', '你是我的命运', '剧情', '石忠（黄政民 饰）是一个淳朴的农村男孩，把全部的心血都放到了他所经营的牧场中。他希望有一天，自己能够遇到一个善良美丽的女孩，并能够与之结婚。终于，他遇到了少女银荷（全度妍 饰），石忠便被这个时尚的女孩吸引了。石忠全力向银荷展开追求的攻势，但银荷刚开始十分看不起这个乡下小子，但最终都为石忠的真心实意感动。两人结婚了，原本以为这段婚姻能给双方带来幸福。但事实上银荷是有个不堪的过去的，是有关她的前一段婚姻……©豆瓣', '全度妍', '朴珍杓', 7.8, 7066, 'tt0479773', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2176563405.jpg', 0.7, 2.4, 27, 45, 25, '0.542292,0.036058,-0.809883,0.608285,-0.384994,-0.474815,0.669016,-0.297796,-0.400228,-0.067836,0.285030,0.681728,-0.035895,0.368718,0.094465,0.286386,0.177679,-0.612041,-0.057374,-0.251742,-0.091257,-0.341778,-0.289971,0.245888,-0.402384,-0.094416,0.653822,-0.097303,0.158527,0.347892,0.308390,0.073540,0.309684,0.541240,-0.193296,0.263894,-0.144738,0.005757,-0.193580,0.121671,0.081819,-0.105183,-0.182670,0.588581,-0.132555,0.479467,0.607077,-0.248452,-0.319313,-0.085417,0.585472,-0.100924,-0.130136,0.379471,0.134588,0.082376,0.359063,0.146811,-0.322311,-0.042455,0.184799,-0.084231,-0.820000,-0.024134,0.021600,-0.174421,-0.638314,0.434066,0.276051,-0.270678,0.107314,-0.615576,0.236312,0.498472,0.401093,0.440538,-0.302117,-0.067736,-0.628344,0.192136,0.809176,-0.083494,-0.304623,0.844948,-0.541984,-0.320931,0.058420,-0.226241,-0.670450,0.257212,0.354023,0.091254,-0.235933,0.064119,-0.599613,0.236190,-0.199948,-0.094370,0.061059,-0.565853,-0.213162,-0.073585,-0.428291,-0.749080,-0.545321,0.009674,0.091358,-0.418024,1.037402,-0.919271,-0.113088,0.516124,0.144721,-0.489954,0.586858,0.353439,0.280674,0.143547,-0.025934,0.023573,-0.244548,0.262781,0.067853,0.567355,0.104447,-0.184153,-0.365234,0.409408', '26283288', '24284209', '1309161', '1303112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433577', '赛末点', '剧情', '穷小子威尔顿（乔纳森•莱斯•迈勒斯）为改变自己的命运，从爱尔兰来到伦敦当起网球教练，立誓要凭一身网球绝技混入对该运动情有独钟的上流社会。结识富家公子哥汤姆后，他得到机会，对方的妹妹克罗伊（艾米莉•莫蒂梅尔）对他一见钟情，其后，在对方的父亲的相助下，威尔顿顺利混入上流社会。正当要与克罗伊谈婚论嫁时，威尔顿邂逅汤姆的女友、来自美国的女演员诺拉（斯嘉丽•约翰逊），后者同样在为进入上流社会做着不懈的努力。相似经历令两人萌生真情，但威尔顿并没为诺拉放弃自己的计划。一切梦想都成真后，威尔顿重遇已与汤姆分手的诺拉，两人旧情复燃，威尔顿开始在她与妻子之间周旋。不久，诺拉怀孕坚拒堕胎，威尔顿迎来人生的赛点。©豆瓣', '乔纳森·莱斯·梅耶斯', '伍迪·艾伦', 8.1, 168597, 'tt0416320', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p685837045.jpg', 0.3, 1.3, 18.6, 52.9, 27, '0.126932,-0.036925,-0.600698,0.352041,-0.069282,-0.492624,0.516783,0.172622,-0.215300,-0.379036,0.407961,0.892781,-0.412016,0.115751,0.346855,0.045117,-0.595984,-0.832689,0.250299,0.137958,0.196256,-0.635727,-0.388203,0.190295,-0.131990,-0.483796,0.533654,-0.012739,0.118965,0.499610,0.083684,0.174347,0.193765,0.232850,-0.122616,0.085517,0.166703,0.157986,-0.785252,0.343254,0.194525,0.114014,-0.449893,0.188634,-0.078060,0.127182,0.382145,-0.093011,0.365387,0.006307,0.196301,0.005256,0.241996,0.386395,-0.218982,-0.176421,0.137227,0.351709,-0.084899,0.253562,0.103552,0.091974,-0.447599,0.187524,-0.068714,0.128164,-0.440324,0.269810,-0.643502,-0.028528,0.102635,-0.206287,-0.466897,0.524964,0.283667,0.288035,-0.355386,0.379161,-0.381417,-0.363474,0.894524,-0.029128,-0.262992,0.161691,-0.058447,-0.306536,0.008696,-0.043266,-0.420234,-0.185233,0.154097,0.104763,0.289949,0.679613,-0.479174,-0.171995,-0.467510,0.185026,0.258810,-0.192847,-0.223894,-0.803336,-0.301523,-0.097695,-0.388119,-0.328961,0.283865,-0.477742,0.500595,-0.955192,0.178339,0.372655,0.243449,-0.480080,0.398262,0.024515,0.213976,-0.404148,-0.362426,0.521573,0.040822,0.291436,0.053099,0.350374,0.195843,0.101403,-0.030492,0.646132', '11541282', '26971054', '30345227', '1297239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433602', '赌圣2：街头赌圣', '喜剧', '赌圣退休后，赌坛再起风云，各路好手都想争夺赌王的位置。世界赌王大赛即将拉开帷幕，旨在夺冠的澳门赌霸雷泰（林国斌 饰）为了掩人耳目，想制造出另一蒙面赌圣分散众人注意力。另一方面，自赌圣退隐后，三叔（吴孟达 饰）生活潦倒，于是前往天神村寻找赌圣的接班人。三叔发现村民阿葛 （葛民辉 饰）拥有特异功能，认为他就是赌圣的接班人，于是拉他一起闯荡江湖。在赌场内，他们遇上了泰国赌后豪姬（彭丹 饰），并得悉她正准备暗杀少女缘份（邱淑贞 饰）及她的弟弟小龙（释小龙 饰）。阿葛对缘分一见钟情，於是与三叔联手对付豪姬，救回了缘份。原来缘分是雷泰的女友，随后她带阿葛他们去见雷泰。雷泰任务阿葛正是蒙面赌圣的适合人选。赌王大赛终于开幕了！©豆瓣', '葛民辉', '王晶', 6.2, 14679, 'tt0112909', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2477767085.jpg', 4.6, 17.7, 50.4, 18.5, 8.8, '-0.165022,-0.151293,-0.435937,0.134607,-0.125294,-0.191576,0.201555,0.060348,-0.456078,-0.270915,0.375216,0.724526,-0.030256,0.198034,0.286510,0.074359,-0.255493,-0.583086,0.054646,-0.200266,-0.182343,-0.113958,-0.198681,0.053616,0.031244,0.053713,0.625110,0.035209,-0.178354,0.584094,0.576141,0.012846,-0.208135,0.187552,-0.221506,-0.056138,-0.043430,0.098833,-0.718908,0.236752,-0.244686,-0.051754,-0.248919,0.020343,0.093067,0.310951,0.348384,-0.120563,0.438369,-0.211154,0.007662,-0.132393,-0.158273,-0.135703,0.250379,-0.027186,0.359444,0.233868,0.037356,-0.074707,0.006198,-0.156792,-0.478679,0.363700,0.338795,0.046717,-0.238695,0.205556,0.032259,-0.195843,0.000367,-0.105295,0.248179,0.289735,0.433394,-0.123561,0.055943,0.006389,-0.235874,0.420439,0.508730,-0.126482,0.471583,0.296712,0.335312,-0.473723,0.182927,-0.369742,-0.086002,0.108001,0.382520,0.005852,0.122449,0.011809,-0.341211,-0.127968,-0.028796,0.167719,0.263926,-0.168561,0.245132,-0.573529,-0.099874,-0.053447,-0.113000,-0.048797,0.081777,-0.259351,0.566870,-0.700072,-0.053795,0.467539,0.241373,-0.533118,0.547695,0.030009,0.213654,-0.454401,-0.182331,-0.047007,-0.117317,0.404605,0.008649,0.215046,0.034628,-0.345329,-0.101288,0.160316', '4301278', '1780122', '3230460', '1305441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433673', '怪物史瑞克3', '喜剧', '怪物王子和恐龙公主的故事在继续。史莱克原以为可以和费奥娜在沼泽地过上自由散漫的生活，谁知道费奥娜的父亲，变成青蛙的“遥远王国”国王病重，史莱克和费奥娜不得不放弃自由，继承王国。对史莱克而言，“祸不单行”：费奥娜怀孕了，显然他没有做好当爸爸的准备。因为不想继承王国，也因为即将出生的小怪物，史莱克带着话痨驴子和穿靴子的猫，一同去找菲奥娜的远方堂弟亚蒂，在他们的软磨硬泡之下，懒散的亚蒂终于答应接过王位这个烫手山芋，四人开始了热闹非凡的回国之旅。与此同时，在国内陪伴父母的费奥娜公主也遇上了不小的麻烦，大反派“魅力王子”纠结了一帮海盗卷土重来，阴谋篡位，费奥娜组织了一支妇女自救队，童话中的公主、母后们悉数上场，展开了搞笑连连的正义之战，及时赶王国的史莱克一行四人，也参加到了队伍中，“另类”大决战的序幕也就此拉开。©豆瓣', '麦克·梅尔斯', '克里斯·米勒', 7.4, 68513, 'tt0413267', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2221540858.jpg', 0.5, 3.5, 38.5, 42.7, 14.9, '0.259914,0.043221,-0.631421,0.478927,0.138692,-0.076162,0.680658,0.012570,-0.364382,-0.058113,0.173576,0.899582,0.030478,0.226867,0.456015,0.073589,-0.659101,-0.385995,0.019363,-0.078189,-0.242076,-0.553523,-0.037288,-0.265516,0.026401,-0.446016,0.718504,-0.081602,0.007856,0.849148,0.458611,0.016113,0.064612,0.369368,-0.102375,0.247691,0.231835,-0.011898,-0.165163,0.225391,0.090237,0.033971,-0.295063,0.269654,0.379152,0.149681,0.529432,-0.829995,0.418859,-0.266268,0.240916,-0.613739,0.134357,0.193290,0.501659,-0.250120,0.160865,0.165132,0.196834,-0.191898,-0.017978,-0.377286,-0.609718,0.275470,0.046863,0.011544,-0.622882,0.576244,-0.071003,-0.030257,0.373824,-0.278560,0.204346,0.481963,0.156975,0.164441,-0.210873,0.240582,-0.710577,0.020559,0.729160,0.055613,-0.162869,0.120841,0.230144,-0.634959,-0.196030,-0.431295,-0.513987,-0.118974,0.401626,-0.046928,-0.182190,0.362635,-0.520580,-0.066887,-0.470870,-0.349263,0.270420,-0.513702,-0.160174,-0.340867,0.019887,-0.264838,-0.149219,0.306603,0.091552,-0.005512,0.643349,-0.800902,0.117335,0.521299,0.433506,-0.501050,0.511857,-0.026832,0.424530,-0.040846,-0.141713,0.218930,0.064233,0.351381,0.540454,0.347239,0.054139,-0.191070,-0.408731,0.405868', '25721544', '35030151', '2072478', '27042738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433676', '卧底肥妈2', '喜剧', 'FBI探员马刚（马丁•劳伦斯 Martin Lawrence 饰）最近和妻小闹得很不愉快，家人总是责备他太忙于工作而疏忽了照顾家庭。马刚这边正闹得情绪低落，却又有大案件找上了他。原来某日政府机关的电脑突然全部死机，过后发现很多绝密文档都被人浏览过了。FBI怀疑电脑工程师汤姆（马克•摩斯 Mark Moses 饰）有重大嫌疑，却又一直都找不到证据，于是只好派马刚再次出山。军命难违，本来不愿意再增加工作的马刚只有再次化身成肥胖的老妈子，以保姆身份混进了汤姆的家。在这里，他却意外发现了一个喧哗的世界，他和家里的三个孩子玩得不亦乐乎，亦知道了重拾天伦之乐的方法……©豆瓣', '马丁·劳伦斯', 'John Whitesell', 6.8, 9157, 'tt0421729', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p925227410.jpg', 1, 6.6, 52.9, 30.7, 8.8, '0.339007,-0.159080,-0.606622,0.282402,-0.126771,-0.395814,0.527441,0.220448,-0.693084,-0.399636,-0.076338,0.572366,-0.038725,0.334188,0.008002,-0.057605,-0.535720,-0.529405,0.114077,-0.229881,-0.274474,-0.442581,-0.087800,-0.279186,-0.162689,-0.086540,0.018627,-0.176845,-0.006477,0.191406,0.088081,0.048826,-0.000020,0.807075,-0.023655,0.136581,0.089695,0.089638,0.183822,-0.127474,0.200254,-0.211690,-0.252676,0.253489,0.199303,0.466567,0.299896,0.063394,-0.460810,-0.029389,0.225032,-0.153849,-0.070255,-0.245942,0.482956,-0.038489,0.285632,0.070017,-0.270521,-0.062587,0.088596,0.104366,-0.694643,0.226848,-0.012169,0.199381,-0.419891,0.277703,-0.350600,-0.118053,-0.151377,-0.321979,0.250464,0.488504,0.262183,0.369573,-0.179181,0.003460,-0.538239,0.219518,0.344718,0.065067,-0.115776,0.368313,-0.193796,-0.288924,0.184427,-0.289186,-0.270005,-0.020729,0.286361,0.110297,-0.190884,0.108113,-0.421651,0.104154,-0.274484,-0.208682,-0.191129,-0.540990,0.019250,-0.527509,-0.002812,-0.154712,-0.389035,0.155440,0.096711,-0.046771,0.492776,-0.729468,0.097970,0.639445,0.221102,-0.661439,0.565758,0.166577,0.094772,-0.254857,-0.005657,-0.234405,0.076203,0.542999,0.272431,0.094782,0.152138,-0.516145,-0.362244,0.186847', '35073886', '1293434', '1308206', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433701', '上甘岭', '剧情', '抗美援朝进入最关键的决胜阶段了。美军在板门店谈判期间，暗中调集大量军队，发动突然袭击。美军目标很明确，就是攻占上甘岭，以此作为据点，进而夺取五圣山，一次增加谈判的筹码。在上甘岭守卫的是中国人民志愿军某部八连。面对比我方多得多的敌军，志愿军没有退缩，而是选择了顽强抵抗， 以此拖延美军时间，粉碎敌人阴谋。连队在连长张忠发（高保成 饰）的带领下，与美军浴血奋战。虽然坑道里的环境恶劣，而且面临着断水断粮的危险，但是志愿军硬是坚守了24天，为中朝联军大反攻奠定了坚实的基础。©豆瓣', '高保成', '沙蒙', 8.3, 16449, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2537259656.jpg', 1.1, 1.5, 17.7, 39.6, 40.2, '-0.041336,-0.084544,-0.870616,0.726181,0.180292,0.283409,0.310494,-0.175444,-0.160914,0.172737,0.462633,0.317391,0.509693,-0.522159,0.023032,-0.631347,-0.226505,-0.641368,-0.144302,-0.050838,-0.399630,-0.566318,-0.621467,-0.210888,0.006671,-0.356534,1.069888,0.533674,-0.594054,0.079714,-0.090060,0.188648,0.345813,0.666650,0.203102,-0.211140,0.000125,-0.735855,-0.328592,0.503094,-0.174145,-0.420676,-0.321991,0.270889,0.092690,0.773655,0.598188,-0.493717,-0.056507,-0.038419,-0.079938,-0.646218,-0.085988,0.049348,0.554484,0.132374,0.052255,0.092596,-0.072784,0.205126,-0.168711,-0.283911,-0.808922,-0.031473,0.086753,-0.217907,-0.633530,0.610154,-0.076895,0.376564,0.352561,-0.344701,0.102338,1.095051,0.278248,-0.110131,-0.674323,-0.112339,-0.510840,0.061129,0.699532,-0.259506,-0.146258,-0.137754,0.129190,-0.254870,0.211211,-0.516778,0.034124,-0.192537,0.183317,-0.181694,0.304558,0.080946,-0.580152,0.249920,-0.499753,-0.480789,0.097440,-0.241756,-0.085837,-0.814826,0.053676,-0.186078,-0.169536,0.658237,0.109206,0.124919,0.810341,-0.867923,-0.220983,0.574071,0.570240,-0.422452,0.357658,0.401725,0.030236,-0.101777,0.215492,0.244433,-0.183821,0.572318,0.176500,0.004210,-0.311686,-0.207786,-0.214201,0.384663', '1291860', '1424551', '5157137', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433702', '红与黑', '剧情', '故事发生在法国一个偏僻的小镇上，我们的主人公于连（吉姆·罗斯·斯图尔特 Kim Rossi Stuart 饰）就出生在那里。身处乱世，于连从小就有远大的理想，虽然出生卑微，但他仍怀有着挤进上流社会的幻想，并为此不断的做着努力。19岁之时，于连成为了市长雷纳尔（贝尔纳·维尔莱 Bernard Verley 饰）家的家庭教师并和市长夫人路易斯（卡洛尔·布盖 Carole Bouquet 饰）之间产生了暧昧关系，东窗事发后，于连被迫离开了小城。几经波折，于连成为了拉莫尔侯爵（克劳德·里奇 Claude Rich 饰）的私人秘书，侯爵的女儿马蒂尔德（朱迪丝·哥德雷科 Judith Godrèche 饰）爱上了于连。从马蒂尔德身上，于连看到了飞黄腾达的希望，然而，路易斯的一封信揭露了于连灰暗的过去，并将他的希望彻底打碎。©豆瓣', '卡洛尔·布盖', '让-丹尼尔·维哈吉', 8.3, 6629, 'tt0137320', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2674000257.jpg', 0.2, 0.9, 14, 52.6, 32.3, '0.235294,0.185266,-0.745111,0.439147,0.075413,-0.552157,0.647124,0.185573,-0.765603,-0.399432,-0.177222,1.141453,-0.339765,0.185552,0.676949,-0.116925,-0.231554,-0.793690,-0.071928,0.041295,-0.056665,-0.758104,-0.281335,-0.221197,-0.463366,-0.497097,0.373685,0.184419,-0.043961,0.239018,0.513093,0.453457,-0.106412,0.288594,-0.144933,0.147685,-0.118972,-0.223070,-0.638866,0.145304,0.012230,-0.104345,0.109609,-0.221816,0.212757,0.203474,0.433700,-0.523088,-0.014405,-0.141896,0.352538,0.034060,0.060468,0.284726,0.023102,-0.013124,0.185921,0.327664,-0.126410,0.071851,0.657359,-0.284075,-0.671256,0.011709,0.145573,0.489063,-0.536326,0.643268,-0.187577,-0.237511,0.024104,-0.406138,0.216156,0.212868,-0.199246,0.222634,-0.405017,0.024338,-0.728093,-0.199826,0.327204,0.297519,-0.494501,0.110057,0.047956,-0.353435,-0.051702,-0.285469,-0.514656,0.156751,0.208878,0.368345,-0.235153,0.373081,-0.499020,-0.199240,-0.338512,-0.354205,0.363412,-0.451645,-0.193802,-0.416152,0.108662,-0.537611,-0.476023,-0.018789,-0.074149,-0.272112,0.385067,-0.973112,0.441210,0.203789,0.249492,-0.173031,0.653237,-0.010262,0.347666,0.347378,-0.054057,0.476544,0.058454,0.378407,0.366258,0.291145,-0.224944,-0.246969,-0.102502,0.506632', '30484534', '1293145', '1783461', '1898357');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433736', '古惑仔之人在江湖', '动作', '陈浩南（郑伊健 饰）、山鸡（陈小春 饰）、巢皮等人从少年时代起就是好友。他们无心读书，一心向往江湖生活。终于有江湖人士大佬B收纳为徒，开始闯荡江湖。浩南在一次黑帮仇杀中大展拳脚，杀死了黑道大哥巴闭，因此与另一头目靓坤( 吴镇宇 饰)结下深仇。靓坤设法加害浩南，令浩南兄弟巢皮惨死，而浩南误服药物与山鸡女友发生关系，兄弟间开始积怨。浩南心灰意冷，打算收手，怎料大佬B遭全家灭门，自己经营的店铺被烧毁，靓坤的步步相逼令浩南忍无可忍。©豆瓣', '郑伊健', '刘伟强', 7.9, 122591, 'tt0116456', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2637722859.jpg', 0.6, 1.7, 24.6, 49.1, 24, '0.139595,-0.446317,-0.442481,0.001380,0.182817,-0.140270,0.432655,0.194787,-0.565474,-0.213752,0.242658,0.588699,-0.181101,0.284125,0.110714,-0.251151,-0.012623,-1.001285,0.163903,-0.225786,0.292053,-0.074090,0.046455,-0.182944,-0.191805,-0.022913,0.630116,0.153692,-0.234410,0.576928,0.215526,0.130765,-0.434952,0.120716,-0.043430,0.155403,0.029654,-0.046823,-0.825914,-0.284594,-0.136649,-0.165852,-0.127517,-0.052377,0.147692,0.200575,0.619772,0.011227,-0.074004,-0.399126,0.057439,-0.134672,-0.291112,-0.050580,0.506083,0.046977,0.239101,0.497024,0.192072,-0.208504,0.038022,-0.015466,-0.400871,-0.017388,0.318000,-0.022662,-0.460018,0.450650,-0.147169,0.054858,-0.261775,-0.138353,0.027408,0.266148,0.450927,-0.120560,0.048289,0.090519,-0.495825,0.318101,0.880000,-0.044984,0.550468,-0.055264,0.400720,-0.020419,0.243377,-0.293394,-0.120560,-0.297907,0.478834,-0.361089,-0.420020,0.651292,-0.234873,-0.082827,-0.095796,0.360131,0.233384,-0.208580,-0.080047,-0.379752,-0.468271,0.000741,-0.051369,0.208988,0.322523,-0.104391,0.711840,-0.929260,-0.027432,0.066985,0.370210,-0.507967,0.287205,-0.203499,0.104265,-0.224403,-0.280537,-0.089725,0.298042,0.099964,0.441759,-0.070955,-0.187254,-0.065325,0.047015,-0.499272', '30345227', '1480318', '35030151', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1433990', '风雨哈佛路', '剧情', '丽兹（索拉·伯奇 Thora Birch饰）出生在美国的贫民窟里，从小就开始承受着家庭的千疮百孔，父母酗酒吸毒，母亲患上了精神分裂症。贫穷的丽兹需要出去乞讨，流浪在城市的角落，生活的苦难似乎无穷无尽。随着慢慢成长，丽兹知道，只有读书成才方能改变自身命运，走出泥潭般的现况。她从老师那里争取到一张试卷，漂亮的完成答卷，争取到了读书的机会。从现在起，丽兹在漫漫的求学路上开始了征程。她千方百计申请哈佛的全额奖学金，面试时候连一件像样的衣服也没有。然而，贫困并没有止住丽兹前进的决心，在她的人生里面，从不退缩的奋斗是永恒主题。©豆瓣', '索拉·伯奇', '彼得·勒文', 8.1, 146288, 'tt0338109', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2184507337.jpg', 0.6, 2.3, 20.3, 44.2, 32.6, '0.156688,0.156787,-0.711962,0.407630,-0.356929,-0.461519,0.667895,0.198265,-0.246545,-0.087502,0.108085,0.605733,0.294208,0.464250,0.193300,-0.034124,-0.257580,-0.622951,0.087904,-0.204325,-0.530056,-0.481001,-0.201983,-0.156083,-0.185751,-0.268483,0.585758,0.236690,-0.156148,0.351111,0.050194,-0.059171,0.127060,0.341795,-0.392412,0.015027,-0.086274,0.203342,-0.287067,0.231582,0.214078,-0.135686,-0.316274,0.099918,0.244997,0.232361,0.730416,-0.132525,0.051219,-0.040817,0.576254,0.005581,-0.267604,0.127106,0.048281,0.077803,0.140960,0.236515,-0.126274,0.240763,0.022878,-0.315978,-0.529231,-0.351292,-0.026855,0.403826,-0.809101,0.540221,0.064940,-0.136941,0.139004,-0.555262,-0.002316,0.283441,-0.091655,0.535235,-0.325862,0.067246,-0.650739,0.569643,0.699986,-0.148708,-0.428257,0.410451,-0.337179,-0.235337,0.089043,-0.316076,-0.720167,-0.226103,0.285124,0.201272,-0.529970,0.187649,-0.441061,0.208501,-0.148847,-0.364781,0.042055,-0.277655,-0.267490,-0.476513,-0.134602,-0.180975,-0.249322,0.175059,-0.237325,-0.619565,0.738698,-0.866483,0.249926,0.731008,0.360170,-0.399922,0.660065,-0.035347,0.395605,0.055234,0.173423,0.503697,-0.202148,0.714313,-0.005262,0.174129,-0.051561,0.106403,-0.488167,0.863556', '1864491', '1301169', '1292719', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1434172', '铁道游击队', '战争', '抗日战争时期，鲁南临城、枣庄一带的铁路线上活跃着一支游击队，队员在大队长刘洪（曹会渠）、政委李正（冯奇）的领导组织下，配合主力部队给予了日军沉重的打击，被当地百姓亲切地称为“飞虎队”。日军想方设法偷袭“飞虎队”，终使刘洪受伤，但刘洪因此得以被寡妇芳林嫂（秦怡）照料，成 就一对爱人。刘洪伤愈后，配合李正指挥作战，大败日军。恼羞成怒的日军欲以肆意杀戮之法激怒刘洪，刘洪中计，准备在微山湖与日军展开正面交锋，幸得李正及时劝阻，“飞虎队”力量才得以保全。修整后的“飞虎队”将沿线日军悉数歼灭，但芳林嫂却在执行侦察任务时被捕。©豆瓣', '曹会渠', '赵明', 7.6, 14921, 'tt0354964', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2251435268.jpg', 1.4, 2.4, 29.6, 47.1, 19.5, '0.044355,0.118935,-0.704635,0.513019,-0.063958,-0.168076,0.241066,0.098437,-0.568790,0.451476,0.570244,0.061701,0.312743,-0.207231,0.092981,-0.291128,-0.307593,-0.834980,-0.155584,0.237346,-0.128229,-0.260474,-0.314535,-0.090465,-0.012160,-0.364187,0.441157,0.208525,-0.196420,0.503660,-0.116851,0.220202,-0.052315,0.642055,0.291091,0.160505,0.103525,-0.866196,-0.291422,0.111526,-0.307053,-0.444499,-0.318925,-0.035699,-0.134340,0.481184,0.919182,-0.131081,-0.079589,-0.377584,-0.099244,-0.491804,0.245373,0.337484,0.581316,0.269852,0.021222,-0.141219,-0.220245,0.071803,-0.204116,0.139046,-0.483635,-0.101530,-0.041015,-0.046256,-0.493910,0.441496,-0.201580,0.527170,0.216618,-0.531499,0.015982,0.924779,0.257500,0.053071,-0.383408,0.133755,-0.135805,0.113566,0.489612,-0.405621,-0.122702,-0.388591,0.016992,-0.341415,0.254748,-0.200541,-0.189203,-0.286608,0.576837,-0.238711,0.268861,-0.103794,-0.486908,-0.212713,-0.557422,-0.001744,-0.356205,0.097834,0.011126,-0.771832,0.153003,-0.118807,-0.293663,0.456765,0.193799,0.188994,0.603805,-0.540014,-0.020803,0.581080,0.102691,-0.294081,-0.178721,0.263928,0.191782,-0.047060,0.189896,0.090131,0.144065,0.670084,0.527438,0.539745,-0.597349,-0.090193,-0.112921,0.067971', '1307201', '1431694', '1464618', '1296909');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1434257', '美国派(番外篇)4：集体露营', '喜剧', '硬条家族的一员——麦特（泰德•希根布尔克 Tad Hilgenbrink 饰）即将升入高三，他对家族前辈们的业绩羡慕不已，立志也要拍出一部刺激的个人电影作品，但是麦特的为人教人难以欣赏，嚣张的他把欢送毕业生的表演变成了一场闹剧，校方为了惩罚麦特，要求他加入仪队夏令营，如此麦特和担任仪队指挥的青梅竹马伊丽丝（阿莉尔•凯贝尔 Arielle Kebbel 饰）再次相聚，但伊丽丝厌恶麦特的种种恶作剧早已与其反目成仇。夏令营对渴望得到奖学金的伊丽丝意义重大，但是麦特却只顾用买来的各种偷拍设备为自己的香艳小电影搜集素材，或是与夏令营的明星队员作对。玩世不恭的麦特渐渐体会并理解了周围人群的追求，他与伊丽丝的裂痕也在渐渐弥合，这次夏令营会成为麦特的成长之旅么？©豆瓣', '尤金·列维', 'Steve Rash', 6.3, 21079, 'tt0436058', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1446477261.jpg', 2.6, 14.6, 54.2, 20.7, 8, '0.183977,-0.123161,-0.343868,0.667215,0.123364,-0.227235,0.489083,0.209638,-0.358312,-0.166295,0.150545,0.831123,-0.361573,0.172304,0.216818,-0.098185,-0.433507,-0.767205,0.052406,-0.107333,-0.048403,-0.406099,-0.139747,-0.310380,0.075527,-0.381620,0.823863,0.100883,-0.260947,0.650945,0.299651,0.194096,0.159781,0.404706,0.029137,-0.162847,0.043854,0.115494,-0.240094,-0.081629,-0.059903,-0.056479,-0.355685,0.213064,0.187825,0.311123,0.690288,-0.064066,0.006951,-0.160504,0.349692,-0.376194,0.176087,0.225598,0.005938,0.105355,0.141919,0.081399,-0.089636,0.142906,-0.136945,-0.190998,-0.960097,0.042276,0.046695,0.103360,-0.299592,0.560724,0.078014,-0.052395,0.128494,0.049992,0.028200,0.325551,0.215518,0.475952,-0.255828,-0.021544,-0.319617,0.276620,0.556409,-0.056098,-0.048523,0.392736,-0.447981,-0.395282,-0.059085,-0.380609,-0.652088,-0.074948,0.158203,0.124823,0.008054,0.404484,-0.647799,-0.185255,-0.220229,-0.246934,0.033524,-0.582036,0.061876,-0.863632,-0.107259,-0.287409,-0.295326,-0.165095,0.171830,-0.543181,0.885489,-0.798701,0.114627,0.456040,0.157315,-0.589564,0.730009,0.143813,-0.078295,-0.146675,-0.411213,0.245521,0.005065,-0.027027,0.037261,0.349652,0.270829,-0.330548,0.006222,0.534914', '3811356', '4301278', '27602116', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1434269', '黑炮事件', '剧情', '赵书信（刘子枫 饰）是某矿山公司的工程师，为人忠厚，工作勤勉。下棋是赵书信为数不多的爱好之一，他对自己那副棋子也格外珍惜，却于一次出差归来时发现丢失了一枚，情急之下冒雨前往邮局，发了一封“黑炮丢失301找赵”的电报给旅馆，寻找棋子。岂料这封电报招致邮局方面的怀疑，上报 公安局立案侦查，上升成了所谓的“黑炮事件”。 受此事件影响，赵书信被调离原来岗位，更阻止其参与正在进行的德国合作项目。公司将精通德语的专家赵书信换成了旅游翻译冯良才，工程进度和质量受到重大影响。不久，邮局送来一个寄给赵书信的邮包，矿山公司高层领导秘密将其打开，发现里面竟是一颗棋子…… 电影《黑炮事件》获广播电影电视部优秀故事片奖 、第6届中国电影金鸡奖最佳男演员奖（刘子枫）。©豆瓣', '刘子枫', '黄建新', 8.6, 30267, 'tt0091190', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2591996324.jpg', 0.2, 0.7, 9, 47.6, 42.6, '-0.013519,0.154259,-0.474817,0.783940,0.144209,-0.042308,0.341884,0.107395,-0.595626,-0.432936,-0.331376,0.422633,-0.199283,0.085216,0.088423,-0.277587,-0.164756,-0.527984,-0.249692,-0.137971,-0.254954,-0.457058,-0.167166,-0.283489,-0.121364,0.007760,0.329189,0.108137,-0.624497,0.254362,0.584456,0.280093,-0.136478,0.609127,0.232708,0.013899,0.116454,-0.034622,-0.210051,0.146544,0.422520,-0.623011,0.178771,-0.013093,0.498177,0.218944,0.631380,0.370022,-0.328129,-0.256359,0.759542,-0.222558,-0.083015,-0.319157,0.586464,0.516301,-0.264464,-0.021755,-0.370067,0.003236,0.319233,-0.495122,-0.444974,-0.276605,0.307147,0.186183,-0.410022,-0.177841,-0.451968,0.505229,-0.368235,-0.371433,0.571824,0.359543,0.351774,0.077498,0.242490,0.071896,-0.497530,0.591181,0.194670,-0.247140,0.011717,-0.175424,-0.103023,-0.773511,0.347464,0.025036,-0.048694,0.538329,0.748913,-0.111561,0.387757,-0.384910,-0.311701,-0.312956,-0.114309,-0.415643,0.154752,-0.467677,0.091725,-0.906593,0.162736,-0.068073,-0.334949,0.034744,0.250583,-0.181587,0.670049,-0.043670,0.062233,0.249244,-0.035131,-0.725527,0.704268,-0.035918,0.162694,-0.410784,0.332649,0.062344,0.628767,0.463331,0.078135,-0.203468,-0.143982,-0.457712,-0.160233,0.109014', '1295276', '2027945', '19977815', '4078562');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1434270', '红楼梦第一部：宝黛相会', '剧情', '声名显赫的京城贾家分荣、宁二府。荣公长孙贾赦，独一子名贾琏。次孙贾政娶王氏，生子名珠，早逝；次女元春，选为贵妃；又得一子，因口中衔玉，玉又有字，名宝玉。宝玉不爱读八股文，却偏爱和女孩子搅在一起。贾政妹妹贾敏嫁扬州林如海，膝下一女，名黛玉。黛玉11岁丧母，林如海将其送到贾 府依伴外祖母史太君。黛玉与宝玉初次见面，竟无一点生疏。王夫人胞妹嫁于薛家，女儿宝钗知书达理。为宝钗选女官，薛姨妈合家进京，客居贾家。贾府为迎元妃省亲，特修省亲别墅——大观园。元月十五，亲人得一日相聚。', '夏菁', '谢铁骊', 8, 4467, 'tt0106772', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2538647106.jpg', 0.8, 2.2, 21.9, 47.3, 27.8, '0.002902,0.235898,-0.538061,0.649102,0.015542,-0.779347,0.625742,0.625348,-1.253310,-0.206219,0.465135,0.594686,-0.488826,0.379471,-0.174987,0.258547,0.281719,0.230064,0.189489,-0.139455,0.277027,-0.122125,0.639080,0.076825,-0.320919,0.190247,-0.059238,-0.362934,0.483744,-0.107055,-0.073870,0.053280,-0.261531,-0.045464,-0.300572,0.720164,-0.877637,-0.093147,-0.132641,-0.332595,-0.201132,0.013947,-0.846663,-0.535428,0.551425,0.081835,0.664118,0.040224,0.763024,-0.726848,0.653619,0.823518,-0.058909,0.481338,0.531090,-0.242351,0.167842,0.070491,-0.037170,-0.374065,0.026405,-0.167415,0.308725,0.592449,0.675358,-0.189316,-0.306445,0.236664,-0.485970,-0.281730,-0.567432,-0.299552,0.339928,0.332553,-0.385814,0.333743,-0.399529,0.237899,-0.343625,0.802501,0.117496,-0.128937,0.279030,-0.071747,-0.166830,-0.426986,0.518582,-0.373411,-0.523903,-0.090033,0.378739,0.076548,0.391181,0.400510,0.315172,-0.191264,-0.528279,0.498815,0.639504,-0.456179,0.082956,0.138544,-0.008349,-0.289898,-0.676486,-0.165448,0.919390,0.187587,0.359468,0.076641,0.149305,0.098827,-0.100970,-0.676325,0.395336,0.165233,0.929946,-0.330345,0.116382,-0.315934,-0.321713,-0.425470,0.040687,-0.013997,-0.446451,0.014423,-0.130116,0.100659', '1303176', '1484633', '1297213', '1308162');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1434272', '三毛流浪记', '剧情', '解放前的旧上海，大资本家、军阀、投机商人、洋人、流氓、骗子横行于世，他们过着养尊处优、挥金如土的腐败日子，而底层人民则穷苦不堪，生活艰辛。大头、圆鼻子、三根头发、瘦小身材，这个外貌滑稽的男孩就是本片的主人公三毛（王龙基 饰）。三毛自幼失去父母，无依无靠的他终日在上海街头流浪，身无分文的他饿极了甚至吃刷广告的浆糊，困了就睡在垃圾车里。为了生存他送报纸、推黄包车、捡烟头，然而霉运却总尾随其后，所有的事都以失败告终。他好心做善事，反遭到诬陷和殴打。不过，生活在黑暗底层的三毛始终保持着诚实善良的性格，他从不愿为一口饭而沦为他人做恶的工具……本片根据著名漫画家张乐平同名连环画改编。©豆瓣', '王龙基', '赵明', 8.3, 19202, 'tt0470084', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2533593090.jpg', 0.3, 0.8, 14.8, 51.8, 32.3, '0.139586,-0.070066,-0.372651,0.247614,-0.279256,-0.284226,0.602580,0.423072,-0.248024,-0.118504,0.216634,0.601615,0.234737,0.267228,0.056889,0.000805,-0.296744,-0.586162,-0.096082,0.144744,-0.028478,-0.066967,-0.180663,-0.433054,-0.273208,0.087373,0.424030,0.114935,-0.169878,0.201042,0.308634,-0.033562,-0.089778,0.066548,-0.545396,0.146794,-0.209485,0.018930,-0.025903,-0.167025,-0.084596,-0.349837,-0.145044,-0.102699,-0.012323,0.246487,0.587147,-0.163778,-0.146987,-0.265095,0.310498,-0.310491,-0.409508,0.066624,0.246232,0.070224,0.401441,-0.142351,0.025623,0.227048,0.287862,-0.053094,-0.563865,-0.152452,-0.074174,0.106977,-0.684450,0.667119,0.075830,-0.090712,-0.013350,-0.285273,0.046729,-0.098912,0.229212,0.373757,0.030047,0.177288,-0.361494,0.621805,0.476193,0.094100,-0.366632,0.279002,-0.502650,-0.077476,0.294008,-0.666224,-0.550909,-0.237971,0.061734,-0.419996,-0.451585,0.486223,-0.588566,0.304291,0.006524,-0.071233,-0.079657,-0.028899,-0.396462,-0.217351,-0.100349,-0.475820,-0.141781,0.074412,0.208848,-0.090804,0.665253,-0.375502,0.120143,0.546667,0.075964,-0.480331,0.557549,0.103199,-0.016281,0.038684,-0.195077,0.399418,0.183547,0.290752,0.067821,-0.074398,-0.111069,-0.139142,-0.234904,0.474632', '1908036', '25882279', '30162520', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436679', '人形师', '恐怖', '这是一个关于复仇的故事。几百年前，小山村中的一名男子依照他的未婚妻的形貌做了一个真人大小的玩偶，随后，他的未婚妻离奇惨死，男子成了最大嫌疑对象。村民们认定就是男子杀了他的未婚妻，将他残忍处死。那具人偶就放在了男子的坟前。数百年过去了。一天，美术馆馆长（郑柔美 Yu-mi Jeong 饰）路过发现了这具栩栩如生的人偶，将她带回了美术馆收藏。人偶其实早已具有了灵魂和法力，她如今终于找到了机会为自己的主人，也是自己深爱的男子报仇。于是她控制了馆长的身躯，并威逼馆长的弟弟帮她实现报仇计划……©豆瓣', '金有美', '郑勇基', 6.6, 17571, 'tt0416853', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2064209420.jpg', 1.5, 10.5, 51.7, 27.6, 8.7, '0.041273,0.128435,-0.416270,0.538921,-0.624060,-0.286669,1.069401,-0.082772,-0.503856,-0.165084,0.344743,0.803450,0.131224,0.502488,0.324544,0.360266,0.040820,-0.685422,-0.156121,-0.289574,-0.372571,-0.213280,-0.315194,-0.272013,-0.039241,-0.398864,0.718579,-0.040268,0.008166,0.099726,0.212485,0.028043,0.064078,0.257904,-0.269536,0.185646,-0.048267,-0.267477,0.043624,0.275212,0.000996,-0.469388,0.241928,0.453998,-0.500844,0.482839,0.715114,-0.317680,-0.294115,-0.276451,0.393956,-0.212643,0.026502,0.219188,0.091314,-0.052351,0.275255,0.309547,-0.257397,-0.307788,0.238570,-0.338332,-0.707037,0.005686,0.183592,0.013579,-0.788955,0.618369,-0.049640,0.267085,-0.098973,-0.457755,0.342103,0.006837,0.042435,0.196501,-0.296648,-0.098185,-0.507739,0.570613,0.374617,-0.017410,-0.073529,0.302042,-0.022997,-0.333299,-0.153530,-0.194645,-0.176130,0.048366,0.416952,0.037171,-0.292905,0.031888,-0.545288,-0.376227,-0.481876,0.197926,0.078668,-0.336905,-0.106934,-0.079921,-0.157844,0.025704,-0.122469,-0.105427,-0.023885,-0.445614,0.772214,-0.612936,0.178920,0.674645,0.280939,-0.485999,0.592325,-0.328834,0.183256,-0.219721,0.196310,0.073971,0.075213,0.440086,0.248321,0.377988,0.138250,-0.060865,-0.462348,0.643607', '21619567', '1467779', '26884422', '10486471');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436680', '毁灭战士', '动作', '影片根据1993年同名射击游戏改编而成。2145年火星舰队总部接到从该地区传来的微弱求救信号，而在那里科学探测站正在进行着遗传密码破解的重要实验，一旦该地区失去控制，无疑将会造成整个人类的一场大劫难。特别行动队队长瑞博尔（卡尔·厄本 Karl Urban 饰）、士官长萨吉（道恩·强森 Dwayne Johnson 饰）带着六名队员迅速登陆以救援基地内的幸存者，可当他们进入基地时，发现实验室不仅一片狼藉，而且实验室里满是怪物。更可怕的是，这些行为怪异的生物并非来自外星，而是受到某种未知病毒感染后的人类！面对随时可能被感染的危险，萨吉必须和他的队员们利用手中的每一件武器，深入到实验室中心，找出真相，完成他们的使命。RRTSRTS惟一可以做的是把通往地球的通道用免疫隔离系统封锁，再背水一战，用尽身上每一件终极武器，将这班魔怪一一歼灭……©豆瓣', '卡尔·厄本', '安德泽·巴特科维卡', 6.2, 12776, 'tt0419706', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1590143933.jpg', 3.5, 16.2, 54.5, 19.1, 6.7, '0.232634,0.100625,-0.577082,0.513481,-0.001739,0.403955,0.645076,-0.525054,-0.362109,-0.180286,0.291182,0.428449,0.161321,-0.049413,0.066607,-0.097620,-0.245821,-0.535709,-0.319915,-0.356143,-0.801520,-0.521346,-0.424729,-0.298007,0.175335,-0.562401,0.781722,0.220219,-0.447653,-0.068702,-0.010235,0.562205,-0.261767,0.368232,0.171153,-0.480380,-0.041223,-0.337045,-0.280727,0.255749,-0.047466,0.019897,0.023432,0.181633,0.000729,0.236398,0.684571,-0.681406,-0.258409,-0.188533,0.418587,-0.370892,-0.011283,0.017739,0.380371,0.262290,-0.121304,0.216452,-0.026483,0.207678,0.118954,-0.081501,-0.940726,-0.304784,0.197702,0.072673,-0.194863,-0.016781,-0.107762,0.091711,0.208784,-0.415233,0.330024,0.507257,0.256106,0.352680,-0.300975,-0.032787,-0.488272,-0.058175,0.499212,-0.438172,-0.437722,-0.096862,-0.037500,-0.467598,-0.168139,-0.273198,-0.251055,0.106652,0.095299,0.445642,0.017861,0.230328,-0.653992,0.138734,-0.142351,-0.634395,0.041234,-0.334375,-0.126673,-0.996089,0.062719,0.043088,-0.112475,0.387905,0.147732,-0.192123,0.792401,-0.722339,0.187829,0.635260,0.291710,-0.435188,0.239168,-0.388949,0.215863,-0.363444,-0.102589,0.190118,0.245193,0.687549,0.139166,0.374823,0.075568,-0.292544,-0.401342,0.292900', '2369613', '25774050', '2051813', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436768', '时光驻留', '剧情', '浪漫之都法国，拥有迷人气质的摄影师罗曼（梅尔维尔·珀波 Melvil Poupaud 饰）在工作中突然晕倒，经诊断发现他已罹患晚期癌症，去日无多。突如其来的打击，令罗曼内心百感交集，也许他隐隐意识到即使拍摄过那么多精美的照片，却无法留住行将消逝的生命。罗曼取消接下来的工作，与父母和姐姐苏菲（Louise-Anne Hippeau 饰）聚餐。纵然事先练习，依然无法道出真相，只得徒劳付诸言语的伤害。此外，他还要面对相守多年的男孩——同性恋人萨沙（Christian Sengewald 饰），接近黄昏的疲惫爱情，可堪这段生死考验？生命最后的旅途，关于生死最后的体验。与不同的人交错过往，随后分开。也许生就注定是一段孤独的旅程，直到终点，无人陪伴……©豆瓣', '梅尔维尔·珀波', '弗朗索瓦·欧容', 8.1, 17911, 'tt0417189', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2244194842.jpg', 0.3, 1.2, 20.1, 51.4, 27.1, '-0.243590,-0.004446,-0.692475,0.336376,0.098587,-0.345499,1.010033,-0.066007,-0.266590,-0.320641,0.305852,0.412126,-0.163980,0.333192,0.427301,-0.240586,-0.288604,-0.623497,0.232080,-0.031459,-0.134029,-0.504083,-0.367731,0.214194,0.029311,-0.291917,0.778595,0.256546,-0.023573,0.493450,-0.034556,0.125210,-0.171890,0.507679,0.154581,-0.168482,-0.029986,0.337618,-0.518696,-0.244590,0.239001,-0.264326,-0.161533,0.231557,-0.135240,0.265578,0.631390,-0.259459,-0.198398,0.122738,0.693682,-0.091988,0.020669,0.074928,-0.078147,0.143462,0.267945,0.353563,-0.176728,0.031169,-0.146213,0.292805,-0.795355,0.135120,0.167249,0.158191,-0.472598,0.368994,-0.109498,-0.070491,0.008771,-0.344844,0.065793,0.394387,0.307573,0.412899,-0.193502,-0.006730,-0.310876,0.252146,0.772676,-0.035513,-0.519596,0.551367,-0.227868,-0.305207,-0.047515,-0.313773,-0.261828,0.168261,0.055007,0.409834,-0.311560,0.392428,-0.397711,0.073767,-0.204213,-0.123684,0.135402,-0.270985,-0.066838,-0.614410,-0.140579,-0.360239,-0.467925,0.104644,0.256127,-0.300108,0.582844,-0.515860,0.339686,0.432704,0.138772,-0.270396,0.493786,0.425869,0.057268,-0.197761,0.044212,1.003757,-0.356429,0.410299,-0.036845,-0.014571,0.112469,0.299295,-0.667597,0.538094', '6039412', '1291835', '25828589', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436846', '驱魔', '剧情', '律师艾琳（劳拉·琳妮 Laura Linney 饰）接到一桩官司。一名神父由于用宗教手段——驱魔仪式来治疗女孩艾米莉的重病，因而使得艾米莉耽误了正确的药物治疗时间。法庭上，一场宗教与科学之争展开了。事件的开端，源于19岁女大学生艾米莉（珍妮弗·卡彭特Jennifer Carpenter饰）的恐怖遭遇。她在大学宿舍睡觉时，感觉有灵异恶魔来侵，接下来更为惊悚的事情陆续发生。艾米莉一反常态，她变得双眼发黑，行为怪异，整日活在犹豫恶魔缠身的梦魇中，艾米莉无法控制自己的意志，痛苦得生不如死。家人为她找来精神病医生，却毫无起色。无奈下，请来神父（汤姆·威尔金森 Tom Wilkinson 饰）一探究竟，才得知艾米莉被远古六恶魔上了身。万魔缠身的她，只有通过宗教仪式进行驱魔，才有可能逃出生天。神父的驱魔并没有挽救艾米莉，还引来了控告。无神论者却认为，恶魔缠身是无稽之谈。', '劳拉·琳妮', '斯科特·德瑞克森', 7.5, 24931, 'tt0404032', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p622236579.jpg', 0.8, 3.4, 32.1, 46.9, 16.9, '0.078143,-0.134259,-0.333621,0.070661,-0.085872,-0.040276,0.864804,-0.124409,-0.527470,-0.447732,0.397379,0.262853,-0.147729,0.035739,0.431163,-0.033904,-0.317340,-0.441726,0.194735,0.005036,-0.191644,-0.235851,-0.371420,-0.169195,-0.017180,-0.695537,0.315014,-0.132822,-0.109903,0.163553,0.069135,0.557110,-0.017903,0.309307,0.110609,-0.096223,0.002880,0.034782,0.087360,0.135848,0.332924,-0.217259,-0.227909,0.243179,-0.242532,0.386058,0.231545,-0.297356,-0.193070,-0.326482,0.397553,-0.235835,-0.153823,0.342183,0.342568,0.084077,0.036508,0.135884,-0.048555,-0.133210,0.273436,0.159769,-0.726957,0.034409,0.149332,0.396767,-0.155298,0.229011,-0.261708,-0.034736,-0.005312,-0.431686,-0.076670,0.289498,0.611560,0.345348,-0.018550,-0.163909,-0.315749,-0.036738,0.465286,-0.157267,-0.582702,0.265572,-0.348762,-0.367333,0.221607,-0.257932,-0.302342,0.130998,0.177824,0.024876,-0.255973,0.521841,-0.333724,-0.371145,-0.482578,-0.201252,-0.256818,0.079982,0.007981,-0.622975,-0.206798,0.038401,-0.313066,-0.186548,0.251322,-0.231855,0.457260,-0.656033,0.539558,0.679647,0.239975,-0.150760,0.372071,-0.085243,0.284972,-0.177687,-0.167527,0.305198,-0.070226,0.525134,0.160892,0.150902,0.079411,0.083233,0.023160,0.333696', '10440076', '3005387', '1292528', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436870', '死神来了3', '惊悚', '高中生Wendy（Mary Elizabeth Winstead饰）与友人一起去游乐场庆祝毕业，大家玩得十分痛快。游乐场内灯火璀璨，却诡异处处。在坐上过山车的座椅时，Wendy忽然看到了怪异现象，心生恐怖，男友Jason安慰她不过是幻觉。过山车开动起来，可是在半空中突然出轨，大家倒挂空中。Wendy眼看着朋友一个一个坠落死亡，自己也不能幸免于难。被同学的吆喝喊醒的Wendy惊觉刚才不过是幻觉，但是她忧心忡忡，力阻大家离开过山车。虽然遭到大家的嘲笑，但是事后证明这是正确的选择。过山车就如同Wendy看到的一样出事了。然而，逃过一劫的少男少女们并没有脱离死神的魔掌。他们接二连三地死去。Wendy发现这一切都与在游乐场的一张照片有关。为了生存，她开始了与死神的搏斗。©豆瓣', '玛丽·伊丽莎白·温斯特德', '黄毅瑜', 7.2, 145198, 'tt0414982', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1332895335.jpg', 0.6, 4.6, 44.3, 36.8, 13.6, '0.655102,-0.104478,-0.854850,0.271468,0.037188,-0.206696,1.044016,0.085284,-0.444408,-0.220975,0.392656,0.852302,-0.673769,0.432533,0.026925,0.128888,-0.369065,-0.698626,-0.096281,0.128821,-0.258052,-0.208851,-0.054162,-0.116582,-0.178957,-0.010913,0.438610,0.122767,0.046913,0.707307,0.236230,-0.071779,0.017730,0.591013,-0.404538,-0.171099,-0.481174,0.228235,-0.006454,0.059872,-0.065446,-0.256810,-0.223960,0.255738,0.045763,0.215082,0.525784,-0.347073,-0.354467,0.049298,0.181688,-0.463798,-0.020165,0.337623,0.199328,0.147898,0.147186,-0.282954,0.012789,0.036217,0.025463,0.043930,-0.459102,0.193521,-0.148868,0.263943,-0.404148,0.385245,0.199361,-0.002839,0.218456,-0.098291,0.501685,0.093727,0.217527,0.416813,-0.558479,-0.099941,-0.622233,-0.030608,0.865999,0.078240,-0.315483,0.448329,-0.213711,-0.367002,-0.204065,0.045935,-0.301867,-0.028577,0.201226,0.278800,-0.378509,0.128610,-0.560225,0.154178,-0.085938,-0.253514,-0.563126,-0.568421,-0.160833,-0.468821,-0.039751,-0.180420,-0.333183,0.271029,-0.268223,-0.360683,0.535283,-0.934173,0.195597,0.598684,0.218533,-0.188353,0.555994,0.127027,-0.228100,-0.010090,0.034471,0.003339,0.038202,0.301283,0.045658,0.302532,-0.231280,0.262458,-0.463766,0.494001', '1296534', '1308755', '4275444', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436891', '大偷袭', '剧情', '太平洋战争初期，美军将兵力投入欧洲战场，无力挽回菲律宾战事，导致一万名美军、六万名菲军在巴丹半岛被俘。日军一直残酷对待这些战俘，军部更于1944年一月决定屠杀俘虏，这部电影，讲述的就是发生在44年一月四天中的故事。游骑兵上尉普林斯分属幕西中校的队伍，他们接受了在麦克阿瑟将军北上过程中营救某战俘营里500名美军的任务，由于日军对待战俘毫不留情，此次行动必须高度隐秘。同一时间，战俘营中的少校吉布森（约瑟夫•费因斯 Joseph Fiennes 饰）正艰难的为生存和获取外界信息而努力，虽然当地有护士玛格丽特等人想法设法为战俘提供帮助，但缺药的状况一直存在。为执行屠杀命令，宪兵军官长井接管了战俘营，而战俘营外，游骑兵战士们经过秘密行军终于抵达了目的地，营救成败，很快就要揭晓……©豆瓣', '本杰明·布拉特', '约翰·达尔', 7.2, 7885, 'tt0326905', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1590312703.jpg', 0.6, 3.5, 41.5, 41.9, 12.5, '-0.142713,0.005648,-0.368720,0.316015,0.224539,0.164092,0.190457,-0.411429,-0.596271,-0.279331,0.272346,0.358540,0.385998,-0.258011,0.459536,-0.179886,-0.658423,-0.809682,-0.316435,-0.233544,-0.332604,-0.591644,-0.153197,-0.605192,0.066978,-0.522590,0.776290,0.489776,-0.154661,0.314149,-0.025053,0.311789,-0.137333,0.367822,0.243515,-0.185664,0.530151,-0.612476,-0.409253,0.212481,-0.379379,-0.305241,-0.227549,-0.066595,0.316650,0.526773,0.794405,-0.377489,-0.092517,-0.059447,-0.201273,-0.385958,-0.005681,0.050280,0.573609,0.206870,0.139185,0.358749,0.003992,0.222725,-0.349880,-0.234863,-0.560419,-0.239508,-0.081781,0.117745,-0.203516,0.240748,-0.244065,0.618547,0.319030,-0.187584,-0.164168,0.805616,0.209941,0.128065,-0.347109,-0.061065,-0.319952,0.247467,0.727266,-0.314510,-0.144238,-0.220408,-0.072656,-0.464278,0.225892,-0.436858,-0.084664,0.072698,-0.073562,0.037442,0.038613,0.367364,-0.279237,0.176028,-0.493475,-0.642313,0.027423,-0.138068,-0.127154,-0.866676,0.016694,0.023607,-0.160018,0.277363,0.154892,0.252987,0.870222,-0.401211,0.084323,0.432014,0.374743,-0.563598,0.333807,0.182187,0.322597,-0.167432,0.470169,0.300069,-0.041256,0.409195,0.082163,0.005639,-0.354352,-0.314290,-0.180350,0.185873', '2369613', '6007281', '5403927', '1291860');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1436998', '阿修罗城之瞳', '动作', '江户时代魔鬼横行，为了对抗伪装成人类的魔鬼，一群有志之士成立了一个名叫“鬼御门”的组织。其中一个高手病叶出门(市川染五郎 饰 )，被称作“杀鬼者”，五年前他神秘地离开组织，来到第四代鹤屋南北(小日向文世 饰)开办的剧场做演员。此时在江户出现了一个名叫“暗夜的茶花”的盗贼， 实际上她们是一群表面上以云游表演为生的女子，其中最美的是一个叫椿(宫泽理惠 饰)的女子。病叶偶然邂逅了椿，两人相爱了。假扮成尼姑的恶鬼首领美惨(樋口可南子 饰)，无意中发现了椿肩膀上的阿修罗王的标记，可是椿对此一无所知，在美惨的推波助澜下，在病叶与椿结合的一瞬间真相终于浮出水面。鬼王阿修罗重生，阿修罗城出现在了世人面前。©豆瓣', '市川染五郎', '泷田洋二郎', 6.9, 6086, 'tt0459744', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p607218137.jpg', 1.8, 8.9, 45.6, 30.4, 13.3, '0.360719,0.067589,-0.334437,0.485417,-0.131954,0.088995,0.907932,0.033531,-0.349114,-0.345690,0.468594,0.701651,-0.190893,0.178740,0.253256,0.113679,0.033914,-0.620038,-0.216254,-0.327678,-0.217524,0.014345,-0.442116,-0.118775,-0.226508,-0.266305,0.889994,0.249616,-0.048829,0.365912,0.466095,0.462722,-0.412245,0.154419,-0.172689,-0.069673,0.084558,-0.069034,-0.024954,0.434023,-0.543680,-0.368830,-0.157324,-0.077540,-0.437375,0.159174,0.789758,-0.472018,-0.029854,-0.291722,0.217080,-0.199596,-0.255119,0.188148,0.617112,-0.149109,0.251468,0.164624,-0.079876,-0.110371,0.017568,-0.148267,-0.482666,0.028639,0.190700,0.500840,-0.685441,0.225850,0.128578,-0.240346,0.199541,-0.264197,0.352931,0.260580,0.313610,0.243210,0.098654,0.175592,-0.477377,0.135463,0.397425,0.123077,-0.194294,0.159208,0.108738,-0.379693,-0.228587,-0.045701,0.021790,-0.007143,0.134260,-0.361136,-0.112114,0.147495,-0.558351,-0.039445,0.008673,-0.044345,0.087829,-0.173538,-0.360860,-0.637099,-0.099817,-0.320054,-0.267595,0.193998,-0.000884,-0.171428,0.660398,-1.037148,0.225882,0.388318,0.268709,-0.252133,0.522965,0.017291,-0.084037,-0.304298,-0.109873,0.227279,0.257865,0.336926,-0.035752,0.481057,-0.167410,-0.119569,-0.347513,0.123352', '1467779', '21619567', '10174444', '1417036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437109', '黑暗侵袭', '惊悚', '莎拉（肖娜·麦克唐纳 饰）本来平静幸福的生活被一次车祸意外打破，丈夫和女儿在事故中丧生，她虽然活了下来却从此一蹶不振，为了让莎拉重新振作起来，她的五个女性朋友为她安排了一次探险旅行，地点是在一个丛林中荒僻而古老洞穴，茹诺(娜塔丽·杰克逊·门多萨 饰)是其中最有野外探险经验也是她选择来到这里。正当女孩们对山洞中景色惊叹不已时，却在不知不觉中惊扰了洞中另外一种生物，他们没有视觉，依靠声音的来源残忍的捕杀她们，女孩们为了自救团结起来，却在逃生中朋友间互生怀疑，为了生存下去，她们要如何在狭小黑暗的洞穴中找到出去的路呢？©豆瓣', '肖娜·麦克唐纳', '尼尔·马歇尔', 7.6, 100730, 'tt0435625', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2209603070.jpg', 0.8, 3.8, 29.8, 46.2, 19.4, '-0.017363,0.217473,-0.775268,0.592528,-0.320309,-0.192335,1.144228,-0.346450,-0.641182,-0.191287,0.173377,0.820549,-0.024984,0.122333,-0.015391,0.042206,-0.504554,-0.361096,-0.071598,-0.303701,-0.627735,-0.191942,-0.409633,-0.352906,-0.231067,-0.155832,0.695128,0.427799,-0.264036,0.339885,0.011960,0.207005,-0.344591,0.623716,-0.174702,-0.087784,0.007348,-0.043212,-0.326109,0.221823,-0.216124,-0.256988,-0.501719,0.234707,0.104992,0.269985,0.776759,-0.412363,-0.113690,-0.078595,-0.036575,-0.203707,-0.180308,-0.064675,0.237432,-0.207404,0.490871,0.168859,-0.216094,-0.013952,0.039118,0.006040,-0.623451,0.108669,0.043154,0.231078,-0.516450,0.244070,0.269553,-0.299444,0.315289,-0.424983,0.189684,0.075649,0.562093,0.357694,-0.345122,0.039666,-0.318714,-0.095891,1.004859,-0.078849,-0.120080,0.325433,-0.365566,-0.502069,0.234678,-0.011355,-0.448700,-0.100217,0.397825,0.152883,-0.304997,0.149815,-0.461071,0.193269,-0.181658,-0.215828,-0.364248,-0.549546,-0.312204,-0.483731,0.140683,-0.055009,-0.338954,0.171394,-0.212254,-0.325649,0.506632,-0.722998,0.272220,0.627795,0.183448,-0.423912,0.663388,0.068068,0.380594,-0.147663,0.014479,0.266666,-0.175277,0.262764,0.051015,0.201847,-0.248848,0.109913,-0.631482,0.494228', '1296534', '21619567', '26715845', '1291835');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437204', '一球成名', '剧情', '像世界上那些的孩子们一样，桑提亚格（库诺•贝克饰）有一个梦想，就是成为职业足球运动员。但是，身居洛杉矶贫民区的他，只是个墨西哥来的穷小子，职业足球运动员，对他仅仅是一个梦。直到有一天，命运的大门向桑提亚格敞开，英国超级联赛的纽卡斯尔联队向他敞开了大门。突然间，桑提亚格成为了阿兰•希勒、马丁•泰勒、大卫•贝克汉姆等人中的一员。幸福来的太快让桑提亚格迷失了方向，职业球员的训练远比他经历过的困难，面对挫折与挑战，桑提亚格向着自己的球星之梦前进。©豆瓣', '库诺·贝克', '丹尼·加农', 7.5, 36846, 'tt0380389', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1793017518.jpg', 0.4, 2.9, 34, 46.6, 16, '0.214954,-0.053568,-0.439320,0.564236,-0.108978,-0.560335,0.785877,-0.116730,-0.468152,-0.233139,-0.002446,0.929761,-0.174010,0.301652,0.403450,-0.075225,0.069750,-1.033746,-0.236105,-0.263741,-0.663763,-0.262526,-0.174534,-0.495479,0.044363,0.018650,0.899760,0.249191,-0.351246,0.182828,0.344416,0.391453,0.472511,0.337894,-0.354457,0.156332,0.216138,0.170313,-0.269120,0.313295,-0.135462,0.065659,-0.405503,0.055444,0.047493,0.075821,0.375078,-0.415522,0.095766,-0.167934,0.076812,-0.279674,0.082583,0.182634,0.294122,-0.037758,-0.150391,-0.192413,0.156868,0.201224,-0.292959,-0.472728,-0.824010,-0.072814,0.080077,0.013421,-0.720610,0.431360,0.041168,0.063097,0.311559,-0.071571,-0.028588,-0.016351,0.382534,0.274721,-0.285898,0.054886,-0.388542,0.143923,0.679656,0.124140,-0.561034,0.247001,-0.561111,-0.513528,-0.249012,-0.328656,-0.570197,-0.026355,0.338838,-0.148021,0.140541,0.275712,-0.588440,0.147542,-0.155967,-0.345024,-0.183485,-0.337664,0.021461,-0.476138,0.338004,-0.526662,-0.297434,0.243156,-0.274784,-0.214615,0.889567,-0.813855,0.174248,1.007181,0.177982,-0.291582,1.072780,-0.282634,0.213454,-0.339349,0.035481,0.626000,-0.087321,0.137854,-0.122365,0.569409,-0.180099,0.009661,-0.209766,0.863474', '30162520', '10462973', '30167633', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437318', '一代妖后', '剧情', '清同治三年的1864年，假太监安得海自恃得西太后慈禧（刘晓庆）的宠爱，在朝中为所欲为，连同治皇帝（陈道明）也不放在眼中。当得知同治皇帝与宫女桂莲（巩俐）相好时，有心染指桂莲的他求得慈禧恩准，以将桂莲赐配给他“二哥”为名，想逼其与他成婚，不料桂莲性烈宁死不从，安得海恼羞成怒，将她卖进了天桥妓院。同治皇帝敢怒不敢言，私访天桥妓院，并借安德海南下之机，传旨山东巡抚丁宝桢将其就地正法，与慈禧嫌隙渐深。得知同治染上梅毒后，慈禧不准皇后生育，同治含恨而死，不久，皇后自尽，东太后慈安（陈烨）也神秘驾崩。©豆瓣', '刘晓庆', '李翰祥', 7.3, 11079, 'tt0351998', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1914274753.jpg', 0.6, 3.7, 40.7, 41.1, 13.9, '-0.010095,0.247364,-0.548984,0.629412,-0.138240,-0.212318,0.647134,0.297589,-0.605339,-0.022629,0.381710,0.532247,-0.366951,-0.074162,0.104942,0.147761,-0.192609,-0.318964,0.009294,-0.340681,0.173524,-0.216562,0.166251,-0.283109,-0.508123,-0.041187,0.651766,-0.248140,0.103753,0.167230,0.552838,0.024762,-0.035545,0.476487,-0.282992,0.306409,-0.351201,-0.507909,-0.248146,0.088924,0.231761,-0.812825,-0.462022,-0.163178,-0.067367,0.058638,0.138476,-0.526182,0.163954,-0.302888,0.385108,0.124937,-0.269315,0.470622,0.063596,0.028332,-0.078295,0.529705,-0.306758,0.022231,-0.150945,0.071570,0.064299,-0.010663,0.040446,0.097977,-0.250510,0.228116,-0.238781,-0.029674,-0.109630,-0.397075,0.300900,0.316805,-0.442069,0.264985,-0.245547,0.071022,-0.702135,0.574281,0.290176,-0.138269,0.124595,0.031806,0.381106,-0.160194,0.520262,-0.292409,-0.109548,0.242135,0.237886,-0.181422,-0.224301,0.423571,0.113056,-0.475142,-0.417808,0.455718,0.290542,0.003325,-0.168660,0.069562,-0.256867,-0.292892,-0.315437,-0.251155,0.421807,-0.170226,-0.067373,-0.315895,0.262927,0.165869,0.499920,-0.701917,0.616530,0.013305,0.296727,-0.130618,-0.293514,-0.044166,0.132313,0.317030,0.151560,0.238497,-0.180839,-0.470779,-0.279695,0.055047', '1305720', '1301081', '1418605', '1299578');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437339', '篱笆墙外', '喜剧', '一个初春的早上，小狸猫RJ跑到了大熊的家里将它为过冬而储存的食物一扫而光，后果可想而知，大熊要他一个星期内将食物给找回来，不然他将成为食物。另一方面，冬眠过后的动物们吃惊地发现他们的家园被人类霸占了一大半，乌龟文尼还现身说法，越过人类的篱墙十分危险。但是，有人类就意味着有着大量的食物，为了填饱肚子和避免成为大熊的食物。于是，RJ开始策划鼓动大家一起越过篱墙去抢食物,他翻过篱墙偷来一包薯片将大家彻底征服。动物们疯狂的行动开始了！©豆瓣', '布鲁斯·威利斯', '提姆·约翰森', 7.4, 21336, 'tt0327084', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1198860480.jpg', 0.3, 3, 37.5, 44.7, 14.4, '0.620130,0.149981,-0.464166,0.186360,-0.278913,-0.090596,0.465485,0.039137,-0.313579,0.115380,-0.174554,0.528754,0.012433,0.163761,-0.196751,-0.187868,-0.084512,-0.466107,-0.162280,-0.059218,-0.548015,-0.008850,-0.195922,-0.407697,-0.139600,-0.073944,0.446497,-0.128799,-0.008113,0.275351,-0.009528,-0.041619,0.173460,0.613520,-0.272718,0.150027,-0.251205,-0.413062,0.092105,0.534468,0.014351,-0.251306,-0.120406,0.416752,0.149396,0.124465,0.955718,-0.359765,-0.181360,-0.510492,0.215973,-0.498297,0.047140,0.429692,0.237259,0.247944,0.006035,-0.083166,-0.338207,0.553035,0.323307,-0.154031,-0.564802,-0.126626,-0.314126,0.006406,-0.692523,0.097572,0.288158,0.177142,0.429087,-0.529066,0.220732,0.316836,0.020753,0.424155,-0.132413,0.049956,-0.898376,-0.188697,0.755897,-0.562396,0.256946,0.134761,-0.018803,-0.299289,0.281020,-0.273507,-0.092934,-0.303845,0.400476,0.403348,-0.436835,0.127784,-1.183484,0.122301,-0.186202,-0.770515,0.125952,-0.170323,-0.295860,-0.519369,0.120990,0.057447,-0.098078,0.147008,0.257207,-0.347661,0.955510,-0.401420,0.173143,0.730578,0.321775,-0.471449,0.370695,-0.512290,0.127199,0.027622,0.019645,0.064294,0.284555,0.408729,0.544908,0.437310,-0.167258,-0.053827,-0.520827,0.483672', '4181031', '26290398', '2977870', '1292680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437342', '冰川时代2：融冰之灾', '喜剧', '地球上的冰河期终于就快要结束了！面对一天天变暖的天气，动物们都欢欣鼓舞。万物回春的天气里，食物多种多样，生活无忧无虑……我们第一集的三个英雄迭戈（剑齿虎）、曼尼（猛犸）和希德（树獭）却在普世欢腾的气氛中察觉出了危机：随着地球逐渐变暖，水位正慢慢上升，照这个速度下去，动物们的家园很快将被淹没。于是，动物们在迭戈、曼尼和希德的带领下，又开始了找寻新家园的旅途。路上，除了欢笑连连，还有苦难多多。动物们最终能否克服困难，找到一个全新的天地？©豆瓣', '雷·罗马诺', '卡洛斯·沙尔丹哈', 8.2, 226717, 'tt0438097', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204578670.jpg', 0.1, 0.9, 17.6, 53.2, 28.2, '0.297316,0.100799,-0.448477,0.454965,0.313873,-0.232332,0.652609,0.158955,-0.153419,0.071059,0.008176,0.601392,-0.376188,0.462384,0.124618,-0.281265,-0.678656,-0.710327,-0.307368,0.195042,-0.433452,-0.043816,-0.496416,-0.059643,-0.105378,-0.263203,0.523903,0.205720,0.276980,0.587084,-0.219024,0.103693,-0.119077,0.456643,-0.406051,0.143960,0.112412,-0.169080,-0.232120,0.040802,-0.214876,-0.235557,-0.133134,0.076165,0.045198,0.053799,0.751960,-0.689264,-0.090020,-0.206985,0.141127,-0.236202,0.043589,0.275409,0.323836,-0.086983,0.143517,0.111718,-0.126190,0.389749,-0.303407,0.010473,-0.693693,0.278235,-0.235979,0.234188,-0.433027,0.168624,0.586314,-0.222590,0.156297,-0.574435,0.111528,0.267471,0.069959,0.763433,-0.360918,0.002123,-0.320974,-0.237708,0.791791,-0.021663,-0.466119,0.502012,-0.238279,-0.329706,0.212920,0.075705,-0.323300,-0.452494,0.328886,0.400080,-0.301818,0.580705,-1.088657,0.605732,-0.123985,-1.098073,-0.179671,0.001131,-0.240262,-0.655194,-0.047515,-0.447494,-0.123778,0.031157,0.076713,-0.044271,1.030551,-0.591392,0.356865,0.449801,-0.105304,-0.368002,0.141879,-0.121605,0.260970,0.233960,0.012815,0.064089,-0.422932,0.823515,0.288510,0.484943,-0.333004,0.185079,-0.386913,0.834965', '4181031', '1292680', '2357162', '5361544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437377', '鱿鱼和鲸', '剧情', '伯克曼一家正面临一场家庭危机。老爸伯纳德（杰夫·丹尼尔斯 Jeff Daniels 饰）事业正在走下坡路，曾是畅销作家的他如今变得湮没无闻，反而是妻子琼（劳拉·琳妮 Laura Linney 饰）而今在写作上声名鹊起，令伯纳德倍感落差，并选择用尖酸刻薄嘴脸面对妻子的成功，二人不得不面临婚姻破裂的结局。两个儿子必定要因父母关系受到困扰。大儿子沃尔特（杰西·艾森伯格 Jesse Eisenberg 饰）16岁了，正值青春萌动，他坚决站在父亲一边，不料自己喜欢的女生竟然上了父亲的床；小儿子弗兰克（欧文•克莱恩 Owen Kline 饰）12岁，将父母离婚视作世界末日，甚至开始喝酒，因支持母亲变得和哥哥势不两立。一家四口的不知所措深深印在两个孩子的成长里面……©豆瓣', '欧文·克莱恩', '诺亚·鲍姆巴赫', 7.7, 12050, 'tt0367089', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p802723906.jpg', 0.3, 1.8, 26.2, 54.2, 17.5, '0.137776,-0.093350,-0.624523,0.262495,-0.038678,-0.462825,0.579002,0.489668,-0.696154,-0.297228,0.371956,0.728797,-0.182338,0.616699,0.178973,-0.157870,0.034685,-0.701734,0.162458,0.224706,0.095402,-0.410141,0.013240,-0.260865,-0.254453,-0.281013,0.644053,-0.176407,0.014641,0.460606,0.392929,0.426643,-0.047197,0.289112,0.049381,-0.019155,-0.002468,-0.041193,-0.607568,0.041629,0.097640,-0.037129,0.142489,0.155012,-0.019507,0.273615,0.508144,-0.081782,-0.223367,-0.271500,0.396888,-0.067087,-0.254534,0.581222,0.297363,-0.005858,0.288075,0.130008,-0.255291,-0.278202,0.053095,-0.258667,-0.440239,0.087624,0.209736,0.056700,-0.456869,0.326443,-0.217851,-0.059483,0.068705,-0.444819,0.032243,0.315850,0.228413,0.685520,-0.166594,0.083688,-0.283736,-0.165266,0.654802,-0.092102,0.053457,0.346186,-0.340403,0.074889,-0.027414,-0.425532,-0.769785,0.160726,0.089307,-0.092620,0.099371,0.452403,-0.361348,-0.006771,-0.474304,-0.012326,0.218568,-0.212443,-0.011648,-0.127719,-0.175774,-0.272949,-0.234071,0.141502,-0.061393,-0.528278,0.596255,-0.567894,0.302593,0.136699,0.364699,-0.425606,0.336216,0.306555,0.255144,-0.410523,-0.166957,0.560894,-0.207543,-0.438751,-0.083982,-0.326289,0.019870,0.101265,-0.041407,0.511447', '26245360', '1578475', '4066127', '3014557');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437554', '九二神雕之痴心情长剑', '喜剧', '风流大侠遑仁（刘德华 饰）与师父（元奎 饰）、小师弟生活在一起，他常在梦中与一位女子（关之琳 饰）相见，他一心想找到这位令他神魂颠倒的美女。这时候魔王（吴耀汉 饰）邀请江湖中人前往雪山帮忙去玉女寒冰。遑仁发现被藏在冰中的女子正是自己的梦中情人，他一心想保护自己的爱人——姑姑不让魔王抓走，可是旅馆馆主路比（关淑怡 饰）不甘自己喜欢的逞仁喜欢上了他人，便通知了魔王逞仁的行踪。逞仁在与魔王决斗的时候被魔王打伤后重伤死亡，姑姑便吧自己的真气传给了逞仁，逞仁虽然复生了，魔王却抓走了姑姑……©豆瓣', '刘德华', '元奎', 6, 6530, 'tt0104560', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167121524.jpg', 5.1, 19.8, 52.7, 15.9, 6.5, '-0.089513,0.046555,-0.458855,0.534814,-0.314382,-0.444032,0.756700,0.136300,-0.542862,-0.179738,0.378365,0.804739,-0.181316,0.141125,0.350248,0.347313,-0.108804,-0.525964,-0.085372,-0.226724,-0.334384,-0.092188,-0.293335,-0.001858,0.026186,-0.548160,0.517237,0.027934,-0.152816,0.396235,0.205469,0.107643,-0.353208,0.665662,-0.354615,0.208551,-0.002317,-0.023842,-0.191916,0.450118,-0.091317,-0.209111,0.033163,0.274335,-0.189434,0.243535,0.376188,-0.517055,-0.041980,-0.154982,-0.014057,-0.186569,0.004693,0.193346,0.321013,-0.343594,0.457638,0.162041,-0.328284,-0.110612,0.057399,-0.067859,-0.506881,0.177279,0.217230,0.116876,-0.645150,0.353494,-0.154159,0.150337,0.198712,-0.318890,0.359992,-0.115857,0.086336,0.239255,-0.037763,-0.193513,-0.406628,0.327733,0.643212,-0.077277,0.418672,0.253627,0.228142,-0.202310,-0.123904,-0.114635,-0.343196,0.000312,0.442741,-0.102446,-0.236135,0.158633,-0.317483,-0.263466,-0.152502,0.372900,-0.125325,-0.441576,-0.120345,-0.108773,-0.098808,-0.222115,0.035400,-0.062424,0.255183,-0.157715,0.616710,-0.921695,0.482401,0.535660,0.242164,-0.443885,0.833142,0.098086,0.005560,-0.075435,-0.051226,-0.061955,0.212601,0.428659,0.206096,0.419911,0.083659,-0.015380,-0.387010,0.174810', '1302384', '1308755', '2990737', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437847', '太后吉祥', '喜剧', '清朝末年，慈禧（斯琴高娃 饰）突然身染怪病，御医们一批批来了又走，都没能开出药方治好太后的病。慈溪大怒，命人将御医们全部斩首。斩首这天，刑场旁边放着丰盛的酒席，好让御医们死前饱餐一顿。一个江湖郎中汤元元（陈佩斯 饰）因饥肠辘辘，不知就里就坐上席间大吃大喝。主斩官洪禄以为汤元元是问斩的御医，喝人将他捉了上来。汤元元发现洪禄正不停打嗝，随口说了个药方竟治好了他的病。太后得知此事，忙命人暗中吩咐洪禄带汤元元入宫为她看病。汤元元最终命运如何？©豆瓣', '陈佩斯', '金韬', 7.1, 10087, 'tt0184562', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2496978785.jpg', 0.8, 4.5, 46.2, 35.8, 12.8, '-0.018337,0.168494,0.000741,0.175208,-0.024054,-0.086010,0.543741,0.262383,-0.486284,-0.168007,0.418103,0.302581,-0.379455,0.133548,-0.023685,-0.029367,-0.345202,-0.378178,0.015490,0.021092,-0.551689,0.116864,0.178368,-0.275325,-0.211062,0.115591,-0.364636,-0.507441,0.465341,0.518249,0.132863,0.126221,0.225289,0.460044,-0.387000,0.415056,-0.074471,-0.594283,0.181451,0.037701,0.283459,-0.722357,-0.385984,0.099217,0.103195,0.218385,0.295998,-0.141268,-0.009345,-0.285041,0.152086,-0.257171,0.203174,0.551340,0.219973,0.335901,0.031601,-0.058423,-0.390804,-0.073991,-0.196366,0.213442,-0.389423,0.156828,-0.052220,0.109823,-0.494456,0.210513,-0.150715,0.180371,-0.357480,-0.310318,0.543127,0.194190,-0.172179,0.350245,0.198967,-0.050703,-0.688149,0.336742,0.239916,-0.266468,0.207378,0.193410,0.202161,-0.220121,0.854330,-0.161427,0.092147,-0.141779,0.174292,-0.066688,-0.143236,-0.192661,0.040178,0.028769,-0.411829,-0.250690,-0.030551,0.203856,-0.124058,-0.232880,-0.026994,0.127275,-0.370043,-0.093012,0.216372,0.327426,0.633272,0.283163,0.229477,0.224770,0.001046,-0.667216,0.443735,0.100284,0.164664,0.329895,-0.143985,-0.383029,0.006229,0.594497,0.548552,0.464670,-0.277724,-0.127898,-0.496981,0.060571', '4307000', '1302874', '3892449', '21357362');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437857', '阿诗玛', '爱情', '在一个名叫阿着底的所在，美丽的撒尼族姑娘阿诗玛（杨丽坤 饰）心灵手巧，心地善良，歌声甜美，许多年轻小伙和姑娘甚至不辞辛苦千里迢迢赶来，只为一睹阿诗玛的芳容。在这群勇敢憨厚的好小伙中间，最为出众的青年阿黑（包斯尔 饰）赢得了阿诗玛的芳心。他们郎才女貌，情意互属，羡煞旁人， 却独独气坏了头人热布巴拉（崔超明 饰）之子阿支（韩菲 饰）。阿支垂涎阿诗玛的容颜，千方百计想要将她骗到手，无奈阿诗玛如同一只冷艳带刺的玫瑰，坚决不从。为此阿支使尽各种诡计，企图拆散这对人间眷侣……本片根据撒尼族历史悠久的民间叙事长诗改编，荣获1982年西班牙桑坦德第一届国际音乐最佳舞蹈片奖。©豆瓣', '杨丽坤', '刘琼', 7.8, 4970, 'tt0333099', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2532739201.jpg', 0.3, 1.5, 26.7, 49.7, 21.9, '-0.029343,0.154531,-0.433857,0.547408,-0.173231,-0.084341,0.520558,-0.049801,-0.234590,-0.015778,0.160832,0.367320,-0.121533,-0.030632,0.223760,0.228194,-0.053820,-0.455262,-0.174948,-0.222091,0.177847,-0.005521,-0.332661,0.179280,-0.187601,-0.233663,0.319675,-0.102686,-0.165065,0.683549,0.480079,0.100505,-0.136348,0.015988,-0.397125,0.080868,0.027708,0.053128,-0.073285,0.105698,-0.209739,-0.254570,-0.259355,0.048153,-0.318022,0.099589,0.679037,-0.359479,0.069390,-0.041469,0.403849,-0.185157,0.220272,0.132621,0.090442,-0.201397,0.254326,-0.135865,-0.238096,-0.077286,0.320829,-0.221638,-0.587328,0.210034,0.279117,-0.005867,-0.666897,0.345708,-0.019054,-0.045896,0.163691,-0.133102,0.148727,-0.105817,0.154335,0.291805,0.044812,0.157047,-0.497821,0.394368,0.419921,0.355149,-0.030072,0.200723,-0.315167,-0.456635,0.224138,-0.229561,-0.469847,0.048798,0.382860,-0.187332,0.408913,0.096291,-0.635390,-0.027924,-0.121901,0.200721,0.048022,-0.583912,-0.124965,-0.310775,-0.232193,-0.442996,-0.059364,0.035252,0.159223,0.010577,1.062209,-0.472503,0.041392,0.301392,-0.001188,-0.259077,0.502713,0.249392,-0.177268,-0.196984,-0.540890,0.282829,0.200854,-0.197550,-0.032809,0.421234,-0.221337,-0.275143,-0.409569,0.180652', '26348103', '27602116', '1302661', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1437883', '怪物', '恐怖', '青年建筑师Ray（方中信 饰）带妻子May（舒淇 饰）及5岁儿子子路(谭竣浩 饰)搬进新家的翌日傍晚，就有怪事发生，May带着子路在天台花园玩耍时，看到子路被强大力量离奇扯出天台，坠楼失踪。接着，May又频频听到小孩寻找母亲的哭叫声，更恐怖的，是家中无论子路的玩具还是衣衫都先后离奇失踪。 在警察的帮助下，Ray和May知晓导演这一切的，是躲藏在他们背后的神秘“怪物”（林嘉欣 饰）。而在与“怪物”争夺儿子的过程中，Ray和May渐渐了解到，神秘“怪物”在丑陋可怖的外表下掩藏着一个不为人知的辛酸故事。©豆瓣', '林嘉欣', '郑保瑞', 6.5, 17664, 'tt0483908', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486763728.jpg', 1.5, 11, 55, 25.2, 7.3, '0.255614,-0.151780,-0.705626,0.286894,-0.000306,0.118420,1.043350,0.158472,-0.550917,-0.305712,0.607539,0.658281,-0.395184,0.416455,0.170208,-0.101059,-0.210108,-0.588188,-0.042929,-0.116992,-0.452199,-0.352158,-0.291353,-0.091045,0.126604,-0.559910,0.318864,0.274260,-0.050522,0.559257,0.292326,0.393752,-0.567050,0.438607,-0.488222,0.073774,-0.021752,0.395649,-0.095657,0.026279,0.056511,-0.292590,-0.303101,-0.047455,-0.420408,0.298293,0.764024,-0.202793,-0.143919,0.066126,0.355338,0.062309,-0.071314,0.117347,0.469338,-0.019189,0.201335,0.282748,-0.170564,0.093237,0.175953,0.101018,-0.544420,0.208158,0.265640,0.415912,-0.466793,0.320146,0.017413,-0.114946,0.503124,-0.473057,0.324688,0.092831,-0.085035,0.688965,-0.128583,0.029622,-0.506481,0.074906,0.395528,-0.097380,0.008124,0.354228,-0.102512,-0.188032,0.102228,-0.338386,-0.344529,0.122544,0.244684,0.134231,-0.310118,0.184733,-0.599825,0.153775,-0.068580,-0.005039,0.079458,-0.306513,-0.476571,-0.483629,-0.337035,-0.353948,-0.090505,0.356539,0.007180,-0.225731,0.742374,-0.604001,0.134078,0.365579,0.307187,-0.251033,0.633004,-0.444441,0.032409,-0.171471,-0.058351,-0.094039,0.006667,0.171644,0.049261,0.489927,-0.247318,-0.158869,-0.468761,0.248956', '21619567', '20451118', '1467779', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438041', '求求你，表扬我', '喜剧', '民工杨红旗（范伟 饰）几次三番跑到报社要求登报表扬自己，因为自己在一起强奸未遂案中救了一个姑娘，可是当事人女大学生欧阳花（陈好 饰）对这件事却坚决否认，并且声称自己从未见过杨红旗。记者古国歌（王志文 饰）在调查中得知杨红旗要求登报表扬是为了完成父亲在临终前的愿望，然而 直到其父去世依然没有看到儿子被登报表扬，古国歌受到很大的触动。在警察女友米一（苗圃 饰）的帮助下，古国歌很快就找到了事件的真相。真相自然使杨红旗得偿了登报受表扬的心愿，可是却深深的伤害了想维护自己清誉的女大学生欧阳花，与此同时，古国歌也陷入了不知对错的矛盾之中……本片在2005年第八届上海国际电影节上荣获评委会大奖以及最佳剧本奖。©豆瓣', '王志文', '黄建新', 7.2, 25658, 'tt0487942', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p498351612.jpg', 1, 5.5, 39.6, 40, 13.9, '-0.100486,0.221396,-0.623600,0.635081,-0.021628,-0.302248,0.416081,-0.246711,-0.755119,-0.341351,0.169323,0.310629,-0.474317,0.196272,0.281565,-0.311143,-0.166918,-0.634074,0.052929,0.001479,-0.397803,-0.509728,-0.002809,-0.220872,-0.458476,0.085586,0.344811,0.223629,-0.238502,0.440582,0.620837,0.196146,0.063075,0.456669,0.090907,0.247749,0.165014,0.271428,-0.161844,0.202333,0.234611,-0.644224,-0.142689,0.115933,0.308221,0.309780,0.429840,-0.256642,-0.231476,0.009215,0.404084,-0.365594,0.040476,0.201907,0.299807,-0.066110,0.381842,-0.084936,-0.342039,-0.216155,0.145610,-0.375004,-0.211300,-0.163279,0.288803,0.192969,-0.662493,0.203353,-0.457790,0.407192,-0.011712,-0.234853,0.313855,0.230417,0.360788,0.510184,-0.312627,0.116184,-0.506455,0.502142,0.602366,0.139247,0.005124,-0.226070,-0.407273,-0.479864,-0.238531,-0.062894,-0.272990,0.212520,0.394200,-0.096047,0.028233,0.063179,-0.143811,-0.698217,-0.001733,-0.053040,0.041643,-0.608586,0.119008,-0.359758,-0.065391,-0.106276,0.024016,0.072608,-0.038801,-0.518590,0.746921,-0.815013,0.444767,-0.069241,0.289692,-0.621323,0.622720,0.295658,0.040030,-0.190825,0.017997,0.318144,0.167146,0.180518,0.060786,0.136229,0.055909,-0.568238,-0.015034,0.265761', '1308228', '1302425', '2052978', '2079632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438066', '隐藏摄像机', '剧情', '知名电视节目主持人乔治（丹尼尔·奥特尤尔 Daniel Auteuil 饰）与妻子安娜（朱丽叶·比诺什 Juliette Binoche 饰）、儿子皮埃尔一家三口的平静生活被乔治从家门口捡来的录像带打破，这盒录像带显示有人静静地注视着乔治家的一举一动。很快，更多的录像带 和恐吓性质的明信片寄到了乔治及家人手上。乔治对看不见的敌人殊为紧张，开始小心保护儿子，并且为录像带的内容指引，回想起多年以前，差点成为母亲养子的阿尔及利亚遗孤马吉德。乔治怀疑录像带的始作俑者即为马吉德，于是登门拜访，却引发了意外的结局……本片获2005年戛纳电影节最佳导演奖、费比西奖等二十余项专业褒奖。©豆瓣', '丹尼尔·奥特伊', '迈克尔·哈内克', 7.6, 13383, 'tt0387898', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196346399.jpg', 1.4, 4.4, 26.8, 46.7, 20.7, '-0.073366,-0.071586,-0.472656,0.525604,0.120561,-0.388237,0.430192,0.199543,-0.522900,-0.266878,0.036880,0.822963,-0.398813,0.036117,0.336405,0.024970,-0.490033,-0.531279,-0.040900,-0.122559,-0.020101,-0.469946,-0.115557,-0.241289,-0.063329,-0.306011,0.122381,-0.041859,0.054289,0.568642,0.367802,0.137697,0.032811,0.116332,0.198409,0.077474,0.100749,-0.115144,-0.502222,0.213878,0.136190,-0.169142,-0.202919,0.056440,0.265869,0.139822,0.654128,-0.064885,-0.138785,0.007215,0.501911,-0.109530,0.108775,0.046585,0.252012,0.327863,0.020787,0.025214,-0.318150,-0.009802,0.209253,-0.048335,-0.699403,-0.040024,-0.013058,0.203093,-0.407879,0.415539,-0.318929,0.250605,0.145933,-0.147838,0.415482,0.201310,0.230248,0.270642,0.031440,0.051940,-0.218062,0.014994,0.024436,-0.330694,0.045595,0.270761,-0.117866,-0.376869,0.131689,-0.124558,-0.476809,0.247937,0.461977,-0.004450,0.173424,0.095722,-0.226358,-0.364337,-0.182201,-0.243689,0.319266,-0.442648,-0.135341,-0.671380,0.092569,-0.000667,-0.011109,-0.072785,-0.163420,-0.274690,0.559022,-0.129115,0.432338,0.360004,0.050936,-0.196280,0.442106,0.027720,-0.017199,-0.250580,-0.294364,0.232943,0.309590,0.057987,0.108031,-0.070904,0.107591,-0.271487,-0.144881,0.312858', '1829654', '3318306', '2027945', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438091', '英雄儿女', '剧情', '抗美援朝时期的某高地，激烈的战争正在进行，刚出院的中方志愿军战士王成（刘世龙）一回到部队就要求投入到战斗中去，并拿出父亲王复标（周文彬）鼓励他为国立功的家书给张团长（郭振清）和政委王文清（田方）看，王复标是王文清的老战友，他也知道王成是王复标的儿子。王成在战斗中壮烈牺牲，全团展开向他学习的行动，文艺兵、王成的妹妹王芳（刘尚娴）强忍悲痛投入到创作中。和王芳的接触中，王文清虽认出她是自己十八年前无奈丢下、后被王复标收养的女儿，却没有和她相认，而是鼓励她以实际行动向哥哥学习，王芳也在后来的战斗中有英勇表现。©豆瓣', '田方', '武兆堤', 7.9, 14483, 'tt0188299', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1344007523.jpg', 1.5, 2.5, 22.4, 44.3, 29.4, '0.117447,-0.101805,-0.800652,0.645872,-0.258132,-0.615340,0.836336,-0.265778,-0.432458,0.055947,0.464331,0.572151,0.193774,0.334393,0.151281,-0.117606,-0.391541,-0.782293,-0.147473,0.175215,-0.187944,-0.546235,-0.060908,0.065864,-0.059311,-0.177197,0.452636,-0.274169,-0.378321,0.576684,0.195828,0.001932,0.008631,0.903290,0.129397,0.366922,-0.240063,0.023483,-0.397044,0.082713,0.388841,-0.252084,-0.501743,0.174700,0.325467,0.462135,0.667290,-0.324334,0.129018,-0.035713,0.124443,-0.296769,-0.053665,0.285540,0.254895,0.363770,0.153883,-0.087793,-0.065718,0.242329,-0.526402,-0.035057,-0.579793,0.008863,0.046647,0.121013,-0.748103,0.609778,-0.117961,0.105925,0.432558,-0.457171,0.144819,0.470724,-0.035292,0.633192,-0.523667,-0.040114,-0.138389,0.331924,0.508560,-0.106495,-0.022131,0.063136,-0.049307,-0.513052,0.211932,-0.081234,-0.280646,-0.105335,0.325085,-0.012812,-0.060502,0.023390,-0.382401,-0.112969,0.028651,-0.319833,0.099994,-0.279215,0.060584,-0.459399,-0.025921,-0.455060,-0.436681,0.105580,0.052128,-0.601354,0.719957,-0.813397,-0.005049,0.112424,0.469888,-0.355660,0.531546,0.156380,0.111927,-0.142856,0.081129,0.188510,-0.066210,0.475053,0.291845,0.345835,0.085869,-0.230560,-0.265326,0.497224', '1301022', '3111650', '2976072', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438093', '求爱上上签', '喜剧', '以《欲望都市》为蓝本的香港喜剧片。Selina汪楚翘（刘嘉玲 饰）是一名事业有成的女强人，她是心理医生，但是多次不成功的恋爱经验让她自己患上了婚姻恐惧症。她与几名单身女郎，包括尖酸刻薄实战经验却不丰富的女作家关德娴（朱茵 饰），外表狂野爱刺激的倪险（蒙嘉慧 饰），爱打抱不平身手不凡的Mark（张文慈 饰）等组成了一个“八婆团”。在爱情路上坎坷的众人分别遭遇了不同的情感，Selina遇上了江湖大哥任初九（梁家辉 饰），并帮助前男友（钟镇涛 饰）的女儿Yuki（张柏芝 饰）从不良少女改邪归正；关德娴周旋于评论家石大班（许少雄饰）与英俊的大学生斯通（陈冠希 饰）；倪险棋逢对手遇上了大陆来的大胆（陆毅 饰）；而Yuki暗中与保镖许劲（许志安 饰）发生了感情。不管过程如何惊险刺激，最后众女郎都获得了圆满的爱情。©豆瓣', '刘嘉玲', '王晶', 5.8, 28153, 'tt0406221', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p486841140.jpg', 3.6, 21, 59.3, 13.2, 2.9, '0.086147,-0.158941,-0.465836,0.622246,-0.171381,-0.070383,0.739775,0.099979,-0.399535,-0.058053,0.260667,0.549936,-0.154532,0.118412,0.243240,-0.046745,0.025894,-0.717293,0.171805,0.066290,-0.141556,-0.242902,-0.363124,-0.054887,-0.223519,-0.438156,0.617303,0.006466,-0.178883,0.510867,0.653162,0.295782,-0.046054,0.282187,-0.227463,0.080061,0.199389,0.213309,-0.254059,0.000017,-0.088036,-0.229446,-0.055569,0.107786,-0.183793,0.371348,0.757381,0.001554,-0.143916,-0.095798,0.514697,0.029896,0.065944,0.209864,0.180522,-0.086731,0.308471,0.274673,0.080736,0.096026,0.161752,0.075402,-0.637493,-0.054999,0.314768,0.103588,-0.542495,0.576371,-0.311406,-0.314778,-0.071956,0.003290,0.012338,0.199353,0.409581,0.119908,0.023269,-0.073640,-0.353448,0.553462,0.632093,0.420538,-0.215615,0.591722,-0.341707,-0.602029,-0.164918,-0.367820,-0.514456,0.186063,0.149693,-0.109650,-0.238264,0.197084,-0.569505,0.059513,-0.040039,0.249822,-0.033835,-0.358428,0.000237,-0.502510,-0.309787,-0.801302,-0.363954,-0.022277,0.129011,-0.200953,0.908960,-0.813238,-0.127800,0.299255,0.134203,-0.779441,0.859408,0.233954,-0.039631,-0.113115,0.006564,0.229617,-0.200642,-0.166540,-0.030160,0.514004,-0.133594,-0.195012,-0.217169,0.130518', '26354526', '6963575', '26283288', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438282', '越轨追击', '剧情', '十月里一个普通的湿气蒙蒙的日子，广告总监查尔斯（克里夫•欧文 Clive Owen 饰）错过了他的列车，但是在下一列车上，他却因一张车票，结识了金融投资顾问露辛达（詹妮弗•安妮斯顿 Jennifer Aniston 饰），两人给彼此留下了良好的印象。其时查尔斯的女儿身患糖尿病，他不得不抽出更多的精力照顾女儿，而同时事业上却遭遇了挫折，妻子忙于工作，无暇给予他更多情感上的宽慰。之后的日子里，查尔斯与露辛达时常见面，两个各自有家庭的人越发接近，终于在一次约会后来到了宾馆，但这次独处很快被打破，一个名叫拉洛克（文森特•卡索 Vincent Cassel 饰）的陌生人破门而入，用枪威胁他们，实施了抢劫并强暴了露辛达。担心私情暴露的两人无法依靠法律，而拉洛克的勒索却越发频繁，查尔斯决定用自己的力量，去解决这场危机。©豆瓣', '克里夫·欧文', '米凯尔·哈弗斯特罗姆', 7, 5894, 'tt0398017', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1063644142.jpg', 0.8, 5.3, 44.6, 39.9, 9.3, '0.437337,0.124187,-0.631806,0.549833,-0.025625,-0.500353,0.803711,0.315479,-0.512975,-0.248795,0.191651,0.674677,-0.084763,0.255236,0.191029,-0.052344,-0.436652,-0.623728,0.315083,-0.072524,-0.362528,-0.405050,-0.231369,-0.191857,-0.182317,-0.255320,0.451984,-0.047682,-0.176521,0.448860,0.133762,0.077767,0.166552,0.785436,0.009927,-0.098799,0.012107,0.049769,-0.232810,0.270924,0.220601,-0.387503,-0.161836,0.217624,0.043203,0.646956,0.545350,-0.105520,-0.161219,-0.169806,0.385137,-0.340503,-0.018389,-0.014797,0.219318,0.020702,0.236541,0.098867,-0.460366,-0.068547,0.082358,-0.047236,-0.645996,0.106154,-0.097168,0.136514,-0.651978,0.478214,-0.170642,0.054825,-0.134689,-0.373904,0.061673,0.470443,0.165763,0.141308,-0.381002,0.001042,-0.330200,0.032045,0.723110,-0.113249,-0.012383,0.473695,-0.349853,-0.215683,0.017196,-0.306410,-0.455851,-0.183305,0.425504,0.049327,-0.205752,0.190084,-0.689410,0.051584,-0.343152,-0.131990,-0.146938,-0.446049,0.116651,-0.644325,-0.185346,-0.424611,-0.533967,0.127753,0.299362,-0.221780,0.544884,-0.586756,0.093058,0.586601,0.470918,-0.368852,0.550975,0.234923,0.362359,-0.062906,-0.028474,0.132594,-0.101781,0.289134,0.250891,0.314196,-0.139070,-0.104517,-0.178829,0.579185', '1309172', '3743049', '34461680', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438300', '小贼、美女和妙探', '喜剧', '在哈里（小罗伯特·唐尼 Robert Downey Jr.饰）的旁白中，这个带着黑色幽默的故事开始了。他本来是一个衰运连连的惯偷，因为一次躲避警察追捕的缘故，闯入了好莱坞电影的选秀片场。可谓歪打正着，导演竟然一下子就看上了哈里，让他前往洛杉矶接受角色培训。哈里就这样莫名其妙地成为了“准演员”，他将会出演一名神探。剧组专门安排哈里到真正的侦探佩里（瓦尔·基尔默 Val Kilmer饰）身边，体验真实的侦探生活。一桩命案等待着他们的调查，而死者是一名女士。这种惊险的生活真让哈里受尽了苦头，因为冷酷的佩里可不是一个容易应付的搭档。而同时，哈里在派对上重遇了年少时的梦中情人哈莫妮（米歇尔·莫娜汉 Michelle Monaghan饰）。她已经在好莱坞摸爬滚打一番，仍然名声未扬，如今她的妹妹更是神秘自杀。为了赢得美人心，哈里开始调查这件事情，这时才慢慢发现，这和他们之前接手的命案竟然相关，而且背后还隐藏着一个不为人知的巨大秘密。', '小罗伯特·唐尼', '沙恩·布莱克', 7.2, 17644, 'tt0373469', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2299543016.jpg', 0.9, 5.6, 40.1, 41.5, 11.8, '0.421031,-0.018832,-0.608720,0.688672,-0.215471,-0.404408,0.745153,0.054082,-0.529091,-0.340909,0.367628,0.838169,-0.475993,0.273253,0.331980,0.074890,-0.453273,-0.679960,-0.215940,-0.094490,-0.261914,-0.355705,-0.579897,-0.137908,-0.130320,-0.125583,0.421730,0.134223,-0.072903,0.400458,0.357868,0.270967,0.013832,0.388815,-0.094232,0.058156,0.344992,0.029060,-0.076793,0.266336,0.205967,-0.338797,-0.065034,0.332471,-0.076346,0.409641,0.405602,-0.339234,-0.180925,-0.081989,0.387302,-0.411979,-0.019110,0.074496,0.219698,-0.066327,0.261553,0.192002,-0.308875,0.001193,-0.085958,0.007162,-0.900103,0.116938,0.038528,0.307781,-0.492354,0.104549,-0.126196,-0.055079,0.079856,-0.291750,0.129872,0.315629,0.358093,0.239351,-0.135250,0.066325,-0.458838,0.358075,0.696970,0.031899,-0.074917,0.392959,-0.028224,-0.412998,0.008107,-0.207302,-0.454250,0.013131,0.293527,-0.282547,-0.130060,0.217909,-0.412357,0.002248,-0.404411,-0.149906,-0.210900,-0.340949,-0.027090,-0.660579,-0.196066,-0.258340,-0.339151,-0.100489,0.069772,-0.307194,0.576379,-0.751618,0.239190,0.907209,-0.008959,-0.346807,0.477991,0.087609,0.093550,-0.050732,-0.167069,0.020408,0.046627,0.305733,0.084195,0.582053,0.056092,-0.458407,-0.351210,0.495699', '34890458', '1793491', '25928048', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438337', '珍爱泉源', '剧情', '1500年，大将军托马斯（休·杰克曼 Hugh Jackman 饰）奉皇后伊莎贝拉（蕾切尔·薇兹 Rachel Weisz 饰）之命前往新大陆寻找创传说中的“生命之树”。只要饮下一滴树的汁液，便会获得永生。一路历尽千辛万苦，终于到达了一座辉煌的隐蔽之地，看到了永生难忘的奇异景象。2000年，脑癌专家汤米（休·杰克曼 Hugh Jackman 饰）急切为患脑癌的妻子丽兹（蕾切尔·薇兹 Rachel Weisz 饰）寻找良药。研究小组从南美洲丛林里带回了一株奇异的树种标本，在提炼药物用于黑猩猩实验时奇迹般地产生了效果。2500年汤姆•乘坐着用思想控制的透明圆球飞船中，穿梭于太空宇宙。辽阔的星际间，身边却只有那棵已快死亡的古树，他无时无刻不回想着关于丽兹的记忆。千年的奔涌时空里，苦苦寻觅的一直是生命的真谛……©豆瓣', '休·杰克曼', '达伦·阿伦诺夫斯基', 7, 12389, 'tt0414993', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2239129668.jpg', 2.1, 9.2, 39.9, 33.4, 15.4, '-0.207106,0.297383,-0.614214,0.629433,0.267262,-0.134291,0.552850,-0.168732,-0.254183,-0.111343,-0.041946,0.359015,-0.212978,0.078290,0.236378,0.347162,-0.422892,-0.524636,-0.128385,-0.378383,-0.342115,-0.342662,-0.520673,0.136558,0.083151,-0.598757,0.627389,0.144422,0.181627,0.328532,-0.423102,0.324501,-0.161461,0.198651,-0.167076,-0.123584,0.298531,-0.115456,-0.227017,0.032805,-0.018239,-0.433453,-0.021457,-0.104083,0.017040,0.122059,0.745723,-0.790781,0.275201,-0.240026,0.194981,0.056597,0.199320,-0.392209,0.190744,-0.012888,0.021809,0.168267,-0.386144,-0.009664,0.209622,-0.419850,-0.714578,-0.346249,-0.126056,0.078412,-0.397261,-0.001389,0.088121,0.237813,0.072330,-0.282879,0.428358,0.054450,0.155095,0.458728,-0.245283,-0.259889,-0.184490,0.106659,0.247880,-0.170545,-0.464525,0.568822,-0.539473,-0.407647,-0.038809,-0.012511,-0.484535,-0.174625,0.406850,0.369400,-0.105675,0.429879,-0.608202,0.091054,-0.490037,-0.238747,0.228637,0.174972,-0.499333,-0.520359,-0.148282,0.075977,-0.073039,0.063155,-0.098090,-0.282245,0.542401,-0.298792,0.534805,0.474693,0.002164,0.002165,0.806980,-0.576292,0.009316,-0.270758,-0.056383,0.612305,-0.155986,0.442187,0.029322,0.230109,0.001331,0.215339,-0.517957,0.406416', '1295656', '1300830', '25837262', '1