INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438338', '慕尼黑', '剧情', '这是一部关于政治、复仇的真实的电影。1972年在联邦德国举办的第20届奥运会上，巴勒斯坦的极端恐怖组织“黑色九月”闯进了奥运村绑架了11名以色列运动员，以此要挟以色列释放被关押的该组织成员。联邦德国的警察草率对待了这次绑架事件，他们直接冲进了恐怖组织的巢穴企图武装营救 人质，孰料导致了11名以色列运动员全部遇难!事件发生之后，以色列“摩萨德”高层迅速训练了一批特工，展开了对“黑色九月”组织以及相关的巴勒斯坦人血腥的报复……©豆瓣', '艾瑞克·巴纳', '史蒂文·斯皮尔伯格', 7.9, 38312, 'tt0408306', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504312826.jpg', 0.3, 1.8, 23.2, 53.6, 21, '0.417885,-0.138570,-0.448696,0.456414,0.177146,0.066920,0.215668,-0.164238,-0.592945,-0.067844,0.448131,0.610719,-0.074044,-0.131817,0.402577,-0.079726,-0.198679,-1.014423,-0.561972,-0.354882,-0.519795,-0.494638,-0.236246,-0.308333,0.355799,-0.176998,0.509545,0.028784,-0.480295,0.366323,0.470219,0.644542,-0.167803,0.181877,0.159946,-0.237750,0.569176,-0.195182,-0.358014,0.269176,-0.317964,-0.545332,0.157661,-0.040477,-0.153700,0.663921,0.798401,-0.363015,0.030126,-0.599310,0.572588,-0.584381,-0.342736,0.249534,0.604363,0.341509,-0.026406,0.493908,0.068577,-0.023797,-0.069986,-0.252284,-0.730371,-0.122254,0.044742,0.037703,-0.441544,0.459967,-0.291493,0.465461,0.280677,0.049236,0.301176,0.775447,0.159517,0.132440,0.182587,-0.027376,-0.332921,0.447009,0.774999,-0.426837,-0.309551,-0.182047,-0.152850,-0.451622,0.081414,-0.403200,0.184535,-0.021328,0.616373,-0.275545,-0.177324,0.477543,-0.867368,-0.330657,-0.289618,-0.447783,0.178146,-0.138166,-0.011782,-0.782509,-0.248930,0.073269,-0.075524,0.127336,-0.046248,0.189350,0.670994,-0.803895,0.374474,0.726019,0.233334,-0.693222,0.128986,-0.082373,0.050631,0.061346,0.054213,0.028701,0.301531,0.700515,-0.051685,0.450900,0.130381,-0.484974,0.084105,-0.169901', '1292829', '25723905', '26336253', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438584', '圣诞快乐', '剧情', '第一次世界大战期间，战事胶着而残酷，不同阶层的人不断的卷入到战争的漩涡之中，徘徊在死亡的边缘。终于，平安夜来临。德国、法国和苏格兰军营宣布在圣诞之夜停战，相互约定度过一个和平安详的圣诞节。每个人都放下了手中的武器，手执蜡烛，互道“圣诞快乐”。应征入伍的德国男高音歌手斯普林克（本诺·福尔曼 Benno Fuehrmann饰）的女友安娜（黛安·克鲁格 Diane Kruger饰）在平安夜来看望他。士兵们被安娜柔美天籁的声音所深深温暖，苏格兰牧师（卡瑞·刘易斯 Gary Lewis饰）也吹响了风笛，划过寂静寒冷的雪夜，久久飘荡在战场上空。影片根据1914年圣诞节前夕发生的真实故事改编而成。本片荣获2006年第78届奥斯卡金像奖最佳外语片提名，2006年第63届金球奖电影类-最佳外语片提名，2006年第31届恺撒奖最佳影片提名，2006年第19届欧洲电影奖观众奖-最佳影片提名等多项大奖。', '黛安·克鲁格', '克里斯蒂安·卡里翁', 8.5, 7314, 'tt0424205', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p719001501.jpg', 0.4, 0.9, 12.4, 44.1, 42.1, '-0.304358,0.063486,-0.720500,0.538651,0.585623,-0.050220,0.517120,0.004109,-0.302665,0.098289,0.222111,0.742981,-0.466444,0.113175,0.700191,-0.142588,-0.423531,-1.075551,-0.182140,-0.208664,-0.061703,-0.107613,-0.214658,0.250509,0.052920,-0.507233,0.676543,0.007022,0.199262,0.645807,0.526786,0.019844,-0.135135,0.187580,-0.043152,-0.132546,0.555000,0.152781,-0.678263,0.520658,-0.385912,-0.384502,-0.546611,-0.203206,0.228545,0.104924,0.799618,-0.426720,0.348497,0.298009,0.677654,-0.386834,-0.495143,-0.069276,0.325567,0.195685,0.145089,0.348275,0.087492,0.472881,-0.396518,-0.369385,-0.232394,0.271628,0.047071,0.326236,-0.135107,0.600420,-0.066898,0.416976,-0.064831,0.040777,0.327942,0.111336,0.221986,0.240726,-0.096785,-0.031674,-0.187037,0.754092,0.503861,-0.231529,-0.744744,-0.061485,-0.262038,-0.614340,-0.054007,-0.187417,-0.482276,0.216807,0.477152,0.094223,0.246168,0.326660,-0.702525,0.041190,0.109915,-0.753950,0.059067,-0.068495,-0.213082,-0.929045,-0.073618,-0.109370,-0.181961,0.132563,0.091150,-0.105415,0.578904,-0.254821,0.720712,0.535111,-0.012982,0.358339,0.592366,0.220089,0.159981,-0.182665,-0.117124,0.417026,-0.307494,0.012502,-0.083115,0.241840,-0.323002,-0.026928,-0.318288,0.305464', '1780122', '1302279', '24751811', '26788667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438591', '哆啦A梦：大雄与翼之勇者', '动画', '大雄突发奇想，想要凭借自己的力量飞上天空。他自制翅膀，在学校的后山辛苦练习，可惜屡战屡败。正在这时，一架人力飞机通过异次元空间出现在上空，飞机连同驾驶员一同栽了下来。大雄、静香和哆啦A梦救助了这个拥有翅膀的奇怪家伙，他名叫古斯基，来自鸟的国度——鸟托邦。在修好飞行器后，古斯基准备返回自己的国家，结果胖虎和小夫突然出现，阴差阳错闯入异次元空间，为了救回伙伴，大雄他们也随同前往。鸟人警备队长官滋古连度对人类极度憎恨，他企图消灭所有人类，大雄和小伙伴在鸟托邦的冒险就此展开……本片根据日本漫画家藤子F不二雄的长篇同名漫画改编。©豆瓣', '大山信代', '芝山努', 8.4, 5734, 'tt0306741', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2520702800.jpg', 0.1, 1.2, 16, 44.2, 38.5, '0.033416,0.156336,-0.822746,0.389056,0.230083,0.014421,0.444372,0.123849,-0.166345,-0.193263,0.230308,0.798832,0.038367,-0.030522,-0.017051,0.050117,-0.482477,-0.534357,-0.148416,-0.075965,-0.426117,-0.331192,-0.066843,-0.342172,0.101863,-0.382151,0.681844,-0.029981,-0.220988,0.359816,0.148355,0.039554,-0.444447,0.316799,-0.488660,0.177277,-0.028738,0.063949,-0.120410,0.177671,-0.220239,0.052114,0.061588,-0.016502,0.036067,-0.081622,0.870409,-0.463866,-0.208033,-0.285021,0.020706,-0.353701,-0.259895,-0.369678,0.461277,-0.019284,-0.011467,-0.207964,0.111769,0.025822,0.081599,-0.229016,-0.576823,0.142922,-0.196390,-0.015285,-0.386812,0.210533,-0.039836,0.169087,0.231558,-0.285892,-0.003284,0.212813,0.074953,0.179944,-0.239794,0.205882,-0.223843,-0.056184,0.599877,-0.225578,-0.170889,0.240299,0.011838,-0.257074,-0.267795,-0.068852,-0.227079,-0.222069,0.460375,-0.056308,-0.376573,0.154861,-0.713140,0.094652,-0.294123,-0.041093,0.039301,-0.382122,-0.235130,-0.418755,0.113916,0.066428,0.010315,0.196214,0.096171,-0.246604,0.770573,-0.895189,0.066031,0.592902,0.450499,-0.135836,0.457543,-0.467206,-0.169767,-0.282762,-0.093659,-0.153193,0.229680,0.483423,0.265064,0.147682,-0.024151,0.025635,-0.480984,0.172865', '1457926', '1458894', '25774050', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438652', '无耻混蛋', '剧情', '故事分五章进行。二战中德占法国，德军上校汉斯（克里斯托弗·瓦尔兹 Christoph Waltz 饰）号称“犹太猎人”，在一次屠犹行动中，少女苏珊娜（梅勒尼·劳伦特 Mélanie Laurent 饰）侥幸逃脱。与此同时，八名美国犹太士兵在中尉奥尔多（布拉德·皮特 饰） 的带领下潜入德占法国刺杀德国军人，其行动神出鬼没，手法残忍，对德军造成相当威胁，被称为“杂种”。三年后苏珊娜来到巴黎继承了姑母的电影院，结识了德国战斗英雄，电影《国家荣耀》的主演弗里德里克（丹尼尔·布鲁赫 Daniel Brühl 饰）。对苏珊娜一见钟情的弗里德里克说服德国宣传部长约瑟夫·戈培尔（西尔维斯特·格洛斯 Sylvester Groth 饰）在苏珊娜的影院首映《国家荣耀》，希特勒（马丁·乌特克 Martin Wuttke 饰）本人也将出席。苏珊娜决定借放映之机烧毁影院；而在德国间谍女演员布里奇特（戴安娜·克鲁格 Diane Kruger饰）的安排下，英美联合的刺杀行动“奇诺”也将在首映当晚行动……本片被提名2009年戛纳电影节金棕榈奖，获第82届奥斯卡最佳导演、最佳影片等七项提名，并荣获奥斯卡最佳男配角奖（Christoph Waltz）及戛纳电影节最佳男演员奖。', '布拉德·皮特', '昆汀·塔伦蒂诺', 8.6, 442092, 'tt0361748', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575043939.jpg', 0.3, 0.9, 10.6, 42.8, 45.3, '-0.102979,-0.129676,-0.604865,0.555681,0.365245,-0.205000,0.252689,0.103835,-0.389815,-0.054870,0.355687,0.820233,-0.401591,-0.228136,0.608968,-0.111126,-0.683395,-0.631595,0.008016,-0.145298,0.128478,-0.540960,-0.413227,-0.162872,-0.088735,-0.516746,0.655674,-0.114205,-0.179686,0.491591,0.662282,0.321994,0.232678,0.044054,0.232049,0.090849,0.652529,-0.579191,-0.530543,0.701894,-0.153375,-0.240413,-0.191625,0.078451,0.234361,0.317297,0.638164,-0.348528,0.375490,-0.280408,0.361133,-0.386744,0.094014,0.071145,0.251016,-0.190578,0.076785,0.472744,0.157437,0.166073,0.106209,-0.232844,-0.320596,0.325841,0.140891,0.207993,-0.465385,0.305341,-0.440214,0.422971,-0.074276,0.059508,0.000432,0.404787,0.128443,-0.015518,0.258780,0.170048,-0.367265,0.374266,0.270290,-0.284862,-0.256084,-0.043232,-0.092868,-0.568785,0.057174,-0.273533,-0.210442,0.042008,0.474457,-0.349375,0.569854,0.183997,-0.409733,-0.262505,-0.384120,-0.248577,-0.013159,-0.071228,0.278273,-1.157346,0.019754,0.125166,-0.115622,0.030744,0.135192,0.006531,0.480039,-0.285238,0.205227,0.469829,0.430751,-0.041275,0.623259,0.138886,0.086207,-0.366243,-0.177619,0.465516,0.058315,-0.160190,-0.031123,0.133799,0.042215,-0.422730,-0.005835,0.175852', '1298616', '2075345', '34961898', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438689', '美丽的大脚', '剧情', '张美丽（倪萍 饰）的丈夫多年前因无知犯法被枪毙了，数年后也失去了孩子。她深知没有文化的后果，于是美丽当上了村里面的老师，教全村的孩子们知识。城里的老师夏雨（袁泉 饰）来这个穷乡僻壤当志愿者，夏老师的到来给张美丽与孩子们带来了许多新鲜的知识与希望，可是夏老师对艰苦的环境并不适应，是张美丽那淳朴真实的感情逐步的感动了夏老师，即使丈夫前要带走夏老师，她都不舍离去。张美丽与放映员王树（孙海英 饰）有暧昧的事也被夏老师知道了，她知道王树的婚姻生活并不美满，也极力鼓励张美丽在这件事上做出抉择，为自己打算一番。他们相处和睦，可是夏老师还是要回到北京，夏老师让张美丽一起去，可是美丽丢不下孩子们，于是一大群人到来城里，城里人的歧视也让美丽清楚一定要孩子们好好念书。夏老师说服丈夫帮助改善村里的经济，本来以为不会在见到张美丽的，却因一场意外，夏老师再次回到村里去……', '倪萍', '杨亚洲', 7.5, 28330, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2227062801.jpg', 0.5, 2.5, 34.8, 47.7, 14.5, '-0.152382,0.077425,-0.505659,0.676982,-0.517179,-0.607083,0.573798,-0.149769,-0.473915,-0.445891,-0.521321,0.310149,0.048869,0.846523,0.089993,-0.007738,-0.138459,-0.514059,-0.170173,-0.026320,-0.359224,-0.572417,0.261123,-0.451881,0.019232,-0.124496,0.134107,0.239562,-0.331990,0.043974,0.382876,-0.020103,-0.157779,0.488679,0.074083,0.036402,-0.319094,0.320255,-0.492836,-0.184676,0.346156,-0.197580,-0.424434,-0.057090,0.478354,0.009897,0.568297,-0.135796,-0.619071,-0.068007,0.521924,-0.188065,0.263453,0.402426,0.427557,-0.058199,0.176768,-0.282143,-0.247759,-0.010590,0.154823,-0.325077,-0.332556,0.137959,0.208565,-0.299340,-0.949063,0.378332,0.335658,-0.082615,0.199166,-0.443331,0.446871,0.398832,0.358919,0.442070,0.158887,0.253457,-0.167744,0.386198,0.900875,0.344297,-0.091182,0.009505,-0.533882,-0.538056,-0.093439,-0.187595,-0.802931,0.400886,0.237320,0.005206,-0.117625,0.082646,-0.111649,-0.186794,-0.259655,-0.184524,-0.084832,-0.484481,0.301243,-0.205280,0.144402,-0.454027,-0.368671,0.284019,0.098786,-0.451025,0.998451,-0.727897,0.274240,0.308034,0.317209,-0.713041,0.553502,0.381643,-0.135730,-0.089234,-0.260009,0.135215,0.117748,0.172880,0.325256,0.336106,-0.130436,0.043056,0.012521,0.530827', '26348103', '24879820', '1877596', '26730542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438708', '无穷动', '剧情', '大年三十的除夕夜，三个混迹于中国上流社会的成功女性——时装模特琴琴（李勤勤）、房地产经销商夜太太（平燕妮）和才貌双全的艺术家拉拉（刘索拉）——应同样是成功女性的时尚杂志出版商妞妞（洪晃）的邀请，来到她家过春节。妞妞请客的目的是想找出哪一位是她离家出走的丈夫的情人，而众人也知所赴的是鸿门宴，所以一开始讲话时都很小心翼翼。随着她们对各自情感故事的讲述，妞妞发现谁是她丈夫的情人已经不再重要，因为某种程度上她和她们是一样的人，在成功自信的外表下，心里所藏的，是那些过去年代遗留下来的不可弥补的情感歉疚和无穷动的欲望。©豆瓣', '洪晃', '宁瀛', 6.7, 12017, 'tt0477927', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2546682556.jpg', 4.4, 12.1, 40.7, 31.1, 11.7, '0.481994,-0.080364,-0.764342,0.566368,-0.226842,-0.106417,0.818366,-0.158155,-0.681738,-0.130538,0.131842,0.810147,-0.241399,0.577652,0.163423,0.094619,-0.052100,-0.661940,-0.204721,-0.222942,-0.044508,-0.407635,-0.154857,-0.068722,-0.194843,-0.142759,0.541889,-0.031856,-0.165340,0.366518,0.569877,0.260735,0.011501,0.519386,-0.377727,0.060324,-0.238615,-0.038555,-0.431506,0.095422,0.206711,-0.150937,-0.254829,0.237769,0.001202,0.329179,0.396235,-0.242469,-0.093893,0.182516,0.576213,-0.291295,-0.031214,0.292135,0.365732,-0.090531,0.417094,0.294383,0.003315,-0.022252,-0.139456,0.027447,-0.730590,-0.080254,0.271603,0.267883,-0.646441,0.353447,-0.054254,-0.154267,0.040707,-0.491818,0.416973,0.235730,0.033499,0.398297,-0.138204,0.066317,-0.520057,0.181219,0.786441,0.326804,0.118522,0.436322,-0.381014,-0.489337,-0.080436,-0.251434,-0.518509,0.076618,0.094307,0.074515,-0.178597,0.087783,-0.634244,-0.034708,0.095542,-0.310314,0.174998,-0.583906,-0.020364,-0.456832,-0.184782,-0.880734,-0.357260,-0.078856,0.361491,-0.402071,0.963294,-1.135040,0.084477,0.543389,0.206681,-0.582859,0.839572,0.094418,-0.067844,-0.213847,0.015344,-0.024305,-0.073139,0.038476,-0.061203,0.562261,0.090247,-0.148257,-0.314662,0.459218', '26354526', '1303112', '1292219', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438734', '内陆帝国', '剧情', '在由金斯利（杰瑞米·艾恩斯 Jeremy Irons 饰）导演的电影里，尼基（劳拉·邓恩 Laura Dern 饰）扮演了一个名叫苏珊的女人，她在剧中的情人是戴文（贾斯汀·塞洛克斯 Justin Theroux 饰）所扮演的比利。关于这部电影，有一个传说，最先拍摄这个剧本的剧组遭遇了一些可怕的离奇经历，导致电影流产。尼基有一个控制欲爆棚的丈夫，在丈夫给予的巨大压力下，尼基在潜意识里躲进了苏珊这个虚构的角色中。随着时间的推移，一些奇怪的人出现在了尼基的身边，一些科学无法解释的事件接连发生在尼基的生活里，而尼基呢，在混沌和迷惘之中，她已经无法分辨，自己究竟是尼基，还是苏珊。©豆瓣', '劳拉·邓恩', '大卫·林奇', 7.7, 8972, 'tt0460829', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2373527855.jpg', 3.2, 6.1, 24.1, 36.9, 29.6, '0.328211,0.087693,-0.816513,0.711246,0.033005,-0.073297,1.104225,0.106882,-0.375586,-0.533583,0.342909,0.868865,-0.359652,0.091516,0.224086,-0.039571,-0.426794,-0.626155,-0.170793,-0.293456,-0.277603,-0.572550,-0.689604,-0.146598,-0.058367,-0.362339,0.575399,-0.001662,-0.377335,0.098877,0.531182,0.494920,-0.083440,0.350283,0.114121,0.446760,0.179854,-0.088149,0.017667,0.274103,0.367290,-0.194326,-0.046568,0.083201,0.030984,0.432291,0.608056,-0.452495,-0.094814,0.142571,0.726243,-0.157940,-0.167259,-0.039300,0.092891,-0.193297,0.029620,-0.150629,-0.382917,0.188207,0.153163,-0.057324,-1.103947,-0.132153,0.109744,0.533884,-0.619996,0.242146,-0.062535,-0.148206,0.160966,-0.322921,0.306529,0.271789,0.357107,0.471018,-0.047378,-0.101640,-0.302176,0.255304,0.610042,0.086761,-0.343016,0.730692,-0.457741,-0.338613,-0.450173,0.015942,-0.854309,0.047246,0.471751,-0.074467,-0.259219,0.403386,-0.339088,0.062270,-0.053960,-0.243065,-0.205647,-0.223676,-0.128250,-0.687918,-0.399954,-0.459974,-0.040402,-0.206178,-0.198037,-0.338777,0.677834,-0.756587,0.253119,0.606845,0.055459,-0.189594,0.631848,0.075844,0.245061,-0.004882,0.006564,0.379490,0.100938,0.090191,-0.066241,0.611361,0.117025,-0.215763,-0.619579,0.605540', '34890458', '1303077', '35360296', '3569911');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438790', '怪谈新耳袋 电影版', '恐怖', '耳袋，即是把听到的怪异诡秘的故事，好好地放进袋子里收藏起来。电影改编自日本畅销灵异小说《怪谈新耳袋》，由99则独立的灵异故事组成。故事内容都是民间种种怪异骇人的传言，例如公寓洗手间的女鬼、照片上莫名多出来的人、发出幽幽呜咽的音乐盒、扔不掉的儿童自行车……承袭了日本恐怖电影的一贯风格，每桩灵异事件，都在引发毛骨悚然的恐怖情绪。©豆瓣', '竹中直人', '吉田秋生', 7, 8469, 'tt0468774', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2734823435.jpg', 2, 8.1, 41.2, 34.4, 14.3, '0.576291,-0.040649,-0.423808,0.514324,0.334220,0.445326,1.044168,0.009750,-0.478695,0.013424,0.158462,0.389312,-0.531529,-0.005106,0.044311,0.260307,-0.456619,-0.430637,-0.533441,-0.233366,-0.118725,-0.165935,-0.264876,-0.454010,0.239509,-0.341228,0.119976,0.129355,-0.692162,0.213196,0.238389,0.602419,-0.648372,0.026572,-0.234518,0.029519,-0.335724,0.259968,0.245126,-0.343133,0.145838,-0.367944,-0.046840,0.095266,-0.017960,0.028548,0.599443,-0.232507,-0.347365,0.388311,0.864682,0.202099,-0.528650,-0.189546,0.159952,0.607565,0.531258,0.242600,0.151793,0.180907,0.251701,0.232859,-0.624095,-0.044633,0.130042,0.489903,-0.175290,0.400463,-0.131612,0.102743,0.362871,-0.063784,0.345833,-0.458967,0.570687,0.669110,0.071420,0.226499,-0.409336,0.428600,0.102456,0.025532,-0.243127,0.343529,-0.288441,-0.546044,-0.158174,-0.079923,-0.302303,0.107509,0.396289,-0.194459,-0.245555,0.483259,-0.746836,-0.011623,0.417731,-0.428713,0.007753,0.045798,-0.347143,-0.516852,-0.299377,-0.108672,0.000617,-0.197092,0.317375,-0.168124,1.061915,-0.093624,0.116434,0.577838,-0.305488,0.076177,0.264702,-0.238118,-0.199381,0.204001,-0.157568,-0.122830,0.093308,0.413084,0.077125,0.578925,-0.036455,-0.403030,-0.535335,0.561623', '2364051', '27199913', '4181031', '1299767');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438924', '蛇鹤八步', '剧情', '蛇鹤八步是由武林八大门派掌门们共同研究所得出的拳法，拥有着极高的威力，是武林中人都想要得到的宝物。然而，不幸接连发生，八大掌门统统命丧黄泉，蛇鹤八步也因此失传，成为了江湖上的传说。徐英风（成龙 饰）是一位神秘的侠客，某日，他带着蛇鹤八步的拳谱重现江湖，掀起了重重涟漪，亦引爆了一场腥风血雨。一些人想要夺得拳谱成为武林的霸主，一些人想领略蛇鹤八步的风采，一些人以为徐英风正是当年凶案的罪魁祸首，一时间，徐英风成为了江湖上人人得而诛之的存在。不过，徐英风并不把这些想取他性命的人放在眼里，他的目的只有一个，那就是找到凶手，为掌门们报仇。©豆瓣', '成龙', '陈志华', 6.5, 3903, 'tt0078251', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2179819766.jpg', 1.3, 8.9, 59.8, 21.2, 8.7, '0.263822,0.034558,-0.560355,0.742976,-0.149227,0.067962,0.246045,-0.228557,-0.597118,-0.508529,0.267275,0.697067,0.081673,0.011325,-0.044194,-0.105002,0.461312,-0.688905,-0.026859,-0.397857,-0.096557,-0.067420,-0.436606,-0.054956,-0.229946,-0.260764,0.525826,0.373575,-0.512348,0.191976,0.249603,0.254014,-0.134704,0.192651,-0.607651,-0.051816,-0.350723,0.039181,-0.378213,0.121466,-0.429944,-0.353817,-0.233449,0.309831,-0.346416,0.204608,0.236494,-0.235663,-0.021658,-0.142328,0.114276,-0.439384,-0.181494,-0.069030,0.376999,0.060127,0.154175,0.488468,0.044067,0.011009,0.238023,-0.026475,-1.190356,-0.001895,0.383460,0.215076,-0.317846,0.535491,-0.266585,-0.171246,-0.367558,-0.136797,0.384724,0.093461,0.323813,-0.105311,-0.062664,-0.059067,-0.976171,0.235071,0.859250,-0.075238,0.063797,0.036374,0.365186,-0.493449,-0.115266,-0.763804,0.065585,0.105438,0.498168,0.000317,0.111854,0.383900,-0.503014,-0.053276,-0.150531,-0.215302,-0.153772,-0.255373,-0.041730,-0.303601,-0.114794,-0.179183,-0.317832,-0.296048,0.303130,-0.470745,1.096683,-0.700249,0.247245,0.278788,-0.179739,-0.630151,0.738787,-0.094553,0.066567,0.041329,-0.415255,-0.045547,0.386927,0.288008,-0.084642,0.384798,0.042269,-0.212507,-0.140092,0.234993', '27602116', '3718665', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1438938', '第九突击队', '剧情', '影片根据真实故事改编，以苏联入侵阿富汗事件为背景。1987年到1989年期间，阿富汗战场异常惨烈。由于穆斯林的强烈抵抗，苏联在阿富汗损兵折将，死伤无数。西伯利亚克拉斯诺亚尔斯克，六名新兵应征入伍，以协助前线战斗。他们接受严苛的魔鬼训练，进行各种特种培训。1987年末，这支奇兵组成“第九突击队”前往阿富汗，受命占据3234高地，以掩护苏联士兵撤退。第九突击队保护苏军大部队安全通过，而自己却弹尽粮绝。血腥而残酷的战场上，他们视死如归的身影显得异常悲壮。©豆瓣', '费奥多尔·邦达尔丘克', '费奥多尔·邦达尔丘克', 7.4, 6909, 'tt0417397', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2186592740.jpg', 0.9, 5.4, 34, 42.3, 17.4, '-0.102015,-0.173009,-0.897132,0.842881,0.309650,0.292286,0.235036,-0.473702,-0.463523,-0.006054,0.547663,0.321869,0.589117,-0.441002,0.219807,-0.587432,-0.388703,-0.667194,-0.414577,0.137996,-0.437943,-0.359488,-0.448921,-0.409864,0.140888,-0.531773,1.119393,0.366987,-0.497106,0.667110,-0.048874,0.405541,-0.195776,0.318668,0.461269,-0.555879,0.090026,-0.349230,-0.450760,-0.055491,-0.468667,-0.266216,-0.464493,0.130419,0.083477,0.469501,0.850917,-0.520634,-0.036362,-0.251506,0.162853,-0.494029,-0.292709,0.052376,0.538514,0.218822,-0.165089,0.118194,0.213311,0.312603,-0.862533,-0.217969,-0.538573,-0.185554,-0.067928,-0.041315,-0.445116,0.248747,-0.429305,0.508938,0.538449,-0.234129,-0.145843,0.879181,0.217958,0.385235,-0.202005,-0.060176,-0.184057,0.333515,0.909984,-0.257364,-0.539648,-0.552009,-0.360692,-0.381944,0.259984,-0.801962,-0.032804,0.164882,-0.187392,-0.417403,0.198625,0.335079,-0.885310,0.158502,-0.348577,-0.744919,-0.334872,0.089955,-0.014398,-1.177832,-0.213471,-0.217922,-0.220992,0.510738,-0.069217,0.220940,0.869701,-0.521900,0.148624,0.592058,0.438087,-0.429160,-0.048855,0.221094,0.303827,-0.172192,0.002242,0.633584,-0.072958,0.257701,0.163152,0.181609,-0.485219,-0.053235,-0.257314,0.170105', '2369613', '35058077', '20274039', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1439205', '熊猫家族', '动画', '第一话：自幼失去父母的少女米米和奶奶住在密林深处。某天，奶奶回乡赶赴爷爷的忌日，只留下米米一人居住。这时，一对熊猫父子偶然闯进她的家中。米米成为熊猫爸爸的女儿，同时成为小熊猫胖胖的妈妈，这三个天真的小家伙组成了一个奇怪而有趣的家庭。第二天，胖胖随秘密去学校，结果引起一场混乱。当他们回到家不久，动物园的园长随着警察叔叔前来抓捕偶然脱逃的熊猫父子……第二话：有人偷吃掉胖胖的咖喱饭，还动了他的乐器。随着脚印，米米他们发现了正在床上呼呼大睡的小老虎。小老虎是流动马戏团的演员，他迷路来到了米米家。经过一番周折，小老虎终于回到马戏团，找到了自己的妈妈。当晚，一场大雨瓢泼而下，淹没了米米的房子，也困住了马戏团的动物们……©豆瓣', '杉山佳寿子', '高畑勋', 7.9, 14778, 'tt0069058', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2192369280.jpg', 0.3, 2.7, 27.9, 40, 29.2, '0.132102,-0.230180,-0.669588,0.081971,0.125905,-0.308128,0.624404,0.257086,-0.355166,-0.332128,0.122360,0.311231,-0.277602,0.484887,0.361312,-0.115312,-0.365431,-0.375595,-0.110520,-0.242293,-0.055236,-0.219046,-0.152720,-0.245024,0.200449,-0.027848,-0.029580,-0.305691,-0.087962,0.712578,-0.007160,-0.213718,-0.157492,0.386416,-0.414419,0.314600,0.030265,0.003933,0.066725,0.253253,0.032943,0.235389,-0.017426,-0.537370,0.190889,0.176367,0.993309,-0.408800,-0.244094,-0.208351,-0.001107,-0.425588,-0.186754,-0.108304,0.581884,-0.227259,0.467692,-0.342964,-0.107366,0.080454,0.329851,-0.377617,0.086784,0.010534,-0.114164,0.107035,-0.196056,0.140676,0.134967,0.001978,0.528830,-0.603191,0.073414,0.272031,0.007057,0.569274,-0.624288,0.225674,-0.890594,-0.033587,0.915099,-0.007767,0.279616,-0.107444,0.112240,-0.547932,0.263520,0.076806,-0.326914,0.136574,0.627132,-0.079379,-0.203518,0.290057,-0.815441,-0.345516,-0.338964,-0.188550,0.226096,-0.561100,-0.062781,-0.234447,0.144166,0.226510,0.007385,0.281983,-0.086930,-0.046647,0.654257,-0.345680,0.676217,0.195847,0.464572,0.061487,0.754244,-0.365229,0.337061,0.019268,0.113734,-0.014419,0.100049,0.654416,0.304903,0.534693,-0.032033,-0.155232,-0.638098,0.019682', '1310175', '26882457', '21619567', '3214137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1439286', '辛瑞那', '剧情', '美国石油巨头Connex公司准备与一家获得哈萨克斯坦石油开采权的小公司Killen合并，并就开采权向海湾某石油国家的年轻王子纳西尔（亚历山大•希德迪格 Alexander Siddig 饰）施加压力。瑞士日内瓦某能源咨询公司的研究员布莱恩•伍德曼（马特•达蒙 Matt Damon 饰）代表公司参加了纳西尔王子在西班牙马贝拉行宫的聚会，后成为纳西尔王子的经济顾问。但美国政府却支持纳西尔王子腐败无才的弟弟继承王位，并派出CIA特工鲍勃（乔治•克鲁尼 George Clooney 饰）前往黎巴嫩实施刺杀纳西尔王子的计划。与此同时，华盛顿一家律师事务所派班尼特（杰弗里•莱特 Jeffery Wright 饰）对Connex-Killen合并事宜进行事前调查……本片获奥斯卡、金球奖和英国电影电视协会最佳男配角奖（乔治•克鲁尼），并获奥斯卡奖最佳原创剧本和金球奖最佳电影音乐提名。', '乔治·克鲁尼', '斯蒂芬·加汉', 7.3, 6973, 'tt0365737', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1665737247.jpg', 0.8, 4.9, 38.1, 41.1, 15.1, '-0.370047,-0.005528,-0.319396,0.467893,0.424291,-0.519954,0.235342,0.439719,-0.291028,-0.309727,0.088659,0.836203,-0.072213,-0.146325,0.553476,0.328975,-0.871618,-0.572750,-0.029253,0.017750,0.388138,-0.550865,-0.051978,-0.319704,-0.053402,-0.226156,0.888865,-0.287836,-0.192104,0.432586,0.373758,-0.055608,0.026400,-0.007830,0.302197,-0.069223,0.823895,-0.188896,-0.854119,0.552093,-0.001175,0.209645,-0.080704,-0.210700,0.677068,0.337917,0.075947,0.001872,0.480273,-0.413616,0.381027,-0.253638,0.217678,0.032312,0.371580,-0.001633,0.239202,0.293231,-0.038775,-0.326911,0.286605,-0.400313,-0.583170,0.267776,0.116930,0.296655,-0.153307,0.233915,-0.535729,0.181020,0.005839,-0.098715,0.091679,0.556806,0.283662,-0.156286,0.175216,0.203325,-0.459881,0.352220,0.019516,-0.150564,-0.263465,-0.173351,-0.001304,-0.830574,-0.102749,-0.128215,-0.185995,-0.067989,0.519461,-0.240431,0.526696,0.269097,-0.444005,-0.195753,-0.217001,-0.445974,0.495229,-0.163489,0.413988,-1.365462,0.094088,0.121449,0.082691,-0.280290,0.541539,0.060790,0.399073,-0.384778,-0.034952,0.628485,0.559587,-0.395442,0.529747,-0.087762,0.126564,-0.584598,-0.308691,0.162838,0.087966,0.153405,-0.312048,0.084729,0.298679,-0.669779,-0.122214,-0.022129', '1293572', '1298616', '34961898', '3077791');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1439400', '焦裕禄', '剧情', '1962年冬，焦裕禄（李雪健）被派往灾荒严重的河南省兰考县任县委第二书记，眼见街上成群结队的乞丐、纷纷逃亡外地的饥民，他心情十分沉重，下决心根治长期困苦兰考百姓的风沙、水涝和盐碱“三害”，不久，他在多次深入基层做调查研究的基础上，制定出治理“三害”的方案。但他深入群众的工作方式招致县长、县委副书记吴荣先（李仁堂）的不满。升为县委书记后，焦裕禄不顾肝脏经常胀痛，几乎每日都坚持去治理“三害”第一线工作，很得人民爱戴，吴荣光指使人就某件事借题发挥想将焦裕禄整垮，结果全县群众聚在一起为他鸣冤。其后兰考遭遇特大水灾，焦裕禄的肝病虽然已到晚期，仍坚持去抗灾第一线。©豆瓣', '李雪健', '王冀邢', 7.5, 10265, 'tt0470385', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2560061956.jpg', 2, 3.6, 33.6, 36.3, 24.4, '-0.094272,-0.182475,-0.556416,0.199965,0.156388,-0.098131,0.099494,0.383138,-0.581650,0.033044,0.249966,0.187476,0.028620,0.081070,0.059670,-0.384730,-0.258852,-0.509562,-0.100266,0.385356,-0.186350,-0.243481,-0.109982,-0.165915,-0.305313,0.142040,0.237074,0.292981,0.057034,0.248991,0.013045,0.326875,0.239585,0.442968,0.189255,-0.181423,-0.004568,-0.204268,-0.304696,-0.033861,0.342441,-0.510870,-0.379951,0.060257,0.265304,0.558996,0.284923,0.093854,-0.241274,-0.000581,0.343483,-0.440734,0.243412,0.225262,0.690644,0.355570,-0.110990,0.304966,-0.236469,-0.072568,-0.175283,-0.179562,-0.427360,-0.212662,0.064386,0.019745,-0.671595,0.243131,0.151964,0.033455,-0.055482,-0.422169,0.226742,0.547820,-0.154512,0.460933,-0.251255,0.056346,-0.056681,0.545482,0.706097,-0.036844,-0.207213,-0.233050,-0.446050,-0.140744,0.403634,-0.384107,-0.175978,-0.167108,-0.101651,-0.345939,-0.079766,0.256157,-0.090056,-0.022504,-0.219008,-0.189415,-0.096440,0.362529,-0.050334,-0.352266,0.134395,0.108040,0.080972,-0.134827,0.291866,-0.222583,0.501210,-0.378115,-0.107120,0.302248,0.019694,-0.804578,0.375934,0.265491,0.140474,-0.032855,-0.070812,-0.076969,0.059086,0.866387,0.173831,0.108977,-0.157053,-0.333869,-0.035212,0.464234', '1422283', '19994974', '1307577', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1439579', '名侦探柯南：引爆摩天楼', '喜剧', '知名建筑设计师森谷帝二这日邀请新一参加在他府上举办的茶会，柯南只得电话拜托小兰。柯南、小兰及毛利小五郎三人未入森府，已被绝对对称的宏伟建筑吸引。衣香鬓影的茶会上，森谷帝二令人诧异地大声攻击年轻设计师，讲建筑的美学准则要被他们破坏殆尽。柯南在规定时间内将他出给众宾客的难题破解，被获准和小兰一起参观陈有他设计图的展览馆，交谈中，他感慨30多岁初成名时的作品不够对称称不上完美，并从小兰口中打探到她要与新一在米花大楼约会为新一庆生的诸多细节。不久，柯南连接数通向新一挑战的电话，对方均告知他已在某地放置会在某时爆炸的炸弹，柯南将危机一一化解后，开始与警方、毛利一起分析到底是何人所为。电视报道其中最为轰动的爆炸案时，柯南由画面联想到所有炸弹放置的地点附近均有森谷帝二自认不完美的作品，心中一惊。众人拜访森谷帝二时，柯南暗中将他的宅邸查看，找出凶犯正是他的证据，原来他是狂热的完美主义者，想亲手毁掉年轻时因妥协设计出的不绝对对称作品，并借机报复没令他的宏伟设计夙愿在西多摩市达成的新一。被抓一刻，森谷帝二的冷笑令柯南醒悟：米花大楼亦是他不完美的作品，小兰正在那里等新一赴约。', '高山南', '儿玉兼嗣', 8.5, 125026, 'tt0131479', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453728121.jpg', 0.1, 0.6, 13.5, 47.4, 38.4, '0.347160,0.068326,-0.712012,0.367548,0.071308,-0.121152,0.462026,-0.038295,-0.334431,-0.312598,0.265543,0.730044,-0.515380,0.189290,0.257725,-0.039683,-0.259506,-0.591163,-0.353182,-0.282342,-0.293719,-0.453058,-0.174384,-0.214398,0.061447,-0.092561,0.142961,0.085578,-0.279565,0.336088,0.230784,0.182271,-0.327497,0.327626,0.044374,-0.084950,0.112556,-0.088710,-0.185972,0.090255,-0.213348,-0.393218,-0.200913,0.258189,-0.068596,0.344041,0.474731,-0.140051,-0.033053,0.070797,0.386001,-0.009101,0.002713,0.206877,0.285233,-0.078432,-0.040110,0.269627,-0.446248,0.109187,0.065282,-0.224948,-0.842469,-0.043860,0.048863,0.064753,-0.295188,0.265697,-0.131283,-0.063323,0.160529,-0.264523,0.098526,0.277082,0.256067,0.203188,-0.019776,0.027581,-0.292596,0.213042,0.364082,0.064090,0.024545,0.115867,-0.138316,-0.365148,-0.174500,-0.167384,-0.069809,0.108552,0.420162,0.201540,-0.010742,-0.132814,-0.496682,-0.261315,-0.264162,-0.292082,0.073468,-0.210577,-0.364831,-0.850596,-0.025480,-0.156180,-0.269034,-0.045193,0.144085,-0.295902,0.722399,-0.739348,-0.108242,0.318227,0.096142,-0.444620,0.576561,0.110065,-0.108922,-0.101435,-0.069720,-0.178933,0.065073,0.492532,0.086046,0.405503,0.039194,-0.436680,-0.637532,0.231894', '3318306', '25928048', '26577354', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1439890', '情癫大圣', '剧情', '唐僧（谢霆锋饰）在取经的路上千辛万苦，他们来到了莎车城，在热烈的欢迎仪式上遭到了树妖的偷袭，把他的徒弟都抓走，剩下了唐僧一人。在这个镇上，唐僧遇到了一只样子丑陋但性格活泼的蜥蜴妖美艳（蔡卓妍饰），美艳对唐僧一见钟情，唐僧被美艳的性情感动，两人都严重违反了天规。唐僧发现美艳藏起了一个天外来客（范冰冰饰），美艳更与这位美丽的天外来客成了情敌。原来美艳并不是一只妖精，而同样也是一名天外来客。美艳不顾安全救回了唐僧的徒弟，愿意接受天庭的审问，唐僧为了救回可怜的美艳，竟拿起了大刀……©豆瓣', '谢霆锋', '刘镇伟', 5.5, 125001, 'tt0469050', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p486679196.jpg', 9.7, 29.3, 43.2, 13.3, 4.6, '0.499825,0.050139,-0.550246,0.537832,-0.377375,-0.113108,0.793885,0.095391,-0.168617,0.019990,0.364504,0.784336,-0.251380,0.189693,0.009467,0.097810,0.176312,-0.322606,-0.245612,-0.076338,-0.030973,-0.121682,-0.244749,-0.078351,0.003251,-0.503881,0.311669,-0.098933,0.162188,0.699399,0.578641,-0.064741,-0.144936,0.193609,-0.489622,0.145122,-0.130464,0.125430,0.280048,0.346861,-0.177022,-0.326169,0.097433,0.401465,-0.536084,0.417455,0.667546,-0.387638,-0.507712,-0.304863,0.348096,-0.366560,0.102208,0.430767,0.429744,-0.434279,0.130031,-0.044546,-0.238873,0.097710,0.339326,-0.322820,-0.402776,0.279602,0.064875,0.283627,-0.465014,0.463980,-0.095269,0.113159,0.163537,-0.365139,0.219819,-0.013076,0.240785,0.361907,0.193995,0.166466,-0.656027,0.261360,0.557370,0.202392,0.011359,0.582213,-0.192093,-0.485573,-0.028426,-0.413558,-0.340115,0.184977,0.560453,-0.170448,-0.308754,-0.060155,-0.687521,-0.231583,-0.340670,0.283820,-0.478705,-0.333473,-0.152308,-0.165276,-0.183772,-0.622111,-0.358615,0.133013,0.110286,0.011852,1.044309,-0.523592,0.061587,0.667350,0.153197,-0.640380,0.625440,0.166430,-0.077983,0.002369,-0.168835,0.167764,0.217956,0.308268,0.293680,0.452595,-0.441309,-0.175854,-0.497702,0.263783', '1302661', '26348103', '3811356', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1440164', '大菩萨岭', '剧情', '幕末时期，时局动荡，暗流涌动。甲州武士机龙之助（仲代達矢 饰）剑术绝伦，却拥有一颗邪恶阴暗之心。在一次剑术比赛前夕，对手宇津木文之丞（中谷一郎 饰）的妻子阿滨（新珠三千代 饰）恳求他败给丈夫，甚至不惜委身于他。然而在次日的对决中，龙之助仍然以绝对优势杀死文之丞。在此之后 ，他和被休的阿滨离开甲州，浪迹江湖。两年后，他以杀手身份加入新选组，替幕府斩杀反抗义士。在此期间，文之丞弟弟兵马（加山雄三 饰）也来至江户，并拜入剑豪岛田虎之助（三船敏郎 饰）的门下，等待为兄长报仇的良机。宿命的相逢无可避免……本片根据中里介山同名原著中“甲源一刀流の巻 - 03 壬生と島原の巻”部分改编。该小说在报纸上连载23年，被称作“世界上最长的历史小说”。©豆瓣', '仲代达矢', '冈本喜八', 8.7, 12065, 'tt0060277', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2187846310.jpg', 0.3, 0.9, 10.3, 42.5, 45.9, '-0.430284,0.202645,-0.360917,0.673858,0.134213,-0.106067,0.262039,0.142395,-0.201342,-0.457648,0.247703,0.634473,0.080218,-0.079644,0.293192,-0.271319,0.146796,-0.687819,0.111794,-0.152579,-0.004917,-0.277206,-0.205171,0.200051,-0.242218,-0.281566,0.964606,0.275330,-0.172326,0.421903,0.216295,0.444054,-0.226264,0.214379,0.082902,-0.094940,-0.246496,0.001757,-0.246183,0.299477,-0.344560,-0.470514,-0.131222,0.061281,-0.122149,0.188428,0.729390,-0.247993,0.079727,-0.260157,0.166414,-0.036457,-0.287810,0.112713,0.409063,0.111144,0.075945,0.313761,-0.034662,0.061878,-0.227773,-0.117986,-0.561553,-0.208471,0.201343,-0.048323,-0.436672,0.466342,-0.369911,-0.020892,-0.107918,-0.213865,-0.209027,0.035623,0.277430,0.007994,-0.228632,-0.057621,-0.063851,0.325796,0.324020,-0.224632,0.052173,0.062906,0.449074,-0.181957,-0.239608,-0.560218,-0.299928,0.023479,0.066911,0.068381,0.045909,0.471879,-0.453736,-0.066768,-0.306542,0.108609,0.145294,-0.131768,0.002666,-0.330590,-0.013110,-0.102154,-0.060257,0.061522,0.525294,-0.424806,0.765894,-0.550353,0.061453,0.176602,0.224066,-0.333259,0.510620,0.178252,-0.061073,-0.007482,-0.056376,0.364145,0.268669,0.146663,0.058038,0.093822,-0.052016,-0.073214,-0.365287,0.332035', '25880986', '26759820', '10467125', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1440703', '爱再来一次', '剧情', '伊恩·温德姆（保罗·尼科尔斯 Paul Nicholls 饰）与女友萨曼莎·安德鲁斯（詹妮弗·洛芙·休伊特 Jennifer Love Hewitt 饰）像任何一对平凡的情侣一样，每天忙着自己的生活，很少时间独处。一次争吵过后，前来道歉的peter犹豫着要不要上出租车，因为这份犹豫女友选择离开。不到一分种，出租车 在前面街口与一辆卡车相撞，女友香消玉陨。悲痛万分的peter在次日清晨醒来发现又回到了之前的一天，女友安然无恙，一切按照既定步骤发展。如果再来一次，Peter不敢想着居然成为事实。他放下一切业务，与女友登山、散步、彼此倾诉，爱意缠绵。到了那个决定性的夜晚，那辆夺命的出租车上，他毫不犹豫地上车，并且在致命的一击来到之时，俯身保护她。如果再来一次，他会用生命来爱她。©豆瓣', '詹妮弗·洛芙·休伊特', '吉尔·约格尔', 8, 78143, 'tt0332136', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p480953787.jpg', 0.4, 2.4, 23.7, 45.2, 28.3, '0.112814,0.148495,-0.995081,0.653837,-0.083751,-0.553509,0.890950,0.092411,-0.376945,-0.182638,0.199945,0.694300,-0.260943,0.367456,0.455497,-0.060458,-0.364474,-0.555051,0.241315,-0.112437,-0.356444,-0.426661,0.222606,-0.013911,-0.004585,0.079075,0.541380,0.005404,0.178431,0.691089,0.218891,-0.130000,-0.164729,0.701521,-0.209667,-0.076441,-0.244062,0.037405,-0.574612,0.421124,0.294703,-0.096031,-0.096324,0.221434,-0.074623,0.061112,0.714586,-0.271990,-0.297433,0.182755,0.255173,-0.087996,0.237972,0.130590,0.181311,0.044820,0.318607,-0.029824,-0.268600,0.207877,-0.046267,0.202755,-0.218908,0.087831,-0.524815,0.026550,-0.921316,0.391309,-0.242124,0.116589,-0.067041,-0.692048,0.140775,0.288638,0.252266,0.140405,-0.363701,-0.086988,-0.486972,-0.129918,0.747895,0.275860,0.206395,0.740164,0.279146,-0.056202,-0.144508,0.033775,-0.662072,-0.006002,0.473458,0.084029,-0.287451,-0.071913,-0.457099,-0.108857,-0.500371,-0.259484,0.129366,-0.334696,0.032874,-0.566557,0.321529,-0.175113,-0.349746,0.398975,0.093182,-0.218165,0.224466,-0.916867,0.436042,0.567960,0.377751,-0.354884,0.407214,0.056502,0.086994,-0.273036,0.115749,0.505974,-0.065548,0.452705,0.111797,0.232459,-0.063355,0.445724,-0.405287,0.331030', '1299965', '3111650', '1297769', '25837175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1440742', '穿越美国', '剧情', '布莉（费莉西蒂·哈弗曼 Felicity Huffman 饰）是个性别倒错者，生就男儿身的他自幼认为自己应该是女人，因此成年后一直努力工作赚钱，一直接受荷尔蒙治疗，分步骤实行变性手术。就在最后一步正式“去势”的前夕，布莉接到来自纽约的意外消息，原来他有个儿子，是当年不小心的结果，如今快要成年，但当街卖身因此被警察拘留。布莉硬着头皮到纽约见到儿子陶比（凯文·齐格斯 Kevin Zegers 饰），隐瞒真实身份带他一路开车回家，一路相处布莉慢慢了解陶比对找到生父的执念，而陶比竟然爱上这位“大嫂”，这段古怪关系将以怎样的方式揭开真相……©豆瓣', '菲丽西提·霍夫曼', '邓肯·塔克', 8.2, 11860, 'tt0407265', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2342279728.jpg', 0.3, 1.3, 16.8, 51.2, 30.4, '0.010085,-0.033731,-0.397468,0.247595,-0.252019,-0.165846,0.039732,-0.093702,-0.475345,-0.643678,-0.024834,0.583982,-0.234763,0.110847,0.309433,0.207507,-0.077450,-0.382560,0.341543,-0.194013,-0.337754,-0.544770,-0.056794,-0.127764,-0.107467,-0.099165,0.477931,-0.105749,0.029249,0.393379,0.362344,0.235466,-0.075292,0.304206,0.067709,0.001943,0.046944,-0.124142,-0.261798,0.138239,0.221249,-0.145115,-0.001874,0.098838,0.149643,0.503201,0.358048,0.050384,-0.336791,-0.010044,0.372491,-0.206598,-0.175932,0.223922,0.378551,-0.105440,0.188410,0.375785,-0.131502,-0.122672,-0.116835,-0.128313,-0.410065,-0.007528,0.042781,0.002461,-0.562367,-0.045302,-0.269165,-0.180726,0.004646,-0.430857,0.019419,0.392571,0.331131,0.338687,-0.130857,0.113321,-0.338543,-0.257383,0.650327,0.038321,-0.320953,0.508242,-0.026765,-0.269913,0.155513,-0.289809,-0.201461,0.181962,-0.214923,0.454843,-0.228071,0.197557,-0.067860,-0.205935,-0.147025,0.186268,0.186944,-0.476490,-0.095031,-0.082704,-0.127810,-0.392735,-0.298554,-0.172021,-0.048952,-0.423198,0.385103,-0.486942,0.398624,0.512363,0.145508,-0.678421,0.482703,0.208460,0.157624,-0.437106,0.094469,0.301119,0.211921,-0.162411,0.124189,0.135662,0.007352,-0.220478,-0.133032,0.217034', '1421278', '1494897', '4145476', '1308035');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1440855', '第一滴血4', '动作', '军政府统治下的缅甸，其西部由于蕴含丰富资源而被军队觊觎多年，那里的儿童经常被军队强征入伍，针对平民的屠杀已经成了部分军人的娱乐……一支教会义工小队为了进入该地区向难民提供人道主义帮助，在泰国找到了隐居的兰博（西尔维斯特•史泰龙 Sylvester Stallone 饰），希望熟悉河道的后者提供帮助。兰博认为时局没有改变的可能，拒绝带路，但终被义工莎拉（Julie Benz 饰）的诚意打动，将他们送达。岂料这支义工小队在村庄中遭到军队的袭击，生还者全部被掳走。教会获悉义工们身陷险境，组织雇佣兵营救，并再次委托兰博带路，这一次，兰博的态度发生了转变，他率领雇佣兵们潜入缅甸军营，又一次化身热血战士。©豆瓣', '西尔维斯特·史泰龙', '西尔维斯特·史泰龙', 7.5, 48095, 'tt0462499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456972157.jpg', 0.7, 3.7, 33.5, 43.3, 18.8, '0.424352,0.094324,-0.482869,0.596025,-0.076715,0.090048,0.399963,-0.232264,-0.430594,-0.242125,0.321654,0.487099,0.433607,-0.214894,0.362579,-0.302758,-0.078951,-0.496854,-0.309594,-0.144748,-0.300300,-0.396602,-0.375443,-0.492824,-0.148550,-0.558354,0.709227,0.235259,-0.264090,0.591137,0.199938,0.602377,-0.189779,0.268757,0.229101,-0.136972,0.233442,-0.431339,-0.309801,0.404602,-0.512120,-0.219130,0.015888,0.220145,0.212623,0.361360,0.759531,-0.194708,-0.139190,-0.282548,0.175171,-0.352633,0.293798,0.060596,0.550940,0.243159,0.051512,0.138881,0.032645,0.144026,-0.148884,-0.104000,-0.840170,-0.171733,0.141834,0.046248,-0.812057,0.185412,0.072028,0.084441,-0.073473,-0.257173,0.048943,0.747819,0.294609,0.226917,-0.006621,0.054349,-0.552070,0.187407,0.903671,-0.490651,-0.257593,-0.324527,-0.332526,-0.320228,0.400664,-0.309263,-0.156779,0.106646,0.218360,-0.145709,0.092129,0.187363,-0.672758,0.087442,-0.457934,-0.575482,0.031822,-0.297348,-0.031384,-0.864673,0.038240,0.220986,-0.011725,0.382302,0.140219,0.049386,0.693881,-0.853750,0.206527,0.765360,0.524667,-0.846444,0.329756,-0.008695,0.073827,-0.160258,-0.033597,0.376195,0.415126,0.405348,0.181870,-0.129918,-0.200105,-0.496290,-0.168608,-0.083039', '2369613', '1292829', '1307762', '1300371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1440958', '自古英雄出少年', '剧情', '年仅十岁的富绅小少爷“大丈夫”（郝勇 饰）生性顽皮，不服管教。为使其收心敛性，父母替他娶了一个二十多岁的媳妇（张小燕 饰）。媳妇武艺高强，管教甚严，这可苦坏了散漫惯的大丈夫，遂找准机会，逃离家门。时逢清朝末年，国家动荡不安，朝廷腐败，烽烟四起。天地会以“反清复明”为宗旨，带领起义民众反抗清朝的高压统治。后因内奸告密，总舵遭到突袭，兄弟死伤无数。总舵主之子在黄婆婆的护送下藏匿江边小城。大丈夫偶然机会救下黄婆婆，从此立志加入天地会，永不回家。谁想朝廷派出大内高手，一路追杀天地会遗孤，黄婆婆更被高手所害。失去庇护的孩子们手足无措，命运多舛……©豆瓣', '郝勇', '牟敦芾', 7.6, 4988, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526124116.jpg', 0.9, 3.4, 31.8, 43.4, 20.6, '-0.354838,-0.048760,-0.285641,0.380623,-0.216641,-0.078841,-0.178812,0.454527,-0.626632,-0.280285,0.094653,0.286812,0.328812,-0.053086,0.123004,-0.388579,0.059638,-0.317226,-0.156387,0.031986,-0.035733,0.083621,0.122958,-0.232043,-0.331133,-0.155833,0.441742,0.289099,-0.166704,0.250528,0.449274,0.123674,0.020571,0.073008,-0.219374,-0.013224,-0.130332,-0.267900,-0.263921,-0.089050,-0.422316,-0.382113,-0.081861,-0.206663,0.029357,0.133013,0.299712,-0.219213,0.103283,-0.883763,0.247080,-0.079649,-0.101628,0.153239,0.592270,-0.044666,0.059794,0.309813,0.134351,-0.141162,-0.038008,-0.105112,-0.214581,-0.031043,0.546434,-0.331306,-0.622825,-0.023092,0.094373,-0.042504,-0.148854,-0.118259,-0.015493,0.595629,0.003746,-0.023711,-0.002470,0.282444,-0.509264,0.325495,0.570716,-0.339970,0.097425,-0.472264,0.235279,-0.017597,0.738910,-0.696750,-0.592939,-0.102820,0.180428,-0.442511,0.023133,0.369764,0.069859,-0.247599,-0.402934,0.291911,0.149050,-0.225798,0.094575,-0.083410,0.001202,0.162192,-0.110488,0.239071,0.042960,0.092030,0.603333,-0.592073,0.110260,0.256765,0.328798,-1.045057,0.349189,0.250467,0.296864,-0.231608,-0.033787,0.217726,0.426718,0.219037,-0.037863,-0.212713,-0.396079,-0.274281,0.330783,-0.257938', '1302874', '1421278', '1302110', '1305915');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441017', '冬春的日子', '剧情', '20世纪90年代初，中国社会正经历着一场前所未有的巨大变革。人们的思想发生转变，商品社会的气息扑面而来。这场改革大潮，似乎正席卷着社会上下每一个角落。蜗居在美术学院的青年教师夫妇冬（刘小东 饰）和春（喻红 饰）多年来过着枯燥、单调、乏味的生活。这两个高中时代就交往的恋人，早已被程式化的生活磨去激情。然而，随着改革大潮的到来，他们如死水般的心也开始活泛起来。郁郁不得志的冬一心将画作卖到海外，赚取美金；春则和远在美国的前男友保持联系，时刻准备抛弃当下的一切，远赴异国他乡开辟一片新的天地。死寂的生活令人绝望，他们的心飞向各自的彼岸……本片荣获1994年希腊塞萨洛尼基电影节金亚历山大奖。©豆瓣', '刘小东', '王小帅', 7.4, 7177, 'tt0106750', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230693578.jpg', 0.9, 3.9, 34.6, 44.7, 15.9, '0.099770,0.142990,-0.944137,0.559025,0.243644,-0.199463,0.621310,0.165919,-0.380004,-0.191942,-0.152201,0.510368,-0.304482,0.315472,0.380199,-0.165978,-0.155923,-0.797968,-0.463246,-0.050577,-0.133500,-0.124684,-0.210409,-0.008897,-0.193851,-0.168406,0.691202,0.267337,-0.118298,0.507905,0.100802,0.152872,-0.052824,0.400015,-0.257832,-0.110196,-0.040082,0.368708,-0.608304,-0.212990,-0.036196,-0.133444,-0.595859,0.043940,0.089081,0.107175,0.701221,-0.157759,-0.125994,-0.009215,0.641853,-0.223450,-0.251838,-0.021574,0.260528,0.334244,-0.002170,0.194605,-0.092388,0.206192,-0.096633,-0.320836,-0.404818,0.030216,0.022924,0.170982,-0.424812,0.541318,0.347257,-0.031115,-0.093508,-0.241394,0.139795,0.317339,0.189333,0.756168,-0.161409,-0.017292,-0.443375,0.508226,0.984397,0.202472,-0.691577,0.320905,-0.370735,-0.201797,-0.175495,-0.043131,-0.543551,-0.471802,0.328052,-0.150668,-0.175853,0.530189,-0.859716,0.388711,-0.014687,-0.425884,0.206794,-0.148926,-0.241507,-0.635033,-0.256565,-0.505409,-0.267195,0.185108,0.071709,-0.303826,0.714959,-0.451095,0.315455,0.672547,0.167352,-0.153835,0.441467,-0.105536,0.064069,-0.086901,-0.094483,0.350128,-0.427325,0.430089,0.025425,0.227667,-0.341159,0.218441,-0.276481,0.685269', '27040921', '34461680', '3626364', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441054', '古畑任三郎 VS SMAP', '剧情', '某年，日本超人气偶像组合SMAP的演唱会召开在即，但是5名成员木村拓哉、香取慎吾、中居正广、草彅刚、稻垣吾郎却忧心忡忡，若有所思。在此之前，工作人员之一的富樫明男（宇梶刚士 饰）狠抓阿刚的痛脚，其行径足以导致SMAP解散，他狮子大张口勒索阿刚1000万日元。协商无效的情况下，5个好兄弟精心设计了一套详细周密的谋杀方案。这边厢，SMAP的演唱会准时召开，那边厢富樫吊死密室。突发命案，古畑任三郎（田村正和 饰）和今泉（西村雅彦 饰）隆重登场。虽然表面上富樫死于自杀，但现场种种能够蛛丝马迹则令古畑疑窦丛生，面对团结一致的SMAP，他该如何各个击破……本片为《古畑任三郎》系列第三部SP。©豆瓣', '田村正和', '铃木雅之', 8.7, 8588, 'tt0331249', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2388615673.jpg', 0.2, 0.8, 12.4, 37.2, 49.4, '-0.099513,-0.019473,-0.305781,0.112238,0.236663,0.124604,0.154998,0.256431,-0.071125,-0.465399,0.375155,0.411218,-0.406489,0.084995,0.191836,0.010000,-0.399735,-0.331927,0.116752,-0.051452,-0.011637,-0.182880,0.113119,-0.111427,0.003236,0.241571,0.713006,0.192056,-0.170523,0.289649,0.716416,0.568748,-0.140810,-0.040214,0.255234,0.133743,0.180987,-0.089591,-0.250732,-0.041567,-0.263735,-0.274804,-0.462794,0.227411,0.305040,0.446155,0.587352,-0.027149,-0.416778,-0.106182,0.434379,-0.226984,-0.153931,0.180489,0.453868,0.009931,0.264890,0.251267,-0.085426,-0.055006,0.009410,0.019929,-0.674704,-0.041246,0.257238,0.081557,-0.151478,0.252306,-0.110517,0.035974,-0.015128,-0.142132,-0.091293,0.230042,0.499561,0.045197,-0.200077,0.170889,-0.077194,0.160716,0.524053,0.122112,0.118823,0.167605,0.167258,-0.446405,-0.195225,-0.255214,-0.219316,0.027465,0.052906,-0.185573,0.192345,-0.021550,-0.137952,-0.282000,-0.090788,0.100510,-0.000715,-0.129058,-0.006679,-0.618050,0.088863,-0.232474,-0.340463,0.208167,0.332238,-0.122501,0.646551,-0.412092,-0.221607,0.167769,0.066878,-0.367133,-0.049131,0.239775,-0.015772,-0.292894,-0.208354,-0.293254,0.306312,0.013262,0.297122,0.429838,0.090912,-0.227867,-0.248407,0.026556', '2369613', '1322847', '26759820', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441176', '阿婴', '剧情', '阿婴是闾门县令的独生女，自幼目睹母亲因通奸之罪被施“木马”酷刑惨死的情形，心中留下阴影。成年后，她被父许配给武举封青云。封青云是个虚伪的道学家，自视甚高，对美色不屑一顾，面对美艳的阿婴不屑正视，却私下暗自偷窥。二人夫妇不像夫妇，心存芥蒂。返娘家途中，二人于树下歇息，就在此时，恶名远播的采花大盗熊艳（单立文饰）正慢慢靠近二人。知县等不到二人，于是下令四处寻找。衙门捕头（高捷饰）一直暗恋阿婴，深感焦急，寻到大树旁却见武举尸横当场。兜售水粉的小货郎（黄耀明饰）鬼鬼祟祟，捕头当即盘问，货郎道出所见。却不知，其中另有文章，而一股恐怖的阴云，正慢慢地靠近县衙......蔡康永在完成剧本后一直不愿再提起这部电影，可见其对该片恐怖色彩的敬畏。该片以静态的影象风格塑造了一个风声鹤唳的幽冥人间。极其独特。©豆瓣', '王祖贤', '邱刚健', 7.3, 8847, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2577364500.jpg', 1.4, 5, 34.1, 43.4, 16, '0.203577,-0.176176,-0.515044,0.471123,0.180735,-0.153231,0.670606,0.343583,-0.698179,-0.134451,0.419490,0.564095,-0.416368,0.138745,-0.079700,-0.092747,-0.150497,-0.587236,-0.340183,-0.237361,0.043488,-0.314429,-0.105305,-0.003661,-0.188509,-0.111948,0.256049,-0.014148,-0.115966,0.627849,0.243659,0.195494,-0.357824,0.438043,-0.200296,0.023017,-0.139458,-0.028746,-0.251629,-0.092069,0.088664,-0.453988,-0.461013,-0.094796,-0.275391,0.352365,0.531228,-0.171949,-0.272036,-0.159523,0.320977,-0.059883,0.008729,0.173978,0.248916,0.041905,0.159366,-0.022917,-0.226027,0.058901,-0.080465,0.154176,-0.335780,0.263095,0.146155,0.238954,-0.340714,0.207939,-0.020484,-0.152977,-0.010356,-0.479054,-0.009202,-0.304899,-0.045642,0.368794,-0.013295,0.099998,-0.337069,0.187565,0.226233,0.204803,0.006109,0.228542,0.135147,-0.047240,0.333367,-0.201242,-0.336922,-0.132604,0.205665,0.304569,0.121529,-0.029726,-0.300987,-0.138980,-0.369528,0.158471,0.006968,-0.255076,-0.314515,-0.390494,-0.327417,-0.241261,-0.202493,0.054089,0.314851,-0.103894,0.334473,-0.453716,0.299914,0.130961,0.069028,-0.529601,0.364393,0.089766,-0.029007,0.023801,-0.229924,-0.036056,0.097657,0.395955,0.052730,0.198989,-0.069668,-0.237417,-0.345195,0.201873', '1309297', '3111650', '21348112', '1302488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441238', '面纱', '剧情', '电影讲述了20年代一对年轻的英国夫妇来到中国乡村生活的故事，在这美丽却凶险的环境中，他们经历了在其英国家乡舒适生活中绝对无法想象和体验的情感波澜，并领悟到了爱与奉献的真谛。故事以女主角吉蒂开篇，为了逃离20年代伦敦浮华却又空虚的社交圈，也为了防止自己变成一位老姑娘，吉蒂接受了沉默寡言的医生沃特·费恩的求婚。费恩在把吉蒂带到上海后，便迅速地投入到了他的细菌学研究中去。孤独的吉蒂和迷人的已婚男子查理·唐森发生了婚外情，当费恩发现时，他羞恨交加。为了报复，也为了重整自己的生活，费恩决定孤注一掷，带着吉蒂远走霍乱肆虐的偏远城镇。沃特从一尘不染的研究室走向了瘟疫流行的最前线，他慢慢地协助控制了当地的疫情。吉蒂则开始在一家由法国修女住持的修道院兼医院中做义工，并逐渐找回了生活的勇气和意义。沃特和吉蒂终于可以互相敞开心扉，但就在他们日渐亲密的同时，沃特染上了霍乱。沃特的生死决定了他们新近迸发出来的激情能否转化为永恒的爱情……', '爱德华·诺顿', '约翰·卡兰', 8.3, 158327, 'tt0446755', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2562672848.jpg', 0.2, 1, 15.8, 48.9, 34.1, '0.252820,0.145763,-0.653532,0.594791,-0.217686,-0.409634,0.897780,0.137058,-0.388213,-0.031217,0.040268,0.814966,0.003343,0.276661,0.316581,0.108466,-0.419447,-0.740293,-0.031149,-0.112243,-0.175064,-0.288309,-0.180175,-0.326193,-0.034588,-0.390712,0.554246,0.293252,-0.250310,0.268298,0.129670,0.224913,-0.095460,0.528233,-0.208190,-0.052303,0.003112,0.125203,-0.532784,0.169504,0.187982,-0.415824,-0.219099,0.304953,-0.028960,0.306143,0.768245,-0.161510,-0.066222,0.007906,0.357604,-0.144523,-0.115898,0.222913,0.077043,0.027886,0.047794,0.182286,-0.135512,-0.068481,-0.090939,-0.140830,-0.788377,-0.046091,0.112946,0.157386,-0.514520,0.543283,0.018387,-0.244210,0.137956,-0.294297,0.209730,0.291600,0.115073,0.554488,-0.198483,0.004713,-0.395247,0.355589,0.702916,-0.122633,-0.398211,0.520820,-0.481445,-0.465751,-0.003188,-0.093037,-0.450088,-0.333138,0.317105,0.064118,-0.335368,0.375310,-0.707591,-0.010194,-0.305317,-0.390145,0.022582,-0.295221,-0.000464,-0.608615,-0.336048,-0.526333,-0.163200,-0.098063,0.058938,-0.228521,0.659154,-0.789959,0.234626,0.681762,0.250466,-0.556260,0.543451,0.143294,0.255496,-0.135653,-0.091631,0.605141,-0.254455,0.633972,0.145966,0.429491,-0.073490,0.080208,-0.546569,0.674418', '30162520', '3285642', '1309172', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441473', '水中女妖', '悬疑', '“水妖”的传说在西方家喻户晓，据说那是一群住在海、河或森林中的美丽少女。一栋公寓的门卫克里夫兰（保罗·吉亚玛提 Paul Giamatti 饰）在夜里巡逻时，发现在游泳池里有一位少女，他救她出来，得知她名叫斯托丽（布莱丝·达拉斯·霍华德 Bryce Dallas Howard 饰），原来就是传说中的水妖，正在被怪兽追逐。为了帮助斯托丽回到原来的世界，克里夫兰找来许多大厦住户帮助，也慢慢爱上了这个与众不同的女孩，可惜时间紧迫，斯托丽在这个世界耽搁越久，越会惹来怪兽袭击，甚至开始威胁这个世界人们的生命……©豆瓣', '保罗·吉亚玛提', 'M·奈特·沙马兰', 5.6, 5635, 'tt0452637', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p906788470.jpg', 8, 27.5, 44.4, 15, 5.1, '0.139282,0.413555,-0.784149,0.470705,-0.086279,-0.034833,0.864678,-0.149769,-0.343541,-0.439832,0.188693,0.628597,-0.046143,0.258831,0.467331,0.162348,-0.139918,-0.131507,0.027160,-0.485672,-0.557607,-0.256722,-0.349985,-0.212068,0.431548,-0.664873,0.484079,0.296809,-0.138591,0.209255,0.364273,0.541036,-0.244603,0.393210,-0.379943,0.014115,0.407779,-0.024227,0.130043,0.337815,-0.317101,-0.104752,-0.154644,0.070419,-0.063980,-0.093644,0.770430,-0.414446,-0.180712,-0.103579,0.394384,-0.143424,0.006803,0.002570,0.759575,-0.720436,-0.014988,-0.129847,-0.272057,0.081101,-0.031772,-0.075372,-0.647770,0.178323,-0.003335,0.316222,-0.557184,0.127027,0.116767,-0.243045,0.084717,-0.165897,0.222303,0.120223,0.012009,0.245277,-0.108867,-0.132412,-0.719102,0.019912,0.556729,-0.043949,0.003936,0.431610,0.032379,-0.122446,-0.051536,0.132007,-0.450472,-0.191486,0.433161,-0.215770,-0.415694,0.054839,-0.783288,0.062310,-0.393834,-0.410899,0.185795,-0.287062,-0.569395,-0.536669,-0.022573,-0.166214,-0.052402,0.028259,-0.197627,-0.023889,0.719645,-0.768876,0.220775,0.752899,0.156489,-0.359103,0.824286,-0.031247,0.104526,-0.073736,-0.259473,0.558035,0.275529,0.380402,-0.054131,0.394484,-0.297781,-0.312704,-0.508494,0.531805', '3055049', '21619567', '1309101', '1760027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441602', '霍元甲', '剧情', '霍元甲（李连杰 饰）年少时以稚嫩的霍家拳打败向他挑衅的小恶霸后习武信心大增，凭着对武术的悟性及热情，他的武艺根基日益深厚，成为天津赫赫有名的武师，可是其性情也渐变得浮躁傲慢，越来越好勇斗狠。得知徒弟被天津另一高手秦爷重创后，霍元甲不问原由闯入秦爷的寿宴，威逼其当场签生死状 与他比武，虽然最后他取得了胜利，但却因此赔上了他一生最爱的母亲及女儿的性命。大错铸成后，痛不欲生的霍元甲神志昏乱远走他方。后得某偏远村落的村民孙婆婆及其失明孙女月慈（孙俪 饰）的悉心照料，霍元甲复原了精神气，并开始领悟武学的真谛。©豆瓣', '李连杰', '于仁泰', 7, 158658, 'tt0446059', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171661378.jpg', 0.7, 5.5, 47.3, 35, 11.5, '-0.225068,0.180681,-0.577153,0.710623,-0.122243,-0.406932,0.294816,0.224352,-0.610407,-0.242354,0.246930,0.756246,0.044836,0.195209,0.090007,-0.428084,0.163217,-0.577373,-0.063930,-0.133708,-0.101597,-0.385160,-0.233986,0.079275,-0.412616,-0.471894,0.419956,0.286545,-0.451101,0.435255,0.099172,-0.039949,0.235838,0.368664,-0.035508,0.219497,-0.362326,-0.233369,-0.172291,-0.193741,0.215108,-0.263877,-0.078217,0.072930,-0.231831,0.428102,0.595524,0.035044,-0.209301,-0.463905,0.485864,-0.096995,-0.344340,0.174177,0.227160,0.132111,0.102559,0.136702,-0.027096,-0.139457,-0.172366,-0.041325,-0.612270,0.134228,0.228760,-0.175572,-0.445110,0.467027,-0.137123,-0.110054,-0.392257,-0.250465,-0.265045,0.197608,-0.063464,0.212523,-0.279297,-0.031162,-0.370193,0.151067,0.556754,-0.156024,-0.043361,0.208236,-0.064789,-0.656782,0.133936,-0.817531,-0.083184,0.083030,0.370259,0.149829,-0.035050,0.166519,-0.166065,-0.171955,-0.202501,0.229556,-0.250338,-0.286067,-0.027450,-0.240717,-0.136345,-0.456757,-0.271145,-0.170282,0.229755,-0.232698,0.981710,-0.749806,0.055875,0.106344,0.252668,-0.542876,0.401785,-0.085347,0.218937,0.112090,-0.394638,0.500035,-0.033689,0.260219,0.219713,0.199611,-0.204236,-0.062118,-0.164858,0.495076', '27602116', '24284209', '26711487', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441612', '只是朋友', '喜剧', '谁也想不到，现如今风光无限、英俊帅气的一流音乐制作人克里斯·布兰德（瑞恩·雷诺兹 Ryan Reynolds 饰），高中时代竟是个木讷、痴肥还戴着牙套的死胖子。当年他和美丽的洁米（艾美·玛提西奥 Amy Matysio 饰）是亲密无间的好朋友，克里斯始终暗恋洁米，却迟迟不敢说出口。在毕业派对当晚，克里斯通过年册向洁米表白，却得到只愿做朋友的答复。转眼十年，克里斯已经成为风度翩翩的帅气男子。十年前的遭遇让他发奋图强，最终成为魅力十足的女性杀手。在某次去巴黎公干的路上，克里斯因故在家乡新泽西逗留。在此期间遇到了当年的一种好友，其中包括久未某面洁米。分别经年，一切似乎重新开始……©豆瓣', '瑞安·雷诺兹', '罗杰·昆宝', 6, 7196, 'tt0433400', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1579294644.jpg', 3.4, 18.4, 57.2, 15.5, 5.5, '0.158301,0.182134,-0.563366,0.509616,-0.284127,-0.506367,0.545288,-0.013754,-0.354098,-0.396868,-0.016615,0.630191,-0.411108,0.287089,0.229424,0.144863,-0.301256,-0.465802,0.048078,-0.159777,-0.117835,-0.374427,-0.384988,0.099329,0.063751,-0.313025,0.541929,0.012428,0.246133,0.577082,0.325183,0.037041,0.046069,0.298073,-0.270431,0.082605,0.170885,0.168560,-0.268870,0.281531,-0.116910,-0.305941,-0.330557,-0.007593,0.034072,0.364891,0.402752,0.176946,-0.209676,-0.016236,0.339833,0.118392,-0.014376,0.100856,0.261928,-0.215100,0.289388,0.215467,-0.161875,0.006195,0.127324,-0.028404,-0.447639,0.299837,-0.018191,0.184368,-0.422054,0.536078,-0.187792,0.001373,0.202716,-0.404297,-0.048915,0.058885,0.055470,0.184660,0.179621,0.368401,-0.454080,0.414552,0.698004,0.200024,-0.469099,0.247710,-0.003795,-0.188488,-0.021077,-0.203649,-0.546857,0.236407,0.008459,0.115011,-0.054081,0.075775,-0.262541,0.009814,-0.329211,0.177553,0.138668,-0.288745,-0.241122,-0.602194,-0.012102,-0.348870,-0.296140,-0.006032,-0.100731,-0.240482,0.568435,-0.694622,0.292257,0.342723,0.067979,-0.313847,0.580724,0.462608,0.009229,-0.223273,-0.355036,0.491218,0.168872,0.014295,0.039881,0.308791,-0.069944,0.023709,-0.258091,0.517452', '1292720', '35030151', '1292219', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441644', '妖兽都市', '动画', '泷莲三郎（屋良有作 配音）一个普通的上班族，而他有着不为常人所知的另一个角色——“黑暗护卫”（闇ガード），为了维护人界与魔界之间的和平而不断的战斗着。接到上级分配下的任务，与魔界的绝色美女麻纪绘（藤田淑子 配音）一起保护魔导士乔瑟贝‧迈亚多（永井一郎 配音），确保他在即将在东京签订的两界休战条约之前的安全。在机场经过一场恶斗后，总算是接到了迈亚多，而他却是个任性的好色老头。但俩人基于职责所在，将迈亚多护送到饭店。殊不知魔界激进派分子早已经设下埋伏并展开攻击，意图破坏和约的签订。危机中，泷与麻纪绘能否顺利完成任务？而随着局势发展，泷与麻纪绘发现整个事件背后令人惊讶的真相……本片的原始企画仅为35分钟左右的OVA作品，后来却在制作分镜稿时，发展成为87分钟的动画电影。©豆瓣', '屋良有作', '川尻善昭', 7.6, 12099, 'tt0098692', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2511406984.jpg', 0.7, 3.4, 31.8, 45.1, 19, '0.375024,0.204921,-0.583329,0.732123,0.098395,-0.157178,0.488397,0.107709,-0.276463,-0.358409,0.344956,0.621499,-0.085373,-0.102631,0.355117,-0.177333,-0.382853,-0.708850,-0.308301,-0.165268,-0.320359,-0.365641,-0.275564,-0.174036,-0.236821,-0.327378,1.092370,0.292032,-0.190168,0.311949,0.305199,0.324936,-0.541638,0.415269,0.073570,-0.312250,0.212604,-0.089926,-0.424765,0.457161,-0.164240,-0.246532,-0.143329,0.205804,-0.002689,0.554437,0.659096,-0.465361,-0.322230,-0.122361,0.437435,-0.510346,-0.121610,0.040785,0.380655,0.154321,0.341667,0.397409,-0.332199,0.218635,-0.152605,-0.270281,-0.884231,0.043459,0.107991,0.063501,-0.330854,0.449782,0.022809,-0.050310,0.075910,-0.271666,0.147687,0.768632,0.469712,0.366734,-0.302874,0.108812,-0.333736,-0.222029,0.820603,-0.036700,-0.331518,0.223666,0.135085,-0.478573,-0.161394,-0.315627,-0.215660,-0.029509,0.018576,0.189959,0.058257,0.146283,-0.735762,0.136083,-0.273781,-0.100054,0.028978,-0.549929,-0.066141,-0.836011,-0.181218,-0.320891,-0.344401,0.182571,0.398638,-0.178951,0.600896,-0.793493,0.052189,0.548026,0.313299,-0.422529,0.506114,0.244505,0.230833,-0.303342,-0.052122,-0.157419,0.014983,0.454826,0.060119,0.250134,-0.019997,-0.186141,-0.473013,0.365524', '2369613', '3861846', '26759819', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1441801', '局内人', '剧情', '华尔街一间热闹的信托银行，某日突然闯进了4名劫匪，挟持了包括银行员工在内的50名。这伙匪徒是在他们的首领道尔顿（克里夫•欧文 Clive Owen 饰）的远程指挥下行事的。道尔顿心思紧密、狡猾多疑，他让人质都穿上和匪徒一样的服饰，戴上和匪徒一样的面罩，以此来迷惑警方的狙击手和特种部队。警方一时亦无可奈何。奉命到场的探长弗雷泽（丹泽尔•华盛顿 Denzel Washington 饰）试图和道尔顿取得沟通，让他释放人质。然而却被道尔顿玩弄于股掌之中。此时，银行的董事阿瑟也赶到了现场，密切关注案情进展。然而他关心的不是人质安全，却是他的隐秘。随着时间慢慢过去，匪徒除了简单的要求外都没有提出其他要求，基辅感到内有乾坤……©豆瓣', '丹泽尔·华盛顿', '斯派克·李', 7.7, 72246, 'tt0454848', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p528000230.jpg', 0.3, 1.8, 27.1, 53.1, 17.6, '0.554903,-0.103073,-0.765060,0.501983,-0.176123,-0.065523,0.693562,-0.036974,-0.555704,-0.237630,0.237787,0.459706,0.013946,-0.056837,0.119650,-0.142339,-0.420340,-0.846478,-0.458093,-0.214037,-0.107759,-0.699106,-0.353714,-0.361481,-0.025325,-0.244398,0.260053,0.070817,-0.126875,0.563909,0.319905,0.196981,-0.286894,0.538329,0.065140,-0.211387,0.390175,-0.339210,-0.267267,0.185393,-0.081436,-0.181410,0.018668,0.217963,0.144276,0.781679,0.510654,-0.245316,-0.125796,0.159297,0.119386,-0.228053,0.101804,0.127927,0.329400,0.099434,0.077317,0.143487,-0.262793,0.164487,0.001583,0.069907,-0.875445,0.219565,0.174729,0.256541,-0.399182,0.395700,-0.315766,0.082059,-0.042116,-0.414252,0.180814,0.031493,0.208258,0.211495,0.072884,0.016472,-0.427284,-0.006407,0.600422,-0.005380,-0.218145,-0.175101,-0.349683,-0.383955,-0.022602,-0.272035,-0.165735,-0.173300,0.470505,-0.053540,0.107687,0.039517,-0.423771,-0.006011,-0.242990,-0.142567,-0.190069,-0.447318,0.091291,-0.617103,0.119057,-0.311118,-0.287911,0.153897,0.262516,-0.025854,0.573846,-0.692696,-0.034128,0.732828,0.539486,-0.539380,0.573114,0.012899,0.185633,0.022766,-0.287617,-0.276013,0.597983,0.489904,0.178099,0.467252,-0.159382,-0.407607,-0.260851,-0.203331', '1307442', '1947080', '35073886', '1293434');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1442700', '双面北野武', '剧情', '彼得武（北野武 饰）是日本娱乐圈一颗耀眼的明星，他同时身兼主持人、导演、演员等多种身份。生活富裕，风头无两。他终日里乘坐劳斯莱斯，游走于各大秀场。在此期间，彼得武还要和经纪人（大杉涟 饰）探讨下一部戏的计划，始终不得闲暇。所有的人都希望在彼得武的电影里出演角色，他们趋之若鹜，疯狂至极。某天，一个龙套演员（寺岛进 饰）向彼得武推荐一个志愿者，这个染着黄毛、衣着光鲜且表情木讷的家伙竟然和彼得武的容貌一模一样。彼得武甚感好奇，于是接纳了这个名叫北野（北野武 饰）的便利店员。但自此之后，彼得武和北野便仿佛堕入一个混乱的噩梦之中，他们之间的界限渐次模糊……©豆瓣', '北野武', '北野武', 7.3, 6355, 'tt0478044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p894052786.jpg', 1.1, 6.2, 38, 37.9, 16.8, '0.089163,0.095144,-0.501714,0.678807,0.071891,-0.430507,0.556726,0.218297,-0.346325,-0.566932,0.217395,0.462510,-0.446395,0.109501,0.296958,-0.227446,-0.442733,-0.782120,-0.371346,-0.211866,-0.026503,-0.204765,-0.101425,-0.255656,-0.341556,-0.011932,0.666308,0.206309,-0.087557,0.502347,0.576520,0.136884,-0.181155,0.148195,0.119486,-0.007595,0.196809,-0.115834,-0.204294,0.088780,-0.096879,-0.208070,-0.107260,0.297994,0.027639,0.348562,0.593800,-0.256954,0.001863,0.098462,0.223566,-0.057394,-0.280144,0.177793,0.139619,0.070832,0.346048,-0.142839,-0.011006,0.138888,-0.144874,0.011654,-0.561386,0.160629,0.110847,0.408388,-0.185963,0.225144,-0.137737,-0.101372,0.009853,-0.169688,0.023930,-0.178394,0.258361,0.377864,0.017866,0.301033,-0.218199,0.374666,0.424288,0.496200,-0.213924,0.292172,-0.152797,-0.438567,-0.258497,-0.158922,-0.502071,-0.016854,0.304272,-0.306983,0.216074,0.229662,-0.474608,0.153235,-0.057668,0.125247,-0.128643,-0.000044,0.113316,-0.813587,0.089012,-0.396554,-0.120494,-0.035722,0.054920,-0.173983,0.804506,-0.584291,0.128605,0.043370,0.148876,-0.319092,0.691511,0.019668,0.101121,-0.069346,-0.194816,-0.048952,0.278734,0.088045,-0.079892,0.474097,-0.258692,-0.335017,-0.231172,0.167146', '3811356', '1322847', '25863940', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1443650', '天使A', '喜剧', '巴黎，一个小混混安德烈（加梅勒•杜布兹 Jamel Debbouze 饰）因走投无路准备跳河时，他赫然发现了一位金发美女也正在跳河。安德烈奋不顾身的救起了这位同病相怜的美女――安吉尔（丽•拉丝姆森 Rie Rasmussen饰）。安德烈在高挑美丽的安吉尔面前感到自惭形秽，但安吉尔认定是安德烈救了她，所以她属于安德烈，她要帮安德烈开心起来。当追讨欠债的黑老大捉走了安德烈，安吉尔帮助他脱离险境；当安德烈无钱还债时，安吉尔卖身替安德烈还了钱。安德烈看到安吉尔为自己做的事，感到又羞又气，他彻底爱上了安吉尔。最终，在安吉尔的鼓励下，安德烈对她说出了“我爱你”，其实，也对他自己。最终，安吉尔向安德烈坦白了自己是来帮助他的天使，是时候要走了……©豆瓣', '贾梅尔·杜布兹', '吕克·贝松', 7.7, 19460, 'tt0473753', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1755862685.jpg', 0.5, 3.4, 28.6, 44.9, 22.5, '0.158277,0.122446,-0.535243,0.329157,-0.395057,-0.808195,0.698311,0.071796,-0.163970,-0.051331,0.218437,0.857474,-0.112660,0.365952,0.310294,0.516460,-0.369403,-0.617724,0.222805,-0.068599,-0.381111,-0.353723,-0.098754,-0.269858,-0.106478,-0.244775,0.205519,-0.190230,-0.052350,0.328783,0.660762,0.207593,0.449019,0.517425,-0.073407,0.177835,0.126919,-0.120912,0.135703,0.153314,0.225609,-0.401934,-0.340336,0.487582,-0.095600,0.553002,0.322918,-0.013794,0.109566,-0.118847,0.229665,-0.353276,0.286446,0.281068,-0.103455,-0.269252,-0.247526,-0.191116,-0.257129,-0.151312,0.371205,0.128256,-0.670400,0.161180,-0.250029,0.110028,-0.753913,0.270815,-0.252086,0.159233,0.467303,-0.301039,-0.095121,0.125665,0.055136,0.207174,-0.230668,-0.043493,-0.485446,0.154875,0.584751,0.134269,0.063157,0.398528,-0.382347,-0.340953,0.183354,0.141292,-0.451756,-0.139911,0.376430,0.057676,-0.193836,-0.066862,-0.253855,-0.401125,-0.460640,-0.088424,-0.345543,-0.416870,-0.054614,-0.124140,-0.271700,-0.407024,-0.404727,-0.104128,-0.150110,-0.241776,0.562051,-0.500579,0.057904,0.836925,0.320992,-0.621268,0.685106,0.327854,-0.087244,-0.041252,-0.065648,0.265605,-0.068636,0.124016,0.468463,0.186113,0.257412,-0.139043,-0.288782,0.557020', '1292584', '30167633', '1299799', '5959696');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1444595', '雀圣2：自摸天后', '喜剧', '细芬（应采儿 饰）表面上是一个普通的家庭主妇，但事实上她是麻雀高手过三洞的徒弟，精通麻雀。她爱麻雀但更爱丈夫子雄（尹子维 饰），而丈夫则不喜欢她沉醉麻雀。子雄是个不务正业的小混混，得到赌坛老大鬼哥的赏识。同时，鬼哥的妹妹也看上了子雄，千方百计要从细芬手中夺得子雄，细芬十分担忧。细芬的师姐十三飞（元秋 饰）和师妹初恋（李笼怡 饰）出招教授。但子雄还是受不住诱惑，决定跟细芬离婚。细芬在麻雀台上与波波对阵时输掉了丈夫。细芬伤心自杀，经师父及师姐师妹的鼓励，决定把失去的自信找回来，誓要在雀神大赛上赢回波波……©豆瓣', '应采儿', '王晶', 6, 19125, 'tt0489501', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2192296174.jpg', 3.8, 18.1, 56.9, 16.1, 5.1, '0.183894,-0.081392,-0.325882,0.576732,-0.375959,-0.260096,0.476933,0.080190,-0.231225,0.184965,0.120599,0.633112,0.013928,0.223186,-0.259513,0.088425,0.107067,-0.557675,-0.060536,-0.007844,0.269095,-0.435878,0.126754,0.006721,-0.216516,-0.306415,0.540720,-0.089176,-0.047569,0.671526,0.521701,0.114295,0.123798,0.227772,-0.101367,0.021801,-0.309716,0.200560,-0.218796,0.161149,0.205636,-0.114311,0.030839,0.345610,0.158169,0.140375,0.501034,-0.230932,-0.029446,-0.373153,0.214919,-0.083440,0.081424,0.326152,0.348643,0.004015,0.279485,0.047964,0.041173,0.068922,0.020273,-0.005670,-0.383146,0.064639,0.523665,-0.026885,-0.653751,0.433401,-0.364808,0.067740,-0.037658,-0.208594,0.049007,0.014179,-0.023470,0.270972,-0.270758,0.186257,-0.369993,0.126467,0.604737,0.228434,0.442491,0.136636,0.217279,-0.431223,0.295515,-0.609924,-0.481579,0.163126,0.367765,-0.110983,-0.111108,-0.170827,-0.366720,0.064908,-0.072256,0.058140,-0.192330,-0.539848,0.063823,0.018253,-0.052774,-0.443780,-0.318845,-0.133124,0.099284,-0.590299,0.680292,-0.965933,0.249212,0.300562,0.252872,-0.224279,0.706272,0.064122,-0.266466,-0.368095,-0.077271,-0.155264,-0.208011,-0.021203,0.165669,0.236951,0.068503,-0.278419,-0.252575,0.249799', '35030151', '3445516', '1292219', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1448703', '人皮灯笼', '剧情', '1963年，一伙黑帮分子在老大的指使下将一对情人残忍杀害，男子被埋在“十世受苦，不得超生”的阴穴处；而女子被扒皮，皮罩在灯笼上，永世不得超生。1993年，蛊惑仔阿辉（梁家辉 饰）终日倒霉透顶，而且身边连连发生奇怪灵异世间。阿辉在古董摊买下一古董表，却被一股力量莫名牵引到一栋废宅里，半梦半醒间见自己与一个叫小芙蓉的艺旦（邱淑贞 饰）亲热的场面。辉在医院被一鬼魂提醒只有四婆能够解救自己，于是他前往找四婆。四婆为他问米，他从盆中之水渐渐看到了自己的前世悲惨遭遇……©豆瓣', '梁家辉', '刘伟强', 6.8, 12393, 'tt0108640', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2332513174.jpg', 0.9, 7.5, 52.1, 29.9, 9.6, '0.212032,0.084682,-0.731282,0.278769,-0.035259,-0.112533,1.015143,0.165999,-0.592303,0.135026,0.372538,0.764271,-0.517729,0.209088,0.193419,0.085219,0.199934,-0.745419,-0.240270,-0.138936,-0.446416,-0.143487,-0.206735,0.033810,-0.166792,-0.406033,0.215901,0.060624,0.104500,0.248164,0.273284,0.346069,-0.280184,0.315992,-0.386315,-0.011549,-0.006997,-0.082572,0.079347,0.161523,0.055796,-0.585327,-0.164862,-0.132548,-0.378219,0.165731,0.814419,-0.449914,-0.251881,-0.195211,0.235362,-0.189600,-0.384158,0.189576,0.072698,-0.116286,0.044795,0.226480,-0.598532,0.051786,0.493109,-0.023520,-0.345748,0.024537,-0.106828,0.213280,-0.630627,0.222336,0.033655,0.214512,0.087535,-0.511040,0.356786,-0.094903,0.096803,0.543278,-0.308898,-0.149019,-0.553743,0.370199,0.741833,-0.046517,0.074144,0.361775,-0.098061,-0.197004,-0.153095,-0.101818,-0.601163,-0.160003,0.464896,-0.127954,-0.366298,0.050756,-0.529485,-0.163590,-0.159192,0.025055,-0.219575,-0.240960,-0.317390,0.036447,-0.392745,-0.018878,-0.118100,0.378091,0.224076,-0.098193,0.496243,-0.529876,0.284921,0.576515,0.186839,-0.271665,0.710046,-0.030993,-0.007987,0.081255,-0.136874,0.211409,0.379459,0.381295,0.435780,0.467361,-0.329435,0.008021,-0.244603,0.119742', '21619567', '1292217', '1428054', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1448751', '周恩来', '剧情', '红卫兵在全国掀起的极左运动令时任国务院总理的周恩来（王铁成 饰）忧心忡忡，周恩来在国家危局中挺身而出，维护贺龙、陈毅等老同志、老战友。为了保证国家建设周恩来力促鞍钢恢复生产。1966年邢台地震，他赶赴一线督促重建。七十年代中美开始了多个层面的接触，周恩来会见基辛格，在接见美乒代表队时笑谈嬉皮士，促进了两国关系的正常发展。1971年，周恩来着力粉碎了林彪团伙颠覆国家的阴谋。长期的高强度工作，令周恩来身体每况愈下，体内查出了癌细胞。周恩来带病回到老区延安探访，当地民众贫穷的生活令他无法释怀，指派北京专家帮助延安脱贫。四人帮的活动日益猖獗，周恩来力主邓小平、叶剑英回到重要岗位，与四人帮继续周旋斗争……©豆瓣', '王铁成', '丁荫楠', 8.6, 5694, 'tt0105895', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2457045114.jpg', 1, 1.3, 12.5, 35.2, 50, '-0.055978,0.055844,-0.631141,0.128894,0.100626,-0.079784,0.010744,0.424704,-0.787021,-0.092299,0.259937,0.416019,-0.096120,0.019724,0.175233,-0.359695,-0.389892,-0.758198,-0.025841,0.250848,-0.102950,-0.529257,-0.194967,-0.430854,-0.445998,-0.242611,0.535321,0.468909,-0.175766,0.313977,-0.107325,0.140308,0.091243,0.426268,0.066523,-0.467810,0.202188,-0.174897,-0.685924,0.060466,0.160880,-0.347857,-0.207978,-0.006583,0.198542,0.150048,0.407017,-0.138312,-0.094344,-0.403579,0.361186,-0.290235,-0.156319,0.096058,0.551415,0.557859,-0.081384,0.537466,-0.332684,-0.057910,-0.222420,-0.278362,-0.033781,-0.133029,0.061535,0.320455,-0.488282,0.619136,-0.061677,0.435139,-0.101894,-0.281565,0.189613,1.104721,-0.068014,0.666594,-0.123762,0.345460,0.023082,0.620995,0.633530,-0.113011,-0.620441,-0.408728,-0.474868,-0.060219,0.303725,-0.446131,0.239631,-0.358620,-0.189471,-0.128345,-0.066564,0.489149,-0.502044,-0.006055,-0.330278,-0.268074,0.119211,0.093253,0.041729,-0.773416,-0.369077,-0.085000,0.136121,-0.149544,0.031070,-0.299270,0.852955,-0.715759,-0.095946,0.401103,0.331463,-0.689244,0.462180,0.228976,0.159029,-0.556571,0.095582,0.339027,-0.266817,0.509689,-0.071615,0.168708,-0.448338,-0.239596,0.090068,-0.035457', '1424552', '1316511', '30481973', '3562446');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1448755', '钢之炼金术师：香巴拉的征服者', '剧情', '分隔在两个世界的爱力克兄弟二人，使用各自的手段尝试着兄弟再会。哥哥爱德华穿过“门”来到真实世界。公元1923年的德国慕尼黑，一场世界大战即将到来。无法在这个世界使用炼金术的爱德华，与长相酷似弟弟的青年爱尔凡斯一起研究火箭的科技，希望借助火箭回到原来的世界。另一边的炼金术世界，弟弟阿尔冯斯修行炼金术，打扮宛若曾经的爱德华，与国家炼金术士们一起寻找找回哥哥的方法。而暗地中，慕尼黑的一个神秘组织开始了寻找理想国“香巴拉”的仪式，连接炼金术世界与现实世界的“门”被打开了。兄弟二人的命运与两个世界的危机交织在一起，爱力克兄弟要面对前所未有的挑战。©豆瓣', '朴璐美', '水岛精二', 8.2, 20386, 'tt0485323', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2634832302.jpg', 0.6, 1.6, 18.3, 45.4, 34, '0.081425,0.275113,-0.517163,0.748441,-0.297595,-0.354631,0.480052,0.044784,-0.448900,-0.226818,0.024793,0.896414,0.031222,0.262164,0.478084,-0.222942,-0.070506,-0.840418,-0.141759,-0.247680,-0.501335,-0.419184,-0.279324,-0.376952,-0.114996,-0.748378,1.034117,0.089617,-0.131622,0.162884,0.015538,0.248996,-0.566313,0.200513,-0.325276,-0.425774,0.259838,0.254739,-1.015527,0.345106,-0.210686,0.371880,-0.091180,0.014460,-0.379358,-0.319478,0.668535,-0.533595,0.226386,-0.501626,0.156893,-0.060444,-0.275241,0.013358,0.331295,0.091559,0.128550,0.298904,0.232728,-0.063224,-0.007024,-0.335656,-0.670141,-0.085883,0.338391,-0.103883,-0.561423,0.230506,-0.144553,-0.216407,0.035566,-0.178654,0.439304,0.633161,0.729063,0.674925,-0.303638,-0.119551,-0.331820,-0.205973,0.477602,-0.228055,-0.318830,0.392362,-0.176347,-0.066271,-0.287517,-0.177887,-0.613866,-0.019195,0.287756,-0.034803,-0.266505,0.529155,-1.136351,0.095140,-0.188560,-0.216340,0.411587,-0.500257,0.016255,-0.858665,-0.220864,-0.286466,-0.035714,0.156284,0.106047,-0.163881,0.947070,-0.911237,0.235226,0.405885,0.383880,-0.264966,0.879209,0.118888,0.105179,-0.804707,0.024092,0.368242,-0.084981,0.357801,-0.329818,0.528372,0.008802,0.337343,-0.743035,0.768110', '26290398', '1870681', '1292206', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1448758', '半斤八两', '喜剧', '万能私家侦探社是一家连同社长黄若思（许冠文）在内只有三名工作人员的小侦探社，由于生意不咸不淡，加上黄若思为人小气刻薄，员工河豚（许冠英）和积琪（赵雅芝），尤其前者没少遭罪。原在汽水厂上班的李国杰（许冠杰）因工作偷懒被老板解雇，一身好功夫的他来到万能求职，黄若思起初不肯雇用，随后见他的确有两把刷子，应了下来，薪水自然苛刻。李国杰没来之前，黄若思与河豚搭档侦探的，无非一些风流、偷窃、欺诈事务，这些案件不是每一都能侦破，而侦破的过程常常充满尴尬，远称不上完美，但其时香港社会的百态却一览无遗。他来之后，三人的合作亦是如此。更要命的，是他们常被警探（吴耀汉）误视作不法分子。几件不大不小的案子，尤其八十岁老翁的娇妻（卢慧芝）在外与人（吴耀汉）偷情一案办过，李国杰显现出比黄若思更强的工作能力，更得客户青睐。某日，黄若思与李国杰受委托来到某家先前被劫匪威胁、现有劫匪出入的戏院，捕捉劫匪的过程中，黄若思被匪首（石坚）的几声枪响吓破胆且负伤，李国杰却凭机智将劫匪制服并收获意外好处，两人身份一时对调。', '许冠文', '许冠文', 8.3, 24427, 'tt0074179', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1606347997.jpg', 0.2, 1, 17.2, 48.9, 32.7, '0.260846,-0.251156,-0.469951,0.256349,-0.220064,-0.213879,0.669984,0.228328,-0.649373,-0.440948,0.070729,0.519862,-0.046546,-0.074665,0.186084,-0.404970,-0.046592,-0.345123,-0.100762,-0.124112,0.013175,-0.485588,-0.049758,-0.210022,-0.362144,-0.219027,0.246206,0.067151,-0.294436,0.348222,0.225583,0.088008,-0.136692,0.426760,-0.245952,-0.073463,0.159140,0.096039,-0.243246,0.120251,0.100474,-0.162125,-0.108013,-0.020013,0.240066,0.431672,0.364865,0.090083,-0.571684,-0.111384,0.272123,-0.140106,0.047716,-0.006138,0.378898,0.028968,0.477023,0.207606,-0.169978,0.112304,0.101647,0.023241,-0.692990,0.182315,0.295609,-0.044301,-0.309263,0.322349,-0.073851,0.056670,-0.272666,-0.255620,0.147957,0.090952,0.175268,0.189001,0.125693,0.231778,-0.546806,0.255829,0.535955,0.123411,-0.087412,0.270123,-0.117670,-0.439894,0.087009,-0.421684,-0.129447,0.224403,0.232418,-0.043909,-0.088856,0.137562,-0.375070,-0.018012,-0.106472,0.053278,-0.197400,-0.260621,-0.097977,-0.662888,0.060227,-0.399126,-0.272996,0.209801,0.437215,-0.254672,0.449681,-0.678694,-0.125631,0.429222,0.200720,-0.501798,0.431890,0.047814,0.234215,-0.186133,-0.462949,-0.232455,0.324485,0.244888,0.159494,0.118645,