INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1449328', '机动警察剧场版2', '剧情', '2002年冬天，横浜大桥突然被战斗机炸毁，媒体虽然报导此为自卫队战机所为，但实际上这架战机却并不存在。民众广泛对自卫队产生了不信任感。特车二课第二小队的后藤（大林隆介 配音）队长察觉此事与在99年的那场事件中失踪的自卫队队员柘植有关——1999年，日本陆上自卫队的机器人 小队在一次联合国维和行动中遭到全歼。而柘植是特车二课第一小队队长南云（榊原良子 配音）原来的恋人。民众的不信任感达到了顶峰，处于戒严状态的东京面临着大骚乱，人们被即将爆发战争的危机笼罩着。在自卫队王牌队员荒川的帮助下，后藤（大林隆介 配音）和南云追查到了柘植的下落。后藤招集起泉（富永美伊奈 配音）、篠原（古川登志夫 配音）等特车二课原来的成员们，启动PATLABOR机器人进攻柘植的根据地……本片是押井守导演推出了《机动警察PATLABOR》的第二部剧场版。©豆瓣', '富永美伊奈', '押井守', 8.9, 6533, 'tt0124770', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1137696692.jpg', 0.4, 0.8, 9.5, 31.1, 58.2, '0.116279,-0.296573,-0.647797,0.497989,0.275294,0.108566,0.459982,0.014320,-0.542434,-0.368739,0.564311,0.414505,-0.163027,-0.087598,0.319295,-0.186367,-0.294843,-0.714612,-0.343015,0.037637,-0.136976,-0.408961,-0.142074,-0.198047,0.030019,-0.354855,1.036812,0.325310,-0.384353,0.379508,-0.000907,0.394109,-0.127722,0.436734,0.399655,0.162326,0.434479,-0.392804,-0.163941,0.166301,-0.453795,-0.331778,-0.086919,0.116566,0.184740,0.449018,0.848040,-0.344327,-0.115540,-0.163884,0.033520,-0.521469,-0.162853,0.010712,0.885592,0.113414,-0.167863,0.200224,-0.015591,0.186045,-0.329013,0.013986,-0.585481,-0.043289,-0.084749,0.118506,-0.262540,0.317920,-0.474096,0.160085,0.255087,-0.002920,0.153994,0.476002,0.231194,0.209959,-0.318804,0.299418,-0.322510,0.091334,0.838386,-0.211296,-0.279338,0.039625,-0.025461,-0.481444,-0.422644,-0.360180,-0.135696,-0.038609,0.014738,-0.058361,0.221581,0.317509,-0.582463,0.010753,-0.055403,-0.595368,-0.049251,-0.128710,-0.049063,-0.869645,0.060437,-0.388877,-0.133919,0.406552,0.307671,-0.102650,0.830803,-0.977738,-0.005518,0.663470,0.215902,-0.208821,0.225466,0.216982,-0.079318,-0.316237,-0.072975,-0.171572,-0.058987,0.752474,0.251462,0.136670,-0.161763,-0.542420,-0.190260,-0.190050', '2369613', '1826173', '3266509', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1449711', '世上最快的印第安摩托', '剧情', '电影改编自世界著名摩托车手伯特·孟若的生平，真实而又生动的再现了一代传奇车手跌宕起伏的一生。故事开始于1899年，孟若（安东尼·霍普金斯 Anthony Hopkins 饰）降生到了这个世界上，从小体弱多病的他甚至被医生下达过“死亡通知书”，但幸运的是，孟若还是顺利的长大了。1915年，孟若有了自己的第一辆摩托车，从此开启了与风竞速的生涯，直到七十二岁那一年，孟若依然没有放弃自己曾经的梦想。他改装了二十年代购入的印第安牌侦查摩托车，从新西兰骑往美国。一路上，孟若结识了易装癖者蒂娜（克里斯·威廉斯 Chris Williams 饰）、寡妇艾达（戴安·拉德 Diane Ladd 饰）、销售员佛兰多（保罗·罗德里奇斯 Paul Rodriguez 饰）等一干有趣的朋友们，在他们的帮助和鼓励下最终创下了新的世界纪录。©豆瓣', '安东尼·霍普金斯', '罗杰·唐纳森', 8.9, 15511, 'tt0412080', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2480744820.jpg', 0.1, 0.4, 7.1, 37, 55.4, '0.253341,0.212678,-0.597893,0.621502,-0.055447,-0.414170,0.535851,-0.110157,-0.601732,-0.197257,0.302762,0.814015,-0.267863,0.107927,0.356889,0.083875,-0.311665,-0.659260,0.056928,-0.199894,-0.426975,-0.363104,-0.336718,-0.149282,-0.065020,-0.356037,0.558798,0.036255,0.088841,0.559625,0.230746,0.250343,0.183286,0.284163,-0.391927,0.320593,0.121297,0.123132,-0.138030,0.199466,-0.150754,-0.325250,-0.188682,-0.078685,0.031247,0.306950,0.596773,-0.238035,0.008767,-0.009619,0.337407,-0.188811,-0.097870,-0.113018,0.283272,0.119148,-0.013591,0.280990,-0.064161,-0.006456,-0.070186,-0.080684,-0.600100,-0.103557,-0.088239,-0.008673,-0.688900,0.450441,-0.426947,-0.114442,0.027230,-0.230340,0.101207,0.217347,0.218405,0.472984,-0.049532,0.080474,-0.374270,0.547012,0.480010,0.063139,-0.493830,0.433560,-0.176557,-0.524834,-0.250126,-0.225233,-0.580589,0.105177,0.675282,0.043142,-0.310583,0.288994,-0.643710,-0.032169,-0.346384,-0.246196,0.042808,-0.131734,-0.207524,-0.465688,-0.053823,-0.641790,-0.227004,-0.114298,-0.110590,-0.320916,0.897396,-0.668358,0.313487,0.442434,0.051668,-0.376580,0.639497,-0.043968,0.032269,-0.122949,0.119207,0.450773,-0.138449,0.393874,0.207069,0.555210,-0.142078,-0.105816,-0.288561,0.656283', '30162520', '1292720', '1870681', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1449845', '冥王星早餐', '剧情', '影片改编自英国布克奖提名作家Patrick McCabe的同名畅销小说《Breakfast On Pluto》，讲述20世纪70年代，异装癖男孩帕特里克·布莱登（希里安·墨菲 Cillian Murphy饰）在遭受社会舆论非议的环境下，从未改变自己，一直寻找母亲的故事。帕特里克在婴儿时就被父母抛弃，然后被神父（连姆·尼森 Liam Neeson饰）收养。可他从小就喜欢穿女生的衣服，幻想自己是个女孩儿。他不知道自己的母亲到底是谁，更无从得知她现在身处何处。等到帕特里克长大后，更是带着金色的假发，画着浓艳的女妆，他拒绝任何人去改变自己，可又怎知，这严酷的环境怎么能容忍这样的“异类”。一路上，帕特里克遇到形形色色的陌生人，一路寻找他的母亲。男主角希里安·墨菲凭借在《冥王星的早餐》中的出色演出，获得第63届金球奖喜剧/音乐类最佳男演员提名。©豆瓣', '基里安·墨菲', '尼尔·乔丹', 8.3, 12804, 'tt0411195', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p788528406.jpg', 0.4, 1.6, 15.5, 45.3, 37.1, '0.080691,-0.007323,-0.665980,0.679858,-0.264908,-0.172323,0.518818,0.096394,-0.442364,-0.280382,0.306826,0.881504,-0.195217,0.109592,0.062737,0.303836,-0.504278,-0.583144,0.135001,-0.128120,-0.331267,-0.368602,-0.293604,0.018138,0.025285,-0.222723,0.553934,-0.121494,-0.276517,-0.068989,0.571611,0.154374,-0.083288,0.430960,-0.247318,0.261122,0.066609,0.171619,-0.026484,0.259096,0.158243,-0.190735,-0.244296,0.208120,-0.060561,0.217921,0.687919,-0.429253,0.053914,-0.051075,0.588911,-0.056898,-0.122926,0.057923,0.161751,-0.257611,0.196365,0.033438,0.106894,0.122786,-0.069721,0.046915,-0.367416,-0.073207,0.127606,0.321886,-0.627697,0.178598,-0.161685,0.010317,0.002956,-0.332581,0.037412,0.113095,0.229113,0.346768,0.001999,-0.046630,-0.508425,0.319856,0.536952,0.145309,-0.373660,0.328609,-0.528774,-0.364840,-0.007711,-0.338760,-0.821972,0.173800,0.205670,0.040507,-0.312694,0.195285,-0.266312,0.002842,-0.092862,-0.051943,0.042530,-0.436957,-0.211026,-0.512090,-0.069067,-0.399979,-0.290500,-0.280504,-0.119451,-0.474796,0.689446,-0.727298,0.374074,0.527320,0.138575,-0.389665,0.678000,0.099705,0.068403,-0.107119,-0.166259,0.522101,-0.077350,-0.031192,-0.021111,0.294826,0.139827,-0.209931,-0.181601,0.530641', '1292720', '30162520', '