INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1449962', '迈阿密风云', '剧情', '美国南部城市迈阿密一直以来都是毒品犯罪的“茂盛”繁殖地。美国联邦调查局（FBI）更是从来都没有放松对这一带地区的监控。警方的卧底在一次毒品交易中惨遭杀害，上级要求桑尼（柯林·法瑞尔 Colin Farrell 饰）和里卡多（杰米·福克斯 Jamie Foxx 饰）扮成毒贩，卧底联系其首领蒙托亚（路伊斯·托沙 Luis Tosar 饰），查 明真相。卧底过程中，个性夸张的詹姆斯不知不觉中陷入了与性感女银行家伊莎贝拉（巩俐 饰）的私密恋情之中。然而，这个亚裔女人实际上就是本地毒品走私集团幕后的重要头目，并且是蒙托亚的女人。蒙托亚的生意代表兹托并不相信桑尼和里卡多，凭直觉感到他们有问题，对他们出处提防，并绑架了里卡多的女友，将这对不速之客置于死地。©豆瓣', '科林·法瑞尔', '迈克尔·曼', 5.7, 14713, 'tt0430357', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p596308431.jpg', 4.6, 24.4, 54.4, 12.9, 3.7, '0.304147,-0.042252,-0.680232,0.484657,-0.103237,0.090354,0.588059,-0.203893,-0.762291,-0.219038,0.023879,0.605813,-0.076058,-0.169747,0.273011,0.249696,-0.497573,-0.782961,-0.112212,-0.281146,-0.254823,-0.681871,-0.415504,-0.444324,-0.127679,-0.071107,0.332964,0.257684,-0.277990,0.326419,0.430794,0.402929,-0.196931,0.454714,0.182048,-0.111076,0.516287,-0.228987,-0.392902,0.115493,-0.121052,-0.087232,0.090995,0.264414,0.204008,0.683509,0.236614,-0.305193,-0.104788,-0.084920,0.058802,-0.384949,0.011207,-0.051050,0.491752,-0.240089,0.279211,0.447401,-0.189204,-0.297760,-0.031804,0.039571,-0.782767,0.039474,0.380136,0.352080,-0.362800,0.322055,-0.270668,0.000030,-0.050746,-0.152954,0.260917,0.223549,0.324914,0.019021,0.265805,0.110356,-0.373579,-0.071903,0.453920,0.010326,-0.141492,0.080739,-0.406147,-0.585651,-0.250808,-0.111299,-0.152768,0.051011,0.063725,-0.090923,-0.050577,0.317724,-0.396397,0.042933,-0.123868,-0.191157,-0.102242,-0.345681,-0.067610,-0.501254,-0.083135,-0.552458,-0.162894,0.001337,0.136310,-0.010247,0.237888,-0.694790,0.036473,0.765473,0.368481,-0.415732,0.521506,0.144847,0.090564,-0.560260,-0.345474,0.202015,0.374609,-0.002705,-0.114695,0.106795,0.187737,-0.508578,-0.097750,0.200304', '1307442', '1293434', '35073886', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1450031', '启示', '剧情', '玛雅文明末期，奢华淫靡之气蔓延，为了祭奠那些刚刚落成的金字塔以及驱散众神的愤怒，玛雅王国派出强悍的军队入侵丛林深处的弱小部落，将战俘作为祭天的牺牲斩杀。年轻骁勇的战士虎爪（Rudy Youngblood 饰）和族人过着平静的生活，他有可爱的儿子和美丽的妻子，并且不久将迎来新的生命。但玛雅军队打破了这一切，他的部落遭到袭击，虎爪及时将妻儿藏在深坑之中，自己却不慎被俘。经过一路坎坷，他和其他战俘来到玛雅城。无数头颅被可耻的刽子手斩落，但即便在这个时刻，虎爪也念念不忘丛林深处的妻儿。只要一息尚存，他无论如何也要回到妻儿的身边……©豆瓣', '鲁迪·杨布拉德', '梅尔·吉布森', 8.7, 87305, 'tt0472043', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1374588202.jpg', 0.3, 0.9, 10.6, 42, 46.1, '0.102444,0.276103,-0.882968,0.663451,-0.088836,0.189462,0.976270,-0.129107,-0.395160,-0.128800,0.494444,0.760068,0.331745,0.180056,0.038447,-0.049024,-0.054069,-0.575509,-0.293024,-0.062408,-0.420958,0.051581,-0.368746,-0.261579,-0.114558,-0.550894,0.889882,0.417698,-0.092992,0.463394,-0.064805,0.397500,-0.367933,0.517128,-0.344573,-0.018797,-0.077966,-0.187192,-0.210680,0.105223,-0.372741,-0.181257,-0.122226,0.292930,-0.295237,0.304040,0.777237,-0.486656,-0.124239,-0.410635,0.317981,-0.442699,0.096632,0.348565,0.377879,0.032591,0.195952,0.261850,-0.004043,-0.110597,-0.000304,-0.368863,-0.970019,-0.264055,0.011572,-0.149293,-0.953988,0.404055,0.107423,0.023076,0.236650,-0.231316,0.356183,0.497753,-0.039289,0.384911,-0.237662,0.127465,-0.467866,0.100787,0.818071,-0.379907,-0.483695,-0.249923,-0.194867,-0.573753,0.015842,-0.561605,-0.518914,-0.088503,0.405406,0.134017,-0.142608,0.423351,-0.712357,0.107569,-0.474283,-0.408931,0.081922,-0.269679,-0.390141,-0.210042,-0.065590,-0.350869,-0.454602,0.254468,0.071630,0.067185,0.794106,-0.632028,0.422439,0.551598,0.624296,-0.408367,0.561943,-0.205743,0.131625,0.115620,-0.174393,0.647273,0.239046,0.451527,0.249149,0.053796,-0.214653,-0.067998,-0.400804,0.532815', '21619567', '25828589', '26667010', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1451563', '五朵金花', '爱情', '旧历三月云南大理，人民公社的副社长金花（杨丽坤）带领着姐妹们驱车去赶一年一次的“三月街”传统盛会，半路车坏，众人手足无措之时，遇到前来参加赛马会的剑川铁匠阿鹏（莫梓江），阿鹏将车修好，没等金花致谢就翻身上马冲进赛场勇夺冠军。赛后金花找机会与阿鹏接近，两人交谈中生出感情，相约来年山茶花盛开时再在蝴蝶泉边相见。第二年阿鹏如约前来，左等右等不见金花身影，不知如何是好之时，他结识两位来自长春电影制片厂的音乐家与画家朋友，对方听完他的经历，立誓帮他找到金花。找寻中，积肥模范金花（孙静贞）、畜牧场金花（谭尧中）、炼钢厂金花（王苏娅）和拖拉机手金花（朱一锦）先后被阿鹏错当作他的真命天女，笑话闹了不少。©豆瓣', '杨丽坤', '王家乙', 8.1, 10060, 'tt0355036', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507113721.jpg', 0.3, 1, 21.5, 49.2, 27.9, '-0.010183,-0.128840,-0.797351,0.183890,0.097486,-0.456135,0.317729,-0.024312,-0.476147,0.094268,0.076213,0.488387,-0.563484,0.176410,0.317651,-0.031936,-0.181355,-0.835632,0.149968,-0.244713,-0.143073,-0.030473,0.116955,0.433012,-0.145267,0.244058,0.060945,-0.090026,0.130917,1.117077,0.007805,0.123424,-0.158049,0.240987,-0.132869,0.223062,0.239648,0.205771,-0.455679,0.308166,-0.051235,-0.254809,-0.340716,-0.318929,0.023324,0.146276,0.603816,-0.123415,0.267036,-0.407034,0.056465,0.023084,0.207695,0.132540,0.495003,0.191446,0.193874,0.103731,-0.223805,-0.145975,-0.213251,-0.062738,-0.021771,0.544249,-0.152972,0.124387,-0.816879,0.219582,0.139475,-0.144904,0.206352,-0.421269,0.421108,0.192005,0.153839,0.117760,-0.165505,-0.147537,-0.462679,0.245634,0.809870,0.018514,0.257950,0.183573,0.312406,-0.129295,0.547346,-0.018862,-0.112623,0.130439,0.289553,-0.120688,0.034886,-0.227485,-0.464570,0.060523,-0.263831,-0.136610,0.280696,-0.040875,-0.169954,-0.693438,0.081495,-0.096389,-0.292091,0.020507,0.189649,0.082620,0.551665,-0.627985,0.280265,0.078916,0.451143,-0.212546,0.725410,0.164287,0.219770,-0.035114,0.113356,-0.352290,-0.121763,0.663387,0.187298,0.145640,-0.264629,-0.073702,-0.309926,0.070097', '35256235', '25723081', '26365262', '1304600');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1451895', '神算', '喜剧', '许怀谷（许冠文 饰）专职为人算命，但他实际上不过是预先搜集了客人的资料而且利用了客人的心理，被人称为神算。税务局局长夫人疑心丈夫有外遇前来占卜，竟然让许怀谷猜中了疑似局长情人的名字。局长遭到妻子责骂后，决定派出评税员邱浩基（黎明 饰）调查许怀谷的收入。调查期间，许因为头部受伤得了超能力，接触到别人手脚便能看到对方的将来。浩基为了升职便要求许怀谷接近商人洪森，希望能找到他瞒税的证据。开始时候洪森处处回避，当知道许怀谷是个神算后，便重金礼聘二人。浩基借此机会彻底调查洪森……©豆瓣', '许冠文', '许冠文', 7, 5882, 'tt0105386', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2661534660.jpg', 0.7, 6.1, 48.3, 31.6, 13.2, '0.159963,-0.072535,-0.500058,0.398719,-0.405427,-0.167573,0.105817,0.178015,-0.753571,-0.501553,0.313546,0.375656,-0.139410,-0.125708,0.297603,0.084931,-0.144048,-0.580783,0.289568,-0.135112,-0.349011,-0.510549,-0.161678,-0.433986,-0.085578,-0.177226,0.195369,0.134046,-0.159208,0.058400,-0.054308,0.078317,0.268117,0.371088,-0.054763,0.081996,0.166262,-0.071462,-0.303964,0.264447,0.131239,-0.222909,-0.142212,0.176656,0.089943,0.659402,0.331132,-0.043066,-0.253282,-0.183841,0.143569,-0.224953,0.327821,0.189122,0.378920,0.343891,0.427091,0.364754,-0.425756,-0.071843,0.008030,0.253750,-0.741452,0.147876,0.154828,0.095425,-0.240682,-0.121255,-0.361581,0.030853,-0.266196,-0.366002,0.482160,0.291556,0.106234,0.040280,-0.041663,0.100577,-0.486193,0.101817,0.427056,-0.217896,0.219079,0.250365,-0.032614,-0.326245,0.276941,-0.197259,-0.041709,0.125598,0.036206,0.243661,-0.198174,-0.112983,-0.205448,-0.359446,-0.379067,0.243838,-0.031847,-0.453426,0.051470,-0.239513,-0.310477,0.123130,-0.067149,-0.108434,0.331904,-0.381123,0.490598,-0.738010,0.019771,0.532462,0.302951,-0.787157,0.633887,0.251010,-0.136316,-0.365835,-0.004342,-0.433054,0.213020,0.394048,0.035764,-0.020382,0.221348,-0.757541,0.061586,-0.053520', '3811342', '35073886', '1308655', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1451911', '独家新闻', '喜剧', '一个美国女大学生桑德拉（斯嘉丽·约翰逊 Scarlett Johansson 饰），为了替学校报纸寻找独家新闻，来到英国伦敦采访一个电影导演。在调查和采访的过程中，她参加了魔术师希德（伍迪·艾伦 Woody Allen 饰）一次魔术戏法表演，在密闭的箱中她遇见了一个离世 的资深记者鬼魂。记者生前是一个为了拿到独家新闻无所不尽其用的人。他在去往阴间的船上从一个被害的前任秘书口中得知“塔罗牌杀手”竟然是英俊多金的贵族彼得（休·杰克曼 Hugh Jackman 饰）。他不想让这有爆炸性的新闻埋葬，于是找上桑德拉希望她帮他完成心愿。面对这个千载难逢的机会，桑德拉决定深入虎穴，拉上魔术师希德假扮父女混进上流社会，接近彼得。事情顺利得令人惊讶，桑德拉与彼得成了甜蜜的一对。然而塔罗牌杀手又继续行动……©豆瓣', '斯嘉丽·约翰逊', '伍迪·艾伦', 7.3, 54838, 'tt0457513', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p620204954.jpg', 0.5, 3.7, 39.1, 44.7, 12.1, '0.228322,-0.083699,-0.455346,0.507231,-0.181219,-0.304224,0.687342,-0.060562,-0.385032,-0.289853,0.227547,0.812149,-0.399116,0.142128,0.322594,0.050675,-0.527815,-0.666763,0.064318,-0.122134,-0.106687,-0.404640,-0.249930,-0.398014,0.097746,-0.215616,0.569743,0.074103,-0.023938,0.381582,0.440354,0.312424,-0.030401,0.166619,-0.163130,-0.088430,0.380145,-0.094656,-0.354857,0.504283,0.049547,-0.172580,-0.103520,0.283324,-0.068694,0.234876,0.500371,-0.272433,-0.000236,0.142407,0.504067,-0.492588,-0.070705,-0.040581,0.168432,-0.001173,0.206994,0.032461,-0.232781,-0.105237,0.095845,-0.226874,-0.733398,0.082197,0.075956,0.379544,-0.436044,0.280047,-0.322411,0.112071,0.106102,-0.274379,0.228810,0.065882,0.344290,0.198393,0.081810,0.118245,-0.443912,0.335535,0.694633,0.179782,0.031536,0.236667,-0.022908,-0.399607,0.238072,-0.184421,-0.423792,0.337754,0.345598,-0.245016,-0.102172,0.101255,-0.446778,-0.291733,-0.536743,0.037589,0.053193,-0.306526,-0.236429,-0.714737,-0.085790,0.207407,-0.181316,-0.041470,0.061227,-0.339521,0.674584,-0.650196,0.090636,0.669814,0.079263,-0.408309,0.878919,0.024547,0.207195,-0.392511,-0.091469,-0.069004,0.240997,0.265330,0.010268,0.242832,0.050705,-0.408247,-0.338296,0.139566', '4301278', '34890458', '1829654', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1452109', '经过', '剧情', '2004年，故宫书画处助理研究员阿静（桂纶镁饰），自小听着资深员工阿超伯（田丰饰）的故宫往事长大，对故宫的山洞库房有着诸多想像。东横（戴立忍饰）是名自由作家，帮故宫撰写故事，一段失恋境遇让他相信残缺只是人生必经过程。退休的阿超伯一生的故事，成为东横写作的题材，更是阿静童年的最深记忆。阿静学姐的前男友东横情愫暗生她，渐渐冷漠的东横因她有了改变。一日，阿静在故宫遇见了日本人岛英一郎（荫山征彦饰），原来他是汽车公司的设计师，在公司的斗争中心灰意冷，想来寻找苏东坡的“寒食帖”，解开爷爷回忆的谜底……©豆瓣', '桂纶镁', '郑文堂', 6.9, 7273, 'tt0447349', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1770078329.jpg', 0.9, 7.6, 48.7, 32.7, 10.1, '0.170064,-0.102506,-0.164632,0.442651,0.140279,-0.263541,0.631877,0.088835,-0.853313,-0.379439,0.142134,0.611592,-0.187313,0.429095,0.085950,0.041725,-0.265487,-0.439794,0.068077,-0.213198,-0.013884,-0.438507,0.052663,-0.029450,-0.022045,-0.367969,0.747902,0.243943,-0.179086,0.271513,-0.074330,0.212013,-0.271582,0.152027,-0.161643,0.071733,0.160772,0.221337,-0.446132,-0.269989,-0.073611,-0.218656,-0.241708,-0.073422,-0.203847,-0.006869,0.603071,0.259851,-0.349168,0.121765,0.648951,-0.037711,-0.195770,-0.259998,0.219484,0.274300,0.134695,0.478815,-0.211669,-0.228948,-0.166087,-0.142180,-0.339178,-0.181249,0.366070,0.220259,-0.457713,0.452778,-0.050931,0.051567,0.247907,-0.273864,0.174327,-0.029996,0.291089,0.397745,-0.054545,0.092468,-0.336280,0.645056,0.412710,-0.107452,-0.112660,0.479645,-0.235081,-0.370148,-0.197742,0.019458,-0.390598,0.242024,-0.116294,-0.158547,-0.450007,0.288229,-0.472290,0.005978,0.127523,-0.293760,0.293485,-0.268788,-0.183514,-0.494810,-0.547381,-0.231025,-0.151691,-0.413435,0.195565,-0.318142,0.819817,-0.587436,0.238418,0.592780,-0.044673,-0.346631,0.944023,-0.030038,-0.239275,-0.373744,0.171318,0.366052,-0.256674,-0.011687,-0.162272,0.318650,-0.185494,-0.115562,-0.596961,0.499629', '1908036', '3448362', '2338019', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1452554', '平原游击队', '剧情', '抗日战争时期的1943年秋，游击队长李向阳（郭振清）接到牵制日军驻守某县城的松井部队的任务，以达到粉碎日军“扫荡”华北某根据地的阴谋，并保住藏于李庄的粮食。行动时，李向阳与参谋长兵分两路并头进行。李向阳转移粮食时，被地主杨老宗窥见，后者赶去县城向松井（方化）告密，松井闻之大喜，率大部队赶到李庄，但粮食和乡亲已被李向阳安排转移到地道，然而地道终被松井发现。为引诱松井离开李庄，李向阳率队员进县城，炸毁日军弹药列车，并计划在松井撤退时打他个措手不及，但李向阳低估了松井的狡猾，松井半路杀了个“回马枪”折回李庄，残杀了一些不肯说出粮食藏在哪里的乡亲。可是李向阳的神出鬼没松井终没招架住。©豆瓣', '郭振清', '苏里', 7.5, 7565, 'tt2009551', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1578531668.jpg', 1.6, 2.5, 32.1, 44.3, 19.5, '0.099115,-0.292679,-0.354514,0.109112,-0.034368,-0.237657,0.347120,0.191433,-0.168029,-0.128471,0.209613,0.219557,0.125125,-0.259638,0.097617,-0.237825,-0.196902,-0.379965,-0.165230,-0.118323,0.106349,-0.439389,-0.001221,-0.272182,-0.059114,0.092843,0.810502,0.562230,-0.165860,0.287709,-0.108172,0.261575,-0.262825,0.562645,0.167539,0.413225,-0.100043,-0.540311,-0.128709,0.318901,-0.282692,-0.344437,-0.196697,-0.096003,0.099898,0.562730,0.483158,0.130513,-0.120210,-0.027826,-0.126082,-0.537328,-0.113772,0.295749,0.503165,-0.095007,-0.197741,-0.112710,-0.226546,0.274396,-0.029902,0.181291,-0.454064,-0.004060,-0.021944,-0.219882,-0.516307,0.204177,-0.102554,0.333474,-0.011176,-0.572535,0.095511,0.728695,0.033171,-0.032434,-0.368086,0.335643,-0.340753,-0.305229,0.457797,-0.582209,0.240382,-0.232650,0.247689,-0.296352,0.102156,-0.110013,0.164920,-0.032578,0.132415,-0.013631,0.078598,-0.232449,-0.481532,-0.330267,-0.327337,-0.157638,0.183736,-0.127230,-0.347898,-0.854201,0.315917,-0.180181,-0.375592,0.532669,0.370278,0.116293,0.495504,-0.540223,-0.504899,0.621718,0.225830,-0.337384,0.013004,0.076053,-0.090451,-0.079535,0.242341,0.220250,0.329422,0.828979,0.570427,0.182374,-0.586955,-0.407604,-0.223574,-0.178763', '2369613', '1431694', '1300371', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1453067', '隔山有眼', '惊悚', '老夫妻鲍勃·卡特(泰德·列文饰)与艾塞尔(凯瑟琳·昆兰)为了庆祝他们的结婚纪念日，带着家人开车做一次穿越国境的公路长途旅行。本希望借此次旅行增进家庭成员之间的感情，但旅行中发生的种种摩擦却时时考验着这个家庭。旅程渐渐进入漫漫黄沙荒无人烟的地带，在一次夜晚扎营时休息时，他们遭受到了一群怪物的袭击，原来此处附近曾有一个废弃美军研制核武器的基地，核实验让附近一个村庄的人们遭受到了可怕的核辐射，活下的人身体变的畸形且性情嗜血而暴力，他们伏击这一家人，对他们进行残忍的捕杀，原本老实懦弱的女婿达乌·布库威斯基(亚伦·斯坦福德饰)决心振作起来，做出最强烈的反击。©豆瓣', '亚伦·斯坦福', '亚历山大·阿嘉', 6.8, 41169, 'tt0454841', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200535672.jpg', 1.8, 8.7, 49.6, 30.1, 9.8, '0.306001,-0.312718,-0.733948,0.645818,0.038509,-0.130110,0.715595,0.151903,-0.421972,-0.237776,0.348668,0.624283,-0.266525,0.123345,0.282277,-0.100818,-0.304915,-0.276724,-0.048489,-0.001201,-0.338775,-0.285697,-0.243192,-0.319494,0.108907,-0.244863,0.409228,0.476770,-0.219120,0.402661,-0.110289,0.148551,0.015514,0.534840,-0.132443,-0.194173,0.083640,-0.077874,-0.281875,0.174384,-0.067579,-0.002757,-0.128077,0.046549,-0.040612,0.450540,0.812954,-0.220849,-0.277809,-0.339953,0.283294,-0.301583,0.094686,0.159099,0.238969,-0.143930,-0.082793,0.189900,-0.086803,-0.059177,-0.043546,-0.111868,-0.565834,-0.016289,-0.246256,-0.052358,-0.452048,0.242568,0.039717,0.008741,0.162989,-0.112874,0.262568,0.771007,0.236212,0.036464,-0.242821,0.079712,-0.458825,-0.179518,1.002112,-0.195868,-0.308465,0.017481,-0.407333,-0.431178,0.205247,-0.096794,-0.454005,-0.220742,0.153137,-0.160529,-0.327314,0.410598,-0.752978,0.034588,-0.390282,-0.253188,-0.050810,-0.187743,-0.254208,-0.902927,-0.035690,-0.386707,-0.324701,0.193233,-0.098068,-0.112811,0.432980,-0.541183,0.365154,0.629653,0.389825,-0.385797,0.550649,0.036179,0.160269,-0.154278,-0.048310,0.333659,-0.038984,0.372281,0.077426,0.292759,0.058092,0.201850,-0.267855,0.500724', '3147969', '34461680', '11541282', '1498831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1455442', '新世纪福音战士剧场版：死与新生', '剧情', '《新世纪福音战士》电影版第1部。分为“DEATH篇（死亡篇）”与“REBIRTH篇（新生篇）”两个部分。“死亡篇”以原TV版动画第1集到第24集的内容为基础，重新剪辑了一个总结篇。“新生篇”内容承接第24集内容：第十七使徒被消灭后，SEELE向NERV下达命令，要EVA初号机负责执行“人类补完计划”。然而碇元度不认同SEELE的做法，拒绝执行。SEELE认定这是一种叛变的行为，决定把NERV彻底消灭。破晓时分，NERV本部突然遭到来自战略自卫队的袭击，他们对NERV的人员进行了惨无人道的大屠杀。为了保护驾驶员，葛城美里命令把精神崩溃的明日香送上二号机，并放在湖底的深处，自已就亲自去救碇真嗣 。但此时的碇真嗣已经处在精神崩溃的边缘。©豆瓣', '绪方惠美', '庵野秀明', 9.2, 43046, 'tt0169880', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p454134242.jpg', 0.4, 0.6, 6.1, 23.8, 69.1, '0.183972,0.125180,-0.491954,0.900636,0.204266,-0.151264,0.182614,0.011111,-0.171203,-0.169619,0.015126,0.376821,0.021727,-0.089370,0.339784,0.111651,-0.313871,-0.555504,-0.409849,-0.133454,-0.205318,-0.614857,0.149071,-0.079585,0.091788,-0.502428,1.062204,0.170579,-0.533285,0.038939,0.324159,0.683365,-0.193497,0.327291,0.376147,0.019895,0.031748,-0.537751,-0.195877,0.487822,-0.092832,-0.005473,0.170966,0.119537,-0.258865,0.381831,1.101955,-0.478249,-0.273115,0.018966,0.644611,-0.380197,-0.523384,0.380284,0.656872,0.350984,-0.278521,0.513283,-0.077292,0.637045,-0.223950,-0.200082,-1.048282,-0.642617,0.142409,-0.053414,-0.268886,0.198368,-0.406912,0.435871,0.335604,-0.286934,0.219496,0.406625,0.652768,0.372699,-0.150921,-0.043836,0.195635,-0.102967,0.493497,-0.153935,-0.183836,0.187148,0.142393,-0.366346,-0.057071,-0.183705,0.281942,0.249293,0.048075,0.455413,0.007985,0.143457,-0.900987,-0.396592,-0.163133,-0.861604,-0.139276,-0.308745,0.079902,-0.684440,-0.127480,0.358079,0.177428,0.238248,0.209268,-0.303767,0.851325,-0.458183,0.477284,0.321186,0.030394,-0.453615,0.078169,0.421270,0.103743,-0.502403,0.296928,-0.039965,0.225219,0.701510,0.146288,0.202522,-0.294510,-0.196798,-0.457655,0.284657', '26759820', '10467125', '1292347', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1455849', '鬼来电', '悬疑', '手机里传来陌生的铃声，呼叫人竟是自己的名字，另一端传来不知所谓的留言内容，但那毫无疑问的是自己的声音，这是怎么回事？“鬼来电”悄悄在高校学生中蔓延开来，一旦接到鬼来电，必然在电话所预言的时间内悲惨死去。由美（柴咲コウ饰）的好友阳子、研二、夏美先后惨死，由美有心挽救好友们的生命，却爱莫能助。山下（堤真一饰）的妹妹早先亦死于这通电话，他企图帮助由美一起企图揭开真相，可很快，由美也收到了鬼来电……©豆瓣', '柴崎幸', '三池崇史', 7, 31373, 'tt0366292', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p662740428.jpg', 1.1, 6.3, 47.2, 34.6, 10.8, '0.118209,0.175665,-0.571627,0.573351,0.001864,0.144658,0.531028,-0.032195,-0.454807,-0.291682,-0.131281,0.409908,0.016397,0.317218,0.151055,0.092893,-0.358556,-0.737491,-0.021632,-0.294532,-0.271367,-0.160652,-0.111850,-0.301850,0.143641,-0.166705,0.306575,0.192143,-0.320753,0.344186,0.502613,0.494877,-0.535622,0.546511,-0.006722,0.382436,0.113794,0.104387,-0.045212,-0.056711,0.152907,-0.454564,0.058750,0.327405,-0.123769,0.602492,0.260575,-0.421097,-0.132407,0.245996,0.352559,-0.171108,-0.058967,-0.000393,0.355942,0.296402,0.621049,0.190935,-0.363881,-0.051290,0.041530,0.285806,-0.452483,0.155599,0.015966,0.247048,0.138532,0.179468,-0.361369,0.135913,0.223179,-0.157838,0.290381,0.155989,0.125472,0.372374,-0.670842,0.004429,-0.049467,-0.065155,0.624053,-0.004230,-0.154500,0.322368,0.103154,-0.339892,0.102153,0.161759,-0.455715,0.109993,0.418025,0.279925,-0.016874,0.106453,-0.430313,-0.064168,-0.131493,-0.083289,-0.033208,-0.325303,-0.431026,-0.347148,-0.203321,0.024111,-0.268245,0.287701,0.223293,0.008212,0.801662,-0.646859,0.003399,0.136442,0.041821,-0.020063,0.356063,0.107823,0.015405,-0.047712,0.114392,0.192766,0.232937,0.545079,-0.011701,-0.128321,0.022844,-0.274844,-0.673952,0.083319', '1307146', '4724586', '25938113', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1455979', '墨攻', '剧情', '诸国纷争群雄争霸的两千多年前，赵国为一举攻下势均力敌的燕国，决定先拿夹在赵燕之间的梁国开刀，于是妇孺平民加起只有四千余人的梁城被赵国十万大军包围。危难之时，梁王（王志文）向以守城著称的墨家请求一支可以抵抗赵军的守军，却等来其貌不扬孤身应战主张“兼爱非攻”的墨者革离（刘德 华）。革离出奇制胜，令赵军无功而返，后为应付赵军随时而来的庞大攻击，又亲自练兵制造无数特别兵器，梁城上下对其无不折服，更得到逸悦将军（范冰冰）的爱慕，然而，杀气也在此时降临他的四周。©豆瓣', '刘德华', '张之亮', 6.2, 73335, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165825008.jpg', 2.6, 15.1, 57.4, 20.2, 4.7, '-0.013732,0.100938,-0.576112,0.531345,0.169167,0.088602,0.419594,0.176015,-0.555233,-0.218902,0.250814,0.431019,-0.001274,-0.240261,0.098040,-0.542859,0.195193,-0.678217,-0.538164,-0.107495,-0.113906,-0.037266,-0.380135,-0.143098,-0.330953,0.037124,0.647094,0.347750,-0.304964,0.439129,0.005196,0.194402,0.084193,0.745364,-0.083072,-0.361217,-0.596468,-0.276088,-0.382387,0.309736,-0.266837,-0.355676,-0.549278,0.395726,-0.395717,0.308022,0.602093,-0.389972,0.335719,-0.249739,0.007206,-0.193347,0.074100,0.034299,0.205066,0.183147,0.030609,-0.102778,0.011355,0.098525,-0.086640,0.007324,-0.696284,-0.071685,0.043127,-0.041714,-0.603541,0.366414,-0.046000,-0.032972,0.165466,-0.343816,-0.039862,0.778626,0.107414,0.011439,-0.147007,-0.232382,-0.584445,-0.091625,0.605906,-0.147274,-0.176372,-0.432722,0.099225,-0.379894,0.247985,-0.316898,-0.398208,-0.169880,0.201248,-0.138299,0.500662,0.094025,-0.533227,-0.135899,-0.366584,-0.004822,0.082193,-0.203199,0.092158,-0.585679,-0.007447,-0.010978,-0.132411,0.423172,0.526869,0.188325,0.744550,-0.495185,-0.307167,0.245287,0.455961,-0.651613,0.130364,0.078226,-0.020346,0.207802,-0.363619,0.141275,0.394211,0.542144,0.153626,0.101030,-0.118605,-0.190328,-0.413358,0.245723', '1917313', '1301022', '5157137', '1295746');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1456197', '人皮客栈', '恐怖', '帕克斯顿（杰伊·赫尔南德兹 Jay Hernandez饰）和乔什（德里克·理查德森 Derek Richardson饰）是大学同窗好友，二人为了摆脱枯燥的校园生活，决定前往东欧进行一次刺激的旅行。两人于是当起了背包族，还遇上了同道中人奥利（艾瑟·古庄森Eythor Gudjonsson饰）结伴同行，寻欢作乐。听到斯洛伐克有一个小镇，是个香艳的天堂，美女秀色可餐，几个年轻人就糊里糊涂踏上了火车，来到这个想象中的乐园。在这里，美女让他们一夜销魂，然而可怕的事情却接二连三。他们将会发现，此处并不是他们的游乐场，而是一个难逃生天的地狱。奥利的失踪，更让胆小的乔什意识到，恐怖的事件拉开帷幕了。©豆瓣', '杰伊·埃尔南德斯', '伊莱·罗斯', 6.8, 50279, 'tt0450278', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1103646054.jpg', 1.6, 8.5, 47.5, 31.4, 11.1, '0.548514,-0.196603,-0.661512,0.503491,-0.037181,-0.305478,0.966066,0.000790,-0.541800,-0.053480,0.100403,0.798316,-0.466253,0.280600,0.473046,0.315695,-0.284410,-0.543230,0.243949,-0.161759,-0.258234,-0.500347,-0.215710,-0.202727,0.104641,-0.344407,0.230709,0.276917,-0.058562,0.705764,0.332712,0.073947,-0.102365,0.602668,-0.176730,0.020706,0.409804,0.151368,-0.000100,0.346150,-0.113945,0.091436,-0.288083,0.137014,0.134503,0.157547,0.479382,-0.129410,-0.278141,0.161908,0.240710,-0.363407,-0.148597,0.152619,0.255754,-0.412495,0.089665,0.079146,-0.144873,0.211871,0.043301,-0.120800,-0.572749,0.213553,-0.153102,0.021189,-0.395853,0.293203,0.002333,-0.346036,0.022026,-0.327545,0.225914,0.373139,0.384467,0.447649,-0.026093,-0.208790,-0.422417,0.108619,0.863796,0.069139,-0.424199,0.393348,-0.008995,-0.494402,0.010530,-0.023482,-0.292693,0.022864,0.378662,-0.053186,-0.330888,0.273242,-0.627886,0.071669,-0.508937,-0.197164,-0.183412,-0.255995,-0.167401,-0.755541,-0.120936,-0.067189,-0.361078,0.349350,-0.005517,-0.134094,0.551726,-0.638707,0.165098,0.760982,0.120492,-0.291614,0.498426,0.008484,0.150269,0.078413,0.087589,0.237070,0.047025,0.327263,0.030931,0.530635,-0.212637,-0.233859,-0.418720,0.413663', '1301686', '1296534', '26687241', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1456415', '智齿', '剧情', '赵仁英（金正恩 饰）在外语学院当数学讲师，是个美丽自主的现代女性。一个叫李锡的男孩进入了仁英视线里。她十分惊讶这个男孩跟自己的初恋情人同名同姓，就连长相也十分相似。因为如此，仁英无可救药的爱上了这名男孩。而李锡也是很喜欢仁英的。可是，仁英的好友同事郑宇见到李锡的时候，感觉李锡并不想仁英的初恋男友，也不相信李锡与仁之间的爱情。郑宇实在不忍看到好友生活在幻觉中，便决意带来了已经三十岁的仁英的初恋情人，那位真正的李锡。©豆瓣', '金廷恩', '郑址宇', 6.2, 5826, 'tt0481815', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p637505736.jpg', 2.8, 16.2, 54.1, 20.4, 6.5, '0.454503,-0.071733,-0.713310,0.682881,-0.395342,-0.499888,1.055307,0.140669,-0.403313,-0.489626,0.095515,1.035115,-0.125064,0.651569,0.292476,0.050638,-0.066338,-0.656273,-0.166482,-0.392014,-0.171418,-0.493014,-0.167862,0.046957,-0.287638,-0.067334,0.832780,-0.182420,-0.181273,0.665094,0.505626,0.045113,0.240273,0.786860,-0.281244,0.126974,0.031315,0.365278,-0.069659,-0.135306,0.073215,-0.210692,0.129418,0.450869,-0.332029,0.254166,0.526690,-0.344424,-0.249127,-0.031966,0.369768,-0.124954,-0.271093,0.247061,0.175994,-0.158162,0.250496,-0.177369,-0.072990,-0.087334,-0.062571,0.058794,-0.673333,0.003127,0.026546,0.242784,-0.396159,0.523063,-0.055686,-0.303214,0.182190,-0.295616,0.364460,0.167506,0.236080,0.523732,-0.503801,-0.019957,-0.050011,0.113854,0.635807,0.361192,-0.281547,0.690713,-0.508834,-0.667141,-0.080273,0.104165,-0.719550,0.302109,-0.106901,0.104002,-0.266284,0.201727,-0.534054,0.149960,-0.065925,0.308598,-0.191838,-0.438400,-0.036474,-0.169446,-0.239109,-0.834676,-0.437235,0.154122,-0.042786,-0.513505,0.830401,-0.980801,0.015730,0.349401,0.436788,-0.345127,0.803361,0.452102,-0.351348,-0.285901,-0.026851,0.060742,-0.043670,0.052272,-0.042775,0.565546,0.010872,-0.319860,-0.458677,0.498757', '4275444', '24756472', '1291877', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1456503', '爱疯狂', '喜剧', '本片讲述了一个家庭30多年的悲欢离合，以其中一个孩子Zac为主线，因为他游离于同性恋和双性恋之间。这部作品完全不同于其他的同性恋电影，直到影片最后，你可能也不会有一个最终的判断。但是那种家庭的亲情，父母兄弟姐妹恋人之间的爱和冲突，却让人不能不心生感动。片名C.R.A.Z.Y.是家里五个男孩名字的首字母：Christian, Raymond, Antoine, Zac, Yvan.影片中的一段故事，说有一个人很信仰上帝，他每天行走，身后会留下两串脚印，一串是自己的，另一串是上帝的。但是在他最困苦的时候，他发现自己身后只有一行脚印。等他摆脱了困苦后，他质问上帝，“为什么说和我同在，却在我最需要你的时候离开我？”上帝回答说，“在你最困苦的时候，你看到只有一行脚印，那是因为是我背负着你前行。”这是加拿大选送参加2006年奥斯卡最佳外语片的电影，该片共获得包括多伦多电影节最受观众欢迎奖在内的大小奖项共计37项。', '米歇尔·寇特', '让-马克·瓦雷', 8, 6183, 'tt0401085', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p490646072.jpg', 0.5, 1.9, 22.4, 46.5, 28.7, '0.045495,-0.154791,-0.739930,0.845982,-0.119124,-0.155667,0.817182,-0.016713,-0.456645,-0.094037,0.052243,1.139778,0.010514,0.244649,-0.063513,0.018661,-0.204438,-0.621044,-0.103738,-0.267697,-0.469433,-0.446060,0.017302,-0.128601,-0.259314,-0.153911,0.645298,0.138652,-0.244080,0.208780,0.589812,-0.039144,0.006764,0.368773,-0.255766,0.073697,0.036634,0.269912,-0.184743,0.213872,0.093048,-0.201373,-0.255471,0.333502,-0.215119,0.319583,0.523766,-0.287266,-0.092361,0.091416,0.402066,-0.383812,-0.169015,-0.180290,-0.028798,-0.167980,0.550294,0.426729,-0.045156,0.095724,-0.040539,0.007311,-0.861278,-0.136806,-0.025146,0.357219,-0.726181,0.525548,0.044937,-0.148076,0.290845,-0.247174,0.483197,0.216538,0.342180,0.317751,-0.188171,-0.264543,-0.538269,0.296418,0.792401,-0.036804,-0.292091,0.464925,-0.499464,-0.532774,-0.126005,-0.005400,-0.496390,0.238420,0.086923,0.050240,-0.242754,-0.119976,-0.360401,0.311341,0.261008,-0.272228,-0.019561,-0.808910,0.037973,-0.339599,-0.078619,-0.528073,-0.375733,0.115244,-0.004635,-0.426055,1.034284,-0.702679,0.240498,0.377947,0.390601,-0.615092,1.084866,0.556571,-0.181364,-0.249982,0.155875,0.225312,0.026327,-0.111048,-0.027033,0.130625,0.138054,-0.033544,-0.407569,0