INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1456774', '警察有约', '喜剧', '赵六安（夏雨饰），社区普通小片警，整日处理鸡毛蒜皮的邻里纠纷和生活琐事。善良热情的赵六安倒也乐此不疲。只是年届而立之年还没对象的他，婚姻大事自然成为了他和周围人的首要任务。赵六安头上有五个姐姐，又是家中独子，所以不仅邻里、同事对此格外热心，他的五个姐姐更是成为赵六安相亲时刻的“监视者”。然而十二次相亲经历均告失败，不过赵六安倒也不觉烦恼，回到宿舍便与网友（梁静饰）聊天。这位神秘的网友，原来是赵六安身边一位熟悉的“陌生人”。这部充满温情、幽默和悬念的轻喜剧《警察有约》，演员阵容强大，不仅囊括了夏雨、梁静等青年演员，更有杨立新、剧雪、许亚军、贺晓舒等明星友情加盟，乒乓球冠军王涛还在片中客串了一个小角色。本片荣获2003年中国电影金鸡奖最佳影片、最佳编剧、最佳男主角、最佳女配角四项提名。夏雨凭借此片夺得最佳男主角桂冠，而首上荧屏的梁静则获得最佳女配角提名。', '夏雨', '徐耿', 7.5, 7850, 'tt0470390', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2372533697.jpg', 1.8, 2.1, 32.7, 47.2, 16.2, '0.045198,-0.058078,-0.555161,0.620471,-0.094396,-0.277662,0.799221,0.035773,-0.537718,-0.128728,0.049281,0.435462,-0.435189,0.254078,0.386106,-0.439709,-0.214592,-0.443758,-0.223944,-0.017300,-0.135867,-0.282402,-0.376693,-0.183193,-0.328164,0.056331,0.564435,-0.198617,-0.177024,0.398178,0.762925,-0.125405,-0.036118,0.526999,0.051441,0.242744,0.202771,0.309779,-0.239734,0.284337,0.037226,-0.434494,-0.147593,-0.098150,0.232642,0.296171,0.517387,0.198754,-0.048154,-0.006953,0.460956,-0.225363,-0.101772,-0.091704,0.331083,-0.178281,0.512058,-0.291423,0.103298,0.076778,-0.064895,-0.362898,-0.530414,0.176698,0.399266,-0.014163,-0.264422,0.203116,0.117682,-0.048703,-0.017702,-0.186826,0.297406,0.099851,0.373891,0.103556,-0.062516,0.027741,-0.195010,0.821009,0.451881,0.272264,-0.252927,-0.000556,-0.147042,-0.878213,0.057482,-0.111990,-0.479411,0.244229,0.333805,-0.235419,0.504366,-0.119126,-0.250331,-0.026843,0.288737,-0.169551,0.001664,-0.404399,0.537372,-0.700066,-0.116260,-0.312418,-0.148342,0.062756,0.276717,-0.487340,0.820302,-0.511167,0.127026,0.171564,0.052773,-0.540468,0.688839,0.157428,0.375253,-0.459192,-0.022201,-0.040115,-0.049057,0.021410,0.190271,0.403207,-0.403880,-0.181222,-0.081584,0.204022', '2027945', '1322847', 