INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457127', '迷宫物语', '科幻', '小女孩欧吉蒂（又译：吉茜娜）因好奇而带着大肥猫走进座钟后的迷宫之门，在广阔的迷宫通道里追随着白衣小丑的影子，就此成为两个故事的旁观者。这两个故事一个关于世界知名的赛车受杰克?休，他汽车拉力赛中的死因成迷：另一个关于被派往444号工程传达停工命令的杉冈勉，身处大量失控机器人中的他是工程中唯一的人类，当他决定毁掉一切阻止工程的时候，上司却发来了可继续支持工程的命令……原名《Manie—Manie  迷宫物语》。是一部实验性质的动画作品，由《迷宫物语》、《狂奔的男人》、《工事中止命令》三个小故事组成，各部分风格迥然不同，情节也各自独立，因此作品整体谈不上完整的情节叙述，只以小女孩为视线贯穿鲜有对白的群片。片中的每个故事由不同的制作人员负责，因此从人物设定到表现手法及配乐都大相径庭。全间充斥着语言般的隐喻，超现实与写实的表现手法互相融合，使作品从始至终弥漫着一种迷离而诡异的氛围。此外，3个部分的映像效果都十分精美，对细节的把握也十分出色。', '吉田日出子', '川尻善昭', 8.1, 7983, 'tt0185481', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575547749.jpg', 0.7, 2.1, 20, 47.6, 29.6, '0.171088,0.100022,-0.571752,0.925550,0.035424,0.220843,0.875949,0.069459,-0.439543,-0.308165,0.159927,0.534945,-0.038495,0.004441,0.107927,-0.336285,-0.251268,-0.383444,-0.370202,-0.185256,-0.214779,-0.463605,-0.032402,-0.189594,-0.131169,-0.349802,0.764763,0.068307,-0.505007,0.108207,0.194925,0.218530,-0.544089,0.190970,0.054941,-0.204179,0.043964,-0.037181,-0.168932,0.151688,-0.359992,0.066282,-0.124558,0.159380,-0.522153,0.457894,0.848926,-0.575964,-0.191064,0.072082,0.410322,-0.062683,-0.199375,-0.041602,0.100874,0.300248,0.158554,0.229771,-0.194671,0.160775,-0.008426,-0.234431,-0.866686,-0.183316,0.272975,0.401663,-0.375120,0.237377,0.013680,-0.155231,-0.002239,-0.287641,0.069151,-0.210973,0.563481,0.607860,-0.093595,0.213068,-0.281134,0.143397,0.297036,0.166142,-0.609796,0.549213,-0.331915,-0.425357,-0.228528,-0.181726,-0.253427,0.022406,0.155353,0.074966,0.071403,0.097560,-0.874334,0.147376,0.028244,-0.407916,-0.144359,-0.558237,-0.082788,-0.849661,0.085839,-0.119399,0.067454,0.144576,0.081896,-0.142934,0.786307,-0.486797,0.150300,0.286242,-0.107619,-0.465155,0.613561,0.135116,0.106467,-0.335667,-0.024866,0.120978,0.095063,0.174189,-0.113779,0.455845,-0.117548,-0.340502,-0.7