INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457191', '分手男女', '剧情', '盖瑞（文斯•沃恩 饰）在球场上遇见了布鲁克（詹妮弗•安妮斯顿 饰）并对她一见钟情。两人很快同居了。不久两人就在各种生活的琐碎事情中矛盾重重，艺术家气质的布鲁克看不惯盖瑞的不拘小节，矛盾再一次升级，布鲁克提出分手。由于房子是共同的财产，他们都没有搬离房子。布鲁克不断约会帅气的男孩，盖瑞也把屋子弄得乌烟瘴气，更带脱衣女郎回家，但彼此心中还是爱着对方。在朋友的劝解下，他们出售了房子，并要在两个星期之内搬走。凡事粗心的盖瑞终于在与朋友的聊天中得知了布鲁克的真实想法，当他想布鲁克剖白心意的时候，却遭到了布鲁克的拒绝……©豆瓣', '文斯·沃恩', '佩顿·里德', 6.5, 17975, 'tt0452594', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1600831532.jpg', 1.4, 10.4, 55.6, 26.3, 6.3, '0.426740,-0.062093,-0.758805,0.303386,-0.286602,-0.444561,0.890358,0.077273,-0.554906,-0.310704,-0.043378,0.741276,-0.330419,0.252561,0.140517,0.022144,-0.496033,-0.670346,0.177071,-0.148046,-0.121386,-0.641081,-0.029057,-0.367102,-0.125333,-0.155504,0.426436,-0.041564,-0.034628,0.310871,0.268789,0.011224,0.004654,0.512527,-0.228885,0.069046,0.118713,0.102933,-0.465327,0.007780,-0.050276,-0.162361,-0.237506,0.275795,0.285293,0.412772,0.388957,0.025399,-0.199902,0.456185,0.053083,0.068396,0.062655,0.155782,0.278523,-0.256012,0.463647,0.328879,-0.252402,-0.058498,0.047955,-0.005267,-0.420061,0.203147,0.027035,0.109867,-0.580284,0.713041,-0.003690,-0.061618,0.012311,-0.323813,-0.030950,0.259007,0.326722,0.419723,-0.113499,-0.042272,-0.535049,-0.043152,0.641019,0.145514,-0.045148,0.425870,-0.358616,-0.286966,-0.145551,-0.008496,-0.461754,-0.111163,0.348747,0.167533,-0.164713,0.277012,-0.681126,-0.075218,-0.152344,-0.094804,0.047689,-0.628418,0.136901,-0.647669,-0.217759,-0.403891,-0.566767,0.117388,0.020859,-0.020760,0.532438,-0.884062,0.130064,0.486679,0.434376,-0.571889,0.540137,0.269729,0.192473,-0.245076,0.170995,0.127609,0.051069,0.079809,0.386086,0.477194,0.135814,-0.086202,-0.444877,0.688242', '1308755', '3230121', '1292211', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457217', '哈利·波特与凤凰社', '奇幻', '逃过摄魂怪的追杀，通过魔法部的审查，哈利（丹尼尔·雷德克里夫）终于回到美丽的霍格沃兹。然而这个学期并不轻松，他不仅要完成魔法等级考试，还要应对夜晚的噩梦和黑魔法防御课老师乌姆里奇的打压。在好友的支持下，哈利秘密组建了邓不利多军团，与大家一起练习黑魔法防御术。噩梦中，哈利总是以伏地魔的视角出现，似乎他们之间有着某种神秘的联系。在邓不利多（迈克尔·刚本）的指示下，哈利向斯内普教授（阿伦·瑞克曼）学习封闭术，却鲜有成效。终于在一次噩梦的诱使下，哈利偏执的赶往魔法部营救小天狼星，却不想陷入伏地魔的圈套，引发凤凰社与食死徒之间的正面冲突。在混战中，小天狼星（加里·奥德曼）不幸遇难。究竟哈利与伏地魔（拉尔夫·费因斯）之间有着怎样的联系？在悲恸中，邓不利多为哈利揭开谜底，哈利还有更长、更艰难的路要走……©豆瓣', '丹尼尔·雷德克里夫', '大卫·叶茨', 8.5, 510958, 'tt0373889', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p443403700.jpg', 0.2, 1.1, 15.7, 42, 41, '0.222251,-0.125889,-0.411358,0.658816,0.171645,-0.204941,0.605652,-0.146037,-0.187940,-0.544853,0.104759,0.418596,-0.190136,0.417843,-0.031746,-0.233129,-0.588183,-0.683681,0.038351,-0.116521,-0.538475,-0.729835,-0.356714,-0.403338,-0.125071,-0.414100,0.496722,0.289097,-0.433981,0.020681,0.116232,0.281625,0.005564,0.502010,0.131696,-0.172613,0.219881,-0.191033,-0.289431,0.152343,0.261105,-0.074226,-0.296493,0.223019,0.274428,0.132300,0.552876,-0.540066,0.117355,0.063694,0.214234,-0.316013,-0.017391,0.057815,0.597032,-0.012125,0.026272,0.104975,0.032456,0.212967,-0.303519,0.038395,-0.661325,0.127230,0.173961,0.174255,-0.512387,0.242440,0.022502,0.372794,0.246403,-0.175993,-0.235397,0.646522,0.397601,0.129698,-0.118872,0.051811,-0.111852,-0.442902,0.533018,-0.153529,-0.408260,-0.003807,-0.471777,-0.383780,-0.103755,-0.024490,-0.116579,-0.184766,0.380866,-0.013698,0.250952,0.796165,-0.672207,-0.187361,-0.333855,0.189087,-0.225056,-0.321868,-0.097227,-0.978626,0.087139,-0.256922,-0.271446,-0.050741,0.136761,-0.343003,0.482270,-0.813528,0.359087,0.432675,0.238945,-0.139748,0.390451,0.138966,0.360791,-0.225878,-0.183651,0.305810,0.186701,0.561656,0.084609,0.318219,0.369258,0.147867,-0.317807,0.582550', '25723905', '2369613', '1306809', '20274039'