INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457218', '夏洛特的网', '喜剧', '小女孩阿芬家的母猪在春天生下了一窝11只小猪，母猪只有十个奶头，最瘦弱的一只小猪没奶吃，阿芬爸爸准备将其杀掉。阿芬救下了小猪，帮它取名韦宝，亲自喂养。随着小猪慢慢长大，阿芬不能再在家里养韦宝了，阿芬只好把韦宝送到隔壁舅舅的农场里继续饲养。韦宝天真烂漫，很快就以其热情、开朗的性格和农场里的动物成了好朋友。幸福快乐的时光很快过去，韦宝从其他动物口中得知春天出生的小猪圣诞节前就会被杀掉制熏肉。韦宝的好朋友蜘蛛莎莉承诺会让韦宝看到冬天的雪。在老鼠的帮助下，莎莉织出了各种各样神奇的字来形容韦宝，引来人们争相观看，韦宝最终能否看到冬天的雪？©豆瓣', '朱莉娅·罗伯茨', '盖瑞·温尼克', 8, 68456, 'tt0413895', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p581675614.jpg', 0.2, 1.4, 21.9, 50.6, 25.9, '0.185379,0.092960,-0.373221,0.283519,-0.314133,-0.046200,0.420840,0.229114,-0.378080,0.151379,-0.143563,0.509705,-0.078087,0.544894,0.060900,-0.060881,-0.291295,-0.259145,-0.217920,-0.066468,-0.560632,-0.090145,-0.135889,-0.161532,0.055178,-0.061343,0.364666,-0.209589,0.237051,0.384625,0.175196,-0.146011,-0.154707,0.256066,-0.582500,0.286367,-0.197204,-0.072046,-0.073067,0.436404,0.061468,0.053490,0.004037,-0.187325,0.090325,-0.019752,0.780842,-0.549534,-0.175943,-0.452393,0.239200,-0.078361,0.056948,0.163641,0.307489,-0.078039,0.513688,-0.226083,-0.474624,0.283698,-0.035743,-0.174794,-0.398328,0.249473,-0.052749,0.120123,-0.568113,0.294244,0.206151,0.211544,0.514069,-0.511966,0.099042,0.137842,-0.090160,0.695830,-0.238346,0.280706,-0.503161,0.033526,0.512183,-0.171548,-0.028443,0.366519,-0.022173,-0.366790,0.510584,-0.181767,0.012302,0.090379,0.402504,0.204548,-0.686028,0.028822,-0.706217,-0.188820,-0.101998,-0.154832,0.241512,-0.260066,-0.371270,-0.127794,0.039532,-0.099118,-0.223460,0.179539,0.062298,-0.098824,0.941599,-0.722855,0.267222,0.251828,0.349170,0.007981,0.364665,-0.399984,0.126101,-0.048065,0.112084,0.035496,0.211938,0.370283,0.506812,0.524824,0.031906,-0.173911,-0.369235,0.459348', '4181031', '1302661', '1457926', '2977870');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457219', '光荣之路', '剧情', '1965年是马丁·路德·金与黑豹党、披头士与越战、白人在篮球领域统治天下的时代。高中女子篮球教练唐·哈金斯（Josh Lucas 饰）接到德州西部大学的聘用，虽然提供的待遇不高——一家人只能暂住男生宿舍，董事会的资助也不足以招揽高水平运动员，但由于将要执教的是一支NCAA(美国大学联盟锦标赛）第一赛区的球队，哈金斯还是承接下来并马上同助手展开范围广泛的定位在黑人选手上的球员搜寻。教练组陆续找到了七位天赋优异的黑人球员，这些球员性格迥异，各有所长。在经历了一次热血对决之后，黑白球员很快打成一片，投入到哈金斯教练严酷的训练中去。球员偶尔的违规行为跟篮球理念的区别让教练与球员们逐渐成长着……终于迎来了赛季开始的时刻。德州西部队一路凯歌，面对种族主义者的暴力威胁、部分舆论的轻视，哈金斯教练决定和他的黑人球员们一起冲向光荣之路的顶点……©豆瓣', '乔什·卢卡斯', '詹姆斯·加特纳', 8.6, 46480, 'tt0385726', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1321134590.jpg', 0.1, 0.5, 11.4, 46.5, 41.4, '0.161269,-0.079635,-0.366796,0.698057,-0.202606,-0.394838,0.112945,0.105938,-0.611432,-0.003134,0.143149,0.719932,-0.218581,0.091635,0.529904,-0.722067,-0.036689,-1.037919,-0.346272,-0.139663,-0.386478,-0.625819,-0.108713,-0.268437,0.046496,-0.517487,1.048010,0.049769,-0.351994,0.636927,0.239479,0.178063,0.259387,0.184924,0.005116,-0.167797,0.311211,0.065722,-0.584628,0.219771,-0.109235,0.012238,-0.376262,-0.161963,0.482103,0.135212,0.639188,-0.278476,0.295528,-0.136174,0.329499,-0.012715,-0.056197,0.087786,0.656311,0.041699,0.228725,0.135754,0.423711,0.396365,-0.529944,-0.294286,-0.616412,-0.002083,0.134097,-0.044832,-0.566664,0.819299,-0.019615,0.086110,-0.016081,-0.132456,-0.086622,0.241157,0.066283,0.217270,-0.022339,-0.029287,-0.186419,0.187513,0.799247,0.083400,-0.401294,-0.277753,-0.404641,-0.568267,-0.250281,-0.476368,-0.480949,0.038020,0.318390,0.222302,0.095942,0.230301,-0.548317,0.357455,0.001036,-0.512353,0.108202,-0.455975,0.210121,-0.816762,0.224001,-0.244923,-0.035023,0.106220,-0.054329,0.048378,1.158889,-1.011848,-0.096732,0.679360,0.334531,-0.298147,0.657996,-0.132288,0.406630,-0.379814,-0.449324,0.215348,-0.049025,0.368476,-0.161553,0.679875,-0.325208,-0.357311,-0.134869,0.544877', '26615753', '1826173', '3811356', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457319', '一石二鸟', '喜剧', '远在贵州崇山峻岭间的金沙驿站破破烂烂，人烟罕至。驿丞石仪咆（吴宗宪 饰）和卜得辽（雪村 饰）、曾武了（吴孟达 饰）终日无所事事，或靠打猎或靠说冷笑话打发时光。这一日，仪表不凡的玉树（高虎 饰）和馨馨（林心如 饰）到达驿站，接着押解要犯的官差也随后抵达。各色人等相继云集驿站，石仪咆兴奋之余却不知杀机四伏。原来明朝嘉靖年间，奸相严嵩把持朝纲，陷害忠良，祸国殃民。时有御史张应龙（韩震华 饰）屡次参劾严嵩，反糟奸相憎恨，陷罪乌有，发配边陲。为庸除后患，严嵩密令心腹于此地杀害张应龙。张之女馨馨为救父亲跟随至此。一场大战在所难免……©豆瓣', '吴宗宪', '朱延平', 4.1, 18065, 'tt1239466', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363748602.jpg', 32.3, 38.9, 23.7, 3.6, 1.5, '-0.119385,-0.113936,-0.534695,0.336363,0.476863,0.035687,0.378838,0.506622,-0.448738,-0.162891,0.146216,0.247261,-0.258038,0.009899,0.175581,-0.394580,-0.052921,-0.371063,-0.061106,-0.415958,0.154728,-0.234734,-0.095811,-0.132172,-0.343910,-0.388221,0.124646,0.309171,0.017827,0.564360,0.050513,0.185653,-0.331519,0.248865,-0.180915,-0.200147,-0.077722,0.027836,-0.233383,-0.231254,-0.311448,-0.655336,-0.336307,-0.373917,-0.160202,0.114182,0.541263,-0.019200,0.020956,-0.047760,0.039281,-0.077019,-0.010097,0.002797,0.310261,-0.233501,0.103766,0.459014,-0.208554,-0.029091,0.165820,0.149044,-0.038328,-0.046432,0.019366,-0.020834,-0.051286,0.452373,-0.027282,-0.034159,-0.093622,-0.307908,0.204755,0.172444,-0.050867,0.255949,0.208313,0.071732,-0.363066,0.374448,0.373056,-0.124101,0.144800,-0.165053,0.309767,-0.364482,0.388090,-0.239383,-0.040588,-0.150836,0.215138,-0.143814,0.193808,0.128911,-0.285043,-0.183532,-0.316046,0.315736,-0.046460,0.190269,-0.332121,-0.246701,-0.043601,-0.359847,-0.002967,0.109882,0.459395,0.259834,0.052428,-0.230588,0.105255,0.031302,0.069262,-0.562750,0.348615,0.277960,0.213163,0.174981,-0.090299,-0.124573,0.473408,0.421825,0.074528,-0.066073,-0.432295,-0.246379,-0.326389,0.036381', '1306490', '1294011', '3606975', '1459054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457926', '哆啦A梦：大雄与风之使者', '剧情', '强烈的台风登陆日本，风雨过后，大雄遇到了一个捣蛋的小家伙。通过未来机器的检测，发现这竟是拥有智慧的小型台风，大雄为它起了一个可爱的名字——小风。为了让小风自由玩耍，大雄、哆啦A梦和静香带着小风来到一片神奇的土地。他们在此认识了御风而行的天吉和小纯，得知自己来到了风的部落，小伙伴们与这里的人很快成为朋友。但是，风之部落的和平正受到邪恶的威胁。无恶不作的岚族人揭开了族长乌岚达的封印，他的灵魂附在小夫的身上，率领其族人企图统治整个世界……©豆瓣', '大山信代', '芝山努', 8.5, 7901, 'tt0473474', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520703028.jpg', 0.2, 0.9, 15, 42.6, 41.2, '0.161328,0.331538,-0.688419,0.662597,-0.024723,0.178598,0.521037,0.139914,-0.353048,-0.202414,0.022263,0.885346,-0.110052,0.476497,0.186781,0.167377,-0.098420,-0.647961,-0.411804,-0.063862,-0.487509,-0.105606,-0.149883,-0.185933,-0.028341,-0.410161,0.521001,0.204121,-0.184769,0.348458,0.049076,0.160636,-0.294308,0.409084,-0.568083,0.092170,-0.213961,0.016975,-0.080866,0.149471,-0.358939,0.026479,-0.088332,0.231621,-0.041370,0.196495,0.856993,-0.808299,-0.342144,-0.380692,0.339843,-0.389136,0.081630,-0.250375,0.402128,-0.003428,0.167329,0.007168,0.081733,0.157335,-0.049724,-0.216268,-0.901847,0.190476,-0.036173,-0.055355,-0.372339,0.310924,0.053511,-0.024231,-0.071664,-0.137988,0.209310,0.388328,-0.181842,0.582614,-0.410239,0.413115,-0.371454,-0.372041,0.795757,-0.310303,-0.344877,0.176728,-0.241571,-0.330550,-0.074335,-0.241639,-0.230274,-0.224074,0.477034,0.137197,-0.129811,0.247595,-1.036392,0.031396,-0.195550,-0.121979,0.179642,-0.205075,-0.390377,-0.410060,-0.117764,-0.160051,-0.145841,0.331135,0.150283,-0.269424,1.068161,-0.949285,0.170977,0.599192,0.514766,-0.440198,0.380350,-0.407102,0.036045,-0.134603,-0.228987,0.210102,0.168261,0.434419,0.458167,0.435708,-0.122718,0.015778,-0.280908,0.217246', '24284209', '25774050', '4181031', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1457957', '哆啦A梦：大雄的宇宙小战争', '科幻', '匹里卡星的政权遭到了独裁将军吉尔莫亚（八名信夫 配音）发动的政变，大总统帕比（潘惠子 配音）被迫从匹里卡星逃了出来，误打误撞中降落到了地球。此时，大雄（小原乃梨子 配音）等人正在拍摄电影《宇宙小战争》，意外发现了逃难的帕比，交谈中得知帕比年仅10岁，而8岁就大学毕业了，大家也了解到了他的遭遇，决定帮助他，并同他成了好朋友。吉尔莫亚军队通过小型侦察机找到帕比的行踪，向大雄等人发起了攻击，他们捉了静香做人质。帕比为了不连累大家，最后向叛军投降了。帕比的爱犬胖胖（三ツ矢雄二 配音）通过自己的嗅觉找了帕比的位置，可惜来玩了一步，正好遇上了哆啦A梦等人，大家计划一要救回静香和帕比，一同向皮力卡星出发了，但在未知的星球里又将会有什么样的冒险等待着他们了……©豆瓣', '大山信代', '芝山努', 8.6, 5325, 'tt0313990', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520699109.jpg', 0.3, 0.8, 12.9, 42.7, 43.3, '0.119074,0.001698,-0.758307,0.356666,0.016851,-0.297948,0.361759,0.059449,-0.328061,-0.062442,0.044134,0.574391,-0.099433,0.094046,0.319340,0.282812,-0.493882,-0.591489,-0.002564,-0.157890,-0.515516,-0.366920,-0.298944,-0.318078,-0.049251,-0.243902,0.255930,-0.024053,-0.111118,0.199477,0.279612,0.035906,-0.057404,0.434456,-0.036307,0.372498,0.059501,-0.301143,-0.150802,0.421145,-0.169369,-0.263515,-0.320221,0.222336,0.249299,0.486234,0.634054,-0.306579,0.074757,-0.241891,0.023892,-0.417902,0.131183,0.066952,0.332622,0.004540,0.081007,-0.012527,-0.316486,0.103688,-0.137609,-0.032545,-0.663686,0.302189,-0.217204,0.173867,-0.551934,0.186285,-0.024588,-0.101791,0.320624,-0.326676,0.122788,0.571675,0.237759,0.080240,-0.066125,-0.022003,-0.423759,0.011811,0.597898,-0.094232,-0.184450,0.271659,0.239868,-0.375710,0.023490,-0.143350,-0.307981,0.021689,0.558095,0.045776,-0.262735,0.109045,-0.459921,-0.121782,-0.237994,-0.259624,0.001027,-0.331330,0.037950,-0.663112,0.006328,-0.161788,-0.280002,0.224593,0.029535,-0.152414,0.733888,-0.681793,-0.055820,0.581369,0.539975,-0.269953,0.589217,-0.142518,-0.034515,0.042910,0.379214,-0.133366,-0.116575,0.499677,0.585301,0.296682,0.113399,-0.330987,-0.386281,0.251252', '25928048', '1458900', '3755531', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458862', '妃子笑', '喜剧', '弘治七年，皇上在全国范围内大选妃子。来在同村的两位少女鸳鸯（黄婉君 饰）和朱朱（黄婉伶 饰）相助于危险的夜路，遂互称姐妹，共赴皇宫。对于少女们来说，如果成功当选皇妃，无论富贵贫贱都可飞上枝头当凤凰，自然竞争激烈，条件也很苛刻。不光自身条件要好，还要经过严格的培训与层层考试。但更加残酷其实是她们各自之间的勾心斗角、尔虞我诈。面对种种的困难与危险，鸳鸯与珠珠能否闯过难关？而面对这残酷的竞争，她们的友情是否会改变呢？©豆瓣', '萧正楠', '郑伟文', 5.5, 9538, 'tt0493655', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1621644404.jpg', 10, 26.7, 45.2, 13.2, 4.9, '0.114127,0.012653,-0.604460,0.641560,0.195584,-0.003254,0.555495,-0.075585,-0.627836,-0.038214,0.189427,0.253758,-0.174452,-0.006702,0.235747,-0.357405,-0.075717,-0.512037,0.081226,-0.195557,-0.412610,-0.488935,-0.135276,-0.349234,-0.385399,-0.031045,0.687397,0.283044,0.013090,0.230863,0.410473,0.110837,-0.260531,0.411162,-0.021317,-0.509145,-0.039603,0.484181,-0.794660,-0.018405,0.020072,-0.157107,-0.333464,-0.005940,0.518734,0.025842,0.330013,-0.628591,-0.359958,0.079513,0.396253,-0.076075,0.064029,0.533795,0.360610,-0.162847,0.401448,0.411069,0.127654,0.134998,-0.215128,-0.411384,-0.610160,0.140572,0.520696,-0.173155,-0.503592,0.283429,0.249429,-0.210756,-0.031002,-0.145982,-0.037955,0.588120,0.354398,0.314430,-0.440235,-0.075243,-0.386455,0.166434,0.984020,0.386431,-0.375241,0.012333,-0.203140,-0.683888,-0.142721,-0.418653,-0.412676,0.205409,0.129898,0.106637,0.085332,0.463939,-0.494893,0.135980,-0.053512,0.063069,0.024164,-0.524883,0.336643,-0.445176,-0.076837,-0.696389,-0.653141,0.221299,0.506019,-0.414328,0.882222,-0.963121,0.084601,0.196086,0.363637,-0.862237,0.662040,0.441105,0.579548,-0.145209,-0.388563,0.046814,-0.238996,0.024071,-0.178517,0.276757,0.095466,-0.004062,-0.015801,0.185043', '1293265', '25721544', '1949320', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458889', '哆啦A梦：大雄的恐龙', '剧情', '小夫（肝付兼太 配音）炫耀自己家的暴龙趾骨化石。大雄（小原乃梨子 配音）眼红并信口开河表要找大整架恐龙化石，否则便用鼻子吃意大利粉。于是，他便前往图书馆借了些有关恐龙化石的书籍。后来他在附近的断层挖到一枚恐龙蛋的化石，借了哆啦A梦（大山羡代 配音）的时光布还原得到一只双叶颈龙，并以叫声将之命名为皮助（横泽启子 配音）。很快大雄和它成为好朋友，但因它越长越大且被人发现，故大雄决定将他送回白垩纪时代。可是，后来却发现将它错送到上古的北美洲。于是，大雄一行人乘时光机再次回到恐龙时代，但途中被欲抢皮助的神秘人追击，时光机因而故障，使大家必须靠自己沿着古陆块回到日本。经过长时间的冒险，神秘人物再度出现希望获得皮助，原来是他来自未来的违法恐龙猎人（加藤精三 配音），要获得皮助卖钱，要大雄一行以交出皮助为条件，换取将他们用时光机送回家，大雄将会如何取舍，回到自己家呢……《大雄的恐龙》是藤子·F·不二雄的科幻漫画哆啦A梦中的第一部长篇漫画作品，也是第一部哆啦A梦的剧场版动画电影。', '大山信代', '福富博', 8.7, 8884, 'tt1147517', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2519543937.jpg', 0.2, 0.6, 12, 40.1, 47.2, '0.152171,0.104677,-0.311259,0.318708,0.120148,-0.247390,0.323461,0.001825,-0.354914,-0.123702,-0.126762,0.590839,-0.112613,0.109128,-0.196222,0.267139,-0.134603,-0.357594,0.045941,-0.060018,-0.230300,-0.126019,-0.123963,-0.065847,-0.057110,-0.133364,0.646968,-0.119907,-0.225242,0.112236,0.063215,0.220135,-0.178302,0.137920,-0.239378,0.102238,-0.298908,0.068342,-0.131259,0.312308,-0.075524,-0.073167,-0.023994,0.053119,0.028763,0.133430,0.640204,-0.430646,-0.294920,-0.096741,0.333077,-0.257934,-0.246747,-0.231745,0.136024,0.120800,0.037807,0.104834,-0.247071,0.340564,0.090164,-0.129463,-0.531913,-0.011994,-0.042786,0.051893,-0.481339,0.060357,-0.005799,0.044951,0.280286,-0.450117,0.272067,0.136734,0.451055,0.197426,-0.070117,0.163361,-0.168955,0.166029,0.522551,-0.180546,-0.046142,0.298389,0.300505,-0.464163,0.068835,-0.256587,-0.238207,0.137610,0.261059,0.220046,-0.199482,0.035915,-0.788953,-0.187071,-0.268045,-0.323823,0.222369,-0.191498,-0.120941,-0.323725,0.188619,-0.064325,-0.109668,-0.000554,0.289911,-0.478744,0.654995,-0.532890,0.239424,0.591055,0.164093,-0.138106,0.364889,-0.476643,-0.081421,-0.139675,0.154585,0.019757,0.313644,0.381238,0.183632,0.014646,0.053747,-0.323261,-0.489623,0.387576', '26290398', '26759820', '26839466', '2977870');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458890', '哆啦A梦：大雄的宇宙开拓史', '科幻', '大雄（小原乃梨子 配音）与哆啦A梦玩耍时意外发现，房间的塌塌米下方与旷野星上一艘太空船相连，太空船的主人叫罗布鲁（菅谷政子 配音）。大雄与哆啦A梦（大山信代 配音）阴差阳错地进到了这个星球，在旷野星上，引力比地球小，大雄成了大力士飞毛腿，成了旷野星的超人了。同时也结识了一批旷野星上的朋友，罗布鲁的妹妹克蕾姆（小山茉美 配音），还有跟哆啦A梦一样爱吃铜锣烧的江姆（杉山佳寿子 配音），全身覆毛的雌性动物，是罗布鲁的宠物。而罗布鲁的家人和邻居遭到了卡尔泰矿业公司驱赶，这个公司专门将星球上的人们赶走后，不顾星球的存亡，疯狂得开采星球上的资源，导致有许多星球已经不适合人居住了。为了不让罗布鲁的星球遭到破坏，大雄决定留在星球上与坏蛋斗争到底……©豆瓣', '大山信代', '西牧秀雄', 8.4, 7162, 'tt1147515', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2568834938.jpg', 0.3, 0.8, 15.4, 44.6, 38.9, '0.053035,0.025825,-0.724142,0.507665,0.206573,0.041308,0.424869,0.381541,-0.138837,0.100254,-0.374301,0.621839,-0.201683,0.251768,0.204010,0.261546,-0.319705,-0.480075,-0.360771,-0.196329,-0.695722,-0.373979,0.035308,-0.459245,-0.144653,-0.398421,0.536767,0.162867,-0.276544,0.057074,0.126622,0.341124,-0.147015,0.387064,-0.437408,0.213436,0.023538,0.153578,-0.131521,-0.003757,-0.453089,0.363224,0.135300,-0.068081,0.384605,0.132267,0.614236,-0.421675,0.060749,-0.404499,0.078490,-0.034988,0.271421,-0.424381,0.569085,-0.465888,0.047836,-0.185693,-0.071695,-0.104836,0.558433,-0.368564,-0.564905,0.076864,0.208636,-0.119584,-0.606397,0.123366,0.148155,0.046907,-0.067774,-0.060642,0.547206,0.358259,0.121016,0.345483,0.076820,-0.008731,-0.365382,0.136314,0.571297,0.141265,-0.150389,0.346742,-0.172486,-0.503441,-0.335189,-0.257104,-0.385219,-0.123314,0.258387,-0.220400,-0.347218,0.293343,-0.721815,0.002459,-0.115875,-0.365288,0.234420,-0.314061,-0.287550,-0.498014,0.182831,-0.267270,0.078441,0.307990,0.048204,0.043644,0.772956,-0.858928,0.139276,0.638031,0.406872,-0.107780,0.724282,-0.317679,-0.048598,-0.345326,0.154843,-0.121879,0.322787,0.390813,0.396399,0.175652,-0.105230,-0.007107,-0.444383,0.346238', '1438591', '1458894', '3755531', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458891', '哆啦A梦：大雄的大魔境', '科幻', '一天，胖虎（立壁和也 配音）、小夫（肝付兼太 配音）和大雄（小原乃梨子 配音）三人在空地讲着有关密境和魔境的事情，胖虎和小夫希望能去密境去探险，就拜托大雄去求哆啦A梦（大山羡代 配音）帮忙。回家后大雄开始求哆啦A梦，哆啦A梦面对大雄的“撒娇”没辙，于是拿出了道具“家用人 造卫星”来寻找密境。正找着不亦乐乎之际，妈妈叫大雄出去买东西，再回来路上，见到了一只流浪狗，而回想起妈妈不准收养流浪宠物的家规，准备放弃之时，却因为帮助妈妈找回钱包，破例收养了。而他真实身份是保弯湖王国的保弯湖108世的儿子——昆佗克王子（清水マリ 配音），因为邪恶大臣达保兰的篡权，被迫流放外出。昆佗克王子趁着他们找寻密境之际，将自己回家的路线假装成探险路线给了大雄，探险路上又将会发生什么有趣的事情了，昆佗克王子能夺回自己的王位吗……©豆瓣', '大山信代', '西牧秀雄', 8.6, 7120, 'tt4184350', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2568835835.jpg', 0.2, 0.8, 13.5, 42.1, 43.4, '0.074783,-0.096718,-0.268865,0.375732,0.180461,-0.409257,0.240985,0.081835,-0.213094,-0.331537,-0.292473,0.610119,0.148185,0.247487,0.305793,0.378295,-0.410817,-0.354489,0.165815,-0.042588,-0.348911,-0.186206,0.254078,-0.133462,-0.002449,-0.197779,0.365606,-0.120411,-0.133063,0.283440,0.169313,0.111476,-0.284404,0.353794,-0.233170,0.151364,-0.227650,0.235610,-0.322826,0.306098,0.156005,0.147288,-0.246630,0.155097,0.551046,0.080128,0.489460,-0.327258,0.001064,0.013847,0.265194,-0.174392,0.105488,-0.096321,0.139952,-0.017957,0.353773,0.132504,-0.068609,0.140205,0.146968,-0.217744,-0.435085,0.033092,-0.020950,0.006793,-0.536462,-0.041588,0.004549,0.145595,0.663177,-0.464682,0.442987,0.387237,0.252259,0.358068,-0.214177,-0.083693,-0.470713,0.227293,0.469034,-0.119088,0.471077,0.235433,0.355426,-0.262596,0.241762,-0.194801,-0.297854,0.108340,0.281493,-0.000541,-0.487237,0.222682,-0.486330,-0.398553,-0.012562,-0.240810,0.261385,-0.413059,-0.199762,-0.304717,0.429698,0.182040,0.049645,0.207772,0.110011,-0.224203,0.391273,-0.615105,0.289357,0.826652,0.294740,-0.441692,0.681648,-0.110007,0.021635,-0.254110,0.310636,-0.196788,0.180562,0.502224,0.280723,0.073497,0.168496,-0.209664,-0.544775,0.195696', '5339081', '1949005', '1292625', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458892', '哆啦A梦：大雄的海底鬼岩城', '科幻', '暑假临近，大家为露营地点的事而争执。大雄（小原乃梨子 配音）和静香（野村道子 配音）想去海滩，胖虎（立壁和也 配音）和小夫（肝付兼太 配音）则想去爬山。最后，在哆啦A梦（大山羡代 配音）的提议下决定去海底山探险。而到了海底，胖虎和小夫却想总想着去幽灵船寻宝，结果遇到了危险，大家也意外发现海底居然也居住着人类。进而发现亚特兰提斯和姆联邦这两个国家争相进行军备竞赛，得知亚特兰提斯预备发射鬼角弹的事，如果亚特兰提斯发射鬼角弹，那么全世界都会毁灭，因此为了阻止鬼角弹发射，大雄他们决定去亚特兰提斯的百慕大海域阻止这个阴谋。勇敢的少年们能拯救地球吗？本片是哆啦A梦剧场版系列的第四部。©豆瓣', '大山信代', '芝山努', 8.6, 7798, 'tt1147509', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2569026042.jpg', 0.2, 0.7, 12.9, 42.1, 44.1, '-0.045029,-0.205529,-0.644127,0.410724,0.376385,-0.140507,0.434709,0.033632,0.065209,-0.190272,-0.171779,0.678249,-0.065194,-0.019409,0.290239,0.239392,-0.646415,-0.234063,0.123142,-0.003207,-0.403139,-0.316503,-0.033499,-0.283650,0.117676,0.103762,0.494507,0.058856,-0.267899,0.259935,0.346212,0.293389,-0.298382,0.476729,-0.145239,0.014355,-0.084410,0.185189,-0.253541,0.277002,-0.269979,0.134798,-0.442178,0.300590,0.424019,0.319421,0.304047,-0.329025,-0.119485,-0.069956,0.050918,-0.310813,0.179407,-0.043578,0.358461,-0.250498,0.052282,0.086214,0.035480,0.222173,0.031592,-0.094786,-0.546173,0.162252,0.064460,-0.047599,-0.566215,-0.115619,0.121647,-0.222970,0.319392,-0.336641,0.115014,0.448834,0.404621,0.213624,-0.211139,0.043201,-0.320813,0.060533,0.707496,-0.048284,-0.031768,0.224041,0.369285,-0.414927,-0.253422,-0.035022,-0.293353,0.050358,0.104415,-0.039781,-0.316182,0.310834,-0.619980,-0.193257,-0.041423,-0.467403,-0.150095,-0.258271,-0.099570,-0.605251,0.271070,0.095533,-0.340642,0.215939,0.059642,-0.193916,0.489608,-0.614706,0.148205,0.844318,0.344532,-0.436538,0.544792,0.304641,-0.036444,-0.092972,0.018190,-0.084138,-0.158989,0.364167,0.110273,0.278265,0.320270,-0.459584,-0.427665,0.270393', '3285622', '3178770', '1306723', '1292849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458894', '哆啦A梦：大雄与铁人兵团', '科幻', '因为玩具机器人，大雄（小原乃梨子 配音）受到小夫（肝付兼太 配音）和胖虎（立壁和也 配音）的奚落，连哆啦A梦（大山のぶ代 配音）不愿帮他。为了寻找生气走掉的哆啦A梦，大雄通过任意门来到寒冷的北极，却在这里发现奇怪的机器人零件。在此之后，各式的零件源源不断从空中掉落至大雄的家中。由于零件过于巨大，为了不引起骚动，两个好友将机器运到镜面世界，并组装成巨大的机器人。他们兴奋地邀请静香（野村道子 配音）来镜面世界玩耍，偶然间发现机器人竟然装备有威力强大的武器。不久，一个名为莉露露（山本百合子 配音）的女孩出现在小镇上，她自称是机器人的主人。大雄他们热心地将镜面世界工具借给莉露露，却发现她在那里建立了毁灭地球的基地……©豆瓣', '大山信代', '芝山努', 8.6, 7123, 'tt1147528', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520700067.jpg', 0.2, 0.7, 12, 41.2, 45.8, '0.083266,0.158957,-0.726127,0.316188,-0.057088,-0.019977,0.749314,0.151838,-0.190030,-0.328129,0.173062,0.671970,-0.281265,0.051911,-0.188934,0.209145,-0.199044,-0.376057,-0.149384,-0.022263,-0.565976,-0.206677,0.052866,-0.546790,-0.099379,-0.471502,0.566608,-0.146106,-0.268071,0.161349,0.047706,0.180001,-0.256997,0.404740,-0.203584,-0.042357,-0.202552,0.165837,0.002806,0.111449,-0.589264,0.053557,-0.002242,0.051136,0.088833,0.105694,0.814591,-0.315425,-0.088879,-0.181040,0.272909,-0.081331,-0.040397,-0.521780,0.393226,0.066023,-0.091276,-0.244290,-0.195066,0.182358,0.312160,-0.289692,-0.589625,0.033429,-0.009952,0.064930,-0.331108,0.275078,-0.160057,-0.141380,0.113464,-0.371427,0.273870,0.025014,0.272469,0.439048,-0.313427,0.302815,-0.171899,0.049668,0.157848,0.037138,-0.178973,0.403264,-0.119647,-0.301602,-0.050906,-0.208902,-0.240783,-0.011928,0.224477,0.059415,-0.244504,0.126578,-0.779696,-0.066284,-0.157126,-0.156735,0.096497,-0.399513,-0.460847,-0.717474,0.213726,-0.120243,-0.150613,0.161098,-0.009713,-0.228622,0.865828,-0.839265,0.001541,0.580503,0.397026,0.115653,0.399649,-0.356051,-0.325466,-0.236278,-0.130418,-0.166958,0.131238,0.386161,0.394234,0.232002,-0.092835,-0.039608,-0.342823,0.237787', '3005387', '10174444', '1438591', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458895', '哆啦A梦：大雄与龙骑士', '科幻', '平凡的一天，大雄却感到无比心烦。先是与小夫争论恐龙还存在与否时落败，接着零分试卷又面临妈妈的搜查。为了藏匿积攒下来的试卷，大雄和哆啦A梦利用道具在后山挖了一个巨大的洞。大雄欣喜过望，于是和小伙伴们建立起一个地下理想王国。与此同时，小夫的心情则无比烦闷，他无数次看见恐龙，甚至在地洞里看过奔跑的恐龙群。不久，小夫神秘失踪。得知他可能困在地下，大雄、哆啦A梦、胖虎、静香他们决定前去营救好友。令小伙伴们意外的是，地洞竟然连接着一个奇异的世界，这里不仅有各种各样的恐龙，还有一个神秘的王国。小伙伴们受到地下王国的热情接待，并最终找到小夫。但偶然的机缘，他们得知地下王国正在进行一项神秘的计划……©豆瓣', '大山信代', '芝山努', 8.4, 6055, 'tt1147527', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2520700344.jpg', 0.2, 0.8, 15.3, 45.5, 38.2, '0.047137,-0.068322,-0.609208,0.566535,0.292869,-0.032020,0.678888,-0.033065,-0.422145,-0.347819,0.073628,0.623504,-0.341455,0.324892,-0.034644,-0.153910,-0.400567,-0.431275,-0.296676,-0.051318,-0.405582,-0.194593,-0.329092,-0.466205,0.001137,-0.125082,0.617572,0.156304,-0.165020,0.468119,0.076761,0.256157,-0.451066,0.384003,-0.248693,0.048406,0.108121,0.331149,-0.161555,0.023986,-0.250241,0.189411,-0.133755,0.178569,0.161860,0.164509,0.499733,-0.555787,-0.292299,-0.164280,0.200251,-0.137528,-0.244646,-0.016402,0.522367,0.061603,0.297945,-0.045443,-0.065450,-0.006038,0.088164,-0.076814,-0.826354,0.074022,0.240823,0.111175,-0.274345,0.197600,0.251653,0.041163,0.157712,-0.308810,0.139104,0.322895,0.286468,0.418262,-0.276762,0.250135,-0.153424,-0.123527,0.553230,-0.052811,0.045403,0.050110,0.028746,-0.475562,0.157207,0.144036,-0.204905,0.040142,0.398596,0.079715,-0.330246,0.198099,-0.778597,0.140303,-0.371225,-0.292840,-0.020982,-0.369373,-0.338675,-0.519785,0.206136,0.170252,-0.246333,0.346594,0.007967,-0.190469,0.647617,-0.608292,0.280179,0.500675,0.178370,-0.320297,0.379682,-0.045180,0.070357,-0.188479,-0.229058,0.209815,0.063656,0.275509,-0.024459,0.089566,-0.213299,-0.234985,-0.589925,0.284901', '25774050', '1308585', '25928048', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458896', '哆啦A梦：大雄的平行西游记', '科幻', '为了在新生欢迎会上表演话剧《西游记》，大雄班级举行的话剧的排练。大雄（小原乃梨子 配音）想当孙悟空，可是却只是村人甲。为了证明自己最像孙悟空，大雄用航时机来到中国唐朝，想见孙悟空，而且真的见到了“孙悟空”。后来大雄以哆啦A梦（大山信代 配音）的道具为赌注，证明孙悟空很像 大雄。大雄与他的朋友来到唐朝，却没有见到孙悟空。因此大雄用哆啦A梦的模拟游戏机假扮孙悟空，最后被识破。由于没有关好机器，游戏里的妖怪从游戏机里跑了出来。妖怪最后统治了世界，大雄他们也面临危险。 为了恢复历史，拯救玄奘法师，大雄、静香（野村道子 配音）、小夫（肝付兼太 配音）和刚田武（立壁和也 配音）假扮孙悟空等角色来保护玄奘法师，踏上了冒险之旅……故事改编自小说《西游记》。©豆瓣', '大山信代', '芝山努', 8, 8652, 'tt1147525', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2520700785.jpg', 0.4, 2.3, 24.5, 42.4, 30.5, '-0.059048,0.000853,-0.510705,0.376321,0.149898,-0.214214,0.345655,0.006981,-0.251567,-0.434686,0.050977,0.827306,-0.375296,0.040158,-0.157756,0.007311,-0.360628,-0.398097,-0.201579,-0.005221,-0.104732,-0.179127,0.145505,-0.014523,-0.166167,-0.015610,0.512427,-0.221441,-0.444355,0.235282,0.236189,0.017887,-0.056781,0.049696,-0.167793,0.164806,-0.210172,0.368144,-0.135882,0.206612,-0.128696,0.049684,-0.278791,0.179462,0.234373,0.106680,0.350407,-0.616513,-0.245766,-0.091757,0.221809,-0.226677,-0.305797,-0.304544,0.207335,-0.000875,0.350330,-0.039234,0.229526,-0.013278,-0.183196,-0.409815,-0.622630,0.341602,-0.026407,0.031927,-0.265788,0.176299,0.025680,-0.050147,0.212550,-0.151045,0.207453,0.171062,0.536982,0.289844,-0.032928,0.251117,-0.183868,0.310020,0.566679,-0.104280,0.152187,0.635232,0.166766,-0.339166,-0.040071,-0.211523,-0.148855,0.305982,0.123990,-0.286880,-0.355150,0.092057,-0.403468,-0.167764,-0.165608,0.133374,0.042431,-0.225031,-0.191099,-0.572324,0.165004,0.014552,0.044992,-0.070839,0.138499,-0.557756,0.903902,-0.928652,-0.035722,0.462803,0.145529,-0.244514,0.503927,-0.011494,-0.256803,-0.324900,0.055064,-0.030606,-0.137425,0.307736,0.359821,0.033997,-0.000083,-0.394964,-0.546346,0.353410', '27602116', '26711487', '1870681', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458897', '哆啦A梦：大雄的日本诞生', '科幻', '由于不堪忍受老师和妈妈的责骂，大雄决定实施第n次出走计划。与此同时，胖虎、小夫、静香也因为各种各样的原离家出走。小伙伴们凑在一起，但拥挤狭窄的现代都市没有他们的立锥之地。在哆啦A梦的帮助下，他们乘坐时光机来到7万年前的日本。当时这片土地上渺无人烟，绿草晴空，空气清新。小伙伴们展开想象，营造属于自己的快乐家园。偶然间，他们遇到从远古穿越时空来到现代的中国少年克克鲁。克克鲁生在爱好和平的光明族，他们这一族被凶恶残暴的黑暗族袭击，克克鲁则恰巧碰到时空乱流来到现代。大雄他们将克克鲁带到7万年前的日本，小伙伴们同情这个男孩的遭遇，决定帮助他打败黑暗族，拯救族人……©豆瓣', '大山信代', '芝山努', 8.5, 9453, 'tt1147511', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520700977.jpg', 0.2, 0.9, 13.1, 43.5, 42.3, '0.375870,0.230787,-0.767648,0.269555,0.062680,0.100858,0.593476,-0.093161,-0.151602,-0.402151,0.274011,0.617058,0.190738,0.320104,0.053768,-0.136921,-0.379910,-0.230889,-0.263840,0.146407,-0.234941,-0.010690,-0.005499,-0.235592,-0.003967,-0.327934,0.797994,0.224805,-0.509692,0.372489,-0.154036,0.410530,-0.432744,-0.027744,-0.484028,0.156912,-0.000082,0.364741,-0.476410,0.079345,-0.699610,0.117019,-0.050915,0.188089,0.000044,0.077185,0.709997,-0.464480,-0.352151,-0.044223,0.409684,-0.457929,-0.292359,0.011936,0.457602,-0.147414,0.190230,-0.059200,0.342103,-0.202122,-0.439878,-0.095573,-0.615574,0.209333,0.138927,-0.072877,-0.450478,0.185922,0.325563,0.066286,0.156166,-0.259415,0.290742,0.454113,0.192415,0.322997,-0.037392,0.183790,-0.241573,-0.084394,1.100616,-0.367282,-0.187307,-0.042764,-0.252899,-0.269280,0.171708,-0.265956,-0.511546,0.089071,0.245332,-0.100100,-0.269122,0.669574,-0.985667,0.227994,-0.216357,-0.292664,0.241377,-0.210620,-0.453494,-0.577132,-0.019203,-0.105267,-0.246567,0.325126,0.067036,-0.323868,0.822782,-0.736887,0.501731,0.385392,0.534964,-0.584605,0.677870,-0.081344,-0.015353,-0.118081,-0.062017,0.534266,0.215576,0.293765,-0.198786,0.035270,-0.263257,0.067189,-0.595588,0.232685', '26290398', '3214137', '4160441', '34822138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458898', '哆啦A梦：大雄与动物行星', '科幻', '大雄在睡梦中通过粉红色的雾走进一个动物王国，里面人人和平相处，科技发达，是真正的乌托邦！原来动物王国是在遥远的星球，而粉红色之雾是来自未来世界的随意气，是可以用来通往遥远的地方！哆啦A梦回到地球后，收到未来动物星球的求救消息，但随意气已经用完，他们该怎么办呢？在这个绿色的动物星球上，都是些爱好和平的动物们。但和动物星的平行星中，却住着贪婪的人类。于是战争又开始了……©豆瓣', '大山信代', '芝山努', 8.5, 6009, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520701139.jpg', 0.2, 0.8, 14.7, 43.1, 41.2, '0.331129,0.617496,-0.621688,0.631718,-0.040926,0.424850,0.642604,-0.145276,-0.432759,0.145507,-0.441009,0.630591,0.000027,0.303090,-0.202817,0.594918,-0.280857,-0.446266,-0.118445,-0.466869,-0.640378,-0.381971,-0.387509,-0.506489,0.091011,-0.541824,0.704480,0.445305,-0.036606,-0.040386,0.042112,0.229495,-0.365553,0.526487,-0.515541,-0.230274,-0.147604,0.078512,-0.209881,0.186928,-0.249165,0.257639,-0.086336,0.313734,-0.040811,0.112554,0.540524,-0.803924,0.013975,-0.290325,0.248564,-0.236067,-0.095710,-0.060234,0.717895,-0.394577,0.365361,-0.225532,0.199170,0.294829,0.145203,0.000440,-0.634619,-0.171059,-0.027435,0.454538,-0.526044,0.419574,0.147259,-0.280994,0.035233,-0.427723,0.614784,0.328125,0.156300,0.688823,-0.055164,-0.007439,-0.586867,-0.251296,0.774556,0.212993,-0.580143,0.353903,-0.465633,-0.712445,-0.187614,-0.242772,-0.479115,-0.135370,0.189155,-0.021834,-0.358139,0.292467,-1.060034,0.446867,0.220350,-0.461754,0.301380,-0.466763,-0.375314,-0.279616,0.204400,-0.577603,-0.289866,0.106783,0.144679,-0.291605,0.905893,-1.087091,0.216951,0.753977,0.185904,-0.398179,0.858518,-0.366703,-0.022776,-0.211469,-0.091166,0.262344,-0.022800,0.574415,0.113159,0.290440,0.013213,-0.185723,-0.259210,0.560444', '26290398', '1457926', '4160441', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458899', '哆啦A梦：大雄的阿拉伯之夜', '科幻', '哆啦A梦（大山信代 配音）拿出了一个可以进入连环画的鞋子，大家跳进连环画玩，可是静香（野村道子 配音）丢了一只鞋子，没有回来。而连环画被大雄的妈妈烧毁了。于是，大家必须去古代的阿拉伯，寻找童话与现实有衔接的地方，找寻静香的下落。静香是被奴隶贩子拐走了，而大家先是遭遇四十大盗，哆啦A梦的口袋也被偷了，然后大家在海上遭遇暴风雨，拣回一条命被冲到了大沙漠，只能在一望无际的沙漠里艰辛的寻找静香的下落。沙漠里，大家经受着常人无法忍受的困难，大雄严重中暑昏迷，小夫屡屡看到幻像。他们后来发现了一个黄金宫，国王是《一千零一夜》里的风云人物水手辛伯达，他有着大魔神，神灯，飞毯等许多不可思议的，只会出现在《一千零一夜》童话故事里的道具。他为什么会有这些东西？面对想抢夺黄金宫的奴隶贩子和四十大盗，大雄一行人将如何化险为夷……©豆瓣', '大山信代', '芝山努', 8.7, 6946, 'tt1147508', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2520701413.jpg', 0.1, 0.6, 11.2, 38.6, 49.4, '0.406565,-0.007691,-0.467555,0.414998,0.094421,-0.221585,0.715352,-0.069432,-0.450371,-0.268710,0.172414,0.823117,-0.267148,0.105577,-0.233258,0.437814,-0.270372,-0.520731,-0.264089,-0.113639,-0.479445,-0.138245,-0.192397,-0.146795,-0.124649,-0.016615,0.327402,0.089699,-0.199287,0.224057,0.323302,0.175383,-0.144431,0.283860,-0.473187,0.197205,-0.083078,-0.007113,0.081783,0.396597,-0.087323,-0.163143,-0.074778,0.135587,0.184393,0.076810,0.693399,-0.488901,-0.095180,0.189286,0.344143,-0.363429,-0.138324,0.065239,0.260341,-0.013187,0.041823,-0.069435,-0.194251,0.092381,0.139350,-0.175118,-0.549066,0.011961,0.010428,0.244920,-0.769466,0.246131,0.073834,-0.026176,0.285964,-0.274607,0.415202,0.205357,0.238165,0.243488,0.109007,-0.182121,-0.595856,0.251166,0.587996,-0.276116,0.007392,0.266844,0.014414,-0.339767,-0.005551,-0.233424,-0.309725,0.172375,0.613453,-0.159942,-0.532526,0.112490,-0.705228,0.164391,-0.317424,-0.486762,-0.119686,-0.186177,-0.511608,-0.180701,0.152450,-0.294351,-0.273978,0.230486,0.150583,-0.131299,0.722901,-0.517841,0.128432,0.619529,0.225547,-0.059473,0.588364,-0.492128,-0.191428,0.093194,0.215932,-0.055367,0.123159,0.481515,0.458951,0.280628,-0.142420,-0.132485,-0.631761,0.293721', '21619567', '1316560', '21350559',