INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458900', '哆啦A梦：大雄与云之国', '科幻', '大雄相信天空上有云之国，遭到好友们的嘲笑。哆啦A梦用未来的神奇工具和大雄共同打造属于自己的云之国，建好之后，好友们被邀请上来，大家度过一段快乐的时光。漂浮的云之国停在阿尔卑斯山上，大雄他们解救了一个神秘的男孩，不久后男孩失踪。正当他们四处寻找的时候，突然真正的云之国出现在他们面前。小伙伴们受到邀请，见识到了云之国高度发达的文明，深表惊奇。但是他们却被天上人软禁，无法回到地面。更进一步得知，天上人正在密谋一个“诺亚计划”，企图用洪水将为非作歹的人类从地球上抹去……©豆瓣', '大山信代', '芝山努', 8.8, 9293, 'tt1147523', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520701519.jpg', 0.1, 0.6, 10.8, 37.5, 51.1, '0.396741,0.224791,-0.974161,0.434793,0.113127,0.047673,0.639964,-0.013460,-0.396553,-0.119655,0.142567,0.842728,-0.257546,0.417215,0.153676,-0.041726,-0.509400,-0.739357,0.003303,-0.271275,-0.579181,-0.264309,-0.199173,-0.235463,-0.190458,-0.046403,0.444701,-0.029830,-0.091546,0.522579,0.123150,0.371181,-0.233728,0.449647,-0.526800,0.128918,0.033783,0.062299,-0.098349,0.236423,-0.314458,-0.193036,-0.204571,0.131661,-0.058485,0.116570,0.641969,-0.469311,-0.165054,-0.222864,0.139899,-0.458625,-0.043979,0.240701,0.341204,0.172052,-0.112718,-0.042489,-0.090476,-0.244881,-0.106865,-0.335305,-0.687033,0.041580,-0.019124,0.020145,-0.655828,0.337167,0.275346,-0.112622,0.089213,-0.516795,0.413888,0.437744,0.209755,0.297171,-0.127362,0.141387,-0.350839,-0.019377,0.977818,-0.074354,-0.206613,0.182029,0.081430,-0.165134,-0.199021,-0.158237,-0.433292,-0.071080,0.423870,0.198809,-0.395859,0.289830,-0.686635,0.089908,-0.347350,-0.333844,0.167449,-0.283540,-0.301195,-0.633510,-0.111061,-0.291876,-0.392662,0.254518,-0.098107,-0.322415,1.000112,-0.881911,0.231782,0.448692,0.457364,-0.253984,0.657464,-0.259381,-0.082748,-0.051024,-0.175565,0.031332,0.341079,0.412729,0.242433,0.177223,-0.341552,0.181759,-0.457740,0.239397', '1292219', '30162520', '1438591', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458901', '哆啦A梦：大雄与白金迷宫', '科幻', '春假来临，大雄的爸爸从午夜电视里放送的神秘广告中得知白金饭店的存在，那里环境优美，四季如春，远处的雪山则常年积雪，是度假的绝佳之选。但是这个胜地究竟在何方却无从得知，朋友们都认为大雄在吹牛。正当他倍感失望打算离家出走的时候，一个神秘的手提箱送到野比家。通过这个箱子，大雄和哆啦A梦来到了白金小岛。在这个罕无人迹全自动化的小岛上，大雄他们尽情玩耍，然而不久后哆啦A梦却离奇失踪。隐藏在这个小岛背后的秘密由此慢慢揭开……©豆瓣', '大山信代', '芝山努', 8.6, 6131, 'tt1147521', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520701737.jpg', 0.2, 0.8, 12.5, 40.7, 45.8, '0.232530,0.179357,-1.009598,0.437305,-0.042463,0.037688,0.543572,0.059189,-0.362380,-0.549029,0.117724,0.673146,-0.198716,0.490295,0.132282,0.316098,-0.227758,-0.495656,-0.133222,-0.441841,-0.460485,-0.189403,-0.422073,-0.046574,-0.049460,0.290544,0.510756,0.192906,-0.056378,0.518651,0.240226,0.221826,-0.475302,0.428145,-0.526939,-0.053116,0.119561,0.234184,-0.181741,0.173113,-0.325818,-0.164208,-0.071784,0.085528,0.261048,0.249691,0.575894,-0.341795,-0.333892,0.342206,0.294528,-0.264420,-0.151396,-0.028279,0.465688,-0.222587,0.067034,-0.101529,-0.297739,0.064590,-0.055028,-0.100505,-0.573505,-0.013842,0.092812,0.180033,-0.375692,0.355953,0.021795,-0.316127,0.099773,-0.254234,0.405667,0.249398,-0.026000,0.413580,-0.062540,0.051781,-0.496909,-0.053825,0.393562,0.123847,0.030709,0.401578,0.083789,-0.214022,0.153926,0.023005,-0.293326,-0.090291,0.252384,0.041426,-0.471711,0.015866,-0.642714,0.122859,0.204380,-0.126806,0.046870,-0.131313,-0.621541,-0.572049,-0.029428,-0.226613,-0.022184,0.123810,-0.222299,-0.141911,0.599439,-0.857275,0.426753,0.511774,0.094939,0.005165,0.644598,0.087129,0.108410,-0.158754,-0.202639,0.140068,0.218117,0.447235,-0.111416,0.240977,-0.124954,-0.409100,-0.949365,0.395410', '1307755', '1438591', '1293019', '3053397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458902', '哆啦A梦：大雄与梦幻三剑士', '科幻', '现实生活中，大雄（小原乃梨子 配音）经常受到老师和妈妈的责骂，还常被小夫（肝付兼太 配音）、胖虎（立壁和也 配音）欺负。他无时无刻不在梦想成为胆识过人、实力强大的超级英雄。为了帮心情低落的大雄一圆英雄梦，哆啦A梦（大山のぶ代 配音）拿出造梦机器。经过一番挑选，大雄鬼使神差地选择了《梦幻三剑士》的剧情。在精灵西露可（山本道子 配音）的引领下，大雄来到了梦中的亚米鲁曼王国。在这里，他被称为银剑客诺比尼亚，宿命中将要推翻妖灵大帝奥特罗姆对亚米鲁曼王国的统治，他还遇到小夫和胖虎模样的剑客斯内密斯、贾托斯。他们联手向妖灵军团发起冲击，而在这一过程中，现实和梦境的界限渐渐混淆……©豆瓣', '大山信代', '芝山努', 8.7, 8011, 'tt1147524', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520701848.jpg', 0.2, 0.7, 12.6, 38.5, 48, '0.020454,0.171520,-0.447508,0.588743,0.193612,-0.296086,0.565549,0.101935,-0.226944,-0.338458,0.136997,0.827002,-0.240641,0.162342,0.392522,-0.051743,-0.315163,-0.535784,-0.257958,0.123720,-0.265931,-0.307279,-0.006298,-0.096904,-0.154504,-0.300871,0.633605,-0.035413,-0.415548,0.087486,0.187924,0.419258,-0.159460,0.063389,-0.106747,0.193910,0.098804,-0.026245,-0.191949,0.230230,-0.298987,0.048266,-0.204687,0.335763,0.125975,0.034230,0.416254,-0.629592,0.094908,-0.218180,0.171822,-0.384164,-0.105034,-0.214540,0.327343,-0.122365,0.268628,0.033680,0.101964,-0.028302,-0.033397,-0.392028,-0.805045,0.042706,0.224132,0.101627,-0.447975,0.160133,0.064911,-0.061446,0.294934,-0.098368,-0.019201,0.275695,0.527616,0.420094,-0.125385,0.077578,-0.266198,0.134745,0.621791,0.126788,-0.225508,0.168538,0.071947,-0.506206,-0.296152,-0.323828,-0.468306,-0.096162,0.221641,-0.033867,-0.065422,0.654550,-0.658597,-0.001894,-0.200674,-0.043461,-0.108349,-0.297608,-0.206189,-0.394444,0.076804,-0.368253,-0.062280,0.166368,0.269590,-0.279780,0.687334,-0.910345,0.239976,0.407536,0.403883,0.142900,0.440161,0.021524,-0.086652,-0.122152,-0.013729,0.007929,0.161082,0.171867,0.341001,0.241432,-0.161099,-0.051368,-0.420011,0.398419', '26759819', '1793491', '1420088', '3592853');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458903', '哆啦A梦：大雄的创世日记', '科幻', '暑假再次来临，然而大雄却愁眉苦脸，提不起兴趣。原来老师放假前布置了一个作业，让同学们自选课题，进行自由研究。眼看小夫、静香甚至胖虎都找到了研究题目，大雄惟有求助好朋友哆啦A梦。哆啦A梦拿出未来世界的“创世组件”，它就如同养成游戏一般，通过操作者自己动手，模仿宇宙诞生的全过程。凭借哆啦A梦的帮助，大雄着实体验了一把当上帝的感觉。不过创造宇宙也不是什么简单事，经过两个好朋友细心观察和照看，他们的微缩宇宙终于形成，而且创造出与地球类似的星球。在适宜的条件下，生命开始繁衍。最终静香等人也加入进来，和大雄一同经历生命进化的精彩而刺激的过程……©豆瓣', '大山信代', '芝山努', 8.5, 6812, 'tt1147512', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520701997.jpg', 0.2, 0.9, 13.9, 43.2, 41.8, '-0.083008,0.079697,-0.388292,0.312762,-0.064223,-0.175318,0.202951,-0.129657,-0.129912,-0.336606,-0.223634,0.431936,-0.255875,0.109281,0.083766,-0.018560,-0.433607,-0.616508,-0.009623,0.233630,-0.564416,-0.352914,-0.047909,-0.291680,0.152292,-0.343932,0.516298,-0.188990,-0.205073,0.264574,-0.150598,0.099363,-0.149258,0.306760,-0.233210,-0.164525,0.013503,0.561738,-0.538888,0.102379,-0.211771,0.308411,-0.195672,0.099484,0.240593,0.016170,0.396781,-0.562755,-0.448133,-0.231897,0.378287,-0.158057,-0.239662,-0.330594,0.099867,0.414295,0.178318,-0.107514,0.188945,0.071654,-0.222072,-0.232826,-1.008382,0.035640,0.268486,-0.265817,-0.220843,0.059077,0.311354,-0.107667,0.124325,-0.085080,0.276515,0.462739,0.614833,0.354197,-0.232379,0.125437,-0.155772,0.080646,0.422543,-0.272072,-0.409262,0.677384,-0.008529,-0.445267,-0.138471,-0.005164,-0.084055,0.225779,-0.278181,0.220444,-0.338488,0.144705,-0.633588,-0.033133,-0.012941,-0.283925,0.133751,-0.440420,-0.142468,-0.463112,-0.041627,0.215675,-0.368842,0.071827,0.092144,-0.517773,0.884064,-0.681970,0.282565,0.468257,0.274570,-0.410000,0.652779,-0.088657,-0.011679,-0.575087,0.113231,0.026709,-0.101084,0.278504,0.113253,0.244891,0.054384,0.073882,-0.578558,0.582656', '27602116', '6844861', '24284209', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458904', '哆啦A梦：大雄与银河超特急', '科幻', '在空地上，小夫（肝付兼太 配音）向大家炫耀现在最畅销的神秘火车的车票，胖虎（立壁和也 配音）和静香（野村道子 配音）恳求小夫也带他们去。这时，大雄（小原乃梨子 配音）急匆匆跑了过来，哆啦A梦（大山信代 配音）已经三天没回家，小夫和胖虎在一旁幸灾乐祸的笑着。晚上，哆啦A梦回来了，原来这三天他跑到了22世纪去买银河列车的车票。第二天晚上，银河列车在后山停站了，大雄和哆啦A梦开始了他们的银河之旅，车长（伊仓一恵 配音）总是笑嘻嘻，很有礼貌。另一边，神秘的生命体降落在了后山，是来自宇宙的寄居物，寄居物将自己附在人类的身体上，来操纵人的大脑，他们的目的是将整个地球毁灭掉。在车上奇奇怪怪的事情发生不断，大雄在车厢外看到了一个忍者，小夫说看见了海盗，胖虎则看见了恐龙。哆啦A梦告诉大雄他们出现了一伙“神秘黑色影团”。遭到黑色影团的袭击后，列车在一颗行星上停下了，而冒险这才刚刚开始……', '大山信代', '芝山努', 8.6, 5837, 'tt1147522', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520702177.jpg', 0.2, 0.8, 12.9, 39.5, 46.6, '0.281542,0.088219,-0.623346,0.324405,0.044266,-0.195008,0.807074,0.203197,-0.218721,-0.072016,0.076614,0.761219,-0.347973,0.053076,0.212849,0.360385,-0.426970,-0.372403,-0.177018,-0.207520,-0.695365,-0.239293,0.254627,-0.064735,0.063895,-0.008361,0.174277,-0.061148,-0.064213,0.576120,0.272806,0.082146,-0.251798,0.400423,-0.483719,0.219750,-0.126123,0.121524,0.143275,0.142501,-0.164515,-0.272463,-0.110824,0.070244,0.117609,0.044953,0.582113,-0.176503,-0.073292,0.086659,0.142450,-0.311489,-0.106324,-0.146007,0.537127,-0.064296,0.007791,-0.177955,-0.088316,0.060542,0.000189,0.095447,-0.525852,0.083246,-0.436423,0.245047,-0.583599,0.447593,0.114541,-0.193485,0.481426,-0.465502,0.487406,0.296173,-0.093366,0.267191,-0.050439,0.048295,-0.467333,0.098596,0.489131,0.107832,0.101803,0.483840,0.204457,-0.390421,-0.226334,0.115799,-0.246060,-0.169100,0.375249,-0.061379,-0.442650,-0.014266,-0.683644,0.076769,0.225182,-0.466433,-0.143564,-0.272451,-0.384567,-0.491788,0.199186,-0.341246,-0.119364,0.416060,-0.109958,-0.054076,0.618515,-0.802476,0.164726,0.750924,0.389427,0.120544,0.704753,-0.235539,-0.135585,-0.099390,0.319851,-0.237229,0.035571,0.813990,0.482076,0.526764,-0.123207,0.029951,-0.560090,0.355649', '3055049', '1297347', '1316560', '3044878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458906', '哆啦A梦：大雄的南海大冒险', '科幻', '又一个暑假到来，大雄、静香、胖虎和小夫组成一个小组，共同进行海洋研究。在图书馆查资料时，大雄被《金银岛》的精彩故事所吸引，竟突发奇想打算出海寻找宝藏。适值此时，南太平洋海域传来发现宝藏的消息，哆啦A梦经不住大雄的软磨硬泡，同意展开这次寻宝大冒险。小伙伴们相继聚到一起，将目标锁定在加勒比海域一个名叫多摩斯的小岛上。他们的旅程原本充满乐趣，但是意外很快便发生。小伙伴们遭遇时空错乱，阴差阳错来到了17世纪。大雄被浪头冲走，下落不明。哆啦A梦等人被一艘海盗船救下，却弄丢了一次元空间袋。海盗船船长吉德正准备前往金银岛寻找失踪的哥哥和侄子。哆啦A梦他们随船前往，殊不知更大的冒险即将到来……©豆瓣', '大山信代', '芝山努', 8.3, 5366, 'tt1147519', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520702517.jpg', 0.2, 1.8, 17, 44.9, 36.1, '0.016093,-0.072640,-0.572632,0.273531,0.180909,-0.050844,0.532028,-0.031626,-0.429635,-0.120597,-0.191416,0.683638,-0.375996,0.099643,0.291485,0.093185,-0.504643,-0.357768,-0.013253,-0.010449,-0.458480,-0.323027,0.013578,-0.109905,0.212932,-0.220804,0.521513,0.128965,-0.059119,0.499175,0.172738,0.286289,-0.686145,0.573231,-0.255993,0.197040,0.242388,0.138451,-0.267859,0.252066,-0.510665,0.148703,-0.112088,-0.019001,0.134295,-0.050586,0.853066,-0.166257,-0.168359,-0.086307,0.094089,-0.265107,-0.122733,-0.344807,0.319819,0.179456,0.128680,-0.016747,0.001228,-0.007380,0.038445,-0.289630,-0.429213,0.310629,0.301376,-0.058805,-0.192432,-0.118109,0.100421,0.120957,0.166913,-0.256025,0.374974,0.696763,0.507411,0.103525,-0.179854,0.210084,-0.170123,0.049085,0.813433,-0.366024,0.246604,0.243636,0.281327,-0.196762,0.117399,0.171867,0.017746,0.242289,0.527106,0.103471,-0.413316,0.236721,-0.657309,-0.090542,-0.295498,-0.569698,0.033814,-0.336887,-0.463831,-0.698786,0.176740,0.340822,-0.047699,0.408203,-0.063819,-0.042740,0.610429,-0.396093,0.405621,0.710351,0.112698,-0.151942,0.631118,-0.217606,0.029501,-0.386188,0.373115,-0.019170,0.096806,0.313140,0.158726,0.136321,-0.257986,-0.052290,-0.601997,0.131571', '27069070', '3147969', '2159244', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458907', '哆啦A梦：大雄的宇宙漂流记', '科幻', '由“拉格那母星”生存下来的人与其他漂流在宇宙中的人组成“银河漂流舰队”，为了找寻适合生存的星球，派遣出“宇宙少年骑士团”四处寻找。李昂（白石冬美 配音）等四人被派到太阳系而发现了地球，无意间将正在“星际大奇航”游戏中的胖虎与小夫带进所搭乘的太空船中离开了地球。哆啦A梦与大雄、静香为了救出他们，乘坐“宇宙救护船”追了下去。但是在途中因为空间跳跃时遭到强力电磁波击中，导致太空船损毁。幸而李昂的太空船亦在相同地方也是因为跳跃装置故障而停滞，哆啦A梦等人因此而进入了李昂的太空船，恰巧与胖虎和小夫相遇。当李昂一行人回到了“银河漂流舰队”前，发现与原先舰队中多出了以李昂的父亲李贝尔特（有本钦隆 配音）为首的“独立军”，这个独立军的目的就是要以武力侵略适合生存的星球，他们经由派出去的间谍佛蕾亚得知了地球的情报，并且计划要进攻地球，大雄一行人将如何阻止“独立军”，从而拯救地球呢……本片为纪念哆啦A梦进入电影电视第20周年，同时是哆啦A梦剧场版系列第19部的作品。', '大山信代', '芝山努', 8.4, 5185, 'tt1147514', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520702618.jpg', 0.2, 1.1, 15.8, 44, 38.9, '0.053787,0.260923,-0.819985,0.645141,0.117266,-0.159616,0.467638,0.074820,-0.447093,-0.114573,0.001114,0.679422,0.158971,-0.057703,0.371564,0.167591,-0.397259,-0.518404,-0.287506,-0.278445,-0.564436,-0.368224,-0.052782,-0.291724,0.076412,-0.508705,0.754291,0.224348,-0.285018,0.298568,-0.049339,0.378099,-0.459196,0.438423,-0.106856,0.046985,-0.025213,0.028942,-0.410343,0.409173,-0.460811,-0.016001,-0.069769,-0.030584,-0.040657,0.223726,0.892784,-0.495687,0.120122,-0.283789,0.046144,-0.298910,-0.095430,-0.375689,0.413874,0.021248,-0.028771,0.053602,0.043942,0.418637,-0.095316,-0.075320,-0.781828,-0.078012,0.121333,-0.108675,-0.547769,0.138260,-0.231072,-0.164461,0.191678,-0.172789,0.461192,0.692005,0.537037,0.220685,-0.132395,0.126978,-0.353123,0.069390,0.565597,0.043319,-0.338961,0.293546,0.066904,-0.484560,-0.234871,-0.265272,-0.107420,0.034267,0.219457,0.094395,-0.113435,0.316308,-0.762753,0.076270,-0.178670,-0.487232,0.033499,-0.388412,-0.229051,-0.737047,0.234983,0.001745,0.081476,0.407680,-0.026874,-0.046661,0.574976,-0.803460,0.259951,0.745295,0.412932,-0.423133,0.733262,-0.100607,0.132244,-0.327039,0.312510,-0.026764,0.073915,0.571997,-0.035700,0.136477,-0.200424,-0.072671,-0.597962,0.194848', '25774050', '1438591', '25928048', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458908', '哆啦A梦：大雄的太阳王传说', '科幻', '在一次偶然的情况下，大雄（小原乃梨子 配音）与多啦A梦（大山羡代 配音）穿过秘密通道时空圈，闯进一个森林中古代文明的国度——玛雅王国，他们遇上跟大雄长得一模一样的迪奥（绪方惠美 配音），迪奥是玛雅王国的王子。迪奥王子的母亲中了魔女娜汀拉（唐泽润 配音）的诅咒，长眠不醒。为了救母亲，迪奥王子一定要打败娜汀拉。因此在森林中修炼。迪奥王子从大雄口中得知现代日本的事，便对日本产生兴趣，所以迪奥便希望与大雄转换身份，到日本修炼。大雄便成为了王子；王子就成了大雄，各自展开不一样的生活，最后迪奥在日本认识了技安等人，他们一起去对抗娜汀拉，究竟他们能否打败娜汀拉救迪奥的母亲……本片是为了纪念哆啦A梦诞生30周年而制作的，是哆啦A梦电影系列第21部作品。©豆瓣', '大山信代', '芝山努', 8.5, 9031, 'tt1147513', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520702689.jpg', 0.2, 0.7, 14.1, 43.6, 41.4, '-0.096221,-0.138189,-0.192172,0.541677,0.205824,-0.148344,0.445458,-0.134509,-0.121304,-0.241393,0.169626,0.763968,-0.061477,0.329361,0.285491,0.507755,-0.785866,-0.563306,0.090152,-0.148677,-0.333177,-0.340060,0.046459,-0.255740,-0.008861,-0.448403,0.678126,-0.236097,-0.407374,0.212454,0.173116,0.210541,-0.372457,0.263885,0.068218,0.267531,0.219896,-0.044381,-0.385135,0.458588,-0.235600,0.167570,-0.145233,0.279334,0.393119,0.054241,0.572923,-0.748234,0.410238,-0.185951,0.344119,-0.366638,0.004314,-0.243992,0.232934,-0.334518,0.437284,0.198446,0.021028,-0.203249,0.021006,-0.304154,-0.637881,0.334715,0.265489,-0.054521,-0.406658,0.018239,-0.005365,-0.068235,0.474444,-0.127179,0.247507,0.321085,0.537989,0.171918,-0.054010,0.070364,-0.279913,-0.050169,0.614473,-0.071896,0.089926,0.335722,-0.021427,-0.627663,-0.377716,-0.118756,-0.263166,0.074975,0.130884,-0.143887,-0.096616,0.420699,-0.454789,-0.346520,-0.326254,-0.049829,0.353743,-0.353164,-0.068003,-0.386978,0.063504,-0.182006,0.007001,-0.008558,0.204582,-0.225593,0.533930,-0.675426,0.229646,0.648201,0.385139,-0.148219,0.615517,-0.042838,-0.023527,-0.230047,0.237081,0.148236,-0.026074,0.097196,0.174054,0.294300,0.111364,0.103457,-0.402254,0.418871', '26759819', '1458902', '3592853', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458909', '哆啦A梦：大雄与机器人王国', '科幻', '大雄（小原乃梨子 配音）为了拥有跟小夫（肝付兼太 配音）一样的宠物机器狗，擅自从哆啦A梦（大山信代 配音）的空间袋订了很多机器人。没想到却将另一个星球的波克（桑岛法子 配音）也牵连进来。由于波克严重受损，只有把他带回去他原来的世界，才能得救。于是大雄一行人决定护送这个孩子回去，后来他们遇到了机器人医生查贝克博士（穂积隆信 配音）。原来这个机器王国本来是人类跟机器人和平共处的世界，但是在艾德姆国王因拯救机器人，而身亡后，继位的珍娜女王（新山千春 配音）由于打击过大，于是把机器人当做奴隶并把他们变成只听从人类的忠实道具来使唤。这主要也是因为珍娜女王听信邪恶司令官铁斯塔（森山周一郎 配音）的话，下令改造机器人。铁斯塔一开始就打算利用珍娜，目的是要夺取这个国家。在大雄等人的协助下，人类与机器人在机器王国能回到过去的和平吗……©豆瓣', '大山信代', '芝山努', 8.3, 5395, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2520702937.jpg', 0.4, 1.2, 18.2, 42.7, 37.5, '0.099979,0.143454,-0.452074,0.294447,-0.304807,-0.133988,0.413737,0.129134,-0.336810,-0.302621,0.015551,0.732167,0.120749,-0.163533,0.094964,0.102810,-0.448214,-0.147443,-0.192001,-0.083353,-0.426500,-0.520091,0.209884,-0.455697,0.008238,-0.432787,0.606139,-0.316225,-0.224583,0.086058,0.232082,0.236093,-0.074648,0.176665,0.008101,0.102518,-0.000656,-0.166524,-0.186050,0.217538,-0.185642,0.288358,0.035054,0.262074,0.061149,0.098239,0.492909,-0.570664,-0.061514,-0.387615,0.128204,-0.371603,-0.028270,-0.211592,0.286162,-0.111813,0.039739,0.145792,-0.076112,0.157884,0.195978,-0.120894,-0.876499,0.063851,-0.037097,-0.043154,-0.354425,0.129784,-0.085307,-0.012169,0.042289,-0.268674,0.311679,0.471104,0.387835,0.370070,-0.229027,0.185569,-0.369963,0.106558,0.496398,-0.129098,-0.274186,0.318405,0.096942,-0.577307,-0.134705,-0.261223,-0.343526,0.012565,0.133559,0.009514,-0.422494,0.093899,-0.605924,-0.118889,-0.411138,-0.157147,0.189204,-0.479752,-0.072500,-0.405427,0.364973,0.045196,-0.018709,0.243902,0.295294,-0.253225,0.790611,-0.726536,0.222713,0.682379,0.378235,-0.453319,0.312709,-0.039126,-0.016575,-0.304604,0.009719,-0.019016,0.353571,0.468995,0.340747,0.142459,0.161496,-0.345930,-0.409547,0.280922', '24284209', '3769423', '27009869', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1458910', '哆啦A梦：大雄的猫狗时空传', '科幻', '平凡的一天，大雄偶然邂逅一条机灵可爱的小狗。小狗对他分外依恋，大雄无奈之下，只得拜托哆啦A梦想办法收养。与此同时，周围被丢弃的小猫小狗越来越多，小伙伴们忧心忡忡，甚至在后山也找不到小动物们借以安身立命之所。万般无奈之下，大雄他们将小动物带到连恐龙都尚未诞生的史前时代，利用进化退化枪促成动物们进化。次日，小伙伴们按照约定前去看望小动物，结果在时空隧道中遭到乱流。来到了比前一天万一千年的时代。此时，猫狗国已空前繁荣，他们在这里结识了小八等一种好友。不久得知地球将遭到陨石的撞击，而猫狗国内部也在酝酿着一个阴谋。新的冒险就此展开……本片为哆啦A梦剧场版25周年纪念作品。©豆瓣', '大山信代', '芝山努', 8.6, 9962, 'tt1147516', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2520703421.jpg', 0.2, 0.7, 13.8, 40.3, 44.9, '-0.008621,-0.033718,-0.754554,0.304816,0.134609,0.170432,0.448070,-0.085875,-0.328633,-0.191323,0.067364,0.694787,-0.311296,0.397436,-0.099526,-0.411964,-0.090690,-0.405158,-0.208196,-0.086672,-0.269557,-0.126026,-0.231491,-0.112238,-0.154944,-0.198356,0.508698,-0.007530,-0.089820,0.478528,0.092208,0.148876,-0.431926,0.174321,-0.384635,-0.002220,0.004608,0.176452,-0.008601,-0.015437,-0.212676,0.084782,-0.059557,-0.010972,-0.001049,-0.001842,0.839285,-0.900071,-0.347841,-0.585831,0.247201,-0.142782,-0.058203,0.119467,0.503308,0.021889,0.341105,-0.143361,-0.056304,0.295260,0.065962,-0.187049,-0.519264,0.213493,-0.079359,-0.089955,-0.445943,0.017384,0.365960,-0.033344,0.176166,-0.515341,0.142450,0.314302,0.122905,0.230193,-0.212604,0.185761,-0.326335,-0.111036,0.621808,-0.058245,-0.192550,0.294712,-0.088874,-0.287202,0.014718,-0.177716,-0.279443,-0.033045,0.448255,0.090563,-0.507766,0.440900,-0.956089,0.096319,-0.284248,-0.122187,-0.052536,-0.207165,-0.228219,-0.481549,0.254259,0.090279,0.067093,0.350231,0.248448,-0.262140,0.835276,-0.672173,0.345946,0.391373,0.365744,-0.350324,0.449889,-0.328086,0.102759,-0.146160,0.110878,0.168091,0.144429,0.329892,0.424797,0.125347,-0.244245,-0.186424,-0.635191,0.357456', '1457926', '4181031', '4160441', '1438591');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1459054', '龙门客栈', '动作', '明朝中叶，宦官当权，兵部尚书于谦遭陷害入狱，满门抄斩，只剩下一儿一女被押送塞外龙门充军。东厂太监曹少钦（白鹰 饰）意欲斩草除根，派人截杀两个孩子，被于谦旧部朱骥阻拦。曹少钦又派心腹皮绍棠（苗天 饰）和毛宗宪（韩英杰 饰）赶到出关必经之地龙门客栈拦截。其时义士萧少镃（石隽 饰）也赶赴客栈与栈主会合商议搭救忠良之后，朱骥与其女扮男装的妹妹朱辉（上官灵凤 饰）也赶到客栈，三路人马碰头，怀着各自目的，试探彼此身份，很快变成一场混战，此时曹少钦也正飞速赶来龙门客栈，武功极高的他是义士们的最后宿敌……©豆瓣', '上官灵凤', '胡金铨', 8.2, 18128, 'tt0060635', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2254482511.jpg', 0.3, 1.2, 16.3, 54.8, 27.5, '0.118427,-0.083896,-0.338216,0.255021,0.259058,-0.081916,0.263308,0.573642,-0.584740,-0.508722,0.351932,0.427923,0.035197,-0.074708,0.159637,-0.417418,-0.183611,-0.542228,-0.193481,-0.198518,-0.018089,-0.329598,0.201729,-0.145377,0.034091,0.065379,0.339304,0.128344,0.140637,0.750776,0.494885,0.237727,-0.651579,0.363646,-0.107277,0.181562,0.264514,-0.335002,-0.367307,0.088538,-0.384986,-0.341162,-0.390277,-0.291156,-0.215777,0.263250,0.681972,-0.071564,0.183235,-0.234287,-0.288375,-0.375739,0.044397,0.166139,0.576253,0.107580,0.233533,0.462001,0.009854,0.115680,-0.264395,0.102431,-0.206700,0.265260,0.440171,-0.188860,-0.456913,0.216347,-0.073278,0.040987,-0.062840,-0.348128,0.314042,0.536270,-0.074458,-0.031222,0.006274,-0.158287,-0.686346,0.210698,0.620145,-0.229370,0.378463,-0.479328,0.580078,-0.181688,0.551215,-0.265022,0.098859,0.041218,0.507193,-0.152214,0.249016,-0.099706,-0.192430,-0.058697,-0.629984,0.306493,0.061268,-0.281728,0.246896,-0.539385,-0.112280,-0.052441,-0.310419,0.201857,0.374307,0.408643,0.236303,-0.192532,-0.177769,0.005346,0.266194,-0.993189,0.377680,-0.040859,0.147056,-0.204329,0.040977,-0.306246,0.555812,0.210828,0.147664,0.056386,-0.486324,-0.171629,-0.433323,-0.353179', '1461031', '1306490', '1464901', '1294011');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1459148', '遇人不熟', '剧情', '故事发生在一夜之间。无名小卒宫田(中村靖日 饰)每天上班下班过着简单平凡的生活。刚刚被男友劈腿分手的真纪（雾岛丽香 饰）走出了他们同居的房子，失魂落魄的在饭馆遇上了在吃饭的私家侦探神田（山中聪 饰）和宫田。单纯善良的宫田把痛苦无家可归的真纪领回了家暂住。对真纪有了好感，想进一步发展下去。不料，分手半年的前女友阿美（板谷由夏 饰）却突然出现。侦探神田和阿美进行了一项秘密交易，牵扯上了黑社会老大浅井（山下规介 饰）一笔丢失的巨款，这笔巨款和几个人都牵扯上了关系。真相慢慢浮上水面，5个人的命运和嘴脸在一夜之间无处遁形。©豆瓣', '中村靖日', '内田贤治', 8.2, 8838, 'tt0461857', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1709976573.jpg', 0.2, 1, 14.6, 55.5, 28.7, '0.361607,0.021650,-0.464029,0.115950,-0.176372,-0.266002,0.516573,0.291740,-0.235891,-0.242665,-0.116623,0.679580,-0.319746,0.338466,0.138801,0.105414,-0.172316,-0.760032,0.134200,-0.267017,-0.051469,-0.569124,0.094638,-0.264400,-0.023889,-0.046070,0.307692,0.189975,0.006763,0.529950,0.306382,0.102542,-0.332858,0.317386,-0.185953,0.222980,0.085501,0.396027,-0.144750,0.109772,-0.221596,-0.275385,0.081129,-0.055478,0.190200,0.377339,0.537342,0.083798,-0.384978,0.165320,0.239786,-0.090288,-0.146230,0.161250,0.535419,-0.070373,-0.000573,0.178260,-0.503752,-0.246776,0.351909,-0.202303,-0.473218,-0.092947,-0.086674,0.180749,-0.753407,0.604370,-0.109752,0.009975,0.074535,-0.476569,0.092382,0.553058,0.245196,0.299004,-0.086994,0.159191,-0.516165,0.311355,0.758895,-0.031352,0.109535,0.393169,-0.175123,-0.226660,-0.342595,-0.147766,-0.074243,-0.110274,0.393962,-0.219141,-0.442403,0.038900,-0.538828,0.017869,-0.019636,-0.047291,-0.093395,-0.364110,-0.037282,-0.374061,-0.240843,-0.419334,-0.496407,0.373883,0.093979,-0.160397,0.535708,-0.680125,0.137096,0.630889,0.582165,-0.381560,0.549845,0.101801,-0.042174,-0.117070,0.176678,0.044099,0.119953,0.389896,0.407458,0.309316,-0.093307,0.129169,-0.254612,0.279811', '25908042', '1299062', '1292219', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1459368', '悲伤电影', '剧情', '本片在平行推进中描写了四段悲伤的恋情：拳击陪练河锡（车太贤 饰）厌倦了做人肉沙袋的饭碗。一次偶然的机会，他找到一份新的职业——分手代理。这份工作让他见识了太多的悲欢离合，并坚定了对女友淑贤（孙泰英 饰）的爱，但是偏偏事与愿违；身为职业女性的珠蓉（廉晶雅 饰）因为工作压力大，忽略了对儿子辉灿的呵护。当她因胃病住院后，母子在交流中都感受到了亲情的温暖；手语主播秀珍（林秀晶 饰）和消防员镇宇（郑宇成 饰）是一对恋人。不过，她并不喜欢他的危险工作。当两人终于决定结婚时，却遭遇了灭顶之灾……哑女秀恩（申敏儿 饰）与画家尚宇（李基宇 饰）在公园活动中不期而遇，他们因为一幅画结缘。由于她带着娃娃的面具，因此他看不到她的脸。但两人却在猜测中堕入了无声的爱河……©豆瓣', '郑雨盛', '权宗官', 7.7, 62692, 'tt0475711', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1825817370.jpg', 0.3, 2.6, 29.2, 46.3, 21.5, '0.166957,-0.024769,-0.623743,0.548619,-0.202363,-0.246081,1.012942,0.266633,-0.431064,-0.062043,0.311438,0.737439,-0.236193,0.088831,0.107956,0.012348,-0.154548,-0.780340,0.192980,-0.083410,-0.326803,-0.325103,-0.274673,0.016958,-0.193548,-0.093535,0.607559,0.135077,-0.214360,0.493762,0.340327,-0.160248,-0.042314,0.711717,-0.078891,-0.054711,0.015826,0.265745,-0.125594,-0.019500,0.082295,-0.245686,-0.192147,0.394189,-0.010613,0.492212,0.718483,-0.234712,-0.242922,0.023860,0.212595,-0.126088,-0.090978,0.169509,0.129387,0.177425,0.271903,0.125645,-0.322238,0.171443,-0.013547,-0.014333,-0.650011,0.068015,0.022944,0.263814,-0.595600,0.803923,-0.060588,-0.141001,0.032034,-0.134533,0.184637,0.110402,0.254993,0.454440,-0.368172,0.103531,-0.234461,0.369263,0.444278,0.091510,0.029632,0.724051,-0.450162,-0.467428,-0.155113,-0.085541,-0.490812,-0.046401,0.262814,0.118197,-0.346586,0.163089,-0.606611,0.011148,-0.118047,0.071241,-0.241197,-0.648063,0.048212,-0.402646,-0.095643,-0.659073,-0.449541,0.142335,0.108297,-0.339438,0.624337,-0.887750,0.177895,0.503736,0.268516,-0.458315,0.728544,0.492656,-0.029736,-0.394776,-0.002235,0.474355,-0.223749,0.160494,0.253166,0.391944,0.037052,-0.097264,-0.390409,0.621512', '1304989', '24756472', '3059036', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1460341', '佛兰德斯的狗', '剧情', '在19世纪的比利时法兰德斯。一天，一位修女造访了安特卫普镇的大教堂。这位修女仰望著鲁宾斯《圣母昇天》画时，记忆一下子回到了20年前……尼洛（Brady Bluhm 配音）是一个孤儿，和爷爷（罗伯特·劳吉亚 Robert Loggia 配音）一起生活在安特卫普城附近的霍布肯村，以帮人运送牛奶为生。一个偶然的机会，他们收养了一条被人遗弃的大狗帕奇。尼洛和姥爷过着穷苦的生活，帕奇尽自己所能帮助他们，为他们拉车进城卖牛奶。尼洛虽然贫穷，却拥有惊人的艺术天才，他心中有一个高贵的梦想，并为实现自己的梦想不懈努力。然而厄运却接连不断：因为穷富之别，尼洛被迫远离小伙伴阿洛伊斯（德比·戴瑞巴里 Debi Derryberry 配音），年少的清梦被搁浅；在世人都抛弃尼洛的时候，只有老狗帕奇和他不离不弃……影片改编自英国作家奥维达的同名小说。©豆瓣', '津村真琴', '黑田昌郎', 8.9, 12886, 'tt0304072', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453890966.jpg', 0.4, 0.8, 10.5, 31.4, 56.9, '0.171359,0.079067,-0.459720,0.704923,0.028842,-0.535561,0.764338,0.138412,-0.476928,-0.442388,0.207317,0.967666,0.001953,0.329980,0.275965,0.084046,-0.261232,-0.366787,0.180121,-0.214244,-0.308351,-0.265815,-0.323519,-0.172595,-0.222182,-0.325231,0.505818,0.086905,0.024954,0.270129,0.110343,0.160142,-0.011147,0.240740,-0.364843,0.217939,0.167631,-0.132235,-0.188717,0.153446,-0.286551,0.097023,-0.267106,-0.010128,0.134204,0.098969,0.594896,-0.274766,0.032170,-0.189878,0.280486,-0.258082,0.139176,0.113797,0.145852,-0.225595,0.194127,0.015150,-0.050195,-0.096867,0.049121,-0.220749,-0.655299,-0.061489,-0.037081,0.018097,-0.618393,0.686327,-0.077298,-0.078502,0.079763,-0.337591,0.028621,0.262923,0.146333,0.465125,-0.145980,0.002479,-0.539272,0.374950,0.782612,-0.178797,-0.207836,0.396925,-0.388477,-0.396387,-0.102820,-0.164473,-0.807446,-0.029563,0.327482,-0.049561,-0.256067,0.486540,-0.510373,0.003449,-0.279434,-0.177555,-0.059486,-0.301180,-0.173608,-0.518076,-0.009634,-0.290023,-0.093526,0.302402,0.122838,-0.179297,0.817393,-0.693882,0.217918,0.717665,0.275716,-0.163732,0.846001,-0.042747,0.056915,-0.187478,-0.080739,0.715398,0.248518,0.209892,0.158644,0.275287,0.070414,0.116631,-0.341273,0.746933', '30162520', '1292720', '1870681', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1460888', '少年往事', '剧情', '1928年的青岛，方忆琳（马晓倩 饰）和尧永诺（翟天临 饰）结识于一把教堂外遗失的小提琴，两人由此变成了无话不谈的好朋友。在方为反抗母亲逼迫她订婚而离家出走后，尧义不容辞地将她偷偷安置在海边的废弃小船中。尧悉心照顾生病一人的方，方也帮尧一起追寻要成为音乐家的梦想。然而少年们的宴席也终有散场的一天。在方决定坐船去欧洲寻父之后，尧和朋友们决定卖掉心爱的老爷车来帮方筹集船票的钱。当方真的买好船票准备远行之时，送行的尧也终于在岸边为她奏起了那首写给她的小提琴曲……©豆瓣', '翟天临', '陈建忠', 7.8, 7730, 'tt6380322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2321048333.jpg', 0.9, 4.1, 25, 44.6, 25.4, '0.023559,0.138930,-0.751517,0.560266,-0.024032,-0.480160,0.475189,0.244275,0.103912,-0.277105,-0.114586,0.834479,0.005122,0.637478,0.660830,-0.094847,-0.342167,-1.036527,-0.199313,-0.285867,-0.491637,-0.321033,0.021172,-0.184885,-0.199700,0.050961,0.473834,0.259601,0.156337,0.530834,0.375444,0.066964,-0.037250,0.455236,-0.557007,-0.110063,-0.253985,0.328816,-0.272041,0.102369,0.005043,-0.371730,-0.177262,0.274404,0.226138,0.142248,0.910129,-0.118784,0.052535,-0.000098,0.215179,-0.169248,0.456549,-0.209752,0.259436,0.281832,-0.040073,0.024693,-0.565209,0.035941,-0.038256,-0.129203,-0.539234,-0.076448,-0.008745,-0.328932,-0.765454,0.473342,0.042750,0.131875,-0.083156,-0.459621,0.431846,0.505883,-0.044435,0.314274,-0.219283,0.065250,-0.568120,0.314316,0.759702,-0.004102,0.307394,0.282587,0.127317,-0.353706,0.378506,-0.034570,-0.383403,-0.253497,0.349697,0.006967,0.032781,-0.189251,-0.643937,-0.315790,-0.347307,-0.137965,0.138408,-0.232666,0.069783,-0.560453,0.153032,-0.158922,-0.008784,0.202950,-0.009910,-0.305633,0.788846,-0.553667,0.338712,0.430640,0.334697,-0.612553,0.852323,-0.121972,0.349722,-0.027292,0.147970,0.021496,-0.008704,0.233249,0.339084,0.116718,-0.039183,0.127401,-0.585955,0.433907', '1307146', '30162520', '1301912', '1293607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1460996', '十兄弟', '喜剧', '老爷百岁大寿时被小儿子大虾（钟镇涛 饰）气死，根据族规，家财由大哥全权管理，而大虾只分得瘦田一亩及老牛一条。十分奇怪的是，这片瘦田里种出的蔬菜瓜果都特别巨大。于是，大虾和大虾嫂（张敏 饰）刨开土一看，发现地里原来埋藏着十颗宝珠。可惜此事被无恶不作的大帅得知，于是带领兵马前来抢宝珠。情急之中，大虾与大虾嫂各吞宝珠五粒，分头逃走。大虾不幸被大帅捉去，大虾嫂则跌入一个墓穴逃过一劫。 当晚大帅府内，大虾生下五个天赋异品的孩子：大力三、橡皮四、飞天五、铜头六及高脚七。而这五个孩子却误以为大帅就是他们的父亲，而可怜大虾被关到了监狱。同一时间，大虾嫂亦生下五个兄妹：千里眼、顺风耳、遁地入、大口九及大喊十。大虾和大虾嫂最后能否打败邪恶的大帅，一家重逢？©豆瓣', '张敏', '李力持', 6.9, 66282, 'tt0114424', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2352277002.jpg', 1.2, 6.8, 49.4, 31.8, 10.8, '-0.022179,-0.196091,-0.307158,0.341303,0.143226,-0.223855,0.331871,0.564826,-0.185107,0.014513,0.174743,0.370489,-0.117114,0.072027,-0.122128,-0.075988,0.368592,-0.271417,-0.332999,-0.031861,-0.121117,-0.029178,-0.106162,0.098165,0.139897,0.087821,-0.103454,-0.205451,0.384572,0.533132,0.083468,-0.146806,-0.505331,-0.161093,-0.122894,0.369527,0.174404,-0.112609,-0.169625,0.109302,-0.244383,0.004994,0.082038,-0.022777,0.163057,0.311247,0.535424,-0.504304,-0.213676,-0.550952,-0.178942,-0.021837,-0.241454,0.365663,0.264622,0.077474,0.311143,-0.132802,-0.256497,0.334820,0.385313,-0.104029,-0.385354,-0.065290,-0.124628,-0.062247,-0.603233,0.084255,0.079431,0.148040,-0.009615,-0.358012,0.101866,0.023980,-0.106627,0.490488,-0.123340,-0.069613,-0.742230,-0.050535,0.472259,-0.331304,0.309976,-0.152989,0.377127,-0.161060,0.523821,-0.096716,0.026900,0.086457,0.461687,0.162932,-0.223266,0.087477,-0.655063,0.163760,-0.423185,-0.116151,0.076869,-0.026115,-0.246221,0.072172,0.181950,0.020034,-0.195489,0.209610,0.371482,-0.066104,0.556472,0.082196,0.194868,0.012423,0.024428,-0.174092,0.405883,-0.112135,0.005435,-0.290713,-0.068859,-0.411739,0.291200,0.134977,0.565339,0.362339,-0.382942,-0.359842,-0.636206,-0.064225', '1432825', '1306505', '26603666', '1469984');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461031', '七侠五义之五鼠闹东京', '武侠', '南侠展昭（林炜 饰）获封“御猫”，五鼠之锦毛鼠白玉堂（李志希 饰）内心不服，潜入皇宫向展昭挑战，结果虽中伏仍全身而退。皇帝有感白玉堂武功高强气概过人，赦免其罪，包拯有心收复五鼠，令他们为朝廷效力，遂派遣展昭远赴陷空岛拜访。另一方面，回到陷空岛的白玉堂被四个义兄：飞天鼠卢方、彻地鼠韩彰（郑浩南 饰）、穿山鼠徐庆（方中信 饰）、翻江鼠蒋平捉弄，又被女剑客丁月华反唇相讥，遂有志行侠于天下，远赴东京。展昭一路跟随白玉堂潜入庞太师府，助其大闹太师府。庞太师权欲熏心，派出手下延揽五鼠意欲收为己用。卢方等四鼠有感包拯与展昭义薄云天，表示归顺，唯独白玉堂倔强，偷走尚方宝剑而不肯就范……©豆瓣', '林炜', '陈木川', 6.2, 3082, 'tt5825942', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2529382517.jpg', 2.8, 12.5, 60.8, 17.1, 6.8, '-0.119707,0.167450,-0.260895,0.391692,0.239241,-0.055363,0.003991,0.512617,-0.575237,-0.401432,0.305340,0.304224,-0.149505,-0.141737,0.008787,-0.265452,0.117463,-0.332259,-0.189828,0.030161,0.361806,-0.115210,0.049798,-0.106586,-0.354672,0.118053,0.285830,0.209546,0.003690,0.659286,0.306116,0.387958,-0.413803,0.377619,-0.156298,0.157203,-0.067013,-0.112027,-0.117430,0.049618,-0.096992,-0.244815,-0.563217,-0.025840,0.068718,0.138379,0.430580,-0.252995,0.022399,-0.098711,0.083469,-0.121760,0.146212,0.005198,0.133344,-0.022198,-0.293103,0.357553,0.158494,0.014809,0.027301,0.284945,-0.061487,0.156471,0.292698,-0.173876,-0.239340,-0.103585,-0.369673,0.103226,-0.456867,-0.329483,-0.198241,-0.153478,0.037869,-0.316175,0.138606,0.071488,-0.352891,0.349747,0.503043,-0.141510,0.333934,-0.639629,0.582833,-0.394237,0.439283,-0.343007,0.068093,-0.112912,0.330554,-0.206487,0.224814,-0.031969,-0.054127,-0.391278,-0.609557,0.593327,-0.003451,0.131551,0.223662,-0.272191,0.227251,-0.081519,-0.179354,-0.161721,0.467161,-0.048075,0.147088,-0.302465,-0.404267,-0.039548,0.007029,-0.890496,0.365959,-0.075443,0.122449,0.021667,0.063864,0.028243,0.610490,0.078820,0.398649,-0.017174,-0.260780,-0.292536,-0.370223,-0.300471', '1459054', '3291930', '1300883', '5996799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461079', '咒怨 录像带版', '悬疑', '名叫佐伯俊雄（小山僚太 饰）的男孩多日未曾上课，他的级任教师小林俊介（柳优怜 饰）按照地址登门拜访，发现家里乱七八糟，臭气熏天，而独自在家的俊雄则浑身是伤，精神恍惚。俊雄的父母行踪不明，他的妈妈伽椰子（藤贵子 饰）是小林大学时代的同学，且一直对小林心存爱慕，但是这份心思为伽椰子乃至她身边所有的人带来难以预料的悲剧。村上一家搬入一幢独栋房产，在一个毫无征兆的日子里，厄运忽然降临，无论是村上一家还是与之相关的家庭教师（三轮ひとみ 饰）、异性好友（栗山千明 饰），皆遭遇了令人不寒而栗的恐怖恶灵。咒怨最为恐怖的故事缓缓拉开序幕……©豆瓣', '藤贵子', '清水崇', 7.9, 18851, 'tt0330500', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230107928.jpg', 0.9, 2.9, 24, 42.5, 29.8, '0.107201,-0.358082,-0.369385,0.278896,-0.019687,-0.020593,0.768091,0.198516,-0.614497,-0.590369,0.185649,0.543767,-0.090932,0.474514,0.271036,-0.010799,0.081563,-0.466761,0.039387,-0.061418,-0.114515,-0.364622,-0.051567,0.028656,-0.013619,-0.053122,0.475990,0.041902,0.131013,0.581754,0.025000,0.579930,-0.185181,0.191950,0.019025,0.052194,0.018066,0.046775,-0.124083,-0.052281,-0.143014,-0.210057,-0.201395,0.299250,0.005220,0.185167,0.612080,-0.080977,-0.511530,-0.228072,0.391407,-0.006473,0.033438,0.235602,0.283959,-0.053577,0.416024,0.244452,-0.027420,-0.199247,0.312218,0.037956,-0.466004,0.029106,0.258278,0.191035,-0.365264,0.395580,0.004758,0.045097,0.125148,-0.354468,0.143776,0.010585,0.152262,0.470412,-0.457396,-0.022904,-0.118649,0.066422,0.259244,-0.177652,-0.057789,0.216883,-0.076093,-0.119896,0.021798,-0.027916,-0.492958,0.096304,-0.086089,0.209807,-0.089634,0.227961,-0.628270,-0.004649,-0.068400,-0.173030,0.031100,-0.138609,-0.197738,-0.584415,-0.055415,-0.555979,-0.283181,0.039699,0.278493,-0.056306,0.701255,-0.643529,0.248327,0.285835,0.163384,-0.115180,0.335779,-0.137901,-0.116729,-0.114069,-0.094615,0.074830,-0.005128,0.219593,0.059515,0.344507,-0.082138,-0.263220,-0.252650,0.345937', '3811356', '10174444', '25922902', '27185563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461348', '来电惊魂', '惊悚', '居住在埃兰谷的姬尔·强森（凯米拉·贝尔 Camilla Belle 饰）是一个普普通通女高中生，由于她煲电话粥过长，因此父亲本（克拉克·格莱格 Clark Gregg 饰）命令她当保姆赚取花费。万般无奈，姬尔只得应征来到曼卓基斯医生（Derek de Lint 饰）的家中。曼卓基斯及其夫人凯丽（Kate Jennings Grant 饰）住在一幢豪华的湖畔别墅中，屋内的装饰奢侈高贵，令姬尔目不暇接。她当晚的工作很简单，就是在曼卓基斯夫妇外出用餐时留下看家，并照顾他们两个正在生病的孩子。不久夜色降临，偌大的别墅内显得空空荡荡，冷清吊诡。正在此时，一通通神秘的电话接连打了进来，令姬尔变得恐慌与不安……本片为1979年同名影片的翻拍之作。©豆瓣', '卡米拉·贝勒', '西蒙·韦斯特', 6.1, 11953, 'tt0455857', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2541661115.jpg', 4.1, 17.5, 53.3, 19.6, 5.6, '0.041813,0.059656,-0.589498,0.225421,0.010410,-0.268298,0.882806,0.483426,-0.481828,-0.784494,0.204357,0.562536,0.004478,0.218989,0.285124,-0.074645,-0.545425,-0.193326,-0.069669,-0.194636,0.041822,-0.238380,0.002793,-0.274079,0.161003,-0.306479,0.018748,-0.184688,-0.020126,0.486187,0.179029,0.267606,-0.263458,0.231421,-0.043765,-0.023912,0.110558,-0.195632,-0.208364,0.007605,-0.267739,-0.031962,-0.269910,-0.117935,0.451939,0.330476,0.547619,-0.147060,-0.347318,0.069002,0.244031,0.139397,-0.193751,0.020643,0.344240,0.057607,0.334317,0.000847,-0.579290,0.170773,-0.022752,-0.352022,-0.490596,0.308136,0.039789,0.040694,-0.458064,0.539348,-0.047783,-0.286976,0.046389,-0.485883,0.208209,0.052016,-0.123753,0.556641,0.043422,0.105258,-0.330769,0.090301,0.340192,0.109841,0.070436,0.325105,-0.187448,-0.270992,0.243217,-0.019337,-0.488505,-0.132013,0.308115,-0.060661,0.247498,-0.114189,-0.535590,0.048460,-0.446654,-0.364657,-0.128505,-0.280722,-0.371805,-0.848318,0.087914,-0.035150,-0.153886,0.132038,-0.071208,0.210528,0.245348,-0.618046,0.451138,0.074554,0.201039,-0.161126,0.499753,-0.122831,0.236391,0.165446,-0.338815,0.381838,0.061007,0.285903,0.071491,0.300555,-0.304085,-0.200495,-0.601229,0.111807', '10466639', '1316693', '1297659', '1424661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461351', '小红帽', '喜剧', '本片把家喻户晓的“小红帽”故事变成了《罗生门》。这部由温斯坦公司发行的非传统童话动画片是第一部完全独立投资拍摄的电脑动画长片。灰熊警长（艾勒比 Xzibit 配音）和鹳探员比尔（安东尼·安德森 Anthony Anderson 配音）奉命调查小红帽祖母的小屋内发生的动乱案件，多人都被警方指控有犯罪嫌疑，涉案人员包括空手道高手小红帽（安妮·海瑟薇 Anne Hathaway 配音）、搞笑的大灰狼（帕特里克·沃伯顿 Patrick Warburton 配音）、略有痴呆的伐木巨人（詹姆斯·贝鲁什 James Belushi 配音）等。他们分别被指控有多项罪名，其中包括：破坏和非法入侵、破坏社会安定、非法偷吃、无执照使用斧子等等。然而，所有被指控的这些嫌疑人都有他们自己的故事要讲，这也使得案件的真相变得扑朔迷离......到底谁才是真正的凶手呢？©豆瓣', '安妮·海瑟薇', '柯瑞·爱德华兹', 7.5, 13677, 'tt0443536', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2250462395.jpg', 0.9, 4.5, 31.9, 44.1, 18.6, '0.471025,-0.403395,-0.458927,0.335610,0.144042,0.185679,0.592370,-0.057900,-0.403524,-0.320374,0.141354,0.497918,-0.368116,0.071376,-0.156954,-0.020856,-0.410091,-0.599174,-0.210354,-0.063714,-0.023818,-0.550230,-0.260330,-0.251329,0.047983,0.014519,0.483839,-0.192219,-0.378598,-0.086023,0.407385,0.137698,-0.326980,0.104696,0.242023,0.219111,0.390117,-0.238695,0.037880,0.102352,0.064479,-0.182046,0.065185,0.140567,0.013949,0.354217,0.612956,-0.174967,-0.082427,-0.016922,0.561467,-0.485771,-0.032873,0.066512,0.279909,0.073763,0.102118,0.458525,-0.116933,0.003486,-0.001540,-0.206553,-0.990149,-0.077752,0.055989,0.270358,-0.121623,0.000259,-0.259261,0.084253,0.085469,-0.054583,0.319526,0.242629,0.712064,0.365167,0.308830,0.056848,-0.605241,0.418384,0.276683,-0.120894,-0.421775,0.087861,-0.099555,-0.371865,-0.121086,-0.367323,-0.126329,0.242236,0.430390,-0.279784,-0.185683,0.293362,-0.525747,-0.220720,-0.151452,-0.434612,-0.325890,-0.262032,-0.105018,-0.628994,-0.171564,-0.174953,-0.045379,-0.142694,0.303385,-0.337414,0.538981,-0.571743,0.135057,0.522787,0.169258,-0.386187,0.281753,-0.016039,0.080312,-0.063896,-0.185044,-0.061724,0.351979,0.212547,0.310260,0.169388,0.417109,-0.355082,-0.151857,0.120778', '6844861', '27073234', '1793491', '25918677');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461370', '吴清源', '剧情', '1914年出生于福建省闽侯县的吴清源被称为“围棋天才少年”，1928年在濑越宪作（柄本明饰）、喜多文子（松坂庆子饰）等日本朋友的热心帮助下，吴清源（张震饰）和母亲（张艾嘉饰）、妹妹（黄奕饰）东渡日本，开始了终其一生的围棋生涯。初至日本，吴清源与日本棋院大赛刚出炉的冠军较量，并中盘获胜；五年后，吴清源与他人共创围棋新布局，掀起一场围棋革命。1939至1956年间，吴清源凭个人之力打败日本最顶尖的七位超级棋士，十次大胜“十番棋”，被誉为“昭和棋圣”。他以“95盘擂台赛式”的“十番棋”，令当时棋坛所有大师全部降级，创造了日本围棋界所称的“吴清源时代”。然而，吴清源作为一位围棋棋手能否超越国籍、政治、战争等世俗问题？他是否有过难以承受的痛苦？©豆瓣', '张震', '田壮壮', 6.9, 11397, 'tt0439885', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2321296423.jpg', 1.7, 8.8, 44.9, 33.3, 11.4, '-0.189323,0.216841,-0.362181,0.524624,-0.046619,-0.259590,-0.132021,0.052606,-0.449664,-0.394898,0.306456,0.881745,-0.200140,0.145885,0.320658,-0.575728,0.152467,-0.844174,0.011450,-0.103684,-0.208770,-0.257469,-0.215279,0.337230,-0.269292,-0.078663,0.862154,0.209060,-0.508499,0.512698,0.046201,0.379462,0.110128,-0.007370,-0.181184,-0.329074,0.217775,0.084262,-0.691828,0.234122,-0.403467,-0.182769,-0.217572,0.011147,-0.203129,-0.022953,0.375607,-0.299796,0.172605,-0.487780,0.248382,-0.051966,-0.672707,0.140360,0.511992,0.219870,0.038283,0.324781,0.208857,0.164755,-0.159612,-0.264594,-0.540672,-0.105068,0.094735,-0.063843,-0.240409,0.644611,-0.218232,-0.065892,-0.117145,0.074677,0.046898,0.415081,0.405994,0.070522,-0.170231,-0.133974,-0.188632,0.637012,0.646718,-0.070011,-0.102260,-0.009892,0.428100,-0.555912,-0.016276,-0.731776,-0.115175,0.390850,0.153014,-0.256272,0.264439,0.212115,-0.462677,0.160506,-0.047398,-0.196895,0.448855,-0.196981,0.428299,-0.476727,-0.153578,-0.341112,-0.174341,-0.192268,0.409416,-0.413249,1.151978,-0.615425,0.049071,0.056639,-0.199468,-0.133331,0.418430,0.328816,0.024543,-0.342055,-0.226381,0.134062,-0.246425,0.250055,-0.271317,0.485538,0.222606,-0.109733,-0.025610,0.366585', '27602116', '26711487', '26615753', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461401', '猛鬼差馆', '喜剧', '香港有一间警局，三十年前曾是日军侵略香港时的军营。因为战败，日本军官在里面切腹自杀了。据说他们的阴魂不散，魂魄依然逗留在这所警局当中，并会在孟兰节当天出没。金麦基（张学友 饰）与孟超（许冠英 饰）都在这所警局里面当警察，但他们一直不相信警局里面的恐怖传说。直到在孟兰节当天他们亲眼目睹了逃犯蛇仔明（楼南光 饰）遇到太阳化作了灰土，原来蛇仔明在监狱内看到了日军的鬼魂，被咬后变成了僵尸，他们才相信警局内的确有阴魂。他们把情况报告上司正想查明真相，又遇到了一女子疑似被僵尸咬后死去了。一场警察与厉鬼间的较量也正式开始了……©豆瓣', '张学友', '刘镇伟', 7.1, 16976, 'tt0093522', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1017045390.jpg', 0.7, 4.8, 44.9, 35.9, 13.6, '0.307617,-0.112035,-0.863055,0.169163,0.095484,-0.107831,0.832875,-0.103677,-0.609424,-0.052827,0.251672,0.620780,-0.240662,0.225426,0.028104,-0.175638,-0.449325,-0.551432,-0.277726,-0.498732,-0.509034,-0.076699,-0.367601,-0.112560,0.103379,-0.134190,0.248277,0.322466,0.086720,0.450708,0.273348,0.177466,-0.258695,0.543954,-0.194510,0.030787,0.431940,0.188585,0.144027,0.206268,0.106137,-0.492568,0.087517,0.084162,0.001283,0.306767,0.605012,-0.354799,-0.273432,-0.153191,-0.058967,-0.257971,-0.185554,0.268109,0.811687,-0.111200,0.446179,0.299964,-0.183531,-0.092677,-0.168854,0.154574,-0.535063,0.078574,-0.046191,0.194628,-0.248205,0.307970,0.064906,0.182525,0.128223,-0.215441,0.479534,0.336557,0.327016,0.097715,-0.143380,-0.264113,-0.770649,0.258391,0.668236,-0.133383,-0.212612,0.134105,0.125851,-0.643110,0.036258,0.046429,0.009579,0.132412,0.367056,-0.058081,-0.594493,-0.192295,-0.561554,-0.149491,-0.201933,-0.010776,-0.375656,-0.029131,-0.357423,-0.461662,-0.150443,-0.309784,-0.287530,0.202362,0.009604,0.248822,0.371032,-0.784725,0.370935,0.558145,0.358851,-0.344557,0.695594,-0.182417,0.071589,0.130607,0.168054,-0.102758,0.395796,0.790079,0.472413,0.478451,-0.122664,-0.267524,-0.275792,0.242247', '25870679', '35073565', '1947080', '4724373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461403', '茶馆', '剧情', '世纪之交，古老的中国正迎来前所未有的巨大变革。老态龙钟的大清王朝摇摇欲坠，六君子的鲜血无法阻止历史车轮的滚动，老北京城的上空风云变幻，波谲云诡。王利发（于是之 饰），北京城内裕泰茶馆的年轻掌柜。他谨记父亲的教诲，体面周全地迎送四方宾客。小小的茶馆内，三教九流各色人等穿梭于此：提笼架鸟哀叹时运的松二爷（黄宗洛 饰）；慨叹国之将亡的刚毅满人常四爷（郑榕 饰）；一心谋求实业救国的秦仲义（蓝天野 饰）；丧尽天良买卖人口的刘麻子（英若诚 饰）；打算娶老婆的庞太监（童超 饰）……你方唱罢我登场，小小茶馆之内演尽世间的沧桑与凄凉……本片根据老舍同名原著改编，并1983年第3届中国电影金鸡奖特别奖、文化部1982年优秀影片奖特别奖。©豆瓣', '于是之', '谢添', 9.5, 114507, 'tt1395030', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2528965424.jpg', 0.1, 0.2, 2.3, 17.7, 79.7, '-0.124828,0.217575,-0.493284,0.334108,0.485243,-0.232050,0.374390,0.318184,-0.356385,-0.176923,0.183192,0.393579,-0.037054,0.069374,0.241169,-0.133770,0.070130,-0.437704,-0.435223,0.069937,0.307804,-0.096440,-0.293806,-0.132851,-0.457610,0.053158,0.256306,0.314259,-0.005464,0.420363,0.461490,0.086215,-0.245349,-0.162783,-0.198619,-0.018907,0.006763,0.251455,-0.502413,-0.398759,-0.333721,-0.183314,-0.226158,-0.280876,-0.181490,-0.001113,0.367627,-0.142228,0.139059,-0.224288,0.497709,0.151326,-0.070774,-0.042768,-0.000187,0.051093,0.039138,0.349110,0.003453,0.091804,-0.229442,-0.240249,-0.346835,-0.129319,0.321789,0.226289,-0.276770,0.329733,0.015165,-0.002666,-0.259595,-0.146967,0.079055,-0.092262,0.304369,0.226318,0.136915,0.230890,-0.302536,0.520656,-0.000010,0.163828,-0.361094,0.029721,-0.087078,-0.355970,0.028253,-0.332418,-0.378442,-0.015531,0.115403,-0.126909,0.139436,0.276165,-0.348493,-0.029512,-0.099492,0.010031,0.164766,0.079856,-0.235820,-0.444618,0.071139,-0.314582,-0.058313,0.109543,0.334790,0.135655,0.604742,-0.153318,0.109237,0.268890,-0.069210,-0.151820,0.523652,0.068562,0.058734,-0.095071,-0.126677,-0.061621,-0.302563,0.233757,-0.169413,0.182125,-0.323997,-0.385431,-0.209029,0.141895', '22265121', '26647163', '1388176', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461919', '王者之心', '剧情', '中世纪，罗马帝国毁灭，各方势力分割盘踞英格兰，爱尔兰国王乘机聚集势力、虎视眈眈。雄图大略的马克王（卢夫斯·塞维尔 Rufus Sewell 饰）希望在传奇骑士特里斯坦（詹姆斯·弗兰科 James Franco 饰）的帮助下实现统一大业。失去双亲特里斯坦的他被马克王悉心抚养长大，情同父子。为分裂英格兰各部落，爱尔兰王决定以女儿为奖品举办全英骑士大赛。特里斯坦为马克王赢得了公主，但当看到公主的真面目时他如遭雷击。原来他曾在进攻爱尔兰的战斗中身负重伤，得到了神秘爱尔兰女子伊索尔德（索非亚·迈尔斯 Sophia Myles 饰）的照顾。两人由此相爱，但为了统一大业不得不分离。不管是为了国家和平还是为了养育之情，特里斯坦和伊索尔德都无法再继续恋情。他们将如何压抑这份热情？而爱尔兰国王的阴谋是否给马克王的统一大业带去障碍？©豆瓣', '詹姆斯·弗兰科', '凯文·雷诺兹', 7.1, 14979, 'tt0375154', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p792648816.jpg', 0.8, 6.5, 43.7, 36.6, 12.4, '-0.286619,0.333497,-0.441160,0.775367,0.176873,-0.492763,0.405498,0.138120,-0.579960,-0.295211,0.064410,0.729311,0.036026,-0.101491,0.183707,-0.215822,-0.558788,-0.607074,-0.034411,-0.050148,-0.156069,-0.278344,-0.163748,-0.508483,-0.268776,-0.323405,0.770991,0.070955,-0.073929,0.155455,0.335302,0.508907,-0.032581,0.256336,-0.057485,0.028124,-0.097438,-0.115643,-0.717732,0.250493,-0.085127,0.098217,-0.385114,0.146505,0.230173,0.114329,0.282705,-0.579677,0.503227,-0.615498,0.018783,-0.297748,0.350906,0.574278,0.068531,-0.136808,0.239798,0.123168,-0.109780,-0.375770,0.177385,-0.474756,-0.708643,-0.024617,0.156037,0.163271,-0.685996,0.326045,-0.490518,-0.013778,0.249423,-0.185327,0.056592,0.886834,0.408993,0.168057,-0.106372,0.152752,-0.472337,-0.058761,0.976630,-0.052473,-0.392752,-0.443791,-0.137956,-0.599918,0.001909,-0.382296,-0.386805,0.005381,0.342806,0.048858,0.583974,0.532698,-0.667437,-0.472493,-0.507510,-0.304716,0.319310,-0.716400,0.127618,-0.384808,-0.096284,-0.201230,-0.021212,-0.061838,0.160047,-0.197326,0.819663,-0.821662,0.361256,0.319024,0.375105,-0.574482,0.505889,0.037722,0.284986,-0.464786,-0.292079,0.535124,0.214537,0.081552,0.206532,0.128896,-0.067965,0.039929,-0.082728,0.458895', '25721544', '1308837', '30345227', '1849026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461964', '小兵张嘎', '剧情', '抗日战争时期的河北白洋淀，调皮莽撞的少年张嘎（安吉斯）目睹奶奶为掩护八路军逃跑被日寇杀害后，只身来到县城要找到游击队排长罗金宝（张莹），好让他帮忙为奶奶报仇，哪想真遇见罗金宝时，他将对方当作了汉奸，闹了笑话。误会解除后，张嘎梦想成为一名小八路，并想拥有一把枪，结果因为太想得到枪，他不但在和胖墩（吴克勤）打赌时耍赖，还违反纪律将某次战斗中收缴到的真枪偷偷藏在了树上的鸟窝里，再闹笑话。张嘎可没将笑话当笑话看，想不通的他约上胖墩又来到县城，要自个替奶奶报仇。在县城，张嘎遇到鬼子龟田（葛存壮）和胖翻译（王澍），一番斗智斗勇，两人没从张嘎身上捞得什么好处。一些列事情经历后，张嘎由鲁莽捣蛋的少年成长为真正的八路军小侦察员。©豆瓣', '安吉斯', '崔嵬', 7.8, 37321, 'tt6485574', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2314095621.jpg', 1.2, 2.1, 24.3, 48.5, 23.9, '0.164345,-0.145346,-0.447185,0.287806,-0.294104,-0.433480,0.471359,-0.201609,-0.395075,0.071491,0.089666,0.560774,-0.157382,0.129541,-0.144892,-0.177494,-0.267350,-0.655541,0.026849,0.021002,-0.437472,-0.456740,-0.198911,-0.045782,-0.251600,-0.153132,0.315584,-0.083648,-0.391165,0.174852,0.235188,-0.085630,-0.019504,0.296155,-0.430989,0.232185,-0.224492,0.036509,-0.043856,0.147065,-0.025034,-0.305644,-0.269874,0.004102,0.063638,0.169707,0.722966,-0.148306,-0.010400,-0.301666,0.107171,-0.278274,-0.011498,0.068338,0.294171,-0.045815,0.271078,-0.130822,-0.128871,0.104967,0.081420,-0.151601,-0.432364,0.012825,-0.048226,-0.118274,-0.948012,-0.045162,0.184083,0.138480,0.516336,-0.234356,0.376123,0.444429,0.142361,0.177431,-0.309170,0.119971,-0.531256,0.338647,0.612494,-0.395328,0.438960,0.097434,0.461335,-0.245860,0.363074,-0.279100,-0.349745,0.196280,0.201756,-0.455037,-0.314067,-0.108192,-0.471425,-0.247158,-0.248670,-0.108109,0.029227,-0.320577,-0.055583,0.078822,-0.080273,-0.058779,-0.310223,0.258954,0.011502,-0.265100,0.421374,-0.559073,0.190639,0.529234,0.128619,-0.285225,0.568332,0.244717,0.052735,-0.086332,0.051709,-0.258740,0.284414,0.364559,0.456365,0.312740,-0.078407,-0.539397,-0.076279,0.238699', '1306505', '1299965', '1291847', '1926007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461981', '鸡毛信', '儿童', '抗日战争时期，华北根据地龙门村有赵姓父子两人，父亲（舒适）是民兵队中队长，12岁的儿子海娃（蔡元元）则是儿童团团长。某天，赵父让海娃给八路军送一封有关攻打日军炮楼的鸡毛信，海娃装扮成放羊娃赶着一群羊携信上路。路途，海娃遇到敌人，急中生智把信藏在绵羊的尾巴之下，逃过一劫。海娃被迫带路，晚上却趁敌人熟睡取信逃跑，中间信一度得而复失、失而复得，海娃也再落敌人之手，这回，聪明勇敢的他将敌人引上了歧途，而敌人发现上当时，打伤了海娃的手，这时，八路军赶到。©豆瓣', '蔡元元', '石挥', 7.3, 11631, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2327156580.jpg', 1.4, 2.9, 38.7, 41.8, 15.1, '0.310412,-0.226219,-0.561606,0.295182,-0.016733,0.019279,0.238239,-0.071613,-0.325540,0.075316,0.371258,0.465644,0.519473,0.272713,0.120040,-0.301707,-0.084311,-0.564137,-0.202813,0.087177,-0.335232,-0.142159,-0.110566,-0.020857,0.097546,-0.148430,0.432867,0.065946,-0.046015,0.546757,0.102994,0.189067,-0.166733,0.226975,-0.278673,0.347947,-0.106580,-0.499365,-0.097795,0.269605,-0.231272,-0.107069,-0.084475,0.047128,-0.002159,0.177543,0.793206,-0.037645,-0.108086,-0.250280,0.045145,-0.387924,-0.000461,0.109762,0.523675,-0.133146,0.070903,-0.093109,0.189264,0.010338,0.151694,-0.000036,-0.181643,0.279694,-0.270320,-0.122838,-0.730498,-0.034097,0.014536,0.462395,0.326143,-0.367786,0.453409,0.536288,0.036042,0.109384,-0.221942,0.090710,-0.418388,0.036693,0.573482,-0.346349,0.297976,-0.161351,0.025643,0.067021,0.614623,-0.168135,-0.167734,0.016929,0.568163,-0.123935,-0.198975,-0.225470,-0.408019,-0.095758,-0.361849,0.029944,0.075542,-0.311739,-0.106469,-0.237675,0.108912,-0.155275,-0.290265,0.433569,0.030421,-0.019069,0.477602,-0.065426,0.011419,0.596150,0.296976,-0.132733,0.476565,0.006848,0.091457,0.016402,0.175481,0.151087,0.135013,0.385397,0.239514,0.088592,-0.443635,-0.204688,-0.316799,0.137451', '1451563', '25837175', '4009651', '1466273');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1461985', '闪闪的红星', '剧情', '故事发生在红军长征离开后的江西苏区。少年潘冬子（祝新运 饰）的父亲响应号召，参加红军抗击敌军去了，只剩下母亲与东子相依为命。母亲也是抗敌的积极分子，从小耳濡目染的冬子虽然只有11岁，也立下了决心长大参加红军对抗日军。一天，反动地主胡汗三前来捉拿东子的母亲，眼看形势危急，冬子妈决定留下来掩护其他群众撤退。在连扔两枚手榴弹砸死多名敌人后，冬子妈亦英勇就义。目睹了妈妈被敌人杀害的惨况，冬子决心用自己的力量为母亲报仇。冬子开始用自己的机智与勇敢与敌人周旋，暗中帮当地的游击队送盐送信。通与敌人的斗争，冬子渐渐成长，替母亲报仇的时刻也终于来到。©豆瓣', '祝新运', '李俊', 7.6, 27332, 'tt1809343', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1789642491.jpg', 2.2, 3.2, 29, 45.8, 19.8, '-0.202729,-0.342100,-0.475697,0.251248,-0.218675,-0.331822,0.180853,0.141664,-0.267796,0.053345,0.297830,0.615777,0.491225,0.063065,-0.004246,-0.577672,-0.191355,-0.748394,-0.065076,0.169753,-0.122257,-0.456401,-0.035926,-0.201563,0.147834,-0.067342,0.535893,-0.074461,-0.070471,0.555566,0.268058,0.143856,-0.045791,0.373032,-0.177758,0.144234,-0.107184,-0.389345,-0.496534,-0.102012,0.030365,-0.248450,-0.142174,-0.019451,0.067178,0.236349,0.602064,-0.335590,0.065096,-0.246032,-0.045059,-0.392257,0.036975,0.352821,0.228732,0.138213,0.150848,0.175683,0.068418,0.091209,-0.257295,-0.042106,-0.476500,-0.051421,0.196675,-0.225336,-0.844513,0.213391,0.107798,0.270834,0.475541,-0.396193,0.174631,0.665543,-0.204617,0.273712,-0.546762,0.027513,-0.218794,0.189280,0.792603,-0.512588,0.307811,-0.186368,0.316951,-0.008438,0.369686,-0.214135,-0.306993,0.141426,0.215881,-0.258541,-0.117335,0.072264,-0.726222,-0.278666,-0.410593,-0.103548,0.177008,-0.411583,0.038318,-0.296377,-0.136450,-0.248725,-0.350379,0.222544,0.128253,-0.114846,0.888497,-0.492626,-0.020115,0.249952,0.294013,-0.577096,0.385230,0.169505,0.162716,0.008101,0.256243,0.239336,-0.069778,0.447137,0.215026,0.031402,0.032859,0.085254,-0.204324,0.042462', '34822138', '1482089', '35048413', '30463515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1462243', '孝子贤孙伺候着', '喜剧', '在民政局工作的陈二小（陈佩斯 饰）和舅舅（魏宗万 饰）是新旧两代白事工作者。陈二小的红白理事会提倡白事新办，响应法律号召推行火葬；他舅舅是位老资格的大了，坚决捍卫土葬风俗，与此同时向丧家放高利贷从中渔利。陈母（赵丽蓉 饰）年逾古稀，老脑筋一时无法转变。她生怕儿子将自己烧 掉，加上娘家哥哥煽风点火，陈母立逼着二小立下土葬的字据。寿辰前夕，二小的姐姐（丁嘉丽 饰）和姐夫（倪大红 饰）送来一口大红棺材祝寿，这让陈母的心事彻底了结。风水先生算出陈母须在农历九月期间躺在棺材里去阎王爷处报名，同时为了检验二小的孝心，陈母和哥哥想出假死的馊主意，由此也引出一连串惹人发笑的荒诞闹剧……©豆瓣', '陈佩斯', '陈佩斯', 8.7, 17801, 'tt0353017', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2690073198.jpg', 0.3, 0.8, 10.7, 40.3, 47.8, '-0.038167,0.017074,-0.412782,0.363445,-0.091359,-0.198595,0.377064,0.270529,-0.437880,-0.192895,0.090589,0.304126,-0.273407,0.290082,-0.060353,-0.190294,-0.051987,-0.407239,-0.207857,0.017274,-0.265005,-0.312351,0.164187,-0.264841,-0.104828,0.032755,0.037965,0.044567,-0.141035,0.019738,0.563239,0.146373,-0.193961,0.088446,-0.195714,0.040785,-0.401881,0.137541,-0.137533,-0.134176,0.276314,-0.367777,-0.134467,-0.045144,0.383511,0.399987,0.326883,-0.249974,-0.000237,-0.196373,0.413871,-0.184227,-0.019452,0.470634,0.225305,0.080952,0.213030,0.161050,-0.250456,-0.082536,0.139361,-0.133174,-0.302153,0.125351,0.235661,0.074017,-0.783192,0.506442,-0.161676,-0.090231,0.064559,-0.355960,0.354197,0.315616,0.090544,0.381168,-0.072453,0.064027,-0.500824,0.586912,0.199716,0.021681,0.285234,-0.087424,-0.199498,-0.161829,0.298198,-0.061283,-0.111063,-0.114058,0.419783,-0.291346,0.201959,-0.059016,-0.275697,-0.562156,-0.107525,-0.264398,0.269952,-0.210944,-0.069324,-0.030884,0.040704,-0.233571,-0.093233,0.195258,0.212695,-0.161626,0.419570,-0.310828,-0.035252,-0.046827,0.110476,-0.385177,0.561771,0.173872,0.201238,-0.326242,0.012370,-0.265774,-0.013163,0.289998,0.292275,0.233864,0.123614,-0.190173,-0.147120,0.168868', '1306505', '1293607', '1316525', '1305201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1462467', '卖身契', '喜剧', '志文（许冠文 饰）是电视台一名跑龙套，自认为很有才华，所以一直郁郁不得志。志文的弟弟志新（许冠英 饰）是一个天才发明家，最近他发明了一部笑弹机，能让人大笑不止。正当志文得过且过之时，另外一家电视台请他去客窜一回主持，志文信心十足、带着弟弟的新发明前往晚会现场，志文的卖力 表演和笑弹机的威力令在场的所有人都大笑不已，节目的效果超过了预期。于是，这家电视台许诺高薪想挖志文过来。志文也十分想走，无奈自己和原来的电视台签了8年的卖身契，如果违约将承担巨额赔款。一个晚上，兄弟俩一起潜入了电视台的保险库，想将卖身契偷回来……©豆瓣', '许冠文', '许冠文', 7.8, 6938, 'tt0077892', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1176284861.jpg', 0.3, 2.2, 26.2, 48.2, 23.1, '0.055445,-0.137617,-0.556806,0.390196,-0.035456,-0.301155,0.412386,0.243657,-0.431577,0.025282,0.219436,0.855249,-0.274615,0.155704,0.081167,-0.054055,-0.212316,-0.488175,-0.058835,-0.315296,0.101741,-0.255726,0.160711,0.029354,-0.166492,0.052139,0.200661,-0.252679,0.042196,0.663558,0.305877,0.075513,0.142618,0.481774,-0.037887,-0.120887,0.240363,-0.121916,-0.330979,0.213034,0.134736,-0.090902,-0.306591,0.169079,0.268860,0.029282,0.605138,0.254815,-0.203264,0.082009,0.087116,-0.324850,-0.066603,0.184659,0.045660,0.303451,0.427296,0.170464,-0.489346,0.077574,0.067806,0.011768,-1.022512,0.281798,0.136928,-0.131536,-0.491402,0.326161,-0.159091,-0.019287,0.082720,-0.549224,0.409622,0.284198,0.087543,0.331528,-0.134704,0.151897,-0.611328,0.445790,0.561624,-0.080386,0.171889,0.144937,0.148000,-0.197741,0.072969,-0.038121,-0.565827,0.158868,0.109309,-0.084991,0.051360,-0.389130,-0.556522,0.166676,-0.141989,-0.298495,-0.037872,-0.613656,-0.217356,-0.469078,-0.067059,-0.011835,-0.062824,-0.211497,0.281789,-0.268464,0.919033,-0.516791,-0.207096,0.357215,0.369719,-0.544816,0.675972,0.350653,-0.049234,-0.041078,-0.109530,-0.487101,-0.133843,0.452432,0.144911,0.300933,0.249030,-0.722512,-0.103601,0.183835', '26678784', '27602116', '30163500', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1462631', '最后的假期', '剧情', '体态丰腴的黑人女子乔姬娅（奎恩•拉提法 Queen Latifah 饰）是新奥尔良一家餐饮厨具连锁店的普通店员，生活在社会底层的她生性乐观，总是幻想无数的可能。她喜爱美食，暗暗喜欢着一位男同事，然而因种种原因这些都无一达成。某天，一个意外改变了乔姬娅的人生，在医院的例行检查中，她被诊断患有名为“蓝氏综合症”的绝症，只剩下三周左右的生命。倍感绝望的乔姬娅决定尽情享受最后的时光，她辞去工作，取出所有积蓄，乘飞机前往欧洲，只为品尝仰慕已久的名厨戴笛尔（杰拉尔•德帕迪约 Gérard Depardieu 饰）的手艺。在此期间，她入住昂贵的总统套房，滑雪、做SPA、游走上流社交圈。她的个性言语与生活作风引起了名流们的注意……©豆瓣', '奎恩·拉提法', '王颖', 8.3, 22283, 'tt0408985', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315872583.jpg', 0.2, 1.1, 16.9, 46.6, 35.2, '0.235671,0.048186,-0.529811,0.249386,-0.117898,-0.145788,0.724879,0.295316,-0.465240,-0.376313,0.252567,0.671437,-0.209477,0.318911,0.269195,-0.046149,-0.037279,-0.568299,-0.083126,0.025478,-0.082511,-0.112543,-0.201906,-0.241711,-0.120891,-0.235626,0.316998,0.112357,-0.209335,0.579975,0.223024,0.191929,0.082947,0.376656,-0.342615,-0.299653,0.126261,0.028063,-0.171668,0.084243,-0.060103,-0.193562,0.027283,0.209554,0.062256,0.425251,0.772572,-0.072707,-0.254725,-0.005143,0.543722,-0.101191,-0.003556,0.134977,0.126718,0.222765,-0.001888,-0.001701,-0.352585,0.157860,0.133988,-0.013808,-0.823689,-0.295707,0.087208,0.115640,-0.523377,0.477352,-0.029871,-0.180520,-0.156441,-0.358288,0.105687,0.097573,0.048354,0.350650,0.113669,0.270137,-0.368714,0.541277,0.658046,-0.006048,-0.329168,0.257116,-0.601768,-0.396181,0.069645,-0.283046,-0.403594,-0.321711,0.009645,0.190106,-0.009323,0.095829,-0.534270,0.125113,-0.119567,-0.601169,0.201350,-0.185068,-0.245929,-0.717792,-0.055874,-0.361813,-0.384815,-0.179145,0.263484,-0.123324,0.721027,-0.678426,0.240788,0.509761,0.089967,-0.680514,0.841719,0.117887,0.226999,0.115008,-0.217786,0.490006,-0.042786,0.050840,-0.166327,0.473718,-0.213570,0.050499,-0.552132,0.400587', '3096161', '2027945', '3811356', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1462839', '金田一少年事件簿之上海人鱼传说', '喜剧', '中国上海杨氏剧团的团长头戴他亲手制作的面具被人枪杀后，其子杨小龙因无不在场证据遭警察怀疑。因为深信大哥是清白的，杨小龙的妹妹杨蕾丽（水川麻美）写信到日本，拜托七濑美雪（友坂理惠）和著名侦探金田一（堂本刚）接手此案，金田一本无心过问，可是没能禁受住杨蕾丽的美貌。金田一和 七赖美雪来到上海后，对一切都充满好奇，杨氏剧团的演出更令他们惊叹不已。可是当他们找到杨蕾丽询问事情始终时，发现剧团的人尤其杨小龙，态度十分冷淡，似乎并不欢迎他们的到来，这令两人一时之间丈二和尚摸不着头脑。©豆瓣', '堂本刚', '堤幸彦', 7.7, 6226, 'tt0298384', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p927840993.jpg', 0.5, 2.7, 30.6, 43.3, 22.9, '0.190091,-0.080110,-0.620745,0.211568,-0.112056,-0.200478,0.446822,-0.127202,-0.797446,-0.647885,0.098308,0.453765,-0.435683,0.085995,0.118688,-0.051948,-0.326470,-0.481033,-0.185903,-0.119840,-0.006985,-0.329114,0.150783,-0.251208,-0.343593,0.019709,0.410775,0.016069,0.003151,0.684971,0.350296,0.493341,-0.075601,0.655198,0.159349,0.178393,0.123650,0.184179,-0.159832,0.026485,0.168413,-0.192380,-0.279022,0.539159,0.048191,0.359503,0.553825,-0.092480,-0.369314,-0.153850,0.176092,-0.373067,0.128397,0.214055,0.415484,-0.016801,0.091120,0.164994,-0.240763,-0.088594,-0.077315,0.092959,-0.509392,0.254198,0.279848,0.231135,-0.449083,0.005291,-0.221037,-0.038506,0.158490,-0.433301,0.451230,0.115249,0.374411,0.307739,0.084241,0.203913,-0.485837,0.139563,0.659098,0.089439,0.184188,0.019212,-0.081477,-0.568825,0.029371,-0.185400,-0.450507,0.476111,0.051277,0.100730,0.110680,-0.031255,-0.240748,-0.435513,0.042066,-0.154148,0.051940,-0.576655,0.127651,-0.450337,-0.008012,-0.623994,-0.213404,0.017782,0.180339,-0.173478,0.693369,-0.797322,-0.072908,0.004736,0.155243,-0.547152,0.461053,0.206631,-0.026829,-0.370936,-0.279982,-0.208343,0.308868,0.315094,0.199019,0.239362,0.198433,-0.335163,-0.105043,0.049583', '35030151', '1301022', '22555690', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1463357', '至尊三十六计之偷天换日', '喜剧', '千术高手钱文迪（刘德华 饰）与女友莉莉（钟丽缇 饰）、好友“金手指”阿智配合，在赌局中赢得富豪刘耀祖六百万港币。发现自己被骗的刘耀祖怒不可遏，绑架阿智要挟文迪为其入狱，以便从犯人鲁宾孙（关海山 饰）手中拿回刘的三亿财产。文迪担心好友安危只得服从，入狱执行任务，进入了冤家——狱警杀手雄（梁家辉 饰）的势力范围。文迪在狱中凭借过人手段很快站稳脚跟，甚至连杀手雄也一并收服。随着文迪与鲁宾孙接触日深，他发现鲁宾孙居然是刘耀祖岳父。原来刘耀祖觊觎鲁宾孙财产多时，为此不惜将妻子杀害，鲁宾孙替女儿报仇反遭陷害，落得在牢中晚景凄凉。正义感勃发的文迪决定帮鲁宾孙讨回公道，遂联合杀手雄夺取刘耀祖的不义之财……©豆瓣', '刘德华', '王晶', 7, 12279, 'tt0107806', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2351357406.jpg', 1, 5.9, 45.6, 34.9, 12.6, '-0.237093,0.023361,-0.314217,0.233117,-0.280318,-0.364388,0.208295,0.156318,-0.410597,-0.392588,0.188451,0.390495,0.025101,0.043534,0.215105,-0.306913,-0.006776,-0.595196,-0.065564,-0.102290,0.011535,-0.559996,0.077730,-0.315956,-0.094970,-0.142420,0.358139,-0.035570,-0.253149,0.470434,0.556694,0.331683,-0.247527,0.309822,0.068283,0.330743,0.138429,-0.145361,-0.562396,0.097331,0.098113,-0.399461,0.273051,-0.007185,0.140942,0.410824,0.534705,-0.219320,0.010298,-0.267963,0.141755,-0.280962,-0.206641,0.008999,0.406118,-0.012542,0.108261,0.396123,-0.284550,-0.122637,0.272757,-0.055223,-0.543803,-0.110414,0.373407,-0.195854,-0.461225,-0.291957,-0.372169,0.455213,-0.222100,-0.123565,0.180951,0.187162,-0.051827,0.263311,-0.195639,0.135478,-0.590099,0.457663,0.449809,-0.404685,0.523130,-0.259373,0.350176,-0.123877,0.223844,-0.416616,-0.374069,-0.050383,0.390505,-0.249743,0.196167,0.108713,-0.316002,-0.480379,-0.489469,0.363405,0.189621,-0.437438,-0.065878,-0.171581,-0.101735,0.075457,0.049364,0.027546,0.071687,-0.554850,0.538807,-0.560823,-0.103164,0.126340,0.469526,-0.666038,0.213031,-0.118884,0.178667,-0.234723,-0.062026,-0.079308,0.550591,0.228176,0.507049,-0.191739,-0.068367,-0.311368,0.293320,-0.188713', '1302110', '1410695', '1297574', '1297862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1463390', '南征北战', '剧情', '1947年初，解放军华东部队在苏北七战七捷后，进行战略性转移，一营高营长（冯喆 饰）率领部队北撤，在山东桃村集结待命。不少战士和老乡都想不通，高营长和女村长赵玉敏（张瑞芳 饰）耐心给大家做工作。此时蒋军共出动25个师的兵力，企图造成南北夹击。我军在桃村大沙河阻击南线敌人六昼曰，主力部队集中到风凰山围歼北线的国民党李军长（阳华 饰）率领的七个师。高营长接到师长（陈戈 饰）命令抢占摩天岭高地，以阻击敌军张军长（项堃 饰）率领的增援部队，李军长率领的部队已被我军全歼并活捉李军长。高营长又率领部队乘胜追击张军长率领的部队，赵村长也带领游击队配合主力部队，切断敌人退路，又绞断敌人企图炸毁桥梁的炸药导火线，保住了大桥。一场大战开始了......©豆瓣', '陈戈', '成荫', 7.5, 5224, 'tt0352615', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2703824728.jpg', 1.5, 4.1, 33.2, 41.1, 20.1, '-0.131870,-0.234989,-0.825378,0.743823,0.189321,0.023088,0.256018,0.037282,0.016032,0.207742,0.252846,-0.212801,0.743075,-0.285228,0.107326,-0.700883,-0.224105,-0.763237,-0.148142,0.058885,-0.267283,-0.627760,-0.175451,-0.253509,0.333730,-0.167353,0.563289,0.192342,-0.222850,0.389176,0.172236,0.108965,0.296232,0.561131,0.433929,0.326169,0.132777,-0.757699,-0.311072,0.050127,-0.344424,-0.261862,-0.085492,-0.222746,0.205162,0.559903,0.962022,-0.235735,0.081357,0.155464,-0.552373,-0.359528,0.396521,-0.074049,1.081666,0.049137,-0.197566,-0.307062,0.053307,0.201422,-0.488886,0.125014,-0.234712,-0.142339,0.198575,-0.322801,-0.457869,0.057387,-0.144723,0.721508,0.471792,-0.546431,-0.062465,0.933384,0.028498,-0.055893,-0.176282,0.190718,-0.489470,0.191069,0.454713,-0.331065,-0.004836,-0.860916,0.408606,-0.364134,0.108409,-0.162977,-0.070359,0.258054,0.254938,-0.501001,0.935486,-0.164647,-0.555879,-0.068194,-0.334454,-0.212374,0.050791,-0.062688,0.325794,-0.630466,0.286847,0.016153,0.205285,0.820437,0.294441,0.523240,0.586533,-0.235488,-0.430476,-0.097171,0.326779,-0.596412,0.203429,0.398610,0.176220,-0.232514,0.530769,-0.063638,0.002086,0.800301,0.824911,0.453203,-0.542218,-0.234810,-0.079558,-0.107495', '1307201', '35231379', '1482707', '1464618');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1463787', '棒球英豪', '剧情', '比邻而居的浅仓和上杉两户人家关系密切，两家的娃娃小南（长泽雅美 饰）与双胞胎兄弟达也（齐藤祥太 饰）、和也（齐藤庆太 饰）更是从小玩到大的好朋友。受父母的影响，三个孩子对棒球情有独钟，他们相约共同走入宛如圣地的甲子园。步入青春时代，别样的情怀在少男少女心间萌生。弟弟和也率领球队挺进甲子园，成为学校内的风云人物。小南担任棒球部经理，守护着青梅竹马每一天。哥哥达也拥有比弟弟更出色的棒球才能，但是上了高中后却放弃棒球，加入拳击部。个中情思，谁人能知。一场意外，却改变了少男少女的人生……本片根据安达充同名漫画改编。©豆瓣', '长泽雅美', '犬童一心', 6.9, 5615, 'tt0489569', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p662443095.jpg', 1.4, 8.7, 45.9, 29.5, 14.4, '0.162874,-0.192066,-0.342082,0.449763,0.230927,-0.283465,0.420407,0.134539,-0.555165,-0.215380,-0.101212,0.676938,-0.111998,0.330795,0.210561,-0.312614,-0.137138,-0.711487,-0.145895,-0.267799,-0.068873,-0.303180,-0.058495,0.307206,-0.060983,-0.099132,0.728704,-0.063191,-0.146814,0.601996,0.232282,0.075114,-0.119569,0.013168,-0.047608,0.049896,0.028793,0.392073,-0.288850,0.137498,-0.105864,0.080011,0.093683,-0.276839,0.157074,0.005982,0.743807,-0.287084,-0.155569,-0.495233,0.198593,0.182669,-0.356313,0.049674,0.364634,0.177366,0.383175,0.178735,-0.082261,0.122115,-0.063671,-0.405695,-0.452851,0.131861,0.441243,-0.093398,-0.703156,0.558910,0.152325,-0.357301,0.128755,-0.021500,0.080440,0.312121,0.167462,0.367405,-0.324617,-0.129894,-0.344786,0.139016,0.908439,-0.040678,-0.025906,-0.038189,-0.163639,-0.504445,-0.311050,-0.262986,-0.555247,0.224805,-0.083357,0.003550,0.180018,0.098081,-0.508693,0.355387,-0.113625,0.177236,0.156617,-0.812155,0.232432,-0.601100,0.133111,-0.515111,-0.473370,0.169448,0.300106,-0.389134,0.945374,-0.998210,0.074277,0.106779,0.516965,-0.214441,0.808695,-0.012446,0.090708,-0.530213,-0.256540,0.294374,-0.115729,-0.015567,-0.055280,0.393818,-0.242684,-0.175705,-0.185755,0.232843', '3445516', '35030151', '35048413', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1463961', '芳香之旅', '剧情', '上个世纪60年代，情窦初开的少女李春芬（张静初饰）是个女售票员，她迷倒了许多男乘客，当然也包括师傅老崔（范伟饰），他受到过毛泽东接见。但是春芬情窦初开的爱人却是从上海来的刘奋斗（聂远饰），他英俊飘逸，令春芬怦然心动，可当刘奋斗刚要示爱时，就被当作流氓而发配去劳动改造了。命运翻覆，春芬最后选择嫁给了年长自己许多的师傅老崔。有了婚姻的春芬，身体却如花苞，因为车祸后的老崔失去了男性能力，直到老崔去世，春芬才恍然知晓了，肉体上做不到男人的老崔，穷其所能证明他在精神上是个完完全全的男人。弹指一挥间，几十年过去了，春芬决定延续她的芳香之旅……©豆瓣', '张静初', '章家瑞', 7.1, 10415, 'tt0470302', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2185202929.jpg', 0.9, 5.2, 42.3, 39.9, 11.7, '-0.146276,-0.062111,-0.574711,0.439710,-0.508920,-0.700172,0.893948,-0.011931,-0.383619,-0.369427,-0.205709,0.522783,-0.119024,0.692882,0.286185,-0.049624,0.060901,-0.412330,-0.232515,-0.299633,-0.567836,-0.285282,0.037576,-0.198099,-0.255546,0.191566,0.429007,0.090313,-0.295116,0.119177,0.593778,0.011502,0.391422,0.559794,-0.340921,0.396146,0.003889,0.042582,0.072357,-0.203095,0.315056,-0.430422,-0.141978,0.134133,-0.161583,0.367375,0.507332,-0.053704,-0.097047,-0.315336,0.425030,0.043738,0.124189,0.272319,0.359103,0.065276,-0.063569,-0.146929,-0.138151,-0.122037,0.072319,-0.053598,-0.371962,0.238608,0.183094,-0.191290,-0.611036,0.017012,0.141508,0.142777,-0.164261,-0.517457,0.192952,0.066675,0.337652,0.272999,-0.068355,0.120292,-0.496224,0.705090,0.718584,0.368401,-0.485029,0.499958,-0.233269,-0.559618,-0.080845,-0.216140,-0.389720,0.137215,0.434902,0.060238,-0.189155,0.077434,-0.192744,-0.440185,-0.110762,0.075297,-0.016250,-0.201730,-0.103623,-0.211913,-0.331143,-0.614335,-0.199301,0.263899,0.094651,-0.323737,0.869620,-0.655909,0.188641,0.539382,-0.099650,-0.762884,0.715900,0.083818,0.147099,-0.164739,0.321740,0.577999,0.052363,0.306812,0.237961,0.330740,-0.280795,-0.082864,-0.060346,0.414673', '25828521', '1306755', '24879820', '1394424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464338', '最爱女人购物狂', '喜剧', '被弃置在百货公司内的婴孩长大后，成为超级购物狂方芳芳（张柏芝），因为无法控制自己的购物欲望，方芳芳陷入经济困境，而更要命的，是她因此连番失业，痛定思痛之后，她决定去看精神科医生，不想这个非一般的精神科医生李简仁（刘青云）有选择恐惧症。看病过程中，李简仁的护士早产，方芳芳协助保下母子平安，因此获得工作，但条件是要帮李简仁解决选择问题。不久方芳芳遇上同她一样患有购物狂症状的何穷富（陈小春），建议其看心理医生，但何穷富生性吝啬嫌医生费贵，方芳芳只好充当医生帮他治疗。方芳芳正为信用卡债务苦恼之际，发现何穷富与李简仁都是香港大富豪，而与此同时，他们两个又同时约会她，令她如在梦中同时应答了两个约会。©豆瓣', '刘青云', '韦家辉', 6.2, 55770, 'tt0491002', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554728015.jpg', 3.1, 15.7, 54.3, 19.9, 7, '-0.044435,0.003380,-0.406102,0.131451,-0.205730,-0.345989,0.575766,0.163955,-0.491480,-0.518601,-0.024618,0.538249,0.100498,0.376218,0.009601,-0.314748,-0.119655,-0.487918,0.060665,0.034940,-0.494708,-0.373030,0.119668,-0.338774,-0.149677,-0.220517,0.435276,-0.065561,-0.304289,0.096341,0.270535,0.394359,0.096139,0.568861,-0.132421,-0.105275,-0.064404,0.021581,-0.401354,0.531147,0.502398,-0.140128,-0.077151,0.254284,0.123954,0.334140,0.512973,0.099842,-0.260573,-0.235348,0.338569,-0.305258,-0.206522,0.023374,0.176482,0.010646,0.420280,-0.211073,-0.407053,-0.114259,0.126929,0.058250,-0.552607,0.035420,0.324839,0.260970,-0.583917,-0.027160,-0.096616,-0.084800,0.023954,-0.397528,0.215121,0.351036,0.327097,0.410988,-0.143482,-0.103806,-0.492500,0.235615,0.810775,0.249916,-0.018902,0.397337,-0.344638,-0.567138,0.379493,-0.198909,-0.362082,0.182425,0.086806,0.106608,-0.329562,0.068077,-0.140409,-0.056395,-0.282185,-0.159922,-0.320480,-0.327917,0.273799,-0.468653,0.104415,-0.137586,-0.123855,0.072925,0.076443,-0.341348,0.597622,-0.767459,0.065284,0.399989,0.477442,-0.796110,0.707091,0.164961,0.320822,-0.279640,0.200487,0.002910,0.100213,0.166740,0.108214,-0.000494,-0.088538,-0.196143,-0.320825,0.153362', '1877596', '1293265', '1949320', '1305915');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464449', '穿越时空的思念', '动作', '元军攻打日本之际，中国大陆的妖怪为了得到死者魂魄亦东渡日本。在这里，他们遭遇了犬夜叉的父亲斗牙王。经过一番艰苦鏖战，大陆妖怪最终被封印在斗牙王的牙齿中。时间回到战国时代，四魂之玉的一枚碎片飞到不归之森，唤醒了大陆妖怪首领之子玛瑙丸。为了解开被斗牙王牙齿所封印的力量，玛瑙丸派随从琉璃、玻璃将犬夜叉一行人引到不归之森，并诱使犬夜叉用铁碎牙斩断结界。结界消失，被封印上百年的力量开始复活，玛瑙丸变得愈加强大。与此同时，玻璃和琉璃分别夺去了珊瑚的云母和法师的风穴，使犬夜叉一方陷入苦战；另一方面，戈薇的意识被玛瑙丸控制，她迫不得已用箭再次将犬夜叉封印，之后更被桔梗推入枯井，穿越时空回到了现代……©豆瓣', '山口胜平', '筱原俊哉', 8.5, 16571, 'tt0322645', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2517464938.jpg', 0.2, 1, 14.6, 41, 43.2, '-0.068500,0.566310,-0.361814,0.461283,-0.222761,0.178080,0.617624,0.050507,-0.346660,-0.150302,0.074087,0.499696,-0.110683,-0.102734,-0.035343,0.236610,0.224547,-0.536493,0.006788,-0.197705,-0.498438,-0.000238,-0.347472,0.152476,-0.249281,-0.808404,0.958482,0.263907,-0.060886,-0.047781,-0.330003,0.497463,-0.274912,0.305837,-0.019923,0.147668,-0.068135,-0.265411,-0.097065,0.415886,-0.157500,-0.380183,0.427277,0.540658,-0.309722,-0.138047,0.904810,-0.519868,0.273000,-0.467936,-0.000169,-0.284003,-0.390669,0.335375,0.514828,0.146197,-0.072526,0.122225,-0.391697,0.034912,0.439155,0.010750,-0.476480,-0.053944,0.146031,0.021219,-0.341007,0.323271,0.036270,0.278043,-0.326756,-0.362150,0.469654,0.513676,0.292338,0.173748,-0.377955,-0.358976,-0.499559,-0.099891,0.680945,-0.585064,-0.088798,0.016715,0.001221,-0.321285,-0.078351,-0.028628,0.380715,-0.068151,0.796502,0.461920,-0.287877,0.372008,-0.964948,-0.235029,-0.422973,-0.171433,0.179190,-0.302761,-0.202591,-0.372131,-0.222234,0.094326,0.115271,0.011685,0.045009,0.094067,0.624484,-0.631907,0.135973,0.394127,0.496551,0.011479,0.219253,-0.391625,0.076801,-0.298459,0.111842,0.480583,0.340694,0.639055,0.432134,0.203292,0.093909,0.242616,-0.674114,0.244656', '26290398', '1293531', '26759819', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464452', '犬夜叉：红莲之蓬莱岛', '喜剧', '蓬莱岛，相传为古时候的神之岛，秦始皇曾派徐福及三千童男童女寻找蓬莱，以觅长生不老之方。岛上生活着人类、妖怪和半妖，他们和睦相处，自由自在。为了防止半妖受到伤害，巫女奏使用法术使蓬莱岛隐藏起来，每隔50年才会伴着浓雾出现一次。然而邪恶的四斗神趁小岛结界虚弱之际潜入，污染鸣动之窑，对岛上居民进行无情统治和屠杀。在戈薇到达战国时代的50年前，犬夜叉曾和桔梗乘船登上蓬莱，结果遭遇四斗神。在交战中，犬夜叉的力量被四斗神封印。50年后，蓬莱岛再次出现。半妖阿蓝趁机逃出，遭到四斗神一路追杀，最后幸被犬夜叉一行救下。为了拯救岛上居民，犬夜叉、戈薇等人决定踏入蓬莱。另一方面，阿蓝的姐姐浅葱决定跳入窑中保全兄弟姐妹们的性命……©豆瓣', '山口胜平', '筱原俊哉', 8, 13304, 'tt0473658', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2517464126.jpg', 0.3, 1.9, 25.6, 43.3, 29, '-0.203330,0.254602,-0.430687,0.408713,0.158498,-0.050131,0.276977,-0.289642,-0.337818,-0.318574,0.202375,0.498446,-0.042148,0.053485,0.308901,-0.088993,-0.034145,-0.470033,-0.132818,-0.145797,-0.323717,0.312395,-0.166938,0.045400,-0.539639,-0.760764,0.541271,0.417511,0.106444,0.349281,-0.315454,0.281478,-0.711261,0.231094,-0.088380,0.025833,-0.202274,-0.064974,-0.201942,0.622371,-0.490855,-0.418833,0.006751,0.202670,-0.144934,0.259232,0.742340,-0.760578,-0.066855,-0.470139,-0.141651,-0.457379,-0.322663,0.200689,0.532780,-0.160301,0.160933,0.272720,-0.132937,-0.152885,0.034227,-0.038685,-0.473271,-0.119062,0.094920,-0.111064,-0.356767,-0.149210,0.247693,0.046491,0.027551,-0.251945,0.212564,0.415567,0.457922,0.379657,-0.328669,-0.069927,-0.298447,-0.133094,0.830824,-0.462103,0.099283,-0.106027,0.203486,-0.365942,0.198311,-0.518804,0.153838,-0.022887,0.148272,0.031310,-0.106437,0.233898,-0.817518,-0.200479,-0.400151,-0.192209,0.024789,-0.056228,-0.127368,-0.611518,0.086485,-0.049849,-0.032022,0.084933,0.217203,-0.218590,0.405766,-0.747962,0.631455,0.429458,0.708829,-0.288832,0.521597,-0.186007,0.028793,-0.233209,0.034445,0.328122,0.108395,0.643020,-0.062807,-0.223056,-0.150003,0.248963,-0.517077,0.059618', '26863060', '4160441', '6982558', '1293531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464526', '横空出世', '剧情', '1949年新中国建立以来，虽然人民当家做主人，但是新政权还随时面临被海外敌对势力所颠覆的严峻现状。惨烈的抗美援朝战争结束后，曾经立下赫赫战功的冯石将军（李雪健 饰）接到中央委派的重要使命，那就是主持原子弹的研发工作。虽然对原子弹一窍不通，但是军人出身的冯石只有服从上级的命令，带着一支经过烈火淬炼的英雄部队挺近荒凉的戈壁滩。在此之后，以美国留学归来的陆光达（李幼斌 饰）等科学界的精英人才从四面八方调到了西北荒漠。白手起家，艰苦创业，在内无经验外断支援的艰苦条件下，一群怀着崇高理想的无名男儿朝着共同的目标奋勇前行……©豆瓣', '李雪健', '陈国星', 9.4, 66754, 'tt0459399', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p672536444.jpg', 0.2, 0.3, 3.6, 18.6, 77.2, '-0.139631,-0.031668,-0.814739,0.733801,0.053367,0.003538,0.189110,-0.139741,-0.544783,-0.212453,0.200138,0.517693,0.385978,0.019781,0.329015,-0.153140,-0.262264,-0.588154,-0.474025,-0.067562,-0.318035,-0.382131,-0.382932,-0.185448,-0.202015,-0.194203,0.837792,0.389173,-0.170404,0.441274,0.122480,0.303748,-0.039547,0.316132,-0.127913,-0.483181,0.143901,0.173068,-0.608372,0.114317,-0.147652,-0.160704,-0.112712,0.010048,0.004844,0.452482,0.243556,-0.362811,-0.054370,-0.331592,0.276597,-0.349132,-0.151719,-0.008561,0.500896,0.350734,-0.024079,0.273507,0.152255,0.155398,-0.451863,-0.435195,-0.812870,-0.442913,0.240091,0.047721,-0.680647,0.780854,0.017209,0.080853,0.078844,-0.242387,0.118769,0.539491,0.200182,0.549179,-0.287433,0.395307,-0.311550,0.216165,0.791205,-0.193904,-0.480406,-0.229987,-0.224404,-0.463650,0.349726,-0.376480,-0.352399,-0.062129,-0.048194,0.062631,0.187389,0.058105,-0.544355,0.329880,-0.162206,-0.302681,0.281374,-0.215831,-0.227175,-0.704819,0.034989,-0.484044,-0.123861,0.338145,0.294576,-0.097284,0.972664,-0.621289,-0.016658,0.042772,0.152565,-0.753598,0.346576,-0.007802,0.235521,-0.375289,-0.013480,0.353708,0.119904,0.681304,-0.116854,0.035276,-0.176351,-0.433060,-0.075471,0.280767', '27602116', '27040921', '1308424', '6424814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464540', '地雷战', '剧情', '抗日战争较为艰苦的1942年，胶东抗日根据地边缘村庄赵家庄等经常遭受日军的突袭，为了减少损失，区武委会雷主任（张长瑞）和赵家庄民兵队长赵虎（白大钧）集合群众的智慧，想出应对日军的策略：他们联合附近几个村庄组成民兵联防壮大武装力量的同时，用土制地雷组成各式各样的地雷阵，将日军沉重打击。日军为对付地雷阵，搬来工兵攻入赵家庄大肆烧杀抢掠，民兵们及时总结经验、吸取教训，不断改进制雷技术和布雷方法，使得日军防不胜防。进入麦收季节，日军本想趁民兵抢收麦子时一举拿下赵家庄，不想民兵早已设下了布局更为精妙的地雷阵。©豆瓣', '白大钧', '唐英奇', 8.1, 38356, 'tt6476542', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2688347980.jpg', 1.5, 2.1, 19, 47, 30.4, '0.114586,-0.506446,-0.393316,0.255200,0.105356,0.150288,0.123617,-0.302965,-0.457843,-0.021788,0.048650,-0.121153,0.383413,-0.376173,-0.215808,-0.733467,-0.327644,-0.491397,-0.229855,0.089543,-0.305075,-0.285557,-0.343920,-0.354933,0.122877,-0.244468,0.463429,0.435744,-0.303307,0.067028,-0.447327,0.254393,0.003237,0.211492,0.250907,0.087519,0.040514,-0.929824,-0.458088,0.224839,-0.619989,-0.323108,-0.392345,-0.162166,0.248486,0.363587,1.020999,-0.177044,0.147125,-0.327389,-0.189506,-0.145533,0.025195,0.248753,0.583462,0.120334,-0.024635,-0.082590,-0.054620,0.323650,-0.281117,-0.504529,-0.523865,0.001239,0.035903,-0.500893,-0.400957,0.076539,0.204842,0.308220,0.278650,-0.450630,0.146324,0.805652,0.430475,0.130239,-0.343946,0.030169,-0.266207,-0.113050,0.601918,-0.370385,0.095027,-0.471998,-0.255929,-0.162932,0.392061,-0.330114,0.277059,-0.046300,0.202975,-0.368581,0.267619,0.035461,-0.852678,0.253744,-0.334034,-0.469253,0.030965,0.159234,-0.197016,-1.028439,0.284141,0.085596,-0.208689,0.518774,0.069022,0.528717,0.708797,-0.460333,-0.345962,0.505469,0.316139,-0.325842,-0.153962,-0.063598,0.085280,0.063086,0.058167,-0.201720,0.003796,0.942776,0.392408,0.236906,-0.477045,-0.352047,0.104040,0.022103', '1466273', '1464618', '5403927', '1422938');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464548', '阿司匹林', '爱情', '面容憔悴的文静（梅婷 饰）是一名终日奔波、黑白颠倒的娱乐记者，她奔波于各种各样的聚会，应付脾气秉性各异的受访者，劳累不堪，疲于奔命。在这个有如染缸、物欲横流的娱乐圈中，文静没有选择沉沦与屈从，依旧真诚地期盼一份纯真爱情的到来。此前，她曾有过两段失败并且刻骨铭心的恋情，直到小白（宋宁 饰）的到来，才为她封闭的内心世界吹进一股清新的微风。两人的恋情至纯至真，波澜不惊，但是纯美从来不容于世，它总要经受现实残酷无情的碾压。小白憧憬着光明的前程，文静则面对美国投资公司总监李文卿（潘石屹 饰）的追求，他们各自在理想和现实中徘徊不定……©豆瓣', '曹俊', '鄢钷', 7.2, 16861, 'tt1522813', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2361446824.jpg', 1.2, 6.5, 37.7, 38.4, 16.2, '0.220402,0.256909,-0.625150,0.497685,-0.176589,-0.124856,0.788696,0.312623,-0.371426,-0.350962,0.337867,0.286218,-0.136623,0.347653,0.352038,-0.223936,-0.090458,-0.624577,-0.408498,0.110985,0.252128,-0.217512,-0.428127,0.104516,-0.191269,-0.135079,0.940053,0.164574,-0.187881,0.555803,0.219405,0.183094,-0.298956,0.497170,-0.127141,-0.125795,-0.186999,0.368213,-0.473090,-0.253874,0.090702,-0.294262,-0.202227,0.126388,-0.234866,0.251323,0.652845,-0.126960,-0.260657,0.144675,0.607125,-0.233235,-0.146923,0.140335,0.042999,0.070539,0.197360,0.127327,-0.178737,-0.001891,-0.183299,0.065025,-0.810821,-0.054093,0.216452,0.352254,-0.189213,0.541190,0.035013,-0.220104,-0.081543,-0.153863,-0.030711,0.154506,0.235252,0.574635,-0.132904,0.273378,-0.340679,0.379243,0.660148,0.250869,-0.504074,0.283926,-0.625698,-0.046140,0.028337,-0.458565,-0.932256,-0.233013,0.080925,0.021304,-0.056706,0.539434,-0.794175,0.310486,-0.224321,-0.120255,0.005654,-0.305013,-0.233539,-0.449507,-0.213735,-0.726443,-0.406906,0.063738,0.102743,-0.229476,0.756760,-0.833846,0.360952,0.360336,0.066491,-0.522191,0.701496,0.349217,0.003964,-0.173574,-0.077239,0.674247,-0.281630,0.100985,-0.195886,0.353449,-0.112599,0.165970,-0.547669,0.478861', '1296992', '1307884', '6772974', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464563', '冲出亚马逊', '剧情', '1999年，两名中国特种兵参加了国际猎人学校的特种兵训练，他们经受了种种极端考验，为中国特种兵赢得了荣誉，本片根据他们的故事改编而成。1999年8月，中国特种兵王辉（侯勇 饰）与胡小龙（穆立新 饰）远赴拉美的亚马逊河流域，在科林少将的猎人学校中接受严酷的训练。猎人学校有着高达六成的淘汰率，为了不让国旗被降下，王辉与胡小龙决心坚持到底。猎人学校的生活就是训练，他们在真子弹飞过的战地穿梭、接受饥饿训练等近乎人体生理极限的挑战，连学校医官丽娜也不忍这种不人道的方式而频频向教官抗议。在教官们化装成匪徒的最终考验中，当地的黑社会因自感生存空间被压缩向猎人学校进攻，并绑架了科林的女儿丽娜，王辉与胡小龙运用智慧和勇敢，拯救了危局。©豆瓣', '侯勇', '宋业明', 6.6, 48721, 'tt1501292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1798753903.jpg', 4, 10.4, 46, 29.9, 9.7, '0.189165,-0.262877,-0.329381,0.527720,-0.095667,-0.274601,0.277179,-0.106034,-0.524950,-0.278164,0.271606,0.374916,-0.011221,0.101265,0.310377,-0.584964,-0.191918,-0.655127,-0.334616,-0.040210,-0.374794,-0.438737,-0.114064,-0.242076,-0.087910,-0.196548,0.615498,-0.075706,-0.308290,0.650291,0.201649,0.340074,0.150437,0.213911,0.039853,-0.286559,0.308978,-0.170372,-0.313698,0.102974,0.175167,-0.120338,-0.159174,-0.111094,0.161494,0.180456,0.764642,-0.172277,0.041570,-0.307981,0.255067,-0.493529,-0.081728,0.146704,0.481680,-0.051712,-0.042816,0.106553,0.362581,0.187388,-0.177506,-0.298143,-0.681812,-0.157569,0.047028,-0.153233,-0.538528,0.255483,0.000627,0.087268,0.127136,-0.119374,-0.207294,0.334147,0.202638,0.586573,-0.256284,-0.119226,-0.413030,0.427698,0.642473,-0.103734,-0.443674,-0.315227,-0.396995,-0.762596,-0.038361,-0.448097,-0.312551,0.004823,0.239719,-0.049033,-0.200639,0.112242,-0.708218,0.007987,-0.246377,-0.300466,-0.045037,-0.261731,-0.113389,-0.948461,0.144641,-0.396482,-0.171614,0.074020,0.023044,-0.159946,0.782294,-0.918676,0.069405,0.518692,0.491708,-0.420023,0.635562,-0.026680,0.178253,-0.111374,-0.072207,0.166914,-0.009532,0.556908,0.253518,0.476905,0.053480,-0.141462,-0.138254,0.324659', '3811356', '2369613', '1420088', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464595', '神鞭', '动作', '清朝末年，天津城了出现一个恶霸地痞——玻璃花（陈宝国 饰），他无恶不作、欺行霸市。一日，卖豆腐的老实人傻二（王亚为 饰）和玻璃花较上了劲，争执中傻二甩开自己的辫子还击，玻璃花被抽得毫无还手之力，落荒而逃。不日玻璃花纠集了一伙武林高手来找傻二寻仇，憨二照样甩开自己又粗又长的还击，竟然打败了一众高手！从此“神鞭”傻二的名声传扬开来。八国联军入侵时，傻二加入了义和团，“神鞭”歼敌无数，立下了赫赫战功……©豆瓣', '王亚为', '张子恩', 7.1, 7772, 'tt0397625', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2411908751.jpg', 1, 3.8, 45, 37.5, 12.6, '0.088998,0.000566,-0.580967,0.240672,-0.245256,-0.113798,0.290805,0.279627,0.078465,0.190216,-0.099838,0.615768,-0.369285,-0.115558,-0.111411,-0.133908,0.223024,-0.836876,-0.206876,0.039555,0.111573,0.059889,-0.318890,-0.131878,0.056983,-0.091232,-0.000718,-0.057762,-0.512588,0.355558,0.350235,-0.089479,0.139002,0.085846,-0.228837,0.489972,-0.137736,-0.041588,0.457467,0.000828,-0.538990,-0.597361,0.072214,-0.060021,-0.359199,0.519417,0.357267,-0.236016,0.315272,-0.547486,0.192940,-0.156940,-0.400505,0.091218,0.527834,-0.234140,0.213138,-0.157398,-0.014192,-0.174444,0.240336,-0.104677,-0.322779,0.156271,-0.064837,-0.271389,-0.738308,0.409662,0.099758,0.088582,-0.325214,-0.161134,0.132118,0.295111,0.089152,0.111540,-0.084852,-0.058412,-0.831627,0.275851,0.438280,-0.266583,-0.107263,-0.190895,0.438653,0.119849,0.046370,-0.634733,0.048001,-0.401047,0.784546,-0.387728,-0.172377,0.000402,-0.544295,-0.133711,-0.534299,0.303744,-0.167262,0.134059,-0.258488,-0.233443,0.097386,-0.192419,-0.294626,0.318910,0.391707,0.074961,0.469824,-0.431726,-0.051258,0.327325,0.483910,-0.537658,0.362185,0.164788,-0.102167,0.330572,-0.143076,-0.249412,0.358898,0.356310,0.587405,0.305384,-0.455917,-0.424635,0.094063,0.258530', '1298667', '1300857', '1303462', '1305440');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464618', '狼牙山五壮士', '战争', '抗日战争时期的1941年秋，为了阻止日军对晋察冀边区进行大扫荡，八路军某部班长马宝玉（李长华）和战士葛振林（高保成）、宋学义（李力）、胡福才（霍德集）、胡德林（张怀志）五人接受任务登上狼牙山棋盘陀主峰。日军以三千兵力猛攻狼牙山，五位战士不畏势单力薄，凭借居高临下的有利地形，与拥有飞机、大炮的日军展开顽强的战斗：日军连续发起三次猛烈的冲锋，均被他们击退，胜利地完成了牵制日军的任务。弹尽粮绝之时，五位战士也没放弃与日军进行搏杀，战斗到最后一刻。©豆瓣', '李长华', '史文炽', 7.3, 11872, 'tt0354692', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2532680861.jpg', 1.8, 3.2, 38.6, 39.7, 16.7, '0.152657,-0.290592,-0.883932,0.713965,0.238182,0.128450,0.306214,-0.259444,0.149352,0.235050,0.701985,0.308214,0.273662,-0.499015,0.039670,-0.907445,0.099829,-0.768810,-0.181410,0.300406,-0.400589,-0.365365,-0.329886,-0.267953,0.042157,-0.182607,0.912417,0.411151,-0.390466,0.352682,0.109054,0.172757,0.282628,0.551305,0.269742,0.170326,0.071201,-0.836954,-0.374388,0.415645,-0.351809,-0.278268,-0.438590,0.187692,-0.100923,0.215854,1.028396,-0.536411,-0.052771,-0.375454,-0.513244,-0.444973,0.101767,0.243591,0.784409,0.163405,-0.061561,-0.148578,0.340806,0.195516,-0.412960,0.045871,-0.576438,-0.135266,-0.147976,-0.319770,-0.494188,0.531826,-0.233908,0.670926,0.319261,-0.374855,-0.248813,1.017243,0.117854,0.057248,-0.610231,-0.227387,-0.410649,0.082480,0.560416,-0.121620,-0.486448,-0.293285,0.223761,-0.491629,-0.043691,-0.651250,-0.067776,0.090568,0.325081,0.013614,0.537767,0.138030,-0.945527,0.219784,-0.333469,-0.327216,-0.167068,-0.030870,-0.179246,-1.169965,0.174832,-0.373743,-0.541276,0.494977,-0.016446,0.046501,0.901116,-0.570407,-0.208009,0.268716,0.388729,-0.129764,0.337571,0.282186,0.049890,-0.051872,0.370105,0.301935,-0.294902,0.757776,0.717060,0.208114,-0.438537,0.240781,-0.059030,0.320001', '1424551', '2369613', '35155748', '35058077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464633', '花季·雨季', '剧情', '深圳的一所高中里，一群年轻人在度过他们的花季雨季。他们中间，有沉稳可靠的女班长谢欣然（颜丹晨 饰），她家境普通，没有深圳户口，还要在暑假坚持打工；有因美丽多才而受关注的文艺委员刘夏（旸姿白云 饰），她与班上的篮球明星王笑天（李晨 饰）关系很好，是同学们口中的“一对”；有用《封神榜》中雷震子激励自己发奋读书的书呆子陈明（张超 饰），一心想要考上清华大学……在新任班主任江楠（曹蓬 饰）老师的凝聚力下，这群孩子从明朗的16岁花季进入敏感多思的17岁雨季，经历各种成长的烦恼，留下动人的青春故事……本片根据女作家郁秀16岁处女作《花季雨季》改编。©豆瓣', '颜丹晨', '戚健', 6.9, 6760, 'tt10195256', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2870187219.jpg', 1.2, 6.8, 47.7, 32.6, 11.7, '0.283721,-0.228283,-0.469361,0.387573,-0.357770,-0.078890,0.505333,0.050164,-0.270306,-0.368748,0.179769,0.337957,-0.181848,0.616526,0.268751,-0.207769,-0.052357,-0.462381,0.168855,-0.114661,-0.004612,-0.294470,-0.308415,0.170039,-0.357869,-0.208798,0.459030,-0.104573,0.184569,0.814638,0.279062,-0.102382,0.125421,0.083993,-0.313668,-0.090490,0.010362,0.255387,0.025020,0.198108,-0.148440,-0.086808,-0.310976,-0.362503,0.233558,0.287987,0.703783,0.327423,-0.094953,-0.024665,0.660330,-0.147002,-0.312085,0.204565,0.584553,-0.006810,0.179962,0.001008,-0.134335,0.084461,-0.282125,-0.523420,-0.189595,-0.099467,0.328762,0.168394,-0.412502,0.421412,0.145820,-0.174812,0.407738,-0.226100,-0.082940,0.194022,0.022340,0.549919,0.069113,0.159881,-0.100379,0.664532,0.527836,0.094359,-0.552314,0.105482,-0.492008,-0.291824,0.075821,-0.173824,-0.792654,0.207265,0.076507,-0.214537,-0.099364,-0.077544,-0.340607,0.175364,0.270412,0.009719,0.067808,-0.118646,-0.334447,-0.395520,-0.146846,-0.648179,-0.433110,-0.009037,0.053588,-0.330701,1.246974,-0.811142,-0.000072,0.313781,0.192768,-0.397633,0.604720,0.181991,0.156921,-0.204769,-0.081701,0.217117,-0.412952,0.181578,-0.375002,0.518178,-0.407666,-0.386132,-0.318830,0.309882', '25922902', '26348103', '1303010', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464901', '黑白战场', '剧情', '龙老四（曾志伟 饰）是黑道大哥，秘密鲸吞了一亿二千万的公款，准备和情投意合的小三阿姗私奔到国外。此事，引起了帮派四大天王的内斗，并引发血案。米探长（林雪 饰）奉命调查，但这人生性胆小，敷衍了事。帮派元老柴叔和小字辈发仔（余文乐 饰）目睹了这一切，觉得蹊跷，怀疑事出有因。发仔的恋人小玲（黄伊汶 饰）总是提心吊胆，生怕他出事，劝他不要介入。仅剩的天王（张耀扬 饰）怀疑龙老四才是幕后主使人，因此派手下前去调查，杀害了发仔的朋友。其弟跑来劝发仔躲避，不幸丧命，小玲也被误杀。发仔愤怒之极，此时抚养柴叔也卷入此案，发仔奋力营救，两人才逃出魔爪。龙老四私奔未成，遭到老婆与养子Peter仔暗算。危急时刻，柴叔与发仔正好杀到，由此引出一段鲜为人知的江湖隐情……©豆瓣', '余文乐', '钟少雄', 6.2, 3943, 'tt0489067', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515753293.jpg', 2.8, 14.9, 59.4, 17.6, 5.3, '-0.066041,-0.342068,-0.437248,0.132432,0.122936,-0.006351,0.437558,0.064069,-0.575578,-0.331363,0.264016,0.314168,-0.190279,0.040498,0.264672,-0.240471,-0.009648,-0.528449,0.085978,0.037354,0.126952,-0.255816,-0.126712,-0.221226,-0.193939,0.010612,0.256275,0.184246,-0.469622,0.474778,0.345154,0.398738,-0.622518,0.338472,-0.009866,0.230326,-0.013672,0.116128,-0.323671,-0.037030,-0.024833,-0.230598,0.011761,0.150558,0.174912,0.453496,0.334554,-0.241249,-0.114271,-0.170899,0.047644,-0.582932,-0.100757,0.024079,0.656435,-0.161348,0.267275,0.395164,-0.249333,0.048259,0.114662,0.065692,-0.623626,0.251859,0.277484,0.126781,-0.567063,-0.005843,-0.252424,0.004472,0.102121,-0.070210,0.281083,0.449387,0.190135,-0.162412,0.015296,0.141854,-0.426998,0.003752,0.734244,-0.307202,0.269685,-0.234804,0.566900,-0.249093,0.153404,-0.308694,-0.133386,0.215360,0.456719,-0.162779,-0.071614,0.373397,-0.275860,-0.386588,-0.206257,0.192311,-0.050945,-0.322231,0.068500,-0.185246,-0.130227,-0.209969,-0.075107,0.067997,0.144785,-0.051497,0.332056,-0.426322,-0.013246,0.197175,0.253528,-0.899139,0.405232,0.194149,0.058993,-0.341898,-0.092216,-0.204894,0.336043,-0.043656,0.278516,0.036045,0.078918,-0.465006,-0.068244,-0.449849', '1302110', '1484760', '1297710', '1307106');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464907', '黑帮暴徒', '剧情', '“阿飞”（普雷斯利•奎文亚吉 Presley Chweneyagae 饰）是约翰内斯堡19岁青年，年纪轻轻就成为了当地一名黑帮成员。从小的不良成长环境使他逐渐形成了残酷暴戾的性格。他在当地无恶不作，然而却遇上了一件改变他一生的事情。这天他刚刚差点打死一个小伙子，然后前 去劫车，开枪打伤女主人后，飞车狂奔，车后却隐约传来了婴儿哭声。阿飞心中有了恻隐，想到刚刚杀了孩子的母亲，他决定把婴儿带回家中照料。照料起婴孩毛手毛脚的他，威迫隔壁有经验的母亲照顾婴儿，慢慢的，他心中善良的意识也在婴儿的哭声中苏醒过来。©豆瓣', '普雷斯利·奎文亚吉', '加文·胡德', 7.3, 8357, 'tt0468565', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p962841907.jpg', 0.6, 4.2, 37.9, 43.7, 13.6, '-0.082306,0.101447,-0.742043,0.270284,-0.478364,-0.195171,0.913659,0.334290,-0.536013,-0.154144,0.226573,0.618124,0.023977,0.441808,0.184088,0.129490,-0.190991,-0.642833,-0.192161,-0.049029,-0.261004,-0.037290,-0.240061,-0.238684,0.075107,-0.466980,0.333997,-0.029321,-0.145589,0.457447,0.064894,0.022308,0.147948,0.471199,-0.302144,0.244728,0.068574,-0.008283,0.200888,0.083879,-0.031786,-0.310621,0.075583,0.029400,-0.196102,0.583448,0.632447,-0.197996,-0.171370,-0.380120,0.301323,0.147016,-0.219437,0.080841,0.257157,-0.066533,0.116653,-0.056314,-0.309887,-0.143727,-0.078373,0.067434,-0.398574,0.150972,-0.139847,0.000267,-0.751435,0.151699,-0.111857,0.114772,0.153527,-0.421611,0.164242,0.063429,-0.157412,0.517892,-0.228483,0.205675,-0.430264,-0.051891,0.665953,-0.254531,-0.142699,0.369089,-0.336689,-0.503151,0.213260,-0.233074,-0.295776,-0.122210,0.455906,0.009039,-0.570199,0.104259,-0.065816,-0.092063,-0.233403,0.029212,-0.088861,-0.226230,-0.355191,-0.030632,-0.222190,-0.170187,-0.382286,-0.149427,-0.145798,-0.086780,0.913599,-0.633615,0.159443,0.644894,0.069092,-0.274785,0.333301,-0.164178,0.356691,0.034706,0.273420,0.305996,-0.050395,0.370424,0.047516,0.314692,-0.239907,-0.017902,-0.190813,0.345039', '21619567', '4724586', '3111650', '5262027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464932', '精装追女仔之3狼之一族', '喜剧', '刘定坚（冯淬帆 饰）为节省成本将刘备（刘德华 饰）从车行解雇，岂料，刘定坚当年的情敌口水沾（黄霑 饰）携三个女儿阿贞（邱淑贞 饰）、阿敏（周慧敏 饰）、阿德（翁慧德 饰）和小姨子文文（张敏 饰）在刘的车行旁边又开了一家车行，不甘被抢生意的刘定坚随即雇佣失业表兄弟四人（成奎安、王晶、郑丹瑞、陈山河 饰），与口水沾的车行对抗。表兄弟四人颇为好色，虽然工资被刘定坚克扣，但每天创造“勾女”发明并且在刘备指导下向隔壁四女发动攻势的生活却也其乐融融。不久，黑道背景的同业以及心怀不轨的大老板向刘定坚和口水沾发难，令整日对峙的这两班人站到了同一阵线上……©豆瓣', '刘德华', '黄靖华', 6.2, 5279, 'tt0098217', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2348765217.jpg', 3.8, 17.3, 53.7, 15.4, 9.8, '0.303990,0.023918,-0.530871,0.312182,-0.022042,-0.273617,0.607232,0.696145,-0.195233,0.030506,0.285619,0.401578,-0.334408,0.114787,0.050587,-0.300048,-0.008475,-0.595251,0.036385,0.124899,0.006853,-0.123004,-0.175185,-0.091316,-0.329959,0.013981,0.308408,0.037265,-0.087179,0.499291,0.521276,0.104898,-0.220318,0.207947,-0.233293,0.234589,-0.033104,-0.025530,-0.092278,0.017243,-0.106018,-0.294638,-0.163623,-0.394673,0.228376,0.425999,0.357333,0.224809,0.053062,0.041539,0.145289,-0.283852,-0.010334,0.144708,0.379305,0.107636,0.169676,0.001593,-0.186432,0.063439,0.368223,0.211885,-0.475182,0.097216,0.337802,-0.159850,-0.791006,0.474158,-0.241067,-0.300998,0.007628,-0.374390,0.125780,0.334125,0.058588,0.376557,-0.101633,0.042875,-0.519241,0.096372,0.254956,0.065677,0.143143,-0.196406,0.002268,-0.348204,-0.152830,-0.038404,-0.272999,-0.379897,0.521622,-0.117291,0.241880,-0.125655,-0.715386,0.021316,0.048247,0.095288,0.179632,-0.151649,-0.004501,-0.669188,-0.085127,-0.712793,-0.160079,0.312841,0.328429,-0.135921,0.474610,-0.336311,-0.214520,-0.088381,0.395214,-0.525544,0.527450,0.177394,-0.054730,0.100398,-0.119723,0.003604,0.361186,0.123948,0.259789,0.602569,-0.355873,-0.003515,-0.255741,0.256013', '1301566', '1876765', '1394176', '26252157');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1464936', '何必有我?', '剧情', 'Koko（郑文雅 饰）的男友（周润发 饰）是香港一名社工，乐于助人。在男友的影响下，Koko也当上了一名社工。Koko虽然能经常帮助别人，但却一直未能改善自己和父亲的关系。Koko父亲刚刚刑满获释，因为不满父亲的所作所为，Koko多次将来向奶奶要钱的父亲赶出家门。一次偶然，Koko认识弱智青年肥猫（郑则仕 饰），肥猫的智商一直保留在童年水平，他和母亲在清贫中度日，整日和街坊一班小孩子玩耍。附近有一个恶霸经常欺负肥猫，周围的人对此亦无可奈何。Koko想帮助肥猫适应社会、自力更生，她最终能成功吗？©豆瓣', '郑则仕', '郑则仕', 8, 6295, 'tt0089259', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1954905483.jpg', 0.3, 1.3, 21.1, 52, 25.2, '0.092126,0.036609,-0.510567,0.534825,-0.402420,-0.321632,0.557478,0.106168,-0.657061,-0.452397,0.124886,0.681526,0.169148,0.498456,-0.063854,-0.166921,-0.095619,-0.430326,0.213804,-0.016015,-0.155415,-0.404919,-0.500119,-0.142884,-0.457613,-0.305820,0.486649,-0.000965,-0.104085,0.574905,0.277258,0.103762,-0.135583,0.384997,-0.338014,0.004144,0.157300,0.268697,-0.197160,0.047677,0.034715,-0.205365,-0.040002,-0.058886,0.306295,0.326768,0.601073,-0.071642,-0.433686,-0.121479,0.250248,0.077656,-0.060475,0.367380,0.517449,-0.218011,0.674758,0.087609,0.141756,-0.002581,-0.139708,-0.025734,-0.533058,-0.154766,0.185242,-0.040931,-0.687540,0.453134,0.138684,-0.182669,-0.025538,-0.345276,0.057030,0.327498,-0.034139,0.649531,-0.410622,0.226486,-0.425534,0.278351,0.743618,-0.034173,-0.100157,0.365328,-0.322770,-0.277585,0.008267,-0.267038,-0.687851,0.140055,0.041686,-0.166124,-0.574274,-0.045140,-0.193905,0.153238,-0.109251,0.326556,-0.098133,-0.349008,0.198541,-0.248741,0.171776,-0.529956,-0.351491,-0.096044,-0.034659,-0.422612,0.597128,-0.943760,0.254750,0.541451,0.410609,-0.709527,0.808580,0.309961,0.137160,-0.181150,-0.097838,-0.011596,0.070707,-0.053235,0.084066,0.178809,0.204832,-0.357764,-0.005576,0.198773', '3445516', '35030151', '1302384', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1465415', '撕裂人', '喜剧', '美貌的小镇教师斯黛拉（伊丽莎白·班克斯 Elizabeth Banks 饰）在母亲过世后得到当地富豪格兰特（迈克尔·鲁克 Michael Rooker 饰）的多方照顾，嫁给他后尽管诸多不满，却依然努力成为一个合格的妻子。有次二人吵架后格兰特愤而出走，被神秘的外星生物侵入体内，第二日清早回家性情大变。于此同时，小镇的宠物狗开始神秘失踪，曾与格兰特在酒吧一同饮酒的女孩布兰达（布兰达·詹姆斯 Brenda James 饰）也不见了踪影。在发现了格兰特开始腐烂变异的脸后，惊恐的斯黛拉求助于小镇警长比尔和众警员（内森·菲利安 Nathan Fillion 饰），但众人均被吓坏，格兰特借此逃脱。众人决定在附近农场猎捕格兰特，却没想到这竟导致了怪异生物的大蔓延，整个小镇都处于极度危险之中。本片被提名2007年美国科幻、幻想及恐怖电影协会最佳恐怖电影奖，并获最佳化妆土星奖。', '内森·菲利安', '詹姆斯·古恩', 6.2, 29934, 'tt0439815', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1133949911.jpg', 3.5, 16.3, 52.4, 20.7, 7.2, '0.151125,0.144263,-0.776638,0.180140,0.075579,-0.244213,0.652770,0.048070,-0.776008,-0.366024,-0.023551,0.813275,-0.487063,0.300190,0.216350,-0.039219,-0.287644,-0.411114,-0.251245,-0.150929,-0.137316,-0.292169,-0.331681,-0.261128,-0.135828,-0.529792,0.335202,0.068549,-0.092127,0.626234,0.235319,0.380915,-0.250164,0.423650,-0.057823,0.117646,0.377733,-0.206042,-0.181003,0.172705,-0.037098,-0.136438,-0.205418,0.045122,-0.007990,0.277036,0.721890,-0.097079,-0.106892,-0.213186,0.357720,-0.028720,0.090339,0.131821,0.603099,-0.111941,0.144625,0.038289,-0.087471,0.056338,0.049121,0.189921,-0.303494,0.210296,0.145778,0.159698,-0.456324,0.206743,0.000669,-0.037599,-0.047925,-0.268489,0.080089,0.134996,0.012132,0.153077,0.037979,0.158140,-0.300213,0.161477,0.380339,-0.072490,-0.325829,0.139159,-0.184859,-0.556859,-0.009254,-0.089231,-0.327399,-0.056576,0.434827,0.213488,-0.159489,0.273292,-0.592891,-0.160767,-0.372103,-0.282584,-0.129531,0.099512,-0.211079,-0.881936,0.000355,-0.001678,-0.230140,0.062503,-0.162136,-0.014157,0.363699,-0.637722,0.504878,0.401198,0.185619,-0.423334,0.461322,-0.173443,0.287389,-0.068763,-0.132194,0.466098,0.192139,0.252840,0.074501,0.128808,-0.229993,-0.195966,-0.381711,0.353391', '1308069', '2159244', '1309194', '2357711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1465754', '老友有钱', '剧情', '奥利维亚（珍妮佛·安妮斯顿）有三个亲密无间的老朋友，四个女人多年为伴，无话不谈。随着人到中年，朋友的际遇各有不同，却都已然成家立业：她们一个成为著名的服装设计师，一个是当红剧作家，另一个继承大笔遗产，衣食无忧。相比之下，奥利维亚的生活真是一塌糊涂，她不仅单身未婚，而且刚刚丢了工作，生活陷入困境。虽然带着表面的尴尬与难堪，老友们依然不离不弃，帮奥利维亚介绍工作，介绍男友，却鲜有成效。其实老友们也有自己的烦恼，厌倦工作、厌倦婚姻、厌倦生活，每个人都切实感触着中年的危机与烦恼。奥利维亚游走在大商场，索要着免费的面霜试用装，借着老友的光参加各种高级派对，等待烦恼逝去，等待真命天子的到来。其实不管每个人多有钱，还不是都这样等待着……©豆瓣', '凯瑟琳·基纳', '妮可·哈罗芬瑟', 6.4, 5494, 'tt0436331', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p839040714.jpg', 1.7, 13.7, 51.7, 26.1, 6.7, '0.108445,-0.250652,-0.405720,0.356398,-0.175368,-0.291881,0.764517,0.139953,-0.330678,-0.562473,0.170147,0.677139,-0.027396,0.658656,0.129791,-0.346936,-0.124334,-0.553018,-0.072238,0.047236,-0.107211,-0.283281,-0.389305,-0.132739,-0.456048,-0.192132,0.447248,-0.129013,0.071541,0.515981,0.329331,0.058755,-0.125062,0.375601,-0.586238,-0.301111,0.207640,0.385428,-0.495209,-0.150874,-0.246809,0.166543,-0.070119,-0.060866,0.252914,0.311804,0.535559,-0.023704,-0.329075,0.133552,0.311613,-0.152119,-0.109428,0.081713,0.117240,0.161643,0.202541,0.137504,-0.116664,0.033699,-0.138464,-0.109032,-1.015637,0.062121,0.178472,0.284614,-0.632158,0.628203,0.171728,-0.348481,-0.107162,-0.301660,0.171903,0.435225,0.160987,0.387748,-0.123046,0.426398,-0.390350,0.456505,0.919049,0.248067,-0.311356,0.366796,-0.384527,-0.108039,0.253826,-0.147204,-0.674845,-0.158731,-0.160541,-0.045174,0.101738,0.282757,-0.533875,0.398923,0.055159,-0.183109,0.217967,-0.691570,-0.061649,-0.755259,-0.122932,-0.388787,-0.531000,0.249640,0.246207,-0.335472,0.981931,-0.577299,0.240738,0.336134,0.114117,-0.920094,0.824101,0.507380,0.157672,-0.396855,-0.373538,0.452763,-0.067901,-0.088010,0.067270,0.118097,-0.239088,0.072032,-0.263577,0.412295', '26678784', '1308424', '4301278', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1465819', '甜言蜜语', '爱情', '与世隔绝的海岛小渔村，忠厚善良的哑巴男孩阿水（古天乐饰）自小就没了父母，开了一个家庭旅馆兼杂货铺。阿水每天傍晚都会在面向大海的平台上打沙包，坐在木架边吹口琴。海风拂过，淡淡的生活节奏之于阿水简单而又幸福。假小子一般的女孩小四喜跟阿水很要好，几乎成了金水的翻译。然而这一切的平静生活，被一个从香港来到这个小岛度假的姑娘雯雯（蒙嘉慧饰）打破了。美丽温柔的雯雯住进了阿水家开的度假木屋里，渐渐地，她和阿水以及小四喜成为了好朋友，度过了非常愉快的几天。当雯雯就要离开的时候，阿水已经深深地爱上了她，可依旧没有勇气表白。三年后，小四喜也离开了渔村，只有阿水一个人生活。阿水终于发现了那幅雯雯在墙上画给他的画。此刻，对雯雯万分思念的阿水终于决定去香港找她。然而意外发生了。©豆瓣', '古天乐', '赵崇基', 8.1, 11017, 'tt0266947', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1327882479.jpg', 0.4, 1.5, 20.8, 45.8, 31.6, '0.268467,-0.009721,-0.540089,0.433725,-0.261556,-0.481159,0.823526,0.274394,-0.387885,0.023463,0.032663,0.727074,-0.152863,0.528931,0.306076,0.407622,-0.332770,-0.620503,-0.171596,-0.237533,-0.281415,-0.245801,-0.021086,-0.066627,-0.011942,0.058908,0.293206,0.042677,0.117130,0.331215,0.030321,-0.177528,-0.055135,0.489323,-0.526016,0.189878,-0.185607,0.107558,-0.040628,0.226941,0.002662,-0.209379,-0.130432,0.001114,0.013364,0.156555,0.669357,-0.174145,-0.313360,0.184467,0.137501,-0.204638,-0.201409,0.113790,0.211594,-0.105695,0.119201,-0.077219,-0.364313,-0.152624,0.163875,-0.253799,-0.089866,0.296282,-0.098901,0.091291,-0.648649,0.646668,0.152621,-0.100826,0.043304,-0.545139,0.312014,0.175573,0.097501,0.532089,-0.243603,0.256313,-0.438714,0.215984,0.501521,0.177949,-0.056885,0.614638,-0.162847,-0.245405,0.149535,-0.047989,-0.388498,0.031271,0.246970,0.067974,-0.439008,-0.206714,-0.628032,0.084468,-0.173282,-0.186338,-0.076741,-0.456951,-0.333477,-0.481176,-0.167809,-0.371844,-0.247834,0.202987,-0.155084,-0.030350,0.535595,-0.756665,0.301252,0.313107,0.061711,-0.114462,0.581990,0.024325,-0.149641,-0.065964,0.257948,0.186528,-0.246212,0.665993,0.347728,0.560416,-0.256686,-0.106242,-0.533261,0.440131', '1302133', '21619567', '10576419', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1465829', '赤壁(上)', '动作', '东汉末年，汉室幼主难当大局，朝廷中曹操（张丰毅 饰）独断专行，挟天子以令诸侯，大夫孔融（王庆祥 饰）誓死直谏，结果落得给曹兵祭旗。原来曹操决心已定，欲剿灭刘备（尤勇 饰）、孙权（张震 饰）等江南反贼，一统天下。长坂坡一战后，刘备在军师诸葛亮（金城武 饰）辅佐之下，率结义 弟兄关羽、张飞（臧金生 饰）、赵云（胡军 饰）等，带领难民且战且退，最后只得求助于江东孙权。对于抗曹之事，孙权亦正犹豫不决。但大都督周瑜（梁朝伟 饰）与其妹孙尚香均力挺其出战，眼看大兵压境，孙刘联盟方现雏形。诸葛亮观周瑜严明治军，旗下大将甘兴（中村狮童 饰）身先士卒，颇感欣慰。此刻突然传来军中箭弩严重缺乏，孔明不顾鲁肃（侯勇 饰）好心劝阻，甘愿立下军令状，谋求箭弩……©豆瓣', '梁朝伟', '吴宇森', 6.4, 186371, 'tt0425637', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p936373819.jpg', 2.8, 12.2, 53.2, 25.6, 6.2, '-0.268097,0.123678,-0.541360,0.163078,0.510664,0.231936,-0.126868,0.657127,-0.482045,-0.319269,0.668613,0.168723,0.259520,-0.209882,-0.265446,-0.451847,-0.252606,-0.641715,-0.102828,0.311744,0.500732,-0.064236,-0.250530,-0.043355,-0.589506,0.210776,0.682770,-0.004175,0.319510,0.591304,0.116590,0.188301,0.188851,0.685300,0.420175,0.073364,-0.385353,-0.321895,-0.517786,-0.082827,-0.152195,-0.341457,-0.559235,-0.052669,-0.301335,0.273048,0.188510,-0.442634,0.249686,-0.138613,0.092512,-0.041575,0.149206,-0.080066,0.134796,0.215498,-0.009901,-0.018655,0.233269,0.049098,0.086172,0.162719,-0.060668,-0.213233,0.155069,-0.305283,-0.275149,0.245571,-0.400922,-0.066188,0.082571,-0.415916,-0.196272,0.310917,0.535836,-0.240031,-0.098379,-0.228737,-0.193082,0.458961,-0.044227,-0.118066,0.032307,-0.688366,0.289541,-0.269398,0.507468,-0.147132,-0.424308,0.080135,0.613238,-0.294782,0.427345,-0.027519,0.170538,-0.209036,-0.449580,0.723007,0.070623,0.327698,0.242138,-0.094781,0.157329,-0.049817,-0.197577,0.286809,0.590959,0.461620,0.237442,-0.293339,-0.891423,-0.284951,0.014116,-0.659736,-0.060243,0.148533,0.114516,0.179527,0.054908,0.111479,-0.086308,-0.053347,0.265847,-0.167342,-0.298784,-0.306713,-0.177843,-0.085334', '3291930', '1947091', '4821046', '5908477');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466007', '寂静岭', '悬疑', '为了女儿，Rose（拉达•米契尔 饰）与女儿一起来到了一个奇怪的地方。女儿常常梦游，Rose寻遍医生都无法把女儿的病治好，虽然灰心过但Rose还是不愿放弃医治女儿。女儿是她的命根，女儿梦游时总是说着一个名字，于是她丢下丈夫（肖恩•宾 饰），到了那个叫寂静岭的地方。Rose以为在那里能找到治疗女儿疾病的答案，但这个地方却出乎了她当初所想象。祸不单行的是女儿在这时候奇怪地失踪了。这里不像一般的城镇，空气中弥漫着让人窒息的浓雾。在这里居住的人不多，却有很多奇怪的生物居住，Rose到处寻找女儿，却不得要领。而且更常常遇到令她意想不到的事情，从未接触过的事物。渐渐的，她了解了有关这个地方的历史，也得知了一个秘密……©豆瓣', '拉达·米切尔', '克里斯多夫·甘斯', 7.7, 262368, 'tt0384537', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p554634907.jpg', 0.7, 3.4, 28.8, 45.7, 21.4, '0.244152,-0.096717,-0.897915,0.669566,-0.276190,-0.209108,0.874039,-0.033111,-0.894701,-0.575629,-0.019134,0.847182,-0.040970,0.300160,-0.088508,0.414151,-0.174185,-0.487692,0.069731,-0.369934,-0.541873,-0.494265,-0.356939,-0.255591,-0.158677,-0.326802,0.308801,0.218738,-0.263275,0.133404,0.041922,0.053064,0.050560,0.907884,-0.536165,-0.025601,0.030768,0.416458,0.016804,0.103659,0.075851,-0.154807,-0.101925,0.426089,0.047130,0.396563,0.481914,-0.197719,-0.417845,-0.051826,0.134380,-0.096018,0.043375,0.110583,0.250530,-0.422227,0.444205,-0.170724,-0.301568,-0.096985,0.086755,0.140150,-0.795626,0.172204,0.336461,0.327437,-0.652697,0.171497,-0.191830,-0.235712,-0.109547,-0.443710,0.664327,0.231727,0.137322,0.474408,-0.419042,-0.129324,-0.698233,0.031317,0.905116,-0.003091,-0.136815,0.424192,-0.447778,-0.417356,0.052426,-0.148040,-0.641888,0.292446,-0.090924,0.245018,-0.606932,0.213389,-0.349392,0.056546,-0.059490,0.002493,-0.048569,-0.561373,-0.184894,-0.033694,0.040987,-0.342154,-0.349774,0.025203,-0.097380,-0.331327,0.675781,-0.734112,0.210973,0.780287,0.454010,-0.583105,0.803525,0.139406,0.110121,-0.202107,-0.005337,0.258917,-0.026697,0.254171,0.094831,0.426525,0.158109,-0.326299,-0.502011,0.501738', '1292064', '1866424', '26718282', '26420626');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466022', '铁扇公主', '剧情', '唐僧师徒四人赶奔西天，渐觉热气蒸人。问及乡里，才知此地唤做火焰山，无春无秋，四季皆热，山周围八百里火焰。受阻于火焰山，孙悟空、猪八戒到翠屏山芭蕉洞找铁扇公主公主借灭火的芭蕉扇，铁扇公主不肯借予。孙悟空变只小虫钻进铁扇公主腹内大闹，结果拿到手的是一把假扇子。猪八戒又化作牛魔王的模样从铁扇公主手中骗到真扇。牛魔王这时正在跟狐狸精寻欢作乐，听到扇子被抢走了，赶紧回到家中，接着又化作孙悟空的模样从猪八戒手中骗回扇子。影片结尾，悟空和八戒，以及乡亲们联手打败了牛魔王，终得宝扇，扇灭火焰山的烈火，登上取经的路程。影片中的牛魔王其实“日本鬼子”的影射，正值抗战时期，万氏兄弟想借此片鼓舞全国人民的抗战热情。本片是中国第一部长篇有声立体卡通（动画电影），手冢治虫也受《铁扇公主》影响，决定从事动画行业。©豆瓣', '白虹', '万籁鸣', 8.7, 5173, 'tt0471945', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2550052042.jpg', 0.3, 0.8, 11, 40, 47.9, '0.118965,0.108841,-0.622739,0.428684,0.377931,-0.121894,0.442620,0.219788,-0.048740,0.174787,0.227049,0.406696,-0.243598,0.154231,-0.175173,0.102515,-0.139229,-0.517235,-0.258796,0.063527,0.312356,0.348304,-0.113357,0.246075,-0.201390,0.050582,0.313104,-0.132933,-0.086672,0.171123,0.361487,-0.070336,-0.354229,0.067821,-0.375456,0.327198,-0.514947,0.128021,-0.087948,0.272385,0.134553,-0.301627,-0.192303,-0.068603,0.023032,0.198079,0.443575,-0.324981,0.052294,-0.168370,0.249938,-0.132979,-0.183615,0.054921,0.237892,0.029611,0.285560,-0.398774,-0.003152,0.059171,0.183817,-0.444330,0.095763,0.241518,0.014470,-0.002576,-0.280609,0.065061,0.040780,0.100951,0.115079,-0.346593,0.110307,-0.141129,0.169569,0.485258,-0.039201,-0.022468,-0.486658,0.370562,0.357624,-0.273659,0.294346,0.047646,0.153066,-0.061974,0.139715,0.010970,0.119706,-0.202499,0.654343,-0.070131,-0.007916,0.063113,-0.461884,-0.185233,-0.199128,-0.002639,0.070117,-0.041590,-0.010982,-0.392371,-0.015688,0.010320,0.132534,-0.344791,0.444691,0.060009,0.465129,-0.224906,0.094246,0.156873,-0.179506,0.052938,0.373627,-0.207179,0.005458,-0.170371,0.136825,-0.015756,0.074851,0.544004,0.409133,0.112566,0.036231,-0.404850,-0.254761,0.040657', '21619567', '4919019', '1856675', '26882457');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466273', '巧奔妙逃', '剧情', '一八路军战士缴获了日军的战略进攻地图，但无奈身负重伤，只得将地图交给自己的农民弟弟二柱，拜托其赶到火车站把地图送给同志。与此同时，来自东北的秦贵（黄宏 饰）被掌柜委派，去火车站接收地图，另一方面，立志加入八路军抗日的弹棉花农民老幺（魏宗万 饰）和自家年轻的叔叔顺子（赵亮 饰）四处寻找八路军的队伍，叔侄俩在茶馆中偶遇擅长口技的说书人（徐玉琨 饰），三人在日本军官佐佐木一郎（孙敏 饰）带队追索地图的枪火中救下了已经受伤的二柱，说书人顶替二柱交接地图，老幺和顺子则一路狂奔引开了佐佐木的队伍。在火车站，秦贵误认说书人是八路军接头人从而死缠不放，随后赶到的老幺和顺子短暂汇合后四人被日军的炮火再次打散，秦贵、老幺和说书人被困地窖，顺子去邻村搬来村民搭救，一场普通人和鬼子的追逐好戏正式上演……©豆瓣', '黄宏', '孙敏', 8.2, 17183, '东奔西走', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2869990227.jpg', 0.7, 1.9, 17, 46.9, 33.5, '0.268970,-0.404956,-0.505914,0.253827,-0.123176,-0.258309,0.310479,0.187146,-0.312365,0.110551,0.555385,0.541799,0.295270,-0.102695,0.112620,-0.061979,-0.227825,-0.480140,-0.256896,0.068244,-0.163055,-0.391300,0.074711,-0.242402,0.272954,-0.040317,0.305906,-0.007895,-0.221020,0.693873,0.171024,0.128841,-0.489531,0.154833,-0.111340,0.525647,0.081628,-0.498173,-0.348764,-0.006752,-0.336915,-0.169364,-0.203339,-0.198751,0.197999,0.320876,1.056102,-0.004848,0.181574,0.182583,-0.037705,-0.234056,-0.099682,0.045471,0.587365,0.169844,0.038333,-0.086433,-0.061251,0.040302,-0.354306,-0.016726,-0.230639,0.164298,-0.001101,0.082215,-0.639221,0.515391,0.013858,0.214912,0.331732,-0.412297,0.389561,0.392042,-0.096313,0.255078,-0.043192,-0.032038,-0.431391,0.252753,0.312793,-0.152399,0.535924,-0.130186,0.125983,-0.173712,0.201597,0.022817,-0.164270,-0.024725,0.579432,-0.272157,-0.078490,-0.255855,-0.741563,-0.026128,-0.223124,-0.058373,0.283594,-0.190502,-0.253967,-0.840497,0.110027,-0.183557,-0.066159,0.210729,0.056010,0.350343,0.809520,-0.323938,-0.215676,0.414691,0.115416,-0.194955,0.351466,-0.005018,0.069918,-0.312227,0.098209,-0.260976,0.239129,0.887227,0.585412,0.356489,-0.332550,-0.387544,-0.283773,0.051307', '5403927', '26788667', '26365262', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466394', '王的男人', '剧情', '朝鲜第十代王燕山王君时期，艺人长生（甘宇成饰）和孔吉（李俊基饰）因为不肯加入当地的艺人团，来到京城汉阳谋生。此时暴君燕山君（郑镇荣饰）沉迷于宠妾张绿水（姜成妍饰），朝纲混乱，民不聊生。长生与孔吉二人在街头开始表演讽刺君主的喜剧，大受欢迎，却遭逮捕。后要求到王面前表演，求得一笑。结果，多亏孔吉的急中生智，燕山君才笑了出来。两人随即被留在宫中取乐，孔吉更是因为美色令王倍加宠爱。他们不停表演，大臣们却各自心怀鬼胎，导致了杀戮局面。最终，君王和艺人的命运又将如何呢？©豆瓣', '甘宇成', '李濬益', 7.1, 88474, 'tt0492835', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p454364823.jpg', 1.2, 6.4, 42.6, 34.7, 15.1, '-0.179539,0.283920,-0.524808,0.531491,0.267703,-0.198215,0.500499,0.350813,-0.590333,-0.095056,0.184562,0.355408,-0.223794,0.331826,0.303360,-0.382076,-0.259824,-0.455108,-0.184158,-0.066442,0.104905,0.088058,-0.034598,-0.075014,-0.608068,-0.105196,0.549280,0.157808,-0.335655,0.271147,0.486683,0.196929,-0.275968,0.530590,0.047125,0.275754,0.178131,-0.106521,-0.439815,0.096245,0.082414,-0.599470,-0.642089,-0.026082,0.138285,-0.041658,0.623832,-0.372642,0.031649,-0.453529,0.204152,-0.326460,0.038021,0.393524,0.297602,-0.089990,0.310536,0.180114,0.021073,-0.004658,0.034275,-0.060106,-0.561336,0.096615,-0.015272,0.052294,-0.236011,0.255623,-0.040583,-0.218882,0.100477,-0.444120,0.285127,0.423575,0.556832,0.109046,-0.242223,0.112957,-0.392722,0.309885,0.594111,0.279696,-0.274659,-0.076996,0.264950,-0.461158,-0.057877,-0.357265,-0.193193,-0.132579,0.450168,-0.015455,0.208331,0.447311,-0.262715,-0.294872,-0.055229,-0.169545,0.146945,-0.272359,-0.138457,-0.426125,0.113223,-0.304779,0.003753,-0.078740,0.275780,-0.134056,0.466630,-0.698034,-0.096585,0.166684,0.246940,-0.720269,0.307638,0.162885,0.140058,-0.103749,-0.233222,-0.123994,0.240641,0.378902,0.415533,0.249113,-0.336985,-0.110622,-0.204333,0.162259', '1293265', '1301022', '1295746', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466419', '影子部队', '剧情', '抵抗运动的领导人之一杰彼耶杀死德国卫兵，逃出了国际集中营。不久，杰彼耶到英国接受戴高乐将军授勋，但在得知替代他的临时负责人菲力克斯被捕后，连夜乘飞机跳伞回国营救。几经曲折，他们始终未能救出同伴，菲力克斯和挚友弗朗索瓦在狱中服毒自杀。后来杰彼耶也遭被捕，玛蒂尔德精心策划把 他营救出来。就在杰彼耶养伤的过程中，玛蒂尔德却被捕了，并被敌人以女儿作人质威迫她供出同伴，但最后她却死在同伴的枪下。本片中的人物与浪漫主义作品中的英雄人物不同，他们虽是为了集体和民族的利益而战，但也会因情感的软弱和个人的动机而屈服。影片格调深沉、色彩凝重，相当写实地还原了二战期间法国地下游击队的艰苦而冷酷的战斗生活，以低调朴实的纪实片风格塑造出几个英雄人物，把他们身处的孤立无援、危机四伏的困境都鲜明地表现出来，生动有力地表现了作者对抵抗运动及其时代的反思。', '利诺·文图拉', '让-皮埃尔·梅尔维尔', 8.6, 7437, 'tt0064040', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204668213.jpg', 0.4, 1.3, 10.8, 43.5, 44, '0.166774,0.058219,-0.624362,0.691995,0.006561,-0.207125,0.699408,-0.071677,-0.535154,-0.166014,0.319222,0.871863,0.026792,0.101192,0.363551,-0.144200,-0.518255,-0.690928,-0.211173,0.070310,-0.131235,-0.568222,-0.213467,-0.326130,-0.153649,-0.263854,0.871059,0.303641,-0.200690,0.474726,0.136446,0.269528,-0.165904,0.479949,0.064252,-0.156488,-0.037421,-0.226599,-0.243440,0.046261,0.114989,-0.483728,-0.357330,0.396796,0.029418,0.552270,0.728193,-0.284266,-0.028379,-0.003348,0.342550,-0.390409,-0.069497,0.194391,0.216442,-0.130528,0.168306,0.486213,0.097150,-0.057658,-0.156706,-0.044810,-0.827813,-0.013340,0.192553,0.049429,-0.559720,0.598249,-0.116423,0.108591,-0.062819,-0.137374,0.162550,0.274037,0.276434,0.347077,-0.198411,-0.028781,-0.548838,0.111120,0.646929,-0.099375,-0.472188,-0.009946,-0.391193,-0.569628,-0.009252,-0.600096,-0.382565,-0.102502,0.328148,-0.034505,-0.220164,0.276898,-0.723352,-0.112182,-0.573234,0.017295,-0.253280,-0.456414,0.001825,-0.555976,-0.103864,-0.393544,-0.401601,0.004952,-0.046425,-0.218117,0.691347,-0.752960,0.013986,0.490921,0.275245,-0.516436,0.464229,0.162386,0.148321,-0.017023,-0.180457,0.388963,0.161455,0.131632,0.149530,0.259312,-0.155869,-0.127027,-0.375504,0.354769', '1308837', '25880986', '