INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466574', '上海滩十三太保', '动作', '抗日时期，爱国人士高先生不满汪伪政权卖国行径，与神偷黑帽子（王羽 饰）将双方密约窃走，计划将其公开。上海富商沈刚夫（陈观泰 饰）受人所托，命上海滩十三太保保护高先生离沪赴港。南京方面内务部长官洪述亦同时动作，收买部分太保暗杀高先生……长枪小杨（李修贤 饰）首先发难行刺却因失手被洪述清除，高先生先后在烟嘴冯金榜（江生 饰）、眼镜（王钟 饰）、富商陶大业（梁家仁 饰）、学生关伟（刘德华 饰）、浪子叶不凡（姜大卫 饰）、少爷梁少雄、教头（狄龙）的护卫下历经连番血战，终于杀出重围。只可叹“教头快刀、浪子富翁、学生少爷、熊虎鹰豹、眼镜烟嘴、长枪难逃”的上海滩十三太保一朝风流云散。©豆瓣', '狄龙', '张彻', 7.5, 5633, 'tt0083061', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167125216.jpg', 0.8, 3.9, 31.9, 43.9, 19.4, '-0.375877,0.095308,0.077349,0.131399,0.257313,-0.025693,0.049030,0.247654,-0.291196,-0.435615,0.567744,0.299955,-0.011877,-0.105151,0.060322,-0.146576,0.056598,-0.675809,-0.135723,0.044153,-0.018396,-0.281413,-0.201506,0.087419,-0.315511,0.127814,0.269654,0.179472,-0.177245,0.497131,0.307916,0.023926,-0.093951,0.049900,0.025753,-0.100533,0.243261,-0.296820,-0.303897,-0.179474,0.072174,-0.303060,-0.023108,-0.268798,0.339302,0.064277,0.491756,-0.136812,0.017963,-0.191665,0.174596,-0.083947,0.106398,0.065154,0.495781,0.254948,0.242555,0.118007,0.138473,-0.164885,0.327012,-0.139985,0.086284,0.271885,0.396191,-0.290109,-0.333004,0.388554,-0.575583,0.258205,-0.137502,-0.214397,0.049234,-0.098079,0.304834,-0.341893,0.085388,0.151557,-0.293237,0.583265,0.183390,0.194513,0.071171,-0.836698,0.162399,-0.347011,-0.024499,-0.231023,-0.023166,-0.096129,0.655993,-0.503353,0.468269,0.269410,-0.170288,-0.225430,-0.422456,0.672597,0.008640,0.146442,-0.127132,-0.234500,-0.021144,-0.120195,0.347824,0.067248,0.518417,0.020159,0.493141,-0.394895,-0.012994,-0.061498,0.109482,-0.286223,0.391068,-0.158017,0.119060,-0.159504,-0.138866,-0.003859,0.314466,0.206137,0.234521,0.046570,-0.230255,-0.631741,0.229086,-0.288710', '21327512', '1294488', '1465829', '1301982');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466897', '足球尤物', '喜剧', '维欧拉（阿曼达•贝尼斯 饰）甜美可人，笑容如同一片金色阳光。但她可不是个娇滴滴的小女生。疯狂喜爱足球的她，一直把踢球当作梦想。谁知，可恶的学校竟然取消了女子球队。维欧拉为了继续她的足球梦，乔装成她的双胞胎哥哥赛巴斯蒂去新学校报道，并作为新生加入足球队，准备在球场上战胜那些轻视女孩的男球员们。然而从小女生变成男生可不是一件容易的事，维欧拉故作野蛮的样子着实让人又佩服又好笑。在室友杜克（钱宁 •塔图姆饰）的帮助下，维欧拉足球技术越来越出色。而不知不觉中，她竟爱上了这个和她朝夕相处的阳光大男孩。令人咋舌的是，学校的“万人迷”奥莉维娅竟然疯狂地为她着迷。一件件突发事件接踵而至，维欧拉不知所措。但她始终不变的，对足球的狂热，促使她硬着头皮也要向前走。爱情，足球，皆大欢喜还是全盘皆输？等待维欧拉，等待你我……©豆瓣', '阿曼达·贝尼斯', '安迪·菲克曼', 7.4, 67655, 'tt0454945', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p800759469.jpg', 0.4, 3.4, 37.6, 43.2, 15.3, '0.242877,0.029797,-0.563144,0.485162,-0.196105,-0.317718,0.479454,0.261747,-0.167031,-0.095260,-0.028116,0.508267,-0.322141,0.184948,0.140970,0.168283,-0.307983,-0.836377,-0.181264,-0.101867,-0.173157,-0.221790,0.060458,-0.334275,0.235535,-0.212356,0.480434,0.109887,-0.186160,0.190737,0.337896,0.332128,0.292957,0.528269,-0.213382,-0.039828,0.095810,0.081363,0.125916,-0.013206,0.001968,-0.092277,-0.374032,0.274325,0.196552,0.106777,0.568825,-0.280584,0.003706,-0.099705,0.260723,-0.285468,0.085258,-0.038105,0.072532,-0.343245,-0.003390,-0.299741,0.289723,-0.211682,0.279308,-0.484650,-0.634935,0.205727,-0.014927,-0.180815,-0.466487,0.474298,-0.017834,0.228225,0.269702,-0.267516,-0.085596,0.027608,0.123958,0.240498,-0.170449,-0.065943,-0.381782,0.269633,0.470520,0.426778,-0.457398,0.347348,-0.701138,-0.289753,-0.086078,-0.308924,-0.677027,0.110849,0.431906,-0.206368,0.067927,0.300292,-0.315341,0.072075,-0.307950,0.057541,-0.206727,-0.731237,-0.109810,-0.369604,0.196185,-0.171598,-0.401912,-0.021736,-0.283986,-0.243416,0.825840,-0.662057,0.107851,0.824560,0.111483,-0.215407,0.440734,-0.204797,-0.130565,-0.281105,-0.461858,0.526150,0.001065,-0.165436,0.004362,0.636429,-0.077788,0.153068,-0.174158,0.532209', '3230462', '1302776', '1307146', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466907', '波浪预报', '爱情', '初中时期就以认识的秀浩（车太贤 饰）与秀恩（宋慧乔 饰）两人正读高中。秀浩的成绩与相貌都一般，但他看起来非常单纯善良。美丽的秀恩是全校男生的梦中情人，但实际上秀恩早已有了暗恋的人，那个人就是秀浩。两人随后经常走到了一起，这样令很多喜欢秀恩的男孩子们非常嫉妒，非常愤怒的男生们竟然合起来打秀浩。但无辜的是他始终不知道秀恩是喜欢自己的。秀恩之后用录音邮件厢秀浩表达了自己的爱慕之情，听到了秀恩真情的告白之后，秀浩也感到了初恋的感觉。两人开始恋爱，非常快乐的过着日子。在同学们的安排下，两人在一个小岛上度过了最难忘的一天。令秀浩震惊的是，原来秀恩一直向男友隐瞒着自己患有重病的事。©豆瓣', '车太贤', '田昀树', 6.5, 5866, 'tt0488177', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p712606000.jpg', 1.8, 11.3, 54.4, 23.4, 9.1, '0.403762,-0.340781,-0.600688,0.796696,-0.230583,-0.141631,0.927157,-0.026489,-0.635385,-0.206964,0.008495,0.658536,-0.452201,0.675259,0.244955,0.025979,-0.152351,-0.760094,-0.165548,-0.273796,-0.268125,-0.306036,-0.034003,0.000826,-0.343311,-0.191563,0.587274,-0.123229,0.047023,0.544000,0.342081,0.193459,0.262846,0.662330,-0.339408,-0.055646,-0.104798,0.237379,-0.043868,-0.106588,0.032374,-0.115673,-0.189542,0.399542,-0.123021,0.165857,0.573991,-0.211842,-0.389198,0.168790,0.428587,-0.194142,-0.204992,0.201962,0.354212,0.048395,0.514302,0.037194,-0.085356,0.069579,0.075364,0.116467,-0.570073,0.066529,0.088774,0.195007,-0.580831,0.638327,0.009137,-0.095071,0.191378,-0.367765,0.211300,0.245846,0.105390,0.396442,-0.401137,-0.094894,-0.439176,0.090881,0.817865,0.220354,-0.201277,0.712734,-0.511694,-0.485916,-0.138154,0.044846,-0.628908,0.184152,-0.075813,0.039549,-0.237623,0.250188,-0.567294,-0.047196,0.263004,-0.091799,-0.073442,-0.752471,-0.245521,-0.456544,-0.227063,-0.723821,-0.734356,-0.076933,-0.071125,-0.369856,1.099352,-1.212541,0.011538,0.421649,0.135261,-0.395836,0.834162,0.463351,-0.310698,-0.120499,-0.246778,0.230289,-0.171172,-0.139935,-0.001285,0.538374,-0.282561,-0.197527,-0.466851,0.801242', '1292219', '6963575', '35030151', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1466910', '搭讪的法则', '喜剧', '英俊不凡的民俊（宋一国 饰）是情场上的高手，性感的智媛（孙艺珍 饰）也相貌出众，能把异性深深吸引住。这两名恋爱高手被命运安排走到了一起。为了吸引住民俊，智媛佯装交通事故，进一步接近民俊了。民俊与智媛都知道，他们遇上了高手，各有自己的战斗策略，两人同样没有把自己的本色显露出来，一路互相摸索。为了探究，他们都忽略了自己已坠入爱河。这一场“恋爱战争中”，两人到底谁会胜出呢？©豆瓣', '孙艺珍', '吴基桓', 6.4, 18671, 'tt0492650', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1172292312.jpg', 1.9, 12.1, 55.7, 23.3, 7, '0.567937,-0.191868,-0.501020,0.443842,-0.319821,-0.113908,0.696149,-0.202306,-0.316119,0.046533,0.378843,0.719991,-0.435165,-0.140913,0.247815,-0.303923,-0.245762,-1.115039,-0.176215,-0.138417,-0.363237,-0.267408,-0.510297,0.189329,-0.135813,-0.048411,0.629069,-0.156159,-0.296664,0.504644,0.498303,0.129490,-0.234004,0.360602,-0.165538,0.278621,-0.011100,0.033502,-0.047011,0.214926,-0.039226,-0.291348,-0.160023,0.341467,-0.083738,0.346601,0.736205,-0.082662,-0.056915,0.154900,-0.042834,-0.207889,-0.060393,0.453408,0.259939,-0.197988,0.247882,0.378872,-0.123887,0.064787,0.126531,0.299421,-0.735136,0.127275,0.115808,0.014351,-0.284140,0.474540,0.382967,-0.367823,0.000421,-0.242007,0.263419,0.439160,0.587647,0.041296,-0.033464,-0.128265,-0.544672,0.197452,0.739485,0.257333,0.084548,0.466684,-0.251666,-0.576601,-0.392023,-0.646187,-0.400602,0.087345,0.419799,0.258905,0.088557,0.183855,-0.360061,-0.049177,-0.012644,-0.087675,-0.425081,-0.680696,0.055813,-0.219433,-0.579157,-0.774690,-0.616810,0.257232,-0.048244,-0.323789,0.716244,-0.882142,-0.337024,0.339834,0.264037,-0.489846,0.855797,0.172804,-0.008607,-0.146194,-0.298994,-0.061507,-0.119829,0.087554,0.094323,0.732889,-0.082733,0.043697,-0.427572,0.364490', '4301278', '25777330', '30162520', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1467023', '侠盗魅影', '喜剧', '19世纪80年代，美国帝国主义四出扩张，对殖民地进行疯狂的洗掠。一时间，殖民地人民纷纷建立起了反抗军，对抗美帝国主义。墨西哥当时也是美帝的殖民地，萨拉（萨尔玛•海耶克 Salma Hayek 饰）是当地一位银行家的女儿，虽然自小就被精心培养成标准的“欧洲淑女”。但萨拉却是一身豪气侠胆，被美帝夺取了家里的财产后，萨拉开始了武装抢劫美帝的银行之旅。玛丽亚（佩内洛普•克鲁兹 Penélope Cruz 饰）是当地一户农户的女儿，因父亲被美兵殴打伤重，点燃了她对美帝的仇恨之火，玛丽亚也开始抢劫美帝的银行。两个女孩在一次抢劫银行时偶遇了，从此她们结束了单打独斗，联合起来共同对付美帝。©豆瓣', '萨尔玛·海耶克', '乔阿吉姆·罗恩尼', 6.7, 9063, 'tt0416496', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1047232837.jpg', 1, 7.3, 53.6, 30.6, 7.4, '0.382937,0.107224,-0.714040,0.380726,-0.163244,-0.277125,0.379174,-0.017574,-0.504759,0.237930,0.099250,0.883749,-0.008746,0.240738,0.060784,0.274830,-0.165389,-0.716293,-0.241114,-0.023035,-0.010709,-0.317368,-0.222981,-0.227341,-0.281981,-0.336195,0.376158,0.071909,-0.219292,0.306638,0.358062,0.267751,0.145460,0.342516,-0.209858,-0.064281,0.228577,-0.315771,-0.175457,0.355972,-0.167480,-0.242597,0.043590,0.201453,0.054185,0.464582,0.550387,0.015568,0.427003,-0.592449,0.373206,-0.055914,-0.189619,0.366651,0.603455,0.011157,0.086679,0.190227,-0.081559,-0.234385,0.191904,0.008889,-0.426802,0.068553,0.035664,-0.133677,-0.749399,0.631564,-0.206513,0.065684,-0.105306,-0.110351,0.151042,0.473144,0.178248,0.430432,0.040926,-0.017425,-0.675497,0.390581,0.642628,-0.159637,-0.090892,0.052754,-0.263222,-0.404421,0.148902,-0.295942,-0.154085,-0.496663,0.429569,-0.421374,-0.055413,0.432374,-0.961660,0.002663,-0.412674,-0.369557,0.235140,-0.191110,-0.013098,-0.582067,-0.216775,-0.354193,-0.217770,0.188534,0.203332,0.154231,0.810804,-0.600523,-0.062701,0.706949,0.438762,-0.632376,0.289679,-0.093121,0.039595,0.068276,0.021992,0.258672,0.228910,0.317965,0.240505,0.242084,-0.044848,-0.253248,0.225037,0.434211', '1309069', '30162520', '26280899', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1467044', '魔术师', '剧情', '1900年，科学的发展还未能遮盖魔术的神秘感，维也纳的人们对艾森海姆（爱德华·诺顿 Edward Norto饰）的魔术更是达到了痴迷的状态。这个神奇的魔术师总是能把现实和虚幻的东西混为一体，让人坠入云里雾里，怀疑他是否真的具有超能力。而台下的乌尔侦探，更是想从艾森海姆每一场的表演里看出幕后的真相。一天，一位上台接受挑战的女子令艾森海姆大为震惊——她就是自己往日的恋人苏菲（杰西卡·贝尔 Jessica Biel 饰）。他们曾经因为等级门户之故被迫分开，而如今，苏菲将成为王储的妻子。尽管这样，二人还是旧情复炽，无法自拔。当苏菲打算放弃一切跟爱森海姆私奔时，悲剧却发生了,她离奇死去，所有证据都表明凶手就是由爱生恨的王储。真相似乎已经大白，但是魔术师的世界亦真亦幻，实情也随之扑朔迷离。©豆瓣', '爱德华·诺顿', '尼尔·博格', 7.6, 90910, 'tt0443543', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p480484402.jpg', 0.4, 2.8, 31.3, 48.1, 17.5, '0.155401,0.195634,-0.617828,0.449527,-0.272021,-0.138055,0.664159,-0.094922,-0.641897,-0.313986,0.101498,0.738013,-0.248569,0.160793,0.303677,0.064912,-0.494378,-0.804356,0.125919,-0.215532,-0.106309,-0.643631,-0.347067,-0.283780,-0.008350,-0.337530,0.704079,0.224931,-0.237347,0.168462,0.323523,0.161136,-0.164153,0.535572,0.177588,-0.113437,0.076721,0.034101,-0.291574,-0.066453,0.105724,-0.100821,-0.209378,0.378192,-0.310731,0.279165,0.397571,-0.465400,-0.149416,-0.035168,0.419038,-0.445987,0.004827,0.420815,-0.034161,-0.113028,-0.027164,0.266646,-0.017227,-0.124840,0.096600,0.118897,-0.973484,0.227898,0.072381,0.143016,-0.277881,0.199112,-0.209320,-0.024163,-0.002277,-0.075323,0.172613,0.180996,0.544743,0.389615,-0.152549,-0.186871,-0.368593,0.127812,0.615125,0.130232,-0.622622,0.430280,-0.283595,-0.521626,-0.321210,-0.074039,-0.469801,0.260125,0.235900,0.350678,-0.081348,0.492752,-0.444107,-0.184167,-0.422144,-0.229809,-0.236794,-0.301948,0.031270,-0.335533,-0.250736,-0.352865,-0.205077,-0.319134,0.279529,-0.337956,0.543962,-0.613363,0.304847,0.484298,0.255183,-0.446429,0.470864,-0.011422,0.077757,-0.239286,-0.285870,0.423119,-0.122461,0.022628,-0.020604,0.326142,0.340787,0.120515,-0.286892,0.699840', '27098364', '6844861', '1793491', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1467748', '我的九月', '剧情', '1990年九月，北京亚运会前夕，大榆树小学的百来名学生正在为开幕式的团体体操表演进行紧张的训练。其中一名叫安建军（张萌 饰）的却因为总是反应慢半拍而被取消了参赛资格，和他一起被取消的还有他的几个小伙伴。被人称作“安大傻子”的建军伤心不已，在中队长刘庆来（张晨 饰）的怂恿 下，几人到训练场捣乱，引得新来的班主任高老师（张国立 饰）到建军家家访。而这次家访让一直胆小不敢言的建军与高老师成为了好朋友，二人相约日后有什么问题就说出来一起解决。一次偶然，建军买彩票中了五十块钱捐给了亚运会，这引来了晚报记者的采访。但害羞的建军没有把自己的名字说出来，倒是刘庆来说了自己的名字，于是这份荣誉就挂在了庆来的头上。受到委屈的建军在高老师的鼓励下，开始省下买早餐的钱来买彩票，且勤奋练习武术。在亚运会开幕前2天，有同学突然受伤不能参加。建军的辛勤得到了证明，他和小伙伴们站在了亚运会的会场……', '张萌', '尹力', 8.8, 10678, 'tt4053842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494288807.jpg', 0.3, 0.5, 10.4, 39, 49.9, '0.389535,-0.123645,-0.725792,0.304404,-0.291159,-0.446227,0.261040,0.113042,-0.343262,0.075346,0.261800,0.689560,-0.420177,0.291330,0.228971,-0.062233,-0.187724,-0.622996,-0.005601,-0.180332,-0.290885,-0.596107,0.273941,0.035437,-0.094267,-0.185055,0.109689,-0.269601,0.008503,0.858721,0.294943,-0.148379,0.504325,0.294044,-0.253609,0.109868,0.166851,0.126048,-0.047705,0.192499,0.175492,-0.177614,-0.427743,0.091396,0.433838,0.269826,0.567007,0.105187,-0.235562,0.220851,0.311015,-0.308740,0.022289,0.010880,0.344584,0.247467,0.344822,0.040078,-0.067319,0.315059,-0.017917,0.047804,-0.590689,0.163089,0.053221,0.081094,-0.659033,0.768668,-0.063784,-0.014555,0.135126,-0.346954,0.314745,0.359643,-0.044341,0.428349,-0.174729,-0.163647,-0.492953,0.386947,0.613877,-0.095530,-0.041686,0.140007,-0.117853,-0.171264,0.336876,-0.101655,-0.349953,0.187345,0.193033,-0.150896,-0.141644,-0.154346,-0.616297,0.113627,-0.004951,-0.266335,0.043046,-0.368692,-0.272218,-0.382881,-0.009672,-0.142300,-0.325314,-0.054093,0.241297,-0.291763,1.047583,-0.994747,0.126491,0.527512,0.661803,-0.274849,0.608549,0.060272,-0.020666,0.015797,-0.173040,-0.677436,-0.114679,0.702909,0.275282,0.423772,-0.058907,-0.548332,-0.218247,0.273831', '3091208', '1292219', '25922902', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1467778', '机动警察剧场版1', '剧情', '1999年的东京，一部军用的机械人在无人的情况自动启动、一个名为帆场瑛一的篠原重工天才程序员自杀；谁也没想到，两起无关事件却会在将来把东京带入恐怖中。从建筑施工现场到人们的日常生活，处处都可以见到一种被称为“Labor”的大型机器人。面对Labor相关犯罪与日俱增的局面，警察局成立了特殊车辆二课，配备专门机器人PatLabor，负责处理特殊事务。Labor到了更新换代的时期，作为机器人大脑的电脑操作系统升级为HOS。正在这时，突然发生多起机器人失控事件，机动警察小队负责调查此事。他们发现这是由与HOS有关的电脑病毒所导致的，而肇事者已经销毁了所有资料行踪不明。在东京湾，制造巨型海上方舟以解决东京土地问题的巴比伦计划已经到了关键时刻，那里集结了全国45%的Labor机器人，这些机器人一旦失控后果将不堪设想……本片为TV动画《机动警察》的剧场版。©豆瓣', '古川登志夫', '押井守', 8.3, 6607, 'tt0100339', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1137689110.jpg', 0.3, 1, 17.7, 46.4, 34.6, '0.329058,0.100158,-0.821081,0.308821,-0.019992,0.150100,0.557344,-0.092674,-0.579712,-0.342451,0.385778,0.541353,-0.078498,-0.146027,0.271148,-0.204071,-0.449185,-0.531843,-0.395575,-0.189176,-0.689312,-0.547778,-0.226425,-0.502522,0.131560,-0.450834,0.800192,0.078618,-0.369104,-0.046372,-0.022349,0.447043,-0.381571,0.331101,0.044231,-0.194250,0.052520,-0.306108,-0.181169,0.173507,-0.258689,-0.339660,0.075100,0.075960,-0.103131,0.222209,0.793029,-0.293129,-0.441562,-0.169105,0.524442,-0.272789,-0.042061,-0.287747,0.590968,0.173155,-0.223003,0.150021,-0.441208,0.162647,0.170080,-0.028495,-1.044669,-0.272265,-0.084674,0.146536,-0.375722,0.004157,-0.283109,0.148934,0.178925,-0.364145,0.298745,0.516105,0.428652,0.458829,-0.238030,0.119232,-0.479455,0.211656,0.557670,-0.119801,-0.471713,0.272517,0.227864,-0.434459,-0.302632,-0.381394,-0.140160,0.079848,0.226460,0.022696,-0.142464,0.386995,-0.619672,0.030510,-0.135956,-0.594575,-0.044241,-0.113033,-0.084463,-0.908699,0.060572,-0.067954,-0.155349,0.253488,0.277697,-0.074824,0.718568,-0.875412,0.023477,0.641087,0.170990,-0.611630,0.180794,-0.342690,0.254767,-0.228061,-0.163645,-0.329601,0.236547,0.862961,0.108053,0.286729,0.190328,-0.532198,-0.333272,0.184497', '2369613', '2577