INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1467779', '天使之卵', '科幻', '影片架构在一个充满阴影和灰暗色彩的超现实主义世界中，剧情的主角是两个没有提及名字的少年（根津甚八 配音）与少女（兵藤真子 配音）。少女随身带着一颗神秘的蛋，她花许多的时间在某个歌德式的死城里搜集各式瓶子与手工艺品。身上背着一把十字型武器的少年在某天也随着一种神秘的机械来到这个城镇。同时，巨大腔棘鱼的身影在城镇上方出现，城市里的人也成群的活过来开始用长枪猎捕这些鱼群。在少女如巨穴般的瓶子中，就像个庇护所一般，里面收藏着蒐藏品。少年等少女入睡后将那颗神秘的蛋打破。少女表现得很生气并紧跟着已经离开的少年。最后少女沉入了溪谷中死去，她口中吐出来的气泡最后都化作了一颗颗的蛋。本片由日本导演押井守以及知名插画家天野喜孝合作，德间书店于1985年发行，并于2007年以DVD形式再版。影片旁白由野田圭一担任。©豆瓣', '根津甚八', '押井守', 8.2, 8284, 'tt0208502', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2570194697.jpg', 0.7, 2.5, 18.9, 44.2, 33.7, '0.192014,0.179292,-0.449967,0.546061,0.009871,-0.068746,1.178021,-0.016807,-0.276570,-0.065158,0.125176,0.746581,-0.408272,0.320050,0.142969,0.009154,-0.133302,-0.617439,-0.444570,-0.288827,-0.254922,-0.149945,-0.301337,0.070753,-0.234129,-0.213680,0.901424,0.134243,-0.078367,0.329119,0.223326,0.061039,-0.338041,0.322731,-0.265897,-0.190082,-0.146559,-0.041504,0.142710,0.270432,-0.111250,-0.329433,-0.022217,0.059045,-0.162799,0.123966,0.971074,-0.506357,0.114915,-0.126688,0.304363,0.088180,-0.277955,-0.083296,0.250211,0.178485,0.255777,-0.139103,-0.254874,0.091888,0.197230,-0.342092,-0.356505,-0.147025,0.058229,0.555662,-0.613768,0.244738,0.042843,0.067579,0.144008,-0.514155,0.221858,-0.288899,0.276678,0.414234,-0.209812,0.089014,-0.388365,0.392417,0.114281,-0.034400,-0.426368,0.177668,-0.263599,-0.474070,-0.301990,0.125527,-0.256419,-0.139641,0.333403,0.085001,-0.243801,0.147976,-0.819476,0.207023,0.022282,-0.351399,-0.043551,-0.201822,-0.581714,-0.586341,-0.007829,-0.143640,-0.090608,0.107226,0.137282,0.062749,0.780154,-0.517979,0.421338,0.392075,0.100590,0.163612,0.471326,-0.251604,-0.010749,-0.179073,-0.104032,0.130322,0.157979,0.079005,0.012137,0.553371,-0.239870,-0.128251,-0.536788,0.394203', '21619567', '20451118', '25884436', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1468154', '春田花花同学会', '喜剧', '本片是《麦兜故事》系列的第三部，由现实和动画两部分故事组成。现实部分的故事开始于一次“人质挟持事件”，一群持枪匪徒闯入香港中环的国际金融中心（IFC），劫持了一家广告公司的数十名职员，在和警方对峙的关键时刻，匪徒提出要吃外卖盒饭，警方进一步调查发现此案线索涉及“春田花花幼儿园建校五十周年校庆”，而匪徒在与广告公司职员交谈时，发现某个直发披肩女孩（周笔畅）来自著名而神秘的网站春田花花幼儿园，产生好奇。而穿插在现实部分里的动画故事，春田花花幼儿园的小朋友幻想着自己将来快乐简单的理想职业生活，可是长大的他们（黄秋生、郑中基、梁咏琪等），换取温饱的方式多数变成了目标不分的随大流装傻。©豆瓣', '周笔畅', '赵良骏', 6.2, 41618, 'tt0499525', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p805081207.jpg', 4.9, 18.2, 46.6, 21.4, 8.9, '0.411895,-0.128469,-0.374304,0.453370,0.098188,0.156440,0.547231,0.330170,-0.365100,-0.229262,0.109602,0.636493,0.007913,0.319944,0.182417,-0.028287,-0.265547,-0.618566,0.006476,-0.093896,-0.090207,-0.492610,0.016052,-0.384712,0.024854,-0.039016,0.650573,0.022806,-0.264058,0.424442,0.497173,0.127742,-0.601484,0.129739,-0.088968,-0.121005,0.485473,-0.023069,-0.438005,0.184669,-0.261665,-0.225886,-0.056284,-0.068488,-0.127122,0.210189,0.854890,0.123179,-0.192286,0.094946,0.603766,-0.337959,-0.358769,-0.164673,0.478297,0.144198,0.440500,-0.011948,0.043188,0.092020,-0.183097,-0.210819,-0.620773,-0.143186,0.027718,0.296255,-0.410536,0.405165,-0.074952,0.219406,0.337627,-0.358246,0.155945,0.192303,0.459927,0.359671,0.049970,0.174267,-0.487198,0.369136,0.497880,-0.177327,-0.070398,0.327716,-0.242820,-0.337372,-0.187743,-0.032022,-0.243448,0.093710,0.217777,-0.218430,-0.457649,0.242713,-0.777465,0.051251,0.015686,-0.324039,0.175261,-0.294560,-0.198415,-0.814835,-0.021798,-0.186403,-0.111902,-0.036221,0.233687,-0.123470,1.019054,-0.734223,0.031700,0.674688,0.157456,-0.637443,0.776701,0.174540,0.243784,-0.382553,-0.026231,-0.087186,0.043179,0.108911,-0.015161,0.264097,-0.202947,-0.236338,-0.429132,0.104860', '3811356', '5403927', '25863940', '1418179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1468155', '伊莎贝拉', '剧情', '1999年，澳门回归中国前。澳门司警马振成（杜汶泽饰）因惹上是非遭停职，警察生涯即将终结。马振成与伙计仍然夜蒲，盲打误撞遇上一名神秘少女张碧欣（梁洛施饰）。张碧欣随之跟着马振成回家，醉酒醒来的马振成以为自己与对方有了一夜情，再加上碧欣声称是他与初恋情人分手后生下的女儿，更加令马振成错愕不已。碧欣因欠租数月以致无家可归，其心爱的狗狗伊莎贝拉亦被无良业主赶走，下落不明。身为父亲的马振成希望能弥补以往的责任，其后碧欣坚决要与马振成同住，令一向放浪的马振成生活顿起变化。为求自保，马振成企图以身犯险令自己得以脱罪，他的好友杜Sir（黄秋生饰）亦屡劝无效。张碧欣欢欣鼓舞地准备与父亲落草，对着同校男生也难掩得意之色。然而渐渐地马振成从张碧欣身上，体会到什么是责任。©豆瓣', '杜汶泽 Chapman To', '彭浩翔', 7.6, 72230, 'tt0499141', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2154990442.jpg', 0.5, 3, 30.8, 47.9, 17.7, '0.037792,-0.089361,-0.525464,0.373971,-0.150436,-0.385153,0.484401,0.025420,-0.565851,-0.247840,0.034189,0.638446,-0.031653,0.542529,0.315331,-0.187629,-0.073599,-0.576478,-0.132834,0.006179,-0.113354,-0.240406,-0.153182,-0.015020,-0.404485,-0.224590,0.559846,0.142827,-0.210898,0.539878,0.437449,0.310228,-0.235118,0.497487,-0.067327,-0.019176,-0.328908,0.100050,-0.448701,-0.018638,0.130590,-0.411330,-0.220724,0.067607,-0.090944,0.354220,0.584102,-0.074822,-0.235696,-0.226642,0.442923,-0.189186,0.089097,0.264933,0.156055,0.117752,0.227679,0.387889,-0.139813,-0.035809,0.174495,0.030864,-0.480957,0.127534,0.159991,-0.188684,-0.497991,0.154332,-0.165943,0.078114,0.113902,-0.203518,0.153962,0.354970,0.128610,0.299959,-0.222652,0.064259,-0.330284,0.118561,0.691572,0.176717,-0.010156,0.146122,-0.090916,-0.309786,0.189185,-0.408606,-0.473829,0.052454,0.089790,0.259398,-0.179388,0.320696,-0.265058,-0.270694,-0.266117,0.195008,-0.068781,-0.176633,0.051441,-0.202708,-0.123393,-0.321522,-0.412596,0.204280,0.207043,-0.260709,0.425789,-0.816032,0.202495,0.351997,0.305178,-0.621674,0.510119,0.237403,0.260171,-0.115959,-0.085382,0.224840,0.058965,0.102017,0.068904,0.032655,-0.232550,0.019932,-0.181494,0.196538', '1301022', '35030151', '30345227', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1468527', '新半斤八两', '喜剧', '许氏三兄弟主演，许冠文编剧的本片，剧情简单，许冠文是娱乐周刊的社长，为了挽救将倒闭的杂志社，费尽心思发掘消息。影片中许依旧是刻薄的老板，许冠杰仍是身手不凡的醒目仔，许冠英依然傻得惹人可怜。本片始终对时代有一定的触觉，明星绯闻，美容隆胸，卡拉OK这些新兴事物为影片制造了不少乐趣。陈欣健执导手法与许氏相近，同样以演员的表演作主导，并以此为剧情的重心。影片虽然能触及社会问题，但深度不够，未能自我突破。许冠文是娱乐周刊的社长，为了挽救将倒闭的杂志社，费尽心思发掘消息。影片中许依旧是刻薄的老板，许冠杰仍是身手不凡的醒目仔，许冠英依然傻得惹人可怜。本片始终对时代有一定的触觉，明星绯闻，美容隆胸，卡拉OK这些新兴事物为影片制造了不少乐趣。', '许冠文', '陈欣健', 7.4, 7030, 'tt0100974', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1387184520.jpg', 0.4, 3.1, 37.4, 43.1, 16, '-0.249804,0.045331,-0.180751,0.391387,0.021232,0.006054,0.450548,0.267568,-0.594036,-0.198107,0.082955,0.620759,-0.316180,0.024961,-0.038161,-0.053235,-0.025614,-0.415937,-0.004814,0.141109,0.292436,-0.355622,-0.459494,-0.320919,-0.452024,-0.297829,0.756838,0.150447,-0.616894,-0.154002,0.400978,-0.043296,0.050087,0.305651,0.155016,-0.171613,-0.022891,-0.062797,-0.419817,0.203356,0.084029,-0.367824,-0.160213,0.145859,-0.117648,0.365001,0.458405,0.111721,-0.240642,-0.052958,0.787847,-0.282417,-0.054145,-0.150908,0.085684,-0.027110,0.493131,0.223687,-0.118644,0.022695,0.020059,-0.223256,-1.268683,0.014822,0.492520,0.238242,-0.362391,0.246534,-0.307786,-0.153836,-0.013336,-0.007702,0.235000,-0.073381,0.579776,0.237919,0.075722,0.454139,-0.198785,0.488598,0.327230,0.362949,-0.327781,0.551985,-0.284467,-0.539663,-0.132915,-0.505330,-0.281735,0.381386,0.001611,-0.035796,0.064000,0.243712,-0.470432,0.177720,-0.029942,-0.310962,-0.003569,-0.370252,0.122235,-0.956981,-0.088344,-0.351328,0.027630,-0.482197,0.397379,-0.384811,0.989457,-0.587926,-0.199884,0.611002,0.186807,-0.644130,0.829217,0.142377,-0.223182,-0.291413,-0.540856,0.022329,-0.051497,-0.037898,-0.010862,0.079667,0.058107,-0.715377,-0.183239,0.358196', '27602116', '3318306', '6844861', '25918677');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1468547', '学校风云', '剧情', '中五在读的朱婉芳（袁洁莹 饰）与郭小珍（李丽蕊 饰）本是一对儿普通的中学女生，直至帮派分子刀疤试图接近朱婉芳，在校门口殴打一名不良学生致其意外身亡。警官海哥（林正英 饰）要求朱婉芳出面作证，虽然刀疤之大哥潇洒（张耀扬 饰）恶语威胁，但朱婉芳有感温老师（刘松仁 饰）与海哥的正气，终于指认嫌凶。潇洒大为光火将朱婉芳掳走勒索，温老师在众目睽睽之下却无力保护自己的学生。为偿还欠款，朱婉芳与郭小珍打工度日，刀疤从旁默默相助终于令婉芳留意他温柔的一面。不久郭小珍发现男友佐治背叛，伤心欲绝之际遭车祸身亡，朱婉芳的世界，突然间分崩离析……本片是林岭东风云三部曲的最后一部，剧本仍由其兄林岭南（南燕）操刀。©豆瓣', '袁洁莹', '林岭东', 8.1, 20682, 'tt0096472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2190608234.jpg', 0.4, 1.6, 19.6, 48.5, 29.9, '-0.080992,-0.062624,-0.339109,0.264554,0.096948,-0.354507,0.591389,0.270210,-0.236837,-0.331073,0.425424,0.413654,-0.095504,0.372258,0.178497,-0.195625,0.007753,-0.550892,-0.110368,0.056813,-0.072442,-0.300266,-0.295644,-0.081237,-0.282162,-0.337935,0.463086,0.066171,-0.290548,0.546088,0.338624,0.333315,-0.345455,0.322383,0.017240,-0.137184,0.086121,0.054237,-0.310960,-0.147194,-0.081066,-0.501566,-0.113967,-0.109559,-0.076696,0.504400,0.534781,-0.078304,-0.209191,-0.193922,0.480070,-0.192964,-0.152414,0.117868,0.282974,-0.021083,0.248848,0.081261,-0.201510,0.019099,0.184881,-0.063510,-0.374489,0.081789,0.255435,0.127300,-0.208089,0.328646,-0.209563,0.016793,0.204661,-0.103475,0.008714,0.057183,0.264341,0.103663,-0.262457,0.152460,-0.118288,0.258513,0.330535,0.011781,0.028008,-0.013241,0.127016,-0.322364,0.148448,-0.037072,-0.187874,0.146707,0.133369,-0.090453,0.042701,-0.054740,-0.210031,-0.300989,-0.261999,0.447754,-0.043268,-0.097445,-0.110573,-0.411373,0.077022,-0.051150,-0.052151,0.175352,0.113038,-0.069121,0.415098,-0.466572,0.075094,0.005526,0.318060,-0.417791,0.337445,0.185072,-0.126432,-0.147504,-0.220837,0.048520,0.323037,0.157865,0.126702,0.203632,-0.174181,-0.389650,-0.097942,-0.001248', '1432699', '4202326', '1773217', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1468710', '皮毛', '剧情', '1958年，美国纽约。此时的黛安•阿布斯（妮可•基德曼 Nicole Kidman 饰）还是一个只知相夫教子的平凡女人。她生在富有的犹太商人家庭，父母经营着著名的Russek皮草店。从小养尊处优的黛安与身份悬殊的艾伦•阿布斯（泰•布里尔 Ty Burrell 饰）结婚，并努力协助他的时尚摄影工作。来自父母家庭的苛责以及婚后生活的枯燥无聊都让黛安倍感压抑和孤独。某日，一个新搬来的邻居莱昂内尔（小罗伯特•唐尼 Robert Downey Jr. 饰）出现在黛安的生活中，她为对方的神秘所吸引，开始有意识地去注意和探究莱昂内尔的一切。不知不觉间，她的人生悄然发生改变……本片根据Patricia Bosworth在1984年出版的关于黛安•阿布斯的畅销传记小说改编。©豆瓣', '妮可·基德曼', '史蒂芬·西恩博格', 6.9, 5687, 'tt0422295', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p705692065.jpg', 1.7, 9.6, 42.5, 32.9, 13.3, '0.370035,0.018357,-0.534874,0.551543,-0.134473,-0.381042,0.733675,0.187270,-0.329383,-0.644740,-0.088506,0.675745,-0.137454,0.315283,0.308084,0.032142,-0.546470,-0.655938,-0.087205,-0.076413,-0.004649,-0.439417,-0.235703,-0.493493,-0.248655,-0.361908,0.384284,-0.120973,-0.104860,0.393880,0.274587,0.401403,-0.144494,0.385010,0.072994,0.005261,0.140238,0.076026,-0.259974,-0.101770,0.027159,-0.033961,-0.134016,-0.062223,0.287356,0.220034,0.697642,-0.365746,0.071767,0.002657,0.625375,0.130337,-0.034774,-0.059249,0.156019,-0.029704,-0.044005,0.169617,-0.365430,0.101658,0.036332,-0.259800,-0.731167,-0.190401,0.217750,0.257536,-0.542691,0.450559,-0.077004,-0.280871,0.016937,-0.459465,-0.029059,0.470098,0.211270,0.571963,0.111770,0.383174,-0.192326,0.250992,0.634928,0.172124,-0.365170,-0.043600,-0.551689,-0.575944,0.160008,-0.181017,-0.754564,-0.085024,0.312242,-0.043522,-0.017451,0.696454,-0.530502,-0.005208,-0.156400,-0.163528,0.096296,-0.512346,-0.131095,-0.762083,-0.204087,-0.607247,-0.158570,-0.188857,-0.005295,-0.349611,0.627244,-0.654386,0.524577,0.472658,0.308467,-0.147398,0.728981,-0.019910,0.414704,-0.203820,-0.516392,0.654011,0.025732,0.005741,-0.018821,0.311180,0.096153,0.066339,-0.089323,0.590155', '3160978', '3009079', '1460341', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1469049', '处刑人', '剧情', '一对热血虔诚的爱尔兰裔兄弟，因自卫杀人而得罪黑帮，警署以正当防卫之名无罪释放。从此之后，二人决定以己之力对抗社会渣滓，购买武器以暴制暴，在朋友洛克（大卫·德拉·洛克David Della Rocco 饰）的帮助下清除犯罪分子。联邦警探保罗·斯迈克（威廉·达福 Willem Dafoe 饰）负责侦破案件，本来毫无头绪；但 在黑帮头子“老爸乔”（卡洛·罗塔 Carlo Rota 饰）雇佣了传奇枪手“公爵”（比利·康诺利 Billy Connolly 饰）对抗麦克马纳斯兄弟之后，情况却发生了意想不到的变化……©豆瓣', '威廉·达福', '特洛伊·达菲', 8.2, 46344, 'tt0144117', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p921876170.jpg', 0.6, 2.4, 18.5, 45.8, 32.7, '0.218153,-0.264659,-0.324146,0.307842,0.094923,-0.438562,0.363021,0.377525,-0.467679,-0.412858,0.429236,0.312908,0.144392,-0.413016,0.412837,-0.348596,-0.641803,-0.574859,0.168935,-0.119370,0.010287,-0.681825,-0.415052,-0.442304,0.036272,-0.306659,0.391180,-0.133310,-0.109336,0.291130,0.249537,0.514266,0.043974,0.116932,0.439200,-0.172575,0.526971,-0.277288,-0.677621,0.094332,-0.127209,0.088882,-0.019427,0.060040,0.215484,0.477727,0.332726,-0.474130,0.131847,-0.417062,0.120795,-0.173531,0.086896,0.003534,0.365890,-0.158098,-0.042472,0.240925,0.207874,-0.271415,0.354027,0.043003,-0.611583,0.113035,-0.002014,0.227802,-0.370871,0.184428,-0.512657,0.098222,-0.023277,-0.065084,-0.014944,0.283269,0.510870,-0.057527,0.084711,0.041344,-0.411755,-0.046174,0.519586,-0.083855,-0.203953,-0.193819,-0.254531,-0.366082,-0.197627,-0.361426,-0.254460,-0.276990,0.247550,-0.330847,0.120901,0.448992,-0.367306,-0.520997,-0.332068,0.118389,-0.158308,-0.182417,0.226766,-0.722358,-0.180960,0.187042,-0.105922,-0.133645,0.303883,-0.021868,0.370353,-0.548253,-0.026964,0.423421,0.190281,-0.238165,0.232977,-0.203367,0.010193,-0.282506,-0.296097,0.361895,0.671481,0.206620,0.211316,0.051643,0.185410,-0.025534,0.478483,0.061398', '3006781', '2369549', '6517421', '3541415');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1469111', '爱你如诗美丽', '剧情', '教授阿蒂利奥（罗伯托·贝尼尼 Roberto Benigni饰）对诗有着狂热的喜爱。离了婚的他带着两个小女儿，每天都致力于让他的学生发现诗的美好。近来，有一个梦境常常困扰着他，梦中他在教堂里迎娶一个女子。直到他参加阿拉伯诗人福阿德（让·雷诺 Jean Reno饰）的记者招待会，才终于在现实中见到了梦中的女子。他坚信眼前的她（尼可莱塔·布拉斯基 Nicoletta Braschi饰）正是自己命运中注定的另一半。于是，这个诗人像迷恋诗歌一样，迷恋上了这个福阿德身边的文学研究员维多利亚。但是，维多利亚对阿蒂利奥并无好感。她随福阿德回到伊拉克，却不幸中在战火中受了重伤。阿蒂利奥闻讯，不顾一切的奔往那个战火纷飞的国度，寻找心爱的维多利亚，为她疗伤让她苏醒。曲折的旅途就像历险，然而心中有爱，一切都变得无惧。©豆瓣', '罗伯托·贝尼尼', '罗伯托·贝尼尼', 8.1, 9822, 'tt0419198', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p800589560.jpg', 0.4, 2.2, 20, 45.9, 31.5, '0.272719,0.184489,-0.858974,0.664618,-0.120037,-0.392287,1.070304,-0.088405,-0.478791,-0.279507,0.256044,0.802994,-0.131817,0.457445,0.243855,0.355233,-0.441498,-0.840442,-0.209917,-0.017817,-0.260021,-0.351461,-0.249484,0.000522,-0.221993,-0.297497,0.347671,0.157532,-0.005484,0.618002,0.199734,0.274937,0.141656,0.640119,-0.058587,0.122949,0.203328,0.135086,-0.124508,0.002477,0.046202,-0.149643,-0.233888,0.474790,-0.277765,0.197675,0.602728,-0.549349,0.026487,-0.028840,0.441678,-0.331409,0.085906,0.269350,-0.134008,0.089801,0.063671,-0.205711,-0.205733,0.007257,-0.072558,-0.001393,-0.627400,-0.066359,0.180395,0.348754,-0.681414,0.552936,-0.032887,-0.024884,0.080581,-0.147041,0.222190,-0.040791,0.385796,0.526642,0.015982,0.008855,-0.466478,0.085716,0.611551,0.134294,-0.381519,0.354363,-0.577037,-0.381866,0.193113,-0.043650,-0.553690,-0.031998,0.182905,-0.140657,-0.186543,0.388936,-0.430636,0.180224,-0.370294,-0.097948,-0.179062,-0.313929,-0.177780,-0.396441,-0.172787,-0.518875,-0.295342,-0.023080,-0.008377,-0.414899,0.861322,-0.651882,0.577610,0.890104,0.205733,-0.382568,0.729314,0.206610,0.132595,-0.074109,-0.085050,0.720165,-0.210016,0.083626,-0.128754,0.399128,-0.052013,0.017175,-0.487359,0.860559', '1309172', '1291877', '30162520', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1469353', '布鲁克林秘案', '剧情', '莱昂内尔（爱德华·诺顿 Edward Norton 饰）有着非常悲惨的过去，母亲在他很小的时候就撒手人寰，无依无靠的莱昂内尔被送进了孤儿院，幸运的是，在这里，他遇见了名为弗兰克（布鲁斯·威利斯 Bruce Willis 饰）的男子，在孤儿院里摸爬滚打这么多年，弗兰克一直对莱昂内尔提供着保护和帮助。离开孤儿院后，弗兰克成立了一家私人侦探所，莱昂纳尔则在其中打工。某日，弗兰克去送一份非常危险而又神秘的文件，哪知道这个任务让他丢掉了性命。弗兰克的死给莱昂内尔带来了巨大的打击，但现在还不是哀悼的时候，莱昂内尔决定查出这场死亡时间背后的真相，为老友讨回一个公道。©豆瓣', '爱德华·诺顿', '爱德华·诺顿', 7, 18988, 'tt0385887', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2572943395.jpg', 1.1, 6.1, 44.1, 37.9, 10.9, '0.055513,0.065855,-0.549484,0.520776,-0.524330,-0.401343,0.766732,0.177262,-0.569648,-0.305765,-0.010510,1.036897,0.133046,0.353466,0.326680,0.273635,-0.366161,-0.447779,-0.058041,-0.372035,-0.366105,-0.722176,-0.358115,-0.396030,-0.007313,-0.150683,0.313935,0.010032,0.071998,0.344352,0.197451,0.475519,0.095637,0.590158,-0.363053,0.252250,0.220463,-0.061869,-0.011324,0.432819,0.409178,-0.048889,-0.164878,0.254608,0.180760,0.403061,0.163004,-0.117919,-0.167290,-0.156352,0.333822,-0.300964,0.066412,0.171057,0.131514,-0.178872,0.301737,0.204097,-0.476924,0.131384,0.224179,-0.167005,-0.846551,-0.003078,-0.132497,0.104844,-1.069474,0.501173,-0.341783,-0.118236,0.099513,-0.590813,0.262055,0.412979,0.207321,0.279688,-0.192274,-0.016765,-0.604276,-0.105728,0.593560,-0.331340,-0.079487,0.035299,-0.123349,-0.240192,0.247785,0.015031,-0.502423,0.035447,0.479461,-0.023343,0.022741,0.078869,-0.505496,-0.168528,-0.557738,-0.231570,-0.086926,-0.535430,-0.306453,-0.361083,-0.147517,-0.062175,-0.396063,-0.098001,-0.135992,-0.327648,0.590978,-0.661948,0.505561,0.781750,0.316160,-0.366521,0.636992,0.166852,0.339500,-0.176417,0.030290,0.313811,0.134201,0.267591,0.097222,0.171014,0.235905,-0.308050,-0.155436,0.638436', '1309069', '3279069', '1299965', '1292584');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1469441', '看上去很美', '剧情', '在大人和老师眼里，方枪枪不是个好孩子，他调皮捣蛋不听话，一进幼儿园，就被老师追着剪了辫子。方枪枪（董博文 饰）生活的幼儿园里有几百名小朋友，在那里他认识了杨南燕（宁元元 饰）、杨北燕（陈曼媛 饰）。幼儿园里有统一的标准管理着所有小朋友，按时拉屎、自己穿衣，表现优秀的人会被授予 小红花，贴在他们名字后面。慈眉善目的唐老师（李昕芸 饰）让方枪枪感到亲近，而不苟言笑的李老师则让他感到恐惧。总也得不到5朵小红花的方枪枪在一次意外后，对小红花失去了兴趣。他编故事，给小朋友起外号等等。有天晚上他做了个怪梦，第二天醒来，他把这个秘密告诉别的小朋友，说李老师是一个吃人的大妖怪！……©豆瓣', '董博文', '张元', 7.9, 84060, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567685798.jpg', 0.5, 2.7, 23.3, 48.4, 25.1, '0.285799,-0.115848,-0.543677,0.471966,-0.567064,-0.130787,0.476939,-0.049413,-0.443258,-0.208838,-0.244819,0.459539,-0.143611,0.467354,-0.047390,0.106638,-0.037472,-0.641010,-0.112738,0.025811,-0.419317,-0.373614,0.071007,-0.191526,-0.101816,0.041300,-0.172419,-0.299873,-0.125525,0.636921,0.430275,-0.061540,0.316104,0.293321,-0.288161,0.083788,0.022388,0.136055,0.334784,0.171246,0.222296,-0.079914,-0.059050,0.097449,0.268501,0.119332,0.628610,-0.204854,-0.292600,-0.115722,0.266469,-0.191928,-0.029946,0.008630,0.367748,0.147502,0.117851,-0.269024,-0.022454,0.386937,0.182182,-0.131991,-0.283170,0.029721,0.084031,0.082673,-0.786487,0.604119,-0.166136,0.032565,0.298765,-0.395107,0.575937,-0.090260,0.109829,0.367974,-0.051962,0.127786,-0.608000,0.331082,0.420480,-0.106008,0.006283,-0.081871,-0.297608,-0.134818,0.073971,0.057212,-0.433978,0.208385,0.249995,-0.429004,-0.226804,-0.133321,-0.319415,-0.046901,0.234723,0.000588,-0.133568,-0.409246,-0.092438,-0.034542,0.226424,-0.260979,-0.336559,0.138323,-0.013229,-0.201513,0.912515,-0.771194,0.258618,0.200499,0.425177,-0.309982,0.769899,0.201520,0.033223,-0.163969,0.103038,-0.114753,0.253772,0.238979,0.238098,0.524041,0.094630,-0.322826,-0.330488,0.348698', '1308609', '1307741', '1307146', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1469984', '翡翠森林狼与羊', '动画', '暴风雨之夜，小羊羊咩（成宫宽贵 配音）和野狼卡滋（中村狮童 配音）意外的躲进了一间小木屋避雨。在漆黑的房间里，羊咩和卡滋看不清彼此，交谈甚欢并约好第二天一起午餐。相约见面时，羊咩和卡滋发现了彼此的身份，面对羊咩的天然和善良，卡滋强忍着把羊咩吃拆入腹的冲动，在羊咩面前努力做只好狼，二者迅速成为好朋友。羊咩和卡滋成为好友的事被羊群和狼群发现。羊咩被族长赋予任务去探听狼群的消息才能重归羊群；而卡滋这边，狼族给了卡滋“将功赎罪”的机会去羊咩那探听羊群的消息。身怀心事的羊咩和卡滋再次相约河边见面。突如其来的暴雨和卡滋的相救让二者发现无法去欺瞒对方，相约跳入洪流中的羊咩和卡滋劫后余生，没有退路的他们决定翻阅雪山，前往能让狼和羊能和平共处的翡翠森林。在前往的路上遭遇了狼族的围追，他们能否成功翻越雪山躲过狼群，卡滋又能否克服吃羊的天性，一起到达梦想的翡翠森林呢？©豆瓣', '中村狮童', '杉井仪三郎', 8.3, 21288, 'tt0498465', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p805833250.jpg', 0.3, 1.6, 17.4, 43.1, 37.7, '0.289919,-0.274428,-0.478816,0.539040,0.297510,-0.020544,0.413772,0.279651,-0.158727,0.018187,-0.361675,0.429840,-0.153507,-0.080819,0.008131,-0.275148,-0.295716,-0.393664,0.154602,0.109388,-0.163465,0.054016,-0.260227,-0.065724,0.127815,0.141308,0.413155,0.027674,-0.031261,0.895626,0.078268,0.161510,-0.477124,0.428817,-0.216347,0.069112,0.099336,-0.046749,-0.269004,0.338142,-0.108581,0.027534,0.005154,0.157184,0.287495,0.236709,0.788592,-0.530620,-0.319138,-0.201432,-0.297114,-0.156449,0.385620,0.342916,0.289365,-0.076219,0.432279,0.173344,0.028790,0.136195,-0.063031,-0.249462,-0.517923,0.016595,-0.115761,0.151829,-0.349532,0.372086,0.293482,0.073757,0.563420,-0.189376,0.180631,0.197229,0.363828,0.542631,-0.059805,0.179955,-0.701147,-0.241147,0.850216,-0.226262,0.476405,0.103303,0.453833,-0.515075,0.505553,0.039882,0.036814,-0.172938,0.580529,0.412307,-0.886037,0.149168,-0.980450,-0.018793,-0.050120,-0.355357,0.065694,-0.420377,-0.197109,-0.608497,0.162793,-0.186455,-0.011434,0.430026,0.231850,-0.311993,0.536225,-0.753115,0.299295,0.358460,0.402178,-0.216968,0.809563,-0.285346,0.067004,0.002009,0.310853,-0.080350,0.314552,0.342105,0.761612,0.282252,-0.092553,-0.117065,-0.853872,0.361413', '26603666', '35256235', '1