INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1470328', '罗密欧点', '剧情', '1972年的越南战争，韩国亦卷入其中。崔泰宇（甘宇成 饰）中尉所在的部队在一场战争中全部被歼，仅剩崔泰宇一人生还。崔泰宇常常被噩梦折磨而醒，为摆脱心魔，他主动要求归队，但迟迟得不到批准。CID的副队长对崔泰宇下达了一道秘密搜索的命令：6个月前在R-高地战争中已确认阵亡的18名士兵持续发来求救信息，要求崔泰宇带领部队前往R-高地进行搜救。3天后，崔泰宇带领10几名部下来到了R-高地入口，那里原来有一座古庙，因战争被炸毁，但庙前的石碑依然高耸着：双手染血者不归……©豆瓣', '甘宇成', '孔水昌', 7, 9107, 'tt0417072', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2617545713.jpg', 1.4, 6.9, 42.5, 36.4, 12.8, '-0.031754,0.067568,-0.811640,0.674166,0.188336,0.074752,0.478402,-0.136792,-0.319644,-0.188779,0.365986,0.350700,0.063452,-0.146854,0.379930,-0.303515,-0.241670,-0.662347,-0.324720,-0.308991,-0.526789,-0.466589,-0.019597,-0.042425,-0.011150,-0.379045,0.879054,0.363914,0.051788,0.526385,0.200569,0.120915,-0.124929,0.579777,0.196669,-0.058403,0.338227,-0.291393,-0.043056,0.448155,-0.455916,-0.411925,0.003418,0.136961,-0.129100,0.428540,0.839672,-0.649879,-0.077598,-0.124448,-0.089110,-0.361236,0.061727,0.252307,0.777862,0.283882,-0.035953,0.377829,-0.367316,0.364644,-0.167692,-0.180191,-0.376563,-0.243890,-0.005101,0.100230,-0.456716,0.379863,-0.169409,0.277906,-0.057483,-0.124978,0.214492,0.573807,0.210485,0.258215,-0.418721,0.031732,-0.435354,-0.041034,0.479835,-0.307953,-0.042223,-0.248015,0.032879,-0.417746,0.080890,-0.080694,-0.218243,0.031684,0.101601,0.241222,-0.065726,0.033846,-0.565108,0.208709,-0.363105,-0.448506,-0.089418,-0.286908,-0.296863,-0.773771,0.024186,0.341069,0.043506,0.347486,-0.154464,0.169182,0.648350,-0.480545,0.321574,0.358210,0.438692,-0.371689,0.510413,0.399103,0.323361,-0.060860,0.296430,0.545511,0.082248,0.562371,0.169422,0.021911,-0.317653,-0.374043,-0.251872,0.080632', '35058077', '1449328', '3266509', '1381964');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1470346', '卡萨诺瓦', '剧情', '贾柯莫·卡萨诺瓦（希斯·莱杰 Heath Ledger 饰）是威尼斯著名的浪荡子，从伯爵夫人到禁欲修女，似乎每个女人都抵抗不了他的睿智和风流。终于，他的放荡行为触怒了宗教局，被捕之后险些处以绞刑，幸好朋友及时出现力挽了狂澜。朋友警告卡萨诺瓦，如果不能找到一个正派女子结婚 ，他将被逐出威尼斯。卡萨诺瓦幼年时母亲离他而去，并且许下承诺将来会来威尼斯与他重聚，卡萨诺瓦一直相信着这个诺言。为了等待母亲，即使带上了婚姻的枷锁，他也要留在威尼斯。在机缘巧合之下，卡萨诺瓦认识了弗朗西斯卡（西耶娜·米勒 Sienna Miller 饰）。弗朗斯西卡思想前卫，饱读诗书又主张男女平等，这一切对于见惯了肤浅女人的卡萨诺瓦来说有着致命的吸引力。但是一方面，他们两人都有着未履行的婚约。另一方面，聪慧的弗朗西斯卡就像一头彪悍的小马那样难以驯服，卡萨诺瓦必须做出巨大的努力，才能捕获他的芳心。而在这条艰难的道路上，卡萨诺瓦渐渐的领悟了爱情与欲望的区别。', '希斯·莱杰', '拉斯·霍尔斯道姆', 7.1, 18274, 'tt0402894', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2239651599.jpg', 0.7, 5.2, 45.1, 37.8, 11.3, '0.139589,0.204246,-0.703779,0.734078,-0.228078,-0.377452,0.728685,0.082183,-0.431962,-0.166458,0.159560,0.710917,0.076597,0.132670,0.314410,0.028857,-0.263606,-0.679887,0.115000,-0.209114,-0.236151,-0.529375,-0.170278,-0.104293,-0.214596,-0.469024,0.604464,0.014372,-0.199282,0.198019,0.407683,0.451713,0.064987,0.359358,-0.424775,-0.147457,-0.016532,-0.017150,-0.267352,0.245547,0.124721,-0.141543,0.017891,0.254127,-0.152527,0.320448,0.387622,-0.381410,-0.258713,-0.036197,0.363402,-0.250213,0.083519,0.491946,0.030043,-0.095300,0.246272,0.226644,-0.260471,-0.005056,0.235916,-0.232732,-0.763763,-0.037765,0.024545,0.063565,-0.642135,0.568844,-0.113148,-0.050901,-0.040855,-0.348652,-0.042598,0.147743,0.246231,0.208966,-0.069058,0.087532,-0.476224,-0.045950,0.789935,-0.019165,-0.440047,0.336962,-0.380413,-0.359401,-0.041937,-0.395094,-0.590786,0.077947,0.286777,0.170881,-0.332539,0.324914,-0.324890,-0.207550,-0.368763,0.159909,-0.101892,-0.392235,-0.022655,-0.124906,-0.254836,-0.478430,-0.398625,0.133234,0.125446,-0.198014,0.709941,-0.837468,0.279994,0.612739,0.399519,-0.508639,0.681694,0.186687,0.076932,-0.091736,-0.102312,0.479200,-0.016324,0.209031,0.159091,0.318615,0.201484,0.002025,-0.214405,0.722025', '35030151', '4058933', '1304641', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1470865', '失业生', '剧情', '电影讲述了阿荣（张国荣 饰）、家宝（陈百强 饰）和家辉（钟保罗 饰）三人追逐梦想的成长故事，阿荣、家宝、家辉是学校里同学好友，毕业后面对自己人生的道路各自做出了不同的决定。阿荣家境贫寒天生叛逆，经历了世间的种种磨难，与朋友的嫌隙也日渐消融。热爱音乐的家宝一心想要追求自己的梦想， 在不被家人理解后愤然出走，与阿荣等人打工赚钱并收获了纯净的爱情，最后被唱片公司发现做了自己的演唱会。玩世不恭的弟弟家辉选择了一条父母喜欢的道路，但也一直在背后默默支持者哥哥和朋友。这三个毕业又即失业的学生是怎样在这个梦想与现实激烈碰撞的毕业季中殊途同归的呢？©豆瓣', '张国荣', '霍耀良', 7, 10865, 'tt0081501', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2498300586.jpg', 1, 7.9, 44.9, 33.4, 12.9, '0.284510,-0.271337,-0.537833,0.570447,0.008753,-0.471666,0.647884,0.221547,-0.548103,-0.181300,-0.039313,0.858033,-0.154014,0.364021,0.119953,-0.096704,-0.192390,-0.803885,0.186514,-0.084635,-0.088622,-0.485888,-0.060807,-0.023100,-0.161115,-0.109800,0.637540,0.070148,0.030911,0.804468,0.446415,-0.110933,0.021042,0.396023,-0.076880,0.171055,0.057366,0.436651,-0.461691,-0.122642,0.131999,-0.231492,-0.065578,0.156276,-0.049321,0.253340,0.738679,0.178755,-0.061165,-0.083990,0.369027,-0.342328,-0.056388,0.139800,0.267422,0.076115,0.342605,0.402427,0.086509,-0.123579,-0.251795,-0.159757,-0.702661,-0.175149,0.211072,-0.028922,-0.710395,0.619307,0.105822,-0.165220,0.204201,-0.245573,0.252971,0.391150,0.431630,0.539130,-0.337069,-0.161173,-0.346932,0.315655,0.721650,-0.204749,-0.083158,0.654450,-0.356772,-0.306760,-0.232697,-0.074722,-0.761389,0.105736,0.172480,0.185445,-0.365090,0.209763,-0.751850,0.137553,0.132762,-0.021731,0.052580,-0.703696,0.017783,-0.333295,-0.126713,-0.539742,-0.385349,0.035171,0.007630,-0.411082,1.097229,-0.928693,-0.000646,0.412176,0.477550,-0.746097,0.958632,0.227934,0.227252,-0.371029,0.214861,0.142997,-0.339788,0.148693,-0.013740,0.359374,0.100268,0.003919,-0.531229,0.467727', '3445516', '1292720', '35048413', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1471507', '十三罗汉', '惊悚', '人老心不老的鲁本•蒂什科夫（Elliott Gould 饰）拿出全部家当与威利•班克（阿尔•帕西诺 Al Pacino 饰）合伙经营赌场饭店。但他忘了，在拉斯韦加斯这个光怪陆离、骗盗横行的地方，防范之心是最不可或缺的。班克混迹赌城多年，奸诈手段让他在此如鱼得水。他骗尽鲁本的钱财，将赌场据为己有。老鲁本不堪如此沉重的打击，从此一病不起。鲁本的遭遇激怒了他的好友丹尼•奥逊（乔治•克鲁尼 George Clooney 饰），在对威利劝说无效的情况下，他重新集结了包括罗斯蒂•雷恩（布莱德•彼特 Brad Pitt 饰）、莱纳斯•凯德维尔（马特•戴蒙 Matt Damon 饰）在内的十三位罗汉，准备对班克赌场进行入侵。7月3日午夜，班克赌场开业，这注定是一个不平凡的夜晚……©豆瓣', '乔治·克鲁尼', '史蒂文·索德伯格', 7.5, 92976, 'tt0496806', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2203093998.jpg', 0.4, 2.9, 35.2, 45.2, 16.2, '0.219050,-0.117948,-0.558837,0.315331,-0.133928,-0.242001,0.594802,0.156899,-0.327798,-0.275021,0.293436,0.614982,-0.153124,0.079569,0.286166,0.130639,-0.477214,-0.431381,0.060260,-0.393202,-0.067251,-0.497242,-0.181143,-0.340444,-0.072556,-0.281891,0.144048,0.061132,0.052668,0.249087,0.365826,0.459251,0.280700,0.315268,0.035339,0.212847,0.143396,-0.305630,-0.235634,0.114849,-0.136714,-0.122341,-0.209155,0.321407,0.187702,0.364932,0.388213,-0.179300,0.106894,-0.114596,0.398217,-0.219178,-0.009796,0.132847,0.262490,-0.359712,-0.214160,0.277158,-0.352052,-0.151840,0.333554,-0.024401,-0.731123,-0.026468,0.023631,-0.073588,-0.658490,0.181195,-0.194213,0.288262,-0.368424,-0.208063,0.029352,0.235758,0.119462,0.065677,0.456477,-0.144030,-0.548433,0.053772,0.370052,-0.221278,-0.212007,0.174710,-0.026037,-0.197167,-0.109628,-0.288669,-0.468928,-0.350227,0.298434,-0.281482,0.052464,0.437482,-0.545685,-0.124412,-0.272486,-0.169882,-0.026983,-0.144234,-0.224711,-0.702026,-0.403289,-0.445333,-0.321642,-0.016350,0.039354,0.022874,0.487451,-0.598657,0.100689,0.526723,0.225643,-0.187515,0.634523,-0.045992,0.076044,-0.062165,-0.263546,0.365338,0.460476,0.089281,0.243661,0.447973,0.055389,0.020235,-0.154928,0.450564', '1793491', '1299799', '1308842', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1472510', '与女人们的对话', '剧情', '岁月流逝，人生周转，见惯了爱人们的喜怒哀乐，不觉便看淡了婚礼上的信誓旦旦。失去的终将失去，一切都随风而逝，不触动一丝涟漪。在友人的婚礼上，男人（Aaron Eckhart 艾伦•艾克哈克 饰）与女人（Helena Bonham Carter海伦娜•博纳姆•卡特 饰）相遇。他们是一对分手多年的夫妻，血气方刚的年龄毁掉了原本海誓山盟的爱情，多年后再次见面，时光已销蚀青春的容颜，似乎那些原本不可饶恕的细节与片断也变得微不足道。然有些东西一旦撒手，便注定永远失去……本片荣获2005年东京电影节评审团特别奖、最佳女演员奖。©豆瓣', '艾伦·艾克哈特', '汉斯·卡诺萨', 8.1, 23139, 'tt0435623', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2173125417.jpg', 0.3, 1.6, 18.9, 49.5, 29.7, '0.256926,-0.001622,-0.604484,0.306567,-0.211711,-0.630559,0.872498,-0.111467,-0.306854,0.025737,-0.015498,0.764010,-0.472822,0.285451,0.274737,-0.153646,-0.382705,-0.936217,-0.109737,-0.266948,0.146088,-0.374555,-0.060370,0.007537,-0.142798,-0.394831,1.091313,0.310130,0.104187,0.542647,0.373362,-0.167054,-0.011819,0.293226,0.042473,0.087598,-0.144351,0.222898,-0.460200,-0.269645,-0.056332,-0.323980,-0.188005,0.183070,-0.370125,0.054027,0.593930,-0.388240,-0.281455,-0.062317,0.438900,-0.287486,-0.082530,0.053418,-0.043717,0.002265,0.121192,0.421971,-0.424634,-0.120670,0.202228,0.060589,-0.230443,0.016239,0.208790,0.183001,-0.354304,0.580630,0.053939,0.193404,-0.167848,-0.235598,0.214169,0.027222,0.426644,0.154843,-0.141716,-0.117416,-0.410510,0.477943,0.846740,0.139563,-0.573079,0.341644,-0.432511,-0.349016,-0.370847,-0.275394,-0.415642,0.242695,0.091643,0.085241,-0.010383,0.746421,-0.384214,0.003291,-0.221231,-0.198983,0.072010,-0.414101,-0.056604,-0.405485,-0.480913,-0.518613,-0.446570,0.156596,0.242996,-0.179267,0.708952,-0.768309,0.444461,0.328965,-0.017569,-0.350358,0.684782,0.123795,0.065155,-0.258553,0.083944,0.565012,-0.467635,-0.055170,0.035008,-0.086211,-0.116815,0.414231,-0.087781,0.666314', '4202326', '1780122', '6973376', '1763916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1472532', '恐怖鸡', '惊悚', '某雨夜，深圳一名妓女斯琴爱儿被女通缉犯叶小雁（吴倩莲 饰）狠狠的勒死了，小雁为的是得到斯琴爱儿的身份。小雁乔装成爱儿的样子，顺利通过了海关到达了香港，报失了身份证后，小雁成功取得了爱儿的身份。爱儿本身有个香港老公才得到了香港居民的身份，此时爱儿的老公也在苦苦等候妻子抵步。小雁选中了嫖客陈启明（黎耀祥 饰），启明是个计程车司机，离异后把女儿交给母亲抚养很少过问。小雁首先把启明撞成残废，然后潜入了他的家中把他禁锢，详细询问了他的身世。怎料启明的母亲前往探望儿子，凶狠的小雁为了计划，把启明的母亲杀害了，更骗走了启明的女儿。在小雁领取身份证当天，爱儿的丈夫发现了小雁的嫌疑，一直跟踪她至启明的家中。打斗中小雁的丈夫（陈豪 饰）出现了，原来他们夫妇俩同时通缉犯，并要得到启明的身份与他的双手……©豆瓣', '吴倩莲', '曾瑾昌', 7.4, 19901, 'tt0184649', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1758292824.jpg', 0.7, 3.6, 33.7, 47.6, 14.4, '0.161262,0.207260,-0.648649,0.319783,-0.344824,-0.516096,0.350956,0.250023,-0.449382,-0.115626,0.460768,0.763548,0.090564,0.312873,0.288745,0.219521,-0.240547,-0.710644,-0.042562,-0.286784,-0.168457,-0.418874,-0.066981,0.111851,0.000200,-0.189249,0.156466,-0.448111,0.004848,0.351393,0.202248,0.179745,-0.077963,0.325837,-0.312140,0.413136,0.277260,-0.203232,-0.367454,0.442373,0.107004,-0.187875,0.114983,0.120147,-0.054918,0.447521,0.782385,-0.147811,-0.279459,-0.202317,0.201567,-0.320350,0.011305,0.188662,0.335473,0.089472,0.122402,0.266982,-0.450646,-0.041948,0.223499,0.100788,-0.581790,0.145321,0.123145,0.167308,-0.543897,0.214304,-0.340751,-0.075648,0.071045,-0.643719,0.453926,0.405745,-0.341855,0.274463,-0.315440,0.155310,-0.502874,0.363643,0.526283,-0.083888,0.411335,0.181558,0.023843,-0.179336,0.394141,-0.120014,-0.500883,0.084300,0.574437,0.100667,-0.334478,0.045469,-0.394143,-0.309222,-0.456024,0.017069,-0.109620,-0.456509,-0.085317,-0.248311,-0.124878,-0.320502,-0.174466,-0.225737,0.127988,-0.165958,0.713196,-0.709773,0.185764,0.400558,0.592789,-0.582830,0.373810,-0.031795,0.253965,-0.111549,0.079270,-0.258002,0.202124,0.596278,0.122611,0.224968,0.093076,-0.459951,-0.355913,0.139103', '1309069', '1301022', '30345227', '35461732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1472783', '一眉道人', '喜剧', '一眉道人（林正英 饰）修为高强，擅长茅山道术，和徒弟阿豪（钱小豪 饰）住在一个小镇上；他养了一只清朝的小僵尸，小僵尸经常帮他和阿豪办事。一天，一眉道人被邻镇的人邀请去捉鬼，因为邻镇瘟疫蔓延，不时有僵尸出没。一眉道人带上阿豪和小僵尸出发了。在邻镇一眉道人他们遇上了一群修女，阿豪弄出不少笑话。一眉道人发现邻镇的引用水源都被尸毒污染，不能饮用，于是和阿豪一起寻找水源。他在教堂的地下室发现了僵尸的痕迹，原来此处本来放着一具西洋僵尸，邻镇乡公所的所长意外令西洋僵尸复活了。一场精彩的中国法术对付西洋僵尸的好戏上演了。©豆瓣', '林正英', '林正英', 7.9, 40887, 'tt0098690', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2246195318.jpg', 0.3, 1.8, 25.6, 46.7, 25.5, '0.417484,-0.501936,-0.384378,0.215725,-0.244975,-0.161709,0.684338,0.003143,-0.364847,-0.216825,0.055693,0.601625,-0.200691,0.133777,-0.334249,-0.189587,0.081121,0.024547,-0.056912,-0.145962,-0.328976,0.086879,-0.369481,-0.237698,0.129907,-0.503546,0.105445,0.032382,-0.172287,0.322372,0.111651,-0.186689,-0.487245,0.232272,-0.339553,0.073580,-0.086666,-0.258713,0.241206,0.295548,0.002598,-0.242532,0.039884,-0.106492,-0.263670,0.324262,0.785090,-0.249500,-0.179824,-0.271236,0.003818,-0.203387,0.062391,0.085581,0.461562,-0.226489,0.366544,-0.057053,0.054780,-0.308900,0.044987,0.089918,-0.218569,0.234178,0.153874,0.317337,-0.372806,0.512989,0.217415,0.117307,-0.247798,-0.561129,0.462466,0.093214,0.250537,0.173514,0.136623,-0.260721,-0.682780,0.338326,0.468926,-0.203308,0.133532,0.228397,0.082048,-0.446212,0.026770,-0.174880,0.034442,0.134135,0.661695,-0.418368,-0.580663,0.017181,-0.568778,-0.019158,-0.146335,0.302882,-0.361356,0.194726,-0.088639,-0.720765,0.008513,-0.135057,0.032349,-0.087536,0.242507,-0.041105,0.599114,-0.358534,0.170714,0.518221,0.336427,0.006998,0.679419,-0.599705,-0.035245,-0.055928,-0.143503,-0.223759,0.370318,0.738772,0.675894,0.591791,0.003395,-0.249017,-0.071032,0.098816', '1394470', '1466273', '1401900', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1472907', '薄暮之光', '剧情', '社会底层人士考斯迪南（詹·海帝安Janne Hyytiäinen饰）是个不起眼的保安。他的生活和事业都充斥着失败感，如果说他曾经有过一些挣扎的话，也陷于徒劳，因为无穷无尽的孤独和自卑感已经把他牢牢笼罩。他似乎已经被这个世界遗忘了太久。美女米尔雅（玛利亚·海斯卡涅 Maria Järvenhelmi 饰）就这样意外的出现了，被她如此垂青，考斯迪南的人生终于重现亮光。没料到，米尔雅接近考斯迪南，不过是珠宝店抢劫计划的一部分。可怜的考斯迪南不但默默忍受了一场情感的欺骗，还因此事而入狱。即使保释出狱后，一切都有了重建的希望，噩运却始终不肯离开这个小人物，又一次给他无情的打击。走投无路的考斯迪南，只有期盼着人生能有一丝曙光。©豆瓣', 'Janne Hyytiäinen', '阿基·考里斯马基', 7.8, 6652, 'tt0458242', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p677193910.jpg', 0.3, 1.7, 25.8, 53.7, 18.4, '0.205133,0.002502,-0.764482,0.449600,-0.227943,-0.449829,0.933609,0.119985,-0.641471,-0.390335,0.258338,0.716630,-0.254417,0.239307,0.292139,0.092712,-0.312686,-0.623246,0.087188,-0.028360,-0.071184,-0.523464,-0.677766,0.013451,0.012433,-0.337280,0.563086,0.452542,-0.244251,0.496665,0.127316,0.148320,0.390671,0.979495,-0.127478,-0.028874,-0.027896,0.051625,0.058264,-0.006317,-0.008047,-0.218999,-0.234901,0.470901,-0.176288,0.338298,0.368722,-0.287688,-0.143862,0.035398,0.245872,-0.491264,0.152764,0.334164,-0.064683,-0.293178,0.210483,0.179794,-0.347351,-0.058110,0.357320,0.187744,-0.913253,-0.090034,0.007336,0.192778,-0.669565,0.581788,-0.223165,-0.090617,0.095057,-0.187378,-0.041284,0.247071,0.374117,0.416833,-0.369657,-0.010567,-0.925111,-0.004369,0.650076,-0.260665,-0.656774,0.524116,-0.241094,-0.020325,-0.165276,-0.260713,-0.560731,-0.004823,0.181314,0.049832,-0.286343,0.566631,-0.435450,-0.113670,-0.353181,-0.135635,-0.303747,-0.423805,-0.178900,-0.313811,-0.369571,-0.245929,-0.445664,0.294748,0.066808,-0.349840,0.482287,-0.539938,0.614704,0.591657,0.155195,-0.535667,0.768432,0.325956,0.101843,-0.094770,0.006043,0.545723,-0.145110,0.285827,0.226619,0.341760,0.143174,-0.235960,-0.185282,0.627322', '1306801', '1299932', '25763555', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1473074', '古惑仔2之猛龙过江', '剧情', '自从靓昆（吴镇宇 饰）企图谋夺洪兴江山事败之后，陈浩南（郑伊健 饰）声势日盛。在众人支持下，浩南誓要夺得铜锣湾的揸Fit人。树大招风，因此招来了同门大飞（黄秋生 饰）的嫉妒，大飞亦加入了铜锣湾揸Fit人的争夺。另一方面，山鸡（陈小春 饰）与台湾教父雷公的情妇丁瑶（邱淑贞 饰）有染，返港后发现雷公有意和洪兴争夺濠江赌场，并通过东星双虎涉足其中。雷公和丁瑶及三联帮众人亦来到了香港。丁瑶暗中拉拢大飞，合谋将雷公杀害并欲嫁祸给山鸡，浩南、山鸡等人会否坠入丁瑶精心设计的圈套中？一场腥风血雨的江湖混战即将展开！©豆瓣', '郑伊健', '刘伟强', 7.7, 94214, 'tt0260932', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p722782989.jpg', 0.5, 2, 29.3, 47.9, 20.3, '0.094357,0.071295,-0.458269,0.323379,0.299676,-0.127790,0.278283,0.364193,-0.547133,0.066777,0.273631,0.447791,-0.083299,-0.008170,0.115256,-0.148209,-0.210088,-0.730870,-0.116536,-0.052710,0.009016,-0.151381,-0.297725,-0.043409,-0.140193,0.137804,0.394074,0.048533,-0.240906,0.635568,0.501500,0.193580,-0.443202,0.324698,0.067482,0.141677,-0.144455,0.064620,-0.628450,0.165246,-0.278721,-0.519321,-0.233856,0.160305,-0.069240,0.408542,0.431235,-0.268490,0.163674,-0.471687,0.043083,-0.289093,-0.000548,0.109383,0.375785,0.052557,0.241529,0.539969,-0.314263,0.133818,0.132607,0.120233,-0.563541,0.152289,0.237266,-0.036353,-0.298030,0.409028,0.032129,0.075131,0.086316,0.147280,0.251475,0.326466,0.495403,-0.092574,-0.018802,0.081470,-0.350111,0.163617,0.484073,-0.143284,0.591373,-0.075803,0.570017,-0.164873,0.006200,-0.106341,0.057188,-0.184288,0.728833,-0.078817,0.096767,0.199532,-0.643725,-0.231966,-0.242945,0.048611,-0.072387,-0.065777,0.095093,-0.724305,-0.212703,-0.145146,-0.012380,-0.081015,0.273316,0.006412,0.341406,-0.710674,0.055083,0.272100,0.400826,-0.565856,0.227693,-0.058580,0.184728,-0.279099,-0.411565,-0.154021,0.393178,0.277590,0.170438,0.048394,-0.251297,-0.360535,-0.052097,-0.130910', '25723905', '1433736', '26365262', '1307704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1473078', '猛鬼学堂', '科幻', '不知什么时候，僵尸竟然窜上了香港的街头，由于被咬的人随后也会变成僵尸，一时间变得僵尸遍街，人们陷入了恐惧当中。一日，一只僵尸跑进了香港警局，由于没有对付僵尸的经验，警察们都束手无策。这时，警员金麦基（张学友 饰）与孟超（许冠英 饰）合理制服了僵尸，上司因此吩咐从各个部门抽调人员由他们领头组成猛鬼部队。于是，各个部门都把平时最不受欢迎的人物抽调了过来，一群乌合之众组成的猛鬼部队成形了。岂料训练刚开始，猛鬼部队的训练营地就窜进了僵尸，还有一个学员被僵尸咬了而没察觉，他也开始慢慢变为僵尸……©豆瓣', '张学友', '刘镇伟', 6.7, 8519, 'tt0095617', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2332487132.jpg', 1.7, 9.1, 50.8, 26.8, 11.5, '0.764249,-0.331266,-0.565041,0.222985,-0.128932,-0.124397,0.832908,-0.070593,-0.383139,-0.056134,0.253566,0.392006,-0.161003,-0.053074,-0.068603,-0.373310,-0.145196,-0.646200,-0.373996,-0.183791,-0.376633,0.153154,-0.210464,-0.458863,0.148753,-0.230285,0.477174,0.038394,0.011834,0.443138,0.101536,0.246012,-0.043432,0.306604,0.081206,0.113896,0.454691,-0.269501,0.596156,0.107339,-0.113925,-0.496653,-0.040720,0.045167,-0.183450,0.495592,0.742719,-0.245453,0.168076,-0.361528,-0.065731,-0.370761,-0.224528,0.063017,0.765219,0.005625,0.165276,-0.212739,0.237761,0.170200,-0.222604,0.164478,-0.548177,0.117965,-0.109426,0.436941,-0.637954,0.156201,-0.009058,0.198155,-0.011852,-0.419392,0.210613,0.208191,-0.034329,0.240048,0.216403,-0.053125,-0.714246,0.298289,0.711835,-0.199325,-0.345655,0.080700,-0.046929,-0.852933,-0.025433,-0.154409,0.189208,-0.276493,0.407920,0.147131,-0.489708,-0.074056,-0.691272,0.026818,-0.017253,-0.252109,-0.459637,-0.038367,-0.266665,-0.494094,0.051882,-0.121400,0.069278,0.145810,-0.081873,0.364845,0.703482,-0.646752,-0.056188,0.300314,0.281666,-0.380427,0.439279,-0.642321,-0.014467,0.171342,0.336094,-0.440265,0.226765,0.870943,0.821602,0.589276,-0.343302,-0.417118,0.049769,0.273866', '21619567', '1394470', '2160611', '1292523');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1473297', '四角关系', '剧情', '瑞秋（派珀•佩拉博 Piper Perabo 饰）终于要嫁给了青梅竹马的男友海克（马修•古迪 Matthew Goode 饰）了，海克英俊温柔体贴忠厚，深深爱着瑞秋，瑞秋以为自己也同样深深爱着海克。婚礼上，就在通往神圣婚姻的红地毯上，瑞秋不经意地向旁边一瞥时，她突然像被闪电击中一样，而她，就是花店老板露丝（琳娜•海蒂 Lena Headey 饰），负责婚礼所有的鲜花。就这样，她们在婚礼上结识，并成为了朋友。虽然瑞秋和露丝彼此爱慕，但是她已经结婚了，而且海克是那么的好，最终瑞秋选择了放弃，露丝也选择了离开。瑞秋的变化被海克看到了眼里，他想给瑞秋幸福，于是，他选择了离开。瑞秋与露丝最终能否有情人终成眷属？©豆瓣', '派珀·佩拉博', '欧·帕克', 7.6, 28026, 'tt0421994', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2327802467.jpg', 0.4, 3.1, 31.9, 43.7, 20.9, '0.457904,0.028685,-0.612077,0.361066,0.074228,-0.936986,0.784296,0.114824,-0.067274,0.138160,0.294235,1.066922,-0.361332,0.089246,0.200444,0.604664,-0.689335,-0.889713,0.171645,-0.287524,-0.204878,-0.555296,0.067270,0.159929,0.208648,-0.193946,0.506058,-0.341573,0.431757,0.750649,0.391312,0.315321,0.225173,0.589715,-0.136167,0.405513,0.048200,-0.123255,-0.515351,0.362181,0.076324,0.103830,-0.142497,0.310741,0.031931,0.239445,0.347838,-0.217505,0.050849,0.136995,0.029334,-0.436794,0.279162,0.377467,-0.033098,-0.065730,0.394490,0.183230,-0.262045,-0.127243,0.127631,-0.015294,-0.484136,0.314385,-0.131605,0.225413,-0.713772,0.588983,-0.097243,-0.308322,0.414595,-0.571471,0.352645,0.065985,0.255864,0.039197,-0.487065,0.045600,-0.489152,0.054591,0.428341,0.456959,-0.031554,0.621766,-0.312929,-0.234025,0.015766,-0.029678,-0.764866,0.132663,0.386053,0.244509,-0.028658,0.194261,-0.500579,-0.169229,-0.554448,0.010627,-0.115369,-0.676577,-0.003996,-0.391502,-0.305059,-0.307994,-0.796725,-0.043147,-0.231021,-0.349832,0.475332,-1.008572,0.292826,0.512491,0.577582,-0.269317,0.685952,0.345912,0.133142,-0.014251,-0.002372,0.381063,-0.202622,0.055147,-0.013292,0.373194,0.071990,-0.108991,-0.324262,0.734713', '1297239', '1299556', '1922691', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1473562', '丛林赤子心', '剧情', '迪士尼于1987年发行了一部十分特別的电影，全片几乎都是由动物所主演，片名是《丛林赤子心》（Benji the Hunted），故事內容是敘述一只名叫Benji小狗的故事。其實在《丛林赤子心》之前，导演Joe Camp所属的 Mulberry Square制片公司已在1974年、1977年、1980年推出了三部以小狗Benji为主角的电影，都受到观众的欢迎，1987年的《丛林赤子心》才是与迪士尼合作，再度介绍这只传奇的灵犬！本片剧情是叙述灵犬Benji流落野外的故事，Benji发现有一只豹妈妈被猎人射杀，留下孤苦无依的四只小豹，Benji在恻隐之心的驱使下，顾不得自己远离家园，还担负起照顾四只小豹的任务，甚至因此放弃了好几回它明明可以回家的机会。另外，Benji还要提防灰狼等凶猛野兽的攻击，保护小豹的安全。最后，它总算替小豹们找到了一个适当的归宿。本片的导演是Joe Camp，本片大部分情节都是动物们演出的画面，因此有对白的部分并不多，故事情节相当感人，配乐也非常不错 ，本片的配乐则是由Euel Box所负责。', '本吉', '乔·坎普', 9.1, 16814, 'tt0092638', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321248846.jpg', 0.2, 0.6, 6.8, 27.5, 64.9, '0.001659,-0.448974,-0.315516,0.479696,0.293106,-0.055478,0.476536,-0.088525,-0.384931,-0.222129,0.324546,0.528594,-0.039628,0.039784,0.007435,-0.222130,-0.155263,-0.326775,-0.336220,0.121029,-0.090020,-0.126555,-0.393976,-0.140776,-0.050113,-0.376096,0.828006,-0.107677,-0.274815,0.290688,0.281831,0.128787,-0.155687,0.115184,-0.220007,0.120476,-0.140910,-0.138668,-0.235965,0.198768,-0.041313,-0.283443,-0.297889,0.008400,-0.035050,0.314839,0.876693,-0.311831,-0.348503,0.024262,0.413861,-0.409885,0.109013,-0.223706,0.325836,-0.104493,0.559121,0.346713,-0.148923,0.357223,-0.156722,-0.250528,-1.139017,-0.010770,0.276232,0.266862,-0.558198,0.322682,0.079814,0.135346,0.255597,-0.488179,0.183075,0.076738,0.267274,0.408001,-0.155858,0.229130,-0.371270,0.347047,0.682740,0.015555,-0.134867,0.477291,-0.156438,-0.769286,-0.152669,-0.205485,-0.359054,0.146736,0.178382,0.219032,-0.299466,0.001136,-0.876214,-0.049247,-0.071796,-0.598875,0.003905,-0.537362,0.010178,-0.552183,-0.080569,-0.330589,-0.091288,0.044630,0.295440,-0.227230,1.015359,-0.767909,0.293845,0.585064,0.022301,-0.447285,0.850255,-0.066709,0.089023,0.018491,0.190135,-0.039099,0.095784,0.096398,0.251798,0.169285,0.099619,-0.553836,-0.525651,0.436637', '24284209', '27602116', '26759820', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1473795', '海神号', '剧情', '新年的钟声即将响起，欢快喜庆的气氛弥漫在正孤独航行于北大西洋上的海神号中。这是一艘拥有800个房间、13层楼高、载客量超过2000人的超豪华邮轮。在船长麦克•布莱福德（Andre Braugher 饰）的组织下，达官显贵、社会名流纷纷云集在豪华明亮的大厅，伴着美食佳酒、轻歌曼舞一同庆祝新年的到来。与此同时，大西洋底的地壳发生剧烈震动，继而掀起足以摧毁万物的滔天巨浪。在自然面前，再坚固的船只也需俯首称臣。海神号被巨浪掀翻，无数人丢掉性命。面对死神的威胁，侥幸逃过第一波劫难的人们开始想尽办法逃生。在茫茫无所依靠的大海中央，他们的命运终将如何？本片翻拍自1972年经典灾难片《海神号遇险记》（The Poseidon Adventure）。©豆瓣', '乔什·卢卡斯', '沃尔夫冈·彼德森', 6.8, 37735, 'tt0409182', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p914223313.jpg', 0.9, 7, 50, 33.3, 8.7, '0.024997,0.160393,-1.078109,0.486804,0.362459,0.294704,1.002300,0.184509,-0.242303,0.196316,0.558851,0.618464,-0.209507,-0.014152,0.325629,-0.296050,-0.253678,-0.460393,-0.346095,-0.114542,-0.164715,-0.111063,-0.289736,-0.099400,0.203108,-0.184774,0.553239,0.460884,-0.003019,0.382768,0.158278,0.145356,-0.256588,0.590783,-0.291053,-0.199094,-0.248186,0.113261,-0.370492,0.002876,-0.678256,-0.472063,-0.059011,-0.093359,-0.118440,0.007415,0.667868,-0.401111,0.046490,0.078404,0.310358,-0.172868,0.071543,0.189941,0.261983,0.238553,-0.108611,-0.067204,-0.119735,-0.041075,0.059381,-0.052076,-0.443137,-0.144556,-0.065660,0.014047,-0.081332,0.361032,0.025852,-0.153443,-0.038948,0.070782,0.236433,-0.014361,0.039119,0.584876,-0.181926,0.354754,-0.490797,0.042991,0.950497,0.102399,-0.429437,-0.033715,-0.157190,-0.215995,-0.070604,-0.387704,-0.481012,-0.453929,0.660711,0.160641,0.202859,0.400442,-0.551296,0.276735,-0.177116,-0.801536,-0.229737,-0.119154,-0.550322,-0.698002,0.048243,-0.135478,0.071169,0.294032,0.111885,-0.131153,0.627806,-0.307753,0.497843,0.491128,0.054864,0.134976,0.594100,-0.302906,0.135148,0.278103,-0.041966,0.126367,-0.105492,0.628011,0.032292,0.157136,-0.261646,0.124330,-0.253248,0.378663', '3011051', '2269893', '3582181', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1474045', '盗走达芬奇', '喜剧', 'Cuma（罗伯特·维凯威兹 Robert Wieckiewicz 饰）在一次盗窃事件中被警察逮到，由于掩护了同伙Julian（波利斯·席克 Borys Szyc 饰）而使Julian逃过了牢狱之灾，狱中的Cuma这天收到医生开出的健康证明获得假释。原来是老主顾上门，让他盗走波兰博物馆镇馆之宝——达芬奇的名画《抱银鼠的女人》。Cuma去找Julian合作，Julian已经是一名警察，还上夜大读法律，一片向上的生活。怀有强烈爱国心的他不愿意帮忙，然而Cuma既是他的兄弟更是他的恩人，他心生一计，决定暗中掉包，也不会让国宝落在自私的收藏家手中。忙碌的准备工作开始了，找人画复制品，准备炸药，遇上形形色色有趣的人，到了动手的那一天……那一天，乌龙百出，却又皆大欢喜。©豆瓣', '罗伯特·温茨凯维奇', '尤利尤斯·马胡尔斯基', 7.5, 13058, 'tt0425622', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2250044917.jpg', 0.3, 2.3, 32.5, 50.1, 14.7, '0.332524,-0.150422,-0.665979,0.370849,-0.289811,-0.189765,0.618202,0.011253,-0.597000,0.087356,0.409622,0.626297,-0.273190,0.154348,0.248378,0.142607,-0.226466,-0.519136,0.163607,-0.217491,-0.357766,-0.286077,-0.328812,-0.342596,-0.047243,-0.195235,0.349205,0.211602,0.012323,0.383802,0.300613,0.250405,0.091840,0.394195,-0.273179,-0.051521,-0.135427,-0.037054,-0.099232,0.419832,0.218779,-0.389746,-0.127251,0.288544,0.092170,0.511746,0.490209,-0.121272,-0.199972,-0.014799,0.377926,-0.495615,-0.050620,0.123059,0.176540,0.118728,-0.021925,0.232281,-0.415779,-0.033952,0.110523,-0.005688,-0.506449,0.004624,0.146732,0.098588,-0.666564,0.426044,-0.203302,0.114792,-0.165297,-0.285769,0.262379,0.175997,0.018715,0.257009,0.200474,-0.126544,-0.675346,0.218063,0.584115,-0.196707,0.101119,0.200538,-0.045507,-0.268469,0.290808,-0.318573,-0.231374,-0.033103,0.434068,-0.224434,-0.165997,-0.146121,-0.520866,-0.082109,-0.448087,-0.067153,-0.023552,-0.342173,0.041094,-0.312802,-0.006877,-0.080621,-0.309192,0.289196,0.267271,-0.301930,0.564336,-0.626378,0.226345,0.671706,0.197126,-0.435621,0.523061,0.071708,-0.130004,-0.064005,-0.232961,-0.204789,0.343147,0.443248,0.096822,0.177206,0.211526,-0.361594,-0.209649,0.214814', '1947080', '1292584', '1306801', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1474180', '触不到的恋人', '剧情', '女医生凯特（桑德拉•布洛克 饰）因为工作繁忙，搬离了郊外的河边小屋。临走时她在信箱里放了一封信，希望下一位住客能帮忙处理信件。不久，她来到了旧址，发现信箱里面有一封来自建筑师亚历克斯（基努•里维斯 饰）的来信，信一封接着一封。原来他们所处的年代相差了两年，他们惊讶之余更乐于成为对方的笔友，他们在不同的空间里，一次又一次感受对方的存在。随着爱情的滋生，亚历克斯决定要见凯特一面，但他们都不知道这场跨越时空的恋爱，将会使他们经历何样的景况。©豆瓣', '基努·里维斯', '亚历杭德罗·阿格雷斯蒂', 7.7, 97200, 'tt0410297', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p696975196.jpg', 0.3, 2.3, 28.5, 48.4, 20.5, '0.377225,0.059121,-0.618567,0.597514,-0.034550,-0.055158,0.698110,-0.038058,-0.692338,-0.282381,0.095696,0.812076,-0.222168,0.139426,0.092796,-0.149012,-0.418249,-0.450146,0.088988,-0.769380,-0.393471,-0.504613,-0.595005,-0.237058,0.003420,-0.196925,0.302133,0.126978,-0.037264,0.433823,0.066145,-0.037980,-0.198975,0.628000,-0.074096,0.108936,0.106804,0.130334,-0.223430,0.146669,0.276669,-0.142701,-0.181969,0.295411,0.217117,0.328373,0.649332,-0.202886,-0.210319,0.140255,0.514722,0.120669,-0.074526,0.047121,0.313432,0.182066,0.046468,0.193078,-0.326924,-0.016296,-0.001907,-0.161677,-0.514739,0.129923,-0.129275,0.370435,-0.414226,0.335907,-0.197493,-0.036950,-0.099807,-0.408315,0.173081,0.467521,0.432527,0.332407,0.001911,-0.277216,-0.337908,0.031320,0.659734,-0.232703,-0.042551,0.453705,-0.238328,-0.451783,-0.102386,0.179271,-0.724825,0.268894,0.339472,0.300575,-0.185176,-0.002470,-0.519268,-0.085258,-0.483679,-0.226152,-0.030236,-0.457772,-0.207706,-0.566455,-0.203245,-0.246494,-0.282482,-0.022867,0.059029,-0.274067,0.586711,-0.594986,0.228940,0.333291,0.381927,-0.342743,0.831680,0.104392,0.216372,-0.331828,0.236067,0.237554,0.249202,0.406566,0.232686,0.215295,-0.073440,-0.203531,-0.454921,0.433834', '3055049', '1302384', '30162520', '1361252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1474185', '人生遥控器', '剧情', '建筑师迈可·纽曼（亚当·桑德勒 饰）每天都过着忙碌的生活。事业有成的他纵使有个美满的家庭，美丽贤惠的妻子唐娜（凯特·贝金赛尔 饰），可爱的一对儿女，他总是没时间好好享受天伦之乐，为了晋升而逃避甚至忘记了与家人们的约定。迈可正寻找一个万能遥控器，一个神秘身份的老板莫蒂（ 克里斯托弗·沃肯 饰）给了他一个。当迈可回到家尝试使用后才发觉了这个遥控的神奇功能：他可以利用这个遥控器控制自己的生活时间，这对他来说是件极其兴奋的事情，他可以逃过那些繁琐的事，随心所欲到达自己想要的时段。直到有一天，这个遥控器不再受他的控制了，他的生活变得乱七八糟，时间迅速向前走，而他也错过了很多重要的事情：他迅速的成为公司的高层、他的妻子离开了他与别人结婚、父亲逝世、儿子结婚等等，他才后悔自己故意错过的东西，而他也来到了弥留之际，他努力要告诫儿子不要重蹈覆辙，多把时间留给家人……', '亚当·桑德勒', '弗兰克·克拉斯', 7.8, 132464, 'tt0389860', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735368246.jpg', 0.3, 2.5, 28.4, 46.2, 22.6, '0.293495,0.030148,-0.742614,0.554710,-0.460688,-0.369599,0.845651,0.049441,-0.372948,-0.438883,0.072118,0.700923,0.125667,0.388425,0.024632,0.303635,-0.342629,-0.734022,0.448813,-0.008261,-0.180415,-0.207087,-0.099323,-0.335628,-0.122265,-0.154691,0.428034,-0.054748,0.081526,0.115347,0.069886,-0.147373,0.325315,0.569131,-0.371000,0.070033,0.025278,0.056006,-0.149398,0.271527,0.309537,-0.158653,-0.075249,0.425484,0.133161,0.287416,0.554649,-0.088847,-0.451219,0.043363,0.321764,-0.368316,-0.108585,0.234558,-0.041701,0.042473,0.040648,0.107104,-0.485326,0.079923,-0.028013,-0.095058,-0.994882,-0.074578,-0.152619,-0.053944,-0.729358,0.366591,-0.262728,-0.206341,0.011918,-0.604662,0.292972,0.503249,0.157845,0.193099,-0.443919,-0.007054,-0.490771,0.379094,0.732438,-0.181554,-0.264493,0.653685,-0.162482,-0.248245,-0.093055,-0.452176,-0.753417,-0.091389,0.273131,0.016151,-0.213961,0.313184,-0.373491,-0.024102,-0.394543,-0.376061,-0.011046,-0.444182,-0.005038,-0.144556,-0.072967,-0.479452,-0.590592,0.070410,-0.095806,-0.523832,0.695688,-0.697752,0.186110,0.703609,0.451036,-0.912145,0.719597,0.145403,0.275449,-0.229588,0.094276,0.364353,-0.137937,0.297375,0.045981,0.279571,0.345168,-0.016872,-0.298436,0.651350', '1877596', '26678784', '30163500', '1306916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1474189', '电锯惊魂3', '悬疑', '“竖锯”（托宾·贝尔 Tobin Bell 饰）和新学徒阿曼达一起失踪，警方四处搜索，满城阴云密布。一天夜里，刚值完晚班的女医生莲恩·戴伦（巴哈·索莫克 Bahar Soomekh 饰）惨遭绑架，醒来时惊恐万分的莲恩，发现自己被捆绑在一间废弃的空屋里，同屋的还有另一名倒霉受害者杰夫（安古斯·麦克菲登 Angus Macfadyen 饰）。此时“竖锯 ”已卧床不起、奄奄一息，莲恩被告知除非她能在死亡游戏完成前保住这个疯子的性命，否则她和杰夫必死无疑！为了活下去，神经高度紧张、备受煎熬的莲恩想尽办法让“竖锯”保住最后的呼吸。然而她却怎么也想不到，杀人狂暗地里有着更可怕的杀人计划--那将会是恶名彰著的“竖锯”绞尽心血的死前华彩！最后的终极死亡游戏即将开始……©豆瓣', '托宾·贝尔', '达伦·林恩·鲍斯曼', 8.1, 159914, 'tt0489270', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p443443408.jpg', 0.4, 1.8, 21.1, 46.3, 30.4, '-0.074368,-0.042528,-0.599745,-0.047820,0.061012,-0.236490,0.699210,0.017183,-0.384958,-0.089839,0.335020,0.422341,-0.505107,0.178337,0.059609,-0.158274,-0.202451,-0.574712,-0.081802,0.079310,-0.385795,-0.399440,-0.355669,-0.204604,-0.118521,-0.125728,0.420997,-0.093727,0.093211,0.334205,0.413905,0.451267,0.010364,0.222647,-0.097928,-0.107035,0.132040,-0.359068,0.060149,0.191052,0.139380,-0.023263,0.109216,0.172148,-0.153129,0.549221,0.436867,-0.143175,-0.008687,-0.222405,0.359003,-0.405518,-0.159732,0.341682,0.441917,0.045111,0.130124,0.098888,-0.231195,-0.158307,0.181644,0.012538,-0.711021,0.169168,0.205447,0.051165,-0.424142,0.237216,-0.133235,0.265047,0.166560,-0.178721,0.346153,0.330758,0.279840,0.189248,-0.152158,-0.082707,-0.629650,-0.123413,0.444088,-0.363106,-0.015841,0.293391,0.124096,-0.035447,-0.090426,-0.332834,-0.240606,-0.148524,0.230064,0.133718,-0.211513,0.055575,-0.320329,0.002212,-0.366152,0.081580,-0.166273,-0.156113,-0.496857,-0.318000,0.046834,-0.070408,-0.278532,0.295925,-0.041763,-0.352647,0.183639,-0.354105,0.302631,0.297651,0.095520,-0.105255,0.395102,0.118160,0.209601,0.054563,0.015463,0.376975,0.199330,0.484835,0.318552,-0.008342,-0.139251,0.031120,-0.515196,0.546882', '1417598', '26747274', '1299932', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1474203', '致命紫罗兰', '动作', '未来世界，军方研制强化战士作战能力的药剂，却弄巧成拙导致大量民众沾染失败的实验制剂，并由此诞生了身体异于常人的生化人群体。军方兴建了庞大的隔离建筑，同时研发出对付生化人的最终武器，于是生化人组织派出女战士紫罗兰（Milla Jovovich 饰）潜入军方内部，用暴力方式将最终武器抢夺。紫罗兰难耐好奇，于路将最终武器包装打开之后发现里面居然是一名男童（Cameron Bright 饰），原来男童拥有可以消灭生化人的血液抗原，紫罗兰认为血液抗原亦可使生化人返回人类形态，不满组织的粗暴解决方式遂决意背叛，携自称“6号”的男童踏上了躲避军方和生化人组织的亡命之旅。而男童的背后，还有更大的秘密尚未揭开。©豆瓣', '米拉·乔沃维奇', '科特·维莫', 5.5, 16508, 'tt0370032', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1052132524.jpg', 8.2, 28, 47, 12.2, 4.7, '-0.070294,0.219817,-0.325360,0.260353,-0.308081,0.304852,0.388998,-0.198053,-0.592722,-0.213651,0.340315,0.436873,0.399198,-0.421745,-0.011785,-0.367959,-0.145447,-0.311224,-0.157412,-0.158432,-0.763760,-0.156324,-0.573363,-0.734665,0.313302,-0.845225,0.941152,0.133115,-0.629635,0.196776,-0.067562,0.614822,-0.451040,0.322572,0.161281,-0.470953,0.175127,-0.286726,-0.230074,0.441968,-0.381861,-0.112592,0.115317,0.174347,-0.288016,0.305578,0.883838,-0.702013,0.098951,-0.776403,0.100366,-0.303694,-0.127498,-0.113767,0.293191,0.516777,-0.153391,0.085005,-0.011566,0.103431,0.282933,0.069714,-0.961388,-0.194595,0.202713,-0.062002,-0.407099,0.218118,-0.142930,0.193165,0.032501,-0.271984,0.056553,0.185804,0.473743,0.228047,-0.048135,0.074620,-0.505808,-0.018304,0.472502,-0.273515,-0.459740,0.072565,-0.427619,-0.634426,-0.289402,-0.540791,0.095209,-0.092309,0.189859,0.472929,0.008776,0.270437,-1.008797,0.057136,-0.270445,-0.012137,0.278409,0.057584,0.041888,-0.840767,-0.040048,0.255075,-0.258254,0.088199,0.148236,-0.131016,0.927582,-0.595671,-0.093168,0.518551,0.428971,-0.833563,0.205929,-0.395320,0.070481,-0.252718,-0.218802,0.192436,0.260377,0.382987,-0.121463,0.241694,-0.021460,-0.228992,-0.153462,0.194894', '1292680', '2051813', '1793915', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1474336', '赤脚小子', '剧情', '清朝某年。赤脚小子关丰曜（郭富城 饰）独身入省城闯荡，他一贫如洗，可以依赖的只有自己一身功夫和染坊“四季织”内的父亲故交段青云（狄龙 饰）。省城内局势颇不宁静，天龙坊主人喀和布（曾江 饰）凭旗人身份独霸一方，用以选拔家丁打手的擂台熙攘不休。新任县令袁天佑（张兆辉 饰）与教师（秦沛 饰）欲铲除喀和布，但立根不稳无计可施。关丰曜于路巧遇四季织女主人白筱君（张曼玉 饰）和袁师之女小莲（吴倩莲 饰），并终与段青云相见，原来段青云为躲避追捕，改名换姓藏身染坊，并与白筱君产生了情意。喀和布为吞并四季织奸计频出，关丰曜忍无可忍打上门去，反被喀和布收服利用。袁天佑在同喀和布的较量中一再受挫，竟要挟段青云与喀和布拼斗，关丰曜匆匆赶去救援，但为时已晚……©豆瓣', '郭富城', '杜琪峰', 7.1, 7421, 'tt0106552', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2253800895.jpg', 1, 5.1, 46.3, 34.5, 13.1, '-0.148319,-0.095357,-0.439847,0.373812,-0.013620,-0.277947,0.037669,0.108125,-0.584122,-0.472576,0.197844,0.331245,-0.238809,-0.152473,0.295946,0.018375,0.099606,-0.594388,0.187228,-0.257783,0.145973,-0.394868,-0.280288,-0.096545,-0.201072,-0.083040,0.611509,0.269492,-0.390210,0.711054,0.239525,0.194355,-0.507491,0.400184,-0.078274,-0.107998,-0.127571,-0.039810,-0.523007,-0.037617,-0.289785,-0.453434,-0.255896,0.040385,0.172770,0.389958,0.447638,-0.380205,0.019463,-0.127219,0.086041,-0.084162,-0.053238,0.120848,0.395843,0.039441,0.230849,0.457946,-0.339683,0.206609,-0.083567,-0.199222,-0.129306,0.368915,0.328863,-0.240040,-0.754460,0.479206,-0.039721,-0.379484,-0.016648,-0.369036,0.033419,0.214652,0.180129,0.312142,-0.095447,-0.140173,-0.698428,0.240150,0.479841,-0.029919,0.332434,0.055570,0.325833,0.077470,0.096285,-0.276783,-0.118387,-0.195757,0.325621,-0.126047,0.235828,0.034533,-0.246805,-0.040159,-0.466659,0.192895,0.044889,-0.195899,-0.058649,-0.540722,-0.080243,-0.337882,0.015971,-0.161065,0.339532,0.011448,0.302745,-0.873155,0.006131,0.032377,0.386367,-0.786528,0.324791,0.252017,0.305007,-0.200681,-0.366686,-0.216526,0.163762,0.468395,0.355619,0.121857,-0.215056,-0.006879,-0.131490,-0.145281', '27621189', '1410695', '35030151', '1300060');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1475572', '守日人', '动作', '影片是根据谢尔盖·卢科扬涅科的三部曲中的第二部《守日人》改编。故事发生在上一集叶戈尔（德米特里·马丁诺夫 Dmitry Martynov 饰）归入黑暗阵营几年之后，安东(康斯坦丁·哈宾斯基 Konstantin Khabenskiy 饰）与其新女友兼徒弟斯维塔担当光明阵营力量的同时，叶戈尔也在逐渐成长为黑暗阵营中一名拥有强大力量的少年，并受到父亲安东暗中的保护。直到黑暗阵营中一名吸血鬼的离奇死亡，打破了光明与黑暗之间的微妙平衡，安东更被诬陷为凶手。审判庭裁定如果在期限之内无法证明安东不是凶手，光明和黑暗两大阵营之间的大战将一触即发。为此，安东开始寻找古代传说中那能改变命运的神器——命运粉笔，来挽回这摇摇欲坠的世界……©豆瓣', '康斯坦丁·哈宾斯基', '提莫·贝克曼贝托夫', 7.4, 9806, 'tt0409904', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1157593975.jpg', 1.8, 6.1, 32.1, 41.4, 18.6, '0.075316,0.443398,-0.548936,0.694161,0.079547,0.067633,0.749910,0.154854,-0.560362,-0.394774,0.195726,0.712602,0.222684,-0.049728,0.438426,-0.033200,-0.460814,-0.805975,-0.208370,-0.010235,-0.412305,-0.606298,-0.661429,-0.172642,-0.276925,-0.557570,0.832132,0.289093,-0.323959,0.161182,0.275104,0.488733,-0.183807,0.132331,0.112784,-0.088949,0.235802,-0.148127,-0.603493,0.443281,-0.257582,0.127826,-0.100348,0.209156,-0.273186,0.027524,0.581817,-0.520815,0.174528,-0.371383,0.452427,-0.153636,-0.098967,-0.019604,0.412808,0.196028,0.286173,0.360266,-0.044936,0.026493,-0.047446,-0.043667,-1.133765,0.240795,0.009554,0.179178,-0.219070,0.198626,0.110211,-0.168332,0.426841,-0.047948,0.075088,0.284084,0.729133,0.244355,-0.438781,-0.278300,-0.522638,-0.205410,0.534719,-0.212929,-0.518626,0.143385,-0.096030,-0.361468,-0.553506,-0.226472,-0.385107,-0.138722,0.313377,0.337745,0.235691,0.693477,-0.631874,-0.013356,-0.270666,-0.090506,-0.048451,-0.265455,-0.012311,-0.400828,-0.338556,0.032688,-0.245930,-0.148454,0.142643,-0.258271,0.591424,-0.659226,0.470216,0.421634,0.220497,-0.332876,0.476546,0.332734,0.519257,-0.272615,0.048771,0.346243,0.261814,0.255352,0.216322,0.077634,-0.187486,0.141785,-0.152360,0.670256', '6844861', '26667010', '27098364', '10440076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1476023', '绝代艳后', '剧情', '这部电影讲述了一位法兰西王后的一生，讲述了那个年代，法国大革命前贵族们奢华迷乱的生活。奥地利公主玛丽（克尔斯滕•邓斯特 Kirsten Dunst饰）非常聪明，生性活泼，14岁的时候，在一场政治婚姻中，从奥地利公主变成法国的太子妃。由于某些原因，王子对玛丽非常的纵容，婚后，玛丽一直过着极其奢华的生活，同样，玛丽也一直无法与内心的寂寞彻底脱离。这部电影将给我们带来关于18世纪法国宫廷和社会的各种震撼，匪夷所思的奢侈，欲望交织的爱情，以及最后法国人民的怒吼。©豆瓣', '克斯汀·邓斯特', '索菲亚·科波拉', 6.9, 82095, 'tt0422720', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735421206.jpg', 0.9, 7.9, 48.3, 32.7, 10.1, '0.257506,0.200052,-0.547262,0.841813,0.145410,-0.163593,0.950245,-0.081655,-0.710522,-0.478103,0.067854,0.744486,-0.277821,0.304564,0.613057,-0.042041,-0.474575,-0.460438,-0.379549,0.032185,0.076168,-0.188054,-0.229083,-0.252695,-0.449071,-0.371375,0.754909,0.042510,-0.257005,0.429045,0.335121,0.595073,0.147899,0.315189,-0.140867,-0.066412,0.246119,0.043654,-0.395092,0.019508,0.315888,-0.259386,0.100330,0.460215,-0.066961,-0.134330,0.583123,-0.594349,0.072818,-0.404455,0.690827,0.010177,-0.222777,0.328111,0.109776,-0.060799,0.312863,0.262748,-0.147457,-0.109406,-0.174993,-0.219476,-0.748926,0.009170,0.143520,0.045347,-0.474652,0.363679,-0.088929,-0.038070,0.197596,-0.291531,0.200896,0.353866,0.453840,0.406134,-0.210732,-0.014063,-0.352510,0.442386,0.931880,0.055452,-0.490453,0.286116,-0.732105,-0.473056,0.006505,-0.307947,-0.804712,0.025185,0.187191,-0.105285,0.004751,0.644020,-0.884554,0.049246,-0.186200,-0.508965,0.386812,-0.448567,-0.079341,-0.784349,-0.465619,-1.024143,-0.091907,-0.313928,0.147368,-0.078295,0.834519,-0.780049,0.215052,0.216415,0.215651,-0.291178,0.567720,0.249285,-0.018572,-0.046314,-0.219246,0.691934,-0.274669,-0.085429,-0.384584,0.502454,0.054309,-0.079130,-0.408656,0.794626', '1303542', '2053515', '1296992', '5029050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1477206', '特务风云', '剧情', '本片把中央情报局创始人之一的爱德华·威尔逊波澜壮阔的人生搬上银幕。爱德华·威尔森(马特·达蒙Matt Damon 饰)因童年的悲剧在心底根植入荣誉的情愫。1939年，正在耶鲁大学就读的他被秘密社团“骷髅会”看中，将他招募为会员，随即他又加入了二战期间的战略情报局。威尔森成为了情报局的核心成员和创建者。然而，长期的尔虞我诈让他多疑的天性与日俱增，在冷战的进程中，威尔森青年时期的最初理想已经被消磨的面目全非。而职业惯性已经把威尔森推离了正常的生活轨道，他与妻子玛格丽特(安吉丽娜·朱莉Angelina Jolie 饰)之间的矛盾日益加深，两人的婚姻名存实亡。为了国家，威尔森不但牺牲了个人理想，连家庭和亲情也因他的蜕变而陷入绝境......©豆瓣', '马特·达蒙', '罗伯特·德尼罗', 7.4, 14441, 'tt0343737', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1267840804.jpg', 0.7, 4.4, 36.3, 41.9, 16.7, '0.411149,0.175584,-0.714657,0.564604,-0.189217,-0.325450,0.715469,0.095253,-0.691633,-0.136357,0.044266,0.911437,-0.086907,0.190629,0.409613,-0.029358,-0.079446,-0.901273,-0.209473,-0.073684,-0.265753,-0.567846,-0.357736,-0.414938,-0.217840,-0.386388,0.980907,0.235357,-0.263951,0.335948,0.232755,0.434794,0.051687,0.290537,-0.054780,-0.063497,0.204968,-0.198747,-0.395505,-0.064449,0.013024,-0.405686,0.078245,0.262178,-0.135419,0.394461,0.678886,-0.201240,0.095505,-0.248293,0.447727,-0.445729,-0.185915,0.017072,0.464815,0.153286,-0.048459,0.482614,-0.070610,-0.032879,0.158660,-0.322954,-0.944405,-0.187106,0.052828,0.128637,-0.518768,0.906419,-0.053883,-0.094147,0.105784,-0.168032,0.117117,0.366476,0.310762,0.306331,-0.246525,0.046393,-0.276496,0.358097,0.609903,-0.138542,-0.358942,0.311139,-0.563335,-0.404065,-0.339378,-0.317760,-0.351384,-0.363887,0.466713,0.059806,-0.083215,0.575858,-0.826237,0.103623,-0.247086,-0.241424,-0.002929,-0.545285,0.076841,-0.449924,-0.451560,-0.564233,-0.294253,-0.120168,0.115965,-0.301406,0.703630,-0.857438,0.108197,0.624748,0.267485,-0.564678,0.547249,0.114252,0.311880,-0.363278,0.053399,0.494210,-0.112318,0.245104,0.185293,0.159584,-0.160257,-0.060294,-0.305170,0.656132', '26759819', '1303034', '25903033', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1477448', '南极大冒险', '剧情', '动物与人之间互救互助，不舍不弃的感人故事，冰天雪地的南极迎来了三个科考队员，他们要前来搜寻一块陨石，随行的还有八条雪橇狗。南极风景优美，三人惊叹不已，然而危险却也随着美景到来。几天之后，一场暴风雪让他们尝到了苦头，其中一名队员掉进了薄冰下的冰水里面，危在旦夕，幸得雪橇狗奋身相救，队员才脱险——这似乎只是一个小小的序曲，更严峻的考验还在后头。狂暴的风雪在肆虐着南极大地，科考队员进退两难，在恶劣的天气和环境下挣扎求生。而此时，他们只能决定放弃那八条忠实的雪橇狗。当三人安全返回的时候，他们怎样也放不下那些还陷于危难的狗。为了挽救它们，三人沿途折回，回到了那片南极大地。©豆瓣', '保罗·沃克', '弗兰克·马歇尔', 8.7, 80660, 'tt0397313', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p687048224.jpg', 0.1, 0.6, 10.3, 40.7, 48.3, '0.035389,-0.218624,-0.826240,0.457112,0.299548,-0.191026,0.805257,0.148444,-0.589296,0.101177,0.597040,0.520477,-0.156407,0.037189,0.086502,-0.195144,-0.401374,-0.475825,-0.312113,-0.014852,-0.580445,-0.101741,-0.461905,-0.046754,0.021066,-0.109827,0.636479,0.526300,0.021434,0.505398,0.161768,-0.210210,-0.521351,0.637373,-0.387258,-0.005214,-0.168698,0.100688,-0.407555,0.037093,-0.158083,-0.192247,-0.490151,0.130531,0.083220,0.227034,0.713809,-0.315781,-0.208616,-0.066276,-0.043808,-0.576977,0.109930,0.220047,0.417494,-0.245375,0.234941,-0.098375,0.108848,0.284399,-0.224094,-0.043090,-0.501471,0.141261,-0.229195,0.158227,-0.603192,0.450536,0.240163,0.085952,0.003842,-0.516089,0.117787,0.323527,0.090480,0.516056,-0.411358,-0.137622,-0.378849,-0.119760,1.051362,-0.136412,-0.159747,-0.007625,-0.174157,-0.425967,0.058919,-0.059562,-0.242823,-0.208592,0.722102,0.316592,-0.343568,0.092789,-0.779779,0.370706,-0.220299,-0.424858,-0.528524,-0.292115,-0.136928,-0.505889,0.404874,0.018193,-0.235529,0.455268,0.057721,-0.099669,0.636413,-0.381026,0.417839,0.629984,0.328552,-0.285343,0.359917,-0.032605,0.353177,-0.002203,-0.137415,0.252913,-0.037056,0.471328,0.428330,0.375864,-0.375010,0.110221,-0.555468,0.073835', '3011051', '1294941', '21619567', '1473795');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1477506', '阿基拉和拼字大赛', '剧情', '自从五年前父亲去世后，阿基拉·安德森（柯克·帕尔莫 Keke Palmer 饰）慢慢成了“问题女孩”，她逃课，整蛊，总是和母亲坦娅（安吉拉·巴塞特 Angela Bassett 饰）做对，老师也拿她没办法。事实上，已经十一岁的阿基拉所作的一切都来自于她内心的孤独，加之对父亲的怀念，她开始沉溺于拼字游戏，并逐渐发现自己在这种游戏上的天赋。忙于养家、经常忽略阿基拉的母亲对此十分不解，认为她在不务正业、浪费时间，幸而阿基拉得到一位神秘教授（劳伦斯·费斯伯尼 Laurence Fishburne 饰）的支持，并在学校的拼字比赛中一路胜出，还顺利拿到参加全国拼字大赛的机会。天赋加上努力，在一场场拼字比赛中，阿基拉找到了自信和自我，并且遇到一个强劲对手——一个亚裔男孩，两人从互看不顺眼的竞争发展成惺惺相惜……©豆瓣', '柯柯·帕尔莫', '道格·阿金森', 7.7, 15275, 'tt0437800', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2253946472.jpg', 0.2, 1.6, 28.4, 51.6, 18.3, '0.162952,0.098132,-0.655875,0.499947,-0.257887,-0.377064,0.383597,-0.231551,-0.556834,-0.310908,-0.038017,0.609830,-0.165707,0.338416,0.246675,-0.412084,-0.165075,-0.635627,0.112686,0.019525,-0.162901,-0.609293,-0.334159,-0.139288,-0.233517,-0.530330,0.516051,0.014164,-0.155646,0.662906,0.290393,0.237920,0.039915,0.352192,-0.033236,-0.213794,0.076075,0.164176,-0.114235,0.213820,0.192453,-0.085781,-0.132048,0.093941,0.304785,0.236843,0.682108,-0.188320,-0.215788,0.024001,0.410556,-0.108891,-0.287534,0.140911,0.355932,0.132394,0.196002,0.309811,-0.046968,0.153034,-0.174912,-0.220202,-0.748554,0.035157,0.151354,0.184323,-0.403122,0.547533,0.025624,-0.144865,0.027889,-0.403048,-0.104987,0.307661,0.300540,0.283769,-0.299526,-0.041443,-0.255927,0.206187,0.642096,-0.192500,-0.240777,0.528394,0.102292,-0.240859,0.113768,-0.402267,-0.426933,0.126039,0.027655,0.062232,-0.049844,0.103218,-0.444714,0.144505,-0.078771,-0.196194,0.071378,-0.323684,0.258168,-0.501687,-0.126452,-0.336903,-0.339697,0.055754,-0.036360,-0.539367,0.596110,-0.915288,0.460652,0.343087,0.157429,-0.363683,0.421409,0.180615,0.125195,-0.236904,-0.261835,0.401717,0.028171,-0.135246,-0.167714,0.267899,0.256637,-0.330650,-0.343313,0.541145', '35030151', '35144311', '1292219', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1477916', '心理游戏', '喜剧', '一天雨夜，青年漫画家西（今田耕司 配音）在地铁站出来遇见了初恋梦中情人弥（前田沙耶香 配音）。西送弥回家途中得知了弥已订婚，随后，他被弥邀请到酒馆喝酒，弥的未婚夫也来了，西虽然嫉妒弥的未婚夫，但自愧不如。这时，黑社会来到店里，原来弥被黑社会所追杀，打晕了弥的男友并要强奸弥，西则蜷缩一旁不敢动弹。黑社会发现了一旁的西，用枪爆了他的屁眼。前一刻，西还沉醉于与初恋梦中情人相逢时的甜蜜，下一刻就肛门中枪，贯穿脑部，死于非命。当西等人上了天堂，西觉得自己死得很难看，后悔人生过得很窝囊，决心再度复活。他们一行人违反神的意旨，并回到地上的世界，却阴差阳错却来到了鲸鱼的肚子里，接下来又将会有什么等待着他们呢……©豆瓣', '今田耕司', '汤浅政明', 8.9, 36757, 'tt0452039', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453762724.jpg', 0.7, 1.5, 8.6, 30.6, 58.6, '0.180325,0.132993,-0.480035,0.264336,0.181473,-0.283719,0.784155,0.173409,-0.252356,-0.123665,-0.176526,0.543398,-0.622018,0.456464,0.509319,0.103721,-0.155742,-0.873065,-0.297910,-0.257794,-0.501543,-0.130697,-0.056747,-0.187874,-0.268074,-0.076553,0.279751,0.375490,0.100456,0.365760,0.207366,0.027382,-0.233024,0.554321,-0.292545,0.255983,-0.249181,0.139779,0.155917,0.153143,0.121258,-0.158728,0.059188,0.601116,0.177568,0.299378,0.553597,-0.289038,-0.100804,-0.150923,0.115483,-0.109286,-0.065295,0.271721,0.249929,-0.276839,0.111118,-0.043826,0.034687,-0.144491,0.058438,0.153948,-0.587762,0.049218,-0.227584,-0.006310,-0.566488,0.388011,-0.013127,0.362456,0.005328,-0.319756,0.276625,0.157580,0.152346,0.436318,-0.156782,-0.084485,-0.497367,0.122252,0.836418,-0.002513,0.172226,0.400153,-0.015189,-0.426729,-0.298668,0.096153,-0.291442,-0.184279,0.326384,0.040672,-0.239820,0.066661,-0.386100,-0.089620,-0.195107,0.250367,-0.228492,-0.184919,-0.046459,-0.175179,0.054752,-0.134079,-0.159090,0.294142,-0.112303,-0.143671,0.260536,-0.765343,0.220665,0.896622,0.507559,0.048078,0.565644,0.212882,-0.199234,-0.167435,-0.045856,0.459476,0.294363,0.310526,0.209343,0.325079,-0.327745,-0.180366,-0.536812,0.343546', '1947080', '1305386', '3285050', '1949005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478063', '世贸中心', '剧情', '本片是以美国“911”事件为背景的灾难片，故事重现了当时那场突如其来的灾难。9月11日的一个美妙清晨，消防总署突然警铃大作，接到世贸中心遭到恐怖袭击而倒塌的消息后，消防警员约翰·迈克洛林（尼古拉斯·凯奇 Nicolas Cage 饰）和同事们立即整装赶赴现场，摆在他们眼前的是一幅幅惨绝人寰的画面，坍塌的大厦冒着浓烟，受伤的人们在痛苦地呻吟。为了营救被困在世贸中心里面的人，约翰不顾残楼摇摇欲坠的危险，带着队友冲进了大楼中，然而他们还来不及展开动作，就被二次倒塌的残楼压住了。当约翰在碎石中醒过来时，发现昔日并肩作战的同伴全部殉职，只有一位叫威尔·吉米诺（迈克尔·佩纳 Michael Pena 饰）的警员还幸存着。他们在地狱般的废墟中等待着救援队，面对着渐渐稀少的氧气和随时可能降临的死亡，恐惧、彷徨、伤心、绝望从四面八方缓缓袭来，营救与自救在惊心动魄的24小时内同时展开了……', '尼古拉斯·凯奇', '奥利佛·斯通', 6.6, 20971, 'tt0469641', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2535495645.jpg', 1.3, 9.6, 55.5, 27.3, 6.4, '0.215696,0.074778,-1.059235,0.224572,0.217518,-0.084438,1.112312,-0.059412,-0.565536,-0.139772,0.494300,0.589663,-0.374120,0.346993,0.268485,-0.214249,-0.475705,-0.837271,-0.523114,-0.144463,-0.450595,-0.282255,-0.105266,-0.411410,0.136448,-0.535331,0.392545,0.365232,-0.052259,0.549484,0.174752,0.318390,-0.343379,0.742874,-0.081128,0.048112,0.084107,-0.161880,-0.171805,0.130370,-0.001590,-0.468347,-0.207598,0.158177,-0.335945,0.335915,0.679475,-0.482328,0.013536,0.021453,0.283630,-0.401125,0.107869,0.291222,0.349484,0.010436,0.057701,0.003251,-0.244331,-0.043852,0.143383,-0.072174,-0.568472,0.137713,-0.160996,0.456309,-0.752657,0.334978,-0.128343,0.202750,0.432136,-0.196765,0.361611,0.163588,0.001335,0.715449,-0.410480,-0.003992,-0.470881,0.108847,0.734554,-0.107218,-0.323760,0.089477,-0.095346,-0.328153,-0.150444,0.101763,-0.391183,-0.303789,0.577696,0.159723,-0.014878,0.196161,-0.603187,-0.000009,-0.267765,-0.557577,-0.497945,-0.039937,-0.493573,-0.838672,-0.061206,0.102790,-0.026307,0.324036,-0.231643,0.061229,0.535329,-0.566112,0.387713,0.519840,0.188437,0.151546,0.409533,-0.204334,0.016171,0.086954,-0.133371,0.235601,-0.021611,0.559708,0.344454,0.301236,-0.346574,-0.024569,-0.368803,0.356594', '3011051', '2269893', '4724373', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478064', '人类之子', '剧情', '20年后的人类社会，正面临着前所未有的灭顶之险——所有的人类都丧失了生育能力，而东欧和非洲国家已经四分五裂，人口向英国等富裕国家大量迁移。然而在英国境内，人们正陷入一片混乱和恐慌中。人人都为世界末日的到来而焦躁狂暴。非洲女孩肯（克莱尔-霍普•阿什提 Claire-Ho pe Ashitey饰）非法移民到这个国家，但令人振奋的是她腹中竟然怀有孩子。为了保住人类唯一的血脉，警察蒂奥（克里夫•欧文 Clive Owen 饰）和前妻朱丽（朱丽安•摩尔 Julianne Moore 饰）决定不惜一切代价将肯安全离境，但枪林弹雨却使他们举步维艰。在逃亡中，婴儿出生在了一个难民营里。刀枪当前，保住人类最后的希望，成为蒂奥心中唯一的信念。©豆瓣', '克里夫·欧文', '阿方索·卡隆', 7.6, 74931, 'tt0206634', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1971393744.jpg', 0.7, 3.9, 30.8, 45.8, 18.8, '-0.101518,0.288318,-0.837023,0.335970,0.068918,-0.217021,0.707706,-0.024841,-0.585491,-0.100775,0.095734,0.890926,0.212042,0.166583,0.252579,0.059295,-0.336986,-0.605377,-0.261013,-0.115751,-0.426342,-0.338562,-0.437128,-0.559543,-0.348292,-0.334205,0.828139,0.485652,-0.106759,0.388018,0.046528,0.364549,0.007046,0.463916,-0.199340,-0.066424,-0.106212,-0.180824,-0.486076,0.175803,0.017866,-0.019369,-0.225034,0.454448,-0.019890,0.377238,0.684168,-0.488258,0.128151,-0.367542,0.395500,-0.493835,-0.241541,0.354438,0.091974,-0.211004,0.152855,0.081703,-0.105800,-0.104921,0.220564,-0.184580,-0.783907,-0.052737,-0.021686,0.191266,-0.514790,0.362674,-0.012379,-0.007750,0.246126,-0.193717,0.235798,0.551892,0.136659,0.569318,-0.485211,-0.068697,-0.614964,-0.144574,0.735661,-0.351929,-0.449725,-0.006081,-0.433946,-0.579459,0.010891,-0.539233,-0.511414,-0.310169,0.139234,0.225513,-0.259026,0.513781,-0.631301,0.130628,-0.407972,-0.518089,0.004883,-0.250499,-0.153985,-0.296665,-0.247016,-0.329888,-0.208401,0.300311,0.311774,-0.090758,1.027675,-0.614614,0.248176,0.560846,0.473703,-0.665758,0.414649,-0.144716,0.400121,-0.164626,-0.130712,0.530445,0.030191,0.370555,-0.038786,-0.124980,-0.304873,0.103509,0.031965,0.437919', '24284209', '27602116', '30163500', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478066', '父辈的旗帜', '剧情', '1945年2月，被喻为“太平洋的绞肉机”的硫磺岛战争结束。在战斗的第五天时，五名美军海军士兵、一名军医、一名随军记者一起“缔造”了一张英雄的照片，一张象征国家胜利的照片：他们将美国国旗插在了硫磺岛的制高点。当照片登上美国各大报纸头条的时候，当时的六名英雄中的三人甚至还不及知道自己成为英雄而英勇牺牲了。幸存下来的其余三人战后却对那场战争只字不提，仿佛他们未曾参与那场战争。因为他们不是为了成为英雄才走上战场，他们是为了国家而战，当他们看到身边的伙伴一个个倒下时，他们觉得生命的意义也在一点点流失……©豆瓣', '瑞恩·菲利普', '克林特·伊斯特伍德', 7.8, 49382, 'tt0418689', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p798398494.jpg', 0.3, 1.7, 25.3, 52.4, 20.2, '0.155815,0.132413,-0.711600,0.580025,0.086713,-0.190987,0.717582,-0.199885,-0.363939,-0.049860,0.531691,1.167861,-0.081497,0.028020,0.348681,-0.455959,-0.337264,-1.159757,-0.393899,-0.170220,-0.530040,-0.182781,-0.407839,-0.224781,-0.275192,-0.416445,1.089828,0.262888,-0.049838,0.688479,0.284514,-0.044915,0.081038,0.517307,-0.159659,-0.211958,-0.009068,-0.066755,-0.371232,0.091799,-0.453947,-0.416303,-0.396263,0.273278,-0.140451,0.021914,0.866185,-0.345259,0.168772,-0.333140,0.197736,-0.556093,0.075692,0.173789,0.751823,0.059765,0.158400,0.169428,0.246311,-0.187938,0.081911,0.024912,-0.994148,-0.029201,-0.275213,0.303407,-0.628223,0.844678,-0.282395,0.172391,0.199912,0.008754,0.627269,0.686292,0.190505,0.271476,-0.329263,-0.154374,-0.736426,0.431819,0.883960,-0.174759,-0.127851,0.079214,0.063447,-0.490322,-0.348111,-0.379066,-0.376197,0.158024,0.358953,-0.091522,-0.154855,0.201820,-0.696460,0.196864,-0.282553,-0.745424,0.013205,-0.308007,-0.196255,-0.704759,-0.237494,-0.264024,-0.158139,0.323934,0.031177,-0.059080,1.285611,-0.654496,0.067091,0.534721,0.366096,-0.460104,0.890529,0.377668,0.222926,-0.197459,-0.150091,0.100497,0.073481,0.458582,0.292759,0.159051,-0.263015,0.053986,-0.047480,0.525654', '27602116', '30162520', '3811356', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478174', '赌圣3：无名小子', '喜剧', '无名（张家辉 饰）从小就无父无母，幸亏得到舅舅罗四海（王晶 饰）收留，无依无靠的无名自小就没人管，经常流连街头赌档，练得了一身精湛赌术。罗四海发现了无名的绝技，于是带着他与两个小弟阿骏（黎骏 饰）和贱男到深圳设局骗钱。四人在深圳行骗时得罪了本地老大猛哥（龙方 饰），在猛哥面前无名凭借一手绝活博得赏识四人才得以解围。回港后无名邂逅了一个盲人女模特苦儿（舒淇 饰），阿骏看出了无名的心思，向他保证能帮助追到苦儿，条件是传授他赌术。无名爽快应承了。猛哥来港找到了无名，逼他用赌术为他赚钱，无奈之下无名只能答应。岂料阿骏赌术学成后，乘机打盲了无名，在猛哥那里取代了无名的位置。无名最终命运如何？©豆瓣', '张家辉', '张敏', 6.2, 7954, 'tt0275538', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2043343558.jpg', 2.9, 16.6, 57.1, 16.3, 7, '-0.063730,0.104023,-0.412156,0.345525,-0.270894,-0.585498,-0.222129,0.001683,-0.431372,-0.154544,0.234059,0.683176,0.216870,0.196946,0.132257,0.066203,-0.014929,-0.474358,-0.057535,-0.188852,-0.059437,-0.286883,-0.162460,-0.038679,-0.294725,-0.115750,-0.009773,-0.091149,-0.204597,0.480067,0.324080,0.241391,-0.229855,0.038669,-0.407695,0.202359,-0.028386,0.023990,-0.344933,0.559114,-0.093365,-0.346411,-0.141116,-0.017920,0.101467,0.243690,0.415624,0.081322,-0.097097,-0.343977,0.016995,0.015341,-0.172082,-0.165900,-0.079631,-0.138793,0.384839,0.025334,-0.276119,0.025196,0.059414,0.085119,-0.443727,-0.043755,0.138886,-0.091848,-0.667249,0.052465,-0.188473,-0.490541,-0.129172,-0.551924,0.049896,-0.060855,0.088991,-0.037613,-0.023435,0.052280,-0.427665,0.219592,0.343633,-0.074070,0.283768,0.195761,0.443461,-0.054295,0.203453,-0.253306,-0.034018,-0.098475,0.373378,0.088862,-0.238681,-0.196249,-0.224580,-0.186921,-0.062070,0.448573,0.026773,-0.188983,0.101292,-0.412006,0.014827,-0.240217,-0.210263,-0.279697,0.084750,-0.229265,0.786579,-0.663835,0.291341,0.155669,0.240722,-0.290722,0.445424,0.045129,-0.010381,0.024420,0.011753,-0.215504,0.164970,0.362082,0.389695,0.356114,-0.107581,-0.465155,-0.036973,0.235624', '1292720', '26593587', '1296770', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478582', '幸运数字斯莱文', '剧情', '老实巴交的小伙子斯莱文（乔什•哈奈特 Josh Hartnett 饰）带着好朋友尼克对他的承诺来到了世界金融中心纽约讨生活。尼克曾承诺只要斯莱文来纽约闯天下，他将提供一切的帮助。然而，当斯莱文按照尼克提供的地址找到尼克住所时，却发现尼克已经不知所踪。身无分文又无家可归的 斯莱文只好暂时住在尼克的空房子里。大麻烦降临到斯莱文的头上！原来纽约的两伙黑帮都在竭力寻找尼克，原因尼克知道一次“黑吃黑”事件的真相。这下他们都把住在尼克家的斯莱文当成了尼克！一时，斯莱文百口莫辨，陷入了黑帮混战中。最后，“幸运”的斯莱文能否化险为夷？©豆瓣', '乔什·哈奈特', '保罗·麦圭根', 7.4, 15588, 'tt0425210', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p504736537.jpg', 0.6, 3.9, 33.2, 47.7, 14.6, '0.728906,-0.076581,-0.740193,0.177345,-0.272837,-0.780980,0.158845,-0.223114,-0.386636,-0.265568,0.675243,1.143590,-0.142006,-0.059286,0.189511,-0.058280,-0.464337,-0.496421,0.213859,-0.538529,-0.251319,-0.755906,-0.109547,-0.260817,0.077567,-0.214868,0.240644,-0.000464,0.416739,0.275087,0.055482,0.244051,0.324643,0.325431,0.204433,0.323645,0.267715,-0.236922,-0.204519,0.534233,0.089642,0.279067,-0.116760,0.211778,0.565226,0.256530,0.426725,-0.640198,0.286161,0.510830,0.356978,-0.399543,0.410174,0.021669,0.339058,-0.316496,0.028987,-0.117704,-0.526823,-0.356643,0.149707,0.039462,-0.609342,-0.058234,0.059992,0.043418,-0.441752,-0.021400,-0.074281,-0.003174,0.388886,-0.304352,-0.006302,0.295846,0.961848,0.253203,-0.012337,-0.263583,-0.173468,-0.161854,0.397657,-0.337790,-0.053606,-0.187249,-0.405729,-0.356879,-0.065855,-0.313194,-0.308113,-0.170616,0.642633,-0.210642,-0.206007,0.808983,-0.301087,-0.077652,-0.553408,-0.079007,-0.075441,-0.317256,-0.131519,-0.631263,-0.099444,-0.006778,-0.142671,0.206808,0.062321,-0.049129,0.086083,-0.761202,0.239545,0.842601,0.299145,0.202789,0.559725,-0.058395,-0.003303,-0.059813,-0.210201,0.775085,0.526673,0.457281,0.281005,0.128206,-0.062790,-0.141173,-0.206279,0.150714', '1309069', '1829654', '26835471', '3148748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478789', '春雪', '剧情', '大正时代，出身贵族的松枝侯爵家嗣子松枝清显（妻夫木聪饰演），对青梅竹马的绫仓伯爵家的掌上明珠聪子（竹内结子饰演）情有独钟，但清显一直没有勇气向她表白，反而笨拙地示爱或者伤害，甚至因为误会中断联系。然而由于贵族彼此间的复杂考虑，聪子和治典殿下订了家族婚事，清显这才发现他对聪子的爱无法自拔，通过多方设法，使两人得以私下偷会，但恰恰这样的行为反让这对情侣都陷入绝望的苦恋而无法自拔，已是他人未婚妻的聪子怀孕后，真相无法掩藏，他们走向了爱情的尽头。©豆瓣', '妻夫木聪', '行定勋', 7.1, 6579, 'tt0468753', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p886003064.jpg', 1.1, 6.1, 41.6, 36.6, 14.5, '0.340668,-0.033365,-0.468846,0.690109,0.001717,-0.283531,0.613482,0.253047,-0.527176,-0.446130,-0.007532,0.600033,-0.166122,0.133115,0.214586,0.103950,-0.167183,-0.731454,-0.038310,-0.183371,-0.077766,-0.530080,0.107642,-0.184851,-0.228410,-0.007548,0.936568,0.180017,-0.329233,0.312881,0.345514,0.317929,-0.039679,0.398817,0.135383,0.054831,0.056377,0.184026,-0.414853,0.089043,-0.028179,-0.132354,-0.067812,0.299212,-0.031115,0.448291,0.538608,-0.455664,-0.291415,-0.114195,0.388947,-0.209335,0.100175,0.484099,0.396086,0.065448,0.205598,0.243110,-0.188114,-0.272348,0.032872,0.170540,-0.615323,0.133959,0.170716,-0.063252,-0.322506,0.492954,-0.033549,-0.279053,-0.003689,-0.092507,0.230850,0.521888,0.388856,0.115902,-0.613546,0.047511,-0.285805,-0.127976,0.575327,0.183036,-0.203353,0.493895,-0.327659,-0.325663,0.004764,-0.424113,-0.704249,-0.115197,0.087764,0.565455,-0.179858,0.385652,-0.193446,-0.252484,-0.271224,0.066189,0.338623,-0.748686,0.003967,-0.389049,-0.440403,-0.770008,-0.276609,-0.055936,0.126402,-0.320824,0.475350,-0.692142,0.060289,0.496630,0.477041,-0.560150,0.704924,0.382144,-0.103801,-0.283487,-0.367947,0.412168,-0.096195,-0.024002,0.041340,0.020410,0.017637,0.012145,-0.354078,0.082117', '30345227', '35287908', '1295681', '4840388');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1478926', '龙虎门', '剧情', '本片根据黄玉郎同名漫画改编。出身武术世家的王降龙（元华 饰）、王伏虎兄弟为使草根阶层不受欺压，开创龙虎门传授武术、匡扶正义。王小龙（甄子丹 饰）、王小虎（谢霆锋 饰）为王伏虎膝下一对同父异母的兄弟，小龙幼年时被母亲带离龙虎门，身边留有一块龙形玉佩和小虎的虎形玉佩成双。小龙命运多舛，母亲身死后他为帮派人物马坤（陈观泰 饰）收养。小龙搭救了后来成为火云邪神手下的罗刹女（李小冉 饰），成为她一生所爱。时光荏苒，青年王小虎与众师弟盲打误撞卷入马坤与白狮帮的纷争，并得到火云邪神交予马坤的罗刹令。王小龙为马坤取回罗刹令，却因不容马坤手下的卑鄙行径而和对方动手，混战中，王小虎得到嗜武青年石黑龙（余文乐 饰）援手。王小虎与马坤之女马小灵（董洁 饰）相遇相识，石黑龙亦如愿拜入王降龙门下，另一边，马坤欲退出江湖却惹怒火云邪神，王小龙浴血苦战，只救得小灵。火云邪神听信罗刹女拖延之计独身横扫龙虎门，王小虎石黑龙身受重创，小灵带二人远赴白云山求助。龙虎三皇潜心修炼，准备与火云邪神的最后一战……', '甄子丹', '叶伟信', 5.9, 73467, 'tt0482930', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1520857276.jpg', 3.9, 20.3, 55.4, 15.6, 4.8, '-0.218531,0.042610,-0.341478,0.450929,0.079002,-0.306795,0.256586,-0.003690,-0.485269,-0.351996,0.416025,0.467224,0.000311,0.084106,0.241544,-0.211664,0.113217,-0.598454,-0.105036,0.032287,0.221372,-0.026180,-0.202565,0.121549,-0.442992,-0.183972,0.731672,0.138945,-0.188636,0.476523,0.261403,0.377746,-0.456437,-0.045745,-0.153051,0.157093,-0.367721,0.057974,-0.467211,0.198458,-0.185299,-0.073616,-0.284551,0.200163,-0.304806,0.258949,0.331852,-0.404030,0.194986,-0.729524,0.157799,-0.121164,-0.123445,-0.079137,0.293955,0.024834,0.339016,0.182895,0.087043,0.163485,0.041089,0.030731,-0.505335,0.314571,0.230612,0.053711,-0.363041,0.263760,-0.187138,0.020853,0.025436,-0.128831,-0.160573,0.111153,0.410194,-0.040110,-0.165702,0.122437,-0.220182,0.088764,0.476388,-0.112047,0.222320,-0.200397,0.326206,-0.310088,0.161183,-0.248415,-0.054467,-0.123381,0.435690,0.088419,0.269633,0.327723,-0.204432,-0.316291,-0.279728,0.476732,-0.047014,-0.015389,0.105053,-0.458058,-0.064369,-0.147888,-0.040053,-0.336211,0.326138,-0.175059,0.598877,-0.568265,0.175419,-0.155773,0.331297,-0.549781,0.329183,0.042564,0.301034,-0.204158,-0.252937,0.143884,0.308037,0.236887,0.275598,-0.032180,-0.155427,-0.028123,-0.059902,-0.076728', '2369613', '3861846', '30345227', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1479110', '犀照', '剧情', '家中经营药堂的刘诚（冯德伦饰）带着一众乡亲打算到城里发展生意。生意正值兴旺，一场莫名的大火让所有兄弟都失去了生命，刘诚自此一无所有并锒铛入狱。真正的凶手其实是他的助手彭四（黄浩然饰），为了钱竟不择手段。狱中警察的亲人曾受刘诚慷慨施药，于是请来年轻律师蓝小芊（钟欣桐饰）帮刘诚洗脱罪名。可惜彭四用钱疏通关系，决心要将刘诚置之死地。蓝小芊买通刽子手，希望能在行刑时放走刘诚。刘诚回到自己的故乡，发现祖屋被毁，妻子女儿过着人不似人的生活。后来，刘诚才被早已发生在自己身上的事吓倒。©豆瓣', '冯德伦', '林健龙', 6.1, 5309, 'tt0757139', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p967358738.jpg', 3.9, 17.1, 54.4, 18.2, 6.5, '-0.072502,-0.081068,-0.499390,0.192298,-0.353407,-0.381737,0.588687,0.234352,-0.651160,-0.353679,0.327973,0.528019,0.152903,0.310033,0.231695,-0.029592,-0.152985,-0.710209,-0.007016,-0.097570,-0.204684,-0.422058,0.082092,-0.279383,-0.231007,-0.139128,0.304164,0.241985,0.006800,0.299831,0.191561,0.063445,-0.093793,0.483640,-0.215332,0.149303,-0.032440,-0.082334,-0.620403,0.022616,-0.018447,-0.217781,-0.199237,0.250210,0.060337,0.298530,0.513437,0.051225,-0.232753,-0.128442,0.065342,-0.297721,0.137937,0.223012,0.214070,0.106050,0.140471,0.404484,-0.427536,-0.129337,0.255967,-0.123045,-0.705829,-0.032281,0.234265,-0.044445,-0.684113,0.369559,-0.043297,0.037875,-0.026560,-0.310193,0.369790,0.227985,0.159087,0.450192,-0.160025,0.068529,-0.736425,0.445749,0.772664,-0.310160,0.264004,0.312863,-0.081306,-0.165972,0.107193,-0.271241,-0.333156,0.085834,0.449235,0.004576,-0.202227,0.207413,-0.276572,-0.283183,-0.276719,-0.037062,0.111341,-0.319292,0.109635,-0.098689,-0.289861,0.013569,-0.298647,0.184646,0.206088,-0.341934,0.447815,-0.534676,0.073859,0.565538,0.331275,-0.675684,0.225724,0.063332,0.223175,-0.221614,-0.323336,0.005411,0.271353,0.501317,0.325741,-0.150861,-0.276731,-0.247108,-0.131008,0.261091', '1309116', '1292268', '26996783', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1479377', '保持缄默', '喜剧', '本片讲述了小镇牧师沃尔特·古德菲勒（罗温·艾金森 Rowan Atkinson 饰）是位上帝忠实的侍奉者，他整天为教区的事忙得不可开交，还要为快要召开的牧师大会发言稿准备着。却忽视了家庭和妻子格洛里亚·古德菲勒（克里斯汀·斯科特·托马斯 Kristin Scott Thomas 饰）的感受。妻子得不到丈夫的关爱又被家庭琐事纠缠着，又担心青春期的女儿滥交男友，而懦弱的儿子在学校经常被同学们欺负。还每天晚上被邻居家狗的叫声骚扰使她心烦意乱。这时招来了管家格雷斯·霍金斯(玛吉·史密斯 Maggie Smith 饰)，这位慈祥的老人来到了他们家。管家到来后她就像亲人一样照顾和关心着全家人，一切都在悄无声的改变着，每天晚上都在叫的邻居家的狗忽然消失了，而格洛里亚·古德菲勒的情人也没了踪影，所有原来对他们家不利的事情都在向好的方向发展。所有事仿佛都与这位管家有关，然而，让他们没有想到的是这位神秘的管家有一个天大的不可告人的秘密......', '罗温·艾金森', '尼尔·约翰逊', 7.8, 27578, 'tt0444653', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1429472110.jpg', 0.4, 2, 25.4, 52.1, 20.1, '0.264934,-0.310773,-0.663603,0.443955,-0.306410,-0.359078,0.726965,0.357512,-0.500356,-0.394110,0.032409,0.724029,-0.103290,0.321106,0.253479,0.246862,-0.317913,-0.810534,-0.258127,-0.135086,-0.145425,-0.409071,-0.005916,-0.345897,-0.125784,-0.460200,-0.076799,-0.216948,-0.070706,0.341685,0.286530,0.359504,0.045043,0.474739,-0.187527,0.282629,0.280782,-0.007216,-0.084501,-0.020955,0.108261,0.055158,-0.291997,0.231933,0.050867,0.426616,0.436492,-0.328129,-0.155832,-0.090800,0.150785,-0.308161,0.327154,0.273088,0.500274,-0.164067,0.176724,0.256971,-0.198200,-0.066284,0.250088,-0.055159,-0.789794,0.179952,0.018349,0.304717,-0.871917,0.469071,-0.185793,-0.178965,0.313805,-0.407872,0.418028,0.306800,-0.048723,0.536670,-0.256868,0.021007,-0.570403,0.114262,0.571387,0.124523,-0.195184,0.211575,-0.191851,-0.158269,0.048457,-0.144518,-0.754216,-0.113543,0.236179,0.022508,-0.137063,0.485256,-0.392392,-0.073446,-0.120557,-0.278199,-0.072169,-0.620199,-0.203689,-0.695945,-0.052264,-0.321109,-0.313652,0.224017,0.019331,-0.059354,0.788147,-0.806229,0.457952,0.658676,0.205279,-0.618811,0.799246,0.135781,0.230843,-0.207909,-0.124147,-0.026259,0.198825,0.332044,0.377714,0.349647,-0.021747,-0.1319