INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1479864', '灵幻至尊', '恐怖', '茅山弟子傲天龙（林正英 饰）与大黄（郑则士 饰）同时爱上了师傅的掌上明珠梦梦，师傅临终前设局考验二人谁更真心，大黄用计赢得了师傅的信任。虽然梦梦倾心天龙，无奈父命难为，天龙于是愤然出走。一晃十八年过去了，大黄和梦梦的儿子连高（金少龙 饰）已经长成英俊少年，而天龙的女儿凝红（黎姿 饰）也成年。天龙父女俩这天回家乡探亲，半途上遇到红袍火鬼为祸人间。天龙费尽九牛二虎之力将其收伏，关在鬼笼内。回到家乡，大黄和天龙两师兄弟心里还是有隔阂，互相敌视。连高无意中放出了火鬼，此时的火鬼法力大增，天龙和大黄都已无法独力应付。为了对付火鬼，二人终于抛开成见，再次合作。©豆瓣', '林正英', '吴勉勤', 7.2, 10168, 'tt0102772', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2349401980.jpg', 0.8, 5.1, 43.5, 34.6, 16.1, '-0.146066,-0.115850,-0.332140,0.257399,0.186072,-0.642923,0.232214,-0.030349,-0.550681,-0.127843,0.311133,0.373793,0.174504,-0.022690,0.116194,0.035966,-0.128050,-0.525952,0.049599,-0.064618,0.110392,-0.165730,-0.178145,0.153788,-0.110965,-0.014956,0.393409,-0.156199,0.303228,0.756367,0.373340,0.148596,-0.344531,0.022958,-0.155032,0.225812,-0.200288,0.203291,-0.408794,0.148393,-0.092173,0.072082,-0.250725,0.177823,-0.202146,0.153370,0.276454,-0.310055,-0.314713,-0.366826,-0.098867,-0.107838,-0.231675,0.052214,0.297762,-0.036504,0.664672,0.210676,-0.078877,0.230624,-0.247432,0.244066,-0.437599,0.363478,0.153316,-0.167483,-0.351464,0.329473,-0.029601,0.021762,0.070050,-0.522927,-0.229293,0.248474,-0.031482,0.342215,-0.499865,0.155905,-0.394765,-0.150697,0.618979,-0.320145,0.368526,0.020521,0.294904,-0.068879,0.031621,-0.249743,0.012788,-0.049497,0.330671,0.380914,0.084961,0.356523,-0.506362,-0.202070,-0.352205,0.272858,0.136019,0.002225,0.006116,0.017799,-0.237601,-0.387214,-0.184847,-0.330769,0.258009,-0.137551,0.723110,-0.841328,0.173824,-0.074805,0.467426,-0.421759,0.498040,-0.047179,0.193803,-0.448454,-0.299895,0.009954,-0.069247,0.467833,0.303006,0.017802,0.060317,-0.119717,-0.259828,-0.042326', '35030151', '1292219', '3091208', '1306133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1479872', '再世追魂', '惊悚', '探长（吕良伟 饰）的妻子怀孕即将生产，两人匆匆赶往医院，途中，探长接到了出警任务，称有三名穷凶极恶的劫匪正在持枪抢劫，探长赶到了现场，英明神武的他迅速而又准确地击毙了其中两名歹徒，剩下的一名被就地制服并放出狠话，称要向探长复仇。探长的妻子生下了一对双胞胎，让探长感到在意的是，这两个婴儿的额头上分别有一枚红色的胎记，巧合的是，胎记的位置竟然和那两名劫匪被子弹击中的位置一模一样。随着时间的推移，两个孩子渐渐长大，周遭发生的种种让探长不得不开始怀疑，这两个孩子有可能是两名劫匪的投胎转世，而自己的生命正遭受着莫大的威胁。©豆瓣', '吕良伟', '梁小熊', 7.2, 6059, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2351351496.jpg', 0.8, 4.4, 42.1, 38.9, 13.8, '0.371792,-0.186619,-0.668509,0.489536,-0.188028,-0.283415,1.070688,0.064156,-0.356358,-0.283045,0.556105,0.737970,-0.229857,0.200253,0.290775,-0.018187,0.146680,-0.898738,-0.324544,-0.053565,-0.565962,-0.420680,-0.283961,-0.067878,0.210078,-0.361338,0.498137,0.048527,0.016692,0.662438,0.560635,0.376062,-0.141123,0.161280,-0.507088,0.226720,0.219807,-0.254450,0.030453,0.278880,0.199359,-0.237670,0.272567,0.252520,-0.443945,0.582221,0.856675,-0.112871,-0.267941,-0.234094,0.344791,-0.384820,-0.021013,0.206932,0.590142,0.197129,0.194383,0.096926,-0.280497,0.027343,0.242841,0.142320,-0.824865,0.193430,-0.053277,0.360640,-0.658997,0.263872,-0.112062,-0.205631,0.286050,-0.252765,0.453252,0.406035,-0.112743,0.383994,-0.275772,-0.248804,-0.558120,-0.088918,0.608466,-0.090169,-0.124710,0.384448,0.026716,-0.348801,0.014886,-0.003965,-0.063011,0.083051,0.549611,0.128015,-0.173389,-0.163936,-0.388700,0.280166,-0.539461,-0.116988,-0.191679,-0.139738,-0.092464,-0.515608,0.077533,-0.401027,-0.565550,0.361728,0.041172,0.039051,0.696932,-0.471209,0.124988,0.562131,0.321851,-0.571585,0.566004,0.205868,0.248136,-0.206560,-0.093229,-0.099200,0.298815,0.369662,0.243542,0.394616,-0.374591,-0.225085,-0.368481,0.141050', '21619567', '1578663', '1307748', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1480051', '阴阳路', '恐怖', '由 “讲古佬” 毕彼得（雷宇扬 饰）的叙述开始，分别带出四个鬼故事。《抄墓碑》讲述三名青年（古天乐、丁子峻、朱永棠 饰）到荒岛上度假，夜晚在海边偶遇三个露营少女（蔡少芬、麦家琪、白嘉倩 饰）便一起大讲鬼故事，Ken自认大胆，提议到附近坟场抄墓碑上死人的资料，在抄墓碑时发现了其中一名刚认识女子的墓碑。《阴阳路》讲述一个天昏地暗的下午，杜先生（陈锦鸿 饰）与妻子（钟丽缇 饰）相约在餐厅吃饭，与情妇在开车途中发生争执，发生交通意外，结果妻子仍然不断接到丈夫电话......《红当当》讲述小波、大B、Jo Jo去祭拜已故朋友Ken，在陵园无意中被已故杜先生的鬼魂缠上，幸遇与“毕彼得”长相一摸一样的灵异专家“一颗痔”解救。脱险后“一颗痔”警告其少穿红衣，“跟红顶白”是鬼怪的习惯......《佗地位》讲述电影明星雄哥（吴志雄 饰）带着他的女友May（伍咏薇 饰）前往电影院看一出他有份主演的恐怖片，两人误坐了两个“鬼陀地”的“陀地位”，最后，在剧院洗手间突然遇到灵异事件，一直走不出剧场……', '古天乐', '郑伟文', 6.8, 18556, 'tt0286322', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2354367019.jpg', 1.2, 7, 51.5, 30.5, 9.8, '0.244544,-0.182064,-0.475868,0.312179,0.146304,-0.042805,0.731500,0.326647,-0.271728,-0.327292,0.167325,0.685731,-0.453834,0.419602,0.469734,-0.145229,-0.287217,-0.473454,-0.080273,-0.054723,-0.352407,-0.363454,0.133595,-0.032704,-0.010875,-0.218241,0.103778,-0.044802,-0.169037,0.560466,0.342126,0.154748,-0.591119,0.049232,-0.400861,0.109755,0.065817,0.329609,-0.199820,0.177826,-0.128494,-0.280117,-0.061179,-0.188729,0.074968,0.246508,0.614181,0.002968,-0.077549,0.063043,0.220844,0.071618,-0.012024,0.089552,0.521106,0.143834,0.346910,0.167405,-0.046446,0.018895,0.109407,-0.174026,-0.041963,0.225845,0.107385,0.355563,-0.507223,0.251309,0.032303,0.013232,0.166846,-0.205380,0.465737,-0.065662,0.132340,0.392478,0.219244,0.054061,-0.403748,0.315855,0.317914,0.060449,0.477309,0.256141,0.294745,-0.342547,0.044001,0.265414,-0.176018,0.103666,0.291348,-0.253443,-0.132490,-0.212881,-0.484731,-0.169178,0.023230,-0.010911,0.113981,-0.093324,-0.214294,-0.738286,-0.040361,-0.155855,0.007594,0.406611,-0.029190,-0.083014,0.396770,-0.328642,0.235261,0.204350,0.105468,-0.304231,0.683208,0.061851,0.073849,-0.255048,0.187129,0.260836,0.348015,0.186191,0.064431,0.335759,-0.402085,-0.0