INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1480318', '洪兴仔之江湖大风暴', '剧情', '香港铜锣湾，喧嚣鼎沸，鱼龙混杂。黑道中两大势力洪兴和东星盘桓于此，龙争虎斗，此消彼长。洪兴老大洪胜（谷峰 饰）骁勇精明，为人义气，颇得徒众敬仰，却独独与儿子洪飞（梁朝伟 饰）关系不和。洪飞淡出黑道，独来独往过着自在生活。洪兴马仔小春（陈小春 饰）偶然与东星老大的儿子阿宝及头面人物垃圾，正当危难之时阿飞出手相助。小春对其无限崇拜，更将妹妹小彤（李若彤 饰）介绍给阿飞。身为记者的小彤从小就对金庸小说中的英雄侠客充满敬仰，她对江湖之事怀有一份浪漫的情结，由此小彤阿飞渐渐萌生感情。洪胜年事已高，准备金盆洗手，但在典礼当晚遭到东星骚扰，气急病倒。在小彤的劝说下，阿飞与父亲重归于好。与此同时，洪兴与东星的矛盾日益激化，一场黑道风暴即将到来……©豆瓣', '梁朝伟', '邱礼涛', 6.4, 7059, 'tt0118118', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2408444955.jpg', 2.6, 12.2, 55.5, 20.4, 9.5, '-0.060750,-0.149615,-0.632269,0.361703,0.186664,-0.142194,0.484696,0.269450,-0.689476,-0.176100,0.211730,0.700273,-0.185905,0.253862,0.281796,-0.366533,-0.109628,-0.794245,-0.111653,0.045368,0.323456,-0.388616,-0.302750,0.004633,-0.333759,-0.057777,0.387835,0.210503,-0.360061,0.708863,0.285213,0.359542,-0.436302,0.611000,-0.036742,0.009313,-0.013984,0.172828,-0.672128,-0.203731,-0.015954,-0.312585,-0.166431,0.264206,-0.013720,0.103393,0.465910,-0.069087,-0.086094,-0.312451,0.052581,-0.172952,-0.102806,-0.049290,0.357152,0.037962,0.280942,0.366306,0.032029,-0.026769,-0.258280,-0.000955,-0.463067,0.032775,0.106361,0.115770,-0.608057,0.615369,-0.060413,-0.244089,0.011723,-0.180131,0.211253,0.187172,0.271066,0.223355,-0.010226,0.118973,-0.181274,0.040695,0.654323,0.132501,0.316220,0.101342,0.130830,-0.256521,0.127345,-0.117186,-0.455526,-0.170921,0.284250,-0.157568,-0.006503,0.660568,-0.555052,0.061290,0.128357,0.194726,-0.012430,-0.321715,0.102522,-0.419824,-0.376166,-0.438527,-0.165551,0.009898,0.281300,0.018146,0.876858,-1.017589,0.113761,0.078733,0.277926,-0.627722,0.403554,0.291655,0.078906,-0.217353,-0.388185,-0.057322,-0.077348,0.058117,0.050873,0.069760,-0.178318,-0.256409,-0.088495,0.065615', '35030151', '1292219', '3445516', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1481233', '精灵鼠小弟3', '喜剧', '他是一个聪明的、热心的家伙——他是一只老鼠，一只颇有心计的老鼠，他的名字叫斯图亚特。斯图亚特在这个对他来说超级庞大的世界里，一心想寻找自己的家和归属的意义，当他被里特一家收养之后，他开始了一场和各种角色一起的冒险活动——包括他的宿敌家：猫斯纳贝尔。', '查尔斯·阿德勒', 'Audu Paden', 6.9, 5296, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193565184.jpg', 1.9, 8.1, 46.7, 29.2, 14.1, '0.750558,0.112376,-1.104872,0.742022,-0.669124,0.045915,0.948357,-0.069455,-0.597519,0.014514,0.162087,1.296816,-0.074093,0.268590,-0.013129,0.429224,0.112261,-0.769606,-0.127054,-0.187717,-0.160402,-0.625201,-0.684860,-0.382157,-0.079765,-0.110937,0.293236,-0.204844,-0.189092,0.356564,0.445685,0.172320,0.392906,0.521669,-0.510906,0.028621,0.242726,0.115032,0.363191,0.193872,0.089510,0.101341,-0.222482,0.459161,-0.062862,0.552637,0.732583,-0.530077,-0.113465,-0.462531,0.170222,-0.327896,-0.206706,0.134215,0.551900,-0.169100,0.278209,0.124879,-0.155195,-0.138261,0.120368,-0.115301,-1.159914,-0.211348,0.098009,0.116030,-0.788675,0.532202,-0.031836,-0.277033,0.031506,-0.287323,0.324436,0.255245,0.341063,0.479570,-0.037929,-0.049822,-0.451614,0.030829,0.824334,-0.136686,-0.204014,0.488113,-0.215165,-0.456913,-0.134915,-0.136593,-0.652141,-0.352170,0.591790,-0.257774,-0.620180,0.015421,-0.945200,0.313978,-0.222871,-0.161497,-0.249537,-0.588170,-0.126175,-0.194927,-0.075077,-0.640119,-0.281156,0.104136,0.174648,-0.383913,1.082093,-0.992961,0.037711,0.603587,0.227925,-0.604073,0.934067,0.152833,0.108716,-0.216781,0.100920,-0.116249,0.072748,-0.004194,0.260487,0.746735,0.293482,-0.197858,-0.317320,0.944177', '30162520', '1783461', '24756472', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482030', '国王班底', '剧情', '威利（西恩·潘 Sean Penn 饰）是生活在路易斯安那州的一名政治家，对于自己的仕途，威利有着非常远大的理想和抱负。长久以来，在南方种植园里工作的农民们都遭受着非常不公平的待遇，威利亲力亲为的为他们谋求福利和权益，久而久之，威利的努力得到了回报，农民们在生活条件逐渐得到改善的同时，也极力的拥护着威利，将他视为他们的领导人。在选举中，因为得到了农民们的大力支持，威利最终顺利的被选为了议员，可是，在他手握的权利越来越大的同时，威利也逐渐的忘记了自己的初心。为了向上爬，他开始无所不用其极的来打压竞争对手，玩弄权谋手段。©豆瓣', '西恩·潘', '斯蒂文·泽里安', 7.1, 5713, 'tt0405676', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1133251922.jpg', 0.9, 6, 40.6, 40.7, 11.7, '0.224531,0.024624,-0.866708,0.859742,-0.354150,-0.270317,0.630673,0.214435,-0.506690,-0.133670,0.339323,0.801877,0.135906,0.207398,0.192186,-0.309547,-0.462672,-0.819724,-0.147063,-0.039843,-0.236073,-0.580393,-0.354703,-0.571198,-0.641409,-0.412079,0.629984,0.022813,-0.177911,0.131067,0.415429,0.356303,0.436399,0.513887,-0.441536,-0.050695,0.147170,-0.290040,-0.318988,0.067289,0.086313,-0.356029,-0.445857,0.420878,0.232123,0.394650,0.583096,-0.514077,-0.177452,-0.138180,0.360845,-0.329441,0.128093,0.306995,0.248160,0.152356,-0.056857,0.520051,-0.273785,0.154182,0.076563,-0.333189,-1.173649,-0.306505,0.191633,0.345046,-0.892206,0.626383,0.221856,-0.293672,0.159543,-0.465997,-0.027614,0.540364,-0.026570,0.393011,-0.591807,0.189451,-0.653118,0.271881,0.787814,-0.004332,-0.277982,0.203860,-0.687882,-0.587151,-0.000245,-0.374048,-0.661372,-0.792985,0.455266,0.158073,-0.080238,0.545180,-0.610875,0.193860,0.074947,-0.726145,-0.013040,-0.557222,0.223774,-0.539480,-0.253731,-0.709293,-0.176212,0.200164,-0.008111,-0.549112,1.329084,-1.113538,-0.094478,0.571013,0.422903,-0.725272,0.697733,0.258146,0.249274,0.071386,-0.435833,0.026710,0.183262,0.381338,0.233210,0.237566,-0.002371,-0.194796,0.013384,0.910350', '27602116', '24284209', '30163500', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482051', '致命拜访', '剧情', '一艘太空船在华盛顿附近的小镇坠毁，人们一觉醒来，发现身边的人变得冷漠而陌生。精神科医生卡罗尔（妮可•基德曼 饰）和助手本（丹尼尔•奎格 饰）几经周折，发现这种变化是因为感染了外星病毒。灾难不可控制的蔓延，感染的人越来越多，他们占领城市，设置隔离区，想把人类变成没有情感的怪物，卡罗尔带着儿子奥利弗开始逃亡，她惊奇地发现奥利弗正是拯救人类的希望。©豆瓣', '妮可·基德曼', '奥利弗·希施比格尔', 6.6, 18436, 'tt0427392', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p478670694.jpg', 1, 8.9, 54.8, 28.6, 6.7, '0.452986,-0.165412,-0.749298,0.435576,-0.329847,0.030253,1.142519,-0.140248,-0.547108,-0.132597,0.215458,0.685995,-0.274092,0.214530,0.312302,0.214865,-0.535707,-0.183110,-0.162580,-0.185751,-0.374181,-0.388020,-0.538293,-0.636159,0.305394,-0.787704,0.549458,0.397980,-0.384897,0.549392,-0.073273,0.299610,-0.087105,0.697443,-0.058691,0.051154,-0.194604,-0.371710,0.066967,0.199058,-0.078034,0.072680,-0.166042,0.419296,-0.246572,0.335739,0.830064,-0.137805,-0.193775,-0.519968,0.285824,-0.218615,0.057091,-0.253030,0.347655,-0.008463,-0.139982,-0.215704,-0.029921,-0.208758,0.124933,0.223200,-0.334775,0.286776,-0.028107,0.569041,-0.204407,0.115449,-0.039903,0.028096,0.002046,-0.392764,0.146558,0.284557,0.149463,0.507122,-0.049355,0.130979,-0.631164,-0.157954,0.544354,-0.563241,-0.520716,0.401477,-0.407859,-0.607301,-0.103004,-0.206302,-0.544853,-0.080203,0.136414,0.199115,-0.435671,0.385372,-0.600116,-0.114445,-0.243512,-0.453759,-0.234364,-0.162137,-0.157906,-0.708571,-0.094817,-0.081467,-0.093864,0.173460,-0.231079,-0.262577,0.674005,-0.686726,0.307340,0.687882,0.504609,-0.458699,0.522535,-0.273985,-0.210104,-0.350127,-0.250401,0.411819,0.007133,0.449679,0.151365,0.172396,-0.130096,0.053461,-0.228499,0.480354', '20451118', '3005387', '1316693', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482055', '少年汉尼拔', '剧情', '汉尼拔（加斯帕德·尤利尔）的童年之初充满明媚与温馨，可爱的妹妹就像他的小尾巴，是他最爱的亲人。然而战争带走了一切，他的父亲、母亲还有他的家园。可是这仅仅是噩梦的开始，真正的毁了他一生的是妹妹的死——残忍的德军，吃了他的妹妹。妹妹的死成了汉尼拔永远的梦魇，妹妹的脸庞和声 音常常在他的梦里出现。汉尼拔决定去寻找他最后的亲人，叔叔的妻子，他的婶婶，一个神秘的东方女人，紫夫人（巩俐）。紫夫人教会了汉尼拔搏击的技术，也让他见识到东方世界生吃文化的精髓。汉尼拔似乎找到了走出童年阴影的出口，他开始杀人，吃人，在血腥中得到灵魂的暂时安宁。杀害妹妹的仇人，一个接一个凄惨的死去。汉尼拔和紫夫人之间也渐渐产生若有若无的情愫，可是此时，灵魂深陷泥沼的少年汉尼拔还留下什么来爱呢？©豆瓣', '加斯帕德·尤利尔', '彼得·韦柏', 7.4, 87162, 'tt0367959', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p613252076.jpg', 0.7, 4.3, 35.4, 41, 18.5, '0.119987,0.170973,-0.611924,0.742563,-0.437123,-0.452473,1.065059,0.130655,-0.631713,0.028324,0.212227,0.815237,0.082882,0.437641,0.108000,0.423882,-0.016697,-0.595863,-0.039334,0.105158,-0.207254,-0.352559,-0.182705,-0.284838,0.116569,-0.394058,0.581275,0.206378,0.017446,0.148420,0.104743,0.031482,-0.072755,0.749456,-0.261516,0.325352,-0.245487,-0.105872,-0.287256,0.182471,0.222903,0.056007,-0.090223,0.297535,-0.331335,0.394470,0.544518,-0.342516,-0.048820,-0.213486,0.375289,-0.424294,-0.115588,0.196076,-0.057039,-0.265880,0.244192,0.197079,-0.091763,-0.209163,-0.016029,0.190001,-0.654544,-0.063201,0.067870,0.154261,-0.610260,0.562970,-0.111087,-0.014190,0.334150,-0.308187,0.493527,0.057553,-0.150020,0.393617,-0.434844,0.020371,-0.580248,0.326936,0.748424,-0.162849,-0.137284,0.352177,-0.200867,-0.464020,-0.123261,-0.323326,-0.542169,0.128740,0.210503,-0.067272,-0.403984,0.302972,-0.722063,-0.178375,-0.081046,0.015877,-0.004101,-0.762358,-0.132091,-0.052781,-0.277016,-0.521094,-0.468923,0.004492,0.018434,-0.321020,0.736624,-0.825840,0.306691,0.563805,0.220527,-0.235503,0.562295,0.183954,-0.082901,-0.094047,-0.158704,0.543082,-0.017602,0.231206,0.176472,0.358654,0.184789,0.312164,-0.456949,0.675612', '24756472', '4275444', '26884422', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482063', '一级戒备', '动作', '彼得·加里森（迈克尔·道格拉斯 Michael Douglas 饰）是美国白宫的一名特工以及第一夫人的贴身保镖。20年的特工生涯以及当年为总统挡下一枪的事迹都令他毫无疑问地成为特勤局里的明星。然而彼得万万没有想到的是，有一天他也会成为追捕对象。彼得接到消息说白宫内部混入了纳粹分子，暗杀总统的阴谋在酝酿，但掌握线索的特工查理随后却被残忍杀害。行事干练的特工大卫（基弗·萨瑟兰 Kiefer Sutherland 饰）和新手马琳（艾娃·朗格利亚 Eva Longoria 饰）受命负责此案，并对所有特工一一测谎，然而彼得却未能通过，他与第一夫人的暧昧关系也开始在局里流传，阴差阳错之间，彼得被认为就是那名预谋暗杀者。然而当所有人都竭力追捕彼得之时，真正的杀手正一步步向总统逼近。为了保护总统，逃亡中的彼得唯有说服大卫和马琳共同缉凶，才有可能扭转局面……©豆瓣', '迈克尔·道格拉斯', '克拉克·约翰森', 6.2, 6133, 'tt0443632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p797847014.jpg', 1.4, 11, 65.2, 18.7, 3.7, '0.202968,-0.182920,-0.574816,0.619945,-0.104740,-0.226892,0.541371,-0.063489,-0.751488,-0.543596,0.541556,0.651497,-0.114700,-0.247240,0.607363,-0.078680,-0.457915,-0.970554,-0.194867,-0.194048,-0.112648,-0.580963,-0.454035,-0.251210,-0.028191,-0.360434,0.653757,0.072252,-0.219109,0.413846,0.447100,0.651657,-0.047030,0.417259,0.123997,-0.251926,0.632301,-0.443158,-0.426152,0.208439,0.120490,-0.356856,-0.172638,0.230479,-0.127782,0.540160,0.153381,-0.360768,0.017744,-0.150171,0.088361,-0.436686,0.059080,0.166306,0.553031,0.087425,0.107383,0.620030,-0.020579,0.016962,0.121684,0.026421,-0.957900,0.068565,0.142461,0.266618,-0.462274,0.066103,-0.399082,0.174133,0.176483,-0.227634,0.200640,0.303651,0.237136,0.203007,0.015489,0.165500,-0.556046,-0.019467,0.564595,-0.088513,-0.226542,-0.062019,0.055437,-0.411250,0.087749,-0.306833,-0.306009,0.040897,0.160042,0.017536,-0.039775,0.374191,-0.322180,-0.163044,-0.614820,-0.152986,-0.025952,-0.411033,0.048009,-0.812806,-0.095555,-0.128870,-0.213014,0.081602,0.046907,-0.228734,0.551815,-0.861749,0.325815,0.560861,0.045849,-0.463346,0.552955,0.256013,0.170556,-0.244686,-0.308870,0.173589,0.514642,0.352745,-0.014685,0.210391,0.055531,-0.652856,-0.000774,0.004230', '1307442', '25723905', '1793491', '1301161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482072', '穿普拉达的女王', '剧情', '初涉社会的安德丽娅•桑切丝（安妮•海瑟薇饰）来到了著名时尚杂志《RUNWAY》面试，以聪明得到了主编米兰达•普雷斯丽（梅利尔•斯特里普）的特许，让她担任自己的第二助理。开始的时候安德丽娅感到十分委屈，就算自己多努力工作也无法得到赞赏，经一位老前辈的指点便重新改造自己。工作越来越顺，甚至取代了第一助理在米兰达心中的地位，决定带着这个聪明的女孩前往法国。可安德丽的改变让她失去了男友及朋友的爱，令她非常矛盾。到达法国后，她得知了米兰达的地位不保了，没想到米兰达竟然牺牲自己多年的好搭档保住了自己的地位，此事令安德丽娅深感失望，有了抽身离去的想法，到底安德丽娅会何去何从？©豆瓣', '梅丽尔·斯特里普', '大卫·弗兰科尔', 8.2, 670587, 'tt0458352', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p735379215.jpg', 0.2, 1, 18.4, 51.4, 29, '0.176944,0.217035,-0.849139,0.827271,-0.161749,-0.598996,0.177418,0.181620,-0.423733,-0.445336,0.219287,0.908293,-0.152537,0.339083,0.398339,0.016678,-0.235984,-0.508883,0.049920,-0.272730,-0.290507,-0.601730,-0.310034,-0.314082,-0.198639,-0.300156,0.737042,0.049942,-0.083894,0.256320,0.223290,0.239100,0.464143,0.599098,-0.066322,0.270434,0.212180,-0.069480,-0.112930,0.188625,0.533525,-0.160282,-0.050945,0.395247,0.154701,0.396857,0.459807,-0.212780,-0.349581,0.063789,0.572384,-0.402794,0.185001,0.131596,0.123441,-0.028149,-0.218439,0.128035,-0.642904,0.114667,0.002490,0.023950,-0.832402,-0.071446,0.184799,-0.037754,-0.849910,0.085384,-0.290737,-0.095908,0.162603,-0.362061,0.047280,0.433778,0.057147,0.337240,-0.063009,0.220728,-0.322046,0.005599,0.703644,0.019363,-0.247800,0.202353,-0.196355,-0.415193,0.007279,-0.383648,-0.426219,-0.135289,0.278344,0.289350,0.166057,0.218426,-0.249428,-0.248483,-0.430597,-0.185471,0.125515,-0.457996,0.101033,-0.231911,-0.272741,-0.240447,-0.338743,-0.253986,-0.023104,-0.485126,1.014235,-1.022206,-0.011290,0.399649,0.235648,-0.958666,0.539419,0.206322,0.205700,-0.355338,-0.137357,0.463442,-0.142226,0.156966,0.184699,0.247998,-0.121119,-0.398451,-0.290131,0.409688', '1877596', '30163500', '27602116', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482075', '我的超级前女友', '喜剧', '俗话有云：最毒妇人心。得罪女友的后果常常会非常严重，更何况片中可怜的马特（卢克·威尔逊 Luke Wilson饰）冒犯的是超人女朋友。其实，马特和女超人珍妮（乌玛·瑟曼 Uma Thurman饰）的恋爱故事也开始得算是浪漫，但是马特却慢慢发现这个新女友的的超人面目。她爱闹脾气，占有欲强，霸气十足，让马特望而生畏。马特果断的和珍妮分了手。本来马特以为可以喘口气了，却不料他的“灾难”才刚刚开始。珍妮凭借着自己的超能力，随时随地让马特栽进大坑。她想方设法让马特得不到一刻安宁，总是在生活和工作中屡屡出丑。更糟糕的是，马特正在萌芽的新感情也泡了汤，他尝到了得罪女超人的后果：丢了工作，也无法正常的生活。马特该如何收拾这个烂摊子，让珍妮手下留情……©豆瓣', '乌玛·瑟曼', '伊万·雷特曼', 5.6, 12699, 'tt0465624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2209593515.jpg', 5, 24.8, 57.1, 10.2, 2.9, '0.247167,-0.007214,-0.682277,0.486093,-0.428130,-0.417164,0.592577,0.184994,-0.629319,-0.147191,0.033751,0.693744,-0.071192,0.057045,0.052427,0.001300,-0.303016,-0.545214,0.060956,0.125733,-0.181177,-0.371772,-0.303425,-0.097987,-0.041132,-0.314620,0.294439,-0.071921,-0.334263,0.167132,0.294856,0.323126,0.395858,0.549339,-0.284099,0.006954,-0.047474,-0.099374,-0.201649,0.058436,0.446975,-0.127448,-0.033995,0.542018,0.103588,0.276741,0.439065,-0.238410,-0.376527,0.016200,0.485310,-0.397011,-0.063738,0.089862,0.067706,-0.403380,0.236841,-0.060937,-0.019442,0.022424,0.071196,0.110351,-0.805754,0.086449,-0.147712,0.045255,-0.565967,0.281886,-0.083550,-0.010820,0.228525,-0.071873,0.088930,0.208808,0.328385,0.380785,-0.166156,0.101029,-0.512692,-0.000558,0.523386,0.172839,-0.234070,0.643304,-0.276842,-0.381762,-0.035074,-0.323128,-0.485585,-0.107034,0.296913,-0.001890,-0.136435,0.262478,-0.424924,0.002781,-0.238330,-0.001102,-0.208209,-0.605051,-0.224921,-0.089122,-0.389731,-0.414377,-0.216133,-0.093498,0.012291,-0.335152,0.560049,-0.630323,0.206116,0.520869,0.030207,-0.503589,0.306747,0.408985,-0.125186,-0.152878,-0.132769,0.283747,-0.137620,0.057109,0.268219,0.380122,0.257176,-0.325317,-0.249631,0.619259', '1783461', '1304977', '25763555', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482077', '灵魂战车', '动作', '约翰尼·布雷泽（尼古拉斯·凯奇 饰）本是摩托车特级演员，当他发现父亲身患癌症之时，他与恶魔梅菲斯特签订了契约。他自己变身幽灵车神，为恶魔服务。对恶魔的要求言听计从的约翰尼，白天是星光灿烂的特级明星；夜间一身皮装、身体化为骷髅、身披布满刺钉的战袍，开动摩托车，替恶魔追捕那 些 穷凶极恶之人。但约翰尼渐渐发现，最大的恶魔便是梅菲斯特，他开始在正义与邪恶之间游走。爱人洛克希安妮（伊娃·门德斯 饰）令约翰尼鼓起勇气，他心中做出了一个决定。©豆瓣', '尼古拉斯·凯奇', '马克·斯蒂文·约翰逊', 6.7, 112639, 'tt0259324', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1551671396.jpg', 1.7, 9.9, 48.6, 29.4, 10.3, '0.070181,-0.055742,-0.447559,0.397993,-0.212535,-0.218237,0.922962,0.175004,-0.291547,-0.240200,0.638371,1.005758,-0.301080,-0.143791,0.403398,0.075429,-0.322716,-0.702330,0.072389,-0.061118,-0.073785,-0.230641,-0.182465,-0.190682,-0.076138,-0.479290,0.567925,-0.029362,0.183057,0.225283,0.308360,0.515925,-0.003983,0.280762,-0.114580,-0.282269,-0.002750,-0.518610,0.013280,0.223447,-0.043475,0.107872,-0.115842,0.408226,-0.419436,0.361956,0.589752,-0.468869,-0.093327,-0.569591,0.322150,-0.301606,0.195981,-0.235699,0.196897,0.176305,0.066949,-0.015215,0.315121,0.011107,0.182717,0.069787,-0.324262,0.145069,-0.191877,0.296171,-0.489868,0.162143,-0.335986,0.150084,0.284674,-0.324158,-0.078164,-0.125856,0.194850,0.312524,0.046590,0.054696,-0.597610,0.093321,0.298997,0.158870,-0.336216,0.332600,-0.346717,-0.468789,0.101568,-0.016350,-0.465571,-0.274836,0.145894,0.096962,-0.010000,0.514233,-0.798007,-0.228146,-0.500852,0.080740,-0.258015,-0.196932,-0.218293,-0.544514,-0.394716,-0.307690,0.014653,0.141444,0.030577,-0.311898,0.341346,-0.966774,0.206396,0.258098,0.276769,-0.120479,0.325804,-0.251211,0.139174,-0.094268,0.011095,0.370442,0.150942,0.318915,0.133411,0.086482,0.326290,0.021744,-0.221274,0.525379', '1296534', '1299556', '27006896', '30137576');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482079', '别惹蚂蚁', '喜剧', '想象下你是个在校没朋友，没人陪你玩，又被恶霸欺负的小孩？这是件多么可怕的事。在华纳兄弟出品的动画片《别惹蚂蚁》里的主人公就遇到这种状况。故事根据童话作家约翰·尼科尔(John Nickle)创作的同名儿童小说改编,讲述刚搬家的卢卡斯,在学校没朋友，又被邻居恶霸欺负，只好把怒气出在蚂蚁上,破坏他们的巢穴，不料蚂蚁起来报复，用一把神奇缩小枪，将卢卡斯变成蚂蚁般大小，并把他带回巢穴一同生活，经过这次，卢卡斯学会了宽容与同情，友情的真谛和欣赏和敬畏自然本身。©豆瓣', '朱莉娅·罗伯茨', '约翰·A·戴维斯', 7.2, 33902, 'tt0429589', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1096547573.jpg', 0.5, 3.6, 44, 40, 11.9, '0.747511,-0.378335,-0.566192,0.378922,-0.193648,-0.210420,1.011140,-0.110517,-0.265703,-0.093994,0.021451,0.655227,-0.406558,0.161283,-0.154215,-0.160117,-0.355462,-0.591002,-0.170339,-0.091396,0.054894,-0.411905,-0.306933,-0.027819,0.082672,-0.122293,0.446886,-0.239032,-0.420473,0.254685,0.065245,0.190032,-0.007492,0.160057,-0.418933,0.225872,-0.075469,0.542395,0.038825,0.034724,0.107545,-0.051293,0.092335,0.082041,0.068377,0.023222,0.678685,-0.427060,-0.133653,-0.128898,0.299658,-0.185745,0.060041,0.033452,0.309324,-0.020534,0.214300,-0.197105,-0.079326,0.075847,0.081682,-0.351916,-0.732168,-0.037359,-0.006162,0.158220,-0.573762,0.380913,0.148193,0.097156,0.198980,-0.363301,0.224315,0.034654,0.367673,0.509484,0.043547,0.051501,-0.567373,0.259057,0.727124,0.022866,-0.083921,0.306205,-0.155494,-0.245688,0.065963,-0.357326,-0.419025,0.022045,0.409299,-0.143321,-0.608972,0.311425,-0.650122,-0.017166,0.065750,-0.039972,-0.012833,-0.554967,0.030491,-0.530897,-0.034872,-0.008180,-0.226887,-0.013113,0.372268,-0.443396,0.858332,-0.712082,0.240582,0.579911,0.318432,-0.346452,0.612217,-0.083574,-0.265742,-0.003271,0.158022,-0.064206,0.437779,0.285355,0.489158,0.468834,0.013463,-0.326496,-0.331629,0.614220', '21619567', '3005387', '2053515', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482080', '航班蛇患', '动作', '黑帮老大艾迪•金策划了一起凶杀案，被偶然路过的年轻人西恩•琼斯（Nathan Phillips 饰）目击。为了在法庭上成功指控这个作恶多端的黑社会头子，警方派出资深联邦密探尼维利•费恩（Samuel L. Jackson 饰）负责保护西恩，并将其从夏威夷护送至洛杉矶法庭。为避免证人遇害，尼维利采取声东击西的策略，与西恩偷偷乘上一架普通的红眼航班。然而这项绝密的计划被艾迪安排在警方的内奸获知，为了逃脱法律制裁，艾迪派出携带大量毒蛇的杀手登上飞机，一场离奇恐怖的血腥灭口案件就此展开……©豆瓣', '塞缪尔·杰克逊', '大卫·R·艾里斯', 6.2, 20193, 'tt0417148', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p643537929.jpg', 2.2, 14.3, 58.4, 20.4, 4.7, '0.359199,-0.078915,-0.586014,0.359791,0.219881,0.061823,0.385234,0.101882,-0.296418,-0.135894,0.495727,0.527583,-0.070846,-0.247178,0.523729,-0.173124,-0.670182,-0.465813,-0.022403,-0.256416,-0.318597,-0.730952,-0.169652,-0.454058,0.001362,-0.036932,0.472098,0.133888,-0.146008,0.534918,0.519228,0.614824,-0.296806,-0.018430,0.059543,-0.331304,0.283326,-0.520661,-0.425689,0.455518,-0.112196,-0.149100,-0.019788,0.016821,-0.023521,0.484692,0.642447,-0.367050,0.041651,-0.254080,0.185561,-0.599176,0.325218,0.013297,0.568545,0.181607,-0.355411,0.444837,-0.271377,-0.163654,0.096057,-0.007059,-0.880532,-0.092754,0.089773,0.089063,-0.261258,-0.208812,-0.389630,0.377804,0.171985,-0.072938,0.046886,0.552287,0.274298,-0.052191,0.177188,0.262668,-0.376588,-0.037675,0.574396,-0.194925,0.040727,-0.216114,0.104089,-0.306032,-0.040342,-0.260564,-0.082384,0.062739,0.600036,-0.482416,-0.042328,0.311564,-0.509854,-0.399742,-0.591787,-0.057623,-0.231583,0.000720,-0.043278,-1.072714,0.155630,0.301481,-0.268642,0.195345,0.143544,0.041436,0.311710,-0.409072,0.233372,0.877271,0.057770,-0.363290,0.102876,0.036249,0.349016,-0.248892,-0.449614,0.044476,1.002536,0.508200,0.162419,0.086955,0.020947,-0.206054,-0.084267,-0.065017', '6517421', '4014397', '2028645', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482086', '儿女一箩筐2', '喜剧', '拥有着12个孩子的欢乐家庭——贝克家族如今也难逃岁月出的难题。随着长女诺拉（派珀·佩拉博 Piper Perabo 饰）出嫁怀孕，孩子洛林又远赴纽约深造，身为家长的汤姆（史蒂夫·马丁 Steve Martin 饰）深感家庭聚会的时间将越来越少，今年假期也许是最后一个全员出游的机会，于是他和妻子凯特（邦尼·亨特 Bonnie Hunt 饰）精心策划了一个温内特湖畔的温馨旅行计划。然而汤姆万万没想到的是，他学生时代的宿敌吉米（尤金·列维 Eugene Levy 饰）竟然也带着自己的8个孩子来到了温内特湖消遣夏日。两个处处较劲的老爸，两个闹哄哄的家庭碰到一起，湖光山色瞬间变成火药味十足的战场，两家老小24口人全部出动，为了各自的“荣誉”，全力投入到这场鸡犬不宁、笑料百出的家庭大作战中……本片为2003年家庭喜剧《儿女一箩筐》续集。©豆瓣', '史蒂夫·马丁', '亚当·尚克曼', 6.9, 6392, 'tt0452598', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1399144558.jpg', 0.5, 5, 53.1, 30.9, 10.6, '0.125212,-0.054905,-0.659979,0.416485,-0.067282,-0.398459,0.585521,0.172990,-0.539589,-0.333323,0.151442,0.694255,-0.298574,0.414538,0.409693,-0.153673,-0.283909,-0.636023,-0.180973,0.044089,-0.019932,-0.387820,-0.084927,0.033746,-0.078672,-0.165693,0.408656,0.044261,0.360788,0.362570,0.294499,0.161099,-0.069437,0.104851,-0.197887,0.095650,0.128671,0.006596,-0.216749,0.262833,-0.096551,0.193686,-0.334942,-0.074822,0.149517,0.261831,0.850437,-0.071831,0.075227,-0.208494,0.391897,-0.177832,-0.202316,0.038299,0.400244,-0.195500,0.316376,0.194251,-0.055636,-0.031135,0.222283,-0.249747,-0.606826,0.347492,0.085708,-0.098162,-0.487804,0.512659,0.073458,-0.201207,0.028233,-0.240454,0.085224,0.427953,0.309270,0.372008,-0.369598,0.250449,-0.511788,0.137229,0.737432,-0.117431,-0.125577,0.175909,-0.473806,-0.191073,0.111459,-0.411556,-0.625813,-0.019354,0.253754,-0.121872,0.071638,0.435457,-0.634084,0.100003,-0.409636,-0.176382,0.275727,-0.439688,-0.059534,-0.628490,0.112293,-0.099044,-0.389279,0.265928,0.226649,-0.198549,0.774843,-0.441744,0.030983,0.481997,0.031788,-0.340749,0.611131,0.028783,0.463342,-0.166481,-0.067160,0.125677,-0.055053,-0.036972,0.125153,0.293277,-0.139326,-0.237926,-0.124581,0.415322', '3811356', '30162520', '26926321', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482089', '重振球风', '剧情', '肖恩（Dwayne Douglas Johnson）是少年监管所的管理员，每天都为少年犯之间的纷争而烦恼。在他看来这些少年犯在这样的监禁环境下根本无法洗心革面，他的工作毫无意义。在年迈母亲的鼓励下，肖恩决定用橄榄球改变孩子们的人生，将他们拉回正轨。尽管通过艰难的游说，肖恩终于说服高校赛季同意他带领少年犯参赛，但说服这些问题少年组成一只真正的队伍更加困难重重。肖恩用自己的强硬和对孩子们的信任打动了他们，组建了一只“野马队”。在他看来，帮孩子们找回失去的人生比赢得比赛更为重要。很快他们参赛了，一路风雨兼程，这只特殊队伍回取得怎样的成绩呢？©豆瓣', '道恩·强森', '菲尔·乔安诺', 7.9, 7085, 'tt0421206', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264253033.jpg', 0.2, 1.4, 24.4, 51.9, 22.1, '-0.011018,0.028625,-0.451656,0.392637,-0.363492,-0.295857,0.449978,-0.073743,-0.473283,0.017141,0.291038,0.580418,0.114430,0.278436,0.183957,-0.485827,-0.405511,-0.639554,0.032574,-0.094904,-0.372397,-0.545861,-0.274251,-0.288531,-0.088031,-0.183294,0.996201,0.014058,-0.201363,0.302169,0.208829,0.157635,0.302235,0.274152,-0.300314,-0.032110,-0.218052,0.102557,-0.239021,0.079991,0.038697,0.114486,-0.623145,0.197829,0.282740,0.302467,0.755485,-0.506499,-0.223536,-0.087942,0.264257,-0.493732,-0.073938,0.138790,0.196823,0.237580,-0.078967,0.231496,-0.182396,0.153416,-0.352853,-0.226156,-0.801079,-0.079614,0.098281,0.086226,-0.877210,0.270508,0.099049,-0.008761,0.303916,-0.306105,-0.058165,0.720585,0.142659,0.307105,-0.334064,0.061195,-0.533374,0.141907,0.918736,-0.055438,-0.344760,0.144687,-0.348324,-0.364205,-0.127677,-0.372214,-0.351526,-0.064078,0.091255,0.158320,-0.098063,0.084853,-0.388895,-0.119382,-0.044571,-0.419309,-0.058744,-0.894854,0.167005,-0.497085,0.067402,-0.158850,-0.249684,-0.015865,0.057921,-0.306329,0.993872,-0.851513,0.056065,0.462379,0.212330,-0.730568,0.457676,0.079752,0.466348,-0.278463,-0.211942,0.195598,0.065456,0.346566,0.222361,0.385087,-0.046235,-0.005910,-0.404233,0.464986', '1877596', '30163500', '30345227', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482099', '神枪手之死', '剧情', '杰西•詹姆斯（Brad Pitt 布莱德•彼特 饰），南北战争时期最著名的强盗，他与兄长组建的詹姆斯帮伙同其喽罗犯下无数宗抢劫案，即使防卫再出色的银行也难逃他们的魔掌。杰西凭借其出神入化的枪法和经历成为平民百姓心中的传奇人物。人过中年杰西逐渐厌倦颠沛流离和与政府捉迷藏的生活，手下的喽罗或死或伤，兄长也因杰西的坏脾气选择离开。新加入“詹姆斯帮” 的懦弱男孩罗伯特•福特（Casey Affleck 凯西•阿弗莱克 饰）视杰西为超级偶像，与渐感疲惫的杰西隐居乡间。然而经过多年的相处，罗伯特却最终成为这名传奇侠盗生命之闸的掣动者……©豆瓣', '布拉德·皮特', '安德鲁·多米尼克', 7.6, 22765, 'tt0443680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p779837603.jpg', 0.7, 4, 30.6, 44.4, 20.3, '0.183546,-0.303950,-0.316532,0.464152,-0.060675,-0.444167,0.660822,0.053174,-0.438480,-0.526555,0.303497,0.953497,-0.098666,0.130793,0.337309,-0.237242,-0.144865,-0.726874,-0.054633,0.045304,0.137862,-0.135018,-0.303070,-0.201412,-0.250253,-0.325463,0.910689,-0.057482,0.009851,0.386390,0.191698,0.617618,-0.128072,0.059857,-0.213379,-0.051274,0.007025,-0.166443,-0.602133,0.091286,-0.067697,-0.062932,0.037602,-0.064977,-0.068175,0.223095,0.425227,-0.230817,-0.008650,-0.299700,0.252465,-0.207391,-0.040537,0.104447,0.271211,-0.023354,0.269463,0.305366,0.123848,-0.036927,-0.010842,-0.106879,-0.873417,0.102693,0.353703,-0.103238,-0.559454,0.176220,-0.236676,-0.152518,0.020236,-0.175467,-0.132096,0.286880,0.257092,0.159038,-0.059617,0.101704,-0.324192,0.051129,0.609909,-0.063905,-0.288837,-0.116783,-0.180374,-0.380395,0.218404,-0.790935,-0.453966,-0.072063,0.150931,-0.191651,-0.033479,0.580180,-0.494614,0.033650,-0.422666,0.026352,0.053445,-0.150060,0.014779,-0.615779,-0.037646,-0.487276,-0.338310,-0.156569,0.212141,-0.192800,0.615592,-0.762702,0.297875,0.195915,0.238737,-0.471525,0.504260,-0.022013,0.279927,-0.101754,-0.208300,0.635173,0.261978,0.256756,0.031127,0.084331,-0.030997,-0.164422,-0.001325,0.356912', '24875409', '4301278', '25880986', '5308201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482101', '美好的一年', '剧情', '故事发生在风光惹人醉的法国普罗旺斯。伦敦证券师麦克斯（罗素·克劳 Russell Crowe 饰）作为遗产继承人的身份来到这里，虽然事业陷入低谷，但过世的叔叔留下的一大片葡萄园和一幢大房子，足够他卖出后获得一笔可观的收入。他在这里住下的期间，与当地一个咖啡店女子芳妮（玛丽昂·歌迪亚 Marion Cotillard 饰）相谈甚欢。原来，童年时候芳妮曾经是麦克斯前来叔叔家时的玩伴。芳妮为麦克斯打开了一扇大门，让他重拾渐忘的往事，不再满脑子都是数字和金钱的游戏。麦克斯让心灵在这片美丽的土地上尽情呼吸，以往为名为利的生活渐渐退去。这时，叔叔的私生女（艾比·考尼什 Abbie Cornish 饰）从加州前来造访，并且有着明确的目的：得到葡萄园的继承权，麦克斯刚刚平静下来的生活是否又开始了名争暗斗，抑或在普罗旺斯这个美好的地方，美好的日子天天上演？©豆瓣', '罗素·克劳', '雷德利·斯科特', 7.7, 23259, 'tt0401445', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173839322.jpg', 0.3, 2.5, 29.6, 46.6, 21.1, '0.211551,0.354891,-0.724469,0.612432,-0.077536,-0.380374,0.869620,0.248927,-0.537412,-0.319103,0.039262,0.839763,-0.090731,0.397983,0.390115,0.285607,-0.338704,-0.563638,0.071813,-0.276621,-0.108964,-0.426270,-0.258457,-0.119007,-0.112979,-0.368296,0.573555,0.204481,-0.018695,0.458024,-0.003308,0.298387,-0.021723,0.162207,-0.217618,-0.063188,0.195497,0.250137,-0.530215,0.150434,0.004560,-0.102133,-0.244085,-0.055151,0.125662,0.179612,0.688852,-0.113511,-0.207420,0.142605,0.276848,-0.005908,0.009833,-0.013560,0.175365,-0.010485,0.293724,0.271250,-0.346190,-0.059528,0.048264,-0.223702,-0.585976,-0.060742,0.201136,0.013706,-0.501484,0.457068,-0.184797,-0.123770,0.119481,-0.397525,0.192640,0.518677,0.236561,0.467039,-0.276254,0.148528,-0.564473,0.132329,0.699011,-0.011988,-0.087419,0.396378,-0.400504,-0.313817,0.005511,-0.054974,-0.427092,-0.060601,0.259768,0.015068,-0.026115,0.306483,-0.765352,0.004036,-0.221255,-0.499546,0.284913,-0.408288,-0.374277,-0.562921,-0.297767,-0.242263,-0.157586,-0.014026,0.062341,-0.310429,0.671359,-0.765573,0.362958,0.288622,0.381516,-0.198543,0.865788,-0.082027,0.115530,-0.152107,-0.158029,0.265466,0.097982,0.214764,-0.048119,0.018703,-0.214028,-0.058249,-0.557252,0.696376', '3055049', '1296534', '2334814', '6858739');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482102', '咒怨2(美版)', '悬疑', '对于奥布莉（爱波·塔布琳 Amber Tamblyn 饰）来说，姐姐凯伦（莎拉·米歇尔·盖拉 Sarah Michelle Gellar 饰）的死充满了疑点。两年前，凯伦远赴日本求学，不久之后奥布莉一家就收到了凯伦被关入精神病院的噩耗，而现在，曾经善良美丽的姐姐已经变成了一具冰冷的尸体。奥布莉坚信其中必有古怪，因此，她和专门报道灵异事件的记者伊森（陈冠希 饰）联手，对老房子中的咒怨展开了调查。同一时间，在世界各地，发生了数件离奇死亡事件，而死者与咒怨均有着千丝万缕的关联。咒怨果真这样无孔不入吗？究竟又是谁在背后操纵着这股强大的力量呢？©豆瓣', '莎拉·米歇尔·盖拉', '清水崇', 6.4, 15599, 'tt0433386', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2215544253.jpg', 3, 14.6, 52, 21.8, 8.6, '0.268643,-0.203124,-0.804080,0.448635,0.178259,0.055561,0.862958,-0.055520,-0.529505,-0.211147,0.231376,0.614756,-0.278413,0.048673,0.144942,0.112544,-0.159499,-0.638283,-0.118347,-0.488471,-0.412893,-0.529546,-0.480062,-0.019018,0.213924,-0.367243,0.331265,0.136016,0.092508,0.505510,0.341886,0.675203,-0.421569,0.353929,0.021147,0.004034,0.221915,0.293887,-0.094873,0.161989,0.270785,-0.291253,0.039982,0.201572,-0.148877,0.352605,0.493487,-0.380542,-0.216390,-0.116618,0.408801,-0.166039,-0.018274,0.322769,0.474216,0.086230,0.395259,0.377346,-0.334686,-0.334993,0.158500,0.116651,-0.584612,0.107627,0.245366,0.255847,-0.327361,0.249943,-0.050118,-0.019308,0.083863,-0.249743,0.303298,0.241195,0.156042,0.453480,0.064782,-0.099458,-0.427451,-0.135611,0.606205,-0.039801,-0.291541,0.181778,-0.099960,-0.330359,-0.313691,-0.048359,-0.366577,0.297475,0.333799,0.108332,-0.198943,0.515433,-0.652062,-0.117256,-0.339289,0.193627,-0.191095,-0.072221,-0.174215,-0.561465,-0.355867,-0.277626,-0.191287,-0.024592,0.260617,-0.134051,0.622934,-0.659889,0.453506,0.447898,0.269534,-0.508898,0.361392,-0.067168,0.045796,-0.005887,-0.106844,0.160487,0.159331,0.298674,0.245366,0.306849,0.143812,-0.311707,-0.308976,0.462345', '1300958', '1296534', '1301686', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482107', '怪兽屋', '动画', '12岁的DJ（米切尔•莫索 Mitchel Musso 饰）是个爱幻想的家伙。他整天觉得对面街的老头子的那座荒废的老屋阴森怪气，附近的一些物体经常不翼而飞。经过详细观察，DJ发现原来失踪的物品都被老屋吃了，那么老头子失踪的老伴应该都是被吃了，DJ心想。不过大人们甚至伙伴们都觉得DJ在异想天开。万圣节前的一天，DJ和伙伴乔德（山姆•勒纳 Sam Lerner 饰）不小心将篮球扔到了老屋门前，他们眼睁睁的看着一股神秘力量将篮球吸进了屋内，就连新搬来的伙伴珍妮（史宾塞•洛克 Spencer Locke 饰）也差点成了老屋的美味。伙伴们这下相信了DJ的说法，不过大人们却依然觉得他们在扯蛋。为了阻止老屋继续吃人作恶，伙伴们决定携手与它作战到底。©豆瓣', '米切尔·莫索', '吉尔·克兰', 7.3, 44955, 'tt0385880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p621350618.jpg', 0.5, 3.7, 38.7, 43.5, 13.7, '0.327470,-0.304577,-0.676052,0.184849,-0.332451,-0.353128,0.687203,0.028362,-0.535691,-0.135725,-0.010025,0.681457,-0.280755,0.251644,0.203769,-0.037267,-0.248433,-0.524877,-0.011118,-0.287910,-0.228411,-0.269260,-0.233854,-0.379027,0.001982,-0.069127,0.203280,-0.012038,0.065923,0.256304,0.167165,-0.075222,0.068231,0.359112,-0.254024,0.118801,0.095337,-0.065416,0.111446,-0.160598,-0.007546,-0.145375,-0.003642,0.091872,0.299008,0.222279,0.563297,-0.236941,-0.334947,-0.164469,0.013489,-0.079843,-0.024429,0.393974,0.306611,0.111774,0.121340,-0.041136,-0.149506,-0.109633,0.207987,0.064629,-0.557375,0.216403,0.042572,0.106420,-0.685986,0.502301,0.193811,-0.218102,-0.048741,-0.511181,0.492286,0.067800,0.272632,0.441669,-0.134315,-0.097995,-0.600474,-0.045523,0.576668,-0.282110,0.036814,0.284931,-0.011411,-0.227676,-0.018740,-0.044920,-0.347327,-0.094051,0.114548,0.121043,-0.295595,0.192337,-0.704404,0.061966,0.056037,-0.381987,-0.046915,-0.413953,-0.343773,-0.423548,0.007654,-0.276112,-0.145276,0.288231,0.003788,-0.150118,0.709904,-0.378174,0.187378,0.608738,0.390573,-0.299232,0.669620,-0.159099,0.089695,0.051543,-0.188771,-0.032064,0.237209,0.314344,0.568282,0.556758,-0.086468,-0.254399,-0.303703,0.430241', '1309101', '3055049', '30162520', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482297', '彩虹老人院', '剧情', '少女沙织（柴崎幸 Kou Shibasaki饰）与母亲相依为命，父亲卑弥呼（田中泯 Min Tanaka饰）因为是一名同志而抛弃母女二人，离家多年。沙织一直生活在破碎的家庭阴影中，然而母亲也因癌症离她而去。一天，一位神秘男子春彦（小田切让 Jô Odagiri饰）找到沙织，告知她的父亲即将不久于人世，希望她能到老人院里当看护，陪卑弥呼走完最后的日子。沙织一直不肯原谅父亲，但是为了偿还母亲因病欠下的债务，她还是来到了老人院当看护。起初，沙织完全无法接受老人院的这些同志老人，更意想不到，面前这位英俊帅气的男孩春彦居然是自己父亲的现任爱人。这部散发着幽幽感伤之情却不乏温情满满的同志题材影片，用细腻柔情的笔触描画着这份看似不可原谅的禁忌爱情。影片中满头银发的老同志们也为本片增色不少。©豆瓣', '小田切让', '犬童一心', 7.8, 9758, 'tt0451123', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1709959208.jpg', 0.5, 2.5, 25.6, 48.5, 22.8, '-0.194249,0.051986,-0.450783,0.502020,-0.306594,-0.574457,0.859217,0.083393,-0.530881,-0.576539,0.296787,0.699283,0.064531,0.689499,0.195120,0.003452,-0.181717,-0.394750,-0.137994,-0.024508,-0.066947,-0.195946,-0.193577,0.048878,-0.462580,-0.264950,0.907637,0.260973,0.041810,0.356704,0.237292,0.333932,-0.337241,0.254820,-0.151655,-0.050088,-0.129068,0.109418,-0.356766,0.087823,0.270277,-0.324825,-0.222476,0.203883,-0.198115,0.234820,0.546922,-0.114470,-0.277875,-0.157939,0.394954,-0.049746,0.135102,0.280831,0.089786,0.024353,0.476172,0.408855,-0.317891,-0.059952,0.071579,-0.269227,-0.444849,-0.058590,0.074552,0.234705,-0.453652,0.374435,-0.171777,-0.104586,0.294413,-0.393258,0.142169,0.007136,0.157535,0.564592,-0.542713,0.161653,-0.268607,0.355075,0.504631,0.023132,0.015520,0.416679,-0.529735,-0.219176,0.030419,-0.173501,-0.704296,0.260458,-0.114112,0.284658,-0.047823,0.199827,-0.236721,-0.147635,-0.261502,0.067592,0.051597,-0.446325,-0.001559,-0.284720,-0.210903,-0.534309,-0.375747,0.105025,0.145368,-0.222626,0.770572,-0.488537,0.328279,0.231146,0.107851,-0.433041,0.645438,0.259047,0.017048,-0.173914,-0.190318,0.640567,-0.110598,-0.094449,0.180022,0.033360,-0.152487,-0.018673,-0.344910,0.216516', '1296992', '25738406', '6973376', '3732800');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482354', '午夜凶铃：凶铃再现', '悬疑', '拥有不堪回首过去的安藤满男（佐藤浩市 饰）一早接到同事宫下（鹤见辰吾 饰）的电话，得知医科大读书时的好友高山龙司（真田广之 饰）意外死亡。安藤为高山的尸体进行解剖，排除了自杀和他杀的原因，发现好友死于心肌梗塞。在警方的安排下，他见到了高山的情人高野舞（中谷美纪 饰），却听到了朋友因一卷录像带而丧命的说辞。安藤自然不会相信虚无缥缈的臆测，谁知几天后高山的前妻浅川玲子（松岛菜菜子 饰）和年幼的儿子也在车祸中死亡，损毁的车中破碎的录像机引起安藤的怀疑。未过多久，浅川的上司吉野（松重丰 饰）登门拜访，讲述了关于贞子和诅咒录像带的一切真相。安藤的命运由此发生改变……本片根据铃木光司的同名原作改编。©豆瓣', '佐藤浩士', '饭田让治', 5.9, 6019, 'tt0134928', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1002358605.jpg', 6.2, 21.8, 50.2, 13.9, 8, '0.169402,-0.177196,-0.499464,0.346134,0.031804,0.058035,0.765181,0.078696,-0.328874,-0.517726,0.239618,0.653289,-0.267893,0.291303,0.539924,-0.176470,-0.283936,-0.596620,0.084694,-0.124813,-0.248318,-0.574251,-0.052272,-0.198219,-0.039585,-0.196728,0.762588,0.087748,-0.124343,0.544272,0.216373,0.318611,-0.338992,0.159264,0.239033,0.352373,-0.239839,0.227610,-0.250501,0.134377,-0.038535,-0.380506,0.013236,0.172940,-0.073547,0.403378,0.484252,-0.216617,-0.456608,-0.107239,0.522205,-0.158965,0.082199,0.059273,0.536144,0.075791,0.082552,0.437084,-0.572884,-0.115051,0.159784,0.330671,-0.344761,-0.267043,0.182912,0.324546,-0.204828,0.282527,-0.126298,-0.114198,0.138515,-0.211801,0.214472,0.184301,0.437309,0.337421,-0.279447,0.044271,-0.235516,0.218100,0.405441,-0.111612,-0.029687,0.143724,0.205411,-0.306717,-0.260598,0.019482,-0.392426,0.379276,0.235250,0.260150,-0.303418,0.186136,-0.215195,-0.540688,-0.025688,-0.204159,0.103136,-0.159285,-0.286368,-0.634280,-0.069882,-0.124133,-0.281090,-0.056881,0.109630,-0.247089,0.520317,-0.673205,0.244605,0.266237,0.022073,-0.230762,0.258838,0.013295,-0.184792,-0.150917,0.210988,0.295550,0.342653,0.266515,0.154905,0.103606,0.008410,-0.217786,-0.448887,0.095009', '25723905', '25727519', '20274039', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482366', '鬼娃娃花子', '惊悚', '坂本拓也（井上孝幸饰）上的本町小学附近有另一所小学，不知为何接连发生了小学生的连续杀人事件，消息传到本町小学，学生之间议论纷纷。 　　拓也的妹妹—夏美（前田爱饰）的班上同学，问钱仙凶手是谁，钱仙的回答是「花‧子」。小朋友们直觉想到“鬼娃娃花子”。“鬼娃娃的花子”是一个传说 住在厕所裏的幽灵，而根据钱仙的预言，下一个受害者正是夏美，并且“花子”明天就会现身…… 　　夏美立刻跑去拓也的班上，找拓也求助，没想到拓也不当一回事，把夏美赶回去。夏美只好和同学浩志一起回家，途中到一位非常漂亮的女孩，向他们问到本町小学的路。 　　这名美少女叫作水野芽子（河野由佳饰）。第二天刚好转学进入拓也的班上，成绩优秀的芽子，不久在班上即大受欢迎，有一次，芽子被班上的加奈子与小绿撞见从谣传的“花子”出现的厕所裏出来，从此竟被同学们怀疑是“花子”，只有拓也一直护着她。 　　在这之后，有一天，拓也与芽子一起打扫饲养著山羊的小屋。在拓也为了拿学级日志到离开到职员办公室时，加奈子和小绿正好在走廊。突然她们看到眼前出现一大片血迹，吓得拔腿就跑，没想到混身是血，拿着镰刀的芽子，就站在前面……', '河野由佳', '松冈锭司', 6.2, 13790, 'tt0114688', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1717768683.jpg', 3.9, 16.9, 52.6, 20.5, 6.1, '0.396977,-0.188942,-0.659153,0.180969,-0.100961,-0.394677,0.494012,-0.044334,0.014992,-0.284882,0.046437,0.585978,-0.485434,0.557427,0.301634,0.080959,-0.236548,-0.579210,-0.217451,-0.493229,-0.473529,-0.222719,0.202776,-0.120622,0.008617,-0.311141,0.359234,-0.132188,-0.193623,0.473290,0.398962,0.201298,-0.239524,0.331468,-0.251967,0.083116,-0.099886,0.106908,0.314732,0.242892,-0.089216,-0.185379,-0.401421,-0.122149,0.286513,0.232114,0.582882,-0.108570,-0.202310,0.159256,0.234531,-0.246147,-0.253778,-0.023724,0.806948,-0.332512,0.247834,0.058547,-0.140397,0.071124,0.125468,-0.166440,-0.342157,0.270390,-0.070387,0.279856,-0.436091,0.303495,0.151750,-0.169803,0.434619,-0.434292,0.354389,0.186481,-0.070535,0.231378,-0.309404,0.052302,-0.501316,-0.151115,0.505011,0.063985,0.173023,0.181875,0.164512,-0.236822,-0.036030,0.078118,-0.038508,0.158398,0.222932,-0.167988,-0.440139,-0.262777,-0.404903,-0.172815,-0.194414,-0.128756,0.225470,-0.220936,-0.469004,-0.496074,0.268935,-0.246519,-0.391809,0.341584,0.141539,-0.221970,0.810140,-0.859119,0.034868,0.320858,0.261610,-0.178104,0.563036,-0.133642,-0.277833,0.087378,-0.282657,-0.205730,0.509904,0.703879,0.181357,0.511067,-0.121479,-0.243174,-0.351494,0.182201', '1292219', '25912924', '2245683', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482495', '富贵再三逼人', '喜剧', '在加拿大领取了3千万奖金的骠叔（董骠 饰）一家，回到了香港居住。从未见过这么多钱的一家人竟然决定从银行取出了所有的现钞。所谓财不可以露眼，他们这么高调的行为引起了劫匪的注意。劫匪抢走了他们所有现钞，劫匪所开的车突然爆炸，钞票也全部被烧毁。骠叔感叹自己又变成了穷人。但他们的运气还在，随即他们发现领取款项的收据连同钞票一起被烧掉了，银行只能当作骠叔一家还没有领取3千万的巨款，让他再次取款。他们又再一次成为了富人。真是时来运到，骠叔的女儿们同时在澳门赢得了300多万的奖金。©豆瓣', '董骠', '冼杞然', 7.1, 12597, 'tt0097396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2445941596.jpg', 0.7, 4.9, 47.9, 33.6, 12.9, '0.160811,-0.015019,-0.579714,0.153039,-0.454061,-0.562100,0.541939,0.180430,-0.093159,0.191699,0.343244,0.883298,-0.162879,0.045862,0.221008,-0.010583,-0.099982,-0.584026,-0.218188,-0.513171,-0.216540,-0.227150,-0.102449,-0.224490,-0.209935,-0.067618,0.213972,0.145379,-0.195925,0.248148,0.323201,-0.010085,-0.002905,0.452957,-0.599533,0.349219,0.055228,0.147886,0.022078,0.298884,-0.275704,-0.328272,0.079123,0.148332,0.368766,0.359815,0.816439,0.116639,-0.191780,0.385760,0.268984,-0.192694,-0.215232,0.023606,0.029596,0.071765,0.207228,-0.136505,-0.705808,0.133499,0.525816,0.088575,-0.817859,-0.156074,-0.370347,0.116496,-0.868776,0.382723,-0.133155,0.090806,-0.210317,-0.304903,0.361988,0.248099,-0.098307,0.233071,-0.200683,-0.402778,-0.830719,0.400000,0.453365,-0.436024,-0.026229,0.365210,-0.129047,-0.530215,0.147949,-0.165626,-0.143250,-0.022036,0.776342,0.006253,-0.107511,0.044700,-1.007590,-0.115607,-0.207130,-0.604050,0.092750,-0.331615,-0.056285,-0.552329,-0.143191,-0.171429,-0.371468,0.431629,0.258733,-0.062976,0.723701,-0.472277,-0.109302,0.640042,0.599456,-0.671033,0.493482,-0.034866,0.014728,0.392705,-0.029748,-0.491600,0.608266,0.912161,0.486157,0.231180,-0.009381,-0.306985,0.121230,0.466185', '1316560', '7051900', '26678509', '4300640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482505', '地海传说', '动画', '早在远古时期，人类和龙和谐地生活在一起，然而野心勃勃的人类选择了海洋和大地，栖身东方国度；渴望自由的龙则选择风和火，隐藏在西方世界，两者从此不再有交集。直到某天，两条龙出现在人类的世界，并且相互厮杀，这一事件给人类带来难以估量的影响。上千头牲畜死亡，无数农作物枯死，干旱、饥荒、瘟疫蔓延，世界逐渐失衡，人类社会崩溃在即。大法师格德四处寻找灾难的根源，在这一过程中他遇见了惧怕影子的17岁少年——英拉德王子亚刃。这注定以一段不平凡的旅程……本片根据美国女性奇幻文学作家娥苏拉•勒瑰恩（UrsulaK.LeGuin）的“地海系列”原著改编，有宫崎骏之子宫崎吾郎主持制作。©豆瓣', '冈田准一', '宫崎吾朗', 6.3, 18999, 'tt0495596', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p924710920.jpg', 3.9, 18.7, 46.4, 22.5, 8.7, '-0.001476,0.138236,-0.683518,0.540285,0.249882,0.108654,0.632951,-0.034712,-0.330675,-0.216341,0.129887,0.722399,-0.069778,-0.003957,0.364027,-0.308588,-0.329372,-0.350613,-0.066519,0.046005,-0.280368,-0.140010,-0.459685,-0.436407,-0.280509,-0.592284,1.062541,0.214793,-0.315138,0.339195,-0.151057,0.447598,-0.438359,0.450327,-0.236350,0.082456,-0.036056,0.220848,-0.498725,0.198597,-0.373536,-0.021448,-0.058838,0.113033,-0.265980,0.060679,0.783889,-0.711751,-0.062095,-0.394185,0.666624,-0.300312,-0.223416,-0.069332,0.571636,-0.301393,0.075631,0.229827,0.122661,-0.118628,-0.018766,-0.147049,-0.590585,-0.205918,0.209518,0.415209,-0.194316,0.533820,0.322182,-0.255851,-0.071861,-0.220399,0.165551,0.456541,0.605034,0.246954,-0.061425,-0.139006,-0.364366,0.241527,0.616410,0.007979,-0.762000,0.293094,-0.359821,-0.695423,-0.492148,-0.237555,-0.460970,-0.175950,0.397396,0.144928,-0.389190,0.740978,-0.919877,0.039848,0.196021,-0.243704,0.094313,-0.226246,-0.386434,-0.367313,-0.222915,-0.421775,-0.101023,0.032268,0.214927,-0.252272,0.775342,-0.760084,0.372336,0.420959,0.293584,-0.370700,0.743667,-0.090501,0.050724,-0.473301,0.009392,0.624701,-0.151901,0.287232,0.003063,0.196964,-0.077560,0.372700,-0.406324,0.624368', '26759820', '26290398', '26759819', '26873582');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482541', '超级计划', '喜剧', '大陆保安阿峰（于荣光 饰）身手敏捷，一直想出外闯荡世界。这天，阿峰见义勇为，和表妹女干警阿华（杨紫琼 饰）一起解救了被一伙恐怖分子绑架的人质，获得了警局表扬。阿峰认为这些表扬一点意义都没有，于是只身前往香港闯荡。半年后，阿华获派前往香港与当地警方合作侦查一个悍匪集团，暂时住在助理督察阿明（周华健 饰）家。阿明对阿华心生好感，展开追求，无奈阿华还是对表格阿峰念念不忘。随后，阿华见到了阿峰，两人聊了很多。不料，之前已经落网的悍匪集团重要成员炮哥忽然被人劫走。阿华对阿峰真正的身份开始心生疑心……©豆瓣', '杨紫琼', '唐季礼', 6.9, 7268, 'tt0106544', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2351996679.jpg', 0.7, 4.7, 50.7, 34.5, 9.5, '0.061140,-0.142238,-0.549900,0.368793,-0.145647,-0.269880,0.123054,0.122518,-0.523219,-0.355437,0.050813,0.500982,-0.010998,0.308089,0.270238,-0.246699,-0.362518,-0.647448,0.030814,-0.284988,-0.238440,-0.360613,-0.119706,-0.107959,-0.133722,-0.125105,0.269372,0.077417,0.016064,0.651158,0.391650,0.129207,-0.373053,0.402469,-0.105750,-0.081381,0.636676,-0.051645,-0.630402,0.131122,-0.073357,0.013987,0.003730,0.012219,0.307121,0.170466,0.372253,0.261598,-0.358445,-0.278696,0.116245,-0.263855,0.091701,-0.296745,0.739843,0.117717,0.325805,0.259707,0.015867,-0.112341,0.013769,-0.209270,-0.479683,0.198135,0.183489,-0.152105,-0.555568,0.139763,-0.349684,0.114050,-0.085225,-0.102529,0.457278,0.562655,0.286292,0.059354,0.139488,0.298160,-0.164970,0.026688,0.731036,-0.192016,0.257919,-0.028336,0.163089,-0.264724,0.087502,0.180687,-0.132808,0.224550,0.202456,-0.080242,-0.263875,-0.182628,-0.370914,0.007838,-0.201368,0.072486,0.032629,-0.528258,0.170792,-0.528520,-0.193489,-0.042302,-0.132056,0.053164,0.087120,0.110267,0.674998,-0.743427,-0.023782,0.420941,0.585232,-0.958183,0.435617,-0.011314,-0.082288,-0.385074,0.181925,-0.053903,0.298242,0.276675,0.117393,0.183152,-0.041026,-0.470439,0.009463,-0.196326', '1296203', '1293265', '1305915', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482707', '渡江侦察记', '剧情', '1949年，我人民解放军响应毛主席“打过长江去，解放全中国”的号召，砺兵秣马，准备横渡长江。大军渡江之前，特派李连长（孙道临 饰）带领一个侦察班先行渡江了解敌人的江防情况。接受命令后，他带领吴老贵（齐衡 饰）、周长喜（康泰 饰）、杨威（中叔皇 饰）、小马（孙永平 饰）等迅速过江，并及时和游击队刘四姐（李玲君 饰）取得了联系。他们混入江边修工事的老百姓中，略施小计搞到一份江防工事图，并及时汇报给上级。不久，他们得知敌人新增一个榴弹炮团，于是他们假扮敌人工兵混入敌炮阵地，出色完成了侦察任务，在返回的路上，周长喜为掩护同志而壮烈牺牲。军事机密的再三泄露，令敌军长（崔超明 饰）火冒三丈，他下令炮击我游击队根据地，正和上级通话的步话机被敌炮火击中，怎么办，吴老贵和小马临危受命......©豆瓣', '孙道临', '汤晓丹', 7.6, 4333, 'tt6478958', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2510077051.jpg', 1.2, 2.3, 31.6, 46, 19, '-0.066702,-0.283664,-0.529719,0.612638,-0.044372,0.056684,-0.090831,0.057288,-0.258615,-0.014619,-0.027649,0.054574,0.315429,-0.316865,0.080179,-0.447866,-0.465774,-0.591001,0.094910,-0.112383,-0.339189,-0.378995,-0.030977,-0.327834,0.271910,-0.089093,0.404143,0.096802,-0.116371,0.599585,0.087286,0.071353,-0.086458,0.518520,0.165031,0.141313,0.072455,-0.423015,-0.248113,0.084228,-0.456869,-0.265039,-0.069149,-0.096669,0.173645,0.447071,0.649739,-0.184809,-0.050030,-0.126161,-0.271678,-0.203018,0.527492,0.034855,0.644982,0.097001,-0.261048,-0.091622,-0.254529,0.372916,-0.250719,-0.026334,-0.267843,-0.199339,-0.048073,-0.250759,-0.357744,0.061886,-0.239078,0.387438,0.108288,-0.278644,0.106298,0.665549,0.055619,-0.074601,-0.237371,-0.050614,-0.344279,0.345796,0.419442,-0.329602,0.108821,-0.420704,0.284296,-0.309149,0.167442,0.239437,-0.091527,-0.030649,0.416378,-0.189794,0.218707,-0.335607,-0.387037,-0.142513,-0.468558,-0.217468,-0.092068,0.027388,0.161287,-0.770380,0.258064,-0.150294,-0.142524,0.474753,0.055112,0.392953,0.427413,-0.352405,-0.182157,0.329030,0.227656,-0.624408,0.152856,0.244152,0.173875,-0.124772,0.380569,0.028425,0.227154,0.732422,0.352040,0.232530,-0.299543,-0.306292,-0.103204,-0.166134', '1292846', '1431694', '1293830', '35231379');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482709', '董存瑞', '剧情', '1945年5月，见习小八路董存瑞（张良）和同村好友郅振标（杨启天）要求像其它青年一样参军抗日，因年龄太小被赵连长（张莹）拒绝，两人尤其董存瑞很不服气，却也无可奈何。一次反“扫荡”中，区党委书记王平不幸牺牲，临死之际，他托付董存瑞替他上交最后一次党费，董存瑞和郅振标代王平完成心愿时，也如愿成了八路军的一员。经历抗日战争、内战的枪火洗礼，董存瑞逐渐由鲁莽、冲动的孩子蜕变成为真正的革命战士。1948年5月，在解放隆化的战役中，已成为共产党员的董存瑞被任命为爆破队长，在执行任务的紧要关头，董存瑞为减少战友伤亡，做出震撼后人的举动，成为英雄。©豆瓣', '张良', '郭维', 7.3, 12651, 'tt6567022', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2533788795.jpg', 2.2, 3.3, 38.3, 39.8, 16.4, '-0.168049,0.000809,-0.515951,0.174795,-0.104957,-0.425435,0.383128,-0.177365,-0.459266,-0.151754,0.350095,0.727596,-0.117339,-0.027139,0.247771,-0.546411,-0.032623,-0.701805,-0.009609,0.066288,-0.129936,-0.405286,-0.119431,-0.055218,-0.046731,-0.317664,0.918321,0.150864,-0.076361,0.392166,0.388602,0.192116,0.324877,0.402678,0.183250,0.029156,-0.150894,-0.152116,-0.314066,-0.065049,-0.354342,-0.270745,-0.237336,-0.049811,-0.022501,0.207246,0.653698,-0.458861,-0.245710,-0.605304,0.376989,-0.464350,-0.179791,-0.090782,0.287603,0.414271,0.060701,0.068345,0.269905,-0.171880,-0.118429,-0.541765,-0.614267,-0.042237,0.128844,-0.112471,-0.801133,0.448622,0.069707,0.558585,0.213581,-0.106106,0.004882,0.389544,0.282870,0.664033,-0.786434,0.134798,-0.230306,0.451281,0.867008,-0.168684,-0.320624,-0.285902,-0.104143,-0.283861,0.332194,-0.529523,-0.171646,0.423084,-0.141570,0.059323,-0.069165,0.315516,-0.326412,-0.239590,-0.328723,0.116224,0.024495,-0.236973,-0.032398,-0.322528,0.058089,0.070846,-0.266657,0.105470,-0.049962,-0.387369,0.804308,-0.738333,-0.028268,-0.002048,0.328392,-0.496364,0.437644,0.354652,0.095235,-0.352093,0.238814,0.320954,-0.099896,0.242602,0.376785,0.045493,-0.298443,-0.203976,0.022569,0.191767', '30345227', '35030151', '4861627', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1482911', '生化危机3：灭绝', '动作', '爱丽丝（米拉•乔沃维奇 Milla Jovovich 饰）被保护伞公司实验室复制，成了伊萨克博士（伊恩•格雷 Iain Glen 饰）的研究标本。因为她体内的DNA可以对抗T-病毒，所以博士以此来提升僵尸的杀伤力。爱丽丝接到了人类的求救信号，但却中了奸计，几经拼杀，方才自救。她如释重负，然而在睡梦中，她却强烈地感受体内强大力量的召唤，显然保护伞公司实验室对她做了手脚。而且，伊萨克博士还给僵尸注入了人类血液，激活其人类的心智。僵尸变得更强大，根本无法被控制，他们残忍地杀害了实验室助手，被训练对付爱丽丝。3年后，地球成了不毛之地。内华达州的幸存者结成了同盟，爱丽丝也在其中，但是她不敢表露身份，因为实验室给了她超能力，同时也让她被迫做了间谍。爱丽丝被孤立，只有卡洛斯懂得她的苦衷，二人也因此陷入了暧昧之中……©豆瓣', '米拉·乔沃维奇', '拉塞尔·穆卡希', 7.4, 202865, 'tt0432021', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2165451110.jpg', 0.5, 3.9, 36.3, 41.6, 17.7, '0.385779,0.264215,-0.626381,0.532491,-0.338186,-0.195490,0.662510,0.061281,-0.590364,-0.137648,0.131823,0.561803,-0.043337,-0.110672,-0.311214,0.103985,-0.172987,-0.617945,-0.021132,-0.041514,-0.423546,-0.330964,-0.410409,-0.441967,0.037951,-0.660170,0.597039,0.062621,-0.324516,0.100297,-0.092173,0.419207,0.188619,0.576729,0.210610,0.004679,0.258987,-0.346836,0.087852,0.355007,0.170771,-0.242466,0.050038,0.522143,-0.111895,0.296831,0.655557,-0.115197,0.093479,-0.486038,0.280488,-0.275040,0.025689,0.166189,0.268914,0.121283,0.099284,0.119706,-0.082791,-0.026059,0.189533,0.169515,-1.045087,-0.029300,-0.001642,-0.049523,-0.409466,0.119208,-0.219716,0.095109,-0.059027,-0.207036,0.099979,0.195455,0.304800,0.222048,-0.212453,-0.133569,-0.601131,0.004364,0.334287,-0.384412,-0.650742,0.336628,-0.591412,-0.532800,-0.301596,-0.380763,-0.134184,-0.234005,0.365137,0.498252,-0.430465,0.333685,-0.669123,-0.253388,-0.568780,-0.040679,-0.326890,-0.416686,0.027827,-0.472385,-0.482220,-0.158973,-0.296892,-0.206192,0.084273,-0.161422,0.707261,-0.731003,0.054043,0.798797,0.528479,-0.293717,0.335738,-0.293946,-0.031287,-0.075892,0.073594,0.212183,-0.027228,0.539823,0.557354,0.369016,0.215528,-0.032625,-0.406720,0.492588', '1793491', '25932086', '1308585', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1483239', '夺命枪火', '剧情', '表面上看来，乔伊（保罗·沃克 Paul Walker 饰）过着人人羡慕的美满生活，温馨的房子，漂亮的妻子，听话懂事的儿子，乔伊似乎对这一切的一切都信手拈来。但在背地里，乔伊有着自己的苦恼，身为一个黑道中人，他至今仍然做着替人跑腿销赃的“小事”，上位之日遥遥无期。终于有一 天，机会来了，老大带领乔伊参加了一次重要的毒品交易，没想到遭人暗算，老大被射身亡。一如既往的，乔伊被分配了销毁枪支的小任务，心灰意冷的他随手将枪放入了家中的地下室里。没想到，自己随便的举动被儿子和他的好友奥格雷（卡梅隆·布莱特 Cameron Bright 饰）尽收眼底，不幸的是，奥格雷是一个终日受家庭暴力所苦的孩子，一念之差下，奥格雷偷了枪，将虐待他的继父打死。事已至此，一切都变得复杂起来，原来，奥格雷的继父是某俄罗斯黑帮老大的侄子，一时间，黑道白道和乔伊都在寻找着奥格雷的踪迹，乔伊必须在18小时内找到奥格雷和他的枪，否则后果不堪设想。', '保罗·沃克', '韦恩·克雷默', 7.7, 23041, 'tt0404390', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p734522641.jpg', 0.5, 2.6, 26.5, 50.9, 19.6, '0.243570,-0.043880,-0.838241,0.439175,-0.374559,-0.428235,0.676663,0.031931,-0.441642,-0.139869,0.228354,0.667332,-0.077345,0.165877,0.153476,0.273526,-0.362794,-0.608319,-0.318079,-0.227759,-0.331586,-0.599493,-0.308166,-0.228814,-0.081782,-0.188450,0.023579,-0.044204,-0.062553,0.175284,0.380345,0.277274,0.237798,0.360537,-0.131201,0.051087,0.148712,-0.284505,-0.065013,0.145776,0.271946,-0.167055,-0.041023,0.615313,0.233925,0.509216,0.697033,-0.391007,0.016827,-0.124052,0.242912,-0.198583,-0.033366,0.157780,0.292529,-0.006077,-0.018084,0.220144,-0.257640,-0.169075,0.579690,0.003995,-0.779965,-0.096644,0.003080,0.036456,-0.718263,0.608321,-0.163453,0.211885,-0.065552,-0.410557,0.411403,0.236069,0.243175,0.261298,-0.075404,0.059523,-0.658004,0.118902,0.566992,-0.042434,-0.179842,0.116010,-0.218832,-0.466074,0.026394,-0.339155,-0.549097,-0.162637,0.596185,-0.244822,-0.136814,0.502246,-0.172746,0.060894,-0.317758,-0.144255,-0.285792,-0.327793,-0.050539,-0.245523,0.066621,-0.257472,-0.483533,0.236521,-0.081615,-0.050362,0.621439,-0.604286,0.311974,0.549359,0.249794,-0.218306,0.545002,0.156003,0.263014,-0.022004,-0.328241,0.090715,0.406825,0.155147,0.556184,0.336822,0.138008,-0.219661,-0.142139,