INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1483446', '墨斗先生', '剧情', '证券行高级经理麦窦（陈小春饰），年轻有为、恃才傲物。他本过着奢华又嚣张的上层生活，然而如此“成功”的生活就在这一天改变了。一日，麦窦像往常一样去中环上班，一名陌生男子走上前向他讨20元过海返工，可是麦窦头也不回地闪身避开。这瞬间的拒绝动作给他带了接踵而至的噩运，麦窦的不幸旅程由此开始。先是被老板无情炒鱿鱼，再是新工作的老板要求他必须在下午五点钟前过海面谈。然而麦窦刚出公司就被洗劫一空，身无分文的麦窦居然还遭遇一顿痛打。初尝世间百味的麦窦，到底能否如期在五点钟前到达面试地点呢？“鬼王”雷宇杨首执导筒，执导本部幽默搞笑但寓意深刻的喜剧电影《墨斗先生》，由陈小春主演，张学润、张达明、蒋怡、罗家英、Beyond等众多演艺界明星大腕倾情演出。©豆瓣', '陈小春', '雷宇扬', 7.1, 5142, 'tt0441359', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2114137513.jpg', 1.4, 5.7, 43.2, 38.4, 11.4, '0.035383,0.108135,-0.626353,0.255519,0.114282,-0.310455,0.431750,0.234858,-0.161113,-0.194075,0.008242,0.454639,-0.362231,0.298291,0.527730,-0.027501,-0.034842,-0.250286,-0.046476,-0.117922,-0.048864,-0.145045,-0.136194,-0.045716,0.026578,0.018909,0.324613,0.181024,-0.141157,0.367254,0.379710,-0.020163,0.219325,0.585463,-0.172498,0.102806,0.119896,0.171751,-0.299918,0.247160,0.220836,-0.341376,-0.126898,0.000257,0.021822,0.367095,0.383269,0.089770,-0.331091,0.133658,0.550455,-0.106849,-0.026508,0.010470,0.187575,0.122238,-0.030869,0.073409,-0.218493,0.230240,-0.114957,-0.167143,-0.254981,0.137316,-0.006640,-0.160082,-0.598057,0.342187,0.000401,0.124266,-0.001795,-0.379063,0.082795,0.083681,0.297324,0.258303,0.164164,0.200194,-0.464828,0.450238,0.652322,0.159167,-0.207884,0.490668,0.127159,-0.540310,0.069508,-0.214142,-0.164160,0.012191,0.098222,-0.076827,0.056786,-0.069659,-0.404831,-0.005856,-0.199942,0.008929,-0.037579,-0.118588,-0.052418,-0.743586,0.064048,-0.234274,-0.185119,0.109215,0.013558,-0.163838,0.429016,-0.422924,0.205582,0.488613,0.368234,-0.366315,0.693542,0.096331,0.191121,-0.092016,0.068248,-0.060251,0.155170,0.441261,0.268766,0.362335,0.033366,-0.292075,-0.065951,0.195706', '24751811', '2159244', '3326747', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1483577', '功夫小子闯情关', '动作', '清朝末年，一代宗师太极拳高手杨崇武（于海 饰）一家隐居杭州西子湖畔。杨崇武与妻子慧娘（胡慧中 饰）晚年喜得贵子杨学文（吴京 饰）。学文自幼天资聪慧，生性好武，而杨父怕他惹事闯祸，每日督促儿子苦读诗书，不准他外出。学文暗中偷学父亲的太极拳，并自创了一套辫子神功，平日勤加苦练，习得一身好武功。适逢钱塘江边举行祈雨祭祀，学文和表弟偷偷前去参加龙王祭。在祭典上，学文遇见了留洋归来的千金小姐曹央云（钟丽缇 饰），学文一见钟情。为了追求央云，学文参加了革命党。他的辫子神功在禁鸦片运动中大显神威，学文与央云感情日益加深。然而向中国走私鸦片的帝国主义分子却并不善罢甘休，暗中设下阴谋诡计，一场殊死搏斗旋即展开。©豆瓣', '吴京', '袁和平', 6.5, 7422, 'tt0117821', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2352279391.jpg', 1.8, 8.7, 58.6, 23.4, 7.5, '0.109851,-0.159505,-0.343195,0.579093,0.054489,-0.432852,0.015465,0.058922,-0.564446,-0.553999,0.321661,0.430715,0.088966,-0.106206,-0.057720,-0.187415,-0.024264,-0.467977,0.263408,0.083138,0.216416,-0.091705,0.267953,0.248434,-0.276885,-0.285252,0.004404,-0.037360,-0.114982,0.745040,0.032550,-0.027326,0.175887,-0.028773,0.056334,-0.056730,-0.100426,0.062916,-0.185820,0.041550,0.303649,-0.486418,-0.544038,-0.298961,0.078816,-0.000503,0.448422,0.128074,0.212425,-0.608906,0.208528,-0.066434,-0.308382,0.259817,0.401453,0.108204,0.362214,0.238929,0.322490,0.105506,-0.058157,-0.120839,-0.035578,-0.161597,0.525619,-0.078664,-0.295443,0.195986,-0.223227,-0.124646,-0.525568,-0.707611,-0.144261,0.165462,0.177552,0.083876,-0.104700,0.153264,-0.457752,0.505564,0.508546,-0.063227,0.357635,-0.104163,0.064254,-0.227812,0.474502,-0.606796,-0.328220,-0.098179,0.192883,-0.547393,0.090324,0.221674,-0.275374,0.166910,-0.089071,0.314422,0.050395,-0.040907,-0.046384,-0.422870,0.046317,-0.535984,-0.117275,-0.391156,0.349212,-0.499353,0.531886,-0.749525,0.259117,0.041802,0.050059,-0.440274,0.484237,-0.056488,0.327791,-0.047067,-0.216384,-0.049333,-0.088078,0.306222,-0.404994,0.530752,0.146964,-0.186019,-0.092924,0.191146', '25723081', '1419416', '3445516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1483630', '一轮明月', '剧情', '在日本留学多年的李叔同（濮存昕 饰）终于回到了魂牵梦绕的祖国，当时正置辛亥革命成功，他为共和欢呼，并出仼《太平洋报》副刊主编，憧憬国家美好未来。好景不长，没过多久国家陷入军阀混战，李叔同也从穿洋装的主编转变为懦雅的布衣君子，以教授书画为业。其间，培养了丰子恺（尹治 饰）、刘质平（胡光子 饰）等一批日后的艺术名家。此时的李叔同对佛学产生浓厚兴趣，遁入空门，法号弘一。闽南佛学院太虚院长（刘伟明 饰）与弘一法师都有宏大的志愿，虽门派不同，最终却殊途同归。抗战爆发后，身患重病的弘一法师仍坚持抗日救亡运动，并谱写救亡歌曲鼓舞士气，1942年10月13日，一代大师驾鹤西去......©豆瓣', '濮存昕', '陈家林', 8, 6340, 'tt10168220', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2509726858.jpg', 0.7, 2.8, 21.1, 44.5, 30.9, '-0.074278,-0.045797,-0.287806,0.325917,0.308555,-0.513920,0.162876,0.230630,-0.565952,-0.427077,0.146774,0.559539,-0.217614,0.089138,0.176092,-0.281690,-0.189248,-0.548472,0.117526,-0.175222,0.071964,-0.262531,-0.038523,0.164570,-0.357839,-0.213912,0.495445,0.355696,-0.232328,0.589054,0.135223,0.149021,0.105351,0.334958,0.132614,-0.040593,-0.070722,0.238368,-0.392517,-0.072238,-0.086436,-0.283317,-0.220253,-0.163923,-0.402153,0.048651,0.484103,-0.213960,0.123219,-0.179586,0.484860,0.071720,-0.154440,0.007628,0.213751,0.380481,-0.053727,0.513962,-0.123644,0.137591,-0.422353,-0.066596,-0.282284,-0.072129,0.291509,0.143033,-0.377099,0.807182,-0.050851,-0.039594,-0.063804,-0.330705,-0.087824,0.404434,0.257208,0.484258,-0.011195,0.308978,-0.221906,0.530415,0.310563,-0.154050,-0.299334,0.025561,-0.237038,-0.400773,0.245658,-0.252801,-0.140428,-0.013752,-0.009496,-0.093301,0.298915,0.094526,-0.376475,0.005678,-0.222621,-0.056721,0.341185,0.003569,-0.142181,-0.468078,-0.080196,-0.139254,0.023326,-0.279478,0.310265,0.072699,1.035521,-0.714061,0.170715,0.026577,-0.128503,-0.379697,0.596349,0.080431,-0.105862,-0.262982,-0.167928,0.456961,-0.410067,0.580542,-0.269986,0.248659,0.153706,-0.224932,-0.011819,0.171526', '25922902', '27602116', '1826173', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1484091', '水果硬糖', '剧情', '天真甜美的十四岁少女海莉（艾伦·佩吉 Ellen Page 饰）在网络上认识了三十二岁的摄影师杰夫（帕特里克·威尔森 Patrick Wilson 饰），二人相约在咖啡馆见面，相谈甚欢。海莉主动要求去杰夫家，让他为自己拍摄艺术照片，杰夫欣然从命。聊天喝酒之后，杰夫突然眩 晕倒地，醒来发现自己竟被五花大绑。原来海莉是有备而来，就是要惩罚在网络上勾引未成年少女的恋童癖。海莉在屋中搜寻杰夫进行不法行为的证据，并为他实施了阉割手术。中途邻居太太（吴珊卓 Sandra Oh 饰）来访，也被海莉成功蒙混过关。随着海莉惩罚计划的一步步展开，杰夫的真面目也逐渐浮出水面……本片被提名英国独立电影奖最佳外国独立制片电影，并获西班牙加泰罗尼亚电影节最佳剧本、最佳电影及最受观众喜爱影片奖。©豆瓣', '艾利奥特·佩吉', '大卫·斯雷德', 7.5, 210890, 'tt0424136', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2168294290.jpg', 1, 3.8, 31.6, 46.4, 17.1, '0.047448,0.132519,-0.556673,0.278437,0.012818,-0.289337,0.458972,0.192972,-0.326723,-0.059710,0.229717,0.853450,-0.492536,0.153553,0.181079,0.126325,-0.522253,-0.599193,0.014280,0.004734,0.052186,-0.370543,-0.030182,-0.079882,0.030917,-0.306145,0.471263,-0.262104,-0.243126,0.502024,0.548100,0.015497,-0.065506,0.302801,0.123751,0.106353,0.337094,-0.287164,-0.384380,0.442737,-0.078445,-0.328038,-0.138942,0.135324,-0.049254,0.377381,0.793282,-0.029767,-0.132806,0.004450,0.645730,-0.260869,0.165960,0.228210,0.353926,-0.014782,0.197165,0.119061,-0.095820,0.128842,-0.053220,-0.048548,-0.314826,0.254988,-0.019212,0.200661,-0.366267,0.236534,-0.157653,0.129943,0.040290,-0.145759,0.009332,0.241467,0.174242,0.145276,0.048756,0.201395,-0.365715,0.279032,0.091312,0.113147,-0.109167,0.544492,-0.160452,-0.528314,0.086589,-0.115286,-0.286892,-0.052258,0.391053,-0.141689,-0.032155,0.008004,-0.326874,-0.081652,-0.255166,-0.062790,-0.076630,-0.233317,-0.068248,-1.062550,-0.160087,0.061832,-0.227314,-0.213171,-0.051684,-0.304467,0.521531,-0.556534,0.221789,0.796158,0.235224,-0.336633,0.574576,0.254116,-0.110978,-0.269206,-0.314428,0.230393,-0.001165,0.127535,-0.031701,0.278178,0.097439,-0.212278,-0.541320,0.334362', '34961898', '2075345', '24751811', '2255841');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1484163', '金田一少年事件簿：吸血鬼传说杀人事件', '悬疑', '美雪（上野树里 饰）收到朋友的邀请函，邀请去“废墟之乡”小度周末，美雪喊上同学和青梅竹马的金田一（龟梨和也 饰）一同前往，临时被同学放鸽子，变成了2人独行。在废墟之乡的一家旅馆，同住的还有警察剑持（加藤雅也 饰）、摄影师、小说家、医生等几个人，旅馆员工凑青子温柔大方，旅馆老板在饭后给大家讲了当地流传的吸血鬼的故事。50年前，这里搬来一户罗马尼亚人，被大家误以为是吸血鬼，村民放了一场大火，事后却没找到儿子的尸体，从此天天有人死于吸血鬼之口。50年后，一家三口搬到这里开了旅馆，经济泡沫导致破产后夫妇自杀，剩下的一个女儿6年前神秘死去，身上的血都被抽干了。故事讲到这里楼上传来惊叫声，一名女子死去，美雪恰好是事件的目击者，次日又一而再再而三有人死去，所有的矛头都直指美雪，一直逃避侦探爷爷大名的金田一，为了保护最重要的人，决定找出案件的真相。©豆瓣', '龟梨和也', '池田健司', 6.8, 7695, 'tt0481119', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558475797.jpg', 1, 8.5, 51.9, 27.3, 11.2, '0.310750,-0.195039,-0.348605,0.051844,-0.127162,-0.175296,0.448479,0.124061,-0.497850,-0.311961,0.298223,0.816304,-0.182886,0.353256,0.341756,0.058516,-0.292987,-0.552182,-0.087469,-0.248542,-0.406678,-0.182608,0.384406,-0.265312,-0.001223,-0.008574,0.195144,0.019386,0.043217,0.521741,0.080668,0.401288,-0.413893,0.234054,-0.117091,0.249644,0.088445,-0.033282,-0.188577,0.255151,-0.330973,-0.192214,0.025513,-0.041578,0.106652,0.277584,0.568227,0.035902,-0.046844,-0.059973,0.064488,-0.350405,-0.099559,0.078745,0.621396,-0.232989,0.450622,0.240686,-0.296342,-0.340418,0.034961,0.067866,-0.439496,0.117100,0.050973,0.121212,-0.429711,0.447179,0.053011,0.185802,0.042558,-0.436366,0.496105,-0.005084,0.072825,0.263065,0.014418,0.015702,-0.492125,0.185083,0.694862,-0.275071,0.257907,0.094408,-0.009525,-0.345312,0.135396,-0.137108,-0.314472,0.254053,0.240523,-0.040724,-0.354209,0.010326,-0.619889,-0.329702,-0.191812,-0.192838,0.360186,-0.314274,-0.343754,-0.491202,0.046975,0.134621,0.023441,0.112359,0.123156,0.072061,0.842021,-0.468339,0.204701,0.543460,0.309424,-0.302297,0.577971,-0.246623,0.142307,-0.029487,0.097628,-0.106679,0.362134,0.560500,0.222227,0.143668,-0.081913,-0.153690,-0.469821,-0.029041', '30162520', '3811356', '1478066', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1484633', '邪', '恐怖', '桂治洪“邪”三部曲之首。民国初年，广州西关陈家家道已中落到，只剩陈秀英（恬妮）、其入赘的丈夫杨振宇（王戎）及服侍秀英的丫环。秀英体弱多病，稍一走动便会连咳不止，振宇是赌徒加酒徒，在外一遇不顺心事，便会对秀英及丫环拳打脚踢，丫环无法再忍，别秀英归家。这日秀英迎来自称陈府仆人之女的梁绮华（陈思佳）。见秀英身虚体弱，绮华表示愿留下将她照料，秀英将振宇恶习说明，绮华仍毫无犹豫，秀英感激不尽。对这位新来的丫环，振宇自没给予特殊优待，但绮华也非“善类”，某日她瞅准机会联合秀英将振宇杀害。秀英从此陷入恐慌，终被振宇的“鬼魂”吓死。她至死不知的是，绮华原是振宇的情人，而振宇与绮华亦没想到，秀英竟然“阴魂不散”。©豆瓣', '恬妮', '桂治洪', 7.2, 11307, 'tt0081782', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1533514295.jpg', 1, 4.6, 39.7, 41.7, 13, '0.181701,-0.148922,-0.379325,0.006477,0.007118,-0.390052,0.521983,0.234950,-0.702957,-0.234907,0.291302,0.299180,-0.154533,0.060086,0.095059,-0.222772,-0.024914,-0.408871,0.007590,-0.026832,0.019076,-0.140864,0.195166,0.012774,-0.382656,-0.088979,-0.062146,-0.321695,-0.095093,0.353804,0.164024,0.319295,-0.197171,0.313488,-0.078198,0.532560,-0.130189,-0.111174,-0.319640,-0.080939,0.132345,-0.129003,-0.366822,-0.186576,-0.026080,0.252943,0.323092,-0.347422,0.043345,-0.516628,0.190680,0.144914,-0.011925,0.164492,0.327055,-0.046737,0.317769,0.225097,-0.286023,0.152889,0.260784,0.233757,-0.222195,0.318060,0.486924,0.119620,-0.441731,0.223778,0.049874,-0.125457,-0.116517,-0.179882,0.038002,0.069492,-0.125709,0.298058,0.094638,0.292305,-0.191940,0.147008,0.112396,-0.043958,0.004483,0.180458,0.229444,-0.210556,0.538886,-0.390666,-0.653273,0.192940,0.146121,0.221830,0.018779,0.015303,-0.110956,-0.078476,-0.265010,-0.063640,0.030123,-0.135051,-0.271121,-0.044985,0.041764,-0.267580,-0.267074,0.147649,0.420329,-0.084134,0.466398,-0.730032,0.137278,-0.091133,0.323771,-0.637840,0.475629,0.226151,0.251153,-0.016240,-0.115305,-0.010267,-0.166678,0.102751,0.226750,0.005797,-0.184645,-0.169688,0.107111,-0.108112', '3445516', '1304401', '1440958', '1329962');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1484760', '黑社会2：以和为贵', '剧情', '自从阿乐（任达华饰）当上和联胜办事人后，总算有一个过度性的安宁局面。然而，两年一度的办事人选举又一次即将来临。现任办事人阿乐留恋身份权力，希望说服一众元老和邓伯（王天林饰）修例让其连任。而人马众多的Jimmy仔（古天乐饰）为被看好的新办事人人选，但他却只想着生意。一次交易，Jimmy在国内被捕，对方告诫他不可从事生意活动，除非身为办事人。为了大计，Jimmy终与阿乐反目，争当办事人。另一边，阿乐为了铲除障碍，说服东莞仔（林家栋饰）与其联手，绑架Jimmy幕后老板以迫其放弃。一场腥风血雨的冲突拉开序幕，最后他们的恩怨如何解决？是否真能以和为贵？©豆瓣', '古天乐', '杜琪峰', 8.2, 132686, 'tt0491244', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p588133332.jpg', 0.2, 1.3, 18.5, 48.3, 31.8, '-0.307172,-0.075648,-0.335123,0.324707,-0.268893,-0.127520,-0.148294,0.424989,-0.572314,-0.395523,0.205140,0.443811,0.059742,-0.183790,0.262854,-0.326768,-0.142398,-0.524749,0.313935,-0.080562,0.076836,-0.248025,-0.277577,-0.551257,-0.161041,-0.006636,0.760858,0.212255,-0.290169,0.298576,0.454098,0.190271,-0.185557,0.390210,0.092295,-0.382208,0.067385,0.145407,-0.607849,0.048161,-0.297636,-0.331124,-0.388403,0.094077,0.218526,0.341030,0.419181,-0.116207,-0.255356,-0.345883,0.091323,-0.502838,0.093545,-0.036894,0.243919,-0.091197,0.331607,0.720326,-0.373772,-0.078627,0.079219,-0.198162,-0.787635,-0.022782,0.171306,0.095118,-0.498407,0.222264,-0.120253,0.037656,-0.223541,-0.035450,0.002684,0.587626,0.557888,0.046089,-0.163685,0.202057,-0.386851,0.054269,1.033374,-0.079700,0.071097,-0.094210,0.342087,-0.188121,0.134256,-0.421105,-0.334111,0.051067,0.285311,-0.064523,-0.042452,0.147855,-0.242023,-0.323442,-0.377216,-0.075363,0.147237,-0.407584,0.525802,-0.459306,-0.069230,-0.030972,-0.220549,0.006976,0.229409,-0.261932,0.471486,-0.635877,-0.123581,0.347405,0.445718,-1.210890,0.500880,0.555307,0.363982,-0.548814,-0.369503,-0.270072,0.295849,-0.139688,-0.022427,-0.248073,0.032703,-0.315664,0.069248,-0.043860', '1302110', '26678784', '1293265', '1428876');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1485185', '生存游戏', '科幻', '卢米斯（米洛·文堤米利亚 Milo Ventimiglia 饰）、雷克斯（Billy Slaughter 饰）、莎拉（Nicole Oppermann 饰）三个年轻人偶然得到一款名为《生存》的游戏，该游戏以15世纪欧洲臭名昭著的“血腥贵妇”伊丽莎白·巴瑟（Elizabeth Bathory）为蓝本，其制作精良，惊悚非常。在试玩过程中，奇怪的声响和事情接连出现，三人更先后离奇死亡。葬礼后，卢米斯的妹妹艾玛将《生存》游戏交给哥哥生前最好的朋友霍奇（约翰·福斯特 Jon Foster 饰）。霍奇聚集一种电玩好友，一同体验这款卢米斯最后玩过的游戏。随着游戏的进行，霍奇等人发现这是一款真正的死亡游戏，所有的参与者都面临着死亡的结局。而他们已经身陷其中，无法逃离了……©豆瓣', '乔恩·福斯特', '威廉·布伦特·贝尔', 6.4, 6406, 'tt0441796', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p457062251.jpg', 2.4, 14.5, 51.9, 24.4, 6.9, '0.140770,-0.056913,-0.458478,0.588942,0.080189,-0.180925,0.683168,-0.063147,-0.577463,-0.565397,0.248316,0.560014,-0.443935,-0.047045,0.446715,0.020706,-0.538914,-0.516267,-0.186559,-0.157238,-0.477730,-0.478482,-0.142364,-0.510588,-0.087101,-0.025151,0.492271,-0.033018,-0.169323,0.313088,0.411447,0.568846,-0.319197,0.340886,0.041939,-0.047370,0.191481,-0.145730,-0.435406,0.324676,-0.133951,0.159348,-0.027896,0.111604,0.101010,0.029470,0.661556,-0.445129,0.114099,-0.063371,0.341189,-0.092706,-0.049767,-0.212478,0.183089,-0.002012,0.280972,-0.077166,0.022779,-0.049343,0.067241,-0.209426,-0.887489,0.219582,0.117500,0.062028,-0.198783,0.022939,-0.144861,-0.035602,0.156189,-0.000160,0.234319,0.440069,0.765854,0.045837,-0.042495,-0.161551,-0.265846,0.434449,0.474572,-0.223881,-0.279537,0.342185,-0.275343,-0.600048,-0.374870,-0.211260,-0.498949,0.162904,0.283873,0.259727,0.171424,0.564309,-0.905317,-0.066175,0.085504,-0.453796,0.083751,-0.163298,-0.013312,-0.953821,-0.235546,-0.126614,-0.314580,0.049969,0.035543,-0.349370,0.599732,-0.664652,0.323622,0.200068,0.040554,-0.245607,0.425826,-0.122496,0.384402,-0.323588,-0.217411,0.530318,0.249321,-0.018315,-0.019047,0.157806,-0.004583,-0.009547,-0.512805,0.585964', '3318306', '2364001', '2988294', '25995508');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1485260', '本杰明·巴顿奇事', '剧情', '飓风正在侵袭美国新奥尔良，一位病危的老妇睁开了她的睡眼。老妇名叫戴茜（凯特·布兰切特饰），她叫女儿凯若琳（朱莉娅•奥蒙德饰）为她阅读一本日记。这本日记的作者叫本杰明•巴顿（布拉德•皮特饰）。本杰明出生在第一次世界大战停战之时，但生来便像个老人的他被父亲当作怪物，被遗弃在了养老院。本杰明在养老院与老人们一起生活。但谁都没有想到，本杰明逆向发育——越活越年轻！也许“越活越年轻”是某些人的梦想，但真正这样成长的本杰明却有了别人无法理解的烦恼与快乐。穿越半世纪的世界变革，本杰明身处其中，感受别人感受不到的感受。为何母亲会让自己念这本日记？本杰明•巴顿此人与母亲有什么关系？凯若琳陷入了深深的疑惑与好奇之中。©豆瓣', '凯特·布兰切特', '大卫·芬奇', 9, 921980, 'tt0421715', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2192535722.jpg', 0.1, 0.5, 7.6, 34.4, 57.4, '0.302860,-0.177212,-0.698253,0.586649,-0.108293,-0.327186,0.842691,0.022980,-0.641363,-0.545642,-0.075584,0.960404,-0.321571,0.360055,-0.009836,0.301766,-0.267344,-0.395049,0.115674,-0.013652,-0.082822,-0.417324,-0.333861,-0.213436,-0.205143,-0.296523,0.475672,0.099765,-0.270699,0.204411,0.044092,0.371030,0.034299,0.516570,-0.210590,0.114672,0.248692,0.023292,0.104156,-0.049146,0.154424,0.060438,-0.061007,0.245563,-0.182694,0.027017,0.480157,-0.165485,-0.150186,-0.168578,0.379647,-0.077973,-0.067736,0.206952,0.111563,-0.003836,-0.006780,-0.005637,0.062776,-0.304590,-0.119035,-0.068473,-0.501652,0.107923,-0.053403,0.363721,-0.441004,0.152171,-0.278342,-0.178274,0.100011,-0.229732,0.133745,0.386381,0.133475,0.503198,-0.221666,-0.186390,-0.501425,0.232212,0.483110,-0.003571,-0.398923,0.557177,-0.426945,-0.521272,-0.005300,0.013809,-0.665182,0.030014,0.164084,0.338772,-0.356919,0.328564,-0.208907,0.021270,-0.117911,-0.028921,-0.044306,-0.520003,-0.300701,-0.281296,-0.393333,-0.452944,-0.360943,-0.208578,0.093552,-0.451634,0.895537,-0.610501,0.420821,0.389911,0.117584,-0.426184,0.797153,0.302388,-0.050126,-0.181647,0.071732,0.562601,-0.070627,0.100500,0.174917,0.134552,0.017788,0.003090,-0.199174,0.669855', '1292720', '1456503', '30162520', '3504940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1494897', '九个女仔一只鬼', '喜剧', '生于贫苦家庭的陈建伟苦学成才成为公司高层，他也因年轻得志而变得恃才傲物，其冷傲苛刻的为人处事方式遭人排斥。一次交通意外让伟英年早逝，不甘心就此离开人间的他不愿意赴阴间报到，灵魂附在他生前驾驶的车上不愿离开。不过，他的灵魂已经完全失去生前的记忆，他已不记得自己到底是谁。中学女子篮球队队长嘉嘉骗老爸说自己赢得了篮球比赛的胜利，她与哥哥Evans因此得到伟寄身的汽车作奖励。嘉嘉属于无牌驾驶，一次外出途中车辆不受控制，但却自行停下，她既惊恐又疑惑。后来嘉嘉的哥哥Evans发现了其中的秘密，知道伟的灵魂依附在这辆车内。伟请求嘉嘉帮助他寻回记忆，并答应帮助她以赢得球赛作为交换...©豆瓣', '陈冠希', '钟澍佳', 6.3, 10731, 'tt0390305', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p548292476.jpg', 3.4, 15.6, 50.8, 20.7, 9.4, '0.127395,0.381593,-0.769605,0.422001,-0.261899,-0.231144,0.361125,-0.076620,-0.349009,-0.293070,0.196212,0.789682,0.466774,0.139531,-0.024411,0.052665,-0.057042,-0.361575,0.286223,0.052872,-0.198960,-0.483602,0.024165,-0.042819,-0.065591,-0.404845,0.695698,0.189456,-0.189427,0.446510,0.106203,0.254911,0.062096,0.576551,-0.135958,0.148739,-0.206340,0.213780,-0.100810,-0.033602,0.141074,-0.311555,-0.086886,0.148191,0.164527,0.326286,0.518964,0.062103,-0.466561,-0.197553,0.272944,-0.277654,-0.065495,-0.150199,0.002621,0.123917,0.048437,0.358302,-0.142043,0.097732,-0.178048,0.235348,-0.578167,-0.090476,0.157810,0.105678,-0.514979,0.474742,-0.216177,-0.068476,-0.149062,-0.289791,0.161418,0.206337,0.199252,0.211193,-0.198995,-0.026120,-0.502739,-0.072176,0.936124,-0.189051,-0.374285,0.497263,-0.356831,-0.386633,0.123531,-0.461256,-0.612944,0.274535,-0.010412,0.314801,-0.169843,0.049616,-0.008467,-0.193842,-0.194178,0.146119,-0.018651,-0.420089,0.174287,-0.168844,-0.071812,-0.203134,-0.143587,-0.076337,-0.049735,-0.519918,0.514824,-0.942270,0.101827,0.360816,0.544211,-0.858390,0.603132,0.048242,0.080868,-0.402906,0.064702,0.279004,0.214880,0.111240,-0.126642,-0.089426,0.151371,-0.056371,-0.192539,0.227115', '25721544', '1293265', '1308805', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1498658', '蛇形刁手', '喜剧', '江湖上，两大门派鹰爪门和蛇形门世代敌对，双方都想将对方彻底铲除。一个月黑风高的晚上，鹰爪门突击了蛇形门，蛇形门遭到血洗，只有长老白长天（袁小田 饰）侥幸逃出。白长天为了躲避鹰爪门的追杀，隐姓埋名于市井。一日，白长天被市井无赖欺负，街上武馆的打杂简福（成龙 饰）帮白长天打发走了无赖们；随后，暴露了身份的白长天遭到鹰爪门伏击，幸得简福路遇相救才捡回一条命。白长天决定传授简福蛇形拳，聪明好学的简福在学习蛇形拳后加以创新，独创了蛇形刁手。鹰爪门再次找上门，简福为了师傅挺身而出。©豆瓣', '成龙', '袁和平', 7.3, 22328, 'tt0078252', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1748545302.jpg', 0.3, 3, 41.6, 42, 13.1, '0.309308,0.127507,0.106967,0.311117,0.330053,-0.212013,0.027320,0.306439,-0.141387,-0.401464,0.328963,0.543901,0.199100,0.135516,-0.048063,-0.336432,0.431323,-0.878131,-0.267352,-0.219297,-0.242479,0.376170,0.126712,-0.027118,0.026978,-0.022759,0.272419,0.135318,-0.172461,0.601498,0.122321,0.087125,-0.335883,0.001572,-0.434942,0.229090,-0.061648,0.089314,-0.444350,-0.013272,-0.541500,0.014911,-0.177095,0.131835,-0.330411,0.397559,0.198856,-0.138141,0.068514,-0.659140,-0.134518,-0.224257,-0.364760,0.146539,0.829647,0.504726,0.384592,0.237129,-0.343095,0.360631,-0.106516,-0.287967,-0.725030,0.080144,0.345548,-0.203618,-0.639013,0.036011,-0.230227,-0.396668,-0.069547,-0.444193,-0.331895,0.049713,0.214731,-0.214884,-0.247764,0.207982,-0.537455,-0.003795,0.303752,-0.604071,0.078346,-0.154844,0.860596,0.337437,0.647513,-0.519264,0.408112,-0.300941,0.999823,-0.387991,-0.124653,-0.200679,-0.537863,-0.332589,-0.611363,0.333276,-0.513766,-0.440627,-0.319249,-0.499928,0.024637,0.087107,-0.119637,0.261215,-0.045435,0.057674,0.196773,-0.916579,0.138370,-0.277475,0.167154,-0.434221,0.338282,-0.120764,0.102675,-0.061730,-0.205325,-0.068701,0.382163,0.781688,0.266037,0.520241,0.020736,-0.247912,-0.010552,-0.148740', '26665875', '25723905', '1408130', '1303137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1498811', '感谢你抽烟', '剧情', '尼克（艾伦•艾克哈特 Aaron Eckhart 饰）是这个世界上最赚钱也最富有争议的行业――烟草业 的代言人。他每天不仅要像推销员一样用三寸不烂之舌去说服人们抽烟，还要不得不变着法子去对付禁烟团体、环保团体和科学团体的抗议，在政府和参议员中想尽办法为烟草业谋取最大利 益。尼克还有两个知心朋友――为酒业代言的波利（玛丽亚•贝罗 Maria Bello 饰）和为军火业代言的鲍比（大卫•科恩查内 David Koechner 饰）。相同的行业性质让三人成为无话不谈的密友，经常在一起交流怎样对付环保团体等各种社团的抗议、如何在政府、参议员中周旋的诀窍。在政治和商业互相交错的舞台上，他们上演了一出又一出好戏。©豆瓣', '艾伦·艾克哈特', '贾森·雷特曼', 8, 33919, 'tt0427944', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p641850219.jpg', 0.2, 1.5, 20.9, 52.5, 24.8, '0.290204,-0.048801,-0.609677,0.472345,0.041411,-0.231905,0.251284,0.315054,-0.528888,-0.089036,-0.058974,0.731202,-0.265443,-0.064245,0.200670,-0.194786,-0.326715,-0.791295,-0.176190,-0.025262,-0.129802,-0.731980,-0.161513,-0.290921,-0.387314,-0.102170,0.508923,-0.179391,-0.291806,0.100810,0.654658,0.299593,-0.033921,0.174692,-0.021643,-0.367474,0.214858,-0.141010,-0.638282,0.225531,0.129148,0.018902,-0.276414,-0.074753,0.155093,0.161695,0.336537,-0.333898,0.272080,-0.145199,0.331315,-0.290390,0.034294,0.092297,0.289415,-0.155383,0.273169,0.296422,-0.317401,0.217704,0.050673,-0.045961,-1.074952,-0.118769,0.263214,0.264554,-0.647508,0.381749,0.152649,-0.265176,0.062623,-0.082464,0.236589,0.658809,0.369109,0.366751,-0.072010,0.136110,-0.536223,0.095806,0.568152,0.384203,-0.096330,0.031604,-0.327039,-0.124386,-0.228021,-0.430111,-0.252799,-0.553048,0.224251,-0.415999,0.073390,0.238935,-1.030305,0.136357,0.085556,-0.354027,0.402348,-0.443951,0.128751,-1.125535,0.102584,-0.383254,0.064081,0.042149,0.370050,-0.381976,0.943617,-1.057586,-0.303445,0.586334,0.463859,-0.434457,0.732769,0.101393,0.272321,-0.532953,-0.542963,-0.179178,0.418280,0.090611,-0.082240,0.336348,0.356834,-0.126256,-0.151697,0.407891', '4301278', '3318306', '1793491', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1498818', '通天塔', '剧情', '在摩洛哥、墨西哥和日本发生的三个故事。理查德（布拉德·皮特 饰）和妻子苏珊（凯特·布兰切特 饰）因为婚姻危机，去摩洛哥旅行，苏珊在旅行车里遭遇枪击，为了医治苏珊，一车美国游客不得不在摩洛哥的小村滞留，而警方也将此次事件上升为恐怖袭击，展开了调查，其实真相却惊人的简单。理查德夫妇滞留在摩洛哥，影响到了家里的孩子们，墨西哥保姆为了参加儿子的婚礼，只能让她的侄子（盖尔·加西亚·贝纳尔 饰）开车带着她和孩子们一起去，但是，从墨西哥过境回来的时候，他们遇到了麻烦，警方怀疑她绑架美国小孩，事情开始不受控制。日本，聋哑少女千惠子孤寂地生活在无声的世界中，母亲的自杀使她和父亲的沟通越发困难，由于自己的残疾，她也得不到异性的关注，性格越发叛逆。于是，她用自己的方式，和世界沟通交流。©豆瓣', '布拉德·皮特', '亚历杭德罗·冈萨雷斯·伊纳里图', 8.1, 150319, 'tt0449467', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p792233816.jpg', 0.3, 1.6, 20, 51.1, 27, '0.235826,-0.015813,-0.872783,0.528385,-0.300165,-0.095865,0.800166,0.171487,-0.551504,-0.179995,0.153807,0.800665,0.012279,0.195458,0.294836,0.037724,-0.498433,-0.673062,0.170459,0.002949,-0.345084,-0.586812,-0.099256,-0.506620,-0.139018,-0.343580,0.366638,0.007352,-0.284912,0.430426,0.226457,0.418730,-0.143345,0.696127,-0.150711,-0.047341,0.056764,0.042233,-0.213331,0.245167,0.299551,-0.161644,-0.202538,0.275918,0.193776,0.358323,0.731742,-0.182380,-0.042134,-0.233336,0.090118,-0.354294,0.044503,0.178805,0.319296,-0.110632,0.292835,0.347119,-0.260066,-0.010462,0.082140,0.069441,-0.429269,0.248052,0.096853,0.171798,-0.705148,0.365532,-0.238497,-0.035134,0.223871,-0.435135,0.244650,0.660237,0.143753,0.367797,-0.174375,-0.016307,-0.427466,0.144808,0.853683,-0.141750,-0.091921,0.209467,-0.369272,-0.349062,-0.094246,-0.174329,-0.560925,0.086066,0.286424,-0.222644,-0.406379,0.409645,-0.518244,-0.207475,-0.231749,-0.446976,-0.162593,-0.364963,0.131161,-0.718183,0.035144,-0.451076,-0.417156,-0.121370,0.132483,-0.095768,0.694556,-0.685994,0.244071,0.854934,0.381999,-0.689104,0.559160,0.167720,0.228874,-0.284116,-0.158207,0.282947,-0.055647,0.263553,0.159858,0.265535,0.105526,0.016329,-0.213107,0.458895', '34461680', '1292849', '26718282', '3285622');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1498825', '鼠国流浪记', '喜剧', '宠物鼠罗迪的奢华生活全被一只从下水道爬上来的流浪鼠西德搅了，无赖西德甚至把罗迪冲进了下水道。从没经历过世事的罗迪简直步入了噩梦一般，他光鲜的衣着和闪亮的皮鞋与肮脏的下水道城市格格不入。不过幸运的他遇到了丽塔，一个独立、勇敢、聪明、强悍的新新鼠类，更重要的是，她是个漂亮的女孩儿。丽塔答应送罗迪回家，不想这个过程费尽了周折。地下世界里生活着一只妄想灭绝鼠类的疯疯癫癫的癞蛤蟆陶德。他一路对丽塔和罗迪围追堵劫。历尽千辛万苦，他们终于回到罗迪的家。然而在丽塔看来，罗迪的家虽然舒适却宛如金丝雀的鸟笼。已经对丽塔心生爱慕的罗迪该怎么办呢？他会放弃豪华的生活追随着心爱的姑娘去漂泊么？©豆瓣', '休·杰克曼', '山姆·菲尔', 7.1, 9142, 'tt0424095', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456551571.jpg', 0.5, 4.2, 43.8, 39.8, 11.6, '0.315331,0.082094,-0.613807,0.391379,-0.471155,-0.446164,0.999168,0.002127,-0.345683,-0.215152,0.138887,0.595392,0.042953,0.198737,-0.000738,0.233348,-0.143032,-0.362361,-0.185019,-0.111472,-0.171205,-0.183867,-0.456869,-0.090816,0.130316,-0.110285,0.548177,0.225594,-0.023970,0.229740,0.311813,0.096657,-0.039502,0.254604,-0.629333,-0.081213,0.141532,0.385654,0.001463,-0.089614,-0.170549,0.098851,-0.053365,0.181936,0.052469,0.061614,0.606026,-0.458139,-0.252336,-0.098447,0.442403,-0.151846,-0.057768,0.224887,0.153505,-0.103967,0.068287,-0.033077,-0.009793,0.036955,0.174082,-0.225454,-0.704011,0.027936,-0.049288,-0.147200,-0.514499,0.426344,0.077478,-0.086467,0.019999,-0.357981,0.220783,0.075678,0.230365,0.535864,-0.000713,0.314943,-0.613022,0.112712,0.803014,0.096947,-0.346511,0.385276,-0.214810,-0.373483,0.076024,-0.490751,-0.680142,-0.164745,0.361431,-0.202244,-0.667038,0.210310,-0.784023,0.265829,-0.460064,-0.115246,-0.089081,-0.306107,-0.415509,-0.202928,-0.010403,-0.723615,-0.236615,0.097451,-0.144018,-0.264410,0.627423,-0.584234,0.246383,0.633508,0.062833,-0.441371,0.613285,-0.175853,0.051724,0.182750,0.037404,0.549248,0.179109,0.381537,0.125499,0.520573,-0.177326,-0.093381,-0.531339,0.651791', '21619567', '1293515', '1428054', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1498831', '恋爱假期', '喜剧', '爱丽斯(凯特•温斯莱特 Kate Winslet饰)住在英国伦敦的乡村，而阿曼达(卡梅隆•迪亚兹 Cameron Diaz饰)则是洛杉矶的美国丽人。她们在天南地北的两端，却遇上了同样的问题：在感情上遭受了挫败，令生活灰暗无光。二人在网上聊天，商议在圣诞节到来之前，到对方的环境去生活，交互双方的住所作为度假场地。于是，一场令人兴奋的旅行开始了。爱丽斯来到美国大都市，阿曼达则乘班机前往极具英伦情调的英国乡村。除了新鲜的生活环境，当地男生的魅力更让她们猝不及防。©豆瓣', '卡梅隆·迪亚兹', '南希·迈耶斯', 7.7, 150053, 'tt0457939', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1784891606.jpg', 0.2, 2.1, 29.3, 47.5, 20.8, '0.349337,-0.055383,-0.950084,0.489942,0.056576,-0.162641,0.658035,0.494066,-0.644837,-0.265410,0.198310,0.692585,-0.400807,0.239530,0.460145,-0.180029,-0.659158,-0.513678,-0.009351,-0.175511,-0.270542,-0.374778,0.007725,-0.273696,-0.008618,-0.264707,0.428996,0.053075,-0.225853,0.403022,0.047801,0.351189,-0.253472,0.570602,-0.443737,-0.284943,0.139785,0.131824,-0.435116,0.233014,-0.100762,-0.254267,-0.224866,-0.032080,0.441174,0.244896,0.904321,0.095176,-0.230721,0.133346,0.315191,-0.073322,0.073623,0.014014,0.313498,-0.329932,0.098142,0.026604,-0.017873,0.208182,0.203078,-0.340514,-0.365228,0.449213,-0.090769,0.133994,-0.333947,0.775501,0.060360,-0.531757,-0.008034,-0.560310,0.184185,0.358266,0.135183,0.443195,0.134919,0.211093,-0.377844,0.048636,1.021066,0.172062,-0.116098,0.253012,-0.483646,-0.538868,-0.148098,0.058205,-0.424957,-0.209902,0.444502,-0.023784,-0.122863,0.214580,-0.928160,0.098754,-0.038776,-0.361659,0.096973,-0.393991,-0.014288,-1.240132,0.136375,-0.576864,-0.274669,0.147983,0.283604,-0.129503,0.394095,-0.850940,0.090750,0.559483,0.255944,-0.257250,0.579695,-0.022184,0.209536,0.086856,-0.073689,0.567531,-0.068740,0.323251,0.028113,0.410885,-0.247472,0.224447,-0.424494,0.523268', '3178770', '11541282', '2159244', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1499008', '满城尽带黄金甲', '剧情', '王（周润发 饰）领兵造反，夺得了王位。他为了更加巩固自己的地位，赶走了前妻，迎娶了梁国的公主、现任王后（巩俐 饰），以得到梁王的支持。王子元祥（刘烨 饰）是前妻留下的孩子，王跟现任王后也生下了元杰（周杰伦 饰）、元成（秦俊杰 饰）。王后却与元祥有着不可告人的乱伦关系，王一直念念不忘自己的前妻，对外声称前妻已死。王后一直野心勃勃，元杰得知父亲逼着母亲吃毒药，就答应了母亲在重阳节的那天发起兵变，腥风血雨的战争也开始了……©豆瓣', '周润发', '张艺谋', 5.8, 240381, 'tt0473444', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1323669669.jpg', 6.3, 24.3, 47.7, 15.8, 5.9, '-0.349192,0.381597,-0.496092,0.925823,0.224476,-0.300387,0.499520,0.323402,-0.629545,-0.632913,0.160397,0.570623,-0.040593,0.150419,0.177458,0.014510,-0.147906,-0.368692,0.037107,0.119221,-0.063035,-0.273564,-0.133327,-0.353245,-0.324431,-0.261181,0.702837,-0.183361,-0.249654,0.223774,0.837395,0.084100,0.125858,0.523002,-0.198196,0.161285,-0.338246,0.159441,-0.534468,0.227363,0.185799,-0.393039,-0.081235,-0.030585,0.250151,0.307102,0.175847,-0.570861,0.220194,-0.511773,0.343053,-0.477441,-0.028839,0.413857,0.473259,-0.141813,0.235189,0.520201,-0.194002,-0.501952,0.221781,-0.144495,-0.500026,-0.133440,0.157019,0.071816,-0.602487,0.290942,-0.397276,0.012851,0.445109,-0.232173,0.657444,0.723771,-0.132026,0.124346,-0.285191,0.027592,-0.716565,0.387179,0.697393,-0.000099,0.186801,-0.341209,0.194192,-0.493749,0.019267,-0.237382,-0.540317,0.157429,0.352003,-0.150863,0.172020,0.473102,-0.096495,-0.660278,-0.255376,0.124966,0.656970,-0.611180,0.245220,-0.063484,-0.134727,-0.486310,-0.135137,-0.072198,0.193450,-0.328024,0.525917,-0.845307,0.055073,0.078766,0.483183,-1.159187,0.383062,0.342184,0.025037,-0.394791,-0.242118,0.215987,0.005896,-0.161989,0.117405,0.171282,0.057822,-0.057042,-0.134522,0.291300', '1297710', '1484760', '1294693', '4258485');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1499148', '蓝莓之夜', '剧情', '伊丽莎白（诺拉•琼斯饰）被男友抛弃，伤心又苦恼的她把钥匙扔在咖啡店里。咖啡店的老板杰瑞米（裘德•洛饰）保存了很多钥匙，每把钥匙都埋藏了一个伤心的故事。伊丽莎白爱吃店里没人点的蓝莓蛋糕，在某一晚决定离开纽约，穿越美国到处看看。在旅途上认识了明明深爱却困囿彼此的分居夫妇，还有豪爽爱赌却鲜回家看望父亲的少女（娜塔莉•波曼饰），每到一个地方她就给杰瑞米写一张明信片。以他人为镜，伊丽莎白找到了爱的真谛，回到纽约，看见等待自己的杰瑞米，可以幸福地，再吃一客蓝莓蛋糕，放心享受爱的欢愉。©豆瓣', '裘德·洛', '王家卫', 7.7, 156392, 'tt0765120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2237042966.jpg', 0.4, 3.2, 30.4, 44.8, 21.2, '0.228399,0.235719,-0.414171,0.262651,-0.188990,-0.479732,0.744452,0.405768,0.037181,0.121518,0.034521,0.734020,0.067859,0.509577,0.258511,0.392012,-0.281688,-0.403974,0.257133,-0.217892,-0.210849,-0.173810,-0.119593,-0.133293,0.123524,0.013994,0.162702,0.007364,0.172066,0.214837,0.247522,-0.118276,-0.097483,0.483926,-0.352530,0.065029,-0.042622,0.063513,-0.366216,0.187334,-0.028332,-0.194190,0.191535,0.115257,0.231174,0.036027,0.587949,0.060575,-0.190290,0.164722,0.222291,0.012958,-0.228913,0.055538,-0.200526,0.035981,0.073645,-0.136065,-0.449326,0.041172,0.239377,-0.044847,-0.563157,-0.177849,-0.097494,0.132399,-0.599011,0.671540,-0.335027,0.048988,0.240434,-0.297902,0.406452,-0.019912,0.087088,0.456259,0.177237,0.167314,-0.292240,0.225670,0.372248,-0.315331,0.266215,0.354329,-0.175118,-0.120849,0.421940,0.006012,-0.660294,0.129020,0.215417,-0.023467,-0.143754,-0.184625,-0.755292,0.078203,-0.163529,-0.229674,0.428287,-0.551014,-0.347314,-0.472711,0.028571,-0.052786,-0.281437,-0.004044,0.004951,-0.164190,0.732603,-0.333458,0.455120,0.493235,0.264606,-0.408865,0.928415,0.287948,-0.176017,-0.283793,0.176643,0.680464,0.187021,0.107343,0.143256,0.394673,0.079717,0.283946,-0.898682,0.482141', '26868553', '25731805', '26884422', '4233625');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1499796', '糖果', '剧情', '丹（希斯•莱杰 饰）与美丽的糖果（艾比•考尼什 饰）相爱了。两人在一起之后一起出游，他们相处的时光充满了爱意。可是糖果是个吸毒者，她喜欢吸食海洛因，而且她还让男友丹一起吸食。他们利用吸毒后的极度兴奋的状态，企图为生活带来更多刺激。即使糖果的父母指责丹没有把他们的女儿从毒海中营救出来，甚至与她一起泥足深陷。其实他们有尝试戒除毒瘾，可是他们又受到了丹的同性恋朋友卡斯珀（杰弗里•拉什 饰）的影响，毒瘾越来越大，生活变得越来越堕落……©豆瓣', '希斯·莱杰', '尼尔·阿姆菲尔德', 7.6, 6146, 'tt0424880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p790038888.jpg', 0.6, 3.4, 29.4, 48.3, 18.4, '0.083320,-0.228323,-0.506124,0.800464,-0.145588,-0.270914,0.903319,0.303422,-0.401723,0.095587,-0.427835,0.634213,-0.164026,0.161412,-0.087535,0.037043,-0.282771,-0.601451,0.211061,0.075618,-0.296719,-0.267258,-0.144193,-0.024931,-0.288064,-0.595264,0.553032,0.018660,0.096989,0.446946,0.243067,0.236908,0.206108,0.634298,0.101282,-0.043715,0.344494,0.157527,-0.180853,0.244885,0.296744,0.017595,0.321231,0.189651,0.386148,-0.089644,0.690686,-0.029399,-0.085158,-0.374609,0.149641,-0.012097,-0.128570,0.220168,-0.001388,0.141382,0.412548,-0.071745,-0.479990,-0.014067,0.107923,0.149324,-0.742407,0.104052,0.019522,-0.080397,-0.304765,0.294693,0.271551,0.081323,-0.000446,-0.021103,0.205461,0.451207,0.115173,0.153858,-0.384125,-0.433620,-0.792281,-0.005393,0.784715,-0.200772,-0.041609,0.522007,-0.713039,-0.376774,-0.001132,-0.225299,-0.504394,-0.020380,0.173753,0.104816,-0.639996,0.636336,-0.552347,0.023729,-0.300379,-0.055789,0.163451,-0.242414,0.079814,-0.688711,-0.302949,-0.496798,-0.417824,-0.159787,0.175984,-0.605062,0.757384,-0.687332,0.313762,0.556203,0.414618,-0.680740,0.536688,0.283906,-0.166490,-0.067457,-0.280410,0.546012,0.018196,-0.089406,0.441819,0.378234,0.137817,0.456314,-0.262551,0.674258', '1304641', '1292062', '25882279', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1506851', '肥猫流浪记', '剧情', '因犯事而被判入狱之弱智成年人肥猫获保释，社会工作者玛姬奉命派往照料肥猫，玛姬接肥猫出狱，并带他去离岛拜祭父母，因交通意外二人分开，肥猫独自流浪。肥猫得一老人五叔公收留，由于其简单乐观性格，很得村人好感，更化解老人与隔壁青年之误会，三人成为好友，肥猫快乐的渡过了一段时间。肥猫参加乡村表演，玛姬从电视看到，于是往乡村向老人讨回肥猫，谁知警察的突然介入让肥猫身受重伤。', '张曼玉', '曹建南', 7.5, 5211, 'tt0095149', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2348554173.jpg', 0.5, 2.7, 36.7, 43.6, 16.6, '-0.095189,-0.300285,-0.474660,-0.100574,-0.121264,-0.298333,0.768028,0.274431,-0.322963,-0.299088,0.293226,0.478740,-0.054322,0.425987,0.487836,-0.508017,0.134923,0.052302,0.048205,0.261117,0.051812,-0.097358,0.280788,-0.287928,-0.245610,-0.335904,0.330012,0.055428,-0.027401,0.809501,0.030128,0.128144,-0.661172,0.271575,0.040925,-0.021629,-0.173846,0.071959,-0.380737,0.086930,0.123985,-0.183626,-0.084091,-0.167314,-0.164806,0.393757,0.626346,-0.015404,-0.426717,-0.423810,0.228829,-0.027921,-0.187154,-0.083096,0.460345,-0.093129,0.340281,-0.023419,0.232772,-0.171352,0.053162,-0.195001,0.117638,0.265223,-0.005723,0.252616,-0.285844,0.178961,0.034870,0.153834,0.009528,-0.329914,-0.274889,0.214723,-0.182268,0.464864,0.150539,0.424962,-0.119674,-0.042110,0.530361,-0.335951,0.088870,0.150315,0.035637,-0.334402,0.600340,-0.126434,-0.128518,0.214479,0.334812,-0.318064,-0.314205,0.083790,-0.087098,-0.168784,-0.284997,0.120022,0.102293,-0.171857,0.217308,-0.487258,0.211233,0.170404,-0.168111,-0.102549,0.357089,-0.338435,0.253463,-0.445910,0.236038,0.358336,0.383785,-0.515173,0.445430,-0.184440,0.488115,-0.241606,0.119106,0.139329,0.259198,0.140084,0.297618,-0.111346,-0.097317,-0.161927,-0.367241,-0.214933', '10466639', '1773217', '3267195', '20380318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1507134', '生活艰难但是快乐', '剧情', '国际大都会东京，品川居民区的公寓内居住着五个性格各异的年轻人。渴望交到女朋友的落榜复读生冈野瞬（相叶雅纪 饰）、恶习满满的滑板少年恩田琢磨（二宫和也 饰）、总是遭遇倒霉晦气事件的贵田春彦（大野智 饰）、家中经营和风居酒屋的公子哥二叶廉太郎（松本润 饰）、超级暴走的问题少年鸭川忠（樱井翔 饰）。他们从初中时代就是好朋友，虽然时光流逝和各自不同的家境与人生，让少年们的心中渐渐产生了隔膜，但是曾经的友情依然维系着彼此，更加显得弥足珍贵。高中毕业在即，对未来全然没有打算的五个少年相约进行一年一度的“原宿参拜”。而在这一过程中，才发现彼此间似乎真的渐行渐远。无忧无虑的男孩们，终究要长大成人……©豆瓣', '相叶雅纪', '堤幸彦', 8.6, 9071, 'tt0757923', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p718126297.jpg', 0.5, 1.4, 13.2, 36.2, 48.8, '0.273780,-0.089946,-0.627938,0.464770,0.001396,-0.336466,0.797019,0.269011,-0.481263,-0.397294,0.033009,0.749591,-0.263448,0.388378,0.502537,-0.220589,-0.224227,-0.648558,-0.161232,-0.248197,-0.139039,-0.428692,-0.052872,-0.079245,-0.252344,-0.197208,0.855544,0.156316,-0.036337,0.616641,0.310388,0.196391,-0.251984,0.376321,-0.328511,-0.165627,0.134510,0.357119,-0.183794,-0.200370,-0.123080,-0.187578,-0.276990,0.101007,0.038834,0.301459,0.907011,-0.223652,-0.249338,0.064815,0.130987,-0.001650,-0.330680,0.114310,0.387063,0.019880,0.257640,0.306046,0.026219,-0.003155,0.090962,-0.137694,-0.332826,0.115107,0.339336,0.041647,-0.449580,0.583951,0.207083,-0.378855,0.173220,-0.149312,0.069431,0.262604,0.295661,0.383863,-0.327656,-0.008229,-0.340776,0.100022,0.513614,0.145517,-0.228285,0.374611,-0.271542,-0.410363,-0.277375,-0.139081,-0.551937,-0.160726,0.012548,0.254541,-0.206067,0.136635,-0.667392,0.124110,0.045807,-0.182599,0.223602,-0.389675,-0.028789,-0.676977,-0.091621,-0.820747,-0.522788,0.217711,0.218054,0.024687,0.914135,-0.956859,0.066374,0.199171,0.175731,-0.392133,0.542739,0.159085,0.028027,-0.442216,-0.360581,0.087369,-0.181914,0.042209,-0.030826,0.486229,-0.377212,-0.095915,-0.304165,0.546435', '3811356', '24839498', '1826173', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1507140', '生活艰难所以快乐', '剧情', '故事承接第一部，讲述二叶廉太郎（松本润饰）、贵田春彦（大野智饰）、恩田琢磨（二宫和也饰）、鸭川忠（樱井翔饰）和冈野瞬（相叶雅纪饰）五位少年自高校毕业后，各自展开自己的人生之路。在相隔三年之后的某一天，在机缘巧合下几人重新聚首在一起。在美国从事音乐活动的恩田琢磨突然回到日本，而二叶廉太郎却行踪不明。再次相逢在一起的四人，回到了当时合租的八盐住宅区。然而物是人非的是，正在计划新建高级住宅城的自治团体与反对改建的居民之间发生了激烈的纠纷。由日本导演堤幸彦执导的青春电影《生活艰难所以快乐》，由日本五人偶像组合杰尼斯偶像团体岚担任主演。©豆瓣', '大野智', '堤幸彦', 8.6, 7177, 'tt0757922', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2251718378.jpg', 0.4, 1.7, 14.8, 35.6, 47.5, '0.139208,-0.115608,-0.684281,0.307587,0.538857,-0.366089,0.485822,0.441362,-0.350723,-0.337365,0.154165,0.625953,-0.275857,0.334898,0.456176,-0.393844,-0.456014,-0.881993,-0.072416,-0.179771,0.017795,-0.375953,0.241777,-0.165409,-0.248627,-0.168780,0.882472,0.302142,-0.102927,0.414440,0.361654,0.172766,-0.535771,0.123624,-0.166681,-0.004092,0.368734,0.232878,-0.591278,0.144462,-0.311155,-0.261579,-0.349260,-0.097532,0.275274,0.211925,0.861689,-0.062010,-0.186758,0.021143,0.213006,-0.113658,-0.210225,-0.056385,0.503506,0.184783,0.191933,0.288312,-0.119843,0.101739,-0.163157,-0.228323,-0.438338,0.182434,0.108661,0.235671,-0.334503,0.462607,0.143938,-0.110818,0.191118,-0.170733,0.061446,0.684438,0.387058,0.309770,-0.135518,0.264197,-0.019491,0.443176,0.896473,0.031779,-0.119243,0.347283,0.132703,-0.380179,-0.338838,-0.022008,-0.241560,-0.227330,0.054132,0.001635,0.121838,0.107579,-0.819631,-0.048928,0.026777,-0.242330,0.423960,-0.218986,0.082373,-0.968413,0.027721,-0.299466,-0.118871,0.118262,0.215533,-0.249743,0.702733,-0.944925,-0.014733,0.216133,0.231774,-0.542182,0.538006,-0.005781,0.144928,-0.265063,0.218316,0.230011,-0.032377,0.342732,0.066170,0.461725,-0.112197,0.009477,-0.648809,0.164461', '5403927', '2369613', '26365262', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1507151', '游侠', '动作', '故事发生在亚洲黑社会势力强大的美国旧金山。FBI亚裔警探汤姆为了救同事杰克（杰森·斯坦森 饰）击杀了一名黑社会杀手，引来全家的杀身之祸。当杰克来到汤姆的度假小屋时，汤姆一家已经被烧为灰烬。 汤姆一家的惨死成了杰克心中永远无法弥补的遗憾，时时刻刻折磨这他。 事发三年后，杰克在调查各帮派一些核心人物的命案时，发现一个叫罗杰（李连杰 饰）的杀手，他头脑冷静、神出鬼没、枪法精准，表面上拿着中国帮会的钱，背地里为日本帮会服务，却不服从命令放走了中国老大的妻女 随着调查的深入，罗杰的秘密被一一揭开，杰克在震惊的同时，也不得不重新面对当年汤姆一家惨死的真相。©豆瓣', '李连杰', '菲利普·G·阿特威尔', 6.5, 30685, 'tt0499556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p858293602.jpg', 1.7, 10.8, 54.8, 25.3, 7.4, '0.246165,-0.032394,-0.524476,0.347482,-0.174617,-0.413864,0.663218,0.061024,-0.469933,-0.327959,0.389623,0.786155,-0.096625,0.235451,0.122068,-0.115492,-0.316512,-0.721259,-0.068316,-0.248958,-0.157104,-0.318227,-0.310888,-0.500645,-0.073198,-0.054772,0.341330,0.139522,-0.131895,0.301862,0.304800,0.450221,-0.150513,0.187822,-0.162632,-0.008617,0.410043,-0.301507,-0.235403,0.180373,-0.141982,-0.414361,-0.020008,0.190548,-0.176491,0.421712,0.648998,0.029907,-0.273096,-0.218073,0.349017,-0.434489,-0.150189,-0.008994,0.480058,-0.158221,0.030975,0.272584,-0.094740,-0.178588,0.066178,0.158654,-0.980718,0.031115,0.147831,0.213287,-0.640913,0.300865,-0.409494,0.268341,-0.018158,-0.208821,0.303876,0.401242,0.278199,0.188093,-0.094594,0.287294,-0.482955,0.167205,0.753239,-0.251134,0.017766,-0.094446,-0.057628,-0.188514,0.027569,-0.151286,-0.368592,0.049962,0.429631,-0.166224,-0.124290,0.294695,-0.611029,-0.347798,-0.303651,-0.254498,-0.063944,-0.344260,-0.227614,-0.532760,-0.318748,-0.218538,-0.268522,-0.022824,0.029134,0.099276,0.665577,-0.542933,0.153164,0.615247,0.083707,-0.417961,0.415590,0.024006,0.022529,-0.137561,-0.243993,0.133345,0.520212,0.382656,0.204549,0.283767,0.090608,-0.386527,-0.157445,0.192409', '26678784', '1793491', '25928048', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1507152', '德州电锯杀人狂前传', '惊悚', '在德州某屠宰场，肥胖的女工正在案板切肉，突然感到腹中剧痛，原来身怀有孕的她羊水已破，产下一个畸形儿，遗弃在垃圾箱，后来被清洁工救起。N年后，一群年轻人驾车路过这里。刚从越南前线归来的艾瑞克（马修•波莫 Matthew Bomer 饰）刚与未婚妻克莉希（乔丹娜•布鲁斯特 Jordana Brewster 饰）团聚，就得知弟弟迪恩（泰勒•汉德雷 Taylor Handley 饰）又要去前线，他本想陪弟弟共赴沙场。但迪安在女友贝莉（迪奥拉•拜尔德 Diora Baird 饰）的劝说下准备将入伍证烧掉，他们为此产生了争执。这时，他们遭到了飙车党挑衅。后来，为首的女孩竟然被警察击毙。警察霍伊特（R•李•艾尔米 R. Lee Ermey 饰）拦住了他们的车子，把他们带到了令人毛骨悚然的屠宰场，开始了惨无人道的折磨……©豆瓣', '乔丹娜·布鲁斯特', '乔纳森·里贝斯曼', 6.8, 18849, 'tt0420294', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p641857606.jpg', 1.6, 8.3, 48.8, 29.6, 11.7, '0.297760,-0.170316,-0.616022,0.130799,-0.085701,-0.389824,0.776598,0.410015,-0.359521,-0.166389,0.318147,0.668598,-0.289046,0.372504,0.346078,0.206959,-0.401251,-0.532518,-0.024095,-0.117404,-0.431649,-0.070270,-0.055500,-0.363610,0.042047,-0.220470,0.293665,-0.185619,-0.028525,0.560860,0.251023,0.292399,-0.034061,0.581522,-0.396049,0.451148,0.298288,-0.236272,0.011588,0.013432,0.100042,-0.246198,-0.008505,0.122003,0.009643,0.338924,0.629500,-0.068314,0.271607,-0.279138,0.218804,-0.149604,0.168628,0.242470,0.296220,-0.154122,0.069006,-0.072224,-0.173969,0.022061,0.227013,0.020897,-0.245202,0.220177,-0.267238,-0.090189,-0.718952,0.176805,-0.256358,0.282902,0.366142,-0.070824,0.250722,0.365940,-0.003325,0.457138,0.103833,-0.137480,-0.436386,0.104023,0.606119,-0.148917,0.105873,0.122028,0.185236,-0.205260,0.456018,0.083891,-0.130283,-0.183148,0.609061,-0.167327,-0.123809,0.024683,-0.564123,-0.338115,-0.333833,0.055122,0.000023,-0.108494,-0.391484,-0.494926,0.051715,0.010269,-0.197718,0.171964,-0.118737,0.176877,0.324048,-0.552563,0.171133,0.461653,0.233283,-0.427866,0.265024,-0.054789,0.213670,-0.121707,0.072038,0.236458,0.310603,0.580570,0.476614,0.408150,-0.280650,0.043329,-0.356511,0.222828', '21619567', '3011051', '1292533', '1303462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1507158', '惊涛大冒险', '动作', '兰德尔（凯文•科斯特纳 Kevin Costner  饰）本事美国海岸警卫队的一名出色队员，然而，老猫烧须，一次他执行拯救任务时不仅任务完全失败，还搭进去了五名队友的性命。兰德尔从此一蹶不振。上司为了帮兰德尔重拾信心，将他派到了培训基地当任教官。在那里，兰德尔遇到了自信狂妄的学员游泳冠军费殊（艾什顿•库彻 Ashton Kutcher 饰）。费殊的自信活力给了兰德尔重新投入工作的信心。一次，费殊问兰德尔一共救过多少人，兰德尔告诉他22人；费殊一阵失落，随后问，“不是200个吗？”兰德尔斩钉截铁地回答，“我只记得我失去多人！”费殊彻底被兰德尔的勇气与坚毅所折服。两师徒惺惺相惜。之后，两人一起投入到了一次生死攸关的抢险中……©豆瓣', '凯文·科斯特纳', '安德鲁·戴维斯', 7.5, 6850, 'tt0406816', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199293704.jpg', 0.3, 2.7, 33.1, 48, 16, '-0.067493,0.121841,-0.522309,0.601611,-0.412129,-0.831088,0.366294,-0.165182,-0.391939,0.124573,0.049503,0.732686,0.164421,0.138413,0.290661,-0.142816,-0.234246,-0.612031,0.052930,-0.136790,-0.308730,-0.643964,-0.256995,-0.221176,0.085142,-0.518147,0.349682,0.055916,-0.002452,0.539891,0.248989,0.108917,0.177639,0.454805,0.226391,0.052644,0.380079,-0.040046,-0.205601,0.234152,-0.008988,-0.022317,-0.439248,0.235150,0.210664,0.184224,0.444404,0.219029,-0.289867,-0.032141,0.197783,-0.121887,0.186627,0.130917,0.069696,0.103443,0.011158,0.245463,-0.040061,0.001595,-0.087812,-0.130412,-0.756323,-0.180064,-0.214938,-0.018392,-0.625809,0.522814,-0.225849,0.054953,0.037719,-0.156161,-0.134053,0.206304,0.413982,0.312478,-0.231252,0.067306,-0.270812,0.146971,0.705949,-0.249470,-0.198521,-0.020379,0.318288,-0.279490,0.135541,0.002738,-0.211078,0.329612,0.415909,0.063403,-0.029684,0.034682,-0.471319,-0.136207,-0.564363,-0.008649,-0.511158,-0.433623,0.157041,-0.194129,0.120310,0.163354,-0.280299,0.111002,0.192196,-0.139768,0.559552,-0.516154,0.245608,0.519258,0.222187,-0.467181,0.235375,0.121650,0.282129,-0.322870,-0.011641,0.178656,0.150588,0.159771,0.553224,0.392408,-0.166007,-0.309548,-0.106222,0.334845', '26678784', '1293158', '1309069', '30205168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1507248', '自豪与荣耀', '剧情', '在纽约警署，泰尔尼家族声名赫赫。老弗朗西斯·泰尔尼（强·沃特 Jon Voight 饰）创下无数丰功伟绩，在黑白两道皆有很高声望，他的儿子小弗朗西斯（诺亚·艾默里奇 Noah Emmerich 饰）、雷（爱德华·诺顿 Edward Norton 饰）以及女婿吉米·伊根（柯林·法瑞尔 Colin Farrell 饰）也同样在警察的岗位上兢兢业业。某晚，正在参加橄榄球比赛的吉米突然得到噩耗，他所负责的辖区发生枪战，数名警员中弹身亡。在父亲的鼓励下，雷加入特别行动小组，开始追捕相关疑犯。在调查过程中，雷发现越来越多疑点，进而察觉吉米、小弗朗西斯甚至敬爱的父亲都可能牵涉其中。正义在这一刻染上污点，雷的调查之路也充满曲折和危险……©豆瓣', '科林·法瑞尔', '加文·欧康诺', 7.1, 9049, 'tt0482572', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1340519361.jpg', 0.7, 4.9, 45.4, 38.7, 10.3, '-0.110268,-0.102873,-0.833586,0.375519,0.318129,-0.196534,0.489239,0.118633,-0.351542,-0.399422,0.244807,0.665171,-0.173646,0.198165,0.451180,-0.353218,-0.465015,-0.530960,-0.094915,-0.252819,-0.432354,-0.760535,-0.334994,-0.351808,0.088863,-0.422247,0.231681,0.298065,-0.305964,0.150304,0.386962,0.317274,-0.082917,0.440008,-0.030676,0.102531,0.338198,-0.062335,-0.115142,-0.250363,0.071589,-0.075202,-0.343672,-0.074723,0.422864,0.373127,0.286391,-0.380093,-0.160756,-0.146403,0.344596,-0.072583,0.277978,-0.245287,0.458838,0.086818,-0.005296,0.378185,0.051772,-0.156369,0.100737,-0.008016,-0.677172,0.148185,0.217208,0.471973,-0.391049,0.189261,-0.128169,0.249629,0.069627,-0.064548,-0.142182,0.195649,-0.019817,0.135136,0.016707,0.224677,-0.448179,-0.037627,0.483030,-0.007684,-0.308413,-0.220432,-0.160644,-0.325291,-0.330716,0.037910,-0.325895,-0.088585,0.724113,-0.223116,0.291330,0.652587,-0.162473,-0.121271,-0.154820,-0.163778,-0.232029,-0.005365,-0.096395,-0.839339,0.151615,-0.200413,-0.327554,0.128571,0.114889,-0.238613,0.588752,-0.704601,0.175394,0.354438,0.027050,-0.401700,0.391358,0.049468,0.260992,-0.285729,-0.568628,0.434430,0.596784,0.052877,0.237119,0.188925,-0.134501,-0.336220,-0.122898,0.189676', '1307442', '6517421', '3804683', '20277632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('15077774', '谋杀疑案', '喜剧', '奥黛丽（詹妮弗·安妮斯顿 Jennifer Aniston 饰）和尼克（亚当·桑德勒 Adam Sandler 饰）的婚姻已经走入了第七个年头，感受到了“七年之痒”所言非虚的夫妻两人决定用一场旅行来修复他们之间的关系，令爱火重燃。在飞机上，夫妻两人邂逅了一位百万富翁穆尔康（特伦斯·斯坦普 Terence Stamp 饰），穆尔康热情的邀请两人进入自己的社交圈，前往自己位于欧洲的豪宅里度假。然而，让奥黛丽和尼克没有想到的是，在豪宅里竟然发生了一场谋杀案，身为“不速之客”的他们很快就成为了最大嫌疑人。直到这时，两人才意识到，或许他们闯入了一个圈套之中，成为了凶手的替罪羔羊。©豆瓣', '詹妮弗·安妮斯顿', '凯尔·纽瓦切克', 6.2, 13454, 'tt1618434', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2562919700.jpg', 2.3, 16, 55.2, 20.6, 6, '0.425185,0.166398,-0.836919,0.410192,-0.085315,-0.257750,0.920527,0.134562,-0.633020,-0.273318,0.275487,0.894222,-0.532329,0.174012,0.630621,0.129128,-0.394423,-0.856941,-0.042826,-0.450975,-0.396644,-0.545410,-0.356968,-0.135024,-0.071234,0.009043,0.508605,0.146910,-0.195258,0.446675,0.331533,0.076518,-0.225337,0.432322,-0.144479,0.240525,0.617632,0.177924,-0.373091,0.424124,-0.058786,-0.178478,-0.000709,0.246483,0.079385,0.347696,0.687615,-0.465684,0.018342,0.137601,-0.045138,-0.265351,-0.203701,0.282963,0.426058,-0.166053,0.196803,0.231114,-0.368072,0.115313,0.128611,-0.280902,-0.606249,0.248175,-0.106658,0.195705,-0.460536,0.471114,0.021506,-0.453305,-0.086617,-0.162129,0.419496,0.546787,0.269299,0.429736,-0.075931,-0.107194,-0.729100,-0.099998,0.969568,-0.031577,-0.173153,0.324439,0.046095,-0.522642,-0.188483,-0.091990,-0.189552,-0.142824,0.546260,0.058255,-0.063669,0.263894,-0.713227,-0.230491,-0.546053,-0.041179,0.024309,-0.327914,0.013593,-0.796143,-0.202139,-0.378197,-0.257214,0.109715,-0.159072,-0.404455,0.426169,-0.962977,0.209767,0.322905,0.359174,-0.296333,0.859040,-0.112763,0.429865,-0.378990,0.228016,0.139943,-0.034239,0.156935,0.373305,0.322189,-0.261597,-0.009375,-0.189151,0.427074', '26687241', '3055049', '25721544', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1509868', '倒霉爱神', '喜剧', '世界上有这么极端的两种人。一种是运气极好的，就像艾什莉（琳德赛•洛汗饰）。从高中开始，艾什莉就备受上帝眷顾。买刮刮乐一定会中头奖，就连在繁忙的纽约街头叫出租车，都会停下来好几辆。好运的光环一直围绕着她，而这次，为唱片巨头举办化装舞会，则给她带来了升职的绝妙机会。而清洁工杰克（克里斯•派恩饰）则是另一个极端。只要他出现的地方，必定乌云笼罩，医院，警察局，中毒急救中心更是他常去的地方。然而，乐观的他却总是能坦然的面对一切厄运。并执着的要把自己的乐队推荐给唱片大王。奇妙的，在化装舞会，两个人相遇了。意外的一吻，改变了两个人命运的轮盘，运气向两个相反的极端发展。于是，艾什莉急切的想要找到害她走霉运的陌生人，要回自己的运气。却没有想到，自己竟渐渐爱上了这个男孩……©豆瓣', '琳赛·洛翰', '唐纳德·皮特里', 6.8, 55020, 'tt0397078', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p899508219.jpg', 0.7, 6.4, 53.8, 31.5, 7.7, '0.215964,0.032562,-0.629481,0.582519,-0.123988,-0.207201,0.834528,0.279139,-0.337526,-0.008605,0.260815,0.699863,-0.292755,0.220217,0.382688,0.294876,-0.213207,-0.667458,0.012072,0.038192,-0.544795,-0.303712,-0.251927,-0.429833,-0.063898,-0.214120,0.386726,0.205708,-0.125815,0.181148,0.390138,0.200270,-0.002381,0.764423,-0.393593,0.057992,-0.084809,-0.037302,0.112079,0.364534,0.120564,-0.243331,-0.112385,0.450569,-0.150908,0.274456,0.593846,0.022837,-0.211724,-0.008448,0.362264,-0.303558,-0.050383,-0.057522,0.237526,-0.241390,0.192409,0.010998,-0.154162,-0.047848,0.230096,-0.120251,-0.904572,0.179293,-0.068175,0.127857,-0.590989,0.381397,0.178186,-0.162770,0.023511,-0.340469,0.250795,0.217245,0.110860,0.378746,-0.293516,-0.139695,-0.388168,0.099868,0.587798,0.033694,-0.346725,0.472620,-0.439964,-0.268150,0.082849,-0.170523,-0.522565,0.105988,0.360567,0.172959,-0.053712,-0.031871,-0.495462,-0.013871,-0.347787,-0.117419,-0.092959,-0.625250,0.017602,-0.457642,0.065942,-0.118489,-0.456468,0.312164,0.008207,-0.165607,0.619460,-0.829549,0.248466,0.909455,0.274153,-0.419870,0.701716,0.025178,-0.134489,-0.088910,-0.105048,0.057591,-0.140803,0.248033,0.015023,0.418494,0.165441,-0.017137,-0.205615,0.759255', '1949005', '35158375', '3785918', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1510114', '爱我多深', '剧情', '一个淳朴老实的男人，终日循规蹈矩，突然一天，数额惊人的彩票大奖不期而至，他会如何处置？是买一辆拉风的玛莎拉蒂，购栋金碧辉煌的别墅，开家属于自己的公司，还是解决心理的孤寂和下身的欲望？有时人是不可理喻的动物，即使在害羞木讷的弗朗索瓦身上，依然会瞥见离经叛道的冲动。人到中年的弗朗索瓦是一家公司的职员，闲暇时常去名叫毕加尔的酒吧，此处不仅盛产琼浆玉液，更可一览撩人春色。达妮埃拉，活色生香的妖娆极品，意大利血统让她骨子里有种狂放不羁的媚惑，堪称是无可挑剔的上等佳人，150欧元一次的价格也着实不菲。每次弗朗索瓦看见达妮埃拉，都难免眩晕窒息……', '莫妮卡·贝鲁奇', '贝特朗·布里叶', 6.2, 7000, 'tt0420555', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2555563409.jpg', 2.7, 17.1, 54.4, 18.6, 7.1, '0.234163,0.194325,-0.686180,0.368277,-0.375593,-0.184418,0.744516,0.315437,-0.712028,-0.068590,0.336896,0.787181,-0.278058,0.164025,0.411691,0.435212,0.199002,-0.237643,-0.217046,-0.077262,-0.074197,-0.201878,-0.375212,-0.079062,0.156604,-0.247331,0.331825,0.128261,-0.208084,0.484608,0.377439,0.243303,-0.011964,0.452819,-0.443279,-0.545031,0.011520,0.153678,0.170229,-0.140628,0.020066,-0.283454,-0.141940,0.081182,-0.020819,0.059521,0.366628,0.166375,-0.514960,0.210220,0.558741,0.126035,-0.037878,-0.083969,-0.008649,-0.440371,0.356947,-0.353814,-0.382163,0.009251,0.249894,0.209579,-0.850115,0.162447,0.144859,-0.077921,-0.477600,0.414441,0.028231,-0.095008,0.075576,-0.160056,0.002863,-0.169869,0.186056,0.596559,0.023347,-0.048820,-0.753912,0.015286,0.397765,0.409092,-0.319945,0.385099,-0.523456,-0.391488,0.132796,-0.521302,-0.554795,0.069216,0.077654,-0.001497,0.007442,-0.084405,-0.725610,0.161386,-0.306053,-0.198329,-0.115855,-0.320502,-0.216563,-0.285953,-0.110816,-0.512024,-0.324745,0.180588,0.456689,-0.091258,0.579277,-0.537941,0.013562,0.658007,0.206962,-0.331504,0.641720,-0.094519,-0.249066,0.246414,-0.303934,0.254045,0.006575,-0.062921,-0.236964,0.451567,-0.023544,-0.174038,-0.241989,0.753366', '1308457', '1793491', '30387441', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1528848', '大气层消失', '科幻', '一对情侣（张京生 & 吕丽萍 饰）为了钱财抢劫火车，致使一辆运送剧毒药品的罐装车毒气泄漏，最终烧穿了臭氧层。与此同时，正因病在家休息的男孩（张宁 饰）突然发现能够听懂好朋友大白猫的语言。大白猫告诉他这起严重的事故，如不及时加以制止，地球上的生物最终都将灭亡。然而大人们 为了金钱忙碌奔波，根本不会相信男孩和动物说的话。万般无奈之下，男孩只能和其他动物联合起来寻找污染源，以一己之力拯救全人类……本片荣获第十一届金鸡奖（1991年）特别奖。©豆瓣', '张宁', '冯小宁', 7.8, 8554, 'tt2626660', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2672142254.jpg', 1, 2.8, 26.6, 44.6, 25, '0.067507,0.073017,-0.533931,0.089132,0.054785,0.179700,0.512567,0.054711,-0.282081,-0.202089,0.039535,0.518329,-0.004297,-0.109860,-0.007383,-0.128626,-0.435138,-0.283265,0.164825,0.237297,-0.331361,-0.393547,-0.051358,-0.287519,-0.040605,-0.359502,0.380961,0.160737,-0.089082,0.479568,0.211695,-0.135801,-0.200745,0.289075,0.018134,-0.204719,-0.295327,0.108812,-0.034978,0.243328,-0.110723,-0.240640,0.038713,0.021918,-0.041195,0.229893,0.336965,-0.435866,-0.069510,-0.395560,0.204715,-0.370022,0.133338,-0.102873,0.302607,-0.136430,0.316067,-0.096201,-0.123117,0.159343,0.403897,0.140933,-0.505743,-0.019469,-0.160475,-0.016736,-0.362431,0.335631,0.118695,-0.006623,0.050772,-0.230931,0.212060,0.248652,0.302890,0.180574,-0.071500,0.177039,-0.587458,0.071411,0.343814,-0.318633,-0.093508,0.476891,-0.371811,-0.400892,-0.067591,-0.359918,-0.265873,0.078239,0.265115,0.353561,-0.554873,0.060643,-0.444196,0.006462,-0.127299,-0.269897,0.023196,-0.056393,-0.041853,-0.315355,0.159315,-0.033753,-0.053935,0.212810,0.235737,-0.140355,0.722247,-0.431907,0.054217,0.520537,0.487865,-0.548622,0.280638,-0.225028,0.101262,-0.008917,-0.140749,0.084324,0.030793,0.378157,0.289134,0.032843,0.032980,-0.084977,-0.085868,-0.136788', '24284209', '25882279', '3005387', '26921827');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1531733', '安娜情欲史', '剧情', '安娜（格莱·贝 Gry Bay 饰）一直坚信，男友乔纳（马克·史蒂文斯 Mark Stevens 饰）是自己的真命天子，但是很显然，乔纳并不这么想，他抛弃了安娜，开始了独自探索世界的旅程。一晃五年过去了，这五年里，安娜从来都没有忘记过去乔纳，终于，在日复一日的痛苦中，安娜想通了，她开始了在陌生人身上寻求安慰的混乱生活。一次偶然中，安娜结识了名叫弗兰克（Thomas Raft 饰）的男子，弗兰克的温柔和善良逐渐治愈了安娜的内心，就在安娜重新振作只是，乔纳居然回到了安娜的身边，重新陷入纠结的安娜离开了弗兰克，但几乎是在同时，乔纳再度失去了音讯。安娜将注意力转移到了工作上，但在内心里，她明白，乔纳总有一天还会回来。©豆瓣', '格莱·贝', '杰西卡·尼尔森', 6.2, 10874, 'tt0349080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2305704705.jpg', 4.5, 18.3, 48.8, 20.6, 7.8, '0.389219,0.279160,-0.836269,0.362260,-0.141893,-0.705215,0.904713,-0.200803,-0.593204,-0.103368,0.143941,0.765589,-0.216994,0.496796,0.459187,0.566453,-0.818457,-0.822689,0.203125,-0.328805,-0.402729,-0.684195,-0.149036,0.078773,-0.138716,-0.461491,0.517437,-0.070538,0.046532,0.503109,0.142529,0.049118,0.293063,0.892044,-0.009898,0.526367,0.097185,-0.249610,-0.028313,0.236640,0.320357,-0.281486,-0.184438,0.634986,0.279885,0.313998,0.570549,-0.346803,-0.097127,0.125263,0.269156,-0.175661,-0.053413,0.076781,0.083063,0.177843,0.314288,0.020461,-0.406845,0.095308,0.148706,0.033419,-0.406870,0.352118,-0.059262,0.267205,-0.823661,0.362348,0.023661,-0.065359,0.043671,-0.449308,0.085817,0.371492,0.284361,0.163184,-0.295308,0.020893,-0.424307,-0.093908,0.615965,-0.051679,-0.261577,0.556466,-0.040484,-0.218042,-0.242401,0.194067,-0.417417,-0.086505,0.317516,0.366655,-0.404515,0.624386,-0.507907,0.110087,-0.347445,-0.156985,-0.106975,-0.557710,-0.179711,-0.324772,-0.291687,-0.227800,-0.302392,-0.181991,-0.298406,-0.385084,0.622992,-1.183434,0.349360,0.469144,0.381333,-0.155572,0.446767,0.186308,0.085358,-0.112289,0.323115,0.581959,-0.147552,0.333978,0.350750,0.399057,-0.122272,0.002981,-0.495569,0.735835', '1308755', '1309172', '1299965', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1547134', '赖家王老五', '喜剧', '特里普（马修·麦康纳 Matthew McConaughey 饰）是个标准规格的王老五，虽然不再是二十多岁的翩翩美少年，却不失成熟男子的魅力，成功的事业和不赖的长相一应俱全。但他几乎和男女私情绝缘，整天喜欢在家中和父母混在一起，成为情感上的“啃老族”。这当然让父母着急。两老为了帮儿子早点拍拖结婚，想尽各种点子。在发现特里普似乎对金发碧眼的美女十分感兴趣时，他们的好主意便成型了——他们找来一名叫波拉（莎拉·杰茜卡·帕克 Sarah Jessica Parker饰）的美女，让她完成任务给她报酬，目的就是：让特里普发现异性的吸引，从此计划恋爱的事儿。怎料，特里普在迷人的波拉面前不堪一击，防线瞬间崩溃，堕入情网。这不仅令波拉也有点情迷意乱，还印证了“计划赶不上变化这句老话”……©豆瓣', '马修·麦康纳', '汤姆·戴伊', 6.1, 7554, 'tt0427229', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315872351.jpg', 2.4, 15.9, 60.5, 17.2, 4, '0.108234,-0.070533,-0.679191,0.334238,-0.410367,-0.377992,0.836283,0.008987,-0.376357,-0.185907,-0.123976,0.762595,-0.325797,0.070885,0.441195,0.139389,-0.328133,-0.524534,0.008811,-0.114389,0.004714,-0.625281,-0.358461,-0.032438,-0.162720,-0.614144,0.505243,-0.071503,-0.132417,0.505008,0.527297,0.010907,0.117061,0.365655,-0.191476,0.013637,-0.105530,-0.012289,-0.255165,0.176710,0.031113,0.035831,-0.117136,0.304062,-0.039657,0.411587,0.498443,0.014579,-0.293821,0.160863,0.269721,-0.161651,0.002462,0.214109,0.154194,-0.135255,0.290710,0.092433,-0.241409,-0.170477,0.331407,-0.059516,-0.750743,0.186487,0.381788,-0.115793,-0.479540,0.185541,-0.120312,-0.162923,0.052204,-0.237832,0.178691,0.270908,0.373497,0.506635,-0.175934,0.311126,-0.544130,0.080953,0.585556,0.279585,-0.128629,0.462092,-0.228313,-0.311547,-0.146074,-0.254869,-0.300658,-0.005768,0.071969,0.143451,-0.019924,0.159845,-0.528884,-0.034680,-0.136595,0.008854,-0.247743,-0.624175,-0.088632,-0.212202,-0.199338,-0.456306,-0.365452,0.027911,0.169378,-0.154482,0.725536,-0.863281,0.223221,0.466146,0.256050,-0.603039,0.583224,0.392635,0.161136,-0.227003,-0.321031,-0.092702,-0.054583,-0.087959,-0.011820,0.533225,0.008268,-0.398087,-0.361077,0.635457', '1783461', '3230462', '35144311', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1550445', '情不自禁', '剧情', '小黎（邬玉君饰）是个女警察，小白（潘粤明饰）是个小混混，他们在同一地方出没，却并不相识。一次小白被贩毒团伙的人追杀，在地铁站里，走投无路的他冒犯了小黎，并把关键的呼机偷偷扔在了小黎口袋中。被轻薄后的小黎又气又恼，小白通过呼机对小黎“展开攻势”，但小黎脾气未退，也不愿还他呼机。小黎父亲（陈友旺饰）警告女儿不要再跟着小混混往来，但小黎发现自己爱上了小白。之后她铤而走险独闯小白的家，正好撞见了来要挟小白的团伙老大。危险时刻，父亲出现拯救了小黎。但小黎误认为小白是凶手，并在独闯中被抓，小白遭到怀疑。最后，老大让小白打死小黎以证明清白……©豆瓣', '潘粤明', '方刚亮', 8.4, 16245, 'tt17009388', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2463321941.jpg', 0.5, 1.8, 16, 40.7, 41, '0.551440,0.057073,-0.438985,0.261502,-0.383873,-0.412049,0.599381,0.068825,-0.656329,0.174669,0.250262,0.546850,-0.127719,0.134504,-0.149741,0.363647,0.116916,-0.503385,0.228395,-0.120486,-0.329661,-0.407350,-0.075984,0.064417,-0.093549,-0.096079,0.198453,-0.463423,-0.373585,0.488665,0.314807,-0.063186,-0.301223,0.839210,-0.082149,0.181002,-0.112340,-0.068608,0.014986,0.255000,0.084704,-0.286513,0.068607,0.387955,0.017565,0.476366,0.627916,-0.128092,-0.173433,-0.269632,0.145422,-0.387880,-0.253713,0.103729,0.465924,-0.221373,0.358023,0.099796,-0.106708,-0.034132,0.319542,0.484338,-0.345356,0.271293,0.015423,0.036752,-0.691799,0.392267,-0.273336,-0.004507,0.125159,-0.408657,0.253651,0.151886,0.223312,0.105709,-0.274270,-0.005919,-0.465805,-0.198023,0.397494,-0.307525,0.325979,0.285275,0.091909,-0.229386,0.251792,-0.126031,-0.547904,0.133465,0.339208,-0.214594,-0.748311,0.013345,-0.456617,-0.075209,-0.093911,0.207852,-0.338840,-0.538263,-0.250883,0.078395,-0.262760,-0.410811,-0.397808,0.016931,0.053846,-0.237389,0.302706,-0.776656,0.206596,0.817828,0.424183,-0.458033,0.556924,0.372595,-0.083199,-0.013539,0.006431,-0.125936,0.279487,0.507960,0.450645,0.208562,0.109409,-0.428950,-0.071615,0.115521', '26718282', '1947080', '3114200', '3927749');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1550450', '空中杀阵', '动作', '在法保罗夫航空展上，一架最先进的幻影2000战机在飞行表演之时无故失踪。安东尼（伯努瓦·马吉梅 Benoît Magimel 饰）和塞巴斯蒂安上尉（科洛维斯·科尔尼拉 Clovis Cornillac 饰）奉命追踪飞机的下落，并最终找到了飞机，没想到幻影2000竟然向两人发起了攻击，无奈之中，为了自保，安东尼将其击落。之后，安东尼和塞巴斯蒂安因为违抗军令而遭到了撤职，法国军方找到两人，举荐他们参加一场秘密的战机竞赛，他们的对手是美国方面，赢得了比赛的那一方即可获得大笔的军火订单，而安东尼和塞巴斯蒂安亦可因此官复原职。就这样，两人接收了任务，哪知道等待着他们的，竟是恐怖分子冷酷的枪口。©豆瓣', '伯努瓦·马吉梅尔', '吉拉尔·皮雷', 7, 7393, 'tt0421974', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p822564065.jpg', 1, 6.5, 45.4, 35.6, 11.5, '0.191221,0.019119,-0.688280,0.798832,-0.047304,-0.178275,0.305435,0.104229,-0.177623,-0.111231,0.329753,0.864838,-0.038713,-0.219676,0.398778,-0.005823,-0.459125,-0.760800,-0.054959,-0.146283,-0.433936,-0.727115,-0.269963,-0.232223,0.175639,-0.134090,0.629090,0.050307,-0.131240,0.690911,0.328181,0.216843,-0.035095,0.545680,-0.021685,-0.182182,0.126672,-0.159578,-0.175428,0.445993,0.044410,-0.355498,-0.200259,0.147036,0.167382,0.408779,0.564890,-0.325152,0.209171,-0.329770,-0.233462,-0.558608,0.380440,0.152818,0.300876,-0.071651,0.045613,0.115053,-0.146251,0.137556,0.103203,0.201470,-0.777190,0.099709,-0.362662,-0.050719,-0.403538,0.277772,-0.506668,0.164016,-0.132340,-0.328785,0.201024,0.583588,0.099079,-0.027189,-0.395504,-0.267702,-0.611570,-0.112855,0.396173,-0.206333,-0.198270,0.142980,0.241129,-0.502272,-0.007178,-0.369468,-0.048746,-0.024640,0.640803,0.248628,0.149943,0.086314,-0.669764,0.006442,-0.443826,-0.264591,-0.276096,-0.531806,-0.040562,-0.961735,0.224889,-0.143615,-0.464316,0.192085,0.082102,-0.067980,0.476245,-0.784789,0.039820,0.506144,0.367217,-0.343904,0.478573,-0.008100,0.282727,-0.203358,-0.023719,-0.168751,0.205910,0.434215,0.176723,0.239665,0.183016,-0.190466,-0.097857,0.263687', '20274039', '25723905', '1307442', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578475', '洛奇6：永远的拳王', '剧情', '转眼30年过去，往日的荣光渐渐不再。曾经的传奇拳王洛奇（西尔维斯特·史泰龙 Sylvester Stallone 饰）生活平淡乏味，心爱的妻子亚德里安（Talia Shire 饰）因癌症去世，自己与儿子的关系又分外紧张，他终日坐在所开的小餐馆里追忆往昔，谁也不会想到这位拳王退休后的人生竟如此落寞。是时，新一代的拳王横空出世，年轻的梅森·迪克逊（Antonio Tarver 饰）统治者重量级冠军的头衔。在体育频道工作的波利（Burt Young 饰）突发奇想，策划了一场新老两代拳王的世纪对决。梅森渴望在比赛中向拳迷们证明自己的实力，洛奇则希望在此感受万众欢呼呐喊的狂热气氛，他们怀着各自的心愿重返拳台……©豆瓣', '西尔维斯特·史泰龙', '西尔维斯特·史泰龙', 8.6, 16054, 'tt0479143', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199984134.jpg', 0.3, 1.1, 13.2, 38.2, 47.3, '-0.210955,0.031924,-0.647708,0.467361,0.013193,-0.389220,0.487734,0.226535,-0.503584,-0.399023,0.251906,0.956445,-0.307904,0.297914,0.312089,-0.244055,-0.305790,-0.671293,-0.042527,-0.203173,0.106628,-0.315852,-0.280544,-0.134224,-0.014475,-0.316469,0.547677,0.040896,-0.047310,0.628389,0.562827,0.337815,0.125444,0.271260,-0.136264,-0.134141,0.111559,0.149171,-0.457976,-0.115658,-0.159504,-0.087916,-0.247388,0.043501,0.151967,0.082582,0.537826,-0.240936,0.208772,-0.008203,0.339533,-0.022576,-0.009239,0.190817,0.125902,-0.088438,0.043704,0.183791,-0.003067,-0.045326,-0.070841,-0.150189,-0.767063,0.197751,-0.093076,0.313701,-0.469089,0.650157,-0.126432,-0.120924,0.122060,0.093586,0.179106,0.325164,0.142350,0.456635,-0.017522,0.170775,-0.246456,0.232825,0.687119,0.176659,-0.087850,0.372685,-0.073876,-0.413238,-0.157232,-0.303143,-0.590314,-0.140413,0.301793,0.094079,0.120269,0.565512,-0.455524,0.088597,-0.190977,-0.102731,0.094096,-0.245412,-0.104927,-0.585015,-0.101388,-0.320185,-0.195001,-0.104614,-0.065667,-0.270958,0.764996,-0.726498,0.228477,0.140487,0.040905,-0.186129,0.599645,0.347002,0.068357,-0.293356,-0.327905,0.686375,-0.095225,0.055447,0.027806,0.175807,-0.336052,0.053600,-0.202559,0.738096', '1870681', '1292720', '30162520', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578500', '绢', '剧情', '十九世纪中期，一场致命的天灾几乎毁了法国的丝绸工业，受法国丝绸商人巴达比欧（阿尔佛雷德·莫利纳 饰）所托，退役军人哈维（迈克尔·彼特 饰）离开爱妻海琳（凯拉·奈特莉 饰），赴日购买蚕种。在当时，这并不是一件容易的事，由于处在幕府末期的日本正实行闭关锁国政策，一切交易只能在暗中进行。当时势力较大的贵族源十兵卫（役所广司 饰）同意于哈维做这笔交易，但在商谈中，哈维却被十兵卫的小妾（芦名星 饰）所吸引，尽管两人语言不通，但宿命一样的爱情还是开始了。随着哈维的四次旅程，两人之间的感情越来越深。远在法国的海琳，靠做教师带着儿子艰辛度日。丈夫的远行，总是让她担心不已。随着时间的推移，海琳渐渐发现哈维似乎有一个异国情人……©豆瓣', '芦名星', '弗朗索瓦·吉拉德', 6.9, 8154, 'tt0494834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p794911239.jpg', 1.3, 8.3, 46, 33.8, 10.6, '0.177053,-0.013571,-0.553979,0.446452,0.151596,-0.255343,0.534705,0.201173,-0.497850,-0.451499,0.078961,0.548698,-0.095960,-0.132293,0.128059,-0.040855,-0.250810,-0.473449,0.067689,-0.153625,-0.185155,-0.614725,-0.223398,-0.118862,-0.447700,-0.226096,0.724722,0.209909,0.001668,0.316081,0.239648,0.255262,0.080951,0.233206,-0.023687,-0.177210,0.300035,-0.021700,-0.388450,0.162234,0.101118,-0.046458,-0.085374,-0.114856,0.096381,0.485072,0.313242,-0.409695,0.096055,0.039818,0.359268,-0.183403,0.052338,0.111678,0.216435,0.006491,0.045138,0.154492,-0.443251,0.174578,0.253575,-0.080463,-0.426275,0.130262,0.154495,0.142410,-0.465413,0.434065,-0.052857,0.055497,0.054824,-0.444651,0.058572,0.604984,0.205347,0.276079,-0.179192,0.190194,-0.356236,0.086015,0.726458,0.218074,-0.205027,0.239835,-0.342591,-0.385112,-0.104126,-0.259393,-0.290843,-0.133378,0.268374,-0.024504,0.120050,0.503802,-0.431093,0.064432,-0.262733,-0.273043,0.127731,-0.212714,0.105442,-0.608898,-0.095852,-0.757957,-0.236773,0.131296,0.327213,-0.253298,0.454900,-0.608969,0.215201,0.796439,0.302073,-0.305903,0.355498,0.161486,0.341898,-0.097465,-0.425777,0.393586,-0.109518,0.044279,0.100878,0.262889,0.105954,-0.097930,-0.084176,0.372161', '25978126', '6722730', '25721544', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578502', '异形大战铁血战士2', '动作', '恶战结束，两名铁血战士带着死去同伴的尸体向家乡返航。令他们想不到的是，死去同伴的身体竟成为异形幼卵的栖息地，成熟的异形破胸而出，并且兼具异形和铁血战士的强大威力，成为了连铁血战士也难以撼动的终极异形。一场残酷的杀戮随即在飞船上进行，最终导致飞船坠毁在科罗拉多州的群山之中。幸存的异形逃出飞船，并开始恐怖的繁殖，而附近的康尼森小镇的居民也不可避免地成为异形狩猎和寄生的对象，原本宁静祥和的小镇变成了恐怖的人间地狱。与此同时，一个留在地球的铁血战士获知了同伴死前发出的信息，他决定与这群宿命的恶魔敌人奋战到底……©豆瓣', '史蒂文·帕斯奎尔', '科林·施特劳斯', 5.9, 34338, 'tt0758730', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167448161.jpg', 5.5, 22.2, 48.7, 16.7, 6.8, '0.169583,0.082015,-0.809147,0.636316,-0.153614,0.118000,1.205163,-0.211841,-0.256076,0.152338,0.724955,0.716772,0.192218,0.124434,0.330211,-0.457045,-0.053429,-0.417255,-0.405646,0.078652,-0.601904,-0.073721,-0.547345,-0.509251,0.316072,-0.686665,1.149808,0.427040,-0.144948,0.431848,0.009313,0.412296,-0.376093,0.351366,-0.401739,-0.193443,-0.259138,-0.414328,-0.272037,0.268561,-0.272077,-0.148654,-0.009721,0.144945,-0.394749,0.163009,1.081593,-0.709827,-0.000463,-0.433988,0.258720,-0.440022,0.053179,0.149872,0.539223,-0.032250,-0.119966,-0.019307,0.293212,0.122513,0.010573,0.160671,-1.130531,-0.007342,-0.109177,0.129063,-0.399439,0.471070,0.168130,0.144026,0.253043,-0.239284,0.210910,0.123578,0.086686,0.558890,-0.328780,0.194348,-0.555058,-0.024802,0.923252,-0.169112,-0.772356,-0.125226,-0.037862,-0.870157,-0.370926,-0.652572,-0.216905,-0.183516,0.428175,0.382948,-0.241705,0.515509,-1.124770,0.094333,-0.332673,-0.506700,-0.114718,-0.147736,-0.378017,-0.795389,-0.115435,-0.111528,-0.195555,0.367741,0.027285,-0.063489,0.948320,-0.793696,0.326943,0.554137,0.422692,-0.362167,0.311967,-0.307122,0.231087,0.064426,0.074226,0.386208,0.217531,0.542338,0.400485,0.195300,-0.253772,0.056214,-0.431888,0.634563', '26667010', '21619567', '25774050', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578503', '美国黑帮', '剧情', '上世纪70年代，哈莱姆黑人区，弗兰克•卢卡斯（丹泽尔•华盛顿 饰）是黑帮老大约翰逊的司机。约翰逊暴毙后，弗兰克充分利用了这个来之不易的机会，将地下世界的所有权利分配进行了重组，成功上位，接手大佬事业，掌控了毒品交易大权。期间他远赴东南亚金三角走私高纯度海洛因，张罗自己的家族兄弟，集结了一帮为他卖命的手下，一股黑暗势力正在兴起。另一边，警察里奇•罗伯茨（卢塞尔•克劳 饰）家庭破裂，与主流社会格格不入，整天以一副邋遢鬼模样流连于街头。他慢慢觉察出毒品圈内的风起云涌，，并展开了秘密调查。随着调查的深入，罗伯茨和卢卡斯之间的距离越来越短，两个气质相近，惺惺相惜的男人，不可避免地进行正面对决……©豆瓣', '丹泽尔·华盛顿', '雷德利·斯科特', 7.9, 50601, 'tt0765429', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p452255500.jpg', 0.3, 1.3, 22.4, 53.5, 22.5, '0.275330,0.084271,-0.681729,0.353153,-0.093538,-0.133039,0.460396,0.255833,-0.520398,-0.124957,-0.097943,0.601739,-0.102147,-0.063847,0.229180,-0.127113,-0.412368,-0.912663,-0.242348,-0.134231,-0.007542,-0.481815,-0.534049,-0.435283,-0.271204,-0.074548,0.447406,-0.003789,-0.248273,0.254952,0.152723,0.204632,-0.160166,0.242930,0.008699,-0.262838,0.474358,-0.307732,-0.543077,0.082497,-0.040006,-0.097497,0.111714,-0.011729,0.139690,0.320004,0.484852,0.018850,0.208269,-0.328250,0.294076,-0.041660,-0.128450,-0.059867,0.384136,0.048028,0.080991,0.291585,-0.112887,-0.299692,0.006270,-0.092574,-0.514136,0.118966,-0.031213,0.164840,-0.402349,0.403732,0.000172,-0.098381,-0.141414,-0.367354,0.193539,0.468697,0.452872,0.031461,0.090255,0.024021,-0.386404,0.060076,0.565519,0.061098,-0.189384,-0.104059,-0.195961,-0.379847,-0.314175,-0.273241,-0.250407,-0.470682,0.396309,-0.178841,0.216353,0.602102,-0.647736,0.096454,-0.290799,-0.172401,0.059562,-0.150720,0.087773,-0.885901,-0.420388,-0.373398,-0.094331,0.039989,0.145822,-0.078772,0.497194,-0.422277,0.018725,0.750885,0.321573,-0.496556,0.378837,0.067647,0.419832,-0.537738,-0.305347,0.254871,0.164479,0.221082,0.202543,0.279338,-0.263514,-0.044370,0.032757,0.315217', '25723905', '2973528', '11541282', '4014397');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578507', '谍影重重3', '动作', '失去了心爱的女人，波恩（马特•戴蒙 饰）面临更为艰难的日子，他努力回忆，却只能在睡梦中被脑海里一知半解的闪回所惊醒，依然无法记起自己的身份。但是波恩注定不是平凡人，不等他冷静下来好好“寻找回”自己真正的身份，中情局派出的杀手又接踵而至。在接连的几次较量之后，杰森•伯恩终于被彻底激怒，决定反戈一击——他主动追击杀手，到过莫斯科、马德里。巴黎，也在伦敦和丹吉尔做过停留。随着问题一个一个解决，杰森回到了纽约，在那里，他将会找到一切的答案，寻回自己的身份。©豆瓣', '马特·达蒙', '保罗·格林格拉斯', 8.8, 393097, 'tt0440963', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p792223507.jpg', 0.1, 0.4, 9.1, 38.6, 51.7, '0.320718,0.282163,-0.913730,0.512689,-0.293437,-0.380573,0.741278,-0.165924,-0.648507,-0.381370,0.126276,0.798246,-0.011008,0.366576,0.268850,-0.023210,-0.323922,-0.880307,0.355962,-0.206860,-0.263615,-0.513104,-0.310182,-0.244120,-0.033133,-0.090437,0.677186,0.183039,-0.150317,0.130816,0.245028,0.368968,0.177965,0.651821,-0.262522,0.170083,0.045625,-0.140957,-0.253782,0.506517,0.350694,-0.558079,-0.271428,0.510818,-0.042061,0.291386,0.653001,-0.219060,-0.188021,0.118764,0.106279,-0.584146,-0.056625,0.250725,0.142800,0.087304,-0.085721,0.256074,-0.469520,0.037761,-0.066561,0.085769,-0.807782,0.041210,0.107479,0.309786,-0.800585,0.248920,-0.309393,0.172918,0.019774,-0.530993,0.169439,0.342183,0.279828,0.189193,-0.400670,-0.078131,-0.549167,0.147432,0.904729,-0.034867,-0.167260,0.383057,0.173234,-0.205206,0.047786,-0.290515,-0.265528,-0.080363,0.352996,0.353981,-0.451207,0.199064,-0.186531,-0.207376,-0.529808,-0.637473,-0.084863,-0.565677,-0.037536,-0.333400,-0.381349,-0.161789,-0.274564,0.079722,-0.249596,-0.084978,0.476761,-1.061270,0.145090,0.722350,0.260079,-0.425273,0.236364,0.090254,0.174925,-0.121215,0.414181,0.387085,0.167756,0.272666,-0.006674,0.143739,0.048649,0.170367,-0.593580,0.635268', '1301022', '30345227', '1870682', '30210700');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578509', '蝴蝶效应2', '剧情', '尼克（Eric Lively 饰）与好友们一起在郊外为女友茱莉（Erica Durance 饰）庆祝生日，但是在返回的路上发生了车祸，茱莉不幸重伤身亡，尼克悲痛万分。很快一年过去了，有一天尼克发现自己可以通过看老照片的方法重返过去。就这样，他利用自己的超能力改写了历史，让茱莉躲过了灾难。虽然女友的复活令尼克兴奋异常，但生活的烦恼依旧接踵而至。因为有了之前的经验，尼克不断改变历史，以期生活可以按照自己的思维发展。但结果往往事与愿违，总会出现更大的问题。尼克会接受命运的安排吗？©豆瓣', '埃里克·里夫利', '约翰·R·莱昂耐迪', 6.2, 65993, 'tt0457297', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1863331764.jpg', 4.1, 18.3, 49.7, 20.4, 7.6, '0.092547,0.098320,-0.434242,0.310099,0.080513,-0.236177,0.549431,-0.001453,-0.600077,-0.344911,0.055219,0.737630,-0.223300,0.165337,0.531177,-0.287363,-0.424758,-0.623382,0.502888,-0.025811,-0.544482,-0.603402,-0.210162,-0.334668,-0.041077,-0.457766,0.719435,0.209081,0.059819,0.625062,-0.125254,0.279238,0.120987,0.515521,-0.083192,0.199901,0.077820,0.141217,-0.252945,0.382380,0.358264,-0.257750,0.015799,0.273263,-0.059936,0.197741,0.618154,-0.272697,-0.535217,0.048888,0.438435,-0.319143,-0.174237,0.128773,0.183667,0.053020,0.090263,0.170817,-0.286001,-0.023024,0.039384,0.210575,-0.772878,0.136450,-0.025097,0.118077,-0.643641,0.322549,0.133621,0.014501,0.132468,-0.366898,0.232337,0.858545,0.624677,0.290194,-0.545986,-0.013840,-0.544610,0.007868,0.831756,-0.050273,-0.291181,0.475055,-0.382519,-0.078629,-0.071334,-0.161554,-0.210986,0.282440,0.200447,0.288385,-0.458124,0.540276,-0.383779,-0.028132,-0.399817,-0.218413,-0.075723,-0.476041,-0.032128,-0.666641,-0.115248,-0.210072,-0.508738,-0.177004,0.056498,-0.572609,0.671398,-0.935983,0.243871,0.403951,0.215878,-0.478199,0.594703,0.241373,0.143045,-0.147600,0.130514,0.405811,-0.135807,0.318421,-0.095968,0.231340,0.311925,-0.316530,-0.353288,0.658847', '35030151', '30345227', '26971054', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578510', '小飞侠', '喜剧', '两父子谢峻（卢惠光饰）、谢飞（谢苗饰）号称是世界上武功最高的父子，果不其然，他们勇闯虎穴打败独角猩猩兽，救出了被关在山中的小公主。其实只是他们的一场英雄美梦。一日，谢父正在教授村民功夫时，突然接到师公的求救信号。为了满足师公的心愿，谢飞和父亲谢峻只好偷渡来到香港。当两人前去解救时，发现师公已被关进精神病院。不仅如此，父子二人还莫名其妙地被卷入一起抢劫珠宝杀人案中。在警察的追捕中，父子失散。在香港这个复杂的花花世界里，失散后的父子俩发生了一段段有趣的故事。©豆瓣', '谢苗', '林伟伦', 6.9, 14628, 'tt0115001', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2339592543.jpg', 1, 6.1, 51.9, 30.5, 10.5, '0.231142,-0.083547,-0.723857,0.352379,0.161923,-0.300865,0.553481,-0.099376,-0.773136,-0.235453,0.342673,0.643446,-0.157281,0.397879,0.284150,-0.003920,-0.302191,-0.682890,-0.107809,-0.394731,-0.232184,-0.332785,-0.177218,-0.009024,0.063792,-0.231165,0.381499,0.195024,-0.118137,0.643662,0.122153,0.009512,-0.803028,0.504566,-0.087472,0.350857,0.373913,0.278259,-0.304779,0.133612,-0.079410,0.002713,0.036444,-0.334702,-0.048998,0.103207,0.542826,-0.558866,-0.068155,-0.198447,-0.010238,-0.350635,-0.210704,0.196570,0.620104,0.017995,0.595292,0.093206,-0.287891,-0.109583,-0.023651,-0.008580,-0.427904,0.170948,0.161183,-0.014105,-0.614862,0.322420,0.118149,0.111036,0.201173,-0.240911,0.456238,0.471319,0.417190,0.489497,-0.133977,0.013969,-0.368248,0.066854,0.837457,-0.370677,0.093474,0.048621,0.318788,-0.315852,0.233900,-0.087866,-0.083667,0.070537,0.531841,-0.140685,-0.231936,0.242859,-0.541778,-0.090528,-0.387208,0.218753,0.056880,-0.280952,-0.092488,-0.531477,-0.022036,-0.103352,-0.046991,0.070198,0.178486,-0.259174,0.400679,-0.583795,0.357734,0.278977,0.139370,-0.169086,0.643324,-0.081722,0.284634,-0.143794,-0.180748,-0.112822,0.408420,0.393593,0.175659,0.251346,-0.150206,-0.165441,-0.369692,0.048901', '25856453', '1451563', '2365079', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578643', '灵数23', '剧情', '沃尔特（金•凯瑞 Jim Carrey 饰）本来过着幸福的田园生活，直到有一天他和“23”这个数字扯上了关系，他的生活彻底发生了改变。妻子阿加莎送了一本名为《数字23》的小说给沃尔特作为生日礼物，这本书看来平凡无奇，描述的是一个侦探遭遇了23场杀人梦魇，“23”这个数字就像枷锁一样牢牢控制住他的生活，最后他亲手杀了自己妻子。沃特尔惊奇地发现书中描写的很多情景和生活细节竟然和自己的生活一摸一样，既有过去的，也有即将发生的。小说的情节好像推动着他的生活一步步滑向最后的深渊――他亲手杀死了自己的妻子。为了避免这一结局，沃尔特只有找出这些事件和“23”背后的真相！©豆瓣', '金·凯瑞', '乔·舒马赫', 6.5, 16062, 'tt0481369', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167452926.jpg', 1.8, 11.5, 52.8, 27.5, 6.4, '0.318159,-0.027688,-0.633080,0.719349,-0.066431,-0.147835,0.941251,0.006220,-0.162341,-0.367555,0.150097,0.800543,-0.141219,0.322464,0.093139,0.220347,-0.302562,-0.901920,0.012262,-0.075948,-0.345130,-0.309916,-0.344397,-0.167272,0.138434,-0.173072,0.646149,0.086003,-0.287111,0.169890,0.149413,0.416061,0.055886,0.420927,-0.372353,0.354434,-0.144354,0.219166,-0.125506,0.055873,0.070635,-0.122722,-0.013781,0.361435,-0.069188,0.360480,0.699775,-0.528072,-0.487170,0.099718,0.532711,-0.342580,-0.210940,-0.090299,0.032510,0.125640,0.044483,0.014358,-0.127344,-0.068561,0.179326,-0.158901,-0.950060,-0.334814,0.054323,0.218005,-0.569737,0.316864,-0.070683,0.111198,-0.036555,-0.295457,0.253573,0.378290,0.513237,0.242453,-0.297590,0.009397,-0.654262,0.315101,0.685316,0.033533,-0.383812,0.543529,-0.445228,-0.206282,-0.280937,-0.215987,-0.358280,0.293121,0.470006,0.136840,-0.578371,0.373886,-0.499532,-0.060749,-0.155005,-0.283765,0.116606,-0.614740,-0.213903,-0.286901,-0.350399,-0.466325,-0.487143,-0.316388,-0.065370,-0.706130,0.664175,-0.445453,0.244781,0.639104,0.066580,-0.410598,0.665347,0.284235,0.008999,0.057223,0.229375,0.231914,0.064615,0.342593,0.204130,0.326809,0.197643,0.056390,-0.465514,0.964513', '1296757', '25763555', '35158375', '1793912');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578646', '勇敢的人', '剧情', '即便是号称不夜城的纽约，遍布全市的霓虹灯也无法照亮夜幕中的每个角落，电台节目主持人艾瑞卡（朱迪•福斯特 饰）和恩爱的未婚夫（尼维•安德鲁斯 饰）就在某个夜晚误入了最肮脏的黑暗世界，被一伙暴徒围攻，艾瑞卡被打成重伤，未婚夫惨遭杀害。伤愈之后的艾瑞卡找到警探朋友，也是她忠实的听众梅瑟（特伦斯•霍华德 饰），要求他主持正义，但这个被无数罪案搞得焦头烂额的人，无法把全部精力投入到艾瑞卡的案子上，愤怒的艾瑞卡决定自己解决问题。她从黑市买了一把枪，成为了“暗夜复仇者”，惩罚逃脱法网的罪人。这一切，引起了梅瑟的注意，他所代表的法律的正义显然不能认同艾瑞卡的做法，二人之间的矛盾终将爆发……©豆瓣', '朱迪·福斯特', '尼尔·乔丹', 7.3, 9926, 'tt0476964', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1257556594.jpg', 0.4, 3.9, 39, 43.5, 13.2, '0.465857,0.210214,-0.694326,0.484181,-0.119880,-0.266940,0.563358,0.198383,-0.257021,-0.178974,0.161349,0.492930,-0.230143,0.083791,0.307126,0.106633,-0.243288,-0.744562,-0.185482,-0.236005,-0.323203,-0.588999,-0.118073,-0.350569,-0.226196,-0.140072,0.403807,0.262717,-0.226673,0.095749,0.519784,0.364116,0.079449,0.421090,-0.096401,-0.106331,0.363392,-0.245904,-0.165220,0.456053,-0.110868,-0.178986,0.106469,0.551479,-0.102061,0.220238,0.701606,-0.315559,0.080710,0.018912,0.548114,-0.575731,0.097845,0.078937,0.466157,-0.236983,-0.145896,-0.153266,-0.191842,-0.024292,0.398919,0.046051,-0.811849,-0.213809,0.117175,0.199212,-0.587519,0.408862,0.017925,-0.081845,-0.048768,-0.095471,0.384850,0.067740,0.269256,0.230562,0.092989,-0.041793,-0.563695,0.159917,0.642959,-0.167658,-0.278064,-0.017957,-0.558150,-0.513182,-0.063634,-0.150210,-0.517698,-0.339723,0.594799,-0.142737,-0.062225,0.664875,-0.476918,-0.092980,-0.328563,-0.214044,-0.393358,-0.331466,0.167084,-0.414151,-0.397514,-0.170470,-0.104068,0.195448,-0.013259,0.003184,0.486413,-0.511021,0.416996,0.448390,0.217200,-0.037321,0.507833,0.076722,0.242322,-0.174239,-0.155866,0.265170,0.482181,0.334623,0.337143,0.174422,0.186318,-0.265159,-0.308928,0.497516', '25828589', '26747274', '1307311', '1422957');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578663', '非礼勿视', '惊悚', '八个感化院的青年在两名警官的监督下，前往乡间一所破败的客栈中接受社区服务，但是他们的到来却无意中惊醒一个沉寂已久的恶魔。雅克布•古德奈特 饰（Glen Jacobs 格兰“凯恩”雅克布 饰），身高七英尺，体重四百磅，头骨里嵌着一个生锈的铁盘，锋利的指甲足够戳穿对手眼睛的精神病患者。雅克布四年前曾被警官弗兰克•威廉姆斯（Steven Vidler 饰）枪击头部，却侥幸逃生。如今弗兰克正是这群青年的督导员。弗兰克和孩子们的出现激起了雅克布屠杀的欲望，他举起巨斧，将客栈变作血腥的屠宰场……©豆瓣', 'Glen Jacobs', '葛雷格瑞·达克', 6.2, 10372, 'tt0437179', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204598171.jpg', 3.1, 16.8, 55.4, 18.1, 6.5, '0.358690,-0.041649,-0.384651,0.318179,-0.231944,-0.267102,1.350694,0.243098,-0.097864,-0.256700,0.598149,0.386043,-0.244839,0.257733,0.182749,-0.043050,-0.034814,-0.663969,-0.375881,-0.179650,-0.338835,-0.282843,-0.567931,0.062244,0.018615,-0.318171,0.391328,-0.012073,0.144653,0.585787,0.124211,0.361688,0.189777,0.004686,-0.214118,-0.082621,0.154463,-0.458618,0.078979,0.182323,-0.226466,-0.019527,0.094893,0.243444,-0.171782,0.584134,0.757022,-0.290267,0.278068,-0.162244,0.131023,-0.004556,-0.133036,0.432134,0.425842,-0.000512,0.070854,-0.205543,-0.160572,0.111267,0.312524,-0.044457,-0.468604,0.103352,-0.123551,0.301641,-0.858789,0.382860,-0.183199,0.077951,-0.230906,-0.151347,0.068614,-0.086751,0.040914,0.265168,-0.219197,-0.070103,-0.657010,-0.115389,0.235285,-0.239219,-0.296028,-0.368484,-0.308318,-0.420994,-0.016530,0.092620,-0.341782,-0.236325,0.588997,-0.182094,-0.121545,0.065803,-0.722582,-0.091479,-0.733189,-0.096641,-0.226536,0.051432,-0.466080,-0.557268,0.218010,-0.162815,-0.357141,0.115932,0.100598,-0.049836,0.401453,-0.313671,0.272952,0.336419,0.149717,0.400366,0.525270,-0.060118,0.390861,0.098348,-0.315643,0.146604,0.243620,0.251666,0.245079,0.767520,-0.168394,-0.256551,-0.399601,0.522760', '21619567', '1467779', '20451118', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578669', '黑色大丽花', '剧情', '布奇（乔什•哈奈特 Josh Hartnett 饰）和李（艾伦•艾克哈特 Aaron Eckhart 饰）都是拳击界的佼佼者，李被称为“火先生”、而布奇则被称为“冰先生”。李在警局执行组，而布奇则比较落魄。在警局举行的一场拳赛上，布奇故意输给了李，以此跻身了警局，成为李的搭档，两人更成了无话不谈的好友。两人奉命调查一个叫纳什的家伙犯下的连环凶杀案，在一次埋伏行动中，李为了救布奇射杀了一名监视的疑犯，但却没抓到纳什。随后两人在现场附近发现了被称为“黑色大丽花”的肖特的尸体，肖特死因恐怖。李很快就放弃了调查纳什一案，而集中精力一人追查肖特的案件，而当年被李抓获的抢劫银行犯鲍比提早出狱也让李感到焦头烂额。布奇为了帮助搭档，自己也开始着手调查，然而，随着调查的深入，真相逐渐浮出水面之际，却发现了李身后不为人知的秘密。©豆瓣', '乔什·哈奈特', '布莱恩·德·帕尔玛', 6.5, 33314, 'tt0387877', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1461667933.jpg', 1.6, 11.8, 54, 26.8, 5.8, '0.292481,0.124132,-0.758019,0.634089,-0.138190,-0.431124,0.887105,-0.068300,-0.153826,-0.597894,0.127919,0.205169,-0.472972,0.296647,0.227963,-0.482806,-0.137079,-0.722438,-0.253097,-0.213337,-0.763766,-0.430934,-0.336853,-0.357984,-0.221825,0.094294,0.479561,0.215875,-0.398599,0.217694,0.454945,0.552789,0.049419,0.471058,-0.011718,-0.017903,0.400725,0.242422,-0.016857,0.124537,0.250749,-0.849755,-0.059579,0.066031,0.249878,0.555067,0.678714,-0.130137,-0.042847,-0.223999,0.103434,-0.530668,0.062586,-0.075855,0.837572,-0.165711,-0.177736,-0.160270,-0.198817,-0.540605,0.032708,-0.034172,-0.731934,0.138573,0.312402,0.264035,-0.431504,-0.404372,-0.403361,0.284693,-0.082630,-0.457072,0.275100,0.456201,0.421514,0.191919,0.124578,0.052627,-0.609998,0.214164,0.888419,0.014667,-0.139773,-0.412430,-0.025667,-0.472080,0.103768,0.160957,0.060952,-0.077679,0.784416,-0.274135,0.294301,0.278742,-0.220183,-0.457333,-0.166472,-0.227739,-0.226198,-0.429346,0.236725,-0.806003,-0.135483,-0.147694,0.005328,0.231042,0.006194,-0.345685,0.191967,-0.486313,0.321400,0.241764,-0.058356,-0.510190,0.453103,-0.046869,0.291977,-0.322216,0.223195,-0.014697,0.716612,0.211967,0.608978,0.623312,-0.066451,-0.266854,-0.338630,0.239188', '25870679', '1304642', '4903581', '26897427');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578685', '亚瑟和他的迷你王国', '家庭', '为了保住外婆的花园，十岁的亚瑟（弗莱迪·海默 Freddie Highmore 饰）必须找到外公失踪前留下的财宝。按照外公留下的提示，亚瑟终于找到了每年只打开一次的月光之门，进入了迷你墨王国，见到了外公笔记里的美丽的塞琳娜公主和迷你墨人，从他们口中得知四年前外公为了寻找宝藏走入了禁忌城，而统治那里的是“邪恶的M”。在与闯入的敌人战斗时亚瑟从石头里拔出了力量之剑，成为了迷你墨王国的英雄。神剑拔出，迷你墨王国的英雄们必须前往奈克罗鲍利——禁忌城打败“邪恶的M”。亚瑟、塞琳娜公主、王子倍塔克服重重困难终于抵达了M的老巢，传说中的恶魔玛塔扎德就住在这里……本片是吕克·贝松的第十部电影，传说是他的“收山之作”，历时七年的筹备制作过程，投资达6500万欧元，是法国电影制作史上最昂贵的作品。©豆瓣', '弗莱迪·海默', '吕克·贝松', 7.4, 48815, 'tt0344854', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209903027.jpg', 0.5, 3.5, 37.3, 42.9, 15.8, '-0.135494,0.372138,-0.285865,0.610046,0.214683,-0.330919,0.484981,-0.069126,-0.223375,-0.314540,0.250610,0.664678,0.102907,0.221928,0.261056,0.204672,-0.329846,-0.529766,-0.218637,-0.473614,-0.247117,-0.228766,-0.460968,-0.063455,-0.101901,-0.650120,0.675469,0.157536,-0.324439,0.142198,0.278142,0.329573,-0.281276,0.170600,-0.256194,-0.159429,0.027809,-0.038899,-0.393212,0.402876,-0.047359,-0.011470,0.003142,0.104089,0.393058,0.135244,0.540927,-0.740259,0.261109,-0.154090,0.337286,-0.335061,-0.346849,-0.209437,0.218111,-0.009288,0.255364,0.133216,-0.334784,-0.134684,0.043771,-0.496691,-0.797925,-0.262772,0.120884,0.038786,-0.722904,0.168598,-0.223429,0.105479,0.280908,-0.380604,0.432658,0.327487,0.088913,0.158839,-0.170286,-0.184171,-0.621843,0.130658,0.480740,-0.360551,-0.104783,0.060854,0.077486,-0.510777,-0.075023,-0.261082,-0.166035,0.231478,0.445641,-0.053130,0.093445,0.310012,-0.864137,-0.467884,-0.591325,-0.240705,0.425345,-0.441674,-0.356726,-0.525815,0.006491,0.025067,-0.034552,-0.031540,-0.042868,-0.291543,0.663741,-0.670538,0.313391,0.251736,0.408778,0.067494,0.728898,-0.394680,0.157840,-0.201602,-0.072043,0.425633,0.133093,0.393818,0.055966,0.240676,0.000100,-0.312780,-0.603469,0.572123', '24750460', '26290398', '1308585', '19899707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578698', '言语的秘密生活', '剧情', '独来独往的工厂女工汉娜（萨拉·波莉 Sarah Polley 饰），由于听力不好而总是戴着助听器。不善交际的她在工作上一直任劳任怨，终于在数年后得到了第一个假期。然而出乎众人意料的是，一时间具足无措的她居然主动放弃了这个难得的机会，自愿前往一间海上石油钻井平台，照顾一位在事故中被严重烧伤暂时失明的男人约瑟夫（蒂姆·罗宾斯 Tim Robbins 饰）。与世隔绝、荒凉枯燥的钻井平台，两颗饱受痛苦往事折磨的孤独灵魂，一段交织在秘密与真相间的微妙亲密关系。在汉娜的悉心照料下，约瑟夫终于敞开心扉，与此同时，汉娜也打破沉默，向他讲述起自己不为人知的凄惨遭遇。©豆瓣', '萨拉·波莉', '伊莎贝尔·科赛特', 8.3, 5810, 'tt0430576', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1284465342.jpg', 0.5, 1.5, 14.8, 49, 34.2, '0.017213,0.138505,-0.802797,0.389803,-0.046541,-0.234409,0.939427,-0.014487,-0.675767,-0.200591,0.206778,0.531599,-0.204885,0.323143,0.270168,0.002562,-0.349511,-0.674439,-0.108121,-0.084159,-0.437305,-0.495324,-0.398397,-0.425510,-0.214530,-0.415364,0.475107,0.222412,-0.160688,0.353199,0.232560,0.413247,-0.276983,0.625551,-0.021276,-0.227683,0.235909,0.017101,-0.160536,-0.123901,0.062014,-0.404275,-0.059442,0.263790,0.005074,0.393480,0.628426,-0.259553,-0.458513,0.233662,0.245187,-0.091276,-0.056206,0.235423,0.295738,0.100970,0.195962,0.151339,-0.535321,0.123620,0.050957,-0.074786,-0.534176,0.035887,0.048924,0.241922,-0.318709,0.660862,-0.011670,-0.173624,-0.040651,-0.485386,0.006987,0.429366,0.365391,0.516228,-0.561788,0.256054,-0.024564,0.098609,0.626790,0.140446,-0.337456,0.388745,-0.246486,-0.280561,-0.079667,-0.139361,-0.645805,-0.245677,0.337986,0.121942,-0.178156,0.375109,-0.582173,0.039457,-0.242623,-0.240475,-0.114323,-0.144005,-0.307330,-0.552120,-0.067596,-0.259949,-0.368729,0.305362,-0.079397,-0.159631,0.447594,-0.680905,0.438663,0.442425,-0.037115,-0.146742,0.536358,-0.061163,0.286288,-0.048017,-0.068282,0.613414,-0.116729,0.178410,0.116249,0.447716,-0.059356,0.140913,-0.632928,0.447558', '1309172', '1292211', '21348112', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1578714', '神奇女侠', '动作', '戴安娜（盖尔·加朵 Gal Gadot 饰）是女王希波吕忒（康妮·尼尔森 Connie Nielsen 饰）的女儿，自幼生活在天堂岛上。巨大的屏障将这座岛屿同外界的纷纷扰扰隔开犹如一个世外桃源，而岛上生活着的亦都是女性。在女武官安提奥普（罗宾·莱特 Robin Wright 饰）的教导之下，戴安娜习得了高强的武艺，而她的体内，似乎隐藏着某种强大的未知力量。一场意外中，一位名为史蒂夫（克里斯·派恩 Chris Pine 饰）的男子来到了岛上，从他口中，戴安娜得知外面的世界正在经历战争的磨难，而造成这一切的罪魁祸首，是战神阿瑞斯（大卫·休里斯 David Thewlis 饰）。为了拯救人类于水火之中，戴安娜依然拿起了长剑与盾牌，发誓要彻底摧毁阿瑞斯的阴谋。©豆瓣', '盖尔·加朵', '派蒂·杰金斯', 7.1, 451808, 'tt0451279', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2460006593.jpg', 1.6, 7.8, 39.4, 37.4, 13.9, '0.102134,0.142930,-0.572941,0.735045,-0.139590,-0.043126,0.919943,0.074255,-0.381283,-0.261304,0.479751,0.696011,0.047568,0.186460,0.412779,0.166524,-0.233989,-0.621263,-0.221034,-0.162365,-0.325951,-0.391979,-0.596445,-0.189929,-0.183936,-0.730258,0.485802,-0.022236,-0.139339,0.228373,0.245781,0.436828,-0.280883,0.332741,-0.177947,-0.142387,-0.103246,0.029653,-0.372201,0.158719,-0.062832,-0.248870,-0.196612,0.545596,-0.154357,0.075675,0.604211,-0.613971,0.293768,-0.413355,0.256749,-0.147936,0.139926,0.061816,0.227986,-0.115593,0.033698,0.197787,-0.071946,0.087282,0.481111,-0.332868,-0.560964,-0.145908,0.159462,0.133734,-0.431850,0.439050,-0.024871,-0.156389,0.004083,-0.205727,0.116910,0.070601,0.272065,0.422743,-0.200752,-0.134634,-0.531117,0.044370,0.506384,-0.073737,-0.547414,0.042838,-0.353482,-0.290195,-0.267089,-0.172765,-0.654936,-0.104022,0.271671,0.159841,-0.073830,0.609200,-0.672899,0.016585,-0.448833,-0.062534,-0.181206,-0.324937,-0.217770,-0.639315,-0.277843,-0.442452,-0.085010,-0.003024,0.077037,-0.139434,0.705076,-0.744332,0.374931,0.524325,0.121240,-0.123450,0.393862,-0.088578,0.292351,-0.118774,-0.199727,0.490823,0.020022,0.282474,-0.010496,0.340378,0.035038,-0.059396,-0.300599,0.684362', '4126925', '6021916', '35161768', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1580620', '美人鱼', '喜剧', '少女克莱尔（艾玛·罗伯茨 Emma Roberts饰）和海莉（乔安娜·利维斯克Joanna ''JoJo'' Levesque饰）是一对靓丽活泼的好友。海莉的母亲是海洋生物学家，她开学之后就要随同家人离开美国前往澳洲。两个好姊妹的即将天各一方，她们趁着这个暑假来到海滩上尽情游玩，心里盼望着一起的日子可以长些，再长些。在这里，她们碰到了一件怪事：一条传说中的美人鱼阿夸玛（萨拉·帕克斯顿 Sara Paxton 饰）闯进了她们的生活。原来，阿夸玛顺着洋流来到这里，是为了在三天内找到人间真爱。否则，她将被迫嫁给一个不爱的人。而潜水救生员雷蒙德（杰克·麦克道曼 Jake McDorman 饰），正是她心中的白马王子。阿夸玛请教克莱尔和海莉，如何才能赢得王子的心。然而，情窦初开的两个姊妹，心中也对雷蒙德这个帅哥心旷神怡，加上风骚的情敌赛西莉亚（阿莉尔·凯贝尔 Arielle Kebbel 饰）的干扰，这个夏天的海滩就要好戏连连了。', '艾玛·罗伯茨', '伊丽莎白·艾伦', 6.6, 37747, 'tt0429591', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1194162603.jpg', 1.2, 9.2, 54.9, 26.1, 8.6, '0.325517,-0.239657,-0.580699,0.573052,-0.047028,-0.531800,0.750191,-0.148452,-0.346128,-0.194784,-0.000223,0.778605,-0.469081,0.598970,0.488572,0.380195,-0.492828,-0.559434,0.057633,-0.223073,-0.197851,-0.317651,-0.228770,-0.101741,0.012755,-0.072857,0.500075,-0.016668,0.202682,0.718870,0.293627,0.121866,0.041769,0.245059,-0.319049,0.010419,0.002315,-0.050937,-0.243750,0.340280,0.264269,0.058490,-0.010042,0.176993,0.223552,0.116923,0.583669,-0.354077,0.105609,0.003129,0.278592,-0.279570,0.187470,0.212037,0.063825,-0.365860,0.267728,-0.036737,-0.299792,0.117871,0.130619,-0.210016,-0.200675,0.311979,-0.114587,-0.016243,-0.419093,0.161497,-0.039700,-0.323014,0.261618,-0.257219,0.274419,0.430379,0.212793,0.351068,-0.204498,-0.056722,-0.391373,-0.006942,0.731742,0.143637,0.006466,0.305303,-0.040189,-0.287774,0.083687,0.009525,-0.486748,-0.029147,0.301446,-0.015061,0.021678,0.096388,-0.545749,0.109482,-0.336668,-0.116096,0.072161,-0.334360,-0.268762,-0.499652,-0.049037,-0.434344,-0.234736,0.269239,0.040664,-0.207343,0.548072,-0.713796,0.181843,0.437672,0.326282,-0.511962,0.662907,0.064727,0.216794,-0.237858,0.083241,0.380206,-0.060505,0.023576,-0.048854,0.414253,-0.029012,-0.037611,-0.42