INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1584750', '神奇四侠2', '动作', '在第一集解决了“毁灭钢眼博士”后，“神奇四侠”已经逐渐适应了新的身份，队员们的生活亦过得有滋有味 。里德（尤安·格瑞福德 Ioan Gruffudd 饰）和苏珊（杰西卡·阿尔芭 Jessica Alba 饰）终于步入教堂，然而，正当婚礼进行到一半时，突然狂风大作，一道银 色闪电在天空闪过。里德忙叫“霹雳火”（克里斯·埃文斯 Chris Evans 饰）追上去看过究竟，熟料“霹雳火”完全不是对方对手，里德的担忧变成了现实：新的敌人出现了――“银影侠”（道格·琼斯 Doug Jones 饰）！世界各地开始灾难不断。通过调查，苏珊发现“银影侠”只不过受“行星吞食者”盖拉克图斯所迫，帮其在宇宙寻找可供其吞食的星球，今次的目标正是――地球！“神奇四侠”又出动了，这次能否帮助可怜的“银影侠”、成功挽救地球？©豆瓣', '艾恩·格拉法德', '蒂姆·斯托瑞', 6.5, 95701, 'tt0486576', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p739461553.jpg', 1.6, 10.9, 57.2, 23.2, 7.2, '0.032851,0.320820,-0.518924,0.287705,0.156264,-0.286192,0.544663,0.108130,-0.041313,-0.171733,0.224385,0.419710,-0.159053,-0.013821,0.439097,0.061746,-0.426021,-0.461525,0.108757,-0.166288,-0.364700,-0.341482,-0.480734,-0.183983,0.074182,-0.638122,0.559386,0.048056,0.106312,0.238611,0.079092,0.455119,-0.039177,0.442067,0.038483,0.061339,0.043349,-0.006084,-0.397550,0.281981,-0.223656,0.006237,-0.259986,0.010910,-0.011657,0.336477,0.586456,-0.265031,0.079050,-0.108413,0.303365,-0.208983,0.173458,-0.073428,0.296554,0.014710,-0.116220,-0.140659,-0.028264,0.201675,0.030989,-0.077164,-0.576585,0.213703,0.031960,0.130563,-0.344520,0.064609,-0.201905,-0.153012,0.010584,-0.273555,0.013448,0.416042,0.241333,0.344676,-0.131870,0.042863,-0.374350,0.050787,0.380897,-0.076269,-0.447182,0.281059,0.003900,-0.259213,-0.112806,0.001925,-0.093038,-0.123979,0.645497,0.291457,-0.181535,0.542780,-0.644332,-0.132232,-0.432181,-0.410929,-0.064199,-0.220629,-0.200297,-0.695846,-0.241581,0.124599,-0.043512,-0.040920,-0.013745,-0.135726,0.358216,-0.834469,0.287033,0.312524,0.027478,-0.205897,0.138871,-0.125927,0.158134,-0.259141,0.052360,0.144516,0.175838,0.451241,0.045114,0.289502,0.235384,-0.104872,-0.296417,0.308231', '1306809', '1308754', '20274039', '2369613')