INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1584991', '午夜凶铃3(美版)', '剧情', '年轻女孩茱莉娅（玛蒂尔达·鲁茨 Matilda Lutz 饰）和男友霍尔特（阿历克斯·罗 Alex Roe 饰）分隔两地，相互思念。某晚在一个奇怪的梦后，茱莉娅发现霍尔特不见了踪影，视频通话中则有一个疯狂的女子咆哮质问，四下寻找霍尔特的下落。充满担忧的茱莉娅启程前往霍尔特所在的学校，并因缘际会见到了视频中的那个女孩斯盖伊，谁知更因此目睹了斯盖伊离奇的死亡。在此之后，霍尔特出现，他说自己接收了加布里埃尔教授（约翰尼·盖尔克奇 Johnny Galecki 饰）的一个实验，表面上该实验是为了证明人死后灵魂的存在，实则他们是观看那盘受诅咒的录像带，观看者在死亡前将录像转给下一个“替身”，然而死亡者接连出现。就在此时，茱莉娅也观看了这盘恐怖的录像带……©豆瓣', '玛蒂尔达·鲁茨', 'F·贾维尔·古铁雷斯', 5.2, 5191, 'tt0498381', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2376001912.jpg', 12, 34.7, 39.1, 8.8, 5.4, '0.314979,0.089405,-0.663781,0.452595,0.031646,-0.200389,0.824976,0.037544,-0.391247,-0.290876,0.293161,0.806148,-0.420923,-0.092077,0.069543,0.169036,-0.517471,-0.561131,-0.127207,-0.483682,-0.362198,-0.494245,-0.100929,0.018452,0.017495,-0.334021,0.210013,-0.360004,0.063625,0.518941,0.327531,0.301125,0.012670,0.534928,0.202156,0.221796,0.320374,0.035791,0.038862,0.470249,0.100431,-0.002505,0.065477,0.119863,0.002721,0.397998,0.666949,-0.322972,0.093823,0.087381,0.282082,-0.130059,0.024440,0.127937,0.242292,-0.136024,-0.018608,-0.249083,-0.429566,-0.175402,-0.069247,0.153642,-0.465385,0.012447,0.090864,0.500080,-0.254428,0.275166,-0.222948,-0.024166,0.110805,-0.301283,0.194356,0.236800,0.416053,0.356455,0.220071,-0.264685,-0.218837,-0.078246,0.122489,-0.049869,-0.368665,0.345822,-0.174716,-0.357075,-0.045019,0.186004,-0.561008,0.007463,0.567831,0.199757,-0.096688,0.481878,-0.650517,-0.100894,-0.440819,-0.037598,-0.049406,-0.361532,-0.477608,-0.748496,-0.176839,0.020318,-0.312128,0.005741,-0.140625,-0.517530,0.540066,-0.583172,0.499856,0.467363,0.186667,-0.051937,0.423979,-0.041979,0.003055,-0.208679,-0.025936,0.804377,0.384365,0.421031,-0.038227,0.264209,-0.124697,-0.139289,-0.658181,0.320511', '1316693', '35161768', '1309194', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1585146', '黄金罗盘', '家庭', '故事发生在一个和我们的地球很相似的世界里，那里人们的灵魂变成灵神跟随自己。莉拉自幼（Dakota Blue Richards 饰）跟随身为约旦大学校长的叔叔一起生活，她热情、勇敢且富有正义心。一天科尔特夫人（nicole kidman 饰）要到北方去，希望莉拉能伴随身边。好奇的莉拉开心地答应。临行前叔叔交给她一个黄金罗盘，告诉她世界上只有一个人能读懂。莉拉从黄金罗盘中不仅能得到所问问题的答案，还了解到了自己的身世之谜。这一路上，科尔特夫人行为诡异，莉拉还发现在特尔特夫人的一份名单上赫然写着自己失踪朋友罗杰的名字！罗杰和其他孩子一样，被诱拐到极北之地成为科学试验品。莉拉找到时机逃跑出来，自己动身前去拯救罗杰……©豆瓣', '妮可·基德曼', '克里斯·韦兹', 6.5, 84051, 'tt0385752', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193562374.jpg', 1.8, 12.4, 52.2, 25.8, 7.8, '0.212282,0.404268,-0.796457,0.470709,-0.085551,-0.131981,0.647942,-0.117044,-0.173705,-0.269611,-0.092149,0.493588,-0.047891,0.243817,0.588341,0.457880,-0.404819,-0.504984,0.216891,-0.131615,-0.590411,-0.483907,-0.227787,-0.378166,-0.277300,-0.489442,0.294851,-0.181520,0.142415,0.488009,0.020058,0.386190,-0.264867,0.371291,-0.362360,0.023284,-0.052265,-0.072574,-0.302175,0.453587,0.073256,0.148213,-0.037482,0.276848,-0.058917,0.112013,0.615515,-0.352671,0.125914,0.164864,0.242902,-0.347137,-0.098286,-0.259306,0.528550,-0.124724,-0.044828,0.097021,-0.069194,0.027688,0.066463,-0.289656,-0.546613,-0.294823,0.195156,0.386361,-0.483149,-0.003135,0.033608,0.021539,0.158218,-0.705958,0.342991,0.015918,-0.053204,0.330145,-0.213332,0.234141,-0.373606,-0.168115,0.549792,-0.233792,0.268143,0.110935,-0.115739,-0.404433,0.127105,-0.216033,-0.522322,0.171265,-0.006091,0.134869,0.016670,-0.056860,-0.440126,-0.258767,-0.279167,0.056261,0.289673,-0.658304,0.122394,-0.165388,-0.251694,-0.071048,-0.150575,0.017105,-0.022003,-0.328202,0.760702,-0.430170,0.228421,0.460266,0.409523,-0.137282,0.654937,0.107338,0.151327,-0.218701,-0.069890,0.128226,0.276788,0.180682,-0.221684,0.239121,0.192038,0.140639,-0.326164,0.454553', '1394424', '1458900', '3055049', '1292001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1585236', '纳尼亚传奇2：凯斯宾王子', '动作', '邪恶的勋爵弥若兹（塞吉·卡斯特里图）害死了自己的兄长，并长久挟制王子凯斯宾（本·巴恩斯），伺机篡位。迫于弥若兹的谋害，凯斯宾在深夜逃离城堡，奔向纳尼亚丛林深处。在敌人的追击下，凯斯宾慌张的吹响了号角。在另一个世界，彼得（威廉·莫斯里）、苏珊（安娜·帕波维尔 ）、埃蒙德（斯堪德·凯恩斯）和露西（乔基·亨莉）四人已成为伦敦街头的普通学生。可是号角的吹响，让他们再次感到纳尼亚的呼唤。1300年后，受制于台尔马人的纳尼亚，正等待国王和女王的拯救。©豆瓣', '乔芝·韩莉', '安德鲁·亚当森', 7, 89165, 'tt0499448', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p815665348.jpg', 0.8, 6.3, 45.8, 34.3, 12.7, '0.223101,0.109392,-0.556699,0.585612,0.078680,-0.185544,0.841948,0.238725,-0.163032,-0.174678,0.292193,0.977646,0.086151,-0.137984,0.561954,0.335973,-0.586585,-0.580022,-0.065601,-0.333944,-0.071244,-0.390330,-0.315673,-0.451028,0.057582,-0.603540,0.509548,0.015551,-0.019982,0.536216,0.203590,0.310627,-0.012252,0.400928,0.045476,0.234810,0.373189,-0.377388,-0.196889,0.175123,-0.245096,-0.124268,-0.452698,0.267009,0.021577,0.365516,0.371244,-0.738949,0.472980,-0.301719,0.110117,-0.358748,0.182064,0.023471,0.178043,-0.482807,-0.116234,0.231725,-0.063756,-0.107078,-0.077245,-0.079780,-0.688358,0.317668,-0.076337,0.087689,-0.445739,0.272823,-0.284203,0.066488,0.437916,-0.308296,0.023977,0.399258,0.036171,0.252301,-0.280222,-0.097012,-0.578644,-0.223760,0.488108,-0.027164,-0.286983,-0.252730,-0.138564,-0.466927,0.103970,-0.059844,-0.734720,-0.447759,0.576030,0.061467,-0.093357,0.223826,-0.526553,-0.205183,-0.559384,-0.177576,0.055872,-0.518420,-0.415014,-0.771353,0.096943,-0.070942,0.195978,-0.085506,0.013800,-0.080883,0.328495,-0.595021,0.498736,0.645014,0.220504,-0.069713,0.466192,-0.038502,0.122058,0.019944,-0.109494,0.581494,0.350192,0.452258,0.151326,0.148420,-0.087478,-0.053617,-0.322913,0.473507', '1298095', '1301686', '1316693', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1588704', '房车之旅', '喜剧', '鲍勃（罗宾·威廉斯 Robin Williams 饰）都快50岁了，事业面临着挑战，家庭面临着危机。本来他打算在百忙之中抽出时间陪家人展开一次夏威夷之旅，以改善糟糕的家庭关系；无奈又放不下公司业务，因为一个名牌大学MBA的公司新人给他带来了严重的威胁，如果不拼了老命工作，饭碗随时不保。用心良苦的老爹，只好临时想了一个折中办法：取消夏威夷之行，全家租来一个流动房车，前往他的出差地的城市附近，来一次野营活动。一边是忙碌繁琐的工作，一边是盼望着有个美好旅途的家庭，鲍勃得有一流的周旋功夫，不仅顾全大局而且两面讨好。问题是老爹又不是超人，应付起来自然力不从心，笑料百出。©豆瓣', '罗宾·威廉姆斯', '巴里·索南菲尔德', 7.3, 11495, 'tt0449089', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1510678254.jpg', 0.8, 4.1, 39.6, 40.8, 14.7, '0.014897,0.048138,-0.613426,0.460482,-0.122008,-0.266701,0.406162,0.301723,-0.321447,-0.172005,0.344504,0.535222,0.259311,0.306861,0.112987,-0.125519,-0.369497,-0.557646,0.188364,0.260082,-0.440660,-0.554417,-0.173725,-0.102597,-0.140008,-0.164048,0.174650,0.178709,-0.091469,0.292741,0.065477,-0.032855,0.224072,0.563988,-0.158136,-0.383023,0.012773,0.107904,-0.313940,0.256127,0.428808,0.000556,-0.095423,0.259040,0.492966,0.459668,0.444253,0.230561,-0.250642,-0.078488,0.377994,-0.293546,-0.160031,-0.081108,0.318446,-0.061173,0.210788,-0.001313,-0.332182,-0.075405,0.181239,-0.158853,-0.872777,0.042940,0.108271,-0.119985,-0.684475,0.425177,-0.125853,-0.182231,0.021050,-0.407632,-0.002404,0.651483,0.438910,0.249366,-0.056418,0.335931,-0.522271,0.192643,0.856748,0.031246,-0.069796,0.302182,-0.146209,0.067843,0.152684,-0.406058,-0.365428,-0.220730,0.138503,-0.278977,-0.204485,-0.040951,-0.330882,0.193970,-0.270814,-0.370406,0.151059,-0.425283,-0.003611,-0.371961,0.233831,-0.017412,-0.200728,0.141858,0.310672,-0.279340,0.656829,-0.489398,-0.146771,0.834673,0.209315,-0.761138,0.609153,0.168584,0.343998,-0.324725,-0.002542,-0.173346,-0.298966,0.381044,0.223463,0.054993,0.149419,-0.384772,-0.296340,0.254610', '26678784', '1877596', '30163500', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1607471', '国家宝藏：夺宝秘笈', '动作', '冒险家本•盖茨（尼古拉斯•凯奇饰）是次要挑战更艰难的探险寻宝之旅。美国第16任总统亚伯拉罕• 林肯之死一直是美国历史上的一宗悬案，据调查，凶手约翰•沃克斯•布斯实际是受人唆使犯下惊天命案。盖茨参加一次公开演讲，台下的一位叫米奇•威尔金森（艾德•哈里斯饰）的男子宣称，盖茨的祖父与林肯之死有千丝万缕的联系。于是盖茨开始调查约翰•布斯相关的线索，发现一本叫“国家密宗”的书，是解答一切问题的关键。但国家密宗只有美国总统本人知道其所在，为了探寻真相，盖茨不惜铤而走险，绑架总统。©豆瓣', '尼古拉斯·凯奇', '乔·德特杜巴', 7.2, 101765, 'tt0465234', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1102384696.jpg', 0.4, 3.8, 41.2, 42.5, 12.2, '0.216110,-0.208302,-0.530259,0.629141,0.135766,-0.137264,0.088298,-0.035671,-0.827775,-0.544995,0.159872,0.933977,-0.042870,-0.055323,0.237910,0.296218,-0.420127,-0.587039,0.113325,-0.209943,-0.042436,-0.939491,-0.157875,-0.593553,-0.147189,-0.164573,0.218680,0.062119,-0.253361,0.242941,0.751644,0.624161,0.014641,0.108853,0.173607,-0.214771,0.459260,-0.082141,-0.429610,0.081950,0.002056,-0.176321,-0.206239,0.227605,0.062031,0.489379,-0.234903,-0.133132,0.045645,-0.327813,0.349246,-0.309761,-0.077658,-0.008948,0.403264,-0.037297,0.049530,0.753036,0.114628,-0.292340,0.156980,0.021563,-0.504901,-0.151969,-0.005411,0.579650,-0.252436,-0.014954,-0.530508,0.247421,-0.019852,-0.269596,0.160654,0.310020,0.224794,-0.174776,0.491965,-0.110196,-0.453931,0.078837,0.512197,0.003541,-0.033107,-0.275496,-0.288062,-0.330818,0.202368,-0.439842,-0.212888,0.391372,0.317123,-0.200388,0.048914,0.515192,-0.292530,-0.227802,-0.540847,-0.369133,-0.112862,-0.241240,0.134795,-0.764483,-0.274574,-0.040133,-0.086832,-0.374941,0.141162,-0.580739,0.631488,-0.466192,0.267621,0.528210,0.087328,-0.427542,0.520337,0.126023,0.123455,-0.511622,-0.222415,0.233229,0.141965,0.068048,-0.450027,-0.226954,0.492427,-0.542623,-0.166873,0.044388', '1296252', '1296217', '30318116', '26920842');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('16475702', '一夜惊喜', '喜剧', '从小品学兼优、美丽干练的米雪（范冰冰 饰）对人生有着极好的规划，如今她身为某大型广告策划公司主管，事业顺风顺水，春风得意。可就在一个多月前盛大的生日派对过后，米雪竟意外发现自己有孕在身。一切的一切都指向了此前那个狂欢到极点、酗酒到断片的生日派对，在五十多名到场男性中，业已离婚的钻石男公司老板周毕安（丹尼尔•海尼 饰）、爱恋米雪的青年下属张童宇（李治廷 饰）、健壮帅气的干儿子林智博（蒋劲夫 饰）以及卖海鲜酱发财的暴发户陆大虎（黎明 饰）。在闺蜜林薇薇（吴佩慈 饰）的参谋下，米雪手足无措地迎来了人生中最跌宕起伏的时刻……©豆瓣', '范冰冰', '金依萌', 5.2, 122301, 'tt3013126', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2068215479.jpg', 10.7, 32, 44.6, 9.7, 3, '-0.208496,-0.031748,-0.570851,0.304591,0.109045,-0.185464,0.513138,0.396961,-0.353336,-0.209433,0.401627,0.299884,-0.387527,0.387506,0.782447,-0.081371,-0.207918,-0.675999,-0.218257,0.040020,-0.143487,-0.177703,-0.142452,-0.046912,-0.214439,-0.177286,0.572938,0.115704,0.123188,0.495003,0.425143,-0.054929,0.028222,0.205396,-0.269299,-0.018773,0.186175,0.089681,-0.326165,0.130196,-0.138078,-0.097204,-0.153713,0.044792,0.274567,0.335334,0.759361,-0.194018,-0.240803,-0.072294,0.501388,-0.012807,0.054123,-0.039192,0.397923,-0.006026,0.279954,-0.014038,-0.258946,0.016726,0.338348,-0.278218,-0.288885,-0.026611,0.117047,0.097244,-0.416517,0.495106,-0.032067,0.000345,0.267869,-0.254593,-0.044638,0.116726,0.068307,0.327778,-0.037789,0.553791,-0.477442,0.428524,0.399503,0.469313,-0.141430,0.461523,-0.167023,-0.319414,-0.296582,-0.092072,-0.458752,0.025433,0.187967,-0.116750,0.163997,0.370536,-0.670725,-0.071957,0.044639,0.020406,0.051263,-0.156396,-0.511585,-0.547037,0.039791,-0.391860,-0.219503,0.136718,0.109048,-0.141112,0.520895,-0.694102,0.020269,0.075176,0.005081,-0.216685,0.467961,-0.127976,0.165402,-0.243159,-0.339332,0.236556,0.005711,-0.010751,-0.049254,0.501112,-0.355284,-0.193118,-0.389579,0.339940', '3041753', '24839498', '3155839', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1652587', '阿凡达', '动作', '战斗中负伤而下身瘫痪的前海军战士杰克·萨利（萨姆·沃辛顿 Sam Worthington 饰）决定替死去的同胞哥哥来到潘多拉星操纵格蕾丝博士（西格妮·韦弗 Sigourney Weaver 饰）用人类基因与当地纳美部族基因结合创造出的 “阿凡达” 混血生物。杰克的目的是打入纳美部落，外交说服他们自愿离开世代居住的家园，从而SecFor公司可砍伐殆尽该地区的原始森林，开采地下昂贵的“不可得”矿。在探索潘多拉星的过程中，杰克遇到了纳美部落的公主娜蒂瑞（佐伊·索尔达娜 Zoe Saldana 饰），向她学习了纳美人的生存技能与对待自然的态度。与此同时，SecFor公司的经理和军方代表上校迈尔斯（史蒂芬·朗 Stephen Lang 饰）逐渐丧失耐心，决定诉诸武力驱赶纳美人……本片采用3D技术拍摄，共耗资5亿美元制作发行，是电影史上最为昂贵的作品。本片荣获第82届奥斯卡最佳摄影、最佳视觉效果、最佳艺术指导等3项大奖。', '萨姆·沃辛顿', '詹姆斯·卡梅隆', 8.8, 1294377, 'tt0499549', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2634997853.jpg', 0.3, 0.8, 10.2, 35.2, 53.5, '-0.096536,0.125639,-0.495663,0.591741,0.196427,-0.170345,0.307090,-0.042187,-0.226310,-0.187833,0.261838,0.545711,0.202100,-0.050935,0.463061,0.042563,-0.498599,-0.338111,-0.248375,-0.106694,-0.283972,-0.385163,-0.153339,-0.305557,-0.035200,-0.613874,0.860849,-0.162218,-0.396280,0.280532,0.163967,0.565306,-0.031483,-0.025705,0.117860,-0.193795,0.174177,-0.372005,-0.574498,0.498287,-0.093735,0.143316,0.044930,-0.156578,0.271764,0.179214,0.754859,-0.429966,0.177128,-0.267851,0.346277,-0.360514,0.229604,-0.117113,0.327236,-0.064231,0.047822,0.240674,-0.097736,0.120648,0.167475,-0.264181,-0.934239,-0.098623,0.258387,0.005639,-0.584885,0.260183,-0.087549,0.096467,0.015024,-0.156553,0.208382,0.481478,0.384573,0.133003,-0.000535,-0.068167,-0.306693,0.251535,0.247721,-0.192050,-0.324125,0.072488,-0.252960,-0.744191,-0.212205,-0.437531,-0.265896,-0.126199,0.103395,0.118222,0.273869,0.254238,-0.790553,-0.143506,-0.347318,-0.499124,0.318025,-0.237497,0.103809,-0.908249,-0.003155,-0.136802,-0.141177,0.119609,0.093073,-0.293443,0.644800,-0.493034,-0.094156,0.311042,0.455307,-0.362348,0.507597,-0.324192,0.092636,-0.418362,-0.125536,0.356027,0.121816,0.247497,-0.094890,0.154518,0.254387,-0.175085,-0