INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1652592', '阿丽塔：战斗天使', '动作', '故事发生在遥远的26世纪，外科医生依德（克里斯托弗·瓦尔兹 Christoph Waltz 饰）在垃圾场里捡到了只剩下头部的机械少女将她带回家中，给她装上了本来为自己已故的女儿所准备的义体，并取名阿丽塔（罗莎·萨拉扎尔 Rosa Salazar 饰）。苏醒后的阿丽塔对这个五彩斑斓但却暴力而又残酷的世界产生了浓厚的兴趣，在结识了青年雨果（基恩·约翰逊 Keean Johnson 饰）后，阿丽塔开始接触名为机动球的运动，并在比赛中展现出了惊人的格斗天赋。在废铁城居民们的头顶，漂浮着巨大的浮空城市撒冷，废铁城居民们的一切劳作和付出，都是为了给撒冷提供继续运作的燃料。在大财阀维克特（马赫沙拉·阿里 Mahershala Ali 饰）所设立的机动球比赛中，最终获得冠军的人能够获得前往撒冷生活的资格，阿丽塔决定利用自己的格斗天赋参加比赛，却被卷入了一个巨大的阴谋之中。', '罗莎·萨拉查', '罗伯特·罗德里格兹', 7.5, 571532, 'tt0437086', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2544987866.jpg', 0.8, 4.6, 33.4, 42.6, 18.6, '0.160468,0.271154,-0.716790,0.683266,-0.306594,-0.162560,0.696636,0.201090,-0.330609,-0.203747,0.264172,0.833977,-0.190219,-0.025320,0.209603,-0.035626,-0.219459,-0.702527,-0.175415,-0.147808,-0.495903,-0.552232,-0.281612,-0.331362,0.009878,-0.518671,0.632721,0.175404,-0.274088,0.283638,0.100250,0.117426,0.007602,0.511253,-0.263039,-0.002505,-0.097407,-0.095630,-0.093313,0.319252,-0.169784,-0.019096,-0.201016,0.144356,0.226989,0.383447,0.828942,-0.515262,0.120665,-0.225565,0.156749,-0.150494,0.145039,0.114392,0.082014,0.215325,0.031952,0.038626,-0.185094,0.229806,0.234982,-0.389455,-0.728396,-0.033041,-0.062746,-0.046671,-0.624946,0.674147,0.000140,-0.199495,0.101867,-0.092993,0.287255,0.205439,0.070760,0.313270,-0.162821,0.006175,-0.364141,0.277715,0.454507,-0.203112,-0.440162,0.336045,-0.282066,-0.485633,-0.327095,-0.359105,-0.125029,-0.209537,0.447602,0.289630,0.047306,0.331685,-0.848710,0.166332,-0.234857,-0.501017,-0.028641,-0.377250,-0.133692,-0.609012,0.094780,-0.165980,-0.282055,0.135465,0.050352,-0.266267,0.792988,-0.907172,0.184398,0.637403,0.316914,-0.151866,0.430763,-0.177312,0.220516,-0.087663,-0.390488,0.324277,-0.019896,0.452268,0.046521,0.421824,-0.028523,-0.293198,-0.563139,0.722688', '12