INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1652618', '速度与激情3：东京漂移', '动作', '东京，一直是改装汽车爱好者的天堂，复杂狭窄的街道成为了他们用激情和速度去拼杀的赛道。由于东京街道的弯道极度，在这样的路线上比拼速度，单纯的速度是无法获得胜利。所以，东京的街道赛变成了漂移技术的比赛。男主角尚恩（卢卡斯·布莱克 Lucas Black 饰）注定是个失败者，在学校毫无朋友，唯一能发泄的地方就只有街头赛车，在经历一次非法赛车被警方通缉后，为躲避牢狱之灾，不得不离开美国，到东京他在军中服役的父亲家中。可是父亲的专制，让尚恩觉得与其格格不入，每天仍然沉迷于街头赛车中。东京赛车极高的漂移技术把尚恩深深吸引，并结识了“漂移之王”DK（布莱恩·泰 Brian Tee 饰）。由于与日本的犯罪集团扯上关系，尚恩不得不为弥补自己的过失再次比赛，而这次比赛的赌注却是自己的生命。一场东京狂飙，就此拉开……©豆瓣', '卢卡斯·布莱克', '林诣彬', 7, 138689, 'tt0463985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1035097366.jpg', 1.5, 9.2, 43.8, 30.1, 15.3, '0.159644,0.139477,-0.687065,0.735440,0.035900,-0.419745,0.536393,-0.033477,-0.509094,-0.048280,0.408351,0.880172,-0.227257,0.030080,0.257607,-0.282017,-0.210032,-0.819623,-0.172084,-0.012548,-0.462185,-0.495382,-0.143978,-0.150358,-0.145939,-0.108786,0.829960,0.308403,-0.304629,0.556017,0.257878,0.106025,-0.103911,0.461753,-0.416525,-0.259929,-0.098594,0.042398,-0.301009,0.198498,0.072246,-0.293374,-0.019338,0.101217,0.147220,0.290507,0.875327,-0.098490,-0.062312,0.015474,0.181691,-0.445320,-0.093494,-0.163505,0.405791,0.001603,0.122896,0.148292,-0.040702,0.014838,-0.001598,0.038681,-0.658568,0.108526,-0.111891,0.011881,-0.598891,0.539524,-0.136342,-0.195589,0.120097,-0.186312,0.290485,0.118312,0.401479,0.130635,-0.319691,-0.146651,-0.404196,0.115751,0.804020,0.110600,-0.238597,0.431421,-0.335545,-0.370063,0.021073,-0.534925,-0.269275,-0.085433,0.234642,-0.128245,-0.211533,0.246451,-0.699001,0.053426,-0.247361,-0.416736,-0.120322,-0.386234,0.114846,-0.880927,0.175520,-0.561764,-0.042477,0.119829,-0.007515,-0.235046,0.359125,-1.019602,-0.043354,0.814369,0.285237,-0.383695,0.689343,-0.047684,0.086257,-0.029970,-0.144357,0.276191,-0.151442,0.426490,-0.118850,0.328645,-0.051357,-0.113546,-0.547948,0.970490', '11541282', '30345227', '26971054', '3592853');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1663415', '上车走吧', '剧情', '1998年，山东青年刘承强（高虎 饰）和同乡高明（黄渤 饰）相约来到首都北京。已去海南发展的表哥小软将自己承包过的小巴托给承强，在小巴老板陆建刚的帮助下，二人在郊区找到落脚之处，也顺利地成为了小巴302线的司乘人员。建刚哥为人仗义，但同在一条营运线的大头和大英子出于利益 的关系，处处与强子和小明作对，双方为此曾大打出手。在此期间，他们结识了同住一个院子的四川女孩小辫子，高明更与她日久生情，而强子则喜欢上了小巴上的常客丽娟（陈宁 饰）。经过一番努力，两人经营的小巴逐渐有了起色，甚至引来电视台的关注。与此同时，大头对他们的排挤也越来越厉害，这两个外地青年在北京的闯荡之路无比艰难……©豆瓣', '高虎', '管虎', 8.1, 30756, 'tt9602302', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2495747700.jpg', 0.3, 1.2, 19.2, 53.6, 25.8, '0.300170,-0.198563,-0.760565,0.606001,0.017781,-0.389537,0.606701,0.243752,-0.532655,0.147854,0.260346,0.695457,-0.142462,0.122769,0.248000,-0.231616,-0.257805,-0.650538,-0.011994,-0.178859,-0.320340,-0.507810,-0.293678,0.061186,-0.348619,0.036591,0.255058,0.175953,-0.111767,0.641038,0.170438,-0.136513,-0.194045,0.310711,-0.371232,0.029395,-0.008897,0.058028,-0.197270,-0.041066,-0.120910,-0.342671,-0.151984,-0.186761,0.202533,0.481468,0.702362,0.062916,-0.274372,-0.067458,0.067109,-0.119913,0.063742,-0.044876,0.382500,0.088376,0.405650,0.179997,-0.318305,-0.064841,0.013739,-0.116561,-0.623983,0.249090,0.139549,0.065451,-0.749642,0.567388,0.106036,-0.360974,-0.027352,-0.769709,0.201113,0.581809,-0.011879,0.192728,-0.116901,0.147169,-0.393635,0.004605,0.852400,0.119265,0.125173,0.032547,-0.030302,-0.355201,-0.053478,-0.103675,-0.336844,-0.295410,0.493309,-0.214716,-0.047397,0.064950,-0.682215,0.193275,-0.092895,-0.028061,0.065081,-0.307877,0.076403,-0.619418,-0.175768,-0.782672,-0.150294,0.264184,0.211805,-0.284510,0.738937,-0.831672,0.049592,0.417689,0.591704,-0.596702,0.731789,0.014707,0.390534,-0.225592,-0.274661,-0.114697,0.093917,0.331350,0.246037,0.446582,-0.261379,-0.189201,-0.503975,0.119402', '1292219', '3055049', '1301022', '1293303');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1666889', '五郎八卦棍', '剧情', '北宋年间，杨家将出战金沙滩，佘太君求得“七子去六子还”的签语，心中忐忑。国丈潘美因杨七郎打死自己儿子，使计陷害杨家将，令杨家一门忠烈在金沙滩的对辽战事中几乎俱折，唯有杨五郎（刘家辉 饰）负伤逃脱、杨六郎（傅声 饰）发狂返回天波府。潘美为斩草树根，引辽兵入宋，暗中将天波府团团围住，以防杨家将面见皇帝伸冤。杨五郎得悉皇帝下诏斥自己为叛徒，心感走投无路，经一义士以命相劝，遂远上五台山清凉寺请求出家，方丈因其杀性未伏，不予接纳，杨五郎强驻寺中，并化杨家枪法为棍法，潜心修炼。不久，天波府因僧人报信，派出杨八妹（惠英红 饰）赴五台山接杨五郎，沿途潘美步步紧逼，令杨五郎下山救妹复仇……©豆瓣', '刘家辉', '刘家良', 7.1, 4332, 'tt0086606', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2559824563.jpg', 0.8, 4.5, 44, 38.5, 12.3, '-0.312151,0.100925,-0.510018,0.481222,0.378395,-0.117556,0.012258,0.165722,-0.415521,-0.387503,0.307945,0.294526,0.044830,-0.003684,-0.040532,-0.062125,0.135501,-0.234522,-0.132582,-0.027205,0.137898,-0.143020,0.146984,-0.258204,-0.341187,-0.052978,0.348312,0.389652,-0.212509,0.557976,0.237826,0.106325,-0.139540,0.219017,0.043210,0.324374,-0.395466,-0.238654,-0.184215,0.046517,-0.139715,-0.684253,-0.407572,-0.056470,-0.281436,0.273267,0.227448,-0.194289,0.144781,-0.263700,0.064405,-0.165828,0.006250,0.205976,0.187851,-0.037224,-0.102812,0.446380,-0.063345,0.135108,-0.219813,-0.086584,0.000609,0.048985,0.440352,-0.243120,-0.529840,0.058403,-0.267047,0.287817,-0.029605,-0.415624,0.144732,0.188972,0.175025,0.073602,-0.210862,-0.148461,-0.295649,0.471655,0.502512,-0.329772,0.536174,-0.645052,0.389554,-0.112735,0.595060,-0.219885,-0.050343,0.020840,0.419004,-0.111762,0.208822,0.056319,0.160153,-0.340365,-0.539148,0.477353,0.027871,0.082921,0.400325,-0.480033,0.039088,-0.060457,-0.075737,-0.110432,0.290925,-0.060406,0.184008,0.079719,0.050055,0.203348,0.051710,-0.598164,0.433319,0.071904,0.129346,-0.155531,0.034947,0.369134,0.170468,0.351484,0.039652,-0.239385,-0.331533,-0.003738,-0.390338,-0.096115', '1461031', '1296240', '1306490', '1294011');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1689787', '回归', '剧情', '雷蒙黛（佩内洛普•克鲁兹 Penélope Cruz饰）和他的酒鬼丈夫、年轻女儿共住，生活却不像别人平静。 雷蒙黛有个姐姐索尔（劳拉•杜纳丝 Lola Dueñas饰），小时候两人和父母生活贫寒。父母在一场火灾后遇难后，两姊妹就搬到了马德里生活，为着各自生活已经渐渐疏远。然而，一场意外和一个鬼魂，打破了两姐妹平静的生活。©豆瓣', '佩内洛普·克鲁兹', '佩德罗·阿莫多瓦', 8.2, 44616, 'tt0441909', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2213137026.jpg', 0.2, 1.1, 17.5, 52.1, 29, '0.174298,-0.299104,-0.662091,0.582078,-0.264966,-0.594106,1.212409,0.375000,-0.577269,-0.217132,0.050579,1.011265,-0.092335,0.509185,0.247210,0.078748,-0.485905,-0.838937,0.023372,0.166595,-0.061933,-0.221424,0.016989,-0.467653,-0.175934,-0.235343,0.428346,-0.121565,0.242027,0.666563,-0.063689,0.225641,-0.434898,0.474009,-0.374302,0.320273,-0.045878,0.725742,-0.535977,-0.054308,-0.148339,-0.011184,-0.306904,-0.171361,0.401523,0.250366,0.766554,-0.288140,-0.389568,-0.064618,-0.013501,-0.031813,-0.377403,0.504931,0.404574,-0.303456,0.427675,0.061518,-0.110070,-0.097010,-0.092903,-0.222438,-0.078078,0.118007,-0.038423,0.189411,-0.769073,1.026786,0.098933,-0.173515,-0.109791,-0.252785,0.199873,0.570889,0.131307,0.602239,-0.390746,0.018456,-0.327314,0.379495,1.149928,0.046036,-0.316523,0.739067,-0.408245,-0.232871,-0.089979,-0.176086,-1.116263,-0.021224,0.225148,0.049586,-0.194197,0.515428,-0.684176,-0.153590,-0.127847,-0.128818,0.050413,-0.603115,0.177657,-0.433969,-0.325762,-0.747707,-0.515833,0.079408,-0.068944,-0.381772,0.721478,-0.764990,0.460084,0.090860,0.019899,-0.545341,0.380867,0.112375,0.454579,-0.236493,0.409808,0.146434,-0.280986,0.040194,0.331726,0.480111,-0.271507,0.461113,-0.110886,0.616040', '1296534', '26245360', '25721544', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1718162', '人鱼朵朵', '剧情', '朵朵出生的时候，老天并没有赋予她一双可以走路的脚。然而她的生命中没有缺少父母的爱，她接受手术后获得一双可以走路的脚，并获得了她生命中的第一双鞋。她相信巫婆的预言，相信黑羊和白羊会带给她幸福。但是在日常的生活中朵朵不停的搜集美丽的鞋子以致要专门用一间屋子存放。长大后的朵朵（徐若瑄饰），到了童话书籍出版社上班，她爱童话也爱幻想。透过神秘插画家的介绍，她认识了牙医诊所的主治医师，一名微笑牙医（周群达饰）。最后借着黑羊与白羊的牵引，他们结了婚，走进了幸福的生活。但是一场意外突然到来……©豆瓣', '徐若瑄 Vivian Hsu', '李芸婵', 6.9, 16490, 'tt0768137', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1643408130.jpg', 1.7, 8.4, 44.4, 32.9, 12.5, '0.340362,0.204748,-0.653848,0.509393,-0.358138,-0.181948,0.831074,0.083578,-0.152248,-0.204803,0.209211,0.739923,0.099763,0.176975,0.095521,0.275136,-0.143016,-0.647844,0.249873,-0.034438,-0.387425,-0.161777,-0.212361,-0.271316,-0.102382,-0.280670,0.632993,0.114941,-0.075936,0.794950,-0.048730,-0.031388,0.159938,0.279129,-0.434582,0.061544,-0.023564,0.391897,-0.062244,0.383511,0.185286,-0.014867,0.020902,0.403198,-0.122977,0.197796,0.648206,-0.469948,-0.157134,-0.080865,0.353412,-0.107544,0.021455,0.306944,0.047344,0.225426,0.208082,0.028002,-0.144451,0.058503,0.098089,-0.262533,-0.746051,-0.395475,0.053053,0.323317,-0.649185,0.434535,0.030088,-0.040697,0.362240,-0.308176,0.251434,-0.002786,0.296847,0.704608,-0.174337,0.096713,-0.647868,0.389596,0.278124,-0.348076,-0.245629,0.859580,-0.615129,-0.311790,-0.018366,-0.069041,-0.665407,0.124431,0.231977,0.180554,-0.402842,-0.145791,-0.448000,0.157714,-0.021285,-0.275745,-0.035576,-0.450365,-0.115416,-0.315328,-0.159470,-0.550411,-0.294524,0.151124,-0.000979,-0.397603,0.581635,-0.942000,0.569763,0.527695,0.318923,-0.341980,0.917107,0.196913,0.107744,-0.161888,0.071688,0.395464,-0.178183,0.324602,0.022124,0.410950,0.035201,0.189690,-0.625384,0.498612', '1850797', '3927750', '2052978', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1722041', '蜡笔小新之黑暗珠珠大追击', '喜剧', '', '矢岛晶子', '原惠一', 8.2, 7566, 'tt0406672', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2621613292.jpg', 0.4, 1.6, 21.4, 41.5, 35.2, '0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000', '10001432', '10047547', '10174444', '10342838');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1727557', '父子', '剧情', '阿宝（吴景滔饰）梦中坐在父亲的自行车后坐，一手拿着风车，一手紧紧地抱着，然而美梦破碎。落魄父亲周长胜（郭富城饰）有着烂赌恶习，母亲阿莲（杨采妮饰）为此无法忍受，决定出走后被抓回。为了挽救夫妻间已经破裂的感情，父亲一厢情愿地安排全家去坐邮轮度假，母亲趁机离家不归。穷困潦倒之余，周长胜又遭到了高利贷追债，连番失意的他想抛下阿宝，但还没离开就被追债的人打断腿。父子二人踏上了逃亡之路，伤残的父亲没有赚钱能力，只能逼迫阿宝去借钱甚至偷东西。有一次，阿宝偷窃失手，怯懦的父亲无力挽救……。这对父子的再次相见将会如何？©豆瓣', '郭富城', '谭家明', 6.9, 29828, 'tt0768114', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p518004802.jpg', 1.4, 6.9, 47, 35.8, 8.9, '0.072419,-0.106609,-0.673375,0.296152,-0.211841,-0.596115,0.665457,0.289649,-0.299081,-0.099861,0.305898,0.570248,0.060425,0.369840,0.163227,-0.026988,-0.107668,-0.669127,-0.028893,0.137531,-0.300104,-0.383965,0.185339,-0.053131,-0.371479,0.282004,0.470571,-0.060225,-0.163981,0.500531,0.174477,0.131819,-0.185124,0.402349,-0.344544,0.218674,-0.428978,0.176888,-0.293165,0.070023,0.291888,-0.315440,-0.011655,-0.006979,-0.067128,0.391688,0.533973,-0.178518,0.227378,-0.313658,0.183111,-0.290285,-0.062576,0.359561,0.097611,0.148690,0.124781,0.082234,-0.338216,-0.175447,0.616933,0.016935,-0.508779,0.214185,-0.195596,-0.181981,-0.880909,0.366211,-0.284242,0.117612,0.113804,-0.376311,0.154994,0.569197,0.262502,0.359739,-0.082987,0.175676,-0.354369,-0.044164,0.728843,-0.219382,0.296405,0.332579,0.069067,-0.052956,0.374376,-0.448346,-0.327520,-0.178797,0.450903,0.099473,-0.298398,0.070034,-0.216167,0.017621,-0.342827,0.035969,-0.019460,-0.245022,-0.131592,-0.051182,0.005811,-0.105283,-0.189253,0.297150,0.201728,-0.352933,0.086113,-0.447670,0.208235,0.345740,0.469368,-0.532396,0.487189,0.179225,0.047502,0.079302,0.192913,0.237158,-0.066582,0.469002,0.303028,-0.202590,0.062406,-0.064409,-0.165341,0.204405', '1299965', '35461732', '25908042', '1292533');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1750027', '判我有罪', '剧情', '美国黑手党根基深厚，危害严重。为了清除社会弊端，警方经过多年的侦察和筹备，对五大家族之一的卢切斯家族展开攻势。包括新泽西头目杰基•迪诺西奥（Vin Diesel 文•迪塞尔 饰）在内的20名家族成员被捕，并被指控76项罪名。在审判之前，公诉方与杰基秘密谈判，要他选择或者遭受长达30年的牢狱之灾，或者充当污点证人，指控其他家族成员。杰基宁愿坐牢也不愿出卖伙伴，他拒绝聘任律师，一个人为自己以及整个家族成员展开了辩护……影片根据美国司法历史上最长的一次黑帮刑事审判改编而成，主人公为上世纪80年代的传奇帮派头目杰基•迪诺西奥（Jackie DiNorscio），故事情节与台词片段均采自18年前入档的庭审记录。由于案情复杂，且牵涉人物众多，审判持续21个月之久，并创下多项纪录：创下了多项庭审纪录：20名被告配备了20名辩护律师、8个陪审团轮番上阵以及史无前例的超长结案陈词（其中一位辩护律师的结案陈词居然宣读了5天）。', '范·迪塞尔', '西德尼·吕美特', 7.8, 11327, 'tt0419749', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1728320501.jpg', 0.5, 2.2, 25.1, 52, 20.2, '-0.017025,-0.079502,-0.284702,0.555247,0.234098,0.086171,0.333563,-0.052954,-0.559376,-0.524454,0.259100,0.487542,-0.136519,0.168159,0.494416,-0.516694,-0.375732,-0.790399,-0.193362,-0.402682,-0.347818,-0.908355,-0.020623,-0.279214,-0.060339,-0.162081,0.583530,-0.015064,-0.140916,0.184406,0.241578,0.401068,-0.168986,-0.146855,0.156023,-0.189554,0.509826,-0.046995,-0.465332,0.110265,-0.296141,-0.249446,0.000863,-0.053615,0.053586,0.398649,0.464564,-0.242904,-0.040139,-0.392539,0.393780,-0.435770,-0.135469,-0.046697,0.668271,0.081281,0.317006,0.949115,0.101030,-0.147628,-0.055396,-0.220408,-1.129691,-0.185168,0.155448,0.248707,-0.249586,0.521748,-0.352731,0.397668,-0.536624,0.052387,0.004072,0.273057,0.461138,0.187530,-0.109755,0.148830,-0.212079,0.494642,0.332420,0.014008,-0.312937,-0.378795,-0.168038,-0.520198,-0.196799,-0.511831,-0.161213,0.166463,0.225941,-0.105187,0.212669,0.520604,-0.465760,-0.172854,-0.368441,-0.390584,0.080179,-0.197949,0.028945,-0.684694,-0.044239,0.143329,-0.253571,0.139453,0.319698,-0.192756,0.657399,-0.299824,0.177492,0.276870,0.253289,-0.687009,0.358915,0.367379,0.398843,-0.378542,-0.217279,0.174097,0.347095,0.170919,0.053699,-0.095028,-0.076086,-0.413525,0.050146,-0.131654', '1293989', '26678784', '26848640', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1754628', '香火', '剧情', '庙里的佛像塌了，需要三千元钱重新修葺，为了筹得这笔钱，和尚（李强 饰）先后来到了佛教科和文物科，然而两方人马只会相互推诿责任，看来谁也不打算掏出这笔钱来。无奈之下，和尚前去找在另一座庙中生活的师兄帮忙，可是师兄只是劝他放弃。之后，和尚决定靠化缘筹钱，哪知道没过多久竟然被警察抓进了派出所，出来后，和尚遇见了想要帮忙的妓女、企图哄女友开心的小伙子和一心想替妻子求药治病的丈夫，甚至当起了算命先生。最终，和尚卖掉了念珠总算筹齐了钱，当他满心欢喜的回到庙里之时，等待着他的，却是寺庙即将被拆的消息。©豆瓣', '李强', '宁浩', 8.4, 17986, 'tt3330856', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2599941387.jpg', 0.2, 0.8, 12.5, 52.9, 33.6, '0.006272,0.058694,-0.515356,0.201420,-0.318910,-0.587037,0.305240,0.179458,-0.323129,-0.164935,-0.142373,0.469925,0.303199,0.253538,0.145517,0.090251,-0.276358,-0.385138,-0.017153,-0.219212,-0.237557,-0.375834,0.166709,-0.222922,-0.346425,0.074426,0.045635,0.240661,0.380150,0.136941,0.383897,0.123462,-0.060842,0.446039,-0.226608,0.266149,0.035732,0.115071,-0.150326,0.234082,0.226624,-0.340967,-0.087191,0.016859,0.047070,0.353281,0.391525,-0.054745,-0.024002,0.076573,-0.032389,0.021444,0.018740,0.145066,-0.013524,0.131685,0.534152,0.027203,-0.319838,0.045049,0.420518,-0.270461,-0.270001,0.171964,0.157164,-0.237648,-0.893383,0.280121,0.013275,0.366119,-0.174189,-0.398059,0.418565,0.490972,0.112855,0.327125,-0.232631,-0.171949,-0.746592,0.284246,0.235354,-0.153603,0.669103,0.314904,0.144172,-0.288279,0.382111,-0.110447,-0.144368,0.195320,0.475865,-0.147125,-0.220179,-0.357783,-0.426487,-0.324568,-0.291431,0.009211,0.095539,-0.429522,0.003788,-0.077273,0.147179,0.352372,-0.007199,0.069350,0.311805,0.039342,0.442295,-0.388510,0.049203,0.465482,0.283913,-0.473895,0.674184,-0.345324,0.180817,-0.206816,0.040833,-0.385563,0.063940,0.920909,0.489967,0.084712,0.107547,-0.281956,-0.009865,0.046376', '1432825', '26801782', '1300108', '1293908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1754927', '88分钟', '剧情', '一夜的纸醉金迷后美国联邦调查局的法庭精神分析师Jack Gramm博士（Al Pacino饰）被一宗谋杀案的电话带离了美人香，这宗谋杀案和9年前的西雅图杀手案极其相似。Jack当时的精神分析是判定嫌疑犯Foster有罪的关键依据。现在联邦调查局认为Foster是无辜的，而被害者在临死前的录象带也亲口证实Jack抓错了人。真正的罪犯也许正在逍遥法外。当Jack正处于迷惑之时，他又收到了莫名的死亡威胁，得知自己只能再活88分钟。面对种种突如其来的迷团以及死亡的威胁，Jack该如何应对……©豆瓣', '阿尔·帕西诺', '乔恩·阿维奈', 6.5, 17047, 'tt0411061', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1255261361.jpg', 1.5, 11, 54, 27.7, 5.7, '0.247401,0.058375,-0.555668,0.427360,-0.108310,0.065251,0.616019,0.047674,-0.686527,-0.383013,0.417740,0.591889,-0.184778,0.434098,0.492343,0.002740,-0.118467,-0.695841,-0.139798,-0.234918,-0.467248,-0.887805,-0.432203,-0.188342,0.259901,-0.095539,0.465146,0.364560,-0.224353,0.181007,0.235437,0.702675,-0.194658,0.559887,-0.091987,-0.097932,0.110733,-0.007034,-0.318851,0.046541,0.488901,-0.572709,0.071779,0.412149,-0.329454,0.556874,0.491142,-0.548597,-0.544406,0.089311,0.607567,-0.650645,-0.270276,0.174861,0.335453,-0.079839,0.161744,0.304803,-0.223811,-0.151885,0.099662,0.362168,-1.023316,-0.123909,0.054158,0.194423,-0.238312,0.275987,-0.337320,0.155899,0.108482,0.042782,0.259187,0.447162,0.196667,0.697126,-0.205392,-0.333559,-0.558989,0.107571,0.577570,0.100974,-0.248066,0.224434,0.008080,-0.567971,0.134688,-0.361109,-0.143823,0.306850,0.287766,0.199082,-0.286225,0.261196,-0.283238,-0.305795,-0.369227,-0.049733,-0.146898,-0.616794,-0.208315,-0.333299,-0.297911,-0.120509,-0.370022,0.034220,0.311684,-0.217585,0.316189,-0.820268,0.222696,0.581571,-0.113930,-0.524895,0.304504,0.188127,-0.020404,-0.070125,-0.298470,0.154366,0.319852,0.539522,0.051086,0.099927,0.265479,-0.343929,-0.440937,0.287742', '1297689', '25862560', '1307442', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1756073', '我们俩', '剧情', '冬天，在某个四合院孤孤单单生活的老太（金雅琴）迎来一个来北京求学的外地女孩（宫哲）。女孩想租老太离学校很近的房子，但嫌老太要价太高，老太一脸爱住不住的表情坚决不降价，女孩无奈租了下来，两人开始磕磕绊绊争吵不休的主客生活。无论是安装电话、缴纳电话费，还是点电炉、借用电冰箱，女孩都觉得老太在处处算计她，心里十分委屈，老太看她，也是一百个不顺眼。但日久生情，两人渐渐成了彼此的依靠。日子溜过春天、夏天，老太眼见女孩生活尤其恋爱中的喜怒哀乐，她晚年的孤独因为有女孩的陪伴冲淡了不少。秋天来临，女孩找到更好的住处，要离开老太，老太的精神一下子垮了下来。©豆瓣', '宫哲', '马俪文', 8.7, 110828, 'tt0757376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173725381.jpg', 0.1, 0.6, 9.6, 40.8, 48.8, '0.339453,-0.290079,-0.310064,-0.194765,-0.341708,-0.354300,0.789366,0.252373,-0.468488,-0.050586,0.416770,0.740516,-0.082643,0.271764,0.186601,0.193008,-0.278438,0.107779,0.150405,-0.108468,0.231767,-0.383280,0.101411,0.006629,-0.087652,0.053912,0.356599,-0.115676,0.414311,0.446307,-0.387171,-0.007978,0.306921,0.441289,-0.522912,0.331094,-0.203953,-0.187937,0.051093,0.065381,0.171305,0.022283,-0.329969,-0.203014,0.135288,0.332751,0.567774,0.216525,-0.484349,0.178588,0.336210,-0.101244,-0.570544,0.010976,0.277255,0.062201,0.450269,0.086247,-0.209227,0.029876,0.072441,0.198472,0.106274,0.695824,0.255964,0.224574,-0.477923,0.755316,0.181783,-0.197297,-0.162265,-0.856039,0.211703,0.058450,0.035966,0.571485,-0.494416,0.011738,-0.832616,0.036939,0.551660,-0.086586,-0.015400,0.489764,-0.371685,-0.008982,0.333829,-0.353925,-0.881879,-0.167473,-0.114570,0.044472,-0.429151,0.150490,-0.560316,0.362374,-0.020524,-0.135743,0.037871,-0.662639,-0.592340,-0.248436,-0.381872,-0.420703,-0.190232,-0.090761,0.061037,-0.228480,0.622794,-0.772001,0.117901,0.196007,0.519077,-0.221460,0.577792,0.114585,0.114783,-0.295058,0.035967,0.027800,-0.549273,0.465682,0.168441,0.354060,-0.498081,-0.137856,-0.067266,0.462751', '1302384', '1763134', '10745399', '1307561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1756361', '喜欢你', '剧情', '17岁的青葱时节，内向纯洁的少女小优（宫崎葵 饰）与放弃了棒球转而练习吉他的佑介（瑛太 饰）成为好朋友。她喜欢在课堂偷偷瞄着男孩的侧影，用笔画下对方的漫画形象；也喜欢每日陪伴他在河堤边练习，哼唱着同一段旋律。纵使心里多么喜欢，却无法将那三个字勇敢说出口。女孩小小的倔强与别扭，使两个年轻人错失了向彼此迈进一步的机会。另一方面，优的姐姐不久前刚刚与恋人生离死别，她的出现似乎使三人之间的关系微妙难测。此去经年，当优（永作博美 饰）和佑介（西岛秀俊 饰）再次见面，可曾想起当年河堤旁的梦幻岁月……本片荣获蒙特利尔国际电影节最佳导演奖。©豆瓣', '宫崎葵', '石川宽', 7, 17490, 'tt0781511', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p728484372.jpg', 1, 7.3, 44.7, 34.8, 12.2, '0.230312,0.059552,-0.418022,0.676871,0.024142,-0.190833,0.665175,0.033123,-0.430427,-0.011759,-0.025486,0.615563,-0.294119,0.351266,0.212119,0.004928,-0.030343,-0.793129,0.130548,-0.142372,0.061692,-0.388605,-0.114944,0.274954,-0.201302,-0.311595,0.630123,0.041760,-0.024059,0.535567,0.269126,0.076561,-0.232371,0.077654,-0.224086,-0.078609,-0.175037,0.224004,-0.200527,-0.013329,0.125175,-0.251021,-0.403368,0.072350,-0.068039,0.203956,0.646665,-0.192222,-0.254948,0.076057,0.396526,0.083702,0.002357,-0.012461,0.238337,0.081661,0.275585,0.101418,-0.019484,-0.011203,0.076447,-0.115930,-0.281766,0.197239,0.033089,0.092454,-0.595963,0.348985,-0.071540,-0.152149,0.248647,-0.158756,-0.029039,0.195409,0.494866,0.153595,-0.303426,0.113917,-0.105241,0.164419,0.460772,0.380711,-0.217658,0.575150,-0.141760,-0.297769,-0.232991,-0.155763,-0.459547,0.104637,0.053384,-0.061171,-0.073833,-0.106931,-0.526196,0.084388,0.095535,0.210503,0.267112,-0.448030,-0.156310,-0.386707,0.170507,-0.564556,-0.464312,0.080543,-0.095683,-0.284504,0.722592,-0.734598,0.100655,0.530341,0.315015,-0.055090,0.622047,0.302468,-0.094963,-0.249385,-0.148616,0.435959,-0.348754,-0.105123,0.092297,0.322418,-0.205048,0.150759,-0.719325,0.379911', '1307146', '3811356', '5416009', '3155839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1758336', '野蛮秘笈', '喜剧', '上官灵凤（张柏芝 饰）是一个快乐幸福的小女孩，爸爸妈妈对她分外疼爱，每天都为女儿将睡前故事。只是，这些故事无关王子和精灵，而一律都是武侠江湖、大侠剑客。虽然灵凤喜欢这些故事，但她也有尴尬烦心的事情。爸爸名叫上官英俊（元华 饰），妈妈名叫独孤美丽（元秋 饰），这两个怪名字让灵凤在学校受到不少嘲笑。10岁生日那天，她终于得知，原来那些武侠故事并非虚构，竟然都真实存在，而且父母正是隐居闹市的江湖高手。这个懵懵懂懂的小女孩随着父亲母亲走入大山，研习武功，开始一段奇异的旅程……©豆瓣', '张柏芝', '王晶', 4.9, 13095, 'tt0757378', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2360559748.jpg', 14.6, 36.3, 40.1, 6.4, 2.6, '0.159050,-0.285904,-0.369861,0.463872,-0.169313,-0.052299,0.660837,-0.216418,-0.940821,-0.634296,0.228269,0.702658,0.071971,0.557575,-0.029193,0.264563,0.079955,-0.378216,0.188447,-0.171654,0.071227,-0.322338,-0.033697,0.060513,-0.140072,-0.291337,0.299756,-0.078701,0.036064,0.729173,0.205974,0.031536,-0.380653,0.325943,-0.276805,0.121738,0.098285,0.321683,-0.281810,-0.167045,-0.241508,0.166153,-0.013902,0.121996,-0.168118,0.069938,0.465055,-0.259936,-0.403843,-0.000596,0.492137,-0.287135,-0.137602,0.219189,0.145627,0.059292,0.784735,0.263824,0.122536,0.032161,-0.265135,-0.142418,-0.525712,0.145763,0.490976,0.170867,-0.367679,0.346971,-0.157236,-0.383390,0.328852,-0.208335,0.430215,0.073543,0.477329,0.473810,-0.167435,0.098308,-0.355921,0.334708,0.468081,-0.017079,-0.042080,0.661757,-0.099198,-0.136755,0.054309,-0.323635,-0.527708,0.471767,-0.360031,-0.295386,-0.184975,0.390604,-0.280704,0.169470,0.250515,0.033980,0.155210,-0.449940,-0.385252,0.080548,-0.222124,-0.473895,-0.345281,-0.228238,0.167110,-0.282345,1.088048,-0.698351,0.431425,0.273907,-0.045618,-0.480293,0.607019,0.292816,-0.053176,-0.113832,0.063192,0.458300,-0.038033,-0.056520,-0.488260,0.244978,0.054617,-0.165433,-0.493268,0.362077', '6963575', '26348103', '25738406', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1758487', '惊变28周', '科幻', '在恐怖的致命病毒横行28周之后，英国境内已经空无一人。由于失去了载体，病毒也随之消亡。随着一架从美国飞来的运输机的降落，在病毒爆发前就离开英国的英国人，重新踏上了被病毒肆虐半年的土地。这可以说是地球上最后的一群英国人，重建家园的重担就落在了这群平民身上。然而，重建工作才开展不久，就有人报告发现了病毒感染的幸存者。科学家们也希望能从幸存者身上提取血清研究出对付病毒的疫苗。可是，万万没有想到的是，病毒并没有像大家想象中的那样已经消亡，反而进化后变得更加强大。这英伦三岛上最后的一群人们，将面对空前的危机……©豆瓣', '杰瑞米·雷纳', '胡安·卡洛斯·弗雷斯纳迪罗', 6.6, 49904, 'tt0463854', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2191902863.jpg', 3.3, 11.3, 46.2, 29.9, 9.3, '0.279895,0.144647,-0.797840,0.360109,-0.129793,-0.280810,0.873899,-0.239394,-0.351796,0.010205,0.098379,0.776690,-0.274494,-0.022967,-0.219644,-0.191170,-0.341024,-0.621887,-0.322619,-0.034013,-0.634053,-0.210260,-0.431561,-0.294421,0.041168,-0.387086,0.780491,0.497119,-0.537653,0.308210,0.092259,0.392372,0.014945,0.811890,-0.361505,-0.074241,-0.174251,0.072163,0.043752,0.466850,0.172150,-0.493962,0.248807,0.202798,0.068252,0.132819,0.730869,-0.359914,-0.087730,-0.373920,0.380608,-0.420833,0.027583,0.276080,0.636589,0.202992,-0.170774,0.030031,-0.130293,-0.096865,-0.120690,0.018066,-0.992714,-0.164255,-0.321936,0.178503,-0.515606,0.269053,0.138615,-0.071458,-0.131529,-0.194511,0.552410,0.622738,0.020818,0.443022,-0.380715,0.018354,-0.674096,0.002358,0.731531,-0.324650,-0.833483,0.420980,-0.155981,-0.690975,-0.240558,-0.268217,0.022339,-0.034175,0.282466,0.433343,-0.402910,0.374558,-0.835861,0.311083,-0.456308,-0.689102,-0.079485,0.093200,-0.246811,-0.770962,-0.219966,-0.163672,-0.458223,0.373351,0.118375,-0.210937,0.872145,-0.784356,0.314335,0.467485,0.414202,-0.559430,0.148408,-0.241303,0.045252,0.143474,0.058139,0.322763,0.058219,0.944371,0.322837,0.426938,-0.091247,-0.223322,-0.236675,0.711169', '25774050', '1292523', '1578502', '7054604');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1759371', '科学睡眠', '剧情', '斯蒂芬尼（盖尔•加西亚•贝纳尔 Gael García Bernal 饰）是一个充满奇思妙想和新鲜念头的小伙子，他从墨西哥来到法国，并在亲戚的帮助下找到了这份机械枯燥的办公室工作。斯蒂芬尼喜欢做梦，梦里有着各种奇妙的事情；因为害羞他在女孩面前十分拘谨。这天，斯蒂芬尼搬来了一个新邻居——那个笑容温暖的邻居女孩有着和他一样得名字：斯蒂芬尼(夏洛特•甘斯布 Charlotte Gainsbourg 饰)。斯蒂芬发现她的想象力天赋和自己竟然十分相似。他们用只属于彼此的方式交往着，命运的连结也由此开始。©豆瓣', '盖尔·加西亚·贝纳尔', '米歇尔·贡德里', 7.7, 16804, 'tt0354899', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1020475953.jpg', 0.8, 4.3, 26.7, 43.2, 25, '0.378880,-0.047972,-0.740485,0.683630,-0.496718,-0.202254,0.896523,0.103873,-0.704031,-0.296719,0.016171,0.989205,-0.224922,0.446446,0.063140,0.186539,-0.405118,-0.610519,0.116811,-0.221818,-0.193457,-0.519060,-0.332378,-0.302132,0.025966,-0.418492,0.428245,-0.075938,-0.153698,0.416568,0.278486,0.143950,-0.111410,0.603950,-0.340571,-0.003680,0.071375,0.153575,-0.146534,-0.055161,-0.047718,0.154866,-0.239780,0.186505,-0.112615,0.214980,0.512804,-0.223400,-0.349475,0.118697,0.176327,0.055313,-0.024846,0.153193,0.233695,-0.072821,0.279872,-0.088826,-0.147819,0.054730,0.127831,-0.030279,-0.755033,0.002382,-0.050037,0.241944,-0.507980,0.262619,-0.090936,-0.023120,0.253807,-0.723545,0.061309,0.160207,0.284960,0.563641,-0.232188,0.015320,-0.382843,-0.062992,0.546044,0.149793,-0.207972,0.623389,-0.664089,-0.465803,-0.287528,0.084902,-0.550322,0.006628,0.135284,-0.053052,0.025059,0.133771,-0.906281,0.120162,0.258537,0.085889,-0.007322,-0.536200,-0.046481,-0.573119,-0.168186,-0.530500,-0.576729,-0.045065,0.019077,-0.365968,0.790743,-0.898097,0.138784,0.618571,0.148997,-0.159322,0.572441,0.132314,-0.181258,-0.418254,-0.284482,0.273964,-0.040599,0.017663,0.098521,0.554243,-0.090979,0.111498,-0.526730,0.699699', '1292062', '24756472', '1309172', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1759386', '了不起的狐狸爸爸', '喜剧', '本片根据挪威藉英国儿童文学作家罗尔德·达尔（Roald Dahl）的同名儿童故事改编。狐狸爸爸（乔治·克鲁尼 George Clooney 配音）和狐狸太太（梅丽尔斯·特里普 Meryl Streep 配音）在乳鸽场偷窃时得知狐狸太太怀孕，狐狸爸爸承诺二人脱逃后不再行窃。两年后，狐狸爸爸不顾獾律师（比尔·默瑞 Bill Murray 配音）的反对，执意购入了位于养鸡场、火腿商和苹果酒三农场主地界上的树屋。一心想成为运动员的狐狸儿子艾什（詹森·舒瓦兹曼 Jason Schwartzman 配音）对新搬来暂住的表兄克里斯托弗森（艾瑞克·蔡斯·安德森 Eric Chase Anderson 配音）又妒又恨；而狐狸爸爸则再次按奈不住，联合树屋管理员负鼠凯利（华莱士·沃勒德斯基 Wallace Wolodarsky 配音）秘密对三农场主再行偷窃，直到引来一场人和动物的殊死大战……本片被提名英国电影电视工会最佳动画片及最佳音乐奖和金球奖最佳动画片，并获拉斯维加斯、洛杉矶、纽约和多伦多影评人协会的最佳动画片奖，及旧金山和圣地亚哥影评人协会最佳改编剧本奖。', '乔治·克鲁尼', '韦斯·安德森', 8.5, 187888, 'tt0432283', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2174698025.jpg', 0.2, 0.8, 12.1, 45.4, 41.5, '0.019133,-0.354645,-0.436685,0.567134,0.480704,-0.482682,0.341288,0.170962,-0.283306,-0.010395,-0.021868,0.973147,-0.443936,0.141914,0.233123,0.087355,-0.584794,-0.396776,-0.107573,-0.216593,0.253323,-0.424316,-0.104634,-0.084087,0.150330,-0.168629,0.450926,-0.490820,-0.080696,0.476398,0.524160,0.138363,-0.083812,-0.115316,0.260051,0.348760,0.580343,-0.113800,-0.364183,0.406161,0.265359,0.105212,-0.134609,-0.161592,0.308160,0.106532,0.417008,-0.251582,0.265631,-0.314622,0.377056,-0.075572,0.155694,0.128784,0.427814,-0.338937,0.455455,0.219526,-0.062430,-0.072227,-0.001075,-0.237030,-0.352121,0.129583,0.079804,0.222768,-0.212847,0.090571,-0.289751,0.209096,0.131055,-0.092155,-0.030540,0.084212,0.281483,0.179514,0.194212,0.223386,-0.226099,0.373424,0.029692,-0.083407,-0.069591,0.017953,0.342029,-0.656920,0.229110,-0.202935,-0.465174,0.047387,0.546632,-0.399448,0.064069,0.170325,-0.603138,-0.183928,-0.159720,-0.286619,0.030671,-0.145003,0.084451,-1.044828,0.134507,0.050806,0.248459,-0.346657,0.257896,-0.190608,0.492873,-0.685988,0.326377,0.523571,0.090306,-0.093277,0.434102,-0.234555,0.287562,-0.459612,-0.013187,0.040342,0.138256,0.181877,0.297170,0.195050,0.174600,-0.375057,-0.197611,0.320406', '34961898', '2075345', '1298616', '3077791');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1759849', '终极斗士2', '剧情', '昔日的重量级拳击冠军乔治（迈克尔•加•怀特 Michael Jai White 饰）在俄罗斯拍摄广告度日，某天他的家被人闯入后放置了大量毒品，于是乔治因贩毒入狱。这场陷害的幕后主使是俄罗斯当地的黑拳界，他们利用犯人们的搏击比赛开设赌局，而乔治出色的身后令他成为了监狱的目标，各方希望乔治能与狱中拳王伯伊卡（斯科特•阿金斯 Scott Adkins 饰）一战。拒绝成为黑拳界谋利工具的乔治在狱中处境艰难，除了狱警的侮辱，伯伊卡一众也不放弃任何挑衅乔治的机会，当乔治发现自己除了登上擂台已没有任何获得自由的可能以后，他毅然决定与伯伊卡决斗。然而拥有凌厉腿法的伯伊卡并不是一个低级的对手……©豆瓣', 'Michael Jai White', 'Isaac Florentine', 7.5, 9699, 'tt0443676', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1418301269.jpg', 0.6, 2.9, 36.3, 42.4, 17.7, '0.201363,-0.036112,-0.630385,0.687905,-0.022490,-0.323879,0.471782,0.098135,-0.376073,-0.470646,0.168010,0.891298,-0.099112,0.140485,0.010487,-0.257066,-0.103500,-0.678976,-0.229380,-0.018325,-0.301036,-0.561651,-0.179000,-0.608933,-0.149335,-0.331927,0.562805,0.163120,-0.457111,0.381310,0.511557,0.421699,0.311727,0.350736,0.009862,-0.213255,0.313180,-0.241542,-0.389032,0.426866,-0.126616,-0.033072,-0.023602,0.347300,0.395264,0.288460,0.359666,-0.369696,0.219372,-0.172660,0.380102,-0.338797,0.148260,0.196984,0.262270,-0.201776,0.044534,0.383696,-0.149484,-0.130799,0.134995,-0.098110,-0.951532,0.019825,-0.056791,0.082821,-0.319586,0.471008,-0.220348,0.084064,-0.014164,0.068107,0.129809,0.296885,0.211720,-0.122732,0.079421,-0.110849,-0.410568,0.169911,0.619554,-0.191201,-0.297229,0.036172,0.071592,-0.332368,-0.001097,-0.647414,-0.186630,-0.134392,0.546701,0.086689,0.145119,0.044751,-0.198504,-0.220250,-0.390666,-0.150128,0.158329,-0.297543,0.021938,-0.901513,-0.019897,-0.281723,-0.368900,0.066483,0.071240,-0.543711,0.381760,-0.743483,0.177479,0.693356,0.186773,-0.371207,0.518531,0.002073,0.129603,0.038583,-0.260915,0.302385,0.525380,0.225166,0.185732,0.113537,0.030616,-0.105653,0.098881,0.505338', '27073234', '1307442', '1793491', '30216729');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1759975', '开心鬼上错身', '喜剧', '小诗 ( Kris Aquino 饰 )养有一只可爱的大狗Magic，Magic从小就跟着小诗一起生活，他们的感情十分好。这次，小诗要到美国探亲，没办法带着Magic一同前往，于是只好委托男友阿杰帮忙好好照看Magic。阿杰表面上十分乐意，可是小诗走了之后，他马上招来一群猪朋狗友来家里作乐，根本不管Magic。无人照看的Magic跑了出去，半夜，迷路的Magic跑到了开心鬼（黄百鸣 饰）的神庙。看到风吹倒了蜡烛神台着火，聪明的Magic跑上去扑灭了火苗。为了感谢它的救命之恩，开心鬼显灵并用施法令Magic变成了人，但限期只有49天。变成人之后的Magic不会说人话，动作习性还是和狗一样，因而笑料百出。人模狗样的Magic在这49天内会有什么不一样的经历？©豆瓣', '黄百鸣', '黄百鸣', 7, 18873, 'tt0102183', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1994720479.jpg', 0.8, 5.1, 49.9, 31.9, 12.4, '0.357049,-0.141130,-0.599341,0.214945,-0.243381,-0.053964,0.404488,0.190848,-0.391261,0.079545,-0.062029,0.528980,-0.081984,0.310349,0.004919,0.092142,-0.420982,-0.300293,0.033224,-0.169383,-0.436150,-0.093284,0.181063,-0.063836,-0.164065,-0.009170,-0.108868,-0.121335,0.258296,0.497003,0.308818,-0.128074,-0.069419,0.485192,-0.459266,0.133927,-0.308371,0.136820,0.225673,0.179934,0.164037,0.068619,-0.266882,-0.066880,0.171522,0.039212,0.387440,-0.349799,-0.204828,0.046612,0.195752,-0.337750,0.246723,0.082713,0.288718,-0.125723,0.285818,-0.213953,-0.061872,0.093098,0.092869,-0.196972,-0.470243,0.377407,-0.066739,0.282583,-0.791674,0.127716,0.184282,0.038316,0.167058,-0.460225,0.147379,0.370366,0.015097,0.254139,-0.170890,0.184039,-0.797644,-0.114818,0.800065,-0.061389,-0.073464,0.283508,-0.109482,-0.061269,0.122076,-0.154885,-0.037456,-0.204179,0.335263,-0.009821,-0.491323,-0.296005,-0.504518,-0.173083,-0.028963,0.053246,-0.189593,-0.410174,-0.060096,-0.290822,0.106990,-0.482947,-0.216618,0.141635,0.017827,-0.130783,0.544477,-0.639939,0.299878,0.373032,0.210975,-0.533023,0.646519,-0.048537,-0.274858,-0.005600,0.011046,-0.060214,0.206931,0.578491,0.466627,0.375566,0.195531,-0.315563,-0.255400,0.133129', '26769480', '1297710', '1926007', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1760027', '快乐的大脚', '喜剧', '玛宝是帝企鹅家族中的另类分子，经常受到排挤歧视——原因是在帝企鹅里面，不会唱歌是一件丢人的事情，而玛宝恰恰是这样的企鹅。但是，他格外擅长舞蹈，舞技超群的绝艺却没有带给他幸运，铁面领袖把他赶出了族门。玛宝在外面的世界流浪，却碰上了另一个族群：阿德利企鹅。这群企鹅嗜好跳舞，自诩“2266歌舞团”，他们惊叹于玛宝的舞步，邀请他前去舞会狂欢。然而，在前往舞会的路上，玛宝遇到了一个踩着摇滚舞步的流浪者，他指引玛宝去解开心中的谜团：为什么企鹅食物会越来越少，为什么海平面有大型的铁皮船，为什么船上的人对企鹅残暴不仁。于是玛宝追踪一艘铁壳船，闯入了人类的世界。©豆瓣', '伊利亚·伍德', '乔治·米勒', 7.4, 80347, 'tt0366548', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199294148.jpg', 0.5, 3.6, 34.9, 45.1, 15.9, '0.260978,-0.015865,-0.773475,0.574900,-0.346142,0.200565,0.711151,0.134865,-0.452223,-0.163381,0.256969,0.843859,0.050185,0.091823,0.165572,0.186600,-0.122422,-0.236772,0.231901,-0.112577,-0.304521,0.035433,-0.218372,-0.365760,0.089877,-0.344757,0.524986,0.317484,-0.480736,0.510139,0.383389,0.216143,-0.198528,0.648073,-0.456759,-0.035545,0.333728,0.111536,0.378759,0.091794,-0.500259,-0.074665,-0.062396,0.279911,-0.099087,0.049979,0.511038,-0.468912,-0.082450,-0.149174,0.155456,-0.344082,0.075653,-0.171019,0.705214,-0.003819,0.167798,0.206544,0.114036,0.043929,0.156690,0.123228,-0.722571,0.056651,0.022363,0.288523,-0.590284,0.410976,-0.111308,-0.177984,-0.009397,-0.057698,0.237331,-0.067314,0.427937,0.282884,0.175173,0.199276,-0.672231,-0.041974,0.841163,0.086928,-0.210316,0.330624,-0.308699,-0.300544,-0.051041,-0.302888,-0.375911,-0.220141,0.348562,-0.310598,-0.366487,0.167892,-0.696434,0.245608,-0.094174,-0.264902,0.088619,-0.466592,-0.309217,-0.462878,0.228126,-0.349861,-0.206485,0.078142,0.067769,-0.197028,0.985405,-0.894342,0.250625,0.899201,0.181755,-0.517524,0.965936,0.122140,-0.122110,0.020256,-0.037698,-0.018950,0.095817,0.133110,-0.179582,0.406233,0.184043,-0.261117,-0.396571,0.523197', '3055049', '3755531', '30162520', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1760104', '加菲猫2', '喜剧', '慵懒搞怪的加菲猫又回来了！这次加菲和主人乔恩（Breckin Meyer 布瑞金•梅耶 饰）远赴英国旅行，一路上它花招不断，主仆俩闹出不少的笑话。巧合的是，伦敦有一只出身名门的猫和加菲长得极其相似，阴差阳错之下它们互换了身份，加菲因此享受了一把它梦寐以求的奢侈而豪华的生活。贵族猫继承了主人的泼天财富，引起了主人贪心亲戚达吉斯（Billy Connolly 饰）的忌恨。达吉斯坏招频出，意欲置其于死地，我们的假贵族加菲面对这个凶险的敌人该如何招架呢？©豆瓣', '布瑞金·梅耶', '蒂姆·希尔', 7.5, 84872, 'tt0455499', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2172910210.jpg', 0.4, 3, 34.4, 44.4, 17.9, '0.500291,-0.048757,-0.505254,0.324833,0.010441,-0.034375,0.405672,0.154349,-0.462457,-0.163348,0.261512,0.601841,-0.210305,-0.070248,-0.146930,0.091266,-0.092029,-0.245687,0.153702,-0.127868,0.146913,-0.167037,-0.467867,-0.074152,-0.130053,0.025443,0.070024,-0.016835,0.116582,0.339054,0.426296,0.241776,-0.131766,0.093895,-0.325495,-0.050123,-0.214413,0.231896,-0.050563,0.089883,-0.028151,-0.026875,-0.009706,-0.045102,0.033229,0.208840,0.434150,-0.381806,-0.099068,-0.156439,0.511839,-0.167414,0.029635,0.277415,0.212917,-0.282061,-0.009719,-0.208994,-0.143924,-0.152337,0.320952,-0.044326,-0.764323,0.036871,-0.000930,0.114265,-0.326997,0.447812,0.094318,-0.140032,-0.000219,-0.270852,0.126198,0.389563,0.224700,0.159740,0.118980,0.204836,-0.690209,-0.095950,0.735633,-0.012157,-0.151161,-0.037771,-0.477998,-0.457167,0.134878,-0.777264,-0.407495,-0.171662,0.463397,-0.095392,0.039284,0.218822,-0.607265,0.069969,-0.282090,0.257892,-0.073087,-0.494401,-0.070896,-0.311277,0.080199,-0.575927,-0.251164,-0.071164,0.280287,-0.273392,0.494818,-0.662184,-0.058656,0.685882,0.460061,-0.314771,0.439529,-0.220424,0.011500,0.095207,-0.216739,-0.005885,0.266356,0.142228,0.277141,0.273404,0.287801,-0.058305,-0.151605,0.382150', '1793491', '1877596', '1874704', '1438924');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1760622', '香水', '剧情', '十八世纪，让-马普蒂斯特•格雷诺耶（本•韦肖 Ben Whishaw 饰）出生在巴黎最肮脏、最恶臭不堪的地方——鱼市场上。格雷诺耶天生对气味有着惊人的天赋：无论恶臭还芳香，他都一一记住，并能轻易分辨各种气味。当他在孤儿院长到13岁的时候，被院长卖给了制皮匠。格雷诺耶在制皮铺过着犬马不如的生活。机缘巧合，格雷诺耶在香水巴尔蒂尼面前展露了其过人的天赋，进入了香水铺工作。但格雷诺耶并不仅仅满足于制作出世界上最芳香的香水，他梦想学得如何保存万物气味的方法。巴尔蒂尼告诉格雷诺耶香水的起源地在格拉斯，那里的人知道保存气味的方法。格雷诺耶拿着巴尔蒂尼的推荐信来到了格拉斯。格雷诺耶爱上了青春少女的体香，为了把这种香味保存下来，格雷诺耶最终走上了杀手的道路。©豆瓣', '本·卫肖', '汤姆·提克威', 8.5, 515929, 'tt0396171', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571500223.jpg', 0.6, 1.4, 12.8, 43.1, 42.2, '0.316850,0.043856,-0.561228,0.431696,-0.194789,-0.151240,0.315909,0.287093,-0.470682,-0.390461,-0.206094,0.654405,0.070070,-0.061032,0.333549,0.190285,-0.124739,-0.440983,0.086264,-0.409865,-0.331622,-0.199067,-0.397512,-0.073544,-0.148400,-0.724686,0.295101,0.111438,-0.256874,-0.067466,0.173123,0.322397,0.258945,0.047839,-0.195640,-0.352878,0.151799,-0.347528,-0.252215,0.181620,0.026224,-0.283712,0.243580,0.089970,0.316585,0.033763,0.635679,-0.476052,0.135671,0.000530,0.148553,0.089442,0.287086,0.123457,-0.183062,-0.471415,0.017064,0.282149,-0.067704,-0.310180,0.224241,0.026552,-0.810921,-0.095661,-0.143852,0.355983,-0.504727,0.266758,-0.351983,-0.014537,-0.147129,-0.592244,-0.017700,-0.137491,-0.019026,0.464291,-0.042270,-0.273893,-0.694286,-0.404132,0.234552,0.066135,-0.208842,0.376447,-0.741348,-0.615501,0.058347,-0.325099,-0.128081,0.080762,0.241186,0.404984,0.127619,0.146015,-0.975176,0.003457,-0.082465,0.010818,0.143368,-0.155629,-0.373755,-0.697350,-0.240623,-0.142058,-0.191495,-0.186219,0.118098,-0.382426,0.374574,-0.507710,0.097891,0.439871,0.145062,-0.104131,0.406261,-0.109729,-0.168635,-0.093027,-0.230270,0.585001,0.426819,-0.010632,0.232276,0.791923,0.289265,-0.101477,-0.162291,0.699113', '20283482', '26290398', '1292680', '1293531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1762492', '舞动天地', '剧情', '杜兰尼（安东尼奥·班德拉斯 Antonio Banderas 饰）是一位小有名气的舞蹈家，但是，事业上的成功并不能弥补他的空虚感，因为在杜兰尼的内心里，将舞蹈的精髓发扬光大，让每一个人都感受到舞蹈的乐趣和自由才是他真正想要到达的终点。怀抱着这样的理想，杜兰尼开始行动了。杜兰尼将据点设在了位于纽约的一间公共学校之中，虽然做好了最坏的打算，可接下来发生的事情依旧让杜兰尼感到沮丧和失落。不过世上无难事只怕有心人，随着时间的流逝，越来越多的学生们加入到了杜兰尼的舞蹈学习班里来，通过和这些年轻又富有活力的年轻人交流，杜兰尼也找到了自己新的人生意义。©豆瓣', '安东尼奥·班德拉斯', '丽兹·弗德兰德', 7.7, 5442, 'tt0446046', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p643330341.jpg', 0.2, 2.4, 29.7, 47.5, 20.2, '0.341482,0.234672,-0.904372,0.680124,-0.167859,-0.289019,0.841435,-0.109227,-0.544050,-0.207220,-0.127273,0.719520,-0.122041,0.420824,0.308088,0.072506,-0.321079,-0.795569,-0.078901,-0.291591,-0.317808,-0.458182,-0.299597,-0.033306,-0.258606,-0.245327,0.773832,0.365173,-0.205675,0.415955,0.235677,-0.057282,0.272180,0.523805,-0.258731,-0.041703,0.113735,0.029365,-0.122956,0.241390,0.380721,-0.201397,-0.240133,0.275843,0.108157,0.374850,0.638819,-0.104491,-0.071569,0.173747,0.320911,-0.223651,-0.124944,0.284962,0.158258,0.205167,0.131839,0.178473,-0.340904,0.271031,-0.214803,-0.201055,-1.077393,0.002647,0.116769,0.154654,-0.565543,0.641239,0.041498,-0.418111,0.209843,-0.469429,0.247096,0.483649,0.251576,0.465096,-0.377172,0.136310,-0.515652,-0.154473,0.963503,0.027358,-0.299003,0.489425,-0.255694,-0.570407,-0.071444,-0.246967,-0.177808,-0.235440,0.042127,0.367130,-0.022693,0.025814,-0.784071,0.237620,-0.097553,-0.443645,-0.141242,-0.570513,0.104004,-0.567692,-0.076469,-0.363304,-0.417952,0.006841,0.217079,-0.410422,1.009011,-0.986890,0.176983,0.623535,0.315833,-0.354567,0.638113,0.052920,0.294692,-0.068711,-0.251074,0.201454,-0.141152,0.619678,0.065533,0.750963,-0.165642,-0.394009,-0.565560,0.719817', '2053515', '1793491', '25928048', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1762834', '46亿年之恋', '剧情', '在一所监狱，彪悍好斗的香月史郎（安藤政信饰）被绳子勒死，与他有暧昧传言的有吉淳在一旁反复叨念是他杀的。警察开始调查这桩奇特的凶案。有吉淳（松田龙平饰）原是一名在GAY吧打工的男妓，遭客人虐待后，将其杀客人，由此被投入牢房。而香月史郎是在不良环境中长大的男子，打死人并和有吉淳在同一天被押入监狱。性格截然相反的他们关系却十分亲密，在狱中香月一直充当着有吉的保护人。有吉发现金字塔和火箭，看见三重彩虹……囚犯们证词杂乱无章，调查毫无头绪，新调来的监狱长似乎也与这起事件有关，事件的真相藏在迷雾之中。©豆瓣', '松田龙平', '三池崇史', 7.2, 8392, 'tt0497876', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p779637698.jpg', 1.4, 7.3, 37.1, 37.7, 16.6, '0.317563,-0.253879,-0.702550,0.282580,-0.243997,0.279774,0.937493,0.132162,-0.864730,-0.244821,0.392544,0.477820,-0.393416,0.049062,0.115369,-0.085154,-0.342392,-0.804483,-0.146856,-0.384381,-0.380041,-0.677981,0.029356,-0.204808,0.038240,-0.446164,0.456058,-0.027212,-0.208732,0.136715,0.231286,0.423971,-0.448516,0.460105,-0.312912,0.077878,0.043732,-0.087813,-0.041917,0.035730,-0.273245,-0.502950,-0.223107,-0.116026,0.200394,0.463728,0.707813,-0.194310,-0.410175,0.206109,0.358586,-0.256676,-0.252743,0.176785,0.633018,-0.061243,-0.020573,0.455882,-0.239952,-0.169521,0.096780,-0.281868,-0.541585,0.074031,0.195763,0.347671,-0.419940,0.422381,0.127729,0.165709,0.161924,-0.132632,0.230119,0.260360,0.020593,0.451807,0.054712,0.140849,-0.767494,0.053732,0.693852,0.053042,-0.096759,0.034372,-0.235257,-0.425326,-0.161943,-0.111073,-0.086029,-0.104222,0.464761,0.045587,-0.468431,0.086445,-0.345815,-0.037854,0.066973,-0.048108,-0.087620,-0.408969,-0.317733,-0.682186,-0.197894,-0.600059,-0.415537,0.109328,0.019535,-0.169936,0.547953,-0.897903,0.319461,0.530482,0.291727,-0.322722,0.576493,0.090629,-0.053502,0.039412,-0.279135,0.049850,0.401948,0.409678,0.403292,0.328249,-0.179861,-0.088864,-0.509050,-0.002350', '3263169', '1308755', '1947080', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1763132', '时间', '剧情', '相貌在爱情中是否能敌得过时间？世喜（成贤娥 饰）和智宇（河正宇 饰）已经相恋多年，但是世喜慢慢觉察，爱情好像被时间冲淡了，智宇已经开始厌倦这段感情。世喜惊恐，决定离开男友。半年后，智宇交往了一位新女友，他觉得她身上有世喜的味道，于是陷入了几年前和世喜热恋的甜蜜回忆中 ，即使新女友的相貌比世喜漂亮，但是他的爱与世喜的样子已经融为一体。智宇向新女友坦白自己的感受，却想不到，眼前的新女友正是世喜，她为了重获男友欢心，去了整容。世喜听到智宇对自己的一往情深，不禁狂喜。然而二人能否再续前缘，迎来大团圆结局？©豆瓣', '成贤娥', '金基德', 7.5, 30646, 'tt0497986', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p584864044.jpg', 0.7, 4.1, 33, 45, 17.2, '-0.090361,0.144866,-0.648192,0.454472,-0.014836,-0.599509,0.644411,-0.180740,-0.509399,-0.363574,-0.198431,0.634101,-0.465008,0.543837,0.350050,0.187463,-0.189923,-1.043549,-0.019473,-0.435326,-0.196444,-0.212898,-0.374955,0.009669,0.006307,-0.275661,0.669196,0.161008,0.086587,0.605343,0.512556,0.038418,-0.099263,0.628615,-0.009639,-0.006304,0.085913,0.271473,-0.467932,-0.056942,0.230786,-0.012214,-0.088922,0.267243,-0.268800,0.353269,0.762721,-0.052061,-0.314728,-0.048449,0.481475,0.262440,-0.030481,0.289934,0.120422,0.165592,0.377405,0.138065,-0.315804,-0.108688,-0.167377,-0.110873,-0.583432,0.185425,-0.149941,0.025241,-0.371507,0.432385,-0.069904,-0.182323,0.181726,-0.360901,0.095483,0.279841,0.600514,0.573764,-0.444062,0.029722,-0.225991,0.150779,0.746479,0.178685,-0.209957,0.925739,-0.153107,-0.387760,-0.264154,0.035077,-0.455248,0.059660,-0.044664,0.268377,-0.246761,0.328793,-0.419251,0.072827,-0.304740,0.170750,0.106011,-0.463322,-0.061438,-0.217760,-0.613458,-0.591667,-0.395879,-0.154431,0.177441,-0.484166,0.704820,-0.818107,0.238649,0.282237,0.195719,-0.508353,0.588764,0.339703,-0.047877,-0.346509,0.109620,0.500260,-0.346647,0.050618,0.288630,0.213238,-0.172353,0.057954,-0.439718,0.414042', '25777330', '34973399', '27191829', '26263428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1763134', '汉江怪物', '剧情', '康斗（宋康昊饰）是一个平凡又有些糊涂的中年男人，他带着女儿玄舒（高雅成饰）与家人一起生活，在汉江边经营小店，过着安静祥和的生活。康斗父亲熙峰（边熙峰饰）是一个和蔼老人，弟弟南日（朴海日饰）是家里唯一的大学生，却失业没有工作。他时常牢骚并酗酒，对现实不满。妹妹南珠（裴斗娜饰）是个射箭运动员，却常在关键时刻掉链子。一天，人们聚集在汉江边上，惊奇地发现攀在大桥的桥墩上，一只从未见过的不明怪物。突然怪物窜到了岸边，冲进围观的人群中。康斗想马上带着女儿逃离，但玄舒却被怪物抓走了，这个普通家庭遭受了空前的打击，整个城市也如临大敌，他们该如何面对怪物？©豆瓣', '宋康昊', '奉俊昊', 7.6, 268901, 'tt0468492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2512336853.jpg', 0.6, 3.1, 31.5, 47.5, 17.3, '0.252615,-0.224556,-0.494780,0.441751,-0.244070,-0.156760,1.032157,0.199330,-0.532325,0.018960,0.427205,0.653613,-0.253694,0.411552,-0.060472,0.084263,-0.136970,-0.313818,-0.073874,0.075087,-0.295655,-0.207784,-0.252619,-0.189328,-0.081158,0.001589,0.351866,-0.001673,-0.065868,0.581897,0.193718,0.110670,-0.186572,0.711293,-0.492468,0.093718,-0.054489,0.019801,0.157155,-0.011496,-0.107682,-0.366684,-0.302054,0.099355,-0.063629,0.258066,0.679002,-0.093547,-0.089331,0.044064,0.117496,-0.246781,-0.145551,0.140722,0.502601,-0.294484,0.003348,-0.243553,-0.026040,-0.088843,0.146218,-0.023382,-0.352286,0.017015,-0.069465,0.382823,-0.712761,0.681111,0.167066,-0.109833,0.017714,-0.310225,0.162108,0.073750,-0.090143,0.634914,-0.259339,0.026999,-0.651347,0.041644,0.560693,0.075458,-0.161097,0.328104,-0.414566,-0.373955,0.046895,-0.223780,-0.634572,-0.240610,0.223489,-0.114561,-0.438861,0.196691,-0.443632,0.368103,-0.124282,-0.148962,-0.067369,-0.374523,-0.417531,-0.245913,0.180183,-0.493743,-0.352716,0.181853,-0.210955,-0.045590,0.693830,-0.658896,0.104270,0.546889,0.290497,-0.325556,0.665497,0.019884,0.051776,-0.008891,-0.062120,0.041602,-0.024131,0.506608,0.232519,0.415746,-0.374854,-0.102395,-0.317957,0.485782', '21619567', '1307561', '1783772', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1763905', '我是', '剧情', '影片讲述了被遗弃的小男孩孔德尔（彼得·贾戈尔斯基 Piotr Jagielski 饰）不断寻求自身归属感，找寻精神家园的命运故事。从小被母亲遗弃的孔德尔，在孤儿院的生活充满压抑和克制。母亲一心寻找所谓的真爱，嫌弃孔德尔是自己的累赘，非但不收留儿子，反而置自己的亲生骨肉于不顾。面对母亲的抛弃，小孔德尔失声痛哭。终于，才十一岁大的孔德尔毅然逃离孤儿院，去追寻属于自己的家园。孔德尔开始了他的流浪生活，寄住在一艘废弃的破船上，于此有了一个“家”。弃船对面住着一户富裕人家，小女孩跟他年纪相仿，受过良好的教育生活条件优越。然而因为长相难看，总是受到排挤和冷落，直到遇见一样孤独的孔德尔，幼小的心灵自此有了彼此的慰藉。本片荣获2006年柏林电影节特别致意最佳影片奖。©豆瓣', 'Piotr Jagielski', '多罗塔·肯杰扎夫斯卡', 9, 11594, 'tt0478175', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p537073155.jpg', 0.3, 0.8, 7.9, 32.9, 58.1, '0.157885,-0.217391,-0.672118,0.568140,-0.204382,-0.596653,0.660026,0.266186,-0.485557,-0.189499,0.090513,0.785453,0.116424,0.477609,0.153773,-0.020963,-0.051133,-0.368529,-0.114474,-0.067762,-0.157034,-0.619563,-0.140301,-0.250700,-0.195189,-0.361944,0.515875,0.017093,-0.246640,0.283306,0.229781,0.495330,-0.041056,0.398211,-0.293804,0.131242,-0.130536,-0.014679,-0.234080,-0.065463,-0.170238,0.017686,-0.086619,-0.090729,0.049457,0.429319,0.596027,-0.239264,-0.098922,-0.341797,0.358233,-0.084855,-0.029696,0.065521,0.196947,-0.117291,0.219077,-0.099681,-0.247393,0.019195,0.262628,-0.437797,-0.287852,-0.183504,0.387160,0.005857,-0.659832,0.530627,0.192352,-0.304532,0.162144,-0.367553,0.149236,0.375660,0.091396,0.434205,-0.327144,0.158750,-0.495333,0.219064,0.665567,-0.042111,-0.443122,-0.008021,-0.486804,-0.197742,0.157444,-0.424398,-1.047163,-0.124174,0.409359,0.126806,-0.451207,0.304885,-0.275276,-0.118923,-0.248250,0.115317,0.251907,-0.599139,0.064048,-0.586914,-0.218278,-0.343486,-0.107425,-0.173562,-0.080591,-0.375667,0.703141,-0.747333,0.629474,0.323661,0.348427,-0.467507,0.608066,0.101302,0.186856,0.009224,-0.040887,0.782545,0.030713,0.311254,0.001289,0.114858,-0.184417,0.296291,-0.173603,0.708450', '1292720', '26348103', '1460341', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1763916', '浪客剑心：星霜篇', '剧情', '明治政府建立二十余年，新时代虽已来临，却似乎与人们心中——尤其是维新志士心中的那个理想国度相差甚远。国家仍处在大时代的动荡惶恐之中，战争的阴影仍笼罩在日本的上空。当年的浪漫剑客如今纷纷尘埃落定：弥彦成长为正直善良的剑客；左之助也少却了青春孟浪，变得沧桑；剑心的儿子剑路同样拜入比古清十郎的门下，誓要成为绝世高手，却与父亲分外隔膜；剑心接受政府的任务赶赴大陆战场，为了赎回前半生的罪过而疲于奔命，逆刃刀从此封存，家中只留下病弱的阿薰苦苦等待。这不再是关于明治剑客的浪漫谭，这是一个英雄迟暮的哀婉诗篇……©豆瓣', '凉风真世', '古桥一浩', 7.9, 9402, 'tt0294885', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2394734873.jpg', 2.8, 4.1, 20, 39.8, 33.3, '-0.050912,0.285941,-0.657767,0.657607,0.193770,-0.355063,0.605743,0.126610,-0.415389,-0.476210,0.210946,0.466215,0.115605,0.219034,0.281572,-0.371084,-0.013199,-0.744120,-0.334193,-0.132170,-0.034767,-0.201801,-0.351461,-0.023427,-0.490896,-0.200811,1.077476,0.484723,-0.004950,0.295624,0.272955,0.363344,-0.019907,0.494004,-0.265506,-0.248016,-0.135479,0.064063,-0.330952,-0.163044,-0.293213,-0.218824,-0.232746,0.275403,-0.204216,0.359860,0.492545,-0.238516,-0.228603,-0.410184,0.365804,-0.079971,-0.346466,-0.101887,0.158282,0.040028,0.097486,0.209140,0.076651,-0.072822,-0.189708,-0.219955,-0.722437,0.115949,0.478095,-0.010898,-0.266066,0.351599,-0.097215,-0.086467,-0.174837,-0.078341,0.100451,0.058990,0.352037,0.519761,-0.189146,0.103759,-0.224359,0.215777,0.736714,0.140664,-0.538543,-0.003557,-0.327352,-0.421934,-0.028809,-0.410273,-0.343449,-0.014399,-0.022089,0.080727,0.171491,0.906947,-0.539339,0.188036,-0.243692,0.090457,0.109302,-0.420939,-0.202907,-0.115516,-0.279789,-0.399475,-0.052919,0.075053,0.276760,-0.025563,0.978176,-0.625963,0.176613,0.017848,0.050078,-0.243961,0.489273,0.250745,0.113928,-0.205099,-0.351332,0.697596,-0.228408,0.333941,-0.228289,-0.089737,-0.184985,0.054119,-0.341192,0.458558', '33407124', '3001114', '26667010', '10746430');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1763939', '阳光下的罪恶', '剧情', '大名鼎鼎的名侦探波洛（大卫·苏切特 David Suchet 饰）因体重超标而导致心脏问题，恢复健康迫在眉睫。于是他和他的助手海斯廷斯（休·弗拉瑟 Hugh Fraser 饰），来到以海滨浴场和海岛风情著称的伯格小岛上度假休养。这座恍如世外桃源的孤岛在莱瑟库姆湾旁，络绎不绝来到此地度假的游客们都住在岛上唯一的旅馆里。在看似云淡风轻的惬意时光里，一场突如其来的谋杀打破了小岛的平静。美艳轻佻的少妇阿伦娜·马歇尔（路易斯·德拉米尔 Louise Delamere 饰）被掐死在海滩上。然而这起凶杀案并非像表面上的那么简单，每一个人都拥有不在场证明。在错综复杂的线索中，波洛抽丝剥茧，最终发现真凶竟是他们最亲近的人。©豆瓣', '大卫·苏切', 'Brian Farnham', 8.4, 7093, 'tt0276115', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2220608777.jpg', 0.2, 0.5, 12.1, 53.2, 34.1, '0.309157,-0.075574,-0.921620,0.555765,-0.012214,0.165944,1.001072,0.150004,-0.484038,-0.135456,0.039870,0.606874,-0.254576,0.448030,0.634048,0.210480,-0.511092,-0.353570,0.001361,-0.339957,-0.197973,-0.645293,-0.435656,-0.229435,0.068895,-0.292208,0.275185,0.217806,-0.113639,0.476913,0.035141,0.402991,-0.149634,0.445984,-0.303395,-0.115430,0.048226,-0.163297,-0.032292,0.173121,-0.218120,-0.281046,-0.099452,0.240397,0.094643,0.539682,0.587104,-0.445514,-0.111984,0.117934,0.096074,-0.206296,0.119137,0.019613,0.182126,-0.447768,0.085337,0.242231,-0.420744,-0.046566,0.427817,-0.398602,-0.382856,0.123039,0.218812,0.370209,-0.370506,0.613752,0.083365,-0.081047,-0.245072,-0.158317,0.152884,0.063198,0.153070,0.159932,0.004629,0.111289,-0.606585,-0.045761,0.545301,0.367255,-0.437715,0.335148,-0.173999,-0.379998,-0.026423,-0.407387,-0.269684,-0.073627,0.083090,-0.139760,-0.031069,0.174517,-0.533113,0.040006,-0.283747,-0.138427,-0.402448,-0.281678,-0.379609,-0.901523,-0.003894,-0.324593,-0.220578,0.088405,-0.117744,-0.305901,0.409617,-0.476995,0.050035,0.356370,0.082831,0.005431,0.580355,-0.125820,0.256991,-0.136020,-0.323259,0.450686,0.401524,0.272942,0.063806,0.348850,-0.367602,-0.057621,-0.534875,0.633105', '1316693', '10466639', '1301686', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1764342', '蜥蜴', '爱情', '雅丽（姜惠贞 饰）仅与一只蜥蜴为伴，她自称自己身上带有咒语。她一直孤立自己，直到她认识了新同桌赵强（曹承佑 饰）。这位新同学会相信她说的话，愿意陪在她的身边。不知为何，雅丽不见了。再见面是高二的时候，赵强以学习的名义找到雅丽，这时雅丽已不再穿着黄色雨衣，出落成一个美丽大方的女孩。两人共度的时光非常快乐，但雅丽又再次消失，赵强再次伤心。在雅丽消失的日子里，赵强当上了一名银行职员。他一直没有放弃寻找雅丽，但他雇佣了私家侦探也找不到雅丽的下落。某天，雅丽的突然出现使赵强兴奋不已，但雅丽是来道别的。©豆瓣', '曹承佑', '姜知垠', 7.2, 6306, 'tt0777837', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2200540394.jpg', 0.8, 5.7, 41.4, 37.2, 15, '0.215106,0.087448,-0.761519,0.266427,-0.211537,-0.580759,0.854296,0.159597,-0.494723,-0.333466,0.286333,0.743538,-0.129935,0.240043,-0.017279,0.396509,-0.357280,-0.685215,0.348750,-0.382132,0.015224,-0.346613,-0.173628,0.144995,-0.244005,-0.062850,0.304525,-0.500898,0.208750,0.824483,0.315371,0.179626,0.173816,0.607593,-0.100121,0.150605,0.116754,0.146809,-0.161170,0.463409,0.235993,0.195733,-0.425846,-0.061654,-0.187232,0.224439,0.288627,-0.098814,0.012887,0.015147,0.398283,-0.201688,0.051579,0.030942,0.139443,0.191420,0.346310,0.000084,-0.529088,0.023017,0.126627,0.306116,-0.417844,0.375127,-0.016042,0.451370,-0.616819,0.063613,-0.131465,-0.574618,0.386744,-0.800572,0.148044,0.316312,0.185573,0.244434,-0.274463,0.324887,-0.705138,0.057057,0.509968,0.196701,-0.356992,0.429242,0.075596,-0.248805,0.248317,0.050719,-0.389133,-0.074918,-0.115227,0.234579,-0.139812,-0.166954,-0.643768,0.074592,-0.393485,0.026932,-0.092988,-0.146517,-0.475452,-0.172542,-0.420775,-0.434972,-0.466208,-0.106637,-0.200329,-0.222931,0.773520,-1.166584,0.367527,0.379648,0.533824,-0.396390,0.656727,0.551024,0.099092,0.016956,-0.081587,0.000276,-0.322254,0.437143,0.130344,0.288666,0.111058,-0.250831,-0.594099,0.278237', '1308755', '1292219', '2052978', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1764361', '四月一日灵异事件簿剧场版：仲夏夜之梦', '动画', '普通高中生四月一日君寻（福山润 配音），有着异于常人的体质，他可以看到并且吸引各种鬼怪，而如果和同学百目鬼静（中井和哉 配音）在一起时，就不会被鬼怪缠上。因为命运的牵引，四月一日走进了一家奇怪的店里，这是一家可以帮客人实现任何愿望的店，但是店主人壹原侑子（大原沙耶香 配音）同时要拿走和这愿望对等的代价。侑子答应帮四月一日实现远离鬼怪的愿望，而作为代价，四月一日要留在店里打工。有一天，一个阴郁的少女走进店里，委托侑子实现自己的愿望。由此，侑子、四月一日和百目鬼三人来到了一所诡异的豪宅里。在这里，他们遇到一群奇奇怪怪的收藏家，同时，四月一日在这所大房子中遭遇了各种各样的灵异事件，犹如在仲夏夜里做了一场诡秘的梦……©豆瓣', '大原沙耶香', '水岛努', 8.7, 11849, 'tt0466405', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2181265210.jpg', 0.1, 0.5, 12.2, 39, 48.2, '0.155385,-0.025869,-0.383577,0.230007,-0.219274,-0.075932,0.719105,0.132096,-0.570537,-0.315640,-0.050054,0.806185,-0.184725,0.412594,0.405501,-0.039325,-0.109200,-0.495311,-0.079595,-0.417705,-0.187276,-0.270174,-0.144419,-0.278648,-0.059047,-0.289608,0.434645,0.336197,0.079709,0.471555,0.311805,0.180668,-0.350202,0.198119,-0.147263,-0.254338,-0.040306,0.396667,-0.206469,0.511322,-0.123578,-0.264637,-0.232831,-0.044688,0.127757,0.195134,0.598519,-0.276683,-0.470757,-0.101108,0.308457,-0.224363,-0.135892,0.396403,0.004682,0.102233,0.375393,0.346492,-0.281062,-0.023977,0.145221,-0.266215,-0.727855,-0.090085,0.268489,0.010477,-0.469077,0.297287,0.205668,-0.140390,0.277552,-0.370988,0.267934,0.445372,0.399606,0.442796,-0.090744,-0.068219,-0.585288,0.063339,0.759440,-0.259164,-0.025799,0.559409,0.070230,-0.274427,-0.121308,0.199539,-0.298523,0.269331,-0.030710,0.299359,-0.346479,-0.010147,-0.687005,-0.130806,-0.079409,-0.077385,-0.011373,-0.133269,-0.188779,-0.554649,0.220617,-0.248340,-0.025633,0.311379,0.480384,-0.324297,0.594992,-0.911367,0.346030,0.463683,0.513372,-0.098414,0.723077,-0.199175,0.030390,-0.076508,0.045381,-0.157122,-0.038943,0.450643,-0.025604,0.495151,0.031297,-0.077724,-0.443219,0.492524', '3055049', '1783461', '1793491', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1764796', '机器人9号', '科幻', '机器人9号（伊利亚•伍德 Elijah Wood 饰）突然醒来，发现身边的世界充满危机，四处残败，一片末世景象。9号带着一个画有三个奇怪符号的圆形物体逃到街上，幸遇发明家机器人2号（马丁•兰道 Martin Landau 饰）给自己装上了声音，但2号却不幸被机器怪兽抓走。9号找到了老兵1号（克里斯托弗•普卢默 Christopher Plummer 饰）、机械工5号（约翰•雷利 John C. Reilly 饰）、疯癫画家6号（克里斯品•格拉夫 Crispin Glover 饰）和大力士8号（弗雷德•塔塔绍尔 Fred Tatasciore 饰）。9号与5号擅自出行援救2号，危急时被女武士7号（詹妮佛•康纳利 Jennifer Connelly 饰）救下，但无意中9号却令终极机器兽复活。带着自己从哪里来以及生存使命的问题，9号决定想尽办法制服机器兽，拯救全世界……', '伊利亚·伍德', '申·阿克', 7.5, 73011, 'tt0472033', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p494268647.jpg', 0.4, 3.2, 32.6, 46.5, 17.2, '-0.296551,0.459083,-0.454776,0.452916,0.170307,-0.030258,0.804409,-0.109034,0.072104,-0.460210,0.275520,0.502957,0.173405,0.357697,0.254431,0.246272,-0.391170,-0.255056,0.214080,-0.198861,-0.702900,-0.257974,-0.109468,-0.252155,0.165956,-0.450114,0.433110,-0.097225,0.103077,0.471497,0.355441,0.529624,-0.004666,0.543960,-0.217184,-0.180413,0.455723,-0.174174,0.210630,0.264973,-0.713470,0.087298,0.011587,0.062928,-0.159962,0.113790,0.976413,-0.677777,0.157349,-0.165653,0.098238,0.200195,0.009101,-0.063985,0.268605,-0.035814,-0.194676,-0.179436,0.014670,0.007280,0.266622,0.097409,-0.419759,-0.008577,-0.097711,0.005877,-0.525013,-0.033779,-0.635998,0.314765,-0.019181,-0.061986,0.245799,-0.163473,0.460064,0.608459,-0.188344,0.107464,-0.507452,-0.046471,0.243808,-0.011939,-0.424443,0.218526,0.249468,-0.511851,-0.043775,-0.193285,-0.312515,0.093109,0.611386,-0.040465,-0.031530,0.082596,-1.116046,0.071440,-0.393387,-0.260406,-0.004937,-0.247199,-0.229018,-0.712435,0.321660,0.216435,-0.157388,0.435802,-0.086991,0.052656,0.691299,-0.240786,0.454339,0.530126,-0.277811,-0.298270,0.768541,-0.083090,-0.027869,-0.525272,0.071812,0.143966,0.450080,0.489899,0.029852,0.398155,-0.325133,-0.181058,-0.355950,0.298655', '26290398', 