INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1764842', '狂野大自然', '喜剧', '纽约动物园里的狮王萨姆森是园内唯一一头出生在动物园外的动物，他经常对其他动物夸夸其谈他的野外经历，而事实上，他不过出生在马戏团，更别说什么野外经历。父亲丰富多彩的经历深深刺激了小狮子瑞恩，他渴望能到野外体验一番。意外发生了，阴差阳错之下瑞恩被送上了开往非洲放生野生动物的货轮。丢失了儿子的萨姆森焦急万分，于是，他率领着动物园里的一班动物一起来到了非洲丛林寻找儿子。这帮以前在动物园里养尊处优的动物们在弱肉强食的非洲丛林该怎样面对激烈的野外竞争呢？©豆瓣', '基弗·萨瑟兰', '史蒂夫·威廉姆斯', 6.7, 4914, 'tt0405469', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2239578392.jpg', 1.6, 8.9, 52.9, 27.2, 9.5, '0.782247,-0.011772,-1.032647,0.499918,0.141602,0.054521,0.743503,-0.311076,-0.660338,-0.012515,0.160613,0.618718,-0.141655,0.456492,-0.107425,-0.025627,-0.447680,-0.228726,-0.132313,-0.038844,-0.381046,-0.129960,-0.643978,-0.253390,0.194097,0.150631,0.340867,0.020512,0.006701,0.433837,0.184210,0.125754,-0.203869,0.272178,-0.389347,0.152439,0.222316,0.394469,-0.067259,0.164013,0.150559,-0.093890,-0.224469,-0.018153,0.252891,0.025215,0.824250,-0.408137,-0.267760,-0.458130,0.272443,-0.208742,0.133712,0.295367,0.445761,-0.148189,0.205566,-0.053850,0.260719,0.259159,-0.083256,-0.019355,-0.335085,-0.052603,-0.215565,0.247099,-0.703194,0.286766,0.420215,-0.043627,0.213516,-0.278361,0.294467,0.192573,-0.010554,0.437396,0.026909,-0.201380,-0.488453,0.266407,1.042920,-0.406547,-0.176906,0.133187,-0.244116,-0.570189,0.239368,-0.537741,-0.599852,-0.095161,0.057994,-0.096589,-1.037768,0.177629,-0.779346,0.511675,0.110956,-0.383107,-0.347118,-0.059271,-0.171677,-0.689315,0.095843,-0.788828,-0.289273,-0.052884,0.185050,-0.296407,0.466535,-0.799929,0.278291,0.653070,0.312759,-0.351228,0.568082,-0.300813,0.152686,0.088516,0.030933,0.395236,0.052699,0.361465,0.017483,0.324662,-0.040554,-0.118787,-0.387542,0.660015', '34461680', '3055049', '2002683', '1296538');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1765009', '歌舞青春', '剧情', '特洛伊（扎克·埃夫隆 Zac Efron饰）和盖布利拉（瓦妮莎·哈金斯 Vanessa Hudgens饰）本是分属两个世界的年轻人。特洛伊从小就作为篮球种子来培养，而盖布利拉则是个高智商的学习优秀学生。新年晚会两人被推上舞台，合唱了一首美妙的歌，彼此的内心都燃起了火花。碰巧的是，两人竟成为了高中同班同学。艺术老师打算挑选合适的人选参演一部音乐剧，特洛伊和盖布利拉凭着优美默契的歌声打动了老师。要获得最终的演出资格，他们还得在第二轮面试中打败对手，然而，事情却起了波折。这边篮球队正为了一场重要的比赛而加紧训练，队员纷纷要求特洛伊专心练球；那边学术比赛即将开始，众人反对队员盖布利拉为音乐剧的事情分心。更糟糕的是，他们的竞争对手从中作梗，把篮球赛、学术比赛和音乐剧面试排在了同一天。鱼与熊掌该怎样取舍，两个年轻人当机立断，妙计横生。©豆瓣', '扎克·埃夫隆', '肯尼·奥特加', 7.7, 151721, 'tt0475293', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2567963309.jpg', 0.6, 2.6, 28, 46.9, 22, '0.135112,-0.168116,-0.373989,0.525353,-0.175469,-0.153622,0.267061,0.022953,-0.241955,0.004060,0.216482,0.603970,-0.360849,0.065706,0.480047,-0.117463,-0.323817,-1.028130,0.187620,0.047516,-0.175547,-0.459310,-0.111287,-0.137937,0.153213,-0.262389,0.758340,-0.069102,-0.131588,0.585186,0.417974,0.028756,-0.041674,0.131715,0.041142,-0.178182,0.110313,0.168972,-0.211556,0.170038,-0.029837,-0.037697,-0.637483,0.098115,0.288448,0.359106,0.483022,0.043898,0.305143,0.124985,0.215383,-0.301210,0.106724,0.091596,0.413474,-0.004333,0.252667,0.179648,0.148111,0.258748,-0.204858,-0.244698,-0.643834,0.175008,0.108172,-0.042563,-0.569424,0.795769,0.066180,-0.065325,0.235321,-0.015353,-0.068180,0.321991,0.243275,0.341023,-0.039328,-0.213346,-0.078222,0.226923,0.620161,-0.172339,-0.054682,0.328911,-0.149366,-0.385842,-0.052891,-0.134174,-0.317406,0.077430,0.569259,0.056572,0.319394,0.036684,-0.533456,-0.199037,0.000412,-0.194529,0.088495,-0.563973,0.254571,-0.601199,0.120078,0.208190,-0.205201,-0.072520,0.099574,-0.117548,0.892760,-0.761438,-0.144770,0.396988,0.026818,-0.203848,0.516805,0.275455,0.321630,-0.165054,-0.182773,-0.301363,-0.318975,0.107117,0.009963,0.545453,-0.002037,-0.431640,-0.574841,0.357581', '1826173', '4202326', '4127270', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1765014', '莱姆酒日记', '剧情', '保罗·坎普（约翰尼·德普 Johnny Depp 饰）是个失意的纽约作家，他来到波多黎各一家不景气的报社当记者，过起醉生梦死的生活。他在旅馆遇见性感美艳的切诺特（艾梅柏·希尔德 Amber Heard 饰），立刻被她吸引。地产大亨桑德森（艾伦·艾克哈特 Aaron Ec khart 饰）雇佣坎普写广告，并为他提供了丰裕的金钱与物质。坎普发现切诺特竟是老板的女人，却还是无法控制地爱上了她。桑德森安排坎普陪伴切诺特，坎普经受住美色的诱惑，拒绝与她一起私奔。他们来到一座岛上考察房产，在酒会上，喝醉的切诺特和当地男子热舞，让桑德森大怒。第二天，桑德森宣布与坎普终止合作，并将切诺特赶出家门。坎普收留了切诺特，并决心写出桑德森房产黑暗交易的内幕，但是出版社拒绝出版。他和朋友在集市斗鸡赚了一笔大钱，当他们拿着钱回来准备自己动手印刷文稿，却发现出版社早已被拍卖，人去楼空。坎普没有放弃自己的追求。回到纽约，他成功揭露了桑德森，成为一名记者，与切诺特幸福地生活在一起。', '约翰尼·德普', '布鲁斯·罗宾逊', 6.2, 15623, 'tt0376136', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1299836529.jpg', 2.2, 17, 55.3, 20.1, 5.4, '0.262553,-0.070556,-0.644298,0.202135,-0.288740,-0.494282,0.736910,0.320709,-0.119061,-0.057890,0.077199,0.801898,-0.185140,0.265536,0.482193,0.255445,-0.348192,-0.468920,0.382951,-0.138998,0.383002,-0.421014,-0.268269,-0.236521,-0.004569,-0.237621,0.420962,-0.024588,-0.255673,0.504073,0.320056,0.086015,0.168535,0.447883,-0.111440,0.143664,0.201375,0.024621,-0.453588,0.357183,-0.245375,0.074820,-0.187148,-0.103588,0.394261,0.198223,0.299823,0.123030,0.146503,-0.000784,0.151846,-0.246416,0.233305,0.140710,0.040319,-0.027576,0.096240,0.113570,-0.577716,-0.056828,0.137102,-0.207319,-0.345630,0.040545,-0.048752,0.153303,-0.456102,0.524601,-0.520963,0.008323,-0.201006,-0.503689,-0.020509,0.183689,0.232275,0.131244,0.102927,0.047754,-0.584879,0.169311,0.446490,-0.070786,-0.020920,0.127083,-0.015926,-0.283613,0.051454,-0.093967,-0.305332,-0.153426,0.379038,0.018562,-0.020635,0.105774,-0.718236,-0.177136,-0.443382,-0.527716,0.258552,-0.617348,-0.105665,-0.947124,-0.267306,0.065712,-0.388452,-0.048151,0.223829,-0.193407,0.246898,-0.484286,0.160545,0.707688,0.489665,-0.281729,0.511463,0.017216,-0.005314,0.171295,-0.151383,0.367371,0.393869,0.436239,0.003770,0.261003,0.144224,-