INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1765127', '植物学家的中国女孩', '剧情', '故事发生在上世纪的80年代。著名的植物学家在一个岛上培育研究植物，他的性格严厉保守，与女儿陈安（李小冉 饰）相依为命。这天，混血女子李明（米兰妮•詹姆帕诺米 Mylène Jampanoï  饰）前来岛上实习，她父母在唐山地震中双双亡故。陈安于李明朝夕相处，二人暗结断背情愫，感情日渐深厚难分。陈安哥哥在西藏当兵，探亲归来，喜欢上了李明，父亲大力撮合婚事。此时陈安与李明已经互许终生，升华为情欲和爱欲交织的感情。为了二人可以相伴终生，李明决定答应这头婚事。然而，哥哥终究发现李明不是处女的秘密，怒不可遏，把李明打伤。李明逃回植物园，这时父亲才觉察到了李明与女儿之间的不寻常关系。一场悲剧正在慢慢上演。©豆瓣', '米兰妮·让帕诺米', '戴思杰', 6.5, 26268, 'tt0425985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578207376.jpg', 3.8, 14.9, 45.2, 26.1, 10, '0.048811,0.068772,-0.806749,0.402927,-0.011880,-0.266674,0.505728,0.062077,-0.642879,-0.364294,-0.136488,0.448197,0.027703,0.225685,0.052291,-0.240178,-0.106622,-0.609279,0.070429,0.011589,-0.102862,-0.457302,-0.008225,-0.200905,-0.325987,-0.181100,0.485511,-0.044472,-0.061478,0.548908,0.350963,0.323452,-0.360984,0.251090,-0.083850,-0.061424,0.033240,0.291392,-0.747561,-0.082017,-0.015248,0.042771,0.100765,-0.315476,0.091209,0.204627,0.436892,-0.044994,-0.172332,-0.293934,0.251178,-0.126112,-0.027821,0.189437,0.427000,0.073359,0.303488,0.204251,-0.265492,-0.394251,-0.039810,-0.174695,0.007581,0.118118,0.243782,-0.009456,-0.542855,0.480423,-0.082848,-0.134392,0.087252,-0.428528,0.084818,0.487231,0.321970,0.421579,-0.078134,0.117310,-0.068747,0.042701,1.021043,0.080062,0.246877,0.370032,-0.168600,-0.372542,-0.074269,-0.143328,-0.357551,0.042509,0.409365,0.006169,-0.171281,0.322393,-0.221105,-0.256755,0.071160,0.396531,0.247409,-0.312225,0.135398,-0.096383,-0.356665,-0.513461,-0.450276,0.103729,0.046490,-0.423053,0.486323,-0.703799,0.331579,0.114374,0.345942,-0.614203,0.524681,0.241043,0.114139,-0.489439,0.240927,0.371479,-0.167747,-0.100025,0.077003,0.171617,-0.058637,0.252592,-0.317229,0.274219', '25721544', '6890343', '1294713', '1306465');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1765848', '天生一对', '剧情', '冰（杨千嬅 饰）是广告公司的客户经理，公司她是女强人，下班后她跟很多女人一样，苦苦寻觅自己的爱情。一天晚上她在酒吧遇到了心理医生V仔（任贤齐 饰），两个人缠绵的时候V仔意外发现了冰的胸部有肿块。经医生诊断证实冰真的患上了乳癌，冰大受打击，惧怕自己因为失去了一边乳房而没有好归宿。自从因为V仔发现自己的病情后，冰就对V仔存在了怨恨，可是V仔也因为她留下了阴影，因此不举。冰差点被朋友骗财，幸好有V仔及时解围，之后二人便互相扶持帮助，情愫暗生。冰同时要为是否切除乳房而烦恼。©豆瓣', '杨千嬅', '罗永昌', 6.1, 15091, 'tt0778129', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486594258.jpg', 2, 13.9, 63.6, 16.5, 4.1, '0.033390,-0.201103,-0.603341,0.186858,0.087974,-0.153546,0.553632,0.384338,-0.677592,-0.039116,-0.007555,0.398726,-0.376584,0.150795,-0.332128,0.051156,-0.148291,-0.795592,0.120427,-0.085001,-0.659528,-0.120693,-0.091042,-0.241415,-0.137318,-0.425348,0.338372,-0.001677,-0.096579,0.256445,0.197864,0.360232,0.184346,0.890036,-0.156074,-0.002058,0.063886,0.279440,-0.014063,0.412469,0.245535,-0.158504,-0.024126,0.105853,-0.024890,0.650362,0.603770,-0.088893,-0.602249,-0.336656,0.326968,-0.494201,0.056231,-0.079245,0.508825,0.025965,0.620550,-0.037211,-0.261894,-0.234639,0.283149,-0.027689,-0.549085,-0.050524,0.121628,0.181130,-0.720447,0.586694,-0.168145,-0.037106,0.114172,-0.181318,0.498972,0.142628,0.225406,0.123276,-0.092320,-0.056382,-0.329131,0.294401,0.759909,0.208802,-0.138826,0.693004,-0.122795,-0.411926,-0.051428,0.314827,-0.186182,0.131147,0.183489,0.287810,-0.640446,-0.080012,-0.322465,-0.302895,-0.461003,0.008282,-0.041276,-0.441136,-0.038674,-0.179698,-0.104165,-0.400814,-0.377779,-0.125979,0.062348,-0.219398,0.556300,-1.016536,0.340549,0.633139,0.418772,-0.715573,0.820853,-0.184370,-0.261398,-0.140655,-0.143493,0.162497,-0.034152,-0.078558,0.546965,0.298291,-0.108307,0.106366,-0.121247,0.282220', '2052978', '1308755', '2124718', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1766086', '太阳照常升起', '剧情', '姜文蛰伏七年之后的又一力作，由四个充满魔幻现实主义风格的小故事组成。1976年，南部一个边远的小山村，李东方（房祖名 饰）的母亲因为一双鞋子疯掉，成为疯妈（周韵 饰），终日疯疯癫癫，一天，李东方无意发现疯妈发疯的真相……1976年，一所大学里，晚上在操场放电影，有五个女人声称被人“摸屁股”，梁老师（黄秋生 饰）阴差阳错成为嫌疑犯，有人开始在暗中帮他洗脱嫌疑……1976年，老唐（姜文 饰）和唐妻（孔镱珊 饰）下放到李东方所在的小山村。老唐天天和村里的孩子们一起上山打猎，逍遥自在，唐妻备受冷落之下，准备寻找自己新的生活……1958年，新疆，两个骑骆驼的女人，唐妻和身怀六甲的疯妈，并肩而行，迎接她们的，是两段截然不同的命运……若干年后的纠葛，从茫茫戈壁上的相遇开始，早已冥冥注定。©豆瓣', '房祖名', '姜文', 8.3, 266928, 'tt0769507', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453675494.jpg', 0.7, 2.1, 16, 42.4, 38.8, '0.104788,-0.063339,-0.516080,0.455410,-0.140255,-0.183643,0.645304,-0.088199,-0.678692,-0.345495,0.004740,0.459989,-0.260116,0.750339,0.284712,-0.135668,-0.225263,-0.701752,-0.129138,-0.156267,-0.505183,-0.248259,-0.066768,-0.218415,-0.306785,0.082543,0.461674,0.023425,-0.055279,0.505749,0.291605,0.183043,-0.337077,0.347097,-0.148076,0.042296,-0.100727,0.383411,-0.129646,0.099485,-0.066584,-0.335411,-0.291554,-0.292945,-0.011557,0.141798,0.658141,-0.037129,0.150828,-0.375869,0.348328,-0.219567,-0.372478,0.124458,0.458139,-0.108235,0.257791,-0.004863,-0.199053,-0.268120,0.077475,-0.397917,-0.006719,-0.073140,0.181267,0.007915,-0.556103,0.166978,0.063465,0.009003,0.142703,-0.570455,0.220869,0.366001,0.370230,0.544444,-0.209644,-0.017459,-0.482543,0.330433,0.726313,0.120384,0.161184,-0.156997,0.269623,-0.322955,-0.083975,0.096537,-0.435942,-0.012116,0.384027,-0.255044,-0.175155,0.240059,-0.679868,-0.066841,0.068884,-0.131200,0.229685,-0.294519,-0.085581,-0.470904,-0.107292,-0.509762,-0.116066,0.431656,0.146750,-0.318219,0.489927,-0.546915,0.529734,-0.034525,0.047146,-0.572667,0.657076,-0.064884,0.217168,-0.324089,0.155036,0.361707,0.149867,0.188071,0.167128,0.510233,-0.510080,0.123394,-0.500473,0.445977', '26687241', '2365260', '2278795', '2122766');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1766789', '乱马OVA：邪恶之鬼', '剧情', '很久以前，有一只恶鬼为害人间。虽然被法术高强的猴子高僧所封印，但是随着岁月的流逝，符咒的威力渐渐失去，加上八宝斋的捣乱，恶鬼重新获得自由。不过这个家伙似乎和传说中的不同，圆滚滚的身材配上白痴的外表，让所有人都感到心底发寒。当然鬼不可貌相，它具有附体的能力，凡是被恶鬼上身的人都有做坏事的冲动。在此期间，早乙女玄马、九能带刀（鈴置洋孝 饰）、响良牙（山寺宏一 饰）接连中招，甚至连一向善良的小霞姐姐（井上喜久子 饰）也卷入其中。面对温柔可亲的小霞姐姐，天道一家陷入无限困扰之中……本片根据高桥留美子同名原著改编，系该动画的OVA版。©豆瓣', '山口胜平', '井内秀治', 8.4, 8142, 'tt0183694', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p608761179.jpg', 0.1, 0.7, 16.6, 41.7, 40.9, '0.076686,0.019826,-0.441161,0.454114,-0.181231,0.065202,0.610444,0.049823,-0.427755,-0.380103,0.129659,0.466053,-0.262422,0.025241,-0.107033,0.054052,0.139883,-0.399445,-0.190610,-0.064817,-0.065848,-0.014719,-0.323387,0.049699,-0.163305,-0.469929,0.599518,0.130206,-0.211066,0.211176,0.144379,0.411577,-0.120382,0.012102,-0.089870,-0.022109,-0.315147,0.070616,0.272503,-0.083238,-0.106154,-0.053355,0.165661,0.142396,-0.225625,0.197329,0.552708,-0.476882,-0.284349,-0.236365,0.427056,-0.049376,-0.247071,0.073388,0.097133,0.044394,0.349143,-0.033681,-0.151378,-0.084565,0.141991,0.012849,-0.860214,0.002218,0.495327,0.088284,-0.105268,0.181670,0.250681,0.017375,0.030867,-0.133267,-0.039358,-0.229200,0.556462,0.281361,-0.127340,-0.010092,-0.386635,-0.072255,0.417852,-0.084159,-0.480265,0.173766,-0.253162,-0.250219,-0.263850,-0.473223,-0.113126,0.230398,0.024875,0.151220,-0.198822,0.277211,-0.574947,0.012096,-0.017253,0.173774,-0.249568,-0.245604,-0.156840,-0.342423,-0.124040,-0.569153,-0.169090,-0.079055,0.374902,-0.236942,0.851511,-0.575545,0.251841,0.312063,0.027580,-0.165470,0.442683,-0.117885,-0.302440,-0.184316,-0.271126,0.282657,0.274253,0.139545,0.156443,0.331254,-0.008053,-0.123407,-0.335524,0.461560', '24284209', '27602116', '26667010', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1766827', '我曾侍候过英国国王', '剧情', '坐监多年的扬•迪特（奥德里奇•凯瑟饰）大赦获释，他被“放逐”到捷克北部边境森林里修一条看上去永远修不完的道路。回想年轻时候，迪特感慨万千，那时的自己（伊万•巴尼弗饰）只是个年轻的饭店服务生，却立志要成为百万富豪。小个子的他精通服务之道，同时不忘追逐金钱和女人。他先后到过生活奢靡的天堂艳楼，布拉格最气派豪华的巴黎饭店。在那里，饭店领班告诉迪特，他之所以精通各项待客之道，是因为曾侍候过英国国王。第二次世界大战前后的捷克情势变化莫测，迪特遇见了同是小个子的德国姑娘丽莎（朱丽娅•耶特斯饰）并遇到许多困难，但他依然坚定不移地朝着立下的目标努力……©豆瓣', '伊万·博尔内夫', '伊日·门泽尔', 8.3, 14020, 'tt0284363', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1538683478.jpg', 0.2, 1.1, 14, 51.7, 33, '0.356739,0.142926,-0.689902,0.594801,-0.111583,-0.450668,0.543318,-0.062523,-0.448232,-0.133862,0.278616,0.795226,0.033211,0.037988,0.276388,0.159823,-0.115467,-0.434201,0.075977,-0.151507,-0.108514,-0.437529,-0.346688,-0.171298,-0.309084,-0.401819,0.154098,-0.089773,0.067865,0.318294,0.153226,0.200682,0.066430,0.320752,-0.333588,-0.074896,0.335914,-0.094137,-0.282444,0.047551,-0.154949,-0.151847,-0.245312,0.143830,0.201475,0.238786,0.213500,-0.048545,-0.044753,-0.035078,0.235941,-0.076958,0.027689,-0.003221,0.452213,-0.159670,0.029157,0.203007,0.081681,-0.034311,-0.176289,-0.317025,-0.510538,-0.040047,0.121380,0.132797,-0.563935,0.324408,-0.149899,-0.070543,-0.014013,-0.537343,-0.035893,0.131556,0.160042,0.276718,0.055901,-0.097931,-0.708297,0.165768,0.667058,0.059813,-0.422004,0.275604,-0.123291,-0.397580,0.097738,-0.139985,-0.644353,0.127339,0.126507,-0.273579,-0.013051,0.219158,-0.484177,0.096392,-0.494888,-0.196038,0.041153,-0.012682,-0.194376,-0.533854,0.067812,-0.713805,-0.258965,0.048741,-0.075095,-0.058863,0.471619,-0.735339,0.125070,0.649228,0.333529,-0.383311,0.709446,-0.038187,0.115486,-0.062390,-0.229617,0.633295,0.081231,0.089466,-0.160750,0.343237,0.011412,-0.239179,-0.227319,0.609228', '3055049', '1292720', '1460341', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1767042', '潘神的迷宫', '剧情', '12岁女孩子奥菲丽娅（伊万娜•巴克尔洛 饰）有一个凶暴的法西斯军官继父维达（塞吉•洛佩兹 饰），维达的任务就是镇压反抗者，研究各种刑具来折磨残害被抓来的异见人士，奥菲丽娅每天都目睹让人不愉快的事件。眼看着冷酷的继父和其党羽每日作恶还以此为乐，母亲又身怀六甲患病在床，被孤独感和目睹暴行的痛苦困扰的奥菲丽娅开始沉浸在自己的幻想中聊以自慰。一天，奥菲丽娅遇到了迷宫的守护者，潘神（道格•琼斯 饰）。潘神告诉她，她其实是奇幻王国失踪的公主，要想恢复身份，必须通过三个危险的考验。©豆瓣', '伊万娜·巴克罗', '吉尔莫·德尔·托罗', 7.9, 218170, 'tt0457430', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p924581966.jpg', 0.5, 2.7, 24.3, 47.3, 25.1, '0.097637,-0.255053,-0.401150,0.558877,-0.119500,-0.011786,0.943958,-0.034744,-0.464995,-0.254349,0.255759,0.515524,-0.151349,0.321665,0.369059,0.163292,-0.360471,-0.644426,-0.115676,0.038182,-0.315307,-0.460510,-0.108862,-0.521958,0.029681,-0.577784,0.270717,0.176460,-0.104883,0.290283,0.366441,0.478043,-0.153919,0.535368,-0.222719,-0.146359,0.129317,-0.249508,-0.048382,0.035870,0.077740,-0.449333,-0.087981,0.351008,0.027979,0.295984,0.653274,-0.468805,0.050246,-0.013814,0.400022,-0.503040,0.027842,0.263659,0.324497,-0.131928,0.025831,0.245142,-0.170848,0.066970,0.153042,-0.175593,-0.884872,-0.036167,0.295948,0.070420,-0.658401,0.475488,-0.120494,0.191434,0.029875,0.000971,0.118091,0.300067,0.080281,0.412572,0.010235,-0.098742,-0.601710,0.147542,0.495778,-0.258289,-0.107929,0.097297,-0.231969,-0.364272,0.013453,-0.470843,-0.475059,-0.076428,0.338309,-0.277586,-0.357863,0.341562,-0.529045,-0.153558,-0.429972,-0.226383,-0.159639,-0.413090,-0.283437,-0.442152,-0.057864,-0.218042,-0.275778,0.193988,0.124336,-0.361782,0.588919,-0.706826,0.395102,0.578993,0.211819,-0.637671,0.647303,0.171209,-0.067202,-0.154649,-0.091661,0.462583,0.113321,0.111683,0.132198,0.347012,0.227446,0.082238,-0.362034,0.448184', '3005387', '3785918', '3119246', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1767732', '水浒笑传', '喜剧', '痞子武松（许冠杰饰）前往阳谷县寻找家兄武大（吴孟达饰），到景阳冈上骗吃骗喝，却借着酒意误打死一只老虎。阳谷县人将武松簇拥回县，县太爷将他封为都头。另一边，潘金莲（毛舜筠饰）与武大两夫妻正商量着如何骗钱，将目标锁定有钱却白痴的西门大官人。他们二人找到王婆，开始设计一个精细的行骗计划，而此时武松上门寻找家兄，二人害怕武松搅乱计划，所以百般隐瞒......©豆瓣', '许冠杰', '高志森', 6.4, 9197, 'tt0108127', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2318529306.jpg', 2.4, 13, 55.3, 21.7, 7.5, '0.465775,0.053662,-0.515457,0.258061,-0.063034,-0.222184,0.402276,0.227929,-0.372069,-0.143308,0.484106,0.245329,-0.237968,0.026730,0.146534,0.092331,-0.157447,-0.648836,0.022624,0.092043,0.261520,-0.350563,-0.159480,-0.012378,-0.162895,0.302080,0.161466,-0.123381,-0.123157,0.563250,0.368158,0.014873,-0.442283,0.356935,-0.070263,0.144523,-0.154955,-0.081048,-0.160271,0.187973,-0.105145,-0.202037,-0.250741,-0.181030,-0.015994,0.451991,0.610114,-0.313954,-0.120811,-0.176585,-0.031993,-0.505018,-0.014633,0.359651,0.052628,-0.021881,0.036505,0.015769,0.055648,0.044588,0.083741,0.061329,-0.220649,0.297362,0.178647,-0.034154,-0.585980,0.067295,-0.147277,-0.051989,-0.109275,-0.626689,0.175920,0.110860,0.356610,0.152392,-0.075574,0.055656,-0.605616,0.230719,0.535000,-0.078044,0.430880,-0.082035,0.501349,0.036702,0.318016,-0.031891,-0.127929,-0.399527,0.603137,0.076334,-0.146123,-0.226226,-0.331349,-0.224634,-0.257092,0.378129,-0.021048,-0.286463,0.194149,-0.550262,-0.069488,-0.210814,-0.157302,-0.054740,0.370962,-0.321840,0.207097,-0.201181,-0.079532,0.372465,0.150624,-0.465265,0.313167,-0.019209,0.156138,-0.288985,-0.212099,-0.379182,0.334525,0.214973,0.123964,0.280666,-0.403744,-0.064363,-0.219660,0.284767', '4032539', '1451563', '1294417', '25837175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1769507', '沉静如海', '剧情', '法国人André（迈克尔·加拉布鲁 Michel Galabru 饰）和她的孙女Jeanne（朱莉·德拉姆 Julie Delarme 饰）原本平静的生活因二战的到来和德军对法国的侵占被打破，更让他们无法接受的是，他们家里的一个房间竟被征用作为一个德国军官Werner（托马斯·儒阿特 Thomas Jouannet 饰）的起居室。他们对这个敌方的军官一直保持着一种冷漠，尤其是Jeanne，她从来不和军官说话，即使是在他向他们问好的时候。让人意想不到的是，这个年轻的军官在多日的相处后，竟和他们谈论起自己的生活、音乐和法国文化，透露出他纳粹军服下隐秘的内心世界。同时，Jeanne也在积极的参与法国地下反抗德军的组织活动。渐渐地，两个来自敌对双方的年轻男女间产生了一种奇异的情感。这种情感在他们离别的时候，化成了Jeanne口中的一句话，她和他说的第一句话，也是唯一的一句话......本片根据法国作家Vercors写于1941的同名小说改编。', '朱莉·德拉姆', '皮埃尔·布特龙', 9.2, 83447, 'tt0430594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p541622159.jpg', 0.1, 0.3, 5.3, 29.7, 64.6, '0.681736,0.013560,-0.986252,0.971199,-0.247724,-0.181738,1.156626,-0.116682,-0.649463,-0.158473,0.121162,1.068517,-0.306234,0.187483,0.144813,0.067220,-0.327716,-0.769595,-0.251580,0.037852,-0.209907,-0.541225,-0.271150,-0.153253,-0.243108,-0.240827,0.531342,0.049934,-0.457298,0.446067,0.176841,0.390583,0.288139,0.688852,-0.145212,-0.005979,0.057829,-0.014779,-0.071509,-0.030398,0.148949,-0.266174,-0.373711,0.369406,-0.228331,0.510497,0.639137,-0.294283,-0.079088,0.210838,0.274597,-0.340222,0.037526,0.176151,0.249179,-0.034282,0.208390,0.287195,-0.080969,0.104399,-0.222728,0.260984,-0.866653,-0.029431,-0.137583,0.335382,-0.565650,0.664015,-0.093906,-0.098358,0.202126,-0.401265,0.259527,0.449578,0.076443,0.503879,-0.394747,-0.071616,-0.710670,0.194522,0.777199,0.017946,-0.602518,0.198191,-0.527449,-0.555968,-0.081067,-0.069967,-0.547301,-0.271906,0.191559,-0.111302,-0.069226,0.072453,-0.775104,0.100175,-0.037106,-0.425755,-0.018992,-0.606578,-0.049013,-0.702584,-0.231242,-0.874779,-0.516917,0.175286,0.207740,0.079934,1.030418,-0.880472,0.069314,0.489695,0.406063,-0.393405,0.674372,0.376581,0.109010,-0.078073,-0.215204,0.261501,-0.008850,0.198182,0.250599,0.748089,0.130083,0.1