INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1771061', '不再沉默', '剧情', '一个派对过后，少女Melinda（克里斯汀·斯图尔特 Kristen Stewart 饰）开始变得沉默寡言。新学期开始，她认识了新同学Heather（Allison Siko 饰），尽管她并不喜欢Heather，但她却只能和Heather一起。她原先的那帮好朋友们都认为她在派对上的报警是对他们的一种背叛而疏远她，尤其是她原来最好的朋友Rachel（Hallee Hirsh 饰）也不再和她有来往，整天和她的新男友Andy（Eric Lively 饰)混在一起。语文课上，老师用她蹩脚的英文念她们的名字；生物课上，她和Dave（迈克尔·安格拉诺 Michael Angarano 饰）分在一组；美术课上，老师让她好好学画一棵树；历史课上，老师是个专横的民族主义者......她的世界因为回忆和现实而变得压抑不堪，她开始尝试画一些奇怪的东西。她终于下定决心把事情的真相说出来，到底在派对上她和Andy之间发生了什么事，到底她为什么要报警......她不再沉默。本片改编自美国作家Laurie Halse Anderson的同名获奖小说。', '克里斯汀·斯图尔特', '杰西卡·沙泽尔', 7.8, 21335, 'tt0378793', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2569329278.jpg', 0.3, 2.2, 27.8, 48, 21.6, '0.742613,-0.024783,-0.615393,0.701075,-0.181180,-0.207244,0.802192,-0.151525,-0.440596,-0.249928,-0.090527,0.813306,-0.186328,0.398808,-0.072517,0.295788,-0.555977,-0.813110,0.303837,-0.241608,-0.344658,-0.589586,-0.040936,-0.163075,-0.015678,0.044912,0.391287,-0.181413,-0.122664,0.333762,0.447183,0.059408,0.288637,0.517508,-0.056079,-0.066949,-0.132381,0.197909,0.098136,-0.144637,0.307584,-0.329994,-0.236330,0.323620,0.268807,0.291006,0.522933,-0.014943,-0.092559,0.229730,0.177741,-0.230560,0.142992,0.224495,0.077817,0.131371,0.298292,0.252650,-0.070694,-0.050667,-0.224089,0.040980,-0.471796,0.132295,0.197603,0.249493,-0.528276,0.551330,-0.085425,0.025098,0.021242,-0.486289,0.173427,0.182963,0.337678,0.173923,-0.092841,-0.248508,-0.469213,0.240444,0.781508,0.148151,-0.043823,0.367056,-0.258851,-0.267351,-0.253239,-0.131385,-0.590783,0.022050,-0.079058,-0.239573,-0.243087,0.042378,-0.655917,-0.049470,0.130301,-0.064057,-0.183623,-0.501909,0.139378,-0.205146,-0.108848,-0.539333,-0.457972,-0.160871,0.053287,-0.450604,0.844993,-1.041980,0.255853,0.542473,0.342433,-0.512388,0.567895,0.376483,-0.176524,-0.395733,-0.143848,0.007093,-0