INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1772560', '和平战士', '剧情', '在比赛中，丹•米尔曼（斯科特•麦克洛维茨 Scott Mechlowicz 饰）完成了一组高难度的吊环动作，却在落地时把左腿摔得粉碎。他猛然惊醒，原来是南柯一梦。凌晨三点，受惊的米尔曼出去散心，意外在加油站结识了一位身怀绝技的老者苏格拉底（尼克•诺特 Nick Nolte 饰），两人成了忘年交。米尔曼外形俊朗，成绩优异，所以总有女孩子围绕身边，然而因为跟好友的女友上床而惹得兄弟反目。另外，他一直希望完成一个高难度动作，却遭到教练的强烈反对，因为后者怕他受伤。由于困扰的时候，他就会来加油站跟苏格拉底交谈。然而一场突如其来的车祸使得米尔曼丧失一切，双脚骨头碎了近100处，他的体操生涯遭到毁灭性打击。病床上的米尔曼这时想起了苏格拉底。在苏格拉底的指引下，米尔曼通过集中全部精神创造了奇迹……©豆瓣', '斯科特·麦克洛维茨', '维克多·萨尔瓦', 8.4, 10943, 'tt0438315', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p536934426.jpg', 0.6, 2.6, 17.1, 36.9, 42.9, '0.311256,0.158641,-0.877456,0.230161,0.158145,-0.461839,0.557039,0.067442,-0.285183,-0.233214,0.374093,0.765376,-0.622249,-0.133264,0.447550,0.156492,-0.157757,-0.871746,-0.019773,0.048177,-0.421355,-0.408968,-0.108955,-0.153645,-0.035753,-0.605861,0.141996,-0.078351,-0.215518,0.594082,0.130551,0.351514,0.296495,0.476185,0.131682,0.096333,0.259018,-0.301937,0.003863,0.128742,0.216982,-0.309722,-0.042629,0.179910,0.132909,0.433230,0.641774,-0.247749,-0.106542,-0.000891,0.266403,-0.277573,0.152784,0.064357,0.516268,0.009524,0.186321,0.087352,-0.118570,0.015579,0.379797,-0.097230,-0.469447,0.198919,-0.039952,0.227234,-0.515533,0.582081,-0.296397,0.131496,-0.028306,-0.175068,0.467332,0.335043,0.177802,0.202326,-0.201542,-0.204964,-0.264799,-0.149642,0.641199,0.036871,-0.498698,0.214465,-0.460001,-0.200880,-0.047553,-0.198269,-0.000666,-0.025527,0.420026,0.042383,-0.132016,0.266176,-0.254977,-0.354365,-0.469285,0.046128,-0.508233,-0.423780,-0.378932,-0.492960,0.224813,0.052035,-0.274162,0.190192,-0.190143,-0.264502,0.574528,-0.549528,0.225153,0.570464,0.229012,0.333790,0.490899,-0.321220,0.245110,-0.185834,-0.004549,0.182975,0.013023,0.059287,0.378384,0.417366,-0.179185,-0.081909,-0.590611,0.536237', '30162520', '4832825', '3155839', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1773216', '迷恋荷尔蒙', '剧情', '年轻英俊的美国大兵巴利（特罗伊·加里蒂 Troy Garity 饰）在脱衣舞俱乐部遇到美艳舞者，同伴怂恿巴利搭讪看是男是女。巴利很绅士的和对方攀谈，同时没有把战友的下流赌注讲出来，从而赢得这位叫亚当斯（李·佩斯 Lee Pace 饰）的变性舞者好感。一见倾心的两人开始交往，他们感到很幸福。巴利的室友费希尔（肖恩·海托西 Shawn Hatosy 饰）十分嫉妒，不断挑衅生事，并最终唆使新兵用球棒残忍结束了巴利22岁的生命。7月4日是美国国庆日，亚当斯正在庆典晚会上大放异彩，而在异地的寓所巴利已倒在血泊中。当摘得桂冠的亚当斯得知巴利的噩耗后悲痛让他甚至无法站立。他弯下腰蜷缩成一团，绝望的哭泣，仿佛身体每一处留下巴利痕迹的地方都渗透出被切割凌迟的苦痛......本片根据真人真事改编，讲述一位美国士兵因爱上变性舞者而惨死在战友乱棒下的震撼悲剧。由获得过奥斯卡的弗兰克·皮尔森执导，入围当年金球奖最佳迷你剧集奖，艾美奖最佳导演奖，以及全美独立精神奖最佳男主/男配奖等。', '特洛伊·格雷提', '弗兰克·皮尔森', 8.6, 30228, 'tt0324013', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195120366.jpg', 0.2, 0.8, 11.6, 44.9, 42.5, '-0.077492,-0.328180,-0.521745,0.377385,-0.083832,-0.362740,0.780805,-0.020954,-0.320684,0.168829,0.408687,0.691170,-0.247191,0.253453,0.405938,-0.152393,-0.407288,-0.757794,-0.327979,-0.078999,-0.214431,-0.283746,-0.298589,-0.013812,-0.230500,-0.539664,0.521087,-0.323742,0.021414,0.595879,0.607946,0.184603,0.094706,0.119716,-0.026187,0.009000,0.261186,-0.019441,-0.397976,0.298917,-0.076104,-0.138365,-0.364886,0.141046,-0.025582,0.279069,0.674402,-0.286457,0.219538,-0.136263,0.511988,-0.341332,0.073767,0.272106,0.248538,-0.057706,0.292783,-0.046872,0.019161,-0.223341,0.274055,0.080490,-0.639468,0.322180,0.324889,0.357377,-0.398088,0.351108,-0.241146,0.221912,0.222789,-0.161376,0.140877,0.082995,0.325616,0.131095,-0.160029,0.017446,-0.182493,0.498371,0.362233,0.011834,-0.611234,-0.037805,-0.153870,-0.413728,0.077983,-0.062074,-0.290209,-0.101124,0.397633,0.046323,0.189778,0.250424,-0.332115,-0.046518,-0.087771,-0.347445,-0.187930,-0.327465,-0.211985,-0.780209,-0.287668,-0.013663,-0.064787,-0.136070,0.214586,-0.151302,0.528609,-0.611181,0.230031,0.470119,0.167847,0.044358,0.470515,0.198553,-0.057687,-0.017929,-0.323829,0.374954,-0.010939,-0.105255,-0.064658,0.455348,-0.188544,-0.110954,-0.371997,0.414697', '1316693', '3811356', '1299663', '1291554');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1773217', '鬼影', '悬疑', '年轻的自由摄影师Thun（Ananda Everingham）这日携女友Jane（Natthaweeranuch Thongmee）与大学同窗聚会完毕开车归家，途中Jane将一名飘忽而至的女子撞倒在地。Jane欲下车查看女子伤势，被Thun劝阻，两人匆忙逃离肇事现场。Jane开始终日坐立不安，并指责Thun冷血，Thun只叫她放宽心莫多虑。Jane的担心并非多余，一连串怪事紧接将他们找上：Thun所拍的许多照片上多出一个模糊的女影、颈部莫名疼痛起来、那日聚会的同窗先后跳楼死去……两人更在暗室多次突然陷入恐怖氛围中。为了摆脱噩梦，Jane决定展开深入调查，与Thun有关的一个女子的悲惨经历慢慢浮出水面。©豆瓣', '阿南达·爱华灵咸', '班庄·比辛达拿刚', 7.7, 112164, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2170768955.jpg', 0.6, 3.1, 27.8, 46.8, 21.8, '0.549827,0.077672,-0.546665,0.265750,0.067748,-0.313798,1.029575,0.019292,-0.542674,-0.389410,0.124010,0.647477,-0.476661,0.425827,0.377888,-0.182474,-0.199712,-0.727496,-0.122657,-0.031020,-0.348054,-0.290612,0.069289,-0.246936,-0.105069,-0.373926,0.447698,0.181374,-0.183915,0.874110,0.228993,0.210365,-0.529197,0.539212,-0.123290,-0.154504,-0.221047,0.348888,-0.284669,-0.077812,0.064296,-0.731505,-0.152223,0.064399,-0.210865,0.384630,0.839467,-0.061808,-0.260273,-0.035736,0.455375,-0.237894,0.064360,0.135733,0.237100,0.388278,0.073886,-0.023235,-0.281814,0.037046,-0.048747,-0.010337,-0.254904,0.217985,0.134942,0.101427,-0.498718,0.207639,-0.099473,0.131091,0.121401,-0.292627,0.165819,0.316228,0.070808,0.323291,-0.248773,0.028532,-0.166211,0.165384,0.897831,0.196597,0.063970,0.231776,0.101871,-0.295213,0.095306,-0.070716,-0.082908,-0.090097,0.356752,0.145410,-0.108841,0.202347,-0.290656,-0.019288,-0.237373,-0.212423,-0.380687,-0.208256,-0.289677,-0.494364,-0.095134,0.202213,-0.247520,0.081563,-0.088442,-0.087438,0.364218,-0.593466,0.331984,0.410105,0.198995,-0.267890,0.268953,-0.056645,0.172945,-0.166253,-0.026775,0.156108,0.281142,0.139068,0.058837,0.215483,-0.649368,0.256151,-0.583339,0.278264', '21348112', '2365260', '1296534', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1773285', '火影忍者剧场版：大激突！幻之地底遗迹', '剧情', '鸣人（竹内顺子 配音）、小樱（中村千绘 配音）和鹿丸三人进入深山寻找走失的雪貂，在回来的路上，他们遭到全副武装的骑士团的袭击。在激烈的对抗中，鸣人和对方的白甲头目特穆金一同跌落悬崖，两人被刚巧路过的商队所救。一路上，两个对手慢慢开始了解，继而得知特穆金要建立一个没有战争和灾难的乌托邦，而鸣人具有的神奇力量正是他们所需要的。与此同时，鹿丸则和小樱目击到一个巨型堡垒，他们发现堡垒四周满是穿着铠甲的武士。鹿丸偷偷潜入侦查，看见一群被禁锢在容器中的小孩，并听到关于吉鲁遗产的谈话。这与特穆金之间究竟有什么样的关联？本片为《火影忍者》第二部剧场版动画。©豆瓣', '竹内顺子', '川崎博嗣', 6.7, 8318, 'tt0791188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2171254694.jpg', 1.5, 9.2, 53.2, 23.5, 12.6, '0.544999,-0.212706,-0.751151,0.627440,0.195467,0.011282,0.938364,-0.159087,-0.220897,-0.587100,0.366431,0.743322,-0.098016,0.108014,0.152772,-0.277952,-0.226189,-0.614415,-0.373511,-0.124911,-0.648826,-0.300413,-0.238950,-0.007567,-0.086161,-0.356149,0.834868,0.099686,-0.340452,0.634018,0.293579,0.371456,-0.760298,0.282272,-0.141804,0.122216,0.132856,-0.048638,-0.090499,0.346927,-0.386785,-0.043441,-0.219487,0.024852,-0.044822,0.288323,0.933555,-0.562123,0.002138,-0.023970,0.135986,-0.159143,0.071510,0.217027,0.577772,0.110921,0.170672,0.044813,-0.042655,0.122231,-0.101599,-0.030970,-0.751686,0.088674,0.061123,0.335983,-0.366693,0.343220,0.337581,-0.264884,0.518068,-0.308280,0.192422,0.485730,0.209637,0.423714,-0.352208,0.100104,-0.534097,-0.242888,0.695643,-0.148761,-0.120057,0.150345,0.120628,-0.348711,-0.210818,0.017636,-0.042753,-0.061299,0.513787,0.111217,-0.227106,0.073862,-0.816670,0.188439,-0.061008,-0.344364,-0.062622,-0.318922,-0.288304,-0.940629,-0.059660,-0.415983,-0.189961,0.519878,-0.136174,-0.246560,0.727731,-0.975009,0.088038,0.535574,0.278629,-0.212773,0.407090,-0.144841,0.119896,-0.164370,-0.144461,0.113916,0.395471,0.324399,0.255347,0.439443,-0.078498,-0.091784,-0.527544,0.055005', '2369613', '20274039', '25774050', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1773614', '多罗罗', '动作', '日本室町时代中叶，当权的幕府威信锐减。野心勃勃的醍醐景光（中井贵一饰），为了成就霸业，而将尚未出生的儿子百鬼丸献祭给48个魔神，他和妖怪定下约定，取走了包括眼、耳、口、鼻等在内的48个器官。一出生就缺少器官部位的百鬼丸，被抛入河中，后来为医生养父（原田芳雄饰）所救，替他制作了义眼、义肢等补足了身上缺失，并命名为百鬼丸（妻夫木聪饰），抚养他长大。为了摆脱自己被诅咒的命运，夺回身体的每一个部分，百鬼丸向占有自己器官的48个魔神宣战，离家踏上征战之旅。在寻找魔神的旅途上，百鬼丸遇到了自称“侠盗”的多罗罗（柴崎幸饰），为了得到百鬼丸手中的宝剑，多罗罗跟随他一起踏上旅程。©豆瓣', '妻夫木聪', '盐田明彦', 6.8, 11418, 'tt0780503', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p658345118.jpg', 1.7, 9.1, 48.7, 30.8, 9.8, '0.070803,0.222030,-0.454857,0.512556,-0.039453,-0.656501,0.639133,0.066619,-0.201127,-0.438099,0.012299,0.707116,-0.065401,0.005660,0.252420,0.077117,0.075017,-0.717518,-0.271533,-0.033834,-0.419580,-0.206869,-0.115583,0.078749,-0.252706,-0.560408,0.819729,0.113588,-0.195622,0.196313,0.248097,0.356380,0.138339,0.070954,-0.368292,-0.031283,-0.402430,-0.150653,-0.069452,0.487927,-0.185235,-0.301778,0.228771,0.170192,-0.204264,0.298485,0.771175,-0.303724,0.188733,-0.784092,0.275201,-0.305500,-0.030380,0.174254,0.318929,0.336066,0.100611,0.221720,-0.301667,0.053685,0.269286,-0.291002,-0.953080,-0.439248,0.151049,0.023340,-0.693233,0.222509,0.000916,0.098866,0.104789,-0.483146,0.275856,0.553270,0.273389,0.474688,-0.398932,0.168092,-0.498637,0.000969,0.484144,-0.432151,-0.034879,0.055178,0.017737,-0.486818,0.126914,-0.209907,-0.178001,-0.203052,0.367176,0.258478,0.028512,0.365093,-0.482701,-0.106573,-0.123150,-0.264693,0.351990,-0.358513,0.027097,-0.263971,-0.117531,-0.094715,0.001657,0.069669,0.219919,-0.271173,0.680711,-0.492441,0.344468,0.551295,0.315361,-0.570938,0.662322,0.157949,0.315564,-0.390401,0.120751,0.367913,0.428561,0.460541,0.062588,0.087322,-0.119143,-0.006527,-0.584095,0.359267', '26678784', '25774050', '30279170', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1774132', '芭比之天鹅湖', '动画', '在充满了浪漫和梦幻的童话世界中，奥黛特（Kelly Sheridan 配音）只是一个平凡的女孩，但幸运的是，她拥有一颗像金子一样善良闪光的美丽心灵，希望这能为她带来好运。一次偶然中，奥黛特来到了一片幽深的森林之中，此时的奥黛特并不知道，这是一座遭到了诅咒的森林。原来，为了将森林据为己有，女王的表哥不惜使用邪恶魔法将精灵们全部变成了动物，而误打误撞走入森林的奥黛特成为了唯一能够接触这诅咒的那个人。不幸的是，奥黛特还没来得及做什么呢，女王的表哥便施咒将她变成了一只天鹅，这让故事开始变得精彩起来。深陷陷阱的奥黛特该如何自救，又该如何拯救森林里的生灵呢？©豆瓣', '凯莉·谢里丹', '欧文·赫利', 8.4, 13477, 'tt0383206', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2155078375.jpg', 0.2, 0.7, 15.8, 43.8, 39.5, '0.287597,0.352296,-0.539367,0.774146,-0.290821,-0.083161,0.986439,-0.236143,-0.298714,0.004679,0.158060,0.872296,-0.145917,0.104966,-0.035099,0.280014,-0.127683,-0.280663,-0.224866,-0.213243,-0.319107,-0.266515,-0.562500,-0.020727,0.173755,-0.517210,0.635510,0.467296,-0.180272,0.113795,0.247396,0.291902,-0.061221,0.291587,-0.332299,0.038248,0.018354,0.267676,-0.056268,0.355275,-0.152747,-0.029916,-0.024135,0.436253,-0.316332,0.087599,0.821278,-0.574034,-0.141116,-0.308393,0.587623,-0.322711,-0.007707,0.311261,0.044492,-0.161870,0.166590,-0.229212,-0.128986,0.079172,0.253577,-0.322071,-1.057545,-0.037894,0.027149,0.142178,-0.432830,-0.044650,0.301052,-0.291862,0.310832,-0.197087,0.347777,0.074751,0.523921,0.474871,-0.268141,-0.061262,-0.635946,0.161581,0.889070,-0.262476,-0.439828,0.622765,-0.314893,-0.660002,0.163834,-0.226665,-0.388376,0.005186,0.323502,0.139261,-0.341364,0.248728,-0.779127,0.124160,-0.388015,-0.217762,-0.140833,-0.661846,-0.545504,-0.016498,-0.054292,-0.198983,-0.274549,0.149282,-0.085168,-0.324898,0.792366,-0.933371,0.500442,0.535709,0.188395,-0.293358,0.621504,0.113612,-0.054910,0.079745,-0.129955,0.302530,0.117001,0.391647,0.260524,0.304164,0.025982,-0.045490,-0.554535,0.536990', '2053515', '26667010', '35360296', '1308784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1774223', '异度见鬼', '剧情', '家住洛杉矶的希妮·维尔斯（杰西卡·阿尔芭 Jessica Alba 饰）多才多艺，美丽聪慧，但是上天并未对她过多垂青。童年时发生的一场事故，导致希妮双目失明，从此只能生活在黑暗的世界里。在姐姐海伦（帕克·波西 Parker Posey 饰）的执意劝说下，希妮答应做角膜移植手术，她的世界重见光明。然而好景不长，在慢慢习惯了多彩世界后，希妮经常能够看到一些奇怪诡异的景象，而这些似乎又与死亡紧密联系在一起。在主治医师保罗·福克纳（亚历桑德罗·尼沃拉 Alessandro Nivola 饰）的帮助下，希妮开始踏上一段寻找真相的奇异旅程……本片翻拍自港版恐怖片《见鬼》，并荣获2008年青年选择奖最佳女主角奖（Jessica Alba）。©豆瓣', '杰西卡·阿尔芭', '大卫·莫罗', 6.3, 6381, 'tt0406759', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p457126857.jpg', 1.6, 12.6, 60.7, 20.7, 4.4, '-0.004392,0.171095,-0.611782,0.366325,0.072070,-0.318337,0.763801,-0.031740,-0.372437,-0.109011,0.207470,0.822455,-0.435796,0.127772,0.331037,0.022244,-0.465817,-0.520590,0.274253,-0.223710,-0.209005,-0.528203,-0.350697,-0.082300,-0.087442,-0.694581,0.511456,0.122831,0.130687,0.342622,0.347442,0.259229,-0.363829,0.365001,-0.094647,-0.011890,0.111547,0.204913,-0.425916,0.267346,0.114498,-0.204039,-0.420743,0.100062,0.171510,-0.107227,0.646768,-0.478384,-0.229413,-0.082084,0.405465,0.104497,0.092207,0.009973,0.182100,-0.086390,0.177001,0.263670,-0.097225,0.105782,0.074197,-0.127065,-0.444617,0.233742,0.074121,0.304733,-0.371646,0.127916,0.135936,-0.099700,0.106628,-0.187511,0.148932,0.236529,0.594355,0.209909,-0.043882,0.130123,-0.121529,0.178732,0.520457,0.140265,-0.377534,0.702260,-0.316107,-0.408532,-0.095168,-0.028219,-0.616276,0.221177,0.272439,0.190368,-0.171339,0.371967,-0.420835,0.104911,-0.305640,-0.245916,-0.184907,-0.374528,0.050887,-0.466976,-0.077526,-0.244710,-0.326317,0.106282,0.012698,-0.369300,0.579910,-0.732640,0.733057,0.467161,0.095206,-0.229798,0.458853,0.009880,0.165161,-0.166486,-0.075844,0.760010,-0.156550,0.033206,-0.126528,0.299573,-0.004607,0.049935,-0.580818,0.623972', '1309172', '1291835', '6827727', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1775450', '赌侠之人定胜天', '喜剧', '罗姓富豪笃信命理之说，为保财运使正室与女仆分别怀孕，日后两名儿子同时出生，高姓大师判定两子为旺财星跟灾星转世……一晃多年，香港街头又多了一名潦倒青年罗四两（张家辉 饰），四两封赌必胜，但却会给亲人带来灾运，自从三岁时克死生父，便由三叔抚养成人，身边只有青梅竹马的好友阿花（杨恭如 饰）不时照顾搭救。而四两同父异母的兄弟司徒定一（杜德伟 饰）却在高师傅维护之下财运亨通，更兼赌术超人轻松羞辱赌王李大胜。定一为保持好运将四两控制在手中二十余年，直至四两被李大胜关入赌术研究中心。四两在中心结识一“外星遗孤”（李灿森 饰）并终于发现自己其实一直生活在假象之中。面临人生大难的定一为转运设计陷害四两，兄弟之战在所难免……©豆瓣', '张家辉', '郑伟文', 5.6, 4537, 'tt0441232', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2381505493.jpg', 5.4, 24.8, 55.9, 9.6, 4.3, '-0.503444,0.005837,-0.461466,0.481131,-0.074081,-0.358937,0.498943,-0.003654,-0.278724,-0.368051,0.290591,0.776022,-0.100006,0.228308,0.286642,-0.230603,0.351331,-0.506475,-0.139152,0.032183,-0.354914,-0.400295,-0.326510,0.010310,-0.270133,-0.158085,0.218552,0.085003,-0.050249,0.398999,0.352458,0.190922,-0.185140,-0.006648,-0.053352,-0.022725,-0.208135,0.338902,-0.516263,0.211751,-0.135954,-0.234792,0.043614,-0.083821,0.192518,0.288206,0.577353,-0.264239,-0.029413,-0.382143,0.167926,0.114096,-0.151166,-0.095986,0.231302,0.041810,0.509497,0.107842,-0.176068,-0.098559,0.032075,-0.266123,-0.426935,0.116253,0.370405,-0.265567,-0.477265,0.127798,-0.031465,-0.127268,-0.164904,-0.053211,0.264373,0.482543,0.249032,0.409660,-0.165286,0.092870,-0.246919,0.257052,0.427698,-0.120520,0.010798,-0.071427,0.130514,-0.184517,0.382840,-0.295512,-0.210706,-0.035228,0.311537,0.099587,0.329797,0.270396,-0.035147,0.038711,-0.389700,0.422215,0.383505,-0.255589,0.288194,-0.124501,0.112175,-0.180785,-0.079787,0.311252,0.449769,-0.494409,0.698566,-0.399479,0.310097,0.024274,0.235166,-0.655400,0.427200,0.332604,0.287673,-0.456804,-0.035265,0.281134,0.218013,-0.046136,0.219136,-0.093364,-0.404794,-0.075980,-0.143586,0.120453', '35048413', '26678784', '26711487', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1776595', '戈雅之魂', '剧情', '1792年，西班牙的最高权力由天主教掌控，为了杜绝法国革命潮流的影响，天主教重新开启宗教裁判所来控制国内骚乱，修道士洛伦佐（哈维尔·巴登 Javier Bardem 饰）是这场运动的领导人。谋略过人的他设法掌控宗教裁判所的最高权利。宫廷画家弗朗西斯科·戈雅（斯特兰·斯卡斯加德 Stellan Skarsgård 饰）是洛伦佐的朋友。因为一个模特伊内斯（娜塔丽·波特曼 Natalie Portman 饰），戈雅受冤被关进宗教裁判所，受到各种严刑拷打，他请求洛伦佐去救伊内斯，谁知伪善的洛伦佐却强奸了伊内斯，并将她打入秘密地牢。二十年后，时局变迁，西班牙被法国军队占领。洛伦佐被西班牙教会驱逐流放，伺机卷土重来。此时的戈雅几乎完全丧失听力，独自囚禁在内心的阴暗中，这个时期却成了他的创作巅峰期。法国废除了西班牙宗教所，伊内斯得以释放，举目无亲的她找到几乎已经神经失常的戈雅，并在他的帮助下找到了在监狱中生下的女儿。欧洲革命风云再起，当西班牙再次陷入战乱中时，洛伦佐被判处死刑。', '哈维尔·巴登', '米洛斯·福尔曼', 7.5, 5698, 'tt0455957', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p794960495.jpg', 0.7, 4.1, 32.7, 45.6, 16.9, '0.147855,0.387374,-0.588224,0.463280,-0.133587,-0.226579,0.482441,0.059292,-0.327539,-0.289406,-0.030671,0.817838,-0.065398,0.175166,0.338828,-0.021590,-0.479202,-0.766182,-0.179114,-0.099684,-0.274425,-0.496455,-0.138884,-0.135380,-0.214543,-0.407938,0.853585,0.189424,-0.563132,0.026841,0.140882,0.516183,0.050620,0.383355,0.034170,0.105604,0.246139,-0.502278,-0.291233,0.241493,-0.144271,-0.400431,-0.036409,0.423716,-0.003426,0.279353,0.278118,-0.552476,0.428201,-0.366867,0.388521,-0.241288,-0.127168,0.318333,0.148932,-0.167015,-0.238269,0.336463,-0.157607,-0.054707,-0.065511,-0.206045,-0.721380,-0.194470,0.192315,-0.036283,-0.450029,0.437123,-0.111238,0.013347,-0.180235,0.086648,0.087105,0.471828,0.174427,0.409425,-0.098626,-0.071470,-0.510332,-0.080872,0.540967,-0.257765,-0.434360,-0.116628,-0.304183,-0.613223,0.100657,-0.351123,-0.222142,-0.268461,0.401803,-0.066015,0.166907,0.506223,-0.421749,-0.204687,-0.451738,-0.268551,-0.033954,-0.286428,0.038044,-0.592558,-0.201496,-0.252568,-0.274565,-0.159936,0.073058,-0.019409,0.385059,-0.656372,0.419784,0.851831,0.241558,-0.345218,0.346880,-0.047060,0.365571,-0.053225,-0.344995,0.735809,0.247550,0.474451,0.030491,0.129518,0.007959,-0.286729,-0.182010,0.550844', '3861846', '1482099', '1303034', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1776964', '何时是读书天', '剧情', '独身的大场美奈子（田中裕子饰）在超市做收银员，早上兼一份送奶工作，晚上在家中品味堆满的书籍。美奈子每天早上都会派牛奶到敏子和中学同级同学高梨槐多（岸部一徳饰）的家。一天，槐多的妻子容子偶然知道了每天早上给他们家送奶的是美奈子，并知道了丈夫过去的事情，她约见了美奈子托付后事。槐多和美奈子是中学时代的恋人，那时候他们经常在书店约会。那时候美奈子的妈妈和槐多的爸爸相好，一次意外双双死去。他们拿因父母的事中断了关系，后来槐多结婚了，美奈子独自一人。30多年过去了，虽然两个人都生活在同一个城市里，但是没有任何往来。容子去世后，槐多与美奈子得以结合，但是……©豆瓣', '田中裕子', '绪方明', 8.3, 8157, 'tt0478706', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1709962051.jpg', 0.3, 1.2, 15.4, 50.6, 32.5, '0.311515,-0.159653,-0.603847,0.204047,-0.258383,-0.602152,0.648714,0.241088,-0.389076,-0.219863,-0.321465,0.573304,-0.194538,0.373020,0.105259,0.485910,-0.472539,-0.690030,0.267050,-0.506123,-0.133761,-0.176461,0.195430,-0.125192,0.122587,-0.325906,0.146004,-0.266233,0.280698,0.747092,0.314979,-0.245189,-0.082727,0.482926,0.025852,0.053064,0.527395,0.444005,-0.341935,0.411544,-0.181448,-0.171323,-0.283216,0.128525,0.557183,0.277697,0.465109,0.197231,-0.627980,-0.089967,0.318727,-0.068849,-0.204091,0.354255,0.641829,-0.120525,0.519275,0.232731,-0.313294,-0.105165,0.164969,0.083954,-0.382533,0.125348,0.498773,-0.123673,-0.301968,0.798256,-0.115629,-0.263289,0.365553,-0.386574,0.448253,0.548513,0.242082,0.163839,0.155187,0.000817,-0.537088,0.417151,0.677221,-0.053059,0.296119,0.397293,-0.132981,-0.254727,-0.122231,-0.053200,-0.339033,0.270602,0.057275,-0.119397,-0.455011,0.150442,-0.600242,0.139412,-0.040321,-0.039388,-0.026298,-0.432448,-0.191810,-0.554839,0.053436,-0.740962,-0.347107,0.379632,0.228920,-0.250145,1.100787,-0.775469,0.325958,0.675092,0.657810,-0.443346,0.624378,0.500963,0.100175,-0.041967,0.218443,-0.167051,-0.046894,0.435961,0.154489,0.624899,-0.090382,0.090703,-0.676439,0.305311', '3091208', '5262027', '25922902', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1777570', '完美陌生人', '悬疑', '年轻干练的萝温娜·普莱斯（哈莉·贝瑞 Halle Berry 饰）是《纽约快报》的一名记者，她秉持正义，疾恶如仇。在一宗参议院同性恋性丑闻的报道被撤下后，萝温娜大发雷霆，一气之下辞去工作。在当晚，萝温娜邂逅多年未见的童年好友葛瑞丝，但一周后却得知葛瑞丝死于非命。葛瑞丝死前曾提到广告业巨头哈利森·希尔（布鲁斯·威利斯 Bruce Willis 饰）的名字，她与这个男人在网上结识，曾有过一段不伦之情。被对方甩掉后，葛瑞丝扬言要将奸情告诉哈利森的老婆。萝温娜判定这是一起谋杀案，她找来报社的搭档——同时也是网络高手——迈尔斯（Giovanni Ribisi 饰）协助调查。一场猫鼠游戏就此展开……©豆瓣', '哈莉·贝瑞', '詹姆斯·弗雷', 6.6, 19853, 'tt0457433', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p772471826.jpg', 1.4, 10, 51.5, 30.5, 6.6, '0.311451,0.113263,-0.497778,0.536567,0.090186,-0.301063,0.406777,-0.073611,-0.515782,-0.304636,0.108470,0.832084,-0.618241,0.315379,0.283187,0.025090,-0.255461,-0.953419,0.021039,-0.265107,-0.171195,-0.541742,-0.111981,-0.153251,0.045680,-0.235477,0.460311,-0.103858,-0.100346,0.417708,0.531717,0.398802,-0.146008,0.403421,-0.139753,0.216520,0.311863,0.117317,-0.349731,0.207525,0.203295,-0.248110,-0.053832,0.113150,0.109421,0.371040,0.399678,-0.136123,-0.156460,-0.077876,0.553805,-0.211718,-0.004326,0.035974,0.707832,0.077349,0.236996,0.435207,-0.109644,-0.209872,0.019142,-0.000404,-0.517876,0.044322,-0.040883,0.273481,-0.464090,0.230999,-0.410407,0.178417,-0.054430,-0.106406,0.226197,0.360772,0.321821,-0.042223,0.259564,0.053614,-0.406089,0.331760,0.723974,0.067073,0.097102,0.168490,-0.036825,-0.286062,0.014258,-0.092968,-0.346568,0.138804,0.328752,-0.313090,-0.132490,0.261240,-0.573704,-0.440105,-0.360420,0.124502,0.147918,-0.308899,-0.174133,-0.626969,-0.192128,-0.065775,-0.276324,-0.024891,0.006661,-0.266215,0.499209,-0.917400,0.216336,0.525370,0.283522,-0.436997,0.710918,0.147125,0.185364,-0.188656,0.003996,0.200344,0.413001,0.096346,0.127318,0.236612,0.145857,-0.282850,-0.472600,0.278697', '30345227', '4301278', '25723905', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1777612', '阳光小美女', '剧情', '7岁的奥利芙，戴眼镜，小肚腩，做一夜成名的美梦，坚信自己有朝一日能当选美国小姐。爸爸，推销成功学课程的讲师，相信“世界上只有两种人，成功者和失败者”，四处贩卖他的“成功九部曲”；哥哥，自闭男，崇拜尼采，为了考上飞行学院发哑誓，九个月没有同家人说话；舅舅，自称是美国最好的普鲁斯特研究学者，同性恋，恋人和同事跑掉、失业，自杀未遂，生活混乱；爷爷（阿兰·阿尔金 饰），被养老院赶出来的老流氓，满嘴脏话、吸毒；妈妈，是这个疯狂家庭唯一正常的人。在家人的支持下，奥利芙参加了“阳光小美女”的选美比赛，一家人踏上了集体寻梦的旅程。奥利芙能否如愿当选？家庭成员们怎样才能度过他们各自的危机？©豆瓣', '阿比盖尔·布雷斯林', '乔纳森·戴顿', 8.3, 253513, 'tt0449059', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p792394752.jpg', 0.2, 1.3, 16, 47.7, 34.8, '-0.024190,-0.247209,-0.265320,0.186351,-0.176438,-0.403543,0.235021,0.044312,-0.477930,-0.073208,0.132690,0.520085,0.020710,0.399067,0.333086,-0.032268,-0.290677,-0.407191,0.201112,-0.073548,-0.195060,-0.536493,0.118526,-0.138627,-0.163612,-0.299820,0.507682,-0.326536,0.089786,0.519859,0.378333,0.125043,0.042833,0.004266,-0.181674,0.013562,0.297803,-0.050678,-0.583576,0.181956,-0.170481,0.364260,-0.234616,-0.218160,0.227132,-0.011716,0.450724,0.056764,0.053603,-0.295915,0.418975,-0.336304,-0.236904,0.230419,0.139031,-0.054269,0.565732,0.257887,0.208576,-0.189536,-0.171618,-0.120684,-0.336827,0.154716,0.343391,0.067563,-0.397066,0.210196,0.069237,-0.003619,0.135623,-0.132288,0.048481,0.375817,0.096105,0.433029,-0.088337,0.253667,-0.535093,0.285896,0.628502,-0.211376,-0.547348,0.055515,0.026535,-0.047776,0.286909,-0.476454,-0.655079,0.313031,0.053788,-0.089372,-0.294170,0.078951,-0.373822,0.089195,-0.156616,-0.222058,0.215800,-0.361945,-0.122671,-0.461524,-0.016210,-0.062744,-0.333262,-0.343370,0.121813,-0.392726,0.894685,-0.799843,0.213667,0.310543,0.381800,-0.390668,0.679277,0.264265,0.217612,-0.341231,-0.231534,0.229871,-0.018958,0.257700,-0.264153,0.280542,0.169786,0.130607,-0.245082,0.207334', '6963575', '3445516', '25922902', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1777619', '恋恋师情', '剧情', '年轻女孩安娜贝尔（Erin Kelly 饰）在相继被两所学校开除后，参议员父亲将她安排到一所天主教寄宿学校继续学业。安娜贝尔很快又拥有了新的校园生活，以及三个性格各异的室友。学校的诗歌老师西蒙娜（戴安娜·加德瑞 Diane Gaidry 饰）则负责管理她们寝室。西蒙娜是一位工作上极其关心学生，私生活也严格遵守宗教和社会道德的女性，然而从不按常规出牌，甚至公然蔑视权威的安娜贝尔着实是最令她头疼的学生。西蒙娜甚至想要放弃，申请将安娜贝尔调到别的寝室去，然而她很快又发现了安娜贝尔身上独特的成熟与感性气息，决定耐心引导。而令人意想不到的是，就在两人朝夕相处的过程中，安娜贝尔竟渐渐爱上了西蒙娜，然而学校森严的天主教义却给这份单纯的情感蒙上荆棘，爱情的囚鸟又能否飞越藩篱……©豆瓣', 'Diane Gaidry', '凯瑟琳·布鲁克斯', 7, 6667, 'tt0323120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2378461365.jpg', 1.3, 9, 45, 29.9, 14.7, '0.750996,0.146747,-0.520023,0.630280,-0.230205,-0.283218,0.461218,0.300611,-0.456074,-0.201171,0.153176,0.657304,-0.042854,0.408614,0.450066,0.125967,-0.609509,-0.748901,-0.068861,-0.361703,-0.371320,-0.666265,0.161008,-0.051780,-0.063739,-0.407226,0.613229,-0.270612,-0.135982,0.444908,0.195930,0.418165,0.022839,0.441059,0.079299,0.073233,0.237544,-0.083780,0.042976,-0.006520,0.221718,-0.084293,-0.167582,0.286246,0.186717,0.321337,0.629251,-0.128747,0.035825,-0.047924,0.593984,0.059790,0.056678,0.239706,0.278107,0.064298,0.189674,0.319408,-0.095700,0.125697,0.083166,-0.082013,-0.578591,0.238975,0.028351,0.079061,-0.419604,0.591722,0.029527,-0.294512,0.191391,-0.327150,-0.276864,0.175566,0.104505,0.534539,-0.149264,-0.041387,-0.253784,-0.054867,0.384522,-0.026419,-0.363461,0.305912,-0.348632,-0.328756,0.013397,-0.220977,-0.483953,-0.098544,0.270053,0.205956,-0.062734,0.330610,-0.614766,-0.027719,-0.295956,-0.169064,0.030268,-0.487947,-0.060027,-0.622724,0.017439,-0.217449,-0.455325,-0.230202,0.185887,-0.090855,0.801810,-1.003157,0.087557,0.540352,0.324239,-0.356114,0.523849,0.015851,0.208720,-0.049004,-0.247055,0.308307,0.142189,0.336353,-0.023246,0.606683,-0.032684,-0.160151,-0.266514,0.602627', '1826173', '4127270', '25922902', '1301172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1778999', '鬼域', '悬疑', '女作家徐寻（李心洁）在处女小说获得空前成功后陷入创作困境。在创作新的定名为《鬼域》的小说时，她期望向读者呈现一个如幻似真的“诡异空间”，无奈反反复复几次构想出来的故事情节都差强人意，而昔日情人的再一次现身，更令她心绪纷乱，一怒之下，她删除了电脑里的《鬼域》初稿，却自此进入自己虚构出来的“鬼域”。一番惊险之旅之后，徐寻在鬼域里遇见一小女孩（曾雅琪），得知鬼域意为“被遗弃的空间”，现实生活中人们所遗弃的一切（包括打掉的胎儿），都能在这里找到。在该女孩的帮助下，徐寻开始了更加恐怖的逃亡旅程，后来两人在鬼域老伯（刘兆铭）的指点下，朝鬼域的出口奔去，小女孩的身世之谜逐渐被揭开。©豆瓣', '李心洁', '彭顺', 6.6, 15000, 'tt0498311', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1297564013.jpg', 2.7, 12.7, 46.1, 28.3, 10.2, '0.132902,0.428744,-0.587776,0.592950,0.141436,-0.230747,0.806862,-0.175538,-0.614680,-0.042132,0.242239,0.700520,-0.418274,0.311647,0.182186,0.031652,-0.496705,-0.478841,-0.254537,-0.341716,-0.379253,-0.214932,-0.381039,-0.133406,0.011563,-0.419731,0.755439,0.492457,-0.363866,0.010222,-0.079389,0.118508,-0.411670,0.468604,-0.267290,0.353032,-0.222704,0.071926,-0.229358,0.367186,0.012194,-0.349679,-0.341931,0.338275,-0.217266,0.106469,1.016910,-0.415009,-0.290053,0.202417,0.775928,-0.097237,-0.277032,-0.082127,0.197671,0.104046,0.332938,0.047925,-0.202414,0.294323,-0.179038,-0.126528,-0.724915,-0.162781,0.073623,0.283549,-0.435829,0.176197,0.088278,0.147987,0.110994,-0.491914,-0.030864,0.234758,0.444435,0.436547,-0.374762,-0.024854,-0.363901,0.373646,0.616933,-0.147319,-0.221451,0.496234,0.092928,-0.475639,-0.166871,0.121667,-0.484370,0.014374,0.554946,0.240525,-0.364272,0.432273,-0.595355,-0.120862,-0.258820,-0.325051,-0.142011,-0.306545,-0.369081,-0.398819,-0.331477,0.315465,-0.097453,-0.143833,-0.012547,-0.296716,0.600564,-0.652773,0.464288,0.574086,-0.129074,-0.288835,0.444053,-0.059822,0.179744,-0.001181,-0.091922,0.369269,0.053270,0.652452,0.073328,0.377661,-0.209898,-0.124979,-0.818355,0.454520', '21619567', '1467779', '30401849', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1779509', '四大天王', '剧情', '吴彦祖、连凯、尹子维、陈子聪成立了一个名叫Alive的乐团，准备在乐坛创出自己的一片天地。然而，他们在访谈中收获了前辈极为尖锐的真知灼见：张学友坦言，技术包装害了唱片业，很多资质差的歌手也在浑水摸鱼；黄贯中表示，踏实创作的人越来越少；谢霆锋直言，唱片公司并不尊重歌手的意见；卢巧音暗讽狗仔队总是无理取闹……总之，很多人都一针见血地指出了乐坛的症结所在。事实也证明alive乐队的成长之路荆棘密布，先是主打歌曲被盗，在网上免费下载，其次是媒体总是挖空心思找他们的绯闻炒作，第三是公司对他们的包装越来越一厢情愿，第四是学舞不精，彩排偷懒，演唱会忘词等糗事，显然这支乐队距离他们的梦想越来越远……吴彦祖凭借此片拿下香港电影金像奖新晋导演奖。©豆瓣', '吴彦祖', '吴彦祖', 7, 5902, 'tt0800362', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504360524.jpg', 1.9, 8.1, 41, 35.7, 13.3, '0.003163,-0.324745,-0.422359,0.697965,0.083228,0.043301,0.255076,0.178832,-0.327015,-0.148556,0.064775,0.652269,-0.331863,-0.008666,0.156419,-0.437591,-0.167183,-0.460632,0.214735,-0.232543,0.253282,-0.332871,-0.244265,-0.188972,-0.457399,-0.098232,0.788836,0.159520,-0.494794,0.213973,0.525760,-0.185793,0.048452,0.325848,-0.009276,0.027000,0.302527,0.225573,-0.199305,0.150303,-0.147210,-0.318863,-0.159412,0.253822,-0.014288,0.414571,0.284743,0.097720,-0.205906,0.232915,0.744324,-0.527993,-0.027864,-0.214620,0.335514,0.038148,0.483000,0.269381,-0.230062,0.129026,-0.487738,-0.103722,-0.923901,0.064204,0.308341,0.087848,-0.478414,0.397195,-0.132812,-0.184377,-0.127139,-0.157408,0.312776,0.120705,0.191929,0.169694,0.071353,0.057360,-0.380552,0.358104,0.381397,0.156471,-0.257759,0.588743,-0.079915,-0.448755,-0.280115,-0.205114,-0.404158,0.004743,0.176095,-0.240821,0.128994,-0.091947,-0.434572,0.021881,0.377143,-0.433982,-0.087877,-0.495710,0.137826,-0.676987,-0.092791,-0.109409,-0.024415,-0.259087,0.242727,-0.455269,0.932043,-0.599099,-0.099171,0.541101,0.254872,-0.538942,0.592181,0.179348,0.029610,-0.172227,-0.407962,-0.106655,-0.111536,-0.069423,-0.040459,0.377274,0.258032,-0.631831,-0.488905,0.377518', '27602116', '25880986', '1468527', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1779632', '真爱无价', '喜剧', '艾琳（奥黛丽·塔图 Audrey Tautou 饰）的梦想是结交很多的富家子弟，让他们成为裙下之臣。五星级酒店就是她的活动场所。这天她来到高级饭店，投入有钱佬雅克的怀抱，却误打误撞认识了酒店服务生让（加德·艾尔马莱 Gad Elmaleh 饰）。艾琳以为让是一个富家子弟，纵情诱惑，二人一夜浪漫后，艾琳才发现让根本不是有钱人，于是愤然离去。然而让已经深深迷恋上了艾琳，他明白自己没有艾琳要求的身家条件。于是，他重新找了一份工作，并无意中成为了富贵寡妇的玩伴。这时，让重遇了艾琳，艾琳对改变后的让有了改观，二人渐渐成为密友，感情也渐渐升温……©豆瓣', '奥黛丽·塔图', '皮埃尔·沙尔瓦多利', 7.1, 29018, 'tt0482088', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p779525183.jpg', 0.6, 5.5, 43.8, 39.3, 10.9, '0.545804,0.266417,-0.597682,0.333136,-0.252792,-0.558642,0.829796,0.241821,-0.726138,-0.041001,0.056038,0.836668,-0.178139,0.150532,0.234518,0.294938,-0.301787,-0.771394,0.030842,-0.324879,-0.175069,-0.452188,-0.108211,-0.036211,-0.200365,-0.300697,0.327434,0.083428,-0.136610,0.552176,0.332138,0.055611,0.247048,0.697311,-0.173066,0.037100,0.353332,0.017960,-0.223988,0.322598,-0.053325,-0.212868,-0.129638,0.274935,-0.039490,0.296061,0.571509,-0.058558,-0.310248,-0.054129,0.142935,-0.084504,-0.168733,-0.028129,0.039295,-0.138112,0.155011,0.009260,-0.329304,-0.064873,0.157218,0.215790,-0.598603,0.200371,0.112231,-0.155191,-0.767378,0.322036,0.023725,-0.458540,0.056445,-0.331200,0.284320,0.242906,0.233946,0.337874,0.076728,0.290738,-0.633859,0.188869,0.669568,0.237898,-0.167393,0.643233,-0.377974,-0.486159,0.225844,-0.113347,-0.471564,-0.107314,0.271945,0.226447,0.020759,0.028362,-0.654444,-0.063743,-0.521560,-0.216164,0.187644,-0.648316,0.035036,-0.375907,-0.503028,-0.224421,-0.319276,-0.213079,-0.036472,-0.330106,0.699726,-1.044957,0.302872,0.615094,0.364619,-0.651058,0.838644,-0.145298,-0.011760,0.027310,0.282715,0.014462,-0.085070,0.206518,0.094333,0.403052,-0.082141,-0.319559,-0.142865,0.630065', '1308755', '1783461', '2124718', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1780122', '风吹麦浪', '剧情', '20世纪二十年代，英国和爱尔兰之间的矛盾不断加深，最终爆发爱尔兰独立战争。原本拥有光明前途的医科大学生达米安（Cillian Murphy 饰）得知战争爆发，毅然投笔从戎。他回到家乡，与弟弟泰迪（Padraic Delaney 饰）、好友丹（Liam Cunningham 饰）一起加入了爱尔兰共和军。这群青年凭借满腔热血以及出色的战术，一次次挫败受雇于英国政府的“黑与棕”民兵部队。他们的反抗迫使英军同意签订条约，然而，这也成为昔日战友分道扬镳的岔路口……本片荣获2006年戛纳电影节金棕榈奖、2006年欧洲电影节最佳摄影奖、2007年爱尔兰电视电影奖观众奖最佳爱尔兰影片和IFTA最佳男配角（Liam Cunningham）及最佳影片奖。©豆瓣', '基里安·墨菲', '肯·洛奇', 8.1, 21037, 'tt0460989', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p789837646.jpg', 0.4, 1.3, 18.3, 52.4, 27.6, '-0.156841,-0.051748,-0.428433,0.759944,0.551793,-0.160058,0.077752,-0.091894,-0.414566,0.001904,0.027617,1.145262,-0.191415,-0.128159,0.404440,-0.473414,-0.430649,-1.014011,-0.061041,-0.099186,0.107017,-0.301166,-0.278992,0.020073,-0.187171,-0.392070,1.207418,0.064117,-0.176867,0.887693,0.537583,0.268566,-0.077033,-0.073885,0.142695,0.045022,0.329878,-0.042997,-0.734268,0.424091,0.082105,-0.113277,-0.262230,-0.168622,0.343899,0.122283,0.739133,-0.110801,0.119973,-0.228962,0.556228,-0.300804,-0.365533,0.132232,0.243846,0.165583,0.312579,0.163608,0.205536,0.024968,0.003921,-0.240871,-0.316006,0.157096,0.124508,-0.267899,-0.437628,0.480363,0.003654,0.271697,0.041800,0.095343,0.034914,0.547756,0.309295,0.085183,-0.283588,0.088334,-0.323473,0.555125,0.558966,-0.167608,-0.508219,-0.041972,-0.168462,-0.734928,-0.175517,-0.512147,-0.194502,0.076202,0.312594,-0.024892,0.089161,0.229628,-0.788550,-0.151971,-0.017760,-0.265336,0.379752,-0.038594,0.078611,-0.822537,-0.308655,-0.139866,-0.081190,0.045791,-0.142051,-0.060257,0.801193,-0.473021,0.250183,0.297646,0.504935,-0.255956,0.785263,0.039324,0.120418,-0.348636,-0.307047,0.449573,-0.327639,-0.152403,0.029073,-0.051486,-0.179354,-0.124299,-0.093798,0.167240', '26365262', '1303390', '26615753', '26990609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1780168', '诡丝', '剧情', '腿有残障的科学家桥本良晴（江口洋介）率领科学小组（大S、陈柏霖等）发明“孟结海绵”，捕获囚禁了一个十三岁男孩的鬼魂，为了查出该男孩的死因，以便自己死后也能变成类似的鬼，桥本良晴找来有超常能力的探员叶起东（张震），令其跟踪被放出去的男孩。最终，叶起东发现男孩是被他的亲生母亲杀害。其后，叶起东从男孩的双眼间看到一条细丝，它似乎连接着某种神秘的力量。科学小组成员因为害怕男孩伤害他们，再次将他隔绝拘禁，不想因此扰动了细丝的另一端，更为恐怖凶残的力量被释放出，小组人员先后一一离奇死亡，叶起东与女友（林嘉欣）也受到该力量的追踪。©豆瓣', '张震', '苏照彬', 7.2, 33607, 'tt0486480', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2203804156.jpg', 1, 5.9, 39.5, 40.5, 13, '0.152210,-0.111578,-0.592067,0.487329,-0.304482,0.046896,0.822967,0.050370,-0.495190,-0.195401,0.187961,0.500895,-0.131418,0.143745,-0.052387,-0.030644,0.017570,-0.656959,-0.021505,-0.185245,-0.413053,-0.390007,-0.199037,-0.127165,0.158719,-0.432406,0.667882,0.036466,-0.202289,0.123894,0.140747,0.483810,-0.347867,0.489833,-0.137406,0.019113,-0.160741,-0.278254,0.122220,0.184126,-0.001148,-0.222405,0.255626,0.278487,-0.543759,0.292539,0.824478,-0.349203,0.039054,-0.215094,0.368845,-0.294222,-0.065082,0.100781,0.546024,0.131144,0.056773,0.043027,0.027776,-0.109286,0.090296,0.025029,-0.700263,-0.142523,0.196202,0.245263,-0.376762,0.090734,0.002552,-0.084043,0.363178,-0.414127,0.055004,0.231382,0.257974,0.407454,-0.246777,0.150700,-0.292911,-0.202614,0.408745,-0.355237,-0.347939,0.118402,-0.466213,-0.634593,-0.115482,-0.323317,-0.205820,0.105939,0.445649,0.445991,-0.384206,0.229274,-0.505268,-0.195477,-0.231451,0.234735,-0.216502,-0.328984,-0.034487,-0.337914,-0.192082,-0.302301,-0.071552,0.223569,0.029224,-0.204547,0.667783,-0.625233,0.164825,0.837269,0.339048,-0.397229,0.325019,-0.153975,-0.015509,-0.209093,-0.151670,0.045542,0.301429,0.584133,0.252376,0.315481,0.057637,-0.098804,-0.231793,-0.018378', '25774050', '3005387', '21619567', '1292829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1780256', '金猴降妖', '剧情', '话说齐天大圣孙悟空、天篷元帅猪八戒以及卷帘大将沙和尚保护唐僧西天取经，一路上历经千辛万苦，降服妖魔鬼怪无数。这一日，师徒四人来在一片荒山野岭之中。这时一年轻村姑上前求助，孙悟空火眼金睛认出是妖怪白骨精所化，上前将其打跑。然唐三藏肉眼凡胎，嗔怪悟空伤害性命，加上猪八戒煽风点火，紧箍咒念得齐天大圣疼痛难忍。在此之后，白骨精又化作小孩和老头前来诱骗，皆备悟空识破打跑。唐僧恼怒不已，一气之下赶走悟空，由此中了妖怪的奸计……本片根据古典名著《西游记》中的故事改编，并荣获1986年中国电影金鸡奖最佳美术片奖；广播电影电视部1985年优秀影片奖；1987年法国布尔波拉斯文化俱乐部青年动画电影节长片奖和大众奖；1989年芝加哥国际儿童电影节动画故事片一等奖。©豆瓣', '李扬', '特伟', 9.2, 11226, 'tt2572208', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1988812771.jpg', 0.2, 0.4, 5.4, 27.4, 66.6, '-0.285480,-0.223582,-0.324753,0.538303,0.412492,-0.229439,0.133059,-0.296888,-0.477125,0.038530,-0.054686,0.693775,-0.496587,-0.018867,-0.047595,-0.017647,-0.305271,-0.386157,-0.304365,-0.161663,0.322831,0.093099,-0.238112,0.061337,-0.259339,-0.350233,0.294992,-0.283197,-0.113147,0.569089,0.499678,-0.195207,-0.285979,-0.016974,0.057708,0.506675,-0.055795,0.143984,-0.023381,0.212756,-0.096970,-0.208180,-0.415159,-0.216219,-0.314566,0.089760,0.156988,-0.316040,0.124604,-0.360480,0.430708,-0.342307,-0.298989,-0.123141,0.311786,-0.230959,0.400943,-0.021462,0.264018,0.349661,0.029124,-0.301864,0.043413,0.124301,-0.141319,-0.049061,-0.312644,-0.007942,0.068748,0.542237,-0.146202,-0.135661,0.160738,-0.280283,0.393585,0.345262,0.114368,0.099613,-0.369077,0.667835,0.260534,-0.267400,0.107983,0.005754,-0.020619,-0.242078,0.071353,-0.194981,-0.061304,0.251059,0.523797,-0.197891,-0.145021,0.105046,-0.121348,-0.158099,-0.153566,0.148084,-0.368820,-0.193156,-0.167625,-0.415188,0.076186,0.065434,0.061212,-0.448233,0.298258,0.027425,0.760584,-0.052136,0.072807,0.313511,0.033570,0.068406,0.775369,-0.149251,-0.041040,-0.261680,-0.199599,0.207644,-0.164956,0.185415,0.172662,-0.000696,-0.240131,-0.303879,0.044736,-0.074388', '1307315', '1418019', '1302279', '1297368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1780330', '致命魔术', '剧情', '19世纪末，人们对科学文明还不是认识得太过清楚，于是，安吉尔（休•杰克曼Hugh Jackman饰）和伯登（克里斯蒂安•贝尔Christian Bale饰）的魔术，成为了伦敦城内的神奇人物。安吉尔出身贵族，魔术手段华丽丰富，是富人圈子里的表演常客。而伯登即使出身平平，争强好胜的心智和充满创造力的魔术技巧，却也令他有了名气。两人自小本是要好的伙伴，然而，现在魔术界二人各有领地，并且都有野心想成为音乐大厅里的顶级魔术师，一番明争暗斗如箭在弦上。伯登掌握了精彩的分身术，叫座又叫好。而安吉尔见情势不妙，搬来科学家助阵——他发明的交流电有无穷魔力，保证让观众目瞪口呆。二人出招接招，一来一往，争斗在剧烈升级，友谊和道德都被抛诸脑后，一场血案在悄悄酝酿。©豆瓣', '休·杰克曼', '克里斯托弗·诺兰', 8.9, 802468, 'tt0482571', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p480383375.jpg', 0.2, 0.6, 7.9, 37.3, 54.1, '0.331638,0.123011,-0.589259,0.451356,0.072362,0.088616,0.351371,-0.113749,-0.482626,-0.233189,0.130818,0.662939,-0.415872,-0.133022,0.040064,-0.283056,-0.205344,-0.698968,0.151152,-0.127633,0.102164,-0.480743,-0.239081,-0.256795,-0.087407,-0.612938,0.223335,0.108238,-0.426042,0.324496,0.268699,0.013653,0.020939,0.255144,-0.085084,-0.063488,0.072542,0.074509,-0.361417,0.031928,-0.076542,-0.123393,-0.284985,0.155116,0.084992,0.156924,0.438618,-0.188747,0.078808,0.158583,0.420626,-0.205113,-0.166552,0.115798,0.339635,-0.052446,0.010281,-0.020027,0.221910,0.118345,-0.017894,-0.055488,-0.814577,0.027949,0.464295,-0.071573,-0.505323,0.376360,-0.015840,-0.330543,-0.266648,0.024205,0.099205,0.033943,0.485141,0.434652,0.223679,0.019186,-0.416048,0.153880,0.762947,0.093557,-0.476503,0.268219,-0.435102,-0.627286,-0.289960,-0.535583,-0.227306,-0.296193,0.289737,-0.002836,-0.012908,0.472232,-0.469432,0.206964,-0.067160,-0.042239,-0.017922,-0.585203,0.075271,-0.718992,-0.242542,-0.687281,-0.265747,0.018064,0.170751,-0.259165,0.982294,-0.729531,-0.121172,0.385442,0.126779,-0.338128,0.701741,-0.169452,0.142906,-0.009255,-0.365636,-0.099411,-0.140984,0.029485,0.020355,0.384063,0.097533,-0.215265,-0.240542,0.376688', '27602116', '24284209', '26283288', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1780428', '省港旗兵2：兵分两路', '动作', '为打击日益严重的犯罪，内地警方应港府要求，派遣向东（徐锦江 饰）、京生（林国斌 饰）、郭学军三名警员，以偷渡客的身份登陆港岛。在港期间，香港警署程Sir作直接领导，本土探员大大（万梓良 饰）协助办案。他们混入内地犯罪集团，惩治烂仔小兴、击毙江家四兄弟，行动干练，手段凶狠。但他们的作风却不为程Sir所欣赏，另一方面，江家兄弟之死也掀起黑帮的复仇怒火，大大更因此丧命。应京生当年战友阿虎之邀，三人假装参与银行抢劫团伙，暗中则和警方联合，意欲将抢劫团伙一网打尽。然行动前夜，突生变故……©豆瓣', '万梓良', '麦当杰', 7.7, 8828, 'tt0093957', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169583728.jpg', 0.4, 2, 28.6, 50.1, 18.9, '0.040339,-0.197137,-0.458894,0.359598,0.213573,0.047686,0.337414,0.254444,-0.473838,-0.160735,0.181899,0.374374,0.236997,-0.176925,0.272070,-0.516543,-0.413042,-0.562413,-0.167797,0.004248,0.166750,-0.327459,-0.067035,-0.550257,-0.079081,0.009313,0.348472,0.240513,-0.455639,0.517091,0.313823,0.584780,-0.687934,0.436791,0.293681,-0.341951,0.317152,-0.138932,-0.471081,0.018533,-0.272836,-0.522174,-0.026766,0.183710,0.274999,0.526397,0.559366,0.122963,-0.186416,-0.490065,-0.035272,-0.571582,0.050161,0.017230,0.711206,0.015425,0.247715,0.462389,0.074129,-0.041940,-0.073334,-0.141101,-0.617845,0.152857,0.386833,-0.144086,-0.386360,-0.132799,-0.299187,0.374110,-0.193775,0.002780,0.046456,0.585761,0.233977,-0.240514,0.077848,0.148420,-0.439250,0.203477,0.762850,-0.121670,0.265592,-0.494432,-0.054676,-0.323165,0.185465,-0.194864,0.076013,-0.113882,0.384649,-0.333701,0.078265,0.293141,-0.414199,-0.279921,-0.366619,0.150038,-0.123212,-0.314715,0.414303,-0.927643,-0.034396,0.035902,-0.079809,0.196912,0.546686,0.096416,0.508719,-0.500921,-0.317136,0.461286,0.462346,-1.052717,0.152085,0.151894,0.138960,-0.237174,-0.314694,-0.245874,0.616298,0.216636,-0.046090,-0.005402,-0.264777,-0.523413,0.276784,-0.477000', '3621404', '26826398', '3412882', '1484760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1781023', '芭比与魔幻飞马之旅', '爱情', '在遥远的北欧雪国，生活着一个无忧无虑、美丽纯洁的公主安妮卡（凯莉·谢里丹 Kelly Sheridan 配音）。她热爱自然，喜欢溜冰，然而国王（罗素·罗伯特 Russell Roberts 配音）和王后（凯瑟琳·巴尔 Kathleen Barr 配音）却对其保护有加，生怕女儿受到一点伤害。因此安妮卡只能偶而偷跑出王宫，享受短暂的自由与快乐。在生日当天，安妮卡捡回一头小北极熊，照例被国王和王后一顿唠叨。夜幕降临，闷闷不乐的安妮卡决定偷跑出去，享受溜冰的乐趣。她优美的舞姿博得了国民的赞美，也引来了邪恶恐怖的巫师万洛克（Colin Murdock 配音）。巫师将国民们变作石头，强迫安妮卡嫁给他。关键时刻，一匹飞马来到无助的安妮卡身边……©豆瓣', '凯莉·谢里丹', 'Greg Richardson', 8.3, 10149, 'tt0480345', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155076193.jpg', 0.4, 0.9, 19.6, 42.7, 36.3, '0.143075,0.402715,-0.580641,0.691448,0.077700,-0.269875,0.821997,0.227910,0.063490,-0.035141,0.548308,0.755177,-0.415054,0.135157,0.587550,0.275360,-0.286677,-0.308273,0.245713,0.234423,0.007807,-0.163462,-0.078342,-0.167823,-0.359282,-0.539111,0.332121,-0.343335,-0.100194,0.610026,0.122964,0.102394,-0.185154,0.231371,0.150736,-0.096332,0.185871,-0.326241,-0.107549,0.224889,0.066530,0.126115,0.024542,0.155339,0.275968,-0.130336,0.659901,-0.560091,-0.077714,-0.009260,0.517235,-0.342023,0.250440,0.111782,-0.018230,-0.096959,0.157797,-0.305028,-0.115554,0.157261,0.217321,-0.320012,-0.492407,0.002558,-0.155150,0.032162,-0.404368,0.447472,-0.142291,0.020137,0.471498,-0.323635,0.230480,0.034684,-0.004416,0.502421,-0.193231,0.602401,-0.293767,0.097932,0.419820,-0.064428,-0.390736,-0.057144,-0.370137,-0.237671,0.306328,-0.292884,-0.733926,-0.014312,0.353668,0.011487,-0.151529,0.271883,-0.573167,-0.070805,-0.579178,-0.211267,0.251036,-0.484640,-0.216896,-0.515399,0.123170,-0.366328,-0.190340,-0.175854,0.161358,-0.226514,0.805574,-0.753852,0.504287,0.767824,0.412796,-0.083428,0.491683,0.210637,0.145122,0.102252,-0.087782,0.473903,0.175007,0.151965,0.297028,0.163848,-0.097533,0.113294,-0.348974,0.604508', '3005387', '4233625', '26348103', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1781126', '十二宫', '剧情', '二十世纪70年代，旧金山出现了一个自称“十二宫”的杀人狂，杀人后，向媒体寄一封信，留下密码、线索，向警方挑衅，多次的阴差阳错使案件陷入僵局，警方渐渐束手无策。连环杀人案件也引起了《旧金山纪事报》的记者罗伯特（杰克•格兰恩哈尔 饰）和保罗（小罗伯特•唐尼 饰）的注意，他们在警察大卫（马克•普法洛 饰）的帮助下，开始调查这一系列的连环凶杀案件，在和“十二宫”杀手斗志斗勇的同时，他们个人的生活也面临了极大的挑战。©豆瓣', '杰克·吉伦哈尔', '大卫·芬奇', 7.5, 183983, 'tt0443706', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p470486287.jpg', 0.6, 3.8, 33.1, 46.1, 16.3, '0.231216,-0.371267,-0.588651,0.607408,0.024492,0.047595,0.532826,0.106002,-0.440591,-0.195969,0.410956,0.695602,-0.490199,0.033368,0.362857,-0.416414,-0.487365,-0.760903,0.106787,-0.217401,-0.451347,-0.603302,-0.325104,-0.507956,0.214409,-0.001627,0.210016,0.273539,-0.272975,0.460869,0.325885,0.574584,-0.131719,0.447378,0.216108,0.095993,0.393234,-0.372414,-0.222375,0.287409,0.118818,-0.432167,-0.042602,0.365388,0.027780,0.533660,0.684191,-0.377873,-0.280858,-0.030248,0.500469,-0.254234,0.129471,0.182384,0.447210,-0.018817,-0.073041,0.344808,-0.113762,-0.162897,0.042903,-0.023639,-0.692896,0.190849,-0.090198,0.428761,-0.425335,0.321689,-0.360554,0.395089,-0.193289,-0.161988,0.386681,0.503692,0.329587,-0.105328,0.024422,-0.049064,-0.349993,0.130788,0.320545,0.054371,-0.112911,-0.113144,0.027575,-0.377339,-0.318167,0.098197,-0.186819,-0.003273,0.719382,-0.289574,-0.144945,0.319061,-0.514752,-0.279339,-0.360988,-0.305011,-0.224629,-0.260199,-0.082072,-1.041833,-0.071307,-0.114151,-0.259064,0.103702,0.006122,-0.061918,0.604593,-0.551630,0.084588,0.761675,0.186375,-0.409326,0.394350,-0.287998,-0.081408,-0.162451,-0.255615,0.037550,0.391450,0.549745,0.378405,0.377018,0.103174,-0.220855,0.016287,0.134324', '6517421', '2028645', '6984051', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1782223', '警花燕子', '剧情', '刑警父亲因公殉职多年后，遗传了父亲血性的田燕（汤唯 饰）也成了警察，不过她做的是交警。上班第一天，她就因照章办事得罪了赶着出庭的大律师端木长春（田雨 饰），但后者当时没同她计较，令她得意洋洋。支队领导李队晓得事情始末后，批评她做事欠妥当，因为端木长春十分不好惹，果然，她被骂时生 出的火还没消，支队就收到法院的传票。在李队和指导员的“唬吓”下，田燕为了不使她与端木长春的私人恩怨牵连到支队，硬着头皮找到端木长春要求和解，不想不打不相识的两人竟因此成为恋人。然而，他们的爱情之路，因为暗恋端木长春的叶卿（李佳璇 饰）的刻意作梗，充满了波折。©豆瓣', '汤唯', '张菁', 5.8, 4805, 'tt9548076', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2328611890.jpg', 5, 21.2, 55.3, 13.9, 4.5, '0.325520,-0.069229,-0.669786,0.430711,-0.683109,-0.395254,0.466457,0.118646,-0.898102,-0.049724,0.274278,0.449758,-0.049896,0.129424,0.286792,-0.049985,0.069260,-0.497254,0.299827,0.040773,0.146129,-0.586003,0.011148,-0.127788,-0.113662,-0.070806,0.252670,-0.044731,0.105269,0.387214,0.271825,-0.012648,-0.033666,0.551413,0.306195,0.297922,0.027802,0.328473,-0.141468,0.099011,0.165094,-0.156444,0.039507,0.063189,0.163481,0.548582,0.023374,0.111242,-0.173778,-0.162165,0.158018,-0.494468,0.037372,0.443701,0.252171,-0.029724,0.408075,0.338974,-0.315762,-0.316504,-0.115150,0.395353,-0.327142,0.166114,0.026969,0.121049,-0.559595,0.605460,-0.468337,-0.198570,0.038773,-0.517317,0.224670,0.322108,0.387430,0.072678,-0.335005,-0.174628,-0.508500,0.182325,0.433792,-0.008798,0.100415,-0.010760,-0.100344,-0.442834,0.165571,-0.188721,-0.131234,0.004472,0.190267,-0.123760,-0.187310,0.062543,-0.135038,-0.320219,0.031924,0.078043,0.068437,-0.537261,0.046300,-0.140331,-0.044165,-0.596576,-0.390551,-0.066864,0.295035,-0.315396,0.328586,-0.737626,0.140771,0.389487,0.106991,-0.820566,0.394960,0.394002,0.074978,-0.079799,0.119553,-0.166931,-0.014542,0.668680,0.360517,0.480640,-0.004812,-0.451563,-0.056029,0.031606', '2334073', '1308034', '1421278', '1301221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1782964', '一公升的眼泪', '剧情', '本片改编自日本同名文学作品《一升的眼泪》，作者是一位坚强的罕见疾病患者。1986年首次出版创下26万本的销售纪录。女主角木藤亚也（大西麻惠 饰），生活在一个平凡的家庭，一直过着简单快乐的生活。升上高中后她的身体似乎出现了些毛病，她开始失去平衡力甚至常常摔倒在地。妈妈带她到医院检查，才发现她患上了一个名叫脊髓小脑变性症的不治之症。而因为这一场突如其来的病变，让亚也的身体运动机能衰弱，手脚自主活动与语言能力逐渐丧失。亚也为此放弃了很多东西，也同样遭受了部分人的歧视与不解，她不明白为何病魔一样要选择她，可是她在家人的理解与鼓励，让她依然没有对生活完全失望。直至患病末期只能无助地躺在床上，面对生命的无助，却勇敢地生存至最后一秒，直至生命机能停止而死亡……©豆瓣', '加藤和子', '冈村力', 8, 13975, 'tt0494724', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2076112084.jpg', 0.4, 1.9, 23.9, 43.5, 30.3, '0.026582,0.193280,-0.730981,0.493766,-0.011301,-0.260295,0.826819,0.168744,-0.391566,-0.340318,0.234452,0.742970,-0.134453,0.242367,-0.069743,-0.060057,-0.120919,-0.674796,0.008486,0.336087,-0.635641,-0.179192,-0.059434,-0.344117,-0.334844,-0.509834,0.697959,0.182890,-0.260314,0.454009,-0.032064,0.208395,0.357719,0.542021,-0.119330,-0.060020,-0.166408,-0.041907,0.024783,0.138559,0.380892,-0.530241,-0.169345,0.289567,-0.058716,0.286942,0.809956,-0.170501,-0.357113,-0.022517,0.537987,-0.326100,-0.224328,0.189196,0.225770,0.030972,0.069109,0.049739,-0.164397,0.179256,0.157153,0.250493,-0.960710,-0.155164,0.102711,0.333562,-0.528512,0.638821,-0.032102,0.059966,-0.196565,-0.406366,0.124429,0.349150,0.108752,0.605175,-0.621505,0.065839,-0.358637,0.103972,0.656114,-0.093301,-0.690093,0.668103,-0.551321,-0.656307,-0.243713,-0.335786,-0.419742,-0.113783,-0.099892,0.322151,-0.500730,0.428218,-0.559675,0.203930,-0.275928,-0.378918,-0.364621,-0.196155,-0.025636,-0.145357,-0.180120,-0.358973,-0.278827,-0.019988,0.014454,-0.423552,0.769022,-0.637480,0.318740,0.655057,0.291238,-0.498477,0.527588,0.276924,-0.084279,-0.035695,-0.033569,0.667531,-0.184389,0.236104,0.125385,0.236074,-0.078055,0.468237,-0.439962,0.742640', '26667010', '1296757', '26315728', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1783457', '功夫熊猫', '喜剧', '首度以人见人爱的大熊猫和中国功夫作为故事主线，《功夫熊猫》定于6月全球上映，届时配合举世瞩目的2008年北京奥运，加上武术首度被列为奥运特设项目，相信定必在全世界掀起势不可挡的中国功夫热潮，电影有望打破纪录，勇夺全球动画票房金牌！梦工厂对这部重头戏非常重视，除了出动《怪物史瑞克》、《马达加斯加》班底精心构思故事、设计角色，钻研最先进的电脑特技外，更请来最星光熠熠的声演阵容，包括搞笑巨星杰克·布莱克( Jack Black )声演熊猫阿宝、金像影帝达斯汀·霍夫曼( Dustin Hoffman )声演施福大师、成龙大哥声演灵猴、性感巨星安吉丽娜·朱丽( Angelina Jolie )声演飞虎女、《霹雳天使》华裔红星刘玉玲( Lucy Liu )声演毒蛇，如此强劲卡士绝对前所未见！梦工厂CEO杰弗瑞·卡森伯格( Jeffrey Katzenberg )早前更为电影将会铺天盖地的宣传攻势揭开序幕，亲自在一段45分钟短片亮相介绍剧情和特色。香港电影公司亦特别安排放映给业内人士及商业伙伴率先欣赏，片中熊猫阿宝、飞虎女、灵猴、毒蛇、仙鹤、猛螳螂、大豹等角色一出场，即引发笑声不绝，观众反应非常热烈，大家都很期望电影正式上映时，可看到熊猫阿宝使出「无敌扑楼梯」、「面条护身术」、「肚腩凸击」等独门绝招！故事讲述好食懒做的熊猫阿宝，一直醉心中国功夫，一次误打误撞竟然被认定为传说中的武林高手「龙战士」，奉命去对付刚逃狱的魔头大豹！一代宗师施福大师因而要面对人生最大的挑战──如何在迫切的时间内，将拥有一身豪华臀、麒麟臂、肚腩肉、不能看也不能打的大熊猫，训练成为名震江湖的功夫大师？', '杰克·布莱克', '马克·奥斯本', 8.2, 534552, 'tt0441773', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1597238857.jpg', 0.2, 1.1, 18.3, 51, 29.5, '-0.345532,-0.189043,-0.368154,0.511046,0.382346,0.197626,0.138348,0.072770,-0.280779,-0.257537,0.361107,0.436316,-0.420393,-0.278499,0.241812,-0.348900,-0.045960,-0.367222,-0.024529,-0.074169,0.140785,0.134107,-0.267651,0.061465,0.039525,-0.427733,0.497768,-0.200825,-0.186539,0.318095,0.342830,-0.170019,-0.002920,-0.126281,0.055513,-0.074109,0.247736,0.076024,-0.371347,0.466992,-0.034293,-0.043779,-0.056079,0.065315,-0.263800,-0.217225,0.410912,-0.309161,0.006761,-0.294389,0.305933,-0.131580,-0.105664,-0.115438,0.307988,-0.047339,0.542529,0.032777,0.213876,0.102527,-0.108295,-0.287629,-0.605598,0.193010,0.055577,0.055045,-0.251006,0.107758,-0.189679,0.210768,0.043281,-0.198606,-0.118863,-0.154129,0.539189,0.181221,0.145338,0.494395,-0.233182,0.450362,0.153637,-0.022030,-0.068691,0.451820,0.282515,-0.380117,0.061368,-0.377754,-0.049582,0.119626,0.237803,-0.091880,0.051796,0.162503,-0.415178,0.034506,-0.124848,-0.3