INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1783461', '马格瑞姆的神奇玩具店', '喜剧', '对外号称自己243岁的马格瑞姆（达斯汀·霍夫曼饰）先生，开了一家有200年历史神奇的玩具店，每件玩具都有自己的生命力，莫莉·马奥尼（娜塔丽·波特曼饰）是这家玩具店的经理，小时候的她因为能出色的弹奏“拉赫曼尼诺夫第二号钢琴协奏曲”而被认为是一个天才钢琴手，可是直到她22岁，却一直无法突破瓶颈，变的对自己自信心不足。老实刻板的会计师亨利·韦斯顿（杰森·贝特曼饰）被雇佣为玩具店做资产评估，和玩具店中一直交不到朋友的小伙计埃里克（扎奇·米尔斯饰）渐渐成为了朋友。突然有一天，马格瑞姆宣布要离开，要将店交给莫莉，莫莉却不相信自己有这样的能力去经营这玩具店，而此时，一直明亮欢乐的玩具店也开始变的阴暗而丧失色彩，难道马格瑞姆的玩具店真的要从此消失吗？，朋友们要如何帮助莫莉建立自己的信心呢？©豆瓣', '娜塔莉·波特曼', '扎克·海尔姆', 7.1, 15651, 'tt0457419', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p934716347.jpg', 0.8, 6.8, 44.3, 35.2, 13, '0.232632,0.105401,-0.646008,0.409487,-0.350169,-0.374388,0.656241,0.176805,-0.643182,-0.288632,0.066995,0.892636,-0.058402,0.329037,0.110374,0.445412,-0.044537,-0.728094,0.140226,-0.215286,-0.066251,-0.565109,-0.274277,-0.223066,-0.238198,-0.193049,0.336690,0.036766,0.062756,0.241791,0.341559,0.194188,0.464180,0.304478,-0.261620,-0.103056,0.200886,-0.060282,-0.037438,0.290572,0.177638,0.007490,-0.046838,0.052425,0.072057,0.271330,0.310330,0.176051,-0.251989,0.075488,0.395814,-0.076980,-0.011378,0.214160,0.324241,0.028388,0.184124,0.056494,-0.281210,-0.016499,-0.017187,-0.221804,-0.973826,0.106533,0.154153,0.110013,-0.731927,0.148910,-0.223005,-0.203239,0.077174,-0.210429,0.120688,0.293850,0.335553,0.271300,-0.127864,0.012527,-0.664564,0.094629,0.560419,-0.037667,-0.261125,0.536708,-0.252669,-0.313933,-0.070609,-0.309345,-0.551366,0.083680,0.098774,0.214463,0.067353,0.010127,-0.664817,-0.029064,-0.185074,-0.253722,-0.031445,-0.420111,-0.121769,-0.289028,-0.076860,-0.428423,-0.172640,0.099949,0.005758,-0.345976,0.712422,-0.981232,0.185368,0.359666,0.337926,-0.315794,0.699301,-0.118066,0.045953,-0.110234,-0.131357,0.128098,-0.174884,0.244788,0.101345,0.334404,0.343032,-0.252337,-0.300897,0.579572', '1793491', '27056396', '3006892', '1481233');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1783537', '男妇女主任', '剧情', '故事发生在金秋时节的兰河峪村。由于村妇女主仼交接班出现问题，此职位临时空缺，村长（张洪杰 饰）便动员凤莲（宋丹丹 饰）的丈夫刘一本（赵本山 饰）临时代理去乡里开会。在乡妇联会议上，刘一本天上一拳地上一脚地把本村妇女工作吹了个溜溜光。说者无心、听者有意，领导马上把兰河峪当成了全乡的典型，还说过段时间去村里开现场会。自知说走嘴的刘一本回村后便被村长臭骂一顿，凤莲也埋怨他不该在会上自吹自擂。骑虎难下的刘一本借坡下驴，想尽办法兑现在会上的“精彩发言”。他走东家串西家，联系热心群众开展农村文娱活动，利用广播宣传开展精神文明活动的重要性。一时间，村民的热情被调动起来，所吹嘘的事情件件弄假成真......©豆瓣', '赵本山', '张惠中', 7.7, 7655, 'tt9501772', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2538982299.jpg', 0.5, 2.2, 32.2, 43.6, 21.5, '0.446841,-0.019493,-0.412924,0.388984,-0.310025,-0.026237,0.258989,0.214699,-0.165758,-0.074813,-0.113789,0.280494,-0.258001,0.297060,0.164979,-0.186446,-0.159735,-0.342940,0.048757,0.083448,-0.144296,-0.316092,0.401260,-0.196491,-0.216807,0.274194,-0.061395,0.155353,-0.427240,0.177254,0.379277,0.065001,0.076798,0.392209,0.046151,0.012229,-0.022874,0.068260,0.125689,-0.117321,0.016702,-0.461243,-0.127880,-0.102076,0.426010,0.229449,0.487846,0.212800,-0.170395,0.057892,0.342031,-0.084826,0.413596,0.260841,0.859616,0.168750,-0.218511,0.027989,-0.250393,-0.312262,0.027702,-0.417657,-0.364755,-0.016147,-0.047982,0.112910,-0.582738,0.149085,0.069313,0.270365,-0.177426,-0.338706,0.290554,0.362382,0.054667,0.423077,0.202495,0.006002,-0.288881,0.631148,0.413128,-0.116744,0.084029,-0.094177,-0.024610,-0.155566,0.122061,0.346435,-0.353377,-0.162351,0.279764,-0.414530,0.022897,-0.281547,-0.262682,-0.042785,0.038045,-0.359708,-0.003115,-0.152689,-0.050978,-0.424165,0.227560,0.178806,-0.028833,-0.007818,0.410154,-0.133364,0.588710,-0.143290,-0.070719,0.413822,0.145463,-0.466070,0.355929,0.107472,0.341751,-0.264506,-0.026296,-0.115642,0.180242,0.650033,0.371510,0.481092,-0.101606,-0.419988,0.133557,0.184856', '1439400', '25912924', '1305363', '1293847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1783772', '巴黎，我爱你', '剧情', '这是2006年戛纳电影节的开幕影片，众多著名导演参加了这部包含有十多个小故事的影片，其中包括科恩兄弟、杜可风等等。制片人希望通过这部众多导演参与的影片讲述发生在巴黎的几乎所有的情感。片中的十多个小故事有的看似荒诞不经、有的看似毫无头绪，但是细细品味，你会发现其中 每个导演想表达的“真理”。一个还算小有成就的中年男友，在路边停车时，突发感概，为什么满街上的人，只有自己形单只影？就在这时，一个女人因为低血糖晕倒了在他的车旁，热心的男人将她扶进了自己的小车后座休息，两颗孤独的心由此靠近。塞纳河畔，三个年轻人在调戏着路过的年轻女子。其中一个发现了就在他们旁边有一个戴头巾的漂亮女孩，女孩离开时不小心摔倒了，那个年轻人跑过去把她扶了起来。爱情在两人中间慢慢滋长。一间画室里，一个法国男孩对另一个男孩一见钟情，絮絮叨叨的讲着自己是如何抑制不住和他谈话，讲着自己是如何被对方的气质所吸引……然而另一个男孩对他却无动于衷，最后，法国男孩留下了自己的联系方式离开了。这时，男孩用英语问旁人，“刚才他在讲什么？我法语不好。”随后，男孩冲出了画室，奔跑着去追寻自己的爱情。……一个美国中年妇女来到巴黎旅游，她望着川流不息的人群，此时她多么希望自己就是法国人，能长此居住在这个陌生而又极具魅力的城市。她想起了自己的前男友，虽然两人已经分手了十一年，他也有了自己的家庭。最后，他参观了巴黎的公墓，看到历史上叱咤风云的人物安静的躺在那里，她也感悟了。', '朱丽叶·比诺什', '奥利维耶·阿萨亚斯', 8.3, 142736, 'tt0401711', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1762258035.jpg', 0.3, 1.3, 17.2, 46.1, 35.2, '0.452989,0.138016,-0.821454,0.587129,-0.308414,-0.146208,1.046512,0.011753,-0.345301,-0.144284,0.330688,0.889092,-0.202851,0.529877,0.100629,0.151941,-0.376358,-0.561279,-0.081066,-0.044188,-0.446730,-0.343145,-0.192192,-0.041583,-0.194523,-0.046231,0.379802,-0.028553,-0.278611,0.194391,0.310821,-0.108662,-0.019751,0.561562,-0.454029,0.270531,0.107517,0.023328,0.146459,0.206852,0.155502,-0.505747,-0.316863,0.122280,-0.336856,0.363556,0.585527,-0.051162,-0.126197,0.277320,0.453582,-0.219967,-0.089171,0.071910,0.070879,-0.006150,0.189586,-0.061081,-0.185535,-0.118535,0.052369,0.110714,-0.530390,0.070511,-0.130370,0.429675,-0.814951,0.670950,0.077541,-0.136808,0.232944,-0.361484,0.244055,0.177999,0.042299,0.239503,-0.089256,-0.085558,-0.669276,0.184771,0.650169,0.083833,-0.192091,0.510984,-0.281384,-0.449395,-0.037214,0.047572,-0.520972,-0.123862,0.330423,-0.176503,-0.282700,-0.252339,-0.429150,0.219312,0.015752,-0.205255,-0.128359,-0.482261,-0.289170,-0.451725,-0.112845,-0.479299,-0.373381,-0.037040,-0.049941,-0.218921,1.002298,-0.752799,0.048355,0.672990,0.394778,-0.288535,0.887895,0.056064,0.013947,-0.089623,-0.062904,0.242009,-0.138581,0.245572,0.096960,0.676167,-0.217347,0.055368,-0.593922,0.584857', '30162520', '5262027', '3055049', '26648284');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1783774', '解构生活', '剧情', '威尔·弗兰西斯（裘德·洛 Jude Law 饰）是知名建筑师，可年轻有为的他家庭生活并不那么幸福。妻子与他的沟通越来越少，一心扑在自闭的女儿身上，家人缺乏日常的交流。威尔的办公室接连被盗，气愤的他开始调查窃贼，并由此结识了单身妈妈阿米拉（朱丽叶·比诺什 Juliette Binoche 饰）。魅力独特的阿米拉正是窃贼的母亲，可此时威尔已深深被她吸引。他放弃对盗窃案的追踪，悄悄追求阿米拉。阿米拉生活贫困，一个人肩负着抚养和教育儿子的重任。威尔渐渐打动了阿米拉，似乎两个人的生活即将因为这段感情被重新构建。然而，生活的解构，并不像威尔设想的那般简单。©豆瓣', '裘德·洛', '安东尼·明格拉', 7.4, 11496, 'tt0443456', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p786728321.jpg', 0.3, 3.2, 35.8, 47.9, 12.8, '0.469796,-0.227168,-0.531739,0.395480,-0.303441,-0.504921,0.913241,0.233155,-0.351955,-0.451657,0.104643,0.545981,0.165882,-0.004242,0.196182,0.114229,-0.236573,-0.576325,0.170911,0.075439,0.070117,-0.645226,-0.131554,-0.350669,-0.170688,-0.342514,0.536647,0.008878,-0.288830,0.477470,0.028662,0.330849,0.114862,0.699101,0.064705,0.021794,0.262931,-0.015048,-0.092874,-0.012325,-0.005419,-0.060482,0.060359,0.330022,0.018015,0.281874,0.533816,-0.422077,0.087084,-0.295732,0.227404,-0.106895,0.121317,0.047720,-0.015118,-0.047144,0.140869,0.136448,-0.043804,-0.264547,0.214103,-0.272997,-0.579544,-0.097533,0.114814,0.056441,-0.663708,0.280857,-0.058251,-0.254858,0.187433,-0.276178,0.111234,0.404487,0.192291,0.432550,-0.120954,0.185211,-0.363528,0.349891,0.436978,-0.024957,-0.271995,0.414653,-0.535089,-0.737784,-0.016021,-0.044080,-0.662429,-0.116682,0.380123,0.065567,-0.256084,0.561625,-0.355625,0.135654,-0.136893,-0.106367,0.046476,-0.735094,0.298042,-0.522547,-0.356546,-0.474393,-0.421842,-0.308047,-0.147222,-0.354300,0.540825,-0.833823,0.393785,0.556792,0.100881,-0.571677,0.566772,0.338079,0.158142,-0.167591,-0.181094,0.786482,0.091916,0.207931,0.123344,0.396488,0.256435,0.211802,-0.392396,0.735436', '3059036', '1309172', '2131640', '1305666');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1784747', '死亡塔', '动作', '一代宗师李振强（李小龙 饰）和武林高手秦谷（黄正利 饰）是生死之交，秦谷的莫名死亡让李振强决心找到背后的真凶。哪知道在这过程中，李振强不幸遇害，只留下了一个和死亡塔有关的秘密，没有人能够解开。振国（金泰中 饰）是李振强的弟弟，得知哥哥的死讯，闭关修炼多年的振国决定下山，为兄寻仇。追随着李振强留下的线索，振国来到了神秘的山庄之中，经历了诸多生死攸关的险情，并最终打开了秘密通道，来到了潜藏在山庄之下的宫殿之中。在这里，等待着他的竟然是正是秦谷，振强和振国都落入了他一手策划的阴谋漩涡之中。秦谷想要将振国杀死毁尸灭迹，遭到了后者的奋起反击。©豆瓣', '李小龙', '吴思远', 6.8, 4465, 'tt0076709', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1388194867.jpg', 4.4, 10.5, 41, 29, 15.1, '0.379121,0.237103,-0.681656,0.474672,-0.131083,-0.122588,0.623031,-0.139967,-0.923830,-0.212951,0.448494,0.674579,-0.012485,0.130722,-0.020956,-0.031210,-0.262166,-0.795145,-0.164028,-0.377008,-0.169013,-0.566683,-0.367940,0.176346,0.028093,-0.371431,0.500457,0.261191,-0.134970,0.450283,0.329813,0.438769,-0.381390,0.548857,-0.101005,0.182720,0.143008,-0.109280,-0.504707,0.491482,0.068728,-0.190720,-0.108873,0.527804,-0.170156,0.394277,0.475010,-0.368121,-0.095307,-0.005780,0.080715,-0.394811,-0.049460,0.089488,0.282032,0.166732,0.342489,0.713172,-0.378196,0.130194,0.080178,0.059444,-0.792437,-0.030534,0.377459,0.277935,-0.573423,0.224355,0.052262,-0.278957,0.146978,-0.535264,0.403308,0.407861,0.341841,0.231911,-0.323676,-0.175120,-0.563262,0.035453,0.516322,-0.481312,0.052444,0.072537,0.227773,-0.200119,0.127868,-0.203247,-0.062765,0.031109,0.537814,0.374202,-0.251902,0.104878,-0.383991,0.087369,-0.413415,-0.048762,-0.126467,-0.429672,-0.474136,-0.229932,-0.180930,-0.071520,-0.340003,0.178903,-0.224543,-0.237105,0.465463,-0.870872,0.274848,0.415036,0.347437,-0.182910,0.634948,-0.067243,-0.028397,-0.197637,0.062813,0.046642,-0.182502,0.489226,0.042837,0.214390,-0.050056,-0.462556,-0.629049,0.165354', '1301022', '1783461', '35030151', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1785166', '重见天日', '剧情', '出生在德国的迪特•丹格勒（克里斯蒂安•贝尔饰）自幼就梦想着驾驶飞机翱翔天际。长大后，他随家人移民至美国，加入军队成为了一名真正的飞行员。随后迪特便随海军投身越南战场。赶往执行任务的途中，迪特飞机不幸被越南军队的地面炮火击落。侥幸逃脱一死的他，却最终被敌人俘获，饱受严刑折磨。迪特被押至设在老挝的战俘集中营，那里还有几个美国军队的同伴。看守敌人给予他们非人待遇，迪特还未坐定就暗下决心要逃跑，但周围的同伴吉恩（杰瑞米•戴维斯饰）、杜恩（史蒂夫•茨恩）等并不那么认为，他们没多少信心。在一番劝说下，迪特精心策划，要在雨季来临时越狱。他们要面对是无边丛林、饥饿、野兽，还有不知道在何处的越南人……©豆瓣', '克里斯蒂安·贝尔', '沃纳·赫尔佐格', 7.6, 15381, 'tt0462504', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p828964132.jpg', 0.5, 2.5, 29.3, 50.1, 17.5, '-0.001407,0.066709,-0.795210,0.459333,-0.035631,-0.176675,0.501533,-0.018123,-0.305222,-0.035858,0.336387,0.631418,0.302548,-0.193742,0.155429,0.107326,-0.470184,-0.455952,0.026257,-0.155725,-0.527414,-0.400870,-0.099729,-0.386052,-0.036964,-0.255178,0.650469,0.174548,0.050975,0.438634,0.106264,0.383466,-0.015010,0.568912,-0.361972,0.054692,0.298169,-0.341120,-0.233832,0.318234,-0.085738,-0.217514,-0.144477,0.061688,0.138336,0.236734,0.721339,0.018479,0.180100,-0.127444,-0.376712,-0.555042,0.349126,0.198503,0.556168,-0.280194,-0.137498,0.134279,0.121672,0.217560,-0.170142,0.064394,-0.477513,-0.162427,-0.131774,0.068719,-0.669718,0.350927,-0.240059,0.131985,-0.150800,-0.146176,0.008828,0.652158,-0.079709,0.286083,-0.115178,-0.058849,-0.788675,0.014710,0.866684,-0.301033,-0.071541,0.076601,-0.020368,-0.519417,0.151754,-0.241706,-0.320240,-0.145782,0.536475,-0.008324,-0.401456,0.175186,-0.485403,0.129748,-0.551294,-0.257017,-0.291787,-0.314926,0.038246,-0.658309,0.241908,-0.169558,-0.306557,0.359184,0.094733,0.172430,0.686191,-0.631915,0.253619,0.654647,0.527354,-0.548977,0.395198,0.144124,0.188285,-0.055080,0.235314,0.457601,0.225413,0.284067,0.240953,0.243283,0.091002,-0.207972,-0.140224,0.292459', '1294941', '1292849', '1419918', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1786231', '光荣岁月', '剧情', '1944年至1945二战期间，一群阿尔及利亚的伊斯兰教小伙子应召入伍，被编入法国军队，参加对德国的反击战。阿布戴卡德（ 罗舍迪·泽姆 Roschdy Zem饰）因通过军事理论考试而被授予下士军衔，在上级命令下带领同乡的弟兄们编进严厉的马丁尼兹中士（伯纳德·布兰肯 Bernard Blancan 饰）的队伍中。在首次训练中，矮小伙萨义德（贾梅尔·杜布兹 Jamel Debbouze 饰）在应对中士投手雷的考察时险些酿成大祸，幸好中士出手敏捷，反应神速，才让这批新兵幸免于难。在战斗中，这些新兵表现神勇，特别是下士，中士对他另眼相看。午餐时，出于对非洲士兵的歧视，食品分配极为不公，为了各种族士兵权益，下士不惜以下犯上，贸然顶撞了中士，两人是否就此结下私人恩怨？非洲士兵们的命运又何去何从？©豆瓣', '贾梅尔·杜布兹', '拉契得·波查拉', 7.7, 6666, 'tt0444182', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1426913570.jpg', 0.4, 2.3, 27.6, 50.8, 19, '0.148635,-0.057244,-0.460221,0.462670,-0.157861,-0.217588,0.135489,-0.080900,-0.589893,-0.202646,0.465214,0.634676,-0.001600,-0.259823,0.386373,-0.410092,-0.341984,-0.678357,-0.182927,-0.064639,-0.496809,-0.407563,-0.075318,-0.303712,-0.191491,-0.677953,0.433922,-0.189635,-0.282136,0.490047,0.124012,0.391451,0.126794,0.224118,0.103260,-0.195510,0.421948,-0.206402,-0.333336,-0.012293,-0.375105,-0.189981,-0.261274,-0.106622,0.203825,0.396511,0.594082,-0.368610,0.028896,-0.261623,0.121167,-0.279427,0.219921,0.218595,0.559455,0.168112,-0.052327,0.203043,0.209767,0.344417,-0.150165,-0.050869,-0.450968,-0.136804,-0.110653,-0.066426,-0.590750,0.494120,-0.259920,0.170305,0.167552,0.014045,-0.166445,0.478582,0.124006,0.262172,-0.077074,-0.244777,-0.255382,0.209321,0.449344,-0.289631,-0.227181,-0.318530,-0.357397,-0.568470,0.466937,-0.302541,-0.227088,-0.084611,0.069143,-0.160897,0.236057,0.349168,-0.558728,0.056524,-0.410929,-0.336433,-0.098892,-0.209890,-0.105860,-0.575648,0.152351,-0.283484,-0.383249,0.291017,0.277220,0.260267,0.737154,-0.626394,0.036261,0.258196,0.320717,-0.372501,0.326887,0.285721,0.182815,0.019324,-0.123048,0.071965,0.424877,0.097392,0.101195,0.280925,-0.080073,-0.378399,0.140806,0.048199', '3811356', '4127270', '1826173', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1787277', '彩虹女神', '剧情', '岸田智也（市原隼人）和佐藤葵（上野树里）在大学结识。二人非常合拍，葵还常常给智也出谋划策如何追女生。葵是独立电影制作小组的成员，她要在毕业前导演一部叫《THE END OF THE WORLD》的电影，于是决定选用智也当男主角。无奈毕业后，路开始分叉。葵引荐智也去了一间影视社工作，重遇那晚葵想说出对智也的情愫，然而终究没有开口。葵不久飞往美国留学。正巧智也抬头，看到天空挂着彩虹。他兴奋地拍下，发送给相隔重洋的葵，但是却得到了葵飞机失事罹难的噩耗。亲人同学都悲伤不已，用她生前的电影去悼念逝者，在智也的心目中，葵也始终朦胧的牵动着他内心的爱。©豆瓣', '市原隼人', '熊泽尚人', 7.7, 38991, 'tt0804513', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p634033465.jpg', 0.3, 2.3, 30, 45.6, 21.9, '-0.030863,0.137576,-0.737001,0.692559,0.412860,-0.536405,0.211369,0.212529,0.142086,-0.376039,-0.109430,0.652200,-0.077391,0.500709,0.271931,0.064954,-0.567003,-0.682883,-0.088991,-0.243676,-0.115352,-0.212106,0.252019,-0.011184,0.077028,-0.175169,0.858179,0.302607,-0.216122,0.690731,0.223398,0.108397,-0.198544,0.363120,-0.079671,0.154199,-0.149584,0.282875,-0.154966,-0.080197,0.141523,-0.352878,-0.372548,0.262842,0.352490,0.550865,0.722581,-0.037049,-0.244775,0.175867,0.122008,-0.348140,0.022065,-0.226708,0.460845,-0.102322,-0.100011,0.170734,-0.109459,0.237512,-0.148645,0.193543,-0.624077,0.024436,-0.031443,-0.033536,-0.366197,0.625157,0.012367,0.212586,0.072744,-0.262885,0.030126,0.141555,-0.089049,0.533167,-0.263519,0.356033,-0.159221,0.338522,0.590085,0.166774,-0.090768,0.453216,-0.195861,-0.510998,-0.206523,-0.041668,-0.316490,-0.057540,0.335430,0.019056,-0.168280,-0.118158,-0.341969,-0.033234,0.011190,0.133056,0.212627,-0.390635,0.201049,-0.844132,0.228067,-0.203504,-0.491754,0.017587,0.051975,-0.393911,0.718941,-0.653147,-0.077427,0.414178,0.224395,-0.194738,0.713049,0.171354,-0.330631,-0.264625,-0.157741,0.148471,-0.070292,0.382577,0.183361,0.231030,0.072726,-0.148450,-0.534089,0.068702', '3266509', '3811356', '26365262', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1787291', '被嫌弃的松子的一生', '剧情', '有一天父亲（香川照之饰）突然来找阿笙（瑛太饰），告诉他有个素未谋面的姑姑死了，叫他去收拾下姑姑的房子。在河边的破烂小屋里，阿笙渐渐开始了解父亲口中的姑姑，到底有着怎样的一生。小时候的姑姑川尻松子（中谷美纪饰）经常做着白雪公主似的美梦，她后来成为一名安分的中学教师，却因百口莫辩的误会被辞退了，之后和一作家同居，作家却因为太爱她而选择自杀，死前留下遗言：生而为人对不起。这件事对松子打击极大；之后与该作家的事业敌人同居直至，又忍受不住去找对方妻子的诱惑，结果惨遭抛弃；又是当上浴室女郎，甚至还杀人入狱，然而不管有意无意，她从不放弃生活的希望。不管生活再怎样破碎，她仍然本能地生存下去，这生存本身，足以打动任何人，包括阿笙。©豆瓣', '中谷美纪', '中岛哲也', 8.9, 666046, 'tt0768120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p884763596.jpg', 0.4, 1.1, 9.1, 34, 55.4, '0.080259,-0.010552,-0.537214,0.418439,-0.233198,-0.400829,0.687713,0.143116,-0.311938,-0.353258,0.048033,0.656981,0.114040,0.301523,0.019231,0.032688,-0.180281,-0.509638,0.120766,-0.097975,-0.293681,-0.421760,0.033118,0.059457,-0.021336,0.099168,0.526419,-0.050566,-0.219274,0.105032,0.395362,0.258108,0.168490,0.445830,-0.084291,0.220397,-0.226630,0.201124,-0.229329,0.036491,0.375509,-0.181509,-0.093291,0.156065,-0.019247,0.197806,0.296154,-0.260906,-0.326519,-0.289915,0.371396,-0.170538,0.086898,0.213877,0.100845,-0.133983,0.224940,0.266011,-0.226341,-0.243924,0.167967,0.248562,-0.568574,0.014527,0.247570,0.024395,-0.688649,0.096426,0.030084,0.080956,0.120646,-0.300189,0.199328,0.389543,0.274082,0.343357,-0.436438,0.094485,-0.441077,0.207565,0.873310,-0.054253,0.017823,0.179634,-0.002111,-0.068535,0.317757,-0.430738,-0.572335,0.111963,-0.177751,0.166485,-0.514763,0.133550,-0.205425,-0.144835,-0.076336,-0.137344,0.111942,-0.621188,0.004286,0.143257,-0.184273,-0.118839,-0.281273,-0.037108,0.016783,-0.349613,0.651520,-0.683735,0.366086,0.538733,0.494585,-0.643343,0.561354,0.323961,0.089533,-0.048555,0.103765,0.309426,0.007927,0.228182,0.189763,0.117987,0.293918,0.025821,-0.346198,0.220524', '1877596', '25721544', '1296569', '4861627');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1788094', '轮回', '悬疑', '1970年，日本群马县某饭店发生疯狂杀人事件，某大学医学教授大森范久（治田敦 饰）狂性大发，杀害了包括年幼女儿在内的11人。在此之后，大森也自杀身亡，事件起因至今不明。35年后，人气恐怖片导演松村郁夫（椎名桔平 饰）决定将该事件改编成电影，搬上银幕。影片制作委员会举行了试听会，无数怀揣梦想的女孩来此应征。无名新人杉浦渚（優香 饰）也是众多候选人之一，她的独特气质引起了松村的关注，最终她被定为影片的女主角。在此之后，小渚经常做一些奇怪的梦，梦中她来到一所从未到过的红色房子。当她随摄制组来到发生凶案的旅馆之时，这里却让她有一种似曾相识的感觉……©豆瓣', '优香', '清水崇', 6.8, 8484, 'tt0456630', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p805807442.jpg', 1.4, 9.8, 47.9, 31.2, 9.8, '0.160900,-0.017770,-0.622770,0.198204,0.269306,0.077347,0.773671,0.055746,-0.635620,-0.588246,0.485444,0.701013,-0.614209,0.297974,0.396574,0.001333,-0.069765,-0.555449,-0.000597,-0.299073,-0.190942,-0.161999,-0.184255,-0.108108,-0.077144,-0.198715,0.643070,0.243518,-0.257744,0.295438,0.411206,0.388625,-0.136438,0.223377,0.063895,0.161767,0.207338,0.206898,-0.094688,0.214662,-0.173029,-0.355231,-0.299010,0.061519,0.005632,0.234355,0.769459,0.019055,-0.509115,-0.112586,0.510310,-0.107315,-0.231876,0.092254,0.332502,0.220282,0.180814,0.384231,-0.210670,-0.045292,0.005464,-0.092130,-0.529806,0.064311,0.305645,0.368714,-0.284137,0.141278,-0.010412,0.013414,0.143945,-0.301348,0.066854,0.011677,0.475092,0.296653,0.056944,0.101528,-0.312003,0.605142,0.869141,-0.230702,-0.179838,0.300669,-0.218771,-0.308102,-0.035096,-0.309006,-0.295483,0.460507,0.064235,-0.037896,-0.076640,0.090366,-0.436333,-0.424955,0.056742,-0.361818,0.202439,-0.169645,-0.043465,-0.587435,-0.171524,-0.200471,-0.277288,-0.197235,0.059837,-0.262624,0.714187,-0.811963,0.291910,0.671504,0.014412,-0.524352,0.444992,-0.104336,-0.202584,0.068435,0.077325,0.164297,0.027806,0.302742,-0.197377,0.276806,0.117913,-0.369646,-0.362411,0.186433', '3811356', '25721544', '35030151', '1301156');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1788431', '日本沉没', '剧情', '地球物理学家田所雄介博士（小林桂树 饰）带领自己的团队前往深海科考，却发现海底出现异常龟裂与乱泥流，在一系列调查之后，他得出来日本列岛在一年后即将沉没的结论。可是日本政府的官员们却认为田所博士的预测只不值得相信的谎言。只有山本首相（石坂浩二 饰）认识到事态的严重性，并且委任田所的前妻鹰森沙织（大地真央 饰）为危机管理大臣，带领田所博士和他们的团队设法拯救日本。很快，从北海道开始，日本诸岛先生发生大规模的地质灾害，整个日本陷入一片恐慌。政府对于灾害束手无措，仅有的海外移居政策完全不能应对急剧恶化的态势，日本诸岛完全沉没的现实即将上演。最终，田中博士和自己的科考队员们终于找到一个可以挽救日本的方法，但这个方法的实际操作却困难重重……此片改编自日本科幻小说家小松左京的同名畅销小说，该片斥资20亿日元，是近年来日本影坛投资最大、宣传最大的灾难片。©豆瓣', '草彅刚', '樋口真嗣', 6.4, 23484, 'tt0473064', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p656803775.jpg', 2.6, 13.2, 53.8, 24.4, 6, '-0.007233,0.097651,-0.771943,0.370337,0.216062,-0.157154,0.276133,0.076742,-0.491510,-0.400831,0.260611,0.685308,-0.091332,-0.099429,0.018525,-0.004761,-0.455873,-0.524644,-0.260356,-0.077971,-0.270076,-0.419398,-0.238285,-0.326914,-0.310157,-0.078318,0.918775,0.482745,-0.435186,0.328193,0.094658,0.531500,0.061173,0.297714,0.082068,-0.152976,0.237820,-0.130788,-0.478525,0.263172,-0.129818,-0.145377,-0.167680,0.201412,0.042996,0.401386,0.584863,-0.160592,-0.168833,-0.043222,0.464572,-0.522926,-0.159929,0.149721,0.425438,-0.044463,-0.093064,0.106125,-0.142678,-0.091704,-0.145023,-0.034444,-0.649809,-0.155526,0.132971,0.436018,-0.290638,0.072770,-0.010580,-0.178172,0.026632,-0.343610,0.039294,0.700132,0.306739,0.212960,-0.348677,0.236278,-0.398440,0.237489,0.714719,-0.142143,-0.407965,0.050882,-0.086280,-0.561190,-0.084843,-0.245476,-0.022301,0.068229,0.056424,0.018522,-0.251776,0.469728,-0.508756,0.064002,-0.375296,-0.638580,0.054885,-0.234256,-0.004183,-0.702049,-0.118891,-0.228958,-0.098718,-0.022848,0.319555,-0.111390,0.857506,-0.587452,-0.064160,0.495328,0.083453,-0.515969,0.243514,0.188683,-0.145511,-0.206450,-0.049956,0.086147,0.028769,0.598755,-0.236069,0.188950,0.197935,-0.450853,-0.296479,0.034785', '2369613', '6007281', '3861846', '1449328');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1788602', '蜜糖与调味：风味绝佳', '剧情', '高中毕业后，少年志郎（柳乐优弥饰）不顾父母阻挠，跑到加油站工作，支持自己的只有70多岁的奶奶（夏木マリ饰），奶奶的一言一行都非常西化，还有一个20多岁的男朋友（陈柏霖饰），她常常教给志郎恋爱的方法，但是爱情是什么，淳朴的志郎只是半懂不懂。一个雨夜，志郎在街上目睹了一个少女和恋人发生争执，少女泪光闪闪的模样显得可怜而无助，深深印刻在志郎的心里。有一天，加油站里来了打零工的大学生乃里（沢尻エリカ饰），竟然就是之前那个雨夜里的少女。恋爱的感觉一下子充满了志郎的全身，尽管乃里时时流露出的情绪都是因为前男朋友（高岡倉甫饰），志郎还是费尽心思讨好她。乃里渐渐被志郎的真诚打动，她接受了这份情意。初尝恋爱滋味，志郎每日与乃里如胶似漆得黏在一起，还约好了19岁就住在一起，可是有一天，乃里突然不告而别……©豆瓣', '柳乐优弥', '中江功', 6.9, 8296, 'tt0794373', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p769611165.jpg', 1.2, 9, 47.3, 30.7, 11.8, '-0.016142,-0.177006,-0.537017,0.446743,-0.315201,-0.453365,0.749644,0.047587,-0.293556,-0.059758,0.336838,0.547395,-0.263184,0.700075,0.208942,0.156263,-0.115057,-0.626286,-0.067724,0.004317,-0.112881,-0.466787,-0.083921,0.038679,-0.091714,-0.239658,0.591204,0.102518,0.132759,0.437497,0.338786,0.063461,-0.000992,0.564991,-0.165509,-0.096703,-0.015611,0.190524,0.090040,-0.182308,0.102632,-0.086198,-0.155394,0.030632,-0.081622,0.501053,0.556149,0.043744,-0.285265,0.280614,0.440208,-0.077228,-0.140580,0.181028,0.265405,-0.138903,0.360542,-0.112194,-0.222546,-0.102624,0.038292,0.048068,-0.278730,-0.028769,0.214462,0.234108,-0.494639,0.475840,0.127344,-0.223574,0.334539,-0.314042,0.051080,0.051232,0.052882,0.555208,-0.358034,0.008528,-0.378890,0.157613,0.536286,-0.008826,-0.087529,0.676268,-0.388805,-0.267927,-0.017329,-0.098461,-0.558907,0.002885,-0.281041,-0.136635,-0.399818,0.183472,-0.577036,-0.007144,-0.109268,0.098400,0.111933,-0.414230,-0.044895,-0.286081,-0.257333,-0.642490,-0.477989,0.243472,0.343356,-0.151544,0.705098,-0.835099,0.243300,0.460565,0.104132,-0.146952,0.607021,0.207293,-0.258391,-0.053054,-0.062508,0.241456,-0.283167,0.102913,0.115435,0.535572,-0.185492,0.086440,-0.400056,0.523521', '1292219', '1466907', '4275444', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1788940', '扶桑花女孩', '剧情', '1965年福岛县的煤矿小镇磐城，如今正面临着时代变革所带来的巨大冲击。石油能源逐渐成为主流，而煤资源则渐渐退出历史舞台。世代靠挖煤为生的磐城百姓开始感到生活的艰辛，镇上的煤矿相继关闭，失业不断增加。为了使小镇重新焕发活力，一个兴建“夏威夷娱乐中心”的计划旋即出炉。世代 居住于此的女高中生纪美子（苍井优 饰）得知娱乐中心招聘草裙舞演员的消息后，和好友一同前来应聘。然而暴露的服装却吓退了很多保守纯朴的女孩，最终只有只有纪美子、早苗、初子和小百合四人留下。在来自东京的舞蹈老师平山圆香（松雪泰子 饰）的指导下，这几个没有任何基础的女孩顶住各方压力，为早日成为优秀的草裙舞女郎而刻苦学习……©豆瓣', '松雪泰子', '李相日', 8.1, 26266, 'tt0768116', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1079104581.jpg', 0.2, 1.2, 21.4, 49.9, 27.3, '-0.076119,0.159696,-0.477475,0.462446,-0.016073,-0.041384,0.260826,0.287827,-0.483647,-0.325043,0.165668,0.667385,0.140348,0.347628,0.291998,-0.347144,-0.206587,-0.395366,-0.249484,-0.110519,-0.263493,-0.164342,-0.076551,-0.208651,-0.364802,-0.495358,0.861605,0.289057,-0.131237,0.495217,0.112703,0.212671,-0.228147,0.151917,-0.126836,-0.084854,0.166181,-0.082902,-0.353844,0.324966,-0.310708,-0.076850,-0.186931,-0.155299,0.159512,0.295043,0.742225,-0.059638,-0.134988,-0.460488,0.560723,-0.020739,-0.134539,-0.091720,0.275932,0.237450,0.246869,0.096389,-0.360636,-0.117462,0.189019,-0.391095,-0.682657,0.019931,0.579018,0.072631,-0.367180,0.392623,0.189139,-0.241808,0.060589,-0.419304,-0.003764,0.517529,0.267327,0.347116,-0.287887,0.297034,-0.221691,0.262812,0.713209,-0.059802,-0.252950,0.141874,-0.284241,-0.206833,0.140008,-0.245598,-0.280555,-0.231467,-0.033680,0.204022,0.057211,0.110978,-0.703177,0.059968,-0.141834,-0.542038,0.486504,-0.165916,-0.157050,-0.926986,0.014328,-0.174184,0.096210,0.261214,0.302646,-0.137319,1.014702,-0.794003,0.075329,0.401680,0.341770,-0.513898,0.486735,-0.388727,0.249545,-0.162075,-0.258652,0.209394,-0.069300,0.410600,-0.289305,0.164664,-0.538214,-0.354225,-0.338328,0.430783', '2369613', '3811356', '5403927', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1789283', '时空线索', '动作', '一艘货轮意外爆炸，特工道格（Denzel Washington 丹泽尔•华盛顿 饰）奉命前往调查。然而，当他到达现场时，却发现自己分明是第一次到这个地方，却对眼前的场景十分熟悉。道格经过缜密调查，发现了这起爆炸事件与自己有着密不可分的关系。他借助政府的时光实验室――这里可以获悉4天内任何地方发生的任何事件，发现了自己与一名神秘女子有着不同寻常的关系，而这名女子将导致未来的一场与自己有关的大灾难！道格必须回到过去，将历史从一个实相引向另一个实相才能阻止这场灾难的发生。©豆瓣', '丹泽尔·华盛顿', '托尼·斯科特', 7.8, 58110, 'tt0453467', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199287843.jpg', 0.3, 1.9, 26, 52.8, 19, '0.326001,0.292968,-0.891492,0.685163,0.093741,0.071700,1.156896,-0.264331,-0.705452,-0.581437,0.100120,0.838670,-0.272859,0.059725,0.517012,-0.023587,-0.221000,-0.759542,-0.109150,-0.346440,-0.545573,-0.454909,-0.340264,0.010208,-0.096250,-0.238637,0.663244,0.395227,-0.513230,0.340537,0.222756,0.571496,-0.335283,0.674461,-0.100144,-0.384699,0.016178,0.003320,-0.387203,0.208860,0.117542,-0.330557,-0.220414,0.356986,-0.188551,0.506713,0.576001,-0.550465,-0.687049,0.125162,0.484333,-0.217568,0.014461,0.096645,0.353939,0.074105,-0.248856,0.407295,-0.167332,-0.051070,0.207217,0.012726,-0.639506,0.101380,-0.016598,0.371736,-0.428760,0.043450,0.032739,-0.257819,-0.025548,-0.396790,0.414111,0.701219,0.415751,0.175155,-0.229822,0.055602,-0.524080,-0.287897,0.966127,0.133828,-0.362506,0.451749,-0.043934,-0.584667,-0.273683,-0.112415,-0.058118,0.410522,0.315799,0.134262,-0.058711,0.287214,-0.564597,-0.109686,-0.431610,-0.225072,-0.156212,-0.320336,-0.126379,-0.817498,-0.386733,-0.318308,-0.577964,0.175738,-0.072666,-0.291260,0.431781,-0.770579,0.047299,0.694667,0.183709,-0.447841,0.448355,0.004127,0.198960,-0.605527,0.000915,0.217016,0.109901,0.360581,-0.319473,0.369572,0.077796,-0.205558,-0.298501,0.291269', '25828589', '25909236', '1296534', '1300958');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1789292', '蠢蛋搞怪秀2', '喜剧', '暌违四年，疯狂恶作剧的爱好者们再度回归，继续诠释自毁式恶作剧的精髓。本纪录片倾情奉献来自恶作剧先进国家的成功经验。连环计：先向车里灌入蜂群再用滑珠迎接逃出来的车中人；顺手牵羊计：帮助公马自慰，得到的液体不好浪费，喝掉了事；偷梁换柱计：把鱼钩从脸上穿过，用人当鱼饵钓鲨鱼；假痴不癫计：化装成老年人各种戏弄无辜路人；打草惊蛇计：把蟒蛇藏在海洋球中与之肉搏；美人计：在粉丝情书后面安装了机关拳头来一个打一个；声东击西计：扑克牌结合电椅，令受害人完全不知痛感因何而来；最终大计瞒天过海：假恐怖分子遭遇假出租车司机，整人反被整……当然我们的恶作剧英雄们依然彪悍，血肉之躯对抗公牛、玻璃、铁夹、防暴武器、水蛭、铁耙，看的连你也肉疼！©豆瓣', '约翰尼·诺克斯维尔', '杰夫·特里梅因', 7.9, 7891, 'tt0493430', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456680704.jpg', 2.4, 4.1, 22.2, 38.2, 33.1, '0.008319,-0.197594,0.025619,0.149632,-0.087857,0.135997,0.471165,-0.090600,0.043378,-0.010625,0.308640,0.157914,-0.172603,-0.381049,-0.121510,-0.189717,-0.161960,-0.530767,-0.093571,0.120436,-0.327557,-0.012295,-0.194269,-0.181689,0.214502,0.021318,0.270646,0.042509,-0.274269,0.145168,0.430645,0.097737,-0.260134,0.049442,-0.170322,-0.218005,-0.398147,-0.218131,-0.010004,-0.002586,-0.160582,-0.322708,-0.067194,0.037538,-0.137392,0.136572,0.725440,-0.212602,0.240019,-0.080210,0.084819,-0.257950,-0.034746,0.047625,-0.042268,0.097632,-0.022964,-0.302287,0.034413,0.331927,0.412632,-0.024678,-0.595124,-0.217290,-0.459432,-0.199736,-0.310905,0.015386,-0.007502,0.182618,0.014524,-0.091281,0.248756,-0.198778,0.336246,0.299608,-0.261264,0.150082,-0.463226,0.122239,0.113105,-0.149637,-0.048642,0.140802,0.114118,-0.170967,0.271665,-0.409460,0.152840,-0.161795,0.565420,-0.188507,-0.333072,0.252898,-0.755750,-0.280365,-0.136213,0.120113,0.075229,-0.213595,-0.271811,-0.499877,0.169803,0.193721,0.088433,0.079091,0.258686,-0.045769,0.554460,-0.354708,-0.224024,0.455753,-0.088962,-0.384620,0.473062,-0.061431,-0.284911,-0.121117,-0.257983,0.067898,0.428450,0.466317,0.421536,0.301567,0.039063,0.041980,-0.312920,0.108084', '3262050', '4181031', '1292680', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1789492', '绷带', '剧情', '偶然的机缘，平凡女孩都筑麻子（北乃绮 饰）随好友来到了摇滚乐队Lands的演唱会现场。她们伪装成工作人员进入后台，并因意外结识了乐队的主要成员夏（赤西仁 饰）和健二（笠原秀幸 饰）。夏似乎对麻子颇有好感，因此邀请她参加乐队的庆功会。不过，美丽冷艳的乐队经理Yukari（伊藤步 饰）并不喜欢无关人士过多地参与进来，她与夏针锋相对，令麻子不知所措。数日后，Yukari因病住院，麻子借此机缘成为了Yukari的助理，二人携手打理关于Lands的所有繁杂事务。在向着理想和成功迈进的道路上，这群年轻人们却要切身体会着来自梦想和现实的巨大撕裂感……本片由著名音乐制作人小林武史执导，导演岩井俊二担任编剧。©豆瓣', '赤西仁', '小林武史', 7.3, 10053, 'tt0482459', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p541703269.jpg', 1.4, 7.1, 35.5, 35.8, 20.1, '0.000921,-0.001450,-0.436977,0.303124,-0.028347,-0.195903,0.560255,0.422543,-0.631838,-0.448071,-0.029087,0.485744,-0.164932,0.149431,0.443376,-0.291857,-0.259549,-0.655055,-0.179518,-0.130331,0.014697,-0.302667,0.157795,-0.371211,0.022765,-0.366569,0.661996,0.165740,-0.381672,0.693367,0.544484,0.244243,-0.395209,0.378950,0.164272,-0.022497,0.192324,0.206432,-0.525509,-0.015071,-0.354763,-0.142634,-0.172367,-0.109473,0.104901,0.308986,0.494813,-0.228226,-0.241319,0.091675,0.297027,-0.196758,0.063750,0.127131,0.250474,0.197408,0.405529,0.235547,-0.046013,0.125989,-0.058790,-0.340280,-0.648868,0.215491,0.340295,0.261488,-0.567333,0.577597,0.105562,-0.137175,0.041038,-0.042274,0.334141,0.252233,0.190794,0.055056,-0.002495,0.254636,-0.157968,0.488913,0.775446,0.329266,0.139721,0.176120,-0.293472,-0.535852,-0.282562,-0.077568,-0.289772,0.215694,0.108619,0.024384,0.282653,-0.209650,-0.538988,-0.061326,0.071245,0.028062,0.032682,-0.339274,0.254242,-0.819809,0.147494,-0.363212,-0.174589,-0.186783,0.096029,-0.307258,0.784919,-0.818070,0.015547,0.361039,0.304472,-0.352292,0.691392,0.011216,0.035794,-0.441130,-0.365297,0.064862,-0.057624,0.309396,0.008561,0.382223,-0.150039,-0.418889,-0.312185,0.003750', '1316589', '3811356', '35030151', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1790577', '放·逐', '惊悚', '澳门回归前三天，五位情深意重的杀手。杀手阿和(张家辉饰)与妻子阿静(何超仪饰)带着刚满一个月的孩子重返故地，阿火(黄秋生饰)与阿波(林雪饰)奉黑社会老大大飞(任达华饰)的命令来追杀阿和，但另一对好兄弟阿泰(吴镇宇饰)与阿猫(张耀扬饰)闻讯，为了情义前来阻止。冲突在阿和家突然爆发，又迅速重归平静。最后他们决定一起做一宗大买卖来解救阿和，在谢夫(张兆辉饰)那里，摆放在他们眼前的是两个选择：暗杀蛋卷强(林家栋饰)或者抢夺一吨黄金……最终他们选择了前者，然而却在餐厅和死对头大飞不期而遇，一场恶战难免。©豆瓣', '黄秋生', '杜琪峰', 8.2, 115360, 'tt0796212', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p665486282.jpg', 0.3, 1.8, 17.8, 46.9, 33.1, '-0.132777,-0.072857,-0.563877,0.477939,0.152076,-0.355271,0.655265,0.378057,-0.171293,-0.282085,0.262677,0.710738,-0.048934,-0.025804,0.185251,-0.300131,-0.285793,-0.534335,-0.043764,-0.196010,-0.170808,-0.368893,-0.169414,-0.207863,-0.064369,0.035926,0.462347,-0.144946,-0.071488,0.795702,0.810766,0.170741,-0.381567,0.316522,-0.093566,-0.112264,-0.035178,0.247030,-0.626725,0.158656,-0.147533,-0.129964,-0.347780,0.077962,0.290652,0.365093,0.618282,-0.431142,-0.008924,-0.089395,-0.082061,-0.266835,-0.075422,-0.055359,0.386396,0.028045,0.298655,0.180912,-0.188666,-0.111925,0.302552,-0.022032,-0.418013,0.073917,0.310573,0.020346,-0.687921,0.330293,-0.021927,-0.040053,0.276655,-0.080808,0.161283,0.536137,0.339922,0.227846,-0.010353,-0.105243,-0.470017,0.085355,0.690669,-0.061113,0.362030,0.018323,0.191952,-0.567564,-0.086989,-0.179144,-0.312260,-0.020273,0.363405,-0.145421,0.140085,0.172765,-0.631840,-0.187396,-0.117266,0.242190,-0.066067,-0.317775,0.342610,-0.574248,0.045370,-0.281146,-0.211379,0.438973,0.106960,0.104402,0.589992,-0.590797,0.148400,0.214776,0.479853,-0.514464,0.555913,0.300298,0.123431,-0.467935,-0.103349,-0.213992,0.243956,-0.021399,0.420652,0.198382,-0.152165,0.175061,-0.210009,0.004979', '2084048', '2976123', '1897368', '6858739');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1790754', '恋爱刺客', '喜剧', '约翰•塔克（杰西•麦特卡尔菲 饰）是学校里面的风头人物，深受女孩子的欢迎，他也乐在其中。不久，他的三位美丽的女友嘉丽、希瑟、贝丝发现了自己的男友都是约翰。感到晴天霹雳的三人决定一争到底，但最后都躲不过被约翰抛弃的命运。本是敌人的她们伤心过后决定联合起来一起对付约翰，惩罚他的花心之举。可是她们的计划在约翰身上并不奏效。这时善良单纯的凯特（布兰特妮•斯诺 饰）成为了她们报复约翰的工具，凯特虽然心里不太愿意，因为她需要诱惑约翰，之后再让他品尝失恋之苦。可是她也希望能走进三位校花的生活圈子中，便同意了。果然，约翰对打扮后美得不可方物的凯特动心不已，竟变了个人似的对凯特的感情专一认真。凯特本来想自己的任务即将完成，可是却发现自己真的爱上了约翰……©豆瓣', '杰西·麦特卡尔菲', '贝蒂·托马斯', 6.4, 13081, 'tt0455967', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1208829877.jpg', 1.7, 10.6, 60.6, 22.2, 4.9, '0.507682,-0.045757,-0.639661,0.316898,-0.252822,-0.520214,0.623961,0.057898,-0.451176,-0.202016,0.018483,0.610246,-0.171039,0.282648,0.167770,0.228104,-0.530293,-0.643320,0.114235,-0.172343,-0.004160,-0.467000,-0.106550,-0.394312,-0.074456,-0.228455,0.452506,-0.025843,0.065549,0.355250,0.455175,0.360835,0.353121,0.599729,0.183152,-0.034881,0.204903,-0.054221,-0.225294,0.123342,0.108633,0.023623,-0.080660,0.656300,0.080117,0.374150,0.249976,-0.247901,-0.121301,-0.058532,0.121779,-0.313784,0.132421,0.180316,0.075993,-0.281283,0.263325,0.093145,0.045559,-0.032065,0.145616,-0.001125,-0.571539,0.257160,0.091061,0.060228,-0.508499,0.282119,-0.183526,0.031398,0.011387,-0.335503,0.009640,0.203368,0.441741,0.276133,-0.203234,0.066064,-0.435434,-0.012848,0.682533,0.083150,-0.052789,0.362564,-0.417593,-0.529517,-0.007437,-0.180834,-0.545523,-0.019928,0.176638,0.217023,-0.080710,0.147676,-0.375174,-0.133602,-0.432698,0.005745,-0.208848,-0.558623,0.099165,-0.397132,-0.132778,-0.457161,-0.597748,-0.208203,-0.006197,-0.392673,0.579984,-0.896954,0.170652,0.593897,0.305521,-0.551622,0.616911,0.410383,-0.041483,-0.116700,-0.089305,0.377528,-0.118215,-0.058571,0.186679,0.336026,0.276729,-0.225210,-0.296088,0.599908', '1308755', '7065238', '1301022', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1792917', '贝奥武夫', '动作', '在英国撒克逊人长篇史诗《贝奥武夫》的描述中，主人公贝奥武夫（雷·温斯顿 Ray Winstone 饰）是一位拥有强健体魄和惊人战力的武士，他一身将经历三场对其影响重大的战役。为了拯救被巨人格兰戴尔（克利斯丁·格拉夫 Crispin Glover 饰）掠夺的村庄，贝奥武夫带领一群武士渡过海洋向其挑战。在一场浴血奋战之后，格兰戴尔被武士们所击败。但是战斗却没有结束，格兰戴尔的母亲（安吉丽娜·朱莉 Angelina Jolie 饰）为了复仇向贝奥武夫发起了挑战。一场更大的战役即将打响。虽然这次，勇士们将付出更加惨痛的代价，但是在无所畏惧的贝奥武夫面前，即便是再厉害的对手，也将被毁灭。多年后，与一条恶龙的终极之战，最终将贝奥武夫的名字变成了不朽的传奇。©豆瓣', '雷·温斯顿', '罗伯特·泽米吉斯', 6.7, 30397, 'tt0442933', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165572589.jpg', 1.8, 10.2, 47.6, 30.7, 9.7, '0.094173,0.082547,-0.568533,0.701839,0.101992,-0.192760,0.731081,-0.101609,-0.301355,-0.251806,0.211615,0.899945,-0.232579,0.041276,0.404635,-0.319085,0.107378,-0.733771,-0.305294,0.083096,-0.406382,-0.543787,-0.311346,0.063984,-0.190565,-0.635669,0.689895,0.136910,-0.370623,0.380322,0.577943,0.403797,0.294642,0.286823,0.074084,-0.185171,0.076614,-0.184790,-0.233197,0.254045,-0.046073,-0.268298,-0.116947,0.452031,-0.048874,0.068638,0.750763,-0.773000,0.263794,-0.323435,0.326651,-0.347357,0.301561,0.447721,0.228146,0.014772,-0.077153,0.383002,0.062270,-0.080663,0.088863,-0.401684,-1.229675,-0.173245,0.140625,-0.108480,-0.642449,0.433833,-0.015690,0.149929,0.024105,0.054832,-0.071485,0.522114,0.461423,0.389992,-0.179383,-0.093169,-0.502559,0.016575,1.013329,-0.058905,-0.359101,0.024975,0.075128,-0.459394,-0.250837,-0.583963,-0.505279,0.200973,0.480839,0.034671,0.262429,0.365135,-0.770409,-0.179711,-0.763934,-0.466694,-0.008765,-0.086528,-0.199077,-0.501449,-0.177811,-0.332703,-0.278035,0.241505,0.123579,-0.358847,1.030803,-0.862947,0.114341,0.305055,0.383181,-0.248580,0.459079,-0.079894,0.353960,-0.043637,0.225509,0.537697,0.314737,0.202145,0.398548,0.199876,-0.159360,0.018627,-0.112577,0.723184', '27602116', '26678784', '1874704', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1792922', '梦女孩', '剧情', '60年代的底特律，3个黑人女孩蒂娜(碧昂丝•诺尔斯 Beyonce Knowles 饰)、埃菲 (詹妮弗•哈德森Jennifer Hudson 饰)和劳莱尔(阿尼卡•诺尼•罗斯Anika Noni Rose 饰)组成了“梦想”组合，一心要在选秀赛中开拓歌唱生涯。然而，比赛结果却令她们大失所望，柳暗花明的是，她们被经纪人柯蒂斯（杰米·福克斯 Jamie Foxx 饰）看中，雄心壮志的要把她们打造成受市场欢迎的流行歌手。于是，三个女孩的开始踏上充满未知的星途。柯蒂斯为他们设计了一整套方案，跟大牌歌手的舞台上表演和声，然后把重新定位组合中三个人的角色，让她们独立演出——歌喉最好但外形不足的埃菲被撤掉主唱的位置，而相貌出众的蒂娜则担当主唱。这使得组合内部掀起了风暴。三个歌手之间的关系开始在成名路上变得不再单纯， 埃菲和柯蒂斯之间的恩怨也在纠缠交织。©豆瓣', '杰米·福克斯', '比尔·康顿', 7.7, 17763, 'tt0443489', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2523971891.jpg', 0.4, 2.1, 28.9, 48.1, 20.5, '0.486012,0.029498,-0.481291,0.678808,-0.027403,-0.207178,0.616096,0.227876,-0.372364,-0.085033,0.027968,0.778469,-0.453448,0.046886,0.283987,-0.179365,-0.263064,-0.872733,-0.017143,-0.183328,-0.075236,-0.496794,-0.004079,-0.123510,-0.288720,-0.348180,0.826553,-0.255504,-0.136995,0.472472,0.537643,0.167121,0.024863,-0.003109,-0.009918,-0.149196,0.236633,-0.041039,-0.229920,0.419252,-0.158622,-0.031685,0.007195,0.212567,0.014875,0.261795,0.705121,-0.167228,0.361597,-0.122085,0.357245,-0.023725,0.108411,0.178754,0.143622,0.037194,0.248470,0.115465,-0.146996,-0.073989,0.095215,-0.301128,-0.613329,0.306197,0.353278,0.064365,-0.543701,0.507825,-0.061948,-0.282202,0.014986,-0.130808,0.148039,0.268675,0.584480,0.270334,0.099589,0.061993,-0.264824,0.060640,0.700445,0.097185,-0.340256,0.306150,-0.269113,-0.341605,-0.365644,-0.228190,-0.529751,-0.064332,0.278872,-0.012417,0.268280,0.028377,-0.908157,0.074447,-0.050056,-0.224738,-0.137941,-0.471061,0.060330,-0.711434,-0.218211,-0.302423,-0.246140,-0.008090,-0.010367,-0.183286,0.845436,-0.779400,0.007544,0.374443,0.236513,-0.265492,0.607959,0.086901,0.373231,-0.243122,-0.217906,-0.014417,-0.096259,-0.139737,0.015641,0.521215,-0.271341,-0.172848,-0.485050,0.403259', '3811356', '25880986', '4301278', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1792928', '金刚狼', '动作', '1845年，尚年幼的维克多与詹姆斯兄弟俩在长辈之间一场突如其来争执中唤醒了自身的潜能，詹姆斯情急之下将陌生的生父杀死，自此兄弟两人流落战场，他们凭借不死不衰之身和野兽一般的天赋在各个时代的战争中大开杀戒，直到遇见史崔克少校并加入了他的异能人特殊部队。詹姆斯（休·杰克曼 Hugh Jackman 饰）很快厌倦了对弱势者的杀戮，离开了团队和维克多（列维·施瑞博尔 Liev Schreiber 饰），与女友凯拉隐居在山林中，做了一名伐木工人。六年后，詹姆斯惊闻昔日的超能力队友纷纷被杀害，而杀手正是哥哥维克多，不久连凯拉也遭其毒手，愤怒的詹姆斯与史崔克合作，将自己的身体改造，成为钢筋铁骨的“金刚狼”。金刚狼摆脱军方控制后，发誓要杀死维克多和史崔克为凯拉报仇……©豆瓣', '休·杰克曼', '加文·胡德', 7.5, 261225, 'tt0458525', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2063167557.jpg', 0.4, 2.9, 33.3, 45.9, 17.6, '0.086223,0.081405,-0.705754,0.473699,-0.185960,-0.290843,0.575145,-0.041802,-0.556680,-0.318808,0.168616,0.894756,-0.048943,0.127810,0.260290,-0.309719,0.035964,-0.753718,-0.026677,-0.080237,-0.350680,-0.438515,-0.277715,-0.336430,-0.116028,-0.755498,0.610952,-0.128904,-0.284480,0.538452,0.198223,0.367945,-0.044553,0.391893,-0.084537,0.208221,0.156886,-0.290820,-0.323768,0.258381,-0.041525,-0.060578,0.035216,0.079022,-0.152246,0.187903,0.642508,-0.570584,0.108272,-0.456144,0.195432,-0.326707,-0.096068,0.246750,0.508135,-0.279743,0.106168,0.448963,-0.007067,0.099271,-0.125855,0.048566,-0.744437,-0.121330,0.061939,-0.158988,-0.701368,0.402103,0.011017,0.146552,0.040918,0.044864,0.144654,0.355600,0.247560,0.265033,-0.119459,-0.111920,-0.508977,-0.036311,0.677548,-0.247143,-0.242757,0.048945,-0.035402,-0.384713,-0.200128,-0.303875,-0.421857,-0.216731,0.461894,0.096287,-0.275499,0.488581,-0.442439,-0.227789,-0.594039,0.194208,-0.180103,-0.347813,-0.004731,-0.639570,-0.147629,-0.381402,-0.073641,0.028101,0.006610,-0.227273,0.623490,-0.877799,0.255407,0.457381,0.374212,-0.304440,0.360890,-0.183603,0.445502,-0.103337,0.035074,0.346904,0.455595,0.251518,0.338461,0.281038,-0.061885,0.159304,-0.155424,0.482759', '1309069', '1303034', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1792933', '查理·威尔森的战争', '剧情', '查理（汤姆•汉克斯 Tom Hanks 饰）被美国国防部授予了反战间谍英雄的称号，因为他跟其他的谍报人员——乔安妮（朱莉娅•罗伯茨 Julia Roberts 饰）与盖斯特（菲利普•塞默•霍夫曼 Philip Seymour Hoffman 饰）一起为前苏联的解体、柏林墙的倒塌都做出了重要贡献。查理具有光鲜身份，他身兼国防部、政府、CIA等多方角色，终日周旋于商界政要之间，美色金钱纷至沓来，谁都希望借助他的能量满足一己私利。他关注阿富汗战争的局势，并且跟巴基斯坦的军方也通了气。其实，他所做的都是为了美国的利益，在红颜知己乔安妮与性格伙伴盖斯特的帮助下，他们导演了这场充满了传奇色彩的间谍战争……©豆瓣', '汤姆·汉克斯', '迈克·尼科尔斯', 6.6, 8614, 'tt0472062', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p937737495.jpg', 1.7, 10.1, 50.2, 30.2, 7.8, '0.138367,-0.031202,-0.690260,0.687407,-0.169640,-0.265986,0.441726,0.195084,-0.329204,-0.092180,0.158001,0.820395,-0.077093,-0.096071,0.105345,-0.118865,-0.667789,-0.961418,-0.019998,0.091968,-0.056379,-0.548589,-0.451137,-0.418840,-0.300042,-0.281537,0.492825,0.081926,-0.256107,0.168730,0.363998,0.321354,0.172129,0.427259,0.285622,-0.086197,0.273637,-0.172016,-0.560889,-0.042762,0.080111,-0.194432,0.026284,0.428988,0.137214,0.325402,0.243078,-0.398808,0.204219,-0.263607,0.172232,-0.368591,0.422501,0.183255,0.247632,0.029903,0.142408,0.284880,-0.100369,-0.030806,0.407534,0.217141,-0.837214,-0.017226,0.059404,0.107874,-0.282432,0.749581,-0.268268,-0.035467,-0.027702,-0.151869,0.210168,0.658146,0.308560,0.078683,-0.180796,0.194835,-0.431288,0.324642,0.521137,-0.037046,-0.414597,0.094899,-0.449139,-0.463013,-0.120175,-0.356342,-0.303878,-0.369445,0.443101,-0.282852,0.342867,0.454602,-0.633137,-0.169371,-0.120877,-0.140755,-0.023232,-0.414411,0.063712,-0.698470,-0.394693,-0.676014,-0.251355,-0.076956,0.397221,-0.229547,0.900604,-0.623743,-0.038606,0.536159,0.308777,-0.657446,0.636567,0.060805,0.259884,0.007402,-0.092086,0.243735,0.059483,0.166149,0.156720,0.182364,0.252620,-0.165902,0.037862,0.359063', '4301278', '27602116', '30162520', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793200', '我的父亲，我的儿子', '剧情', '无政府主义记者Sadik（菲克雷特·库斯坎 Fikret Kuskan 饰）在一次军事政变当天，因为无法把临盆妻子及时送去医院而导致妻子失血过多去世。儿子Deniz刚出生他就被送进了监狱受尽了折磨。出狱后的Sadik新生活没过多久，为了儿子他带着一个秘密回到了早已断绝关系的父母家。父亲Huseyin（Çetin Tekindor 饰）因为Sadik当年没有听自己的话学习农业而无法原谅他。母亲竭尽全力修复着父子俩的关系。就在一家人逐渐磨合快要看到曙光的时候，Sadik的秘密像道晴天霹雳再次打翻了宁静的生活。©豆瓣', '切邓·泰肯多尔', '查恩·厄尔马克', 8.9, 18760, 'tt0476735', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1975027048.jpg', 0.3, 1, 8.2, 32.4, 58.1, '-0.106844,0.050926,-0.701471,0.487725,-0.311663,-0.638286,0.804668,0.433389,-0.754105,-0.264048,-0.074382,0.859681,0.055532,0.483537,0.116403,-0.031755,-0.307383,-0.734538,0.081708,-0.323306,-0.420666,-0.457577,0.405345,-0.305093,0.035391,-0.534227,0.435479,-0.061320,0.056427,0.285511,0.010994,0.265018,-0.002852,0.570439,-0.520340,0.124849,0.038887,0.073040,-0.441516,0.413197,0.413377,-0.195941,0.046265,0.261648,-0.035988,0.220600,0.540808,-0.285063,-0.170489,-0.422310,0.274964,-0.340274,-0.105709,0.400705,0.312067,-0.068997,0.384081,0.173293,-0.532603,-0.084419,0.158077,-0.292457,-0.573035,0.017503,-0.105284,0.023627,-0.803638,0.610484,-0.177267,0.098186,0.282477,-0.450631,0.457632,0.613889,0.123130,0.717888,-0.494726,0.134470,-0.530308,0.212231,0.887753,-0.431493,0.125281,0.629493,-0.209466,0.029808,0.291129,-0.266095,-0.608201,0.131907,0.484617,0.236746,-0.623520,0.292324,-0.041741,-0.282329,-0.373980,-0.388348,0.039740,-0.400159,-0.058154,-0.238276,-0.247123,-0.043246,-0.340244,0.180704,-0.178149,-0.042902,0.528834,-0.684625,0.679053,0.349595,0.463512,-0.645379,0.486380,0.053731,0.151980,-0.284708,0.548981,0.313269,-0.024093,0.529278,0.472857,0.144904,-0.069222,-0.025149,-0.370783,0.622924', '26245360', '1299965', '4861627', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793491', '美食总动员', '喜剧', '小老鼠雷米在嗅觉方面有着无与伦比的天赋，不想过与垃圾堆为伴的生活，心怀成为五星大厨的梦想。一个偶然的机会，他认识了古斯特餐厅的学徒林奎尼，这个倒霉的学徒生性害羞，在厨艺上更是没有什么天赋，并且遭到餐厅大厨的排挤，即将被解雇。这一人一鼠结成了奇特的联盟：雷米奉献自己极富创造力的大脑。操作林奎尼前台“表演”。在雷米的帮助下，林奎尼不但成为新的“天才厨师”，获得了美女同事的爱情，还挫败了大厨的阴谋，成为古斯特餐厅的合法继承人。突如起来的成功让林奎尼有些不知所措，想摆脱自己的傀儡身份，把雷米赶出了厨房。古斯特餐厅的成功，引起了苛刻的美食评论家科隆的注意，准备一尝林奎尼的手艺，重新为餐厅评定星级；而不甘失败的前大厨，蠢蠢欲动，想要找到林奎尼一夜成名的秘密。失去了雷米，林奎尼该如何面对这些问题……©豆瓣', '帕顿·奥斯瓦尔特', '布拉德·伯德', 8.5, 342429, 'tt0382932', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p465604496.jpg', 0.1, 0.6, 13, 46.4, 39.9, '0.422474,0.216141,-0.529398,0.590010,-0.315250,-0.324781,0.527988,0.469038,-0.665350,-0.251053,0.226401,0.837292,-0.207992,0.180297,0.353792,-0.083707,0.038748,-0.514171,0.035477,-0.186146,-0.226009,-0.310667,-0.376879,-0.181658,-0.157210,-0.399203,0.656487,-0.014323,-0.276283,0.224518,0.229916,0.093226,0.242362,0.282999,-0.219395,0.151506,0.517765,-0.165565,-0.305894,0.227592,-0.057737,-0.062559,-0.033995,0.145645,-0.025831,0.127311,0.384388,0.096608,-0.350996,-0.167257,0.425340,-0.205995,-0.012440,0.207828,0.359073,0.065614,0.055466,-0.029832,0.057677,0.040446,0.050497,0.088431,-1.350189,-0.148639,0.317007,-0.198722,-0.690387,0.367337,-0.089876,-0.106293,0.030722,-0.305735,-0.105062,0.230685,0.332902,0.406064,0.007704,0.267139,-0.666736,0.083670,0.644952,0.022409,-0.148556,0.368971,-0.127564,-0.577699,0.064158,-0.522372,-0.399418,-0.128195,0.235131,0.250099,-0.004219,0.170268,-0.650006,0.033978,-0.257708,-0.288131,0.134166,-0.294977,-0.076392,-0.652916,-0.126711,-0.093996,-0.326264,-0.118788,0.115292,-0.299725,0.858408,-1.026970,0.237351,0.564778,0.333011,-0.350247,0.659864,-0.099319,0.147980,-0.022533,-0.299166,0.017236,0.129174,0.236056,0.036958,0.506498,0.089272,-0.271421,-0.405042,0.499800', '27098364', '30163500', '1874704', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793671', '疯狂店员2', '喜剧', '距上一集约十年后，一场大火将但丁（布莱恩·奥哈罗兰 Brian O''Halloran 饰）所在的便利店付之一炬，他本人也被老板扫地出门。在此之后，他和好哥们兰度（杰弗·安德森 Jeff Anderson 饰）到一家名为“Mooby’s”的快餐店打工，这里有一个狂迷魔戒、还带着点儿gay倾向的店员埃里亚斯（Trevor Fehrman 饰），以及和但丁始终大玩暧昧、纠缠不清的女主管贝姬，当然还少不了毒品贩子二人组杰（Jason Mewes 饰）和沉默鲍勃（Kevin Smith 饰）。这群人凑在一起，每天插科打诨，互相攻讦，过着无忧无虑混吃等死的逍遥日子。年过三十，即使再怎样玩乐的人也希望安定下来。但丁认识了一个富家女，未来岳父许诺只要和其女儿来佛罗里达结婚，便会赠送一个洗车店。这对始终辛苦打拼的但丁来说无疑天上掉馅饼，不过，这也意味着他要离开一众好友，结束这样简单快乐的生活……本片荣获2006年艾丁堡国际电影节观众奖、2007年MTV电影奖最猛粗口时刻。', '布莱恩·奥哈罗兰', '凯文·史密斯', 7.3, 8287, 'tt0424345', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2580288942.jpg', 1.8, 6.2, 34.7, 39.2, 18.1, '0.086311,-0.118405,-0.509530,0.316202,0.097476,-0.299409,0.632238,0.077123,-0.224447,-0.145589,-0.129719,0.745688,-0.402243,0.348924,0.478567,0.123662,-0.325191,-0.405312,0.001126,-0.106545,-0.054143,-0.209117,-0.054865,-0.206332,-0.146531,-0.005762,0.161065,0.010422,0.284789,0.532791,0.447236,0.081094,0.172906,0.376823,-0.161406,0.035188,0.069022,0.168545,-0.435728,0.180360,0.096583,-0.240448,-0.115264,0.013655,0.340896,0.046083,0.372364,-0.104243,-0.150960,0.204780,0.146109,-0.289578,-0.213366,-0.079919,0.182229,-0.208284,0.266952,0.305694,-0.204703,0.154576,-0.042166,-0.137682,-0.516509,0.075763,-0.047685,-0.154151,-0.483795,0.646792,0.166554,0.139013,-0.132602,-0.200535,0.186050,0.266580,0.220104,0.224292,-0.221726,0.091389,-0.532803,0.418968,0.595087,-0.080327,-0.172631,0.272057,0.011113,-0.403610,0.014437,-0.199346,-0.481664,-0.070093,0.186139,-0.081177,-0.043950,-0.002663,-0.536663,0.150719,-0.039325,-0.220021,0.216613,-0.337359,-0.097674,-0.546397,-0.063350,-0.462824,-0.447929,0.165241,0.053093,-0.259972,0.632543,-0.458467,0.168060,0.484686,0.310766,-0.504194,0.656358,0.133999,0.200027,-0.092615,-0.230479,0.181214,0.145459,0.105764,0.179512,0.327025,0.0