INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793903', '幻影凶间', '悬疑', '根据著名作家史蒂芬·金同名小说改编。恐怖小说家麦克（约翰·库萨克 饰）喜欢带着科学设备到闹鬼的地方探险，以收集写作素材。这次他选择了海豚酒店，不顾酒店经理（塞缪尔·杰克逊 饰）的强烈劝阻，住进了曾有多名住客自杀的1408号房间。麦克如愿以偿的经历了很多恐怖事件，彻底改变了他之前对灵异现象的看法。当他终于承受不住一波一波的恐怖攻击，准备离开1408号房间时，最恐怖的事情发生了：他用尽办法也无法离开。©豆瓣', '约翰·库萨克', '米凯尔·哈弗斯特罗姆', 7.6, 152863, 'tt0450385', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p887024730.jpg', 0.6, 3.6, 31.2, 45.2, 19.4, '0.301455,-0.103494,-0.679938,0.335826,0.157913,0.012989,0.863132,-0.032394,-0.517506,-0.423592,0.240156,0.618768,-0.182048,0.107241,0.219894,-0.090891,-0.329810,-0.407619,0.057720,-0.235065,-0.389023,-0.452003,-0.116369,-0.257887,0.109329,-0.290751,0.094269,0.122181,-0.379413,0.364380,0.338901,0.414083,0.061957,0.565972,0.061962,0.001248,0.168115,0.084413,-0.244016,0.168319,0.283897,-0.165071,-0.185528,0.223723,0.194149,0.125458,0.383636,-0.321043,-0.332428,0.099139,0.456835,0.079648,0.032212,0.091603,0.272755,0.121347,0.153663,0.219681,-0.163326,0.126304,0.050272,0.064375,-0.775255,-0.027442,0.057907,-0.065300,-0.353920,-0.012538,-0.278254,0.115997,0.135016,-0.499998,0.070279,-0.008190,0.410293,0.242392,0.000110,0.026462,-0.292454,0.291158,0.655582,0.022650,-0.268267,0.261063,-0.167199,-0.282470,-0.360136,-0.095960,-0.269911,0.266648,0.454217,0.291412,-0.241528,0.006176,-0.571345,-0.267774,-0.065060,-0.527178,-0.071327,0.006970,-0.117191,-0.764002,-0.213017,0.243826,-0.010919,0.084568,-0.098445,-0.150634,0.609050,-0.558644,0.264635,0.644505,0.296710,-0.599173,0.572633,-0.218541,-0.240588,-0.125982,0.193012,0.264848,-0.132962,0.583902,0.252190,0.477715,0.165055,-0.371982,-0.324613,0.661309', '3005387', '1301686', '10466639', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793904', '决战犹马镇', '剧情', '丹•埃文斯（克里斯汀·贝尔 饰）在南北战争断了一条腿，得到政府小小的补偿，他和妻子艾丽丝还有两个儿子在亚利桑那的农场居住。然而，恶劣的气候和腐败之风却让丹负债累累，一些人想在建造铁路上获得暴利，他们想尽办法赶走埃文斯一家，家人开始质疑丹的能力。就在此时，西部声名狼藉罪犯 宾•维德（罗素·克劳 饰）被捕获。他曾带领着副手查理•普林斯（本·福斯特 饰）和一帮手下驰骋荒野，劫得大量财物并犯下无数命案。被逮捕的宾•维德将由押送队带到康坦森镇，搭上火车他会被送到亚利桑那州的犹马镇，在那里接受联邦法庭的公开审判。为了拯救农场和家人，丹自愿参加了押送队，但即使被束缚，宾·维德仍然是危险的。在旅程中，押送队不断折损。当火车到来之时，一切会发生什么改变？©豆瓣', '罗素·克劳', '詹姆斯·曼高德', 8, 39373, 'tt0381849', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p443323143.jpg', 0.7, 2.2, 20, 50.2, 26.9, '0.269176,0.123739,-0.671963,0.391882,-0.084517,0.072802,0.540423,0.195866,-0.480310,-0.170717,0.124961,0.818566,0.025697,0.079533,0.290913,0.094694,-0.291580,-0.575569,0.085528,-0.087089,-0.379778,-0.556894,-0.078269,-0.275374,-0.031421,-0.517253,0.662907,0.147892,-0.128774,0.500832,0.229223,0.446444,-0.082049,0.239119,-0.257889,0.025770,0.505058,-0.301703,-0.193536,0.310705,-0.309433,-0.168979,0.027843,0.071210,0.332405,0.238701,0.686611,-0.183615,-0.057434,-0.046313,0.010732,-0.349722,0.376926,0.171559,0.217994,-0.064357,0.047492,0.502481,-0.412781,0.114214,0.244430,-0.213861,-0.800522,-0.108051,-0.115876,0.066950,-0.766363,0.422208,-0.116162,0.142053,-0.110189,-0.243048,0.341778,0.601620,-0.252149,0.257334,-0.174567,-0.252599,-0.734963,-0.006919,0.741656,-0.365191,0.005566,-0.075238,-0.169235,-0.212674,0.079571,-0.257837,-0.267010,-0.178704,0.372329,-0.144335,-0.010902,0.231422,-0.449776,-0.018051,-0.400684,-0.344027,0.154491,-0.309764,-0.049112,-0.603596,0.279470,-0.115281,-0.292915,0.298225,0.222253,-0.220148,0.341928,-0.618109,0.279204,0.570986,0.275739,-0.588638,0.349708,0.028615,0.244627,-0.085989,-0.160196,0.287381,0.505938,0.423766,0.334928,0.078012,0.102705,-0.121340,-0.259252,0.393802', '26678784', '1309069', '3215099', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793909', '预见未来', '动作', '尽管很多人觉得拥有超能力是一件好事，但事实却偏偏和想象中相反。克里斯（尼古拉斯•凯奇 Nicolas Cage 饰）天生具有预测未来的能力，但他从小就在痛苦中度过：各种机构、政府、医院都对他极感兴趣，以至他快乐的童年都在测试和研究中度过。成年后的克里斯隐形埋名混迹于赌城拉斯维加斯，不时去赌博一下赢点小钱。因为一个恐怖组织预谋要炸毁洛杉矶，特工凯莉（朱丽安•摩尔 Julianne Moore 饰）找到了克里斯帮忙。然而，这预测未来的超能力现在令克里斯痛苦万分，因为他预测到无论多么努力，洛杉矶最终还是会被炸毁，而且他的爱人也会在此劫难中死去……©豆瓣', '尼古拉斯·凯奇', '李·塔玛霍瑞', 7.2, 97592, 'tt0435705', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1100336420.jpg', 0.6, 4.6, 42, 41.7, 11, '0.167856,0.176626,-0.618035,0.540389,0.043084,-0.047610,0.843484,-0.153687,-0.547846,-0.402187,0.127416,0.767281,-0.082992,0.035598,0.131694,0.007632,-0.383964,-0.388424,0.231401,-0.139855,-0.460276,-0.553345,-0.674867,-0.310099,-0.140109,-0.156480,0.564447,0.298530,-0.121556,0.315333,0.118766,0.374803,0.123464,0.540816,0.033922,-0.157262,0.148466,0.185561,-0.248472,0.382143,0.139549,-0.088575,-0.154720,0.372331,0.085750,0.144878,0.375553,-0.293413,-0.251944,-0.238159,0.138747,-0.111860,-0.166842,0.268792,0.034092,-0.064330,0.218529,0.307240,-0.153497,0.073184,0.163350,0.157191,-0.991695,-0.128321,0.226801,0.191229,-0.490275,0.208747,-0.056467,-0.024701,-0.037956,-0.403352,0.137623,0.432692,0.261940,0.423222,-0.277212,-0.008435,-0.676025,0.031862,0.832291,-0.270155,-0.271055,0.411626,-0.442046,-0.292226,-0.205997,-0.305821,-0.507800,0.017224,-0.120348,0.203445,-0.293826,0.410524,-0.214782,0.290599,-0.231108,-0.187076,-0.487388,-0.460572,0.130861,-0.566940,-0.159019,-0.444608,-0.492678,-0.040887,0.103175,-0.620534,0.699629,-0.943529,0.133440,0.670185,0.223651,-0.476018,0.633659,0.384614,0.022341,-0.330954,-0.297163,0.550220,0.097546,0.049395,-0.345882,0.257248,0.347273,-0.360657,-0.174973,0.785419', '1793491', '1811755', '30163500', '25763555');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793912', '闪电狗', '剧情', '波特（约翰•卓佛塔配音）绝非一只普通的狗。在被女孩佩妮（麦莉•赛勒斯配音）带回家后，波特被她的父亲改造成一只“超级闪电狗”。它有强化的骨骼、风驰电掣的速度、无穷的力量。它要和佩妮一起去拯救被“绿眼人”绑架的父亲。波特靠着它的力量，战胜了无数强敌。当然，这一切只是在大屏幕上。实际上，波特与佩妮只不过是一起演出一部戏剧。波特并没有什么超能力，但它坚信自己的力量是真实的。一次拍摄后，混淆了真实与戏剧的波特冲出牢笼，要去大街上拯救佩妮，而它无法预知到，它将面临一个没有超能力的真实又危险的世界。©豆瓣', '约翰·特拉沃尔塔', '拜伦·霍华德', 7.5, 115993, 'tt0397892', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p775039123.jpg', 0.3, 2.8, 35.9, 45.2, 15.8, '0.346501,0.139547,-0.676595,0.678191,-0.171690,-0.037967,1.023700,-0.011545,-0.411069,-0.185945,0.066976,0.878462,-0.150442,0.185528,-0.209668,0.223858,0.009540,-0.587051,0.115165,0.043864,-0.655792,-0.456198,-0.578953,-0.236822,-0.032443,-0.265648,0.695699,0.002111,-0.505362,0.163498,0.142948,0.173208,0.014327,0.396222,-0.406724,0.081594,-0.115261,-0.046535,-0.033692,0.279133,0.228577,-0.172466,-0.016801,0.591286,-0.326138,-0.031486,0.798515,-0.525542,0.138039,-0.087892,0.368619,-0.367507,0.028390,0.356336,0.147248,-0.139785,0.119089,-0.129258,0.218454,-0.051445,0.145954,-0.195959,-1.185032,-0.143346,-0.197511,0.366497,-0.445692,0.483871,-0.136218,-0.045728,0.203334,-0.357661,0.008098,-0.004207,0.296162,0.312318,-0.357566,-0.180209,-0.727048,-0.077791,0.700628,-0.081540,-0.443373,0.577481,-0.448400,-0.397003,-0.297551,-0.348388,-0.395628,0.045366,0.585417,0.254654,-0.452136,0.256459,-0.828068,-0.183371,-0.454508,-0.083738,-0.445698,-0.392697,0.088461,-0.530868,-0.069021,-0.433303,-0.115622,-0.034449,0.114663,-0.608440,0.681097,-0.923273,0.301520,0.754673,0.197484,-0.169240,0.623645,-0.263997,0.243401,-0.129183,0.125019,0.141936,0.446155,0.373950,0.353355,0.414838,0.583332,0.190918,-0.443727,1.132982', '1308585', '1793491', '35158375', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793915', '生死新纪元', '动作', '影片改编自Maurice G. Dantec的畅销小说《Babylon Babies》。未来世界，随着科技的超速发展，大量高科技的机器人投入使用，为人类提供便利的同时也取代了大批劳动力。很快机器人的数量就已与人类不相上下，世界变成了机器与人类共生的一个团体。Toorop(范·迪塞尔 Vin Diesel 饰)是一名退役的老兵，空有一身的武艺却终日无所事事，转业当上了拿钱办事的雇佣兵，专门接受各种护送任务。一日，他接受了一项新任务：在Rebecca修女(杨紫琼 Michelle Yeoh 饰)的陪同下，押解一个神秘女人横跨欧亚大陆。然而他并不知道对方身上原来有着某种可怕的病毒，这种病毒的力量足以毁灭全世界。与此同时，一个邪教组织也正在对她虎视眈眈，企图利用这名女性产下一个基因改良的人种……©豆瓣', '范·迪塞尔', '马修·卡索维茨', 5.2, 10206, 'tt0364970', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2097792142.jpg', 11.7, 32.7, 42.9, 9.4, 3.3, '0.143866,0.288741,-0.427748,0.712310,-0.437788,0.133709,0.564281,-0.119296,-0.265983,-0.467419,0.215754,0.837916,0.186701,-0.074372,0.166918,-0.386591,-0.132022,-0.381629,-0.188733,-0.080332,-0.590030,-0.291553,-0.654917,-0.446966,-0.043105,-0.564376,1.013996,0.053164,-0.309415,0.303938,0.256544,0.414203,-0.156556,0.306094,-0.414418,-0.298406,0.254412,-0.292006,0.039180,0.280969,-0.305504,-0.119045,0.277526,0.001408,-0.375663,0.165882,0.720748,-0.326496,-0.168278,-0.595715,0.491840,-0.198667,0.035618,-0.214863,0.291651,0.157938,-0.071336,-0.013968,-0.071355,0.124707,0.043549,-0.109568,-1.180147,-0.399904,0.177927,-0.015688,-0.423566,0.127765,-0.006323,-0.083059,-0.203566,-0.214499,-0.062815,0.377070,0.274124,0.624137,-0.196435,0.152667,-0.585788,0.263925,0.470282,-0.063403,-0.600107,0.428265,-0.317704,-0.578339,-0.311887,-0.272207,-0.468932,-0.143957,0.143264,0.210393,-0.031562,0.149150,-0.908264,0.384248,-0.208598,-0.259199,0.019743,-0.267267,0.079626,-0.774297,-0.170093,-0.277146,-0.138729,0.273506,0.422839,-0.220007,1.033687,-0.552867,0.007844,0.476257,0.282402,-0.854716,0.415924,-0.095129,0.203161,-0.327400,-0.166191,0.203466,0.292370,0.330401,-0.053737,0.530297,-0.018372,-0.140585,-0.173174,0.561308', '27602116', '24284209', '26759820', '