INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793922', '我不在那儿', '剧情', '在这部关于鲍勃·迪伦生平的传记电影中，将分别由六位演员扮演鲍勃·迪伦，分别演绎鲍勃在不同时代的生活故事和音乐经历。该片讲述了鲍勃·迪伦早期作为民谣歌手艰苦奋斗的生活，和1960年代初成形的美国民歌界的英雄和知识分子，具有争议的摇滚转型、摩托车意外事故还有后来从公众视线里销声匿迹的隐退，近年来工作重心不放在录制唱片而是举行巡回演唱会上，如名为“永不停止的巡演”（The Never Ending Tour）等等。在一本由英国作家霍华德·苏尼斯撰写的鲍勃·迪伦非官方自传中，大部分是关于迪伦的童年时代和家庭生活。书中为我们进一步了解他的作品提供了更多信息，特别是与他的妻子苏拉(夏洛特·甘斯布饰)。除此之外，霍华德·苏尼斯还爆料了这位老牌摇滚歌手的一件秘密绯闻，他与自己的一位伴唱歌手从1986年开始有了一段不为人知的婚姻。每一段故事都表现了迪伦活泼善变的性格特征中的一个方面，影片也采取不同的方式来拍摄每个故事，分别用不同的主题与之相匹配：Woody (马库斯·卡尔·富兰克林饰)一个11岁的黑皮肤男孩，总是在奔跑中；Robbie（本·威士肖饰）一个风流倜傥的创作歌手，总是在路上；Jude (凯特·布兰切特饰)年轻的雌雄同体的摇滚巨星；John/Jack (克里斯汀·贝尔饰)一位重新找到自己、传递福音的民谣偶像；Billy (理查·基尔饰)大名鼎鼎的不法之徒，一个活着的奇迹但正在渐渐老去。幕后制作：【六人饰演鲍勃•迪伦】为了在银幕上塑造鲍勃·迪伦，你能想象出一共需要几位演员吗？托德·海因斯用他的新片《我不在那儿》给出了答案——六位。这是一部“导演心目中的鲍勃·迪伦传记片”，电影非常怪异地启用', '凯特·布兰切特', '托德·海因斯', 7.9, 22738, 'tt0368794', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p775566271.jpg', 0.6, 2.6, 24.1, 47.9, 24.8, '0.346818,-0.107773,-0.411793,0.861839,0.046247,-0.076278,0.745868,-0.040039,-0.295578,-0.406408,-0.001767,0.984054,-0.189544,0.313876,0.405005,-0.099876,-0.492904,-0.703228,-0.041942,-0.106116,-0.000146,-0.587978,-0.471890,-0.107462,-0.239456,-0.418054,0.695847,-0.082582,-0.315356,0.370047,0.368493,0.236637,-0.055272,0.044489,-0.098157,-0.030737,0.291679,0.080654,-0.253569,0.261502,0.018118,-0.218394,-0.108226,0.085600,0.001374,0.337672,0.423271,-0.278114,0.226780,0.094371,0.531072,-0.003461,0.011472,-0.147020,0.122794,0.112659,0.380299,0.311302,-0.089027,0.103802,-0.230172,-0.310989,-0.980609,-0.065825,0.158707,0.477186,-0.481853,0.292221,-0.146946,-0.027389,0.144292,-0.269251,0.162179,0.168726,0.358397,0.289313,0.027483,0.118788,-0.345290,0.408100,0.396331,0.245146,-0.489609,0.423875,-0.214982,-0.515228,-0.315509,-0.102904,-0.538745,0.051763,0.194085,-0.125745,0.046347,0.260853,-0.684664,0.007313,0.042851,-0.371834,0.122333,-0.216181,-0.100415,-0.948932,-0.145589,-0.514471,-0.040940,-0.392564,0.199195,-0.479057,1.014424,-0.704931,0.189693,0.343411,-0.097430,-0.358998,0.642797,0.163847,0.272988,-0.289484,-0.083301,0.223389,-0.009919,0.016152,-0.121881,0.380868,0.072523,-0.220721,-0.497804,0.639430', '27602116', '3318306', '1870681', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1793929', '达拉斯买家俱乐部', '剧情', '1986年美国达拉斯市，恐同的德州电工罗恩·伍德鲁夫（马修·麦康纳 Matthew McConaughey 饰）发现自己患上“同志病”——艾滋，生命只剩30天。他使用的AZT（叠氮胸苷）是当时美国药管局唯一批准面市的抗艾药物，但毒性极大。为了活下去，罗恩开始研究各种抗艾 处方和替代疗法，甚至走私来自世界各地未经批准的药物。在医生萨克斯（詹妮弗·加纳 Jennifer Garner 饰）和异装癖同性恋雷蒙（杰瑞德·莱托 Jared Leto 饰）的帮助下，罗恩开始成立了一个叫做“达拉斯买家俱乐部”的地下组织，为艾滋病人提供更多“非常规疗法”，很多患病的男同性恋亦求助于他。他的举动自然受到了药管局和药商的阻挠和施压。罗恩最终在1992年9月去世，离他被告知只剩30天可活已经过去了2557天。在这近7年时间里，他坚持不懈的与病魔、与药管局及制药商进行艰苦的斗争，享受真正活过的人生......本片根据真人真事改编，讲述一个绝症病人如何努力求生并拯救成千上万面临同样境遇的人的故事，提名金球奖剧情类最佳男主/男配以及获得大小29个奖项。', '马修·麦康纳', '让-马克·瓦雷', 8.8, 425151, 'tt0790636', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166160837.jpg', 0.1, 0.3, 7.5, 42.3, 49.7, '-0.181112,-0.272694,-0.223203,0.285628,0.165365,-0.039134,0.425318,-0.154833,-0.437637,-0.476515,-0.102059,0.532997,-0.082421,0.151191,0.290140,-0.287795,-0.319944,-0.395092,0.151608,-0.044718,-0.527402,-0.424871,-0.314640,-0.374795,-0.058199,-0.373112,0.639206,0.037991,-0.047114,0.255510,0.130474,0.422323,0.125545,0.280418,0.020993,-0.001008,0.197838,-0.220571,-0.398141,0.343128,0.334952,-0.215740,-0.212662,0.016633,0.151942,0.401323,0.380413,-0.447386,-0.157828,-0.231728,0.319646,-0.272249,-0.115246,0.033840,0.052917,0.112622,0.257511,0.314399,-0.205065,-0.006813,-0.029613,-0.113013,-0.722400,-0.161088,0.119585,0.206388,-0.266091,0.362427,-0.183403,0.286277,-0.188530,-0.236605,-0.024209,0.409203,0.128932,0.362609,-0.418557,-0.076329,-0.549003,0.291754,0.471884,-0.064173,-0.396374,0.378434,-0.235557,-0.533650,-0.038834,-0.319027,-0.181110,0.020130,0.208223,0.110358,-0.159498,0.159180,-0.490031,-0.004323,-0.165048,-0.421739,0.144575,0.013188,0.076489,-0.671292,-0.104326,-0.108667,-0.308376,-0.110972,0.297677,-0.530472,0.720206,-0.531405,0.169925,0.276759,0.237195,-0.627589,0.436760,-0.003036,0.167520,-0.174823,-0.407013,0.468907,0.095873,0.206725,0.110772,0.085002,-0.002615,-0.016123,-0.147159,0.284761', '2369613', '4301278', '27602116', '1793915');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1794171', '变形金刚', '动作', '“霸天虎”的先遣部队旋风和毒蝎袭击了美军位于卡塔尔的军事基地，与此同时，路障帮助他的搭档迷乱潜入了美国总统的座机空中一号，通过电脑获悉，要想找到威震天就必须找到维特维奇家族的那副眼镜，上面有威震天关于能量块的信息扫描，而它现在的拥有者萨姆•维特维奇（希安•拉博夫饰）成为了“霸天虎”攻击的目标。萨姆是名高中生，学校里没有人相信他讲述的关于这副眼镜的历史，失望之余，萨姆把眼镜放到网上拍卖，然而从未引起买家的兴趣。这时父亲送了一辆破车给他，这辆车恰好就是“汽车人”大黄蜂的变形。大黄蜂帮助萨姆交上了漂亮的女朋友（梅甘•福克斯饰），但很快就遭遇了“霸天虎”的袭击，擎天柱带着其他“汽车人”赶到，一场机器人大战由此拉开了序幕。©豆瓣', '希亚·拉博夫', '迈克尔·贝', 8.3, 455425, 'tt0418279', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1188042816.jpg', 0.3, 1.2, 15.8, 48.3, 34.4, '0.434945,0.017870,-0.624699,0.533019,-0.068963,-0.074506,0.545452,0.103031,-0.448913,-0.142511,0.150050,0.504708,-0.040817,0.025413,0.366911,0.191388,-0.465565,-0.531165,-0.025325,-0.210581,-0.517497,-0.538914,-0.360882,-0.164957,0.433413,-0.449190,0.509827,0.069323,-0.112226,0.448081,0.135439,0.139102,0.078353,0.351929,-0.147065,-0.030742,0.060256,-0.215399,0.097146,0.328404,-0.229923,-0.149284,0.119150,0.178029,0.021979,0.472003,0.559122,-0.182281,0.052509,-0.043833,0.084312,-0.263148,0.146715,-0.139942,0.448100,0.141789,-0.019933,-0.018487,-0.176823,-0.158073,0.190630,0.123302,-0.561320,0.167727,-0.454964,0.076827,-0.559817,0.306185,-0.503473,0.201095,0.087302,-0.169279,0.501601,0.277982,0.178880,0.146945,-0.021721,0.109460,-0.602701,-0.019445,0.457443,0.011186,-0.219743,0.169946,0.021329,-0.251114,-0.132447,-0.145213,-0.380858,0.039690,0.787560,0.001395,-0.061169,-0.023701,-0.629687,-0.159279,-0.513872,-0.352840,-0.013012,-0.130366,-0.143052,-0.790949,-0.220575,-0.124029,-0.014266,-0.004641,-0.068791,-0.096688,0.726518,-0.716544,0.085862,0.418960,0.213770,-0.195795,0.671964,-0.294514,-0.031324,-0.276798,0.077805,-0.098532,0.283066,0.496449,0.030997,0.355141,0.197966,-0.558686,-0.078912,0.333663', '1307897', '11810348', '1294917', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1794401', '鬼打鬼之黄金道士', '喜剧', '道士英叔（林正英 饰）胸怀开宗立派之志，每日带领五名徒弟勤加修炼，他为人坦荡，清贫无一长物，不得不做看更来补贴日用。英叔受人委托，看守一座无人大宅，无处容身的师徒六人暂住大宅之中。这座宅第中有一对儿清朝鬼夫妻留驻，女鬼阿娟（罗慧娟 饰）饱受丈夫虐待殴打，英叔仗义出手，将男鬼驱逐，阿娟自此留在其身边，与五个徒弟相处融洽。不久男鬼带同伴寻仇，英叔师徒大展威力再次驱鬼，阿娟亦一改受气形象，在丈夫面前扬眉吐气，此后她日日配合众徒弟练习捉鬼之术。一伙外国黑社会分子得到情报，获悉在这座大宅内藏有大量黄金，他们乔装教堂人员入住，试图谋害英叔等人，夺取黄金……©豆瓣', '林正英', '陈会毅', 7, 11201, 'tt0104460', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1927154387.jpg', 1.3, 7.7, 45.4, 30.2, 15.5, '-0.212729,-0.396443,-0.397103,0.186419,-0.111338,-0.020066,0.351578,0.050133,-0.584211,-0.468197,0.382582,0.472249,0.061369,0.102465,0.030929,-0.252831,-0.193062,-0.302290,-0.070625,-0.269711,0.184923,0.024664,0.028483,-0.426855,-0.256227,-0.330174,0.337264,-0.007974,0.107218,0.211732,0.140698,0.026935,-0.675359,-0.166676,-0.396243,-0.067694,0.063791,-0.022326,-0.411107,0.170454,-0.664686,-0.162245,-0.093814,-0.185461,0.098888,0.014861,0.709794,0.017878,-0.258998,-0.394291,0.042082,0.145299,-0.136389,0.233786,0.300166,-0.060470,0.507441,0.146190,-0.323573,-0.006246,-0.077363,-0.325042,-0.263527,0.070752,0.408024,-0.200482,-0.331597,0.214518,0.140321,0.073624,-0.203111,-0.163851,-0.071548,0.141814,0.035029,0.146260,-0.003606,-0.010758,-0.387622,0.123503,0.542618,-0.448706,0.395558,-0.209121,0.253689,-0.081699,0.337250,-0.354087,-0.236881,-0.240327,0.142576,-0.108091,0.080351,0.030739,-0.222384,-0.107295,-0.293716,0.491430,0.159606,-0.231076,0.140346,-0.935010,0.140642,0.138230,-0.056935,0.156176,0.291374,-0.185568,0.522883,-0.333768,0.278616,0.062021,0.499675,-0.583036,0.574434,-0.247605,0.401157,-0.369881,-0.265876,0.207779,0.552279,0.257496,0.144805,0.003588,-0.218372,0.140059,-0.109497,-0.155891', '1301257', '2369613', '10466639', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1794435', '姨妈的后现代生活', '剧情', '12岁的侄子宽宽，在假期去看望退休后独自在上海生活的姨妈（斯琴高娃饰）。在宽宽眼里，姨妈是个怪癖多多的人。一次姨妈在公园遇到了一个从广东到上海来发展的江湖混混潘知常（周润发饰），这个神秘男人使得姨妈神魂颠倒，两人因京剧成了知音，并演绎出一段黄昏恋情。不料好景不长，潘知 常带着姨妈的棺材本积蓄一道消失。与此同时，姨妈又发现保姆（史可饰）竟然是靠“碰瓷”来赚取外快。接连发生的事件让姨妈醒悟万千，她决定离开上海，回到东北的家，那里有已经疏远了的丈夫和女儿……©豆瓣', '斯琴高娃', '许鞍华', 7.4, 57094, 'tt0470984', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1052723783.jpg', 0.7, 4.3, 34.8, 45.3, 15, '0.254878,-0.133560,-0.639645,0.395515,-0.291364,-0.449181,0.650905,0.304510,-0.583341,-0.347051,0.266404,0.710553,-0.396879,0.501426,0.314254,-0.067106,0.025317,-0.478986,0.143473,-0.275158,-0.197587,-0.244018,-0.134942,0.028744,0.116754,-0.207738,0.163739,0.000953,0.070964,0.556523,0.303282,0.028665,-0.299958,0.557696,-0.326098,0.278481,-0.074109,0.256763,-0.205170,0.157915,0.123362,-0.342120,-0.057664,-0.231158,-0.061370,0.121963,0.753119,0.224202,-0.096713,0.011313,0.566589,0.028565,-0.190376,-0.067315,0.426152,-0.022635,0.082453,0.135344,-0.342717,0.059520,-0.007226,-0.225813,-0.202412,0.319121,-0.059027,0.044332,-0.911808,0.464711,0.069519,-0.279355,-0.044876,-0.705022,0.342173,0.487546,-0.167966,0.620313,-0.238269,0.344996,-0.623999,0.328283,0.668241,-0.098079,0.037577,0.389740,0.123178,-0.195345,0.308259,-0.102095,-0.370216,-0.002587,0.172792,-0.302939,-0.374540,0.073018,-0.671866,-0.056301,-0.210109,-0.170552,0.378210,-0.325810,-0.253264,-0.400849,-0.274342,-0.210040,-0.134187,0.347410,0.031417,-0.140529,0.614298,-0.751626,0.337220,0.659600,0.243966,-0.426827,0.851536,0.025700,0.143534,-0.227834,0.059801,0.081094,-0.043448,0.412312,0.115947,0.144031,-0.271668,-0.194105,-0.447042,0.266623', '25731805', '1306505', '1926007', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1796007', '初恋', '剧情', '生性孤僻的美铃（宫崎葵 饰）在年幼时被母亲抛弃了，当时母亲只带走了哥哥。在叔父家中寄人篱下，学校也没有同学愿意接近她。后来她在一间酒吧里认识了一群年轻人，也成为了他们当中的一员，性格也渐渐开朗了。不久，她喜欢了这群人里一个叫岸的男生。岸突然对美铃说正打算抢劫运钞车，岸表示需要美铃的帮助，美铃竟然义无反顾的答应了。她要学会开摩托车，需要记牢运钞车的路线。而美铃就在一个下着雨的清晨，出发了……©豆瓣', '宫崎葵', '塙幸成', 7.3, 7536, 'tt0809925', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1471726203.jpg', 0.8, 5.2, 39.5, 38.4, 16, '0.462056,0.196170,-0.731254,0.407151,-0.599740,-0.510402,0.569524,0.039148,-0.342101,-0.265065,0.085006,0.898448,0.321500,0.274077,0.300548,0.126497,-0.107737,-0.464209,0.069336,-0.452857,-0.269063,-0.423547,0.002403,-0.203773,-0.089219,-0.230718,0.432895,0.100352,0.105518,0.660136,0.213426,-0.080395,-0.024285,0.630667,-0.370970,0.207792,0.095715,0.098531,0.077822,0.272828,-0.247689,-0.295044,-0.094529,0.075047,0.240582,0.508232,0.624331,-0.140848,-0.211064,0.026358,0.083071,-0.155336,-0.022949,0.131720,0.725005,-0.118265,0.364959,0.255421,-0.299485,0.065974,-0.130172,-0.039785,-0.342441,0.024568,-0.109742,-0.000076,-0.816920,0.573191,0.065663,-0.175164,0.180651,-0.552307,0.167554,0.251522,0.118596,0.413848,-0.075572,-0.080541,-0.507957,0.180673,0.769419,-0.135275,0.043673,0.768102,-0.225841,-0.059144,0.062283,-0.231144,-0.606999,-0.205375,0.439470,-0.166652,-0.688919,-0.117472,-0.258965,-0.032509,0.003255,-0.002218,-0.007983,-0.397960,-0.021414,-0.222293,-0.023684,-0.467047,-0.148815,0.179871,-0.300518,-0.059015,0.788686,-1.038200,0.292289,0.687622,0.454620,-0.618208,0.624921,0.233337,-0.051499,0.058514,0.402981,-0.065134,-0.075990,0.340122,0.175686,0.605685,0.005983,-0.336933,-0.533744,0.243467', '1292219', '1292720', '5262027', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1796053', '蜂蜜与四叶草', '爱情', '毛头小子竹本（樱井翔 饰）是美术系新生，对大学生活充满了憧憬，入驻公寓第一天便受到两个人的震撼：浑身裹着古怪艺术家气质的同屋森田（伊势谷友介 饰），才华横溢而浑身萝莉气的自闭少女花本育（苍井优 饰），二人几乎同时喜欢上小育，但小育和美术老师阿修（堺雅人 饰）有亲戚关系，被他保护得非常严密。另一个室友真山（加濑亮 饰）被女生山田（关惠美 饰）默默爱着，但他却痴迷打工时的上司——美丽成熟的建筑师理花。两条故事线交织着青春的一切：大学生活，艺术梦想，狂狷的内心，矛盾的感情。在身边人个个闪闪发光的映衬下，最为单纯平凡的竹本，从最初的迷茫慢慢意识到自己的成长……本片是大热漫画《蜂蜜与四叶草》真人版电影。©豆瓣', '樱井翔', '高田雅博', 7.5, 43210, 'tt0810400', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p828552028.jpg', 0.6, 4.5, 35.4, 40.8, 18.7, '0.115279,-0.211524,-0.421490,0.577671,-0.071350,-0.132478,0.691322,0.320898,-0.592345,-0.378315,0.302863,0.660013,-0.483940,0.396403,0.214782,0.141669,-0.094242,-0.663540,-0.161534,-0.097673,-0.011724,-0.133927,-0.094752,-0.040785,-0.235211,-0.372565,0.867752,-0.006652,-0.005445,0.610847,0.238126,0.388543,-0.118840,0.117452,-0.073596,-0.106445,0.063392,0.060651,-0.004547,-0.213516,-0.250041,-0.060244,-0.119877,0.090042,-0.112446,0.088571,0.752739,0.085890,-0.210888,-0.091387,0.462048,-0.084730,-0.255960,0.224651,0.240243,0.096862,0.217135,-0.024020,-0.085873,-0.004449,0.204466,-0.328658,-0.478369,-0.128711,0.400239,0.356112,-0.342797,0.608539,0.058218,-0.252686,0.421772,-0.108882,-0.168632,-0.317389,0.334373,0.455031,-0.018146,0.256485,-0.162212,0.388013,0.394824,0.127389,-0.255223,0.497679,-0.744030,-0.265397,-0.291809,-0.106201,-0.633130,0.021655,0.054910,-0.018561,-0.051684,0.148575,-0.639325,0.077690,0.259082,0.102691,0.074455,-0.425923,-0.156364,-0.489109,-0.275095,-0.684537,-0.265728,0.060783,0.165944,-0.152589,1.022914,-0.851516,0.055227,0.475699,0.062905,-0.117758,0.445470,-0.007463,-0.242262,-0.206037,-0.174961,0.430020,-0.061060,0.087872,-0.037212,0.563761,-0.551658,0.190717,-0.535446,0.505922', '3811356', '25922902', '10174444', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1796232', '恋爱情结', '喜剧', '根据中原亚矢的漫画作品《ラブ★コン》改编而成。大谷（小池徹平饰）和小泉（藤澤惠麻饰）是同班同学，由于分别拥有159cm和170cm的身高而被人戏谑为“矮冬瓜”和“女巨人”，两人一见面就会拌嘴，拿彼此的身高取笑，但又有着超高的契合度，被周围人称为阪神搞笑二人组。在吵吵闹闹中，两人意外地发现彼此竟拥有共同的兴趣爱好，转而由冤家转变为好朋友的身份。渐渐的，大谷的温柔体贴让小泉心生感动，她鼓起勇气向大谷表白，不料对方却被吓跑了，而主要的顾虑仅是因为身高问题……这对欢喜冤家最终能踏倒“身高拦路虎”而在一起吗？©豆瓣', '藤泽惠麻', '石川北二', 7.3, 8469, 'tt0810415', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169658189.jpg', 0.7, 4.8, 37.4, 40.4, 16.6, '0.451230,-0.270663,-0.771594,0.674640,-0.123827,-0.375645,0.756820,0.117035,-0.572182,-0.045495,-0.024600,0.812076,-0.562336,0.027535,0.190759,-0.064574,0.089913,-0.870180,-0.199915,-0.142225,-0.182201,-0.605875,-0.253709,-0.237930,-0.188303,-0.196455,0.508859,-0.243154,-0.165354,0.622829,0.397681,0.151994,-0.147791,0.461580,-0.120529,0.069907,-0.228586,0.024287,-0.091536,0.258135,-0.155140,-0.156856,-0.160224,0.226066,-0.291586,0.619597,0.812294,-0.175339,-0.320653,-0.018434,0.224513,-0.204750,-0.136511,0.135259,0.463949,0.004446,0.583701,0.088004,-0.023076,-0.008962,0.245026,0.032319,-0.649992,0.213733,0.222959,-0.069734,-0.491185,0.674581,0.258271,-0.429563,0.415528,-0.129140,0.051340,0.265983,0.553860,0.506155,-0.284505,-0.160277,-0.256233,-0.349596,0.500795,0.121766,-0.261301,0.412462,-0.358755,-0.444917,-0.162109,-0.375715,-0.269843,-0.068109,-0.031431,0.461486,-0.011829,0.024658,-0.777127,0.073839,-0.050871,0.193633,-0.122704,-0.779593,0.070516,-0.287852,-0.335852,-0.876235,-0.396291,0.177005,0.151195,-0.439104,0.836677,-0.887791,-0.254320,0.456511,0.389692,-0.398067,0.629665,0.228710,-0.224996,-0.217213,-0.118955,-0.249799,-0.082288,0.021664,0.287539,0.344241,-0.060323,-0.089006,-0.479420,0.312315', '1292219', '3155839', '26354526', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1796255', '乌龟意外之速游', '喜剧', '雀（上野树里 饰）是一个无聊的女生，她每天在家喂养乌龟，接听海外丈夫每天打来的一通电话，这天也不例外。一个奇怪的水管工坚持自己曾经修理过因为鳗鱼饭而堵塞的家庭，雀就跟到水管工的公司去看，却因不看其他奇怪的物品而要自己走回家。走回家的路上想用30秒的时间爬完一段长楼梯，却因滚下来的苹果而扑倒，扑倒的时候看到一张招募间谍的小小贴纸。当时并不引以为意的雀继续去赴发小好姊妹（苍井优 饰）的约会，却被告知还要等2个小时，雀去烫头发，顺便回想了一下从小到大好友的辉煌自己的低调，忽然间，她想起了那张间谍纸条，她决定前去应聘！©豆瓣', '上野树里', '三木聪', 7.6, 8942, 'tt0455577', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p670877447.jpg', 0.5, 3.6, 31.9, 44, 20, '0.415461,-0.040109,-0.440380,0.470547,-0.189958,-0.380823,0.640992,0.092795,-0.049808,-0.258239,-0.092959,0.607728,-0.111700,0.447430,0.153130,0.057771,-0.248650,-0.404151,0.198980,-0.084051,-0.465605,-0.134161,-0.027042,-0.082124,0.105896,0.178792,0.227328,-0.075379,0.117376,0.602748,0.131525,-0.250341,-0.032321,0.537076,-0.138726,0.042284,-0.249399,0.118688,0.403033,0.040593,0.357102,-0.382812,-0.184543,0.114251,0.298132,0.438261,0.417070,0.050161,-0.084821,-0.033631,0.184012,-0.035236,-0.085143,0.055785,0.480959,0.040069,0.142403,-0.276093,-0.353101,0.191815,0.032200,-0.012681,-0.435157,0.052327,-0.295201,0.144066,-0.681359,0.588637,-0.208314,0.132246,0.102363,-0.538702,0.071771,0.351380,0.010724,0.637725,-0.131493,0.082430,-0.276519,0.390854,0.465038,0.074162,0.272091,0.458211,0.137576,-0.204805,0.175507,0.014018,-0.210834,-0.165276,0.438813,0.005047,-0.339934,-0.402950,-0.581653,-0.017399,-0.185652,-0.298958,0.053308,-0.391402,-0.403707,-0.413802,0.220983,-0.250761,0.027040,0.462412,0.262138,-0.171565,0.320417,-0.633813,0.097038,0.588032,0.279797,-0.515464,0.775546,0.081342,-0.161732,-0.089757,0.161264,0.046261,0.205592,0.541420,0.191024,0.330899,0.186881,-0.257550,-0.588903,0.173642', '2990737', '1361252', '1302384', '1307876');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1796995', '摇摆', '剧情', '早川猛（小田切让饰）在大城市里事业顺利，是名年轻有为的摄影师，其兄早川稔（香川照之饰）则在家乡继承父业，经营一家小加油站。在母亲的周年忌日，猛从东京回到老家探亲，昔日情人智惠子（真木阳子饰）在加油站工作，她感叹当年没跟猛离开。年轻气盛的猛和传统而顽固的父亲动不动就起冲突，而身为大哥的稔却顺从父亲。之后兄弟二人和智惠子去附近溪谷游玩，不料智惠子从古老破旧的吊桥坠下身亡。当时唯一在她身边的稔成了杀人嫌疑犯，猛为了帮助兄长四处奔走，力图证实这是一起意外。然而在开庭过程中，稔突然一反常态……©豆瓣', '小田切让', '西川美和', 7.6, 7431, 'tt0809535', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2187343352.jpg', 0.5, 1.8, 31.1, 50.3, 16.3, '-0.076879,0.200479,-0.861071,0.217800,0.210084,-0.459662,0.431324,0.383442,-0.364676,-0.504373,0.175121,0.761607,0.324667,0.290636,0.170969,0.056464,-0.210926,-0.681244,-0.141997,-0.159415,-0.179974,-0.361248,0.172431,-0.171397,-0.183819,-0.224212,0.395945,0.022623,-0.184800,0.753342,0.221520,0.405340,-0.374248,0.182004,-0.353395,0.078957,0.113211,0.315430,-0.281357,0.249231,-0.000800,-0.383543,-0.349603,0.039330,0.387420,0.449523,0.443466,-0.183632,-0.358002,0.058527,0.058971,-0.125169,-0.258749,0.169645,0.628250,-0.142325,0.236563,0.176851,-0.460312,-0.216433,0.251728,-0.298125,-0.345807,-0.047483,0.020622,0.072800,-0.616999,0.477545,-0.196486,-0.286477,0.399214,-0.521226,0.223419,0.373997,-0.029908,0.372061,-0.495238,0.274788,0.068854,0.166058,0.624984,0.031186,0.140991,0.270723,0.073701,-0.049225,0.108747,-0.265409,-0.226258,-0.193034,0.315579,-0.105659,-0.142710,0.172982,-0.313991,-0.094454,-0.153151,0.211211,0.215043,-0.029051,-0.157338,-0.289013,0.120444,-0.149960,-0.011313,0.305249,-0.143833,-0.272129,0.651037,-0.810236,0.215799,0.579759,0.237686,-0.327490,0.476834,-0.090538,-0.037405,-0.119211,0.025586,-0.090193,0.161073,0.340108,0.016545,0.297945,-0.164268,-0.182797,-0.434950,0.174891', '25723081', '1292219', '35030151', '1307755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1797020', '门', '惊悚', '蒋中天（陈坤 饰）正在经历人生的低潮。面对上司兼同窗好友洪源（黄觉 饰），他显得极度不自信，对对方也不信任。总是认为他跟自己青梅竹马的女友文馨（杨幂 饰）有染。突然冒出的中学同学李作文更让他昏了头，李作文不学无术，混到今天成了个出租车司机，还总是在中天面前出现，中天一直记得李作文当年企图强奸文馨未遂，心里一直有着阴影。他对自己的不信任映照到文馨身上，开始疑神疑鬼，终于文馨忍受不了，留下一通信息后出走。蒋中天埋头粉刷墙壁，日日装修。在幻觉之下，他杀了洪源，但洪源的魂魄依旧纠缠着他。他开始怀疑警方派人来监视他，每一个邻居每一个上门的过客，他都认为是有目的的。他一边追寻着文馨的下落，一边接近事实的真相，然而当真相的门打开时，他发现一切早已是不能挽回的大错。©豆瓣', '陈坤', '李少红', 5.1, 10233, 'tt0798841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2362206306.jpg', 16.7, 32.4, 37, 8.8, 5.1, '0.249804,0.149620,-0.777128,0.717532,-0.105060,-0.253480,0.879930,-0.110195,-0.403491,-0.441944,0.197163,0.359657,-0.201088,0.483966,0.058418,-0.031291,-0.235178,-0.696512,-0.102369,-0.114030,-0.335386,-0.441087,-0.177450,-0.228560,-0.436386,0.219966,0.418986,0.217561,-0.290431,0.095007,0.373653,0.196066,0.156352,0.512752,-0.199803,0.116480,-0.137920,0.208418,0.048248,-0.100622,0.317744,-0.479890,-0.242210,0.327944,-0.080962,0.270953,0.473997,-0.095854,-0.259459,0.007569,0.223098,-0.242949,-0.113277,0.200520,0.349530,0.006511,0.251222,0.011490,-0.150060,-0.046799,-0.025715,0.109473,-0.553945,-0.068541,0.018287,0.270564,-0.453776,0.153800,-0.295754,0.063397,0.046159,-0.482711,0.091566,0.059364,0.254709,0.350451,-0.322820,-0.004714,-0.607185,-0.004860,0.692199,0.200974,-0.144612,0.257741,-0.237725,-0.149852,-0.016373,-0.049045,-0.477828,0.075074,0.131357,0.017512,-0.109726,0.218331,-0.174131,-0.142470,-0.030004,-0.007570,-0.063533,-0.362021,-0.125276,-0.096649,-0.259558,-0.553773,-0.411124,0.130270,-0.067252,-0.420300,0.323273,-0.833352,0.284372,0.335518,0.171803,-0.498037,0.608390,0.382203,-0.224871,-0.222586,-0.071427,0.220663,0.064938,0.323623,0.209021,0.262386,0.014066,-0.168079,-0.311045,0.390050', '4275444', '1301022', '1296370', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1805685', '大狗民', '喜剧', '帕德（Mahasamut Boonyaruk 饰）是一名罐头工厂的切鱼工人，一次意外中，他削去了自己的左手食指，当他在一个鱼罐头里找到了自己的手指后才发现，这截手指其实属于工友耀德（Sawatwong Palakawong Na Autthaya 饰）。领略了切鱼工作的危险后，帕德辞了职成为了一名商场保安，就是在此过程中，他结识了名叫金（Saengthong Gate-Uthong 饰）的女子。没多久，帕德决定不干保安了，遂即转行成为了出租车司机，他和金之间的情感也日益深厚起来。金的手上有一本神秘的白皮书，这么多年来，她一直企图解开书中隐藏的秘密，一次偶然中，在一个名叫彼得（Chuck Stephens 饰）的老外手中金发现了和自己一模一样的书，多年来的疑惑似乎有了被解开的希望，而看见金如此的为彼得着迷，帕德的心情十分复杂。©豆瓣', '马哈萨穆特·布恩亚鲁克', '韦西·沙赞那庭', 7.9, 7500, 'tt0444778', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2328616301.jpg', 0.8, 3, 24.2, 45.6, 26.4, '0.298394,0.169905,-0.797786,0.703052,-0.288772,-0.417712,0.911227,0.078225,-0.500596,-0.226099,0.079563,0.763578,-0.088777,0.268786,0.197860,0.184202,-0.120051,-0.951535,-0.214544,-0.373594,-0.642701,-0.348537,-0.511221,-0.005946,-0.102046,-0.267838,0.255287,0.308600,-0.143865,0.556401,0.433681,0.091598,0.140872,0.439768,-0.293570,0.042437,0.253620,0.003115,0.159086,0.063357,0.123007,-0.400555,0.059589,0.368576,-0.009619,0.483070,0.630322,-0.155119,-0.037432,0.066175,0.165596,0.058306,0.019870,-0.154054,0.307049,0.381006,0.123474,-0.147069,-0.494251,0.110710,0.229907,-0.082944,-0.783245,-0.164420,-0.166318,0.201203,-0.897425,0.321104,-0.052058,-0.158366,-0.153081,-0.465606,0.214674,0.081989,0.385512,0.173214,-0.039469,-0.062646,-0.430766,0.279186,0.403914,0.073733,-0.076243,0.350305,-0.125882,-0.401173,-0.185546,0.041651,-0.069867,-0.204933,0.714031,-0.001938,-0.212500,0.038343,-0.633617,-0.100681,-0.233793,0.046000,0.074051,-0.185308,-0.257880,-0.238483,-0.015156,-0.334507,-0.312384,0.115710,-0.068341,-0.311730,0.755203,-0.852470,0.312564,0.388127,0.131168,-0.261493,0.681798,-0.031939,0.142741,-0.121431,-0.077960,-0.052749,0.141323,0.414234,0.430196,0.553954,-0.118204,-0.400246,-0.454229,0.417633', '21360412', '1307146', '