INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1806543', '这就是英格兰', '剧情', '这是一个关于英国“光头仔”群体的故事。1983年的英国，正处于一个动荡时期。12岁的叛逆少年沙恩在放学回家的路上遇到了一群“光头仔”，在同他们大打出手后沙恩也成为了他们中的一员。令沙恩没有想到的是，这些人竟成为他日后最好的朋友甚至亲如一家人。他们一起，在一个灰色的年代里分享自己的成长和喜怒哀乐。©豆瓣', '托马斯·图尔格斯', '西恩·迈德斯', 8, 22903, 'tt0480025', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p504729047.jpg', 0.3, 1.7, 22.1, 51.8, 24.1, '0.666709,-0.187880,-0.830532,0.606242,-0.368064,-0.209103,0.849957,-0.060633,-0.524052,-0.322679,0.040535,0.857797,-0.161426,0.691423,0.165487,-0.358147,-0.145427,-0.752421,0.022270,-0.224602,-0.339743,-0.279418,-0.565104,-0.219601,-0.403326,-0.180707,0.780301,-0.068023,-0.138346,0.640159,0.285175,0.231438,-0.032130,0.530781,-0.543425,-0.056894,0.168929,0.082256,-0.157745,0.225201,-0.421937,-0.190832,0.016248,-0.103954,-0.048364,0.204773,0.733985,-0.255255,-0.076750,-0.029028,0.348237,-0.310391,-0.518232,0.093885,0.630143,-0.112614,0.416939,0.154727,-0.032531,0.031713,-0.034113,-0.079474,-0.831385,-0.005036,0.040538,0.456008,-0.789745,0.460941,0.251323,-0.221559,0.292736,-0.257454,0.511900,0.639437,0.206938,0.546401,-0.056592,0.124409,-0.765424,0.222288,1.120073,-0.001921,-0.472371,-0.034072,0.049542,-0.343193,0.034792,-0.067521,-0.559085,-0.034703,0.127102,-0.345936,-0.443692,0.287499,-0.789922,0.243764,0.040447,-0.297992,0.135035,-0.336495,-0.272614,-0.559741,-0.109175,-0.845724,-0.491778,0.258472,0.148039,-0.337105,1.195687,-0.899144,0.301490,0.466755,0.388129,-0.693658,1.197709,0.149797,0.379881,-0.222197,-0.254183,0.066684,0.123128,-0.081514,-0.098806,0.372999,-0.155007,0.035016,-0.314610,0.467384', '3055049', '30162520', '25721544', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1806555', '热血警探', '喜剧', '尼古拉斯•安奇尔（西蒙•佩吉Simon Pegg 饰）在伦敦担任高级巡警，抓贼破案似乎是他最大的乐趣。为此他成为警局中最敬业最能干的警员。但这却招致了警长的妒嫉，可怜的尼古拉斯被调至一个偏僻平静的小镇当警察。小镇已经几十年没有过恶性犯罪事件。尼古拉斯在那里过得相当郁闷 ，他觉得自己的擒贼本领没有施展空间。更令他烦恼的是，镇里警察局局长儿子丹尼•巴特曼（尼克•弗罗斯特 Nick Frost 饰）也来凑热闹，成为他的搭档。这个新搭档麻烦至极，整天询问大城市的警员经历。正在尼古拉斯烦心于镇里鸡毛蒜皮的事务和身边的苯搭档时，镇里却发生了一桩案件，让尼古拉斯嗅到了大展拳脚的机会，惊心动魄的战役开始了。©豆瓣', '西蒙·佩吉', '埃德加·赖特', 8.2, 175087, 'tt0425112', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1774982769.jpg', 0.4, 1.8, 17.4, 48.3, 32, '0.518584,-0.228154,-0.735305,0.389398,-0.305615,-0.280868,0.873178,0.039722,-0.764115,-0.298498,0.199589,0.693247,-0.188022,0.154487,0.222306,-0.099396,-0.220973,-0.589578,0.120852,-0.150577,-0.160852,-0.415504,-0.327568,-0.297822,-0.103042,-0.206110,0.254777,0.142733,-0.043578,0.345476,0.226172,0.353053,0.228227,0.600922,-0.223504,0.138759,0.417663,-0.012426,-0.011424,-0.087565,0.146388,-0.285503,-0.250885,0.299059,0.261984,0.315633,0.550892,0.138486,-0.309253,-0.137044,0.271575,-0.268232,0.051307,-0.159805,0.392983,-0.054758,0.162782,0.143020,-0.093379,-0.284525,0.027048,-0.046009,-0.905229,0.213346,0.074743,0.171223,-0.372924,0.214667,-0.194603,-0.112905,0.112978,-0.270909,0.374004,0.385120,0.182640,0.172213,-0.081959,0.067108,-0.547224,0.257937,0.629467,-0.022400,-0.227270,0.286966,-0.417033,-0.408229,0.074489,-0.401221,-0.243597,-0.055483,0.163744,-0.341265,-0.208870,0.220787,-0.406152,0.083187,-0.146828,-0.138813,-0.233092,-0.295807,-0.160464,-0.578980,-0.110219,-0.456710,-0.431220,-0.075466,0.031652,-0.135317,0.452369,-0.712441,0.044607,0.747107,0.100366,-0.270339,0.737432,0.145584,0.225826,-0.208731,-0.071733,0.030667,0.009243,0.486009,0.223585,0.445160,0.026505,-0.530461,-0.329917,0.482446', '1793491', '1947080', '1299932', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1807495', '夏日时光机', '喜剧', '这是一个热得不能再热的夏天。科幻协会的7位好朋友：河本（瑛太饰）、曾我（与座嘉秋饰）、遙（上野樹里饰）等人逗留在学校里玩耍。某日，他们在房间的一角突然发现了一个凭空冒出的时光机！心绪激荡的众人开始讨论起他们的时光之旅，他们一致决定要回到昨天拿回不小心弄坏的空调遥控器——这天气，没空调可不好活啊。穿越时空的人并不是游刃有余的，肆意更改过去可能会引起不良后果，“严重的话，一切都会消失。”研究员穗积（佐々木蔵之介饰）下出如此判断。大家开始恐慌起来，为了一个小小的遥控器，他们竟会因此消失吗？©豆瓣', '永山瑛太', '本广克行', 8, 13647, 'tt0498567', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p540520721.jpg', 0.5, 1.7, 21.5, 49.3, 27, '0.457399,0.158938,-0.800424,0.273188,-0.008596,-0.167960,0.807003,0.148379,-0.602931,-0.322223,0.108613,0.659593,-0.296103,0.251498,0.067952,0.089088,-0.571164,-0.599897,-0.132523,-0.280576,-0.472383,-0.140636,0.029329,-0.295228,-0.242552,0.032589,0.242614,0.232895,-0.200743,0.202898,0.154020,-0.071194,0.056440,0.572274,-0.209763,0.072244,-0.409037,0.231639,-0.031480,0.279008,0.227835,-0.177103,-0.199636,0.066029,0.220504,0.079594,0.508378,-0.166785,-0.382134,0.163571,0.361512,-0.275860,-0.147774,-0.044571,0.316799,0.042435,0.077123,-0.094890,-0.284317,0.112236,-0.025575,0.042827,-0.377184,0.366264,-0.342656,0.360461,-0.340338,0.254983,-0.056165,-0.109394,-0.136646,-0.480134,0.191204,0.221608,0.271450,0.333949,-0.325768,-0.137411,-0.306482,0.048310,0.755826,-0.184978,-0.348257,0.449496,-0.083366,-0.312068,-0.164324,0.009256,-0.448466,-0.229597,0.382357,0.046789,-0.047431,0.145127,-0.448195,0.092330,-0.062700,-0.393411,-0.042289,-0.050435,-0.178400,-0.206667,0.070168,0.057948,-0.491160,0.467285,-0.085136,-0.209161,0.492745,-1.020915,0.249759,0.554564,0.122141,-0.394893,0.290532,0.040925,0.009449,0.211848,0.029179,-0.127877,0.034861,0.638749,0.294817,0.483420,0.097303,-0.065773,-0.501632,0.002256', '1308755', '30210700', '1301022', '1937946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1807966', '烈火中永生', '剧情', '重庆解放前夕的1948年，自知良日不多的国民党开始对共产党人与进步人士进行疯狂的屠杀。江姐（于蓝）在丈夫被杀后，收拾心情来到华蓥山区参加农村武装革命，由于叛徒甫志高的出卖，她和重庆地下党组织领导人许云峰（赵丹）被捕并被囚禁在渣滓洞集中营。国民党先后对许云峰和江姐威逼利诱、严刑拷打，妄图从他们口中得到有关地下党的线索，告失败。而在肉体被折磨时，许云峰和江姐精神上反是越挫越勇，他们带领狱友小萝卜头（方舒）等同国民党展开了一次又一次的斗争。1949年4月，解放军横渡长江，重庆解放在即，许云峰、江姐等人通过在集中营装疯卖傻10余年的华蓥山区党委书记华子良与外面的党组织取得了联系，开始策划越狱行动。©豆瓣', '赵丹', '水华', 7.8, 4558, 'tt0483922', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1322238680.jpg', 1.3, 2.5, 26.1, 47, 23.1, '0.258563,-0.211687,-0.804262,0.288514,0.018713,-0.224316,0.430955,0.073410,-0.718790,0.300596,0.080831,0.463814,-0.371038,0.112193,0.231881,-0.381380,-0.567748,-0.855083,-0.169951,-0.135272,-0.221672,-0.539031,-0.089662,-0.227750,-0.077415,-0.140498,0.611590,0.258836,-0.323969,0.446429,0.325331,0.284593,-0.101028,0.465775,-0.094437,0.025744,0.135159,-0.177724,-0.437429,0.392116,0.150456,-0.350029,-0.177456,-0.018351,0.043497,0.192269,0.658927,-0.298656,-0.072784,-0.209817,0.165935,-0.525861,-0.317042,0.212108,0.673862,0.229542,0.025629,0.585762,-0.110399,-0.061011,-0.156018,-0.343216,-0.437538,-0.118136,0.044911,-0.074282,-0.614056,0.527215,0.052324,0.459831,0.241273,-0.342221,0.200635,0.658789,-0.025446,0.563517,-0.235844,-0.177730,-0.400708,0.299794,0.788798,-0.256589,-0.001200,-0.104697,0.233747,-0.326274,0.026993,-0.180798,0.163791,-0.097373,0.115574,-0.098265,-0.226429,0.116822,-0.659830,-0.117149,-0.277008,-0.175160,0.164397,-0.239574,-0.063162,-0.648438,-0.366546,-0.233265,0.019126,0.239358,0.069661,-0.159646,0.534678,-0.986738,0.334380,0.340095,0.362113,-0.681982,0.266212,0.335918,-0.095486,-0.151889,0.133968,0.229944,0.326143,0.723198,0.320955,0.186133,-0.278842,-0.083444,-0.135409,0.150061', '1293265', '30345227', '1301022', '26316956');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1808049', '小飞龙', '动画', '距今约5000年前，云集着智者和贤达的神秘之岛亚特兰大陆一夜之间沉没。大西洋底的波塞冬族向亚特兰大陆的飞龙族发起进攻，在强大邪恶的攻势之下，飞龙族彻底覆灭。飞龙族首领将其尚在襁褓中的儿子托付给白海豚露卡（北浜晴子 音），露卡把婴儿藏到日本海附近的猪首岬岩洞中。最终，好心的渔夫一平（八奈見乗児 音）发现了婴儿，将其带回家抚养。13年后，阿龙（塩屋翼 音）已经成长一个少年。是时村中遭到海怪袭击，阿龙在露卡的引导下找到海龟梅顿，终于从它的口中得知自己的身世。一曾迷惑的阿龙最终选择披上红色披风，拿起短剑，和露卡向着波塞冬族占领的大西洋进发……本片根据手冢治虫同名原著漫画改编。©豆瓣', '塩谷翼 (voice)', '富野由悠季', 8.1, 5805, 'tt0189171', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p740285377.jpg', 0.3, 1.2, 22.4, 46.1, 29.9, '0.123064,0.297078,-0.460508,0.824634,0.151813,-0.003806,0.606254,-0.130278,-0.128381,-0.287401,0.177139,0.630999,0.191087,0.370486,0.156909,0.131459,-0.113585,-0.568784,-0.391275,-0.027930,-0.365504,-0.180760,-0.318135,-0.018471,0.093133,-0.263852,0.765749,0.161546,-0.321536,0.264004,0.293149,0.482466,-0.506326,0.095162,-0.336594,0.282950,-0.192087,-0.148571,0.003511,0.518551,-0.229601,-0.094694,-0.033779,0.301709,0.027045,0.356594,0.920375,-0.521124,0.132657,-0.241747,0.155244,-0.146871,0.042119,0.100065,0.803739,0.042193,0.109875,0.095134,-0.134239,-0.205301,-0.013179,-0.031839,-0.326233,0.091532,0.059866,0.182005,-0.520277,0.081971,0.012986,0.218178,0.306124,-0.363865,-0.003158,0.326031,0.098664,0.386944,-0.040973,0.286393,-0.254569,-0.013475,0.402924,-0.312929,-0.102955,-0.220491,0.316014,-0.510183,0.032205,-0.159957,-0.141710,-0.215552,0.615368,0.244562,0.069254,0.455245,-0.824249,-0.030471,-0.324681,-0.385239,0.264229,-0.169211,-0.317309,-0.307393,-0.077495,-0.106906,-0.007640,0.165803,0.088629,-0.116219,0.670751,-0.529612,0.190267,0.318223,0.233786,-0.087527,0.357469,-0.347830,0.079419,-0.106349,0.261433,0.352861,0.244723,0.250493,0.170293,0.196156,-0.127835,-0.248847,-0.487322,0.293671', '26290398', '1467779', '24879819', '2252594');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1810604', '超人4：和平任务', '动作', '轰动世界的第一英雄——超人，重返地球，接受大敌挑战，对手是坏蛋雷克斯，他针对超人的弱点，用氪元素制造邪恶的核能人，利用最先进的科学武器，面对势均力敌的对手，超人与其展开太空大对决……本片无论从情节上还是特技上，都是超人系列的最失败的作品。情节简单幼稚，特技粗糙。本集上映后，批评如潮，这也结束了里夫的超人生涯……', '克里斯托弗·里夫', '西德尼·J·弗里尔', 5.9, 4335, 'tt0094074', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2190238240.jpg', 7.1, 22.9, 48.3, 13, 8.8, '0.129182,-0.042749,-0.286447,0.544295,0.081366,0.226632,0.530560,-0.294906,-0.125067,-0.144050,0.537132,0.749435,-0.161325,-0.580314,0.191043,-0.319095,-0.368456,-0.340067,0.155901,0.072858,-0.288529,-0.499096,-0.789016,-0.126120,0.378807,-0.490031,0.839873,0.066093,-0.897892,0.038794,0.484065,0.021901,0.153867,0.181050,0.182512,-0.432349,-0.229521,0.177367,-0.365400,0.332036,-0.209970,0.015104,0.126825,0.311042,-0.476828,-0.089484,0.509145,-0.651313,0.188016,-0.303671,0.651687,-0.547535,-0.363440,-0.154435,0.081749,-0.187202,0.042408,0.038132,0.623679,0.263630,-0.059659,-0.123928,-1.311402,-0.112767,0.185109,-0.268145,-0.252728,0.354151,-0.105597,0.138718,0.033978,-0.125637,-0.037793,0.004936,0.624337,0.363201,-0.131224,-0.001633,-0.051285,0.433117,0.288269,0.039172,-0.826663,0.259445,-0.017806,-0.463992,-0.348750,-1.054414,-0.309672,0.070843,0.092728,0.012384,-0.157786,0.408160,-0.723134,0.329882,0.062495,-0.116493,-0.095487,-0.271461,0.081933,-0.876129,-0.078954,-0.236964,-0.240734,-0.077676,0.166568,-0.575376,1.088904,-0.665171,-0.083859,0.611955,0.324757,-0.302917,0.544796,0.035903,-0.174300,-0.529244,-0.343901,0.211017,-0.117611,0.341566,-0.175128,0.354459,0.319037,-0.314266,-0.316761,0.810435', '27602116', '24284209', '27098364', '6844861');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1811755', '超人集中营', '喜剧', '别看如今的杰克（蒂姆·艾伦 Tim Allen 饰）肚大腰圆，他可是曾经为政府所雇佣的超能力秘密特工，当年，为了消灭人类最强大的敌人“激进派”，杰克不仅失去了他的战友们，同时也失去了自身的超能力。军队放弃了再也没有利用价值的杰克，后者则过上了梦寐以求的正常人的生活。二十多年后的今天，当“激进派”分子再一次蠢蠢欲动的时候，军队再度的找到了杰克，这一回，他将扮演一个十分特殊和重要的角色。杰克的任务是教导四个个性极其顽劣的的孩子，教他们如何正确使用和控制各自强大的超能力。对于杰克来说，这四个孩子可比曾经所遇见的所有敌人加在一起都要难对付的多，年事已高的他能够顺利的完成任务吗？©豆瓣', '蒂姆·艾伦', '彼得·休伊特', 5.5, 3935, 'tt0383060', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193565854.jpg', 6.7, 29, 51.1, 9.8, 3.4, '0.352439,-0.039141,-0.553964,0.755853,-0.582824,-0.314090,0.638771,-0.214863,-0.539713,-0.350221,0.085941,0.749541,0.421672,0.020296,0.004418,-0.269525,-0.110287,-0.523968,-0.149419,-0.203099,-0.454554,-0.603413,-0.532280,-0.325628,-0.081156,-0.467310,0.794652,0.015341,-0.222859,0.017225,0.351217,0.330218,0.269883,0.174439,-0.172687,-0.239113,0.067709,-0.130612,-0.266367,0.283453,0.057067,-0.000774,-0.037067,0.578116,-0.038808,0.247941,0.537655,-0.594151,-0.379035,-0.354897,0.312520,-0.327438,-0.112687,0.028092,0.178503,-0.056087,0.309154,0.195220,0.079564,-0.040548,-0.015078,0.014780,-1.458440,-0.202032,0.291081,-0.312190,-0.664130,0.286572,0.002386,-0.058810,-0.006253,-0.334398,0.203475,0.739280,0.115997,0.252283,-0.406872,-0.052915,-0.559675,0.245701,0.899960,-0.045078,-0.464297,0.238265,-0.252325,-0.498332,-0.232654,-0.700137,-0.274480,0.309123,0.340821,0.330556,-0.294239,0.241569,-0.560738,0.152062,-0.277704,-0.163761,-0.030468,-0.578343,0.110189,-0.572130,-0.095554,-0.456689,-0.401987,0.112219,0.123900,-0.340721,1.093450,-0.978509,0.102390,0.617846,0.230992,-0.736089,0.420876,0.076932,0.252686,-0.326298,-0.174879,0.110605,0.190283,0.416960,0.162883,0.345001,0.185123,-0.311664,-0.294667,0.753542', '30163500', '1793491', '26678784', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1815487', '新扎师妹3', '喜剧', '钟sir（许绍雄饰）与伙计遇到交通意外，幸得有心地善良的范树娃（薛凯琪饰）的救助。钟sir眼看树娃的善良与智勇，便设法让家中贫困的树娃进入了警校。在警校中，钟sir及伙计们努力让树娃得到好成绩，好让她能进入自己的队里。树娃最后也被派到了钟sir的一队，得知树娃想嫁一个有钱人，关爱树娃的众人也极力帮忙，刚好一个从日本来的刑警伊豆（铃木仁饰）前来搜集钟sir那组的偷懒证据，大家想撮合伊豆及树娃两人。得知伊豆的真实身份后，不服输的他们决定在限定的时间内破一宗大案。刚好警队高层的女儿跟犯罪分子勾结，树娃无意间发现了真相，便开始了他们的破案行动……©豆瓣', '薛凯琪', '马伟豪', 4.7, 5984, 'tt0816663', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2525736229.jpg', 19.9, 37.2, 33.9, 5.9, 3.1, '0.351788,0.174646,-0.716057,0.537036,-0.290944,-0.177787,0.377014,-0.025211,-0.562867,-0.350651,-0.051980,0.618755,-0.111858,0.421721,0.293485,-0.072076,-0.103224,-0.773346,0.129564,-0.287955,-0.434959,-0.268471,-0.032196,-0.363570,-0.106768,0.117511,0.158169,0.377575,0.008790,0.409205,0.263643,0.104455,-0.137370,0.482706,-0.276387,0.014796,0.158123,0.006916,-0.034569,0.226008,0.123766,-0.469018,-0.251785,0.209813,0.306911,0.524964,0.588918,0.048609,-0.226183,0.135978,0.243275,-0.237347,0.110695,0.242686,0.570079,0.083687,0.074975,0.088247,-0.421631,0.188583,-0.146297,-0.064182,-0.805780,0.007000,0.161907,-0.153319,-0.671084,0.225769,-0.011747,-0.183885,0.089349,-0.301835,0.179619,0.632622,-0.046892,0.105265,-0.153873,-0.061762,-0.528894,0.158512,0.618372,-0.081699,0.118422,0.050726,0.128651,-0.734984,0.007064,-0.220451,-0.134336,-0.075091,0.651670,-0.006715,-0.199729,-0.080859,-0.531474,-0.269943,-0.186583,-0.142802,0.012705,-0.403566,0.094887,-0.548281,-0.193555,-0.302794,-0.249267,0.380673,0.103281,-0.231088,0.967935,-0.774183,-0.167472,0.537816,0.251324,-0.772442,0.782997,0.217924,0.194022,-0.065431,0.138301,-0.222778,0.290900,0.581864,0.251178,0.378262,-0.127620,-0.471863,-0.572643,-0.071495', '1296770', '4301278', '1877596', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1815638', '录取通知', '喜剧', '高中毕业生巴特比（贾斯汀·朗 Justin Long 饰）被无数大学拒之门外，面对父母的压力，巴特比找了一群和他有同样经历的哥们，租了一栋废弃的两层楼的楼房，自己办起了一所叫“南方哈门工业大学”的学校。这间学校的宗旨就是“谁都能来上大学”。原本打算只是为了蒙混父母，没想到一下子就有全美就有几百名遭遇一样的高中毕业来报到。其中一个学生的遭遇几乎代表了这里的所有人――当他收到录取通知时，他的父母第一次对他说出了“你是我的骄傲”。巴特比他们只好忙前忙后，聘请教师、逐渐完善教学设施等。随着学校的名气越来越大，引起了另一所“哈门”大学校长的注意……©豆瓣', '贾斯汀·朗', '斯蒂夫·平克', 7.6, 73331, 'tt0384793', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1035650502.jpg', 0.5, 3.4, 32.2, 45.1, 18.7, '0.576648,-0.270460,-0.723781,0.603491,-0.261961,-0.366125,0.537735,0.135020,-0.434282,-0.379441,-0.028197,0.742924,-0.134159,0.569689,0.190796,-0.276464,-0.033217,-0.494956,-0.045308,-0.522367,-0.230646,-0.419584,-0.232923,0.046969,0.013364,-0.155272,0.306306,-0.084519,-0.160973,0.466234,0.258731,0.206482,0.418273,0.469973,-0.259013,-0.017010,0.077468,0.327193,0.176482,0.065025,-0.119927,-0.146241,0.008959,-0.184945,0.308838,0.365181,0.359360,0.549778,-0.132935,-0.164284,0.468572,0.034994,-0.070718,0.264629,0.561570,-0.101881,-0.024221,0.202809,-0.328197,0.037885,0.004905,-0.385716,-0.792734,0.139267,0.133719,-0.049695,-0.700527,0.444836,0.111853,-0.280936,-0.012931,-0.135876,0.247539,0.369728,-0.022371,0.561969,0.033797,-0.046282,-0.518340,0.192751,0.812680,-0.341500,-0.152816,0.029206,-0.296489,-0.266022,0.195651,-0.065410,-0.360884,0.196550,-0.015917,-0.102353,-0.280085,-0.213499,-0.428041,-0.104450,-0.193311,-0.454517,0.204676,-0.448263,-0.071260,-0.651265,0.072318,-0.335813,-0.248006,0.166383,-0.061467,-0.181275,0.888638,-0.980813,-0.129271,0.442091,0.596649,-0.527582,0.761912,0.009509,0.139557,0.044114,0.085665,-0.111608,0.037242,0.702382,0.086402,0.558538,0.160308,-0.631825,-0.034890,0.589492', '1292219', '1793491', '35144311', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1819388', '波斯王子：时之刃', '动作', '本片根据育碧软件公司2003年的同名电子游戏改编。十五年前，孤儿达斯坦（杰克·吉伦哈尔 Jake Gyllenhaal 饰）在市集上因英勇好战被波斯国王收养入宫。十五年后，长大成人的达斯坦随两位哥哥和叔父（本·金斯利 Ben Kingsley 饰）出征，奇袭圣城阿拉姆特，并得到国王许婚，将阿拉姆特公主塔米娜（杰玛·阿特登Gemma Arterton 饰）许配与他。达斯坦无意中得到了塔米娜公主竭尽全力保护的“时之砂”匕首，却被诬陷毒害老国王，被迫逃亡。为了洗清罪名，同时确保伟大的波斯帝国不至于沦落他手，达斯坦胁迫塔米娜公主与他一同进入了臭名昭著的“奴隶谷”，破坏了阿马尔酋长（阿尔弗雷德·莫里纳 Alfred Molina 饰）的鸵鸟大赛。在老国王的葬礼上，达斯坦终于发现了幕后凶手，而塔米娜公主也终将有关“时之砂”的秘密据实以告……©豆瓣', '杰克·吉伦哈尔', '迈克·内威尔', 7.2, 111627, 'tt0473075', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p591951327.jpg', 0.6, 4.7, 41.5, 42.6, 10.6, '-0.068698,0.145316,-0.238024,0.634911,0.413703,-0.131168,0.366844,0.010294,-0.360160,-0.413177,0.284620,0.889660,-0.133030,0.063412,0.582704,0.499886,-0.637275,-0.510580,0.026704,-0.354132,-0.071517,-0.541951,0.006637,-0.305708,-0.219353,-0.567251,0.503104,-0.261029,0.051304,0.495026,0.353579,0.286794,-0.075384,0.300407,0.024942,0.126527,0.182016,-0.407938,-0.176771,0.115059,-0.106199,-0.161765,-0.034641,0.092197,0.356263,0.321781,0.339913,-0.903544,0.559806,-0.571328,0.385899,-0.275614,0.383958,0.011950,0.224088,-0.159249,0.177378,0.417309,-0.107545,-0.410533,0.142696,-0.463907,-0.464429,0.130627,0.000688,-0.241723,-0.647686,0.262209,-0.266902,0.186385,0.137460,-0.155155,0.321752,0.516851,0.134261,-0.031201,-0.133650,-0.066920,-0.653547,0.179861,0.453371,-0.127370,0.039006,-0.166922,0.159856,-0.704122,0.163900,-0.546429,-0.345675,0.106984,0.292189,-0.223315,0.233659,0.589202,-0.370284,-0.601251,-0.927444,0.047612,0.388099,-0.400218,-0.000428,-0.373269,-0.037849,-0.095375,-0.050706,0.064788,0.235302,-0.189061,0.314583,-0.658350,0.303624,0.488862,0.305748,-0.486619,0.454085,0.069090,0.122588,-0.272130,-0.379524,0.535909,0.404209,0.175812,0.367456,-0.015722,0.188767,-0.127632,-0.223523,0.340494', '6390825', '2131654', '3285073', '24859795');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1819460', '搭车人', '动作', '暑假到了。女大学生格蕾丝•安德鲁斯（索菲亚•布什Sophia Bush饰）和同校男友吉姆•哈尔西（扎卡里•耐顿Kyle Davis饰）打算一路开车前往墨西哥州，体验浪漫刺激的公路旅行。路上却撞见神色不太寻常的路人约翰•莱德尔（西恩•宾Sean Bean饰），请求搭顺风车。两个大学生虽然有所迟疑，但也答应了约翰的请求。怎知噩梦从此上演。约翰在车上毫不饰掩他的杀人计划，他以杀人为乐，并且目标说不定就是眼前两个手无寸铁的大学生。格蕾丝和吉姆惊恐万状，一番惊险搏斗终于把约翰推出车外，仓皇逃去。噩梦就此完毕？抑或一切还只是刚刚开始？©豆瓣', '肖恩·宾', 'Dave Meyers', 5.8, 5596, 'tt0455960', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2165258440.jpg', 7.2, 21.6, 51.1, 15.5, 4.6, '0.259579,-0.165763,-0.365897,0.219692,0.056247,-0.507909,0.512321,0.037263,-0.265421,-0.410450,0.033130,0.385085,-0.204327,-0.014158,0.532706,0.019577,-0.692328,-0.406473,0.151914,0.067630,-0.237303,-0.250964,0.096369,-0.286437,-0.097033,-0.125654,0.435054,0.024705,0.097133,0.767574,0.347970,0.309254,-0.237622,0.390224,-0.207108,0.058003,0.183278,-0.125634,-0.391250,0.040719,-0.009572,-0.071685,-0.262530,0.085456,0.055080,0.468910,0.600443,-0.012638,0.071593,0.103706,-0.071472,-0.261944,0.105982,0.209441,0.195876,-0.162410,0.026849,-0.009951,0.043572,0.183632,0.117037,0.108212,-0.115894,0.229476,-0.234244,-0.029790,-0.436805,0.145068,-0.074222,0.166770,0.148420,-0.196648,-0.139912,0.099655,0.279004,0.071271,0.142518,-0.017082,-0.377856,0.046398,0.555684,0.230796,0.006641,0.568726,0.037271,-0.257732,0.130163,0.033116,-0.490566,0.079172,0.301190,-0.063524,-0.189506,0.046767,-0.361743,-0.210030,-0.514079,-0.074214,-0.117923,-0.278734,0.014292,-0.924703,0.397189,-0.156332,-0.219725,-0.042604,0.038463,-0.023045,0.014058,-0.541748,0.068820,0.426027,0.103715,-0.230264,0.504202,-0.019778,0.093450,-0.265222,0.127905,0.149593,0.096248,0.256135,0.052392,0.386950,-0.024411,-0.114770,-0.081126,0.499861', '2075345', '1296339', '3036464', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1820145', '理发师陶德', '剧情', '受法官塔萍（阿伦`瑞克曼）陷害，被迫流放他乡15年的陶德（约翰尼`德普）回到伦敦后，满心的怒火，只想复仇。他的妻子露西（劳拉`凯利）已经不知所踪，而女儿乔安娜（珍妮`怀森纳）则被塔萍作为养女囚禁在深宅大院里。陶德遇到了馅饼店老板娘洛薇特夫人（海伦娜`卡特），也是一直爱恋他的女人。在馅饼店楼上，陶德重新开张了他的理发店。渐渐的馅饼的生意好了起来，只是烟筒里不断冒出恶臭的黑烟。理发店的客人也很多，却很少见到有人走出来。那里，陶德一直在等着法官塔萍的到来。©豆瓣', '约翰尼·德普', '蒂姆·波顿', 7.8, 145641, 'tt0408236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1662825746.jpg', 0.4, 2.6, 27.1, 47.1, 22.8, '0.167663,0.181017,-0.694330,0.199593,-0.128810,-0.588322,1.020618,0.505990,-0.445889,-0.255107,0.351360,0.864376,-0.311044,0.761351,0.436251,0.572895,-0.361931,-0.427035,-0.077084,-0.279088,-0.248831,-0.346333,-0.075457,-0.330927,-0.244687,0.072818,0.183713,0.233767,0.336221,0.017869,0.475359,0.007074,-0.071402,0.857650,-0.152436,0.330375,0.241729,-0.138024,-0.137508,0.053349,0.272171,-0.416098,-0.173858,-0.068102,0.240265,0.299106,0.405002,-0.040043,0.068041,0.090732,0.226075,-0.182254,0.167079,0.077525,0.410175,-0.184948,0.146016,-0.124904,-0.173498,-0.170474,0.095944,0.073381,-0.356235,0.193640,-0.129035,0.345279,-0.739135,0.499852,-0.152677,0.159555,-0.074763,-0.470926,0.247440,-0.130786,-0.151548,0.345186,-0.395296,0.045313,-0.686410,0.064864,0.465616,0.065742,0.006777,0.162788,-0.251664,-0.266934,0.318768,0.116232,-0.456643,-0.262700,0.427200,-0.015163,-0.257679,0.164746,-0.417285,-0.130282,-0.394155,-0.147285,-0.035530,-0.135969,-0.361835,-0.618367,-0.137067,-0.223691,-0.255585,-0.077174,-0.123985,0.016213,0.239504,-0.744782,0.332749,0.582299,0.120723,-0.200154,0.447288,-0.253293,0.234594,0.150481,-0.164513,0.312237,0.080289,0.449519,0.362573,0.531124,0.107903,-0.138511,-0.075630,0.556392', '21348112', '1309172', '1301686', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1820156', '我是传奇', '剧情', '2012年，人类被不知名病毒感染，纽约成为一座空城。Robert Neville（Will Smith 饰）是为军方服务的科学家，也是对病毒有免疫力的幸存者。白天，他带着狗Sam在街道上寻找食物，用广播寻找幸存者，在实验室里研究治愈病毒的方法；晚上，他只能躲在屋子里，因为那些感染病毒而没有死亡的人们，成为了“夜魔”只能夜晚出来活动，丧失理智，会攻击所有的人。某天，Sam也感染病毒死去，Robert Neville陷入了前所未有的孤独。当他准备和“夜魔”们同归于尽的时候，另外一个幸存者Anna(Alice Braga 饰)救了他。Anna相信山上的隔离区还有幸存者，但是固执的Robert Neville却坚持守在纽约。又一个晚上，“夜魔”攻击Robert Neville的住所，此时他的研究已经获得成功，但是只有坚持到天亮，人类才能得以延存。©豆瓣', '威尔·史密斯', '弗朗西斯·劳伦斯', 8.1, 384835, 'tt0480249', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p574158935.jpg', 0.3, 1.5, 19.1, 49.3, 29.8, '0.137117,0.002879,-0.601199,0.177670,-0.199013,0.066812,0.958674,-0.069461,-0.516730,-0.229233,0.405246,0.494168,0.166944,0.311455,-0.076244,-0.180691,-0.452229,-0.366805,0.034168,-0.108076,-0.711941,-0.158548,-0.478939,-0.573879,0.121624,-0.373605,0.694409,0.450067,-0.250245,0.182856,-0.012395,0.319673,0.014750,0.758601,-0.387280,-0.285076,-0.040180,-0.456967,0.022585,0.490790,-0.024363,-0.322911,-0.158781,0.241235,-0.036438,0.354906,0.715026,-0.376501,-0.164913,-0.234813,0.167168,-0.622274,-0.130881,0.094263,0.442843,-0.181079,0.077345,0.059026,-0.076005,0.003501,-0.097986,0.251804,-0.957538,-0.112962,0.005399,0.396221,-0.478374,0.481344,0.183640,0.076450,0.038510,-0.403865,0.343842,0.162209,0.020723,0.476318,-0.170922,-0.134412,-0.866678,0.092736,0.725558,-0.439254,-0.310280,0.380575,-0.386042,-0.664198,-0.103562,-0.433881,-0.313834,-0.226769,0.099211,0.305666,-0.564701,-0.052313,-0.614992,0.166058,-0.123941,-0.574985,-0.106950,-0.190499,-0.169154,-0.839716,-0.005043,-0.156875,-0.233898,0.275143,0.043670,-0.202819,0.893635,-0.876897,0.381632,0.777976,0.445989,-0.694149,0.815863,-0.059003,-0.043752,0.186977,0.151970,0.311384,-0.118085,0.685145,0.198197,0.250295,0.007606,-0.033729,-0.561798,0.520558', '3005387', '13