INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1824412', '哈拉十诫', '喜剧', '影片彻底颠覆了经典《十诫》的“人神契约”，由10个相互独立又彼此相关的幽默小故事串联而成。贯穿始末的叙述者，用戏谑的口吻向观众娓娓道来这十个令人瞠目结舌的短篇：一个忘背伞包却奇迹生还的跳伞男子，居然瞬间成为电视明星；一个把自己处子之身献给耶稣的老处女；一个不告诉儿子生父是谁的母亲；一个拿病人生命开玩笑的医生，在下一章节被抓入狱，遭受性虐待却被视为稀松平常之事……叙述者一直置身事外的讲述这段段荒诞不经的故事，直到他“通奸”的故事上演。©豆瓣', '保罗·路德', '大卫·韦恩', 6.5, 8366, 'tt0811106', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p795881238.jpg', 3.8, 13.3, 47, 27.1, 8.7, '0.275575,-0.015927,-0.337128,0.664177,-0.113452,-0.170712,0.954238,-0.292641,-0.129284,-0.114784,0.266130,0.790047,-0.681939,0.253165,0.144265,0.013019,0.048211,-0.843288,-0.234853,0.118767,-0.242545,-0.481806,-0.240183,0.025067,-0.114605,-0.078664,0.492538,-0.255802,-0.308585,0.162422,0.254997,0.134544,-0.139877,0.163327,-0.208059,0.152416,-0.337930,-0.078737,0.048360,-0.115061,-0.071571,-0.222094,0.002660,0.201083,-0.549999,0.223885,0.723688,-0.404840,-0.125328,-0.083433,0.822835,-0.348126,-0.272395,0.131482,0.066102,0.135368,0.155925,0.361543,0.003611,-0.152156,0.208935,-0.030532,-1.025224,-0.321359,-0.158174,0.291827,-0.386872,0.222535,-0.165439,0.226811,0.122925,-0.249255,0.090618,0.126780,0.427835,0.832197,-0.185287,-0.022035,-0.298707,0.328863,0.336790,0.091094,-0.528109,0.517392,-0.102783,-0.289339,-0.015945,-0.045775,-0.428673,0.209051,0.288844,-0.232798,-0.080482,0.420286,-0.441748,-0.212589,-0.033885,-0.132194,0.085986,-0.624369,-0.335321,-0.288452,-0.239261,-0.148965,-0.148949,-0.060725,0.459174,-0.222778,0.835184,-0.188404,0.151554,0.413187,-0.174146,-0.337462,0.502185,0.306783,0.199644,-0.005707,0.095565,0.075502,0.370376,0.373252,0.323022,0.460486,0.053225,0.104904,-0.663865,0.223854', '1422088', '27602116', '1294434', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1824414', '幸运查克', '剧情', '查克（戴恩·库克 Dane Cook 饰）在10岁的一个游戏上，得罪了“小巫婆”。她下了一个毒咒在查理身上。成年后查理成为一名牙医，成功的事业并没有令他过得开怀——他从来没有获得过真爱，奇怪的是，追求他、和他上床的女孩非常多，然而她们总是离他而去，并且下一任的男朋友总是她们的真名天子。查克慢慢察觉到，自己只不过是一道桥，帮助别人通往真爱所在，“幸运查克”的名号也是这么来。而这一切，原来都是因为当年的魔咒。当查理遇上凯姆（杰西卡·阿尔芭 Jessica Alba饰）并倾心爱上了她，真正的痛苦到来了。他不知道怎么做才能留住爱人，让她不再奔向下一个人。查理无微不至的宠爱凯姆，为她做饭给她送花，甚至为她约会她心仪的男生，祈求魔咒不会再应验。©豆瓣', '戴恩·库克', '马克·海尔弗里奇', 6.3, 26039, 'tt0452625', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456586319.jpg', 2, 12.9, 56.9, 22.5, 5.7, '0.187038,0.045516,-0.771899,0.668964,-0.703687,-0.359651,0.794177,-0.127050,-0.371779,-0.303820,0.215653,0.831655,-0.062245,0.262277,0.041990,0.370689,-0.099917,-0.558590,0.300635,-0.152384,-0.373516,-0.284942,-0.265848,-0.218960,-0.140290,-0.191950,0.426807,-0.121261,0.007298,0.223679,0.412721,0.093036,0.454089,0.661996,-0.393060,0.136482,0.084579,0.012972,0.066242,0.282712,-0.082612,-0.211763,-0.239303,0.492393,-0.266718,0.231842,0.269657,-0.314651,-0.209843,-0.175534,0.308613,-0.304097,0.268038,0.137558,0.062726,-0.211956,0.191195,0.126668,-0.165105,0.023474,0.072580,0.040855,-0.886728,0.090656,-0.184396,0.163624,-0.609880,0.252733,-0.307486,-0.153398,0.128023,-0.532135,0.127570,0.128033,0.157046,0.224680,-0.563193,-0.012436,-0.614049,0.209205,0.853035,0.164658,-0.142708,0.524676,-0.145534,-0.336644,0.100375,-0.140999,-0.637871,0.085720,0.159627,0.077020,-0.130933,0.135785,-0.261156,-0.067138,-0.299619,-0.112226,-0.073671,-0.517762,0.011632,-0.103047,-0.091085,-0.451206,-0.439729,-0.120641,-0.098005,-0.573874,0.617707,-0.902724,0.446196,0.805159,0.476865,-0.608596,0.770689,0.415828,-0.037424,-0.127591,-0.185674,0.513816,0.028726,0.151143,0.054323,0.304297,0.268804,-0.080277,-0.307264,0.791067', '1304977', '1949005', '6874741', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1826173', '网球王子', '动作', '在美国长大的网球天才少年越前龙马（本乡奏多 饰）被父亲召唤回到了日本，进入到网球名校青春学园。起初，并不把学园前辈放在眼里的龙马也在轮番接触后了解到青春学园网球部的厉害。他们的成员包括了队长手冢国光（城田优 饰）、副队长大石秀一郎（铃木裕树 饰）、腹黑的不二周助（相叶弘树 饰）、元气满满的菊丸英二（足立理 饰）、数据控乾贞治（荒木宏文 饰）、热血的河村隆（小谷嘉一 饰）、龙马的好朋友桃城武（加治将树 饰）以及桃城的死对头海堂熏（鲸井康介 饰）。各具特色的前辈给龙马带来不一样的冲击，包括对友谊、团队的认知。和手冢交锋的失败让龙马受挫，意志消沉。在不佳的精神状态中，迎来了关东大会。青学的首个对手就是实力强劲的冰帝。经过一番死斗之后迎来了龙马出战的大高潮，究竟结果会是什么，龙马能否从阴影中走出，重拾自我……©豆瓣', '本乡奏多', '阿部雄一', 6.5, 6996, 'tt0824406', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2508638583.jpg', 3.7, 12, 50.6, 24.6, 9.1, '0.065219,0.064464,-0.527866,0.368148,0.010161,-0.302973,0.228802,0.311030,-0.301999,-0.187193,0.220560,0.367738,-0.201016,0.296005,0.287745,-0.103048,0.075348,-0.842574,-0.317377,-0.017034,-0.308625,-0.272147,-0.076424,0.199817,-0.149459,-0.426833,0.888028,0.037870,-0.353734,0.619620,0.291893,0.287068,0.141695,0.098636,0.085780,0.004593,0.205318,0.144808,-0.081694,0.246990,-0.038043,-0.141931,-0.186269,0.187554,0.372116,0.082214,0.809551,-0.253013,0.069956,0.000709,0.247500,-0.167012,-0.115745,0.322272,0.507870,0.233042,-0.078673,0.264820,0.002749,0.417579,0.000711,-0.120533,-0.562060,0.088255,-0.020419,0.264881,-0.371802,0.895213,-0.044005,-0.382231,0.386063,-0.102720,-0.035412,0.306880,0.333725,0.118455,-0.310995,0.147493,-0.001458,-0.039532,0.719507,-0.281810,-0.083655,0.122950,-0.089049,-0.414620,-0.321614,-0.258166,-0.101511,0.005608,0.271888,0.233316,0.163569,0.130398,-0.601081,-0.012777,0.010694,-0.166414,0.084619,-0.312477,0.040919,-0.531939,-0.061096,-0.537493,-0.359404,0.094104,0.197471,-0.148937,1.040895,-1.116807,-0.134460,0.431101,0.243767,0.010501,0.321400,0.036565,-0.199809,-0.156780,-0.225667,0.131957,0.096064,0.458100,0.217778,0.650875,0.094470,-0.432786,-0.344421,0.280024', '4127270', '26999591', '26784898', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1827042', '伊丽莎白2：黄金时代', '剧情', '1585年，此时伊丽莎白一世（凯特•布兰切特 Cate Blanchett 饰）已经52岁。她单身未嫁，政治手腕已经非常成熟，处理国务也比年轻时得心应手。她思想开明，允许人们信仰罗马天主教。然而，却屡屡受到苏格兰女王玛丽•斯图亚特的种种对抗，玛丽甚至派杀手暗杀伊丽莎白未遂。另一方面，女王还面临着西班牙这个宿敌。西班牙和英国之间的宗教差异，加之海盗活动猖獗的现况，使得二国矛盾日渐尖锐，为日后的战争埋下伏笔。罗利带着海外新鲜的探险经历在女王面前出现，令女王多年尘封的心有了悸动。然而，女王的爱情，注定了要屈服于国家的利益。在英国与西班牙的战争中，女王展现出的强大魄力，把大不列颠推向霸主的辉煌巅峰。©豆瓣', '凯特·布兰切特', '谢卡尔·卡普尔', 7.4, 22196, 'tt0414055', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2195707180.jpg', 0.5, 3.9, 36.9, 43.3, 15.5, '0.191638,0.328054,-0.789507,0.704671,0.207282,-0.180561,0.580496,0.130320,-0.566055,-0.190556,0.317696,0.582620,-0.146729,0.067243,0.529735,-0.156119,-0.192586,-0.725082,-0.055939,0.160847,-0.108578,-0.325654,-0.666898,-0.249065,-0.516926,-0.685280,0.826446,0.154626,-0.275886,0.464631,0.142195,0.410955,0.070926,0.342569,-0.097198,-0.369076,0.293601,0.014598,-0.474405,0.070967,-0.072679,-0.168651,-0.125333,0.380360,-0.237921,0.340090,0.256885,-0.560465,0.076624,-0.457584,0.549630,-0.195549,-0.208427,0.417388,0.526848,0.076423,-0.182572,0.407652,-0.011223,-0.227569,0.053445,-0.215893,-0.595463,0.000670,-0.024130,0.135498,-0.549254,0.409786,-0.192213,0.090200,0.089358,-0.063709,0.088622,0.524606,0.253467,0.323672,0.033252,0.145120,-0.297506,0.098868,0.794747,0.019154,-0.567546,-0.142411,-0.461115,-0.556160,-0.063417,-0.772526,-0.579664,0.004308,0.048026,-0.142827,0.020903,0.861736,-0.719552,0.121104,-0.402930,-0.220793,0.259941,-0.268060,-0.002689,-0.701462,-0.625380,-0.701518,-0.254056,0.098156,0.359605,-0.118420,0.872075,-0.809958,0.310939,0.697652,0.338166,-0.496580,0.530890,0.213768,0.046903,-0.176430,-0.340623,0.514469,-0.247237,-0.036400,-0.135417,0.046406,-0.027114,-0.139326,-0.075890,0.513037', '5308201', '1308837', '1763916', '10439358');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1827713', '卑劣的街头', '动作', '赵炳斗（赵仁成 饰）是一个三流社团的小头目，家中有两个弟妹，母亲身体不好，生活困顿；他在社团里也混得不如意，老大不器重，净派一些当街打架、恐吓收债的小事情，本来应该他接手的游戏厅也被别人抢了功。炳斗的同窗好友金珉浩（南宫民 饰）是一个不得志的小导演，为了拍黑帮片，找炳斗体验生活；在金珉浩的帮助下，炳斗也和初恋对象姜贤珠（李宝英 饰）重逢，但是炳斗黑社会的身份让贤珠心存芥蒂。终于，炳斗抓住了一个机会代替了老大，在社团中地位大大提升，他帮助清理拆迁中的钉子户，使社团新开发的房地产项目大获成功，自己也从中分了一杯羹；在他坚持不懈的努力下，贤珠渐渐接受了他的感情，他也答应退出黑社会，过平淡的生活。金珉浩的电影因为真实而深受好评，炳斗到电影院观看，正是这部电影，改变了二人的生活，事情往不可控制的方向发展©豆瓣', '赵寅成', '庾河', 8, 97060, 'tt0821442', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1877813710.jpg', 0.2, 1.3, 21.1, 51.4, 26, '0.094564,0.113088,-0.431658,0.544986,-0.213893,-0.143299,0.525412,0.219909,-0.370472,-0.087628,0.170609,0.611681,0.060522,0.327034,0.007863,-0.168726,-0.191449,-0.592523,0.057909,-0.023330,-0.145408,-0.174213,-0.338243,-0.264998,-0.421162,-0.016256,0.611618,0.013894,-0.450450,0.242897,0.360962,-0.069001,0.140866,0.273370,-0.041959,0.077310,0.079611,0.174531,-0.257360,0.243638,0.104821,-0.406819,-0.155966,0.079421,0.363348,0.456509,0.448834,-0.076469,-0.330848,-0.129652,0.230156,-0.274799,-0.226790,0.040377,0.155778,0.068349,0.298755,0.208764,-0.275957,0.018865,-0.180539,-0.289345,-0.799553,-0.115170,0.204735,0.085167,-0.702461,0.430376,0.029861,-0.190516,-0.049449,-0.314767,0.107476,0.433994,0.299084,0.306317,-0.420760,0.168259,-0.477107,0.436916,0.764886,-0.024280,-0.167444,0.360101,-0.197112,-0.285242,-0.063168,-0.252341,-0.391419,-0.152780,0.257545,-0.205994,-0.152452,0.217773,-0.397558,0.052141,0.003659,-0.153267,-0.092793,-0.466112,0.280904,-0.496996,-0.301668,-0.305851,-0.168544,-0.110761,0.195650,-0.407559,0.777145,-0.780911,-0.035084,0.507851,0.401004,-0.735113,0.601523,0.141822,0.091037,-0.241449,-0.106180,-0.098979,0.012268,0.218853,0.176916,0.434301,0.012249,-0.414629,-0.279351,0.448152', '1877596', '5985887', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1827955', '名侦探柯南：侦探们的镇魂歌', '动画', '一天毛利小五郎收到一张请帖，里面是谜样男子的委托，需要前往横滨的一个游乐场。小五郎和柯南一行人快乐地到达欢乐的游乐场，还带上了可以出入无阻代表VIP的手表，不料正中那名神秘男子的圈套。所有带上手表的人不得离开游乐场，否则便会发生爆炸。从现在开始到晚上十点，柯南和小五郎如果不能解开谜题，兰和少年侦探团也会随着游乐园粉身碎骨。然而更意想不到的是，那名男子居然直接称呼柯南为工藤新一。©豆瓣', '高山南', '山本泰一郎', 7.9, 96675, 'tt0498536', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2249750926.jpg', 0.3, 2.1, 25, 47.6, 25, '0.231134,0.186016,-0.667506,0.143786,-0.254005,-0.207946,0.805757,0.069354,-0.241947,-0.304963,0.083717,0.768837,-0.473380,0.494020,0.746097,0.248364,-0.404065,-0.629548,-0.217464,-0.520642,-0.555747,-0.315347,-0.001415,-0.292368,0.147133,-0.282716,0.320254,0.478018,-0.214410,0.728578,0.224957,0.271484,-0.322991,0.525656,-0.314731,-0.147883,-0.050069,-0.145371,0.036467,0.632265,0.040253,-0.118129,-0.144592,0.209067,-0.078023,0.181974,0.645357,-0.180890,-0.314959,0.173432,0.254566,-0.025062,-0.406325,-0.084397,0.292487,-0.118123,0.255612,0.279522,-0.270508,0.315628,0.202599,-0.173711,-0.452648,0.327392,-0.055830,0.286586,-0.105228,0.206358,-0.168204,-0.207915,0.279993,-0.561466,0.127537,0.147117,0.147613,0.268431,-0.114368,0.041281,-0.698524,-0.001647,0.475153,-0.023114,0.107582,0.352955,0.325765,-0.272486,-0.432232,-0.028488,-0.355979,0.314322,0.390002,0.140496,-0.128038,-0.464525,-0.540163,-0.085764,-0.399612,-0.326513,0.115659,-0.176197,-0.204485,-0.757320,0.292953,-0.044856,-0.184422,0.609700,0.245634,0.001861,0.835184,-0.670479,0.125433,0.552701,0.363894,-0.197521,0.507236,-0.093133,-0.096437,-0.303141,0.012499,-0.194932,0.459381,0.561016,0.128119,0.422043,-0.255017,-0.375415,-0.594000,0.188165', '1301686', '3811356', '10466639', '1293019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1828115', '色，戒', '剧情', '本是岭南大学学生的王佳芝（汤唯 饰）因战争辗转到了香港读书，她在香港大学加入了爱国青年邝裕民（王力宏 饰）组织的话剧组，他们主演的爱国话剧更激起了他们的爱国情操。当邝裕民得知汪伪政府的特务头子易先生（梁朝伟 饰）正在香港的时候，他们便密谋要刺杀易先生。化名“麦太太”的王佳芝很快得到了易太太（陈冲 饰）的信任与喜爱，同时美丽的“麦太太”也吸引了易先生的眼球，正当事情进行得如火如荼之际，易先生突然要回到上海去。此后王佳芝一直生活在上海，没想到重遇了邝裕民。当得知刺杀行动还没结束时，王佳芝再次成为了特务，再次以“麦太太”的身份出现在易先生的面前。重逢后的二人关系进一步发展，此时的易先生因爱上了王佳芝而对她毫无忌讳，王佳芝的内心也变得起伏不定。刺杀行动进行正顺利，但当易先生送给王佳芝璀璨钻戒表达爱意时，王佳芝做出了惊人的决定……©豆瓣', '梁朝伟', '李安', 8.6, 712218, 'tt0808357', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453716305.jpg', 0.3, 0.9, 12.3, 41.5, 45, '0.256847,0.032597,-0.463196,0.494093,0.210836,-0.546110,0.413019,0.357900,-0.443066,-0.477017,0.010175,0.534507,-0.233072,0.481295,0.381869,-0.127645,-0.209139,-0.630733,-0.081447,-0.015652,-0.166528,-0.642042,0.130771,-0.202362,-0.026140,-0.074441,0.365307,0.331724,-0.338094,0.490236,0.283323,0.161685,0.079050,0.834404,0.089053,0.048605,0.280741,-0.026428,-0.704993,0.228627,0.428382,-0.068808,-0.204085,0.211678,0.143214,0.184314,0.671799,-0.296458,-0.276097,0.117730,0.668992,-0.262670,0.350622,0.052347,0.491396,0.183628,0.106537,0.182476,-0.408746,0.009185,-0.025470,-0.110316,-0.551858,0.262406,0.143399,-0.050620,-0.539050,0.174031,-0.095607,0.242684,0.216619,-0.217844,0.396997,0.446288,0.253686,0.015128,-0.004335,0.101804,-0.332864,0.209525,0.655720,0.139950,0.101026,0.306732,-0.018700,-0.478769,0.071620,-0.094715,-0.123392,-0.223253,0.366630,-0.045295,0.008336,0.150975,-0.115291,-0.432079,-0.298771,0.183014,0.347100,-0.250731,-0.044819,-0.512548,-0.265917,-0.360867,0.097276,0.181478,-0.055532,-0.057242,0.703486,-1.012442,0.060923,0.471147,0.097131,-0.458391,0.682904,0.070621,-0.244824,-0.342140,-0.166802,-0.050909,0.087483,0.227702,0.359471,0.350324,0.076804,-0.186664,0.079579,0.194068', '1301022', '1292219', '2052978', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1829230', '舞出我人生', '剧情', '个性张扬的街头嘻哈与高贵典雅的芭蕾可以在舞台上完美的契合，就像泰勒（钱宁 •塔图姆饰）与诺拉（珍娜•迪温）的结合一样。这是一个奇迹，还是一种宿命。泰勒是来自巴尔的摩的底层社会的反叛青年，诺拉是就读与贵族艺校的优秀的芭蕾舞学生。诺拉要参加的高级舞蹈比赛，需要一个舞技超群的舞伴，而泰勒刚好因为被罚在艺术学校社区服务而闯入诺拉的视野。泰勒随意自如的街头舞蹈吸引了诺拉，舞台上的一次次合作，让这两个同样执着于艺术的孩子擦出律动的火花。两条原本平行的直线，交汇于舞蹈的光辉。©豆瓣', '查宁·塔图姆', '安妮·弗莱彻', 7.7, 90893, 'tt0462590', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p477592337.jpg', 0.3, 2, 29.7, 48.5, 19.5, '0.640163,0.101542,-0.573448,0.864379,-0.204920,-0.237759,0.834973,0.240762,-0.153013,0.112896,0.350567,0.977170,-0.234870,0.339596,0.471647,-0.059588,-0.101141,-0.989066,-0.188710,-0.128462,-0.354006,-0.632561,-0.307462,-0.085885,-0.048397,-0.508844,0.619394,-0.183994,-0.487183,0.776763,0.479480,0.175716,-0.144838,-0.084510,-0.366393,-0.578814,0.049775,0.197505,-0.222747,0.128833,-0.092475,-0.126934,-0.032718,0.011769,-0.159902,0.074674,0.861241,-0.348656,0.260078,0.045830,0.636454,-0.049859,-0.033079,0.050134,0.256320,-0.122832,0.076492,-0.071786,0.090938,0.069212,0.043545,-0.294711,-0.959758,-0.110415,0.120421,0.322883,-0.371141,0.808064,0.284210,-0.395930,0.254809,-0.226473,0.029057,-0.002458,0.198398,0.578460,-0.104757,-0.041521,-0.242219,0.218396,0.479826,0.357061,-0.614626,0.310025,-0.730054,-0.508630,-0.208059,-0.269192,-0.476906,-0.153012,0.295291,-0.058901,0.059607,0.245475,-0.750269,0.147347,-0.171194,0.112674,-0.126491,-0.552335,-0.136584,-0.841291,0.079833,-0.663170,-0.197074,0.041193,0.076660,-0.201952,0.943064,-1.113036,0.145888,0.666538,0.054436,-0.148552,0.870361,0.073634,0.240090,0.021866,-0.231634,-0.026798,0.135473,0.212495,-0.087094,0.913169,-0.046802,0.149467,-0.587999,0.753044', '3811356', '4127270', '3775163', '1292943');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1829654', '憨豆的黄金周', '喜剧', '憨豆先生（罗温•艾金森 Rowan Atkinson 饰）总是傻人有傻福。他买彩票意外获得前往法国度假的机会。憨豆先生马上收拾好行囊，前往法国圆他的先锋派电影之梦！抵达巴黎后，憨豆先生遇到了一位来自俄罗斯的戛纳电影节评委。奇思妙想的憨豆希望能拍摄一部关于自己的先锋派电影，于是做事从来不顾后果的他带上了与那位俄罗斯评委走散的儿子，两人跳上了火车，路上扮演一对父子，却因语言不通大闹笑话，最后陷入了困境。憨豆最后会被作为“绑架者”被捕还是凭借他的影片入围嘎纳，夺得大奖？©豆瓣', '罗温·艾金森', '史蒂夫·班德莱克', 8.1, 122748, 'tt0453451', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2191830473.jpg', 0.2, 1.6, 19.2, 48.4, 30.6, '0.141107,-0.009585,-0.518470,0.377338,0.229877,-0.577405,0.369332,0.190189,-0.207931,-0.213641,0.180862,1.093186,-0.330836,0.162807,0.492555,-0.062239,-0.591877,-0.394610,0.027256,0.073145,-0.043629,-0.159603,-0.274382,0.051371,-0.020117,-0.085410,0.445822,0.228768,-0.385568,0.525184,0.563108,0.110142,-0.008589,0.112249,-0.228427,0.191503,0.218881,0.058526,-0.354838,0.454724,0.143159,-0.007408,-0.144979,-0.147199,0.143363,0.181863,0.488744,-0.032058,-0.028617,0.026173,0.433126,-0.342396,0.046097,-0.110561,-0.189100,0.047665,0.245749,0.104159,0.017465,-0.027706,-0.021233,-0.287330,-0.636717,0.114049,-0.059439,0.153628,-0.464961,0.215867,0.018519,-0.002832,-0.096958,-0.213087,0.243703,0.256644,0.379037,-0.056224,0.149256,0.008510,-0.404111,0.363610,0.646010,-0.172040,-0.068510,0.272136,0.044779,-0.535362,0.210531,-0.267078,-0.444029,0.476433,0.586555,-0.343654,-0.006592,-0.027144,-0.472144,-0.042150,-0.209750,-0.220479,0.058979,-0.120446,0.133644,-0.850754,0.162687,-0.036020,0.000625,-0.119424,0.082925,-0.144621,0.660897,-0.411905,0.140530,0.541577,0.342841,-0.327937,0.783920,0.045601,-0.026564,-0.098478,-0.009044,0.060503,-0.086868,0.123915,0.126697,0.272141,0.013055,-0.366490,-0.276832,0.231864', '34890458', '30162520', '1299166', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1830189', '黑楼孤魂', '剧情', '文革中，少女小菊一家遭人迫害，小菊本人被吊死在自家，凶手将现场伪装成自杀……一晃十几年过去，一部电影正在紧张的拍摄，录音师霍峰（陈希光 饰）对现场效果不甚满意，带女主角于红（潘婕 饰）回住处做音效。霍峰所住的旧楼面临拆迁，大多数住户早已搬离，只留下老领导老林、无业青年由飞以及霍峰三家。于红在楼内看到异样幻象，霍峰的录音设备也采样到诡异的响动。二人调查这栋楼的历史，获悉小菊的冤案，始明白小菊那地下室的冤魂在人去楼空之时向当年的凶手索命。老林与由飞身上先后发生意外，于红发现导演郑磊（韩小磊 饰）亦与当年的凶案有关，并最终决定帮助小菊复仇。©豆瓣', '陈希光', '梁明', 7.2, 13237, 'tt6047232', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2868201737.jpg', 1.7, 5.1, 37.4, 41.3, 14.5, '0.067847,-0.096751,-0.608964,0.075362,0.207971,-0.147338,0.770963,-0.022157,-0.459628,-0.428143,0.286933,0.633411,-0.267409,0.330754,0.225627,-0.109790,-0.219757,-0.390363,-0.274037,-0.304443,-0.178912,-0.289885,0.020933,-0.312090,-0.077025,-0.105078,0.386767,0.204551,-0.205856,0.374994,0.411260,0.255483,-0.623674,0.080295,0.071038,0.081834,-0.123374,-0.129248,-0.566493,0.036724,0.027897,-0.234331,-0.234789,-0.305894,-0.053088,0.360564,0.647235,-0.174669,-0.359723,0.039407,0.227238,-0.131743,-0.026034,0.263160,0.493825,0.150517,0.153482,0.333720,-0.435089,0.163081,-0.101652,-0.031543,-0.480107,0.189257,0.333849,0.256623,-0.251412,0.337495,-0.171802,0.106295,0.055136,-0.342537,0.365195,0.030495,0.194095,0.482977,-0.280605,-0.004408,-0.307922,0.116478,0.321705,0.091995,0.139679,0.276352,0.093503,-0.338326,-0.198249,0.181289,-0.091448,0.243290,0.457589,0.094722,-0.097239,-0.008623,-0.434826,-0.258781,-0.112621,-0.216486,-0.235361,-0.125866,-0.335749,-0.711718,-0.128774,-0.019684,-0.071271,0.075590,0.147935,-0.110237,0.154855,-0.599446,0.199724,-0.032918,0.129023,-0.503388,0.262532,-0.140473,0.164737,-0.074364,-0.314598,0.136063,0.294761,0.530072,0.158026,0.152553,-0.226295,-0.376449,-0.386528,-0.060577', '10466639', '1309194', '1316693', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1835843', '博物馆奇妙夜', '喜剧', '拉里·达利（本·斯蒂勒 饰）生活似乎不太顺利：经常换工作，居无定所；妻子与他离婚，找了一个证券经纪人，即将再婚，自己在儿子心目中的地位也岌岌可危。达利为了挽救自己的生活，也为了争取到儿子的抚养权，他不得不放弃“做大事”的梦想，成为了纽约自然博物馆的夜间警卫。达利原本 以为这是一份无聊的工作，谁知道上班的第一天，不可思议的事情就发生了：博物馆里的法老金牌拥有神奇的魔法，当夜晚来临的时候，馆中所有的标本都会活过来，追逐骨头的霸王龙、爱捣乱的猴子、暴虐的匈奴王、钻木取火的穴居人……将一切弄得不可开交。在26任总统特迪·罗斯福的帮助下，达利好不容易控制住了局面，但是，他马上又遇到了新的麻烦：有人想打法老金牌的主意。职责所在，也是为了博物馆夜晚的奇迹，达利不得不挺身而出。©豆瓣', '本·斯蒂勒', '肖恩·利维', 7.6, 270715, 'tt0477347', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2221540227.jpg', 0.3, 2.4, 31.2, 48.6, 17.6, '-0.026816,0.011495,-0.665138,0.327914,-0.309050,-0.167178,0.293108,0.144510,-0.380819,-0.455838,0.165137,0.887527,-0.001782,0.297181,0.253053,0.147593,-0.269162,-0.690544,0.090067,-0.066298,-0.170584,-0.223773,-0.335258,-0.440667,-0.118998,-0.179442,0.381036,0.202538,-0.107731,0.070760,0.275647,0.212180,0.186772,0.522794,-0.091581,-0.221304,0.086891,0.165296,-0.253030,0.128366,0.088980,-0.213676,-0.090371,0.266546,0.361796,0.172067,0.226585,-0.256800,-0.154043,-0.250932,0.312393,-0.297962,0.022574,0.123320,0.211722,-0.064009,0.176996,0.180569,-0.375746,-0.059728,0.146809,-0.253604,-1.006512,0.078763,-0.004206,-0.072240,-0.634135,0.159875,-0.004983,0.009464,0.286561,-0.328981,0.484749,0.511986,0.353141,0.449043,-0.314771,0.018614,-0.699274,0.219513,0.781260,-0.061316,-0.234224,0.224113,-0.098295,-0.270145,0.047784,-0.426315,-0.449057,0.028614,0.215247,-0.007674,-0.244659,0.237160,-0.477417,-0.093146,-0.192005,-0.329058,-0.069565,-0.549484,-0.057455,-0.247860,-0.002751,-0.169564,-0.121586,0.037033,0.116062,-0.236675,0.574146,-0.752461,0.223075,0.630623,0.186445,-0.676494,0.493021,0.221374,0.203491,-0.240861,-0.044835,-0.011506,0.053083,0.537325,0.162412,0.076183,0.177336,-0.300382,-0.356804,0.638157', '30163500', '26678784', '1793491', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1839857', '隔山有眼2', '惊悚', '美国新墨西哥州的炎热荒地里，经常发生神秘失踪事件，又因其与世隔绝，里面的凄惨故事很难为外界所知。在卡特家族误入变异食人魔领地惨遭杀戮之后一年，一行八人的国防护卫队士兵又被排到这片戈壁滩执行训练任务。在其余六人被派到山里时，剩下被罚站的法国裔士兵拿破仑（麦克·麦克米兰 Michael McMillian 饰）与金发女兵安博尔（杰西卡·斯托普 Jessica Stroup 饰）在基地留守。异状很快发生，厕所里面伸出一只可怕的手，一位全身被粪便入侵的科学家爬了出来，留下一句“小心他们”就死去了，安博尔坚持上山寻找其他人发出警告，怎料变异食人魔们早就在错综复杂的山道布下天罗地网，等待倒霉的猎物们前来送死……©豆瓣', '麦克·麦克米兰', '马丁·韦兹', 6.4, 22781, 'tt0800069', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1501507869.jpg', 2.4, 13.7, 53.2, 22.7, 8, '0.392927,-0.102557,-0.832894,0.259692,0.011981,0.163450,0.815460,-0.085029,-0.368682,-0.306191,0.258627,0.489380,-0.144572,0.115986,0.044582,-0.382518,-0.032854,-0.525226,-0.175976,-0.308802,-0.510675,0.073654,-0.257239,-0.380881,-0.106379,-0.380156,0.427679,0.294589,-0.065629,0.516507,0.008728,0.442245,-0.440351,0.159526,-0.322270,0.079605,0.368557,-0.369944,0.073731,0.215358,-0.333059,-0.086724,-0.178159,-0.155058,0.014759,0.252047,0.760084,-0.333366,-0.030764,-0.231733,0.105273,-0.397596,0.172159,0.236097,1.022211,0.074717,-0.041437,0.195475,-0.019705,0.221282,0.044130,-0.066887,-0.532188,0.074719,-0.192641,0.463497,-0.529383,0.201033,0.006025,0.053968,0.057825,-0.276184,0.211462,0.242422,0.124671,0.267232,0.154242,0.069223,-0.465635,-0.161601,0.728394,-0.389646,-0.218829,-0.241079,0.051036,-0.247156,0.276055,-0.171843,-0.222061,0.102249,0.576842,-0.113775,-0.323509,0.179186,-0.611443,0.152233,-0.310441,-0.580009,-0.280433,-0.033172,-0.443267,-0.852768,0.129947,0.157093,-0.194025,0.424970,-0.027301,0.332835,0.437609,-0.258918,0.349150,0.496515,0.358628,-0.339454,0.251146,-0.421414,0.279332,0.174319,0.157914,0.334970,0.475739,0.496349,0.481124,0.398440,-0.291276,-0.128208,-0.597605,0.070768', '1293143', '10466639', '2024935', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1844413', '八月迷情', '剧情', '莱拉（凯丽•拉塞尔 Keri Russell 饰），一个出色的大提琴手；路易斯（乔纳森•莱斯•梅耶斯 Jonathan Rhys Meyers 饰），一名流浪的爱尔兰歌手。一个月色迷离的晚上，两人相遇了。度过难忘的一晚后，莱拉那专横的父亲又强逼她继续踏上音乐会的旅程。路易斯因等不到恋人失望之下离开了；而莱拉发觉爱人走后，独自伤心的等待肚中的孩子出生。岂料几个月后莱拉遭遇了一场车祸，宝宝亦随之夭折。孰料，莱拉的宝宝其实并没有死，而是被她狠心的父亲送到了孤儿院。一晃眼10多年过去了，生活在孤儿院的少年奥古斯特（弗莱迪•海默 Freddie Highmore 饰）坚信自己的父母还在世上，于是踏上了漫漫寻亲路。©豆瓣', '乔纳森·莱斯·梅耶斯', '科斯汀·谢里丹', 8.3, 151937, 'tt0426931', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p792528025.jpg', 0.5, 2.1, 16.9, 41.3, 39.2, '0.205059,0.091632,-0.785482,0.487966,-0.165182,-0.710986,0.836437,0.128179,-0.523283,-0.176031,0.200095,0.793144,-0.121555,0.433008,0.323280,0.107874,-0.194335,-0.636738,0.087706,-0.160927,-0.410409,-0.258084,0.040615,-0.073470,-0.015854,-0.251910,0.435454,0.052880,0.454702,0.687100,0.208251,-0.009331,-0.112554,0.417758,-0.079870,0.316950,0.137514,0.136464,-0.113179,0.412541,0.237883,-0.092946,-0.125887,-0.047344,0.012740,0.127135,0.812884,-0.081441,0.096594,-0.204827,0.301336,-0.264378,-0.099929,0.142205,0.185852,-0.140223,0.019761,0.144881,-0.288519,-0.133769,0.003286,0.012972,-0.437490,0.224386,-0.111229,-0.028883,-0.803026,0.576683,0.052040,-0.140646,0.110263,-0.496142,0.036627,0.290272,0.087399,0.510727,-0.164566,0.135968,-0.268393,0.300732,0.633545,-0.300981,-0.118992,0.560036,0.004803,-0.376605,0.150800,0.005476,-0.704460,0.158009,0.581849,0.035241,-0.393179,0.165180,-0.327928,-0.077553,-0.590600,-0.186674,-0.106183,-0.319741,-0.162609,-0.285398,0.183268,-0.148636,-0.278177,0.225362,-0.120967,-0.181480,0.430476,-0.579591,0.598465,0.621010,0.105524,-0.355541,0.530113,0.167238,0.400568,-0.054621,0.198933,0.931353,-0.109531,0.111398,0.132265,0.066216,-0.076842,0.204258,-0.463195,0.436911', '1300945', '1297606', '1297228', '3001149');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1848925', '恶童', '动作', '宝町是一座与时代发展脱节、人口密集的中型工业城市，整日响着轰隆隆机器操作的声音。小黑和小白是被称之为“猫党”的人，可以腾空在城市顶端，可以滑落在纵深空间，小黑会拿着铁棍来狂扁他不喜欢的大人，小白则有着自己天真的想象世界。宝町是一个没有将来的城市，直到一家叫“KIDDY KASTLE”的公司来到这里并想把宝町改造成他们想要的样子时，恶童们知道这是为自己的生活和城市、更是为自己的灵魂而战斗的时候了。这座城市的没有规则、自由自在、清新空气、游乐设施都是属于宝町独有的！©豆瓣', '二宫和也', '迈克尔·艾里亚斯', 8.6, 64099, 'tt0831888', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456779198.jpg', 0.6, 2, 13.7, 36.9, 46.8, '0.248409,0.323432,-0.897319,0.701748,-0.162570,0.105651,0.909889,0.383749,-0.478353,0.083119,-0.046200,0.703369,0.112263,-0.011711,-0.285496,0.135991,-0.151452,-0.691981,-0.350775,-0.273794,-0.471195,-0.526326,-0.141274,-0.443563,-0.114079,-0.598594,0.662615,0.176509,-0.416902,-0.090704,-0.119416,0.032654,0.041000,0.474155,-0.776556,-0.289999,0.029075,0.116108,-0.212093,0.273707,-0.432314,0.014888,0.033888,0.143967,-0.049594,0.077927,0.783689,-0.167427,-0.115874,-0.118855,0.123551,-0.027456,-0.048997,-0.208940,0.360905,-0.460793,0.205769,0.001575,-0.239046,-0.052273,0.414373,-0.488385,-0.874988,0.047849,0.092985,0.058323,-0.524296,0.487823,-0.037395,-0.362293,0.101513,-0.601410,0.592392,0.367779,0.348039,0.731935,-0.220780,0.154760,-0.820063,0.154432,0.758397,-0.104397,-0.250480,0.598419,-0.548590,-0.509710,-0.647051,-0.412981,-0.603283,-0.418385,0.129656,0.157878,-0.456319,0.094300,-0.689245,0.454054,0.098541,-0.677308,0.127446,-0.496641,-0.421545,-0.350109,-0.135600,-0.628603,-0.047876,0.066331,-0.054388,-0.143331,0.772576,-1.145130,0.134437,0.661879,0.363665,-0.255450,1.002102,-0.102026,-0.178741,-0.094997,0.194350,-0.107458,-0.117286,0.585245,0.162104,0.538555,0.132950,-0.187633,-0.530164,0.731650', '3055049', '3230462', '1907966', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1849003', '拜金女郎', '喜剧', '爱娃•马歇塔（海莉•达芙 饰）与汤泽•马歇塔（希拉里•达芙 饰）两姐妹过着随心所欲的生活，她们身上都是奢华的打扮，身为化妆品集团继承人的她们是城中的高贵名媛。她们已去世的父亲建立了价值千万的化妆品公司，而她们只需不时在董事会上露露面，凡事都交给助理处理。但没想到在父亲的纪念会上，公司产品能导致使用者毁容，丑闻爆出后姐妹两正式开始了潦倒的生活，她们一夜间失去了所有金钱、名誉、权力。从未面临过真实世界的姐妹俩，必须习惯穷人的生活，也要拯救父亲的声誉与公司的命运……她们最后又能否在历练中成长呢？©豆瓣', '希拉里·达芙', '玛莎·库利奇', 5.9, 12483, 'tt0433412', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1554405006.jpg', 4.5, 19.4, 57.8, 14.8, 3.4, '-0.060949,0.141928,-0.339628,0.438466,-0.087459,-0.333988,0.296102,0.354754,-0.550463,-0.313066,0.278973,0.741235,-0.028911,0.369362,0.225621,-0.021869,-0.411290,-0.765043,-0.045446,-0.305584,-0.096247,-0.247981,0.021848,-0.243189,-0.384620,-0.212894,0.618644,-0.183645,-0.061714,0.193167,0.283697,0.081666,-0.303349,0.325973,-0.239538,-0.098925,0.000362,0.187307,-0.771535,0.025482,-0.014819,-0.084251,0.023649,0.082811,0.328641,0.184204,0.422452,-0.111834,-0.184291,-0.430313,0.520413,0.158372,0.203836,0.123456,0.370376,-0.015841,0.528177,0.509196,-0.320812,-0.072329,0.135323,-0.279132,-0.893749,-0.047461,0.250462,0.010610,-0.696415,0.502349,-0.082734,-0.047083,-0.011501,-0.128251,0.220309,0.550885,0.152174,0.260942,-0.155679,0.095417,-0.746304,0.440065,0.665322,-0.120516,-0.264507,0.436534,-0.196724,-0.230299,-0.275374,-0.741844,-0.551892,0.092037,-0.079835,0.263915,0.063719,0.454710,-0.652583,0.094501,-0.260535,-0.456269,0.426330,-0.417202,0.038796,-0.483137,-0.324072,-0.662245,-0.638899,0.104954,0.221499,-0.321931,0.737999,-0.934775,-0.065707,0.322983,0.584064,-0.852903,0.568334,0.079251,0.493052,-0.006049,-0.272291,0.091223,-0.089795,0.382737,-0.055572,0.049790,0.189519,-0.000505,-0.065069,0.340762', '1877596', '4301278', '26678784', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1849026', '空战英豪', '剧情', '1914年，第一次世界大战爆发，1917年，法、国，意和其他欧洲国家相续结成联盟，决心一并抗击德国。很多胸怀远大志向的热血青年志愿加入了这场空前绝后的欧洲大陆的战争，并且希望通过自己的微薄努力结束战争，让大家重新过上安详平静的生活。失去家族牧场的布雷恩（詹姆斯·弗兰科 James Franco 饰）、为了光复家族荣耀的威廉，想穿越大西洋旅行的布里格斯，因种族原因被逐出美国的黑人拳击手等三十八个年轻人为了一个共同的目标加入了海外作战空军部队。他们在在法国将军赛诺特（让·雷诺 Jean Reno 饰）和美国士兵瑞德·卡西迪（马丁·亨德森 Martin Henderson 饰）的辅助和领导下，每个人都真正了解到为荣誉和和平而战的意义，所有人组成了“拉斐特飞行小队”。可战争的残酷和现实大大超过了这群热血青年的想象，死亡每天都在靠近，危险处处不在......', '詹姆斯·弗兰科', '托尼·比尔', 7.4, 9724, 'tt0454824', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1090376129.jpg', 0.5, 3.3, 36.1, 46.3, 13.8, '0.054546,0.177534,-0.640852,0.588368,0.086740,-0.245761,0.350805,-0.075257,-0.477521,-0.157367,-0.033241,0.912611,0.206920,-0.117726,0.335662,-0.256379,-0.415917,-0.662869,-0.197018,0.096440,-0.301395,-0.502644,-0.256718,-0.449998,-0.213795,-0.490532,0.800352,0.229005,-0.151788,0.458442,0.066066,0.313511,0.049883,0.232880,-0.092231,-0.262768,0.205676,0.038594,-0.724028,0.173559,-0.347813,0.074573,-0.275367,0.256566,0.193720,0.039144,0.545574,-0.295092,0.074373,-0.152038,0.099555,-0.429281,-0.132757,0.130378,0.284163,-0.050310,0.024294,0.572618,0.239374,-0.052157,-0.159756,-0.216953,-0.981221,-0.072309,0.262251,0.027639,-0.519357,0.885463,-0.264300,-0.115825,0.086479,0.042866,0.216548,0.881122,0.216175,0.146546,-0.195968,0.098571,-0.579201,0.188076,0.989207,-0.175061,-0.459894,-0.154263,-0.211192,-0.472934,-0.259028,-0.464144,-0.381105,-0.047317,0.220780,-0.072842,0.017970,0.532466,-1.000199,0.154112,-0.201623,-0.620138,0.149490,-0.412675,0.140183,-0.556204,-0.165379,-0.384367,-0.313624,0.192149,0.171464,-0.159077,1.062037,-0.839947,0.179043,0.580496,0.421216,-0.551749,0.743837,0.134680,0.360118,-0.385372,-0.121638,0.361321,-0.033850,0.253900,-0.047389,0.206622,-0.039551,-0.015077,-0.133988,0.538002', '25917239', '26678784', '27602116', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1849031', '当幸福来敲门', '剧情', '克里斯•加纳（威尔·史密斯 Will Smith 饰）用尽全部积蓄买下了高科技治疗仪，到处向医院推销，可是价格高昂，接受的人不多。就算他多努力都无法提供一个良好的生活环境给妻儿，妻子（桑迪·牛顿 Thandie Newton 饰）最终选择离开家。从此他带着儿子克里斯托夫（贾登·史密斯 Jaden Smith 饰）相依为命。克里斯好不容易争取回来一个股票投资公司实习的机会，就算没有报酬，成功机会只有百分之五，他仍努力奋斗，儿子是他的力量。他看尽白眼，与儿子躲在地铁站里的公共厕所里，住在教堂的收容所里…… 他坚信，幸福明天就会来临。©豆瓣', '威尔·史密斯', '加布里埃莱·穆奇诺', 9.2, 1427039, 'tt0454921', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2614359276.jpg', 0.1, 0.4, 5.6, 29.3, 64.6, '-0.300904,0.024137,-0.655750,0.515269,-0.341176,-0.489760,0.584322,0.079494,-0.189299,-0.076441,0.012258,0.661305,0.369833,0.222146,-0.080815,0.144137,-0.399120,-0.309666,0.014724,-0.211766,-0.238911,-0.465062,-0.402794,-0.424403,-0.129818,-0.005157,0.307239,-0.002870,0.129365,0.089507,0.202269,0.064633,0.186360,0.469154,-0.194033,0.002348,0.010719,-0.224527,-0.316805,0.495049,0.203074,-0.077894,-0.175878,0.161615,0.624333,0.102115,0.622302,0.159881,-0.041526,-0.134506,0.084383,0.041365,-0.011498,0.226074,-0.216299,-0.074988,0.548409,0.165488,-0.333999,-0.108875,0.222168,-0.203620,-0.820707,0.009216,0.082296,-0.045685,-0.672595,0.571678,-0.068216,-0.052540,0.056463,-0.506113,0.014194,0.024412,0.124658,0.354631,-0.385468,0.140241,-0.595095,0.135498,0.438828,-0.420798,0.000303,0.366326,-0.229443,-0.012060,0.105198,-0.261863,-0.753308,-0.114658,0.357305,0.182508,-0.229629,-0.057570,-0.207328,0.003698,-0.437281,-0.491126,0.105525,-0.413591,0.190804,-0.525196,0.132012,-0.023603,-0.370785,0.330479,0.101819,-0.476897,0.570743,-0.513031,0.151791,0.667475,0.582987,-0.500960,0.858543,-0.084955,0.189275,-0.209771,0.135135,0.248667,-0.033724,0.359864,0.323668,0.051882,0.123215,-0.079458,-0.122635,0.764868', '30279170', '3055049', '1296132', '1460341');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1849371', '太阳浩劫', '科幻', '故事发生在遥远的2057年，太阳的逐渐衰竭让人类即将面临有史以来最大的危机，如果失去了日照，大地将会陷入黑暗和冰封之中，永无再见天日之时。为了拯救地球，一支八人行动小组组成了，他们分别是稳重老城的机长凯恩达（真田广之 饰）、植物学翘楚卡伦佐（杨紫琼 饰）、航海高手特雷（本尼迪特·王 Benedict Wong 饰）、物理学家卡帕（希里安·墨菲 Cillian Murphy 饰）、驾驶员卡西（萝丝·拜恩 Rose Byrne 饰）和她的助手马斯（克里斯·埃文斯 Chris Evans 饰），指挥官哈维（特洛伊·格雷提 Troy Garity 饰）以及博士希瑞尔（克利夫·柯蒂斯 Cliff Curtis 饰）。背负着全人类的使命，八人驾驶着宇宙飞船“伊卡鲁斯二号”飞向了太阳。随着目的地的临近，问题不断的出现着，他们不仅和地球失去了联系，还收到了来自“伊卡鲁斯一号”，也就是他们的前任所发来的求救信号。危险和不安的气息不断的在八个行业精英之间弥漫和扩散着，他们能够顺利完成任务吗？又是否能够平安返回地球呢？', '基里安·墨菲', '丹尼·博伊尔', 7, 23299, 'tt0448134', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196599208.jpg', 1.3, 7.4, 44.8, 35.2, 11.2, '-0.021764,0.087179,-0.737270,0.604709,0.137241,-0.260593,0.579529,0.189675,-0.281172,-0.220513,0.045104,0.726249,-0.030514,-0.020810,0.426235,0.016218,-0.389758,-0.661811,-0.144940,-0.220188,-0.429121,-0.669450,-0.257220,-0.227905,0.153560,-0.520417,0.560847,0.064689,-0.084760,0.341460,0.214920,0.483845,-0.304666,0.519848,-0.030502,-0.103347,0.234763,-0.137335,-0.368879,0.246613,-0.025892,0.089145,0.206713,0.172732,0.070887,0.246365,0.676033,-0.614523,0.187719,-0.251123,-0.021387,-0.266075,0.084507,-0.067397,0.288231,-0.143020,-0.157784,0.266373,-0.008640,0.003322,-0.016274,-0.121229,-0.740711,-0.045409,-0.033974,0.385282,-0.383477,0.278945,-0.264321,-0.123149,0.226767,-0.252858,0.259098,0.531084,0.123768,0.251253,-0.189229,-0.112110,-0.444174,-0.082720,0.556548,-0.022542,-0.481628,0.082600,-0.195413,-0.480549,-0.375021,0.085476,-0.559871,-0.129081,0.456064,0.305083,0.211759,0.487624,-0.543611,0.021498,-0.271943,-0.443450,-0.029213,-0.318873,0.006215,-0.636483,0.061130,-0.330517,-0.291603,0.182808,-0.061935,-0.099987,0.618578,-0.684597,0.482707,0.541855,0.284300,-0.055391,0.437404,-0.122955,0.387608,-0.472661,-0.151815,0.440571,-0.084300,0.585375,0.184405,0.269794,-0.058145,-0.096186,-0.222812,0.409131', '25774050', '2032339', '25928048', '4126925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1849959', '怒火攻心', '动作', '杀手切弗（杰森•斯达森Jason Statham 饰）遭人暗算，死对头瑞奇兄弟向其体内注射了致命毒物。切弗醒后急火攻心，痛苦不堪。为了寻找解药，他闯入了奥兰多的黑帮据点，但一无所获。走投无路的切弗前往贝弗利山庄，向老大卡雷托求救，但是后者称他应对唐金事件负责。切弗的医生告诉他，只有提高体内肾上腺素的含量，才能维持生命。愤怒的切弗为了复仇，在王子宾馆干掉了瑞奇的哥哥，并闯进医院到处搜罗相关药品，结果引来大批警察。虽然成了全城通缉的要犯，但是切弗还是不顾一切地搭救女友伊芙（艾米•斯玛特Amy Smart 饰）。在躲过追杀后，他对女友坦白了这一切的源头，是因为他曾经放过的香港三合会毒品大亨唐金，所以仇家才对他下毒手。女友深明大义，与切弗共同踏上了复仇之路……©豆瓣', '杰森·斯坦森', '马克·耐沃尔代', 7.4, 88543, 'tt0479884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456446128.jpg', 0.9, 4.5, 33.8, 43.4, 17.4, '-0.048242,-0.091698,-0.302071,0.259722,0.071241,-0.282647,0.519283,0.008564,-0.263544,-0.173198,0.181066,0.387790,0.112547,-0.058542,0.173256,0.081857,-0.115714,-0.445956,0.026927,-0.260216,-0.299034,-0.317671,-0.135662,-0.434673,0.099521,-0.173934,0.413506,0.053355,-0.314900,0.414657,0.347978,0.514417,-0.082060,0.652206,0.101440,0.014143,0.131785,-0.276395,-0.406951,0.409624,0.400097,-0.335882,-0.026477,0.447855,0.049190,0.462099,0.552469,-0.253186,-0.102892,-0.269830,0.150642,-0.484341,0.159317,0.014652,0.397918,-0.133377,0.205529,0.240026,-0.106767,-0.286685,0.028407,0.077896,-0.618435,-0.169163,0.221456,0.025970,-0.419163,0.069530,-0.166122,0.290381,-0.040758,-0.324785,0.200610,0.270388,0.112530,0.061158,-0.287802,-0.017303,-0.566058,-0.072814,0.488583,-0.259510,0.163724,0.116080,-0.010377,-0.305323,0.127087,-0.234420,-0.351074,-0.031346,0.324747,-0.014681,-0.114487,0.260493,-0.367252,-0.337567,-0.539609,-0.135571,0.085898,-0.310905,-0.046825,-0.429499,-0.055313,0.095093,-0.158641,0.005579,0.031015,-0.205073,0.454155,-0.723087,-0.016983,0.831277,0.435842,-0.697978,0.348086,-0.172502,-0.041265,-0.173944,-0.249563,0.308540,0.478681,0.552062,0.235646,0.140416,0.190272,-0.123410,-0.250332,0.077608', '35073886', '1309116', '1292829', '3743114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1850521', '公寓', '恐怖', '世珍（高小英）独自住在一幢高层豪华公寓中的一间。某日深夜，拖着疲惫身躯在地铁站等车时，一神秘女子突然将她拉住欲一起跳轨，惊魂甫定，女子已命丧黄泉。加上工作中为如何布置橱窗以迎即将到来的圣诞节与合作伙伴发生冲突，她开始夜夜被噩梦折磨。勉强称作开心的事，是某日晨跑时结识住于对面公寓的残疾女孩柔妍（张熙珍）。柔妍自言父母虽然双亡，却托好心邻居照料活得幸福，并在谈话结束一刻，相交她一个魔方。世珍察觉到柔妍所住的房间有异样，之后用望远镜夜夜观察，更发现时间每走到9点56分，整幢公寓便会齐齐熄灯，而次日清晨，会有一具尸体被拖出。世珍的行为被女高中生（朴夏善）发现并告知母亲，其母报警，但世珍没将警察的警告当回事。不久，女高中生主动向世珍道歉，两人成为朋友，而她屡屡玩不转魔方令世珍发现藏于其中的与柔妍有关的秘密，倒吸一口凉气。©豆瓣', '高素荣', '安兵基', 6.3, 11819, 'tt0826024', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2507718620.jpg', 2.2, 13.4, 56.2, 22.4, 5.7, '0.211921,0.004458,-0.749300,-0.027859,0.073888,-0.204658,0.874062,0.058310,-0.518962,-0.370547,0.296704,0.536478,-0.378270,0.418460,0.411374,-0.130515,-0.135053,-0.528546,-0.177633,-0.189910,-0.473630,-0.145268,0.250141,-0.040719,-0.003773,-0.318798,0.298558,0.014222,0.115958,0.464392,0.221364,0.092162,-0.498970,0.571571,-0.179459,-0.165979,-0.105982,-0.054533,-0.210339,0.311662,-0.165524,-0.292288,-0.219467,-0.075532,-0.159171,0.207681,0.626933,-0.104461,-0.304283,-0.096398,0.228531,0.015768,-0.206600,0.196755,0.524337,0.084060,0.294687,0.041206,-0.431683,0.145430,0.063453,-0.062620,-0.215513,0.130328,-0.023826,0.088751,-0.411145,0.232773,0.062150,0.025014,0.097479,-0.366782,0.250743,0.248150,0.210323,0.322433,-0.080449,0.236413,-0.351748,-0.215464,0.521311,-0.161028,0.131179,0.393457,0.058247,-0.297635,0.187228,0.128927,-0.386994,-0.022608,0.196355,0.373445,-0.170537,-0.067047,-0.269753,-0.193387,-0.254610,0.025482,0.151646,-0.382884,-0.295719,-0.579440,-0.138041,0.070189,-0.053400,0.350381,0.023186,-0.179667,0.241976,-0.680458,0.288722,0.427814,0.376509,-0.180523,0.631133,-0.163946,0.239253,-0.033524,0.099022,0.190546,0.202495,0.383154,0.206089,0.326606,-0.375291,0.009600,-0.470293,0.064277', '10466639', '1296534', '3011051', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1850660', '复制贝多芬', '剧情', '1824年，维也纳。年仅23岁的安娜·霍兹（戴安·克鲁格 Diane Kruger 饰）凭借自己对于音乐的出色领悟力成为贝多芬（艾德·哈里斯 Ed Harris 饰）的乐稿抄写员，此时已经失聪的贝多芬正醉心于创作自己的“告别作”。安娜本想借着为贝多芬工作的机会向他学习，从而成为一名出色的作曲家，可是很快她发现贝多芬是一个固执、粗鲁、一味沉浸在自我世界中的疯子。贝多芬《第九交响曲》的首演由于安娜在危急时给予帮助而取得成功，两人的关系逐渐好转。安娜拿出自己所写的曲子让贝多芬评价时，却惹来贝多芬尖酸刻薄的嘲讽，安娜一气之下离开了贝多芬。在贝多芬的请求下，安娜又重新回到贝多芬身边并且尝试接受他那些过激言语所传达的意见，安娜似乎渐渐理解了这位天才级的大师……本片2007年在素有“西班牙奥斯卡”之称的哥雅奖（Goya Awards）上获最佳欧洲电影提名。©豆瓣', '黛安·克鲁格', '阿格涅丝卡·霍兰', 7.4, 7460, 'tt0424908', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p482507491.jpg', 1, 4, 36.4, 42.6, 16, '0.160604,0.507796,-0.583693,0.695205,-0.047354,-0.220038,0.575399,0.011646,-0.450164,-0.276491,0.247915,0.873654,-0.046108,0.394767,0.361195,-0.061550,-0.460128,-0.865191,0.232020,0.010102,-0.070344,-0.631583,-0.202502,0.103195,-0.302396,-0.582778,0.545634,-0.269711,-0.447858,0.545035,0.208611,0.275029,0.293891,0.260629,-0.053201,0.099815,0.366837,-0.222623,-0.193682,0.226300,0.114511,-0.246286,-0.230780,0.038929,-0.176351,0.225558,0.638805,-0.315908,-0.072246,0.038039,0.674897,-0.002071,0.063662,0.007330,-0.042903,0.133268,0.122946,0.132051,-0.162824,0.236052,-0.349487,-0.023715,-0.807318,0.212243,0.133000,0.178659,-0.562731,0.228638,-0.131105,-0.000478,0.130202,-0.221565,-0.014802,0.160796,0.324275,0.542676,-0.300101,0.138582,-0.162261,0.199996,0.442545,0.275514,-0.537216,0.499015,-0.101977,-0.260392,-0.010322,-0.301502,-0.448651,0.062580,0.272961,0.228601,0.138494,0.046259,-0.322515,-0.315652,-0.121587,-0.204203,0.127165,-0.300422,-0.026138,-0.740024,-0.060102,-0.189143,-0.185325,-0.298101,0.037892,-0.472546,0.936675,-0.746860,0.328658,0.406776,0.079615,-0.078878,0.619901,0.020915,-0.068536,-0.188449,-0.199528,0.502122,-0.235443,0.115986,0.117762,0.476175,-0.008657,-0.221790,-0.405449,0.542547', '27602116', '1870681', 