INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1850797', '方糖', '剧情', '幼年丧母的诗恩(林秀晶饰)对马有着深厚的感情。与一匹叫“雷鸣”的马更是亲密无间，视为亲弟弟。但诗恩的父亲不愿女儿走上赛马的道路，把“雷鸣”卖到了别的地方。固执的诗恩没有放弃当一名优秀骑手的梦想，更没有忘记过弟弟“雷鸣”。命运安排诗恩与“雷鸣”再次相遇。在诗恩的调教下“雷鸣”具备了赛马的实力，诗恩准备带着“雷鸣”参加赛马大会。可此时“雷鸣”的身体却出现了异样……马背上的诗恩张开双臂：“与它一起奔跑，感觉全世界都属于我自己！”只要与天雷在一起诗恩觉得能够奔跑到世界的尽头，他们的奇迹就要开始了么？诗恩把弟弟最爱吃的方糖塞满了口袋……©豆瓣', '林秀晶', '李焕庆', 8, 20550, 'tt0438986', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p699062958.jpg', 0.4, 2, 22.7, 48, 27, '0.185291,0.052399,-0.761621,0.742939,-0.160162,-0.352547,0.760523,0.201592,-0.267204,-0.100755,0.092339,0.768904,-0.067030,0.199509,0.142737,-0.245144,0.172413,-0.920619,-0.142603,-0.117154,-0.277047,-0.338676,-0.195374,0.005819,-0.123040,-0.292660,0.609759,-0.147167,-0.241866,0.774177,0.326834,-0.087887,0.043686,0.352158,-0.632775,-0.013936,-0.136732,0.332272,-0.348528,0.116208,-0.002197,0.062613,0.129234,0.170635,-0.070826,0.081924,0.501133,-0.228081,0.086248,-0.135359,0.060390,-0.123101,0.292853,0.132695,0.180552,0.141539,0.053864,-0.006041,0.031581,0.090434,0.187274,-0.154732,-0.609635,0.100813,-0.084188,0.136109,-0.803313,0.199921,-0.109418,-0.195202,0.226198,-0.366800,0.277347,0.140482,0.132002,0.573311,-0.422145,0.134128,-0.509527,0.038996,0.753578,-0.199063,-0.082895,0.388810,-0.260106,-0.397569,0.020192,-0.098846,-0.567565,-0.077917,0.323233,0.374506,-0.390024,0.191536,-0.395437,0.148997,0.110381,-0.336720,-0.020461,-0.383395,-0.107953,-0.280490,-0.073380,-0.578511,-0.173133,0.247916,0.080463,-0.246653,0.752929,-0.904600,0.270672,0.401191,0.308388,-0.356779,0.704971,0.062426,0.058809,0.055130,0.267755,-0.044730,-0.098102,0.097066,0.244419,0.455008,-0.100839,0.064356,-0.621536,0.684724', '35030151', '21360412', '35144311', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1850942', '半个尼尔森', '剧情', '白人历史教师丹•邓恩（瑞恩•高斯林 饰），在纽约布鲁克林一家破旧的公立中学教书，他的学生多是黑人。丹有激情和创造力，热爱学生，不遵循官方教学大纲，相信黑格尔辩证法，认为历史本质由相反力作用而成。他使得纸页间枯燥的历史生动鲜活，鼓励学生思考和分析历史，及自己周遍世界的运作法则，学生成为丹存活于社会的救生索。晚上，他是不可救药的瘾君子。这种分裂的生活没有能持续多久，丹某次在空无一人的女更衣室吸毒而虚脱，被他的黑人女学生德丽（莎莉卡•艾普斯 饰）发现。共同保守的阴暗秘密，拉近了他们的关系，也改变了各自的生活。©豆瓣', '瑞恩·高斯林', '瑞安·弗雷克', 7.5, 6637, 'tt0468489', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p823376066.jpg', 0.7, 3.4, 32.8, 47, 16.2, '0.147887,0.172235,-0.574587,0.531085,-0.132160,0.283340,0.513107,0.090642,-0.536595,-0.304650,-0.130411,0.449720,0.019878,0.247459,0.156913,-0.407945,-0.140409,-0.646047,0.175044,-0.062746,-0.446444,-0.528039,-0.091662,-0.550658,-0.389964,-0.718282,0.791071,0.329039,-0.270310,0.111829,-0.029209,0.219110,0.251448,0.175387,-0.090217,-0.160034,0.286684,0.051761,-0.127669,-0.060217,0.177790,0.042172,0.066101,-0.026928,0.175200,0.176305,0.774853,0.026236,-0.079361,-0.045815,0.503272,-0.049149,-0.357280,0.093496,0.426031,0.102097,-0.093926,0.150890,0.121993,0.010447,0.013739,-0.160658,-0.600502,-0.252483,0.088155,0.212749,-0.385791,0.841277,0.043946,-0.281444,-0.340962,0.013898,0.032472,0.175251,0.420650,0.357301,0.186158,-0.171444,-0.325001,0.329665,0.494692,0.052022,-0.711216,0.561331,-0.941092,-0.606737,-0.339727,-0.239455,-0.313224,-0.215524,0.121323,-0.023464,-0.262152,0.237284,-0.496914,0.054090,-0.050121,0.080091,0.200443,-0.416854,-0.221768,-0.574815,-0.074185,-0.514587,-0.032837,-0.082639,0.031462,-0.307307,1.080179,-0.846146,-0.141560,0.405443,0.270382,-0.409643,0.940092,-0.129326,0.028033,-0.432144,-0.014922,0.485278,-0.047581,0.350629,-0.005341,0.468307,0.145697,0.107871,-0.253139,0.534804', '25882279', '27602116', '1303010', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1850963', '花魁', '剧情', '日本江户时期，艺妓云集的吉原游郭车水马龙，繁华非常。商贾富豪挥金如土，只为博得佳人浅浅一笑。年仅八岁的小女孩辗转来到吉原玉菊屋，得名清叶，时玉菊屋头牌花魁妆日（菅野美穗饰）负责训练这个桀骜不驯的小女孩。为了早日离开这个烟花之地，清叶专心训练，以期早日成为吉原花魁，全身而退。转眼十年过去，清叶（土屋安娜 饰）色艺双全，成为吉原头号花魁，并更名日暮。然她此时仍未改却倔强秉性，对待富甲一方却傲慢无理的客人不屑一顾。武士仓之助（椎名桔平 饰）倾心日暮，并欲取之为妻，日暮却向他提出了一个几乎不可能的条件……本片根据安野モヨコ同名漫画改编。©豆瓣', '土屋安娜', '蜷川实花', 8.1, 81937, 'tt0794338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p656858958.jpg', 0.2, 1.5, 20.4, 48.8, 28.9, '-0.076851,0.398242,-0.232147,0.391508,-0.078474,-0.286465,0.404316,0.136199,-0.346031,-0.534933,0.300932,0.543291,-0.118141,0.249724,0.398293,0.172234,0.059969,-0.444775,-0.110500,-0.321508,0.344819,-0.111789,-0.058042,0.217349,-0.326507,0.061338,0.656785,0.190597,0.094982,0.588633,0.163148,0.189207,-0.063247,0.188232,-0.073308,-0.337428,-0.075396,-0.056185,-0.275250,0.365885,-0.573293,-0.408051,-0.427482,-0.270519,-0.106074,0.069722,0.785552,-0.220716,-0.173701,-0.381926,0.464064,-0.034843,-0.207481,0.344468,0.169616,-0.378063,0.021594,-0.089965,-0.056489,-0.018976,-0.271374,-0.325366,-0.423347,0.130853,0.137382,0.153140,-0.194247,0.214567,-0.199717,-0.142454,-0.005708,-0.403218,-0.094202,0.022806,0.146935,0.237497,-0.292155,0.475128,-0.463436,0.289518,0.371279,0.427721,-0.137024,0.281758,-0.042994,-0.454115,0.333953,-0.332722,-0.398780,0.040561,-0.121110,-0.123906,0.386634,-0.038268,-0.373129,-0.182010,-0.244407,-0.030363,0.299103,-0.124937,-0.115879,-0.482320,0.046476,-0.216552,-0.187997,-0.166312,0.310745,-0.343452,0.849328,-0.940893,-0.085736,0.377927,0.195869,-0.311501,0.335455,0.113447,0.048286,-0.194772,-0.293001,0.520877,0.092866,0.340541,-0.287711,0.262220,-0.155668,-0.314833,-0.165602,0.253538', '25922902', '10174444', '3811356', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1851683', '佐贺的超级阿嬷', '剧情', '8岁那年，男孩昭广跟随母亲（工藤夕贵 饰）离开广岛，来到了佐贺的乡下老家。这里没有玩具，没有朋友，甚至连最亲爱的妈妈也转身离开，迎接昭广的只有低矮破旧的房屋，以及独立抚养了七个儿女的超级阿嬷（吉行和子 饰）。初来乍到的昭广无法适应这里的寒酸生活，但随着时光的流逝，他渐渐体味到了与阿嬷在一起生活所得到的幸福……本片根据日本作家岛田洋七的同名小说改编，小说在2006年台湾金石堂年度畅销书排行、诚品年度畅销书排行、2006年博客年度畅销书排行以及香港各大书店畅销书排行中均获第一。日本原版连续三年位居日本各大畅销书排行榜前列，至今销售超过380万册。©豆瓣', '吉行和子', '仓内均', 8.5, 6484, 'tt0480773', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p764067971.jpg', 0.3, 0.9, 14.2, 43.6, 41.1, '0.172072,-0.097349,-0.657207,0.549391,0.390668,-0.326545,0.397438,0.163988,-0.595580,-0.501230,-0.062232,0.746870,-0.139029,0.461032,0.095514,-0.142593,0.021322,-0.601273,-0.422328,-0.555285,-0.182285,-0.078426,-0.162514,0.086055,-0.363367,-0.150080,0.933624,0.099479,-0.064870,0.629157,-0.023212,0.240349,-0.112080,-0.105831,-0.523692,0.227411,0.350151,0.222450,-0.342071,0.459327,-0.339576,-0.215171,0.055455,-0.370536,0.435873,-0.052829,0.695992,-0.190500,0.013228,0.158708,0.615967,0.123790,-0.722932,-0.167975,0.628390,-0.008727,0.481825,0.292360,-0.118276,0.144278,-0.390741,-0.301692,-0.524801,-0.085069,0.353973,0.170203,-0.823620,0.533056,-0.210481,-0.283767,-0.027835,-0.297039,0.298330,0.307455,-0.045538,0.335143,-0.113686,0.295001,-0.430046,0.727773,0.327547,0.076055,-0.279761,0.069682,0.093386,-0.293449,-0.103481,-0.675695,-0.459598,0.304030,0.058779,0.202789,0.171017,0.143362,-0.552241,0.043401,0.192813,-0.745841,0.421274,-0.263782,-0.298352,-0.739591,-0.005414,-0.333195,0.036551,0.083966,0.364417,-0.405965,1.073205,-0.722633,0.464642,0.201830,0.344642,-0.398300,0.891595,0.004225,0.075939,-0.160602,0.109989,0.252019,-0.003549,0.262440,-0.078376,0.143795,-0.217856,-0.322535,-0.516208,0.631686', '1908036', '25880986', '27602116', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1851857', '蝙蝠侠：黑暗骑士', '剧情', '从亲眼目睹父母被人杀死的阴影中走出来的“蝙蝠侠”，经历了成长之后，已经不再是那个桀骜不的孤单英雄了。在警官吉姆·戈登和检查官哈维·登特的通力帮助下，“蝙蝠侠”无后顾之忧地继续满世界的奔波，与日益增长起来的犯罪威胁做着永无休止的争斗，而他所在的高谭市，也是进展最为明显的地方，犯罪率以一种惊人的速度持续下降着，毕竟对方是能够上天入地的“蝙蝠侠”，不借两个胆子谁还敢造次呢？不过像高谭这种科技与污秽并存的城市，平静是不可能维持太久的，果不其然，新一轮的混乱很快就席卷了整个城市，人们再一被被恐慌所笼罩着，而声称愿意为这一切负责的，自然就是所有混乱的源头以及支配者--“小丑”了。先不管“小丑”掀起一个又一个犯罪的狂潮的最终目的为何，他的企图都是邪恶的，所作所为更是早就危害到了高谭市民的正常生活……其中自然包括了“蝙蝠侠”身边几个非常重要的人，而他需要做的，就是将这股新的危机全部亲自用手捏得粉碎。然而在面对着这个有史以来最具针对性、最恶毒的对手时，“蝙蝠侠”却不得不从他的地下军械库里搬出每一件能够用得上的高科技武器，还得时刻纠结着为他曾经信仰的一切寻找答案。', '克里斯蒂安·贝尔', '克里斯托弗·诺兰', 9.2, 989139, 'tt0468569', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p462657443.jpg', 0.2, 0.4, 5.6, 25.9, 67.8, '0.378372,0.188916,-0.888917,0.742201,-0.252010,-0.136907,0.825263,-0.041991,-0.581901,-0.157462,0.177580,0.679523,0.033609,0.145004,0.109028,-0.074327,-0.120780,-0.691132,-0.512905,-0.106029,-0.501541,-0.547557,-0.435701,-0.182981,-0.227253,-0.254723,0.430163,0.361860,-0.317657,0.058828,0.475782,0.258016,0.077154,0.754167,-0.192248,-0.317204,-0.153369,-0.116819,-0.164415,0.246347,0.265541,-0.340030,-0.089364,0.458139,-0.246038,0.287790,0.506923,-0.437063,-0.291969,-0.061445,0.483869,-0.407436,-0.049866,0.205823,0.256193,-0.203258,0.104582,0.141625,-0.122999,0.122312,0.147034,-0.016968,-1.258703,-0.053273,0.024611,0.141390,-0.660609,0.315537,0.054469,-0.253195,0.080058,-0.201228,0.330552,0.319467,0.141198,0.437132,-0.310719,-0.130387,-0.589199,0.074021,0.766244,0.111771,-0.476229,0.255013,-0.251669,-0.441681,-0.279267,-0.392788,-0.465580,-0.141052,0.298068,0.240767,-0.149904,0.272045,-0.572039,0.219942,-0.242884,-0.441656,-0.213575,-0.476807,-0.076769,-0.311588,-0.158545,-0.525116,-0.213442,0.103236,0.167539,-0.355019,0.749727,-0.846030,0.163640,0.656347,0.210872,-0.462814,0.376696,0.005414,0.126142,-0.091132,-0.260024,0.072793,0.027070,0.580172,0.269247,0.419178,0.108759,-0.329160,-0.373064,0.676001', '1793491', '30163500', '1874704', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1851906', '辛普森一家', '喜剧', '绿日乐队在春田镇办了环保演唱会，惨遭冷遇，成员落水而亡。为了悼念，教堂举办了弥撒仪式。辛普森一家又迟到了，而且爷爷突然灵魂附体，说出了灾难降临的预言。巴特因为踩着滑板裸奔被罚，得到了邻居弗兰德斯的帮助，情同父子。丽莎遇到了志同道合的爱尔兰男孩柯林，两人暗生情愫。荷马丢弃核废料与垃圾严重污染了水资源。他买回了一头猪，引起了妻子玛姬的不满，小女儿美姬倒是乐得其中。一个长着无数眼睛的怪异生物让大家意识到了问题的严峻性。居民大会上，丽萨提出的环保议案被否决，问题传到了施瓦辛格总统的耳朵里。政府下令将污染严重的春田镇隔离。如梦初醒的村民们这才发现环境的重要，愤怒的人们把矛头指向了污染的始作俑者——辛普森一家……本片是从1987年开始在美国连播18年的TV动画长寿剧集《辛普森一家》第一次登陆大银幕，在影迷中引起巨大反响。©豆瓣', '丹·卡斯泰兰尼塔', '大卫·西尔弗曼', 8.4, 80025, 'tt0462538', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1947152148.jpg', 0.2, 1, 14.8, 44.7, 39.2, '0.292450,0.033987,-0.675147,0.200333,0.132462,-0.074826,0.773814,0.117021,-0.394310,0.023672,0.410468,0.702544,-0.553978,0.183626,0.416710,-0.023283,-0.173462,-0.463544,-0.061023,-0.177645,-0.260500,-0.400275,-0.011494,-0.332421,-0.023512,-0.557582,0.253621,0.068204,-0.215284,0.391496,0.141289,0.285640,0.071691,0.334454,0.077572,0.201523,0.156320,-0.106089,0.017362,0.288091,-0.060396,-0.186366,-0.021949,0.155273,0.028208,0.388316,0.540668,-0.311802,-0.292667,-0.141759,0.618886,-0.396779,0.010521,0.339710,0.497366,0.006223,0.131915,0.127740,-0.159016,0.010463,0.211319,-0.096707,-0.278686,0.075692,-0.156022,0.195929,-0.500359,0.604895,0.046019,-0.043036,-0.103821,-0.275374,0.550289,0.197657,0.234436,0.517385,-0.014238,0.170149,-0.343118,0.141531,0.650619,-0.280535,-0.244594,0.099557,-0.373118,-0.364252,-0.014030,-0.184320,-0.184500,0.108159,0.572411,0.010716,-0.305518,0.446875,-0.627383,-0.248635,-0.152368,-0.524287,0.021356,-0.084620,-0.290762,-0.618090,-0.135153,-0.048391,0.057847,-0.036556,0.036452,-0.113830,0.813040,-0.568426,0.213990,0.652568,0.320805,-0.347279,0.389816,-0.220739,0.112948,-0.025623,-0.071234,-0.061952,0.147715,0.400447,0.345889,0.234627,-0.030602,-0.334069,-0.108891,0.134816', '3005387', '1296542', '30162520', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853160', '狗咬狗', '剧情', '暗黑、摇晃的船舱，来自柬埔寨的杀手鹏（陈冠希 饰），狗一般在抢食已经洒在地上的残羹冷炙。甚至，在杀人前，还不忘点了满满一桌的食物，风卷残云之后再冷静杀人施然离去。因身为警察的父亲涉毒而大受的打击的重案组探员伟（李灿森 饰），冷漠，行事不按指令，孤僻暴躁。在追捕鹏的过程中屡屡失败而令他愈来愈走向极端，以暴制暴的手段充满了血腥。鹏在逃亡途中遇上了轻微智障女子（裴唯莹  饰），互生情愫，最终二人一起逃回柬埔寨。伟死心不惜，追到了柬埔寨。二人狗咬狗般的追捕和互相角力又开始了！©豆瓣', '陈冠希', '郑保瑞', 8.1, 87209, 'tt0819765', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151061551.jpg', 0.6, 2.2, 19.1, 47.2, 30.9, '0.369106,0.028982,-0.673082,0.507375,0.174360,-0.261049,0.570229,0.425280,-0.200713,0.088753,0.434929,0.625878,-0.206407,-0.261107,0.149371,-0.441410,-0.226324,-0.715380,-0.581561,-0.010761,-0.237245,-0.304379,-0.002846,-0.157820,-0.050916,-0.051114,0.529599,0.156973,-0.323875,0.708843,0.258201,0.359600,-0.406557,0.415891,-0.384722,0.061978,-0.123705,-0.104008,-0.301571,-0.214537,0.272951,-0.629982,-0.038206,0.231092,0.004312,0.509731,0.795874,-0.419161,-0.111421,-0.318375,-0.050564,-0.332029,-0.414474,0.073428,0.514880,-0.096665,0.027057,0.263564,-0.010343,0.106926,-0.089575,0.263440,-0.511499,0.096177,-0.111464,0.292979,-0.381028,0.504482,-0.012460,0.416788,0.077929,-0.047081,0.079324,0.117834,-0.154641,0.347837,0.043074,0.016315,-0.498082,0.001699,0.662273,0.001233,0.032149,0.278501,-0.108957,-0.295118,-0.035783,-0.252914,-0.195131,-0.427871,0.417020,0.065396,-0.362043,0.232969,-0.730614,-0.089036,-0.129437,0.175035,-0.121787,-0.221424,-0.295261,-0.860125,-0.018024,-0.372329,-0.230562,0.313726,-0.130685,-0.132257,0.368549,-0.644626,0.021557,0.352665,0.273970,-0.343464,0.244573,-0.207520,-0.094586,0.085739,-0.138386,0.050552,0.263246,0.087297,0.570070,0.472716,-0.329849,-0.052721,-0.179040,0.119149', '26365262', '20274039', '1292050', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853176', '斯巴达300勇士', '动作', '这部电影描述了人类史上最残酷的战争之一：温泉关之战。公元前480年，波斯国王薛西斯一世（罗德里格•桑托罗 Rodrigo Santoro 饰）亲率30万大军征战希腊。希腊各个城邦迅速派出军队结成了联军，准备抵御波斯军队的入侵。防线的最前线设在希腊的温泉关，此处由斯巴达 城的国王列奥尼达（杰拉德•巴特勒 Gerard Butler 饰）率领本城300精兵和联军4000余人镇守。由于叛徒的出卖，希腊军队被波斯军队抄到了身后形成围剿之势。列奥尼达为了保存联军实力，让联军首先撤退，自己率领300精兵死守温泉关断后。数以十万波斯大军浩浩汤汤蜂拥而至，自知必死的斯巴达士兵反而士气高涨，在战斗中爆发出惊人的战力。整个战争整整持续了2天，最后列奥尼达和他的300精兵全部阵亡，而波斯军队则损失了20000多士兵，薛西斯一世的两个兄弟也在此役中战死……©豆瓣', '杰拉德·巴特勒', '扎克·施奈德', 7.9, 163078, 'tt0416449', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p443321967.jpg', 0.7, 2.9, 23.7, 46.9, 25.8, '-0.124266,-0.028902,-0.864006,0.693377,0.635127,0.160365,0.411154,0.082603,-0.357523,-0.115341,0.382301,0.373274,0.479697,-0.438802,0.455050,-0.525109,-0.224008,-0.869524,-0.458570,-0.212255,-0.172194,0.008978,-0.248705,-0.312390,-0.054680,-0.507892,0.779716,0.414116,-0.114957,0.380086,-0.094992,0.449642,0.028336,0.257074,0.429832,0.062565,0.019011,-0.757712,-0.070426,0.399751,-0.852756,-0.086228,-0.274336,0.167949,0.055727,0.154334,0.744768,-0.717358,0.382336,-0.041942,-0.240210,-0.446964,0.045134,-0.004010,0.536324,0.021767,0.098301,0.106632,0.140282,0.017968,-0.343405,-0.217206,-0.866819,-0.160769,-0.119765,-0.348693,-0.808247,0.601243,-0.123856,0.250352,0.223347,-0.028998,0.070840,1.108403,0.222399,0.035829,-0.017773,-0.226618,-0.706269,0.081682,0.627319,-0.400157,-0.126148,-0.605562,-0.066248,-0.382793,-0.130937,-0.605991,-0.251703,0.126937,0.206507,-0.408940,0.758288,0.433246,-0.822793,0.127658,-0.569357,-0.527473,-0.088165,0.068272,0.143363,-0.528768,-0.250001,0.032899,-0.010959,0.530029,0.207673,0.735314,0.760387,-0.295541,-0.196249,0.307385,0.556404,-0.573845,0.244079,0.180210,0.026679,0.345806,0.251018,0.599406,0.244624,0.338164,0.341942,0.088156,-0.271864,-0.172994,-0.328751,0.413506', '1424551', '4825006', '1422938', '26356488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853181', '兽餐', '喜剧', '在当地的小酒馆里，常年聚集着一群无所事事的人们，他们在这里喝酒，抽烟，聊天，打架，闹事，平庸的生活倒也过得自在。这一天和之前的每一天一样，甜心（珍妮·瓦德 Jenny Wade 饰），老板（杜恩·惠特克 Duane Whitaker 饰）和酒保（贾达·弗雷德兰德 Judah Friedlander 饰）用心的招呼着客人，而借宿在酒馆图菲（克里丝塔·艾伦 Krista Allen 饰）只得带着小儿子躲在房间里以避开嘈杂粗鲁的男人们。突然间，几个浑身是血的人冲进了酒馆并封死了门窗，在大家的震惊询问下，他们吐露了实情。原来，这些人遭到了一些可怕异型的袭击，而这间方圆数百里人气最旺盛的酒馆已然成为了异型们袭击的目标。平静惬意的夜晚突然变得惊悚和血腥起来，面对强大的异型，他们能够成功脱险吗？©豆瓣', '克里丝塔·艾伦', '约翰·古拉格', 6.3, 6553, 'tt0426459', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p878942025.jpg', 4.3, 15.9, 50.1, 21.5, 8.2, '0.521239,-0.007516,-0.742053,0.225247,-0.146265,-0.124780,1.084192,0.213439,-0.546099,-0.122965,0.220362,0.695722,-0.233019,0.243721,0.202455,-0.041138,-0.302939,-0.440650,-0.312350,-0.187629,-0.158442,-0.168908,-0.290936,-0.577829,-0.073853,-0.267799,-0.140380,0.041201,-0.024968,0.500513,0.241726,0.098821,-0.233179,0.492324,-0.303035,-0.068322,0.062361,-0.064788,-0.045562,0.055081,-0.239746,-0.198156,-0.505532,0.004989,0.156432,0.243906,0.458766,-0.157378,-0.340962,0.232634,0.161726,-0.208168,-0.075824,0.267972,0.390852,-0.234161,0.520146,-0.038178,-0.089773,0.135880,-0.009566,0.134397,-0.664649,0.243083,-0.059399,0.279636,-0.558415,0.525370,0.246667,-0.225595,0.064387,-0.335075,0.203374,0.190898,-0.244441,0.298805,-0.151648,-0.132437,-0.645555,-0.024020,0.698125,-0.064048,-0.279566,0.091441,-0.188545,-0.166194,0.012407,0.032597,-0.535102,-0.397972,0.395028,-0.007347,-0.095579,0.099042,-0.848130,0.189584,-0.014908,-0.363446,-0.171799,-0.153566,-0.372758,-0.971483,-0.033621,-0.366228,-0.332555,0.323335,-0.031915,0.097433,0.620447,-0.765257,0.211163,0.422959,0.235599,-0.032626,0.483234,-0.121879,0.177535,0.240439,-0.345052,0.060715,0.206300,0.490152,0.363176,0.765017,-0.286377,-0.005364,-0.708039,0.435508', '10466639', '1394176', '1301686', '1309101')