INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853621', '落叶归根', '剧情', '老赵（赵本山饰）是个五十多岁的农民，他南下深圳打工，因好友老刘死了，不得不走上背对方尸体回家安葬之旅。他先把老刘伪装成醉鬼，混上长途车，却不幸在途中遇上劫匪（郭德纲等饰）。救了一车人钱财的他反而给乘客赶下了车。老赵只好在路上拦车，晚上住店，钱却被偷。他到别人（午马饰）的葬礼哭丧，混得饭吃……一路上，老赵遇到形形色色的中国人。目标在望之际，他累晕了，在医院中苏醒后，警察告诉他，要按规定把尸体火化。老赵带着老刘的骨灰回到他的家乡，那儿却已经拆迁了。门板上，写着老刘的儿子的留言。©豆瓣', '赵本山', '张杨', 8.3, 159915, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1298673351.jpg', 0.3, 1.5, 17, 44.3, 36.9, '0.230409,-0.014690,-0.486594,0.079886,-0.394218,-0.626422,0.625844,0.218975,-0.307091,-0.007499,0.081080,0.413765,0.097876,0.545186,0.115462,-0.162941,-0.443454,-0.302597,-0.109382,0.061249,-0.637948,-0.049779,0.006247,-0.136716,-0.159197,0.229602,-0.020256,0.219884,0.203162,0.392138,0.257193,-0.165889,0.046893,0.533976,-0.591327,0.498157,-0.003116,-0.147988,0.239190,0.096986,0.176733,-0.748789,-0.105343,-0.148260,0.294471,0.513117,0.572996,0.315863,-0.033963,0.136275,-0.021475,-0.317404,0.037977,-0.017684,0.271797,0.018926,0.070634,-0.053364,-0.204466,-0.114220,0.170962,0.012949,-0.182622,0.171690,-0.206646,0.126907,-0.983463,0.361161,-0.008735,0.506754,-0.114997,-0.634788,0.504327,-0.066097,-0.199923,0.439709,0.088868,-0.052329,-0.690135,0.585439,0.470191,-0.110057,0.302598,-0.043243,0.056865,-0.196536,0.369297,-0.104982,-0.396598,-0.064217,0.646808,-0.292445,-0.411938,-0.256515,-0.431240,-0.217856,-0.089004,-0.145838,-0.145690,-0.060193,-0.051728,-0.545122,0.266587,-0.392176,-0.070543,0.340117,0.158717,0.026432,0.446961,-0.092304,0.188907,0.520737,0.337390,-0.507998,0.709867,-0.084525,0.046698,-0.010643,0.121290,-0.066168,0.281060,0.668967,0.551355,0.353760,-0.205341,-0.190885,-0.464035,0.459546', '1306505', '1303462', '1432825', '26801782');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853752', '机器人之恋', '剧情', '在精神病院里的朴一顺（郑智熏饰）是名强迫性适应青年，他认为自己可以窃取他人能力和思想，只要带上面具，别人就找不到他。他一直认为凡是任何能想到的东西，他都能偷过来。有一天，新来的女孩车英君（林秀晶饰）成为他的新目标。一顺发现英君从来不吃饭，她饭盒里装满了电池，英君称自己是个机器人，她听收音机，有时会对着电灯、自动售卖机讲话。一顺与这个自称是机器人的女孩成了好朋友，在她不开心时偷走她的心，并喜欢上了她。英君告诉一顺，机器人不能谈恋爱，一顺对英君说“你是机器人也无所谓”。英君的拒绝进食已经到了生命危险的地步，一顺为此开始想尽一切办法。©豆瓣', '郑智薰', '朴赞郁', 6.5, 18889, 'tt0497137', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p613595811.jpg', 3, 14.3, 46.8, 25.7, 10.1, '0.281892,0.283241,-0.758835,0.311089,-0.813967,0.068038,0.598365,-0.118657,-0.573097,-0.121231,-0.081342,0.757812,0.062078,0.224602,-0.066304,0.256382,-0.212036,-0.563839,0.005476,-0.176903,-0.547179,-0.397589,-0.204489,-0.364695,-0.170292,-0.295905,0.179468,-0.156303,-0.275044,-0.052426,0.332122,-0.058795,0.301978,0.708800,-0.293457,-0.038330,-0.377329,-0.173099,0.165960,0.187633,0.062138,-0.121231,-0.056385,0.248257,-0.074543,0.293783,0.464294,-0.042087,-0.257282,0.053511,0.160130,-0.052192,-0.065014,0.004841,0.183625,0.005615,0.095293,0.090117,-0.231969,0.255835,0.204623,0.097175,-0.756861,-0.186983,-0.194865,0.319324,-0.591051,0.326416,-0.245322,-0.077039,0.132564,-0.489518,0.191133,-0.142379,0.220373,0.250528,-0.162803,-0.141665,-0.845820,0.275088,0.526711,0.009227,-0.234885,0.558183,-0.044745,-0.251577,-0.108353,-0.160777,-0.499370,-0.025442,0.068986,0.269565,-0.411629,-0.073726,-0.243611,0.186526,0.065054,-0.020098,0.085080,-0.477625,0.170609,-0.108703,0.122376,-0.453944,-0.359087,0.226251,-0.094689,-0.436933,0.611667,-1.044351,0.101967,0.590748,0.384784,-0.601301,0.789478,0.178077,-0.254594,-0.288855,0.065275,-0.120188,-0.000292,0.260163,0.281956,0.498674,0.468759,-0.196422,-0.186060,0.515378', '1783461', '2052978', '1308805', '1292719');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853768', '蝙蝠', '剧情', '相铉（宋康昊 饰）是一位受人崇敬的神父，他目睹了很多临终病人的告解，也以主的名义送别了他们。相铉自小在教堂的孤儿院长大，领养他的是一位双目失明的牧师。牧师知道他想做一个测试抗病毒药物的志愿者，极力劝阻，但他一意孤行，希望如耶稣般以身殉道。结果，500人的项目仅他一人生还，这个奇迹使他成为被顶礼膜拜的神父。但是他内心却隐藏着一个不可告人的苦衷……一位母亲恳请他为自己罹患癌症的儿子康宇（申河均 饰）祈祷，他欣然应允，并意外发现患者是他童年的玩伴。在每周三的祈祷中，相铉结识了患者的妻子泰举（金玉彬 饰）。她不但沉默寡言，而且还有夜游的习惯。在一次意外接触中，两人堕入情网，然而这段爱情却逐渐被心魔导入了地狱……本片获得第62届戛纳电影节评审团特别奖。©豆瓣', '宋康昊', '朴赞郁', 7.4, 34403, 'tt0762073', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p571309710.jpg', 1, 4.5, 33.3, 43.6, 17.6, '-0.028759,0.025190,-0.581715,0.664498,-0.250040,-0.171445,0.795175,0.120007,-0.450853,-0.282410,0.511080,0.990534,-0.156588,0.382132,0.068056,0.013704,0.045567,-0.468491,0.217628,-0.061474,-0.216107,-0.295445,-0.361098,-0.229319,-0.216972,-0.395499,0.539115,0.071780,0.035588,0.344079,0.423622,0.248714,0.145474,0.577397,-0.297536,0.056834,0.108182,-0.065148,-0.030047,0.087221,-0.022602,-0.335429,-0.286229,0.449764,-0.155341,0.471374,0.542071,-0.207293,-0.177976,-0.109602,0.388601,-0.375368,0.020667,0.235988,0.128953,0.063387,0.010974,0.266849,-0.025239,0.086765,-0.035835,0.034528,-0.825272,-0.233685,0.180549,0.268493,-0.646720,0.511432,0.015740,0.025663,-0.111949,-0.123232,0.096474,0.059812,0.103168,0.403121,-0.293579,-0.107227,-0.529218,0.428934,0.518727,-0.121361,-0.413184,0.513640,-0.481940,-0.543042,0.066532,-0.073739,-0.626331,0.126198,0.240429,-0.065209,-0.405162,0.077985,-0.269018,-0.209956,-0.325818,-0.015041,-0.292065,-0.365079,0.146964,-0.452919,0.012471,-0.213232,-0.371034,-0.079506,0.065789,-0.439583,0.844527,-0.672844,0.301456,0.647722,0.185084,-0.649596,0.841876,0.361125,0.052388,-0.175124,-0.187252,0.424995,-0.139892,0.120459,-0.012210,0.353935,0.068057,0.158894,-0.419142,0.253126', '34890458', '1456503', '30162520', '2028634');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1853770', '密阳', '剧情', '申爱（全度妍饰）带着儿子来到亡夫的故乡——小城密阳。她在那里开了一家钢琴学院，希望和儿子寻找一段崭新的人生，让儿子在亡夫小时候成长的地方成长，感受密阳的阳光和人情。然而车在半路抛锚，幸遇宗灿（宋康昊饰）前来相助，他是名汽车修理厂的老板，平凡的他热心地帮申爱找房子、拉拢客户，定制奖牌，然而这过分的热情让申爱感到不安，只得坦白告诉他不要打自己主意。一天灾难不幸降临到申爱和儿子身上，她几乎丧失了继续生存的勇气，直到宗教给了她精神救助。然而，信教之后的心灵也没能平静多久。申爱很快又陷入自我矛盾的分裂中，转而不信任它并报复性地攻击。在整个过程中，只有宗灿一直陪伴在她身边，直到申爱重见一缕阳光。©豆瓣', '全度妍', '李沧东', 8, 53742, 'tt0817225', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1193264503.jpg', 0.5, 1.8, 21.3, 51.4, 25.1, '-0.085407,0.352923,-0.676368,0.483073,-0.221217,-0.382935,0.428581,0.382250,-0.520641,-0.104862,0.233012,0.572109,0.098575,0.303032,0.188550,0.074596,-0.359745,-0.531188,0.143285,0.159532,-0.352588,-0.341373,-0.096259,-0.213666,-0.106393,-0.401024,0.363954,0.416791,-0.010759,0.487285,0.099493,0.046185,-0.057098,0.673011,-0.129905,-0.004106,-0.044463,0.090838,-0.279854,0.145008,-0.077118,-0.326571,-0.290143,0.289834,-0.006301,0.171896,0.636372,0.057821,-0.248872,-0.011558,0.246728,-0.227816,-0.046842,-0.028958,0.140037,0.125155,0.362092,0.132359,-0.199521,-0.053296,0.104763,0.036060,-0.669719,0.101040,-0.006836,-0.037945,-0.674745,0.464987,-0.041667,-0.250848,0.169409,-0.212691,0.292552,0.278958,0.120536,0.295335,-0.448978,0.136641,-0.315007,0.126677,0.614773,-0.269381,-0.108385,0.382846,-0.282560,-0.140354,0.081001,-0.092057,-0.544758,0.041269,0.247340,0.328717,-0.346196,0.027511,-0.574888,0.097793,-0.283767,-0.150448,0.056077,-0.617470,-0.003420,-0.215262,-0.150857,-0.202840,-0.301712,0.012239,-0.050506,-0.113582,0.641645,-0.551222,0.393954,0.454605,0.440205,-0.397918,0.727795,0.089503,0.020562,-0.203374,0.159571,0.255935,-0.145816,0.423631,0.120542,0.113189,-0.218657,0.194592,-0.478938,0.469007', '4604803', '21360412', '26021055', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1855131', '东京塔', '剧情', '小时候的雅也由于老爸和老妈的离婚，离开了故乡小仓。年轻的老妈（内田也哉子饰）带着他回到筑丰老家，她一边在小料理屋帮忙，一边培养自己的孩子。学校放长假时，雅也也会去老爸住的地方。上了中学，雅也想着从这个小地方出去，就这样，他一直走到了向往的东京。但作为大学生的雅也（小田切让饰）却过着失败的日子，勉强留级后毕业，老妈（树木希林饰）对此毫无怨言，尽管患病却一心支持着儿子。后来雅也终于醒悟找到了工作，还清积欠的债务，成为插图画家、专栏作家还做广播节目。雅也把老妈接到了东京一起生活，她受到了朋友们的尊敬和喜爱。这时离雅也15岁离开老妈后过去了15年，后来老妈却癌症复发……©豆瓣', '小田切让', '松冈锭司', 8.6, 34115, 'tt0820158', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2177767108.jpg', 0.1, 0.6, 11.7, 41.8, 45.7, '0.203625,0.197396,-0.709275,0.291462,0.063331,-0.643731,0.277086,-0.002064,-0.403291,-0.400904,-0.157993,0.836825,-0.022792,0.836469,0.014496,0.085108,-0.554155,-0.616858,0.038782,-0.042926,-0.538337,-0.201742,0.193210,0.138082,-0.344833,-0.191319,0.129450,-0.065171,-0.003182,0.524669,0.217891,-0.047347,0.241504,0.604472,-0.185780,0.248729,-0.208723,0.163418,-0.026899,-0.004537,0.526185,-0.292338,-0.291964,-0.069362,0.840883,0.248692,0.752684,0.095745,-0.240278,0.064175,0.172993,-0.281510,-0.170159,0.062720,0.286185,-0.152091,0.192914,0.196012,-0.289475,0.094170,-0.262969,-0.180687,-0.347238,0.078893,-0.175954,-0.117106,-0.672704,0.437958,-0.039160,-0.069315,0.108997,-0.562079,0.258259,0.350267,-0.307197,0.557123,-0.501873,0.274348,-0.470302,0.271546,0.715907,0.144721,0.070782,0.209383,-0.405682,-0.304098,-0.098285,-0.223312,-0.429302,-0.046924,0.048912,-0.003346,-0.313076,-0.056821,-0.319143,-0.197197,-0.331048,-0.124104,0.089337,-0.468785,-0.220727,-0.357962,0.303639,-0.310461,-0.518042,0.184916,0.048156,-0.343520,0.803603,-0.663445,0.196420,0.539899,0.805377,-0.485679,0.737990,-0.161924,0.148963,-0.085251,-0.143654,0.357879,-0.155365,0.357964,0.343256,0.284927,-0.047516,-0.463492,-0.399420,0.379858', '1292219', '1292337', '1309013', '25731805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1855834', '充气娃娃之恋', '剧情', '在寒冷的冰雪中，单身汉拉斯（瑞恩•高斯林 Ryan Gosling 饰）感到有些孤寂而无聊。他是一个典型的宅男，性格自闭，无友无伴。他的哥哥格斯（保罗•施耐德 Paul Schneider 饰）和嫂子（艾米莉•莫迪默 Emily Mortimer 饰）住在隔壁，见此情景也觉得辛酸。嫂子见他整天宅在家中，于是邀请他前来吃饭，但是兄嫂的嘘寒问暖仍无济于事。某天，拉斯居然从玩具公司定制了一个充气娃娃比安卡，并带她参加家庭聚会，一起吃饭，一起入眠，一起去教堂礼拜。周围的人都觉得拉斯的精神不正常，兄嫂为此专门咨询了医生达戈玛（派翠西娅•克拉克森 Patricia Clarkson 饰），后者认为拉斯的症状是一种幻觉，最好的治疗就是因势利导。而此时，拉斯对于比安卡的痴迷已经达到了无以复加的地步，甚至还要在教堂跟它举行婚礼……©豆瓣', '瑞恩·高斯林', '克雷格·吉勒斯佩', 7.6, 43501, 'tt0805564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p813316203.jpg', 0.6, 3, 29.9, 49.5, 17.1, '0.146683,-0.176180,-0.591430,0.329420,-0.138401,-0.367204,0.834749,0.395753,-0.557751,-0.365355,0.264876,0.757767,-0.181881,0.450258,0.384699,0.057140,-0.393351,-0.314998,0.067454,0.083626,-0.254918,-0.348184,0.030954,-0.302488,0.010277,-0.393049,0.158901,-0.248117,0.260782,0.431611,0.223513,0.208930,-0.020476,0.702450,0.094059,-0.222354,0.047504,-0.074060,-0.182885,0.136702,0.070234,0.140853,-0.159624,0.143329,0.293562,0.125923,0.330929,-0.114207,-0.008755,-0.165154,0.196884,-0.028310,-0.051104,0.243163,0.056624,-0.310773,0.418745,-0.154374,-0.118124,0.130811,0.295912,0.053320,-0.462096,0.340619,0.197094,0.191710,-0.356393,0.401218,-0.201841,-0.350982,-0.052037,-0.405344,0.223365,0.191624,0.164873,0.487670,-0.100086,-0.040081,-0.571601,0.058875,0.489858,0.260143,-0.181171,0.175235,-0.269061,-0.313697,0.007203,-0.023043,-0.548438,-0.079313,-0.050257,-0.010305,-0.267415,0.152056,-0.581519,0.092020,-0.141086,-0.207613,-0.212662,-0.410466,0.068762,-0.691807,0.119618,-0.398946,-0.365512,-0.249322,0.308571,-0.131248,0.327390,-0.752092,0.245404,0.539346,0.340861,-0.101430,0.717339,0.081883,-0.086325,-0.052869,-0.236452,0.180329,-0.094924,0.320001,0.194831,0.595882,0.152044,0.050635,-0.262961,0.567057', '1309172', '1301686', '1308755', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1856436', '红气球之旅', '剧情', '本片为侯孝贤向法国导演艾尔伯特•拉摩里斯（Albert Lamorisse）拍摄于1956年的短片、在电影史上有重要地位的《红气球（Le Ballon Rouge）》的致敬之作，也是他继《咖啡时光》之后拍摄的第二部致敬外语片。Suzanne（朱丽叶•比诺什 Juliette Binoche）每日为一出筹备中的改编自中国元曲的木偶剧《求妻煮海人》中角色的声音演出以及其它琐事忙得焦头烂额，加上丈夫Pierre远在加拿大蒙特利尔写小说，儿子Simon（Simon Iteanu）成了“累赘”，无奈，她请了在巴黎念电影的中国女孩Song（宋芳 Song Fang）照料Simon。与Simon在一起时，Song双手始终不离摄影机，并向好奇她在拍什么的Simon提及《红气球》。Suzanne的房客Marc（Hippolyte GirardotLouise）仗着是Pierre的朋友，时常做出一些令她愤怒的事，而房租更是借口生活贫困已经好几个月未交。Suzanne有心接在布鲁塞尔的女儿Louise（Louise Margolin）回巴黎念书，决定赶走Marc，却不得Pierre理解。将一切看在眼里的Song没有参与类似琐事，她与Suzanne保持着淡然的朋友关系，多数时间想的只是她的电影：Simon发现一个无人理会的大红气球，拉着它穿越巴黎的大街小巷的过程，被她记录在摄影机里，成了一部电影中的电影。之后，该红气球也似有生命般，始终在Simon出现的地点上空飘来荡去。', '朱丽叶·比诺什', '侯孝贤', 7.4, 9202, 'tt0826711', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2516801273.jpg', 0.7, 3.5, 35.2, 46.8, 13.8, '0.256795,0.047544,-0.686778,0.688577,0.158983,-0.201358,0.771221,0.193018,-0.391015,-0.172078,0.067373,0.700770,-0.264367,0.138638,0.121375,-0.071473,-0.500032,-0.873198,-0.262565,-0.133370,-0.161291,-0.340736,-0.217990,-0.133396,-0.277042,-0.337480,0.404468,0.054854,-0.015653,0.275389,0.233386,-0.129062,-0.140158,0.344140,-0.139172,0.002094,-0.280297,0.064161,-0.332898,0.363444,0.204162,-0.316120,-0.414516,-0.062460,0.116610,0.428244,0.683939,-0.083121,-0.061044,0.157331,0.463857,-0.305818,-0.023610,-0.022560,0.133599,0.176979,0.240363,-0.031525,-0.275513,0.258237,0.100725,-0.266309,-0.658098,0.150895,0.124629,0.494248,-0.695171,0.727184,-0.188585,-0.028472,0.064907,-0.398673,0.272416,0.089310,0.113017,0.497082,-0.063577,0.196424,-0.427293,0.501294,0.543310,0.178671,-0.139381,0.398759,-0.150704,-0.209705,-0.261977,-0.152784,-0.523071,-0.013761,0.134511,-0.018327,-0.270222,0.209511,-0.392021,0.005974,0.059032,-0.414962,0.063664,-0.464920,-0.085658,-0.714513,0.138972,-0.391866,-0.130912,-0.172733,0.294784,-0.262309,0.670265,-0.635196,0.231061,0.530471,0.261521,-0.288684,0.851045,0.054787,0.051649,-0.021391,-0.001411,0.106695,-0.055975,0.335112,0.254820,0.221464,-0.031072,-0.284301,-0.411969,0.464227', '30162520', '3055049', '1303449', '1298880');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1856675', '海贼王剧场版1：黄金岛冒险', '喜剧', '在遥远的东海海域，曾经有一位人称黄金大海贼的海盗名叫邬南。他从来不欺凌百姓，只与其他邪恶的海贼拼杀，并由此聚敛了堆积如山占世界总量三分之一的黄金，他的财富可以将夜晚照得亮如白昼。邬南将这些黄金藏在一个不知名的小岛上，随后不知去向。众海贼们无不垂涎于那座黄金山，而邬南手下当初绘制的藏宝图更成为海贼们竞相追逐的对象。再次遭遇饥饿困扰的草帽海贼团遇到了一心脱离贫困的小男孩飞男，从他的口中，路飞得知了邬南及其黄金岛的秘密，于是决定向小岛进发。与此同时，邪恶的海贼黄金龙也正驾船接近小岛。多支人马在小岛相遇，看来一场精彩拼杀在所难免……©豆瓣', '田中真弓', '志水淳儿', 7.8, 13488, 'tt0814243', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2300512475.jpg', 0.5, 2.8, 30, 41.4, 25.3, '0.166928,-0.087388,-0.797450,0.419099,-0.028333,0.028125,0.814936,-0.052968,-0.377851,0.172351,0.366165,0.687232,0.084911,0.091564,0.153485,-0.035427,-0.099525,-0.534529,-0.326186,-0.368095,-0.045212,-0.372614,-0.478718,-0.303743,-0.199064,-0.251388,0.745965,0.424384,-0.171643,0.315949,0.262184,0.351415,-0.477781,0.431625,-0.652371,-0.169848,-0.008684,0.024710,-0.079924,0.043014,-0.529952,-0.136323,-0.007004,0.063422,-0.066649,0.191528,0.998297,-0.543340,-0.059897,-0.287737,0.095677,-0.364337,0.058191,0.129447,0.495630,-0.068368,-0.113204,-0.140788,-0.040416,0.028657,0.054920,-0.079967,-0.547605,-0.136309,0.191890,0.280547,-0.381333,0.385051,0.199204,-0.239738,0.228395,-0.083365,0.106174,0.269498,-0.055833,0.108566,-0.026715,0.002648,-0.530749,0.389370,0.732978,0.016831,-0.035389,0.071651,0.041773,-0.397761,-0.197354,-0.154230,-0.271211,-0.146543,0.682515,0.067308,-0.125226,0.468439,-0.962468,0.201198,-0.100199,-0.474495,0.116171,-0.124681,-0.468543,-0.617491,0.040178,-0.265273,0.053750,0.183618,0.190384,0.031200,0.900252,-0.507677,0.096728,0.492175,0.299215,-0.310865,0.504225,-0.083940,0.040728,-0.050668,-0.072875,0.335325,0.371774,0.568627,0.085071,-0.030474,-0.192138,-0.253635,-0.298487,0.381694', '21619567', '26290398', '24879819', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1857099', '老无所依', '剧情', '美国德克萨斯州乡村，老牛仔Moss（乔什·布洛林 饰）在猎杀羚羊时发现几具尸体，几包海洛因和200万现金。Moss决定将毒品和现金占为己有，想以此改变自己的生活，谁知却遭到冷血杀手Chigurh（哈维尔·巴登 饰）的跟踪和追杀，陷入了逃亡的险境。同时，当地治安官Bell（汤米·李·琼斯 饰）也在对一连串的杀人事件进行调查，并努力保护Moss的安全。但是，让Bell感到无力绝望的是，他使尽浑身解数也无法追踪到冷血杀手，Moss的生命安全也受到严重的威胁，Bell一边缅怀父辈们的光荣岁月，一边深感现实中老无所依的悲哀。©豆瓣', '汤米·李·琼斯', '伊桑·科恩', 8.3, 278444, 'tt0477348', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p551171670.jpg', 0.4, 1.6, 15.8, 46.1, 36.1, '0.140694,-0.182380,-0.473736,0.523047,-0.065445,-0.246342,0.839828,0.018094,-0.588775,-0.291142,0.237617,0.579326,0.180263,0.036623,0.057384,-0.216691,-0.337215,-0.700458,-0.244677,0.029615,-0.451392,-0.470130,-0.277773,-0.404921,-0.209711,-0.321058,0.489998,0.387248,-0.387186,0.511074,0.280269,0.546399,-0.150764,0.591971,-0.171837,-0.128063,-0.047038,-0.084271,-0.296758,0.054826,0.238183,-0.452136,-0.207647,0.371965,0.207775,0.453756,0.789058,-0.333845,-0.373207,-0.003174,0.293080,-0.465702,0.001042,0.191531,0.201664,-0.002839,-0.190756,-0.047087,-0.249821,0.046408,0.332272,0.265340,-1.235746,-0.132040,0.034464,0.070123,-0.647212,0.187100,-0.133796,0.178374,0.043442,-0.225972,0.219466,0.168870,0.312723,0.271180,-0.310504,0.033779,-0.540724,0.171403,0.696907,-0.072361,-0.041889,-0.074955,-0.280761,-0.446658,-0.049208,-0.289585,-0.430258,-0.132952,0.355527,0.172610,-0.242548,0.248732,-0.695526,-0.134442,-0.323042,-0.488376,-0.148917,-0.324497,-0.109209,-0.553976,-0.169753,-0.358906,-0.247538,0.180770,0.304230,-0.285609,0.492845,-0.607568,0.239839,0.651188,0.249669,-0.622899,0.430848,0.064801,0.061191,-0.045176,-0.235500,0.365970,0.395514,0.350968,0.392409,0.155553,0.010684,-0.139493,-0.255370,0.302931', '26678784', '1793491', '4820775', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1857175', '屋顶上的童年时光', '剧情', '11岁的汤米（亚力桑多•摩瑞斯饰）和姐姐薇奥拉（玛塔•诺比莉饰）、父亲雷纳托（吉姆•罗西•斯图尔特饰）同住罗马，一家三人面对琐碎的家庭问题，时常发生争吵，却也还算甜蜜。汤米喜欢爬上屋顶，俯瞰这座城市。他喜欢踢足球，父亲却要求他去学游泳，并向冠军目标冲刺。工作不顺利时，他经常发火。姐姐喜欢捉弄他，引得他生气。他有伙伴，却更喜欢一个人的空间。一天母亲斯特芬妮突然返回家中，她被父亲骂为“水性杨花”。不定期离家出走的母亲，跪着请求家人原谅，承诺不再离开，但汤米却疑心重重，母亲会留在家里吗？这个家庭会不会有新的问题？©豆瓣', 'Alessandro Morace', '吉姆·罗斯·斯图尔特', 8.4, 7449, 'tt0456041', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1162930506.jpg', 0.1, 0.5, 14.5, 49.8, 35.1, '0.103555,-0.193108,-0.775949,0.274448,-0.251563,-0.286308,0.697508,0.215416,-0.347251,-0.167616,0.223087,0.881119,0.124931,0.182797,-0.068799,0.290982,-0.476984,-0.554979,0.505195,-0.013692,-0.078096,-0.557146,0.207722,-0.303700,-0.059646,-0.210638,0.009795,-0.315782,-0.049974,0.338452,0.046373,0.230045,0.146319,0.665467,-0.070195,0.062875,0.015571,0.146367,-0.046962,0.137594,0.053879,0.182954,-0.249524,-0.062774,0.335638,0.246690,0.313683,-0.020086,-0.241993,-0.227002,0.173615,-0.165695,0.350382,0.180251,0.164869,-0.401856,0.294605,0.175609,-0.045260,0.041091,-0.050448,-0.138813,-0.142383,0.217593,-0.040641,0.065101,-0.581088,0.325118,-0.319288,-0.053932,0.098050,-0.334692,0.047232,0.378212,0.176807,0.176696,-0.347958,0.159744,-0.348836,-0.147253,0.702364,0.132290,-0.000079,0.236141,-0.355109,-0.088168,0.134806,-0.063781,-0.705088,0.068547,0.065956,0.017679,-0.159632,0.174423,-0.146416,0.007184,-0.254092,-0.051392,0.029954,-0.413436,-0.077730,-0.091942,0.186456,-0.134066,-0.424496,-0.220433,-0.174764,-0.289126,0.437897,-0.707708,0.378863,0.507410,0.833049,-0.536245,0.669099,0.373985,0.040368,-0.183651,0.059915,0.430774,-0.146277,0.002712,-0.159670,-0.002795,0.459079,-0.141513,-0.148467,0.412632', '26718282', '1308637', '1292869', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1858233', '春天情书', '剧情', '学生时代作为出色的美式足球选手大出风头，但因伤隐退后，速见升（内野圣阳 饰）进入东京一家公司成为平凡的上班族。无聊烦恼的职场交际和女友不咸不淡的往来令他倍感烦闷。在此之后，他以“春（ハル）”作网名，登陆一个电影留言板寻求同好。留言板上充斥着热爱电影的人群，速见独独与网名“星星（ほし）”的陌生人相聊甚欢。未过多久，他们通过私人邮件聊天，从电影聊到爱情、事业、人生。星星的真实身份是住在盛冈的女孩藤间美津江（深津绘里 饰），多年前爱情道路上的巨大打击让她始终无法向前迈出一步。她不停地变换工作，仿佛一只找不到归宿的鸟儿。通过邮件，星星和春天彼此牵绊与吸引，成为了虚拟时代来临时从未谋面的知心好友。两人的话题不断深入，看似一切美好，直到一次意外状况发生，令他们之间的信任接受史无前例的考验……本片荣获第70回日本电影旬报十佳影片第四名。©豆瓣', '深津绘里', '森田芳光', 8.6, 15196, 'tt0115431', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2327619627.jpg', 0.3, 1, 10.5, 44.4, 43.8, '0.115183,0.100152,-0.565576,0.605674,0.352899,-0.078987,0.500378,0.203302,-0.531638,-0.049728,-0.019357,0.530713,-0.336219,0.298299,0.246168,-0.044407,-0.200813,-0.800400,0.045296,-0.110156,0.007991,-0.263291,-0.315858,0.001918,-0.133028,-0.246305,0.697713,0.129992,-0.229769,0.379986,0.255446,0.071439,-0.314930,0.324474,0.054545,-0.160984,0.174703,0.376599,-0.509241,0.222145,-0.224967,-0.089100,-0.273464,-0.152085,-0.043932,0.273331,0.736048,-0.175529,-0.357577,-0.009895,0.577045,-0.109735,-0.236847,-0.078355,0.092592,0.294151,0.175417,0.095069,0.070368,0.048970,-0.185971,-0.134138,-0.557648,0.116086,0.064386,0.227603,-0.315666,0.577871,-0.011678,-0.068174,0.150566,-0.354754,0.117499,0.100181,0.456806,0.214634,-0.238844,0.324080,-0.167193,0.356530,0.821048,0.390138,-0.593004,0.527544,-0.320192,-0.157819,-0.150421,-0.218144,-0.562328,0.069859,0.185020,0.120874,-0.049280,0.193912,-0.534947,0.147400,-0.040366,-0.174139,0.258748,-0.585591,0.024627,-0.765842,-0.008594,-0.255446,-0.360128,-0.111766,0.063604,-0.417446,0.799667,-0.655797,0.137617,0.608662,0.132705,-0.299141,0.898685,0.117471,-0.015916,-0.386590,0.092803,0.267022,-0.021806,0.324961,-0.061180,-0.003105,-0.407319,0.168079,-0.505289,0.325073', '3811356', '4301278', '1302050', '