INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1858270', '生死格斗', '动作', '为了追寻哥哥的踪迹，某国公主霞（戴文青木 Devon Aoki 饰）坚持要参加世界上最权威的格斗比赛“生死格斗”，在比赛中，参赛者随时都有丧命的危险，而自己的命只有自己负责。与此同时，女飞贼艾伦（霍莉·瓦兰丝 Holly Valance 饰）、摔跤手蒂娜（杰米·普莱斯利 Jaime Pressly 饰）、游戏主办者的侄女海伦娜（莎拉·卡特 Sarah Carter 饰），以及世界各地的武术高手都收到了比赛的邀请函，一帮野心勃勃的武者向着比赛场地神秘岛进发，他们各有各的隐情，但最终目的都是打倒对手，获得千万奖金。选手们在岛上接受了严格的训练，比赛层层推进，他们闯五关斩六将，但是随着比赛的进行，某些令人不安的真相渐渐的浮出水面，这场比赛真的仅仅是为了决出世界最强武者而举办的吗？影片根据热门同名游戏改编而成，以其极高的还原度在广大玩家中引起了共鸣。©豆瓣', '杰米·普莱斯利', '元奎', 5.2, 9777, 'tt0398913', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1986703343.jpg', 12.3, 32.6, 40.6, 10.4, 4.1, '-0.204216,0.006248,-0.421094,0.655076,0.047932,0.072589,0.302102,-0.124179,-0.174472,-0.070187,0.626733,0.680340,-0.183006,-0.129733,0.359794,-0.429233,-0.190403,-0.765869,-0.162179,-0.167769,-0.499181,-0.492458,-0.143867,-0.125886,0.083432,-0.417292,0.926617,0.186433,-0.358675,0.307505,0.336630,0.093447,-0.244957,0.182392,0.101155,-0.330190,0.250289,-0.005579,-0.263926,0.311859,-0.220025,0.107154,-0.311418,0.098851,0.207664,0.396822,0.644899,-0.496230,0.206093,0.093875,0.307319,-0.347182,-0.087070,0.065702,0.363128,0.012830,0.232608,0.222380,0.212610,0.211860,-0.117735,-0.221088,-0.797788,0.132302,0.334151,0.168354,-0.195914,0.382665,-0.039748,-0.029095,0.055901,0.173660,0.130928,0.426647,0.288526,-0.102219,-0.171168,-0.230534,-0.399881,0.209039,0.584580,-0.137591,-0.199419,0.005562,-0.164517,-0.564100,-0.104777,-0.620685,-0.160708,0.119385,0.407449,0.103291,0.176577,0.166138,-0.545352,0.101441,0.156940,-0.614911,-0.039747,-0.288177,0.129419,-0.854211,0.143611,-0.170455,-0.236413,-0.196617,0.059144,-0.412939,0.970800,-0.970675,0.067615,0.617155,0.120082,-0.444299,0.714647,-0.059052,0.214522,-0.129283,-0.389366,0.111665,-0.034382,0.177958,-0.228802,0.430228,0.094920,-0.339552,-0.266470,0.634941', '25880986', '27602116', '2369613', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1858678', '没有青春的青春', '剧情', '本片改编自罗马尼亚神学家伊利亚德的同名小说。1938年，年逾七十的哲学教授多米尼克•马泰（蒂姆•罗斯 Tim Roth 饰）本打算自杀，却被闪电突然击中。严重烧伤的多米尼克得到了罗马尼亚医生斯坦库里斯库教授（布鲁诺•岗茨 Bruno Ganz 饰）的救治，痊愈后，多米尼克竟发现自己返老还童，并分裂出另外人格。不仅如此，多米尼克还具有梦中学习、透视、意念移物等特异功能。为了躲避纳粹医生鲁道夫（安德烈•汉尼克André Hennicke 饰）的追踪，多米尼克化名辗转于瑞士、罗马尼亚、马耳他、印度等地，直到二战结束。六十年代，某次登山时多米尼克遇见一名叫做维拉尼卡的女子（亚历山德拉•玛利亚•拉拉 Alexandra Maria Lara 饰），与他年轻时的未婚妻劳拉一模一样。维拉尼卡及朋友山中遇险，被多米尼克救治后便拥有了梦中追溯语言起始的能力，却因此加速衰老。多米尼克一方面希望维拉尼卡助他完成语言及时间起源的著作，一方面又不愿看到爱人因此早夭，矛盾中痛苦不已……本片获独立精神奖最佳摄影提名。', '蒂姆·罗斯', '弗朗西斯·福特·科波拉', 7.6, 7891, 'tt0481797', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1517878485.jpg', 0.9, 4.1, 30, 44.9, 20.1, '0.081377,-0.012822,-0.489712,0.409428,0.255226,-0.541183,0.412828,-0.095876,-0.374654,-0.672608,-0.002730,0.524493,-0.298182,0.045019,0.352056,0.075220,-0.440528,-0.682507,0.141556,0.029334,-0.402128,-0.520226,-0.286301,-0.065975,-0.071698,-0.730802,0.231457,-0.042289,-0.126391,0.348588,-0.086257,0.410081,0.097155,0.055121,0.064349,0.118260,0.202233,-0.305782,-0.363738,0.342228,0.272129,-0.025770,-0.097818,0.033872,-0.103074,0.409517,0.530147,-0.296221,0.338988,-0.169112,0.319611,0.071258,-0.039175,-0.032743,0.022149,-0.002092,0.168371,0.112984,-0.060595,-0.024032,0.063823,0.103942,-0.508659,0.128424,-0.058047,0.223565,-0.104165,0.057719,-0.284661,0.056576,-0.041838,-0.257964,-0.029458,0.244491,0.331864,0.224752,-0.067090,-0.092823,-0.299190,0.108475,0.299430,-0.165988,-0.393099,0.232999,-0.272980,-0.484883,0.263256,-0.144956,-0.031658,0.062912,0.236355,0.191599,0.109423,0.342254,-0.304112,-0.048673,-0.782503,0.002975,-0.146079,0.107831,-0.082033,-0.719479,0.055762,-0.003452,-0.119735,-0.120274,0.046023,-0.157295,0.484123,-0.419266,0.383645,0.493156,0.328465,0.121958,0.376925,-0.059217,-0.030476,-0.214012,-0.210467,0.669584,0.125857,0.077678,-0.041963,0.068947,0.116424,-0.214483,-0.231113,0.410729', '2338056', '7916027', '1306607', '3148027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1858711', '玩具总动员3', '喜剧', '距上一次的冒险已经过去11个年头，转眼间安迪（约翰·莫里斯 John Morris 配音）变成了17岁的阳光男孩。这年夏天，安迪即将开始大学生活，他必须将自己的房间收拾整齐留给妹妹。此前，伍迪（汤姆·汉克斯 Tom Hanks 配音）与巴斯光年（蒂姆·艾伦 Tim Allen 配音）等玩具一直期待安迪再和他们玩耍，但是随着岁月的流逝，他们被冷落在箱子里很久了。安迪十分珍惜这些童年的玩伴，于是准备将他们收在阁楼。谁曾想，妈妈却把玩具们当作废物扔到街道上。玩具们误解了安迪，于是愤然出走，宁可被捐赠到阳光之家幼儿园。伍迪尽力劝解大家，却收效甚微，只得独自黯然离开。巴斯光年他们原本以为将重新回到往昔的快乐时光，不料却陷入一场阴谋之中……©豆瓣', '汤姆·汉克斯', '李·昂克里奇', 8.9, 477336, 'tt0435761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1283675359.jpg', 0.1, 0.4, 9, 36.1, 54.4, '0.371466,0.096392,-0.613317,0.175511,-0.330479,-0.595028,0.779396,0.043868,-0.486952,-0.243832,-0.087470,0.635288,-0.147311,0.584830,0.169467,0.001539,-0.584557,-0.754637,-0.002413,-0.308420,-0.048675,-0.220533,-0.104233,-0.194836,-0.215491,-0.087336,0.476238,-0.059479,0.359617,0.515396,-0.029353,0.104614,-0.113231,0.542691,-0.174064,0.304398,0.045801,-0.153032,-0.221125,0.035008,0.010160,-0.180797,-0.269842,0.060444,0.296703,0.007074,0.797968,-0.151009,-0.022795,0.038443,0.159025,-0.333109,-0.080099,0.244665,0.128686,0.231658,0.234084,0.037015,-0.184433,0.115361,-0.036003,-0.305087,-0.312089,0.265787,-0.142571,0.051073,-0.688567,0.401703,-0.060771,0.091380,0.162127,-0.456943,0.062128,0.164272,0.192201,0.309856,-0.345228,0.058431,-0.389408,0.099164,0.615835,-0.174506,0.040312,0.334996,0.174019,-0.029140,0.145784,-0.065897,-0.577810,0.029422,0.480080,0.138391,-0.156372,0.276507,-0.849216,-0.053911,-0.310658,-0.423735,0.082635,-0.597359,-0.184158,-0.435700,0.162045,-0.172895,-0.358362,-0.064288,-0.005759,-0.071670,0.644161,-0.559090,0.363984,0.359863,0.113557,-0.128493,0.386397,-0.151523,0.253192,0.087340,0.387681,0.296314,-0.030501,0.488169,0.351645,0.352045,-0.089470,0.096726,-0.676012,0.592340', '2365260', '21619567', '1307146', '3431336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1858802', '黑皮书', '剧情', '二战末期，荷兰的犹太姑娘雷切尔（卡里斯·范·侯登 Carice van Houten 饰）和她家人刚刚逃过死神关口，来不及喘息又遭到德国军船的扫射，只幸存下雷切尔一人。躲避在暗处的雷切尔把叛徒的样子牢牢记在心上，她的一生都为寻找这个人而孤注一掷。她为了隐藏身份，当了一名歌手，然而阴差阳错竟让她开始了另一条人生道路。游击队队长让雷切尔混进德国阵营中，去搭救他被逮捕的儿子。于是，美丽的雷切尔成功俘获了德国军官的心。一切都好像进展顺利，但雷切尔的一个机密任务，却让她陷入了四面楚歌的境况。复仇的决心还在雷切尔心中熊熊燃烧，叛徒还在某个阴暗的角落……©豆瓣', '卡里斯·范·侯登', '保罗·范霍文', 8.4, 74539, 'tt0389557', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198811825.jpg', 0.2, 0.9, 13.8, 49.7, 35.4, '0.136847,0.166820,-0.766637,0.700557,-0.196577,-0.337084,0.692254,0.034197,-0.383041,-0.026265,0.473758,0.766424,-0.039015,0.043212,0.139179,0.213841,-0.400564,-0.759056,-0.068775,-0.152139,-0.258196,-0.260119,-0.413523,-0.404313,-0.092816,-0.229117,0.719326,0.431930,-0.165629,0.087892,0.301453,0.236050,-0.021054,0.671026,-0.207279,0.064239,0.253060,-0.395567,0.034136,0.099904,-0.082310,-0.485520,-0.349447,0.508803,-0.106734,0.551671,0.625190,-0.243396,0.107499,-0.033293,0.008750,-0.485818,0.110254,0.275062,0.244262,-0.117925,-0.102813,0.126789,-0.176935,0.114898,0.013015,0.123205,-0.821137,0.037042,0.019087,0.084415,-0.642147,0.356610,-0.293146,0.219334,0.213772,-0.289589,0.205534,0.249136,0.058578,0.253556,-0.395069,-0.080472,-0.696313,0.210961,0.651251,-0.157079,-0.286670,0.084179,-0.090974,-0.512441,-0.066865,-0.130161,-0.362644,-0.271744,0.530874,-0.052203,-0.276715,0.274382,-0.548368,0.201821,-0.593644,-0.207673,-0.379010,-0.602996,-0.166899,-0.310046,-0.082002,-0.030253,-0.372655,0.217802,-0.067463,-0.073852,0.702960,-0.500312,0.230055,0.805127,0.112106,-0.427833,0.512156,0.227145,0.194211,0.059722,-0.097658,0.246845,0.071117,0.495647,0.181570,0.284360,-0.197066,0.035526,-0.259908,0.380566', '30163500', '1306801', '25928048', '1867335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1858876', '小孩不笨2', '剧情', '中产家庭的汤姆和杰瑞兄弟生活条件优越，但是他们却有着诸多烦恼。爸爸（梁智强 饰）是某手机开发公司的职员，妈妈（向云 饰）是某著名杂志的编辑，夫妻俩整日忙于工作，根本无暇顾及孩子的感受。在这对父母的眼里，孩子们调皮捣蛋，一身的缺点，简直让他们操碎了心。汤姆的好朋友成才（洪赐健 饰）生于一个单亲家庭，父亲（黄奕良 饰）文化程度不高，年轻时打架还瘸了一条腿。他为了避免儿子重蹈覆辙，便采取粗暴的方式进行教育。家长如此，学校的老师也如出一辙。教授华文的符老师痛心学生们的学业，然而在教育过程中不得其法，与学生的关系越来越紧张。校长一味遵循校规行事，甚至公开体罚以达到的目的。学校、老师、家长，本该扮演呵护幼苗成长的角色，却成了揠苗助长和扼杀天性的凶手。当他们发现自己的错误时，孩子的心中已满是伤痕……©豆瓣', '梁智强', '梁智强', 8.3, 8737, 'tt0475179', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1617356989.jpg', 0.3, 1.4, 16.5, 45, 36.8, '0.147038,-0.440142,-0.196585,0.457161,-0.274687,-0.234264,0.323544,0.268210,-0.608461,-0.444737,0.250316,0.479884,-0.003004,0.309172,0.104328,-0.271614,-0.195627,-0.589909,0.004981,0.121180,-0.020131,-0.505618,0.081389,-0.259585,-0.244624,-0.342505,0.765780,-0.210281,-0.260953,0.366505,-0.004760,0.144296,0.086237,0.202485,-0.063665,-0.112591,0.009879,0.051586,-0.139383,-0.330131,0.220630,0.068511,-0.143252,-0.008125,0.224216,0.361796,0.762701,0.099249,-0.222208,-0.328282,0.565178,-0.126345,-0.183092,0.164143,0.350675,-0.086751,0.521334,0.265113,0.147681,0.082886,0.045323,-0.197643,-0.723106,-0.149202,0.227598,-0.045099,-0.420815,0.429411,-0.021632,-0.047911,0.085141,-0.350936,0.052340,0.087241,0.042314,0.612652,-0.440347,0.079432,-0.169159,0.185282,0.401239,-0.129296,-0.190721,0.302247,-0.655272,-0.344806,0.111518,-0.398174,-0.661931,0.014881,-0.104081,-0.073561,-0.436483,0.356281,-0.404895,0.026821,-0.068737,0.010671,0.127900,-0.567308,-0.131643,-0.383867,0.103846,-0.382682,-0.450032,-0.065855,0.112938,-0.349523,1.026036,-0.901263,-0.118506,0.335567,0.236116,-0.618201,0.867154,0.224367,0.287670,-0.297921,-0.347937,0.065408,-0.034676,0.182562,-0.120326,0.234302,0.153840,-0.255260,-0.061868,0.287352', '3445516', '6963575', '25922902', '25882279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1859036', '宝贝计划', '剧情', '故事围绕一个刚出生的宝宝开始。人字拖（成龙 饰）虽有不凡的身手，可是终日沉迷赌博毫无人生目标，便与包租公（许冠文 饰）、八达通（古天乐 饰）一起盗窃，干着偷偷摸摸的犯罪事。城中女富豪（余安安 饰）唯一的孙子出生后，包租公受不了金钱的诱惑，答应把宝宝偷给黑帮老大，以证明宝宝是否是自己死去的儿子与前女友的孩子。成功偷得孩子后，一连串发生的事情，使人字拖及八达通改变了自己的人生观念。人字拖开始关心家人，八达通也看到了自己老婆（蔡卓妍 饰）的不易，开始重新做人。 在包租公及黑势利的威胁下，他们还是要把偷来的BB交出来，到底又会发生些什么事，故事有会否大团圆结局呢？©豆瓣', '成龙', '陈木胜', 7.5, 403034, 'tt0485976', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p946770581.jpg', 0.4, 3.1, 34.5, 45.6, 16.4, '0.235714,-0.145652,-0.345377,0.205502,-0.185588,-0.141394,0.417460,0.022783,-0.576701,-0.167412,0.191441,0.660978,-0.183150,0.178669,-0.019038,0.302745,-0.257392,-0.630990,0.135897,0.038891,-0.208685,-0.313835,-0.004592,0.070443,-0.045038,-0.099833,0.365123,-0.109331,0.037099,0.205130,0.550995,0.016426,-0.115677,0.220725,-0.199248,0.215066,-0.246108,0.285301,-0.182592,0.065224,0.275052,-0.099360,-0.027105,0.120629,-0.001976,0.191335,0.689717,-0.304987,-0.201926,-0.178265,0.459127,-0.084186,-0.110694,0.254496,0.024928,0.066037,0.468303,0.348969,-0.087419,-0.002913,0.216407,0.234700,-0.512827,-0.182498,0.211269,0.079804,-0.588759,0.133963,-0.047784,-0.111487,0.484424,-0.377290,0.105838,0.260680,0.313734,0.441507,-0.304148,0.079610,-0.684159,0.287547,0.561577,-0.112645,0.003515,0.326740,0.042392,-0.247046,0.043459,-0.400401,-0.490477,0.161024,0.166441,0.078566,-0.346035,0.245244,-0.452641,-0.006249,-0.059392,-0.013963,0.016735,-0.458025,-0.198567,0.001043,-0.090133,-0.303455,-0.313956,0.091936,0.276210,-0.349185,0.677983,-0.535767,0.118731,0.439812,0.197235,-0.705732,0.469806,0.053952,0.249184,-0.291966,-0.181275,-0.126039,0.046126,0.011246,0.038259,0.180385,0.136388,-0.082335,-0.028557,0.267508', '1877596', '4301278', '1309033', '3179758');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1859845', '小叮当', '喜剧', '奇妙的精灵世界里居住着成千上万的小精灵，他们各司其职，装点广阔人间：风仙子为花儿传粉；花仙子为花草上色；水仙子给大地解冻；动物仙子唤醒冬眠的小动物……然而小叮当（梅·惠特曼 Mae Whitman 配音）却只是一名修理仙子，负责制造和修补一些工具，她天天渴望能像姐妹们一样到人间工作，装扮春天。于是，小叮当开始苦练姐妹们的能力，希望改变自己的职能。然而冒冒失失的她虽然学习刻苦，但也闯祸不断，甚至在学习风仙子的技能时不慎破坏了春天的准备进程。懊恼悔恨之时，她却意外发现了自己发明创造的天赋，小叮当决定将功补过，努力发明提高工作速率的工具，让人间的春天及时降临……本片为迪士尼公司制作的《奇妙仙子》系列作品中的第一部。©豆瓣', '梅·惠特曼', '布拉德利·雷蒙德', 8.2, 15255, 'tt0823671', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2501660759.jpg', 0.2, 1.1, 20.2, 47.2, 31.3, '-0.000300,0.352590,-0.401692,0.715029,-0.065035,-0.063966,0.446348,-0.081819,-0.314084,-0.299788,-0.026926,0.420893,-0.152398,0.369613,0.001525,0.110248,-0.361776,-0.515090,0.011102,0.074272,-0.228821,0.138543,-0.385110,-0.322508,-0.189345,-0.614116,0.616067,0.116617,-0.113653,0.344217,-0.367651,-0.320774,-0.275950,0.450217,-0.049655,-0.154930,-0.056179,0.191138,-0.229236,0.272877,-0.113483,0.072763,-0.179119,-0.046757,0.182835,0.420253,0.702395,-0.519510,-0.308220,-0.318852,0.472187,-0.111562,0.412800,0.087667,0.145746,0.093840,0.276396,-0.376748,-0.110386,0.253088,-0.032362,-0.592995,-0.677041,-0.072022,0.316435,-0.059468,-0.407082,0.098083,0.121213,0.324831,0.127460,-0.410621,0.118280,-0.046362,0.447216,0.659494,-0.348817,-0.102040,-0.375243,0.540913,0.519635,-0.093335,-0.364570,0.674645,-0.443774,-0.367569,-0.035581,-0.184950,-0.341350,-0.222918,0.166486,0.219402,-0.033458,0.208657,-0.736713,0.090641,-0.071251,0.071144,-0.451075,-0.531787,-0.029560,-0.510614,0.258507,-0.243617,-0.212852,0.016738,0.472110,-0.507385,0.860018,-0.822967,0.300381,0.572794,0.077699,-0.407416,0.472316,-0.376458,0.042924,-0.137294,-0.359702,0.230195,-0.225149,0.357225,0.009102,0.480720,-0.066985,-0.025211,-0.370970,0.239196', '10174444', '3811356', '2053515', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1860453', '海贼王剧场版7：机关城的机械巨兵', '喜剧', '正是狂风暴雨时节，路飞、娜美、索隆等人登上一艘行将沉没的海盗船，并发现一个巨大的藏宝箱。众人费了九牛二虎之力，终于将箱子带回梅利号。结果发现，箱子里没有任何金银财宝，而是一个长相怪异且有些脱线的老太婆。老太婆唯恐路飞他们杀掉自己，于是许诺愿用金冠的秘密交换的生命。所谓金冠，传说是一顶价值连城的王冠，只有真正的海之王才能拥有。路飞相信了老太婆的话，于是扬帆朝目标之地挺进。众人来至老太婆所住的机械岛，然而老太婆的儿子兰切特以为路飞等人是劫持了自己母亲的盗贼。他一面救回母亲，一面利用其研制的机械巨兵向梅利号展开攻击。寻找金冠的道路上危机重重……©豆瓣', '田中真弓', '宇田钢之助', 7.7, 10886, 'tt1059950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2300511653.jpg', 0.5, 2.7, 29.8, 42.8, 24.1, '-0.133718,-0.086289,-0.501307,0.531527,-0.118448,-0.226328,0.775552,-0.036806,-0.348786,-0.178235,0.387825,0.519233,0.153967,-0.054377,0.169318,0.408719,-0.351333,-0.280896,0.069375,-0.212096,-0.541019,-0.347742,-0.129322,-0.190385,0.113736,-0.342229,0.548949,0.079904,-0.099859,0.148569,0.246306,0.134106,-0.150901,0.512995,-0.276460,-0.029312,-0.104368,-0.296412,-0.008893,0.276058,-0.406098,-0.027742,-0.152203,0.357522,-0.245118,0.359272,0.856940,-0.620740,0.027189,-0.229165,0.041946,-0.285138,0.082413,-0.112988,0.035690,-0.205508,-0.067129,-0.139606,-0.167831,-0.132618,0.399355,-0.190945,-0.407231,0.090664,-0.073256,-0.030159,-0.420438,0.137831,-0.088555,0.200267,0.115598,-0.363737,0.311316,-0.083110,0.146115,0.175704,-0.155181,0.067820,-0.560630,0.007175,0.229365,-0.130323,-0.114824,0.486888,0.267971,-0.376929,-0.187314,-0.194914,-0.267289,-0.085878,0.618627,0.260987,-0.129047,-0.185730,-0.631955,-0.055245,-0.651049,-0.149374,0.264030,-0.375902,-0.332126,-0.323004,0.306791,-0.079217,-0.186863,0.229877,-0.097939,-0.165428,0.654978,-0.247594,0.117795,0.546218,0.010317,-0.339972,0.529866,-0.396870,-0.002288,-0.284053,-0.121556,0.158350,0.302883,0.275041,0.055979,0.101909,-0.009637,-0.148598,-0.234221,0.373554', '21619567', '1467779', '1856675', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1860582', '三眼神童', '动画', '头上贴着胶布、无论从外形还是性格来看都像小孩子的写乐保介却天资聪颖，以第一名的成绩跳级进入高中。写乐平时天真开朗，然胶布下却掩藏着第三只眼的秘密。原来他是古老的三眼族的遗孤，十几年前三眼族神秘灭亡，写乐被族人托付给养父犬特医生。童年时的写乐脾气暴虐，令人困扰。犬特发现，只有用胶布将第三只眼封上才可使写乐安静下来。而一旦胶布被撕开，古老文明的灵魂将再次回归。如同被命运引领一般，写乐和朋友们经历了一次次神秘而刺激的大冒险……根据手冢治虫同名漫画改编。©豆瓣', '岸野一彦', '芹川有吾', 8.4, 12013, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554491718.jpg', 0.3, 1, 18.8, 40.4, 39.5, '0.140998,0.242626,-0.160567,0.483669,-0.174074,-0.062991,0.666200,-0.040052,-0.408186,-0.167126,0.003060,0.585509,-0.246693,0.272777,-0.106982,0.203839,0.065246,-0.707733,-0.085596,-0.231484,-0.252229,-0.131400,-0.357755,0.288304,0.049263,-0.649776,0.621877,0.003975,-0.371290,0.246789,0.240132,0.624554,-0.321175,0.095419,-0.241354,-0.303909,-0.358016,0.165017,0.242151,-0.040194,-0.179984,-0.118000,0.046233,0.259309,-0.185424,0.235028,0.767874,-0.510674,-0.281928,-0.469818,0.322018,-0.251878,-0.394845,0.283973,0.629432,0.519854,0.314871,0.306391,0.055899,0.087935,0.051553,-0.160700,-0.557619,-0.035165,0.180335,0.085427,-0.454969,0.178820,0.074975,-0.112441,0.038560,-0.414488,0.309366,0.190261,0.372860,0.577390,-0.157239,0.288052,-0.053798,-0.009888,0.545833,-0.056710,-0.408320,0.169643,-0.144616,-0.482305,0.006362,-0.548350,-0.357860,0.259209,0.222712,0.310366,-0.219769,0.451442,-0.782620,-0.084236,-0.205471,0.045226,0.097273,-0.563048,-0.176412,-0.325736,-0.396350,-0.200551,-0.220093,0.027803,-0.003245,-0.368813,0.967920,-0.567706,0.328347,0.206167,0.174652,-0.184547,0.513303,-0.001779,-0.056566,0.088837,0.120182,0.321502,0.332489,0.195116,-0.012473,0.296636,-0.150788,-0.214364,-0.404499,0.821715', '1302661', '4181031', '1307146', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1860745', '仙境之桥', '剧情', '杰西（乔什·哈切森 Josh Hutcherson 饰）是个过得不怎么快乐的孩子。他在学校里受同学欺负，在家中又无法得到父母的宠爱。只有两个人能为他的童年带来亮光——一个是音乐老师，另一个便是刚转校来到班上的莱斯利（安娜索菲亚·罗伯 Annasophia Robb 饰）。莱斯利以她独特的方式感染了生活暗淡的杰西，慢慢打开了他的生活的另一扇窗。在河的另一边，他们要建造一个叫做“特雷比西亚”的王国，他们在树上打造一个屋子，王国的成员有妖怪、马蜂军团、松鼠和秃鹰。这个幻想的天地创造了他们每天放学后最好的时光。然而，童话毕竟太虚幻，杰西和莱斯利的特雷比西亚世界，迎来了风雨飘摇的一天……©豆瓣', '乔什·哈切森', '嘉柏·丘波', 7.9, 71911, 'tt0398808', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p713363828.jpg', 0.4, 2.8, 25.4, 44.5, 26.8, '0.513151,-0.043676,-0.528464,0.748035,-0.204600,-0.263140,1.051731,0.254711,-0.442759,-0.280983,0.181708,0.816841,0.026488,0.585370,0.294696,0.188752,-0.500709,-0.529986,0.043353,-0.290443,-0.388849,-0.160293,-0.205132,-0.445219,-0.040642,-0.434740,0.687183,-0.208182,0.215132,0.350045,0.087132,0.300082,0.122070,0.240885,-0.443078,0.228662,0.159501,0.067732,-0.108945,0.323315,-0.283413,0.044091,-0.251327,0.251118,-0.047427,0.160590,0.593679,-0.330853,0.001666,-0.234027,0.258740,-0.273211,-0.111140,-0.052452,0.455689,-0.235828,0.374191,0.086718,-0.241056,0.064403,0.016095,-0.272175,-0.798783,-0.088340,0.099267,0.337795,-0.521869,0.589364,0.089238,-0.384579,0.198510,-0.294345,0.130953,0.428892,0.107964,0.577862,-0.190975,0.011372,-0.670962,0.046970,0.569662,-0.245947,-0.321509,0.521530,-0.412489,-0.321986,0.040335,-0.079272,-0.642223,-0.104382,0.418181,-0.204234,-0.086112,0.187073,-0.889750,0.125151,-0.224642,-0.340213,-0.068678,-0.635701,-0.292973,-0.372841,0.108088,-0.376650,-0.357173,0.291955,-0.023684,-0.109750,0.756901,-1.089904,0.324478,0.525530,0.237565,-0.131188,0.750814,-0.020918,0.027821,-0.277520,0.137817,0.238151,0.011696,0.337078,0.068379,0.593142,0.130745,-0.040636,-0.518759,0.764037', '1292062', '3055049', '30401849', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1861411', '好奇害死猫', '剧情', '重庆的一所高档公寓里，聚集着各式各样的人，他们窥视对方的生活，也被对方所窥视。“好奇”在他们之中蔓延着，在他们所不知道的时刻，在他们看不见触不到的阴暗角落，正在逐渐地膨胀，把他们引去了未知的方向……　　洗相店的小妹（林园饰），因为时常为公寓里有钱的住户送洗好的相片，能够有机会看到有钱人的生活状态。但她真正在意的却是住在车库里的一个小保安（廖凡饰）。与她相反，她暗恋的那个小保安却对有钱人的生活十分好奇并且向往。一天公寓楼下搬来了一个年轻漂亮的女人梁晓霞（小宋佳饰），她开了间美甲店。她的到来引起了小妹的注意。小妹很快发现，原来她和公寓的住户郑先生（胡军饰）有染，而出生大户人家的郑太太（刘嘉玲饰）似乎并不知情，她的生活重心都放在儿子和种植玫瑰花上。表面上看郑家三口的生活十分平静。出身贫寒的郑先生因为与郑太太婚姻找到了通往财富捷径，但他并不满足这种平静现状和寄人篱下的生活，因结识梁小霞而感情生活出轨。在此之后，一些诡异可怕的事情连续在郑家发生，使郑家人的生活陷入不安与惶恐。郑先生怀疑这一切都是梁晓霞所为，而倔强的梁晓霞也并不否认，并借这些诡异事件逼迫郑先生和她在一起。梁晓霞的紧紧相逼让郑先生无所适从......', '刘嘉玲', '张一白', 6.4, 32551, 'tt0805513', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2372011888.jpg', 2.2, 12.9, 53.7, 25.6, 5.7, '0.570391,0.024219,-0.782703,0.574923,-0.326441,-0.108998,1.188795,0.142871,-0.673769,-0.378288,0.168233,0.733882,-0.091549,0.421111,-0.069829,0.186812,-0.185128,-0.479076,-0.101970,-0.168350,-0.268352,-0.351923,-0.262553,-0.371421,-0.119310,0.042092,0.459571,0.316979,-0.234089,0.397771,0.130555,0.060753,-0.086973,0.809394,-0.297997,-0.060423,-0.244260,0.161291,-0.124704,-0.085474,0.040849,-0.373462,-0.153827,0.214198,0.176857,0.407088,0.675977,-0.238463,-0.381141,0.091599,0.143039,-0.134945,-0.104217,0.317671,0.271986,-0.058165,0.087849,-0.045038,-0.353175,0.035083,0.052825,0.054834,-0.738686,0.084258,0.139486,0.253373,-0.651744,0.660374,0.086469,-0.312837,-0.063290,-0.449434,0.312122,0.358008,0.045347,0.232534,-0.355593,0.028415,-0.604447,0.019482,0.778908,0.044693,-0.160367,0.492865,-0.542436,-0.439246,-0.060023,-0.143469,-0.786432,-0.178807,0.097958,0.231628,-0.183541,0.192057,-0.537639,0.188939,0.111854,-0.155630,-0.143072,-0.726681,-0.139158,-0.478860,-0.278138,-0.675827,-0.413730,0.062024,-0.001349,-0.395278,0.531684,-0.933579,0.112554,0.502872,0.548872,-0.594940,0.890071,0.018124,0.040013,-0.096721,-0.522749,0.203081,0.020210,0.471223,0.143944,0.430380,-0.221831,-0.049116,-0.322889,0.609604', '1296370', '1308755', '1307561', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1861935', '从心开始', '剧情', '查理(亚当·桑德勒 Adam Sandler饰)是一个9•11的直接受害者，他的妻儿和爱狗都在这场灾难中丧生。查理从此一蹶不振，严重的自闭抑郁。他已经习惯了每天踩着电动滑车，戴着大耳机在街头行尸走肉般游荡，心灵巨大的创伤让他回归不了正常的生活。艾伦（唐·钱德尔 Don Cheadle 饰）则是一个表面看来非常幸福的男人，有成功的事业和美满的家庭，然而他承受的生活压力是常人无法理解的，他的内心在暗暗苦撑。直到有一天，艾伦在街头遇上了查理。得知这个老同学为何变得如此颓唐后，艾伦心里便下定决心也帮他一把，让他从低谷中走出来。他们一起谈心，游戏，慢慢的发现彼此的心灵都从窒息中苏醒过来。©豆瓣', '亚当·桑德勒', '麦克·宾德尔', 7.8, 17856, 'tt0490204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p543896015.jpg', 0.4, 2.4, 25.7, 49.5, 22, '-0.051625,0.185312,-0.868040,0.502061,-0.362814,-0.280714,0.975594,0.127663,-0.494269,0.114013,0.235708,0.897479,-0.166490,0.434973,0.147521,-0.007623,-0.303611,-0.752951,-0.026184,0.008732,-0.337848,-0.288217,-0.293243,-0.247359,-0.297180,-0.222093,0.511799,0.210157,-0.023456,0.575812,0.101105,0.265233,0.184717,0.693647,-0.265039,0.103719,-0.207530,0.106834,-0.110893,-0.060815,0.362587,-0.168645,0.013554,0.413557,-0.085672,0.156662,0.681796,-0.244987,-0.259506,0.149596,0.422879,-0.307998,-0.241218,0.204332,0.243770,0.074431,-0.062268,-0.121891,-0.296206,0.183678,0.107711,0.195469,-0.794451,-0.113473,-0.166173,0.288210,-0.633641,0.611828,0.022662,-0.122620,0.077989,-0.297653,0.189151,0.360598,0.378804,0.484182,-0.440954,0.127882,-0.597847,0.095881,0.867747,0.022679,-0.443534,0.403406,-0.512514,-0.348854,-0.079610,-0.173147,-0.717346,-0.373826,0.347988,0.124126,-0.604633,0.340879,-0.370651,0.255160,-0.201207,-0.212289,-0.270468,-0.471424,-0.052407,-0.438159,-0.362884,-0.652280,-0.192604,0.129962,0.011105,-0.416707,0.650647,-0.684153,0.439362,0.617003,0.274359,-0.204427,0.656428,0.108584,0.166658,0.006263,0.068775,0.480445,-0.121757,0.314627,0.318432,0.451403,-0.097997,0.290160,-0.476780,0.830253', '25763555', '4275444', '30162520', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1862151', '疯狂的石头', '喜剧', '重庆一间工艺品厂已经濒临倒闭，却不料在拆倒旧厂房的时候，发现了厕所里的一件宝物——一块价值连城的翡翠。厂里决定用这块翡翠举办一个展览，赚些钱发拖欠了几个月的工人工资。期间由工艺品厂保卫科长包世宏（郭涛 饰）负责看守这件宝物。但是，国际大盗麦克与本地一帮小偷却让包世宏一筹莫展，他们各施其技接近翡翠，展览馆开始了一场明争暗斗的较量。黑色幽默也开始幕幕上演。翡翠的价值几何？最后谁是胜出者？事情远没有表面那么简单……©豆瓣', '郭涛', '宁浩', 8.5, 762086, 'tt0843270', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p712241453.jpg', 0.2, 1, 12.3, 44, 42.4, '0.137582,0.091975,-0.690002,0.124498,-0.192242,-0.028318,0.632184,0.082931,-0.456452,-0.254632,0.303547,0.478895,-0.315021,-0.159174,-0.156020,0.201241,-0.123596,-0.419133,0.267223,-0.488596,-0.036458,-0.358736,-0.435889,-0.081255,-0.255985,0.369312,0.479028,0.525108,0.049143,0.410447,0.237333,-0.097753,0.127845,0.191181,0.179311,-0.415954,0.368763,0.197177,-0.191690,0.094203,-0.104665,-0.052946,-0.155531,-0.033545,0.343277,0.420249,0.390745,-0.051879,-0.050808,0.298591,0.296726,-0.193888,-0.056287,0.043109,0.500404,0.162591,0.161312,0.028734,-0.601392,-0.134519,0.392081,-0.124202,-0.523343,0.059165,0.163998,0.087923,-0.565816,0.517225,-0.041618,0.358524,-0.303561,-0.213836,0.379887,0.375926,0.338720,0.303501,0.008786,-0.380003,-0.751291,0.370135,0.546061,-0.172804,0.141344,0.363234,0.222568,-0.411775,-0.133938,-0.321545,-0.038590,-0.056365,0.356695,-0.162739,0.093094,-0.438532,-0.850694,0.166565,-0.120161,-0.171135,0.068300,-0.156951,-0.076978,-0.602956,0.032249,-0.182035,-0.255995,0.075090,0.211819,-0.136942,0.565316,-0.429413,-0.198742,0.335236,0.198382,-0.468231,0.479768,-0.198399,0.269826,-0.078212,-0.331096,-0.539691,0.117855,0.441045,0.005738,0.450119,0.336768,-0.443238,-0.255740,0.238124', '1309101', '1293515', '26290398', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1862397', '人体雕像', '剧情', '本片用风格化的手法展现了匈牙利三代人的怪诞故事。丑陋的士兵马洛戈瓦尼（Csaba Czene 饰）每日在长官的责骂中进行机械精确的繁琐工作，他那被压抑的生命只能通过炙烤自己身体和偷窥时自渎来缓解，某夜他将猪的尸体看做肥硕的女人，一夜癫狂之后被长官枪杀；大胃王比赛的选手巴拉托尼（Gergely Trócsányi 饰）承担在社会主义国家比赛中为国争光的重任，他呕出的比赛用食品却是国民平日所无福消受的美食；巴拉托尼与一名女子竞吃选手体格消瘦异常的儿子靠制作动物标本为生，儿子不堪照顾肥硕臃肿的父亲，致使巴拉托尼身亡，儿子回到家里，将父亲和自己做成了标本……本片获2006年特兰西瓦尼亚国际电影节最佳导演奖等多项褒奖。©豆瓣', '查巴·策勒', '乔治·巴勒菲', 8, 9855, 'tt0410730', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1079218159.jpg', 1.4, 3.4, 20.4, 44, 30.9, '-0.107926,-0.096652,-0.354739,0.449670,-0.155202,-0.248963,0.641028,0.236743,-0.578906,-0.045787,0.438397,0.596119,-0.181088,-0.053453,0.073394,-0.183392,-0.241614,-0.666557,-0.316091,0.219525,-0.295970,-0.172028,-0.177773,-0.344411,-0.157587,-0.573634,0.651303,-0.289439,-0.200339,0.209156,0.165405,0.161986,0.224874,0.154377,-0.111416,-0.101821,-0.006501,-0.104825,-0.046301,0.110225,0.179745,-0.321385,-0.079629,0.065764,-0.005209,0.316632,0.857743,-0.289587,-0.064845,-0.414895,0.438001,-0.257248,0.019689,0.305786,0.078806,-0.047566,0.195464,0.066302,-0.168972,0.067147,0.244020,-0.170310,-0.711983,-0.214217,-0.013657,0.019262,-0.624225,0.594387,-0.294994,0.267790,0.135352,-0.323071,0.275368,0.141229,0.107800,0.544020,-0.026960,0.102836,-0.353441,0.531118,0.190004,-0.115393,-0.338100,0.068002,-0.354786,-0.628420,0.089023,-0.616629,-0.303037,-0.135148,0.218839,-0.036913,-0.168410,0.293814,-0.616448,-0.160341,-0.149256,-0.417327,-0.007753,-0.213400,-0.204509,-0.530047,0.043603,-0.211195,-0.019940,-0.099049,0.181793,-0.164351,0.765185,-0.443864,0.105790,0.475453,0.063544,-0.105994,0.440260,-0.280756,0.295158,-0.163818,-0.345196,0.171047,0.165331,0.119825,0.321739,0.523872,-0.094984,0.080218,-0.417426,0.645488', '10467125', '3811356', '27602116', '1294434');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1863384', '无夜不漫长', '剧情', '蒂姆·康沃尔（李·威廉姆斯 Lee Williams饰），拥有一张天使面孔的英俊少年。伊沃·斯蒂德曼（马克·沃伦 Marc Warren饰），长相冷酷脾气暴躁的硬朗男孩。于万千宠爱一身的蒂姆，在大学时期备受众人喜爱。在一次有名的创意写作课程上蒂姆邂逅了伊沃。蒂姆的魅力让伊沃无法自拔，深深为之着迷。终于，伊沃还是表明了心迹。两人相爱。然而在一次旅行中，蒂姆邂逅了一名叫伊莎贝尔·温伍德（麦凯拉·米卡埃尔Mikela J. Mikael饰）的女子，此刻他才发现自己根本不爱伊沃。在看似无辜的外表下，蒂姆离开了伊沃。而深爱蒂姆的伊沃，不惜一切代价地挽留着他。就在这次旅行结束的时候，一切都发生了改变。本片根据犯罪小说家Barbara Vine的同名小说改编而成。©豆瓣', '李·威廉姆斯', '汤姆·森兰', 7.7, 6128, 'tt0313410', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1263500514.jpg', 0.6, 3.1, 28.3, 47.3, 20.7, '0.114194,0.249442,-0.766025,0.709242,-0.193577,-0.761058,0.864353,0.141725,-0.204964,-0.260436,0.072993,0.743534,-0.432234,0.202056,0.513403,0.116237,-0.294036,-0.680125,-0.183369,-0.105745,-0.101610,-0.509182,-0.255423,-0.111015,-0.009990,-0.640510,0.418315,0.092503,-0.131387,0.359124,0.424987,0.264251,0.177087,0.338533,0.001652,-0.049125,0.212007,-0.238399,-0.116816,0.120737,0.209745,-0.301387,-0.305985,0.291523,-0.232931,0.134735,0.847678,-0.394654,-0.168278,0.078712,0.579231,-0.022676,0.000392,0.031298,0.089054,-0.260613,0.012551,0.076276,-0.060344,0.011901,0.144317,-0.252754,-0.512884,-0.080897,0.022236,0.281949,-0.539651,0.598637,-0.368283,-0.004265,0.036395,-0.594317,-0.129167,-0.086719,0.414410,0.387377,0.104605,0.080860,-0.297579,0.103365,0.444521,0.505151,-0.487976,0.276683,-0.541043,-0.459972,-0.099802,-0.229452,-0.726655,0.259084,0.453314,-0.285354,0.104549,0.402270,-0.474687,-0.084558,-0.428194,-0.045775,-0.152549,-0.235998,-0.188370,-0.678792,-0.304201,-0.465594,-0.211197,-0.020566,-0.048255,-0.216752,0.706237,-0.670666,0.293238,0.556764,-0.076608,-0.043830,0.539635,0.103630,0.027629,-0.143665,-0.082271,0.647792,0.113591,-0.085019,0.025450,0.468666,-0.040620,-0.002468,-0.438376,0.764674', '6827727', '1296992', '26677495', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1863766', '魔发奇缘', '喜剧', '女巫Gothel（唐纳·墨菲 Donna Murphy 配音）靠着一朵神奇的金色花朵保持青春。王后重病，国王派人找到了这朵金花给王后治病，王后病愈，生下了一个一头金发的小女孩Rapunzel（曼迪·摩尔 Mandy Moore 配音）。女巫失去金花，却发现小公主的金发有 着同样的魔力，因此她偷走Rapunzel，把她关到森林中的一座没有楼梯高塔之上。十八年后，Rapunzel在女巫的抚养下长成一个拥有长长金发的美人，她越发渴望外面的世界，女巫为了自己青春永驻，想方设法把Rapunzel留在身边。一天，窃贼Flynn（扎克瑞·莱维 Zachary Levi 配音）盗取公主王冠后逃入森林，在好奇心趋势下登上了这座神秘的高塔，误打误撞见到了塔中的长发公主。在Flynn的陪伴下，Rapunzel走下高塔，开始了人生和爱情的大冒险。本片为迪斯尼公司第50部动画长片，改编自经典格林童话《长发公主》，由迪士尼元老级画师格兰·基恩首次担任动画片导演。', '曼迪·摩尔', '内森·格雷诺', 8.3, 249535, 'tt0398286', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p707509468.jpg', 0.1, 0.8, 17, 48.4, 33.7, '-0.098609,0.495276,-0.577571,0.840289,-0.060371,-0.319240,0.917166,0.144573,-0.247386,-0.112713,0.398197,0.595244,-0.249355,0.348717,0.262348,0.313666,-0.546242,-0.286170,-0.166088,-0.182287,-0.352411,-0.141800,-0.374033,0.102089,-0.046633,-0.624882,0.939556,-0.039299,0.115800,0.167434,0.249669,0.079467,0.022043,-0.081194,-0.358721,0.161166,0.273761,-0.122425,0.119712,0.631007,-0.155757,-0.184196,0.069238,0.010963,-0.246037,-0.146411,0.768534,-0.708465,0.324962,-0.422525,0.557475,-0.054026,0.090316,0.004589,0.341817,-0.129287,0.120906,-0.011590,-0.382680,-0.099968,0.214042,-0.472116,-0.422918,0.130286,0.052078,0.398900,-0.709935,0.134917,-0.026801,-0.075382,0.433209,-0.542884,0.120150,-0.026061,0.288690,0.179638,-0.160413,0.260608,-0.571332,0.302769,0.425962,0.123821,-0.268812,0.121693,-0.224835,-0.231023,0.077520,-0.158602,-0.434020,-0.114543,0.411416,-0.222717,0.127342,0.021492,-0.517277,-0.123254,-0.563656,-0.213489,0.047247,-0.423059,-0.264833,-0.342553,-0.139730,-0.091633,-0.046101,-0.094075,0.135612,-0.184773,0.579501,-0.616935,0.515288,0.538433,0.179058,-0.120885,0.656295,-0.151608,0.171572,-0.138940,-0.114509,0.431889,-0.087971,0.382684,-0.009034,0.343660,-0.267885,-0.133531,-0.684617,0.288495', '1467779', '21619567', '5938000', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1863770', '拜见罗宾逊一家', '喜剧', '刘易斯是一个非常有才华的小发明家，他发明了一部“记忆扫描仪”，通过它可以扫描你的记忆。刘易斯希望通过这部机器找回自己未曾谋面的家人。岂料这部机器却被盗窃了，更神奇的是，一名来自的未来的男孩将刘易斯带到了未来。在这里，刘易斯见到了超级古怪的一家人——罗宾逊一家，在他们那里刘易斯得知自己的发明无意中穿越了时空，来到了未来。在罗宾森一家的帮助下，刘易斯发现一系列惊险的秘密，有关未来和他自己身世的秘密！©豆瓣', '安吉拉·贝塞特', 'Stephen J. Anderson', 7.7, 12363, 'tt0396555', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456795724.jpg', 0.5, 2.9, 30.7, 44.4, 21.5, '0.368376,0.175618,-0.662928,0.704923,-0.366427,-0.104796,0.718473,-0.266411,-0.659886,-0.468508,0.167091,1.045972,-0.075382,0.321095,-0.120405,0.254873,-0.346191,-0.497739,0.014137,-0.346325,-0.381846,-0.610480,-0.795575,-0.161032,-0.086670,-0.488018,0.676335,0.037093,-0.442763,0.037155,0.077735,0.209658,-0.152252,0.354253,-0.558163,0.332335,0.318770,0.029209,-0.321527,0.422894,0.085114,-0.380336,-0.014099,0.360677,-0.249724,0.273817,0.550951,-0.216014,-0.338419,0.123386,0.403613,-0.092424,-0.081341,-0.025591,0.181274,0.041265,0.062738,0.181574,-0.378930,-0.039149,-0.004654,-0.047742,-1.133537,-0.253800,0.086032,0.218290,-0.670702,0.103899,-0.208001,-0.005696,0.074702,-0.402389,0.473270,0.392671,0.363019,0.302002,-0.343458,0.118836,-0.530590,0.175970,0.709884,-0.316225,-0.169410,0.578133,-0.064928,-0.367540,-0.054680,0.015779,-0.641726,0.218593,0.660587,0.217828,-0.216744,0.293749,-0.592155,0.140668,-0.220661,-0.158646,0.009012,-0.385947,-0.062242,-0.601989,-0.331741,-0.512224,-0.253284,-0.140419,-0.006924,-0.656178,0.910487,-0.916677,0.221054,0.505518,0.224098,-0.313180,0.853393,-0.042600,0.211162,-0.470071,-0.025472,0.095381,0.157930,0.262551,-0.027687,0.548756,0.267046,-0.299227,-0.634255,0.741702', '1793491', '1783461', '25928048', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1863955', '另一个波琳家的女孩', '剧情', '玛丽•波琳（斯嘉丽•约翰逊 饰）与姐姐安妮（娜塔丽•波特曼 饰）美丽动人，如此优点却遭到了父亲与叔叔加以利用。为了提升自己家族的地位与权利，玛丽的父亲要把玛丽送进皇宫当中，成为了当时国王亨利八世（艾瑞克•巴纳 饰）的情妇。玛丽后来怀上了国王的孩子，但她的姐姐安妮也在这个时候进入皇宫，她要勾引国王以得到宠爱。原来安妮早已对进入皇宫密谋已久，为的是得到国王的宠爱以得到皇后的位置，全然不顾自己妹妹玛丽早已对国王产生了真感情。于是，同是波琳家族的一对姐妹为了各自的爱情与利益在皇宫中明争暗斗。姐妹俩争斗过后得到的结果到底如何？©豆瓣', '娜塔莉·波特曼', '贾斯汀·查德维克', 7.1, 96525, 'tt0467200', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p597623489.jpg', 0.5, 4.8, 45.6, 38.4, 10.6, '0.005760,0.390404,-0.598917,0.717872,-0.029733,-0.420447,0.644870,0.156810,-0.640026,-0.322762,0.435211,0.775698,-0.214702,0.056756,0.276376,0.411848,-0.525456,-0.598961,0.175997,-0.326402,0.035470,-0.541868,-0.219811,-0.173062,-0.171320,-0.467842,0.661507,-0.355578,0.062404,0.116598,0.266249,0.372553,-0.034092,0.390070,0.025324,0.173366,0.234199,0.030375,-0.647016,0.280640,0.324638,-0.055948,-0.269564,0.270460,0.114711,0.010266,0.461338,-0.675491,0.126089,-0.377019,0.315420,-0.064268,0.109594,0.309989,0.255310,-0.385659,0.425465,0.500110,-0.103488,-0.122425,0.129284,-0.133686,-0.612903,-0.002807,0.341706,-0.091199,-0.554829,0.283164,-0.422198,-0.301373,0.314516,-0.349647,0.254776,0.648326,0.068915,0.444370,-0.541748,0.024098,-0.669797,-0.219568,0.670061,-0.132719,0.040959,0.164508,-0.102973,-0.423342,0.166459,-0.439647,-0.573345,0.000706,0.201985,0.171843,0.173782,0.507234,-0.481955,-0.301441,-0.470383,-0.050797,0.625894,-0.725710,0.054042,-0.252654,-0.302244,-0.354979,-0.284054,-0.229293,0.096565,-0.346036,0.686330,-0.989544,0.287572,0.325967,0.464326,-0.948861,0.571867,0.105742,0.308583,-0.343589,-0.486353,0.170410,-0.020159,-0.073779,0.026235,0.003271,0.068149,-0.215010,-0.354560,0.198210', '30345227', '1949320', '1293265', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1864199', '暗物质', '剧情', '物理专业研究生刘星（刘烨 饰）远赴美国某州立大学深造，在校期间，他师从著名教授雅各布•瑞瑟（Aidan Quinn 饰）。他的勤奋和出众才华很快在同侪中脱颖而出，并深得瑞瑟教授的信任和赏识。在众多课题中，刘星独对暗物质倾心着迷，他将自己投入到这项研究中，却未料到他所得出的理论与导师经典的瑞瑟模式相冲突。刘星关于暗物质的论文博得一片好评，然而醉心研究的他忽略了校园政治的存在，他的答辩未获通过。极度抑郁和愤慨之下，他走上了一条不归路……本片根据卢刚事件改编，并荣获2007年圣丹斯电影节阿尔弗莱德•斯隆奖和2007年亚美电影节最佳故事影片奖。©豆瓣', '刘烨', '陈士争', 6.8, 7220, 'tt0416675', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2577437832.jpg', 1.4, 10, 46.2, 31.8, 10.6, '0.276780,0.075938,-0.707591,0.809389,0.213960,-0.227420,0.466798,-0.255821,-0.556827,-0.226420,0.015551,0.626361,-0.387899,0.189087,0.282575,-0.278759,-0.443194,-0.709956,-0.083498,-0.185011,-0.099006,-0.725441,-0.586965,0.056044,-0.337194,-0.459021,0.752556,0.054025,-0.419650,0.812236,0.062867,0.248697,-0.009659,0.331119,0.094378,0.036892,0.412034,0.165927,-0.274066,0.025316,0.294974,-0.318746,-0.547457,0.033296,0.086901,0.245575,0.496197,-0.256435,-0.252925,0.121061,0.608941,-0.441224,-0.145498,0.054927,0.270969,0.139997,0.149663,0.520093,-0.027386,0.245896,-0.165004,-0.160726,-0.672619,-0.328097,0.111353,0.186678,-0.345108,0.556749,-0.151458,-0.148303,-0.036882,-0.309610,-0.317183,-0.105295,0.174246,0.376081,-0.105865,0.133558,-0.206040,0.638584,0.333761,-0.000171,-0.521046,0.192558,-0.142808,-0.634794,-0.075792,-0.299224,-0.254902,0.022025,0.436258,0.071850,0.100714,0.158379,-0.414139,0.044185,-0.085051,-0.139145,-0.056240,-0.185869,-0.097237,-0.780838,-0.074678,-0.355631,-0.416309,-0.327334,0.016202,-0.583915,0.913297,-0.758634,0.071646,0.254483,0.089871,-0.327022,0.773265,-0.002214,0.170961,-0.229750,-0.518042,0.154968,-0.166722,0.251301,-0.052473,0.552360,0.271975,-0.371995,-0.540484,0.424666', '27602116', '25880986', '3811356', '2338019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1864290', '我要成名', '剧情', '潘家辉（刘青云饰）其实也走红过，他曾经是十几年前电影金像奖最佳新人奖得主。然而世事变幻，加上他性格锋利，在圈内的发展每况愈下。失意落魄之时，竟有新人吴晓菲（霍思燕饰）当他是无敌尊师，还拜师学艺。吴晓菲纵然受尽新人的委屈，演戏亦任劳任怨，感动得潘家辉终于收之为徒弟，成为其经纪人。师徒日夕相对，感情渐厚。吴晓菲慢慢成长的演技，为她带来的第一部戏却是三级片，还要远赴日本。她的事业将走向何方，和潘家辉搁浅的感情又该怎么办。最后成名的是潘家辉，还是吴晓菲，是皆大欢喜，抑或是两败俱伤？©豆瓣', '刘青云', '刘国昌', 6.9, 22171, 'tt0843287', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p924463320.jpg', 0.9, 6.2, 47.8, 35.5, 9.6, '-0.358086,-0.145582,-0.486838,0.535657,-0.066350,-0.398028,0.330482,0.203604,-0.338708,-0.061722,0.345418,0.525904,-0.277301,0.234943,0.025328,0.024036,-0.008291,-0.699006,-0.145635,-0.057594,0.238813,-0.243388,-0.534794,0.321900,-0.314897,-0.098470,0.925960,0.120617,-0.335088,0.112969,0.605458,0.052889,-0.240950,0.379531,-0.236716,0.016013,-0.160947,0.180808,-0.458508,-0.072080,0.177714,-0.430184,-0.177087,-0.006231,-0.017007,0.304587,0.446990,0.188269,-0.258806,0.005746,0.617358,-0.351483,-0.161885,0.002939,0.141739,0.002017,0.384285,0.237557,0.100697,0.060006,-0.219492,-0.149619,-0.854093,0.232868,0.327659,-0.070832,-0.726631,0.466288,-0.098761,-0.247485,-0.165004,-0.247377,0.043420,0.309352,0.400468,0.372188,-0.236583,0.084738,-0.130513,0.383972,0.681300,0.395335,-0.287716,0.559101,0.183856,-0.552390,0.213620,-0.682681,-0.504782,0.153717,0.029750,-0.038818,0.178028,0.344517,-0.184774,0.099084,-0.235428,0.157692,0.053155,-0.319208,0.186685,-0.327323,-0.132097,-0.614430,-0.561893,-0.273950,0.181126,-0.711543,0.867058,-0.603621,0.075862,0.361805,0.233149,-0.547408,0.564707,0.162969,-0.061234,-0.006363,-0.099000,0.336636,-0.468552,-0.039645,-0.065459,0.049137,0.079468,-0.312633,-0.218964,0.499640', '27602116', '25880986', '35262731', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1864491', '隐形人', '剧情', '尼克（贾斯汀•钱特温 Justin Chatwin饰）出生于富足的家庭，亦是学校里的优等生。他梦想着可以成为诗人，但他的母亲却早已为他安排了以后的人生。他希望通过自己的努力去实现梦想。安妮（玛格丽塔•列维伊娃 Margarita Levieva饰）和尼克在同一所高中，是一个问题少女，受家庭影响，终日游手好闲。在一宗偷窃案中，安妮被男友出卖，却误认为是尼克告的密，遂与一帮朋友将尼克拖入树林暴打一顿。转天，尼克像往常一样去学校上课，却发现自己变成了幽灵一般的隐形人……©豆瓣', '贾斯汀·查特文', '大卫·S·高耶', 6.4, 5973, 'tt0435670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p472376223.jpg', 3.1, 13.6, 51.4, 24.6, 7.2, '0.255978,0.011505,-0.350901,0.343738,-0.343542,-0.440909,0.796001,0.244170,-0.384293,-0.089945,0.033700,0.750089,0.046567,0.483382,0.220756,0.176957,-0.322582,-0.727709,0.205393,-0.201052,-0.004356,-0.602895,-0.165817,-0.087763,0.023641,-0.380300,0.535961,-0.186622,-0.191677,0.223038,0.080064,0.288148,0.069686,0.453413,-0.176091,0.167597,-0.058857,-0.056009,-0.130242,0.155132,-0.135582,0.029535,-0.306584,0.019868,0.089866,0.246226,0.577253,-0.172577,-0.056764,-0.124855,0.461891,-0.295752,-0.088266,0.214074,0.300048,-0.094723,0.077243,0.083327,-0.121016,0.069967,0.277667,-0.074039,-0.632464,-0.138876,0.203351,0.172742,-0.733817,0.537861,0.052827,-0.018220,0.227678,-0.239261,0.045508,0.062856,0.209389,0.536299,-0.201271,0.123026,-0.566564,0.252579,0.637292,-0.029087,-0.395763,0.181294,-0.414526,-0.093446,0.006024,-0.072382,-0.572870,-0.298858,0.375757,-0.077654,-0.456939,0.346704,-0.299262,-0.159516,-0.285033,0.061437,-0.117282,-0.521192,-0.083960,-0.483626,0.187765,-0.251160,-0.453844,-0.118087,0.094650,-0.447388,0.557717,-0.997421,0.357076,0.846777,0.214294,-0.308864,0.770625,0.142053,0.314424,-0.063787,-0.008007,0.298652,0.263797,0.440044,-0.097955,0.322937,0.043674,-0.083723,-0.271730,0.581304', '1302384', '1949005', '1308755', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1864541', '中国龙', '喜剧', '阿姆（金城武 饰）和小文（郝邵文 饰）在夏威夷生活，小文每日在阳光沙滩上优游的与白人女童游戏，阿姆则要担负生活压力，为了保住自己的摊位，雇佣壮汉把自己打造成功夫高手来吓退流氓。释小龙（释小龙 饰）和释小燕（叶全真 饰）师姐弟分别修行功夫和特异功能，如今二人通过考验，受国家委派前往夏威夷参加世界武术大赛。小龙、小燕偶然从流氓手中救下阿姆，小文很快与小龙成为朋友，阿姆则对小燕一见钟情。被打的流氓引来犯罪集团将小龙绑架，原来小龙与小燕此行表面是参加比武，实际上是为了争夺中苏共同拥有的核武器启动装置。小燕为了救回小龙和犯罪集团作战，而他们的领队却心怀鬼胎……©豆瓣', '金城武', '朱延平', 6.9, 8580, 'tt0115053', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352179464.jpg', 0.8, 5.5, 51.8, 31.1, 10.8, '-0.091315,-0.180920,-0.471415,0.495638,-0.201874,-0.067354,0.383662,-0.023202,-0.407961,-0.143919,0.294761,0.633083,-0.041696,0.118657,0.360476,-0.207561,-0.282919,-0.624685,-0.045029,-0.043023,-0.377302,-0.389727,-0.159353,-0.033275,-0.234902,-0.381206,0.611865,-0.181075,-0.383030,0.715688,0.366819,0.155019,-0.394121,0.239566,-0.125361,-0.092828,0.022650,0.073606,-0.504587,0.218022,-0.018453,0.028745,0.047137,-0.100608,0.245376,0.162117,0.735746,-0.335645,0.190913,-0.546828,-0.140129,-0.287823,0.032283,-0.114201,0.205899,-0.060447,0.450430,0.227801,0.104609,0.043141,0.326567,-0.407135,-0.476651,0.228986,0.455213,-0.228977,-0.421359,0.365328,-0.071665,-0.022039,0.159665,-0.059533,0.136254,0.540532,0.375069,0.263459,-0.143332,0.159388,-0.473947,0.070570,0.652254,-0.140575,0.200794,0.005895,-0.056076,-0.228527,0.246874,-0.410990,0.060568,0.089802,0.195374,-0.215905,-0.006276,-0.054303,-0.627318,0.017717,0.073900,-0.048966,0.157742,-0.424124,0.046924,-0.631990,-0.034426,-0.352184,-0.185256,0.042172,0.100911,-0.327289,0.761541,-0.924159,0.069140,0.248942,0.533844,-0.462293,0.579322,0.034810,0.309659,-0.468105,-0.116377,-0.166535,0.240603,0.270147,0.247987,0.114277,-0.148167,0.116506,-0.136105,0.148118', '4127270', '26365262', '3811356', '3445516');
