INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1864990', '身为人母', '剧情', '一处平静又寻常的社区里，主妇萨拉（凯特•温丝莱特 Kate Winslet 饰）每天的工作就是带孩子，而她的丈夫理查德却整日沉迷于成人网站自慰，夫妻关系濒临有名无实的境地。无聊的日子中，萨拉的注意力被同社区的“律师情人”布拉德（帕特里克•威尔森 Patrick Wilson 饰）所吸引。布拉德的妻子凯西（詹妮弗•康纳利 Jennifer Connelly 饰）是位女强人，平日忙于工作，无暇顾及家庭，夫妻之间越渐陌生。萨拉和布拉德由借带孩子之名越走越近，时常在社区游泳池相会，他们最终跨越了界线……这个夏天的压抑气氛，伴随社区到来了一位恋童者所引发的恐慌达到了顶峰，萨拉在难以忍受与布拉德的地下情之后提出了私奔计划。而在当晚，没有料到的情况发生了。©豆瓣', '凯特·温丝莱特', '托德·菲尔德', 7.7, 22740, 'tt0404203', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2573981355.jpg', 0.3, 2.1, 29, 51.4, 17.2, '0.461748,0.005703,-0.702981,0.385710,0.040505,-0.087264,0.916374,0.630418,-0.796337,-0.286869,0.118446,0.669823,-0.455201,0.210680,0.415674,-0.050522,-0.310904,-0.572066,-0.208726,-0.197515,-0.151167,-0.460635,-0.208801,-0.231775,-0.257383,-0.394388,0.404512,0.020279,0.162356,0.373725,0.226050,0.410777,-0.152588,0.563313,0.130330,-0.105428,0.389364,-0.040630,-0.291211,0.111586,0.057813,-0.001044,-0.014747,0.002175,-0.020027,0.374404,0.693562,0.066695,-0.064995,-0.039426,0.342375,-0.095276,-0.037099,0.206070,0.460409,-0.300622,0.034051,0.161792,-0.210975,-0.106165,0.088652,-0.107186,-0.478294,0.368931,0.048269,0.272180,-0.402635,0.495619,-0.071780,-0.192175,0.244039,-0.256599,0.043766,0.230174,0.206452,0.425432,-0.162355,0.008927,-0.436644,0.141982,0.681689,0.089039,-0.279541,0.481984,-0.425658,-0.362749,-0.211908,-0.340332,-0.583281,-0.353544,0.155717,0.073497,-0.162376,0.439080,-0.414574,-0.075669,-0.299937,-0.164752,0.050726,-0.493370,-0.102373,-0.824437,-0.213771,-0.541931,-0.104189,-0.094844,0.105756,-0.164741,0.470655,-0.739744,0.370797,0.515178,0.090583,-0.361859,0.714886,0.192693,0.407736,-0.271503,0.073245,0.297844,-0.062671,0.131670,0.091542,0.211274,-0.167813,0.031391,-0.315850,0.582215', '1309172', '10466639', '1296534', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1865012', '五路追杀令', '剧情', '美国黑手党头目老普莱摩生命垂危，而此时他昔日的手下——魔术师巴迪（Jeremy Piven 饰）正与警方谈判，试图通过做污点证人来减轻自己的抢劫罪行，病床上的普莱摩下令拿到巴迪的心脏，并委托一名神秘的瑞典人处理此事。黑手党二号人物迅速发出了一百万美元的悬赏，誓要取得巴迪性命。截获此消息的警探理查德（Ryan Reynolds 饰）与唐纳德马上前往巴迪的所在地——太浩湖。与此同时，高额悬赏吸引了各路杀手，包括疯狂的纳粹三兄弟、辣妹双人组、易容杀手以及擅于刑讯的雇佣兵，三名离职警察亦同时受律师委托，带回弃保的巴迪。一时间，各路人马先后杀到巴迪潜藏的豪华酒店，将那里变成了混乱的战场……尘埃落定之后，理查德却发现了此案背后的玄机。©豆瓣', '瑞安·雷诺兹', '乔·卡纳汉', 6.9, 15064, 'tt0475394', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1020566754.jpg', 1.4, 7.6, 45.1, 35.7, 10.1, '0.220619,-0.038766,-0.406094,0.422650,-0.080536,-0.151968,0.496843,0.041542,-0.515778,-0.200478,0.373991,0.508354,0.139215,0.107840,0.563582,-0.132389,-0.417913,-0.916952,-0.383512,-0.304619,-0.252619,-0.565148,-0.316445,-0.272575,0.088982,-0.380813,0.529584,0.003470,-0.041848,0.630259,0.476798,0.519011,-0.307383,0.310838,0.160117,-0.040037,0.472215,-0.443403,-0.340593,0.264294,-0.102856,-0.312509,0.032993,0.090295,-0.039137,0.551678,0.399746,-0.241561,0.084228,-0.278498,0.142128,-0.313351,0.153830,0.151314,0.371642,0.193233,0.108124,0.303390,-0.319540,-0.090755,0.083649,0.092441,-0.940140,-0.045527,0.118942,0.263473,-0.322994,0.007091,-0.538886,0.286325,-0.004246,-0.072843,0.119864,0.185600,-0.029445,-0.013666,-0.090547,0.009841,-0.416441,0.001954,0.418292,-0.167279,-0.021537,-0.489156,0.170228,-0.365985,0.106486,-0.189615,0.085209,-0.026781,0.644165,-0.008637,0.138345,0.100684,-0.476768,-0.302027,-0.443687,-0.327341,-0.152388,-0.127676,-0.104375,-0.991278,-0.135481,0.261312,-0.047215,0.029759,0.258777,0.218844,0.549058,-0.453408,0.129683,0.490860,0.158998,-0.323842,0.122128,-0.171563,0.354625,-0.070283,-0.383270,-0.129068,0.619302,0.609279,0.207656,-0.001176,-0.200165,-0.456851,-0.158518,-0.012617', '25723905', '2028645', '6517421', '30143331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1865108', '黑白道', '剧情', '当了八年卧底探员的海生（张家辉饰）成功逮捕犯罪分子Dark哥（吴镇宇饰），心想到终于可以摆脱卧底生活，海生感到生活又恢复了光明。可是，事情却不是海生想的那样美好。复职的颁奖仪式草草了事，同事对他投来的不是关切与欣赏，而是不信任的目光。警员阿龙（黄秋生饰）只是默默地安慰他。卧底时期的女友与自己分手，陌生人开始跟踪自己，海生觉得自己警员的生活远比卧底更加痛苦。他回想起卧底时候Dark哥与他的往事，不由得动容，而此时，海生卧底时的朋友找到海生，原来想逃离卧底生涯，远非那么简单。©豆瓣', '张家辉', '邱礼涛', 6.8, 11521, 'tt0845464', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1643403737.jpg', 1, 7.1, 51.4, 32, 8.5, '0.321654,-0.418486,-0.318219,0.345243,-0.209966,-0.441598,0.785480,0.104379,-0.804711,-0.235362,0.329795,0.640355,0.108202,0.120045,0.248055,0.294348,-0.656584,-0.670678,0.259411,-0.163115,0.278363,-0.521791,-0.109450,-0.205688,0.079945,-0.294149,0.839134,-0.016818,-0.074184,0.539081,-0.057627,0.256302,0.125684,0.594310,-0.068947,0.105197,0.102803,0.194793,-0.726237,-0.100934,0.323202,-0.020120,-0.434619,0.340550,-0.060152,0.148534,0.233608,0.039726,-0.493075,0.094785,0.030077,-0.633660,-0.152730,0.041922,0.062167,0.255555,0.317078,0.201298,-0.153378,-0.044311,-0.058066,0.178973,-0.609880,0.128927,0.092586,0.336124,-0.336919,0.202336,-0.240041,0.108908,0.368483,-0.287339,0.174192,0.243535,0.151938,0.429644,-0.274775,-0.080706,-0.336294,0.424531,0.876671,-0.006569,0.081818,0.442972,0.173375,-0.099622,-0.007691,-0.027022,-0.327831,0.239725,-0.216755,-0.018363,-0.309509,0.390758,-0.534984,-0.098974,-0.186666,0.177799,-0.067958,-0.735186,-0.278043,-0.211917,-0.297391,-0.186934,-0.294374,-0.128801,0.047131,-0.476426,0.392727,-1.247915,0.038518,0.589745,0.484626,-0.568700,0.433002,0.165841,-0.332557,-0.813644,-0.044206,0.107724,-0.223788,0.383280,0.112412,0.110193,-0.046510,-0.370872,-0.306696,0.005191', '30345227', '35030151', '1308755', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1865561', '潜水钟与蝴蝶', '剧情', '1995年12月8日，一场突如其来的灾难袭向了家庭事业双得意总编吉恩•多米尼克•鲍比（Mathieu Amalric 饰）。他的脑干突然中风，继而引发极其罕见、概率极低的闭锁症候群。罹患此症的吉恩全身瘫痪，只有左眼尚能自由活动。他形容自己就如同困在潜水钟里一般，身体被紧紧箍住，无法动弹，而心灵却像蝴蝶一样在广阔的天地里自由飞翔。吉恩凭借着左眼和顽强的意志以及语音矫正师的协助，与世界做着无声的交流……本片荣获2007年AFI电影节观众奖最佳影片奖；2007年波士顿影评人协会最佳摄影、最佳导演和最佳外语片奖；2007年戛纳电影节最佳导演奖和技术大奖；2008年法国凯撒电影节最佳男主角（Mathieu Amalric）和最佳编剧奖。©豆瓣', '马修·阿马立克', '朱利安·施纳贝尔', 7.9, 38703, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p553666966.jpg', 0.3, 1.9, 22.6, 50.9, 24.2, '-0.460051,-0.057642,-0.502037,0.614780,0.330718,0.122988,0.476013,0.188063,-0.431589,0.132262,0.039556,0.899964,-0.443002,0.172979,0.346687,-0.101961,-0.242685,-1.002020,-0.208004,0.014863,-0.147167,-0.287314,-0.426903,0.054288,-0.035969,-0.710638,0.787119,-0.154627,-0.125416,0.513486,0.317309,0.205111,0.118206,0.043615,-0.228459,-0.181796,0.160635,0.063863,-0.331164,0.627321,0.114055,-0.310286,-0.264280,0.168062,-0.023383,0.114120,0.645405,-0.576778,-0.062460,-0.037253,0.576766,-0.499655,-0.163050,0.066096,0.140314,-0.144560,0.425373,0.002921,-0.050183,0.273917,0.419701,-0.453748,-0.683368,0.150916,0.103009,0.168729,-0.405279,0.310639,-0.005336,0.251677,-0.267222,-0.093265,0.128184,0.212841,0.190728,0.378752,-0.551794,-0.018558,-0.109151,0.672739,0.250619,-0.097458,-1.034829,0.318153,-0.327419,-0.680983,-0.318050,-0.358752,-0.257795,-0.215965,0.531178,0.279720,0.048439,0.229923,-0.338304,0.182255,0.066047,-0.458126,-0.205364,-0.162027,0.109141,-0.801369,-0.046994,-0.253314,0.042499,-0.006789,0.170601,-0.365744,0.562743,-0.728059,0.311168,0.600531,0.202647,0.052961,0.797805,-0.191409,0.121697,-0.230893,-0.155361,0.182658,-0.334372,0.126758,0.232809,0.362608,-0.135984,0.093021,-0.339495,0.508479', '1780122', '10462973', '1299663', '1302279');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1865703', '红辣椒', '科幻', '近未来，为了治疗现代人类越来越多、越来越严重的精神疾病，位于东京的精神医疗综合研究所开发出一种可以反映他人梦境的机器。通过微型DC的帮助，梦境在显示器上呈现出来，更方便找到一个人焦虑的症结。某日，三台微型DC失窃，与之相关的研究人员的梦境接连被人侵入，随后受到严重伤害。美女医疗师千叶敦子另一个身份是梦境侦探“红辣椒”，她能够与患者同步体验梦境。为避免盗贼利用微型DC进一步作恶，她不得不潜入受害者的梦中寻找恐怖分子，一场充满奇幻和惊险的争斗旋即展开……本片入围2006年威尼斯电影节主竞赛单元，荣获2007年葡萄牙奇幻电影节影评人选择奖、2006年蒙特利尔电影节大众选择奖。©豆瓣', '林原惠美', '今敏', 9.1, 420438, 'tt0851578', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p456825720.jpg', 0.2, 0.6, 6.9, 30.5, 61.7, '0.030315,0.009879,-0.237960,0.423753,0.295419,0.109249,0.642947,-0.227086,-0.772309,-0.256897,0.321567,0.611906,-0.339268,0.018839,0.162248,-0.203931,-0.420012,-0.416396,-0.236407,-0.147839,-0.399723,-0.468065,-0.406380,-0.246651,-0.056387,-0.531768,0.821284,0.173050,-0.528957,0.122540,-0.042366,0.321759,-0.315581,0.176981,0.097963,-0.285782,-0.012003,-0.046093,-0.624388,0.458675,0.000431,-0.279848,-0.043927,0.071387,-0.115499,0.116033,0.812038,-0.262055,-0.215233,-0.245942,0.755857,-0.247064,-0.370334,-0.315742,0.017862,0.275896,0.081183,-0.055248,-0.072068,0.083429,-0.015479,-0.241159,-0.725926,-0.064834,0.250312,0.180090,0.031755,0.198175,-0.171668,0.236474,-0.026422,-0.062164,0.095429,0.149054,0.538272,0.186104,-0.193513,-0.007741,-0.175058,0.331723,0.507900,-0.180250,-0.478041,0.341376,-0.361611,-0.767447,-0.243418,-0.557185,-0.130365,0.327821,0.323485,0.043073,-0.110800,0.360556,-0.526415,0.108356,-0.198398,-0.392367,0.048969,0.022557,0.118718,-0.857582,0.069786,0.141354,-0.151192,-0.147222,0.092641,-0.550363,0.639741,-0.789519,0.160707,0.713326,0.350136,-0.288471,0.503759,-0.217458,0.057428,-0.340212,-0.199242,0.300788,-0.012933,0.343346,-0.399331,0.158721,-0.066411,-0.076387,-0.444285,0.074751', '2369613', '2286642', '26759820', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1865903', '苏乞儿', '剧情', '鸦片战争前夕，大侠黄飞鸿（王珏 饰）协助钦差大人林则徐（鲍方 饰）查禁鸦片。十二贝勒（熊欣欣 饰）勾结烟商决定亲自来广州对付黄林二人。广东富商苏仁（吴孟达 饰）的儿子苏灿（甄子丹 饰）武功了得，苏灿的女友戴懿德（袁洁莹 饰）刚从国外回国，遭到火莲教袭击，苏灿为救女友用巨型炮仗炸毁了太平鼓还伤及了无辜。黄飞鸿得知此事后找到苏灿理论，苏灿对黄不满矛盾由此而生。十二贝勒知道两人不和趁机挑拨，想利用苏灿对付黄飞鸿。暗恋苏仁的小姨峭牙珍（陈淑兰 饰）因为误会率领众人去破坏戴懿德的妇女会，与此同时戴发现了十二贝勒的阴谋，但反被十二贝勒抓住，苏灿为救戴被十二贝勒擒住，还让苏灿染上了毒瘾。受到挑拨之后的苏灿前去行刺林则徐，与黄飞鸿发生打斗，戴懿德终于出现说明了真相，苏灿懊悔不已一蹶不振。幸亏老乞丐（关海山 饰）出现帮助苏灿戒毒成功，在千军一发之际苏灿出现帮助黄飞鸿制服了十二贝勒。', '甄子丹', '袁和平', 6.6, 8003, 'tt0106376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2870207352.jpg', 1.2, 7, 60, 24.5, 7.2, '-0.087182,-0.051739,-0.549383,0.190894,-0.010766,-0.218140,0.274518,0.111459,-0.332572,-0.153115,0.386367,0.281622,-0.362849,-0.177031,0.213420,-0.105508,0.020625,-0.498126,0.274044,0.026590,-0.035152,-0.261592,-0.045264,-0.206321,-0.044495,-0.509421,0.171288,-0.123738,-0.271216,0.560152,0.508839,0.284090,-0.170264,0.420417,-0.034750,0.253384,-0.073830,-0.186224,-0.187664,0.322484,-0.045368,-0.338049,0.101613,0.128066,-0.201964,0.516411,0.466246,-0.240111,0.144020,-0.220108,0.130235,-0.283389,-0.129980,0.266447,0.421695,0.164738,0.044701,0.218660,-0.279464,0.062796,0.158334,0.120724,-0.096948,0.137554,0.227312,0.050122,-0.344954,0.076995,-0.256557,0.000591,0.019424,-0.316043,0.343659,0.538997,0.329629,-0.045258,-0.113774,-0.009896,-0.562486,0.137104,0.332890,-0.320009,0.368076,0.027235,0.327885,-0.062801,0.173371,-0.168763,0.069006,0.175715,0.389001,-0.267146,-0.000074,-0.018307,-0.231473,-0.635410,-0.379941,0.346922,0.145707,-0.115037,0.086950,-0.408765,-0.195427,-0.230869,-0.211864,-0.077198,0.230471,-0.102259,0.154695,-0.514485,0.202637,0.033352,0.423906,-0.561559,0.482236,0.280366,-0.037588,-0.073664,-0.005589,-0.260784,0.201555,0.094549,0.076670,0.289303,-0.065682,-0.364738,-0.088176,-0.290323', '1297710', '1305016', '26611458', '1305179');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1865943', '哆啦A梦：大雄的恐龙', '动画', '一天，大雄和静儿、技安被强夫邀到家中参观恐龙化石。当然，大雄免不了又被强夫取笑一番。为了要做强夫面前争一口气，大雄夸下海口，恐龙化石没什么了不起，他要让小伙伴们见识一下真正的恐龙！奇迹再次发生在大雄身上，他真的找到了一颗活的恐龙蛋！大雄和叮当在家将小恐龙孵化了出来并在公园里暗中饲养。小恐龙比助一天天长大，公园有怪兽的消息传遍了日本。为了小恐龙能健康成长，大家决定将小恐龙用时光机送回白垩纪。没料到，一个神秘人暗中跟踪他们，也来到了白垩纪想要虏走比助。为了保护比助，叮当、大雄、强夫、技安和静儿再次来到了白垩纪……©豆瓣', '大原惠美', '渡边步', 8, 23772, 'tt0802983', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2371782728.jpg', 0.3, 1.8, 23.5, 44.4, 30, '0.043799,0.008374,-0.628606,0.094034,0.044641,-0.169645,0.527808,-0.263301,-0.407040,-0.034919,-0.136708,0.776003,-0.469473,0.321292,-0.231369,-0.151995,-0.387821,-0.326256,-0.149605,-0.129585,-0.225517,-0.084871,-0.304847,-0.125091,-0.013440,0.038778,0.229522,-0.256817,0.026227,0.395125,0.182917,0.018390,-0.137902,0.030175,-0.516737,0.139549,-0.171043,-0.040090,0.027299,0.172536,0.096694,-0.011351,-0.045380,0.018047,0.347681,-0.214853,0.527618,-0.592953,-0.231264,-0.481357,-0.106244,-0.121383,0.023525,0.005652,0.315716,-0.116639,0.147954,0.079583,-0.239259,0.158796,0.362748,-0.353054,-0.443759,0.367046,-0.274611,-0.051008,-0.423985,0.145159,0.278411,0.019197,0.334457,-0.445482,0.494407,0.250456,0.143712,0.285733,-0.127805,0.328465,-0.399096,-0.054707,0.772852,-0.152992,0.110838,0.072971,0.374242,-0.362946,0.013746,-0.359909,-0.170492,-0.090499,0.367172,0.015042,-0.536670,0.071832,-0.560419,0.082880,-0.526548,-0.361976,-0.090060,-0.037389,-0.143685,-0.053521,0.034352,-0.057476,-0.064604,0.471487,0.179363,-0.401158,0.808663,-0.672176,0.251973,0.447847,0.492290,-0.381129,0.261844,-0.498418,-0.151717,-0.088242,0.082104,-0.235881,0.090915,0.440756,0.460374,0.120115,-0.037806,-0.435438,-0.594423,0.056435', '1458910', '1458900', '26711487', '1457926');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866131', '铁三角', '动作', '彭辉（古天乐饰）、宝山（任达华饰）和莫中原（孙红雷饰）是三个饱受社会、家庭以及经济压力的好友。一天晚上，三人在酒吧聊天，商量改变现状的办法。一位名叫陈福水的神秘老人留下线索，为他们三个带来一次寻宝奇遇。莫中原破解了老人留下的密码，原来宝藏就藏在立法局的地下。三人准备一番，决定铤而走险，寻找宝藏。然而就在他们发财在望之时，警探正文（林家栋饰）却追捕而至，他和彭辉乃至宝山的妻子（林熙蕾饰）似乎又有着不可告人的秘密。一连串怪事也接踵而至，先后加入的人物与势力，陷入了你死我活的夺宝旋涡而无法自拔。©豆瓣', '古天乐', '徐克', 6.4, 25589, 'tt0846017', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1116915846.jpg', 2.3, 11.6, 54.2, 25.9, 6, '-0.003310,-0.175058,-0.575897,0.648788,0.061749,-0.099581,0.768449,0.285144,-0.575768,-0.374158,0.175674,0.598224,-0.093802,0.261479,0.248016,-0.314571,-0.240891,-0.646272,0.260155,-0.175012,-0.311878,-0.445085,-0.202950,-0.312577,0.034078,-0.202446,0.658705,0.312058,-0.210003,0.263870,0.301497,0.391743,-0.655618,0.628784,-0.203463,-0.111697,0.331559,0.310118,-0.581485,0.097287,-0.043349,-0.393218,-0.313498,0.136704,-0.107736,0.328326,0.629497,-0.202043,-0.116724,0.179894,0.137442,-0.316146,-0.272700,-0.091419,0.339621,-0.102505,0.297624,0.444435,-0.212613,0.122003,0.245901,-0.002405,-0.667869,-0.083907,0.452570,0.284668,-0.280458,0.359341,0.116863,-0.145218,-0.127562,-0.349492,0.201123,0.482552,0.420330,0.163465,-0.211986,-0.029409,-0.676820,0.075722,0.495270,-0.120076,0.368081,0.251398,0.401555,-0.534492,-0.108176,0.110466,-0.217357,-0.133259,0.521885,-0.103346,-0.168207,0.167210,-0.771438,-0.108144,-0.263233,-0.292489,0.091230,-0.384871,-0.054699,-0.656058,-0.163901,0.019604,-0.275163,0.558183,0.292910,-0.120384,0.660867,-0.476052,0.068197,0.383211,-0.118574,-0.776618,0.706978,-0.020921,0.161654,-0.443455,-0.069783,0.001989,0.060947,0.154503,0.082150,0.172576,-0.165390,-0.079154,-0.303418,0.099614', '4301278', '26290398', '1294917', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866264', '女王', '剧情', '1997年，戴安娜王妃车祸身亡，举国悲痛欲绝，但是英国王室人员却对此采取了逃避疏离的态度。这种漠不关心激怒了很多英国民众。民众反王室的情绪相当高涨，紧急形势让王室陷入了严重的危机。但是，英王伊丽沙白（海伦•米伦Helen Mirren 饰）并没有出来稳定民心，而是携家人躲到了度假行宫。托尼•布莱尔（麦克•辛 Michael Sheen 饰）此时刚出任首相，面对此刻棘手的情势，必须尽快找到平衡各方利益的措施，让王室摆脱信任危机，女王重新修好与国民的关系，而自己也在当中树立权威。©豆瓣', '海伦·米伦', '斯蒂芬·弗雷斯', 7.7, 76080, 'tt0436697', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p664458467.jpg', 0.2, 1.5, 28.9, 53.3, 16.1, '0.245035,0.402693,-0.422583,0.447805,0.425443,-0.103339,0.462191,0.416291,-0.729797,-0.465837,0.057510,0.397013,0.009521,-0.133266,0.278772,-0.116656,-0.604497,-0.486971,-0.127770,0.301035,-0.088459,-0.423030,-0.185454,-0.526679,-0.559771,-0.408234,0.835109,0.309578,-0.367630,0.513559,0.030084,0.577390,0.266214,0.731235,0.442201,-0.271316,0.031719,-0.273301,-0.573504,0.237098,0.212474,-0.330461,-0.283066,0.861607,0.340180,0.626461,0.240977,-0.454196,-0.191038,0.054923,0.441342,-0.549728,-0.052384,0.364938,0.415113,-0.238572,-0.238731,0.239437,-0.345637,-0.068381,0.140877,0.040500,-0.527459,0.157242,0.021767,0.213007,-0.241794,0.464816,-0.325472,0.148274,-0.080120,-0.234346,0.303723,0.833969,0.062608,0.130777,-0.362199,0.114022,-0.486555,-0.138387,0.886503,0.038474,-0.531081,-0.106536,-0.528929,-0.512668,-0.160830,-0.499101,-0.227899,-0.249415,0.274628,0.028029,0.199237,0.453911,-0.261819,-0.299039,-0.543861,-0.284390,0.058461,-0.441045,0.268885,-0.617518,-0.250013,-0.332518,-0.163658,-0.218647,0.286671,0.036786,0.441356,-0.647280,0.043746,0.329028,0.223462,-0.940631,0.103890,0.065002,0.141852,-0.155969,-0.364693,0.289726,-0.004988,0.197280,-0.066997,-0.129544,0.037976,-0.312754,0.097919,0.134652', '1484760', '1395445', '1293265', '1294693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866424', '尼斯湖怪：深水传说', '家庭', '因为战争的缘故，安格斯•麦克莫洛（亚历克斯•以特尔 饰）的父亲远征战场。他与母亲、姐姐一起居住，他与父亲感情深厚，每天都期待着父亲能够回家团聚。安格斯喜欢浩瀚的大海，却畏惧下水游泳。一天他在海边发现了奇怪的石头。原来这是颗蛋，当一条奇怪的爬行动物出现在安格斯的面前时，他惊讶极了。他为这只小动物改名“克鲁索”，克鲁索即使淘气，却十分听从安格斯的话。安格斯把克鲁索当作自己的朋友，精心照顾，但克鲁索越长越大，他害怕母亲要他放弃克鲁索。这时他们的大房子被军队征用做栖身之地，安格斯便要更加小心了。但还是无法避免的因为克鲁索的淘气发生了许多荒唐事。幸好，安格斯有男佣刘易斯的帮忙，他们把越长越大的克鲁索放进了尼斯湖中。安格斯时时跑去与克鲁索玩耍，首次在克鲁索的带领下潜入了水底。但生活存在着暗涌，当地人开始发现了克鲁索的存在，想借此成名。就连住在安格斯家中的军队，也误以为巨大的克鲁索是敌方的潜艇，对可怜的它发出攻击，安格斯拼命营救。', '布鲁克·奥佩斯', '杰·拉塞尔', 6.9, 40200, 'tt0760329', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1514858619.jpg', 1.1, 7, 48.4, 33.1, 10.4, '0.264692,-0.062190,-0.955852,0.497805,-0.187706,-0.251564,0.834232,0.009844,-0.626665,-0.176912,0.178709,0.851809,-0.022524,0.183713,-0.083885,0.198300,-0.303097,-0.462224,-0.117762,-0.036333,-0.211251,-0.350406,-0.383797,-0.199210,-0.011318,-0.220743,0.317103,-0.002162,-0.175772,0.469664,0.116009,0.094915,0.081426,0.688298,-0.324869,-0.002547,-0.277548,-0.064248,-0.006908,0.026243,0.144024,-0.048180,-0.203588,0.186620,0.288653,0.352389,0.539620,-0.357774,-0.313623,0.014835,0.092903,-0.346282,0.221730,0.182836,0.269219,0.033495,0.038139,-0.063616,-0.158842,0.116962,0.214696,-0.008180,-0.745616,0.092642,-0.109296,0.142261,-0.789301,0.361886,0.005074,-0.166093,0.208320,-0.415873,0.302378,0.469998,0.054203,0.259466,-0.391943,0.016580,-0.598850,0.015017,0.778763,-0.059084,-0.111778,0.170395,-0.240541,-0.238679,0.101902,-0.281168,-0.559955,-0.121631,0.321646,0.045916,-0.400031,0.226319,-0.535418,-0.041694,-0.244385,-0.322407,-0.221458,-0.435449,-0.082264,-0.317173,0.037941,-0.498823,-0.383485,0.135975,-0.034776,-0.304547,0.618325,-0.864652,0.318618,0.688579,0.496645,-0.352069,0.656730,0.086482,0.033883,0.005491,-0.070477,0.173372,0.019994,0.270450,0.416373,0.373768,0.211827,-0.020301,-0.537875,0.432106', '1291586', '2990737', '1296538', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866462', '恶魔的艺术2：邪降', '恐怖', '六个昔日的同窗好友在分开多年之后分别收到了旧时好友Ta的邀请，于是他们一起离开曼谷前往儿时的故乡。记忆之门也渐渐敞开。当时还在读中学的他们与校内好色的体育老师不和，一次偶然的机会，六人撞破了体育老师与Ta的继母Panor（Mamee饰）的奸情，并用DV录下。Ta将此事告知父亲，导致父亲与继母panor的对峙，panor更加愤恨Ta。疯狂的体育老师遂将六人抓起来进行虐打侮辱。受辱后的六人愤恨难平，于是前去求助神奇的巫师，请求降邪......六人本以为过去的事已经远离，却不知此次旅行，却成为了他们万劫不复的噩梦......©豆瓣', '娜帕克帕发·纳克普拉西特', 'Pasith Buranajan', 7.5, 33350, 'tt0756222', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1308639435.jpg', 1.1, 4.2, 31.8, 44.7, 18.3, '0.433861,-0.040333,-0.754000,0.810097,0.096554,-0.562252,0.741685,-0.117215,-0.609304,-0.084703,0.029992,0.844569,-0.208060,0.483483,0.360930,-0.200351,-0.227718,-0.880646,-0.183504,-0.356118,-0.442452,-0.518774,-0.048621,-0.132074,0.008393,-0.247645,0.611928,0.006863,-0.241903,0.856321,0.310485,0.148580,-0.434962,0.589191,-0.128372,0.090932,0.003186,0.332706,-0.445105,-0.027800,0.118204,-0.359415,-0.079861,0.125136,-0.033523,0.393010,0.719101,-0.332027,-0.138371,-0.229341,0.120248,-0.332911,-0.159202,0.443806,0.350615,0.174973,0.327000,0.238025,-0.325120,0.111705,-0.169220,0.090255,-0.558364,0.123266,0.166177,-0.155303,-0.598552,0.589919,0.101788,0.026187,0.123375,-0.415652,0.121640,0.603414,0.139540,0.325934,-0.267681,-0.195115,-0.246662,0.055977,0.870760,-0.196421,0.153305,0.034786,0.170513,-0.205751,0.164808,-0.018575,-0.392485,0.047157,0.440924,0.360560,-0.244946,0.324911,-0.563299,-0.455661,-0.335228,0.110111,0.113417,-0.594155,0.020891,-0.477121,-0.044837,-0.050308,-0.299446,0.141142,0.216925,-0.126532,0.477735,-0.807869,0.328138,0.296157,0.426704,-0.617464,0.586769,0.207355,0.230743,-0.184177,-0.021969,0.047443,0.180544,0.551730,0.239300,0.337729,-0.025540,-0.092514,-0.402459,0.320970', '1301022', '35030151', '30345227', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866471', '雷神', '动作', '勇敢善战雷神托尔（克里斯•海姆斯沃斯 Chris Hemsworth 饰），作为永恒境界阿斯加德的王位继承人，受人敬仰。然而由于一次鲁莽的行动，险些挑起一场古老的战争，因此被父亲天神奥丁（安东尼•霍普金斯 Anthony Hopkins 饰）流放到人间。托尔在人间认识了 美丽的女科学家珍•福斯特（娜塔莉•波特曼 Natalie Portman 饰）和她的工作伙伴，在他们的帮助下，托尔找到了和自己一起被贬的雷神之锤，但此时的雷神之锤并不属于他。此间，托尔的弟弟洛基为了成为阿斯加德的王，居然联合寒冰巨人，企图在永恒境界掀起一场腥风血雨。为了维持永恒之界的法度，托尔的四位朋友也来到人间，他们决定带托尔返回永恒之境。此时，为了阻止雷神重归永恒境界，洛基派出巨人杀死托尔。丧失能力和法战的托尔为了保护无辜的人类与自己的朋友，献出了自己的生命。托尔的死打破了天神的的咒语，托尔复活并重获雷神之力战胜巨人。此时，天神生命危在旦夕，托尔必须与自己的朋友们重返永恒之界，维护那里的法度……本片改编自传奇漫画家搭档斯坦•李（Stan Lee）和杰克•科比（Jack Kirby）于1962年推出《雷神》连载漫画。', '克里斯·海姆斯沃斯', '肯尼思·布拉纳', 7.1, 322955, 'tt0800369', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p956098719.jpg', 0.8, 5.8, 43.6, 35.8, 14, '0.090232,0.394621,-0.609015,0.648197,-0.060668,-0.325365,0.666320,0.085275,-0.249229,-0.365215,0.277572,0.845053,0.063759,-0.031891,0.482382,-0.061472,-0.387819,-0.467690,0.068374,0.061258,-0.194953,-0.315295,-0.577213,0.032366,-0.308640,-0.639797,0.739359,-0.127607,0.079794,0.099755,0.087693,0.442802,-0.138140,0.345227,0.106121,0.096287,-0.029646,-0.144156,-0.539738,0.406014,-0.194774,0.158350,-0.085166,0.335552,-0.231259,0.111347,0.259706,-0.563810,0.343915,-0.497567,0.163324,-0.482638,-0.159031,0.126863,0.125551,-0.291959,0.012591,0.263830,0.157093,-0.079136,0.339178,-0.401902,-0.950313,-0.113348,-0.081259,0.079326,-0.347261,0.351737,-0.175142,0.026319,0.221397,-0.214637,0.219722,0.452071,0.337741,0.438451,-0.299514,-0.176924,-0.476990,0.177472,0.827318,-0.105873,-0.355041,-0.072699,-0.089971,-0.496661,-0.425495,-0.472671,-0.621187,-0.114819,0.338075,0.204724,0.257930,0.723322,-0.629032,-0.388007,-0.466435,-0.177651,-0.163466,-0.465102,0.074775,-0.490175,-0.113241,-0.160695,-0.096369,-0.166816,0.214760,-0.313285,0.681096,-0.830428,0.485273,0.355165,0.515314,-0.280525,0.784369,0.115511,0.288603,-0.431547,-0.019423,0.586162,0.287099,0.330169,0.099907,-0.135144,0.029853,0.342400,-0.242597,0.637813', '10440076', '1793491', '26667010', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866473', '蚁人', '动作', '前工程师斯科特（保罗·路德 Paul Rudd 饰）由于劫富济贫进了监狱，出狱后的他为了争取看望女儿的权利又走上了盗窃之路。没想到一次意外的偷盗事件让他成为了新一代“蚁人”，老蚁人汉克.皮姆博士（迈克尔·道格拉斯 Michael Douglas 饰）成为了他的导师，可皮姆博士的女儿霍普（伊万杰琳·莉莉 Evangeline Lilly 饰）却并不看好他。但是危机迫在眉睫，为了对付强大的敌人拯救世界，斯科特不得不叫来自己的一帮狐朋狗友帮助自己完成一个不可能完成的任务。而取得任务的成功也是斯科特挽回女儿的关键，屌丝能否逆袭就看最后一击。©豆瓣', '保罗·路德', '佩顿·里德', 7.7, 419110, 'tt0478970', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266823371.jpg', 0.3, 2, 29.2, 50.3, 18.1, '0.050200,0.182534,-0.401545,0.595847,-0.476083,-0.616032,0.415645,-0.020108,-0.241754,-0.175807,0.356445,0.726798,0.235150,-0.099917,0.258223,0.299155,-0.251173,-0.422979,0.276327,-0.160803,-0.347707,-0.455262,-0.582236,-0.404154,0.003145,-0.360874,0.598254,0.188712,-0.096935,0.221287,0.368912,0.414772,0.258314,0.584010,0.120326,0.117276,0.500920,-0.013589,-0.221885,0.315219,0.138077,-0.246356,-0.202188,0.438698,0.055301,0.344317,0.440617,-0.159736,-0.082081,-0.396688,0.226032,-0.644407,0.045163,0.066140,0.123058,-0.161343,0.124218,0.400967,0.018019,-0.154406,0.099728,-0.189511,-1.090303,0.152921,0.065104,-0.050704,-0.615908,0.341811,-0.315489,0.060071,0.064946,-0.368649,-0.023993,0.295568,0.329677,0.308759,-0.360617,-0.007300,-0.471306,0.246575,0.647825,-0.483397,-0.163077,0.273252,0.029401,-0.470176,0.226956,-0.377769,-0.253781,0.175379,0.400374,0.170864,-0.136760,0.049607,-0.335352,-0.105979,-0.760663,-0.148334,-0.082580,-0.519761,0.156386,-0.426392,0.029843,0.123766,-0.372927,-0.003615,0.047948,-0.597122,0.558162,-0.660515,0.005982,0.785309,0.227993,-0.658476,0.627719,0.219356,0.275985,-0.552430,-0.044710,0.002341,-0.051735,0.497436,0.149108,0.146970,0.431316,-0.436621,-0.106791,0.507264', '26678784', '30163500', '1793491', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866475', '无敌浩克', '动作', '在高华大学变异的经历总在重演，关于军方通缉的亦围绕在脑海，科学家Bruce Banner（爱德华·诺顿 Edward Norton 饰）就在这样的梦魇下在巴西一边控制着体内的伽马辐射带来的异常，一边努力和纽约的蓝先生寻求解决办法。在汽水生产厂房的他一日不小心割伤手指，让血滴入了汽水瓶，远销到美国的这瓶汽水暴露了他的行踪。美国军方穷尽能力追捕他，还找来求胜心切的英国霹雳将军Emil Blonsky（蒂姆·罗斯 Tim Roth 饰）。被逼到绝路的Bruce变身为绿巨人，Emil和其他军人都大吃一惊。为了亲手擒住Bruce，Emil建议给自己注入可使基因变异的样本。Bruce在美国隐匿时遇到旧女友Betty Ross（丽芙·泰勒 Liv Tyler 饰），Betty义无反顾地站在他一边，同时发现，她拥有令他体内绿巨人安稳的力量。那边Emil已经被求胜蒙蔽了眼睛，他的寻衅加上美国军方极度想利用Bruce体内异能作为残暴行径的决心，一场大战已经避无可避。', '爱德华·诺顿', '路易斯·莱特里尔', 7.1, 216670, 'tt0800080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p916263375.jpg', 0.6, 4.9, 46.5, 35.6, 12.5, '0.145453,0.171737,-0.632239,0.626084,-0.095004,-0.117940,0.531216,0.151619,-0.302720,-0.160619,0.219890,0.603179,-0.064382,-0.021315,0.206226,-0.058575,-0.127049,-0.651800,-0.089248,0.088352,-0.406063,-0.409933,-0.466745,-0.036108,0.029028,-0.529494,0.532880,0.078385,-0.464475,0.243047,0.105569,0.492522,-0.046415,0.523020,-0.303805,-0.115677,-0.207885,-0.318431,-0.088530,0.272872,0.408727,-0.485285,0.038099,0.388758,0.106269,0.141142,0.640397,-0.132349,0.059452,-0.168376,0.314657,-0.384306,0.115082,0.087659,0.381751,0.087946,-0.069837,0.062108,-0.247699,0.143947,0.251680,0.249358,-0.988666,-0.222160,0.209144,0.140148,-0.677460,0.244158,-0.111067,0.166185,0.128567,-0.242581,-0.054009,0.314668,-0.049204,0.327270,-0.215166,0.061434,-0.762741,-0.025712,0.510857,-0.231186,-0.257084,0.150908,-0.062354,-0.138099,-0.198561,-0.242285,-0.305105,-0.334238,0.398177,0.233420,-0.274672,0.341000,-0.621719,-0.104353,-0.297571,-0.296578,0.126314,-0.197944,-0.033797,-0.569178,-0.261810,-0.298692,-0.189682,0.198233,0.189579,-0.201622,0.476256,-0.602512,0.162548,0.851364,0.249566,-0.439002,0.364637,0.013377,-0.018849,-0.049998,-0.233449,0.251306,0.331581,0.486583,0.149752,0.401638,0.12