INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1866479', '复仇者联盟', '动作', '一股突如其来的强大邪恶势力对地球造成致命威胁，没有任何一个超级英雄能够单独抵挡。长期致力于保护全球安危的神盾局（SHIELD）感到措手不及，其指挥官“独眼侠”尼克·弗瑞（塞缪尔·杰克逊 Samuel L. Jackson 饰）意识到他必须创建一个“史上最强”的联盟组织， 云集各方超级英雄一起发威，才能拯救世界于水深火热，抵御黑暗势力的侵袭。于是由六大超级英雄——“钢铁侠”（小罗伯特·唐尼 Robert Downey Jr. 饰）、“雷神” （克里斯·海姆斯沃斯 Chris Hemsworth 饰）、“美国队长”（克里斯·埃文斯 Chris Evans 饰）、“绿巨人” （马克·鲁弗洛 Mark Ruffalo 饰）、“黑寡妇”（斯嘉丽·约翰逊 Scarlett Johansson 饰）和“鹰眼”（杰瑞米·雷纳 Jeremy Renner 饰）组成的 “复仇者联盟”应运而生。他们各显神通，团结一心，终于战胜了邪恶势力，保证了地球的安全。', '小罗伯特·唐尼', '乔斯·韦登', 8.2, 626327, 'tt0848228', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1469137689.jpg', 0.5, 1.6, 17.4, 46.2, 34.3, '-0.181457,0.291081,-0.546788,0.562715,0.198203,0.260735,0.221821,0.142485,-0.220787,-0.348675,0.213977,0.711000,0.008160,-0.299331,0.102649,-0.275726,-0.028799,-0.330330,-0.120891,0.095740,-0.267012,-0.196049,-0.839262,-0.292012,-0.154128,-0.406735,0.734277,-0.059616,-0.466174,0.128158,0.329322,0.748481,0.042438,0.121384,0.221510,-0.318766,0.362810,-0.294198,-0.574614,0.391975,-0.510234,0.313766,0.025867,0.648198,-0.092247,-0.077954,0.263370,-0.662067,0.374225,-0.522380,0.156740,-0.263890,-0.094969,-0.244257,0.315302,-0.217809,-0.030762,0.003414,0.317709,0.069712,0.400375,-0.106705,-1.025468,-0.110052,0.288785,0.020932,-0.333230,0.064106,-0.335200,-0.052395,0.081366,0.115919,-0.029839,0.255691,0.355752,0.085372,0.046699,0.301081,-0.303918,0.013917,0.503363,-0.311633,-0.629038,-0.461027,-0.124517,-0.240682,-0.303414,-0.567650,-0.362229,-0.181410,0.372758,-0.004481,0.237028,0.374876,-0.667084,-0.120189,-0.460126,-0.150639,-0.095440,-0.343266,0.407843,-0.926912,-0.127586,-0.087611,-0.006334,0.344206,0.126745,0.184768,0.795479,-0.742209,0.217558,0.602014,0.238696,-0.240509,0.305256,0.206418,0.309659,-0.468905,-0.106648,0.265187,0.272667,0.180369,0.100606,0.190496,0.068601,0.0