INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1867332', '冒牌天神2', '喜剧', '曾在直播节目中大出其丑的主播埃文·巴克斯特（史蒂夫·卡瑞尔 Steve Carell 饰）走下演播台，开始转战政界，并成功当选布法罗的议员。他努力打造自己的良好形象，以“改变世界”的口号赢得选民的支持，同时这也是夜晚睡前祈祷的内容。在此之后，埃文带着一家四口人来到弗吉尼亚州的亨茨维尔小镇居住，即将展开全新的政坛生活。埃文的仕途顺风顺水，刚刚走马上任就得到呼风唤雨的朗议员（约翰·古德曼 John Goodman 饰）的器重，成为最新议案的共同发起人。正在这关键时刻，上帝（摩根·弗里曼 Morgan Freeman 饰）却突然出现在埃文面前，他只被要求干一件事，那就是建造一艘方舟。埃文的生活自此起了翻天覆地的变化……©豆瓣', '史蒂夫·卡瑞尔', '汤姆·沙迪亚克', 6.6, 45813, 'tt0413099', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1081258688.jpg', 1.3, 9.6, 52.8, 27.7, 8.5, '-0.005563,0.191672,-0.653535,0.633603,0.125909,-0.244112,0.571697,0.238632,-0.303187,-0.004312,0.411746,0.933564,-0.296271,0.266020,0.481966,0.165510,-0.650952,-0.659671,0.172302,-0.122286,0.061330,-0.338922,-0.159955,-0.210508,-0.044587,-0.203390,0.564203,0.096070,-0.078574,0.284532,0.367710,0.220368,0.194378,0.439215,-0.219272,0.072582,0.168881,-0.083046,-0.250845,0.001179,-0.055283,-0.090264,-0.214815,0.166884,0.320733,0.155083,0.429739,-0.452726,-0.036882,-0.050477,0.423894,-0.175809,0.119181,-0.035629,0.315030,0.100398,-0.067190,0.222794,-0.094025,-0.007593,-0.038489,-0.309910,-0.757039,-0.121472,-0.102408,0.324808,-0.381940,0.352238,-0.215610,-0.045216,-0.008700,-0.117839,-0.013280,0.322116,0.166126,0.272200,-0.033890,0.285511,-0.442538,0.129236,0.467307,0.044172,-0.491954,0.184896,-0.224653,-0.225255,-0.171654,-0.219713,-0.344315,-0.329046,0.145795,-0.067550,0.373723,0.261446,-0.523962,-0.004659,-0.290256,-0.439310,0.418796,-0.261882,-0.307202,-0.858660,0.054028,0.005984,-0.168483,0.048113,-0.019029,-0.368901,0.580973,-0.766069,0.137183,0.493683,0.224337,-0.165897,0.602190,0.013867,0.316974,-0.373432,-0.286438,0.245960,-0.009854,0.551559,-0.037073,0.296299,0.171477,-0.279517,-0.281019,0.767158', '1870681', '3178770', '10763928', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1867335', '星尘', '爱情', '不要向流星许愿，否则它就会变成女人……故事开始于一个平静到让人昏昏欲睡的小村庄，由于村庄被一个鹅卵石城墙所包围，所以它也叫“围墙村”。虽然只是薄薄的一面城墙，却世世代代地保护着这里的村民，因为一墙之隔的外面世界，是一个平行宇宙，那里充满了魔幻与超自然的生物。生活在“围墙村”的特里斯坦·索恩和所有的年轻人一样，对村里最美丽的姑娘维多利亚一见倾心，为了能够得到她的爱，他甚至许下了这个世界上最不可能完成的诺言：带回天上落下的星星。为了能够完成许诺，特里斯坦不得不鼓足勇气穿越那道象征着禁忌的城墙，进入另一个世界--“暴风之所”，那是一个神秘的国度，到处都是永恒的魔法和流动的传奇，很快，特里斯坦就会完全融进这个独特的地域，成为其中的一个组成部分。当特里斯坦走进“暴风之所”，最终找到了流星下落的位置时，他发现自己看到的不是预期中的陨石，而是一个美丽、勇敢的女人……在进入大气层之时，“流星”不小心崴了脚，然而这只是一切不幸的开始而已，打从她脚落地开始，就有一系列的陷井在等着她，这个自称伊凡娜的“流星女”成了所有野心家围捕的猎物。特里斯坦就不用说了，即使没有陨石，他仍然要把伊凡娜带到维多利亚面前。除此之外，还有野蛮、残忍、邪恶的女巫，她想得到“流星”让青春永驻；国王的几个诡计多端的儿子，对于他们来说，得到“流星”，就等于得到王位。当然，这个过程中还有魔法师、小妖精以及一个会飞的海盗，他们因为各种各样的原因--有善意的，也有邪恶的，但他们的目的却只有一个，那就是伊凡娜的心脏。特里斯坦为了自己那不可告人的小秘密，决定保护伊凡娜，虽然他不知道这场旅程会带来多少不可思议的遭遇，但被爱情冲昏了头脑的他已', '伊恩·麦克莱恩', '马修·沃恩', 7.7, 68478, 'tt0486655', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p620198224.jpg', 0.5, 3.6, 30.1, 44.4, 21.4, '0.344228,0.256074,-0.856651,0.846300,-0.344707,-0.070312,1.051912,-0.106546,-0.225839,-0.223367,0.281342,0.874866,-0.061872,0.198794,0.131585,0.358044,-0.131205,-0.561504,-0.189416,-0.400128,-0.558098,-0.429202,-0.299347,-0.222301,-0.148845,-0.220917,0.760022,0.269231,-0.209359,0.125291,0.171419,0.194548,0.138109,0.561461,-0.456997,-0.034249,-0.095714,-0.048407,-0.094378,0.203680,-0.015586,-0.056396,-0.035427,0.412743,-0.350882,0.198578,0.639319,-0.573697,-0.100708,-0.232345,0.267584,-0.476151,0.109559,0.112193,0.267527,-0.316599,0.090198,0.041066,-0.003440,0.121880,0.291435,-0.128840,-1.032235,-0.047209,0.020733,0.243526,-0.474540,0.366460,0.138294,-0.183093,0.145319,-0.290267,0.369403,0.174085,0.153632,0.363018,-0.484093,-0.063796,-0.734655,-0.020337,0.700153,0.077578,-0.399108,0.471620,-0.297417,-0.519131,-0.036690,-0.094574,-0.358087,0.012875,0.516666,0.224026,-0.317100,0.199402,-0.637928,0.179221,-0.271702,-0.319351,-0.056333,-0.681372,-0.245694,-0.297242,-0.033850,-0.423174,-0.374580,0.298133,-0.030859,-0.229868,0.899152,-0.930586,0.267174,0.845978,0.372140,-0.352124,0.650977,0.096682,0.005565,-0.176128,0.018475,0.204819,0.045149,0.536790,0.010419,0.437883,0.068817,-0.102307,-0.433189,0.719372', '3769423', '25932086', '3005387', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1867345', '遗愿清单', '剧情', '老富翁爱德华•科尔（杰克•尼克尔森 Jack Nicholson 饰）近年来在公立医院的私有化改造事业中获利颇丰，他为节省成本，规定病房“一房两床”的做法颇受非议，但性格强势的科尔不以为意，岂料他不久被检查出罹患癌症，本欲入住单人病房的科尔在舆论压力下只得与另一位病人——老卡特（摩根•弗里曼 Morgan Freeman 饰）同处一室。汽车修理技师老卡特博闻强识，将三个子女培养成才，但代价是牺牲了年轻时要做历史教授的梦想。曾经结婚多次如今却孤身一人的科尔逐渐对卡特产生了兴趣，两位老人在病房中结下了友谊。科尔偶然发现了卡特的“遗愿清单”，他决定运用自己的力量，让那些纸面上的疯狂构想一一实现，去发现人生的真正意义……©豆瓣', '杰克·尼科尔森', '罗伯·莱纳', 8.7, 413105, 'tt0825232', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1481879628.jpg', 0.1, 0.6, 10.4, 42.2, 46.8, '0.196617,0.141926,-0.545682,0.405764,-0.304101,-0.601122,0.718874,0.317002,-0.497392,-0.409534,0.249633,0.840530,-0.011485,0.159987,0.263141,-0.018374,-0.135399,-0.535914,0.174481,-0.096567,-0.299944,-0.679074,-0.245147,-0.320043,-0.177126,-0.467685,0.466780,-0.036166,-0.063494,0.257155,0.251824,0.466382,0.243954,0.251089,0.053047,0.117191,0.421971,-0.184595,-0.344829,0.185315,-0.160132,-0.173447,-0.174613,0.190610,0.099740,0.436541,0.491818,-0.005960,-0.095655,-0.049558,0.344258,-0.002598,0.056188,0.307464,0.411817,0.304267,0.038823,0.506072,-0.236487,-0.249364,-0.144365,-0.117800,-0.694285,-0.049731,-0.006381,0.175848,-0.649026,0.338187,-0.295538,-0.147478,-0.256439,-0.295051,-0.037151,0.220821,0.270128,0.435044,-0.137693,0.267670,-0.446225,0.012319,0.498367,-0.131443,-0.306990,0.326761,-0.327308,-0.307335,0.115773,-0.273630,-0.312436,-0.082588,0.493885,0.029798,-0.023833,0.278576,-0.501994,-0.045807,-0.567526,-0.061057,-0.114835,-0.102091,0.045050,-0.710792,-0.334500,-0.185513,-0.491159,-0.236420,0.002145,-0.280445,0.697435,-0.549751,0.041274,0.469976,0.274228,-0.459043,0.621536,0.156004,0.414088,-0.054296,-0.122484,0.211346,-0.014001,0.279621,0.194062,0.388077,0.060513,-0.126884,-0.253696,0.548527', '30162520', '1309069', '1870681', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1867389', '同居牢友', '喜剧', '刚刚重获自由的约翰（戴克斯·夏普德 Dax Shepard 饰）再次走入了监狱，不为了别的，只为了复仇。原来，约翰此次入狱是为了执行一个任务——保护检察官的儿子尼尔森（威尔·阿奈特 Will Arnett 饰），这个检察官不是别人，正是害得约翰屡屡遭受牢狱之灾的罪魁祸首。父债子还，刚来到尼尔森身边，约翰就将他卖给了狱中人人望而生畏的同性恋老大巴里（切·麦克布瑞德 Chi McBride 饰），本以为尼尔森即将遭遇非人待遇的约翰却没有想到，尼尔森竟然激起了巴里内心的爱意和温柔，很快两人便心心相印起来。就这样，尼尔森从一个狱中菜鸟转眼变成了大名鼎鼎的“压寨夫人”。绝望中，约翰明白，自己接下来的日子不会太好过。©豆瓣', '戴克斯·夏普德', '鲍勃·奥登科克', 7.3, 20726, 'tt0454987', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1751718842.jpg', 0.7, 4.6, 39.7, 40.9, 14.1, '0.293343,-0.097933,-0.466452,0.399285,-0.551396,-0.692584,0.715810,0.129412,-0.423533,-0.395242,0.189302,0.531636,-0.361533,0.052558,0.272446,0.159034,-0.467847,-0.502065,-0.228685,-0.236232,-0.106384,-0.424375,-0.289668,-0.165616,-0.013429,-0.142544,0.320158,0.027161,-0.005246,0.427635,0.433197,0.599861,0.496923,0.383435,0.044388,0.229362,0.278253,-0.121329,-0.183708,0.188894,0.226662,-0.037512,0.031290,0.380819,-0.059963,0.175711,0.285982,-0.365554,0.039157,-0.303576,0.054211,-0.285776,0.081478,0.200052,0.048988,-0.356201,0.282690,0.118977,-0.221640,-0.007927,0.145420,-0.042482,-0.731959,0.163702,-0.258348,0.129566,-0.423558,0.034968,-0.445381,0.155063,0.126358,-0.303901,0.115550,0.274363,0.402695,0.302620,-0.265814,-0.065107,-0.528823,0.105140,0.754389,-0.101401,0.032025,0.110497,-0.071548,-0.355215,0.406687,-0.074828,-0.314359,0.088616,0.302712,-0.056484,-0.071346,0.255620,-0.373342,-0.183738,-0.480829,-0.141096,0.000719,-0.362908,-0.220881,-0.095189,-0.066867,-0.061138,-0.301042,-0.076103,-0.163072,-0.189000,0.249200,-0.767022,0.673488,0.565716,0.071498,-0.327656,0.266096,0.206002,0.198972,-0.197546,-0.078740,0.107400,0.245697,0.549524,0.330157,0.251698,0.216928,-0.377373,-0.018101,0.749214', '1308755', '25763555', '10774184', '1949005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1867408', '伤城', '剧情', '总督察刘正熙（梁朝伟饰）与妻子金淑珍（徐静蕾饰）过着甜蜜生活。与刘正熙本是同事兼好友的丘建邦（金城武饰），被革去警察职务后当起了私家侦探，终日喝酒至烂醉如泥，因多年前女友自杀身亡令他久久不能忘怀，与卖酒女细凤（舒淇饰）的关系扑朔迷离。金淑珍的父亲，富豪金元胜突然被杀害，矛头直指两个无业游民，可是嫌疑人也在案发的一个星期后被杀害，警方也迅速结案。但金淑珍觉得案中疑点重重，就拜托丘建邦帮忙。随着案件的逐步抽丝剥茧，发现了意想不到的秘密，以及故意纵火企图杀死金淑珍的元凶。一个伤心的城市，到底隐藏了多少秘密在其中呢？©豆瓣', '梁朝伟', '刘伟强', 6.8, 95984, 'tt0834902', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1653842628.jpg', 0.7, 6.6, 50.8, 33.8, 8, '-0.062315,-0.026149,-0.542982,0.180220,0.063780,-0.171999,0.649884,0.145809,-0.612819,-0.402687,0.055117,0.654842,-0.141576,0.192654,0.183872,-0.245597,-0.125097,-0.769368,0.107828,-0.224436,-0.229629,-0.638500,-0.046685,0.023509,0.141832,-0.101682,0.026833,0.039839,0.049752,0.361627,0.343419,0.485799,-0.438253,0.289659,0.107475,0.079967,0.408995,0.056462,-0.351808,0.109283,-0.001444,-0.362741,-0.075965,0.102934,-0.067169,0.409905,0.607777,-0.070067,-0.363597,-0.089717,0.231002,-0.213467,-0.095369,-0.151569,0.284265,0.089626,0.306175,0.539920,-0.528383,0.153069,0.322853,0.072798,-0.724500,0.122128,0.252431,0.101728,-0.421665,0.317617,-0.027619,-0.038098,0.071752,-0.266580,0.240159,0.342706,0.103314,0.308784,-0.261881,0.199216,-0.498894,0.479372,0.380701,0.166908,-0.024553,0.137403,0.176801,-0.202649,-0.007841,-0.072926,-0.194848,0.030959,0.418353,0.049543,-0.038341,0.226460,-0.489246,-0.143991,-0.279446,0.304536,0.109759,-0.123024,-0.224447,-0.121596,-0.151582,-0.148379,-0.156906,0.020188,0.047716,-0.154052,0.412526,-0.517529,0.182719,0.425931,0.193768,-0.722111,0.345115,0.491849,0.019353,-0.148443,-0.168097,-0.174839,0.352546,0.269882,0.407889,0.060673,-0.229683,-0.451756,-0.163699,-0.137131', '26678784', '1302110', '35073886', '1297862');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1867415', '街头之王', '剧情', '洛杉矶警察汤姆·罗德（基努·里维斯 Keanu Reeves 饰）作风骠悍，勇猛果敢，经常和队友不顾警察条例而对嫌疑犯暴力相向。他们的做法令不法分子既恐惧又憎恨，同时也受到同僚的指摘。凭借队长杰克·沃德（福里斯特·惠特克 Forest Whitaker 饰）的关照，汤姆我行我素，不为所动。泰伦斯·华盛顿（Terry Crews 饰）是汤姆的昔日搭档，他奉命调查汤姆暴力执法的问题。某晚，泰伦斯遭到两个戴面具之人的杀害，根据现场遗留下来的证据，汤姆便成了头号嫌疑犯。几经周折，他和负责调查此案的警官保罗·迪斯坎特（Chris Evans 饰）合作，却发现这起谋杀案的背后竟然隐藏着惊天的阴谋。与此同时，危险尾随而至，汤姆必须抓紧时间，为了自由和清白全力奋战……©豆瓣', '基努·里维斯', '大卫·阿耶', 6.6, 9554, 'tt0421073', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1074170920.jpg', 1.1, 8.5, 54.5, 28.6, 7.4, '0.265833,-0.304299,-0.396822,0.427754,-0.137179,-0.169436,0.535153,0.197842,-0.486572,-0.373738,0.458738,0.484604,0.060311,-0.173098,0.324515,-0.131400,-0.516477,-0.773812,-0.040448,0.042717,-0.056303,-0.694417,-0.250332,-0.392463,0.077057,-0.407516,0.290918,-0.145945,-0.148084,0.462618,0.414285,0.611408,-0.252718,0.369918,0.221895,-0.133015,0.474438,-0.276145,-0.444019,0.164939,0.174535,-0.268571,-0.217197,0.282723,-0.066301,0.658282,0.456212,-0.267766,-0.187457,-0.116193,0.312283,-0.387947,0.182557,0.290059,0.413726,-0.137200,0.026429,0.545696,0.100694,-0.105403,0.111101,0.032345,-0.823823,-0.027465,0.090464,0.361717,-0.195710,0.169627,-0.474312,0.221819,0.113208,-0.106381,-0.023002,0.206588,0.299416,-0.030526,-0.007970,-0.013656,-0.269244,-0.031628,0.385910,-0.095578,-0.062659,-0.210749,-0.255920,-0.265521,0.047827,-0.191081,-0.387024,-0.125186,0.296122,-0.179830,0.074367,0.275436,-0.393395,-0.227931,-0.404166,0.030399,-0.279025,-0.235593,0.060171,-0.790785,-0.077325,-0.218501,-0.240104,0.077861,0.095859,-0.154032,0.336517,-0.629656,0.006044,0.772504,0.314081,-0.522443,0.372924,0.107233,0.067311,-0.385066,-0.513464,-0.000006,0.629973,0.129020,0.178893,0.103045,0.307816,-0.353415,0.082054,0.094277', '1307442', '1299335', '3006781', '26352445');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1868933', '让娜·迪尔曼', '剧情', '《让娜·迪尔曼》是一部怎样的电影呢？它是阿克曼1975年的一部长达三个半小时的电影，它又是一部著名的“女权主义”电影，它还是一部在形式与内容上都极富革命精神的电影。总之，阿克曼这位拍片数极少的比利时女导演凭借她二十出头拍出的这部电影，就足以让无数的影评人、电影史学家为她 树碑立传了。它的独特、先锋已远远超出了我们的想象，我相信，以前没有，以后也不会再有如此奇妙的观影体验了！影片内容用一句话就可以概括：一个中年寡妇三天的日常生活（影片其实是从第一天下午到第三天的下午，仔细算下来也就两天多一点），影片的拍摄手法也十分“简单”——固定长镜头（影片中的机位选择非常严格，比如说厨房是正面、侧面两个机位，算下来全片也就只有十几个机位），影片场景同样十分“单调”——超过90%是在让娜?迪尔曼所住的公寓里拍摄的。', '德菲因·塞里格', '香特尔·阿克曼', 8.8, 6234, 'tt0073198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506409538.jpg', 0.6, 1.2, 8.5, 36.8, 53, '0.144193,-0.154577,-0.510310,0.675137,0.295755,-0.086185,0.702412,-0.168265,-0.318950,-0.221307,0.246014,0.743470,-0.449535,0.166538,0.028017,-0.010499,-0.424279,-0.363303,-0.198939,-0.178380,-0.228035,-0.303014,-0.243495,-0.070308,0.017738,-0.288588,0.546197,-0.026915,-0.548998,0.039793,0.178894,-0.232261,0.281248,0.168056,-0.022272,-0.002489,-0.180026,-0.180073,-0.061943,0.394439,0.331827,-0.264012,-0.273908,0.200424,-0.142017,0.345189,0.712422,-0.112236,-0.440610,0.427866,0.696496,-0.119249,-0.349249,-0.056776,0.208522,-0.081706,0.518854,0.180847,-0.201635,0.344847,-0.324240,-0.109135,-1.166990,0.104244,-0.162701,-0.027699,-0.417070,0.369508,-0.060020,-0.195538,0.126452,-0.391854,0.060766,0.043650,0.261056,0.373732,-0.191844,-0.373482,-0.561824,0.570941,0.537120,0.393425,-0.412177,0.802585,-0.114287,-0.742503,-0.405777,-0.435167,-0.294353,0.386800,0.206047,-0.202999,-0.177306,-0.296636,-0.535921,0.323332,-0.094945,-0.662370,-0.030460,-0.386055,0.259517,-0.849401,-0.124693,-0.500758,-0.352478,-0.164534,0.310743,-0.349297,1.033892,-0.491533,0.011739,0.436099,0.124964,-0.311081,0.924602,0.031891,-0.100158,0.100152,0.235443,-0.205912,0.004286,0.196694,0.273818,0.587374,0.224261,-0.457126,-0.513934,0.759213', '3318306', '2027945', '27602116', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1870044', '波拉特', '喜剧', '电影用讽刺癫狂的手段，展现了哈萨克主播波拉特（萨莎·拜伦·科恩 Sacha Baron Cohen 饰）到美国的一场“文化之旅”。波拉特在哈萨克国内是个排名第六的主持人，擅长用粗俗搞笑的桥段吸引观众眼球。他的家人也有点儿“怪”，妹妹还获得“风尘小姐”的第四名。就是这样一个主持人，被派去了美国进行文化学习，并拍回来一部纪录片。波拉特和制片人在人们的欢送下来到了光怪陆离的美国。他开始学习美国的礼仪，接触美国的文化，然而却处处碰壁，处处闹出笑话。这天波拉特在电视上看到心中的美丽女神，心驰神往，甚至忘记了此行任务……能否学成归国，对于乐不思蜀的波拉特还是未知数呢。©豆瓣', '萨莎·拜伦·科恩', '拉里·查尔斯', 7.4, 53440, 'tt0443453', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2499955827.jpg', 2.4, 5.7, 30.8, 41, 20, '0.551830,0.187144,-0.424268,0.651989,0.013412,-0.303964,0.539858,0.095474,-0.437420,-0.051276,0.008842,0.666867,-0.440199,0.071482,0.231420,0.136385,-0.393830,-0.606952,0.143449,0.033828,0.208118,-0.251753,-0.163625,0.051980,-0.131619,-0.471857,0.434292,-0.013950,-0.335766,0.390450,0.231689,0.219314,0.130523,0.334263,-0.178258,0.048765,-0.042719,-0.179856,-0.173956,0.257925,0.044723,-0.230212,-0.351500,0.279684,-0.038078,0.312089,0.494898,0.051447,0.147158,0.202240,0.569270,-0.309648,-0.157132,0.350776,0.269762,-0.292529,0.108687,0.044213,0.134977,0.246774,0.052470,0.020248,-0.695377,0.117711,0.076157,0.253833,-0.625255,0.421474,-0.103112,-0.117660,-0.102047,-0.296143,0.073299,0.088733,0.071671,0.525764,-0.084831,0.026046,-0.290192,0.257273,0.574364,-0.034175,-0.332097,0.288314,0.032519,-0.593451,-0.043152,-0.406978,-0.287171,0.120206,0.250782,-0.265635,-0.027888,0.191681,-0.957551,0.216847,-0.089798,-0.573400,-0.297371,-0.368261,-0.004242,-0.977293,-0.132987,-0.399917,-0.354958,-0.055879,0.433946,-0.295007,0.784275,-0.705589,-0.112966,0.640579,0.132244,-0.265041,0.589755,0.323428,-0.160717,0.043897,-0.410821,0.002431,-0.204560,0.276567,-0.106299,0.605257,0.105498,-0.368736,-0.153600,0.564587', '19965431', '3318306', '10763928', '20283482');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1870128', '攻壳机动队SSS', '动作', '独裁国家统治者——西亚古共和国将军卡路玛，在国家解体之际之时准备前往日本政治避难，在此期间他发表了制造恐怖活动的声明。多年过去，卡路玛麾下以卡盖鲁大佐等为首的一群身上文有“梵”字的特工接连自杀。而在他们死之前，几乎每个人都留下了绰号为“傀儡师”的黑客即将到来的讯息。近两年不断壮大的公安九课受命调查此事，经过户草和巴特的层层追查，发现少佐也涉足其中。而随着调查的深入，近年多起诱拐案件、逐渐凸现的贵腐老人现象甚至日本一些重要部门也都与傀儡师的案件有关。揭去重重迷雾，骇然的真相慢慢浮出水面……本片根据士郎正宗的同名原著改编。©豆瓣', '田中敦子', '神山健治', 8.9, 13967, 'tt0856797', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2552602870.jpg', 0.3, 0.7, 9.1, 33.2, 56.6, '0.159428,-0.064162,-0.712605,0.605609,0.118021,-0.046754,0.268426,-0.085103,-0.558084,-0.397890,0.136931,0.561908,-0.124045,-0.116760,0.092496,-0.294136,-0.342913,-0.794975,-0.266192,-0.424663,-0.400603,-0.422794,-0.250747,-0.344070,-0.175272,-0.398324,0.720362,0.293661,-0.204797,0.189642,0.160587,0.322418,-0.500138,0.308094,0.286114,-0.059764,0.379859,-0.262535,-0.335430,0.033046,-0.074027,-0.269040,-0.049193,0.045888,-0.074405,0.577377,0.529107,-0.339162,-0.232431,-0.270484,0.378784,-0.336735,0.033754,-0.173004,0.581106,0.384818,0.217224,0.663609,-0.013181,-0.242337,-0.209446,0.003365,-0.638442,-0.023958,0.212767,0.238021,-0.383279,0.104301,-0.159144,0.176730,-0.038786,-0.254968,0.377917,0.701004,0.166523,0.135831,-0.044104,0.143015,-0.187032,0.346326,0.428248,0.142554,-0.308141,-0.156651,-0.039286,-0.311708,-0.062076,-0.249444,0.251572,-0.046790,0.232729,0.066370,-0.017196,0.502305,-0.399370,0.004893,-0.325627,-0.312689,0.084409,-0.077011,-0.035224,-0.657329,-0.130633,-0.007830,-0.084450,0.098931,0.206450,0.004275,0.650421,-0.472650,0.167774,0.520156,0.274238,-0.532846,0.279564,-0.130674,-0.098836,-0.223324,-0.267697,0.113102,0.458797,0.395962,0.004128,0.234436,0.033701,-0.323189,-0.287437,0.032678', '25723905', '10463953', '26328483', '1298104');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1870681', '冲浪企鹅', '喜剧', '“大Z”吉克（杰夫·布里吉斯 Jeff Bridges 配音）是企鹅世界最知名的冲浪选手，他有着光辉成绩，又在十年前消失在一次比赛里，因此成为传奇，他的故事激励了一代又一代小企鹅继承冲浪事业，科迪（希亚·拉博夫 Shia LaBeouf 配音）就是其中最痴迷的一个，他从小就立志走出小镇，也的确凭自己的努力和天赋，得到经纪人长腿鸟（马里奥·坎东尼 Mario Cantone 配音）和矮熊老板（詹姆斯·伍兹 James Woods 配音）的支持，带他进入世界级冲浪比赛赛场——夏威夷岛。在那里，科迪遇见了一个蔑视“大Z”的傲慢选手“坦克”（狄尔里奇·巴德 Diedrich Bader 配音），为维护偶像向他提出挑战，还遇到美丽的救生企鹅兰妮（佐伊·丹斯切尔 Zooey Deschanel 配音），梦想和爱情，一起摆在年轻科迪的面前……©豆瓣', '希亚·拉博夫', '艾什·布兰农', 7.2, 12018, 'tt0423294', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1572777165.jpg', 0.6, 4.7, 41.1, 40, 13.6, '-0.071813,-0.130237,-0.536502,0.821750,-0.276203,-0.351913,0.371990,0.109239,-0.135836,-0.140321,0.347761,1.059897,-0.170507,0.229007,0.260614,0.040758,-0.160558,-0.525163,0.150130,-0.106916,-0.029774,-0.364882,-0.414325,-0.021944,0.074567,-0.443443,0.795133,-0.203572,-0.316843,0.459587,0.466070,-0.040199,0.180220,0.081610,-0.090563,0.008490,0.467383,-0.017938,-0.184258,0.333631,-0.211618,0.224872,-0.107488,-0.030126,0.236490,-0.057234,0.353566,-0.127077,0.172226,-0.139817,0.225804,-0.145601,-0.034509,-0.025966,0.278815,-0.035550,0.211080,0.072123,0.106036,0.074162,-0.092835,-0.275910,-0.789993,-0.010612,-0.196178,0.219848,-0.603743,0.516105,-0.049679,-0.237622,0.354011,-0.150609,-0.122346,-0.088049,0.328916,0.422566,-0.106993,0.323768,-0.323537,0.082670,0.306161,0.129024,-0.269440,0.313089,-0.026678,-0.454142,0.008684,-0.359502,-0.420050,-0.127936,0.244992,-0.336541,-0.047576,0.337711,-0.513541,0.334646,-0.132973,-0.386549,0.133641,-0.326709,-0.088581,-0.740587,0.101626,-0.125335,-0.263448,-0.075348,0.140365,-0.455668,1.150579,-0.817411,0.212533,0.449521,0.262118,-0.160903,0.726141,0.202043,0.107830,-0.225201,-0.143766,0.317006,-0.088367,0.123903,-0.218386,0.251325,-0.120349,-0.237308,-0.574785,0.840179', '27602116', '25880986', '3882427', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1870682', '街舞少年', '剧情', '有舞王之称的DJ·威廉斯（哥伦布·绍特 Columbus Short 饰）就刚刚经历了一场因为飙舞而引起的社团争斗，他一直呵护的弟弟在这场流血事件中意外丧生。身心俱疲的他来自洛杉矶，到来亚特兰大一所黑人学校进修。在新环境里感到非常不适应的他，自从加入了一个街舞爱好者同盟会之后，生活开始有了翻天覆地的变化。他的出众舞技在这里得到施展，同盟的人在景仰之余，都期待他能帮助同盟会夺取大家垂涎已久的全国街舞大赛冠军。然而他们不知道的事，纵然有出神入化的舞技，在成为同盟会最有竞争力的主心骨之前，DJ必须面对的是如何抛开残酷的往事带给他的种种阴影。DJ是否能够重新站起身来，正视前方的道路，在这条自己曾经深深热爱的街舞道路上勇往直前呢？©豆瓣', '哥伦布·绍特', 'Sylvain White', 7.3, 7696, 'tt0775539', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p710368355.jpg', 0.7, 4.8, 39.2, 41.1, 14.2, '0.206364,0.014782,-0.957088,0.569848,0.024535,-0.065552,0.480380,-0.073771,-0.706254,-0.165098,0.320308,0.749917,-0.098053,0.220488,0.213804,-0.267908,-0.252928,-0.805347,-0.021857,-0.277301,-0.419867,-0.226453,-0.468813,-0.188650,-0.197180,-0.309532,0.853524,0.308894,-0.494541,0.596891,0.237703,0.326018,0.197609,0.651074,-0.237976,-0.175833,0.222844,0.427153,-0.295004,0.085514,0.079954,-0.507556,-0.462202,0.385110,0.006832,0.153901,0.588849,-0.275272,-0.231692,-0.028484,0.436835,-0.412254,-0.045750,0.067313,0.357739,0.063737,-0.018061,0.210098,-0.158329,0.054768,-0.194264,-0.245202,-0.819606,-0.234593,0.228962,0.263175,-0.654160,0.567218,0.093724,-0.251076,0.200984,-0.154446,0.147816,0.372007,0.275324,0.204839,-0.054532,-0.005076,-0.516135,0.159756,1.198357,-0.042284,-0.351714,0.220907,-0.211174,-0.490359,-0.196212,-0.338312,-0.542177,0.012847,0.156272,0.128823,-0.083445,0.255139,-0.444709,0.174405,0.023139,-0.315310,-0.026111,-0.428461,-0.012596,-0.580233,-0.263107,-0.495928,-0.205715,-0.070254,-0.023545,-0.511501,0.968758,-1.178878,0.244000,0.459793,0.061480,-0.486546,0.689959,0.165792,0.182946,-0.233480,-0.345240,0.196451,-0.215075,0.248142,-0.151003,0.334377,0.027929,-0.080279,-0.391663,0.757356', '35030151', '25721544', '1301022', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1870801', '灰姑娘', '剧情', '贤秀（申世京）是做整容医生的母亲尹熙（道智苑）的掌上明珠，她虽对整形手术没有一点兴趣，一同在美术学院读书的好朋友却都热衷通过人工再造让自己变得更美丽，然而她们在被尹熙在手术台上改造过后，先后离奇地惨死，一时间贤秀和母亲陷入恐慌中。最好的朋友盛恩（安圭莲）完好无损，成为贤秀最大的安慰。贤秀偶然闯进家中禁地地下仓库，发现一张非常恐怖的小孩照片，令起萌生揭出母亲所藏秘密的想法，慢慢地，疑问有了答案，她和母亲也渐被逼到角落。©豆瓣', '申世京', '奉万大', 6.2, 10768, 'tt0845442', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1249046459.jpg', 1.9, 13.8, 59.3, 20.3, 4.8, '0.136141,-0.115725,-0.733975,0.379435,-0.115279,-0.180290,0.919802,-0.022271,-0.743380,-0.280678,0.214872,0.811475,-0.198956,0.192113,-0.059180,-0.076181,-0.209399,-0.463738,-0.057684,-0.257273,-0.207090,-0.628509,-0.172422,-0.192518,-0.069209,-0.384300,0.531795,0.049487,-0.274849,0.132289,0.015323,0.188644,-0.092170,0.553334,-0.079150,0.105264,0.046182,0.223404,-0.081829,0.213570,0.043584,-0.413640,-0.157495,0.265139,-0.090718,0.365205,0.629977,-0.146458,-0.336906,0.040575,0.182345,-0.169305,-0.238533,0.170486,0.236546,-0.046527,0.303344,0.151144,-0.403038,-0.163158,0.212079,0.001669,-0.623854,-0.067856,0.439224,0.205512,-0.508697,0.541619,0.026500,-0.028029,0.287472,-0.343696,0.399266,0.174941,0.082063,0.491933,-0.374416,0.155183,-0.318987,0.169755,0.500545,0.046804,0.024458,0.384830,-0.399328,-0.437491,0.159376,-0.203360,-0.439113,0.065906,0.132710,0.257202,-0.377710,0.225451,-0.300209,-0.043135,-0.114223,-0.057760,-0.033712,-0.439051,-0.006400,-0.285860,-0.101694,-0.094022,-0.316645,-0.042269,-0.066010,-0.414080,0.773591,-0.682586,0.353469,0.198625,0.292962,-0.377226,0.504749,0.047005,0.006437,-0.226595,-0.142549,0.298404,0.088612,0.278965,0.123182,0.167386,-0.062084,-0.076170,-0.630709,0.350456', '4724586', '25723780', '3111650', '1908318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1871220', '霹雳先锋', '喜剧', '华探长张铁柱（李修贤 饰）打拼十几年才有了探长地位，此人嫉恶如仇不事逢迎，与新任督察罗Sir多有摩擦，辛苦破案结果反被后者刁难。另一方面，悍匪“法官”（成奎安 饰）一伙购枪策划大行动，偷车贼伟仔（周星驰 饰）被法官收为外围助手，向其提供犯罪用车。法官与手下狂牛（黄光亮 饰）和鸡翼( 何家驹 饰)等人洗劫赌档，同一天伟仔因偷车嫌疑被张铁柱抓捕入监，赌档事发，罗Sir不顾张铁柱作证将伟仔定为嫌疑人，令张与伟仔二人大为不满。张铁柱将伟仔释放，同时要求伟仔合作抓捕法官一伙。购入武器的法官一伙战力大增，行事愈发嚣张，与其他帮派当街火并，伟仔被卷入杀人案件，只得配合张铁柱，一警一贼终于开始合作……©豆瓣', '李修贤', '黄柏文', 7.3, 15769, 'tt0126301', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2347547076.jpg', 0.5, 3.8, 43.9, 35.7, 16.1, '-0.011341,-0.395836,-0.405195,0.327145,-0.001726,-0.121821,0.346990,0.240014,-0.510659,-0.293497,0.274151,0.270909,-0.451930,-0.176136,0.172254,-0.513797,-0.212012,-0.619662,-0.276955,0.102171,0.003467,-0.541694,0.065944,-0.427534,-0.203795,0.093412,0.203675,-0.124092,-0.450959,0.456591,0.636286,0.387628,-0.391820,0.165111,0.081613,-0.041846,0.372029,-0.197620,-0.449366,-0.066929,-0.111450,-0.312498,-0.002805,-0.322330,0.227734,0.438928,0.540782,0.022469,-0.236226,-0.362789,0.155672,-0.398441,0.107661,0.064886,0.616219,0.249954,0.048664,0.305116,-0.177629,-0.045271,0.124437,-0.144400,-0.461565,0.102665,0.253217,-0.130712,-0.236008,-0.054222,-0.122215,0.169648,-0.073151,-0.024266,-0.005184,0.306140,0.270932,-0.061716,0.343568,-0.027793,-0.398250,0.074922,0.507237,-0.053418,0.183574,-0.360446,-0.014371,-0.382903,0.144028,-0.158630,-0.044195,-0.161626,0.487372,-0.246374,0.305572,0.156174,-0.282394,-0.278944,-0.232452,0.290944,-0.175574,-0.061405,0.323357,-0.717352,-0.111303,-0.174722,-0.071310,0.207418,0.240668,-0.164987,0.356429,-0.457975,-0.230809,0.040322,0.504235,-0.703403,0.168040,0.145649,0.132938,-0.423168,-0.232748,-0.262104,0.647298,0.133648,0.462120,-0.024881,-0.096742,-0.298544,0.193396,-0.312317', '26996640', '1293854', '1780428', '1303269');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1871800', '惩罚者2：战争特区', '剧情', '前FBI探员弗兰克卡（雷·史蒂文森Ray Stevenson 饰）在黑帮杀掉妻儿之后走向了黑暗复仇的不归路。成为这个城市里隐秘的“惩罚者”，令城内不少罪犯闻风丧胆，而他穿着代表惩罚者的骷髅制服，穿梭在这个充满罪恶的都市中。一名新崛起的黑帮份子比利（多米尼克·威斯特 Dominic West 饰）开始向惩罚者叫嚣，并且还要统领城内各大帮派。可一番激斗之后，比利最终还是败在惩罚者的枪下。不过若干时日之后，一位名叫疯人吉姆（道格·休切逊 Doug Hutchison 饰）的神秘人现身城内，他不但有着和比利一样信念，而且他的手法更离谱——他不但要统一黑帮，还要干掉其他帮派的黑帮头目，做城内真正的寡头老大，甚至他还向惩罚者下了挑战书，要将他置于死地！惩罚者在追查的过程中，渐渐发现了吉姆的真实身份，这令他大吃一惊……©豆瓣', '雷·史蒂文森', '莱克茜·亚历山大', 6.6, 13536, 'tt0450314', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p776536259.jpg', 2, 10.4, 52.3, 26.5, 8.8, '0.074857,0.188580,-0.580741,0.580737,0.031943,-0.075769,0.764259,-0.023940,-0.471652,-0.149844,0.316082,0.659971,0.077362,0.105216,0.303690,-0.150126,-0.436581,-0.756665,-0.290951,-0.253143,-0.356024,-0.257871,-0.513534,-0.236840,-0.101177,-0.192284,0.490513,0.370153,-0.195681,0.237553,0.487566,0.413534,-0.086904,0.336890,-0.258828,-0.019799,0.315624,-0.441942,-0.246924,0.230826,-0.060426,-0.210746,-0.157118,0.313780,-0.039086,0.341999,0.507393,-0.286304,0.018768,-0.219318,0.203458,-0.254415,-0.158760,0.124072,0.293614,-0.068343,0.104292,0.215593,0.065795,0.063769,0.011381,0.026688,-0.947269,0.065306,0.180717,0.298093,-0.666688,0.213742,-0.128198,0.201896,-0.008067,-0.250715,0.077376,0.128656,0.242844,0.082986,-0.059314,-0.034836,-0.651905,0.077947,0.607366,0.023599,-0.236216,-0.200143,0.119690,-0.385877,-0.310061,-0.204141,-0.223984,-0.230309,0.533168,-0.152313,-0.018133,0.424343,-0.747851,-0.129546,-0.244536,-0.210929,-0.136121,-0.212194,-0.246316,-0.604438,-0.081389,-0.328975,-0.146836,0.130744,0.106190,-0.015951,0.628079,-0.676815,0.039271,0.549321,0.340721,-0.468034,0.316017,-0.007179,0.257403,0.050733,-0.364979,0.059261,0.605362,0.524293,0.113543,0.359715,-0.165588,-0.446587,-0.179791,0.367023', '1793491', '26747274', '25828589', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1871817', '历史系男生', '剧情', '这是一群高智商男生们的故事。二十世纪八十年代，英国北部的一所男子中学里，八个高中生正积极准备着牛津和剑桥大学的招生考试。这几个男生性格各异。有万人迷，自视甚高的Dakin（多米尼克•库珀 Dominic Cooper 饰）；有四肢发达头脑不简单的Rudge（拉塞尔•托维 Russell Tovey 饰）等。他们对课本对知识有属于自己的解读。教他们文学的是个肥胖，教学方式独特的怪老头Hector（理查德•格雷弗斯 Richard Griffiths饰），他主张学生通过课本获得情感上的共鸣和享受，而不是单纯为了升学而读。与他教学模式相反的则是学校新聘请的老师Tom（斯蒂芬•坎贝尔•莫尔 Stephen Campbell Moore 饰）。Tom的目标则是协助这些孩子尽可能考上牛津或剑桥。两种老师的两种教学模式，究竟孰优孰劣，或许并没有一个标准答案。©豆瓣', '塞缪尔·安德森', '尼古拉斯·希特纳', 8.2, 21086, 'tt0464049', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p454017789.jpg', 0.4, 2, 19.3, 45.4, 32.9, '0.776633,-0.408408,-0.269281,0.848094,-0.302990,-0.142097,0.662626,-0.082792,-0.424916,-0.538469,-0.055018,0.625324,0.233105,0.343121,-0.013254,-0.131121,-0.275139,-0.641013,-0.127090,-0.154631,-0.257548,-0.764976,-0.365961,-0.034579,-0.099589,-0.255622,0.592022,-0.288058,-0.350425,0.499174,0.237355,0.475382,0.278104,-0.051951,-0.190163,-0.291340,0.073310,0.105802,0.081466,0.014582,0.158149,0.152664,-0.253903,-0.142380,0.123663,0.347347,0.731966,-0.047560,0.099543,-0.112307,0.464783,-0.154954,-0.304015,0.346010,0.248596,-0.037616,0.228956,0.085931,0.228301,0.253705,-0.125878,-0.265784,-0.764058,-0.192987,0.254033,0.333800,-0.362455,0.581981,-0.025568,-0.480819,0.090610,-0.281166,-0.238453,0.223637,0.283359,0.478749,0.161958,-0.167830,-0.371337,0.210768,0.433629,0.101355,-0.381129,0.107049,-0.556476,-0.550082,0.092306,-0.126572,-0.534216,-0.001427,0.040045,-0.070642,0.042963,-0.083658,-0.461271,0.192053,-0.003215,-0.141423,-0.055731,-0.498752,0.047491,-0.643484,0.213172,-0.489072,-0.403778,-0.209992,0.169044,-0.239466,1.149869,-1.029058,-0.102592,0.354441,0.187041,-0.440684,0.823099,0.133144,0.081389,-0.369359,-0.303375,-0.136574,0.002963,0.015592,-0.317233,0.947695,0.384919,-0.479281,-0.242248,0.731264', '25922902', '27602116', '3811356', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1871836', '三十极夜', '惊悚', '在美国阿拉斯加最北边的极地圈内，偏僻的小镇巴罗每年有三十天的极夜，在这三十天里。小镇居民将忍受漫长的黑夜才能重见光明。又一个极夜来临时，陌生流浪汉（本•福斯特 饰） 的到来，打破了小镇宁静的生活。小镇治安官伊本（乔什•哈奈特 饰）得之，以强悍狡猾的马洛(丹尼•哈斯顿 饰)为首的二十名吸血鬼，将偷袭本镇，没有迁徙到南方的居民们即将大祸临头。身为一镇之主的伊本临危受命，不得不带领镇上的剩下的老弱病残和凶残暴戾的吸血鬼们周璇；而且他自己和妻子斯泰拉（梅丽莎•乔治 饰）的关系也一直貌合神离，夫妻感情濒临破裂。种种问题堆积在一起，伊本能够完成这个几乎不可能的任务吗？©豆瓣', '乔什·哈奈特', '大卫·斯雷德', 6.4, 14900, 'tt0389722', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1305774575.jpg', 2.5, 12.9, 51.8, 25.6, 7.1, '0.397159,0.013650,-0.718563,0.679245,-0.091520,-0.066819,0.662040,0.147901,-0.335617,-0.451426,0.332679,0.753746,0.008883,0.069661,0.220709,0.007506,-0.116089,-0.433665,-0.258787,-0.419651,-0.315626,-0.306088,-0.499954,-0.340347,-0.176542,-0.225698,0.398785,0.297362,0.192437,0.391617,0.162849,0.388147,0.073709,0.333200,-0.444513,-0.126630,0.171408,-0.291185,-0.159517,0.242314,-0.224289,0.115890,-0.153560,0.203192,0.183270,0.499104,0.585131,-0.345766,-0.097613,-0.104190,0.198003,-0.333562,-0.026445,0.127275,0.536557,-0.409574,0.162547,0.267545,-0.290301,0.020951,0.033373,-0.122341,-0.741952,0.057727,0.071987,0.181655,-0.471940,0.448510,0.072163,-0.331133,0.053282,-0.178077,0.164105,0.537317,0.056986,0.481023,0.121152,-0.094520,-0.507319,0.034775,0.720884,-0.159250,-0.542146,0.099551,-0.282108,-0.614113,0.007661,-0.361000,-0.508092,-0.178195,0.224871,-0.096161,-0.214044,0.348387,-0.782072,0.145481,-0.220149,-0.306562,-0.146952,-0.106894,-0.287962,-0.773317,-0.061173,-0.495708,-0.130722,0.222455,0.104706,0.157400,0.594504,-0.652533,0.197613,0.493520,0.352081,-0.288527,0.411987,0.141319,0.313998,-0.057501,-0.102755,0.410142,0.140594,0.518670,0.211523,0.275636,-0.271136,-0.106813,-0.522949,0.691763', '34461680', '4924694', '10440138', '1416898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1871840', '新丧尸出笼', '动作', '美国科罗拉多一个名叫里德维尔的小镇，一种神秘病毒蔓延其中。为防止病毒蔓延，政府派出部队严防当地居民离开小镇，镇上的医院则人满为患。下士莎拉•伯曼（Mena Suvari 饰）和大兵巴德（Stark Sands 饰）带着她生病的母亲去医院，谁知医院内的患者突然转化成凶残无比、嗜血如命的恐怖僵尸。它们四处攻击为感染者，所有被咬过的人很快也变成僵尸的同类。莎拉和同伴迅速跳上吉普逃亡，却偶然从无线电台中得知她的弟弟特瑞沃（Michael Welch 饰）被困在某栋建筑里的消息。为了救唯一的弟弟，莎拉和同伴再次杀入血肉横飞的僵尸群中……©豆瓣', '米娜·苏瓦丽', '史蒂夫·迈纳', 6.5, 18069, 'tt0489018', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1439880843.jpg', 2, 10.7, 54.2, 25.5, 7.5, '0.164878,-0.193810,-0.655599,0.491007,-0.044143,0.042491,1.090526,-0.096803,-0.417511,-0.139656,0.293043,0.704645,0.002726,0.118884,0.081943,0.052100,-0.188644,-0.224065,-0.337802,-0.065843,-0.561831,0.060708,-0.488600,-0.362417,0.246613,-0.281671,0.433980,0.190573,-0.111515,0.649173,-0.006468,0.711924,-0.495369,0.480351,-0.073026,0.049526,-0.010189,-0.371549,-0.022546,0.294432,0.028120,-0.128613,0.087395,0.038115,-0.094073,0.307708,0.886430,-0.284811,0.179024,-0.502637,-0.032137,-0.236813,0.107562,0.136342,0.407083,-0.040403,0.507510,-0.102294,-0.127828,-0.034124,-0.019920,0.151041,-0.510622,-0.027491,0.080789,0.124647,-0.436949,0.203291,-0.211560,0.084477,0.349374,-0.276234,0.236815,0.094443,-0.221962,0.481820,-0.296458,-0.102134,-0.563718,-0.135453,0.507105,-0.376559,-0.180054,-0.072488,-0.241826,-0.398391,0.303529,-0.075286,-0.216335,-0.164866,0.293148,0.082741,-0.415436,0.275258,-0.713399,-0.000123,-0.439919,-0.344750,-0.204560,0.071540,-0.453029,-0.777621,0.186022,0.036656,0.072115,0.010711,-0.136712,0.277691,0.434023,-0.610670,0.324322,0.482884,0.468305,-0.453057,0.407361,-0.413350,0.220209,0.078426,-0.211810,0.342488,0.488277,0.734120,0.147730,0.259346,-0.296497,-0.283711,-0.372658,0.538139', '20451118', '21619567', '10466639', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1872133', '三峡好人', '剧情', '三峡建设工作正在进行中的奉节县城，迎来一男一女两个山西人。男人韩三明（韩三明 饰）来自汾阳，是名忠厚老实的煤矿工人，来奉节为寻十六年未见的前妻。前妻是他当年用钱买来的，生完孩子后跑回了奉节。寻找前妻的过程中波折不断，韩三明决定留下来做苦力一直等到前妻出现。女人沈红（赵 涛 饰）来自太原，是名沉默寡言的护士，为寻多日不曾与自己联系的丈夫而来奉节。丈夫与她的夫妻关系早已是有名无实，这点她虽然深知，仍想让丈夫当面给她个说法。沈红的找寻过程也不是一帆风顺，丈夫在有意无意地躲着她。韩三明和沈红虽不认识，却因为要做相对意义上的“拿起”与“舍弃”抉择，在冥冥之中有了某种神秘的联系。本片荣获2006年第63届威尼斯国际电影节金狮奖。©豆瓣', '赵涛', '贾樟柯', 8.4, 129155, 'tt0859765', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p520162740.jpg', 0.3, 1.2, 14.7, 47.5, 36.2, '0.103939,-0.060124,-0.608024,0.664297,-0.264275,-0.233225,0.569292,0.128573,-0.810057,-0.428777,-0.236092,0.638633,-0.063163,0.266528,0.082164,0.033875,-0.052350,-0.734582,-0.003820,-0.220286,-0.180421,-0.453416,-0.059703,-0.050870,-0.268850,-0.008841,0.400552,0.058961,-0.167575,0.346706,0.516388,0.266413,-0.203012,0.691969,-0.313535,-0.013771,-0.191960,0.255585,-0.346723,0.391597,0.256707,-0.326612,-0.108226,-0.025278,0.119513,0.604688,0.537058,-0.032622,0.002222,-0.175519,0.220760,-0.190599,0.005082,0.105042,0.309057,-0.026487,0.087693,0.296954,-0.278954,-0.099107,0.244370,-0.330799,-0.596687,-0.077791,0.314839,0.227267,-0.868492,0.328123,-0.025975,0.041124,0.007947,-0.342881,0.391925,0.477600,0.122040,0.332261,0.026014,0.017824,-0.400296,0.451302,0.737033,0.147526,-0.022691,0.245602,0.006410,-0.480727,0.161779,-0.212716,-0.581313,0.087531,0.077154,-0.005441,-0.058803,-0.087468,-0.306060,0.013723,-0.060829,-0.027288,0.202623,-0.408986,0.019469,-0.256530,-0.046478,-0.649948,-0.101440,0.087015,0.072462,-0.399409,0.556455,-0.901663,0.225887,0.310044,0.430156,-0.662975,0.694936,0.349755,0.139728,-0.538790,0.242918,0.061643,-0.106178,0.255137,0.012416,0.087773,-0.105209,-0.049439,-0.346328,0.336049', '1301022', '1308805', '35030151', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1872272', '美国田园下的罪恶', '剧情', '本片根据1965年美国印第安纳波利斯的真实案件改编而成。女孩西尔维亚（艾伦•佩姬 Ellen Page 饰）因游乐园工作的父母事务繁忙，与妹妹简妮（哈蕾•麦克法兰 Hayley McFarland 饰）搬入育有七子女的单亲母亲格特鲁德•巴尼泽夫斯基（凯瑟琳•基纳 Catherine Keener 饰）家暂住。格特鲁德的大女儿宝拉（阿丽•葛雷勒 Ari Graynor 饰）未婚先孕，西尔维亚无意中听到这一消息，失口告知同学，没想消息泄露。宝拉迁怒西尔维亚，致使其被格特鲁德体罚。这之后，酗酒成性的格特鲁德将一切家庭问题均归于西尔维亚的到来，背着镇上人将她囚于地下室，并怂恿子女用酷刑折磨西尔维亚。不仅如此，镇上其他儿童也参与到这残酷的摧残中，共同实施了美国历史上针对个人犯下的最严重的罪行之一。凯瑟琳•基纳因此片被提名2008年艾米奖与金球奖最佳女主角。©豆瓣', '艾利奥特·佩吉', '汤米·奥·哈沃', 8.3, 40864, 'tt0802948', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1010310013.jpg', 0.5, 1.2, 15, 50.7, 32.5, '0.174337,-0.116192,-0.573365,0.311080,0.114964,-0.106788,0.606275,-0.010214,-0.654723,-0.449282,-0.127678,0.621528,-0.282707,0.229995,0.500344,0.169387,-0.425559,-0.522984,-0.000012,-0.193051,-0.277567,-0.635607,-0.013238,-0.345992,-0.138731,-0.338819,0.281321,-0.100372,-0.155138,0.381512,0.306136,0.478016,-0.182948,0.010520,0.226241,0.237424,0.212821,0.023910,-0.297400,0.080145,-0.019415,-0.309936,-0.022687,0.232836,0.240525,0.406573,0.650615,-0.346800,0.093746,-0.340920,0.352868,-0.160458,-0.100764,0.184650,0.369397,-0.068968,0.377446,0.532018,-0.307960,-0.172044,0.164255,-0.292938,-0.562846,-0.069991,0.314160,0.060726,-0.308732,0.261313,-0.239020,0.051610,-0.075204,-0.053601,0.190073,0.337533,0.064042,0.211619,-0.189002,-0.123116,-0.159977,0.419176,0.373441,-0.271677,-0.168972,0.001560,-0.357764,-0.290888,0.244126,-0.512371,-0.375237,0.244566,0.160359,0.219786,-0.148876,0.480684,-0.276636,-0.232823,-0.370746,-0.241422,0.033226,-0.215841,-0.207171,-0.545788,0.002259,-0.280196,-0.282606,-0.047121,0.146944,-0.128758,0.519691,-0.437925,0.279346,0.355222,0.280259,-0.547846,0.418592,-0.041207,0.571175,-0.182331,-0.231963,0.402266,0.175773,-0.030930,0.089631,0.039925,-0.016671,-0.331068,-0.237110,0.211122', '26684564', '1465415', '1297735', '1296217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1873535', '千禧曼波', '剧情', '年轻生命的消耗像是一首风驰电掣的摇滚乐，以热情洋溢的节奏，疯狂起始，然後又在某个浑然忘我的时刻，曳然而止。电音感官的放纵、暗夜生涯的浪荡、过渡爱情的沈沦、江湖义气的不归路，都是多少热血灵魂曾经走过的无悔无憾。一个年轻女孩活在她自己的异世界里，写着虚幻颠簸的年轻故事。迷幻的时序，跳跃的空间，所有事件都在若有似无的混沌里进行。女孩名叫Vicky(舒淇 饰)，带着五十万存款，跟小她两岁的双鱼座男小豪(段钧豪 饰)拍拖。小豪是无业游民，以极度自私的方式爱着Vicky。他精准计算着她下班回家的时间，检查她的各种帐单与手机通话记录，并且嗅窥她身上的气味，然後在发现不寻常的蛛丝马迹之後，歇斯底里地发怒，让猜疑迷惑了年轻冲动的心智。两人这样互相折磨着，不平衡的恋情难以长久。Vicky为了养小豪而在酒店当公关，她有一群玩伴，带她在PUB里认识了捷哥。捷哥年长而成熟，他们在一起像是大哥骄纵着小妹。Vicky开始觉得她需要到另一个世界，於是在一个苍白的日子里，她想要离开，离开小豪，离开这个岛屿的不安，她想要逃得远远的...', '舒淇', '侯孝贤', 7.2, 28053, 'tt0283283', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1030632720.jpg', 0.6, 5.1, 39.9, 39.8, 14.5, '0.307227,0.259053,-0.878627,0.629758,-0.425557,-0.145712,1.049204,0.120776,-0.341676,-0.209486,0.163347,0.592185,-0.030764,0.405552,-0.005488,0.066973,-0.061974,-0.684437,-0.180734,-0.129562,-0.165170,-0.271577,-0.298182,-0.091301,-0.107249,-0.354728,0.455830,0.158762,-0.184734,0.399610,0.211056,-0.033251,-0.220104,0.529663,-0.532141,-0.071845,-0.162655,-0.026105,-0.083538,-0.069840,0.214364,-0.209434,-0.249994,0.210928,-0.303413,0.360068,0.811044,-0.185475,-0.218846,0.125640,0.460765,-0.174823,-0.187848,0.072308,0.030405,0.169679,0.211866,-0.066164,-0.139485,0.268502,0.007385,0.052664,-0.788130,0.004314,0.003820,0.461519,-0.531177,0.444066,-0.104701,-0.193122,0.205530,-0.295599,0.003021,0.077924,0.142173,0.516800,-0.294547,-0.001234,-0.534289,0.095276,0.519848,-0.041310,-0.486301,0.626724,-0.310017,-0.405996,-0.098759,-0.229397,-0.730349,-0.291475,0.297538,0.050269,-0.372040,0.228590,-0.600026,0.321897,0.055465,-0.088787,-0.307610,-0.399898,-0.310753,-0.309422,-0.275234,-0.703915,-0.364927,0.168633,0.127479,-0.284915,0.826330,-0.751378,0.245711,0.833039,0.250370,-0.568719,0.643431,0.194257,-0.135391,-0.065080,0.025432,0.429194,-0.270028,0.392454,