INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1873750', '地狱男爵2：黄金军团', '动作', '人间与地狱，自古订下了休战契约，只要契约一日无人逾越，地狱邪魔便不能作怪。千百年来，两界一直相安无事。然而，地狱之中，一股酝酿已久的邪恶势力悄然蓄势待发......能够行走于天地两界的暴君弩阿达王子（鲁克·高斯 Luke Goss 饰），妄图用鲜血唤醒无敌的魔兽军团，用地狱之火焚烧人间。在他的血的召唤下，地狱深处蛰伏已久的魔兽们纷纷冲出地底。面对无坚不摧的黄金军团，唯一能拯救人间免于堕入炼狱的，只有地狱男爵（朗·普尔曼 Ron Perlman 饰）。尽管身上流着恶魔的血，但早已皈依善良的红角撒旦，挺身而出站在了人类一边。他将同火焰女（塞尔玛·布莱尔 Selma Blair 饰）、鱼人（道格·琼斯 Doug Jones 饰）等“超自然研究发展局”的盟友一起，跨越阴阳两界屠魔，抵御人间浩劫！这一次男爵又会不会再次被邪恶本性蚕噬？©豆瓣', '朗·普尔曼', '吉尔莫·德尔·托罗', 6.9, 58567, 'tt0411477', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p456610958.jpg', 0.9, 6.5, 49, 33.6, 9.9, '0.191485,0.358190,-0.495631,0.462101,0.186798,0.113669,0.649946,-0.021376,-0.196928,0.093946,0.319325,0.633809,-0.076162,0.000221,-0.025865,-0.187947,0.008451,-0.553054,-0.283428,-0.055100,-0.279166,0.177934,-0.698270,0.153196,-0.155632,-0.379712,0.780249,0.282604,0.107029,0.029245,0.212199,0.604303,-0.394871,0.231818,-0.544593,-0.499239,-0.267637,0.073891,-0.148880,0.247630,-0.107037,0.063599,-0.041321,0.245517,-0.163314,-0.073313,0.357956,-1.118378,0.485317,-0.592485,0.145297,-0.376296,0.099971,0.202204,0.101616,-0.169682,0.248305,0.191149,0.166353,-0.042944,0.081960,-0.048225,-0.723705,-0.379101,-0.191912,0.164072,-0.176150,0.174006,0.193267,0.125006,0.227550,-0.058681,0.078214,0.046737,0.467323,0.321630,-0.150706,-0.449514,-0.443332,-0.126253,0.630934,-0.309776,-0.623063,-0.059596,-0.106425,-0.497594,-0.227671,-0.226691,-0.333807,-0.424794,0.302238,0.511698,-0.119960,0.718985,-0.960971,-0.085383,-0.507297,0.147538,-0.106388,-0.176768,-0.230418,-0.382119,-0.479619,-0.012658,0.065572,0.253028,0.298392,0.219076,0.474402,-0.644245,0.401480,0.293607,0.407490,-0.083292,0.648738,-0.080368,0.112995,-0.159807,0.248139,0.581189,0.285971,0.663493,0.304263,0.271779,-0.037069,0.560737,-0.206671,0.484137', '25890017', '3213270', '2