INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1874704', '我嫁了个怪蜀黍！', '喜剧', '这部片可以是加了幽默的《Akira》，添了人情味的《RoadRunner》，动画版的《低俗小说》（Pulp Fiction）。一个关于一对新婚夫妇在新婚之夜发生的温馨故事。丈夫格兰特（Grant）突然得到奇异的超自然力量，与此同时妻子凯丽（Kerry）窘于应付。无论何时，只要Grant一想什么，就会变为现实，尽管他并不知道这些魔力来自哪里。他从此成为清谈节目的风云人物。拉森·扎尔斯（Larson Giles），笑笑公司（Smile Corp.）老总，一个Ted Turner型媒体巨头，派遣他的私家军团，由粗暴但无脑的菲古森（Ferguson）上校率领，去绑架格兰特，以便霸占全球媒体收视率。接下来就是电影史上最暴力和奇怪的对战之一。除了多个足以开罪所有人的极端暴力画面，还有曾被称为“电影中有史以来出现的最怪异和滑稽的性场面”。', '哈里斯·米切尔森', '比尔·普莱姆顿', 8.1, 8778, 'tt0119346', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1554375181.jpg', 0.8, 2.6, 19.3, 45.8, 31.5, '0.430907,-0.044671,-0.583255,0.558574,0.041361,0.214321,0.698680,0.144866,-0.479712,-0.165257,0.343268,0.702265,-0.293317,0.078097,0.412635,0.080883,-0.075079,-0.520610,-0.174012,-0.071545,-0.043289,-0.410848,-0.511511,-0.261756,0.247489,-0.367695,0.521980,-0.053750,-0.469064,0.119879,0.521696,0.485951,-0.158055,0.395196,-0.162371,-0.046034,0.208084,-0.055501,-0.233819,0.215789,-0.056919,-0.076943,0.136651,0.213940,-0.216419,0.157457,0.462384,-0.261269,-0.208681,0.120269,0.641113,-0.252770,-0.263876,0.006560,0.259755,0.022115,0.412627,0.086873,-0.092118,0.114988,-0.103999,-0.034538,-1.228683,-0.027647,0.240818,0.270852,-0.308976,0.291024,0.019239,-0.168347,0.120369,-0.113252,0.250127,0.335329,0.336612,0.397477,0.115033,0.102942,-0.205111,0.235500,0.860146,0.106588,-0.490771,0.379564,-0.140653,-0.235568,-0.089490,-0.479087,-0.295291,0.256536,0.185769,-0.140116,0.176985,0.377656,-0.680521,0.062336,-0.042833,-0.274645,0.252467,-0.360751,-0.038628,-0.503315,-0.205802,-0.352803,-0.136184,0.048676,0.221088,-0.141839,0.863578,-0.826118,0.021069,0.292562,0.307871,-0.366030,0.541514,0.233163,-0.084795,-0.052463,-0.090323,0.004275,0.129442,0.043385,-0.143907,0.364614,0.234044,-0.419660,-0.231048,0.357290', '1793491', '24284209', '27602116', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1875311', '理发师', '剧情', '理发师陆平（陈坤 饰）凭着自己的好手艺在大上海过着平凡的生活。日军侵占上海之后，一次意外的事故使他不得不远走他乡，自此开始了长达半生的颠沛流离。逃往江南古镇之后，陆平遇到了一位美丽的江南女子宋嘉仪（曾黎 饰），俩人一见钟情，无奈宋嘉仪婚约在先，其父宋丰年也想借女儿在那个特殊的年代里有个依靠，将宋嘉仪嫁给了国民党军官叶江天，嫁为人妇的宋嘉仪从未停止对陆平的爱恋，而陆平在颠沛流离的大半生除了自己的手艺始终没有放下的还有这份感情。一生情缘，半世坎坷，乱世之中这对有情人如歌如泣般演绎着他们的人生与爱恋……本片根据凡一平同名小说改编，是导演陈逸飞生前最后一部作品。©豆瓣', '陈坤', '陈逸飞', 6.4, 8313, 'tt0821477', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2388172297.jpg', 2.7, 12.3, 55.5, 23, 6.5, '0.103576,0.024414,-0.642364,0.859711,-0.095455,-0.477311,0.651926,-0.102124,-0.649170,-0.215866,0.088077,0.816508,0.063260,0.416974,0.070131,0.090636,-0.120293,-0.658130,-0.062060,-0.173477,-0.061471,-0.405428,-0.315962,-0.002349,-0.249507,-0.108330,0.734889,0.224341,-0.043505,0.379085,0.382336,0.052550,-0.067019,0.376864,-0.413848,0.368567,-0.148019,0.189134,-0.545400,0.161106,0.119762,-0.359236,-0.371804,0.036003,-0.144458,0.300313,0.778802,-0.252783,-0.213801,-0.006614,0.494756,-0.073689,-0.176756,-0.010178,0.141611,0.102329,0.283584,0.342429,-0.306344,-0.121928,0.022129,0.015059,-0.649323,-0.176654,0.156581,-0.076668,-0.817788,0.743688,-0.194829,-0.096852,0.093935,-0.278722,0.178037,0.248652,0.319732,0.238154,-0.283413,0.030326,-0.261405,0.711524,0.747065,0.093547,-0.178189,0.536543,-0.220726,-0.385010,-0.164700,-0.327405,-0.710156,0.100309,0.208989,-0.005009,-0.140844,0.192871,-0.448592,0.173947,-0.053182,0.028748,0.151668,-0.348783,-0.178568,-0.209482,-0.267189,-0.614119,-0.567863,-0.045360,0.078417,-0.339099,0.730286,-0.688153,0.085535,0.365643,0.039577,-0.629813,0.691453,0.260441,0.083280,-0.086438,-0.089306,0.371575,-0.373204,0.320553,0.271731,0.331453,-0.000954,0.009584,-0.370109,0.526499', '4842877', '26958479', '35030151', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1875313', '梦想照进现实', '剧情', '某部正在拍摄中的电视剧的女主角（徐静蕾）深夜短信该剧导演（韩童生），称有事想面谈，见面寒暄完毕，她即提出罢演，原因是实在恶心剧本中的女主人公形象演不下去，导演好言相劝，说该形象本是为她量身打造、要以大局为重等等，无奈女主角铁心罢工，导演作罢。导演称当初接戏相当被动，女主角的辞演让他如释重负，得到女主角讥讽，导演暴跳如雷，两人开始争执，导演怪女主角歪曲事实，女主角嫌导演做人太假。最终，话题又回到剧本，围绕它，两人就做人的技巧、人生的困惑、现实对梦想的凌驾等方面展开辩论。©豆瓣', '徐静蕾', '徐静蕾', 6.5, 17748, 'tt0843282', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2200541605.jpg', 4.4, 13.3, 44.2, 27, 11.1, '-0.010511,0.049940,-0.231556,0.372489,0.202878,-0.202366,0.320210,0.182145,-0.171630,-0.364158,0.286357,0.688986,-0.624238,0.057869,0.282651,-0.393184,-0.471587,-0.468625,0.070621,0.249898,0.448100,-0.319363,0.232193,0.052732,-0.322622,-0.071778,0.794820,-0.342127,-0.340495,0.121952,0.733069,-0.148105,-0.076600,0.350820,0.587702,0.126573,-0.214328,-0.005482,-0.588950,0.109350,0.410834,0.057933,-0.257499,0.226672,0.106067,0.317532,0.373312,0.102308,-0.260079,0.227059,0.941739,-0.483694,-0.095188,0.095984,0.079681,0.082352,0.396559,0.136761,0.038651,0.182093,-0.407059,-0.081513,-0.579209,0.221502,0.119347,0.125822,-0.227669,-0.028945,-0.037147,0.164076,0.177485,-0.184358,0.146122,-0.247939,0.918424,0.207935,0.080175,0.178240,0.157958,0.776740,0.302217,0.238659,-0.010976,0.530737,0.163358,-0.254007,0.075606,-0.259340,-0.577896,0.036345,-0.182053,-0.129820,0.129761,-0.222786,-0.317422,-0.386231,0.204369,0.099626,-0.018873,-0.463403,0.270218,-0.534546,-0.238597,0.098439,0.251479,-0.415137,0.103812,-0.383920,0.540165,-0.495402,-0.483783,0.324736,0.287110,-0.665948,0.509937,0.506909,0.057022,-0.507097,0.167616,-0.011168,-0.305357,-0.017527,-0.013383,0.018986,0.278202,-0.414705,-0.426293,0.155328', '6869395', '34810454', '25835285', '10605978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1875317', '天黑请闭眼', '恐怖', '杀人游戏在年轻人当中颇为流行，七个朋友在酒吧里面玩这个游戏，不幸弄假成真，游戏变成了现实——他们发现每天晚上在游戏中被杀之人，必定在当晚真的死去。这使得众人大为恐慌，自己随时成为假戏真做的冤魂。他们猜想，凶手极有可能就在这几个人当中，为了能使事情水落石出，逃出生天，他们继续进行着这个惊悚的游戏，而往事也随之渐渐抬头。他们曾经有一个名叫露露（小宋佳 饰）的朋友，在一次事故中，露露被他们撇下不管，以致死亡。如今，露露似乎要回来了……这个恐怖游戏的幕后凶手，到底是冤魂不散的露露，还是另有其人？©豆瓣', '王志文', '刘晓光', 4.8, 6382, 'tt0833547', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2487622155.jpg', 17, 37.7, 37.2, 6.2, 1.9, '0.210509,0.118044,-0.783576,0.264226,-0.223177,0.079516,0.790643,-0.177955,-0.769064,-0.328865,0.340152,0.903335,-0.314330,0.271076,-0.032921,0.038244,-0.399714,-0.526759,-0.133531,-0.402373,-0.363531,-0.273508,-0.267508,-0.228946,0.002070,0.018641,0.378097,0.090557,0.010579,0.418165,0.431255,0.407474,-0.386238,0.614694,-0.038978,0.145496,0.145461,-0.087330,-0.248497,0.293110,-0.024158,-0.164457,-0.106386,0.136809,-0.279241,0.127238,0.752250,-0.334202,-0.360573,0.057395,0.334398,-0.588253,-0.410795,0.061756,0.366982,-0.283359,0.430859,0.137748,-0.220983,-0.013748,-0.022073,0.152080,-0.814319,0.209990,0.058361,0.236769,-0.274241,0.036210,0.134431,-0.164298,0.198878,-0.101101,0.390367,0.318085,0.590516,0.211661,-0.194887,-0.333397,-0.815547,0.033502,0.809904,-0.097522,-0.101181,0.350620,0.187267,-0.305219,-0.180110,-0.236713,-0.289120,0.223138,0.465351,0.034075,-0.546796,0.341483,-0.584866,0.248865,0.083021,-0.033094,-0.350128,-0.421037,-0.315051,-0.292439,-0.219634,-0.074583,-0.398368,0.017530,-0.139174,-0.361209,0.641425,-0.985048,0.233740,0.808266,0.224086,-0.648367,0.503079,0.251954,0.038098,-0.185932,-0.208605,-0.073819,0.080652,0.365094,0.258677,0.323082,0.000774,-0.162774,-0.531637,0.453750', '1308755', '1299628', '1301022', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1875488', '冰刀双人组', '喜剧', '你想不到，花样滑冰赛场上竟然有如此搞笑的溜冰表演。查兹（威尔·法瑞尔 Will Ferrell 饰）摇滚味十足，耍弄着喷火的伎俩，一举一动都赢得粉丝们的狂热支持，整个场地都变成了他轻松驾驭的舞台。本来胜券在握，却万万想不到对手吉米（乔恩·海德 Jon Heder饰）同样实力超群。别小看吉米一副娘娘腔的打扮，优雅的气质和舞步可是相得益彰。既然两人都平分秋色，大赛决定实行双冠军。这可激怒了二人，他们当场斗殴，把赛场弄得一片混乱——当然，后果严重极了。他们被取消了终身的比赛资格。两个滑冰王子从此上不了赛场，各自谋生，状况相当黯淡。二人的内心还是想收复失地，卷土重来，然而禁赛规定又让他们无计可施。可是，转机到了，他们发现可以建立起一对男子双人滑组合，就可以重归赛场。这无疑意味着，查兹和吉米要最大限度的化解宿仇，冰释前嫌，在二人组里默契配合，才能重现赛场辉煌。果然，祛除心病后，这对组合屡屡出奇制胜，在赛场上的表现可谓笑料连连。', '威尔·法瑞尔', 'Josh Gordon', 6.7, 11062, 'tt0445934', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1452354753.jpg', 2, 9.1, 48.3, 31.1, 9.6, '-0.055510,0.027793,-0.610417,0.532932,-0.180471,-0.238145,0.327068,0.034731,-0.268190,0.236460,0.272518,0.638944,-0.538849,-0.098500,0.472756,-0.416464,-0.179216,-0.720115,-0.069145,-0.081714,-0.057293,-0.359705,-0.328675,-0.153886,-0.041339,-0.257013,0.605249,0.080486,-0.303926,0.605799,0.455166,-0.070039,0.233392,0.204089,-0.048897,-0.223332,-0.002880,0.111143,-0.099008,0.218454,-0.109970,-0.103193,-0.276133,0.422824,0.105853,0.071410,0.660480,-0.318655,-0.179596,-0.008292,0.255909,-0.298077,-0.098850,0.393677,0.075339,-0.169412,0.193210,0.187791,-0.071070,-0.098744,0.159189,0.051747,-0.758294,0.451801,0.023927,-0.075454,-0.372960,0.629317,0.086207,-0.266247,-0.090841,0.049854,0.079079,0.247109,0.523043,0.095095,-0.137796,-0.238006,-0.704223,-0.071559,0.687114,0.062853,-0.360990,0.240168,-0.052209,-0.368024,-0.191886,-0.539881,-0.210688,-0.139372,0.201149,-0.066429,0.128875,0.103517,-0.450373,0.132055,-0.147072,-0.118321,-0.300027,-0.559711,0.277819,-0.452152,-0.121085,-0.260394,-0.513831,0.274688,-0.035203,-0.183622,0.730731,-0.825910,-0.125084,0.199241,0.079223,-0.384561,0.379249,0.365873,0.145066,-0.056779,-0.540620,-0.056311,-0.001859,0.173387,0.190575,0.703240,0.002227,-0.168802,-0.434117,0.671672', '1826173', '4127270', '35030151', '3000078');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1876686', '疯羊', '喜剧', '美丽宁静的新西兰牧场，无数温顺的绵羊正在草场上觅食，突然远处传来令人毛骨悚然的叫声。奥利弗（马修·张伯伦 Matthew Chamberlain 饰）年幼时由于哥哥安格斯的恶作剧而患上“恐羊症”，成人后在回农场处理父亲留下的遗产时发现哥哥安格斯为了赚钱而用羊做基因试验，从而引发了一场灾难。本来温顺的绵羊突然变得凶残起来，并且迅速蔓延。但凡被已经变异的羊咬过，无论是羊或者是人都会变成可怕的食肉动物。四处躲藏的奥利弗巧遇一直反对农场基因试验的女孩“Experience”，在农场工人塔克的帮助下，三人不得不开始阻制这场灾难的进一步扩散……本片是新西兰导演乔纳森·金 （Jonathan King）的处女作，这位口味独特的导演热衷于“令人倒胃口的血腥镜头”。©豆瓣', 'Matthew Chamberlain', 'Jonathan King', 5.8, 6409, 'tt0779982', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2184137781.jpg', 5.8, 23.6, 50.2, 15.2, 5.2, '0.089284,-0.143654,-0.596114,0.422202,0.024984,-0.116112,0.713998,0.206838,-0.421474,-0.013981,0.184047,0.624867,-0.172530,0.242362,0.140523,-0.055546,-0.262629,-0.253388,-0.375785,0.162072,-0.211615,-0.115130,-0.327286,-0.422831,0.244050,-0.309765,0.408397,-0.010644,-0.224470,0.442055,0.156347,0.291993,-0.084761,0.329866,-0.081038,-0.176218,-0.105367,0.110461,-0.211763,-0.115298,0.088178,-0.217636,-0.141575,-0.042037,0.041283,0.244415,0.700100,-0.434117,-0.311930,-0.442398,0.441756,-0.047176,0.203336,0.063013,0.261294,0.140578,0.270822,-0.070853,0.039303,-0.031697,-0.007086,0.006700,-0.513147,0.025756,-0.031623,0.202577,-0.220916,0.081518,0.196155,0.162191,0.296540,-0.410903,0.011908,0.234388,0.177655,0.550967,-0.148478,0.285109,-0.280338,0.152312,0.679415,-0.006276,-0.388375,0.335323,-0.308383,-0.589833,0.218157,-0.266855,-0.183586,-0.071205,0.489246,0.099680,-0.297523,0.406916,-0.878319,-0.079722,-0.039559,-0.533509,-0.145596,0.011833,-0.438702,-0.568242,-0.071375,-0.232020,0.039360,0.129811,-0.000532,-0.361968,0.548512,-0.588814,0.326886,0.687207,-0.002161,-0.243109,0.094560,-0.453615,-0.025560,0.017941,-0.207990,0.171314,0.049929,0.263733,0.250915,0.305817,0.064585,-0.193013,-0.419155,0.509278', '3005387', '10581450', '2357162', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1876765', '意', '剧情', '1964年，玫瑰（陈冲 饰）是夜总会里当红的歌手，结识了澳洲水手比尔（斯帝温•威德勒 饰），带着儿子Tom（骆佳炜 饰）、女儿May随比尔移民到澳洲去。不久与比尔分手后，她继续留在澳洲，周旋在不同的男人身边。数年后，玫瑰与比尔复合，比尔却要继续水手的工作。不甘寂寞的玫瑰恋上了华人餐厅中的年轻厨师Joe（戚玉武 饰）。玫瑰带着儿女离开了比尔的房子，与Joe同居了。可是Joe很快对养活玫瑰三母子的重任感到了压力，两人关系僵化，玫瑰崩溃。更不堪的是玫瑰16岁的女儿May与Joe恋上了，玫瑰深感震惊……而玫瑰的儿子Tom把母亲经历的这一切看在眼里。©豆瓣', '陈冲', '托尼·艾尔斯', 8, 10399, 'tt0452631', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2584161464.jpg', 0.3, 1.4, 21.7, 50.7, 25.9, '0.149459,-0.095029,-0.730183,0.448886,-0.162347,-0.605895,0.766961,0.286683,-0.683954,0.043554,0.143978,0.777152,-0.268231,0.364169,0.392162,0.101119,-0.388033,-0.709238,-0.102534,-0.291346,-0.249755,-0.529330,0.011835,-0.054902,-0.127786,-0.272500,0.556287,0.074262,0.383760,0.744812,0.228900,-0.031814,-0.045526,0.253865,-0.118125,0.146681,0.097763,0.065288,-0.569629,0.185882,0.048266,-0.150922,-0.139333,-0.018027,0.114881,0.148247,0.619983,-0.167200,0.322869,-0.313092,0.159910,0.024656,-0.070376,0.082735,0.206258,0.021260,0.285217,0.040571,-0.429250,-0.180830,0.097053,-0.253755,-0.398370,0.293173,0.210533,0.285304,-1.125152,0.547193,-0.339567,0.017958,0.282809,-0.413546,0.186625,0.177252,0.117052,0.606011,0.032596,0.140453,-0.595724,0.261420,0.633521,0.122740,0.017196,0.183268,-0.289433,-0.200913,-0.180904,-0.115962,-0.414151,-0.059616,0.148779,0.094543,-0.008741,0.202590,-0.843422,-0.074141,-0.180940,-0.241226,0.323018,-0.337903,0.015904,-0.665123,-0.142066,-0.743244,-0.245803,0.071461,0.271073,-0.015601,0.773788,-0.830057,0.193100,0.398711,0.652036,-0.446625,0.582393,0.046705,0.187685,-0.166483,-0.212401,0.291195,-0.055551,0.181008,0.495164,0.385182,-0.116429,-0.103170,-0.304905,0.205920', '3111650', '1299965', '1926007', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1877016', '梦游夏威夷', '喜剧', '阿洲（杨佑宁 饰）即将从军队退役，这时候他时常梦见小学同学陈欣欣（张钧宁 饰）死去，令他纳罕的是这位小学同学她已多年没见。他一直受这个梦困扰，坚信这个梦是为他带来什么信息。他们的连上士兵昆河逃走，上级便派出阿洲及其好友小鬼（黄鸿升 饰）找回昆河。于是阿洲趁着这次出外的机会寻找陈欣欣，意想不到的是陈欣欣也跟阿洲与小鬼一样来到了花莲。他们一同享受着阳光海滩，日子愉快。他们突然遇到了寻找目标昆河，可是昆河却把他们绑架到了一个放满了炸药的小屋里，原本以为会遭遇不测的他们，事情出乎了他们的意料……©豆瓣', '杨祐宁', '徐辅军', 7.3, 5623, 'tt0788133', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2390013437.jpg', 0.4, 4, 40.1, 40.1, 15.4, '0.317870,-0.121982,-0.703566,0.432240,-0.133656,-0.397404,0.582441,-0.082090,-0.805875,-0.406247,0.053269,0.568396,-0.298685,0.172514,0.009067,-0.008532,-0.283888,-0.660928,-0.016589,-0.000915,-0.421310,-0.254678,-0.345044,-0.142359,-0.121525,-0.108949,0.262869,0.093481,-0.124369,0.660197,0.393808,0.168411,0.063330,0.793046,-0.148194,0.319039,0.059004,0.286055,-0.029549,0.028261,0.082734,-0.384913,-0.176533,0.144850,0.227130,0.370204,0.517006,-0.182878,-0.313242,0.064874,-0.005458,-0.504340,0.069031,0.145360,0.280922,-0.126748,0.134199,-0.010923,-0.217241,-0.239554,0.109815,0.015241,-0.502371,0.190081,0.036871,0.166848,-0.486035,-0.032619,-0.024586,0.159960,0.362597,-0.426552,0.361399,0.445396,0.271064,0.179330,-0.184196,-0.136773,-0.550069,0.251284,0.937133,-0.122573,0.051730,0.195236,-0.082358,-0.278172,0.034150,0.083774,-0.316738,0.370389,0.254408,-0.013849,-0.110637,0.110969,-0.361859,-0.122439,-0.289984,-0.095994,0.038115,-0.313969,-0.182356,-0.381164,0.029731,-0.444721,-0.353898,0.323908,-0.162305,-0.137929,0.519331,-0.772416,0.279242,0.543534,0.314934,-0.542761,0.808102,0.005294,-0.103487,-0.199089,0.237844,-0.060078,-0.142484,0.320935,0.346844,0.254368,-0.091389,-0.105288,-0.318149,0.205405', '25870679', '2990737', '1292064', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1877596', '飞吧，爸爸', '剧情', '高胜锡（李俊基 饰）是个沉默寡言的男孩子，喜欢看书思考的他实际上是一个打架高手，能一个打七个。上班族张家弼（李文植 饰）因为女儿被男同学欺负，平时就胆小如鼠的他下决心要为女儿报仇，所以他找到了高胜锡，希望胜锡能教会他如何与人打架。家弼苦苦恳求后，胜锡才答应了当家弼的师父。接下来，胜锡安排了一系列艰苦训练，各种各样的训练层出不穷。40天的训练过去了，家弼整个人都焕然一新。决战的日子就要来临了，家弼到底能不能战胜强大的对手为女儿报仇呢？©豆瓣', '李准基', '崔宗泰', 6.8, 5849, 'tt0857334', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200534521.jpg', 0.9, 7.5, 51.4, 28.9, 11.3, '-0.065501,-0.312689,-0.362986,0.440106,-0.353009,-0.285768,0.357054,-0.025133,-0.496678,-0.354341,0.167757,0.493434,0.127811,0.186619,0.105483,-0.165169,-0.071157,-0.640029,-0.038986,-0.061655,-0.330357,-0.305252,-0.095822,-0.277448,0.093861,-0.166503,0.354073,0.090880,0.153327,0.170522,0.259936,0.020460,0.346639,0.197696,-0.238828,-0.179134,-0.167545,-0.002337,0.016765,0.224383,0.027094,0.058117,-0.226246,0.224107,0.214767,0.287165,0.433715,-0.053280,-0.087002,-0.262195,0.127546,-0.409247,-0.135801,0.366034,0.235748,-0.280361,0.324649,0.175781,0.077555,0.014281,-0.243998,-0.046425,-1.033097,0.085252,0.074218,-0.218760,-0.875022,0.399774,0.076103,-0.029926,-0.135956,-0.346941,0.245653,0.546944,0.263892,0.397969,-0.058747,-0.129661,-0.547860,0.348587,0.890261,-0.084572,0.077371,0.182850,-0.016506,-0.144724,0.168520,-0.857658,-0.663781,0.055509,0.129202,-0.110881,-0.350584,-0.095925,-0.127922,-0.034810,-0.216891,-0.051141,0.030911,-0.580845,-0.006880,-0.071620,0.022470,-0.220612,-0.305186,0.349087,0.004566,-0.469965,0.968763,-1.056954,0.051015,0.614790,0.343109,-0.885638,0.591138,0.323872,0.020816,-0.143558,0.127736,-0.268907,-0.011675,0.187597,0.118068,0.522949,0.253950,-0.120825,-0.311697,0.250707', '24284209', '30163500', '5985887', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1878176', '爱的边缘', '剧情', '薇拉·菲利普斯（凯拉·奈特莉 Keira Knightley 饰）和凯特琳·托马斯（西耶娜·米勒 Sienna Miller 饰）在对天才诗人迪伦•托马斯（马修·瑞斯 Matthew Rhys 饰）爱的沦陷中构筑着深厚的友谊。一方面，薇拉是托马斯青梅竹马的灵魂之友，初恋 相逢却终因托马斯的无法专情而嫁给军官威廉姆·克里克（希里安·墨菲 Cillian Murphy 饰）。在威廉姆出征期间用着他的军人津贴来维持托马斯花天酒地的巨大生活开销。另一方面，凯瑟琳是对托马斯不离不弃的妻子，虽然被托马斯的滥情一次又一次的伤害折磨，却始终深深爱着他。薇拉，凯瑟琳，托马斯三人就这样在战乱的年代保持着令人不解的暧昧关系，直到从前线归来的威廉姆听闻了薇拉和托马斯的绯闻，盛怒之下将枪口指向了托马斯….该片改编自英国天才诗人迪伦·托马斯的生平事迹。该片获英国威尔士电影电视艺术学院奖最佳服装设计奖项。', '凯拉·奈特莉', 'John Maybury', 6.9, 9361, 'tt0819714', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p739508313.jpg', 0.8, 7.3, 47, 34.7, 10.2, '0.260473,-0.191910,-0.720480,0.604233,-0.010436,-0.330591,0.868641,0.196145,-0.262705,-0.052112,0.348290,0.729971,-0.269134,0.142919,0.356008,0.151155,-0.432686,-0.939795,0.008087,-0.098545,-0.186958,-0.743958,-0.123416,-0.138295,-0.335179,-0.451332,0.420655,-0.346878,0.057085,0.510560,0.338962,0.463006,0.188427,0.313803,-0.123827,0.096027,0.275040,-0.347408,-0.335279,0.405746,0.472391,-0.027136,-0.416758,0.353493,0.104935,0.319985,0.702081,-0.679594,0.611503,0.227522,0.221447,-0.376288,0.110249,-0.155563,0.211785,-0.295244,0.018579,0.274618,-0.132717,-0.026864,0.207997,-0.037229,-0.404410,0.057626,-0.107091,0.114704,-0.707222,0.549079,-0.363285,0.168568,0.017181,-0.105228,-0.029542,0.185443,0.040815,0.342328,-0.002497,0.292398,-0.083542,0.057613,0.345097,0.041056,-0.360581,0.394126,-0.665276,-0.326587,-0.212337,-0.245405,-1.022142,-0.292779,0.377399,-0.253704,0.250683,0.352923,-0.351521,-0.147194,-0.570897,-0.011135,0.058271,-0.196754,-0.155919,-0.598974,-0.138156,-0.458296,-0.079620,-0.083201,-0.038344,-0.189338,0.555189,-0.590219,0.184945,0.536501,0.243670,-0.143307,0.747936,0.144102,0.015200,-0.164488,-0.223677,0.764957,-0.058431,-0.133974,0.228644,0.233338,0.281707,0.021476,-0.230490,0.807962', '26677495', '26809592', '1291556', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1878616', '隐秘', '剧情', '有着灰暗过去的伊丽娅·叶利什科（Kseniya Rappoport 饰）从乌克兰来到意大利的维拉齐，她租住简陋破败的房间，向对面公寓的看门人请求工作，甚至情愿将薪水的一部分分给对方。在此之后，她又结识该公寓内某个三口之家的女佣吉娜（Piera Degli Esposti 饰），千方百计打听这户姓安德齐尔人家的事情，还盗配了他们家的钥匙。而为了进入安德齐尔家，伊丽娅更是不择手段。她似乎在寻找什么，又似乎在躲避着什么。这一切仿佛都和伊丽娅那段过去紧紧相连……本片荣获2007年欧洲电影节观众选择奖最佳影片；2007年意大利大卫奖最佳导演、最佳影片、最佳女主角（Kseniya Rappoport）、最佳配乐和最佳摄影等5项大奖。©豆瓣', '克谢尼娅·拉波波尔特', '朱塞佩·托纳多雷', 8, 10291, 'tt0494271', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p794655247.jpg', 0.3, 1.4, 21, 52.6, 24.8, '0.031819,0.112926,-0.541195,0.469169,0.138941,-0.405920,0.495097,0.122761,-0.229723,-0.385341,0.022928,0.898038,-0.250704,0.202917,0.199304,0.355053,-0.423012,-0.647945,-0.205746,-0.364810,-0.245134,-0.400463,-0.245293,-0.145391,-0.009699,0.247834,0.417383,0.042334,-0.031435,0.340656,0.656833,0.053199,-0.276008,0.324985,-0.115016,0.160661,0.125176,-0.055995,-0.478101,0.084456,-0.017335,-0.335571,-0.422635,0.097938,0.465413,0.279756,0.562251,-0.033205,0.110371,0.358047,0.269195,-0.244132,0.006397,0.207172,0.112018,-0.127579,0.197252,0.034158,-0.147593,0.293543,0.114649,-0.241743,-0.642521,0.086004,0.186353,0.122995,-0.507362,0.451442,0.070562,0.116067,-0.030312,-0.200889,0.305550,0.403607,-0.124988,0.242907,-0.366964,-0.014709,-0.578891,0.344281,0.201225,-0.085871,-0.032226,0.220889,0.011899,-0.696374,-0.115790,0.015683,-0.551952,-0.074797,0.511677,0.069398,0.312979,-0.099073,-0.527341,-0.186099,0.105581,-0.405045,0.053389,-0.344919,0.075340,-0.827401,0.131349,-0.111455,-0.222833,-0.019828,-0.057049,-0.232994,0.421702,-0.373756,0.177455,0.527987,0.384252,-0.294583,0.643579,-0.292269,0.326126,-0.147306,-0.463523,0.295760,0.014698,0.357808,0.215506,0.264413,-0.152568,-0.190778,-0.481301,0.453344', '1829654', '1484091', '1306762', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1883406', '恶魔的艺术', '悬疑', '影片围绕着一个家庭遭到情妇利用"黑色巫术"复仇的故事展开.讲述了一个百万富翁全家人被神秘而诡异的地杀害。没有丝毫线索; 无法找到可以指证的凶手。神秘而恐怖的死亡令所有人为之困惑。一位罪案报道记者参与进此案的调查, 发现一个美貌的女人有可疑。他该如何向所有人证明她就是那个一直隐藏着的、并且擅长"魔鬼的艺术"的情妇? ...', 'Arisa Wills', 'Tanit Jitnukul', 6.3, 8367, 'tt0444759', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2248671565.jpg', 3.6, 16.7, 49.9, 20.9, 9, '0.408896,-0.098151,-0.719950,1.103488,-0.383474,0.100634,1.095600,-0.163949,-0.694989,-0.565113,0.265203,0.611831,-0.131865,0.067533,0.067158,0.251681,0.148472,-0.775332,-0.309477,-0.025094,-0.290674,-0.620977,-0.394121,-0.509615,0.021100,-0.180301,0.521061,0.445133,-0.292346,0.119872,0.573994,0.467736,-0.426358,0.327913,-0.171927,-0.360812,0.129532,-0.280460,-0.163543,0.549552,0.107008,-0.331402,-0.161829,0.523635,-0.858594,0.423288,0.779130,-0.370962,-0.319522,-0.037985,0.833757,-0.477937,-0.050535,0.434089,0.279384,0.083632,0.085400,0.245590,-0.051968,-0.123262,0.160960,0.021803,-1.412725,-0.249086,0.219773,0.591648,-0.433427,0.166427,-0.174066,-0.065615,0.179111,-0.249670,0.289882,0.090705,0.200813,0.332909,-0.063711,0.123826,-0.468184,0.208031,0.648824,-0.040936,-0.330646,0.196099,-0.214097,-0.304838,-0.114041,-0.221932,-0.660501,0.300203,0.465111,0.247927,-0.236555,0.204842,-0.666448,-0.191066,-0.346513,-0.159550,-0.107532,-0.527034,-0.258489,-0.547338,-0.269013,-0.013020,-0.374015,0.089035,-0.088981,-0.457594,0.763774,-0.864968,0.290651,0.872765,0.099400,-0.887959,0.576329,0.011745,-0.019383,-0.145050,-0.459332,0.120569,0.382460,0.345970,-0.055374,0.254722,-0.057729,-0.409605,-0.519237,0.119406', '3670447', '3785918', '4820775', '30368448');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1884684', '沉默', '剧情', '《沉默》改编自著名日本作家远藤周作的同名小说。故事发生在德川幕府时代禁教令下长崎附近的小村子，一个葡萄牙耶稣会的教士偷渡到日本传教，并调查恩师因遭受「穴吊」酷刑而宣誓弃教一事，因为这事在当时欧洲人的眼中，不只是个人的挫折，同时也是整个欧洲信仰、思想的耻辱和失败。在传教与寻访的过程中，信仰与反叛、圣洁与背德、强权与卑微、受难与恐惧、坚贞与隐忍、挣扎与超脱……所有的两难情境都面临了，逼迫着他对基督的信仰进行更深层且更现实的思索，最终，他彷佛也走过一趟恩师的心路历程，拥有自己对信仰的诠释与实践。', '安德鲁·加菲尔德', '马丁·斯科塞斯', 7.7, 21986, 'tt0490215', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2399605505.jpg', 1.1, 3.6, 27.4, 46.4, 21.6, '0.186860,-0.095577,-0.792588,0.717091,0.182503,-0.131217,0.951268,0.109375,-0.473043,-0.289279,0.252395,0.849586,-0.033382,0.082343,0.300345,-0.183524,-0.447536,-0.869583,-0.118237,0.082680,-0.203276,-0.576470,-0.164110,-0.076142,-0.466816,-0.320570,0.854210,0.496842,-0.644552,0.211177,0.096494,0.512228,-0.106202,0.389616,-0.226020,-0.215000,-0.046423,0.227506,-0.360574,-0.025550,0.145909,-0.493319,-0.262228,0.340557,-0.360746,0.294161,0.463176,-0.556483,-0.234027,-0.212606,0.235256,-0.425924,-0.169107,0.420562,0.007152,0.006920,0.020036,0.571718,0.125538,0.133359,-0.031049,0.031916,-1.037718,-0.266522,0.210428,0.184416,-0.493307,0.578251,0.148605,-0.117100,0.070301,-0.259161,0.139330,0.280947,0.196067,0.550243,-0.297878,-0.241482,-0.394672,0.199380,0.582668,-0.056720,-0.372377,0.114705,-0.402596,-0.541040,-0.114362,-0.312886,-0.444545,-0.114985,-0.011983,0.145811,-0.114111,0.605728,-0.743536,0.082028,-0.108248,-0.307154,0.081551,-0.521562,0.155110,-0.559929,-0.360062,-0.581262,-0.287259,0.052516,0.645988,-0.147459,0.799569,-0.678569,0.323381,0.552816,0.331706,-0.743876,0.680323,0.346084,-0.071471,-0.106553,0.122282,0.597119,0.013784,0.376680,-0.204209,0.039064,0.139914,0.372663,-0.399016,0.472375', '25828589', '26667010', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1885124', '时间旅行者的妻子', '剧情', '一场车祸，母亲丧生，而孩子却奇迹般幸存，他赤裸着身体获救，然而救人者竟然是来自未来的自己。原来，这个名叫亨利（艾瑞克•巴纳 Eric Bana 饰）的图书管理员，患上慢性时间错位症，以至于每次发病都将穿越时空。而且，他每次穿越都赤身裸体，经常闹出笑话。久而久之，亨利习以为常。一个偶然的机会，他爱上了一个名叫克莱尔（瑞秋•麦克亚当斯 Rachel McAdams 饰）的女孩。为了追求克莱尔，他穿越时空对6岁的克莱尔表白，并许诺未来将娶她为妻。因此，当亨利在现实中出现时，两人迅速热恋、结婚，而且还生了一个女孩。但是，亨利的老毛病依旧无法改变，所以克莱尔必须适应这个穿越时空的老公，两人也因此历经磨难……本片改编自美国作家奥黛丽•尼芬格(Audrey Niffenegger)创作的同名畅销小说。©豆瓣', '瑞秋·麦克亚当斯', '罗伯特·斯文克', 7.7, 235195, 'tt0452694', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p480590433.jpg', 0.3, 2.6, 28.6, 48.5, 20, '0.078695,-0.013172,-0.534006,0.392193,-0.245584,-0.384350,0.741228,-0.114341,-0.480404,-0.519778,0.180022,0.953925,-0.217778,0.345753,0.174743,0.148046,-0.248782,-0.601369,0.163910,0.075022,-0.405501,-0.205198,-0.279097,-0.205992,-0.178515,-0.293785,0.490624,-0.159857,-0.048942,0.454008,0.318321,0.297084,0.207062,0.426703,-0.060719,0.151235,0.109740,0.092420,-0.254009,0.305461,0.032742,-0.215584,0.019694,0.284468,-0.300023,0.352977,0.478618,-0.372356,-0.214307,-0.222875,0.680136,-0.269601,-0.068173,0.338050,0.084529,-0.031375,0.312193,-0.004539,-0.112996,-0.117866,-0.010791,0.094733,-0.594355,0.077101,-0.025843,0.088891,-0.366105,0.198192,-0.006882,-0.031916,-0.052004,-0.191311,0.126830,0.383054,0.413996,0.197410,-0.618272,-0.023526,-0.370359,0.122983,0.629980,0.001397,-0.517029,0.575574,-0.228699,-0.521813,-0.041362,-0.051226,-0.764947,0.307404,0.041711,0.055118,-0.347185,0.389031,-0.241732,0.006843,-0.465771,0.038094,-0.257692,-0.197063,-0.244222,-0.358837,-0.031306,-0.225159,-0.394459,-0.046052,-0.092574,-0.465475,0.559763,-0.513064,0.349412,0.810583,0.129466,-0.435847,0.687228,0.226782,0.117295,-0.432316,-0.074253,0.792556,-0.089188,-0.045501,-0.059616,0.206933,0.041124,0.164986,-0.353708,0.685855', '1460341', '34890458', '3001149', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1886896', '妄想', '惊悚', '梁咏娜（蔡卓妍饰）因失恋变得精神恍惚。有天她遇到了与前男友阿坤十分相似的伟豪（余文乐饰），令她对生活仿佛也有了希望。好友阿仪（梁洛施饰）鼓励咏娜放下以前的不快，好好的与伟豪发展。咏娜跟伟豪很快开始交往，咏娜担心伟豪会像阿坤那样变心，终日都幻想着伟豪要离开自己，又开始坠入了妄想的深渊。警察因伟豪的失踪，调查与伟豪有关的人，发现了一个惊人的真相。©豆瓣', '余文乐', '彭顺', 6.2, 6284, 'tt0865496', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p904398085.jpg', 2.8, 16.6, 54.2, 20.5, 5.9, '0.465144,-0.230376,-0.767856,0.355597,-0.031302,-0.295130,0.879512,0.126212,-0.586939,-0.169864,-0.024793,0.731362,-0.370393,0.340336,0.163861,-0.237622,-0.414391,-0.885148,0.090671,-0.118404,-0.127415,-0.451308,-0.088509,0.013441,0.014478,-0.251866,0.395263,0.108228,-0.269305,0.668991,0.043122,0.091607,0.019214,0.562632,-0.239089,0.137733,-0.343146,0.429326,-0.300903,-0.084554,0.359430,-0.003105,0.112751,0.231700,0.007322,0.383950,0.397953,-0.167951,-0.520122,-0.024980,0.360323,-0.204057,-0.011556,0.097231,0.121156,0.222605,-0.056977,0.141279,-0.340127,-0.154601,-0.027840,0.015038,-0.557632,0.261557,0.100808,0.262849,-0.522713,0.142566,0.020945,0.000227,0.340798,-0.157934,0.325417,0.721221,0.305532,0.444345,-0.230091,-0.038566,-0.471052,0.242248,0.740055,-0.052476,-0.242966,0.418566,0.176068,-0.264316,-0.108535,0.135047,-0.453428,0.068142,0.126067,0.140721,-0.540721,0.415015,-0.571924,0.025263,0.043330,-0.007952,-0.244802,-0.678003,-0.126317,-0.207194,-0.296642,-0.497953,-0.339998,-0.035689,-0.169610,-0.550765,0.527791,-0.951383,0.373913,0.324708,0.592316,-0.907282,0.437254,0.091853,-0.175168,-0.179007,0.072114,0.446582,-0.037254,0.189587,0.176622,0.225320,0.076306,0.011464,-0.483084,0.134461', '1301022', '1949320', '1308755', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1887829', '虫师', '奇幻', '距今一百年前的日本，流行着一种被称为“虫”的神秘生命体，它无形无色，几乎不属于任何一个科属，却可对人类的精神和身体产生巨大的影响。白发独眼的男人银古（小田切让 饰）天生具有特殊体质，他可以感知到虫的存在，并利用这项技能帮助人排忧解难，因此他又被人们尊称为“虫师”。银古跋山涉水，四处云游，曾遭遇专吃声音的“阿牟”、长着四个角的女孩真火（守山玲愛 饰）、传说中的梦幻彩虹“虹蛇”、必须通过誊写虫的故事来将其封印的“禁种之虫”……在这一过程中，银古也不可避免受到虫的影响……本片根据日本漫画家漆原友紀同名原著改编。©豆瓣', '小田切让', '大友克洋', 6.6, 13829, 'tt0862946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p764625487.jpg', 2.1, 11.8, 48.8, 27.3, 10, '0.116763,0.153435,-0.519625,0.815700,-0.108024,0.314797,0.770898,-0.067606,-0.434454,-0.405294,-0.029210,0.619896,-0.155619,-0.069231,-0.072949,0.102384,0.203007,-0.135335,-0.057053,0.067485,-0.490203,0.020189,-0.569024,-0.050206,-0.220304,-0.593725,0.654615,0.048491,-0.645357,0.316612,0.006369,0.531679,-0.142205,0.434753,-0.201952,-0.016898,-0.181557,-0.088438,0.173833,0.127301,-0.129324,-0.294583,0.305317,0.324985,-0.519307,0.213033,0.699326,-0.841519,-0.285295,-0.306501,0.417517,-0.101953,-0.152298,0.015466,0.482152,0.088190,0.243921,0.193862,-0.031880,0.152872,0.102061,-0.068797,-0.955931,-0.292630,0.152029,0.283937,-0.185339,0.331003,0.183730,-0.068347,-0.062458,-0.122573,0.070527,-0.007944,0.249095,0.284545,-0.219613,0.049674,-0.494684,0.104028,0.458621,-0.171032,-0.657716,0.307416,-0.440781,-0.540955,-0.335270,-0.150887,-0.068688,0.050884,0.271676,0.361189,-0.425619,0.256245,-0.859805,0.134682,-0.026086,-0.046631,-0.147121,-0.143214,-0.081327,-0.608685,-0.210038,-0.456679,-0.369940,0.017774,0.351112,-0.283082,0.783787,-0.651057,0.468018,0.639288,0.236853,-0.234742,0.592787,-0.078813,0.079501,-0.280604,-0.295571,0.329581,0.229050,0.406305,0.146516,0.399624,0.139154,0.092421,-0.398704,0.507235', '1308784', '26667010', '25774050', '3213270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1888671', '鸡犬不宁', '剧情', '一向不景气的豫剧团接到了一个振奋人心的消息：香港某集团邀其演出。然而就在启程之际团长遇意外身亡，豫剧团随之解散。剧团里的三个好兄弟：马三（李易祥 饰）、刘兵（姚鲁 饰）和四海（金宏 饰）亦随之失业。马三失业后，无奈下只好把斗鸡作为谋生手段，其妻大红（小香玉 饰）一人分做两份工，一心想着出国；四海妻子素梅（徐帆 饰）去了深圳发展，四海贩起了狗，夫妻间渐渐疏离；刘兵靠老丈人的钱开了间相馆，可他却不满足业余摄影师的现状。生活所迫下，三个男人开始慢慢适应新的环境。他们的困惑也在改变中越积越厚，但是，生活的真相或许本是如此……©豆瓣', '徐帆', '陈大明', 6.7, 9363, 'tt0482051', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1757508657.jpg', 1.6, 9.6, 49.6, 30, 9.2, '0.165989,0.274634,-0.491411,0.254967,0.132509,-0.234876,0.275614,0.381356,-0.286040,-0.157580,-0.013530,0.496552,0.135450,0.239628,0.124303,-0.088228,-0.300774,-0.458681,-0.102988,-0.072698,0.059899,-0.255604,-0.243630,-0.097004,-0.235250,0.093718,0.262376,0.255135,0.033923,0.594834,0.289031,0.000070,-0.060148,0.441965,-0.022863,0.142036,0.165310,0.166816,-0.239805,0.174801,0.151556,-0.289195,-0.094216,-0.006410,0.121222,0.379211,0.441592,-0.028008,-0.271947,-0.157989,0.262875,0.047919,-0.319432,0.050272,0.187589,0.233573,0.257048,0.174569,-0.510808,0.125128,0.127142,0.110363,-0.448987,0.280808,0.085373,0.145271,-0.577318,0.365751,-0.095145,-0.199314,-0.092604,-0.534578,0.236347,0.374374,0.364380,0.307226,-0.196436,0.248516,-0.238462,0.381042,0.681798,0.077834,-0.295173,0.144972,-0.080066,-0.128584,0.212766,0.055131,-0.270381,-0.262214,0.149485,0.075229,-0.005959,-0.094588,-0.521666,0.163359,-0.118119,-0.046932,-0.144392,-0.262594,-0.067654,-0.384315,-0.053887,-0.138044,-0.358907,0.062388,0.235868,-0.201297,0.475118,-0.505740,0.024664,0.090999,0.227791,-0.416612,0.359860,-0.055808,0.322312,-0.084498,-0.007997,-0.185559,-0.120780,0.218495,0.281065,0.348281,-0.230961,-0.294296,0.011359,0.264323', '25908042', '1451563', '1292219', '26280899');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1889053', '芭萨提的颜色', '剧情', '影片中的英国女电影人苏，乃由末任香港总督彭定康幼女彭雅思饰演。镇压过印度革命者的英国警官被革命者视死如归的气概所感动，留下了一本记录当时情况的日记。多年后，他的孙女Sue（彭雅思 Alice Patten 饰）阅读日记后深受感动，凭着一腔热血辞掉电影公司的工作，来到印度拍摄这部记录那段历史的影片。Sue到德里大学的学生中选角。一群充满朝气却和芸芸大众一样对印度这个国家心如死灰的年轻人以及进入她的视野。开始的拍摄，麻醉于醉生梦死的的学生，对于当年那些为国捐躯的革命者的行为根本没法理解，致使迟迟不能进入角色。灾祸横至，国防部长的腐败导致朋友们中的飞行员Ajay（马德哈万 Madhavan 饰）遭遇了空难。Ajay为了防止平民受伤而献出了自己的生命，却因为政府高层的反唇覆舌而死后名誉受损。元凶逍遥法外。小伙子们恍然感觉到，自己体内的热血开始为枉死的朋友，为多难的祖国而沸腾……', '阿米尔·汗', '拉凯什·奥姆普拉卡西·梅赫拉', 8.5, 15741, 'tt0405508', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2188748198.jpg', 1.1, 2.6, 14.7, 34.7, 46.9, '0.244648,-0.063297,-0.590391,0.615918,-0.059384,-0.360525,0.587534,0.117352,-0.679958,-0.373464,0.209018,0.749403,-0.023175,0.450527,0.334032,-0.038158,-0.238205,-0.784299,-0.309579,-0.031982,-0.217016,-0.178958,-0.229177,-0.272931,-0.304828,-0.412567,0.897935,0.295649,-0.322891,0.381431,0.198284,0.325991,0.097366,0.316475,0.181772,0.030389,-0.069135,-0.137656,-0.420560,-0.008299,0.206440,-0.163312,-0.051444,0.204546,-0.019146,0.294073,0.721456,-0.198047,-0.093654,-0.310474,0.649967,-0.343439,-0.074924,0.263831,0.184694,0.277949,0.307229,0.206842,-0.011064,0.091896,-0.114117,-0.123327,-0.862708,-0.263741,0.071081,0.157109,-0.385548,0.372751,-0.165392,-0.027547,0.080566,-0.137244,0.131889,0.243885,0.140482,0.516274,-0.291947,0.012483,-0.261269,0.483934,0.540700,-0.104307,-0.398363,0.369104,-0.223428,-0.356540,0.003611,-0.305029,-0.408098,0.123094,0.087121,0.025789,-0.142835,0.292947,-0.567086,-0.155060,-0.223368,-0.379127,0.058531,-0.224840,-0.171613,-0.640300,-0.253033,-0.193252,0.021573,-0.084030,0.268433,-0.239634,1.012479,-0.702274,0.090076,0.504391,0.107588,-0.653033,0.515457,0.149519,-0.045199,-0.024250,-0.198188,0.472009,0.192714,0.472691,-0.087767,-0.016728,-0.192661,-0.355557,-0.137521,0.417640', '27602116', '25880986', '3811356', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1889152', '银行大劫案', '剧情', '本片根据真实历史事件改编。1971年，黑人激进组织领导迈克尔X因贩毒被控告，但因他一年前取得了英国皇室成员玛格丽特公主的私密照片并以此要挟官方而被开释。英国军情五处工作人员提姆（Richard Lintern 饰）受命取回收藏在伦敦某银行的这批照片。提姆物色到贩毒女子玛婷（Saffron Burrows 饰），要挟她抢劫银行来为自己取得照片。玛婷很快同以泰瑞（Jason Statham 饰）为首的几个半职业罪犯或新人组成了计划挖地道劫掠保险库的团伙。泰瑞等人如愿将保险库洗劫，但赃物却让他们坐立不安：涉及皇室成员的私密照片、银行家行贿官员的账本、高官们不可告人的龌龊爱好……由于一位无线电爱好者无意间听到了他们作案时的对话内容，此案掀起轩然大波，泰瑞等人陷入了各种势力争夺的中心，他只能借助手上的证据苦苦周旋……©豆瓣', '杰森·斯坦森', '罗杰·唐纳森', 7.5, 53884, 'tt0200465', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1060994552.jpg', 0.2, 2.2, 32.5, 51.2, 13.9, '0.319599,0.048023,-0.364757,0.486567,0.162810,0.102373,0.521637,0.181010,-0.755053,-0.338221,0.295322,0.463939,-0.213142,-0.118516,0.155313,-0.108799,-0.415243,-0.723681,-0.064983,-0.410998,-0.180042,-0.410842,-0.249562,-0.600196,-0.094377,-0.241451,0.533338,0.066579,-0.292136,0.195229,0.292739,0.244763,-0.444952,0.159731,-0.003073,-0.246751,0.487843,-0.170929,-0.268809,0.030336,-0.254351,-0.426228,-0.175103,-0.059680,0.072169,0.532015,0.573909,-0.060705,0.086969,-0.109142,0.350242,-0.233058,-0.082642,0.081085,0.511420,0.257287,0.214116,0.514641,-0.215138,-0.025442,0.157580,0.055047,-0.831518,-0.154482,0.032245,0.301688,-0.289503,0.364668,-0.464504,0.239277,-0.101517,-0.017439,0.257357,0.394766,0.183630,-0.047655,0.165249,-0.042884,-0.513387,0.475027,0.202481,-0.197555,-0.006168,-0.208720,-0.292319,-0.522612,0.098579,-0.210282,-0.143926,-0.032557,0.503078,-0.342035,0.020261,0.254929,-0.654222,-0.180314,-0.242958,-0.260892,0.211693,-0.326084,-0.053701,-0.918646,-0.242984,0.067036,-0.182272,-0.075018,0.336669,-0.003776,0.779142,-0.389018,-0.103359,0.839191,0.256116,-0.649083,0.471891,-0.045765,0.176088,-0.190525,-0.399149,-0.088955,0.527371,0.342034,0.077245,-0.011865,-0.021123,-0.471028,-0.002347,-0.064817', '3318306', '1309112', '258