INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1889242', '林肯', '剧情', '1865年，持续四年的美国内战进入了尾声，亚伯拉罕·林肯总统（丹尼尔·戴-刘易斯 Daniel Day-Lewis 饰）也迎来了他的第二个任期。在生命和任期的最后四个月，林肯一直在致力于一场比内战还艰苦的战役：推动宪法第13修正案在国会的通过。该法案将从法理上永久废除奴隶制在美国的存在。然而修正案提出的时机异常糟糕：废奴思想缺少人民的响应；国会为保守势力把持；支持废奴的激进派也不满林肯的作风。当分裂出去的南部州表达了重回谈判桌和终结内战的意愿后，林肯发现他面临一个两难的痛苦决定：是获得妥协的和平，还是坚守内心的道德？是结束奴隶制，还是结束战争？“假如奴隶制不是错误，那就没有对的了。”根据历史著作《对手的团队：林肯的政治智慧》改编，由普利策奖得主托尼·库什纳执笔，奥斯卡导演史蒂文·斯皮尔伯格执导，两届影帝丹尼尔·戴-刘易斯主演的传记大片《林肯》引领观众走近林肯一生中最伟大的成就：废除奴隶制。电影中的林肯是充满灵活智慧的政治家，也是运筹帷幄的三军统帅；是痛失爱子的慈父，也是心怀内疚的丈夫。当他的国家处在最迷惘的一刻时，林肯以超人的远见将目光及于战争之外，把全部心血投入到改变一个国家前进方向的伟大博弈中。他想说服美国人民：当不同肤色的人抬头仰望，看到的将是同一片星空。', '丹尼尔·戴-刘易斯', '史蒂文·斯皮尔伯格', 7.8, 49646, 'tt0443272', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1789645296.jpg', 0.5, 2.3, 26.5, 49.7, 21.2, '-0.002152,0.268017,-0.678492,0.775960,-0.082074,-0.209563,0.630895,0.093444,-0.444581,-0.042589,0.315023,0.897836,-0.151364,-0.147957,0.434661,-0.126291,-0.448800,-0.866067,-0.262757,0.138648,-0.200737,-0.600107,-0.271324,-0.268645,-0.291254,-0.369528,1.158106,0.341927,-0.341586,0.279914,0.454772,0.171797,0.290404,0.404404,-0.092419,-0.156711,-0.048839,-0.226481,-0.504279,0.214389,-0.049734,-0.275366,-0.136009,0.377097,-0.036730,0.305786,0.499776,-0.431992,0.059760,-0.047835,0.626197,-0.507792,-0.397342,0.171322,0.310459,0.137203,-0.243201,0.507280,-0.011473,0.083997,-0.124343,-0.086837,-0.871991,-0.110255,-0.109205,0.208183,-0.714749,0.667395,-0.105376,-0.209139,0.081770,-0.232004,0.208294,0.422981,0.178519,0.562004,-0.122972,0.005256,-0.522997,0.201592,0.614274,-0.172848,-0.544219,0.105833,-0.324702,-0.608831,0.033518,-0.476648,-0.332513,-0.174687,0.131764,-0.125832,0.032696,0.343225,-0.539496,0.012480,-0.202332,-0.602518,0.317992,-0.518161,0.043315,-0.463241,-0.176965,-0.412594,-0.130215,0.071018,0.067470,-0.337719,0.818443,-0.824584,0.078766,0.267340,0.403100,-0.471456,0.976182,0.300263,0.122513,-0.320973,0.033466,0.405127,-0.143968,0.206401,-0.183758,0.160589,0.161586,-0.118930,-0.221541,0.520409', '6101834', '25880986', '24875409', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1889243', '星际穿越', '剧情', '近未来的地球黄沙遍野，小麦、秋葵等基础农作物相继因枯萎病灭绝，人类不再像从前那样仰望星空，放纵想象力和灵感的迸发，而是每日在沙尘暴的肆虐下倒数着所剩不多的光景。在家务农的前NASA宇航员库珀（马修·麦康纳 Matthew McConaughey 饰）接连在女儿墨菲（麦肯吉·弗依 Mackenzie Foy 饰）的书房发现奇怪的重力场现象，随即得知在某个未知区域内前NASA成员仍秘密进行一个拯救人类的计划。多年以前土星附近出现神秘虫洞，NASA借机将数名宇航员派遣到遥远的星系寻找适合居住的星球。在布兰德教授（迈克尔·凯恩 Michael Caine 饰）的劝说下，库珀忍痛告别了女儿，和其他三名专家教授女儿艾米莉亚·布兰德（安妮·海瑟薇 Anne Hathaway 饰）、罗米利（大卫·吉雅西 David Gyasi 饰）、多伊尔（韦斯·本特利 Wes Bentley 饰）搭乘宇宙飞船前往目前已知的最有希望的三颗星球考察。他们穿越遥远的星系银河，感受了一小时七年光阴的沧海桑田，窥见了未知星球和黑洞的壮伟与神秘。在浩瀚宇宙的绝望而孤独角落，总有一份超越了时空的笃定情怀将他们紧紧相连……', '马修·麦康纳', '克里斯托弗·诺兰', 9.4, 1637713, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2614988097.jpg', 0.2, 0.4, 3.9, 21.5, 74, '0.167721,0.128662,-0.897783,0.538671,0.116990,-0.045076,0.728077,0.143820,-0.360016,-0.071679,0.073963,0.657143,-0.162848,0.124783,0.166194,0.041653,-0.265794,-0.355590,-0.274094,-0.340077,-0.396634,-0.618716,-0.463211,-0.106498,0.145839,-0.690882,0.566436,0.180942,0.122709,0.349117,-0.252164,0.376139,-0.342493,0.359816,-0.201543,-0.135275,0.224676,0.166681,-0.489037,0.188092,-0.287783,0.040608,0.123422,-0.042311,-0.128505,0.185930,0.731371,-0.287058,0.012378,-0.145369,0.291952,0.002312,-0.105154,-0.197697,0.397085,-0.188302,-0.113194,-0.044702,-0.013699,0.083201,0.129983,-0.109808,-0.643205,-0.133433,0.081492,0.271319,-0.435176,0.394415,0.021277,-0.250897,0.062555,-0.374772,0.135991,0.313999,0.034608,0.292184,-0.094384,0.034398,-0.324680,0.138523,0.367291,-0.051399,-0.365331,0.208121,-0.308482,-0.370380,-0.214032,-0.044971,-0.492710,-0.205963,0.308774,0.160642,-0.091047,0.332900,-0.605420,0.245253,-0.103192,-0.356344,0.172813,-0.301522,-0.325599,-0.652891,-0.030755,-0.183764,-0.307083,0.170807,0.055704,-0.026362,0.664912,-0.471844,0.596658,0.744578,0.446285,-0.135066,0.821520,-0.136161,0.229700,-0.449507,0.213603,0.575011,-0.053901,0.496490,0.044244,0.214746,-0.203836,0.088133,-0.503644,0.422891', '1298405', '2334814', '26682880', '3606973');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1890157', '相思成灾', '喜剧', '贾克斯（布莱特妮•墨菲 饰）住在伦敦，是英国时尚杂志《VOGUE》的小助理，周围聚集着一堆时尚界、艺术界的朋友。她和最亲密的同性恋友人彼得(马修•瑞斯 饰)住在一起，和前男友詹姆斯分手后保持着肉体关系，她生活中最大的乐趣就是给自己的朋友当媒人，帮助他们处理感情上的各种问题。一天，贾克斯认识了才华横溢、帅气性感的杂志新摄影师助理保罗（圣地亚哥•卡布瑞 饰），她想当然地要把保罗和彼得撮合在一起，展开了她的行动。不过这个无厘头的丘比特似乎太忙于撮合别人的感情，而没有时间认真审视自己的情感。©豆瓣', '布莱特妮·墨菲', '阿莱克·凯西西恩', 7.4, 47625, 'tt0452643', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p553573002.jpg', 0.7, 4.5, 35.9, 43.1, 15.8, '0.647016,-0.169984,-0.666070,0.735406,-0.259530,-0.525483,0.810095,0.353408,-0.578112,-0.266215,-0.047195,0.453074,-0.180802,0.340945,0.321746,0.010375,-0.660943,-0.808274,-0.013726,0.054533,-0.229790,-0.747548,-0.314496,-0.180648,-0.256993,-0.203216,0.252348,-0.341210,-0.061387,0.370930,0.404248,0.146873,0.136202,0.437701,-0.025665,-0.026995,0.236376,-0.093100,-0.417049,0.238178,0.200588,0.073965,0.037498,0.216882,0.181345,0.291873,0.631747,-0.057717,0.043675,-0.028364,0.239934,-0.188640,0.252913,0.149029,0.140006,0.036538,0.352036,0.006253,-0.161334,-0.192000,0.200385,-0.101087,-0.543961,0.136427,-0.186877,0.285213,-0.617087,0.511828,-0.142390,-0.135171,0.067735,-0.460128,0.234009,0.369738,0.370600,0.000042,-0.186524,0.129548,-0.357794,0.348542,0.559075,0.365596,0.026218,0.267521,-0.583210,-0.213972,-0.165231,0.051141,-0.649204,-0.191520,0.293198,-0.318765,0.038043,0.438945,-0.687707,-0.172379,-0.224816,0.009740,-0.054009,-0.595958,0.236531,-0.800207,-0.280641,-0.727178,-0.393021,-0.229565,0.086690,-0.312637,0.762279,-0.823511,0.046252,0.635937,0.554731,-0.179572,0.756019,0.263318,0.111070,-0.413484,-0.194530,0.184026,-0.047324,-0.058113,0.190562,0.440966,0.354897,0.166279,-0.309556,0.787777', '26677495', '3230121', '27605105', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1890558', '大丈夫2', '剧情', '添（曾志伟 饰）、Dr Lee（陈小春 饰）、娇（张达明 饰）以及大学生阿仔（黄又南 饰）平日在老婆或女友面前总是毕恭毕敬，百依百顺。其实四人都心怀鬼胎，那就是在取得他们的另一半信任之后找机会出去鬼混。Mary（毛舜筠 饰）、绮贞（原子鏸 饰）、娇妻（何超仪 饰）和阿Ling（林苑 饰）是四人的伴侣，一开始她们都以为自己的另一半对自己始终如一。但四人渐渐识穿了男人们的诡计，羞愤之余，四人订立了攻守同盟，决定一起出去鬼混，以牙还牙。男人们知道了自己的另一半亦开始红杏出墙后，大为紧张，开始跟踪自己的老婆或女友。他们之间的危机最终能否顺利化解？©豆瓣', '曾志伟', '钟晴', 6.1, 6756, 'tt0860387', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2293675814.jpg', 2.9, 16.6, 56.4, 18.2, 5.9, '0.103704,-0.041284,-0.561013,0.540206,-0.090092,-0.316463,0.449789,0.170022,-0.331369,0.011677,0.088859,0.426119,-0.082867,0.328929,0.129497,-0.148302,-0.414206,-0.861205,-0.099964,-0.276600,-0.316760,-0.192685,-0.025463,-0.147990,-0.232492,-0.135650,0.255476,-0.237239,0.040032,0.349914,0.816211,0.184572,-0.190212,0.399537,0.014026,0.115196,0.046922,0.013202,-0.410186,-0.026212,0.069540,-0.119253,-0.262230,0.076690,-0.012449,0.331966,0.833964,-0.132144,-0.187064,-0.239633,0.291725,0.102518,0.164851,0.350959,0.107166,-0.077074,0.509334,0.058862,-0.109731,0.141597,0.383047,0.316375,-0.442796,0.256348,0.176805,-0.035959,-0.354903,0.327158,0.074509,0.056093,0.338572,-0.356666,0.118196,0.382854,0.199043,0.105021,-0.247284,-0.027635,-0.549816,0.281783,0.472874,0.143581,0.230872,0.248287,-0.022627,-0.286527,0.009265,-0.038146,-0.425420,-0.278850,0.437608,0.106269,0.034169,0.049751,-0.374335,-0.143414,0.094191,0.140691,-0.043170,-0.503690,0.218187,-0.392288,-0.129910,-0.488619,-0.290546,0.272572,0.101137,-0.153993,0.641756,-0.768654,0.123284,0.360086,0.295323,-0.832827,0.440560,0.291593,0.094035,-0.329645,-0.103886,-0.092445,-0.031727,-0.051643,0.296700,0.395422,-0.059430,0.142421,-0.216342,0.214058', '1301022', '26730542', '4301278', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1890569', '第601个电话', '剧情', '600个明星的电话号码曝光后，迷糊精易淑（周笔畅）的电话号码因与其中之一大明星天佑（张柏芝）的仅相差一位，成为“第601个电话”，平静简单生活自此变成啼笑皆非的闹剧。就在她不胜其烦要换号码时，接到身患重病的大男孩阿文（胡歌）的电话，听过阿文的故事，易淑决定抛弃原有的生活去寻找天佑，帮助阿文达成心愿——希望听到心爱的偶像天佑演唱自己写的一首歌。而站在绚丽舞台上的天佑，在收获鲜花和掌声的同时，有着常人无法理解的压力，她在等待一个机会，来像易淑一样下定决心改变自己的旧生活。©豆瓣', '张柏芝', '张国立', 4.7, 14102, 'tt0865448', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2362488915.jpg', 18.9, 38.4, 33.6, 4.9, 4.1, '0.314227,0.236431,-0.478218,0.674628,-0.110070,-0.195593,0.760253,0.358496,-0.178383,-0.261635,0.247459,0.826475,-0.225047,0.347407,0.274813,-0.275591,-0.267366,-0.717001,0.341843,0.056529,0.070295,-0.633661,0.011405,-0.163599,0.108401,-0.305964,0.587966,-0.091990,-0.072403,0.503097,0.375423,0.129537,-0.108347,0.295126,-0.279085,0.172048,-0.248680,0.267041,-0.248320,0.230647,-0.191901,0.187624,0.006451,0.215404,-0.046187,0.020844,0.604298,-0.215961,-0.288180,0.254755,0.628305,0.069974,-0.032949,0.098360,0.140785,0.361559,0.262983,0.093617,-0.433790,0.090245,-0.175200,-0.028952,-0.876426,0.226586,0.120988,0.312158,-0.420080,0.630628,-0.050069,-0.218997,-0.063613,-0.198305,0.236248,0.586208,0.294624,0.619126,-0.368978,0.548208,-0.225269,0.136751,0.613490,0.159724,-0.015256,0.611469,-0.153360,-0.176761,-0.111847,-0.098059,-0.595696,0.035066,0.195719,-0.049534,-0.268180,-0.120124,-0.404374,0.033611,-0.394619,-0.209852,0.144482,-0.376476,-0.452200,-0.284737,-0.170907,-0.031955,-0.276777,0.132684,0.007255,-0.440121,1.152276,-0.800102,0.065061,0.333084,0.010371,-0.681489,0.695299,0.376291,-0.254405,-0.382351,-0.064163,0.495475,-0.265832,0.116637,-0.065895,0.070051,-0.314922,-0.017281,-0.523665,0.321544', '27602116', '24284209', '26348103', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1890572', '坠入', '剧情', '电影特技演员罗伊•沃克（Lee Pace 饰）在拍摄一组骑马从桥上一跃而下的镜头时严重受伤，导致下半身瘫痪失去知觉。此时的他极度绝望，万念俱灰，只想一死了之。正当罗伊沮丧之际，因摔断胳膊住进医院的5岁小女孩亚历珊卓（Catinca Untaru 饰）闯入了罗伊的世界。这两个年龄悬殊的病友就此交上了朋友，亚历珊卓每天来罗伊的病房报到，只为听朋友讲那个玄幻神奇的故事。而罗伊用这个顺口编出的故事吸引小女孩，却想完成借机完成他的自杀计划……本片荣获2007年柏林影展玻璃熊特别表扬-最佳影片奖、Sitges - Catalonian International Film Festival的最佳影片奖、2008年奥斯汀影评人协会奖最佳剧本。©豆瓣', '凯婷卡·安塔鲁', '塔西姆·辛', 8.8, 113530, 'tt0460791', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p568541514.jpg', 0.3, 1.2, 9.6, 35.4, 53.6, '0.273078,0.058511,-0.451140,0.107664,0.089852,-0.173568,0.638241,0.032235,-0.207272,-0.187753,0.352544,0.575777,-0.506430,0.334480,0.306984,-0.081390,-0.368428,-0.567826,-0.079667,0.073764,-0.221824,-0.328403,-0.159337,-0.117563,-0.153248,-0.451626,0.690521,-0.204115,-0.042872,0.439512,0.321963,0.164029,0.070731,0.057970,0.098687,0.331116,0.291097,0.019473,-0.102519,0.386548,0.033307,-0.242762,-0.086555,0.138134,-0.232069,0.329962,0.756557,0.034647,-0.247576,0.145279,0.733200,-0.315149,-0.149930,-0.079038,0.222151,-0.155612,0.065974,-0.125464,0.028051,0.056858,0.018191,-0.057888,-0.680881,0.212336,0.141506,0.069469,-0.485363,0.243368,-0.259916,0.330755,0.080837,-0.260102,-0.053752,0.316119,0.351647,0.311288,-0.166874,0.078257,-0.163048,0.554494,0.372133,-0.050717,-0.381402,0.384201,-0.263230,-0.467880,0.062179,0.007415,-0.198056,0.010717,0.391950,-0.044305,-0.144877,-0.217460,-0.181125,-0.072673,-0.066571,-0.088409,-0.155063,-0.199247,-0.068532,-0.540737,0.090584,0.221058,-0.118105,-0.219466,-0.067195,-0.215939,0.503277,-0.183781,0.323687,0.571526,0.163344,-0.025173,0.623536,-0.058013,-0.063755,-0.218981,-0.010269,0.493863,-0.170173,-0.009283,0.171211,0.234603,-0.121825,-0.157962,-0.639286,0.568824', '4135443', '2027945', '6537486', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1890784', '门徒', '剧情', '阿昆（刘德华饰）长年垄断了海洛因市场，虽视追随8年多的阿力（吴彦祖饰）为接班人，但阿昆一向小心行事，从没透露过“货仓“、加工场的位置也未见过其他“同事”。阿昆打算把自己的生意全权交由阿力打理，阿力渐渐知道了更多毒品市场中的秘密。8年来阿力以卧底的身份搜集毒贩的全部资料，但他对吸毒者阿芬（张静初饰）投入了感情，阿芬的景况却令他对自己边缘人的身份感到更加迷惘。斗志斗勇的过程中，阿力最终取得了阿昆的完全信任，8年来的追踪，也有了终结。©豆瓣', '刘德华', '尔冬升', 8, 279254, 'tt0841150', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1181944920.jpg', 0.2, 1.2, 22.5, 52.4, 23.7, '-0.049047,0.065535,-0.570092,0.412765,-0.276180,-0.256753,0.420111,0.000620,-0.769924,-0.163912,0.038465,0.545056,0.053951,-0.074745,0.070529,-0.029638,-0.137837,-0.667705,-0.270007,-0.329307,-0.150357,-0.470412,-0.357120,-0.321759,-0.280995,-0.177779,0.446510,0.105746,-0.042129,0.333399,0.130721,-0.038118,0.084696,0.620158,0.106603,-0.062532,0.078949,-0.017632,-0.402101,-0.064579,0.136792,-0.308912,-0.167603,0.168786,0.191658,0.564682,0.546741,-0.152264,-0.280526,-0.026325,0.220819,-0.040766,0.178294,-0.096615,0.267706,0.180113,-0.011478,0.440821,-0.396633,0.002878,-0.005322,0.019082,-0.915411,-0.048342,0.072648,0.096637,-0.639941,0.429007,-0.275965,0.113705,-0.099577,-0.282337,0.283940,0.117980,0.277088,0.099866,-0.084670,-0.108379,-0.337861,0.315052,0.438192,-0.156129,-0.009706,0.420993,-0.350129,-0.529714,-0.211792,-0.353349,-0.143062,-0.079854,0.176787,0.276835,-0.284370,0.283921,-0.562132,-0.010748,-0.005166,-0.307455,-0.057345,-0.382867,0.088457,-0.314213,-0.435276,-0.698333,-0.230529,-0.022397,0.096744,-0.145518,0.748537,-0.687535,-0.013098,0.517683,0.373571,-0.726270,0.584622,-0.072305,0.052428,-0.185974,-0.307320,0.117477,0.046489,0.208981,0.257961,0.254251,0.098567,-0.580625,-0.095760,0.310492', '26678784', '6557030', '1793491', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1890787', '心中有鬼', '剧情', '30年代上海，电影摄影师沈君初（黎明饰）深爱着自己的女友播音员徐曼丽（范冰冰饰），但因性格内向无法开口向女友求婚。在懊丧中曼丽播出了一个自己编写的广播剧。在广播剧中，摄影师君初因为错过了曼丽的结婚请求而懊悔不已，他买了戒指约曼丽见面的时候曼丽被车撞死。君初日后一直生活在对曼丽的思念中。之后出现了另一个女人妻子三三（刘若英饰），但君初并不理会三三。而三三虽深爱着君初，却也无法让他快乐。直到有一天，三三看到了徘徊不去的曼丽，她教给三三如何接近君初让君初快乐……广播剧结束了，君初听到了曼丽的故事，写了一封信向曼丽求婚，曼丽接到信后飞奔去了约会的地方，就是广播剧故事当中他们约会的南京路口……©豆瓣', '黎明', '滕华涛', 5.5, 12850, 'tt0819785', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1033993060.jpg', 6.1, 26.6, 54.1, 10.6, 2.6, '0.286016,-0.060743,-0.909242,0.468851,0.226225,-0.362173,0.983361,0.216981,-0.077316,0.019561,-0.003223,0.854000,-0.332009,0.464045,0.222411,0.006456,0.005637,-0.908302,0.095835,-0.327922,-0.010465,-0.432417,0.162108,0.040601,0.164413,-0.031179,0.324208,-0.110517,0.067953,0.602334,0.395927,-0.051425,-0.331007,0.488293,-0.005344,0.148363,-0.009870,0.260493,-0.377419,0.239244,0.029889,-0.162782,-0.284054,0.311155,-0.257705,0.360404,0.616957,-0.271907,0.012996,0.056759,0.444009,0.259319,-0.203103,-0.026383,-0.009473,-0.089232,0.458270,0.379606,-0.366715,0.139259,-0.290277,0.070062,-0.506704,0.372238,-0.161638,0.404606,-0.583425,0.279733,-0.118319,0.114018,0.213181,-0.412143,0.173024,0.198861,0.427080,0.238841,-0.189350,0.039504,-0.327258,0.482531,0.465474,0.056093,-0.107508,0.589792,0.441324,-0.116796,-0.011233,0.104129,-0.795295,0.223129,0.085621,0.206554,-0.369516,-0.173194,-0.613404,-0.065230,-0.239674,-0.171781,-0.054174,-0.218045,-0.317155,-0.360104,-0.006600,-0.344380,-0.401283,0.007048,0.306471,-0.451030,0.973473,-0.785444,0.226321,0.568748,0.479643,-0.671693,0.769500,0.665938,-0.170660,-0.180590,0.347378,0.129275,-0.350529,0.215360,0.443792,0.081929,-0.149160,-0.323833,-0.627247,0.458437', '1307146', '3111650', '4847665', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1891157', '神偷艳贼', '喜剧', '哈里（柯林·菲尔斯 Colin Firth 饰）供职于一家生意红火的画廊，日子尚且能够算是过得平静而又富足。但是，令哈里感到沮丧的是，人过中年的他要头脑有头脑，要能力又能力，可即便如此，还是要整日受自己的讨厌鬼老板沙班达尔勋爵（艾伦·瑞克曼 Alan Rickman 饰）的气。当最后一根稻草压上脊背时，忍无可忍的哈里决定要凭借自己的聪明才智，好好的将老板一军。完美的复仇计划新鲜出炉，万事俱备唯缺一位重要的关键人物，于是，哈里将目光投到了一位名叫PJ（卡梅隆·迪亚茨 Cameron Diaz 饰）的德州女牛仔身上。没想到，正是这个女牛仔将哈里的整个计划搅得乱七八糟，焦头烂额之中，哈里发现，事态正在朝着他无法控制的方向渐渐的发展而去。©豆瓣', '卡梅隆·迪亚兹', '迈克尔·霍夫曼', 6.3, 14529, 'tt0404978', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1838933043.jpg', 1.6, 12.7, 58.4, 21.5, 5.8, '0.011382,0.190255,-0.482724,0.417424,-0.081231,-0.507462,0.500126,0.278784,-0.598362,-0.381349,0.119202,0.552337,-0.077726,0.141469,0.475254,0.341439,-0.115673,-0.699399,-0.145220,-0.105118,-0.137579,-0.504509,-0.255985,-0.405474,-0.260784,-0.274662,0.443174,0.137273,0.122535,0.150992,0.534328,0.386740,0.294733,0.292438,-0.249873,-0.183728,0.040658,-0.476543,-0.221859,0.118145,0.291448,-0.083068,-0.192119,0.342636,0.120548,0.176374,0.644908,-0.022651,-0.087623,0.066951,0.354216,-0.139225,0.019555,0.263779,0.230296,0.020135,-0.003096,-0.048301,-0.213112,-0.017055,0.348027,-0.318370,-0.842853,0.163614,0.136397,0.238627,-0.613567,0.046291,-0.137173,-0.053302,0.057415,-0.509692,-0.024116,0.193713,0.431326,0.437801,-0.007978,0.157555,-0.244378,-0.131115,0.526774,0.099537,-0.233606,0.378828,-0.284895,-0.108830,-0.027741,-0.216113,-0.401144,-0.216705,0.384265,0.274071,-0.086194,0.444852,-0.437017,-0.010468,-0.425732,-0.313104,-0.053385,-0.214665,0.037560,-0.222865,-0.141423,-0.368161,-0.059226,0.152912,0.101698,-0.122855,0.554862,-0.566555,-0.060435,0.626810,0.053501,-0.186198,0.393274,-0.034089,0.174392,-0.112337,-0.157276,-0.004831,0.103776,0.169259,0.159355,0.445611,-0.229925,-0.506547,-0.337945,0.428832', '1793491', '25928048', '26678784', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1891179', '梅兰芳', '剧情', '京剧艺术大师梅兰芳先生的传记电影，但多处描写与史实不符。唱了大半辈子戏的大伯因在西太后寿辰中顾及家中出殡未穿红被赐一纸枷锁后，少年梅兰芳将他临死留下的一封书信随身携带，开始跟随与梅家有世交的京剧老生名角十三燕（王学圻）学唱戏、做人。十年后，梅兰芳（余少群）在梨园崭露头角，想着能一辈子清清白白唱戏、做人。对戏剧艺术有颇深研究的留洋司法局长邱如白（孙红雷）满腹牢骚于传统京剧，却在看过梅兰芳的演出后难抑激动，提笔给他写下鼓励、建议书信。梅兰芳也想创新表演，对邱如白十分感激。两人封封书信往来、见面促膝长谈中，梅兰芳对京剧的理解日渐加深、翻新，并收获“三哥”邱如白持续一辈子的单纯情谊。但梅兰芳也因此与十三燕生出分歧。两人在好事者的怂恿下决定对打擂台，梅兰芳大获全胜，迎来自己的时代。梅兰芳能成功，除了自个有非一般的悟性、邱如白时刻在艺术上将他鼓励外，尚因大银行家“六爷”冯子光（英达）在财力上慷慨相助。之后，梅兰芳（黎明）迎娶福芝芳（陈红），开始试图过台上销魂女子、台下一般男子的生活，却注定如身戴“纸枷锁”般难如愿：结识当红须生孟小冬（章子怡）后，他与之结成精神上的伉俪，却抱憾擦身；抗日时期，为了表气节，他蓄须忍痛离别心爱的舞台。期间助他在国际舞台上大放光彩的赴美演出，亦是好事多磨。', '黎明', '陈凯歌', 6.9, 114850, 'tt0851532', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p581429949.jpg', 1, 6.3, 47.3, 37.3, 8.1, '-0.038464,0.147335,-0.605665,0.568085,0.211655,-0.232474,0.585541,0.090946,-0.404997,-0.082174,0.281038,0.827870,-0.382294,0.230668,0.080246,-0.416958,-0.153242,-0.714571,0.068537,0.108827,0.041908,-0.321463,-0.006355,0.183094,-0.504568,-0.298082,0.463065,0.135192,-0.273103,0.618504,0.385555,-0.115904,0.004577,0.160893,-0.243956,-0.016256,-0.177452,0.179905,-0.455009,-0.066826,0.205065,-0.146626,-0.282186,-0.010553,0.017309,0.125381,0.543681,-0.116600,0.049230,0.070687,0.315856,0.131730,0.028746,0.256132,0.053861,0.313318,0.136206,0.373462,-0.129110,-0.043135,-0.245898,-0.199905,-0.398340,0.073566,0.202979,0.267721,-0.481441,0.645995,0.007706,-0.038002,-0.208744,-0.171484,0.117174,0.113447,0.394415,0.236841,-0.135490,-0.036618,-0.186594,0.551072,0.311895,0.110229,-0.081933,0.370825,-0.203858,-0.368852,0.268457,-0.298227,-0.289740,0.046487,0.211569,-0.129241,-0.039355,0.063229,-0.324612,-0.081372,-0.015073,0.209289,0.084501,-0.396065,0.049685,-0.582826,-0.208823,-0.396761,-0.321313,-0.165844,0.321636,-0.520852,0.848941,-0.620321,0.202672,0.098606,0.204030,-0.424073,0.711461,0.353663,0.083629,0.021592,-0.025292,0.153121,-0.218627,-0.012934,0.072352,0.227537,-0.213686,-0.112329,-0.291790,0.534201', '1307146', '30162520', '1870681', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1891211', '霍顿与无名氏', '喜剧', '在名为欧诺的热带丛林中，小象霍顿（金·凯瑞 Jim Carrey 配音）和朋友们自由自在地生活于此。某天，一粒灰尘闯入霍顿的世界。当灰尘经过他面前时，他仿佛听到微弱的求救声。经过一番手忙脚乱的追逐，霍顿终于在一朵花上找到了那粒灰尘。原来灰尘上有一个“无名镇（呼呼镇）”，当地人民原本生活安泰，无忧无虑，但一枚滑落的果实却将“无名镇”所在的灰尘从苜蓿花蕊上撞向天空。这一变故让即将迎来百年庆典的“无名镇”出现诸多怪事，偶然机缘，小镇镇长麦多多和霍顿间取得了联系。为了让小镇重新回到稳定状态，霍顿决定带着他们回到原有的世界……本片根据苏斯博士（Dr. Seuss）的同名小说改编。©豆瓣', '金·凯瑞', '吉米·海沃德', 7.8, 44320, 'tt0451079', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p890145762.jpg', 0.4, 2.4, 26.1, 47.7, 23.4, '0.109078,0.558645,-0.662305,0.553407,0.256977,-0.276258,0.638093,0.198841,-0.311590,-0.202127,-0.016147,0.717474,-0.410415,0.376122,0.270815,-0.019236,-0.393699,-0.614313,-0.125106,-0.352130,-0.522297,-0.098387,-0.438291,-0.207366,-0.247671,-0.205714,0.632166,0.430118,-0.220207,0.571898,0.007427,0.222832,-0.218993,0.356451,-0.511475,-0.006150,-0.067796,0.248091,-0.250782,0.191641,-0.143967,-0.156356,-0.118730,-0.267154,0.385852,0.143700,0.879569,-0.409720,-0.136770,-0.149151,0.224313,0.043809,0.160141,-0.051885,0.112691,0.196116,0.154247,0.177813,-0.304383,-0.109844,0.085694,-0.321508,-0.372582,-0.120684,-0.041223,0.210836,-0.485028,0.299792,0.166928,-0.201787,0.053308,-0.435543,0.392863,0.312320,0.056672,0.398771,-0.344526,0.150338,-0.331528,0.008059,0.532993,0.054720,-0.175170,0.308106,-0.100294,-0.231245,0.002963,0.192892,-0.071057,-0.201185,0.412538,0.029963,-0.003873,0.236418,-0.686186,-0.076259,-0.296778,-0.427686,0.155555,-0.003225,-0.542041,-0.580125,-0.103565,-0.040903,-0.354765,-0.033293,-0.063271,-0.152639,0.687303,-0.624325,0.464380,0.412427,-0.079095,0.219177,0.401647,-0.124840,0.203051,-0.320743,-0.144394,0.315473,0.206749,0.778449,0.176755,0.157463,-0.403280,-0.060663,-0.445414,0.523377', '21619567', '1309194', '1467779', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892134', '夺命来电', '科幻', '故事中每个人都被手机所控制，开始恶意攻击任何靠近他们的人，而这些“手机僵尸”并未死去，而是可以互相通信结成团伙…', '塞缪尔·杰克逊', '托德·威廉姆斯', 4.5, 5966, 'tt0775440', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2518745320.jpg', 15.2, 49.1, 30.7, 3.6, 1.4, '0.729125,-0.109930,-0.579154,0.524361,-0.304772,0.558475,1.000861,-0.282630,-0.895459,-0.284699,-0.475030,0.384810,-0.007182,0.108475,-0.638947,-0.284614,-0.288901,-1.041450,-0.080031,0.081258,-0.330631,-0.157072,0.015076,-0.640592,-0.137964,0.054303,0.453621,0.234281,-0.452313,0.396020,-0.148170,-0.000285,-0.833108,0.854890,0.134165,0.039008,-0.368709,-0.593009,0.040228,0.176597,-0.479174,-0.069018,-0.024527,1.080971,-0.127032,0.568889,0.908019,-0.532108,-0.071959,-0.462396,-0.171636,-0.204502,-0.009430,0.258753,0.126103,0.515349,0.982922,0.146980,0.476160,0.520319,-0.013630,0.420636,-0.873077,0.114549,-0.383712,0.407947,-0.224414,0.283916,-0.131574,0.299976,-0.507465,-0.079430,0.451781,-0.025103,0.173652,-0.097279,-0.757145,-0.350684,-0.680593,0.006712,0.615908,0.022673,-0.463909,0.211134,0.169450,-0.447639,-0.430670,0.161375,-0.185994,-0.032910,0.404533,0.791521,-0.198655,0.326231,-0.857904,0.358964,-0.212833,-0.008166,-0.098032,-0.984498,0.116572,-1.018681,-0.148244,0.050806,-0.591386,0.402498,0.057972,-0.207953,0.552680,-0.752128,0.047978,0.709248,0.624603,-0.461285,0.002218,-0.011348,0.081431,-0.004272,-0.491859,0.426548,0.538300,0.694829,0.061586,-0.204923,0.006319,0.260813,-0.219823,0.352410', '10466639', '4023433', '25774050', '3230023');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892147', '杀出狂人镇', '剧情', '坐落于美国宾夕法尼亚州的奥格登·马什镇，景色美丽宜人，生活安逸自在。但是，一起突发事件打破了小镇的宁静。原本性格温和的中年男子罗瑞（Mike Hickman 饰）手提步枪闯入正在进行棒球比赛的赛场，治安官戴维（蒂莫西·奥利芬特 Timothy Olyphant 饰）果断出击，将其射杀。惨剧似乎一发不可收拾，在此之后，各种血腥残酷事件接二连三发生，原本爱好和平的小镇人民一个个狂性大发，仿佛天堂般的小镇变成了恐怖的人间地狱。戴维和几个理智尚存的伙伴发现，镇民疯狂的原因与当地的饮用水有关。与此同时，为防止狂病蔓延，政府派出军队封锁小镇。戴维他们必须绞尽脑汁逃离这片死亡之地……©豆瓣', '蒂莫西·奥利芬特', 'Breck Eisner', 6.3, 15574, 'tt0455407', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2210461329.jpg', 2, 14.2, 57.8, 20.9, 5.1, '-0.034481,0.126141,-0.518609,0.343966,0.059602,0.370141,0.684575,0.192632,-0.286999,-0.119588,0.387127,0.420344,-0.148874,-0.174745,0.388641,-0.161726,-0.236144,-0.577400,-0.081244,0.009596,0.000829,-0.151158,-0.295117,-0.317870,0.077324,-0.458423,0.535557,0.224349,-0.113844,0.516995,-0.170938,0.442312,-0.488931,0.377718,-0.103448,-0.310860,0.068599,-0.268077,-0.555824,0.027386,-0.196451,-0.022845,-0.213006,0.221478,0.144880,0.226169,0.855955,-0.279588,-0.227041,-0.147141,0.388145,-0.252852,-0.049802,0.169926,0.374216,-0.106187,-0.025046,-0.011260,-0.162318,-0.072270,0.222974,-0.212357,-0.107969,0.231578,0.052300,0.116539,-0.138592,0.192151,0.117223,-0.114969,0.153189,-0.086662,0.102073,0.369743,0.394384,0.221720,0.062434,0.020396,-0.255591,-0.027980,0.889933,-0.244162,-0.393800,-0.061801,-0.480929,-0.174266,-0.004150,-0.222549,-0.292808,-0.187310,0.279617,-0.247940,-0.019736,0.542630,-0.715603,-0.030532,-0.343395,-0.437402,0.000183,-0.031063,-0.639636,-0.824016,-0.003531,0.009138,-0.120843,0.291212,-0.260838,0.375067,0.398429,-0.533604,0.286759,0.495851,0.080911,-0.223275,0.032342,-0.077607,0.171694,-0.039381,-0.142220,0.698360,0.324403,0.607281,-0.062198,0.088345,-0.337148,-0.105551,-0.213544,0.609330', '2269893', '10466639', '1914923', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892510', '保姆日记', '剧情', '安妮（斯嘉丽•约翰逊 饰），一名出身于普通工人家庭的纽约大学毕业生，带着母亲的殷切希望准备成为一名成功的职业女性。但是，就在安妮对自己的前途与未来感到迷茫的时候，一个意外却打破了她原本的生活轨迹，她在纽约上东区第五大道的X家找到了一份保姆的工作——全天候照顾X家四岁的儿子格莱尔。但是，这份收入不菲的工作却不像自己想象中那么轻松。除了和任性淘气的格莱尔打交道外，安妮还要负责一些家中的杂活儿，同时隐瞒母亲自己现在的工作。而富有的X家似乎也不像那样光鲜，X先生整日忙着赚钱，不在家中；X太太则忙于购物、打扮、社交，偶尔还对安妮的工作吹毛求疵，夫妇俩不但无暇顾及儿子格莱尔，而且婚姻似乎还出现了裂痕。而此时，一个帅气的富家子弟哈佛（克里斯•伊文斯 饰）却闯进了她的生活。卷入这一切的安妮是否能当好这个富家保姆？她与哈佛将情归何处……©豆瓣', '斯嘉丽·约翰逊', '莎里·斯宾厄·伯曼', 6.9, 44235, 'tt0489237', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p620203080.jpg', 0.4, 4.9, 52.2, 34.5, 8.1, '0.355894,-0.003581,-0.661609,0.625768,-0.451102,-0.564974,0.841157,0.353460,-0.359515,-0.464618,0.099246,0.849195,0.191777,0.339943,0.094401,0.209540,-0.382123,-0.635329,-0.022854,0.011052,-0.123773,-0.422197,-0.220681,-0.146175,-0.197222,-0.258405,0.477113,-0.051293,-0.069863,0.458473,-0.057884,0.165106,0.129388,0.542407,-0.338835,-0.095094,0.115450,0.324131,-0.034930,0.107453,0.177993,-0.009560,-0.087068,0.170905,0.285551,0.430559,0.579299,0.083702,-0.211669,-0.151070,0.371897,-0.130143,0.036951,0.172511,0.169102,-0.047050,0.266027,-0.065082,-0.289257,0.154988,0.047680,-0.296378,-0.870654,-0.096744,0.155724,0.217280,-0.777142,0.510354,-0.160935,-0.266993,0.079870,-0.325468,0.120770,0.480147,-0.078650,0.484833,-0.408070,0.296847,-0.711106,0.180996,0.595233,0.080970,-0.330812,0.487554,-0.396598,-0.168675,0.050788,-0.215069,-0.820682,-0.170508,-0.039739,0.049507,-0.095611,0.248567,-0.441684,0.191957,-0.124779,-0.069210,-0.111868,-0.634763,-0.221787,-0.518097,0.011305,-0.606427,-0.560178,-0.203722,0.232101,-0.327838,0.845029,-0.829065,0.185195,0.413724,0.307738,-0.578784,0.794709,0.344770,0.399213,-0.211651,-0.250741,-0.021734,-0.072680,0.224267,0.041222,0.407644,-0.018112,-0.315625,-0.247963,0.637729', '1783461', '4847665', '24