INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892530', '东方的承诺', '剧情', '圣诞节，一个14岁的俄罗斯少女因难产而死在伦敦一家医院，俄裔助产士安娜（娜奥米·沃茨 饰）觉得事有蹊跷，暗中调查少女的来历，却发现少女不但是一个偷渡客，而且还是深陷性交易的雏妓。安娜在叔叔的指点下找到了偏僻的伦敦俄裔社区。原本，安娜只想向叔叔老朋友西蒙（阿明·缪勒·斯塔 尔 饰）了解情况，但在偶遇神秘而阴郁的尼古拉（维果·莫腾森 饰）之后，却发现真相超出想象的复杂。西蒙原来是黑道家族的教父，尼古拉与其关系非浅，二人掌控着整个伦敦的地下色情网。在西蒙的授意下，尼古拉阻止安娜的调查，不想却把黑帮的罪恶隐情曝光，很快，意想不到的背叛、报复与谋杀发生了……©豆瓣', '维果·莫腾森', '大卫·柯南伯格', 7.6, 23652, 'tt0765443', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2186264487.jpg', 0.5, 3.2, 31, 48.3, 17, '0.674225,-0.030934,-0.499540,0.333419,0.127675,-0.235208,0.859209,0.200523,-0.601730,-0.435069,0.408652,0.640150,-0.145702,0.252312,0.340023,0.343525,-0.514022,-0.593122,0.193515,-0.173620,-0.198893,-0.829023,-0.382846,-0.138550,0.049893,-0.351657,0.379491,0.212410,-0.237625,0.441909,0.181361,0.408297,-0.265012,0.378364,0.036285,-0.139958,0.485686,-0.148853,-0.347263,0.151959,0.214260,-0.242001,-0.160424,0.225771,0.105840,0.540652,0.238758,-0.240906,-0.229974,-0.123116,0.336234,-0.243220,0.020192,0.086989,0.258808,-0.112702,0.100623,0.241039,-0.333563,-0.202621,0.194451,0.137117,-0.615980,0.452091,0.273714,0.649928,-0.476691,0.266194,-0.291142,-0.184295,0.073202,-0.263428,0.110060,0.596196,0.178199,0.155390,-0.075015,0.165205,-0.676493,-0.304939,0.752590,0.016739,-0.148784,0.154216,-0.057740,-0.302606,-0.168266,0.111111,-0.431659,0.211058,0.221582,-0.125098,-0.274315,0.510582,-0.339936,-0.289785,-0.457975,0.084082,-0.140715,-0.369785,-0.217785,-0.599016,-0.307820,-0.147808,-0.382977,-0.103909,0.124365,-0.162071,0.362957,-0.676737,0.141366,0.592519,0.327338,-0.409796,0.609363,0.000729,-0.093393,-0.270206,-0.243519,0.513003,0.183724,-0.145899,0.075058,0.341288,0.096392,-0.492637,-0.254591,0.145037', '25789402', '10546747', '1306454', '1293145');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892531', '可爱的骨头', '剧情', '14岁的小女孩苏西（西尔莎•罗南 Saoirse Ronan 饰）生性活泼、古灵精怪，父亲（马克•沃尔伯格 Mark Wahlberg 饰）是一个模型爱好者，母亲(蕾切尔•薇姿 Rachel Weisz 饰)是循规蹈矩的传统女性，妹妹大胆，弟弟弱小。生日时，她收获了一部 相机，从此爱上了拍照，甚至在一个月间用光了24卷胶卷，令父母十分挠头。一次，全家在逛超市的时候，她偷偷望着橱窗外的男孩发呆。祖母（苏珊•萨兰登 Susan Sarandon 饰）看穿了苏西的心事，那个英俊的英国学长便是她的暗恋对象。然而，还没等两个人吐露心事，苏西却落入了坏人设下的陷阱。那个色迷迷的邻居哈维，用花言巧语引诱苏西，骗她走入其事先设好的圈套……本片根据艾丽斯•西伯德的畅销小说改编而成，以苏西的视角、倒叙的方式，讲述了一个魔幻主义的犯罪故事。©豆瓣', '西尔莎·罗南', '彼得·杰克逊', 7.2, 118217, 'tt0380510', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2585074698.jpg', 1.2, 5.9, 37.3, 40.9, 14.8, '0.401632,-0.095969,-0.293576,0.605617,-0.338162,-0.116460,0.692559,0.159783,-0.287348,-0.195130,0.230401,0.571436,-0.221063,0.152503,0.199617,0.335180,-0.411774,-0.570635,-0.085421,-0.276343,-0.105544,-0.401916,-0.265165,-0.027905,0.023554,-0.336606,0.312539,-0.308531,0.001868,0.298733,0.209062,0.121405,-0.071599,0.142635,-0.084304,0.232809,0.200816,-0.138713,0.081169,0.257642,-0.082710,-0.161029,-0.229626,0.250371,-0.297571,0.458210,0.783107,-0.181709,0.124975,-0.062612,0.336735,-0.017287,-0.122458,0.105468,0.190692,-0.280011,0.273006,-0.063988,-0.195664,0.137847,0.197942,0.067392,-0.421116,-0.151594,-0.036353,0.016221,-0.545550,0.231063,-0.063224,0.242690,0.045873,-0.460650,-0.130431,-0.021486,0.278792,0.346753,-0.022027,0.014951,-0.349270,0.192900,0.126912,0.126713,-0.152408,0.499069,-0.322210,-0.152667,0.163729,0.038234,-0.787869,0.132913,0.571538,-0.302445,-0.093106,0.109665,-0.567596,-0.335639,-0.244721,0.043519,0.123313,-0.428885,-0.403298,-0.581864,-0.086706,-0.360917,-0.194879,-0.149132,-0.197316,-0.093077,0.549244,-0.572520,0.131163,0.528036,-0.023878,-0.392535,0.677715,-0.000766,-0.115876,-0.212850,-0.160504,0.303438,-0.090655,-0.128985,-0.052776,0.468775,0.182039,-0.225863,-0.419900,0.421685', '4233625', '26677495'