INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892578', '海鸥食堂', '剧情', '芬兰是最接近日本的欧洲国家，坐飞机只需要十个小时。幸惠（小林聪美饰）在风光如画的首都赫尔辛基独自经营一家叫做“海鸥食堂” 的日式餐厅，她希望以简单却温暖的传统手卷留住客人的心，只可惜事与愿违，餐厅经常空无一人。后来，绿（片桐入饰）与正子（罇真佐子饰），因为不同原因，先后来到了那里帮忙。再加上日本文化迷的年轻小帅哥顾客，本来只是驻足指点观望，后来却被肉桂卷香味吸引进来的芬兰老太太们，曾在那里工作过而忘不了原来咖啡机的中年男人，认真地询问如何扎稻草人诅咒老公的中年女人。这些有趣而真实的人，围绕在海鸥食堂周围，结下了淡淡的情谊。©豆瓣', '小林聪美', '荻上直子', 8.3, 63772, 'tt0483022', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2496820453.jpg', 0.3, 1.4, 16.9, 46.8, 34.6, '0.405332,0.003563,-0.563791,0.272605,-0.161859,-0.266474,0.612329,0.340014,-0.608890,-0.282022,0.009613,0.436786,0.109185,0.344817,0.235411,0.142576,-0.190372,-0.330394,-0.086049,-0.264001,-0.263311,-0.275470,-0.167900,-0.363644,-0.126168,-0.072422,0.224926,0.177288,-0.060811,0.387672,0.146447,0.083588,-0.280758,0.284561,-0.318620,-0.233373,0.236974,0.051931,-0.340615,0.007080,-0.143507,-0.281342,-0.357836,0.067413,0.112102,0.323444,0.446294,0.070732,-0.202622,-0.166409,0.103964,0.091146,-0.179922,-0.072199,0.281781,-0.000396,0.559044,-0.102829,0.035700,-0.088152,-0.185670,0.132477,-0.263388,0.211199,0.248706,0.146150,-0.383636,0.483807,0.110662,-0.163349,0.115951,-0.209953,0.057309,0.043507,0.016549,0.413340,0.144711,0.301852,-0.452126,0.179376,0.603154,0.160452,-0.087265,0.416940,-0.236261,-0.139021,0.123322,-0.106163,-0.174943,-0.030675,0.042409,0.134502,0.045087,-0.245630,-0.650497,0.211802,-0.072051,-0.213753,0.251679,-0.348131,-0.439337,-0.634453,0.124482,-0.498245,-0.216225,0.262089,0.080150,0.062097,0.718682,-0.698792,0.214214,0.492091,0.273063,-0.329611,0.767288,-0.013603,-0.203607,-0.272535,-0.353603,0.237883,-0.002440,0.161977,-0.050284,0.304981,-0.159665,-0.278788,-0.598233,0.117187', '3055049', '1306860', '4830911', '1294009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1892848', '玩命记忆', '剧情', '在一座停产的密闭工厂里，五个男人从昏迷中转醒，但他们却想不起来自己身为何人，又为何在这里，唯一清楚的是，他们被困在这里，而且或被捆、或受伤，状态糟糕。与此同时，一起绑架案的赎金交接程序正在进行，歹徒依靠高明的事前准备成功拿到了钱并脱身，暗中监视的警察们迅速展开了追击。厂房里的五个男人在经过搜寻模糊的记忆片段与分析后，大致理清了当下的形势：五人中有两人是被绑架的某公司总裁寇斯与同事麦肯，其他三人则是绑匪，真正的寇斯与麦肯必须在收钱的绑匪返回前脱身，否则将面临撕票的危险，但是在身份无法确定的情况下，每个人想要保住自身安全又谈何容易？©豆瓣', '吉姆·卡维泽', '西蒙·布兰德', 7.3, 32017, 'tt0450340', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1152543186.jpg', 0.4, 3.3, 40.1, 45.8, 10.4, '0.352315,0.058347,-0.778889,0.253085,-0.147491,-0.046714,0.762229,-0.150486,-0.622153,-0.325565,0.173173,0.496622,0.228575,0.127643,0.007560,-0.158201,-0.491252,-0.719438,-0.053964,-0.154834,-0.561185,-0.645223,-0.334354,-0.317931,-0.136985,-0.127148,0.570246,0.180184,-0.198837,0.137684,0.088471,0.263454,-0.633309,0.463142,-0.031212,-0.061816,0.114253,-0.222687,-0.378275,0.444612,0.029447,-0.406610,-0.098462,0.109572,0.192807,0.788874,0.712583,-0.307460,-0.338755,0.396973,0.056980,-0.311374,-0.318030,0.335150,0.300780,0.071914,0.102419,0.066298,-0.457011,0.083236,-0.128461,0.133776,-0.886179,-0.127808,0.244292,0.200288,-0.610324,0.220243,-0.062549,-0.066995,-0.023435,-0.377074,0.282856,0.581707,0.102187,0.238417,-0.059620,-0.170497,-0.686592,-0.310822,0.752452,-0.006033,-0.170658,0.273761,0.100698,-0.497948,-0.180188,-0.177869,-0.028098,-0.005418,0.495260,0.399690,-0.258086,-0.143790,-0.294461,0.082681,-0.291833,-0.219700,-0.357482,-0.425244,-0.219642,-0.529727,-0.006874,-0.137168,-0.398227,0.149030,-0.027780,-0.243813,0.496051,-0.842100,0.094878,0.543005,0.374431,-0.510680,0.434306,-0.004872,0.460445,-0.081236,-0.133038,-0.146224,0.321699,0.500035,0.248294,0.240572,-0.213735,-0.074134,-0.665819,0.220491', '1947080', '35073886', '1301022', '6790253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1895119', '非法制裁', '剧情', '约翰（凯文·贝肯 Kevin Bacon 饰）和海伦（凯利·普雷斯顿 Kelly Preston 饰）结婚多年，感情一直十分要好，两人共同将两个孩子布兰登（Stuart Lafferty 饰）和卢卡斯（乔丹·加勒特 Jordan Garrett 饰）养育成人，一家四口的生活可谓是幸福美满。某日，约翰载着布兰登，开车行驶在回家的道路上，两人将车暂时停在了一间加油站处，殊不知这一举动彻底改变了他们的命运。在加油站，布兰登遇见了乔（马特·欧莱瑞 Matt O''Leary 饰），后者是黑帮领袖比利（加内特·赫德兰 Garrett Hedlund 饰）的弟弟，拥有着和哥哥一样凶残冷酷的个性，约翰脑海中有关儿子最后的影像，是他倒在血泊之中的模样。重重波折之后，法院释放了乔，因为凯文决心亲手替儿子报仇，曾经平凡而又和善的男人，义无反顾的踏上了一条充满了暴力和鲜血的道路。', '凯文·贝肯', '温子仁', 7.1, 14062, 'tt0804461', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2197782040.jpg', 1.2, 6.2, 40.9, 38, 13.7, '0.248236,-0.033010,-0.557733,0.698105,-0.054089,-0.570306,0.846428,0.288227,-0.601907,-0.071589,0.102353,0.961108,-0.139217,0.381970,0.361758,0.006441,-0.324694,-0.620774,-0.159605,0.042923,-0.372653,-0.741147,-0.036168,-0.272036,0.094983,-0.248804,0.435863,0.001123,0.197766,0.521485,0.375690,0.271056,-0.097723,0.292292,-0.396661,0.087872,-0.086501,-0.116420,-0.282389,0.077089,0.046840,-0.186774,-0.045441,0.110045,0.058803,0.209771,0.696039,-0.083845,-0.059701,0.003392,0.114240,-0.170984,0.166217,0.180100,0.131140,-0.173501,0.149454,0.316349,-0.172411,-0.182914,0.231696,-0.164217,-0.470265,0.006907,-0.171801,-0.075295,-0.989746,0.601224,-0.071944,0.061722,0.165775,-0.473725,0.193275,0.145562,0.218892,0.290242,-0.066982,-0.025047,-0.415331,-0.080883,0.549151,-0.033407,0.003238,0.337621,-0.374647,-0.244067,-0.261260,-0.040937,-0.622857,-0.193208,0.597080,-0.051987,-0.134639,0.145947,-0.566613,-0.121964,-0.316712,-0.027993,-0.026702,-0.317497,-0.076320,-0.506645,-0.052986,-0.576601,-0.345463,0.112674,-0.443292,-0.181082,0.537880,-0.723277,0.185460,0.288032,0.159528,-0.313095,0.801712,-0.049193,0.260959,-0.254761,0.196463,0.346114,0.075713,-0.044613,0.309825,0.474443,-0.153246,0.255358,-0.251500,0.632222', '24698878', '26809592', '3111650', '11525673');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1895120', '死寂', '悬疑', '童谣本应该充满欢声笑语，但世界上偏偏有这么一些童谣，让人听了毛骨悚然。小镇拉文斯•法尔就流传着这样一个恐怖的童谣：小心来自玛丽•肖的凝视；她没有孩子，只有玩偶；如果你看到她，不要尖叫；否则她会扯开你的嘴巴撕掉你的舌头。这个小镇一直就在笼罩在这个童谣的诅咒之下，只要有玩偶出现的地方，就有人遇害，死状一样，都是舌头被割下。吉米（瑞恩•科万顿 Ryan Kwanten 饰）和萨丽新婚不久，就决定搬离这个受诅咒的地方，但最终萨丽还是没有逃脱这个诅咒。悲伤不已的吉米决定送妻子的尸骸返回家乡，并着手调查这个笼罩在整个小镇头上的恐怖诅咒。随着调查的深入，吉米发现了这首童谣背后的另一个真相。©豆瓣', '唐尼·沃尔伯格', '温子仁', 7.8, 253299, 'tt0455760', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1235830609.jpg', 0.4, 2.4, 26.5, 47.3, 23.5, '0.457036,0.016470,-0.828671,0.567243,-0.216636,0.032353,0.891005,0.128717,-0.249759,-0.141266,0.261111,0.674895,-0.348215,0.442929,-0.000474,0.365696,-0.264158,-0.669456,-0.045672,-0.232320,-0.415221,-0.383525,0.025693,-0.201370,0.058250,-0.072366,0.389339,0.286280,-0.361591,0.114412,0.264725,0.225162,-0.012589,0.563398,-0.641620,0.151357,-0.087538,-0.019120,0.339652,0.199858,0.242133,-0.033997,0.095336,0.333269,-0.286491,0.330519,0.418844,-0.259418,-0.130011,0.068908,0.265553,-0.337118,0.006000,0.106700,0.170121,-0.373302,0.218122,0.081463,-0.386847,-0.017903,0.145787,0.203993,-0.753257,0.163738,0.085853,0.306485,-0.589450,-0.009088,0.034056,0.012611,0.004205,-0.188116,0.491350,0.195955,0.206049,0.418573,-0.076281,0.038715,-0.600627,-0.013698,0.498308,-0.279034,-0.231862,0.089133,-0.256185,-0.340928,0.076148,0.061436,-0.409151,-0.001794,0.238120,0.165355,-0.523755,0.074595,-0.445930,-0.061944,-0.226319,-0.379208,0.025442,-0.431894,-0.263975,-0.237359,-0.299426,-0.134760,-0.261457,0.188567,-0.054960,-0.201266,0.522153,-0.588849,0.467899,0.590769,0.325583,-0.301645,0.438949,0.350196,-0.089849,0.123640,-0.024973,0.396586,0.158830,0.317836,0.247510,0.322815,0.280494,-0.269685,-0.481099,0.596789', '1421570', '1947080', '1867335', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1897368', '生死拳', '动作', '全国武术冠军高岗（吴京 饰）随一只京剧团赴港表演，期间高岗矫健的身手引起地下黑拳组织者豪哥的注意，豪哥邀请高岗参加黑拳，但被其拒绝。高岗与剧团中的少女小田（杨爱瑾 饰）交好，但困窘的生活状况令高岗自叹无力给予女孩幸福，在小田的支持下，高岗终于走向了黑拳的赛场……高岗初战告捷，得以结识黑拳组织中打杂的古惑仔——队长（郑中基 饰），队长性格悭吝，但其实为人良善，且身怀武功。赌球的庄家辉少觊觎黑拳生意，与豪哥合伙将赛事扩大。高岗在连番拼斗中无一败绩，成为辉少与豪哥手中的王牌。另一黑拳庄家陈新嫉妒不已，尽遣K1冠军等高手与高岗比拼，高岗在队长帮助下涉险获胜，但这时等待着他的是鸟尽弓藏的结局，而小田和他的关系，也远没有想象的简单……©豆瓣', '吴京', '罗守耀', 7, 5676, 'tt0813549', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2143892416.jpg', 2, 8.5, 43.3, 32.6, 13.7, '-0.059450,-0.075194,-0.683673,0.536762,0.071958,0.028631,0.321562,0.077447,-0.482284,-0.005653,0.304055,0.765944,-0.087285,-0.140926,0.089693,-0.354639,0.031611,-0.752652,-0.312097,0.069923,-0.163086,-0.444743,-0.236050,-0.015627,-0.361237,-0.024992,0.658599,0.281513,-0.473261,0.824578,0.490562,0.165777,-0.044529,0.253163,-0.174103,-0.294309,0.240821,0.159086,-0.447734,0.380123,-0.146607,-0.154853,-0.342529,-0.010836,0.271574,0.207834,0.519368,-0.156460,-0.036829,-0.151290,0.082533,-0.455222,-0.011161,-0.039027,0.401744,0.034744,0.098264,0.241308,0.103779,-0.048182,0.066633,-0.168792,-0.601126,0.106375,0.286299,0.028799,-0.740586,0.575749,-0.191641,-0.183151,-0.020381,-0.053569,0.303874,0.260470,0.303401,-0.125943,-0.134418,-0.074136,-0.156921,0.035310,0.718242,0.231521,-0.086672,-0.155776,-0.138988,-0.629840,0.064648,-0.346346,-0.094629,-0.118611,0.092037,-0.124241,0.112352,-0.014663,-0.322373,0.058535,-0.035533,0.083568,-0.185205,-0.441519,-0.033814,-0.653091,-0.187854,-0.260438,-0.163104,0.047865,0.061946,-0.406643,0.671109,-0.957613,-0.091838,0.230790,0.432392,-0.195754,0.737792,0.070389,0.104177,-0.009042,-0.238983,-0.089532,0.137431,-0.097236,-0.012219,0.363205,-0.374145,-0.422400,-0.116140,0.162426', '35030151', '22964524', '4127270', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1898129', '芭比之十二个跳舞的公主', '动画', '约瑟芬国王（Christopher Gaze 配音）膝下有十二个如花似玉的女儿，在享受天伦之乐之余，国王开始担心起这十二个过分活泼好动的小公主的未来命运了。为了让公主们健康成长，国王找到了公爵夫人罗薇娜（凯瑟琳·欧·哈拉 Catherine O''Hara 配音），让她做她们的“教导老师”，希望这位真正的贵族淑女能够带领女孩们走上正途。长久生活在宫廷之中，罗薇娜养成了严谨保守的个性，先不说她制定的那些严苛的规矩，光是不许在皇宫里跳舞这一条就足够让公主们头痛了。一次偶然中，公主们发现了一条隐秘的通道通往一块神奇的土地，在那里，她们可以肆意舞蹈。国王生病的消息传来，焦急的公主们表示绝不坐视不管，因为只有她们才能挽救她们的父亲。©豆瓣', 'Ashleigh Ball', 'Greg Richardson', 8.6, 14691, 'tt0859594', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2155079590.jpg', 0.2, 0.9, 14.4, 39.6, 44.9, '0.162942,0.369778,-0.477637,0.778731,-0.168998,-0.081720,0.657728,0.009701,-0.616043,-0.183597,0.340411,0.547090,0.033743,0.369501,0.315511,-0.081004,-0.448411,-0.341267,-0.239772,-0.295898,-0.295119,-0.142999,0.075385,-0.658216,-0.492270,-0.448765,0.455748,-0.103934,0.062147,0.215203,0.399035,-0.033756,0.006491,-0.031029,-0.403181,-0.184499,0.186078,0.061629,-0.078217,-0.001961,-0.077423,-0.122480,-0.186096,0.248697,0.412677,0.111565,0.476495,-0.707394,-0.081289,-0.303949,0.448102,0.161570,0.124933,0.275808,0.162308,-0.231644,0.332031,0.027571,-0.178799,-0.012270,-0.042484,-0.269676,-0.684857,-0.071097,-0.107843,0.168573,-0.633025,0.039509,0.183370,-0.502114,0.188036,-0.444587,0.204981,0.485103,0.086802,0.220919,-0.237049,0.219788,-0.403909,0.152497,0.866204,0.099087,-0.383901,-0.043808,-0.379878,-0.452886,0.382049,-0.476156,-0.710443,-0.021800,0.370662,-0.179340,0.051894,0.199726,-0.328022,0.009026,-0.262082,-0.312050,0.082239,-0.609806,-0.048260,-0.431841,0.136203,-0.354496,-0.209141,0.220084,0.110169,-0.373999,1.052203,-0.829615,0.286981,0.338895,0.211883,-0.869291,0.658367,0.260868,0.347905,-0.120644,-0.193319,0.227037,-0.148779,0.237197,0.086157,0.573929,-0.153979,-0.071360,-0.557890,0.325026', '1877596', '26348103', '6963575', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1898223', '玫瑰人生', '剧情', '有着“小云雀”之称的法国国宝级歌手艾迪特·皮雅芙（玛丽昂·歌迪亚饰），她有着传奇的一生。皮雅芙的童年颠沛流离，先是被母亲抛弃，然后被父亲送到妓院由祖母抚养，随后在父亲从军队退役后，又被强行带走随马戏团演出生活。再之后皮雅芙跟随父亲卖艺为生，街头初啼并到成为一名酒吧卖唱的 少女。正式登台的皮雅芙顺利成为一名歌喉迷人的明星，演唱了许多脍炙人口的歌曲。然而她的情感却一再受挫，尤其是和拳击手马塞尔（让-皮埃尔·马丁斯饰）的情感经历。她的晚年每况愈下，最后死于肝癌。©豆瓣', '玛丽昂·歌迪亚', '奥利维埃·达昂', 8.4, 86200, 'tt0450188', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2447868310.jpg', 0.2, 1, 15, 48.2, 35.6, '-0.035603,0.076323,-0.424371,0.623580,0.069744,-0.357716,0.837616,0.246188,-0.292339,-0.175103,0.273809,1.133969,-0.092896,0.501654,0.596051,-0.044501,-0.108603,-0.726209,0.277871,-0.053706,-0.031569,-0.353058,0.251645,0.235841,-0.315804,-0.427945,0.895456,-0.334388,-0.103501,0.668987,0.383080,0.636942,-0.182896,0.129354,-0.309260,0.287871,0.429779,-0.136889,-0.355044,0.265062,0.115355,-0.098734,-0.413533,-0.134920,-0.321778,-0.126070,0.726645,-0.112265,0.219460,-0.178533,0.534378,-0.090045,-0.015924,0.147285,0.082317,0.021919,0.213019,0.264805,-0.422154,0.235852,0.098566,-0.226041,-0.547658,0.251874,0.175421,0.029085,-0.831180,0.251804,0.055960,0.014090,0.171235,-0.123314,0.079697,0.283394,-0.092908,0.565051,-0.189686,0.411498,-0.450825,0.320754,0.607539,0.005668,-0.457406,0.634374,0.124293,-0.369888,0.181576,-0.628972,-0.638383,0.447399,0.235371,0.063343,-0.333733,0.279022,-0.764605,-0.260245,-0.377913,-0.263524,0.211724,-0.154569,-0.222975,-0.618138,-0.318972,-0.217981,-0.287742,-0.293904,0.144744,-0.075770,0.842458,-0.718516,0.227596,0.340737,-0.100395,-0.475511,0.446042,0.050350,0.262046,0.134991,-0.152430,0.585423,0.106241,0.200432,0.064608,0.306194,-0.073319,-0.043597,-0.387877,0.500162', '3811356', '1780122', '1870681', '1482099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1898357', '工厂女孩', '剧情', '伊迪·塞奇威克（西耶娜·米勒 Sienna Miller饰）出身于显赫的家族，她曾是剑桥艺术学校的高才生，而后来到纽约发展。在一个画展上她遇到了她的偶像——前卫艺术大师安迪·沃霍（盖·皮尔斯 Guy Pearce饰），而安迪亦被她的美丽与独特气质所折服。安迪邀请伊迪到他的工作室拍电影，她欣然接受，随后他们的作品风靡美国。由于不断地享乐与放纵，伊迪的经济出现了问题，她将要破产。而她的父亲对于她的生活状态并不满意，甚至不会给她留下任何遗产。也就在这时，伊迪遇到了民谣大师鲍勃·迪伦（海登·克里斯滕森 Hayden Christensen饰），两人很快坠入了爱河。安迪得知此事后非常生气，决定不再与伊迪合作。伊迪该何去何从？©豆瓣', '西耶娜·米勒', '乔治·海肯卢珀', 7.6, 10769, 'tt0432402', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p956995786.jpg', 0.8, 4.3, 30.8, 43.4, 20.7, '0.434562,0.054990,-0.819531,0.708137,-0.146699,-0.385164,0.594051,0.222456,-0.550407,-0.401389,0.109079,1.015731,-0.102923,0.273292,0.409414,0.049605,-0.263955,-0.754742,0.136709,-0.148231,-0.094716,-0.410728,-0.187320,-0.283589,-0.127670,-0.220018,0.562475,-0.042881,-0.366835,0.470094,0.164832,0.458942,0.046957,0.560402,-0.109890,0.156846,0.055130,0.059203,-0.335925,0.115875,0.215938,-0.319853,-0.078192,0.221876,0.155511,0.217040,0.469382,-0.159059,-0.105717,-0.038399,0.333134,-0.235644,0.190960,0.161675,0.271979,-0.187181,0.245339,0.336351,-0.213871,-0.069399,0.010630,-0.134940,-0.664628,0.023776,0.067790,0.233913,-0.459698,0.518576,-0.215844,-0.130829,-0.099977,-0.293755,-0.096616,0.267862,0.295481,0.178275,-0.080514,0.076058,-0.438989,0.312039,0.579494,0.321301,-0.334474,0.366607,-0.293729,-0.450659,-0.155077,-0.300610,-0.491047,0.096462,0.382063,0.159465,-0.006816,0.355166,-0.448583,-0.184073,-0.253923,-0.283355,-0.027162,-0.429639,0.005039,-0.565345,-0.179194,-0.517902,-0.530489,-0.267364,0.036637,-0.180621,0.542321,-1.013907,0.125482,0.416371,0.256725,-0.416428,0.567315,-0.077135,0.044879,-0.160389,-0.083748,0.369891,0.017593,0.083942,0.011757,0.274473,0.225955,-0.220821,-0.228396,0.513725', '1301022', '1292219', '1299556', '3213250');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1899601', '蜜蜂总动员', '喜剧', '从外表上看，蜜蜂巴瑞·B·拜森（杰瑞·宋飞 Jerry Seinfeld 配音）和其他的伙伴没有任何区别，但他对待未来却有着自己的想法。从大学毕业后，他和同学被分配到蜂房工业公司，成为一只毕生只能辛勤忙碌、四处采蜜的工蜂。巴瑞不愿过这种一眼就能看的到未来的生活，却似乎无力扭转局面。在第一次采蜜之行时，巴瑞遭遇一连串意外，更无数次险些丢掉性命。他最终在美丽姑娘温妮莎（芮妮·齐薇格 Renée Zellweger 饰）的家中落脚，并和温妮莎成为好朋友。偶然机会，巴瑞发现蜜蜂辛勤工作得来的蜂蜜却被人类所“窃取”，这令他气愤不已，他决定行动起来，保护蜜蜂的果实……©豆瓣', '杰瑞·宋飞', '史蒂夫·希克纳', 6.8, 22134, 'tt0389790', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p866034413.jpg', 1.2, 7.6, 49.5, 32.5, 9.3, '0.157063,-0.027057,-0.679418,0.491457,-0.243862,-0.288245,0.894026,-0.084981,-0.481861,-0.089978,0.102307,0.858092,-0.231810,0.225216,-0.061203,-0.007867,-0.211165,-0.637866,0.123149,-0.061139,-0.323922,-0.205966,-0.281139,-0.218380,-0.046664,-0.202462,0.744902,-0.178250,-0.201535,0.397987,-0.096670,0.101133,-0.090780,0.686114,-0.207643,0.151324,0.101420,0.125337,-0.072769,0.087676,0.169218,-0.147337,-0.414530,0.392249,0.207107,0.351176,0.747103,-0.320445,-0.354297,-0.065039,0.263395,-0.059804,0.372732,0.175947,0.160199,-0.065121,0.112876,-0.074700,-0.051100,-0.019719,0.084799,0.077004,-0.793034,-0.052901,0.086936,0.313217,-0.612543,0.335756,0.058318,0.172190,-0.013078,-0.636664,0.040436,0.224100,0.172732,0.476876,-0.488189,0.034626,-0.567704,0.261137,0.720099,0.104919,-0.288465,0.572753,-0.286754,-0.441644,0.018347,-0.067496,-0.464385,-0.199194,0.558729,0.243305,-0.255076,0.305201,-0.755163,-0.013088,-0.194440,-0.313842,-0.038841,-0.443209,0.133704,-0.390603,0.005599,-0.375805,-0.617530,0.244012,0.218650,-0.587370,0.619563,-0.883825,0.089493,0.578623,0.301612,-0.229142,0.442781,-0.096665,0.060965,-0.021628,-0.154825,0.517183,0.289528,0.315009,0.139695,0.188773,0.186099,-0.261274,-0.449097,0.407756', '21619567', '25828589', '1301022', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1899892', '海军陆战队员', '剧情', '伊拉克战场，美国海军陆战队员约翰•特里顿（约翰•塞那 John Cena 饰）为营救战友独闯虎穴，虽然他的营救成功，却因违抗总部的命令而被强制退伍。约翰解甲归田回到家乡，见到久违的妻子凯特（凯莉•卡尔森 饰）。不愿窝在家里的约翰找到一份保全工作，却在上班第一天就被炒掉鱿鱼。为了排解心中抑郁，夫妇俩相约驾车外出度假。在一间加油站，他们遭遇珠宝大盗罗梅（罗伯特•帕特里克 Robert Patrick 饰）及其同伙。罗梅与路过的警察发生冲突，一番枪战过后，罗梅团伙成功逃跑，并劫持凯特为人质。突如其来的变故唤醒约翰的斗志，他开始独身一人追踪劫匪……本片男主角John Cena是美国最大摔角组织WWE的摔角明星。©豆瓣', '约翰·塞纳', 'John Bonito', 5.7, 4234, 'tt0419946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2623081747.jpg', 6.4, 24.3, 52.3, 11.8, 5.2, '0.118751,-0.002760,-0.476714,0.171675,-0.092805,-0.378500,0.596151,0.211198,-0.467137,-0.368976,0.380517,0.759594,-0.090265,0.173511,0.351777,-0.178872,-0.373855,-0.383650,0.141142,0.000940,0.021093,-0.218481,-0.142704,-0.334576,0.134509,-0.169668,0.644102,0.057849,-0.107686,0.546242,0.276853,0.470541,-0.146829,0.428462,0.063803,0.027752,0.186421,-0.326068,-0.439616,0.258646,-0.094644,-0.150501,-0.063250,0.037249,0.232853,0.379348,0.572004,0.127867,0.070314,-0.133590,0.108720,-0.346973,0.026790,-0.133013,0.350904,-0.091450,-0.038306,0.195004,-0.178013,0.108094,0.040045,0.105236,-0.451047,0.215362,0.000977,0.106984,-0.590296,0.162963,-0.314975,0.431692,0.216239,-0.142434,0.044693,0.393835,0.164710,0.329568,0.118678,0.103047,-0.449343,0.140782,0.727635,-0.528865,0.416753,-0.000436,0.019448,-0.265941,0.498544,-0.093568,-0.157147,-0.105562,0.307504,-0.138830,-0.052584,-0.086529,-0.496106,-0.196715,-0.457028,-0.178671,0.006924,-0.293770,-0.039662,-1.008547,0.142549,0.183075,-0.073593,0.062416,0.178006,0.062136,0.146299,-0.582168,0.181080,0.700492,0.157539,-0.477687,0.296530,0.089111,0.223401,-0.339847,-0.064869,0.438965,0.434485,0.291938,0.094772,-0.012443,-0.138406,-0.296979,-0.219658,-0.069834', '2369613', '3871833', '3178770', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1900121', '波特小姐', '剧情', '家庭富裕的波特小姐（芮妮•齐薇格 饰）至今已32岁了依然未婚，而从小很喜欢画画的她，多年来一直视自己所画的动物们为朋友。波特小姐的作品得到了出版社的认同，为她策划的是韦恩先生（伊万•麦克格雷格 饰）。韦恩先生一直被家中的两名兄长认为不是做生意的材料，他要借这次机会好好表现。波特小姐也希望做出点成就给母亲看看。事情发展顺利，波特小姐的书一本本成功出版，她与韦恩两人日久生情。韦恩先生在圣诞派对上向波特小姐求婚，可是他们的婚姻却没有得到波特小姐父母的赞同。一直以来波特的父母都想为她找一个门当户对的人，但他们还是为女儿的幸福做出了让步。波特夫妇要求女儿与韦恩先生分开3个月，看他们的恋情是否能经历考验。波特一家来到了农庄度假，期间波特小姐以书信的形式与韦恩先生沟通，突然她收不到未婚夫的回信，才知道韦恩病了，当她赶到时，韦恩先生已离世了。自此，波特小姐仿佛失去了画画的能力，她要封闭自己……', '蕾妮·齐薇格', '克里斯·努安', 7.9, 17731, 'tt0482546', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p788078742.jpg', 0.2, 1.6, 26.3, 48.5, 23.4, '0.194446,-0.151740,-0.328617,0.551178,-0.192631,-0.789905,0.361006,-0.039562,-0.553316,-0.556972,0.144630,0.987949,-0.044800,0.393292,0.241259,0.258230,-0.330552,-0.604268,0.273151,-0.254402,-0.010747,-0.667713,-0.200462,-0.378437,-0.016196,-0.417704,0.377919,-0.061368,0.078680,0.306235,0.030209,0.155903,0.256822,0.396556,-0.082625,0.038452,0.072991,0.064613,-0.722329,0.333596,0.260437,0.058896,-0.150522,0.072202,0.317365,0.324622,0.475920,-0.430156,-0.240038,-0.008077,0.429789,-0.032729,0.284080,0.511352,0.259986,-0.133049,0.375729,0.366098,-0.234955,-0.250518,-0.098375,-0.219669,-0.672638,0.151720,0.100505,0.153190,-0.774467,0.461301,-0.375539,-0.143441,0.095097,-0.616557,0.060205,0.384178,0.254364,0.179444,-0.317832,0.159396,-0.486969,-0.099920,0.590683,-0.112941,0.032084,0.240877,-0.256599,-0.439608,0.318979,-0.182451,-0.686534,0.255127,0.138736,-0.089394,0.013986,0.168863,-0.406506,-0.221794,-0.434057,-0.100075,0.178762,-0.717777,0.124511,-0.458488,-0.057533,-0.182894,-0.035053,-0.242970,0.227354,-0.535282,0.778693,-0.867728,0.147852,0.286684,0.436945,-0.630853,0.909806,0.208780,-0.023389,-0.357202,-0.198346,-0.106281,-0.014673,0.121356,0.208550,0.180267,0.791739,-0.033822,-0.071643,0.388747', '35048413', '1292720', '1783461', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1900161', '大奥', '历史', '1712年，第七代将军德川家继之时，深受第六代将军家宣器重的间部诠房（及川光博饰）受命辅佐幼主摄政。秋元乔知（岸谷五朗饰）等一批老臣对此心怀不满，两派斗争愈演愈烈。大奥也不例外，女总管绘岛（仲间由纪惠饰）一直协助现任将军的生母月光院（井川遥饰），对付第六代将军家宣的正室天英院（高岛礼子饰）派系的人，她成了天英院的眼中钉。府中有传月光院与诠房有私情，天英院准备抓住机会一举打垮敌人，她和秋元等人密谋先拿绘岛开刀，铲除月光院的得力助手。绘岛外出时偶遇歌舞伎名角生岛新五郎（西岛秀俊饰），对这位美男子一见钟情。此后两人又因机缘巧合频频重逢，绘岛却不知这是天英院的诡计。一日，戏院突起大火……©豆瓣', '仲间由纪惠', '林彻', 7.6, 11572, 'tt0872036', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p765850209.jpg', 0.3, 2.2, 32, 47, 18.4, '-0.120246,-0.065023,-0.272698,0.356103,0.249819,-0.063085,0.365486,0.711080,-0.603615,-0.711413,0.479263,0.565719,-0.157832,0.000130,0.448857,-0.143248,-0.147918,-0.440115,-0.014452,-0.133989,0.017476,-0.170768,0.077682,-0.196983,-0.401869,-0.182921,0.648794,0.134213,-0.034215,0.354221,0.334687,0.413465,-0.056149,0.084285,0.161274,-0.049661,0.223491,-0.037062,-0.248111,0.008967,-0.453518,-0.410934,-0.582718,-0.226366,0.134544,0.233820,0.319424,-0.056058,0.077739,-0.532039,-0.039309,-0.084872,-0.010971,0.228154,0.794571,0.049693,-0.103755,0.569184,-0.065319,-0.393894,-0.273362,-0.061647,-0.225645,0.119917,0.306625,-0.031307,-0.206773,0.542483,-0.054010,-0.294054,0.073748,-0.139403,0.224695,0.548976,0.180169,-0.039839,-0.270701,0.170152,-0.384056,0.272507,0.433713,-0.101423,-0.034975,-0.167727,0.218281,-0.273689,0.247283,-0.311282,-0.368227,-0.158028,0.129531,-0.087916,0.108093,0.332053,0.065468,-0.093271,-0.504701,0.259610,0.377797,-0.366504,0.208816,-0.543793,-0.323934,-0.316993,-0.092626,0.261460,0.542948,0.139171,0.567387,-0.570430,-0.022570,0.121443,0.198629,-0.519370,0.609285,0.231972,-0.009707,-0.220513,-0.136663,-0.314526,0.322350,0.109906,0.138787,0.226669,-0.126132,-0.228185,-0.234440,-0.412731', '2065021', '26999591', '3819939', '30241298');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1900172', '妹妹恋人', '爱情', '赖（松本潤饰）和郁（榮倉奈々饰）是一对孪生兄妹，两人同在国中读书。哥哥是优等生，又是体育健将，受到女孩子的欢迎。妹妹则性格文静，乖巧温顺。在赖的好友（平岡祐太饰）向郁表白后，赖对郁突然变冷淡了，这使郁困惑不已：她和哥哥一直都是情深意笃，孩提时，赖还把结草的戒指戴在自己手上，说要娶己为妻，和现在的赖简直判若两人。其实，赖一直都在被对郁的爱意折磨，无论如何刻意冷落，他就是忘不了郁。一晚，赖大胆向郁表白，郁起初虽然错愕不已，但在冲动之下，她还是选择回应了哥哥的爱，两人开始品尝这甜蜜与苦涩交融的果实……可是这份不能言说的禁忌之恋的出路在哪里？©豆瓣', '松本润', '安藤寻', 5.7, 12296, 'tt0871977', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1026887542.jpg', 7.4, 25.4, 48.3, 13.7, 5.1, '-0.206588,-0.187105,-0.803309,0.504690,-0.179505,-0.039877,0.574675,0.201675,-0.554308,0.074114,-0.141952,0.563645,-0.341887,0.531766,0.168478,-0.006276,0.126273,-0.541681,-0.110621,0.100109,-0.014767,-0.471605,0.013823,-0.206633,-0.125394,-0.299631,0.457107,0.183649,-0.181694,0.583658,0.741010,0.207335,-0.248254,0.765554,-0.259512,0.024700,-0.245704,0.343192,-0.035774,-0.206977,0.423749,-0.290689,0.002079,0.248994,0.464420,0.245479,0.455101,-0.256456,-0.261485,0.273057,0.278476,-0.248340,-0.029507,0.306460,0.125261,-0.335806,0.126571,-0.061952,-0.198952,0.049666,0.210789,0.091900,-0.397163,-0.001915,0.256206,0.024582,-0.711951,0.662847,-0.049051,0.151979,0.038890,-0.075154,0.288852,0.176615,0.006416,0.490687,-0.147702,0.123137,-0.246234,0.026635,0.440057,0.270715,-0.028595,0.416075,-0.285091,-0.196373,-0.169215,-0.014259,-0.534964,-0.108028,-0.082139,0.057375,0.056062,0.004794,-0.364645,-0.181861,0.274675,0.383928,0.172158,-0.795612,-0.195044,0.038430,0.079165,-0.647458,-0.266925,0.360985,0.013906,-0.416736,0.611620,-1.003657,0.167849,0.235362,0.490344,-0.537408,0.813770,0.524677,-0.353762,-0.239022,0.053025,0.505774,0.018286,-0.235077,0.347592,0.535701,0.208189,0.340119,-0.544777,0.439493', '2052978', '21766698', '1302384', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1900841', '窃听风暴', '剧情', '1984年的东德，整个社会笼罩在国家安全局的高压统治之下，特工魏斯曼（乌尔里希·穆埃 Ulrich Mühe 饰）奉命监听剧作家德莱曼（塞巴斯蒂安·科赫 Sebastian Koch 饰）及其女友演员克里斯蒂娜（马蒂娜·格德克 Martina Gedeck 饰）的生活，监听过程中，魏斯曼渐渐对这家人的生活产生了兴趣，开始暗中帮助他们。一篇刊登在西德《明镜》报上的文章引起了特工头目的注意，他们认为这篇文章是德莱曼写的，并逮捕了克里斯蒂娜，希望能够从她口中得出她丈夫的秘密？而审问克里斯蒂娜的正是魏斯曼……©豆瓣', '乌尔里希·穆埃', '弗洛里安·亨克尔·冯·多纳斯马尔克', 9.2, 527353, 'tt0405094', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1808872109.jpg', 0.2, 0.4, 5.3, 29.5, 64.6, '0.357375,-0.047992,-0.680666,0.791616,0.080461,-0.055229,0.438976,0.257714,-0.723870,-0.420432,0.200986,0.366949,-0.325880,-0.063140,0.537723,-0.043574,-0.532768,-0.790855,0.049857,-0.291131,-0.366431,-0.509649,-0.078293,-0.696681,-0.063328,-0.407378,0.355942,0.050552,-0.273446,0.100171,0.244805,0.556665,-0.101819,0.182378,0.166495,0.029665,0.267491,-0.493595,-0.294731,0.155658,-0.025034,-0.154134,-0.171105,0.235200,0.017917,0.385950,0.408062,-0.269610,-0.039622,-0.105510,0.225630,-0.208225,0.056195,-0.015775,0.188877,-0.172193,0.030779,0.372882,0.018536,0.099928,-0.026013,-0.100676,-0.537296,-0.087561,-0.020983,0.586073,-0.324811,0.320694,-0.404730,0.079042,-0.257987,0.069024,0.030800,0.315288,-0.023809,0.379991,0.164954,0.076754,-0.424450,0.068412,0.169198,-0.283198,-0.329105,0.179952,-0.573285,-0.376300,-0.125751,0.237570,-0.305528,-0.060994,0.181217,0.066463,-0.068903,0.369003,-0.385920,-0.102180,-0.356221,-0.202210,0.006348,-0.417149,0.032553,-0.820248,-0.291088,-0.225054,-0.059847,-0.104042,-0.124708,-0.231796,0.679420,-0.611372,0.132148,0.474752,0.132602,-0.216250,0.283296,0.049705,-0.054755,-0.409408,-0.149318,0.278116,0.340409,0.056757,-0.008427,0.182908,0.265352,-0.459323,-0.069479,0.344698', '2367243', '25723905', '1293656', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1900848', '末代独裁', '剧情', '二十世纪七十年代，年轻的苏格兰医生尼古拉斯•哥瑞肯（James McAvoy 詹姆斯•麦艾维 饰）踌躇满志，怀着为穷苦人民救死扶伤的伟大理想来到了贫困的乌干达。在此他结识了医学会的白人同事，美丽的莎拉（Gillian Anderson 吉莉•安德森 饰），深深为之所吸引 。某次集会上，尼古拉斯得以见到乌干达总统安迪•阿明（Forest Whitaker 福里斯特•惠特克 饰），阿明的言论使尼古拉斯甚为着迷，甚至狂热崇拜。集会之后，他救助了因事故受伤的阿明，并因其苏格兰人身份受到赏识。之后更以总统御用医生的身份走近这位残暴君主……影片改编自Giles Foden的同名小说，男主角福里斯特•惠特克凭借此片获得第79届奥斯卡奖最佳男主角奖。©豆瓣', '福里斯特·惠特克', '凯文·麦克唐纳', 7.9, 31597, 'tt0455590', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p791296361.jpg', 0.2, 1.2, 22.2, 56.2, 20.2, '-0.066527,-0.050120,-0.380571,0.444147,-0.016879,-0.461059,0.455159,0.202229,-0.490280,-0.359618,0.446993,0.948157,-0.273181,0.149072,0.478312,0.047281,-0.370267,-0.420977,-0.255869,0.012335,0.024738,-0.181496,-0.419436,-0.042864,-0.311441,-0.468517,0.422492,-0.195907,-0.211028,0.438514,0.465232,0.586597,0.112895,0.069732,0.080574,0.057902,0.331367,-0.185916,-0.711852,0.259422,0.026078,-0.197502,-0.225350,0.212829,-0.126343,0.177564,0.468261,-0.302546,-0.104574,-0.346399,0.747832,-0.104185,0.280155,0.228927,0.010085,0.170014,0.146131,0.142856,0.123088,0.168141,-0.022449,-0.014000,-0.558085,0.093973,0.049728,0.261834,-0.371815,0.285112,-0.166598,-0.134066,0.177655,-0.093616,-0.068285,0.257730,0.028801,0.126746,0.132870,0.293693,-0.055438,0.254574,0.364584,0.125767,-0.449951,0.152460,-0.416796,-0.634192,0.435421,-0.159518,-0.525468,0.128459,0.393086,-0.019992,0.322646,0.388304,-0.292853,-0.292615,-0.332915,-0.117484,0.073109,0.036208,0.021949,-0.801923,-0.115627,-0.211977,-0.107214,-0.424071,0.255388,-0.336401,0.742764,-0.526195,0.286550,0.479839,0.078762,-0.406106,0.467971,-0.022888,0.059448,-0.177226,-0.577098,0.584818,-0.041769,0.183083,-0.249428,0.109756,-0.110892,-0.439509,-0.158944,0.398644', '1829654', '2336737', '3072064', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1901328', '红色机尾', '剧情', '影片讲述了二战中，美国第一批黑人飞行员，克服当时制度和种族上的限制，组成了一支带有实验性质的特殊的轰炸机护卫队——塔斯克基飞行（TuskegeeAirmen）。他们的飞机上都画着“红尾巴”，于是这也成为了他们的绰号。“红尾巴”这支美国军事史上第一支由非裔美国人组成的飞行员编队，因为参加战争培训被派往阿拉巴马州随时准备迎战。在那里，他们经历了猖獗的种族主义和骚扰，他们的飞行和战斗能力曾饱受质疑，但“红尾巴”在空中卓越的表现，促使空军废除了种族隔离制度。他们在与意大利、德国的冲突中也起到了不可或缺的作用。', '内特·派克', '安东尼·海明威', 6.5, 6801, 'tt0485985', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1532596394.jpg', 2.7, 12.1, 50.2, 27.1, 7.8, '0.501839,0.043046,-0.797294,0.889826,0.161517,-0.008734,0.469183,-0.134410,-0.325453,0.122861,0.253190,0.760678,0.030801,-0.018558,0.172929,-0.238516,-0.504151,-0.780285,-0.176580,-0.024357,-0.632382,-0.433878,-0.423679,-0.419021,0.038747,-0.398593,0.769043,-0.002792,-0.524924,0.739265,0.120300,0.124294,0.133855,0.234507,-0.206947,-0.122730,-0.007868,-0.091679,0.015335,0.287458,-0.257296,-0.353504,0.040408,0.067951,0.095985,0.663692,0.616889,-0.498380,0.045215,-0.600424,-0.133440,-0.514501,0.050907,0.222700,0.570440,0.324567,0.107858,0.081134,0.066971,0.170826,-0.237071,-0.002243,-0.816562,0.043388,-0.081685,0.126365,-0.666296,0.554079,-0.366580,0.052810,-0.016255,-0.071435,0.280770,0.466211,0.006937,0.110813,-0.094374,0.077157,-0.813144,0.346056,0.701193,-0.272474,-0.550707,-0.282743,-0.430205,-0.368796,-0.341390,-0.645750,0.064920,-0.384170,0.302034,-0.170635,-0.095661,0.077246,-1.027541,0.520019,-0.128326,-0.548773,-0.329804,-0.228416,0.158879,-0.840438,0.149607,-0.718196,-0.515494,0.093812,0.187346,-0.006348,0.855093,-0.807468,0.171329,0.469498,0.484959,-0.405342,0.444612,0.132201,0.145772,-0.112100,-0.120280,0.087043,-0.067278,0.422600,0.093034,0.416581,0.133040,-0.093790,-0.221734,0.506882', '1307762', '1294917', '26290398', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1902105', '荒野大飚客', '喜剧', '道格（蒂姆·艾伦 Tim Allen 饰）是个无聊的住家男，工作之余百无聊赖还要被儿子看不起；鲍比（马丁·劳伦斯 Martin Lawrence 饰）辞掉工作一心想当作家，但是毫无进展还遭老婆整日奚落；杜德利（威廉·H·梅西 William H. Macy 饰）是个软件工程师，标准极客宅男，因为不敢和女人讲话一把年纪还没有女朋友；伍迪（约翰·特拉沃尔塔 John Travolta 饰）风流半辈子，如今公司面临破产，名模老婆也要离他而去。四个老友，带着各自的中年危机，在伍迪的建议下开始了一次哈雷摩托旅行，他们穿皮衣、绑头巾、做起不像样的“逍遥骑士”打扮，开始穿越新墨西哥州，试图在状况百出、不计后果的旅行中，重新找回失去的自我、久违的激情乐趣，了却今生遗憾……©豆瓣', '蒂姆·艾伦', '沃尔特·拜克', 7.1, 10849, 'tt0486946', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195573324.jpg', 0.8, 4.9, 42.4, 39.8, 12.1, '0.006523,-0.220667,-0.536511,0.366765,-0.481903,-0.620786,0.731512,0.213363,-0.405472,-0.383860,0.063357,0.667684,-0.170074,0.375468,0.382803,0.190091,-0.443907,-0.627200,0.122717,0.195651,-0.052004,-0.343609,-0.033157,-0.180857,-0.345691,-0.279807,0.269519,-0.214373,-0.005945,0.354461,0.555335,0.206663,0.057147,0.398959,-0.351272,-0.060538,0.211880,-0.243330,-0.074341,0.191885,0.144706,-0.148115,-0.039853,0.157930,0.100184,0.320294,0.680785,0.117096,0.020940,-0.087485,0.376094,0.051427,-0.081390,0.072261,0.254614,-0.234723,0.119071,-0.094956,0.067802,0.065336,0.399779,-0.259250,-0.461068,0.163152,-0.032113,-0.002024,-0.630134,0.264339,-0.348829,-0.019854,0.013580,-0.386068,-0.123901,0.050124,0.419083,0.359040,0.031727,0.202357,-0.381379,0.355680,0.405727,0.285761,-0.076274,0.437261,-0.047097,-0.097219,0.002516,-0.254851,-0.682069,-0.208112,0.274750,-0.188005,-0.101170,0.119622,-0.517747,0.230256,-0.239825,-0.096795,-0.136141,-0.202817,-0.142692,-0.481536,-0.010510,-0.329647,-0.152681,0.143490,0.126563,-0.186962,0.376693,-0.668118,0.089409,0.474951,0.036028,-0.575165,0.566409,0.151093,0.191313,-0.288738,0.046700,0.056743,-0.151536,0.203530,0.173963,0.434023,-0.116451,-0.353946,-0.122817,0.294486', '3111650', '3326747', '4233625', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1904722', '宠物坟场', '悬疑', '路易斯带著一家人从城市迁居到缅因州的乡间小镇开始，由于家门前经常有卡车飞驰，附近的宠物常遭遇被碾死的悲剧，然后被葬在附近的印第安墓园。而这座墓园也因此被称作宠物坟场。不幸的是，路易斯·克里兹的爱女也惨死车轮之下，同样被葬在宠物坟场，他的亡魂却被起死回生成为恐怖的杀人魔，宁静的小镇不再宁静。', '杰森·克拉克', '凯文·库尔施', 5.7, 17911, 'tt0837563', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2547439963.jpg', 4.2, 26.3, 52.2, 13.5, 3.8, '0.574631,0.163453,-1.029173,0.378745,-0.028858,0.128750,0.876450,0.249358,-0.510667,-0.030056,0.484755,1.028783,-0.016619,0.346248,0.039633,0.041537,0.187329,-0.333148,-0.165481,-0.154521,-0.403634,-0.125296,-0.091916,-0.134777,-0.031573,-0.469261,0.414105,0.525957,-0.013048,0.285534,0.016576,0.866075,-0.413758,0.362323,-0.707995,0.026434,-0.117269,-0.087629,0.091110,0.198015,-0.597736,-0.267596,0.128386,-0.077020,-0.000470,0.083759,0.994354,-0.169123,-0.219923,-0.202510,0.152673,-0.179285,-0.059472,0.147860,0.727979,-0.493535,0.134768,0.181388,-0.239498,-0.125101,0.032303,-0.100054,-0.622766,0.112426,0.036535,-0.021449,-0.819316,0.399206,0.240277,-0.268935,0.116728,-0.160449,0.676439,0.030740,0.190402,0.468786,-0.078008,-0.025497,-0.616742,-0.151610,0.891646,-0.174758,-0.169499,0.128110,-0.106484,-0.485776,0.148312,-0.383152,-0.316134,-0.033758,0.561850,-0.157318,-0.518833,0.435770,-0.831362,-0.055231,-0.431202,-0.431328,-0.061245,-0.171690,-0.475037,-0.626298,0.276142,-0.158870,-0.075884,0.226883,-0.215682,0.019676,0.335745,-0.664854,0.792728,0.556576,0.272911,-0.075091,0.612637,-0.559816,0.274724,0.044097,0.098270,0.683444,0.618786,0.711453,0.405823,0.039469,-0.401841,-0.096468,-0.551809,0.954459', '21619567', '3011051', '1856675', '3430271');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1905462', '荒野生存', '剧情', '影片改编自真实的故事，展现了一个理想主义者的传奇，一个流浪的故事。克里斯托弗（埃米尔•赫斯基 饰）家境优渥，是亚特兰大私立名校艾莫里的优等生，前程似锦。但是，他从学校毕业后，选择了截然不同的人生，放弃令人羡慕的工作，把存款捐给慈善机构，去阿拉斯加寻找自我。在家人的劝阻声中，他踏上了回归自然的慢慢长路，成为名副其实的流浪者。一路上，他遇到不少人，也数次遭受野外生存的挑战，每一步都充满了艰辛，他以坚韧的毅力，实践着寻找自我的梦想……©豆瓣', '埃米尔·赫斯基', '西恩·潘', 8.6, 208017, 'tt0758758', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p465687407.jpg', 0.7, 1.9, 12.9, 37.4, 47.1, '0.118326,-0.107145,-0.391419,0.763016,-0.113367,-0.407777,0.447570,0.091088,-0.427163,-0.026585,0.269425,0.790895,0.089297,0.255817,0.158570,-0.200463,-0.137211,-0.554700,0.055291,-0.069397,-0.212121,-0.388718,-0.180737,-0.090434,-0.207325,-0.157477,0.788250,0.205748,-0.354433,0.408651,0.141707,0.204352,0.195732,0.281501,-0.437397,0.045390,0.198004,0.144553,-0.261474,0.335061,0.039238,-0.125460,-0.291677,0.067424,-0.075835,0.247067,0.649224,-0.026818,0.007857,0.075924,0.733417,-0.295955,-0.240556,0.145892,0.093635,0.133352,-0.126856,0.338955,-0.011184,0.031760,0.136611,-0.266752,-1.000648,-0.462733,0.217866,-0.010624,-0.905807,0.547508,0.254324,-0.134794,0.158830,-0.284722,-0.031658,0.139411,0.140565,0.285727,-0.058269,0.129130,-0.468161,0.540258,0.865399,-0.164330,-0.477681,0.299816,-0.485385,-0.601914,-0.005223,-0.400083,-0.814030,-0.174631,0.150929,0.087563,-0.347408,0.141047,-0.770346,0.219918,-0.164282,-0.391266,-0.094324,-0.462860,-0.133737,-0.511124,-0.097195,-0.263340,-0.363329,0.062827,-0.091390,-0.507181,0.958795,-0.633686,0.128257,0.752425,0.111401,-0.451660,0.931770,-0.256978,0.179351,-0.150745,0.039915,0.759364,0.020977,0.489537,-0.167916,0.297857,-0.109770,0.017745,-0.540474,0.881745', '30279170', '27602116', '26647163', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1905777', '失踪宝贝', '剧情', '美国小镇上，四岁女童阿曼达突然失踪，她的姨妈和姨夫找到私家侦探Patrick Kenzie（Casey Affleck 饰），委托他调查外甥女失踪的事情。Patrick Kenzie和女朋友兼工作搭档Angela（Michelle Monaghan 饰）开始了艰难的调查。随着调查的深入，他们发现阿曼达的母亲Helene是一个地道的瘾君子，她对毒品的关心程度似乎远胜于女儿的失踪，调查围绕她展开之后，毒品贩子、诈骗犯、虐待儿童的人渐渐浮出水面，Detective Remy Broussard（Ed Harris　饰）以及警官Jack Doyle（Morgan Freeman　饰）也加入了案情的调查，但是阿曼达的名字却越来越遥不可及，Patrick Kenzie也站在了道德的十字路口，开始思考怎样才算是“伸张正义”。©豆瓣', '卡西·阿弗莱克', '本·阿弗莱克', 7.8, 21567, 'tt0452623', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498072912.jpg', 0.5, 2.3, 23.9, 54.3, 18.9, '0.360736,-0.432856,-0.504971,0.516266,-0.240191,-0.329437,0.539857,0.087015,-0.786232,-0.274077,0.139397,0.572720,-0.338827,0.112156,0.087845,0.022065,-0.459152,-0.878518,0.105104,-0.210323,-0.237989,-0.790969,-0.252360,-0.232474,0.080144,0.047095,0.401859,-0.052995,-0.120421,0.367383,0.090317,0.308014,-0.155848,0.521046,-0.100586,-0.144393,0.260355,0.078599,0.066232,-0.029278,0.207298,-0.358333,0.204700,-0.055388,0.023149,0.793050,0.725633,-0.118539,-0.309586,-0.194905,0.443197,-0.333827,0.133139,-0.034183,0.560516,0.144026,0.064580,0.345657,-0.405278,-0.328619,-0.197161,-0.104257,-0.488136,0.114540,0.297440,0.310603,-0.650961,0.053088,-0.291702,-0.154044,0.219065,-0.281477,0.240759,0.645790,-0.075104,0.438709,-0.039143,-0.025343,-0.523304,0.085385,0.326566,-0.037160,0.121652,0.218988,-0.049302,-0.691443,-0.152783,-0.041249,-0.115244,-0.039127,-0.106659,0.093080,-0.239670,0.113022,-0.554913,-0.159372,-0.283694,-0.237551,0.030343,-0.450794,-0.265397,-0.509719,-0.320488,-0.325997,-0.278220,-0.115367,-0.078083,-0.392690,0.499229,-0.776871,0.134280,0.550721,0.376778,-0.577166,0.548846,-0.072688,-0.182841,-0.523662,-0.049886,0.218838,-0.097155,0.178065,-0.016904,0.053308,0.206864,-0.367926,-0.226434,0.171371', '3263169', '1294756', '12