INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1905786', '国家要案', '剧情', '如日中天的华盛顿年轻议员史蒂文•柯林斯（本•阿弗莱克 Ben Affleck 饰）的女助手研究员突然遇害，柯林斯在针对军火商峰点公司的国会听证会上一时失态，致使婚外情曝光，成为众矢之的，只好跑去大学好友兼昔日竞选顾问，《华盛顿环球报》的资深记者卡尔•麦卡弗里（罗素•克劳 Russell Crowe 饰）家暂避。麦卡弗里在调查一起凶杀案的过程中偶然发现死者竟与柯林斯的已故女助手研究员有关。在同事德拉（瑞秋•迈克亚当斯 Rachel McAdams 饰）的帮助下，随着麦卡弗里的调查一步步深入，峰点公司内幕与国会议员的丑闻纷纷曝光。麦卡弗里面对新闻竞争、事件真相、昔日友情与社会公正的多股力量，最后报道究竟何去何从？©豆瓣', '罗素·克劳', '凯文·麦克唐纳', 7, 17977, 'tt0473705', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p916259353.jpg', 0.6, 4.3, 47.3, 40.6, 7.3, '0.372976,-0.217175,-0.360364,0.303249,0.187998,-0.386493,0.251126,0.477746,-0.605223,-0.333443,0.416790,0.810338,-0.326274,0.058170,0.717799,-0.169287,-0.651727,-0.668866,0.160380,-0.347108,0.128696,-0.837157,-0.325764,-0.334198,0.068204,-0.216247,0.618961,-0.228290,-0.102495,0.527379,0.318152,0.655924,-0.284866,0.202947,0.479225,0.015864,0.919391,-0.107078,-0.695719,0.124612,-0.082259,-0.075691,-0.312883,-0.366222,0.279080,0.324010,-0.009905,-0.134106,0.069325,-0.327492,0.554067,-0.092785,0.257197,0.031842,0.619706,0.102041,0.330037,0.638448,-0.065275,-0.189525,-0.058293,0.166847,-0.507398,0.109353,0.215512,0.459780,-0.423629,-0.009904,-0.288811,-0.129278,0.256580,-0.134380,-0.062558,0.187119,0.177431,-0.005896,0.149461,0.276137,-0.187442,0.065009,0.235662,0.262186,-0.167554,-0.225426,0.005657,-0.262157,-0.096048,0.053968,-0.423138,0.001428,0.167058,-0.099911,0.082013,0.737026,-0.253982,-0.316329,-0.393537,-0.143269,0.100478,0.013693,-0.087082,-1.076114,-0.477385,0.094456,-0.176226,-0.671409,0.185416,0.020999,0.390079,-0.505845,0.105383,0.753188,0.194358,-0.228657,0.491061,0.302253,0.249836,-0.385815,-0.536953,0.057293,0.284787,0.459392,-0.090092,-0.010390,0.103322,-0.450173,0.168942,0.048691', '1293572', '1298616', '3077791', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1905790', '迈克尔·克莱顿', '剧情', '刑事犯罪检察官的迈克尔·克莱顿(乔治·克鲁尼 George Clooney 饰)曾在纽约法律界风光一时。离职后又在一家大型私人法律事务所谋事。在新老板马蒂·巴彻(西德尼·波拉克 Sydney Pollack 饰)的督促下，开始了清理不良记录的工作中。但工作和个人生活也因此改变：妻子孩子离他而去，债务让他没了以前的光彩。财政状况让他只得继续在工作中煎熬。同时，他又因为公司的肮脏业务而卷入一场价值高达数百万美元的集体诉讼案当中。而正当他利用自己的关系和丰富的办事经验“拨开迷雾”成功解决这场诉讼案时，老板手下的另一个办事员亚瑟·艾登斯(汤姆·威尔金森 Tom Wilkinson 饰)以及女诉讼律师凯伦·克劳德(蒂尔达·斯文顿 Tilda Swinton 饰)等人的一一卷入，使得迈克尔的事业和人生再次面临新一轮严峻的挑战……©豆瓣', '乔治·克鲁尼', '托尼·吉尔罗伊', 7.1, 10981, 'tt0465538', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1395655462.jpg', 1, 5.4, 43.1, 40.9, 9.6, '0.082544,-0.014621,-0.483008,0.449244,-0.152063,-0.449227,0.608792,0.437108,-0.355510,-0.259552,0.202987,0.728119,0.074743,0.159086,0.397507,-0.040172,-0.446081,-0.799029,0.004357,-0.167970,-0.239289,-0.750211,-0.285907,-0.387589,-0.080757,-0.232974,0.491764,0.004164,-0.131753,0.309340,0.143342,0.112739,0.009007,0.589251,0.027201,-0.018673,0.308413,0.029389,-0.356847,0.105627,0.271392,-0.233176,-0.170528,0.078459,0.332121,0.532533,0.518154,-0.219429,-0.158733,-0.070332,0.346469,-0.213200,-0.046645,0.159429,0.294005,0.034959,0.185900,0.352390,-0.495590,-0.051244,0.039348,-0.172171,-0.755721,-0.037573,-0.088725,0.100654,-0.500469,0.351417,-0.081198,0.073951,0.084585,-0.162935,-0.057782,0.419349,0.417743,0.350596,-0.091235,0.039998,-0.274824,0.272375,0.645922,0.069906,-0.067594,0.176346,-0.350167,-0.264134,-0.196270,-0.188327,-0.408286,-0.292915,0.280716,0.030703,-0.101890,0.305101,-0.667880,0.112799,-0.332870,-0.222755,-0.129361,-0.311597,-0.045999,-0.692183,-0.098586,-0.157712,-0.291389,-0.104898,0.204533,-0.353095,0.508568,-0.679009,0.172456,0.597384,0.334979,-0.440473,0.606129,0.021302,0.440913,-0.096786,-0.185937,0.012075,0.111708,0.437010,0.013297,0.235800,0.126044,-0.372591,0.066599,0.311908', '1307442', '11541282', '6790253', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1907464', '集结号', '剧情', '1948年解放战争时期，连长谷子地（张涵予 饰）率领九连47名战士在汶河岸执行掩护大部队撤退的任务，团长刘泽水（胡军 饰）下令，以集结号为令，听见号响就撤退。惨烈的战争在炮弹的轰鸣中开始，九连的战士死伤惨重，排长焦大鹏（廖凡 饰），牺牲前说自己听见了集结号，谷子地自己没有听见，他决定死守阵地。九连打退了敌人三次进攻，炸毁二辆坦克，歼敌无数，全连除连长谷子地，47人全部阵亡。这场战争改变了谷子地的人生。由于部队改了编号，谷子地找不到组织，九连牺牲的烈士们也被认定为失踪。谷子地开始了艰难的寻找，为九连的兄弟们讨个说法，也为了探明当年集结号的真相。©豆瓣', '张涵予', '冯小刚', 8.2, 248586, 'tt0881200', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1655611025.jpg', 0.6, 1.4, 17.4, 49.9, 30.7, '0.132281,-0.129982,-0.688782,0.518693,0.074093,-0.061937,0.332324,-0.102055,0.021578,0.035801,0.397483,0.269941,0.274524,-0.401026,0.298176,-0.425590,-0.017939,-0.780439,-0.336405,0.053925,-0.246475,-0.381802,-0.037206,-0.380558,-0.011596,-0.158829,0.595861,0.412008,0.089900,0.619864,0.045840,0.173817,0.546531,0.121309,0.226456,0.245518,-0.129884,-0.240768,-0.104415,0.138986,-0.506884,-0.238134,-0.241789,-0.146879,0.100359,0.607993,0.746884,-0.347519,0.115806,-0.208245,-0.259461,-0.302794,0.143234,0.139610,0.632415,0.284905,-0.029024,0.301639,0.141053,0.296299,-0.330289,0.242972,-0.875928,0.017913,0.062621,-0.161181,-0.715443,0.383780,-0.346187,0.566316,0.328473,-0.257323,0.248569,0.555626,0.220888,0.256623,-0.544057,0.096703,-0.411137,0.354167,0.561031,-0.414255,0.097568,-0.246727,0.299582,-0.234669,0.052769,-0.014336,-0.173358,0.144919,0.184114,0.001187,0.015269,0.408997,-0.859565,0.113147,-0.502238,-0.637306,-0.025985,-0.132991,-0.455862,-0.607992,0.261056,0.115893,-0.193304,0.556248,-0.043645,0.159711,0.951962,-0.445725,-0.182671,0.235089,0.245144,-0.427983,0.273538,0.255027,0.143200,-0.161395,0.475688,-0.068387,-0.169614,0.799569,0.447113,0.210449,-0.126806,-0.388025,-0.354849,-0.036922', '4181031', '1292444', '25928048', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1907465', '在路上', '剧情', '赛尔(萨姆·赖利 Sam Riley 饰) 是一个追寻灵感，渴望遨游的年轻作家，迪安·莫里亚蒂（加内特·赫德兰 Garrett Hedlund 饰）则是个风流率性，曾几进监狱的不安少年，还娶了16岁的浪荡姑娘玛丽露（克里斯汀·斯图尔特 Kristen Stewart 饰）为妻。然而赛尔十分喜欢迪安充满激情的生活，迪安则钦佩赛尔的风度与学识，三个迷恋自由的年轻人结识后，很快便决定抛下生活，一同行走在路上。他们一路搭便车，吸大麻，行时高歌，醉时沉思。在穿越美国东西的大道上，放浪形骸，追寻自我，燃烧青春。影片改编自美国作家杰克·凯鲁亚克的自传性同名小说，该小说被奉为“跨掉的一代”的圣经。©豆瓣', '萨姆·赖利', '沃尔特·塞勒斯', 7.1, 33564, 'tt0337692', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1550507116.jpg', 1.1, 6.8, 41.9, 37.2, 12.9, '0.254852,-0.038841,-0.264277,0.681922,-0.083748,-0.603375,0.639733,0.337887,-0.253628,-0.174455,0.146509,0.651344,-0.178809,0.366572,0.492241,0.250001,-0.495498,-0.421996,0.090263,-0.042923,0.121099,-0.454198,-0.221882,-0.091496,-0.115815,-0.466415,0.521288,-0.109775,-0.109530,0.573092,0.332919,0.441440,-0.128218,0.125478,-0.186984,-0.004732,0.242287,-0.037541,-0.222588,0.020487,-0.187489,-0.118740,-0.209902,-0.269591,-0.095241,-0.049403,0.576226,-0.005802,0.070167,-0.127369,0.409960,0.162170,0.124073,0.092684,-0.152645,-0.052897,-0.025325,0.147167,-0.010806,0.031405,-0.057018,-0.171409,-0.526811,-0.059533,0.061314,0.259337,-0.501608,0.360326,-0.084233,-0.225912,0.025324,-0.248208,-0.337289,-0.045864,0.283753,0.221538,0.165897,0.057891,-0.297685,0.249220,0.261457,0.175624,-0.402656,0.432789,-0.278081,-0.183745,-0.009355,0.135766,-0.750726,-0.242025,0.239767,0.008908,-0.052552,0.482827,-0.504014,0.024494,-0.315896,0.032548,0.132943,-0.134773,-0.374638,-0.589770,-0.260745,-0.271859,-0.130366,-0.352555,0.230719,-0.174470,0.748278,-0.438062,0.308050,0.527990,-0.213736,-0.320629,0.599446,0.040114,-0.220576,-0.128435,-0.005053,0.797258,-0.155993,0.017458,-0.074549,0.407475,-0.196757,0.028653,-0.426159,0.735039', '1296992', '1460341', '26348103', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1907467', '卡珊德拉之梦', '剧情', '伊恩（伊万·迈克格雷格 Ewan McGregor 饰）与特里（柯林·法莱尔 Colin Farrell 饰）兄弟俩被开餐馆的父亲养大，他们被母亲教育要向会做生意的有钱叔叔霍华德学习。特里和女友嗜好赌博，经常借钱去赌场。一场赛狗比赛让特里赢了些钱，兄弟俩一起买了艘小游艇，取名为“卡珊德拉之梦”，然而他们却并未察觉这个名字所蕴含的不吉祥。伊恩爱上了野心勃勃、想成为模特或演员的女孩安吉拉。为了完成她的梦想，伊恩四处寻找挣钱之道；特里也因为赌博欠下巨额债务。兄弟俩都陷入绝境。霍华德叔叔出现在他们面前，想要给他们帮助，条件是他们必须杀死对自己不利的商业伙伴。为了摆平各自的困境，两人将目标对象杀死。一切看似顺利，但是一场噩梦却悄然降临。杀了人的特里一直内心自责，不敢面对自己杀人的现实，犹豫着要向警察自首。伊恩得知消息，害怕特里自首会连累自己，于是找到叔叔霍华德，两人开始酝酿谋杀特里的计划。在“卡珊德拉之梦”游艇上，亲情、金钱、良知开始相互审判……', '伊万·麦克格雷格', '伍迪·艾伦', 7.1, 10969, 'tt0795493', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p767799172.jpg', 0.6, 4.5, 43.5, 41.1, 10.3, '0.284858,-0.010449,-0.548591,0.368151,-0.193574,-0.519136,0.636306,0.055366,-0.303517,-0.160415,0.191274,0.681593,-0.006606,0.047658,0.140985,0.098582,-0.504149,-0.617780,0.193195,0.135853,-0.107428,-0.610076,-0.047304,-0.327094,-0.219513,-0.164206,0.294753,-0.112051,-0.074017,0.210771,0.398513,0.318175,0.028367,0.202005,0.147627,0.068931,0.065801,-0.221055,-0.534803,0.297248,0.067308,-0.044415,-0.289274,0.289599,0.408329,0.236333,0.391838,0.071593,0.035462,-0.011415,0.035089,-0.300270,0.265366,0.238199,-0.060866,-0.098965,0.365890,0.169600,-0.151890,-0.153308,0.101492,-0.164519,-0.685178,0.103177,-0.029212,0.134210,-0.514904,0.204374,-0.316506,0.115334,0.098764,-0.376736,0.019112,0.388407,0.380382,0.232729,-0.266666,-0.055051,-0.641887,-0.165725,0.790704,-0.116684,0.092468,0.130762,-0.147738,-0.125830,-0.022215,-0.223483,-0.499499,0.045805,0.580837,0.039073,-0.150189,0.398025,-0.408367,-0.118172,-0.253343,-0.062662,-0.056905,-0.437692,0.177752,-0.435015,-0.016007,-0.086515,-0.372970,-0.011179,0.090251,-0.338672,0.426876,-0.636802,0.143898,0.783471,0.544263,-0.353840,0.511849,0.049601,0.077045,-0.323526,-0.021329,-0.081208,0.193777,0.091637,0.290170,0.038808,0.302649,0.0