INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1907966', '疯狂原始人', '喜剧', '原始人咕噜一家六口在老爸Grug（尼古拉斯·凯奇 Nicolas Cage 配音）的庇护下生活。每天抢夺鸵鸟蛋为食，躲避野兽的追击，每晚听老爸叙述同一个故事，在山洞里过着一成不变的生活。大女儿Eep（艾玛·斯通 Emma Stone 配音）是一个和老爸性格截然相反的充满好奇心的女孩，她不满足一辈子留在这个小山洞里，一心想要追逐山洞外面的新奇世界。没想到世界末日突然降临，山洞被毁，一家人被迫离开家园，展开一场全新的旅程。离开了居住了“一辈子”的山洞，展现在他们眼前的是一个崭新绚丽却又充满危险的新世界，到处都是食人的花草和叫不出名字的奇异鸟兽，一家人遇到了全所未有的危机。在旅途中，他们还遇到了游牧部落族人Guy（瑞恩·雷诺兹 Ryan Reynolds 配音），他有着超凡的创造力和革新思想，帮助咕噜一家躲过了重重困难，途中他还发明了很多“高科技”产品，并让他们知道了原来生活需要“用脑子”，走路需要“鞋子”等等。一行人在影片中展开了一场闹腾而又惊险的旅程。', '尼古拉斯·凯奇', '柯克·德·米科', 8.7, 790615, 'tt0481499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1867084027.jpg', 0.1, 0.6, 11.3, 41.5, 46.5, '0.211074,-0.093115,-0.847252,0.559469,-0.101979,-0.125018,0.922387,-0.076243,-0.505866,-0.159474,0.138424,0.782417,-0.181475,0.137264,0.074838,-0.019772,-0.188368,-0.359122,-0.051878,-0.012719,-0.310778,-0.197729,-0.257866,-0.323258,-0.050989,-0.328764,0.346866,0.252810,-0.225573,0.392973,0.097540,-0.047067,-0.264721,0.496797,-0.375310,0.141400,-0.068313,0.166792,-0.100356,0.138742,-0.066538,-0.170667,-0.287663,0.177355,-0.055888,0.176775,0.556058,-0.265524,-0.235616,-0.041983,0.139967,-0.273100,-0.192158,0.084785,0.266923,-0.213592,0.218442,0.140975,-0.142623,0.164951,0.004187,-0.130492,-0.731446,-0.000196,-0.009767,0.125557,-0.692677,0.284600,0.314326,-0.123806,0.173554,-0.431856,0.319748,0.136396,0.499140,0.655250,-0.016175,0.052863,-0.659818,0.082616,0.724513,-0.229464,-0.294277,0.512183,-0.349076,-0.221528,-0.120155,-0.039962,-0.639516,-0.168352,0.168089,0.024858,-0.502988,0.144586,-0.731634,0.463501,-0.105746,-0.445787,-0.059144,-0.433798,-0.299390,-0.607392,0.000938,-0.365880,-0.281731,0.294258,-0.041637,-0.240548,0.626965,-0.859827,0.129259,0.592750,0.252193,-0.304450,0.657952,-0.022040,0.009683,-0.059653,0.132026,0.152121,-0.059008,0.294125,0.033232,0.438465,-0.012927,0.104932,-0.651712,0.622899', '3055049', '1296534', '1866424', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1908036', '黄色的眼泪', '剧情', '1963年早春，成功申办奥运会的日本东京到处是热火朝天的建设场面，日本经济高度增长。然而就在这样的大发展时代大潮中，仍有一小群笨拙地坚守着梦想的人。青年村冈荣介（二宫和也 饰）的母亲身患癌症却坚持不肯就诊，荣介只好花钱临时找来歌手井上章一（相叶雅纪 饰）、作家向井龙三（樱井翔 饰）和画家下川圭（大野智 饰）演了一出戏，才把母亲哄骗进医院。荣介请他们在小饭店荣屋吃了顿饭后，各奔东西。几天后，四人在机缘巧合下重聚在一起。一直努力想当一名儿童漫画家的荣介，收留了同样正在为梦想而努力的三人。本片改编自有“青年漫画教祖”之称的已故漫画家永岛慎二的名作《年轻人们》。该漫画曾于1974年被改编成电视连续剧《黄色的眼泪》，电视剧深深感动了一名酷爱电影的少年，他就是本片导演犬童一心。32年后，犬童一心终圆夙愿，邀请活力偶像组合“岚”领衔主演这部有关梦想与现实的青春物语。', '二宫和也', '犬童一心', 8.2, 10102, 'tt0879825', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p661308569.jpg', 0.2, 1.5, 18.9, 46.4, 32.8, '-0.199623,-0.009943,-0.399261,0.373375,0.245922,-0.388351,0.494692,0.206102,-0.299773,-0.397128,0.126238,0.747625,-0.236175,0.315886,0.244004,-0.133751,-0.315982,-0.607934,-0.214002,-0.005921,0.048014,-0.021411,-0.152696,-0.147895,-0.218872,-0.093078,0.781700,0.140679,0.018290,0.290287,0.477546,0.101829,-0.003407,-0.047275,-0.116055,0.079381,0.114176,0.070139,-0.166670,0.263034,-0.098746,-0.385543,-0.445166,-0.125885,0.037282,0.092147,0.645948,-0.010680,-0.001650,0.029256,0.351721,-0.131077,-0.163038,-0.035025,0.348571,-0.048873,0.335569,0.056363,-0.189194,-0.025415,-0.114006,-0.372247,-0.612884,-0.010720,0.194881,0.230106,-0.592497,0.424165,-0.041182,-0.213913,0.145290,-0.314151,-0.166710,0.127894,0.374383,0.474989,-0.147937,0.141265,-0.252075,0.771724,0.493511,0.079393,-0.079675,0.501036,-0.000139,-0.274047,-0.262289,-0.353863,-0.565109,-0.075644,0.161417,-0.126983,-0.163731,0.077526,-0.480331,0.001703,-0.129802,-0.208242,0.192405,-0.043996,-0.016159,-0.639708,0.131661,-0.328596,0.047625,-0.000608,0.223950,-0.246256,1.150952,-0.582926,0.065342,0.593672,0.094088,-0.475328,0.742032,0.097519,-0.055347,-0.098543,0.044276,0.086023,-0.252611,0.189375,0.148695,0.356684,-0.214377,-0.208021,-0.373879,0.217008', '27602116', '3811356', '25863940', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1908318', '在黑暗中等待相遇', '剧情', '根据乙一同名畅销小说改编。因遭遇意外事故后天失明的少女本间（田中丽奈 饰）与父亲安静地生活在大房子里，平日生活就是阅读父亲带回来的盲人图书，以及和好友出行逛街谈心。这天她推开窗户，不知窗户面对的轻轨上发生了杀人事件。随后而来父亲遭遇车祸去世，本间婉拒亲戚的好意决定仍然独自居住在这个房子里。大石（陈柏霖 饰）是一个孤僻的少年，在印刷厂工作的他与同事谈不来，亦被上司故意为难。受不了的大石在上司每天经过的地铁站企图将上司推下铁轨，他的手想伸出去，上司倒下……已经成为最大嫌疑人的大石逃进了本间的房子，与她默默相处，安静无声。本间意识到房子内有人，也意识到他对她没有坏心。在这个逼仄的房间里，本间要面对自己不敢外出世界的恐惧，大石要面对真相的拷问。安静的二人滋生出一种奇妙的互相扶持的心理。一天，大石说他不是凶手，真凶另有其人，而本间也应该“看见”了凶手。©豆瓣', '田中丽奈', '天愿大介', 7.4, 5622, 'tt0872007', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p562219019.jpg', 0.4, 3.7, 35.4, 45.1, 15.4, '0.384736,-0.035681,-0.716471,0.266399,-0.168129,-0.055478,1.053739,0.250019,-0.549478,-0.312927,0.421965,0.822579,-0.213785,0.361447,0.248358,0.064570,-0.190326,-0.554049,-0.089456,-0.143596,-0.259157,-0.395530,-0.151171,-0.299920,-0.164066,0.098089,0.509549,0.062782,-0.194515,0.387134,0.116936,0.422928,-0.126260,0.500238,-0.167298,0.026983,-0.093545,0.103629,-0.154480,0.100018,0.026622,-0.388495,-0.167187,0.109645,0.118250,0.260217,0.721804,0.076513,-0.164406,0.237989,0.198456,-0.139911,-0.027325,0.183795,0.573992,0.079720,0.046999,0.363076,-0.381001,0.071762,0.061270,-0.099348,-0.494991,-0.134903,0.013307,0.250388,-0.477785,0.447070,-0.089889,-0.322619,0.114606,-0.436504,0.189861,0.200507,0.203965,0.522801,-0.335763,0.003432,-0.332197,-0.133346,0.559001,-0.043397,0.113342,0.404827,-0.292630,-0.182787,0.008859,-0.215007,-0.436482,-0.244574,0.204015,0.058716,-0.535425,-0.054134,-0.401061,-0.206736,-0.139223,-0.211750,-0.073310,-0.416659,-0.162716,-0.397576,-0.085178,-0.248192,-0.357994,0.175260,0.098047,-0.248428,0.411077,-0.875029,0.185574,0.533949,0.292107,-0.384440,0.648904,0.116754,-0.014085,-0.179283,0.185566,0.283314,0.119057,0.619546,0.137191,0.285727,-0.137445,0.072198,-0.618610,0.216216', '1296534', '1302384', '21619567', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1914652', '真爱之吻', '喜剧', '佩内洛普（克里斯蒂娜•里奇 饰）出生在贵族家庭，可是她的家族被诅咒了她一出生便有着一个猪鼻子。佩内洛普对自己的样貌感到十分的自卑，她羞于与一切人交往，要想解除这个诅咒，便要得到一个出自真爱的吻，才能让佩内洛普恢复美貌。女儿长大了，佩内洛普的父母极力张罗她的婚事，佩内洛普也想找到个真正爱她的人解除魔咒。可是每个看到佩内洛普真面目的男子都落荒而逃，令佩内洛普与父母都感到十分难堪与沮丧。以往，每个见过佩内洛普真面目的男生都签约保证不会向外界透露这个秘密。可是某贵族继承人却走漏了风声。记者雷蒙当年想得知佩内洛普的真面目，却让佩内洛普的母亲击伤了右眼，此时他要与贵族继承人合作，雇人假扮相亲者与佩内洛普见面，以拍到她的真面目。但被雇佣的麦克斯（詹姆斯•麦卡沃伊 饰）是个没落贵族，佩内洛普误以为他不在乎自己的面貌，备受感动。实际上麦克斯从未见过佩内洛普，两人隔着一块玻璃相处良久后彼此吸引住了，但他碍于与佩内洛普的身份相差甚异，默默离开了。最后佩内洛普又能否找到真爱，得到真爱之吻解除恶毒的魔咒呢？', '克里斯蒂娜·里奇', '马克·帕兰斯基', 6.7, 56203, 'tt0472160', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p461623169.jpg', 0.7, 7.5, 54, 29.9, 7.8, '0.258699,-0.098672,-0.759329,0.696362,-0.265308,-0.150986,0.957755,0.025099,-0.428369,-0.395490,0.172762,0.945275,-0.486611,0.405434,0.142005,0.290912,-0.137782,-0.650691,0.199258,-0.218812,-0.094429,-0.351918,-0.152876,-0.145453,-0.193547,-0.281868,0.755710,-0.059300,-0.250139,0.345702,0.280219,0.285359,0.123679,0.448056,-0.444084,0.108985,-0.062391,0.151940,-0.063083,0.232748,0.006974,-0.088437,-0.091800,0.499833,-0.206492,0.453964,0.402075,-0.194789,-0.134684,0.054882,0.162947,-0.188001,0.095426,0.519624,0.257559,-0.259214,0.211263,0.072674,-0.214178,-0.116205,0.149197,0.147427,-0.793787,0.087429,0.242410,0.159424,-0.631248,0.360000,-0.330447,-0.063649,-0.257227,-0.156701,0.056235,0.280121,0.104205,0.421347,-0.205458,0.036406,-0.552662,-0.133929,0.694499,0.126748,-0.136981,0.342925,-0.312641,-0.602520,0.045626,-0.234741,-0.738771,0.189005,0.259171,0.266040,-0.071307,0.279466,-0.509479,-0.289830,-0.378480,0.026474,-0.029341,-0.852849,0.105778,-0.107025,-0.558392,-0.503118,-0.535990,0.033199,0.185792,-0.476724,0.812481,-0.838099,0.117449,0.438923,0.487454,-0.731030,0.532128,0.451627,0.136454,-0.253650,-0.051788,0.410084,0.280529,0.007818,0.136177,0.2