INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1914681', '留级之王2', '喜剧', '泰吉•巴德兰德巴德（卡尔•潘 Kal Penn 饰）带着范•维尔德的精神和大学学位，远赴英国加尔福德大学——这里是他父亲曾经“战斗”过的地方，兄弟会“狐狸与猎犬”之屋留下了父亲风光的记忆，然而来这里担任助教的泰吉并不被对方认可，狐狸与猎犬的首脑皮普反而将泰吉戏弄了一通。泰吉来到自己负责的宿舍——被戏称为马厩的败落小屋，这里住着四个边缘化的学生：研究量子物理和男女关系的盖辛，暴躁的爱尔兰人谢莫斯，沉默的宅男赛门以及不检点的女生赛迪。泰吉为了让这几位问题青年重新振作，自组鸡公牛社团向皮普的狐狸与猎犬之屋发起挑战，而皮普的女友查莉令泰吉一见钟情，于是一场关乎学生尊严和助教爱情的奋战拉开了序幕……©豆瓣', '卡尔·潘', 'Mort Nathan', 6.1, 5525, 'tt0480271', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1621687594.jpg', 3.8, 17.9, 55.9, 16.2, 6.2, '0.541684,-0.246063,-0.512380,0.743852,-0.053538,-0.496490,0.567409,0.182046,-0.390060,-0.357713,-0.119051,0.596852,-0.072820,0.452886,0.390498,-0.138043,-0.264503,-0.628958,-0.294851,0.095067,-0.170861,-0.479392,-0.029362,-0.184547,-0.121131,-0.171781,0.566660,0.121279,-0.292246,0.631606,0.275275,0.389771,-0.151048,0.163957,-0.039727,0.082712,0.190767,-0.001448,-0.089316,0.065516,0.269989,-0.030252,-0.231964,0.057617,0.124369,0.241794,0.557092,-0.065573,0.010102,-0.413868,0.043005,-0.330136,0.148493,0.228704,0.478220,-0.060310,0.235700,0.245411,0.311425,0.044101,0.093262,-0.283484,-0.518036,-0.013908,0.027450,0.085811,-0.563303,0.697128,-0.137588,-0.092427,0.127288,-0.121484,-0.003006,0.287068,0.274973,0.432290,-0.086316,0.175257,-0.452617,0.084937,0.432000,-0.119076,-0.254663,0.147574,-0.019586,-0.633129,-0.023494,-0.088105,-0.404412,-0.105524,0.280582,0.052765,-0.077551,0.146650,-0.825791,-0.046515,-0.210888,-0.002668,0.060496,-0.449296,-0.064424,-0.657576,-0.076771,-0.392366,-0.249374,0.075043,0.140561,-0.050523,0.479248,-0.821536,0.147949,0.489210,0.413029,-0.311579,0.655639,-0.073016,0.293311,-0.171023,-0.043286,0.020382,0.203903,0.427481,0.400087,0.332570,-0.099842,-0.283726,-0.365380,0.483171', '26365262', '1414808', '1420088', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1914682', '恋爱学分', '剧情', '这是布莱恩·杰克逊（詹姆斯·麦卡沃伊 James McAvoy 饰）刚刚升入英国布里斯托大学的第一年，纵情的聚会和销魂的香烟都令他如坠云端，然而更加吸引他的则是比拼知识的电视节目大学挑战赛。虽然负责带队的老师（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）开始对他不屑一顾，但布拉恩还是凭借从小对知识的积累和热情赢得了参赛资格，与此同时，与美丽队友爱丽丝（爱丽丝·伊芙 Alice Eve 饰）的暧昧火花也翩然而至。然而在际遇丰富的大学校园中，布莱恩又恋上了另一位有思想的女生丽贝卡（丽贝卡·豪尔 Rebecca Hall 饰）并同她度过了第一个离家在外的新年。然而当对手强大的比赛和三角恋情的压力来临，布莱恩是否做好了准备迎接人生挑战，赢得成长学分？©豆瓣', '凯瑟琳·塔特', '汤姆·沃恩', 6.8, 14410, 'tt0477095', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1023597457.jpg', 0.5, 6.6, 54, 30.5, 8.4, '0.182177,-0.033914,-0.605946,0.651219,-0.082013,-0.277799,0.420008,0.127198,-0.161982,-0.070708,0.111255,0.724724,-0.333644,0.389007,0.519603,-0.173368,-0.213498,-0.762413,0.068535,-0.113034,-0.250101,-0.500247,-0.126091,-0.187564,0.148808,-0.483045,0.699406,0.037191,-0.264056,0.861836,0.274681,0.317631,0.134782,0.590485,-0.063729,-0.225466,0.264849,0.329722,-0.223147,0.100231,0.024760,-0.013730,-0.246674,0.207372,0.382015,0.371389,0.503373,-0.242140,0.009354,-0.080657,0.340680,-0.167967,0.165073,0.141948,0.229925,0.207308,0.122149,0.272357,0.176390,0.288907,-0.222558,-0.531775,-0.625737,0.016314,0.173743,-0.089048,-0.464295,0.697842,-0.105271,-0.147872,0.200354,0.060600,-0.047101,0.395206,0.138336,0.458476,-0.128539,-0.002781,-0.409991,0.170082,0.539124,0.037752,-0.263743,0.400852,-0.263068,-0.501399,-0.045222,-0.120823,-0.328690,-0.007437,0.207323,0.191206,0.170046,0.190122,-0.627672,0.126676,-0.122697,-0.165281,0.050158,-0.549896,-0.148385,-0.715627,-0.130298,-0.455461,-0.507143,-0.026245,0.124450,-0.316068,0.985781,-1.000993,0.035759,0.422024,0.253880,-0.290071,0.636558,0.135749,0.038480,-0.240076,-0.276688,0.381358,-0.139566,0.167253,0.012134,0.507722,0.022449,-0.264755,-0.382473,0.737662', '25922902', '4127270', '3811356', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1914787', '丑闻笔记', '剧情', '希芭·哈特(凯特·布兰切特 饰)是学校里新来的美术老师，她年轻美丽，气质高雅。老教师芭芭拉(朱迪·丹奇 饰)悄悄地关注起希芭，并渐渐和希芭结成好友。希芭把芭芭拉当成密友，向她倾诉年迈丈夫的无趣，女儿的叛逆和儿子的低能。两个女人结为看起来温馨又和谐的忘年之交。无意中芭芭拉发现希芭与学生的不论之恋，她逼迫希芭承认了奸情，并答应保守秘密。可是两个人的友谊却由此变质。保密人芭芭拉对希芭的占有欲越来越强，希芭在秘密被泄露的威胁下一次次屈服。然而秘密总有被泄露的一天，保密人事无巨细的日记转瞬成了记满丑闻的笔记。©豆瓣', '朱迪·丹奇', '理查德·艾尔', 7.9, 27799, 'tt0465551', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1127807830.jpg', 0.2, 1.2, 23.5, 55.5, 19.5, '0.430126,-0.003270,-0.379096,0.381626,0.108660,-0.003405,0.688897,-0.018051,-0.369823,-0.250819,-0.190557,0.540992,-0.396137,0.166144,0.293953,0.211103,-0.179459,-0.789826,-0.011547,-0.233613,-0.105008,-0.803965,-0.166018,-0.270560,0.000133,-0.413027,0.264215,-0.075649,-0.275559,0.222076,0.387579,0.267558,-0.294777,0.414870,0.176606,0.011425,0.148338,-0.085378,-0.122268,-0.114479,-0.022150,0.027612,-0.142153,0.134670,0.253818,0.637831,0.695705,-0.248790,-0.333355,-0.087608,0.310258,-0.207843,-0.276339,-0.149689,0.232432,-0.193921,0.110805,0.275075,0.029817,-0.356734,-0.035130,-0.111309,-0.473184,0.039542,0.269231,0.175027,-0.269098,0.288403,-0.053507,0.261109,0.029622,-0.194282,-0.067899,-0.216764,0.018625,0.266075,0.085659,0.193060,-0.215516,0.073949,0.389633,0.244695,-0.456331,0.359432,-0.595080,-0.177047,-0.037446,-0.189736,-0.972208,0.003694,0.197793,0.174772,-0.001221,0.512402,-0.421465,-0.487013,-0.469403,0.321922,0.097941,-0.790492,0.045698,-0.326984,-0.212059,-0.261692,-0.509555,0.015401,-0.057861,-0.505394,0.788124,-0.651066,0.453164,0.713004,0.289305,-0.378507,0.576491,0.234363,0.375085,-0.213615,-0.496048,0.544207,0.162711,-0.205192,0.095056,0.344168,-0.130920,-0.222936,-0.397189,0.227761', '26348103', '1309161', '4058963', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1914831', '盛夏光年', '剧情', '康正行（张睿家 饰）就读于一件海边小学，身为班长的他被老师任命陪伴一个多动症的小孩余守恒（张孝全 饰），慢慢影响他，让他变成一个乖孩子。两个人在成长的过程中成为了好朋友，但在康正行心里的这份友谊却变质了。一天，一个叫慧嘉（杨淇 饰）的女孩出现在他们面前，这个寂寞的女孩很快喜欢上了正行，但正行心里爱着的却是另外一个人。慧嘉知道了正行心意后，跟他成为了好朋友。守恒也开始追求慧嘉，守恒却不想太早让正行知道，他觉得正行跟慧嘉都是他生命中不可或缺的人。各自怀有秘密的他们生活开始变得混乱，终于他们在海边说出了自己的秘密……©豆瓣', '张睿家', '陈正道', 7.2, 124139, 'tt0885520', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2675971821.jpg', 0.8, 5.2, 40.8, 39.1, 14.1, '0.541227,0.088504,-0.673753,0.612516,-0.418724,-0.208946,0.848910,0.313181,-0.745015,0.001830,-0.063728,0.911004,-0.004829,0.505087,0.285101,0.018299,-0.300494,-0.750896,0.147939,-0.223240,-0.298666,-0.452409,-0.164446,-0.219603,-0.214305,-0.192955,0.589212,0.195453,0.198380,0.373812,0.235490,0.004722,0.200797,0.653156,-0.247544,0.081311,0.000708,0.008072,0.074886,-0.155964,0.005809,-0.196515,-0.046684,0.443891,-0.074251,0.336320,0.575190,-0.091708,-0.325536,-0.170195,0.271602,-0.415392,-0.211357,-0.053647,0.115643,0.156748,0.274538,0.063827,-0.206648,0.032433,-0.110657,0.054094,-0.683227,0.008751,0.178943,0.181994,-0.676272,0.587224,0.045045,-0.324259,0.007648,-0.398642,0.310348,0.306816,0.233827,0.295861,-0.444469,-0.017166,-0.646135,0.126121,0.864529,-0.013149,-0.347600,0.457272,-0.220373,-0.496743,-0.127933,-0.154343,-0.479944,-0.163480,-0.086573,0.172872,-0.259969,0.032420,-0.488595,0.245333,-0.063920,0.051877,-0.169806,-0.771376,-0.102807,0.031788,-0.134675,-0.542568,-0.583756,0.126220,-0.210109,-0.297943,0.980285,-0.913014,0.234341,0.630312,0.356571,-0.568383,0.812086,0.314657,0.113339,-0.390336,0.073278,0.082025,-0.287207,0.044007,0.219184,0.420413,-0.069813,-0.012187,-0.392861,0.605617', '25721544', '3230462', '30162520', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1914923', '黑色星期五', '恐怖', '少女惠特妮•米勒（Amanda Righetti 饰）及其男友麦克（Nick Mennell 饰）等一行五人前往水晶湖森林游玩，快乐的假期很快为血腥杀戮所取代，躲藏在暗处的杀人魔王杰森（Derek Mears 饰）突然出现，将青年男女们逐一杀害。六周后，大学生特伦特（Travis Van Winkle 饰）及其一班朋友又来到水晶湖的小木屋内狂欢，他们偶遇寻找妹妹惠特妮的克雷（Jared Padalecki 饰）。虽然警方声称此地不见失踪人员身影，但克雷坚信妹妹必然身在丛林某处。与此同时，特伦特的两个朋友遭到杰森袭击，这群惶恐的大学生和克雷联合起来，共同面对身带血腥与杀戮气息的杰森……©豆瓣', '贾德·帕达里克', '马库斯·尼斯佩尔', 5.9, 11016, 'tt0758746', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2177128470.jpg', 4.7, 22.4, 52.9, 14.2, 5.7, '0.005948,-0.391384,-0.584334,0.320550,0.260751,-0.141618,0.887961,0.171050,-0.433547,-0.469828,0.271696,0.414365,-0.173319,0.277097,0.442553,-0.322241,-0.429717,-0.394343,-0.324723,-0.358269,-0.164800,-0.047071,-0.174677,-0.090831,0.084175,-0.419887,0.672690,0.141332,0.098079,0.681666,0.209986,0.477934,-0.652458,0.254774,-0.021536,-0.316809,0.501651,-0.009077,-0.441583,0.274816,-0.485079,-0.057955,0.064534,-0.084121,-0.210015,0.196874,1.021171,-0.298222,-0.005683,-0.304974,0.090320,-0.183334,0.113945,0.116767,0.544272,-0.166185,0.342980,0.047184,-0.089695,-0.013121,-0.146158,-0.190445,-0.362288,0.350421,0.187968,0.238987,-0.194728,0.014272,0.103403,-0.105715,0.267037,-0.013803,0.095567,0.293486,0.149230,0.030401,0.018442,0.040048,-0.247170,-0.158344,0.622737,-0.106513,0.146767,-0.025191,-0.053636,-0.301023,0.219352,0.269788,-0.271797,-0.118267,0.294517,0.079491,0.223486,0.352221,-0.808309,-0.066060,-0.379441,-0.055883,0.186633,-0.334258,-0.376302,-1.053772,0.048466,0.270004,-0.087216,0.230187,-0.035720,0.199360,0.446586,-0.621275,0.583506,0.384240,0.157497,-0.425129,0.342748,-0.215684,0.137817,-0.332970,-0.124365,0.516041,0.621536,0.184460,-0.199994,0.156039,-0.295050,-0.013132,-0.372065,0.019575', '10466639', '1306809', '4706257', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1915180', '老千', '剧情', '辛苦打工赚钱的高尼（曹承佑饰）工资低微，但性格好强的他不甘于贫穷。有一天，他输光了所有的钱，发现被老千所耍。气愤的他去理论，遇到了老千高手平京长（白润植饰），为了学到高超的赌术，高尼费尽心思拜平京长为师，并保证赢回一定数额就洗手不干。终于，学有所成的高尼出山后，开始了老千生涯。最初他是想把输掉的钱赢回来，但是人的欲望是没有止境的，他违背了当初许下的承诺，同时他的出色赌技引起了美女郑老板（金惠秀饰）的赏识，并与另一位老千开始了合作。一轮又一轮的赌局中，高尼迎来了生死之战。©豆瓣', '曹承佑', '崔东勋', 7.6, 48367, 'tt0875025', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1005194174.jpg', 0.4, 2.4, 30.8, 48.5, 17.9, '-0.092078,0.259699,-0.486579,0.522139,-0.531924,-0.446662,0.404962,-0.209317,-0.287148,-0.010051,0.170690,0.812531,0.106611,0.229536,0.119286,-0.168728,0.144182,-0.684006,0.026410,-0.252538,-0.100751,-0.467695,-0.084007,-0.082129,-0.263386,-0.207900,0.393187,0.359622,-0.273109,0.291071,0.423965,-0.085839,0.470332,0.470287,-0.252151,-0.009243,-0.098509,0.041124,-0.147648,0.147561,0.260394,-0.297118,-0.206399,0.179938,0.258396,0.459355,0.335141,0.150324,-0.260154,0.149415,0.398712,-0.282451,-0.101720,0.111285,0.252175,0.192996,0.064061,0.137585,-0.172690,-0.025333,0.010965,-0.219575,-0.977046,-0.087067,0.129755,-0.239155,-0.746565,0.468506,-0.042435,-0.115020,-0.204131,-0.126509,0.005526,0.206728,0.439264,0.036943,-0.122673,-0.098984,-0.578759,0.435194,0.751451,-0.093111,-0.040802,0.371034,-0.012576,-0.667566,0.127330,-0.626499,-0.237218,0.164118,0.644755,-0.008082,-0.148853,-0.023752,-0.555213,0.104550,-0.134381,-0.062316,-0.096007,-0.432272,-0.026556,-0.203866,-0.285995,-0.355346,-0.406229,0.036533,0.163049,-0.663193,0.907362,-0.833017,0.069118,0.657225,0.297243,-0.621246,0.714980,-0.003039,-0.018746,0.075514,-0.108807,-0.026162,-0.005370,0.361534,0.147726,0.268375,0.050008,-0.215851,0.173728,0.590193', '1877596', '27602116', '1793491', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1915342', '看车人的七月', '剧情', '家庭离异的中年男人杜红军（范伟 饰）是一名看车人，年过不惑的他渴望重新拥有一个完整的家庭，于是和美丽的花店店主小宋（陈小艺 饰）好上了。小宋也是一个离了婚的女人，两人共同的愿望就是赶快组织一个新的家。杜红军的儿子因为思念母亲，一直反对杜红军再婚。但杜红军还是和小宋结了婚。就在一切准备妥当的时候，小宋的前夫刘三从监狱里出来了。刘三反悔了当初的离婚协议，于是一切开始变得不可收拾……©豆瓣', '范伟', '安战军', 8, 10595, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1357942694.jpg', 0.3, 1.2, 20.1, 53.7, 24.8, '0.296808,-0.011963,-0.763373,0.528543,-0.504642,-0.488774,0.583994,-0.016423,-0.634468,-0.259140,-0.298828,0.775007,0.096697,0.940108,0.148051,0.160412,-0.096909,-0.768076,-0.264972,0.000783,-0.485957,-0.636741,-0.004566,-0.410132,-0.034258,0.118691,0.353683,0.188292,0.040660,0.243455,0.435711,0.048629,0.014451,0.594444,0.007840,0.198295,-0.066137,-0.065749,-0.591834,-0.162767,0.139449,-0.084133,-0.139734,0.323693,0.223187,0.413599,0.502892,0.061907,-0.158274,-0.126893,0.403101,0.052708,-0.139982,0.171349,0.450559,0.001655,0.258954,0.249004,-0.177155,-0.253748,-0.109750,-0.303433,-0.324727,0.027772,0.128290,-0.221373,-0.593610,0.447483,-0.015822,0.221893,0.143747,-0.495649,0.292445,0.298153,0.161017,0.385048,-0.399887,0.088366,-0.582002,0.535291,0.646809,0.180680,-0.074849,0.350896,-0.206117,-0.579767,-0.418370,0.065658,-0.726620,0.048380,0.394596,-0.014332,-0.190959,-0.202375,-0.705218,-0.174814,-0.276975,0.126683,0.030764,-0.297741,0.083342,-0.113616,-0.290259,-0.518613,-0.502564,0.381294,-0.288823,-0.169868,0.861696,-0.579124,0.123271,0.290193,0.135899,-0.925356,0.523227,0.215671,0.396063,-0.178287,0.257147,0.200715,-0.157365,0.103294,0.319650,0.359124,-0.193885,0.119545,0.032776,0.562304', '27135473', '26730542', '1309013', '24879820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1915381', '逃离猩球', '科幻', '好莱坞早在1968年就拍摄了这一取材于法国作家皮埃尔.鲍李（Pierre Boulle）的著名同名科幻小说的电影，在当时，影片以其构思奇特的情节、精妙*真的化装技术以及令人出乎意料甚至颇感震撼的结局而大受欢迎，也催生了其后的四部续集和两部电视剧集的诞生。影片要素：两千年后的地球，上校乔治.泰勒（Colonel George Taylor），和他的战友们，以佐斯博士（Dr. Zauis）为首的残暴的星球统治者，善良的同情人类的猿族夫妇兹瑞和考尼斯（Zira and Cornelius）和他们的儿子凯撒（Caesar），猿族，人类影片资料：《人猿星球》（Planet of the Apes） 1968年 乔治的飞船误入两千年后的地球并失事，在善良的猿族夫妇兹瑞和考尼斯的帮助下，他逃出了猿族的监牢，但猿族首领佐斯博士并没打算放过他...《失陷猩球》（Beneath the Planet of the Apes） 1970年 前来搜寻乔治的飞船再次失事在星球上，新加入的战友和乔治联手去阻止猿族对人类的杀戮。《逃离猩球》（Escape from the Planet of the Apes） 1971年 帮助人类的猿族夫妇兹瑞和考尼斯这回自身难保，他们的飞船坠毁在1973年的地球，人类发现了未来猿族将要统治人类，瑞兹肚里的小猿孩能存活吗？人们将怎么对待他们这对会说话的猿族？《猩球征服》（Conquest of the Planet of the Apes） 1972年 上集中猿族夫妇最终没能逃脱人类毒手，但他们的孩子凯撒却在善良的马戏团主里卡多（Ricardo Montalban）的保护', '罗迪·麦克道尔', '唐·泰勒', 7.6, 5726, 'tt0067065', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2242995363.jpg', 0.6, 2.4, 30, 50.5, 16.4, '0.207198,-0.019878,-0.771365,0.609777,0.093275,-0.125762,0.643769,-0.209676,-0.338911,-0.087333,0.253771,0.911171,0.028914,-0.041843,0.194655,0.096155,-0.405356,-0.330722,-0.197917,-0.156940,-0.342836,-0.214844,-0.503411,-0.524046,-0.043274,-0.560414,0.796758,0.048538,-0.057599,0.426284,0.006590,0.148111,0.032964,0.094019,-0.150106,0.210980,0.061607,-0.008324,-0.279703,0.227207,-0.214148,-0.011817,-0.174901,0.178113,-0.159133,0.326063,0.471414,-0.532015,0.069134,-0.269740,0.175749,-0.469978,-0.031416,-0.000457,0.425429,-0.385400,-0.036160,0.364158,0.089380,-0.195707,-0.077691,-0.022769,-0.968026,0.011771,-0.142679,0.042420,-0.513492,0.542198,-0.004541,0.142337,-0.089344,-0.256741,0.220107,0.618811,0.180952,0.355354,-0.028334,0.048652,-0.431356,0.283654,0.649973,-0.095563,-0.457545,0.188114,-0.111124,-0.762245,-0.478738,-0.461354,-0.613149,-0.036853,0.481743,0.057452,-0.248859,0.389873,-0.780247,0.042734,-0