INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1915385', '决战猩球', '动作', '故事发生在人猿的全球革命和人类之间的残酷核战争十年后，凯撒必须保护人猿和人类两方的幸存者免受邪恶人类和人猿好战派系的威胁……', '罗迪·麦克道尔', 'J·李·汤普森', 6.7, 4988, 'tt0069768', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2242996448.jpg', 1.9, 9.6, 50, 26.5, 12, '0.397344,-0.123498,-0.596262,0.411325,0.156767,0.266168,0.958464,-0.402418,-0.457527,0.173758,0.008365,0.864763,-0.059644,-0.277388,0.185270,-0.468445,-0.305176,-0.635797,-0.449508,0.175819,-0.307681,-0.433394,-0.678127,-0.624975,-0.032965,-0.587536,0.928015,0.226116,-0.526792,0.468599,0.008936,0.435112,-0.641581,0.174868,0.080837,-0.357253,0.028971,-0.084069,-0.917324,-0.124014,0.003899,-0.011445,-0.071248,0.408498,-0.542035,0.205842,0.344675,-0.919669,-0.238721,-0.695396,0.322047,-0.518337,-0.538805,0.096421,0.651716,-0.302275,0.154330,0.566938,0.679172,-0.176105,-0.009307,-0.179619,-1.230292,-0.365838,-0.059109,0.204698,-0.290903,1.121716,0.433657,0.273639,0.608838,0.133138,0.148374,0.850535,0.475131,0.597026,-0.220130,0.101869,-0.487805,-0.142388,1.236985,-0.084905,-0.817377,-0.301380,-0.086564,-0.852958,-0.714638,-0.684811,-0.567106,0.037864,0.166035,-0.083710,-0.597658,0.850773,-1.323058,-0.000875,0.022541,-0.294665,0.261452,-0.241438,0.019916,-0.609230,-0.443851,-0.910826,-0.188769,0.352204,0.399867,-0.271090,1.026657,-1.027074,0.216841,0.457026,0.568384,-0.796567,0.514220,0.042233,0.372465,-0.291407,-0.001968,0.298816,0.141402,0.255704,0.189132,0.105639,0.164914,0.497358,-0.018487,0.490965', '1849026', '1308837', '26678784', '1422920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1915393', '娜娜2', '剧情', '喧哗东京，同年出生的大崎娜娜（中岛美嘉 饰）和小松奈奈（市川由衣 饰）同住一起，各自经历着激荡绚烂的青春。娜娜和乐队BlackStone同心协力，携手朝着目标奋勇前进。虽然娜娜曾经发出警告，但是因失业而烦闷的奈奈还是未能抵挡Trapnest的队长一之濑巧（玉山铁二 饰）的诱惑，而与之陷入热恋。一向将工作放在首位而在男女之事上表现随便的巧，其作为自然引起周围人的不满，尤其是对奈奈心存爱恋的寺岛伸夫（市川由衣 饰）。伸夫的赤诚与执着，对比巧的冷漠轻浮，终于让痛苦的奈奈做出了决定。全新的恋情，全新的道路，这群年轻人还将经历更多的考验……本片根据矢泽爱的同名小说改编。©豆瓣', '中岛美嘉', '大谷健太郎', 6.4, 31292, 'tt0882791', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2256750202.jpg', 3, 15.7, 48.7, 22.8, 9.7, '0.319975,-0.081204,-0.561473,0.528070,0.142290,-0.345633,0.686663,0.266907,-0.339266,-0.108803,0.243943,0.523370,-0.113049,0.270270,0.259835,-0.101653,-0.249026,-0.713857,-0.163956,0.004324,-0.028681,-0.362569,0.039580,0.155328,-0.190869,-0.313801,0.710280,0.089999,-0.226666,0.601471,0.530379,0.503992,-0.307767,0.337298,0.194065,-0.178452,-0.049183,0.318084,-0.488697,-0.039979,-0.038033,-0.208745,-0.204842,0.177281,-0.103621,0.296569,0.793456,-0.246724,-0.457696,-0.058347,0.439818,-0.182965,-0.026456,0.169905,0.124698,0.166352,0.282096,0.216272,-0.276744,0.090621,0.020380,-0.110210,-0.677886,0.175745,0.275655,0.018908,-0.426849,0.474558,0.138803,-0.278621,0.429419,-0.083255,0.089565,0.391931,0.317307,0.236536,-0.462506,-0.024837,0.033459,0.086526,0.507540,0.102085,-0.346603,0.190309,-0.271610,-0.326888,0.084865,-0.220051,-0.594081,-0.021032,-0.052973,0.134961,0.030651,0.281531,-0.686174,0.101249,-0.065901,-0.070055,0.214753,-0.476848,-0.069066,-0.765683,-0.183007,-0.584500,-0.423179,-0.023245,0.333020,-0.145862,0.988746,-0.845390,0.026212,0.275178,0.246415,-0.270333,0.454069,0.052124,-0.139897,-0.179903,-0.163704,0.274518,-0.124206,0.230538,0.095531,0.318248,-0.077443,0.040769,-0.634863,0.382193', '3811356', '5403927', '25922902', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1915403', '只是爱着你', '剧情', '濑川诚人（玉木宏 饰）是一个大学新鲜人，他不愿参加学校的开学典礼而选择了在校园附近闲逛。他在马路旁遇到了里中静流（宫崎葵 饰），她古怪的行径使热爱摄影的诚人忍不住按下了快门。自此静流喜欢上了诚人，可诚人只当她是朋友。随后他们成为了朋友，诚人也喜欢上了同班的富山美雪（黑木明纱 饰）。他跟静流发现了一个环境优美的树林，因为喜欢诚人的关系，静流也喜欢上摄影。静流要和诚人一起参加摄影比赛，而她的作品就是拍下跟诚人在湖边接吻的画面。但是当天傍晚，静流却不辞而别……©豆瓣', '玉木宏', '新城毅彦', 7.9, 112434, 'tt0872022', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2323383500.jpg', 0.5, 2.8, 25, 43.5, 28.3, '0.668187,-0.056769,-0.645008,0.405382,-0.005487,-0.373615,0.597242,0.207321,-0.357239,0.140708,0.277450,1.141238,-0.150274,0.264735,0.192297,0.308374,-0.400205,-0.808286,0.142602,-0.369691,-0.252505,-0.371188,0.041130,-0.051789,0.059048,-0.292100,0.507062,0.130120,-0.117609,0.904263,0.236494,0.019859,-0.041085,0.558908,-0.056790,-0.059074,0.124662,0.192725,-0.056441,0.155577,-0.350224,-0.475250,-0.198225,0.217656,0.261655,0.479949,0.709395,0.039442,-0.257748,0.024757,0.161967,-0.420951,-0.160483,0.040638,0.404665,0.003364,0.433731,0.100813,-0.065474,-0.180242,0.010527,-0.009167,-0.220870,0.149334,0.095907,0.329440,-0.514224,0.855477,0.024635,-0.345898,0.048698,-0.507943,0.393710,-0.168151,0.213673,0.079485,-0.175732,-0.093172,-0.117935,0.316498,0.733630,0.125932,0.198569,0.561381,-0.364244,-0.357463,-0.143859,-0.243943,-0.454534,-0.146214,0.123268,-0.169619,-0.298263,-0.263306,-0.587417,0.219881,0.274697,0.051951,-0.059561,-0.350283,-0.126355,-0.649117,0.227520,-0.615577,-0.552144,-0.009155,0.007544,-0.384604,0.863228,-1.133101,0.113033,0.766859,0.583221,-0.163050,0.945174,0.187698,-0.183302,-0.005503,0.149527,-0.211658,-0.084113,0.287491,0.039185,0.517605,0.105851,-0.398593,-0.764441,0.320541', '1292219', '1292720', '3139191', '1307755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1916282', '林海雪原', '动作', '1946年冬，人民解放军派出一支剿匪分队，在团参谋长少剑波（张勇手 饰）带领下，深入土匪出没的林区，发动群众实行土改，同时打击盘距在深山里的土匪。一天，小分队在河神庙发现匪徒一撮毛（孟庆芳 饰）的踪迹，设巧计活捉了他，从他身上搜出一张先遣图，通过审讯得知，匪首座山雕（毕钰 饰）要在大年三十晚上摆百鸡宴为自己庆寿。经研究决定，派侦察英雄杨子荣（王润身 饰）化装成土匪胡彪深入虎穴，将来配合小分队里应外合智取威虎山。杨子荣上山后，座山雕并不信任他，经过三番五次较量，最后又献上先遣图，这才打消座山雕的疑虑，他封杨子荣为上校团副和百鸡宴的大总管。杨子荣利用这有利身份对威虎山的军事布署做了全面侦察了解，并巧妙地将情报送了出去。万事俱备，只欠东风......©豆瓣', '张勇手', '刘沛然', 7.8, 3887, 'tt6559408', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2537595119.jpg', 1, 1.6, 25.5, 50, 21.8, '0.064277,0.080739,-0.667141,0.555698,0.083515,0.053662,0.173641,0.011238,-0.292824,0.052657,0.275278,0.120461,0.251004,-0.211294,0.024081,-0.136497,-0.578640,-0.642032,-0.275783,-0.193184,-0.119845,-0.527519,-0.365394,-0.126184,0.253232,-0.090015,0.336834,0.319298,-0.347900,0.217337,0.392809,0.077793,-0.066264,0.187527,0.047819,-0.003313,0.147352,-0.432728,-0.162039,0.206083,-0.161945,-0.136767,-0.305089,-0.188981,0.175163,0.398642,0.832126,-0.423180,-0.299596,-0.101269,0.025338,-0.223195,0.111428,-0.053281,0.449944,0.189427,-0.125137,0.199143,-0.045903,0.159893,-0.265234,-0.180278,-0.532539,-0.026307,0.211320,-0.001348,-0.760195,0.141138,-0.156598,0.305606,0.152786,-0.430446,0.116261,0.567076,0.234273,0.071795,0.075816,0.094048,-0.355038,0.343435,0.298313,-0.284252,0.180075,-0.300755,0.293171,-0.211585,0.294392,-0.101016,0.379249,-0.075293,0.252219,-0.192589,0.081094,-0.269983,-0.405751,-0.159506,-0.428016,-0.064266,0.052979,-0.149921,0.049041,-0.699679,-0.005309,0.109504,-0.255234,0.301577,0.224174,0.028134,0.365155,-0.458670,-0.072676,0.433673,-0.021101,-0.528023,0.250369,0.101365,-0.123330,-0.431612,0.150511,-0.141119,0.424182,0.588320,0.439341,0.416418,-0.167679,-0.432021,-0.330924,-0.062382', '1296909', '1293936', '1466273', '10807909');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1916995', '玩叛游戏', '剧情', '墨守成规的会计师乔纳森（伊万·麦克格雷格 Ewan McGregor 饰）意外结识风度翩翩的律师怀亚特（休·杰克曼 Hugh Jackman 饰），怀亚特的热情与幽默让这位极度压抑自我的会计师看到了这个世界金融中心繁华背后的奢靡。怀亚特与乔纳森无所不谈，他告之乔纳森存在一个神秘的性爱俱乐部，那里有无数希望和男人发生一夜情的美女，乔纳森对此表现出憧憬。怀亚特出差前与乔纳森拿错电话，乔纳森意外接到来自性爱俱乐部的电话邀请，考虑再三之后乔纳森最终走入了那片欲望之地，并且在一次约会中偶遇自己在地铁中曾经遭遇的心仪女子“S”。正当乔纳森完全沉浸在幸福之时，意外发生了。自己在旅馆房间被打晕，“S”遭遇绑架，怀亚特神秘失踪，一下子仿佛他这段曾经的经历只发生在自己的妄想之中……©豆瓣', '伊万·麦克格雷格', 'Marcel Langenegger', 6.4, 8757, 'tt0800240', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p901846772.jpg', 1.1, 11.1, 57.4, 25.3, 5.1, '0.317836,0.278728,-0.939948,0.454990,-0.080135,-0.109355,0.878126,-0.081299,-0.491994,-0.593028,0.044458,0.962632,-0.586739,0.447025,0.743019,0.019427,-0.185976,-0.801777,0.050544,-0.126914,-0.070082,-0.668013,-0.340898,-0.004363,-0.010227,-0.233357,0.319341,0.139716,-0.250169,0.624533,0.182092,0.590794,-0.286358,0.756237,-0.091348,0.090679,0.580007,0.266031,-0.458271,0.009335,0.125967,-0.258577,0.028273,0.174794,0.128139,0.224718,0.547847,-0.223789,-0.413191,-0.001192,0.351971,0.026911,0.032649,0.014208,0.167141,-0.021999,0.205073,0.201629,-0.133277,-0.053287,0.221782,-0.089635,-0.575468,0.113437,-0.143940,0.220577,-0.181073,0.311895,-0.092225,0.050903,0.255932,-0.122593,0.447082,0.355545,0.395692,0.229508,0.025351,0.097604,-0.305848,-0.035200,0.711050,0.039778,-0.239952,0.387164,-0.294763,-0.269084,0.150305,0.090723,-0.631471,0.212116,0.360528,0.120663,-0.265611,0.360579,-0.443255,-0.121515,-0.173683,0.003495,-0.030797,-0.345507,-0.336129,-0.744525,-0.301471,-0.296239,-0.346044,-0.123367,-0.142055,-0.105050,0.178385,-0.838922,0.321318,0.336023,0.253798,-0.365080,0.717326,0.138379,0.155515,-0.117058,0.009356,0.385695,0.131981,0.196815,-0.145150,0.277920,-0.108577,-0.072823,-0.537133,0.319137', '1296534', '26687241', '1300958', '2230893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917074', '阿童木', '动作', '在未来世界，由于痛失爱子，天才科学家天马博士（尼古拉斯·凯奇 Nicolas Cage 配音）创造出了机械人阿童木（弗莱迪·海默 Freddie Highmore 配音），想以此来作为儿子的替身，寻找安慰。虽然，阿童木拥有博士儿子的情感和记忆，而且先进的程序还在不断完善其情绪，并让他富有同情心。可是，博士始终无法接受失子之痛，对阿童木也不能正确对待，并认为他不是人类而将其抛弃。阿童木沦落为无家可归的流浪儿，而且还备受军方的四处通缉，并最终被抓住。军方要求天马博士拿掉阿童木的能源，让它变成军方机器人的能源配备。在最后时刻，天马博士突然醒悟，并协助阿童木逃走。面对军方的围追堵截，阿童木奋起反抗，最终一场惊世大战一触即发。在不断的旅行过程中，阿童木也逐渐成长，他也接受了自己这机械与人类结合的设计，并肩负起全人类生死存亡的重任。©豆瓣', '弗莱迪·海默', '大卫·博维斯', 6.9, 48096, 'tt0375568', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1822907716.jpg', 1.2, 7.2, 48.4, 32.9, 10.3, '-0.178763,0.253120,-0.566839,0.433105,-0.047093,-0.252367,0.607203,-0.081793,-0.514323,-0.408356,0.197857,0.731807,0.236002,0.066219,0.043866,-0.074003,-0.376513,-0.434916,0.077739,0.353348,-0.160394,-0.475639,-0.228854,-0.300715,-0.111947,-0.543634,1.028964,-0.148899,-0.372488,0.291794,0.154525,0.214105,-0.013454,0.539084,-0.030499,-0.164304,0.008960,-0.059839,-0.312830,0.201630,0.041236,-0.170298,0.200574,0.351775,-0.247260,0.120038,0.608644,-0.574856,0.035136,-0.239983,0.252020,-0.577113,-0.118920,-0.041144,0.100300,0.041119,-0.297103,0.321669,0.029041,0.252287,0.184460,-0.048801,-1.156263,-0.251100,0.101938,0.058118,-0.455702,0.358965,-0.059526,0.044932,0.038572,-0.261516,0.036171,0.150302,0.491813,0.494465,-0.559557,0.151082,-0.293927,0.159077,0.449489,-0.225244,-0.390300,0.307819,-0.230142,-0.594215,-0.041721,-0.576354,-0.447680,0.007122,-0.012653,0.429064,-0.344291,0.377601,-0.510462,0.089264,-0.439167,-0.272223,0.019556,-0.534774,0.248772,-0.490211,-0.040974,-0.137639,-0.262024,-0.201548,0.220255,-0.490311,0.714500,-0.846874,0.007082,0.675269,0.384724,-0.528973,0.355296,0.141992,-0.037812,-0.343583,-0.256474,0.436201,0.037560,0.497435,-0.021222,0.009412,0.220988,-0.123039,-0.128987,0.468234', '26759819', '1793491', '26759820', '27073234');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917086', '不可告人', '剧情', '儿科医生贝克（弗朗索瓦•克吕泽 饰）与妻子玛格特（乔瑟•克罗泽 饰）在初次亲吻的老地方旧日重温时，妻子被人带走。几天后，人们寻获了她的尸体，警方判定玛格特被一名变态的连环杀手杀害。从此，贝克陷入了痛苦的思念和懊悔。八年后，一封神秘的地暖在邮件发送到贝克的邮箱，一份视频令他无比震撼——玛格特出现了，并约她到公园。与此同时，两具尸体使警察重新调查玛格特的案件。律师通知贝克他遭到逮捕。贝克决定去公园一探究竟，就此一个潘多拉的盒子被打开。©豆瓣', '弗朗索瓦·克鲁塞', '吉约姆·卡内', 7.1, 5618, 'tt0362225', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p753947235.jpg', 0.8, 5.8, 40.9, 42.3, 10.2, '0.490264,-0.135380,-0.313824,0.362817,0.097767,-0.363925,0.677644,0.381910,-0.662236,-0.065010,0.207793,0.714815,-0.418887,0.202952,0.420622,0.018129,-0.521764,-0.778203,-0.069898,-0.637303,-0.441809,-0.417474,-0.193422,-0.276701,0.551896,-0.599320,0.396528,-0.187693,0.156664,0.390241,0.004362,0.663231,-0.336120,0.558182,-0.043654,0.209245,0.409278,-0.298466,-0.102648,0.254573,0.046300,-0.421738,0.030204,0.067133,-0.174199,0.264902,0.831307,-0.082882,-0.267551,-0.136410,0.322704,0.011417,-0.018186,0.116433,0.212854,-0.106474,-0.154949,0.286714,-0.530930,-0.287617,0.247161,0.037327,-0.561622,-0.094493,-0.190201,0.328428,-0.734005,0.215353,-0.510611,0.518046,0.111102,-0.345429,0.206616,0.287656,-0.082052,0.317020,0.189473,-0.249723,-0.292960,0.229064,0.358996,-0.175341,0.065470,0.034420,-0.021562,-0.273605,-0.080255,0.333289,-0.404412,0.066018,0.818846,-0.032536,-0.176043,-0.023546,-0.801143,-0.619501,-0.681430,-0.284049,-0.144020,-0.350070,-0.342249,-0.835897,-0.176721,0.323870,-0.226834,-0.176836,0.134153,0.017772,0.291538,-0.594015,0.533876,0.682577,-0.095466,-0.255476,0.454643,-0.008581,-0.076454,-0.238778,-0.022151,0.396554,0.697376,0.538925,0.274046,0.198857,-0.084503,-0.030608,-0.559516,0.378588', '1309194', '1297659', '3735015', '1295547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917160', '樱桃小丸子 真人版1', '喜剧', '力求还原漫画中小丸子一家的真人版上演了！三年级小学生小丸子（森永迫依 饰）的家有姐姐、爸爸妈妈和爷爷奶奶。六口人的樱桃家并不富裕，但每天都朝气蓬勃着。小丸子如同生活中大部分的小女孩。有很多奇思妙想，喜欢好吃的食物，可爱的物件，不爱打扫卫生，爱赖床，作业永远在开学前一刻才做完。总之，糗事一箩筐。小丸子的班上有各式各样的同学。好朋友小玉，富二代花轮，精力爆棚的班长丸尾，阴险的藤木，还有帅哥二人组杉山和大野。每天的生活不咸不淡，偶尔有些小幸运，譬如被邀请去花轮家大吃大喝；偶尔也有些小不幸，譬如被锁在了厕所里，害怕就这样死去。在或幸运或不幸里，小丸子体验到很多“人生”的真理，在这之中，一点点成长。©豆瓣', '森迫永依', '西浦正记', 8.4, 9751, 'tt0882758', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2509125890.jpg', 0.5, 1.7, 16.2, 38.4, 43.2, '0.349509,-0.294224,-0.491664,0.156840,-0.262363,-0.108445,0.606268,0.262899,-0.374032,-0.048965,-0.190808,0.671114,-0.171790,0.648055,0.000947,-0.103161,-0.216591,-0.359915,0.021307,-0.132979,-0.260498,-0.184117,0.029546,-0.158376,-0.168501,-0.173586,0.230198,-0.018349,0.170752,0.393686,0.129985,-0.125762,0.054055,0.313981,-0.313883,0.181140,-0.028736,0.309949,0.187083,0.002370,0.012131,-0.014919,-0.089934,-0.012041,0.523501,0.077891,0.696521,-0.278615,-0.367840,0.012085,0.336022,-0.047031,-0.250630,0.342098,0.325479,0.142107,0.424859,-0.256315,-0.053312,0.249564,0.088285,-0.113788,-0.666599,-0.334142,0.184962,0.003355,-0.503154,0.652840,0.265101,-0.111314,0.472028,-0.321831,0.397763,0.040398,0.220450,0.563727,-0.069267,0.126615,-0.506363,0.350691,0.602756,0.154582,-0.151618,0.366547,-0.307040,-0.044248,0.109177,-0.295416,-0.439726,0.234516,-0.004527,-0.082843,-0.350318,0.235791,-0.692251,0.457762,0.319859,-0.118751,0.021601,-0.344132,-0.417068,-0.494780,0.353012,-0.529885,-0.244805,0.149803,0.116383,-0.342854,1.147800,-0.845035,0.237839,0.452307,0.295727,-0.190904,0.709391,0.084398,-0.076325,-0.072615,-0.120981,-0.014318,0.010043,0.046420,0.163468,0.553918,-0.013422,-0.244095,-0.462533,0.474554', '24284209', '27602116', '4181031', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917171', '硫磺岛的来信', '剧情', '中途岛战役失利直接宣布了日军在太平洋战场上的失败，负隅顽抗的日军依然坚守日本最南端的小岛—硫磺岛。这个看似不起眼的小岛，却上演了二战太平洋上最惨烈的战争。栗林忠道中将（渡边谦 饰）是日军在硫磺岛的指挥官，负责这道日军最后的防线。栗林中将大力改革日军内部的陋习和不足，并设计出一整套对付美军、以拖延为主的作战方案。虽然他和日军的二万名官兵都上下齐心，但面对占尽空中优势的四万名美军士兵，栗林知道这将是一场没有归路的战争。在最后的战争之前，栗林写下了他最后的家书……©豆瓣', '渡边谦', '克林特·伊斯特伍德', 8.2, 64525, 'tt0498380', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p973154238.jpg', 0.6, 1.3, 16.4, 51.4, 30.3, '0.256914,0.091314,-0.935670,0.893242,0.337665,-0.031920,0.636886,-0.260302,-0.234829,0.204069,0.487892,0.562718,0.278754,-0.309122,-0.045499,-0.184562,-0.303828,-0.893081,-0.312315,-0.037868,-0.415113,-0.569261,-0.524919,-0.027255,-0.104607,0.141647,1.121159,0.652062,-0.362879,0.266453,0.203474,0.175816,0.427816,0.796592,-0.030425,0.086115,-0.287363,-0.608073,-0.099384,0.024824,-0.186043,-0.517721,-0.210883,0.417572,0.101513,0.689705,1.001951,-0.387705,0.209158,0.041910,0.084554,-0.525944,0.030491,0.233974,0.587262,-0.040698,-0.204143,0.040078,-0.046717,-0.123589,-0.151008,-0.002289,-0.673050,-0.136983,-0.179351,0.094363,-0.294902,0.855714,-0.242440,0.314134,0.102415,-0.044327,0.092038,0.829605,0.207041,0.008767,-0.478321,0.019968,-0.535611,0.065714,0.416574,-0.081810,-0.152801,-0.038611,-0.222571,-0.398491,0.017396,-0.787565,0.071341,-0.065168,0.130439,-0.240994,0.023907,-0.002848,-0.846753,0.264120,-0.312333,-0.587870,-0.187872,-0.221940,-0.408873,-0.782022,0.074935,-0.656606,-0.619232,0.405372,-0.071261,0.318934,0.743643,-0.651509,-0.320894,0.617404,0.317133,-0.099557,0.512926,0.557499,0.149133,0.100819,0.104523,0.252907,-0.309525,0.641089,0.308930,0.499377,0.000504,-0.266075,-0.404764,0.591658', '10467125', '1381964', '35058077', '26356488');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917313', '天行者', '剧情', '影片的大部分时间，都有三方势力的互消互长，拉扯抗衡。一方是叶秋（郑伊健饰）。他曾经是江湖中的猛兽，然而8年狱中生活后，如今的他却只想办正道企业，振雄图大志，洗清背景。但似乎他的决心并不为人所理解。另一方是鬼仔（冯德伦饰）。他就像叶秋的过去一样，享受着叱咤江湖的威风而忘记回头，并视叶秋为威胁。而宋国明警官（方中信饰），则时刻都在等待一个时机，将两方一同擒下。鬼仔以叶秋心爱的盲女（霍思燕饰）为诱饵，迫使他进行一桩交易。宋国明闻风亦开始蠢蠢欲动。但是，正是在这场战斗中，宋国明得以慢慢意识到叶秋的苦心，而叶秋，也令鬼仔对自己的黑道生活有了新的顿悟。©豆瓣', '郑伊健', '阮世生', 6.3, 10324, 'tt0891603', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2370421200.jpg', 2.7, 12.7, 56.8, 21.1, 6.7, '0.097910,0.145428,-0.609000,0.482265,0.025914,-0.069014,0.513964,0.174887,-0.505950,-0.134551,0.296801,0.345301,0.136093,0.077727,-0.042795,0.088105,-0.004148,-0.933692,0.017257,-0.034967,-0.014603,-0.114491,-0.401920,-0.124486,-0.252430,-0.129730,0.644089,0.126911,-0.109049,0.316612,0.343466,0.117941,0.055780,0.734538,-0.003588,-0.160818,-0.061424,0.085926,-0.310947,-0.075632,-0.065125,-0.382041,-0.411802,0.412534,-0.101225,0.384162,0.459638,-0.351561,-0.152583,-0.032111,0.153471,-0.350139,-0.028909,0.138888,0.310927,-0.012482,0.140737,0.215800,-0.065352,0.148062,0.036451,0.214840,-0.839495,0.035102,0.108582,0.217670,-0.534100,0.476888,0.014177,-0.107629,0.037243,-0.200433,0.133675,0.363281,0.393273,0.121930,-0.190363,-0.180903,-0.489012,0.321141,0.730630,0.008520,-0.081476,0.380136,-0.078036,-0.455813,-0.182331,-0.173600,-0.231616,-0.312015,0.077431,0.071602,-0.312045,0.302488,-0.447391,0.151301,-0.153978,0.101219,-0.125695,-0.522333,0.086500,-0.502008,-0.336962,-0.430564,-0.166450,0.002870,0.277688,-0.457006,0.708594,-0.685661,0.006039,0.629666,-0.005257,-0.624880,0.624987,0.059021,0.129995,-0.179789,-0.142230,0.057071,0.081190,0.181346,0.189310,0.206705,-0.085818,-0.121011,-0.032827,0.450087', '4301278', '25917239', '30163500', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917323', '男国少年梦', '剧情', '相貌英俊的X（Derek Magyar 饰）是一个应召男孩，他向中老年同好者提供服务，赚取费用，过着悠闲自在的生活。他喜欢用性来换钱，在这一过程中，只有年届八十的乔治（Patrick Bauchau 饰）不曾与他发生关系，只当他是倾诉的对象。乔伊（Jonathon Trent 饰）与安德鲁（Darryl Stephens 饰）同住一间公寓，三人都有着相同的兴取向，在合住的一年里三人互有好感，偶有肉体接触。黑人小伙安德鲁欣赏X，但却不认同他出卖肉体的方式。始终为X守身如玉的安德鲁最终无法忍受，上演了一出示威性的一夜情，这让对凡事都毫不在乎的X心里不是滋味……本片荣获2006年费城国际同性恋电影节评委会奖最佳影片和最佳剧本奖、2006年罗德岛国际电影节金奖。©豆瓣', '德里克·迈戈雅', '亚伦·布洛卡', 7.3, 6067, 'tt0433350', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p906666951.jpg', 1.1, 5.6, 37.5, 40, 15.8, '-0.002185,-0.057425,-0.769637,0.699393,-0.165631,-0.074642,0.843426,-0.065430,-0.395729,-0.156128,0.001021,0.796475,-0.305025,0.095596,0.205804,-0.012832,-0.043217,-0.622654,-0.130458,-0.242208,-0.026620,-0.479523,-0.385710,-0.122780,-0.341815,-0.383857,0.412484,-0.214472,-0.174213,0.546069,0.682428,0.232000,0.182273,0.347646,-0.173198,-0.118434,0.171839,0.264555,-0.293896,0.234860,0.026586,-0.248273,-0.258867,0.151928,0.154382,0.463938,0.630703,-0.083057,-0.200779,0.137341,0.376512,-0.037766,-0.090879,0.052992,0.187318,0.055713,0.267704,0.251046,-0.081565,0.147472,0.203808,-0.043341,-0.778525,-0.022275,0.159693,0.164445,-0.590825,0.767974,-0.150929,-0.116526,-0.274895,-0.156253,0.245295,0.049113,0.343799,0.316280,-0.071332,0.111531,-0.543295,0.415791,0.798439,0.348157,-0.303568,0.433906,-0.697260,-0.553580,-0.129700,-0.328130,-0.470569,-0.088338,-0.007077,0.076584,0.012070,-0.065884,-0.438779,0.131819,0.141700,-0.181069,0.113039,-0.423987,0.060094,-0.603476,-0.188924,-0.776473,-0.457187,-0.042528,0.097181,-0.488097,0.684764,-0.807751,-0.067367,0.520625,0.440877,-0.509608,1.192942,0.354906,0.002309,-0.024542,-0.286153,0.081323,-0.181746,-0.126863,-0.038696,0.390585,0.158769,-0.279257,-0.295835,0.549035', '3055049', '1456503', '30162520', '3033092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1917577', '明明', '动作', '明明（周迅饰）是一个浪迹江湖的侠女，与阿D（吴彦祖饰）一见钟情。为了阿D口中的“有了五百万，就去哈尔滨一起生活”的诺言，冒险去抢黑社会头目猫哥（张信哲饰）的钱。其实，阿D还有另外一个女友，名叫娜娜（周迅饰），拥有和明明一样的容貌，就连爱慕明明的青年阿土（杨佑宁饰）都将她们认错。究竟哈尔滨埋藏着怎样的秘密，值得阿D一直追寻？明明从猫哥那里抢来的盒子，究竟又承载着怎样的秘密？明明和娜娜的爱情，又将走向何处呢？©豆瓣', '周迅', '区雪儿', 4.9, 23444, 'tt0885505', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2456330706.jpg', 18.8, 31.8, 36.4, 9.5, 3.5, '0.224907,-0.138740,-0.429493,0.728360,-0.223157,-0.547249,0.609648,-0.150352,0.185252,-0.401084,-0.135817,0.313195,0.228881,0.234320,-0.140724,0.193522,-0.104595,-0.464547,-0.375440,-0.342618,-0.315769,-0.481522,-0.320366,0.206983,0.180099,0.306467,0.343284,-0.122669,-0.105193,0.158171,0.964316,0.284308,-0.348278,0.413958,-0.115718,-0.018037,0.145125,0.524531,-0.124278,0.088071,0.361030,-0.209641,0.207907,0.034660,0.031725,-0.038137,0.731395,-0.528760,0.149199,0.021617,0.210499,0.118927,0.118845,-0.091092,0.052448,-0.115871,-0.079898,-0.093830,0.022045,-0.069347,0.497750,-0.108958,-0.472763,-0.237242,0.538743,0.093052,-0.738591,0.043934,-0.031898,0.076547,0.370881,-0.274173,0.327193,0.406713,0.379188,0.480177,-0.011822,0.007659,-0.879512,0.208849,0.666463,0.082261,0.275396,-0.069925,-0.160034,-0.711515,-0.061489,0.148635,-0.619516,0.076523,-0.032653,-0.277886,-0.030132,0.034683,-0.571564,0.180680,0.222720,0.390799,0.120549,-0.688212,0.101589,-0.047615,-0.032134,-0.434871,0.076091,0.018220,0.132073,-0.255067,0.758148,-0.487919,0.347109,0.572701,0.421992,-0.458637,0.800325,0.227358,-0.257580,-0.540980,-0.222432,0.296911,0.464677,0.095531,0.239246,0.178444,0.049607,0.102720,-0.183297,0.501082', '1304309', '1316525', '1305713', '35505100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1918027', '太阳之歌', '剧情', '居住在海滨小镇的16岁女孩雨音薰（YUI 饰）青春美丽，然而正值花季的她却无法像同龄人一般在洒满阳光的海滩边自由玩耍与奔跑。原来薰罹患一种罕见的疾病——XP色素性干皮症，她的皮肤不能接受阳光照射，否则将出现生命危险。从此白天与之无缘，薰只能终日躲在家中，唯一的乐趣也只是趁着夜晚踱到车站广场唱着自己喜爱的歌。在这一过程中，薰渐渐喜欢上时常路过车站的冲浪男孩藤代孝治（塚本高史 饰）。某天，她带着胆子追上去，对孝治表白。温柔的海风，吹拂着他们慢慢升温的恋情。可是，薰就像童话中的灰姑娘，无论怎样眷恋都必须在日出前赶回家中。对于生命之火渐渐微弱的她来说，无论爱情还是音乐，都已成为无比奢侈的东西了……©豆瓣', '吉冈唯', '小泉德宏', 7.7, 11002, 'tt0844347', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p805944220.jpg', 0.4, 2.9, 28.7, 45.1, 22.8, '0.196807,0.377327,-0.947578,0.589061,-0.152079,0.041472,0.790996,0.519875,-0.278598,0.151814,0.341574,0.472529,-0.106698,0.369817,0.380517,0.050728,-0.351436,-0.710585,-0.009495,-0.314795,-0.341954,-0.283141,-0.111358,0.203068,-0.181049,-0.292459,0.578240,0.192353,0.087379,0.622933,0.128011,-0.052447,-0.294425,0.632613,-0.431289,-0.441892,-0.043661,0.231267,-0.132578,0.197441,0.031287,-0.388738,-0.250863,0.079136,-0.219362,0.166247,0.868363,-0.548984,-0.193090,0.050210,0.241082,-0.187833,-0.039551,0.066472,0.220654,-0.094277,0.260777,0.043883,-0.101087,0.116491,-0.135073,0.018784,-0.358350,0.301703,0.168627,0.328817,-0.458446,0.429949,0.285282,-0.106563,0.207357,-0.435296,0.189863,-0.148835,-0.184692,0.691919,-0.322645,0.212310,-0.607496,0.162271,0.610881,0.110685,-0.538792,0.682102,-0.622231,0.006001,0.043507,-0.048369,-0.888022,-0.262304,0.081230,0.097683,-0.375672,0.143274,-0.668802,0.453973,0.058750,-0.325522,-0.000727,-0.039670,-0.158911,-0.405358,-0.123334,-0.560920,-0.334836,0.261335,0.051034,-0.274674,0.761861,-0.707518,0.456410,0.658024,0.213512,-0.058862,0.647721,0.003377,0.006678,0.272362,-0.272201,0.686246,-0.345631,0.385482,0.043108,0.514518,-0.198059,0.311805,-0.605251,0.705385', '5977789', '3097044', '3534824', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1918208', '割腕者的天堂', '剧情', '故事设定在一个死后的奇异时空，所有自杀后的人都会被聚集到这里。在这个异次元的世界里，除了每个人都拥有神奇力量外，一切看似跟现实世界毫无分别。男主人公齐亚（派屈克·福吉特 Patrick Fugit饰）为情割腕自杀后，本以为能就此一了百了，却阴差阳错的坠入这个自杀者的天堂。在路上，齐亚先后遇见了因各种原因自杀的路人，后与另外两位自杀者结伴同行，一起踏上了神奇旅程。©豆瓣', '派屈克·福吉特', '葛兰·杜奇克', 7.6, 13671, 'tt0477139', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p504615714.jpg', 0.6, 3.7, 30.8, 45.7, 19.2, '0.158367,0.156494,-0.931694,0.413832,-0.193884,-0.159775,0.828458,-0.013249,-0.643370,-0.147712,-0.000741,0.960135,-0.204911,0.157840,0.428551,-0.174869,-0.488058,-0.517574,-0.210541,-0.420873,-0.850855,-0.241416,-0.217928,-0.220248,-0.232954,-0.356949,0.495455,0.360816,-0.069722,0.336248,0.103773,0.434524,-0.664961,0.419065,-0.350329,0.310581,0.229268,0.148695,-0.192337,0.353834,-0.284206,0.088253,0.081832,0.140804,-0.418745,0.083316,0.727968,-0.525558,-0.044602,-0.142816,0.239944,-0.183577,-0.283981,0.042857,0.182153,-0.242640,0.305910,0.221881,-0.228436,0.025668,0.307874,-0.004811,-0.901797,-0.167534,0.048378,0.115363,-0.340662,0.278806,0.337774,-0.243641,0.021986,-0.195068,0.393768,0.261962,0.532425,0.201271,-0.002232,-0.316786,-0.394171,0.081432,0.904655,0.000454,-0.462338,0.400728,-0.098192,-0.284699,-0.222310,-0.004791,-0.385994,0.260004,0.334252,0.359099,-0.339471,0.255635,-0.698108,0.185367,-0.044422,0.115691,-0.143360,-0.403667,-0.340905,-0.463302,0.067958,-0.089750,-0.258831,0.277437,0.095491,-0.030018,0.672811,-0.633552,0.482557,0.563924,0.183936,-0.655350,0.871680,-0.022343,0.250057,0.001548,0.079664,0.140668,0.145583,0.586206,-0.061215,0.445027,-0.209871,0.188754,-0.733576,0.585412', '26715845', '3055049', '30162520', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1918224', '曼谷杀手', '动作', '捷克布拉格，职业杀手乔（Nicolas Cage 饰）完成了一次任务，手法老道。长久以来，乔信奉的四个原则让他冷酷无情的完成一次次任务并活在所有人的视线之外，但这种漂泊无定的孤寂人生教人厌倦，乔决定前往曼谷，在那里完成最后四次任务。乔在曼谷灯火缭乱的街头物色到一位当地扒手康担任自己的助手兼翻译，负责与泰国雇主接头。乔很快完成了第一次任务，付出了右臂擦伤的代价，到药房寻求帮助的乔遇见聋哑姑娘Fon（杨采妮 饰），后者温柔的态度让乔的心中萌发了牵挂……康在接头的途中被一群流氓殴打，满身伤痕的康打动了乔，乔传授他战斗的技巧，自己冷酷的原则也开始发生动摇。乔的最后一次任务是刺杀一位敢作敢为的正派政治家，康的话犹在耳边让他迟迟不能动手。另一方面，泰国雇主恐怕事情败露而欲杀人灭口。乔与黑帮雇主的战斗不可避免……©豆瓣', '尼古拉斯·凯奇', '彭发', 5.9, 27011, 'tt0814022', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p725849628.jpg', 3.9, 21.5, 53.7, 16.6, 4.2, '0.021603,0.173749,-0.568138,0.937178,-0.327535,-0.188813,0.388831,-0.110546,-0.157679,-0.663722,-0.115424,0.755460,-0.044827,0.483029,0.308965,-0.352055,0.066222,-0.750552,-0.068885,0.038807,-0.654583,-0.568323,0.364663,-0.745331,-0.092632,0.073321,0.484297,0.774160,-0.282363,0.304956,0.478806,0.280275,-0.032395,0.473452,-0.105844,-0.276702,0.290097,-0.141486,0.059788,0.018423,0.492880,-0.408817,-0.123840,0.600623,0.127364,0.606155,0.644613,-0.085587,-0.289842,0.074596,0.356802,-0.521876,0.391911,-0.158842,0.225205,-0.072052,-0.135993,-0.008866,-0.048444,0.059719,0.180147,-0.218132,-0.783064,-0.234580,-0.002602,-0.290839,-0.700500,0.221543,-0.024571,0.565476,-0.259614,-0.146602,0.363918,0.403661,0.420047,0.112930,-0.136582,0.051724,-0.494385,0.396593,0.785868,0.049948,-0.194987,0.196827,-0.325362,-0.709515,0.088989,-0.486465,-0.078706,0.111270,0.450205,-0.128835,-0.054333,-0.065683,-0.221594,-0.353493,-0.136411,0.197306,-0.298158,-0.272711,0.029070,-0.652278,-0.244085,-0.280209,-0.133795,0.379840,-0.248006,-0.509938,0.519220,-0.672962,-0.022428,0.390495,-0.077869,-0.831921,0.561405,0.106625,0.302794,-0.235876,0.282131,0.339530,0.288948,0.003711,0.514800,0.147654,-0.173672,0.126631,-0.021361,0.382703', '3670447', '4301278', '3785918', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1918648', '蒙古王', '剧情', '少年铁木真随父亲——乞颜部落首领也速该（Ba Sen 饰）远行，为了平复与仇敌蔑儿乞人之间的恩怨，也速该希望儿子选择蔑儿乞人的女儿为妻，而铁木真却选择了弘吉剌部落首领的女儿孛儿帖，并承诺五年后前来迎娶。归途中，也速该死于敌人塔塔儿人的毒酒，部落的牛马和牧民也被叛徒虏去。铁木真从少年时起便经历了人生困苦，他一面和母亲四处漂泊，一面躲避着仇家的追杀。长大成人的铁木真（浅野忠信 饰）依然生活在刀光剑影之中，纵然朝不保夕，他仍记得与孛儿帖的约定，终于将孛儿帖（Khulan Chuluun 饰）迎娶回家，生活开始出现转机。然一场灾难尾随而至，蔑儿乞人为报当年仇恨，射伤铁木真，虏去孛儿帖。伤愈的铁木真只得求助好友札木合（孙红雷 饰）……本片荣获包括2008年亚洲电影节最佳配角奖（孙红雷）、2007年俄罗斯金鹰电影节最佳服装设计和最佳音效在内等国际电影节11个奖项。', '浅野忠信', '谢尔盖·波德罗夫', 6.8, 11855, 'tt0416044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1325530086.jpg', 2.2, 9.7, 45.8, 30.8, 11.6, '-0.312348,-0.036566,-0.489758,0.625478,0.239161,-0.259191,0.383977,0.033695,-0.616367,-0.118327,0.165826,0.737377,0.004677,0.122550,0.483193,-0.056544,-0.288339,-0.856764,-0.182936,-0.311526,0.086842,-0.103707,0.101244,0.002943,-0.274958,-0.367154,0.757247,-0.098956,0.149694,0.752489,0.510332,0.038444,-0.388485,0.315613,0.051031,0.142195,-0.400935,0.022852,-0.485511,0.126434,-0.096954,-0.308265,-0.292677,-0.163475,0.035643,0.226899,0.927653,-0.568678,0.324957,-0.447431,0.006558,-0.223088,0.113714,0.123758,0.364021,-0.150017,0.333666,0.477573,0.051655,-0.175139,-0.309736,0.110455,-0.312459,0.206195,0.229800,-0.028008,-0.726542,0.664329,-0.213089,0.046124,0.076311,-0.287773,0.137127,0.521805,0.227715,0.198294,-0.223183,0.028220,-0.289647,0.253608,0.584322,-0.147417,0.134155,-0.271982,0.050854,-0.563520,0.131223,-0.075479,-0.390286,0.241728,0.467711,0.003003,-0.216346,0.353178,-0.332173,-0.208396,-0.268617,0.096849,0.404035,-0.320416,0.012321,-0.453968,0.118087,-0.126111,-0.270447,0.055487,0.358699,0.103438,0.382980,-0.401134,0.130570,0.338923,0.438777,-0.427482,0.568725,0.010639,0.085444,-0.248657,-0.153104,0.520441,0.037557,0.089352,0.058610,-0.084812,-0.188293,-0.105295,-0.182307,0.310205', '1780122', '4202326', '1303390', '3078390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1919245', '鬼妈妈', '动画', '你相信在你们家某个角落里有一条通往另一样世界的通道吗？可千万别爬进去。小女孩卡洛琳搬进新居后，破旧而又死气沉沉的环境让她感觉无聊透顶。无趣古板的父母，怪异的邻居，还有一个讨厌的小男孩和他的小黑猫，这样的生活对于满脑子都是奇思妙想的她来说，简直要了命。不过事情并不是一直都那么糟，一个夜晚，她居然在家里的第13个门后面，发现一条秘密通道，喜欢刺激冒险的卡洛琳当然不会放弃一探究竟的机会，于是她顺着那条通道慢慢的爬了过去。卡洛琳发现通道另一边是一个和现实完全相同但又不同的世界，一切现在都似乎在这里得到了复制，但是自己那些梦想却又在这里得到了实现。而最让卡洛琳高兴的是，这个世界里的妈妈对自己和善可亲、百依百顺。可是后来，她发现了这位“鬼妈妈”准备给自己换上纽扣眼睛，并把自己永远留在这个“奇妙”的世界。卡洛琳发现自己大祸临头了，她必须想办法逃出“鬼妈妈”的魔掌。', '达科塔·范宁', '亨利·塞利克', 8.3, 179449, 'tt0327597', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1731353563.jpg', 0.1, 0.8, 16.2, 48.8, 34.1, '0.352055,0.150139,-0.730272,0.542405,-0.502210,-0.232112,0.871973,-0.088958,-0.597740,-0.095814,-0.040551,0.730100,0.138995,0.303598,-0.118823,0.437537,-0.224488,-0.450571,0.123498,-0.471731,-0.592778,-0.360718,-0.287041,-0.225236,0.079912,-0.219939,0.542961,0.242442,-0.100426,0.130786,0.335920,-0.019328,0.025780,0.830336,-0.359108,-0.075870,-0.065172,0.220872,0.140563,0.036172,0.007658,0.093542,-0.117584,0.624572,-0.139105,0.283268,0.411008,-0.391420,-0.463719,0.180363,0.343103,-0.223871,-0.251184,0.036212,0.222515,-0.286270,0.168082,-0.005536,-0.045903,0.059963,0.151338,0.056628,-0.761726,-0.014007,-0.028549,0.142764,-0.595224,0.114144,0.202924,-0.263431,0.076921,-0.484006,0.445436,0.241525,0.488249,0.357314,-0.508253,0.002318,-0.641657,-0.170155,0.656456,-0.106065,-0.158133,0.708696,-0.264963,-0.269749,0.024281,-0.049673,-0.424347,0.088525,0.076314,0.071216,-0.607000,-0.096398,-0.536405,0.279376,-0.065403,-0.117142,-0.116098,-0.669597,-0.130911,0.027250,-0.040206,-0.220879,-0.218442,0.151603,-0.235707,-0.382131,0.577000,-0.571447,0.237627,0.745134,0.310808,-0.727477,0.974013,0.190909,0.003941,-0.298774,-0.003632,0.213789,0.001552,0.570694,0.032700,0.485006,0.026293,-0.166355,-0.656472,0.704612', '35069014', '2671