INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1919906', '即使这样也不是我做的', '剧情', '青年金子彻平（加濑亮饰）在高峰期乘上了地铁，赶往学长介绍的公司面试。不料，他在岸川站下车时，被一个女中学生拉住并被指认为是“痴汉”，彻平因此遭到了逮捕。在警察的严厉质问下，彻平坚称自己没有犯罪。而律师告诉彻平，如果否认犯罪将遭到拘留，一旦被起诉，后果将更加严重。这飞来横祸令彻平茫然失措，与此同时，彻平的母亲丰子（罇真佐子饰）和朋友齐藤达雄（山本耕史饰）为了还彻平清白， 四处奔走寻求帮助。当过法官的资深律师荒川正义（役所广司饰）和年轻的女律师须藤莉子（濑户朝香饰）向他们伸出了援手，一场决定命运的法庭辩论随即展开。©豆瓣', '加濑亮', '周防正行', 8.3, 9812, 'tt0794350', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p658414422.jpg', 0.3, 1, 13.6, 53.3, 31.8, '0.405490,-0.095183,-0.393014,0.245318,-0.238518,-0.277805,0.802012,0.371637,-0.149795,-0.010222,0.223145,0.718724,-0.174604,0.021481,0.552997,-0.083782,-0.106534,-0.669446,-0.057423,0.165448,-0.251364,-0.803681,0.248354,-0.082275,-0.116237,-0.254932,0.467020,-0.162261,-0.276405,0.501474,0.417509,0.522295,-0.046986,0.299674,-0.049339,0.027114,0.268283,-0.010268,-0.466409,0.452970,0.074215,-0.491811,-0.051836,0.461906,-0.179772,0.729609,0.349561,-0.096169,-0.391735,-0.101899,0.409012,-0.658613,0.116248,0.572752,0.482036,0.095544,-0.104697,0.403294,-0.415534,0.082616,0.164937,-0.066040,-0.681742,0.033910,0.033882,0.139910,-0.463825,0.324716,-0.203184,-0.060369,0.125627,-0.222237,0.229090,0.329932,0.249512,-0.020908,-0.292386,0.164468,-0.245998,0.142569,0.582876,0.175195,0.311685,0.224820,-0.069919,-0.415922,0.127057,-0.026553,-0.312356,-0.034071,0.186475,-0.156316,-0.173336,-0.188192,-0.297171,-0.342568,-0.281765,-0.130116,-0.177030,-0.415872,-0.207469,-0.341048,0.105523,0.091609,-0.274330,0.289498,0.119371,-0.087591,0.466438,-0.764712,-0.023658,0.557797,0.756253,-0.438198,0.419395,0.120555,-0.185522,-0.155234,0.051454,-0.033941,0.519628,0.722116,0.320879,0.068550,0.053595,-0.319878,0.039553,-0.032332', '1293145', '25862560', '26331839', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920620', '光荣的愤怒', '剧情', '云南黑井村，熊家四兄弟横行乡里，老大（李晓波饰）粗鲁地教训了来叫板的狗卵（蒲小虎饰）、老二（孔庆三饰）是村里的会计，为人狡诈。老三（王砚辉饰）是阴险的村长，手段狠毒。老四（朱义饰）是个不折不扣的流氓，喜欢玩弄妇女。村民们备受欺压，敢怒不敢言，新上任的村支书叶光荣（吴刚饰）也苦于抓不到证据，只得一忍再忍，等着找机会一网打尽熊家兄弟。终于，机会来了。熊家兄弟从外地绑架回来两名女子，被叶光荣盯上。他暗地发动群众，以“打倒四人帮，黑井村有希望”暗语，准备当天夜里去熊家抓现行，但没想到人算不如天算，兵分四路的抓捕行动意外频出，乱成一锅粥。就在叶光荣一帮人陷入绝境的时候，突然峰回路转，出乎意料的事情发生了。©豆瓣', '吴刚', '曹保平', 8.2, 29822, 'tt1982693', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p630606567.jpg', 0.2, 1, 16.2, 55, 27.7, '-0.132525,-0.396825,-0.295224,0.174027,-0.437624,-0.167108,0.264754,0.080013,-0.663241,-0.147298,0.054316,0.028446,0.032891,0.317211,0.393064,-0.183662,-0.007294,-0.531391,-0.058737,-0.093345,-0.107384,-0.198236,0.000041,-0.439502,0.094962,0.312123,-0.077869,0.211022,-0.259534,0.248040,0.473705,0.174164,-0.181903,0.322126,-0.347426,0.194175,0.144668,-0.250173,-0.103621,0.058024,-0.286276,-0.030199,-0.347312,0.073640,0.201929,0.566635,0.455159,0.005299,-0.253287,-0.185659,0.129055,-0.289321,-0.104720,0.263347,0.761443,-0.149172,0.225545,0.011728,0.137046,-0.320688,0.140865,-0.207157,-0.787323,0.415965,-0.035763,-0.212896,-0.710439,0.284856,0.122326,0.351012,-0.091206,-0.444042,0.289191,0.225617,0.289469,0.321633,0.045224,0.149909,-0.386392,0.046757,0.709802,-0.316298,0.153416,-0.139019,0.289041,-0.045939,0.467671,-0.488014,-0.162622,-0.184203,0.597457,-0.268467,-0.273798,0.142248,-0.219770,-0.294829,-0.220454,0.225637,0.133307,-0.341818,0.053661,-0.097439,0.059542,0.170460,-0.243018,0.593111,0.043122,0.008606,0.544230,-0.382589,0.045997,0.595127,0.080795,-0.717214,0.307536,0.224608,-0.176633,-0.155844,-0.170818,-0.546495,0.647543,0.415147,0.641616,0.273458,-0.232153,-0.517876,0.221541,-0.077595', '1302110', '1877596', '3811342', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920730', '淘金俏冤家', '喜剧', '本杰明·芬恩·费尼根（马修·麦康纳 Matthew McConaughey 饰）是一名疯狂的淘金猎人，淘金的热情使他无法如常人一般找份像样的工作养家糊口，他的妻子苔丝（凯特·哈德森 Kate Hudson 饰）也向他提出离婚，并在千万富翁奈杰尔（唐纳德·萨瑟兰 Donald Sutherland 饰）的巨轮上找了份不错的工作。一次意外的沉船事故中，芬恩无意中发现一枚碟子碎片，并推断这来源于一批失落了300多年的皇家财产，而这批财产同时也是他与妻子苦寻了8年的共同理想，芬恩决定这次决不放弃，然而周围却没有一个人相信他的推测。芬恩唯有想出了一个无厘头却不失精妙的方法登上了奈杰尔的船，并能言善辩地说服了杰奈尔与其女儿，甚至是苔丝也加入寻宝计划。然而与此同时，淘金团伙Bigg Bunny和芬恩的前导师已经盯上了他们，一场螳螂捕蝉黄雀在后的淘金好戏，即将上演……', '马修·麦康纳', 'Andy Tennant', 5.8, 4922, 'tt0770752', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p895388101.jpg', 4.5, 21.1, 57.2, 14, 3.3, '0.250135,-0.094467,-0.647608,0.613607,-0.301751,-0.507570,0.809967,-0.128828,-0.659287,-0.180292,0.127694,0.803803,0.040735,0.099136,0.213577,0.229168,-0.332624,-0.627214,-0.020582,-0.175628,-0.162106,-0.588604,-0.406086,-0.315099,-0.092007,-0.211707,0.473934,0.191265,-0.073635,0.540374,0.443192,0.210355,0.093329,0.589444,0.012906,0.011613,0.103398,0.048926,-0.158066,0.211376,0.012352,-0.294287,-0.288509,0.349473,0.099753,0.819683,0.552922,-0.144670,-0.023960,0.073894,0.151682,-0.295338,0.023906,0.116243,0.271458,-0.048919,-0.059015,0.214197,-0.128014,-0.202744,0.133077,-0.016167,-0.972307,-0.020932,-0.038555,0.217103,-0.565565,0.463209,-0.011724,0.093439,-0.289847,-0.279401,0.092623,0.169054,0.348967,0.142570,-0.193989,-0.078575,-0.511971,0.336305,0.623028,0.180632,-0.208754,0.448857,-0.232846,-0.503954,0.040542,-0.228543,-0.382108,-0.071677,0.429359,0.161325,-0.090338,0.082978,-0.490314,-0.003753,-0.486246,-0.187523,-0.078845,-0.400506,0.151371,-0.547250,0.052453,-0.168199,-0.497963,0.089729,0.016604,-0.231510,0.538445,-0.536264,0.055857,0.583936,0.133899,-0.348441,0.589348,-0.020183,0.093587,-0.210595,-0.032206,-0.009607,-0.011195,0.185414,0.252281,0.235883,0.240658,-0.405676,-0.280705,0.442561', '3119246', '1793491', '34890458', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920765', '侦探学园Q SP', '家庭', '由名侦探団守彦创立的全日本最优秀的侦探学校DDS最近要招收新成员了！引来了无数侦探迷们的积极参与，要想进入学园首先得经历考试，而这次考试则是解决一起疑案。喜欢推理的小Q（神木隆之介 饰）也参加了这次考试。在现场他结识了形形色色和他一样喜欢推理的人们，其中包括了拥有瞬间记忆能力的少女美南惠（志田未来 饰）、能力出色行动力强且颇神秘的天草流（山田凉介 饰）、电脑高手的鸣泽数码（松川尚瑠辉 饰）及一根筋的少年远山金太郎（要润 饰）。他们在这起案件中，通过合作最终解决了悬案，而这只是一切故事的开端……本剧改编自天树征丸的原作小说，由漫画家佐藤文也执笔。该SP是系列剧《侦探学园Q》的前篇。©豆瓣', '神木隆之介', '中岛悟', 7.8, 6212, 'tt0884210', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2501474425.jpg', 0.3, 2.1, 29.7, 45.1, 22.9, '0.132086,-0.093390,-0.212781,0.407670,0.210054,-0.179613,0.174841,-0.016011,-0.380801,-0.459020,0.024837,0.480626,-0.036261,0.222897,0.303649,-0.103474,-0.340335,-0.676108,-0.207562,-0.298914,-0.161163,-0.413956,-0.125471,-0.078931,-0.136527,-0.263977,0.812450,0.139309,-0.136539,0.339395,0.423455,0.309732,-0.037614,-0.188989,0.119140,-0.072982,0.180425,0.116522,-0.176377,0.191509,-0.014803,-0.178649,-0.138891,-0.029846,0.162320,0.202061,0.613578,-0.163399,-0.195674,-0.122486,0.442747,-0.206780,-0.205230,-0.009440,0.482847,0.199965,0.317026,0.275317,-0.012122,-0.005667,-0.055462,-0.191230,-0.814420,-0.103583,0.411355,0.374857,-0.221540,0.191176,-0.016679,-0.119935,0.183026,-0.082201,-0.013551,0.271733,0.593381,-0.026076,-0.046832,0.115134,-0.097032,0.497807,0.492403,0.052434,-0.147249,0.344210,-0.237971,-0.494980,-0.457073,-0.315899,-0.089103,0.245891,0.156382,-0.004002,-0.047124,0.226728,-0.541437,0.001252,0.120854,-0.094765,0.086318,-0.135378,0.072239,-0.602541,0.011249,-0.206641,-0.228918,-0.103409,0.299418,-0.372687,1.104440,-0.862193,-0.151693,0.576284,-0.002531,-0.246585,0.490672,0.100379,0.018483,-0.259392,-0.041862,-0.177092,0.045032,0.476834,-0.183027,0.556433,0.257096,-0.702718,-0.518435,0.167843', '27602116', '25880986', '3811356', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920796', '附注：我爱你', '剧情', '霍莉（希拉里•斯万克 饰）与盖里（杰拉德•巴特勒 饰）深爱彼此，虽然有时候他们会有争吵，可是这些都是他们生活中的情趣。霍莉感觉自己已经找到了最爱，盖里却在他们婚后罹患脑癌并逝世了。自此，霍莉便生活在失去挚爱的痛苦中。她感觉丈夫并没有就此离开，她还能在家中感受到盖里的气息。她把自己困在家中，两位好友丹尼丝（莉莎•库卓 饰）、莎拉及霍莉的母亲还有母亲酒吧里的酒保丹尼尔都十分担心她。就在她三十岁生日的那天开始，她便不断收到由盖里给她寄来的信，每封信的最后都加上一句“我爱你”的附注。盖里的信为霍莉的生活注入了力量，她一步步的向前走，但事实上盖里已经死去了，她终究要自己独自生活。丹尼丝怀孕了，莎拉即将要结婚，她们两个都生活在幸福当中，霍莉突感落寞。她又开始躲避众人，自认识霍莉后丹尼尔一直都陪在霍莉身边，丹尼尔向霍莉表达自己的爱意。霍莉第一次跑到母亲怀里痛哭，她也知道了盖里的信原来一直由母亲代寄。最后一封信就要拆开，霍莉会否得到重生呢？', '希拉里·斯万克', '理查德·拉·格拉文斯', 8.1, 124662, 'tt0431308', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p461625359.jpg', 0.3, 2, 21.7, 45.6, 30.5, '0.119717,-0.061414,-0.779469,0.591229,-0.197270,-0.448476,0.957570,-0.121065,-0.318103,-0.261487,0.096895,0.841407,-0.116752,0.581642,0.118760,0.444960,-0.276527,-0.808431,0.184421,-0.184204,-0.325167,-0.305483,-0.352123,-0.253933,-0.247083,-0.182883,0.287897,-0.107003,0.038332,0.340094,0.248578,-0.013060,-0.042340,0.838390,-0.297573,0.431743,-0.201492,0.057817,-0.046480,0.147547,0.409217,-0.268629,-0.022330,0.444829,0.345850,0.374897,0.622981,-0.274350,0.215411,0.178150,0.127865,-0.025214,-0.007176,0.321348,0.165442,-0.030589,0.289508,0.333098,-0.392910,0.079040,0.052676,0.072639,-0.558769,0.084554,-0.156468,0.246018,-0.443941,0.370783,-0.127030,0.077229,0.114403,-0.236408,0.203654,0.182329,-0.208435,0.430973,-0.343830,-0.096657,-0.333484,0.139370,0.585060,-0.326496,-0.021380,0.571956,-0.403414,-0.204601,0.068632,-0.066302,-0.689007,-0.119407,0.094791,0.420956,-0.239763,0.206756,-0.426093,0.106779,-0.199861,-0.163569,0.021703,-0.409226,0.140382,-0.269219,-0.218899,-0.460394,-0.540056,0.117550,-0.100567,-0.361350,0.447786,-0.508413,0.368832,0.438443,0.402928,-0.374863,0.544437,0.267365,0.202704,0.090725,0.030924,0.726652,-0.111646,0.189009,0.224123,0.356365,-0.003529,0.265081,-0.495916,0.715788', '1291877', '1309172', '1292277', '1301582');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920798', '女人们', '剧情', '玛丽·海恩斯（梅格·瑞恩 Meg Ryan 饰）住在纽约曼哈顿区，是小有成就的服装设计师，她还有英俊且事业有成的老公，乖巧可爱的女儿，一家人住在豪华别墅，在任何人眼中都是艳羡对象。在玛丽身边，围绕着一群多年死党，包括独立的时尚杂志撰稿人西尔维娅·福勒（安妮特·贝宁 Annette Bening 饰）、有点唠叨的艾迪·科恩（戴博拉·麦辛 Debra Messing 饰）和性感的散文家亚历克斯·费舍尔（贾达·平克特·史密斯 Jada Pinkett Smith 饰）。但是看似完美的生活被一个意外发现打破，玛丽老公出轨了，对象是外形完美的香水专柜小姐克瑞斯托·艾伦（伊娃·门德斯 Eva Mendes 饰），玛丽寻求好友们帮助，没想到却遭到西尔维娅的背叛……©豆瓣', '梅格·瑞恩', '黛安·英格利什', 6.8, 9204, 'tt0430770', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2270441432.jpg', 0.9, 8.4, 48.8, 32.8, 9.1, '0.232495,-0.155297,-0.588915,0.464172,-0.250305,-0.244458,0.738365,0.190234,-0.473599,-0.298618,0.268710,0.767216,-0.237633,0.288518,0.295565,0.480448,-0.352882,-0.439609,0.150430,0.153022,0.034774,-0.460942,-0.337449,-0.012469,-0.077306,-0.569222,0.110151,-0.424441,0.096620,0.441488,0.542637,0.457441,-0.033199,0.094804,-0.113418,0.025334,0.498853,-0.400514,-0.140453,0.277484,-0.124204,0.174964,-0.115048,0.208567,0.190814,0.156700,0.600343,-0.110790,0.155621,0.173532,0.386683,0.026589,0.261087,0.177589,0.099716,-0.293825,0.060790,0.097618,-0.257183,0.047276,0.498057,-0.076855,-0.490666,0.052542,0.174073,0.234729,-0.570139,0.510246,-0.296590,-0.244879,0.108555,-0.538610,-0.075670,-0.021936,0.007674,0.338736,0.166057,0.506335,-0.423326,-0.007521,0.209722,0.320056,-0.406464,0.147605,-0.515244,-0.221657,-0.033136,-0.150093,-0.926138,-0.076798,0.237051,-0.266962,0.133287,0.217015,-0.580842,-0.101476,-0.333463,-0.152250,0.127129,-0.267961,-0.314209,-0.752017,-0.057753,-0.639742,-0.348623,-0.183974,-0.286185,-0.255214,0.551456,-0.746423,0.181399,0.427520,0.029161,-0.146940,0.712508,0.166785,0.175186,0.007216,-0.335801,0.502280,0.283776,-0.293604,0.146772,0.455173,-0.027186,-0.124163,-0.180025,0.422291', '26809592', '4095250', '35161768', '27089612');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920799', '蓝色吉祥物', '喜剧', '萨尔曼（Scott Prendergast 饰）的哥哥诺亚应征奔赴伊拉克战场，其嫂子莱斯莉（Lisa Kudrow 饰）带着两个儿子为了生活疲于奔命。刚好失业的萨尔曼被嫂子叫到家中，帮忙照顾两个调皮的小家伙。不过为了多挣些钱贴补家用，萨尔曼不得不来到蓝色霓虹公司应聘传单分发员的工作。每天他必须套上闷热厚重的蓝色吉祥物人形，站在公路边向过往的车辆宣传蓝色霓虹的写字楼。经济萧条时期，赚钱尚且不易，他还得忍受旁人奚落的言语和目光。某天，独自回到公司的萨尔曼无意中发现了莱斯莉的秘密……©豆瓣', '丽莎·库卓', '斯科特·普瑞德佳斯特', 7.7, 11887, 'tt0816545', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p934141016.jpg', 0.4, 2.8, 28.1, 50.2, 18.5, '0.170787,0.047597,-0.615490,0.335584,0.114635,-0.587190,0.422140,0.416788,-0.070179,-0.379331,0.122345,0.264217,-0.072857,0.233354,0.308835,0.113245,-0.516788,-0.406919,-0.021540,-0.047255,-0.186784,-0.270883,0.005924,-0.424115,-0.221177,-0.358201,0.120130,0.208351,0.195969,0.212122,0.124422,0.196953,-0.103492,0.180092,-0.229892,-0.367222,0.011032,-0.200648,-0.269280,0.196812,-0.008519,-0.028803,-0.231504,-0.063098,0.445793,0.204516,0.895028,-0.079874,0.107533,0.243723,0.224118,-0.381784,0.211117,-0.150363,0.206673,-0.197303,0.091596,-0.223510,-0.238070,-0.029599,0.052939,-0.332022,-0.479153,-0.081576,-0.215657,0.194378,-0.520701,0.260991,-0.314011,0.010534,0.285496,-0.525926,0.253412,0.231389,-0.198853,0.495534,-0.047455,0.141689,-0.533253,0.165149,0.331895,0.211281,0.024389,0.132708,-0.537357,-0.032695,0.299851,-0.106916,-0.410084,-0.204628,0.408404,-0.336440,0.206916,0.347545,-0.774150,-0.194519,-0.176503,-0.432130,0.138693,-0.403186,-0.244742,-0.580605,0.149603,-0.276400,-0.143664,0.351335,0.106096,-0.051645,0.412981,-0.519933,0.277587,0.607784,0.439640,-0.259897,0.574426,-0.488233,0.413676,-0.068495,-0.378190,-0.010803,0.190129,0.372126,0.210503,0.185612,-0.083991,-0.109842,-0.229798,0.149516', '2159244', '4181031', '10581450', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920805', '成为简·奥斯汀', '剧情', '简•奥斯汀（安妮·海瑟薇 Anne Hathaway 饰）的一生是否如她的文字那样充满曲折的过程和完满的结局？《成为简》用传记方式描述她的一生：她的母亲竭力为她撮合婚事，对象是上层社会的有钱人。但是简不接受没有爱情的婚姻，认为女人要靠自己的能力去养活自身。于是，她拒绝贵族瓦斯莱先生的求婚，爱上了心灵相通的汤姆•勒弗罗伊（詹姆斯·麦卡沃伊 James McAvoy 饰）。好事多磨，有人从中作梗，导致汤姆家人并不赞成二人婚事，汤姆决定携简私奔。但是这样一来，汤姆的经济来源就会被切断，简亦将面临着世俗的压力和贫困的生活。到底二人在私奔路上会走得多远？会不会有美满的结局？©豆瓣', '安妮·海瑟薇', '朱里安·杰拉德', 8.3, 253281, 'tt0416508', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1284506783.jpg', 0.1, 0.9, 15.9, 49.1, 33.9, '0.258454,-0.012635,-0.552965,0.697795,-0.166342,-0.215127,0.624296,0.094458,-0.293542,-0.239072,0.007903,0.780831,0.003217,0.036363,0.128655,0.166631,-0.146020,-0.635009,0.134222,0.121330,-0.370062,-0.822421,0.246062,-0.720797,-0.108386,-0.315672,0.661890,0.148111,-0.383008,0.074936,0.284856,0.550870,-0.038697,0.478160,-0.045606,0.095709,-0.113012,0.115991,-0.524586,0.219081,0.308756,0.151841,-0.037844,0.354632,-0.071165,0.129657,0.414342,-0.255510,0.030747,0.214576,0.440657,-0.287265,0.111001,0.098336,0.068469,-0.344418,0.181230,0.432105,-0.139093,-0.083603,0.123151,-0.039923,-0.608545,-0.237787,0.257765,0.146767,-0.629561,0.347449,0.010765,0.004965,0.019036,-0.415232,-0.054344,0.399827,0.543717,0.232371,-0.150649,-0.036616,-0.746441,0.041084,0.923139,0.124029,-0.174629,0.474102,-0.765606,-0.391302,-0.337255,-0.319463,-0.863943,-0.039174,0.332711,0.095580,-0.288909,0.534990,-0.195623,-0.246278,-0.239972,0.129265,0.283248,-0.631451,0.269019,-0.315992,-0.146971,-0.723806,-0.509267,-0.065384,0.080020,-0.651191,0.712997,-0.827232,-0.010978,0.671311,0.333298,-0.629789,0.830452,0.354235,0.086141,-0.212056,0.108543,0.386987,-0.226655,-0.027968,0.228732,0.015098,0.347593,0.040007,-0.308339,0.739481', '1309177', '1303112', '1309161', '2284481');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1920907', '亡命感应', '剧情', '琳达（桑德拉•布洛克 Sandra Bullock 饰）有着一个看似幸福的家庭——漂亮的房子、两个女儿和丈夫吉姆（朱利安•麦克马洪 Julian McMahon 饰）。然而当有一天，琳达一觉醒来，马上被告知这家庭的支柱，丈夫吉姆已经死于一起交通事故。悲痛万分的琳达想都不敢想失去了吉姆以后的生活。这一夜，她在哭泣中睡去。第二天一觉醒来，琳达赫然发现吉姆还好好的睡在自己的房间！迷惑不解的琳达只好将这一切都当作是自己发过的一场噩梦。但明天一觉醒来，却又发现自己不得不同母亲一起出席丈夫的丧礼！琳达彻底迷惑了，她似乎在不同的时空中来回穿梭：星期四，星期一，星期六，星期二……©豆瓣', '桑德拉·布洛克', 'Mennan Yapo', 6.7, 9713, 'tt0477071', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167450472.jpg', 1.4, 9.2, 51.1, 30.5, 7.7, '0.204639,-0.033987,-0.981308,0.274493,-0.199567,-0.620057,0.887992,0.148754,-0.260737,-0.456115,0.084048,0.799112,-0.379913,0.659209,0.254315,0.098405,-0.516553,-0.566502,-0.110081,-0.064831,-0.462560,-0.358894,0.217083,-0.199533,0.124445,-0.067941,0.282024,-0.214922,0.260004,0.553764,0.281773,-0.050855,0.141719,0.746016,-0.215192,0.057852,-0.014478,-0.047250,-0.005320,0.217878,0.367022,-0.041004,-0.180825,0.467812,-0.016266,0.260394,0.515385,-0.191460,0.011298,-0.119575,0.424243,0.039978,-0.178414,0.141247,0.480868,-0.228088,0.156850,-0.097891,-0.404211,-0.163296,0.326874,0.040499,-0.743170,0.042876,0.072965,-0.018261,-0.415271,0.379472,0.021405,-0.041701,0.039733,-0.331988,0.271391,0.630221,-0.061258,0.591861,-0.145962,-0.073453,-0.604870,0.050867,0.679060,-0.036253,-0.103021,0.443813,-0.204650,-0.168789,-0.023126,-0.069380,-0.542281,-0.097023,0.313156,0.086155,-0.342855,-0.045022,-0.511638,-0.053438,-0.242979,-0.273252,-0.263194,-0.410466,-0.106637,-0.238926,0.051285,-0.229545,-0.492675,0.280360,0.143252,-0.289335,0.462750,-0.870989,0.365724,0.544794,0.331627,-0.181924,0.755645,0.187222,0.210101,-0.043685,0.237028,0.255465,-0.193414,0.254860,0.211420,0.437288,0.165354,0.307893,-0.607014,0.678240', '1292211', '1866424', '1309172', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1921583', '魔术师', '剧情', '20世纪50年代末期，曾经风靡一时的剧场风云变幻，人们迷恋电视、迷恋摇滚，对于曾经伴随他们长大的各种杂耍则不再关注。他是一个经验丰富的魔术师，舞台上得体从容，现实中却不得不为了可怜的生活费而流转于各个表演场所，上至华贵的音乐厅，下至破落偏僻的小酒馆，不变的是他对魔术的执着。在苏格兰某个乡间逗留时，魔术师结识了一个小女孩，她感叹于那些神奇的魔法，于是偷偷离开故乡，转而追随魔术师的脚步。他们辗转来至爱丁堡，生活变得愈加艰辛，而为了满足女孩对魔法的信任和对繁华世界的向往，魔术师不得不想各种办法去赚钱……本片荣获2010年欧洲电影节最佳动画片奖、2010年纽约影评人协会最佳动画片奖。©豆瓣', 'Jean-Claude Donda', '希尔万·肖默', 8.7, 76479, 'tt0775489', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p791086335.jpg', 0.2, 0.7, 10.9, 42.4, 45.9, '0.237974,0.093635,-0.595179,0.709667,-0.019605,-0.088912,0.847145,-0.082269,-0.561881,-0.258325,0.283738,0.933712,-0.159340,0.263546,0.264442,-0.087550,-0.386032,-0.570710,-0.137104,-0.278796,0.047463,-0.170602,-0.380736,-0.200957,-0.402314,-0.233513,0.566713,0.278803,-0.222721,0.530457,0.404444,0.278490,-0.093669,0.143441,-0.394834,-0.310639,-0.054639,0.020122,-0.406441,0.146634,0.065916,-0.439233,-0.418074,-0.010517,0.056810,-0.097965,0.839284,-0.045714,-0.048594,-0.146314,0.530124,-0.160545,-0.271961,0.144258,0.126912,0.131161,0.132071,-0.107763,0.061931,0.003277,-0.220076,-0.326694,-0.816533,0.029926,0.188919,0.166274,-0.404214,0.519580,0.034343,-0.157016,-0.090144,-0.404418,0.129840,-0.168937,0.378454,0.445635,-0.046427,0.178999,-0.050963,0.469382,0.628916,0.359451,-0.328894,0.462960,-0.373860,-0.601636,-0.115003,-0.408989,-0.739794,-0.078645,0.156601,-0.016126,0.030769,0.225174,-0.717813,0.271606,0.078904,-0.449199,0.225869,-0.329946,-0.300569,-0.804201,0.130064,-0.538740,0.013660,-0.027060,-0.026585,-0.352583,0.917428,-0.875319,0.356527,0.729569,0.236150,-0.399121,0.857739,-0.097639,-0.011911,0.013575,-0.331649,0.587332,-0.252837,0.276692,-0.325503,0.278036,-0.192648,-0.138341,-0.378005,0.679625', '3811356', '30162520', '10763928', '3154392');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1921686', '街头霸王: 春丽传奇', '动作', '《街霸之春丽传奇》根据Capcom的经典游戏《街头霸王》改编。黑帮老大拜森(尼尔·麦克唐纳 Neal McDonough 饰)拥有无限的权力，名下的黑暗组织掌管着曼谷的所有贫民窟，由专横且嗜杀成性的巴洛克(迈克·克拉克·邓肯 Michael Clarke Duncan 饰)监管。其他爪牙有面具杀手维加(特布 饰)；美丽而性感的毒碣子康塔娜(何超仪 饰)。拜森的魔爪伸向了春丽(克斯汀·克鲁克 Kristin Kreuk 饰)的父亲。父亲在自己面前被折磨得死去活来，她却无能为力，决定放弃了雍容华贵的舒适生活，师从元(仇云波 饰)习武，希望有朝一日，成为街头战士，保护身边每一个人。国际刑警查理(克里斯·克莱因 Chris Klein 饰)不惜走遍全世界，搜集罪证将拜森庞大的犯罪网络一网打尽。另外，专门调查黑社会凶杀案的警探玛雅(穆恩·布拉得古德 Moon Bloodgood 饰)也从旁协助。他们组成一面不可跨越的正义之墙。一场美与丑、明与暗、善与恶的斗争即将展开......', '克莉斯汀·克鲁克', '安德泽·巴特科维卡', 4.5, 10246, 'tt0891592', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203814382.jpg', 21.5, 39.9, 31.3, 5.4, 1.9, '-0.055842,0.014807,-0.389601,0.576913,-0.062512,-0.108509,0.659951,0.249270,-0.347850,-0.176805,0.323125,0.606733,-0.013277,-0.101582,0.206873,0.215097,-0.265274,-0.744479,-0.168476,0.046961,-0.098069,-0.310763,-0.509651,-0.195613,-0.004232,-0.292760,0.554902,0.020681,-0.087463,0.300381,0.461857,0.512681,-0.230473,-0.151688,-0.121282,-0.260380,0.084099,-0.260530,-0.369593,0.053013,-0.288555,0.028873,-0.105510,0.123752,-0.153945,0.087719,0.438133,-0.373423,0.206770,-0.393274,0.384834,-0.318856,-0.095927,0.085609,0.129880,0.038302,0.103038,0.221556,-0.131214,-0.128961,0.271022,-0.032700,-1.042255,-0.044904,0.235508,0.252411,-0.464953,0.335676,-0.326159,0.044681,0.127067,-0.132840,-0.078007,0.055521,0.272170,0.108343,0.120952,0.070443,-0.466313,0.106335,0.359943,0.030908,-0.316004,-0.255478,-0.236967,-0.240615,-0.173398,-0.487555,-0.331292,-0.180038,0.298730,-0.218190,0.147049,0.441898,-0.722224,-0.153791,-0.301204,0.025985,0.075611,-0.281165,-0.044860,-0.599385,-0.262771,-0.371693,-0.212886,0.073317,0.132539,-0.071233,0.643370,-0.597914,0.247367,0.524737,0.191701,-0.384128,0.392124,0.154549,0.334728,-0.144206,-0.254539,0.409962,0.358507,0.302460,0.123901,0.222595,-0.049412,-0.115482,-0.277593,0.360758', '1793491', '1308585', '1874704', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1922152', '爱情三选一', '剧情', '威尔（瑞安•雷诺兹 饰）的女儿玛雅（阿比吉尔•布莱斯林 饰）在学校学习了性教育之后，回到家中嚷着要父亲给她讲述关于自己的爱情故事。雅玛更想努力的从故事中找到母亲的形象，虽然她的父母已离婚。1992年，威尔暂时别离的女友艾米莉（伊丽莎白•班克斯 饰）独自来到纽约发展自己的事业，他是协助克林顿竞选总统的竞选战团的一员。威尔雄心勃勃，可是他的事业却不如想象中顺利。感情路也是如此，寂寞的威尔跟战团员工艾波（艾拉•费舍尔 饰）、新闻记者夏曼（蕾切尔•薇姿 饰）发展出若有似无的感情，最后他甚至与同样出轨了的艾米莉分手收场。即使到后来威尔在纽约站稳了脚，有了自己的公司，他还是兜兜转转在这三个女人当中，到底谁是他的真爱？©豆瓣', '瑞安·雷诺兹', '亚当·布鲁克斯', 7.8, 50671, 'tt0832266', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p484187995.jpg', 0.2, 2, 27.4, 49, 21.3, '0.117095,-0.059841,-0.693420,0.436558,-0.155753,-0.625311,0.633201,0.258541,-0.423412,-0.112344,0.167033,0.605998,0.028727,0.172277,0.259614,0.187454,-0.455461,-0.685387,0.296489,-0.134223,-0.021046,-0.570412,-0.248044,-0.067726,-0.092590,-0.175246,0.482143,-0.057973,-0.209426,0.164330,0.131553,0.184538,0.103171,0.428053,0.030234,0.233340,0.278254,0.100496,-0.185217,0.096298,0.221467,-0.189661,-0.400960,0.254567,0.307547,0.359573,0.436951,-0.071795,0.185009,0.108929,0.207031,-0.126576,0.075738,-0.024294,0.149470,-0.288909,0.278035,0.390146,-0.096134,-0.244931,0.119457,-0.141354,-0.535345,0.076377,-0.231595,0.298331,-0.796429,0.243572,-0.293894,-0.046355,0.261284,-0.386741,0.028735,0.558810,0.022159,0.281036,-0.223450,0.096949,-0.554748,0.225162,0.477530,0.205658,-0.268716,0.316004,-0.161746,-0.462464,-0.215186,-0.078602,-0.580273,-0.269080,0.502903,-0.124437,-0.187346,0.396321,-0.407740,-0.182752,-0.258433,-0.216440,-0.005331,-0.449194,0.248828,-0.433698,-0.092953,-0.517301,-0.506091,-0.328412,0.008744,-0.314933,0.597395,-0.889056,0.205087,0.592732,0.232736,-0.594139,0.674124,0.203160,0.337613,0.030452,0.037317,0.575037,-0.223408,0.188107,0.014530,0.453727,0.389718,-0.174710,-0.492881,0.585206', '1301022', '1783461', '1299965', '1301221');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1922273', '电锯惊魂4', '悬疑', 'SWAT指挥官瑞格（莱瑞克•本特 饰）突然被绑架，卷入了一场致命游戏，他必须在一个半小时之内过关斩将，躲过一个比一个恐怖的陷阱，才能保住性命。经验十足的FBI探员斯琼姆（斯科特•派特森 饰）来到被折磨得筋疲力尽的警察局，协助警探一起研究被竖锯玩死的受害者尸体，试图找出蛛丝马迹。随着调查的深入，竖锯变态的起因以及他邪恶的计划渐渐浮出水面……©豆瓣', '托宾·贝尔', '达伦·林恩·鲍斯曼', 7.8, 115215, 'tt0890870', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196982868.jpg', 0.4, 2.6, 27.9, 43.9, 25.2, '0.086575,-0.184848,-0.241252,0.413115,-0.124174,-0.202488,0.740065,-0.044547,-0.289586,0.125731,0.374758,0.139270,-0.343278,-0.392830,0.210550,-0.399583,-0.260966,-0.672387,0.016892,-0.050042,-0.488983,-0.716292,-0.601965,-0.183651,0.157514,-0.252744,0.452834,-0.001348,-0.073932,0.345279,0.235703,0.494152,-0.304598,0.102569,-0.014210,-0.085040,0.451822,-0.475306,-0.102797,0.289015,0.098455,-0.217595,0.135720,-0.169217,-0.297474,0.628046,0.685052,-0.161009,-0.139782,-0.076724,0.269216,-0.543101,-0.115850,0.212592,0.545605,0.280669,-0.117354,0.265564,-0.384661,-0.110126,0.358003,-0.192468,-0.928742,-0.062503,0.238659,-0.065732,-0.502555,0.021029,0.071543,0.363263,0.223135,-0.020325,0.083146,0.205653,0.335106,0.187292,-0.154708,0.183338,-0.457992,-0.014308,0.473476,-0.425534,-0.117648,-0.009048,0.256973,-0.063782,-0.048226,-0.439183,0.145212,-0.033334,0.622646,-0.176597,-0.279634,0.268992,-0.374339,-0.052872,-0.704360,-0.295572,-0.254222,-0.329538,-0.250475,-0.615471,-0.243960,0.176493,-0.009368,0.375488,-0.112783,-0.145978,0.313745,-0.288383,0.112972,0.649990,-0.101416,-0.182880,0.263226,0.066359,0.169084,-0.152973,0.046808,0.195032,0.473210,0.394042,0.358058,0.551898,-0.043403,-0.111418,-0.618074,0.384800', '26747274', '3143727', '26816090', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1922691', '胖男孩快跑', '喜剧', '丹尼斯（西蒙·佩吉 饰）当年因害怕成立家庭，并觉得自己会毁掉女友比莉（桑迪·牛顿 饰）的一生，结婚当天丢下了已怀孕的女友逃走了。5年后，丹尼斯才发现自己原来一直是爱着比莉的。就算他们会因为儿子的关系经常见面，可是比莉已经与会计师威特（汉克·阿扎利亚 饰）约会，她早已因丹尼斯当年的行为而死心。纵使丹尼斯对于威特充满了敌意，可是自己也明白他根本比不上帅气成功的威特。胖胖的丹尼斯不过是个保安而已，他微薄的工资无法付得起房租，房东的女儿把他赶到了大街上去。彷徨无助的丹尼斯感到无地自容，他不知如何面对儿子与比莉，还有情敌威特。可是他一想到要与比莉重新在一起，他毅然宣称要参见马拉松比赛，在马拉松赛场上，还是情感的赛场上，丹尼斯都誓要胜过威特……©豆瓣', '西蒙·佩吉', '大卫·休默', 7.1, 6489, 'tt0425413', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p788103638.jpg', 0.6, 5.1, 43.9, 39.3, 11.1, '0.076699,-0.036351,-0.749555,0.346874,-0.136913,-0.662663,0.627305,0.020357,-0.544479,-0.326178,0.044071,0.779387,-0.105212,0.400259,0.405486,0.203563,-0.073561,-0.604093,0.093404,-0.247092,-0.149204,-0.728246,-0.105039,-0.145499,-0.171219,-0.272350,0.401021,-0.207345,0.081598,0.556923,0.599881,0.147893,0.234119,0.578354,0.028769,0.022431,-0.011052,-0.059499,-0.413184,0.068519,0.230748,0.082015,-0.144826,0.275565,0.095030,0.300805,0.335242,0.042922,-0.114873,-0.050472,0.307082,-0.093329,0.098965,0.087109,0.237645,-0.145182,0.295382,0.232149,-0.172672,0.030520,0.269844,0.026429,-0.593633,0.273295,-0.064795,0.104596,-0.607194,0.420041,-0.270386,-0.046959,0.118164,-0.422344,0.107733,0.283087,0.211908,0.365935,-0.279951,-0.162252,-0.596796,-0.147999,0.647560,0.058838,0.006689,0.390469,-0.157563,-0.248814,0.013982,-0.290519,-0.620190,0.285424,0.054656,0.222618,-0.324635,0.244899,-0.217737,-0.190296,-0.323055,-0.124826,-0.032569,-0.475972,0.132069,-0.025575,-0.121786,-0.490265,-0.534672,0.045465,-0.014496,-0.312656,0.391981,-1.087355,0.262378,0.647768,0.472011,-0.422442,0.485462,0.352991,-0.031419,-0.046626,-0.121697,0.432850,-0.089239,0.118819,0.094972,0.183119,0.311284,-0.215426,-0.043266,0.672501', '1308755', '35030151', '1301022', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1923474', '黄石的孩子', '剧情', '英国记者乔治•何克（乔纳森•莱斯•梅耶斯 饰）潜入了南京，打算把日军在当地的暴行公诸于世。可是他被日军发现了，在即将被斩头之际，一名中国游击队员陈汉生（周润发 饰）救起了。何克还认识了战地外籍医生丽（拉达•米契尔 饰）。何克辗转到了黄石，与60多名孤儿一起居住。孩子们保饱受战争折磨，对外国人他们都有抵触心理，甚至不尊重。可是随着时间的过去，何克的热心与善良还是感动了孩子们，短短几个月他们的生活与周遭环境有了很大的改善。也幸得有好心人王太太（杨紫琼 饰）的帮助。生活日渐上了安稳的轨道，战争的步伐也逐渐逼近。何克与汉生还有丽决定带着孩子们到山丹，一个人迹罕至的地方。路途之艰辛，同伴的离世也无法阻挡他们的脚步。可是一场疾病，还是打击了汉克、丽与孩子们的生活……©豆瓣', '乔纳森·莱斯·梅耶斯', '罗杰·斯波蒂斯伍德', 6.7, 19378, 'tt0889588', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1235740035.jpg', 1.4, 8.4, 50.7, 31.6, 7.8, '0.034337,-0.262312,-0.668779,0.480604,-0.039099,-0.345591,0.712657,0.103289,-0.523546,-0.154763,0.180913,0.536256,-0.073603,0.204717,0.276226,-0.103423,-0.414606,-0.724191,-0.127681,-0.099096,-0.594943,-0.328295,-0.108594,-0.330562,-0.277439,-0.412704,0.464018,0.213873,0.009803,0.462360,0.170483,0.297161,-0.073099,0.568025,-0.355117,0.199213,0.252159,-0.223722,-0.300094,-0.062912,0.095006,-0.376631,-0.200726,0.112193,0.115294,0.336116,0.785101,-0.226745,-0.125833,-0.120087,-0.033185,-0.255575,0.085002,0.358879,0.353029,-0.088322,0.120618,0.196153,-0.148288,0.065885,0.087781,-0.161030,-0.350363,0.219455,-0.005138,0.105602,-0.735787,0.558854,0.080934,-0.173874,-0.139742,-0.403472,0.150061,0.436778,0.055511,0.321707,-0.352055,-0.036659,-0.496512,0.101931,0.816693,0.022257,-0.345118,0.349957,-0.433494,-0.463807,-0.092754,-0.155146,-0.556508,-0.127189,0.405983,0.041861,-0.379303,0.337544,-0.620637,0.169672,-0.511686,-0.402364,-0.034243,-0.462557,0.113521,-0.687024,-0.106497,-0.684365,-0.508966,0.201244,0.118739,-0.044445,1.206679,-0.660752,0.177171,0.603328,0.479375,-0.653532,0.521992,0.125042,0.208737,0.173855,0.059813,0.339433,-0.090754,0.328571,0.345827,0.444196,-0.308311,-0.067207,-0.251670,0.370576', '3811356', '26348103', '25922902', '1303010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1925058', '逃离地球', '喜剧', '在距离地球15光年的外太空，科技昌明的Baab星上生活着一群爱好和平的蓝色小人。其中斯科奇（布兰登·费舍 Brendan Fraser 配音）是该星球一个勇猛果敢、正义感十足的超级英雄，他经常驾驶超新星-9号飞船穿梭宇宙，在BASA总部他的兄弟盖里（罗伯·考德瑞 Rob Corddry 配音）的指挥下，一次次圆满完成营救受困外星人的任务。这一日，刚回家不久的斯科奇被BASA负责人莉娜（杰西卡·阿尔芭 Jessica Alba 配音）命令即刻前往黑暗星球——地球执行救援任务。担心兄弟的安危，盖里与执意前行的斯科奇发生争吵。在全Baab星人民的注视下，斯科奇成功抵达著名的51区，结果却被夏克尔将军（威廉·夏特纳 William Shatner 配音）为首的军方抓获。为了救回最亲密的兄弟，一向谨小慎微的盖里不得不踏上凶险的征途，而这一切背后的阴谋也悄悄浮出水面……', '杰西卡·阿尔芭', '卡尔·布伦克尔', 6.6, 5386, 'tt0765446', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2135936250.jpg', 1.4, 9.3, 55, 27.1, 7.3, '0.079982,0.170088,-0.793524,0.606283,-0.052158,-0.055549,0.441710,0.154510,-0.192841,-0.168595,0.330240,0.702698,0.017352,-0.119498,0.566028,0.086868,-0.426238,-0.397312,-0.334130,-0.184519,-0.305900,-0.345485,-0.301602,-0.338716,-0.031142,-0.295588,0.608806,0.279882,-0.010492,0.266683,0.274962,0.325694,-0.373536,0.419000,-0.068305,-0.022223,0.270078,-0.118969,-0.309815,0.236757,-0.251442,0.149070,0.028326,0.022531,0.074514,0.268053,0.596047,-0.362154,0.094427,-0.109625,0.180698,-0.652959,0.314695,-0.326718,0.560305,-0.004575,-0.129512,0.195886,0.040178,-0.034267,0.050802,-0.261572,-0.696877,-0.136850,-0.096388,0.123975,-0.538861,0.162135,-0.114462,-0.048981,-0.041412,-0.113744,0.309384,0.472542,0.058971,0.150762,0.013730,0.281992,-0.274899,0.035117,0.599485,0.095072,-0.159253,-0.041719,-0.044878,-0.457039,-0.043238,-0.241106,-0.553980,-0.166003,0.403506,-0.077562,-0.025671,0.296517,-0.490541,0.194428,-0.386418,-0.392648,-0.150290,-0.439548,-0.058312,-0.726052,0.239071,-0.148623,-0.179445,0.215902,0.025852,-0.052118,0.574469,-0.786619,0.101281,0.567848,0.365778,-0.247085,0.529436,0.126736,0.232328,-0.347317,-0.048192,0.419014,0.124481,0.539344,-0.120858,0.315278,-0.004344,0.006419,-0.486758,0.386200', '1420088', '1438591', '25928048', '3178770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1926007', '天堂口', '剧情', '阿峰（吴彦祖饰），小虎（杨佑宁饰）和大刚（刘烨饰）是在乡下从小一起长大的好兄弟，好朋友。大刚为了出人头地的梦想，说服他们，一起来到了传说中黄金遍地的上海，准备大干一场。到了上海一段时间后，小虎和阿峰来到了天堂口歌舞厅，在那里遇到了美丽的歌女露露（舒淇饰），还有当时在上海声名显赫的实力人物，也就是天堂口的主人洪哥（孙红雷饰）。在歌舞厅的侧面路口，阿峰偶遇了受伤倒地的马克（张震饰），并把他带回家救治。从此，这几个好朋友的人生围绕着醉生梦死的天堂口歌舞厅开始发生变化……时间是永不回头的箭，当他们开始怀疑自己的时候，会否后悔当初来到是上海的决定呢？这里，真的是天堂吗？©豆瓣', '吴彦祖', '陈奕利', 5.7, 44451, 'tt0897287', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2037811305.jpg', 7, 24, 51.1, 14.2, 3.6, '0.323689,0.053436,-0.748940,0.271770,-0.208784,-0.372582,0.629468,0.171188,-0.502609,0.072153,0.262027,0.805466,-0.090803,0.614050,0.263889,0.171477,-0.379984,-0.754188,-0.023852,-0.305868,-0.359655,-0.286630,-0.169044,0.048530,0.015335,-0.183627,0.323068,0.113248,0.172729,0.504698,0.312662,-0.096063,-0.196807,0.319948,-0.599121,0.138014,-0.096193,0.120915,-0.522586,0.288989,0.193302,-0.095130,0.039076,0.040782,0.292261,-0.015635,0.485933,0.048671,-0.095060,0.058143,-0.019308,-0.144251,-0.022353,-0.055342,0.356203,-0.258516,0.404600,0.054183,-0.117738,0.154965,-0.132845,-0.120296,-0.468907,0.153042,0.060540,0.009543,-0.902178,0.425576,0.145241,-0.118525,0.303141,-0.404133,0.399070,0.310031,0.165602,0.448021,-0.299930,-0.004286,-0.645034,0.272708,0.853710,-0.079468,0.109804,0.329484,0.321626,-0.409304,-0.073890,0.131240,-0.189839,-0.009747,0.252736,-0.055598,-0.384035,-0.152351,-0.756268,0.065690,0.098696,-0.073039,0.047000,-0.254936,-0.042647,-0.391268,-0.039992,-0.411884,-0.115259,0.151280,-0.136375,-0.146148,0.599433,-0.960448,0.220825,0.474101,0.514291,-0.461448,0.802660,0.023374,0.016635,-0.159169,0.047621,0.129364,-0.071430,0.463871,0.074892,0.250598,-0.010648,-0.162871,-0.587143,0.469061', '3055049', '2124718', '1302384', '1296538');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1926517', '蠢蛋进化论', '喜剧', '研究者对同年龄组的两个家庭做了跟踪调查：一对是IQ为130的天才组合，夫妻和睦，但是无嗣，正当两人准备作试管婴儿之时，男主人却在自慰中意外死亡；另一个家庭，都是IQ 80的低能夫妻，天天吵架，不过却人丁兴旺，不仅三代同堂，而且家族甚大。根据这个调查，研究者选择了一个自愿 者鲍尔斯（卢克•威尔逊 Luke Wilson 饰）做冷冻实验，不想实验出了差错，500年后他醒来后，却成为地球上最聪明的人。他被盲打误撞地选做了总统的候选人，支持他的甚至还有5届自由搏击冠军。在盛大的竞选现场，他只能硬着头皮面对选民演说，对于目前的种植、沙尘暴等问题，他提出的是灌溉这一看似离谱的解决办法。而且，还得到了选民的拥护，然而这个美梦迅速破灭了，他开始遭到谩骂、攻击，甚至是性命堪忧……©豆瓣', '卢克·威尔逊', '迈克·乔吉', 6.6, 13875, 'tt0387808', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2383837833.jpg', 2.8, 12.1, 46.5, 28.5, 10.1, '0.333779,-0.060756,-0.617868,0.475054,-0.210926,-0.165898,0.499724,0.031916,-0.568457,-0.198400,0.272394,0.693562,-0.220437,0.118610,0.040601,-0.237138,-0.188817,-0.655917,-0.035834,0.073056,-0.390236,-0.546331,-0.177789,-0.215850,-0.290505,-0.121246,0.653556,0.116690,-0.146143,0.169655,0.237681,0.112583,0.335914,0.454990,-0.266791,-0.120341,0.181859,0.125671,-0.263443,0.284688,0.018661,-0.326314,-0.190306,0.377558,0.063894,0.725564,0.364432,-0.373590,-0.164557,-0.243972,0.393973,-0.429432,-0.198120,0.296443,0.307908,-0.025074,0.205962,0.224342,-0.015125,-0.054977,0.008597,0.038350,-1.101005,0.058917,0.227979,0.066955,-0.490639,0.385501,-0.055785,-0.128813,0.014868,-0.163263,0.248187,0.424000,0.414830,0.397888,-0.310588,0.068455,-0.468564,0.151173,0.735729,0.077832,-0.598757,0.393024,-0.381278,-0.685096,0.179067,-0.533992,-0.200407,-0.054314,0.074159,0.143137,0.046347,0.140918,-0.392336,0.052389,-0.245124,-0.311826,0.057619,-0.423845,-0.094969,-0.443962,0.140793,-0.128891,-0.533288,0.210220,0.130647,-0.499154,0.771012,-0.820692,-0.001419,0.390709,0.328248,-0.724501,0.740821,0.221831,0.241431,-0.150943,-0.036418,-0.044763,-0.066022,0.133421,-0.033103,0.186442,0.365782,-0.325324,-0.239951,0.340329', '1793491', '26678784', '30163500', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1926790', '蜡笔小新：卟哩卟哩王国的秘密宝藏', '动画', '蜡笔小新推出的又一剧场版。这次，小新的妈妈美伢时来运转，竟然抽中了特等奖——全家到美丽的布里布里岛国免费6日游！于是，爸爸、妈妈和小新收拾好东西出发了！孰料，旅程中小新竟然遭人绑架了！原来布里布里国的黄金之都埋藏着神奇的宝藏，当地野心勃勃的白蛇党领袖蟒蛇伯爵妄图掠夺宝藏，而打开黄金之都的钥匙就是布里布里国的森凯诺王子。巧合的是，森凯诺王子和小新长得一模一样，于是小新就被当成森凯诺王子遭到了白蛇党的绑架。小新这一次巧妙之旅又将碰到什么新奇古怪的人和事？©豆瓣', '矢岛晶子', '本乡满', 8.1, 10314, 'tt0477602', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2224674814.jpg', 0.1, 1.2, 22.6, 44, 32, '0.205439,-0.078925,-0.556059,0.573206,-0.090635,-0.521959,0.646674,-0.076597,-0.374498,0.008395,0.306258,0.458749,-0.057405,0.123778,0.341283,0.577630,-0.426562,-0.456407,-0.086383,-0.267156,-0.210883,-0.100057,-0.529893,-0.192036,0.093795,-0.333601,0.111250,-0.072145,-0.103460,0.268240,0.579109,0.010963,-0.147690,0.263186,-0.219901,0.281064,0.186567,0.072028,-0.052020,0.134235,0.031434,0.172786,0.000417,0.323672,0.125439,0.351311,0.357895,-0.519012,0.247081,-0.259890,0.302693,-0.381578,-0.056507,0.248721,0.378653,0.291606,0.455990,0.002061,-0.113689,-0.141336,0.510425,-0.070554,-0.544075,0.116002,0.188762,-0.012236,-0.435157,0.426055,-0.187183,-0.029337,0.289326,-0.523816,0.269892,0.447700,0.625821,0.324961,0.047196,-0.016868,-0.357371,0.091707,0.538533,-0.071112,-0.218716,-0.147513,0.283918,-0.550530,0.368998,-0.206734,-0.195333,0.035869,0.873972,-0.226200,0.101187,0.636806,-1.050737,-0.101923,-0.446985,-0.162364,0.344589,-0.379301,-0.118289,-0.245936,0.180187,-0.168713,-0.021354,0.208177,0.486517,-0.004114,0.606026,-0.553040,0.209153,0.557066,0.091415,-0.373714,0.347890,-0.155112,-0.200085,0.199660,-0.292884,-0.063292,0.294514,0.703707,-0.001049,0.422711,0.092969,-0.493232,-0.416283,0.442921', '1309031', '26290398', '1292680', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1926795', '史诗电影', '喜剧', '被卢浮宫馆长扶养长大，却因为某白化病刺客杀死馆长而被迫四处流浪的露西（洁玛·梅斯），在墨西哥“自由摔角”大闹过后的难民爱德蒙（卡尔·潘）。近来“航班蛇患”事件中的生还者苏珊（芳恩·钱伯尔斯）和来自“X战警社区”却没有超能力的变种人彼得（亚当·坎贝尔），这四个可怜孤儿终于走到了一起。不幸的四人受邀进入怪人威利·旺卡的“巧克力冒险工厂”参观，结果露西在一个房间发现了神秘的魔衣橱。好奇的露西打开衣橱，竟然发现它可以通到传说中的“哪里呀”王国！在王国里，他们遇见了上半身是人而下半身却长着羊蹄的小鹿，打扮花哨的海盗头子杰克船长，巫师学院的哈利波特，而他们都是正义狮神阿斯兰大军的成员。为了对抗邪恶的“白衣贱女巫”，他们加入了狮神阿斯兰的队伍，成为王国的统领，带着虾兵蟹将，拯救“哪里呀”王国！', '卡尔·潘', '贾森·弗莱德伯格', 5.1, 6168, 'tt0799949', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1282970153.jpg', 17.8, 29.6, 38.5, 9.5, 4.6, '0.497456,-0.083997,-0.426636,0.332410,-0.104465,-0.371286,0.825136,0.085874,-0.496043,-0.258353,0.349829,0.615106,-0.015467,0.189074,0.379732,0.273284,-0.439776,-0.317822,-0.217869,-0.181506,-0.386346,-0.194744,-0.343587,-0.526604,0.115647,-0.463643,0.486343,0.021791,-0.021995,0.487829,0.301953,0.398471,-0.416412,0.254231,-0.189269,0.200999,0.537012,-0.119031,-0.061307,0.321822,-0.256571,0.055126,-0.270045,0.235211,-0.024838,0.205291,0.466180,-0.467703,0.236365,-0.238538,0.054560,-0.324229,-0.079288,0.016552,0.553968,-0.316769,0.209893,-0.019651,0.325788,-0.072958,0.217436,-0.039068,-0.581335,0.121442,0.109305,0.447161,-0.495946,0.448622,-0.135320,-0.050981,0.169494,-0.180030,0.168800,0.290712,0.092807,0.333368,0.111198,0.120574,-0.771413,0.000270,0.454679,-0.155171,-0.339324,-0.188621,-0.169345,-0.595389,0.064601,-0.317278,-0.271981,-0.159267,0.379159,-0.183946,-0.134658,0.215137,-0.836173,0.081468,-0.298066,-0.212718,-0.154922,-0.184830,-0.153712,-0.644082,0.055728,-0.319473,-0.044475,0.148889,0.051965,0.041622,0.575406,-0.794779,0.252163,0.761041,0.304519,-0.210915,0.619724,-0.201576,0.005047,-0.199555,-0.252118,0.256733,0.342327,0.400084,0.356918,0.435996,-0.020454,-0.258901,-0.327227,0.294524', '3005387', '1309101', '1301686', '26586766');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1926812', '蜡笔小新：动感超人大战泳装魔王', '喜剧', '动感超人的动感石头被泳装魔王抢走了，因而无法回到原来的世界，于是指派小新一家人成为动感战士前往另一个世界，这时另一个世界的人纷纷被变成泳装人，小新听了莉莉和博士的说明后，决定协助动感超人克服危机，他和动感超人能打败魔王挽救地球的和平吗...', '矢岛晶子', '本乡满', 7.9, 9459, 'tt0409848', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2224675153.jpg', 0.3, 2.2, 28.5, 40.7, 28.4, '0.269486,0.318328,-0.513000,0.429545,-0.577602,0.060523,0.480199,0.255647,-0.470078,-0.000373,0.138683,0.996056,-0.024413,0.079513,0.717114,0.096967,-0.436256,-0.673382,0.186733,-0.152510,-0.571806,-0.265224,-0.186238,-0.524774,0.043526,-0.755792,0.822346,0.194203,-0.044666,0.151154,0.245315,0.504655,-0.116512,0.622951,-0.192600,0.169610,0.337440,-0.110918,-0.340462,0.748796,-0.192195,0.503518,0.331809,0.486448,-0.611658,-0.160502,0.688635,-0.725051,0.037788,-0.476295,0.313982,-0.324457,-0.185155,-0.019914,0.229986,-0.172916,0.261711,0.242178,-0.005837,0.020106,0.472467,-0.125984,-0.811434,0.197614,0.162871,0.016993,-0.320099,0.296896,0.023501,-0.096484,0.228981,-0.125654,0.417313,0.389221,0.699760,0.514257,-0.086526,0.091174,-0.512039,0.099042,0.702274,-0.103467,-0.256693,0.184817,0.135263,-0.199687,0.036446,-0.225269,-0.198791,0.148092,0.362664,0.272503,-0.421467,-0.102240,-0.714163,-0.152611,-0.340054,-0.204120,0.326802,-0.886659,-0.479479,-0.369029,0.005327,0.346486,0.278787,0.114286,0.028329,-0.125544,1.092991,-1.024900,0.019461,0.180730,0.294930,-0.476816,0.830822,-0.153309,0.100138,-0.549306,0.197213,0.052472,0.016578,0.718324,0.153306,0.188416,-0.152510,-0.048829,-0.291140,0.325411', '35048413', '27602116', '26311828', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1927369', '天使与魔鬼', '动作', '本片根据美国畅销作家丹•布朗的同名小说改编。欧洲核子中心的科学家维多利亚•维特勒（阿耶莱特•祖瑞尔 Ayelet Zurer 饰）与父亲在高速粒子对撞机实验中收集到了反物质，却发现父亲遇害，尸体胸口被烙“光照派”符号，高爆炸性的反物质被偷走，出现在正待选新教皇的罗马梵蒂冈，威胁天主教廷及整个罗马的安危。于此同时，四位主要教皇候选人的红衣主教神秘失踪。在教皇内侍（伊万•麦克格雷格 Ewan McGregor 饰）的授意下，哈佛大学的符号学专家罗伯特•兰登教授和维多利亚都被请到梵蒂冈协助罗马警察开展搜寻行动。兰登说服罗马总探员奥利维迪（皮耶法兰西斯柯•法维诺Pierfrancesco Favino 饰）依照“土、气、火、水”的提示在罗马的名胜教堂间与“光照派”展开了时间战……©豆瓣', '汤姆·汉克斯', '朗·霍华德', 7.4, 108549, 'tt0808151', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p786228964.jpg', 0.4, 3.6, 36, 45.5, 14.4, '0.249154,0.016569,-0.689594,0.701970,0.334551,-0.265436,0.527499,0.278400,-0.280626,-0.291673,0.194986,0.616580,-0.302614,0.145367,0.360667,0.055369,-0.487307,-0.603803,-0.178279,-0.141665,-0.402905,-0.690708,-0.365497,-0.248682,-0.080568,-0.734220,0.247625,0.103737,-0.180380,0.159925,0.167438,0.540715,-0.205626,0.163690,0.040442,-0.048274,0.615381,-0.454373,-0.176451,0.320135,0.094285,-0.120062,0.124587,0.081160,0.102328,0.429807,0.191133,-0.394453,0.412809,-0.044550,0.311243,-0.348445,0.102021,0.043654,0.485477,0.228920,-0.276626,0.198414,-0.171645,0.079177,0.054517,-0.158748,-0.510941,0.056081,0.127603,0.328189,-0.576030,0.322933,-0.363534,-0.001386,-0.075728,-0.198079,0.260465,0.111770,-0.063357,0.159569,0.165814,-0.009296,-0.302936,0.097184,0.264327,-0.138456,-0.285066,-0.228431,-0.133553,-0.358033,0.002989,0.088360,0.006716,0.016595,0.530698,-0.227749,0.405714,0.395548,-0.587510,-0.151134,-0.444432,-0.243347,-0.000971,-0.036067,0.058905,-1.053839,-0.171171,-0.043163,0.023877,-0.022148,0.214320,0.077429,0.459388,-0.371566,0.340255,0.470035,0.185129,-0.143889,0.526496,-0.078298,0.004154,-0.184591,-0.269584,0.179077,0.443943,0.540099,0.175874,0.308160,0.222197,-0.245806,-0.341416,0.161347', '6517421', '2075345', '1293572', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1927686', '爱情呼叫转移', '喜剧', '徐朗（徐峥饰）人到中年，婚姻正经历七年之痒的考验。家庭生活的细碎，烦闷与周而复始，终于使他败下阵来，向相守多年的妻子提出离婚。偶然中，徐朗遇到了一个脾气古怪又爱捉弄人的天使（刘仪伟饰），得到了具有魔力的神奇礼物——一部可以满足主人所有愿望，将梦中天使带到他身边的手机。于是，十二位性格迥异，却都拥有天使面孔的女人翩然而至。她们或纯洁坚韧，或天真无邪，或性感妖娆，或知性端庄…十二种粉红女郎，十二种生命经历，十二种致命诱惑。在这场情感的闹剧中，徐朗最终得到是不尽的幸福，还是不明的困惑…©豆瓣', '徐峥', '张建亚', 6.4, 170796, 'tt0902249', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1103600864.jpg', 2.1, 11.6, 55.5, 25, 5.9, '0.015593,0.355661,-0.292163,0.660880,-0.301510,-0.101047,1.089558,-0.181730,-0.285747,0.065578,0.189123,0.419601,-0.098867,0.337832,0.234791,0.071817,0.009245,-0.698165,-0.113394,0.172518,-0.055300,-0.260361,-0.287925,0.090764,0.098501,-0.537733,0.686295,0.246060,-0.020328,0.416296,0.449462,0.277620,-0.414142,0.307667,-0.171966,-0.259762,-0.264909,0.234246,-0.255993,0.075168,-0.057896,-0.079936,-0.102472,0.297358,-0.256907,0.042988,0.658326,-0.496584,-0.361890,-0.119406,0.542458,0.190901,-0.155715,0.248085,-0.090599,0.312122,0.347238,0.104847,-0.115781,0.005657,0.207782,0.061667,-0.851059,-0.173269,0.098035,0.203663,-0.145139,0.318944,0.171309,-0.020270,0.287473,-0.202211,-0.007669,-0.158162,0.635071,0.643097,-0.166089,0.099431,-0.233711,0.211247,0.547553,0.287430,-0.444878,0.363499,-0.902082,-0.432839,0.131258,-0.476704,-0.570698,0.346467,0.198343,0.222627,0.134584,0.425747,-0.714132,0.172777,-0.083247,0.328567,0.081848,-0.480568,-0.148288,-0.425047,-0.228626,-0.427577,-0.504207,0.073526,0.224420,-0.352796,0.993264,-0.760350,0.307508,0.416405,0.161276,-0.468109,0.594516,0.264276,-0.008007,-0.217417,0.222738,0.615567,-0.365499,-0.285439,-0.287775,0.258494,-0.222208,0.453418,-0.314881,0.577601', '25882279', '26348103', '3005387', '1303542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1929402', '切·格瓦拉传：阿根廷人', '剧情', '1952年，古巴独裁者巴蒂斯塔上台，他所率领的政府在国内实行高压统治，对国外则推行亲美政策。切•格瓦拉（Benicio Del Toro本尼西奥•德尔•托罗 饰）于1955年和菲德尔•卡斯特罗（Rodrigo Santoro 罗德里格•桑托罗 饰）在墨西哥城相会，随后加入卡斯特罗组织的“七二六运动”。次年，格瓦拉与其他81名起义者一同踏上推翻巴蒂斯塔独裁政府的征程……为了详尽真实再现革命家切•格瓦拉的一生，美国好莱坞著名导演史蒂芬•索德伯格（Steven Soderbergh）用了4个小时来描绘这位传奇英雄。最终按照院线的需要，影片被分作两部分上映。本片荣获2008年戛纳电影节最佳男主角奖，并获得金棕榈奖提名。©豆瓣', '本尼西奥·德尔·托罗', '史蒂文·索德伯格', 7.5, 7836, 'tt0892255', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1533623280.jpg', 0.7, 3.2, 30.9, 49, 16.2, '-0.086436,-0.043963,-0.313426,0.504822,0.417892,-0.257936,0.052062,0.179097,-0.212706,-0.118865,-0.099023,0.846025,-0.265841,-0.320601,0.589941,-0.270809,-0.609079,-0.714549,-0.103228,-0.158343,0.240624,-0.534997,-0.373425,-0.177739,-0.220531,-0.257483,0.827890,-0.122306,-0.033225,0.437268,0.676911,0.302172,0.147648,-0.248121,0.141664,0.037261,0.399193,-0.371508,-0.795831,0.436586,-0.201772,-0.180477,-0.324215,-0.184472,0.023238,0.329956,0.263934,-0.358615,0.368933,-0.220512,0.573175,-0.309859,-0.182300,-0.049797,0.231394,0.059378,0.093689,0.460479,-0.003249,0.184192,-0.044999,-0.468493,-0.494229,-0.115805,0.074637,0.154597,-0.309834,0.341356,-0.228460,0.136836,-0.172101,-0.290081,-0.122115,0.594275,0.319206,0.211495,0.193805,0.083123,-0.180339,0.485983,0.309819,0.031868,-0.456394,-0.102759,-0.055793,-0.479344,-0.097417,-0.442528,-0.136789,-0.003152,0.397078,-0.112737,0.249270,0.383531,-0.604457,-0.202294,-0.140696,-0.532441,0.237927,-0.008284,0.165529,-0.804881,-0.128057,-0.066790,0.145014,-0.180607,0.209649,-0.117095,0.649840,-0.419710,0.257676,0.353639,0.434062,-0.354450,0.588176,0.199364,0.073359,-0.204795,-0.202892,0.425983,-0.007566,0.030126,-0.048348,0.250296,0.111669,-0.427158,-0.007690,0.184892', '1780122', '26990609', '1298616', '2336737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1929438', '诺比特', '喜剧', '黑人青年诺比特（艾迪·墨菲 Eddie Murphy 饰）的身世颇为不幸，他从小被父母抛弃，全靠一个经营餐馆和孤儿院的中国人老王（Eddie Murphy 饰）将其养育成人。诺比特经常受到小伙伴们的欺负，只有美丽的凯特是他最好的伙伴，两人童年时甚至举行了幼稚可爱的结婚仪式。当然，并非所有美好的故事都有美好的结局。诺比特的婚姻可谓一场悲剧。他的妻子不是凯特，而是体型巨大、堪以吨计的超级肥婆拉丝普蒂娅（Eddie Murphy 饰）。拉丝普蒂娅颟顸粗鲁，性格暴躁，诺比特在她的“领导”下唯唯诺诺，苦不堪言。某天，命运之神忽然降临。括别多年的凯特（Thandie Newton 饰）再次回到小镇，这让诺比特看到新的希望……本片获2008年金酸梅奖最差男主角、最差男配角、最差女配角奖（均为Eddie Murphy）2010年金酸梅奖十年最差男主角奖（Eddie Murphy）。', '艾迪·墨菲', '布莱恩·罗宾斯', 5.7, 5773, 'tt0477051', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536341407.jpg', 8.1, 24.2, 46.8, 14.9, 6, '0.157808,-0.135251,-0.331380,0.204205,-0.141947,-0.126343,0.635337,0.223341,-0.390660,0.078114,0.364148,0.991815,-0.183483,0.233001,0.330142,0.067785,-0.276081,-0.556750,-0.428186,-0.043322,-0.095986,-0.259851,-0.124626,0.129674,-0.157398,-0.421272,0.479866,-0.367030,0.280903,0.186468,0.386383,0.299170,-0.015667,-0.070124,-0.265784,0.224177,0.279566,-0.136298,-0.293539,0.100241,-0.236990,0.223507,-0.144433,0.271800,0.097411,0.012211,0.640480,-0.512629,-0.130918,-0.198421,0.725334,-0.081500,-0.097377,0.076736,0.131273,-0.246076,0.315403,0.124234,0.052499,0.070249,0.396535,-0.088765,-0.967183,0.188478,0.216214,-0.064739,-0.508098,0.355375,0.227239,0.143945,0.084354,-0.042988,-0.085853,0.117699,0.203257,0.440678,-0.049725,0.274444,-0.229807,0.310804,0.622436,0.066932,-0.508279,0.162689,-0.363638,-0.346946,0.060278,-0.366327,-0.674027,0.090476,0.524766,-0.068773,0.100997,0.324556,-0.462981,-0.032049,-0.200696,-0.238836,0.118121,-0.005194,-0.537809,-0.445262,0.135475,-0.392917,-0.389315,-0.068381,0.164128,-0.229539,0.888693,-0.733869,0.249817,0.559834,0.224645,-0.210191,0.556341,-0.045553,0.157263,-0.370921,-0.238927,0.389892,0.013841,-0.322388,0.176790,0.151216,-0.044023,-0.249750,-0.231392,0.736122', '27602116', '2