INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1929441', '戴夫号飞船', '喜剧', '身着一身白西装的戴夫（艾迪·墨菲 Eddie Murphy 饰）看起来是个彬彬有礼的中年人，虽然身处现代纽约的他总显得和这个年代、这个大都市格格不入，但谁能想到，这个看起来非常真实的“人”其实是一架人形飞船，身体里住着许多四分之一英寸高的外星小人，他们来到地球，想寻求解救自己星球的方法，不料却先在让飞船适应地球生活上经受了极大的考验，惹了一堆麻烦之后，谁想到飞船竟然自主爱上了一个美丽的地球女人吉娜（伊丽莎白·班克斯 Elizabeth Banks 饰），外星小人们偏轨的航线越来越难调正……©豆瓣', '艾迪·墨菲', '布莱恩·罗宾斯', 6.8, 11997, 'tt0765476', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453485563.jpg', 1.2, 7.7, 50.4, 30.9, 9.9, '0.262595,0.382631,-0.770584,0.518637,-0.549369,-0.033145,0.769110,-0.015671,-0.556063,-0.156392,0.117819,0.909493,-0.147127,0.146787,0.104987,0.395064,-0.338144,-0.048720,0.062945,-0.086772,-0.568123,-0.351482,-0.526895,-0.209885,-0.152715,-0.250901,0.503621,0.235576,-0.002146,0.193587,0.112553,0.091455,0.096578,0.456837,-0.585269,-0.229604,-0.042341,0.063160,0.316319,0.075723,-0.110638,0.133359,0.090230,0.363907,-0.239430,0.165517,0.506045,-0.210125,-0.337391,-0.061585,0.416602,-0.114337,-0.107183,-0.011038,0.243862,-0.299418,-0.105474,-0.452998,-0.102820,0.072642,0.337031,0.021346,-0.501557,0.347058,-0.092203,0.133487,-0.436836,0.130278,-0.209348,-0.313194,-0.293492,-0.296515,0.120658,0.259098,0.343663,0.297859,-0.165822,0.070753,-0.682764,-0.049287,0.546804,0.374880,-0.633714,0.389158,-0.415919,-0.379856,-0.385946,-0.241706,-0.519023,-0.166213,0.106252,-0.275399,-0.327825,-0.013155,-0.796067,0.453594,-0.385636,-0.167760,-0.212385,-0.304677,-0.308252,-0.341277,-0.152789,-0.655901,-0.196736,0.160523,0.167194,-0.173576,0.712520,-0.787948,-0.003043,0.545970,0.245620,-0.411498,0.429498,0.084500,0.005933,-0.298005,-0.253244,0.254812,-0.115391,0.255899,-0.289943,0.609636,-0.056595,-0.174940,-0.509466,0.533341', '1481233', '1292062', '30162520', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1929443', '的士速递4', '喜剧', '故事围绕由比萨快递员转职为计程车司机的丹尼尔（萨米•纳塞利 饰）和英俊但迷糊的马赛警察埃米利安（弗雷德里克•迪方多 饰）展开。丹尼尔驾驶技术高超，他所开的计程车经特别改良，时常在马路上风驰超速，在改装的出租车的帮助下多次协助老出纰漏的马赛警察侦破案件；警察埃米利安是丹尼尔的好朋友，英俊的他有时有点迷糊老干傻事儿。经常需要丹尼尔来帮他收拾烂摊子。埃米利安和他的马赛警察们接受到了一项重要的任务一一看守被押送过境的比利时籍恐怖分子头目 24小时。高人但不威猛的马赛警察局长吉贝尔部署下了“天罗地网”，没想到还没出机场就差点把犯人弄丢了，搞得军方大为火光；而埃米利安的美丽动人的辣妹女友蓓塔则接到了另一项卧底任务，两个人刚刚开始的假期又不得不分开……恐怖组织为了营救他们的头目，在马赛精心设计了一连串的袭击。而法国政府似乎对此也有所准备。一场精心谋划的连环局开始了，螳螂捕蝉，黄雀在后。但究竟谁是黄雀呢?', '萨米·纳塞利', '热拉尔·克瓦兹克', 7.1, 34908, 'tt0804540', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p903648927.jpg', 1.1, 6.4, 42.6, 35.8, 14.1, '0.451078,-0.178609,-0.491771,0.379574,-0.232919,-0.255062,0.214548,0.008121,-0.538478,-0.327701,0.341841,0.441541,-0.102761,-0.126738,0.504423,0.076562,-0.493166,-0.404123,0.062267,-0.015241,-0.490403,-0.563875,-0.204410,-0.378738,0.091939,-0.197019,0.053863,0.039338,0.256766,0.214855,0.252634,0.098170,-0.057157,0.279962,-0.209280,0.162576,0.220812,-0.293805,-0.025168,0.121196,0.057124,-0.283884,-0.264340,0.004374,0.081886,0.574054,0.499452,0.120111,-0.042224,-0.074002,0.166128,-0.363262,0.051810,-0.099945,0.332616,0.083449,0.100342,-0.031637,-0.150281,-0.153344,0.096739,0.075217,-0.501222,0.230729,-0.046376,-0.200353,-0.554232,0.249006,-0.373524,0.285239,0.127175,-0.293184,0.125165,0.360361,0.196751,0.320883,0.122798,0.029200,-0.565093,0.189081,0.546244,0.024681,-0.050652,0.215502,-0.083682,-0.356395,-0.033706,-0.288804,-0.250580,-0.085479,0.433058,-0.315004,-0.076805,-0.159690,-0.355248,-0.070556,-0.501605,-0.210830,-0.307332,-0.370898,-0.149910,-0.731874,0.111791,-0.136907,-0.118723,0.250118,0.076304,0.133021,0.501052,-0.719125,0.057236,0.663449,-0.069348,-0.435783,0.302903,0.246612,0.088837,-0.202944,-0.224229,-0.250002,0.358535,0.381042,0.307473,0.493215,-0.098770,-0.466894,-0.243043,0.037724', '3178770', '1292829', '1307442', '3282396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1929461', '只要在一起', '剧情', '人生中总是充满意外的相遇。爱画画的孤独女生卡蜜伊（奥黛丽•塔图饰），落寞贵族菲利贝尔(Laurent Stocker饰)以及生活邋遢的帅气厨师弗朗克（吉约姆•卡内饰)，本是巴黎街头的陌生人。一次偶然，却让他们开始了同室而居的生活。起初的生活，有争吵，也有烦乱。但在相互磨合的过程中，三个人各自讲述着自己的苦恼，也渐渐成为互相的支撑。卡蜜伊不再孤零零一个人，菲利贝尔战胜自己，克服了口吃的毛病，而弗朗克关于祖母的烦闷也一点一滴的由女孩的细心而化解。他们，在巴黎的夜晚，上演温情。同时，也有闪烁在我们眼中的些许火花，名字叫做爱情。©豆瓣', '奥黛丽·塔图', '克洛德·贝里', 7.7, 24055, 'tt0792965', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1849794439.jpg', 0.2, 1.9, 30.7, 48.7, 18.6, '0.349184,-0.144702,-0.673646,0.553275,-0.114479,-0.390782,1.059628,0.215539,-0.370048,-0.165908,0.267947,0.718204,-0.102140,0.586999,0.314373,-0.134890,-0.356333,-0.656090,0.218595,-0.051360,-0.110984,-0.496098,-0.084981,-0.611606,-0.067668,-0.418807,0.629610,0.243624,0.003236,0.490696,0.177122,0.242461,-0.236307,0.782550,-0.159896,-0.071798,0.149938,0.156669,0.017615,-0.183734,0.037267,-0.202222,-0.209716,0.165912,0.040227,0.433990,0.805075,-0.293387,-0.008954,0.131930,0.257779,-0.001745,0.038483,-0.052462,-0.060438,-0.114146,0.219310,-0.097113,-0.105714,-0.224085,-0.177140,-0.008103,-0.564312,-0.025878,0.134999,0.277702,-0.496113,0.820768,0.174670,-0.282379,0.256611,-0.009197,0.201745,0.321976,0.571623,0.386619,-0.126496,-0.135618,-0.339180,0.152035,0.592936,0.137146,-0.443595,0.517126,-0.751388,-0.254480,-0.008896,-0.121892,-0.538368,-0.296186,0.254967,-0.067646,-0.082220,0.498802,-0.710931,0.289989,-0.003989,-0.047886,0.028318,-0.528223,-0.116763,-0.606556,-0.219056,-0.535189,-0.455596,-0.054243,-0.000030,-0.255870,0.736212,-0.991327,0.286230,0.539546,0.186372,-0.159979,0.685512,0.048994,0.182768,-0.188268,-0.316059,0.633692,-0.147739,-0.050635,0.126412,0.503473,-0.185389,0.522010,-0.354225,0.704058', '1309172', '1292062', '1304989', '3059036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1929463', '少年派的奇幻漂流', '剧情', '故事开始于蒙特娄，也结束于蒙特娄。一名在找寻灵感的作家（拉菲·斯波 Rafe Spall 饰）无意间得知派·帕帖尔（伊尔凡·可汗 Irrfan Khan 饰）的传奇故事。派的父亲（阿迪勒·侯赛因 Adil Hussain 饰）开了一家动物园。因这样特殊的生活环境，少年派（苏拉·沙玛 Suraj Sharma 饰 ）对信仰与人的本性自有一套看法。在派17岁那一年，他的父母决定举家移民加拿大以追求更好的生活，而他也必须离开他的初恋情人。在前往加拿大的船上，他们遇见一位残忍成性的法国厨师（杰拉尔·德帕迪约 Gérard Depardieu 饰）。当天深夜在茫茫大海中，原本令派感到刺激无比的暴风雨一瞬间就成了吞噬货船的大灾难。派却奇迹般地活了下来，搭着救生船在太平洋上漂流，而且有一名最令人意想不到的同伴——理查德·帕克，一只孟加拉老虎。神奇的冒险旅程就这样意外开始了……', '苏拉·沙玛', '李安', 9.1, 1273086, 'tt0454876', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1784592701.jpg', 0.2, 0.4, 6.4, 31.6, 61.4, '0.273749,-0.020741,-0.607214,0.690607,-0.164185,-0.281315,0.692787,0.146263,-0.500997,-0.290043,0.155921,0.969996,-0.027758,0.277518,0.532406,-0.034471,-0.211038,-0.308945,-0.021280,-0.153633,-0.206175,-0.273432,-0.381094,-0.215729,0.123139,-0.428468,0.566965,0.169574,-0.153330,0.555900,0.156822,0.425047,-0.034027,0.379317,-0.404595,-0.155764,0.181866,0.192748,-0.202775,0.226098,-0.203623,-0.308992,0.033323,0.159455,-0.176779,0.277117,0.737562,-0.259241,-0.153693,-0.036797,0.304198,-0.230153,-0.042431,-0.082392,0.411585,0.001675,-0.038769,0.177494,-0.209941,0.042314,0.006698,-0.050819,-0.543678,0.109075,-0.020432,0.155220,-0.581020,0.249559,-0.106474,-0.025557,0.013705,-0.537847,0.183056,0.522932,0.048815,0.329506,-0.061774,-0.054308,-0.529949,0.312848,0.900817,-0.274399,-0.105333,0.277610,-0.116604,-0.462118,0.214020,-0.281963,-0.291368,-0.098291,0.372875,-0.240568,-0.241600,0.188492,-0.621686,0.144475,-0.221802,-0.302902,-0.006839,-0.282621,-0.035841,-0.615331,0.019591,-0.263206,-0.275107,0.064796,0.258796,-0.033077,0.616029,-0.577586,0.358396,0.680569,0.039406,-0.450692,0.629694,0.083669,0.023714,-0.269021,0.017079,0.379129,0.005003,0.331251,-0.037951,0.304778,-0.081159,-0.091722,-0.395719,0.490993', '30162520', '25721544', '34461680', '27042738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1930829', '五福星撞鬼', '喜剧', '鹧鸪菜（洪金宝 饰）、花旗参（秦祥林 饰）、犀牛皮（冯淬帆 饰）、大生地（吴耀汉 饰）和罗汉果（曾志伟 饰）这五个好友近来倍感无聊，他们各自吹牛外出沟女，结果一无所获。无聊至极之时，五福星相约前往离岛旅游。一路上麻烦不断，几人却乐在其中。正当夜晚几人玩耍取乐时，却听到隔壁无人豪宅中传来奇怪声音。大生地和鹧鸪菜冒险前往，结果发现一男一女两鬼。次日，众人向霸王花（胡慧中 饰）报警，胡虽不相信五福星的说法，还是派出梁来娣等四位美艳女警前去侦查。他们原打算在鬼屋捉弄四位女警，结果反致梁被男鬼（陈百祥 饰）上身。男鬼生前被人残忍杀害，由此失去心爱的恋人，死后更被贪婪女鬼所困。五位好友决心帮他完成心愿……©豆瓣', '洪金宝', '洪金宝', 6.5, 8269, 'tt0103290', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350127192.jpg', 1.7, 11.9, 56, 21, 9.3, '0.085768,-0.074755,-0.817920,0.198449,0.005541,-0.027313,0.709234,0.166264,-0.490533,-0.365305,-0.072708,0.497284,-0.385605,0.159508,0.287560,-0.234801,-0.190584,-0.371803,-0.031611,-0.020955,-0.047521,-0.076836,0.007432,-0.209792,-0.140064,0.005042,0.233197,0.293338,-0.104084,0.691579,0.513620,0.433718,-0.526840,0.363266,-0.104832,-0.008881,0.145659,0.112785,0.104782,0.087320,-0.039615,-0.160437,-0.282900,0.033908,-0.074081,0.320547,0.604670,-0.140175,-0.171767,-0.177189,-0.144763,-0.086353,0.108580,0.168979,0.142125,-0.090655,0.482262,0.010677,-0.100011,0.126461,0.187269,-0.016424,-0.347195,0.393624,0.219106,-0.039365,-0.326284,0.020424,-0.230286,-0.047837,0.050223,-0.310259,0.134662,0.168313,0.266157,0.294100,-0.026763,0.012047,-0.336859,0.118749,0.588947,0.185590,0.289650,0.038899,0.253822,-0.265369,0.086914,0.035160,-0.248900,0.031588,0.467251,0.163914,0.112235,-0.251871,-0.545884,-0.058519,-0.248334,0.229220,-0.156832,-0.149177,-0.005793,-0.816937,0.239954,-0.199708,-0.213958,0.258419,0.198795,-0.177772,0.521441,-0.376882,0.052231,0.171821,0.227896,-0.630543,0.578333,0.172812,0.160135,-0.410184,-0.008197,-0.048936,0.259276,0.134895,0.352346,0.126534,-0.294295,-0.148083,-0.504202,-0.273431', '10466639', '3011051', '3147969', '3267195');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1935146', '花神咖啡馆的情人们', '剧情', '故事发生在1929年，波伏娃（安娜·莫格拉莉丝 Anna Mouglalis 饰）遇见了改变她一生命运的男人萨特（洛兰特·道驰 Lorànt Deutsch 饰），相同的理念令两人走到了一起。然而，生性风流的萨特却并不愿意为了波伏娃而放弃他“自由”的生活，即便已经同波伏娃确定了关系，但他依然公开和诸多伴侣来往，他和波伏娃早已达成共识——这些伴侣的存在并不会破坏他们之间的爱情，正相反，没有了束缚，他们反而因此获得了真正的爱情。尽管波伏娃也有着自己的情人，但她却无法走出身为女人的桎梏，独占欲和嫉妒令她只能在黑夜里独自哭泣，她和萨特之间的“契约婚姻”在给她带来灵感和荣誉的同时，亦变成了她一辈子都绕不出的迷宫。©豆瓣', '安娜·穆格拉利斯', '伊兰·迪朗·科昂', 7.5, 9878, 'tt0778611', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1646650035.jpg', 0.8, 4.3, 33.6, 43.9, 17.3, '0.556152,0.108942,-0.805674,0.772595,-0.125988,-0.353150,0.974194,0.136775,-0.531661,-0.193038,-0.065459,0.817419,0.076614,0.116839,0.170171,-0.047732,-0.292874,-0.785130,0.287953,-0.284709,-0.210750,-0.678992,-0.194699,-0.197521,-0.321831,-0.232704,0.890081,0.001871,-0.210101,0.354702,0.309759,0.218178,-0.162159,0.747161,-0.135814,0.005699,0.032775,0.276019,-0.342094,0.075265,0.022191,-0.016057,-0.198228,0.330222,-0.192989,0.285149,0.351792,-0.763521,-0.071873,0.158188,0.192968,-0.365336,0.155941,0.122121,-0.127048,-0.306756,0.193673,0.614399,-0.145116,0.109413,0.273255,0.139706,-0.820524,0.116393,0.143143,0.205769,-0.571295,0.759625,0.069854,-0.184704,-0.038960,-0.257047,0.104945,0.293900,0.431176,0.270553,-0.421910,-0.065339,-0.879843,-0.091172,1.035510,0.191714,-0.382262,0.410976,-0.602082,-0.466123,-0.465873,-0.284288,-0.575329,-0.160929,0.252713,0.498180,-0.367819,0.506836,-0.596747,0.038224,-0.205862,-0.014508,0.064573,-0.748155,0.357772,-0.387156,-0.293147,-0.766647,-0.499576,0.132515,0.074436,-0.554771,0.592666,-1.027758,0.265807,0.430223,0.443763,-0.780576,0.930416,0.355230,0.142950,-0.199701,0.042162,0.721567,-0.087758,0.194600,0.204747,0.136314,0.337276,0.266177,-0.261643,0.773607', '25721544', '1308755', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937132', '寿喜烧西部片', '动作', '源平坛浦决战结束后，平家一支逃到深山之中，建立汤田村。从此数百年不曾出山，过着隐居世外的桃源生活。然而，他们的平静生活被接二连三的外来者打破，俗世盛传汤田村埋藏着可供平家东山再起的金银财宝，遂引得贪婪凶残之徒云集于此。不久，平家后裔平清盛（佐藤浩市 饰）携部众前来，赶走寻宝之徒。但平清盛绝非善良之辈，他用更为残酷的手段逼迫当地族人供出藏宝地点，为此不惜杀害无辜之人。未过多久，平家死对头源义经（伊势谷友介 饰）率人马来至此地，双方为了争夺财宝展开连番混战，致使当地民众难以生活，纷纷逃离。神秘独行枪手（伊藤英明 饰）的到来打破平源双方的平衡，汤田村变得愈加动荡不安……本片荣获2008年亚洲奇幻电影节最佳影片第二名、2008年每日电影最佳艺术指导和最佳技术奖。©豆瓣', '伊藤英明', '三池崇史', 7.1, 5887, 'tt0906665', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1076913118.jpg', 2.2, 8.1, 38.9, 36.6, 14.2, '-0.109733,0.096815,-0.620963,0.471052,0.146563,0.029450,0.261681,-0.092709,-0.732429,-0.230711,0.159052,0.506463,-0.048653,-0.028292,0.350057,-0.340291,-0.142546,-0.536086,-0.218983,-0.334193,0.184065,-0.074135,-0.282299,-0.176966,-0.338253,-0.318671,0.708410,0.506228,-0.144582,0.534607,0.034697,0.474301,-0.296929,0.232073,-0.057750,-0.162959,-0.180276,-0.020962,-0.546820,0.193482,-0.575659,-0.524915,-0.543104,-0.008941,-0.022029,0.223532,0.565636,-0.410323,-0.060241,-0.322558,0.244760,-0.383130,-0.325693,0.121966,0.436801,0.007528,0.195656,0.447580,-0.166443,0.237636,-0.026007,-0.285216,-0.533211,-0.030059,0.098482,0.043258,-0.304170,0.346173,0.218061,0.031129,-0.226427,-0.222875,0.056414,0.390617,0.597650,-0.102815,0.068236,-0.042122,-0.289962,0.249097,0.842618,-0.236848,-0.083337,-0.134118,0.061633,-0.522150,0.121070,-0.806067,-0.548725,-0.192385,0.328874,-0.030340,0.106495,0.505088,-0.559981,-0.035636,-0.263930,-0.017433,0.334481,-0.016277,-0.131936,-0.803269,-0.041867,-0.172553,-0.121587,0.093919,0.074013,-0.230149,0.692436,-0.604743,0.179405,0.358220,0.187181,-0.496269,0.293840,-0.171594,0.091330,0.120815,-0.245414,0.414740,0.228246,0.396496,-0.042394,-0.211534,-0.362916,-0.002375,-0.114679,0.106670', '1306998', '6007281', '25983044', '3230460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937257', '微不足道', '喜剧', '博士查理（大卫•休默 David Schwimmer 饰）最近遇到了麻烦。不仅丢掉了大学里的工作，自己写的书也出版无望。为了不成为家里的负担，查理找到了份电话销售的工作，在那里认识了自来熟的同事加斯（西蒙•佩吉 Simon Pegg 饰）。加斯告诉了查理他的计划，即敲诈一位经常浏览色情网站的牧师。为了让家人过上富足的生活，查理答应加入，再加上加斯一夜情的女友朱茜（爱丽丝•伊芙 Alice Eve 饰），三人开始了这个计划。看似简单的计划，却弄巧成拙的愈发偏离最初的目的。越来越多的人被卷进其中，事情越弄越大。而且，糟糕的是，查理发现加斯和朱茜的背后似乎掩藏着不可告人的秘密，危险也在逐步逼近查理，究竟结局会怎样……©豆瓣', '大卫·休默', '让-巴普蒂斯特·安德烈', 8.2, 54014, 'tt0488085', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1517352664.jpg', 0.2, 1.3, 17.3, 51.7, 29.4, '0.535273,-0.110446,-0.580943,0.447013,-0.100248,-0.302884,0.369368,0.105620,-0.484248,-0.292476,-0.038839,0.650452,-0.125457,-0.121456,0.333233,0.119367,-0.439757,-0.484780,0.399368,-0.169330,-0.101076,-0.738062,-0.377974,-0.349438,0.048597,-0.302967,0.396913,0.015002,-0.186858,0.214136,0.220038,0.360865,0.081774,0.429124,0.164707,0.201218,0.293394,-0.088473,-0.280737,0.216698,0.263749,-0.133358,-0.071693,0.249219,0.263636,0.435389,0.462236,0.065354,-0.443819,0.159626,0.420300,-0.215679,-0.075171,0.010327,0.317900,-0.005842,0.308797,0.365243,-0.315132,0.118490,0.008717,-0.003591,-0.695725,0.292591,0.268230,0.378381,-0.473561,0.180062,-0.300119,-0.097836,0.197193,-0.276015,0.211423,0.629153,0.271672,0.192545,-0.057825,-0.033869,-0.630452,0.100079,0.479884,-0.063459,0.195028,0.138232,-0.072441,-0.265912,-0.086069,-0.066172,-0.328769,-0.012638,0.499401,0.024614,-0.348310,0.359852,-0.543711,-0.022153,-0.230341,-0.198154,-0.088673,-0.465711,-0.228696,-0.326186,-0.138560,-0.300582,-0.401357,-0.222262,-0.035211,-0.331032,0.567535,-0.764767,0.225170,0.584425,0.322998,-0.392806,0.253271,0.431479,0.096048,-0.268177,-0.170548,0.021859,-0.109073,0.252266,0.247033,0.150730,0.301989,-0.735276,-0.331625,0.606434', '1307442', '1986338', '1298299', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937400', '美国派(番外篇)5：裸奔', '喜剧', '艾瑞克（John White 饰）算得上是一个标准的失意青年了，连在家中打个手统也造成祖母受惊去世的恶果。艾瑞克与女友翠西交往两年，但一直未能上垒，现在已是全校最后的处男、公认的笑柄，这些还不算，他是大名鼎鼎的“硬条”家族的一员，堂兄德维特等人名满江湖，给他巨大的心理压力。翠西终于同意与艾瑞克共赴巫山，岂料两人时运不济最后又发展成一场屎尿屁笑话，幸好德维特的学校要举办考后大裸奔活动，艾瑞克与死党匆匆投奔堂兄希望用狂欢宽慰心怀……经历了与侏儒橄榄球队的对决，裸奔活动的大幕即将揭开，然而关键时刻，艾瑞克忽然领悟了爱与性的意义，做出了自己的抉择。©豆瓣', '克里斯托弗·麦克唐纳', '乔·努斯鲍姆', 6.5, 23551, 'tt0808146', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1446499363.jpg', 2.2, 12, 53.8, 23.2, 8.7, '0.133644,-0.141665,-0.462184,0.464817,0.109853,-0.394960,0.522550,0.031489,-0.487921,-0.223631,0.093603,0.720109,-0.383139,0.282276,0.300887,-0.170004,-0.034658,-0.779341,0.094986,-0.091124,-0.174991,-0.347460,-0.180266,0.100532,-0.171063,-0.207736,0.605555,0.030054,-0.283748,0.385694,0.539158,0.105234,0.092112,0.380876,-0.313675,-0.048945,-0.068932,0.224479,-0.334746,0.166612,-0.055114,-0.245421,-0.079391,0.116660,0.022355,0.423813,0.432122,-0.276437,-0.208342,-0.265800,0.378561,-0.345639,-0.082252,0.228094,0.322406,-0.251374,0.308653,0.220857,0.164474,-0.236136,0.177655,-0.190995,-0.567158,0.047125,0.098009,-0.049806,-0.664675,0.745743,-0.083454,-0.189284,0.008929,-0.072215,0.263456,0.502452,0.199452,0.215438,-0.196291,-0.016697,-0.293447,0.138417,0.615476,-0.005254,-0.348933,0.327029,-0.034011,-0.387524,0.060374,-0.440324,-0.414313,0.164735,-0.009486,0.139429,-0.156397,0.183278,-0.482102,-0.065005,-0.306719,-0.127611,0.131116,-0.502232,0.024221,-0.434179,-0.243225,-0.396107,-0.390376,-0.082450,0.174169,-0.214318,0.620876,-0.724515,0.073950,0.326471,0.222812,-0.377452,0.701434,0.314749,0.193673,-0.188030,0.130798,-0.169549,-0.086643,0.066891,0.141258,0.331730,-0.004259,-0.159414,-0.258717,0.252629', '4202326', '4301278', '3212120', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937401', 'K歌情人', '喜剧', '阿莱克斯(休•格兰特 饰)是一个八十年代过气流行乐歌手，近年好不容易逐渐获得更多的演出机会，更得到流行天后Cora邀请他写歌并合唱该曲。但此刻阿莱克斯碰到了创作瓶颈，多年没有作曲之余，而且从来没有过作词的经验，现在却要在几天内作出一首畅销的流行曲。就在阿莱克斯十分烦恼时，他遇到了苏菲（德鲁•巴里摩尔 饰），这个美丽的女孩精通运用文字，随口唱出的歌词让阿莱克斯十分满意，多次邀请苏菲才答应与阿莱克斯一起合作。但苏菲一直困在前一段失败的感情中，她害怕承诺。当她与阿莱克斯的感情逐渐升温的时，两人却要一起面对分歧……©豆瓣', '休·格兰特', '马克·劳伦斯', 7.6, 97509, 'tt0758766', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p477610353.jpg', 0.2, 2.5, 33.6, 46.9, 16.8, '0.071354,0.009087,-0.749951,0.773435,-0.060943,-0.379308,0.973807,-0.060335,-0.718566,-0.224996,-0.158213,0.653917,-0.445018,0.258425,0.192145,-0.255676,-0.306102,-0.790097,0.418674,-0.081040,0.075084,-0.505111,-0.328062,0.102984,-0.431630,-0.252194,0.736155,-0.133265,-0.180229,0.499943,0.209509,-0.120259,0.213636,0.642099,0.017961,-0.036111,0.365159,0.270534,-0.202384,0.275378,0.153848,-0.022178,-0.392456,0.206870,0.052643,0.385047,0.285217,-0.156055,-0.100458,0.413645,0.623725,-0.026770,0.177240,-0.057432,0.297698,0.043336,0.722314,0.168958,-0.190673,0.048820,-0.343369,-0.237392,-0.846004,0.306974,0.153892,0.124735,-0.595188,0.394867,-0.116066,-0.142772,-0.233483,-0.458547,0.127586,0.342485,0.570129,0.136703,-0.246509,-0.141929,-0.137176,0.250480,0.744462,0.035199,-0.298293,0.498046,-0.289236,-0.607841,-0.197156,-0.009217,-0.399505,0.153819,0.095364,0.263504,-0.137355,0.118031,-0.445616,-0.089215,-0.290658,-0.135028,0.160774,-0.187484,0.132062,-0.661287,-0.257572,-0.252106,-0.190547,-0.257030,-0.030947,-0.395625,0.684563,-0.950555,0.329072,0.358014,0.292508,-0.192649,0.587365,0.518341,0.040975,0.051361,-0.048397,0.297460,-0.396406,-0.131291,0.242112,0.327566,0.426429,-0.223804,-0.335458,0.696528', '35030151', '1308755', '1301022', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937502', '追风筝的人', '剧情', '2000年美国加利福利亚，知名作家阿富汗人Amir(Khalid Abdalla 饰)接到一个电话，将他带回了童年的岁月……1978年阿富汗喀布尔，Amir（Zekiria Ebrahimi 饰）是富家少爷，仆人Ali的儿子Hassan（Ahmad Khan Mahmoodzada 饰）是 他忠实的跟班与玩伴。二人参加了一场传统的斗风筝比赛，Amir经历了终身难忘的事情，两人的命运随之改变：Ali和Hassan离开了Amir家，音信全无；随着阿富汗战争的爆发，Amir和父亲移民到美国，过上了新的生活。电话是父亲的老朋友Rahim（KhanShaun Toub 饰）打来的，希望Amir能够到阿富汗去找Hassan的儿子Sohrab (Ali Danish Bakhty Ari 饰)，等待Amir的，除了满目疮痍的家乡、不堪回首的往事，还有难以启齿的秘密。', '赫立德·阿卜杜拉', '马克·福斯特', 8.2, 160246, 'tt0419887', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p956325412.jpg', 0.4, 1.8, 17.4, 47.6, 32.8, '0.089761,-0.197060,-0.323422,0.556358,0.000628,-0.331674,0.618553,-0.061471,-0.708342,-0.275599,-0.190784,0.893659,0.058151,0.201972,0.506440,-0.143974,-0.257745,-0.981304,-0.126226,-0.129918,-0.213046,-0.429275,-0.200378,-0.295831,0.101764,-0.388458,0.384901,0.212501,0.076120,0.734194,0.173338,0.472277,-0.328683,0.209005,-0.391226,0.109325,-0.047160,0.400377,-0.679808,0.101752,0.122847,-0.180420,-0.101210,0.065567,0.221079,0.328297,0.525322,-0.151019,0.051369,-0.211192,0.203260,-0.169902,-0.221268,0.117554,0.348833,0.319707,0.180849,0.432594,-0.220019,-0.031184,0.147174,-0.293828,-0.404178,0.048393,0.139194,0.105997,-0.743135,0.696149,-0.103042,-0.096433,0.160644,-0.390332,0.437393,0.454500,0.038342,0.595354,-0.117954,0.155524,-0.419444,0.615229,0.994401,-0.173226,-0.063819,0.290482,0.001880,-0.322296,-0.018723,-0.416183,-0.606232,0.276297,0.288778,-0.144877,-0.213622,0.285642,-0.795159,-0.219070,-0.288025,-0.562481,0.431024,-0.561579,-0.145564,-0.417083,-0.444607,-0.471145,-0.276758,0.353562,0.102020,0.067442,0.821285,-0.905272,0.294748,0.516770,0.249465,-0.531623,0.725513,-0.034144,0.114857,-0.339465,0.468055,0.132567,-0.148362,0.241842,-0.135675,0.061337,-0.071780,-0.210129,-0.381743,0.328226', '35048413', '