INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937621', '杀手：代号47', '动作', '代号47（蒂莫西•奥利分特 饰）是一个利用基因技术制作的复制人，受雇于名为“The Agency”的组织进行刺杀活动，47是他颈背条码的最后两个数字，也是他的名字。因为卷入了政治阴谋，47在东欧遭到了国际刑警和俄国军队的双重追杀。在追查真凶的过程中，他遇上了一个致命的女人（欧嘉•克瑞兰蔻 饰）。杀手的冷酷无情渐渐被女人瓦解，但是生命也正在受到威胁……©豆瓣', '蒂莫西·奥利芬特', '泽维尔·吉恩斯', 7.2, 80129, 'tt0465494', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p725839995.jpg', 0.9, 5.5, 38.9, 39.4, 15.2, '0.097200,-0.161009,-0.492245,0.757843,-0.434752,0.155810,0.732747,0.162001,-0.525733,-0.112373,0.339132,0.649887,-0.038325,-0.314127,0.108253,-0.076601,0.015992,-0.710816,0.097504,-0.102572,-0.526316,-0.597593,-0.262295,-0.515644,0.107833,-0.618097,0.698771,0.009183,-0.684145,0.058207,0.351078,0.661870,-0.199690,0.614715,-0.120388,-0.162415,0.268456,-0.451077,0.084816,0.520430,-0.197863,-0.405043,0.095754,0.266560,-0.466024,0.597248,0.854220,-0.482892,0.038765,-0.342794,0.320134,-0.566171,-0.189703,0.030268,0.408230,-0.127513,0.047352,0.259304,-0.216490,-0.148348,0.316060,-0.036439,-1.274213,-0.206073,0.253488,0.133553,-0.639347,0.480488,-0.370810,0.049780,-0.061946,-0.204493,0.381476,0.431980,0.499843,0.171857,-0.166870,-0.148433,-0.568710,0.030429,0.420959,-0.076024,-0.518784,0.342428,-0.315436,-0.531556,-0.232834,-0.439107,-0.243677,-0.055153,0.270854,-0.116284,-0.285233,0.242486,-0.958572,0.084774,-0.289483,-0.360344,0.023400,-0.470027,-0.159923,-0.648792,-0.398720,-0.362865,-0.564944,0.187254,-0.029543,-0.196976,0.815250,-0.936271,0.222351,0.974288,0.216417,-0.522387,0.502774,0.154890,-0.017424,-0.159257,-0.105093,0.145839,0.446842,0.212733,0.145693,0.340314,0.029155,-0.108690,-0.143770,0.422199', '27009869', '1793491', '1308585', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1937946', '穿越时空的少女', '剧情', '17岁少女绀野真琴是一个活泼跳脱的少女。在一次普通值日工作中，真琴不小心摔倒了，自此她发现自己拥有了穿越时空的能力。她兴奋不已，掌握了穿越时空的方法后，她经常用这个方法去解决生活中许多令她困扰十分的事。喜欢棒球的真琴与同班的两名男生千昭与功介有着共同爱好。一天，与她本是好朋友的千昭突然向她表达爱意，手足无措了她再次穿越时空希望可以躲避这件事的发生。但没想到，千昭会跟同学友梨在一起了，而友梨也是一直喜欢千昭的。此时，暗恋功介的果穗误以为真琴是功介的女友。为了帮忙解决朋友的问题，真琴不断以同样的方法回到过去。她突然发现自己手臂上的数字原来是穿越时空的次数，次数变得越来越少，与此同时她也发现了千昭的秘密……©豆瓣', '仲里依纱', '细田守', 8.6, 360777, 'tt0808506', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2079334286.jpg', 0.2, 1, 12.2, 40.7, 45.9, '0.433615,-0.073964,-0.581739,0.441970,-0.278869,-0.041141,0.750906,-0.275827,-0.587709,-0.398671,-0.043771,0.729563,-0.036237,0.382403,0.281911,-0.008682,-0.110979,-0.835973,0.253863,-0.245253,-0.445795,-0.473624,-0.207004,-0.174256,-0.294958,-0.406274,0.592909,0.018169,-0.199026,0.443542,0.138027,0.262422,0.038914,0.607194,-0.080486,-0.111773,-0.146370,0.115875,0.046106,0.192765,0.154488,-0.336328,-0.229567,0.383343,-0.062725,0.444181,0.555548,-0.150855,-0.406340,0.029355,0.206446,-0.106495,-0.120397,0.066565,0.155042,0.025298,0.224529,-0.058969,-0.271110,0.015586,0.073500,-0.080600,-0.640438,0.036561,0.085318,0.214445,-0.572754,0.249407,-0.108147,-0.199438,0.230379,-0.546567,0.055878,0.282771,0.270683,0.307499,-0.473614,-0.023058,-0.377785,-0.001075,0.814930,0.190155,-0.152941,0.681427,-0.317875,-0.351984,-0.225977,-0.147303,-0.334189,0.138111,0.045347,0.254683,-0.227326,0.254854,-0.456366,-0.054171,-0.013896,-0.022510,-0.054638,-0.440642,-0.082165,-0.171759,-0.084430,-0.501294,-0.425470,0.005988,-0.090637,-0.576021,0.887259,-1.164672,0.050306,0.663629,0.457953,-0.264196,0.641875,0.135231,-0.039997,-0.219207,-0.011979,-0.086198,-0.091927,0.153213,0.076937,0.449437,0.215799,-0.103715,-0.600862,0.468357', '35030151', '1395231', '1297052', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1938312', '刺青', '剧情', '小绿（杨丞琳饰）是个网络视讯女郎，作风大胆前卫。她在一间刺青店里认识了小竹（梁洛施饰），她所开的刺青店是为了纪念她的父亲。小竹的弟弟因为目睹自己父亲于地震中死去，身心受到了极大的创伤，小竹深明是自己当年为了与情人见面而丢下了弟弟，以至悲剧的发生。因此面对小绿的强烈爱情的暗示，就算她也同样爱上了小绿，她也无法抛开自己深深的罪恶感，面对感情。手臂上的刺青成了她永远的伤。小绿对小竹的爱恋原来早就在她小时候开始，失去真挚亲情的她，早早对小竹倾注了所有的感情。竹子的决定该如何呢？亲情与爱情的较量，该如何才能做到两全其美呢？©豆瓣', '梁洛施', '周美玲', 6, 56873, 'tt0891457', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486639599.jpg', 4.6, 21, 50.9, 17.6, 6, '0.177549,0.101401,-0.687334,0.478003,-0.325676,-0.190248,0.750141,-0.028948,-0.503072,-0.091178,0.373243,0.778375,0.022425,0.373806,-0.087504,0.089860,0.091714,-0.802185,0.038028,-0.017381,-0.363464,-0.389113,-0.216414,-0.061349,-0.065533,-0.115294,0.519360,0.105872,-0.140267,0.036299,0.532597,0.317803,0.078294,0.434050,-0.066918,0.123010,-0.302692,0.102281,-0.367307,-0.204270,0.305308,-0.188894,0.139257,0.363414,-0.191825,0.137803,0.717312,-0.308277,-0.397447,-0.154256,0.423934,-0.198760,0.156746,0.361706,-0.034628,-0.030095,0.221353,0.159691,-0.250188,-0.142303,0.204174,0.062417,-0.753692,-0.085177,0.089811,0.100282,-0.594034,0.632476,-0.081389,-0.148556,0.168482,-0.384150,0.104111,0.229228,0.277894,0.395579,-0.485758,-0.201511,-0.298155,0.112132,0.839368,0.095779,-0.085657,0.572917,-0.487865,-0.185941,-0.104676,-0.371030,-0.419856,0.131460,0.201863,0.222061,-0.407287,0.302742,-0.366132,-0.112943,-0.076007,-0.034508,0.087174,-0.688395,0.062924,-0.044726,-0.446205,-0.704860,-0.481625,-0.057160,0.195702,-0.362908,0.708424,-1.078738,0.208252,0.395866,0.232092,-0.760338,0.511538,0.217239,-0.148344,-0.143390,0.047029,0.496315,-0.278274,0.012803,0.212139,0.137178,0.262120,0.237384,-0.287884,0.646179', '1301022', '30345227', '35030151', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1938923', '疯狂的兔子', '科幻', '未来某城市，艺校姑娘然然（柳田 饰）常带邻家小孩豆豆（赵梦洋 饰）玩耍，不料在一起偶然事件中豆豆丢失，她焦急万分。此时，城市上空降临UFO，宇航局安全处派出的特工莫名其妙失去了记忆。局长（王鹰 饰）让侦察员叶云（李艺 饰）观看监视录像，录像中似有一个类似豆豆的身影出现，但很快便消失了。与此同时，班上来了一个酷似豆豆的学生李大米，他随身携带一个神奇的游戏光盘，如果谁玩光盘大喊“神奇的兔子”，不可思议的事情发生了，兔子竟然跳到人的身上，兔形浸入人的衣服和皮肤，而人也变的疯狂暴唳。然然因拒绝玩此游戏，疯狂的兔子弄坏了她的乐器。原来，西伯尔星球科学家劫持了豆豆并改变了其大脑，改名换姓派回地球作恶......©豆瓣', '柳田', '崔小芹', 6.7, 12532, 'tt6676134', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230918667.jpg', 5.9, 9.9, 41.8, 27.9, 14.5, '0.310101,0.016555,-0.637381,0.247687,-0.124573,-0.051325,0.688735,0.109550,-0.454281,-0.103834,0.251720,0.414879,-0.205831,0.036901,-0.042379,0.241882,-0.308901,-0.535644,0.048740,-0.126078,-0.430775,-0.042379,-0.141639,-0.271614,0.256312,-0.282222,0.263542,-0.130120,-0.113359,0.642665,0.005267,-0.085391,-0.384750,0.523847,0.030541,0.218621,0.124890,0.255156,0.232127,0.101871,-0.067825,-0.052377,0.188993,0.056036,-0.097414,0.157745,0.708392,-0.215391,-0.177230,-0.294322,0.223989,-0.116181,-0.180060,-0.107877,0.268627,0.137762,0.110048,-0.426110,-0.189306,0.012899,0.206766,0.074304,-0.270311,0.072630,0.106608,0.321815,-0.255724,0.074767,-0.109852,0.108690,0.164157,-0.353386,0.251033,-0.037850,0.190417,0.250121,-0.005814,0.120067,-0.414108,0.273013,0.192403,-0.173966,-0.137645,0.076770,-0.128790,-0.229477,0.123091,0.072795,-0.301311,0.209397,0.376843,-0.158860,-0.372191,0.213550,-0.546916,0.140944,-0.125331,-0.041558,-0.174798,-0.318158,-0.413558,-0.368108,-0.006022,-0.078823,-0.174985,0.050343,-0.043574,-0.093123,0.741848,-0.582534,0.268770,0.556751,0.195029,-0.200390,0.414528,-0.431423,-0.071015,-0.304358,0.054405,0.087061,0.179434,0.419636,0.053826,0.296530,-0.141056,-0.085936,-0.414338,0.260296', '1307146', '3005387', '3811356', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1939173', '破绽', '剧情', '由于妻子出轨，特德（安东尼•霍普金斯 Anthony Hopkins 饰）冷静地将她射杀了，他的完美杀人计划开始了。当警方接报前来现场时，警官罗布发现特德的妻子正是自己的情人珍妮佛。伤重但还没身亡的珍妮佛成了一具植物人，让人吃惊的是特德欣然承认了罪行。年轻的公诉律师威 利（瑞恩•高斯林 Ryan Gosling 饰）觉得此案极容易获胜，希望凭借此案让自己进入经济庭和在女友面前威风一把。然而事件并没有这么简单，老奸巨猾的特德放弃使用辩护律师，由他自己亲自应诉。虽然每个人都知道特德犯了罪，但由于他在法庭上的“完美”表现和充分利用制度上的形式公平而合理合法地逃脱了法律的制裁！威利若想将犯人绳之以法，只有去抓住每一点的――破绽。©豆瓣', '安东尼·霍普金斯', '格里高利·霍布里特', 7.3, 43050, 'tt0488120', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p572433210.jpg', 0.5, 3.6, 37.2, 46.2, 12.5, '0.316482,0.157457,-0.689202,0.463760,-0.306855,-0.218899,0.664886,0.145226,-0.462464,-0.223927,0.205070,0.690311,-0.049855,-0.034057,0.138696,0.078412,-0.404541,-0.821914,-0.019903,-0.101022,-0.259288,-0.720071,-0.157487,-0.332541,-0.090684,-0.336992,0.530507,-0.034542,-0.170732,0.357297,0.366426,0.208279,0.310866,0.680954,-0.164393,-0.024881,-0.064500,-0.154033,-0.334822,0.255653,0.190833,-0.316113,-0.149152,0.474569,-0.060818,0.579708,0.519063,-0.471242,-0.370788,0.046938,0.527403,-0.607402,0.093476,0.364673,0.202501,-0.052903,0.023422,0.272326,-0.300446,0.021052,0.341168,-0.067575,-0.991143,-0.092611,0.018484,0.164340,-0.606661,0.333981,-0.472002,0.165400,-0.080364,-0.284655,0.158206,0.132087,0.116054,0.210050,-0.149574,-0.129506,-0.555296,-0.007833,0.514305,0.028979,-0.423136,0.072455,-0.291621,-0.723659,-0.179965,-0.482062,-0.154499,0.005452,0.177880,0.085450,-0.180246,-0.052810,-0.271467,-0.166572,-0.460776,0.094003,-0.386187,-0.450011,-0.002754,-0.341906,-0.031652,-0.166697,-0.632566,-0.129113,-0.111691,-0.516710,0.415679,-0.675599,0.072443,0.535117,0.357499,-0.421338,0.642216,0.304769,0.006401,-0.177563,-0.312121,-0.081712,0.369175,0.316593,0.481933,0.394806,0.105735,-0.220460,-0.125777,0.396667', '1295318', '25862560', '1307442', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1939414', '功夫之王', '动作', '杰森（Michael Angarano 饰）是一个疯狂迷恋港台功夫片的美国少年，然而现实中的他却饱受坏孩子的欺负，不敢反抗。偶然机会，节森从某中国古董店得到一根如意金箍棒，借着金箍棒的力量，他竟然回到了几千年前的中国。此时，邪恶的玉疆战神（邹兆龙 饰）凭借降伏齐天大圣孙悟空（李连杰 饰）的威名篡夺天界，靠武力鱼肉百姓，民不聊生。杰森先后邂逅了嗜酒的游侠鲁彦（成龙 饰）、沉默寡言的默僧（李连杰 饰）以及轻盈美丽的金燕子（刘亦菲 饰）。他们为解救被困的齐天大圣朝着天界进发……©豆瓣', '迈克尔·安格拉诺', '罗伯·明可夫', 5.7, 177189, 'tt0865556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p887405912.jpg', 6.5, 25.2, 49.3, 13.6, 5.4, '0.199466,0.273582,-0.663651,0.621724,-0.134684,-0.255440,0.535417,0.109407,-0.441359,-0.075827,0.369028,0.602317,0.024939,0.061584,-0.080346,0.083919,0.088137,-0.627304,0.014021,0.174661,0.119447,0.086487,-0.610693,0.001937,-0.222604,-0.144427,0.572406,0.000694,-0.215798,0.499887,0.246113,0.255264,-0.110262,0.064842,-0.367217,0.099181,-0.120412,0.235880,-0.198697,0.342961,-0.184367,-0.345543,-0.044340,0.260262,-0.438347,0.216833,0.366675,-0.545427,0.073954,-0.345145,0.534316,-0.104071,-0.351560,0.077437,0.089478,0.040046,0.108746,-0.074139,0.041250,0.199398,0.227285,-0.084173,-0.681454,0.017551,0.052596,0.174596,-0.444223,0.472227,-0.025049,0.012081,-0.009140,-0.291809,-0.012918,0.097430,0.313981,0.048555,-0.233867,0.126143,-0.399279,0.435970,0.353821,0.030304,-0.240963,0.208716,0.012340,-0.184857,-0.055562,-0.297704,-0.401218,-0.202069,0.425391,-0.181314,0.129523,0.207432,-0.580612,-0.015791,-0.219892,0.139232,-0.112495,0.053401,-0.185511,-0.511033,-0.182168,-0.416799,-0.088179,-0.028081,0.099773,0.040084,0.686496,-0.634234,0.208321,0.521570,0.138931,-0.186104,0.612141,-0.097239,-0.166069,-0.106149,-0.212621,0.564522,0.048597,0.228506,-0.024141,0.267316,-0.134168,-0.186710,-0.325886,0.463938', '25928048', '27602116', '1306795', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1939761', '极速赛车手', '动作', '影片改编自动画大师吉田龙夫(Tatsuo Yoshida)的经典系列动画作品。斯皮德·莱瑟（埃米尔·赫斯基 Emile Hirsch 饰）的父亲波普斯（约翰·古德曼 John Goodman 饰）是个汽车制造商，经营的公司已经相当有名气。在他的培养下，大儿子雷克斯成为世界顶级车手，然而，不幸的是雷克斯在一次比赛中失事过世。斯皮德在女友翠茜（克里斯蒂娜·里奇 Christina Ricci 饰）还有家人的支持下决定参加国际汽车大奖赛，并且找出哥哥死亡的真相。在比赛过程中，斯皮德结识了神秘赛车手莱瑟X（马修·福克斯 Matthew Fox 饰），以及同样为对抗罗伊尔顿的亚洲车手天速（郑智薰 饰）。在他们的帮助下，斯皮德开始接受这个可能会通向死亡的赛道的考验。在寻找哥哥死亡真相的过程中，斯皮德发现了让家人相当震惊的事实……©豆瓣', '埃米尔·赫斯基', '莉莉·沃卓斯基', 6.2, 8000, 'tt0811080', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1024619866.jpg', 5.9, 18.9, 44, 22.4, 8.7, '-0.024352,0.204007,-0.494758,0.579013,0.172825,-0.219630,0.502819,0.007377,-0.559774,-0.306482,0.583677,0.768864,-0.203094,0.164980,0.287918,-0.030178,-0.315805,-0.461040,-0.068290,-0.130593,-0.431128,-0.666269,-0.357673,-0.245633,-0.024641,-0.437228,0.913727,0.201215,-0.240082,0.241938,0.315151,0.405370,0.094481,0.161926,-0.098968,0.070923,0.416398,-0.101399,-0.536517,0.489499,-0.017370,-0.017216,-0.002544,0.089927,0.041674,0.213475,0.539291,-0.274644,0.084619,0.175768,0.554216,-0.260333,0.015766,-0.105069,0.340821,-0.045255,0.212355,0.341108,-0.080098,0.069724,-0.108936,0.095324,-0.828166,0.070195,0.211951,0.204961,-0.655073,0.284582,-0.292251,-0.094244,0.129303,-0.316866,0.255389,0.331705,0.485384,0.289868,-0.073710,0.161286,-0.363316,0.236311,0.529129,-0.059355,-0.090847,0.235355,-0.216011,-0.508852,-0.232686,-0.393576,-0.427332,0.185872,0.438827,-0.077725,0.012585,0.370881,-0.348872,-0.039202,-0.025393,-0.367001,0.075238,-0.264738,0.009993,-0.869913,0.023699,-0.169058,-0.190176,-0.240648,0.043712,-0.507720,0.722513,-0.819232,0.185779,0.435795,0.055187,-0.175986,0.655631,-0.043268,0.102590,-0.374317,-0.116663,0.381737,0.032499,-0.059790,-0.225773,0.321715,0.178174,-0.351184,-0.419170,0.423410', '2369613', '25880986', '3861846', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1940086', '别惹小孩', '喜剧', '西方传统的一年一度的万圣节又到了，据说在这个鬼魂和怪物自由出没的夜晚，只有遵循传统点燃南瓜灯的人才能安然度过。然而总有那么一些人因各种各样的原因而没能遵守这个传统，他们将接受最严酷的教训，甚至可能命丧黄泉。万圣节这天，格雷戈先生（布莱恩•考克斯 Brian Cox 饰） 和太太在午后还没过就弄坏了南瓜灯；四个打扮恶俗的女士在小路上高声谈笑；一群捣蛋鬼作了最最严重的恶作剧……这些不遵守规矩的人将在这个恐怖的午夜付出惨痛的代价！©豆瓣', '奎恩·罗德', '迈克尔·道赫蒂', 6.6, 19438, 'tt0862856', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1762398994.jpg', 2.5, 11.3, 48.9, 29.1, 8.2, '0.307473,0.053717,-0.818742,0.223760,-0.244575,-0.014422,0.881897,0.094957,-0.211265,-0.237710,0.495978,0.627415,-0.032456,0.046120,0.339022,-0.242212,-0.265997,-0.281232,-0.015369,-0.091063,-0.420857,-0.387973,-0.114696,-0.115242,-0.133158,-0.349922,0.401683,0.240258,-0.033038,0.287968,0.083168,-0.079433,0.166225,0.323731,-0.654517,-0.086564,0.167485,0.087472,-0.003736,0.092379,-0.018892,-0.322695,-0.112742,0.088327,-0.073945,0.332088,0.563771,-0.767106,-0.401145,0.069889,0.463750,-0.631349,-0.342385,0.521443,0.244867,-0.191951,0.210992,0.108700,-0.144506,0.174091,-0.110656,-0.159203,-0.905740,0.102437,0.172897,0.191489,-0.664371,0.685195,0.064082,-0.166890,0.035629,-0.379381,0.403456,0.300833,0.132759,0.470849,-0.060727,-0.135352,-0.751592,0.058045,0.614263,-0.313479,-0.229539,0.396306,-0.380356,-0.457081,0.122247,-0.385055,-0.490072,-0.052684,0.271391,-0.354922,-0.310461,0.071666,-0.756637,0.245834,-0.006530,-0.384863,0.036764,-0.307910,-0.506406,-0.487122,0.045946,-0.417452,-0.180870,0.396579,0.267457,-0.093938,0.986146,-0.879776,0.425340,0.451364,0.332408,-0.349203,0.719595,0.210621,0.189482,-0.014194,-0.148145,0.041022,0.254624,0.340181,0.036743,0.667866,0.192260,-0.102847,-0.321842,0.319722', '24284209', '3005387', '1309101', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1940094', '我们的幸福时光', '爱情', '身为大学讲师的柳贞（李英娜 饰）表面虽然风光，可是她一直受小时候被堂兄强奸的惨痛经历困扰，因此她非常不满意母亲息事宁人的做法。她不相信爱情，也不相信命运，她更有过三次自杀未遂的经验。她即使极不情愿，而她还是在姑妈的安排下到了劳教所去。在里面她认识了因谋杀而被判死刑的润秀（姜东元 饰）。因为同样有被母亲抛弃的命运，同样感到生命的绝望，两人很快放下了戒心，从相知相识到相恋，彼此温暖着，慰藉着对方的心灵。但正当他们爱得激烈，润秀的刑期也即将来临……©豆瓣', '李奈映', '宋海星', 8.1, 26791, 'tt0870967', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p472182473.jpg', 0.4, 2, 22.2, 45.4, 30, '0.176450,0.055955,-0.956076,0.527610,-0.270291,-0.145655,0.906660,0.016628,-0.579727,-0.214965,0.356167,0.638472,0.057260,0.252128,-0.011939,-0.069686,0.053219,-0.360773,0.101565,-0.208437,-0.204537,-0.518403,-0.105249,0.036175,-0.267896,-0.153263,0.632427,0.139708,-0.160610,0.422223,0.272318,0.265596,0.197136,0.849397,-0.230295,0.106807,-0.021996,0.238323,-0.147466,-0.144009,0.403997,-0.337932,0.000666,0.314073,-0.151396,0.383846,0.662227,-0.340215,-0.518928,0.082981,0.587174,-0.508767,-0.021394,0.349708,0.317763,0.137106,-0.020788,0.325024,-0.166929,0.210282,0.083014,0.104400,-0.771961,0.046957,0.309254,0.291962,-0.660920,0.872076,-0.264388,-0.050837,-0.207912,-0.209622,0.089648,0.314175,0.273455,0.286075,-0.478620,-0.208434,-0.595553,0.060937,1.215636,0.017154,-0.216450,0.532902,-0.687156,-0.481609,-0.019377,-0.384079,-0.686781,0.167265,0.128075,0.191779,-0.378072,0.352066,-0.186946,-0.034743,0.000236,0.093692,-0.062595,-0.788653,0.210340,-0.064321,-0.455579,-0.837687,-0.781844,-0.152334,-0.113333,-0.599251,0.651627,-0.901646,0.296085,0.563955,0.439770,-0.494004,0.699068,0.535032,-0.050743,-0.140257,0.097672,0.716310,-0.069933,0.017822,0.276557,0.274222,0.112412,-0.041867,-0.208530,0.568640', '25721544', '1292064', '2071525', '1307561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1940459', '最后的吸血鬼', '动作', '16世纪，日本爆发应仁之乱，战火瞬时蔓延全国。国内征伐不断，百姓流离失所。是时妖魔邪祟趁虚而入，祸乱人间。吸血鬼在魔王鬼源真祖的率领下大肆屠害生灵，与之相对，另有一部分吸血鬼猎人挺身而出，与这群恶魔展开斗争，彼此缠斗近400年。20世纪70年代，猎人集团以“红盾”的名义存在，他们中的少女猎人藤本小夜（全智贤 饰）尤其出众。小夜是吸血鬼和人类结合生下的女孩，她表面上是一个16岁的普通女高中生，实际上却是年龄接近400岁的吸血鬼猎人。她受命潜入美军基地内一所美国人学校，在此结识了将军的女儿爱丽丝（Allison Miller 饰），并将其从吸血鬼的手中救出。真祖及其手下蠢蠢欲动，他们和猎人绵亘了数百年的恩怨终于要做个了断……©豆瓣', '全智贤', '克里斯·纳汉', 5.1, 8380, 'tt0806027', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p454189842.jpg', 11.2, 35.7, 41.6, 8.2, 3.2, '0.348506,-0.107476,-0.316991,0.322808,-0.154416,0.132572,0.656674,-0.168919,-0.473711,-0.304910,0.286684,0.862857,-0.079492,0.201076,0.078722,-0.164229,-0.093483,-0.718027,-0.166611,-0.347806,0.013981,0.006266,-0.542440,-0.172336,-0.240711,-0.344195,0.958787,0.099417,-0.003019,0.442198,-0.020907,0.338932,-0.383590,0.246263,-0.344218,-0.333997,-0.008543,-0.222696,-0.109250,0.249569,-0.338127,-0.277568,0.057292,-0.050903,-0.219104,0.280089,0.773936,-0.515938,0.354999,-0.646481,0.333291,-0.274034,-0.268154,0.214602,0.717777,-0.188857,0.290172,0.257582,0.255625,-0.256280,-0.146733,-0.313028,-0.616144,-0.129587,0.208188,0.093987,-0.498888,0.462015,0.111898,0.213579,0.253894,0.037984,0.074490,0.429329,0.210713,0.267353,0.034748,-0.163405,-0.382169,0.155884,0.732544,0.036940,-0.498002,-0.167424,-0.261273,-0.790106,-0.177543,-0.480083,-0.404880,-0.223199,0.211462,-0.051422,-0.044993,0.534356,-0.784209,-0.028260,-0.251524,0.081764,0.224198,-0.064225,-0.175498,-0.433472,-0.292897,-0.444769,-0.133946,0.145863,0.297335,-0.109061,0.904413,-0.856123,-0.068718,0.591097,0.716249,-0.357643,0.692192,-0.300583,0.209474,-0.258546,-0.204124,0.344776,0.024986,0.336694,0.043573,0.169064,-0.265157,0.038040,-0.205489,0.295841', '3811356', '25880986', '26386465', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1940867', '大电影', '喜剧', '以乳鸽店立身的安德森（曾志伟 饰）赴上海创业，却迷上炒房，将妻子气死也未思悔改，这天安德森在影院偶然听到代言新楼盘“碧水云居”的过气演员潘志强（黄渤 饰）放出的“内部消息”，遂再次筹款预抢购新房。与此同时，新婚的昔日售楼小姐罗茜（姚晨 饰）为碧水云居付出五万订金后，惊系该楼盘周边林立各污染源。潘志强担任楼盘主持嘉宾并为售楼公司鞍前马后，只希望对方能为自己的新片注资，不料却被要求退还订金的罗茜纠缠，潘志强心生一计，令罗茜将房转卖安德森，事成后自食其言拒退订金，罗茜无奈只得曝光楼盘内幕，结果引发连串反应，使潘志强与安德森发现自己陷入了开发商之局，于是各人苦思脱身之法……©豆瓣', '姚晨', '刘晓光', 5.6, 36334, 'tt3056688', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2007475134.jpg', 8.7, 25.6, 48.7, 13.6, 3.4, '-0.034845,0.277008,-0.323090,0.031568,0.189656,-0.439589,0.228842,0.467171,-0.250685,-0.188019,0.187348,0.424465,-0.308030,0.127089,0.329114,-0.017246,-0.112896,-0.390327,0.002906,0.058553,0.191625,-0.320489,0.159561,-0.126734,-0.189079,0.292517,0.303672,0.218088,-0.064897,0.123110,0.377906,0.189037,-0.195036,0.440306,0.365900,0.247413,0.222745,-0.016474,-0.591788,0.251413,-0.121467,-0.247563,-0.279341,-0.023142,0.168166,0.486166,0.370356,0.153012,-0.191781,-0.312040,0.413656,0.160933,0.303978,0.022786,-0.042927,0.237962,0.330042,0.067138,-0.594156,0.105510,0.124703,0.038516,-0.376231,0.106075,0.240337,-0.174710,-0.337100,-0.090066,-0.285320,0.151413,-0.191804,-0.351130,-0.149523,0.352734,0.323160,0.111573,-0.073908,0.139829,-0.509366,0.291930,0.103627,0.090873,0.200422,0.049309,0.165373,-0.425085,0.180988,0.151119,-0.190838,-0.059285,0.445017,0.232862,0.433757,-0.183862,-0.406344,-0.399312,-0.170338,-0.177520,-0.010637,-0.132107,-0.133819,-0.701222,0.070563,0.432300,-0.104487,-0.197079,0.397716,0.004056,0.016694,-0.505782,0.034253,0.113427,0.426933,-0.539556,0.392079,-0.090180,0.241317,-0.305709,-0.047801,-0.197209,0.006651,0.334887,0.150207,-0.004861,0.009753,-0.419344,0.024080,0.217435', '20472857', '3077791', '3183490', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1940880', '呼吸', '剧情', '生无可恋的死囚张真（张震 饰）知道自己剩下的日子不多，在他想要自杀之际，他又想要多活几天而放弃了马上死去的念头，继续感受冰冷的监狱，他也知道不用自己动手，他离死亡也不远了。原本生活幸福的的室内设计师妍（朴智娥 饰）面对丈夫（河正宇 饰）的外遇，顿时倍感失落伤心。无意间 ，她在电视上看到了死囚张真的有关报道，恻忍之心油然而生，便前往监狱探望张真。不知为何，妍把小时候徘徊死亡边缘的经历告诉了张真这名陌生人。妍想为张真做些事情，因此常常寄给张真礼物。妍的出现，再次带给了张真生活中的温暖。后来两人发展出的恋情，遭到了妍的丈夫的阻止。©豆瓣', '张震', '金基德', 7.3, 20780, 'tt0901475', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1171885752.jpg', 0.7, 4.5, 37.7, 41.6, 15.5, '0.403739,0.121995,-0.670067,0.387646,-0.049858,-0.040173,0.849733,-0.012226,-0.387290,-0.401964,0.156751,0.405229,-0.242456,0.372063,0.077155,-0.033693,-0.346731,-0.791563,0.049570,-0.342690,-0.031751,-0.231064,0.087314,0.057583,-0.172237,0.081706,0.872135,0.199172,0.075598,0.287078,0.122213,0.521634,-0.046479,0.402277,-0.223334,0.185078,-0.117581,0.275496,-0.248335,-0.072898,0.721655,-0.512738,-0.311933,0.382842,-0.003329,0.223600,0.527464,-0.062696,-0.459364,-0.015577,0.592052,-0.008133,0.179896,0.028993,-0.047273,-0.031529,0.138204,-0.101914,-0.255396,0.049415,0.251135,0.183083,-0.484756,0.520500,-0.163871,-0.030435,-0.424956,0.181997,-0.255983,0.238857,0.256624,-0.076731,0.480646,0.572558,0.077218,0.343954,-0.283942,0.117064,-0.215991,0.137884,0.948083,-0.163089,-0.013419,0.353419,-0.171979,-0.136511,-0.078851,-0.027370,-0.536124,0.052491,0.162004,0.393243,-0.367371,0.100621,-0.504709,0.110205,-0.248794,-0.222845,0.031083,-0.130411,-0.110730,-0.276064,-0.247104,-0.018408,-0.289809,0.041006,-0.214300,-0.679434,0.377463,-0.658437,0.264420,0.331102,0.694259,-0.963012,0.630525,0.057096,-0.107449,-0.161513,0.261984,0.455620,-0.167248,0.109314,0.348835,0.048052,0.096533,-0.003148,-0.404440,0.655277', '25858759', '4728584', '5919538', '4145476');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1941242', '墨水心', '家庭', '麦琪（伊丽莎•班尼特 Eliza Bennett 饰）是一个生活在德国的12岁小女孩，她和父亲阿莫（布兰登•费舍 Brendan Fraser 饰）相依为命。妈妈莱莎（Sienna Guillory 饰）在麦琪尚在襁褓中时便神秘失踪，十几年来阿莫凭借旧书装祯的手艺维持父女二人的生活。麦琪对母亲的下落充满好奇，而父亲则三缄其口。孤单的小女孩每日徜徉书海，任凭思绪飞扬。某晚，一个肮脏邪恶的家伙（Paul Bettany 饰）闯入父女的家中，阿莫和女儿仓皇逃到姑妈爱利诺（海伦•米兰 Helen Mirren 饰）的家中，此时麦琪终于得知母亲失踪真正的原因以及父亲所具有的神奇能力。原来阿莫能够通过阅读将书中的人物带到现实的世界中来，而这也正是灾难的开始……本片根据德国著名女作家科尼莉亚畅销丛书中的第一部改编。©豆瓣', '伊丽莎·班尼特', '伊恩·索夫特雷', 6.4, 31648, 'tt0494238', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165825218.jpg', 1.7, 12.7, 56.6, 23.5, 5.6, '0.236701,0.056362,-0.674121,0.566504,-0.108012,-0.355517,0.652455,-0.111490,-0.610581,-0.508015,0.226923,0.823263,0.157743,0.374361,0.328702,0.157674,-0.358461,-0.590356,-0.200881,-0.276370,-0.106331,-0.508846,-0.356499,-0.194445,0.000558,-0.404502,0.465230,-0.016410,-0.112875,0.520802,0.133485,0.518912,-0.567940,0.231885,-0.032583,0.150158,0.250006,0.124466,-0.423053,0.087765,0.060189,-0.088323,-0.107765,0.112091,0.061421,0.077030,0.825857,-0.489777,0.016735,-0.063627,0.454879,0.039745,-0.240433,-0.064775,0.325254,-0.034813,0.342950,0.117879,-0.200030,0.112647,-0.079767,-0.244131,-0.562709,-0.037354,0.325112,0.102769,-0.405186,0.219134,-0.175316,-0.244114,0.237197,-0.435286,0.105196,0.291029,0.123856,0.697501,-0.125177,0.017475,-0.305123,0.251098,0.149710,-0.283221,-0.091129,0.397131,-0.283221,-0.199500,0.045737,-0.221352,-0.700448,0.026503,0.225472,0.109138,-0.144279,0.302452,-0.479954,0.080782,-0.214635,-0.110207,0.192128,-0.301873,-0.345572,-0.337696,-0.210597,-0.338402,-0.160531,-0.139746,0.055961,-0.379238,0.751800,-0.699312,0.378461,0.270040,0.062345,-0.221516,0.492192,-0.092471,0.211658,-0.314581,-0.140700,0.653063,0.065934,0.014840,-0.141526,0.207956,0.025629,-0.051971,-0.469402,0.448183', '30401849', '26348103', '1292720', '1296992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1944900', '天启四骑士', '剧情', '兰斯林（丹尼斯·奎德 Dennis Quaid 饰）警官同时也是一个单身父亲，因公务繁忙，他无暇照顾两个儿子，大儿子亚历克斯无形中时常扮演父亲的角色。最近兰斯林被一桩连续杀人案缠住，每个凶案现场都发现了至少四名嫌疑人的踪迹，并且统一留下了“过来看”的血色留言，死者死于悬挂的状态充满了宗教意味，兰斯林从人体悬挂的铁架入手，发现这一干罪犯以杀人作为宗教仪式，并且以启示录中记载的“天启四骑士”自居。第一个受害者的华裔养女克里斯汀（章子怡 饰）主动找到兰斯林，坦承了自己与连续杀人案的关系，但是这不能阻止更多人受害，兰斯林惊见自己最不愿意看到的事情发生了……©豆瓣', '丹尼斯·奎德', '乔纳斯·阿克伦德', 5.2, 9170, 'tt0892767', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1081197424.jpg', 8.9, 33.4, 46.8, 8.8, 2.2, '0.018677,-0.044873,-0.549410,0.658035,-0.144220,-0.342424,0.879029,-0.013986,-0.467248,-0.604595,0.214642,0.467634,-0.175487,0.232081,0.164979,-0.339605,-0.246073,-0.675909,-0.118077,-0.096081,-0.571700,-0.349013,-0.062003,-0.399888,-0.251204,-0.148109,0.344968,-0.048776,-0.125169,0.071305,0.485738,0.527624,-0.172291,0.426990,0.042270,0.012469,0.084229,-0.177344,-0.262559,0.285429,0.223062,-0.211831,-0.072890,0.175243,0.048413,0.551904,0.817373,-0.272592,-0.240542,-0.268962,0.395206,-0.269463,0.042447,0.183566,0.410662,0.132080,0.072309,0.154711,-0.109230,-0.190594,0.349556,-0.049739,-0.663784,-0.024731,0.150668,0.454271,-0.294123,0.186634,-0.290518,-0.138354,-0.007424,-0.281708,0.403067,0.315048,0.318916,-0.013738,-0.064519,0.031290,-0.470195,0.109447,0.458849,0.094664,-0.216741,0.204435,-0.451784,-0.547392,-0.064637,-0.026261,-0.187042,0.077462,0.310237,-0.099592,-0.043222,0.335005,-0.251795,-0.424366,-0.135686,-0.217226,-0.234347,-0.454587,0.102648,-0.500357,-0.081311,-0.383018,-0.224385,0.100186,0.016271,-0.286618,0.364389,-0.522697,0.090095,0.292549,0.100069,-0.387791,0.551359,0.078298,0.119211,-0.168891,-0.109651,0.167412,0.498644,0.240301,0.277767,0.144172,0.161746,-0.190993,-0.265419,0.421062', '4903581', '2988294', '4023433', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945253', '自由作家', '剧情', '爱林（希拉里·斯万克 Hilary Swank饰）从事的第一份教育工作，就是在威尔逊学校一个糟糕透顶的班级里担任老师。这里有着给老师们带来噩梦的学生：他们虚度光阴，消磨时辰，把学校当成18岁之前的游乐场；更混乱的是，学生们来自社会里的不同种族和各类底层阶级，分帮结派互相斗殴。爱林想方设法让仇恨远离孩子们的心，消解他们之间的敌意，可是，作为一名白人老师，孩子们对她树起了重重心墙，爱林的教育理想在现实中一次又一次地碰壁。孩子们跌入深渊的心灵是否无药可救，他们的未来能否在爱林的循循教导下重现曙光，爱林的肩上承着千斤重担，她只有一本或者可以感化孩子的《安妮日记》，以及一颗热忱真诚的心，带领迷失的孩子找到明灯。©豆瓣', '希拉里·斯万克', '理查德·拉·格拉文斯', 8.6, 24815, 'tt0463998', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1009650327.jpg', 0.2, 0.8, 11.2, 44.7, 43.1, '0.236207,-0.134348,-0.459029,0.598210,-0.446611,-0.217414,0.675008,0.016990,-0.497425,-0.169296,0.041810,0.501001,0.142110,0.655036,0.113686,-0.190549,-0.441144,-0.896597,-0.346956,-0.210246,-0.466671,-0.454377,-0.261185,-0.321686,-0.215072,-0.243508,0.634917,0.251032,-0.222721,0.247164,0.171634,0.379601,0.127688,0.201392,-0.240923,-0.141822,0.044940,-0.003065,-0.217840,0.113879,-0.027618,0.166164,-0.310736,0.092055,0.207586,0.052455,0.884826,-0.135908,-0.134479,-0.302081,0.456252,-0.237974,-0.131424,0.180554,0.370890,0.229289,0.276196,0.110009,-0.019322,0.148739,-0.002888,-0.366381,-0.741411,-0.275327,0.053526,-0.036669,-0.617012,0.397255,0.440765,-0.042254,0.175776,-0.037018,0.083030,0.095821,0.229836,0.720208,-0.485314,-0.095411,-0.183833,0.134652,0.723737,-0.185611,-0.231480,0.063364,-0.493027,-0.336700,0.180332,-0.070743,-0.655480,-0.060817,0.171715,0.068854,-0.257389,0.428091,-0.420452,0.091078,-0.197798,-0.229323,0.011154,-0.628804,-0.090426,-0.511914,-0.057005,-0.225881,-0.314124,0.094977,0.276497,-0.253535,1.223218,-0.681798,0.353376,0.370075,0.178862,-0.524753,0.798952,0.217034,0.189584,-0.211095,-0.109705,0.314615,0.058925,0.228775,-0.127914,0.183220,-0.297282,0.109804,-0.398846,0.414692', '26348103', '1307146', '27602116', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945330', '迷雾', '科幻', '一座风景秀美的小镇被一场突如其来的浓雾瞬间淹没。雾中传来阵阵惨叫，人们惊慌失措地四处逃散。戴维和他的儿子与众多镇上的人被困在小镇超市里，等待雾的消散。浓雾并没有如期望的散开，而走进浓雾的人一去不返。浓雾逐渐露出了它狰狞的面目。恐惧、惊慌、挣扎、悲伤、绝望……人们的精神濒临崩溃。如何才能活着走出迷雾？面对超市里几近癫狂的人们和超市外吞噬一切、不可知的迷雾，戴维紧紧搂着儿子，开始了艰难的求生之路……©豆瓣', '托马斯·简', '弗兰克·德拉邦特', 8, 306492, 'tt0884328', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1970406441.jpg', 0.9, 2.6, 19.5, 47.9, 29.1, '0.043993,0.044317,-1.020338,0.419478,0.152441,0.132086,1.466179,0.449600,-0.367037,-0.086138,0.110265,0.306764,-0.288764,0.551352,0.038721,0.077101,-0.248917,-0.818648,-0.485602,-0.057816,-0.162965,0.231080,-0.424924,-0.366601,-0.047278,-0.390650,0.747371,0.930842,-0.009609,0.643649,-0.033496,0.124567,-0.549088,0.808399,-0.119946,-0.135672,-0.121807,-0.117350,-0.095336,-0.120193,-0.304451,-0.422343,-0.282304,0.087770,-0.429848,0.402491,1.136400,-0.207079,0.111090,0.097051,0.182629,-0.604256,0.057541,0.468432,-0.070064,-0.231133,0.036987,-0.344200,-0.146073,-0.149741,-0.146136,-0.071783,-0.418119,0.226817,-0.006563,0.634115,-0.394776,0.336848,0.269954,-0.085554,0.259710,-0.302168,0.199109,-0.476453,-0.307214,0.756795,-0.405484,0.025250,-0.713890,-0.228180,0.498090,-0.343711,-0.537161,0.300640,-0.419528,-0.113587,-0.027109,0.247242,-0.581564,-0.358859,0.624174,0.503131,-0.504282,0.354972,-0.542379,0.038982,-0.210403,-0.637203,-0.525674,-0.251233,-0.735001,-0.547488,-0.250856,-0.145625,0.151555,-0.007082,-0.242746,0.200795,0.284860,-0.364474,0.217848,0.316443,0.031253,0.024105,0.348810,-0.503211,0.142979,0.257135,0.073319,0.350354,-0.096682,0.739187,0.345262,0.426952,-0.438201,0.545428,-0.562503,0.623359', '20451118', '21619567', '30136177', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945336', '通缉令', '动作', '生活对小职员卫斯理（James McAvoy 饰）来说是毫无意义的重复，每天要忍受痴肥上司唠叨、好友与女友上床，还要不停用药物控制过快的心跳。这天他被一名陌生女子从疯狂枪手的追杀中救出，进入了刺客联盟的世界，救命恩人火狐（Angelina Jolie 饰）与联盟领导史隆（Morgan Freeman 饰）告知卫斯理当年抛弃他的父亲也是组织一员，最近为叛徒十字所杀，卫斯理必须尽快在严酷的训练中成长，才能自保，甚至为父报仇。刺客联盟起源于纺织行会，他们按照纺织机提供的密码决定刺杀对象，从而顺应命运的安排。卫斯理很快凭借优异的天赋掌握一系列暗杀手段成为组织一员，开始执行命运赋予的任务，并逐渐接近向十字寻仇的目标，终于，史隆令卫斯理远赴东欧刺杀十字，但在这次任务中，卫斯理意外发现了组织内部的阴谋，而这一次，他不再用逃避解决问题。本片获2009年英国帝国电影奖最佳科幻幻想电影奖。', '詹姆斯·麦卡沃伊', '提莫·贝克曼贝托夫', 7.4, 174394, 'tt0493464', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p947402638.jpg', 0.7, 4.2, 33.4, 45.2, 16.4, '-0.178998,0.162077,-0.269032,0.718914,-0.028151,0.076528,0.294347,-0.084500,-0.436645,-0.403586,0.266675,0.491180,0.337187,-0.040205,0.474541,-0.339588,-0.250072,-0.662302,0.067158,-0.225598,-0.313908,-0.521717,-0.303303,-0.542504,-0.112988,-0.515507,0.930436,0.132397,-0.468931,0.220966,0.250041,0.340436,-0.186488,0.095177,0.016555,-0.481950,0.306268,-0.074025,-0.506313,0.405164,-0.094225,-0.219241,-0.088185,0.176211,-0.066814,0.415882,0.529407,-0.457434,-0.225991,-0.486525,0.344444,-0.551426,-0.292304,-0.195186,0.394346,0.183400,0.164171,0.308042,0.065096,0.055739,-0.176990,-0.277699,-1.144116,-0.136655,0.464876,-0.098930,-0.561368,0.151753,-0.206403,0.286673,0.057273,-0.288716,0.085574,0.472707,0.524493,0.237081,-0.208079,0.194299,-0.323178,0.279050,0.731451,-0.178116,-0.175385,-0.006490,0.045609,-0.230125,0.075878,-0.494602,-0.262192,0.101420,0.112052,0.091030,-0.041104,0.409262,-0.391886,-0.142892,-0.264881,-0.208161,0.180743,-0.468065,0.280396,-0.723432,-0.076747,0.101354,-0.118680,0.038500,0.048661,-0.374129,0.664531,-0.915726,0.199024,0.634044,0.302776,-0.773880,0.438939,0.180981,0.245973,-0.523514,-0.038894,0.146526,0.151945,0.214793,-0.148585,0.055904,0.118006,-0.243120,-0.191147,0.270236', '2