INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945337', '爱的盛宴', '剧情', '哲学教授兼作家哈利（摩根•弗里曼 饰）经常光顾一间咖啡店，在那里目睹了形形色色的爱情故事。咖啡店老板布拉德利（格雷格•金尼尔 饰）因与妻子凯斯林（塞尔玛•布莱尔 饰）离婚而陷入苦闷，他为此与偶遇的房地产经纪人戴安娜（拉达•米切尔 饰）闪电结婚，又因后者对已婚情人大卫（比利•巴奇 饰）念念不忘，而闪电离婚。绝望的布拉德利尝试和爱犬为伴，然而美貌温柔的阿加莎（米茜•派尔 饰）意外出现，打乱了他的心。与此同时，咖啡店的服务生奥斯卡（托比•海明威 饰）和克罗伊（爱丽克莎•黛奥洛斯 饰）走在了一起，他们为共同的未来制定种种计划，并对家庭生活产生了无限的憧憬……©豆瓣', '摩根·弗里曼', '罗伯特·本顿', 7, 5376, 'tt0800027', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p461625975.jpg', 0.8, 6.8, 44.3, 35.9, 12.2, '0.265592,-0.160042,-0.504467,0.420186,0.122474,-0.443886,0.865398,0.553281,-0.488528,-0.410129,0.069804,0.890413,-0.427060,0.202574,0.408568,0.079252,-0.426852,-0.662854,0.121096,0.061386,0.082350,-0.582498,-0.057709,-0.333522,0.009699,-0.316932,0.408543,-0.202969,0.072934,0.716655,0.333948,0.562634,-0.054282,0.219143,0.073501,0.175336,0.292940,0.059399,-0.610587,0.026998,0.034686,-0.002831,-0.065084,-0.064521,0.006680,0.253691,0.540989,-0.059213,-0.012742,-0.126913,0.210022,0.011314,0.205293,0.194678,0.185426,-0.051511,0.087489,0.137467,-0.346621,-0.163112,0.354979,-0.047069,-0.582506,0.314235,0.010548,0.251915,-0.476984,0.336979,-0.357007,-0.001930,0.317772,-0.117482,-0.024563,0.191173,0.500361,0.234544,-0.021106,0.039476,-0.206116,0.108275,0.305954,0.132828,0.088042,0.308465,-0.466735,-0.233478,-0.131908,0.252106,-0.690552,-0.243900,0.186686,-0.006631,0.033097,0.383487,-0.553267,-0.242266,-0.284738,-0.025104,0.017423,-0.477137,-0.159441,-0.970648,-0.155301,-0.495085,-0.189182,-0.133011,0.077823,-0.073556,0.338089,-0.752440,0.357571,0.361153,0.251037,-0.345404,0.745272,0.070212,0.122417,-0.329042,-0.113225,0.658900,-0.073087,-0.136119,0.019999,0.211135,0.259355,0.151713,-0.218739,0.585586', '1297239', '3326747', '4319218', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945549', '超市夜未眠', '剧情', '艺术学院学生本（肖恩•比格斯代夫 Sean Biggerstaff 饰 ）在被女友苏芝甩了之后，夜夜无法入睡。在经历了两周的不眠之夜后，本决定到超市去上夜班以打发这额外的8小时。在超市上夜班，本遇到了形形色色的人，包括喜欢恶搞的同事巴里和马特、超级迷恋中国功夫的布莱恩，还有收银员莎伦（艾米丽雅•福克斯 Emilia Fox 饰）。在这里，本发现了自己有能停止时间的能力。他一次次在上夜班时停止时间，用自己的画笔去描绘各式女子。不知不觉间，本发现自己喜欢上了莎伦，并且不再失眠。就在本准备展开爱情攻势的时候，误会一个个接踵而至，本又开始失眠了。©豆瓣', '肖恩·比格斯代夫', '西恩·埃利斯', 7.7, 113158, 'tt0460740', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2198335977.jpg', 0.5, 3.2, 28.5, 46.9, 20.8, '0.534967,0.415595,-0.907817,0.141350,0.009557,-0.281371,0.567777,0.183181,-0.587203,-0.192382,-0.025032,0.573710,-0.364239,0.195493,0.691430,-0.320175,-0.769483,-0.771496,0.021888,-0.539183,-0.489647,-0.494405,-0.012741,-0.364699,0.174514,-0.575169,-0.008502,-0.194143,0.022876,0.335852,0.291571,0.126588,0.417946,0.517836,-0.180611,0.068309,0.039588,-0.088068,0.075932,0.346058,0.291552,-0.538501,-0.202911,-0.105918,0.089276,0.142542,0.784525,-0.186204,-0.205561,-0.258649,0.306386,0.124236,-0.145980,-0.062192,0.230773,-0.017562,0.200266,-0.052463,-0.201894,0.152281,0.287078,-0.071714,-0.358758,0.050497,-0.287947,-0.065190,-0.669291,0.541645,-0.178716,0.092375,-0.035074,-0.683328,0.087657,0.422981,0.054015,-0.030721,0.020254,-0.133774,-0.579585,0.363728,0.658058,0.340433,-0.015342,0.535034,0.026461,-0.338950,-0.319367,-0.220245,-0.201665,-0.204076,0.424519,0.164532,-0.390242,0.063893,-0.732015,0.020050,-0.098650,-0.389898,-0.150830,-0.261273,-0.397973,-0.764536,-0.022403,-0.379169,-0.287254,0.198770,-0.022662,-0.168043,0.691162,-0.968888,0.425254,0.525887,0.250541,-0.177038,0.859951,0.001645,0.022905,0.184706,-0.293290,0.008467,-0.177605,0.743159,0.418599,0.384111,-0.123418,0.115025,-0.560291,0.516290', '1292272', '3055049', '25728612', '1291992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945780', '血色将至', '剧情', '1898年，银矿工丹尼尔·普莱恩惟尤（丹尼尔·戴·刘易斯 Daniel Day Lewis 饰）因井下作业事故摔断了腿，但他因祸得福了解到秘密的石油信息。他利用领养的孤儿HW（狄龙·弗雷泽尔 Dillon Freasier 饰）欺骗乡民赢得了石油地盘，从此飞黄腾达。但是， 成为 石油大亨的他并不快乐，在一次意外事故中H.W不幸失聪， HW对他的怨恨与日俱增，他唯一认亲的兄弟居然也是冒牌货。传教士伊莱·桑迪不过是个借宗教蛊惑人心的小人。在一次采矿事故中，丹尼尔的工人不幸丧生。正当他希望伊莱（保罗·达诺 Paul Dano 饰）施以援手时，对方羞辱了他，两人从此开始明争暗斗……©豆瓣', '丹尼尔·戴-刘易斯', '保罗·托马斯·安德森', 8.4, 71070, 'tt0469494', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196432057.jpg', 0.3, 1.3, 15.1, 45.9, 37.4, '0.014281,-0.093653,-0.546094,0.249907,-0.057737,-0.313309,0.652104,-0.151592,-0.476609,-0.246098,0.248178,0.556249,0.028401,0.090999,0.064264,0.317488,-0.245214,-0.351519,0.412541,-0.082639,-0.203748,-0.509153,-0.343625,-0.605193,-0.234516,-0.214907,0.475209,0.292399,-0.218911,0.365892,0.039130,0.117131,0.191175,0.494865,-0.111595,0.108593,0.183389,0.022746,-0.326668,-0.021086,-0.019324,-0.333912,-0.222862,0.364135,0.181757,0.674171,0.484625,-0.455705,0.211553,-0.088489,0.240968,-0.471072,0.050343,-0.144389,0.067202,-0.124142,0.104119,0.236372,-0.127964,0.005227,0.204590,-0.045206,-0.419411,-0.167471,-0.024500,0.132070,-0.348316,0.699593,-0.192943,0.200535,-0.193490,-0.060853,-0.110031,0.033338,0.237971,0.191810,-0.283925,0.004380,-0.525453,0.175357,0.708174,-0.138880,-0.161619,0.272597,-0.328250,-0.574240,0.013623,-0.319571,-0.399955,0.049734,0.521629,-0.159825,-0.138383,0.543576,-0.314016,-0.264584,-0.338656,0.163834,-0.024506,-0.247201,0.035899,-0.313300,0.035749,-0.212936,-0.414076,-0.061012,0.206550,-0.439744,0.410307,-0.642142,0.234300,0.626822,0.222705,-0.540219,0.515151,0.154474,0.050782,-0.408275,-0.269623,0.348712,0.233346,-0.089444,0.326010,-0.053408,0.127107,-0.172389,0.206543,0.365522', '25721544', '1308755', '26718282', '1308762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945797', '穿越苍穹', '剧情', '这是一部由33首披头士经典歌曲串起来的音乐电影，讲述了一个发生在20世纪60年代，受反战抗议、精神诉求和摇滚乐影响很深的爱情故事。裘德（吉姆·斯特加斯Jim Sturgess 饰）是来自利物浦的一名船厂工人，他孤身一人来到美国的普林斯顿寻找父亲，结识了马上就要退学的马克思（乔·安德森Joe Anderson 饰）以及他美丽的妹妹露西（埃文·蕾切尔·伍德 Evan Rachel Wood 饰）。裘德和露西相爱了，他们来到纽约，遇到了摇滚歌手桑迪（丹娜·弗齐丝 Dana Fuchs 饰），然后又认识了黑人吉他手乔乔（马丁·卢瑟 Martin Luther 饰） 和女同性恋普鲁登斯（梅天悦T.V. Carpio 饰），他们的生活随着动荡的岁月发生着改变。本片的人名都来自于披头士的经典歌曲。©豆瓣', '吉姆·斯特吉斯', '朱丽·泰莫', 7.7, 9839, 'tt0445922', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2553281182.jpg', 1, 4.3, 27.2, 42.4, 25, '0.365616,-0.352387,-0.457199,0.560108,0.128294,-0.366097,0.884419,0.294988,-0.336401,-0.158866,0.076959,0.811340,-0.239323,0.206577,0.451889,0.129272,-0.572168,-0.816674,0.224943,-0.186643,0.052564,-0.575295,-0.079073,-0.072039,-0.030465,-0.389037,0.335591,-0.161624,-0.212077,0.519741,0.407494,0.450062,0.030709,0.100535,-0.050304,0.409844,0.300423,-0.118305,-0.284034,0.081783,0.171481,-0.115184,-0.057313,-0.042768,-0.043423,0.208355,0.543012,-0.209436,0.278504,0.047959,0.463464,-0.043862,-0.048764,-0.035151,0.215171,0.016380,0.043922,0.324319,-0.139703,0.139626,0.096018,-0.087056,-0.343591,0.370776,0.042929,0.455974,-0.505704,0.355974,-0.200010,-0.068183,0.045481,-0.275575,0.274603,0.507026,0.284834,0.436865,0.066710,0.063071,-0.426554,0.336739,0.701014,0.181596,-0.398715,0.100397,-0.447371,-0.424551,-0.305171,-0.056953,-0.622354,0.057137,0.452200,-0.196661,-0.003618,0.198601,-0.716446,-0.153944,0.016062,-0.527966,0.018703,-0.274029,-0.134521,-0.959075,-0.295334,-0.515173,-0.026000,-0.086232,-0.047604,-0.118329,0.756694,-0.708097,0.354154,0.398064,0.157423,-0.263186,0.541886,-0.162553,-0.005652,-0.101215,0.014661,0.585816,-0.082403,0.068972,-0.015752,0.350451,0.242540,-0.058750,-0.212797,0.307728', '11541282', '30162520', '35161768', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1945800', '加州之王', '剧情', 'Charlie（迈克尔•道格拉斯  Michael Douglas 饰）在圣克莱塔行为健康院疗养了两年后，终于获准出院。两年间，Charlie的精神趋于正常，却开始痴迷于一批古老的西班牙宝藏，还把自己的女儿Miranda（埃文•蕾切尔•伍德 Evan Rachel Wood 饰）也拖下了水。在艰难的寻宝历程中，父女二人冲突不断，纠结多年的矛盾开始爆发，但是父女之间的亲情渐渐冰释，越发浓烈。最终，能否找到宝藏并不重要，亲情的回归才是这一路最大的收获。©豆瓣', '迈克尔·道格拉斯', '麦克·卡希尔', 7.6, 7356, 'tt0388182', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1707669514.jpg', 0.5, 3.4, 31.7, 45.6, 18.9, '0.194511,0.443817,-0.876834,0.483640,0.138216,-0.492705,0.537596,-0.024059,-0.623678,0.039970,0.077853,0.564586,-0.207623,0.203404,-0.042438,0.117449,-0.406704,-0.647115,0.171901,-0.305873,-0.225371,-0.455019,-0.347452,-0.111168,-0.392039,-0.380807,0.486639,0.368159,0.073818,0.353832,0.198278,0.154327,-0.136973,0.457267,0.048638,-0.040822,0.343329,0.111100,-0.295511,-0.160171,0.249548,-0.338399,-0.241764,0.373983,0.475648,0.407724,0.589324,-0.368821,-0.186757,0.227979,0.356832,-0.065158,-0.340460,0.107043,0.344471,0.142099,0.129588,0.467864,-0.304638,-0.128660,-0.188378,-0.177707,-0.547851,0.017990,0.043445,0.027165,-0.455108,0.618666,0.135592,-0.297449,0.151164,-0.358957,0.014911,0.788726,0.169212,0.379858,-0.348595,-0.080820,-0.221065,-0.003905,0.706410,-0.303854,-0.476838,0.424452,-0.270855,-0.443889,-0.216808,-0.107917,-0.117910,-0.402524,0.761008,0.374606,0.074146,0.477610,-0.736924,0.324692,-0.434063,-0.229855,0.023654,-0.287453,0.194490,-0.452939,-0.321876,-0.617963,-0.242353,0.051760,0.069208,-0.318716,0.715314,-0.467139,0.439380,0.455579,0.022561,-0.497840,0.304182,-0.014592,0.156692,-0.323337,-0.145843,0.496372,-0.272316,0.185015,0.323568,0.468352,-0.051057,0.278149,-0.279708,0.609535', '27040921', '34461680', '24325798', '35446144');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946607', '神探南茜', '喜剧', '在本地小有盛名的少女侦探南茜•朱儿（艾玛•罗伯茨 饰），因为父亲的生意，离开了小镇，搬到洛杉矶生活。随着环境的改变，她也答应了爸爸，从此不再冒险破案，做一个普通的女孩儿。巧合的是，朱儿一家的新宅正是神秘死亡的好莱坞著名女影星德丽娅•德雷克特生前的居所。自从德丽娅死后，这所宅子经常发生一些古怪的事件。这个神秘的地方以及女星离奇的死因又激起了朱儿的好奇心，她决定瞒着父亲，“重操旧业”。在男友奈德•尼可森（马克斯•希尔洛特 饰）和新认识的小伙伴科奇（乔什•弗里特尔 饰）的帮助下，朱儿逐渐发现了一些线索，但与此同时她却收到了莫名的死亡威胁……©豆瓣', '艾玛·罗伯茨', '安德鲁·弗莱明', 6.7, 6490, 'tt0479500', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1895167048.jpg', 1.3, 8, 54.4, 28.2, 8.1, '0.520212,-0.017996,-0.656684,0.418261,-0.078889,-0.161468,0.842442,0.192462,-0.550054,-0.406829,0.198869,0.879626,-0.107434,0.327021,0.292163,0.161589,-0.329065,-0.318962,0.239137,-0.325916,-0.117249,-0.458470,-0.384531,-0.290775,0.070129,-0.461108,0.388909,0.163248,-0.023249,0.403338,0.247574,0.331862,-0.127177,0.469222,-0.090112,0.220631,0.156380,0.084065,-0.150822,0.159540,-0.017395,-0.286171,0.009596,0.068854,0.167736,0.430428,0.452347,-0.208993,-0.364238,0.043128,0.434889,-0.045116,-0.003624,-0.048194,0.300315,-0.244528,0.087417,0.261557,-0.363125,-0.171470,-0.064967,0.013314,-0.490563,0.127019,0.359937,0.398580,-0.605753,0.268379,-0.211110,-0.191986,-0.047984,-0.552538,0.216838,0.378270,0.113434,0.284437,-0.004241,0.174358,-0.359103,0.154719,0.553619,-0.012560,-0.049559,0.259563,-0.349062,-0.463719,-0.002096,-0.112333,-0.445479,0.131689,0.316144,-0.032829,-0.207133,0.179916,-0.570733,-0.209943,-0.143181,-0.190379,0.011384,-0.263727,-0.083234,-0.586341,-0.124452,-0.319778,-0.151889,-0.156999,-0.021640,-0.202724,0.506981,-0.783180,0.294367,0.684849,0.192902,-0.404412,0.419047,-0.135443,0.209504,-0.111727,-0.000943,0.318296,0.046706,0.233528,0.001876,0.422856,0.187414,-0.346396,-0.132742,0.398505', '1309172', '1296534', '3111650', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946776', '异能', '动作', '【剧情1】二战后，美国政府到处搜寻特异功能人士，并成立特别“部门”对其进行人体实验，试图将异能植入士兵体内作为战争武器。在一次药物试验中心灵感应“推手”姬拉（卡米拉·贝勒 Camilla Belle 饰）携药品逃至香港，“部门”派出特工亨利•卡佛（杰曼·韩苏 Djimon Hounsou 饰）负责追捕。香港某区，一直逃避“部门”的意念移物“灵动人”尼克（克里斯•埃文斯 Chris Evans 饰）帮助可预见未来的“透视人”少女卡西（达科塔·范宁 Dakota Fanning 饰）逃出音爆人兄弟及其 “透视人” 妹妹“棒棒糖女孩”（李小璐饰）的追杀。在当地灵异人士的帮助下，尼克与卡西找到姬拉，却发现在药物的影响下，姬拉已然命在旦夕……【剧情2】1945年，纳粹科学家不断进行超能转移的试验，渴望将超乎寻常的异能通过注射移入普通士兵的身体。虽然战争结束，但这项试验仍在继续。战后，各国政府成立名为“隔离区”的秘密基地，他们四处搜罗拥有卓越天赋的孩子进行试验，成果和死亡如影随形。异能者尼克（克里斯·埃文斯 Chris Evans 饰）的父亲（Joel Gretsch 饰）曾是某政府培养的超能杀人者。随着年龄的增长，他的父亲渴望过回正常人的生活，结果却遭杀害。十年后，隐居香港的尼克遇到13岁的小女孩凯希（达科塔·范宁 Dakota Fanning 饰）。凯希是一名观察者，她具有准确预知未来的能力。她从隔离区逃跑引起轩然大波，而和尼克的相逢也让事情变得愈加复杂和危险……', '克里斯·埃文斯', '保罗·麦圭根', 6, 29153, 'tt0465580', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p775067015.jpg', 4.1, 20.3, 52.2, 18.2, 5.2, '0.064554,-0.041435,-0.329291,0.475033,-0.078970,0.063368,0.441025,-0.163631,-0.671498,-0.429232,0.309804,0.466399,-0.036631,-0.135875,0.013816,-0.088372,-0.452435,-0.533337,0.134571,0.053157,-0.363187,-0.512689,-0.472337,-0.351332,0.103734,-0.716135,0.737961,0.051367,-0.357450,0.262446,-0.130974,0.322117,-0.215745,0.346527,0.024715,-0.202679,0.207595,-0.080619,-0.340532,0.347125,0.024343,-0.259880,-0.118908,-0.043690,0.074052,0.248553,0.557497,-0.305963,0.013838,-0.300387,0.247150,-0.113530,-0.119094,0.008501,0.333437,0.199992,0.027579,0.178384,-0.026719,0.042346,-0.062806,0.064339,-0.699261,-0.145323,0.242200,0.103357,-0.318400,0.018410,-0.129572,0.247482,0.074698,-0.215270,-0.141944,0.378724,0.132756,0.166448,-0.284382,0.102355,-0.360752,0.089345,0.321938,-0.261586,-0.340026,0.107386,-0.393684,-0.625432,-0.196857,-0.182163,-0.150597,0.005848,0.212622,0.243432,-0.151500,0.464188,-0.485763,0.079304,-0.329995,-0.165715,-0.046684,-0.141543,0.068706,-0.993850,-0.074086,-0.165189,-0.371736,-0.056797,0.204518,-0.412928,0.683052,-0.735027,0.079186,0.579312,0.248699,-0.585558,0.366903,-0.219948,0.076256,-0.490103,-0.357673,0.544419,0.112658,0.342216,-0.112636,0.170352,0.024641,-0.092122,-0.075176,0.281838', '2369613', '20274039', '1306809', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946786', '隐藏的恋情', '剧情', '“我不在乎你是否完全属于我……只要我爱的人一直在我身旁，即使他爱的是别人。”1942年巴黎，Jean（杰瑞米·雷乃 Jérémie Renier 饰）和Philippe（布鲁诺·托德契尼 Bruno Todeschini 饰）这两位青年同志恋人冒着生命危险，庇护一个孩童时的犹太朋友-Sarah / Yvonne（露易丝·莫诺特 Louise Monot 饰），她的家人都被盖世太保杀害了。他们三人挣扎求存，在这个没有怜悯的社会组成一个临时家庭。Jean的不肖兄弟Jacques（尼古拉斯·高布 Nicolas Gob 饰）是个盖世太保的走狗，他出现后，他们三人的关系受到威胁。当Jean的同志身份被暴露，并且被指控与一名纳粹分子有染之时，一场悲剧正在徐徐展开……©豆瓣', '杰瑞米·雷乃', '克里斯蒂安·富尔', 8.6, 9020, 'tt0444518', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1716549482.jpg', 0.2, 1, 11.4, 43, 44.3, '0.419565,-0.157125,-0.691237,0.620363,-0.498983,-0.208899,0.830796,0.137657,-0.454479,-0.281149,0.251199,0.869766,0.079921,0.272771,0.012237,0.087594,-0.181687,-0.903976,-0.075439,-0.117467,-0.197684,-0.440894,-0.150473,-0.286938,-0.310584,-0.231004,0.538620,-0.026129,-0.102433,0.378164,0.450554,0.341756,-0.017963,0.474095,-0.129930,0.064003,0.450028,-0.010922,-0.216646,0.130653,-0.009857,-0.236372,0.144596,0.304357,-0.204834,0.376074,0.649495,-0.410070,0.002715,-0.319723,0.158657,-0.406073,0.290304,0.475288,0.214942,-0.260926,0.165638,0.332261,-0.033129,-0.136454,0.089949,-0.019219,-0.800302,-0.222789,0.074490,0.262056,-0.587820,0.653350,-0.181344,-0.165127,0.046335,0.033276,0.232912,0.344749,0.189928,0.146646,-0.335683,-0.163823,-0.711878,0.122947,0.734332,0.110435,-0.208382,0.179653,-0.239063,-0.323168,-0.187781,-0.064438,-0.622665,-0.084964,0.354759,-0.252254,-0.225050,0.237484,-0.547589,-0.228743,-0.078804,0.045795,-0.044923,-0.433872,0.010737,-0.216984,-0.035041,-0.558713,-0.391842,0.233852,-0.004365,-0.208020,0.775084,-0.801504,0.319939,0.531323,0.419968,-0.704376,0.765955,0.262516,0.126778,-0.310471,-0.120229,0.213025,0.318200,0.063866,0.391851,0.246584,0.150707,0.109647,0.018361,0.226071', '1301022', '30162520', '4301278', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946867', '发胶', '喜剧', '胖女孩特蕾西（尼科尔·布朗斯凯 Nicole Blonsky 饰）生长在60年代的一个普通美国家庭。她迷上了一个电视选秀的舞蹈节目，并梦想能站到舞台上发光发亮。然而特蕾西的母亲，自小因为肥胖而缺乏自信，常常担心肥胖是特蕾西的绊脚石。不料特蕾西在节目中的出色表现，令她的前途顿时开阔。甚至大家对她的喜欢，胜过了本来非常得宠的艾姆伯小姐（布兰特妮·斯诺 Brittany Snow 饰）。欢喜之余，特蕾西却迎来了事业的急剧转折。一方面，艾姆伯为了保住地位，不惜用尽卑劣手段力挽狂澜，甚至不惜勾引特蕾西的父亲，使得其家庭不和。另一方面，当时社会严格实行种族隔离，特蕾西还陷入了一场种族斗争之中，危险的形势随时会把她的事业前途毁于一旦。©豆瓣', '妮基·布朗斯凯', '亚当·尚克曼', 7.4, 20113, 'tt0427327', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p874809078.jpg', 0.8, 4.3, 36.1, 42.9, 15.8, '-0.002166,0.175668,-0.762649,0.591784,-0.169452,-0.271446,0.511959,0.331119,-0.519961,-0.081065,0.289141,0.770912,-0.265430,0.135458,0.139470,-0.015849,-0.099727,-0.646435,0.034864,0.228367,-0.072602,-0.325603,-0.388486,-0.550425,-0.471060,-0.566710,0.660895,0.131278,-0.341340,0.242708,0.269381,0.049751,0.236074,0.482016,0.038237,-0.140440,0.016800,-0.096102,-0.236542,0.110724,0.173454,-0.241160,-0.094266,0.334655,-0.034874,0.386172,0.466327,-0.253754,-0.148734,-0.250194,0.635319,-0.226849,-0.099509,0.227408,0.301561,-0.132801,0.067000,-0.005927,-0.153018,-0.014629,0.241769,-0.387001,-0.645491,-0.078652,0.164355,0.099976,-0.525498,0.415367,-0.116260,-0.219722,0.143400,-0.122364,0.029912,0.329564,0.245850,0.220135,-0.157470,0.188492,-0.394197,0.160996,0.613212,0.113975,-0.336426,0.554088,-0.454801,-0.269303,-0.050588,-0.352243,-0.516616,-0.158180,0.385019,-0.194808,0.016308,0.366603,-0.364461,0.129085,-0.235357,-0.090144,-0.134404,-0.361027,-0.147618,-0.201060,-0.100763,-0.501396,-0.301442,-0.190308,-0.035606,-0.424783,0.826470,-0.851726,0.029108,0.494970,0.113575,-0.490498,0.529439,0.053959,0.320240,-0.087183,-0.494763,0.355513,-0.257364,-0.046277,-0.156456,0.051539,-0.131697,-0.163171,-0.258062,0.725178', '1870682', '35030151', '1303034', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946877', '后窗惊魂', '悬疑', '本片翻拍自希区柯克的名作《后窗》。凯尔(希安•拉博夫 Shia LaBeouf 饰)本来有着一个幸福的家庭，然而一年前当他的父亲死于车祸后，他的生活开始改变。凯尔一直认为父亲的死与自己有关，一直非常自责。一天，老师批评凯尔时无意提到了他父亲，他爆发了，将老师扔了出去，因此被法院判罚监禁在家三个月。母亲试图用工作冲刷掉悲伤，因此整天只有凯尔一个在家。百无聊赖的凯尔开始用他的望远镜偷窥邻居们的生活：风骚的女仆勾引男主人；三个小孩整天在家看A片；整天剪草的神经汉捏死在自己花园里打洞的兔子；长得鼻直口阔的美女天天游泳练瑜加等等。凯尔渐渐发现在这些邻居中了可能一个隐藏的连环杀手，危险也随之而来。©豆瓣', '希亚·拉博夫', 'D·J·卡卢索', 6.5, 22617, 'tt0486822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1023557426.jpg', 1.2, 9.4, 56.3, 27.6, 5.6, '0.234415,-0.297879,-0.458327,0.256306,-0.355449,-0.324231,0.674300,0.213830,-0.417936,-0.279661,0.228046,0.782098,-0.137791,0.432703,0.112451,-0.116214,-0.222020,-0.530599,-0.070400,0.046339,-0.126810,-0.235327,0.089409,-0.323713,-0.157312,-0.191783,0.397962,-0.252983,0.104536,0.357578,0.116260,0.174653,0.023725,0.307681,-0.059277,0.025207,-0.082393,-0.208918,0.146489,0.132870,0.179309,-0.092139,0.086071,-0.126155,0.038590,0.167945,0.681091,-0.131307,-0.263260,-0.173936,0.564029,-0.123296,-0.313273,0.180366,0.351760,-0.056348,0.253779,-0.101999,-0.231053,-0.065673,0.067105,-0.012317,-0.345170,-0.151815,-0.125348,0.138015,-0.548289,0.302614,0.129150,-0.010521,0.190961,-0.309943,0.237005,0.279419,0.021289,0.385037,-0.354541,0.033203,-0.442716,0.234845,0.370154,-0.312903,-0.069660,0.276794,-0.078584,-0.053969,0.014663,-0.124491,-0.641768,-0.027298,0.230691,-0.188660,-0.548463,0.211236,-0.367806,0.078698,-0.054584,-0.047740,-0.146879,-0.433976,-0.406713,-0.371725,0.058339,-0.286891,-0.345061,-0.087442,-0.009161,-0.298231,0.412906,-0.696453,0.533037,0.514496,0.114923,-0.228243,0.583937,0.101940,0.109237,0.049158,-0.045755,0.487989,0.301178,0.212712,0.148900,0.525987,0.078653,0.064941,-0.327277,0.443506', '1302384', '1292207', '4233625', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946882', '007：大破量子危机', '动作', '紧接前一集《皇家赌场》的剧情，由于爱人维斯佩的背叛，邦德（丹尼尔·克雷格 Daniel Craig 饰）的怒火被彻底激发，甚至在执行最新任务时都不得不尽量克制个人感情，以免把这次任务升级为个人恩怨。通过与M（朱迪·丹奇 Judi Dench 饰）对白先生（加斯帕·克里斯 滕森 Jesper Christensen 饰）的审问，得知维斯佩是被一个难以想象的犯罪组织所要挟。为了能查清楚这个组织的情况，邦德根据手上的线索顺藤摸瓜，最终把目标锁定在了一个名叫格林（马修·阿马立克 Mathieu Amalric 饰）的商人身上。经过不断的调查，最终发现了这个犯罪组织的惊天阴谋，想控制全球的自然资源。在随时可能遭遇背叛、谋杀和骗局的情况下，邦德再次出击……最终成功挫败了这个惊天阴谋。在这一集的片头，性感火辣的舞女轮廓将回归这部经典系列电影的片头。©豆瓣', '丹尼尔·克雷格', '马克·福斯特', 6.6, 114514, 'tt0830515', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p976999823.jpg', 1.1, 9.2, 54.3, 27.7, 7.7, '0.303815,0.305619,-0.433998,0.754600,0.222418,-0.089724,0.334630,-0.004400,-0.320535,-0.480994,0.241874,0.515565,-0.203249,-0.253102,0.108522,-0.008709,-0.480001,-0.733388,-0.085865,-0.165947,-0.207329,-0.534263,-0.581687,0.018130,0.143259,-0.266909,0.635210,0.136827,-0.414783,0.411586,0.567319,0.641551,-0.066766,0.168528,0.103473,-0.180969,0.365862,-0.312767,-0.329321,0.396526,0.160635,-0.250908,0.213464,0.318908,-0.109721,0.494915,0.707710,-0.469694,-0.326898,0.024874,0.399557,-0.216231,0.087400,0.298629,0.216297,0.080118,0.156447,0.400298,-0.483045,-0.023834,0.201364,0.025012,-1.246628,-0.181078,0.287385,0.242331,-0.338778,0.085794,-0.464449,0.081202,0.102625,-0.094405,0.234472,0.516341,0.546855,0.146561,-0.350523,0.047151,-0.401193,0.020908,0.414138,-0.192067,-0.121715,0.162422,0.004324,-0.374918,-0.190943,-0.102653,-0.048882,0.214109,0.472971,0.171001,-0.098366,0.297845,-0.657544,-0.280245,-0.404969,-0.153271,-0.175722,-0.604560,-0.091996,-0.637745,-0.379572,0.203781,-0.048780,-0.055863,0.023025,-0.219768,0.467583,-0.685659,0.210763,0.674968,0.178285,-0.463051,0.216358,0.228977,0.179117,-0.440420,-0.213734,0.043578,0.381448,0.220981,0.100578,0.442636,0.216640,-0.426643,-0.350088,0.460311', '26678784', '2707323