INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1946890', '危情24小时', '剧情', '尼尔·兰德尔（杰拉德·巴特勒 Gerard Butler 饰）和妻子艾比看似美满幸福，生活中相互协调照顾五岁的女儿苏菲。直到一天，一名不速之客莱恩（皮尔斯·布鲁斯南 Pierce Brosnan 饰）声称绑架了他们的女儿，并持枪威胁尼尔夫妇在接下来的24小时中完全受他摆布，不得违抗。为了女儿的安危，尼尔夫妇开始在歹徒的一个又一个要求下亲手将金钱事业一一断送。然而，就在尼尔以为剥削将要结束的时候，噩梦才真正开始，这名歹徒的身份原来牵扯着夫妻二人之间一个深不见底的秘密……©豆瓣', '皮尔斯·布鲁斯南', '麦克·巴克', 6.1, 6330, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2268287126.jpg', 4.2, 16.9, 53.4, 20, 5.5, '0.190215,0.024322,-0.595872,0.478017,-0.480489,-0.533870,0.834009,0.063187,-0.515420,-0.376247,0.488450,0.693269,0.008305,0.172991,0.614240,-0.027560,-0.331922,-0.841486,-0.056973,-0.244902,-0.373145,-0.656913,-0.298615,-0.188840,-0.007194,-0.273556,0.433251,-0.120861,0.341267,0.350360,0.282474,0.001297,-0.155123,0.358835,0.287529,0.134402,0.455114,-0.063584,-0.440243,0.210289,-0.170282,-0.173392,-0.068510,0.386409,-0.202549,0.360914,0.568584,-0.468911,0.091125,-0.507773,0.115321,-0.081056,0.003079,0.344013,0.367437,-0.196183,0.396604,0.412151,-0.270845,0.047322,0.120114,-0.123415,-0.623116,0.110091,-0.013798,0.088727,-0.670997,0.392863,-0.279224,-0.161022,-0.016618,-0.288481,0.038326,0.755668,0.410046,0.579282,-0.574373,0.025514,-0.516297,-0.027282,0.599059,-0.066025,0.003140,0.070043,-0.092732,-0.182400,0.007814,-0.178239,-0.611836,-0.271566,0.437717,0.196261,-0.276635,0.284903,-0.247894,-0.017006,-0.334999,0.019160,0.036437,-0.652760,-0.062478,-0.502991,0.102877,-0.269642,-0.251029,0.101148,0.045862,-0.287014,0.583865,-0.617936,0.378949,0.551165,0.380573,-0.284856,0.315973,0.431538,0.650060,-0.295798,-0.191153,0.263350,0.250815,0.204566,0.150298,0.059612,-0.036993,0.094416,0.146683,0.532770', '4301215', '30345227', '1307748', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947080', '赶尽杀绝', '动作', '漆黑的夜里，史密斯（克里夫•欧文 Clive Owen 饰）无意中被卷入了一场黑帮的追杀，穿越激烈的枪林弹雨，他解救了一个在襁褓中的婴儿。婴儿的啼哭，让这个功夫了得的铁汉遭遇了难言的尴尬。除了在超市购置婴儿用品之外，他还得解决婴儿的喂奶问题。这时，他想到了在妓院工作的朋友DQ（莫妮卡•贝鲁奇 Monica Bellucci 饰），并强行赶走了嫖客，把婴儿托付给她。DQ其实对史密斯怀有深情，却一直没有机会表白。在蜂拥而至的黑帮暴徒来临之际，两人终于坦诚相见，并肩作战，照顾婴儿。经过史密斯的调查，他们发现想要加害婴儿的黑帮其实跟军火商有关系，而且他们还雇佣了很多代孕妈妈。史密斯隐隐觉得这背后隐藏着一个不可告人的秘密，于是他决定铤而走险，一场正邪较量由此展开……©豆瓣', '克里夫·欧文', '迈克尔·戴维斯', 7.4, 47881, 'tt0465602', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1708240488.jpg', 1.1, 5.1, 33.9, 42.9, 17.1, '0.364895,-0.029619,-0.916128,0.333206,-0.107744,-0.155112,0.944632,0.063980,-0.517952,-0.344859,0.276848,0.555489,-0.352897,0.119708,0.104967,-0.096115,-0.223438,-0.852800,-0.161138,-0.040895,-0.246452,-0.384845,-0.431226,-0.245555,-0.035378,-0.294956,0.315221,0.144363,-0.275645,0.366284,0.256439,0.056984,-0.143582,0.594912,-0.184912,0.001790,0.135178,0.226485,-0.290248,0.234875,0.056205,-0.152615,-0.059654,0.236235,-0.042354,0.685773,0.521635,-0.214344,-0.024834,0.103409,0.103458,-0.148084,-0.170964,0.176530,0.399182,-0.095838,0.127396,0.010969,-0.290362,-0.020889,0.201248,0.122607,-0.818047,0.112646,0.093328,0.315505,-0.557451,0.399180,0.023404,0.195250,0.172793,-0.206437,0.266019,0.497910,0.080626,0.377375,-0.114933,0.196773,-0.772359,0.109965,0.595415,-0.173009,0.140234,0.251499,-0.167673,-0.427436,0.158940,-0.064103,-0.341707,-0.047429,0.586831,-0.130358,-0.641915,0.175850,-0.632551,-0.096883,-0.101671,-0.074838,-0.134934,-0.398967,-0.039968,-0.502691,-0.201321,-0.190517,-0.433929,0.079633,0.043006,-0.159771,0.622876,-0.867181,0.235133,0.903147,0.262145,-0.298379,0.509154,0.223907,0.219119,-0.191660,-0.043624,0.040724,-0.059246,0.160210,0.396291,0.398211,-0.055621,-0.212768,-0.294973,0.173710', '35073886', '3005387', '1306801', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947089', '投名状', '剧情', '清末战火连绵民不聊生，大哥（李连杰 饰）被同僚出卖，所带军队无一生还。因为装死而活下来的大哥遇见了离家出走的莲生（徐静蕾 饰），二人一夜取暖后，莲生不告而别。大哥在街道上被三弟（金城武 饰）发现并带回村，发现竟是二虎（刘德华 饰）的妻子。被贫穷饥饿所折磨的农民在憨厚的二虎与忠诚的三弟的带领下，劫抢官银，导致官府半夜报复。大哥乘机鼓动大家参加军队赚来军饷粮食，三人纳投名状结兄弟义，浩浩荡荡地带着一百零八人出发从军。这支兄弟军不要命的拼劲，拿下不少胜仗。只是爬得越高，大哥的野心越大，二虎与三弟再也无法管束，分歧渐生；而大哥与莲生的感情被三弟发现，三弟误以为莲生是兄弟反目的原因，想借杀大嫂来解救二虎。面对朝廷的欺诈、官府的黑暗、野心的膨胀，曾经纳过投名状的三兄弟最终自相残杀……©豆瓣', '李连杰', '陈可辛', 7.6, 219052, 'tt0913968', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167464205.jpg', 0.5, 3.8, 31.7, 41, 22.9, '0.089116,-0.308628,-0.352392,0.222529,0.091787,-0.372576,0.285118,0.167823,-0.454918,-0.072007,0.210692,0.403957,0.192670,-0.045343,-0.033729,-0.294633,0.208367,-0.443008,-0.206144,0.034090,-0.006804,-0.342420,-0.006172,-0.127258,-0.058540,-0.180330,0.516866,0.242205,-0.148331,0.504459,0.255590,0.119784,-0.145002,0.344223,-0.203604,0.175911,-0.326290,0.035555,-0.447148,0.011990,-0.100793,-0.234313,-0.229917,-0.060255,-0.033516,0.154794,0.634233,-0.218129,-0.037994,-0.157175,0.158125,-0.297602,-0.004612,-0.106244,0.265795,0.059826,0.137856,0.439689,0.112368,-0.177140,-0.044987,0.066566,-0.357742,0.113615,0.136884,-0.148998,-0.720105,0.387687,0.081708,-0.012608,-0.017443,-0.157440,0.327268,0.480413,-0.077048,0.234648,-0.346628,-0.140618,-0.557919,0.153437,0.757025,-0.446069,0.379105,-0.170984,-0.001937,-0.063408,0.340252,-0.392980,-0.464491,0.101463,0.293536,-0.148099,-0.155800,0.257907,-0.605103,0.005538,-0.264402,0.090230,0.064120,-0.334303,0.158146,-0.196923,-0.222407,-0.211432,-0.130622,0.330870,0.417831,-0.064441,0.321148,-0.504009,0.113772,0.219816,0.563363,-0.704811,0.352915,0.139046,-0.092276,-0.020771,-0.207318,0.018363,0.162772,0.149275,0.292168,-0.104689,-0.185129,-0.051298,-0.238648,0.022254', '1296978', '1308035', '1297710', '1301376');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947091', '三国之见龙卸甲', '剧情', '三国乱世，战火纷争。面对魏军强势压境，初任工兵的赵云（刘德华 饰）主动请缨，借助军师诸葛亮（濮存昕 饰）以攻为守的策略，立下劫寨扰敌的大功。随后的长坂坡一战，赵云单枪匹马杀入曹营救回幼主，从而一战成名。随后并被委以重任与黄忠老将军一起出征定军山，收取汉中，奠定蜀国基业。不过此役，由于黄忠心急想争头功提前出兵，却中了曹操的奸计伤亡惨重。危机之时，赵云及时赶到救出了黄忠和罗平安（洪金宝 饰），并在诸葛亮妙计的帮助下，烧掉曹军粮草扭转战局立下大功。赵云也因此荣升五虎上将，而身为同乡兄长的罗平安心中却是百般滋味。时间就在战争中飞逝而过，蜀国的五虎大将也先后辞世。在诸葛亮的再一次灭魏大计前，赵云坚持做先锋大将，却在凤鸣山前遇上曹操10万大军，面对人生的终极之战，赵云该如何应对？©豆瓣', '刘德华', '李仁港', 5.5, 72264, 'tt0882978', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1023572443.jpg', 10.2, 27.3, 43.9, 13.3, 5.3, '-0.295971,0.284461,-0.698937,0.492665,0.348691,-0.218781,0.032386,0.200265,-0.561125,-0.353065,0.294841,0.385427,0.042590,-0.190171,0.045627,-0.560448,-0.085430,-0.899984,-0.055113,0.078485,0.095743,-0.089151,-0.320905,-0.019391,-0.133428,-0.073190,0.798386,0.381825,-0.024860,0.648885,0.179064,-0.001912,0.017493,0.942073,0.360012,0.113142,-0.442080,0.042234,-0.711983,0.321920,-0.176947,-0.496082,-0.525751,-0.007474,-0.046605,0.248404,0.326393,-0.479196,0.076568,0.007586,-0.060478,-0.201122,0.231477,-0.096379,0.217818,-0.008661,0.012758,0.133840,0.084063,0.181239,-0.298839,-0.092400,-0.499352,-0.067423,-0.155890,-0.299153,-0.623249,0.382583,-0.089267,0.121219,0.082065,-0.439282,-0.028538,0.867782,0.574940,-0.071271,-0.306700,-0.061472,-0.339520,0.262618,0.586803,-0.282747,-0.030611,-0.476148,0.331034,-0.369999,0.314340,-0.349089,-0.217185,0.333427,0.583389,-0.095651,0.419659,0.256255,-0.062491,-0.150868,-0.516790,0.380438,0.002181,0.140515,0.337408,-0.436371,0.088072,0.006577,-0.491360,0.259504,0.520420,0.112824,0.251651,-0.581865,-0.486824,0.035098,0.195226,-0.778230,0.175097,0.419336,0.356933,-0.001066,0.130502,0.341019,-0.022234,0.306088,0.292982,-0.076188,-0.330819,-0.277821,-0.437474,0.333065', '1294693', '1302705', '34906611', '3264045');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947114', '跟踪', '惊悚', '黄文展“狗头”（任达华 饰）和何家宝“猪女”（徐子珊 饰）是香港CIB（Criminal Intelligence Bureau）的职员。CIB俗称香港警察中的狗仔队，里面人人行动低调样貌平凡，但却对罪犯有极其灵敏的嗅觉。狗头和猪女这次的任务是追踪珠宝劫案的疑犯陈重山（梁家辉 饰）。陈重山是个犯案“天才”，对躲避警察追捕有丰富经验和巧妙手段。这次CIB行动，比平时都更为艰巨。尽管已经警方十面埋伏，狗头和猪女都使出浑身解数，陈重山还是屡屡逃脱。一路的跟踪就好像猫捉老鼠，没完没了。陈重山似乎有神奇的力量，闻到警察追到身边的气味。眼看有警员在追踪过程中殉职，狗头和猪女心急如焚。©豆瓣', '任达华', '游乃海', 7.4, 43744, 'tt0901488', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1929460809.jpg', 0.4, 2.6, 36.5, 48.5, 12.1, '0.049696,-0.434935,-0.484724,0.408686,-0.197929,0.119776,0.623983,-0.248576,-0.517965,-0.244955,0.270903,0.209968,-0.225502,-0.209407,-0.031014,-0.287585,-0.048694,-0.630985,-0.091241,0.211685,-0.397947,-0.129275,-0.535771,-0.148162,-0.090001,-0.091589,0.243380,0.208371,-0.313956,0.529660,0.450272,0.075919,-0.374322,0.561836,-0.207808,0.001771,0.231802,0.025470,0.090528,-0.077901,0.199911,-0.455075,-0.194430,-0.080889,0.256083,0.469273,0.425721,-0.261840,-0.303585,-0.014665,-0.080992,-0.366582,-0.197016,0.130036,0.527112,-0.199536,0.305463,-0.131322,0.205764,-0.107206,-0.111660,0.051453,-0.693283,0.038854,0.322723,0.175059,-0.423386,-0.372960,-0.258180,0.418331,0.080144,-0.402242,0.119407,-0.333876,0.205736,0.248300,0.359097,0.208128,-0.738988,0.080652,0.529004,0.297516,-0.143894,-0.174010,-0.210894,-0.826666,-0.083672,-0.237672,-0.079297,0.054344,0.456953,-0.123309,-0.340491,-0.147269,-0.451362,0.198342,-0.000063,0.279922,-0.348030,-0.267197,-0.078898,-0.711865,0.145885,-1.005794,-0.093324,0.218422,0.218541,-0.300847,0.565804,-0.761464,0.001545,0.415185,0.053340,-0.376043,0.626154,-0.238664,-0.166182,-0.303189,-0.054979,-0.316205,0.476740,0.298596,0.406235,0.468164,-0.091614,-0.521649,-0.101316,0.345837', '26354526', '25928069', '1304318', '26757951');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947144', '美味情缘', '剧情', '凯特（凯瑟琳·泽塔-琼斯 Catherine Zeta-Jones 饰）天生丽质，是一所餐厅里杰出的主厨，她是个十足的工作狂，因为工作她的生活变得十分刻板，没有一丝火花。对自己的手艺非常自信的她常常都坚持己见，老板只好强迫她去看心理医生。凯特的妹妹因车祸而逝世了，留下年幼的女儿祖需要凯特照顾。妈妈离开后，祖变 得越来越封闭。无论凯特怎么努力，祖还是与阿姨保持距离。此时餐厅里请来了新的厨师尼克（艾伦·艾克哈特 Aaron Eckhart  饰），工作态度完全有别与凯特，这使凯特无法接受，但他却有能耐使不喜欢吃正餐的祖乖乖吃饭。凯特不得不对尼克另眼相看，此后因为祖的关系他们约会渐多，凯特与尼克之间也产生了微妙的情缘，就连凯特与祖之间的关系也大大改进了。但这时，两人在工作上却出现了分歧，感情受到了挑战……©豆瓣', '凯瑟琳·泽塔-琼斯', '斯科特·希克斯', 6.9, 52715, 'tt0481141', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1144496241.jpg', 0.5, 5, 51.9, 34.1, 8.5, '0.301111,-0.104608,-0.706469,0.459885,-0.036172,-0.513203,0.723568,0.311399,-0.692371,-0.474070,-0.177205,0.751952,-0.227070,0.300850,0.092571,-0.137723,-0.306365,-0.509420,0.032324,-0.135173,-0.087269,-0.762093,-0.196884,-0.205207,-0.280535,-0.310920,0.216921,-0.393850,-0.214511,0.443997,0.083207,0.033552,0.415065,0.714938,0.026840,-0.116196,-0.063643,-0.079371,-0.118400,-0.006035,0.472240,0.111718,-0.114644,0.194470,0.503996,0.513855,0.438785,-0.190411,-0.302986,0.029154,0.132699,0.005749,0.080324,0.268924,0.212509,-0.103914,0.190840,0.366661,-0.171890,-0.081434,-0.151352,-0.036043,-0.648785,0.115662,0.032485,0.187142,-0.704972,0.553769,-0.084894,-0.284734,0.229824,-0.543291,0.162511,0.181358,0.298812,0.347328,-0.140087,0.043891,-0.392053,-0.275777,0.713545,0.153939,-0.042233,0.382617,-0.547854,-0.397074,-0.188543,-0.175876,-0.491659,-0.020532,-0.131433,0.204944,0.100671,0.347559,-0.368553,-0.209839,-0.216038,-0.004961,-0.014509,-0.501554,0.135365,-0.714650,-0.069649,-0.807542,-0.342425,-0.189718,-0.039832,-0.268526,0.696037,-1.027888,0.121434,0.261029,0.456610,-0.385840,0.859283,0.309725,0.135207,-0.265225,-0.176132,0.171672,-0.287430,0.102138,0.346430,0.359869,0.293926,0.012657,-0.094978,0.419113', '1302384', '1308755', '1303112', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947265', '落叶', '喜剧', '在未来的某一天，一对男女Retro（山口胜平 配音）和Pandy（本田贵子 配音）在一片荒野中醒来，却发现自己不但赤身裸体而且丧失了记忆。二人来到了东京闹市中肆意抢劫衣服和食物，经过一番大战后，两人被捕，并被投放到月球上的监狱“Dead Leaves”。经过一段短暂的禁闭生活后，他们发现这座监狱是一所克隆工厂。两个看守员随意杀害克隆人，于是Retro和Pandy萌生了越狱的念头。Retro和Pandy轻而易举地解开了身上的锁，更不可思议的是，他们居然对这座监狱了如指掌。他们的真实身份究竟是什么？©豆瓣', '山口胜平', '今石洋之', 8.6, 7098, 'tt0439533', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453769222.jpg', 0.5, 1.2, 11.9, 40.4, 46, '0.397245,0.086203,-0.811136,0.384014,-0.046168,-0.020868,0.987875,-0.299639,-0.733082,-0.240860,0.219633,0.782134,-0.406583,0.341445,0.069012,0.007373,-0.559781,-0.826795,-0.279700,-0.324412,-0.580732,-0.452476,-0.301442,0.003268,0.041003,-0.123580,0.644807,0.434652,-0.174259,0.437218,0.032684,0.168502,-0.494918,0.442685,-0.146092,0.182881,0.358784,0.041446,-0.051431,0.184651,-0.287308,-0.392465,-0.135660,0.111633,-0.117113,0.279483,0.809445,-0.140468,-0.609062,0.028605,0.247325,-0.261763,-0.331843,0.231771,0.422682,-0.012946,0.172083,0.245644,-0.284288,0.049410,-0.058599,-0.035661,-0.573571,-0.254901,-0.114924,0.011424,-0.568186,0.371660,0.072622,-0.194195,0.085359,-0.379337,0.159954,0.188933,0.261581,0.547721,-0.345689,-0.096734,-0.725829,-0.044990,0.619800,-0.248602,-0.106847,0.415252,0.118822,-0.489505,-0.248391,0.065413,-0.066785,-0.163980,0.370322,0.104176,-0.325810,0.131922,-0.594125,0.087113,-0.434958,-0.440939,-0.020390,-0.224134,-0.201517,-0.655520,-0.170009,-0.498990,-0.387308,0.261542,0.021686,-0.226269,0.339643,-0.872073,0.263149,0.417944,0.289461,-0.343209,0.417751,-0.047635,0.308799,0.024324,-0.099541,0.011530,0.398873,0.509435,0.262501,0.566278,-0.263960,0.022899,-0.866565,0.357386', '21619567', '1296534', '1908318', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947266', '情键四分钟', '剧情', '年届八十的克鲁格夫人（Monica Bleibtreu）有极深的钢琴造诣，因为藏有不为人知的青春秘密，她六十年来如一日地在一所女囚监狱教授钢琴，不在乎有无薪水，也不在乎学生的多寡。费劲周折将一架崭新的钢琴搬到监狱后，她的钢琴课却因一名学生的自杀面临被终结的危险。替人顶罪的叛逆女孩杰妮（Hannah Herzsprung）要求学钢琴，但因举止粗鲁遭到克鲁格夫人的拒绝，前者自顾自地弹下流畅、激情、放肆的音符，后者发现她在音乐上不可限量的才华，定下苛刻条件答应教她，又强迫她去参加一个专门挖掘21岁以下的天才钢琴师的大赛。慢慢地，音乐冲破了两人巨大的年龄差距，她们曾受过深重创伤的心灵也渐渐通过彼此获得慰藉，然而，一切并非表面般风平浪静。©豆瓣', '莫妮卡·布莱布特罗伊', '克里斯·克劳斯', 8.5, 8813, 'tt0461694', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p487011593.jpg', 0.3, 1.3, 13.9, 44.2, 40.4, '0.371584,0.238788,-0.706969,0.603618,-0.401825,0.013827,0.804915,0.017485,-0.391875,-0.285971,0.490366,0.675681,-0.119426,0.164679,0.053388,-0.215691,0.060649,-0.517257,0.143577,-0.150151,-0.100117,-0.542309,0.013778,0.021243,-0.234483,-0.428968,0.676049,-0.078349,-0.268416,0.398795,0.002990,-0.006798,0.308793,0.204680,-0.216878,-0.165224,0.023445,0.166977,0.205842,0.043394,0.061675,-0.441352,-0.060901,-0.210691,-0.042135,0.364943,0.754656,0.059664,-0.078600,0.198088,0.635181,-0.093802,-0.014534,0.227485,0.317299,0.232729,-0.083984,0.345010,-0.188978,0.006012,-0.043888,-0.269110,-0.626095,-0.221497,0.247782,0.027632,-0.477740,0.598169,-0.110758,-0.167880,-0.234340,-0.256208,-0.194486,0.036907,0.193749,0.363652,-0.119562,-0.027274,-0.369900,0.155633,0.584672,-0.031356,-0.306990,0.219341,-0.420544,-0.654346,0.080595,-0.780413,-0.461981,0.006561,0.181446,-0.004669,-0.133560,0.029434,-0.356035,-0.005479,-0.235851,-0.128872,-0.105318,-0.393455,-0.073122,-0.421288,-0.058815,-0.317965,-0.360365,-0.116261,0.071762,-0.450623,0.887120,-0.721896,0.278969,0.534835,0.230022,-0.244835,0.675103,0.005160,0.039160,0.058377,-0.210881,0.292413,-0.072946,0.247387,0.092784,0.472020,0.037599,-0.063158,-0.242230,0.335099', '27602116', '24284209', '3811356', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947270', '天狗', '剧情', '伤残军人李天狗（富大龙）复员后，听从组织安排携带妻子桃花（朱媛媛）和儿子来到偏远山区当起国有林场的护林员，他没想到的是，眼前淳朴善良的农民发家致富的招数竟是乱砍乱伐乱卖林区的树木，而被当地人称为“三条龙”的孔家三兄弟是始作俑者兼幕后推手。为履行自己的护林人职责，李天狗开始了一个人的战斗，在这一过程中，他遭遇的威胁一次比一次升级（桃花甚至遭到侮辱），可是，他始终没忘记自己是一名共产党员，用自己的实际行为谱写了一曲生命赞歌。©豆瓣', '富大龙', '戚健', 8.8, 32521, 'tt0830838', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1379497824.jpg', 0.2, 0.7, 8.8, 41.2, 49.1, '0.072950,-0.030855,-0.787829,0.872515,-0.478504,-0.126893,0.866802,-0.180527,-0.417174,-0.171875,0.365291,0.519683,0.073986,0.175180,0.100703,-0.031961,0.030462,-0.494014,-0.295140,0.124287,-0.326328,-0.294622,-0.180322,-0.265350,-0.294715,-0.140759,0.532625,0.309702,-0.403509,0.126326,0.217323,0.139279,0.206182,0.359624,-0.274232,0.102501,0.065659,-0.028584,-0.027441,0.177002,-0.072080,-0.389351,-0.263150,0.300274,-0.139203,0.519954,0.748093,-0.279663,-0.205121,-0.665261,0.313641,-0.338887,0.097331,-0.005312,0.541555,-0.240472,0.137081,0.088467,0.018231,-0.180736,0.076376,-0.174543,-0.930112,-0.124898,0.092598,-0.020499,-0.763854,0.233579,-0.130054,0.064199,0.053567,-0.350120,0.300307,0.078444,0.479750,0.402822,-0.167043,0.017597,-0.472415,0.283730,0.946581,-0.131270,-0.340229,0.154401,-0.457105,-0.560529,0.090256,-0.254041,-0.334652,-0.010009,0.234506,-0.211018,-0.002617,0.079461,-0.478202,-0.148876,0.018546,-0.280668,-0.017914,-0.337494,-0.341883,-0.289416,0.051432,-0.489348,-0.263709,0.244565,0.154229,-0.358842,0.683861,-0.796019,0.068355,0.335383,0.112254,-0.594456,0.563673,0.167141,0.142276,-0.168802,-0.069702,0.085247,0.239726,0.429823,0.393050,0.141201,-0.094963,-0.071227,0.008711,0.436024', '1301022', '30163500', '26981174', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947282', '奇异的恩典', '剧情', '年仅21岁的威廉·威伯福斯（艾恩·格拉法德 Ioan Gruffudd饰）在好友威廉姆·彼特（本尼迪克特·康伯巴奇 Benedict Cumberbatch饰）的劝说下加入英国议会。两人共同领导了反奴隶运动，与反对者展开激烈的斗争。然而威伯福斯拟定的关于反黑奴的议案还是被国会否定了。身心疲惫的威伯福斯被议会的明争暗斗弄得心力交瘁，患上大肠炎。1797年，当他来到乡下朋友家静养的时候，遇见了他的崇拜者芭芭拉·史普纳（萝玛拉·嘉瑞 Romola Garai饰）。威伯福斯向她讲述了他所为之奋斗的事业，两人相爱并结了婚。终于，在1807年威伯福斯的议案得到部分通过，坚守反黑奴运动的队伍也开始逐渐壮大。本片根据英国政治家、改革家，废除奴隶制倡导者威廉·威伯福斯的人物原型改编，讲述他在18世纪的英国国会长期坚持反黑奴运动并与反对者展开斗争的故事。影片使用电脑技术将过去影片与现在影像结合在一起，上演一场关于正义与邪恶较量的史诗。', '艾恩·格拉法德', '迈克尔·艾普特', 8.2, 6254, 'tt0454776', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p721368381.jpg', 0.4, 1.4, 18.5, 48.7, 31, '0.371825,-0.152045,-0.524999,0.392137,0.250088,-0.495679,0.522846,0.170379,-0.431232,-0.200208,0.265981,0.602256,-0.352057,-0.048839,0.470363,-0.078662,-0.636910,-0.795258,-0.043864,0.201205,0.064480,-0.519828,-0.138610,-0.241151,-0.260817,-0.543877,0.694888,-0.048398,-0.261941,0.306606,0.298902,0.274801,-0.028595,0.165633,0.180299,0.004706,0.178030,-0.253519,-0.435081,0.098519,0.178108,-0.150221,-0.317376,0.050125,0.058264,0.369972,0.518219,-0.437601,0.311498,-0.125951,0.368070,-0.186447,-0.132782,0.137955,0.201441,0.287979,-0.002237,0.470104,-0.071263,-0.039768,-0.217091,-0.124228,-0.577665,-0.049693,-0.127065,0.338037,-0.496008,0.521515,-0.265048,0.050686,-0.001380,-0.240334,-0.075017,0.598094,0.249698,0.394169,-0.162304,-0.115526,-0.346160,0.205214,0.503940,0.094495,-0.411379,0.179690,-0.240097,-0.481239,-0.174458,-0.300198,-0.193865,-0.227340,0.296855,-0.174021,-0.085434,0.665846,-0.883522,-0.190735,-0.421575,-0.308636,0.179593,-0.274347,0.020538,-0.760035,-0.326715,-0.213815,-0.142270,-0.021487,0.070500,-0.185134,0.662000,-0.751367,0.248783,0.495657,0.378075,-0.346335,0.370371,0.036773,0.192471,-0.278889,-0.047595,0.328888,0.027494,0.250372,0.206558,0.396994,0.097557,-0.018023,-