INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947549', '生死狙击', '剧情', '这是一部谍中谍式的电影，不过主角换成了狙击手。美国退役优秀狙击手鲍勃（马克•沃尔伯格 Mark Wahlberg 饰）正在阿肯色州享受退役后的休闲时光，不料，平地生波，他的前上司前来拜访他，希望他能接受一项新的任务――在总统街头演讲那天充当隐形狙击手暗中保护总统。虽然十万分不情愿，但禁不住上司的游说，鲍勃最终答应了。总统演讲那天，鲍勃正在仔细观察着四周情况时，突然会场遭到枪手袭击，总统身边的衣索比亚主教被杀。鲍勃被当成暗杀者遭遇警方追捕。心知成了替罪羔羊，鲍勃在身中两枪的情况下奋力逃走了。鲍勃此时唯一的出路就是找出幕后的真凶，为自己洗刷罪名。©豆瓣', '马克·沃尔伯格', '安东尼·福奎阿', 7.8, 147093, 'tt0822854', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1722251312.jpg', 0.2, 1.6, 25.2, 52.2, 20.8, '-0.030396,0.008072,-0.493580,0.474045,-0.013950,-0.128962,0.366434,0.175568,-0.434044,-0.467646,0.423088,0.604093,0.035174,0.038182,0.343084,0.021181,-0.571514,-0.618542,-0.127625,-0.035054,-0.287393,-0.310531,-0.330893,-0.457492,0.086259,-0.089850,0.584894,0.028361,-0.135393,0.290692,0.417995,0.601034,0.192368,0.317516,-0.077417,-0.182808,0.537366,-0.342892,-0.427448,0.528071,0.095521,-0.263465,-0.140257,0.196987,0.002720,0.560676,0.441470,-0.240220,-0.149093,-0.188787,0.113832,-0.429221,0.235060,0.235759,0.418918,0.133678,0.182527,0.077357,0.028944,0.011449,0.023393,-0.048703,-0.608986,-0.089986,-0.031833,-0.021319,-0.240768,0.078552,-0.386776,0.325874,0.082656,-0.142164,0.207259,0.135856,0.301966,0.127582,-0.089696,0.121401,-0.509755,0.093342,0.582081,0.090607,-0.101043,0.115927,-0.137278,-0.312731,0.168455,-0.306524,-0.250079,0.063533,0.456596,-0.066516,-0.248717,0.001416,-0.192245,-0.236743,-0.556260,-0.139766,-0.254175,-0.358286,-0.142282,-0.714401,0.120750,0.263178,-0.100070,-0.054453,-0.086406,-0.255244,0.406702,-0.613359,0.217586,0.792380,0.012320,-0.370601,0.546097,0.194489,0.233475,-0.198420,0.089275,-0.072145,0.413716,0.401428,0.140363,0.103671,-0.103999,-0.372960,-0.270615,0.104773', '2369613', '25723905', '1307442', '1293619');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1947719', '特工的特别任务', '喜剧', 'Henry（科林•汉克斯 饰）有个不修边幅的胖母亲（梅格•瑞恩 饰），他成为联邦调查特工再次回到家中，他被母亲的改变下了一大跳。母亲变得窈窕而富有魅力，性格也变得开朗乐观，就连名字都改成了Mathy。Henry带回的未婚妻Emily（塞尔玛•布莱尔 饰）与Mathy相处甚欢，只是Henry对于母亲的改变无所适从。正当Henry努力适应母亲的改变时，一名潇洒的男人Tommy（安东尼奥•班德拉斯 饰）走进了母亲的生活，他们发展迅速。Henry竟发现这名Tommy跟一个艺术品偷窃团伙有关，Henry面对母亲与事业的发展，再次陷入两难，最后他还是同意上司在自家安装偷听器。他们一路调查Tommy，更把真相告诉了Mathy。Tommy与同党想尽办法偷取了雕像，Tommy却被同党抛弃了。他马上想到了危险的Mathy，他只好向Henry说出自己的真实身份，一起合力营救Mathy……', '安东尼奥·班德拉斯', '乔治·加洛', 5.9, 14324, 'tt0780534', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p484324060.jpg', 3.5, 19.2, 59.4, 15.1, 2.8, '0.342816,0.060661,-0.554618,0.417403,-0.290864,-0.398422,0.662947,0.080384,-0.475110,-0.367148,0.092856,0.769018,-0.154764,0.234783,0.417976,-0.037727,-0.414935,-0.823921,0.053243,0.139071,-0.086634,-0.487003,-0.279647,-0.249602,-0.039954,-0.269103,0.548525,-0.066374,-0.359773,0.339972,0.263889,0.339857,-0.144884,0.368186,-0.064364,0.085298,-0.066267,-0.031260,-0.188863,0.078686,0.079172,-0.174561,-0.005659,0.169481,-0.040203,0.368848,0.481467,-0.201134,-0.519168,-0.031512,0.372457,-0.093710,-0.127223,0.334854,0.153814,0.144467,-0.153820,0.222242,-0.440840,-0.017902,0.062874,0.012516,-0.679340,0.366326,0.113618,0.168348,-0.657997,-0.131664,-0.151900,-0.121715,0.162966,-0.516575,0.201974,0.399191,0.254830,0.453398,-0.237977,0.146419,-0.300571,-0.011467,0.787460,0.116515,-0.246335,0.135017,-0.082818,-0.192102,0.133367,-0.264486,-0.294867,0.065058,0.228884,0.157849,-0.002295,0.206165,-0.393141,-0.273931,-0.361351,-0.128992,-0.069593,-0.557567,0.014235,-0.364141,-0.300705,-0.276606,-0.374535,0.081217,-0.263797,-0.255145,0.600900,-0.661914,0.171873,0.404360,0.407024,-0.827147,0.362395,0.012648,0.225171,-0.270664,0.040746,0.436613,0.166142,0.062882,-0.121010,0.144518,0.064987,-0.136205,-0.368407,0.160391', '26