INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1948506', '精灵宝可梦：梦幻与波导的勇者', '动作', '小智（松本梨香 配音）一行人继续着磨练技艺的旅途，他们来到了欧鲁德朗城，这里正在举行为了纪念百年前阻止了战争的勇者亚朗而设置的对战祭典。小智带着皮卡丘（大谷育江 配音）勇敢参战，并且最终凭借着强大的实力夺得了头筹，获得了珍贵的宝物“勇者之杖”。然而，让小智没有想到的是 ，传说中的神奇宝贝路卡利欧竟然从杖中现身，它的重现江湖揭开了一个隐藏了百年的秘密。与此同时，神秘莫测的神奇宝贝梦幻现身会场，掳走了皮卡丘和喵喵。为了找回皮卡丘，小智和贝路卡利欧踏上了旅途，他们的终点是世界初始之树，在那里隐藏着一切问题的答案。©豆瓣', '松本梨香', '汤山邦彦', 8.1, 4922, 'tt0875609', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2171959876.jpg', 0.3, 1.7, 20.5, 45.8, 31.7, '-0.107049,0.405108,-0.518602,0.758696,-0.131419,-0.155332,0.342003,-0.158437,-0.274661,-0.285852,0.042698,0.467373,-0.113322,0.087007,0.334814,0.114744,-0.247831,-0.450933,-0.052005,-0.190335,-0.332903,-0.344778,-0.459085,-0.149997,-0.098046,-0.540452,0.651337,0.509308,-0.299192,0.459749,0.305974,0.180801,-0.306432,0.386240,-0.136190,-0.030138,0.286111,0.150092,-0.157609,0.314546,-0.231158,-0.164205,-0.264091,0.456459,0.147119,0.043976,0.445771,-0.590969,0.043812,0.031348,0.230519,-0.351543,0.024204,-0.235223,0.246028,-0.034255,0.037620,0.086199,-0.014837,0.021589,0.204736,-0.284677,-0.869276,-0.158688,-0.053028,-0.016025,-0.486531,0.377854,-0.022845,-0.009873,0.386579,-0.337163,0.343629,0.303952,0.425373,0.045250,-0.011369,-0.111873,-0.545004,0.046259,0.484474,-0.405552,-0.210403,0.244196,0.010447,-0.685791,-0.283843,-0.273468,-0.271993,0.068632,0.576749,0.320881,-0.010160,0.072942,-0.739960,-0.009805,-0.113064,-0.298376,0.091211,-0.428317,-0.254537,-0.524533,-0.037722,-0.189281,-0.355013,-0.027494,-0.199327,-0.483276,0.843377,-0.828781,0.237586,0.716438,0.118742,-0.083422,0.659783,-0.293239,0.069578,-0.224713,0.008976,0.234489,0.045230,0.496130,0.242753,0.191432,0.035080,0.026757,-0.687382,0.782038', '3769423', '1870681', '1793491', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1948937', '野兽家园', '剧情', '本片改编于美国插画作家莫里斯•桑达克（Maurice Sendak）1963年出版的同名儿童画书。小男孩马克斯（马克斯•莱克兹 Max Records）精力旺盛无处发泄，不满姐姐克莱尔（派媲塔•艾莫里琪丝 Pepita Emmerichs 饰）的忽视和妈妈（凯瑟琳•基纳 Catherine Keener 饰）的管教。在一次与妈妈的争吵中，马克斯离家狂奔而去，到河边独自驾驶小船，在海面航行了两天两夜，到达了一个神秘岛屿。岛上生活着一群头上长角、身材高大的毛绒绒怪物们，它们有的脾气暴躁，有的性情温顺，还有的胆小怕事。为了不被吃掉，马克斯骗怪物们说自己是维京人的国王，来到岛上也要当它们的国王。单纯的怪物们相信了马克斯，兴高采烈的奉他为王，在岛上建筑新居。但令马克斯意外的，却是名叫卡罗的怪兽（詹姆斯•甘多费尼 James Gandolfini 配音）与怪兽KW（劳伦•艾波罗丝Lauren Ambrose 配音）之间的矛盾……', '马克思·瑞考德兹', '斯派克·琼斯', 7, 17067, 'tt0386117', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p780555143.jpg', 1.9, 8.9, 40.5, 34, 14.7, '0.279147,-0.099358,-0.715313,0.658412,0.021261,-0.290437,0.868204,0.009294,-0.251779,-0.288031,0.015305,0.443919,-0.082978,0.221352,0.167784,0.048378,-0.231176,-0.348164,-0.050716,-0.136819,-0.231833,-0.289318,-0.240598,-0.569059,-0.213960,-0.486742,0.290780,-0.048048,-0.078580,0.489617,0.412593,0.392546,-0.018696,0.314637,-0.244704,0.095867,0.153757,-0.143588,0.141101,0.092830,-0.145766,0.099380,-0.153017,0.062133,0.250096,0.144203,0.829009,-0.386820,0.071287,-0.124773,0.015151,-0.209288,0.301083,-0.071401,0.598983,-0.339071,0.013330,-0.016831,-0.111339,0.093186,0.238536,-0.162893,-0.338008,0.061983,-0.183397,0.343325,-0.641332,0.325441,-0.095553,-0.112423,0.133425,-0.320736,0.060649,0.126484,-0.037793,0.431018,0.247148,0.178689,-0.543039,0.072253,0.502112,0.197962,-0.278249,-0.070925,-0.374155,-0.298518,0.034826,-0.199163,-0.470327,-0.161161,0.484077,-0.242811,-0.249030,0.325213,-0.742733,-0.009327,-0.396390,-0.241609,-0.165833,-0.489008,-0.138727,-0.609636,0.159321,-0.345781,0.027036,0.086813,0.034438,-0.067868,0.706119,-0.596269,0.396343,0.678872,0.257192,-0.272753,0.709798,0.034946,0.011925,-0.156278,-0.035956,0.194198,0.116136,0.119058,0.227364,0.443033,0.054254,-0.078143,-0.391565,0.557349', '21619567', '3055049', '3005387', '1308831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949005', '公主与青蛙', '喜剧', '蒂亚娜（Tiana）是个从不相信童话的女孩子，具有烹饪天赋的她最大的目标便是开一家属于自己的餐厅，多年来她一直努力赚钱，希望够自己的双手去实现梦想。可是就在她即将攒够钱的那天晚上，她遇到一只自称是王子马文（Naveen）的青蛙，他说自己是被影子人施了魔法并且许诺只要蒂亚娜吻他，那么他就可以帮蒂亚娜实现梦想。可是当蒂亚娜吻完青蛙，青蛙并没有变成马文王子，蒂亚娜却变成了一只青蛙。他们在躲避坏人的追赶时遇到喜欢演奏爵士乐的鳄鱼路易斯和荧火虫雷蒙，他们决定一起去密西西比河河口找女巫妈妈沃提帮忙。邪恶的影子人派出大批的影子杀手已经追上了这一行人，在紧要关头，妈妈沃提出现救了他们并且告诉了他们如果要变会人类，马文就必须去亲吻真正的公主夏洛特。可是此时马文在和蒂亚娜相处的过程中早已经爱上了这个执着的女孩子……本片无论从音乐和画面都融入大量新奥尔良元素，为影片创作音乐的兰迪·纽曼（Randy Newman)曾获奥斯卡奖，他本人就是新奥尔良人。', '阿尼卡·诺尼·罗斯', '罗恩·克莱蒙兹', 7.6, 56255, 'tt0780521', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1231072532.jpg', 0.3, 2.4, 34.7, 44.4, 18.3, '0.206715,-0.100373,-0.558701,0.437617,-0.379733,-0.291674,0.761429,0.015418,-0.200564,-0.162607,0.178290,0.779968,0.113556,0.097335,0.197106,0.261250,-0.309028,-0.663130,0.245600,-0.139038,-0.167754,-0.357761,-0.152686,-0.216011,0.167985,-0.384944,0.490189,-0.056086,-0.058802,0.204865,0.183351,-0.049081,0.075845,0.503784,-0.205072,0.121725,0.065436,-0.092643,-0.060382,0.429376,0.096140,0.114365,-0.222468,0.207400,0.003552,0.200492,0.457070,-0.364322,0.266571,0.005277,0.095453,-0.498915,0.258813,0.061419,0.189145,-0.332974,0.226357,-0.103089,-0.132527,-0.091735,-0.000595,-0.161837,-0.847613,0.136085,-0.045893,0.112832,-0.624873,0.120002,-0.083540,0.066712,0.217715,-0.474909,0.010358,0.161622,0.147713,0.279044,-0.165224,-0.077562,-0.637096,0.178539,0.681248,-0.074730,-0.188694,0.401067,-0.191139,-0.442991,-0.274920,-0.115453,-0.374920,-0.044412,0.297643,0.101767,-0.452079,0.158450,-0.486756,-0.079799,-0.297863,-0.172192,0.184248,-0.470938,-0.078268,-0.428238,-0.023394,-0.161320,-0.086071,0.052392,-0.011916,-0.333061,0.582063,-0.862986,0.359003,0.854824,0.377649,-0.322287,0.798983,0.007268,-0.210721,-0.157713,0.152176,0.319787,0.036834,0.209249,0.228755,0.405854,0.377445,0.11