INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949128', '突然有一天之第四层', '恐怖', '从事设计工作的单身妈妈蔡闵英带着6岁的女儿珠熙搬入某商品房的504室，由于迷信，所谓5楼就是4楼而已。大厦安静舒适，正适合闵英这样经常夜间工作的人。母女俩生活简单有序，波澜不惊。然而好景不长，奇怪的响动搅扰了母女的生活。3楼的单身男子韩昌洙抱怨母子二人过于吵闹，一向喜好安静的闵英对此倍感诧异，在她看来那吵闹声正是来自于楼下。不久，一个放高利贷的男子惨死电梯间，接着经常在家独处的珠熙举止也变得愈加孤僻和诡异。闵英的不安与日俱增，她隐约感到这栋大厦和所住的房间有些问题。但当她想逃离时，却发现事情并非如此简单……©豆瓣', '金裕贞', '权昊英', 6.4, 6555, 'tt0927627', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1648254323.jpg', 1.4, 10.5, 60, 21.5, 6.6, '0.506627,-0.073261,-0.863096,0.226243,-0.122402,-0.118183,0.909101,0.513461,-0.776199,-0.695589,0.156237,0.518714,-0.055989,0.476672,0.219006,-0.026655,-0.152041,0.050949,-0.261530,-0.155441,0.145002,-0.159613,0.243616,-0.539884,-0.057186,-0.313748,0.248246,0.180108,-0.325912,0.555619,0.235360,0.321806,-0.287765,0.623276,-0.209276,-0.286036,0.007757,0.307633,-0.210319,-0.424703,-0.166140,-0.015195,-0.241764,-0.020819,0.097309,0.330448,0.535735,0.064100,-0.721733,0.400584,0.433878,0.160268,-0.292724,-0.083733,0.462110,0.052571,0.309034,-0.023205,-0.304997,0.005641,-0.232068,-0.089757,-0.428908,0.254513,0.258308,-0.002206,-0.225924,0.470513,0.050630,-0.145596,0.074424,-0.270168,0.186736,0.268379,0.171072,0.690609,-0.125842,0.071757,-0.361078,0.020522,0.605951,0.239520,-0.377564,0.671522,-0.414569,-0.420549,0.236253,-0.090276,-0.457855,-0.253052,0.053558,-0.050563,-0.152389,-0.082110,-0.365047,0.285234,0.073632,-0.115059,-0.086642,-0.682002,-0.339149,-0.522567,-0.103222,-0.462339,-0.225948,0.229082,-0.286032,-0.164421,0.270196,-0.875895,0.239933,0.284864,0.276704,-0.426388,0.637038,-0.057791,0.123944,-0.023296,-0.416088,0.258797,-0.054198,0.148017,-0.028284,0.423934,-0.337533,-0.103684,-0.692745,0.084918', '26704621', '2052978', '27617348', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949312', '全民超人汉考克', '动作', 'Hancock（Will Smith饰），是刀枪不入的全民超人，犯罪分子对他闻风丧胆。然而这位全民超人每次与犯罪分子对峙都闹得惊天动地，造成严重的破坏，对市民的生命和公共财产都是巨大的威胁。这也就是虽然他有着独一无二的能力却仍然得不到大众认同的原因。他暴躁易怒又不辩解的个性更是激化了矛盾。这天公关经理Ray Embrey（Jason Bateman饰）十分倒霉，不仅他的全球爱心理念推销不出去，更在回家的途中被塞车堵在了火车轨道上，险些就被火车一碾而过。Hancock及时出现救了他一命，不可阻挡地破坏了火车和现场的交通，惹起众怒。Ray却灵光一闪，决定包装Hancock，把他塑造成为一位全民爱戴的英雄。没想到，最大的反对竟然来自他的妻子Mary（Charlize Theron饰），她坚持要Hancock离开她的家庭。事情发展下去，牵扯出令人惊讶的缠绵前缘。', '威尔·史密斯', '彼得·博格', 6.9, 180965, 'tt0448157', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1133205431.jpg', 0.9, 6.4, 49, 34.6, 9.1, '0.240606,0.125776,-0.918499,0.485710,-0.145417,-0.137167,0.813241,0.102845,-0.311144,0.103118,0.343262,0.618698,-0.385351,-0.166834,0.231907,0.001824,-0.000940,-0.455593,0.072150,0.143363,-0.198306,-0.245424,-0.369447,-0.137518,-0.131988,-0.265648,0.389091,0.153859,-0.625260,0.321119,0.327454,0.136636,0.240549,0.792667,-0.193288,0.025570,-0.218583,0.127517,0.062483,-0.073398,0.165580,-0.478100,0.107620,0.526308,-0.161865,0.411642,0.350197,-0.220418,-0.353577,-0.020794,0.450708,-0.573784,-0.014851,0.193983,0.348642,-0.149730,0.063552,0.211622,-0.296095,0.015249,0.221663,0.218424,-0.991985,0.055882,0.060829,0.042058,-0.595076,0.592395,-0.178772,-0.222513,-0.130362,-0.229379,0.245451,0.187775,0.216495,0.364806,-0.212091,0.013164,-0.649965,0.084461,0.851556,-0.075885,-0.422378,0.227978,-0.474014,-0.284474,-0.114752,-0.510086,-0.407946,-0.181784,0.341092,-0.038231,-0.248303,0.281705,-0.399950,-0.057450,-0.255482,-0.227515,-0.119058,-0.351521,-0.054177,-0.281819,0.081661,-0.468108,-0.381807,0.262260,0.123168,-0.162600,0.747048,-0.753277,-0.174914,0.667204,0.400417,-0.752229,0.575295,0.374233,-0.086930,-0.054601,-0.192607,0.026159,0.046289,0.440567,0.100302,0.263926,0.200511,-0.175381,-0.132907,0.570139', '30163500', '1308206', '6874741', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949320', '我盛大的同志婚礼', '喜剧', 'Chuck Levine（Adam Sandler 饰）和Larry Valentine（Kevin James 饰）是同一个消防站的消防队员，二人在工作上默契十足，更是无话不谈的好兄弟。私底下，Chuck Levine是一个无女不欢的花花公子；而Larry Valentine却对已故前妻情有独钟，全心照料他们的一双小儿女。为了让孩子成为自己的人身保险受益人，Larry Valentine必须结婚，对女人兴趣缺缺的他，想出了一个“好主意”：和Chuck Levine扮成同性恋假结婚。乱哄哄的婚礼之后，两人的生活发生了翻天覆地的变化。为了应付政府官员的检查，他们住在了一起，并参加同性恋派对，面对抗议的群众慷慨陈辞，甚至大打出手，从“假玻璃”变成“真斗士”，在同性恋人群中知名度迅速扩大，但是也受到消防队同事的歧视。更要命的是，Chuck Levine似乎遇上了他的真命天女：为他们辩护的美女律师（Jessica Biel 饰）。两人暗生情愫，但是苦于，Chuck Levine的同志身份，无法进一步发展。事情很快超出了Chuck Levine和Larry Valentine的控制范围，怎样将生活纳入正轨，成为他们不得不想办法解决的问题。', '亚当·桑德勒', '丹尼斯·杜根', 7, 23221, 'tt0762107', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2483506095.jpg', 0.8, 5.1, 46.2, 37.9, 9.9, '0.267014,-0.253249,-0.534097,0.480612,-0.302440,-0.005911,0.701520,0.161634,-0.638904,-0.157008,0.024209,0.779672,-0.281128,0.077113,0.152616,-0.313105,-0.233710,-0.872780,0.034821,-0.004901,-0.229178,-0.604193,-0.101196,-0.302414,-0.262003,-0.168964,0.594992,-0.057690,-0.149354,0.206957,0.404477,0.035472,-0.061264,0.548338,-0.144960,-0.218530,-0.086373,0.142060,-0.495967,0.186611,0.095334,-0.049776,-0.070891,0.217127,0.080364,0.395618,0.552588,-0.148376,-0.350209,0.039319,0.316940,-0.460736,-0.071540,0.288887,0.262371,0.042863,0.245381,0.132013,-0.153585,-0.168802,0.131537,-0.097413,-0.723016,0.125894,0.256544,0.046334,-0.588462,0.530321,0.080084,-0.237769,0.055471,-0.144319,0.256774,0.452759,0.162382,0.348046,-0.425893,0.089457,-0.653626,0.086936,0.975718,0.186819,-0.151333,0.307406,-0.277934,-0.433681,-0.202638,-0.171292,-0.368228,-0.131211,0.026610,0.120175,-0.262819,0.292802,-0.473835,-0.057134,-0.273742,-0.251650,0.020224,-0.800573,0.137492,-0.355368,-0.188384,-0.440526,-0.357530,0.169530,0.191572,-0.269083,0.727460,-1.072066,-0.228785,0.345111,0.458761,-0.940366,0.634667,0.234309,0.253071,-0.344893,-0.431769,-0.078220,-0.060268,0.289366,0.104640,0.275335,0.000861,-0.153501,-0.337372,0.290027', '1293265', '30345227', '25721544', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949321', '布鲁克斯先生', '剧情', '探讨人性的双面性，展示残忍、阴暗的另一个自己。布鲁克斯先生（凯文•科斯特纳Kevin Costner 饰）是个成功的上流社会人士，热衷慈善，德高望重，家庭美满。这样一个满分男人，人格里却有着另人不为所知的一面：另一个他自称马歇尔，不断诱使布鲁克斯以杀人为乐。他陶醉于连环杀人的乐趣中，就如染上毒瘾，却不料在杀害一名夫妇的时候，被一名摄影师拍下全过程。摄影师以此来要挟布鲁克斯，怎料却被布鲁克斯反攻一着。因为事情蹊跷，引来了女警探特蕾西的怀疑。于是布鲁克斯先生开始了他下一步的计划。©豆瓣', '凯文·科斯特纳', '布鲁斯·A·埃文斯', 7.6, 30396, 'tt0780571', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2255762675.jpg', 0.5, 2.9, 30, 49.5, 17.2, '0.448728,0.144111,-0.358781,0.702665,-0.275825,-0.103575,0.920216,0.087042,-0.321640,-0.276226,0.324829,0.823098,-0.212175,0.224862,0.223863,0.028689,-0.083391,-0.631679,-0.208624,-0.129153,-0.173081,-0.391755,-0.534341,-0.230949,-0.172963,-0.167843,0.251538,-0.008907,-0.259630,0.371289,0.454317,0.466570,0.147790,0.382958,0.066712,0.013373,0.322226,-0.214015,-0.182403,0.198160,0.091462,-0.337792,-0.279010,0.351392,-0.560704,0.567618,0.517867,-0.333024,-0.125929,-0.338827,0.578127,-0.199569,-0.003432,0.451065,0.208832,0.030518,0.117289,0.225272,-0.083910,-0.000443,0.260550,-0.121743,-1.105913,-0.046196,-0.047359,0.247517,-0.452220,0.162053,-0.211220,-0.008232,0.064736,-0.248252,-0.129496,0.007258,0.419406,0.146778,-0.177419,0.012176,-0.186326,0.289356,0.635177,0.227047,-0.319590,0.220077,-0.251894,-0.261221,0.309553,-0.208507,-0.431251,-0.271560,0.427280,-0.231171,-0.031880,0.149230,-0.394409,0.041721,-0.411740,0.265168,-0.409074,-0.369187,-0.257080,-0.398089,0.046559,-0.050963,-0.352226,0.077957,0.145112,-0.353484,0.620948,-0.773006,0.099832,0.656759,0.000216,-0.361524,0.592897,0.220686,-0.001105,-0.130585,-0.395764,0.044176,0.236966,0.174083,0.012598,0.642577,0.003422,-0.264004,-0.171709,0.440028', '3785918', '1793491', '1874704', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949328', '心灵传输者', '动作', '羞涩内向的15岁高中生戴维•莱斯（Max Thieriot 饰）拥有灰暗的童年，母亲在他5岁时离家出走，父亲则粗暴蛮横，他在学校里还经常受到同学的捉弄。某天，他不慎跌入冰窟中，却由此发现自己拥有心灵传输的神奇能力。这项能力可以让戴维凭借想象瞬间从一个地方转移到另一个地方，地与地之间从此没有障碍。在此之后，戴维离开家独自居住，并利用这段时间学习掌握心灵传输的技术，而他首要目标锁定在抢银行上。多年后，戴维（Hayden Christensen 饰）因此过上随心所欲、养尊处优的自在生活。然而他的好日子即将走到尽头，一个名叫“游侠”的神秘组织专门追踪具有心灵传输能力的异能者。戴维成了被追击的对象……©豆瓣', '海登·克里斯滕森', '道格·里曼', 6.6, 53135, 'tt0489099', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p955763677.jpg', 2.4, 11.4, 49.2, 28.5, 8.5, '0.430984,0.293134,-0.710746,0.717255,-0.523737,-0.116023,0.699636,0.086137,-0.445239,-0.338000,0.039177,0.765937,0.011716,0.216383,0.204512,0.015383,-0.102692,-0.606670,-0.053006,-0.152546,-0.534832,-0.475930,-0.398169,-0.201247,-0.041350,-0.670567,0.631554,0.011712,-0.455682,0.318286,-0.119083,0.325063,-0.262367,0.508550,-0.246475,-0.176404,0.090328,0.178572,-0.054071,0.498054,-0.046584,-0.243831,0.168678,0.224616,-0.249547,0.346887,0.791060,-0.251400,-0.163766,-0.109375,0.336660,0.040045,-0.226827,0.065928,0.236482,-0.037728,0.034120,0.075367,-0.169458,0.137007,0.059827,-0.183815,-0.898464,-0.283465,0.016369,-0.159597,-0.439801,0.211855,0.093718,-0.211781,0.067696,-0.398445,-0.017395,0.247044,0.095261,0.396628,-0.397753,0.141465,-0.179435,0.040597,0.633685,-0.195019,-0.625018,0.464424,-0.192982,-0.378339,0.054466,-0.398411,-0.389386,-0.210600,0.203870,0.477687,-0.309326,0.057684,-0.527084,0.421575,-0.148094,0.117021,-0.025558,-0.412146,-0.153544,-0.599548,-0.227833,-0.391858,-0.314020,0.166765,-0.104451,-0.411454,0.597607,-0.834489,0.345410,0.720378,0.447096,-0.358303,0.778913,-0.167488,0.073379,-0.264552,-0.078456,0.469796,0.045806,0.658031,-0.066981,0.219433,-0.284353,0.023275,-0.396518,0.744560', '24733428', '1793491', '25932086', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949369', '巴黎', '剧情', '突发的心脏病让舞蹈演员皮埃尔（罗曼·杜里斯 Romain Duris 饰）不得不离开了热爱的舞台，除了失业所带来的沉重打击外，他的生命安全还时时受到病魔的威胁。爱丽丝（朱丽叶·比诺什 Juliette Binoche 饰）是皮埃尔的姐姐，为了成为一名合格的单身母亲，她不惜屡屡拒绝来自他人的求爱，即使对方是令她动心的好男人。巴黎，一座繁华而又落寞的城市，除了皮埃尔和爱丽丝，每分每秒，还有无数的人们在那里找到和遗失自己的希望和梦想。苦苦暗恋自己学生的教授，突然陷入中年危机的建筑师，甚至是整天絮絮叨叨的老板娘，每一个人都曾经有过一段五味俱全的传奇故事。当这些故事在这座城市里发生交汇的时候，他们开始相信，幸福终将在某一天敲响自己的房门。©豆瓣', '朱丽叶·比诺什', '塞德里克·克拉皮斯', 7.5, 9881, 'tt0869994', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1184349213.jpg', 0.4, 3.1, 33.7, 47.8, 14.9, '0.036804,-0.049773,-0.757301,0.553717,-0.160831,-0.195225,1.045988,-0.064556,-0.559481,-0.345705,0.318638,0.902977,-0.134773,0.601738,0.396980,0.022172,-0.134091,-0.717513,-0.004907,-0.142378,-0.240485,-0.455392,-0.402435,-0.341303,-0.200596,-0.397937,0.585808,0.192853,-0.219254,0.241257,0.230624,0.385585,-0.016708,0.597015,-0.423695,0.095326,0.041130,0.020701,-0.341358,-0.046201,0.055751,-0.240873,-0.144759,0.223040,-0.280867,0.161408,0.470570,-0.268879,-0.304503,0.005366,0.408367,-0.284591,-0.044927,0.111868,0.115654,-0.146006,0.400840,0.148449,-0.155393,0.053341,0.189258,-0.030969,-0.800235,-0.122781,0.215390,0.217011,-0.562837,0.464411,0.006566,-0.042936,0.327554,-0.181845,0.207650,0.349514,0.291093,0.535173,-0.420477,0.053079,-0.506222,0.276144,0.873228,0.031282,-0.365306,0.268038,-0.303714,-0.285466,0.029929,-0.143090,-0.787852,0.228816,0.082226,0.012457,-0.027342,0.212664,-0.643470,0.050838,-0.141005,-0.333561,0.116971,-0.389551,-0.247022,-0.578840,0.009940,-0.516272,-0.296363,0.127437,0.013651,-0.312984,0.841535,-0.883149,0.523510,0.502062,0.394370,-0.500783,0.757368,0.214276,0.181258,-0.030529,-0.303572,0.527397,-0.067455,0.410015,-0.123917,0.191831,0.071030,-0.060038,-0.373323,0.607746', '4275444', '30162520', '1308755', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949376', '夏日时光', '剧情', '三兄妹齐聚乡下为母亲Hélène（Edith Scob 饰）七十五岁生日庆祝，一家三代子孙满堂其乐融融。饭后母亲却对长子Frédéric（查尔斯·贝尔林 Charles Berling 饰）提及到自己死后如何处理遗产的事情，Frédéric有点烦躁，不愿母亲提起这个话题。然而Hélène坚持把所有的物件下落安排好，她告诉儿子这间祖屋将会卖掉，她用一生去尊敬的叔叔、画家保罗的的画作又该如何处理等等，Frédéric则坚持这件屋子将会被保留下来，留给孩子们去传承下去。几个月后，Hélène去世，一直在巴黎生活工作的Frédéric希望能保留祖屋，然而即将举家迁往中国工作的弟弟Jérémie（杰瑞米·雷乃 Jérémie Rénier 饰）和即将去纽约结婚组织家庭的妹妹Adrienne（朱丽叶·比诺什 Juliette Binoche 饰）因为不会再回到巴黎而赞成把祖屋卖掉。一切都如母亲所说的一样。Frédéric无奈地接受并着手处理事情。在屋子出手的最后一个月，Frédéric的孩子们在祖屋开了一个盛大的派对，青春在这里上演，对祖辈感情的传承也许将以另一种方式延续下去。', '朱丽叶·比诺什', '奥利维耶·阿萨亚斯', 7.7, 6154, 'tt0836700', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2182423389.jpg', 0.4, 2, 26.9, 52.5, 18.3, '-0.075074,0.134682,-0.621068,0.371431,-0.258701,-0.401892,0.474070,0.169708,-0.369648,-0.539617,0.034971,0.701681,0.231347,0.471353,0.249513,-0.022824,-0.313935,-0.469652,0.125885,-0.093768,-0.346233,-0.449752,0.332661,-0.212457,0.006220,-0.018995,0.436402,0.212418,0.198030,0.222050,0.191767,0.269958,-0.022994,0.136197,-0.157301,-0.088515,-0.357746,0.212703,-0.635881,0.171319,0.205363,0.078592,-0.116549,0.182031,0.426183,0.049061,0.625032,-0.066672,-0.228605,-0.066111,0.346451,0.002351,-0.028575,0.342768,0.240491,0.148209,0.148838,0.489998,-0.487115,-0.124279,0.068569,-0.216722,-0.606776,0.070331,0.050188,0.044496,-0.899981,0.348679,0.046230,0.011549,-0.028701,-0.489872,0.408264,0.705044,0.232031,0.591615,-0.361979,0.168446,-0.433209,0.295754,0.726927,-0.263147,0.152297,0.200535,0.039907,0.003022,0.133866,-0.258821,-0.474889,0.117160,-0.006908,0.279546,-0.090142,0.246786,-0.249533,-0.424773,-0.174488,-0.452421,0.495590,-0.785837,-0.020712,-0.482272,0.202937,-0.012037,-0.281524,-0.074576,0.322220,-0.243851,0.712770,-0.563606,0.296103,0.233358,0.378623,-0.820509,0.456856,0.150863,0.502640,-0.242707,0.009568,0.281934,0.155726,0.096579,0.018693,0.072770,0.163301,-0.004493,-0.401605,0.375013', '1309033', '1877596', '1308035', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949377', '亲亲老爸', '剧情', '四年前妻子离世后，家庭教育专栏作家丹•伯恩斯（史蒂夫•卡瑞尔 饰）独立抚养教育三个女儿。虽然他专职为父母们排忧解难，但是面对自己苦闷封闭的现实生活、孩子的成长问题，却束手无策。为了缓解人生危机，丹带着全家回乡，盼望能够找到新的生活方向。不料事与愿违，唠叨的父母和爱嘲弄的亲戚让他更为郁闷；而在书店里偶遇的玛丽（朱丽叶特•比诺什 饰）让他重见阳光；可是意想不到的是玛丽竟然是弟弟米奇（戴恩•库克 饰）的女朋友……亲情。爱情不如意的丹，是选择向生活妥协，还是会勇于冲破障碍追求美好未来？©豆瓣', '史蒂夫·卡瑞尔', '彼得·赫奇斯', 7.1, 5942, 'tt0480242', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p505596653.jpg', 0.7, 5.1, 41.9, 40.7, 11.6, '-0.201258,-0.097935,-0.468466,0.631658,-0.088904,-0.421007,0.667961,0.256554,-0.635975,-0.327590,0.053571,0.575629,0.186069,0.636711,0.240795,0.153940,-0.180769,-0.556268,0.340786,0.019719,-0.256338,-0.384338,-0.231856,-0.399397,-0.307186,-0.482495,0.672518,0.155869,-0.110501,0.251647,0.470872,0.490130,0.087297,0.435624,-0.111292,-0.102782,0.052645,0.173065,-0.558799,-0.040613,0.055422,-0.111643,-0.146309,0.304009,0.140725,0.206113,0.544136,0.017902,-0.147293,-0.238573,0.268794,-0.232465,-0.087945,0.259520,-0.106594,-0.061809,0.340245,0.054668,-0.145449,-0.064387,-0.049979,-0.251996,-0.784606,-0.096814,-0.002557,-0.041150,-0.797794,0.353289,0.065898,-0.085957,0.263662,-0.324804,0.113148,0.277107,0.140955,0.746283,-0.523853,0.124197,-0.309513,0.114046,0.624908,-0.201036,-0.301948,0.568465,-0.495172,-0.131184,0.332427,-0.231434,-0.789501,0.124674,0.019126,0.273301,-0.146154,0.387939,-0.391417,0.072989,-0.477869,0.063206,0.293635,-0.626773,-0.027694,-0.293610,0.091846,-0.224189,-0.596849,0.004868,0.016663,-0.562611,0.779601,-0.759771,0.111250,0.392021,0.255710,-0.660361,0.741047,0.384729,0.113925,-0.484537,-0.040416,0.585576,-0.224138,-0.080611,-0.207979,-0.077612,0.175700,-0.052385,-0.497540,0.558250', '30279170', '26021055', '26348103', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949761', '史前一万年', '剧情', '史前一万年的世界，神秘而幽远。在终年为白雪覆盖的大白山上，生活着以打猎为生的亚高族。他们擅长捕猎猛犸象，然而随着猛犸象越来越少，亚高族也逐渐走向末路。具有预知能力的老妈妈临死前做出预言：亚高族将面临四脚恶魔的入侵，届时族人将迎来最后一次狩猎，在此之后一位伟大的战士就会出现，并迎娶躲避战乱来到部落的蓝眼睛小女孩伊芙乐（Camilla Belle 饰）为妻，最终带领亚高族远离饥饿。族人们对此深信不疑，耐心等待决定命运的时刻的到来。男孩达雷（Steven Strait 饰）和卡恩（Mo Zinal 饰）对伊芙乐都心存爱慕。某日，消失十多年的猛犸象群重新回到大白山，达雷阴差阳错杀死一头猛犸象，赢得了女孩的心。不久，野蛮的外族入侵，虏走了美丽的伊芙乐。为了找回爱人，达雷和伙伴们踏上了充满艰险的旅途……©豆瓣', '史蒂文·斯崔特', '罗兰·艾默里奇', 5.9, 38540, 'tt0443649', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2220872972.jpg', 5.2, 20.5, 51.1, 18.2, 4.9, '-0.081098,0.135853,-0.554799,0.465592,-0.076795,0.048042,0.648540,-0.050100,-0.292752,-0.233156,0.291908,0.689989,-0.050838,0.177512,0.470341,-0.211483,-0.046335,-0.363268,-0.086071,0.020885,-0.296500,-0.213130,-0.186210,-0.300193,-0.054224,-0.460109,0.925189,0.294639,-0.183712,0.717280,0.016236,0.348047,-0.295136,0.346886,-0.239260,-0.161022,-0.085690,-0.066585,-0.284989,0.374518,-0.195594,0.019315,-0.131671,0.026728,-0.411890,-0.021128,0.868179,-0.766549,-0.197766,-0.383886,0.250242,-0.524722,0.083891,0.125736,0.395797,0.071474,-0.181114,0.395198,-0.056120,0.055575,-0.069286,-0.194384,-0.529363,0.113426,0.020240,0.029894,-0.753923,0.290253,0.323119,0.033446,0.354056,-0.390994,0.084555,0.400412,0.310007,0.410053,0.088519,0.242663,-0.320360,-0.214852,0.813035,-0.343585,-0.232859,0.063447,0.028148,-0.346254,0.195922,-0.278223,-0.461398,-0.124326,0.186841,0.363831,-0.289245,0.463059,-0.758385,0.183948,-0.625683,-0.446316,0.346584,-0.369279,-0.359168,-0.465516,-0.051672,-0.230722,-0.103698,0.338483,0.029686,-0.296179,0.887460,-0.844392,0.492726,0.393493,0.389737,-0.427340,0.458404,-0.179208,0.126562,-0.207688,-0.013614,0.796627,0.080959,0.259625,-0.175452,-0.168143,-0.265089,0.158759,-0.399347,0.424173', '6974439', '3811356', '10174444', '4160441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949811', '云水谣', '剧情', '年轻的陈秋水（陈坤 饰）为少女王碧云（徐若瑄 饰）的弟弟雨萌当家庭教师，他清朗潇洒，有一套快乐的学习方法，两人一起唱歌学英文，简单快乐，很快就堕入爱河。然而陈秋水是左翼人士，为避难必须逃往大陆。虽然似乎是短暂的离别，但秋水离去前仍与王碧云私定终生，发誓矢志不渝。但离别似乎很漫长 。秋水甚至与台湾失去了联络，但等待和思念仍埋在他的心中。部队护士王金娣（李冰冰 饰）对他坦言爱意，并展开追求。战争结束后，王金娣跟随秋水调至西藏，一路照顾无微不至。秋水亦多次寻碧云未果，决定把旧情藏于心底，不辜负决心随他的王金娣，二人成婚，但命运的嘲弄却在不远处。秋水不知道，身在台湾的王碧云，终身未嫁，一生都在等待。©豆瓣', '陈坤', '尹力', 6.9, 105106, 'tt0924003', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p787213786.jpg', 1.2, 7, 47.8, 34.3, 9.7, '-0.117499,0.175137,-0.564203,0.555639,0.111944,-0.507536,0.548357,-0.062946,-0.543610,-0.302566,0.111381,0.274474,0.213772,0.020021,0.137976,0.025114,-0.207324,-0.730119,-0.082831,0.038042,0.068139,-0.496506,0.093205,0.041617,-0.285753,-0.115882,0.606616,0.110928,0.049618,0.794906,-0.042931,0.247772,-0.210435,0.468381,-0.090471,-0.147302,-0.114121,0.353079,-0.741059,0.084636,0.208527,-0.287860,-0.358431,-0.101952,0.172956,0.220307,0.467551,-0.207877,-0.190323,0.171303,-0.002669,-0.459219,-0.133061,0.381799,-0.002689,0.150697,0.153751,0.280400,-0.322676,-0.009329,-0.172824,-0.022157,-0.323623,0.096012,0.315135,0.079082,-0.459537,0.326684,-0.338663,0.024865,0.173442,-0.237005,0.239315,0.109655,0.395670,0.326636,-0.264605,0.151608,-0.425557,0.381391,0.803393,0.214785,0.035440,0.127734,-0.153949,-0.450829,-0.026362,0.105834,-0.485067,0.029177,0.084664,0.237750,-0.035423,0.296049,-0.225808,-0.003267,-0.151391,0.080659,0.021854,-0.574874,-0.096877,-0.456270,-0.023227,-0.660887,-0.436225,-0.024603,0.249224,-0.115654,0.733976,-0.971612,0.364833,0.067134,0.308633,-0.593375,0.735000,0.400146,0.226034,-0.223444,0.234835,0.574024,-0.379795,0.112145,0.094658,0.258838,-0.208272,0.277423,-0.618358,0.295545', '35030151', '3445516', '25962735', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949812', '东京审判', '剧情', '1946年，远东国际军事法庭在东京审判日本战犯，当时法庭由11个国家的11名法官组成，受中国国民政府的委任，以梅汝璈（刘松仁 饰）为首的中国法官在3月20日飞抵东京。《大公报》记者肖南（朱孝天 饰）负责远东国际军事法庭的全程跟踪报道，战前相爱的恋人和田芳子（林熙蕾 饰）与他相 会。在宴会上，肖南目睹了梅汝璈的激动和欢欣，却预感到此行必定多艰难。审判终于开庭了，中国代表团遭受到了种种困难和挫折，整个法庭不赞成死刑的人居然占多数。面对各国法官们的偏见与刁难，中国法官和检察官们与他们斗智斗勇，克服了对美国法律不了解的种种不利因素，在庭审辩论中取得了上风。最终法庭是否能将东条英机等臭名昭著的战犯送上绞刑架呢？©豆瓣', '刘松仁', '高群书', 7.5, 85834, 'tt0884868', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2119846670.jpg', 0.9, 4.2, 32.6, 44.5, 17.7, '0.071853,0.083147,-0.734862,0.366934,0.119265,0.055695,0.389206,0.187900,-0.367395,0.072159,0.325015,0.803639,-0.434750,0.380861,0.367714,-0.153294,-0.475634,-0.921724,-0.148941,-0.013853,-0.373530,-0.746184,-0.162315,-0.344537,-0.253295,0.065571,0.471664,0.244130,-0.016685,0.449531,0.505422,0.382722,0.037901,0.418341,-0.127927,-0.119556,0.421603,0.086618,-0.463142,-0.039868,0.019463,-0.454782,-0.314428,0.184475,0.018222,0.233165,0.539253,-0.294624,-0.234911,-0.093171,0.480740,-0.722273,0.072437,0.560791,0.349284,0.035638,-0.026657,0.541307,-0.241475,0.155697,-0.154321,-0.089414,-0.515745,-0.097968,-0.035348,0.242076,-0.368436,0.654227,-0.258077,0.203972,-0.250770,-0.106930,0.183397,0.525545,-0.004545,0.549352,-0.031293,-0.218004,-0.326709,0.161141,0.752540,0.117402,-0.335014,-0.274299,-0.250879,-0.697192,-0.148869,-0.349781,-0.020036,-0.008134,0.226789,-0.230967,-0.103451,0.134106,-0.462187,-0.213321,-0.079137,-0.208047,0.005116,-0.283346,0.088331,-0.665468,-0.134373,-0.606649,-0.430645,0.247936,0.353599,0.090718,0.904131,-0.661176,0.120469,0.459006,0.351756,-0.701341,0.729772,0.535257,-0.060333,-0.064055,-0.030399,0.005016,-0.007673,0.446144,0.287120,0.259666,0.111108,-0.098785,-0.066355,0.076268', '30162520', '4301278', '10876425', '3212120');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1949877', '惊声尖笑5', '喜剧', '戴恩·桑德斯（西蒙·雷克斯 Simon Rex 饰）和乔迪（阿什丽·提斯代尔  Ashley Tisdale 饰）是一对快乐的新婚夫妇，这一天他们意外接到一通电话。此前戴恩的哥哥查理遭遇灵异事件，惨死家中，而他的三个孩子凯西（Gracie Whitton 饰）、莉莉（Ava Kolker 饰）和尚在襁褓中的艾登（Dylan Morris 饰）则宣告失踪。三个形同野人的孩子被人偶然发现于某个林中小屋之中，经过一番争执和讨论，戴恩最终令妻子同意收养三个小外甥。突然增加的人口，令戴恩不得不更加努力赚钱养家。可是在他们的新家内，接二连三发生了各种诡异事件，举止反常的小姐妹花，来自另一个世界的神秘访客，桑德斯一家开启了爆笑而恐怖的大门……©豆瓣', '西蒙·雷克斯', '马尔科姆·D·李', 5.5, 18737, 'tt0795461', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1898144743.jpg', 10.3, 27.9, 42.4, 12.8, 6.5, '0.324898,-0.116315,-0.662233,0.371783,-0.042761,-0.110989,0.967943,0.124819,-0.637445,-0.502198,0.298084,0.801321,-0.388371,0.411394,0.351905,0.022615,-0.178127,-0.430006,0.072807,-0.201110,-0.257854,-0.495021,-0.206290,-0.447096,-0.017084,-0.204273,0.196457,-0.016240,0.038262,0.650924,0.453411,0.331641,-0.508285,0.312763,-0.092272,0.247688,0.385372,0.054377,-0.112373,0.013413,-0.013418,0.030329,-0.206615,0.167850,0.044332,0.309928,0.738814,-0.465512,-0.245103,-0.245660,0.446802,-0.009342,-0.277526,0.134905,0.477263,0.042650,0.422248,0.151792,-0.330719,-0.079958,0.232169,-0.154519,-0.360781,0.265557,0.097202,0.152215,-0.315063,0.238448,0.121886,-0.116601,0.244809,-0.287050,0.089086,0.470029,0.357094,0.577568,-0.212954,-0.123955,-0.329211,-0.128023,0.501315,-0.207907,-0.166639,0.387604,-0.068149,-0.191795,0.062015,0.005432,-0.496156,0.300786,0.479673,-0.044901,-0.096934,0.371221,-0.684340,-0.007023,-0.581736,-0.216825,-0.149915,-0.278919,-0.356886,-0.702337,-0.041563,-0.304825,-0.425217,0.241731,-0.077101,-0.074123,0.590714,-0.728001,0.206225,0.309437,0.126955,-0.409654,0.368548,0.002177,0.468192,-0.234771,-0.044184,0.143156,0.200149,-0.074870,-0.040912,0.329409,-0.082583,-0.063754,-0.360973,0.242541', '1296534', '10466639', '1301686', '1309194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1950148', '赎罪', '剧情', '1935年夏天，来自一个宽裕的英国小康家庭的13岁的少女布里奥妮（斯奥里兹•罗南 饰）刚刚开始尝试写作,想象力丰富。一天，她暗中发现仆人的儿子——罗比•特纳（詹姆斯•迈克沃伊 饰）和她姐姐塞西利亚（凯特•奈特莉 饰）之间有暧昧关系，而且发现他给她写了一封充满情色意味的情书。布里奥妮丰富的想象力虚构着各种可怕的事情，浮想联翩。当她的表姐罗拉被强奸后，布里奥妮相当肯定她看到是罗比做的，这次指证使罗比蒙冤入狱，留下伤心欲绝的塞西利亚。第二次世界大战爆发了，出狱后的罗比和塞西利亚都投入了保卫祖国的战斗，布利奥妮放弃到剑桥升学成为一名军队医务人员。没有人能理解她的做法，只有她知道她怀揣着巨大的秘密和自责。她鼓起勇气，想把这秘密解开，能真正赎罪和得到宽恕。然而，世事幻变，出乎布利奥妮的预算。©豆瓣', '詹姆斯·麦卡沃伊', '乔·赖特', 8.5, 340970, 'tt0783233', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2174553771.jpg', 0.1, 0.8, 12.5, 46.5, 40, '0.505772,0.101222,-0.803445,0.598046,-0.009368,-0.434010,0.739722,-0.022988,-0.349293,-0.327444,-0.120976,0.379878,-0.294227,0.064027,0.218817,0.133848,-0.609618,-0.670356,0.225008,-0.245299,-0.178899,-0.554599,-0.337034,-0.221400,-0.125286,-0.722336,0.154106,-0.063581,-0.071802,0.291754,0.353122,0.468563,0.418625,0.410424,0.250605,0.084761,0.280095,-0.150743,-0.059436,0.287731,0.123660,0.093821,-0.181715,0.225028,0.098860,0.374275,0.421153,-0.256728,0.107799,0.060736,0.437187,-0.394444,0.103210,0.130310,-0.038854,-0.283103,-0.114518,-0.102939,-0.220913,-0.150949,0.500719,-0.131683,-0.686607,-0.279861,-0.071712,0.247170,-0.510958,0.252016,-0.393527,-0.070155,0.274553,-0.398028,-0.059897,0.426848,0.105864,0.180104,0.021227,-0.016865,-0.563197,0.166466,0.466276,-0.082802,-0.067948,0.087412,-0.477185,-0.511063,0.111713,-0.355128,-0.445958,0.133530,0.391338,-0.137554,-0.114555,0.354911,-0.204805,-0.423588,-0.523338,-0.114475,-0.194694,-0.669274,-0.129120,-0.563502,-0.311578,-0.458889,-0.538038,-0.016971,0.092517,-0.523202,0.611849,-0.598414,0.183799,0.521742,0.319079,0.036647,0.522561,-0.124814,0.069777,-0.225794,-0.285057,0.398464,-0.046781,0.099679,0.213167,0.399032,0.317008,0.001064,-0.291492,0.616649', '1292211', '30344474', '1307442', '2368587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1950192', '深度谜案', '悬疑', '马丁（伊利亚•伍德 Elijah Wood 饰）为了追寻偶像逻辑数学家亚瑟（约翰•赫特 John Hurt 饰）的足迹，来到牛津大学深造。他发现，寄宿的房东伊格莱顿太太（安娜•玛西 Anna Massey 饰）仿佛跟亚瑟交往甚密，而她的养女贝丝（朱丽•考克斯 Julie Cox 饰）却总是故弄玄虚。后来，马丁结识了壁球伙伴洛娜（蕾欧诺•瓦特林 Leonor Watling 饰），两人堕入爱河……亚瑟演讲时，马丁作为唯一的提问者，引起了他的注意。后来，二人在房东家不期而遇，发现伊格莱顿太太被人谋杀。现场唯一的线索是一个圆圈。二人被警方带走协助调查。此后又有一些人离奇地死去，而且他们的死因似乎还暗含着某个数学定律……©豆瓣', '伊利亚·伍德', '艾利克斯·德·拉·伊格莱希亚', 6.7, 22449, 'tt0488604', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p779543829.jpg', 1.2, 8.8, 49.5, 32.3, 8.2, '0.438368,-0.180443,-0.602842,0.465252,-0.078992,-0.566501,0.808940,0.244349,-0.477905,-0.563324,0.157320,0.659850,-0.462502,0.028796,0.281165,0.264534,-0.634895,-0.650259,0.266128,-0.140856,-0.110107,-0.630756,-0.102089,-0.244929,0.074042,-0.217675,0.179650,-0.025686,-0.104668,0.250882,0.057170,0.507155,-0.087576,0.308261,0.000960,0.313427,0.467842,-0.229588,-0.211706,0.036803,0.101041,0.024814,-0.265678,0.175804,0.029504,0.427835,0.533215,-0.203284,0.175527,0.060318,0.236544,-0.304509,0.139962,-0.017681,0.275732,-0.239437,0.208487,0.165697,0.016087,-0.048501,0.363161,0.032948,-0.364748,0.395806,-0.039966,0.404802,-0.288258,0.265122,-0.099120,0.102201,-0.018857,-0.168214,0.180643,0.309602,0.192950,-0.021369,-0.070697,0.041904,-0.473636,0.051041,0.499768,-0.023883,-0.129961,0.128153,-0.356901,-0.445057,0.077132,0.160929,-0.419799,-0.029388,0.526944,-0.133732,-0.007880,0.234560,-0.477694,-0.362602,-0.562375,-0.013215,-0.241360,-0.441220,-0.052831,-0.768010,-0.002878,-0.193293,-0.354023,-0.083138,-0.035629,-0.268457,0.516458,-0.540728,0.231356,0.504645,0.150215,-0.338347,0.588143,-0.048220,0.045833,-0.394806,-0.259954,0.445390,0.284128,-0.005562,0.124391,0.165887,0.209616,-0.065257,-0.277817,0.253593', '1316693', '10466639', '1301686', '1297659');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1950198', '一夜大肚', '喜剧', '艾莉森（凯瑟琳•海格尔），20出头，漂亮性感，是个颇有前途的娱乐新闻记者，最近还得到老板赏识小小升职了一把。班斯通（西斯•罗根 饰），游手好闲，生活杂乱无章，成天只知道和狐朋狗友厮混。某天晚上，春风得意的艾莉森在酒吧遇见了班斯通，二人酒后乱性，发生了一夜情。原以为酒醒之后，他们的生活就会按照以前的轨迹继续下去，谁知道艾莉森竟然怀孕了，两个自由自在生活惯了的大孩子，面临着逃避责任还是承担后果的艰难抉择。经过一番思想斗争后，艾莉森和班斯通决定担负起为人父母的责任，把孩子生下来。他们开始像别的情侣一样，试着约会、相处，融入对方的生活，但是他们越是了解对方，对未来的生活就觉得越迷茫。即将出生的孩子，更是他们人生的一道难题……©豆瓣', '凯瑟琳·海格尔', '贾德·阿帕图', 6.5, 26364, 'tt0478311', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2488114090.jpg', 1.3, 9.9, 56.2, 26.7, 5.9, '0.269518,-0.186267,-0.565518,0.161909,-0.237229,-0.260199,0.502623,0.077935,-0.514105,-0.251545,0.114635,0.765507,-0.288952,0.432330,0.373625,-0.043871,-0.460428,-0.778498,0.184154,0.061921,-0.000109,-0.430594,0.030283,-0.230510,0.118825,-0.158368,0.471351,0.051546,0.058543,0.201075,0.189958,-0.065124,-0.008221,0.414272,-0.394817,0.098522,-0.211527,0.335010,-0.266830,-0.123378,0.239067,0.123136,-0.064432,-0.181468,0.280505,0.105483,0.443697,-0.179049,-0.581710,-0.222846,0.487668,-0.226583,-0.114182,0.112696,0.225409,0.083271,0.212395,0.085355,-0.144295,-0.018995,-0.105166,-0.195799,-0.463864,0.186304,-0.111122,0.077190,-0.598558,0.184751,0.299638,-0.246421,0.120389,-0.344910,0.064181,0.604380,0.412543,0.456912,-0.338029,0.069930,-0.640096,0.039650,0.983727,-0.032633,-0.254066,0.452208,-0.256161,-0.232331,-0.166017,-0.422667,-0.487259,-0.052513,0.057312,0.040021,-0.425404,0.510095,-0.338903,0.244477,-0.111105,-0.114759,0.149830,-0.479716,-0.146154,-0.223803,-0.168332,-0.324674,-0.523448,0.129937,0.036385,-0.502982,0.752531,-0.969329,0.123517,0.545334,0.488314,-0.818031,0.574677,0.384265,0.147419,-0.267698,0.191579,0.273674,-0.167837,-0.042282,0.028612,0.353915,-0.019604,0.065407,-0.127171,0.341369', '1877596', '25721544', '1949320', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1950330', '罗马', '剧情', '故事发生在墨西哥城的一个中产阶级社区“罗马”，讲述年轻女佣克里奥（雅利扎·阿巴里西奥饰）在雇主索菲亚（玛丽娜·德·塔维拉饰）家中工作，该家中索菲亚的丈夫长期在外，由女佣克里奥照顾索菲的四个孩子。突如其来的两个意外，同时砸中了女佣克里奥和雇主索菲亚，两人究竟该如何面对苦涩茫然的生活？四位孩子似乎是希望所在。 这是以导演阿方索·卡隆的儿时记忆铸成的影片，而卡隆其实就是片中某一位小孩。', '雅利扎·阿巴里西奥', '阿方索·卡隆', 8.2, 138785, 'tt6155172', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2555541430.jpg', 0.3, 1.8, 17.7, 49.8, 30.4, '0.180502,-0.035325,-0.297573,0.383386,-0.011730,-0.404726,0.759652,0.045709,-0.443004,-0.659783,0.365515,0.645570,0.094194,0.522794,0.312809,0.268955,-0.505528,-0.504684,-0.134874,-0.034452,-0.276458,-0.490406,-0.224498,-0.466656,0.056667,-0.267120,0.216293,-0.342340,0.201805,0.124676,0.413804,0.613338,-0.399594,-0.008768,-0.000610,0.133111,0.358002,-0.202951,-0.292417,-0.064604,0.013879,0.189822,-0.175595,0.089774,0.192138,0.401712,0.522435,-0.201393,0.104812,-0.217035,0.158886,0.094339,-0.024919,0.117026,0.072585,-0.128773,0.349065,0.025760,-0.079465,-0.013232,0.100723,-0.062323,-0.496406,0.036110,0.322181,0.390177,-0.599438,0.397076,-0.053013,-0.242344,0.249021,-0.161980,0.079846,0.349304,0.160760,0.657706,-0.017729,0.046624,-0.223347,0.072982,0.413050,-0.098542,-0.210963,0.314768,-0.434890,-0.284953,0.052308,0.133563,-0.629744,0.152469,0.117542,-0.060799,-0.016056,0.376372,-0.356864,-0.181948,-0.412918,-0.077812,-0.175037,-0.376311,-0.145799,-0.498402,0.041459,-0.412590,-0.334033,-0.186360,0.100929,0.163547,0.687548,-0.497114,0.268876,0.368156,-0.015066,-0.244065,0.394444,0.213907,0.420081,-0.318397,-0.027993,0.307754,-0.037355,-0.276165,-0.187501,0.272297,-0.141745,-0.263749,-0.293906,0.393980', '26348103', '2002744', '4301215', '4847665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1950454', '奇趣马戏团：吸血鬼的助手', '动作', '达伦·山（Chris Massoglia 饰）是一个学业优秀、青春阳光的高中生，他在学校人缘极好，且拥有幸福美满的家庭，因此被朋友们称为“完美先生”。某日，一张宣传单改变了他的生活走向。一个囊括了各种怪异事物的奇趣马戏团来到他所在的镇上，虽然父母老师禁止，不过达伦依旧和痴迷吸血鬼的好友史蒂夫（Josh Hutcherson 饰）偷偷前去观看。闻所未闻的奇人怪事令两个男孩兴奋不已，而吸血鬼拉登·克雷斯利（John C. Reilly 饰）和他的剧毒蜘蛛的登场则让他们备受触动。演出结束后，达伦偷了蜘蛛，因无法成为吸血鬼而心存愤恨的史蒂夫杀蜘蛛不成反中剧毒，危在旦夕。为了拯救好友，达伦不得不化身半吸血鬼成为拉登的助手。他由此开始经历一场奇幻之旅……本片根据爱尔兰小说家Darren Shan的同名作品改编。©豆瓣', '克里斯·马索格利亚', 'Paul Weitz', 6.1, 9658, 'tt0450405', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1867117587.jpg', 3.1, 17.4, 55.1, 19.9, 4.5, '0.357957,-0.199757,-0.383306,0.556717,0.003279,-0.125922,0.720334,0.057009,-0.425754,-0.345142,0.256050,0.733352,-0.206791,0.372259,0.265241,-0.136499,-0.197173,-0.501085,-0.024285,-0.189952,-0.155799,-0.050458,-0.290591,-0.191387,-0.123569,-0.463410,0.785184,-0.013890,-0.044891,0.564304,0.220034,0.418292,-0.145791,0.093345,-0.138458,-0.061607,0.100874,-0.086468,-0.299246,0.315111,-0.025928,-0.019119,-0.160373,0.168396,-0.161691,0.157547,0.819090,-0.397779,-0.221688,-0.386887,0.515648,-0.375474,-0.017971,0.270714,0.292944,0.025041,0.079442,-0.040009,0.000472,0.154378,0.095338,-0.093146,-0.874522,-0.123029,0.277246,0.084721,-0.364992,0.462154,-0.008952,-0.148059,-0.009892,-0.252218,-0.037878,-0.008869,0.334373,0.297149,0.145593,0.160241,-0.363368,0.190358,0.620839,0.041982,-0.331537,0.299496,-0.244135,-0.328664,0.140741,-0.332575,-0.496644,0.235978,0.294512,0.042128,-0.001332,0.313601,-0.765849,-0.122301,-0.405624,-0.143236,-0.097418,-0.371362,-0.188348,-0.669633,-0.070970,-0.272814,-0.066277,-0.033771,0.128893,-0.372399,0.819788,-0.750115,0.103834,0.412560,0.043841,-0.351627,0.583428,-0.027785,0.022671,-0.304406,-0.219681,0.367356,0.349835,0.132369,0.058186,0.187209,0.052586,-0.154683,-0.295253,0.402880', '3811356', '26759820', '25880986', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1950525', '大灌篮', '喜剧', '世杰（周杰伦 饰）因为在外惹事而被功夫学校开除，他是一个弃婴，从来不曾离开过学校在外闯荡。虽然学校有着不学无术的校长、古怪的四大师叔，仍然是世杰的庇护所。在外流浪的第一晚，就因为把汽水罐扔进垃圾桶的本领被立叔（曾志伟 饰）看中——立叔生活潦倒，然而鬼点子多多，他帮世杰设计了一个“打篮球寻亲”的计划，利用志杰的特长在赚钱之余也名声远扬。然而篮球队是需要队长丁伟（陈柏霖 饰）许可才能进入，丁伟妹妹莉莉正是志杰暗恋的女孩，莉莉暗恋的却是中锋萧岚。世杰的天才让他轻松地进入篮球队，也让球队轻松地打进了大学篮球赛的冠军争夺赛。即将跟老对手李天——以前的战友、如今的敌手——交锋，世杰才明白丁伟的颓废不仅由于李天抢走了自己的女朋友，还在篮球场上让自己一败涂地。这不仅是一场篮球战，还是一场心理战。©豆瓣', '周杰伦', '朱延平', 5.6, 140334, 'tt0848538', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p887161942.jpg', 9.6, 27, 45.2, 12.5, 5.7, '0.138241,-0.185737,-0.449179,0.428959,-0.418941,-0.624633,0.328225,0.059051,-0.497319,-0.233487,0.212999,0.612709,-0.088243,0.316796,0.184373,-0.155968,0.179350,-0.634823,-0.108202,-0.075291,-0.133262,-0.445875,-0.253095,0.145427,0.014756,-0.240292,0.590635,-0.020178,-0.408655,0.459628,0.297600,0.045181,0.092804,0.452664,-0.185647,-0.077351,0.166281,0.331695,-0.208456,0.058356,0.032836,-0.223707,-0.118767,-0.001487,0.336386,0.182999,0.610114,0.079156,-0.075166,-0.023465,0.274304,-0.303816,-0.215424,-0.073761,0.424554,-0.025063,0.286891,0.160112,0.153711,0.227597,0.029227,-0.131514,-0.563072,0.120819,0.199550,-0.178334,-0.573799,0.790439,-0.007665,-0.106247,-0.004623,-0.143844,0.173930,0.281708,0.163353,0.308964,-0.322678,0.108883,-0.442746,0.252828,0.532035,-0.095830,-0.100248,0.169977,0.045785,-0.361324,0.238875,-0.391749,-0.558992,0.232015,0.280410,-0.231486,-0.116132,0.115639,-0.451856,0.153023,-0.256644,-0.065459,0.076624,-0.356433,0.008976,-0.334190,-0.035141,-0.257930,-0.447411,0.033316,-0.038289,-0.395380,0.729544,-0.911331,0.077493,0.608035,0.097023,-0.397010,0.510313,0.379159,0.050676,-0.145640,-0.229407,0.057008,0.031233,0.317026,-0.033648,0.619394,0.090192,-0.534723,-0.352657,0.497126', '1826173', '35030151', '1292219', '4739952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1951105', '一球成名2：梦想成真', '剧情', '终于，圣地亚哥（库诺·贝克 Kuno Becker 饰）踏上了英伦列岛，加入了英超纽卡斯尔俱乐部，开始了在英超联赛的征战。不管是在英超赛场还是在欧洲冠军联赛，圣地亚哥精湛的球艺引起了欧洲各大俱乐部的注意，欧洲的豪门球队皇家马德里也向其发出了正式的邀请。为了参加欧洲的顶级赛事欧洲冠军联赛，与欧洲最出色的球队和球员同场竞技。圣地亚哥最终决定转会皇家马德里。这场看似简单的转会，在圣地亚哥看来却是波折不断。在英超的一个赛季中，圣地亚哥与贝克汉姆（大卫·贝克汉姆 David Beckham 饰）建立了良好的关系，在赛场上并肩作战。但是也遭遇到与经理人决裂，其他球员糜烂的私生活的影响……在名利的诱惑之下，这位冉冉升起的足球新星的职业生涯将会怎样发展？©豆瓣', '库诺·贝克', '佐米·希尔拉', 6.2, 12382, 'tt0473360', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1793019216.jpg', 2.6, 15.3, 56, 19.9, 6.2, '-0.034581,0.409807,-0.711257,0.760462,0.292080,-0.485980,0.054362,0.182339,-0.739266,0.419391,0.190993,1.126609,-0.516869,0.081523,0.557411,-0.426820,0.083371,-1.167689,-0.212306,-0.240782,-0.357718,-0.672922,-0.467280,-0.046001,-0.010157,-0.098941,1.210510,0.212844,-0.497186,0.544869,0.297749,0.386800,0.559188,0.146204,-0.254093,-0.172427,0.220169,0.507450,-0.728655,0.465637,0.010586,-0.146533,-0.580128,-0.049782,0.607441,0.153243,0.340499,-0.321705,0.610223,-0.084125,0.616410,-0.104617,0.029357,0.362632,0.551429,-0.130663,-0.094504,0.361066,0.097105,0.246762,-0.269906,-0.205988,-0.652239,0.095843,0.119418,0.218506,-0.681047,1.141307,-0.241274,-0.050476,-0.062913,0.055672,0.268278,0.552723,0.093852,-0.107006,0.033515,0.075300,-0.348811,0.110854,0.773264,0.041104,-0.415098,-0.199896,-0.085791,-0.585132,-0.150193,-0.653117,-0.424662,-0.048427,0.407125,0.067612,0.263257,0.578111,-0.867630,0.449056,0.075807,-1.015482,0.108025,-0.336525,0.304131,-0.834992,-0.136739,-0.490389,-0.286820,0.014430,-0.094249,0.207973,0.852309,-0.913055,-0.121767,1.008616,0.176599,-0.251405,0.696255,-0.157740,0.612868,-0.134165,-0.606540,0.343463,-0.302427,0.085853,-0.462673,0.641111,-0.101357,-0.289874,-0.314852,0.632806', '26615753', '1780122', '1457219', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1951107', '超级礼物', '剧情', '杰森（德鲁·傅勒 Drew Fuller 饰）与爷爷霍华德·史蒂文斯（詹姆斯·加纳 James Garner 饰）之间似乎从未有过所谓祖孙情深的桥段，杰森唯一知道的就是向爷爷要钱。当爷爷去世后，杰森满心以为可以继承一大笔财产，前途无忧之时，他发现爷爷竟在他和这笔财产之间设置了十二道障碍，他必须依次完成遗嘱上的十二个有关“礼物”的任务后，方能得到这笔最终的超级礼物。为了获得遗产，杰森只好着手完成第一个任务，没想到得到的礼物竟是让他尝尝破产的滋味，而这仅仅是开始，对于几乎没有过正式工作的富二代杰森来说，遗嘱上的每一个任务都是一次艰难挑战，他不知道在这条发现之旅上他还会遇到什么，也不知道爷爷到底在卖什么药，然而他的人生却因为这份遗嘱正悄悄地被改写……本片改编自吉姆·斯托维尔的同名畅销小说。©豆瓣', '德鲁·傅勒', 'Michael O. Sajbel', 7.3, 7262, 'tt0482629', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2209604948.jpg', 1.1, 4.8, 36.8, 41.5, 15.8, '0.187345,0.135113,-0.756332,0.677487,-0.160539,-0.559786,0.452155,-0.097644,-0.450362,-0.315931,0.066446,0.831956,0.193274,0.123556,0.187161,0.070685,-0.184774,-0.455730,0.011832,-0.280408,-0.336110,-0.775950,-0.246340,0.090439,-0.080971,-0.096823,0.533897,-0.091364,0.062345,0.273799,0.430225,0.269177,0.247384,0.335643,-0.085979,0.231601,0.264132,0.148205,-0.441821,0.103391,0.253363,-0.063415,-0.196448,0.394620,0.185022,0.342656,0.297623,-0.241722,-0.277192,0.010949,0.291632,-0.061482,0.037976,0.086874,-0.136152,0.089373,0.423941,0.448486,-0.269402,0.028689,0.181863,-0.032731,-0.905849,-0.116818,-0.062755,0.182326,-0.505207,0.323387,-0.338192,0.006264,-0.061237,-0.721376,0.284358,0.508743,0.444959,0.415910,-0.446523,0.036424,-0.742255,0.008725,0.735525,-0.162655,0.104941,0.444831,-0.015888,-0.441549,0.170681,-0.258831,-0.223220,0.422979,0.287354,0.369904,0.004429,0.203713,-0.407288,-0.068498,-0.190182,-0.416727,0.120693,-0.526301,-0.071116,-0.201440,-0.222726,-0.141274,-0.551991,0.097369,0.167491,-0.617433,0.564193,-0.762941,0.386372,0.440638,0.176646,-0.606036,0.516086,0.382088,0.139426,-0.273398,-0.054102,-0.075248,0.192799,0.334769,0.223845,0.060948,0.527597,-0.408017,-0.049768,0.771189', '30163500', '1304977', '3215099', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1951163', '第二滴血', '剧情', '威尔（比尔·米尔纳 Bill Milner 饰）是个寂寞的乖小孩，他被家里管得很严，没什么朋友，又因宗教因素被严格限制娱乐，只能靠画画打发时间。偶然的机会，威尔结识了学校的“问题学生”卡特（威尔·保尔特 Will Poulter 饰），带着威尔进入另一个崭新世界，卡特第一次给他 看了电视，带他作恶，还要他帮忙拍短片，完成自己的导演梦想。善良单纯的威尔成了卡特的小跟班，也渐渐开始发现摄影机的妙处，尽情发挥自己的想象力，但少年人的友谊总会埋下许多不安定因素，随着一个法国交换生的出现，似乎威尔和卡特的关系出现了裂痕……©豆瓣', '比尔·米尔纳', '加斯·詹宁斯', 7.8, 6664, 'tt0845046', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2281095366.jpg', 0.6, 2.6, 25, 48.5, 23.4, '0.412090,-0.187411,-0.401819,0.312127,-0.527167,-0.149659,0.813281,0.348405,-0.201972,-0.020425,0.028462,0.855489,-0.227097,0.209803,0.287963,0.021893,-0.396818,-0.615896,0.282873,0.113085,-0.098486,-0.596109,-0.295750,-0.288945,-0.156630,-0.347417,0.445115,-0.061650,-0.230270,0.166919,0.023439,0.205144,0.121513,0.403224,-0.071202,0.007711,0.093513,-0.426099,0.210314,0.175638,-0.059272,-0.031260,0.050900,0.218119,-0.021367,0.407203,0.477841,0.074534,0.088902,-0.022554,0.075310,-0.020357,0.006513,-0.097266,-0.176512,-0.083794,0.341257,0.120241,0.081325,-0.301009,0.050075,-0.323620,-0.591901,0.100697,0.044238,0.255273,-0.573565,0.534743,-0.049397,-0.268864,0.090098,-0.304660,-0.070805,0.392843,0.167334,0.172741,-0.208633,0.101273,-0.227605,0.189017,-0.001240,-0.080616,-0.338897,0.569855,-0.296740,-0.359329,0.071240,-0.165067,-0.273871,-0.166627,0.563264,-0.123175,-0.231016,0.168961,-0.656781,0.111330,0.018522,-0.407427,-0.089180,-0.417461,0.117732,-0.570015,-0.040037,-0.299604,-0.742334,-0.215400,-0.021119,-0.166969,0.641362,-0.845817,0.334734,0.784125,0.077081,-0.396644,0.801377,0.222731,0.129322,0.048086,0.001303,0.298414,-0.205717,0.295838,0.210966,0.398668,0.035989,-0.373537,-0.408402,0.782212', '1309172', '35158375', '1292062', '4914656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1951175', '拳霸2', '动作', '距今五、六百年前的泰国，时局动荡，阴阳逆反。邪恶阴险的军官Rajasena发动叛乱，夺取政权，为此展开大规模的血腥屠杀。少年泰恩出身于一个正直的武将家庭，他的父母双亲皆被叛军杀害。泰恩侥幸逃脱，然而才出龙潭，又入虎穴，他被迫与凶猛的鳄鱼同处一池。泰恩面对鳄鱼时的果敢引起夫毕克匪帮的头目车南的注意，车南将少年留在部落里，延请各路流派的好手教习泰恩格斗技巧。经过多年的磨练，泰恩（托尼·贾 Tony Jaa 饰）终于成长为身怀绝技的高手，并接任车南晋升为匪帮的新任首领。虽然数年过去，但他始终没有忘记Rajasena加诸在其家族身上的厄运，他开始走上一条充满血腥和艰险的复仇之路……©豆瓣', '托尼·贾', '托尼·贾', 6.3, 9793, 'tt0785035', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2107697577.jpg', 3.3, 15, 51.2, 22.6, 7.9, '0.140404,0.046361,-0.592071,0.668625,-0.045358,-0.280745,0.691715,-0.355084,-0.538882,-0.293607,0.242283,0.525167,0.027235,0.057113,0.268300,-0.442411,0.142250,-0.646787,-0.277404,0.068148,-0.238344,-0.188942,-0.488756,-0.003997,-0.172565,-0.300552,0.821619,0.423639,-0.232339,0.414110,0.247537,0.356401,-0.196313,0.339022,0.025987,-0.149750,-0.163341,-0.146664,-0.209684,0.071162,-0.238265,-0.473131,-0.311763,0.064015,-0.075300,0.361471,0.583680,-0.495928,0.062377,-0.308055,0.330587,-0.234104,-0.106656,0.161762,0.494587,0.145725,-0.024418,0.415845,0.135239,-0.071977,-0.090249,-0.147273,-0.750955,-0.060888,0.101284,-0.064152,-0.527492,0.435869,0.053571,0.007878,-0.105278,-0.338673,-0.199401,0.292723,0.170945,0.159507,-0.190804,0.163431,-0.406653,0.058692,0.654481,-0.187162,-0.308028,-0.353485,0.003069,-0.607709,0.181107,-0.759533,-0.285037,-0.117196,0.351736,0.016030,-0.019308,0.473575,-0.575513,0.012986,-0.498120,-0.066299,0.086698,0.150766,-0.158913,-0.534746,-0.108675,-0.257363,-0.313976,0.135132,0.337817,-0.251122,0.633705,-0.739398,0.182588,0.282126,0.099883,-0.517768,0.432673,-0.114878,0.394427,-0.026268,-0.335598,0.540963,0.368576,0.343596,0.177349,0.340610,-0.446675,-0.050740,-0.121998,0.372334', '5308201', '1482099', '1308837', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1951318', '生日快乐', '爱情', '若即若离的感情线，一个在防守，一个在等待。小米（刘若英饰）与小南（古天乐饰）是大学时候的同学。每年小米的生日，小南都会送上祝福，唱一首五音不全的歌给小米听。彼此相知相爱，可是小米因为童年的阴影始终无法正面她与小南之间的感情。小米后来出国留学了，两人分隔两地但心里还是时时牵挂彼此。历年的生日，小米仍记得小南的祝福。仿佛各自又有了不一样的生活，可是当年的记忆还在。最后小南告诉小米自己就要踏上婚姻的道路，小米伤心欲绝，要强的她此刻才剖白心声。就算他们仍然彼此相爱，可一切都已经无法回头……©豆瓣', '古天乐', '马楚成', 7.1, 60384, 'tt0923923', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p664165174.jpg', 0.9, 5.9, 43.1, 36.8, 13.3, '0.188231,-0.207260,-0.804158,0.685691,0.193877,-0.809182,0.687521,0.241851,-0.277185,0.077922,-0.050886,0.527425,-0.028033,0.162737,-0.069600,0.166471,-0.297796,-0.876395,0.220786,-0.189520,-0.060910,-0.414920,0.010449,0.247901,-0.193342,0.056824,0.603199,-0.209194,-0.070380,0.463503,0.157703,-0.164547,-0.123197,0.468642,-0.228728,0.000053,0.143935,0.347824,-0.492306,-0.241702,0.090555,-0.188472,-0.201000,0.205936,-0.102544,0.230107,0.788555,-0.196847,-0.228421,0.442575,0.005532,-0.194581,-0.107144,0.094555,0.055444,0.020488,0.550153,0.295678,-0.035629,0.131047,0.152910,0.122384,-0.535635,0.034499,0.105024,0.245992,-0.402353,0.850758,-0.105777,-0.064285,0.372788,-0.465534,0.300157,0.419501,0.293210,0.468068,-0.567572,-0.086371,-0.369060,0.167580,0.994630,-0.067766,-0.130413,0.521996,-0.509185,-0.199287,-0.058198,0.263707,-0.879354,0.326197,-0.048701,0.357825,-0.511735,0.434905,-0.599856,0.231822,-0.106775,-0.020003,0.227818,-0.899660,0.197431,-0.359019,-0.422483,-0.769323,-0.544783,-0.002559,0.211774,-0.098096,0.917290,-0.773587,0.426211,0.345670,0.240126,-0.186634,0.689765,0.646834,-0.086669,-0.157229,0.289096,0.247567,-0.411403,0.197872,0.157724,0.368740,0.304087,0.322465,-0.565851,0.526585', '1292219', '27040921', '30209018', '26809007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1958063', '超狗任务', '喜剧', '超人狗最初是一条在警队服役的普通小猎犬，因为执行任务时的一次严重失误，被革职。流落街头的小猎犬被捉到一个动物研究所，邪恶的西蒙（彼德•定克拉吉 饰）博士在那里对流浪狗进行试验，希望能创造出一条超人狗。小猎犬大闹实验室，阴差阳错成了超人狗，并逃了出去。研究所的一个保安在下班的时候遇见超人狗，并把它带回家，希望借此改善和儿子的关系。在家里，超人狗发现自己不但力量强大、速度惊人，而且还能说话和飞翔。在保安之子的鼓励下，超人狗决定用自己的力量服务社会，与此同时，邪恶的西蒙博士则在琢磨怎么夺回超人狗，还计划着一个阴险的阴谋……©豆瓣', '杰森·李', '弗雷德里克·杜周', 6.4, 6184, 'tt0467110', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315904843.jpg', 1.9, 11.5, 57.2, 22.4, 7, '0.110904,0.043257,-0.531900,0.576531,-0.295064,-0.365980,0.506707,0.005923,-0.236800,-0.144014,0.347497,0.579777,-0.101320,0.051510,-0.024743,-0.214897,-0.167033,-0.316135,0.052401,0.058315,-0.330872,-0.366196,-0.590622,-0.026022,0.118215,-0.317247,0.316116,-0.136145,-0.213194,0.419267,0.222787,-0.179035,-0.161652,0.206848,-0.373875,-0.065288,0.176416,-0.050442,0.052843,0.064125,0.185834,0.057597,0.256236,-0.067473,0.063968,-0.025601,0.714648,-0.581137,-0.312286,-0.415929,0.207389,-0.163142,0.031769,0.220122,0.432146,-0.179072,0.061219,-0.008540,0.153342,0.222839,0.160165,-0.100125,-0.962950,-0.186109,-0.427797,0.191856,-0.398291,0.317218,0.009413,0.231411,0.371507,-0.579661,-0.159235,0.035553,0.013522,0.640852,-0.231767,0.358574,-0.796427,0.063827,0.389193,-0.327363,-0.295309,0.143873,-0.005155,-0.313775,0.053954,-0.151350,-0.096922,-0.104945,0.559084,-0.155747,-0.783066,0.087857,-0.633276,0.006211,-0.286998,0.179924,-0.143045,-0.372307,-0.299369,-0.559033,0.466304,0.010053,-0.006122,0.360344,0.204512,-0.476128,0.499275,-0.807393,0.222594,0.884836,0.325983,-0.398763,0.466769,-0.291720,0.158626,-0.288731,-0.156196,0.006912,0.476696,0.576876,0.443324,0.392058,-0.057031,-0.336887,-0.450987,0.445830', '3213270', '1793491', '1300324', '30387441');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1958400', '面对巨人', '剧情', '在他的六年教练生涯中，泰勒从未在赛季中获胜。当球队中最优秀的队员Shiloh决定转学后，他们连在新赛季中获胜的希望都随之而去了。赛季一开始便输了三场比赛之后，泰勒发现那些爸爸们决定解雇他，随之而来的一系列压力令他完全失去了希望。他将如何重拾勇气与信心，用信仰击败恐惧呢？◇花絮：美国电影<面对巨人> 涉及宗教信仰问题引争议一部针对学生观众，讲述高中足球教练以对上帝的信仰来影响球员的影片在议会却找到了观众，不是因为影片的宗教信息，而是因为影片的分级。议员罗伊·布伦特和很多律师听说电影《面对巨人》因为宗教内容而被定位PG级而非G级后感到十分不满，上书美国电影协会(MPAA)，要求讨个说法。PG意味着建议影片由家长陪同观看，G则表示影片老少咸宜。罗伊·布伦特在信中质问美国电影协会为什么会因为影片有宗教内容而将其定为限制级，他甚至还拿出最近哈佛公共卫生学院刚做出的一份调查说MPAA对电影的性和暴力的管理能力越来越弱。言下之意，颇有责怪MPAA“该管的不管，不该管的瞎管”之意。MPAA官员并未回应罗伊·布伦特等议员及律师的质问，但是在回复给布伦特的信中，MPAA的克里克曼坚持影片如此定级决非仅是因为宗教内容，他表示影片中若有任何比较强烈涉及成熟的一些话题都有可能导致定级为PG级别，《面对巨人》很成熟地讨论了怀孕，还有其他很成熟的话题，“定级为PG是因为希望父母在孩子看这部影片之前心里有数，知道孩子们会从影片中得到什么信息。”对于这种解释，议员马莎表示并不满意，她表示他们会继续研究电影分级程序和标准，希望在今年能举行听证会。克里克曼说影片制作人对如此分级并没有意见。制作人、市场部副主席克里斯', '埃里克斯·肯德里克', 'Alex Kendrick', 8, 10758, 'tt0805526', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p479660056.jpg', 1.6, 4.3, 20.5, 37.9, 35.7, '0.081447,-0.041877,-0.546112,0.696077,0.045158,-0.015020,0.417053,0.043266,-0.673070,-0.293961,-0.025911,0.708457,-0.250573,-0.084558,0.281009,-0.453712,-0.343587,-0.504066,-0.033275,-0.159090,-0.276324,-0.776145,0.011007,-0.354541,-0.227521,-0.524764,0.746594,-0.009599,-0.517258,0.196952,0.289389,0.198369,0.425227,0.409884,0.277263,-0.198391,0.034407,0.075372,-0.298999,0.330866,0.364731,-0.022680,-0.332813,0.296613,0.193175,0.502664,0.491984,-0.340033,-0.270422,0.000635,0.543410,-0.184039,0.019083,0.152354,0.252747,0.108782,0.232387,0.478873,0.099945,0.218980,-0.192317,-0.119813,-0.843489,0.069833,0.057740,0.387035,-0.316633,0.285194,-0.157151,0.041065,0.069839,-0.150301,0.174132,0.250449,0.377681,0.252783,-0.055261,-0.235367,-0.303512,0.191676,0.494176,-0.062489,-0.147480,0.409829,-0.383179,-0.541548,-0.180306,-0.239148,-0.273216,0.300065,-0.083813,0.360587,-0.118113,0.118502,-0.292434,-0.056568,0.103880,-0.507125,-0.032305,-0.767826,0.221687,-0.600928,-0.008461,-0.052614,-0.187704,-0.306142,0.129372,-0.337329,0.947261,-0.929264,0.070067,0.365845,0.535740,-0.655864,0.670557,0.213429,-0.002599,-0.397566,-0.086578,0.011680,0.044952,-0.055527,-0.107576,0.140389,0.311870,-0.580594,-0.026709,0.438682', '27602116', '25880986', '26834930', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1958447', '深蓝即是黑', '剧情', '乔治（奎姆·古铁雷兹 Quim Gutiérrez 饰）在父亲中风之后，不得不搁置自己未来的人生计划。七年来，他悉心照顾父亲，在做看门人工作的同时学习商业学位课程。他羡慕自己暗恋的女孩娜塔莉亚学有所成，想要找到一个更好的工作，但却因为看门人的工作经验屡屡失败。与父亲关系很糟的哥哥安东尼在监狱服刑，爱上一个因为吸毒入狱的美丽女子宝拉（玛塔·埃图娜 Marta Etura 饰）。宝拉与其它囚犯的男友调情遇到了麻烦，想通过怀孕进入监狱产房而躲避报复。安东尼刚开始只想和她玩玩，但很快就爱上了她，他想帮助宝拉受孕，却因为自己的不孕症而无能为力。于是他让弟弟乔治定期来监狱探访，帮助宝拉受孕。为了帮助哥哥实现愿望，乔治帮宝拉成功怀孕，却发现自己对宝拉产生了感情。乔治决定不再背负责任包袱，正视自己的愿望，与娜塔莉亚断绝关系，等待宝拉的出狱。本片获得第63届威尼斯电影节欧洲电影标签奖。', '基姆·古铁雷斯', '丹尼尔·桑切斯·阿雷瓦洛', 7.9, 5603, 'tt0452971', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p562157352.jpg', 0.2, 1.7, 23.7, 53.7, 20.7, '-0.151514,-0.008384,-0.652169,0.506955,-0.237446,-0.503895,0.552047,0.095573,-0.388981,-0.436315,0.032776,0.722705,0.140174,0.321783,0.076425,0.053792,-0.411630,-0.639605,0.406501,0.038183,-0.293542,-0.499986,0.021235,-0.435126,-0.161628,-0.478896,0.735391,-0.109448,-0.092452,0.219900,0.311513,0.211007,0.243885,0.415143,-0.004735,-0.142572,0.124805,0.131589,-0.464612,0.344572,0.285835,-0.137032,-0.149138,0.286333,0.264859,0.219736,0.578302,0.068937,-0.131436,-0.150974,0.321242,-0.465808,-0.099090,0.047025,0.096822,-0.024189,0.055545,0.273122,-0.300596,-0.184042,-0.035349,-0.327100,-0.623604,-0.046528,0.071650,-0.049852,-0.433054,0.183933,-0.370509,0.266067,0.159415,-0.297236,-0.077410,0.602551,0.222057,0.267975,-0.518707,0.272536,-0.386671,0.243719,0.679766,-0.259249,0.102331,0.508036,-0.160585,-0.402086,0.185281,-0.231761,-0.349584,0.142025,0.093811,-0.011479,-0.355793,0.133235,-0.256695,-0.211154,-0.414035,-0.025341,0.131049,-0.453066,0.201468,-0.379648,-0.132826,0.121785,-0.495414,-0.200141,-0.021696,-0.589939,0.539257,-0.748221,0.387516,0.722701,0.410265,-0.876839,0.781604,0.293807,0.238461,-0.408133,-0.043816,0.591371,-0.128344,0.080872,-0.115946,0.062516,0.188548,-0.039284,-0.360235,0.451749', '