INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1958667', '蜡笔小新：呼风唤雨！猛烈！大人帝国的反击', '喜剧', '这天在小新居住的春日部附近，突然新开了一家叫“20世纪博”的游乐园。游乐园里到处播放着从前20世纪的旧的电视节目和电影，这里，一切都是从前时光的回放。每一个到了这里的大人，都沉浸在过去的旧时光里，而对小孩子来说，这些的东西一点意思都没有。令小新万万想不到的是，进入了游乐园的爸爸妈妈都不在理会其他事情，只是一直沉醉在以往的时光里。城里的大人们都进去了，只剩下了小孩子！这到底是谁的阴谋，小新他们能否粉碎这阴谋？©豆瓣', '矢岛晶子', '原惠一', 9.3, 36687, 'tt0831848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2327107485.jpg', 0.1, 0.3, 4.4, 22.5, 72.6, '0.588934,0.004253,-0.972064,0.558849,-0.149424,-0.330721,0.921214,-0.051903,-0.600624,-0.442694,-0.159497,0.523694,-0.147234,0.424786,-0.182666,0.118013,-0.736179,-0.699787,-0.483082,-0.463070,-0.289284,-0.275319,-0.322950,-0.036628,0.009609,0.079491,0.112573,0.408556,-0.044426,0.230188,0.266801,-0.077194,-0.216352,0.490141,-0.363237,0.340859,0.075361,0.433235,0.068128,0.091091,0.214337,-0.098088,-0.360560,0.143229,0.273545,0.418036,0.601898,-0.385725,-0.159196,0.113629,0.095191,-0.204643,-0.160339,0.121422,0.361310,-0.017606,0.511413,0.075231,-0.108029,0.208441,0.019149,-0.169439,-0.755091,0.065509,-0.013716,0.258352,-0.613210,0.651906,0.267408,-0.152603,-0.064509,-0.290804,0.701774,0.140071,0.199163,0.498000,-0.175853,-0.170135,-0.863538,0.338437,0.921367,0.053462,-0.357778,0.687960,-0.287492,-0.241391,-0.548934,-0.200323,-0.536527,0.162964,-0.150719,-0.037839,-0.394975,0.302736,-0.728891,0.514217,0.293464,-0.453523,0.006113,-0.435732,-0.234652,-0.651375,0.125055,-0.533301,-0.260001,0.226978,0.211344,-0.081040,0.775750,-0.818800,0.064995,0.504023,0.342789,-0.290420,1.089133,-0.023367,-0.059407,0.217780,0.000692,-0.201415,-0.017283,0.513275,0.127086,0.566582,0.155089,-0.252883,-0.802593,0.767499', '3055049', '1304862', '1296538', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1959195', '忠犬八公物语', '剧情', '1923年，日本秋田县大馆市天降大雪，近藤家纯种秋田犬产仔，赠与县土木科长间濑。后者将其中一犬转赠东京帝国大学教授上野秀次郎（仲代达矢 Tatsuya Nakadai 饰）驯养。上野的独生女千鹤子对此欢欣鼓舞，而上野夫妇却面露难色。后来，千鹤子（石野真子 Mako Ishino饰）谈恋爱，竟怀了男友的孩子。男友专程登门造访。上野与之对谈，后者诚惶诚恐，坦言要对其女儿负责，事不宜迟，即日便举行婚礼，上野闻听此言，转怒为喜。千鹤子出嫁后，上野旋即把全部的心血与爱都投注在幼犬身上，并取名为阿八。每日上下班，阿八必在涩谷车站等候，一年四季，风雨无阻，令路人叹为观止，成为地方一道风景，主仆之情感动天地……本片根据真实事件改编，为1987年日本票房冠军，票房成绩高达54亿日元。©豆瓣', '山本圭', '神山征二郎', 9.2, 180285, 'tt0093132', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2603716224.jpg', 0.2, 0.4, 5.4, 27.8, 66.3, '-0.305829,-0.234080,-0.444514,0.285623,0.169542,-0.226146,0.148807,0.213786,-0.417174,-0.261723,0.025934,0.598586,-0.373627,0.220165,0.412267,-0.096177,0.018156,-0.486083,-0.095887,-0.249103,0.220073,-0.299438,0.203382,-0.127950,-0.251400,-0.055456,0.414966,-0.021944,0.306309,0.928585,0.310033,0.322301,-0.257322,0.152922,0.321741,-0.129709,-0.038676,0.184747,-0.366750,0.220722,-0.523140,-0.092551,-0.109661,-0.054780,0.207449,0.177015,0.613116,-0.065514,-0.173416,-0.424261,0.250299,-0.079482,0.216357,0.237004,0.587461,0.061838,0.292337,0.343393,-0.321003,0.063687,0.010936,-0.204463,-0.120228,0.035286,0.060824,-0.100494,-0.210370,0.446579,-0.105505,-0.219217,0.077625,-0.413663,0.050094,0.174459,0.296455,0.291039,-0.057947,0.134388,0.179688,0.159599,0.358216,-0.158821,0.245657,0.108272,-0.088050,-0.443725,0.115020,-0.137052,-0.252388,0.092452,-0.206306,0.263141,0.270857,0.059450,-0.281146,-0.140799,-0.157933,-0.152161,0.304572,-0.241700,0.074588,-0.520717,0.098307,-0.315005,-0.248294,0.076837,0.618514,-0.158751,0.620046,-0.577901,-0.114851,0.416245,0.446982,-0.264805,0.468816,0.002584,0.121052,-0.246691,0.041724,0.018906,0.233704,0.291578,-0.103499,0.102568,-0.119709,-0.128587,-0.394541,0.070990', '26365262', '25723081', '35256235', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1959877', '崖上的波妞', '动画', '海神的女儿波妞从深海出逃玩耍，却被困在玻璃瓶里冲到岸上，碰巧被住在岸边悬崖的宗介救出，两人因此相识。但是波妞的父亲——魔法师藤本，认为人类世界肮脏丑陋，强行把波妞带回海里。面对父亲的阻挠、席卷小镇的海啸，以及永远失去魔法的威胁，波妞仍然大胆而坚决地决定——要变成人类跟宗介在一起。而承诺要永远保护波妞的宗介，也即将面临新的挑战...', '神月柚莉爱', '宫崎骏', 8.6, 450447, 'tt0876563', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2627847859.jpg', 0.2, 0.8, 12.4, 42.2, 44.5, '0.044954,0.041208,-0.584330,0.397948,-0.276767,0.011958,0.657763,0.209914,-0.147107,0.034073,0.485256,0.873885,0.285975,0.176212,0.259626,-0.061393,-0.024063,-0.559929,-0.211741,-0.038745,-0.460081,-0.510772,-0.098848,-0.278729,-0.116932,-0.413894,1.001965,0.234435,-0.143630,0.361537,0.216201,0.203813,-0.588963,0.540303,-0.253862,-0.258064,-0.241758,0.319145,-0.315899,0.534393,-0.149019,-0.105209,0.187007,0.287696,0.088378,0.052769,0.653580,-0.559248,0.041911,-0.103694,0.229454,-0.516601,0.014234,0.154549,0.592922,-0.178222,-0.105552,0.070557,-0.219246,-0.063214,0.397540,-0.225504,-0.487888,0.004392,0.162871,0.013468,-0.752239,0.125391,0.480783,0.134132,0.365345,-0.105443,0.034933,0.147764,0.103325,0.420943,-0.540475,0.215423,-0.323106,-0.259911,0.725048,-0.391847,-0.135423,-0.075694,-0.119549,-0.059096,0.062551,-0.464641,-0.515361,-0.015947,0.055391,0.343837,-0.750880,0.492483,-0.754752,-0.176587,-0.404722,0.049081,0.274440,-0.487556,-0.299394,-0.359920,0.084355,-0.018103,0.065162,0.124192,0.035090,-0.153378,0.734699,-0.708746,0.479361,0.647575,0.550043,-0.268990,0.591219,0.142713,0.148623,-0.161319,0.201385,0.652578,0.215042,0.403769,-0.106308,0.001908,0.066457,0.258105,-0.451795,0.462978', '1294766', '1438591', '6974439', '35287908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1960313', '变异编年史', '动作', '未来世界，人类社会由四个权力体掌控。三岛统治东方，鲍豪斯统治欧洲，伊比里奥统治非洲，卡比特尔则统治着美洲。此时地球能源几近枯竭，疾病灾祸肆意横行。为了争夺有限的资源，这四个权力体的战争不断，此消彼长。时间来至2707年，在鲍豪斯和卡比特尔正在进行一场血腥残酷的战争，剧烈的爆炸摧毁了一个古老的封印，双方士兵随后面临新的敌人——残忍无度的变异人。原来他们的炮火无意中使冰河时代末期来自外太空的神秘机器重新启动，它可以将人类转化为残忍血腥、丧失人性的变异人，并且有如病毒一般以极快的速度蔓延。地球危在旦夕之时，统治者们抛弃地球独自逃亡。而幸存者们则要找到古老的兄弟会以及他们口中的编年史，继而找出彻底消灭变异人的办法……©豆瓣', '托马斯·简', '西蒙·亨特', 5.4, 7177, 'tt0490181', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2268523814.jpg', 10.7, 28.9, 43.5, 12, 4.9, '-0.169948,0.448963,-0.588088,0.554024,0.001952,0.184916,0.739010,0.046454,-0.338346,-0.052376,0.142738,0.363986,0.346333,-0.272948,0.224561,-0.268390,-0.221829,-0.332175,-0.259810,0.133637,-0.552168,-0.102384,-0.663488,-0.721026,-0.072257,-0.553824,0.679923,0.275805,-0.349925,0.196833,-0.189271,0.506189,-0.327062,0.250141,-0.052957,-0.233986,-0.100977,-0.367801,-0.513755,0.158791,-0.355136,0.044422,0.005793,0.219555,-0.429239,0.086984,0.728453,-0.581160,0.211480,-0.935415,0.451822,-0.522351,-0.251070,0.086182,0.496375,-0.070730,0.020816,0.105371,0.138168,-0.022992,0.241786,-0.080351,-1.128731,-0.314179,-0.205882,0.055801,-0.085995,0.318404,0.170325,0.009975,-0.094138,-0.147599,-0.010416,0.590896,0.226896,0.418528,-0.329212,-0.203292,-0.376752,0.096196,0.732433,-0.336525,-0.820209,-0.011200,-0.121584,-0.471988,-0.320705,-0.583763,-0.391497,-0.374028,0.427276,0.300846,-0.064567,0.841002,-1.081919,-0.017910,-0.257540,-0.542037,0.041937,-0.102615,-0.092133,-0.687931,-0.408778,-0.164044,-0.017225,0.173130,0.113209,-0.001078,0.997562,-0.565705,0.298797,0.695767,0.436752,-0.678795,0.123855,-0.211942,0.264863,-0.378274,-0.196816,0.609860,0.124949,0.422496,-0.018137,0.229519,0.029966,0.288343,-0.244217,0.683141', '26667010', '1292680', '4181031', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1961963', '长江七号', '喜剧', '小狄（徐娇 饰）是一个在贵族学校念书的穷孩子。他诚实善良，却总是遭到富家子的欺负和嘲笑。小狄和爸爸（周星驰 饰）住在一所废弃的旧房子里，爸爸每天拼命的工作，就是为了让他念好书，将来出人头地。平日，小狄总是很乖，就算体育课因为没有运动鞋而被老师罚站，他也从不埋怨爸爸。可是这一次，为了一个大家都有的玩具，小狄跟爸爸发起脾气来。爸爸买不起，就在垃圾堆里捡了一个“球”给儿子玩。谁知，这个透明的小球却变成一只活泼可爱，拥有超能力的太空狗。小狄欣喜极若狂，给他取名叫“长江七号”。小狄梦想着用七仔的超能力考100分，却没想到七仔非但没有帮到他，却让他得了个零蛋。他偷偷修改了成绩单，跟爸爸说了一次谎。爸爸大怒，小狄离家出走，赌气要凭真本事考好成绩给爸爸看。谁知，正当小狄笑着，拿着成绩单的时候，工地发生事故，爸爸从楼上摔了下来……©豆瓣', '周星驰', '周星驰', 7.1, 444095, 'tt0940709', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2097947361.jpg', 1.2, 7.4, 41.8, 34.2, 15.4, '0.146946,-0.244292,-0.562776,0.568281,-0.584656,-0.561208,0.563909,0.127462,-0.111314,-0.159993,-0.142953,0.607109,-0.060213,0.478773,-0.344894,0.146019,-0.092354,-0.504404,0.182362,0.021545,-0.182326,-0.297506,-0.137477,0.103544,0.049872,-0.135779,0.083880,-0.326256,-0.145235,0.303523,0.264269,-0.167957,0.229523,0.406131,-0.355435,0.142454,-0.186558,0.435710,0.331498,0.200477,0.283034,-0.124607,-0.134084,0.095517,0.425925,0.211555,0.559649,0.104465,-0.036443,0.030360,0.331560,-0.175519,-0.167720,0.077976,0.234082,-0.152658,0.211350,-0.171232,-0.117752,0.160138,0.394799,-0.168924,-0.537939,-0.146272,-0.041448,0.072601,-0.735223,0.576492,-0.180879,-0.006382,0.196648,-0.426129,0.170298,0.074707,0.004988,0.604331,-0.408610,0.190896,-0.628578,0.142103,0.367768,-0.238119,0.160574,0.350158,-0.098849,0.014441,0.559891,-0.254061,-0.682435,0.218159,0.157073,-0.336637,-0.537465,-0.122329,-0.492895,0.062943,-0.025511,-0.095263,-0.170630,-0.652187,-0.216721,0.068767,0.296164,-0.186643,-0.278510,0.204934,-0.098919,-0.324394,0.803913,-0.693999,0.231846,0.501719,0.335040,-0.434755,0.700062,0.390929,-0.115185,0.024203,0.279153,-0.374757,0.068261,0.462365,0.237666,0.363523,0.301021,-0.432397,-0.322550,0.565508', '1292720', '26348103', '25907029', '1305175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962112', '泰若星球', '动作', '和平美丽的泰若星上女孩马拉（埃文•蕾切尔•伍德 Evan Rachel Wood 饰）与同伴塞恩（贾斯汀•朗恩 Justin Long 饰）在滑翔比赛游戏时突遇地球战舰，善良的泰若星人以为神明降临，结果竟被抓走，包括马拉的父亲。马拉驾驶滑艇将一架人类战机引入风洞，却好心救下中尉吉姆（卢克•威尔森 Luke Wilson 饰）和机器人吉蒂（大卫•克洛斯 David Cross 饰）。为了救回父亲，马拉帮吉姆修好了战机零件，并随吉姆和吉蒂进入人类战舰，却只发现汉默尔将军（布莱恩•考克斯 Brian Cox 饰）一意孤行决定占领泰若星，改造大气层，同时杀死全部泰若星生物。一场大战不可避免，泰若星过去的秘密也终被揭示出来……本片获2008年加拿大渥太华国际动画电影节最佳动画电影大奖。©豆瓣', '埃文·蕾切尔·伍德', '阿瑞斯特曼尼斯·瑟巴斯', 7, 6820, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p557999996.jpg', 1.4, 6.1, 43.6, 38.9, 10.1, '-0.207146,0.141316,-0.366812,0.362482,0.130661,-0.371083,0.579358,-0.128630,-0.250185,-0.145159,0.313954,0.529884,-0.120490,-0.376570,0.563533,0.141727,-0.782688,-0.262687,0.130239,-0.006549,-0.371082,-0.456433,-0.221651,-0.114489,0.265585,-0.481403,0.664149,-0.137093,-0.072091,0.464563,-0.016577,0.334902,-0.244236,0.303254,0.247171,0.145438,0.090957,-0.258071,-0.289565,0.150068,-0.494845,0.053540,-0.000819,-0.194147,0.102731,0.145417,0.642683,-0.441362,0.389778,-0.375513,-0.148723,-0.311694,0.335298,-0.149585,0.140370,-0.173081,0.007445,-0.005915,0.098314,0.045613,0.282293,-0.011110,-0.402642,0.137659,-0.192567,-0.158753,-0.264772,0.130139,-0.353067,0.329618,-0.131271,-0.193307,-0.042926,0.112593,0.372202,0.149687,0.004184,0.279747,-0.610134,-0.136064,0.338099,-0.189092,-0.179463,0.140380,0.077054,-0.407509,-0.102650,-0.331035,-0.346350,0.050278,0.536808,-0.146992,0.009165,0.415391,-0.570887,-0.220037,-0.584741,-0.321566,-0.026117,-0.210429,0.106378,-0.613347,0.212673,0.039024,-0.057037,-0.032989,0.007447,-0.086586,0.450581,-0.370233,0.300884,0.360202,0.250609,-0.084054,0.443048,-0.097741,0.249838,-0.369314,-0.064464,0.397388,0.200103,0.273031,-0.055517,0.138862,0.163888,-0.170399,-0.214521,0.281838', '1297389', '20274039', '21349734', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962115', '蹩脚英语', '剧情', '35岁的诺拉（帕克•波西 Parker Posey 饰）是曼哈顿的一个成功的职业女性――她是一间高级酒店的客服主管。虽然她精明能干，一眼就能看穿客人的需要，但是她却一直未能找到自己的爱情归宿，她在处理感情方面简直一塌糊涂。诺拉曾同酒店的客人――明星尼克发生过关系，但当她满怀憧憬的时候，才发现对方不过是为了演出而和她体验生活。在一个个“第一次约会”失败后，心灰意冷的诺拉遇上了说着一口蹩脚英语的法国人朱利安（梅尔维•珀波 Melvil Poupaud 饰）。两人的感情迅速升温，可是朱利安很快就要回法国了，他邀请诺拉和他一起“私奔”。可是感情屡受挫折的诺拉竟忽然没了信心，拒绝了朱利安。当朱利安回国后，诺拉才恍然大悟：自己再也没法忘掉这个男人。于是她在好友陪伴下来到了巴黎。©豆瓣', '梅尔维尔·珀波', '佐伊·R·卡萨维蒂', 7.2, 7365, 'tt0772157', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p753738370.jpg', 0.8, 6.1, 40.6, 38.1, 14.4, '0.381754,0.094283,-0.770873,0.463909,-0.266272,-0.611057,0.845609,0.019125,-0.475007,-0.172369,0.160766,0.823238,-0.305125,0.449115,0.322775,0.194656,-0.409568,-0.860538,0.198140,-0.297925,-0.258446,-0.534579,-0.306938,-0.044125,-0.075135,-0.127729,0.345332,-0.126811,-0.077968,0.309870,0.272241,0.007589,0.215189,0.842416,-0.221156,0.188782,0.238876,0.045839,-0.175885,0.256067,0.290819,-0.179704,-0.379061,0.385238,0.120979,0.442540,0.460725,-0.080435,-0.243966,0.226731,0.089404,-0.249094,-0.008006,0.171435,0.253617,-0.167095,0.322505,-0.005734,-0.085204,-0.092092,0.087826,0.062114,-0.522825,0.226243,-0.154702,0.084763,-0.632979,0.486605,-0.085119,0.012018,-0.024735,-0.548453,0.119492,0.283884,0.190930,0.435005,-0.335385,0.005839,-0.612234,0.229512,0.666879,0.082308,-0.356422,0.654315,-0.219203,-0.450942,0.007456,-0.102444,-0.570130,0.016194,0.355847,0.159511,-0.325578,-0.013565,-0.512032,-0.178484,-0.356226,-0.086922,-0.027326,-0.479503,0.268450,-0.530078,-0.254981,-0.484820,-0.464099,-0.024210,-0.052361,-0.195036,0.598802,-0.995731,0.143756,0.613817,0.281622,-0.486197,0.692696,0.165141,-0.019515,0.029240,0.100328,0.204204,-0.302729,0.222339,0.235598,0.529364,0.308110,-0.135751,-0.178918,0.584900', '1308755', '4275444', '1309080', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962116', '我在伊朗长大', '剧情', '电影改编自伊朗女插画家Marjane Satrapi的同名漫画，以自传的形式讲述了自己的成长经历，反映了伊朗的社会变迁。1979年之后，伊朗发起了伊斯兰教革命，社会动荡不安，革命的失败更使伊朗失去民主的希望，日渐保守，人民苦不堪言。九岁的Marjane早熟、敏感，她聪明地瞒过官方爪牙，迷上了西方朋克乐队和流行音乐，沉浸在自己的世界。两伊战争爆发之后，伊朗的生活更加艰难，Marjane渐渐长大，越来越大胆的行为让父母担心不已，她14岁那年，被父母送到了奥地利上学。在奥地利，Marjane身为一个伊朗人，不得不面对别人的歧视和自卑的情绪。当她终于克服了心理障碍，赢得大家认可的时候，爱情的伤痛和对家乡的思念，却使她决定回到父母身边。此时的伊朗，依然经历着战火的洗礼，宗教对妇女生活的限制越发严苛，Marjane开始怀疑自己是否应该在这个充满专制的国度继续生活下去。', '齐雅拉·马斯楚安尼', '文森特·帕兰德', 8.7, 118141, 'tt0808417', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1486953055.jpg', 0.2, 0.7, 10.2, 42.4, 46.5, '0.133862,0.156545,-0.727881,0.638918,-0.074012,-0.197504,0.554054,-0.020467,-0.509731,-0.171602,0.081793,0.758064,0.005792,0.250852,0.192915,-0.337415,-0.390925,-0.796411,-0.160458,0.192415,-0.222654,-0.310921,-0.133431,-0.241838,-0.436579,-0.489113,0.817344,0.292292,-0.534637,0.332634,0.120618,0.288420,0.349464,0.409518,-0.192003,-0.052558,0.038703,0.082349,-0.374902,0.002686,0.301156,-0.241651,-0.207443,0.350914,-0.216452,0.168060,0.716043,-0.344526,-0.309677,-0.350837,0.720188,-0.388123,-0.454424,0.251373,0.146572,0.193101,-0.037349,0.089587,-0.077693,0.109217,-0.251203,-0.064746,-0.589801,-0.099477,0.123251,0.046157,-0.643125,0.474390,0.079908,0.019490,0.083159,-0.290756,0.015733,0.630569,0.193725,0.631322,-0.381558,0.093584,-0.323312,0.226219,0.844465,-0.112639,-0.603361,0.278212,-0.604898,-0.342561,0.006578,-0.379231,-0.710221,-0.183256,0.095352,-0.074109,-0.433962,0.695761,-0.621139,-0.046570,-0.051857,-0.612852,0.364640,-0.435158,0.049463,-0.401627,-0.617222,-0.794332,-0.249039,-0.098373,0.000031,-0.259067,1.060061,-0.896797,0.391037,0.465774,0.384553,-0.727506,0.492167,0.394442,-0.080287,-0.242195,-0.094465,0.805235,-0.391227,0.140949,-0.075191,0.201345,-0.120203,0.023733,-0.312957,0.639377', '27040921', '26348103', '6963575', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962230', '雀圣3自摸三百番', '喜剧', '万金游（郭晋安 饰）是“雀爷”万叔（夏雨 饰）的独生子，麻雀技艺深得父亲真传，是承继父亲的赌业的好人选。一筒（元秋 饰）是万金游的干妈，一直把金游当成自己的亲儿子，疼爱有加。可是在在雀爷大寿的当晚，从拉斯维加斯回来的雀爷也带上了他的新任妻子二索（刘琸琪 饰）。金游跟一筒都觉得二索图谋不轨，原来她联手雀爷的死对头爆棚要霸占雀爷的一切产业。故意让金游认识倒霉透顶的吴靓（杨思琦 饰），使金游的牌运急速下跌，每次打牌拿的都是烂牌。幸好金游学会了乐观处事，运气刚要回来的时候，女友却被爆棚挟持……©豆瓣', '郭晋安', '林子皓', 5.7, 8932, 'tt0934871', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2175560002.jpg', 5.6, 23.3, 56.5, 10.8, 3.9, '0.005600,-0.108512,-0.596060,0.520590,-0.371085,-0.292026,0.282040,0.252993,-0.617116,-0.075025,0.261609,0.684451,-0.234730,0.057865,0.141862,0.206749,0.206123,-0.437442,-0.212484,0.066639,-0.201939,-0.412836,-0.158847,0.098092,-0.110736,-0.107149,0.159866,-0.169429,-0.151371,0.363969,0.589037,0.098661,0.168063,0.411575,-0.376858,0.115813,-0.263273,0.244367,-0.068782,0.175705,0.105122,-0.177851,0.061676,0.332333,0.262470,0.335229,0.356129,-0.022855,0.006777,-0.010697,0.275512,-0.247465,-0.222670,0.066319,0.413881,-0.010356,0.069258,0.099022,-0.259644,0.110008,0.112003,-0.153846,-0.662175,-0.022255,0.358549,-0.224993,-0.750777,0.423540,-0.162404,-0.008004,0.042619,-0.378520,0.413954,0.225326,-0.149510,0.566697,0.001597,0.057363,-0.652050,0.329581,0.359487,-0.168001,0.140056,0.308926,0.039506,-0.196082,0.158363,-0.316834,-0.429110,-0.097781,0.313386,0.008823,-0.037032,-0.084934,-0.291318,-0.067846,-0.007212,0.064785,0.194046,-0.414216,-0.162312,-0.072802,-0.012904,-0.644319,-0.108176,0.028402,0.012390,-0.441668,0.632860,-0.664809,0.085001,0.345722,-0.000354,-0.716976,0.777416,0.224702,-0.243428,-0.349641,-0.171205,-0.190879,0.170318,0.052023,0.197774,0.212082,0.182257,-0.479459,-0.293825,0.384306', '1308805', '1293607', '1299649', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962319', '爱我生活', '爱情', '可爱的市子（吉井怜饰）是大学里一名普通的大学生，她和父亲（石田衣良饰）感情很好，但是市子却不得不告诉父亲自己是lesbian的事实，并向他介绍了自己的恋人英理（今宿麻美饰）英理是法律系大三的学生，是个独立自主的女学生，她和父亲感情不好，所以一直希望可以考取律师资格，面对考试的压力与爱情的抉择，两个人的恋情能够开花结果吗？©豆瓣', '吉井怜', '川野浩司', 7.1, 9889, 'tt0923779', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2604735447.jpg', 1.2, 7.1, 42.1, 35, 14.5, '0.369683,-0.420984,-0.384225,0.874743,-0.538744,-0.175352,0.879548,0.098326,-0.681800,-0.452595,-0.108021,0.936505,0.119073,0.768967,0.048199,0.209907,-0.060135,-0.905839,0.216259,-0.222014,-0.097278,-0.584977,-0.244161,-0.055928,-0.362193,-0.239940,0.906312,0.052684,-0.158578,0.337598,0.468828,0.194353,0.332840,0.578681,-0.394602,-0.160933,-0.100464,0.304601,-0.323311,0.125611,0.325171,0.052860,-0.143172,0.456852,0.273571,0.419407,0.535577,-0.035242,-0.324299,0.037317,0.359942,-0.574064,-0.125508,0.583596,0.337581,-0.131929,0.537323,0.284845,0.257546,0.020805,-0.209128,-0.259885,-0.700290,-0.217851,0.237046,0.234586,-0.653909,0.751601,0.095229,-0.220188,0.181186,-0.162815,-0.081305,0.232985,0.045162,0.602466,-0.616030,-0.010825,-0.373807,0.246143,0.907858,0.173340,-0.349224,0.645407,-0.532995,-0.670251,-0.078580,-0.186986,-0.794006,0.263882,-0.168636,0.147654,-0.262821,-0.017307,-0.433722,-0.147822,-0.127534,0.012297,-0.058185,-0.884228,0.243953,-0.034256,0.020093,-0.812742,-0.913937,0.002143,0.014779,-0.539674,1.185988,-1.252314,-0.254652,0.493700,0.517185,-0.722458,0.822106,0.560968,-0.019492,-0.325981,-0.146284,0.125838,-0.371287,0.069070,-0.131274,0.521688,0.344311,-0.347833,-0.391224,0.535708', '6963575', '1395231', '35030151', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962508', '双子神偷', '喜剧', '从小被喇嘛收养的刘曦（吴京饰），跟随养父吉祥（洪金宝饰）护送“贡佛天珠”，怎料途中被一群神秘人偷去。吉祥怀疑事件与多年前销声匿迹的“双子门”有关，于是找到了当年的校长常忠（元华饰）。为了尽快找到丢失的天珠，吉祥以及常忠决定重组“双子门”，从马戏团找回双胞胎姐妹珍珠（蔡卓妍饰）、宝珠（钟欣桐饰）以及其余学生。苦苦追寻终于发现天珠下落，与一班似乎同是“双子门”的人大打出手。刘曦最后抢到了“天珠”，却误交给常忠弟弟，常勇。同时也发现了更多的秘密。©豆瓣', '蔡卓妍', '江道海', 5.7, 35568, 'tt0934949', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p486808942.jpg', 6.4, 24.8, 51.4, 12.6, 4.8, '0.018688,-0.058800,-0.485860,0.321690,0.085905,-0.380510,0.373395,0.079175,-0.645715,-0.297495,-0.035933,0.458586,-0.159592,0.190497,0.230068,0.134460,-0.239406,-0.437850,0.003423,-0.374021,-0.178640,-0.288546,-0.050003,0.293970,-0.057303,-0.343938,0.553286,-0.060301,0.068767,0.489646,0.309958,0.341333,-0.658369,0.002627,-0.030600,0.337436,0.027182,0.044987,-0.391732,0.079676,-0.044676,-0.088582,-0.091254,-0.127462,0.104630,0.111781,0.368121,-0.348538,0.111319,-0.311463,0.023182,0.062957,-0.323448,-0.019542,0.218397,0.590312,0.206178,0.371868,-0.332367,0.126768,0.296948,-0.186593,-0.461078,0.269008,0.441635,0.058877,-0.610774,0.231804,0.090689,0.017977,0.329128,-0.329452,0.496856,0.496778,-0.026407,0.128134,-0.380115,0.032154,-0.514410,0.095345,0.450317,-0.385498,0.360185,0.187227,0.580965,-0.233481,0.197545,0.076296,-0.025880,0.438564,0.719703,0.355679,0.121692,0.058927,-0.609224,-0.245413,-0.322761,0.049048,0.477517,-0.329947,0.058585,-0.582933,-0.098554,-0.107903,-0.095602,-0.054630,-0.114286,-0.143805,0.762488,-0.576436,0.399248,0.280597,0.172214,-0.618869,0.386550,-0.257768,0.418618,-0.398584,-0.229322,-0.062876,0.278540,0.582452,0.055376,-0.016468,-0.097437,-0.289683,-0.210053,-0.281717', '1307793', '1302786', '1408130', '2159331');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962611', '蜡笔小新：呼风唤雨！夕阳下的春日部男孩', '动画', '某日，小新（矢岛晶子 配音）一家人来到一间废弃的电影院中寻找失踪的风间（真柴摩利 配音），哪知道竟被吸入了荧幕之中，穿越到了一个名为“正义之都”的西部小镇内。这里的统治者是名为杰士提斯（小林清志 配音）的男子，在他的铁腕政策下，居民们生活得十分压抑困苦。在酒吧里，小新找到了风间，可此时的风间已经成为了小镇里的警长。之后，小新邂逅了名为小椿（齐藤彩夏 配音）的女孩，她不仅屡屡向小新一行人伸出援手，还替他们找到了安身之所。小椿希望有朝一日能够推翻杰士提斯的统治，小新决定助她一臂之力，广志（藤原启治 配音）发现若是想要从电影中脱身，那就必须顺应剧本将电影演完，一场精彩的大戏就此拉开序幕。©豆瓣', '矢岛晶子', '水岛努', 9.2, 18473, 'tt0769760', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2435714673.jpg', 0.1, 0.4, 6.3, 28.2, 65, '0.017558,0.202185,-0.532896,0.369792,-0.072538,-0.312746,0.505034,0.066188,-0.367962,-0.039334,0.278859,0.625038,-0.178499,0.492520,0.609951,0.250916,-0.293414,-0.651014,-0.109936,-0.254439,-0.129241,-0.156103,-0.541079,-0.040613,-0.284008,-0.204399,0.744100,0.382087,-0.136659,0.170553,0.148497,0.076054,-0.367993,0.274764,0.113995,0.177474,-0.005432,-0.098720,-0.255347,0.395248,-0.111051,-0.297156,-0.303362,0.217600,0.026959,0.417578,0.559983,-0.373782,0.011495,-0.131119,0.304812,-0.196003,-0.182267,0.220980,-0.031798,-0.018448,0.311509,0.161255,-0.349478,0.143770,-0.133133,-0.113806,-0.637005,0.056330,-0.015907,0.269934,-0.431195,0.258232,0.052980,-0.307103,0.216507,-0.395019,0.166267,0.256824,0.556315,0.441700,-0.318656,0.118747,-0.288052,0.018943,0.546243,-0.059353,-0.007305,0.370465,0.212475,-0.495044,0.116103,0.007090,-0.363666,-0.125327,0.278234,0.018008,-0.112775,0.038467,-0.542301,0.017429,-0.167309,-0.123703,0.090627,-0.306039,0.009668,-0.772731,-0.039997,0.015359,-0.023922,0.101368,0.068391,-0.399292,0.724814,-0.779557,0.049638,0.550859,0.306712,-0.077294,0.520311,0.023939,0.216299,0.088286,0.097109,0.066085,0.033305,0.656036,0.155764,0.373667,-0.117543,-0.483889,-0.621846,0.476392', '2369613', '3811356', '3266509', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1962968', '在屋顶上流浪', '剧情', '男孩哈勒姆（杰米•贝尔 Jamie Bell 饰）自小就十分依恋母亲，他喜欢拿着妈妈的东西胡闹：拿眼线笔画眼线、拿唇膏到处涂抹、用妈妈的耳钉帮自己穿耳洞……然而，他的母亲却突然离世了，之后他的爸爸娶了他的继母。哈勒姆十分悲伤，正处在青春叛逆期的他怀疑母亲是被他的继母谋害的。于是，哈勒姆把自己慢慢于是隔绝开来，经常喜欢独自一人在树屋内远远的偷窥着别人，为的是能探究出母亲的死亡之谜，帮她复仇……©豆瓣', '杰米·贝尔', '大卫·马肯兹', 7.7, 8757, 'tt0466816', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1343951213.jpg', 0.6, 2.5, 26.3, 51.1, 19.5, '0.335147,0.120680,-0.580878,0.516578,-0.629723,-0.345450,0.653708,0.333759,-0.460332,0.017362,0.146788,0.788070,0.050669,0.610686,-0.214395,0.492028,-0.184751,-0.727284,0.218967,0.005240,-0.297402,-0.195728,-0.298294,-0.046917,-0.194517,-0.241866,0.364880,-0.291620,-0.044664,0.142711,0.183188,0.165808,0.094835,0.703157,-0.402353,-0.056369,-0.502527,-0.129467,-0.089013,0.036270,0.440199,-0.281460,0.038714,0.251819,-0.125490,0.310352,0.702532,-0.298546,0.290497,-0.266221,0.347568,-0.242835,0.131400,0.216092,0.037324,0.022777,0.240393,-0.148251,-0.339960,-0.117376,0.245660,-0.153502,-0.367158,-0.046597,-0.001107,0.188709,-0.642676,0.313396,-0.327315,0.003377,0.612435,-0.340462,0.228040,0.094118,-0.176602,0.428403,-0.512696,-0.293673,-0.536199,0.317961,0.153651,-0.214921,0.340151,0.486101,-0.411400,0.044308,0.268983,-0.349062,-0.741655,-0.106008,0.293180,-0.090736,-0.288665,-0.007887,-0.458882,-0.134628,-0.039945,-0.078084,0.066280,-0.485421,-0.220711,0.098275,-0.062363,-0.354399,-0.351806,-0.219207,-0.060929,-0.125504,0.504415,-0.632522,0.483861,0.566825,0.193271,-0.503814,0.475217,0.086346,0.050568,-0.111965,-0.262746,0.373188,-0.145743,0.345165,0.403811,0.399122,0.193613,0.131220,-0.370280,0.578386', '1292207', '1292719', '1293372', '1396313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1963131', '地下幻灯剧画 少女椿', '剧情', '少女椿（松井良彦 配音）的母亲死于重病，没有亲戚愿意收留这个可怜的孩子，于是，椿跟随着卖花时结识的戴帽子的绅士来到了名为“赤猫座”的马戏团中，在这座破败荒芜的马戏团里进行表演的，都是一些或是残疾或是古怪的“异人”们，在这里，椿悲惨的遭到了他们的凌辱，沦为众人的奴隶，过着苦不堪言的生活。马戏团里新来了一位能够将自己塞进狭窄玻璃瓶的侏儒魔术师，他的表演大受欢迎，很快就令快要倒闭的马戏团赚得盆满钵满，成为了老板眼中的聚宝盆。与此同时，椿和魔术师之间也产生了懵懂的感情，然而，就在两人决定双宿双飞之时，魔术师却遇见了意外一命呜呼。©豆瓣', '松井良彦', '絵津久秋', 7.8, 11162, 'tt0930902', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2548468039.jpg', 1, 2.5, 25.3, 46.2, 24.9, '0.468386,-0.095635,-0.616548,0.201143,-0.246092,-0.250749,1.000454,0.139728,-0.517403,-0.052847,0.230523,0.929568,-0.290592,0.617267,0.287426,-0.032790,-0.100549,-0.661744,-0.521205,-0.326500,-0.214454,-0.371186,-0.345163,-0.210178,-0.276462,-0.294624,0.642396,0.090374,-0.193923,0.432700,0.380031,0.242525,-0.089395,0.369902,-0.353453,0.208976,0.075616,0.076358,-0.034870,0.131366,-0.088446,-0.326440,0.083078,-0.001109,-0.089261,0.464733,0.834106,-0.480009,-0.206877,-0.121868,0.284805,-0.149179,-0.175069,0.496438,0.192797,-0.090615,0.254368,-0.083217,-0.212852,0.219891,0.216432,-0.076492,-0.753658,0.047013,0.071056,0.160359,-0.782255,0.617299,0.311601,-0.211627,-0.008252,-0.271980,0.553342,0.058459,0.284095,0.490492,-0.073026,0.180792,-0.429998,0.224016,0.686965,0.049560,-0.300583,0.382627,-0.198650,-0.462377,0.065199,-0.240417,-0.463936,-0.019696,0.448886,0.087103,-0.227157,0.220930,-0.573267,0.034572,-0.201815,-0.121926,-0.076781,-0.137850,-0.300355,-0.676023,-0.016856,-0.449686,-0.236977,0.176573,0.085477,-0.154374,0.719081,-0.847963,0.286437,0.370323,0.253957,-0.177135,0.674249,-0.044105,0.157258,0.108989,-0.172830,0.054907,-0.029867,0.440292,0.321521,0.348089,-0.170295,-0.211476,-0.284074,0.405563', '21619567', '3111650', '30162520', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1963512', '仙履奇缘3： 时间魔法', '爱情', '在神仙教母的帮助下，辛蒂瑞拉（詹妮弗·黑尔 Jennifer Hale 配音）和王子（Christopher Daniel Barnes 配音）结合过上了幸福的生活。然而好景不长，邪恶的后母发现了辛蒂瑞拉魔法的秘密，她偷走了神仙教母的魔杖，施法使时光倒流到了辛蒂瑞拉未去参加舞会之时，几乎是一瞬间，辛蒂瑞拉重新变回了寄人篱下的灰姑娘，失去了所有的一切。在魔法的作用下，辛蒂瑞拉那刻薄的姐姐安娜斯塔西娅（崔丝·麦妮利 Tress MacNeille 配音）穿上了水晶鞋，而王子亦被魔法蛊惑，决定迎娶安娜斯塔西娅。心急如焚的辛蒂瑞拉决定为自己的命运而战，她悄悄混入了皇宫之中。虽然没有了魔杖，但辛蒂瑞拉坚信，真爱的力量能够帮助她取得最终的胜利。©豆瓣', '詹妮弗·黑尔', 'Frank Nissen', 7.7, 5587, 'tt0465940', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526097034.jpg', 0.4, 3.4, 32.2, 41.3, 22.8, '0.207413,0.234385,-0.481207,0.709229,-0.178292,-0.515591,0.920749,0.130269,-0.277592,-0.229471,0.402739,0.853666,-0.141734,0.067244,0.283982,0.284251,-0.671224,-0.870612,0.330885,-0.133437,-0.410254,-0.368029,-0.382068,0.276091,-0.190559,-0.694727,0.655082,-0.231715,0.035817,0.270281,0.203427,0.392222,0.153355,0.234961,0.166730,0.114008,0.343557,-0.128127,-0.248549,0.373194,0.076197,-0.140166,-0.049091,0.739849,-0.201835,0.212600,0.529582,-0.661791,0.295651,-0.192578,0.447634,-0.367528,0.082974,0.187517,-0.042157,0.053672,-0.094660,-0.056427,-0.219092,0.016487,0.291344,-0.121153,-0.796923,0.266515,0.250024,0.067088,-0.795714,0.636310,-0.140136,0.061210,0.226787,-0.227374,0.192139,0.358228,0.146824,0.399040,-0.106347,0.064865,-0.525466,0.151546,0.473235,0.001655,-0.487213,0.696682,-0.218233,-0.508341,-0.089891,-0.124524,-0.658154,-0.128112,0.247275,0.363172,-0.135353,0.467668,-0.597404,-0.312194,-0.672002,0.053423,0.021199,-0.446164,0.057690,-0.441820,-0.368592,-0.268236,-0.148624,-0.322243,0.055416,-0.405429,0.693532,-1.058858,0.242473,0.571898,0.367771,-0.185159,0.547720,-0.134270,0.238390,0.040645,-0.016144,0.358818,-0.243044,0.485631,0.412843,0.337003,0.308050,0.153426,-0.571378,0.869648', '1299556', '4126925', '30401849', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1963710', '身在其中', '惊悚', '女性摄影师莎拉（Alysson Paradis 饰）和马西欧（Jean-Baptiste Tabourin 饰）这对幸福的夫妻组成的小家庭即将迎来新的成员，但一场严重的车祸摧毁了他们美好的憧憬。马西欧在车祸中丧生，莎拉以及未出世的宝宝侥幸存活。圣诞之夜，孤独的莎拉待在家中，等待第二天早晨的生产。这时敲门声响起，一名黑衣女（Béatrice Dalle 饰）请求使用电话。莎拉本能地拒绝了她，谁知黑衣女竟千方百计想要闯进来。她的目的只有一个，抢夺莎拉那尚未出世的孩子。挡路者只有死路一条……©豆瓣', '艾莉森·帕拉迪丝', '亚历山大·布斯蒂罗', 6.4, 8513, 'tt0856288', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1122785660.jpg', 5.9, 14.7, 41.7, 26.7, 11.1, '0.067228,0.284050,-0.820085,0.223353,-0.194929,-0.030474,0.880446,-0.076593,-0.085411,-0.465483,0.528235,0.786278,-0.090006,0.185334,0.489446,-0.227317,-0.251886,-0.470476,-0.153087,0.089964,-0.526648,0.068226,-0.156215,-0.266132,-0.177570,-0.284437,0.561531,0.180839,-0.005416,0.784474,0.313261,0.480269,-0.256873,0.344312,-0.283158,0.063450,0.215283,0.118109,-0.274078,0.343271,-0.158670,-0.194083,0.021863,0.067820,-0.149478,0.427721,0.660813,-0.584672,0.253475,-0.178825,0.270713,-0.293206,-0.064027,0.302833,0.350943,0.112023,0.251284,-0.050074,-0.181186,-0.280591,0.108317,0.073452,-0.615298,0.111874,0.147542,0.152202,-0.254711,0.330135,-0.059296,0.025371,0.501423,-0.045687,0.251060,0.676632,0.133277,0.498138,-0.055555,0.236791,-0.578131,0.232323,0.676647,-0.299201,-0.237926,0.332637,-0.104527,-0.557611,0.176851,-0.108274,-0.580740,-0.016667,0.531445,0.215746,-0.049481,-0.060307,-0.448026,0.059410,-0.295240,-0.110467,-0.082211,-0.287281,-0.552541,-0.550650,0.127809,-0.167214,-0.350948,0.371341,0.069741,0.083442,0.780016,-0.673883,0.393363,0.248499,0.387158,-0.373989,0.502696,0.185075,0.402384,-0.240641,0.065988,0.415584,-0.071112,0.150255,-0.026688,0.233936,-0.148902,0.008358,-0.569826,0.304103', '1296534', '1301686', '27042738', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1966121', '呖咕呖咕对对碰', '喜剧', '阿芝（李彩华 饰）是一名电视整蛊节目主持人，某日，她乔装打扮来到富贵商场进行整蛊计划，哪想到真实身份意外曝光，引发了一场混战，并因此与曾经的高中同学杰克（李璨琛 饰）重逢了。原来，阿芝从事这份不光彩的职业纯属为了赚钱，以此一圆她出国读书的梦想，在杰克等人的建议下，阿芝决定在商场中开店。想要开店，必须先征得赵富豪（夏春秋 饰）的同意，赵富豪早年丧妻，儿子赵新贵（黄浩然 饰）又在外国念书，孤身一人的他倍感孤独。赵富豪喜欢打台湾麻将，找到了突破口的阿芝苦练麻将技术，并最终成为了赵富豪的“最佳牌友”。就在事成之际，赵新贵却杀了出来，在他眼中，阿芝等人不过就是趋炎附势的骗子，他要将他们统统赶出商场。©豆瓣', '黄子华', '麦子善', 5.5, 3620, 'tt0934895', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2362483963.jpg', 7.2, 26.1, 55.9, 8.2, 2.6, '-0.009820,0.140047,-0.636762,0.483188,-0.202111,-0.500867,0.475476,0.051946,-0.418681,-0.438447,-0.135242,0.355541,-0.268153,0.365130,0.269055,-0.229482,-0.125575,-0.526647,0.010164,-0.139294,-0.175834,-0.277641,0.016949,-0.470728,-0.195715,0.220400,0.323340,0.283958,-0.237601,0.153791,0.711309,0.126834,-0.059955,0.636746,-0.144703,-0.085304,-0.081040,0.213551,-0.513500,0.150639,0.185344,-0.536581,-0.042210,-0.105340,0.354925,0.023280,0.458642,0.051703,0.152310,0.062930,0.333050,-0.047847,-0.107237,-0.127295,0.382593,-0.190626,0.006761,-0.121531,0.080733,0.085989,0.145019,-0.198786,-0.475768,-0.066514,0.208923,-0.033568,-0.664422,0.322120,-0.090409,0.081801,-0.182473,-0.292729,0.328841,0.145980,0.376083,0.136353,0.242645,0.164781,-0.579136,0.691762,0.574641,0.146331,0.200713,0.125422,-0.149977,-0.610660,0.073925,-0.114776,-0.225807,0.028899,0.625857,-0.327062,-0.158896,-0.094210,-0.213641,-0.244292,0.132595,-0.048900,0.204935,-0.416665,0.326614,-0.585249,-0.052241,-0.277927,-0.117265,0.124447,0.198503,-0.433175,0.537803,-0.793005,-0.001683,0.432802,0.241196,-0.723030,0.514897,-0.010203,0.243692,-0.269060,0.081226,0.012660,0.217377,0.340814,0.098349,0.183941,0.032655,-0.096635,-0.075929,0.395976', '1301022', '1297710', '25870679', '1302512');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1966182', '霍比特人1：意外之旅', '动作', '中土最后一座矮人王国埃尔波尔，巍峨壮丽，庄严雄伟。老国王索尔积聚大量财富，却引来恶龙史茅革的觊觎和荼毒，最终导致这座城池陷落。许多年后，灰袍巫师甘道夫（伊恩·麦凯伦 Ian McKellen 饰）找到弗罗多的舅舅——霍比特人比尔博·巴金斯（马丁·弗里曼 Martin John C. Freeman 饰），邀请他加入由13名矮人组成的远征队伍。原来史茅革已多年不见声息，背负家国仇恨的矮人王子索林（理查德·阿米蒂奇 Richard Armitage 饰）希望借此机会收复故土。经过一番考虑，巴金斯决定加入。令他想不到的是，远征旅途多灾多难，与索林结下深仇大恨的苍白半兽人及其爪牙阴魂不散，更有食人鬼和石人制造的无数艰险。而在旅途中，巴金斯也意外得到了日后影响整个中土的重要宝物……本片根据J.R.R·托尔金的同名原著改编。©豆瓣', '伊恩·麦克莱恩', '彼得·杰克逊', 8.4, 389177, 'tt0903624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2159038705.jpg', 0.4, 1.4, 14.6, 44.3, 39.3, '0.076710,0.018934,-0.662144,0.473169,0.407386,-0.382074,0.616309,-0.066771,-0.398158,-0.414779,0.249759,0.751137,-0.027916,-0.230910,0.155528,-0.132717,-0.423360,-0.266887,0.115074,-0.269070,-0.058227,-0.574399,-0.371334,-0.388467,-0.106804,-0.506957,0.686776,0.238471,0.010237,0.382494,-0.015224,0.357245,-0.011843,0.116175,-0.073323,0.112837,0.185461,-0.045187,-0.259427,0.184385,-0.337930,0.368457,-0.268203,0.234302,-0.244738,0.240611,0.354018,-0.540941,0.162338,-0.130315,0.242582,-0.156583,0.147081,-0.044995,0.411896,-0.303772,-0.040800,0.406547,-0.224210,-0.221506,0.071725,-0.169308,-0.353855,-0.038317,0.283527,0.337367,-0.447916,0.303218,0.124150,0.075198,0.049126,-0.156881,-0.019070,0.456050,0.604675,0.153594,0.433566,0.092359,-0.211324,-0.093962,0.582034,-0.174122,-0.257358,-0.380445,-0.328330,-0.384700,0.119285,-0.328523,-0.336089,-0.007567,0.277711,-0.066802,0.370791,0.759630,-0.866831,-0.119890,-0.645473,0.069523,0.026158,-0.143866,-0.067048,-0.645009,-0.191353,-0.021789,0.111647,0.134327,0.139131,-0.059674,0.549660,-0.265817,0.352809,0.408378,0.333575,-0.173235,0.346732,-0.220893,0.024271,-0.160077,-0.210634,0.675065,0.282196,-0.009477,0.116523,-0.161102,0.068436,-0.317927,-0.126383,0.167853', '35161768', '26290398', '1303910', '3878007');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1966460', '图雅的婚事', '剧情', '内蒙古日渐干旱的草原上，丈夫巴特尔（巴特尔 饰）为了掘水井而双腿残疾，妻子图雅（余男 饰）勤劳善良，性格泼辣。她一个人挑起了家庭的重担，照顾孩子，但长期的劳碌让她的腰椎病变，甚而也有下肢瘫痪的危险。为了不再耽误图雅，卧躺床上的巴特尔决意离婚，在现实面前，图雅也只能同意。但她坚持提出自己再婚的条件：新丈夫必须和自己一起供养巴特尔。由此，图雅开始了艰难的择夫历程，附加条件让许多前来求婚的男人打了退堂鼓。邻居森格（森格 饰）素来怕老婆，其妻却常跟别的男人出走，并一走了之。他对图雅情苗暗生……本片荣获2007年第57届柏林国际电影节金熊奖。©豆瓣', '余男', '王全安', 8, 28935, 'tt0949564', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p581291401.jpg', 0.2, 1.1, 19, 55.8, 23.9, '-0.111996,-0.020091,-0.726858,0.256696,-0.267946,-0.268658,0.366223,0.294915,-0.462527,0.043943,0.102387,0.801895,0.133986,0.148000,0.074741,0.015948,-0.206495,-0.485493,-0.014790,0.177189,-0.219928,-0.309702,0.152593,-0.312931,-0.333357,-0.176854,0.596828,-0.300157,0.058980,0.405062,0.389110,0.059960,0.179454,0.309788,-0.063192,-0.045137,-0.130237,0.038020,-0.211864,0.159110,0.117435,-0.073521,-0.115209,-0.011057,0.109724,0.497826,0.425731,-0.045808,-0.152520,-0.375148,0.463936,-0.153332,0.062881,0.206858,0.274696,-0.197515,0.250867,0.312349,-0.053710,-0.262724,0.229178,-0.062871,-0.159769,-0.004660,0.126825,-0.133957,-0.646942,0.474517,-0.071646,0.016234,-0.135777,-0.365343,0.082906,0.450530,0.098688,0.080993,-0.296397,0.138289,-0.295173,0.135835,0.462733,0.174363,-0.068585,0.169157,-0.507174,-0.403074,0.182050,-0.355597,-0.535712,-0.128866,0.200126,-0.059691,-0.376769,0.117346,-0.263844,0.066347,-0.243215,0.033073,-0.098418,-0.228513,0.063802,-0.012135,-0.011851,-0.345129,-0.303001,-0.031160,0.324588,-0.219205,0.556223,-0.487846,0.188578,0.527054,0.460902,-0.531698,0.535043,0.400168,0.373347,-0.172957,0.105382,0.414183,-0.308314,-0.067613,-0.002772,0.131848,-0.194518,0.175493,-0.223049,0.399249', '21354767', '1292207', '1292720', '1397550');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1966464', '苹果', '剧情', '刘苹果（范冰冰饰）在北京一家洗脚城里做按摩妹，丈夫安坤（佟大为饰）是负责清洗高楼落地窗的工人，二人生活贫困，却相亲相爱。洗脚城老板林东（梁家辉饰）是个好色的港商，时常找不同小姐满足生理需要。老婆王梅（金燕玲饰）不能生育，经营一家美容院，两人感情冷淡。一日刘苹果的好友小妹因为得罪客人而被开除，二人喝得酩酊大醉。神志混乱的苹果误打误撞走到一间足浴客房，正好是林东的休息室，二人发生关系，却被正在刷窗的安坤看到。安坤欲借此敲诈林东，并前去找王梅谈判，愤怒的王梅要林东也尝尝“戴绿帽”的滋味，于是与安坤发生关系。而在这时，一个更大的变故产生。苹果怀孕了，而到底谁才是这个孩子的父亲成了林东与安坤赌博的筹码，四人签订协议，如果是林东的骨肉，他将给二人十二万元的补偿费，而如果是安坤的，则双方互不相欠......©豆瓣', '梁家辉', '李玉', 6.7, 112351, 'tt0949489', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558318647.jpg', 2, 10.1, 46.5, 31.6, 9.7, '0.377585,-0.107482,-0.539974,0.270964,-0.248816,-0.469352,0.742965,0.478362,-0.416636,-0.196578,0.101644,0.540381,-0.057273,0.374100,0.199433,-0.123841,0.109797,-0.623380,0.108780,-0.002358,-0.213206,-0.303201,0.061140,-0.196300,-0.023640,0.056163,0.177238,-0.180910,-0.147036,0.248782,0.464885,-0.004198,-0.280711,0.574281,-0.080219,0.124010,-0.052133,0.100620,-0.503277,0.027534,0.114679,-0.410410,-0.046562,-0.055249,0.260207,0.363847,0.500894,0.039361,-0.342351,-0.113839,0.194652,-0.066561,-0.119886,0.148631,0.278599,-0.124100,0.275055,0.003397,-0.282456,-0.089740,0.298788,-0.045658,-0.564729,0.181823,0.021933,0.114442,-0.485109,0.516227,-0.026865,-0.129074,-0.081876,-0.192543,0.306122,0.460222,0.184913,0.536059,-0.371576,-0.125905,-0.791885,-0.020905,0.725239,0.099263,0.290117,0.323234,-0.223229,-0.393382,0.154388,0.108554,-0.359884,0.101422,0.372450,-0.084858,0.012707,-0.085040,-0.527228,-0.160970,-0.204345,-0.124411,0.143431,-0.317788,0.210849,-0.568806,-0.221575,-0.411734,-0.306693,0.106356,0.306014,-0.191259,0.303576,-0.662616,-0.180955,0.204431,0.329525,-0.750141,0.551710,0.091156,0.172961,-0.218390,-0.044436,-0.127670,0.066129,-0.003215,0.381975,0.473792,0.030728,-0.017392,-0.222500,0.084973', '1308755', '1301022', '25721544', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1968438', '穿越大吉岭', '剧情', '自父亲葬礼后，三兄弟已有一年互不往来。老大弗朗西斯（欧文·威尔逊 Owen Wilson 饰）计划了一次周密的印度旅行，并告诉弟弟们这是为了找回自我和彼此间的亲情。虽然不热衷这次旅行，试图摆脱各自糟糕生活的老二彼得（艾德里安·布洛迪 Adrien Brody 饰）和老三杰克（詹森·舒瓦兹曼 Jason Schwartzman 饰）还是同意了弗朗西斯的计划。兄弟三人搭乘豪华列车展开了笑料百出的穿越印度之旅，并从沿途各地收集奇怪的纪念品。终于在勾搭完女列车员、放跑作为纪念品买回的眼镜蛇和在列车上大打出手后，他们被忍无可忍的列车长连同所有行李一起扔下了车。虽然一切脱离了弗朗西斯的控制，但这计划外的变故却令兄弟三人更为接近这次旅行的真正目的……本片曾入围第64届威尼斯电影节主竞赛单元。©豆瓣', '欧文·威尔逊', '韦斯·安德森', 7.7, 59296, 'tt0838221', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1545143046.jpg', 0.4, 2.4, 28.1, 48.2, 20.8, '0.220023,-0.142903,-0.563668,0.382202,0.234389,-0.637755,0.425722,-0.006563,-0.556581,-0.157409,-0.037256,0.658167,-0.218423,0.006472,0.463435,-0.029210,-0.639113,-0.533307,-0.045860,-0.182691,-0.098930,-0.502697,-0.031063,-0.121739,-0.043648,-0.102818,0.481806,0.098233,-0.090143,0.692798,0.575770,0.042955,-0.219081,0.245005,-0.221948,0.039749,0.156684,0.130319,-0.582057,0.036416,-0.018899,-0.046320,0.027079,0.085333,0.441135,0.314874,0.626684,-0.184540,-0.062805,0.028800,0.048345,-0.173187,-0.034666,0.056160,0.200631,0.118693,0.152762,0.343874,0.031441,0.181317,0.042791,-0.125353,-0.540132,0.105283,0.003805,-0.127219,-0.600210,0.416926,-0.111452,0.062823,-0.007369,-0.194308,0.278488,0.661763,0.267880,0.076876,-0.019681,0.048071,-0.341278,0.048587,0.723788,-0.072230,-0.032235,0.137480,-0.114558,-0.332869,0.015384,-0.092167,-0.214517,0.115883,0.491489,0.073013,0.041612,0.268479,-0.649301,-0.143682,-0.228944,-0.355333,0.205800,-0.310561,0.136406,-0.917523,0.106178,-0.287756,-0.114167,0.010221,0.023881,-0.100328,0.455200,-0.660719,0.230619,0.248136,0.261980,-0.476721,0.378036,0.180902,0.343043,-0.428804,-0.035281,-0.043118,0.019876,0.571396,0.168743,0.311052,0.048754,-0.313448,-0.333243,0.254633', '11541282', '3178770', '25833539', '1296339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1968502', '陆小凤传奇之大金鹏王', '武侠', '隐匿江湖多年的柳余恨（杨世星 饰）突然现身，陆小凤（张智霖 饰）深感诧异。原来这与五十年前金鹏王朝遗留的稀世珍宝有关。陆小凤碍于金鹏王相求和上官飞燕（吴佳妮 饰）卷入此事，决定帮忙查找当年的三个叛臣，他很快找到关中珠宝阁大当家的严立本和峨嵋掌门严独鹤，但两人很快便死于西门吹雪（何润东 饰）和丹凤公主（吴佳妮 饰）剑下，二人的死使刚有眉目的线索戛然中断，事情变得扑朔迷离。紧接着花满楼（张智尧 饰）离奇失踪，丹凤公主也中毒身亡，通过缜密梳理，陆小凤发现求他办事的金鹏王竟然是个假冒者......©豆瓣', '张智霖', '邓衍成', 7.7, 18430, 'tt14699076', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2559075183.jpg', 0.5, 2.6, 29.6, 46.7, 20.6, '0.178757,0.175592,-0.259417,0.406083,0.133599,-0.250258,0.384356,-0.163698,-0.578843,-0.511971,0.309790,0.665034,-0.364224,-0.089340,0.140688,0.062917,-0.088382,-0.607786,0.179645,-0.194987,0.099303,-0.307282,-0.001589,-0.123994,0.026737,-0.012674,0.527518,0.043017,-0.083437,0.850244,0.250927,0.136260,-0.429067,0.376141,0.051563,0.190246,-0.173665,0.167729,-0.131160,0.230187,-0.070753,-0.169409,-0.169903,0.162974,-0.182640,0.511151,0.056998,-0.372197,-0.259529,-0.174196,0.278356,-0.033291,-0.016583,0.031217,0.363523,-0.074237,0.149620,0.406927,-0.628420,-0.201781,0.018407,0.233056,-0.374236,0.126901,0.423705,0.088751,-0.283383,0.085583,-0.316458,-0.039661,-0.096553,-0.568283,0.252508,0.492197,0.412707,-0.242699,-0.133841,-0.257106,-0.455331,0.238567,0.178716,-0.071412,0.012024,-0.117732,0.554832,-0.329944,0.063251,-0.063732,0.252726,0.069185,0.459575,-0.019672,0.162389,0.230396,-0.272058,-0.233440,-0.234483,0.070240,0.104096,-0.278157,-0.061667,-0.280017,-0.246650,-0.292762,-0.211045,-0.034557,0.256567,-0.231638,0.222408,-0.527742,-0.021025,-0.150206,-0.156591,-0.755316,0.156479,-0.211537,-0.017862,-0.135024,-0.366290,0.164294,0.110948,0.201488,0.184586,0.137718,0.083621,-0.237380,-0.427592,-0.365383', '1304738', '1307186', '1296240', '25723081');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1968790', '福音战士新剧场版：序', '剧情', '突袭世界的大灾难“第二次冲击”后，世界在废墟之上重建。14岁的少年碇真嗣被父亲碇元渡叫到第3新东京市。本以为能见到父亲迎接的他，却见到名为“使徒”的巨大生物与军队交火。危急之下，特务机关NERV的葛成美里将真嗣救下，并将其带往碇元渡所统领的NERV总部。但迎接真嗣的，却是是父亲冷酷地命令：驾驶称为“EVA”的巨大人型机器人与使徒战斗。本已表示拒绝的真嗣，看到重伤的替补驾驶员绫波丽后，决定遵从父亲的命令。就这样，从未受过作战训练的真嗣，准备驾驶EVA初号机迎战使徒。世界的命运托付在了一位年仅14岁的少年身上，而“第二次冲击”所隐藏的“人类补完计划”似乎也开始了行动。掌握一切答案的碇元渡，却只是不动生色地观察，仿佛一切早已写入剧本。©豆瓣', '绪方惠美', '庵野秀明', 9.1, 70151, 'tt0923811', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2411110730.jpg', 0.2, 0.6, 6.6, 28.7, 63.9, '0.043176,0.146555,-0.721214,0.533716,-0.248914,-0.232338,0.590035,0.087450,-0.350461,-0.204278,0.571493,0.678615,-0.038514,0.073894,0.493800,-0.112201,-0.180727,-0.581834,-0.534094,0.079449,-0.468623,-0.401131,-0.182740,-0.208945,0.064176,-0.522054,1.126429,0.206177,-0.256533,0.133348,0.020566,0.310955,-0.114956,0.724983,-0.105808,-0.265994,-0.114166,-0.013815,-0.114376,0.215084,-0.262470,-0.327659,-0.081230,0.326678,-0.240303,0.404475,0.695601,-0.760323,-0.088384,-0.279401,0.139578,-0.223962,0.036428,0.121160,0.302689,0.002181,-0.088202,0.208367,0.208471,0.084862,-0.261875,-0.100310,-0.674290,-0.264233,-0.075299,0.039070,-0.478563,0.192969,-0.297508,0.255557,0.220266,-0.271576,0.147064,0.313258,0.259477,0.305652,-0.332506,0.185448,-0.307331,-0.143180,0.295110,-0.192575,-0.503700,0.246517,-0.109352,-0.486546,-0.310297,-0.245255,-0.246697,0.105767,-0.100660,0.501004,-0.104888,0.120599,-0.412661,-0.229410,-0.464453,-0.209409,-0.029889,-0.513374,-0.274076,-0.594473,0.074548,0.054080,-0.185449,0.259215,0.264445,-0.046248,0.510643,-0.858637,0.231670,0.218650,0.145932,-0.270980,0.311014,0.063383,-0.005898,-0.387785,0.131519,0.342923,0.010455,0.566005,0.008046,0.344431,0.022680,-0.117164,-0.410586,0.492172', '26759819', '26759820', '7051375', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1970437', '人狗奇缘', '剧情', '11岁的哥哥灿伊（俞承浩 饰）居然像个大人一样，无微不至的照顾着妹妹小伊（金香奇 饰）。兄妹俩人一直都相信，只要他们乖乖听话，总有一天，离家出走的妈妈会回到他们身边。小伊生日到了，为了满足她的心愿，哥哥送了一只刚刚出生小狗送给她，小伊认为这是妈妈送给她的礼物，所以取名为“心意”。有了“心意”的陪伴，灿伊不在家的时候，小伊有了玩伴。三个小家伙像一家人一样，快乐的生活着。转眼“心意”长大了，在一个阳光灿烂的冬日，“心意”拉着冰车，带着小伊在结冰的江上快乐的玩耍，不料发生意外，小伊掉进冰窟窿里面……灿伊把小伊意外的过错归咎在“心意”的身上，没有妈妈，没有小伊妹妹的灿伊，也不能接受“心意”再呆在自己身边，于是灿伊离家出去，开始了新的生活，而“心意”尾随其后，也开始了一段追觅之旅……©豆瓣', '俞承豪', '朴银炯', 8.4, 39336, 'tt1710565', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p547477150.jpg', 0.6, 1.7, 15.5, 41.7, 40.3, '0.024986,0.074545,-0.852205,0.411902,-0.405837,-0.340874,0.586306,0.261794,-0.239627,-0.024153,-0.117001,0.616886,0.177736,0.575628,0.100931,0.149527,-0.393534,-0.463316,-0.262398,-0.187138,-0.304365,-0.298597,0.209969,-0.042729,0.034597,-0.193789,0.215493,-0.210231,0.242591,0.622886,0.377244,-0.149643,-0.048028,0.347946,-0.469399,0.209214,-0.194534,0.399495,-0.228014,0.168334,0.070584,0.063338,0.145273,0.117839,0.404387,0.012759,0.872859,-0.480181,-0.211904,-0.133394,0.118234,-0.186106,0.358919,0.070583,-0.031523,0.087453,0.459499,-0.105032,-0.220081,0.172103,0.091101,-0.456977,-0.328048,0.008525,0.083946,0.103773,-0.760535,0.291939,-0.106037,-0.197488,0.239310,-0.670230,0.241377,0.444386,0.040839,0.464321,-0.539860,0.415791,-0.590078,-0.130968,0.716195,-0.270393,0.130529,0.619245,-0.103598,-0.084618,0.266880,-0.098593,-0.599981,0.050074,0.059359,0.147723,-0.375407,0.134309,-0.229596,-0.033350,0.121172,-0.061874,0.210963,-0.791448,-0.044093,0.190383,0.107198,-0.418313,-0.511702,0.123636,-0.155270,-0.272679,0.919696,-0.800323,0.557929,0.379267,0.481396,-0.488748,0.788586,0.216049,0.038899,-0.167199,0.536351,0.193214,0.035870,0.207921,0.484295,0.360193,-0.027037,0.067774,-0.583712,0.417467', '1291565', '1292219', '3077680', '2081098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1971111', '魔法奇缘', '喜剧', '女孩吉赛尔美丽的歌声飞遍森林，小动物们轻轻的和着，王子被深深地吸引。于是，王子和女孩一见倾心，正准备着他们盛大的婚礼。谁知，坏王后为了保住自己的权利，从中作梗，把吉赛尔送到了21世纪的纽约街头。吉赛尔（艾米•亚当斯 饰）无所适从的游走在喧嚣的纽约，没人知道她是真的公主，她害怕极了，找不到能够帮她的人。幸好，好心的律师罗伯特（帕特里克•德姆西 饰）收留了她。渐渐的，公主纯真的心打动了原本刻板的律师，机缘巧合，相遇的两个人互生情愫。而这时，爱德华王子（詹姆斯•麦斯登 饰）也不顾一切地，穿越时空，来到了纽约，营救他心爱的公主。公主真爱的天平，将倾向何处…©豆瓣', '艾米·亚当斯', '凯文·利玛', 7.2, 57889, 'tt0461770', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1293401256.jpg', 0.8, 5.2, 41.4, 37.7, 14.9, '0.383760,0.274310,-0.641396,0.706214,-0.231268,-0.300647,0.781602,0.286743,-0.397429,-0.061542,0.438634,0.660661,-0.242794,0.388117,0.397596,0.370484,-0.435532,-0.671649,-0.240578,-0.138307,-0.151497,-0.338119,-0.156888,-0.444510,-0.033351,-0.338687,0.488327,0.026814,0.066691,0.501958,0.308610,0.100621,-0.039543,0.606782,-0.421167,0.162955,0.002286,-0.073464,-0.129389,0.220039,0.272275,-0.147649,-0.194051,0.246381,-0.129721,0.306465,0.635654,-0.547687,0.310954,-0.156456,0.452331,-0.317242,0.352527,0.236558,0.043512,-0.273005,0.157550,-0.144333,-0.330422,-0.318314,0.493457,-0.018715,-0.341380,0.390027,-0.044104,0.149554,-0.711471,0.347167,-0.202407,-0.053952,0.408143,-0.426293,0.317879,0.180488,0.092541,0.230555,-0.011565,-0.017561,-0.595268,0.219965,0.818840,0.067295,0.025639,0.187966,-0.245888,-0.557461,0.021763,-0.242453,-0.703972,-0.069783,0.548471,-0.170288,-0.068332,0.219571,-0.511542,-0.239963,-0.420864,-0.050296,0.014108,-0.826924,-0.006248,-0.277136,-0.052856,-0.244292,0.054939,0.110306,0.110977,-0.094226,0.752122,-0.961298,0.221679,0.922240,0.274001,-0.379545,0.727132,-0.006930,-0.286141,-0.288953,-0.328831,0.251278,-0.231244,0.297983,0.257265,0.503601,-0.106943,0.037582,-0.452355,0.356490', '1309178', '3230462', '7065238', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1972698', '守望者', '动作', '由于邪恶势力肆意蔓延，一群具有超群实力的正义之士挺身而出，他们戴着面具，身着奇装异服，与各种坏蛋展开较量。不久，他们的英雄事迹通过媒体传遍全国，美元钞票、丝绸鬼魂、罗夏、城市队长等超级英雄的名字广为传播，他们更参与到大大小小的重大事件之中，也因各自的性格遭受着不同的命运。但是在20世纪70年代，政府出台的法令导致一部分不愿成为权贵爪牙的英雄退休，超级英雄集团由此分化。1985年的一天，效力政府的超级英雄“喜剧演员”爱德华·布莱克（杰弗里·迪恩·摩根 Jeffrey Dean Morgan 饰）被人杀害。四处逃亡的“罗夏”的沃尔特·科瓦奇（杰基·厄尔·哈利 Jackie Earle Haley 饰）意识到有人正向曾经的超级英雄痛下杀手，而这背后隐藏着更大的阴谋……©豆瓣', '帕特里克·威尔森', '扎克·施奈德', 8.6, 192832, 'tt0409459', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1663601927.jpg', 0.7, 2.3, 13.6, 35, 48.4, '0.197273,-0.075812,-0.374412,0.456461,-0.113685,0.170558,0.384989,0.121375,-0.709408,-0.413490,0.504148,0.799463,-0.269892,-0.017550,0.292366,-0.299835,-0.244305,-0.509442,0.004151,-0.265509,-0.035675,-0.323420,-0.409844,-0.236534,-0.157716,-0.315702,0.737523,0.118254,-0.312344,0.306657,0.316038,0.315747,-0.107226,0.209186,-0.094332,-0.281377,0.208060,-0.152825,-0.220067,0.169705,-0.300112,-0.213518,-0.022847,0.182969,-0.451688,0.103654,0.543013,-0.533041,0.252952,-0.358549,0.537310,-0.319031,-0.023984,-0.001185,0.720124,0.060603,0.183589,0.298594,0.290222,0.002960,0.048209,-0.079111,-0.766583,-0.107211,0.269242,0.346478,-0.411026,0.326570,-0.193154,-0.062720,0.044317,-0.081842,-0.005105,0.308794,0.335899,0.136752,-0.069021,-0.001984,-0.770751,0.133746,0.487587,0.025081,-0.295159,-0.213554,-0.274861,-0.430725,-0.246940,-0.560069,-0.517865,-0.221147,0.291948,-0.145454,-0.104825,0.622330,-0.892473,0.097891,-0.162089,-0.159895,0.110718,-0.101895,-0.179841,-0.785232,-0.244108,-0.314114,0.061557,0.243088,0.163741,-0.110407,0.955384,-0.723423,0.063440,0.488304,0.392290,-0.458417,0.581636,-0.219364,0.206981,-0.215813,-0.461519,0.314860,0.316154,0.143833,-0.062973,0.064905,-0.189924,-0.342815,0.153691,0.350925', '26290398', '27602116', '25863940', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1972701', '糊涂侦探', '喜剧', '冷战结束后，天控局面临被解散的危险，但是这个美国最大的特务机关，依旧担负着重要的使命。不过，近期天控局总部却遭受了突发性袭击，导致特工们都有被身份曝光的危险。其中也包括强壮如牛、身手不凡的23号特工（道恩•强森 Dwayne Johnson 饰）。总部经过研究发现，袭击事件是一个叫盖不达集团的，为了迎敌，总部对分析家麦克斯韦（史蒂夫•卡瑞尔 Steve Carell 饰）委以重任，后者终于等到了一展身手的机会。于是，他积极参与了对付盖不达的行动，不过之前的两次演习都被他搞砸了。唯一的收获是，他跟99号特工（安妮•海瑟薇 Anne Hathaway 饰）结成了搭档，后者是唯一不怕身份曝光的特工。他们在飞机上遇到了一个疑似的恐怖分子，但是当他们出手时，却意外陷入了对方的圈套。此后，这对欢喜冤家又接连遇到一系列令人啼笑皆非的困境……©豆瓣', '史蒂夫·卡瑞尔', '彼得·西格尔', 6.8, 42995, 'tt0425061', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2154983077.jpg', 0.9, 7.6, 49.3, 33.6, 8.7, '0.329027,-0.067507,-0.786292,0.459788,-0.015608,-0.022943,0.598820,-0.006886,-0.490573,-0.274550,0.486601,0.766294,-0.119291,-0.050451,0.286719,-0.133162,-0.192441,-0.699604,-0.010614,-0.164926,-0.445396,-0.333123,-0.373775,-0.172660,0.059479,-0.224865,0.494480,0.257552,-0.465500,0.412978,0.324939,0.488981,0.170886,0.646101,0.031303,-0.067952,0.351172,-0.150968,-0.070206,0.328780,0.067846,-0.315784,-0.052432,0.459598,0.081166,0.689960,0.454393,-0.274475,-0.409790,-0.129240,0.322714,-0.690103,-0.045195,0.072683,0.565486,0.110051,-0.005163,0.222915,-0.109189,-0.042293,0.141450,0.087827,-1.095005,0.143293,0.183469,0.015863,-0.472075,0.453707,-0.258400,-0.037384,-0.124768,-0.102105,0.418572,0.803327,0.443997,0.054548,-0.108907,0.304402,-0.656989,-0.172620,0.807049,-0.125318,-0.316817,0.098085,0.022184,-0.558578,-0.004663,-0.523273,0.033869,0.225736,0.375281,0.091201,-0.288980,0.027517,-0.496390,0.020434,-0.398461,-0.300900,-0.276420,-0.450519,-0.101045,-0.718864,-0.091591,-0.309991,-0.656570,0.335242,-0.004732,-0.139740,0.582819,-0.802427,0.107798,0.761109,0.224462,-0.734096,0.569430,0.241630,0.196712,-0.204849,-0.068632,0.047609,0.116051,0.440872,0.201528,0.303907,0.192533,-0.599302,-0.119181,0.058950', '26678784', '1793491', '1294941', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1972721', '浪漫鼠德佩罗', '剧情', '老鼠德佩罗（马修•布罗德里克 Matthew Broderick 配音）自幼体弱多病，却拥有两只硕大无比的耳朵。童年在图书馆度过，慢慢的开始学会了认字，学会了阅读，他喜欢童话故事中那些英雄救美的故事，常常幻想自己也能成为一个英勇的骑士，在美人落难时拔刀相助。一次外出中，德佩罗认识了豌豆公主（艾玛•沃特森 Emma Watson 配音）。渴望成为英雄的德佩罗，因为触犯了鼠国严苛的律条被父亲勒斯特（威廉姆•H•麦西 William H. Macy 配音）驱逐。在多尔王国外的广袤土地上，德佩罗认识了同样被自己国家驱逐的老鼠罗斯库洛（达斯汀•霍夫曼 Dustin Hoffman 配音）。不久之后，流放的德佩罗得知豌豆公主被关入地牢，对公主心怀爱恋的德佩罗决定决一死战救出公主，会战胜邪恶赢得自己该有的爱和尊严吗？本片是根据美国著名儿童文学家凯特•迪卡米罗的同名小说改编。', '马修·布罗德里克', '山姆·菲尔', 6.7, 12376, 'tt0420238', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2624049143.jpg', 1.2, 8.9, 50.4, 30.5, 8.9, '0.189754,0.203031,-0.413345,0.707906,0.122633,-0.185747,0.679831,-0.053543,-0.370614,-0.154023,0.204638,0.810146,-0.144040,0.154849,0.310257,0.248963,-0.291960,-0.504249,-0.059123,-0.262918,-0.188349,-0.429766,-0.231824,-0.336657,-0.211654,-0.601194,0.661588,0.003343,-0.194223,0.355152,0.254772,0.191983,0.130722,0.161751,-0.090569,0.163543,0.198953,-0.202238,-0.063142,0.268591,-0.095782,0.074637,-0.038978,0.058365,-0.000372,0.054443,0.535573,-0.572902,0.128956,-0.250252,0.488279,-0.269895,0.017564,0.222054,0.184034,-0.155677,0.274822,0.042734,0.036876,-0.043583,0.077516,-0.276892,-0.572830,-0.304775,-0.145889,0.264639,-0.684155,0.192460,-0.152020,0.005420,0.367495,-0.199415,0.072537,0.065645,0.258547,0.336205,0.130217,0.103128,-0.466631,0.296247,0.567828,-0.327716,-0.236905,0.030106,-0.205292,-0.448216,0.238259,-0.475035,-0.483631,-0.076274,0.426368,-0.192154,-0.206319,0.436366,-0.395647,-0.155733,-0.417373,-0.161183,0.184441,-0.495878,-0.032903,-0.355049,-0.181749,-0.276830,-0.110368,-0.098483,0.136759,-0.489879,0.827144,-1.020041,0.438765,0.577005,0.082674,-0.305491,0.536092,0.223241,0.041999,-0.060018,0.144114,0.561879,0.268645,0.108018,0.109758,0.336952,0.241762,-0.107386,-0.445978,0.673158', '26593587', '1870681', '1292720', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1972729', '铁甲钢拳', '剧情', '2020年，未来一个并不遥远的年份，整个世界已经发生了许多变化。在那个时代，人类拳击不再被允许，取而代之的是各种机器人走上了擂台，继续这项火爆的运动，愉悦大众。前拳击手查理·肯顿（休·杰克曼 Hugh Jackman 饰）似乎并不那么落寞，他很快适应了时代的发展，带着经过训练的机器人一次次走上拳台。但是倒霉事接二连三，他先是意外落败，债台高筑，继而接到前女友突然过世的消息，并见到了从未谋过面的儿子——11岁男孩麦克斯（达科塔·高尤 Dakota Goyo 饰）。一次意外，让麦克斯遇到了一台业已被淘汰的陪练机器人Atom。在麦克斯的坚持下，查理同意让Atom参加比赛，却意外发现这台“废物”不仅抗打，而且拥有搏斗的潜质与天赋。肯顿父子和他们的机器人由此踏上新的征途……©豆瓣', '休·杰克曼', '肖恩·利维', 8.3, 258550, 'tt0433035', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1031075041.jpg', 0.3, 1.4, 16.8, 48, 33.5, '0.263385,0.220435,-0.678593,0.445260,-0.174055,-0.334708,0.627635,-0.104917,-0.534137,-0.366383,0.076099,0.802307,-0.393419,0.046525,0.157206,-0.327453,-0.127591,-0.458667,-0.010452,-0.041166,-0.480438,-0.459834,-0.271800,-0.337548,-0.033263,-0.434343,0.729173,0.051929,-0.267748,0.794967,0.162066,0.125378,0.259122,0.610480,-0.281833,-0.002170,0.388155,0.134304,-0.043759,0.193149,-0.044969,-0.249203,-0.022671,0.141759,-0.202285,0.395157,0.553769,-0.229079,-0.407066,-0.140258,0.389657,-0.056099,-0.141295,-0.038194,0.366668,-0.049968,-0.175301,0.194042,0.095829,0.063388,0.051613,-0.129309,-0.528070,0.188582,-0.041512,0.135967,-0.545719,0.454959,-0.198912,0.085734,-0.103542,-0.116217,0.152461,0.385877,0.437845,0.440483,-0.218793,0.155707,-0.391469,0.126385,0.611990,0.086615,-0.633254,0.517235,-0.122323,-0.613121,-0.196003,-0.332427,-0.456670,0.203626,0.365482,0.163661,-0.086474,0.275784,-0.472851,0.090592,-0.253862,-0.161785,-0.159434,-0.287033,-0.071170,-0.628539,0.100464,-0.338736,-0.385342,0.127188,-0.144576,-0.326931,0.463184,-0.720302,0.378180,0.248309,0.242308,-0.411507,0.507497,-0.150067,0.008912,-0.317664,-0.075442,0.280332,-0.062418,0.165316,0.130693,0.417233,0.006413,-0.335065,-0.212600,0.662668', '35030151', '35144311', '6803494', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1972732', '嗜血破晓', '剧情', '曾经由人类主宰的社会如今变成了吸血鬼的天下，而仅存的人类被圈养起来成为制造新鲜血液的机器。人类的数量越来越少，吸血鬼必须研究出血液的替代品，否则将面临更加恐怖的变异。爱德华·道尔顿（伊桑·霍克 饰）是专门研究新型替代品的首席血液专家，他的老板查尔斯·布罗姆利是一位野心家，他非常满意当前吸血鬼世界的现状并企图通过垄断新的替代品获得巨额利润。一次意外爱德华遇到了逃亡中的人类奥德丽·班尼特（克劳蒂娅·卡万 饰），并帮助她摆脱追捕，不料事后奥德丽居然找上门来，并且带来了在一次意外中由吸血鬼奇迹般变成人类的艾维斯，仅存的人类需要一个可以信任的吸血鬼的帮助……斯派瑞格兄弟（Peter Spierig & Michael Spierig）在此片中将以往的吸血鬼类型片进行改造，融入科幻的元素打造出全新的故事氛围。©豆瓣', '伊桑·霍克', '迈克尔·斯派瑞', 6.9, 38244, 'tt0433362', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1174429818.jpg', 0.8, 6.1, 48.4, 36, 8.8, '0.211766,0.240957,-0.196768,0.542930,-0.294535,-0.164440,0.677883,-0.115269,-0.542052,-0.359457,0.169692,0.627067,0.121158,-0.084471,0.318095,-0.069251,-0.253603,-0.244868,0.073366,-0.153427,-0.324979,-0.461881,-0.655094,-0.468600,0.031940,-0.812661,0.826457,-0.034721,-0.406660,0.100789,0.195639,0.612189,0.069755,0.217207,-0.124079,-0.263014,0.285674,-0.242296,-0.357179,0.400055,-0.162648,0.089827,0.209553,0.247096,-0.299154,0.070315,0.646777,-0.697016,0.120301,-0.606811,0.556314,-0.289275,0.090113,0.014391,0.283811,0.169246,0.006825,0.080286,0.055720,0.023882,0.263341,-0.130993,-1.229706,-0.119142,0.113936,0.233583,-0.431969,0.179746,0.172019,0.015775,0.088478,-0.171753,-0.032445,0.255814,0.638623,0.310311,-0.120991,-0.059363,-0.545856,0.084092,0.496113,-0.153568,-0.788428,0.419134,-0.510813,-0.610812,-0.176002,-0.453874,-0.355683,-0.004639,0.285497,0.199441,-0.141275,0.588255,-0.955246,-0.081537,-0.490911,-0.325195,0.147763,-0.140513,-0.056168,-0.761195,-0.216341,0.072403,-0.116989,-0.111353,0.201477,-0.522189,0.799076,-0.763558,0.092055,0.561580,0.294206,-0.420071,0.287965,-0.186725,0.097785,-0.352740,-0.261402,0.333948,0.326756,0.242427,0.031592,0.237683,0.066140,-0.053537,-0.210551,0.574264', '26667010', '6844861', '1793491', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1972775', '向日葵', '剧情', '泰植（金来沅 饰）自高校退学，变成为了黑社会的小头目。每次喝完酒打起架来的毫不保留，激烈时甚至越战越勇，于是大家都给他取了一个叫“疯狗”的绰号。但泰植后来还是锒铛入狱了，被假释出来的他仿佛变了另一个人似的。对仇人也熟视无睹的态度令众人十分疑惑。他终日拿着一本手册，原来里面记录了他生活中要做的平常事。这是他在监狱里便记录的手册，他要对自己约法三章，要令自己变好。手册是德子给他的，他特意找到了这位老人。德子对待泰植犹如自己的亲生儿。但德子的女儿熙洙却总对泰植恶言相向，实际上她并不讨厌泰植。他们三个人正要开始他们的新生活，但谁都不相信，泰植愿意改过自身。©豆瓣', '金来沅', '姜锡范', 7.9, 23645, 'tt0923714', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p497587514.jpg', 0.5, 2.5, 24.2, 46.5, 26.1, '0.292836,0.058005,-0.704563,0.632620,-0.467641,-0.261436,0.795059,-0.078150,-0.493145,0.034014,0.146915,0.824168,-0.120555,0.213706,-0.098169,0.309869,-0.359646,-0.654905,-0.180515,-0.228837,-0.290308,-0.138854,-0.237852,-0.296760,-0.175505,0.107911,0.040370,-0.200690,-0.196827,0.142711,0.406464,0.056046,0.386932,0.746787,-0.323856,0.259454,-0.245200,0.084109,0.187110,-0.007054,0.239398,-0.235768,-0.408851,0.486390,0.063069,0.645173,0.399033,-0.121360,-0.360533,-0.190485,0.189262,-0.334440,-0.164416,0.288189,0.159133,-0.016237,0.229300,0.254095,-0.080684,0.138802,-0.002557,-0.050860,-0.735993,0.025429,0.035602,0.208118,-0.651280,0.470909,-0.210736,0.079018,0.015165,-0.173102,0.059755,0.023652,0.203980,0.308520,-0.237532,-0.221098,-0.633089,0.380120,0.621809,-0.010178,-0.256102,0.342532,-0.232976,-0.398298,0.042187,-0.150881,-0.396175,-0.084037,0.226000,0.040840,-0.308663,-0.038520,-0.538350,-0.013314,-0.003627,-0.088252,-0.118544,-0.556256,-0.146717,-0.091521,0.042486,-0.564152,-0.439202,0.111239,0.040323,-0.257851,0.796451,-0.605082,-0.004513,0.340244,0.132342,-0.577853,0.461022,0.377830,-0.074551,-0.179492,-0.061603,-0.268399,0.209018,0.530736,0.373427,0.426414,0.257125,-0.099696,-0.237312,0.559891', '30162520', '1481233', '1306801', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1978369', '我的机器人女友', '喜剧', '生日没有任何人祝福，这样过着寂寞生活的大学生次郎（小出惠介饰）在20岁生日那天突然遇到了生命中的那个“她”（绫瀨遥饰）。二人共渡了一个美好的夜晚。是夜，“她”从次郎的眼前消失了。一年后的生日，本以为还将回归寂寞生活的次郎再次遇到了“她”。这一次，“她”讲出了惊天的故事：“我是未来次郎你创造的机器人，回到过去来保护你免受灾难。”就这样，“她”住进了次郎家中，开始了与次郎的同居生活。灾难似乎没有离开次郎的意思，但次郎与她的感情已在其中萌发。爱与时间的感人故事，守护未来的约定，开始今天的生活。©豆瓣', '绫濑遥', '郭在容', 7.5, 160915, 'tt0929860', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p637412789.jpg', 0.6, 3.9, 32.9, 43, 19.5, '0.133894,0.007636,-0.755706,0.451876,-0.223415,-0.380197,0.977041,-0.099591,-0.242735,-0.412763,0.108543,0.652923,-0.020521,0.638810,0.544861,0.145137,-0.394125,-0.722941,0.135862,-0.134482,-0.054334,-0.307619,0.078970,-0.147645,0.000607,-0.101595,0.814589,0.343376,-0.024847,0.482193,-0.159115,0.049305,0.153802,0.480815,-0.441153,0.380735,0.102295,0.432207,-0.264617,0.333544,0.057019,-0.178674,-0.215369,0.409943,-0.005639,0.414459,0.578840,-0.436323,-0.530495,-0.049709,0.507348,-0.336290,-0.113210,0.284123,0.104090,0.095501,0.157772,0.316560,-0.193029,-0.091022,-0.167843,-0.289895,-0.700802,0.059385,-0.317653,-0.013219,-0.398185,0.447537,-0.222780,-0.295203,0.405560,-0.285912,0.355726,0.759093,0.528361,0.272502,-0.619177,0.296697,-0.387974,0.380784,1.322933,-0.231979,-0.150001,0.640178,-0.080718,-0.353942,-0.409057,-0.071680,-0.637633,0.043502,-0.047492,0.028453,-0.495507,0.424400,-0.510323,0.052490,-0.101422,-0.088774,0.472349,-0.326072,-0.303422,-0.160384,-0.195394,-0.513063,-0.833541,0.128164,-0.085995,-0.320810,0.829113,-0.991357,0.178901,0.535528,0.591855,-0.282070,0.762508,0.383315,-0.216324,-0.045125,0.464361,0.432564,-0.080735,0.625994,0.151446,0.508822,0.333059,0.396060,-0.599505,0.640489', '25721544', '4728584', '1870682', '25858759');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1978709', '黑天鹅', '剧情', '纽约剧团要重排《天鹅湖》，因前领舞Beth（薇诺娜•赖德 Winona Ryder 饰）离去，总监Thomas（文森特•卡索尔 Vincent Cassel. 饰）决定海选新领舞，且要求领舞要分饰黑天鹅与白天鹅。Nina（娜塔莉•波特曼Natalie Portman 饰）自幼练习芭蕾舞，在母亲的细心关照下，技艺出众。这次，她希望可以脱颖而出。然而，在竞争中，她发现心机颇重的Lily（米拉•库妮丝 Mila Kunis 饰）是自己的强劲对手。在选拔中，她的白天鹅表演的无可挑剔，但是黑天鹅不及Lily。她感到身心俱疲，回家还发现了背部的红斑与脚伤。她一个人找到总监，希望争取一下。总监趁机亲吻她，却被她强硬拒绝。结果，总监居然选了她。队友怀疑她靠色相上位。在酒会上，Beth甚至当众发泄。这种压力外加伤病，一直影响着她的发挥。总监启发她要释放激情，表现出黑天鹅的诱惑。在强大的心理暗示中，她似乎也滑向了黑天鹅的角色……', '娜塔莉·波特曼', '达伦·阿伦诺夫斯基', 8.6, 745683, 'tt0947798', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2549648344.jpg', 0.2, 0.8, 11.5, 45.2, 42.3, '0.130128,0.174985,-0.659342,0.636672,-0.203285,-0.206843,0.549052,0.258942,-0.302484,-0.115150,0.542195,0.602937,-0.277485,0.091348,0.290261,0.090788,-0.209163,-0.610047,0.114546,0.233884,-0.053965,-0.361268,-0.359250,0.032909,-0.037043,-0.429265,0.541102,-0.128867,-0.453818,0.436332,0.286530,-0.080996,0.227082,0.368849,-0.009181,-0.052659,0.118195,-0.068920,-0.019943,0.303079,0.302076,-0.392763,-0.285113,0.321872,0.115362,0.338897,0.497614,-0.097475,0.017554,0.095452,0.422067,-0.112002,0.318501,0.215906,0.014954,0.088253,0.329876,0.040693,-0.113985,0.253309,0.136447,-0.030933,-0.772044,0.011774,0.182608,0.160248,-0.607044,0.469893,-0.224041,0.122433,0.065428,-0.208271,-0.095470,0.045066,0.088151,0.177211,-0.279264,0.100060,-0.351232,0.195614,0.440371,0.018054,-0.398279,0.192819,-0.331949,-0.410957,0.070326,-0.416993,-0.245668,-0.123536,0.233383,0.230488,-0.083587,-0.109113,-0.342195,-0.041534,-0.289677,0.023781,-0.384742,-0.474193,0.205275,-0.584438,-0.292090,-0.245604,-0.399084,-0.265763,0.041879,-0.482964,0.456473,-0.921341,0.151043,0.833119,0.449349,-0.195856,0.550884,0.152765,-0.086406,-0.020258,-0.354118,0.096173,-0.304821,-0.022991,0.048243,0.512454,-0.042450,-0.299539,-0.436129,0.424759', '1793491', '1986338', '35144311', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1979067', '裂口女', '恐怖', '20世纪70年代，在日本中小学生中间流传着这样一个恐怖的传说：放学独自走到公园附近时，会遇到一个带着白色口罩、穿红色风衣的女人。遇到路过者，她会摘下口罩，露出裂到耳朵的恐怖大嘴，问对方“我漂亮吗？”如回答不漂亮，她会将对方毁容；若回答漂亮，她就将对方变得和自己一样；如果逃跑，她会以极快的速度追上。这个女人的名字就叫：裂口女。各学校一时间人心惶惶，男女学生们都怕碰到这个可怕的女人，而大人们却对这个谣言嗤之以鼻。但随着一场不详的地震发生，裂口女终于到来……©豆瓣', '佐藤江梨子', '白石晃士', 5.3, 6656, 'tt0891520', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1048247923.jpg', 9.6, 32.2, 45.6, 8.8, 3.7, '0.472754,0.150032,-0.572406,0.416459,-0.209341,0.320869,0.965440,-0.036743,-0.155827,-0.174326,0.355553,0.777668,-0.653920,0.224121,0.010700,0.205835,-0.104315,-0.543190,0.035663,-0.150603,-0.698886,0.075364,-0.186958,-0.155452,-0.027713,-0.169463,0.130479,0.098470,-0.331515,0.367875,0.420761,-0.008598,-0.073393,0.592458,-0.570937,-0.309247,-0.323675,0.161811,0.526920,0.187634,-0.044014,-0.134323,-0.119575,0.151322,-0.410620,0.214322,0.509742,-0.065017,-0.242809,0.036606,0.455204,-0.395956,-0.109845,0.323643,0.376050,-0.219615,0.243598,-0.181935,0.161519,0.084300,0.141000,-0.052232,-0.241468,0.492399,-0.185172,0.341166,-0.464279,-0.043395,-0.004919,-0.232199,0.346547,-0.407804,0.179260,0.101813,0.228796,0.264550,-0.091846,0.110294,-0.786075,0.081344,0.560997,-0.047877,-0.544744,0.133223,-0.122273,-0.290308,-0.045285,-0.046583,-0.591949,0.172560,0.335521,-0.073119,-0.432636,-0.015125,-0.377300,0.060158,-0.116675,-0.115836,-0.148561,-0.112878,-0.623382,-0.208981,0.020162,-0.452831,-0.405643,0.527999,-0.055551,-0.090895,0.763582,-0.624606,0.029101,0.448171,0.371420,-0.486512,0.582208,-0.056244,-0.160631,0.028930,-0.269183,0.168905,0.042563,0.221360,-0.106279,0.704858,-0.105044,-0.165182,-0.108393,0.471996', '1783772', '1296534', '26648284', '1296500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1979068', '灵异咒', '恐怖', '某日，东京一处房屋失火，房屋主人小林雅文（村木仁 饰）生不见人，死不见尸。小林是一名怪奇作家，他经常到传言闹鬼的地方体验采访，著书立作，同时还是一名电台灵异节目的主持人。他的失踪引起人们广泛猜测，而其留下的DV素材则称为寻找其下落的关键所在。录像带中，小林曾拜访过一位家庭主妇，主妇声称在隔壁经常能够听到婴儿的哭声，而那户人家根本没有小孩。在采访结束后不久，主妇遭遇车祸身亡。小林坚信这起事故背后另有隐情，他由此展开更为深入的调查。然而调查越深入，离奇诡异的事件越来越多，而恐怖的真相也渐渐浮出水面……©豆瓣', '村木仁', '白石晃士', 7.2, 11994, 'tt0930083', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2547316981.jpg', 2.1, 7.8, 34.8, 39.2, 16, '0.155306,-0.349441,-0.677488,0.166211,0.036213,0.067982,0.808157,0.015586,-0.691447,-0.516577,0.267985,0.524749,-0.444259,0.266334,0.146534,-0.174634,-0.298838,-0.317739,0.170166,-0.165322,-0.222129,-0.243716,-0.157963,-0.433452,-0.105535,-0.086980,0.456632,0.374779,-0.408748,0.282707,0.122029,0.374629,-0.523032,0.367927,-0.065435,0.017341,0.245180,0.342689,-0.137384,0.281381,-0.056426,-0.410091,-0.290832,-0.074323,-0.280444,0.347886,0.445340,-0.129356,-0.475827,-0.067463,0.645636,-0.146294,-0.003655,0.064993,0.772267,0.183095,0.395260,0.253570,-0.391988,-0.121248,-0.205025,0.048219,-0.373892,0.215103,0.095696,0.551214,-0.059708,-0.225760,0.019250,-0.071482,0.134452,-0.416881,0.370274,0.236942,0.036081,0.111202,-0.243259,0.054946,-0.331198,0.291237,0.689624,-0.074565,-0.050477,0.252318,0.163959,-0.425741,0.121999,-0.140201,-0.205060,0.323149,0.280729,0.157884,-0.364866,0.310179,-0.168513,-0.124855,-0.222769,-0.185062,-0.142806,0.242133,-0.340969,-0.871737,-0.225740,0.030047,-0.090688,-0.176687,-0.084461,-0.254864,0.618059,-0.734849,0.377209,0.472201,-0.051266,-0.460279,0.255588,-0.011397,0.061519,-0.144060,-0.055149,0.154858,0.145134,0.338246,-0.160099,0.158129,0.055073,-0.702789,-0.334658,0.136222', '10466639', '26718836', '2369613', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1979076', '不要嘲笑我们的性', '喜剧', '美术学校的大学生矶贝米路美（松山健一 饰）被新来的版画老师猪熊百合（永作博美 饰）吸引。他很快跟百合发生了关系，并且因为百合的成熟的魅力和不羁的性格而爱上了她。小远（苍井优 饰）是米路美的好朋友，并且一直暗恋米路美，她知道了米路美和百合的不伦恋而大受刺激。单纯的米路美在去拜访百合家时，得知了百合竟然已经结婚，而且丈夫是个邋遢的糟老头。被现实所冲击的米路美决定跟百合断绝关系，但是他根本忘不了百合，只能躲在家里独自挣扎。看不过去的小远决定帮助米路美和百合。但是天不遂人愿，成年人的世界岂又是这群初出茅庐的年轻孩子们所能揣度的，百合就这样突然消失在所有人的生活中，就像她的突然出现一样。©豆瓣', '永作博美', '井口奈己', 6.7, 13053, 'tt0945550', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p634165568.jpg', 1.6, 9.7, 49.3, 29.5, 9.9, '0.355837,0.000665,-0.650623,0.432536,-0.397054,-0.410024,0.550593,0.293482,-0.177237,-0.148906,-0.078637,0.521614,-0.073168,0.270805,0.226030,0.234834,-0.106613,-0.684897,0.023454,-0.212168,-0.142256,-0.293907,-0.100549,-0.019429,-0.047126,-0.273755,0.371226,0.040251,0.043749,0.594588,0.333930,-0.026806,0.006847,0.370884,-0.223150,0.075160,0.142399,0.156609,-0.156932,0.077872,-0.177611,-0.003461,0.051854,0.196246,-0.011518,0.269003,0.543566,-0.397763,-0.375910,-0.063334,0.335616,-0.342536,-0.077304,0.288387,0.383852,-0.305397,0.291549,-0.247919,-0.194416,-0.060850,0.197330,0.001909,-0.379787,0.288292,0.216877,0.109569,-0.500232,0.409552,0.135306,-0.226343,0.376949,-0.192709,0.020405,-0.048777,0.335810,0.328147,-0.209091,0.112745,-0.635235,0.081643,0.735887,0.375951,-0.324866,0.503475,-0.243177,-0.270736,-0.230813,-0.144998,-0.529216,0.142061,0.147812,-0.222589,-0.396214,0.066021,-0.564892,0.097647,-0.199516,0.186109,-0.126444,-0.534390,-0.247377,-0.220703,-0.065032,-0.640115,-0.392681,0.240364,0.064904,-0.239158,1.036333,-0.781470,0.223163,0.668732,0.420813,-0.747002,0.821916,0.367573,-0.293629,0.117175,-0.061828,0.297375,-0.219349,0.238865,0.099312,0.619823,-0.133856,-0.173451,-0.628991,0.296007', '6963575', '5262027', '1296770', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1980825', '永远的三丁目的夕阳2', '剧情', '20世纪50年代末，日本申奥成功，从东京到全国各地都沉浸在一片自豪与喜悦之中。而我们所熟悉的东京夕阳町三丁目，平淡却不乏温情的百姓故事仍在继续着。铃木车行迎来了亲戚家的孩子，美丽女孩美加（彩梦 饰）。这位养尊处优的大小姐自然无法适应夕阳町的庶民生活，令则文（堤真一 饰）、六子（堀北真希 饰）颇为挠头。另一边厢，茶川龙之介（吉冈秀隆 饰）与淳之介（须贺健太 饰）相守，但始终思念离开的广美（小雪 饰）。淳之介生父的到来让茶川甚感郁闷，为了证明自己拥有抚养淳之介的能力，他重整旗鼓，决定向再次芥川奖发起冲击。夕阳町的平常人们如同一家人，相互争吵、牵绊、鼓舞、扶持，迎来了最为辉煌的时代……本片荣获2008年日本电影学院奖最佳男主角奖（吉冈秀隆）。©豆瓣', '吉冈秀隆', '山崎贵', 8.7, 17038, 'tt0953981', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1011704039.jpg', 0.2, 0.6, 10.6, 40.9, 47.7, '-0.121896,0.082907,-0.531419,0.366402,0.267259,-0.249324,0.540546,0.283760,-0.251553,-0.194621,0.237001,0.514001,-0.104523,0.233635,0.402744,-0.002862,-0.393224,-0.467953,0.020221,-0.113485,0.232096,-0.121528,-0.065404,-0.121507,-0.195958,-0.374791,0.665227,0.304387,0.009074,0.402750,0.291566,0.204801,-0.351096,0.228210,-0.040739,-0.021303,0.025385,0.132161,-0.488102,0.176046,-0.460408,-0.326365,-0.380518,0.072027,0.071866,0.030661,0.768827,-0.317142,-0.189634,-0.055694,0.297329,-0.167934,-0.326405,0.243728,0.222641,0.012706,0.069252,0.034327,-0.142424,-0.190739,-0.050470,-0.166059,-0.463042,0.184478,0.210179,0.161437,-0.204603,0.351091,0.065918,-0.184073,0.142054,-0.289101,-0.014685,0.098831,0.197049,0.294188,-0.382199,0.326285,-0.236982,0.351349,0.629256,0.105446,-0.149809,0.307907,-0.407494,-0.428422,-0.039233,-0.124985,-0.624683,-0.099789,0.131262,0.053373,0.030343,0.166434,-0.413040,0.008984,-0.045216,-0.193969,0.258722,-0.273030,0.131142,-0.586554,0.093597,-0.504192,-0.329838,0.104040,0.404442,-0.158572,0.850858,-0.675075,0.054004,0.371182,0.245060,-0.002552,0.370815,0.105120,-0.131439,-0.146830,-0.327637,0.401035,-0.204038,0.149828,0.147483,0.244417,-0.426225,-0.036516,-0.312061,0.347335', '3811356', '25922902', '5403927', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1981242', '午夜巴塞罗那', '剧情', '故事发生在美丽的巴塞罗那，美国女孩维姬（丽贝卡·豪尔 Rebecca Hall 饰）和克里斯蒂娜（斯嘉丽·约翰逊 Scarlett Johansson 饰）在度假时认识了名声并不太好的艺术家胡安（哈维尔·巴登 Javier Bardem 饰）。性格迥异的两姐妹在第二次遇到胡安后，对于胡安结伴去奥维耶多过周末的的邀请，热情奔放的克里斯蒂娜一下子就爽快答应了，而即将结婚的维姬却感到深深的不安。奥维耶多发生了让人意想不到的事情，原本应该和胡安一夜春宵的克里斯蒂娜因病躺在床上休息，而理智现实的维姬却和胡安一夜风流。当三个人再次回到巴塞罗那之后，维姬的未婚夫道格前来陪伴她，维姬的生活似乎归于平静。而当克里斯蒂娜开始了与胡安热恋并同居的生活之时，胡安的前妻玛丽娅（佩内洛普·克鲁兹 Penélope Cruz 饰）突然出现，这三人之间构筑起一种奇特的关系。于是在盛夏的充满浪漫气息的欧洲名城，一段诙谐而又深刻的关于爱的故事拉开了序幕。在2009年第81届奥斯卡上，佩内洛普·克鲁兹凭借此片获得最佳女配角奖。', '丽贝卡·豪尔', '伍迪·艾伦', 7.8, 222250, 'tt0497465', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453871779.jpg', 0.4, 2.1, 26, 49.3, 22.2, '0.451288,0.027732,-0.848498,0.499841,-0.037067,-0.484211,0.928408,0.222392,-0.508217,-0.310543,0.012373,0.888991,-0.418821,0.385921,0.638054,-0.036032,-0.402660,-0.763494,-0.034724,-0.161490,-0.104436,-0.594809,-0.025633,-0.055416,0.044888,-0.456734,0.474614,-0.134058,-0.092193,0.678673,0.341020,0.390750,-0.000884,0.580602,-0.074684,0.054277,0.108098,0.207807,-0.416872,0.181860,0.127057,-0.132492,-0.271458,0.082512,0.093638,0.188812,0.603067,-0.389976,-0.116747,0.237462,0.418044,0.130036,-0.054467,0.108331,0.153172,-0.124473,0.139071,0.190845,-0.137268,0.049707,0.137743,-0.161460,-0.382905,0.412240,-0.045810,0.263547,-0.452744,0.697472,-0.087638,-0.056690,0.128885,-0.339288,0.184351,0.532115,0.195872,0.480335,-0.052225,0.006449,-0.246842,-0.045455,0.715098,0.252162,-0.268274,0.591698,-0.246568,-0.405448,-0.154906,0.084080,-0.376410,-0.005785,0.380617,0.039081,-0.012940,0.514544,-0.796475,0.099265,-0.224739,-0.162852,-0.078191,-0.328206,0.056969,-0.589605,-0.247655,-0.356420,-0.263717,0.158949,0.104454,-0.116275,0.518043,-0.800833,0.453342,0.392156,0.154874,-0.222188,0.464340,0.188400,0.106911,-0.222903,-0.111522,0.514147,-0.115486,0.026466,-0.004406,0.482036,-0.157118,-0.030667,-0.489928,0.551817', '1296534', '1309172', '3111650', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1981335', '巴黎两日情', '剧情', '玛丽安（朱莉•黛比 饰）是来自法国的摄影师，她的男朋友杰克（亚当•戈登堡 饰）是美国的室内设计师，两人在纽约生活了两年，感情逐渐趋于平淡。为了找回失落的激情，两人放下一切去欧洲度假。在享受了完美的旅行，二人感情重新苏醒之后，玛丽安决定转到巴黎看望父母，顺便领回自己的小猫，对巴黎颇有幻想的杰克欣然同意。然而，种种匪夷所思的事情随之而来：玛丽安的父母作风大胆，话题百无禁忌；玛丽安的前男友们纷纷出现，一个比一个疯狂……短短两天，杰克对天堂巴黎的幻想破灭，他的美国基因无法接受这一切。最终，玛丽安和杰克不得不坐下来谈谈未来，这次谈话也许是一个艰难的开始，或者仅仅是一个无奈的结束。©豆瓣', '亚当·戈德堡', '朱莉·德尔佩', 7.2, 6455, 'tt0841044', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2370862730.jpg', 0.7, 5.6, 39.8, 39.1, 14.7, '0.443325,0.107483,-0.708997,0.597715,-0.179965,-0.344112,0.708584,0.000608,-0.581332,-0.500070,0.086840,0.861987,-0.252460,0.487885,0.290942,0.079331,-0.518993,-0.675641,0.050811,-0.011328,-0.132120,-0.611691,-0.150242,-0.281808,-0.134227,-0.144583,0.352937,-0.075664,0.067384,0.633128,0.231757,0.350438,-0.020816,0.473827,-0.313028,-0.014659,0.153854,0.094732,-0.600903,0.227492,0.262253,-0.065395,-0.100277,0.378755,-0.053668,0.190156,0.695841,0.138228,-0.209124,0.221214,0.468642,-0.234759,-0.209061,0.298103,0.277353,0.010284,-0.083990,0.058572,-0.309630,-0.094786,0.045007,-0.059320,-0.727634,0.100663,-0.215369,0.082490,-0.532224,0.396108,-0.007058,-0.091634,0.210278,-0.317431,0.047438,0.462550,0.282076,0.386407,-0.061302,0.093349,-0.122965,0.236021,0.962248,0.004977,-0.357937,0.558788,-0.154468,-0.245382,0.032083,0.006273,-0.438959,-0.040612,0.170597,0.088900,-0.112239,0.232051,-0.763030,-0.135397,-0.323066,-0.493938,0.115651,-0.508624,0.043912,-0.654327,-0.370025,-0.555430,-0.273418,-0.169414,0.030948,-0.182876,0.672810,-0.864142,0.134418,0.528276,0.100236,-0.504115,0.436010,0.047554,0.079653,-0.484262,0.249873,0.379106,-0.273368,0.094681,0.112298,0.315014,0.196811,0.173712,-0.586103,0.514104', '11541282', '1292219', '25721544', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1981642', '亚瑟和他的迷你王国2', '动画', '迷你墨王国的朋友们为欢迎亚瑟再次造访做着各种各样的准备，塞林娜公主也日夜期盼着他的到来，整个迷你墨王国洋溢着一片忙碌祥和的气氛。亚瑟（弗莱迪·海默 Freddie Highmore 饰）自从上一次的奇妙冒险之后，便一直期望能再回到那个神奇的地方，希望能再次见到美丽的塞林娜公主和迷你墨王国更多的惊喜。可是爸爸却被蜜蜂惹恼了，他打算带着妈妈和亚瑟离开这个地方。亚瑟临出发前忽然收到一只蜘蛛送来的写着“救命”的米粒，似乎迷你墨王国又处于危险之中，看来亚瑟又要开始一段神奇的冒险之旅……本片是吕克·贝松的第十一部影片，全片采用真人与3D动画相结合的方式，其3D部份由曾成功制作《哈利波特》的BUF公司负责制作。目前该片已经通过中国电影局审查，并定于2月16号登陆中国院线。©豆瓣', '弗莱迪·海默', '吕克·贝松', 6.6, 15003, 'tt0940657', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2220859584.jpg', 1.8, 12.1, 50.1, 26.2, 9.8, '0.111846,0.400723,-0.612597,0.769005,0.522182,-0.401666,0.626850,-0.044139,-0.475622,-0.183299,-0.150355,0.600254,-0.300807,0.384917,0.177984,0.137982,-0.493207,-0.514465,-0.341160,-0.181785,-0.161680,-0.283362,-0.287526,-0.200735,-0.094130,-0.316630,0.499327,0.297746,-0.007518,0.432515,0.383136,0.121458,-0.165245,0.546482,0.013904,-0.288618,-0.035324,-0.002789,-0.440532,0.282662,0.199673,-0.061946,-0.116166,0.311026,0.280510,0.217260,0.721279,-0.668939,-0.259785,-0.194163,0.408781,-0.148950,-0.021252,-0.116253,0.237804,0.194792,0.364016,-0.013883,-0.173169,0.080298,-0.124012,-0.554116,-0.743448,0.105722,-0.018257,0.245680,-0.459184,0.117040,-0.168188,0.230737,0.160099,-0.395975,0.303461,0.416967,0.272285,0.404794,-0.095523,0.138964,-0.214477,0.162704,0.563370,-0.065546,-0.254487,0.158056,-0.117467,-0.491839,0.162933,-0.111121,-0.296124,0.195525,0.347465,0.061680,0.135621,-0.061455,-0.761104,0.034545,-0.404873,-0.318047,0.104423,-0.348477,0.157920,-0.759249,0.311818,-0.175410,-0.199873,0.213213,0.210960,-0.203021,0.524655,-0.759703,0.371517,0.317901,0.390677,-0.237508,0.399876,-0.192666,-0.064814,-0.232464,-0.394994,0.148934,-0.252999,0.271205,0.228963,0.468481,0.241667,-0.243424,-0.477392,0.391538', '1420088', '3178770', '11810348', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1981645', '亚瑟3：终极对决', '动画', '《亚瑟》系列电影改编自法国“亚瑟”奇幻小说系列，小说共分四部，此部电影改编自小说第四部《亚瑟和两个世界的战争》。这一集的故事延续上一集，玛塔扎德终于来到了人类的世界。因为自己的身体已经庞大于人类，所以这一次他想组织一支巨人军队，完场自己征服宇宙的梦想。而这一次，只有亚瑟（弗莱迪·海默 Freddie Highmore 饰）可以阻止他的邪恶计划。而幸好他并不是孤军作战，他在迷你王国的未婚妻赛琳娜和好朋友也前来帮忙。而最让人吃惊的是：玛塔扎德的儿子达克斯决定站在亚瑟一派，一起对抗父亲的阴谋。一场保护人类不受危害的战役即将开始......©豆瓣', '弗莱迪·海默', '吕克·贝松', 6.7, 10472, 'tt0940656', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1202649145.jpg', 1.4, 9.3, 52.1, 26.5, 10.6, '0.080144,0.124428,-0.674380,0.822046,0.202900,-0.223635,0.820779,0.088795,-0.325940,-0.130919,0.226200,0.831178,0.044962,-0.116503,0.158176,0.103177,-0.422823,-0.560622,0.000203,-0.050553,-0.234625,-0.326552,-0.480159,-0.501672,0.070141,-0.508486,0.977876,0.053043,-0.269263,0.141146,0.434368,0.250776,0.012137,0.384279,0.026609,-0.016970,0.043280,-0.122254,-0.446426,0.426198,-0.012073,0.166576,-0.380219,0.444648,-0.046702,0.023492,0.592706,-0.531138,0.013356,-0.283820,0.440473,-0.501623,-0.069191,-0.192952,0.211448,-0.296759,0.375176,0.132496,0.353357,-0.012918,0.034400,-0.240249,-0.953452,0.017769,0.088161,0.121275,-0.473821,0.575586,-0.190664,-0.100643,0.095247,-0.249366,0.065708,0.586074,0.654189,0.266077,-0.147526,-0.097581,-0.463172,0.274306,0.537631,-0.033092,-0.308842,0.600167,-0.010687,-0.461560,-0.607822,-0.167112,-0.690242,0.224937,0.252807,-0.210303,-0.206684,0.398980,-0.846262,0.007900,-0.258532,-0.500186,0.029061,-0.559815,0.177448,-0.512897,-0.324808,-0.080086,-0.135265,-0.198810,0.304313,-0.342475,0.786332,-0.679462,0.196125,0.708486,0.142799,-0.412916,0.647926,0.312576,-0.057731,-0.246774,0.096215,0.433365,-0.154255,0.194298,0.115426,0.251352,0.401671,0.030849,-0.422118,0.784562', '26667010', '3769423', '26759819', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1982073', '人蛇大战', '剧情', '老板為賺錢趕工起樓，發現了蛇竇，老板帶頭盡殺幾十萬條蛇。大廈完成後，卻引來了千萬條蛇來報仇。', '向云鹏', '张旗', 6.5, 4964, 'tt0100472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2211641826.jpg', 3.3, 11.6, 53, 22.7, 9.4, '0.102478,-0.655779,0.661023,-0.091155,0.298799,-0.886259,0.629410,-0.175260,-0.502764,1.255847,0.996007,-0.632707,-0.084822,-0.049958,-0.120315,0.262453,0.140290,0.876752,0.994601,0.265068,0.043442,0.635637,-0.713733,0.053522,0.043433,-0.254008,-0.266093,-0.118675,1.280189,0.547597,-0.074329,-0.165167,0.310708,0.369770,0.304022,0.703938,0.885973,-0.646441,0.651610,0.320745,-0.187414,0.125513,1.220561,0.925524,-0.029805,0.476650,0.492452,-1.513973,-0.467205,-1.050780,0.063209,-0.191875,0.189783,0.049117,1.031163,-0.509264,0.438373,0.568460,-0.183886,0.150138,-0.288850,0.532929,-0.021558,-0.222202,-0.644018,0.989346,-0.605194,0.808576,0.086070,1.520105,-0.245068,-1.023049,-0.335367,-1.114679,0.374383,-0.524813,0.581718,0.663705,-1.381594,0.349568,0.504139,-0.345273,0.305733,0.014905,0.115837,-1.032616,0.362336,0.537816,1.865510,-0.353003,1.434275,-0.241425,-1.440031,0.052319,-1.454408,-0.495016,0.097182,0.560456,-0.202125,0.021701,-1.049162,0.251799,0.448195,-0.194496,0.812032,-0.562682,-0.284929,-0.069443,0.251073,-0.934087,-0.603484,0.893014,0.334901,0.304971,0.804832,-1.405044,0.429845,-0.814702,0.565403,-1.387390,0.089221,0.865497,1.327711,0.557006,0.772259,-0.053791,-0.041177,0.740889', '27042405', '3062897', '1291573', '1298586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1985677', '异星战场', '动作', '曾荣获奥斯卡金像奖的著名导演安德鲁·斯坦顿带来全新力作《异星战场》，一部以神秘壮丽的火星为背景的史诗动作冒险巨制。影片根据埃德加·赖斯·巴勒斯于20世纪初创作的经典科幻小说《火星公主》改编，故事 讲述美国内战时期，饱受创伤的前军官约翰·卡特（泰勒·克奇 Taylor Kitsch 饰）无意间穿越到了火星。由于引力不同，约翰成为了力大无穷、弹跳如飞的“超人”，也因此卷入当地几大族群的冲突，周旋于美丽的公主德佳·索丽斯（琳恩·柯林斯 Lynn Collins 饰），英勇的盟友塔斯·塔卡斯（威廉·达福 Willem Dafoe 饰）与狡猾的敌人萨博·赞恩之间。然而地球上战火纷飞带来的痛苦，早已让约翰无心恋战；虽然几大族群都将他视为能够拯救火星的关键人物，可他真的能抛下过去，担负起保卫人民的重任，拯救这个水深火热的世界，扭转异星战场的命运吗？©豆瓣', '泰勒·克奇', '安德鲁·斯坦顿', 6.5, 66556, 'tt0401729', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1560217027.jpg', 2.7, 12.4, 50, 26.4, 8.5, '0.027162,0.235183,-0.675916,0.561315,0.295871,-0.215312,0.596887,-0.027189,-0.202034,-0.031674,0.327130,0.801053,-0.012502,-0.083553,0.521623,-0.067827,-0.365273,-0.545603,-0.039738,0.052587,-0.295478,-0.401614,-0.692247,-0.350156,-0.097176,-0.591624,0.619758,0.053254,-0.423507,0.296336,0.163895,0.312184,-0.133309,0.160783,-0.108843,0.051307,0.005502,0.060237,-0.556390,0.045053,-0.248647,-0.033698,-0.080935,0.217059,-0.086790,0.091683,0.420932,-0.646477,0.198142,-0.352542,0.575729,-0.115194,0.094440,-0.281826,0.282162,-0.036166,0.010322,0.016189,0.226160,-0.087072,0.163222,-0.254960,-0.900105,0.063208,0.072615,0.156374,-0.516373,0.329362,-0.073360,-0.026956,0.073270,-0.052432,0.008559,0.244582,0.464822,0.375608,-0.139196,0.138485,-0.214903,0.266368,0.452124,0.041162,-0.654152,0.013987,-0.315693,-0.340452,-0.217915,-0.429025,-0.442801,0.009655,0.383654,-0.129174,0.019802,0.717535,-0.583669,-0.045724,-0.463692,-0.213546,0.037403,-0.176313,-0.085267,-0.620674,-0.144328,-0.274185,-0.056552,-0.068328,0.299892,-0.157889,0.863932,-0.423458,0.229843,0.627708,-0.004048,-0.301335,0.470272,0.131856,0.076169,-0.174828,-0.002705,0.596506,0.058627,0.224577,-0.052444,0.237606,-0.012235,-0.089687,-0.210822,0.619189', '27602116', '24284209', '26647163', '3036473');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1985959', '小心为上', '剧情', '克里斯（约瑟夫·高登·莱维特 Joseph Gordon-Levitt饰）曾经是一个耀眼的男生：身为冰球明星，有着优越的家境，漂亮的女友，人生如平坦的大道一样畅顺。一场车祸却摧毁了一切，他患上了短暂失忆，每天都在无法控制的状态中度过，就连车匙放在哪里之类的小问题，克里斯也无法有把握地记起。如今他成了银行的守门人，身边唯一的朋友就是盲人路易斯（杰夫·丹尼尔斯 Jeff Daniels饰），他用快乐的人生观指点着克里斯该如何应对生活。有人想方设法接近克里斯，那就是加里（马修·古迪 Matthew Goode饰）。加里对克里斯的际遇十分关心，为他介绍女朋友，把他恢复以往生活的内心欲望唤醒，更重要的目标，是和他合谋参与银行劫案。克里斯不但面对着失忆的苦恼，如今还要应付这个棘手的计划，把人生的掌握权夺回自己手中。©豆瓣', '约瑟夫·高登-莱维特', '斯科特·弗兰克', 6.7, 6201, 'tt0427470', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p621253843.jpg', 1.2, 7.9, 53.2, 31.4, 6.3, '0.226153,0.146430,-0.354190,0.654755,-0.326719,-0.335285,0.641657,0.122446,-0.275867,-0.286641,0.087117,0.491289,-0.013092,0.193065,0.145305,0.105598,-0.323162,-0.686104,-0.057322,0.156564,-0.143385,-0.618417,-0.552249,-0.278139,-0.195021,-0.294481,0.581827,-0.032355,-0.095010,0.097835,0.334419,0.361269,0.176976,0.223104,-0.080747,-0.066516,-0.218186,-0.002284,-0.455440,0.196147,0.105502,-0.008129,-0.118826,0.339325,0.194059,0.209400,0.532295,-0.127811,-0.237840,-0.121987,0.334451,-0.169935,0.010138,0.210463,0.093839,-0.007773,0.095689,0.061148,-0.198772,0.096421,0.204280,-0.182826,-0.916589,-0.118736,0.109157,0.238132,-0.544262,0.208168,-0.243942,-0.118520,0.185296,-0.429991,0.002871,0.366193,0.113171,0.483247,-0.232759,-0.100516,-0.440924,0.180078,0.683669,-0.119812,-0.339336,0.488605,-0.418763,-0.077346,-0.304957,-0.243351,-0.527994,0.042942,0.173043,0.119826,-0.033833,0.506669,-0.217051,0.170650,-0.338573,-0.238892,-0.088646,-0.450449,0.014060,-0.404462,-0.102775,-0.351497,-0.429753,-0.191123,-0.018574,-0.444965,0.573058,-0.816114,0.162076,0.587981,0.150918,-0.317183,0.348323,0.316518,0.040068,-0.473052,-0.195466,0.370025,0.094384,0.088400,-0.074369,0.200228,0.145433,0.046907,-0.212226,0.833792', '1811755', '1793491', '10440076', 