INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1986338', '歌舞青春2', '剧情', '高一生涯结束，野猫队的所有成员都准备好迎接美妙的暑假。暗恋特洛伊（扎克·埃夫隆 Zac Efron饰）已久的夏培（阿什丽·提斯代尔 Ashley Tisdale 饰）利用她父亲的影响力帮特洛伊在自家经营的豪华俱乐部中弄到一份工作，和藉机让他获得大学篮球奖学金的机会。而条件是特洛伊必须放弃野猫队,并和夏培搭档参加俱乐部一年一度的才艺比赛。同时，这也是夏培让特洛伊远离女朋友盖比瑞拉（瓦妮莎·哈金斯 Vanessa Hudgens饰）的计谋。可特洛伊让盖比瑞拉被同时被俱乐部录用，让夏培十分气愤。夏培的弟弟莱恩和没了特洛伊的野猫队合作，排练曲目参加比赛。不料被夏培知道，强行取消了他们的资格。盖比瑞拉伤心地从俱乐部辞了职，并开始与特洛伊产生裂痕，野猫队的成员也开始把特洛伊排除在外。这一次特洛伊到底该选择哪一边的阵营？这个夏天到底会有怎样不一样的抉择？©豆瓣', '扎克·埃夫隆', '肯尼·奥特加', 7.3, 84222, 'tt0810900', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558529447.jpg', 0.7, 4.3, 40.4, 39.1, 15.5, '0.136226,0.010794,-0.575413,0.589027,-0.137498,-0.267638,0.418219,0.143878,-0.249770,-0.051712,-0.008464,0.742424,-0.280177,0.032003,0.360832,-0.169092,-0.351462,-0.796770,0.162723,-0.266592,-0.321630,-0.519655,-0.027498,0.114547,0.148709,-0.274783,0.811442,-0.182068,-0.032099,0.443258,0.513425,0.380445,0.174194,0.300812,0.050755,-0.024403,0.236243,0.106447,-0.209626,0.237010,0.014821,0.018770,-0.268888,0.179519,0.329997,0.216642,0.472911,-0.100641,0.145284,-0.130129,0.219397,-0.120172,0.182123,0.216687,0.458705,-0.189049,0.053474,0.253126,-0.003035,0.166631,0.166276,-0.304076,-0.845887,0.299779,0.231564,-0.060490,-0.862746,0.564012,-0.130202,0.164911,0.185080,-0.017085,0.072923,0.644645,0.261569,0.303541,0.000812,-0.081493,-0.538054,0.008862,0.608717,-0.204544,-0.085927,0.233035,0.042138,-0.370550,0.052969,-0.295296,-0.407304,0.114906,0.253172,0.026644,0.046599,0.044511,-0.648065,-0.006642,-0.157122,-0.433857,0.062231,-0.611948,0.067902,-0.629783,0.066817,-0.186824,-0.279633,-0.036111,-0.012305,-0.230902,0.512322,-1.125571,0.068844,0.627788,0.299168,-0.535093,0.479452,0.195708,0.365981,-0.065217,-0.171679,-0.051377,0.098876,0.167071,0.192324,0.447097,0.229662,-0.577663,-0.244708,0.576106', '30345227', '35030151', '1793491', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1987561', '消防犬', '喜剧', '小狗雷克斯是一条家喻户晓的明星犬，它在好莱坞的地位堪比一线明星，它吃着精细贵重的狗粮，被影人粉丝簇拥，终日过着养尊处优的快乐生活。然而一场意外让雷克斯无忧无虑的日子发生翻天覆地的转变，在一次拍摄中雷克斯不慎从几千米的高空坠落，而它的同伴都认为它必死无疑。事实上，雷克斯幸运地落在一辆拉载番茄的卡车上，几经辗转来到了12岁的小男孩谢恩·费伊（Josh Hutcherson 饰）的家中。谢恩生活在一个单亲家庭，他跟身为消防队队长的老爹克纳（Bruce Greenwood 饰）简直是一对斗气冤家，雷克斯的到来更使费伊热闹了几分。不久，雷克斯的才能被人发现，它成为一条名副其实的消防犬……©豆瓣', '乔什·哈切森', 'Todd Holland', 7.6, 5724, 'tt0476995', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2524249172.jpg', 0.4, 2.4, 32.1, 49, 16.1, '0.379402,-0.055204,-0.579339,0.645281,0.024959,-0.106067,0.920370,0.173784,-0.524217,0.075019,0.576773,0.760885,-0.411611,0.129663,0.255255,-0.208760,0.059644,-0.286582,0.135167,-0.146410,-0.106973,-0.118946,-0.474650,-0.207863,-0.116478,-0.358848,0.648346,-0.001366,0.201738,0.465765,0.300696,-0.181612,0.014632,0.432948,-0.442211,0.037258,0.040811,0.036903,0.095336,0.100771,-0.255474,-0.434113,0.000554,0.108092,0.016863,0.001342,0.806315,-0.438992,-0.190127,-0.088657,0.440248,-0.370969,0.021549,0.126407,0.507000,0.023676,-0.055029,-0.087362,0.052404,0.187236,0.112097,-0.190943,-0.477543,-0.053657,-0.201301,0.306371,-0.771890,0.625707,-0.018783,-0.088830,0.012669,-0.355912,0.191153,0.140954,-0.074496,0.436077,-0.191111,0.127212,-0.678067,0.322137,0.858730,-0.074143,-0.448939,0.412164,-0.272735,-0.587810,-0.137465,-0.245867,-0.698489,-0.233901,0.450934,-0.068220,-0.447803,0.365854,-0.597677,0.231739,-0.357308,-0.257302,-0.211178,-0.276208,-0.285742,-0.453703,0.133367,-0.670009,-0.139425,0.183783,0.071980,-0.328739,0.648729,-0.538146,0.146234,0.503508,0.032323,-0.116324,0.661591,-0.398805,0.222675,-0.086956,-0.130787,0.213458,0.084697,0.190370,0.211777,0.448371,-0.168068,-0.036795,-0.364941,0.566319', '21619567', '3055049', '30162520', '1307561');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19899626', '医生', '惊悚', '其貌不扬的医生崔仁范（金昌完 饰）经营一家整形医院。他事业卓有成就，生活优渥，妻子（裴素恩 饰）更是美艳动人。然而凡事总有缺憾，崔医生隐隐觉察妻子对自己的不忠，他早晨假装上班，中途偷偷回家，果然目击妻子和情人（徐建宇 饰）幽会的场面。他心中的愤怒恣意疯长，最终将一腔怒火倾泻在岳母和妻子身上。业已畸形的心和灵魂，极度扭曲的崔医生已经被心中的野兽所侵蚀。当崔医生再度回到诊所，其本人早已化作视生命如草芥的恶魔，在这个小小的王国内。崔医生用手术刀向他的病人、医护人员展开了丧尽天良、惨无人道的杀戮……©豆瓣', '金昌完', '金成洪', 5, 6727, 'tt2466708', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2013546880.jpg', 16.1, 35.5, 35.1, 8.4, 4.9, '-0.084240,-0.026863,-0.418670,0.403200,-0.118396,-0.418779,0.878569,0.393683,-0.589833,-0.405389,-0.021205,0.220222,-0.371290,0.602567,0.234590,-0.145353,-0.078530,-0.596988,-0.349141,0.270294,-0.201232,-0.159608,-0.125080,-0.449532,-0.050263,0.086423,0.442644,0.044430,-0.056836,0.279932,0.215048,0.477405,-0.003568,0.552437,-0.173138,0.023313,-0.299876,-0.132531,-0.361188,-0.072078,0.635913,-0.338142,0.024864,0.258471,-0.200540,0.474220,0.707400,-0.003176,-0.179609,-0.370575,0.512827,-0.052445,0.272715,0.431786,0.075888,0.045699,0.115061,-0.074986,-0.242254,-0.062402,0.132455,-0.151499,-0.478672,-0.219700,0.131846,0.013677,-0.517060,0.116216,-0.147793,0.223498,0.178925,-0.342998,0.285718,-0.198900,-0.139863,0.787120,-0.210851,0.016567,-0.524641,0.459965,0.331959,0.254154,-0.377458,0.313651,-0.386128,-0.486644,-0.076832,0.021596,-0.503377,-0.139624,0.406140,0.181272,-0.168138,0.349755,-0.407362,-0.309079,-0.134015,0.102316,-0.047570,-0.209793,-0.059392,-0.271896,-0.145954,-0.348450,-0.284838,0.126912,0.108497,0.007923,0.555100,-0.723336,0.158870,0.129659,0.043094,-0.487171,0.453098,-0.134549,0.074150,-0.110328,0.121268,0.589538,0.209185,0.493215,0.309241,0.257487,-0.169899,0.188746,-0.081280,0.442576', '21619567', '10777687', '21348112', '10508879');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19899663', '妈妈别哭', '剧情', '《妈妈别哭》是继《熔炉》之后又一部韩国现实主义力作，入围了第17届釜山电影节的广阔镜单元。本片改编自现实中“得知女儿因为被男学生们强暴而自杀的妈妈亲自为女儿报复”的残忍故事。刚和丈夫离婚准备重新出发的刘琳（柳善 饰）在告别不幸婚姻后原本打算带着刚升为高中生的唯一女儿 柳银雅（南宝拉 饰）重新开始。两人相依为命过着简单平静的生活。但不幸从天而降，银雅竟然选择在自己生日的那天自杀，这也摧毁了刘琳最后的精神支柱。某天，她通过银雅的同学赵翰（申东浩 饰）知道了女儿惨死的真相：在学校遭到多名男同学的强奸，加害者却因未成年人的身份免于受到处罚，对这一结果无法承受的银雅选择了自杀。此后，刘琳受到了前所未有的打击，再不相信法律的她决定无论用何种方法，自己来帮女儿报这个仇，并驱使着她一步步走向无法挽回的结局......©豆瓣', '柳善', '金容汉', 6.6, 20349, 'tt2468826', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1758860244.jpg', 3.3, 13.1, 46.2, 26.5, 10.9, '0.026615,0.043383,-0.684746,0.484801,-0.071583,-0.210487,0.649378,0.145238,-0.388012,-0.207536,0.239948,0.832310,-0.002710,0.383293,0.359208,-0.057879,-0.242623,-0.400866,-0.077065,-0.186916,-0.419379,-0.390717,0.114755,-0.020625,0.020609,-0.126657,0.623632,-0.020264,-0.165416,0.357907,0.537747,0.312215,0.086803,0.332268,-0.050826,0.210389,-0.090591,0.168522,-0.447329,0.338383,0.192529,-0.273880,-0.078308,0.372903,-0.200478,0.385884,0.751148,-0.296364,-0.202756,-0.190727,0.590139,-0.417642,-0.160221,0.426165,0.233169,0.052885,0.200774,0.298066,-0.171077,-0.077540,0.152887,-0.065889,-0.704397,-0.118950,0.261232,-0.194429,-0.518231,0.377266,-0.151186,0.118748,0.163041,-0.244232,0.145858,0.522915,0.363871,0.403910,-0.488839,0.006280,-0.337289,0.271864,0.794377,-0.105378,-0.070444,0.254544,-0.200206,-0.323221,0.132448,-0.456991,-0.547998,0.135223,0.227352,0.248237,-0.361391,0.072837,-0.252423,-0.255069,-0.217841,-0.123484,0.049861,-0.411334,-0.032016,-0.141217,-0.060138,-0.087407,-0.320004,0.099130,-0.098309,-0.262483,0.692173,-0.771690,0.375897,0.459607,0.504345,-0.726451,0.493181,0.435655,0.067062,-0.212531,0.057533,0.243062,-0.086341,0.469367,0.129896,0.177526,0.223590,-0.115346,-0.306611,0.403332', '1296569', '26678784', '25721544', '1877596'