INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19899707', '驯龙高手3', '动画', '梦工场动画将倾情奉献一段跌宕起伏的故事，主人公们不断成长，寻找面对未知的勇气，始终不离不弃。一位维京少年和一只令人生畏的夜煞飞龙之间看似不可能的友情，已经演变成了一段持续彼此一生的史诗级冒险。这便是即将上映的《驯龙高手3》，也是影史上最受欢迎的动画系列之一《驯龙高手》系列最为浓墨重彩的崭新篇章。统领伯克岛的酋长嗝嗝，与阿丝翠德共同打造了一个奇妙而热闹的飞龙乌托邦。而一只雌性光煞飞龙的意外出现，加上一个前所未有的威胁的到来，令嗝嗝和没牙仔不得不离开自己唯一的家园，前往他们本以为只存在于神话之中的隐秘之境。在发现自己真正的命运之后，飞龙与骑士将携手殊死奋战，保护他们所珍爱的一切。', '杰伊·巴鲁切尔', '迪恩·德布洛斯', 7.4, 251293, 'tt2386490', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546335362.jpg', 0.5, 3.8, 37.3, 42.7, 15.6, '0.229149,-0.107806,-0.637345,0.813435,0.329332,-0.029438,0.721299,-0.205283,-0.347730,-0.359859,0.539807,0.912898,-0.055124,0.081784,0.496417,-0.363562,0.122888,-0.645324,-0.291595,-0.012392,-0.111080,-0.187402,-0.802099,0.042211,-0.232890,-0.299533,1.048701,0.259435,-0.241387,0.443166,0.298755,0.349309,-0.430440,0.216447,-0.221631,-0.220643,0.171923,0.042289,-0.329480,0.185784,-0.152106,-0.115783,0.092426,0.335556,-0.405594,-0.015095,0.845501,-1.001564,-0.091589,-0.209438,0.389750,-0.501811,-0.316802,0.049769,0.076204,0.108131,0.375283,0.296821,0.047209,0.112406,-0.121255,-0.294130,-1.226784,-0.064123,0.083457,0.142311,-0.391871,0.448861,0.023005,-0.232941,0.305198,-0.230462,0.327946,0.326842,0.553881,0.349914,-0.358916,0.101640,-0.442449,0.256037,0.911131,-0.058860,-0.337699,0.406690,0.217069,-0.559443,-0.302553,-0.491439,-0.564419,0.000899,0.114292,0.375579,0.023099,0.213088,-0.963244,0.296901,-0.346645,-0.334699,-0.042456,-0.518736,-0.166207,-0.454564,-0.116243,-0.432796,-0.144134,0.182341,0.274219,-0.293073,0.989661,-0.732060,0.248629,0.294664,-0.010170,-0.333359,0.814087,0.100187,0.341847,-0.199831,-0.000480,0.325477,0.006902,0.171176,0.059718,0.263635,-0.113256,0.191044,-0.483389,0.665572', '26667010', '25880986', '26759820', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19899718', '蓝精灵：寻找神秘村', '喜剧', '一次偶然中，蓝妹妹（黛米·洛瓦托 Demi Lovato 配音）发现了一张遗落的地图，指引向一座神秘的村庄。为了求证村庄存在的真实性，蓝妹妹和好友聪聪（丹尼·普迪 Danny Pudi 配音）、健健（乔·曼根尼罗 Joe Manganiello 配音）、笨笨（杰克·麦克布瑞尔 Jack McBrayer 配音）一起踏上了旅途。一路上，初出茅庐的四人组遭遇了无数的危险，但总能凭借他们的智慧和运气化险为夷，四人的友情亦遭到了重重考验。邪恶的格格巫（雷恩·威尔森 Rainn Wilson 配音）也知晓了村庄的存在，为了第一个到达村庄，格格巫开始千方百计的阻挠起蓝妹妹一行的前途。©豆瓣', '黛米·洛瓦托', '凯利·阿斯博瑞', 6.2, 18254, 'tt2398241', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2443742358.jpg', 2.1, 16.2, 57.6, 19.5, 4.7, '0.446579,-0.065483,-0.284475,0.849936,0.056850,-0.242075,0.727217,-0.022344,-0.478534,-0.209752,0.183913,0.658192,-0.136006,0.128834,0.280330,-0.173555,-0.273201,-0.278485,0.096827,-0.256432,-0.301301,-0.526002,-0.459033,-0.251291,-0.174384,-0.443370,0.312003,0.181051,-0.140397,0.608335,0.247115,0.205537,-0.456453,0.149166,0.054870,0.202646,0.073156,-0.058894,-0.237466,0.313744,-0.170243,-0.025157,-0.019636,0.255388,-0.060023,0.416045,0.681017,-0.335853,0.038746,0.023567,0.378213,-0.203487,0.426423,0.168247,0.449755,-0.155363,0.104724,0.069839,0.037643,0.153803,0.052717,-0.170354,-0.633846,-0.031005,0.099306,0.059011,-0.426994,0.105336,0.191011,-0.116882,-0.009978,-0.285026,0.256093,0.453567,0.417459,0.225537,-0.145790,0.152877,-0.243154,-0.224311,0.215424,-0.230852,0.036304,0.291045,0.062768,-0.639129,-0.030232,0.079730,-0.496571,0.171209,0.590977,-0.029654,-0.086937,0.111795,-0.835378,0.083835,-0.255435,-0.222834,-0.093153,-0.290805,-0.022382,-0.675736,-0.194070,-0.146198,-0.071430,0.045665,-0.221911,-0.375974,0.688399,-0.662414,0.246313,0.688324,0.123585,-0.172562,0.480649,-0.085718,0.214127,-0.212026,0.096336,0.310543,0.057771,0.368578,0.192738,0.353632,-0.030432,-0.187594,-0.268938,0.423410', '26290398', '1308585', '26839466', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19944106', '美人鱼', '喜剧', '白手起家的富豪刘轩（邓超 饰）新拍下了一块地皮，并联合了女强人李若兰（张雨绮 饰）使用恐怖的声纳技术驱赶鱼类，用于填海造地。人鱼一族长期居住在附近区域的海里，为了继续生存，带头大哥章鱼八哥（罗志祥 饰）派出了美人鱼珊珊（林允 饰）“色诱”刘轩，准备刺杀。没想到珊珊在卧底过程中与刘轩暗生情愫，一次次破坏暗杀计划，而李若兰却在准备一个更丧心病狂的邪恶计划……©豆瓣', '邓超', '周星驰', 6.7, 774143, 'tt4701660', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2316177058.jpg', 3.8, 12, 42.7, 28.9, 12.6, '0.060001,0.048178,-0.348328,0.501101,0.012395,0.138599,0.390830,0.142926,-0.361778,-0.070113,0.462602,0.187870,0.030701,-0.148146,0.022281,-0.114495,-0.490110,-0.110204,0.001837,0.057871,-0.292525,-0.159500,-0.399610,-0.264883,0.101844,-0.231422,0.685514,0.041836,-0.348203,0.308814,0.085341,0.323527,-0.502190,0.336022,0.099926,-0.186456,0.290346,-0.063536,-0.181803,0.366864,-0.448600,-0.184310,0.035762,0.215384,-0.064003,0.400483,0.616129,-0.242315,0.156104,-0.461891,0.027072,-0.168398,0.039114,-0.106476,0.422215,-0.274135,0.306071,0.191330,-0.229693,0.073243,0.384688,-0.206174,-0.772131,-0.077443,0.169505,-0.140588,-0.325132,0.195989,0.041035,0.135298,0.059102,-0.371827,-0.072129,0.284168,0.333599,0.183915,-0.288817,0.065780,-0.182667,0.383967,0.359148,-0.173628,0.388805,0.191090,0.110034,-0.366836,-0.102322,-0.068894,-0.117678,-0.336056,0.351915,0.062857,-0.199310,0.220504,-0.920148,-0.003312,-0.240359,0.043453,0.038894,-0.278790,-0.149391,-0.628468,0.095620,0.032282,-0.032415,0.169744,0.224270,-0.088097,0.345810,-0.573729,0.027039,0.482109,0.230928,-0.720235,0.047775,-0.092468,-0.160060,-0.137339,-0.176702,-0.113272,0.010433,0.132872,0.106887,0.390013,0.084787,-0.363709,-0.180895,0.314263', '26290398', '1292680', '25774050', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19944289', '过界男女', '剧情', '香港人辉（陈坤 饰）给一个阔太李太当司机，他娶了一个深圳女人婷（田原 饰），两人已经有了一个女孩，但是婷又怀上了二胎，为了不用交超生罚款，辉想让婷去香港产子。他奔波在各个医院，却被告知已经没有空的床位，而找中介公司却要花费20万元的巨款，辉尝试了各种方法......辉的老板李太（刘嘉玲 饰）生活在上层社会中，老公事业有成，女儿在国外念书，生活无忧。可是有一天，她的丈夫Leo不知所踪，Leo名下的账户都被冻结了。为了维持生计，李太只能变卖股票和家里各种值钱的东西，来维持表面的风光生活......辉终于等到了机会，李太让他开车载她去深圳办事，而在回来的路上，发生了一件让李太始料未及的事情......©豆瓣', '刘嘉玲', '刘韵文', 5.7, 13388, 'tt2852460', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2167587449.jpg', 8.6, 25.3, 42.6, 17.6, 5.8, '-0.040472,0.061772,-0.644036,0.349504,-0.341298,-0.421539,0.511752,0.181856,-0.117193,-0.301438,-0.080936,0.709832,-0.020214,0.261413,0.182852,0.217657,-0.074432,-0.629013,0.250914,-0.409997,-0.309747,-0.212788,0.235466,-0.181779,-0.129915,0.052854,0.472995,0.149235,0.192611,0.206236,0.146036,0.138275,-0.030107,0.543562,-0.549051,0.170089,-0.164367,0.117976,-0.011322,0.220896,0.466366,-0.565139,-0.183215,0.481986,0.490635,0.501873,0.753401,0.231527,-0.136845,0.042019,0.172917,-0.037739,-0.168771,-0.271959,0.290556,-0.263483,0.199859,0.127848,-0.623659,-0.128198,0.141084,-0.068961,-0.895312,0.020051,0.036502,-0.130313,-0.791777,0.555063,-0.130258,0.186979,-0.362278,-0.473616,0.466347,0.418698,-0.265291,0.440250,-0.148469,0.080341,-0.716283,0.470515,0.719996,-0.098461,0.000231,0.746361,-0.365898,-0.080305,-0.012717,-0.300874,-0.699654,-0.054202,0.199138,-0.122342,-0.444874,-0.299007,-0.525166,0.068847,-0.530846,-0.266088,-0.032590,-0.314699,-0.108310,-0.330914,-0.055537,-0.350278,-0.309709,0.139634,0.090968,-0.184750,0.555007,-0.687369,-0.112834,0.507791,0.641816,-1.073678,0.858408,-0.162910,0.217073,-0.075846,0.140645,-0.341660,-0.043205,0.294869,0.296174,0.150554,-0.063777,-0.261979,-0.285045,0.343266', '26678784', '1306916', '1877596', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19945757', '偶滴神啊', '剧情', '售卖佛像的古董商人坎杰（Paresh Rawal 饰）是个无神论者。他把佛像视为玩具，不明白那些花招百出的宗教仪式，希望把女儿培养成飞行员，把儿子培养成板球球员。古董店寄托着他全部的希望和感情。某一天热闹的祭祀仪式上，坎杰为了把参与活动的儿子揪回去，开了神的玩笑，被教派的头目警告会遭到神的报应。当天天气突然由晴转阴，且引发了一场地震。其它店铺无一受损，唯有坎杰的店被震的面目全非。本以为投了保险可以挽回损失的坎杰被保险公司告知这属于不可抗力的天灾人祸，不在承保范围内。一无所有的坎杰一纸状书把神告上了法庭。而被告人则是那些借助神灵名义四处捞金的教派头目们。一场看似离奇的官司就这样展开，而神灵（阿克谢•库玛尔 Akshay Kumar 饰）本人似乎也对此事很感兴趣，他隐藏在人群中，来到了坎杰身边，也改变了坎杰对宗教的看法……©豆瓣', '阿克谢·库玛尔', 'Umesh Shukla', 8.4, 62930, 'tt2283748', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1799437388.jpg', 0.4, 1.4, 13.9, 45.5, 38.8, '0.538090,0.168572,-0.513079,0.454001,-0.158683,0.067242,0.550251,0.055818,-0.356922,-0.050913,0.212646,0.790538,-0.293323,0.044264,0.227074,-0.059461,-0.108267,-0.725499,-0.355431,-0.144440,-0.249555,-0.493095,-0.102372,-0.214396,-0.364976,-0.312979,0.292335,0.170624,-0.219900,0.159144,0.341863,0.239686,0.156172,0.302416,-0.202389,-0.081736,-0.320064,0.079272,-0.014960,0.263982,-0.067159,-0.378250,0.135972,0.362167,-0.025657,0.330129,0.647199,-0.420493,-0.085160,-0.300351,0.322062,-0.331543,0.031208,0.383061,0.311843,0.218532,0.046087,0.204290,-0.201588,-0.116784,0.381663,-0.080322,-0.770836,-0.228893,0.237128,0.053908,-0.750440,0.412094,-0.007432,-0.079049,-0.219241,-0.205485,0.463279,0.262259,0.294968,0.375606,-0.054255,-0.128232,-0.815424,0.168875,0.485084,-0.201510,-0.134922,0.070440,-0.399849,-0.404005,0.028207,-0.387532,-0.251212,-0.105206,0.472465,-0.141697,-0.073097,0.092054,-0.574294,-0.232036,-0.118683,-0.507245,-0.093332,-0.519922,0.012376,-0.282788,-0.026844,-0.245017,-0.238502,0.065227,0.287479,-0.185148,0.644383,-0.760477,0.281750,0.545441,0.268625,-0.475860,0.640222,0.075541,0.210053,-0.110598,-0.116160,-0.306523,0.176682,0.514575,0.315893,0.225081,0.073564,-0.235485,-0.150920,0.367754', '1783461', '179349