INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1994876', '马达加斯加2：逃往非洲', '喜剧', '延续前一集的剧情，狮子亚历克斯（本·斯蒂勒 Ben Stiller 配音）、斑马马蒂（克里斯·洛克 Chris Rock 配音）、长颈鹿迈尔曼（大卫·休默 David Schwimmer 配音）、河马格洛里亚（贾达·萍克·史密斯 Jada Pinkett Smith 配音）以及企鹅们，为了能离开马达加斯加岛回到五光十色的纽约，对一架破旧的失事飞机进行维修改造，并成功起飞。当大家已经开始庆祝终于可以回到纽约时，飞机却意外降落，迫降到了非洲大草原上。在这儿，狮子亚历克斯终于见到了它的父母。但是由于生活习性上太多不一样，而且言行举止各异，使得这群纽约来的动物们显得格格不入。这群昔日纽约中央公园的动物明星们，在这野外艰难的环境中应该怎么办？虽然在这儿遇见了自己的同类，但因为习性不同，使得自己无法完全融入他们的群体。为了能融入环境，与同类们建立良好的关系，大家都是施展各种招式，笑料百出。', '本·斯蒂勒', '埃里克·达尼尔', 7.8, 117331, 'tt0479952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2220723383.jpg', 0.2, 1.7, 26.8, 50.6, 20.6, '0.438422,0.124935,-0.684757,0.415902,0.089410,-0.288319,0.374688,-0.003936,-0.384704,-0.288927,0.081556,0.680652,-0.126201,0.231178,-0.044976,-0.147766,-0.729714,-0.359530,0.029580,-0.133279,-0.248866,-0.265796,-0.311948,-0.323021,-0.090112,-0.120106,0.573465,-0.004540,-0.273871,0.312750,0.180826,0.280353,-0.021699,0.238657,-0.394729,-0.094787,0.014067,-0.023948,-0.184449,0.138537,-0.226940,0.130243,-0.061129,0.047648,0.450827,0.118109,0.852952,-0.358608,-0.348082,-0.262160,0.220581,0.091361,0.220886,0.273034,0.371671,-0.160651,0.317543,-0.175471,0.021330,0.348192,-0.227620,-0.123148,-0.634381,0.220584,-0.247116,0.155395,-0.278013,0.139340,0.163586,-0.153297,-0.057655,-0.293207,0.257194,0.440975,0.246530,0.353763,-0.107339,0.052309,-0.296472,-0.165162,0.793362,0.007460,-0.476923,0.443051,-0.337226,-0.494751,-0.240682,-0.244648,-0.201671,-0.187780,0.251187,0.115596,-0.233723,0.389519,-0.876062,0.079885,-0.201802,-0.411379,-0.224228,-0.207976,-0.031304,-1.009209,0.177419,-0.569329,-0.126441,0.033376,0.124453,-0.172473,0.614748,-0.923338,0.261487,0.445601,0.065185,-0.347507,0.357621,-0.058823,0.127675,-0.156386,-0.216566,0.322096,0.005893,0.419900,0.069818,0.308326,-0.014284,-0.065468,-0.395266,0.646426', '3178770', '2369613', '1498831', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1994879', '热带惊雷', '喜剧', '好莱坞计划拍摄一部讲述越战期间，美国一支精英小队前往越南东南部执行绝密任务的战争片，片名《热带惊雷》。该片耗资巨大，场面壮观，号称有史以来最贵的越战影片，并云集了塔克·斯皮德曼（本·斯蒂勒 Ben Stiller 饰）、柯克·拉扎鲁斯（小罗伯特·唐尼 Robert Downey Jr. 饰）、杰夫·波特尼（杰克·布莱克 Jack Black 饰）等过气或当红明星。为力求真实，导演达明·柯克伯恩（史蒂夫·库根 Steve Coogan 饰）甚至将剧组拉至东南亚进行拍摄。影片开拍伊始便状况不断，争议话题频出，最后还卷入当地一场真实的战争之中……本片荣获2009年美国演员协会杰出贡献奖、2008年好莱坞电影节年度喜剧奖、2009年青年艺术家奖最佳男配角奖（Brandon Soo Hoo）。©豆瓣', '本·斯蒂勒', '本·斯蒂勒', 6.9, 38266, 'tt0942385', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1650363880.jpg', 2.2, 8.8, 43.2, 34.1, 11.6, '-0.353212,0.062875,-0.498105,0.326658,0.885746,-0.037521,0.100034,0.071113,-0.131477,-0.105121,0.345592,0.599052,-0.461345,-0.411858,0.637269,-0.094286,-0.584925,-0.494117,-0.137314,-0.038595,0.279646,-0.090759,-0.591554,-0.156088,-0.117127,-0.388310,0.609427,-0.036226,-0.244520,0.361896,0.571356,0.108392,-0.023842,-0.184485,0.497108,-0.142390,0.681348,-0.294062,-0.651114,0.334346,-0.258700,-0.276423,-0.386683,-0.202188,0.260229,0.109457,0.515619,-0.082805,0.348866,-0.239779,0.513136,-0.298532,-0.167933,-0.333671,0.337683,-0.161714,0.560103,0.125367,0.207997,0.153970,-0.060059,-0.565343,-0.482886,0.283619,0.207787,0.275248,-0.134685,0.224104,-0.299876,0.343562,-0.134289,-0.180993,-0.134638,-0.190293,0.788788,-0.006681,0.299275,0.197278,0.116674,0.767327,0.194313,-0.109858,-0.413050,0.034262,0.015722,-0.505245,-0.242805,-0.467131,-0.494305,0.337356,0.398891,-0.401906,0.346607,0.399759,-0.409242,0.064699,-0.345819,-0.550656,-0.154217,0.210746,0.041576,-1.212012,-0.023553,0.128961,0.011931,-0.551497,0.180195,-0.093803,0.618748,0.070767,0.276758,0.460774,0.020576,-0.029612,0.387920,0.051074,0.268316,-0.338264,-0.325293,0.166131,-0.142979,-0.169157,-0.202735,0.074951,-0.043989,-0.800948,0.269564,0.256920', '34961898', '3003137', '1293572', '26335580');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19951149', '黑夜传说5：血战', '动作', '同时拥有狼族和血族两种血统的孩子伊薇成为了狼族和血族两大族群争相抢夺的对象，为了保护女儿的安全，母亲赛琳娜（凯特·贝金赛尔 Kate Beckinsale 饰）不得不带着伊薇过着东躲西藏的日子。崇尚暴力心狠手辣的玛瑞斯（托比亚斯·门基斯 Tobias Menzies 饰）成为了狼族新的首领，刚一上任，他便派出爪牙对血族进行了疯狂的围剿，血族的多处基地被狼族占领，情势岌岌可危。吸血鬼长老塞米拉（劳拉·普沃 Lara Pulver 饰）希望能够赦免赛琳娜的放逐，让她从新回到血族阵营，帮助训练吸血鬼战士对抗狼族。最终，赛琳娜回归了。可是，这群吸血鬼们实际上有着另外的算盘，那就是得到赛琳娜的血。©豆瓣', '凯特·贝金赛尔', '安娜·福斯特', 6, 26023, 'tt3717252', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2408506002.jpg', 4.1, 21.5, 50.1, 16.9, 7.4, '0.054571,0.204590,-0.206472,0.512311,0.021893,-0.310653,0.302704,0.072986,-0.488019,-0.178802,0.419150,0.749256,0.239555,-0.102811,0.283057,-0.130778,-0.380250,-0.359391,-0.158932,-0.183115,-0.370458,-0.088669,-0.469601,-0.293067,0.025021,-0.876872,0.579700,-0.287809,-0.397670,0.428510,0.290379,0.577672,-0.248082,0.042182,-0.066340,-0.217745,0.455759,-0.380145,-0.501275,0.454661,-0.267840,0.478568,-0.285338,0.104068,0.207415,0.243050,0.556068,-0.860877,0.511564,-0.631433,-0.045763,-0.653100,0.024977,0.156060,0.602465,-0.044062,0.124156,0.273736,0.262766,-0.062345,0.219249,-0.137683,-1.031737,0.051229,0.246554,0.156057,-0.634710,0.520977,-0.093342,-0.112571,0.491398,-0.185244,-0.009108,0.622826,-0.025175,0.171692,0.107104,-0.072617,-0.668348,-0.026143,0.698701,-0.213349,-0.241121,-0.231236,-0.176607,-0.871000,0.029776,-0.602298,-0.317214,-0.274972,0.528794,0.130769,0.072592,0.660862,-0.870470,-0.205257,-0.551251,-0.427163,0.287029,-0.512073,0.117143,-0.670264,-0.285219,-0.192669,-0.117318,0.156934,0.033851,0.075375,1.004404,-1.045907,0.326010,0.428986,0.529182,-0.596120,0.285433,0.104533,0.478793,-0.002358,-0.329194,0.397924,0.382314,0.223446,0.194900,0.204637,-0.039226,-0.158890,-0.225727,0.386717', '1420088', '1793491', '24284209', '24750460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19955769', '失常', '喜剧', '鸡汤书籍《我该如何帮你去帮助他人》作者迈克尔·斯通（Michael Stone）来到辛辛那提，准备在一场大会上发表励志演说。这个面临中年危机的已婚男人邂逅了一位不善言辞的销售代理丽莎（Lisa），两人碰出了火花，由此展开了一段婚外情。', '大卫·休里斯', '查理·考夫曼', 7.4, 16686, 'tt2401878', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2293465626.jpg', 0.7, 4, 33.8, 45.3, 16.2, '0.282487,0.121017,-0.265736,0.259410,0.032288,-0.326330,0.345107,0.191480,-0.106684,-0.198151,0.465098,0.719144,-0.423636,0.080410,0.403898,-0.077635,-0.403376,-0.684019,0.451600,-0.093756,-0.332268,-0.360041,-0.203340,-0.099398,0.000764,-0.006673,0.344947,-0.099946,-0.323188,0.259442,0.411003,0.313819,0.027992,0.334155,0.034730,-0.142862,0.281993,-0.045657,-0.626073,0.523693,0.153668,-0.369774,-0.206424,0.037350,-0.168158,0.183277,0.608744,-0.017288,-0.100598,-0.052973,0.661039,-0.134764,0.294621,0.380262,0.205450,0.103358,0.135090,0.111752,-0.282732,-0.092829,-0.179823,-0.605175,-0.409594,-0.098195,-0.341460,0.412600,-0.649394,0.444951,-0.251175,-0.101635,0.152992,-0.185171,-0.181109,0.576684,0.385066,0.285091,-0.109875,0.003851,-0.129395,0.430463,0.737365,0.258981,-0.089988,0.366111,0.216117,-0.363046,-0.048109,0.006827,-0.451133,-0.041822,0.468671,-0.258887,0.006523,0.177956,-0.791648,-0.228181,-0.323600,-0.202028,0.071885,0.048943,-0.148427,-0.689533,-0.280769,0.263926,-0.092533,-0.201569,0.215735,-0.207541,0.904748,-0.643435,0.307603,0.322573,0.050258,-0.497908,0.439692,0.409277,0.394512,-0.349908,-0.128363,0.016700,-0.091578,0.107828,-0.016139,0.334937,0.305790,-0.075669,-0.276771,0.080977', '3811356', '27602116', '11541282', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19955789', '倒数第二次恋爱 2012秋SP', '剧情', '春夏交替过去，来到了秋天。吉野千明（小泉今日子 饰）的工作遇到了问题，制作的电视剧收视率一路走低，上司下了最后通牒，让千明制作其很不擅长的悬疑剧。而邻居长仓和平（中井贵一 饰）也被自己的后辈上司指派了颇为艰巨的任务——请知名作家向坂绿子作为镰仓的申遗形象大使。出乎意料的是，绿子老师答应了和平的请求，但条件是与其发生关系。和平为此烦恼不已，不知该如何抉择。而长仓一家的其它人，典子（饭岛直子 饰）、真平（坂口宪二 饰）、万里子（内田有纪 饰）也在各自烦恼或开心着，或家庭，或爱情，或工作。没有不会寂寞的大人，越是成长，受得伤越多。人生到了四、五十岁，成了别人口中“老朽”的人，坚持着一些在别人看来无需坚持的原则，但同样的，也成为了所珍惜的人眼中“帅气”的人。46岁的千明，51岁的和平，他们的故事仍在继续。©豆瓣', '小泉今日子 Kyôko Koizumi', '宫本理江子', 9.1, 7839, '', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1998695160.jpg', 0.2, 0.2, 6.8, 31.4, 61.4, '0.210656,-0.080119,-0.435355,0.403608,-0.195004,-0.193186,0.328332,0.278327,-0.487990,-0.374612,0.253399,0.673220,-0.019493,0.233727,0.235109,-0.071401,-0.115964,-0.337619,-0.039351,-0.125175,-0.226145,-0.414442,-0.003568,-0.241670,-0.300621,-0.075604,0.644850,0.159744,0.080995,0.306864,0.135328,0.267667,0.078063,0.369129,-0.049401,-0.019625,-0.022953,0.063874,-0.159552,0.020017,-0.108186,-0.363708,-0.233804,0.132192,0.152862,0.371707,0.666449,-0.212584,-0.380758,0.014160,0.386967,-0.315604,0.082487,0.102416,0.024325,-0.116168,0.259112,0.407725,-0.213360,0.109160,0.120499,-0.091282,-0.640555,0.043870,0.182751,0.363952,-0.448485,0.602435,-0.242998,-0.389648,0.029512,-0.475838,0.039992,0.315564,0.253356,0.314014,-0.358688,-0.014503,-0.525673,0.410793,0.751883,0.237891,-0.210927,0.321721,-0.301014,-0.586065,-0.224099,-0.598782,-0.567215,-0.074292,0.154881,0.149396,-0.134182,0.150843,-0.392167,0.029733,0.003431,-0.102704,0.021754,-0.394644,0.101161,-0.320427,0.073955,-0.620043,-0.410209,-0.009231,0.254929,-0.373547,0.918656,-0.836135,-0.085609,0.532649,0.262774,-0.405029,0.541858,0.455749,-0.009498,-0.101272,-0.033403,-0.100603,-0.162206,0.265922,0.146947,0.238189,0.127919,-0.365078,-0.287077,0.218363', '24284209', '27602116', '3445516', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19955790', '地狱为何恶劣', '剧情', '十年前，黑帮头目武藤（国村隼 饰）的老婆静江（友近 饰）为保护老公大开杀戒，锒铛入狱。转眼刑期将满，武藤无论如何希望实现老婆长久以来的梦想，那就是让他们的独生女美津子（二阶堂富美 饰）成为一名电影演员。但是拍摄期间美津子偷偷逃跑，刚愎的武藤还骂跑了专业摄影团队。关键时刻，美津子带着一名搞不清状况的路人桥本公次（星野源 饰）回来。根本没接触过电影的公次被逼担任导演职务，走投无路之际他求助于始终怀有电影梦想的超级影迷平田（长谷川博己 饰）。在此期间，武藤组的死对头池上组在老大池上（堤真一 饰）的率领下准备发动一场血腥的黑道战争。平田等人以此为蓝本，拍摄了一部虚实结合、癫狂暴乱的黑帮火并大戏！©豆瓣', '国村隼', '园子温', 7.6, 17202, 'tt2409302', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2158761043.jpg', 2.1, 5.7, 27, 41.1, 24, '-0.223477,-0.066148,-0.393835,0.319487,0.098141,-0.444815,0.203460,0.189324,-0.286880,-0.424935,0.299989,0.448680,-0.148989,-0.013029,0.323528,-0.082355,-0.137380,-0.528535,-0.072990,0.072984,-0.067658,0.012586,-0.244567,0.124876,-0.242453,-0.049187,0.781849,-0.008455,-0.136114,0.377765,0.535576,0.260338,0.079885,0.125225,0.479672,0.028074,0.129411,-0.065988,-0.330767,0.323524,-0.437982,-0.243212,-0.028898,-0.079449,0.000830,0.372729,0.582658,-0.138469,0.117355,-0.367551,0.263333,-0.433829,-0.218161,0.281300,0.316617,-0.033229,-0.026183,0.206334,-0.256153,-0.133224,-0.014454,-0.014562,-0.793060,-0.023719,0.130494,0.025712,-0.410789,0.122045,-0.155364,-0.206052,0.384317,0.008090,-0.047642,0.293863,0.309408,0.227283,-0.196648,0.304783,-0.327071,0.360856,0.451307,-0.205576,0.067798,0.213211,0.209127,-0.293839,-0.251647,-0.380657,-0.244232,-0.178403,0.008885,-0.243311,-0.129060,-0.134680,-0.375377,-0.072024,-0.011303,-0.023692,0.096870,-0.135426,-0.020917,-0.639626,0.120639,-0.207749,-0.042440,0.079356,0.102729,-0.256210,0.679046,-0.498606,-0.044391,0.614461,0.254535,-0.422213,0.468412,0.477262,-0.135555,-0.176849,-0.069372,0.061453,0.279382,0.471777,0.219000,0.238431,-0.167937,-0.350973,-0.054061,0.218580', '2369613', '3861846', '25880986', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19955828', '穿裘皮的维纳斯', '剧情', '故事发生在一间阴暗人稀的剧院之中，编剧托马斯（马修·阿马立克 Mathieu Amalric 饰）正在为他所改编的剧本《穿裘皮的维纳斯》寻找合适的女主角。接连面试的几位演员都令托马斯感到失望，她们和他脑海里完美的女神形象简直千差万别。面试以一无所获的结局结束了，正当托马斯准备离开之时，一位被淋成了落汤鸡的落魄女郎闯入了剧院。女郎名叫旺达（艾玛纽尔·塞尼耶 Emmanuelle Seigner 饰），巧合的是，她与托马斯剧本中的女主角同名，可是，旺达粗鲁的举止和浅薄的学识让托马斯在内心里暗暗的否定了她。令托马斯感到惊讶的是，旺达不仅拥有全部的剧本，还自备了戏服，在旺达的一再坚持下，托马斯同意了她想要试演的请求，并且亲自与她对戏。就这样，在瓢泼大雨之中，一场关于男人与女人、命令与服从的好戏拉开了帷幕。©豆瓣', '艾玛纽尔·塞尼耶', '罗曼·波兰斯基', 8.1, 44534, 'tt2406252', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2153298824.jpg', 0.9, 2.8, 18.5, 44.4, 33.5, '0.255303,0.071915,-0.706050,0.598199,0.014838,-0.214893,0.685619,0.096525,-0.440692,-0.345022,0.204772,0.838983,-0.594805,0.149944,0.603621,-0.092796,-0.446302,-0.790171,-0.404243,-0.100934,-0.046590,-0.485710,-0.231362,-0.128932,-0.103226,-0.294899,0.563279,0.079075,-0.196375,0.336219,0.592220,0.096651,-0.028430,0.461735,0.052425,0.032718,0.024319,-0.166459,-0.096894,0.177647,0.286156,-0.181629,-0.077940,0.337804,-0.014062,0.478002,0.625715,-0.469517,-0.216935,0.189023,0.445731,-0.128693,0.094044,0.311525,-0.025663,-0.005454,0.060367,0.160438,-0.174545,0.061948,0.146795,-0.031673,-0.776154,0.109459,0.188061,0.137144,-0.613673,0.408757,-0.206661,0.063208,0.171158,-0.358692,0.156652,-0.050432,0.490705,0.564637,-0.048998,-0.035800,-0.363446,0.241813,0.432171,0.380099,-0.168067,0.385121,-0.286808,-0.482915,-0.040658,-0.036715,-0.505674,0.114674,0.332533,0.099134,0.102768,0.089620,-0.594954,-0.182690,-0.270302,-0.204759,-0.186236,-0.498238,-0.095937,-0.640330,-0.131894,-0.122000,-0.213342,-0.137389,-0.021216,-0.280036,0.615485,-0.709519,0.043984,0.418845,0.257608,-0.236719,0.679598,0.097910,0.224636,0.028775,-0.038252,-0.025999,-0.003101,0.187672,0.217690,0.678217,-0.064517,-0.228915,-0.529149,0.424429', '30162520', '25928048', '1292925', '10763928');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19957083', '泰迪熊2', '喜剧', '为了巩固两人的婚姻，泰迪（塞思·麦克法兰 Seth MacFarlane 配音）和泰米琳（杰西卡·巴斯 Jessica Barth 饰）产生了要一个孩子的念头，在尝试了各种方法无果后，两人决定领养。然而，此时泰迪却发现政府并没有将他当做一个真正的“人”，而仅仅只是一份“财产”，因此，他不仅无法领养孩子，还丧失了身为一个“人”的所有公民权利——信用卡报废，工作泡汤，就连他和泰米琳的婚姻也成了一纸空文。愤怒的泰迪和好友约翰（马克·沃尔伯格 Mark Wahlberg 饰）商量之后，两人决定起诉，他们找到了新手律师萨曼莎（阿曼达·塞弗里德 Amanda Seyfried 饰）三人共同为争取“熊权”而展开了战斗。©豆瓣', '塞思·麦克法兰', '塞思·麦克法兰', 6.7, 97638, 'tt2637276', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233262892.jpg', 1.5, 10.6, 49.9, 27.7, 10.3, '0.302809,-0.129339,-0.664233,0.699671,-0.234645,-0.612902,0.641014,0.240198,-0.562615,-0.356449,-0.188552,0.827389,-0.113067,0.038202,0.263309,-0.073570,-0.589509,-0.886696,0.105089,-0.217863,-0.298671,-0.677804,0.059316,-0.480858,-0.244637,-0.074302,0.672716,-0.218400,-0.025390,0.292719,0.390679,0.138026,0.059197,0.499459,0.076168,0.209024,0.039806,-0.335703,-0.365990,0.368584,0.191875,0.115768,-0.163065,0.438550,0.057985,0.588275,0.646641,-0.218722,-0.019548,-0.158058,0.071012,-0.403929,-0.025150,0.199061,0.067880,-0.200166,0.337154,0.183514,-0.314936,0.020606,0.405117,-0.068765,-0.851015,0.084053,-0.208864,0.038714,-0.564675,0.621651,-0.097015,0.173675,0.003361,-0.424761,-0.035662,0.418520,0.166746,0.192310,-0.341800,-0.197906,-0.539348,0.160636,0.518377,-0.235738,-0.146558,0.490797,-0.269853,-0.446188,-0.192930,-0.181200,-0.330387,-0.178423,0.472282,0.472129,-0.266064,0.123884,-0.716300,-0.401986,-0.504411,-0.318893,0.132625,-0.651926,0.155801,-0.578186,-0.117117,-0.145727,-0.600522,0.047279,0.031244,-0.224645,0.648543,-0.901773,-0.029151,0.325129,0.291063,-0.538044,0.519326,-0.111416,0.405594,-0.341389,0.153913,-0.052609,0.063518,0.282827,0.510775,0.056767,0.183555,0.030317,-0.258352,0.448426', '1301022', '30345227', '4301278', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19961072', '盛夏的方程式', '剧情', '故事发生在一座名叫玻璃浦的海滨小镇上，帝都大学物理学副教授汤川学（福山雅治 饰）因公来到此处，入驻了名为“绿岩庄”的旅馆。在旅馆里，汤川结识了名叫恭平（山崎光 饰）的男孩，奇怪的是，平常一接近小孩子就会浑身起疹子的汤川今次尽然安然无恙，这让敏锐的汤川对恭平产生了兴趣。冢原正次（盐见三省 饰）的尸体被发现于岸边的碎石场上，他生前亦是绿岩庄的客人，为了寻找一名叫仙波英俊（白龙 饰）的杀人犯而来到玻璃浦。尽管冢原的死充满了疑点，但警方依旧判断，这只是一起意外坠落事件。为了调查事件的真相，岸谷美砂（吉高由里子 饰）随同僚们赶到了玻璃浦，让美砂感到奇怪的是，一向对案件避之而不及的汤川竟然主动请缨要求协助调查此事。©豆瓣', '福山雅治', '西谷弘', 7.4, 28515, 'tt2412556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1951819675.jpg', 0.2, 2.7, 36.1, 46.5, 14.5, '0.335506,-0.033463,-0.561105,0.373832,0.039870,-0.018292,0.510981,0.308951,-0.592297,-0.490294,0.117779,0.689769,-0.273936,0.301835,0.205295,0.036752,-0.186763,-0.422427,-0.232207,-0.214529,-0.413956,-0.468027,-0.091893,-0.370548,-0.188685,-0.102375,0.340456,0.319176,-0.242246,0.669590,0.332765,0.483303,-0.253493,0.431423,-0.025139,-0.012879,0.011149,0.269842,-0.024999,0.204915,-0.189395,-0.405604,-0.042453,0.285829,0.107831,0.578511,0.714872,-0.115168,-0.344427,0.016746,0.235191,-0.206506,0.170232,0.125525,0.546483,-0.005971,0.045019,0.254640,-0.410800,-0.140358,0.426084,-0.078251,-0.305903,0.061917,0.403117,0.229610,-0.362346,0.183347,-0.119184,-0.107577,0.045376,-0.214216,0.280059,0.097435,0.221883,0.208630,-0.113092,0.085212,-0.253280,0.035414,0.533399,0.098254,-0.129475,0.051894,-0.194382,-0.471705,-0.140569,-0.002410,0.087342,0.053581,0.108113,0.036335,0.036704,-0.056378,-0.497208,-0.328365,-0.044632,-0.126593,-0.082776,0.073934,-0.141196,-0.449135,-0.032854,-0.293459,-0.303851,0.241698,-0.039126,-0.061330,0.350304,-0.774416,0.110319,0.420164,0.093627,-0.312359,0.478913,-0.000824,-0.202856,-0.186834,-0.080882,0.150536,0.293345,0.322181,-0.034297,0.280427,-0.088508,-0.559338,-0.544271,0.127142', '1309194', '3263169', '1292219', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19962556', '真实', '悬疑', '威尼斯电影节参展电影，来自法国鬼才导演昆汀·杜飞的作品。电影描述一位导演寻找奥斯卡级别的“呻吟”的故事，真实与虚幻的交织，画面场景的轮回，真正的“烧脑电影”。', '阿兰·夏巴', '昆汀·杜皮约', 7.5, 7120, 'tt2392672', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2227378009.jpg', 2.1, 5, 28.3, 42.8, 21.7, '-0.197659,-0.202890,-0.397257,1.023188,0.730219,0.069571,0.786934,0.322884,-0.150595,-0.391906,0.631921,1.086706,-0.794117,0.121880,0.281741,-0.148116,-0.575820,-0.697974,-0.112785,0.138233,0.465391,0.168456,-0.663597,-0.113311,0.334361,-0.414642,1.179139,0.027102,-0.953653,0.056295,0.624771,0.158925,-0.484904,-0.313505,0.012678,-0.122163,0.610901,0.419489,-0.650474,0.241896,-0.062282,-0.092789,-0.269489,0.082881,-0.476382,-0.119398,0.783189,-0.312695,-0.035672,0.335885,1.058268,-0.235166,-0.284357,-0.293956,-0.541701,0.173805,0.543691,0.170506,0.439815,0.263731,-0.362183,-0.205503,-1.177095,0.090384,0.378287,0.498324,0.242056,-0.199270,-0.065865,0.225117,0.113346,-0.060616,0.493431,-0.229731,0.629506,0.506958,0.321486,-0.087145,-0.484185,1.215213,0.281248,0.423247,-0.509962,0.859713,-0.372536,-0.768959,-1.016110,-0.240142,-0.705040,0.786068,0.359178,-0.369206,-0.103552,0.279508,-0.643248,-0.204662,0.426485,-0.404140,-0.296459,0.076079,-0.058793,-1.414050,-0.550293,0.018465,0.058765,-1.204237,-0.001764,-0.211697,1.207126,0.000328,-0.165493,0.576197,-0.210232,0.057984,1.180838,0.273189,-0.573454,-0.565097,0.034832,0.330646,-0.188229,-0.292056,-0.377793,0.197283,-0.174950,-0.023163,-0.856499,0.834463', '26275494', '22265121', '30397916', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19962568', '洋妞到我家', '剧情', '文娟（徐帆 饰）和有志（陈建斌 饰）结婚多年，两人共同养育着可爱的女儿皮皮（陈一诺 饰），日子过得风平浪静。然而，有志在家中似乎越来越不管事儿了，于是，全部的重担和压力便都落在了文娟的肩头。文娟是过过苦日子的，为了不让女儿重蹈自己的覆辙，她决定将皮皮送往国外深造。为了帮助女儿学习英语，文娟请来了来自澳大利亚的互惠生娜塔莉（佳妮娜·阿拉纳·特拉诺瓦 Gianina 饰），供他吃住，以换取她对文文的辅导。一个典型的中国式三口之家，忽然多了一个洋妞，这日子过得可想而知，有些神经质的文娟和随性崇尚自由的娜塔莉之间发生了诸多的矛盾和冲突，这些冲突甚至影响到了整个家庭的和谐。©豆瓣', '徐帆', '陈刚', 5.9, 5243, 'tt8083810', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2192620730.jpg', 7.2, 19.5, 50.2, 17.1, 6, '0.535789,-0.318620,-0.679078,0.447558,-0.055501,-0.403064,0.579408,0.225779,-0.452087,-0.187159,0.001232,0.614860,-0.073520,0.364719,0.147167,-0.018420,-0.058117,-0.790364,0.060443,-0.020685,-0.208472,-0.413570,-0.165767,-0.036271,-0.222710,-0.421728,0.214563,-0.234748,0.102419,0.540682,0.248654,0.178929,-0.045324,0.387989,-0.377440,0.215108,-0.229373,0.266678,-0.325288,0.027952,0.181282,-0.039273,-0.278989,0.135996,0.399289,0.269509,0.623688,-0.202813,-0.162280,-0.039168,0.293124,-0.132996,-0.226234,0.202280,0.174235,0.025520,0.228603,0.386465,-0.419980,0.140616,0.264600,-0.145676,-0.639657,0.013937,0.161906,-0.011266,-0.794810,0.558436,0.120083,-0.442835,0.084188,-0.384966,0.272277,0.680778,0.010127,0.575412,-0.295021,0.220800,-0.372037,0.316865,0.717919,-0.103726,-0.256728,0.257884,-0.305152,-0.153260,0.138183,-0.287448,-0.554916,-0.194926,0.149240,-0.075539,-0.154753,0.413542,-0.647135,0.103813,-0.213794,-0.241689,0.145280,-0.453156,0.132023,-0.241983,-0.218407,-0.698879,-0.328774,0.116721,0.034487,-0.242044,0.892859,-0.771138,0.163336,0.453272,0.413954,-0.629227,0.468778,0.404416,0.428315,-0.015421,-0.207135,0.123325,-0.128735,0.154661,0.200906,0.410123,0.151306,-0.115118,-0.227581,0.420685', '1292219', '26730542', '26809007', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19962579', '201314', '爱情', '电影《201314》名字取意为“爱你一生一世”，是围绕着三对都市男女的奇妙爱情而展开的轻松浪漫的故事。失恋女温馨（金晨 饰）与闺蜜夜店疗情伤巧遇热情男温小固（郭晓然 饰），两人因“泼酒事件”开始了奇妙缘分，因同住一栋公寓的13层和14层在两人经历无数次让人啼笑皆非、甚至硝烟四起的非正式认识之后，两个生活节奏如此相似的人终于“相遇”了。御姐水灵儿（邵思涵 饰）因闺蜜温馨和温小固的奇妙缘分，结缘温小固的花心好友钱嘉乐（郭鑫 饰）。这两人因彼此的独特而相互吸引，最终因爱相互接受。温馨另一闺蜜爱情完美主义者的可爱女苗可（芷玄 饰），一直视男友周默（姜潮 饰）如珍宝，因未来两人出现感情危机，因爱再度牵手，因幸福明白爱的真谛。情窦暗生的年轻男女，花花公子的命中真爱，经历危机的浪漫情侣，生动描述了爱情的不同阶段，相遇、相识、相恋、相知、相守，为我们讲述千姿百态却同样感人的爱情……', '郭轩呈', '孔令晨', 4.2, 6961, 'tt6964088', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1814663838.jpg', 33.9, 33, 25.2, 4.5, 3.4, '0.343764,-0.008943,-0.697989,0.413984,0.243140,-0.068822,0.996674,-0.004953,-0.480226,0.004903,0.178305,0.465538,-0.567903,0.178470,0.427525,-0.071112,-0.008391,-0.704444,0.126363,0.150396,0.040016,-0.283192,-0.102866,0.099482,-0.002746,-0.219469,0.458393,0.370334,-0.029455,0.720423,0.353971,0.265209,-0.589885,0.136852,-0.130226,0.030667,-0.034045,0.622891,-0.784760,-0.307012,-0.355437,0.145245,-0.002926,-0.023840,-0.539713,0.203680,0.846557,-0.334533,-0.443246,-0.008051,0.628781,0.150085,-0.144955,0.169888,-0.118960,0.280139,0.475756,0.045959,0.009877,-0.052378,0.020610,0.001568,-0.590114,0.083666,0.235695,-0.058324,-0.049145,0.735508,0.081418,-0.309627,0.245367,0.083403,0.010967,0.228347,0.818504,0.520979,-0.097832,0.092981,-0.005603,0.261778,1.052152,0.128133,-0.448805,0.807556,-0.544117,-0.356935,-0.080947,-0.129883,-0.485607,0.188428,0.034558,0.231205,0.161037,0.315914,-0.853858,0.128748,0.088033,0.599583,0.280672,-0.666615,-0.179921,-0.451335,-0.435752,-0.744005,-0.527639,0.148156,-0.070000,-0.443634,0.771104,-0.663358,0.258854,0.383903,0.153369,-0.550508,0.855251,0.522651,-0.133937,-0.389343,-0.194276,0.725255,-0.408310,-0.334684,0.096476,0.337369,-0.249749,0.527889,-0.529468,0.205708', '27008393', '2365260', '2212281', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19962587', '夜莺', '剧情', '朱志根（李保田 饰）和崇义（秦昊 饰）虽身为父子，但彼此之间关系却十分淡漠，甚至到了互不理睬的地步。虽然倩影（李小冉 饰）几次想要调解公公和丈夫之间的矛盾却均以失败告终。与此同时，倩影和崇义之间的夫妻情谊亦因为繁忙的工作和缺少沟通而产生了裂痕。朱志根有一个未了的心愿，那就是把过世的妻子送给他的夜莺带回妻子长眠的那片土地，并且在妻子的坟墓上将夜莺放生。一番波折和意外之后，朱志根带着孙女任幸（杨心仪 饰）踏上了前往老家阳朔的旅途。这段旅途注定不会太平，接二连三的意外发生之后，这一老一小能否顺利的抵达目的地呢？©豆瓣', '李保田', '费利普·弥勒', 6.5, 7852, 'tt2976864', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204742842.jpg', 2.6, 13.7, 48.1, 26.8, 8.8, '0.263840,0.103131,-0.736216,0.509319,0.110084,-0.481056,0.660002,0.315483,-0.633278,-0.285232,0.177251,0.589637,-0.193660,-0.023525,0.250645,-0.365699,-0.086712,-0.581677,0.085795,-0.393243,-0.211095,-0.533271,-0.255749,0.127459,-0.144603,-0.249166,0.641286,0.214442,-0.051836,0.917540,0.149938,0.109947,-0.404985,0.595785,-0.139956,0.220405,0.016335,0.481227,-0.595998,-0.141337,0.070471,-0.192580,-0.082059,0.062524,0.084788,0.432068,0.770407,-0.340927,-0.338042,-0.029309,0.126048,-0.152393,0.067804,0.201194,0.308977,0.105357,0.373520,0.589150,-0.355801,-0.133991,0.195387,-0.027304,-0.586317,0.088366,0.120329,0.161348,-0.594244,0.658244,0.109312,-0.364660,-0.038024,-0.465660,0.370853,0.740377,0.337872,0.440287,-0.461873,0.151959,-0.382280,0.096716,0.872492,0.158625,-0.005945,0.288994,-0.176814,-0.407181,-0.048232,-0.134249,-0.345947,0.046777,0.344351,0.274759,-0.038634,0.270447,-0.482910,-0.043248,-0.306385,0.133712,0.164724,-0.492383,0.109808,-0.413735,-0.092446,-0.694772,-0.344165,0.141224,0.059244,-0.160788,0.413184,-0.658083,0.305452,0.135999,0.267749,-0.444067,0.628534,0.561113,0.401321,-0.571537,0.013082,0.036811,-0.086226,0.177571,0.188706,0.026783,-0.028661,-0.048287,-0.345597,0.129580', '3078390', '25721544', '25856453', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1996313', '死囚大逃杀', '动作', '杰克•康拉德（Stone Cold Steve Austin “响尾蛇”史蒂夫•奥斯汀 饰）原本是美国中部一座监狱里的死刑犯，在即将走上电椅的那一刻，他却被腐败的监狱长卖给一家电视台。该电视台制片人策划了一个新节目，他从世界各地遴选10位肌肉发达、动作敏捷且暴虐十足的死囚犯，将他们置身于海上孤岛中相互残杀，只有干掉其他对手坚持30个小时的人才有一线生机。整个搏斗过程通过摄像机全方位多角度传送到世界各地，嗜血如命的观众纷纷购买这个疯狂的真人秀。死囚中藏龙卧虎，杰克若想活命只有奋力搏杀……[背景] *光头佬男主角是WWE著名摔角手Stone Cold Steve Austin，他的地位成就与更早前从影的The Rock不相上下。如果从WWE专门为之定做重量级冠军腰带这件事来看，SCSA的成就实际要高于后者的。*WWE自成立电影部门以来，先后重点推出三位选手主演电影：1，Kane《魔影无踪》（See No Evil）；2，John Cena《海军陆战队》（Marine）；3，SCSA《死囚大逃杀》。从票房来看，《海军陆战队》最高，《魔影无踪》次之，《死囚》票房和风评都很差。而从投入与产出的比例来看，《魔影无踪》无疑为最大赢家。*死囚中有对夫妻档，男的是上世纪90年代中期活跃于WWE（当时还叫WWF）的摔角手Wildman。印象中此人最多就得过洲际杯冠军（比WWF冠军次一等），他的前女友Sable曾两次为PLAYBOY宽衣解带拍照，后来跟另一位比她小很多的摔角手结婚，其夫婿Brock Lesner曾为WWE冠军，后来主宾翻脸，Lesner辞职，转投自由搏击，效力于美国最大MMA组织UF', '史蒂夫·奥斯汀', '斯科特·维普', 6.2, 10032, 'tt0443473', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1244158622.jpg', 3.1, 16.8, 54.3, 19.6, 6.3, '-0.185240,-0.113204,-0.551592,0.592524,-0.099822,-0.095762,0.570422,0.023755,-0.483041,-0.150452,0.264674,0.912612,-0.226347,-0.099814,0.263055,-0.402417,-0.049800,-0.720675,-0.318101,-0.295114,-0.304830,-0.250460,-0.467652,0.117530,-0.240581,-0.097699,0.760891,0.040604,-0.331419,0.274859,0.410851,0.042092,-0.009374,0.137395,-0.336278,-0.323765,0.106891,-0.044117,-0.427143,0.415579,-0.187079,-0.134775,-0.116254,-0.060092,-0.014943,0.220219,0.509752,-0.091819,0.107922,-0.176610,0.406218,-0.095615,-0.308510,0.046923,0.367065,0.139455,0.361842,0.087626,0.070181,0.111869,0.028049,-0.366706,-0.797932,0.228138,0.026293,0.070388,-0.429939,0.271667,-0.252171,0.172701,0.043553,-0.014277,0.147892,0.165895,0.044332,0.209110,-0.051137,-0.012484,-0.411036,0.398003,0.675417,0.085945,-0.069817,0.019911,0.136567,-0.610482,-0.051650,-0.461671,-0.105608,0.056264,0.293622,-0.062458,0.049464,0.181661,-0.446141,0.231062,-0.035252,-0.253880,-0.035880,-0.179389,0.019385,-0.685550,-0.169787,-0.191606,0.086288,-0.041211,0.261369,-0.384367,0.731378,-0.796891,-0.001303,0.399058,0.342031,-0.434497,0.640541,0.040097,0.290936,-0.226864,-0.101290,-0.061741,0.188486,0.186059,-0.074503,0.262523,-0.040307,-0.469359,-0.200544,0.442514', '4301278', '25880986', '35262731', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19965431', '圣哥传', '剧情', '在平安度过世界末日的危机后，佛陀（星野源 配音）和耶稣（森山未来 配音）这两位圣者得到了难得的假期。他们相约来到岛国日本，体验人世间的春夏秋冬和喜怒哀乐。佛陀继续着自制T恤衫的爱好，耶稣则迷恋各种动漫电玩，为此常常令生活费趋紧。以大辅为首的三个淘气男孩将佛陀视作按钮星人欺负。耶稣在蒸桑拿时跟一个黑道中人相谈甚欢，被对方当成某个背景雄厚组织的少东家。虽然他们的行为举止有些格格不入，但给周围人带来各种惊奇体验的同时，也使邻里们感受到这两个“外国人”的纯真和热情。圣人再临，不经意间播撒着他们的正能量……本片根据中村光的同名漫画改编。©豆瓣', '森山未来', '高雄统子', 8.6, 9801, 'tt2431934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1900164085.jpg', 0.3, 1.4, 13.5, 39.3, 45.5, '0.310917,0.034884,-0.745736,0.629316,-0.154896,-0.084492,0.741327,0.208724,-0.384041,-0.239050,0.099686,0.755337,-0.416009,0.468678,0.335800,-0.158882,-0.338930,-0.643781,-0.363545,-0.056771,-0.208348,0.020697,-0.259211,-0.136168,-0.251085,-0.273302,0.394122,-0.054397,-0.224889,0.495329,0.072084,0.275095,-0.376281,0.359281,-0.428824,0.114279,0.048860,0.075007,-0.160549,0.118500,-0.255656,0.023457,-0.200053,0.233954,-0.219370,0.238956,0.730519,-0.387312,-0.309214,-0.086055,0.411201,-0.103839,-0.191917,0.209167,0.192511,0.117906,0.207280,-0.039859,-0.022926,0.151243,0.034061,-0.090071,-0.959423,-0.077003,-0.035915,0.263827,-0.331767,0.478602,0.223825,-0.300740,0.095626,-0.120023,0.302925,0.248348,0.269107,0.607483,-0.162745,0.020507,-0.373819,0.185379,0.655992,0.094546,-0.253880,0.244496,-0.382352,-0.253587,-0.000269,-0.187902,-0.361508,0.010051,0.153886,-0.002746,0.148723,0.362496,-0.953654,0.143157,0.235461,-0.140808,-0.017246,-0.463508,-0.090058,-1.048339,-0.053242,-0.629758,-0.298917,0.017818,0.400324,-0.228425,1.009658,-0.640490,0.131568,0.612479,0.134590,-0.351188,0.879415,0.075439,-0.096276,-0.361784,-0.408172,0.068894,0.307850,0.378036,0.148854,0.499345,-0.236995,0.150902,-0.258963,0.292669', '3318306', '25928048', '3811356', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19967839', '意外的恋爱时光', '喜剧', '单身女白领王乐晴（郭采洁 饰）对生活期望很高，希望早日与男友邵东（高圣远 饰）走上结婚的红毯。但卲东是个工作狂，常常因工作忽视了自己的存在，乐晴不得已主动向男友求婚，并请周同（房祖名 饰）拍摄她的求爱过程。搞视频工作室的周同愉快地接受了聘请，随乐晴踏上了求爱旅程，谁知一路上意外频发，囧事不断。随着同甘共苦的行程加码，周同对乐晴产生了异样的感觉。大龄剩女李晓玲（于莎莎 饰）是乐晴的闺蜜，平日里嘴上没有把门儿的，属于典型的刀子嘴豆腐心，她以乐晴的爱情导师自居，对乐晴找对象看的比自己的事都重要，但她将怎样面对乐晴的婚变呢......©豆瓣', '房祖名', '黎志', 5.6, 23065, 'tt3209682', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2156480713.jpg', 6.6, 26.4, 50, 13.2, 3.8, '0.444569,-0.089834,-0.307995,0.451104,0.013028,-0.099274,0.567323,0.169973,-0.358718,-0.249622,0.034289,0.551490,-0.303727,0.059965,0.078269,-0.070735,-0.125487,-0.577001,-0.004439,0.174750,-0.202864,-0.315406,-0.014822,0.099072,-0.247226,-0.105953,0.508429,-0.078964,-0.248643,0.557643,0.370871,0.061778,0.125408,0.480966,-0.041264,-0.054443,0.031458,0.428208,-0.203428,-0.007241,0.119363,-0.125174,-0.090955,0.208257,0.081723,0.428553,0.500347,-0.017682,-0.141164,0.153241,0.465703,-0.245087,-0.042513,0.268271,0.001030,0.158869,0.249803,0.224784,-0.085421,-0.176090,0.212894,-0.070154,-0.467031,0.035292,0.113750,0.048574,-0.586773,0.482915,-0.175389,-0.121310,0.315064,-0.251140,0.031869,0.155825,0.280120,0.419926,-0.167820,0.218722,-0.311186,0.333890,0.428801,0.219758,-0.120486,0.635447,-0.307918,-0.339038,-0.019962,-0.068906,-0.716901,0.009102,-0.089505,-0.008944,-0.171968,0.101594,-0.288655,-0.093934,-0.071832,-0.122225,0.042885,-0.499762,-0.072611,-0.508482,-0.083223,-0.541683,-0.316635,-0.154337,0.000411,-0.500001,0.544282,-0.644459,-0.023606,0.516519,0.238180,-0.812089,0.946567,0.445461,-0.125649,-0.427886,-0.128637,0.152907,-0.199484,0.022205,0.150462,0.280021,-0.027015,-0.319330,-0.283620,0.441422', '5374383', '1470865', '1917323', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19969446', '20岁的差距', '喜剧', '爱丽丝·朗丹（维尔日妮·埃菲拉 Virginie Efira 饰）是一个38岁的单亲妈妈，她很漂亮而且上进，但是在前夫眼里她很无趣，因此她全身心寄情于杂志社的工作。爱丽丝本来有资格成为下一任主编，可是上司和同事纷纷觉得她的形象太老气和刻板，无奈的她心灰意冷。一次坐飞机途 中，她巧遇了刚满20岁的年轻帅小伙巴尔塔扎（皮埃尔·尼内 Pierre Niney 饰），两人在一起的时候被同事看见并误会她搞起了时髦的姐弟恋，因此他们对她的态度也转变了。爱丽丝觉得这个意外是她升职的关键，于是主动开始了勾引巴尔塔扎的计划，本是无心的相遇却变成了愈演愈烈的纠葛。©豆瓣', '夏尔·贝尔林', '大卫·莫罗', 6.8, 13409, 'tt2186812', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1883432800.jpg', 0.7, 7.3, 52.2, 30.5, 9.4, '0.689097,-0.002909,-0.745852,0.465745,-0.487672,-0.273260,0.665540,0.130044,-0.600514,-0.148425,0.099536,0.923339,-0.398673,0.475675,0.324330,0.204959,-0.203126,-0.720015,0.204147,-0.120318,-0.002513,-0.501626,-0.123800,-0.080312,-0.192352,-0.154271,0.451612,-0.014758,-0.079556,0.624506,0.354562,0.315328,0.358164,0.678549,-0.181309,-0.002449,0.107775,-0.132769,0.207620,0.020171,0.148872,-0.218458,-0.024214,0.426833,0.035340,0.656635,0.417283,-0.116659,-0.217373,0.070223,0.522396,-0.245477,-0.086724,0.298588,0.373933,0.029369,0.190012,-0.059178,-0.137485,-0.093247,0.077336,-0.077217,-0.508222,0.303536,0.034686,0.222693,-0.666997,0.593296,-0.048207,-0.124666,0.072207,-0.380107,0.041274,0.247507,0.255549,0.215411,-0.196258,0.018854,-0.428747,0.101043,0.775482,0.197193,-0.269047,0.554046,-0.240221,-0.357801,-0.030233,-0.146020,-0.443728,-0.021115,0.085251,-0.168610,-0.132232,0.113050,-0.490979,0.038363,-0.192469,-0.002640,-0.237115,-0.352025,-0.036642,-0.182403,-0.180979,-0.727924,-0.546554,-0.108739,-0.076185,-0.345346,0.510396,-0.844177,0.003302,0.432080,0.352138,-0.593246,0.843254,0.302927,0.015651,-0.197770,-0.061835,0.189085,-0.341075,0.025769,0.291727,0.423096,0.072686,-0.266535,-0.244474,0.492395', '1302384', '1308755', '3111650', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19971676', '黑衣人：全球追缉', '喜剧', '全球最具影响力的经典科幻IP《黑衣人》全面升级！科幻电影之父史蒂文·斯皮尔伯格联手《速度与激情8》导演F·加里·格雷，金牌班底鼎力巨献！英国黑衣人总部王牌探员H（锤哥）与新晋探员M（泰莎·汤普森）在阻止外星团伙入侵的过程中意外铲除了隐藏在黑衣人组织中的内奸，成功拯救世界 。影片中，各种脑洞大开的外星人和颠覆想象的高科技装备轮番登场，热血沸腾惊心动魄的动作追车场面层出不穷，完美构建出全新的黑衣人宇宙观。本片将于2019年6月14日内地同步北美上映。', '克里斯·海姆斯沃斯', 'F·加里·格雷', 5.5, 159586, 'tt2283336', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2558701068.jpg', 5.4, 29.9, 51.9, 10.2, 2.5, '-0.212237,0.101775,-0.570079,0.295480,0.472098,0.261036,0.511917,-0.381053,-0.607678,-0.006821,0.232107,0.371171,-0.550553,-0.341131,0.616481,-0.513108,-0.383632,-0.730535,-0.280823,-0.100308,-0.056879,-0.279050,-0.721071,-0.490412,0.031510,-0.732388,0.864909,0.206416,-0.586670,0.151364,0.094369,0.104139,-0.399573,0.105890,0.289529,-0.111471,0.409089,-0.410885,-0.780025,0.336459,-0.369456,-0.207937,-0.127276,0.168385,-0.389178,-0.101535,0.636243,-0.431047,0.289368,-0.191528,0.507433,-0.191543,-0.523592,-0.227977,0.222024,0.203987,0.077269,0.276431,0.456133,-0.146833,-0.132019,-0.368922,-0.896861,0.178122,0.293774,0.004112,-0.329996,0.267872,-0.442260,0.328309,0.104174,-0.139819,-0.002326,-0.079262,0.844342,0.450860,0.127265,0.351594,-0.184323,0.393532,0.292882,0.044034,-0.516436,-0.033548,0.065019,-0.526494,-0.438591,-0.485792,-0.111752,0.138740,0.421065,-0.115073,0.089981,0.545043,-0.597969,0.142959,-0.303788,-0.238564,-0.124327,-0.127774,-0.064389,-1.297172,-0.149023,0.016004,0.138141,-0.034849,0.232201,-0.181740,0.893775,-0.440957,-0.095289,0.486856,0.339600,-0.141452,0.511550,-0.272242,0.152641,-0.339227,-0.409699,-0.018391,0.123542,0.134638,-0.085532,0.370312,-0.233451,-0.147293,-0.072425,0.090602', '4014397', '3318306', '2369613', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19973312', '唐顿庄园：2012圣诞特别篇', '剧情', '特别篇开始，Mary（米歇尔·道克瑞 Michelle Dockery 饰）已经怀孕，一家人到苏格兰Rose家度假，留在庄园的Tom（艾伦·里奇 Allen Leech 饰）在Isobel和新女仆Edna的劝说下和众仆人打成一片，令管家Carson（吉姆·卡特 Jim Carter 饰）颇为头痛。没有了主人的仆人们似乎生活更加轻松和随意。众人一起去了集市，而Jimmy对Thomas（罗伯·詹姆斯-克里尔 Rob James-Collier 饰）的态度也有所好转。杂货店老板Joss似乎对Patmore太太有着别样的感情。Gregson为了让Crawley一家接受他对Edith（劳拉·卡尔迈克尔 Laura Carmichael 饰）的感情也来到了Rose家，而Robert（休·博内威利 Hugh Bonneville 饰）发现老友一家似乎也面临了财政问题。终于，Mary平安生下儿子，Matthew（丹·史蒂文斯 Dan Stevens 饰）去医院看望完妻儿，欣喜地向家人报喜时，他的车不幸与一辆货车相撞......', '休·博纳维尔', '安迪·戈达德', 8.2, 32969, 'tt2385306', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2169836747.jpg', 1.2, 1.9, 18.2, 42, 36.6, '0.191782,-0.142023,-0.581011,0.302731,0.025600,-0.582933,0.791352,0.604909,-0.673203,-0.285519,0.176258,0.783061,-0.091671,0.232488,0.502087,0.059924,-0.532395,-0.341683,0.223508,-0.089558,-0.261785,-0.456648,0.340979,-0.442630,-0.051066,-0.410532,0.153871,0.025852,0.290784,0.773265,0.085018,0.370750,0.016013,0.523881,-0.180781,0.246242,0.173871,0.044516,-0.523092,0.120221,0.225597,0.063511,-0.296679,0.195647,0.414854,0.312723,0.652684,-0.012918,-0.210219,0.152138,-0.045703,0.175838,0.278574,0.209797,0.221972,0.004838,0.065392,0.204368,-0.370047,0.104173,0.047863,-0.013689,-0.377735,0.353395,0.059337,-0.060551,-0.646606,0.347735,-0.211025,-0.176373,0.008185,-0.362056,0.370083,0.326025,0.096835,0.507824,-0.230363,0.196642,-0.513878,-0.239579,0.592725,-0.053469,0.125872,0.399107,-0.270500,-0.128097,0.031788,0.018589,-0.534677,-0.074530,0.272517,0.159735,0.006227,0.068885,-0.544894,-0.221125,-0.404500,-0.306213,0.126597,-0.494771,0.109896,-0.752252,0.050436,-0.394569,-0.296177,-0.019912,0.207917,0.089598,0.491141,-0.737540,0.210516,0.141616,0.284229,-0.537813,0.555291,-0.151179,0.139296,-0.421963,-0.206318,0.129171,0.053111,0.278