INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19973780', '菲洛梅娜', '剧情', '1952年的爱尔兰，社会风气保守。少女菲洛米娜（朱迪·丹奇 Judi Dench 饰）因未婚怀孕，被家人送往修道院从事苦役，每天只有1小时与爱子安东尼相处。在安东尼3岁的时候，他被修女们强行抱走，送往美国寄养家庭。此后整整五十年菲洛米娜都沉浸在对爱子的思念中。她将故事告诉了一位记者马汀（史蒂夫·库根 Steve Coogan 饰），后者决定与她一同踏上寻子之旅。这对个性迥异、看似不可能成立的搭档，在希望与失落之间，展开的不只是慈母寻子的冒险，更是跨越友谊的见证。菲洛米娜慢慢了解到儿子不平凡的一生和鲜为人知的秘密，她这份迟来的爱能传递到失散多年的安东尼身上吗？《菲洛梅娜》改编自 BBC记者马汀·斯克斯史密斯的纪实文学《菲洛梅娜遗失的孩子》，取材自真人真事。电影围绕一位母亲半个世纪后的跨海寻子，用喜剧的外观包装悲剧故事，让人在笑泪交织中收获感动，并且给予同性恋、艾滋以及恐同话题以恰如其分的重量。《菲洛梅娜》获得威尼斯电影节最佳剧本奖和LGBT最高荣誉断背狮奖，此外还得到了包括最佳影片在内的4项奥斯卡提名。', '朱迪·丹奇', '斯蒂芬·弗雷斯', 8.4, 26243, 'tt2431286', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2119792764.jpg', 0.2, 0.7, 12.9, 52.4, 33.8, '0.122510,-0.127420,-0.695058,0.535142,0.090684,-0.214596,0.634028,-0.076756,-0.490015,-0.049381,0.175549,0.794945,-0.293451,0.181143,0.453651,-0.070741,-0.412496,-0.739586,-0.133830,-0.240431,-0.247068,-0.520125,-0.147398,-0.121957,-0.279581,-0.440108,0.723212,0.085654,-0.041281,0.490656,0.236278,0.302971,-0.097033,0.220993,-0.182831,0.203163,0.109932,0.053999,-0.335943,0.342716,0.154421,-0.112631,0.018347,0.047083,-0.028934,0.284014,0.737868,-0.303558,0.049531,-0.013879,0.312353,-0.220469,-0.145331,0.063291,0.061310,0.118899,0.309043,0.406828,-0.225759,0.008725,0.149988,-0.367946,-0.631674,-0.013795,0.283856,0.247184,-0.598196,0.476504,-0.245101,-0.012633,0.160877,-0.117181,0.092542,0.264173,0.246353,0.489974,-0.115462,0.118828,-0.263621,0.358029,0.568292,-0.132436,-0.234692,0.291846,-0.349623,-0.471599,-0.070962,-0.298144,-0.496089,0.139085,0.098326,0.134015,0.131989,0.350896,-0.435232,-0.161217,-0.137803,-0.110632,0.164356,-0.527011,-0.064444,-0.438316,-0.150712,-0.373352,-0.176014,-0.043949,0.285802,-0.378157,0.807854,-0.487468,0.345599,0.298436,0.228615,-0.355781,0.818646,0.134009,0.145781,-0.399938,-0.029472,0.498092,-0.017729,0.028828,0.129045,0.092062,-0.126501,-0.059420,-0.437536,0.362550', '1292001', '30162520', '1303034', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19973815', '分手合约', '爱情', '父母亡故的何俏俏（白百合 饰）得到同班同学李行（彭于晏 饰）加倍关怀，两人逐步成了一对青梅竹马的恋人。毕业前夕，李行向俏俏求婚，不料竟被她用“没有达到她想要的物质条件”为理由，狠心地拒绝了。双方在此前提下彼此立下“5年后若单身就结婚”的合约。俏俏远走上海，自尊心受挫的李 行则留在北京打拼。春去秋来，5年之后，俏俏满心以为痴情男李行依然记得当年的约定，两人可以再续前缘，怎料却得知李行要和自小在法国长大的白富美周蕊（吴佩慈 饰）结婚的消息。倍受打击又不甘心的俏俏只有求助于“无敌GAY蜜”毛毛（蒋劲夫 饰），准备联手把李行再次夺回来。到底李行和俏俏的感情在五年后是否还有回旋的余地？©豆瓣', '白百何', '吴基桓', 5.8, 166104, 'tt2910520', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1916743333.jpg', 7, 24, 47.3, 16.2, 5.6, '0.110266,0.164717,-0.605414,0.408597,-0.036290,-0.542731,0.272681,0.047526,-0.424995,-0.098752,-0.250733,0.441502,-0.199434,0.325175,0.026070,-0.104805,-0.199071,-0.737105,0.085754,-0.066998,-0.103630,-0.378347,0.067379,0.193850,-0.129249,-0.025201,0.638691,-0.065768,0.059542,0.460381,0.266396,0.026999,-0.018250,0.333830,-0.355113,0.339708,-0.030084,0.378402,-0.677284,0.289421,0.160715,-0.170394,-0.282849,-0.069792,0.171021,0.214635,0.560925,0.011760,-0.174090,0.013221,0.453138,-0.074137,0.015567,0.309394,0.138949,0.004176,0.359435,0.265684,-0.397398,0.116986,0.316853,-0.030371,-0.396526,0.134408,0.275629,-0.162171,-0.643428,0.573647,-0.112298,0.065599,0.148468,-0.531584,-0.113276,0.622833,0.173682,0.334619,-0.484861,0.152103,-0.465243,0.202081,0.711779,0.157466,0.110679,0.252552,0.166571,-0.523309,-0.004267,-0.001747,-0.470978,0.142645,0.232087,0.285661,-0.230699,0.100667,-0.302253,-0.273164,-0.208168,0.308939,0.208339,-0.426425,-0.219937,-0.279073,-0.236024,-0.575381,-0.373573,0.385470,0.156561,-0.312843,0.474218,-0.829420,0.201928,0.023003,0.551367,-0.619520,0.612111,0.418547,-0.038445,-0.356580,0.205021,0.257137,-0.170818,-0.141187,0.324064,0.193997,0.024766,0.042807,-0.076223,0.283738', '30345227', '1301022', '1300553', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19975090', '金刚王：死亡救赎', '剧情', '金刚王（释延能 饰）有这一段悲惨的童年遭遇，年幼的他遭奸人拐卖，被卖到了日本的哈迪斯神社，在那里，等待着金刚王的，是充满了鲜血和汗水的残酷训练，目的只有一个，那就是将他塑造成为令人闻风丧胆的冷酷杀手。金刚王成功了，练就了一身技艺的他最终成为了组织内部的第一杀手，之后，金刚王借机逃回中国，并遇见了南少林宗师，放下屠刀立地成佛。没过多久，哈迪斯组织就在南少林的脚下建立起了一座高大的客家土楼，在那里，有着三个传说级别的擂台，各地高手汇聚于此，一争高下。然而，日方真正的意图，其实是从精神上摧毁中国人民抗日的意志和信心。得知此事，金刚王挺身而出，与自己的东家为敌，走上了擂台。©豆瓣', '释彦能', '罗永昌', 5.5, 5205, 'tt3259968', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2141185978.jpg', 11.1, 27.5, 42.7, 13.2, 5.5, '0.035756,0.363817,-0.810324,0.646872,-0.138775,-0.166231,0.507311,0.076138,-0.526592,-0.293050,0.262065,0.792376,0.012888,0.134737,0.049756,-0.285732,0.225073,-0.575779,-0.386029,-0.040043,-0.346214,-0.090812,-0.437943,-0.131345,-0.199639,-0.318817,0.727366,0.305330,-0.480637,0.262752,0.418390,0.374398,0.143202,0.250325,-0.377327,0.034317,-0.070935,-0.048139,-0.131527,0.237677,-0.223198,-0.330345,-0.083963,0.070991,-0.315190,0.253158,0.498045,-0.449885,-0.126357,-0.245482,0.389930,-0.524410,-0.155840,0.322550,0.482907,-0.126413,-0.005899,0.194125,0.004523,-0.172799,0.176992,-0.186940,-1.072383,-0.364660,0.196772,0.069592,-0.733681,0.530153,-0.171036,-0.184346,-0.094768,-0.280938,0.334869,0.408923,0.092096,0.192560,-0.043117,-0.143763,-0.668117,0.220773,0.894257,0.094329,-0.163576,-0.194409,0.084384,-0.518418,-0.291242,-0.525069,0.049959,-0.150908,0.556387,-0.130273,0.020650,0.124003,-0.634893,-0.250238,-0.275146,-0.093587,0.007757,-0.307272,-0.064724,-0.443977,-0.265857,-0.409462,-0.213954,0.051640,0.120091,-0.195279,0.899839,-1.029486,0.153391,0.266086,0.157987,-0.357076,0.676648,-0.100042,0.131037,-0.148365,-0.004826,0.162492,0.123165,0.569947,0.249235,0.621439,-0.263491,0.047383,-0.467266,0.584560', '1793491', '30163500', '27602116', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19976058', '念书的孩子', '剧情', '爸妈去城里打工，家里由爷爷照顾九岁的开开上学和生活。开开捡了一只流浪狗，取名叫小胆儿。小胆儿胆子特别小，平时不敢叫唤，爷爷以为它是哑巴狗。小胆儿很聪明，开开让干啥小胆儿就干啥，开开走一步它就跟一步，生怕再走丢了。小胆儿成了开开最好的朋友。爷爷有肺心病，拖垮了家里的经济，为了吃药，连有线电视费也不交了。开开放学没事干，爷爷怕开开空虚，就哄着开开念课文。今天的课念念，昨天的课巩固巩固，明天的课预习预习。爷爷并不在意开开念得对与错，只要能让开开有事干就行。开开每次念书的时候，小胆儿就很捧场，坐在爷爷的鞋子上认真地听。老师开始表扬开开了，说开开的书念得好，作文也写得好，将来一定能考上研究生甚至是博士生。开开念书更起劲儿了，念完了课内念课外，念完了岳飞念三国。有一天，小胆儿突然叫起来，还咬着开开的裤脚往爷爷屋里拽。开开连忙跑过去，却发现爷爷躺在床上没有了呼吸。开开的父母回来安葬了爷爷，要带开开进城。开开不想走，说班里的吴美芳进城半年都没有找到学校，前几天又回来了。开开要念书，不想进城。开开的爸爸在城里打工，住的是工棚。妈妈在城里当保姆，住的是雇主家。开开要是进城还真没地方住。城里上学的条件太不成熟，但在农村还可以。开开跟爷爷学会了做饭，蒸馒头擀面条都会，吃饭穿衣不是问题。最让开开爸妈担心的是，万一晚上开开有个病啥的，连个知道的人都没有。于是开开爸去找开开的老师。王老师说，白天开开自己吃饭，晚上可以睡在老师家，问题都得到了解决。把一个九岁的孩子留在家，别人不说啥，开开妈自己也舍不得。开开妈说，咱还是把孩子带走吧，要不我留下来。开开爸说，不是咱不带他，是他自己不愿走。再说学习是一辈子的大事，', '江化霖', '原雅轩', 8.7, 10907, 'The Reading Boy', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2461375551.jpg', 0.4, 1.3, 10.5, 40.6, 47.3, '0.279302,-0.324176,-0.281116,0.063163,-0.667413,-0.588149,0.199442,0.034589,-0.182283,-0.027512,-0.761748,0.110714,0.096116,0.494368,-0.152193,0.057943,-0.294845,-0.270706,0.325814,-0.088203,-0.200361,-0.305019,0.390813,0.002506,0.027751,-0.081993,-0.021188,-0.496733,-0.115012,-0.082822,-0.120369,-0.484601,0.390430,0.077492,-0.597485,0.150389,-0.572181,0.232535,0.257438,0.196995,0.556395,-0.239900,-0.306843,-0.360578,0.878237,0.057536,-0.012481,0.084940,-0.272093,0.279600,-0.172268,-0.177803,-0.215467,0.106208,0.170601,-0.348602,0.644698,0.066558,-0.091336,0.291342,-0.138202,-0.110678,-0.217648,0.191305,-0.135146,-0.144058,-1.011918,0.338765,0.057252,-0.014135,0.244864,-0.608687,0.562921,0.424141,-0.107464,0.573839,-0.107115,0.156011,-0.766322,0.050702,0.621430,-0.440917,0.378783,0.202409,0.179592,0.273772,0.479689,0.012605,-0.566887,0.094257,-0.033006,-0.121631,-0.435607,-0.397934,-0.183574,0.079452,0.125992,-0.450990,0.027042,-0.403245,0.079515,0.182835,0.253233,-0.167889,-0.152848,0.301370,0.205423,-0.187981,0.579118,-0.636463,0.237421,0.306605,0.664059,-0.397259,0.839554,0.364455,-0.071553,-0.050623,0.214241,-0.510524,-0.212697,0.490344,0.366694,0.497393,0.331952,-0.421393,-0.299407,0.304276', '2138300', '26596361', '25876760', '1306505');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19976260', '末日浩劫', '科幻', '时为2013年，世界各地突然被死神的阴影所笼罩。凡是身处开放空间的人类，无一例外将丧失宝贵生命。外表俊朗的马克（奎姆·古铁雷兹 Quim Gutiérrez 饰）是一条生活在巴塞罗那的苦闷程序狗，上司埃里克（José Coronado  饰）不近人情的苛刻要求压得他早已喘不过气来，而与美丽女友朱莉娅（玛塔·埃图 娜 Marta Etura 饰）的关系似乎也进入了瓶颈期。灾难降临后，马克和其他人被困在某栋建筑物内长达三个月。担心女友的安全，他决定铤而走险离开这个绝地。马克与持有GPS的埃里克携手，穿越重重危险向外行进。繁华的大都市，人们却早已习惯自我囚禁在隔绝的空间内，而宁愿丧失与他人交流的能力。幡然醒悟，为时已晚……©豆瓣', '基姆·古铁雷斯', '大卫·帕斯特尔', 5.8, 3955, 'tt1935914', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2217080836.jpg', 7.5, 22.3, 48.8, 16.2, 5.1, '0.156797,0.304204,-0.575404,0.433005,-0.101237,-0.176432,0.843261,0.186213,-0.413062,-0.254688,0.356353,0.573492,-0.162872,-0.020365,0.185884,-0.097938,-0.229496,-0.555458,-0.026123,-0.317297,-0.292359,-0.363171,-0.291317,-0.168300,-0.197848,-0.567455,0.793270,0.184232,-0.161478,0.233267,-0.017957,0.174572,-0.244413,0.586133,-0.088911,-0.134804,-0.017150,-0.141731,-0.329317,-0.093211,-0.383053,-0.073290,0.091051,0.072700,0.104975,0.260899,0.699368,-0.424182,-0.259977,0.038004,0.439519,-0.359124,-0.107516,0.339995,0.244705,-0.235135,0.073579,-0.016371,-0.219206,0.122849,0.034752,-0.334125,-0.760601,0.082704,-0.007602,0.014912,-0.320188,0.397510,0.080516,-0.162598,-0.105556,-0.272808,-0.091824,0.119745,0.135298,0.391104,-0.145765,0.033107,-0.354875,-0.152980,0.618739,-0.268837,-0.627222,0.242740,-0.503242,-0.424395,-0.524317,-0.170607,-0.532552,-0.181576,0.317078,0.300257,-0.147136,0.349047,-0.621486,0.047343,-0.282300,-0.087238,-0.203376,-0.357660,-0.341087,-0.505032,-0.156314,-0.376402,-0.211738,0.148892,0.076726,-0.205147,0.349770,-0.681388,0.416100,0.522037,0.360322,-0.432062,0.734522,-0.050506,0.236746,-0.253477,-0.030878,0.898065,-0.083318,0.473654,0.037516,0.294129,-0.199177,0.187199,-0.365248,0.520245', '3718279', '3097044', '1291835', '35287908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19976774', '锡尔斯玛利亚', '剧情', '玛利亚（朱丽叶·比诺什 Juliette Binoche 饰）是一名十分出色的演员，凭借“西格德”这一角色一举成名。在剧中，西格德野心勃勃，全身上下充满了致命的吸引力，她的行为直接导致了名为海琳娜的角色的自杀，是一出惊为天人的悲剧。如今，玛利亚已经四十多岁了，命运让她再度站在了舞台之上，只是，这一次，她不再是性感致命的西格德，而变成了悲剧的化身海琳娜。饰演西格德的是一位名叫艾莉丝（科洛·格蕾斯·莫瑞兹 Chloe Grace Moretz 饰）的新生代演员，她的个性狂放不羁，常常惹是生非，饱受非议。在入戏的过程中，玛利亚在艾莉丝的身上看到了曾经的自己，引发了她深深的思考。©豆瓣', '朱丽叶·比诺什', '奥利维耶·阿萨亚斯', 7.7, 19366, 'tt2452254', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2193155170.jpg', 0.5, 2.6, 27.2, 50, 19.6, '0.529094,0.222227,-0.879175,0.797626,-0.021954,-0.248488,1.002859,0.336754,-0.534439,-0.171897,0.447341,0.859627,-0.373624,0.128515,0.369142,-0.003000,-0.205320,-0.698399,-0.254747,-0.029369,-0.467565,-0.411988,-0.522955,-0.172975,-0.242645,-0.747624,0.613196,-0.079437,-0.317449,0.312509,0.751271,0.878551,0.378795,0.397425,-0.053822,0.250571,0.047088,-0.293100,-0.017962,0.434087,0.181876,-0.368255,-0.408285,0.412132,-0.383390,0.388390,0.621127,-0.298723,-0.040188,-0.086681,0.441860,-0.546999,0.034241,0.039807,0.153815,-0.560445,0.219921,0.124702,-0.279759,0.031997,0.193105,-0.011890,-0.855368,-0.064396,0.217732,0.523776,-0.569422,0.557052,-0.193727,-0.229530,0.184153,-0.074306,-0.196701,-0.053936,0.219347,0.329327,-0.005063,-0.022233,-0.436481,0.195677,0.644111,0.453294,-0.592149,0.706830,-0.211160,-0.361480,-0.445581,-0.393001,-0.563694,0.069885,0.408938,0.062106,-0.091727,0.459901,-0.685809,-0.152035,-0.397861,-0.031479,-0.119027,-0.303497,-0.212493,-0.630176,-0.477265,-0.690473,-0.451985,-0.073311,-0.259791,-0.191541,0.806426,-0.839713,-0.044988,0.520113,-0.203775,-0.262659,0.727277,-0.004124,-0.008110,-0.018791,-0.124860,0.230189,0.075248,-0.021126,0.226599,0.611221,-0.024996,-0.123724,-0.444235,0.854832', '30162520', '25763555', '35158375', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1997679', '木乃伊3', '动作', '1947年，中国宁夏。中国两千年前的始皇帝：龙帝之墓在此挖掘出土。同时在美国，大探险家欧康诺（Brendan Fraser饰）与夫人伊芙琳（Maria Bello饰）应邀，将传说中能带来永生的宝石“香格里拉之眼”送往中国，以示中美两国人民友谊长存。不料，国民党军官（黄秋生饰）却和博物馆馆长勾结，当场抢走香格里拉之眼，继而唤醒了两千年前的邪恶力量——龙帝（李连杰饰），此时的龙帝不仅可以借助五行之力施暴，还可以变身为各种怪物涂炭天下生灵。欧康诺一家奋力与龙帝和他身后庞大的兵马俑队伍展开战斗，千年圣女紫媛（杨紫琼饰）与其女林娜（梁洛施饰）也入盟此支神圣的队伍，以期消灭龙帝，还世界以和平。©豆瓣', '布兰登·费舍', '罗伯·科恩', 5.7, 107164, 'tt0859163', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2165575576.jpg', 7.4, 25.9, 48.2, 13.5, 5.1, '-0.178896,0.534681,-0.679602,0.654457,0.208618,-0.024478,0.534291,-0.148138,-0.303888,-0.123363,0.083642,0.465169,-0.004812,0.084716,0.180085,0.228351,-0.091770,-0.633847,-0.219714,0.069229,-0.016313,-0.065435,-0.668595,0.002188,-0.233293,-0.582778,0.620954,0.100546,-0.078309,0.301536,-0.010144,0.326113,-0.455534,0.166209,-0.243005,-0.103031,0.091214,-0.061630,-0.456440,0.229029,-0.226632,-0.338692,0.040992,0.279858,-0.302856,-0.099321,0.337997,-0.490514,0.193277,-0.521777,0.322549,0.033590,-0.262075,0.124277,0.193294,-0.025650,0.454084,0.485690,0.226389,-0.116957,0.331108,-0.079162,-0.596860,-0.145772,0.071117,0.034454,-0.266193,0.337103,0.106213,0.168641,0.016310,-0.268658,0.314443,0.333653,0.250786,0.255884,-0.164160,-0.321401,-0.617224,0.249819,0.282499,-0.317274,-0.272622,-0.038274,0.038404,-0.581749,-0.201019,-0.003381,-0.134181,-0.086945,0.423174,0.065382,0.441508,0.502024,-0.894074,-0.024053,-0.407925,0.069898,0.241149,-0.053449,0.238568,-0.548226,-0.205621,-0.203976,-0.184466,0.161062,0.487286,-0.100627,0.650667,-0.459872,0.157970,0.359432,0.539745,-0.242859,0.526479,-0.043294,0.126723,-0.056517,-0.176170,0.184195,0.028510,0.614625,-0.057102,0.175069,0.153968,0.081865,-0.395163,0.300690', '26290398', '6982558', '25890017', '30336307');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1997681', '心急吃不了热豆腐', '喜剧', '刘好（冯巩）是河北某个小县城一名普通的三轮车师傅，为人时而大大咧咧时而相当抠门，虽然生活不富裕，他还是怀抱知足常乐心态去过好每一天的日子。刘好的生命中，一共出现过三个女人。贺文兰（张澍）离开他时，给他留下和他没有血缘关系的儿子刘小好（叮当）；经别人介绍认识杨倩（徐帆）后，刘好开始与她谈论婚嫁，但对方开出的条件相当苛刻，且嫌弃他有一个儿子，实际上刘小好已经成为刘好生命的一部分；无意间结识陈红（刘孜）后，善良老实的刘好终于收获生活给予他的回报。©豆瓣', '冯巩', '冯巩', 7, 32684, 'tt0470610', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507752102.jpg', 0.7, 4.5, 47.3, 37.1, 10.4, '0.180050,0.051663,-0.662725,0.651589,-0.367044,-0.232968,0.783716,0.049687,-0.573246,-0.400939,0.075567,0.491904,0.213709,0.475954,-0.052717,-0.040926,-0.073820,-0.224175,0.035962,0.032055,-0.149827,-0.229438,-0.073484,-0.093580,-0.426741,-0.147556,0.386681,-0.063479,-0.064237,0.301001,0.127772,0.027951,0.258007,0.476957,-0.659421,0.255328,0.016416,0.244521,-0.198323,0.094660,-0.166725,0.120753,-0.102925,-0.049295,0.101955,0.387274,0.525378,0.108571,-0.593601,-0.146380,0.359946,0.069736,-0.122683,0.057276,0.143347,0.100116,0.624756,0.232220,-0.140761,0.039333,-0.236122,-0.168370,-0.561494,-0.060198,0.214998,-0.046019,-0.540206,0.482393,0.060232,-0.258019,-0.210167,-0.459075,-0.000500,0.219037,0.239854,0.193583,-0.279666,0.127918,-0.400060,-0.028373,0.756018,-0.048902,-0.265505,0.492495,-0.362444,-0.616234,0.327090,-0.222164,-0.311540,0.221544,0.012479,-0.048068,-0.275533,0.005189,-0.491899,0.218614,-0.078750,-0.056217,0.267013,-0.436220,-0.020341,-0.179943,-0.152880,-0.745411,-0.770619,0.057532,-0.081070,-0.431538,0.905803,-0.779805,0.210439,0.269363,0.397005,-0.638919,0.692743,0.353617,0.046445,-0.359370,0.171049,0.219210,0.071833,0.003892,-0.076498,0.126489,-0.227264,-0.191887,-0.105149,0.558432', '26283288', '25828521', '26354526', '1466907');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19977815', '小小飞虎队', '喜剧', '《小小飞虎队》曾获得了大众电视金鹰奖最佳儿童剧奖，飞天奖三等奖等众多奖项。几个主要儿童演员此前几乎都没有表演经验，为了挑选到合适的小演员，剧组在京、鲁、豫近40多所学校选择了三万多名孩子。故事讲述了抗战时期的鲁南，交通员老吴（果静林 饰）在给山里八路军送情报的路上突遭日军的追杀，在万不得已的情形下他将情报编成两句暗语告诉了正在芦苇荡玩的小主人公：大壮（赵泽文 饰），自此，胆小、笨拙而又“一根筋”的大壮拉上同村的虎子（小叮咚 饰）和小银（胡天阳 饰）踏上了前途未卜的 送情报之旅……©豆瓣', '赵泽文', '钱晓鸿', 4.2, 5749, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1830980015.jpg', 48.3, 18.8, 16.5, 7.7, 8.7, '0.012792,-0.084408,-0.520353,0.626092,0.099949,-0.165776,0.157875,0.164350,-0.284937,-0.063910,0.044683,0.509052,0.007024,0.115173,-0.022883,-0.383883,-0.367750,-0.532706,-0.123449,-0.173027,-0.303212,-0.373868,-0.140265,-0.045200,-0.002762,-0.088688,0.317905,0.013527,-0.448119,0.360038,0.620385,-0.067314,-0.144220,-0.079929,-0.447612,0.283253,0.335132,0.066229,-0.054191,0.036242,-0.068703,-0.380861,-0.292692,-0.035492,0.398696,0.444060,0.949832,-0.270078,-0.174513,0.170458,0.285468,-0.131412,0.182373,-0.317728,0.337533,0.189572,0.370406,-0.035471,0.017509,0.284875,0.206626,-0.163399,-0.496290,0.203163,0.173381,0.104398,-0.681656,0.218659,0.071219,0.325519,0.126963,-0.334429,0.295168,0.312883,0.132595,0.121322,0.004267,-0.006726,-0.262280,0.705447,0.204994,-0.134012,0.098904,0.320934,-0.040431,-0.453298,-0.032265,-0.082563,-0.348865,0.034423,0.710883,-0.327218,-0.166007,-0.014254,-0.480082,0.003046,0.200467,-0.291833,0.218292,-0.091574,0.032699,-0.762620,0.122981,-0.133818,-0.290737,0.274172,0.282378,0.059713,0.967561,-0.262531,0.183392,0.387400,-0.124990,-0.478400,0.595168,0.061993,0.110565,-0.073818,0.223783,-0.224001,0.164878,0.382833,0.393566,0.277283,-0.415486,-0.595117,-0.615830,0.161625', '5403927', '3811356', '25863940', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('1998649', '给工藤新一的挑战书~离别前的序章', '剧情', '工藤新一（小栗旬）这晚收到挑战书，称将有他的同学在修学旅行的船上被绑架，若新一不能保护好同学，须让出“高中生名侦探”的称号。新一本对修学旅行没兴趣，这封信令他次日赶到学校与小兰（黒川智花）、园子（岩佐真悠子）及班里另外约30名同学会合。众人刚登上旅行用船，新一即把目光投向代理班主任北岛慎吾（ふかわりょう）、导游西田麻衣（水川あさみ）、船长东邦夫（松重丰）及船员南田恭介（西村和彦）等人，时刻保持着警惕。但园子仍神不知鬼不觉失踪。着手调查尚无头绪，他再接绑架预告电话。©豆瓣', '小栗旬', '冈本浩一', 6.1, 21558, 'tt3168910', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2152493943.jpg', 3.9, 17, 54.1, 18.6, 6.4, '0.325144,-0.417611,-0.248596,0.172903,0.072934,-0.273622,0.084136,0.253149,-0.250574,-0.382406,-0.041055,0.465224,-0.264793,0.265300,0.452390,-0.008523,-0.608784,-0.573199,-0.223278,-0.284425,-0.272202,-0.523327,0.201985,0.100844,-0.111426,-0.246498,0.107460,-0.147644,0.049409,0.864868,0.161201,0.168519,-0.422502,0.415630,-0.108467,0.007081,0.386580,-0.012672,-0.078239,0.314083,-0.255947,-0.240892,-0.403618,0.057707,0.423571,0.496101,0.644985,0.205666,-0.215691,-0.043617,-0.018795,-0.106057,-0.054460,0.003036,0.370959,0.058879,0.021304,0.386805,-0.118844,-0.198709,-0.014418,-0.040919,-0.120089,0.214661,-0.086111,0.095032,-0.139232,0.134776,-0.269335,0.076536,0.278133,-0.221095,0.259476,0.251115,0.057302,-0.069763,0.039851,0.365702,-0.082421,0.241215,0.311934,-0.157596,0.364979,0.013286,0.289937,-0.242112,0.316740,0.266801,-0.327094,0.042735,0.144963,0.026871,0.049465,-0.472409,-0.268617,-0.268394,-0.202574,-0.151898,0.185395,-0.379829,-0.159666,-0.676140,0.185994,0.159622,-0.231789,0.230638,0.367145,-0.021882,0.750203,-0.544779,-0.072278,0.416969,0.198660,-0.200419,0.542791,0.081729,0.016108,-0.400571,0.135143,-0.302006,0.345302,0.638423,0.168885,0.283785,-0.137414,-0.156566,-0.485669,-0.096982', '3811356', '2357711', '25922902', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('19994974', '周恩来的四个昼夜', '剧情', '故事发生在上世纪六十年代初，由于众所周知的原因，饥荒遍野，我国国民经济建设濒临崩溃的边缘。党中央毛主席通过紧急蹉商，委派各级领导奔赴灾情最严重的地区实地考察，周恩来（孙维民 饰）也在邓颖超陪同下，从贵州赶赴河北。公社主仼郭凤林不愿年事已高的总理看到令人揪心的真实状况，他采用欺上瞒下手段，层层弄虚做假，不让干部群众讲真话，甚至对生性梗直的亲爹封锁总理来视察的消息。总理明察秋毫，十分清楚基层在做假糊弄自己，他甩开干部们事前做好的安排，深入底层访贫问苦，他交下的穷朋友张二廷终于向他袒露了真情，而自知犯下大错的郭凤林羞愧万分......©豆瓣', '孙维民', '陈力', 7, 7452, 'tt5051224', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2132291407.jpg', 12.4, 8.1, 25.2, 26.9, 27.4, '0.024749,-0.106289,-0.645023,0.253575,-0.064356,0.259607,0.221532,0.116746,-0.620346,-0.303088,0.232386,0.264553,-0.226858,-0.088540,0.149453,-0.237729,-0.201091,-0.289455,-0.127456,0.053202,-0.116936,-0.597157,-0.051279,-0.202810,-0.238196,-0.098607,0.310470,0.188792,-0.456500,-0.101749,0.257485,0.212855,0.060706,0.354311,0.071423,-0.224587,-0.029465,-0.070926,-0.348475,-0.196038,0.096373,-0.428971,-0.188778,0.229146,0.265818,0.545590,0.210037,-0.273421,-0.384917,0.144847,0.435565,-0.377445,0.179300,0.257295,0.382778,0.182066,-0.180103,0.289009,-0.298240,-0.180462,-0.159864,-0.086235,-0.476157,-0.078214,0.139519,0.286920,-0.420978,0.114657,-0.030438,0.325567,-0.076030,-0.617243,0.364622,0.587523,-0.304061,0.396031,-0.026475,0.024261,-0.091042,0.390503,0.849004,0.054908,-0.226097,-0.202190,-0.444876,-0.226677,0.278960,-0.259967,-0.134874,-0.036612,-0.185864,-0.216754,0.036675,0.256485,0.024036,-0.217332,0.033293,-0.333128,-0.038255,-0.009116,0.111004,-0.292942,-0.116988,-0.325207,-0.190152,-0.169023,-0.011235,-0.201533,0.460100,-0.419101,-0.103811,0.249826,0.099316,-0.636349,0.478431,0.420399,-0.083876,-0.214610,0.012081,0.263531,0.161343,0.548121,0.159427,0.152968,-0.236771,-0.547215,-0.046253,0.157346', '1439400', '4145476', '6890343', '1297607');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2000741', '母亲', '剧情', '1940年，日本一方面深陷中国战场，另一方面与英美等国关系日益紧张。居住在东京的野上一家本来过着平静而幸福的生活。只是在这战争年代，幸福是多么奢侈和脆弱的一件事。身为进步作家的一家之长野上滋（坂东三津五郎 饰）因左倾思想被当局以妨害治安维持法的罪名逮捕，不久即受迫害致死。妻子佳代（吉永小百合 饰）强忍悲痛，坚强地抚养一双女儿初子（志田未来 饰）与照美（佐藤未来 饰）。他用自己一生的幸福和无私的母爱，护佑着孩子们健康成长……本片根据黑泽明生前的御用场记野上照代所创作的自传体小说《给父亲的安魂曲》改编。©豆瓣', '吉永小百合', '山田洋次', 8.6, 9708, 'tt0855852', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1176372745.jpg', 0.2, 0.6, 11.2, 46.3, 41.7, '-0.157371,-0.083940,-0.450189,0.522196,-0.061470,-0.202758,0.574556,0.265835,-0.430721,-0.437630,0.186550,0.626564,0.208561,0.169271,0.193096,0.131523,-0.251069,-0.573002,0.028092,0.137685,0.236535,-0.313963,-0.223295,-0.130012,-0.224813,-0.561230,0.820013,0.125204,-0.087466,0.448561,0.095967,0.545165,-0.169746,0.029598,0.054603,-0.040635,-0.092207,0.137198,-0.415153,-0.065467,-0.161770,-0.189195,-0.176820,0.133378,-0.051665,0.199271,0.471544,-0.355207,-0.246459,-0.302928,0.461247,-0.347788,-0.195744,0.295137,0.176819,0.071663,0.207294,0.491034,-0.391556,-0.072939,0.123255,-0.137201,-0.859730,-0.500275,0.323004,0.012590,-0.594132,0.668144,-0.196856,-0.218496,0.213060,-0.198244,0.248091,0.481757,0.275269,0.686225,-0.550855,0.414105,-0.237572,0.409595,0.642387,-0.158012,-0.121839,0.153867,-0.453349,-0.275286,-0.098479,-0.557179,-0.762391,-0.149842,0.040799,-0.087368,-0.059995,0.283046,-0.456356,-0.078853,-0.050264,-0.192946,0.230838,-0.394250,0.083605,-0.227719,-0.163307,-0.779540,-0.397200,-0.146159,0.216907,-0.374198,1.034682,-0.558084,0.265501,0.510713,0.112313,-0.466840,0.437687,0.609478,0.097005,-0.209600,-0.237100,0.521886,-0.158351,0.090360,0.016763,0.035227,-0.027138,0.103081,-0.238310,0.503241', '26348103', '27602116', '24284209', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20020577', '推拿', '剧情', '少年时代的一场意外让男孩小马（黄轩 饰）的双眼失去了光明，自杀未遂后，阴沉的小马辗转来到了由沙复明（秦昊 饰）所经营的盲人按摩中心就职。在这里，聚集了许多和小马一样的盲人，无论是先天还是后天，生活在共同的黑暗里让这群盲人之间产生了深厚而坚实的友谊。王大夫（郭晓冬 饰） 和女友小孔（张磊 饰）远道而来投奔沙复明，小孔充满了女人味的声音和气息令小马的内心产生了涟漪，执着而决绝的小马追寻着内心的声音，不断的向小孔靠近着。之后，一个名叫小蛮（黄璐 饰）的发廊小姐出现在了小马的生命里，随着时间的推移，小马竟然开始对小蛮产生了感情。©豆瓣', '郭晓东', '娄烨', 8, 191877, 'tt3469964', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2211024574.jpg', 0.4, 1.8, 20.2, 53.3, 24.3, '0.159954,0.005531,-0.796515,0.764612,-0.081850,-0.264423,0.997854,0.392638,-0.600550,-0.119516,0.039093,0.599906,-0.323977,0.285816,0.144036,-0.082214,-0.119597,-0.731294,-0.466250,-0.233412,-0.355878,-0.369451,-0.274945,-0.055744,-0.048538,-0.332529,0.610034,0.193926,-0.210259,0.866022,0.157648,0.113614,-0.005982,0.371443,-0.224349,-0.061400,0.069883,0.046723,-0.020367,0.009843,0.375231,-0.152918,0.102168,0.170322,-0.353317,0.238186,0.850536,-0.348517,-0.001126,0.017633,0.334778,-0.056936,0.107056,0.003520,0.093727,0.314153,0.230906,0.065133,-0.250070,0.095007,0.178398,0.002439,-0.538803,0.131376,0.097238,0.320210,-0.785341,0.352879,0.169543,-0.438470,0.307062,-0.408386,0.224146,0.150986,0.121704,0.560860,-0.399679,0.118708,-0.198096,-0.105991,0.468135,0.006933,-0.378201,0.384766,-0.367499,-0.465826,-0.097154,0.261763,-0.352466,-0.352504,0.407080,0.228064,0.009291,0.226677,-0.961837,0.067554,0.050035,0.053106,-0.028960,-0.352826,-0.151084,-0.603557,-0.420347,-0.690257,-0.115131,0.115084,0.084097,-0.003802,0.740373,-0.974398,0.293561,0.484389,0.169906,-0.152576,0.575292,-0.284723,0.068919,-0.105789,-0.042411,0.093029,-0.198871,0.449593,0.214944,0.516386,-0.301900,0.200427,-0.420383,0.496680', '3111650', '21442760', '21619567', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2002683', '迷幻公园', '剧情', '迷幻公园是这个城市滑板少年的聚集之地，当然，这里也是犯罪的多发地带。少年阿历克斯（盖博•纳文斯 Gabe Nevins 饰）迷恋上了这个公园，每天他都要到这里来，虽然他玩滑板不是很在行，但是能静静的坐在边上，欣赏场内各个高手各种各样的滑板花招，他已经感到十分快乐。然而，那天发生的一次事件却令到阿历克斯即使听到别人提起迷幻公园都十分局促不安。阿历克斯每天都在经历着一番剧烈的心理斗争，他惊恐、他害怕、他迷惘。最终阿历克斯会走向何方？©豆瓣', '盖博·纳文斯', '格斯·范·桑特', 7.3, 21567, 'tt0842929', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p453945433.jpg', 0.7, 4.3, 36.6, 44.7, 13.7, '0.340635,0.022784,-1.083406,0.461823,0.167398,-0.078380,0.847743,-0.088648,-0.518926,-0.134954,0.212452,0.416829,-0.295770,0.505000,0.234137,0.128845,-0.407892,-0.293886,-0.025311,-0.100143,-0.340488,-0.391205,-0.338306,-0.152432,-0.298526,-0.236994,0.227385,-0.127336,-0.045064,0.284233,0.323204,0.355109,0.165439,0.741629,0.046705,-0.146192,0.018184,0.030694,0.098908,-0.038052,0.055803,-0.372426,-0.335593,0.208337,0.208158,-0.033727,0.712125,-0.098206,-0.273501,0.185154,0.102432,-0.216769,0.010833,0.023487,0.250370,-0.456943,0.060371,-0.100388,0.071149,0.114595,0.092405,0.128795,-0.417545,0.058758,0.071658,0.446041,-0.439823,0.083169,0.091300,-0.251177,0.025078,-0.369136,0.135209,0.338529,0.276953,0.246530,-0.073005,-0.100068,-0.601269,-0.079358,0.689193,0.191604,-0.112637,0.363953,-0.347457,-0.472927,-0.198851,-0.043944,-0.689324,0.013814,0.002198,-0.284153,-0.206684,0.385475,-0.396124,0.212271,0.123443,-0.380884,-0.160330,-0.162800,-0.146918,-0.554068,0.077979,-0.523599,-0.409554,0.011261,-0.133645,-0.329297,0.305548,-0.691906,0.252897,0.826250,0.118403,0.054040,0.569238,-0.120900,-0.215927,0.018345,-0.300672,0.323923,0.002097,0.345796,0.056258,0.441094,0.116220,0.117361,-0.393005,0.629153', '34461680', '3011051', '25870679', '34614704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2002696', '你还活着', '剧情', '瑞典小城，形形色色看似普通而又古怪的小城居民。天天神经质般叫嚷“没有人理解自己”的胖大妈，破坏别人宴席而被宣判坐电椅执行死刑的中年大叔，一边做爱一边念叨银行基金赔钱的怪男人，口不择言伤害到对方的争吵夫妇，听了二十七年精神病人倾诉已经不堪重负的精神科医生，一个随时都会解散的业余乐团，敢于追求爱情哪怕只是梦境的女孩安娜……一段段看似毫无联系的生活片段，或荒诞滑稽或离经叛道，却共同讲述着人与人之间爱与被爱的幽默悲喜剧。由广告鬼才导演罗伊·安德森执导的诗意另类影片《你还活着》，以短篇散文诗般的笔法描绘了芸芸众生，一幕幕有关伟大与卑微、欢喜与悲伤、自信与焦虑、爱与被爱的平凡小故事。©豆瓣', '伊丽莎白·赫兰德', '罗伊·安德森', 8.3, 7088, 'tt0445336', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1725060218.jpg', 0.4, 1.9, 15.9, 46.9, 34.9, '0.330969,-0.079778,-0.358312,0.575735,-0.195075,-0.138057,0.977619,0.176988,-0.477198,0.022847,0.210873,0.632757,-0.249559,0.298610,0.091693,0.004177,-0.174283,-0.676690,-0.091314,0.137555,-0.016534,-0.599825,0.062996,-0.434852,-0.258535,-0.262490,0.331832,-0.027541,-0.353744,0.384752,0.266740,0.154515,-0.211732,0.316391,-0.242814,-0.186721,0.001455,0.138543,-0.270336,-0.316802,0.059401,-0.002337,0.022308,0.150519,-0.355867,0.224947,0.610070,-0.317564,-0.186858,-0.007054,0.477928,-0.125639,-0.001816,0.202875,-0.056262,-0.071344,0.414942,0.216229,0.085099,-0.023760,0.113599,-0.110187,-0.806229,0.027460,0.090889,0.384503,-0.253581,0.521556,0.057469,0.135819,0.335455,0.048094,0.078424,-0.131896,0.630581,0.761554,0.043274,-0.113082,-0.336165,0.540931,0.562273,0.267120,-0.578089,0.379695,-0.482687,-0.089875,-0.016821,-0.378212,-0.653222,0.128830,-0.133724,-0.207479,-0.305495,0.255588,-0.538733,0.190609,0.077940,0.153118,-0.074679,-0.685412,-0.296293,-0.565035,0.003834,-0.253127,-0.154631,-0.114423,0.241409,-0.091924,0.920753,-0.660196,0.221444,0.561951,0.335221,-0.355022,0.667779,0.294684,-0.276277,-0.249264,0.066277,0.451079,-0.066057,0.052116,0.100789,0.173839,-0.232527,0.225794,-0.301036,0.374980', '1303077', '25882279', '4847665', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2002741', '决战以拉谷', '剧情', '本片取材自真实事件。伊拉克步兵麦克•德尔菲尔德（乔纳森•塔克 Jonathan Tucker 饰）的父亲汉克•德尔菲尔德（汤米•李•琼斯 Tommy Lee Jones 饰）某天突然接到儿子回国后失踪的消息。老兵汉克驱车来到军营亲自调查，从儿子手机的影像中一点点了解到了麦克在伊拉克所经历的心理创伤。没多久警方发现麦克遇害，并被肢解焚尸。汉克的妻子琼（苏珊•萨兰登 Susan Sarandon 饰）得知噩耗后悲恸万分，不能自己。汉克在调查案件的过程中结识了当地探员艾米莉（查理兹•塞隆 Charlize Theron 饰），二人建立了一种特殊的友谊，并一步步接近事件的真相。本片获奥斯卡奖最佳男主角提名（汤米•李•琼斯），并获第64界威尼斯电影节天主教文化奖大奖及金狮奖提名。©豆瓣', '汤米·李·琼斯', '保罗·哈吉斯', 7.6, 8563, 'tt0478134', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p620199902.jpg', 0.4, 2, 28.9, 52.4, 16.3, '0.005418,0.020494,-0.774203,0.402693,0.505210,-0.346033,0.521565,0.029638,-0.606956,-0.415749,0.034578,0.612686,-0.240051,0.153256,0.637420,-0.118245,-0.793434,-0.594293,0.038056,-0.397454,-0.219049,-0.510653,-0.217474,-0.192890,0.011480,-0.423727,0.417988,-0.105220,-0.162908,0.620378,0.249788,0.438719,-0.107302,0.284434,0.287444,0.354743,0.783269,-0.066040,-0.627314,0.226296,0.059634,-0.185545,-0.140159,0.112685,0.083908,0.297231,0.402655,-0.304099,-0.023224,-0.051891,0.314600,-0.188910,0.037862,-0.162794,0.445771,0.044571,0.157173,0.260156,-0.050273,0.066777,0.070653,-0.079052,-0.278105,0.015313,-0.062122,0.427690,-0.178602,0.005072,-0.494112,0.256757,-0.081987,-0.308268,0.133342,0.348481,0.238217,0.189221,-0.041998,0.074478,-0.293947,0.239542,0.255418,-0.126227,-0.159491,0.034835,-0.104615,-0.752915,0.080536,0.126813,-0.249627,0.296647,0.808001,-0.000353,0.182535,0.397337,-0.139706,-0.390398,-0.574459,-0.208300,-0.142038,0.036153,0.116245,-1.057116,-0.290917,0.023679,-0.153347,-0.348082,-0.036393,-0.172446,0.083302,-0.358595,0.465740,0.355203,-0.129711,-0.130271,0.026840,-0.042367,0.211400,-0.546376,-0.150058,0.524560,0.247236,0.225468,-0.003190,0.213746,0.056962,-0.448073,-0.192620,0.207516', '1293572', '2075345', '6517421', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2002743', '霍乱时期的爱情', '剧情', '长达半个世纪的爱情故事。19世纪末期哥伦比亚的喀他赫纳，电报员Florentino Ariza（Javier Bardem 饰）爱上了富商的女儿Fermina Daza（Giovanna Mezzogiorno 饰），他用热情洋溢的情书打动了Fermina Daza的心，二人迅速相恋。然而，由于身份地位的悬殊，Fermina Daza不得不屈从于父亲，离开了喀他赫纳，在年轻的Fermina Daza看来，二人的爱情只是少不更事的幻觉而已。几年后，Fermina Daza在父亲的安排下，嫁给了有好感的医生Dr. Juvenal Urbino（Benjamin Bratt  饰）。正值霍乱时期，一个医生丈夫不仅能带来优渥的生活，更是生命有力的保障。Fermina Daza渐渐忘记了当年的事情。可是Florentino Ariza却没有忘记，当年一无所有的青涩少年，继承了伯父的遗产，成为富有的船商，他经历着不同的女人，但是内心却对Fermina Daza念念不忘，他能做的事情，就是等待，等待重逢的那一天，纵然五十多年过去，对她的心意还一如往昔。', '哈维尔·巴登', '迈克·内威尔', 7.4, 44382, 'tt0484740', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1634591563.jpg', 1, 5, 34.3, 42.6, 17.1, '0.151390,0.201198,-0.636347,0.739738,-0.315484,-0.363653,0.806537,0.083281,-0.587455,-0.390026,0.168621,0.704811,0.143604,0.178901,0.178108,0.013662,-0.047353,-0.702242,0.056850,-0.087120,-0.074887,-0.530874,-0.308820,-0.074347,-0.236501,-0.405982,0.728654,0.051431,-0.149437,0.415090,0.169042,0.098022,0.283656,0.443623,-0.507301,0.068690,-0.028104,0.224674,-0.444750,-0.055497,0.292929,-0.420616,-0.007858,0.286146,-0.152110,0.407119,0.420881,-0.295666,-0.302057,0.010625,0.537843,-0.081140,-0.094408,0.193127,0.228844,0.163278,0.191569,0.354276,-0.305797,-0.160527,0.120581,-0.036053,-0.828089,-0.020775,0.105412,0.172952,-0.785596,0.675595,-0.175266,-0.144596,0.057563,-0.423434,0.153626,0.328856,0.067918,0.641190,-0.280579,-0.056009,-0.516935,0.287522,0.869235,0.035175,-0.429724,0.572215,-0.309546,-0.491482,-0.116936,-0.454928,-0.711743,0.215799,0.098127,0.116268,-0.276465,0.359930,-0.302566,-0.033093,-0.282566,-0.157523,0.211608,-0.633864,-0.148930,-0.092081,-0.427466,-0.638786,-0.525314,0.129847,0.168614,-0.402991,0.851320,-0.864944,0.280333,0.512940,0.377734,-0.561169,0.694376,0.388997,-0.037249,-0.112822,0.013706,0.455737,-0.309906,0.033900,0.142286,0.069043,-0.074308,-0.117779,-0.236311,0.600101', '26283288', '35030151', '25721544', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2002744', '焦糖', '剧情', '故事发生在黎巴嫩的一家美容院，围绕着五名女性的日常生活展开。拉亚里（纳迪·拉巴基 Nadine Labaki 饰）、尼斯瑞和瑞玛在同一家美容院工作，詹美尔则是她们的常客，而美容院附近的一名女裁缝师罗丝和她年老的痴呆的姐姐莉莉一起住。她们年龄不同，性格不同，人生际遇不同，她们有各自独特的故事。拉亚里因爱上了一个有妇之夫而陷入困苦，而且不得不面对他不知情的妻子；尼斯瑞婚礼在即，却决定到医院做个处女膜修复手术；瑞玛是个女同性恋，对一个美貌的顾客颇有好感；曾经是演员的詹美尔难以接受自己一日一日的衰老；而年老的罗丝因为要照顾姐姐而放弃爱情。一段段故事交织在一起，像焦糖一样，既甜蜜缠绵，又丝丝苦涩……©豆瓣', '娜丁·拉巴基', '娜丁·拉巴基', 7.8, 8895, 'tt0825236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1018501266.jpg', 0.6, 1.8, 24.4, 51.1, 22.2, '0.474949,-0.183810,-0.414906,0.529540,-0.114141,-0.145859,1.132131,0.372821,-0.541286,-0.380405,0.286070,0.849755,-0.108478,0.458913,0.328408,0.141891,-0.239691,-0.542135,0.116808,-0.081801,-0.135787,-0.649200,-0.092613,-0.153563,-0.088419,-0.361841,0.481562,-0.130552,0.078093,0.515057,0.387015,0.269809,-0.314596,0.276215,-0.173671,-0.119982,0.052413,0.002417,-0.361283,0.175374,0.212614,0.039985,-0.203882,0.003127,0.034462,0.333763,0.583326,-0.025183,-0.043130,-0.053471,0.304289,0.007639,0.064194,0.292494,0.132374,-0.122124,0.403495,0.108823,-0.251365,-0.003608,0.117438,-0.071186,-0.656841,0.106159,0.388279,0.289108,-0.607207,0.517963,0.053750,-0.077986,0.043342,-0.260553,0.069886,0.335571,0.156907,0.648855,-0.129067,0.058832,-0.639673,0.023497,0.828853,0.234487,-0.216508,0.477472,-0.453688,-0.241950,-0.180213,-0.085723,-0.803788,-0.051922,-0.060935,0.118678,-0.192882,0.295996,-0.716537,0.002224,-0.216845,-0.095412,-0.073132,-0.317765,0.026923,-0.595558,-0.188440,-0.604630,-0.385542,0.013004,0.186446,-0.169345,0.837006,-0.994485,0.238720,0.317252,0.215789,-0.615121,0.792059,0.307630,0.368687,-0.259377,-0.045005,0.437147,-0.159507,-0.209525,0.015431,0.526115,-0.105470,0.098164,-0.539659,0.513018', '1292062', '1296534', '1308755', '1303036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2002954', '针孔旅馆', '剧情', '大卫（Luke Wilson 饰）与艾米（Kate Beckinsale 饰）是一对刚经历了丧子之痛的夫妻，为了纪念他们即将分解的婚姻，两人驾车行驶在茫茫夜色中，进行他们最后的分手旅行。为抄近路，大卫拐入了一条荒僻小路，然而行驶不久车子即宣告故障，一位子夜时分仍未眠去的年轻人出现帮助了他们，但问题仍未解决。大卫与艾米不得不步行到一家汽车旅馆休息。旅馆内空无一人，值班室内传出令人毛骨悚然的尖叫声，值班员大咧咧的关闭了电视录像，将两人安排在一间拐角的房间，房间设施陈旧肮脏，大卫在翻看电视柜内遗留的录像带时发现内容尽是极其写实的血腥电影，然而更令人震惊的是电影内的场景分明就是他们入住的房间！这家旅馆无疑是杀害旅客制作录像带的变态乐园。于是清冷的夜里，夫妻俩唯一要面对的是自己的生存问题。©豆瓣', 'Kate Beckinsale', '尼姆罗德·安陶尔', 6.3, 20410, 'tt0452702', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2398511813.jpg', 2.4, 14.9, 54.8, 22, 5.9, '0.440491,0.007891,-0.547765,0.269862,0.274930,-0.291838,0.992231,0.373881,-0.548046,-0.345654,0.536320,0.581157,-0.209316,-0.040534,0.218411,0.017050,-0.635828,-0.327326,-0.144204,-0.362729,-0.352780,-0.475954,0.025253,-0.270553,0.204045,-0.060532,0.503858,0.314481,-0.234484,0.285853,0.023125,-0.053903,-0.515236,0.429781,-0.154614,-0.205488,0.241130,0.057546,-0.273257,0.195611,-0.146046,-0.261128,-0.255449,-0.016922,-0.092708,0.401674,0.800747,-0.149911,-0.366724,0.212837,0.320850,-0.033807,-0.250152,0.066233,0.175503,-0.033152,0.396428,0.322548,-0.363816,-0.108472,-0.043491,0.001957,-0.509941,0.088345,-0.116470,-0.032454,-0.318936,0.430237,-0.156947,-0.112277,0.333680,-0.374282,0.485292,0.050006,0.330676,0.537351,0.015691,-0.138700,-0.556528,-0.088423,0.492720,-0.059720,-0.070898,0.733966,-0.156921,-0.467713,-0.026350,0.000884,-0.539293,-0.102601,0.367680,0.155242,-0.154867,-0.211573,-0.628352,0.124191,-0.336394,-0.468367,-0.059522,-0.110510,-0.393719,-0.977373,-0.085704,-0.068672,-0.093004,0.117186,-0.167871,-0.063076,0.351446,-0.513521,0.207749,0.276220,0.062436,-0.120093,0.922810,-0.258354,0.320640,-0.033556,0.056665,0.144644,0.022949,0.581999,-0.062551,0.318899,-0.287359,-0.102402,-0.770857,0.362900', '10466639', '1297659', '2334814',