INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2003156', '赌侠2002', '剧情', '有“地狱倒霉鬼”之称的李加乘（张家辉 饰）出生二十多年来几乎诸事不顺，对人生失望已极的加乘再次周期性自杀，而这次失败的自杀却使他结识了新朋友何红申（黄伟文 饰），以及美丽的护士小姐夏天（王秀琳 饰）。加乘向夏天表达爱意，但同时又担心对方会因为自己而倒霉——李加乘的晦气太重以至于所有对他好、或是受他帮助的人也会连带走霉运。当加乘与夏天的哥哥——赌术高手春天（冯德伦 饰）相遇后，他的霉运却成为赌场上唱衰对手的不二法宝，春天与加乘搭档，将宿敌大口九的赌场生意连连逼退，大口九反戈一击，将加乘绑架又买通春天手下，誓要致二人于死地……©豆瓣', '张家辉', '张敏', 5.9, 6217, 'tt6449044', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2358867785.jpg', 4.9, 21.1, 54.8, 13.6, 5.7, '-0.116409,-0.182032,-0.513494,0.327812,0.043532,-0.234387,0.609172,0.246227,-0.421504,0.022949,0.348152,0.658334,-0.321699,0.062385,0.306140,-0.152658,0.118480,-0.616066,0.129442,-0.068852,-0.280234,-0.164795,-0.185007,-0.122167,0.007965,-0.178889,0.338796,0.188890,-0.144365,0.525885,0.378551,0.358461,0.106470,0.560522,-0.138437,-0.065068,-0.368109,0.047818,-0.146971,0.231569,-0.018498,-0.385531,-0.108339,0.115551,0.005685,0.287373,0.597174,-0.101005,-0.230358,-0.251228,0.268511,-0.378843,0.016536,0.171390,0.217945,-0.054247,0.351361,0.187426,-0.041096,-0.127624,0.143889,0.056312,-0.646346,0.298290,0.149724,-0.272198,-0.463301,0.322308,-0.103074,0.008844,0.043899,-0.148053,0.044959,0.221586,0.227460,0.242264,-0.189405,-0.207542,-0.373267,0.039007,0.587317,-0.190221,0.061880,0.222995,0.045616,-0.244372,0.034882,-0.250721,-0.372293,0.037177,0.253649,0.207633,0.066508,0.123982,-0.445776,-0.063448,-0.195458,0.160101,-0.027665,-0.228462,0.029499,-0.321728,-0.050539,-0.376120,-0.204363,0.021466,0.412045,-0.105892,0.562353,-0.577406,0.211196,0.526663,0.273312,-0.624696,0.380060,0.009656,-0.100021,-0.226552,-0.294727,0.136018,-0.058245,0.142100,0.202011,0.213688,-0.075380,0.093674,-0.135871,0.128033', '1301022', '1308206', '26678784', '1309116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2003389', '葬礼上的死亡', '喜剧', '丹尼尔（马修·麦克费登  Matthew Macfadyen 饰）是个久不得志的作家，而且一直生活在名作家哥哥罗伯特（拉珀特·格雷夫斯 Rupert Graves 饰）的阴影之下。默默担负赡养父母义务的他这次主办父亲的葬礼，却同样被哥哥喧宾夺主。本来严肃而又神圣的葬礼更是被堂姐的未婚夫，错食了迷幻药的可怜虫西蒙（艾伦·图代克 Alan Tudyk 饰），搅得一团糟。然而更大的危机在后面，一个神秘的侏儒男子（彼特·丁拉基  Peter Dinklage 饰）现身了，带着毁坏父亲所有声名的证据对丹尼尔进行敲诈。原来丹尼尔的父亲是同性恋，这个秘密眼看就要在他死后被揭开。在一团混乱中，葬礼断断续续的进行着。戏剧化的悲伤和幽默悄然向我们揭示葬礼的意义——带着挚爱的心情缅怀死者，也让生者将不如意的过去埋葬在葬礼上。©豆瓣', '马修·麦克费登', '弗兰克·奥兹', 8.1, 72110, 'tt0795368', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p501057857.jpg', 0.4, 1.9, 19.2, 50.6, 27.9, '0.160776,0.108284,-0.761358,0.553979,-0.157967,-0.255875,1.004969,0.065605,-0.365316,-0.195102,0.306845,0.740804,-0.178531,0.505859,0.309182,0.111433,-0.251673,-0.745923,-0.198590,0.063704,-0.356926,-0.569235,-0.242814,-0.175172,-0.143273,-0.306040,0.426991,0.194159,0.078316,0.403405,0.463826,0.324073,-0.107610,0.516029,-0.145804,-0.006421,-0.020055,-0.067681,-0.143079,0.044396,0.251709,-0.380896,-0.021527,0.319336,-0.175962,0.410085,0.636145,-0.326521,0.008250,0.013113,0.410270,-0.442452,0.087624,0.466575,0.146073,0.030924,-0.020620,0.249151,-0.239568,-0.145036,0.169885,-0.122175,-0.709040,0.045239,0.085888,0.376434,-0.716495,0.807593,-0.116640,-0.071857,0.107859,-0.187221,0.398694,0.278456,0.060698,0.543181,-0.255336,0.242279,-0.390572,0.264627,0.394073,-0.001803,-0.062479,0.112343,-0.303318,-0.265075,-0.026802,-0.108434,-0.516322,-0.128454,0.486195,-0.219026,-0.017521,0.253444,-0.573513,-0.141067,-0.019269,-0.119946,-0.119906,-0.349594,-0.177666,-0.365359,-0.080471,-0.351142,-0.284952,0.076750,0.078621,-0.153288,0.505235,-0.547769,0.474222,0.450436,0.072975,-0.362002,0.436067,0.279713,0.181139,-0.124153,-0.241587,0.262802,0.113382,0.292844,0.343233,0.238580,0.123335,-0.169044,-0.337536,0.531911', '21619567', '3111650', '1421570', '1301464');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2003667', '人吓鬼', '喜剧', '这是一个发生在上个世纪80年代香港戏班里的故事。戏班里顽皮捣蛋的武生阿贵（董玮 饰）经常扮鬼吓人，连戏班的台柱新少佳都经常被他捉弄，大家对他既气愤，亦无可奈何。这次，当阿贵又扮鬼吓人时，岂料碰上了真鬼——潮州鬼。阿贵吓得屁滚尿流，幸好戏班里的老衣箱声叔（林正英 饰）这方面经验丰富，他得知潮州鬼生前被人分尸，死后才冤魂不散。为了让潮州鬼安息，声叔和阿贵决定找全潮州鬼的尸骸。不料却错挖了另一个恶鬼的尸骸，一时间，戏班被恶鬼弄得乌烟瘴气，声叔决定和阿贵一起扮天师吓走恶鬼。©豆瓣', '林正英', '钱月笙', 6.8, 6861, 'tt0087993', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2345959150.jpg', 1.2, 8.6, 50.9, 26.1, 13.1, '0.395900,-0.341793,-0.408422,-0.088239,-0.304441,-0.112507,0.518642,-0.134910,-0.520821,-0.247844,0.187016,0.431856,-0.555049,0.171513,-0.148150,0.120869,0.030669,-0.352455,-0.107539,-0.032741,-0.059118,0.157744,-0.347592,-0.049985,-0.275167,0.171413,-0.161128,0.066720,0.117490,0.186083,0.216776,0.087658,-0.390566,0.039109,-0.096653,0.361466,-0.003120,-0.137209,0.453115,-0.217191,-0.090535,-0.259063,-0.087211,-0.028589,-0.088655,0.365770,0.257031,-0.331348,-0.071244,-0.193915,0.148935,-0.129526,-0.201892,0.326807,0.366622,-0.359386,0.436681,0.013960,-0.023308,-0.147814,0.199811,0.262315,-0.416455,0.587117,0.408605,0.296031,-0.510658,0.199690,0.219350,0.262601,-0.109197,-0.071913,0.453440,-0.126738,0.321359,0.465861,-0.026840,-0.071372,-0.559843,0.320191,0.532074,-0.257244,0.020162,-0.053292,0.148230,-0.154802,0.401991,-0.277905,-0.065865,0.128204,0.167059,-0.386241,-0.512655,-0.013887,-0.361306,-0.136334,-0.073953,0.364260,-0.541555,0.072831,-0.234621,-0.315648,0.024531,-0.287762,0.106556,-0.128193,0.042230,0.162032,0.270985,-0.135381,-0.009122,0.382970,0.117247,-0.124836,0.379177,-0.165429,-0.045606,0.010200,-0.059644,-0.288664,0.432260,0.555724,0.583951,0.214589,-0.071543,-0.425194,-0.107734,0.160841', '1301996', '1472783', '1759975', '1473078');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2004482', '东京！', '剧情', '《室内设计》弘子（藤谷文子 饰）和怀揣导演梦想的男友阿明（加濑亮 饰）来到大都会东京，手头拮据的他们只得暂住在弘子好友清水朱美（伊藤步 饰）的公寓中。为了生计，两人四处寻找工作和住处，却一路坎坷。阿明的作品终于在一家小影院上映，望着男友喜悦的样子，弘子愈发感到自己的一无是处，就像一把被人丢弃的椅子一样……《梅德》身形扭曲、举止怪异的狂人梅德（Denis Lavant 饰）从下水道钻出，暴走街头，骚扰路人。几天后，他拿着偶然找到的二战时期的手雷出现，并将其一一掷向人群。军方将其抓获，开庭审判。而与此同时，要求处死梅德和要求释放梅德的呼声此消彼长。这个怪异之人俨然成为了狂热时代的偶像……《震动东京》某男（香川照之 饰）是一个十年未走出家门的御宅族，他讨厌阳光，害怕与人接触，成堆的书籍构成了他全部的世界。某天，他偶然瞥见送货女孩（苍井优 饰）的面容，突如其来的地震更将封闭的二人拉近。某男发现，他无法继续呆在家中……', '藤谷文子', '米歇尔·贡德里', 7.8, 18960, 'tt0976060', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1945826329.jpg', 0.6, 2.5, 24.2, 50.4, 22.3, '0.276799,-0.088492,-0.642899,0.470071,0.022046,-0.224526,0.917718,0.416562,-0.413317,-0.133662,0.401140,0.725725,-0.399435,0.165388,0.350055,0.013480,-0.347382,-0.775360,-0.322934,-0.216636,-0.251146,-0.183050,-0.209141,-0.229820,-0.171450,-0.422613,0.603167,0.033892,-0.114834,0.604130,0.300314,0.278328,-0.250190,0.544531,-0.326395,-0.101638,-0.162626,-0.002166,-0.136930,0.041942,-0.183338,-0.265002,-0.180520,0.049551,-0.138575,0.303687,0.757493,-0.098941,-0.115374,-0.041540,0.266532,-0.257264,-0.144745,0.204272,0.186013,-0.043357,0.227644,-0.055311,-0.375326,0.037004,0.407632,0.004698,-0.355622,0.160847,0.002921,0.331119,-0.365179,0.403145,-0.106467,-0.098030,0.155084,-0.502847,0.007455,0.059722,0.140073,0.366227,-0.249114,0.056956,-0.312422,0.156813,0.249982,-0.119777,-0.227442,0.386012,-0.042323,-0.314335,0.058819,-0.024979,-0.523229,-0.192959,0.450514,0.081836,-0.185202,0.012937,-0.604221,-0.092955,-0.140408,-0.237818,-0.018316,-0.360128,-0.277232,-0.711642,-0.079333,-0.317434,-0.215174,0.184653,0.131808,-0.096281,0.603632,-0.605417,0.089093,0.461510,0.282521,-0.226806,0.664058,-0.174144,0.035955,-0.077776,-0.140016,0.098360,0.129372,0.540926,0.050628,0.486784,-0.291802,-0.063244,-0.362632,0.412970', '1467779', '10466639', '21619567', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2005723', '在人生的另一边', '剧情', '内雅特（巴吉·达弗拉克 饰）鳏夫父亲与妓女耶特（诺塞尔·柯丝 饰）同居了。后来内雅特发现耶特把自己的血汗钱都资助了在土耳其上学的女儿阿伊坦（努古尔·耶西塞 饰）。耶特的这个举动使内雅特对之改观不少。本以为大家都可以和平相处了，怎料耶特的离世再次使内雅特与父亲的矛盾加深。内雅特想到了耶特在土耳其的女儿，便前往找寻。他到达后才知道阿伊坦是一名政治激进分子，为了躲过土耳其政府的追捕而逃到了德国。在德国逃难的阿伊坦得到好心人洛塔的帮助，让阿伊坦到自己的家里避难，但洛塔的母亲十分不满阿伊坦的到来，也阻止不了两人发展出一段情。结果，阿伊坦还是被抓捕并遣送回了土耳其。洛塔为了营救自己的爱人，也千里迢迢来到了土耳其，可是营救的前路困难重重。©豆瓣', 'Nurgül Yesilçay', '法提赫·阿金', 8.3, 6922, 'tt0880502', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536123759.jpg', 0.1, 1, 14.6, 53.5, 30.7, '0.253137,-0.062389,-0.681678,0.522011,0.027531,-0.672483,0.516306,0.151449,-0.474962,-0.093492,-0.108195,0.872748,-0.042469,0.154166,0.533535,0.133864,-0.428126,-0.666583,0.100525,-0.404833,-0.224767,-0.661179,-0.406773,-0.195903,-0.287554,-0.325750,0.214572,0.105702,-0.106478,0.389106,0.474836,0.280717,0.112829,0.639791,-0.152532,0.137408,0.037974,-0.208120,-0.190269,0.153275,0.219949,-0.288602,-0.241120,0.292989,0.223854,0.590533,0.631693,-0.504845,0.285160,-0.122860,0.157722,-0.311681,0.244548,0.261139,0.114572,-0.139963,-0.186257,0.181208,-0.347107,0.025763,0.120634,-0.044574,-0.761584,0.401345,-0.059604,0.005288,-0.957653,0.152801,-0.128113,-0.080142,0.125033,-0.451399,0.273828,0.872462,0.024042,0.344061,-0.300704,-0.019858,-0.702840,-0.160577,0.761784,-0.212646,-0.109410,0.179614,-0.274528,-0.451117,0.286921,-0.137883,-0.193903,-0.213458,0.279375,-0.070404,-0.000236,0.283530,-0.625059,-0.322846,-0.720309,-0.348447,-0.053735,-0.202047,0.075867,-0.571749,-0.073633,-0.275920,-0.342158,0.230130,0.110489,-0.166155,0.523148,-0.690050,0.249020,0.568536,0.466296,-0.631287,0.540196,0.049098,0.205946,-0.077549,-0.189878,0.663480,0.329732,0.154787,0.201995,0.286883,0.202702,-0.368167,-0.181015,0.407743', '25908042', '1292584', '26393561', '35461732');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2005841', '男神与女神的罗曼史', '剧情', '故事发生在遥远的古代，名叫瑟拉多（安迪·吉雷 Andy Gillet 饰）的牧羊人和名叫阿斯特蕾（斯蒂芬妮·克雷恩考尔 Stéphanie Crayencour 饰）的牧羊女相爱了，两人的爱情炙热而真诚，他们都视彼此为今生的唯一。不幸的是，由于听信了谣言，阿斯特蕾误以为瑟拉多另有新欢。伤心欲绝的阿斯特蕾发誓再也不愿见到瑟拉多。失去了阿斯特蕾的瑟拉多悲痛万分，只想匆匆了却此生，没想到，企图投河自尽的他被仙女救起。求死不成，瑟拉多重新感受到了自己对于阿斯特蕾的爱意，可是永不相见的誓言已经许下，面对这铁一般的桎梏，瑟拉多能够重新见到阿斯特蕾吗？又将有多少艰难险阻在道路上等待着他呢？©豆瓣', '安迪·吉雷', '埃里克·侯麦', 7.1, 5581, 'tt0823240', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1944267078.jpg', 1.1, 6, 42.4, 37.1, 13.3, '0.378237,0.063762,-0.765402,0.509891,0.033580,-0.556613,0.930707,0.181677,-0.068469,0.169247,0.143922,0.556531,-0.242068,-0.054235,0.268729,0.238045,-0.429250,-0.850410,0.165143,-0.511834,0.127352,-0.598816,-0.115797,0.187892,-0.128068,-0.444164,0.482428,0.094805,0.251397,0.239415,0.337452,0.605849,0.121132,0.371677,-0.008500,0.040843,0.116962,-0.078646,-0.158814,0.079635,0.106917,-0.141654,-0.150196,0.562523,-0.157705,0.256220,0.584324,-0.695745,-0.040622,0.127614,0.166661,-0.307509,0.368351,0.063674,-0.090255,-0.600077,0.177900,0.234526,-0.195107,-0.071878,0.421723,-0.105013,-0.717566,-0.105259,-0.070930,0.191533,-0.633133,0.042503,-0.112710,-0.197823,0.369604,-0.250236,0.126828,0.470317,0.367118,0.543064,-0.396742,-0.149265,-0.712891,-0.088633,0.871197,0.059807,-0.311865,0.621203,-0.396037,-0.205206,0.253617,-0.261932,-0.750245,-0.011440,0.486703,0.204866,-0.192512,0.271344,-0.442759,-0.258430,-0.368509,-0.210895,0.057893,-0.550017,-0.083670,-0.276521,-0.158258,-0.504925,-0.284532,0.205176,-0.080841,-0.402882,0.564245,-0.637942,0.599606,0.360149,0.292679,-0.342242,0.752469,-0.111500,-0.050475,0.213005,-0.051860,0.932092,0.073166,0.089598,0.232557,0.196323,0.088908,0.278853,-0.376843,0.547566', '1292211', '4301613', '1291835', '6511042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2006172', '太行山上', '历史', '1937年日军全面侵华后，华北危急。国共合作的背景下，红军改编为八路军，在总司令朱德（王伍福 饰）率领下东渡黄河奔赴前线抗战。山西实权人物阎锡山面对“国、共、日”三股力量颇为头疼，提出“守土抗日”口号，在民族大义的影响下，于形式上支持八路军抗日。朱德筹划于日军进犯山西的必经险地平型关截击，115师师长林彪临战指挥出色，成功击败板垣师团，史称“平型关大捷”。同时八路军用灵活的战术亦减轻了国军战场的压力。不久日军以优势兵力、装备围攻太原一线，蒋、阎战略判断失误，正面战场接连失败，八路军转入敌后根据地建设，自此拉开了军民抗击日寇的伟大事业……©豆瓣', '王伍福', '韦廉', 6.8, 8604, 'tt0847899', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2361227637.jpg', 3.7, 8.9, 43.7, 30.8, 12.8, '-0.257920,0.002974,-0.652989,0.736069,0.498926,0.288651,-0.438795,0.158350,-0.369499,0.191805,0.262427,0.259678,0.603263,-0.679860,0.098324,-0.756137,-0.139982,-0.910885,-0.122114,0.404586,-0.098343,-0.452149,-0.708003,-0.484536,-0.134041,-0.150324,0.760922,0.706064,-0.540468,0.356595,0.135423,0.314673,0.285486,0.472348,0.433853,0.066318,-0.039058,-0.599041,-0.539070,0.111422,-0.252278,-0.471532,-0.217812,0.015075,0.082580,0.247494,0.819825,-0.337810,-0.007433,-0.231439,0.140776,-0.191644,0.070806,-0.012597,0.740235,0.240828,-0.138110,0.103139,0.091439,0.290628,-0.310562,-0.146650,-0.373889,-0.394992,0.118165,-0.112840,-0.399321,0.502723,-0.382912,0.791552,0.261675,-0.337772,-0.189198,1.259668,0.256087,0.092618,-0.484008,0.225767,-0.011683,0.242826,0.461624,-0.153140,-0.318044,-0.698347,-0.167103,-0.093942,0.178169,-0.555456,0.259711,-0.131726,-0.027577,-0.390696,0.628354,0.146098,-0.542873,-0.210480,-0.194030,-0.055577,0.082114,0.273011,0.152505,-0.660752,-0.112779,-0.253028,-0.267088,0.532381,0.193847,0.365374,0.687037,-0.569045,-0.578575,0.212828,0.172621,-0.450802,0.271642,0.439854,0.194413,-0.141676,0.371982,0.422414,-0.418594,0.443520,0.181252,0.250795,-0.612269,-0.170418,0.135690,0.194473', '1307201', '1424551', '1424552', '26852888');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2009342', '龙之战', '动作', '朝鲜古老传说中，天界生活着许多巨蟒，它们中间德行最高的将有机会变成龙。每五百年会有一名女性被选中，她将利用龙珠（Yeouijoo）帮助巨蟒实现向龙的蜕变，可是邪恶之蟒布那基（Buraki）处心积虑要夺取正义之蟒蛇伊莫吉（Imoogi）手中夺取化龙的机会，为此不惜召唤魔兽大军攻掠拥有龙印少女所在的城池。少女和保护她的恋人逃亡寻找伊莫吉，但男孩却违背誓言，一切以悲剧收场。五个世纪过去，童年时代曾听说过巨蟒传说的新闻记者伊森·肯德里克（杰森·贝尔 Jason Behr 饰）意识到，发生在洛杉矶的一连串神秘事件都与布那基（Buraki）和龙印少女有关。及至与女孩萨拉（阿曼达·布鲁克斯 Amanda Brooks 饰）邂逅后，一切似乎变得愈加明朗。穿越了数个世纪的龙之战，正义与邪恶的战火再次点燃……©豆瓣', '杰森·贝尔', '沈炯来', 4.4, 20112, 'tt0372873', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1597988417.jpg', 29.5, 34, 27.7, 6, 2.8, '-0.143334,0.080228,-0.476867,0.700448,-0.036636,-0.067842,0.761691,-0.278419,-0.456647,-0.190092,0.251733,0.575736,-0.266671,0.066531,0.411146,0.009713,0.014506,-0.695313,0.077034,0.010140,-0.072354,-0.285610,-0.683118,-0.020697,-0.185905,-0.564146,0.817008,0.211398,-0.189976,0.228761,0.126546,0.395193,-0.432367,0.204889,-0.199613,-0.127812,-0.140845,-0.046727,-0.186361,0.207563,-0.090291,-0.085619,-0.019904,0.383658,-0.305159,0.147815,0.598810,-0.608805,0.062869,-0.422732,0.535248,-0.185412,-0.091898,0.186027,0.322578,0.100345,0.098837,0.306541,0.060955,-0.186709,0.230176,-0.248226,-0.530208,-0.035098,-0.106657,0.201160,-0.484454,0.236746,0.114172,0.079310,0.342335,-0.291959,0.074728,0.377975,0.404618,0.160137,-0.071171,-0.197174,-0.652637,-0.007491,0.669441,-0.247866,-0.297976,0.114906,0.044887,-0.533139,-0.215618,-0.229763,-0.218337,0.160763,0.409455,0.278651,-0.092029,0.575457,-0.850627,-0.217072,-0.460210,0.044093,0.204007,-0.168865,-0.248217,-0.415658,-0.211119,-0.150308,-0.210355,0.139407,-0.155904,-0.282638,0.638129,-0.862802,0.292569,0.488228,0.451586,-0.354866,0.459013,-0.307400,0.196366,-0.273022,0.256882,0.470926,0.079245,0.239287,0.026167,0.066135,-0.007735,0.170148,-0.322765,0.598888', '26759819', '1308837', '26290398', '3990098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2009392', '真爱满行囊', '剧情', '贝蒂（Alba Gaïa Kraghede Bellugi 饰）是个敏感而胆小的小女孩，和爸爸妈妈一起住在精神病疗养院旁边一间阴森的大屋里。贝蒂整天都生活在巨大的孤独中：姐姐快乐的离家上学了、爸爸妈妈感情破裂、漆黑的大屋深处、昏暗的天空……一天，从疗养院里逃出了一个英俊的小伙子伊凡（本杰明•莱蒙 Benjamin Ramon 饰）。当贝蒂发现了虚弱的伊凡时，好心的她将他藏在了家里的杂物仓库。他们度过了一段快乐的时光，然而，警察也开始搜索伊凡了。为了他的安全，贝蒂要带着伊凡上路了。©豆瓣', 'Alba Gaïa Kraghede Bellugi', '尚皮耶·亚莫斯', 8.3, 15152, 'tt0478687', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p674583978.jpg', 0.2, 0.9, 16.5, 49, 33.4, '0.433247,-0.008842,-0.823137,0.371855,-0.312052,-0.372602,1.235303,0.299909,-0.463851,-0.083618,0.198126,0.651426,0.066102,0.777549,-0.038045,0.508549,-0.476659,-0.439503,-0.168537,-0.213977,-0.421721,-0.344461,-0.289499,-0.416793,0.048747,-0.175105,0.116500,0.213364,0.321153,0.477753,-0.001810,-0.145455,-0.248321,0.601794,-0.304628,-0.052678,0.110410,-0.017305,0.053413,0.154634,0.101985,-0.264892,-0.118888,0.079644,0.249350,0.362975,0.840579,-0.016554,-0.012438,0.236576,0.181970,-0.071820,-0.312340,0.191674,0.121082,-0.067384,0.185750,-0.018424,-0.447322,0.045987,-0.044267,-0.199860,-0.347523,0.185522,-0.132484,0.168049,-0.605498,0.858650,0.109846,-0.155949,0.439297,-0.473959,0.398461,0.063435,-0.189685,0.521729,-0.277856,0.105319,-0.496790,0.263292,0.431340,-0.352127,-0.145517,0.367476,-0.456441,-0.276185,0.038153,0.193924,-0.788565,-0.399732,0.546592,-0.280642,-0.491736,0.056892,-0.714451,0.317677,-0.198106,-0.125327,-0.403411,-0.334560,-0.480142,-0.382367,0.029557,-0.371106,-0.379098,0.150857,-0.378125,-0.044626,0.682701,-0.597628,0.408965,0.711483,0.293711,-0.062671,0.862379,-0.167642,0.335834,0.156304,0.154006,0.370238,-0.116583,0.610056,0.405855,0.564724,-0.348395,0.230377,-0.755684,0.668190', '1302133', '21619567', '1419992', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2010972', '亡命驾驶', '剧情', '黑夜里，他（瑞恩·高斯林 Ryan Gosling 饰）协助黑帮分子抢劫，是运送车手。白天，他在好友香农（布莱恩·科兰斯顿 Bryan Cranston 饰）的车行从事电影飞车特技工作。在一次逛超市时，他邂逅了艾琳（凯瑞·穆丽根 Carey Mulligan 饰）母子， 双方互有好感，并度过愉快的周末。不过，艾琳的老公斯坦德出狱了，这让他们的感情被拦腰斩断，尽管双方心有灵犀，却只剩无奈。香农把他推荐给黑帮大佬伯尼和尼诺。与此同时，他无意中发现斯坦德被人痛扁，原来后者在狱中欠了保护费。为了偿还高利贷并保证母子平安，斯坦德决定再次铤而走险。他为了艾琳决定帮斯坦德完成这一票。然而，在打劫银行的过程中，斯坦德被店主意外击毙，而他和女同伙布兰奇陷入了黑吃黑的迷局……丹麦导演尼古拉斯`温丁`雷弗恩凭此片获64届戛纳电影节最佳导演奖。©豆瓣', '瑞恩·高斯林', '尼古拉斯·温丁·雷弗恩', 7.4, 71768, 'tt0780504', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1221329447.jpg', 1, 5.3, 34.1, 42.1, 17.4, '0.241935,0.095759,-0.535019,0.212788,0.107256,-0.488205,0.566229,0.141694,-0.401309,-0.063975,0.143617,0.655932,-0.270497,-0.058913,0.192279,-0.054335,-0.506069,-0.592996,0.042811,-0.114446,0.022954,-0.320157,-0.164297,-0.175018,-0.052362,-0.110075,0.296844,0.071026,-0.037931,0.496130,0.324717,0.182993,0.047554,0.530494,-0.096087,0.314014,0.314443,-0.105847,-0.388927,0.345687,0.060287,-0.238510,-0.122527,0.072523,0.342992,0.379569,0.678899,-0.039265,-0.167673,0.031788,0.118810,-0.407053,-0.090201,0.000924,0.118058,0.036401,0.330250,0.065944,-0.134767,-0.054249,0.404061,-0.111764,-0.556506,0.140853,-0.022816,-0.026356,-0.551461,0.549341,-0.238286,0.245569,-0.003596,-0.123309,0.159253,0.241876,0.434706,0.014022,0.000818,-0.105637,-0.448602,0.399362,0.635940,-0.269261,-0.094356,0.274303,-0.262347,-0.524524,0.036844,-0.131321,-0.047318,0.033541,0.699696,-0.163281,-0.148246,0.143737,-0.363153,-0.163960,-0.092351,-0.066229,-0.338309,-0.482142,-0.002128,-0.671259,-0.060167,-0.103629,-0.269082,0.162733,0.191388,-0.226398,0.189205,-0.579900,0.151450,0.759884,0.385079,-0.235978,0.684049,0.084159,0.197900,-0.310571,-0.115843,-0.057734,0.244120,0.311488,0.372341,0.130819,-0.048557,-0.111570,-0.193407,0.190221', '3326747', '11541282', '3