INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2010975', '澳洲乱世情', '剧情', '英国贵族小姐萨拉•阿什莉（妮可•基德曼 Nicole Kidman 饰）孤身飞跃重洋打算说服丈夫卖掉牧澳洲场重返英伦。在澳大利亚北部港口城市达尔文，萨拉相遇牧牛者卓（休•杰克曼 Hugh Jackman 饰）。卓开车带萨拉长途跋涉前往牧场，没曾想只见到萨拉新亡丈夫的尸体。悲痛的萨拉本欲迅速卖掉牧场，可又为了保护初谋面的土著小孩诺拉（布兰登•沃特斯 Brandon Walters 饰）与地头蛇的农场经理尼尔•弗莱彻（大卫•温汉姆 David Wenham 饰）闹翻。一千五百头公牛要赶去达尔文港装船，萨拉只好求卓帮忙。牧牛之旅让萨拉与卓情定澳大利亚。婚后二人耳鬓厮磨不久，卓的流浪个性使其离开萨拉继续牧牛；而本该进行澳洲土著成人出走礼的诺拉则与其他混血儿童一起被抓入教士岛，祖父“乔治王”（大卫•盖尔菲利 David Gulpilil 饰）也入狱。与此同时二战爆发，日军轰炸达尔文港，河山破碎，萨拉的家庭危机还能否解决？本片被提名奥斯卡最佳服装设计奖。', '妮可·基德曼', '巴兹·鲁赫曼', 7.3, 51746, 'tt0455824', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2006964088.jpg', 0.7, 5.2, 38, 42.3, 13.8, '-0.028200,-0.218942,-0.558854,0.370804,0.138985,-0.483320,0.325921,0.167350,-0.228796,-0.232123,-0.024028,0.791257,0.091920,0.100930,0.540554,0.156034,-0.636228,-0.420834,-0.109750,-0.025626,-0.266889,-0.577345,0.137472,-0.084036,-0.173427,-0.211377,0.383605,-0.250588,0.012208,0.522133,0.031581,0.445200,-0.392157,0.257786,-0.084497,0.023836,0.195442,-0.201406,-0.546324,0.370375,-0.057206,0.117677,-0.103042,-0.087701,0.324012,0.193793,0.644616,-0.121663,0.518375,-0.263901,0.007196,-0.030751,0.262458,-0.021635,0.371904,-0.415516,0.003102,-0.021656,-0.094262,-0.136543,0.166818,-0.182132,0.042088,0.264502,0.036607,-0.136287,-0.391663,0.070275,-0.108070,0.238384,0.056637,-0.241432,-0.058495,0.462485,0.030411,0.054504,0.118438,0.317423,-0.284197,0.066666,0.336408,0.009000,-0.033498,-0.305271,-0.073893,-0.473762,0.257824,-0.112317,-0.360485,-0.216289,0.523455,-0.185478,0.169237,0.264502,-0.576595,-0.351080,-0.747770,-0.191029,0.095757,0.145768,0.147748,-0.771810,0.087291,-0.182862,0.109878,-0.059638,0.396226,0.095161,0.165990,-0.338664,0.370420,0.417524,0.373935,-0.282681,0.167045,-0.153288,0.442900,-0.280642,-0.092925,0.691000,0.276682,0.062114,-0.015061,0.064419,0.134020,-0.099181,-0.158045,0.189463', '3036464', '2075345', '3871833', '1292344');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2015079', '精灵宝可梦：洛奇亚爆诞', '动作', '小智（松本梨香 配音）一行人在海上遇见了危险的风暴，流落到了橘子群岛中的亚西亚岛上，这里即将举行热闹的大型庆典，而小智在意外之中遇见了庆典的圣女弗卢拉（平松晶子 配音）。弗卢拉选中了小智作为庆典的“指挥者”，他的任务是前往三圣岛，找到隐藏在岛上的玻璃球。只有集齐三颗玻璃球，才能够正式开启庆典。就这样，小智和伙伴们踏上了寻找玻璃球的旅途，哪知道不仅遇到了前来捣乱的火箭队，还遭到了闪电鸟的袭击。就在千钧一发之际，吉尔露现身捕捉了闪电鸟，之后又企图捕捉急冻鸟，吉尔露的最终目的，是召唤出传说中的神兽洛奇亚。让吉尔露没有想到的是，火焰鸟、闪电鸟和急冻鸟之前竟然开始了激烈的战斗。©豆瓣', '松本梨香', '汤山邦彦', 8.2, 5485, 'tt0210234', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171956327.jpg', 0.3, 1.5, 19.4, 45.2, 33.6, '0.201537,0.165353,-0.895702,0.512048,0.117588,-0.046275,0.406611,-0.045944,-0.082042,-0.104688,0.371781,0.663112,-0.403599,0.058266,0.250950,0.095556,-0.002516,-0.610285,-0.095404,-0.145476,-0.419789,-0.179923,-0.377451,-0.020503,0.203495,-0.539933,0.455990,0.526974,-0.173501,0.406973,0.289223,0.208127,-0.368656,0.565361,-0.229982,-0.112296,0.140273,0.307379,0.096155,0.423535,-0.347851,-0.265581,-0.038161,0.371523,0.327416,0.428095,0.702806,-0.574895,0.210552,-0.138450,-0.020732,-0.476702,0.030916,-0.034150,0.533387,-0.217320,0.178436,-0.091267,-0.070229,0.167390,-0.130148,-0.200448,-0.651907,0.150440,-0.145211,0.273939,-0.530221,0.267464,0.220161,-0.178919,0.285971,-0.322794,0.614596,0.353105,0.179054,0.280123,0.026742,0.108434,-0.464669,-0.042543,0.753904,-0.282593,-0.240513,0.258308,0.087894,-0.684249,-0.097635,-0.213868,0.234584,-0.044038,0.542630,0.277908,-0.405358,0.190927,-0.848377,0.045056,-0.323371,-0.335510,-0.025757,-0.411635,-0.244548,-0.753323,0.323864,-0.039228,-0.313921,0.317010,-0.096018,-0.157539,0.491479,-1.102086,0.386076,0.795722,0.241143,-0.100578,0.637072,-0.109669,-0.074025,-0.075283,0.130052,-0.266356,0.122369,0.547474,0.056385,0.228846,0.224577,-0.239161,-0.480766,0.440529', '1420088', '2032339', '1438591', '3044878');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2024935', '雪盲', '动作', '肃杀之夜，一架军用飞机坠毁南极大陆，机组人员全部身亡。美国位于南极洲的阿蒙森·海斯科特科学研究基地，此时迎来一年一度的圣诞假期。已在此工作两年的美丽女警凯莉·斯泰德克（凯特·贝金赛尔 Kate Beckinsale 饰）正准备回国度假，但就在这一关头，研究站接到发现尸体的报告，凯莉只得和一队人马前往调查。他们在一座峭壁前发现一具死状凄惨的尸体，经过勘察，凯莉得知死者是一名来自英国科考队的地质学家，而他死亡的背后似乎另有隐情。是时，强烈的风暴即将来袭，凯莉不得不中止行程，马不停蹄调查这起案件，希望在风暴来袭前查到凶手。在这一过程中，隐藏已久的秘密也渐渐浮出水面……©豆瓣', '凯特·贝金赛尔', '多米尼克·塞纳', 5.9, 5227, 'tt0365929', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p894816230.jpg', 3.1, 21.4, 57.4, 14.8, 3.3, '-0.007696,-0.182334,-1.108791,0.388390,0.336958,0.034038,0.777233,-0.147292,-0.408932,-0.369564,0.553275,0.652930,-0.138035,0.178862,0.458564,0.037946,-0.536018,-0.569658,-0.142758,-0.332093,-0.539303,-0.466444,-0.279717,-0.176086,0.237105,-0.378499,0.563709,0.434712,0.167185,0.728982,0.010159,0.421105,-0.483044,0.750943,-0.129953,-0.248172,0.454668,-0.144043,-0.236600,0.430659,0.123696,-0.142750,-0.205606,-0.035160,0.017965,0.544970,0.860240,-0.013080,-0.149635,0.084406,0.282943,-0.558046,0.125955,0.054541,0.963773,-0.165720,-0.126443,0.203100,-0.373642,-0.181028,0.011603,-0.107955,-0.404538,0.021596,-0.310531,0.367562,-0.246039,0.141957,-0.088314,0.170112,0.009093,-0.341548,0.453341,0.613162,-0.067277,0.192687,0.064410,0.047271,-0.304274,0.042158,0.622496,-0.116102,-0.096112,0.209960,0.129024,-0.485529,-0.023497,0.078859,-0.079903,-0.068997,0.528335,0.054951,-0.182661,0.164102,-0.549432,-0.111299,-0.551317,-0.501105,-0.170541,0.008689,-0.477446,-0.831023,-0.141947,0.083566,-0.140644,0.310350,-0.006386,-0.014198,0.261461,-0.577680,0.446559,0.481444,-0.165615,-0.158740,0.330308,-0.059410,0.194688,-0.183320,0.040524,0.296351,0.142872,0.407176,-0.172483,0.265288,0.087928,-0.293137,-0.590289,0.087270', '3011051', '3066083', '2159244', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20254219', '超级经纪人', '喜剧', '怪癖经纪人孙美美（蔡卓妍 饰）偷窥艺人东窗事发后被自己一手栽培的功夫明星剑龙（高云翔 饰）背弃，被同行抵触从而陷入事业最低谷；原收债公司恶霸麦超（杜汶泽 饰）机缘下接手一间小型模特经纪公司，转型成为经纪人，寄希望于公司艺人大红、一夜暴富。模特们皆有令人跌破眼镜的别样才艺，为捧红她们，麦超使出浑身解数，先是率领众人将剑龙发布会搅的天翻地覆，与孙美美后台大过招；后是前往爱情动作片公司洽谈演艺合作，探寻行业晦涩面；更是唆使旗下艺人陪各色老板喝酒，却阴差阳错促成了富豪与女星的痴心爱恋。在娱乐圈小试牛刀、胡乱翻腾一阵后，麦超着手实施专业造星大计划。他看中孙美美的工作能力，聘请她为这间经纪公司的首席经纪人。正处事业低谷的经纪人意外接到自己瞧不起的混混抛来的橄榄枝，在窘迫的经济状况面前，孙美美十分不情愿地出任了7个极度糟糕的女模特的经纪人。由最初的游戏人生态度到认真地拾起捧红这几个女孩的梦想，一路发生各种啼笑皆非的故事，而麦超与孙美美之间的关系也在发生着微妙的变化。', '蔡卓妍', '冯志强', 4.8, 12472, 'tt3173512', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2079042615.jpg', 16.4, 36.3, 38.5, 6.2, 2.6, '0.036348,0.228706,-0.551581,0.447045,0.168949,-0.124803,0.291467,0.441439,-0.466264,-0.307632,0.190341,0.514824,-0.500235,0.404302,0.391200,-0.396096,0.006185,-0.856102,-0.213008,0.062068,0.058389,-0.300256,-0.137401,-0.292998,-0.233715,0.151903,0.584979,0.027307,-0.241441,0.306592,0.633254,0.124461,-0.123500,0.299464,0.098846,0.076198,0.376753,0.198423,-0.451826,0.004583,0.125012,-0.291002,0.016168,-0.082370,0.201935,0.143392,0.445733,0.066951,-0.152331,-0.167214,0.438266,-0.143834,0.026132,-0.016435,0.344091,0.246847,0.215511,-0.153639,-0.333413,0.071980,0.095838,-0.210475,-0.731159,0.120940,0.281175,0.118216,-0.616955,0.120654,-0.017893,0.007471,0.022463,-0.135148,-0.069965,0.332586,0.543858,0.150676,0.168899,0.690516,-0.234217,0.378436,0.525143,0.394671,-0.014712,0.294146,-0.193351,-0.161395,-0.152683,-0.212048,-0.363370,-0.271610,0.366350,-0.083714,0.215217,0.115643,-0.587382,-0.092880,0.125278,-0.082153,0.035422,-0.269277,0.036014,-0.636853,-0.137788,-0.174897,-0.117443,-0.117704,0.265155,-0.231834,0.609939,-0.650674,-0.151070,0.279003,0.114220,-0.599412,0.629017,-0.081283,0.151984,-0.236753,-0.257282,0.016141,-0.016753,0.140910,0.071059,0.336018,-0.275018,-0.228