INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20256636', '夏威夷', '剧情', '经济遇到困难的马丁（Mateo Chiarino 饰）在欧亨尼奥（Manuel Vignau 饰）的居所附近寻找工作，却碰巧发现二人原来是儿时的玩伴。为了帮助马丁一把，欧亨尼奥提出让马丁在他的大宅当暑期工，不料却引发一场若有若无的角力游戏，令二人的感情发生微妙变化。多年不见 的儿时好友，如今社会地位已大相迳庭，他们能否扭转这场角力的主从位置？凭借《缺席》获得柏林电影节泰迪熊奖的阿根廷导演马可·伯格带来新作《夏威夷》。电影模糊了性取向的边界，以情思爱欲讲述男性之间奇特细腻的暧昧之情。©豆瓣', '曼努尔·维格诺', '马可·伯格', 8.5, 23015, 'tt2801746', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164658075.jpg', 0.3, 1.4, 15.4, 40.5, 42.4, '0.196072,0.169676,-0.692607,0.758232,0.315156,-0.200906,0.625425,0.270382,-0.371559,-0.324255,0.202466,0.705076,-0.323503,-0.070848,0.396508,-0.192372,-0.298363,-0.703460,-0.046793,0.084155,0.004998,-0.462000,-0.570163,-0.054939,-0.186137,-0.319350,0.711937,0.058047,-0.445592,0.504373,0.234793,0.257143,-0.228176,0.244311,0.120765,-0.202952,0.184898,0.278253,-0.684789,-0.040484,0.084359,-0.054569,-0.170526,0.164857,0.116827,0.460356,0.749103,-0.137651,-0.183483,0.126703,0.406246,0.101288,0.169353,-0.181827,0.238792,0.139834,0.088432,0.093696,-0.069952,-0.016078,0.096508,-0.185188,-0.554938,0.296840,0.216686,0.246905,-0.058158,0.367020,-0.017675,-0.100379,-0.093210,-0.085712,0.109285,0.589074,0.405820,0.288843,0.014719,0.145714,-0.301924,0.077083,0.676874,-0.041571,-0.378331,0.414034,-0.426552,-0.322160,0.012242,-0.162787,-0.254077,0.094194,0.353959,-0.008871,0.056858,0.471598,-0.676048,-0.147243,-0.107249,-0.104166,0.186707,-0.377216,0.147977,-0.759267,-0.354051,-0.134009,-0.125273,-0.174605,0.135834,-0.367747,0.540296,-0.760062,0.262971,0.653873,0.080922,-0.185198,0.685231,0.050854,0.238599,-0.367270,-0.265186,0.252160,-0.130260,-0.141382,-0.078709,0.158675,-0.005358,-0.120940,-0.270741,0.456739', '11541282', '1302050', '20274039', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20257326', '极品飞车', '剧情', '纽约基斯科山，小青年托比·马歇尔（亚伦·保尔 Aaron Paul 饰）和伙伴们共同经营一家改装车行，他同时也是一名技术精湛的赛车高手。虽然刚刚在一场比赛中赢得奖金，但是车行的经营状况还是到了令人堪忧的底部。恰在此时，拥有专业赛车手资格的土豪迪诺·布鲁斯特（多米尼克·库珀 Dominic Edward Cooper 饰）找上门来。迪诺此前撬走了托比的女友，两人可谓不共戴天。但是迪诺此次给他带来一单不小的改装生意，托比和伙伴们成功打造出一辆时速超过370公里的福特野马，而嫉妒心炽盛的迪诺为了最强赛车手的名号向托比发起挑战。为了丰厚的报酬，托比和好友利托·比特共同参赛。谁知迪诺导致利托死亡，事后还嫁祸托比。出狱后，托比借来他的那辆得意之作福特野马，发誓要为利托讨回公道……©豆瓣', '亚伦·保尔', '斯科特·沃', 7.3, 90075, 'tt2369135', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2172119522.jpg', 1.3, 6.1, 37, 39.6, 16.1, '0.068136,-0.038484,-0.398723,0.533086,-0.106768,-0.378570,0.376164,0.037784,-0.495511,-0.181675,0.290828,0.798100,-0.012096,-0.060808,0.515812,-0.029087,-0.078967,-0.493597,0.050820,-0.134064,-0.130300,-0.525160,-0.373504,-0.259793,-0.110980,-0.178404,0.415042,-0.130899,-0.035433,0.508191,0.302133,0.175961,0.151475,0.024061,-0.019686,-0.133774,0.364397,-0.165589,-0.222730,0.301093,-0.189731,0.083664,-0.131066,0.049463,0.320714,0.282473,0.312931,-0.010183,-0.005186,-0.096059,0.066440,-0.248169,0.262512,0.016753,0.304533,0.029722,0.249234,0.137237,0.021259,0.002235,0.026826,-0.126983,-0.711551,0.018098,-0.180967,-0.236785,-0.700068,0.359041,-0.320369,-0.127919,0.091470,-0.267854,-0.214296,0.211381,0.163984,0.207398,-0.066487,0.059120,-0.522633,-0.031432,0.614652,-0.090011,0.111654,0.269323,-0.020972,-0.382899,-0.158103,-0.443399,-0.561607,-0.140835,0.478628,-0.049531,0.312824,0.220172,-0.780013,-0.051791,-0.475380,-0.320573,-0.185976,-0.071587,0.160822,-0.785125,0.138001,-0.409135,0.050836,0.148506,0.106141,-0.411896,0.643288,-0.634910,-0.070180,0.547236,0.299117,-0.317524,0.522631,-0.212448,0.197452,-0.208994,-0.298080,-0.050599,0.231800,0.116958,0.083092,0.145686,0.261739,-0.360292,-0.007232,0.530889', '1793491', '11541282', '1870681', '10763928');
