INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20266753', '警察故事2013', '剧情', '夜幕降临，资深刑警钟文（成龙 饰）接到离家出走许久的女儿苗苗（景甜 饰）的电话，他暗怀喜悦准时来到了正进行三周年店庆的武吧。酒吧老板武江（刘烨 饰）热情地接待了他，但是酒吧内光怪陆离和乌烟瘴气的景象让钟文心生不快。稍后，苗苗抵达，眼见得纹身染发并且桀骜不驯的女儿，钟文尽量和颜悦色地与女儿沟通，可当得知武江是女儿的男朋友时还是发了脾气。就在此时，一名民工为索要工钱带着炸弹入场，钟文出手不凡解决争端，可没过多久却被人用棒球棍打晕。当他苏醒过来时，发现自己被人绑在椅子上，冷酷的武江宣布将其劫持为人质。有限的时间内，钟文不得不和这个狡猾凶狠的匪徒斗智斗勇，寻找逃脱的机会……©豆瓣', '成龙', '丁晟', 5.9, 117574, 'tt2599716', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2161934790.jpg', 6.2, 21.9, 49.9, 16.2, 5.8, '0.122092,0.239272,-0.478456,0.223512,-0.261156,-0.315470,0.510142,0.212439,-0.475934,-0.275899,0.247645,0.358226,-0.329151,0.321699,0.365336,-0.038130,-0.318498,-0.695816,-0.010450,0.048370,-0.190099,-0.286561,-0.006688,-0.079553,0.020881,-0.140842,0.163445,0.030827,0.011137,0.588801,0.289544,0.075020,-0.046301,0.622014,-0.189268,-0.068934,0.107657,-0.131865,-0.104344,0.291809,-0.040074,-0.365901,-0.150594,0.130705,0.112660,0.432508,0.672107,0.088840,-0.212648,-0.078072,0.285783,-0.276163,-0.133481,0.088087,0.132932,0.221022,0.232982,-0.073094,-0.455720,0.083215,0.128430,-0.191605,-0.425794,0.363296,-0.186060,-0.002327,-0.569935,0.355000,-0.198852,0.070858,0.109814,-0.351833,0.235098,0.168918,-0.025629,0.440528,-0.304169,0.132577,-0.458286,-0.022566,0.344597,-0.038316,0.172771,0.035640,0.126887,-0.349512,0.232767,-0.160643,-0.383235,-0.163765,0.572486,0.042900,-0.217059,-0.084159,-0.472738,-0.193262,-0.336091,0.064672,0.127445,-0.383631,-0.451186,-0.576760,0.062841,-0.233953,-0.270677,0.188406,0.042881,-0.003799,0.635122,-0.647829,0.191187,0.248263,0.236481,-0.455763,0.634437,0.211883,-0.040882,-0.186242,-0.067754,-0.165820,0.216276,0.560310,0.278726,0.324820,-0.340081,-0.344706,-0.394740,0.202527', '3041753', '1307146', '3155839', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20273800', '彷徨之刃', '剧情', '电影改编自日本著名推理小说家东野圭吾的同名小说。胜贤（郑在泳 饰）怎么也想不到，自己那乖巧可爱的女儿李秀珍（李秀彬 饰）会以一具冰冷的尸体的形式躺在自己的面前，然而事实已经发生，无法改变，李秀珍被卷入了一场谋杀案中，成为了案件里的受害者。某日，痛苦的胜贤收到了一封神秘 的信件，追随着信件中给出的线索，胜贤见到了女儿临死前最后的影像，绝望和愤怒之中，胜贤杀死了罪犯之一的哲勇，事件并没有就此结束，一位依然有杀害自己女儿的凶手逍遥法外。哲勇的死吸引了警方的注意，一直在调查李秀珍一案的刑警亿观（李成民 饰）展开了对于胜贤的追捕。©豆瓣', '郑在泳', '李正浩', 7.3, 11099, 'tt3554976', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2176645107.jpg', 0.9, 3.9, 38.4, 42.5, 14.1, '0.347606,0.033961,-0.658162,0.634613,-0.087624,0.042952,0.862672,-0.094812,-0.561460,-0.338988,0.351176,0.738617,-0.129289,0.190420,0.108179,0.019757,-0.250730,-0.889458,-0.277392,-0.143960,-0.276381,-0.557216,-0.530046,-0.147272,0.083061,-0.131187,0.572597,0.180063,-0.117517,0.598589,0.469701,0.370982,-0.375542,0.579942,0.028159,0.197383,0.142741,0.060419,0.034488,0.234244,0.118593,-0.526999,0.096141,0.410357,-0.218646,0.514947,0.722203,-0.532338,-0.275196,-0.086593,0.585812,-0.374824,-0.268425,0.322098,0.387873,0.106080,0.197451,0.300038,-0.462120,-0.163386,0.181422,0.210017,-1.125622,-0.173871,0.249987,0.579909,-0.325869,0.381042,-0.205892,0.073310,0.120213,-0.258367,0.547258,0.165826,0.386101,0.372458,-0.125450,0.018297,-0.352437,0.258664,0.489389,-0.147618,-0.289723,0.182995,-0.128608,-0.362823,-0.064260,-0.337419,-0.330884,0.409818,0.353518,0.181467,-0.412312,0.237491,-0.365636,-0.371425,-0.266726,-0.200418,-0.201691,-0.261931,-0.317084,-0.311753,-0.262598,-0.287143,-0.249008,0.023163,-0.151257,-0.454506,0.685493,-0.496683,0.092569,0.338074,0.153852,-0.384935,0.617130,0.258535,-0.125005,-0.004649,-0.113254,0.177338,0.261860,0.266062,0.211136,0.121030,0.031530,-0.386882,-0.434994,0.265866', '26678784', '25928048', '1874704', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20274039', '名侦探柯南：远海的侦探', '动画', '晴朗时节，江户川柯南（高山南 配音）和毛利小五郎（小山力也 配音）、小兰（山崎和佳奈 配音）以及少年侦探团的伙伴们一同来到京都，他们即将登上自卫队的宙斯盾战舰，体验一把出海作战的感觉，期间还结识了美丽又有着几分神秘的女自卫队员藤井七海（柴咲幸 配音）。谁知快乐的氛围很快被恐慌所替代，战舰上突然发现一条断掉的手臂，消失的自卫队员又引起军方的恐慌与猜测。原来某国神秘间谍X已悄悄登上宙斯盾，伺机盗取战舰上的绝密情报。为了找出隐藏的对手，柯南和灰原哀（林原惠美 配音）、阿笠博士（绪方贤一 配音）、服部平次（堀川亮 配音）以及远山和叶（宫村优子 配音）通力合作，与间谍展开连番斗智斗勇的较量……©豆瓣', '高山南', '静野孔文', 6.5, 59180, 'tt3303446', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1919878062.jpg', 3.3, 13.9, 49.3, 22.6, 10.9, '0.172535,-0.196449,-0.401409,0.645409,0.330124,-0.175587,0.513336,0.065150,-0.251941,-0.367990,0.276374,0.690712,-0.260776,0.127496,0.319815,0.018635,-0.650103,-0.767037,-0.187737,0.015084,-0.141954,-0.346831,-0.312845,-0.056712,-0.045409,-0.310208,0.904455,0.077342,-0.391090,0.684785,0.133512,0.289328,-0.430130,0.308608,0.200021,-0.024238,0.235316,-0.096079,-0.109001,0.042541,-0.373990,-0.211848,-0.066864,-0.088566,0.072858,0.362273,0.677898,-0.192377,0.064740,-0.073969,0.144247,-0.215598,0.120154,0.087219,0.439760,0.242116,-0.156513,-0.101186,-0.257011,-0.042507,0.096548,-0.168837,-0.574131,0.155551,-0.052518,0.048518,0.199753,0.061122,-0.123212,-0.043128,0.424131,-0.203279,0.150625,0.262007,0.342575,0.149746,-0.367416,0.443693,0.010033,0.042518,0.433525,-0.004405,-0.090993,0.024172,0.075438,-0.407782,-0.374953,-0.252858,-0.120878,-0.160803,0.382415,0.077767,0.148724,0.095041,-0.803817,-0.049500,-0.189155,-0.145441,-0.093328,-0.155625,-0.050407,-1.120776,-0.022924,-0.229927,-0.147779,0.231342,0.418575,-0.247627,0.758377,-0.842855,-0.063737,0.563777,0.098065,-0.051018,0.144856,-0.116991,-0.244337,-0.421383,-0.145296,0.023096,0.230099,0.461518,0.239928,0.286430,-0.369460,-0.158732,-0.332067,0.052844', '2369613', '25723905', '5403927', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20276229', '007：无暇赴死', '动作', '世界局势波诡云谲，再度出山的邦德（丹尼尔·克雷格 饰）面临有史以来空前的危机，传奇特工007的故事在本片中达到高潮。新老角色集结亮相，蕾雅·赛杜回归，二度饰演邦女郎玛德琳。系列最恐怖反派萨芬（拉米·马雷克 饰）重磅登场，毫不留情地展示了自己狠辣的一面，不仅揭开了玛德琳身上隐藏的秘密，还酝酿着危及数百万人性命的阴谋，幽灵党的身影也似乎再次浮出水面。半路杀出的新00号特工（拉什纳·林奇 饰）与神秘女子（安娜·德·阿玛斯 饰）看似与邦德同阵作战，但其真实目的依然成谜。关乎邦德生死的新仇旧怨接踵而至，暗潮汹涌之下他能否拯救世界？', '丹尼尔·克雷格', '凯瑞·福永', 6.6, 270361, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2707553644.jpg', 0.9, 9.9, 53, 29.9, 6.4, '-0.036129,0.233482,-0.371659,0.418011,0.346529,0.174524,0.555347,0.092158,-0.217584,-0.068173,0.541757,0.447088,-0.305311,-0.262070,0.642032,-0.117355,-0.456287,-0.674952,0.003306,-0.113140,-0.007678,-0.300116,-0.647575,-0.099782,0.052095,-0.409781,0.684411,0.376002,-0.365827,0.164772,0.512598,0.617681,-0.425710,0.492880,0.142185,-0.161058,0.074521,-0.228878,-0.343266,0.077213,-0.054008,-0.370197,-0.279369,0.496730,-0.157807,0.359541,0.695257,-0.551600,0.204486,-0.113414,0.343252,-0.147604,-0.105772,-0.215786,0.214563,-0.188782,0.016554,0.372872,0.287787,-0.095649,0.126664,-0.375194,-0.598721,0.020040,0.219800,0.146707,-0.173172,-0.011605,-0.412649,0.217212,0.112758,0.155937,0.004861,0.189870,0.507944,0.140591,-0.092265,0.090111,-0.304437,0.049466,0.298649,0.082701,-0.403464,0.153174,-0.098554,-0.418334,-0.339244,-0.256787,-0.308145,-0.054595,0.455378,0.072246,0.095967,0.676881,-0.593291,0.031970,-0.660158,0.081072,0.081721,-0.282455,-0.262609,-0.650111,-0.236880,-0.079987,-0.128285,0.080430,-0.103844,-0.056391,0.653994,-0.405471,-0.057748,0.286900,0.073923,-0.109296,0.322467,0.015091,0.371999,-0.525481,-0.335539,0.479895,0.062866,-0.077681,-0.177753,0.149435,-0.291506,-0.023788,-0.155140,0.351194', '10467125', '30382416', '7051375', '30434174');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20276230', '汤姆的农场旅行', '剧情', '男友因车祸意外去世，汤姆（泽维尔·多兰 Xavier Dolan 饰）驱车前往男友家人所在的偏远农场参加葬礼，才得知原来男友母亲并不知道儿子的性取向。男友哥哥弗朗西斯（皮埃尔 - 伊夫·卡迪纳尔 Pierre-Yves Cardinal 饰）恐同而暴力，他威胁汤姆不得透露与弟弟的真实关系，并野蛮的将汤姆囚禁在农场。始料未及的是汤姆渐渐喜欢上农场生活，而弗朗西斯和母亲在与汤姆的接触中也陷入一场心理游戏…《汤姆的农场旅行》讲述一位年轻同志参加男友葬礼，发现自己与男友的关系是秘密，然后更进一步发现恋人的母亲与哥哥也有自己的秘密；由于他的意外出席，引发哥哥不惜使用暴力也要隐藏的动机。这是一部心理惊悚片，全片以层层剥丝的方式来挖掘当事人隐晦的相互关系，风格冷僻，过程令人不寒而栗。电影由年轻加拿大导演多兰自编、自导、自演、自剪，并自做服装设计，再现了他的多兰美学与“不可能之爱”。《汤姆的农场旅行》入围第70届威尼斯电影节主竞赛单元，获得国际影评人费比西奖(FIPRESCI)。', '泽维尔·多兰', '泽维尔·多兰', 7.6, 11333, 'tt2427892', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2112760399.jpg', 0.6, 3.3, 31.2, 45.7, 19.1, '0.044888,-0.184778,-0.467775,0.712897,0.070117,-0.138535,0.567851,0.121131,-0.489889,-0.435221,0.215180,0.820823,-0.187363,0.076933,0.429480,-0.073009,-0.355169,-0.577980,-0.002518,-0.030667,0.054324,-0.710329,-0.235667,-0.209833,0.025350,-0.452249,0.623345,-0.132928,-0.381109,0.523837,0.498897,0.337529,-0.309258,0.327850,0.134622,-0.150080,0.300455,0.251798,-0.559682,0.100230,0.115123,0.011879,0.102830,0.104939,0.191997,0.452337,0.599177,-0.110245,-0.179478,-0.079764,0.554319,0.019640,-0.087796,0.043866,0.220975,-0.027945,0.415274,0.429061,0.129207,0.035357,0.088452,-0.269789,-0.549601,0.121616,0.350781,0.017514,-0.322231,0.310198,-0.186173,-0.131686,0.167356,-0.212547,0.204770,0.306755,0.399178,0.328101,-0.063662,0.083202,-0.094189,0.238503,0.629977,-0.175761,-0.030257,0.395110,-0.334199,-0.471178,0.005303,-0.236187,-0.507812,0.309009,0.035895,-0.130516,-0.063523,0.305749,-0.459386,-0.199085,-0.052540,-0.161014,0.253547,-0.351652,0.257575,-0.718958,-0.158999,-0.229000,-0.112191,-0.255126,0.049843,-0.431734,0.397706,-0.849772,0.362568,0.598689,0.317539,-0.589518,0.681683,0.210080,0.056408,-0.507284,-0.162016,0.268185,-0.075996,0.068571,-0.224205,0.115240