INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20277285', '喜羊羊与灰太狼之喜气羊羊过蛇年', '喜剧', '在晴朗明媚的一天，羊村正举行防御系统揭幕仪式，这是慢羊羊村长的最新发明，该系统可以抵制上千伏的电压。谁知这时灰太狼突然出现搅局，不久前他发明了羊味罐头，由此成为当今最炙手可热的科学家，可是没能抓到小羊依然是他心中隐隐的伤痛。灰太狼操纵天气控制器与羊羊特工队展开殊死搏斗。受伤的喜羊羊偶然结识了熊猫旺财，而对方的真实身份是灭绝了许久的蛇。受挫的灰太狼专心升级天气控制器，却忽略了老婆和灰灰的感受，而他的失误也导致天气控制器失控。危难时刻，青青草原的各位意外发现久远以前蛇族发明的诺亚神舟。可是为了启动神舟，必须得到蛇族的帮助。为此，羊羊特工队和机械喜羊羊踏上凶险莫测的冒险旅程……本片为《喜羊羊与灰太狼》系列第五部剧场版动画。©豆瓣', '祖晴', '简耀宗', 6.5, 9167, 'tt2772570', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1835975583.jpg', 9.2, 13.6, 37.8, 19.1, 20.3, '0.235004,0.110577,-0.543600,0.379276,0.257315,-0.042497,0.585417,-0.047327,-0.330998,-0.288129,0.374244,0.443684,-0.297134,-0.019822,0.003201,0.046225,-0.158764,-0.177574,0.115924,0.122098,-0.200052,-0.110258,-0.519099,-0.104348,0.059927,-0.389881,0.873957,0.316132,-0.394213,0.291897,0.292151,0.215189,-0.119155,0.460368,-0.271043,-0.135667,-0.129710,-0.009819,0.011530,0.149731,-0.075751,-0.230686,-0.041185,0.397516,-0.070101,0.196374,0.656757,-0.505959,-0.453439,-0.217092,0.462848,-0.412286,-0.071380,-0.182835,0.356478,0.136176,-0.127951,-0.025172,0.176170,0.012859,-0.032045,-0.059774,-0.705314,0.056086,-0.120011,0.204035,-0.234667,0.047100,-0.214841,0.120248,0.235269,-0.468331,0.127448,0.278417,0.345953,0.514121,-0.158029,0.304598,-0.421047,0.112394,0.506814,-0.179622,-0.242077,0.516020,0.049153,-0.547718,-0.000549,-0.294700,-0.223880,-0.012404,0.296683,0.276136,-0.213871,0.408840,-0.725018,0.100348,-0.131297,-0.349103,-0.095137,-0.252151,-0.162950,-0.504586,-0.092348,-0.334867,-0.170342,0.120495,0.070307,-0.489576,0.533133,-0.841396,0.327693,0.331092,0.017082,-0.165484,0.443055,-0.011311,-0.173145,-0.269523,-0.066887,0.004385,0.002304,0.304969,0.209696,0.071592,0.174885,-0.230489,-0.425298,0.439000', '26759819', '26759820', '5364978', '30272753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20277433', '焦点', '剧情', '尼基（威尔·史密斯 Will Smith 饰）是一位经验非常丰富的诈骗犯，和他搭档的是名叫杰斯（玛歌特·罗比 Margot Robbie 饰）的女扒手，两人在专业知识上互通有无，彼此之间结下了深厚的友谊。当他们之间的感情逐渐突破了单纯和合作关系后，尼基为了保全自己的事业，毅然决然的甩掉了杰斯。一晃眼多年过去，尼基和杰斯在布宜诺斯艾利斯重逢了。原来，杰斯在尼基离开她之后并没有一蹶不振，而是在行当里不断的精进打磨，时至今日，她已经是一位技巧非常高超的女飞贼了。尼基原本的精心策划的行骗计划，因为杰斯的出现而变得险象环生。©豆瓣', '威尔·史密斯', '格伦·费卡拉', 6.9, 44226, 'tt2381941', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2228702598.jpg', 0.8, 7, 47.3, 35, 9.9, '0.390303,-0.054884,-0.744027,0.685600,-0.283403,-0.563434,0.912220,0.154413,-0.572547,-0.254338,0.166547,0.928473,-0.240814,-0.105174,0.225372,-0.299553,-0.263977,-0.866162,0.049439,-0.394022,-0.299734,-0.837610,-0.588181,0.022215,-0.294848,-0.440528,0.572085,-0.085205,-0.277274,0.534311,0.303294,0.059190,0.076296,0.389111,-0.072173,0.065590,0.213030,-0.040510,-0.229057,0.054939,0.096049,-0.122284,-0.152068,-0.042836,0.089842,0.528936,0.465833,-0.146288,0.055878,0.041649,0.071377,-0.218667,0.006488,0.122822,0.257325,-0.186414,0.258856,0.240090,-0.237913,-0.302992,0.118991,-0.146921,-0.954888,0.250910,-0.037869,0.086483,-0.767853,0.691390,-0.055558,-0.358424,0.025513,-0.616272,-0.011016,0.524868,0.315883,0.167008,-0.090162,-0.198545,-0.441796,0.106644,0.762267,0.211828,-0.232049,0.660837,-0.086869,-0.423085,-0.219942,-0.139429,-0.291158,-0.420773,0.694517,-0.042292,-0.162207,0.405688,-0.709672,0.097008,-0.333623,0.078904,-0.136310,-0.399959,0.151827,-0.723830,-0.428753,-0.946835,-0.482977,-0.058271,-0.117921,-0.451193,0.818613,-1.269669,0.035917,0.469410,0.150740,-0.269210,0.539184,-0.033331,0.107648,-0.034291,-0.299167,0.199250,0.006940,0.211078,0.341730,0.508991,-0.062498,-0.063255,-0.360511,0.841630', '3006892', '1299556', '1783461', '35144311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20277632', '飓风营救3', '动作', '前任特工布莱恩·米尔斯(连姆·尼森 Liam Neeson 饰)在经历了连番家庭保卫战之后，如今貌似平静的生活仍然暗流涌动：女儿金（玛姬·格蕾斯 Maggie Grace 饰）怀孕却不敢告知他，前妻莱诺蕾和丈夫斯图尔特（多格雷·斯科特 Dougray Scott 饰）并不完美的生活令她重新考虑布莱恩，而斯图尔特登门要求布莱恩不再纠缠莱诺雷……不久，布莱恩惊讶的发现莱诺雷死在了自己的床上，被警方列为头号嫌疑人的布莱恩只能依靠暴力脱身，并在警局局长多泽勒（福里斯特·惠特克 Forest Whitaker 饰）的布置中逃亡，以便查出真凶。很快，布莱恩发现前妻的死与斯图尔特和俄罗斯黑帮的交易有关，而金可能成为下一个受害者……©豆瓣', '连姆·尼森', '奥利维尔·米加顿', 6.6, 87163, 'tt2446042', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2224368429.jpg', 1.2, 9.9, 54.2, 26.2, 8.4, '0.179268,0.070321,-0.753672,0.344241,-0.114396,-0.327517,0.800704,0.138303,-0.556295,-0.447759,0.016332,0.676621,-0.174780,0.036821,0.333742,0.003854,-0.474838,-0.656779,0.171064,-0.124319,-0.211503,-0.769600,-0.271079,-0.162787,0.011293,-0.370007,0.400610,0.000398,-0.066304,0.304484,0.449685,0.570751,-0.067440,0.372318,0.185657,0.096408,0.319551,-0.013705,-0.362021,0.258476,0.069288,-0.127641,-0.056792,0.120886,0.360194,0.410501,0.304073,-0.236867,-0.009083,-0.054072,0.162949,-0.167462,-0.036196,0.118767,0.277503,-0.300599,0.084197,0.337445,-0.239859,-0.185875,0.181666,0.064822,-0.703758,0.065467,0.130393,0.267391,-0.450601,0.194298,-0.217725,0.107924,-0.193193,-0.225029,0.026446,0.537701,0.211665,0.087594,-0.144551,0.242014,-0.348459,0.123141,0.465483,0.113121,-0.218747,0.049510,-0.208216,-0.265152,0.001708,-0.089693,-0.425300,-0.054953,0.504040,0.039291,-0.101039,0.352130,-0.222345,-0.251413,-0.584904,-0.134511,-0.191168,-0.262605,0.144089,-0.652400,-0.243387,-0.302459,-0.288413,-0.013437,-0.110000,-0.255479,0.236952,-0.677090,0.224476,0.294548,0.270172,-0.379996,0.269455,0.365064,0.282914,-0.396367,-0.076013,0.492904,0.385460,0.052114,0.250188,0.096337,0.037262,-0.230091,-0.194517,0.241500', '1307442', '1293145', '26930375', '5966609');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20278505', '前目的地', '科幻', '时空劳工局特工（伊桑·霍克 Ethan Hawke 饰）曾经奉命回到20世纪70年代，以阻止当年给城市造成巨大伤害的恐怖分子“闪灭炸弹客”的破坏活动。谁知他的任务失败，在经过漫长的康复后，他再度踏上征程，发誓要将闪灭炸弹客绳之于法。此番他以酒保身份混迹市 井，某天偶然结识了笔名“未婚妈妈”的作家（莎拉·斯努克 Sarah Snook 饰）。作家向他讲述了其匪夷所思的人生。当年作家曾是名叫简的孤儿，性格古怪的她在应聘太空公司失败后，短暂坠入爱河，并生下一名女婴，结果她的人生也发生了翻天覆地的变化。特工打算带着“未婚妈妈”去杀掉那个负心汉，然而真相却并没有那么简单……©豆瓣', '伊桑·霍克', '迈克尔·斯派瑞', 7.9, 187820, 'tt2397535', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2219662154.jpg', 0.4, 2.1, 22.8, 49.1, 25.6, '-0.008615,0.016330,-0.518573,0.313342,0.004360,-0.187534,0.805374,-0.108138,-0.525607,-0.401960,0.193279,0.728048,-0.101759,-0.081189,0.321636,-0.015300,-0.227803,-0.558353,0.018670,-0.191983,-0.302128,-0.448754,-0.019926,-0.114948,0.130552,-0.266077,0.583705,0.120118,-0.195157,0.314739,0.156007,0.342327,-0.236259,0.416660,-0.282054,0.200325,0.103726,0.257575,-0.476099,0.343342,0.042136,-0.190653,-0.028096,0.232289,-0.217329,0.294003,0.579183,-0.166922,-0.228055,-0.125539,0.436453,-0.270263,-0.177429,-0.113727,0.361646,0.051088,0.129273,0.206756,0.042451,-0.152134,0.052424,-0.345693,-0.499532,-0.018132,0.169678,0.101080,-0.516294,0.212750,-0.169152,0.264900,0.002880,-0.176819,0.047946,0.335283,0.457411,0.242037,-0.237369,0.284083,-0.324727,0.480738,0.710462,0.102724,-0.390749,0.407901,-0.120482,-0.458383,0.014064,-0.317428,-0.415039,0.398391,0.306385,0.186947,-0.444596,0.364097,-0.330327,-0.161358,-0.462166,0.032965,0.139997,-0.268750,-0.272592,-0.297276,-0.039918,-0.064896,-0.439869,-0.007810,-0.068964,-0.201445,0.456866,-0.841255,0.410431,0.687422,0.262358,-0.490479,0.608439,0.069641,-0.030231,-0.419323,0.183473,0.446690,0.062375,0.521901,-0.233236,0.169359,0.105539,-0.275227,-0.257694,0.131489', '30345227', '1302384', '1308755', '1908318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20278795', '漫漫北寻路', '剧情', '19世纪末，一位俄罗斯姑娘为了追寻作为极地科学和探险家的祖父的足迹，而毅然决然地放弃父母安排的婚礼，踏上冒险征程！', '克丽丝塔·特瑞特', '雷米·沙耶', 8.2, 10838, 'tt2262345', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315133763.jpg', 0.2, 0.8, 16.8, 51.9, 30.2, '0.028840,-0.190979,-0.566199,1.090487,-0.034628,-0.696832,0.021963,-0.215793,-0.257840,-0.464474,0.323799,1.324091,0.649369,0.273850,0.854885,0.142243,-0.083657,-0.457845,-0.054605,0.171127,-0.345584,-0.374019,0.127184,-0.298484,0.046468,-0.162056,1.330398,0.617431,-0.394806,0.883950,0.359126,0.149605,-0.093645,0.093768,-0.404548,-0.424855,0.030503,0.129516,-0.689932,0.315009,-0.218440,0.268501,-0.163100,-0.156951,-0.131664,0.177208,0.683154,-0.449623,0.302356,-0.524013,0.502879,-0.714582,0.338515,-0.062935,0.022709,0.257971,-0.081232,0.985455,0.135507,-0.155926,0.060669,-0.610119,-0.684004,0.104108,0.300457,0.043877,-1.012208,0.212575,-0.036951,-0.032874,0.106749,-0.787773,0.267764,0.644027,0.465331,0.255276,-0.170348,0.205080,0.157136,0.357076,0.848421,-0.102137,0.228054,0.016042,-0.069655,-0.440437,0.557604,-0.317485,-0.765018,-0.054210,-0.196853,0.141897,-0.096561,0.291952,-0.704611,-0.122319,-0.501919,-0.612408,0.275257,-0.621176,0.150534,-0.583077,0.282937,0.096781,0.053424,0.049146,0.076379,-0.335562,0.625811,-0.526221,0.481767,0.667026,0.365700,-0.964440,1.124874,0.306893,0.120904,-0.601592,0.038057,0.716794,-0.308240,0.275688,-0.739129,-0.154679,0.122138,0.052954,-0.449247,0.138341', '1780122', '1307200', '1303390', '26220759');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20278806', '永远十六岁', '喜剧', '电影讲述28岁的女主角无法承受男友求婚的压力，她选择以与中学生交朋友的方式来逃避。凯拉·奈特莉在片中扮演一个叫做“梅根”（Megan）的年轻女人，她的男友（马克·韦伯）策划了一场别出心裁的求婚，结果吓坏了她，于是借着休假的名义和16岁的妹妹安妮卡（科洛·莫瑞兹）一起找了 个地方躲了起来。萨姆·洛克威尔在片中将扮演一个叫做“克莱格”（Craig）的老男人。', '凯拉·奈特莉', '琳·谢尔顿', 6.4, 7479, 'tt2034031', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196308777.jpg', 2.6, 14.3, 52.3, 23.2, 7.5, '0.321264,-0.232140,-0.500245,0.688696,-0.587440,-0.189898,0.870694,0.225928,0.154659,-0.280386,0.241085,1.005855,-0.230349,0.279729,0.683636,0.165535,-0.224904,-0.671175,0.051650,0.024182,-0.024361,-0.613217,-0.157647,-0.275398,-0.014658,-0.421713,0.460042,-0.651806,-0.050892,0.250496,0.693703,0.238634,0.279573,0.249674,0.125415,0.075111,0.430228,-0.190925,-0.175350,0.666596,0.141547,-0.168956,0.003832,0.245680,-0.118142,0.439969,0.636678,-0.222216,0.258232,-0.011513,0.448396,-0.159091,-0.086019,0.093481,0.099599,-0.445944,0.294252,-0.212946,-0.050237,-0.133541,0.377626,-0.159436,-0.742182,0.212919,0.132236,-0.007345,-0.613880,0.288584,-0.194063,0.131239,0.156353,-0.591109,0.023754,0.262407,0.211873,0.194188,-0.292316,0.060036,-0.289540,0.257263,0.466970,0.265647,-0.136542,0.460270,-0.359273,-0.219136,0.172908,-0.253679,-0.900925,0.002255,0.367896,-0.423389,-0.437748,-0.040614,-0.427817,-0.479595,-0.325872,-0.062149,0.011773,-0.556404,-0.031614,-0.611529,-0.351207,-0.216673,-0.089434,-0.262284,-0.058666,-0.427237,0.536906,-0.757111,0.024081,0.996033,0.121930,-0.271705,0.872142,0.448302,0.144775,-0.239039,0.166253,0.034534,-0.227253,0.126474,0.038966,0.537946,0.198608,-0.022227,-0.440766,0.648966', '34890458', '30167633', '3326747', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2027899', '12怒汉：大审判', '剧情', '翻拍自1957年Sidney Lumet的12 angry men。一个车臣男孩被指控谋杀自己俄罗斯军官的养父，所有证人和证据均对他不利，12位陪审团成员对此展开了讨论，他们将决定男孩今后的命运。12名陪审员来自不同的行业，不同的种族。刚开始的时候，每个人心不在焉， 对这起案件并不在乎，除了一个物理研究员之外，他们都认为男孩有罪。但是，物理研究员唤起了其他11个人对生命的尊重，他们开始认真讨论这起案件，讲述各自生活中的故事和经历，在决定男孩命运的同时，也审视自己的内心世界。最终，当他们达成一致意见的时候，陪审团主持人（Nikita Mikhalkov 饰）的决定却出乎意料……©豆瓣', '谢尔盖·马科韦茨基', '尼基塔·米哈尔科夫', 8.4, 33657, 'tt0488478', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2157181880.jpg', 0.5, 1.9, 14, 42.5, 41.1, '0.551654,-0.115957,-0.572179,0.688376,-0.276337,0.062380,0.817574,-0.045009,-0.708284,-0.245667,0.274529,0.737341,-0.071298,0.148215,0.240693,-0.420258,-0.612345,-1.051206,-0.182220,-0.156387,-0.355498,-0.989223,0.045114,-0.439487,-0.297629,-0.139822,0.616534,-0.085656,0.015642,0.403556,0.342837,0.174104,-0.179822,0.545435,0.119721,-0.205446,0.342711,0.071739,-0.390387,-0.061535,0.025174,-0.185113,-0.166364,0.444437,-0.141883,0.670334,0.800736,-0.550992,-0.291736,-0.130857,0.295458,-0.357185,-0.123010,0.441549,0.594330,0.240416,0.141113,0.517036,0.226609,-0.145170,-0.242548,0.128212,-0.854901,-0.283391,0.352275,0.254256,-0.354354,0.524159,0.100221,0.266923,-0.047323,-0.234008,0.129792,0.298387,0.627412,0.425112,-0.253009,-0.082768,-0.278031,0.163594,0.702878,0.063462,-0.206267,0.156681,-0.555224,-0.634909,-0.404826,-0.068378,-0.384157,0.159581,0.007441,0.348350,-0.135629,0.327661,-0.648913,-0.034919,0.088588,-0.431134,0.024618,-0.793202,0.090634,-0.453221,-0.127761,-0.255099,-0.391887,0.130553,0.159986,-0.332652,1.187881,-0.843694,-0.106559,0.362131,0.361284,-0.855164,0.670024,0.327205,0.229960,-0.634987,-0.207527,0.106231,0.066923,0.104282,-0.182065,0.301243,0.198273,-0.169100,-0.122457,0.241889', '27602116', '4301278', '30159456', '1304034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2027923', '第一诫', '动作', '刑警李国强（余文乐 饰）击毙了杀人魔王陈福来，自己也身中数枪生命垂尾。他在医院休养了四十九天，但刚刚出院就告知职位已被调至杂物科，只因为他的证词里有一些科学无法解释的灵异现象。来到杂物科的李国强遇见了黄警督（郑伊健 饰），这个微胖又酗酒的中年人告诉他，和别的部门不同，杂物科专门处理那些所谓的“灵异事件”，但若想在这里生存下去，就必须坚定一个信念，那就是第一诫：“这个世上没有鬼！”可是这个世上却真的是有鬼的，连月来发生的数起诡异的自杀案件引起了李国强的注意。通过调查，他发现这是陈福来的魂魄杀心不改，他可以通过触碰附在任何人的身上，然后操纵他们的身体为所欲为。为了制伏凶手，李SIR和黄SIR强强联手，展开了一场惊心动魄的大追击。然而就在此时，李国强却渐渐的分不清楚，一直都在鼎力帮助自己的黄警督，他到底是敌是友。©豆瓣', '余文乐', '唐永健', 7.2, 36045, 'tt0918561', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2097812468.jpg', 1.3, 5.6, 38.6, 40.8, 13.6, '0.351135,0.038054,-0.757002,0.423677,-0.329019,-0.117043,0.818656,-0.107976,-0.338657,-0.429621,0.106892,0.437239,-0.057607,0.164182,-0.131015,-0.138056,-0.109331,-0.622460,-0.106210,-0.224665,-0.557327,-0.671032,-0.374998,-0.327304,-0.017972,-0.035909,0.462560,0.296823,-0.309531,0.110369,0.419357,0.157858,0.092021,0.689903,-0.148081,-0.092711,-0.143156,-0.051229,0.008107,0.030058,0.333432,-0.478981,-0.120626,0.278030,0.029499,0.517174,0.395536,-0.328306,-0.388529,0.083926,0.415031,-0.417872,-0.112710,0.040629,0.499010,-0.206684,-0.116486,0.252305,-0.297263,-0.090494,0.055134,0.173307,-0.797585,0.036682,-0.051846,0.391497,-0.446733,0.203945,-0.102650,0.086453,-0.066991,-0.200740,0.514652,0.413945,0.234247,0.254224,-0.220279,-0.213951,-0.605339,0.260797,0.628591,0.101776,-0.263372,0.243441,-0.119736,-0.610729,-0.264233,-0.107800,-0.140709,-0.046665,0.331169,0.073774,-0.273628,-0.082438,-0.299013,-0.072558,-0.181825,-0.138307,-0.343305,-0.219117,0.088304,-0.325121,-0.139937,-0.312503,-0.399998,0.224362,0.166644,-0.460054,0.585847,-0.844478,0.141965,0.505770,0.229937,-0.743766,0.629354,0.202196,0.060224,-0.036768,-0.134438,0.096133,0.317987,0.528969,0.178931,0.597645,0.242668,-0.140893,-0.245082,0.247404', '35073886', '25870679', '1308206', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2027925', '六号出口', '剧情', 'Fion（刘荷娜）和小薇（辰伶）自小就被双方父母拿来比对，无论功课还是钢琴，她们都被迫着要一争高下。为了做纯粹的好朋友，她们于某次极其重要的钢琴比赛前，将琴谱扔进冰箱“Freeze”，但Fion在比赛现场没像小薇一样乱弹琴，小薇失望之余逃离到西门町。结识顾摊少年范达音（彭于晏）与滑板少年Vance（阮经天）后，小薇过上不一样的“极速青春生活”，而Fion为了找寻小薇，在网上建立了“秋叶会”。Fion于街头无意间遇见早已改头换面的小薇，交谈后，两人握手言和。Fion被小薇介绍与范达因和Vance认识，令她在集体小圈子中渐渐体会到别样的青春滋味，开始努力摆脱任由父母摆布的“宿命”。然而因为范达因，她和小薇不自觉地又成了竞争对手。©豆瓣', '彭于晏', '林育贤', 6.2, 18381, 'tt0934427', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198909354.jpg', 4.7, 17.8, 48.6, 21.8, 7.2, '0.393804,-0.054526,-0.710368,0.493653,0.091836,-0.437864,0.606579,0.047049,-0.536283,-0.120670,-0.140160,0.750041,-0.302747,0.401095,0.266467,-0.200408,-0.215588,-0.949139,-0.224340,-0.086606,-0.289577,-0.434972,0.002364,0.030302,-0.298254,-0.047538,0.629044,-0.149666,-0.149292,0.578231,0.327867,0.114459,-0.150868,0.442426,-0.325185,0.047620,-0.196164,0.335595,-0.416310,0.072539,0.274206,-0.345251,-0.283570,0.099192,0.149955,0.084738,0.919256,-0.191881,-0.144273,-0.174297,0.160007,0.059870,0.137153,0.086388,0.178074,0.208016,0.313468,0.158241,-0.165024,0.269093,0.149388,-0.106260,-0.348492,0.225628,0.101606,0.029907,-0.535492,0.624506,0.023009,-0.015420,0.278460,-0.378308,0.325832,0.212455,0.313217,0.369128,-0.217927,-0.285105,-0.402238,0.239824,0.739295,0.164864,0.107292,0.589077,-0.118331,-0.301170,-0.148325,-0.274641,-0.422802,-0.024728,0.062271,0.221265,-0.346414,0.305734,-0.517493,-0.046602,0.043642,-0.027622,0.011994,-0.560965,0.069798,-0.485818,-0.260964,-0.497939,-0.282170,0.164708,-0.091246,-0.517359,0.657836,-1.155069,0.181019,0.524714,0.200978,-0.486152,0.478893,0.125040,0.203211,-0.056656,0.100850,0.056052,-0.007893,0.196684,0.337053,0.404464,-0.143588,0.242325,-0.401028,0.425338', '30345227', '1292219', '35030151', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2027938', '神探', '动作', '天才和疯子常常只是同一个人的两种描述。神探陈桂彬（刘青云 饰）就是这样一个人物，和天才画家梵高一样，他也曾经割下自己的耳朵。尽管破案无数，侦探能力超凡，却终被世俗认定是疯子一个，提早从警局里退了休。探员何家安（安志杰 饰）接到了一桩棘手的案件。案发地在树林，两名警员王 国柱（李国麟 饰）和高志伟（林家栋 饰）办案之后，只有高志伟平安归来，而王国柱和他的枪则神秘失踪。何家安请来陈桂彬为他指点迷津，却未料到陈桂彬的“疯子”行为又一次在侦探过程中表露无遗。他断定高志伟就是此案凶手，并把推理建立在他自己大量的想象之上。他自称能看到高志伟的“七宗罪”，正是这些罪恶把高志伟引向犯罪之路。然而，要何家安相信这一切并不容易，因为他已经被高志伟的演技所迷惑……©豆瓣', '刘青云', '杜琪峰', 8.5, 277653, 'tt0969269', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1349162079.jpg', 0.3, 1.1, 12.3, 44.2, 42, '0.144838,-0.022159,-0.648705,0.471609,-0.145293,-0.201585,0.766663,-0.004818,-0.471636,-0.435847,0.220777,0.758422,-0.059358,0.067630,0.080507,-0.139952,-0.284731,-0.743684,-0.123657,-0.073502,-0.209965,-0.575092,-0.124328,-0.100616,-0.032414,-0.100971,0.508856,0.124158,-0.280130,0.289033,0.235541,0.305031,-0.136725,0.510922,-0.280726,0.105945,0.238909,0.010919,-0.266337,0.048148,0.056944,-0.280653,-0.168639,0.503677,-0.287796,0.282604,0.464121,-0.349731,-0.281419,-0.053317,0.289404,-0.542063,-0.148808,-0.019185,0.296714,-0.215329,0.315660,0.367881,-0.065149,0.047734,0.085217,0.017941,-1.057153,-0.197036,0.074819,0.188133,-0.449320,0.172679,-0.117472,-0.077829,-0.055321,-0.286494,0.356587,0.065534,0.199765,0.210957,-0.194545,-0.327786,-0.563950,0.342995,0.442393,0.133513,-0.102799,0.409639,-0.099451,-0.500138,-0.314841,0.025270,-0.338431,0.116254,0.405367,-0.115108,-0.321405,0.018181,-0.032668,-0.070753,-0.361343,0.252598,-0.195758,-0.422971,-0.179745,-0.263397,-0.038455,-0.286620,-0.432110,-0.040546,0.160644,-0.433996,0.456392,-0.686817,0.033362,0.448057,-0.065591,-0.468711,0.406072,0.036384,-0.176894,-0.498523,-0.185247,-0.057507,0.502002,0.435687,0.101125,0.514681,-0.051114,-0.371007,-0.246084,0.322497', '1793491', '30163500', '3785918', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20279443', '恋爱的温度', '剧情', '看似平淡的一天，在银行工作的张英（金敏喜 饰）回到家中大哭了一场，与此同时在同一家银行工作的李东熙（李民基 饰）也在聚会中醉酒失态。原来他们是一对秘密进行办公室恋情的分手情侣，同事们都不知道他们的关系，两人虽然装作无所谓，但却在各种交集中为难对方。在一次女科长（罗美 兰 饰）为张英做媒的活动中，东熙终于忍不住嫉妒破坏了张英与男同事的相亲，从此二人的关系公之于众，也上演了各种啼笑皆非的趣事。随着两人都再次寻觅到新欢，二人也开始冰释前嫌，但由于公司的集体出游计划，新的事故又开始上演了，在搅乱了各种工作生活之后二人又重归于好，而同时女科长与男科长（崔武盛 饰）各自的婚姻关系也发生了新的变化。分手的情侣还能和好如初吗？爱情的温度在随时随地发生着变化。©豆瓣', '李民基', '鲁德', 7.5, 27379, 'tt3004788', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1903366973.jpg', 0.4, 3.1, 35.1, 46.2, 15.2, '0.456316,-0.147115,-0.755502,0.264964,0.105842,-0.448650,0.735714,0.224967,-0.380954,-0.146800,0.270068,0.554884,-0.572238,0.264387,0.276821,-0.381657,-0.375609,-0.922041,0.180148,-0.140857,-0.153462,-0.483902,0.000999,-0.164231,-0.096755,-0.179060,0.407760,-0.084750,-0.092869,0.497959,0.426605,-0.032297,-0.507757,0.743954,-0.065869,0.054746,0.086213,0.425431,-0.495305,-0.153296,0.089762,-0.282075,-0.317544,-0.007780,0.291075,0.482675,0.847077,-0.165504,-0.348840,0.251633,0.301040,-0.046153,-0.068145,0.214863,0.551234,0.076130,0.280121,0.340861,-0.315988,0.112997,-0.004527,0.198174,-0.510907,0.144681,0.129296,0.313118,-0.404607,0.699414,0.209255,-0.086243,0.023340,-0.271110,0.310258,0.764818,0.332125,0.461711,-0.277834,-0.020404,-0.478988,0.164933,0.853577,0.144737,-0.086295,0.584448,-0.116349,-0.329045,-0.325764,0.245721,-0.471421,-0.175325,0.210251,0.041565,-0.131171,0.375215,-0.905583,-0.085370,0.035430,-0.022326,-0.013712,-0.520250,0.161103,-0.836018,-0.181286,-0.437636,-0.330891,0.197041,0.248087,-0.223902,0.475986,-0.936581,-0.067831,0.297045,0.158096,-0.758309,0.435184,0.298912,0.296328,-0.340977,-0.231768,-0.174628,-0.024872,0.341208,0.263354,0.500908,-0.017210,0.047923,-0.308714,0.242432', '11541282', '1301022', '1305364', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2027945', '每个人都有他自己的电影', '剧情', '给你一个三分钟，你会拍出怎样的电影？本片由35位知名导演，为庆祝戛纳电影节六十周年而拍摄的三分钟短片组成。细心的你会发现，在此短篇集中不仅有众多知名演员的参演，更有著名导演的客串演出。这短暂的三分钟光影，不仅浓缩了精妙的生活片段，更有每位导演对电影、对人生的深刻体悟。 或温情或冷峻或真实或迷幻，人生何止五味，《每个人都有他自己的电影》如是说，你的呢？©豆瓣', '乔什·布洛林', '西奥·安哲罗普洛斯', 7.8, 19159, 'tt0973844', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521811815.jpg', 0.4, 2, 26.1, 48.8, 22.7, '-0.185308,-0.229379,-0.463762,0.909672,0.253451,0.017638,0.723205,0.016348,-0.118817,-0.252611,0.334752,0.989596,-0.577856,-0.030692,0.042688,-0.249462,-0.167273,-0.673372,-0.193053,-0.073049,-0.098964,-0.180424,-0.595619,-0.094201,0.214140,-0.374064,0.418140,0.128389,-0.140350,0.124464,0.456915,-0.060866,0.171949,0.224234,-0.078653,0.212165,-0.203699,-0.040639,-0.192440,0.185300,0.045425,-0.456515,-0.251822,-0.094462,-0.340217,0.389265,0.925607,0.158898,-0.564875,0.254319,1.000469,-0.320652,-0.162579,-0.264128,-0.127347,0.010015,0.370103,0.212018,-0.209677,0.372140,-0.186030,-0.069894,-1.168440,-0.150130,0.181662,0.247538,-0.338316,0.477195,0.264437,-0.239925,0.291725,0.106186,0.029652,0.215271,0.265340,0.205178,0.025981,-0.200760,-0.287664,0.821185,0.436500,0.103828,-0.346246,0.540941,-0.392941,-0.617814,-0.191691,-0.275559,-0.401068,0.229020,0.290291,-0.063418,0.047202,0.015891,-0.519043,0.163493,0.375568,-0.469437,-0.057145,-0.577274,0.091367,-1.066737,-0.068063,-0.396313,-0.195972,-0.436542,0.234478,-0.354306,1.299148,-0.590612,0.253182,0.333470,0.156102,-0.471995,1.057846,0.462673,-0.312409,0.015673,-0.181776,-0.033368,-0.148339,0.140239,-0.072247,0.373231,0.047845,-0.065314,-0.659044,0.492941', '27602116', '3318306', '22265121', '4267948');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20279749', '制服', '犯罪', '一段时间内，社会上接连发生两起猎奇杀人案。死者均为妙龄女子，她们的尸体均被凶手用特殊手法冷冻过，事后被穿上华丽夸张的制服公然丢弃，宛如被人随意摆布的玩偶。刑警队长方友为（任达华 饰）和搭档严晓童（颖儿 饰）、新入职的警官肖凯（袁弘 饰）展开调查。他们发现两位死者十年前曾是大学同学，也在同一个Cosplay俱乐部待过，方友为据此接近二人的同学周瑾（徐若瑄 饰）。周瑾的出现无疑将案件引向了新的方向，而她似乎也即将成为下一个被杀害的目标。躲在暗处的凶手磨刀霍霍，狞笑着向他仇恨多年的女人们展开无情报复。道德沦丧的时代，无所畏惧，命若草芥……©豆瓣', '任达华', '王光利', 5.1, 11076, 'tt3341088', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2155582128.jpg', 13, 34.3, 41.8, 7.7, 3.3, '0.526930,-0.109490,-0.448846,0.321033,-0.162705,0.079769,0.640282,-0.088994,-0.433042,-0.152717,0.493544,0.438956,-0.209912,0.126425,0.164065,-0.073685,-0.094818,-0.923100,-0.224999,-0.271440,-0.364609,-0.421309,-0.270078,-0.096638,-0.031100,-0.255189,0.401431,-0.154243,-0.034995,0.502880,0.494633,0.409122,-0.372542,0.273872,-0.026005,-0.019575,0.121013,-0.066813,-0.339580,0.207537,-0.281995,-0.494325,0.036695,-0.003870,-0.401387,0.412990,0.830135,-0.262775,-0.225056,-0.280651,0.505935,-0.309991,-0.003186,0.399926,0.558146,0.227287,0.100521,0.475569,-0.091270,0.022426,0.097132,-0.045630,-0.544145,-0.024579,0.225969,0.185178,-0.490516,0.615580,-0.144692,-0.012504,0.018882,-0.307970,0.206566,-0.053182,0.486412,0.172523,-0.151112,-0.067516,-0.439979,0.222205,0.587784,0.143108,-0.280107,-0.136724,0.072146,-0.238886,-0.060527,-0.197423,-0.263466,-0.080390,0.326006,-0.103335,-0.158795,0.159418,-0.483386,-0.055560,-0.243882,0.051051,-0.040001,-0.128180,-0.275404,-0.502800,-0.012524,-0.402968,-0.456314,0.050445,0.003111,-0.461404,0.419168,-0.685676,0.193905,0.359506,0.330986,-0.475184,0.516718,-0.122724,0.166699,-0.040689,-0.393402,0.093169,0.436423,0.468616,0.131460,0.263988,-0.280670,-0.131973,-0.247499,0.205778', '4202326', '24839498', '2245683', '1298197');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20283482', '生命之书', '喜剧', '片中，男主角马诺洛（墨西哥演员迭戈·鲁纳配音），要击败情敌华金（查宁·塔图姆配音），赢得爱人玛利亚（佐伊·索尔达娜）的芳心。为此，他不但必须在剑术上胜过马诺洛，以及击剑高手玛利亚本人，还得穿越“铭记之地”（The Land of the Remembered），抵挡种种诱惑，重回人间。影片瑰丽斑斓，色彩丰富，充满墨西哥文化元素。墨西哥人认为，死亡是生命的归宿，也是新生的开始。每年11月的前两天为传统节日“鬼节”（Dia de Muertos），全国都要隆重庆祝，带着面具到处游玩，面包和糖果都装饰着骷髅的形象。片中“铭记之地”的色彩、乐器乃至食物，以及马诺洛的骷髅造型，都从“鬼节”的传统习俗中汲取灵感。', '迭戈·卢纳', '豪尔赫·R·古铁雷斯', 7.8, 29165, 'tt2262227', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2221544267.jpg', 0.3, 2.2, 26.8, 48, 22.7, '-0.420395,-0.109748,-0.321065,0.619182,0.042772,0.070605,0.506345,0.076966,-0.201719,-0.032369,0.272570,0.594571,-0.140349,0.136332,0.453713,-0.018769,-0.497370,-0.491801,-0.130985,-0.087825,-0.110212,-0.149231,-0.426173,0.138317,0.024070,-0.728836,0.645483,0.090888,-0.145054,0.200737,0.169197,-0.112972,-0.141611,0.123223,0.127211,-0.257205,-0.071321,-0.049922,-0.380191,0.182081,-0.204795,-0.251890,-0.130225,0.227461,-0.127512,0.002229,0.571707,-0.183345,0.408436,-0.176420,0.358007,-0.078680,0.120833,0.086896,-0.052245,-0.105650,0.346173,0.200669,0.111480,0.196015,0.275019,-0.384684,-0.683951,0.112223,0.368411,0.159594,-0.289332,0.506123,0.031896,0.090649,0.132868,-0.233880,0.184845,-0.231357,0.285278,0.515247,0.074421,-0.023400,-0.522462,0.404843,0.307150,-0.315806,-0.194567,0.106044,-0.549082,-0.517967,-0.056856,-0.274254,-0.372396,0.106015,0.114312,0.175832,0.119052,0.471010,-0.941009,0.215864,-0.013777,-0.261077,0.150402,-0.110032,-0.081796,-1.006349,0.001662,-0.339054,0.012029,-0.069387,0.453301,-0.197987,0.834572,-0.551723,0.214743,0.599059,0.155476,-0.078799,0.657144,-0.062959,-0.043509,0.002671,-0.398827,0.451505,-0.013254,0.050299,-0.229592,0.241257,-0.019329,-0.047593,-0.136032,0.697194', '3318306', '1322847', '26290398', '26611806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20284873', '寻访千利休', '剧情', '16世纪末4月的一天，暴雨浸淫下的京都，某座并不起眼的宅邸内，一代名流的人生正走向尽头。房屋的主人乃是举世尊奉的茶道宗师千利休（市川海老藏 饰），遥想当年，他在战国乱世得到了织田信长（伊势谷友介 饰）的赏识，并曾以其影响力救助了命悬一线的羽柴秀吉（大森南朋 饰）。英雄霸业烟消云散，秀吉成为新一代枭雄，却渐渐不满利休那种对美毫不妥协的追求以及对强权的漠然蔑视。本不该有交集的二人，裂痕愈来愈大，这似乎也注定了利休的悲剧。生命将逝，在妻子宗恩（中谷美纪 饰）的陪伴和问询下，利休回忆起往昔的岁月，以及年轻时代那段令他刻骨铭心并左右命运的恋事……©豆瓣', '市川海老藏', '田中光敏', 8.1, 7648, 'tt2500392', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2134378932.jpg', 0.6, 2.2, 19.6, 45, 32.6, '-0.012538,0.290879,-0.451990,0.502570,0.300167,-0.245133,0.634297,0.151972,-0.461344,-0.397522,0.434726,0.811260,-0.132670,0.270320,0.282746,-0.214661,-0.010278,-0.744591,-0.225922,-0.333502,0.050681,-0.390349,-0.426623,0.136682,-0.239329,-0.258363,0.967798,0.406268,-0.087458,0.423199,0.166299,0.203811,0.055210,0.384092,-0.290783,-0.047111,-0.224143,0.251874,-0.370506,-0.191051,-0.411617,-0.452272,-0.079652,0.114653,-0.283698,0.260536,0.321001,-0.522799,-0.217297,-0.288928,0.365206,0.024201,-0.237088,0.102029,0.372667,-0.012876,-0.069416,0.535241,-0.109782,-0.198825,-0.137110,-0.015501,-0.682908,-0.189260,0.110395,0.152745,-0.435637,0.751624,0.143782,-0.281428,0.021434,-0.090922,0.104718,0.045059,0.283212,0.241236,-0.455682,0.221692,-0.289966,0.302566,0.332644,0.212059,-0.165525,0.344214,-0.201718,-0.333052,-0.236466,-0.358764,-0.402829,-0.209778,0.120922,0.172188,0.122957,0.453005,-0.330016,0.066785,-0.068516,0.020891,0.341464,-0.273788,-0.129160,-0.437612,-0.147164,-0.564353,-0.289537,0.218028,0.321993,-0.239766,0.828895,-0.637909,0.211656,0.255420,0.189566,-0.300871,0.536635,0.088892,-0.079845,-0.146544,-0.365584,0.750974,-0.123559,0.295909,-0.193607,0.159421,-0.177951,-0.044804,-0.308967,0.559096', '25880986', '1870681', '27602116', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028585', '穿靴子的猫', '喜剧', '他是一只穿靴子的猫（安东尼奥·班德拉斯 Antonio Banderas 配音），多年来行侠仗义，行走江湖，剑术高明，胆大卖萌，虽是官兵通缉捉拿的要犯，但从来都无所畏惧，泰然自若。在某个极不友好的小酒馆里，靴猫听说杰克（Billy Bob Thornton 配音）和吉尔 （Amy Sedaris 配音）这对雌雄恶棍拿到了传说中的魔豆，魔豆长出的豆荚直通巨人的宫殿，而那里住着令人垂涎可以下金蛋的鹅。靴猫决定铤而走险劫掠魔豆，却遭到神秘的黑猫阻挠。在黑猫引诱下，他来到一处猫儿聚会的场所，结果意外遇到当年孤儿院的好友矮蛋（Zach Galifianakis 配音），黑猫则是性感的小母猫咪·柔爪（萨尔玛·海耶克 Salma Hayek 配音）。矮蛋希望和靴猫重组魔豆帮，拿到下蛋的金鹅……©豆瓣', '安东尼奥·班德拉斯', '克里斯·米勒', 7.7, 124602, 'tt0448694', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265550239.jpg', 0.3, 2.2, 30.6, 48.5, 18.5, '0.374927,-0.194558,-0.477085,0.515810,-0.092980,0.179407,0.456988,0.089389,-0.230423,-0.029553,0.418317,0.463697,-0.200684,0.148751,-0.147890,0.051061,0.101405,-0.178168,-0.027264,-0.016593,-0.016557,0.043169,-0.531455,0.043601,0.016946,-0.210820,0.532479,-0.094240,-0.190461,0.673654,0.494304,0.050120,-0.233067,0.056417,-0.390199,-0.204332,0.124452,0.280126,0.265347,0.154956,-0.281014,-0.087265,-0.095494,-0.018993,0.093975,0.158222,0.493133,-0.585399,-0.068345,-0.145019,0.263758,-0.135959,0.068848,0.048196,0.391139,-0.061490,0.231802,-0.062903,0.095619,0.141387,0.191915,-0.135509,-0.574720,-0.116625,-0.060889,0.454938,-0.393261,0.398092,-0.068151,0.134318,0.172141,-0.459783,-0.114152,-0.143597,0.283545,0.338381,0.209272,0.417760,-0.606447,0.047911,0.311486,-0.089330,-0.097042,0.132943,-0.051785,-0.477532,0.264424,-0.221930,-0.235652,-0.219842,0.279918,-0.198259,-0.445223,0.077852,-0.738258,0.151857,-0.019333,0.095655,-0.068433,-0.279580,-0.278472,-0.601187,0.254604,-0.452046,-0.116199,0.127095,0.289402,-0.408038,0.291404,-0.745732,0.244357,0.560319,0.116601,0.013946,0.686509,-0.212230,0.024247,-0.086344,-0.210319,0.070460,0.392520,0.195582,0.358072,0.344209,-0.006143,-0.343383,-0.638984,0.413526', '5322572', '3055049', '26839466', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028634', '盲流感', '剧情', '诺贝尔奖得主Jose Saramago的小说《Blindness》将被搬上电影舞台。书中描述了一个陷入致盲病毒的城市，导火线从一名司机点燃，突然失明后，他得到了一个人的善意帮助，这条线继续燃烧下去，眼科医生也来帮助他们了，故事就这样开始了。所有的致盲者都被关进了一座废弃的精神病院，重兵把守，不惜生命的代价也要制止疾病的扩散。 Julianne Moore将扮演唯一没有失明的人——医生的善良妻子， 著名黑人电影人Danny Glover在片中扮演一名致盲的黑人老者。尽管主角来自美国，但这部电影是由日本、巴西、加拿大合拍的国际性电影。©豆瓣', '马克·鲁弗洛', '费尔南多·梅里尔斯', 7.1, 13752, 'tt0861689', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1200550935.jpg', 2.1, 7.5, 37.5, 39.7, 13.2, '0.138416,0.062522,-0.399031,0.792275,-0.196167,-0.007093,1.021874,0.215255,-0.205661,-0.023785,0.417900,1.040404,-0.171555,0.002922,0.077589,0.100530,-0.349539,-0.621178,-0.290792,-0.132149,-0.436665,-0.274117,-0.200733,-0.444140,0.067477,-0.379432,0.735201,0.057958,-0.483855,0.137671,0.230749,0.281528,0.123476,0.363581,-0.077464,0.128697,-0.019980,-0.378069,-0.070084,0.660748,0.057095,-0.386440,0.024997,0.296004,-0.437791,0.403647,0.721578,-0.045121,-0.136732,-0.073058,0.467835,-0.510719,-0.115050,0.120443,0.306213,-0.024332,0.202261,0.071932,-0.098805,0.004870,-0.000821,-0.099707,-1.041348,-0.082761,0.106323,0.267847,-0.536343,0.554911,-0.051969,-0.021444,-0.056388,-0.031391,0.361298,0.084080,0.290120,0.301754,-0.138202,0.063948,-0.535794,0.651591,0.659382,-0.256524,-0.476874,0.681968,-0.307212,-0.644221,-0.238081,-0.258716,-0.523110,0.129231,0.562558,-0.185275,-0.449825,-0.059948,-0.552794,0.002890,-0.182928,-0.424493,-0.216308,-0.234193,-0.047171,-0.659142,-0.165675,0.127345,-0.001136,-0.117019,0.072626,-0.127062,1.125837,-0.413911,0.192560,0.819188,0.086429,-0.458256,0.850168,-0.150306,0.006133,-0.089523,0.032722,0.246787,0.202670,0.634951,0.074510,0.327780,-0.110034,-0.110545,-0.449219,0.454255', '27602116', '34890458', '2027945', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028640', '末日侵袭', '动作', '2010年，苏格兰格拉斯哥。一种未知、恐怖的病毒肆意蔓延，感染着全身布满疱疹，溃烂流脓，最终在折磨中痛苦死去。由于缺少医疗设备和疫苗，短短一周内死亡人数成千上万。为抑制病毒蔓延，英国政府对苏格兰进行全面封锁，企图将病毒彻底隔离。在此之后，地球上其他地区的人们得到长达近三十年的平静，但在2035年某天，该死亡病毒再次于英国伦敦爆发。正当政府官员焦急万分之际，他们得到了一条令人振奋的消息。一张卫星照片显示，在苏格兰隔离区有生命存活的迹象。为了找到对抗病毒的办法，政府派出以伊登•辛克莱（罗娜•米特拉 Rhona Mitra 饰）为首的科学队伍进入隔离区。伊登当年从疫区侥幸逃生，当她回到这片阔别将近三十年的故土时，却发现这里已经变成弱肉强食、蛮荒残暴的血肉战场……©豆瓣', '罗娜·迈特拉', '尼尔·马歇尔', 6.1, 13575, 'tt0483607', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1663146288.jpg', 5.5, 19.5, 47.2, 20.6, 7.3, '-0.343153,0.366465,-0.544006,0.258934,0.197688,0.171127,0.703538,-0.398429,-0.538330,-0.222108,0.156816,0.499210,-0.263039,0.148523,-0.091375,-0.281241,-0.189897,-0.490359,-0.192067,-0.199691,-0.589431,-0.192913,-0.526423,-0.289433,0.039074,-0.659294,0.816606,0.539082,-0.144436,0.343933,-0.264499,0.439925,-0.220226,0.501214,-0.048459,-0.403365,0.056603,-0.339297,-0.362268,0.306624,0.079165,-0.131495,0.026176,0.097950,-0.204826,0.366467,0.827302,-0.207953,-0.157214,-0.295090,0.422130,-0.360600,-0.241338,0.139950,0.350848,0.136096,-0.135059,0.108892,-0.278617,-0.054634,-0.096571,0.100789,-0.548798,-0.372394,-0.147483,0.351216,-0.142357,0.466976,-0.141169,0.022726,-0.057206,-0.338986,0.150964,0.423317,-0.053143,0.511784,-0.363370,0.058072,-0.496667,0.012547,0.670548,-0.503822,-0.652141,0.132398,-0.338357,-0.630785,0.041418,-0.225178,-0.149436,-0.195474,0.087380,0.459601,-0.339421,0.394303,-0.738536,0.102858,-0.208124,-0.577692,-0.017680,0.148384,-0.256295,-0.709927,-0.519354,0.090800,-0.048003,0.261805,0.001029,-0.193007,0.434656,-0.364185,0.522259,0.430015,0.242620,-0.494775,0.299677,-0.056879,0.141986,-0.107158,-0.144019,0.707208,0.151783,0.664486,0.049227,0.066184,-0.251647,-0.024850,-0.393903,0.546948', '1578502', '3006772', '6714930', '1297611');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028645', '拆弹部队', '剧情', '美军侵入伊拉克后，上士威廉姆斯•詹姆斯（杰瑞米•雷纳 Jeremy Renner 饰）被调入陆军亡命连拆弹组，接替刚在巴格达执行任务中牺牲的同事。拆弹组另两人，负责联络的士官桑波恩（安东尼•麦凯 Anthony Mackie 饰）和负责掩护的特种兵欧文（布莱恩•杰拉蒂 Brian Geraghty 饰）对意气用事的威廉姆斯相当反感。但在联合国大楼的拆弹行动中，抗拒命令强行拆弹的威廉姆斯却得到上校瑞德（大卫•莫尔斯 David Morse 饰）的赞赏。在一次仓库拆弹任务中，威廉姆斯认为被用作尸体炸弹的伊拉克小男孩是他在军营认识的卖盗版DVD的贝克汉姆（克里斯托佛•萨伊 Christopher Sayegh 饰）。小贝克汉姆的死让威廉姆斯更为疯狂，竟私离军营单枪匹马入城调查……本片荣获2010年第82届奥斯卡最佳影片、最佳导演、最佳原创剧本、最佳剪辑、最佳音效剪辑、最佳音响效果等6项大奖。', '杰瑞米·雷纳', '凯瑟琳·毕格罗', 7.8, 169984, 'tt0887912', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p770541118.jpg', 0.5, 2.1, 25.3, 51.9, 20.2, '-0.012739,-0.158367,-0.558716,0.544996,-0.083618,-0.265435,0.276159,0.050797,-0.402314,-0.182406,0.214560,0.750998,-0.101782,-0.312508,0.254787,-0.231420,-0.401176,-0.674760,-0.308773,-0.193964,-0.340330,-0.606759,-0.146646,-0.263969,0.008049,-0.243634,0.665170,-0.207853,-0.210994,0.383620,0.529411,0.309822,0.097071,0.150446,0.196745,0.084615,0.610264,-0.552366,-0.376675,0.464853,-0.093563,-0.078946,-0.160120,-0.021473,0.407443,0.429465,0.673124,-0.186127,0.173370,0.129587,0.199769,-0.309105,0.112188,-0.013918,0.234547,-0.010493,-0.100849,0.051749,-0.097603,0.283128,-0.064038,-0.262465,-0.797459,-0.013236,0.043912,0.101856,-0.393810,0.163969,-0.462408,0.466414,0.219792,0.022732,0.096463,0.221294,0.249695,0.030836,-0.153574,-0.013256,-0.151174,0.435218,0.000157,-0.078795,-0.331870,0.029590,-0.030982,-0.541678,0.124669,-0.062375,-0.285013,-0.015119,0.457941,-0.109506,0.333522,-0.116718,-0.324743,-0.185221,-0.364036,-0.242126,-0.349739,-0.201487,0.029054,-1.211432,0.098064,0.014011,-0.125272,0.026852,-0.075280,-0.003296,0.276312,-0.514305,0.165630,0.561526,-0.069278,-0.122302,0.328859,0.044902,0.279107,-0.403241,-0.166212,0.243200,0.263258,0.253083,0.174824,0.481750,-0.099861,-0.449741,-0.419667,0.205540', '34961898', '1298616', '6517421', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028647', '行动目标希特勒', '剧情', '1944年，二战如火如荼，战争局势波谲云诡。纳粹德国四面出击，但在盟军的合力反击下，德军攻势已成强弩之末。此时此刻，德军一部分高级军官意识到战争的天平已经倾斜，希特勒（David Bamber 饰）的战争策略将引领德国走向灭亡。越来越多的军官相信，只有除掉希特勒及其支持者，发动政变夺取政权，并通过和谈与盟军达成协议，才能最终拯救德国。在这样的思想影响下，一个名为“瓦尔基里”的计划应运而生。在整个计划中，陆军上校克劳斯•冯•施陶芬贝格（Tom Cruise 汤姆•克鲁斯 饰）扮演着重要的角色。出身贵族的施陶芬贝格一度倾心希特勒及其纳粹纲领，他于1943年率装甲师驰骋北非突尼斯战场，并在此失去右手臂、左手两个手指以及右眼。战争的残酷令他的思想发生巨大转变，回到德国后他作别妻儿，与刺杀组织高层军官共同开始策划谋杀最高元首希特勒的危险任务……©豆瓣', '汤姆·克鲁斯', '布莱恩·辛格', 7.2, 47322, 'tt0985699', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2153198744.jpg', 0.5, 3.8, 42.1, 43.2, 10.5, '0.051232,0.222388,-0.641918,0.450733,0.288585,0.116708,0.488689,0.090060,-0.354154,-0.247086,0.387571,0.614569,0.193498,-0.323109,0.433205,-0.385574,-0.382806,-0.965904,-0.335368,0.264827,-0.203007,-0.683448,-0.357579,-0.318374,0.045173,-0.284398,1.024635,0.455824,-0.446346,0.271779,0.259267,0.332418,0.026882,0.409214,0.119807,-0.304984,0.255801,-0.442469,-0.705038,0.162265,-0.188432,-0.270581,-0.187297,0.291775,-0.193344,0.244400,0.607947,-0.694237,0.181221,-0.347308,0.297496,-0.381531,-0.177833,0.285821,0.508641,0.267703,-0.243910,0.310179,0.222536,0.232429,-0.222178,-0.134082,-0.644069,-0.043683,-0.116012,0.059571,-0.413414,0.280422,-0.132580,0.404329,0.032837,-0.154219,0.030159,0.912671,0.211501,0.017810,-0.288298,0.197039,-0.384793,-0.012143,0.686875,-0.152030,-0.446600,-0.098277,-0.135789,-0.376097,-0.283810,-0.363898,0.111280,-0.413393,0.321117,-0.204758,0.185119,0.720368,-0.494976,0.120233,-0.491838,-0.394884,0.216505,-0.102864,0.095788,-0.747467,-0.370581,-0.162227,-0.184299,0.334395,0.012737,0.019504,0.733303,-0.722828,-0.030742,0.309104,0.269545,-0.412772,0.177451,0.395285,0.270698,-0.392496,-0.023521,0.792642,-0.131996,0.158767,-0.131514,-0.003494,-0.118842,-0.072247,-0.087128,0.182449', '1424552', '26852888', '1291860', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028650', '大战外星人', '喜剧', '住在加州某小镇的美丽女孩苏珊·墨菲（瑞茜·威瑟斯彭 Reese Witherspoon 配音）即将和他深爱的男友德里克·迪尔特（保罗·路德 Paul Rudd 配音）走入婚姻的殿堂。可就在这关键时刻，她先是被一颗陨石砸到脑袋，继而全身发光变成一个身形高大头发雪白的巨人。她的变化吓跑了亲朋好友，随后一群全副武装的神秘之人将其抓获并囚禁起来。苏珊被军方带到52区的秘密基地，与来自地球各个角落的怪物们称为科学家们研究的对象。与此同时，一个藏有邪恶力量的不明飞行物正以极高的速度接近地球，它所带来的外星人加莱克萨哈（瑞恩·威尔森 Rainn Wilson 配音）扬言要摧毁地球，毁灭人类。人类奋起反抗，但是他们的武器在加莱克萨哈面前全部败下阵来。地球危在旦夕，人们把命运寄托在了苏珊及其怪物朋友的身上……©豆瓣', '瑞茜·威瑟斯彭', '罗伯·莱特曼', 6.9, 30137, 'tt0892782', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204397540.jpg', 0.8, 6.4, 49.2, 34.2, 9.4, '0.139439,0.053395,-0.790520,0.589737,-0.311848,0.026076,0.950068,0.132609,0.024048,-0.071357,0.376004,0.654670,-0.106364,0.172731,0.263364,0.125763,-0.198427,-0.623323,-0.026533,-0.168111,-0.429284,-0.240936,-0.465322,-0.386529,0.014765,-0.456080,0.623176,-0.085415,-0.253610,0.155641,0.127388,0.416133,-0.189097,0.378349,-0.346264,0.120605,0.206807,-0.514631,-0.037027,0.225821,-0.423001,0.111523,0.098652,0.294230,-0.308807,0.014528,0.719327,-0.332607,0.087301,-0.344914,0.293737,-0.306632,0.035130,0.120500,0.454049,-0.198819,-0.042567,-0.136634,0.138464,0.118708,0.560631,-0.100726,-0.635063,-0.069487,-0.123488,0.227939,-0.489094,0.273203,-0.000618,0.205658,-0.077006,-0.248337,-0.008898,0.009480,-0.039890,0.253339,-0.057313,0.150104,-0.514215,-0.092239,0.317394,-0.016723,-0.632582,-0.042568,-0.267042,-0.300361,-0.268415,0.055241,-0.343084,-0.227141,0.700465,0.084979,-0.052955,0.584492,-0.796662,-0.091842,-0.306214,-0.279695,-0.024918,-0.335109,-0.382150,-0.669352,-0.205868,-0.163297,-0.138448,-0.059989,0.089221,-0.102409,0.826517,-0.452225,0.109880,0.644668,0.261999,-0.260941,0.317199,-0.153429,0.261332,0.030851,-0.214883,0.296618,0.435413,0.546408,0.104173,0.350060,-0.173546,0.183338,-0.452368,0.685863', '21619567', '3005387', '1467779', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028659', '狐狸与我', '剧情', '一个十岁的小女孩（贝蒂•若耶-布萝Bertille Noël-Bruneau 饰）在上学路上碰见了一只正抓田鼠的狐狸。女孩被漂亮的狐狸迷住，下学后回到森林原地希望再见到那只狐狸。从秋天到冬天，女孩在厚雪地里沿着狐狸的脚印寻找，却失足摔断了腿，整个冬天只好在室内度过，读了很多关于狐狸的书。春天是猎狐的季节，为狐狸忧心忡忡的小女孩欣喜若狂的发现了狐狸的洞穴和它的三只小狐狸，却没想到狐狸嗅出人的气味，连夜转移了幼崽。女孩决定不去打扰狐狸，而是坐到山毛榉树上等它主动出现。就这样，人与狐狸的关系慢慢建立，狐狸带着小女孩展开了奇妙的森林冒险……本片的驯兽师是法国的玛丽诺耶•布拉妮（Marie-Noëlle Baroni），片中出现的六只狐狸及其他多数动物都来自于她的农场。©豆瓣', '贝蒂•若耶-布萝', '吕克·雅盖', 8.5, 30568, 'tt0756648', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p458726329.jpg', 0.3, 0.9, 12.7, 44.1, 42, '0.357187,-0.181631,-0.616061,0.395443,-0.188871,-0.051061,0.763634,0.266656,-0.259059,0.172018,0.335033,0.529443,-0.279863,0.294629,0.010213,0.084154,-0.279556,-0.287477,-0.084813,-0.080760,-0.226373,0.032563,-0.468105,-0.037611,0.214537,-0.210248,0.648730,0.117211,-0.072114,0.486601,-0.072697,-0.131325,-0.364165,0.367909,-0.331985,-0.119163,-0.163100,0.170921,0.369925,0.295437,-0.018966,-0.104702,-0.198401,-0.254822,-0.097318,0.187623,0.910052,-0.590412,-0.156670,-0.311645,0.193093,-0.349567,-0.044501,-0.057904,0.500202,-0.470820,0.201036,-0.388569,0.060469,-0.064384,0.254358,-0.124867,-0.183525,0.325221,-0.223802,0.691861,-0.465927,0.334157,0.133073,0.159686,0.455433,-0.739813,-0.088650,-0.151737,-0.156192,0.426272,0.110111,0.334674,-0.506737,-0.046525,0.142087,-0.169175,-0.134829,0.416880,-0.030331,-0.555580,0.244530,0.001301,-0.121465,-0.199171,0.436943,-0.038293,-0.771539,0.028105,-0.910348,0.114067,-0.197680,-0.230011,0.008230,-0.407850,-0.506603,-0.323531,0.140252,-0.442957,-0.154633,0.390478,0.263033,-0.219768,0.395919,-0.766736,0.399688,0.702924,0.126074,0.027650,0.535819,-0.575769,0.009473,-0.102469,-0.031137,0.163170,0.166578,0.413517,0.418696,0.493959,-0.178938,-0.026692,-0.616597,0.461675', '1467779', '21619567', '26839466', '1309194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028666', '换子疑云', '剧情', '1928年美国洛杉矶，在电话局接线台工作的克莉斯汀•柯林斯（Angelina Jolie 安吉莉娜•朱丽 饰）独自抚养儿子沃特（Gattlin Griffith 加特林•格里菲斯 饰），母子的生活简单而幸福。然而她们的生活很快被打乱，某天当克莉斯汀下班后，发现儿子不见踪影。在公众的舆论压力下，腐败的洛杉矶警方于5个月后找回沃特，但克莉斯汀发现这并非自己的亲生儿子。她三番五次要求警方澄清事实，帮其寻找真正的沃特，却一次次受到阻挠和指责，甚至以妨碍警方公务的罪名被送入精神病院。一向以揭露警方暴行为己任的牧师古斯塔夫•布里格拉伯（John Malkovich 约翰•马尔科维奇 饰），为了这个可怜女人的不幸遭遇奔走呼告。另一方面，探员莱斯特（Michael Kelly 饰）在侦办一件偷渡案时，无意中发现了一起重大的连环儿童杀人案。少年沃特的失踪案似乎渐露眉目……', '安吉丽娜·朱莉', '克林特·伊斯特伍德', 8.4, 155938, 'tt0824747', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p794207971.jpg', 0.1, 0.7, 13.1, 51, 35.1, '0.279035,-0.071982,-0.461205,0.444982,-0.164615,-0.191919,0.716031,0.138984,-0.695475,-0.316843,0.305235,0.659273,0.039606,0.187466,0.405593,0.117057,-0.774025,-0.693964,0.162426,-0.230195,-0.157209,-0.592929,0.037677,-0.253335,-0.055966,-0.234998,0.348279,0.030449,0.185248,0.428985,0.171162,0.434284,-0.040908,0.338473,0.147047,0.052022,0.250653,-0.127230,-0.181965,0.360961,0.145078,-0.340081,-0.152055,0.235301,0.050452,0.426935,0.623220,-0.194807,-0.134925,-0.307931,0.544918,-0.287806,0.081481,0.074955,0.248700,-0.168821,0.170713,0.205445,-0.309686,-0.345457,0.307334,-0.173087,-0.547499,0.066933,0.049301,0.109583,-0.353500,0.229216,-0.344883,0.282845,0.003956,-0.218449,0.012342,0.576741,0.126523,0.266723,-0.299799,0.122836,-0.375555,0.108895,0.455156,-0.011174,-0.223074,0.075911,-0.333459,-0.208820,0.117662,-0.136151,-0.507024,-0.167354,0.312256,-0.032919,-0.239431,0.454618,-0.296696,-0.312127,-0.556188,-0.176686,-0.040861,-0.318588,-0.153169,-0.707892,0.028164,-0.439620,-0.317504,-0.104275,-0.103185,-0.342391,0.221775,-0.767675,0.467298,0.626258,0.124702,-0.377024,0.511257,-0.019739,0.382633,-0.312958,-0.288309,0.416100,0.271608,0.240733,0.078726,0.089355,0.098174,-0.135086,-0.273800,0.105860', '3178770', '1298197', '1316693', '1298214');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028669', '丁丁历险记', '动作', '丁丁（杰米·贝尔 Jamie Bell 配音）和白雪的故事可以说是影响了不止一代人。在史蒂文·斯皮尔伯格和彼得·杰克逊的努力下，丁丁的故事终于被搬上了大银幕。这一次，丁丁因为一艘古老的船模，而开始了一次惊险的历险。这艘名为独角兽号的模型船，隐藏着一个海盗和财宝的故事。为了解开这个流传了几个世纪的秘密，丁丁和白雪一起不断寻找线索，找寻真相。在航海家阿道克船长（安迪·瑟金斯 Andy Serkis 饰）、笨手笨脚的侦探搭档杜庞（西蒙·佩吉 Simon Pegg 配音）与杜邦（尼克·弗罗斯特 Nick Frost 配音）以及白雪的帮助下，丁丁游历了半个地球，与恶棍萨卡林（丹尼尔·克雷格 Daniel Craig 配音）斗智斗勇。最终，丁丁终于找到了独角兽号隐藏的秘密，以及那一则古老的诅咒……在第84届奥斯卡金像奖中，丁丁历险记获得了最佳配乐的提名。©豆瓣', '杰米·贝尔', '史蒂文·斯皮尔伯格', 7.7, 123489, 'tt0983193', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1006799889.jpg', 0.4, 2.3, 28.6, 48.4, 20.3, '0.266305,-0.134624,-0.533441,0.869017,0.136172,-0.404939,0.743167,-0.116330,-0.290298,-0.106118,0.063082,0.770063,-0.287358,0.270799,0.205798,0.216925,-0.711729,-0.617263,0.040332,-0.165043,-0.235951,-0.585149,-0.443912,-0.162053,-0.021719,-0.299654,0.658793,-0.051338,-0.131001,0.469895,0.350377,0.066778,-0.200534,0.124866,-0.336961,0.238335,0.495743,-0.081377,0.020020,0.298476,0.043542,-0.212546,0.082433,0.012452,0.000170,0.313064,0.573315,-0.600941,0.163832,0.138809,0.286215,-0.180991,0.047068,-0.118489,0.294296,-0.129310,0.302461,0.280944,-0.103489,-0.047750,0.096910,-0.081453,-0.889979,-0.134693,0.086949,0.326138,-0.623060,0.379121,-0.189241,0.057519,0.191939,-0.161466,0.350384,0.397539,0.410436,0.272819,-0.163349,0.125975,-0.363105,0.219921,0.227868,-0.059872,-0.030188,0.374174,0.075000,-0.407457,-0.099399,-0.031362,-0.426127,0.027995,0.761503,-0.090175,-0.154272,0.212574,-0.885606,0.093025,-0.242901,-0.489168,-0.157469,-0.329494,-0.187765,-0.714872,-0.105121,-0.349932,0.004210,-0.092714,0.026846,-0.424964,0.833256,-0.670028,0.322019,0.660914,-0.145703,-0.087075,0.662479,0.090811,0.244959,-0.281878,0.164036,0.087806,-0.159857,0.328601,0.249621,0.663990,0.140481,-0.202238,-0.515563,0.524001', '1308585', '25928048', '1793922', '3597344');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028677', '雨果', '剧情', '小男孩雨果（阿沙·巴特菲尔德 Asa Butterfield 饰）天生机械控。他寄宿巴黎火车站钟楼，偶尔会去玩具店偷些零件，用来修补父亲（裘德·洛 Jude Law 饰）留下的机器人。一次行窃，他被店主乔治•梅里埃（本·金斯利 Ben Kingsley 饰）当场抓获，因 忌惮带猎狗的巡警（萨莎·拜伦·科恩 Sacha Baron Cohen 饰）只得就范。乔治拿走了雨果父亲的遗物——一本机械手册，令他心急如焚，他尾随至乔治家中，结识了养女伊莎贝拉（科洛·莫瑞兹 Chloë Moretz 饰），他恳求她帮自己保住手册。而伊莎贝拉则觉得此事蹊跷，于是两人结伴探秘。修好的机器人作画的落款却显示乔治的名字，让他们疑心顿起。终于他们发现了乔治家中装满画作的神秘柜子，并在图书馆的电影书籍中发现了乔治的身世。一位知情人的显身，让他们的奇幻冒险更添神秘……本片根据布莱恩•瑟兹尼克的同名小说改编，是马丁•斯科塞斯的首部3D力作。', '阿萨·巴特菲尔德', '马丁·斯科塞斯', 7.7, 189591, 'tt0970179', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1493935120.jpg', 0.4, 2.9, 28.8, 47.6, 20.2, '0.264279,0.025992,-0.547834,0.583180,-0.071391,-0.307766,0.697799,0.031563,-0.421582,-0.410796,0.320798,0.862052,-0.153988,0.205883,0.098758,0.266121,-0.547784,-0.287866,0.150597,-0.213666,-0.113153,-0.418423,-0.342294,-0.611840,0.016905,-0.348448,0.336312,-0.109070,-0.099338,0.427416,0.201129,0.383048,-0.201368,0.201591,0.077429,0.239132,0.072260,-0.393944,0.093002,0.046904,0.095291,-0.041822,-0.229579,0.164219,0.095904,0.428804,0.680362,-0.146942,0.186811,-0.000146,0.404203,0.007896,0.188123,-0.109514,0.000333,0.148521,-0.179568,0.059352,-0.235778,0.000584,0.236371,0.092906,-0.513504,-0.051639,-0.009712,0.268665,-0.358303,0.215361,-0.447293,0.186701,0.069514,-0.260855,0.054058,-0.025164,0.279062,0.125595,0.188334,-0.063980,-0.389827,0.178962,-0.080448,-0.164271,0.114107,0.299604,-0.327875,-0.401856,0.094481,-0.032784,-0.441537,-0.016936,0.693392,-0.079717,0.148706,-0.101599,-0.522861,-0.419455,-0.337639,-0.064826,-0.183418,-0.173896,0.086144,-0.747006,0.037618,-0.050626,-0.199759,-0.243868,-0.002160,-0.154985,0.530031,-0.163849,0.218559,0.608806,-0.026783,-0.293425,0.512338,-0.178769,-0.009221,-0.055607,-0.181021,0.434284,0.321316,0.226567,0.190358,0.285239,0.295403,-0.241513,-0.334895,0.413817', '1316693', '1309194', '1293433', '1484091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2028819', '纽约提喻法', '剧情', '9月，伴随着秋天到来的，似乎还有戏剧导演凯顿（菲利普·塞默·霍夫曼 Philip Seymour Hoffman 饰）的孤独，因一次意外的受伤，凯顿陷入了无休止的诊疗，不停拜访各专业医生；另一方面，创作微缩油画的妻子阿黛尔（凯瑟琳·基纳 Catherine Keener 饰）和他日渐疏远，冷漠尴尬的家庭气氛加深了凯顿的自我怀疑，即便他的剧目获得巨大成功也不能掩盖这一切。凯顿与在剧场工作的女子以及一名女演员保持着暧昧关系，在妻子抛弃他之后，凯顿从这两个女人身上试图找到改善自我精神状态的可能性，然而他还是失败了。凯顿最后决定从戏剧中找到答案，他产生了一个庞杂的创作计划……©豆瓣', '菲利普·塞默·霍夫曼', '查理·考夫曼', 8.3, 18366, 'tt0383028', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p607383015.jpg', 0.9, 3.2, 17.1, 37, 41.8, '-0.019298,0.186011,-0.540512,0.656201,-0.042495,-0.314610,0.916415,0.301697,-0.572319,-0.442395,0.352671,0.583561,-0.314079,0.069802,0.289156,-0.106053,-0.522304,-0.623128,0.064818,0.033680,-0.147202,-0.445528,-0.322692,-0.232022,-0.149670,-0.357384,0.708490,0.057983,-0.352051,0.438455,0.143950,0.340708,-0.017798,0.467950,0.020773,0.097987,0.157854,-0.193695,-0.447328,0.224181,0.403596,-0.265159,-0.304767,0.328417,-0.165156,0.510366,0.821109,-0.143608,-0.330397,0.226922,0.380469,-0.224059,-0.103002,0.086779,0.007504,0.219105,0.050785,0.331203,-0.323570,-0.096283,0.024617,-0.048586,-0.871497,0.092219,0.174215,0.417425,-0.495045,0.566493,-0.048246,-0.032676,0.089904,-0.204668,-0.010870,0.335580,0.374907,0.495983,-0.374061,0.133425,-0.267581,0.262897,0.455036,-0.006842,-0.572606,0.431402,-0.452640,-0.423077,-0.008032,-0.182558,-0.510032,-0.100878,0.284230,0.225101,-0.145383,0.216150,-0.442903,-0.057480,-0.116796,-0.251772,-0.188188,-0.437844,-0.052956,-0.611147,-0.272968,-0.252112,-0.261865,-0.258304,-0.070890,-0.335062,0.606696,-0.917223,0.243516,0.489623,0.208651,-0.387746,0.417222,0.147818,0.136437,-0.267059,-0.172101,0.318688,-0.386603,0.074516,0.159409,0.362076,-0.052797,0.005302,-0.469456,0.546156', '30401849', '6021916', '3005387', '2301363');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2030563', '吓死鬼', '悬疑', '本片是一出剧中剧：相貌平平的婷（Pitchanart Sakakorn 饰）渴望成为万人瞩目的大明星，为此她在表演进修班刻苦学习。某个夜晚，她受警方邀请成为一名还原凶案过程的演示者。虽然这份工作实在有点阴森奇怪，不过婷却离她的明星梦越来越近。在这一过程中，婷的身边也开始出现诡异现象。某天，泰国选美佳丽敏（Apasiri Nitibhon 饰）遭人杀害，婷意识到这是一个令自己一跃成名的良机，她仔细研究敏的生平和案情，准备全心演好这个角色，不过却因此经历了更多离奇的事件，婷开始更为深入地探究敏被害的秘密。饰演婷的女孩梅在这部恐怖片拍摄过程中也经历了许多怪事，她甚至在现场神秘晕倒。似乎虚幻总与现实相关联，围绕这出根据真实事件改编的恐怖片，更多怪事层出不穷……©豆瓣', 'Pitchanart Sakakorn', '蒙松', 6.9, 16203, 'tt0889212', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2240174777.jpg', 1.6, 8, 45.1, 34.4, 11, '0.168566,0.034719,-0.814590,0.455365,0.399036,0.203479,0.682393,-0.264993,-0.310808,-0.474144,0.260149,0.603618,-0.814241,0.096910,0.204648,-0.143355,-0.337629,-0.685078,-0.048080,-0.251421,-0.356441,-0.252671,-0.012507,0.006440,0.028475,-0.345431,0.683626,0.224660,-0.502814,0.363102,0.251555,0.324947,-0.227917,0.373751,-0.105040,0.109357,0.119408,0.247134,-0.065132,-0.128684,0.295611,-0.436594,-0.505812,0.566674,-0.025865,0.264885,0.813804,-0.282701,-0.586938,0.088391,0.641338,-0.311430,-0.294108,-0.372837,0.303401,-0.072336,0.261429,0.069947,-0.015080,0.135006,-0.440736,-0.116117,-0.983903,0.124006,0.334061,0.154016,-0.155944,0.009401,0.184120,0.293043,-0.148375,0.031277,0.166494,0.186991,0.099797,0.323869,-0.074189,0.003962,-0.153840,0.430297,0.881377,0.279176,-0.419644,0.803116,-0.271973,-0.350119,-0.251552,-0.124845,-0.368747,0.309107,0.174850,-0.195984,-0.020115,0.189105,-0.299030,0.214783,-0.224855,0.013465,-0.142720,-0.063833,-0.323887,-0.547442,-0.229867,-0.377873,-0.367117,-0.270424,-0.179168,-0.757011,0.710987,-0.529548,-0.030325,0.640569,0.118232,-0.575054,0.416734,-0.065167,0.103777,-0.206823,-0.491274,0.125930,-0.248663,-0.214081,-0.099259,0.182808,-0.212069,-0.305298,-0.594322,0.419920', '25928048', '30163500', '26667010', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2032143', '东京奏鸣曲', '剧情', '佐佐木家的小儿子健二（井之肋海饰）偷偷练习钢琴。爸爸龙平（香川照之饰）是一个普通的上班族。妈妈惠（小泉今日子饰）则是家庭主妇。哥哥贵（小柳友饰）是个忙着打工的大学生。这是一个乍看非常普通的日本家庭，但其实每个人都藏有不希望被别人知道的秘密。直到某天健二回到空无一人的家里，一切开始漫漫浮出水面……本片以东京一个四口之家为缩影，深细展现其内部风波，勾画各成员之挣扎轨迹，由此统摄东京乃至日本无数人群在世界经济格局转换、金融危机、中东战争等动荡局势下的生存境遇。本片入选二零零八年《电影旬报》日本电影十大佳片。在戛纳电影节上荣获“一种关注”单元的评委会奖。获得第三届亚洲电影大奖(Asian Film Awards，简称AFA)最佳编剧和最佳电影两个奖项。©豆瓣', '香川照之', '黑泽清', 8.1, 24987, 'tt0938341', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1287238832.jpg', 0.3, 1.3, 18.2, 53.6, 26.6, '-0.000593,-0.025631,-0.510450,0.568759,0.258164,-0.065570,0.429230,0.262458,-0.278562,-0.393369,0.254133,0.879092,-0.270022,0.236093,-0.042871,-0.143919,-0.163911,-0.709897,-0.236986,-0.059840,0.095774,0.000251,-0.198006,0.039822,-0.349180,0.087754,0.782755,0.146655,-0.231527,0.248066,0.353021,0.271022,-0.145962,-0.078683,-0.090353,-0.168642,0.041280,-0.040576,-0.384602,0.377445,-0.326110,-0.235943,-0.160901,0.174163,0.124944,0.141207,0.725150,-0.053812,-0.054757,-0.111182,0.582734,-0.251156,-0.546149,0.047928,0.286912,-0.033967,0.251645,-0.112290,-0.011137,0.126074,-0.047174,-0.258159,-0.706357,-0.170784,0.294253,0.385263,-0.319735,0.248584,0.095307,-0.194030,-0.210794,-0.183264,0.239900,0.364004,0.198254,0.331134,-0.048261,0.268844,-0.356703,0.257660,0.496190,-0.136500,-0.381454,0.394541,-0.157250,-0.468071,-0.052439,-0.362091,-0.418340,0.201090,0.109560,-0.328659,0.220008,0.172028,-0.452199,0.312609,0.108066,-0.588820,0.168036,-0.193634,0.060144,-0.834540,0.043335,-0.174729,-0.229951,-0.134470,0.039967,-0.417423,1.047418,-0.654749,-0.023584,0.476135,-0.029447,-0.445573,0.615887,-0.024775,0.078434,-0.292537,-0.016484,0.022746,0.019182,0.114725,-0.383971,0.311043,-0.155909,-0.222651,-0.334990,0.297344', '27602116', '3811356', '25880986', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2032339', '致命弯道2', '恐怖', '在名为“最后的幸存者”的冒险真人秀节目中，六个年轻人将在教官代尔（亨瑞·罗林斯 Henry Rollins 饰）的领导下，在虚拟的世界末日环境下展开关系到生死存亡的争斗，6天之后，唯一幸存下来的选手即能获得高额的奖金。野心勃勃的妮娜（艾丽卡·李尔森 Erica Leerhsen 饰）不巧和作为替补队员半推半就而来的马拉（阿莱卡萨·帕拉迪诺 Aleksa Palladino 饰）被分在了一组，游戏正式开始。令所有人没有想到的是，他们的到来让一群长久以来生活在这片土地上的畸形食人族们感到无比兴奋，选手们接连遇害成为了它们的盘中饕餮。在目睹了马拉被残忍杀害后，妮娜决定要为自己的生命而战，不久之后，代尔和队友杰克（Texas Battle 饰）也加入了战斗，他们能够战胜凶残的食人族吗？©豆瓣', '艾丽卡·李尔森', '乔·林奇', 6.6, 25797, 'tt0804555', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1578878163.jpg', 2, 10.3, 51.7, 25.6, 10.5, '0.272372,0.204712,-0.681519,0.560239,-0.043911,-0.231153,0.697848,0.083079,-0.449857,-0.047593,0.408406,0.844346,-0.314458,0.006890,0.375689,-0.255807,-0.344792,-0.651770,-0.352458,-0.134293,-0.589555,-0.361938,-0.139897,-0.203252,-0.114459,-0.367951,0.690030,0.083588,-0.025317,0.472837,0.343795,0.369477,0.027499,0.303148,-0.249054,0.109150,0.263850,-0.189182,-0.279050,0.379700,-0.322684,0.048096,-0.174294,0.397146,0.171526,0.224228,0.975217,-0.586651,0.033550,0.004447,0.138304,-0.301954,0.034876,0.178379,0.293308,-0.033728,0.156818,0.131893,-0.053074,0.179018,0.091349,-0.073113,-1.043064,0.121684,-0.108988,0.248373,-0.696716,0.499944,0.035000,-0.078062,0.202899,-0.308154,0.223751,0.500941,0.293230,0.341628,-0.033947,-0.219430,-0.499789,0.076700,1.030769,-0.114163,-0.202015,0.063889,-0.270114,-0.531397,-0.090140,-0.331948,-0.339145,-0.197539,0.642715,0.142961,-0.015971,0.320624,-0.944621,-0.013223,-0.155630,-0.496120,-0.066398,-0.445756,-0.157518,-0.574074,-0.055909,-0.252604,-0.424184,0.183652,-0.026825,-0.342663,0.818673,-1.094704,0.253036,0.440185,0.181161,-0.267824,0.495590,0.105668,0.237137,-0.021652,-0.208524,0.006122,0.283329,0.449816,0.261303,0.375189,-0.251177,-0.047832,-0.299037,0.578675', '1420088', '1793491', '1308837', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2032459', '温柔地杀我', '剧情', '爱丽丝（海瑟•格拉汉姆 Heather Graham  饰）和克劳斯（乌尔里奇•汤姆森 Ulrich Thomsen 饰）的婚姻关系名存实亡，一次偶然的机会，她邂逅了性格粗放的男子亚当（约瑟夫•费因斯 Joseph Fiennes 饰），两个人迅速堕入爱河，从性欲的满足到情感的依赖，她无法自拔。为此，爱丽丝终于跟丈夫摊牌，一直被蒙在鼓里的克劳斯暴跳如雷，两人于是离婚。后来，爱丽丝从闺蜜口中得知，克劳斯一直割舍不下自己，心中稍有悔意，但她还是发现了前夫跟闺蜜同居的事实，极为愤怒。爱丽丝答应了亚当的求婚请求。但对于他的火暴脾气，她还是心存芥蒂，幸好其姐狄波拉（娜塔莎• 麦克艾霍恩 Natascha McElhone 饰）帮忙安抚，爱丽丝才逐渐平静。在交流中，她从狄波拉那里看到了亚当雪山攀岩的照片，并意外发现了丈夫不可告人的秘密……©豆瓣', '海瑟·格拉汉姆', '陈凯歌', 6.3, 15896, 'tt0250468', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1081110199.jpg', 2.7, 14.5, 53.3, 22.7, 6.8, '0.214264,0.135259,-0.816307,0.501389,-0.193735,-0.434372,0.807834,0.069370,-0.632606,-0.228686,0.041881,0.735556,-0.369242,0.354490,0.240742,0.213906,-0.516919,-0.802347,0.259278,-0.062781,-0.190225,-0.510936,-0.158470,-0.276043,-0.143882,-0.270591,0.532971,-0.097324,-0.210379,0.385958,0.422195,0.333876,-0.144538,0.695231,-0.072321,0.045017,0.225562,0.038846,-0.293826,-0.065386,0.138385,-0.131944,-0.168580,0.351085,0.058860,0.578368,0.297473,-0.175193,-0.290970,0.161043,0.151370,-0.111253,-0.008058,0.266631,0.143207,-0.176613,0.126338,0.259132,-0.243913,-0.083733,0.071697,0.095155,-0.315410,0.319682,-0.186244,0.339149,-0.323063,0.462828,-0.303814,-0.016511,0.117581,-0.258325,-0.089828,0.257231,0.266639,0.241219,-0.451949,0.076176,-0.274566,-0.151165,0.438029,0.127933,-0.061617,0.490290,-0.309325,-0.500126,-0.015775,0.163833,-0.502453,0.004780,0.484550,0.246827,-0.348199,0.353113,-0.503716,-0.372973,-0.330234,0.168198,-0.240725,-0.479303,0.012632,-0.416836,-0.419019,-0.432307,-0.425391,-0.071721,-0.038558,-0.182092,0.387940,-0.744703,0.259455,0.417033,0.219197,-0.399130,0.329213,0.246902,-0.135279,-0.466041,0.118085,0.583439,-0.167291,-0.241817,0.261860,0.304994,0.165238,-0.048048,-0.244904,0.460672', '1309080', '3059036', '4275444', '1293776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20326557', '巴黎圣母院', '剧情', '善良的吉普赛女郎艾斯米拉达（海伦娜·赛加拉 Hélène Ségara 饰）天性热情奔放，就连巴黎圣母院的神父克洛德也为其倾倒。为了得到艾斯米拉达，克洛德神父指使教堂中丑陋的撞钟人卡西莫多（加劳 Garou 饰）绑架艾斯米拉达，没想到半路杀出的上尉菲比斯（帕特里克·费欧里 Patrick Fiori 饰）上演了一出英雄救美的好戏。艾斯米拉达深深的爱上了菲比斯，然而后者却被神秘人袭击死于非命，而艾斯米拉达竟然成为了此案的凶手，被判处了绞刑。在前往刑场的途中，卡西莫多出现了，他救走了艾斯米拉达，将她带到了巴黎圣母院，藏在钟楼之内，悉心的照料着她，在此过程中，艾斯米拉达透过卡西莫多可怖的外表，看到了一颗温柔而又柔软的心。©豆瓣', '海伦娜·赛加拉', 'Gilles Maheu', 9.4, 13064, 'tt0285800', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2329626263.jpg', 0.2, 0.2, 3.7, 19.8, 76.1, '0.370941,0.141475,-0.671541,0.468661,-0.082033,-0.510822,0.946996,0.377073,0.061348,-0.136233,0.066111,0.527745,-0.472487,-0.079924,0.535286,0.639209,-0.676179,-0.650240,-0.215776,-0.236971,-0.288423,-0.468173,0.104315,-0.453346,0.095322,-0.455369,0.065614,0.059989,0.047991,0.371862,0.449370,0.770827,0.022176,0.291514,0.067854,0.159159,0.128870,-0.384209,0.263636,0.409087,0.172823,-0.216156,-0.188033,0.285688,-0.051031,0.416348,0.593636,-0.561090,0.359370,0.091728,0.227660,-0.300291,0.551386,0.017542,0.228589,-0.456362,-0.223157,-0.215847,-0.342096,-0.102606,0.579911,-0.172155,-0.325186,0.040629,-0.003415,0.057319,-0.498953,0.385687,-0.190253,0.130200,0.046866,0.026751,0.027855,0.038243,0.208080,0.324094,0.255301,-0.082030,-0.586538,-0.214621,0.223034,0.077327,-0.141048,0.091583,-0.427983,-0.687404,0.045811,-0.155431,-0.424633,-0.245124,0.719519,-0.383946,0.289953,0.433399,-0.495810,-0.193446,-0.832006,0.121420,-0.469084,-0.276633,-0.254531,-0.476515,-0.138447,-0.029252,-0.155117,0.029953,-0.264197,-0.113727,0.402809,-0.535471,0.635621,0.749090,0.136279,0.334600,0.650415,-0.169543,0.191265,0.216361,-0.276421,0.685299,0.464691,0.288605,0.305690,0.334862,0.218147,-0.038572,-0.140700,0.758891', '1578663', '1301686', '4846693', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20326665', '星球大战7：原力觉醒', '动作', '自从银河帝国衰败之后，正邪轮回再度开始，第一秩序的黑暗力量蔓延滋长，重新为银河系带来威胁。与此同时，对于凯洛·伦的堕落深感内疚的天行者卢克宣告失踪，而围绕卢克下落的一份星系地图，则引起敌我双方的争夺。不愿成为战争机器的第一军团士兵芬恩（约翰·波耶加 John Boyega 饰）协助反抗组织成员波·达摩龙（奥斯卡·伊萨克 Oscar Isaac 饰）逃到蛮荒星球贾库，寻找藏有地图的机器人BB8。两人失散后，芬邂逅拾荒者蕾伊（黛茜·雷德利 Daisy Ridley 饰）和BB8。他们乘坐破旧的千年隼号躲过了军团的追杀，此后更遇到千年隼号的主人汉·索罗（哈里森·福特 Harrison Ford 饰）。第一秩序制造了破坏力远超死星的弑星者基地。宇宙和平危在旦夕，某人体内的原力则悄然苏醒……©豆瓣', '哈里森·福特', 'J·J·艾布拉姆斯', 7.2, 210371, 'tt2488496', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2293954118.jpg', 1.6, 5.7, 39.5, 38.9, 14.3, '0.012794,0.284689,-0.639354,0.475824,0.323103,0.005841,0.376228,0.042327,-0.180576,-0.230735,0.109858,0.444571,-0.024148,-0.017756,0.329669,-0.217024,-0.308275,-0.510058,-0.012680,-0.250396,-0.236172,-0.267241,-0.386039,-0.226131,0.053514,-0.696834,1.005837,0.172247,-0.165904,0.318669,-0.113446,0.776446,-0.298233,0.258658,0.038833,0.028644,0.133036,-0.177141,-0.392836,0.193689,-0.438993,-0.108075,0.137217,0.355247,-0.072401,0.178040,0.824983,-0.575207,0.398883,-0.617171,0.275726,-0.240676,-0.077412,-0.365083,0.634122,-0.010842,-0.236941,0.275272,0.053370,0.082133,-0.000760,-0.108134,-0.807611,-0.051267,0.086932,0.245919,-0.211628,0.096300,-0.217902,0.009979,0.075717,0.056566,0.219232,0.694949,0.260194,0.115463,-0.166005,0.054509,-0.390462,-0.211769,0.469850,-0.299685,-0.291793,0.135149,0.140603,-0.408845,-0.254945,-0.145916,-0.203900,-0.331005,0.413777,0.278214,0.497412,0.677703,-0.976955,-0.038581,-0.438371,-0.411476,0.149857,-0.133547,-0.093270,-0.819807,-0.108621,-0.024112,0.127322,0.215160,-0.047939,0.102364,0.530970,-0.554894,0.404689,0.359534,0.427519,-0.468151,0.268616,-0.193438,0.251866,-0.530075,0.163733,0.608273,0.352062,0.444661,0.086090,-0.092705,0.043830,0.102000,-0.108626,0.456384', '30201138', '7051375', '2369613', '26759