INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2033543', '小说', '剧情', '源起会议之国的小型讲座，一群伟人聚在一起，开了一个伟大的讨论会，伟大的主题是:“什么是诗意”。开场一个象征镜头，影机先是追踪着火车，开进小城，再走到大街小巷，然后停靠酒店，走进局促的会议室。接着，一批有头有脸的作家杀入镜头，阿城、王朔、马原、方方、余华、棉棉，从阿城的“诗意”考古开始，讲到“有钱就有诗意”。各抒己见的过程中，大家谈得性起，渐将诗意按压在自我之下。镜头有时溜出来，看另一种风景。一旁的会议策划人，在酒店偶遇旧爱，更能体味点点诗意。演员王彤和王志文，就演着也许由作家虚构的故事，他们的存在，比作家更真实。吕乐一个革命式的举动:拆走纪录片与剧情片框框，将两者放在同一议题与空间自由对话。', '王志文', '吕乐', 8.2, 6424, 'tt0989890', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2515131382.jpg', 0.7, 1.9, 16.9, 49.2, 31.4, '0.548840,0.098983,-0.394297,0.629442,0.077436,-0.004501,0.704638,0.280065,-0.275816,-0.017217,0.353845,0.699526,-0.431513,0.259366,0.380734,-0.189245,-0.414253,-0.598538,-0.158948,0.034091,-0.187792,-0.431820,0.061534,-0.002321,0.083983,0.069741,0.371075,0.042682,-0.424004,0.302869,0.200397,-0.100139,-0.499858,0.203727,-0.360929,-0.046328,0.154959,0.073175,-0.369516,0.224485,-0.114872,-0.187681,-0.289829,-0.068293,-0.197415,-0.120193,0.782765,-0.099179,-0.067189,0.376675,0.549556,-0.129160,-0.064424,-0.153296,0.229392,0.223860,0.213337,0.096796,0.127529,0.288264,-0.117911,-0.103363,-0.529728,0.026616,-0.107733,0.330776,-0.412446,0.450683,0.085929,-0.324833,0.222520,-0.286846,0.308398,-0.006736,0.345371,0.410685,0.076060,0.121054,-0.295664,0.247973,0.285512,0.088342,-0.339633,0.522708,-0.083505,-0.353892,-0.027386,0.252906,-0.221914,-0.261208,0.411166,-0.260308,0.153553,-0.012530,-0.794089,0.138660,0.087629,-0.290904,0.150949,-0.294876,-0.156255,-0.733144,0.000294,-0.003291,0.027851,0.025850,0.071179,-0.051898,0.823560,-0.531251,0.000341,0.435909,-0.037526,-0.183721,0.703728,-0.046072,0.026809,-0.291939,0.087695,0.055662,-0.154527,0.499914,-0.102387,0.632685,-0.374040,-0.225093,-0.576267,0.314184', '3811356', '5403927', '1302661', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2033822', '美食、祈祷和恋爱', '剧情', '年轻干练的伊丽莎白·吉尔伯特（朱莉娅·罗伯茨 Julia Roberts 饰）是《纽约时报》的一名人气作家，她经常周游世界，撰写相关的旅游文章。她的生活同样令人欣羡，丈夫史蒂芬（比利·克鲁德普 Billy Crudup 饰）帅气潇洒、气质不凡；饮食无忧、优哉安 乐。然而伊丽莎白却渐渐感到空虚和恐慌，似乎着周遭的一切都不是她真正追求的。伊丽莎白决定走出变质的婚姻，寻找自我。在漫长的离婚拉锯战后，她踏上了周游世界的旅途，在美食、祈祷和恋爱中，认真地思考人生的种种……本片根据伊丽莎白·吉尔伯特（Elizabeth Gilbert）的同名自传改编，著名影星布莱德•彼特担任该片制片人。©豆瓣', '朱莉娅·罗伯茨', '瑞恩·墨菲', 7.4, 113585, 'tt0879870', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p582794306.jpg', 1.1, 6.1, 35.7, 38.3, 18.8, '0.282009,-0.040843,-0.624262,0.556942,0.011958,-0.533211,0.744509,0.231255,-0.369649,-0.435708,0.118239,0.765419,-0.388982,0.405253,0.334861,0.061668,-0.507398,-0.640131,-0.158990,0.095552,0.258875,-0.429803,-0.310568,-0.167333,-0.183813,-0.222818,0.610266,-0.008225,-0.152209,0.522497,0.207711,0.257029,-0.015292,0.325451,-0.076935,0.127056,0.275646,-0.051778,-0.244481,-0.096062,0.199204,-0.157982,-0.318506,0.190158,0.154633,0.228470,0.654105,-0.149170,-0.064413,0.222983,0.601479,-0.145345,0.069121,0.073335,-0.227050,0.209105,-0.074633,0.148786,-0.242415,0.002373,-0.067267,-0.227263,-0.598938,0.015158,-0.071907,0.432442,-0.297346,0.390581,-0.106643,-0.152791,0.264599,-0.281800,0.036301,0.103324,0.405286,0.383790,0.189763,0.360423,-0.177515,0.543979,0.480592,0.346982,-0.478062,0.312727,-0.612888,-0.309175,-0.095536,-0.020732,-0.740523,-0.281389,0.374495,0.057465,0.262712,0.375046,-0.541452,0.076756,-0.140875,-0.218412,-0.152091,-0.211139,-0.091734,-0.892751,-0.249940,-0.617814,-0.240765,-0.472415,0.032030,-0.360943,0.740722,-0.632389,0.229056,0.411623,-0.116283,-0.541020,0.526490,0.117304,0.086863,-0.262791,-0.051416,0.896863,-0.171727,-0.030969,-0.139060,0.457065,0.010556,0.106216,-0.566414,0.787532', '1296992', '3811356', '3001472', '3097044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2034948', '诺桑觉寺', '剧情', '根据奥斯丁同名小说《诺桑觉寺》改编而成。乡村牧师之女凯瑟琳（Felicity Jones饰）是个天真烂漫的少女，受闭塞的家庭环境所限，她终日在小说天地里徜徉探幽，以此为平淡生活增亮添彩。在有钱朋友的引领下，凯瑟琳进入了上流社会的社交圈，她终于见识到现实中的花花世界，其中不乏虚伪狡猾者如索普兄妹和蒂尔尼将军，也有值得终身结交的挚友艾丽诺。凯瑟琳和艾丽诺的哥哥：温文尔雅、俊逸潇洒的亨利（JJ Feild饰）一见倾心，再见钟情，理所当然的，迎接他们的也将是奥斯丁的男女主人公势必经历的种种磨难和考验。©豆瓣', '菲丽希缇·琼斯', 'Jon Jones', 7.3, 18750, 'tt0844794', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2377908684.jpg', 0.2, 3.1, 39.7, 44.1, 12.9, '0.509611,-0.007591,-0.389942,0.767531,-0.146379,-0.103141,0.751501,0.061487,-0.468586,-0.166661,0.274447,0.839602,-0.174245,0.310866,0.421774,0.036488,-0.280560,-0.504943,-0.316858,-0.211569,0.089442,-0.435213,-0.281131,0.019603,-0.208766,-0.565726,0.540281,0.015176,-0.062595,0.521435,0.182659,0.371444,-0.256874,0.217336,-0.333908,0.141739,-0.064249,0.331951,-0.463475,0.037824,-0.061630,-0.306848,-0.156478,-0.052330,-0.027869,0.125849,0.631673,-0.368482,-0.173524,0.185557,0.549128,-0.001865,0.004733,0.155680,0.045716,-0.146497,0.230719,0.335674,-0.021555,0.133582,-0.133924,-0.267574,-0.723658,-0.209015,0.483374,-0.133439,-0.468856,0.596400,0.198527,-0.400277,0.134659,-0.016985,0.049829,0.099351,0.354914,0.292684,0.201825,0.047647,-0.352216,0.495655,0.650217,0.303549,-0.417296,0.243793,-0.606347,-0.484921,0.022468,-0.452455,-0.913761,0.055540,0.214105,-0.124931,0.014272,0.506618,-0.546008,0.141680,-0.186899,0.038664,0.149956,-0.440849,-0.094889,-0.634382,-0.403477,-0.636237,-0.255495,-0.102358,0.238395,-0.423416,0.992338,-0.936413,0.101579,0.487392,0.096901,-0.480438,0.970501,-0.035122,0.090664,-0.064974,-0.172646,0.425945,0.189022,0.221045,-0.094513,0.517764,-0.094487,0.135892,-0.419743,0.512648', '26348103', '1292720', '3445516', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2034997', '故园风雨后', '剧情', '平民小伙子查尔斯·莱德（马修·古迪 Matthew Goode 饰）怀着一腔梦想进入牛津大学，不久便结识了引人注目的塞巴斯蒂安·弗莱特（本·卫肖 Ben Whishaw 饰），并和他成为好友。塞巴斯蒂安英俊得惊人，又出身豪门，生性满怀敏感和忧愁，他带着查尔斯进入自家豪宅——布赖兹赫德庄园，介绍他认识自己的家人，查尔斯很快迷恋上其姐茱丽叶（海莉·阿特维尔 Hayley Atwell 饰），但茱丽叶迫于母亲压力和天主教徒雷克斯（Jonathan Cake 饰）订婚，令查尔斯恋情无果，而塞巴斯蒂安对查尔斯的感情也只能止于暧昧。十年光阴过去，查尔斯已经是知名画家，在渡轮上偶遇茱丽叶，试图重续旧情再度失败，又得知塞巴斯蒂安已经远走国外。再度回到布赖兹赫德庄园，查尔斯已经是一名军官，大宅已经在战争中彻底破败……©豆瓣', '艾玛·汤普森', '朱里安·杰拉德', 7.8, 41988, 'tt0412536', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p584617950.jpg', 0.3, 2, 27.3, 50, 20.3, '0.340862,0.143147,-0.548935,0.390073,0.191479,-0.653137,0.752894,0.088484,-0.599153,-0.350536,0.016383,0.856071,-0.103720,0.419437,0.376564,0.187582,-0.616772,-0.535115,0.061353,-0.360903,-0.000659,-0.618114,-0.168562,-0.066611,-0.105351,-0.387907,0.433080,-0.074979,-0.007034,0.688850,0.500062,0.575303,-0.127023,0.501428,-0.069375,0.203745,0.289671,-0.144307,-0.463837,-0.118790,-0.038990,-0.131730,-0.197361,-0.032752,0.106451,0.236031,0.350040,-0.110063,0.107931,0.058603,0.152128,-0.041924,0.114917,0.186620,0.293479,-0.145706,0.132148,0.303869,-0.209923,-0.063205,-0.026100,-0.093063,-0.090061,0.183251,-0.062392,0.018543,-0.429631,0.520120,-0.115902,-0.078993,0.160679,-0.348595,-0.172542,0.139911,-0.014137,0.283387,-0.002186,0.105550,-0.281042,-0.029762,0.395041,0.114307,-0.246906,0.255535,-0.249318,-0.359898,0.011204,-0.182356,-0.547636,-0.098984,0.496687,0.032497,0.103872,0.527867,-0.408388,-0.127859,-0.659081,-0.020152,0.146799,-0.135437,0.133039,-0.898323,-0.354520,-0.345146,-0.388265,-0.168474,-0.006926,-0.107338,0.343763,-0.777812,0.352411,0.363400,0.265984,-0.168872,0.370279,0.002719,0.159046,-0.188850,-0.114847,0.705969,-0.069140,0.055207,0.086329,0.259552,-0.050561,-0.045095,-0.196012,0.594109', '1297239', '1945337', '1298095', '2372389');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2035642', '2077日本锁国', '动作', '21世纪初，日本生物科技高度发达，其所研制并独家垄断的生物机器人极大推进了时代的进步，但同时其潜在的危害性也不断受到世界各国的指摘。不满于其他国家对该技术限制的呼声，日本于2067年单方面退出联合国，用高科技手段屏蔽一切外来信号，再次进入锁国状态。此后整整10年间，关于日本的现状外界一无所知。美国政府急于了解日本当前的状况，虽派出特种部队SWORD秘密潜入这个已经封闭了十个年头的神秘国家。当特种队员VEXILLE（黒木メイサ 音）和里昂（谷原章介 饰）进入日本后，眼前的一切却令他们大吃一惊……©豆瓣', '黑木美沙', '曾利文彦', 7.1, 10157, 'tt0970472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1076979245.jpg', 1.2, 5.9, 40, 40.6, 12.3, '-0.045575,0.424376,-0.516590,0.432508,0.111327,0.364308,0.057953,-0.350577,-0.835922,-0.551308,-0.406966,0.401015,0.118183,-0.160093,-0.045960,-0.280224,-0.240400,-0.526473,-0.285684,-0.435144,-0.359872,-0.569443,-0.488004,-0.671857,-0.400419,-0.344254,0.789038,0.194361,-0.731843,0.051294,0.012606,0.422599,-0.215944,0.435300,0.223247,-0.358042,0.363569,-0.335521,-0.622588,0.171591,-0.491134,-0.151634,0.175059,0.258440,-0.095138,0.194054,0.496814,-0.635671,-0.260062,-0.396203,0.402610,-0.091381,-0.591979,-0.013525,0.414416,0.220738,-0.024319,0.239314,-0.004370,0.177702,-0.124805,-0.001714,-0.685898,-0.196727,0.265276,0.015968,-0.219934,0.183316,-0.226897,0.218256,-0.349561,-0.233080,0.013169,0.458325,0.361229,0.534974,-0.161151,0.074955,-0.172280,-0.141256,0.588452,-0.111687,-0.704632,0.214720,-0.317413,-0.603248,-0.420790,-0.227198,-0.029535,0.049011,-0.017313,0.350178,-0.149048,0.482903,-0.545779,0.380250,-0.036283,-0.510733,0.084401,-0.139905,0.154763,-0.933175,-0.171095,-0.531916,-0.305270,0.213905,0.334673,0.077769,0.797969,-0.689274,0.084642,0.437659,0.346047,-0.668962,0.322198,-0.114504,0.035785,-0.389619,-0.361877,0.352942,-0.094227,0.430956,-0.347631,0.109435,0.085002,-0.532147,-0.045934,0.029944', '2369613', '1946776', '30465281', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2036270', '女招待', '剧情', '吉娜(凯丽•拉塞尔 饰)擅长制作各种美味非常的馅饼,她把每天在生活中的经历都化为做馅饼的灵感。但实际上她的生活并不快乐，她被一段名存实亡的婚姻困扰多年。她一心想参加馅饼比赛，得到足够多的钱之后离开丈夫厄尔（杰瑞米•西斯托 饰）现自己怀孕了，她知道自己的丈夫是个自私的人，无法养育孩子。她十分迷茫之际，遇到了妇产科医生波马特（内森•菲利安 饰）并且两人疯狂的恋上了，波马特也是个已婚之人。她知道自己的行为是错误的，但她还是不能控制的与波马特见面，受尽良心谴责的她从朋友身上得到了很多的启示。就在女儿出生当天，她决意要与丈夫分开，也要好好处理与波马特的关系。©豆瓣', '凯丽·拉塞尔', '安德林妮·夏莉', 7.4, 6100, 'tt0473308', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1302051134.jpg', 0.7, 4.4, 36.4, 43.4, 15.1, '0.333898,-0.073654,-0.676939,0.471697,-0.368168,-0.263191,0.924004,0.088928,-0.485411,-0.202239,0.132955,0.921822,-0.167648,0.270220,0.212625,0.211564,-0.112325,-0.671786,0.367465,-0.107923,-0.220944,-0.486821,-0.200380,-0.258833,-0.226958,-0.250909,0.412206,0.139936,0.105649,0.130486,0.312004,0.043409,0.255525,0.681941,-0.139355,0.114028,-0.151117,0.079157,-0.076528,0.063989,0.341766,-0.266880,-0.031858,0.419313,0.134540,0.347452,0.551211,-0.138265,-0.256983,-0.108365,0.313770,-0.245816,0.047668,0.290346,-0.096991,-0.023376,0.147771,0.244913,-0.220214,-0.060881,0.110864,-0.034543,-0.923088,-0.092793,0.207010,0.154887,-0.857903,0.564376,-0.214800,-0.003587,-0.215251,-0.607925,0.193688,0.297267,0.224491,0.395317,-0.277645,-0.186593,-0.669190,0.252048,0.900122,-0.031802,-0.167566,0.454398,-0.494251,-0.507932,0.089550,-0.344906,-0.540124,0.189518,0.208674,0.066649,-0.456843,0.292299,-0.329876,0.126648,-0.372124,-0.323190,-0.126096,-0.585397,0.124770,-0.111011,-0.280359,-0.581371,-0.705432,0.046428,-0.005271,-0.525752,0.781967,-1.010080,0.171340,0.637740,0.364373,-0.732534,0.696911,0.298614,0.167235,-0.159227,0.169889,0.260859,-0.134129,0.091509,0.120880,0.376160,0.461224,0.059939,-0.244096,0.614293', '1877596', '1303112', '1308805', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20365404', '金钱怪兽', '剧情', '知名电视财经专家李·盖茨（乔治·克鲁尼 George Clooney 饰）在电视财经节目《金钱怪兽》中担任主持人而声名大噪，在节目中经常出现疯狂举动，会大声说出投资建议，不时在节目中用搞笑的道具和音效介绍股市。然而，事实上他是透过内线消息让他在华尔街成为赚钱高手。一名不速之客（杰克·奥康奈尔 Jack O''Connell 饰），因为听信投资分析而赔光积蓄，因此在节目直播中绑架了盖茨与节目制作人帕蒂·芬恩（朱莉娅·罗伯茨 Julia Roberts 饰）。同时全国民众也透过电视在看着这场玩命直播，而这场挟持行动也揭发了背后更巨大的金融操弄丑闻。', '乔治·克鲁尼', '朱迪·福斯特', 6.8, 15760, 'tt2241351', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2325326034.jpg', 0.8, 7.2, 49, 35, 8, '-0.245800,0.177766,-0.660118,0.580223,0.096550,0.459300,0.571278,0.047547,-0.371888,-0.161872,0.172184,0.603192,-0.576856,0.059712,0.308699,-0.308465,-0.520000,-0.796568,0.079136,-0.055141,0.023523,-0.530239,-0.255906,-0.707484,-0.087462,-0.325041,0.529607,0.044953,-0.595962,0.280816,0.629893,-0.008708,-0.030161,0.391798,0.376969,-0.154667,0.408757,0.202806,-0.138515,0.246497,0.099160,-0.732958,-0.327281,0.146198,0.324691,0.183743,0.447655,-0.336169,0.232774,0.144737,0.276965,-0.411786,0.115069,0.024308,0.299192,0.161044,0.521117,-0.072371,-0.180670,0.178047,-0.024538,-0.120674,-0.587629,0.158294,-0.052970,0.385860,-0.321215,0.176002,-0.359932,0.237960,0.034794,-0.096906,0.135805,-0.002183,0.617940,0.299930,0.078832,-0.045552,-0.321769,0.517791,0.171447,0.207591,-0.173339,0.340849,-0.068118,-0.282298,-0.164203,-0.110638,-0.430659,-0.119356,0.472804,-0.444048,0.143873,0.411353,-0.274486,-0.053096,0.344302,-0.484504,-0.015173,-0.323248,-0.151482,-1.275044,-0.091489,0.044132,0.103891,-0.049415,0.083088,-0.507366,0.808222,-0.630956,-0.033094,0.456998,0.324406,-0.164114,0.804866,-0.181827,0.211843,-0.049272,-0.245390,-0.322303,0.139422,-0.025777,0.090597,0.095535,0.074738,-0.615728,-0.121694,0.475401', '3003137', '34961898', '3318306', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20369263', '巴啦啦小魔仙', '儿童', '在一个月朗星稀的夜晚，美雪（易蜜儿 饰）、美琪（周利书 饰）、石小龙（沈策 饰）等好朋友在观星露营时，意外目击一枚硕大的陨石。连同陨石一同出现的，还有神秘的魔法师和受伤的美丽小鸟。美雪、美琪将小鸟带回家，并为之取名小星。未过多久，两个神秘怪异之人盯上了凌家姐妹。而各种危机和诡异事件也交替发生在姐妹俩的身上。正在此危急时刻，小蓝（廖景萱 饰）和游乐王子（袁奇峰 饰）及时赶到，化解了美雪她们的危机。原来名叫哈莱星的星球发生异变，脱离轨道的哈莱星正向地球撞来。危险渐次逼近，正义的小魔仙最终能否拯救世界……本片为同名电视剧的电影版。©豆瓣', '廖景萱', '李欣', 4.1, 8163, 'tt6967268', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1838140309.jpg', 51.9, 17.3, 14.4, 6.3, 10.1, '0.110558,0.204381,-0.771879,0.212457,0.277394,0.172615,0.748206,0.219042,-0.197389,-0.288635,0.566959,0.503130,-0.421979,0.052176,0.428813,0.165355,0.043730,-0.586286,0.008207,-0.032178,-0.403103,-0.291940,-0.372369,0.096341,0.114091,-0.443021,0.435613,0.231085,0.071716,0.735531,0.142897,0.296994,-0.802919,0.412720,-0.098495,-0.009434,-0.011059,0.151368,-0.465102,0.158755,-0.075040,-0.110165,0.032800,0.140249,-0.077082,0.266884,0.877294,-0.451556,-0.230362,-0.168277,0.167587,-0.158566,0.061212,-0.009776,0.326695,-0.126634,0.161859,-0.116647,-0.151962,0.181816,0.228314,-0.049905,-0.489340,0.368893,0.215875,0.312963,-0.280254,0.234874,0.120640,-0.153180,0.298283,-0.328813,0.317383,0.454589,0.201071,0.396755,-0.361677,0.211026,-0.236175,-0.043251,0.474548,-0.095685,-0.240751,0.369511,0.119006,-0.124447,-0.156771,0.090071,-0.376342,0.110890,0.503379,0.120830,-0.129304,0.335182,-0.916339,0.121836,-0.242746,0.117080,0.146770,-0.288785,-0.295631,-0.544582,0.129139,-0.249567,-0.244635,0.270809,0.123005,-0.094878,0.760001,-0.687985,0.329609,0.377192,0.325410,-0.270919,0.415414,-0.122531,0.028799,-0.204269,-0.163850,0.026751,0.037817,0.501020,-0.116525,0.225769,-0.028784,-0.136995,-0.559201,-0.013288', '1856675', '1309194', '26220731', '26839466');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2036996', '校墓处', '恐怖', '纳兰慕德中学的一面墙上，有一个像人影的污渍，怎样粉刷都无法掩盖。人影自十年前的一场大火，污渍便出现了，夜半常常有怪声四起，闹鬼传闻就在校园中传开。高强（徐天佑饰）、查理（李逸朗饰）、宾仔（麦子豪饰）与阿狄（张智恒饰）在强行的教育政策下来到了纳兰这所女校，学校也因此闹哄哄的。学校一直禁止学生谈恋爱，训导主任方老师（李惠敏饰）也极力阻止，因此她故意刁难几个新来的男生。可是情窦初开的年轻人还是受不了爱情滋味的甜蜜，纷纷坠入情网。这是条被诅咒了的校规，犯规了的几个都离奇失踪死亡，高强与逸敏（傅颖饰）把对彼此的感觉暂时放下，决定救回自己的好友。事情却不像他们想象的简单。©豆瓣', '徐天佑', '钱文锜', 5.8, 13016, 'tt0989654', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2246973237.jpg', 6.3, 22.2, 50.6, 15.5, 5.4, '0.548064,-0.093706,-0.577721,0.490115,-0.238418,-0.125445,0.804624,-0.002534,-0.575816,-0.237995,0.290303,0.450458,-0.346857,0.447450,-0.023057,-0.105926,-0.199339,-0.731847,-0.005143,-0.230576,-0.332246,-0.293729,-0.118268,-0.216479,-0.197791,-0.104995,0.387412,0.307127,-0.243709,0.358800,0.370959,-0.044524,-0.098518,0.653584,-0.171450,0.074872,0.039279,0.310251,0.152584,-0.189950,0.066893,-0.447589,-0.236035,0.032907,0.109088,0.388094,0.414135,-0.034166,-0.180624,0.204680,0.499707,-0.396279,-0.021147,0.311447,0.589140,-0.121050,0.229313,0.056885,-0.094045,0.138440,-0.051495,0.081617,-0.336687,0.002726,0.145503,0.085977,-0.625109,0.572511,0.060784,-0.235819,0.011101,-0.205137,0.054397,0.060955,0.201847,0.432862,-0.255140,-0.101604,-0.614912,0.143564,0.651039,0.090488,-0.536681,0.103782,-0.292041,-0.438276,-0.212866,-0.131606,-0.255328,0.037639,0.340390,0.018597,-0.380126,0.170904,-0.460184,-0.128746,-0.069393,-0.129469,-0.097894,-0.394169,-0.264415,-0.544815,-0.110158,-0.411634,-0.456212,0.141985,0.117969,-0.179687,0.620382,-0.787772,0.216237,0.329995,0.077743,-0.408951,0.425982,0.149482,0.055557,0.000136,-0.126673,0.129080,0.134243,0.498478,0.301461,0.597415,-0.041772,-0.141695,-0.296790,0.461917', '1308755', '1301022', '5262027', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2037012', '革命之路', '剧情', '当他们第一次见面，他是高谈阔论的有志青年，她是向往成为名演员的未来之星。而如今，婚后的他们变了。他变成了在公司做不喜欢工作的无聊上班族，她成了不入流的糟糕演员。在一次演出后，丈夫弗兰克（莱奥纳多•迪卡布莱里奥饰）与妻子爱波（凯特•温斯莱特饰）大动肝火，两人多年的积怨终于爆发。莫非婚姻真的躲不过七年之痒？悲痛的爱波整理照片，发现弗兰克年轻的照片，想起他曾经描述的“美好的巴黎”，她提出了一个计划“全家搬到巴黎”，以拯救这个家庭。但是，这看似遥不可及的计划，却成为了催化剂，将两人推向婚姻更痛苦的深渊。©豆瓣', '凯特·温丝莱特', '萨姆·门德斯', 8.2, 201715, 'tt0959337', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p480460526.jpg', 0.2, 1.2, 18.1, 50.9, 29.6, '0.369928,-0.018196,-0.669519,0.508958,-0.193934,-0.401388,0.883367,0.096841,-0.372221,-0.181354,0.139596,0.873111,-0.285674,0.563146,0.293351,0.200720,-0.270695,-0.844850,-0.014427,-0.061681,-0.055985,-0.373792,-0.239908,-0.290268,0.005565,-0.265040,0.656133,0.156918,-0.071422,0.180063,0.456812,0.249909,0.147905,0.468985,-0.251240,-0.005181,0.161791,0.318772,-0.344975,-0.000152,0.026983,-0.135687,-0.111090,0.207798,0.035056,0.398708,0.431312,0.012588,-0.269546,0.094556,0.681667,-0.385573,-0.141999,0.111802,0.272720,-0.017049,-0.005454,-0.020676,-0.107823,-0.264317,-0.010498,-0.171044,-0.874955,0.160200,0.073059,0.121035,-0.710008,0.533982,-0.027796,0.040086,0.121418,-0.261377,0.127551,0.320645,0.303324,0.334226,-0.073388,0.027495,-0.534006,0.345448,0.852370,-0.011104,-0.518201,0.531507,-0.179885,-0.337962,0.085939,-0.190247,-0.518768,0.057163,0.279129,-0.122859,-0.171961,0.346528,-0.486395,-0.201231,-0.249843,-0.091101,0.151987,-0.488401,-0.312455,-0.350384,-0.454479,-0.451021,-0.507491,-0.103076,0.008384,-0.472067,0.605511,-0.812347,0.042145,0.310689,0.015899,-0.599330,0.777853,0.151224,0.053824,-0.286349,0.203290,0.349398,-0.211690,0.086972,0.158297,0.229588,0.020611,0.135327,-0.439950,0.653318', '30162520', '1783461', '1306916', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20376577', '小时代', '剧情', '这是一个梦想闪耀的时代，这也是一个理想冷却的时代；这是最坏的时代，这也是最好的时代，这是我们的小时代。 这是当下时代一群时尚年轻人的青春故事，也是属于他们生活的真实写照，更是我们这个时代的一个缩影。故事发生在经济飞速发展时期的上海，主人公林萧（杨幂 饰）、顾里（郭采洁 饰）、南湘（郭碧婷 饰）、唐宛如（谢依霖 饰）四个女生在这座风光而时尚的城市里生活与学习、工作与成长，四个女生从小感情深厚，却各自有着不同的价值观与人生观，她们在同一个宿舍朝夕相处，转眼到了大学生涯的后期，平静的生活开始面临层出不穷的挑战，找工作实习的忙碌以及随之而来的巨大生存压力，看似平静的校园生活相继发生着种种让她们措手不及、不知如何面对、需要抉择的事情。同时，顾源（柯震东 饰）、简溪（李悦铭 饰）、宫铭（凤小岳 饰）、崇光（陈学冬 饰）、卫海（杜天皓 饰）、席城（姜潮 饰）等一群男生和这四个女生之间也正发生着千丝万缕的情感交错……面临巨大生存压力，面对剪不断理还乱的情感纠葛，四个女生要先后经历友情、爱情，乃至亲情的巨大转变，在巨变面前，她们是否依然坚持自己的生活态度，她们的青春故事将如何续写精彩？本片根据同名畅销小说《小时代》改编，郭敬明亲自操刀编剧，并首度跨界担任电影导演。', '杨幂', '郭敬明', 4.9, 406600, 'tt3043630', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2004121607.jpg', 25.9, 25.6, 31.8, 10, 6.8, '0.083983,0.062104,-0.661674,0.546825,0.067187,0.011523,0.660757,0.198003,-0.374184,-0.406528,0.164763,0.449648,-0.100746,0.283679,0.305221,-0.482724,-0.243472,-0.710649,-0.029448,-0.055527,-0.155394,-0.317395,-0.318050,-0.072322,-0.136692,-0.196270,0.782784,-0.025990,-0.311724,0.392911,0.488227,0.263753,-0.307491,0.255496,-0.119846,-0.145525,0.050142,0.344451,-0.565013,-0.121888,-0.068655,-0.004358,-0.122455,-0.029943,-0.155778,0.158059,0.639804,-0.181754,-0.229520,0.002749,0.500047,-0.039266,-0.469152,-0.043531,0.200382,0.030100,0.188211,0.196843,0.160277,-0.001863,-0.019774,-0.245493,-0.722334,0.029965,0.334506,0.415144,-0.413171,0.462862,0.187935,-0.363802,0.074952,-0.202443,0.098653,0.490760,0.702218,0.563771,-0.182222,0.114544,-0.254870,0.346262,0.845413,0.163708,-0.471684,0.450363,-0.474806,-0.216650,-0.347459,-0.140514,-0.681852,0.039173,-0.195314,0.014522,-0.115431,0.351338,-0.722816,0.329952,0.106645,-0.137042,0.133357,-0.517977,0.014553,-0.655917,-0.242413,-0.714285,-0.458651,0.015509,0.167800,-0.273194,1.034161,-0.599689,0.075284,0.240373,0.277185,-0.528814,0.576591,0.190448,0.224375,-0.403691,-0.146210,0.353719,-0.281729,0.066842,-0.379025,0.390159,-0.146513,0.047302,-0.432636,0.554881', '27602116', '3811356', '2053515', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2037796', '丑女大翻身', '喜剧', '身高169cm，体重95kg的韩娜（金雅中 饰）是个向往爱情的普通女子，她拥有动听的嗓子，可是只能做歌手亚美的幕后代唱。她暗恋着制作人韩尚俊（朱镇模 饰），尚俊十分欣赏她的嗓音，可是她深明尚俊是不会喜欢丑陋的自己的。韩娜决定到美容院整容，整形成功后，她便参加了新任歌手的选拔。动听的嗓音同样吸引了尚俊，决定把她捧红。她害怕尚俊会认得她，更为自己起了个名字叫珍妮。珍妮很快便窜红了。亚美感到自己的地位受到威胁，于是开始调查珍妮的身世。众人都知道了珍妮的故事，可她无法面对支持她的歌迷，在台上一反常态，她感觉自己失去了自我，到底接下来她将如何面对突如其来的改变呢？©豆瓣', '金雅中', '金容华', 7.2, 139493, 'tt0940642', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1765318197.jpg', 0.6, 4.2, 42.4, 40.1, 12.7, '0.377813,0.243454,-0.592160,0.695353,-0.400804,0.085919,0.585025,0.256949,-0.361602,-0.031555,0.282128,0.708869,-0.293239,0.281177,-0.088895,0.284975,-0.096145,-0.672103,-0.020925,-0.091077,-0.083812,-0.234960,-0.124688,-0.154111,-0.157983,-0.139248,0.422361,-0.161287,-0.369996,0.166476,0.489524,0.079197,0.532552,0.476811,-0.007693,0.006103,0.047069,-0.096170,0.171045,0.100286,0.208970,-0.389879,-0.143038,0.597055,-0.206002,0.404359,0.476057,-0.256027,-0.074404,0.080335,0.483559,-0.334883,0.145640,0.197969,0.010441,0.099603,-0.013485,0.087543,-0.428358,-0.132729,0.110452,0.126304,-0.737757,0.353645,0.266941,0.284756,-0.416449,0.182423,-0.417628,0.169316,0.241892,-0.331223,-0.025212,-0.089815,0.321371,0.245933,-0.087903,0.099965,-0.325848,0.262359,0.822137,0.045380,-0.316012,0.444826,-0.395163,-0.632981,-0.215712,-0.389823,-0.560575,0.025323,0.074900,0.181779,-0.030440,-0.113033,-0.235110,-0.139660,-0.117206,-0.331683,-0.224612,-0.450844,-0.189556,-0.089800,-0.411665,-0.452459,-0.344680,-0.253129,-0.028664,-0.322091,0.906621,-0.757468,-0.007692,0.625321,0.092330,-0.500939,0.425888,0.146243,-0.192337,-0.141007,-0.092892,0.377238,-0.290693,0.009466,0.125095,0.358943,-0.001807,-0.102016,-0.420516,0.579038', '27602116', '30163500', '24284209', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2037833', '地心历险记', '动作', '虽然特雷弗（布兰登·费舍 Brendan Fraser 饰）是大学的地质教授，但是却经常做出挑战传统的事情。他认为，凡尔纳的小说并不是科幻，而是真是存在的。就是因为这样的对立理论，使其被传为学院里的笑话，使得他的学术名声毁于一旦。不过特雷弗却毫不在意这些，他坚信自己的理 论是正确的。为了验证自己的理论，特雷弗带着侄子肖恩（乔什·哈切森 Josh Hutcherson 饰）和当地的向导汉娜（安妮塔·布瑞姆 Anita Briem 饰）开始了在冰岛的旅行。在旅行时，三人意外发现一个奇特的洞穴，并在探询时踏破薄冰跌入了无底深渊。不过，当他们醒来时，却发现了一个神秘的地心世界，里面有着各种稀奇古怪的生物，与凡尔纳小说里面描述的场景一模一样。证据终于找到了，但是如何将证据带回地上？特雷弗三人开始了寻找出路之旅……©豆瓣', '布兰登·费舍', '埃里克·布雷维格', 6.9, 74751, 'tt0373051', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453461145.jpg', 1, 6.8, 48.9, 33.2, 10.1, '0.532536,0.053224,-0.688168,0.789188,-0.083355,-0.222942,0.790516,-0.086030,-0.739548,-0.397776,-0.033228,0.698770,-0.156406,0.066001,-0.009821,0.172814,-0.358216,-0.628187,0.067323,-0.425281,-0.356005,-0.645830,-0.556778,-0.229589,-0.053432,-0.417381,0.564283,0.192708,-0.535556,0.360765,0.124210,0.372692,0.076490,0.715770,-0.151979,-0.135456,0.033673,0.271820,-0.077098,0.193547,0.182982,0.025073,-0.277582,0.472581,-0.028631,0.522926,0.466565,-0.521565,-0.161663,0.099608,0.444781,-0.305950,-0.034436,0.213689,0.323612,-0.093080,0.139166,0.153428,0.066395,0.118233,0.230026,-0.027292,-0.816323,-0.235471,0.067274,0.288025,-0.535525,0.332984,0.014247,-0.196504,-0.229687,-0.301146,0.324579,-0.008056,0.481035,0.421608,-0.171938,-0.202425,-0.550278,0.058584,0.355002,0.073685,-0.217469,0.497868,-0.341814,-0.509027,-0.024533,-0.006166,-0.296188,0.023868,0.246378,0.060018,-0.229523,0.189563,-0.611970,-0.012273,-0.262845,-0.217263,-0.197610,-0.527308,-0.190489,-0.491621,-0.007067,-0.238178,-0.300544,-0.092933,-0.014914,-0.441078,0.590624,-0.698841,0.179974,0.650990,0.112354,-0.364443,0.750744,-0.036228,0.145469,-0.161505,-0.344578,0.270557,0.140780,0.353148,-0.087915,0.459930,0.301237,-0.416687,-0.504379,0.687771', '25932086', '35158375', '1793491', '26834930');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20378811', '宫锁沉香', '剧情', '满清康熙鼎盛之际，自十三岁入宫当宫女的兆佳沉香（周冬雨 饰）与同在乾西四所当差的好朋友琉璃（赵丽颖 饰）度过七年春秋。深宫内院，挡不住少女春心萌动。单纯无知的沉香偷偷恋上十三阿哥胤祥（陈晓 饰），情缘前定，两个身分有着巨大差异的青年男女互生好感。另一方面，琉璃偶然得到九阿哥胤禟（朱梓骁 饰）临幸，后被抛弃，一心攀援富贵的她被嫉妒与虚荣所充满，遂假托沉香之名得以许配十三阿哥。沉香深藏心中委屈，以贴身宫女身份服侍琉璃和深爱的胤祥，而在这一过程中得以和十三阿哥越走越近。在充满阴谋和权力斗争的皇宫，沉香能否与心上人再续前缘……©豆瓣', '周冬雨', '潘安子', 5.4, 90927, 'tt3046080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2068159718.jpg', 15.8, 27.3, 37.7, 11.3, 7.9, '0.006902,0.223279,-0.769243,0.548429,0.215862,-0.326748,0.731972,0.288251,-0.717726,-0.156926,0.463686,0.369428,-0.441876,0.083159,0.125070,0.036982,-0.161066,-0.445772,-0.398922,-0.377935,0.302008,-0.092713,0.127635,0.073706,-0.464513,-0.352575,0.649675,-0.055172,0.270714,0.475835,0.369398,0.379065,-0.385251,0.241819,-0.115887,0.209481,-0.143635,-0.135164,-0.322057,-0.149927,0.098746,-0.398359,-0.483162,-0.124362,-0.020008,-0.031310,0.594400,-0.800412,0.139648,-0.439357,0.279601,0.189992,-0.229457,0.302276,0.075784,-0.066618,0.189537,0.282976,0.030701,-0.081038,-0.070879,-0.054396,-0.025637,0.075812,0.376406,0.004841,-0.417397,0.343395,-0.081175,-0.175382,0.179779,-0.173429,0.164293,0.143595,-0.066885,0.113590,-0.470264,-0.063783,-0.553316,0.254145,0.412624,0.319097,0.102358,0.251378,-0.150350,-0.194658,-0.025361,-0.188208,-0.447620,-0.025107,0.444954,0.054277,0.218078,0.392153,-0.300236,-0.089782,-0.325548,0.337443,0.296156,-0.549275,0.111626,-0.029439,-0.365434,-0.738393,-0.605400,-0.136025,0.591850,-0.227259,0.574257,-0.653369,0.463037,0.205264,0.279879,-0.584063,0.565518,0.014146,0.201946,-0.285724,-0.516168,-0.044778,-0.589548,0.035848,-0.094170,0.467672,-0.504903,-0.048811,-0.737765,-0.064310', '26354526', '1308047', '1418605', '2364074');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20379462', '使命召唤', '剧情', '国际特种部队间谍吉姆（西恩·潘 Sean Penn 饰），为了他的爱人而想要退出组织，但天不从人愿，就在他完成最后一项“任务”时，为了确保自身安全与公司利益，他必须要人间蒸发匿身他处，与心爱的人从此分开。离开组织在欧洲流亡多年后，吉姆以为能够脱离危险，就此过着平静的生活；无奈人生并非他想像中单纯，在刚果被神秘人物追杀的他，被迫放下所有，展开逃亡。逃亡途中他辗转联系到昔日战友，并寻求他们的协助，却也因此发现追杀行动里暗藏着不为人知的祕密，而现在，唯有找出追杀他的幕后主使，才能给他一条生路……©豆瓣', '西恩·潘', '皮埃尔·莫瑞尔', 5.9, 5648, 'tt2515034', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267003469.jpg', 4, 20.3, 55.3, 15.3, 5.1, '0.027716,0.288041,-0.691425,0.735421,-0.147884,-0.328865,0.493016,-0.093951,-0.534412,-0.276760,0.134390,0.690228,0.520633,0.139650,0.058193,-0.023156,-0.427921,-0.776782,0.048375,-0.307413,-0.331936,-0.375133,-0.415702,-0.425144,-0.126073,-0.207977,0.807154,0.559913,-0.241161,0.308346,0.211918,0.215233,-0.594035,0.564789,-0.187024,-0.243559,0.042975,0.133803,-0.678235,0.256870,0.033150,-0.336210,-0.340569,0.465137,-0.056146,0.438307,0.567890,-0.210173,-0.128120,-0.100242,0.077179,-0.568107,0.085241,0.071998,0.209411,0.035768,0.101418,0.591243,-0.291382,0.118011,0.044784,-0.050298,-1.022868,-0.111999,0.023261,0.153658,-0.613103,0.381357,-0.189969,0.195039,0.101578,-0.417540,0.224620,0.688285,0.301215,-0.122251,-0.285187,0.079385,-0.606505,0.283995,0.913520,-0.359731,-0.119400,0.090283,0.003888,-0.366973,0.090562,-0.429168,-0.332858,-0.279622,0.519695,0.275951,-0.398687,0.141189,-0.506225,0.027534,-0.405448,-0.019578,-0.144344,-0.567792,0.201116,-0.461088,0.006448,-0.191269,-0.221590,0.357893,-0.117729,-0.447572,0.527575,-0.802227,0.260739,1.006340,0.407369,-0.820101,0.527804,0.182907,0.271158,-0.325942,0.115718,0.423581,0.180350,0.432168,0.089710,-0.127788,-0.091027,0.009589,-0.451210,0.244442', '26678784', '30163500', '25917239', '27009869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2037958', '月亮坪的秘密', '爱情', '玛利亚（达科塔·布鲁·理查兹 Dakota Blue Richards 饰）的父亲身负重债，逝世后只留给了她一本厚厚的古书《月亮坪的历史》，里面记载着月亮公主与白马的童话。十三岁的玛利亚变成了孤儿，来到月亮坪庄园投靠叔叔本杰明（艾恩·格拉法德 Ioan Gruffudd 饰）。然而入住古堡不久，玛利亚就发现怪事接踵而至：她的东西总是被到处乱放，屋里的钢琴会自动演奏，夜里甚至有一匹白马的影子在屋外晃荡……然而对于这些疑问叔叔却只字不肯透露，玛利亚只好偷偷翻阅那本被叔叔藏起来了的古书，终于得知了月亮坪上一段久远的神秘往事与仇怨，原来整个山谷已被月亮公主的诅咒笼罩百年，唯有等待一位拥有纯真心灵的解咒人出现……本片改编自英国儿童文学作家伊丽莎白·古吉的经典小说《古堡里的月亮公主》。©豆瓣', '达科塔·布鲁·理查兹', '嘉柏·丘波', 6.4, 6397, 'tt0396707', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1555980511.jpg', 2.8, 13.9, 52.3, 22.1, 8.9, '0.296507,0.038914,-0.526712,0.636077,0.205343,-0.115021,0.794707,0.161126,-0.480658,-0.415880,0.379167,0.672769,-0.260368,0.306294,0.120961,0.349748,-0.530594,-0.484758,0.121974,-0.511943,-0.160110,-0.255347,-0.337941,-0.045130,-0.118631,-0.434838,0.536612,0.335172,0.127968,0.376365,-0.015804,0.034042,-0.279497,0.179570,-0.297159,0.173221,0.051073,0.124219,0.176774,0.107551,-0.239309,-0.228075,-0.147669,-0.036113,-0.069245,-0.042334,0.662205,-0.492472,0.051395,-0.070440,0.429340,-0.036749,0.042364,0.165184,0.449425,0.155493,0.276062,0.182671,-0.135199,-0.237977,0.019442,-0.237574,-0.151085,0.104700,0.080507,0.329756,-0.535864,0.205581,-0.155919,-0.111890,0.190285,-0.277612,0.358722,-0.276077,-0.014891,0.505454,-0.071033,-0.025184,-0.735475,0.137691,-0.007572,-0.225515,-0.231825,0.221314,-0.008517,-0.216461,-0.020643,0.089389,-0.419863,0.226647,0.410367,-0.075437,-0.206263,0.060936,-0.626777,0.103518,-0.343089,-0.345467,0.101570,-0.323456,-0.392873,-0.384905,-0.148639,-0.095198,-0.055436,0.098504,0.097855,0.105976,0.716440,-0.443414,0.667808,0.161954,-0.110853,0.053274,0.504501,-0.194362,-0.104586,0.105955,0.220046,0.475203,-0.047915,0.431138,0.091587,0.255851,0.074695,0.051006,-0.535974,0.443144', '1467779', '21619567', '1302133', '1401900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20380318', '孤岛惊魂2', '悬疑', '夜色浓重，腐烂的尸体上流出来黯黑冰凉的血，死乌鸦蜿蜒覆盖了公路尽头，空气中弥漫着令人窒息的味道，诡异凄厉的惨叫声遍布小岛……这里是泰国的R61猛鬼公路，不断发生着骇人的车祸,被称作是无人生还的死亡之路。周晴和周喜（邓家佳 一人分饰）是一对年轻漂亮的孪生姐妹。妹妹周喜平静的生活近来一直被有关车祸的噩梦笼罩。与此同时，在泰国工作的姐姐突然神秘失踪。各种离奇事件接踵而至，周喜隐约感到姐姐遇到危险，她毅然辞去了工作，踏上了寻找姐姐的旅程。第一次出门的周喜只身来到姐姐在泰国的寄身之所。在这个诡异和充满恐怖色彩的小屋里，周喜遇到了一个陌生男子,这个名叫张来（陈志朋 饰）的人自称是姐姐的男朋友。担心周晴安全的周喜和张来顺着地图指引前往“猛鬼公路”寻找周晴。同行的还有张来的泰国朋友“黑龙王”。一进入“猛鬼公路”的地段，三人就遇到了各种惊险和离奇的遭遇。一辆大货车确如同鬼魅般纠缠着众人，展开了生死追逐，杀手则步步紧逼如影随形，当周喜幸运的找到周晴，自以为揭开一切谜底时，却掉入一个又一个精心设置的陷阱……', '邓家佳', '钟继昌', 2.9, 4743, 'tt4177288', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1820381513.jpg', 70.1, 18.8, 7.4, 1.3, 2.3, '0.091918,-0.254967,-0.791627,0.613370,-0.014939,-0.080214,1.089411,0.103306,-0.369912,-0.225795,0.483259,0.623132,-0.294779,0.075994,0.198705,0.124638,0.081291,-0.498852,-0.304080,-0.075201,-0.277532,-0.217821,-0.305925,-0.031665,0.133164,-0.249089,0.409645,0.503665,-0.135908,0.657841,0.216397,0.195382,-0.753679,0.524711,-0.344631,-0.018831,-0.079494,0.194770,-0.145646,-0.039030,-0.089185,-0.127799,0.150036,-0.089310,-0.134259,0.400175,0.724761,-0.141464,-0.260292,0.084347,0.425508,-0.358457,0.070441,0.026048,0.344074,-0.007537,0.138226,-0.047327,-0.276362,-0.225902,-0.140141,-0.016150,-0.530738,0.176116,0.050625,0.291339,-0.385378,0.206365,0.091498,-0.273884,0.272997,-0.353835,0.507764,0.046607,0.106172,0.417781,-0.080155,0.136828,-0.354918,0.025842,0.759397,-0.003536,-0.181005,0.320170,-0.123804,-0.331820,0.064630,0.125585,-0.299945,0.041730,0.485849,-0.001777,-0.351562,0.217895,-0.618844,0.084318,-0.005858,-0.085993,-0.164521,-0.085931,-0.428446,-0.391611,-0.003161,-0.272162,-0.041061,0.404839,-0.212630,-0.138900,0.282152,-0.546978,0.423747,0.479012,0.168794,-0.211292,0.529394,-0.177349,0.122260,0.018613,0.031046,0.289139,0.042875,0.426337,0.104495,0.494716,-0.288847,0.115618,-0.573682,0.234754', '20451118', '1296534', '3011051', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2038379', '刺杀据点', '剧情', '为了应对911之后日益猖獗的恐怖主义，美国总统亨利·阿什顿（威廉·赫特 William Hurt 饰）与西方各国以及阿拉伯国家首脑相约西班牙的萨拉曼卡，将在此缔结全新的反恐同盟。是日阳光明媚，广场人头攒动，不同社会背景之人齐齐聚集，嘈杂万分。阿什顿总统的车队在一片欢呼和反对声中到来，六个月前为保护总统而遭到枪击的资深探员托马斯·巴恩斯（丹尼斯·奎德 Dennis Quaid 饰）冲在最前方，警觉地监视着来自周遭一切可疑之人。谁知，当总统正准备发表演说时，两发子弹击中了他。广场顿时大乱，有人仓皇而逃，有人冲向主席台，有人则趁乱制造祸端。随之而来的爆炸将这美好的一日彻底毁灭。通过电视台女导播、阿什顿总统、巴恩斯以及几名和此事件有关之人的视角，血腥一日背后的真相逐步得到还原……©豆瓣', '丹尼斯·奎德', '皮特·特拉维斯', 7.3, 26789, 'tt0443274', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1729345130.jpg', 0.7, 4.5, 36.3, 46.4, 12, '0.071353,-0.099179,-0.796032,0.435994,0.217264,0.214137,0.719489,0.175343,-0.448172,-0.216675,0.332013,0.700430,-0.397014,0.014486,0.683236,-0.143501,-0.423417,-0.861522,-0.382930,-0.201927,-0.228482,-0.349186,-0.245661,-0.550522,-0.233102,-0.422437,0.653331,0.232604,-0.198389,0.400988,0.313576,0.471025,-0.325960,0.550204,0.046822,-0.217559,0.303507,-0.315380,-0.493586,0.087435,-0.193711,-0.419406,-0.214427,0.209567,-0.253969,0.300179,0.451591,-0.455768,0.239817,-0.362286,0.303446,-0.287984,0.197748,0.304021,0.428956,0.071137,0.099680,0.244939,-0.136428,-0.100792,0.029012,0.041370,-0.334169,0.187073,-0.168023,0.169241,-0.214714,0.230202,-0.277950,0.025476,0.150575,-0.019690,0.407985,0.570435,-0.034758,0.195762,-0.000674,-0.097887,-0.332902,-0.139393,0.716511,-0.003977,-0.271154,-0.003089,0.028230,-0.330192,0.120035,0.065588,-0.245837,-0.303635,0.531962,-0.052036,0.299400,0.401273,-0.619979,0.177152,-0.306491,-0.461107,-0.131510,-0.038485,-0.216337,-1.026763,-0.056043,0.106191,-0.003780,0.223958,-0.070839,0.217824,0.734569,-0.536432,0.146482,0.316280,0.318700,-0.239231,0.361827,-0.203247,0.403039,-0.260752,-0.262038,0.091213,0.421656,0.546211,-0.140380,0.117259,-0.024966,-0.201624,-0.182824,0.185266', '26788667', '11541282', '2159244', '1301447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20388198', '风暴', '动作', '香港闹市街头，一辆押款车被前科累累的重犯曹楠（胡军 饰）劫持。重案组高级督察吕明哲（刘德华 饰）率队赶往现场，与曹楠一伙发生激烈火拼。谁知危机关头，一辆突然出现的汽车搅乱战局。曹楠趁机逃走，而那辆车的车主陶成邦（林家栋 饰）被警方请入警局。陶和明哲是老同学，后来作为古惑仔混迹江湖。出事前他刚刚出狱不久。明哲以及成邦的女友燕冰（姚晨 饰）无论如何都不相信他和曹楠无关，而嚣张的曹楠更五次三番戏耍警察。为了抓住这个狡猾凶狠的对手，明哲决定安排内应潜入对方内部，无奈遭遇惨烈挫败。站在人生的十字路口，陶成邦的选择成为左右战局的关键。而随着风暴愈演愈烈，正邪双方的界限彻底模糊……©豆瓣', '刘德华', '袁锦麟', 6.5, 107358, 'tt3341072', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2160637375.jpg', 2.1, 11.5, 53.7, 26.2, 6.6, '0.365953,0.174206,-0.640751,0.171430,0.167244,-0.099090,0.666696,0.150785,-0.467931,-0.182475,0.504450,0.419420,-0.264135,-0.154071,0.343224,-0.292993,-0.189372,-0.770029,0.047829,0.055707,-0.161584,-0.438184,-0.151059,-0.136938,0.219390,0.187181,0.481513,0.207832,-0.185630,0.682766,0.516658,0.436556,-0.467700,0.483782,0.056428,0.003404,0.248648,-0.204611,-0.464152,-0.017364,-0.165993,-0.259187,0.012578,-0.097771,-0.109106,0.335751,0.596016,0.030524,-0.423693,0.088703,0.321583,-0.437212,-0.156974,0.021035,0.600428,0.085003,0.154846,0.098827,-0.101295,-0.005686,-0.174245,0.161296,-0.545013,0.425875,-0.237984,0.048661,-0.230807,0.118882,-0.103068,0.037478,0.286673,-0.272532,0.294274,0.421009,0.370182,-0.048435,-0.194137,-0.035209,-0.417259,-0.073399,0.725394,-0.052622,-0.012055,0.090340,0.195698,-0.145018,0.026192,-0.393545,-0.223373,0.102970,0.450780,-0.173585,-0.098281,0.020749,-0.201089,-0.097069,-0.410385,0.086484,-0.164416,-0.102589,-0.137575,-0.508230,-0.193544,-0.168167,-0.194639,0.254683,-0.203717,-0.045426,0.211422,-0.617440,-0.041330,0.307505,0.309345,-0.542614,0.353438,0.127493,0.041434,-0.269116,-0.092791,-0.065327,0.193649,0.523372,0.154667,0.192799,-0.172992,-0.273207,-0.105631,-0.130952', '25856453', '1301022', '1306449', '1307186');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20388223', '激战', '剧情', '过气香港拳王程辉（张家辉 饰），在拳坛没落后，沉迷赌博，负债累累，为躲避追债人，逃亡澳门。在合租房中，程辉遇到了一对母女，这名母亲（梅婷 饰），患有精神病，小女孩（李馨巧 饰）不但要上学还要照顾妈妈。程辉和小女孩很投缘，两人时常扮成小动物，排演小品，逗小女孩的妈妈开心。与此同时，富二代林思齐（彭于晏 饰）遭遇家庭变故，他的父亲（高捷 饰）生意失败，变得一无所有，整日在酒吧糜烂。为了鼓励落魄的父亲重新开始生活，林思齐报名参加了MMA。为此，他在一家拳击俱乐部报名，在这里，他认识了正在俱乐部打工的程辉，并拜他为师，学习拳击。经过几个月学习，林思齐在MMA中连胜几场，成为新拳王。随即，又遭遇了另一位高手（安志杰 饰）的挑战，林思齐负伤退赛。同时，追债人找到程辉，打斗中，不小心伤害了梅婷母女。为此，程辉深感内疚，不想再连累别人，便开始重新训练综合格斗技能，希望在MMA中赢得比赛，得到奖金偿还赌债。在MMA中，程辉以四十多岁的高龄挑战拳击，不被人看好。而他遭遇的对手，正是打败徒弟林思齐的新拳王安志杰……', '张家辉', '林超贤', 7.9, 188394, 'tt3003668', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2052557343.jpg', 0.3, 1.9, 22.9, 50.5, 24.4, '-0.105664,-0.318356,-0.436940,0.228058,-0.402814,-0.346083,0.368587,0.076730,-0.433479,-0.300217,0.456747,0.655506,-0.078585,0.391534,0.176572,-0.403203,-0.090001,-0.517295,0.088314,-0.002554,-0.197449,-0.266948,0.029868,-0.219022,-0.120092,-0.337195,0.447035,-0.051606,-0.316487,0.620520,0.206495,0.106999,-0.085594,0.320434,-0.303565,0.114345,0.098279,0.192431,-0.316004,0.207328,-0.066119,-0.198449,-0.234144,0.016100,0.314585,0.250888,0.653188,0.092359,0.008329,-0.286136,0.354617,-0.035786,-0.180084,-0.014084,0.410354,0.075009,0.533543,-0.039595,-0.101880,0.186102,-0.035487,-0.178067,-0.367329,0.379573,0.288823,0.003719,-0.586251,0.534857,-0.084583,0.139683,0.077706,0.019170,-0.037524,0.351287,0.182471,0.250014,-0.124968,0.063393,-0.390058,0.453295,0.910254,-0.280325,0.170956,0.193737,-0.031125,-0.237680,0.246953,-0.466574,-0.209381,0.098702,0.285946,-0.142410,-0.156946,0.167516,-0.264461,0.227109,-0.023244,0.009492,-0.118228,-0.207849,-0.071466,-0.651194,0.010442,-0.153063,-0.196421,0.101467,-0.116080,-0.456058,0.462196,-0.888428,0.155660,0.414330,0.502340,-0.571623,0.611067,0.149481,0.100160,-0.211960,-0.068986,0.089626,-0.045592,0.037073,0.042895,