INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20388224', '绝密跟踪', '动作', '在韩国警察系统中存在着一个特殊的部门——监视班，该班有一群貌不惊人但拥有高超分析能力和跟踪技巧的探员组成。在班长黄尚钟（薛景求 饰）的指挥下，监视班一次次抓获狡猾罪犯，将他们绳之于法。某日，一腔热血的警员河允珠（韩孝珠 饰）以优异的成绩通过黄班长极为苛刻的测试，成为监视班的一员，代号“花猪”。虽然初出茅庐略显青涩，但花猪很快凭借其缜密的分析能力赢得班长的信任。与此同时，以詹姆士（郑雨盛 饰）为首的一组犯罪分子正策划对证券交易所的秘密行动。虽然已经获得罪犯的蛛丝马迹，但詹姆士极其狡猾，拥有超高的反侦查能力。一系列高端的猫鼠游戏在闹市中央相继展开……©豆瓣', '薛景求', '曹义锡‍', 7.7, 91250, 'tt2969656', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2199597040.jpg', 0.3, 1.8, 28.1, 52, 17.8, '0.301158,-0.019865,-0.435282,0.950835,-0.396994,0.169920,0.352617,-0.034220,-0.494120,-0.346252,0.406243,0.328065,0.068766,-0.020900,0.151551,-0.551904,-0.132007,-0.533977,-0.402436,-0.144113,-0.362558,-0.778996,-0.461735,-0.145904,-0.027814,-0.391605,0.675634,-0.044447,-0.479452,0.520402,0.362492,0.182280,-0.234712,0.111044,-0.088662,-0.430699,0.417068,-0.186644,-0.040137,0.208528,-0.156755,-0.072816,0.005039,-0.200158,-0.033230,0.361650,0.905558,-0.423714,-0.336406,-0.176778,0.377341,-0.300528,-0.137380,-0.136692,0.836545,0.327998,0.037325,-0.022726,-0.087378,0.254734,-0.212537,-0.065708,-1.234830,-0.228889,0.459688,0.064154,-0.345706,0.098765,0.054859,0.242922,0.251159,-0.189670,-0.291124,0.096487,0.246375,0.393686,0.183739,0.139178,-0.449996,-0.006254,0.143305,-0.111517,-0.418440,-0.012257,-0.277219,-0.768507,0.062921,-0.351436,-0.118273,-0.157748,0.221143,-0.043883,0.048883,-0.196027,-0.563963,0.136030,-0.020938,0.121700,-0.234641,-0.591856,0.144121,-0.951922,-0.062375,-0.424398,-0.220751,0.378263,0.067326,-0.411498,0.835142,-1.074603,-0.132483,0.487266,0.040039,-0.455201,0.460032,-0.025585,0.087141,-0.445838,-0.516990,-0.048924,0.551023,0.200780,-0.031351,0.543373,-0.166236,-0.652741,-0.322434,0.133223', '1420088', '1793491', '6038071', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20388242', '怒放之青春再见', '剧情', '马路（潘粤明 饰）是某交友网站中层白领，工作的压力和家庭生活的平庸无聊让他丧失了对生活的热情。一天，他平静的生活被20年前初恋女友李爱突然造访的电话打破。马路和李爱数次相约见面却因为种种原因未能如愿以偿，但他青春的情感和记忆已经被打开，当年为了李爱（温心 饰），年轻的他（吕聿来 饰）和郑天亮（张晓晨 饰）、钱大宝（杜海涛 饰）、侯亮（王啸坤 饰）四人组了一个名叫“怒放”的乐队，各种往事历历在目，还有那首当年写给李爱却一直没有唱出来的歌是藏在他内心深处的遗憾。回忆的过程中马路渐渐找回了青春的激情和梦想，他和老友郑天亮（秦昊 饰）、钱大宝（王东方 饰）、侯亮（韩秋池 饰）重组乐队，在大海边唱出当年未唱完的歌曲，几个中年人完成了他们生命中又一次的怒放……©豆瓣', '潘粤明', '卢庚戌', 6.5, 9986, 'tt6412268', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2164134706.jpg', 5.7, 13.7, 41.9, 26.1, 12.5, '0.021876,0.297561,-0.578739,0.672150,-0.136705,-0.376455,1.072183,0.016392,-0.633021,-0.338394,-0.213756,0.561235,-0.199344,0.599008,0.157726,-0.090728,-0.216815,-0.778693,0.238682,0.241611,-0.114428,-0.234823,-0.115761,-0.103578,-0.241793,-0.003129,0.430291,0.272614,-0.064476,0.759237,0.289688,0.119294,0.038115,0.580209,-0.192427,0.262992,-0.056802,0.271380,-0.109437,-0.213063,0.107633,-0.506502,-0.225544,0.130057,0.152163,0.340199,0.680446,0.171616,-0.100758,0.161770,0.348465,-0.152862,-0.147966,0.005772,0.211749,0.175665,0.304082,0.116175,-0.278639,-0.105008,-0.226167,-0.183441,-0.669183,0.047693,0.007475,0.080292,-0.497513,0.692398,-0.112699,0.078962,0.197817,-0.257484,0.302871,0.082972,0.362101,0.472791,-0.271732,-0.017321,-0.564655,0.660378,0.664248,-0.017598,-0.099713,0.583449,-0.252816,-0.452020,-0.384047,0.043057,-0.502811,0.107107,0.406243,0.064909,-0.154232,-0.104082,-0.766925,-0.134513,0.050516,-0.192408,0.009913,-0.462727,-0.252637,-0.466190,-0.282500,-0.656534,-0.346574,0.195657,-0.002236,-0.313135,0.812620,-0.749908,0.187021,0.311198,0.086271,-0.447058,0.734623,0.188236,0.046755,-0.094546,0.266403,0.369215,-0.352888,0.247767,0.270053,0.395425,-0.289312,0.030972,-0.521348,0.631878', '3111650', '24839498', '1304989', '2131640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20388680', '午餐盒', '剧情', '沉默而孤独的中年男人赛扬·费尔南德斯（伊尔凡·可汗 Irfan Khan 饰）妻子去世多年，工作也快到了退休之时。形单影只的赛扬上班下班吃饭回家，寂寞的时候就在阳台上抽烟，不发出一句响声；伊拉（妮拉特·考尔 Nimrat Kaur 饰），一个单纯简单的家庭主妇。她把所有的感情都投入到了家庭中，把照顾女儿伺候丈夫视为自己的责任。她只希望她的丈夫能多看她一眼，多关注她一些。两个生活在孟买完全不可能有交集的男女，居然因为一次午餐错拿而有了交集，引起了共鸣。他们开始用传统而含蓄的书信进行往来，向对方倾诉自己的孤独和寂寞。在城市的两个角落里，一个阴差阳错的美丽错误，两个彼此陌生的男女，一段触不可及的感情缓缓开始。©豆瓣', '伊尔凡·可汗', '赖舒·彼查', 8.1, 12443, 'tt2350496', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171482927.jpg', 0.2, 1, 19, 54.7, 25.1, '0.584085,0.023277,-0.990901,0.595079,-0.450590,-0.501321,1.110468,0.256578,-0.183550,-0.076945,0.015396,0.827985,0.018046,0.492132,0.024103,0.154795,-0.189707,-0.864448,0.265298,-0.155683,-0.316849,-0.441759,-0.072795,-0.368321,-0.153931,-0.244123,0.276926,-0.058048,-0.063895,0.228628,0.171238,0.015279,-0.075705,0.674237,-0.237869,-0.121057,0.164682,0.110230,-0.145737,0.153435,-0.054815,-0.138713,-0.201332,0.267378,-0.088995,0.360022,0.740025,-0.171535,-0.367172,0.023063,0.511946,-0.048753,-0.044654,0.183683,0.162808,-0.082783,0.250424,0.130202,-0.202245,0.063549,-0.105355,0.112468,-0.552421,-0.023090,-0.252667,0.332463,-0.667917,0.725720,-0.119365,-0.504232,0.009765,-0.468910,0.241777,0.325010,0.028654,0.477845,-0.428883,-0.010986,-0.330627,0.139173,0.712170,-0.010054,-0.337659,0.607357,-0.151502,-0.253393,0.028989,-0.129178,-0.687936,-0.238471,0.381563,-0.166377,-0.076031,0.121317,-0.473238,0.345090,-0.053175,-0.334312,-0.025139,-0.547691,-0.029389,-0.396762,-0.129631,-0.627463,-0.690874,0.134439,0.263452,-0.243752,0.829982,-0.512172,0.277112,0.650968,0.287327,-0.599105,0.676041,0.193105,0.134300,-0.067184,0.212342,0.231279,-0.066557,0.119399,0.300415,0.360258,-0.013761,0.375540,-0.407577,0.433619', '1783772', '3111650', '1292217', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20389706', '小小的家', '剧情', '青年荒井健史（妻夫木聪 饰）此前一直照顾姨婆多喜（倍赏千恵子 饰）的生活起居，多喜年轻时曾在东京帮佣，如今在健史的纠缠下，她提笔写下了陈年的悲喜往事。那要回溯到昭和初期，年轻的多喜（黑木华 饰）离开山形老家，几经辗转进入平井家担任女佣。平井家在东京郊区盖了一栋红色屋顶的小房子，男主人（片冈孝太郎 饰）是玩具公司常务，女主人时子（松隆子 饰）雍容美丽。多喜对时子充满敬仰，她更全心全意为平井家服务。某年春节，玩具公司新来的设计人员板仓正治（吉冈秀隆 饰）走进平井家门。相近的趣味和爱好让他和时子愈加投机。与此同时，战况日渐激烈，有情男女藏着彼此的秘密，随波逐流……本片根据中岛京子第143回直木赏同名获奖作品改编。©豆瓣', '松隆子', '山田洋次', 8.2, 17112, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2176712029.jpg', 0.3, 1, 16.7, 55.2, 26.9, '-0.095231,-0.044738,-0.380498,0.336370,0.079746,-0.129568,0.487471,0.374990,-0.537573,-0.517285,0.146552,0.536246,-0.140647,0.308612,0.191669,0.054289,-0.196093,-0.369704,-0.080203,-0.082803,-0.009654,-0.264828,-0.150407,-0.116535,-0.204413,-0.119799,0.404702,0.103673,0.032672,0.238149,0.371654,0.287221,-0.539531,0.085144,-0.128924,0.039363,0.039971,0.128043,-0.283205,-0.175685,-0.449714,-0.279260,-0.249706,-0.383754,0.282270,0.086864,0.769563,-0.025617,-0.285432,-0.151877,0.343762,0.255683,-0.125154,0.065857,0.281270,0.178649,0.163420,0.273296,-0.417734,0.029199,-0.092600,-0.259098,-0.163437,-0.066510,0.185149,0.102334,-0.480881,0.486012,-0.307181,-0.176750,0.292128,-0.182176,0.084970,0.189279,0.011155,0.244370,-0.000029,0.146164,-0.069804,0.391972,0.316087,0.247384,0.198190,0.309083,-0.267430,-0.175092,-0.040604,-0.128551,-0.265518,-0.172241,0.067528,-0.031392,0.198838,-0.032142,-0.350533,-0.157803,0.037526,-0.006011,0.436334,-0.160832,-0.167620,-0.622249,0.033222,-0.649705,-0.204952,0.023429,0.171765,-0.097645,0.684124,-0.603241,0.103193,0.256674,0.296083,-0.244328,0.416888,-0.015995,0.110239,-0.147863,-0.255916,0.172430,-0.081248,0.121354,0.020925,0.356100,-0.469493,-0.049527,-0.372672,0.238223', '3811356', '5403927', '6814906', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20390013', '纯净脆弱的心', '剧情', '15岁那年，青梅竹马的濑户环奈（长泽雅美 饰）和春田一惠（高良健吾 饰）双双升入同一所高中的同一班级。新学期第一天，春田和蓄意挑衅的真山稔邦（中村苍 饰）大打出手，而这一风波也促成了环奈、春田、真山以及川口朝美（波瑠 饰）四个人的友情。此后的岁月里，他们结伴出行，玩耍畅谈。而随着交往的加深，阿真对环奈的情感有了新的变化，环奈和春田则暧昧不定，相互试探而又退缩。在焰火大会的晚上，突如其来的交通事故为四人的友情画上了句号。八年后，进入职场的环奈偶然结识了某出版社的员工赤泽禄（冈田将生 饰）。看似自负毒舌且阳光开朗的赤泽，内心也有着一段长久无法摆脱的痛苦记忆。两个心在滴血的年轻人，结识在匆忙喧嚣的都市中……本片根据育江绫同名漫画改编，人物姓名以漫画版为准。©豆瓣', '长泽雅美', '新城毅彦', 6.5, 6583, 'tt2546434', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2018580340.jpg', 1.7, 12.6, 51.2, 26, 8.6, '0.439768,-0.059721,-0.580825,0.689250,0.341121,-0.277204,0.632773,0.235932,-0.365010,-0.237343,0.151602,0.747090,-0.400360,0.492048,0.432358,-0.228877,-0.172361,-0.755994,-0.074617,-0.171291,-0.167387,-0.424341,-0.091863,0.078516,-0.199429,-0.309993,0.773344,0.199250,-0.046933,0.985083,0.442783,0.305345,-0.385289,0.210833,-0.112431,-0.000146,-0.092124,0.413314,-0.304132,-0.038384,-0.230650,-0.317387,-0.089061,0.017769,-0.016718,0.565392,0.934703,-0.200228,-0.049205,-0.019783,0.511975,0.046507,-0.246260,0.022347,0.372884,0.068311,0.182616,0.378907,-0.330625,0.139987,-0.157707,-0.043525,-0.549411,0.005541,0.070637,0.230033,-0.339737,0.775477,0.265045,-0.221786,0.211503,0.042437,0.028573,0.486042,0.394442,0.205856,-0.244994,0.034920,-0.117699,0.173145,0.707826,0.091929,-0.338251,0.629889,-0.304763,-0.338465,-0.175871,-0.049656,-0.221471,-0.050658,0.142291,0.002156,0.037070,0.253116,-0.787905,-0.006618,0.069305,0.147651,0.161894,-0.442196,-0.137733,-0.758190,-0.313079,-0.634152,-0.325901,0.089134,0.164584,-0.239278,0.918346,-0.976672,-0.135978,0.316191,0.068575,-0.242876,0.613162,0.204923,-0.007315,-0.204679,-0.016163,0.193626,-0.004228,0.243585,-0.000785,0.517344,-0.189770,0.093257,-0.431738,0.242281', '3811356', '26365262', '1826173', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20390185', '3096天', '剧情', '根据1998年震惊世界的真实事件改编。奥地利女孩娜塔莎卡姆普什在被绑架和囚禁八年多之后终于逃出生天，之后娜塔莎出版了自传《3096》讲述了这段可怕的过去。1998年年仅10岁的奥地利女孩娜塔莎遭人绑架沦为性奴，自此一直遭关押达8年。绑架者最初4年始终将她关在屋中，后来逐步放松警惕，但大多数时依旧与世隔绝，在她心中从未放弃过追求自由的希望。', '安东尼娅·坎贝尔-休斯', '雪莉·霍曼', 6.8, 9102, 'tt1667355', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1880934665.jpg', 0.9, 6.6, 51.7, 30.6, 10.1, '-0.121939,-0.071907,-0.694847,0.080381,0.125836,-0.244815,0.589280,-0.633446,-0.953651,-0.610347,-0.170221,0.345674,-0.551887,0.491764,0.578895,0.187570,-0.290987,-0.714070,-0.189107,-0.569368,-0.261649,-0.271396,-0.382788,-0.330997,-0.168949,-0.577151,0.748829,0.178066,0.081429,0.558285,-0.122481,0.167724,-0.006565,0.452050,0.037614,0.243051,0.225415,-0.127126,-0.210308,0.027574,-0.286922,-0.641947,-0.242989,-0.151577,0.015238,0.318255,0.654619,-0.387946,-0.357327,-0.039922,0.446679,-0.193428,-0.679603,-0.022885,0.455158,0.142051,0.109321,0.711655,-0.351011,-0.276670,-0.347979,-0.251941,-0.354505,0.024084,0.129601,-0.333530,-0.331180,0.542867,-0.102924,0.538333,-0.094579,-0.263654,0.040603,0.383447,0.413927,0.497501,-0.115276,0.065054,-0.240945,0.284482,0.899819,-0.209952,-0.399252,0.204265,-0.091352,-0.161593,-0.179213,-0.457807,-0.292484,0.402272,-0.004782,0.549004,-0.610696,0.593963,-0.199533,-0.262824,-0.526513,-0.168511,0.520167,-0.419956,-0.441634,-0.208044,-0.465613,-0.282302,-0.289095,0.008162,-0.280764,-0.413054,0.646466,-0.578322,0.813022,0.618873,0.355641,-0.430399,0.652501,-0.135460,-0.025127,0.130213,0.153391,0.862296,0.111977,0.330918,0.186642,-0.002534,-0.303295,-0.148724,-0.077027,0.295356', '22637441', '1308086', '1303184', '1308806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20395646', '越来越好之村晚', '喜剧', '春节临近，村里打算办一场晚会来让村民们欢聚一堂，欢庆新年的到来。这个小山村人才辈出的小山村在外打工的人们听说了村里要办一场热热闹闹的村晚，怀着合家团圆的心情纷纷从外地赶了回来。被骗财的作家耿直（佟大为 饰）意外的被乡亲们认为成了文学奖的获得者，风光的被邀请回乡负责村晚的 文案策划，获奖的误会越传越大，可面对望子成龙的父亲，耿直更是无从澄清。在城里打工的包工头德发（郭富城 饰）偶遇了因为自己的赌瘾而离婚的前妻淑芬（徐静蕾 饰），花样百出挽救婚姻后，二人一起回乡负责春晚的舞蹈节目。在城里梦想成为一名大厨的春树（王宝强 饰）在酒店意外结识了周大厨父女，憨厚耿直的性格更是获取了美女周一楠（王珞丹 饰）的青睐，在经历了周大厨一番考验后成功带着一楠回乡负责村晚的晚宴。而村晚的主办人的资格更是在死对头向成（黄觉 饰）和山喜（张译 饰）之间展开激烈角逐，一场热闹的村晚即将在明星荟萃的光辉下拉开序幕…', '郭富城', '张一白', 4.3, 23149, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1850784258.jpg', 31.1, 34.8, 25.4, 5.5, 3.3, '0.197090,-0.044758,-0.727063,0.355648,-0.005347,-0.157029,0.361601,0.326614,-0.396731,-0.172507,0.123179,0.577159,-0.576062,0.482802,0.500751,-0.441900,-0.010959,-0.398440,-0.131453,0.112736,-0.090617,-0.234630,0.149389,-0.145946,-0.125313,-0.000944,0.211359,0.328758,0.064322,0.743945,0.716900,0.069883,-0.071084,0.272296,-0.253887,-0.031607,0.131434,0.295927,-0.470576,0.071466,-0.076206,-0.341886,-0.301527,0.060667,0.317271,0.250209,0.688845,0.071860,-0.113815,0.012602,0.522926,-0.250485,0.126181,0.182846,0.470239,0.184163,0.152101,0.147121,-0.069847,0.030350,0.111142,-0.426642,-0.556143,0.348393,0.382189,-0.009486,-0.737520,0.600215,0.236710,-0.135680,-0.098799,-0.215592,0.476026,0.528273,0.046225,0.444621,0.130973,0.170389,-0.392561,0.631630,0.841591,-0.071739,0.013064,0.264743,-0.066999,-0.328353,0.270261,-0.153793,-0.553550,0.120531,0.354983,-0.333291,-0.057986,0.102316,-0.543546,-0.184380,-0.065861,-0.233556,0.145659,-0.241690,-0.060884,-0.858068,-0.010105,-0.279744,-0.153474,0.154299,0.160847,-0.116089,0.662360,-0.782622,0.166499,0.310056,0.116862,-0.640488,0.600513,0.181469,0.283795,-0.097976,-0.078421,-0.306698,-0.057409,0.282690,0.188602,0.322827,-0.230309,-0.414312,-0.265941,0.350522', '26687241', 