INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2039711', '反恐疑云', '剧情', '埃及裔美国人安瓦•艾尔•伊布拉西米（奥玛尔•梅特瓦利 饰）大约二十年前，从埃及移民到了美国，与漂亮的美国姑娘伊莎贝拉•菲尔兹（莉丝•维瑟斯彭 饰）成了家，夫妻恩爱生活美满，育有一子，伊莎贝拉肚子里的第二胎也日渐成型。某日，安瓦•艾尔•伊布拉西米从南非出差回来，在华盛顿机场被神秘的黑衣人带走，原因是中央情报局认为身为化学品工程师的安瓦•艾尔•伊布拉西米是恐怖分子，想从他口中撬出有用的情报。倒霉的安瓦被“引渡”至埃及的开罗，交由驻扎在当地的中情局探员道格拉斯•弗里曼（杰克•吉伦哈尔 饰）和老奸巨猾的当地探员审讯。另一方面，身怀六甲的伊莎贝拉，坚信丈夫是无辜的，四下奔走，努力寻找丈夫的下落。期间，她虽然幸运地获得旧情人（彼得•萨斯加德 饰）的帮助，但终究不足以国家强势机构对抗，一筹莫展。与此同时，刚刚入行不久的特工道格拉斯•弗里曼，在目睹了CIA同事们对安瓦进行的非人道审讯时，也面临着良心的拷问。安瓦是不是恐怖分子？伊莎贝拉能否和丈夫团圆？中情局新手道格拉斯•弗里曼，究竟在这场暗战中发挥了怎样的作用？对这一切疑问的解答，必将引向对“引渡”政策的重新审视。', '杰克·吉伦哈尔', '加文·胡德', 7.1, 7577, 'tt0804522', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1444525924.jpg', 0.8, 4.9, 42.6, 42.8, 8.9, '0.131004,0.023343,-0.727622,0.378371,-0.047468,-0.236037,0.410740,0.143860,-0.494427,-0.098194,0.073278,0.570878,-0.083713,0.040883,0.333964,0.298836,-0.719758,-0.632752,-0.013177,-0.355925,-0.366642,-0.730194,-0.288665,-0.281348,-0.005577,-0.486947,0.219442,0.089648,0.006444,0.161512,0.324282,0.706794,-0.034532,0.206556,-0.064735,-0.024297,0.439340,-0.270029,-0.397572,0.305783,0.167215,-0.256517,-0.315258,0.041638,0.287121,0.497328,0.457338,-0.237427,0.254529,-0.093928,0.173970,-0.367666,0.104923,0.173572,0.482574,-0.098107,-0.143615,0.153820,-0.159553,-0.081967,0.090492,-0.176314,-0.718904,-0.030701,0.031886,0.115552,-0.543184,0.193008,-0.240325,0.026405,0.157601,-0.072700,0.243090,0.536940,-0.053695,0.317634,0.095751,0.093036,-0.431281,-0.047379,0.402397,-0.030790,-0.336762,0.001392,-0.231415,-0.550166,-0.049813,-0.084507,-0.349726,-0.237234,0.359033,-0.124835,0.060345,0.395270,-0.340325,-0.072057,-0.575260,-0.144398,0.055444,-0.124788,-0.067593,-0.659151,-0.068822,-0.356864,-0.232134,0.000107,0.068020,0.064532,0.717880,-0.601117,0.158585,0.548174,0.449075,-0.248357,0.374644,0.050166,0.281120,-0.317913,-0.263735,0.3