INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20397453', '美味毒妇', '剧情', '一个穷途末路的老太太走上了贩毒道路，穿梭于一群年轻男人之间，斗智斗勇、轻松诙谐地化解了重重险境。这部另类犯罪片从头至尾充满了令人捧腹的法式幽默。女主角伯纳蒂特·拉方特自1950年代出道，是特吕弗和夏布罗尔两大法国电影新浪潮干将的处女作女主角，从影五十五年来已参演180多部影视剧，曾两度荣获法国电影凯撒奖，与之配戏的是西班牙国宝级女演员、阿莫多瓦御用明星卡门·毛拉，两位女星擦出笑果无数。', '贝纳德特·拉封', '热罗姆·恩里科', 7.8, 11236, 'tt2215395', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1834997536.jpg', 0.2, 1.5, 25.4, 53.7, 19.3, '0.068624,-0.167123,-0.354367,0.684148,0.144175,-0.269665,0.914828,-0.128361,-0.257201,0.026064,0.338933,0.963629,-0.638975,-0.094701,0.511199,-0.211462,-0.021752,-0.628992,-0.337611,-0.011416,0.124595,-0.081395,-0.751444,0.298082,-0.603970,-0.340910,0.501584,-0.139159,-0.321107,0.244952,0.801737,0.356034,-0.251338,-0.015744,-0.106661,0.287519,0.322446,-0.136180,-0.461814,0.176736,-0.168416,-0.260625,-0.512389,-0.137075,-0.266207,0.047277,0.295979,-0.107867,0.238841,0.080211,0.650604,-0.387957,-0.125375,-0.266213,0.265399,0.030934,0.466312,0.096097,0.163181,-0.019816,0.016687,-0.155480,-0.586527,0.146423,0.028990,0.214612,-0.594739,0.187098,0.093641,-0.200563,-0.008489,-0.216027,0.027053,-0.330161,0.257438,0.208709,0.231095,0.031828,-0.218925,0.786271,0.277069,-0.017424,-0.330585,0.202533,-0.030047,-0.422940,-0.004908,-0.357644,-0.557795,0.121915,0.575704,-0.639957,0.317523,0.423827,-0.551519,0.092232,-0.198082,-0.051812,0.006037,-0.050471,0.053720,-0.931224,-0.378380,-0.351023,0.048897,-0.192641,0.284287,-0.220019,0.514957,-0.439019,-0.004597,0.283464,-0.064591,-0.037952,0.624467,0.214051,0.012367,-0.041669,-0.128173,0.150654,-0.100209,-0.196258,0.216173,0.634641,-0.187312,-0.209758,-0.187779,0.244989', '1306762', '3837666', '26611806', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20398974', '唇唇欲动', '喜剧', '一个是因童年阴影患上了厌食症的孤僻狂，一个是因乐天性格造就的Super吃货，这两个性格迥异的90后女孩，生活在看似平行的两条人生轨迹上。终于有一天，两人不期而遇……冷馨（李媛 饰），90后新锐摄影师，性格孤僻，并患有厌食症。因事业不顺而困扰到极致的冷馨却遇到了天生没心没肺又是吃货的艾伊（陈一娜 饰），同是90后的艾伊不仅没有傲人的家世，且父母离异后各自成家，但这些没有让她变得消极悲观，跟姥姥一起生活的日子，造就了她幸福的童年。一开始格格不入的两个人，在相处中慢慢的彼此感染，摩擦碰撞中两人用各自拿手的光圈与美食合作了一次，却意外收获了彼此的春天。一段啼笑皆非又感人泪下的关于青春、友谊、梦想的奇幻旅程开始了……©豆瓣', '华少', '苏伦', 4.1, 5734, 'tt3296588', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2052777231.jpg', 47.2, 23.4, 14.5, 7.4, 7.4, '0.462859,-0.083919,-0.636063,0.626500,-0.121873,-0.499404,1.066686,0.272490,-0.672926,-0.014206,0.054780,0.672543,-0.345698,0.235116,0.282543,-0.154948,-0.026785,-0.731154,0.013543,-0.156959,-0.320777,-0.233728,-0.161208,-0.044404,-0.224828,-0.329790,0.580580,-0.037549,-0.096611,0.712155,0.170800,0.046479,-0.099424,0.501644,-0.367007,0.062928,-0.083151,0.332280,-0.186461,-0.088924,0.156554,-0.229536,-0.056679,0.325099,-0.261306,0.512184,0.823026,-0.208179,-0.247987,-0.219070,0.416489,0.167786,-0.381032,0.070079,0.377307,0.131540,0.450422,0.118971,-0.207330,-0.144943,-0.050228,0.060511,-0.747637,-0.018013,0.172264,0.140535,-0.347158,0.617527,0.264686,-0.510213,-0.049700,-0.320249,0.120453,0.444237,0.554491,0.511239,-0.072722,0.048858,-0.115570,0.200510,0.988913,0.040434,-0.499314,0.800152,-0.702001,-0.354572,-0.204033,-0.311628,-0.581891,-0.146966,0.230192,0.111850,-0.260519,0.432807,-0.797342,0.472834,-0.110110,0.089832,-0.091292,-0.423290,-0.111502,-0.345779,-0.252947,-0.927840,-0.521783,0.111209,-0.030770,-0.244714,0.842492,-0.884802,0.146299,0.497746,0.010008,-0.440379,0.571784,0.258216,0.104351,-0.109651,0.222223,0.286655,-0.311775,-0.041540,0.098829,0.639437,-0.125644,0.179244,-0.434464,0.730703', '24756472', '1307561', '21442760', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2039903', '劝导', '剧情', '根据简·奥斯丁同名小说《劝导》改编而成。沃尔特家的二小姐安妮（Sally Hawkins饰）温柔娴静，知书达理，是一位德才兼备的好姑娘，可年近28的她至今还待字闺中——8年前，安妮和情郎温特沃斯（Rupert Penry-Jones饰）订下婚约，却最终因长辈拉塞尔夫人（Alice Krige饰）的“劝导”而选择和对方分手。虽然安妮旋即萌生悔意，但受了伤的温特沃斯早已远走他乡，杳无音讯。这段往事给安妮心口划上一道永难愈合的口子，此后，她的心扉再未向他人打开。8年后，温特沃斯衣锦还乡，一举一动都透出绅士魅力，完全不复昔日的穷酸样，已成为富家女竞相追逐的对象，他对安妮的态度冷淡无比；安妮表面虽然镇定自若，在点滴接触中却不自禁地加深了对温特沃斯的无限爱慕之情，深知昔情难追的她也因此在内心深处备受煎熬……©豆瓣', '莎莉·霍金斯', '亚德里安·谢尔高德', 7.7, 12436, 'tt0844330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2327245073.jpg', 0.2, 2.6, 28.5, 47.1, 21.5, '0.182527,0.133696,-0.633441,0.590784,-0.144509,-0.503709,0.836439,0.047320,-0.524024,-0.053477,0.137383,0.554115,-0.423903,0.347742,-0.006786,0.077353,0.056906,-0.640867,-0.009920,-0.252604,0.045919,-0.249013,-0.268275,-0.012769,-0.177724,-0.238881,0.597136,0.061702,0.023775,0.740284,0.049600,0.246178,0.012067,0.547046,-0.120353,0.022737,-0.293659,0.146646,-0.232326,-0.059579,0.357311,-0.277483,-0.208367,0.201619,-0.142488,0.686196,0.666220,-0.185028,0.009161,0.029211,0.362483,-0.016506,0.172538,0.324179,0.191270,0.096787,0.224287,0.102391,-0.173086,-0.173089,-0.074821,-0.014962,-0.406867,-0.069076,0.194910,0.183858,-0.638443,0.602418,-0.398118,0.034433,-0.113854,-0.325212,-0.155754,-0.035664,0.049089,0.440128,-0.230530,0.223602,-0.291204,0.106615,0.320149,0.410340,-0.447921,0.478824,-0.306478,-0.233780,0.149681,-0.272935,-0.591846,-0.191193,0.171693,0.298871,0.137430,0.473782,-0.479665,0.063243,-0.405614,0.335890,0.167838,-0.604777,-0.090957,-0.330032,-0.496904,-0.772012,-0.496492,-0.134644,0.164784,-0.140910,0.669319,-0.846460,0.221889,0.202668,0.219975,-0.492951,0.609156,0.439420,-0.115558,-0.085064,-0.162921,0.437090,-0.261079,0.038075,0.245691,0.368876,-0.034458,-0.042256,-0.397704,0.571207', '1304989', '2131640', '3111650', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20399278', '华颐：吞噬怪物的孩子', '动作', '1998年，以硕泰（金允石 饰）为首的五人团伙“白魅”绑架了某位高权重之人的幼子。行动失败后，他们并未撕票，而是将男孩收作养子，并有意识地培养起成为杀手接班人。转眼将近二十年时光过去，得名华颐（吕珍九 饰）的男孩已经长大，成为清秀帅气的高中生。硕泰遵照上线的指示犯下一连串恶性罪案，他有意让华颐踏入此道，但男孩自幼便仿佛具有能看见怪物的能力，以至于在关键时刻总功亏一篑。在某次行动时，华颐意外获悉自己的身世之谜，可在硕泰不得不开枪射向和他有血缘关系的男人。一意孤行的硕泰，越来越不满的上线组织，始终追查白魅的警官，华颐的命运被卷入漩涡之中……©豆瓣', '金允石', '张俊焕', 7.3, 21264, 'tt2972362', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2115435924.jpg', 0.6, 4.2, 39.4, 42.2, 13.5, '0.073382,0.203084,-0.585815,0.319622,-0.189197,-0.148378,0.590335,0.091858,-0.594538,-0.246303,0.257880,0.569943,-0.082602,0.050736,0.425279,-0.046520,-0.043290,-0.699515,-0.004250,-0.207209,-0.117114,-0.510233,-0.058438,-0.168702,-0.000772,-0.316784,0.786427,0.192686,-0.224589,0.332482,0.277283,0.195146,-0.203228,0.398478,-0.334590,0.039354,0.030696,-0.112045,-0.169818,0.218957,-0.077813,-0.472621,-0.138047,0.070301,-0.304994,0.381613,0.734497,-0.405363,-0.355851,-0.371685,0.337646,-0.301374,-0.272827,-0.008024,0.658956,0.191112,0.145080,0.412089,0.030417,0.039749,-0.040106,-0.079240,-0.673000,0.049322,0.212424,0.196070,-0.622188,0.269309,0.007297,0.037026,-0.086870,-0.302316,-0.074578,0.170060,0.123907,0.042480,-0.358798,0.219263,-0.489537,0.006348,0.519969,0.092413,-0.286916,0.155438,0.079319,-0.499954,-0.148179,-0.343249,-0.281861,0.128006,0.393049,0.198668,-0.302542,0.288487,-0.263001,-0.099717,-0.317619,0.155346,-0.114086,-0.427587,-0.169621,-0.272209,0.019522,-0.259037,-0.398184,0.181804,-0.038783,-0.307185,0.567145,-0.803937,0.277089,0.453263,0.267633,-0.531670,0.456001,0.129834,0.127150,-0.302148,-0.294167,0.344896,0.121837,0.145107,0.052582,0.166337,-0.220402,-0.223654,-0.229973,0.146720', '1301022', '30345227', '35030151', '1293265');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20415220', '夏日之王', '剧情', '乔（尼克·罗宾逊 Nick Robinson 饰）的母亲在他很小的时候就离开了他，现如今，他和父亲弗兰克（尼克·奥弗曼 Nick Offerman 饰）过着相依为命的日子。弗兰克是一个非常独断专行的男人，控制欲极强的他无时不刻的想要控制乔生活里的方方面面。和乔境遇相同的还有帕特里克（加布里埃尔·巴索 Gabriel Basso 饰），他也因为家人们的过度关注而感到窒息。一天夜里，乔和好友比阿基奥（莫伊塞斯·阿里亚斯 Moises Arias 饰）意外发现了一处人迹罕至的森林，和帕特里克一起，感受到了大自然召唤的孩子们决定离家出走，在这片森林里建立他们的乌托邦，这段牢不可破的友谊在一位名叫凯利（艾琳·莫里亚蒂 Erin Moriarty 饰）的女生介入之后，发生了微妙的变化。©豆瓣', '加布里埃尔·巴索', '乔丹·沃格特-罗伯茨', 7.4, 18129, 'tt2179116', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1926553481.jpg', 0.5, 4.2, 37.3, 42.7, 15.2, '0.322517,-0.274750,-0.933223,0.784974,-0.089346,-0.274751,1.098479,0.201233,-0.606556,-0.491725,-0.157559,0.739736,-0.408764,0.545703,0.454361,-0.010850,-0.271402,-0.582405,0.028144,-0.166991,-0.452406,-0.633864,-0.371041,-0.401491,-0.133516,-0.181468,0.426752,0.139559,-0.337320,0.442958,0.033033,0.273092,0.088553,0.814428,-0.134475,0.139154,0.010850,0.024860,-0.056434,-0.119835,0.390681,-0.096489,-0.210232,0.386365,0.361514,0.363885,0.658419,-0.545284,-0.016062,0.044801,0.267658,-0.127513,0.129722,0.110135,0.341591,-0.215964,-0.047385,0.031066,-0.328413,-0.001092,0.230138,-0.238887,-0.480455,0.097078,0.057745,0.016466,-0.698288,0.483010,0.117873,-0.075115,0.136814,-0.331870,0.253469,0.486305,0.104494,0.360976,-0.150762,-0.226801,-0.655005,-0.047601,0.680263,-0.190605,-0.415688,0.254782,-0.455432,-0.638382,-0.484849,-0.050779,-0.670722,-0.233469,0.303518,0.038555,-0.171393,0.329234,-0.546320,-0.018818,-0.097409,-0.094482,-0.269367,-0.496485,-0.067791,-0.603154,-0.227780,-0.652295,-0.175742,0.224223,-0.307677,-0.288812,0.570255,-0.769120,0.295666,0.451762,0.257771,-0.424622,0.787944,-0.028534,0.305984,-0.214908,-0.080766,0.517932,0.098759,0.059925,0.409258,0.466348,0.003786,0.290506,-0.158069,0.691252', '1292211', '4275444', '1309172', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042178', '自虐之诗', '剧情', '从小就生活在不幸中的幸江（中谷美纪 饰），结婚后依然过着苦情女的生活，丈夫（阿部宽 饰）不仅没有工作、嗜酒豪赌成性，还经常对她粗鲁相待，但幸江始终死心塌地地坚守在丈夫身边，不管看不下去的邻居劝她离婚，也不管有钱店主的求爱，在她看来，只要和丈夫在一起就是人生最大的幸福。直到有一天，刑满出狱的父亲（西田敏行 是）出现在幸江面前，生活开始发生变化。©豆瓣', '中谷美纪', '堤幸彦', 8, 6581, 'tt0997159', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p884878401.jpg', 0.3, 2.5, 22.9, 47.7, 26.6, '-0.169905,-0.167757,-0.751091,0.453206,-0.274207,-0.412872,0.812966,0.178356,-0.331790,-0.135646,0.318433,0.710255,0.071743,0.472568,0.225067,0.058952,-0.164130,-0.725338,-0.079567,0.071632,-0.208118,-0.480656,0.047613,0.028487,-0.446802,-0.240898,0.594400,-0.096802,0.246546,0.353539,0.457830,0.003059,0.005179,0.403758,-0.465021,0.058190,-0.022190,0.533735,-0.633529,0.102703,0.163768,-0.137324,-0.149974,-0.027333,0.371055,0.004995,0.561980,-0.233629,-0.343649,0.222381,0.352779,-0.082523,-0.225052,0.287466,0.396020,-0.140674,0.327603,0.246625,-0.400967,0.000217,0.066356,0.160081,-0.467940,-0.135045,0.089583,0.079997,-0.616366,0.627990,0.232311,-0.262514,0.067819,-0.436145,0.114012,0.427533,0.228078,0.413020,-0.457273,0.365219,-0.454851,0.232665,0.838530,0.133883,-0.135725,0.471060,-0.214734,-0.091677,0.082098,-0.339071,-0.865119,-0.149841,-0.240205,-0.040008,-0.606126,0.229485,-0.278415,0.213916,0.091917,0.099504,0.332833,-0.374323,-0.206971,-0.353373,-0.109979,-0.728768,-0.492748,0.410125,-0.082686,-0.622249,0.666312,-1.099464,0.450878,0.460629,0.486077,-0.674138,0.885208,0.702330,0.066612,-0.234824,0.047078,0.551963,-0.081363,0.101560,0.085070,0.110862,0.052121,0.012529,-0.187384,0.625448', '1302384', '1292720', '21766698', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042181', '律政英雄', '剧情', '检察官久力生公平（木村拓哉 饰）六年后回到东京地方监察厅城西部，继续由事务官雨宫舞（松隆子 饰）担任助手。六年时间并没有隔断他们的感情，在斗嘴中舞试探着久利生的心意，久利生感觉到却故意调皮地置之不理。芝山检察官（阿部宽 饰）正对一桩故意伤害人的案件提起起诉，犯罪嫌疑人对罪状也供认不讳。芝山由于正在为自己争取女儿抚养权的官司弄得焦头烂额，这件官司只得转交久利生处理。久利生和舞去了案发现场重演经过时遇见了一个神情庄重的中年人。在初审法庭上发现他竟是犯罪嫌疑人的辩护律师——在业界首屈一指的蒲生一臣，而犯罪嫌疑人也一改之前的口供，否认罪状。原来花岗练三郎议员正在被控贿赂，而他坚称当时正在牙医诊所，目击证人正是一名保安，这名保安就是久利生的犯罪嫌疑人。为了帮花岗脱罪，所以这名犯罪嫌疑人必须身在牙医诊所而不是案发现场。对于高官来说，让花岗入罪是为民除害。但是对于久利生来说，没有什么比杀人之后逃窜更恶劣。尽管艰难重重，他们还是坚定地踏上了寻找证据控告入罪之路。', '木村拓哉', '铃木雅之', 8.2, 13219, 'tt0997157', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1176364620.jpg', 0.2, 1.5, 18.7, 44.9, 34.6, '0.155275,-0.241773,-0.369396,0.308232,-0.318046,-0.197925,0.614521,0.182145,-0.533078,-0.324712,0.284193,0.414016,0.022157,0.137828,0.237092,-0.069909,-0.366615,-0.664196,0.099066,-0.252445,-0.231855,-0.753979,0.196026,-0.172438,-0.061710,-0.015326,0.530987,0.050784,-0.211385,0.198405,0.370658,0.334656,-0.139937,0.262296,0.038106,-0.244007,0.101390,0.012000,-0.424917,0.111385,0.257465,-0.426440,-0.281366,0.160264,0.128287,0.534720,0.373791,-0.125829,-0.344817,-0.088863,0.457201,-0.468317,0.010073,0.151542,0.451114,0.033715,0.137907,0.486474,-0.226881,-0.127594,0.170615,-0.151372,-0.699341,-0.004795,0.084488,0.314066,-0.360515,0.276712,-0.328736,0.060601,0.084349,-0.034074,0.247986,0.278906,0.069885,0.324337,-0.339681,-0.013030,-0.374633,0.054270,0.421107,0.147125,0.071569,0.073910,-0.047452,-0.551798,0.215769,-0.170439,-0.052699,0.100089,0.138477,0.005193,-0.182301,0.021616,-0.054055,-0.171291,-0.315902,-0.096732,-0.097839,-0.383245,-0.080653,-0.333118,0.015097,-0.108385,-0.324073,0.124629,0.216703,-0.267504,0.181310,-0.532000,-0.040217,0.634153,0.260798,-0.714726,0.469120,0.213384,0.161548,-0.284741,-0.256134,0.117320,0.295701,0.594490,0.089498,0.036298,-0.036231,-0.504149,-0.139241,0.106688', '26389331', '25862560', '1296217', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042186', '鸭子和野鸭子的投币式自动存放柜', '剧情', '“如果有被车压的狗，一定要去救；如果有逃走的女人，找到天涯海角也一定要找到；如果有想要的书，就算袭击书店也要得到。”从老家来到仙台求学的大学生椎名（濱田岳 饰），在公寓的门口遇见了一个自称名叫河崎（瑛太 饰）的神秘男子。河崎称隔壁住着一个不丹人，不丹人搞不清鸭子和野鸭的区别。为了帮助他，河崎决定去书店打劫一本《广辞苑》，并邀请椎名参加。懵懂的椎名稀里糊涂随着河崎行动了，不过河崎却错拿了一本《广辞林》。随着和河崎交往的日渐加深，椎名逐渐了解了他真实的面目，以及两年前发生的一段令人难以忘怀的故事……©豆瓣', '滨田岳', '中村义洋', 8, 12743, 'tt0997138', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p543147441.jpg', 0.3, 1.7, 21.7, 51.1, 25.2, '0.315180,-0.050674,-0.464771,0.631058,-0.139750,-0.401447,0.599898,0.062765,-0.252774,-0.326894,-0.014729,0.688282,0.024229,0.112206,0.404754,0.106079,-0.078351,-0.549031,0.140286,-0.582977,-0.409729,-0.431466,-0.300353,-0.064967,0.071540,-0.100369,0.677313,0.248571,-0.216200,0.464439,0.414579,0.150184,-0.226278,0.344469,-0.222780,-0.125014,-0.259023,0.359748,-0.094363,0.284563,0.127973,-0.335125,-0.102253,0.071780,0.158482,0.235650,0.357971,-0.171856,-0.362770,0.174142,0.223514,-0.037863,-0.209940,0.163957,0.236082,-0.027518,0.151772,0.276592,-0.281949,0.124797,-0.038444,-0.001445,-0.716467,0.161070,0.150605,0.160722,-0.578827,0.261724,0.094824,-0.234179,0.331759,-0.362429,0.111415,0.421802,0.204107,0.376062,-0.222357,0.004239,-0.607279,0.115015,0.606643,-0.047086,0.125204,0.277867,0.076709,-0.287844,0.040214,-0.104485,-0.330186,0.395054,0.016331,0.036813,-0.687596,-0.349388,-0.513443,-0.126272,0.033479,-0.155788,0.112445,-0.355997,0.021918,-0.526541,0.014375,-0.091942,-0.065458,0.082030,0.150824,-0.321725,0.812825,-0.866829,0.306251,0.828544,0.481728,-0.391914,0.666994,0.067365,-0.166558,-0.064121,-0.099576,0.044874,0.332424,0.428438,0.029804,0.324367,0.087353,-0.521415,-0.290071,0.367600', '1793491', '1296698', '1308499', '3755531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042193', '恋爱部屋', '剧情', '青木由里（新垣结衣 Yui Aragaki 饰）是一名艺术学校的美术生，因为姐姐结婚而不得不离开原来的住所搬到公寓独自居住。初来乍到的由里听从母亲的建议带着礼物拜访公寓每一位新邻居，对住在楼上的奥优高司（松田龙平 Ryûhei Matsuda 饰）印象深刻。后来由里来到林业部门实习发现，原来自己要跟随的教授竟然就是住在自己楼上的高司。在和高司研究松树发光的课题期间，由里渐渐喜欢上了这个沉默寡言的男生。因为将送给姐姐的礼物遗忘在老居所，由里又认识了新搬来的住户建筑师君太暑子（菊地凛子 Rinko Kikuchi 饰）。受到暑子欣然微笑的椅子的启发，还设计出了自己即将参赛的让两个人更亲近的椅子。由里本以为这两段美好的友谊是新生活的开始，然而一块剪掉的窗帘让她意外的知道了原来高司和暑子曾是一对恋人，而自己现在的住所正是暑子以前住过的地方。就这样由里陷入了一段纠结的三角关系中…', '新垣结衣', '大九明子', 6.3, 6502, 'tt0991219', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1010639463.jpg', 2.8, 16.1, 54, 19.9, 7.3, '0.499245,-0.163256,-0.630217,0.688160,-0.304472,-0.359668,0.740613,0.373682,-0.511680,-0.468454,0.192202,0.813324,-0.014450,0.647893,0.317047,0.286830,-0.179281,-0.529276,-0.292820,-0.282215,-0.546488,-0.519154,-0.237113,-0.024832,-0.001749,-0.270918,0.450429,-0.047153,-0.137493,0.634839,0.392766,0.215768,-0.128489,0.391841,-0.376396,0.040583,0.030419,0.197029,-0.173290,0.002025,-0.086920,-0.237688,0.000820,0.165054,0.131943,0.299499,0.694784,-0.046467,-0.262311,0.104341,0.340372,-0.010319,-0.076799,0.237775,0.538546,0.223007,0.209018,0.174214,-0.403720,0.210250,0.151065,-0.259745,-0.658061,0.194648,0.121463,0.029336,-0.824915,0.613028,0.066401,-0.314164,0.200577,-0.489116,0.386845,0.377793,0.123062,0.525489,-0.279647,-0.002002,-0.257519,-0.007212,0.583085,-0.328282,0.184098,0.462342,-0.241410,-0.251332,0.179629,-0.023327,-0.263788,-0.009498,-0.105781,0.074311,-0.135852,-0.253021,-0.763179,-0.012510,-0.111185,-0.198953,0.242450,-0.519747,-0.065104,-0.496479,-0.197887,-0.348810,-0.255292,0.118834,-0.147280,-0.226998,0.686793,-0.931671,0.326883,0.412140,0.414573,-0.548820,0.806982,0.115527,0.062925,-0.161102,-0.021239,-0.036145,0.037863,0.497413,0.097146,0.559206,-0.056313,-0.265426,-0.650967,0.449655', '1292219', 