INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042219', '天然子结构', '剧情', '右田素夜（夏帆 饰）在木村长大，那里简朴的生活环境十分舒适。素夜就读的中学是一所中小学的混合学校，虽然只有6个学生，年龄各异的孩子们相处融洽。从东京来的转校生大泽广海（冈田将生 饰）打破了村里孩子们的平静。面对这位同龄人，素夜表现热情，可是广海却十分自我，难以相处。夏天的时候，同学们都会一起到海边游泳。通向海边有一条捷径，可是那条捷径一直被村里人认为是灵异的地方，可是大泽却坚持走捷径。在那里，意外发生了，素夜陷入了困境，幸好大泽出手相助。素夜后来知道大泽是以前邻居的孙子，对大泽产生了好感。两人的交往却找来了素夜父亲的反对，素夜竟然发现了自己父亲与大泽母亲之间的过去。两人沉浸在初恋的甜蜜中，一起度过了重要的节日，可是毕业的一天还是到来了。©豆瓣', '夏帆', '山下敦弘', 7.6, 18924, 'tt0997184', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p635063912.jpg', 0.4, 2.7, 31.2, 45.6, 20.2, '0.418768,-0.173765,-0.736453,0.484252,-0.042474,-0.308476,0.577784,0.062009,-0.779806,-0.254705,0.012332,0.418674,-0.184910,0.522248,0.142245,-0.113370,-0.221237,-0.454397,-0.051676,-0.111659,-0.352816,-0.267620,-0.217201,0.085750,-0.262916,-0.112959,0.502276,0.246733,-0.059508,0.583114,0.115640,0.159633,-0.193179,0.635405,-0.314397,-0.223263,0.007517,0.301211,-0.163511,0.030708,-0.122500,-0.124686,-0.335961,-0.010174,0.512570,0.354119,0.632225,0.188218,-0.441252,0.121029,0.302320,-0.080017,-0.246830,0.168287,0.612753,-0.071497,0.196406,0.172489,-0.011232,-0.088961,-0.178730,-0.206015,-0.281966,0.193543,0.185808,0.171263,-0.502193,0.400364,0.396631,-0.425066,0.004337,-0.415949,0.247015,0.258119,0.190371,0.462340,-0.214465,0.071487,-0.498800,-0.151937,1.086454,-0.224436,-0.283995,0.202376,-0.499504,-0.480332,-0.008929,-0.180226,-0.437554,0.175753,0.020718,0.011729,-0.411356,0.163908,-0.422442,0.031147,-0.017096,-0.074692,0.016671,-0.416556,-0.211015,-0.455665,0.016464,-0.533460,-0.478668,0.132045,-0.014317,-0.357143,0.832894,-0.800673,0.143712,0.331409,0.346614,-0.397523,0.868277,0.208272,0.031183,-0.126467,0.057049,0.221588,-0.171953,0.102316,0.029040,0.404544,-0.178547,0.005288,-0.479702,0.463597', '25721544', '1870682', '35030151', '1305084');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042226', '导演万岁！', '剧情', '著名导演，暴力宗师北野武（北野武 饰）突然厌倦以往拍摄的黑帮电影，宣布再也不拍黑帮片，涉猎其他的题材。北野武开始尝试各种影片。他拍摄了小津安二郎风格的亲情片、催人泪下的爱情片、反映50年代社会风貌的怀旧片、恐怖片、忍者片、科幻片等十多部电影，都因为不同的原因而失败，他的导演生涯因此遭遇到瓶颈，需要反思。©豆瓣', '北野武', '北野武', 7.1, 6354, 'tt0996435', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2224693641.jpg', 1.2, 7.8, 40.7, 37.5, 12.9, '0.264799,-0.270825,-0.566784,0.427672,0.802646,0.062978,0.582500,0.192426,-0.206010,-0.439816,0.600649,0.589436,-0.451415,-0.061327,0.206710,-0.420544,-0.441795,-0.619372,0.102383,0.207228,-0.062007,0.159716,-0.397205,-0.238392,-0.199222,-0.183162,1.105453,0.129406,-0.886693,0.081179,0.177865,0.016104,0.227439,-0.019999,0.304854,0.258737,0.115573,-0.030132,-0.588840,0.077421,0.193702,-0.178797,-0.240481,-0.017319,-0.107243,0.439402,0.713590,0.041539,-0.180293,0.171803,0.891885,-0.000591,-0.428503,0.042582,0.154561,0.128540,0.347309,0.140479,0.488563,0.358021,-0.381645,-0.146912,-0.723848,-0.004313,0.230824,0.497055,-0.153826,0.317973,-0.053157,-0.094440,-0.296850,-0.123795,0.065526,-0.058670,0.946962,0.367028,0.097222,-0.047123,0.022839,0.984344,0.460020,0.020366,-0.358758,0.993182,-0.129264,-0.564273,-0.605849,-0.626257,-0.518736,0.342074,0.127001,-0.305608,-0.462907,0.096943,-0.751648,0.141381,0.505053,-0.312282,0.016028,0.068054,0.117796,-1.224560,-0.301133,-0.395711,-0.048649,-0.563901,0.404906,-0.329123,0.805408,-0.395418,0.125085,0.322264,-0.002917,-0.495306,0.743237,0.076714,-0.598552,-0.158796,0.079661,0.372583,-0.343197,0.082917,-0.099978,0.208121,0.182830,-0.582807,0.063325,0.312850', '26275494', '30373716', '1322847', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042230', '欢迎来到隔离病房', '剧情', '28岁的佐仓明日香（内田有纪 饰）职业是一名自由撰稿人。某天她醒来后发现自己躺在了一间白色屋子的床上。原来是一所精神病院的隔离病房，而这里只收女病人。明日香感觉自己失去了记忆，她完全不知道自己是如何来到这里的。截稿日期将至了，她却没有院方及男友作家铁雄（宫藤官九郎 饰）的同意不得出院。她只好在这个地方继续生活。她认识了患有厌食症的美纪（苍井优 饰），得了暴食症的西野（大竹忍 饰），虽然刚开始觉得她们都是怪怪的，但明日香还是跟她们成为了朋友。铁雄派人探望明日香，一时受不了刺激的明日香麻疹发作。即使这样，明日香还是成功对付了医院护士一往的冷酷无情。就在一切仿佛都将要好起来之际，美纪的一个天大秘密，唤醒了明日香的记忆……©豆瓣', '内田有纪', '松尾铃木', 7.2, 5817, 'tt0997174', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p635444060.jpg', 1.2, 4.7, 38.6, 42, 13.4, '0.324437,0.040781,-0.462250,0.223033,-0.319002,-0.296486,0.642879,0.099908,-0.583342,-0.438037,0.210499,0.643966,-0.175412,0.594664,0.092478,0.375747,-0.205080,-0.565901,0.034770,-0.067357,-0.491372,-0.297376,0.094990,-0.093243,-0.130384,-0.285924,0.583339,0.065732,-0.034006,0.211542,0.132473,0.233154,0.212232,0.527030,-0.074409,0.195217,0.152309,-0.023289,0.199544,0.273779,0.225320,-0.456378,-0.191222,0.467806,0.047832,0.411657,0.464482,-0.096234,-0.380416,0.046535,0.385338,-0.211272,-0.311000,0.259494,0.340880,-0.274252,0.106534,-0.086357,-0.312842,-0.006533,0.154704,0.338313,-0.412590,0.031017,0.090471,0.262314,-0.405844,0.345970,-0.298618,-0.078343,0.032949,-0.351110,0.103917,0.282649,0.032206,0.326219,-0.379976,-0.033330,-0.563341,0.212709,0.629480,-0.037025,-0.301648,0.607139,-0.237100,-0.597317,-0.150176,-0.033924,-0.322561,-0.105473,-0.040623,0.181911,-0.394929,-0.253485,-0.210191,-0.099433,-0.101262,-0.176231,-0.180112,-0.230436,-0.050020,-0.179343,-0.063942,-0.335753,-0.365906,0.089479,-0.014709,-0.123500,0.665768,-0.839827,0.188104,0.599908,0.246850,-0.315748,0.521346,0.104301,-0.007245,-0.045439,0.288090,0.156235,-0.158077,0.375983,0.425294,0.509656,0.038132,-0.004656,-0.572222,0.451025', '1937946', '1309080', '35030151', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042235', '等待，只为与你相遇', '爱情', '智史（山田孝之饰）是Trash水生植物店的店长，生意清淡，几乎难以为继。某日，一个女孩子找上门来，不由分说便要求做店员，还就地住了下来。智史后来才知道女孩竟是超级模特森川铃音（長澤まさみ饰），迟钝的智史对铃音的出现和行为目的完全是一头雾水。“女孩子的行为都是有特定的含义的”，在铃音的反复暗示下，智史终于想起13年前的故事，他、花梨、佑司是形影不离的好伙伴，后来却失去了联系。时光荏苒，看到长大了的花梨成为铃音与自己重逢，智史又惊又喜。有一天，佑司（塚本高史饰）的消息也传来，他受伤住在医院里，智史和花梨一起去看望佑司后，花梨却对智史说自己要留下陪伴佑司不走了。独自返回的智史心情低落，郁郁寡欢，这时父亲（小日向文世饰）前来看望，告诉了他一个惊人的秘密……©豆瓣', '长泽雅美', '平川雄一朗', 7.1, 12954, 'tt0997178', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p765843879.jpg', 0.9, 6.3, 43.2, 36.2, 13.4, '0.242350,-0.035432,-0.619878,0.493933,-0.152802,-0.186789,0.757433,0.178032,-0.451487,-0.222086,0.060690,0.667309,-0.230502,0.647904,0.328552,0.334208,-0.294113,-0.699027,0.016224,-0.215068,-0.045519,-0.533889,-0.037383,-0.153200,-0.091407,-0.194177,0.241263,-0.006482,-0.047465,0.541817,0.256624,0.096780,-0.089458,0.843254,-0.064923,0.261529,0.038445,0.005053,0.215850,0.018172,0.231826,-0.304500,-0.260034,0.137721,0.370367,0.343377,0.393192,-0.159390,-0.169719,0.299493,0.194091,-0.059267,0.107362,0.147485,0.376088,0.068329,0.282533,0.209788,-0.537705,0.096477,-0.068346,0.148655,-0.493555,0.284154,0.081427,-0.004834,-0.714448,0.233975,-0.079009,-0.144638,0.197352,-0.528339,0.370978,0.372159,0.274593,0.521510,-0.199430,0.269752,-0.240533,-0.105674,0.738672,0.010033,-0.121452,0.374664,-0.075838,-0.510208,-0.181600,-0.094518,-0.054932,-0.039870,0.138813,0.070073,-0.252995,-0.228955,-0.335722,-0.109300,-0.114456,-0.366240,0.110994,-0.373812,-0.291334,-0.305976,0.002192,-0.421290,-0.444380,0.166622,0.058104,-0.242690,0.694607,-0.877577,-0.005743,0.427777,0.390901,-0.553724,0.643271,-0.042717,-0.183553,-0.050067,0.105053,0.164012,0.049782,0.417143,0.378367,0.210231,0.098949,0.047882,-0.371018,0.219606', '1308755', '2990737', '1301022', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042279', '51号星球', '喜剧', '在一颗名为51号星球的行星上，居住着一群通体绿色的高智慧生物，他们的文明高度发达，生活安宁幸福。不过他们也有自己的恐慌，那就是远在几百光年之外的地球人，他们生怕会遭到地球人的入侵和杀害。雷（Justin Long 音）是一个热衷星球研究的青年，他和地球上的小青年没什么两样，做实习报告、跟朋友聊天、追女朋友、找工作。这一日，一艘来自地球的宇航飞船降临51号星球，且刚好落在雷的院子里。宇航员查理·T·巴克（“巨石”强森 Dwayne Johnson 音）在当地引起一系列恐慌，自己也受到不小的惊吓。由于长久以来的宣传，51号星球的居民生怕地球人会对自己造成伤害。万般无奈之下，巴克船长找到雷，希望他能帮助自己回到正被当地居民围观的飞船，启程返回地球。而另一方面，当地防卫军也针对“入侵”的地球人展开了行动。巴克船长最终能否回到故乡呢？©豆瓣', '道恩·强森', 'Jorge Blanco', 6.8, 10467, 'tt0762125', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p588233622.jpg', 0.7, 6.4, 52.7, 32.4, 7.7, '0.155921,-0.019944,-1.030754,0.609309,-0.163950,0.302189,0.635224,0.061474,-0.435217,0.063676,0.248584,0.816780,0.081460,0.222092,0.246317,0.177487,-0.288631,-0.263968,0.120538,-0.308751,-0.566050,-0.350059,-0.391765,-0.603849,0.028881,-0.608400,0.518033,0.248572,-0.312139,0.322600,-0.218943,0.238344,-0.144977,0.665882,-0.326237,0.074870,-0.021725,-0.039927,-0.067224,0.118136,-0.330548,0.063814,0.146403,0.261506,0.234639,0.365073,0.826621,-0.299260,-0.150964,-0.284472,0.149754,-0.470720,0.172594,-0.247100,0.594120,-0.173346,-0.112883,0.073197,-0.033133,0.172033,0.249098,0.009155,-0.556366,0.092063,-0.081237,0.142804,-0.555822,0.549239,-0.125544,-0.136290,-0.292441,-0.018055,0.554710,0.585683,0.032536,0.398821,-0.139878,0.087773,-0.508122,0.064624,0.804270,0.091726,-0.455266,0.023924,-0.310908,-0.371055,-0.334102,-0.179183,-0.445435,-0.216990,0.352537,-0.082426,-0.324848,0.129352,-0.753899,0.312466,-0.234779,-0.471245,0.092203,-0.505693,-0.221680,-0.912531,0.314526,-0.309887,-0.183993,0.304740,0.220882,-0.042153,1.005775,-0.671760,0.126375,0.670393,0.747024,-0.647785,0.713203,-0.022781,-0.003376,-0.289933,0.064823,0.254802,0.096576,0.614541,-0.084211,0.042444,0.062297,-0.069868,-0.301084,0.311009', '34461680', '1293019', '1307897', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042474', '新局长到来之前', '喜剧', '在中国的官场，自古就有溜须拍马的风气存在。话又说回来，如果当官的不受用这些，那么马屁精们又有什么市场呢？你看这就发生了一个类似的故事。某局老局长休养，新局长即将上任。在这个关口，总务科牛科长担负起迎接新局长的重任。虽说一朝天子一朝臣，不过表现出众的话自然不难取得新领导的欢心。牛科长深谙此道，他调动全科力量为新局长打造宽敞舒适的办公室，他事必躬亲，认真仔细，不放过每一个细节。也许你认为他是一个对工作认真负责的人，可是与此相对的是，他对单身职工宿舍漏雨等事宜则能拖就拖。未过多久，张局长走马上任，谁知阴差阳错被牛科长当成了张老板，由此上演了一出了“官场现形记”……©豆瓣', '李景波', '吕班', 8.5, 6966, 'tt0334735', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2550273354.jpg', 0.2, 0.8, 12, 49.5, 37.5, '0.059972,-0.074741,-0.581518,0.234660,-0.466029,-0.190286,0.382216,0.303789,-0.427890,-0.202751,0.194570,0.503180,-0.100832,0.000476,-0.080540,0.007336,-0.234295,-0.412892,0.134362,0.003801,-0.187037,-0.395400,-0.187376,-0.143445,0.069086,0.100890,0.089526,-0.101243,-0.217313,0.123347,0.184682,0.087448,0.438213,0.525701,-0.366805,0.029244,0.238521,0.323213,-0.062572,-0.087247,0.353518,-0.062415,-0.233994,-0.195675,0.307990,0.324895,0.078445,0.123761,-0.564221,0.208792,0.457937,-0.369902,0.056135,0.090187,0.542355,0.109118,0.022837,0.231692,-0.360183,-0.031721,-0.179603,-0.172041,-0.962394,-0.139004,-0.130517,0.162087,-0.413567,0.281825,0.146707,-0.243973,-0.109355,-0.250211,0.269020,0.325510,0.117992,0.436805,0.174479,0.330993,-0.427401,0.229482,0.561018,-0.011181,-0.506261,0.281028,0.218543,-0.471637,0.297854,-0.178960,-0.354895,-0.074684,-0.025348,-0.335059,0.100200,-0.334078,-0.212458,0.221825,-0.235066,-0.023994,0.050677,-0.354139,-0.202533,-0.058768,-0.136826,-0.326046,-0.194811,0.004438,0.427462,-0.168524,0.812217,-0.665424,-0.079367,0.196273,0.083827,-0.812682,0.840432,0.412143,0.197309,-0.317783,0.017824,-0.521489,0.103086,0.677262,0.283696,0.524140,0.200978,-0.566052,-0.098675,0.283273', '24284209', '26678784', '30163500', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20425292', '私人战争', '剧情', '杰米·多南加盟裴淳华、塔伦·艾格顿主演传记新片《私人战争》，马修·海涅曼(《贩毒之地》《幽灵城》)执导，阿拉什·阿梅尔(《摩纳哥王妃》)操刀剧本，将基于《名利场》撰写的科尔文生平事迹文章进行创作，查理兹·塞隆担任制片人。裴淳华饰演战地女记者玛丽·科尔文，艾格顿饰演一名有军事背景的记者，跟随科尔文前往战区报道。11月开拍。科尔文曾奔赴科索沃、车臣、 东帝汶、中东、塞拉利昂、津巴布韦等战争前线，在斯里兰卡内战期间严重受伤失去了一只眼睛，还报道了“阿拉伯之春”反政府运动，2012年在叙利亚战争爆发时于胡姆斯遭火箭袭击身亡。', '裴淳华', '马修·海涅曼', 7.1, 8416, 'tt2368254', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2532482728.jpg', 1.5, 5.7, 41.6, 39.3, 12, '0.004626,-0.208015,-0.535763,0.264498,0.682597,0.025345,0.146604,0.174964,-0.164211,-0.288599,0.198151,0.543347,-0.465319,-0.473823,0.514185,-0.154525,-0.622244,-0.557024,-0.123816,0.195409,-0.057745,-0.364607,-0.148430,-0.273744,-0.012365,-0.612551,0.532366,0.102481,-0.360347,0.281065,0.168551,0.595276,0.085743,0.169939,0.548505,0.034789,0.353991,-0.563034,-0.181041,0.419659,-0.031116,-0.123512,-0.363255,-0.114107,0.454083,0.201795,0.611823,-0.032910,0.463917,-0.323983,0.452725,-0.462664,0.317849,-0.133704,0.429364,0.133161,-0.081535,0.263992,0.215759,-0.065902,-0.266071,-0.589085,-0.209411,-0.003732,-0.158964,0.407335,-0.217995,0.197730,-0.671664,0.319783,-0.061870,-0.147996,0.074049,0.720967,0.373922,0.112008,0.400985,0.337250,-0.304639,0.416498,0.363692,-0.007496,-0.475865,-0.267025,0.063498,-0.469737,-0.058988,0.048227,-0.289541,0.215337,0.449131,-0.552616,0.098307,0.505808,-0.326492,-0.130924,-0.491684,-0.378040,0.129442,0.189742,0.032570,-1.316133,-0.201866,0.432737,0.394080,-0.336481,0.211450,0.218641,0.543197,-0.212848,0.402387,0.481226,0.360698,-0.412104,0.401121,0.265708,-0.020537,-0.126604,0.096748,0.672663,0.291758,0.089117,-0.014697,0.012133,-0.072014,-0.483491,0.174845,-0.006827', '34961898', '26335580', '3003137', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042593', '初雪', '爱情', '陶艺师的儿子金明（李俊基 饰）作为交换学生从韩国汉城到日本京都上学，认识了喜欢画画的同学七重（宫崎葵 饰），他们学习彼此的语言，慢慢相恋。金明的奶奶重病，他回家探望。当他再回到日本的时候，七重悄无声息地搬家了，彻底离开了他的世界，他只能带着伤痛回到韩国。两年之后，金明又遇上了七重，她是否还记得他们初雪的约定？她又如何解释当年的不辞而别？©豆瓣', '李准基', '韩相熙', 6.4, 19282, 'tt0997155', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p520613283.jpg', 2.3, 13, 53.8, 23.3, 7.6, '0.208726,0.248583,-0.568096,0.430970,-0.358803,-0.631756,0.032532,0.269268,-0.354294,-0.232411,0.177976,0.635851,-0.056005,0.654346,0.063540,0.034607,-0.382415,-0.632130,0.375882,-0.503578,-0.275087,-0.277689,-0.098958,0.133496,0.017710,-0.156025,0.263111,0.089096,-0.076842,0.065598,0.179356,0.039637,-0.007498,0.554322,-0.273144,0.273078,-0.051079,0.286112,-0.230030,0.247087,0.130946,-0.242296,-0.173448,-0.064472,0.098333,0.332775,0.711452,0.263240,0.135491,-0.022071,0.320129,-0.187845,-0.184084,0.221387,0.236982,0.047658,0.112310,0.132731,-0.118713,0.123109,-0.393526,0.076896,-0.191768,0.344887,0.024101,0.132773,-0.572842,0.470457,-0.212698,0.044627,0.229621,-0.604220,-0.091841,0.712834,-0.065370,0.524832,-0.311036,0.059226,-0.358585,0.393004,0.749500,-0.120587,0.005868,0.291578,0.286694,-0.422164,0.101539,-0.189432,-0.147375,0.037405,0.233629,-0.105300,-0.338687,0.086524,-0.447855,-0.301322,-0.103944,-0.234241,0.328861,-0.270894,0.315236,-0.561644,0.224855,-0.608405,-0.574637,-0.199256,0.180729,-0.137839,0.884700,-0.812352,0.169710,0.545728,0.717903,-0.577432,0.620005,-0.056797,-0.102109,-0.293352,0.274361,0.262966,-0.100344,0.618325,0.346482,0.541007,0.002645,0.163003,-0.502911,0.395488', '1292219', '1308609', '4739952', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042617', '13骇人游戏', '悬疑', '本片改编自漫画《The 13th Quiz Show》。阿奇面临人生低谷：被公司开除、被女友抛、面对重大负债压力巨大。此时接到了一通神秘电话，邀请他参加一个名为“13”的游戏。这是一场神秘、竞争激烈的游戏，只要参赛者能完成十三个任务，就可获得一亿元的巨额奖金。但这些任务将逐步挑战人类各方面的极限，从爱情、宗教甚至於道德价值观。每一个任务都有必须遵守的规则，如果失败了，参赛者就会消失，游戏进行时，只有三个限制：一、不能任意放弃；二、禁止去探查游戏的起源；三、不能告诉别人自己在玩这个游戏。阿奇轻易地完成了前两个任务，并决定继续下去。然而，他却不知道接下来的任务充满著恶心、血腥、而且毫无人性。游戏即将开始，为了奖金，他愿意付出多少代价？©豆瓣', '克里萨达·苏克索', '楚克·萨克瑞科', 6.8, 22794, 'tt0883995', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p887015328.jpg', 1.8, 8.6, 46.2, 34.1, 9.4, '0.030592,0.603347,-0.665741,0.486264,-0.228674,-0.158286,0.276013,-0.031172,-0.100650,-0.108849,0.057991,0.773130,-0.043631,-0.201860,0.054478,-0.331773,-0.106028,-0.507124,-0.245295,-0.056043,-0.503153,-0.568662,0.279121,-0.345612,-0.181796,0.016549,0.776907,0.230823,-0.456796,0.072559,0.447013,0.184372,-0.154532,0.409764,0.116286,-0.321726,0.433479,0.139751,-0.319546,0.399411,-0.024100,0.248387,-0.050978,0.322185,0.025098,0.271946,0.503274,-0.290727,-0.547892,-0.075066,0.597836,-0.327483,-0.418176,0.014653,0.049157,0.118982,0.238330,0.326282,-0.022746,0.266927,0.025969,-0.353914,-1.333183,-0.355961,-0.114598,0.058419,-0.167391,0.302648,-0.159100,0.085173,-0.063449,-0.073333,-0.217486,0.564998,0.722633,0.072966,-0.455028,-0.064116,-0.483257,0.270836,0.809350,-0.380701,-0.331517,0.446234,-0.050094,-0.536438,-0.210603,-0.452098,-0.127651,0.307707,0.201312,0.340356,-0.372142,0.174479,-0.559178,0.188461,-0.278625,-0.602434,-0.028578,-0.568866,-0.052291,-0.418302,-0.064643,0.180388,-0.588524,0.386222,0.401119,-0.482411,0.788854,-0.812785,0.260521,0.876661,0.312252,-0.819165,0.466676,0.518212,0.286921,-0.269909,0.172448,-0.047775,-0.042970,0.511188,0.103362,0.121216,0.280582,-0.202743,-0.190278,0.695248', '26678784', '30163500', '6844861', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20426975', '谁说我们不会爱', '爱情', '苏小暖（颖儿 饰）的志向是当一名职业漫画家，为了这个梦想大学毕业后的她选择留在北京当一名“蚁族”。因为出版社黄编辑突然辞职，小暖的漫画集的出版遭遇危机。为帮助小暖的漫画集顺利出版，当模特的闺蜜钱碎碎决定给小暖牵线著名漫画家海歌，但碎碎竟然把地点约在了工体夜店。富二代辛小野（杜淳 饰）一直过着淫逸奢靡的生活，他跟友人相约晚上在工体夜店开怀畅饮。苏小暖和辛小野一群人在夜店莫老板的邀请下，阴错阳差进了同一间包厢喝酒，一夜宿醉，所有人集体断片。小暖更是遗失了重要的漫画手稿。宿醉醒来的辛小野发现小暖的漫画手稿被自己带回了房间。小暖和小野因为漫画手稿不打不相识。这看似偶然的背后，却是神秘莫老板在背后的精心安排……©豆瓣', '杜淳', '刘宝贤', 3.5, 6618, 'tt4056396', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2167458590.jpg', 55.6, 25, 13, 2.8, 3.7, '0.277997,0.146272,-0.512569,0.215309,0.122024,-0.639357,0.492524,0.240572,-0.276114,-0.577550,0.074486,0.635176,-0.342644,0.660050,0.317218,-0.010630,-0.262625,-0.590908,-0.177996,-0.206760,-0.313271,-0.124938,-0.043327,-0.105363,-0.105022,0.193926,0.436993,0.238280,-0.270197,0.381885,0.448245,0.077933,-0.046469,0.381046,-0.089785,0.024768,0.179602,0.027351,-0.298290,0.159590,0.009271,-0.270716,-0.074652,-0.106511,0.398083,0.103940,0.549876,-0.162224,-0.102407,0.053869,0.709747,-0.030554,-0.146875,-0.244633,0.331156,0.230980,0.194858,-0.189702,-0.200345,0.167479,0.072281,-0.294120,-0.425359,-0.048949,0.151090,0.004684,-0.365424,0.383297,0.055833,0.185332,0.179668,-0.351153,0.259293,0.019891,0.247857,0.246266,0.002887,0.548486,-0.399923,0.379729,0.519196,0.187785,0.138398,0.251257,-0.038937,-0.413030,-0.029324,-0.009991,-0.226134,0.156302,0.415100,-0.168470,-0.021681,-0.015227,-0.665364,-0.262307,0.241983,-0.042601,0.065847,-0.036046,-0.299922,-0.550532,-0.040636,-0.087923,-0.107104,-0.022246,0.095728,-0.178932,0.857809,-0.600680,0.169613,0.683110,0.082817,-0.286949,0.689719,0.107130,-0.038110,0.129527,-0.050073,0.151212,0.251232,0.443937,0.313092,0.327979,-0.204243,-0.207726,-0.480062,0.382104', '3811356', '1908036', '27602116', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20426995', '向阳处的她', '爱情', '供职于某广告代理公司的青年奥田浩介（松本润 饰）跟随前辈拜访客户，谁知竟在对方的公司重逢了青春时代的初恋女友渡来真绪（上野树里 饰）。当年浩介（北村匠海 饰）在江之岛念书，班里突然转来一个长相可爱但是头脑和运动神经都不太灵光的女孩真绪（葵若菜 饰）。在真绪受欺负的时候，浩介果断出手相助，此后他们俩在一起学习、聊天、接吻，青涩的恋情在阳光下悄然绽放，直到浩介突然搬家离开。十年的时间并未隔断浩介和真绪的牵念，他们的爱情重新注满热情与温度。两人相恋相爱，结为夫妇。当一切看似驶向幸福的彼岸之际，真绪的身体却突然迅速衰弱。浩介还不知道，他将发现一个令他无法释怀的感伤秘密……本片根据越谷治的同名原作改编。©豆瓣', '松本润', '三木孝浩', 7.9, 61313, 'tt2569772', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1946336785.jpg', 0.4, 2.1, 25.6, 45.4, 26.6, '0.224210,0.051634,-0.620619,0.272264,-0.022445,-0.541982,0.774890,0.209651,-0.201057,-0.405912,0.081397,0.624165,-0.283851,0.341580,0.104991,0.009882,-0.107759,-0.828819,0.054672,-0.104561,-0.087997,-0.363660,-0.130256,0.000975,-0.096947,-0.371483,0.744464,0.089212,-0.027175,0.556002,0.242814,0.099423,-0.335667,0.559332,-0.301189,0.075461,0.052757,0.460106,-0.144353,0.155704,-0.194095,-0.445169,-0.143155,-0.070037,0.009576,0.304707,0.664354,0.044641,-0.398072,0.115992,0.320883,-0.030809,-0.197986,0.078744,0.307124,-0.068188,0.227892,0.108845,-0.369866,0.060706,0.072967,-0.134502,-0.348846,0.110879,0.099166,0.311602,-0.451838,0.365741,-0.033230,-0.291171,0.229195,-0.472502,0.000049,0.505883,0.317014,0.227966,-0.370204,0.289748,-0.171836,0.162341,0.654838,-0.057290,-0.275199,0.645934,-0.357549,-0.248860,-0.238059,0.099022,-0.433631,-0.100648,0.038982,0.049348,-0.082615,0.214573,-0.501371,-0.246334,0.061321,0.144826,0.015718,-0.372798,-0.004923,-0.470571,-0.299092,-0.436343,-0.341365,0.281342,0.132147,-0.072045,0.686361,-0.934601,0.034829,0.553915,0.339442,-0.181591,0.631709,0.251131,-0.208807,-0.255012,0.088114,0.369061,0.097029,0.178394,0.075419,0.490450,-0.080393,0.243858,-0.675775,0.280074', '1937946', '1307755', '1417036', '34973399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20427168', 'SPEC：零', '剧情', '2009年，当麻纱绫（户田惠梨香 饰）和濑文焚流（加濑亮 饰）相识的前一年。在美国FBI学成归来的当麻被分在警视厅公安部公安第五课未详事件特别对策系，接受组长野野村光太郎的直接领导。此前不久，某大型石油企业高管接连被人杀害，死者的心脏无一例外都留下被人用手捏过的痕迹。显而易见，这一系列事件和所谓的SPEC持有者有着极为密切的联系。与此同时，石油企业高管Diablo（大杉涟 饰）高薪聘请神秘SPEC持有者一十一（神木隆之介 饰），企图阻挡神秘的SPEC杀手。一十一，这个日后与当麻和濑文有着不解渊源的难缠敌手将当麻视作杀害父母的爆弹女，之后更斩杀了当麻在美国结识的好友Nancy。SPEC宏大篇章自此拉开序幕，决定世界命运的重大事件也进入了倒计时……©豆瓣', '户田惠梨香', '堤幸彦', 7.8, 17785, 'tt2641868', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2157867458.jpg', 0.9, 3, 26, 44.2, 25.9, '0.076569,0.005715,-0.532407,0.305897,0.274864,-0.030435,0.505233,0.150035,-0.454067,-0.372657,0.375612,0.560560,-0.340796,-0.018582,0.335751,-0.106726,0.003304,-0.643590,-0.109299,-0.358249,-0.318090,-0.375672,-0.289710,0.028654,-0.095452,-0.405325,0.774728,0.055141,-0.180890,0.511841,0.256775,0.398842,-0.243787,0.346855,-0.126009,0.059950,0.448407,-0.128308,-0.484486,0.115059,-0.393548,-0.182929,0.170543,0.089874,-0.032105,0.485963,0.652443,-0.313239,-0.017988,-0.353778,0.315912,-0.173385,-0.372691,0.203344,0.656002,0.170588,0.129156,0.651104,-0.348816,-0.034267,0.400804,-0.097710,-0.763231,-0.113168,0.224142,0.257322,-0.369864,0.191834,-0.184686,0.045794,-0.154594,-0.155648,0.079501,0.225460,0.124134,0.097702,-0.058305,0.191617,-0.006233,0.303794,0.511287,-0.153882,0.005253,0.129230,-0.059321,-0.374063,-0.236656,-0.417352,0.006654,-0.037078,0.419583,0.056781,-0.058734,0.229486,-0.626071,-0.289371,0.025533,-0.054834,0.147951,-0.256239,-0.157902,-0.527943,-0.130028,-0.243439,-0.561748,0.233221,0.275772,-0.000912,0.660499,-0.758681,0.007712,0.436909,0.546410,-0.222655,0.468609,0.162462,0.015823,-0.263301,-0.289857,-0.062268,0.304896,0.442448,0.087229,0.405813,-0.111785,-0.271076,-0.076224,-0.052275', '25880986', '25774050', '1826173', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042973', '睡前故事', '喜剧', '在斯基特（亚当·桑德勒 Adam Sandler 饰）小时候，凝聚着父亲心血的旅馆被转卖给了诺丁汉。诺丁汉将旅馆改造成酒店，并承诺斯基特长大后交还给他经营。为了这一承诺，25年后斯基特还在酒店里勤勤恳恳的做着杂役，却听到诺丁汉将新酒店总经理指名给别人的消息。沮丧的斯基特把自己的遭遇和期望编成睡前故事讲给侄子侄女听，原本天马行空的故事情节竟一一应验在现实中，令斯基特欣喜不已。他决定利用故事达成夺回酒店的期望。但孩子们对他刻意安排的故事内容百般挑剔，迫使现实也朝着意外的走向发展……©豆瓣', '亚当·桑德勒', '亚当·尚克曼', 6.5, 13383, 'tt0960731', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1200446467.jpg', 1.2, 9.3, 57.1, 25.9, 6.5, '0.344064,0.372159,-0.671936,0.677720,0.002963,-0.488301,0.431743,0.027281,-0.493925,-0.369929,-0.006750,0.732362,-0.178592,0.145042,0.234167,0.013905,-0.453715,-0.637973,0.031230,-0.236650,0.046543,-0.772860,0.186314,-0.405488,0.026732,-0.290305,0.114232,-0.100776,-0.108115,0.204952,0.227952,0.299751,0.013236,0.266189,-0.035557,0.347373,-0.039353,0.015984,-0.375292,0.208200,0.213598,-0.017599,-0.133547,0.158114,0.274198,0.270462,0.625256,-0.305216,-0.299759,0.106606,0.432874,-0.205020,0.297469,0.162169,0.145447,0.142334,0.164566,0.400988,-0.505016,-0.150089,0.123322,-0.447881,-0.706511,-0.135335,0.058765,0.007076,-0.706136,0.140162,-0.128728,0.283752,0.247117,-0.399649,0.022097,0.120210,0.692780,0.721032,-0.010791,0.223773,-0.322883,0.112770,0.426725,-0.325521,0.072229,0.271334,-0.243753,-0.104562,0.119067,-0.066622,-0.626374,0.069676,0.127566,0.248379,0.080526,0.330158,-0.563934,-0.341110,-0.308858,-0.506602,0.166385,-0.621536,-0.142579,-0.466604,-0.128083,0.246906,-0.302164,-0.049958,0.048559,-0.166052,0.535023,-0.427646,0.207017,0.494309,0.472659,-0.315074,0.564171,-0.268470,0.318980,-0.122378,0.065181,0.285908,0.275702,0.125141,0.349311,0.264205,-0.137009,-0.289983,-0.559410,0.534410', '10754780', '24733428', '26908280', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2042975', '尼姆岛', '喜剧', '小女孩尼姆（阿比盖尔·布瑞斯林 Abigail Breslin 饰）和科学家父亲杰克（杰拉德·巴特勒 Gerard Butler 饰）一起生活在一个小岛上，父亲埋头在岛屿的科研工作，而孤独的尼姆每日把岛屿的一切幻想成绚丽多彩的冒险，倒也乐在其中。尼姆最爱读畅销冒险作家艾利克斯·卢文的书，在她的幻想中，他是个和父亲面目一样的英雄，带着她畅游这个世界。但是尼姆所不了解的是，“卢文”英雄形象背后其实是个心理问题严重的女作家（朱迪·福斯特 Jodie Foster 饰），她有严重的社交恐惧症、广场恐惧症，因此只能在大城市纽约以半隐居方式埋头写作，连走出自己房间都很困难。一日父亲杰克出海工作却几日未归，担忧的尼姆只好给心目中的大英雄卢文发邮件求救，为了遥远孤岛上的小女孩，足不出户的女作家鼓起勇气踏上前往尼姆岛的路途……©豆瓣', '阿比盖尔·布雷斯林', 'Jennifer Flackett', 6.7, 5251, 'tt0410377', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p456868096.jpg', 1.1, 8.7, 51.4, 29.1, 9.6, '0.325133,-0.033606,-0.784253,0.624058,-0.078918,-0.193999,0.747982,0.097025,-0.606713,-0.204844,0.213879,0.881030,0.078904,0.392790,0.177658,0.307466,-0.501332,-0.536344,-0.059623,-0.232690,-0.302322,-0.611310,-0.250480,-0.291910,-0.223808,-0.359891,0.480345,0.115810,-0.088800,0.167443,0.107592,0.264252,0.001789,0.468426,-0.210735,-0.010908,0.003155,0.099726,-0.095775,0.148139,0.095555,0.008881,-0.176850,0.197909,0.239258,0.213738,0.620230,-0.210323,-0.092441,0.128754,0.241881,-0.272702,0.036956,0.095648,0.309419,-0.339062,0.212667,-0.064609,-0.019478,-0.136396,0.087142,-0.162461,-0.560023,-0.042540,0.206564,0.225297,-0.663100,0.439103,-0.229101,-0.167781,-0.030140,-0.397441,0.054489,0.270143,0.279679,0.388409,-0.051219,0.038426,-0.308070,0.301099,0.334959,0.272033,-0.343860,0.154574,-0.530761,-0.313883,-0.062579,-0.288167,-0.714306,-0.180599,0.216118,-0.195556,-0.365388,0.231413,-0.488120,0.212718,-0.219825,-0.248847,-0.166462,-0.288831,-0.182911,-0.467644,0.150922,-0.438309,-0.158212,-0.149365,0.127813,-0.190626,0.645255,-0.629706,0.388629,0.560867,0.194164,-0.167785,0.826343,0.054304,0.026393,-0.214229,0.068549,0.534023,-0.099796,0.181121,-0.056232,0.262485,0.148753,-0.223213,-0.526897,0.612724', '26677495', '3055049', '1460341', '21354767');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20431537', '道歉大师', '喜剧', '在海外学习法律归来的仓持典子（井上真央 饰）撞坏黑道的豪车，为避免卖身还债，她求助于自称“道歉师”的黑岛让（阿部隆史 饰）。经营东京道歉中心的黑岛以极其专业的技巧圆满解除这一危机，之后典子也作为员工效力黑岛旗下。性格迥异的二人携手搞定了花哨白领沼田卓也（冈田将生 饰）的性骚扰案，知名演员南部哲郎（高桥克实 饰）之子的打人事件以及律界精英箕轮正臣（竹野内丰 饰）内心深藏多年的烦恼。下跪谢罪作为国粹，经黑岛得到了极大的发扬，甚至他还被请去解决日本和蒙坦王国之间的国际纠纷。然而一向轻车熟路的他，却遇到了从业以来最大的挑战……©豆瓣', '阿部隆史', '水田伸生', 7.1, 7593, 'tt2556296', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2043133640.jpg', 1.2, 6.3, 40.4, 39.1, 13, '0.173741,0.101283,-0.439357,0.504653,-0.129648,-0.011449,0.096095,0.291085,-0.282082,-0.454678,0.149211,0.703864,0.116228,0.165066,0.423257,-0.131780,0.117126,-0.560719,-0.118260,-0.039738,-0.145560,-0.483307,-0.219679,-0.150100,-0.444943,-0.127082,0.650942,0.160817,-0.386497,0.512026,0.295571,0.467197,0.035457,0.232205,0.168382,-0.061209,0.124388,0.242733,-0.158581,0.120735,-0.234465,-0.266397,0.213285,0.254009,0.210761,0.378823,0.287522,-0.136199,-0.021385,-0.170717,0.391922,-0.280163,-0.071436,0.177821,0.288765,-0.063108,0.071813,0.457354,-0.318591,-0.065214,-0.012484,0.023088,-0.759863,-0.118454,0.227121,-0.097096,-0.597783,0.429508,-0.010189,-0.186399,0.049579,-0.095217,-0.097676,0.454679,0.388764,0.155784,-0.206910,0.213557,-0.216354,0.300120,0.585400,-0.047393,-0.057975,-0.145396,-0.121706,-0.414398,0.092920,-0.520199,-0.070752,-0.280644,-0.075900,-0.095247,0.059351,0.065301,-0.418808,-0.202473,-0.175124,-0.087498,0.280959,-0.216557,0.168177,-0.862278,-0.014943,-0.639749,-0.391341,0.017874,0.354330,-0.294543,0.766402,-0.811773,-0.153786,0.516321,0.248895,-0.518831,0.582504,0.220370,-0.006836,-0.112303,-0.230862,0.158987,0.347108,0.549748,-0.103615,0.195586,0.068433,-0.202759,-0.157453,0.104147', '2369613', '3811356', '30465281', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2043154', 'Little DJ 小小恋爱物语', '爱情', '海乃环（广末凉子 饰）是FM广播电台午夜节目的栏目策划人，由于无人收听，她的节目面临停播的命运。沮丧的她听到Candies乐队的老歌《比我小的男生》，思绪飘回1977年。1977年的棒球赛场上，高野太郎（神木隆之介 饰）一边模拟着棒球场播音员的赛事直播一边奋力发球。 高野太郎是电台节目《音乐快车》的忠实fans，每日一边收听一边练球。这天突然在学校晕倒，没过多久进住进了医院，乏味的生活和无休止的抽血检查让太郎消沉，直到偶然闯入大医生的房间，当起了小DJ，每日中午为医院病人播放歌曲。小小DJ生涯彻底改变了太郎的住院生活和人生，也改变了他身边的病人和医护人员，因车祸住院的海乃环（福田麻由子 饰）就是其中之一，这个总是爱甜甜微笑的小女生总爱陪在太郎身边。太郎想对她表白却总也开不了口，他写下一封点播信给最信任的《音乐快车》的DJ，信还未寄出，太郎的生命已经迅速衰弱下去。', '神木隆之介', '永田琴', 7.8, 5868, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p823973141.jpg', 0.4, 1.9, 26.7, 49.7, 21.3, '-0.006239,0.036180,-0.201019,0.322097,0.150664,-0.225983,0.692281,0.339838,-0.370230,-0.186377,0.267921,0.390821,-0.117570,0.503795,0.327646,-0.043950,-0.494883,-0.670628,-0.266892,0.323036,-0.202854,-0.346559,0.131293,-0.023468,-0.140178,-0.170825,0.441390,-0.032835,-0.071791,0.586564,0.247406,-0.060246,0.183205,0.218478,-0.232154,0.261018,-0.006641,-0.050972,-0.010106,0.019672,0.388697,-0.472479,-0.280373,-0.001062,0.398493,0.145254,0.597885,0.008112,-0.295177,-0.087979,0.405496,-0.211834,-0.263595,0.131608,0.317154,0.242977,0.441191,0.044587,-0.186077,0.060064,-0.020269,0.041322,-0.554434,0.141700,-0.071732,0.323760,-0.154480,0.381757,-0.315887,0.040965,0.422689,-0.304094,0.030739,0.273689,0.083255,0.409605,-0.509823,0.048446,-0.088079,0.391838,0.389032,-0.008572,-0.087268,0.463680,-0.065838,-0.315528,-0.323956,-0.118798,-0.527811,-0.041385,-0.085855,-0.009166,-0.212174,-0.058580,-0.203198,0.117655,0.084996,-0.614087,0.323652,-0.363684,-0.211248,-0.771124,0.207410,-0.167461,-0.218189,0.189630,0.125052,-0.013601,0.807217,-0.775597,0.261877,0.700260,0.233599,-0.061766,0.595772,0.118126,-0.270606,-0.136825,0.139914,0.231250,-0.206991,0.796552,0.071485,0.605991,-0.056408,-0.142473,-0.756480,0.272652', '3811356', '5403927', '25922902', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2043404', '只有你听见', '剧情', '与家人生活在一起的高中生相原菱（成海璃子 饰）性格内向。在班上阿菱没有朋友，看到同学们都有手机，她也渴望自己能拥有一台。阿菱某天在公园里拣到一台玩具手机，她本来是觉得好玩而留下了。没想到第二天她在学校保健室休息的时候，这部手机竟然响起来。慌忙中她接了电话，对方是一名年轻男子。随后她便认识了这个叫慎也（小出惠介 饰）的男孩子。慎也与祖母生活，刚高中毕业的他当今在废品回收公司上班。在电话里，阿菱与慎也聊开了，互相交换彼此的事情。同样孤独的两人因为这个偶然渐渐走到了一起。阿菱得到了慎也的鼓励，越来越开朗，两人互相影响改变。他们相约在周末的东京见面，阿菱想到终于能跟慎也直面交谈兴奋不已，但意想不到的一个事实也同样走向阿菱。©豆瓣', '成海璃子', '荻岛达也', 7.5, 8733, 'tt0997163', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p988304614.jpg', 0.6, 3.6, 35.4, 43.4, 17.1, '0.616112,0.023823,-0.791560,0.400508,-0.120797,-0.333084,0.729025,0.119116,-0.322084,-0.254129,-0.037622,0.970989,-0.277804,0.361308,0.105134,-0.383340,-0.504038,-0.638665,0.228333,-0.250660,-0.408543,-0.407206,0.024138,-0.182560,-0.021599,0.030560,0.233131,-0.099321,-0.054686,0.701659,0.164838,-0.025378,-0.047990,0.670001,-0.429087,0.086238,-0.018616,0.378297,0.062687,0.113813,0.070987,-0.381882,-0.301885,0.165785,0.299624,0.201786,0.511448,-0.079363,-0.254791,0.148439,0.003904,0.107744,-0.193871,-0.057496,0.310559,0.067497,0.320085,-0.036769,-0.367711,0.062950,-0.069273,0.087011,-0.461841,0.336340,-0.169889,0.080653,-0.353807,0.538806,0.089414,-0.262074,0.208467,-0.320007,0.598063,0.451767,-0.160279,0.353787,-0.291711,-0.034625,-0.358226,0.085466,0.595616,0.088340,-0.062493,0.556319,-0.205474,-0.390140,-0.017403,0.124359,-0.569761,-0.033588,0.165058,-0.026611,-0.289043,-0.052578,-0.522068,0.182519,0.002005,0.020058,-0.058678,-0.579695,-0.125684,-0.510904,-0.181682,-0.441775,-0.558644,0.494365,0.005922,-0.178376,0.866254,-1.057128,0.032807,0.333592,0.395892,-0.469764,0.700086,0.018774,0.031873,-0.190648,0.064656,0.022336,-0.053615,0.266848,0.250283,0.507482,0.000292,-0.017682,-0.628720,0.414286', '1292219', '1915403', '1292720', '1307755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2043465', '十分爱', '爱情', '家宝（邓丽欣饰）样子甜美，受到很多男士的欢迎。与志荣（森美饰）晴晴（钟嘉欣饰）夫妻是老同学。家宝无意间发现了志荣与朋友碧莲之间的暧昧，志荣更与家宝大谈第三者，家宝面对晴晴的时候十分内疚，不知是否应该告之真相，也把事情告诉了自己的室友阿蚊（杨爱瑾饰）。家宝遇到了自己的旧男友大力（方力申饰）的同时也跟医生Joe（张敬轩饰）互有好感，三角关系十分尴尬。家宝被人加害，怀疑是大力继分手后的再次暗算。家宝后来还是觉得大力对自己的感觉是真的，于是重修旧好。但没想到，一切的事情都有各自的真相，令人大感惊奇。©豆瓣', '邓丽欣', '叶念琛', 7.2, 43786, 'tt0996978', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2175061766.jpg', 1.2, 5.3, 38, 41.6, 13.9, '0.549888,-0.566132,-0.542031,0.173295,0.299260,-0.286693,0.503843,0.157489,-0.910517,-0.263933,0.217303,0.572061,-0.559503,0.087064,-0.050600,0.207871,-0.004163,-0.735059,0.358487,-0.100584,-0.152447,-0.538023,-0.052482,0.146224,-0.008016,-0.157996,0.190190,-0.207879,-0.124476,0.701076,0.235638,0.237567,-0.069820,0.881055,0.210525,0.181459,0.053851,0.273390,-0.418648,-0.304111,0.261430,-0.089237,-0.136908,0.405545,-0.311426,0.373128,0.425107,-0.083258,-0.515018,0.076327,0.183376,-0.073649,-0.047778,0.160389,0.304356,0.027145,0.616911,0.336176,-0.162324,-0.017204,0.364733,0.338603,-0.461140,0.434813,0.285274,0.163178,-0.429869,0.186388,-0.260757,-0.119124,0.444762,-0.401690,0.356104,0.490081,0.583854,0.382671,-0.310565,0.106754,-0.360620,-0.387805,0.676881,0.138856,0.332286,0.436343,-0.336581,-0.154057,0.142637,0.106493,-0.589555,0.468660,-0.118061,0.292534,-0.167170,0.402844,-0.670131,0.043199,-0.236962,0.310860,-0.065988,-0.541092,0.140887,0.001682,-0.516766,-0.433737,-0.503000,-0.339367,0.228960,-0.412561,0.683411,-0.934375,0.030041,0.161757,0.515235,-0.474466,0.387028,0.370647,-0.206078,-0.399418,-0.216090,-0.337861,-0.256145,0.094619,0.201781,0.351055,0.140296,-0.544313,-0.077047,0.015818', '35030151', '1480318', '25810920', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2043546', '秒速5厘米', '剧情', '如果，樱花掉落的速度是每秒5厘米，那么两颗心需要多久才能靠近？少年时，贵树（水橋研二配）和明理（近藤好美配）是形影不离的好朋友，可很快，一道巨大的鸿沟便横亘在两人中间：明理转学，贵树也随着父母工作的调动搬到遥远的鹿儿岛。在搬家前，贵树乘坐新干线千里迢迢和明理相会，在漫长的等待后，茫茫大雪中，两人在枯萎的樱花树下深情相拥，并献出彼此的first kiss，约定着下一次再一起来看樱花。时光荏苒，两人竟再没见过，虽然在人海中一直搜寻彼此的身影，但似乎总是徒然。再后来，他们分别有了各自的生活，只是还偶尔会梦到13岁时的这段青涩而美好的感情，才明白当年怎么也说不出口的那个字就是爱。©豆瓣', '水桥研二', '新海诚', 8.3, 542792, 'tt0983213', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p982896012.jpg', 0.6, 2.4, 18.2, 38.6, 40.2, '0.212760,-0.120187,-0.885348,0.518256,0.053126,-0.510943,0.755470,0.004791,-0.461811,-0.021761,0.075553,0.589627,-0.240856,0.425580,0.151920,0.005694,-0.344498,-0.939760,-0.102690,-0.456817,-0.495727,-0.576943,-0.176212,0.090520,0.097939,0.090488,0.647951,0.314675,0.300555,0.714679,0.050506,-0.443789,-0.468449,0.678146,-0.442007,-0.136306,-0.227109,0.588733,-0.307647,-0.086733,0.031978,-0.455933,-0.071606,-0.319918,-0.027319,0.367084,0.663463,-0.318678,-0.245452,0.238794,0.072909,-0.049732,0.050960,0.120556,0.474684,-0.053961,0.514860,0.077472,-0.333031,0.018525,-0.337761,-0.031751,-0.364822,0.145426,-0.120820,0.231295,-0.695773,0.578876,0.344971,-0.464610,0.263649,-0.454940,0.051609,0.600523,0.156318,0.372406,-0.561663,-0.191904,-0.157423,0.079952,0.784986,0.278484,-0.504910,0.549042,-0.082719,-0.257021,-0.213740,0.008409,-0.269651,-0.052975,-0.097752,0.397179,-0.172138,0.175978,-0.644790,0.397880,-0.142365,0.049491,0.052462,-0.644014,-0.246612,-0.512405,-0.031183,-0.821986,-0.347243,0.511061,0.029973,-0.205988,0.652986,-0.728336,0.447542,0.536373,0.563294,-0.068555,0.768370,0.284378,0.026595,-0.052516,0.097916,0.245388,-0.253799,0.343067,0.262188,0.343682,-0.027235,0.365699,-0.527535,0.437420', '34973399', '1308480', '1302109', '6425147');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20435622', '环太平洋：雷霆再起', '动作', '在对抗外星人的入侵并成功封住虫洞的十年后，人类从废墟中站起来。他们忘记了恐惧，纵情狂欢，其中便包括斯特克·潘特考斯特将军的儿子杰克（约翰·博耶加 John Boyega 饰）。在一次偷到废弃机甲零件的过程中，他偶然遭遇以一己之力组装迷你机甲的少女阿玛拉（卡莉·史派妮 Cailee Spaeny 饰）。此后，在姐姐森麻子（菊地凛子 饰）的安排下，杰克和阿玛拉莫玉兰基地接受机甲驾驶员的培训工作。与此同时，总部位于上海的邵氏集团，在总裁邵丽雯（景甜 饰）的主持下，正致力于以无人机甲取代传统机甲。就在这关键时刻，一个与复仇流浪者极其相似的黑色机甲突然出现，并向人类展开了无情杀戮。人们发现，遥远的外星“先驱”仍在蠢蠢欲动，时刻等待着消灭地球人的时机……©豆瓣', '约翰·博耶加', '斯蒂文·S·迪奈特', 5.4, 231720, 'tt2557478', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2512933684.jpg', 7.7, 30.4, 47.6, 11.5, 2.8, '0.039030,0.285850,-0.708773,0.519153,0.058109,-0.319338,0.752600,0.003735,-0.196177,-0.221123,0.448457,0.280572,-0.029933,0.046298,0.392216,-0.028854,-0.521732,-0.433067,-0.130036,-0.063078,-0.418600,-0.277170,-0.196695,-0.366394,0.248639,-0.622044,0.733389,0.077831,-0.298130,0.263796,-0.056948,0.377301,-0.298661,0.458779,0.055097,-0.034145,0.213933,-0.219560,-0.231884,0.296864,-0.327813,-0.092985,0.012382,0.021828,-0.069363,0.195068,0.891771,-0.642348,0.124787,-0.279504,0.092169,-0.106538,0.111191,-0.138786,0.508070,-0.134166,-0.146985,-0.088696,-0.107049,0.115491,0.101344,0.058268,-0.632214,-0.154043,-0.141045,0.287881,-0.565534,0.538735,-0.188949,0.242768,0.058243,-0.407453,0.042029,0.296877,0.186072,0.289686,-0.119124,0.248377,-0.593653,0.075774,0.433157,0.091925,-0.243384,0.117135,0.046375,-0.534947,-0.211907,0.046261,-0.429660,-0.418681,0.498415,-0.117119,0.152802,0.479278,-0.734428,0.027871,-0.251764,-0.113995,0.061729,-0.284706,-0.157976,-0.861923,0.103851,-0.091638,-0.157124,0.276296,0.034194,-0.089457,0.435433,-0.857504,0.342328,0.481485,0.310758,0.075633,0.500345,-0.236493,0.168189,-0.427990,-0.312703,0.234644,0.135332,0.538060,0.195374,0.470995,-0.026339,-0.018005,-0.373300,0.465509', '1307897', '1294917', '1306809', '1309064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20438548', '蜡笔小新：超级美味B级美食大逃亡', '动画', '阳光明媚的一天，盛大的B级美食嘉年华在春日部市召开，野原新之助（矢岛晶子 配音）看到新闻后兴奋非常，于是和樱田妮妮、风间彻、代全林、佐藤正男等好朋友们商定，偷偷前往嘉年华大饱口福。与此同时，B级美食嘉年华举行的消息也传到所谓的A级美食机构。该机构最高负责人满美食大人（中村悠一 配音）对B级食物充满鄙夷，他决定彻底摧毁这些下等吃食。未久，A级美食的飞船飞临嘉年华，对底层料理手艺人进行无情驱逐。为了挽救B级美食，炒面阿健决定启用传承已达五十代的秘制酱汁。阿健的相好红子走投无路，将酱汁罐子交给春日部防卫队的各位。小新和朋友们无意间承担起包围B级美食的重任……©豆瓣', '矢岛晶子', '桥本昌和', 8.3, 18730, 'tt2876906', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2345414490.jpg', 0.1, 1.3, 18, 43.4, 37.1, '-0.020884,0.204578,-0.294167,0.208245,0.045305,0.243187,0.163959,0.325747,-0.148294,-0.262039,0.262334,0.570747,-0.234160,0.328387,0.596353,-0.383084,-0.396643,-0.307549,-0.132172,-0.479520,-0.232058,-0.155027,-0.040693,0.012105,-0.160372,0.009032,0.703289,-0.097571,-0.235474,0.290258,0.389197,0.199734,-0.084039,0.222826,-0.137843,-0.332478,0.394620,-0.194759,-0.441724,0.310378,-0.456268,0.112121,-0.145251,-0.031735,0.437370,-0.065810,0.616402,-0.173463,-0.283913,-0.298552,-0.063609,-0.259276,0.153212,0.143423,0.392889,0.261871,-0.006373,-0.025047,-0.075929,0.062430,-0.131184,-0.261157,-0.828451,-0.239003,0.046472,-0.178525,-0.087389,0.218391,-0.029709,0.087273,0.356144,-0.439490,0.084442,0.271716,0.147002,0.518987,0.005462,0.520126,-0.301198,0.329280,0.483430,0.001943,0.371535,-0.013468,0.194754,-0.347844,0.173337,-0.369934,-0.005194,-0.104362,0.003056,0.275977,0.322328,0.189982,-0.822980,-0.192097,0.165860,-0.848805,0.521849,-0.100204,-0.195155,-1.029885,0.269050,0.188429,-0.196891,0.301628,0.440889,-0.184793,1.005308,-0.659277,0.303310,0.036749,0.036775,-0.340392,0.360963,-0.024665,0.043216,-0.249595,-0.204404,-0.056705,0.256651,0.301283,0.147693,0.395947,-0.078427,-0.387944,-0.440599,0.168277', '2369613', '3318306', '5403927', '26094129');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20438962', '鸟人', '剧情', '早已年过半百的里根·汤姆森（迈克尔·基顿 Michael Keaton 饰）曾经是一名风光一时的好莱坞电影明星，他所塑造的超级英雄飞鸟侠家喻户晓。而今荣耀早成明日黄花，不甘寂寞的里根转战百老汇，试图通过改编雷蒙德•卡佛的《当我们谈论爱情的时候，我们谈论什么》重新赢得关注 与尊重。无奈现实总和理想有太大的差距，剧组经费吃紧，糟糕的男主角被灯砸头，刚从戒毒所出来的女儿萨米（艾玛·斯通 Emma Stone 饰），毒舌戏剧评论员箭在弦上蓄势待发，此外请来救场的好莱坞当红小生麦克·珊农（爱德华·诺顿 Edward Norton 饰）乖戾张扬，屡屡染指篡改里根殚精竭虑打造的戏剧。在混乱的鼓点中，命运多舛的戏剧迎来了公演的重要时刻……©豆瓣', '迈克尔·基顿', '亚历杭德罗·冈萨雷斯·伊纳里图', 8, 238652, 'tt2562232', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203838902.jpg', 0.8, 2.7, 21.5, 45, 30, '0.332677,0.254003,-0.593206,0.265162,0.146834,-0.183295,0.581333,0.168065,-0.133630,-0.161578,0.288117,0.617470,-0.197499,-0.012556,0.360846,-0.191765,-0.194279,-0.599430,-0.011803,0.042327,0.140921,-0.386640,-0.573281,0.029559,-0.119768,-0.250577,0.630349,0.018588,-0.422310,0.308593,0.544366,0.125086,0.085892,-0.118578,-0.091163,-0.003178,0.385100,0.094747,-0.432742,0.035954,-0.243382,-0.155615,-0.113191,0.111172,-0.070028,0.338225,0.236226,-0.324850,0.079484,0.185868,0.739234,-0.213157,-0.185952,0.060032,0.129352,-0.008489,-0.013241,-0.111000,0.011694,-0.117972,-0.208566,-0.239192,-0.909902,0.078759,0.115476,0.245819,-0.403550,0.314773,-0.140190,-0.002340,0.196001,0.021326,0.194783,0.072561,0.268599,0.235654,0.107728,0.143593,-0.144322,0.621680,0.425351,0.104653,-0.549040,0.224731,-0.122327,-0.038004,0.117471,-0.487594,-0.578862,-0.146566,0.425603,-0.345035,0.101714,0.369351,-0.312871,-0.033137,-0.142517,-0.122161,0.021978,-0.253097,-0.101558,-0.746475,-0.292264,-0.428536,0.080053,-0.332591,0.171361,-0.274286,0.824787,-0.604266,0.129359,0.365283,-0.135262,-0.294891,0.547343,-0.018551,0.076732,-0.244765,-0.208150,0.286783,0.131473,0.137847,-0.097459,0.177806,0.055470,-0.468763,-0.284238,0.410126', '27602116', '3318306', '24284209', '1306795');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20438964', '无敌破坏王2：大闹互联网', '喜剧', '这一次，破坏王拉尔夫（约翰·C·赖利 John C. Reilly 配音）和云妮洛普（萨拉·丝沃曼 Sarah Silverman 配音）又闯祸了，导致了云妮洛普所在的游戏《甜蜜冲刺》的游戏机方向盘遭到了损坏。这是一台非常古老的街机，在整个互联网中，只有一只备用方向盘正在销售，然而它的售价实在是非常昂贵，老板决定放弃这台机器，将它解体变卖。这也就意味着，《甜蜜冲刺》里的角色们将永远失去他们的家园。为了避免这一悲剧的发生，拉尔夫和云妮洛普决定亲自到互联网里去走一遭，买回方向盘。一路上，他们惹了无数的笑料，犯了无数令人啼笑皆非的错误。为了赚钱，拉尔夫不惜亲自出马成为视频网站的网红赚取点击量变现，而云妮洛普则在另一款赛车游戏《狂野飙车》里找到了真正的自我。©豆瓣', '约翰·C·赖利', '菲尔·约翰斯顿', 8, 366104, 'tt5848272', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2537667301.jpg', 0.3, 2.1, 22.5, 46.4, 28.7, '0.372001,0.312460,-0.526863,0.341742,0.003535,-0.154193,0.682890,-0.049368,-0.372585,-0.125336,0.165990,0.721738,-0.332073,0.102652,0.185503,-0.012136,-0.103113,-0.406977,0.057651,-0.142167,-0.226965,-0.246802,-0.313320,-0.253038,-0.060731,0.165941,0.500671,-0.043682,-0.390013,0.159555,0.320104,0.227111,0.087817,0.379677,-0.135402,0.165693,-0.199151,-0.261102,-0.015515,0.266887,0.172528,-0.249633,0.218978,0.115273,0.077104,0.136316,0.750739,-0.387990,-0.016634,-0.034755,0.500788,-0.387261,-0.293814,-0.123022,0.028906,0.310196,0.029947,-0.044678,-0.473927,0.275997,0.290047,-0.075035,-0.948233,-0.087400,-0.291957,0.060660,-0.616977,0.136764,-0.238724,-0.132391,0.155857,-0.233274,0.362907,0.260247,0.496087,0.257691,-0.262416,-0.070498,-0.365481,0.209702,0.572185,-0.020386,-0.151378,0.413071,-0.086533,-0.270871,-0.003784,-0.418755,-0.335140,-0.203941,0.486803,0.067700,-0.008446,0.212821,-0.835124,0.142481,-0.115518,-0.607215,-0.076917,-0.366237,-0.185051,-0.772684,0.023402,-0.134791,0.033072,-0.044396,-0.014216,-0.452658,0.546655,-0.768748,-0.078180,0.538814,0.170015,-0.468902,0.367425,-0.056295,0.286559,-0.082011,-0.057581,0.064578,0.058443,0.602011,0.070973,0.150373,0.115361,-0.250473,-0.358859,0.617601', '1793491', '1308585', '25928048', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20440456', '轻轻摇晃', '剧情', '华裔女性珍（郑佩佩 饰）与儿子凯（Andrew Leung 饰）相依为命，从柬埔寨金边移民到英国伦敦。不谙英文的她一直依靠儿子充当眼睛和耳朵，儿子就是她的全部。然而她并不知道凯的性取向，甚至长期以为凯和同居的英国人理查德（本·卫肖 Ben Whishaw 饰）只是“室友 ”。当凯因为一场车祸意外去世后，无助的珍惟有开始接触理查德，从而开始翻阅儿子生前不为人知的画面。一老一少将共同面对失去挚爱的生活——哪怕他们无法以言语沟通。《轻轻摇晃》由英国微波电影基金和BBC联合投资拍摄，是亚裔导演许泰丰的第一部剧情长片，它成功的结合了同志情感与移民故事，演员间细腻微妙的互动，让轻缓流动的画面与剧情有了饱满的张力与生动的趣味。《轻轻摇晃》获2014年圣丹斯国际电影节最佳摄影奖。©豆瓣', '本·卫肖', '许泰丰', 7.3, 13024, 'tt2560102', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2195421480.jpg', 0.6, 4.9, 39.8, 40.7, 14, '0.158757,-0.056865,-0.771074,0.611232,0.408945,-0.140629,0.574176,0.232883,-0.391387,-0.200983,-0.043753,0.724220,-0.423771,0.194532,0.141297,-0.096749,-0.402217,-1.059242,-0.143137,0.021634,-0.164262,-0.481207,-0.086594,-0.187437,-0.110469,-0.418920,0.882104,0.008387,-0.427946,0.505104,0.262088,0.388336,-0.242176,0.029819,-0.243506,-0.135463,-0.084903,0.094979,-0.429276,-0.207277,0.351965,-0.275954,-0.014796,0.046049,0.065826,0.423586,0.907057,-0.356091,-0.041825,0.085566,0.335342,-0.110589,-0.122147,0.017592,0.068489,0.188960,0.335839,0.291061,-0.238465,-0.066263,0.022926,-0.340521,-0.795280,-0.021111,0.233628,0.179351,-0.327703,0.234856,-0.010489,-0.032881,0.175164,-0.045861,0.242301,0.493967,0.264455,0.429540,-0.118940,0.196687,-0.143298,0.336755,0.435314,0.148878,-0.333157,0.636861,-0.411197,-0.470073,-0.436602,-0.248678,-0.297885,0.159562,0.155505,0.030195,-0.065428,0.371251,-0.710753,-0.111996,-0.172101,-0.107818,0.255073,-0.356412,-0.014845,-0.641126,-0.319472,-0.484673,-0.137271,0.029241,0.033364,-0.374999,0.751195,-0.785752,0.028211,0.411450,0.319527,-0.292376,0.698919,-0.050766,-0.013904,-0.465385,-0.082572,0.250430,-0.161136,-0.221826,0.305583,0.209235,-0.122876,0.192388,-0.269075,0.319385', '25880986', '3811356', '10467125', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2044089', '杀手没有假期', '剧情', '一对儿杀手，肯与雷（Colin Farrell 饰），在圣诞期间来到比利时古城布鲁日，他们将在这里接到联系人哈里（Ralph Fiennes 饰）指令的新任务。雷在不久前的一次暗杀中误杀了一名男童，怀着深深愧疚的雷情绪不稳，古城中的等待对他来说是一场难耐的煎熬。肯作为带领雷入行的前辈，试图帮助雷摆脱困境，但他的努力毫无收效。百无聊赖的雷在街上结识了女演员克洛伊，这个神秘女孩引发了雷一系列的冒险经历，与此同时，肯再一次被哈里催促，原来此次任务的真相是暴怒的哈里要雷为他的误杀行为付出代价，肯面对被自己一手引入杀手行当的年轻人，难以做出抉择，两名杀手，在夜色中的古城各怀心事……本片获2009年英国学院奖最佳剧本奖等多项褒奖。©豆瓣', '科林·法瑞尔', '马丁·麦克唐纳', 8.1, 133689, 'tt0780536', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173386253.jpg', 0.4, 1.8, 18.8, 49.7, 29.3, '0.171035,0.162043,-0.755738,0.639727,0.057138,-0.041519,0.464865,-0.230977,-0.800476,-0.270371,0.261017,0.699428,-0.196767,0.283347,0.468748,-0.197427,-0.218673,-0.729446,-0.271033,-0.044806,-0.442127,-0.380602,-0.283238,-0.289307,-0.260430,-0.421574,0.516154,0.588379,-0.249803,0.338323,0.651086,0.693214,-0.098183,0.376368,0.013545,-0.131773,0.388393,-0.121623,-0.170375,0.338844,-0.012146,-0.537557,-0.177830,0.343718,0.242842,0.414656,0.695465,-0.384430,-0.239934,-0.044074,0.275364,-0.617483,-0.059401,0.062562,0.301769,0.021121,-0.023044,0.196367,-0.293711,0.063951,-0.059448,-0.364920,-0.806377,-0.101958,0.267262,0.112242,-0.770861,0.408780,-0.086766,0.187650,-0.096596,-0.149554,0.053098,0.287190,0.331373,0.204299,-0.118625,-0.045874,-0.417509,0.227117,0.707542,0.079675,-0.031943,0.140320,-0.184609,-0.523212,-0.134227,-0.203176,-0.414949,0.060068,0.658083,0.119517,-0.232502,0.124008,-0.181751,-0.172747,-0.460664,-0.214651,-0.128765,-0.459793,-0.233115,-0.636090,0.015904,-0.231285,-0.117096,0.230528,-0.022969,-0.099950,0.618282,-0.873034,0.159230,0.372282,0.018974,-0.287696,0.554701,0.141742,0.010775,-0.246062,0.152051,0.036528,0.065954,0.030329,0.198349,0.346148,-0.079097,-0.020935,-0.307972,0.311830', '1301022', '35030151', '1793491', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2044102', '导火线', '动作', '重案组沙展马军（甄子丹 饰）致力抓拿犯罪分子，身手不凡的他由于抓贼心切常常出手过重。警方一直搜集越南帮兄弟阿渣（吕良伟 饰）、Tony（邹兆龙 饰）、阿虎（行宇 饰）的犯罪证据，于是派出了华生（古天乐 饰）以卧底的身份潜入他们之间。三兄弟为人心狠手辣，想铲除掉眼中钉阿山。阿渣被抓后，Tony也识破了华生的真实身份，要将华生以及其他证人通通杀掉，救出大哥。华生女友秋堤（范冰冰 饰）被挟持，华生不得不放弃指证阿渣。华生与女友都抓走当人质，马军也带着阿渣去营救华生。©豆瓣', '甄子丹', '叶伟信', 7.4, 115772, 'tt0992911', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165117418.jpg', 0.5, 3.8, 37.9, 41.2, 16.6, '0.112996,-0.178053,-0.184787,0.249840,-0.300557,-0.115117,0.300125,0.020743,-0.396374,-0.277481,0.207400,0.350412,0.097017,-0.074864,0.227686,0.048834,-0.439152,-0.719071,-0.086253,-0.011044,-0.245089,-0.459276,-0.237506,-0.311004,0.026567,0.116513,0.360306,-0.189569,-0.263181,0.433561,0.585814,0.318850,-0.408988,0.232758,0.025782,0.061816,0.078982,-0.425427,-0.489464,0.111714,0.060704,-0.276797,0.060035,0.189235,-0.057690,0.461047,0.439440,-0.064896,0.125340,-0.221989,-0.063385,-0.708210,0.176595,0.034433,0.311007,0.092207,0.137092,0.478454,-0.104301,0.086179,0.267119,0.107685,-0.834886,0.188243,0.401639,-0.020172,-0.481735,-0.045128,-0.390741,0.219372,0.218003,-0.166589,0.137815,0.328760,0.108855,-0.089334,-0.022820,-0.103188,-0.548689,0.240443,0.426725,-0.326430,0.581212,-0.274202,0.221124,-0.236517,0.176538,-0.258265,0.010875,0.017618,0.398994,-0.061339,-0.177867,0.012331,-0.337472,-0.481599,-0.389266,0.242652,-0.104879,-0.369772,0.338023,-0.462815,0.093416,-0.015187,-0.238617,0.126598,0.172450,-0.107662,0.393886,-0.371775,-0.140354,0.309961,0.428450,-0.825552,0.230132,0.248600,0.018866,-0.323104,-0.340354,-0.066365,0.655460,0.401329,0.368117,-0.002865,0.003416,-0.521626,-0.264990,-0.381405', '1302110', '1428602', '1297862', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20441632', '爱，简单', '剧情', '女孩吉瓦娜（Tess Amorim 饰）和男孩里奥（Ghilherme Lobo 饰）是最要好的朋友。里奥虽然双目失明，但内心一直渴望自立，不喜欢来自父母的过多保护。新来转校生加百列（Fabio Audi 饰）不小心闯入里奥的世界，也改变了里奥和吉瓦娜的相处习惯。里奥对爱上加百列患得患失，吉瓦娜对里奥的疏远伤心难过，而加百列懵懵懂懂的回应更让男孩女孩们的世界复杂起来......《爱，简单》是巴西导演丹尼尔·里贝罗根据自己2010年的短片《爱，牵手》改编、起用原班人马拍摄的剧情长片处女作。《爱，牵手》曾获得大小11个电影节的最佳短片奖。《爱，简单》依然讲述在牵手中跨越视觉的爱，然而与短片相比，故事的重心从性觉醒转移到了主角的独立成长上。独立成为电影的内核，其中也包括他独立选择去爱谁的自由意志。《爱，简单》获得第64届柏林电影节全景单元国际影评人费比西奖，以及象征同志电影最高荣誉的泰迪熊奖。', '吉列尔梅·路宝', '丹尼尔·里贝罗', 8.3, 30260, 'tt1702014', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189595424.jpg', 0.3, 1.1, 17.9, 45.6, 35.1, '0.045740,0.036730,-0.618093,0.508963,-0.198445,-0.055322,0.596801,0.013072,-0.226302,0.101866,-0.043263,0.839089,-0.038976,-0.006480,0.300665,0.199975,-0.298090,-0.583364,0.102851,-0.132127,0.127232,-0.609864,-0.445385,-0.094866,-0.252230,-0.584551,0.772582,0.007136,-0.155236,0.407902,0.492343,0.032263,0.107141,0.080025,0.096275,-0.022158,0.058012,0.171590,-0.519042,0.170045,-0.128611,0.186454,-0.001947,0.128596,0.097602,0.210475,0.551803,-0.406980,-0.122342,0.062742,0.653886,-0.171719,-0.191443,-0.170392,0.057965,0.224778,0.295663,0.106340,0.110982,0.355012,-0.202035,-0.154699,-0.727978,-0.090307,0.526091,0.130275,-0.480744,0.648790,-0.225527,-0.184682,0.098270,-0.160994,0.060958,0.096490,0.402769,0.440174,-0.052651,0.119426,-0.006407,0.094714,0.633426,0.025741,-0.388989,0.361997,-0.529926,-0.396315,-0.213422,-0.568119,-0.427984,0.092136,0.004909,0.051652,0.132014,0.220013,-0.416069,0.149186,0.142771,-0.064709,0.241729,-0.561139,0.059709,-0.347084,0.000277,-0.400384,-0.085860,-0.280485,-0.103777,-0.597404,1.101540,-0.852720,0.522800,0.575782,0.651866,-0.509769,0.849025,0.479035,0.010629,-0.524972,0.018402,0.678540,-0.118567,-0.290554,-0.231758,0.202937,-0.114383,-0.129609,-0.518804,0.535800', '27602116', '24284209', '1870681', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20443013', '救火英雄', '动作', '平安夜，天气异常炎热，全城莫名诡谲。高负荷运转的发电站危机四伏，消防局严正以待。救火队员各自的满腹心事，让这场“硬战”充满了情感上的纠葛。何永森（谢霆锋 饰）、游邦潮（余文乐 饰）、叶志辉（安志杰 饰），三人是十年生死兄弟，如今却各怀心事：深得赏识的何永森被调离消防局，心有不甘；叶志辉玩转人际关系，升迁最快；游邦潮生性潇洒，不为人事所累，却遭遇坎坷婚姻。三兄弟间暗藏背叛的秘密更是让关系紧绷如弦。与此同时，内地超级消防员海洋（胡军 饰）前来报到，作为香港消防局“新兵”，遭遇“老兵”培总（任达华 饰）明里暗里的刁难，而他自己也有着一个解不开的心结。危机终于来临，电站爆炸大火，香港陷入前所未有的一片黑暗。更有一群人被困火海，命悬一线。消防员走进伸手不见五指的黑暗环境，对抗致命浓烟侵袭，既要救人，又要应对手足斗争，还有队里高层为保稳妥的命令不时闪现。究竟是“一命换一命，救一个算一个”还是“遵守指令，以大局为重”。这场火，不只是拯救，亦是兄弟之间的救赎，将心魔而起蒙蔽心智的浓烟挥去。', '谢霆锋', '郭子健', 7.3, 67105, 'tt3414954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2163316626.jpg', 1, 4.8, 37.8, 43, 13.3, '-0.161628,-0.057963,-0.340783,0.266247,0.246598,0.020034,0.733580,0.214835,-0.462234,-0.320048,0.491742,0.400384,-0.064770,-0.119499,-0.052482,-0.311774,-0.197641,-0.472092,-0.308321,0.102493,-0.092367,-0.282468,-0.253935,0.095302,-0.070838,-0.131704,0.722106,0.510117,-0.182323,0.218521,0.244597,0.271594,-0.242499,0.614991,0.005068,-0.376960,-0.186817,0.113764,-0.301468,-0.043387,-0.156067,-0.252053,-0.333262,0.274615,-0.107698,0.439309,0.433027,-0.027493,-0.107322,-0.102882,0.249509,-0.502592,-0.081752,0.016452,0.158671,-0.070353,-0.013927,0.132060,-0.129419,-0.012450,-0.115105,0.063989,-0.711529,0.111141,0.202054,0.076765,-0.389812,0.131477,0.016638,-0.173298,-0.000968,-0.014863,0.022978,0.192516,0.117673,0.277757,-0.382742,-0.148415,-0.386459,-0.115122,0.948848,-0.210057,-0.106175,0.063268,-0.464258,-0.349696,0.166862,-0.229315,-0.345566,-0.348468,0.196879,0.099219,0.118381,0.472057,-0.405047,0.087554,-0.128210,0.045859,-0.123008,-0.499791,0.117195,-0.421971,-0.286714,-0.151863,-0.260950,0.319576,0.202270,0.024196,0.512437,-0.603719,0.023294,0.251204,-0.096306,-0.464522,0.470929,0.307194,0.065982,-0.237978,0.128289,0.249432,-0.013139,0.184886,-0.010427,0.06467