INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20443571', '洛克王国2：圣龙的心愿', '动画', '在一个阳光明媚的日子里，龙星、奥多、法比亚等好友带领各自的宠物精灵展开对决。最终龙星和他的阿布赢得胜利，可是在他们愉快庆祝之时，阿布的双手竟然开始变得透明。担心的小伙伴们前去问询魔法学院院长格里芬，得知阿布很可能会离开龙星。能够拯救阿布的办法只有一个，那就是找到传说中的萌系精灵王。虽然前途多舛，小伙伴们还是决定试一试。在此之后，龙星、奥多以及超级罗嗦的说唱小子雷皮前去寻找精灵王的儿子乐维，小桃和法比亚则踏上另一端征途。危险的冒险全新展开，邪恶的鸡牛部队将给他们造成更多阻碍……©豆瓣', '林颖', '于胜军', 6.4, 8547, 'tt2876446', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1841216214.jpg', 11.8, 14.9, 35, 18.5, 19.7, '0.187940,0.044890,-0.538013,0.594025,-0.028041,-0.322283,0.544713,-0.072225,-0.480059,-0.154929,0.156285,0.570491,0.002811,0.250459,0.315487,-0.301277,-0.395693,-0.318381,-0.013382,0.009462,-0.241714,-0.304558,-0.338946,-0.210181,-0.022223,-0.329309,0.521957,0.044706,-0.053322,0.473554,0.357904,0.070856,-0.085992,0.417634,-0.060079,-0.057029,0.101607,-0.076007,-0.300970,0.232295,0.040539,0.227084,-0.116690,0.101732,0.343956,0.003982,0.643378,-0.638630,0.045475,-0.167757,0.246117,-0.282540,0.056744,0.124731,0.194046,0.019555,0.190964,-0.039567,0.170522,0.132006,-0.127071,-0.201395,-0.701372,0.273857,-0.012411,0.213599,-0.685262,0.065449,0.074843,-0.123369,0.315221,-0.458556,0.206616,0.448906,0.246314,0.190884,-0.149775,0.040203,-0.188457,-0.119228,0.666850,-0.234220,-0.038548,-0.120074,-0.015507,-0.537870,-0.040875,-0.068642,-0.223090,-0.050051,0.521459,0.112049,0.083865,0.266213,-0.756790,0.004087,-0.303671,-0.328543,-0.028138,-0.474003,0.061526,-0.599462,0.367204,-0.042017,-0.194772,0.320706,0.188621,-0.331946,0.867058,-0.763234,0.205301,0.294623,0.461779,-0.442982,0.396644,0.097296,0.304988,-0.251187,-0.116958,0.290701,0.076889,0.368572,0.171016,0.369075,0.076294,-0.144837,-0.268431,0.370477', '1420088', '2032339', '2053515', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20444530', '我想和你好好的', '剧情', '2006年，某广告公司文案蒋亮亮（冯绍峰 饰）和演员喵喵（倪妮 饰）相会于熙攘喧嚣的北京街头。他搭乘着从富二代车中出来后贸然坐入他车中的喵喵，与对方的兰博基尼相互飙车，看似见义勇为，却也给自己引来不小的麻烦。因工作关系，亮亮与喵喵再度相逢，二人相谈甚欢，别样的情感在彼此心底悄然升起。闹市的莫大孤独感，最终让两人走到一起。他们在北京一角同居，体会着属于两人的微妙幸福感。只是虚妄的幸福过后，裂痕在他们心间产生。亮亮号称对女性有“不主动、不拒绝、不负责”三大原则，而他和包括前女友梅梅等女性之间藕断丝连、暧昧之情也让喵喵心中滋生种种不安。这条路，他们该如何走下去……©豆瓣', '冯绍峰', '李蔚然', 6, 92432, 'tt3310600', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2153383784.jpg', 7.1, 21.1, 43.7, 19.6, 8.5, '0.608333,0.207056,-0.802350,0.614265,0.266983,-0.195625,0.644089,0.285648,-0.471958,0.206708,-0.164061,0.373007,-0.356372,0.172192,0.083389,-0.100777,-0.300092,-0.678126,-0.079878,-0.036863,-0.088724,-0.172199,-0.052169,-0.136800,-0.446729,0.234827,0.678229,0.198785,-0.125020,0.761657,0.373749,0.219920,-0.479922,0.743832,-0.077952,0.001349,0.037336,0.185579,-0.240611,0.060266,0.279678,-0.068788,-0.048910,0.103214,-0.001354,0.158214,0.617613,-0.265353,-0.206275,0.240001,-0.000171,0.134294,0.116168,0.040593,-0.011371,0.295200,0.046555,0.106970,-0.063512,0.029094,0.139165,0.280976,-0.315846,0.110358,-0.295624,0.342559,-0.258546,0.468495,-0.274656,-0.336071,0.554306,-0.390156,-0.072022,0.062850,0.445080,0.270107,-0.342064,0.184940,-0.496249,-0.370203,0.817404,0.210003,-0.004343,0.376498,-0.402038,-0.373730,0.016257,0.152354,-0.498118,-0.437548,0.356358,0.268675,-0.221073,0.238864,-0.714515,0.211878,0.201173,0.061350,-0.061678,-0.676786,0.136882,-0.524157,-0.344170,-0.751454,-0.357190,0.142711,0.368637,-0.110377,0.598523,-1.026919,0.199189,0.407666,0.301703,-0.254489,0.837452,0.095333,-0.139636,-0.107133,0.083214,-0.051485,0.007009,0.285385,0.340234,0.277012,-0.130335,0.432611,-0.250692,0.347389', '35030151', '25962735', '1308755', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20450650', '床垫里的百万欧元', '剧情', '一个古板的老太太把一生的积蓄-—一百万欧元都藏到了她的旧床垫下面，可是这个床垫却被不知情的子女们嫌太老旧，扔了。当子女们得知真相后，一石激起千层浪浪，全家开始了轰轰烈烈的找床垫行动。就在这时，子女中经常被哥哥姐姐们称为傻子的小儿子，给电台打了电话，用5万欧元悬赏里面藏有百万欧元的床垫，此时全国的人们都开始疯狂的找这张藏有百万欧元的床垫，古板的老太太也因此受邀参加电视台节目讲述床垫金额的由来。最终，在全国人都积极参与的情况下，老太太一家是否能如愿的寻回床垫呢？', '菲奥纽拉·弗拉纳根', '兰斯·戴利', 7.6, 4791, 'tt2132374', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503635977.jpg', 0.3, 2.1, 31.9, 50.4, 15.4, '0.179907,0.111381,-0.651697,0.389899,-0.480202,-0.090650,0.419675,0.189577,-0.452509,-0.074473,0.343860,0.600454,-0.174748,0.349233,-0.073751,-0.005578,-0.077734,-0.700257,-0.240220,-0.373692,-0.514324,-0.219019,-0.058804,-0.151908,-0.207675,0.032543,0.102236,0.029429,-0.036831,0.236687,0.274712,0.234074,0.329792,0.344228,-0.325920,0.139950,-0.137409,0.094954,0.254384,0.143041,-0.252253,-0.253622,-0.068493,0.112562,0.363803,0.450791,0.633301,-0.148137,0.082889,0.094433,0.399436,0.017406,-0.193629,0.352026,0.394654,0.132068,0.418530,0.130442,-0.330818,0.074451,0.342584,0.152709,-0.780589,-0.014984,-0.041412,0.017371,-0.679859,0.283454,-0.210022,0.121340,-0.256437,-0.118092,0.339476,0.343922,-0.174612,0.375249,-0.236593,0.030738,-0.743727,0.340225,0.376821,-0.188548,0.149262,0.136449,0.013102,-0.352724,0.224414,-0.337193,-0.452767,0.039799,0.378969,-0.181869,-0.016618,-0.017601,-0.788434,0.078082,-0.116218,-0.673783,0.053673,-0.408938,-0.396190,-0.405800,-0.220198,-0.063483,-0.038674,0.105662,0.350290,-0.148964,0.957046,-0.165815,-0.029492,0.387997,0.192880,-0.458408,0.639924,-0.078787,0.132307,0.400197,-0.063400,-0.465967,0.233744,0.625719,0.288551,0.221532,-0.048856,-0.257114,-0.322368,0.384268', '1302661', '4181031', '27602116', '1309101');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20451118', '致命录像带2', '惊悚', '为了寻找在派对中失踪的大学生，两名携带录像设备的私家侦探闯入了一幢空房子，并在其中发现数卷神秘录影带：1）男人米德尔顿植入了能记录影像和声音的义眼，他在家中却看到恐怖的影像；2）在国家公园丛林里骑车的麦克碰到一个满身伤痕、呕吐黑水的女人，接下来一群恐怖丧尸慢慢向他靠近。被丧尸咬了后，男子的身体渐渐发生变化；3）某剧组造访一个神秘教派，天堂般美好的表象下，恐怖气息蔓延，他们偏偏赶上魔王降临人间；4）父母不在的湖边住宅，孩子们放肆玩耍。夜深人静之际，强烈的光芒突然闪过，神秘生物进入屋内，意外频现。诡异的录影带，将观看者引向黑暗深处……©豆瓣', '凯尔西·艾博特', '西蒙·巴雷特', 7, 9201, 'tt2450186', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1950446394.jpg', 2, 8.2, 41.6, 34.3, 13.9, '0.385021,0.211546,-0.834449,0.478366,-0.077945,0.195103,1.447319,0.093865,-0.372763,-0.187934,0.443211,0.616237,-0.521566,0.249141,-0.069482,0.018898,-0.187524,-0.482122,-0.344968,-0.242058,-0.417939,0.076793,-0.451873,-0.275073,0.173147,-0.414188,0.467158,0.395856,-0.226873,0.307725,-0.045364,0.151508,-0.724902,0.537377,-0.323173,-0.359889,0.230116,-0.020437,0.112252,0.235868,-0.092960,-0.430059,-0.100146,0.068732,-0.380895,0.140375,0.859383,-0.161697,-0.063059,-0.107154,0.259355,0.070208,-0.163456,0.028213,0.376156,0.066285,0.155350,-0.111065,-0.036191,0.010527,-0.155169,-0.006725,-0.463059,0.039165,-0.095132,0.569393,-0.195289,0.163932,0.103595,-0.148371,0.274162,-0.362133,0.144074,-0.200670,0.051824,0.547441,-0.050510,0.188922,-0.287267,-0.053854,0.408291,-0.168784,-0.500535,0.327986,-0.243404,-0.388882,0.070516,0.218775,-0.255457,-0.198604,0.679134,0.199999,-0.284961,0.327427,-0.762950,0.123458,0.043244,-0.216013,-0.429207,-0.183359,-0.744328,-0.690766,-0.270470,0.132930,-0.100211,0.321442,-0.096697,0.014084,0.411367,-0.578417,0.496316,0.726771,0.357460,0.005944,0.631826,-0.506546,-0.091333,0.033645,-0.145516,0.219944,0.348827,0.564656,0.099171,0.456375,-0.601375,0.069821,-0.483314,0.454094', '10466639', '25884436', '1467779', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20451290', '新木乃伊', '动作', '埃及公主阿玛内特（索菲亚·宝特拉 Sofia Boutella 饰）和死神赛特签订了契约想要成为一统埃及的女王，哪知道计划失败，最终，阿玛内特被制作成为了木乃伊，含恨而终。一晃眼千年过去，海豹突击队队员尼克（汤姆·克鲁斯 Tom Cruise 饰）在执行任务期间意外的闯入了一座位于地底的古墓中，唤醒了阿玛内特的灵魂，重返人间的阿玛内特决定将尼克的身体作为死神赛特的灵魂容器，在这个新世界里重新实现自己称王的野心。为了阻止阿玛内特的阴谋，尼克和考古学家珍妮（安娜贝拉·沃丽丝 Annabelle Wallis 饰）联手对抗木乃伊大军，面对来势汹汹的阿玛内特，尼克能否获得最终的胜利，拯救人类呢？©豆瓣', '汤姆·克鲁斯', '艾里克斯·库兹曼', 4.8, 124806, 'tt2345759', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2459198108.jpg', 14.8, 41, 37.1, 5.5, 1.6, '0.119134,0.262026,-0.438863,0.471154,-0.013383,-0.446083,0.421879,-0.005709,-0.556750,-0.172131,0.277385,0.918667,-0.151488,-0.212553,0.271070,0.056066,-0.495554,-0.630848,0.052403,-0.238121,-0.211003,-0.442423,-0.494284,-0.143714,0.110780,-0.624549,0.742696,-0.105440,0.132998,0.143576,0.150526,0.342134,0.006481,-0.105640,0.143958,0.313179,0.303059,-0.393768,-0.340114,0.475128,-0.064913,0.376635,0.047545,0.117907,0.151066,0.104740,0.186118,-0.909837,0.417949,-0.383225,0.233842,-0.454294,0.157260,0.469061,0.094626,-0.169442,-0.033530,0.197885,-0.170869,-0.168052,0.325232,-0.232427,-0.730393,0.030848,-0.102545,0.186290,-0.441978,0.053424,-0.285178,0.345651,0.419109,-0.325290,0.039364,0.589350,0.281816,0.392355,-0.193134,0.126661,-0.426458,-0.245411,0.481395,-0.372224,-0.253082,-0.345589,-0.082697,-0.347827,-0.031868,-0.455353,-0.384541,0.009866,0.436818,0.155255,0.022206,0.514732,-0.598825,-0.330594,-0.679559,-0.151675,-0.077990,-0.335214,0.082293,-0.520317,-0.024001,0.057574,-0.089356,-0.510998,0.152986,-0.421172,0.522714,-0.704787,0.509712,0.642096,0.380009,-0.090562,0.229775,0.128983,0.372011,-0.296982,0.187645,0.436880,0.156632,0.306863,-0.052442,0.226017,0.298862,0.023345,-0.421486,0.656592', '26759819', '24750460', '3148748', '3213270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20451307', '群盗：民乱的时代', '动作', '故事发生在朝鲜李氏王朝的末年，是时世道离乱，奸孽横行，窃钩者诛，窃国者侯，百姓生活在水深火热之中。住在罗州石头（河正宇 饰）是身份低贱的屠夫，某天他受主人赵润（姜东元 饰）指示挥刀杀人。赵润系当地贵族子弟，其武艺高强，却奸猾凶狠。倒霉的是石头行动失败，更导致家人惨遭杀害。在自家生命也命悬一线的时刻，他得到了智异山贼团的营救。因豪门贵胄横征暴敛，许多不堪重负的百姓逃入深山落草为寇，更打出替天行道的旗号劫富济贫。石头与名弓马香、卢教头岱浩、刘世和尚等英雄相会，从此走上一条腥风血雨的人生路。而作恶多端的赵润等人，也将为自己的恶行付出代价……©豆瓣', '河正宇', '尹钟彬', 6.6, 11710, 'tt2972482', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189123024.jpg', 1.6, 10.8, 53.6, 25.1, 8.9, '-0.031643,-0.149214,-0.395293,0.166714,-0.034166,0.069328,0.499701,0.350938,-0.604380,-0.017794,0.477987,0.621485,-0.173551,-0.205964,-0.039950,-0.228409,-0.015716,-0.575772,-0.100900,-0.020146,-0.002620,-0.094667,-0.098945,-0.181914,-0.403893,-0.214916,0.546299,0.350466,-0.173794,0.178720,0.273629,0.226364,-0.057345,0.381257,-0.450230,0.025556,-0.256682,-0.193175,-0.340192,-0.119408,-0.243362,-0.495409,-0.436418,0.112002,-0.145522,0.175094,0.546279,-0.243177,0.012238,-0.321924,0.211976,-0.419705,-0.119105,0.131777,0.474548,-0.198574,0.020438,0.333519,-0.019791,0.117677,0.183159,-0.091011,-0.584348,-0.168410,0.089262,0.193864,-0.654929,0.358580,-0.022474,-0.051129,-0.095626,-0.323863,0.326910,0.147155,0.133917,0.055679,-0.201930,-0.234850,-0.505377,0.235028,0.765027,-0.059698,-0.007126,-0.144061,0.010792,-0.347283,0.172434,-0.321851,-0.520769,-0.196684,0.395027,-0.438380,-0.184809,0.422928,-0.341384,-0.043116,-0.363130,-0.067559,-0.025093,-0.174410,-0.270721,-0.236142,0.023686,-0.212000,-0.162046,0.207470,0.310964,-0.116142,0.623055,-0.508400,-0.040084,0.324673,0.250673,-0.649424,0.403554,-0.061485,0.160846,0.020909,-0.113130,0.282204,0.412113,0.222169,0.027956,-0.014957,-0.198627,-0.058657,-0.063233,0.334666', '25721544', '1877596', '1308035', '1306530');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20451471', '听见下雨的声音', '爱情', '下雨天，有人说是天空在哭泣，也有人说那是邂逅的天气，它是如此的浪漫，富有感情，许多故事都是从这里开始的……一个下着雨的夏末，热爱音乐的乐团“给一个说法吧”主唱阿伦（柯有伦 饰）在市集中汉服摊位遇到美丽的大学生雨婕（韩雨洁 饰），雨婕清新脱俗的气质让阿伦一眼就烙在心中，那股气息令阿伦想起那段大学时期最美丽的遗憾——Sharon（徐若瑄 饰）。阿伦和雨婕两人的感情渐渐萌芽之际，阿伦的乐团却因为唱片公司的决策使得团员间闹不愉快，雨婕想帮忙分担阿伦的压力与烦恼，却又无力可施，反而造成两人间的不快。阿伦又在此时遇到现已成为摇滚天后的Sharon，两人再次见面，回忆点滴浮现，两人情愫再度悄然而生……此时，阿伦的好友画家周以乐（释小龙 饰）将这三角关系全看在眼里。对于雨婕，他有着一份特殊情感，原来四年前……©豆瓣', '柯有伦', '方文山', 5.5, 9691, 'tt3664510', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2160379848.jpg', 10.2, 29.5, 42.5, 12.5, 5.3, '0.329485,0.057691,-0.667638,0.665045,0.128678,-0.223135,0.933994,0.214654,-0.422226,-0.235196,0.080977,0.670031,-0.333860,0.345693,0.177499,-0.171130,-0.159307,-0.660552,0.196060,-0.132957,0.114620,-0.246895,-0.230530,0.161572,-0.126995,-0.412270,0.622403,0.138422,-0.255737,0.587921,0.093252,0.295008,-0.038854,0.521064,0.002456,-0.165006,0.032191,0.290125,-0.163954,-0.093812,0.111118,-0.343439,-0.176493,0.174669,-0.039093,0.269029,0.586242,0.129076,-0.227623,0.144003,0.421210,0.050496,0.129415,-0.105114,0.272185,0.007410,0.114927,0.071935,-0.186546,-0.005816,0.038772,-0.026312,-0.575921,0.222688,0.058862,0.263212,-0.452678,0.453565,-0.050177,-0.212850,0.185647,-0.240392,0.327528,0.174194,0.295571,0.513787,-0.113539,0.151484,-0.288353,0.071864,0.722047,0.087112,-0.418360,0.636068,-0.424462,-0.333061,-0.061716,0.273369,-0.309404,0.058351,0.073629,0.117245,0.140220,0.300722,-0.769471,0.071696,0.283512,-0.093721,0.040824,-0.494848,-0.095880,-0.468260,-0.425470,-0.427765,-0.361163,0.029647,0.276343,-0.064231,0.667701,-0.747927,0.240153,0.459401,-0.100165,-0.230957,0.478768,0.175367,-0.011591,0.006812,-0.137401,0.222634,-0.404807,-0.016396,0.150607,0.486835,-0.213816,0.064204,-0.371271,0.343767', '2053515', '1296534', '20020577', '2131640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20452308', '一路顺疯', '喜剧', '章开（陈思成 饰）是医术精湛的妇产科大夫，由于长相英俊，整天流连于各种美女之间，是个标准的花心渣男。小兰（蒋梦婕 饰）是妇产科的一名俏护士，她花痴般暗恋着章开。由于女友太多，风流的章开抱着只求开心不问结果的轻浮态度，活得到也快活。美玲（刘云 饰）、印巧文（李欣汝 饰）、纪沉鱼（卫莱 饰）和廖春熙（黄小蕾 饰）都与章开有过时间长短不一的情史，但都只是章开花心生活的点缀而己。突然有一天，一封装着B超化验单的神秘邮件让章开五雷轰顶。受到惊吓的章开得了性功能障碍，在心理医生的建议下他决定去寻找孩子的妈妈。经过层层缩小范围，章开把目的地锁定在丽江。章开的弟弟章心（包贝尔 饰）是个智商只有七岁孩童大小的大男孩，他梦想着去香格里拉寻找初恋情人。在妈妈的委托下，章开带着弟弟章心踏上了去往云南的寻人旅途……©豆瓣', '陈思诚', '叶伟民', 5.2, 15152, 'tt3221936', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2098146746.jpg', 16.1, 29.4, 38.1, 11.5, 5, '0.099371,-0.129892,-0.329107,0.419331,-0.184770,-0.098842,0.593629,0.257225,-0.337041,0.018270,0.183402,0.398231,-0.112332,0.470745,0.135652,0.158005,-0.217702,-0.454539,-0.139569,-0.058343,-0.136128,-0.346611,-0.303403,0.147936,0.127652,-0.224660,0.296519,-0.265960,-0.058881,0.470646,0.394617,-0.027252,-0.017784,0.218848,-0.438943,0.009848,-0.249716,-0.028869,-0.025737,0.175773,0.345803,-0.168910,-0.050201,-0.217659,0.119139,0.332275,0.807798,-0.117655,-0.220773,0.229503,0.389160,-0.058720,0.024838,0.165561,0.038092,-0.012618,0.197395,0.039628,-0.347630,0.200306,0.431445,-0.128125,-0.383856,0.036322,0.375408,0.274765,-0.508390,0.428326,-0.244880,-0.144805,0.069730,-0.591993,0.090491,0.174430,0.043794,0.421623,-0.263214,0.154290,-0.342645,0.438750,0.341607,0.302023,-0.107677,0.323978,-0.226106,-0.395037,-0.224681,-0.075315,-0.600146,-0.014944,0.296295,-0.071215,-0.237906,0.098403,-0.567621,0.034052,-0.135508,-0.067275,-0.051945,-0.164910,-0.287812,-0.366437,0.101883,-0.393661,-0.214250,0.280980,0.175710,-0.161429,0.843644,-0.642434,0.183226,0.521500,0.226893,-0.443779,0.925853,0.175787,-0.025199,-0.046151,-0.097161,0.285433,-0.213448,0.208043,-0.059861,0.604189,-0.127817,-0.296155,-0.366089,0.266547', '1418179', '1302661', '3448362', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20452309', '床上关系', '剧情', '夜深人静，面色阴郁的小偷（王小山 饰）悄悄弄开某户人家的房门。黑暗中他实现了一系列的盗窃，还不忘享用一下主人家美酒和按摩椅。正当他兀自陶醉其中时，突然房门开启，男女主人张诚（沈腾 饰）和李小云（李昕芸 饰）回到家中。二人情欲正浓，根本不知刚好把一个小偷堵在家中。小偷打算趁夫妻俩不注意逃出去，谁知大门被二人反锁，钥匙则在张成扔在地上的外裤口袋里。当然在这一过程中男女主人状况不断，小偷只得被迫在各个房间的角落里藏来藏去。就在此时，一枚失踪的避孕套引发了夫妻二人连番争吵，夫妻间的各种不信任以及各种鸡毛蒜皮，搅坏了男女主人的雅兴，郁闷了小偷原本还算不错的心情……©豆瓣', '王小山', '张元', 6.3, 5756, 'A Bed Affair', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2170236261.jpg', 4.9, 15.6, 47, 25, 7.5, '0.722167,0.224317,-0.705260,0.078326,-0.050304,-0.258394,0.845549,0.060168,-0.378084,-0.229855,0.221507,0.403065,-0.370663,0.172437,0.196603,0.086139,-0.444234,-0.599324,-0.222248,-0.107609,-0.399084,-0.174615,-0.314682,-0.103916,-0.305662,0.075574,0.239926,0.002558,-0.210885,0.299454,0.054061,0.028141,-0.587700,0.588528,-0.256316,0.283168,0.147382,0.001655,0.052526,-0.168762,-0.111133,-0.549049,-0.215549,0.029808,0.189332,0.345997,0.631768,-0.299744,-0.121043,0.172849,0.128822,0.113791,-0.338961,0.201927,0.331418,-0.039998,0.295301,-0.047868,-0.320330,0.312088,0.358993,-0.044068,-0.233586,-0.013884,-0.122637,0.053440,-0.434305,0.450468,-0.190433,-0.112198,0.271936,-0.305261,0.330675,0.227609,0.011676,0.446978,-0.230709,-0.241571,-0.800184,0.066358,0.096614,-0.104382,0.352371,0.541931,0.059489,-0.284409,0.022492,0.264322,-0.424782,-0.503328,0.707096,0.234450,-0.292301,-0.112502,-0.368037,0.043789,0.000490,-0.052616,-0.068368,-0.337059,-0.273706,-0.564806,-0.188633,-0.106395,-0.253285,0.233608,0.033371,0.072255,0.236705,-0.557496,0.036568,0.234750,-0.016437,-0.055648,0.528804,-0.096447,0.383240,0.081284,-0.288120,-0.364862,0.317977,0.298186,0.378590,0.673804,-0.153526,-0.014267,-0.289070,0.057360', '1306670', '1394470', '1394176', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2045259', '男才女貌', '爱情', '在云南古城的清晨，几个年轻人开始了他们一天的生活：交警杨乐（余文乐 饰）在执勤时爱上了接送孩子们的幼儿园聋哑教师秦小悠（高圆圆 饰）；中日混血的大学生福田诚（铃木仁 饰）进入某剧组，为日本明星水野裕子（三宅尚子 饰）担任翻译助理。杨乐拜托表哥查问到了秦小悠的情况，并在小悠因身患绝症返回家乡时一路追随；福田诚受色咪咪的剧组男主角拖累，遭到水野裕子误会，然而他靠诚挚终于打动了后者。杨乐与小悠陷入爱河，二人有了爱情的结晶，然而此时小悠的病情恶化……另一方面，水野裕子完成拍摄，即将返回日本。杨乐与小悠，福田和水野，四个年轻人站到了各自的爱情路口……©豆瓣', '余文乐', '马楚成', 6.4, 16962, 'tt0944223', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2456412063.jpg', 2.6, 11.9, 53.9, 24.1, 7.5, '0.251010,-0.026854,-0.502711,0.084927,-0.100869,-0.482065,0.360263,0.385956,-0.380979,-0.209111,0.261779,0.463015,-0.237414,0.438309,0.488478,-0.096728,-0.432709,-0.579247,-0.005549,-0.083676,-0.211851,-0.244493,0.185648,-0.201378,-0.205421,-0.116670,0.684968,0.128089,0.000359,0.445603,0.156615,0.307224,-0.316705,0.272412,-0.006369,0.243459,0.242963,-0.087490,-0.248370,0.261728,-0.119596,-0.202371,-0.368567,-0.019796,0.135932,0.264004,0.773708,0.002154,-0.217717,-0.045833,0.232934,-0.281513,-0.236657,0.040794,0.253624,-0.023541,0.041627,0.146754,-0.144222,0.210494,-0.126753,-0.027629,-0.174245,0.066051,-0.127941,0.119094,-0.457494,0.448319,0.081344,-0.299977,0.355371,-0.397958,0.048236,0.410334,-0.053931,0.226048,-0.229742,0.063985,-0.225015,0.265024,0.596011,0.128130,-0.013605,0.425485,0.066856,-0.425900,-0.143231,0.169295,-0.413556,0.102069,0.276037,-0.045341,-0.152815,-0.163165,-0.485784,-0.178285,-0.107215,-0.178936,0.063520,-0.273555,-0.055825,-0.865133,0.045440,-0.436454,-0.242410,0.075504,0.075529,-0.024989,0.882493,-0.751550,0.044176,0.389290,0.098431,-0.469775,0.546014,0.000196,-0.013210,-0.371792,0.076441,0.078674,0.012369,0.389447,0.149620,0.227694,-0.446649,0.177370,-0.425440,0.059926', '5403927', '3811356', '25922902', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20453087', 'IT狂人特别篇', '喜剧', '曾卷起一股英式幽默风潮的情景喜剧《IT狂人》，在阔别观众2年多之后再度袭来！距第四季完结至今，观众们始终翘首以盼，尽管导演表示不再制作第五季，但他还是重新启动了剧集，推出了本特别篇，“还给观众一个结尾”。Moss，Roy和Jen，位于公司地下室的IT部门三狂人，这次又会遭遇怎么样的爆笑故事？本特别篇依然围绕着IT部三人展开：Roy恋上了七楼一个姑娘，但是很快，他发现自己似乎有情感缺陷，恋情因此摇摇欲坠；与此同时，Moss也发现自己不够自信，在老板Douglas的建议下，他跑去女装店买了一条女式长裤。随后，一个大麻烦找上了Jen和Roy，这个飞来横祸不仅影响了他们个人，更是危及公司的声誉，Jen和Roy面临着被解雇的危险……©豆瓣', '克里斯·奥多德', '格雷厄姆·莱恩汉', 9.2, 21547, 'tt3221116', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2183667933.jpg', 0.1, 0.6, 6.4, 23.2, 69.7, '0.167283,0.205175,-0.599381,0.349957,0.175267,-0.129173,0.632787,0.241222,-0.367624,-0.219218,0.065841,0.736217,-0.338790,0.168981,0.340990,-0.085715,-0.245557,-0.399042,-0.070070,-0.200827,-0.216672,-0.240716,-0.217692,-0.143871,0.048421,-0.214379,0.353239,0.177592,-0.494583,0.463967,0.438694,0.095392,0.043673,0.756414,0.171642,0.036259,0.063285,0.131706,0.113344,0.436243,0.093275,-0.497807,-0.075241,0.158899,-0.087754,0.501174,0.493659,-0.079834,-0.385082,0.037126,0.643452,-0.086743,-0.144834,-0.052365,0.223263,0.012111,0.255487,0.098549,-0.179003,-0.012464,-0.034562,-0.265169,-0.551239,0.044091,-0.027253,0.036202,-0.573411,0.365489,-0.166757,0.057872,-0.115605,-0.315056,0.064032,0.262589,0.367304,0.139072,-0.286281,0.241538,-0.505443,0.148751,0.729734,0.107284,-0.191415,0.231848,-0.004166,-0.307382,-0.282372,-0.049462,-0.307590,-0.103216,0.398044,0.152376,-0.001292,-0.128754,-0.721882,0.142397,-0.004993,-0.332005,-0.049097,-0.335553,-0.031519,-0.438953,-0.097371,-0.233413,-0.131827,-0.037010,0.033408,-0.262856,0.726633,-0.525745,0.161679,0.396480,0.371854,-0.478402,0.643895,0.035637,0.044737,0.048268,-0.169374,-0.048243,-0.210292,0.468014,0.418638,0.344218,-0.058722,-0.515542,-0.236914,0.308479', '30162520', '1361252', '25908042', '27060077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2045321', '结婚证书', '喜剧', '本·墨菲（约翰·克劳辛斯基 John Krasinski 饰）和莎蒂·琼斯（曼蒂·穆尔 Mandy Moore 饰）是一对彼此深爱对方的情侣，他们的爱情充满浪漫和温馨，顺理成章两人也即将走入婚礼殿堂。莎蒂希望在与她的家族渊源颇深的圣•奥古斯汀教堂举行婚礼，但是这恐怕是一个糟糕的决定。这间教堂的弗兰克牧师（罗宾·威廉姆斯 Robin Williams 饰）看似和蔼可亲，却是个极为苛刻和奇怪的家伙。他对年轻男女贸然进入婚姻又选择逃避感到痛心疾首，因此弗兰克坚持任何一对来他的教堂举行婚礼的情侣都要接受婚前准备课程。未能通过该课程的情侣，弗兰克将有权取消婚礼。看似只是例行的公事，却发现实行起来障碍重重。感情一向顺风顺水的本和莎蒂，将迎来走入教堂前的最大挑战……©豆瓣', '罗宾·威廉姆斯', '肯·卡皮斯', 6.6, 5401, 'tt0762114', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1277375977.jpg', 1.9, 9.3, 54, 27.5, 7.3, '0.406262,0.063961,-0.681837,0.580858,0.074195,-0.106320,0.965500,0.118595,-0.279624,-0.239250,0.354327,0.781805,-0.318260,0.105829,0.628544,-0.073003,-0.348907,-0.604425,0.041126,-0.052173,-0.082204,-0.610568,0.091662,-0.207729,-0.068033,-0.195904,0.708830,0.181737,0.016163,0.539641,0.418038,0.139832,0.030981,0.378593,0.024616,-0.273185,0.172010,0.231951,-0.401453,-0.050793,0.037583,0.257713,-0.196998,0.363933,0.136514,0.263572,0.315714,-0.301768,-0.278351,0.100625,0.365126,-0.215543,-0.113101,0.428238,0.153014,-0.063060,0.044857,0.402325,0.010627,-0.116367,0.016576,-0.290825,-0.642502,0.265767,-0.057419,0.018179,-0.550690,0.672778,0.025500,-0.018070,0.042852,-0.205097,0.024570,0.482452,0.421689,0.183803,-0.166828,0.032926,-0.528704,-0.097247,0.699459,0.146663,-0.265419,0.329897,-0.456240,-0.510791,0.035283,-0.088882,-0.482069,-0.075091,0.182796,-0.052452,0.106108,0.139047,-0.506754,-0.188677,-0.242522,-0.166910,0.124193,-0.683609,0.104633,-0.909689,0.061394,-0.491550,-0.617507,-0.036138,0.042639,-0.290200,0.517850,-1.000874,0.309754,0.395122,0.356178,-0.354027,0.878476,0.361932,0.474494,-0.276331,-0.435275,0.314153,-0.213754,0.085772,-0.113045,0.466114,0.209893,-0.003306,-0.271173,0.474559', '1301686', '1302384', '3055049', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20458867', '新世纪福音战士剧场版：复兴', '剧情', '《REVIVAL》的第一部分：「DEATH (TRUE)2」原先是作為《死與新生》的一部分推出。其中《死與新生》分為兩個部分：「DEATH」篇和「REBIRTH」篇。「DEATH」篇是60分鐘的電視動畫修正版，包括了重新製作的鏡頭和一些新鏡頭。「REVIVAL」所採用的版本，稱為「DEATH (TRUE)2」，是對「DEATH」的重新剪輯，去除《死與新生》的「DEATH」篇中的新鏡頭並且作一些小修改。作品的第二部分「REBIRTH」包括了《THE END OF EVANGELION》的第一部分，因此是《THE END OF EVANGELION》早期未完成的版本。《REVIVAL》的第二部分“Air/まごころ、君に”，即為劇場版「THE END OF EVANGELION」。影片从未以它完整的剧场版形式通过DVD和VHS推出。取而代之的是《THE END OF EVANGELION》和《死与新生》分别发售。其中《死与新生》容纳了“DEATH”的“DEATH (TRUE)2”版。', '绪方惠美', '庵野秀明', 9.4, 7551, 'tt13645944', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2227584460.jpg', 0.6, 0.5, 4.4, 19, 75.4, '0.400177,0.052034,-0.558894,0.906137,-0.072014,-0.106081,0.636184,-0.300474,-0.380710,-0.176452,-0.245259,0.924669,-0.163998,0.550026,-0.033986,-0.247795,-0.001345,-0.635005,-0.512723,-0.296769,-0.611428,-0.760638,-0.370337,0.267846,-0.213314,-0.666554,1.438801,0.192649,-0.361743,0.142149,0.299188,0.300115,-0.151298,-0.056029,-0.219083,0.139961,-0.242766,-0.276758,-0.169427,0.363970,0.043720,-0.449612,-0.062583,-0.062766,-0.199799,0.621040,1.196055,-0.527339,-0.078958,-0.001511,1.026770,-0.261956,-0.665496,0.000211,0.166503,0.155146,0.667226,0.510578,-0.325021,0.301773,0.055347,-0.281285,-1.366361,-0.521312,0.533628,0.184313,-0.634946,0.565435,-0.233582,0.026598,0.226396,-0.212802,0.614412,0.543593,0.106920,0.679161,-0.016113,-0.330136,-0.482512,0.367869,0.442180,0.122405,-0.626212,0.317002,0.223053,-0.468833,-0.321240,-0.525813,0.379906,0.376173,0.389098,0.572785,0.103355,0.181696,-1.011042,0.076783,-0.146536,-0.726955,0.148042,-0.425790,0.043690,-0.854853,0.007126,-0.265208,0.150567,-0.122593,0.663184,-0.653404,1.245957,-0.906023,0.296808,-0.091855,0.212453,-0.651521,0.733708,0.190378,0.440129,-0.190748,0.209922,-0.436969,0.160502,0.152799,0.356470,0.691889,0.089126,-0.411084,-0.851230,0.620226', '26759820', '25880986', '27602116', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2046839', '有关时间旅行的热门问题', '喜剧', '游乐园工作的雷（克里斯•奥多德 Chris O’Dowd 饰）沉迷于时间旅行，在工作中因吓坏小游客而被解雇。朋友皮特（迪恩•里浓斯•凯利 Dean Lennox Kelly 饰）和业余作家托比（马克•伍顿 Marc Wootton 饰）在“恐龙汉堡店”扮恐龙打工，毫无前途。三人晚上来到酒吧打发时光，雷突然遇到一位叫凯西的美女（安娜•法瑞丝 Anna Faris 饰）。凯西自称来自未来，是专门负责寻找时间漏洞的技术员，她来此是拜访名人，因为雷在未来将是“伟大的雷”，并著有《时间旅行手册》。皮特和托比不相信雷遇见了“未来美女”，认为他是异想天开编排电影。皮特去卫生间小解，没曾想竟偶然进入了时间漏洞，出来后发现酒吧全是死人，包括他自己。惊慌四措的皮特将雷和托比也拽入了漏洞，从此开始了一系列前后穿梭的时间旅行冒险。©豆瓣', '克里斯·奥多德', '嘉瑞斯·贾里维克', 7.8, 46409, 'tt0910554', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2184071213.jpg', 0.5, 2.8, 25, 49.2, 22.5, '0.104532,-0.070588,-0.472177,0.178406,0.066862,-0.205081,0.626183,0.031740,-0.571507,-0.549241,-0.253225,0.413499,-0.279762,0.274654,0.532989,-0.042786,-0.597450,-0.584517,-0.068061,-0.099384,-0.489993,-0.346585,0.018261,-0.488338,0.141213,-0.397928,0.085794,0.032005,-0.287284,0.288301,0.250998,0.298531,-0.282724,0.466663,-0.173807,0.176984,0.326260,0.052031,-0.033915,0.187910,0.152828,-0.137158,-0.270136,-0.167066,0.439147,0.430998,0.388219,0.036071,-0.170775,-0.093746,0.195079,-0.198673,0.070155,-0.287288,0.204488,-0.231471,0.297057,-0.021712,0.061974,0.160561,0.225517,-0.403825,-0.665837,0.376451,-0.111063,0.072172,-0.516152,0.254090,-0.062114,-0.057863,0.012737,-0.244315,0.105801,0.160785,0.327088,0.000946,0.162354,0.145973,-0.510113,0.363563,0.524034,-0.155194,-0.018991,0.419349,-0.083757,-0.230311,-0.178414,0.076529,-0.297969,0.056495,0.409156,0.005574,-0.136974,0.122781,-0.522019,-0.156713,-0.230988,-0.280114,0.119427,-0.157073,-0.309175,-0.736042,0.276069,-0.100019,-0.221547,0.040704,-0.018937,-0.142149,0.498991,-0.809861,0.083595,0.499680,0.301955,-0.443555,1.192201,-0.200258,-0.066704,-0.297881,0.355416,0.058472,0.296169,0.194951,0.310094,0.324188,0.144095,-0.250796,-0.256705,0.317699', '3055049', '1306860', '1302384', '2052978');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20470074', '言叶之庭', '爱情', '年方15岁的高中生秋月孝雄（入野自由 配音），专心学业的过程中不得不为了生计打工赚钱。母亲离家出走，他与哥哥过着看不到前方的生活。入梅之日，孝雄逃课来到日本庭园。在一座安静的小亭子里，27岁的职场女性雪野百香里（花泽香菜 配音）边吃巧克力边饮啤酒的样子引起了孝雄的注意。似曾相识的二人，仿佛约定好了一般，每到落雨之日便从世俗的烦恼中逃脱出来，相会于这座钢筋铁骨都市丛林中宛若世外桃源的幽静角落。在梅雨季节的日子里，他们的心渐渐向彼此靠拢。志愿成为手工鞋匠的秋月，决心以雪野为模特做一双鞋。雨过天晴，艳阳高照，庭园中久久不见秋月和雪野的身影，相会无期亦有期……©豆瓣', '入野自由', '新海诚', 8.3, 302158, 'tt2591814', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1958733032.jpg', 0.3, 1.8, 17.5, 43.1, 37.3, '0.227989,-0.048002,-0.526502,0.334710,-0.156622,-0.363442,0.781971,0.292539,-0.335933,-0.061212,0.082970,0.570175,-0.008363,0.495372,0.339926,-0.033298,-0.402674,-0.725023,-0.157714,-0.333740,0.009512,-0.131705,-0.225371,0.194170,-0.180536,0.064662,0.502949,0.107254,0.167772,0.516406,-0.118539,-0.291804,-0.322080,0.268723,-0.146312,-0.174003,-0.021330,0.031296,-0.310602,0.303345,-0.281444,-0.300783,-0.385751,-0.138780,0.174004,0.242160,0.824663,-0.376227,-0.133596,-0.216293,0.323515,0.071732,-0.082302,0.318240,0.241335,0.046030,0.249361,-0.035463,-0.276120,0.247275,-0.158830,-0.397777,0.053538,0.019992,0.057506,0.403735,-0.199163,0.542631,0.126759,-0.280858,0.330040,-0.454760,0.202812,-0.210042,0.252149,0.587611,-0.448089,0.203084,-0.406553,0.148951,0.476715,0.282578,-0.064782,0.346525,-0.051858,-0.306935,0.172391,-0.001459,-0.441261,-0.367152,0.018166,0.126948,-0.160992,0.234185,-0.652136,0.387789,0.121781,-0.208934,-0.038399,0.009297,-0.512078,-0.577050,0.130387,-0.500788,-0.172880,0.266267,0.067111,-0.215936,0.499531,-0.599518,0.382608,0.304050,0.182648,0.242086,0.648539,-0.220835,0.411973,0.168445,0.013266,0.333110,-0.400214,0.599599,-0.050968,0.443150,-0.279104,0.096462,-0.560433,0.254375', '1467779', '24839498', '21619567', '5279593');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20470260', '少年收容所', '剧情', '一个专门收容被大人殴打、虐待的孩子的收容所里的故事。 影片讲述了一个照看寄养中心孩子的年轻女人的故事，除了要面对孩子们所可能发生的危险事件之外，她还要面对自己的心魔。', '布丽·拉尔森', '德斯汀·克里顿', 7.8, 6870, 'tt2370248', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2003326228.jpg', 0.4, 2.4, 26.2, 49.7, 21.2, '0.197277,-0.449766,-0.561866,0.526756,-0.297017,0.306513,1.028527,-0.047448,-0.578466,-0.495845,0.355469,0.715610,0.097919,0.659084,0.107026,-0.049203,0.029894,-0.683649,-0.445684,0.083379,-0.503853,-0.311970,-0.403020,-0.597498,-0.027884,-0.429268,0.165871,-0.071206,-0.135240,-0.205946,0.314268,0.338126,-0.326756,0.072223,-0.243986,-0.117935,-0.085974,0.094415,0.038850,0.098857,-0.150967,-0.043637,0.077038,0.096856,-0.060382,0.304434,0.946402,-0.454711,-0.260757,-0.551008,0.400226,-0.224900,-0.020520,0.342310,0.173865,-0.031445,0.724606,0.431685,-0.157238,0.010314,-0.016859,-0.434068,-0.783511,0.096804,0.273126,0.239297,-0.666422,0.055474,0.334501,0.415100,0.304705,-0.199856,0.389003,0.025347,0.288755,1.010269,-0.414407,0.101352,-0.147360,0.176167,0.844904,-0.507911,-0.158595,0.223323,-0.149945,-0.034461,0.052523,-0.432336,-0.799324,0.500921,-0.047881,-0.122100,-0.541159,0.549022,-0.356520,-0.096111,-0.378779,-0.230318,-0.149382,-0.359317,-0.320949,-0.357688,0.185946,-0.078562,-0.257223,0.148054,0.352766,-0.120086,1.129747,-0.586918,0.395595,0.743730,0.257276,-1.275867,0.614391,0.347787,0.365538,-0.149282,-0.162438,0.349637,0.138797,-0.040833,-0.432785,0.247629,-0.221756,-0.310870,-0.393166,0.288252', '3179758', '24879820', '25882279', '26348103');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20470369', '有钱男与贫穷女：纽约篇', '剧情', '经历了一番波折，拥有天才一般头脑的日向彻（小栗旬 饰）终于带着新创公司（Next Innovation）进入全新的发展时期，而他和夏井真琴（石原里美 饰）也开始了一段日本-美国的跨洋之恋。日向再接再厉，决定退出“橱柜”新企划，结果招致属下一直反对，更因试图召回不久前出狱的旧友朝比奈恒介（井浦新 饰）而令公司股票大跌。与此同时，真琴返回日本，她和日向终于开始在同一屋檐下生活，无奈这名完美男友似乎习惯了一个人的日子，两人的相处渐入瓶颈。前进道路上最大的挑战，日向、真琴以及朝比奈这群充满活力的年轻人，能否勇敢迈过？本片为同名电视剧的SP作品。©豆瓣', '小栗旬', '西村正記', 7.6, 21730, 'tt2605312', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1905777244.jpg', 0.6, 3.5, 32.1, 42.2, 21.7, '0.074482,0.175749,-0.448740,0.512603,0.220482,-0.365139,0.360036,0.138066,-0.505497,-0.297937,0.081276,0.561352,-0.174386,0.257563,0.392982,-0.153051,-0.410429,-0.659192,0.069796,-0.148051,-0.216418,-0.030743,-0.309307,-0.111234,-0.217933,-0.155222,0.889068,0.233345,-0.198195,0.507721,0.326100,0.259499,-0.076100,0.166791,-0.006126,-0.037851,0.140604,0.150978,-0.404421,0.325240,-0.158135,-0.322996,-0.289356,0.099594,-0.012663,0.292741,0.553033,-0.215693,-0.276794,-0.179491,0.467587,-0.188233,-0.236792,0.193211,0.330186,0.353801,0.156787,0.290177,-0.132740,0.193906,-0.141995,-0.262952,-0.594518,0.082786,0.062768,0.030252,-0.323497,0.200940,0.017207,-0.043389,0.260883,-0.353674,-0.288076,0.502836,0.514633,0.331703,-0.306721,0.263463,-0.014125,0.066351,0.587598,0.066539,-0.110134,0.273851,0.058250,-0.359311,-0.222201,-0.207291,-0.375536,-0.195606,0.077840,0.142544,-0.050539,0.274535,-0.706924,0.234179,-0.198404,-0.187905,0.206896,-0.190421,0.090680,-0.782941,0.026561,-0.431160,-0.356268,0.061825,-0.025555,-0.328569,0.904870,-0.594509,0.013382,0.396097,0.403886,-0.408598,0.508421,0.083157,0.064552,-0.313286,0.166150,0.373178,-0.164572,0.304924,-0.087688,0.257769,-0.177804,-0.037698,-0.574953,0.356539', '3811356', '5403927', '2369613', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20471829', '晚娘2012(下)', '情色', '几年后，真接到继母的召唤，父亲要求他回家与已经怀有身孕，同父异母的妹妹乔(西野翔)成亲！百般惊讶的真在父亲答应他成为家族的主人后，回到家中。在逐步揭开自已身世的过程中，真似乎同时回到一个难以逃离的情欲轮回！', '马里奥·毛瑞尔', 'M·L·蓬德菲尼普·杜瓦库', 5.5, 6623, 'tt2670454', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1843926565.jpg', 8.9, 30.7, 42.7, 12.2, 5.5, '-0.139314,0.372201,-0.971418,0.692981,-0.522844,-0.637584,0.496347,-0.231017,-0.806116,-0.757436,0.031683,0.809731,0.013832,0.898382,0.118853,-0.283712,-0.208809,-0.530020,0.153792,-0.433186,-0.350954,-0.541898,0.200379,-0.006851,0.218931,-0.542240,0.824706,0.073569,-0.076369,0.063639,-0.078656,0.375259,-0.367888,0.557520,-0.574642,0.443397,-0.221499,0.400133,-0.536837,0.376487,0.392097,-0.028664,-0.042514,0.093211,0.228797,0.200260,0.589300,-0.497230,-0.288204,-0.306474,0.563738,-0.139577,-0.034003,0.276455,0.280470,0.074190,0.334507,0.217358,-0.604291,0.045322,-0.082456,-0.289433,-0.518171,0.067902,0.001652,-0.285071,-0.703677,0.014110,-0.102917,0.152472,0.088449,-0.431431,0.212550,0.871355,-0.049078,0.644833,-0.624254,0.498456,-0.695584,-0.274544,0.858552,-0.118302,0.173415,0.346945,0.395164,-0.234458,0.085785,-0.010101,-0.515698,0.057433,0.450413,0.487725,-0.090423,0.293547,-0.204951,-0.476177,-0.259365,0.106693,0.467307,-0.467823,-0.092405,-0.050722,-0.050071,-0.140412,-0.305843,-0.112132,0.104640,-0.560858,0.337690,-0.975706,0.575812,-0.208723,0.316117,-1.046212,0.290147,0.231157,0.306647,-0.363863,-0.002641,0.561315,0.089820,-0.074277,0.161390,-0.010026,-0.245637,0.113783,-0.482501,0.325881', '1303485', '6890343', '2122766', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20471852', '生化危机：终章', '动作', '爱丽丝（米拉·乔沃维奇 Milla Jovovich 饰）在华盛顿特区被威斯克背叛后身陷险境，人类几乎要失去最后的希望。作为唯一的幸存者，也是人类对抗僵尸大军的最后防线，爱丽丝必须回到噩梦开始的地方——浣熊市，才能完成拯救世界救赎人类的正义使命。回归故事发生的起点浣熊市，爱丽丝将和昔日的朋友一起对抗僵尸和最新变种怪物，与 保护伞公司展开了一场惊心动魄的终极决战。', '米拉·乔沃维奇', '保罗·安德森', 6.5, 248810, 'tt2592614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2429713841.jpg', 2.8, 13.5, 48.7, 26.5, 8.5, '0.086178,0.204851,-0.428132,0.427434,0.184023,-0.165800,0.599721,-0.029974,-0.275079,-0.092179,0.235533,0.798809,0.116747,-0.013953,0.373896,-0.185536,-0.361262,-0.773953,-0.122344,-0.107188,-0.374714,-0.291543,-0.455604,-0.352622,0.176751,-0.358991,1.150284,0.278792,-0.101419,0.061552,0.227605,0.367569,-0.373091,0.205469,0.034832,-0.157407,0.185185,0.042934,-0.918124,0.431843,-0.066556,0.268953,0.011845,0.482750,-0.090209,-0.268381,0.669549,-0.727124,0.093238,-0.625962,0.119275,-0.359421,-0.034700,-0.016255,0.413605,-0.169824,0.197139,0.365972,0.249797,-0.179503,0.226736,-0.180186,-1.085950,-0.060825,0.204235,0.103877,-0.336643,0.343398,-0.055306,0.418379,0.475645,-0.119822,0.294296,0.847800,0.718112,0.364241,-0.195865,0.057629,-0.568481,-0.000649,0.849555,-0.280907,-0.360333,-0.118612,-0.078960,-0.400901,-0.210995,-0.508763,-0.286439,0.152762,0.073114,0.280068,-0.254837,0.595946,-1.063601,-0.299409,-0.433026,-0.313266,0.098952,-0.476229,-0.014613,-0.588311,-0.096859,0.125307,0.131097,0.124679,0.084271,-0.345570,0.726801,-0.917395,0.329444,0.767560,0.481714,-0.397004,0.590539,0.030942,0.461559,-0.684473,0.422044,0.637019,0.028355,0.552639,0.111859,-0.120030,-0.090603,0.208030,-0.300760,0.722941', '26759819', '25827286', '35377026', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20472738', '234说爱你', '爱情', '简沛熏（林依晨 饰）刚刚走出校园走进社会，满心以为自己能够凭借努力和智慧打拼出一片属于自己的天空，哪知道却因为没有后台而连面试的机会都得不到。接踵而至的失败和挫折令简沛熏心灰意冷，唯有男友阿泽（简宏霖 饰）成为了她心灵获得温暖的最后的港湾。然而，就连这个港湾也即将离她而去了，阿泽应征入伍，即将开启为期数年的军旅生涯，这也就意味着两人在未来的几年里只能遥遥相望，做一对甜蜜又苦涩的远距离情侣。在简沛熏最脆弱和无助的时候，一个名为李曜（秦昊 饰）的男人出现在了她的身边，李曜是一名珠宝设计师，成熟稳重的他带给了简沛熏不一样的感觉。©豆瓣', '秦昊', '张玮真', 6, 10720, 'tt5161762', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2381990888.jpg', 4.7, 20.5, 48.2, 22.1, 4.6, '0.028179,0.286898,-0.866806,0.685938,-0.303647,-0.388672,0.865580,0.139922,-0.215239,-0.150911,0.199686,0.760733,-0.047160,0.369355,0.285088,0.084950,0.088661,-0.723407,-0.149146,-0.311593,-0.330518,-0.092872,-0.328639,-0.098531,-0.083099,-0.324692,0.926109,0.259390,-0.120646,0.287468,0.431440,0.086167,0.146134,0.606989,-0.358661,0.019767,0.035909,0.216775,-0.141117,0.165293,0.136943,-0.253024,-0.187768,0.231331,-0.148727,0.297111,0.494608,-0.269527,-0.263619,0.026863,0.386782,-0.204353,-0.188252,0.204984,0.087495,-0.110107,0.212941,-0.045910,-0.256888,0.165579,0.179069,0.099957,-0.923670,0.025250,-0.077206,0.080592,-0.591475,0.529414,0.162926,-0.245727,0.290920,-0.371278,0.387803,0.213121,0.147885,0.561456,-0.312606,0.011159,-0.586251,0.252770,0.741161,-0.139694,-0.267124,0.696009,-0.496395,-0.363276,0.008211,-0.250860,-0.567260,-0.142482,0.106587,0.225404,-0.235243,-0.035961,-0.516845,0.359059,0.005056,-0.141487,0.045295,-0.432660,-0.030188,-0.395624,-0.273469,-0.606907,-0.465993,0.212263,-0.112689,-0.495374,0.617395,-0.995602,0.212715,0.509064,0.190998,-0.386250,0.840763,0.189026,0.054535,-0.109796,0.129277,0.309522,-0.182676,0.358197,0.216428,0.548808,-0.150424,0.015662,-0.380107,0.677357', '24756472', '3230462', '1304641', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20472818', '诡镇', '剧情', '容颜憔悴的女作家路云（何超仪 饰）为了撰写最新的小说精疲力竭，她发现自己的记忆变差，许多时候依靠药物来稳定自己的精神状态。近一段时间，路云的情况似乎有所恶化，她经常被一个诡异梦境所困扰，为此几近崩溃。这日一早，噩梦醒来的路云打电话给在外地公干的老公张世权（谢承均 饰），丈夫给她以安慰，并告知当天搭乘飞机回家。而电话的另一头，张世权刚和另一位女子刘伶结束缠绵。在出版社和编辑洽谈时候，路云惊悉丈夫的飞机失事的噩耗。她匆匆赶往事故处理现场，结果偶遇刘伶的丈夫韩斌（夏凡 饰）。韩斌从妻子的遗物中发现陌生男人的手机，她千方百计试图弄清妻子生前的秘密。通过手机卡，韩斌和路云建立联系，他们也将携手揭开另一半可以隐藏的秘密……©豆瓣', '何超仪', '钱人豪', 3.5, 9740, 'tt4253170', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2164598290.jpg', 56.1, 24.2, 12.4, 3.1, 4.2, '0.036156,0.242671,-0.560440,0.435373,0.019146,-0.167181,0.521999,0.138191,-0.579271,-0.654587,0.003603,0.652631,0.009582,0.515340,0.313148,-0.104317,-0.523982,-0.657240,0.273769,0.083550,-0.474181,-0.357610,-0.169423,-0.236094,0.073817,-0.216634,0.342079,0.071621,-0.300785,0.435341,0.071976,0.091191,-0.411180,0.767540,-0.049710,0.048807,-0.046537,0.172745,-0.240040,0.190324,0.286487,-0.477789,-0.147153,0.322313,-0.072905,0.649013,0.668636,0.063787,-0.342901,0.077313,0.379393,-0.047298,0.002661,0.048481,0.220469,0.279002,0.068368,-0.060599,-0.623490,-0.074955,-0.078360,0.083773,-0.441201,0.019791,0.016080,0.026369,-0.141546,0.270896,-0.309768,0.320922,0.283304,-0.630818,0.280298,0.496450,0.043896,0.420048,-0.177742,0.105020,-0.427036,0.356371,0.379010,0.140313,0.179810,0.521380,-0.011424,-0.278805,-0.017706,0.012498,-0.346176,0.194572,0.532061,0.134620,-0.381674,-0.056844,-0.395005,-0.205631,-0.364333,-0.089721,-0.215558,-0.258761,-0.281071,-0.568528,-0.029209,0.010124,-0.047263,0.092510,0.016649,-0.310162,0.416700,-0.499517,0.356715,0.564635,0.051375,-0.575714,0.360157,-0.080003,0.005351,-0.459550,0.134438,0.339757,0.156732,0.286824,0.000818,-0.036798,-0.231057,0.182019,-0.595993,0.373044', '6722888', '1309194', '2364838', '3632506');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20472857', '百星酒店', '喜剧', '百星酒店是一间位于千岛湖的五星级酒店，但酒店中的工作人员都只有四星酒店的工作经验。这些员工中有想当经理的副经理包定（郑中基 饰），觉得自己是明星胚子的餐饮主管兼酒保彭俊（杜汶泽 饰），对待工作严谨苛刻的客房部主管桃姐（吴君如 饰），一心要嫁有钱人的前台嘉美（盛君 饰）。收到会有神秘评级员前来对酒店进行评级的消息，担心被降到四星的集团把炒人不贬眼的经理古黛（毛舜筠 饰）空降到了百星酒店，以促进服务。一个电影剧组来到酒店取景，剧组两大女主角凌梦露（吴千语 饰）和柯夏萍（熊黛林 饰）入住酒店，提出各种无理要求令员工们疲于奔命。与此同时，富商的千金宝宝（薛凯琪 饰）为了顺利继承遗产，决定在百星酒店举办一次假婚礼。包定找来新上任的英俊的保安主任雷劲（于波 饰）假扮新郎，而宝宝的舅舅志强（黄百鸣 饰）企图阻止婚礼、夺走遗产……©豆瓣', '郑中基', '谷德昭', 5.7, 21903, 'tt2876102', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2170923277.jpg', 7.2, 23.5, 51.1, 14.2, 4.1, '0.151237,0.115913,-0.395456,0.286532,-0.167163,-0.029096,0.275510,0.669886,-0.390421,-0.375495,0.506423,0.740461,-0.166069,0.237862,0.549488,0.118995,0.071453,-0.327743,-0.189859,-0.192516,0.002674,-0.354055,-0.038929,-0.122425,0.053311,-0.013073,0.253040,-0.136342,0.085531,0.333764,0.641034,0.198887,-0.073626,0.185934,-0.014604,-0.244117,0.514177,-0.072953,-0.483718,0.414582,-0.137229,0.142175,0.043833,-0.074964,0.440950,0.264339,0.444268,0.332041,-0.233979,-0.100316,0.515834,-0.024413,-0.018794,-0.051017,0.418410,0.159360,0.444497,0.203304,-0.367462,0.107957,0.210141,-0.206983,-0.717174,0.091412,0.395786,0.042116,-0.489294,0.331979,-0.263138,0.009408,0.203296,-0.385792,0.259537,0.098410,0.158167,0.393178,0.272505,0.274413,-0.500261,0.415716,0.448651,0.085264,0.180719,0.197961,-0.068602,-0.311393,0.128697,-0.071124,-0.434446,0.160219,-0.038201,-0.088031,0.324771,-0.489902,-0.516671,-0.390761,-0.109842,-0.211342,0.137620,-0.256347,-0.185477,-0.963791,0.082367,-0.011897,-0.008992,-0.173981,0.212885,0.025907,0.482080,-0.870524,-0.105891,0.234083,0.618769,-0.783875,0.906338,-0.124707,0.194814,-0.257388,-0.134472,-0.417802,0.167620,0.347683,-0.263219,0.256593,-0.243546,-0.577363,-0.153004,-0.190439', '24751811', '6731985', '25833539', '3718493');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20473370', '校花诡异事件', '惊悚', '华西学院的校花苏苏（赵奕欢 饰）独自赴景区旅游，结果遭遇山洪暴发，不得已滞留期间。她辗转来到老旧古朴的平安旅馆。经过一番讨价还价，她决定暂且在这里待上一周。电闪雷鸣的夜晚，接二连三诡异恐怖事件，令苏苏提心吊胆，惶恐难耐。次日一早，她结识了同样被困住的理工大学生陆苗（孔千 千 饰）、杨东（翟文斌 饰）以及摄影师林枫（王一 饰），青年人在一起让她暂时忘却昨夜的经历，而与林枫似曾相识的感觉又让苏苏隐隐预感到一段美好缘分的开始。只是在这片几乎与世隔绝的荒郊野外，种种意想不到的恐怖经历交替出现，带给苏苏最难忘记的阴森记忆……©豆瓣', '赵奕欢', '关尔', 3.6, 8094, 'tt3411398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2022441352.jpg', 53.3, 25.6, 14.1, 3.6, 3.4, '0.258134,0.151897,-0.767197,0.313499,0.443912,-0.018168,0.658014,-0.099899,-0.929485,-0.458424,0.393720,0.402478,-0.623165,0.447971,0.469847,-0.175753,-0.068342,-0.521492,0.092311,-0.218521,-0.302825,-0.272042,-0.118897,-0.000685,0.097049,-0.267359,0.382024,0.383049,-0.000442,0.716337,-0.049906,0.199377,-0.577629,0.675768,-0.195726,-0.187651,-0.048584,0.285478,-0.309071,-0.019272,0.143896,-0.429739,-0.125136,0.153952,0.015002,0.045648,0.766600,-0.096509,-0.547390,0.320193,0.438244,-0.063524,-0.252670,0.082107,0.068969,0.163519,0.125351,0.102469,-0.431221,-0.057012,0.114713,0.033090,-0.226037,0.311051,0.189791,0.054073,-0.241127,0.264696,0.079618,-0.057298,0.142879,-0.322828,0.247535,0.309376,0.424032,0.377987,-0.095121,0.007432,-0.179141,0.265348,0.909981,-0.131174,-0.116195,0.155262,-0.142443,-0.129790,0.014810,0.072686,-0.287791,0.108284,0.008993,0.282839,-0.323490,0.236591,-0.754230,0.191073,-0.276526,-0.149571,-0.112694,-0.183854,-0.154627,-0.554176,-0.240254,-0.139763,-0.402209,0.263099,0.038971,-0.158454,0.186458,-0.595116,0.480367,0.565164,0.087459,-0.000154,0.363388,-0.058582,0.037649,0.008623,-0.053217,0.508105,-0.151629,0.506484,0.035112,0.370812,-0.277535,0.111404,-0.664158,0.491864', '25856453', '1299433', '1773217', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20473395', 'K 剧场版', '剧情', '7人の覆面作家集団「GoRA」が原作・脚本を手がけ、2012年にテレビ放送されたオリジナルアニメーションで、7人の「王」と呼ばれる存在や、その下へ集った特異能力者たちの戦いを描いた「K」の劇場版。4人の「王」が交錯した学園島事件以降、白銀のクランズマンである夜刀神狗朗とネコは、生死不明となった主であり「白銀の王」のであるシロの行方を追っていた。しかし、なかなかその手がかりをつかめず、気を落としていた2人は、「赤の王」を主とする能力者集団「吠舞羅（ホムラ）」のメンバーである鎌本力夫と櫛名アンナが、何者かに追われている場面に遭遇し……。監督はテレビ版に続き鈴木信吾、アニメーション制作は「マルドゥック・スクランブル」のGoHands。', '浪川大辅', '铃木信吾', 7.8, 5221, 'tt3794204', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2183105552.jpg', 0.9, 2.9, 26, 43.3, 26.8, '-0.156423,0.117355,0.312369,0.145252,0.535088,0.569931,-0.027139,0.396103,-0.624028,-0.835920,0.157168,0.119573,-0.296708,-0.367379,0.497374,-0.281544,-0.196388,-0.381228,0.121143,0.246691,-0.126689,0.807581,0.284732,-0.337283,-0.717419,-0.414420,0.900188,0.187803,-0.124622,-0.429231,0.260508,0.601669,-0.890088,0.080770,-0.050372,0.268509,-0.230600,0.005701,0.173681,0.136136,-0.390271,-0.495723,-0.221398,-0.499889,0.189176,-0.239076,0.803458,-0.432548,0.204665,-0.638346,0.039375,-0.361874,-0.435543,0.216121,0.150322,-0.098350,0.354078,0.094181,0.443881,-0.451708,0.300533,-0.277825,-0.337565,-0.243440,0.234012,0.228938,-0.258995,-0.082612,-0.854510,0.266685,-0.047290,0.256904,0.097831,-0.415935,0.454935,-0.158588,0.280264,-0.085862,-0.063159,0.075465,0.276374,0.057836,-0.039303,-0.468643,0.343018,-0.954236,-0.944259,-0.338249,0.109840,0.135340,-0.040589,0.142381,0.254684,0.019560,-0.242253,-0.675043,0.038614,0.206822,0.041629,-0.378542,-0.077910,-0.317806,0.555762,-0.323812,0.135306,0.512119,0.714966,-0.548839,0.468752,-0.497835,-0.353637,0.108621,0.375237,0.018231,0.653015,-0.349868,-0.393771,-0.610667,-0.101769,0.136678,0.004312,0.327963,0.578842,0.146970,-0.248155,0.056946,0.197460,0.292098', '4930393', '26635321', '1305789', '1307100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2049435', '超人：钢铁之躯', '动作', '遥远的宇宙深处，随着氪星的毁灭，超人的传奇故事拉开序幕。氪星人乔·艾尔（罗素·克劳 Russell Crowe 饰）抵死反抗佐德将军（迈克尔·珊农 Michael Shannon 饰）的邪恶计划，冒险将刚出生不久的儿子卡尔·艾尔被送到银河系另一边的地球。卡尔降落在美国堪萨斯一座小镇，他幸运地成为乔纳森·肯特（凯文·科斯特纳 Kevin Costner 饰）和玛莎（黛安·莲恩 Diane Lane 饰）的养子，并且得名克拉克。克拉克从小显露出与众不同的能力与特征，但这些带给他惊讶的同时还有数不清的烦恼。通过养父的引导，克拉克（亨利·卡维尔 Henry Cavill 饰）慢慢弄清自己的身世以及所肩负的使命。终于有一天，遥远的故乡“同胞”莅临。站在故乡与地球、邪恶与正义的两端，超人即将面临重大的抉择……©豆瓣', '亨利·卡维尔', '扎克·施奈德', 7.2, 235027, 'tt0770828', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1968975252.jpg', 1.2, 5.7, 38.7, 38.7, 15.7, '0.259605,0.205175,-0.806280,0.530826,-0.047399,-0.170987,0.602243,0.104437,-0.316438,-0.268701,0.206809,0.956047,-0.006263,0.104054,0.362880,0.189783,-0.393159,-0.535799,0.072358,-0.163756,-0.251606,-0.656639,-0.537550,-0.231317,0.035100,-0.437129,0.759210,0.128438,-0.074589,0.433648,0.187958,0.598595,-0.354775,0.236452,-0.179279,-0.054239,0.120131,-0.030901,-0.407872,0.152692,-0.025581,0.309995,0.097413,0.206454,-0.158360,0.277992,0.608367,-0.563076,0.008858,-0.310669,0.428376,-0.273018,0.187041,0.007605,0.307935,-0.022123,-0.264698,0.175379,0.078452,-0.152674,0.117756,-0.230446,-0.762342,-0.286729,0.161119,0.233913,-0.424671,0.229902,-0.208740,-0.209689,0.384694,-0.348874,0.100175,0.493489,0.120338,0.418273,-0.143713,0.111988,-0.208273,0.031432,0.399722,-0.037343,-0.455654,0.039761,-0.207777,-0.382884,-0.222683,-0.136315,-0.569781,-0.083849,0.407249,0.250406,0.150837,0.613563,-0.660096,-0.015270,-0.386644,-0.206293,0.104947,-0.278758,-0.056954,-0.538761,-0.030056,-0.281262,-0.018481,-0.008297,0.041957,-0.221472,0.721870,-0.596364,0.559329,0.579312,0.298563,-0.158979,0.414698,-0.012719,0.389683,-0.401405,-0.061652,0.805170,0.094515,0.145346,-0.146722,0.225904,0.147708,0.056501,-0.380265,0.637104', '1303034', '1308585', '1870681', '35161768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20495023', '寻梦环游记', '喜剧', '热爱音乐的米格尔（安东尼·冈萨雷兹 Anthony Gonzalez 配音）不幸地出生在一个视音乐为洪水猛兽的大家庭之中，一家人只盼着米格尔快快长大，好继承家里传承了数代的制鞋产业。一年一度的亡灵节即将来临，每逢这一天，去世的亲人们的魂魄便可凭借着摆在祭坛上的照片返回现世和生者团圆。在一场意外中，米格尔竟然穿越到了亡灵国度之中，在太阳升起之前，他必须得到一位亲人的祝福，否则就将会永远地留在这个世界里。米格尔决定去寻找已故的歌神德拉库斯（本杰明·布拉特 Benjamin Bratt 配音），因为他很有可能就是自己的祖父。途中，米格尔邂逅了落魄乐手埃克托（盖尔·加西亚·贝纳尔 Gael García Bernal 配音），也渐渐发现了德拉库斯隐藏已久的秘密。©豆瓣', '安东尼·冈萨雷斯', '李·昂克里奇', 9.1, 1537415, 'tt2380307', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2614500706.jpg', 0.2, 0.4, 6.9, 30.6, 62, '0.184907,0.179779,-0.761606,0.556364,-0.182682,-0.322384,0.525788,0.147804,-0.619584,-0.106673,0.199493,1.007716,-0.001326,0.499276,0.387599,0.224390,-0.403014,-0.551066,0.128924,-0.309511,-0.237793,-0.333710,-0.447259,-0.219631,-0.080793,-0.503803,0.498939,0.125895,0.126677,0.253210,0.039453,0.152779,0.046383,0.354810,-0.248424,0.143642,0.042119,0.069021,-0.107541,0.335484,-0.110228,-0.185329,-0.082595,0.048472,0.093237,0.129133,0.551579,-0.428521,0.203138,-0.190830,0.300190,-0.340004,-0.010201,0.245190,0.288494,-0.116997,0.165917,0.354801,-0.356783,0.055119,-0.246018,-0.133463,-0.721828,-0.053251,0.051562,0.287818,-0.633552,0.448648,0.090527,-0.315132,0.143035,-0.401625,0.325902,0.315511,0.116119,0.521204,-0.222091,-0.081545,-0.485529,0.065310,0.540414,-0.327886,-0.247799,0.173712,-0.027039,-0.339789,0.050536,-0.003858,-0.585058,-0.140539,0.375160,0.248088,-0.120479,0.464775,-0.664566,-0.072217,-0.304152,-0.267883,0.075559,-0.405688,-0.156164,-0.572867,-0.119202,-0.001425,-0.195259,0.036789,0.080746,-0.372931,0.835857,-0.614794,0.602104,0.579369,0.069830,-0.152893,0.683689,0.171479,0.410966,-0.180953,0.026328,0.487676,-0.036666,0.286989,-0.080702,0.136030,0.035673,-0.015693,-0.427825,0.776255', '1870681', '30162520', '25928048', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2049689', '魔兽战场', '动作', '西元709年，外星人凯坦（James Caviezel 饰）驾驶的飞船坠毁在挪威境内，同伴重伤死亡，飞船损毁，沉入湖底。凯坦凭借随身携带的先进机器掌握了地球的知识和当地的语言，在森林内游荡之际，他遇到了维京人乌弗里克（Jack Huston 杰克•休斯顿 饰），并随之回到了村庄。凯坦告诉维京人自己正在寻找一头“恶龙”，而这条恶龙正是他飞船上的一只怪兽，因飞船坠毁逃遁。维京人起初认为凯坦是个说大话的骗子，但随着村民一个个离奇消失，他们才发现所谓的“恶龙”真的存在……©豆瓣', '吉姆·卡维泽', '霍华德·麦凯恩', 5.9, 10511, 'tt0462465', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p658019441.jpg', 4.2, 21.7, 54.8, 15.1, 4.3, '0.404298,-0.113427,-0.725115,0.391648,0.082807,0.029127,0.837857,-0.298800,-0.590246,-0.158278,0.331570,0.649401,0.171695,-0.172845,0.161488,0.049736,-0.361922,-0.215775,0.051021,-0.197234,-0.358632,-0.353164,-0.490921,-0.313012,0.113515,-0.408498,0.694560,0.315877,-0.081585,0.396746,-0.304959,0.312696,-0.434953,0.310727,-0.290759,-0.011896,-0.042274,-0.052841,0.152762,0.123827,-0.444058,-0.090309,0.296559,-0.080697,-0.249167,0.250748,0.875589,-0.572155,0.026638,-0.339574,0.022767,-0.469634,0.075616,-0.151197,0.545493,-0.179312,-0.146408,-0.140714,-0.009309,0.045313,-0.008228,0.215787,-0.438643,-0.087663,-0.349046,0.107462,-0.273589,0.147092,-0.048974,0.138302,-0.123089,-0.422573,0.353780,0.060568,0.137546,0.371093,0.057339,-0.058743,-0.699997,-0.061381,0.458097,-0.279001,-0.358525,0.311049,0.069681,-0.596106,-0.276754,-0.206827,-0.171311,-0.268961,0.419433,0.179342,-0.509171,0.246117,-0.582940,0.280874,-0.371655,-0.587439,-0.318672,-0.088225,-0.336700,-0.561697,0.075639,-0.054439,0.081864,0.186481,-0.190126,0.009958,0.440194,-0.526120,0.471775,0.731069,0.342632,-0.300087,0.563963,-0.466126,0.008864,-0.140350,0.041928,0.426659,0.339060,0.380294,-0.038520,0.142820,0.020783,-0.171828,-0.225411,0.314117', '21619567', '24879819', '1467779', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20497559', '猎仇者', '悬疑', '张金（樊少皇 饰）是赫赫有名的黑帮马仔，这天，刚刑满释放的他在一家餐馆被人追杀，对方对他连开数枪后迅速逃逸。命不该绝的张金并没有死，惊恐中他在怀疑到底是谁要将他置于死地。经过一番周密考虑，他决定只身调查。首先，他包下了杨言（吴镇宇 饰）的出租车作交通工具，从此，杨言的命运和他綁在了一起。令张金百思不得其解的是自已得罪了谁，非让对方索取自已性命，他锁定入狱前的三个仇家，伹最终又否定了他们是猎杀自已的真凶，张金早年的犯罪生涯被层层剥离开，杨言受雇于张金也是另有所图，故事走向扑朔迷离......©豆瓣', '吴镇宇', '伏羲', 4.2, 9216, 'tt5473330', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2156152549.jpg', 29.9, 39.5, 24, 3.7, 3, '0.165183,0.037530,-0.754252,0.398256,-0.311881,-0.167131,0.686852,-0.020940,-0.530880,0.022420,0.303420,0.748001,0.031470,0.083780,-0.027595,0.057141,-0.082616,-0.669528,0.026735,-0.105501,-0.370330,-0.528472,-0.190936,-0.180360,-0.011431,0.213312,0.314675,0.112690,-0.291772,0.184450,0.604585,0.224371,-0.170742,0.604193,-0.366964,0.266543,-0.040217,-0.164048,-0.157182,0.146156,0.048170,-0.594445,-0.302380,0.316726,-0.198401,0.530794,0.540690,-0.000012,-0.246704,-0.158480,0.160343,-0.543822,-0.206636,0.174302,0.342071,-0.010739,-0.057146,0.435918,-0.407477,-0.058678,0.108278,0.360228,-0.871869,-0.114796,0.133803,-0.049896,-0.735166,0.307812,-0.199859,0.018724,-0.015238,-0.278025,0.260606,0.290241,0.234503,0.047042,0.099223,-0.197727,-0.568018,0.242978,0.780078,0.092069,0.185188,0.158171,0.038863,-0.314758,0.024496,-0.186657,-0.284740,-0.058905,0.730991,0.136011,-0.326229,-0.026679,-0.259572,-0.238453,-0.378599,-0.203969,-0.222720,-0.456234,-0.134393,-0.172524,-0.150682,-0.364771,-0.430426,0.060856,-0.149961,-0.301087,0.330813,-0.778779,0.031268,0.663132,0.284935,-0.737938,0.482324,0.103999,0.025256,-0.028859,0.113313,-0.009461,0.382345,0.495287,0.245912,0.335219,0.247789,-0.044669,-0.297262,0.351658', '35073886', '1292584', '1309116', '1306801');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20497633', '夺命地铁', '剧情', '在莫斯科两站之间的地铁隧道因施工问题产生裂缝，隧道天花板渗漏下来的水滴并未引起足够的重视，结果引发莫斯科河水倒灌，载有数百名乘客的地铁列车陷入洪水之中，不仅令地下隧道面临崩溃，也将毁灭整个城市。安德烈加林和他的女儿捷尼亚医生被困在隧道中。加林医生试图营救乘客，其中包括他妻子的情人。他必须克服怨恨，愤怒和恐惧。除了生存，他还要找回自己的爱情和家庭。', '谢尔盖·普斯科帕里斯', '安东·梅格尔季切夫', 6.8, 19237, 'tt2649128', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2163912778.jpg', 1.6, 7.8, 48.1, 32.9, 9.5, '0.001083,0.143818,-0.889225,0.387980,0.223902,-0.016387,1.287617,0.087668,-0.534646,0.028474,0.382950,0.475959,-0.149934,0.025869,0.187528,-0.265202,-0.697968,-0.455536,-0.218054,0.003695,-0.574305,-0.493945,-0.107121,-0.070346,-0.027706,-0.712680,0.892105,0.607594,-0.214247,0.199807,-0.333071,0.303229,-0.233281,0.703525,-0.007951,0.100015,0.003628,-0.159175,-0.249095,-0.088105,0.000726,-0.034391,0.092085,0.439663,-0.106521,0.515642,0.686173,-0.019423,-0.034757,0.053802,0.086863,-0.479441,0.046100,-0.137731,0.424599,0.005629,-0.002903,0.376952,-0.245764,0.000717,0.324045,0.260315,-0.410266,-0.223114,0.107676,0.234149,-0.319681,0.131793,0.147969,-0.305947,0.117483,-0.107441,0.015098,0.143434,0.141629,0.516663,-0.746087,-0.101666,-0.630160,-0.080672,0.833411,-0.369181,-0.330584,-0.053475,-0.435000,-0.343208,-0.021129,-0.066044,-0.524876,-0.130511,0.592588,0.105386,-0.438260,0.644972,-0.372949,0.082603,-0.333448,-0.635561,-0.218674,-0.277299,-0.316426,-0.606515,-0.002857,0.045810,0.205645,-0.028103,-0.045860,0.068117,0.456913,-0.373943,0.220913,0.596348,0.514947,-0.313869,0.604922,0.033578,0.132057,-0.350218,0.082029,0.328481,-0.250952,0.612484,-0.164828,0.128940,-0.349046,0.298107,-0.463536,0.480380', '25986180', '3011051', '20451118', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20501030', '鬼遮眼', '恐怖', '蒂姆（布兰顿·思怀兹 Brenton Thwaites 饰）和凯丽（凯伦·吉兰 Karen Gillan 饰）背负着灰暗而又沉重的过去，眼睁睁地看着父母在面前悲惨地死去，这成为了姐弟两人记忆中无法痊愈的伤痕。时间飞快地流逝着，然而伤痛却没有因此而淡去，在此期间，蒂姆和凯 丽一直都没有放弃过寻求真相的机会。终于，功夫不负有心人，两人发现，一切惨剧的始作俑者就藏在家中的古董镜子之中。为了终结悲剧，蒂姆和凯丽返回老家想要将镜子摧毁，令两人没有想到的是，他们的举动却在无意之间成为了打开地狱大门的钥匙。鲜血、恐惧、愤怒、悲哀，在排山倒海而来的回忆之中，他们开始搞不清楚，究竟什么是虚幻，什么是现实。©豆瓣', '凯伦·吉兰', '迈克·弗拉纳根', 6.9, 18087, 'tt2388715', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2167579290.jpg', 1.5, 7.9, 43.5, 36.1, 10.9, '0.188633,0.211897,-0.969836,0.361974,0.085078,-0.434691,1.302850,-0.152759,-0.569225,-0.352488,0.159619,0.553867,-0.275084,0.265096,-0.035060,0.233089,-0.482271,-1.049683,-0.217394,-0.356368,-0.392182,-0.489056,-0.333052,-0.240459,0.007369,-0.202929,0.753520,0.380138,-0.071365,0.590694,0.363684,0.309650,-0.332053,0.637417,-0.179146,0.247715,-0.116858,0.089266,-0.336987,-0.144456,0.343016,-0.393712,-0.438898,0.625781,-0.009052,0.233123,0.726003,-0.317541,0.000626,0.237286,0.079003,-0.399624,-0.154038,0.234933,0.195189,0.073474,0.132456,0.036982,-0.171142,-0.219820,0.183094,0.197157,-0.972917,0.054691,-0.037249,0.574238,-0.639555,0.559603,-0.119621,-0.121424,0.138471,-0.731022,0.286822,0.117141,0.481483,0.590682,-0.546940,-0.185367,-0.668607,-0.096892,0.599185,-0.064135,-0.300311,0.605223,-0.252188,-0.020004,-0.249325,-0.079973,-0.380902,-0.083705,0.427053,0.684234,-0.217538,0.626529,-0.436669,-0.038851,-0.605756,-0.356263,-0.121597,-0.434242,-0.504595,-0.273420,-0.284232,-0.325645,-0.536921,0.161697,-0.266149,-0.318269,0.401579,-0.800482,0.312669,0.426609,0.289084,-0.087695,0.676216,0.072833,0.011598,-0.038127,0.038595,0.334773,-0.044124,0.362791,0.400796,0.102821,-0.156772,0.246957,-0.515644,0.601940', '25909236', '21348112', '1417428', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20502443', '玩物', '剧情', '影片以2009年震惊韩国的“张紫妍事件”为蓝本，揭露了演艺届、政界“性贿赂”这一丑陋的社会现象，是一部将现实事件和虚构故事相结合的纪事风影片。“她”香消玉殒，“她”的死撕开了娱乐圈的光鲜表皮。一个女明星的死亡令整个社会哗然，寻着她离去的轨迹，一幅幅丑陋的面孔和事件浮出水面。调查该案件的热血警察和女检察官逐渐深入到事件的敏感核心，却收到来自现实各个方面的压力，困阻重重。真相即将曝光，由此而起的风波也来势凶猛……', '马东锡', '崔承浩', 6.2, 10603, 'tt3144390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2170193684.jpg', 4.2, 18.4, 47.6, 20.5, 9.3, '0.366162,0.164235,-0.486247,0.583055,0.355803,0.104524,0.898467,0.175993,-0.420982,-0.188381,0.219766,0.761898,-0.514643,0.113723,0.275541,-0.076251,-0.232219,-0.816820,-0.176224,-0.121794,-0.279447,-0.074184,-0.300185,-0.472456,0.009676,-0.383178,0.969765,0.411843,-0.620387,0.449997,0.450370,0.456280,-0.381442,0.441275,0.086774,-0.036808,-0.182133,0.112487,-0.381227,-0.073275,-0.053927,-0.778348,-0.078927,0.423380,-0.465786,0.394014,0.757347,-0.212838,-0.308876,0.114622,1.170278,-0.751378,-0.384075,0.170878,0.480452,0.058775,0.070163,0.384165,-0.081168,0.023166,-0.065891,-0.143722,-0.748427,-0.206672,0.100123,0.449648,-0.378242,0.165896,-0.089382,-0.005282,-0.072673,-0.122971,0.179714,0.100024,0.312978,0.420312,-0.097317,0.222495,-0.265123,0.493880,0.609447,0.193228,-0.690535,0.157048,-0.416933,-0.540259,-0.456674,-0.348511,-0.152425,0.083671,0.543961,-0.087199,-0.364428,0.642080,-0.531634,-0.127142,-0.287517,-0.525231,-0.277014,-0.160480,-0.394324,-0.461788,-0.859681,-0.320643,-0.386658,-0.258157,0.028614,-0.292919,0.775206,-0.414027,-0.030243,0.720616,-0.243314,-0.634221,0.447189,0.045330,-0.012870,-0.193391,-0.191857,0.197474,-0.013271,0.264875,-0.262716,0.395072,-0.143461,-0.261775,-0.344081,0.390959', '24499012', '26731376', '26759820', '35151491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20503269', '三日刺杀', '剧情', '伊桑（凯文·科斯特纳 Kevin Costner 饰）是一名经验丰富、资历老道的国际特工，长久以来，他的这一特殊职业令他徘徊在危险的最前线，繁忙的工作让他同妻子克里斯汀（康妮·尼尔森 Connie Nielsen 饰）和女儿佐伊（海莉·斯坦菲尔德 Hailee Steinfeld 饰）之前的关系十分疏远，这成为了伊桑的一块心病。终于，伊桑决定金盆洗手了，他渴望回归家庭，享受最朴素的幸福和快乐。然而，就在退休之前，上司薇薇（艾梅柏·希尔德 Amber Heard 饰）交给了伊桑一个十分重要的任务——对付全世界最臭名昭著的恐怖分子，与此同时，伊桑亦得知，因为妻子有事，他必须担当起照顾正处于叛逆期的佐伊的责任。©豆瓣', '凯文·科斯特纳', '约瑟夫·麦克金提·尼彻', 6.5, 13325, 'tt2172934', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165984702.jpg', 1.9, 12.6, 53.3, 25.1, 7.2, '0.224951,-0.238196,-0.596624,0.652528,-0.192327,-0.294001,0.605654,0.343678,-0.326902,-0.510053,0.262613,0.896077,0.204752,0.293135,0.583171,-0.041281,-0.291051,-0.533473,-0.059120,-0.180652,-0.187856,-0.664511,-0.178911,-0.064136,-0.256004,-0.387812,0.819144,-0.191365,0.037995,0.336279,0.367725,0.502756,0.161642,0.422405,0.087857,-0.312323,0.380558,-0.212538,-0.393787,0.001873,0.197635,0.169754,0.067256,0.408529,0.311420,0.298508,0.428520,-0.305647,-0.095338,-0.017014,0.353976,-0.279981,0.161304,-0.137002,0.305329,-0.247943,0.045910,0.362104,-0.368726,-0.226712,-0.026658,-0.203431,-0.961844,0.051309,0.192224,0.117127,-0.522798,0.287008,-0.151117,0.160550,0.075374,-0.248910,0.225268,0.601296,-0.083343,0.261415,-0.220441,0.252402,-0.217194,0.181998,0.559197,0.100020,-0.127468,0.358743,-0.368526,-0.294260,0.081346,-0.382946,-0.732172,-0.231127,0.261032,-0.054615,-0.016250,0.147971,-0.317759,-0.087898,-0.185819,-0.062676,0.056317,-0.275316,-0.015841,-0.422363,-0.045577,-0.396651,-0.586490,-0.058855,0.021673,-0.330837,0.731295,-0.879365,0.143473,0.552795,0.042312,-0.433897,0.660105,0.284970,0.520963,-0.478144,-0.189901,0.583233,0.051031,0.056538,0.064314,0.325373,0.027992,-0.290624,-0.294331,0.599865', '1793491', '24875409', '27056396', '25880986');
