INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2051007', '哈利·波特与死亡圣器(上)', '奇幻', '《哈利·波特与死亡圣器》小站http://site.douban.com/108361/邓不利多死后，伏地魔（Ralph Fiennes 饰）与食死徒入侵魔法学校，魔法部也被伏地魔的爪牙操控，邪恶的阴云笼罩魔法世界上空。在哈利·波特（丹尼尔·雷德克里夫 Daniel Radcliffe 饰）17岁生日之际，凤凰社成员及一众好友护送他回到了凤凰社的据点陋居，然而这立即遭到食死徒毁灭性地打击。哈利和罗恩（鲁伯特·格林特 Rupert Grint 饰）、赫敏（爱玛·沃特森 Emma Watson 饰）侥幸逃亡，并且按照邓不利多的嘱托继续寻找伏地魔的魂器。死亡的威胁时刻逡巡左右，他们还要面对友情的考验。在寻找摧毁魂器方法的过程中，死亡圣器的面纱也渐渐揭开。与此同时，为了置哈利于死地，伏地魔也在寻找最后一件死亡圣器。最后的决战即将到来……©豆瓣', '丹尼尔·雷德克里夫', '大卫·叶茨', 8.5, 512663, 'tt0926084', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p721429854.jpg', 0.3, 1.2, 14.7, 42.2, 41.6, '0.069246,-0.135856,-0.392660,0.577874,0.168610,0.054586,0.586630,0.012701,-0.230829,-0.454100,0.428697,0.589759,-0.082723,0.173808,0.153653,-0.185568,-0.424316,-0.703797,-0.077778,0.046397,-0.589697,-0.358460,-0.371360,-0.398732,-0.226531,-0.574962,0.579834,0.439546,-0.186220,0.073782,0.334713,0.730655,-0.315845,0.438569,0.167650,-0.323111,0.167010,-0.163602,-0.282445,0.386213,-0.152360,-0.162313,-0.012329,0.396630,-0.099592,0.197064,0.809202,-0.636365,0.353707,-0.238488,0.222025,-0.472536,0.018639,0.212320,0.549233,-0.131148,0.008099,0.044234,-0.057053,0.071541,-0.039598,-0.000759,-0.779476,-0.015702,0.081279,-0.063906,-0.336074,0.498341,0.078218,0.557349,0.402898,-0.073350,0.045272,0.570272,0.145845,-0.000895,-0.271034,-0.104824,-0.264786,-0.228102,0.134311,-0.392367,-0.203085,-0.113377,-0.307774,-0.459340,-0.157859,-0.077921,-0.152411,-0.167144,0.423792,0.478588,0.352456,0.591262,-1.017419,-0.326705,-0.410583,-0.076163,0.055138,-0.318302,-0.292854,-0.847164,0.183174,-0.073861,-0.253997,-0.043802,0.090590,-0.066768,0.377766,-0.463303,0.411754,0.385088,0.282507,-0.293659,0.447459,-0.184052,0.465119,-0.254746,-0.192042,0.544627,0.313985,0.551071,0.173902,-0.093058,0.325657,0.226553,-0.094423,0.603459', '25774050'