INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20513059', '被偷走的那五年', '爱情', '浪漫美好的蜜月之旅，突然以一场车祸戛然而止。曾经沉浸在无上幸福中的何蔓（白百何 饰）从昏迷中醒来，却从姐姐何琪（戴君竹 饰）那里得知自己已经和深爱的老公谢宇（张孝全 饰）离婚的消息。原来她不久前刚刚出了一场车祸，导致忘记了过去五年间发生过的所有事情，最后的记忆只停留在2007年蜜月旅行的梦幻时刻。五年的时间，身边的人和整个世界都发生了太多太多的事情，她痛哭流涕，找到已有新女友的谢宇渴望找回往昔的记忆。许是心疼这个曾让自己又爱又恨的女人，谢宇暂时将何蔓留在家中。失落的时光与记忆，物是人非后什么是珍藏彼此心底……©豆瓣', '白百何', '黄真真', 6, 150882, 'tt3175936', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2089491965.jpg', 5.7, 21, 47.5, 19.1, 6.7, '-0.075147,0.381620,-0.874363,0.384793,0.084065,-0.595713,1.017741,-0.431659,-0.828005,-0.424314,-0.109811,0.468371,-0.288741,0.617184,0.383134,0.190802,-0.328867,-1.068209,0.062665,-0.212941,-0.447522,-0.219484,-0.200401,0.077714,0.029498,-0.372162,0.654286,0.393886,-0.025065,0.425402,0.221327,0.189093,-0.373471,0.666682,-0.205539,0.296412,0.026116,0.591696,-0.470326,-0.201978,0.294536,-0.490742,-0.179082,0.281984,-0.099989,0.147118,0.580780,-0.121340,-0.513451,0.136244,0.357673,-0.153917,-0.351063,0.037616,0.081009,0.174749,0.371338,0.211405,-0.460471,-0.104405,-0.092087,0.158514,-0.649798,-0.113726,-0.029076,0.089006,-0.489457,0.435203,-0.121937,0.247925,0.356629,-0.279912,0.359225,0.385303,0.267546,0.509632,-0.566632,-0.069208,-0.359114,0.452788,0.999777,-0.195446,-0.070466,0.771520,0.017987,-0.262179,-0.282391,0.075516,-0.515003,0.497323,-0.007429,0.237491,-0.354678,0.594072,-0.501177,-0.124763,-0.146749,-0.205154,0.163217,-0.321537,-0.342673,-0.140721,-0.453286,-0.405944,-0.442800,-0.019385,0.046016,-0.317936,0.419231,-0.832645,0.642977,0.380660,-0.006786,-0.385419,0.524706,0.209744,0.129527,-0.237202,0.315409,0.517673,-0.276749,0.105155,-0.070126,0.059442,-0.129303,0.200102,-0.821774,0.706283', '2365260', '26245360', '1302109', '25858759');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20513061', '京城81号', '剧情', '台湾女作家许若卿（林心如 饰）为了与情人赵亦堂（吴镇宇 饰）生活在一起而迁居内地，临走前母亲（金燕玲 饰）给了她祖上留下来的老宅钥匙，于是若卿带着女儿小梦（张煜雯 饰）住进了传说中的凶宅——朝内81号。亦堂的妻子（夏文汐 饰）不肯离婚，加上他常因工作与秘书琉璃（莫小棋 饰）在一起，这让若卿心神不宁。诺大的宅子除了一名老佣人（袁祥仁 饰）便无他人，可是小梦却说自己常与一个红衣小姐姐玩耍，大胆的若卿想要一探究竟，却意外发现了宅子的尘封往事。原来这一切与老宅原来的主人霍家三兄弟息息相关，霍家三少爷霍连奇（杨佑宁 饰）一心想娶青楼头牌陆蝶玉为妻，陆蝶玉却阴差阳错与二少爷（李菁 饰）进行了冥婚，这一场闹剧直接导致了日后霍家的全面衰败……而现实中若卿愈发地感觉到了宅子的超自然力量。本片改编自民间传说的四大凶宅之首“朝内81号”的诡异故事。©豆瓣', '吴镇宇', '叶伟民', 4.8, 104720, 'tt3816526', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187047385.jpg', 17.9, 38.3, 34.6, 6.4, 2.7, '0.114619,0.098847,-0.608791,0.632890,0.166037,-0.449998,0.855335,0.448930,-0.500766,-0.478451,0.188831,0.707622,-0.021301,0.178013,0.189892,0.235737,-0.095457,-0.367317,-0.224441,-0.199857,-0.143316,-0.137253,0.026853,-0.187922,0.015735,0.031653,0.311885,0.155210,-0.009509,0.389189,0.395088,0.307266,-0.462102,0.027471,-0.201578,0.158699,0.045900,0.400712,-0.392507,-0.020160,-0.042004,-0.175829,-0.274313,0.104287,0.094991,0.112480,0.552379,-0.244195,-0.041616,-0.119926,0.221530,0.201127,-0.272303,0.105486,0.182796,-0.064174,0.347155,0.395567,-0.321797,-0.159161,0.262524,-0.061484,-0.452953,0.195748,0.311085,0.067524,-0.507394,0.378034,-0.127124,-0.146052,-0.115971,-0.265504,0.287066,0.304879,0.222219,0.236405,-0.267279,0.015496,-0.529469,0.418269,0.397489,-0.030773,0.135997,0.402692,0.145366,-0.264625,-0.029550,-0.077719,-0.525199,0.033584,0.344983,-0.043101,-0.013458,0.201234,-0.621809,-0.256164,-0.218073,-0.038743,0.097321,-0.343588,0.082599,-0.335092,-0.261139,-0.340504,-0.183792,0.090568,0.364091,0.087144,0.494085,-0.618720,0.142329,0.345887,0.134304,-0.720412,0.455893,0.072296,0.295712,-0.237329,-0.108693,-0.183170,-0.021684,0.366815,0.231261,0.435435,-0.188418,-0.149096,-0.468342,0.194748', '1296534', '21619567', '3111650'