INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20514871', '幽冥', '动作', '讲述了一个美国国防部高级研究计划局科学家接受一项致命任务，带领一队精挑细选的三角洲部队士兵进驻一个被战争摧毁的城市，这里游荡着被称为“幽冥”的神秘幽灵，它们无形无色，能在不经意间造成大规模的伤亡。', '克莱恩·克劳福德', '尼克·马蒂厄', 7.3, 52930, 'tt2106651', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2406120224.jpg', 0.7, 4.2, 38.8, 42.6, 13.8, '0.537514,-0.053570,-0.693380,0.754593,-0.043669,0.583591,0.824345,-0.231825,-0.216568,-0.324149,0.565729,0.568191,0.230942,-0.538814,-0.059122,-0.355965,0.179474,-0.323052,-0.297426,-0.153140,-0.500397,-0.321793,-0.638736,-0.315474,0.186168,-0.615765,0.664369,0.506444,-0.509156,0.481402,-0.275509,0.423511,-0.257214,0.288749,-0.126893,-0.418576,0.813617,-0.582193,0.281730,0.657339,-0.768268,-0.151018,0.211559,0.299235,-0.466571,0.238969,1.046952,-0.565055,-0.093842,-0.440999,0.179546,-0.512456,0.183242,-0.055869,0.626192,0.478487,-0.182563,-0.177440,-0.248653,-0.009657,-0.195089,-0.284732,-0.844953,-0.624535,-0.051152,0.170505,-0.518285,0.154047,0.397836,0.262897,0.085042,0.044201,0.219027,0.384046,0.537992,0.344003,0.030573,0.254026,-0.665464,0.276653,0.619550,-0.765898,-0.626600,-0.108427,-0.408899,-0.455304,-0.171961,-0.515405,-0.367706,0.041115,0.312581,-0.186553,-0.113441,0.329673,-0.820126,0.512870,-0.406899,-0.504128,-0.466431,-0.166255,-0.144409,-0.994325,0.028832,0.206502,-0.504196,0.682475,-0.108365,0.170924,0.953182,-0.508197,0.304667,0.927543,0.463419,-0.407458,0.418733,0.099535,0.365112,0.069126,0.257258,0.235949,0.511776,0.710109,0.447541,0.667236,-0.271856,0.011715,-0.165558,0.205843', '1307897', '24879819', '4181031', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20514902', '闯入者', '剧情', '独居老人邓美娟（吕中 饰）因为常常接到骚扰电话而忧心忡忡，但是大儿子大军（冯远征 饰）及大儿媳（秦海璐 饰）却认为是老人因为丧偶而引发的臆想症。老邓试着跟小儿子小兵（秦昊 饰）沟通，却演变成因为看不惯同性恋儿子的生活习惯引发的争吵。就这样，老邓变成了两个儿子生活中的闯入 者，格格不入地生活在老房子里。随着时间的推移，小区内发生的入室抢劫案以及大军家里发生的恶作剧事件，逐渐让一家人变得警惕起来，而就在此时老邓遇到了一个游荡的少年（石榴 饰），并好心地让他在家里借住。可是事件并没有平息，而是愈演愈烈，两兄弟终于发现一切事件的发生都与几十年前母亲在三线建设中发生的事有密切关系……©豆瓣', '吕中', '王小帅', 7.6, 62621, 'tt3890278', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2242132737.jpg', 0.8, 3.4, 28.4, 51.6, 15.9, '0.366591,-0.192411,-0.773131,0.421688,0.064121,-0.092357,1.167990,0.030392,-0.743631,-0.537283,0.090558,0.476950,-0.327511,0.404067,0.337228,-0.363509,-0.191767,-0.826412,0.037230,-0.011732,-0.100853,-0.362773,-0.008052,-0.308355,-0.225382,-0.338994,0.638578,0.290549,-0.202789,0.416256,0.228918,0.142078,-0.243329,0.604723,0.012996,0.054549,-0.104372,0.346332,-0.116849,-0.006678,0.176734,-0.233452,-0.038729,0.048434,0.220691,0.329983,0.664427,-0.535135,-0.464021,-0.097339,0.250207,-0.142964,-0.194290,0.089916,0.593982,0.199710,0.383469,0.329501,-0.256770,0.068938,0.134827,0.112785,-0.299589,0.473611,0.045575,0.409031,-0.453387,0.396365,0.282095,-0.315461,-0.010397,-0.354995,0.437933,0.597224,0.445418,0.464424,-0.392922,-0.123441,-0.532636,-0.127560,0.716155,-0.114688,-0.249486,0.412045,-0.252225,-0.202316,0.007863,-0.170728,-0.448483,0.036736,-0.177300,-0.040661,-0.383229,0.738492,-0.451192,0.188060,-0.204181,-0.293251,-0.014447,-0.303552,-0.270186,-0.553718,-0.120695,-0.513691,-0.298094,0.307276,0.022394,-0.301368,0.362629,-0.917846,0.263178,0.306190,0.300709,-0.567917,0.345162,0.055879,0.161656,-0.244340,-0.232221,0.051057,-0.076624,0.138901,0.092636,0.047805,-0.264125,-0.231415,-0.093889,0.267347', '1308755', '21348112', '27617348', '1304665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20514947', '龙虾', '剧情', '故事背景设定在一个虚构的近未来社会，居民的婚恋受到严格控制管理。根据规定，单身者要被集中移送到一个酒店里，他们必须要在45天之内找到一个匹配的伴侣，失败者会被转化为一种自选的动物，并被流放到森林中。为了延长45天的期限，酒店里的单身者们还会到森林里狩猎其他逃亡的单身者。本片的主人公大卫（柯林·法瑞尔 Colin Farrell 饰）与一批单身者一同被送到酒店，他忍受着这里的各种严苛规定，同时也积极在酒店提供的各式各样的相亲场合中寻找伴侣。眼看期限将至，大卫还没有找到合适的伴侣。尝试和一个女人配对失败后，他逃到了酒店外面的森林，逃亡的单身者居住的地方。然而，在这个单身者反抗酒店制度的栖息地里，又有着另一套截然不同的制度……©豆瓣', '科林·法瑞尔', '欧格斯·兰斯莫斯', 7.6, 134012, 'tt3464902', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2304460273.jpg', 0.6, 3.1, 29.5, 48.5, 18.2, '0.521429,0.229502,-0.789496,0.784294,-0.096936,0.120645,0.798753,-0.002951,-0.355491,-0.164263,0.177912,0.889597,-0.003786,0.368307,0.445764,-0.059746,-0.256636,-0.408400,-0.171798,-0.425979,-0.756896,-0.222274,-0.232341,-0.339767,-0.449523,-0.158882,0.885599,-0.068625,-0.094214,0.318997,0.129975,0.250838,-0.245017,0.371363,-0.410021,-0.234202,0.313891,-0.110208,-0.111004,0.741105,-0.087860,0.109579,0.021217,0.109906,-0.016096,0.488891,0.879637,-0.254474,-0.123861,0.020912,0.517614,-0.038745,-0.223475,0.265557,0.535000,-0.284932,0.383063,0.408753,-0.124011,0.311105,-0.105373,-0.140068,-1.090748,-0.425455,0.259092,0.084394,-0.513014,0.438896,0.291432,-0.141926,0.120653,-0.479040,0.056119,0.128987,0.265673,0.515421,-0.081491,-0.201074,-0.529990,0.163432,0.657644,-0.333764,-0.520448,0.159854,-0.145896,-0.709968,0.133667,-0.232818,-0.721742,-0.217786,0.224248,0.244566,-0.251999,-0.188185,-0.845770,0.190140,-0.142891,-0.413870,0.011731,-0.292625,-0.387143,-0.762558,0.196571,-0.254909,-0.166375,0.426418,0.328751,-0.346919,0.487204,-0.987575,0.134845,0.805261,0.319823,-0.962460,0.943691,-0.058948,0.570759,-0.091624,-0.185766,0.117510,0.333271,0.618536,-0.083741,0.298064,-0.214653,-0.041132,-0.608693,0.432932', '1793491', '1294893', '3055049', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20515018', '白狐', '动作', '古时候，孤仙谷的小翠（钟欣桐 饰）爱上了凡界少年王元丰（张智霖 饰）。当时正处仙魔世界，天地间一片混沌，而元丰身上隐藏的至阳玄魄，乃邪魔妖道的终极克星。身为孤仙的小翠性格孤独且叛逆，很想有一段九尾孤式的爱情，此时正好遇上了看似傻傻的元丰。元丰看似憨傻，实则内心灵秀，他大智若愚，特别是身居奇功后，越发刚猛酷烈、英气勃发。小翠的妈妈孤母（惠英红 饰）一生养育了十个女儿，在她身上既有慈母的温柔又有孤狸的野性。以元丰为首的正义力量与海蝠王（高虎 饰）为首的邪恶势力展开了生死较量……本片改编自《聊斋志异》。©豆瓣', '钟欣潼', '牛朝阳', 3.5, 11233, 'tt4960930', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2075536699.jpg', 55.4, 25.4, 12.6, 3.2, 3.3, '0.113892,-0.027226,-0.445813,0.627296,-0.039221,-0.170804,0.618284,0.337782,-0.471021,-0.138549,0.291123,0.367819,-0.061334,-0.055402,0.108720,0.023369,0.170712,-0.228607,-0.352879,-0.010223,0.155877,-0.161449,-0.426155,0.462256,-0.120807,-0.492470,0.785574,0.090267,0.033918,0.323218,0.312327,0.468718,-0.109859,0.213316,-0.310145,-0.043383,-0.180546,0.011355,-0.092981,0.119000,-0.008982,-0.042779,-0.325633,0.303016,-0.563043,0.049180,0.476377,-0.397643,0.132494,-0.439429,0.549094,0.121228,-0.314229,-0.005116,0.186099,0.063331,0.355237,0.360100,-0.036017,0.124245,0.011800,-0.010260,-0.675975,-0.066848,0.134409,0.012455,-0.151247,0.388191,0.254501,-0.330764,0.287644,-0.245221,0.161105,-0.056994,0.258213,0.219732,0.012558,-0.100210,-0.394094,0.065832,0.273274,0.018617,-0.197265,0.411458,-0.155527,-0.392743,0.008808,-0.440677,-0.489071,-0.025795,0.112333,0.046143,-0.001065,0.313959,-0.557911,0.217995,-0.094870,0.449327,-0.214545,-0.180123,-0.334303,0.024303,-0.575964,-0.686609,-0.287517,-0.284482,0.146855,0.039158,0.811521,-0.871322,0.068650,0.234888,0.039125,-0.168179,0.405130,0.144093,-0.048585,-0.240616,-0.101754,0.215138,-0.069155,0.193384,0.018581,0.472693,-0.178007,0.140017,-0.220510,0.545135', '24284209', '25880986', '27602116', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20515031', '总铺师', '剧情', '二十多年前，台湾办桌界有三大传奇总铺师称霸北、中、南，分别为憨人师、鬼头师与苍蝇师，乡民们尊称为“人、鬼、神”三霸。随着时代变动，办桌文化终于逐渐式微，人鬼神凋零。苍蝇师想将家传手艺交给独生女詹小婉，谁知小婉只想当明星，美美的出现在萤光幕前。但一心想逃离油烟血水的小婉，却被迫面对巨大的挑战和使命。', '杨祐宁', '陈玉勋', 7.1, 7210, 'tt3166476', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2155515656.jpg', 2, 8.2, 37.1, 38, 14.6, '0.056706,-0.018670,-0.409960,0.316744,0.365944,-0.089182,0.260404,0.111014,-0.613656,-0.424406,-0.079426,0.787345,0.116339,0.037793,0.183512,-0.540193,0.255800,-0.697467,-0.385564,-0.415159,-0.136453,0.015286,-0.189006,-0.116020,-0.226330,-0.397090,0.498677,-0.004345,0.026394,0.273189,0.222089,0.108643,-0.286251,0.110845,-0.273464,0.060786,0.280263,0.248103,-0.310872,-0.258518,-0.178414,-0.139083,0.079738,-0.197376,-0.125269,-0.106895,0.158170,-0.575671,0.186896,-0.616953,-0.082848,-0.117107,-0.414354,0.109820,0.334898,-0.071754,0.566576,0.036902,0.299437,-0.270031,-0.189578,-0.188989,-0.695294,0.084308,0.366792,-0.040139,-0.676037,0.228514,0.039129,0.154095,0.002688,-0.314167,0.563690,0.109881,0.353569,0.366894,-0.111809,0.051655,-0.131064,0.316756,0.525518,0.212128,-0.212875,-0.148200,0.062532,-0.088181,0.097111,-0.588786,0.011293,-0.048647,-0.029425,0.159868,0.070195,0.124821,-0.549503,-0.217890,-0.172267,-0.056083,0.206817,-0.023429,-0.296901,-0.200239,0.264171,-0.156826,0.060071,0.157623,0.255721,-0.271420,0.765220,-0.874605,0.258132,0.081884,0.362632,-0.358907,0.756064,-0.264080,0.128294,-0.379735,-0.309641,-0.001485,-0.082846,0.596342,0.238991,0.335393,-0.489387,-0.171735,-0.100551,0.077905', '1783461', '1877596', '30345227', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20515070', '军中乐园', '剧情', '海龙菜鸟小宝（阮经天 饰）来到海天一色的金门，欢迎他的却是魔鬼士官长老张（陈建斌 饰）带来的铁血磨练。惨遭退训后，他被分发到有“军中乐园”之称的特约茶室，却在这里遇到了新训中心的好友华兴（王柏杰 饰），也发现了老张对阿娇（陈意涵 饰）情有独钟的秘密，坚守忠贞的他这时也被侍应生妮妮（万茜 饰）吸引，展开了一段幽微的情愫……就当一切看似美好之际，茶室出了意外，风声鹤唳下，小宝偶然间又得知了妮妮深藏心底的秘密！他的世界开始动摇之际，变化接踵而至……', '阮经天', '钮承泽', 7.4, 85387, 'tt4012914', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2244406291.jpg', 0.6, 3.5, 34, 46.7, 15.2, '0.522129,0.412449,-0.910387,0.263946,0.049141,-0.097506,0.843936,0.122228,-0.541070,0.082331,0.359338,0.283696,-0.383028,0.101345,0.290430,0.138791,-0.292912,-0.666653,-0.116633,-0.357103,-0.015504,-0.008454,-0.524160,0.069705,-0.068616,-0.332610,0.271618,0.220432,-0.236197,0.474334,0.132399,0.337024,-0.019861,0.634252,0.166635,0.282026,0.211896,0.073257,-0.064322,0.022632,0.026055,-0.443762,-0.126625,0.305056,-0.122162,0.391888,0.759877,-0.328591,-0.276384,0.019745,0.232319,-0.135290,-0.023595,-0.135153,0.260898,0.053399,-0.095672,0.157397,-0.119351,0.087198,0.025158,0.049638,-0.384161,-0.110185,0.060308,0.314547,-0.525016,0.249924,-0.082275,-0.028559,0.079277,-0.447715,0.176435,-0.023519,0.330802,0.317673,-0.108210,0.175708,-0.296855,0.266416,0.574327,-0.147356,-0.055262,0.145345,-0.282773,-0.456640,0.107733,0.164858,-0.344074,-0.132250,0.469164,0.028932,0.066680,0.020753,-0.484072,-0.063645,-0.247875,-0.100302,-0.134781,-0.375178,-0.218117,-0.432806,-0.166934,-0.406002,-0.559684,0.160422,0.023754,-0.020178,0.671394,-0.891484,0.315549,0.543007,0.129376,-0.188243,0.422299,-0.069169,0.054494,-0.245414,0.031953,0.180371,-0.161105,0.528705,0.080938,0.418593,-0.169300,-0.230298,-0.352151,0.468814', '1292211', '21348112', '1301022', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20515071', '飞虎出征', '喜剧', '飞虎队B队队长阿强（杜汶泽 饰）在一次任务后遇到了前所未有的危机，上司（王敏德 饰）对其整个小分队表示失望，下属阿富（余文乐 饰）私下表示想要转到实力更强的A队。阿强为了重振士气决定开展一次特殊的任务，那就是带领小组队员偷渡去澳门嫖妓。可是事与愿违，此次行动漏洞百出，下属虾米（曾国祥 饰）误用强力神油导致4人被澳门警司抓进警局，下属家豪（邹凯光 饰）弄丢了全队的钱被迫偷老父亲（刘江 饰）的钱导致父亲心脏病发……好在在“培训员”细细（刘安琪 饰）的帮助下，4人得以脱生，可在逃亡途中新的冲突又再次发生。本片改编自彭浩翔坏品味小说系列之《特别任务连》。©豆瓣', '余文乐', '麦咏麟', 6.6, 28768, 'tt3044248', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2004661375.jpg', 3.7, 12, 45.1, 29.4, 9.8, '-0.143176,-0.084008,-0.435585,0.411401,-0.060753,-0.121218,0.142276,0.337044,-0.682008,-0.074952,0.403511,0.486567,0.056444,-0.225724,0.352494,-0.302043,-0.269417,-0.515510,0.081203,-0.130954,-0.310308,-0.281565,-0.005455,-0.196133,0.008733,-0.269495,0.400501,0.052494,-0.309569,0.262264,0.416935,0.377351,-0.145887,0.367924,0.061053,0.160084,0.205590,-0.226672,-0.239188,0.143963,0.071477,-0.228797,-0.213337,0.149894,0.409299,0.347542,0.821868,-0.149208,-0.373933,-0.129083,0.166861,-0.289269,-0.052696,-0.224537,0.345018,0.305661,0.261422,0.118809,-0.010366,0.255525,0.057226,-0.127506,-0.643651,0.104965,0.275486,0.062589,-0.540299,0.420840,-0.221187,0.332779,0.171946,-0.130160,-0.037530,0.435995,0.224703,0.170608,-0.044569,0.065029,-0.215914,0.440041,0.560493,-0.255580,0.054625,0.170538,0.080341,-0.305529,0.037361,-0.202155,-0.157543,0.236487,0.414768,-0.006794,-0.001201,-0.081421,-0.583845,-0.047109,-0.178715,-0.077831,-0.113393,-0.300604,0.252786,-0.718132,0.133586,0.080413,-0.211888,0.268386,0.084433,-0.091120,0.312573,-0.573203,-0.090997,0.596319,0.068183,-0.770387,0.035736,0.062589,0.072355,-0.296459,-0.196973,-0.080043,0.229468,0.531918,0.208488,0.173839,-0.089773,-0.493139,-0.131229,-0.080331', '1292829', '26678784', '1296201', '1309112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20515394', '自由坠落', '剧情', '马克（汉诺·科弗勒 Hanno Koffler 饰）即将成为防暴警察，他和女友正期待着孩子的出生，生活看似一帆风顺。在警校集训期间，马克认识了室友凯（马克思·雷迈特 Max Riemelt 饰）。两人一起跑步、游泳、抽大麻，马克感到前所未有的自在。情愫渐生的他终于意识到了内心潜伏着同性爱慕的欲望。而当凯申请调去马克的警队后，他们发现这段感情原来是双向的。前所未有的刺激将马克的安逸生活打乱，在家人和女友眼中他变成了另一个人。马克的世界正在出现真空，他开始体验生命中的自由落体......德国导演斯蒂芬·拉坎特的长片处女作，一部情感丰富的双情路电影，入选第63届柏林电影节“德国视角”单元。为了忠于自己，一个人要付出怎样的代价？究竟是要忠于家庭、责任，还是忠于自己的心？©豆瓣', '汉诺·科夫勒', '斯蒂芬·拉坎特', 7.8, 23208, 'tt2617828', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1930212196.jpg', 0.3, 2.2, 26.9, 46.5, 24, '-0.008580,-0.065280,-0.718764,0.670117,-0.092738,-0.401324,0.633986,0.191966,-0.445290,-0.081112,0.203576,0.720594,-0.078124,0.351581,0.467253,-0.000986,-0.406887,-0.698860,-0.248571,-0.103722,-0.243027,-0.336144,-0.261027,-0.233083,0.053200,-0.405651,0.787316,0.016517,-0.071282,0.383267,0.406654,0.349957,0.023751,0.403450,0.053740,0.052861,0.168941,-0.103132,-0.448297,-0.047075,0.094270,-0.115370,-0.172567,0.171810,-0.000642,0.190560,0.763275,-0.057993,0.050634,-0.010932,0.471808,-0.266303,-0.097423,-0.166789,0.234179,0.084277,0.053607,0.184364,0.102133,0.251069,0.017233,-0.156471,-0.661958,-0.101444,-0.052064,0.241675,-0.586802,0.482539,-0.163452,-0.010237,0.251343,-0.193391,-0.011925,0.267495,0.247626,0.484086,-0.351581,0.016055,-0.308677,0.109728,0.783598,-0.311497,-0.308225,0.403114,-0.490402,-0.329487,-0.061704,-0.090369,-0.410141,-0.140190,0.329817,0.101801,-0.223344,0.391640,-0.457039,0.134902,-0.138209,-0.123196,0.043101,-0.478885,-0.111615,-0.595639,-0.299527,-0.404797,-0.027841,-0.020160,0.107970,-0.328748,0.646908,-0.755351,0.175963,0.654982,0.140926,-0.355667,0.810014,0.218742,-0.124902,-0.373992,0.024061,0.387992,-0.188954,0.183852,-0.113770,0.283728,-0.084462,0.200598,-0.107740,0.679348', '26021055', '1652618', '30162520', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20515977', '魔警', '动作', '从警十七年之久的王伟业（吴彦祖 饰），因为童年和家庭的原因，内心极度不安的他同时秉持着绝对的正义感，以致于其待人接物过程中矫枉过正，与同事交流多有不畅。在驻守急诊室的某个夜晚，伟业为某个急需稀有血型的重伤患者输血，谁知对方是作恶多端的银行抢劫团伙鬼王党的头目韩江（张家辉 饰）。伟业因此受到同事的谴责，而不久后韩江还偷偷溜走，旋即率领同伙犯下滔天大案，伟业的同事更在交火中火焚而亡。人在做，天在看，彪悍跋扈的韩江也从没想过自己会被欲望无情吞噬。另一方面，伟业的精神状况愈加令人堪忧，他拒绝接受心理辅导，宛如鬼魅一般执着地追踪韩江的同伙。他见证着背叛与杀戮，也坐视内心强大信念的轰然垮塌……©豆瓣', '吴彦祖', '林超贤', 6.1, 62512, 'tt3511542', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2177928873.jpg', 3.2, 18.5, 55.1, 18.4, 4.9, '0.108180,-0.079155,-0.768508,0.373995,-0.107011,-0.143743,0.831614,0.202957,-0.830711,-0.173312,0.494131,0.519129,-0.145520,-0.086636,0.194159,-0.327814,0.072711,-0.664291,-0.237762,0.166372,0.052532,-0.116573,-0.280816,-0.337336,0.034493,-0.403456,0.580643,0.048173,-0.264689,0.393931,0.137152,0.388249,-0.039265,0.717364,0.178215,-0.057217,0.008437,0.097085,-0.148299,-0.008522,0.151855,-0.377195,-0.021172,0.300126,-0.415179,0.299789,0.472276,-0.170882,-0.401338,-0.336591,0.449227,-0.418643,-0.022091,0.215099,0.352704,0.145103,0.346891,0.307178,-0.038002,-0.047442,0.010972,0.148999,-0.838934,-0.290132,0.164361,0.265204,-0.498385,0.355151,-0.046522,-0.024263,0.184645,-0.250276,0.016535,0.159930,0.365719,0.478370,-0.326480,-0.314444,-0.344127,0.371978,0.695352,-0.072448,-0.240822,-0.050816,-0.324106,-0.321041,-0.023188,-0.190088,-0.542684,-0.242342,0.297210,0.094904,-0.238980,0.485696,-0.444057,0.078523,-0.240127,0.112598,-0.171324,-0.292417,-0.078150,-0.481457,-0.240478,-0.327756,-0.195420,0.167044,0.183820,-0.229894,0.634351,-0.825951,0.197295,0.634620,0.377249,-0.536193,0.333790,0.242447,-0.239332,-0.027157,-0.196316,0.402457,-0.057072,0.547222,-0.018236,0.071723,-0.108680,-0.162351,-0.037080,0.355255', '1301022', '1308755', '35030151', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2051750', '鬼来电', '悬疑', '年轻少女贝丝•雷蒙德（Shannyn Sossamon 莎妮•索萨蒙 饰）正经历人生最恐怖的时刻。她的两位好友谢莉（Meagan Good 饰）和琳恩（Azura Skye 饰）短短几天内相继遭遇横祸，离奇死亡。更为恐怖的是，她们在死前的几天皆收到来自自己手机的语音短信，短信不仅预告了死期，还录下她们惊恐绝望的呼叫。此后几天，贝丝更亲眼目睹其他几位朋友的死亡，阴森肃杀的气氛在她们之间蔓延。警察杰克（Edward Burns 饰）受命调查此案，与其他警探不同，他对贝丝的描述深信不疑，因为杰克的妹妹便是这一连串离奇事件的第一位牺牲者。两人达成共识，联合调查背后真相，而这时贝丝却接到了自己手机发来的神秘短信……本片根据日本同名电影翻拍。©豆瓣', '莎妮·索萨蒙', '埃里克·瓦利特', 5.7, 5850, 'tt0479968', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2097799339.jpg', 5.8, 24.3, 53, 12.5, 4.4, '0.265593,-0.221443,-0.604379,0.604742,0.237922,0.164554,0.692085,-0.148729,-0.563049,-0.562775,0.189945,0.551440,-0.602890,0.204111,0.198221,-0.247118,-0.446162,-0.686286,-0.093402,-0.344408,-0.266544,-0.323327,-0.176491,-0.189465,0.223773,-0.173752,0.328636,0.051744,-0.173384,0.681891,0.391306,0.407027,-0.618514,0.433889,0.032054,0.086911,0.248492,0.038895,-0.228020,-0.124869,0.134706,-0.229633,-0.023443,0.397227,0.000218,0.433417,0.410247,-0.255630,-0.409169,-0.001439,0.491767,-0.136846,-0.084684,-0.045549,0.452124,0.108223,0.427080,0.359337,-0.270354,-0.242015,-0.231437,0.217537,-0.705976,0.317503,-0.129517,0.292334,0.101063,0.125283,-0.305789,0.200199,0.270900,-0.213787,0.308860,0.367593,0.101774,0.222701,-0.118499,-0.111487,-0.095574,0.135450,0.568198,0.057223,-0.037752,0.187059,-0.176160,-0.426180,-0.139936,0.235418,-0.451052,0.356741,0.423381,0.162874,0.063259,0.373531,-0.541956,-0.130762,-0.103399,-0.136878,-0.137570,-0.418085,-0.258430,-0.878055,-0.414440,-0.230904,-0.435944,0.123550,0.098428,-0.050079,0.648236,-0.458049,0.174718,0.132535,0.142874,-0.373799,0.316435,0.199434,0.117840,-0.296521,0.023308,0.330969,0.271652,0.108881,0.075395,-0.048200,-0.120665,0.011743,-0.573994,0.339524', '3318306', '10466639', '25723905', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2051813', '火影忍者疾风传剧场版：鸣人之死', '动作', '幽灵军团的黄泉（中村秀利 配音）通过神秘的暗黑医疗术，复活了具有足以毁灭世界恐怖力量的魔物魍魉（加藤精三 配音），希望以此建立黑暗的千年王国。魍魉俯身于黄泉身上，随即命令幽灵军团攻打鬼之国，企图杀害具有封印魔物和预言死亡能力的巫女紫苑（藤村歩 配音），并准备夺回魍魉封印在沼之国的肉体。一旦魍魉的灵魂和肉体合二为一，世界将彻底灭亡。鬼之国遇袭的消息很快传到其他各国，叶隐村的忍者也被调动起来。鸣人（竹内顺子 配音）、小樱（中村千绘 配音）、宁次（遠近孝一 配音）和小李（増川洋一 配音）受命前去保护紫苑。然而，鸣人却从紫苑的口中得到他将死去的预言……本片为《火影忍者》第四部剧场版动画。©豆瓣', '竹内顺子', '龟垣一', 7.3, 13376, 'tt0988982', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2610254775.jpg', 0.9, 4.7, 39.5, 37.1, 17.8, '-0.113706,0.287146,-0.445206,0.541505,-0.072399,0.120814,0.433850,0.055526,-0.136535,-0.378647,0.023171,0.549949,0.154342,-0.099920,0.208352,0.026186,-0.077921,-0.473852,-0.200884,-0.082946,-0.330707,-0.138976,-0.296870,-0.281283,-0.199442,-0.790837,1.116173,0.159161,-0.525343,0.087515,-0.081639,0.470218,-0.483085,0.108908,0.030778,0.057340,-0.049276,-0.337800,-0.221006,0.477197,-0.286060,-0.117860,-0.020278,0.344816,-0.311141,-0.005238,0.652545,-0.750332,0.151636,-0.439546,0.230226,-0.473886,-0.248797,-0.070913,0.392496,0.245105,-0.003026,0.272749,-0.018800,-0.022631,0.060656,-0.182373,-1.186244,-0.085962,0.085044,0.162695,0.129942,-0.087599,-0.131490,0.288678,0.384549,-0.330714,0.140681,0.120966,0.439593,0.330148,-0.530498,0.352904,-0.088418,0.003881,0.423469,-0.376892,-0.337883,0.029427,0.097351,-0.488975,-0.560230,-0.034145,0.012776,0.118022,0.430313,0.423773,0.008969,0.400004,-0.764345,-0.399831,-0.203524,-0.230608,-0.027943,-0.062392,-0.037407,-0.836904,-0.240722,0.234812,0.125890,-0.116592,0.456269,0.014392,0.949311,-0.811017,0.281858,0.608626,0.455084,-0.341109,0.097439,-0.100387,0.175662,-0.244173,0.288087,0.337782,0.336336,0.730830,0.420536,0.198881,0.075634,0.211227,-0.505277,0.384522', '2369613', '3861846', '26759820', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2052973', '基因决定我爱你', '喜剧', '女孩四季（关颖）与玛菱（余男）同在一家公司上班、同住一间公寓，一个携带对“肮脏”超级敏感的洁癖基因，另一个则有肥胖基因，必须不停地吃药才能抑制发胖，两人均为无法与他人建立稳定的关系烦恼着。四季重逢初恋男友食蚁兽（何润东），两人欢欢喜喜再续情缘之时，对方不经意间流露的邋遢令她难以继续往前；玛菱与男友（林依伦）一年见面的次数非常有限，渴望常情的她被隔壁住的阳光男孩小熊（彭于晏）暗恋着。为了收获令自己真正开心的爱情，两人决定服食药物改造基因，之后，她们的基因得到修正，但新的烦恼也接踵而至。©豆瓣', '余男', '李芸婵', 5.7, 12592, 'tt1010409', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p507578573.jpg', 5.7, 23.2, 54.7, 13.5, 2.8, '0.191330,-0.024586,-0.562814,0.456796,-0.030849,-0.268141,0.767291,0.154246,-0.470551,-0.465291,-0.111631,0.485386,-0.175338,0.431896,0.125453,-0.271960,-0.042131,-0.423274,0.165034,0.065714,-0.184370,-0.043135,-0.308602,-0.176998,-0.233557,-0.212708,0.639884,-0.065794,-0.088160,0.355201,0.204144,0.399546,-0.318018,0.306493,-0.279112,-0.295760,-0.059696,-0.016521,-0.469055,0.215642,0.318474,0.093977,-0.025775,0.068633,-0.096065,0.248095,0.761602,-0.104995,-0.550878,-0.180606,0.424294,0.303684,0.000362,0.059975,0.087493,0.104473,0.340913,0.116303,-0.250222,0.203417,0.268653,0.025334,-0.780820,-0.040828,0.118135,-0.098847,-0.325526,0.554488,0.002778,-0.106077,0.187546,-0.355111,-0.092332,0.587780,0.381070,0.540522,-0.466441,0.088557,-0.368228,0.018165,0.608987,0.181169,-0.188345,0.635056,-0.477357,-0.621525,-0.052308,-0.313515,-0.573520,-0.004166,0.180952,0.573824,-0.060916,0.214608,-0.693364,0.142754,-0.088051,0.137762,0.081895,-0.245565,0.007042,-0.543184,-0.092666,-0.406086,-0.316664,0.073723,0.216162,-0.411444,0.590299,-0.806291,0.062147,0.335895,0.430133,-0.717405,0.590208,0.103344,0.313397,-0.441221,-0.117427,0.279166,-0.161581,0.104770,0.156635,0.429116,-0.267992,0.446047,-0.532985,0.405344', '3804470', '2053515', '4817024', '3262091');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2052978', '双食记', '剧情', '陈家桥（吴镇宇 饰）不是一个好情人，如果你十分在意他能随传随到的话。空姐coco（江一燕 饰）就十分饱受折磨，他偶尔天天出现给你惊喜，偶尔几个月不见人影，然而沉浸在爱河中的coco对于爱情和爱人是毫不怀疑的。一次与家桥争吵后家桥夺门而出，意外认识自称顾晓繁（余男 饰）的女人，她声称自己在电台教饮食节目，更是热心地教coco做菜的技巧以抓住家桥。Coco满怀感激，直到一天她发现了真正的顾晓繁与自己认识的女人并不相同……©豆瓣', '吴镇宇', '赵天宇', 7.1, 74926, 'tt1000775', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1153248157.jpg', 0.7, 5, 44.3, 40.1, 9.8, '-0.029606,-0.256964,-0.722782,0.489634,-0.217964,-0.092109,0.653803,-0.190087,-0.678068,-0.281606,-0.089073,0.503925,-0.235470,0.271958,0.210048,-0.289171,-0.135771,-0.619381,0.051972,-0.117763,-0.349436,-0.373694,-0.012535,-0.326062,-0.214985,-0.419738,0.396810,-0.092302,-0.130797,0.528682,0.347448,0.172606,0.015285,0.635085,-0.324617,0.052871,-0.030541,0.163859,-0.224311,0.093876,-0.013070,-0.104513,-0.326832,0.140796,-0.170812,0.252861,0.675451,-0.160513,-0.550287,0.047664,0.431426,-0.109802,-0.004596,-0.112334,0.044161,-0.071332,0.485502,0.040236,-0.250629,-0.196702,0.144441,-0.058529,-0.367932,0.208466,0.040627,0.128277,-0.650006,0.246294,-0.051236,-0.118338,0.193949,-0.332163,0.165319,0.115740,0.450587,0.418970,-0.238745,-0.040012,-0.572420,0.270921,0.525499,0.232732,-0.033915,0.670453,0.004755,-0.267208,0.008998,-0.088174,-0.504381,0.155953,-0.050591,-0.017466,-0.313228,-0.013839,-0.089535,0.060632,0.033822,-0.092664,0.059458,-0.677455,-0.251322,-0.487676,-0.007611,-0.333909,-0.475270,0.015306,-0.031751,-0.348902,0.620032,-1.262993,0.467066,0.307767,0.387394,-0.522238,0.989442,0.447754,-0.261438,-0.446185,-0.261963,0.043419,0.222739,-0.390590,0.067813,0.365292,-0.155081,0.096964,-0.286926,0.293513', '1302384', '2124718', '1308755', '22964524');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2053515', '曾经', '剧情', '这是一部由音乐开启的爱尔兰电影。　卖花女（Marketa Irglova）被街头艺人（Glen Hansard饰）的音乐所吸引，开始了一段荡气回肠的浪漫故事。他们不是王子和公主，各自有着琐碎的生活，但是他们有个共同点，那就是对音乐的热爱。在一次合奏中，他们找到了彼此间惊人的默契。这个发现让他们兴奋，很快他们找到了另外的一个同伴，组成了一个乐队，并通过优秀的表现得到了专业人士的肯定。与此同时，爱情也在逐渐萌芽。音乐是这部电影最大的亮点之一，塑造了极其浪漫唯美的氛围。©豆瓣', '格伦·汉塞德', '约翰·卡尼', 8.3, 272670, 'tt0907657', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2173720203.jpg', 0.3, 1.6, 16.8, 43.6, 37.7, '0.554010,-0.027548,-0.619022,0.966580,-0.082005,0.038717,1.047636,-0.042095,-0.625634,-0.145618,0.010305,0.928359,-0.359521,0.252883,0.075895,-0.121221,-0.356080,-0.675814,-0.014406,-0.112492,0.003516,-0.330951,-0.192032,-0.247346,-0.130023,-0.200525,0.877308,0.177397,-0.333571,0.549695,0.244186,0.025896,-0.101589,0.295425,-0.097756,0.036671,0.179830,-0.087053,-0.225814,0.245581,-0.041836,-0.231667,-0.020836,0.096167,-0.401313,0.345249,0.806827,-0.414882,-0.206137,0.361379,0.676437,-0.270046,-0.203084,-0.074686,-0.035464,0.202687,0.373387,0.069991,-0.291523,-0.014048,-0.323834,-0.224845,-1.222979,0.051090,0.172390,0.228376,-0.387230,0.612081,0.233926,-0.468308,0.370231,-0.162061,0.499723,0.212151,0.612669,0.490222,-0.175542,0.036597,-0.459972,0.308320,1.062168,0.155864,-0.496460,0.771329,-0.515666,-0.702107,-0.163952,-0.196936,-0.246833,0.077304,0.565820,0.073827,0.247344,-0.114378,-0.977465,0.277569,0.232803,-0.330405,0.045454,-0.902885,0.041780,-0.896218,-0.357437,-0.479270,-0.159518,-0.026957,0.012990,-0.407403,1.403255,-1.033037,-0.015684,0.653911,-0.026387,-0.482249,0.818777,-0.026743,0.065519,-0.106917,-0.145584,0.069888,-0.113402,0.137327,0.107697,0.697329,0.035531,-0.156959,-0.700604,0.573340', '27602116', '24284209', '3811356', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2053665', '降头', '恐怖', '重案组探员乐民（郑浩南 饰）赴泰国办案时结识流落风尘的钢管舞女郎阿丽（腾子萱 饰），两人迅速打得火热，乐民应承即日返来找她，却一直没有兑现承诺。一晃三年，发生警员被杀命案，警方锁定头号通缉犯林超（李德龄 饰），与此同时，乐民儿子离奇遇害，妻子嘉碧（邵美琪 饰）被吓得魂飞魄散，后又奇异症状缠身。腹背受敌的乐民与资深警探琛哥（林雪 饰）共同办案，经验丰富的琛哥怀疑一切是乐民在泰国欠下的桃花债种下的恶果，导致妻儿被人下了“降头”，乐民将信将疑之下，听琛哥指引找法师做法解决，不曾想这让他的困境和林超案又有了关联……©豆瓣', '郑浩南', '邱礼涛', 6.2, 6063, 'tt1010012', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2255616402.jpg', 2.6, 16.3, 54, 20.8, 6.3, '0.165044,-0.339640,-0.610720,0.081839,0.038603,0.020633,0.459762,0.029290,-0.563847,-0.141158,0.152253,0.551163,-0.261319,-0.065612,0.202954,-0.029914,-0.082256,-0.789045,-0.055657,-0.229833,-0.302478,-0.308585,0.118395,0.006068,-0.108198,-0.114130,0.268276,-0.023093,-0.038259,0.443812,0.392868,0.555584,-0.174150,0.414183,-0.056008,0.076257,0.169746,0.028941,-0.231672,0.147641,0.120114,-0.442063,-0.039483,0.013456,0.003041,0.252491,0.378837,-0.146362,-0.321408,-0.201940,0.175408,-0.377520,-0.018136,-0.121524,0.440665,-0.068296,0.106043,0.236956,-0.296944,-0.504494,0.125962,0.133583,-0.581212,0.223198,0.162237,0.205631,-0.563092,0.025575,-0.171620,0.239240,0.010428,-0.102374,0.474060,0.359959,0.310958,0.041644,-0.011971,-0.057041,-0.327116,0.440072,0.610125,0.073267,0.063739,-0.125809,-0.187255,-0.305888,0.053605,0.062303,-0.273528,0.216583,0.341799,-0.039681,-0.133071,-0.063964,0.030677,-0.172343,-0.298131,0.213766,-0.238471,-0.343593,-0.025431,-0.275019,-0.134127,-0.200334,-0.358224,0.063420,0.004725,-0.213540,0.274987,-0.459885,0.054350,0.385102,0.538013,-0.475456,0.419479,-0.012264,0.036646,-0.367594,0.014999,-0.120558,0.078474,0.373659,0.433480,0.333482,-0.127180,-0.167912,-0.051897,-0.194529', '1293829', '1306313', '25908042', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2054024', '妈妈咪呀', '喜剧', '苏菲（阿曼达·塞弗里德 Amanda Seyfried 饰）与斯盖伊（多米尼克·库珀 Dominic Cooper 饰）的爱情即将修成正果，两人正在为马上来临的婚礼紧张筹备着。不过，在苏菲的心中，一直有一个愿望，就是希望父亲能够在婚礼当天亲手将自己的手送到新郎的手上。可惜，妈妈（梅丽尔·斯特里普 Meryl Streep 饰）一直没有告诉过她到底谁是她的亲生父亲。不得已，苏菲偷看了妈妈的日记，发现其上记录的三个人中的一个很可能就是自己的亲生父亲。于是，她发出了三张请柬邀请他们来参加她的婚礼，想通过这短暂的接触，最终从三人中找出自己的爸爸。于是，在闺蜜的帮助下，在这美丽的希腊小岛上，上演了一出别具特色的寻父记。最终苏菲是否能找出自己的亲生父亲，举行一场完美的婚礼？©豆瓣', '梅丽尔·斯特里普', '菲利达·劳埃德', 7.6, 80589, 'tt0795421', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p705031957.jpg', 0.6, 4, 32.5, 43, 19.9, '0.225566,0.170438,-0.875169,0.795064,-0.158453,-0.350676,0.670209,-0.052937,-0.397232,-0.230785,0.322657,0.870352,-0.225412,0.336879,0.233610,0.139195,-0.233614,-0.771180,0.063552,-0.122299,-0.367477,-0.479622,-0.320954,0.059513,0.129095,-0.142117,0.462077,-0.170282,0.240850,0.395378,0.561275,0.117679,0.044104,0.271466,-0.297659,0.022023,-0.029258,0.087771,-0.270174,0.341623,0.289349,0.009375,-0.165318,0.382458,0.057433,0.435954,0.469219,-0.331649,0.101830,0.110252,0.476197,-0.223272,0.129890,0.290256,0.011901,-0.079722,0.290705,0.174916,-0.457473,-0.017432,0.252935,-0.119039,-0.791850,-0.041035,0.095815,0.160966,-0.545010,0.403508,-0.161882,0.017567,0.218673,-0.317030,0.353026,0.738521,0.134364,0.374517,-0.209778,-0.019807,-0.478815,0.125088,0.616780,-0.168340,0.210086,0.354675,-0.156917,-0.163311,0.094783,-0.198711,-0.577407,0.204018,0.397947,0.143426,-0.256126,-0.138127,-0.419285,-0.267683,-0.370811,-0.249427,0.224917,-0.488835,-0.069004,-0.372465,-0.035901,-0.271664,-0.436327,-0.133809,-0.138286,-0.568690,0.641847,-0.782219,0.211639,0.550481,0.283910,-0.172875,0.693159,0.423350,0.089537,-0.203614,-0.030081,0.184216,-0.030677,0.187014,-0.000427,0.283539,0.392958,-0.002880,-0.571308,0.586856', '3119246', '26021055', '1783461', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2054026', '结婚大作战', '喜剧', '居住在曼哈顿的莉芙（凯特·哈德森 Kate Hudson 饰）和艾玛（安妮·海瑟薇 Anne Hathaway 饰）是一对情同手足、从小一起长大的好姐妹。童年的某天，两人在第五大道的假日大酒店目睹了一场梦幻般的婚礼，从此，在这里举行婚礼的梦想便在她们各自的心中扎下了根。转眼二十多年过去，莉芙成为一名小有成就的律师，艾玛则在一所学校任教，两人也各自收获了美满的爱情。婚期在即，两个女孩子为了婚礼奔波劳碌，并相约担任对方的伴娘。然而令她们想不到的是，两人不仅都以假日大酒店为典礼举办地，而且还请了同一个司仪，更要命的是她们的婚礼都在同一天。这就意味着将有一方做出让步。为了童年的梦想，两个好友互不相让，由此也展开一场激烈且妙趣横生的新娘大作战……本片荣获2009年青少年选择奖最佳喜剧片女主角奖（Anne Hathaway）。©豆瓣', '安妮·海瑟薇', '盖瑞·温尼克', 6.7, 90883, 'tt0901476', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2200085243.jpg', 0.9, 8.2, 54.8, 28.9, 7.2, '0.190637,-0.142980,-0.813386,0.559921,0.222055,-0.406272,0.575923,0.097872,-0.208762,-0.103988,0.429228,0.897041,-0.491350,0.334082,0.659405,-0.151366,-0.167324,-0.846438,0.073161,-0.274103,-0.144201,-0.409390,0.129316,-0.053048,-0.077636,-0.194061,0.572736,-0.074656,0.381367,0.698583,0.677024,-0.157020,-0.185122,0.261454,-0.251986,-0.114144,0.096261,0.154589,-0.562206,0.332591,-0.079853,-0.146901,-0.258751,0.154073,0.181150,0.030830,0.891960,-0.122275,-0.012068,0.004244,0.384389,-0.235724,-0.142000,0.118751,0.530195,-0.317003,0.360673,0.247073,-0.237807,0.214644,0.096045,-0.253555,-0.663632,0.211742,0.290985,-0.113736,-0.613910,0.857089,0.277085,-0.228352,0.028792,-0.329182,0.225704,0.731972,0.120154,0.395671,-0.182842,0.052190,-0.486776,0.325089,0.956681,0.006165,-0.036655,0.430871,-0.174664,-0.506412,-0.142119,-0.145357,-0.564568,0.082803,0.155614,-0.011217,0.073590,0.152697,-0.686051,-0.001877,-0.240567,-0.267959,0.306950,-0.617939,0.174019,-0.870790,0.008187,-0.302912,-0.364159,0.208721,0.128388,-0.254748,0.746054,-0.918151,0.171679,0.437631,0.169761,-0.441468,0.940321,0.468504,0.654037,-0.093694,-0.162438,-0.009051,-0.211946,0.174104,0.011353,0.428219,-0.075706,0.152401,-0.429898,0.441900', '26687241', '11541282', '10876425', '3139191');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2054070', '老师的恩惠', '悬疑', '身体虚弱的朴老师（吴美熙饰）退休后隐居在远离人烟的海边，一年前收留的女学生美子（徐瑛姬饰）提议举行一个同学聚会，让老师开心一下。前来聚会的学生形迹怪异：将要结婚的班长世浩（余贤秀饰）和副班长恩英、身材火爆的顺姬（李智贤饰）、跛脚的达峰、帅气的明浩等来到了老师面前，却因为曾经都被朴老师伤害过而怨气冲天，正阳小时候母亲因为自己被记过去找老师理论时被车撞死而显得阴阳怪气。这夜，在纷纷控诉过老师对自己的伤害后，这群学生接二连三被穿着正阳的衣服戴着兔子面具的人杀死，只有朴老师与奋力保护她的美子幸存。警察在调查时发现朴老师当年并没有一个叫美子的学生，恐怖渐生。到底是谁的阴暗记忆毁了这一切？事实的真相与表面上看到的大相径庭。©豆瓣', '徐英姬', '林大雄', 6.8, 42042, 'tt0870958', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1055410077.jpg', 1.1, 7.3, 49.2, 33.2, 9.3, '0.307125,-0.275282,-0.442970,0.331205,-0.350804,-0.353680,0.647496,-0.004189,-0.499244,-0.569632,0.235977,0.621985,-0.246698,0.562044,0.270423,-0.088812,-0.153011,-0.605433,-0.100987,-0.120449,-0.500612,-0.386546,0.280885,-0.080473,-0.084467,-0.301347,0.493810,0.016974,-0.133370,0.768827,0.362623,0.069112,-0.043846,0.477410,-0.061340,0.027403,0.063501,0.018013,0.012002,0.051880,0.178501,-0.211427,-0.102244,0.184096,0.046208,0.389580,0.611834,-0.044011,-0.428143,-0.069597,0.405034,-0.296777,-0.003840,0.442446,0.513120,0.041470,0.310829,0.044082,-0.006166,-0.135954,-0.050301,-0.119963,-0.378871,0.155414,0.117757,0.112883,-0.416216,0.575783,0.128781,-0.114429,0.206551,-0.272405,0.297265,0.157113,-0.028721,0.387823,-0.134059,0.150668,-0.196583,0.263370,0.755156,0.048610,0.025046,0.187310,-0.245774,-0.245219,0.009497,-0.204213,-0.573910,0.568712,-0.131554,-0.065481,-0.284455,0.018528,-0.474061,-0.205654,-0.158713,0.183233,-0.106917,-0.422808,-0.431309,-0.272207,-0.004323,-0.253128,-0.228120,0.130224,-0.173092,-0.200101,0.778051,-0.951694,0.230281,0.413925,0.511818,-0.282278,0.618617,0.188688,-0.078124,-0.075198,-0.179791,0.043467,0.399126,0.492206,0.171680,0.408129,0.037516,-0.338316,-0.390855,0.193612', '1292219', '35030151', '1306544', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2054932', '虐童疑云', '剧情', '1964年，美国纽约布朗克斯区，圣尼古拉斯天主学校。修女阿洛伊修斯•贝维尔（Meryl Streep 梅丽尔•斯特里普 饰）令行禁止，教条严明，为学生们所畏惧；而新来的布伦丹•弗林的神父（Philip Seymour Hoffman 菲利普•塞默•霍夫曼 饰）则态度和蔼，处事开明，受到学生们的喜爱。这期间，弗林尤其关心学校内有史以来第一位的黑人学生唐纳德•米勒（Joseph Foster 饰）。某天，詹姆斯修女（Amy Adams 饰）将唐纳德的奇怪表现报告给贝维尔修女。贝维尔认定弗林正与男孩发展不正当的关系，她决心不惜一切代价制止。然而事实究竟怎样？©豆瓣', '梅丽尔·斯特里普', '约翰·帕特里克·尚利', 7.6, 27067, 'tt0918927', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2460435206.jpg', 0.3, 2.5, 28.9, 51.6, 16.7, '0.489405,-0.173019,-0.270321,0.321509,0.192577,-0.222255,0.372479,0.140957,-0.420790,-0.601876,0.253253,0.330599,-0.011757,0.005402,0.751179,0.095809,-0.626737,-0.255540,-0.201476,-0.149511,-0.008315,-0.698335,-0.152115,-0.605087,-0.160196,-0.496733,0.069894,-0.255934,0.342471,0.527385,0.381831,0.699314,0.564602,0.016342,0.688065,-0.145527,0.721660,-0.338549,-0.072174,-0.097590,-0.008979,0.222494,-0.231254,0.412585,0.531522,0.302259,0.322215,-0.468908,0.281143,-0.230552,0.261017,-0.133695,0.347346,0.345704,0.145981,-0.185488,-0.054488,0.231219,0.279027,-0.184495,0.075345,-0.409666,-0.363956,-0.011002,0.173313,0.104830,-0.415723,0.098945,-0.358474,0.086200,0.102187,-0.142131,-0.378415,0.017406,0.665678,0.319198,0.031731,-0.110858,-0.090023,-0.157756,0.466394,0.149611,-0.319609,-0.352893,-0.793259,-0.528309,0.017634,-0.341942,-0.580336,0.115833,0.207737,-0.086693,0.386601,0.574077,-0.118351,-0.532920,-0.400661,0.029370,-0.173499,-0.298540,-0.211366,-0.764822,0.124991,-0.241842,-0.143953,-0.395553,-0.189962,-0.030150,0.804940,-0.608992,0.468677,0.316667,0.209175,-0.292846,0.633939,0.116705,0.258261,-0.506621,-0.479171,0.713497,0.400147,-0.114485,-0.194073,0.188169,0.061425,-0.395670,0.466897,0.282003', '1293572', '1303010', '2364001', '27031237');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2054933', '阅后即焚', '剧情', '本片根据曾于1977年至1981年间担任美国中央情报局局长的斯坦菲尔德·特纳的小说《高度机密：总统、中情局局长和特工》改编而成。Osbourne（约翰·马尔科维奇 John Malkovich 饰）是CIA的资深分析员，因酗酒问题被开除。沮丧的Osbourne回到家中又不被老婆重视。他妻子Katie（蒂尔达·斯文顿 Tilda Swinton 饰）是个冷冰冰的职业医生，与财政部的Harry（乔治·克鲁尼 George Clooney 饰）偷情，在船上共度春光。Osbourne赌咒写一本自传来透露CIA的高极机密，却被一心想跟自己离婚的Katie错拿去记录调查自己的财政报告，后又不慎落在了健身房。被傻里傻气的健身房女员工Linda（弗兰西斯·麦克多蒙德 Frances McDormand 饰）和稍有点二百五的健身教练Chad（布拉德·皮特 Brad Pitt 饰）拾得，这下一直为整容手术费用发愁的Linda有了主意，决定去敲诈。这一群人的命运就因为这张光盘而发生了变化。', '乔治·克鲁尼', '伊桑·科恩', 7.1, 81407, 'tt0887883', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p791820195.jpg', 1.1, 5.9, 40.1, 41.6, 11.4, '0.356390,-0.295611,-0.499860,0.387927,-0.215191,-0.472222,0.667969,0.372573,-0.476580,-0.362261,0.228482,0.807427,-0.347326,-0.061951,0.344794,0.147195,-0.405288,-0.650674,-0.040339,-0.143157,0.023892,-0.607155,-0.152248,-0.237682,-0.018066,-0.335024,0.214591,-0.287017,-0.119580,0.257740,0.286353,0.446962,0.229635,0.199700,-0.045901,0.190530,0.178400,-0.132917,0.070532,0.064598,0.329131,-0.260114,-0.044531,-0.125233,0.206636,0.552047,0.446907,0.104465,-0.172985,-0.055426,0.443535,-0.231931,-0.076729,0.087603,0.444086,0.190447,-0.060705,0.364004,-0.431640,0.065901,0.210574,-0.097690,-0.689011,0.004821,0.061830,0.392963,-0.450680,0.358298,-0.461988,-0.048859,0.006901,-0.190890,0.227350,0.274657,0.152409,0.357438,0.130861,0.025327,-0.429743,0.341288,0.203329,0.120635,-0.008821,0.201855,-0.137490,-0.372899,0.071136,-0.089046,-0.426786,0.005030,0.309913,-0.186440,0.032279,-0.017619,-0.459760,-0.129066,-0.262115,-0.289101,-0.276401,-0.382485,-0.330118,-0.436206,-0.090313,-0.213627,-0.308876,0.029196,0.269959,-0.064135,0.443342,-0.694510,0.081151,0.424714,0.097468,-0.406031,0.565396,0.160790,-0.044196,-0.187888,-0.011237,-0.012863,0.298254,0.501370,0.078147,0.420745,0.176443,-0.541242,-0.130770,0.329897', '1293145', '1783461', '3119246', '1299799');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2055017', '练习曲', '剧情', '为免日后回想过往时后悔，大学即将毕业的明相（东明相）请假只身骑上脚踏车，开始了以高雄为起点的逆风向的环岛旅行。明相一路所遇，除了各地美不胜收的风景，还有形形色色的人：想借助影像制造梦想的工作者，正一心一意地将太平洋的风捕捉入镜；来自立陶宛的年轻女模特，在花莲的海边告诉他她的国家没有山；即将退休的小学女教师，向他讲述自己恋恋不舍的心情；导游兼司机的陌生人（吴念真）一边和他分享盒饭，一边告诉他眼前这群下岗女工的生活……而更重要的，是通过与这些的人的短暂接触和所吃的无数苦头，明相对生命有了更深一层的认识，他知晓了属于自己的生命练习曲，才刚刚开始。©豆瓣', '东明相', '陈怀恩', 8, 52933, 'tt1006908', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1175865579.jpg', 0.4, 2.4, 23.4, 45.7, 28.1, '0.525991,-0.105491,-0.609633,0.715970,-0.045439,-0.388859,0.586843,0.096748,-0.412671,-0.198316,0.086940,0.812469,-0.035867,0.343959,0.316819,-0.026316,-0.322522,-0.722429,-0.148290,-0.130253,-0.285630,-0.359942,-0.240730,-0.025657,-0.216233,-0.168761,0.686641,0.159665,-0.181034,0.382421,0.189333,0.133468,-0.020428,0.438531,-0.535236,-0.040932,-0.246352,0.187692,-0.412764,-0.076847,0.123926,-0.412248,-0.343244,0.150374,0.021604,0.298582,0.854605,-0.026203,-0.283831,-0.126930,0.467236,-0.291627,0.159542,-0.033915,0.045788,0.208497,0.038953,0.059948,-0.040979,0.061982,-0.155416,-0.040768,-0.789731,-0.177513,0.128789,0.077681,-0.445402,0.297601,-0.005482,-0.102725,0.490631,-0.342182,0.298915,0.470772,-0.065101,0.533307,-0.190427,-0.032291,-0.441606,0.385849,0.755353,0.211063,-0.117958,0.407351,-0.123129,-0.298179,-0.123284,-0.074862,-0.393535,-0.030561,0.088426,0.265871,-0.310267,0.235976,-0.599926,0.146066,0.037784,-0.423378,0.152142,-0.482503,-0.254556,-0.684582,-0.016617,-0.602904,-0.142090,-0.022636,0.194001,-0.334461,0.970341,-0.791470,0.095851,0.754484,0.499498,-0.574697,0.831917,0.027884,0.037791,-0.215714,-0.088977,0.151717,0.064188,0.494948,-0.032880,0.457158,-0.057288,-0.128948,-0.449636,0.493422', '3811356', '25928048', '30162520', '24733428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20552089', '小叮当与海盗仙子', '动作', '无忧无虑的精灵谷中央，对一切事物都充满好奇心并勇于挑战新鲜事物的小仙子萨瑞娜（克里斯蒂娜·亨德里克斯 Christina Hendricks 配音），被加利仙子派遣管理仙尘。虽然加利仙子再三告诫她严禁篡改仙尘，但终究无法阻挡萨瑞娜踏足未知领域的渴望。受到批评后，萨瑞娜失落地离开精灵谷。一年后，在小精灵的盛大庆典上，萨瑞娜突然返回，她催眠了会场内绝大部分小精灵，并盗走了珍贵的蓝色仙尘投奔海盗。侥幸逃过一劫的小叮当（梅·惠特曼 Mae Whitman 配音）和伙伴们发现自己的魔法正在流失，为了拯救精灵谷，她们尾随着萨瑞娜踏上新的冒险之旅……©豆瓣', '梅·惠特曼', '佩吉·霍姆斯', 7.8, 7453, 'tt2483260', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2161798908.jpg', 0.3, 1.8, 29, 44.2, 24.7, '0.091995,0.325933,-0.457691,0.575114,0.157818,-0.202149,0.520029,-0.125631,-0.509648,-0.106771,0.053374,0.528834,-0.077341,0.235852,0.326356,0.118695,-0.385637,-0.198371,-0.126421,-0.381395,-0.158656,-0.113482,-0.060870,-0.233016,-0.255130,-0.507957,0.692098,0.233157,-0.356762,0.578068,0.199183,-0.023676,-0.283046,0.446625,0.270956,-0.257181,0.228917,0.124935,-0.248079,0.149128,-0.211130,-0.029164,-0.056272,0.196521,0.215465,0.220759,0.692852,-0.797084,-0.010849,-0.402876,0.040121,-0.347548,0.137019,0.171048,0.103248,0.206728,0.161306,0.061495,-0.161263,-0.036410,-0.142680,-0.423850,-0.387224,-0.099835,0.273566,0.077318,-0.224671,0.086123,0.206048,0.404048,0.137654,-0.358503,-0.201863,0.192864,0.242726,0.281027,-0.025483,-0.094159,-0.073301,0.371479,0.737839,-0.220680,-0.179369,0.037004,-0.408215,-0.617439,0.010774,-0.114021,-0.461773,-0.070250,0.313666,0.458578,-0.038756,0.417611,-0.582294,0.134093,-0.342603,-0.287242,-0.117133,-0.494520,0.014470,-0.855610,0.208903,0.006794,-0.209989,0.022185,0.222905,-0.233308,0.640952,-0.884807,0.666838,0.477884,0.305708,-0.352048,0.343356,-0.111943,0.106829,-0.134569,-0.480449,0.914827,0.104555,0.758097,-0.009819,0.103949,-0.097939,-0.153096,-0.403787,0.139034', '2369613', '1420088', '2159244', '1309064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2055699', '不后悔', '剧情', '《不后悔》是韩国电影史上第一次将同性恋酒吧做为背景的电影。该片从2006年11月16日开始上映不到两周，观众人数突破3万。从小在孤儿院长大的洙民（李永勋 饰）来到首尔谋求，虽坚苦但却很充实。一天他受雇替酒后开车的宰民（金南佶 饰）开车，一见到洙民宰民就对他产生了好感并 向其做出了暗示，但洙民拒绝了好意并辞去代驾的工作。洙民工作的工厂开始内部裁员，无路可去的洙民最后只有抛下自尊来到了一间同性恋酒吧工作。另一边，要与家族安排的未婚妻结婚在即，但对洙民的感情却让宰民还是一无反顾的去找洙民。洙民虽然屡次拒绝却发现自己的心渐渐系在宰民身上，终于两人无可避免的相爱了。忽然有一天宰民的母亲发现了这段恋情，他们的爱情陷入了僵局，宰民在现实和爱情面前痛苦万分，而把宰民视做全部的洙民也陷入了前所未有的绝望。在这个冰冷的城市他们热烈的爱将有何去何从？©豆瓣', '李永勋', '李宋喜一', 7.6, 16063, 'tt0996948', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p537034124.jpg', 0.8, 4.1, 32.8, 40.8, 21.5, '0.090119,0.154001,-0.622459,0.363010,-0.070562,-0.299132,0.623988,0.318547,-0.525841,-0.247027,0.044752,0.782673,-0.331329,0.156805,0.367555,-0.106513,-0.277315,-0.734351,-0.026052,-0.244912,-0.291570,-0.442258,0.227282,-0.107068,-0.256932,0.049957,0.713120,0.236133,-0.064674,0.512014,0.407400,0.200358,0.088326,0.856730,0.087029,0.151184,-0.168858,0.151757,-0.241597,0.017464,0.043502,-0.514640,-0.272557,0.305017,0.115139,0.466418,0.733584,0.059860,-0.466467,0.079782,0.509773,-0.360142,-0.278590,-0.001352,0.302098,0.146968,0.017826,0.279182,-0.316680,0.106526,-0.054455,-0.207798,-0.736782,0.028508,-0.220423,-0.099563,-0.536599,0.440214,-0.030822,-0.110138,-0.113191,-0.357422,0.172672,0.553162,-0.004753,0.481734,-0.381514,0.050920,-0.559238,0.131659,0.890030,0.040496,-0.138357,0.508238,-0.182839,-0.400981,-0.135195,-0.079553,-0.349386,-0.208447,0.149746,0.205718,-0.309711,-0.053513,-0.480706,-0.056842,-0.128928,-0.368050,0.097460,-0.586905,0.091744,-0.294379,-0.227651,-0.223544,-0.356451,0.161397,-0.008369,-0.208557,0.671546,-1.052753,0.165796,0.364947,0.581802,-0.548010,0.785601,0.232495,-0.016409,-0.067061,-0.020951,0.474194,-0.056203,0.325312,0.243667,0.253100,-0.043404,-0.157013,-0.335065,0.329749', '1301022', '35030151', '1395231', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2056653', '巴黎小情歌', '剧情', '伊斯麦（路易斯·加瑞尔 Louis Garrel 饰）和茱莉（露迪芬·莎妮 Ludivine Sagnier 饰）是一对产生裂痕的情侣，因此异想天开找来伊斯麦同事爱丽丝（克劳迪德·埃斯曼 Clotilde Hesme 饰）加入他们，试图用三人行为爱情增加激情。但三个人的爱情，终究只是烦恼的叠加，一场争吵之后，茱莉突发心脏急病倒在酒吧。如今剩下伊斯麦和爱丽丝的二人世界，可是愧疚和想念令伊斯麦无福消受，茱莉的家人也开始以“关怀”的姿态进入伊斯麦的生活，尤其是其姐珍娜（基娅拉·马斯特洛亚尼 Chiara Mastroianni 饰）近乎骚扰地出现在他家里，令他快要发疯。为了逃避一切，伊斯麦躲到好友家，却又引来好友弟弟伊旺（格雷戈瓦·勒普兰斯-林盖 Grégoire Leprince-Ringuet 饰）的热烈追求……巴黎的雨总是不停息，正如伤心的男人永远走不出一段已死情感的阴影……', '路易·加瑞尔', '克里斯托夫·奥诺雷', 7.4, 16898, 'tt0996605', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2536713509.jpg', 0.8, 4.2, 35.6, 41.8, 17.7, '0.339734,-0.139021,-0.574474,0.451610,0.196088,-0.308953,0.769201,0.416898,-0.239614,-0.181930,0.029553,0.571052,-0.420210,0.217002,0.379645,0.002141,-0.315216,-0.541199,0.340508,-0.018255,-0.202501,-0.497942,0.054756,-0.417326,-0.221058,-0.385606,0.323766,0.089002,-0.139945,0.603120,0.218884,0.626662,0.137680,0.539099,0.277287,-0.009480,0.092781,-0.069615,-0.223705,-0.101801,0.210014,0.181997,-0.012215,0.314519,0.078149,0.303263,0.544010,-0.293209,0.323150,0.160014,0.088773,-0.257884,0.325193,-0.200357,0.085925,-0.362202,-0.014681,-0.112188,-0.155505,-0.224060,0.059572,-0.050091,-0.408154,0.162210,0.212863,0.043325,-0.455484,0.363627,-0.156992,0.330518,0.179981,-0.007566,-0.102445,0.324060,0.308475,0.491466,-0.063026,0.022597,-0.491317,-0.232663,0.496422,0.035187,-0.358662,0.312040,-0.496709,-0.304295,-0.103558,-0.015542,-0.772207,-0.185252,0.177213,-0.175667,0.122555,0.688832,-0.722658,-0.195179,-0.529467,0.066559,0.269637,-0.475089,-0.004586,-0.518377,-0.057507,-0.209335,-0.396100,0.098482,-0.041528,-0.306465,0.419448,-0.663418,0.503228,0.491475,0.193983,-0.205452,0.550131,0.118500,0.237144,-0.264562,-0.094396,0.752712,0.138182,-0.026162,0.352812,-0.026563,0.013225,0.237502,-0.525149,0.486484', '4896894', '1305666', '3097044', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2057552', '第39号案件', '悬疑', '社工艾米丽·詹金斯（芮妮·齐薇格 Renée Zellweger 饰）做着单调、繁冗的工作，她每天要和不同的家庭打交道，处理他们的子女教育问题，结果得到的抱怨远远多于感谢。原本的38宗案件已经不堪重负，上司又将第39号案件安排给她。迫于责任，疲惫的艾米丽依旧驱车前往小女孩莉莉·沙利文（祖蒂·弗兰 Jodelle Ferland 饰）的家中。一如既往，艾米丽受到不友好地对待，在此之外，这个家庭的怪异气氛又让她倍感焦虑。有感于莉莉的孤独和无助，艾米丽更为主动地参与到这个案件中来。在一个残酷的虐待之夜，她和同事从莉莉的父母手中将小女孩成功解救。一切似乎告一段落，一切又似乎刚刚开始……©豆瓣', '蕾妮·齐薇格', '克里斯蒂安·阿瓦特', 6.8, 28285, 'tt0795351', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2249524384.jpg', 0.8, 7, 50.5, 33, 8.6, '0.496483,0.093053,-0.776607,0.409618,-0.204358,-0.148922,0.740568,0.197111,-0.407082,-0.392770,0.188564,0.831278,-0.016203,0.414836,0.313462,0.101275,-0.396325,-0.586222,-0.115091,0.080937,-0.248877,-0.589348,-0.034094,-0.279323,-0.189132,-0.238908,0.469082,-0.075573,-0.021535,0.653332,0.199467,0.423913,0.038316,0.883510,0.059300,-0.033454,0.146727,0.200928,-0.170218,0.007751,0.185732,-0.161089,-0.287771,0.379544,0.134081,0.488190,0.782733,-0.152775,-0.298104,0.059733,0.426450,-0.329153,-0.022085,0.226996,0.248437,0.063814,0.043868,0.372253,-0.396682,0.058568,0.160614,-0.133223,-0.731490,-0.051722,0.189971,0.188914,-0.587688,0.423760,-0.164330,0.139048,0.315603,-0.486310,0.169346,0.511049,0.238495,0.708102,-0.240734,-0.103856,-0.297591,0.106380,0.684567,0.103011,-0.199050,0.266508,-0.531180,-0.343183,0.078002,-0.304019,-0.563582,-0.013693,0.236575,0.064397,-0.212590,0.467991,-0.663365,-0.023426,-0.233851,-0.365541,-0.246797,-0.631253,-0.020443,-0.692208,-0.016634,-0.455242,-0.483169,-0.199694,0.040393,-0.375711,0.661427,-0.687612,0.196640,0.509838,0.300365,-0.431510,0.345997,0.390895,0.454858,-0.224671,-0.222519,0.191087,-0.033472,0.374226,0.119277,0.294034,0.008435,0.001307,-0.422668,0.328448', '25839662', '3059036', '1301022', '27042738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2058735', '超级女特工', '剧情', '1940年，丘吉尔设立了一个新的情报组织“特别行动局”，简称SOE。其中一个分部负责监督法国的行动。1944年，为了确保盟军登陆成功，这个分部付出了沉重的代价。Louise（苏菲·玛索 Sophie Marceau 饰）刚刚失去丈夫，被哥哥带回法国参加SOE，接受的任务是救出落入敌手的一位英国地质学家——他手中拥有的是德军布置在诺曼底的防御工事图，几乎是盟军登陆的全部关键。和Louise共同作战的还有其他几位姑娘。妓女Jeanne（茱莉·德帕迪约 Julie Depardieu 饰）因为杀害自己的客人而被判死刑，SOE承诺只要她完成任务即可获得豁免。随后加入的Suzy、Gaëlle，都是有着一段不为人知的伤心往事。当她们为了盟军而贡献自己的聪明才智，任务能否成功，她们又是否能全身而退？©豆瓣', '苏菲·玛索', '让-保尔·萨罗米', 7.1, 22133, 'tt0824330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2097796413.jpg', 0.5, 4.6, 44.6, 40.1, 10.2, '-0.027662,0.121574,-0.446433,0.596406,-0.285846,-0.163417,0.251937,-0.174945,-0.264056,-0.290112,0.344426,0.720552,0.398567,-0.077620,0.212804,-0.150927,-0.258820,-0.661604,0.024785,-0.387127,-0.492944,-0.515161,-0.234002,-0.472972,-0.025367,-0.329634,0.825335,0.218370,-0.155375,0.162126,0.449563,0.357381,-0.144228,0.276611,-0.036291,-0.323131,0.220605,-0.274970,-0.466532,0.432120,-0.285795,-0.111840,-0.065745,0.157956,0.125129,0.478480,0.589193,-0.207151,-0.241374,-0.285754,0.215778,-0.484432,0.164946,0.077665,0.075277,0.169317,0.172517,0.390478,-0.425666,0.062306,-0.020224,-0.469993,-1.116695,-0.363376,0.414061,0.039825,-0.328943,0.260859,-0.280169,0.257550,0.098992,-0.211610,0.134772,0.820924,0.186054,0.277774,-0.273471,0.219430,-0.588277,0.182167,0.771656,-0.326553,-0.063359,-0.080974,0.049238,-0.482959,0.198022,-0.437138,0.025245,0.419812,0.179280,0.057763,0.370840,0.047445,-0.711221,-0.010404,-0.431399,-0.445370,0.088494,-0.480010,0.131589,-0.684883,-0.059803,0.029858,-0.357580,0.176056,0.195004,-0.349831,0.956982,-0.843593,0.053755,0.502926,0.410517,-0.754909,0.480569,0.431925,0.379081,-0.326896,-0.002463,0.181528,-0.060762,0.320074,-0.119715,0.044419,0.097623,-0.307053,-0.381592,0.130300', '26678784', '30163500', '27009869', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2058751', '凯撒万岁', '喜剧', '艾迪（乔什·布洛林 Josh Brolin 饰）是一名效力于国会制片厂的制片人，表面看来，这是一份光鲜亮丽的职业，艾迪整天出入于高端场所和宴会之中，打交道的都是大明星和各路社会名流，可实际上，艾迪真正在干的，是帮这群整天闲着没事干尽惹麻烦的巨婴们“擦屁股”的活计。导演劳伦斯（拉尔夫·费因斯 Ralph Fiennes 饰）不小心让知名女明星狄安娜（斯嘉丽·约翰逊 Scarlett Johansson 饰）怀孕了，艾迪必须想办法让这件事成为永远的秘密。酗酒成性的老演员拜尔德（乔治·克鲁尼 George Clooney 饰）在新片即将开机之前竟然遭人绑架，筹得10万美元赎金的活也落在了艾迪的头上，除此之外，艾迪还要谨防对明星八卦虎视眈眈的双胞胎娱记赛克姐妹（蒂尔达·斯文顿 Tilda Swinton 饰）。©豆瓣', '乔什·布洛林', '伊桑·科恩', 6.5, 14333, 'tt0475290', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2306316825.jpg', 1.8, 12.2, 53.7, 26, 6.3, '0.073943,-0.344076,-0.344905,0.250945,-0.345939,-0.253043,0.351217,0.279206,-0.369926,-0.260477,0.120928,0.698566,-0.275964,0.002181,0.291394,0.087145,-0.398204,-0.546132,0.087878,-0.111239,0.187337,-0.432059,-0.344367,-0.191500,-0.223338,-0.307663,0.240722,-0.269403,0.165626,0.157645,0.708903,0.245559,0.018597,0.048040,0.069311,-0.116335,0.223732,-0.143900,-0.125280,0.212378,0.055638,0.031670,-0.041646,-0.099119,0.494289,0.293562,0.148832,-0.113091,0.079909,-0.083936,0.260070,-0.153703,0.151540,0.108433,0.210609,-0.198565,0.248285,0.363212,-0.304612,0.279657,0.374504,-0.038807,-0.658957,0.062621,0.261712,0.222475,-0.781679,0.392179,-0.183405,-0.213612,-0.001227,-0.031301,0.308718,0.265075,0.228882,0.237433,0.166123,0.066971,-0.477005,0.260991,0.309031,0.369169,-0.034024,0.141383,-0.134739,-0.087250,-0.267676,-0.302424,-0.551812,-0.038054,0.117765,-0.451891,0.010201,0.357157,-0.497604,-0.209791,-0.077544,-0.245762,0.045348,-0.228663,-0.028631,-0.706698,0.097600,-0.388228,-0.203680,-0.141392,0.226926,-0.185767,0.653123,-0.533970,0.113380,0.690297,0.182811,-0.369336,0.676204,0.294406,0.220754,0.071439,-0.362006,-0.117706,0.378008,0.042735,-0.040471,0.302673,0.159179,-0.587128,0.150452,0.254822', '1299799', '4301278', '1498811', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2058846', '激战运钞车', '动作', '哈克特（哥伦布·绍特 Columbus Short 饰）、拜尼斯（劳伦斯·菲什伯恩 Laurence Fishburne 饰）、杜比斯（斯基特·乌尔里奇 Skeet Ulrich 饰）、潘梅尔（阿莫里·诺拉斯科 Amaury Nolasco 饰）几个人都任职于一个保安公司。每天的工作就是开着荷枪实弹的装甲车负责押运上千万的现款。大家最近都面临着一个严峻问题——缺钱，于是几个人不免开始动起了歪脑筋。虽然哈克特不情愿，不过其他人的威逼利诱下，他最终还是半推半就的加入了该计划，他们的目标是：打劫自己押运的4200万现金。有老朋友同时也是这方面的行家奎因（让·雷诺饰）帮忙，事情进行得相当顺利。不过在实施计划的当天，一切在计划中的事情突然被一件意外之事打断：有人开枪打死了一个无辜的流浪汉。哈克特因此想退出因而和众人产生了分歧。原本看似坚固的兄弟之情，因为这起意外而开始产生裂痕……', '马特·狄龙', '尼姆罗德·安陶尔', 5.7, 8427, 'tt0913354', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p769178529.jpg', 6.5, 22.9, 54.2, 13, 3.3, '0.528395,-0.138153,-0.728845,0.350778,-0.029047,-0.224755,0.521585,0.025724,-0.560248,-0.287689,0.270741,0.700461,-0.117019,-0.054421,0.174414,-0.016832,-0.527260,-0.521132,0.047779,-0.217129,-0.259191,-0.630222,-0.032860,-0.519558,-0.175223,-0.208377,0.140079,0.156043,0.094003,0.400679,0.206645,0.398370,0.235588,0.501657,0.256888,-0.004768,0.211540,-0.292292,-0.025856,0.036172,-0.000565,-0.125650,-0.299873,0.378626,0.338616,0.651557,0.299934,-0.250454,-0.246606,0.087045,0.121668,-0.354908,0.152493,0.131292,0.224151,-0.090965,0.151456,0.267557,-0.362511,0.089462,0.133559,-0.088395,-0.646721,-0.060447,0.001502,0.201465,-0.704751,0.204800,-0.179693,0.120302,-0.069585,-0.286560,0.006530,0.412832,0.383181,0.122009,0.065487,-0.201433,-0.488318,-0.190210,0.618066,-0.016747,-0.235913,0.201256,-0.193691,-0.241298,-0.242648,-0.011564,-0.361730,-0.016018,0.437495,-0.138830,0.176586,0.256989,-0.627889,-0.044424,-0.275011,-0.232819,-0.480410,-0.223891,0.127611,-0.478256,0.200220,-0.198716,-0.572015,0.214193,0.144793,-0.012881,0.374508,-0.673943,-0.000346,0.501000,0.262320,-0.431404,0.219185,0.035944,0.169843,-0.222479,-0.222447,-0.277369,0.039805,0.072488,0.177933,0.410473,0.262813,-0.451414,-0.072944,0.231697', '1292849', '25908042', '35461732', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2059225', '左右', '剧情', '枚竹（刘威葳 饰）和丈夫肖路（张嘉译  饰）离婚多年，带着女儿禾禾嫁给了老谢（成泰燊  饰），肖路也和空姐董帆（余男 饰）重新组建了一个家庭。禾禾被查出得了白血病，普通的化疗并没有很好的控制住病情，为了救禾禾，枚竹找到了肖路，提出想和他再生一个孩子，肖路无奈答应；经过三次人工授精的失败后，枚竹决定和肖路来真的，两个人的家庭也卷入了其中，四个人都经受着巨大的考验，面对选择，左右为难。©豆瓣', '刘威葳', '王小帅', 6.5, 24898, 'tt1018102', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p661597159.jpg', 1.9, 9.9, 53.6, 28.6, 6, '-0.173611,0.113169,-0.608436,0.440138,-0.419319,-0.372674,0.467717,0.130323,-0.539625,-0.151019,-0.061401,0.345144,-0.164770,-0.139620,-0.030839,-0.085390,0.096159,-0.425498,-0.188646,0.012663,-0.628849,-0.496613,-0.009592,0.174448,-0.150534,-0.192652,0.286489,-0.224719,0.078872,0.268246,0.528563,0.476319,-0.099821,0.198530,-0.105905,0.063066,-0.266511,0.246696,-0.404312,0.080658,0.130253,-0.244998,-0.259843,0.033179,0.281074,0.285333,0.749397,-0.028445,-0.206981,-0.176143,-0.119131,-0.346291,-0.519021,-0.028737,0.097494,0.037346,0.170291,0.163180,-0.541359,-0.090224,0.359190,0.178416,-0.699661,0.056755,0.356474,0.015357,-0.691902,0.499923,-0.300489,0.086672,-0.173311,-0.682545,0.022167,0.293371,0.125834,0.461733,-0.499727,0.041831,-0.623115,0.373273,0.766000,0.051296,-0.015365,-0.029990,-0.204875,-0.522189,-0.120529,0.166671,-0.566964,0.244252,0.332893,0.052552,-0.541908,-0.299862,-0.342463,-0.132932,-0.562757,-0.059489,0.134637,-0.587004,0.237981,-0.346225,-0.016925,-0.220333,-0.743451,0.083647,0.009862,-0.488446,0.639318,-0.458171,0.321347,0.080382,0.558645,-0.340957,0.334915,0.198534,0.400300,-0.332082,0.065789,-0.157471,-0.239149,-0.246775,0.428878,0.478862,-0.056121,-0.166165,-0.363639,-0.035588', '1306530', '1877596', '35461732', '1308979');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2059276', '哥斯拉', '剧情', '二战结束后不久，日本南海惊现离奇事件，打捞船荣子丸在平静的海面上突然遇难，幸存者寥寥，前去搜救的宾果丸也一去不返。不久，南海附近的岛屿大户岛遭受到恐怖的袭击，岛上的老人声称这便是传说中的怪兽哥斯拉作怪。古生物专家山根京平教授受命前往调查，根据现场遗留的痕迹断定，这个怪物是200万年前侏罗纪时代存活下来的恐龙，并且在原子弹辐射的影响下，化身为更具破坏力的恐怖怪兽。该论断一经公布，便在日本国内引起轩然大波。政客和军队纷纷行动，意欲置哥斯拉于死地。而哥斯拉也闯入东京，进行一场毁灭性的破坏。人类的命运悬于一线……本片根据香山滋的科幻小说改编。©豆瓣', '宝田明', '本多猪四郎', 7.7, 5506, 'tt0047034', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2172120157.jpg', 0.8, 3.1, 29.5, 44.8, 21.8, '0.176580,0.150915,-0.881978,0.547416,0.340453,0.347255,0.583529,-0.222463,-0.301727,0.070998,0.414356,0.781721,-0.295889,-0.204714,0.058949,-0.158917,-0.261994,-0.224973,-0.150351,-0.164081,-0.315416,-0.238171,-0.588587,-0.246005,0.184274,-0.403254,0.651573,0.485123,-0.488884,0.513037,-0.038118,0.440273,-0.481210,0.463222,-0.016043,-0.026430,-0.176347,0.128891,-0.250671,0.261464,-0.233613,-0.371372,0.198310,0.038002,-0.166765,0.234138,0.783604,-0.528634,-0.305976,-0.308850,0.427387,-0.335847,-0.111869,0.058750,1.001404,0.043590,0.015647,0.192846,-0.135875,0.001695,-0.147249,0.028937,-0.437745,-0.239786,0.071566,0.272679,-0.195056,0.222717,0.112846,0.101884,-0.144172,-0.117538,0.260591,0.384793,0.251436,0.310131,0.057486,-0.037544,-0.229046,0.262064,0.768093,-0.178815,-0.442821,-0.270773,0.178204,-0.663911,-0.023223,-0.319268,0.073597,0.159383,0.348234,0.010473,-0.476911,0.456995,-0.657854,0.116237,-0.491986,-0.446283,-0.170374,0.061101,-0.266787,-0.915260,-0.110088,0.018297,0.081674,0.037010,0.284800,-0.032020,0.715105,-0.483771,0.320628,0.575002,0.237162,-0.271392,0.258440,-0.263224,-0.007735,-0.231092,-0.208743,0.221567,0.144917,0.664003,-0.120825,0.032074,0.165924,-0.321366,-0.219775,0.222301', '1306983', '2159244', '3871833', '6007281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2059306', '吃蛋糕的人', '剧情', '宁静的农家小镇里住着Kimbrough一家人。一家之主Easy是个普通肉商，他的小儿子Beagle（艾伦·斯坦佛 Aaron Stanford Bruce Dern饰）一直照顾着患病的母亲。大儿子Guy因追寻摇滚梦想远赴纽约，直到母亲去世也没能来得及参加葬礼。Beagle内向敏感，非常喜欢一个患病失去自理能力的女孩Georgia Kaminski（克里斯汀·斯图尔特 Kristen Stewart饰）。Georgia虽然内心孤独但也希望体会爱情的甜蜜。就在他们要初试爱情滋味的同时，彼此长辈之间长久以来不为人知的地下恋情也露出水面……这两家人能否得到如蛋糕般的甜蜜结局呢？©豆瓣', '克里斯汀·斯图尔特', '玛丽·斯图尔特·马斯特森', 7.3, 5835, 'tt0418586', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p694997914.jpg', 0.7, 3.3, 38.3, 45.6, 12.2, '0.079540,0.046800,-0.798056,0.629527,-0.013611,-0.160780,0.788765,0.122533,-0.582173,-0.308117,0.068968,0.696787,0.055669,0.716846,0.108568,0.133222,-0.188491,-0.470156,0.180890,-0.092459,0.000300,-0.156921,-0.265084,-0.074391,-0.131897,-0.070865,0.557985,0.367708,0.291697,0.468136,0.198426,0.068010,-0.148210,0.376743,-0.121018,-0.099844,-0.097358,0.249546,-0.542285,-0.042224,0.104035,0.189283,-0.085106,0.181631,0.058746,0.347838,0.512611,-0.168226,-0.162955,-0.032817,0.209387,-0.019329,0.068001,0.240003,0.153870,0.011976,0.425540,0.271203,-0.073621,0.031410,0.125106,-0.069214,-0.583791,0.134142,0.205632,0.253265,-0.489652,0.596716,0.079804,-0.215070,0.131211,-0.284650,0.165332,0.198942,0.110712,0.674113,-0.424522,0.245085,-0.305882,0.326526,0.973763,-0.084102,-0.355274,0.321576,-0.738598,-0.348567,0.199533,-0.298294,-0.713547,0.043823,-0.013183,0.308113,-0.272945,0.304324,-0.313290,0.251808,0.022408,0.230289,0.135235,-0.538459,0.007490,-0.472149,-0.071534,-0.491532,-0.508356,-0.048926,-0.046608,-0.334005,0.677712,-0.688733,0.309227,0.545194,0.311046,-0.236305,0.676217,0.389392,0.103672,-0.353628,-0.059975,0.694796,-0.503878,-0.317989,0.020586,0.102618,-0.174812,0.095271,-0.369221,0.593353', '25721544', '1309177', '1291835', '1292047');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2059310', '太坏了', '喜剧', '塞斯（乔纳•希尔 饰）和埃文（迈克尔•塞拉饰）是一对不善交际、性格迥异的好朋友，二人即将高中毕业，对没有彼此的大学生活既焦虑又恐惧。一个周末，二人的“桃花运”来了，因为他们收到了一个请柬，邀请他们去参加一个几乎完全是由漂亮女孩们主办的舞会，条件是他们要提供舞会上所需的各种酒类。令人讨厌的朋友弗盖尔（克里斯托弗•米恩特兹•普莱斯 饰）也加入到他们的行列，还给自己弄了一个假身份证，取了“迈克•拉文”这样愚蠢的假名。舞会上，塞斯盯上了舞会的组织者茱尔斯，埃文看上了 与他一起上数学课的女孩贝卡，弗盖尔则选择了装扮刺激的妮科拉。然而一系列不幸的巧合将三个人带到了一个陌生的地方，还让他们与斯莱特和迈克尔斯警官发生了冲突。对于三个即将高中毕业的小伙子来说，这可能是他们经历的最可怕、最让人感到羞愧的一个夜晚，然而，也是一个值得他们回忆一辈子的夜晚。©豆瓣', '乔纳·希尔', '格雷格·莫托拉', 6.9, 22197, 'tt0829482', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2342004258.jpg', 1.5, 8.9, 45.4, 32.6, 11.5, '0.728316,-0.177357,-0.571766,0.604921,-0.300434,-0.331612,0.811590,0.044519,-0.394383,-0.342787,0.145322,1.038030,-0.275525,0.145492,0.450236,0.156697,-0.241779,-0.625303,0.018962,-0.337880,-0.412790,-0.553632,-0.112601,-0.411341,0.053328,-0.205098,0.266621,-0.152328,0.069971,0.774827,0.487944,0.313767,0.177999,0.485930,-0.016785,-0.075110,0.282665,0.022094,-0.098019,0.250027,-0.143780,0.076089,-0.074124,0.335610,0.144232,0.451802,0.544580,-0.199729,-0.207207,-0.029058,0.308415,-0.335487,-0.045589,0.220867,0.175524,-0.329210,0.217384,0.175239,-0.189343,-0.092783,0.076565,-0.073655,-0.788716,0.094100,0.052379,0.199004,-0.458092,0.706257,-0.004750,-0.288846,0.030051,-0.330990,0.332840,0.356690,0.226365,0.266621,0.076775,-0.273469,-0.364741,0.117889,0.867346,0.061598,-0.237886,0.291881,-0.484659,-0.380988,-0.062444,-0.050292,-0.610029,0.175728,0.279666,-0.088054,-0.126502,0.091848,-0.761555,-0.034064,-0.268128,-0.154719,-0.029831,-0.556193,0.145077,-0.650198,-0.098420,-0.484585,-0.654060,-0.076150,0.079924,-0.204750,0.734638,-0.786570,0.035597,0.670754,0.198965,-0.279043,0.736590,0.225203,0.147331,-0.139920,-0.030557,-0.071845,0.206574,0.140225,0.003699,0.700620,0.150847,-0.024578,-0.305899,0.486252', '30162520', '1361252', '