INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2059313', '约书亚', '剧情', '这是一部出色的心理惊悚片，生活在曼哈顿年轻夫妻布拉德（山姆·洛克威尔饰）与艾比（维拉·法梅加饰）迎来了他们第二个孩子，小生命的降生给夫妻俩无比的喜悦，全家人所有的注意力都围绕着她。但是，随着时间的推移，幸福的家庭开始出现诸多奇怪的事故，夫妻关系也出现了裂痕。刚刚出生女婴本来安静可爱，却在半夜无故哭泣，艾比产生的幻觉让她神经衰弱几近崩溃的边缘，整个家庭都被笼罩在一股神秘的力量中。终于布拉德注意到那些可疑的状况都与他们9岁的儿子约书亚 (雅各布·科冈饰)有着关联，这个在学校中被老师夸奖聪明异常的孩子，有着超过同龄人的高智商和成人都莫及的心智，但是表面上，他同家人一样爱护关心着自己新生的妹妹。这些意外到底是有人暗中所为还是纯属偶然，约书亚冷静的外表下做出的种种举动到底意味着什么呢？©豆瓣', '山姆·洛克威尔', '乔治·拉提夫', 7.1, 9722, 'tt0808331', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2460996804.jpg', 1.2, 5.2, 41.8, 39.6, 12.2, '0.232184,0.083004,-0.951233,0.440547,-0.272778,-0.119479,0.958892,0.128408,-0.632722,-0.371782,0.211909,0.719157,-0.411452,0.429895,0.085169,0.070537,-0.205828,-0.622503,-0.219077,-0.115551,-0.238875,-0.414797,-0.409261,-0.037684,-0.058339,-0.459630,0.394748,0.116411,-0.119646,0.385310,0.251856,0.230271,0.008491,0.575341,-0.047402,0.073340,-0.046864,-0.077297,0.018396,-0.179074,0.047930,-0.058929,-0.019811,0.316394,-0.179652,0.351932,0.817142,-0.289094,-0.355715,0.001328,0.485387,-0.237470,-0.026316,0.356588,0.352391,0.071816,0.208505,0.031844,-0.096926,0.124934,0.064621,0.042439,-0.775096,0.081194,0.203010,0.391300,-0.635256,0.305416,0.074840,-0.330532,0.207792,-0.389817,0.305679,0.429449,0.059408,0.610710,-0.503827,0.002058,-0.440646,-0.319020,0.754272,-0.008500,-0.590358,0.270871,-0.601504,-0.482718,-0.190255,-0.219004,-0.468395,0.064980,0.128591,0.229726,-0.170876,0.608395,-0.491854,0.218274,-0.016506,-0.221114,-0.348038,-0.588177,-0.059325,-0.469725,-0.370725,-0.586296,-0.451332,0.019813,0.022064,-0.365947,0.804157,-0.741923,0.456142,0.488229,0.192137,-0.355326,0.439158,0.212830,0.115310,-0.076807,-0.372887,0.250533,-0.047345,0.093522,-0.192959,0.332968,-0.012258,-0.014278,-0.337312,0.621105', '4724586', '1307311', '6745433', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2059321', '破碎的拥抱', '剧情', '马提奥•布兰科（Lluís Homar 饰）曾是一名风光无限的电影导演，在遭遇车祸失明后，他改名哈瑞•凯恩，以编剧的身份过着平静的生活。2008年的一天，名叫雷（Rubén Ochandiano 饰）的青年拜访哈瑞，雷对一部电影的设想再次开启哈瑞关闭已久的记忆大门。1994年，马提奥正在筹拍新片，美丽女孩莱娜（佩内洛普•克鲁兹 Penélope Cruz 饰）在试镜中脱颖而出。莱娜是某公司老板欧内斯特•马特尔（José Luis Gómez 饰）的女秘书，两人之间始终保持着若即若离的暧昧关系。为了给罹患癌症的父亲治病，莱娜委身欧内斯特，成为他的情妇。欧内斯特经不住莱娜的请求，同意投资并让她出演马提奥的新片。拍摄过程中，莱娜和马提奥擦出爱情的火花，而这一切也很快为敏感的欧内斯特所获知。爱恨情仇自此纠缠不清……©豆瓣', '佩内洛普·克鲁兹', '佩德罗·阿莫多瓦', 7.4, 16575, 'tt0913425', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p512804068.jpg', 0.4, 3, 36.2, 46.7, 13.7, '-0.098576,0.089905,-0.558120,0.674204,0.082329,-0.352501,0.687622,0.021933,-0.430309,-0.661833,0.030496,0.725799,-0.359468,0.485478,0.665573,-0.029139,-0.302352,-0.729173,-0.070965,0.142258,-0.143179,-0.379642,-0.223361,-0.274686,-0.064585,-0.309574,0.668690,0.162873,-0.203763,0.413799,0.416719,0.303046,-0.081560,0.245098,-0.071342,0.206663,0.054746,-0.034192,-0.614776,0.153670,0.124914,-0.268390,-0.045018,-0.130720,0.015802,0.162311,0.490187,-0.259959,-0.047637,0.098695,0.404129,-0.189553,0.165521,-0.164442,0.227776,0.182355,0.178988,0.148519,-0.249425,-0.025351,0.104054,-0.311575,-0.605948,0.005214,-0.014845,0.427429,-0.497631,0.351131,-0.186645,0.078468,0.090516,-0.110044,-0.058683,0.085270,0.310423,0.235035,-0.216942,0.092436,-0.428118,0.341410,0.508218,0.201697,-0.190416,0.462147,-0.178244,-0.454431,-0.159693,0.000898,-0.555323,0.198810,0.379708,0.056585,-0.051667,0.489111,-0.404908,-0.340527,-0.337938,-0.126392,-0.094289,-0.303288,0.074531,-0.871450,-0.153627,-0.443360,-0.029042,-0.061869,0.076692,-0.334829,0.515766,-0.677250,0.274833,0.271227,0.184085,-0.407508,0.613943,-0.000242,0.152648,-0.337192,-0.059670,0.517258,0.117847,-0.105228,0.113768,0.256127,0.036705,-0.075228,-0.376360,0.484594', '1299663', '4301278', '24751811',