INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2060184', '恐怖解剖室', '惊悚', '英俊帅气、年轻有为的泰德•格雷（Milo Ventimiglia 米洛•文堤米利亚 饰）事业爱情双得意，他以优异的成绩从哈佛医学院毕业，随后被推荐进入全国最有名的病理学研究小组；另一方面，泰德和女友格雯（Alyssa Milano 阿莱萨•米兰诺 饰）感情顺利，令人欣羡。凭借出众的才干与丰富的学识，泰德很快便在这人才辈出的研究小组中崭露头角，受到同侪的赏识与器重。但他很快便发现，这个小组的工作人员似乎隐藏着不为人知的秘密。原来，这些衣冠楚楚研究人员竟然暗中进行一连串的杀人事件，他们为了创造出完美的杀人纪录而疯狂竞赛。泰德同时发现，自己也在其中越陷越深。是逃脱，还是同流合污，他面临着痛苦而危险的选择……©豆瓣', '米洛·文堤米利亚', '马克·施科尔曼', 6.3, 7774, 'tt0964539', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p770506080.jpg', 2.4, 13.9, 55.4, 22.5, 5.8, '0.191219,0.106023,-0.798914,0.748937,-0.184545,-0.189180,0.493861,-0.159416,-0.530165,-0.325295,0.155579,0.695080,-0.169510,0.174316,0.085150,-0.267087,-0.153046,-0.839613,-0.091181,-0.297629,-0.239245,-0.529704,-0.460395,-0.221644,0.022211,-0.369963,0.569718,0.254269,-0.253089,0.583155,0.209199,0.375517,-0.104596,0.388944,-0.099516,-0.259884,0.277174,-0.074264,-0.193592,0.071699,0.142156,-0.288329,-0.360356,0.077439,0.103300,0.361712,0.625270,-0.210656,-0.370903,0.045929,0.611664,-0.408997,-0.168250,0.112269,0.344592,0.222620,-0.000839,0.192763,-0.063364,0.017287,-0.098577,-0.241209,-1.181577,-0.182358,0.212392,0.085212,-0.464078,0.402555,-0.066794,-0.131462,0.196321,-0.134786,-0.070099,0.342322,0.381235,0.227199,-0.119450,0.368477,-0.271591,0.139115,0.397141,-0.122507,-0.455974,-0.015113,-0.213732,-0.544875,0.177476,-0.438011,-0.277053,-0.014752,0.450432,0.138583,0.273012,0.157668,-0.444626,0.089894,-0.106617,-0.067249,-0.160799,-0.342430,-0.163269,-0.711962,-0.253417,-0.337124,-0.551455,-0.012029,-0.060657,-0.539859,0.990476,-0.856945,-0.003630,0.487343,0.154095,-0.592053,0.530692,-0.128105,0.207162,-0.231867,-0.682955,0.415203,0.015550,0.036609,-0.079932,0.619880,0.067735,-0.461797,-0.386239,0.486598', '27602116', '24284209', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2062677', '罗宾汉', '剧情', '13世纪，大英帝国在狮心王理查一世（丹尼·赫斯顿 Danny Huston 饰）的率领下与来犯的法国军队展开鏖战。孔武有力、骁勇善战的罗宾·朗斯特莱德（罗素·克劳 Russell Crowe 饰）是这群英国战士中的一员，作为射手的他曾随理查参加过十字军东征，在对法的战争中也表现勇猛。但是狮心王遭遇阴谋刺杀，罗宾接受与国王一同遇刺的罗伯特•洛克斯利的遗愿，摇身变成罗伯特回到英国。在王宫骗吃骗喝过后，罗宾如约来到罗伯特的故乡诺丁汉，他不仅得到罗伯特父亲的准许继续假扮其儿子，还意外得知了自己的身世之谜。与此同时，法国野心勃勃，觊觎着英国的领土，而英国国内又乱相丛生，危机四伏。在暗潮涌动的大时代下，罗宾似乎明了了自己的生存使命，不久后他拿起长弓，投入深林，开启了经久不衰的罗宾汉的传说……©豆瓣', '罗素·克劳', '雷德利·斯科特', 6.8, 27289, 'tt0955308', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p475581027.jpg', 0.9, 6.9, 51.1, 33.3, 7.8, '0.086322,0.181957,-0.768026,0.623618,0.012214,-0.302392,0.461710,0.043185,-0.477527,-0.189126,0.324850,0.951921,0.029607,0.087593,0.437895,0.105415,-0.479515,-0.594658,-0.076463,-0.058884,-0.054142,-0.476549,-0.468620,-0.306701,-0.003320,-0.556679,0.692803,0.099998,-0.202707,0.487384,0.247572,0.515015,-0.106870,0.388020,-0.228332,0.111691,0.171196,0.037596,-0.324514,0.364327,-0.071990,-0.224853,-0.367791,0.248709,0.089445,0.327028,0.412914,-0.501455,0.248767,-0.307523,0.240306,-0.319647,-0.021810,0.076308,0.328659,-0.017166,-0.128604,0.329824,0.086967,-0.066582,-0.135705,-0.175243,-0.488077,-0.084753,-0.021073,0.203410,-0.864370,0.404654,-0.312789,-0.069286,0.121986,-0.164468,0.202091,0.630779,0.091835,0.225661,0.076267,0.098158,-0.655317,0.092510,0.658237,-0.132672,-0.333771,-0.240109,0.014066,-0.512212,0.008707,-0.240702,-0.405130,-0.215963,0.339022,-0.133113,0.064696,0.482079,-0.613696,0.034770,-0.565545,-0.287879,0.105921,-0.034623,-0.001118,-0.735354,-0.089954,-0.407461,-0.304780,-0.100658,0.097228,-0.075461,0.470755,-0.740570,0.391392,0.459505,0.256906,-0.274722,0.407239,0.174574,0.206857,-0.126841,-0.258559,0.566938,0.182395,0.158894,0.157743,0.207907,0.025663,-0.296381,-0.335298,0.483522', '3430271', '3285622', '1309069', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2062678', '对话尼克松', '剧情', '尼克松（弗兰克·兰格拉 Frank Langella 饰）在水门事件后下台，却始终未曾对公众承认过自己的错误，欠美国人民一个道歉。福斯特（麦克·辛 Michael Sheen 饰）是一个在澳大利亚主持脱口秀的英国花花公子，在直播中看见尼克松搭乘直升飞机离开白宫时萌生采访他的意念并决定付诸实践。没有人对福斯特抱有期望，没有电视公司愿意出钱购买他的采访，朋友约翰（马修·麦克费登 Matthew Macfadyen 饰）找来业内著名的新闻人鲍勃（奥利弗·普莱特 Oliver Platt 饰）和对尼克松研究颇深的詹姆斯来组成一个小组，开始进行资料挖掘。福斯特自己掏钱付了头笔的采访费，获得了与尼克松见面的机会，并且敲定了连续采访的日子。小组拼命准备问题以便逼尼克松在采访中认罪。尼克松的智囊团也在忙碌地准备应答，他们从不把福斯特放在眼内。正式采访开始，福斯特招架不住尼克松滔滔不绝的自辩，这一切让福斯特破釜沉舟，寻找突破口……', '弗兰克·兰格拉', '朗·霍华德', 8.1, 16109, 'tt0870111', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1375467209.jpg', 0.3, 1, 18.5, 55.8, 24.3, '0.254018,-0.070023,-0.776847,0.584827,-0.125492,-0.298346,0.448130,0.125919,-0.444262,-0.227492,-0.023566,0.704396,-0.403847,0.028689,0.284361,-0.207655,-0.730109,-0.732163,0.077359,-0.051925,-0.143915,-0.643894,-0.069205,-0.609673,-0.131400,0.141094,0.479900,-0.084100,-0.159636,0.477210,0.410951,0.281330,0.377020,0.542502,-0.069151,-0.006216,0.326807,-0.040705,-0.395094,0.477815,0.146900,-0.231449,-0.291929,0.430722,0.421182,0.524371,0.322520,-0.209826,0.038396,0.229349,0.202900,-0.273225,0.215395,0.222687,0.117096,0.219842,0.074573,0.148782,-0.346005,0.058133,-0.116076,-0.188079,-0.646474,-0.070122,-0.138162,0.211759,-0.592091,0.394337,-0.399393,0.309881,-0.057910,-0.327087,-0.044672,0.294463,0.205567,0.114841,0.370515,0.166810,-0.189753,0.337124,0.247385,-0.097699,-0.037793,0.415799,-0.096271,-0.305078,0.095199,0.009287,-0.270594,-0.192927,0.254841,-0.045673,-0.031306,-0.125544,-0.353702,-0.304031,-0.304146,-0.465233,0.178051,-0.471855,0.004473,-1.004231,-0.097583,0.031655,-0.130805,0.054172,-0.098975,-0.063940,0.528842,-0.591679,0.231158,0.624872,0.232909,-0.472833,0.894176,0.130555,-0.087246,-0.496674,0.001383,0.070629,0.166516,0.469556,0.184045,0.121061,0.329618,-0.209099,-0.277089,0.210795', '1293656', '2075345', '24751811', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2062944', '超级杯奶爸', '喜剧', '乔（道恩·强森 Dwayne Johnson 饰）是一名橄榄球运动员，身材强壮又高大的他不仅是队里的主力队员，更是女球迷心目中的完美男人。没有婚姻和家庭的束缚，乔穿梭于欢场与酒吧之间，充分享受着完全自由的单身汉生活，直到一个名叫佩顿（麦迪森·佩蒂丝 Madison Pettis 饰）的小女孩敲响了他的家门。七岁的佩顿自称是乔的女儿，虽然半信半疑，但乔无法拒绝女孩清澈而又充满了希望的眼神，就这样，乔莫名其妙的开始了他的奶爸生涯。面对女儿，毫无经验的乔闹出了不少的笑话，古灵精怪的佩顿也没少给乔惹麻烦，但是，在忙碌的生活间隙，乔逐渐感受到了佩顿带给她的快乐和温馨。一个男人，一个女孩，两人在相处的过程中都迅速成熟起来。©豆瓣', '道恩·强森', '安迪·菲克曼', 7.2, 7876, 'tt0492956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p620190862.jpg', 0.4, 4.2, 41.8, 41, 12.6, '0.160807,-0.132874,-0.629459,0.995864,-0.558760,-0.398257,1.151708,0.087938,-0.421227,-0.266690,-0.217261,0.735845,-0.258488,0.694423,0.446767,-0.096150,0.092307,-0.844930,-0.322011,0.131179,-0.423891,-0.498325,-0.151828,-0.385493,0.005113,-0.184033,0.576030,0.172208,-0.316476,0.422156,0.279688,0.108557,0.177543,0.683551,-0.562935,0.162043,0.061048,0.125174,-0.000692,-0.089329,0.139010,-0.296073,-0.088017,0.396230,0.075920,0.264763,0.863219,-0.292442,-0.216543,0.255114,0.404958,-0.109307,0.046843,-0.054179,0.223098,-0.191803,0.171023,-0.412596,-0.026567,0.078587,0.134590,-0.346540,-0.663785,0.176815,0.149093,-0.103179,-0.613374,0.749436,0.179064,0.139415,0.198260,-0.153367,0.087033,0.155490,0.147517,0.535377,-0.260631,0.174019,-0.615701,0.341820,0.464235,0.310444,-0.520311,0.542985,-0.779946,-0.654093,-0.251650,-0.357807,-0.677614,-0.307329,0.421641,0.067250,-0.211182,0.228599,-0.344659,0.114700,0.116746,-0.073374,-0.002107,-0.620571,-0.106457,-0.456119,-0.222511,-0.819929,-0.270864,0.388156,-0.288007,-0.380410,0.833064,-0.900587,0.092374,0.440891,-0.062521,-0.443636,0.924003,-0.013472,0.234918,-0.030522,0.127360,0.323495,0.183626,-0.123717,0.388023,0.783223,-0.450488,0.191736,-0.258215,0.815021', '24756472', '1292062', '26677495', '1417428');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2063528', '盲山', '剧情', '1990年代末，初踏上社会的大学毕业生白春梅（黄璐）急于帮父母分担重担，无奈一直找不到合适工作，在她发愁之际，装扮成医药采购公司员工的人贩子向她伸来热情的双手，她随他们来到中国西北某个偏僻山村采购中药，结果一杯水喝下肚，她倒床昏睡。醒来后，白春梅遍地不寻她的“医药公司同事”，检查身份证和钱包时，发现它们也一同消失，瞬间，她醒悟自己已被卖给当地人，苦苦哀求一番后，白雪梅明白重获尊严和自由的唯一方式是逃出去，她开始了一次次的出逃冒险，而该过程中，她渐渐知道能相信的人只有自己。©豆瓣', '黄璐', '李杨', 8.7, 164536, 'tt1020972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p524941991.jpg', 0.2, 0.6, 9, 43.3, 46.9, '0.228136,0.319882,-0.752167,0.175820,-0.087231,-0.212790,0.238995,-0.009476,-0.546821,-0.326860,-0.083723,0.828882,0.267577,0.421727,0.186090,0.033828,-0.222324,-0.780932,0.066198,-0.271603,-0.583175,-0.259154,-0.018397,-0.395667,-0.103327,-0.097726,0.238653,0.074774,-0.089506,0.414051,0.104224,0.017349,-0.026872,0.656764,-0.194853,-0.060277,-0.098148,-0.097107,-0.313582,0.252194,0.176462,-0.306239,-0.326202,0.047371,0.180817,0.387036,0.658591,0.372005,-0.211353,-0.002152,0.318090,-0.284330,0.042372,0.041900,-0.081025,-0.001197,0.136094,-0.232361,-0.169509,0.011298,0.016900,-0.175346,-0.289244,-0.071680,-0.143643,0.057557,-0.906179,0.244263,-0.027443,0.170244,0.009305,-0.532969,0.162781,0.440293,0.046700,0.452064,-0.036507,-0.105479,-0.488202,0.434970,0.661643,-0.111409,-0.088782,0.443425,-0.089686,-0.434431,0.383644,-0.082290,-0.177614,-0.141408,0.399608,0.365522,-0.385329,-0.195668,-0.483692,-0.097745,-0.232402,-0.415710,0.074475,-0.191807,-0.047784,-0.163925,-0.260902,-0.145058,-0.228615,0.006929,-0.105000,-0.299038,0.438716,-0.669653,0.226736,0.641161,0.304933,-0.524813,0.568060,-0.146780,0.129266,-0.233966,0.106523,0.182996,0.012011,0.573960,0.288227,0.027008,-0.018926,0.069977,-0.519343,-0.044596', '1926007', '1293607', '25908042', '25837175');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2063533', '水仙花开', '剧情', '一次偶然中，玛丽（波琳·艾克阿特 Pauline Acquart 饰）遇见了花样游泳队的队长弗洛利亚那（阿黛拉·哈内尔 Adele Haenel 饰），弗洛利亚那的性感和美丽很快就吸引了玛丽的目光，然而，在传闻中，弗洛利亚那却并不如表面看来的那么纯洁和美好。随着时间的推移，玛丽渐渐发现传闻的虚假，与此同时，她深深地迷恋上了弗洛利亚那，已经到了无法自拔的境地。安妮（露易丝·巴彻雷 Louise Blachère 饰）是玛丽的好友，在玛丽为弗洛利亚那痴狂的那段日子里，她却偷偷喜欢上了弗洛利亚那的男友弗朗西斯（沃伦·杰坤 Warren Jacquin 饰）。可是，安妮知道自己长得并不漂亮，于是决定将这份感情埋藏在心底。©豆瓣', '宝莲·艾格特', '瑟琳·席安玛', 7.2, 10482, 'tt0869977', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2561135352.jpg', 0.6, 5.4, 41, 37.3, 15.8, '0.615695,0.287569,-0.820746,0.702930,-0.225246,-0.629299,1.158553,0.148435,-0.568119,0.109370,0.222578,0.585163,-0.243725,0.012737,0.591030,0.883005,-0.846081,-0.542906,0.190953,-0.493458,0.018893,-0.449690,-0.633691,0.282403,-0.028884,-0.473340,0.354830,-0.272009,0.190322,0.822037,0.338450,0.410270,0.332785,0.391075,0.281029,0.140907,0.528307,-0.076611,0.057612,0.265701,0.132161,0.159408,-0.334338,0.176761,-0.070908,0.379351,0.374594,-0.334174,0.172951,-0.037941,0.189437,-0.214953,0.342027,0.279825,0.052253,-0.262070,0.379311,0.094786,-0.509510,0.204916,0.329649,0.124741,-0.470274,0.265491,-0.031941,0.415217,-0.608498,0.605417,-0.372361,-0.483320,0.293981,-0.413773,-0.252674,0.121985,-0.000114,0.194700,0.060393,-0.258070,-0.446054,-0.127587,0.093984,0.141887,-0.598763,0.333693,-0.114439,-0.365590,-0.050145,-0.112303,-0.386728,-0.071656,0.519509,0.224094,-0.363157,0.814158,-0.740207,0.147272,-0.367761,-0.209456,-0.126777,-0.470634,-0.325046,-0.600103,-0.508092,-0.813557,-0.399553,-0.394182,-0.102166,0.039859,0.547149,-0.870580,0.330346,0.609673,0.235538,0.230219,0.433659,0.614962,-0.129530,0.072220,-0.410855,0.405773,-0.186265,0.438970,0.253596,0.687567,0.393679,-0.201344,-0.591551,1.007123', '24639908', '1302133', '23424586', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2063867', '金馆长对金馆长对金馆长', '喜剧', '某韩国小镇上，围绕着一家中国餐馆形成了武馆角，餐馆主人是年迈的前中国功夫教练——如今的武会社长。教授跆拳道的金馆长（申贤俊 饰）与教授剑道的金馆长（崔成国 饰）是一对天生的冤家，从事业到爱情无不针锋相对，日子在两家武馆的生源争夺战中平淡的过去，直到又一位金馆长出现——从武会社长处租到场地的功夫教头（权伍中 饰），两位金馆长面对优势尽现的新对手，感到如芒在背，只得结为暂时的同盟，结果却只是弄巧成拙。老会长有心偏袒自己的同派后辈，向三人提出了比武招亲的解决方式，在准备比武的间隙，黑社会势力入侵小镇，三位金馆长终于同仇敌忾，为尊严和友谊向恶势力发起挑战。©豆瓣', '申贤俊', '朴成均', 6.4, 17398, 'tt0984057', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p825820535.jpg', 2.3, 13.7, 51.9, 24.1, 8, '-0.045955,0.123416,-0.373677,0.515863,0.182015,-0.531354,0.420294,0.471585,-0.355901,-0.230222,0.469300,0.613746,-0.059080,0.314816,0.487658,-0.415895,0.058554,-0.694250,-0.187029,-0.091140,-0.207423,-0.320956,-0.050486,-0.096093,-0.173954,-0.090801,0.418069,0.165714,-0.387649,0.580802,0.365253,0.347850,0.007905,0.012987,0.186651,-0.297241,0.400225,0.186541,-0.628652,0.186517,-0.011196,-0.013617,-0.435651,0.097209,0.190331,0.331017,0.516912,-0.109209,0.012306,-0.166562,0.123406,-0.192786,-0.036654,0.023955,0.590916,0.118340,0.239695,0.359141,0.012086,0.075952,-0.020183,-0.165311,-0.534514,0.295314,0.191675,0.179593,-0.540837,0.615348,0.190751,-0.199427,-0.188295,-0.533675,-0.033543,0.247247,0.161769,0.130247,-0.143041,0.292851,-0.404807,-0.006707,0.626042,0.220318,-0.116741,-0.120891,0.232429,-0.316978,-0.029413,-0.237629,-0.233032,-0.334019,0.382705,-0.263792,0.316975,0.140864,-0.941172,-0.120698,-0.111335,0.063646,0.454087,-0.212438,0.165862,-0.673223,-0.061325,-0.276442,-0.254852,0.016949,0.232235,0.028171,0.866684,-0.897878,-0.086586,0.337819,0.258805,-0.275034,0.775211,0.094572,0.092394,-0.240857,-0.409262,-0.400735,0.011056,0.546716,0.078227,0.316472,0.033725,-0.377613,-0.191676,0.252524', '4127270', '26365262', '1316589', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2063914', '哥斯拉', '动作', '拥有幸福美满生活的大兵福德·布罗迪（亚伦·泰勒-约翰逊 Aaron Taylor-Johnson 饰），内心隐藏着一个挥之不去的阴影。15年前，他和父亲乔伊（布莱恩·科兰斯顿 Bryan Cranston 饰）、母亲桑德拉（朱丽叶·比诺什 Juliette Binoch e 饰）生活在日本。父母供职于一座大型核电站。就在福德的爸爸生日当天，一场突如其来的灾难摧毁了核电站，他的母亲在灾难中丧生，语焉不详的政府隐瞒真相，以防止核辐射的名义封锁了该地区。但是乔伊却从种种异状觉察到反常之处，十五年来他一直试图揭开当天的灾难之谜，终于发现这一切都是由一只如山一般巨大的怪兽所引起。怪兽哥斯拉从沉睡中苏醒，令人难以预测的灾难席卷而来……©豆瓣', '亚伦·泰勒-约翰逊', '加里斯·爱德华斯', 6.6, 201043, 'tt0831387', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2185227574.jpg', 2.2, 11.3, 49.6, 27.7, 9.2, '-0.026548,0.035287,-0.897919,0.508187,0.132702,0.067358,1.116125,0.049522,-0.433666,-0.442247,0.381457,0.823517,-0.273294,0.259313,0.225341,0.023747,-0.311777,-0.528145,-0.003850,-0.140348,-0.241633,-0.275024,-0.527022,-0.252802,0.157078,-0.337934,0.604640,0.239588,-0.295648,0.240583,-0.022595,0.654236,-0.248339,0.596398,0.042361,-0.141996,-0.190128,0.054119,-0.338694,0.054993,0.005432,-0.384232,-0.023017,0.531352,-0.204801,0.276393,0.638520,-0.666249,-0.214065,-0.057446,0.256966,-0.475705,0.007128,0.145786,0.353648,-0.110145,-0.142788,0.192904,-0.389895,0.072272,0.238931,-0.257034,-0.415026,-0.262253,-0.052833,0.421749,-0.304252,0.371738,0.025411,0.110074,0.065609,-0.306098,0.049869,0.526527,0.064549,0.533323,-0.346806,0.116154,-0.338137,0.186071,0.662722,-0.312365,-0.321597,0.223064,-0.308315,-0.295116,-0.092968,0.019867,-0.530218,0.121299,0.280539,0.050720,-0.233132,0.721270,-0.579662,-0.295926,-0.477921,-0.349058,-0.262021,-0.304092,-0.281387,-0.460598,-0.215828,-0.174359,-0.246022,0.106121,0.033591,-0.150245,0.327734,-0.687371,0.485445,0.695299,0.039903,-0.053958,0.295615,-0.211043,0.136740,-0.178385,0.049258,0.475095,0.008795,0.328575,-0.063248,0.180586,0.378176,-0.137507,-0.195935,0.470925', '1428054', '20451118', '1296534', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2064441', '野·良犬', '剧情', '自从六岁那年，妈妈从天台一跃而下，林志宏（文俊辉 饰）就再也没有说过一句话。与婆婆相依为命的他生命里从来没有父亲的存在。“爸爸飞去了远方，只要花开爸爸就会回来。”这是妈妈自幼对林志宏说的话。陈满堆（陈奕迅 饰）的童年经历同样不愉快，如果不是遇上老大（曾志伟 饰）可能早已被打死或者饿死街头。老大给他分配任务，成功后给他生活费用。这次的新任务是把黑帮头子纽乔泽（林子祥 饰）的儿子找出来，于是陈满堆进了学校当校工。三个人就这样相遇了，陈满堆，林志宏，以及代课老师miss张（林苑 饰），三个各自怀着自己心事、有着自己心病的人，奇迹般地建立起互相信任、单纯直接的感情。直到纽乔泽出现，大家才惊现林志宏就是纽的儿子。个人都有着自己的使命，亦有着自己的选择。©豆瓣', '陈奕迅', '郭子健', 7.2, 5512, 'tt1018809', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2515751438.jpg', 1.1, 5.5, 37.3, 42.6, 13.5, '0.049790,-0.159349,-0.655894,0.509778,-0.284086,-0.604151,0.632361,-0.139982,-0.475818,-0.107430,-0.031754,0.691991,0.166830,0.522118,0.010200,0.101399,-0.184480,-0.659976,0.041929,-0.326635,-0.302369,-0.454967,0.105966,0.033461,-0.049944,-0.029026,0.276205,-0.176181,-0.249265,0.289895,0.431469,0.163658,-0.001334,0.482019,-0.293820,0.303279,-0.170606,0.386832,-0.262801,0.088025,0.168122,0.009729,-0.069287,0.116296,0.082079,0.220541,0.477042,-0.214995,-0.143313,-0.141026,0.086472,-0.134217,0.021916,0.091174,0.370992,-0.024133,0.530322,0.233818,-0.174541,0.162521,0.076325,-0.048599,-0.576168,-0.017687,-0.030810,0.032359,-0.594296,0.403811,0.051780,-0.172530,0.193156,-0.315967,0.304041,0.199750,0.227014,0.354219,-0.384087,-0.039249,-0.465846,0.277638,0.698490,-0.157967,-0.107112,0.375569,0.004239,-0.241706,0.121308,-0.057348,-0.356754,0.366773,0.239777,0.157029,-0.335929,0.046171,-0.358936,0.060612,-0.090779,-0.153460,0.252761,-0.408034,0.109820,-0.073453,0.096660,-0.184679,-0.397876,0.255979,-0.004974,-0.125709,0.666621,-0.766544,0.403767,0.228832,0.412641,-0.533681,0.487111,0.167271,0.102061,-0.173925,0.273514,0.037733,-0.078263,0.371598,0.237431,0.209402,0.191100,-0.152396,-0.065338,0.428197', '1301022', '1292219', '1308755', '4861627');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('20645098', '小王子', '动画', '灰蒙蒙的都市丛林，美丽的小女孩眼神中没有渴望和雀跃，她跟随妈妈穿梭钢筋水泥的光影之间，按照社会既定法则亦步亦趋。她的未来似乎早被注定和规划，即使生日礼物也找不到些许惊奇。为了进入好学校，母女俩搬到郊外一幢独栋房子里，旁边则是一间与周遭格格不入的破房子。某天，一个飞机螺旋桨突然破墙而入，从而建立起女孩和隔壁那个怪爷爷的友谊。老人自称曾是一名飞行员，年轻时他迫降沙漠，在那里认识了有着纯真心灵的小王子。女孩听老人讲述着有着童话般瑰丽色彩的往事，不知不觉间心驰神往……本片根据安东尼·德·圣-埃克苏佩里的经典同名作品改编。©豆瓣', '杰夫·布里吉斯', '马克·奥斯本', 8.3, 310291, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2274029145.jpg', 0.8, 2, 16.2, 42, 39, '0.321806,0.008058,-0.840827,0.760315,0.033351,-0.128771,0.951364,-0.000945,-0.386995,-0.544523,0.018030,0.528470,-0.035179,0.580688,0.306835,0.124940,-0.461222,-0.407493,-0.352826,-0.362388,-0.270741,-0.466468,-0.274157,-0.051252,-0.042882,-0.220842,0.570961,0.184226,-0.177467,0.448974,0.038555,0.140251,-0.376672,0.117442,-0.304959,-0.086455,0.164055,0.174742,-0.353715,-0.071069,-0.196981,0.077992,-0.096551,-0.157113,-0.206306,0.230025,0.625424,-0.227502,-0.110916,0.048958,0.305707,0.252480,0.035675,0.043463,0.187018,0.018857,0.301426,-0.008803,-0.114691,-0.117251,-0.093755,-0.371728,-0.443506,0.201228,0.057370,0.004088,-0.313067,0.274504,0.202092,-0.177565,0.269933,-0.326549,0.275726,-0.136126,0.410368,0.673991,-0.136702,0.160925,-0.458399,-0.030704,0.520477,0.264593,-0.214032,0.401759,-0.408920,-0.156657,0.023249,0.104659,-0.576038,0.061275,0.281428,-0.014166,0.126462,0.271500,-0.596577,0.128046,-0.019498,-0.072553,0.062847,-0.309634,-0.381032,-0.519727,-0.185568,-0.386467,-0.046290,0.057699,-0.194181,-0.009168,0.614609,-0.748863,0.295137,0.111581,0.327804,-0.098818,0.836035,-0.239687,0.095822,-0.347859,-0.016397,0.208243,-0.177378,0.295228,0.092929,0.426172,-0.327211,0.116617,-0.478289,0.514197', '3055049', '1302133', '1296534', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2065021', '热血高校', '动作', '铃兰男子高中是一所恶名远播的学校，这里聚集着一群嗜好打架的不良学生，他们因象征着流血等不吉利事件，而被称为“乌鸦”，为争夺学校霸权，他们又分为诸多派系，其中最强悍的两股势力为：芹泽多摩雄（山田孝之 饰）所带领的芹泽军团，转校生泷谷源治（小栗旬 饰）和地头蛇片桐拳（矢部恭介 饰）联手的新力军。随着两派矛盾的激化，源治和芹泽两大乌鸦军团决一雌雄的时候即将到来……©豆瓣', '小栗旬', '三池崇史', 8, 133763, 'tt1016290', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1011836385.jpg', 0.7, 2.8, 23, 44.6, 28.9, '0.479762,-0.238026,-0.662911,0.498233,0.207872,0.108755,0.480479,0.451341,-0.183649,-0.432164,0.271873,0.483416,-0.085626,0.285021,0.209623,-0.247175,0.201975,-0.758307,-0.139005,-0.008575,-0.138795,-0.068837,-0.082505,-0.023812,-0.232033,-0.229500,0.829725,0.020297,-0.263022,0.613538,0.495986,0.728693,-0.314160,0.149393,0.077893,-0.088865,0.246133,-0.127207,0.014882,-0.022973,-0.385095,-0.118311,-0.217855,0.227384,-0.025132,0.247228,0.845615,-0.268286,0.326052,-0.724366,0.083621,-0.280949,-0.225552,0.083906,0.930108,-0.273187,0.310747,0.412348,0.201510,-0.001475,-0.047575,0.016932,-0.417909,-0.046016,0.194810,0.266987,-0.313428,0.804718,0.062785,-0.457180,0.318438,0.101649,0.106528,0.556868,0.270396,0.100260,-0.077804,-0.136180,-0.392250,-0.127542,0.831524,-0.181468,0.017050,-0.230150,-0.066452,-0.478696,-0.236071,-0.387185,-0.356679,-0.288542,0.137866,-0.105867,0.207368,0.364987,-0.670352,0.034150,-0.022880,-0.033789,0.270888,-0.347788,0.117086,-0.600567,-0.008121,-0.395247,-0.298775,0.349124,0.256852,0.107355,1.052027,-0.890765,-0.253415,0.423328,0.411582,-0.443413,0.304220,0.029269,0.189043,-0.278559,-0.332754,-0.367670,0.181119,0.049386,0.292538,0.407437,-0.057912,-0.144196,-0.105934,0.264348', '1826173', '26999591', '25922902', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2065047', '眼镜', '剧情', '初春，度假的妙子（小林聪美 饰）坐飞机来到南方一个海岛小镇上，在住宿的旅馆里，她遇上了一群人：养了一条和自己同名爱犬的旅馆主人裕二（光石研 饰），戴着一副眼镜经常微笑的刨冰高手樱（罇真佐子 饰），不是旅馆客人但经常在附近转悠的高校教师春奈（市川实日子 饰）以及前来找妙子的青年艾草（加濑亮 饰）。五个人戴着眼镜每天一起在海边做奇怪的早操，然后一起吃早饭……，虽然生活平静而美好，但妙子还是决定继续旅行……©豆瓣', '小林聪美', '荻上直子', 8.1, 11025, 'tt1016307', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p476608236.jpg', 0.4, 1.7, 20.2, 49.1, 28.5, '0.308738,-0.100413,-0.355082,0.268192,-0.168306,-0.080904,0.492414,0.634823,-0.250674,-0.335875,0.329772,0.702777,-0.039863,0.612698,0.351236,0.189071,-0.577323,-0.286587,0.140785,-0.250085,-0.415115,-0.115488,0.075831,-0.137873,-0.012215,0.020921,0.163700,0.062602,0.311480,0.750508,0.294623,-0.118204,-0.389211,0.252625,-0.444709,-0.323573,0.117345,0.096373,0.125420,0.201504,-0.272707,-0.246531,-0.207424,-0.119459,0.517241,0.167536,0.881989,0.014448,-0.248120,-0.009740,-0.203256,0.081498,-0.062424,0.055404,0.359290,-0.101214,0.289282,-0.135393,-0.218647,0.142682,0.225107,-0.360348,-0.087779,0.177808,0.037829,0.284858,-0.443072,0.687183,0.166396,-0.271520,0.145142,-0.395110,0.228356,0.001930,0.212856,0.356549,-0.013456,0.305011,-0.394164,0.291589,0.493839,0.077462,0.228571,0.172192,-0.179586,-0.030664,0.048972,0.023026,-0.606279,-0.080111,-0.133950,-0.355745,-0.265913,-0.324571,-0.862627,0.180427,0.036933,-0.132122,0.144863,0.108459,-0.228176,-0.986351,0.545135,-0.666140,-0.315180,0.337287,0.168390,0.118572,0.481211,-0.659663,0.202836,0.470573,0.254519,-0.169920,0.724819,-0.243668,0.178689,-0.153978,-0.105225,0.011236,0.072935,0.272923,0.252983,0.679116,-0.343284,0.032864,-0.573919,0.194508', '1292050', '3139191', '3178770', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2067450', '那家伙的声音', '剧情', '电视台主播韩京培（薛景求 饰）的儿子被绑架了，绑匪（姜东元 饰）打来电话要求1亿韩元的赎金，京培不得讨价还价。京培与妻子智善（金南珠 饰）都十分着急，无奈之下只好报警了，警方很快展开了调查。警方的高科技调查方式对于狡猾的罪犯来说根本起不了作用。唯一有用的证据便是绑匪打来电话时被录下了的嗓音。一把低沉而且毫无感情的嗓音。案情一直没有进展，京培与妻子连儿子的死活都不知道。于是京培决定自己出面，偷偷向绑匪提出见面的要求。©豆瓣', '薛景求', '朴镇彪', 7.5, 33004, 'tt0969268', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p541027481.jpg', 0.5, 2.4, 32.7, 48.4, 16, '0.234990,-0.085605,-0.576409,0.797775,-0.318753,-0.066013,0.345269,0.005399,-0.587203,-0.400925,-0.205466,0.313352,0.171036,-0.174168,-0.119484,-0.354258,-0.567108,-0.795797,-0.179173,-0.168576,-0.210516,-0.797986,0.331545,-0.025664,-0.103568,0.203370,0.105759,-0.137909,-0.391918,0.352707,0.511148,0.408759,0.043925,0.602162,0.060117,-0.152496,0.074418,-0.129115,-0.306016,0.368179,0.449848,-0.209348,0.044108,0.345862,0.042050,0.744929,0.230054,-0.227121,-0.388173,-0.011563,0.271476,-0.177295,0.140775,0.295366,0.375164,0.334002,0.482533,0.381589,-0.449539,-0.042691,0.486350,-0.051113,-0.861366,0.362745,-0.141243,0.106153,-0.352674,-0.035137,-0.662842,0.180512,-0.012615,-0.503593,0.425843,0.234208,0.287994,0.223271,-0.344980,0.147294,-0.454726,0.096522,0.447370,0.231636,0.206102,0.198337,-0.011445,-0.645957,-0.070727,-0.269589,-0.292179,0.325351,0.483862,0.242440,-0.366884,-0.130752,-0.177205,-0.381922,-0.172233,-0.313370,-0.038372,-0.627186,0.013192,-0.468962,-0.202697,-0.058862,-0.488918,0.171604,0.239623,0.039987,0.334690,-0.761464,-0.185625,0.465159,0.483826,-0.487379,0.379365,0.103440,-0.190582,-0.243289,0.005145,-0.300657,0.220430,0.518360,0.486292,-0.073706,0.308840,-0.450234,0.020430,-0.106224', '1307442', '1301231', '25862560', '3217142');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2067505', '戏王之王', '喜剧', '警方卧底因为演技太差，被黑帮老大识破并杀害。处长（许鞍华 饰）决定寻找警界里最有表演欲的警员到演艺学院学习演技。连sir（许绍雄 饰）找到了极具表演欲的陈文龙（詹瑞文 饰），委以重任。文龙十分热爱演戏，他有一个恋爱7年的女友Judy（叶璇 饰），但两人貌合神离。跟文龙一样是插班生的单丹（蔡卓妍 饰）是一个三级片女星，她的身份被很多人歧视，但仍然坚持学好演技。同时文龙也因为他夸张的演技受到侧目。单丹与文龙二人可谓同病相怜，也因此成为了好友。满以为自己的演技已有所提高，文龙接受了上司安排的行动，但终告失败了。他也被上司勒令退学了，之后他得到了高人（黄秋生 饰）的指点，真正了解了演戏的真谛。©豆瓣', '詹瑞文', '陈庆嘉', 6, 8667, 'tt1019919', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p489303566.jpg', 5.3, 19.8, 49.2, 19.6, 6.1, '0.435656,-0.257078,-0.443803,0.355260,-0.084579,-0.264525,0.296027,0.157609,-0.524199,-0.229388,0.353964,0.763559,-0.268897,-0.161221,0.212463,-0.148506,-0.170305,-0.660867,0.224515,-0.011208,0.053398,-0.490119,-0.088984,0.332160,-0.338316,-0.194300,0.645647,-0.311753,-0.387918,0.564691,0.180119,0.016702,0.481665,0.478332,0.064820,0.183545,0.086175,-0.225220,-0.146820,0.068791,0.219653,-0.122431,-0.235437,0.200389,-0.133471,0.447599,0.364793,-0.023214,-0.353635,0.074772,0.333084,-0.567792,-0.211672,0.099015,0.217687,0.122154,0.230385,0.449072,-0.016941,0.172087,-0.038911,0.155005,-0.801328,0.075041,0.254757,-0.012131,-0.381590,0.412296,0.083900,-0.181413,-0.192995,-0.329258,0.108146,-0.040941,0.127131,0.007852,-0.263039,-0.037085,-0.551393,0.381046,0.500408,0.140351,-0.074505,0.465352,-0.062328,-0.438427,-0.017378,-0.473697,-0.445630,0.196792,0.034737,-0.060876,-0.143655,-0.245624,-0.426026,-0.062766,-0.308185,0.083205,-0.309128,-0.681346,0.063344,-0.504301,-0.427629,-0.555854,-0.592361,-0.465130,-0.007269,-0.515464,0.765187,-1.036266,-0.217521,0.531717,0.249057,-0.599789,0.677457,0.215323,0.018287,-0.114701,-0.366594,-0.066354,0.012844,0.125606,0.081519,0.459067,0.059740,-0.681119,-0.107082,0.106099', '35030151', '4127270', '1877596', '1395231');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2070367', '每当变幻时', '剧情', '一个草根阶层在街市奋斗的故事。阿妙（杨千嬅）决心解脱，还清父亲欠下的债务后，重新生活。她与另一个“卖鱼佬”（陈奕迅）不打不相识到后来一起为着生活奔波，到后来互生情愫，来来回回，事事变迁过了10年的时间。期间他们失去联系过，缘分还是把他们拉回了彼此的生活，他还是像以前一样关心她的生活。她对他深藏的感情也渐渐浮出水面。事情却又来变化。©豆瓣', '杨千嬅', '罗永昌', 8, 53936, 'tt1020976', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p481717329.jpg', 0.3, 1.8, 23.1, 48.4, 26.4, '-0.153044,-0.097736,-0.686274,0.512060,-0.168583,-0.546025,1.056444,0.098100,-0.653238,0.097099,-0.110771,0.489048,0.002524,0.543072,0.077151,-0.160932,-0.523211,-0.880694,0.390829,-0.201537,-0.266072,-0.060689,-0.139944,-0.169998,-0.435228,-0.163563,0.627871,0.189560,0.013951,0.544484,0.035248,-0.096409,-0.169881,0.776534,-0.400491,0.275587,-0.196251,0.474698,-0.518858,-0.224333,0.127558,-0.168516,-0.334910,-0.050076,0.209791,0.410390,0.786638,0.036080,-0.226217,0.176730,0.079833,-0.100661,-0.139403,-0.000659,0.255294,0.187274,0.049504,0.505109,-0.303665,0.087128,-0.409719,-0.062975,-0.472319,-0.251346,-0.290534,0.198569,-0.853670,0.646289,0.210516,-0.168699,-0.272467,-0.455500,0.043873,0.298677,0.378163,0.421330,-0.408788,0.115630,-0.473572,0.390690,1.144000,0.004127,-0.266465,0.846101,-0.410088,-0.362329,-0.397107,-0.137985,-0.414879,-0.274025,0.047996,-0.111026,-0.488756,0.739926,-0.716294,0.047195,-0.039242,-0.158302,0.245166,-0.656876,0.046332,-0.094953,-0.567533,-0.705530,-0.641138,0.130462,-0.060435,-0.475541,0.823374,-0.662073,0.143844,0.846298,0.301657,-0.690367,0.690330,0.249336,0.211443,-0.394406,0.205305,0.528363,-0.367376,0.393620,0.248895,0.138250,-0.016282,0.510737,-0.433731,0.713088', '26245360', '1307561', '1302109', '30209018');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2071525', '女子监狱', '剧情', '何嘉慧（夏文汐 饰）在结婚当天误伤了未婚夫阿良（任达华 饰）的债主，接着被判入狱。她对监狱里的生活十分不习惯，感觉自己完全没有了自尊，生性倔强的她也卷入了监狱里的明争暗斗中，幸好她认识了大家姐（郑裕玲 饰）、阿琴（冯宝宝 饰）等人，也总算有个朋友互相照顾。她们一起挣扎生活着，面对很多不公平的对待，警官与罪犯的互相勾结，让她们受尽欺凌，在嘉慧痛不欲生之际，却发现自己怀孕了。©豆瓣', '郑裕玲', '林德禄', 7.2, 6155, 'tt0095758', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2228074818.jpg', 0.7, 4, 43.8, 37.5, 14, '0.412419,-0.257765,-0.618608,0.277744,-0.231610,-0.224152,0.938744,0.167032,-0.546833,-0.260126,0.160188,0.623825,-0.312695,0.323633,-0.032762,-0.122711,-0.240185,-0.636923,-0.118890,-0.030230,-0.314370,-0.169813,-0.099563,-0.007148,-0.340687,0.031683,0.381155,-0.054836,-0.098380,0.550559,0.185368,0.168730,-0.013328,0.741200,-0.129130,0.165137,0.206585,0.217028,-0.109834,-0.081350,0.085342,-0.228630,0.128667,0.168156,0.150052,0.373774,0.624210,-0.279843,-0.111517,-0.184148,0.163525,-0.270459,-0.149584,0.364625,0.143996,-0.185636,0.332180,0.326241,-0.371151,0.089778,0.051309,0.060649,-0.414890,0.034895,0.296903,0.175945,-0.477697,0.667045,-0.103095,0.073763,-0.099228,-0.042041,0.287224,0.328828,0.138189,0.376569,-0.178712,-0.183416,-0.611540,0.136071,0.904224,-0.110544,-0.021231,0.345424,-0.371029,-0.251560,0.020499,-0.201238,-0.694426,-0.180901,-0.060094,-0.126702,-0.609435,0.263063,-0.320922,0.015128,0.059420,0.102316,-0.130259,-0.645550,0.120048,-0.300899,-0.370661,-0.799776,-0.545170,0.106163,-0.171005,-0.208295,0.472332,-0.926358,0.116290,0.307964,0.623506,-0.554470,0.629840,0.539697,0.011531,-0.122028,0.180279,0.194403,0.099737,0.085007,0.316539,0.243478,0.053256,-0.008864,-0.196379,0.358166', '1308755', '1296370', '1307561', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2072478', '怪物史瑞克4', '喜剧', '史莱克（麦克·梅尔斯 Mike Myers 配音）与菲奥纳公主（卡梅隆·迪亚兹Cameron Diaz 配音）和三胞胎宝贝幸福生活在一起后，他却对日复一日的平淡生活不满起来。在一次与菲奥纳公主激烈争吵后，他遇到了魔法师侏儒怪（沃尔特·道恩 Walt Dohrn 配音），并与其签订了“一天换一天”的魔法条约。但史莱克没想到，侏儒怪拿走的竟是他出生的那天，结果整个遥远王国变得面目全非，侏儒怪成了国王，派出无数女巫到处搜捕食人魔为奴。而若在日出之前史莱克无法获得菲奥纳公主的真爱之吻，他将彻底消失。焦急的史莱克再次初遇好朋友骡子（艾迪·墨菲 Eddie Murphy 配音），而靴猫剑客（安东尼奥·班德拉斯 Antonio Banderas 配音）则变成了菲奥纳公主的宠物肥猫。在他们的帮助下，史莱克竭尽全力赢取菲奥纳公主的芳心，只可惜事态发展远不如想象顺利……', '麦克·梅尔斯', '迈克·米切尔', 7.6, 59779, 'tt0892791', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p595196020.jpg', 0.3, 2.4, 32.1, 48.2, 17, '0.038288,0.103601,-0.433898,0.622154,0.104702,-0.352708,0.710617,-0.020201,-0.294234,-0.169527,0.135526,0.678856,-0.186264,0.078808,0.153951,0.060362,-0.432598,-0.524322,0.117815,-0.149181,-0.024267,-0.382148,0.056625,-0.419206,-0.087816,-0.579688,0.604214,0.041147,0.163176,0.586656,0.150868,-0.124405,-0.088807,0.264781,-0.138019,0.071640,0.365102,0.060983,-0.175167,0.398359,0.162276,0.024423,-0.005083,0.264499,0.185563,0.077217,0.553941,-0.740693,0.165581,-0.133944,0.266215,-0.278982,-0.006226,0.254030,0.387620,-0.212577,0.093756,-0.227764,0.080027,-0.228953,0.042276,-0.167160,-0.415612,0.423361,-0.155362,0.166323,-0.397981,0.340188,0.016837,0.394145,0.060519,-0.245899,-0.091863,0.106473,0.253870,0.292795,-0.148868,0.267677,-0.420980,0.091474,0.687059,0.001395,-0.177309,0.219917,0.121161,-0.683499,-0.077553,-0.190832,-0.587202,0.025100,0.373991,-0.083992,0.020557,0.472919,-0.534164,-0.129179,-0.509444,-0.151391,0.003307,-0.412474,0.087028,-0.391303,0.003782,-0.203022,-0.144722,-0.006457,0.185278,-0.409676,0.513293,-0.938707,0.169336,0.451013,0.347675,-0.308597,0.189897,-0.089866,0.245835,-0.070038,-0.054694,0.231568,0.137890,0.235048,0.588903,0.281476,0.022742,0.061462,-0.310125,0.507238', '35030151', '1292219', '12