INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2072848', '明亮的星', '剧情', '美丽的富家女芬尼（Abbie Cornish 艾比·考尼什 饰）沉醉于时尚之中，亲手为自己设计并制作衣物是她最大的乐趣。偶然的一次机会，她看到了隔壁穷小子济慈（本·威士肖 Ben Whishaw 饰）并不畅销的诗集，她被那些字句吸引，于是便寻找一切机会接近那个忧郁的男人。在济慈的影响下，芬尼开始学习和欣赏诗歌，在相处过程中两人深陷情网。然而这段感情从开始就遭到各种反对，在聚少离多的日子里，一对恋人通过书信传达彼此心中的爱恋。归来的济慈送给芬尼订情的戒指，并送给她一首题为《明亮的星》的诗，两人在各种各样反对的声音中继续坚守着这份爱情。不久，济慈的新作终于问世，可是此时他却患上了严重的肺病……本片导演是曾凭《钢琴课》斩获金棕榈大奖的简·坎皮恩（Jane Campion）。本片入选了第62届戛纳国际电影节主竞赛单元，并提名第82届奥斯卡最佳服装设计奖。©豆瓣', '艾比·考尼什', '简·坎皮恩', 7.7, 46696, 'tt0810784', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2020692041.jpg', 0.3, 2.4, 28.5, 47.1, 21.7, '0.109891,0.083750,-0.757943,0.760407,-0.067140,-0.243076,0.715682,-0.013342,-0.541044,-0.228755,-0.073450,0.715549,-0.400030,0.192095,0.302756,0.101040,-0.284599,-0.826369,-0.107252,-0.222173,0.000932,-0.421795,-0.294008,0.009688,-0.092360,-0.339265,0.639795,0.264968,-0.335981,0.555252,0.411010,0.079926,-0.068163,0.456894,-0.140643,-0.062173,0.144663,0.193055,-0.325291,0.311440,0.033809,-0.259550,-0.219755,0.056407,0.108819,0.212599,0.698588,-0.313637,0.061641,0.230521,0.519695,0.005651,-0.095121,0.008042,0.087284,0.132904,0.278344,0.312933,-0.193224,0.295701,-0.089115,-0.161287,-0.657892,-0.017633,0.106752,0.204322,-0.550310,0.635437,-0.113549,0.001617,-0.101828,-0.103189,0.277923,0.099059,0.380014,0.200917,-0.131210,0.036518,-0.366882,0.394635,0.340391,-0.017125,-0.207335,0.503068,-0.271724,-0.509959,0.085662,0.027424,-0.329370,0.176710,0.519564,0.230387,0.016437,0.066585,-0.516187,-0.028542,-0.136717,-0.275249,0.068896,-0.428426,-0.045220,-0.747358,0.000232,-0.300106,-0.288262,-0.153699,0.107855,-0.478176,0.688415,-0.591520,0.431859,0.333088,0.066271,-0.295954,0.614226,0.304986,0.175650,-0.116914,-0.347598,0.324961,-0.159460,0.131325,-0.025712,0.327659,0.093706,-0.149682,-0.406408,0.611286', '1299663', '27666513', '1307146', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2073674', '灭顶之灾', '科幻', '地球是人类赖以生存的家园，在供给的同时也在被不断的掠夺着，当地球的忍耐达到极限，人类的下场会是如何呢？近日来，在美国的几大城市里发生了多起离奇的死亡事件，事件现场血腥而诡异。这些人是怎么死的？自杀还是他杀？又因何原因？一切都处在迷雾之中。艾略特（马克·沃尔伯格 Mark Wahlberg 饰）是一名研究自然科学的中学老师，这一连串的事件引起了他的注意，他觉得一切并非巧合。更大规模的人类死亡事件发生了，死亡就像一种病毒一样的在市民之间传染，一时间，城市里人口几乎绝迹。艾略特带着妻子艾尔玛（佐伊·丹斯切尔 Zooey Deschanel 饰）和一群朋友驾着车开始了逃亡之路，他们要躲避的究竟是什么？这连他们自己都不知道。©豆瓣', '马克·沃尔伯格', 'M·奈特·沙马兰', 6.1, 22285, 'tt0949731', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p917548944.jpg', 4.7, 18.7, 51.2, 19.8, 5.6, '0.313068,0.004992,-0.891251,0.402837,-0.143246,0.139239,0.918515,-0.291321,-0.541752,-0.179343,0.222904,0.812189,-0.273011,0.096793,0.016592,0.024669,-0.013477,-0.532113,-0.098177,-0.264424,-0.530006,-0.302918,-0.492954,-0.208472,-0.012102,-0.312377,0.429336,0.367469,-0.322165,0.141753,0.304597,0.444326,-0.157520,0.600734,-0.087457,0.097007,0.018854,-0.108228,-0.130809,-0.029379,0.073708,-0.304793,-0.074970,0.373794,-0.160240,0.283805,0.681229,-0.284046,-0.265557,-0.120697,0.413543,-0.617901,0.089183,0.164415,0.572140,-0.154755,-0.048128,0.198317,-0.013713,0.085872,0.166269,0.378260,-0.931261,-0.027713,-0.024715,0.489782,-0.564083,0.360790,0.112901,-0.220415,-0.011621,-0.238879,0.394366,0.498040,0.242223,0.429848,-0.172880,-0.459628,-0.827854,0.057488,1.074672,-0.133500,-0.507709,0.420954,-0.422431,-0.552522,-0.417118,-0.262904,-0.423819,-0.029184,0.130969,-0.041867,-0.353907,0.699020,-0.447763,0.230224,-0.113323,-0.503122,-0.258501,-0.230237,-0.176440,-0.490285,-0.009331,-0.604640,-0.385299,0.016205,0.071362,-0.195540,0.626641,-0.713541,0.115893,0.864016,0.283779,-0.558197,0.349485,0.076423,0.086269,0.080398,-0.052237,0.115542,0.147780,0.364967,0.167689,0.330532,0.293276,-0.024880,-0.282838,0.654371', '1294941', '25828589', '1309116', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2074035', '菠萝快车', '喜剧', '戴尔（塞斯•罗根 Seth Rogen 饰）有一份令自己和别人都生厌的工作——传票递送员，高中生女友安吉的帅气男同学们又时时令戴尔如坐针毡，于是抽大麻成了他最好的寄托甚至是信仰。戴尔定期在小混混索尔（詹姆斯•弗兰科 James Franco 饰）的家中购买大麻，索尔视其为朋友，推销给他最好的大麻“菠萝快车”，可戴尔只拿对方当做比自己更失败的落寞者。当晚戴尔偶然撞见当地大毒贩瑞德和一名女警联手杀人，慌不择路逃跑的戴尔将菠萝快车这种罕见大麻遗落在现场，担心被瑞德杀人灭口的戴尔和索尔只得选择逃亡，但他们谨慎又笨拙的隐匿方式只是将更多人卷入这场风波，而逃避性格的两人，在这次事件中渐渐学会正视自己的弱点……©豆瓣', '塞斯·罗根', '大卫·戈登·格林', 7, 16955, 'tt0910936', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p916287440.jpg', 1.7, 8.3, 41.3, 34.8, 13.9, '0.537381,-0.062031,-0.397165,0.421342,-0.425837,-0.406571,0.717493,0.113794,-0.418607,-0.036527,0.174519,0.884827,-0.050807,-0.055814,0.174432,-0.014885,-0.488306,-0.620724,0.214776,-0.135871,-0.097081,-0.462871,-0.301654,-0.471615,-0.148394,-0.263330,0.334417,-0.206973,-0.288477,0.248717,0.272433,0.368534,0.064079,0.585519,-0.090348,0.045202,0.002132,-0.417540,-0.101581,0.080883,0.079942,-0.237277,-0.290374,0.267675,0.163018,0.529284,0.488532,-0.125939,-0.116436,-0.151842,0.166816,-0.354123,-0.071618,0.109620,0.174342,-0.163659,0.243935,-0.124930,-0.191392,0.093984,0.262009,0.075721,-0.750361,0.065476,-0.030814,0.098197,-0.469510,0.159195,-0.144642,0.190037,0.253675,-0.230949,0.079555,0.331645,0.298968,-0.028944,-0.153812,-0.215933,-0.524691,0.284501,0.420167,-0.007747,-0.295401,0.178522,-0.284939,-0.299219,0.067384,-0.329534,-0.613049,-0.063687,0.651751,0.032637,-0.062239,0.347877,-0.775294,-0.085708,-0.221741,-0.239593,-0.089674,-0.330697,-0.159852,-0.708654,0.008896,-0.331329,-0.290854,-0.167171,0.381410,-0.278563,0.557239,-0.513913,0.220590,0.556833,0.127317,-0.334337,0.412127,-0.038868,0.245049,-0.016072,-0.369549,0.175090,0.310171,0.242714,0.093010,0.406316,0.143369,-0.000886,-0.123318,0.494937', '4944008', '35161768', '1292000', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2075147', '女伯爵', '剧情', '本片翻拍自1971年的英国恐怖片《德拉库拉女伯爵》，根据真实事件改编，由德尔贝自编自导自演。17世纪的匈牙利，女伯爵伊丽莎白（朱莉·德尔佩 Julie Delpy 饰）的美貌远近驰名。自从她的丈夫在战争中死去，年华渐渐老去的她一直寡居在城堡里。在一次宫廷舞会上，伊丽莎白遇到了英俊多情的贵族青年伊斯特凡（丹尼尔·布鲁赫 Daniel Brühl 饰），两人共坠爱河。而两人之间的私情遭到了伊斯特凡父亲的坚决反对，他强行把儿子送往丹麦，并为他物色了更年轻的结婚对象。伊丽莎白备感失落，向女巫安娜求助驻颜之法，以挽回爱情。传说中，处女的鲜血有驻颜奇效，为了保持自己的美丽，伊丽莎白秘密地谋杀了650名处女，用她们的血来沐浴。而等待着伊丽莎白的并不是爱情的回归，而是被监禁，最后死于狱中。而在这场荒诞血腥事件背后，却隐藏着另一个秘密......©豆瓣', '朱莉·德尔佩', '朱莉·德尔佩', 6.9, 17536, 'tt0496634', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p760331398.jpg', 0.6, 6.2, 49.8, 34.6, 8.8, '0.160976,0.121367,-0.463249,0.439709,-0.118197,-0.327916,0.946852,-0.065003,-0.411283,-0.248386,0.302867,0.774795,-0.139380,0.199716,0.383388,0.219417,-0.440915,-0.629323,-0.085998,-0.086537,0.017493,-0.326645,-0.169277,-0.063864,-0.166470,-0.405284,0.696813,0.005429,-0.075585,0.254019,0.351819,0.507242,-0.086945,0.280591,-0.110568,-0.001551,0.067391,-0.169603,-0.251142,0.233269,0.092116,-0.282844,-0.121972,0.222459,-0.077103,0.433239,0.591049,-0.570082,0.222662,-0.338330,0.463814,-0.093232,-0.005512,0.231852,0.162152,-0.046497,0.319707,0.398225,-0.109215,-0.181404,0.074719,-0.087470,-0.603782,0.096440,0.121832,0.431177,-0.304298,0.545107,-0.134434,-0.017442,0.265881,-0.071674,0.103458,0.059317,0.383782,0.237195,-0.378147,0.016179,-0.441021,0.220002,0.471598,0.247490,-0.175205,0.297363,-0.333572,-0.465700,0.178279,-0.224343,-0.595430,-0.003246,0.412357,0.044592,0.071045,0.558375,-0.573051,-0.143086,-0.491953,-0.027107,0.022724,-0.223327,-0.289156,-0.517823,-0.172591,-0.219690,-0.353005,-0.255547,0.148613,-0.250139,0.482571,-0.708872,0.285952,0.684435,0.219086,-0.467580,0.386531,0.318613,0.139697,-0.210410,-0.347379,0.742370,-0.033891,0.122601,-0.090058,0.256483,-0.012592,0.054811,-0.332718,0.536717', '1296992', '1292528', '129