INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2075345', '穿越西伯利亚', '剧情', '美国夫妇罗伊（伍迪·哈里森 Woody Harrelson 饰）和杰西（艾米莉·莫迪默 Emily Mortimer 饰）坐火车从北京到莫斯科度假。在车上他们认识了西班牙小伙子卡洛斯（爱德华多·诺列加 Eduardo Noriega 饰）和美国姑娘艾比（凯特·玛拉 Kate Mara 饰）。当火车在西伯利亚小镇伊尔库茨克停留时，罗伊因贪恋观光而误了火车，卡洛斯和艾比决定与杰西在下站的伊兰斯基一同等待罗伊乘下班火车赶来。风流的卡洛斯很快便向杰西发起了追求攻势，使本来单纯的观光之旅变得复杂。而下一位与杰西夫妇同车厢的旅客竟是俄罗斯缉毒警官格林科（本·金斯利 Ben Kingsley 饰），随着事态越变越诡异，罗伊夫妇发现自己已深陷危机……本片获西班牙高迪奖最佳艺术指导和最佳电影剪辑奖及最佳摄影、最佳外语、最佳音效和最佳特效四项提名，并获美国科幻、幻象及恐怖电影协会土星奖最佳女主角（艾米莉·莫迪默）、最佳国际影片及最佳男配角（伍迪·哈里森）提名。', '艾米莉·莫迪默', '布拉德·安德森', 6.8, 6981, 'tt0800241', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p488903159.jpg', 1, 7.7, 49.7, 34.1, 7.6, '0.248088,-0.125917,-0.746447,0.512995,0.484130,-0.581667,0.453923,0.342599,-0.201200,-0.115819,0.239234,0.855894,-0.455150,-0.143643,0.701128,-0.018477,-0.818253,-0.559901,0.044811,-0.122170,-0.015543,-0.527556,-0.451810,0.118704,-0.050995,-0.444864,0.541980,-0.346840,-0.017303,0.822937,0.374562,0.240744,-0.137379,0.192812,0.058939,0.115480,0.576792,-0.231550,-0.558128,0.558634,0.242102,-0.145981,-0.237238,-0.220225,0.178370,0.124703,0.557722,-0.086707,0.142703,-0.052554,0.172669,-0.206167,0.127052,0.035635,0.196809,-0.482139,0.207225,0.109470,-0.124208,0.254075,0.131287,-0.053583,-0.290445,0.247974,-0.046209,0.133203,-0.359154,0.090192,-0.306307,-0.195361,0.250205,-0.285869,0.041333,0.509172,0.281197,0.053419,-0.020740,-0.155626,-0.153567,0.410890,0.060646,0.146935,-0.424538,0.440888,0.048529,-0.567656,0.093602,0.083194,-0.344944,-0.159532,0.687393,-0.045939,0.314936,-0.048395,-0.478380,-0.069419,-0.223571,-0.435863,-0.156907,-0.183474,0.171924,-1.379822,0.069443,-0.263270,0.030130,-0.200557,0.012915,0.117780,0.361693,-0.478775,0.253111,0.556035,-0.003836,-0.063003,0.574463,-0.098120,0.201089,-0.323809,-0.352597,0.207874,-0.119197,0.387015,-0.069205,0.354083,-0.047736,-0.137353,-0.417363,0.288796', '34961898', '1293572', '6517421', '1298616');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2075721', '欲孽迷宫', '剧情', '芭芭拉•戴利•贝兰克（朱丽安•摩尔 饰）美艳动人，她的丈夫布鲁克林（史蒂芬·迪兰 饰）是一名探险家。虽然丈夫腰缠万贯，让芭芭拉的生活富足，但她的生活并没有想象中幸福，因为丈夫到处探险的关系，她常常得不到丈夫的陪伴，因而变得让人感觉十分水性杨花。儿子托尼（艾迪•雷德梅纳 饰）成为了她的一切，并常常牵制儿子做事。芭芭拉知道托尼是名同性恋，并极力撮合他与西班牙女友的爱情，可是托尼最后并没有跟那名女孩在一起。布鲁克林却跟儿子的女友私奔了，这样令芭芭拉感到十分伤心。托尼也十分不舍得父亲的离开，他也目睹了母亲自父亲离开后的痛苦。之后他们四处为家，一直患病的芭芭拉还曾自杀过。芭芭拉多年来一直没有放弃要让儿子变回异性恋，她竟然要与儿子发生关系，以让儿子尝试性爱的味道。终于，托尼再也无法忍受母亲了，一把尖刀刺向了芭芭拉……©豆瓣', '朱丽安·摩尔', 'Tom Kalin', 6.3, 6892, 'tt0379976', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p776685125.jpg', 2.5, 15.8, 53.8, 21.8, 6.1, '-0.016859,-0.253998,-0.727263,0.598040,-0.319160,-0.612436,0.995398,0.059465,-0.814361,-0.356553,-0.004165,0.958309,-0.114861,0.291556,0.142803,0.246569,-0.205967,-0.674051,0.120161,0.063883,-0.031159,-0.396476,-0.042323,-0.247381,-0.303146,-0.186117,0.533428,-0.256085,0.042884,0.301026,0.362243,0.202736,0.126937,0.797137,-0.191359,0.096744,-0.152065,0.140203,-0.317435,0.061879,0.283915,-0.056520,-0.051460,0.455963,0.127844,0.234762,0.385065,-0.174006,0.036124,-0.169809,0.063936,0.059819,-0.012683,0.321975,-0.006501,-0.348382,0.321999,0.256473,-0.116517,-0.166985,0.130074,0.028954,-0.663151,0.319982,0.094166,0.162037,-0.647546,0.225185,-0.368816,-0.085121,0.120133,-0.386524,0.269261,0.281265,0.161806,0.328003,-0.367291,0.058881,-0.383280,0.150467,0.830204,0.018340,-0.086795,0.391778,-0.487079,-0.290129,-0.047190,-0.173911,-0.774242,0.127121,0.009447,0.289715,-0.324266,0.446363,-0.372682,-0.105758,-0.376984,-0.057910,-0.041944,-0.489024,0.266948,-0.327146,-0.032876,-0.525320,-0.495517,-0.107414,-0.204576,-0.359766,0.349500,-0.906443,0.328768,0.473584,0.507580,-0.652035,0.517719,0.523364,0.130918,-0.145692,-0.086487,0.788022,0.042694,-0.007389,0.060376,0.159722,0.186798,-0.071253,-0.028241,0.684363', '1308755', '4275444', '26245360', '1309054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2075973', '杀人锦标赛', '动作', '英国的德尔斯布勒，正悄悄展开一场游戏。这是属于富翁和杀戮者的残酷游戏，它每7年举行一次，幕后操纵者以一千万美元奖金为诱饵召集了世界上30位顶尖杀手，在24小时之内，他们将在这个小镇内捉对厮杀，只有最后的王者才能获得巨额报酬。与此同时，富豪们坐在大屏幕前观看现场直播，大赌输赢，场面极其疯狂。本次杀人锦标赛云集了赖莱珍（胡凯丽 Kelly Hu 饰）、安东•博加特、尤里•彼德洛夫（Scott Adkins 饰）、迈尔斯•史雷德（Ian Somerhalder 饰）等身怀绝技、手段凶狠的个中高手，更有怀着复仇目的参加比赛的上届冠军乔舒娅•哈洛（Ving Rhames 饰），这注定是一场血腥而丧失人性的杀戮战……©豆瓣', '罗伯特·卡莱尔', '斯科特·曼', 6.1, 10080, 'tt0471041', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p623719590.jpg', 3.1, 16.3, 57.5, 18.7, 4.3, '-0.195041,0.074842,-0.517483,0.386850,0.171240,0.091630,0.399067,-0.103465,-0.513342,0.036470,0.431850,0.606194,-0.330698,-0.089125,0.563430,-0.450793,-0.339870,-0.562019,-0.365858,-0.280866,-0.362065,-0.327788,-0.305541,-0.098918,-0.141879,-0.128516,0.609698,0.113326,-0.102394,0.483426,0.607021,0.547464,0.155463,0.153067,0.109919,-0.537347,0.387346,0.023146,-0.548879,0.364053,-0.389551,0.022498,-0.482475,0.039518,-0.023120,0.018336,0.731110,-0.511173,0.384810,-0.424930,0.176413,-0.304363,-0.331849,-0.013764,0.174786,-0.062383,0.348600,0.263680,0.206184,0.177402,0.045922,-0.286029,-1.054009,-0.072417,0.079473,0.145665,-0.203168,0.631539,-0.210853,0.023324,-0.080357,0.242161,-0.046405,0.358337,0.375124,-0.083829,-0.029774,-0.312300,-0.420216,0.124209,0.538822,0.056517,-0.191248,0.209523,0.113300,-0.763012,0.047009,-0.738004,-0.199837,0.008465,0.279268,-0.065969,0.265074,0.356093,-0.807179,0.057723,-0.129683,-0.467352,0.191989,-0.202602,-0.420213,-0.812983,-0.094065,-0.081502,-0.190827,0.215415,0.172291,-0.311432,0.785363,-0.821263,0.038883,0.359310,0.137840,-0.147280,0.705332,-0.063091,0.281898,-0.228195,-0.232732,-0.010678,0.029671,0.358363,-0.058654,0.179655,-0.022178,-0.030697,-0.014754,0.843248', '1793491', '3318306', '27098364', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2075994', '连体阴', '剧情', '从泰国移民到韩国的萍（Marsha Wattanapanich 饰）与丈夫伟（Vittaya Wasukraipaisan 饰）过着幸福无忧的生活，就在她生日当天，一通越洋电话改变了她的生活走向。由于妈妈身患重病，萍和伟匆忙赶回泰国，而这也勾起她关于童年过往的回忆。萍出生时还有一个连体姐妹派，由于分离手术失败，派从此殒命，而这也成为萍心中永远的心结。当她踏上故乡的土地，种种离奇诡异的现象接连出现，似乎死去已久的派重新回到萍的身边。而在这一过程中，姐妹俩之间隐藏至深的秘密也渐渐浮出水面……本片荣获2007年奥斯汀奇幻电影节评委会特别奖最佳导演奖；2007年惊叫电影节最佳摄影、最佳导演、最佳剪辑奖；2008年泰国国家电影协会最佳女主角（Marsha Wattanapanich 饰）和最佳原创歌曲奖。©豆瓣', '玛莎·华顿娜柏妮', '班庄·比辛达拿刚', 6.4, 16092, 'tt0484090', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1061058811.jpg', 1.4, 11.6, 57.7, 23.4, 5.8, '-0.206369,-0.004674,-0.757015,0.582672,0.473708,-0.257873,0.491302,-0.166380,-0.296174,-0.210898,-0.003333,0.920270,-0.281990,0.378100,0.493343,-0.085637,-0.409955,-0.868582,-0.066329,-0.342753,-0.314597,-0.131163,0.006625,-0.063082,-0.014600,-0.425200,0.766575,0.124885,-0.036202,0.787682,0.426771,0.195212,-0.456886,0.107998,-0.037381,0.269351,0.125973,0.209697,-0.614173,0.344315,0.174443,-0.518391,-0.178694,0.162432,-0.007488,0.283893,0.877100,-0.321446,-0.308393,0.066516,0.490327,-0.486038,-0.403844,-0.308350,0.322437,0.004748,0.056651,0.405967,-0.328639,0.130621,-0.139411,-0.277771,-0.719458,0.100735,0.188222,0.042909,-0.365340,0.246673,0.069626,0.251129,-0.236158,-0.158617,0.531505,0.547693,0.070929,0.298313,-0.377238,0.222704,-0.142257,0.745808,0.661852,-0.121146,-0.310466,0.458735,-0.165126,-0.229915,0.057856,-0.286651,-0.343900,0.104103,0.311758,0.135968,0.017107,0.085762,-0.343661,0.167924,-0.176402,-0.323935,0.210482,-0.074928,-0.194348,-0.585184,-0.237336,-0.184053,-0.383478,-0.018149,-0.158875,-0.389935,0.648076,-0.619649,0.455429,0.360772,0.174528,-0.486081,0.590921,-0.055776,0.257116,-0.361843,-0.221068,0.467412,-0.428903,0.069664,-0.229554,-0.013179,-0.305872,-0.077830,-0.587781,0.294008', '1780122', '1299663', '3811356', '