INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2076162', '布鲁姆兄弟', '剧情', '史蒂芬（马克•鲁弗洛 Mark Ruffalo 饰）和布鲁姆（阿德里安•布洛迪 Adrien Brody 饰）是从小相依为命的兄弟，他们精于骗术，因此总遭到养父母的抛弃。渐渐地，他们习惯了这种生活方式。在骗局中，总是史蒂芬谋划全局，布鲁姆配合实施。长大后，兄弟俩依旧靠骗术行走江湖，而且还多了一个伙伴——寡言少语但出手不凡的日本女孩邦邦（菊地凛子 Rinko Kikuchi 饰）。三人合作，多次得手，但布鲁姆已经厌倦了这种虚假的生活。这时，史蒂芬计划对独居的年轻富婆佩内洛普（蕾切尔•薇姿 Rachel Weisz 饰）下手，让布鲁姆充当骗财骗色的角色。在交往中，布鲁姆发现佩内洛普是一个多才多艺的古怪女孩，两人在接触中擦出了爱情的火花。但是，骗局即将收官，布鲁姆却苦于恋情与手足情的对立，难以抉择……©豆瓣', '艾德里安·布洛迪', '莱恩·约翰逊', 7, 6202, 'tt0844286', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p896414121.jpg', 0.8, 7.6, 45.3, 34.9, 11.5, '0.355379,-0.187528,-0.450142,0.535933,-0.096585,-0.230885,0.591533,0.215374,-0.468142,-0.211039,0.192893,0.750602,-0.292929,-0.033534,0.267867,-0.114294,-0.353307,-0.900133,0.168252,-0.116093,0.035672,-0.692828,-0.213897,-0.146413,-0.518619,-0.192862,0.608104,0.095131,-0.010836,0.490636,0.283560,0.210219,-0.085810,0.410650,-0.042271,-0.082474,0.252797,-0.066850,-0.401528,0.049697,0.056463,0.021334,-0.333341,0.110115,0.217241,0.530726,0.573766,-0.271451,-0.008739,-0.083398,0.282261,0.004135,-0.081838,0.114601,0.368197,-0.228841,0.291220,0.190163,0.033840,0.095879,-0.013541,0.001523,-0.590143,0.256166,0.194401,0.057855,-0.744339,0.186374,-0.019047,0.012775,-0.265429,-0.059107,-0.035294,0.554596,0.589997,0.311526,-0.112378,0.280106,-0.235540,-0.072075,0.653149,0.246352,-0.646133,0.495927,-0.376288,-0.284382,-0.160848,-0.149723,-0.692688,-0.310517,0.303809,-0.246842,-0.193897,0.398747,-0.745549,0.103985,-0.211937,0.310276,-0.101876,-0.499640,-0.106102,-0.779849,-0.314479,-0.771589,-0.538291,0.088410,-0.107745,-0.325706,0.627561,-0.818360,0.079402,0.335817,0.161480,-0.426413,0.724733,0.360437,0.140900,-0.120403,-0.235453,0.648144,-0.126778,-0.357059,0.124146,0.479559,0.030786,-0.021389,-0.097726,0.305198', '30162520', '4301278', '26322792', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2076181', '无姓之人', '剧情', '在2092年的未来，火星已成了地球人热衷的度假胜地。118岁高龄的尼莫·诺巴蒂（杰瑞德·莱托 Jared Leto 饰）是最后一位仍会死亡的自然人。记忆混乱的他在一次次的催眠及采访之中不断回忆自己的童年，却在每个人生分岔点都衍生出完全不同的人生。在这些不同的版本中，有母亲（娜塔莎·雷托 Natasha Little 饰）和父亲（瑞斯·伊凡斯 Rhys Ifans 饰）离婚后再婚而变成了尼莫“妹妹”的安娜（黛安·克鲁格 Diane Kruger 饰），有身患抑郁症婚后情绪不稳的埃莉斯（萨拉·波莉 Sarah Polley 饰），还有与他育有三名子女的亚洲女孩吉恩（范林丹 Linh Dan Pham 饰）。交织在宇宙大爆炸理论、超弦理论和时间特性的解释中，尼莫的人生真相究竟为何呢？本片获2009年威尼斯电影节金狮奖提名，并获虚构类最佳传记电影奖和Golden Osella最佳技术贡献奖。', '杰瑞德·莱托', '雅克·范·多梅尔', 8.2, 117549, 'tt0485947', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2133687605.jpg', 0.7, 2.5, 18.2, 42.4, 36.1, '-0.011428,0.106687,-0.692244,0.621517,0.186648,-0.312574,0.803121,-0.046275,-0.409095,-0.251201,0.079947,0.830509,-0.272704,0.263650,0.319275,0.012460,-0.570811,-0.611032,0.147699,-0.264129,-0.306284,-0.603323,-0.388411,-0.099034,-0.112878,-0.581835,0.563670,-0.171130,-0.098281,0.225237,0.254305,0.456541,0.043177,0.126944,-0.043371,0.191263,0.165595,0.009135,-0.336172,0.100378,0.035600,-0.117357,-0.139884,0.041400,-0.049195,0.387190,0.688770,-0.440996,0.204432,0.005059,0.634368,-0.032144,-0.070674,-0.110470,0.186871,-0.066788,0.128027,0.206352,-0.132436,0.178714,0.155804,-0.077160,-0.720291,-0.158202,0.284562,0.401177,-0.364300,0.411351,-0.053236,-0.195587,-0.003704,-0.106882,0.012560,0.423581,0.296802,0.378808,-0.175600,-0.070749,-0.425324,0.221909,0.356560,-0.073603,-0.638890,0.449079,-0.539675,-0.539343,-0.363572,-0.152049,-0.491987,0.033654,0.312638,0.110601,-0.058208,0.622646,-0.498961,0.051391,-0.176059,-0.213935,-0.030818,-0.144881,-0.142270,-0.589068,-0.159557,-0.481329,-0.375323,-0.142102,0.149876,-0.215898,0.717614,-0.559022,0.274004,0.421113,0.105573,-0.284030,0.710754,0.120723,0.136653,-0.394980,-0.079059,0.527745,-0.192801,-0.069386,-0.173814,0.341769,0.226767,0.027988,-0.422193,0.54