INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2077287', '激辩风云', '剧情', '本片取材自真人真事，曾获得美国青少年观众票选大奖提名。上世界30年代的德州，黑人被剥夺选举权，并在就业、司法、军役、婚姻等各方面受到隔离和歧视。Mel Tolson（丹泽尔·华盛顿 Denzel Washington 饰）希望自己的同胞们做些事情。他在学校成立了黑人高 校的第一支辩论队。在仔细选拔下，四位学生脱颖而：Hamilton（杰梅因·威廉姆斯 Jermaine Williams 饰）、Henry（内特·派克 Nate Parker 饰）、Samantha（朱尼·斯莫利特 Jurnee Smollett 饰）和James（丹泽尔·惠特克 Denzel Whitaker 饰）。在辩论队成长的道路上，Mel不断的挑战着社会当时的传统观念。他反叛的精神和他激烈的教学方式也不断的被人们炮轰，但他始终坚持着自己信念，最终和辩论队员们一起进入了哈佛大学的辩论殿堂……', '丹泽尔·华盛顿', '丹泽尔·华盛顿', 8.3, 21309, 'tt0427309', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p457136953.jpg', 0.2, 0.9, 14.8, 50.7, 33.4, '0.256159,-0.004886,-0.780762,0.671191,0.130460,-0.227335,0.439284,0.174438,-0.412743,-0.090228,0.225728,0.778297,-0.252924,0.205326,0.173349,-0.374866,-0.422385,-0.980817,-0.066076,-0.040704,-0.416812,-0.612108,0.033556,-0.158040,-0.219132,-0.423581,0.785985,-0.071472,-0.337866,0.454496,0.289695,0.266638,0.217173,0.219755,-0.103945,-0.009486,0.349774,-0.069388,-0.159114,0.038866,-0.069480,-0.201079,-0.399395,0.127683,0.341105,0.255781,0.616312,-0.377933,0.112147,0.054746,0.269719,-0.266704,0.016403,0.319813,0.346109,0.034262,0.087215,0.320543,0.219676,0.095657,-0.092121,-0.166010,-0.468352,-0.102028,-0.012650,0.330300,-0.603347,0.630674,-0.006655,0.070965,0.006846,-0.010932,-0.191351,0.233936,0.183069,0.217286,-0.182706,-0.160286,-0.429275,0.405687,0.593334,-0.028318,-0.541049,-0.207669,-0.578133,-0.486400,-0.330526,-0.251166,-0.552036,-0.285811,0.467420,-0.161952,0.157537,0.135538,-0.597197,0.085795,0.003572,-0.512689,-0.190148,-0.309498,0.325607,-0.886798,-0.044256,-0.333998,-0.394111,0.040222,-0.000607,-0.207428,0.919044,-0.818076,0.183067,0.693353,0.374780,-0.484242,0.692097,0.278013,0.291533,-0.019182,-0.363023,0.139173,0.043582,0.152076,0.078419,0.527123,-0.097313,-0.134911,-0.289341,0.461603', '3811356', '30162520', '25863940', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2078159', '猪头逛大街2', '喜剧', '哈罗德·李（约翰·赵 John Cho 饰）喜欢的女孩玛丽娅去了阿姆斯特丹，他决定追随而至，想尽一切办法赢得她的欢心。在机场，卡玛·派特（卡尔·潘 Kal Penn 饰）偶然遇到了他的前女友温妮莎，却惊讶地发现她就要结婚了。卡玛还没上飞机呢，他就和机场的警卫发生了激烈的争吵，差一点误了事，不过两人最终成功地登上了飞机。由于等不及在飞机上那漫长的6个小时，卡玛跑到厕所里自制了一个“无烟器”--骚乱由此引发，“无烟器”被误认成炸弹，而哈罗德和卡玛则不幸地被当成恐怖分子。这场突发事件致使飞机改变了航向，把他们送到了关塔那摩湾的监狱中关了起来。不甘心的两人成功越狱，从关塔那摩湾跑出来之后，哈罗德和卡玛途经迈阿密抵达德州--温妮莎婚礼的举办地，决定破坏婚礼。但不知道紧随在他们身后的是国家安全局的长官罗恩·福克斯，他要重新抓回这两个高度危险的恐怖分子......', '约翰·赵', '乔恩·赫维兹', 7.2, 9365, 'tt0481536', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1464805463.jpg', 1.3, 6.3, 39.8, 38.4, 14.3, '0.365679,0.222885,-0.960438,0.363931,0.007477,-0.298159,0.744887,-0.085500,-0.239034,0.026793,0.147200,0.636497,-0.273091,-0.045053,0.537092,0.204089,-0.540614,-0.620212,0.057759,-0.243228,-0.631320,-0.492385,-0.005248,-0.357629,-0.001298,-0.101617,0.275314,0.182571,-0.057205,0.442365,0.359345,0.182671,0.046955,0.625648,-0.195857,0.223158,0.101606,-0.014847,0.008279,0.381481,0.133787,-0.297467,-0.161223,0.236034,0.205280,0.360004,0.582131,0.040335,0.052714,0.090292,-0.003270,-0.331968,-0.011668,0.157388,0.547099,-0.095670,-0.288748,-0.171366,-0.287038,-0.057295,0.241698,0.119674,-0.380408,0.171941,-0.315173,-0.032542,-0.614159,0.381246,-0.369331,0.122893,0.108678,-0.439518,0.224604,0.470227,0.133382,0.336162,-0.142067,-0.125078,-0.794441,0.012216,0.831611,-0.018691,-0.251732,0.255778,0.048702,-0.490162,-0.173749,-0.165939,-0.380634,-0.167502,0.857759,-0.137306,-0.152786,0.185752,-0.403277,-0.236018,-0.426580,-0.277522,-0.152235,-0.286592,0.057051,-0.646356,0.111413,-0.357360,-0.146106,0.127945,-0.257101,-0.075283,0.369570,-0.708852,0.240964,0.648834,0.204335,-0.555084,0.550888,0.200814,0.319101,-0.145787,0.205751,0.085178,0.085089,0.621652,0.328903,0.461335,0.080181,-0.231278,-0.433360,0.268958', '3011051', '1303462'