INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2078398', '听见天堂', '剧情', '当上帝为你关上一扇门时，往往他会为你打开另一扇。意大利男孩米克（Luca Capriotti 饰）虽然出身在穷乡僻壤，但他从小就梦想成一流的电影大师，只因他是那么的热爱电影。然而上帝跟他开了一个最残酷的玩笑，米克玩弄一支来复枪时不幸走火，从此他只能淹没在巨大的黑暗当中。 这一度令米克感到沮丧万分，仿佛活着已没有了动力。然而盲校的唐老师的一番话让米克豁然开朗，为什么音乐家在演奏时会闭上眼睛，因为那样音符会蜕变，变的更有力量。于是，米克选择了用耳朵代替眼睛，去记录他生活的点点滴滴。这时，我们才发现：原来，不仅可以看见天堂，还可以听见天堂。©豆瓣', 'Francesco Campobasso', '克里斯提诺·波顿', 8.9, 33676, 'tt0450121', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p501470993.jpg', 0.1, 0.3, 7.6, 40.5, 51.4, '0.164416,0.223201,-0.658852,0.556733,-0.066682,-0.456386,0.967014,0.160744,-0.470693,-0.228479,0.007569,0.732172,-0.217657,0.173462,0.294026,0.093142,-0.246852,-0.573011,-0.052468,-0.229731,-0.186386,-0.235162,-0.150406,-0.418218,0.028311,-0.328025,0.653943,0.077377,-0.408667,0.021876,0.174147,0.299971,0.181608,0.402503,-0.305808,-0.148430,-0.053351,0.286859,-0.068357,0.165045,0.116554,-0.159114,-0.168893,0.118000,-0.506229,-0.054883,0.323307,-0.353837,-0.294316,0.040491,0.379972,-0.268278,-0.126902,-0.062331,-0.090041,-0.124278,0.243105,-0.038769,-0.095127,0.106530,0.108802,-0.003242,-0.705305,-0.098886,-0.028948,0.048193,-0.553990,0.176089,0.065411,0.011981,0.305319,-0.250521,0.275535,0.173000,0.459452,0.528867,-0.527020,-0.150854,-0.647249,0.092307,0.685137,-0.188546,-0.442769,0.641084,-0.191419,-0.478049,-0.038218,0.036967,-0.469406,0.084904,0.140140,0.141829,-0.113070,0.122041,-0.515720,-0.143408,-0.156887,-0.141558,-0.097567,-0.521530,-0.047510,-0.158742,-0.056324,-0.058201,-0.181268,0.151257,-0.034270,-0.363615,0.738823,-0.877563,0.324432,0.428399,0.020448,-0.032694,0.715085,0.186421,-0.216945,-0.095848,-0.016200,0.310449,0.024781,0.482932,-0.017324,0.269286,0.154673,-0.184376,-0.269202,0.665700', '4275444', '1291877', '1783461', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2078804', '攻壳机动队SAC：笑面男', '动画', '2024年，发生了MM制造公司"濑良野基因混合社"的社长绑架案。在收取赎金现场出现的凶犯，居然让自己脸部在所有监视纪录上留下了贴着笑面标志的影像后成功脱逃。案发后六年，"笑面男"的巧妙陷阱再度出现在网络社会中...封印已久的笑面男苏醒了，特A级黑客与九课的巅峰对决即将拉开帷幕！', '田中敦子', '神山健治', 9.2, 6631, 'tt1024215', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2207164758.jpg', 0.2, 0.6, 5.8, 24.3, 69.1, '-0.018754,0.354816,-0.533573,0.255233,-0.065770,0.164981,0.541972,-0.055052,-0.230844,-0.102590,0.321186,0.439854,-0.655947,0.200835,0.339880,-0.445951,-0.098605,-0.799710,-0.123903,-0.538345,-0.573698,-0.037014,-0.455922,0.059649,-0.129185,-0.694321,1.013822,0.105633,-0.400989,0.106867,0.303387,0.497546,-0.484627,0.129226,-0.207324,-0.121876,0.344561,-0.193274,-0.195169,0.518506,-0.269860,-0.403525,0.169320,0.005269,-0.215742,0.169016,0.960446,-0.127712,-0.215149,0.089502,0.472846,-0.426990,-0.182561,0.042582,0.507737,0.166587,0.120288,0.347397,-0.226634,-0.359480,0.201979,-0.124421,-0.814190,-0.236056,-0.065829,0.093918,-0.226101,0.222925,0.022774,0.322042,0.141598,-0.181804,0.416527,0.545231,0.346278,0.195618,-0.016624,0.103766,-0.383053,0.380095,0.362729,-0.175185,-0.594274,0.159232,0.433888,-0.501132,-0.401489,-0.415401,0.026899,0.126626,0.296565,0.170191,-0.062025,0.135858,-0.689667,-0.036973,-0.351666,-0.021503,0.166096,-0.217914,-0.266153,-1.020452,-0.534027,-0.188022,-0.160046,0.258352,-0.030808,-0.328421,0.419094,-0.888743,0.297231,0.466574,0.210434,-0.115933,0.506185,-0.008779,-0.051305,-0.134881,-0.137526,-0.257518,0.382647,0.421121,0.062312,0.418972,-0.228249,0.056994,-0.314261,0.268388', '2369613', '26759820', '25723905', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2078906', '控制', '剧情', '18岁的叛逆男孩伊恩（萨姆•赖利 Sam Riley 饰）最喜欢做的事就是把自己关在房间里听着摇滚乐，对着镜子为自己画眼线。在他的眼中，家乡小镇死气沉沉，毫无出路，而喊出人生真谛的摇滚乐才会使得人的青春有着那么点儿乐趣。这日，伊恩前往伦敦观看著名摇滚乐队性枪手的演出。伊恩似乎天生就是为了摇滚活着，他在演出会现场结识了性枪手的三位成员，当时正在寻找主唱的他们认定了伊恩就是最佳人选。于是，男孩伊恩开始了他的摇滚之路。©豆瓣', '萨姆·赖利', '安东·寇班', 7.9, 14184, 'tt0421082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503108761.jpg', 0.6, 3.1, 23.7, 47.5, 25.1, '0.195321,-0.136404,-0.695755,0.617416,-0.177686,-0.251018,0.940083,0.113592,-0.654805,-0.186834,0.200913,0.729445,0.007064,0.478571,0.536448,0.170655,-0.389937,-0.779478,-0.302981,-0.293084,-0.177909,-0.299105,-0.007269,-0.189942,-0.014365,-0.503909,0.462199,0.119862,-0.213739,0.200173,0.503448,0.179279,0.196251,0.334697,-0.263846,-0.157082,0.081346,-0.181421,-0.118907,0.020054,0.221190,-0.341256,-0.328974,0.246526,-0.334701,0.282860,0.789878,-0.253671,0.066854,-0.088757,0.214431,-0.179248,0.031049,-0.020743,0.139222,-0.224210,0.328616,0.241121,0.094154,0.173385,-0.084147,-0.148246,-0.584485,0.084865,-0.096674,0.252025,-0.449807,0.409362,0.014037,-0.175889,0.597903,-0.316496,0.324990,0.019840,0.268133,0.407982,-0.148858,-0.015470,-0.582561,0.276919,0.484195,0.032772,0.056129,0.483603,-0.389775,-0.513140,-0.172882,-0.213076,-0.628506,-0.194075,0.441289,-0.093537,-0.051015,-0.188855,-0.534880,0.112201,0.192949,-0.469844,0.220845,-0.416337,-0.160086,-0.610937,0.070474,-0.326152,-0.038656,0.054382,0.010868,-0.359101,0.894612,-1.057735,-0.000139,0.895687,0.016325,-0.397398,0.782231,-0.030821,-0.048152,-0.284396,0.115682,0.143886,-0.272526,0.392794,0.042589,0.455515,0.033054,-0.135426,-0.450610,0.711043', '3230462', '3005387', '1292062', '4233625');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2079017', '乐队来访', '剧情', '一支埃及亚力山大的警察管弦乐团受邀前往以色列某城的阿拉伯艺术中心演奏，可他们下了飞机却发现对方没有派出任何人来接待，同时也找不到其他途径好解决问题。一番问路后他们赶往目的地，却发现跑错地方，到了另一个沙漠中的小镇，在善良的餐馆老板娘蒂娜（罗妮•艾尔卡贝兹饰）帮助下，他们在不得不选择休整停留一夜，然后在次日出发。团长的老团长和年轻的队员哈利德（萨累•贝克利饰）产生了矛盾，但他们一起前往老板娘家里留宿，受到盛情款待。其他人则去了另一户家，晚餐气氛有些怪异，他们还得打公共电话向埃及大使馆求助。这一夜过后，第二天他们将带着什么心情离开呢？©豆瓣', '塞森·加布埃', '艾伦·科勒林', 8.1, 6058, 'tt1032856', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2513242444.jpg', 0.2, 1.2, 18.6, 52.8, 27.2, '0.420830,0.055277,-0.935973,0.427237,-0.103972,-0.242208,0.598284,0.157706,-0.435154,-0.338316,0.117018,0.780809,-0.159938,0.319681,0.364658,0.077580,-0.785035,-0.366825,0.056944,-0.334129,-0.444980,-0.426858,0.115360,-0.277224,0.047241,0.173729,0.098232,0.132276,0.082010,0.603763,0.006092,-0.080473,-0.176104,0.732347,-0.304409,0.186038,0.178140,-0.218076,-0.269960,0.526280,0.222884,0.074921,-0.554735,0.188881,0.231922,0.596333,0.491468,0.041410,-0.123992,0.000590,-0.105409,-0.191044,0.225169,0.200837,0.459854,-0.212229,0.214978,-0.069909,-0.119595,0.149463,-0.215434,0.176650,-0.277723,0.458893,-0.096720,0.117825,-0.601218,0.343536,-0.043907,-0.307678,0.035883,-0.613366,0.351625,0.527821,0.080953,0.235567,0.009351,0.041948,-0.603760,-0.177841,1.052568,0.006891,0.076063,0.041529,0.080611,-0.424875,0.267615,0.001236,-0.211246,-0.244117,0.341761,0.119417,0.024982,-0.455925,-0.669157,0.045473,-0.286530,-0.393389,-0.006022,-0.376088,0.034957,-1.098318,0.341886,-0.177140,-0.386772,0.328951,0.174925,0.248180,0.360343,-0.703158,0.126642,0.643056,0.627656,-0.403820,0.619313,-0.068147,0.057081,-0.004005,-0.093761,-0.009008,0.127551,0.759838,0.267192,0.283410,-0.177567,-0.182244,-0.453033,0.117244', '35287558', '3178770', '3871833', '1498831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2079632', '学校霸王', '剧情', '许志皓（林志颖 饰）是个高二新来的转校生，因为家庭富有引起了学校恶霸“乌鸦”（江国宾 饰）的不满，经常对其挑衅欺辱，但幸好有另类同学“老鹰”（金城武 饰）的出手相助才能化险为夷。小志想与“老鹰”做朋友，但却发现他是个很神秘的人并不好相处。“乌鸦”为报复老鹰跟黑道的人有了过节，一次为救校花“公主”（林心如 饰）更遭到痛打。小志得知了此事决定帮助“乌鸦”，呼吁全校一起对他伸出援手，“乌鸦”感激，还与小志一起修好了老鹰父亲留下的车，大家的矛盾得以和解但是“老鹰”并不领情。不料不久后黑社会对学校发起了攻击，学生们奋起抵抗，最终“老鹰”的出现救了大家，黑社会势力得到严惩。©豆瓣', '林志颖', '朱延平', 6.6, 6293, 'tt0115007', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2634404427.jpg', 1.3, 7.3, 58.3, 23.7, 9.4, '0.292162,-0.346275,-0.351950,0.552507,0.025847,-0.042774,0.581240,0.069901,-0.543164,-0.178102,0.121665,0.525814,-0.303127,0.226260,-0.051226,-0.280202,-0.001681,-0.604194,0.306044,0.130153,-0.090535,-0.247760,-0.147498,-0.280934,-0.174264,-0.161007,0.428712,0.101313,-0.096986,0.774096,0.392248,0.132639,0.027101,0.494041,-0.169563,-0.123268,-0.229735,0.333615,-0.260595,0.252672,0.065005,-0.149899,-0.162934,0.211785,0.010954,0.524004,0.334627,-0.135754,-0.323071,-0.299425,0.246703,-0.511291,0.147293,0.244637,0.577743,-0.156044,0.214487,0.016530,0.054017,0.013598,0.000345,-0.115110,-0.330795,0.093580,0.044829,0.028897,-0.565501,0.401699,0.088643,0.072896,0.011488,0.000029,0.023852,0.244647,0.369109,0.096567,-0.130482,0.257265,-0.532854,-0.266830,0.716404,-0.143909,0.049088,0.020463,-0.185652,-0.531389,0.328733,-0.261917,-0.220823,0.028513,0.179263,0.022658,-0.412669,-0.060512,-0.503809,-0.302236,-0.171839,0.260089,-0.026718,-0.681466,0.191955,-0.546093,-0.093716,-0.198685,-0.336540,0.256653,0.196219,-0.288850,0.777284,-1.120247,0.027345,0.380454,0.528542,-0.710758,0.631151,0.182770,-0.234956,-0.168736,-0.058302,-0.242666,0.236870,-0.006305,0.234838,-0.000540,0.083312,-0.536669,0.070046,0.030181', '35030151', '3445516', '4739952', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2080007', '金刚不坏', '动作', '迈克（库尔特•拉塞尔饰）是一个经常与死神打交道的特技演员，久经刺激之后，他俨然成为一个变态杀人狂。一天，他穿上行头，照样开着那印有骷髅图案的汽车上路寻找猎物。在午夜酒吧，他接近了一些年轻女人（罗莎里奥•道森、范妮莎•费丽托、乔丹•莱德、罗丝•麦高恩等饰）。在喋喋不休的她们离开酒吧后，迈克展开了行动，那辆诡异的汽车，便是他的致命凶器。一段时间后，李（玛丽•伊丽莎白•文斯蒂德饰）和她的朋友们（佐伊•贝尔等饰）结伴开车兜风，一路上有完没完地闲聊。此时脸上有疤，目露凶光的迈克又在暗处盯上了她们并一路跟踪，他还能继续可怕的疯狂杀戮吗？©豆瓣', '库尔特·拉塞尔', '昆汀·塔伦蒂诺', 7.6, 55263, 'tt1028528', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p948510953.jpg', 1.1, 4.2, 28.4, 43.9, 22.4, '0.375017,0.012622,-0.485607,0.313047,-0.263647,-0.346045,0.782249,0.122268,-0.208720,-0.142389,0.380704,0.586493,-0.433984,0.124619,0.188890,0.064615,-0.577260,-0.493203,0.137050,-0.056824,-0.288296,-0.214849,-0.242981,-0.266338,0.157129,-0.148943,0.197804,-0.098877,0.102476,0.543965,0.396842,0.113880,-0.080690,0.374430,-0.231995,0.018789,0.325971,-0.134410,0.153051,0.210126,0.070581,-0.106255,-0.063417,0.049205,0.111129,0.108736,0.635260,-0.123378,0.124301,-0.092280,-0.041331,-0.055103,0.292373,0.124439,0.126375,-0.282458,0.270797,-0.017831,0.084903,-0.076800,-0.211060,0.185669,-0.440009,0.303975,-0.371768,0.124964,-0.421142,0.241487,-0.249810,0.076511,0.156271,-0.430030,0.088501,0.136170,0.290744,0.117077,0.187529,0.015099,-0.524470,0.082358,0.372123,0.206048,-0.116613,0.295724,-0.131210,-0.134658,-0.237890,0.164787,-0.527132,-0.435881,0.726758,-0.149321,-0.174905,-0.059312,-0.600813,0.082676,-0.211977,0.009745,-0.158037,-0.019701,-0.208204,-0.987287,0.261789,-0.592129,-0.194335,0.030911,-0.163985,-0.045844,0.420396,-0.538347,0.339987,0.643313,0.258753,-0.413676,0.514994,-0.171417,0.077059,0.015902,-0.143240,0.385177,0.264963,0.261455,0.353665,0.722689,-0.100432,0.101944,-0.289835,0.728170', '34961898', '10466639', '3178770', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2080130', '老港正传', '剧情', '老左（黄秋生 饰）是香港老一代彻头彻尾的左派，他哼唱《歌唱祖国》、《智取老虎山》，高举为人民服务的伟大旗帜。他一生最大的愿望就是能到北京天安门去看看。老左一生全心全意为人民服务，完全没有把心放到自己的小家上，令儿子左忠（郑中基 饰）心生不满。左忠有一个青梅竹马的女友陆敏（莫文蔚 饰），陆敏高中毕业后去了国外留学，左忠不想一辈子和老左一样背着“左”的包袱，利用内地改革开放的机会，展开了内地冒险式淘金之旅。左忠和陆敏在1997年回归后最终满身伤痕回到香港，老左的一生最终将如何落幕？©豆瓣', '黄秋生', '赵良骏', 7.1, 15384, 'tt1031942', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p649264010.jpg', 1.1, 6.3, 42.8, 37.4, 12.4, '-0.245617,0.026606,-0.337252,0.493813,-0.062490,-0.435059,0.204377,0.216310,-0.355132,-0.161679,-0.168417,0.775271,0.304602,0.453903,-0.165153,0.178968,-0.241177,-0.685495,-0.280975,0.002866,-0.554604,-0.138385,-0.132131,-0.063474,-0.264111,0.074178,0.416405,-0.091237,-0.192054,0.431440,0.636718,0.205654,0.195985,0.122765,-0.541903,0.083561,-0.198297,0.182490,-0.604082,0.212883,0.140066,-0.121933,-0.392425,0.136431,0.015913,0.116845,0.851220,-0.188693,0.202042,-0.330646,0.539313,-0.058811,-0.240296,0.052871,-0.158909,0.212932,0.151852,0.194387,-0.402301,0.062117,0.316036,-0.239746,-0.453523,0.011667,-0.144876,-0.165852,-0.838954,0.509660,-0.148226,0.067339,0.153456,-0.860274,0.281381,0.154709,0.005664,0.481550,-0.249444,0.362072,-0.135724,0.569239,1.121959,0.274896,-0.013149,0.131777,0.107332,-0.315828,0.023841,-0.292418,-0.177651,-0.120436,0.310451,0.025898,-0.227643,-0.019063,-0.360258,-0.125108,-0.175905,-0.135319,0.313433,-0.219994,-0.066854,-0.329345,-0.167857,-0.299855,-0.021257,-0.025477,0.043795,-0.434291,0.535972,-0.610819,0.183601,0.342935,-0.032825,-0.623387,1.128819,0.296926,0.087687,-0.087928,0.167881,0.326189,0.058395,0.382046,0.139309,0.170617,-0.418061,-0.061198,0.030283,0.515882', '1308035', '1296978', '1300202', '25881781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2080133', '男儿本色', '动作', '繁盛的中环街道上，突然一声爆炸巨响，押款车一亿美元新钞被天养生（吴京饰）等一帮劫匪于路上公然劫走。多名无辜人员死伤，其中一人为警员陈晋（谢霆锋饰）的未婚妻子。陈晋自此立誓追捕天养生以报仇雪恨，可天养生与一亿美元却不见踪迹。半年后，见习督察方奕威（余文乐饰）带领警员截查车辆时遇袭，队员全体重伤，原来天养生一伙重新出现。高级警司章文耀（林嘉华饰）和罗沛权（郑浩南饰）共同策划连锁行动，誓要将一伙匪徒逮捕。巡警卫景灏（房祖名饰）的哥哥是名打入天养生团伙内部的卧底，碍于身份，他被暂时停职，并想着还哥哥一个清白。三人的追捕中几次不敌天养生，但发现警方有内奸……©豆瓣', '谢霆锋', '陈木胜', 7, 81007, 'tt0995739', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p638370170.jpg', 1, 5.5, 45.7, 36.9, 11, '0.029769,-0.199530,-0.371152,0.306804,0.272713,-0.182282,0.450133,0.029776,-0.626557,-0.408481,0.186662,0.459489,-0.074883,-0.020667,0.479062,-0.239292,-0.200615,-0.716214,-0.248453,-0.273484,-0.502668,-0.422330,-0.138546,-0.229155,-0.093025,-0.292558,0.264854,0.246867,0.093821,0.571521,0.225756,-0.013633,-0.415199,0.268431,-0.002825,-0.063099,0.509556,-0.360067,-0.034848,0.195139,-0.520660,-0.461339,-0.067630,-0.160653,-0.014428,0.452488,0.532314,-0.212365,-0.092963,-0.403409,-0.034071,-0.290251,-0.190943,0.043333,0.626662,0.108547,0.391378,0.262678,-0.346741,-0.043466,-0.063265,-0.099898,-0.520606,-0.069624,-0.117495,-0.089620,-0.292888,0.134072,-0.352540,0.173704,-0.004497,-0.147906,0.182650,0.258557,0.185370,0.124795,-0.107882,-0.160293,-0.406871,0.032311,0.598649,0.017556,0.208597,-0.036687,0.166398,-0.252453,-0.154286,-0.026058,-0.065042,-0.119767,0.466659,-0.049750,0.107121,-0.131452,-0.176282,-0.074335,-0.275988,-0.078906,-0.271436,0.175344,-0.227845,-0.548728,0.150325,0.002845,-0.253201,0.392295,0.208440,0.145614,0.540760,-0.817888,0.144108,0.321664,0.298951,-0.587975,0.289687,-0.036429,0.012341,-0.018145,-0.378756,-0.479659,0.591962,0.426319,0.151909,0.294031,-0.423352,-0.449588,0.047183,-0.430016', '1307186', '35030151', '3387546', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2080707', '恋爱大赢家', '剧情', '王汉文（许绍洋 饰）出身台湾富商家庭，自幼习武，因对经商不感兴趣，前来武校深造。武校女教头钱月珊（杨恭如 饰）为替父还债涉足此业，她与王汉文一见如故。王父闻得此讯，用金钱作筹码要月珊劝儿子回台继承家业，急需用钱还债的月珊认为自己损失不了什么，于是假戏真做，对汉文展开了凌厉的爱情攻势。不法富商杜南（王道 饰）靠走私起家，他有一个不思进取的儿子杜恒风（林志颖 饰），为让儿子回心转意，他巨资买下武校。荒唐的是，他竟然爱上了警方卧底金巧莉（刘亦菲 饰），而刚刚失恋的金巧莉已不再相信什么爱情。©豆瓣', '许绍洋', '朱延平', 6.8, 3870, 'tt1258181', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2363453207.jpg', 9.9, 15.2, 31.6, 13, 30.3, '-0.175239,0.021814,-0.410796,0.402987,-0.358787,-0.314247,0.117088,0.074410,-0.637683,-0.231608,0.209996,0.520241,0.319373,-0.076500,-0.050604,0.075612,0.063264,-0.531447,0.220197,-0.329512,0.048094,-0.530528,0.287121,-0.060033,-0.458939,-0.087729,0.366486,0.008943,0.070551,0.268925,0.468705,0.220527,0.248574,0.102489,0.220777,0.081480,-0.337756,0.149070,-0.544337,-0.035762,-0.031400,-0.139600,-0.265601,-0.021570,0.146653,0.251291,0.463775,0.112004,0.064682,-0.494924,0.405897,-0.203208,-0.270048,-0.123335,0.045244,0.153146,0.258025,0.253680,-0.142121,-0.380866,0.204703,-0.128045,-0.365546,-0.048901,0.095651,-0.085242,-0.663060,0.241917,-0.420067,0.028960,-0.301590,-0.233557,-0.086093,0.435853,-0.010360,0.218582,-0.315068,0.244439,-0.449127,0.842274,0.669298,0.025141,0.147393,0.354912,-0.012315,-0.184018,0.246670,-0.461490,-0.393905,-0.013301,0.088002,-0.185915,-0.109973,-0.063430,-0.142443,-0.268292,-0.087639,0.239445,0.445093,-0.440106,0.029872,-0.235518,-0.150414,-0.217977,0.061100,-0.074513,0.509841,-0.332650,0.623264,-0.722196,-0.214149,0.358295,0.787210,-0.697056,0.440117,-0.286583,0.030937,0.036883,-0.416789,0.185755,-0.232042,-0.055572,-0.095621,-0.104572,0.324028,-0.209212,0.240473,0.058216', '1308035', '1877596', '1305915', '1304920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2081098', '渺渺', '喜剧', '戴诗渺（柯佳嬿饰）是从日本来台湾读书的交换生，被热情活泼的小瑷（张榕容饰）感染，成为好友。渺渺为奶奶寻找初恋时的蛋糕店，却发现它已经成为一家二手的CD店，CD店的老板是一个年轻男子，永远戴着耳机，不与人交流。渺渺不知不觉被他吸引，大大咧咧的小瑷出尽鬼主意帮渺渺问到他的名字以及手机号。这个名叫陈飞（范植伟 饰）的男子过去是个谜，渺渺决心踏进他的世界，小瑷忽然感到失落。当陈飞的故事浮出水面时，两个女生都各自经历了失恋般的痛楚。爱一个人，却无法说出口，那难以言喻的心情在青春时期留下痕迹，当小瑷18岁生日来临，大家去海滩庆祝，虽然心是这样痛，但未来还有好多值得期待。©豆瓣', '柯佳嬿', '程孝泽', 7, 58122, 'tt0984130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1899481641.jpg', 0.9, 6.3, 44.6, 36.6, 11.6, '0.098647,0.280536,-0.539267,0.334991,-0.317460,-0.323454,0.851003,0.138150,-0.309355,-0.207174,0.047743,0.692317,-0.145325,0.469172,0.098837,0.223340,-0.012276,-0.505437,0.230021,-0.214554,-0.090233,-0.040405,-0.061494,-0.007499,-0.151431,-0.061652,0.375607,0.159119,-0.171136,0.434206,0.389080,0.155535,0.008894,0.545834,-0.346434,-0.067450,0.048590,0.027478,-0.116486,-0.045837,-0.111424,0.119350,-0.231312,0.119936,-0.272084,0.379495,0.693560,0.111012,-0.304986,0.011817,0.291629,0.011906,-0.162782,0.013167,0.010677,0.168324,0.220452,-0.267113,-0.147471,0.020839,0.073396,-0.042886,-0.533682,0.187519,0.176848,0.346185,-0.290411,0.191305,-0.026143,-0.304160,0.251258,-0.243085,0.256229,-0.051574,0.176436,0.586684,-0.210488,0.277221,-0.498682,0.139290,0.825896,-0.016223,-0.149614,0.501861,-0.225280,-0.207033,0.257319,0.021503,-0.404604,0.289037,0.093818,0.088165,-0.294913,0.169364,-0.610196,0.054721,0.011470,-0.084072,0.094574,-0.588477,-0.404612,-0.300794,-0.206094,-0.203150,-0.303341,0.138903,0.095514,-0.119142,0.967315,-0.791367,0.227492,0.424105,0.153698,-0.184269,0.824320,0.308887,-0.182320,-0.276752,-0.007535,0.325086,-0.227485,0.062150,-0.107120,0.437733,-0.305481,-0.090660,-0.484455,0.279920', '1292219', '2053515', '4724586', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2081376', '反抗军', '剧情', '1939年，纳粹德国占领波兰，并随之对当地的犹太人进行屠杀与驱逐。大量犹太人在屠杀中遇害，少量犹太人隐藏于森林之中，幸免于难。图维那•比尔斯基（丹尼尔·克雷格饰）便是这群犹太人中的一员。但他并不是一个普通的受害者。双亲被德军残害的图维那在森林中遇到了两个弟弟——祖斯（列维•施瑞博尔饰）与阿斯贝（杰米•贝尔饰），3人一同准备从波兰前往白俄罗斯。但在森林中，他们遇到了幸存的犹太人同伴。大家逐渐聚集起来，食物与物资开始出现短缺，德军的追杀又令他们措手不及。这时，图维那做出了一个惊人的决定：建立一支游击队，反抗德军的进攻。面对德军的精良武器与人海大军，图维那能带领他的部队成功反抗吗？©豆瓣', '丹尼尔·克雷格', '爱德华·兹威克', 7.1, 15653, 'tt1034303', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p675130784.jpg', 0.4, 4.1, 44.8, 40.8, 9.9, '0.557052,-0.081433,-0.764658,0.502147,-0.062143,-0.128578,0.986084,-0.085011,-0.431590,-0.013661,0.181278,0.634169,0.298913,-0.176985,0.239775,-0.321716,-0.397896,-0.669477,-0.141953,-0.109858,-0.320888,-0.218439,-0.531124,-0.623936,-0.158698,-0.220342,0.820857,0.326222,-0.230423,0.485557,-0.012565,0.426164,-0.078563,0.539318,0.080769,-0.024805,0.196781,-0.473746,-0.219857,0.525553,-0.626242,-0.177155,-0.229074,0.182333,-0.080761,0.511038,0.689204,-0.399150,0.228101,-0.449693,-0.078866,-0.444994,0.121434,0.334718,0.390646,0.022319,0.167600,0.010072,-0.089311,0.079937,-0.189499,-0.104775,-0.707139,-0.187118,-0.065155,0.074173,-0.631931,0.358287,-0.012583,0.019479,0.225683,-0.291005,0.120908,0.833596,0.139208,0.191839,-0.241789,-0.260900,-0.724228,0.028453,0.636249,-0.447729,-0.333083,-0.254536,-0.075125,-0.647171,0.106913,-0.206649,-0.264480,-0.263442,0.310530,-0.048206,0.065198,0.452023,-0.986868,0.151398,-0.291600,-0.525397,-0.117963,-0.214782,-0.075059,-0.793617,-0.150791,-0.403147,-0.441129,0.405467,-0.006373,0.298677,0.722326,-0.637739,0.274377,0.547052,0.477230,-0.295326,0.221698,0.152522,0.283101,0.234052,-0.144588,0.545405,0.296811,0.308065,0.219687,0.272462,0.042219,-0.007143,-0.147143,0.257283', '21619567', '1294917', '1292453', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2081493', '弯刀', '动作', '前墨西哥联邦探员弯刀（丹尼·特乔 Danny Trejo 饰）不顾上司的命令，执意追查犯罪头目特雷（史蒂文·席格 Steven Seagal 饰），结果反遭暗算，致令妻女被杀。三年后，弯刀在德州靠近墨西哥边境的地方打工糊口。偶然机缘下，他被神秘人物（杰夫·费伊 Jeff Fahey 饰）相中，受聘刺杀推行强硬移民政策的参议员约翰·迈克劳林（罗伯特·德尼罗 Robert De Niro 饰），但在行动之时弯刀再遭暗算，开始遭到雇主以及幕后黑手特雷的疯狂追杀。危急时刻，弯刀得到露兹（米歇尔·罗德里格兹 Michelle Rodriguez 饰）、移民局女特工莎塔娜（杰西卡·阿尔芭 Jessica Alba 饰）以及许多朋友的帮助。他慢慢了解到这一切背后搅合了政治与毒品的丑恶阴谋，一场正义复仇随即展开……©豆瓣', '丹尼·特雷霍', '伊桑·曼尼奎斯', 6.6, 37308, 'tt0985694', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p650696235.jpg', 3.2, 12.7, 47.4, 27.1, 9.7, '0.148658,-0.049920,-0.483366,0.367676,0.135536,-0.054340,0.494408,0.173151,-0.224819,-0.181224,0.444424,0.498544,0.004266,-0.194471,0.341798,-0.046833,-0.359959,-0.819207,0.190522,0.038138,-0.156971,-0.413193,-0.390459,-0.237119,-0.195596,-0.318552,0.263414,0.139767,-0.135733,0.385603,0.348468,0.585572,-0.105232,0.305033,0.214681,-0.247143,0.555279,-0.370031,-0.515275,0.200232,-0.002315,-0.434568,-0.171531,0.209467,-0.030206,0.515737,0.316344,-0.302472,0.180227,-0.460111,0.320412,-0.114489,0.080157,0.230968,0.425872,0.005981,-0.020889,0.380953,-0.184053,0.018183,0.236367,-0.067523,-0.412957,0.093240,-0.101844,0.080122,-0.492090,-0.059995,-0.312451,0.197454,0.062156,-0.274801,0.182863,0.271346,0.393621,-0.220023,0.088887,-0.109543,-0.326558,-0.036802,0.438443,-0.159363,-0.086792,-0.275877,0.039881,-0.296671,0.184666,-0.217540,-0.158779,-0.134259,0.565967,-0.291369,-0.027261,0.603623,-0.431956,-0.199240,-0.451763,0.113950,-0.133728,-0.154517,-0.133231,-0.623122,-0.221472,-0.068333,-0.118285,0.144494,0.151516,-0.049561,0.142134,-0.473512,0.133891,0.698325,0.186544,-0.278268,0.216590,0.086041,0.316384,-0.133798,-0.251668,0.326778,0.459497,0.096130,-0.000404,0.077520,0.156862,-0.194168,0.153679,0.157026', '10342838', '1293619', '3256172', '26892558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2082012', '闪灵侠', '动作', '在黑暗冰冷充满歌特味道的中心城，身穿黑衣的闪灵侠（Gabriel Macht 加布里埃尔•马赫特 饰）无声无息保护这个他所钟爱的城市。闪灵侠曾是一个名叫丹尼•寇特的联邦警察，凶恶的匪徒夺去了他的性命，借助一项神秘的技术，丹尼重返人间，并以闪灵侠的身份游走在灰色地带，帮助警方处理各种棘手案件。绰号“章鱼”（Samuel L. Jackson 塞缪尔 L 杰克逊 饰）的疯狂科学家是中心城最大的邪恶势力，也是闪灵侠的头号敌人。他正四处寻找大力神之血，以完成其研究多年的永生试验。丹尼的旧情人珊德•沙瑞芙（Eva Mendes 伊娃•门德斯 饰）的出现搅乱了章鱼的计划……©豆瓣', '盖布瑞·马赫特', '弗兰克·米勒', 5.4, 6792, 'tt0831887', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p917370119.jpg', 9, 30.9, 43.6, 12.2, 4.3, '0.265156,0.029669,-0.470821,0.647844,-0.176895,-0.015594,0.674263,0.148873,-0.343014,-0.296983,0.479336,0.664620,0.117654,0.102785,0.123931,0.291370,-0.123770,-0.532944,-0.136091,0.002619,-0.297448,-0.453200,-0.558693,-0.274983,0.117333,-0.459305,0.624623,0.014713,-0.167957,0.181950,0.402372,0.510254,-0.311628,0.457580,-0.152171,-0.219077,0.138453,-0.289077,-0.203712,0.082511,-0.247341,-0.302727,-0.001975,0.273029,-0.258817,0.505862,0.581675,-0.386724,-0.008580,-0.253989,0.389163,-0.623557,0.095968,-0.123785,0.185782,-0.182407,-0.066174,0.280494,-0.282626,-0.132700,0.005982,-0.220349,-0.912405,-0.247065,0.206562,0.278455,-0.435797,0.284340,-0.095750,-0.047112,0.186953,-0.148069,0.051920,0.131974,-0.050953,0.317151,0.104129,0.121244,-0.419309,0.234627,0.306827,-0.118198,-0.427876,0.059273,-0.154113,-0.369617,-0.145381,-0.192305,-0.319300,-0.259688,0.413550,-0.035568,0.069974,0.285306,-0.835670,-0.033593,-0.481897,-0.286126,0.080112,-0.236153,-0.256307,-0.660895,-0.131190,-0.346212,-0.249577,0.074171,-0.021319,-0.201069,0.506314,-0.826425,0.048149,0.702892,0.056662,-0.340206,0.407851,-0.214581,0.114873,-0.301377,-0.510280,0.461366,0.289532,0.277407,-0.062586,0.377169,0.266499,-0.028219,-0.419463,0.530256', '1308585', '3769423', '25774050', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2082013', '欲望都市', '剧情', '凯莉（萨拉•杰西卡•帕克 饰）成为了一个成功的作家，身边依然有3名好友萨曼莎（金•卡特拉尔 饰）、夏洛特（克里斯汀•戴维斯 饰）、米兰达（辛西娅•尼克松 饰）陪伴身边，她们依然时尚美丽。这次凯莉还即将要嫁给一生中最爱的男人Mr.Big（克里斯•诺斯 饰），他们拥有自己的房子。她怀着激动的心情与好友们分享心情。可是婚礼的筹备让大先生感受到了压力。这时米兰达的婚姻出现了问题，因为米兰达的一句话，使大先生对自己这第三次婚姻更感不安了。果然，大先生拒绝在婚礼当天出现，即使他想回头的时候，已经伤透了凯莉的心。好友们极力安慰凯莉，米兰达也深感内疚。凯莉搬回了自己的公寓，在助手的帮助下开始了新生活。凯莉每天都想念着大先生，当米兰达告诉她自己的内疚之处时，她生气不已。几个月过去了，夏洛特再次遇到了大先生，他把即将临盘的夏洛特送进医院，同时也期待凯莉的出现……©豆瓣', '莎拉·杰茜卡·帕克', '迈克尔·帕特里克·金', 7.7, 100871, 'tt1000774', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2237613927.jpg', 0.5, 3.1, 29.6, 43.7, 23.1, '0.109192,0.197578,-0.790753,0.385577,0.033644,-0.574338,0.660239,0.105562,-0.344811,-0.265334,0.279967,0.748112,-0.386538,0.518637,0.364981,0.285064,-0.554341,-0.539699,0.112954,-0.067664,-0.240361,-0.445258,-0.035350,-0.062566,-0.087501,-0.297780,0.151344,-0.049638,0.183052,0.521641,0.298717,0.322390,0.311320,0.518278,0.211041,0.108765,0.319501,-0.108071,-0.217629,0.136463,0.218593,0.116328,-0.209413,0.335143,0.267207,0.191463,0.400044,-0.138621,-0.168096,0.051916,0.260406,-0.153547,0.251924,0.060115,-0.062468,-0.011470,0.138655,-0.023674,-0.394461,-0.022312,0.234142,-0.054129,-0.665434,0.430780,-0.149709,0.095937,-0.561575,0.270453,-0.276848,-0.053166,0.275237,-0.493677,0.110885,0.374607,0.092367,0.199026,-0.362560,0.206670,-0.201101,-0.054596,0.581757,0.063741,-0.073993,0.283677,-0.304428,-0.162500,0.069334,0.170584,-0.553330,0.019284,0.259069,0.275015,-0.148395,0.248731,-0.240055,-0.134655,-0.312108,-0.148183,0.062421,-0.438884,-0.046014,-0.471288,-0.140522,-0.209559,-0.409503,-0.192128,0.103280,-0.167950,0.733449,-0.776602,0.336367,0.356003,0.492118,-0.268060,0.565670,0.311838,-0.015037,-0.016697,-0.165335,0.256856,-0.234500,0.148911,0.223659,0.278082,0.047162,-0.047862,-0.396562,0.571921', '1292219', '1292720', '3230121', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2083735', '庞贝末日', '动作', '故事发生在遥远的古罗马时代，位于庞贝古城的维苏威火山濒临爆发的边缘，再过不久，整座庞贝古城就要在瞬间化为一片废墟，被永久的埋没在史册之中。迈洛（基特·哈灵顿 Kit Harington 饰）从小就失去了父母和家人，被卖到富贵人家成为了奴隶斗士，一位名叫卡西亚（艾米莉·布朗宁 Emily Browning 饰）的贵族小姐出现在了他的生命里，尽管地位悬殊，但迈洛还是不可救药的爱上了她。遗憾的是，卡西亚已经有了婚约，她即将被迫嫁给腐败昏庸的参议员柯福思（基弗·萨瑟兰 Kiefer Sutherland 饰）。火山爆发了，幸存的迈洛决定重返一片火海的城市，原因只有一个，那就是救出他的心上人。©豆瓣', '基特·哈灵顿', '保罗·安德森', 6.2, 38842, 'tt1921064', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2193387860.jpg', 3.1, 17.3, 51.6, 21, 6.9, '0.301504,0.359404,-0.790060,0.396715,-0.085469,-0.234962,0.855144,0.316785,-0.583648,0.057290,0.471084,1.036791,-0.104551,0.261025,0.158966,0.106975,-0.128683,-0.620962,0.011571,-0.405735,-0.235522,-0.470338,-0.390243,0.059593,-0.002268,-0.562321,0.781534,0.191898,-0.157051,0.034789,0.128186,0.256699,-0.067881,0.463338,-0.340363,0.258287,0.083812,0.010790,-0.226320,0.206057,-0.419863,-0.183077,0.130634,0.009962,-0.092718,0.288645,0.420668,-0.321019,0.018579,0.056198,0.403994,-0.333258,-0.128914,0.399309,0.398960,-0.451784,0.096875,0.149126,-0.279425,-0.235073,0.138523,-0.195931,-0.524497,-0.153091,0.164198,0.327219,-0.874605,0.800867,0.047106,-0.516409,0.075757,-0.321255,0.414320,0.078073,0.045801,0.464248,-0.207888,-0.156653,-0.759478,0.254615,0.819375,-0.132975,-0.590916,0.194212,-0.068173,-0.322614,-0.121866,-0.357722,-0.527814,-0.121579,0.479561,-0.170755,-0.236088,0.513404,-0.746941,-0.026517,-0.422213,-0.433249,-0.056015,-0.180952,-0.188480,-0.035374,-0.493118,-0.271518,-0.133613,0.071172,-0.113535,-0.016117,0.607258,-0.769522,0.595010,0.432193,0.401640,-0.145425,0.581108,-0.005103,0.286614,0.144435,0.189245,0.446926,0.031244,0.486422,0.045693,0.131843,-0.064665,-0.226510,-0.375039,0.715078', '25721544', '26245360', '1309069', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2083944', '牛仔裤的夏天2', '剧情', '经过16岁绚烂的夏天之后，这条神奇的牛仔裤一直轮流陪伴着卡门、堤比、莲娜和布莉姬四个挚友，她们把各自的经历作为图案绣在牛仔裤上，相互传递和分享着彼此的心路历程。3年时间过去了，四个女孩子进入了不同的大学，有了新的朋友，大一暑假即将来临，新的奇遇正在等着她们。这个夏天，布莉姬（布蕾克•莱弗利 Blake Lively 饰）跟着考古队去了土耳其，一边探寻古迹一边不断询问自己的过去，陷入了失去妈妈的悲痛。莉娜（阿丽克西斯•布莱德尔 Alexis Bledel饰）与希腊男友分手以后，在学院里遇到了一个心动的男孩，犹豫要不要开始新的恋情。堤比（爱波•塔布琳 Amber Tamblyn 饰）为拍摄电影而忙碌着，与男友的关系进入敏感阶段，不自觉陷入了对爱情的恐慌。卡门（亚美莉卡•费雷拉 America Ferrera 饰）因为朋友们暑假的缺席，加上妈妈为迎接新生命的无暇顾及，接受了去做戏剧节的幕后工作人员的邀请，期间不但被英俊男主角所关注，甚至还被推荐为女主角。这个夏天，将给四个女孩子带来更多惊喜……', '爱波·塔布琳', '萨娜·汉姆利', 7.4, 51765, 'tt1018785', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2094250257.jpg', 0.3, 3.1, 36.8, 44.3, 15.5, '0.427243,-0.024840,-0.572052,0.587191,0.071083,-0.410467,0.743964,0.080540,-0.394257,-0.273342,-0.111330,0.621094,-0.319951,0.415113,0.317865,-0.034747,-0.658890,-0.704282,-0.066103,-0.224830,-0.469897,-0.398975,-0.066414,0.206100,-0.175293,-0.351417,0.364246,-0.191344,0.005009,0.729498,0.420145,0.193142,-0.006324,0.402415,-0.091703,-0.030423,0.222011,0.014399,-0.286656,0.249240,0.173328,-0.021079,-0.101618,0.104476,0.172064,0.265944,0.735479,-0.242844,-0.019060,-0.048638,0.516172,-0.018613,0.073873,0.237205,0.217759,0.285101,0.284539,0.059740,-0.336167,0.253078,-0.013062,-0.327695,-0.737654,0.258017,0.266350,0.286787,-0.658354,0.462088,-0.049188,-0.132805,0.418207,-0.371838,0.167564,0.614131,0.260509,0.444765,-0.258114,-0.006893,-0.379272,0.111701,0.783306,0.061167,0.060978,0.205210,-0.167690,-0.195783,-0.010512,0.070176,-0.549696,0.114031,0.219653,-0.003908,-0.022208,0.240991,-0.862766,0.011136,-0.202043,-0.452773,0.132416,-0.491078,-0.267774,-0.645466,-0.086269,-0.394122,-0.290074,0.137770,0.032432,-0.346114,0.936507,-0.806048,0.281763,0.561777,0.519484,-0.486270,0.825563,0.067313,0.281813,-0.343934,-0.031827,0.256820,-0.014556,0.247711,0.150496,0.531561,-0.239430,-0.015160,-0.477628,0.335953', '3811356', '5977789', '3041753', '26926321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2083967', '奥斯汀书会', '剧情', '伯纳黛特是位温柔的女士，她对爱情总是充满希望，她也关心书会中每个人的生活与心情。她成立的奥斯汀书友会，喜欢把会员聚集在一起讨论奥斯汀书中的内容，每次聚会都会集中讨论一本书。会员乔斯琳（玛丽亚•贝罗 饰）多年来一直独身，她享受与爱犬生活在一起。她的好友西尔维娅（艾米•布伦尼曼 饰）也是会员之一，可是她25年的婚姻受到挑战，她与丈夫丹尼尔离婚了。一次，乔斯琳在电梯里偶遇了后来也加入了书会的格瑞格（休•丹西 饰），乔斯琳极力想撮合格瑞格与西尔维娅。可是乔斯琳看到两人走得越来越近的时候，心里却有点说不出的滋味。而事实上，西尔维娅是一直爱着前夫的，丹尼尔更有与西尔维娅复合的想法。而格瑞格也有心仪的女孩，那便是乔斯琳。西尔维娅的女儿阿莱格拉（玛姬•格雷斯 饰）是位同性恋者，她在母亲婚变后陪伴左右继而也加入书会。阿莱格拉可爱乖巧，但直到她两次受伤住院，母亲才发现自己的女儿原来喜欢极限运动。可是阿莱格拉的情路并不平坦，她的新任女友竟然把她的秘密写成了小说，阿莱格拉伤心不已。普鲁迪(艾米莉•布朗特 饰)也是会员之一，是一名法语教师。可是她的丈夫并不体贴，就在她感到无助脆弱的时候她爱上了自己的学生特雷。普鲁迪的言论并不会完全得到书会中会员的认同，大家都认为她性格怪异。她与新朋友们的相处渐入佳境，而她也要为自己的爱情做出抉择。他们还是相处甚欢的，他们每次讨论一本书，都仿佛把各自的生活观点联合书上内容一起讨论，他们的生活都离不开简•奥斯汀的著作，接下来他们的生活又将受到6本小说带来的影响?', '艾米莉·布朗特', '罗宾·史威考德', 7.5, 12804, 'tt0866437', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p985716869.jpg', 0.4, 3.1, 34.2, 47.8, 14.5, '0.410420,-0.244761,-0.734399,0.616873,-0.104479,-0.339402,0.740349,0.011593,-0.540901,-0.190356,0.196729,0.904628,-0.262491,0.456798,0.219037,0.309020,-0.311511,-0.803651,0.160790,-0.113239,-0.165275,-0.447101,-0.062564,-0.340485,-0.181166,-0.298182,0.347615,-0.153815,-0.067617,0.289221,0.336682,0.181656,0.072097,0.606056,-0.013568,0.008326,0.026406,0.007358,-0.022831,-0.095078,0.205562,-0.053343,-0.247579,0.333784,0.287554,0.378751,0.567351,-0.324116,-0.035057,0.182451,0.267601,-0.187721,0.134325,0.128927,0.210064,-0.108145,0.290653,0.248198,-0.126652,0.044273,-0.048545,-0.068668,-0.608357,0.013763,0.048034,0.185737,-0.540127,0.554006,-0.170937,-0.085182,0.036445,-0.319384,0.125705,0.357458,0.300647,0.218576,-0.197351,-0.231205,-0.324190,0.130615,0.676180,0.135389,-0.300942,0.288547,-0.572017,-0.441618,-0.124427,-0.147224,-0.724450,0.048275,0.071651,0.124190,-0.080067,0.358535,-0.502597,0.089852,-0.193371,-0.219815,0.029220,-0.546953,0.114408,-0.422419,-0.180341,-0.611824,-0.528546,-0.144346,-0.006662,-0.436453,0.933234,-0.841336,0.210666,0.527218,0.358961,-0.493449,0.850324,0.373602,0.003249,0.011386,-0.011542,0.475860,-0.079679,-0.134042,0.179706,0.369230,0.292538,0.019786,-0.148245,0.724572', '30162520', '1309161', '1292720', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2084048', '新家法', '犯罪', 'David（古天乐 饰）、碧咸（苏志威 饰）、碧咸的妹妹阿Ann（杨恭如 饰）、泉（李灿森 饰）从小一起长大，四人宛如兄弟姐妹，David与阿Ann更是青梅竹马。一日，阿Ann在夜总会做陪酒女郎时被黑道社团洪乐社的老大胜（方中信 饰）看上，随后，Ann在酒吧为David庆祝生日时遇到了胜。David与胜争风吃醋发生了争执，打斗中胜错手误伤了泉，使其成了植物人，悲愤不已的David发誓要帮泉报仇。碧咸好赌欠下高利贷无法偿还，被色魔雄要挟用Ann来还债。胜得知后派手下与David、碧咸一起去找色魔雄谈判，岂料谈判破裂双方大打出手，心狠手辣的David奋勇杀出一条血路，斩杀了色魔雄。一时间David闻名江湖，随后加入了洪乐社。David表现出色，很快获得了胜的赏识，他认为为泉报仇的时机已经到了……©豆瓣', '古天乐', '郑伟文', 6.5, 8174, 'tt0885523', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2509803761.jpg', 1.4, 10.3, 57.8, 23, 7.5, '0.002918,0.112780,-0.336396,0.290856,0.287468,-0.325658,0.196252,0.404228,-0.022937,0.032444,-0.066581,0.475599,-0.070299,0.117950,0.170177,-0.526981,0.001139,-0.785450,-0.192503,-0.180598,-0.198950,-0.210520,0.339308,0.199256,-0.087561,-0.211908,0.309845,-0.011519,-0.023630,0.814041,0.711666,0.231684,-0.167612,0.386863,-0.206823,-0.013329,0.050768,0.158235,-0.356196,0.278213,-0.025271,-0.278923,0.057845,-0.024323,0.346135,0.307791,0.644477,-0.198233,0.028923,-0.519332,0.253342,-0.138169,0.169406,-0.011037,0.381040,-0.038837,0.152028,0.241542,-0.316830,-0.216269,0.208755,-0.028688,-0.537194,0.091349,0.414431,-0.225140,-0.733438,0.225596,0.010330,0.076744,-0.136529,0.272679,0.238171,0.414793,0.238471,-0.013956,0.096899,-0.086181,-0.574354,0.027988,1.043061,-0.083477,0.469199,-0.132992,0.255778,-0.295492,0.275728,-0.282512,-0.032061,0.013052,0.540800,-0.282192,0.042893,0.156101,-0.557927,-0.336441,-0.274803,0.284647,0.141319,-0.148701,-0.108362,-0.256795,-0.294857,-0.144998,-0.147134,0.235970,-0.017836,-0.259047,0.504547,-0.694178,-0.111235,0.353402,0.474831,-0.413259,0.652075,-0.083906,-0.053890,-0.329002,-0.057723,-0.099094,0.248881,-0.147720,0.498495,0.330538,-0.154427,-0.057742,-0.289822,-0.033677', '1296978', '25908042', '1419416', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2085498', '海贼王剧场版8：沙漠公主与海盗们', '剧情', '沙漠之国阿拉巴斯坦，虽然当地气候恶劣，但是国王寇布拉爱民如子，为了将国家建设成美丽的绿洲始终和百姓不懈努力。然而就在两年前，奇怪的现象离间了国王和百姓的关系。因为容易引起纷争，世界各国已严禁使用名为Dance Powder的降雨粉。但是阿拉巴斯坦曾大量购入Dance Power，在此之后，除国王所居住的阿鲁巴纳降雨正常外，该国其他区域全部为干旱所统治。一些民众认为寇布拉为己牟利，在克罗克塔尔的煽动下，反叛军揭竿而起，国家危在旦夕。寇布拉的女儿微微公主逃离国家，与路飞等人结伴而行。他们偶然遇见了会变换各种容貌的孟德勒，从而得知克罗克塔尔的阴谋。海盗团扬帆起航，向阿拉巴斯坦进军，一场沙漠大冒险就此展开……©豆瓣', '田中真弓', '今村隆宽', 8.2, 11252, 'tt1037116', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2300517400.jpg', 0.7, 2.1, 19.1, 43.1, 35.1, '0.126294,0.120230,-0.496673,0.623175,0.454007,0.048255,0.428301,0.141578,-0.401700,-0.192622,-0.199330,0.473569,0.093916,-0.338189,0.391974,-0.154974,-0.602236,-0.374740,-0.075064,-0.296975,-0.282676,-0.520108,-0.241169,-0.551159,-0.364163,-0.588407,0.658114,0.488754,-0.268684,0.314354,0.050714,0.234341,-0.236065,0.377206,0.006332,-0.254032,0.064495,-0.160341,-0.456119,0.315826,-0.399948,0.021353,-0.206139,0.173767,0.169686,0.332039,0.573826,-0.580575,0.233422,-0.349587,0.274226,-0.272302,0.553262,-0.048855,0.408219,-0.411949,0.110912,0.036253,-0.115983,-0.182315,0.149921,-0.216504,-0.255254,-0.000637,0.176697,-0.012585,-0.411286,0.142230,0.032641,-0.214225,0.012507,-0.097589,0.286719,0.945559,0.447600,0.267660,0.121874,0.184596,-0.493997,-0.017019,0.816488,0.154372,-0.500675,-0.332040,-0.259469,-0.675167,-0.093922,-0.136226,-0.383723,-0.317126,0.188076,-0.260340,0.290547,0.899565,-0.540248,-0.046296,-0.481861,-0.357945,0.342412,0.083682,-0.030610,-0.550443,0.075967,-0.119386,0.107628,0.195532,0.319105,-0.000090,0.443142,-0.702956,0.327746,0.510099,0.406809,-0.624527,0.391041,-0.035427,0.316281,-0.175331,-0.286381,0.431650,0.437592,0.387160,0.126558,-0.031959,0.097107,-0.134316,0.127112,0.287971', '25978126', '1291824', '1303910', '1453067');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2091015', '谎言之躯', '剧情', '罗格·菲利斯（莱昂那多·迪卡普里奥 Leonardo DiCaprio 饰）曾是一名穿梭于炮火硝烟中的战地记者，如今他受雇于CIA，成为美国方面潜伏在伊拉克的特工，随时追踪臭名昭著的恐怖分子阿尔萨里姆（Alon Aboutboul 饰）。他的上司爱德·霍夫曼（罗素·克劳 Russell Crowe 饰）在遥远的美国坐镇，他凭借手中的电脑掌控大局。通过一个不愿当人肉炸弹的恐怖分子的供述，罗格得知阿尔萨里姆正在策划新一轮的恐怖袭击。在接下来的冲突中，罗格的助手不幸身亡，自己也多处负伤。就在他还未康复之际，又被霍夫曼派往了阿曼。另一方面，对手不断散播与美国军方达成合作的谣言，这令身处虎穴的罗格顿时陷入莫大的危险之中……©豆瓣', '莱昂纳多·迪卡普里奥', '雷德利·斯科特', 7.2, 30903, 'tt0758774', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2345473965.jpg', 0.4, 4.3, 42.7, 41.9, 10.6, '0.387565,-0.038612,-0.932223,0.492567,-0.171543,-0.122932,0.665889,0.076132,-0.677022,-0.211262,0.457066,0.654852,-0.025219,-0.153555,0.234041,-0.061211,-0.467163,-0.818984,-0.067869,-0.094060,-0.210186,-0.717418,-0.711529,-0.282420,-0.289049,-0.412552,0.484562,0.099999,-0.342961,0.214202,-0.084444,0.574271,-0.177999,0.536400,0.047493,-0.034481,0.288973,-0.241576,-0.198983,0.464316,0.087385,-0.207290,-0.099290,0.140897,0.144639,0.621268,0.500919,-0.564419,0.424497,-0.044708,0.255069,-0.328834,0.127411,0.240196,0.340369,-0.139212,0.015137,0.016462,-0.324745,0.035547,0.082209,0.133590,-0.798689,-0.180398,-0.017315,0.344047,-0.477981,0.273758,-0.349869,-0.034774,0.155992,-0.182382,0.080800,0.642180,0.118542,0.195320,-0.077787,0.030970,-0.488490,0.024001,0.648349,0.149194,-0.342701,-0.377362,-0.154551,-0.491058,-0.175569,0.036393,-0.412817,-0.475143,0.551394,-0.159833,0.187441,0.693470,-0.499071,0.140885,-0.541630,-0.267198,-0.238797,-0.007505,0.029893,-0.860048,-0.150375,-0.196475,-0.113768,0.181201,0.138973,0.028210,0.379073,-0.734241,0.393607,0.683768,0.219951,-0.035567,0.212491,0.195209,0.349260,-0.165351,-0.235814,0.431248,0.384764,0.310185,0.269882,0.212963,0.254040,-0.335979,-0.244762,0.375343', '1307442', '1947080', '3231742', '25881247');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2117898', '寂静岭2', '悬疑', '《寂静岭2》改编自热爆电子游戏《Silent Hill 3》。Heather Mason（阿德莱德·克莱蒙丝 Adelaide Clemens 饰）和父亲Harry Mason（肖恩·宾 Sean Bean 饰）在外面逃命已经多年，但她却总不明白那些对他们造成危险的东西是什么。多年来受神秘力量骚扰，更长期被毛骨悚然的恶梦弄得心绪不宁。18岁生日当日，她发现自己被偷偷跟踪，随之而来的事故也让父亲离奇失踪，只遗下一个神秘的讯息。在那场事件中，她发现自己的身份是伪造的，而自己对从前的回忆也成为了梦魇。这一切奇怪的梦和事，引领着她到达那个既陌生又可怕的国度——寂静岭。踏进这里后，Heather发现很多惊人的真相，路上等待她的是恐惧的威吓，而她的身世之谜也慢慢被揭开。各种可怕的生物在这个地方出现，更有人告诉她她就是那个命中注定要来杀光所有梦魇和怪兽的人……', '阿德莱德·克莱蒙丝', '迈克尔·巴塞特', 5.7, 66592, 'tt0938330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1729944511.jpg', 6.5, 26.4, 47.4, 14.1, 5.8, '0.357994,0.096283,-0.823218,0.445810,-0.204854,0.165210,1.050936,-0.338576,-0.752862,-0.574020,0.155439,0.996588,-0.259679,0.358985,-0.154881,0.431807,-0.043188,-0.580577,0.092782,-0.221815,-0.462872,-0.218665,-0.380111,-0.211134,0.057820,-0.271015,0.297062,0.364885,-0.383822,0.289745,0.351655,0.376252,-0.094735,0.803297,-0.321583,0.081422,-0.007855,0.169698,0.190024,0.034554,0.116402,-0.573352,-0.263293,0.660828,-0.374781,0.337938,0.427089,-0.238323,-0.545559,0.088701,0.390155,-0.726893,-0.122872,0.231374,0.346182,-0.109247,0.076278,0.050317,-0.268310,0.083027,-0.113747,0.232856,-0.924603,-0.059601,0.074133,0.328748,-0.610917,0.210532,-0.043410,-0.080244,0.144178,-0.188570,0.416489,0.224449,0.157893,0.386013,-0.261548,-0.254551,-0.593947,0.021193,0.904600,-0.201040,-0.286872,0.479048,-0.149252,-0.365173,-0.142701,-0.221499,-0.496263,0.249063,0.155765,0.126636,-0.303142,0.318779,-0.613623,0.069096,-0.200776,-0.185917,-0.363966,-0.424506,-0.234932,-0.226481,-0.367067,-0.551702,-0.460111,0.220006,0.077899,-0.355967,0.397662,-0.636377,0.459455,0.847939,0.252051,-0.590267,0.442228,0.098127,-0.073123,-0.124515,-0.005788,0.200445,0.076806,0.272160,0.007474,0.300738,0.204578,-0.084230,-0.646276,0.631116', '1292064', '258