INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2117922', '马克思·佩恩', '剧情', '在纽约警察局供职的警探马克思•佩恩（马克·沃尔伯格 Mark Wahlberg 饰）作风硬朗，工作出色。他破解的大案要案不计其数，也亲手将无数罪大恶极的罪犯送入监狱。然而，他冷酷无情的办案方式令他四处树敌，更由此导致妻子、女儿被仇家杀害。为了调查杀害家人的真凶，马克思转入乏人问津的悬案组。在调查某个夜店期间，他邂逅脱衣女郎娜塔莎（Olga Kurylenko 饰），后者在从他家中出来后即被人神秘杀害。次日，马克思与老搭档亚利克斯（Donal Logue 饰）追查谋杀娜塔莎的凶手，但是案件刚刚有所眉目亚利克斯也死于非命，马克思更成为重大嫌疑人。危险正在逼近，马克思最终能否抓到真正的凶手？本片根据同名游戏改编。©豆瓣', '马克·沃尔伯格', '约翰·摩尔', 5.5, 13103, 'tt0467197', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1898868937.jpg', 6.7, 28.5, 50.7, 11.3, 2.8, '0.194251,0.006342,-0.559251,0.312184,-0.096122,-0.133713,0.629773,0.167075,-0.676866,-0.360038,0.288507,0.573956,-0.005627,-0.085016,0.280420,0.109518,-0.449873,-0.567898,0.054862,-0.296223,-0.275074,-0.620087,-0.280718,-0.308891,0.172610,-0.121556,0.417334,0.017558,-0.296108,0.189691,0.230089,0.762334,-0.272325,0.271320,-0.093299,-0.096658,0.382718,-0.110379,-0.266983,0.291700,0.164307,-0.351412,-0.158018,0.121510,-0.291179,0.368760,0.587009,-0.078936,-0.220589,-0.141506,0.409806,-0.499903,-0.056516,0.180929,0.601424,-0.076570,0.043899,0.622991,-0.213408,0.018713,0.001262,-0.056757,-0.846558,-0.131322,0.146506,0.151145,-0.247196,0.030841,-0.353284,0.177822,0.125867,-0.204995,0.101930,0.353643,0.220043,-0.055684,-0.032768,-0.187708,-0.484740,0.398821,0.425885,-0.119377,-0.025149,-0.093609,-0.034046,-0.378479,0.006800,-0.341806,-0.121610,0.101505,0.628998,-0.124309,-0.199621,0.495869,-0.280867,-0.387290,-0.550460,0.009175,-0.186781,-0.268689,-0.067854,-0.652902,-0.267821,0.065529,-0.315539,-0.125696,0.018163,-0.352163,0.277814,-0.527636,0.208175,0.727028,-0.045795,-0.575114,0.339145,-0.006407,0.175330,-0.326511,-0.387603,0.434059,0.784664,0.311834,-0.008596,0.102127,0.158579,-0.381495,-0.330906,0.207357', '1482080', '26352445', '1299335', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2118538', '我去世的吃醋女友', '喜剧', '急躁挑剔的凯特（艾娃·朗格利亚 Eva Longoria 饰）和温柔随和的汉瑞（保罗·路德 Paul Rudd 饰）是一对性格各异、却又得到完美互补的情侣。经过多年的爱情长跑，他们终于迎来步入婚姻殿堂的那一天。然而，美满的婚礼却因一场意外而永久推迟。凯特不幸死于非命，这也给了汉瑞最为沉痛的打击。接下来的一年时间，汉瑞始终沉浸在悲痛中无法自拔。他的妹妹克洛伊（Lindsay Sloane 饰）焦急万分，于是找来通灵者艾丝莉（蕾克·贝尔 Lake Bell 饰）希望能帮汉瑞走出困境。第一次的通灵并不成功，克洛伊偷偷将凯特的日记交给艾丝莉，请她假扮凯特劝解哥哥。在这一过程中，艾丝莉和汉瑞相互吸引。令人想不到的是，已经升天的凯特似乎不愿将男友拱手相让，她竟折返人间！两人一鬼，究竟会闹出怎样的故事呢？©豆瓣', '伊娃·朗格利亚', 'Jeff Lowell', 5.9, 6948, 'tt0785007', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1161432137.jpg', 3.4, 18.3, 61.3, 14.6, 2.4, '0.183287,0.071582,-0.631427,0.481307,-0.080555,-0.413725,0.841443,-0.049356,-0.360580,-0.126261,0.172393,0.616981,-0.308661,0.125506,0.427172,0.138014,-0.361417,-0.606737,0.072666,-0.128595,-0.145387,-0.523126,-0.400814,-0.034302,0.159531,-0.374228,0.394148,0.074312,0.170484,0.595078,0.461994,0.342198,-0.179738,0.485410,0.083374,0.131973,0.195267,0.269896,-0.278268,-0.002800,0.079963,-0.080736,-0.287287,0.292418,0.002810,0.316932,0.610440,-0.275498,-0.042602,0.203886,0.375496,-0.193506,-0.023988,0.056928,0.037001,-0.268667,0.183055,0.187214,-0.289391,-0.063693,0.077788,0.029469,-0.873520,0.244330,0.039187,0.075545,-0.482107,0.458960,0.072376,-0.022592,0.204640,-0.241809,-0.005071,0.663635,0.487581,0.386075,-0.189280,-0.093938,-0.400948,0.111630,0.591532,-0.017779,-0.307412,0.490537,-0.312927,-0.474396,0.140044,-0.286192,-0.553323,-0.011819,0.436341,0.249161,0.007752,0.303383,-0.318862,-0.094155,-0.391073,-0.130586,0.108718,-0.613872,-0.101638,-0.414653,-0.095207,-0.478896,-0.453473,-0.023349,-0.003385,-0.247036,0.566719,-0.536498,0.316799,0.297169,-0.044851,-0.285927,0.725648,0.328730,0.173228,-0.207571,-0.178713,0.364155,-0.109108,0.113943,0.224770,0.324432,0.241375,0.050209,-0.589024,0.472994', '35360296', '1417428', '6745433', '1303077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2122766', '孤堡惊情', '剧情', '劳拉自幼在孤儿院中长大，一大群小朋友天天玩着“一二三，回头看”的游戏，十分友爱。30年后，结婚成家的劳拉带着丈夫和儿子再次来到这座海岸边上的荒废已久的孤儿院，为了重温童年时温暖的回忆以及帮助更多的孤儿，他们决定重建这里。然而7岁的儿子西蒙自从搬来这屋子就开始变得不对劲，他幻想出三个不存在的小朋友嬉戏。劳拉和丈夫担心这个收养又同时患有艾滋病的儿子，劳拉的过度担心让儿子反感。他们一直不相信那些幻觉的真实性，直到一天西蒙失踪了。长达9个月的调查，劳拉开始相信鬼魂的存在，并且发现事情与自己童年时的一位护理员有关，她沉下心来，陪伴这些“孩子们”玩游戏，希望能救出西蒙。©豆瓣', '贝伦·鲁埃达', 'J·A·巴亚纳', 7.4, 62875, 'tt0464141', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p542906219.jpg', 0.6, 3.6, 35.3, 45.4, 15.1, '0.332953,-0.099959,-0.762531,0.301819,-0.181566,-0.475268,0.799568,-0.296434,-0.782054,-0.548867,-0.076218,0.735957,-0.113407,0.986002,0.087487,-0.028623,-0.507657,-0.596702,-0.149722,-0.220518,-0.337850,-0.425237,-0.005248,-0.318117,-0.108217,-0.228342,0.405148,-0.005825,0.245036,0.509476,0.082992,0.137502,-0.004947,0.286510,-0.138985,0.157048,-0.086202,0.250921,-0.205597,0.113843,0.153746,0.177684,-0.135237,0.071364,0.115984,0.086255,0.787833,-0.166331,-0.351080,-0.323737,0.358452,-0.090654,-0.170465,0.231106,0.302573,0.145957,0.355700,0.025259,-0.256350,-0.038501,-0.316300,-0.122765,-0.401553,0.060242,0.048815,0.143450,-0.607655,0.044765,0.095296,-0.144596,0.146898,-0.312128,0.253549,0.696808,0.022629,0.631415,-0.509501,0.172800,-0.410450,0.067461,0.774185,-0.367046,0.002123,0.385739,-0.082865,-0.229937,0.082868,0.016777,-0.535304,0.085594,0.035698,0.239704,-0.444594,0.351271,-0.395839,0.110811,-0.077324,-0.171255,0.098273,-0.398291,-0.146893,-0.317782,-0.104080,-0.306510,-0.295989,0.021939,-0.015234,-0.458768,0.777992,-0.860888,0.451984,0.400944,0.424450,-0.565716,0.579418,0.167425,0.155362,-0.360817,-0.050333,0.443363,-0.070169,0.036006,-0.033735,0.109350,0.000797,-0.084453,-0.441195,0.347566', '1292219', '4861627', '1427834', '2365260');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2123510', '深海寻人', '剧情', '在每一个城市，深受精神困扰的人在100个里就占9个。精神科医生高静（李心洁 饰）在工作中凡事以病人的健康为重，深得同事喜欢。在书店她与一名男子擦身而过，男子买下她想买的摄影书，高静感觉有些奇妙。小凯（梁洛施 饰）是高静的病人，从外地休假回来后带高静参加一个摄影展，高静意外地发现摄影中的正是潜水的自己，更意外的，摄影师正是那天在书店遇见的男子，也是小凯的哥哥——考古学家陈国栋（郭晓冬 饰）。国栋将那天买下的书送给高静，二人从此堕入爱河。为了向高静求婚，国栋和高静、小凯前往与那国岛，潜入海底深处找出藏在那里的钻戒。谁知国栋出事了，只打捞起一具无头的男尸。高静由于太过悲痛而失去了关于那件意外的记忆，小凯对自己态度异常冷淡，高静寻求院长（梁家辉 饰）给自己做催眠，然而催眠之后幻觉更多。©豆瓣', '李心洁', '徐克', 5.9, 31610, 'tt0896815', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p746266823.jpg', 5.2, 22.6, 50.8, 16.5, 4.9, '0.225786,-0.252141,-0.540330,0.298575,-0.215330,-0.393937,0.955264,-0.034413,-0.596810,-0.395747,0.332982,0.810728,-0.005894,0.299955,0.377869,0.218830,-0.269964,-0.387602,-0.049341,-0.110015,-0.277617,-0.311399,-0.295781,-0.025981,-0.014739,-0.332806,0.522372,-0.018258,-0.319117,0.533798,0.192271,0.138624,-0.090744,0.621276,-0.124377,-0.051329,-0.197811,0.021671,-0.137990,0.247658,0.249866,-0.305952,-0.181673,0.211311,0.047758,0.321819,0.706256,-0.079469,-0.312742,0.076917,0.452317,-0.132151,-0.161855,-0.010409,0.064799,0.227881,0.264745,-0.011323,-0.461977,0.182118,0.158997,-0.070780,-0.450830,0.075932,0.145080,0.460759,-0.449454,0.364672,-0.077396,0.057263,0.233925,-0.481609,0.227585,0.119447,0.010542,0.444208,-0.297203,-0.118420,-0.331437,0.199690,0.386808,-0.020497,-0.007969,0.472263,-0.178865,-0.388464,0.257050,0.163994,-0.369310,0.201718,0.149162,-0.020541,-0.233525,-0.105483,-0.493165,0.042677,0.050344,-0.049579,-0.207541,-0.241253,-0.237373,-0.426300,-0.085370,-0.199463,-0.231244,-0.100343,0.053210,-0.337504,0.512447,-0.721993,0.220924,0.407433,0.276315,-0.341460,0.618987,-0.031523,0.031220,-0.343754,-0.120706,0.048057,-0.035166,0.286257,-0.135640,0.366224,0.071204,-0.381943,-0.512702,0.106817', '1296534', '1908318', '1309172', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2123782', '苹果核战记2', '动作', '西元2133年，世界陷入荒芜与混乱，愚蠢的人类亲手用核武器摧毁了自己赖以居住的场所。硝烟与战火散尽之后，孕育着希望的新城奥林帕斯建立起来，高科技的产物生化人 隆重登场，充当着服务人类的重任，而ESWAT则担负起保卫世界和平的重任。在一次执行任务中，布里艾诺斯（山寺宏一 配音）为保护女友迪娜•纳兹（小林爱 配音）而身受重伤，之后ESWAT高层利用布里艾诺斯的基因制作了生化人特雷斯，并让他和迪娜组成新的搭档。虽然颇有抵触，但在一段时间的相处后，迪娜内心深处悄悄发生着变化。与此同时，各地接连发生机器人失控危及人类的情况，而他们使用的武器全部指向了重工业最大生产国波塞冬。奥利帕斯高层研究加强对通信卫星的监控，突然之间，ESWAT内部经过改造的半机械人也失去控制。新的危机呈现，迪娜面临重大的抉择……©豆瓣', '小林爱', '荒牧伸志', 7.5, 8186, 'tt1043842', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1011870454.jpg', 0.6, 3.3, 32.5, 46.6, 16.9, '0.086112,0.153602,-0.821484,0.358243,0.040985,-0.062429,0.601056,0.057620,-0.461179,-0.358378,0.365555,0.475417,0.128323,-0.056421,0.379462,-0.194902,-0.559991,-0.640517,-0.139356,-0.023642,-0.542004,-0.528913,-0.405048,-0.561584,-0.113685,-0.768212,0.752244,0.130943,-0.305542,0.182922,0.075905,0.385778,-0.174203,0.449037,0.306481,-0.320720,0.198896,-0.124924,-0.475279,0.340139,-0.139942,-0.021683,-0.095673,0.248278,-0.015065,0.330831,0.599683,-0.637365,-0.114279,-0.550675,0.224729,-0.451474,-0.039993,-0.108213,0.281670,0.134156,-0.232266,0.111770,-0.307684,0.046365,0.190492,-0.185012,-0.922780,-0.188993,0.122047,0.075639,-0.413251,0.456319,-0.049249,-0.065709,-0.019274,-0.254860,0.233672,0.681738,0.588714,0.495793,-0.229189,0.209205,-0.301128,-0.157196,0.636275,-0.266002,-0.621295,-0.001093,-0.424317,-0.481565,-0.320883,-0.449738,-0.404991,-0.228460,0.000417,0.267844,0.014833,0.605774,-0.810248,0.127119,-0.255365,-0.386106,0.033904,-0.222423,-0.023186,-0.875292,-0.213577,-0.213194,-0.240036,-0.010352,0.113373,-0.264105,0.775830,-0.856705,0.369078,0.342152,0.460881,-0.297698,0.234809,-0.089058,0.357568,-0.458201,-0.249474,0.354464,0.049532,0.453909,0.048703,0.082517,0.072441,0.082862,-0.380048,0.467402', '2369613', '5308201', '26667010', '27098365');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124507', '火线特攻', '剧情', '纽约两位资深警探特克（罗伯特•德•尼罗饰）和罗斯特（阿尔•帕西诺饰）是一对亲密无间的老搭档，二人合计已在警署工作100年。特克脾气火爆，而罗斯特处事圆滑。最近，纽约出现了一位连环凶手，特克与罗斯特二人负责调查此案。在调查过程中，他们发现凶手有特殊的习惯与高超的射击水平，而更奇怪的是，被害人都与特克有千丝万缕的联系。天使般代表正义的警察，与恶魔般代表罪恶的犯罪者。谁才是真正的特克？一段段迷雾拨开，惊人的真相在内心的黑暗处等待。©豆瓣', '罗伯特·德尼罗', '乔恩·阿维奈', 6.6, 14644, 'tt1034331', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p715239352.jpg', 1.3, 10.3, 52.7, 28, 7.6, '0.335861,-0.374684,-0.479921,0.482292,0.196655,-0.095077,0.825042,0.036270,-0.751897,-0.337030,0.285973,0.569250,-0.254005,-0.232825,0.378264,-0.122559,-0.422132,-0.884027,-0.099240,-0.252943,-0.154261,-0.808702,-0.671440,-0.271943,0.025905,-0.301244,0.401399,-0.041300,-0.044416,0.474170,0.268916,0.523978,-0.289898,0.037930,-0.166895,-0.346455,0.297183,0.007071,-0.393023,0.029252,0.034019,-0.079047,-0.201121,-0.062960,-0.099763,0.419920,0.378648,-0.294300,-0.103611,0.033053,0.094670,-0.274435,0.115429,0.166228,0.565547,-0.301195,0.138633,0.408373,-0.223719,-0.005209,-0.198511,-0.103860,-0.842410,-0.002364,0.260665,0.482412,-0.337026,0.284593,-0.195125,-0.235892,0.253401,-0.215992,-0.111355,0.266132,0.247504,0.327137,0.227495,-0.249045,-0.288765,-0.188493,0.541143,0.113569,-0.445822,0.020703,-0.182992,-0.520563,-0.507081,-0.043799,-0.393397,-0.111777,0.233007,0.097983,-0.039737,0.400627,-0.738283,-0.000781,-0.297178,0.095975,-0.274298,-0.293335,-0.091922,-0.860954,-0.393761,-0.694998,-0.358254,-0.034544,0.165524,-0.016391,0.508533,-0.890747,0.353340,0.335341,-0.009758,-0.342295,0.646537,0.073425,0.136588,-0.428041,-0.170992,0.097900,0.560781,0.144874,-0.036996,0.377297,-0.037913,-0.053779,-0.261270,0.142469', '1307442', '25723905', '3006892', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124586', '飓风营救', '剧情', '特工布莱恩(利亚姆·尼森 饰)深爱着女儿凯姆(麦琪·格雷斯饰)，却由于工作的原因难以给予她日常的父爱，失望的妻子带着女儿改嫁他人。退休后，见识过太多黑暗势力的布莱恩生怕女儿受到伤害，费尽心力的守护她却也因此带给凯姆种种束缚，引发了父女间的矛盾。17岁生日后，凯姆执意和朋友前往巴黎旅行，无奈的布莱恩只好答应，不成想灾难正等着年轻的凯姆。在电话里亲耳听到女儿被绑架后，布莱恩强忍内心的痛苦只身踏上了营救女儿的征程，而他只有96个小时。©豆瓣', '连姆·尼森', '皮埃尔·莫瑞尔', 8.3, 243490, 'tt0936501', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1595764830.jpg', 0.1, 0.7, 14.7, 52.2, 32.2, '-0.135314,0.062634,-0.826564,0.501777,-0.136726,-0.455263,0.713565,0.191340,-0.743207,-0.405746,0.120546,0.760960,0.002872,0.453678,0.483406,0.036619,-0.399873,-0.369645,0.072326,-0.104657,-0.236268,-0.392410,-0.015995,-0.107358,0.006718,-0.372023,0.354361,0.200485,-0.023362,0.565016,0.257249,0.374267,-0.104375,0.700691,-0.041526,0.149631,0.167948,0.114958,-0.318901,0.035972,0.232070,-0.203740,-0.141981,0.342759,-0.113354,0.402735,0.430228,-0.210580,0.050558,-0.231920,0.190729,-0.381232,0.064790,0.067087,0.076690,0.124451,0.343141,0.184048,-0.264173,-0.180581,0.175177,-0.118628,-0.541268,0.195573,0.086706,-0.012583,-0.652930,0.305951,-0.322052,-0.015762,0.157545,-0.203471,0.140466,0.346141,0.004087,0.398681,-0.456652,0.324229,-0.275993,-0.000192,0.701132,-0.276376,0.009719,-0.062794,-0.385045,-0.319497,0.276706,-0.469297,-0.841807,0.108418,0.141656,0.339624,-0.216773,0.221676,-0.250446,-0.284903,-0.435120,-0.111613,0.130727,-0.598608,-0.085848,-0.402790,-0.025512,-0.206366,-0.271447,0.147069,0.051354,-0.163737,0.469677,-0.588433,0.522125,0.433455,0.467681,-0.491900,0.551832,0.231490,0.347586,-0.193402,0.044271,0.629694,-0.233414,0.219960,0.119049,-0.016084,0.106381,-0.115864,-0.252606,0.474150', '2075721', '25723780', '1857175', '21354767');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124703', '疯狂的赛车', '喜剧', '在一次全国自行车锦标赛上，倒霉的职业车手耿浩（黄渤 饰）以0.01秒的微弱差距败给撞到狗屎运的对手，屈居亚军，随后他又遭奸商李法拉（九孔 饰）算计，因药检呈阳性而被终身禁赛，他的教练（马少骅 饰）因此气倒。多年后，耿浩靠开车运送水产为生，养活中风的教练，而当年的骗子李法拉则依靠其推销的补品“肾白银”大发其财。李嫌弃彪悍魁梧的老婆，因此雇用两个业余杀手（王双宝 & 巴多 饰）杀妻，结果杀手反被老婆买通；耿浩的教练急火攻心，一命呜呼，耿浩遵照师傅遗愿前去找李法拉讨说法，谁知反中了李的奸计；东海（戎祥 饰）所率领的台湾黑帮来到内地和泰国毒贩（Worapoj Thuantanon 饰）做生意，但耿浩和李法拉的争执引来了警车，也搅了他们的好事。原本不相干的几组人马，由于偶然的机缘而上演了连串好戏……©豆瓣', '黄渤', '宁浩', 8.3, 348919, 'tt0851515', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2510069458.jpg', 0.3, 1.4, 16.8, 46, 35.5, '0.069321,-0.040815,-0.592894,0.540582,-0.117150,-0.493208,0.595728,0.157655,-0.157461,-0.161791,0.295589,0.330475,-0.159182,-0.110948,0.325635,-0.396997,0.093455,-0.425808,-0.007566,0.041983,-0.497919,-0.159510,-0.208666,-0.261687,-0.317290,0.072156,0.332230,-0.042621,-0.210300,0.461156,0.652340,0.368903,0.156602,0.125191,0.002201,0.214361,0.077704,0.241606,0.040405,0.142977,0.119415,-0.437195,-0.019466,-0.311282,0.056797,0.450541,0.565503,0.011683,0.118987,-0.318233,0.195702,-0.334121,-0.022953,-0.037546,0.373073,-0.097961,0.065710,-0.256159,-0.110838,-0.094368,0.200513,0.162547,-0.425824,0.034953,0.165898,-0.163060,-0.540491,0.233097,-0.241134,-0.010536,-0.137929,-0.235674,0.099689,0.270309,0.273044,0.242005,0.118991,0.104641,-0.557329,0.343784,0.482986,0.058743,-0.059015,-0.252373,-0.083541,-0.463460,0.246074,-0.428323,-0.267908,0.114308,0.664460,-0.480253,0.199413,0.094465,-0.405292,-0.210987,-0.024988,0.066948,-0.215260,-0.072794,0.088976,-0.499164,0.191315,-0.279128,0.050544,0.284629,0.268453,0.062867,0.405202,-0.286674,0.025973,0.373579,0.097690,-0.647194,0.453111,-0.115165,0.088913,-0.321458,-0.200778,-0.075070,0.342259,0.319305,0.456482,0.397523,0.019289,-0.204506,-0.073177,0.217783', '1301345', '1297710', '1310167', '1295586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124708', '形影不离', '剧情', '《形影不离》讲述的是发生在中国某南方城市的一个多线索和情节曲折的另类故事，它兼具剧情、心理悬疑元素：吴彦祖扮演的李越是一个工作和家里遇到麻烦不断的年轻工程师。他的妻子阿胖（龚蓓苾饰）是个貌似很情绪化的暗访记者，而闫妮饰演的上司给李越带来了不少压力。故事的开始，李越因种种原因试图自杀，却巧被他的老外邻居老查（凯文·史派西 饰）救下，俩人因此成为了好朋友。于是“失控”的他们共同踏上了生命中的一个完全意外的旅途。但老查真的只是一个普通的邻居吗？©豆瓣', '凯文·史派西', '伍仕贤', 5.9, 20805, 'tt1032763', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1502874615.jpg', 5.2, 22.5, 49.3, 18, 5, '0.600279,-0.144651,-0.374119,0.724380,-0.067068,-0.074281,0.838839,0.035527,-0.486513,-0.467306,0.039390,0.678568,-0.141454,0.253378,0.133308,-0.283961,-0.230912,-0.427639,0.073403,0.177879,-0.333579,-0.385453,-0.321362,-0.204040,-0.235141,-0.261870,0.525230,0.096673,-0.232785,0.337859,0.334125,0.321472,-0.076134,0.379924,-0.166719,0.311471,0.234316,0.119621,-0.072337,0.164582,0.106006,-0.139815,0.007008,0.303283,-0.164116,0.456990,0.654945,-0.006937,-0.372004,0.024370,0.517696,-0.337285,0.116360,-0.043216,0.314444,0.047881,0.397245,0.072489,-0.028800,-0.030879,0.105712,0.013437,-0.824723,0.107600,0.172298,0.201271,-0.377299,0.286922,0.159265,-0.165041,-0.029580,-0.391706,0.202627,0.297081,0.516753,0.224064,-0.236341,0.039710,-0.412591,0.217266,0.846425,0.160281,-0.279624,0.579865,-0.279117,-0.501569,-0.066175,-0.051157,-0.555886,0.151579,0.273524,-0.240384,-0.222941,0.169237,-0.833092,0.104342,-0.063982,-0.150047,-0.179649,-0.362733,0.089929,-0.427307,-0.194082,-0.527246,-0.219919,-0.033433,0.006000,-0.258562,0.794018,-0.559659,0.084086,0.770633,0.067283,-0.727567,0.642616,0.319137,0.135967,-0.196961,0.030050,0.018646,-0.025819,0.063110,0.120829,0.400381,-0.159327,-0.274708,-0.484724,0.446927', '2053515', '26678784', '3785918', '35360296');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124718', '跳出去', '剧情', '农村姑娘彩凤（张雨绮 饰）跟同伴来到一家号称哈佛毕业生开的诊所，希望可以通过整容手术变漂亮，但是整容医生（吴彦祖 饰）的拙劣表现，令她们无功而返。后来，两人挤上了开往上海的货车。来到大城市，人生地不熟，彩凤却对大屏幕里的街舞情有独钟，原来她也曾经是乡舞蹈队的一员。然而，现实的压力却让她只能把梦想暗藏心底。一次偶然的机会，她进入了朗（立威廉 饰）所开的红星公司，虽然工作是清洁工，但可以有机会接触到街舞，让她非常兴奋，时常默默练习。朗是公司老板，富家子弟，每天周旋于红男绿女之间，希望通过街舞大赛帮公司创品牌。他遇到彩凤后，被她对街舞的执着打动，便提供了一个机会，希望帮她实现梦想。然而，因为一次误会，令彩凤伤心地回到了家乡。她还能有机会站在五光十色的舞台上实现梦想吗？©豆瓣', '张雨绮', '冯德伦', 5.3, 10410, 'tt1035733', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p708932573.jpg', 12.1, 29.2, 43, 12, 3.7, '0.134707,0.137845,-0.548741,0.445405,-0.129032,-0.282011,0.470456,0.004663,-0.615569,-0.074923,0.230834,0.578840,-0.157272,0.299055,0.206188,0.083525,-0.115312,-0.544075,0.404284,-0.080846,-0.027411,-0.235479,-0.194346,-0.215440,-0.218402,-0.201993,0.594697,0.123881,-0.124526,0.434854,0.170595,0.010167,-0.017831,0.391205,-0.306953,-0.255736,0.065687,0.269721,-0.355835,0.437556,0.023762,-0.184426,-0.156707,0.038356,0.262895,0.105924,0.523956,0.149816,-0.213204,0.129373,0.243171,-0.051013,-0.005628,0.111818,-0.031494,0.090585,0.327753,0.121771,-0.082907,-0.051571,-0.104078,-0.153506,-0.708155,0.267875,0.293017,-0.091100,-0.852788,0.572568,-0.106472,-0.210202,-0.005521,-0.280443,0.192685,0.131878,0.468599,0.214005,-0.151254,0.288694,-0.529906,0.127839,0.740862,-0.099353,-0.060490,0.500872,-0.203902,-0.287130,0.026942,-0.047967,-0.332980,0.233121,-0.062089,-0.088097,-0.198775,-0.314307,-0.605096,0.104600,-0.359713,-0.212345,0.248521,-0.390359,0.099621,-0.401608,0.151363,0.017819,-0.341048,0.106782,0.017730,-0.558365,0.714761,-1.096536,-0.008208,0.620172,0.461577,-0.459449,0.943660,0.083238,-0.048361,-0.268317,-0.070354,0.094274,-0.247077,0.383996,-0.082518,0.381750,-0.125168,-0.323708,-0.212139,0.378942', '35030151', '2052978', '22964524', '1299062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124724', '不能说的秘密', '爱情', '叶湘伦（周杰伦 饰）是淡江艺术高中的一名插班生，父亲（黄秋生 饰）是该校的一名教师。这天同学晴依（曾恺玹 饰）带他参观学校，接着他独自来到了学校的旧琴房，本身弹得一首好曲的他被某处传来的一首钢琴曲吸引住了。他来到其中一间旧琴房，遇到了路小雨（桂纶镁 饰），纯纯的爱情故事由此发生了。一直以来，叶湘伦都觉得小雨充满了神秘，却无法进一步了解她。叶湘伦约小雨到琴房见面，叶湘伦以为晴依是小雨，跟晴依接吻时被小雨看到，自此之后叶湘伦就没有再看到小雨。叶湘伦到处寻找小雨，发现了那个小雨所说“不能说的秘密”的全部真相。©豆瓣', '周杰伦', '周杰伦', 8.1, 465151, 'tt1037850', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2568025412.jpg', 0.4, 2.5, 23.6, 39.9, 33.5, '0.834911,-0.055660,-0.644901,0.379847,-0.026108,-0.183632,0.712527,0.172895,-0.461449,-0.326812,0.234195,0.547010,-0.313790,0.395194,0.067221,0.015258,-0.290688,-0.622882,0.214072,-0.343324,-0.216721,-0.278025,0.331923,0.459520,-0.086325,-0.195959,0.386307,-0.066740,-0.134860,0.842049,0.038275,0.241346,-0.044037,0.190861,-0.241489,0.254435,0.279659,0.207779,0.095555,0.250580,0.120978,-0.273011,-0.420168,0.110862,-0.311690,0.228194,0.662411,0.272002,-0.034330,0.351395,0.259234,-0.160872,-0.042367,-0.031758,0.398962,0.152555,0.239071,0.177194,-0.317974,0.114931,-0.144401,0.091905,-0.302102,0.261775,0.128264,0.485984,-0.187196,0.273409,-0.112360,-0.322184,0.404154,-0.446675,0.208343,-0.001951,0.134439,0.626188,-0.192004,0.102003,-0.472674,0.181317,0.709045,-0.343969,-0.056531,0.657033,0.096390,-0.165367,0.296982,0.217733,-0.556996,0.420240,0.264117,-0.028531,-0.274291,-0.229774,-0.594431,-0.002784,-0.059467,-0.276133,0.017274,-0.402143,-0.401697,-0.427288,-0.339838,-0.437615,-0.150872,-0.026926,-0.196698,-0.295644,0.691832,-1.025740,0.073978,0.163284,0.111865,-0.321608,0.486736,-0.199862,-0.108701,0.392861,0.285168,0.129737,-0.228780,0.610270,0.212409,0.723669,0.288254,-0.331571,-0.481726,0.019872', '1292219', '5977789', '1296332', '1304942');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124737', '第十九层空间', '惊悚', '大学四年级女生春雨（钟欣桐）的好友清幽某日收到神秘短信后，将春雨带去一栋被废弃的教学楼，并请春雨帮她拍下照片，在计算机里看拍的照片时，春雨只感受到恐惧，产生不祥的预感，不久，清幽离奇死亡，春雨在其手机里看到“GAME OVER”的短信。其后，秋雨收到已死去的清幽发来的短信“你知道地狱的第十九层是什么吗？”，再度毛骨悚然，却也按捺不住好奇要查出清幽死亡的真相，便按手机短信的提示进入游戏里的地狱世界，而她的另外两个也在玩此游戏的好友文雅、素兰，相继遭受不幸在不同的游戏阶段“GAME OVER”。与此同时，警探叶萧在调查中，渐渐将目标人物锁定在大学心理辅导教授严明亮（谭耀文）身上。©豆瓣', '钟欣潼', '黎妙雪', 4.2, 8937, 'tt1039892', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2276638887.jpg', 29.2, 40.2, 25.4, 3.7, 1.5, '0.336049,0.161197,-0.623405,0.606687,-0.048245,0.138543,0.585923,0.094034,-0.570552,-0.065573,0.298052,0.562671,-0.480479,0.459731,0.260500,0.102603,-0.257347,-0.652021,-0.071304,-0.381213,-0.516638,-0.367799,-0.289595,-0.014714,0.458920,-0.207030,0.406540,0.153781,-0.239766,0.682905,0.116111,0.317555,-0.546270,0.604778,-0.287212,0.181886,0.032578,-0.003131,-0.094551,0.190323,0.175434,-0.303017,-0.122341,0.111174,0.133546,0.446975,0.742595,-0.085035,-0.223318,0.351588,0.562486,-0.035684,-0.277266,0.101730,0.536601,0.507670,0.100682,0.141751,-0.387531,0.270978,-0.349069,0.084511,-0.574863,0.080205,-0.119589,0.394644,0.008241,0.314362,-0.148007,-0.099603,0.284018,-0.027135,0.334949,-0.047241,0.110051,0.637366,-0.165787,-0.037448,-0.066503,0.011764,0.235230,-0.112662,0.171111,0.562817,-0.170783,-0.354141,0.158204,0.316747,-0.236488,0.085138,0.498460,0.341326,-0.360003,0.038894,-0.621584,0.069185,-0.024532,-0.154210,-0.256804,-0.461489,-0.605243,-0.614107,-0.357655,0.057730,-0.316739,0.232455,0.145525,-0.120778,0.574155,-0.838763,0.410001,0.303989,0.232954,-0.064483,0.577771,-0.038953,-0.050732,0.058371,0.221660,0.274301,0.168363,0.842758,0.032409,0.330241,-0.473863,-0.220531,-0.643431,0.457615', '1309194', '1301948', '3044878', '2357711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2124751', '夜车', '剧情', '吴红燕（刘丹 饰），中国西部平川市人民法院一个普通的法警。丈夫病亡，独身十年，她的生活黯淡无味，每日里做着例行的工作，法庭上出示证物，判决后送走一个个绝望的人。对她来说，也许只有每周去兴城婚姻介绍所才能让生活有一丝希望，然而幸福却与一次次与她擦肩而过。一个女犯因故意杀人被判处死刑，吴红燕作了她的送行者。女犯的丈夫李军（奇道 饰）因此憎恨上这个沉默的女警，时常尾随其后，伺机刺杀。但是，未曾染血的刀子被丢下，两颗孤独寂寞的心却走到一起……本片荣获2007年第23届华沙国际电影节新导演和新电影大奖。©豆瓣', '刘丹', '刁亦男', 7.5, 11072, 'tt1032941', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p824142415.jpg', 0.6, 3, 33.3, 47.9, 15.1, '0.100101,0.108080,-0.582966,0.750977,0.029768,-0.343737,0.784400,0.124960,-0.323132,-0.096540,0.220344,0.767030,-0.111827,0.267714,0.141796,-0.060992,-0.303935,-0.707304,-0.183733,-0.236023,-0.274380,-0.172646,-0.026199,0.007985,-0.158105,0.043060,0.629277,-0.005722,0.127740,0.741850,0.374768,0.219168,-0.082212,0.426712,-0.124126,-0.150208,0.227123,0.168997,-0.383346,0.315597,0.155353,-0.348103,-0.198714,0.053234,-0.066837,0.369351,0.603807,-0.037726,-0.156168,-0.136682,0.539331,-0.414347,-0.161760,0.249417,0.207685,0.296593,0.121070,0.155053,-0.320471,0.142672,0.063796,-0.074278,-0.632857,-0.025950,-0.044090,0.041298,-0.622562,0.565416,-0.191748,0.219378,0.026758,-0.141568,0.404207,0.186500,0.261359,0.312500,-0.218367,-0.000912,-0.403430,0.430232,0.709984,-0.089511,-0.274555,0.136341,-0.145134,-0.409983,0.288859,-0.172411,-0.448673,-0.101221,0.189764,0.049993,-0.196503,0.023090,-0.429161,0.215226,-0.240437,-0.124709,0.044146,-0.318866,-0.020128,-0.425505,-0.025397,-0.352315,-0.456793,0.155985,0.191900,-0.299856,0.464041,-0.468197,0.427607,0.444855,0.368586,-0.485007,0.819767,0.296041,0.221453,-0.034393,-0.059152,0.246686,0.051662,0.381520,0.089452,0.349567,-0.180956,0.109263,-0.170820,0.483587', '1361252', '30162520', '3119246', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21248460', '王牌情敌', '喜剧', '二十世纪七十年代，各种冒险家混迹在自认为遍地黄金的香港。宋池雄（黄宗泽 饰）憨厚耿直，屡找工作碰壁。一日，他偶遇为人狡诈的夏石森（谢天华 饰），恰巧夏也在找活干，得利于夏石森的巧舌如簧，俩人一起来到茶楼打工。茶楼老板（冯淬帆 饰）原先也靠打工起家，深知生存的不易，他待手下伙计如同家人，加之街坊盏鬼整日里插科打诨，茶楼倒也每天妙趣横生生意红火。不料情祸迭出，宋池雄与夏石森同时爱上太子女美洋洋（徐子珊 饰），演出了一场追爱悲喜剧。时光荏冉，金触风暴席卷港岛，人到中年的宋池雄（谭永麟 饰）本分地捍卫着茶楼，当年的美洋洋（叶玉卿 饰）也早已成人妻人母，而当年的伙计夏石森（陈百祥 饰）已平步青云当了老板......©豆瓣', '谭咏麟', '钟澍佳', 5.6, 6768, 'tt2927086', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1846147508.jpg', 7.9, 26.2, 49.2, 12.5, 4.2, '-0.047665,-0.199818,-0.410890,0.341675,-0.028218,-0.451645,0.403591,0.518015,-0.406985,-0.176119,0.144088,0.481949,-0.086582,0.073551,0.432474,-0.175070,0.070265,-0.407230,-0.154140,-0.086385,0.376193,-0.008254,-0.125472,-0.294397,-0.128110,-0.055700,0.169717,0.134132,0.279247,0.559911,0.345505,-0.044895,-0.406391,0.139090,-0.119874,-0.132886,-0.070685,0.319895,-0.302210,-0.092582,-0.271837,-0.341041,-0.253590,-0.418343,0.162972,0.304612,0.420410,0.053087,0.003388,-0.071723,0.386509,-0.081677,0.039778,-0.082031,0.352484,-0.179534,0.437415,0.156296,-0.117934,0.000511,0.169918,-0.160799,-0.312060,0.054476,0.148493,-0.198946,-0.450825,0.377789,0.161060,-0.144768,-0.244782,-0.142971,0.204017,0.132101,0.219367,0.238338,0.236064,0.148120,-0.451862,0.631004,0.438497,0.171049,0.231434,0.302949,0.158809,-0.213147,0.185952,-0.218113,-0.556018,-0.215393,0.035844,-0.259128,-0.008868,0.081700,-0.542978,0.217684,-0.018917,0.195107,0.148200,-0.063295,0.016675,-0.576940,-0.142832,-0.384005,-0.053604,0.095681,0.278157,0.014508,0.414891,-0.529701,0.133457,0.279711,0.103458,-0.333846,0.687848,-0.191554,0.143467,-0.222608,-0.194876,0.070446,0.070296,0.144122,0.113961,0.320989,-0.270394,-0.271536,-0.223181,0.168832', '3326747', '6068516', '1306860', '2278795');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21263664', '燃情主厨', '剧情', '米其林餐厅如日中天的当红大厨亚当·琼斯（布莱德利·库珀 Bradley Cooper 饰）因浪荡度日，毁了前程。然而受挫的他深信天分并未衰减，于是毅然回到伦敦，卷土重来，找来一群年轻厨师，开一家史无前例的超级餐厅重振雄风。', '布莱德利·库珀', '约翰·威尔斯', 6.5, 24846, 'tt2503944', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266452142.jpg', 1.3, 11.4, 55.9, 24.9, 6.5, '0.120735,0.187675,-0.460909,0.105598,-0.171822,-0.672313,0.661493,0.850081,-0.376094,-0.587629,0.187571,0.858452,-0.067091,0.201677,0.544463,-0.310531,0.180590,-0.132318,0.307211,-0.087868,0.361665,0.030175,-0.306551,-0.282335,-0.090122,0.065169,0.444982,0.157046,-0.302736,0.416904,0.235639,0.190806,0.281034,0.064191,-0.397737,0.138082,0.210124,-0.181195,-0.521176,0.515929,-0.120512,-0.227987,-0.258640,-0.160066,0.115659,0.091663,0.434544,0.394485,-0.229770,-0.253317,0.553646,-0.009944,-0.264337,0.054007,0.350606,0.118075,-0.060698,-0.105398,-0.156533,-0.110440,-0.091064,-0.160386,-0.536416,0.199110,0.193737,-0.273451,-0.441650,0.269915,-0.039761,-0.228747,-0.120894,-0.345805,-0.047413,-0.157504,0.267339,0.286157,0.410863,0.649181,-0.652041,0.044241,0.522504,0.169998,0.172509,0.265488,0.316597,0.036025,0.463791,-0.695843,-0.735844,-0.146488,0.279829,-0.036515,0.403096,-0.004433,-0.354593,0.047680,-0.602577,-0.295504,0.260960,0.107367,-0.204487,-0.948220,0.156103,0.082524,0.080243,0.080869,-0.089910,0.082694,0.517924,-0.627290,0.146426,0.347195,0.135065,-0.701930,0.552953,-0.246211,0.162703,-0.059599,-0.361051,0.457054,0.107105,0.290784,-0.189915,-0.011250,-0.261722,-0.476184,-0.124477,0.219880', '3183490', '1829654', '6731985', '1299166');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21263666', '美国狙击手', '动作', '克里斯·凯尔（布莱德利·库珀 Bradley Cooper 饰）原本是一名普通美国牛仔，“911”事件以后他以30岁的高龄参加了海豹突击队，并成为了伊拉克战场上的一名优秀狙击手。参军之后克里斯认识了塔雅（西耶娜·米勒 Sienna Miller 饰），两人很快结婚生子，但是随着克里斯的多次出征伊拉克，两人的家庭发生了很多问题。战场上的克里斯十分优秀，被队友称呼为“传奇”，恐怖分子以高额奖金请职业狙击手猎杀他，但屡次都未得手，可是身边的队友却一个个遭遇不测，虽然妻子三番五次恳求他退伍，但是他抱着为队友复仇的信念最后一次出征……本片改编自克里斯·凯尔的自传《美国狙击手》©豆瓣', '布莱德利·库珀', '克林特·伊斯特伍德', 7.7, 113677, 'tt2179136', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2203481530.jpg', 0.5, 2.1, 27.9, 51, 18.6, '0.295108,-0.021848,-0.418714,0.656988,-0.038733,-0.498994,0.479181,-0.123220,-0.393003,-0.393987,0.259049,0.876059,-0.011636,-0.044802,0.076650,-0.135959,-0.174700,-0.638743,-0.048290,0.005838,-0.462721,-0.459828,-0.349046,-0.206584,-0.342607,-0.224156,0.847723,-0.215485,0.098560,0.673789,0.361192,0.436762,0.510188,0.409441,0.070861,-0.046873,0.477140,-0.119018,-0.301964,0.365716,-0.295380,-0.038792,-0.316708,-0.012597,0.109898,0.368780,0.523698,-0.132389,0.001582,-0.402942,0.196212,-0.127783,0.237746,0.184819,0.376675,0.119424,0.400321,0.232415,0.382045,0.050550,-0.113079,-0.162730,-0.602950,0.149859,-0.099336,0.009759,-0.622854,0.197681,-0.496472,0.363196,0.284736,-0.268786,0.024422,0.350641,0.338057,-0.000514,-0.352939,0.042524,-0.364491,0.244653,0.775468,-0.055061,-0.345391,0.057211,-0.338223,-0.458385,0.005371,-0.335265,-0.510089,0.452143,0.243609,0.041049,-0.151097,0.193661,-0.245884,0.041343,-0.603559,-0.287310,-0.368130,-0.211690,-0.004187,-0.677924,-0.022374,-0.329182,-0.616152,-0.049950,-0.092128,-0.155017,0.745917,-0.737117,0.173395,0.552200,0.126617,-0.520633,0.413597,0.351883,0.163357,-0.265090,-0.113393,0.302229,0.039363,0.019204,0.132049,0.248196,-0.133578,-0.161907,0.136508,0.498896', '35030151', '3811356', '1870681', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21264315', '鼹鼠之歌', '喜剧', '由于涉嫌用枪支威胁“守法好市民”，当初以史上最差成绩从警校毕业的小巡警菊川玲二（生田斗真 饰）正式被署长酒见路夫（吹越满 饰）宣布开除公职。当他怒不可遏之际，却得知自己已被选为卧底，潜入关东头号黑帮数寄矢会，搜集会长轰周宝（岩城滉一 饰）操纵制造与贩卖毒品的证据。在经受了魔鬼教练一美先生（远藤宪一 饰）的折磨蹂躏后，玲二从头到尾焕然一新，走进了数寄矢会所控制的俱乐部，在此用鲜血结识了一生的兄弟——有着疯蝴蝶之称的阿湖义组的若头日浦匡也（堤真一 饰）。当他总算迈入黑道大门时，来自关西的蜂乃巢会则图谋挑起一场东西黑道大战争。站在风口浪尖的玲二，此时早已没有抽身的机会……本片根据高桥升的同名漫画改编。©豆瓣', '生田斗真', '三池崇史', 6.7, 11712, 'tt2643394', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2157703214.jpg', 1.7, 10.4, 48.7, 29.4, 9.8, '-0.024996,-0.003129,-0.533600,0.304895,0.041893,-0.299844,0.401207,0.237635,-0.179114,-0.253733,0.361304,0.561780,-0.282186,0.042758,0.339611,-0.258746,-0.165863,-0.692856,-0.089757,-0.267290,-0.157144,-0.241672,-0.408306,0.147441,-0.046548,-0.255285,0.685301,0.002430,-0.514230,0.418544,0.215436,0.158248,-0.009883,0.102725,-0.035806,-0.275277,0.199379,0.213583,-0.190465,0.078494,-0.216599,-0.305129,-0.040997,-0.090596,0.165296,0.398420,0.536032,-0.504170,0.079906,-0.234925,0.204654,-0.294542,-0.008997,0.030083,0.282587,-0.020617,-0.131671,0.218837,-0.249469,0.029279,0.013725,-0.301080,-0.776417,-0.276532,0.180058,0.060536,-0.415753,0.400126,-0.128264,0.032121,-0.008698,-0.093377,0.168634,0.268883,0.034095,0.404739,-0.082063,0.248170,-0.420791,0.289685,0.488643,-0.082268,0.054238,0.015933,0.153879,-0.451161,-0.045016,-0.074131,-0.090940,-0.084200,0.384429,-0.103529,-0.104517,0.159537,-0.381820,-0.179940,-0.152464,-0.005876,0.225533,-0.041349,-0.167976,-0.491895,-0.116895,-0.009661,-0.022490,0.156055,0.206726,-0.064238,0.556403,-0.770780,0.129351,0.196152,0.086222,-0.341241,0.279056,0.176235,-0.078140,-0.195644,-0.370392,0.103443,0.365878,0.580256,0.206104,0.335441,-0.197151,-0.538398,-0.181350,0.192773', '4127270', '1826173', '1793491', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2127676', '驱魔道长', '喜剧', '一眉道长九叔（林正英 饰）擅长降妖除怪，麾下两个徒弟阿星（倪星 饰）和小月则鬼马顽皮，经常作出令师傅头疼的事情。九叔师徒所在的酒泉镇教堂曾发生离奇惨剧，屋顶的十字架遭雷劈，将神父活活插死，教堂从此荒废关闭。二十年后，吴神父（午马 饰）计划重开教堂，九叔知教堂处在酒泉镇至阴之地，重开必伤人命，遂极力反对。而镇长之子David（杨子孺 饰）欲借教堂做不法勾当，极力主张重开。九叔拗不过众人，只好作罢。然自此，内中邪祟重返人间……©豆瓣', '林正英', '午马', 7.3, 17338, 'tt0106841', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2238829096.jpg', 0.5, 4.5, 41.3, 36.5, 17.2, '0.065862,0.236741,-0.512240,0.186119,0.323976,0.149790,0.252360,0.202244,-0.430920,-0.501171,0.011030,0.251163,-0.125406,0.193827,0.169426,-0.134656,-0.090986,-0.286897,-0.016890,-0.214505,0.028420,-0.276171,0.262796,-0.262350,-0.376195,-0.226727,0.332794,0.329644,0.288200,0.182525,0.434202,0.396597,-0.427926,0.022976,0.108050,-0.040930,-0.045202,-0.004032,-0.362990,-0.163968,-0.162638,-0.324120,-0.024587,-0.078819,0.082866,0.101467,0.442655,-0.418909,-0.364204,-0.447528,0.142231,-0.102044,-0.120916,0.317091,0.314466,0.150396,0.260605,0.467819,-0.295637,-0.209148,0.248803,-0.195532,0.185938,0.154752,0.540163,-0.334263,-0.301023,-0.047077,0.129109,0.184486,-0.107110,-0.232460,0.184959,0.066753,0.575375,0.243766,0.110275,-0.144323,-0.245099,0.082290,0.471909,-0.336523,0.142616,-0.167284,0.303900,-0.048717,0.266264,-0.254633,-0.088539,0.225743,0.220300,-0.227820,0.130419,0.196414,-0.115793,-0.452128,-0.346902,0.282639,0.097621,0.124008,-0.026146,-0.603872,0.369507,0.213299,0.212470,0.050945,-0.023302,0.153968,0.105376,-0.277614,0.341166,0.106079,0.262277,-0.331573,0.552605,-0.087614,0.520927,-0.229062,0.004441,0.332325,0.035151,0.467904,0.038222,-0.127791,0.173559,-0.138086,-0.061175,-0.069899', '1794401', '26794701', '5384590', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2127788', '不请自来', '剧情', '病重的母亲死于火灾，令乖乖女安娜（埃米莉·勃朗宁 Emily Browning 饰）备受打击，甚至企图自杀。经过一段时间的精神康复，安娜获准回到阔别已久的家中，那里有她身为作家的父亲史蒂芬（大卫·斯特雷泽恩 David Strathairn 饰），亲密无间的妹妹爱丽克丝（阿莉尔·凯贝尔 Arielle Kebbel 饰）以及令她不知该如何对待的未来继母——妈妈曾经的护士蕾切尔（伊丽莎白·班克斯 Elizabeth Banks 饰）。在此期间，安娜接连看到母亲凄惨恐怖的身影，好友马特（Jesse Moss 饰）则声称见到了火灾当晚的一切。种种迹象表明，安娜的母亲并非死于意外，姐妹俩自然而然将凶手锁定在蕾切尔的身上。未过多久，马特遇害。阴云重新笼罩在安娜一家人的头顶。这个可怜几近崩溃的女孩，在真实和虚幻之间彷徨失措……©豆瓣', '艾米莉·布朗宁', '查尔斯·瓜德', 6.8, 20833, 'tt0815245', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2315888153.jpg', 1, 7.5, 51.6, 32.6, 7.4, '0.174860,-0.029271,-0.692756,0.206969,0.141817,-0.281803,0.749599,0.188153,-0.579018,-0.440714,0.465103,0.686341,-0.259289,0.372149,0.399686,0.086152,-0.466337,-0.760908,0.004240,-0.223119,-0.276655,-0.601036,-0.172308,-0.013034,0.041271,-0.605621,0.382222,-0.236876,0.318512,0.556500,0.146610,0.557232,-0.143474,0.290833,0.309564,0.180688,0.173591,-0.125123,-0.534238,0.006592,0.277197,-0.053341,0.047783,0.346692,0.007144,0.260274,0.607532,-0.491980,-0.114688,-0.127609,0.510210,0.038413,0.171746,0.221566,0.247134,-0.121874,0.303293,0.000181,-0.430846,-0.130797,0.204782,0.147843,-0.395520,0.145317,0.248825,0.108888,-0.412401,0.183330,-0.216727,-0.080181,0.228667,-0.375631,0.070203,0.563163,-0.036960,0.712182,-0.342176,0.201138,-0.203452,-0.084459,0.554404,0.087000,-0.234153,0.222301,-0.159478,0.106278,0.019789,-0.175379,-0.700040,0.175213,0.264812,0.184109,-0.039006,0.625760,-0.231111,-0.408812,-0.590311,0.117143,-0.084052,-0.302238,-0.408626,-0.423736,-0.180584,-0.208155,-0.108837,-0.282776,-0.202822,-0.088878,0.375149,-0.825217,0.606142,0.075696,0.287133,-0.196675,0.282186,0.027139,0.196949,-0.219936,-0.133540,0.741548,0.161942,-0.134771,0.068452,0.086734,0.100154,0.213374,-0.265646,0.394906', '1302488', '4896894', '26276364', '26684564');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2129039', '飞屋环游记', '剧情', '小男孩卡尔（Carl Fredricksen）怀揣着对于冒险的热爱偶遇假小子艾丽（Ellie），而艾丽把整个屋子当成一艘大飞船游戏居然使他对这个女孩子有些着迷，相同的爱好最终使两个人成为了一生的爱侣。他们有一个梦想，那就是有朝一日要去南美洲的“仙境瀑布”探险，但直到艾丽去世，这个梦想也未能实现。终于有一天，曾经专卖气球的老人卡尔居然用五颜六色的气球拽着他的房子飞上了天空，他决定要去实现他们未曾实现的梦想。令卡尔始料不及的是，门廊居然搭上了一个自称是“荒野开拓者”的小男孩小罗（Russell），小罗的喋喋不休让卡尔对这个小胖墩格外讨厌。一老一少在飞行中经过了千难万险终于看到了传说中的“仙境瀑布”，在相处过程中卡尔发现小罗其实是个惹人怜爱的孩子。在步行穿越一座森林时，他们遇到了不会飞的大鸟凯文（Kevin）和一只会说话的狗狗逗逗（Dug），让老人惊讶的是他们还遇到了他少年的崇拜偶像——探险家查尔斯·蒙兹（Charles Muntz），而且他发现蒙兹居然是一个为达目的不择手段的坏人。这时，老人离自己的梦想之地只有一步之遥……本片荣获第82届奥斯卡最佳动画长片、最佳配乐2项大奖。', '爱德华·阿斯纳', '彼特·道格特', 9.1, 1240475, 'tt1049413', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363116942.jpg', 0.1, 0.3, 6.3, 32.8, 60.5, '0.101101,-0.004931,-0.777571,0.701870,-0.382988,-0.400364,0.853206,-0.034801,-0.457401,-0.121171,0.344488,0.934747,-0.366182,0.242811,0.195254,0.218493,0.020285,-0.548727,-0.240417,-0.231918,-0.371584,-0.344056,-0.356373,-0.097443,-0.166212,-0.168212,0.676518,-0.021511,-0.167024,0.230073,0.388834,-0.018446,0.060389,0.402994,-0.634038,-0.003639,0.155848,0.084022,0.045730,0.314084,-0.164527,0.031186,-0.156175,0.195227,-0.336901,0.229349,0.745835,-0.286329,-0.114662,0.020697,0.254796,-0.422913,-0.069838,-0.047358,0.251640,-0.281675,0.071592,-0.247315,-0.020707,-0.079060,0.163313,-0.255647,-0.676351,0.125573,-0.015541,0.113808,-0.573858,0.216188,0.034609,-0.230386,0.332494,-0.312146,0.185854,0.303274,0.338127,0.420113,-0.182388,0.079291,-0.717012,0.131826,0.585269,-0.053850,-0.344261,0.562198,-0.244040,-0.484413,-0.008418,-0.168256,-0.569299,-0.039083,0.388125,-0.111282,-0.319935,0.030077,-0.580706,0.170039,-0.311046,-0.233974,0.041227,-0.468925,-0.220509,-0.235961,0.122785,-0.355953,-0.278344,0.099197,-0.117139,-0.431579,0.758891,-0.742073,0.328688,0.855590,0.049618,-0.192936,0.952243,-0.021958,-0.053638,-0.182986,0.103137,0.278920,-0.085319,0.278165,0.046704,0.462616,-0.058717,-0.159126,-0.463691,0.551577', '3055049', '30162520', '26884422', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2129042', '微光城市', '剧情', '未来，由于人类遭受了重大的浩劫，为数不多的人们从地上转而进入地下生活。这座庞大的地下城市最初的设计仅能维持200年的运作，城市里面只有灯光作为唯一的照明工具。不过，随着时间的推移，200年很快就将到来，城市核心的设计寿命也即将到来。城市里停电的次数越来越多，眼见赖以生存的光芒即将消失在这微光城市里。作为好朋友的莉娜（西尔莎·罗南 Saoirse Ronan 饰）和杜恩（哈里·崔德威 Harry Treadaway 饰）两人经常在微光城市里错中复杂的管道中嬉戏。一天，莉娜发现了一份古老的文件，上面记载着如何走出微光城市。眼见微光城市的灯光即将熄灭，在这城市之外到底有什么秘密？是否是一片光明？莉娜和杜恩决定沿着这份古老文件的指引，走出城市，快去看看外面的世界，以此来拯救即将熄灭的城市。©豆瓣', '大卫·莱尔', '吉尔·克兰', 6.8, 25915, 'tt0970411', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1438850665.jpg', 0.9, 8.2, 49.1, 32.1, 9.6, '0.195147,0.473482,-0.761329,0.425862,0.110458,0.110573,0.688647,0.071046,-0.628897,-0.293080,0.145951,0.409120,-0.013306,0.177100,0.191036,0.071287,-0.816058,-0.532729,-0.243615,-0.598358,-0.562519,-0.551924,-0.727332,-0.095734,0.131376,-0.324276,0.620872,0.556371,0.061687,0.217124,-0.120474,-0.207474,-0.314636,0.257923,0.181092,-0.294564,0.111885,-0.038660,-0.248113,0.198911,-0.289549,-0.304569,-0.075403,-0.146837,0.163147,0.387399,0.680467,-0.375362,0.076480,-0.253558,0.265510,-0.031018,-0.148672,-0.149252,0.185347,0.082153,0.121323,0.210662,-0.429570,-0.104837,-0.229312,-0.405642,-0.555558,0.213456,0.306395,0.223244,-0.410470,0.443039,0.229227,-0.443988,0.182275,-0.498166,0.403637,0.282421,0.201197,0.580894,-0.313257,0.013509,-0.415644,-0.210953,0.396385,-0.026042,-0.219843,0.263043,-0.386426,-0.221944,-0.326243,0.255610,-0.273977,-0.224896,0.283729,0.266771,-0.089847,0.420101,-0.976669,0.425591,-0.194656,-0.489413,0.122342,-0.239941,-0.413944,-0.731393,0.024565,-0.188367,-0.075600,0.054462,-0.193976,-0.005925,0.730117,-0.666822,0.414562,0.173618,0.569539,0.122880,0.796554,-0.329781,0.394305,-0.098195,0.077513,0.330573,0.015636,0.592674,-0.310346,-0.036484,-0.205407,-0.189805,-0.422246,0.541409', '1309056', '1298405', '1297659', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2129132', '超凡蜘蛛侠', '动作', '童年的一起突发事件，令彼得·帕克（安德鲁·加菲尔德 Andrew Garfield 饰）和父母生离死别。转眼彼得成为一名高中生，他偶然发现父亲的公文包，并从叔父本（马丁·辛 Martin Sheen 饰）处得到线索，于是启程前往奥斯库公司拜访父亲当年的合作伙伴——科特·康纳斯博士（瑞斯·伊凡斯 Rhys Ifans 饰）。在公司内四处寻找线索的彼得意外被蜘蛛咬了一口，回程途中他的身体发生奇异的变化。在康纳斯博士德引导下，彼得不断了解并发掘体内着超乎寻常的能力，喜怒哀乐，各种意想不到的事情迅速向他袭来。直到某日，他便成了影响深远的超级战士蜘蛛侠。而城市内也出现了凶恶的蜥蜴人，彼得不平凡的人生就此展开……©豆瓣', '安德鲁·加菲尔德', '马克·韦布', 7.6, 312992, 'tt0948470', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1609913975.jpg', 0.5, 2.9, 30.6, 46.2, 19.8, '0.444090,0.082710,-0.697789,0.452597,0.150544,-0.382825,0.683203,0.129588,-0.630959,-0.432506,0.172872,0.648645,-0.194322,0.179708,0.254992,0.019709,-0.463588,-0.686552,0.051291,-0.288974,-0.383185,-0.486143,-0.278621,-0.364625,0.127881,-0.422487,0.295764,0.060450,-0.166070,0.629291,-0.010326,0.372258,-0.090200,0.654403,0.022734,0.167232,0.164921,0.030672,-0.224425,0.126334,0.284178,-0.187360,-0.065373,0.220831,-0.059585,0.338094,0.589679,-0.294406,-0.154808,-0.223624,0.291435,0.045150,0.319150,0.033848,0.395400,0.164255,-0.003530,0.223354,-0.107748,0.129870,0.101264,-0.123212,-0.503081,0.006146,-0.170564,0.434676,-0.418015,0.101621,-0.153313,0.003195,0.249100,-0.486546,-0.089996,0.316772,0.299057,0.034616,-0.159412,0.180322,-0.339481,0.061630,0.387327,-0.053006,-0.365689,0.224866,-0.261973,-0.446110,-0.088265,0.052860,-0.316591,0.025194,0.449751,0.379888,-0.054930,0.499926,-0.500548,-0.081533,-0.442772,-0.063322,-0.124843,-0.063783,-0.065527,-0.831346,-0.023589,-0.084712,-0.239410,-0.074720,-0.007088,-0.283080,0.326893,-0.543671,0.274486,0.664511,0.195399,-0.150669,0.468114,-0.425611,0.213779,-0.270488,-0.160881,0.424163,0.137967,0.404187,0.060291,0.163684,0.171612,-0.192104,-0.188395,0.529517', '3735015', '1465415', '1316693', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2129170', '鬼来电3', '恐怖', '毕业旅行本是很快乐的事，可明日香（堀北真希饰）却留在被其他同学遗忘的角落。她在学校被同学们欺凌，同伴Pam还因无法忍受欺凌而上吊自杀了。Pam的怨气积聚，让明日香为她报复。诅咒在进行，梓、健、瑞江等同学先后收到“自己”打来的电话留言，不久他们真的在电话所预言的时间死去！毕业旅行被浓重的恐怖气氛笼罩，大家惶惶不可终日。艾米莉（黑木メイサ饰）对同学们蹊跷死去背后的真相有所察觉，原来她的心中埋藏了一个巨大的秘密，为了阻止事件的扩大化，艾米莉打算亲手结束这一切。©豆瓣', '堀北真希', '麻生学', 6.3, 14864, 'tt0978797', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2612874453.jpg', 3.4, 14.3, 54.5, 20.5, 7.3, '0.130476,-0.142900,-0.704877,0.197056,-0.121881,-0.038052,0.740836,0.014662,-0.544531,-0.566501,-0.043112,0.464996,-0.480533,0.374802,0.093904,-0.131496,-0.332842,-0.576730,0.120313,-0.073854,-0.233370,-0.117338,0.206971,-0.348036,-0.024969,-0.298086,0.540201,0.305795,-0.190985,0.396953,0.046567,0.572442,-0.236937,0.593668,0.040226,0.113730,0.124488,-0.026771,-0.059697,0.012775,0.007442,-0.387121,-0.170741,0.369972,-0.047251,0.200481,0.721146,0.085873,-0.405405,-0.059895,0.243625,-0.755717,-0.053762,0.353015,0.273074,0.135266,0.209548,0.354835,-0.350934,0.111684,0.219213,-0.051358,-0.627056,-0.023005,-0.082427,0.197419,-0.189031,0.466831,-0.043010,0.050431,0.248969,-0.342307,0.099037,0.256960,0.024026,0.373924,-0.360776,0.070494,-0.410331,0.112198,0.972817,-0.464574,-0.028004,0.230299,-0.035999,-0.106796,0.074241,0.200824,-0.435010,0.121636,0.311993,0.153368,-0.198948,0.357959,-0.381223,-0.415457,-0.352896,-0.308815,-0.094039,-0.667302,-0.281534,-0.469368,-0.329024,0.075370,-0.562427,0.115799,0.134479,-0.096534,0.559000,-0.754024,0.444124,0.512287,0.192621,-0.559210,0.203916,0.266516,-0.020888,-0.099698,-0.069720,0.260646,0.052066,0.384653,0.240230,0.077324,0.030330,-0.048941,-0.590729,0.307195', '25721544', '1301022', '20443013', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2130121', '绑架', '惊悚', '3年前，话剧老师林晓阳（林嘉欣饰）的弟弟被绑架，案件交由高级督察何宛真（刘若英饰）及智叔（张兆辉饰）负责，可是在追捕的过程中，疑犯因争吵坠楼身亡，林晓阳就此埋下了怨恨。三年后，林晓阳患病的丈夫（赵会南饰）病情加重，需要一千万才能有治好的希望，林晓阳动了绑架富豪王森（郭 涛饰）儿子的念头。多日来林晓阳跟她从尼泊尔认识的同伙跟踪小孩动向，后来决定在一个傍晚下手。刚好案子也是有何宛真接手，就让林晓阳有了报复的心理，何宛真为了救回孩子只好服从，可她万万没有想到，原来王森的儿子，跟自己的儿子调换了衣服穿，被林晓阳绑架的正是何宛真的儿子。两个女人，都为着心爱的亲人在绑架案中斗志斗勇，展开激烈的较量。©豆瓣', '林嘉欣', '罗志良', 6.6, 17164, 'tt1045818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2675406456.jpg', 1.3, 9.1, 55.2, 28.7, 5.7, '-0.075671,-0.299662,-0.559898,0.260868,-0.465350,-0.410343,0.441551,0.052637,-0.582691,-0.456624,0.362000,0.435449,-0.066855,0.148804,0.166390,-0.178714,-0.048428,-0.701392,-0.063586,-0.010050,-0.346669,-0.589166,-0.036479,-0.220167,0.258461,-0.423046,0.437089,0.062570,-0.189386,0.302306,0.509815,0.283217,-0.192818,0.398921,-0.096580,0.091562,0.146850,0.220923,-0.312745,0.203453,0.122540,-0.255045,0.134131,0.113939,-0.033115,0.480105,0.641265,-0.127778,-0.234115,-0.121148,0.310926,-0.241158,-0.053196,-0.005514,0.475890,-0.046046,0.255355,0.270507,-0.412508,-0.113826,0.290153,0.042867,-0.603886,0.127710,0.149822,-0.057257,-0.611330,0.360950,-0.158171,0.011953,0.220138,-0.149297,0.378458,0.446410,0.151020,0.510113,-0.189885,-0.049193,-0.443503,0.263020,0.598167,-0.248080,0.338328,0.283525,-0.023522,-0.295452,0.165306,-0.244206,-0.245622,0.163607,0.321102,-0.141790,-0.418064,0.147248,-0.141774,-0.162678,-0.172149,0.156630,0.172794,-0.332888,0.073414,0.003755,0.027839,0.026570,-0.171985,0.102344,0.043303,-0.446580,0.448531,-0.674712,0.267431,0.587221,0.299472,-0.947254,0.398302,0.375648,0.088954,-0.184092,-0.057597,-0.067586,0.165719,0.064729,0.269449,0.048939,-0.081944,-0.354081,-0.216078,0.144646', '35073886', '1302110', '1421278', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2130163', '别惹佐汉', '剧情', '佐汉·德沃（亚当·桑德勒 Adam Sandler 饰）是一名供职于以色列情报机关摩萨德的特工人员，他身手矫健，力大无穷，而且天赋异秉。闲暇时沟女享乐，优哉游哉；接到任务时，便披挂上阵与来自巴勒斯坦的恐怖分子展开惊险刺激的对决。他干掉的对手不计其数，俨然一个新时代的救世主。但是谁都想不到，这个阳刚味儿十足的爷们儿心中竟然有着当美发师的梦想。他早已厌倦了打打杀杀的生活，渴望为了自己的理想而努力。某天，机会终于降临。佐汉假装在执行任务时死亡，从而逃离以色列，来到繁华时尚的美国。在这个完全陌生的国度，佐汉闹出了不少的笑话。但是，只要心中有梦，他便无所畏惧，勇往直前……©豆瓣', '亚当·桑德勒', '丹尼斯·杜根', 6.3, 28144, 'tt0960144', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1467745372.jpg', 4.3, 15.7, 48.3, 23.3, 8.5, '0.111560,0.179714,-0.739672,0.639983,-0.221619,-0.316378,0.501977,-0.165873,-0.465273,-0.493197,0.198368,0.749197,0.141898,0.113267,0.362832,-0.104250,-0.211177,-0.681143,-0.144469,-0.053123,-0.258842,-0.105569,-0.479445,-0.372071,0.017764,-0.213998,0.801640,0.175888,-0.187798,0.271212,0.304528,0.281111,-0.093785,0.428930,-0.501153,-0.257454,0.244475,0.026199,-0.332263,0.198936,-0.136911,-0.016383,-0.281173,0.206946,-0.172537,0.074485,0.556737,-0.337247,-0.400262,-0.114454,0.478791,-0.337702,-0.124842,0.225730,-0.027788,-0.012465,0.091300,0.011440,0.154689,0.065148,-0.022146,-0.258014,-1.060316,-0.061563,-0.079634,0.023928,-0.175223,0.334543,-0.135281,-0.045595,-0.041700,-0.267169,0.198851,0.332759,0.276608,0.277682,-0.222514,0.248239,-0.487462,-0.023307,0.566017,0.130395,-0.385271,0.287025,-0.189928,-0.534584,0.021171,-0.354880,-0.324914,-0.157200,0.100901,0.079600,-0.231029,0.203566,-0.687414,0.151425,-0.203643,0.084218,-0.100434,-0.293103,-0.302739,-0.511446,-0.140023,-0.247768,-0.367039,0.360644,0.187366,-0.161512,0.852591,-0.989458,0.260596,0.630217,-0.113539,-0.580998,0.505748,0.106532,-0.036145,-0.265675,-0.177924,0.497345,0.039949,0.361477,-0.169519,0.274702,-0.228318,-0.375276,-0.160602,0.654324', '1793491', '27602116', '24284209', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2130529', '拳皇', '动作', '美国波士顿，能够进入异次元解封八歧大蛇的三神器八尺琼勾玉、八咫镜和草稚剑正在展出，中情局特工不知火舞（李美琪 饰）正从八神家族传人八神庵（李威尹 饰）处打探三神器的秘密，岂料卢卡尔杀入展馆将三神器抢走并躲入了异次元。神乐家族传人千鹤（叶芳华 饰）透露被抢走的草雉剑为假，委托不知火舞向草稚家族求助。卢卡尔抢走神器后诱骗KOF大赛的格斗家们进入异次元，意欲成为拳皇。同时不知火舞和八神庵为阻止卢卡尔的计划，请求草稚家族传人草稚京一同出战。中情局为了调查这起异次元中的犯罪行为亦派出探员特瑞与不知火舞等人一起进入异次元……本片根据同名经典游戏改编。©豆瓣', '李美琪', '陈嘉上', 3.1, 8835, 'tt1038685', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1654612832.jpg', 62.6, 24.4, 9.7, 1.6, 1.7, '-0.218052,0.217530,-0.236321,0.530908,0.077595,-0.083570,0.177447,-0.227808,-0.289079,-0.666663,0.038276,0.668325,0.006071,0.095019,0.404546,0.184746,-0.180383,-0.541330,-0.216908,-0.102165,-0.383212,-0.378979,0.041625,-0.111454,0.061678,-0.201478,0.651506,-0.029113,-0.565615,0.074725,0.322782,0.714504,-0.664495,0.003248,-0.066575,-0.176778,0.125530,-0.060304,-0.472038,0.714310,-0.346525,-0.114450,0.005520,0.368130,0.158593,0.156275,0.409962,-0.474877,0.625875,-0.417156,0.102215,0.096747,-0.395710,-0.123880,0.388480,0.144283,0.104439,0.235323,-0.070442,0.233125,0.191279,-0.200264,-0.740370,0.129892,0.295115,-0.154659,-0.229977,-0.081200,-0.357572,0.336680,0.336842,-0.022504,0.302772,0.276874,0.386157,-0.347841,-0.121234,0.062423,-0.327827,0.053167,0.072170,-0.410246,0.136319,-0.367522,0.342748,-0.388886,-0.408925,-0.182680,0.214368,-0.105278,0.641615,0.471550,0.515527,0.497484,-0.471773,-0.584776,-0.277406,-0.069909,0.217176,-0.086240,0.085257,-0.908625,0.215176,0.236250,0.022892,0.057411,0.223220,-0.374527,0.340889,-0.488629,0.253383,0.207085,0.201783,-0.423476,0.515074,-0.157328,0.185455,-0.636624,-0.380244,0.323170,0.627200,0.289229,0.082705,0.259995,0.156718,-0.349732,-0.219758,0.057784', '2369613', '4014397', '6517421', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2130545', '当尼采哭泣', '剧情', '本片改编自心理治疗畅销作家欧文‧亚隆的同名小说。十九世纪末的维也纳，正逢四十不惑的医学大师布雷尔，突然接到一封意外的来信。寄信人竟然是社会名媛路·莎乐美（凯瑟琳·温妮克 Katheryn Winnick 饰）。虽然突然布雷尔犹豫过，但还是如约前往咖啡馆。莎乐美此番的目的是希望布雷尔能帮助她的亲密朋友——存在主义大师尼采，有一种刻苦铭心的“痛苦感”每天伴随着他。为了医治根本不愿接受治疗的尼采，布雷尔唯有假意装成需要尼采的帮助。整整一个月，布雷尔和尼采在不同的场所进行着深入的交谈。于是，一场一场不知谁是病人，谁是医生的心理治疗就此展开……©豆瓣', '贾米·埃曼', 'Pinchas Perry', 7.6, 8648, 'tt0760188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1072767865.jpg', 1.1, 5.1, 29.8, 43, 21, '0.333526,-0.096028,-0.321608,0.477693,0.425720,-0.126842,0.390106,-0.128094,-0.630669,-0.537413,0.276532,0.693966,-0.026669,0.289027,0.353699,0.121805,-0.685484,-0.314096,0.165855,-0.202190,-0.137734,-0.672374,-0.337689,-0.171091,0.133338,-0.497898,0.269097,-0.042779,-0.189499,0.548667,0.236397,0.352997,0.061272,0.455591,0.306287,-0.008686,0.268531,-0.137599,-0.575730,0.074183,0.403909,-0.121745,-0.329971,0.021998,0.253385,0.420189,0.214772,-0.360788,0.139116,0.221432,0.331868,-0.101945,0.289594,0.164234,-0.226361,-0.117585,0.409396,0.349296,-0.078547,0.198226,-0.047128,-0.259311,-0.525643,0.064415,0.201025,0.409510,-0.162780,0.441612,-0.475374,-0.135271,-0.186835,-0.460894,-0.231375,0.418080,0.142701,0.597611,-0.011270,-0.192295,-0.454294,0.012805,0.469532,0.080978,-0.480893,0.278572,-0.215115,-0.583641,0.014345,-0.302748,-0.490849,0.029884,0.279531,-0.048889,-0.151703,0.234314,-0.396131,-0.217249,-0.201721,-0.136843,0.220176,0.044954,-0.008983,-0.531308,0.392216,-0.211068,-0.090986,-0.110547,0.172229,-0.434876,0.679387,-0.874613,0.243826,0.472593,0.232210,-0.209251,0.691895,0.071452,-0.127466,-0.058529,0.078251,0.529262,0.005338,0.159101,0.355471,0.400403,0.460655,-0.001910,-0.103532,0.300833', '1292720', '1301172', '22964524', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131291', '纳尼亚传奇3：黎明踏浪号', '剧情', '暑假到了，长大的苏珊和彼得与父母生活在美国，露西（乔基•亨莉 Georgie Henley 饰）和埃德蒙（斯堪德•凯恩斯 Skandar Keynes 饰）则借住到了姨妈家。这让他俩很不情愿，因为那里有个总惹人厌的表弟尤斯塔斯（威尔•保尔特 Will Poulter 饰 ）。有一天，一幅描绘海上行船的油画活了起来，水面不断外溢，露西、埃德曼和小表弟就这样被卷入了纳尼亚世界的汪洋中。好在三人被大船上的凯斯宾王子（本•巴恩斯 Ben Barnes 饰）救起，原来他正在寻找王国旧臣的路上，四人于是共同展开了新的冒险。本片是《纳尼亚传奇》系列电影的第三集，改编自同名小说的第四部《黎明踏浪号》。©豆瓣', '本·巴恩斯', '迈克尔·艾普特', 6.8, 71751, 'tt0980970', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p743270605.jpg', 1.2, 8.7, 49.2, 29.1, 11.8, '0.297195,-0.161425,-0.701990,0.613442,0.323595,-0.358335,0.786766,0.208402,-0.311699,-0.085232,-0.009638,0.958438,-0.206471,0.164637,0.560438,0.342837,-0.649257,-0.508559,-0.011953,-0.123683,-0.223225,-0.418990,-0.409586,-0.093898,-0.082926,-0.304657,0.418820,0.040146,0.026789,0.501629,0.233979,0.352088,-0.177145,0.309906,-0.185702,0.339714,0.213000,-0.036138,0.064240,0.165944,0.107358,-0.035257,-0.193719,0.109305,0.299609,0.150493,0.707758,-0.401151,0.136526,-0.038197,0.209993,-0.249755,0.077180,-0.110402,0.202067,-0.294313,0.179691,0.103850,-0.087611,0.062903,0.091943,-0.135508,-0.496440,0.123739,0.101091,0.188399,-0.653043,0.277161,-0.089695,-0.221362,0.179378,-0.318021,0.158800,0.504519,0.199712,0.252096,-0.124050,-0.151860,-0.692700,0.374038,0.380317,0.311211,-0.249897,0.247575,-0.053343,-0.232754,-0.159346,-0.080066,-0.545498,-0.292178,0.563221,-0.178227,-0.100151,0.282013,-0.849093,0.070097,-0.173174,-0.328665,-0.046806,-0.251852,-0.088332,-0.661476,-0.097580,-0.482974,-0.107283,-0.029835,-0.008050,-0.215396,0.591621,-0.581364,0.404565,0.514728,0.062087,-0.119068,0.697300,0.213155,0.148246,-0.060742,0.088547,0.179152,0.010873,0.341282,0.352693,0.507686,0.107271,-0.088476,-0.519240,0.625773', '35161768', '1302133', '3055049', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131399', '美国女孩的秘密', '剧情', '1934年，经济大萧条越来越严重，10岁的女孩Kit（阿比吉尔·布莱斯林 Abigail Breslin 饰）的家庭也遭到连累，父亲前往芝加哥寻找工作，为了维持生计，母亲把房子的空余房间出租，各色各样的住客搬了进来。包括流动图书馆的馆长Miss Bond、健美操小姐Miss Dooley、魔术师、还有Kit的同学Stirling以及他母亲，无业游民Will和弟弟Countee在此打工，做些修补工作以换取食物。Kit的志愿是当一名伟大的新闻记者，当她了解新闻是需要新鲜的题材，便随时挖掘新鲜事件。当地一直发生游民抢劫的恶性案件，这次轮到Kit的好友Ruthie家被抢，继而是Kit家的保险箱而被偷走了，所有的矛头都指向了Will，只有Kit相信他是无辜的。一个偶然的机会下，Kit和她的小伙伴们发现了真凶，并且打算用计谋擒住对方。他们能在感恩节到来之前让生活回复正常吗？经济大萧条让人们的生活变得艰辛，却又使他们更坚强。', '阿比盖尔·布雷斯林', '帕特丽夏·罗兹玛', 7.9, 8460, 'tt0846308', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2230460761.jpg', 0.1, 1.4, 24.3, 52.7, 21.6, '0.223986,-0.114241,-0.334484,0.201725,-0.231227,-0.247685,0.607283,0.045666,-0.383362,-0.313372,0.036063,0.582962,0.051894,0.297465,0.079926,-0.104023,-0.228724,-0.645016,-0.179481,-0.102721,-0.311699,-0.408867,-0.189410,-0.382004,-0.036004,-0.314011,0.321827,0.120425,-0.175621,0.241134,0.141631,0.111410,0.055960,0.420110,-0.281216,-0.060027,-0.074052,0.036007,-0.197326,0.116588,0.030247,-0.370537,-0.136281,0.123843,0.372754,0.438359,0.658313,0.074067,-0.329608,-0.071582,0.373683,-0.178652,-0.016847,0.113043,0.224290,-0.000139,0.192277,0.156874,-0.248255,-0.000055,0.128449,-0.303106,-0.828536,-0.001613,0.207725,-0.011051,-0.590842,0.247936,0.016810,-0.133480,0.092985,-0.381599,0.450996,0.524665,0.159803,0.441610,-0.027651,-0.014857,-0.508043,0.244571,0.718371,-0.233350,-0.120387,0.182859,-0.456659,-0.306680,0.187134,-0.336386,-0.460889,0.121978,0.273696,-0.032245,-0.159455,0.210999,-0.547902,0.002921,-0.179414,-0.425636,0.227169,-0.443732,-0.133916,-0.609058,0.008234,-0.261432,-0.096897,0.173094,0.141938,-0.337949,0.836638,-0.731494,0.184249,0.576787,0.494976,-0.725521,0.681075,-0.119807,0.123870,-0.061043,-0.176780,-0.075670,0.110703,0.529986,0.127371,0.129192,-0.007499,-0.262148,-0.327769,0.256970', '1877596', '26678784', '4301278', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131459', '机器人总动员', '科幻', '公元2805年，人类文明高度发展，却因污染和生活垃圾大量增加使得地球不再适于人类居住。地球人被迫乘坐飞船离开故乡，进行一次漫长无边的宇宙之旅。临行前他们委托Buynlarge的公司对地球垃圾进行清理，该公司开发了名为WALL·E（Waste Allocation Load Lifters – Earth 地球废品分装员）的机器人担当此重任。这些机器人按照程序日复一日、年复一年辛勤工作，但随着时间的流逝和恶劣环境的侵蚀，WALL·E们接连损坏、停止运动。最后只有一个仍在进行这项似乎永无止境的工作。经历了漫长的岁月，它开始拥有了自己的意识。它喜欢将收集来的宝贝小心翼翼藏起，喜欢收工后看看几百年前的歌舞片，此外还有一只蟑螂朋友作伴。直到有一天，一艘来自宇宙的飞船打破了它一成不变的生活……本片荣获2009年第81届奥斯卡最佳动画长片奖。©豆瓣', '本·贝尔特', '安德鲁·斯坦顿', 9.3, 1238503, 'tt0910970', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1461851991.jpg', 0.1, 0.2, 3.9, 24, 71.8, '-0.284335,0.339341,-0.522752,0.475441,0.010055,0.071427,0.565627,-0.210479,-0.417968,-0.185198,-0.006039,0.503354,-0.040923,0.020742,0.093178,-0.152692,-0.409326,-0.367400,-0.123931,-0.147211,-0.444915,-0.257622,-0.194744,-0.227761,-0.045100,-0.439951,0.895679,0.097068,0.026584,0.283596,-0.285939,0.051424,-0.085974,0.313781,-0.233075,-0.170248,0.097636,0.135679,-0.363295,0.230190,-0.128327,-0.012999,0.147366,-0.297790,0.185263,0.027457,0.837231,-0.179079,-0.395108,-0.400393,0.596039,-0.145922,-0.236871,-0.298146,0.539773,0.368487,-0.147620,0.237823,-0.090873,0.205750,-0.115489,-0.305777,-0.766460,-0.341074,-0.153375,-0.201843,-0.424462,0.342897,0.129143,0.140166,-0.242825,-0.310236,0.253649,0.650787,0.546841,0.441381,-0.049317,0.061591,-0.232824,0.495427,0.586895,-0.275226,-0.643541,0.677903,-0.155221,-0.430184,-0.181349,-0.400833,-0.358037,-0.151001,-0.096066,0.411160,-0.345927,0.402565,-0.838806,0.406831,-0.060323,-0.762658,0.335960,-0.360789,-0.304001,-0.740870,0.068512,-0.329896,-0.021915,0.064984,0.050700,-0.401342,0.800065,-0.438885,0.505061,0.720112,0.288675,-0.436379,0.616524,-0.147018,0.192249,-0.288931,0.246535,0.431731,-0.202963,0.654731,0.091654,0.131732,0.011913,0.193214,-0.425019,0.418826', '26759820', '26290398', '1292444', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131640', '亲爱的朋友', '剧情', '虽然与父亲关系疏离，但毕竟母亲溺爱，家境富裕，又长得漂亮艳丽，利娜（北川景子 饰）本来有着令人羡慕的身世。然而在利娜眼中，所有人都是不可信任，友谊只是一种利用关系。傲慢冷漠的她夜夜流连在声色场上，与他人喧嚣而孤独的狂欢。在人群中突然倒下的利娜，在病床上醒来，耳边传来了噩耗。她患病，必须做手术，切除左胸。作为一个曾经那么骄傲的女生，利娜的生活滑入深渊。就连说过绵绵情话的男人，如今也转身而去。小学同学真纪的出现，让这两个女孩的生命有了交集，利娜心中的“朋友”的定义，也从这一刻起开始改变。©豆瓣', '北川景子', '两泽和幸', 7.3, 24862, 'tt1039780', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p655326474.jpg', 0.9, 5, 38.6, 41.1, 14.4, '0.301443,0.021433,-0.777177,0.596857,-0.208214,-0.281381,1.283944,0.376707,-0.459602,-0.115008,0.098387,0.655374,-0.010223,0.421090,0.211251,0.239524,-0.086185,-0.785358,-0.033140,-0.265161,-0.152300,-0.460150,-0.042161,-0.251060,-0.074405,-0.442556,0.735439,-0.032784,-0.266563,0.750268,0.310527,0.049198,-0.059275,0.676776,-0.389259,-0.200438,-0.104197,0.345702,-0.291020,0.017595,-0.001689,-0.083498,-0.223934,0.227990,-0.151130,0.469309,0.443902,-0.120879,-0.223518,0.201212,0.348278,-0.061057,0.030405,0.250140,0.238119,-0.086444,0.420532,0.212634,-0.161813,-0.059149,-0.030343,0.152771,-0.537424,0.103680,0.055022,0.272116,-0.506727,0.687718,0.044404,-0.301135,0.204247,-0.244612,0.303928,-0.033620,0.080221,0.556639,-0.315683,0.225213,-0.393176,-0.151998,0.688894,0.057921,-0.403259,0.547458,-0.372223,-0.501911,-0.167690,-0.087759,-0.542100,-0.026630,-0.088048,0.115877,-0.192409,0.487248,-0.528860,0.346451,0.048855,0.089344,-0.051617,-0.517179,-0.194826,-0.183155,-0.465469,-0.587931,-0.680820,0.207647,0.064301,-0.273853,0.818053,-0.984198,0.095458,0.428867,0.368722,-0.334629,0.594092,0.444934,0.106291,-0.099570,-0.092583,0.648092,0.024285,0.021987,-0.020859,0.284179,-0.214928,0.351464,-0.421499,0.602071', '25911595', '4275444', '1292211', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131649', '绿区', '剧情', '2003年，伊拉克战争爆发。萨达姆政府受到重创，大规模杀伤性武器（WMD）成为美国出兵伊拉克的有力借口。罗伊·米勒（马特·戴蒙 Matt Damon 饰）所率领的小分队奉命在伊拉克境内寻找WMD，然而无数次的搜寻皆无所获，这令米勒对线报的来源心生疑惑。某次行动中，他遇到当地的独腿男子法哈迪，从对方口中米勒得知一众伊拉克关键人物正在某地集会，行动中意外发现扑克牌通缉令上的艾尔·拉威（Yigal Naor 饰）也在其中，而艾尔·拉威似乎和美国政府有着错综复杂的关系。米勒不顾劝阻展开独立调查，发现所谓的WMD不过是包藏了无数丑恶真相的谎言而已……本片根据《华盛顿邮报》驻巴格达记者拉吉夫·产德拉斯卡兰（Rajiv Chandrasekaran）的作品《翡翠城的帝王生活：伊拉克绿色地带深处》改编。©豆瓣', '马特·达蒙', '保罗·格林格拉斯', 7.3, 30260, 'tt0947810', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p511516956.jpg', 0.4, 3.1, 39.1, 46.2, 11.2, '0.276438,-0.039370,-0.750828,0.551085,0.364762,0.113524,0.341286,-0.233514,-0.440064,-0.363732,0.069495,0.498442,-0.209447,-0.193792,0.162311,-0.066829,-0.474552,-0.616434,-0.062193,-0.164701,-0.116266,-0.516395,-0.375056,-0.502677,-0.175751,-0.292123,0.609354,0.279006,-0.509285,0.337605,0.173847,0.743259,-0.233501,0.424122,0.199840,-0.271722,0.241113,-0.260884,-0.360268,0.241778,-0.188873,-0.282543,-0.253291,0.398510,0.063072,0.708269,0.527508,-0.404580,0.176611,-0.248467,0.277840,-0.207915,0.147611,0.022444,0.354593,0.327588,0.011157,0.208216,-0.184772,0.085962,0.061802,-0.199090,-0.446902,-0.173102,0.199577,0.302135,-0.276411,0.116378,-0.237234,0.039525,0.048016,-0.070829,0.268775,0.458207,0.324119,0.034682,0.018124,-0.001142,-0.508364,-0.011090,0.470027,-0.124351,-0.338435,-0.068412,-0.185846,-0.569064,0.090973,-0.187615,-0.037853,-0.072804,0.210213,0.062434,0.057008,0.452656,-0.507369,-0.107783,-0.438105,-0.282162,-0.098646,0.003923,-0.120454,-0.968721,-0.266327,-0.234661,-0.217958,0.159042,0.067382,0.033825,0.460934,-0.625754,0.214334,0.341199,0.225698,-0.271472,0.319250,-0.031372,0.124108,-0.426143,-0.282579,0.488187,0.235174,-0.009082,-0.068944,-0.096470,0.062100,-0.395624,-0.008426,0.230893', '2369613', '3871833', '25723905', '2973528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131654', '诸神之战', '动作', '不堪忍受奥林匹斯众神残暴压迫的阿戈斯国王亚克里斯（Jason Flemyng 饰）奋起反抗，对至高无上的神明大为不敬。在冥王哈迪斯（拉尔夫·费因斯 Ralph Fiennes 饰）的怂恿下，天神宙斯（连姆·尼森 Liam Neeson 饰）决定对愚蠢的人类施以惩罚。遭遇海难流落到阿戈斯的青年珀修斯（萨姆·沃辛顿 Sam Worthington 饰）是宙斯和亚克里斯的皇后生下的半神，他亲眼目睹哈迪斯所施下的恐怖神迹，并得知哈迪斯将释放北海怪兽克拉肯惩戒世人，除非亚克里斯将美丽的公主安德鲁美达（艾莉克莎·黛沃洛斯 Alexa Davalos 饰）作为牺牲献给众神。在女神爱娥（Gemma Arterton 饰）的点拨下，珀修斯知晓了自己的身世与使命，于是决定启程杀死北海怪兽并摧毁哈迪斯的阴谋……本片根据希腊神话传说改编，也是20世纪80年代同名影片翻拍版本。', '萨姆·沃辛顿', '路易斯·莱特里尔', 6.2, 110306, 'tt0800320', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p443378368.jpg', 2.5, 15.6, 56.4, 20.3, 5.2, '0.080071,0.375747,-0.365045,0.680926,0.250523,0.067548,0.565806,0.015267,-0.092001,-0.305891,0.624992,0.764593,-0.278142,-0.304314,0.425837,0.188044,-0.527862,-0.269510,-0.134950,-0.011667,-0.116553,-0.614693,-0.416999,-0.229414,-0.040456,-0.712893,0.622336,0.037944,-0.303115,0.023940,0.375661,0.523581,0.022870,0.107261,-0.073588,0.099410,-0.313002,-0.061499,-0.393453,0.324255,-0.171046,-0.127425,-0.134154,0.463471,-0.096224,0.124997,0.321516,-1.005951,0.232664,-0.371317,0.319683,-0.283835,0.044381,0.187822,0.154810,-0.422736,-0.208103,0.481226,0.160621,0.066203,0.272809,0.028002,-0.727713,-0.107977,0.013475,-0.069992,-0.450741,0.284813,-0.079606,0.290083,0.201161,-0.178821,0.117427,0.037838,0.189303,0.421532,0.137860,-0.010639,-0.308405,0.110233,0.398946,-0.139246,-0.218498,-0.133823,-0.318521,-0.583090,-0.416246,-0.484545,-0.457116,-0.064675,0.254451,0.216585,0.193832,0.671840,-0.403958,-0.575991,-0.743548,-0.175849,0.044936,-0.396248,0.042048,-0.454974,-0.244964,-0.139748,-0.236808,-0.090383,0.275529,-0.226065,0.459207,-0.662335,0.540083,0.574841,0.330714,-0.397699,0.521563,0.271391,-0.181048,-0.416992,-0.251007,0.698546,0.266642,0.065316,-0.046450,-0.039221,0.088997,0.041581,-0.167633,0.441462', '3157583', '3285073', '24859795', '6390825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131664', '真人快打', '动作', '科尔（刘易斯·陈 Lewis Tan 饰）是一名身手非常矫健，但生活十分落魄的拳手，某日，他莫名其妙的遭到了冷冻术士绝对零度（乔·塔斯利姆 Joe Taslim 饰）的追杀。在特种部队少校贾克斯（麦卡德·布鲁克斯 Mehcad Brooks 饰）的帮助之下，科尔死里逃生，并且启程开始寻找一位叫做索尼娅（杰西卡·麦克娜美 Jessica McNamee 饰）的女子。之后，科尔来到了地球阳间守护者雷电（浅野忠信 饰）的神庙之中，在这里，他遇见了战士刘康（林路迪 饰）和佣兵卡诺（约什·劳森 Josh Lawson 饰）等人，他们唯一的共同点就是身上都有着神秘的龙形标志。一行人即将在这里接受非常严酷的训练，以对抗来自异星敌人的侵略，保护宇宙的和平。©豆瓣', '刘易斯·陈', '西蒙·麦奎德', 5.2, 23793, 'tt0293429', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2639148697.jpg', 10.1, 35.3, 40.9, 9.8, 3.9, '0.206694,-0.258931,-0.478505,0.689158,-0.092619,-0.144281,0.687468,0.225440,-0.636815,-0.431110,0.421679,0.626685,-0.072039,0.068928,0.582444,0.099828,-0.296848,-0.295164,0.000838,-0.103514,-0.572232,-0.418486,-0.415916,-0.302575,-0.058595,-0.512400,0.484455,0.088505,-0.048261,0.470194,0.124591,0.645290,0.017956,0.524479,-0.061179,-0.174622,0.263035,-0.311014,-0.078330,0.227506,-0.124624,-0.069919,-0.015895,0.213171,0.001150,0.237043,0.480638,-0.458651,0.404640,-0.271384,-0.008429,-0.256275,0.042874,0.093930,0.304448,-0.396970,0.048010,-0.044977,0.086275,0.031424,0.071255,-0.112297,-0.659286,0.120384,0.164012,0.123232,-0.482502,0.251379,-0.160627,0.050242,0.091257,-0.298003,0.207926,0.249148,0.357785,0.173727,0.141740,-0.084985,-0.566080,-0.013143,0.388163,0.011844,-0.362743,-0.175098,-0.380713,-0.686933,-0.176948,-0.105535,-0.456514,-0.118676,0.293000,0.087036,0.218295,0.114501,-0.810377,0.114014,-0.331897,-0.078418,-0.211332,-0.365033,-0.120355,-0.798564,-0.036801,-0.357712,-0.268652,0.267180,-0.128449,-0.046983,0.673768,-0.824986,0.268126,0.337318,0.270576,-0.131871,0.502636,-0.001528,0.226961,-0.291197,-0.180913,0.504549,0.363640,0.228686,0.050537,0.507188,-0.069208,0.054636,-0.019216,0.648928', '1420088', '1309056', '1793491', '11810348');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131669', '泰山归来：险战丛林', '动作', '故事发生在十九世纪八十年代，自小生长在丛林之中的泰山（亚历山大·斯卡斯加德 Alexander Skarsgård 饰）早已经离开了刚果，回归了人类社会。他同心爱的珍（玛歌特·罗比 Margot Robbie 饰）结婚成家，在英国伦敦过着幸福美满的生活。某日，被委任为商务密使的泰山回到了他的老家——刚果丛林，然而，此时的他并不知道，自己在一开始，就落入了邪恶而又狡猾的比利时军官罗姆（克里斯托弗·瓦尔兹 Christoph Waltz 饰）一手策划的阴谋之中。如此一来，不仅仅是泰山，就连珍和他的朋友们亦身处危险之中，泰山能否找回曾经矫健的身手和肆意的野性，将企图伤害他至爱之人的敌人们消灭殆尽呢？©豆瓣', '亚历山大·斯卡斯加德', '大卫·叶茨', 6.1, 42102, 'tt0918940', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2367559705.jpg', 3.7, 18, 52.4, 19.6, 6.3, '0.425614,0.110647,-0.949276,0.478137,-0.234263,-0.136913,0.679324,0.089009,-0.478006,-0.134428,0.220730,0.844523,-0.023383,0.242287,0.173203,0.160400,-0.169508,-0.862029,-0.198046,-0.194972,-0.159075,-0.320121,-0.495800,-0.077986,0.048451,-0.496054,0.529410,0.202232,-0.107468,0.408717,0.075935,0.443760,-0.143722,0.495515,-0.371540,0.106583,0.058814,-0.117068,-0.283847,0.108430,-0.089539,-0.401939,-0.104115,0.203091,-0.017688,0.240288,0.770759,-0.443773,0.014867,-0.244003,0.240161,-0.201037,0.098862,0.323303,0.342201,-0.114735,-0.041875,0.454487,-0.227096,0.298719,-0.011599,-0.226787,-0.710904,0.024556,-0.030618,0.180549,-0.786150,0.396211,-0.061874,-0.163257,-0.028946,-0.398952,0.355369,0.393015,0.000947,0.371828,-0.051311,-0.053716,-0.610110,0.207079,0.813847,-0.091796,-0.243776,0.135119,-0.012893,-0.342548,-0.123796,-0.176248,-0.479829,-0.243528,0.444472,-0.055230,-0.326678,0.469013,-0.572296,-0.006475,-0.348771,-0.171240,-0.234011,-0.179939,-0.284739,-0.320819,-0.256687,-0.439937,-0.232981,0.214869,0.018765,-0.060775,0.758516,-0.881555,0.372001,0.569362,0.439794,-0.339753,0.531216,-0.031430,0.129274,-0.028938,0.009469,0.523897,0.072984,0.225435,0.135589,0.379467,-0.176921,-0.239946,-0.375375,0.661035', '1301022', '21360412', '1870682', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21318488', '消失的爱人', '剧情', '结婚五周年纪念日的早上，尼克·邓恩（本·阿弗莱克 Ben Affleck 饰）来到妹妹玛戈（凯莉·库恩 Carrie Coon 饰）的酒吧，咒骂抱怨那个曾经彼此恩爱缠绵的妻子艾米（罗莎蒙德·派克 Rosamund Pike 饰）以及全然看不见希望的婚姻。当他返回家中时， 却发现客厅留下了暴行的痕迹，而妻子竟不见了踪影。女探员朗达·邦妮（金·迪肯斯 Kim Dickens 饰）接到报案后赶来调查，而现场留下的种种蛛丝马迹似乎昭示着这并非是一件寻常的失踪案，其背后或许隐藏着裂变于夫妻之情的谋杀罪行。艾米的失踪通过媒体大肆渲染和妄加揣测很快闻名全国，品行不端的尼克被推上风口浪尖，至今不见踪影的爱人对他进行无情审判，你侬我侬的甜言蜜语早已化作以血洗血的复仇与折磨……本片根据吉莉安·弗琳（Gillian Flynn）的同名小说改编。©豆瓣', '本·阿弗莱克', '大卫·芬奇', 8.7, 866548, 'tt2267998', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2221768894.jpg', 0.2, 0.6, 8.7, 42.7, 47.8, '0.399540,0.034705,-0.689113,0.443887,0.206941,-0.357575,0.696808,0.186009,-0.283835,-0.325247,-0.016509,0.329658,-0.310283,0.085606,0.235873,-0.040407,-0.558661,-0.762287,-0.012607,-0.265936,-0.066311,-0.554209,-0.158129,0.041898,-0.029055,-0.340868,0.280250,0.027577,-0.193207,0.528478,0.409797,0.372021,-0.269672,0.322985,0.066544,0.253914,0.219577,0.185465,-0.425676,0.044130,0.069401,-0.028825,0.017058,0.066383,-0.291034,0.556155,0.550008,-0.420531,-0.044018,-0.222475,0.511312,-0.198749,0.252929,0.174345,0.210947,0.047610,0.152578,0.301230,-0.283909,-0.240232,0.139522,0.166119,-0.572155,-0.035734,0.092438,0.231653,-0.255816,0.251832,-0.302129,0.144785,0.149443,-0.220999,0.293683,0.264428,-0.009201,0.234113,0.046714,-0.057285,-0.511285,0.183513,0.313012,-0.033135,-0.135880,0.226068,-0.126085,-0.140171,0.123502,0.009488,-0.409341,-0.008795,0.291760,-0.029583,-0.005601,0.325714,-0.367458,-0.389852,-0.356662,-0.117927,0.090036,-0.397592,-0.233246,-0.710639,-0.224889,-0.282996,-0.405303,-0.120101,-0.042712,-0.156187,0.223441,-0.691488,0.507420,0.299013,0.124327,-0.394139,0.468797,0.169890,0.157007,-0.016653,-0.254703,0.512376,0.313420,0.171453,0.063959,0.047329,0.094810,-0.030374,-0.520697,0.303791', '1316693', '1307442', '1298197', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2131940', '魔兽', '动作', '这是一个人类和兽人共存，和谐相处，互不侵犯的世界。人类生活在艾泽拉斯大陆中，兽人则在德拉诺劳作繁衍。某日，邪恶的兽人古尔丹（吴彦祖 饰）出现了，它打开了黑暗之门，肆意屠戮手无寸铁的人类，将艾泽拉斯大陆变为了一片地狱的火海。与此同时，曾经与世无争的兽人们如今变得凶猛残暴，他们来到人类的领地，在这里烧杀抢掠，无恶不作。杜隆坦（托比·凯贝尔 Toby Kebbell 饰）是霜狼氏族的酋长，他发现了古尔丹的野心和阴谋，于是带领着自己的部族千里迢迢来到了艾泽拉斯，在此处，人类领袖洛萨（崔维斯·费米尔 Travis Fimmel 饰）亦在寻找结束战争的两全之道。©豆瓣', '崔维斯·费米尔', '邓肯·琼斯', 7.7, 304404, 'tt0803096', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2345947329.jpg', 1.4, 4.4, 29.2, 39.9, 25, '0.295188,0.415863,-0.622709,0.712086,-0.034957,0.132547,0.787436,0.113410,-0.358201,-0.159311,0.260782,0.785131,0.168694,0.097175,0.220261,-0.070548,-0.204894,-0.372620,-0.215984,-0.208641,-0.337225,0.031972,-0.537531,-0.578616,-0.094806,-0.622946,0.569251,0.158220,-0.094014,0.340644,-0.109055,0.385538,-0.388200,0.446804,-0.252763,0.014668,0.085040,-0.145590,-0.358894,-0.078765,-0.588861,0.155763,-0.259708,0.316133,-0.278043,0.067434,0.833041,-0.907966,0.242227,-0.608008,0.146499,-0.533308,-0.009366,0.037620,0.698436,-0.439179,-0.011447,0.321676,0.308608,0.016071,-0.105631,-0.120110,-0.712410,0.048554,-0.261100,0.383044,-0.425393,0.722675,0.223246,-0.013792,-0.085069,-0.210351,0.226885,0.582966,0.252849,0.511738,0.350375,-0.145816,-0.598807,-0.017577,0.703270,-0.282010,-0.661422,-0.024401,-0.326226,-0.908919,-0.155856,-0.345005,-0.488330,-0.576808,0.551935,-0.169448,-0.279771,0.860661,-1.256099,0.122619,-0.138300,-0.297009,0.192376,-0.348409,-0.393100,-0.466833,-0.255333,-0.245016,-0.256237,0.227747,-0.065059,-0.066843,0.741367,-1.009187,0.148543,0.381280,0.510167,-0.499005,0.734359,-0.446480,0.089976,-0.063302,0.008627,0.671204,0.434403,0.507777,0.157916,0.292962,-0.019739,0.431292,-0.366282,0.686081', '26290398', '7056398', '4160441', '3990098');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21319853', '透纳先生', '剧情', '《透纳先生》讲述了英国画家约翰·透纳充满创作激情的一生，他曾经因创作手法过于先锋而备受诋毁，然而透纳视绘画创作为生命，一生佳作累累，即使临死前都挣扎着爬起床临摹一具女尸。他在晚年尤其自19世纪40年代起即致力于绘画形式与色彩的探索，用食材、口水等不可思议的颜料作画，引来一片争议之声，被视为英国最伟大的画家之一，也是出了名的艺术怪人。', '蒂莫西·斯波', '迈克·李', 7.4, 8263, 'tt2473794', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209080093.jpg', 0.8, 3.6, 33.3, 48.4, 13.9, '-0.095157,-0.343451,-0.462294,0.769567,0.036025,-0.391960,0.616934,-0.072136,-0.547653,-0.634022,0.419752,0.823484,-0.176779,0.211399,0.257563,-0.333735,-0.065537,-0.661090,0.037282,0.168464,-0.042610,-0.262731,0.016305,-0.117792,-0.354211,-0.544016,0.752066,0.150874,-0.395917,0.198386,-0.045871,0.095600,-0.020545,0.107450,-0.131903,-0.472825,0.141047,0.034370,-0.131523,-0.108624,0.163175,-0.605794,-0.152709,-0.010255,-0.770669,-0.141387,0.818391,-0.452934,0.327886,-0.162998,0.712893,-0.416702,0.219157,0.049318,0.083595,0.113072,0.305661,0.405402,0.016596,-0.148295,-0.033121,-0.084637,-0.912274,-0.288129,0.315162,0.134172,-0.569136,0.503617,0.019076,-0.012480,0.037569,-0.224920,0.346478,-0.320901,0.446818,0.566741,-0.050381,-0.009089,-0.141730,0.609496,0.111499,-0.104595,-0.253971,0.482901,-0.376774,-0.352227,0.253588,-0.627555,-0.541018,-0.003495,-0.129822,-0.034259,0.007069,0.381662,-0.843340,0.112467,-0.077600,-0.405546,0.250168,-0.091549,-0.309772,-0.718893,-0.362849,-0.197811,0.178583,-0.363466,0.298384,-0.334117,0.956504,-0.395398,0.059404,0.113775,-0.330461,-0.078851,0.793980,0.025121,-0.360140,-0.138458,-0.296148,0.609078,0.146429,-0.076640,-0.313261,0.122049,0.141327,0.009861,-0.556188,0.748225', '22265121', '27602116', '2027945', '3603547');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132120', '27套礼服', '喜剧', '珍（凯瑟琳·海格尔 饰）是个完美伴娘，已经穿过27套伴娘服的她笃信真爱，可是面对自己暗恋许久的人——她的上司乔治，珍却总是爱在心，口难开。一次派对上，珍的妹妹苔丝和乔治邂逅了，火热招摇的苔丝迅速攫住乔治的目光，事实上，苔丝就是个骄横跋扈的大小姐，但为了俘 获乔治的心，她编出种种谎言，装成温顺可爱的乖乖女，使两人关系迅速升温。不久，两人便打算闪电结婚，而珍则再一次被邀请成为伴娘……©豆瓣', '凯瑟琳·海格尔', '安妮·弗莱彻', 6.7, 64670, 'tt0988595', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p478891073.jpg', 0.7, 6.7, 56.4, 29.9, 6.4, '0.321328,0.098790,-0.531694,0.572267,-0.276533,-0.439346,0.617245,0.021724,-0.320604,-0.087444,0.053127,0.509433,-0.587017,0.306841,0.070547,0.284991,-0.346248,-0.830309,0.038251,-0.032429,0.070666,-0.275281,0.125082,-0.234127,0.126095,-0.373875,0.446591,-0.117088,-0.114741,0.234011,0.702308,0.228558,0.208450,0.335372,-0.108500,0.048493,-0.169953,0.053368,-0.180094,0.028883,0.138905,-0.206770,-0.091593,0.253012,0.149183,0.384894,0.604047,-0.464377,0.061256,-0.015322,0.331512,-0.150941,0.074664,0.238339,-0.050579,-0.066809,0.242217,-0.111936,-0.357636,-0.068560,0.179810,-0.212041,-0.444555,0.178878,-0.052153,0.007383,-0.204606,0.418575,-0.179210,0.171998,-0.044769,-0.321808,-0.155999,-0.058837,0.100353,0.362252,-0.270877,0.134530,-0.223193,0.017557,0.762959,0.463115,-0.172803,0.567170,-0.411116,-0.279934,0.314335,-0.289107,-0.499899,-0.029198,0.355177,-0.151894,0.168839,0.119448,-0.434993,-0.335587,-0.668020,0.252628,0.128053,-0.498447,-0.060099,-0.200426,0.009577,-0.370426,-0.273869,0.199488,-0.123804,-0.284564,0.483837,-0.731869,0.244121,0.289949,0.154290,-0.517868,0.530268,0.081940,-0.256041,-0.177015,-0.158076,0.406476,-0.121821,-0.315554,0.262821,0.395381,-0.134842,0.001377,-0.241549,0.363143', '1301022', '25777330', '30345227', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132187', '大学新生', '喜剧', '雪梨（阿曼达•拜恩斯 Amanda Bynes  饰）的妈妈在她很小的时候就去世了，为了寻找妈妈曾经的足迹，今年她进入了妈妈当年的大学——南太平洋大学。新生雪梨刚一入学就申请加入本校的姐妹会，可惜不久她就发现姐妹会里全是些金发碧眼的富家女，一个叫雷切尔（萨拉•帕克斯顿 Sara Paxton 饰）的女生掌管着这里的大权。雷切尔的嫉妒心极强，当她得知自己的男友对这位清纯的新生心怀好感时，就坚决排斥她。无奈之下雪梨只好搬出了姐妹会的宿舍来到了普通宿舍。雪梨在这里遇到了7名同样遭到排斥的稀奇古怪的男生，他们很快就打成了一片。雪梨决定联合8人之力向雷切尔控制的专横的学生会挑战，她要竞选下一任学生会主席！这个出人意料的想法最后能否获得成功？©豆瓣', '阿曼达·贝尼斯', '乔·努斯鲍姆', 6.7, 32570, 'tt0815244', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1077553276.jpg', 1.2, 7.2, 53.4, 30.3, 7.8, '0.519987,0.020099,-0.584125,0.591413,-0.372349,-0.404357,0.402880,0.291690,-0.597543,-0.178551,0.374470,0.784085,-0.212150,0.440521,0.268602,0.144317,-0.196905,-0.571658,-0.071755,-0.379062,-0.268313,-0.308535,-0.180173,-0.035045,0.017532,-0.261886,0.398979,-0.189343,-0.116530,0.530040,0.316127,0.180959,0.192424,0.398130,-0.106716,0.202417,0.329499,0.023895,-0.066299,0.275099,0.034981,-0.151401,-0.093904,0.126289,0.201329,0.447315,0.522453,0.045013,-0.179225,-0.143521,0.345915,-0.133024,-0.021315,0.226938,0.589476,-0.057618,0.190936,0.190138,-0.163273,0.166813,-0.111136,-0.104268,-0.391780,0.078501,0.194776,0.001333,-0.652681,0.504943,0.026311,-0.101213,0.234212,-0.278945,-0.020823,0.402180,-0.026276,0.543444,-0.056447,0.048960,-0.397411,0.193937,0.541593,-0.140087,-0.238961,0.053702,-0.200990,-0.376105,0.157818,-0.128392,-0.473736,0.081824,0.351100,0.153734,-0.115028,0.162414,-0.610968,-0.126916,-0.186098,-0.072852,0.304092,-0.343164,0.020417,-0.346063,-0.002743,-0.068170,-0.324290,0.093699,-0.156488,0.012060,0.930145,-1.016519,0.351906,0.410536,0.562364,-0.519168,0.508187,0.243455,0.021949,-0.132833,0.037001,0.179721,-0.140468,0.425234,0.046995,0.539907,0.157066,-0.449676,-0.240241,0.198891', '1292219', '25922902', '3445516', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132220', '三毛从军记', '剧情', '三毛（贾林 Jia Lin 饰）从来就是银幕上喜剧人物。这次，三毛从军了。抗日战争全面爆发了，无所事事的三毛一心想着为国立功，加入了军队。不料，新兵训练的时候就笑话百出。手榴弹实弹投掷训练时，三毛一不小心就将手榴弹投到了战壕里，搞得全军上下一片乌黑。稀里糊涂的三毛随后参加了一支敢死队，笑话百出的他和队友们竟一股全歼了敌军。抗敌有功，三毛高升到后勤部，不用再上战场了，却成了师长姨太太的跟班。整天被使唤也闹了不少笑话。不料兵败师长自杀，三毛又重投兵营。一次执行空降任务时，三毛和以前的知心战友遭到伏击，大难不死却落入深山。一等就等到了抗战结束，三毛和战友早已成了野人。©豆瓣', '贾林', '张建亚', 8.6, 85518, 'tt5781778', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2252295029.jpg', 0.2, 0.9, 12.4, 44, 42.5, '0.167099,-0.364554,-0.546814,0.352821,-0.056319,-0.568189,0.276754,0.089104,-0.351019,0.424934,0.235509,0.633030,-0.363534,0.006132,0.209232,-0.150426,-0.160894,-0.849648,-0.312220,-0.026538,-0.199599,-0.327151,-0.113325,-0.009242,0.138576,-0.227994,0.484891,0.013145,-0.030028,0.400421,0.164292,-0.058668,0.196113,0.617103,-0.027812,0.445031,0.060498,-0.069415,0.153361,0.172309,-0.129799,-0.408573,-0.192837,-0.141096,0.004697,0.331225,0.744022,-0.246687,0.097527,-0.264881,0.060350,-0.234890,-0.080201,0.008792,0.594317,0.076472,0.202351,-0.063780,0.074979,0.259635,0.077112,-0.091094,-0.375055,0.010292,-0.213460,-0.149800,-0.783398,0.520100,-0.025009,0.259095,0.203341,-0.157625,0.311382,0.330149,0.041238,0.179026,-0.525971,-0.072614,-0.383357,0.568393,0.622850,-0.228445,-0.181789,0.073299,0.329061,-0.244554,0.333513,-0.300623,-0.252519,-0.016603,0.473644,-0.271911,-0.277761,0.079614,-0.651697,0.174213,-0.363549,-0.240484,-0.139552,-0.145477,-0.125499,-0.317896,0.164710,-0.017323,-0.367449,0.418429,0.111612,0.252356,0.693353,-0.615769,0.036173,0.442007,-0.065530,-0.129821,0.346242,0.144541,0.176912,0.167536,0.505931,-0.522647,0.140945,0.778349,0.752360,0.469869,-0.354670,-0.338868,-0.202291,0.387528', '1408130', '1826173', '1466273', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132290', '完美无瑕', '剧情', '20世纪60年代，英国伦敦。供职于伦敦钻石公司的劳拉·奎恩（黛米·摩尔 Demi Moore 饰）美丽端庄，聪明睿智，工作兢兢业业。但在女性地位尚未得到足够尊重的年代，尤其是这家男性占主导地位的钻石公司，劳拉的付出始终得不到应有回报，升职的机会一次次与之擦肩而过。某天，劳拉应邀和公司的清洁工——即将退休的胡布斯（迈克尔·凯恩 Michael Caine 饰）出来看电影，却得知自己将被公司开除的消息，她的事业瞬时陷入绝地。在钻石公司工作十多年的胡布斯深谙公司内部的管理情况，他瞄上了钻石公司的保险库，策划在退休前大干一笔，而多年来郁郁不得志劳拉正是这次行动的绝佳人选……©豆瓣', '迈克尔·凯恩', '迈克尔·莱德福', 7.5, 18944, 'tt0780516', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p779520803.jpg', 0.4, 2.4, 34.2, 48.5, 14.6, '-0.218794,0.467862,-0.668743,0.409693,-0.317018,-0.463406,0.395350,0.443114,-0.375639,-0.277242,0.072436,0.620313,-0.077070,0.270017,0.352459,-0.007536,-0.140851,-0.590500,-0.057940,-0.267104,0.099869,-0.573491,-0.348690,-0.260394,-0.204205,-0.248879,0.655474,0.086972,-0.003315,0.154490,0.371217,0.406360,0.200210,0.405586,-0.055959,-0.336579,0.495941,0.072971,-0.637344,0.057407,-0.021282,-0.278050,-0.007637,0.093392,0.419280,0.229117,0.316594,0.240276,-0.107058,-0.174472,0.794130,0.001245,0.103843,-0.094028,0.653027,-0.001622,0.206405,0.193099,-0.345940,-0.176714,0.115381,-0.363698,-0.818967,-0.023794,0.151108,0.139521,-0.667740,0.441301,-0.122516,0.066369,-0.119822,-0.440005,0.166624,0.341356,0.249251,0.188436,0.017908,0.306569,-0.620541,0.292023,0.362765,0.048209,-0.218713,0.222993,-0.237856,-0.577151,-0.023218,-0.301658,-0.326050,-0.111213,0.399629,-0.062941,-0.015510,0.031467,-0.416970,-0.106535,-0.193581,-0.435462,0.157581,-0.450466,-0.178203,-0.986102,-0.304029,-0.351687,-0.316334,0.056328,0.306635,-0.207428,0.601497,-0.861786,-0.049372,0.566078,0.208571,-0.736369,1.046711,-0.106020,0.196917,-0.296945,-0.101535,0.266549,0.146356,0.137792,-0.096813,0.038272,-0.070999,-0.358137,-0.168640,0.496078', '24751811', '4301278', '26259202', '1295276');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132412', '死亡飞车', '动作', '2012年，美国经济状况恶化，犯罪率剧增，已逐步私人化的监狱为谋取暴利不择手段，于是“死亡飞车”比赛应运而生。昔日优秀的赛车手弗兰克（Jason Statham 饰）在工厂里参与了一场工人抗议，结果当天夜里，有人潜入他的家中，杀害了他的妻子，弗兰克却被当做凶手蒙冤入狱。监狱长、死亡飞车比赛的组织者轩尼诗（Joan Allen 饰）要求弗兰克顶替身死的蒙面赛车手科学怪人，并允诺只要弗兰克以科学怪人的身份再赢一场，他即可获得自由。弗兰克与领航员凯丝（Natalie Martinez 饰）进入了这场驾驶改装车并随时会遭遇死亡的疯狂游戏，怎奈他心不在焉的状况下出师不利，弗兰克面临轩尼诗的威胁与陷害，不得不放手一搏……©豆瓣', '杰森·斯坦森', '保罗·安德森', 7.6, 93031, 'tt0452608', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1004007969.jpg', 0.4, 2.9, 30.8, 47.9, 17.9, '-0.075307,0.297204,-0.412994,0.248810,-0.107695,-0.076349,0.505194,0.030954,-0.411472,-0.339617,0.469064,0.700525,-0.160841,-0.072290,0.325838,-0.092228,-0.310353,-0.585647,-0.126202,0.144964,-0.259111,-0.455038,-0.272040,-0.402360,0.069182,-0.084931,0.574816,0.207765,-0.404609,0.483619,0.286059,0.342585,-0.029927,0.449997,0.158520,-0.249031,0.216972,-0.058993,-0.436937,0.218978,-0.059437,-0.289321,0.032536,0.094523,0.050769,0.336779,0.603508,-0.236944,-0.180205,-0.312391,0.356498,-0.478280,-0.057576,0.139877,0.385640,0.010778,-0.002187,0.410725,-0.025720,0.084058,-0.132319,-0.100121,-0.804452,-0.036534,-0.048707,-0.142142,-0.144924,0.271127,-0.295990,0.227340,-0.021558,0.047878,-0.037003,0.259054,0.353770,0.137221,-0.252765,-0.292693,-0.541024,0.222826,0.686513,-0.097172,-0.244370,0.159475,-0.090428,-0.466072,-0.074055,-0.408022,-0.275308,0.033990,0.468176,0.076915,-0.193863,0.251223,-0.369474,0.006479,-0.394915,-0.308636,-0.017340,-0.090714,0.115454,-0.597946,0.020283,-0.070909,-0.231611,-0.074731,0.010382,-0.313029,0.295885,-0.562472,0.131202,0.686366,0.205153,-0.662553,0.254883,0.086047,0.312873,-0.164155,-0.178159,0.236386,0.020949,0.295409,-0.169988,-0.116786,0.114336,-0.215653,-0.002973,0.290507', '26678784', '27073234', '2988294', '1292739');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132426', '死魂盒', '惊悚', '在一个平凡的日子里，中年男子克莱德（杰弗里·迪恩·摩根 Jeffrey Dean Morgan 饰）从前妻斯蒂芬妮（凯拉·塞吉维克 Kyra Sedgwick 饰）处接来两个女儿汉娜（麦蒂森·达文波特 Madison Davenport 饰）和艾米莉（娜塔莎·凯利斯 N atasha Calis 饰）和自己共度假日时光。当他们驱车周游社区时，刚好瞥见邻居正在甩卖自己的物品。艾米莉看中了一个老旧但独特别致的木匣子，此时她尚不知道，这是一个隐藏着恐怖秘密而且绝对不允许打开的盒子。盒子一旦开启，厄运如影随形，艾米莉和家人的噩梦就此开始……本片根据《洛杉矶时报》记者莱斯利·戈尔斯坦（Leslie Gornstein）依据真实事件创作的《盒子里的恶灵》（Jinx in a Box）改编。©豆瓣', '杰弗里·迪恩·摩根', '奥勒·博内代尔', 6.1, 12505, 'tt0431021', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1629715477.jpg', 3.1, 18.3, 56.5, 16.9, 5.2, '0.388322,0.132992,-0.467506,0.439454,0.031275,-0.257929,0.895140,0.252098,-0.486250,-0.445635,0.014917,0.607410,-0.093392,0.138525,0.218597,0.339253,-0.526045,-0.503483,-0.082585,-0.307184,-0.350650,-0.263230,-0.470812,-0.437605,0.150000,-0.178890,0.282335,-0.078078,-0.003370,0.268788,0.193073,0.444908,-0.310973,0.240138,-0.023548,0.023691,0.411182,0.128244,-0.083998,0.322122,-0.056465,0.017580,-0.158746,0.095038,0.091617,0.273202,0.493224,-0.463367,0.077601,0.045210,0.307019,0.160202,-0.084196,-0.025917,0.160587,-0.069356,0.151913,-0.019800,-0.503401,0.053318,0.420442,-0.226022,-0.525122,-0.250700,0.034395,0.396089,-0.431272,0.380568,-0.497484,-0.045255,0.178655,-0.277917,-0.026985,0.273974,0.275460,0.175924,0.164432,-0.210883,-0.547086,0.113028,0.107876,-0.029087,-0.260654,0.356759,-0.259009,-0.225210,-0.089245,0.146836,-0.725498,0.081314,0.493460,-0.064454,0.155972,0.178332,-0.621846,-0.273421,-0.438426,0.061044,-0.053890,-0.218586,-0.199716,-0.749860,-0.025307,-0.192661,-0.343892,-0.040585,-0.124086,-0.032821,0.567414,-0.529184,0.372549,0.487459,0.007249,0.160987,0.696153,-0.245343,0.268645,-0.545519,-0.117063,0.260202,0.335174,0.106415,0.152186,0.565525,0.184180,-0.223603,-0.229367,0.483029', '1316693', '10466639', '1394176', '1309101');
