INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21324299', '末日迷踪', '动作', '影片改编自同名小说，讲述由凯奇扮演的机长驾驶飞机在万米高空突遇诡异气象，同时地球上成百万人神秘消失。凯奇要将破损的飞机迫降，地面上他的女儿也要寻找失踪的妈妈和弟弟。', '尼古拉斯·凯奇', '维克·阿姆斯特朗', 4.3, 10610, 'tt2467046', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2315662314.jpg', 31.3, 34.7, 24.5, 5.9, 3.6, '0.360043,0.103371,-0.899659,0.747640,0.290021,0.111499,0.850910,0.216787,-0.337535,0.142841,0.587286,0.861023,-0.219471,-0.114531,0.261746,0.636469,-0.612002,-0.686380,-0.282472,-0.200016,-0.511506,-0.516010,-0.329946,-0.181012,-0.012435,-0.306421,0.489749,-0.036074,0.074705,0.508363,0.090156,0.022522,-0.244864,0.167518,-0.627910,0.099481,-0.474265,0.024165,0.032804,0.293691,-0.159133,-0.196901,0.506547,-0.177613,-0.032725,0.203796,1.109238,0.353439,0.087292,-0.149157,0.187578,-0.325190,0.403155,-0.294029,0.421160,0.290244,0.031693,-0.038403,0.146372,-0.239402,0.110322,0.055492,-0.447428,0.102255,-0.171699,0.121948,-0.570330,0.194492,-0.303946,-0.189738,0.055146,-0.503561,0.346152,0.044476,-0.018305,0.310974,-0.098085,0.023984,-0.334916,0.375410,0.359667,0.002331,-0.177743,0.281827,0.159791,-0.175162,-0.331824,-0.396593,-0.552348,0.003314,0.364619,-0.074556,-0.221308,0.410768,-0.401216,0.078726,-0.356957,-0.382782,-0.363266,-0.312747,-0.283842,-0.657279,0.015885,-0.051593,0.006556,-0.034811,-0.106443,-0.346841,0.722487,-0.462213,0.359485,0.478780,0.280270,-0.173126,0.667394,-0.074042,-0.004227,-0.243504,0.517147,0.108719,-0.140275,0.480629,-0.255059,0.076647,-0.077255,0.165983,-0.634329,0.485081', '21619567', '1467779', '1309194', '1401900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132430', '如何众叛亲离', '剧情', '西德尼·扬（西蒙·佩吉 Simon Pegg 饰）是个胆大包天、离经叛道的英国年轻人，他毕业于名校，出身高知家庭，却偏爱旁门左道——创办了一本名为“后现代评论”的杂志专门解构和讽刺明星名流，很不受人家待见。杂志濒临倒闭的当口，扬意外接到来自纽约知名八卦杂志的电话，请他过去上班。进入新坏境的扬依然坚持自己的原则，他不肯根据上流人士的意思改稿，和老板怒吼“新闻自由”，不肯去拍新锐导演马屁……不断挑战潜规则难免让他和周围的一切格格不入。职场磕磕绊绊中，扬和女同事阿里森（克斯汀·邓斯特 Kirsten Dunst 饰）产生感情，又受到新人女明星苏菲（梅根·福克斯 Megan Fox 饰）青睐。扬慢慢学会顺应规则，似乎融入这个上流社会，但内心仍有个真正的自己从未停止呐喊……本片根据英国作家托比·扬（Toby Young）2001年出版的同名回忆录改编。©豆瓣', 'Kelan Pannell', '罗伯特·B·维德', 6.8, 21698, 'tt0455538', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p777950234.jpg', 1, 7.4, 49.2, 34.4, 8, '0.463971,0.171236,-0.453782,0.491348,0.151173,-0.133501,0.468276,-0.084369,-0.348936,-0.294811,-0.139038,0.726661,-0.357847,0.216226,0.279706,-0.076420,-0.288904,-0.604672,0.017981,-0.009372,0.169473,-0.407488,-0.369588,-0.118389,-0.359006,-0.237069,0.176533,-0.138920,-0.420744,0.547716,0.517721,0.395602,0.033147,0.264743,-0.132985,0.028218,0.167239,-0.099553,-0.198537,0.054403,0.354103,-0.223934,-0.158767,0.029205,0.102075,0.217643,0.337883,-0.057115,0.125258,-0.040734,0.751309,-0.181221,-0.238776,0.016110,0.338289,0.199662,0.023323,0.214631,-0.176758,0.212334,-0.167718,-0.241466,-0.359043,-0.182689,0.110087,0.316329,-0.244077,0.580887,0.016297,0.015414,-0.156449,-0.268160,-0.150349,-0.178003,0.253543,0.249510,0.269769,0.235549,-0.299669,0.201624,0.286602,0.266262,-0.357150,0.099772,-0.588244,-0.267233,-0.224695,-0.274531,-0.675086,-0.031180,0.197890,-0.070492,0.168393,0.215106,-0.361889,-0.080502,0.069333,-0.128730,0.227959,-0.361735,-0.228905,-0.724650,-0.248113,-0.182503,0.053850,-0.249922,0.201311,-0.271953,0.630652,-0.755910,-0.045516,0.230214,0.033550,-0.431836,0.661687,0.233327,-0.319789,-0.213805,-0.236925,0.142109,0.174447,0.133721,-0.046674,0.264309,0.141251,-0.437663,0.192411,0.384751', '26259202', '