INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132473', '僵尸世界大战', '动作', '费城一个毫无征兆的宁静早晨，前联合国调查员盖瑞·雷恩（布拉德·皮特 Brad Pitt 饰）驾车载着妻子凯伦（米瑞·伊诺丝 Mireille Enos 饰）和两个女儿蕾切尔（Abigail Hargrove 饰）、康妮（Sterling Jerins 饰）外出。谁知原本快乐的气氛很快变为恐慌与死亡所替代，连环的爆炸，惊恐逃散的人群，无序的车祸以及啃咬他人的丧尸，繁华大都会转瞬沦陷。盖瑞费尽九牛二虎之力带着妻女逃生，最终逃到联合国副秘书长所在的航母上，进而得知包括美国总统在内的数名大国首脑均已死亡，丧尸病毒业已蔓延全球。为了阻止世界毁灭，格里无奈受命，和来自哈佛的病毒学博士法斯巴克（Elyes Gabel 饰）前往病毒的源头之地寻找解除危机的办法。这是一场几乎完全没有希望且充满磨难的征程，世界命运危在旦夕……©豆瓣', '布拉德·皮特', '马克·福斯特', 7.6, 273630, 'tt0816711', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2119276553.jpg', 0.5, 3, 31, 47.1, 18.5, '-0.011180,0.138592,-0.706086,0.373389,0.209623,-0.182111,0.709863,0.156462,-0.396481,-0.228975,0.179561,0.471873,0.007168,0.012141,0.426626,-0.102987,-0.378016,-0.423798,-0.276167,0.000343,-0.214127,-0.333186,-0.336376,-0.012403,0.133529,-0.432985,0.743902,0.317858,0.003677,0.663228,0.126605,0.548994,-0.414343,0.475103,0.201786,-0.157243,0.296892,-0.326223,-0.653157,0.055460,-0.084982,-0.120852,0.016648,0.174096,-0.320094,0.253164,0.738675,-0.497747,0.246495,-0.335423,0.171101,-0.403127,0.042360,0.084108,0.220861,-0.099877,0.066199,0.194489,-0.109018,0.058393,0.356800,0.193138,-0.543314,-0.089842,0.112240,0.246883,-0.171894,0.267292,-0.038783,0.060410,0.078624,-0.214326,0.185974,0.395051,0.096335,0.359290,-0.260359,0.221616,-0.459125,-0.113218,0.624605,-0.435770,-0.427573,0.100810,-0.153146,-0.312266,-0.014200,-0.270904,-0.415792,-0.047070,0.341696,0.357709,-0.121862,0.438123,-0.563027,-0.177557,-0.432958,-0.432429,-0.099957,-0.139582,-0.218325,-0.734739,-0.003135,0.111341,0.014799,-0.078899,0.119685,0.063615,0.343548,-0.341286,0.326222,0.239412,0.060487,-0.330701,0.337393,-0.052827,0.200343,-0.308462,-0.155927,0.606507,0.118835,0.606481,-0.071899,0.108632,-0.062519,0.012486,-0.195275,0.407887', '3871833', '25986180', '3011051', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132475', '最后一站', '剧情', '年轻的瓦伦汀（詹姆斯·麦卡沃伊 James McAvoy 饰）应聘成为大文豪列夫·托尔斯泰（克里斯托弗·普卢默 Christopher Plummer 饰）的秘书和助手，目睹了晚年文豪和他妻子索菲娅（海伦·米伦 Helen Mirren 饰）之间爱恨交织的深刻情感。托尔斯泰不满索菲娅奢侈的生活习惯，索菲娅则看不惯托尔斯泰和“激进派”弟子弗拉基米尔·切科夫（保罗·吉亚玛提 Paul Giamatti 饰）的合作，围绕着托尔斯泰，两度力量始终较劲，瓦伦汀也被牵扯进去，分别为索菲娅和切科夫写日记，记录托翁晚年生活，同时也和托翁崇拜者玛莎（凯瑞·康顿 Kerry Condon 饰）产生了感情。疲惫的托尔斯泰终于选择离家出走，弥留在最后的车站，而索菲娅和切科夫的斗争直到最后一刻都未止息……©豆瓣', '詹姆斯·麦卡沃伊', '迈克尔·霍夫曼', 7.5, 14206, 'tt0824758', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p492393835.jpg', 0.3, 2, 33.3, 49.2, 15.2, '0.314214,-0.075136,-0.687240,0.499361,0.025158,-0.643667,0.718863,0.419411,-0.267471,-0.255574,0.176846,0.714458,-0.334725,0.155025,0.525441,-0.029190,-0.564765,-0.650294,0.071641,0.103523,-0.124141,-0.854314,-0.174045,-0.241123,-0.159564,-0.284729,0.359944,-0.078931,-0.127989,0.548004,0.425733,0.489874,-0.019931,0.340331,0.168906,0.179194,0.406143,-0.278286,-0.451772,-0.186182,0.095151,-0.023713,0.167519,0.133523,0.058841,0.312050,0.354241,-0.419261,0.330435,0.051075,0.158372,0.006411,0.230452,0.105889,0.182387,0.215356,0.198874,0.321992,-0.121986,-0.117015,0.133257,0.032346,-0.456038,0.111660,0.186646,0.310886,-0.504661,0.578736,-0.171144,-0.105627,0.140232,-0.113507,-0.068593,0.396959,0.165524,0.481954,-0.137593,0.065651,-0.161994,-0.092750,0.212048,-0.011838,-0.230417,0.237451,-0.449302,-0.162218,-0.062814,-0.220582,-0.442788,-0.150772,0.158302,0.184858,0.087095,0.545525,-0.462066,-0.222165,-0.243980,0.165084,0.196219,-0.351004,-0.082835,-0.631701,-0.287993,-0.516518,-0.374299,-0.134083,0.147256,-0.054655,0.645845,-0.355788,0.181712,0.344976,0.233949,0.042955,0.686686,0.185563,0.020653,-0.154597,0.026269,0.616895,0.012457,0.053829,0.379540,0.432479,0.131754,-0.117142,-0.041998,0.483218', '4319218', '1945337', '25777634', '1895119');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132477', '狼人', '剧情', '劳伦斯·塔尔伯特（本尼西奥·德尔·托罗 Benicio Del Toro 饰）因幼时的悲痛记忆，离家多年并与家人鲜有联系。一日，在伦敦演出的劳伦斯被弟弟本杰明的未婚妻格温·康利弗（艾米莉·布朗特 Emily Blunt 饰）找到，康利弗告诉劳伦斯本杰明惨死的消息，并请求他回家乡黑色荒野进行调查。劳伦斯重新回到幼时生活的地方，此行他不仅想找出杀害弟弟的凶手，而且希望揭开母亲当年惨死父亲怀中的真相。记忆中宛如世外桃源般的黑色荒野因为接连有人受袭身亡而陷入恐慌，关于月圆之夜出现的怪物更是众说纷纭。调查中劳伦斯终于亲眼见到传说中的怪物——狼人，在追杀狼人的过程中，劳伦斯不幸被咬伤。伤愈之后的劳伦斯感到自己的体内开始产生变化，关于被狼人咬伤后将变成狼人的传说应验在了劳伦斯的身上……©豆瓣', '西蒙·梅雷尔斯', '乔·庄斯顿', 5.7, 10842, 'tt0780653', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p599820377.jpg', 4.3, 24.6, 56, 12.1, 3, '0.146679,0.010205,-0.658188,0.351000,0.109930,-0.373374,0.858567,-0.200974,-0.696415,-0.499767,0.077206,0.599409,-0.204643,0.460443,0.304204,-0.008269,-0.284727,-0.692531,0.016998,-0.226415,-0.353473,-0.374592,-0.242951,-0.257257,0.203393,-0.533113,0.489925,0.197346,-0.009967,0.460569,-0.005287,0.676962,-0.272342,0.358937,-0.095009,0.169012,-0.015807,0.075244,-0.334864,0.200898,0.139359,-0.142628,0.087533,0.246878,-0.071780,0.306644,0.802209,-0.373697,-0.102265,-0.279960,0.237795,-0.141562,0.165311,0.099064,0.452155,0.093422,0.275020,0.371572,-0.149603,-0.270227,-0.042484,-0.091693,-0.457868,0.096903,0.082061,0.326671,-0.242793,0.073846,-0.224345,0.240685,0.064782,-0.327924,0.291489,0.275806,0.346123,0.231239,-0.149891,0.029324,-0.345576,-0.000796,0.581950,-0.466093,-0.181263,-0.045012,-0.052220,-0.239676,0.195097,-0.023402,-0.107110,0.287803,0.352233,0.322232,-0.556660,0.656169,-0.422539,-0.278643,-0.498935,-0.143041,-0.127528,-0.075394,-0.362640,-0.477299,-0.251935,0.062608,-0.245035,-0.324053,-0.027632,-0.271149,0.176658,-0.567872,0.746899,0.394874,0.117842,-0.141184,0.249652,-0.244653,0.271625,-0.055746,-0.029648,0.723020,0.494055,-0.027227,-0.045823,-0.043676,-0.082946,-0.059301,-0.409466,0.458066', '1292528', '35341588', '3531406', '4817901');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21324900', '降临', '剧情', '地球的上空突然出现了十二架贝壳状的不明飞行物，悬浮在十二个不同的国家的上空，外星人向人类发出了讯号，但人类却并不能够解读。美国军方找到了语言学家路易斯（艾米·亚当斯 Amy Adams 饰）和物理学家伊恩（杰瑞米·雷纳 Jeremy Renner 饰），希望两人能够合作破解外星人的语言之谜。经过数次的接触，路易斯发现外星人使用了一种极为特殊的圆环状的文字，并逐渐了解了其中的奥妙。由于一直无法确定外星人来到地球的真正目的，中国、俄罗斯等四国决定对外星人发起进攻，美方亦决定放弃研究将全部人员撤离，在这个节骨眼上，路易斯终于明白了外星人的意图，利用外星人赋予她的特殊的“武器”，路易斯以一人之力改变了未来。©豆瓣', '艾米·亚当斯', '丹尼斯·维伦纽瓦', 7.8, 429876, 'tt2543164', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2411622421.jpg', 0.7, 3.2, 25.1, 47.8, 23.2, '0.478926,0.213831,-0.700225,0.698294,0.138117,0.022643,0.389921,-0.458244,-0.616105,-0.333642,0.056665,0.656971,-0.020048,-0.108009,0.165765,0.018614,-0.317876,-0.508916,0.085180,-0.277594,-0.534610,-0.807985,-0.622536,-0.307235,-0.042874,-0.322271,0.740763,0.125398,-0.431882,0.261807,0.026322,0.264452,-0.021338,0.456734,0.038827,-0.298534,-0.037151,-0.174243,-0.382303,0.367624,-0.085285,-0.047658,0.194336,0.438694,-0.371734,0.432563,0.583336,-0.751460,0.035893,-0.164511,0.253288,-0.176732,0.043751,0.229575,0.212666,0.138242,-0.252744,0.115631,0.097373,0.103953,-0.030780,0.260291,-0.699414,-0.193636,-0.057644,0.290147,-0.362837,0.252634,-0.120173,-0.066785,-0.280821,-0.439818,0.220214,0.636720,0.530955,0.331024,-0.133349,-0.000887,-0.380970,-0.244710,0.300569,0.037483,-0.636739,0.314061,-0.282173,-0.686317,-0.431751,-0.103764,-0.061298,-0.036573,0.325260,0.475249,-0.166024,0.273498,-0.864694,0.094392,-0.328552,-0.307718,0.058119,-0.487149,0.125224,-0.912033,-0.230944,-0.169737,-0.312322,0.182572,-0.034437,-0.167690,0.690989,-0.996939,0.117824,0.581620,0.454710,-0.381419,0.404154,-0.019404,-0.204277,-0.652105,-0.121426,0.382318,0.172637,0.439870,-0.197213,0.298430,0.365176,-0.217883,-0.300825,0.264587', '1420088', '20274039', '1308237', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132495', '朱诺', '剧情', '高中生朱诺（艾莲·佩奇 Ellen Page饰）大大咧咧，是个可爱的精灵鬼，正经历着青春期到成人的蜕变。这一天她突然做出决定：要和帅气的田径队员布里克（迈克尔·塞拉 Michael Cera饰）共尝禁果。朱诺这次可闯了大祸，她一不留心竟然珠胎暗结，接下来的麻烦可想而知。和布里克谈婚论嫁显然还为时过早，但朱诺并不想堕胎，她和好友商量，决定把孩子生下来，然后交给一对善心的夫妇抚养。然而，父母终究得知了朱诺的秘密，反应并没有朱诺料想的那么糟糕——一家人因为腹中的孩子团结起来，共商计策，为她分担怀孕的点滴苦乐。但是，朱诺毕竟是一个超级年轻的妈妈，小小年龄如何应对这一切，恐怕还要经历一次心灵的蜕变。©豆瓣', '艾利奥特·佩吉', '贾森·雷特曼', 7.9, 231454, 'tt0467406', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p583934580.jpg', 0.2, 1.5, 25.1, 51.2, 21.9, '0.216435,-0.220346,-0.649676,0.240486,-0.409159,-0.449055,0.687198,0.095053,-0.519325,-0.354063,0.018149,0.646574,-0.283436,0.181471,0.202717,-0.008533,-0.272388,-0.462302,0.119989,0.108093,-0.145867,-0.535833,-0.339900,0.033685,0.122697,-0.303874,0.589166,-0.020132,0.314249,0.335927,0.427134,-0.123060,0.099177,0.243341,-0.066741,0.182186,-0.037071,0.285261,-0.251406,0.105233,0.297473,0.050835,-0.184866,0.295179,0.048380,0.440273,0.427467,-0.360856,-0.249704,-0.136390,0.512362,-0.296478,-0.079903,0.210822,0.223943,-0.145439,0.267136,0.093502,-0.058001,0.040389,0.118557,-0.209266,-0.612122,0.246808,0.117433,0.045867,-0.643815,0.204277,-0.014216,0.068095,0.058099,-0.282440,-0.136224,0.717551,0.346070,0.427722,-0.414361,-0.065330,-0.415213,-0.035532,0.828730,0.008379,-0.231471,0.517473,-0.035025,-0.494946,0.052608,-0.443790,-0.447587,0.445833,0.112803,0.200005,-0.400946,0.293695,-0.187222,-0.163505,-0.481156,0.021193,0.033879,-0.369302,-0.005403,-0.163629,-0.148357,-0.290242,-0.602812,0.005896,0.161020,-0.184017,0.738215,-0.756155,0.114453,0.301082,0.145303,-0.674919,0.366237,0.275537,0.292322,-0.246134,0.066768,0.276600,-0.212745,-0.078332,0.057885,0.295012,0.097259,-0.245276,-0.210176,0.133488', '25721544', '1877596', '1296569', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132736', '新乌龙女校', '喜剧', '坐落于美丽乡间的圣·崔尼安女子学院，是一所臭名昭著的学校。女校长卡米拉·弗里敦（鲁波特·埃沃雷特 Rupert Everett 饰）癫狂夸张，特立独行。有道是上梁不正下梁歪，连带着其手下的员工和学生也一个个粗暴无行、乖张无比。好在卡米拉极力提倡自由与个性，因此这里宛如女孩们的无上天堂。某天，卡米拉的侄女安娜贝尔（妲露拉·莱莉 Talulah Riley 饰）被他的父亲（鲁波特·埃沃雷特 Rupert Everett 饰）强令转学至此，这个乖乖女受到同学和老师的好一阵捉弄，几近崩溃。与此同时，古板的教育部长乔夫雷（科林·费尔斯 Colin Firth 饰）决心改革糟糕的教育现状，而圣•崔尼安正是首当其冲的整改对象。自由的天堂危在旦夕，女孩们不愿坐以待毙，甚至连安娜贝尔也参与到这场拯救学校的战争中来……©豆瓣', '妲露拉·莱莉', '奥利弗·帕克', 7, 21869, 'tt0964587', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1234447157.jpg', 1.3, 7.4, 43.6, 34.3, 13.4, '0.332117,0.001232,-0.574330,0.382046,-0.148943,-0.007004,0.475088,0.254946,-0.562072,-0.163575,0.200075,0.613211,-0.160764,0.320485,0.564993,0.111900,-0.301984,-0.505210,-0.191742,-0.020919,-0.075629,-0.581925,0.019087,-0.224894,-0.326899,-0.563718,0.364935,0.035251,-0.158278,0.446434,0.302330,0.441691,0.173373,0.213112,0.079373,-0.104973,0.150523,-0.149647,0.056798,-0.101644,-0.004792,0.171774,-0.289077,0.193507,0.281548,0.255261,0.383976,-0.350519,0.083333,-0.254966,0.500471,-0.169851,-0.055938,0.418055,0.306321,-0.415704,0.128712,0.173274,0.019847,-0.073713,0.209739,-0.365283,-0.571583,0.142018,0.122937,0.040705,-0.376178,0.428264,-0.041046,-0.034445,0.072052,-0.115407,-0.111085,0.265088,0.090108,0.273004,-0.050587,0.002741,-0.301332,0.133304,0.545096,0.182694,-0.428737,-0.071317,-0.335445,-0.251814,-0.125127,-0.411471,-0.667867,-0.224648,0.239574,-0.161745,0.013750,0.427258,-0.469363,-0.310347,-0.339682,-0.118614,-0.064906,-0.231404,-0.224664,-0.604160,0.101321,-0.386395,-0.142820,0.034642,-0.144961,-0.152386,0.831538,-1.075876,0.196279,0.280245,0.354667,-0.427696,0.579213,0.033427,0.321241,-0.138075,-0.389800,0.451142,0.162973,0.172907,0.186120,0.335727,0.006198,-0.247725,-0.106774,0.430692', '25922902', '6963575', '3445516', '3503015