INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21327493', '精灵旅社2', '喜剧', '经过一番艰难的考验，吊儿郎当的人类青年乔纳森（安迪·萨姆伯格 Andy Samberg 配音）终于和吸血鬼女郎梅菲丝（赛琳娜·戈麦斯 Selena Gomez 配音）携手走入婚姻的殿堂，而以梅菲丝的父亲德古拉（亚当·桑德勒 Adam Sandler 配音）为代表的怪物们，和人类的关系前所未有地密切起来。婚后不久，梅菲丝生下了可爱的儿子丹尼斯。小家伙一天天长大，外公德古拉对他疼爱有加，他热切期望丹尼斯能够成长为出色的吸血鬼。与之相对，梅菲丝认定儿子是一个普通的人类小孩，她希望能带丹尼斯走进文明社会，远离暴力血腥的怪物世界。为了阻止女儿一家的离开，德古拉想办法支走梅菲丝，同时叫上科学怪人、狼人、透明人、木乃伊等一帮死党，要在有限的时间里对丹尼斯展开一场吸血鬼养成教育集训。两代人的观念分歧，在怪物的世界中也不例外……©豆瓣', '亚当·桑德勒', '格恩迪·塔塔科夫斯基', 7.8, 171201, 'tt2510894', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2276842218.jpg', 0.2, 1.9, 26.6, 48.8, 22.5, '0.140010,0.006012,-0.549692,0.487458,-0.354397,-0.248751,0.795812,-0.142098,-0.590149,-0.050181,0.175410,0.759628,-0.129741,0.103818,0.362814,-0.161846,-0.288763,-0.530185,-0.132542,-0.120931,-0.255187,-0.495531,-0.358227,-0.535287,-0.176181,-0.473846,0.601795,-0.126409,0.115311,0.313325,0.172537,0.147695,-0.175309,0.124763,0.022531,-0.069698,0.220821,-0.067468,-0.524143,0.091094,-0.009027,0.307396,-0.156499,0.108545,-0.145812,-0.036633,0.554679,-0.544335,0.162073,-0.427320,0.109010,-0.208061,-0.131846,0.202982,0.319904,-0.317873,0.345715,0.312321,0.461482,-0.027790,-0.203994,-0.276200,-0.611737,0.042714,0.109115,0.124280,-0.544853,0.642266,0.013474,-0.151844,0.273368,-0.227319,-0.163486,0.280155,0.503876,0.671027,-0.157800,0.142623,-0.247204,-0.069812,0.432255,0.080987,-0.387828,0.396124,-0.481419,-0.574788,-0.188774,-0.316082,-0.579219,-0.250423,0.267633,-0.004598,-0.331144,0.494001,-0.586335,0.102749,-0.373614,0.025094,0.069646,-0.319866,0.013688,-0.457495,-0.085156,-0.491964,-0.070884,0.076814,-0.062024,-0.382599,0.842750,-0.790465,0.095949,0.458731,0.537909,-0.363214,0.660970,0.029387,0.305005,-0.536323,-0.157210,0.313453,0.055241,0.073836,0.073306,0.251518,0.023775,-0.040004,-0.249648,0.437787', '3005387', '25882279', '