INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21327512', '卧虎藏龙：青冥宝剑', '剧情', '武当弃徒戴阎王（李截 Jason Scott Lee 饰）为抢夺青冥古剑夜袭铁小贝勒府，俞秀莲（杨紫琼 饰）重出江湖，携手旧友孟思昭（甄子丹 饰）保护宝剑，被蒙蔽的魏方（岑勇康 Harry Shum Jr. 饰）助纣为虐，雪瓶（刘承羽 Natasha Liu Bordizzo 饰）告知魏方其身世之谜。一场江湖混战，众人力擒戴阎王，保护宝剑周全。影片改编自王度庐小说《铁骑银瓶》。', '甄子丹', '袁和平', 4.9, 37407, 'tt2652118', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2320939539.jpg', 18.1, 35.5, 35.3, 7.9, 3.2, '-0.719568,0.177486,-0.025515,0.155708,0.183345,0.309730,0.131620,0.170137,0.001205,-0.306566,0.755329,0.234567,-0.066025,-0.310561,0.015756,0.184319,-0.099609,-0.561533,0.342880,0.268843,0.253380,0.288978,-0.255076,-0.032996,-0.127655,-0.376245,0.584951,0.126187,-0.270455,0.504924,0.189904,0.122924,-0.465472,-0.208789,0.010987,0.087166,-0.344050,-0.041069,-0.613465,0.009250,-0.580065,-0.239107,-0.321044,0.022454,-0.278570,0.182763,0.652379,-0.166347,0.373995,-0.214855,0.349719,-0.388457,0.083836,-0.216421,-0.002076,0.249084,-0.064802,0.217454,-0.248266,0.293116,0.181033,-0.161286,-0.177688,-0.083307,0.775499,-0.062133,-0.059363,0.353524,-0.513796,0.131633,-0.160173,0.088958,-0.220320,-0.195217,0.388351,-0.496432,-0.012166,-0.224534,-0.341620,0.679377,0.018173,-0.547774,0.491282,-0.126292,0.387570,-0.060122,0.017695,-0.077921,-0.216750,-0.009035,0.555509,-0.416556,0.412675,0.228292,-0.103221,-0.644239,-0.205314,0.715666,0.085131,-0.358322,0.125118,-0.344738,-0.374850,-0.117222,0.294204,-0.161979,0.552289,0.292840,0.302764,0.184457,-0.098698,0.053880,-0.281907,-0.436548,0.370609,0.269714,0.031214,-0.092606,-0.081070,0.259749,0.401085,-0.025326,-0.059444,-0.083305,0.069206,0.219112,-0.148730,-0.351093', '1466574', '1294564', '3626416', '1301946');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21328095', '科洛弗悖论', '科幻', '未来，人们对资源的需求越来越大，可是地球上的资源已经不能再满足人类。于是地球上爆发了资源危机，并险些引发战争。唯一能阻止战争的只有空间站上的粒子加速器，如果实验成功，粒子加速器成功运转，那么它就能让人们用上源源不断的资源。可是在一次粒子加速器意外事件后，地球整个消失了，空间站上的宇航员开始试图弄清楚在他们身上发生了什么。但随着事情的一点点深入，真相慢慢浮现，更奇怪的事情也随之出现。', '古古·姆巴塔-劳', '朱利叶斯·约拿', 6.2, 23990, 'tt2548396', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2512711499.jpg', 4.1, 18.2, 48.2, 21.6, 7.9, '0.290725,0.579158,-0.793735,0.453271,0.228981,-0.125635,0.547923,-0.267171,-0.628257,0.250310,-0.140558,0.600691,-0.245791,-0.064513,-0.325743,-0.068035,-0.624495,-0.573528,0.264559,-0.012271,-0.935631,-0.508213,-0.093282,-0.294958,-0.170173,-0.543916,0.828070,0.448073,-0.314477,0.022089,-0.119834,0.019976,0.004581,0.940094,-0.078923,-0.234499,-0.203764,0.042207,-0.120358,0.321105,-0.048514,-0.410165,0.284881,0.365768,-0.174087,0.096653,0.484348,-0.346728,-0.227671,-0.413439,0.359570,-0.332128,-0.040009,0.096634,0.067911,0.268785,0.046765,-0.059798,-0.260164,-0.060323,0.045729,-0.079016,-0.734862,-0.466928,-0.330183,0.244817,-0.520185,0.051180,0.188641,-0.223535,-0.140217,-0.248539,0.240182,0.667404,0.263164,-0.156698,-1.030116,-0.163508,-0.617093,-0.035737,0.709638,-0.219239,-0.676423,0.862026,-0.137956,-0.605650,-0.821465,-0.258218,-0.166178,-0.083702,0.072242,0.540730,-0.151033,0.765414,-0.793208,0.407076,-0.221735,-0.618452,-0.022567,-0.054358,0.091474,-0.528249,-0.387620,-0.123978,-0.524396,0.394263,0.164515,-0.455925,0.729371,-0.802972,0.165988,0.743598,0.543814,-0.322728,0.149349,-0.188187,0.180826,-0.200331,-0.189122,-0.008165,-0.309356,0.539143,-0.050898,0.397125,0.309097,-0.281654,-0.196017,0.781165', '1300089', '26871938', '30391241', '30272753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132924', '黄沙武士', '动作', '江湖中，两个武林世家的争斗绵延数百年，直到其中的悲笛家出现了一位刀法高超的武士（张东健 饰），他血洗敌方铲除了自己师父（狄龙 饰）的心头大患，杀戮之后的武士选择归隐，他带着敌人家最后血脉的一个婴儿，在师父为了惩罚其背叛而派遣的层层追兵中远赴美国西部。在荒凉的西部小镇，武士继承了朋友的洗衣店，封印了刀鞘的武士开始努力融入普通人的生活，当地马戏团的飞刀女郎琳恩（凯特•波茨沃斯 Kate Bosworth 饰）被匪帮杀害了双亲，大难不死的姑娘从此苦练飞刀试图报仇，相似的昔日经历让武士和琳恩变得亲近，教授琳恩功夫也成了武士劳作之余最主要的活动。不久，匪帮再次侵袭这个小镇，在武士的组织下，昔日的神枪手罗纳德（杰弗里•拉什 Geoffrey Rush 饰）等居民准备与匪帮决一死战。而武士恩师亲自带队的追杀集团，也在全速向这里赶来……©豆瓣', '张东健', '李升茂', 5.4, 5971, 'tt1032751', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p707605692.jpg', 10.1, 30.1, 43.3, 11.7, 4.8, '0.091827,-0.184730,-0.478715,0.715071,-0.006827,-0.295060,0.554026,0.121424,-0.476896,-0.390340,0.545288,0.851924,0.260774,0.173167,0.388868,-0.187415,-0.036074,-0.729112,-0.145354,-0.271821,-0.429117,-0.134272,-0.119493,-0.318938,-0.043136,-0.545787,0.701354,0.231782,-0.065971,0.500353,0.031392,0.142845,-0.133989,0.152461,-0.295375,-0.062306,0.187493,-0.300374,-0.329187,0.241443,-0.155229,-0.230232,-0.036318,0.126096,-0.217001,0.441472,0.748591,-0.191394,0.229728,-0.317181,0.104462,-0.221259,0.066542,-0.028449,0.631086,-0.116847,0.155790,0.146993,0.012031,-0.212209,-0.136815,-0.152305,-0.620970,-0.015056,0.322871,-0.076056,-0.736165,0.603197,-0.002291,-0.041707,-0.136157,-0.216320,0.112344,0.375779,0.017102,0.113710,-0.028464,0.005612,-0.440851,0.290244,0.649870,-0.331759,-0.081347,-0.129842,-0.063848,-0.353919,-0.029295,-0.466799,-0.422769,-0.292281,0.503121,-0.196183,-0.080493,0.407499,-0.777941,0.027512,-0.500122,0.026840,0.068668,-0.222782,-0.130863,-0.483769,-0.023186,-0.268037,-0.003021,0.115206,0.237904,0.136450,0.836654,-0.849625,0.034023,0.501578,0.387675,-0.398511,0.496201,-0.211219,0.282439,0.008728,-0.072064,0.281550,0.212169,0.453479,0.293715,0.389814,-0.122777,-0.071267,-0.376264,0.207210', '3811356', '1826173', '1292219', '1308837');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132930', '速度与激情4', '动作', '在《速度与激情1》中，为了逃避警察的追捕，多米尼克（范·迪塞尔 Vin Diesel 饰）离开洛杉矶一直流亡于多米尼加共和国。而一车价值140万美金的石油装载车让蛰伏多年的多米尼克再次驾车驰骋起来。而这时，却传来红颜知己莉迪（米歇尔·罗德里格兹 Michelle Rodriguez 饰）惨死的消息。为了查明真相，满腔怒火的多米尼克再次孤身赶回美国。原来，莉迪是为了获得赦免多米尼克的机会，而协助警局抓捕大毒枭坎波斯（约翰·奥提兹 John Ortiz 饰）。不过出于习惯，坎波斯将运送毒品后的莉迪杀人灭口。这样，一边是为女友报仇的多米尼克，一边是历练多年的警探布莱恩（保罗·沃克 Paul Walker 饰），两人再次携手，目标直指大毒枭巴尔加。一场急速复仇就此展开……《速度与激情4》沿用了第三部东京漂移的华裔导演林诣彬，剧情上跳过第三部，直接承袭第二部，可以说是不折不扣的正统续作。', '范·迪塞尔', '林诣彬', 7.8, 163359, 'tt1013752', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230413708.jpg', 0.2, 1.4, 26.1, 51, 21.2, '-0.009614,0.029397,-0.639320,0.565493,0.153951,-0.422239,0.526048,-0.013076,-0.473577,-0.186903,-0.034445,0.805873,-0.061800,0.035081,0.426022,-0.046333,-0.386644,-0.614180,-0.140361,-0.134400,-0.064066,-0.515486,-0.171258,-0.333349,-0.160757,-0.302896,0.462265,0.096743,-0.038978,0.528941,0.566693,0.318771,-0.111002,0.309354,-0.068740,-0.194969,0.108219,-0.211427,-0.526836,0.395551,0.082638,-0.418293,-0.071970,-0.027881,0.044224,0.269852,0.456133,-0.188300,0.311536,-0.142624,0.131595,-0.391790,-0.039430,-0.205203,0.093808,0.015795,0.158055,0.347118,-0.074011,-0.198186,0.193040,-0.230181,-0.615702,0.088083,-0.121387,0.108557,-0.531014,0.069907,-0.405624,0.040911,0.168519,-0.267416,0.049687,0.148098,0.341567,0.028312,-0.162930,0.007248,-0.281999,0.207821,0.682816,-0.066886,0.016613,0.174036,0.093731,-0.288837,0.169842,-0.112041,-0.217474,-0.333511,0.347843,0.065362,0.135074,0.258182,-0.488054,-0.082384,-0.685389,-0.196861,-0.039898,-0.089131,-0.074132,-0.585851,-0.021094,-0.170150,0.144144,0.197091,0.152648,-0.226912,0.433333,-0.409833,0.218821,0.571397,0.239961,-0.450085,0.343498,-0.056507,0.081542,-0.185084,0.106711,0.274058,0.015686,0.179032,0.117530,-0.017141,-0.210394,-0.266327,-0.214334,0.395231', '18