INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21329305', '船长哈洛克', '科幻', '或许过去，又或许未来，人类大规模向宇宙殖民。当人口膨胀到五千亿的时候，散落在宇宙各个角落的人类返回故土地球，却引发了伤亡惨重的归乡战争。为了保护地球这片圣地，人类制定了盖亚制裁，约定不许任何人染指这里。可是曾经作为联合舰队舰长的哈洛克（小栗旬 配音）却背叛盖亚制裁，驾驶着他的阿尔卡迪亚号高举叛旗，成为逃逸一百年之久的通缉犯。联合舰队长官伊索拉（森川智之 配音）指使自己的弟弟亚马（三浦春马 配音）混入阿尔卡迪亚号，探寻尼伯龙根人发明的永动机的秘密。在此期间，哈洛克率领船员向地球挺近，而联合舰队则在太阳系布下天罗地网阻挡他的步伐。遥远的故土，失落已久的真相，令所有人为之震惊……本片根据松本零士的经典科幻漫画改编。©豆瓣', '小栗旬', '荒牧伸志', 6.8, 6322, 'tt2668134', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1935368983.jpg', 2.2, 9.6, 44.1, 33.3, 10.8, '-0.204142,0.186538,-0.950641,0.692879,0.030400,-0.102138,0.485389,0.056254,-0.134139,0.041703,0.292482,0.522639,0.261056,-0.138154,0.508108,0.221831,-0.494531,-0.503718,-0.023043,-0.366286,-0.188736,-0.215220,-0.366700,-0.409533,0.044416,-0.485941,0.903678,0.135808,-0.387064,0.114470,-0.080994,0.400895,-0.380778,0.271409,0.062032,-0.009908,0.158785,-0.161237,-0.339505,0.118829,-0.715479,-0.093419,0.019279,0.267575,-0.198398,0.291775,0.463256,-0.520874,0.116389,-0.415581,0.127564,-0.438691,0.020874,-0.207085,0.528876,-0.087134,-0.169276,0.108866,0.106553,0.068776,-0.133246,-0.016211,-0.816644,-0.276613,0.022794,0.110179,-0.253820,0.125721,-0.400345,-0.075417,0.088666,-0.112497,0.104493,0.729499,0.324337,0.178922,-0.157188,0.269728,-0.326075,0.018845,0.443465,-0.075089,-0.381016,-0.356319,0.074200,-0.431701,-0.341674,-0.221605,-0.535817,-0.085877,0.259271,-0.131140,0.254717,0.729598,-0.785345,-0.063864,-0.251009,-0.441893,0.283040,-0.330845,0.149008,-0.793155,0.194137,0.107149,0.068097,-0.078071,0.256779,-0.043418,0.710811,-0.360849,0.344680,0.779960,0.441674,-0.517617,0.319783,0.120969,0.040855,-0.279154,0.197454,0.562825,0.210180,0.779372,0.030726,0.083998,0.257900,0.002269,-0.350511,0.409112', '3610047', '20326665', '2051813', '7155241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132932', '星际迷航', '动作', '故事发生在的二十三世纪，人类的科技发展已经到达了可以星际旅行的地步。2230年出生于瓦肯星的男孩史波克（扎克瑞·昆图 Zachary Quinto 饰），因为母亲阿曼达·格雷森（薇诺娜·赖德 Winona Ryder 饰）是人类，经常遭到同僚的嘲笑和欺负。父亲萨瑞克（本·克劳斯 Ben Cross 饰）是瓦肯星的一名外交官，史波克从小就不断地在严肃的瓦肯逻辑教育和他的人类情感之间挣扎。长大后的史波克遇到了同样怀着远大志向的柯克（克里斯·派恩 Chris Pine 饰），两人虽矛盾不断但通过种种任务考验逐渐开始互相理解。企业号的老舰长是克里斯托弗·派克（布鲁斯·格林伍德 Bruce Greenwood 饰），舰员则包括医疗官“老骨头”麦考伊（卡尔·厄本 Karl Urban 饰）、总工程师史考特（西蒙·佩吉 Simon Pegg 饰）、通讯官乌瑚拉（佐伊·桑塔纳 Zoe Saldana 饰）、舵手苏鲁（约翰·周 John Cho 饰），以及17岁的领航员——天才少年契柯夫（安东·尤金 Anton Yelchin 饰）。而来自未来的老年史波克（伦纳德·尼莫伊 Leonard Nimoy 饰）因穿越时空，告诉了柯克未来罗慕伦帝国的残余势力尼诺（艾瑞克·巴纳 Eric Bana 饰）也已经回到现在，并率领大队人马进行复仇，尼诺摧毁了史波克的家乡瓦肯星，下一个目标便是地球……本片荣获第82届奥斯卡最佳化妆奖。【媒体评价】30年来最令人兴奋的星际迷航电影，它标志着柯克船长新传奇的开始，如果接下来的续集敢于保持这一部的快节奏风格，必将成为未来几年最不可忽视的票房炸弹。——《帝国》自《星际迷航', '克里斯·派恩', 'J·J·艾布拉姆斯', 8.1, 161287, 'tt0796366', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p455376387.jpg', 0.3, 1.5, 18.8, 51.9, 27.6, '0.074973,0.102491,-0.546055,0.613186,0.165490,-0.336311,0.437617,0.103525,-0.318061,-0.483035,0.108501,0.612145,-0.046356,0.056963,0.434327,0.055758,-0.591530,-0.426096,0.028257,-0.206437,-0.142164,-0.646896,-0.215106,-0.275897,-0.091011,-0.416161,0.645784,-0.135791,-0.125611,0.198168,0.310715,0.536139,0.224856,0.177820,-0.028892,-0.031673,0.384410,-0.263865,-0.380964,0.114571,-0.083060,0.107826,0.082454,0.035260,-0.036680,0.236966,0.480083,-0.488580,0.282668,-0.185861,0.295782,-0.077894,0.031644,-0.118886,0.343954,-0.135101,-0.135300,0.246065,0.121876,0.140068,0.061337,-0.169370,-0.569124,0.024087,-0.029194,0.198587,-0.381121,0.271077,-0.173433,0.010273,0.041585,-0.114694,-0.001359,0.471079,0.362504,0.172265,-0.144411,0.157102,-0.416506,0.070397,0.348580,0.126263,-0.458909,0.251500,-0.194109,-0.576883,-0.268328,-0.244156,-0.662032,-0.023226,0.275143,-0.119752,0.073072,0.650247,-0.602306,-0.023840,-0.463426,-0.326252,0.098583,-0.153188,0.129348,-0.838350,0.040453,-0.452437,-0.171390,-0.004865,0.036074,-0.220435,0.609260,-0.549106,0.160988,0.310841,0.077481,-0.201772,0.424763,0.061897,0.178587,-0.348246,-0.084169,0.619768,0.055453,0.130011,-0.073242,0.252545,0.219982,-0.281556,-0.018053,0.559154', '30229667', '2364001', '1293656', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2132941', '黑夜传说3：狼族崛起', '动作', '遥远的黑暗世纪，柯文诺斯的子孙一分为二。血族在维多（比利·奈伊 Bill Nighy 饰）的领导下独行天下，强大的吸血兵团压制极具传染性且无法进化成人的残暴狼族。直到某天，一个神奇的生命诞生，改变了这两个家族的命运。一只母狼诞下有着人类外表的狼人路西安（麦克·辛 Michael Sheen 饰），维多窥见狼人身体内的强大实力，于是对其大量繁殖，并将狼人纳为服务血族的奴隶。奴隶的苦难永无终结，而在这一过程中路西安还冒天下之大不韪与维多的女儿桑雅（罗娜·迈特拉 Rhona Mitra 饰）偷偷相恋。渴望自由的路西安最终设法解开维多对自己的禁锢，狼人与血族持续数百年的战争亦由此拉开序幕……©豆瓣', '麦克·辛', '帕特里克·塔特普洛斯', 6.8, 47286, 'tt0834001', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1428220176.jpg', 1, 7.3, 50.3, 31.4, 10, '0.078143,0.179830,-0.279767,0.744864,-0.004025,-0.226754,0.867316,0.227315,-0.332180,-0.007155,0.263348,0.661674,0.083418,-0.136703,0.184419,-0.117049,-0.126379,-0.429309,-0.055762,0.172047,-0.241436,-0.192553,-0.764473,-0.209783,0.084049,-0.555828,0.867095,0.245338,0.066546,0.494012,0.097596,0.285182,-0.219853,0.083192,-0.201612,-0.050087,0.033554,-0.247975,-0.181707,0.098169,-0.278074,0.042313,-0.020372,0.230979,-0.312193,0.058479,0.535073,-0.664767,0.178664,-0.576770,0.410023,-0.244063,-0.034164,0.072821,0.386587,-0.177565,0.071955,0.230354,0.093301,-0.090387,0.032499,0.235499,-1.138046,-0.167212,-0.137926,0.184519,-0.392479,0.389360,0.058946,0.003529,0.156778,-0.307971,-0.471841,0.441210,0.094948,0.366150,-0.237459,-0.063560,-0.471972,-0.150033,0.515289,-0.358625,-0.879584,0.006958,-0.222197,-0.675256,-0.149411,-0.478288,-0.420227,-0.371482,0.479927,0.392003,-0.202677,0.611524,-0.842660,0.059167,-0.460461,-0.142322,0.120130,-0.171004,-0.098502,-0.450252,-0.329969,-0.400314,-0.184063,0.014994,0.404227,-0.129457,0.744316,-0.626660,0.383609,0.675700,0.407865,-0.351030,0.481617,-0.212347,0.382390,-0.151365,-0.196035,0.724423,0.053989,0.415842,0.101500,0.358070,0.046325,0.255658,-0.474036,0.743986', '1308784', '26667010', '10440076', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21332518', '胜者即是正义SP', '剧情', '至今仍在古美门律师事务所内服役还债的黛真知子（新垣结衣 饰）持续在败诉的路上艰难前行，而高傲自大的古美门研介（堺雅人 饰）则在海外的雪场自由玩耍，兼带调戏偶然结识的美女别府敏子（广末凉子 饰）。与此同时，日本兔之丘中学一名男生坠楼摔成重伤。男孩的母亲坚信儿子在校受到 了欺负，是被其他男孩推下楼的。对此家长与校方意见不一致，男孩母亲通过真知子找到了讨厌小屁孩和学校的古美门。校方迅速予以回应，登门拜访三木律师所。至今仍沉浸在对可爱小纱织深深怀念中的三木（生濑胜久 饰）派出旗下的新人律师，以60岁高龄一次性通过司法考试的敕使河原勋（北大路欣也 饰）。一个古美门绝对不可轻视的对手，加上令他心惊肉跳的新人法官，他的不败纪录能否继续……本片为2012年同名电视剧SP版。©豆瓣', '堺雅人', '石川淳一', 9.1, 93710, 'tt13327842', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151557606.jpg', 0.1, 0.3, 6.5, 32.8, 60.3, '0.029667,-0.001086,-0.464978,0.360513,-0.124037,-0.172639,0.382121,0.206786,-0.455849,-0.322153,0.172159,0.534267,-0.154576,0.399008,0.305934,-0.198054,-0.071767,-0.393557,-0.165961,0.043098,-0.094472,-0.387860,-0.050946,0.028375,-0.344963,-0.180362,0.683204,-0.138416,-0.065797,0.638625,0.291205,0.342356,-0.209209,0.203730,-0.018224,-0.045743,0.312153,0.109802,-0.173090,0.296009,-0.171497,-0.289745,-0.011895,-0.154721,0.119866,0.408167,0.713373,-0.139192,-0.194499,-0.115297,0.382539,-0.174448,-0.255293,0.301114,0.372515,0.064359,0.327787,0.191421,-0.029268,0.086610,0.021645,-0.075081,-0.453254,-0.006716,0.346786,0.131298,-0.391546,0.635243,-0.192870,-0.129240,0.118799,-0.243422,-0.236194,0.131942,0.062692,0.318687,-0.314148,0.369676,-0.206648,0.252320,0.341877,0.039662,-0.176667,0.081817,-0.202606,-0.424508,0.159241,-0.319841,-0.511706,0.049153,0.102609,0.014516,-0.036904,-0.136756,-0.213410,-0.121538,-0.111497,0.091666,0.035904,-0.197984,-0.198887,-0.526120,0.157940,-0.305630,-0.213449,0.085863,0.217787,-0.258019,0.673935,-0.624767,0.021867,0.426709,0.387887,-0.209454,0.728229,0.184081,-0.110087,-0.272037,-0.252109,0.205774,0.161638,0.196223,0.006936,0.335458,-0.065097,-0.343954,-0.250699,-0.003855', '3811356', '25922902', '3445516', '1306544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21332535', '无须多言', '剧情', '专业按摩师Eva（茱莉亚·路易斯-德瑞弗斯 Julia Louis-Dreyfus 饰）是个离婚十年的女人，有个正处在叛逆期的女儿。在一个派对上，她在一个客户介绍下认识了一个女诗人Marianne；又在另一个朋友的介绍下认识了一个中年离婚男人Albert（詹姆斯·甘多菲尼 James Gandolfini 饰）。一开始她对肥肥的Albert并无好感，但在第一次约会之后，她发现了他身上某些地方挺吸引她的，两人很快确立了关系。同时，女诗人Marianne也成为Eva的客户，她经常上门为她按摩，两人也成了无话不说的好朋友。Marianne向Eva说起她的前夫的种种缺点，Eva发现，Marianne的前夫竟然就是自己的男朋友！她开始觉得Albert身上的缺点越来越明显，她该如何维持和Albert的这段关系？©豆瓣', '茱莉亚·路易斯-德瑞弗斯', '妮可·哈罗芬瑟', 7.4, 6902, 'tt2390361', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2172381720.jpg', 0.5, 2.9, 35.8, 48.5, 12.4, '0.744655,-0.031285,-0.655783,0.756401,-0.451827,-0.401268,0.918512,0.043577,-0.455559,-0.400294,0.147771,0.998485,-0.425631,0.446421,0.183499,0.096947,0.007445,-0.714075,0.071132,-0.218983,-0.503373,-0.552874,-0.399528,-0.017965,-0.240286,-0.207731,0.405803,-0.349095,-0.130948,0.282528,0.460715,-0.110907,0.314088,0.684744,-0.308957,0.039539,-0.033850,0.004131,-0.136518,0.312489,0.055228,-0.169430,0.032124,0.291581,-0.187514,0.590399,0.618951,0.108389,-0.334431,-0.010270,0.533175,0.161571,-0.010273,0.045540,0.534995,-0.069600,0.399096,0.018346,-0.210123,-0.142130,-0.043003,0.072425,-0.563084,0.159361,0.010049,0.217519,-0.654505,0.507727,0.036855,-0.149938,-0.096567,-0.669236,0.085352,0.484607,0.098334,0.480537,-0.335110,0.172411,-0.532430,0.077740,0.774199,0.285327,-0.017488,0.676909,-0.204844,-0.397298,-0.096700,0.172804,-0.452916,-0.258198,0.166689,-0.210470,-0.218273,-0.058773,-0.581995,0.060484,-0.002313,0.016554,0.027629,-0.598045,0.129146,-0.234822,-0.311225,-0.504726,-0.569979,0.121985,0.080916,-0.495862,0.742510,-1.148259,0.029690,0.799765,0.297576,-0.652465,0.730794,0.464039,0.128036,-0.392591,-0.133082,0.094161,0.034929,-0.113459,0.113038,0.639241,-0.051225,-0.100704,-0.342847,0.584381', '1292219', '1937946', '1308755', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133293', '高楼大劫案', '喜剧', '乔什（本·斯蒂勒 Ben Stiller 饰）原本是一名兢兢业业的高档公寓的大楼经理，多年来他一直带领着手下的工作人员竭尽全能保证大楼里面居民的安全，为他们提供舒适的生活。而突然有一天，住在大楼顶层的投资巨头亿万富翁亚瑟（阿伦·阿尔达 Alan Alda 饰）被警察带走，罪名是他从投资人那儿骗走了20亿美元的资金。这下乔什和他的同事们都不知所措，因为这里面也包含他们的退休金。但是，这被骗走的20亿却被亚瑟藏在了不为人知的地方，很可能就在亚瑟的家里。所以，为了讨回自己的退休金，乔什带领自己手下的员工，开始了一场不可能完成的任务，前往被警察层层包围的大楼顶层，偷回属于自己的退休金……©豆瓣', '本·斯蒂勒', '布莱特·拉特纳', 6.8, 24203, 'tt0471042', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1133262589.jpg', 0.5, 5, 52.7, 35.1, 6.7, '0.325349,0.011627,-0.954555,0.385160,-0.456086,-0.129174,0.721323,0.233929,-0.412344,-0.111245,0.499414,0.819756,0.132744,0.240843,0.202339,0.267510,-0.300936,-0.512561,-0.284057,-0.491631,-0.268744,-0.343139,-0.317214,-0.506157,-0.081943,-0.155827,0.402114,0.162044,0.188740,0.167946,0.395636,0.245549,0.131548,0.419548,-0.221054,0.082364,0.381377,-0.259688,0.088659,0.138576,-0.126823,-0.191683,-0.016050,0.174169,0.394805,0.394439,0.481922,0.083568,-0.161972,0.206166,0.096070,-0.343199,0.071159,0.017772,0.399623,-0.006229,0.254407,0.244963,-0.512623,0.129848,0.251820,-0.184688,-1.062736,-0.181919,0.091780,0.046132,-0.711714,0.562996,-0.126908,-0.030166,-0.020811,-0.181411,0.228600,0.262956,0.043325,0.376267,-0.157216,0.023465,-0.879471,0.213765,0.495112,-0.321886,-0.010286,0.128382,-0.313263,-0.466540,-0.182072,-0.203856,-0.517645,-0.194887,0.462337,-0.088913,-0.012331,-0.163602,-0.576469,0.101687,-0.212949,-0.479969,-0.266657,-0.603629,-0.182796,-0.563836,0.020319,-0.243595,-0.137131,0.211551,0.110466,-0.182817,0.707912,-0.686699,0.004395,0.632525,0.578203,-0.643682,0.858525,-0.137062,0.281540,0.144382,-0.190843,-0.178140,0.157483,0.706311,0.419171,0.313954,-0.139771,-0.206032,-0.150077,0.460110', '1299932', '1793491', '1308842', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133318', '情迷拉斯维加斯', '喜剧', 'Joy（卡梅隆•迪亚茨 Cameron Diaz 饰）处处以男友Mason为中心而丧失了自我。但Mason反而对此厌倦向Joy提出分手。Jack（阿什顿•库彻 Ashton Kutcher 饰）在父亲的家具工厂上班但并不努力，对此失望的父亲一怒之下解雇了他。两个失意的人，在各自好友Tipper（蕾克•贝尔 Lake Bell 饰）和Hate（罗伯•考德瑞 Rob Corddry 饰）的劝说下前往拉斯维加斯度假。灯红酒绿，两个心灵受伤的人敞开了心胸，度过了疯狂而美好的夜晚。早晨醒来发现结了婚，而Joy出钱Jack出力的一次赌博竟赢得了300万美元的大奖，都想独吞奖金的两人找来了法官。法官为惩罚两人对婚姻的儿戏，判决冻结奖金6个月。互不相让的两人在各自好友的建议下决定“击垮”对方，逼对方先提出离婚，自己可以独吞奖金。于是，一场场争锋相对却妙趣横生的较量随之展开......', '卡梅隆·迪亚兹', '汤姆·沃恩', 6.5, 14493, 'tt1033643', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2675206191.jpg', 1.1, 10.4, 56.8, 25.9, 5.8, '0.115728,-0.007056,-0.634313,0.459425,-0.228826,-0.466879,0.653113,0.345761,-0.256392,-0.040919,0.155573,0.643511,-0.236486,0.078031,0.465115,-0.094637,-0.309809,-0.757061,0.067933,-0.110710,-0.112876,-0.698037,0.152192,-0.373761,-0.114943,0.015712,0.597179,0.087832,-0.012392,0.542440,0.403466,0.006938,0.199317,0.480830,0.092462,-0.070974,-0.160060,0.126990,-0.506997,0.280034,0.030013,-0.063903,-0.373358,0.278998,0.124653,0.480445,0.615412,-0.141551,-0.221962,0.077648,0.440536,-0.356319,0.024508,0.186774,-0.008142,0.122946,0.275478,0.187427,-0.289408,0.076338,0.226246,-0.081073,-0.619641,0.238232,-0.042463,-0.159599,-0.525138,0.630667,0.055855,0.265184,-0.151140,-0.234399,-0.011105,0.466978,0.275338,0.427609,-0.298285,-0.131803,-0.458639,0.087129,0.691927,-0.023276,-0.074832,0.247623,-0.305628,-0.224486,0.050743,-0.286079,-0.404907,-0.185746,0.355165,0.137367,0.034398,0.084055,-0.757724,-0.212976,-0.238680,-0.215580,-0.138531,-0.736758,0.207884,-0.523719,-0.200223,-0.004527,-0.227607,0.248656,0.092252,-0.289781,0.310055,-0.738166,0.046289,0.406409,0.523947,-0.758918,0.694551,0.251113,0.130904,-0.217382,0.010638,0.133942,0.084059,0.067406,0.101796,0.028302,0.182439,0.155683,-0.440141,0.203345', '1949320', '10876425', '25908042', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133323', '白日梦想家', '剧情', '沃特.密提（本·斯蒂勒 Ben Stiller 饰）是一名在《生活》杂志工作了16年的胶片洗印经理，他性格内向，甚至无法跟心仪的同事谢莉尔（克里斯汀·韦格 Kristen Wiig 饰）开口搭讪，面对生活他像个旁观者，时常“放空”做白日英雄梦。直到有一天公司被并购，杂志需要做最后一期的封面，而封面成功与否的关键是找到狂野摄影师尚恩（西恩·潘 Sean Penn）的一卷胶片，沃特终于开口搭讪谢莉尔，并在她和母亲（雪莉·麦克雷恩 Shirley MacLaine 饰）的鼓励下踏上真正的冒险之旅，冰原、大海、喜马拉雅山……沃特的白日梦远不及现实壮丽。©豆瓣', '本·斯蒂勒', '本·斯蒂勒', 8.5, 398728, 'tt0359950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2160195181.jpg', 0.2, 1.1, 13.6, 42.1, 43, '0.273573,-0.066742,-0.324562,0.528859,0.141427,-0.332661,0.569211,0.269681,-0.268978,-0.444227,0.065732,0.726861,-0.215618,0.188329,0.168680,0.206713,-0.402366,-0.718704,0.070479,0.032561,-0.140340,-0.387024,-0.155739,-0.057175,-0.080477,-0.143209,0.599269,0.011545,-0.070764,0.228069,0.278981,0.117672,0.145463,0.315083,-0.090584,0.013278,0.200926,0.128926,-0.398468,0.198475,0.025941,-0.027786,-0.411464,-0.002148,0.281552,0.143660,0.395323,0.023919,-0.171166,0.262890,0.403237,-0.146767,0.228345,-0.120374,0.052591,-0.100752,0.056200,0.066759,-0.170645,0.081710,0.064891,-0.105084,-0.590060,0.140624,-0.159591,0.257397,-0.461182,0.272528,-0.144049,0.070771,0.035677,-0.347581,-0.033645,0.176911,0.350560,0.267228,0.066034,0.120562,-0.386975,0.416123,0.280558,0.512544,-0.323243,0.640336,-0.292098,-0.371135,-0.237040,-0.152893,-0.574403,0.100929,0.234431,-0.123970,-0.226246,0.089988,-0.593697,-0.093936,-0.134439,-0.235426,-0.044019,-0.441904,-0.364264,-0.677679,0.080263,-0.333246,-0.206413,-0.148741,0.010293,-0.365750,0.571923,-0.686651,0.218749,0.613812,0.122908,-0.177358,0.778192,0.254878,-0.095923,-0.239763,0.148979,0.381099,-0.003639,0.201124,0.081100,0.042632,0.172334,-0.122516,-0.494390,0.397566', '3014200', '4301278', '3927750', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133337', '斯图尔特：倒带人生', '剧情', '◎简　　介以扣人心弦的笔法诉说身兼小偷、人质狭持者、精神病与游民等多重身份的男子史都华一生的故事。除了描绘他前科累累、放荡不羈的鲜活人生，也藉此带出了英国下层社会有关暴力、毒品、监狱与犯罪等令人震撼的面貌，以极度真实而又几近残酷的写实手法，刻画出史都华失败潦倒的一生。但令人惊喜的是，作者与史都华都未以悲伤或自怜的口气来诉说哀伤的生命片段，反而能以充满趣味的口吻娓娓道来，使得整本书在浓鬱的哀愁中，却洋溢著活泼生动的韵律，是这部作品最奇特、也最具吸引力的地方。获奖：2008年英国电影学院奖提名最佳男演员', '汤姆·哈迪', '戴维·阿特伍德', 8.7, 53326, 'tt0853153', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2170102215.jpg', 0.2, 0.9, 10.9, 41.6, 46.4, '-0.069218,-0.201782,-0.335259,0.966969,0.015843,-0.174239,1.059965,-0.099243,-0.750269,-0.006219,0.190596,0.711849,-0.145675,0.289837,0.212837,-0.259120,-0.201964,-0.628285,-0.324964,-0.062541,-0.046417,-0.474326,-0.236390,-0.162572,-0.081587,-0.502660,0.701790,0.392636,-0.463926,0.402231,0.338666,0.322331,-0.341772,0.330705,-0.093158,-0.320429,-0.079546,0.197068,-0.257855,-0.221866,0.319960,-0.408737,-0.264869,0.411988,-0.526673,0.262078,0.818901,-0.096360,-0.157592,0.275769,0.676307,-0.037155,-0.145746,-0.010262,-0.222136,-0.098840,0.363834,0.349318,-0.076322,-0.026785,0.070875,0.032120,-1.187764,-0.021835,0.176125,0.116149,-0.060515,0.369107,-0.066452,-0.124334,0.233271,-0.064405,0.153917,-0.299503,0.584750,0.736278,-0.029317,-0.165927,-0.182082,0.519308,0.097787,-0.042992,-0.549546,0.458622,-0.743352,-0.596550,-0.068679,-0.583543,-0.403781,0.167734,0.135917,0.233719,-0.121995,0.397556,-0.650837,0.025205,-0.153967,0.006626,-0.161248,-0.359447,-0.201275,-0.569806,-0.264080,-0.509123,-0.307048,-0.226914,0.567945,-0.240719,0.672441,-0.542921,0.255590,0.343432,-0.227585,-0.300184,0.534985,0.149651,-0.207119,-0.030518,-0.371550,0.661826,-0.097200,-0.085976,-0.112590,0.324718,-0.109118,-0.066716,-0.352895,0.720615', '6844861', '35360296', '1303542', '27666513');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133340', '年轻的维多利亚', '剧情', '登基前，年轻的皇储维多利亚（艾米莉·布朗特 Emily Blunt 饰）不满母亲肯特—斯特拉森公爵夫人（米兰达·理查森 Miranda Richardson 饰）为私人顾问约翰·康罗伊爵士（马克·斯特朗 Mark Strong 饰）操控，威逼自己签署摄政条约。此时，内心 孤独的维多利亚第一次遇见了表弟萨克森—科堡—哥达亲王阿尔伯特（鲁伯特·弗兰德 Rupert Friend 饰）。1836年，维多利亚女王登基，政务主要由墨尔本子爵（保罗·贝坦尼 Paul Bettany 饰）辅佐，但朝野上下各方势力动荡。内心焦灼的维多利亚写信请求阿尔伯特亲王从比利时来到英国，二人于1840年终结连理。婚后，阿尔伯特发现作为外国人的自己并未完全获得接受，而维多利亚也会在争吵中搬出自己的皇威压人，直到一次意外的刺杀事件让维多利亚意识到阿尔伯特在她生命中的重要意义。©豆瓣', '艾米莉·布朗特', '让-马克·瓦雷', 7.3, 39562, 'tt0962736', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1313979253.jpg', 0.2, 2.6, 40.6, 44.2, 12.3, '0.003955,0.346161,-0.758710,0.687956,0.287823,-0.305795,0.498308,0.174633,-0.861503,-0.620794,0.348294,0.769683,-0.262037,0.151575,0.732199,0.183261,-0.388056,-0.500469,0.126510,0.034001,-0.064025,-0.723603,-0.296867,-0.828139,-0.313558,-0.631986,0.570032,0.003893,0.136801,0.446175,0.364817,0.512466,0.076224,0.452641,0.243157,-0.034829,0.432122,-0.157521,-0.421708,0.111598,-0.029034,-0.241143,-0.094868,0.385228,0.433436,0.376154,0.266666,-0.644059,0.428836,-0.224876,0.405045,-0.041007,0.044139,0.269000,0.150515,-0.049637,0.046838,0.516211,-0.104253,-0.115066,-0.017261,-0.195427,-0.268011,0.113684,-0.221632,0.364340,-0.251766,0.527585,-0.556490,0.030153,0.003686,-0.349173,0.119265,0.400221,0.120730,0.360144,-0.084230,0.161720,-0.172272,-0.132587,0.638212,-0.106997,-0.429226,-0.037456,-0.324735,-0.380572,0.055444,-0.300976,-0.309966,0.033822,0.116634,0.220105,0.273366,0.564764,-0.418735,-0.516392,-0.569724,-0.100731,0.225348,-0.241354,0.073079,-0.580749,-0.319652,-0.271759,-0.079754,-0.104846,0.069475,-0.186829,0.220881,-0.593197,0.386755,0.392908,0.334825,-0.381204,0.388259,0.068897,0.263769,-0.367632,-0.186012,0.597132,0.068814,-0.192580,-0.134901,-0.081279,0.116166,-0.233842,-0.040885,0.287360', '1296252', '1309118', '1294639', '7916027');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133368', '天外来菌', '剧情', '改编自Michael Crichton的同名畅销小说。此片是斯科特兄弟重导2008年的电视剧而成的迷你剧。犹他州的皮德蒙特小镇，一对男女情侣正在山上约会，突然一颗人造卫星掉落。好奇的两人将卫星带回小镇，却不知道也将可怕的遭难带回了小镇。突然间小镇上爆发了可怕的病毒， 人们纷纷不明原因地死去。为防止病毒扩散到其他城市，军队封锁了小镇，并派出了代号为“仙女座”的科学队前去查明病源。队员包括：传染病学家Jeremy（本杰明·布拉特BenjaminBratt 饰）、外空生物学家Angela（克里斯塔·米勒 Christa Miller 饰）、微生物学家Tsi（金大贤 饰）、病理学家Charlene（维奥拉·戴维斯 ViolaDavis 饰）。同时，一个名叫Jack（艾瑞克·麦克马奇EricMcCormack 饰）的记者似乎也在探寻着不可告人的秘密……©豆瓣', '本杰明·布拉特', '米凯尔·萨洛门', 6.7, 11670, 'tt0424600', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2878166782.jpg', 2.3, 9.5, 46, 34.1, 8.2, '0.389694,-0.173528,-0.598826,0.497060,0.254835,0.176301,0.710452,0.016358,-0.407464,-0.061991,0.223977,0.588068,-0.262234,-0.000075,0.168482,0.281194,-0.289903,-0.409896,-0.257118,-0.380437,-0.360259,-0.500792,-0.505744,-0.384478,0.161697,-0.559712,0.425187,0.256616,-0.134142,0.306721,0.268276,0.523469,-0.430498,0.327134,-0.087469,0.032466,0.276853,-0.213282,-0.177533,0.104975,-0.197577,-0.023631,-0.092109,-0.009320,0.054324,0.451939,0.755806,-0.425195,0.036932,-0.187830,0.171380,-0.106604,0.158824,-0.091530,0.391270,-0.065175,0.096062,0.086535,0.062400,0.178906,0.323061,0.007792,-0.375371,0.088092,0.317666,0.369792,-0.477306,0.388355,-0.213696,-0.247087,0.029314,-0.217225,0.277744,0.200977,0.111448,0.247647,0.031936,-0.091019,-0.408865,0.267988,0.344077,-0.038346,-0.165564,0.150371,-0.321019,-0.601206,-0.290520,0.149327,-0.256275,-0.041666,0.545848,-0.062662,-0.098390,0.396128,-0.573215,-0.043653,-0.220213,-0.271485,-0.038018,-0.231114,-0.243266,-0.817145,0.237817,0.069652,0.037497,0.138560,0.043149,0.168898,0.677047,-0.402867,0.139206,0.767735,0.047770,-0.235199,0.447668,-0.287747,-0.013651,-0.337022,-0.282150,0.126534,0.132975,0.435059,0.055461,0.415124,-0.029379,-0.393567,-0.275013,0.136078', '1307897', '27069070'