INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133379', '42号传奇', '剧情', '本片改编自著名棒球手Jackie Robinson的事迹。他出生于1919年01月31日，1972年10月24日逝世，是美国职棒大联盟史上第一位黑人球员。1947年04月15日，他穿著42号球衣以先发一垒手的身分於布鲁克林道奇队登场比赛前，黑人球员只允许在自己的黑人联盟（Negro Leagues）打球。虽然当时美国奴隶制度已废除已久，但仍有许多地区依然实行种族隔离政策，无所不在的种族偏见仍强烈左右著社会各个阶层，因此Robinson踏上大联盟舞台的这一天，被公认为美国近代民权运动史上最重要的事件之一。', '查德维克·博斯曼', '布莱恩·海尔格兰德', 8, 18617, 'tt0453562', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1874017507.jpg', 0.2, 1.1, 20.7, 51.7, 26.3, '-0.250275,0.176258,-0.429257,0.238835,0.413289,-0.186079,-0.078079,-0.168099,-0.570955,-0.327741,0.268213,0.529387,-0.099982,0.128646,0.622396,-0.293226,-0.027997,-0.700458,-0.109169,-0.542309,-0.388472,-0.205094,-0.153413,-0.111586,-0.199451,-0.336864,0.923466,0.341124,0.067167,0.297004,0.317960,0.264677,0.461226,-0.023785,0.181186,-0.419332,0.388010,-0.144758,-0.375702,0.196518,-0.567471,-0.231373,-0.496223,-0.133919,0.048979,0.110244,0.368103,-0.399020,-0.008259,-0.634373,0.884052,-0.154235,-0.532002,-0.134567,0.759184,0.178520,0.286535,0.727098,0.364738,-0.061018,-0.255189,-0.503239,-0.158072,0.379324,-0.022405,-0.084694,-0.384853,0.864438,-0.577739,0.098727,-0.255099,-0.137028,-0.062891,0.440755,0.157506,0.246115,0.039702,0.251122,-0.178216,0.259610,0.665599,0.059643,-0.604537,-0.397690,-0.051773,-0.600222,-0.288337,-0.791147,-0.106559,0.037497,0.204867,-0.055666,-0.022615,0.553838,-0.372348,0.591227,-0.016690,-0.563481,0.460393,0.025973,0.126543,-0.501841,0.041353,-0.434197,0.022549,0.157073,0.216781,0.083078,1.032440,-0.637014,0.375454,0.628928,0.321048,-0.413442,0.779347,0.230083,0.293129,-0.227869,-0.459977,0.674052,-0.170574,0.019269,-0.331550,0.244567,-0.221752,-0.297374,0.136470,0.132473', '26999591', '27602116', '1306998', '26615753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133403', '匪帮说唱传奇', '剧情', '这是一部关于The Notorious B.I.G.的传记片。The Notorious B.I.G.六又叫克里斯托弗·华莱士，是美国说唱史上最为杰出的歌手之一。出身于单亲家庭的他，年少时曾在街头混日子，也干过一些不法勾当。但是一次偶然的机会，克里斯托弗参加了一个说唱音乐比赛，随后被签约，这位天才说唱歌手从此大放异彩，成为了美国东海岸说唱的领军性人物。可惜1997年他不幸遭枪杀去世。本片主要关注了克里斯托弗短暂而辉煌的音乐生涯，以及他扑朔迷离的死亡经历。', '贾马尔·伍拉德', '小乔治·提尔曼', 7.9, 6482, 'tt0472198', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1473904138.jpg', 0.3, 2.4, 25.4, 45.1, 26.8, '0.168790,-0.062843,-0.502808,0.894138,0.155179,-0.165049,0.515829,-0.141920,-0.631819,-0.529488,0.064996,1.108173,-0.121228,0.245084,0.464591,-0.519428,0.198098,-0.789140,0.170311,-0.082788,0.025638,-0.308493,-0.385131,-0.086001,-0.169546,-0.430204,0.647915,0.196350,-0.401129,0.603225,0.599602,0.379342,0.151481,-0.042231,-0.126033,-0.041459,0.455649,0.189876,-0.417592,0.146338,-0.286875,-0.632312,-0.168960,-0.014519,-0.085207,0.065952,0.386185,-0.029755,0.074474,-0.247289,0.691549,-0.246070,-0.326942,-0.270628,0.480424,0.189377,0.352646,0.544290,-0.008542,-0.014692,-0.276800,-0.182050,-1.064800,0.165429,0.074501,0.047495,-0.377058,0.372693,0.065586,-0.149247,-0.289070,-0.112586,0.345431,0.118222,0.449056,0.088171,0.031340,0.224121,-0.072737,0.742512,0.914212,-0.088561,-0.432614,0.343532,0.085052,-0.564754,0.120273,-0.941762,-0.514901,0.590206,0.289746,-0.294778,-0.189576,0.327396,-0.414239,0.162910,-0.024723,-0.510481,0.052153,-0.079717,0.007206,-0.677055,-0.197194,-0.343200,-0.262858,-0.248900,0.024343,-0.332086,0.873911,-0.822652,0.296125,0.667784,-0.273693,-0.637502,0.727872,0.348084,0.248109,0.121650,0.035648,0.379285,0.003138,-0.139685,-0.330956,0.226384,-0.036702,-0.543711,-0.175563,0.403919', '27602116', '4301278', '35262731', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133405', '甩皮鬼', '恐怖', '奸商刘有光事业遭遇窘境，为了让手中的度假村顺利开张，他不惜让一手捧红的女明星叶玉芝（陈颖芝 饰）向相关官员出卖肉体。但在一个暴雨之夜，玉芝不慎触电，虽保住性命，然而容貌尽毁。为赶在高官从国外回来前让玉芝重焕青春，刘有光遍寻名医，却无人能治。在巫医指点下，刘绑架并杀害一名少女，通过锦衣授魂术将少女的皮肤移至玉芝身上。一眉道长（林正英 饰）和一群年轻人来刘拥有的小岛上游玩，发现刘印堂发暗，厄运缠身。当晚，高官与玉芝共赴巫山，谁知……©豆瓣', '林正英', '陈会毅', 6.3, 5594, 'tt0102916', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2880831179.jpg', 3.4, 16.6, 52.6, 16.8, 10.6, '-0.181493,0.245028,-0.368532,0.310346,-0.055547,-0.428685,0.676629,0.235350,-0.437151,-0.224033,0.200502,0.511564,-0.302274,0.053215,0.285558,-0.002835,0.104224,-0.524083,-0.158016,0.093224,-0.431934,-0.022399,-0.182593,0.113361,-0.300215,-0.350592,0.506381,0.149670,-0.268257,0.652592,0.324333,0.124313,-0.352218,0.319157,-0.317490,-0.084560,-0.139807,0.119704,-0.328672,0.427653,0.132984,-0.535412,-0.079419,-0.007977,-0.218375,0.287645,0.558193,0.046310,-0.022316,-0.310917,0.222414,-0.107158,0.143169,0.268421,0.316160,0.041173,0.107098,-0.173174,-0.471896,-0.006739,0.267001,-0.128655,-0.295003,0.089155,0.447197,0.151549,-0.583093,0.019766,-0.139001,0.059828,-0.047826,-0.516793,0.314535,0.275488,0.008783,0.366139,0.006896,0.290000,-0.572424,0.450305,0.402585,0.087823,0.243113,0.087021,-0.105364,-0.272216,0.313833,-0.190454,-0.110364,0.009843,0.277272,-0.040226,-0.010993,0.087737,-0.300374,-0.008352,-0.508369,0.143838,0.006086,-0.107293,-0.292473,-0.354085,-0.005406,-0.111522,-0.244146,0.102619,0.395604,-0.356428,0.596087,-0.456921,0.148770,0.362702,0.155963,-0.278594,0.536769,-0.036567,0.298874,0.046778,-0.349978,0.280594,0.507882,0.711805,0.069082,0.115662,-0.531330,-0.189367,-0.121172,-0.124235', '21619567', '1451563', '1294252', '1773217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133413', '粉红豹2', '喜剧', '自从三年前闹得整个巴黎鸡飞狗跳之后，探员杰奎斯·克鲁索(史蒂夫·马丁 Steve Martin 饰)日常工作就是街边检查一下违规停放的车辆，但还是屡屡搞砸，几番折腾，他终于做出了最后决定：告别法国！突然世界各地，价值连城的文物一一失窃，而"粉红豹"钻戒也失窃了。顶头上司 指名点姓，一定要勇破上回"粉红豹"疑案的克鲁索，总督察雷福斯(约翰·克里斯 John Cleese 饰)只好召回这个让人头疼的探长。于是老搭档波顿(让·雷诺 Jean Reno 饰)、女秘书妮可(艾米莉·莫迪默 Emily Mortimer 饰)都被顺利召回，老队伍回来了，新一轮的摧毁行动也正式宣告开始。凡克鲁索所到之处，无不如台风过境般催枯拉朽，而在结识了漂亮的桑妮娅（艾西瓦娅·雷 Aishwarya Rai 饰）后，他更是照旧神魂颠倒、手足无措、笑话百出。这一次他还能顺利完成任务吗？', '史蒂夫·马丁', '哈罗德·兹瓦特', 7, 19868, 'tt0838232', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2315884676.jpg', 0.9, 6.8, 46.3, 34.7, 11.3, '0.004523,0.170320,-0.586134,0.222440,0.130641,-0.516113,0.264057,0.178551,-0.378284,-0.018425,0.181657,0.426094,-0.426528,0.093199,0.497397,0.307227,-0.523179,-0.607126,0.110160,-0.135254,-0.321788,-0.298868,-0.095101,-0.201910,0.289700,-0.154557,0.089078,0.091215,0.079784,0.416921,0.387552,0.072071,0.149639,0.381894,-0.100461,0.083674,0.167818,0.146032,-0.030438,-0.016763,0.066042,-0.291228,-0.167516,0.048019,0.265873,0.447705,0.407351,-0.246006,-0.259960,-0.076402,0.285037,-0.343082,0.090591,0.137430,0.130202,0.229304,0.293863,-0.011010,-0.412527,0.167117,0.216991,0.035421,-0.395275,0.248370,0.047254,-0.004160,-0.443993,0.276389,-0.135785,0.413226,-0.032574,-0.284255,0.175958,0.210053,0.172125,0.216439,-0.074648,-0.010553,-0.267998,0.373643,0.488223,-0.018422,-0.307180,0.167526,0.188330,-0.132875,0.238589,-0.143158,-0.049578,0.011426,0.405701,0.028612,0.075579,0.111736,-0.557790,-0.274908,-0.629857,-0.258569,-0.310916,-0.144038,0.123208,-0.727781,0.177683,-0.121776,-0.192221,0.175864,0.111029,0.020844,0.252975,-0.281880,0.232502,0.503682,-0.052053,-0.394936,0.061171,0.005694,0.236352,0.019065,-0.116895,-0.143023,0.271165,0.616934,0.233934,0.416044,0.152892,-0.394358,-0.147848,0.262107', '21349734', '3735015', '25