INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133422', '乘客', '剧情', '某飞机失事后109名乘客仅数名幸存。心理医生克莱尔（安妮•海瑟薇Anne Hathaway 饰）被导师派去对幸存者进行心理治疗，却发现自己渐渐爱上幸存者之一，前证券公司副总裁艾瑞克（帕特里克•威尔森 Patrick Wilson 饰）。与此同时，克莱尔发现诊所外经常有人监视，自己被跟梢，病人神秘失踪，甚至航空公司职员也来威胁她不要多管闲事，这令克莱尔怀疑航空公司为掩盖机械故障的事实，故意用操作失误来掩人耳目避免调查，进而对察觉真相的幸存乘客施以毒手。随着克莱尔与艾瑞克感情的深入，病人竟变得越来越少，克莱尔与姐姐一家也失去联络，甚至就连她的自身安全也面临威胁……©豆瓣', '安妮·海瑟薇', '罗德里戈·加西亚', 6.6, 26015, 'tt0449487', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p777910201.jpg', 1.2, 9.7, 53.5, 28.8, 6.9, '0.137244,-0.080870,-0.555540,0.294172,-0.044836,-0.116040,0.663336,-0.059736,-0.566201,-0.446609,0.331594,0.524998,-0.079834,0.118124,0.203573,-0.130177,-0.461241,-0.445037,0.045170,-0.117723,-0.496670,-0.371035,-0.107276,-0.490203,-0.100656,-0.259867,0.276906,0.119091,-0.543396,0.321121,-0.065468,0.394948,-0.262159,0.564394,0.364447,-0.127505,0.211480,-0.354599,-0.120388,0.187178,0.126160,-0.254127,0.176410,0.147854,0.034706,0.771559,0.487486,0.003874,-0.342619,-0.306654,-0.007764,-0.193967,0.246828,0.222364,0.376006,0.129809,0.090636,0.282098,-0.286176,-0.043975,-0.203931,0.476126,-0.636812,0.238167,0.008465,0.063165,-0.262725,0.037393,-0.432804,-0.072026,-0.034838,-0.196098,0.443326,0.331320,-0.047539,0.028005,-0.177377,0.081610,-0.304164,-0.080256,0.569924,-0.110457,-0.180588,0.112525,-0.094170,-0.332204,0.026171,-0.086708,-0.240186,0.029919,0.102916,0.079919,0.054346,0.213993,-0.346763,-0.241311,-0.452525,-0.302296,-0.142536,-0.308194,0.142059,-0.707719,0.091511,0.031703,-0.138365,0.056670,0.106688,-0.181570,0.373831,-0.669623,0.316393,0.754653,0.488316,-0.654400,0.313141,-0.094166,0.105770,-0.232517,-0.330399,0.444939,0.210557,0.404951,-0.016488,-0.211325,0.062510,-0.125032,-0.013918,-0.261829', '35073886', '2974273', '1947080', '3263169');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133433', '迷镇凶案', '喜剧', '20世纪50年代僻静的家乡小镇，中年男子加德纳（马特·达蒙 饰）的妻子在家中被杀害。由此宁静的生活被打破，引发出一连串勒索、骗保、迷情事件。而对面邻居搬来了一家黑人，又因此打破了整个小镇的宁静。家庭危机和小镇危机交织在了一起……', '马特·达蒙', '乔治·克鲁尼', 6.1, 23178, 'tt0491175', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2508546069.jpg', 1.6, 17.2, 57, 21, 3.1, '0.481049,0.257819,-0.566770,0.370612,-0.169751,-0.142397,0.924827,0.602429,-0.620868,-0.160836,0.218125,0.959266,-0.142801,0.366779,0.633067,0.135158,-0.054045,-0.669228,0.073127,-0.241156,-0.300374,-0.422611,-0.143828,-0.475201,0.027376,-0.450762,0.359664,0.466107,-0.130869,0.368687,-0.135219,0.788942,-0.465462,0.458620,-0.602289,0.152355,0.232478,-0.071701,-0.584365,0.125994,-0.567813,-0.532450,0.145000,0.256416,-0.055287,0.284916,0.944133,-0.006867,-0.189684,-0.173538,0.400527,0.123570,-0.221585,-0.109494,0.774683,-0.344006,0.454718,0.336636,-0.426266,-0.353067,0.251843,-0.175862,0.036180,0.364697,0.133505,-0.049690,-0.579019,0.569977,0.418284,-0.427960,-0.058940,0.161572,0.560066,0.530033,0.786792,0.687172,0.054042,-0.036945,-0.352057,-0.008093,0.933733,-0.241246,-0.117594,0.326431,-0.767031,-0.268092,0.071604,-0.264549,-0.566527,-0.120015,0.579176,-0.177733,-0.520588,0.400527,-0.752069,0.071408,-0.320151,-0.135287,-0.030968,-0.378726,-0.583572,-1.068584,-0.395216,0.073199,-0.122092,0.233230,-0.165430,0.278391,0.273040,-0.581253,0.363527,0.531929,0.308945,0.053074,0.542780,-0.140587,0.318609,-0.069152,0.312309,0.255097,-0.024883,0.448342,0.092448,0.035828,-0.625137,0.162045,-0.393501,0.631334', '10466639', '11541282', '26687241', '1498831');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21334420', '死在西部的一百万种方式', '喜剧', '艾伯特（塞思·麦克法兰 Seth MacFarlane 饰）是一位忠厚老实的农夫，既幸运又不幸的是，他深爱着的女子路易斯（阿曼达·塞弗里德 Amanda Seyfried 饰）是一位样貌姣好身材火辣的大美女。在和恶霸弗伊（尼尔·帕特里克·哈里斯 Neil Patrick Harris 饰）的决斗中，懦弱的艾伯特选择了退缩，路易斯因此弃他而去。如何挽回女友的芳心成为了艾伯特百思不得其解的难题，就在这时，一位名叫安娜（查理兹·塞隆 Charlize Theron 饰）的神秘女子出现在了艾伯特的身边，她不仅教会了艾伯特射击，还帮助他重拾了信心，在此过程中，艾伯特渐渐爱上了安娜。可是，安娜的丈夫柯林奇（连姆·尼森 Liam Neeson 饰）可不是好惹的角色，身为江洋大盗的他可不会放过敢“撬他墙角”的艾伯特。©豆瓣', '塞思·麦克法兰', '塞思·麦克法兰', 6.9, 49675, 'tt2557490', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2298516748.jpg', 1.5, 8.6, 43.9, 34.5, 11.6, '0.201178,0.087114,-0.532682,0.487772,-0.574680,-0.381768,0.671676,0.238263,-0.446454,-0.092445,0.423639,0.923232,-0.017900,0.221782,0.231445,0.399067,-0.254159,-0.629246,0.043674,-0.140675,-0.268672,-0.558899,-0.325679,-0.312048,0.042599,-0.555360,0.475902,-0.224070,-0.217186,0.308413,0.615950,0.512703,0.118340,0.358495,-0.141084,0.112712,0.367678,-0.263756,0.082299,0.208340,-0.129426,-0.316776,-0.132580,0.357065,0.045760,0.514626,0.452171,-0.247089,0.013941,-0.033098,0.367288,-0.088629,0.170755,0.093794,0.205945,-0.449565,0.061184,0.092242,-0.118019,-0.101784,0.247546,0.026178,-0.626208,0.148388,0.119800,0.323375,-0.772520,0.430158,-0.220635,-0.193736,0.150907,-0.269204,-0.067361,0.005439,0.147231,0.005330,-0.016185,0.065301,-0.537925,0.072587,0.396755,0.395670,-0.243198,0.379954,-0.157694,-0.387339,-0.156317,-0.156481,-0.709601,-0.113756,0.441893,-0.127749,0.076583,0.162943,-0.309349,-0.202799,-0.584366,0.242376,-0.140668,-0.260673,-0.197819,-0.333247,-0.041746,-0.346338,-0.408541,0.025315,-0.196282,-0.333441,0.741798,-0.804159,0.119013,0.672982,0.076767,-0.225594,0.604965,0.239517,0.047995,-0.088075,-0.153569,0.548357,0.114338,-0.255399,0.093228,0.302870,-0.009383,-0.362168,-0.221404,0.555729', '1309069', '1292720', '30167633', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2133466', '富贵吉娃娃', '剧情', '克洛伊（德鲁·巴里摩尔 Drew Barrymore 配音）是比佛利山的一只吉娃娃狗，被宠坏了的它生活极其奢侈。主人薇薇姑妈（杰米·李·柯蒂斯 Jamie Lee Curtis 饰）要出远门，把照顾克洛伊的任务交给了安吉拉（爱莉·希尔斯 Ali Hillis 饰）。安吉拉带着克洛伊和朋友们一起去墨西哥的海滩旅行。来到海滩， 姑娘们立即被健硕英俊的小伙子们吸引了，而克洛伊则在安吉拉的“重色轻狗”下，走失于硕大的墨西哥城中。那些简陋的街道看起来跟比佛利山大相径庭。无奈之下，克洛伊只得求助于一些新朋友，包括一只经历复杂的德国牧羊犬戴戈多（安迪·加西亚 Andy Garcia 饰），和一只多情的小狗帕皮（乔治·洛佩兹 George Lopez 饰），克洛伊在它们的帮助下，振作精神找寻回家的路......©豆瓣', '派珀·佩拉博', '拉加·高斯内尔', 6.9, 10506, 'tt1014775', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165271797.jpg', 1.1, 6.8, 50.4, 31.3, 10.3, '0.365079,-0.421357,-0.371220,0.576490,-0.251054,-0.349809,0.936834,0.164095,-0.179875,0.006171,0.120522,0.794208,-0.017120,0.405378,0.290205,0.074973,-0.545190,-0.359986,-0.041385,-0.107687,-0.130456,-0.410644,-0.423785,0.031650,-0.109234,-0.163754,0.325449,-0.337867,0.241122,0.680350,0.229842,0.348624,-0.147722,0.088493,-0.530251,0.115379,0.022843,-0.196739,-0.033089,0.141942,0.054836,0.356212,-0.211436,0.040730,0.345285,0.141543,0.682727,-0.328328,0.162773,-0.263364,0.167137,0.098080,0.464589,0.164787,0.328419,-0.049711,0.059375,-0.076117,-0.352873,0.112088,0.459793,-0.282302,-0.384899,0.329060,0.191543,0.184090,-0.712050,0.242922,-0.207830,0.039349,0.195284,-0.481150,0.030291,0.205994,0.058831,0.389152,0.127374,0.312912,-0.279136,-0.179402,0.373881,0.184930,-0.049817,0.050338,-0.330733,-0.143645,0.165728,-0.014507,-0.584005,-0.177751,0.499746,-0.279872,-0.128026,0.189807,-0.824197,-0.240278,-0.164328,-0.481753,-0.293431,-0.201535,-0.235846,-0.850709,0.218585,-0.588721,-0.065092,0.013915,0.093859,0.021126,0.627520,-0.520130,0.316824,0.377356,0.244646,-0.162371,0.602266,-0.224340,0.415784,0.166271,-0.128732,0.338349,0.225027,0.212495,0.361477,0.692743,-0.030883,-0.203037,-0.555505,0.663913', '1394176', '1467779', '35161768', '1419992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21335021', '想要拥抱你', '剧情', '故事发生在远在北海道的网走市，平凡的出租车司机小柳雅己（锦户亮 饰）在市民体育馆邂逅了坐在轮椅上的美丽女孩山本司（北川景子 饰），对方天真而倔强的神情给他留下深刻的印象。一来二去，小柳和小司渐渐熟稔。小司在高中时代遭遇车祸，由此导致左半边身体瘫痪，此外大脑也受到损伤，经常会忘记不久前发生的事情。小柳同情女孩的遭遇，也渐渐为对方所吸引，甚至为此不惜和正在交往的女友分手。他们的恋爱之路注定充满考验与挫折，现实中的种种难题，双方父母的反对，却无法阻止他们走到一起。他们历经千难万险，即将得到爱情的结晶，但是命运之神的考验并未就此结束……本片根据真实人物和事件改编。©豆瓣', '北川景子', '盐田明彦', 7.3, 10194, 'tt2714934', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2132720832.jpg', 0.4, 3.8, 42.6, 38.8, 14.4, '0.225272,0.095076,-0.726227,0.513651,-0.062051,-0.096385,0.887575,0.064191,-0.497101,-0.275484,0.354393,0.733364,-0.190260,0.210542,0.345294,-0.410495,-0.239392,-0.674651,0.118099,0.094174,-0.447177,-0.662752,-0.071527,-0.076387,-0.244731,-0.348806,0.798057,0.187377,-0.356376,0.648087,0.115958,0.286711,-0.448872,0.717809,0.078301,0.318581,-0.109182,0.322762,-0.415201,-0.210453,0.127370,-0.362972,-0.171399,0.260709,-0.115261,0.341334,0.684602,-0.141019,-0.576379,0.166545,0.488973,-0.245871,-0.018464,0.127354,0.356059,0.133687,0.326194,0.302755,-0.150498,-0.059307,0.136672,0.202984,-0.381992,-0.060758,0.057206,0.224113,-0.455167,0.515438,0.079754,-0.057382,0.383108,-0.343724,0.098851,0.518404,0.474441,0.244421,-0.308282,0.052071,-0.294662,0.084500,0.913217,0.071612,-0.303075,0.558282,-0.373568,-0.408836,-0.441280,-0.335334,-0.401821,0.351842,0.289084,0.048889,-0.246986,0.547832,-0.382275,-0.175857,0.029979,-0.157322,0.036602,-0.402815,-0.017176,-0.610545,-0.438663,-0.620583,-0.353920,0.100791,-0.066010,-0.335308,0.578637,-0.874031,0.297962,0.562509,0.141368,-0.497328,0.558844,0.299586,-0.055080,-0.164237,-0.088035,0.469373,-0.002319,0.312910,0.023886,0.173485,-0.057261,0.208550,-0.451912,0.434969', '4275444', '25721544', '35030151', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21339377', '湖畔的陌生人', '剧情', '炎热的夏天，在以男性“钓鱼”著称的湖畔度假胜地， 平静湛蓝的湖水下暗潮涌动。英俊的中年男子弗兰克（Pierre Deladonchamps 饰）周旋于两个男人之间：肥胖风趣的亨利（Patrick d''Assumçao 饰）让他感到非常投缘，两人建立起无话不谈的友谊；美如雕像的迈克尔（Christophe Paou 饰） 让他一见倾心，两人发生肉体上的澎湃激情。然而在连场激战后弗兰克逐渐发现迈克尔神秘而危险的一面，湖畔的一桩凶杀案更让一切变得扑朔迷离。弗兰克无法抵挡迈克尔的吸引，其实早已投入感情的亨利也被卷入其中。究竟该就此抽身，还是放纵欲望铤而走险？本片获得第66届戛纳电影节酷儿棕榈大奖和一种关注单元的最佳导演奖，是年度由内到外的赤裸话题大作。情欲和悬念紧紧相扣，阴郁和激情兼而有之。静谧湖水中心灵与肉体交缠鏖战，直至最后一刻。©豆瓣', '皮埃尔·德隆尚', '阿兰·吉罗迪', 7.4, 18422, 'tt2852458', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1987924821.jpg', 1.1, 4.8, 33.3, 45.1, 15.7, '0.147905,0.036237,-0.930873,0.661235,0.253818,-0.095745,1.146504,0.332107,-0.452721,0.057787,0.167108,0.545680,-0.500797,0.090572,0.366753,-0.155407,-0.019464,-0.944873,-0.330538,0.188637,0.021025,-0.369264,-0.407478,0.192842,-0.171527,-0.386775,0.683220,0.311871,-0.286229,0.603722,0.480135,0.261061,-0.297197,0.579450,0.118711,-0.415420,0.006937,0.176551,-0.447212,0.235383,0.014821,-0.239191,-0.247846,0.166709,-0.197891,0.236345,0.880880,-0.127743,-0.180865,0.189102,0.409140,-0.007261,-0.107405,0.171994,0.159705,0.043741,0.073822,0.163244,-0.251942,-0.040581,0.103527,-0.001955,-0.571299,0.285374,0.083133,0.433464,-0.220483,0.418923,0.170943,-0.278209,0.215354,-0.146048,0.014821,0.167922,0.281842,0.236567,-0.115647,0.023129,-0.163435,0.035105,0.746355,0.198179,-0.592829,0.416430,-0.523289,-0.293046,-0.129737,-0.077561,-0.275218,-0.245036,0.372254,0.478498,0.159196,0.560698,-0.815851,0.076240,-0.039181,-0.092438,-0.338550,-0.369013,0.006367,-0.611490,-0.530256,-0.302832,-0.179717,0.120331,-0.040545,-0.300708,0.392275,-0.524866,0.149306,0.478612,-0.040892,-0.023974,0.522583,0.143776,0.030755,-0.105422,-0.233118,0.492044,-0.136202,-0.088397,0.088852,0.651889,-0.430525,0.350585,-0.512680,0.618525', '20451118', '1467779', '21348112', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21339392', '三分之一', '剧情', '在俱乐部Honey Bunny担任雇佣店长的清原修造（藤原龙也 饰）赌马时弄丢店里的营业额，为免被老板破魔翔（窪塚洋介 饰）杀死，他被俱乐部头牌茉莉亚（中岛美嘉 饰）拉去向恐怖魔女涉柿多见子（池畑慎之介☆ 饰）举债。拆东墙补西墙的做法无济于事，修造找来最信赖自己的小弟小 岛一德（田中圣 饰）和生意濒临破产的常客金森健（小杉龙一 饰），策划了抢劫银行的行动。抢劫当天，三人事成后回到Honey Bunny，可是分赃不均产生内讧。而在这次银行劫案背后，又有多方势力以及阴谋介入其中。尔虞我诈，坑蒙拐骗，谁也不知结局将会如何……本片根据木下半太的小说原作改编。©豆瓣', '藤原龙也', '品川祐', 7.7, 10443, 'tt2727322', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2159305421.jpg', 0.7, 3, 26.1, 49.1, 21.1, '-0.126733,-0.021081,-0.358596,0.078570,0.185393,-0.084406,0.215989,0.306864,-0.274620,-0.341636,0.318754,0.536503,-0.049863,0.063247,0.371351,0.103849,-0.145980,-0.349255,0.010362,-0.104713,0.011587,-0.393013,-0.276661,-0.354482,-0.140054,0.068499,0.489507,0.175995,-0.439721,0.076472,0.478364,0.455242,-0.307489,0.090078,0.289578,0.044635,0.219827,0.182831,-0.126207,0.262439,-0.429233,-0.316640,-0.198263,-0.155103,0.407626,0.392982,0.477340,-0.244928,-0.058451,-0.170714,0.355138,-0.277268,-0.131631,-0.005415,0.525173,-0.043206,0.269757,0.395643,-0.518577,-0.045914,0.200681,-0.018851,-0.670700,-0.004471,0.300082,0.085026,-0.462872,-0.068308,-0.198459,-0.028374,0.003396,-0.241466,0.000785,0.437070,0.473233,-0.095138,0.076609,0.146238,-0.441370,0.112839,0.491023,-0.131487,0.329155,0.039956,0.076744,-0.205730,-0.301634,-0.522061,0.072379,-0.058723,0.319557,-0.166286,0.143612,0.189550,-0.563680,-0.235895,0.030361,-0.173413,0.210486,-0.105996,-0.059959,-0.715797,-0.076000,-0.199421,-0.242575,0.028985,0.495084,0.068937,0.459604,-0.572766,-0.085037,0.515252,0.239317,-0.494957,0.168074,0.113074,-0.162679,-0.170616,-0.383594,-0.237668,0.348760,0.424796,0.123330,0.076887,0.031398,-0.519371,-0.047383,0.021383', '27073234', '2369613', '7155241', '2367213');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2134285', '狗狗旅馆', '喜剧', '本片改编自由路易斯·邓肯(Lois Duncan)创作出来的一本深受读者喜爱的同名儿童读物。16岁的孤儿安迪（艾玛·罗伯茨 Emma Roberts 饰）和弟弟布鲁斯（杰克·T·奥斯汀 Jake T. Austin 饰）被一户人家收养，但这家人却不允许他们养宠物。只能把与 他们相依为命的小狗“星期五”安顿在一所被废弃的旅馆中。旅馆虽然破旧，但是很适合狗狗居住。安迪、布鲁斯与朋友们开始改建旅馆，还发明创造出一系列方便实用的自动装置来帮助狗狗们“自给自足”。很快，这里成了越来越多流浪狗狗的甜蜜小窝。也让身为孤儿的安迪和布鲁斯有生以来第一次体验到了家的温馨与可贵。然而随着旅馆里狗狗的数量越来越多，“流浪狗旅馆”也引起了警察地怀疑，他们逐渐查到了这个地方。孩子们为了保护狗狗打算将其转移，一场斗智斗勇大战就要开始了……©豆瓣', '艾玛·罗伯茨', '托尔·弗罗伊登塔尔', 7.5, 13774, 'tt0785006', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1038834531.jpg', 0.5, 3.7, 34.6, 43.3, 18, '0.726578,-0.164284,-0.606697,0.292484,-0.094063,-0.324037,0.762491,-0.057224,-0.505283,-0.204591,0.075919,0.805336,-0.086508,0.600408,0.083723,0.048705,-0.352815,-0.302804,0.021753,-0.225872,-0.139897,-0.216968,-0.252040,-0.350289,-0.261824,-0.078777,0.370750,0.078132,0.143061,0.439016,0.123460,0.129204,-0.158791,0.289508,-0.298797,0.092667,0.068353,-0.083371,-0.037041,0.165724,-0.111021,0.128986,-0.089361,0.195245,0.315471,0.205579,0.856460,-0.368330,-0.219272,-0.151530,0.288660,0.049022,0.036066,0.209664,0.372747,0.019582,0.494563,0.047400,-0.175397,0.231937,-0.142510,-0.238050,-0.566432,0.097519,0.189138,-0.146878,-0.611373,0.399334,0.034088,-0.215266,0.154649,-0.503382,0.225381,0.072790,0.058243,0.591578,-0.191651,0.173442,-0.486722,0.038301,0.591943,-0.311880,-0.055364,0.342422,-0.376323,-0.449447,0.153243,-0.342307,-0.451940,-0.067825,0.347913,0.101813,-0.362385,0.149007,-0.919151,-0.009351,-0.182064,-0.310340,-0.037984,-0.367586,0.009020,-0.719487,0.066642,-0.237809,0.003559,0.003531,0.036237,-0.303214,0.863413,-0.852433,0.086973,0.626281,0.334266,-0.376636,0.509019,-0.156683,0.433204,0.017465,-0.112253,-0.051530,0.288068,0.246776,0.430863,0.396639,-0.052104,-0.293112,-0.406540,0.577423', '4181031', '3811356', '30205667', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2134294', '明星助理', '喜剧', '1939年，伦敦。这是Pettigrew（弗兰西斯·麦克多蒙德 Frances McDormand 饰）悲惨的一天，起码开始看起来是。身为牧师女儿的她，遵守着严厉和刻板的自我约束，同时也把这些约束和教诲放到她所带的小孩身上。没错，Pettigrew是伦敦的家庭教师，然而 她的严厉管教让家长非常不满，一个月内她就被炒了三次。这次家教中心的Holt女士也将她扫地出门。一身灰色老土打扮穷困潦倒的她急中生智拿起了给Delysia Lafosse（艾米·亚当斯 Amy Adams 饰）小姐的职业推荐信，找上门去。Delysia是一个等待大放异彩的歌影双栖明星，为了争取机会，她同时和三个男人周旋，而只有其中一个是她真心所爱。在接下来的24小时，Pettigrew将帮助Delysia度过种种惊险又富喜剧色彩的危机，并且认清楚真正的幸福是什么，而Pettigrew也收获了自己的爱情。', '弗兰西斯·麦克多蒙德', '贝瑞特·奈鲁利', 7.4, 27337, 'tt0970468', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507752683.jpg', 0.4, 3.4, 37.8, 44.1, 14.2, '0.096291,0.049477,-0.458197,0.552817,-0.520125,-0.145436,0.599765,-0.061219,-0.500237,-0.085979,0.259785,0.727565,-0.041012,0.361974,0.216891,0.151965,-0.103621,-0.648178,-0.063206,-0.114751,-0.280952,-0.558414,-0.206672,-0.212941,-0.090687,-0.407820,0.404728,0.043202,-0.078223,0.297910,0.427366,0.148178,0.216126,0.507946,-0.307292,-0.126417,-0.128798,-0.067534,-0.116688,0.180000,0.245118,-0.277950,-0.085947,0.437302,0.021009,0.447176,0.517018,-0.209514,-0.291715,0.021046,0.558096,-0.450115,-0.120586,0.254161,0.116275,-0.009631,0.327175,0.266620,-0.160026,-0.054329,0.000789,-0.172648,-0.907150,-0.017733,0.182994,-0.004639,-0.862900,0.563870,-0.191249,-0.184597,0.121708,-0.181856,0.165802,0.263565,0.128908,0.404139,-0.267396,0.003865,-0.490538,0.345262,0.620881,-0.069652,-0.135531,0.263061,-0.353009,-0.355710,0.187880,-0.477102,-0.544085,0.028045,0.152220,0.030344,0.034941,-0.115904,-0.487126,0.171109,-0.282111,-0.242465,0.033992,-0.799422,-0.051345,-0.184542,-0.037578,-0.517874,-0.492975,0.035669,0.216575,-0.339310,0.906400,-0.740462,0.258158,0.591079,0.372446,-0.475783,0.712855,0.233316,0.214961,-0.163115,0.016027,0.017749,0.036652,0.161167,0.144992,0.489272,0.220947,-0.147641,-0.297031,0.522846', '18