INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21345845', '涉足荒野', '剧情', '影片改编自美国作家谢莉尔·斯瑞德2012年的同名自传，讲述婚姻触礁，母亲去世，自己在绝望中生活多年之后，虽然毫无徒步经验，却独自一人踏上Pacific Crest Trail 远足之路，通过长途步行找回自我的故事。', '瑞茜·威瑟斯彭', '让-马克·瓦雷', 7.7, 28083, 'tt2305051', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217481599.jpg', 0.5, 2.8, 29.6, 46.8, 20.2, '0.061372,0.118729,-0.678024,0.863626,0.635581,-0.834335,0.530604,-0.672774,-0.697270,-0.749066,0.259702,0.929467,-0.032799,0.366033,0.307675,-0.301706,-0.697120,-0.504903,0.321828,-0.214198,-0.360094,-0.400429,0.177652,0.185005,-0.715769,-0.462338,0.784125,0.101636,-0.142558,0.739359,-0.169158,0.372432,-0.289791,-0.071390,0.069004,0.305416,0.200308,0.389135,-0.590686,0.054961,0.138605,-0.204828,-0.262008,-0.084254,-0.024307,0.414463,0.795458,-0.269414,-0.233577,0.102642,0.506403,-0.170322,-0.117072,-0.349416,0.055264,0.186936,0.298369,0.604281,-0.294858,0.028286,-0.419161,-0.314161,-0.168331,-0.134873,-0.188699,0.072560,-0.364354,0.008477,0.099152,0.207751,0.233727,-0.514780,-0.354739,0.106044,0.757593,0.438744,-0.217850,0.241547,0.081265,0.325476,0.906722,-0.123075,-0.297575,0.668581,-0.298541,-0.138439,0.303560,-0.349828,-0.700419,0.029731,0.039173,0.156474,-0.389937,0.734488,-0.341741,0.293530,-0.455079,-0.127842,0.193963,-0.049598,-0.066744,-0.652254,0.014369,-0.315864,-0.060048,0.082550,-0.028835,-0.787534,0.300324,-0.223245,0.489529,0.341878,-0.010476,-0.434844,0.661289,-0.274520,0.059601,-0.297325,0.787454,1.383198,-0.286591,0.201419,-0.124420,-0.253638,-0.385920,0.425461,-0.718432,0.975576', '22637441', '26611083', '1907465', '1844413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21348112', '神秘感染', '剧情', '萨曼莎（娜嘉拉·汤森德 Najarra Townsend 饰）原本约好和女友妮姬（Katie Stegeman 饰）一起去夜店消遣，她见到了朋友爱丽丝（爱丽丝·麦克唐纳Alice Macdonald 饰），喜欢自己的男孩莱利（Matt Mercer 饰），却独独没有看到妮姬。酒过三巡，落寞的萨曼莎自饮自酌，谁知却遭遇了一名男子的暴行。令人不愿回忆的一夜过后，萨曼莎重新回到烦恼多多的生活中。谁知未过几天，她便发现出现在身体上上的种种异状，莫名的血迹，恐怖刺耳的幻听，眼睛充血，皮肤出现青斑，牙齿脱落。从爱丽丝口中得知，对她施暴的男人似乎是警方正全力追查的一个极度危险的人物。几天前还如花似玉的女孩，而今变成了一副恐怖的死尸模样……©豆瓣', '娜嘉拉·汤森德', '艾瑞克·英格兰德', 6.1, 12177, 'tt2281159', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155954261.jpg', 4.7, 19.1, 50.9, 18.4, 6.8, '0.247795,0.066180,-0.677926,0.416934,0.056835,-0.359627,1.230154,0.196606,-0.471968,-0.309906,0.209191,0.551585,-0.712435,0.582032,0.204443,0.303500,-0.325332,-0.842897,-0.051907,-0.145127,-0.396300,-0.137195,-0.216602,-0.281874,0.123982,-0.528113,0.356859,0.164492,-0.004186,0.597497,0.158232,0.039768,-0.105801,0.875511,-0.082254,-0.142592,-0.054728,0.042228,0.259679,-0.031909,0.192646,-0.492794,-0.041738,0.143213,-0.077049,0.409145,0.810895,-0.242170,-0.175829,0.027459,0.428696,-0.020004,0.079587,0.111218,0.256122,-0.203678,0.182132,-0.219186,-0.231603,-0.260620,0.155017,-0.082815,-0.244184,0.105881,-0.190658,0.307570,-0.523550,0.548524,-0.149123,0.037881,0.149827,-0.418663,0.322159,0.081906,0.051590,0.292632,-0.095418,0.189311,-0.365466,0.162958,0.478529,0.251212,0.047715,0.321986,-0.205867,-0.456232,-0.215132,0.002346,-0.229415,-0.086176,0.176423,0.158729,-0.286730,0.167014,-0.466609,-0.133629,-0.512634,0.033961,-0.203661,-0.184123,-0.439709,-0.472363,-0.289932,-0.459354,-0.375716,0.218721,-0.089565,-0.234175,0.349683,-0.826090,0.136149,0.336601,0.084457,-0.049553,0.425477,-0.057802,-0.194197,-0.061072,-0.263869,0.466336,0.079448,-0.066484,0.282865,0.436546,-0.146916,0.373659,-0.256514,0.504316', '1309297', '20451118', '27617348', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21348876', '偷书贼', '剧情', '1939年的德国，9岁的小女孩莉赛尔和弟弟被迫送往慕尼黑远郊的寄养家庭。6岁的弟弟不幸死在了路途中。在冷清的葬礼后，莉赛尔意外得到她的第一本书《掘墓人手册》。这将是14本给她带来无限安慰的书之一。她是个孤苦的孩子，父亲被打上了共产主义者的烙印，被纳粹带走了；母亲随后也失踪了。在弹奏手风琴的养父的帮助下，她学会了阅读。尽管生活艰苦，她却发现了一个比食物更难以抗拒的东西——书。她忍不住开始偷书。莉赛尔，这个被死神称为“偷书贼”的可怜女孩，在战乱的德国努力地生存着，并不可思议地帮助了周围同样承受苦难的人。', '杰弗里·拉什', '布莱恩·派西维尔', 7.9, 29297, 'tt0816442', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2162741033.jpg', 0.3, 2.2, 24.2, 48.1, 25.2, '0.389032,0.015983,-0.748218,0.637965,-0.276348,-0.439352,0.878212,-0.029517,-0.400982,-0.133938,0.151665,0.766527,0.060290,0.429813,0.202675,0.228568,-0.316755,-0.696370,-0.014837,-0.164390,-0.504039,-0.407586,-0.247955,-0.326973,-0.177407,-0.548018,0.413181,0.174526,-0.010076,0.388096,-0.082214,0.282849,0.431175,0.648391,-0.446328,0.222819,-0.153630,-0.220953,0.374350,0.319589,0.007165,-0.580836,-0.145035,0.331188,-0.073277,0.436843,0.888311,-0.259655,0.004824,-0.186706,0.394694,-0.439999,-0.300030,0.170383,0.251910,-0.071369,-0.006980,-0.074330,-0.369435,-0.050673,0.182932,-0.215092,-0.917354,-0.232661,0.059373,0.132326,-0.842631,0.757697,-0.231277,0.138093,-0.008914,-0.454668,0.290692,0.341040,-0.131821,0.663650,-0.385316,0.046024,-0.537806,0.433449,0.535074,-0.091804,-0.159378,0.242387,-0.580350,-0.483647,0.161677,-0.538251,-0.591713,0.068642,0.570608,0.053513,-0.304541,0.361792,-0.635202,-0.121657,-0.280819,-0.316520,-0.200044,-0.609764,-0.276679,-0.276316,-0.241594,-0.313403,-0.371763,-0.008055,-0.007333,-0.537056,1.098779,-0.695433,0.297975,0.907947,0.362888,-0.291736,0.692296,0.193242,0.183339,0.154999,-0.147133,0.429974,-0.080759,0.484240,0.295138,0.445053,0.137066,-0.019312,-0.448531,0.665674', '10773239', '26348103', '24284209', '1303693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21349175', '乐高蝙蝠侠大电影：DC英雄集结', '动画', '华灯初上的夜晚，哥谭市正在举行盛大的年度人物颁奖晚会，野心勃勃的总统候选人莱克斯·卢瑟（Clancy Brown 配音）输给风流倜傥的布鲁斯·韦恩（Troy Baker 配音），心有不甘。正在掌声雷动的时刻，小丑（Christopher Corey Smith 配音）带领爪牙大闹典礼，洗劫钱财。关键时刻，蝙蝠侠（Troy Baker 配音）和罗宾（Charlie Schlatter 配音）及时赶到，将这伙盗贼绳之于法，送入牢房。而莱克斯为了除掉绊脚石蝙蝠侠和超人（Travis Willingham 配音），秘密研制新式武器，放跑了大牢中的小丑一伙。在此之后，小丑等人在各地展开一连串的破坏行动，正义的战士一次次勇敢迎战。莱克斯与超人之间的战争全面拉开序幕……©豆瓣', '罗伯·鲍森', 'Jon Burton', 7.9, 10245, 'tt2465238', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1929254480.jpg', 0.5, 2.2, 26.3, 45.5, 25.5, '-0.307524,-0.180837,-0.298859,0.220481,-0.053293,0.031600,0.428996,-0.008188,-0.138493,-0.289332,0.537626,0.642594,-0.197790,-0.350856,0.460169,-0.381181,-0.498191,-0.842142,-0.185057,0.246719,-0.041513,-0.260655,-0.042202,-0.361799,0.370494,-0.309109,0.784837,0.089966,-0.229804,0.575846,0.603309,0.087417,-0.446270,0.156141,0.075518,-0.253935,0.444764,-0.286876,-0.409717,0.312681,-0.388348,-0.072051,-0.220524,0.104207,-0.019329,0.170148,0.631698,-0.428673,0.244001,-0.283617,0.340117,-0.706306,-0.015697,0.025625,0.210355,0.137200,0.069082,0.145692,0.160640,-0.038192,-0.083938,-0.444303,-0.741954,0.093825,-0.021554,-0.008325,-0.287681,0.467890,0.016027,0.484911,0.472514,-0.065513,0.246637,0.162492,0.536121,0.263742,0.044839,0.133884,-0.484138,0.196396,0.529552,-0.243014,-0.119130,-0.156843,0.261855,-0.204651,0.111100,-0.365747,-0.424498,-0.233017,0.392530,-0.197916,0.057187,0.347443,-0.505446,-0.173083,-0.250284,-0.000080,0.169363,-0.360718,-0.026874,-1.146419,0.036477,0.259522,0.198646,-0.128669,0.001209,-0.255821,0.500227,-0.706788,0.181679,0.605803,0.079296,-0.212278,0.214002,0.185890,0.226654,-0.192096,-0.263054,-0.047847,0.298280,0.340617,-0.056251,0.014242,-0.157890,-0.310995,-0.341997,0.111000', '2369613', '25723905', '20274039', '4014397')