INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21349338', '爱与怪物', '喜剧', '故事的背景设定在一个大部分人类已经死亡的末日世界中，主宰着这个世界里的生杀大权的，是那些变异了的冷血动物。仅剩的人类为了求生被迫迁入地下堡垒中，终日生活在胆战心惊里。乔伊（迪伦·奥布莱恩 Dylan O''Brien 饰）在七年前的大灾难里同女友艾米（杰西卡·亨维克 Jessica Henwick 饰）走散，如今他们身居两个不同的地堡中，靠着无线电联系。一天，无比思念艾米的乔伊决定踏出安全区，重返地上世界，独自徒步前往艾米所在的营地，一路上他遇见了无数的危险，同时也遇见了良师益友克莱德（迈克尔·鲁克 Michael Rooker 饰）和米诺（阿丽亚娜·格林布拉特 Ariana Greenblatt 饰）。性格懦弱胆小的乔伊能够活着见到艾米吗？©豆瓣', '迪伦·奥布莱恩', '迈克尔·马修斯', 7.2, 33927, 'tt2222042', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2640310332.jpg', 1.1, 5.2, 39.4, 41.2, 13.1, '0.300883,0.289542,-0.848069,0.482503,-0.148505,-0.254317,0.758520,-0.151099,-0.607894,-0.284977,0.137311,0.868416,-0.074699,0.309359,0.236993,-0.088933,-0.414582,-0.516064,-0.395574,-0.504011,-0.357865,-0.515329,-0.674355,-0.236191,-0.246210,-0.291746,0.600259,0.041381,-0.003897,0.377530,0.116531,0.259171,-0.312898,0.268009,-0.293556,-0.088597,0.313275,-0.136944,-0.404097,0.253796,-0.231914,0.209375,0.036107,0.364757,-0.014637,0.162963,0.644573,-0.745137,0.209236,-0.376960,0.096821,-0.065372,-0.161618,0.025507,0.442654,-0.230699,0.291686,0.202320,-0.073579,0.303965,0.101967,-0.007386,-0.639160,-0.194751,-0.034824,0.417343,-0.557962,0.190199,0.117495,-0.076160,0.163862,-0.223859,0.324972,0.206496,0.323576,0.536751,-0.151608,-0.062794,-0.427139,-0.236574,0.609047,-0.097095,-0.353242,0.215121,-0.168479,-0.268656,-0.169279,0.009560,-0.862315,-0.181636,0.130799,-0.068384,-0.170527,0.534515,-0.870759,0.304957,-0.252129,-0.048721,-0.271897,-0.121182,-0.213251,-0.743864,0.058264,-0.379013,-0.173532,0.093179,-0.224594,-0.154601,0.481734,-0.579645,0.440060,0.305686,0.454670,-0.134544,0.536897,0.047490,0.368979,-0.248177,0.140757,0.780716,-0.062553,0.277262,-0.181297,0.192343,-0.134341,-0.136293,-0.619516,0.761464', '35161768', '1419992', '34461680', '3878007');
