INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21349345', '移动迷宫', '动作', '男孩托马斯（迪伦·欧布莱恩 Dylan O''Brien 饰）在电梯中醒来，奇怪的是他除了名字之外什么都记不得。当电梯打开，他来到了一个陌生的地方“林间空地”。这里四周被高大的石头墙包围着，墙内住着许多男孩，有纽特（托马斯·桑斯特 Thomas Sangster 饰）、查克（布雷克·库珀 Blake Cooper 饰）、米诺（李基弘 Ki Hong Lee 饰）等人，他们都被困在迷宫里，而墙外还有一群巨大的怪兽威胁着。一天，电梯为他们送来了一个女孩特雷莎（卡雅·斯考达里奥 Kaya Scodelario 饰），她是来这里的第一个女孩。此后，迷宫逐渐开始发生变化，一切都陷入了混乱中，托马斯和特雷莎决定一起走上破解迷宫之路，找出迷宫背后令人不寒而栗的秘密。影片改编自詹姆斯·达什纳撰写的同名反乌托邦科幻小说三部曲的第一本。©豆瓣', '迪伦·奥布莱恩', '韦斯·鲍尔', 7.1, 204619, 'tt1790864', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2201485029.jpg', 1, 6.3, 42.5, 38.7, 11.5, '0.341500,-0.088289,-0.731039,0.516377,-0.039470,-0.175455,1.156542,0.080937,-0.430552,-0.254420,0.109913,0.551598,-0.338309,0.264748,0.138550,0.319624,-0.555220,-0.534086,-0.268838,-0.443769,-0.549091,-0.389708,-0.393620,-0.376211,0.021579,-0.213712,0.299539,0.326265,0.031535,0.186971,0.272256,0.106647,-0.313673,0.299247,0.009167,0.309837,0.342177,-0.318840,0.065118,0.085954,-0.330127,-0.081962,-0.346912,0.323945,-0.147752,0.247027,0.552525,-0.429648,0.191485,0.041544,0.191855,-0.048758,-0.016229,-0.118697,0.366668,-0.075461,0.195461,0.041730,-0.157798,0.161033,0.134443,-0.103562,-0.214954,0.171498,-0.074570,0.351052,-0.453455,0.025081,-0.043804,-0.073468,0.122006,-0.443629,0.155393,-0.099300,0.415841,0.340564,-0.124774,-0.101870,-0.631580,-0.189448,0.283103,0.057783,-0.323974,0.065308,-0.225376,-0.356501,-0.156731,0.299205,-0.464584,-0.215129,0.506664,-0.031175,-0.037349,-0.108880,-0.431735,0.141825,-0.162094,-0.136342,-0.372079,-0.308557,-0.291739,-0.716283,0.035007,0.089132,-0.059399,0.201839,-0.349994,-0.059223,0.353181,-0.231467,0.473198,0.577533,0.231955,0.054311,0.691539,-0.297538,0.183300,-0.019758,0.061897,0.338396,0.093782,0.338038,0.049833,0.505465,-0.059188,-0.003138,-0.660646,0.686915', '20451118', '1316693', '1302133', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21349734', '博物馆奇妙夜3', '喜剧', '纽约自然博物馆重新开张，小保安赖瑞·戴利（本·斯蒂勒 Ben Stiller 饰）带领泰迪·罗斯福（罗宾·威廉姆斯 Robin Williams 饰）策划了精彩的开幕演出。谁知演出刚刚没多久，泰迪、猴子他们便陷入混乱，所有博物馆的伙伴们大闹会场，赖瑞为此焦头烂额。事后他 发现，复活黄金碑正被绿色的物质腐蚀，而这种情况似乎导致了藏品们的疯狂。赖瑞查找资料，断定黄金碑背后隐藏着不为人知的秘密。为了阻止混乱情况的蔓延，他决定前往大英博物馆求助法老王阿卡曼拉的父亲，当然那堆搞怪的藏品也都尾随而至。途中他们遇见了圆桌骑士兰斯洛特爵士，还和屋大维等伙伴走散。久违的奇妙冒险，就在夜幕下的大英博物馆的展开……©豆瓣', '本·斯蒂勒', '肖恩·利维', 7.3, 161881, 'tt2692250', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2219665256.jpg', 0.6, 4.4, 40.9, 39.9, 14.2, '0.236197,-0.003900,-0.761374,0.237785,0.151582,-0.198884,0.587926,0.208016,-0.277406,-0.244567,0.563667,0.473715,-0.298967,0.174362,0.287979,-0.026651,-0.726969,-0.635558,0.051264,-0.021688,-0.350404,-0.176629,-0.283058,-0.466702,0.008047,-0.301886,0.432211,0.176581,-0.165278,0.470573,0.194355,0.255603,-0.325160,0.312735,0.162028,0.018509,0.267970,0.066988,-0.251318,0.008571,-0.155749,-0.226270,-0.240848,0.110241,0.353902,0.224228,0.715730,-0.401611,0.015455,-0.000251,0.151399,-0.306267,0.024980,0.198331,0.293387,0.106428,-0.000057,-0.014869,-0.266314,0.014731,0.005006,0.046440,-0.410721,0.149347,-0.101910,0.139853,-0.279962,0.027190,0.088794,0.032501,0.191432,-0.338686,0.160078,0.362241,0.131118,0.094494,0.017201,-0.034335,-0.398962,0.138474,0.381186,-0.255081,0.013473,0.074157,-0.082060,-0.455239,-0.035040,0.017809,-0.113871,-0.080232,0.568641,0.030988,0.082854,0.222620,-0.658993,-0.173574,-0.246862,-0.377450,-0.120205,-0.253547,-0.092707,-1.012730,-0.155785,0.194041,-0.005802,-0.070260,-0.036204,0.066891,0.452694,-0.228314,0.427206,0.502062,0.072681,-0.293446,0.356146,-0.302705,0.081425,-0.066023,-0.232767,0.075845,0.264589,0.460520,0.296418,0.170719,0.063671,-0.189530,-0.290414,0.367628', '2159244', '2075345', '6517421', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21350556', '三少爷的剑', '剧情', '“剑气纵横三万里，一剑光寒十九洲”，神剑山庄三少爷谢晓峰（林更新 饰）惊才绝艳，十年来历经上千大战未尝一败，被天下人尊为“剑神”。传奇剑客燕十三（何润东 饰）一直以谢晓峰为目标，苦修剑道，终于在生死边缘悟出惊天地泣鬼神的“绝命十三剑”。一时之间，江湖沸腾，然而，就在燕十三赶到神剑山庄下战书的时候，迎接他的，却是三少爷谢晓峰的灵柩。燕十三因痛失对手大感失望，此时神秘女子慕容秋荻（江一燕 饰）出现并告知燕十三，谢晓峰并没有死，要想找到他决战，燕十三就必须要替她杀一个人……', '林更新', '尔冬升', 4.8, 79909, 'tt5269396', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2399366116.jpg', 18.6, 36.9, 32.5, 9, 3, '-0.525505,0.272647,-0.383356,0.622322,0.306957,-0.298572,0.278897,-0.242943,-0.196446,-0.779557,0.266791,0.402043,-0.202036,0.280163,0.298460,-0.232914,0.933867,-0.783865,-0.403726,-0.070754,-0.270362,0.005187,0.278650,0.071669,0.019642,0.120471,0.365147,0.467427,-0.142800,0.266855,0.309444,0.249699,-0.310502,0.356202,-0.408785,-0.004658,-0.416449,0.063783,-0.300372,0.292699,-0.446028,-0.372019,-0.361628,0.770791,0.122923,0.127319,0.493089,-0.113383,0.208406,-0.030065,-0.224222,0.294165,-0.190110,-0.125417,0.379045,-0.509389,0.083622,0.418749,0.139264,-0.062319,-0.328619,-0.265813,-0.746322,0.373095,0.019221,-0.259805,-0.504368,0.318238,-0.551002,0.100063,-0.392298,-0.030321,0.092729,0.243681,0.210445,-0.250731,-0.139837,-0.351504,-0.349392,0.340647,0.654779,0.050741,0.087679,-0.165657,0.696412,-0.146953,-0.404783,-0.414075,0.133551,0.045377,0.537916,0.096626,0.220894,0.400019,-0.255081,-0.132257,-0.380251,0.178491,-0.079709,-0.136534,-0.004721,-0.104456,0.201196,-0.133415,-0.304952,0.109837,0.176426,-0.312772,0.449518,-0.725776,0.459597,-0.363945,-0.123174,-0.665565,0.425521,0.234735,-0.258210,-0.368636,-0.152779,0.436953,0.131094,0.194493,0.245622,0.107295,-0.310840,-0.191479,-0.469728,0.180866', '1438924', '3670447', '1877596', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21350559', '盒子怪', '喜剧', '《盒子怪》根据阿兰·斯诺（Alan Snow）的小说《这里有怪兽》（Here Be Monsters）改编，是一个幽默的寓言故事。“奶酪桥”（Cheesebridge）是维多利亚时期一个光鲜亮丽的城市，这里的居民痴迷于财富、等级，还有臭奶酪！然而在他们别致的鹅卵石道路之下住着一群“可怕”的怪物，他们每天晚上都会从下水道爬出来，偷走居民家中的孩子和奶酪——当然，这只是当地居民的一面之词！事实上“盒子怪”是一群非常可爱害羞的生物，他们躲在可回收的纸板箱里，就像乌龟喜欢缩在自己的壳里一样。盒子怪们收养了一个人类孤儿，给他起名“蛋生”（Eggs），这个小男孩和一个爱冒险的地上世界的女孩温妮（Winnie）成为了好朋友，他们需要在盒子怪与人类之间架起一座桥梁——尤其是当人类政客为了选票而把盒子怪们描绘成一群可怕怪物，进而煽动民众驱逐他们的时候……《盒子怪》是LAIKA公司继《卡罗兰》（Coraline）、《超凡的诺曼》（ParaNorman）之后的第三部动画片，由动画片《狩猎季节》（Open Season）导演Anthony Stacchi和《卡罗兰》、《超凡的诺曼》的故事艺术家Graham Annable共同执导。影片配音阵容强大，包括了本·金斯利（Ben Kingsley）、艾丽·范宁（Elle Fanning）、西蒙·佩吉（Simon Pegg）、尼克·弗罗斯特（Nick Frost）等', '本·金斯利', '格雷厄姆·安纳布尔', 7.8, 27790, 'tt0787474', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195254744.jpg', 0.3, 1.9, 26.5, 49.6, 21.8, '0.435390,-0.164192,-0.507991,0.539772,-0.235670,0.054033,0.920441,0.169784,-0.460677,0.009540,0.192410,0.943065,-0.052472,0.118817,-0.088750,0.178284,-0.220133,-0.382541,-0.313389,-0.237417,-0.285781,-0.271234,-0.469680,-0.440071,0.024200,-0.456635,0.600039,-0.016480,-0.199387,0.119826,0.258713,0.074057,-0.241077,0.092381,-0.176233,0.024808,0.116298,-0.095488,-0.056299,0.047322,-0.360482,0.178826,0.012124,0.087924,0.066022,0.014460,0.648562,-0.402418,-0.109123,-0.222743,0.342714,-0.197661,-0.155474,-0.165008,0.389434,-0.277816,0.330749,-0.147461,0.154706,0.086494,0.386402,-0.176999,-0.755739,-0.164200,0.080549,0.223158,-0.600550,0.436231,0.121283,0.036921,0.241669,-0.298915,0.189628,-0.024337,0.278471,0.416468,0.114873,-0.007836,-0.701063,0.178824,0.147083,0.018923,-0.354792,0.290959,-0.370630,-0.489257,-0.092093,-0.239952,-0.640415,0.019698,0.330105,-0.273854,-0.545216,0.118328,-0.818160,0.000772,0.003316,-0.214226,0.205670,-0.431510,-0.316595,-0.409345,0.022670,-0.414812,-0.149597,-0.174099,-0.1