INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21350962', '代号47', '动作', '影片根据同名游戏改编，“代号47”（鲁伯特·弗兰德 Rupert Friend 饰）是神秘杀手组织的头号杀手，他性格冷静，智慧过人，行动神秘低调，从来没人知道他的底细，只靠颈后位置的一个纹身条码辨认身份。“代号47”既是罪恶的化身，又是善意的使徒。他从不过问犯罪的真理 及意义，直到碰上一名惊为天人神祕女子卡蒂娅（汉娜·韦尔 Hannah Ware 饰），改写了他的命运，更使他遭到杀手组织的追杀，生命危在旦夕……', '鲁伯特·弗兰德', '亚历山大·巴赫', 6.2, 26886, 'tt2679042', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2252051573.jpg', 3.4, 17.6, 51, 20.7, 7.3, '-0.044153,0.273270,-0.343126,0.652080,-0.612886,0.203153,0.562159,-0.041554,-0.569683,-0.248987,0.488179,0.718933,0.108297,-0.196758,0.280615,0.292114,-0.187173,-0.621969,0.297812,-0.215938,-0.300056,-0.298903,-0.274087,-0.484614,0.283866,-0.522656,0.588130,-0.030504,-0.439979,-0.063312,0.426403,0.317667,-0.200760,0.272169,-0.242161,-0.186448,0.078987,-0.111730,0.013504,0.090163,-0.455461,-0.265672,-0.264356,0.312344,-0.456755,0.598791,0.567848,-0.461877,-0.245221,-0.308598,0.356018,-0.441639,-0.142659,-0.162071,0.546136,-0.122421,0.058552,0.340586,0.322578,-0.099305,-0.003526,0.123340,-1.170279,-0.067697,0.203634,0.389065,-0.411608,0.217663,-0.567899,-0.149789,-0.165908,-0.101007,0.046527,-0.017349,0.482645,-0.051846,0.259656,-0.073741,-0.248074,0.226453,0.493239,0.067912,-0.407216,0.462853,-0.248202,-0.762941,-0.415743,-0.339942,-0.076674,0.079928,0.272125,-0.001139,-0.167563,0.084077,-0.635556,-0.165048,-0.254756,0.082945,-0.177103,-0.612862,0.003843,-0.406413,-0.425308,-0.304192,-0.318937,-0.016897,0.100724,-0.155500,0.698419,-0.910479,-0.051880,0.749122,0.194950,-0.542738,0.591120,0.219380,-0.317172,-0.614667,-0.042719,0.573972,0.454964,-0.009896,-0.179516,0.230166,0.050011,-0.090133,-0.095686,0.411314', '1793491', '27009869', '25932086', '1294893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21352814', '归来', '剧情', '上世纪70年代初，与家人音讯全无隔绝多年的劳改犯陆焉识（陈道明 饰）在一次农场转迁途中逃跑回家。这对怀抱芭蕾舞梦想的女儿丹丹（张慧雯 饰）带来了巨大压力，她阻止母亲冯婉瑜（巩俐 饰）与父亲的相见。因此夫妻二人近在咫尺却又相隔天涯。文革结束后，陆焉识终于平反回家，但是他却发现女儿早已放弃了芭蕾的梦想成了一名工厂女工，而深爱的妻子因为患病已经不认识自己。深厚的感情、生活的变故，迫使陆焉识做出了对他来说最荒唐却又最合理的人生选择……本片是张艺谋导演加盟乐视影业后的第一部作品，被编剧邹静之誉为苦心之作。©豆瓣', '陈道明', '张艺谋', 8, 343911, 'tt3125472', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2181207835.jpg', 0.4, 2, 21, 48.5, 28, '-0.098486,0.017901,-0.700354,0.659957,0.226185,-0.529227,0.770189,0.131305,-0.478038,-0.379980,0.258604,0.882754,-0.021725,0.210309,0.213680,0.006058,-0.149013,-0.678691,0.083857,-0.176219,-0.087720,-0.199264,-0.153190,0.141332,-0.261455,-0.223628,0.947112,0.036820,-0.144372,0.430359,0.347948,0.039662,0.053069,0.496190,-0.002872,0.272739,0.167030,0.341388,-0.644242,0.041732,0.017014,-0.246099,-0.123987,0.232774,-0.399483,0.280712,0.551792,-0.097939,-0.299993,-0.238759,0.522191,-0.379396,-0.093143,-0.040509,0.158309,0.045090,0.425047,0.358385,-0.209243,-0.023597,-0.079617,-0.159225,-0.573335,0.192405,0.266199,-0.081359,-0.715419,0.532496,-0.180796,-0.047323,-0.099633,-0.576480,0.137330,0.272490,0.422165,0.433585,-0.466335,0.159484,-0.314630,0.472523,0.801747,-0.131790,-0.257130,0.753226,-0.202612,-0.341202,0.068308,-0.336312,-0.629452,-0.018440,0.037479,0.184799,-0.274712,0.167476,-0.406305,-0.017518,-0.351475,0.088071,0.244140,-0.546280,0.136494,-0.341031,-0.391606,-0.419352,-0.451602,-0.068663,0.097524,-0.469829,0.752444,-0.681975,0.194454,0.419947,0.328091,-0.548413,0.800244,0.210312,0.093487,-0.307322,0.217512,0.447547,-0.325812,0.198263,-0.077517,0.087839,0.013034,-0.153181,-0.299731,0.551832', '35287908', '1456503', '1296569', '1303034');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21354060', '那夜凌晨，我坐上了旺角开往大埔的红VAN', '悬疑', '小职员阿池（黄又南 饰）于凌晨坐上了一辆由九龙旺角开网新界大埔的红色小巴士，车上有司机肥雪（林雪 饰）、义气大叔黄万发（任达华 饰）、神婆（惠英红 饰）、IT男阿信（徐天佑 饰）以及美女Yuki（文咏珊 饰）、吸毒佬（李灿森 饰）等17人。原本平静的夜晚，在小巴穿过狮子山隧道后突然被打破，众人发现除了车上的乘客，全香港的居民仿佛都消失了，一系列的神秘事件接踵而至，大家惊恐之余决定打造统一阵线，以解救自己开启谜团。©豆瓣', '任达华', '陈果', 5.9, 21744, 'tt3504824', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2174742288.jpg', 7.8, 22.4, 43.1, 20.4, 6.2, '0.083256,0.092158,-0.397032,0.176186,0.277380,-0.204888,0.542914,0.251515,-0.557365,-0.215947,0.333388,0.260791,-0.379556,0.167493,0.454276,-0.132623,-0.609081,-0.342629,-0.100857,-0.154697,-0.295732,-0.146058,-0.122330,-0.129215,-0.018258,0.028643,0.393078,0.289303,0.119292,0.365259,0.566153,0.092094,-0.370659,0.331314,0.028154,0.073017,-0.018353,-0.135149,-0.121171,-0.302013,-0.309345,-0.464561,0.130675,-0.132555,0.128973,0.326469,0.726976,-0.399665,-0.127577,0.002982,0.305365,-0.138576,-0.070505,-0.166451,0.066067,0.340825,0.306181,-0.071261,-0.190872,0.040390,0.455007,0.206520,0.222621,0.278850,-0.002056,0.079410,-0.218875,0.134684,-0.128089,-0.052632,0.170244,-0.594556,0.320581,-0.103223,0.213220,0.199542,0.036460,0.107757,-0.363082,0.293195,0.291833,0.059188,-0.076082,0.126275,0.079823,-0.465275,-0.073867,0.056591,-0.162600,-0.150287,0.615088,-0.142113,0.284660,-0.058156,-0.611910,-0.234321,-0.046569,-0.256581,-0.187818,0.211572,-0.275237,-0.707406,0.292943,-0.205817,0.276321,0.395257,-0.090981,0.260699,0.541405,-0.549712,0.261995,-0.154217,0.300341,-0.202008,0.422920,-0.499398,0.197346,-0.288405,-0.174610,-0.015083,-0.006540,0.617047,0.098859,0.350715,-0.594640,-0.185539,-0.174060,0.020492', '2159244', '4706257', '35206186', '21349734');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21354076', '变态假面', '喜剧', '抖S和抖M之子色丞狂介（铃木亮平 饰）貌似没有继承搜查一课魔鬼刑警老爹的基因，虽然长着一副凶狠的面孔，可是为人懦弱胆小，即使加入拳法部之后也没有丝毫改观。某天，美丽可爱的转学生姬野爱子（清水富美加 饰）来到狂介的班上，令这个大男孩体会到前所未有的心跳感觉。放学回家路上，一群匪徒闯入银行劫持人质，人质中更有狂介心仪的爱子。为了救出女孩，他悄悄潜入银行，谁知偶然戴上胖次之后，竟然意外唤醒体内潜藏的强大力量。在此之后，他化身变态假面，以压倒性的实力击败匪徒，也令爱子对变态假面产生倾慕之情。某天，意欲统治周边学校的恶汉大金玉男入侵学校，由此拉开了和变态假面旷日持久的战争……本片根据安土庆周的同名漫画原作改编。©豆瓣', '铃木亮平', '福田雄一', 6.2, 15103, 'tt2708764', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2006591146.jpg', 6.2, 17.2, 46.4, 20.4, 9.8, '-0.087874,-0.033274,-0.344693,0.440279,-0.239672,-0.068849,0.601078,0.090228,-0.372010,-0.375667,0.290714,0.514177,-0.273654,0.021706,0.193152,0.000140,-0.132908,-0.545736,-0.310649,-0.007107,-0.174658,-0.164571,-0.505004,-0.072748,0.120829,-0.490438,0.617932,0.120877,-0.630176,0.555680,0.310564,0.128754,-0.087600,0.207471,-0.090789,-0.081931,-0.000386,0.108376,0.079738,0.160031,-0.142586,-0.004567,-0.110405,0.227515,-0.243516,0.232228,0.680715,-0.334272,-0.265693,-0.250241,0.473403,-0.092191,-0.407631,0.150856,0.392916,0.136777,0.203381,-0.052411,-0.000389,0.022934,0.083432,0.015627,-0.708326,0.121841,0.046330,-0.052811,-0.139996,0.259950,-0.044450,0.003047,0.374262,-0.200473,-0.066434,0.146837,0.243798,0.331448,-0.090432,0.181430,-0.167348,-0.048582,0.419706,-0.158939,-0.372757,0.144840,-0.132245,-0.339746,-0.038217,-0.399512,-0.140428,0.092587,0.075292,0.174028,-0.092400,0.268575,-0.474645,-0.187721,-0.344471,0.264498,0.063750,-0.123055,-0.334450,-0.515867,-0.370233,-0.209471,-0.076641,0.117161,0.175498,-0.207858,0.807430,-0.851965,0.041627,0.434470,0.311722,-0.460254,0.384626,-0.036237,-0.414513,-0.234886,-0.425233,0.252219,0.236956,0.345984,0.024814,0.296064,-0.433673,-0.272070,-0.147300,0.283462', '24284209', '27602116', '3811356', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21354138', '末日哲学家', '剧情', '毕业前的最后一堂哲学课，20名学生被逼参与思想实验。他们由班房跳进核辐射浩劫现场，若未能在防空洞争一席位，器官将瞬即被辐射尘贯穿，痛苦致死。然而，防空洞内的氧气及食物只够10人存活一年。哲学生以抽签决定身份和技能。为延续人类命脉，他们需运用哲学逻辑，公开咨询并举手投票，选出10位最有价值的人物住进防空洞。聪明人比好人有资格留低？工程师的价值比诗人重要？一票延续一命，要牺牲谁去成就社会？', '詹姆斯·达西', '约翰·赫德斯', 6.1, 7354, 'tt1928340', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2120018409.jpg', 7.5, 18.9, 43.4, 21.9, 8.3, '-0.287782,0.130240,-0.281807,0.253131,-0.234456,0.093665,0.165957,-0.024986,-0.404558,-0.347434,0.164759,0.352964,0.075338,-0.220838,0.024761,-0.717568,-0.216337,-0.325892,0.157132,-0.375559,-0.669175,-0.542645,0.169107,-0.165912,-0.107856,-0.479672,0.834804,0.171741,-0.111204,-0.197898,0.045274,0.146609,0.084856,0.067887,-0.173436,-0.439815,0.101313,-0.044185,-0.519185,0.285690,-0.287951,-0.036122,-0.013445,-0.073006,0.041021,0.097393,0.608431,-0.050920,-0.008047,-0.374284,0.323013,-0.133232,-0.163850,0.313191,0.386409,0.175043,0.258292,0.678868,0.247448,0.125000,0.171263,-0.293514,-0.903218,-0.237329,0.224839,-0.065580,-0.353949,0.524112,-0.100273,-0.075637,-0.262918,0.162789,0.048744,0.088634,0.351296,0.197753,-0.183356,-0.073455,-0.415088,0.122565,0.424133,-0.525300,-0.177730,0.324893,-0.211193,-0.775684,0.091466,-0.659392,0.155728,0.042894,-0.058773,0.196568,-0.222699,0.077658,-0.338583,0.028603,0.099260,-0.187435,0.203982,-0.358769,-0.006452,-0.356732,0.004621,0.346445,-0.019614,0.026914,0.269467,-0.418251,1.066379,-0.323848,-0.196742,0.393979,0.406631,-0.673633,0.910015,0.040785,0.272287,-0.405923,0.005163,0.142491,0.197661,0.332463,-0.151868,0.024026,-0.065858,-0.201672,-0.156561,0.278423', '27602116', '24284209', '3718665', '1292444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21354767', '伯纳黛特你去了哪', '剧情', '伯纳黛特（凯特·布兰切特 Cate Blanchett 饰）和丈夫埃尔金（比利·克鲁德普 Billy Crudup 饰）结婚多年，两人共同抚养可爱的小女儿阿比（艾玛·尼尔森 Emma Nelson 饰），一家三口是别人眼里的模范家庭。这么多年来，伯纳黛特全身心的投入到了家庭的建设中去，无条件的牺牲自己，支持着丈夫的每一个选择。最近，伯纳黛特被严重的失眠和强烈的焦虑困扰，越来越不愿意出门接触外人，将自己封闭在家里的四面墙壁内，就连丈夫和女儿也无法接近她的内心。因为伯纳黛特忽然意识到，自己的世界除了她的家人们以外，几乎一无所有。在一家人决定举家前往南极旅游的这个节骨眼上，伯纳黛特失踪了。©豆瓣', '凯特·布兰切特', '理查德·林克莱特', 7.6, 20404, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2555983860.jpg', 0.6, 3.1, 31.5, 45.7, 19.1, '0.301675,-0.129689,-1.109550,0.515832,-0.341038,-0.341456,0.593500,0.286689,-0.616646,-0.269923,-0.175411,1.118275,-0.077900,0.520071,0.255922,0.304316,-0.050840,-0.666864,-0.140163,-0.079033,-0.272619,-0.643899,-0.187592,-0.496912,-0.218326,-0.288159,0.306298,0.104652,-0.045782,0.187822,0.325354,0.358723,0.023270,0.527639,-0.010277,0.271656,0.087573,-0.000235,-0.051679,0.066453,0.025420,0.213493,0.008860,0.205099,0.388059,0.340188,0.480640,-0.138887,0.019229,-0.042897,0.267229,0.022684,0.032903,0.379613,0.353221,-0.430689,0.253839,0.286482,-0.341997,-0.070923,0.170855,-0.320645,-0.730460,0.111766,0.093817,0.016240,-0.949416,0.499138,-0.099911,-0.285457,0.014865,-0.572487,0.251935,0.565682,-0.116172,0.350412,-0.478551,-0.108300,-0.250855,0.262368,0.668036,0.047127,-0.201288,0.124849,-0.271299,-0.097160,-0.152456,-0.421962,-0.778185,-0.143110,0.128582,0.193265,-0.069590,0.316668,-0.458047,-0.059965,-0.335802,-0.066792,0.260038,-0.442605,0.003763,-0.573079,-0.113139,-0.544750,-0.283549,0.115211,0.026807,-0.391841,0.618298,-0.642509,0.226728,0.587866,0.434341,-0.538693,0.810148,0.201762,0.409211,-0.233034,-0.029247,0.387422,0.084723,0.242769,0.286849,0.250120,-0.062456,0.184028,-0.238239,0.665233', '1292207', '35461732', '1309069', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21355933', '金太狼的幸福生活', '喜剧', '金太狼（王雷 饰）拥有一份令全天下男人羡慕嫉妒恨的职业，他是一名妇科医生，每天的工作就是，穿行俯身于各色妙龄、大龄女子张开的大腿之间。然而闷骚男金太狼却渴望拥有一份属于自己的爱情，过上幸福的生活。此时，三个性情各异的姑娘闯入了他的世界——青春靓丽文艺女青年颜子淳（潘之琳 饰）、外冷内热“女王”上司杨晓梅（姚芊羽 饰）、青梅竹马屌丝妹妹小青（李小萌 饰），她们分别渴望得到他的身体、内心和生命之源。于是，直率闷骚男金太狼和姑娘们之间充满了尴尬趣事，往往把姑娘不经意的一句话误会成挑逗性暗示，引得他主动宽衣解带、投怀送抱，却连番惨遭碰壁。在阴错阳差之下他经历了捐精、被保安追打、被潜规则一夜情，甚至献身当裸模……在这三个女孩的轮番轰炸下，金太狼跌跌撞撞地寻找着属于他的爱情和幸福……©豆瓣', '王雷', '李爽', 6.3, 7529, 'tt17492844', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1897392533.jpg', 4.5, 16.3, 49.3, 21.9, 8.1, '0.246700,0.143233,-0.501755,0.562635,-0.221854,0.042865,0.826514,-0.017047,-0.365851,0.061239,0.211580,0.400395,-0.410247,0.371706,0.341473,0.038651,0.126329,-0.573088,-0.184965,0.116678,0.019907,-0.085753,-0.247922,-0.007792,-0.267492,-0.421538,0.638208,-0.165670,-0.185322,0.395116,0.605985,0.276412,-0.173279,0.329208,-0.211588,0.095211,0.092171,-0.022326,-0.267778,0.006122,-0.102099,-0.172901,-0.014094,0.058100,-0.438747,0.007821,0.717803,-0.176803,-0.111183,-0.170286,0.500025,-0.100704,-0.088501,0.314737,0.051693,0.080730,0.354783,-0.002924,0.007572,-0.095832,0.402489,0.075408,-0.536998,0.072655,0.100199,0.153890,-0.494518,0.388815,0.015779,-0.209671,0.149964,-0.219420,0.077213,-0.128286,0.241090,0.295370,-0.136430,0.138708,-0.254911,0.312535,0.650023,0.286930,-0.109567,0.378323,-0.432046,-0.284485,0.214075,-0.125031,-0.845792,-0.077800,0.087318,-0.026385,-0.033947,0.172405,-0.627200,0.139159,-0.020139,0.089707,0.068672,-0.637376,-0.252954,-0.155705,-0.292782,-0.499847,-0.405802,0.221293,0.207075,-0.222457,0.896306,-0.856849,0.067843,0.476225,0.385449,-0.584246,0.680912,0.267660,-0.076439,-0.287287,-0.195385,0.464481,-0.153724,-0.130486,0.081274,0.480450,-0.528045,0.332305,-0.271732,0.425664', '6963575', '3445516', '26348103', '4817024');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21357362', '止杀令', '剧情', '横扫中亚、西亚，跃马欧洲的成吉思汗（涂们 饰）62岁了。面对瘟疫肆虐，勇战沙场的蒙古将士不断倒下，杀人如麻的他，突感死亡的临近。如同历代帝王一样梦想长生不老之术。长春真人丘处机（赵有亮 饰）被传说300岁，懂生死，通晓治国治民之道深居于文登昆嵛山中。金和宋的皇帝曾派人 来请，均遭拒绝。成吉思汗闻知定要会他，命刘仲禄（耿乐 饰）不远万里一定要带回丘处机。丘处机算出这一行自己将有去无回，但为了天下百姓免遭战乱之苦，丘处机带着一口棺材，毅然上路。而他的爱徒赵道安（余少群 饰），不愿师父一人前往西域受苦，甘愿一路随行。途中，一心想找成吉思汗报杀夫之仇的契丹女（李小冉 饰），三次变换身份，希望打动丘处机，带她一同前往西域。一行人历经生死险阻，终于到达八鲁湾与成吉思汗相见。成吉思汗向丘处机索要长生不老之药，丘处机却直言“只有卫生之道，而无长生之药”。经过几番波澜不惊的心战，让成吉思汗明白了“天道喜善恶杀，珍惜别人的生命就是延长自己的生命”的道理。并教授蒙古将士们沐浴卫生，使瘟疫锐减。顿悟后的成吉思汗停止了征伐的脚步，班师东归。封丘处机为大国师。', '赵有亮', '王坪', 5.5, 4524, 'tt3176304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1884684938.jpg', 11.4, 30.7, 37.3, 14.5, 6.1, '-0.173309,0.112221,-0.456468,0.515554,0.024897,-0.186505,0.335364,-0.075484,-0.462714,-0.246460,0.171300,0.624756,0.051796,-0.102581,0.074719,0.009046,0.081587,-0.511541,-0.221994,-0.213058,-0.027893,-0.133358,0.068898,-0.107206,-0.247909,-0.354157,0.298825,0.271716,0.048020,0.589681,-0.007384,0.041938,-0.057857,0.385640,-0.247416,0.104721,-0.325974,-0.180972,-0.359168,0.186589,-0.040049,-0.350573,-0.403225,0.132744,-0.504184,0.288419,0.319283,-0.306737,0.083125,-0.225736,0.081322,-0.265595,0.069085,0.145105,-0.014242,0.190449,0.104682,0.349992,0.156733,0.085627,-0.167098,0.048115,-0.372697,-0.093674,0.062274,-0.042546,-0.458434,0.367240,-0.080822,-0.131691,-0.076633,-0.315076,0.123802,0.456671,0.347505,0.174936,-0.085543,-0.299379,-0.495600,0.280639,0.708317,-0.362995,0.120979,0.013368,-0.035195,-0.392922,0.608691,-0.359020,-0.272007,0.009400,0.364635,-0.094848,0.123030,0.182778,-0.146788,-0.124695,-0.407772,-0.008638,-0.012324,0.119207,0.065137,-0.204441,0.014970,-0.346182,-0.146602,0.099821,0.411417,-0.100823,0.542124,-0.353801,0.280698,0.378995,0.182504,-0.715262,0.510901,0.066670,-0.004737,-0.046851,-0.034539,0.568279,0.089446,0.567868,-0.006953,-0.027509,-0.109042,0.078496,-0.478274,0.139217', '25721544', '1308035', '3280079', '1304600');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21359619', '单身男女2', '喜剧', '即将和方启宏（吴彦祖 饰）步入婚姻殿堂的程子欣（高圆圆 饰）幸福满满，她偶遇最崇拜的股市女强人杨鸯鸯（杨千嬅 饰），于是自我推荐加入了杨的公司。无巧不成书，张申然（古天乐 饰）的公司刚好在鸯鸯公司的对面，两人之前又因为某次邂逅成为男女朋友。性格大条豪爽的鸯鸯知道申然花心轻浮的行径，却只采取反向操作的措施，一心期望能成为申然最后一个女人。子欣的哥哥程子建（周渝民 饰）浪漫气息浓郁，他偶遇失落中的鸯鸯，神奇的章鱼“灯神”让他们成为好朋友，子建对鸯鸯的好感也与日俱增。终于迎来了申然的生日，谁知派对最终变成了大灾难，混乱中的申然也惊讶地发现子欣就在不远的地方。从未熄灭的爱火再度点燃，三男两女的爱情战争进入了白热化的阶段……©豆瓣', '古天乐', '杜琪峰', 5.5, 103652, 'tt3121474', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209656483.jpg', 11.7, 25.6, 42.6, 14.3, 5.7, '0.293062,0.274888,-0.691503,0.430465,-0.045370,-0.223415,0.810888,0.209918,-0.247398,-0.109511,0.232486,0.569487,-0.378115,0.176613,0.345058,-0.029042,-0.012291,-0.740905,-0.119750,-0.032723,-0.123063,-0.268079,-0.296727,-0.101634,-0.070243,-0.093831,0.686106,0.254550,-0.157750,0.481022,0.485135,0.117217,-0.057056,0.658231,0.017916,-0.062424,0.017858,0.342544,-0.319795,0.077466,-0.218677,-0.114882,0.023205,0.237350,0.007167,0.280751,0.512271,-0.044313,-0.269049,-0.080030,0.487135,-0.191046,-0.166569,0.046919,0.297409,-0.082363,0.326769,-0.102934,-0.145766,-0.155535,-0.031834,-0.120529,-0.606300,0.246432,0.071268,-0.054348,-0.316294,0.550807,0.064804,-0.125538,0.289795,-0.169356,0.070221,0.330264,0.495639,0.365093,-0.268620,0.169986,-0.272354,0.143250,0.563606,0.123266,-0.289830,0.509801,-0.146542,-0.517010,-0.007072,-0.063248,-0.250297,-0.116759,0.268815,0.179725,-0.084995,0.254238,-0.710639,-0.076697,0.018307,0.153199,0.173536,-0.272474,0.043307,-0.581936,-0.174725,-0.308788,-0.259575,0.066054,-0.108553,-0.357776,0.673316,-0.800778,0.177263,0.297393,0.264373,-0.433474,0.679978,0.139519,-0.103273,-0.331384,-0.037424,0.273613,-0.378094,0.022566,0.072989,0.478641,-0.177840,-0.197815,-0.268892,0.460108', '25777330', '34973399', '1308755', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21359690', '熊出没之过年', '剧情', '春节将至，外出工作的人都归心似箭，匆匆赶回家中和亲人团聚。光头强（葛平 配音）因为没钱买回家的车票，只能替李老板（张伟 配音）砍树来赚取路费。熊大（张伟 配音）和熊二（张秉君 配音）得知他们赖以生存的家园又要遭到光头强的破坏，于是组织了一干动物们，在光头强砍树的机器上做了手脚，机器坏了，光头强砍树的计划自然泡了汤。无法砍树，拿不到工钱，这也就意味着光头强可能今年没办法回家过年了。得知此事，熊大和熊二动了恻隐之心，尽管光头强和他们平日里斗智斗勇，是一对冤家，但两头熊还是决定在这个节骨眼上帮助他。它们将坏掉的伐木机改装成为了汽车，打晕了光头强想要送他回家，由此引发了一连串的笑话。©豆瓣', '张秉君', '丁亮', 8.5, 24420, 'tt2943974', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2236922385.jpg', 0.7, 1.1, 12.5, 42, 43.7, '0.220854,0.012410,-0.684879,0.248611,-0.399919,-0.357343,0.361559,0.227315,-0.204933,-0.108204,-0.082163,0.514179,0.174380,0.009118,-0.228469,-0.267837,-0.285982,-0.416367,0.078789,0.024460,-0.520332,-0.303617,-0.063532,-0.307349,-0.017965,0.025673,0.005971,-0.105563,-0.123605,0.361604,0.418746,-0.099666,0.264716,0.397042,-0.362897,0.246357,-0.147677,-0.042672,0.089587,0.262023,0.038263,-0.122510,-0.275967,0.040512,0.372904,0.412299,0.499532,0.288881,-0.418644,-0.142457,0.181648,-0.245964,-0.086812,0.164392,0.372559,0.045233,0.129489,0.058486,-0.166423,0.194565,0.110883,0.008801,-0.793324,0.238191,-0.100314,-0.394234,-0.917521,0.203976,-0.166006,-0.042933,-0.048310,-0.416357,0.298982,0.304052,0.148763,0.480153,0.133483,0.066855,-0.558045,0.361597,0.776309,-0.134348,-0.000267,0.210688,0.163531,-0.230137,-0.183688,-0.401568,-0.299785,-0.190507,0.587655,0.054779,-0.525087,-0.220689,-0.615347,-0.041680,-0.147801,-0.273573,-0.103820,0.053674,-0.043647,-0.450364,0.039714,-0.279750,-0.245123,0.328530,0.205971,-0.082254,0.893888,-0.493224,0.130234,0.640165,0.523387,-0.616202,0.600715,0.028854,0.234739,-0.201861,0.060611,-0.575780,0.097974,0.440284,0.581989,0.305645,-0.015597,-0.372226,-0.494034,0.394309', '1877596', '1306530', '3755531', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2135981', '画皮', '剧情', '根据中国古典名著《聊斋志异》改编。秦汉年间，都尉王生（陈坤 饰）率王家军在西域苦战，并救回一女子小唯（周迅 饰）。王生并没有看到在他到来之前，小唯刚刚吞食完人心以保持人形。九霄美狐小唯对王生一见钟情，跟随他回家后以妹妹自居，眼看王生与佩容（赵薇 饰）夫妻情深，暗地里想取代佩容地位成为王生妻子。深爱着小唯且一直为她杀人取心的蜥蜴精小易几度向小唯表白，却被小唯怒吼而走。城里越来越多的人死于心脏被挖，王生誓要查个水落石出，佩容已经觉得小唯异于常人且对丈夫有意。碍于王生对小唯的一片信任，她唯有去寻求当年负气出走的旧情人庞勇（甄子丹 饰）帮忙，而降魔者夏冰出于天命亦自告奋勇去除妖。佩容所作一切但求王生安好，王生心痛佩容不相信自己，小唯委曲求全希冀得到爱情，庞勇和夏冰已蓄势待发。©豆瓣', '周迅', '陈嘉上', 6.8, 424427, 'tt1055300', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p462058001.jpg', 1.4, 8.3, 49.2, 32.2, 8.9, '-0.136671,0.111067,-0.507025,0.359357,0.165256,-0.224640,0.531274,0.075348,-0.382292,-0.362298,0.035818,0.494743,-0.004748,-0.044138,-0.020204,-0.012569,-0.142794,-0.390442,-0.196236,0.023507,0.183833,-0.203491,-0.001670,-0.022953,-0.439282,-0.040071,0.618125,-0.100793,-0.007145,0.454341,0.246255,0.123481,-0.169760,0.397119,-0.084754,0.138979,-0.462750,-0.058897,-0.480252,-0.059541,0.269488,-0.038587,-0.342619,0.058720,-0.277571,0.128516,0.438065,-0.344758,-0.139065,-0.189689,0.151212,-0.345297,0.177419,0.102510,0.057011,-0.023030,0.249909,0.350396,-0.203818,0.101511,0.094826,0.058848,-0.541285,0.116289,0.219788,0.222165,-0.130690,0.249113,-0.266638,0.148623,0.242660,-0.331693,-0.066422,0.077982,0.115417,0.200917,-0.420438,-0.094139,-0.345861,-0.041581,0.485820,-0.006075,0.098419,0.190280,0.157527,-0.183365,0.101597,-0.092548,-0.300057,0.011385,0.103309,0.186021,-0.093673,0.116853,-0.100300,-0.191911,-0.210775,0.072084,0.078318,-0.388570,-0.064771,0.073769,-0.139269,-0.361164,-0.163482,-0.185144,0.313172,-0.454147,0.540813,-0.673649,0.008941,0.092787,0.350806,-0.792598,0.455514,0.082290,-0.078650,-0.259210,-0.054451,0.505332,0.034036,0.003843,0.072255,0.033214,0.089294,0.000667,-0.230980,0.156219', '1293265', '1494897', '1949320', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2135983', '空中杀手', '剧情', '战斗机飞行员函南优一（加濑亮配音）来到基地报道，等待他的是全新的生活环境与熟悉的飞行战斗。在这里，函南优一遇到了各式各样的战友，与不苟言笑的长官草薙水素（菊地凛子配音）。函南优一获得了一架新战斗机，但是，基地里的战友们都对战斗机的前任驾驶员缄默不语。于是函南优一开始留意相关的消息，他渐渐知道，前任驾驶员已经去世，而事件本身与草薙水素有莫大的关系。随着调查的深入，函南优一逐渐发现惊人的真相，而他每天与敌人的战斗，似乎也隐藏着他不知道的意义。©豆瓣', '菊地凛子', '押井守', 8.1, 19683, 'tt1056437', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p724164809.jpg', 0.6, 2.4, 20.6, 44, 32.4, '0.264304,-0.203185,-0.807299,0.828776,0.181710,0.028359,0.657359,-0.011841,-0.617204,-0.438143,0.261808,0.811440,-0.015671,0.021105,0.271694,-0.182021,-0.291552,-0.714758,-0.264634,0.038197,-0.496494,-0.729703,-0.235514,-0.276549,0.142477,-0.355179,0.753997,0.088226,-0.207833,0.515284,-0.093699,0.243589,-0.171748,0.690135,-0.060372,-0.145095,0.040332,-0.056784,-0.087129,0.001250,-0.191929,-0.185233,-0.255207,0.092693,0.282507,0.552925,0.831537,-0.285617,-0.511800,0.007039,-0.066437,-0.354326,0.231017,-0.018183,0.557550,0.022422,0.067979,0.320202,-0.071265,0.048675,-0.379147,0.243605,-0.737244,0.052698,-0.189224,0.218394,-0.339805,0.358826,-0.278812,-0.123395,0.134579,-0.152278,0.474529,0.498743,0.112056,0.295250,-0.306646,0.118688,-0.436871,0.106521,0.713805,-0.167698,-0.224150,0.634120,-0.078888,-0.514066,-0.494918,-0.290486,-0.366995,-0.161855,0.002419,0.319240,-0.216370,0.221803,-0.676269,0.180166,-0.036563,-0.605429,-0.063257,-0.376510,-0.187866,-0.703064,-0.251857,-0.711710,-0.304308,0.268942,-0.090890,-0.315266,0.981297,-1.127376,0.103788,0.401443,0.043660,-0.594643,0.554603,-0.038009,0.117429,-0.343666,-0.090360,0.247910,0.023396,0.267911,0.071501,0.423266,0.004927,-0.268008,-0.350671,0.180888', '1292219', '1395231', '3811356', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21360412', '狂舞派', '剧情', '阿花（颜卓灵 饰）从小就展现出了过人的舞蹈天赋，长大后，怀揣着对舞蹈的一腔热情与热血，阿花加入了大学舞蹈队BombA。队长戴夫（杨乐文 饰）十分看好阿花的才能，两人相约挑战在舞蹈界称霸一时的Rooftoppers。没想到，这一举动却让阿花遭遇到了一生中最巨大的失败和挫折。伤心的阿花离开了BombA，之后偶然遇见了太极社社长阿良（蔡瀚亿 饰），阿良用太极带给了阿花启发，令阿花悟出了全新的舞步，同时找回了对舞蹈的热爱和自信。之后，阿花再一次向Rooftoppers发出了挑战，然而，就在这个节骨眼上，她却因为脚伤而无法行动，一直以来坚定的梦想眼看就要破灭，就在此时，Rooftoppers的队长飓风（Tommy "Guns" Ly 饰）找到了阿花，向她透露了一个惊人的秘密。©豆瓣', '颜卓灵', '黄修平', 7.2, 8846, 'tt3003996', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2171297799.jpg', 1.5, 6.3, 34.9, 42.9, 14.4, '0.025777,0.041806,-0.859852,0.668599,-0.107454,-0.467069,0.609910,0.008440,-0.576482,0.102524,0.141541,0.728377,-0.288762,0.227623,0.460932,-0.134980,0.060788,-0.810349,-0.018403,-0.155964,-0.359205,-0.200031,-0.046709,-0.051334,-0.142062,-0.431825,0.517466,0.114862,-0.447179,0.726525,0.230367,0.033500,0.075624,0.519754,-0.151499,0.149413,0.084210,0.342843,-0.126494,0.226092,0.342137,-0.386261,-0.259868,0.376473,-0.095229,0.125580,0.761854,-0.429288,-0.240457,-0.068546,0.213297,-0.156984,-0.138308,0.137977,0.133859,0.165634,0.111668,0.088078,-0.109704,0.062354,-0.082658,-0.195313,-0.812718,0.054046,0.087769,-0.004045,-0.845910,0.540790,-0.011676,-0.233461,0.090399,-0.348160,0.066166,0.248369,0.326650,0.425264,-0.372874,0.084312,-0.380509,0.183484,0.658761,-0.080806,-0.191234,0.409210,-0.147075,-0.351494,-0.162301,-0.141885,-0.331175,0.014027,0.396983,0.252572,-0.191619,-0.001530,-0.699043,0.113596,-0.190636,-0.219607,0.056536,-0.575812,-0.086951,-0.372902,-0.137241,-0.378512,-0.355346,0.255586,-0.075386,-0.173804,0.961134,-1.158222,0.350733,0.458829,0.298804,-0.347508,0.601119,0.132321,-0.054710,-0.181888,0.174670,0.023907,-0.231099,0.415078,0.287661,0.567426,0.073626,-0.217426,-0.461021,0.646763', '35030151', '4127270', '35144311', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21360417', '恐怖直播', '剧情', '韩国首尔某个平凡的早上，广播电台Daily Topic节目的主持人尹英华（河正宇 饰）正就税率改革与听众进行连线，这时一个自称住在首尔昌信洞的普通工人朴鲁圭打入电话，大肆抱怨超高的电费和相关部门对他的威胁。尹英华颇不耐烦，以偏离主题为由强行切断电话。谁知连线无法单方面由电台方面中断，愤怒的朴鲁圭继续抱怨，并扬言炸掉汉江大桥。尹英华不以为然，进而怂恿对方想做就做，谁知话音刚落，窗外的麻浦大桥便炸作废墟。大惊失色的尹英华很快冷静下来，他决定利用这次难得的机会打一次事业的翻身仗。在他的主持下，针对恐怖分子的连线直播就此展开，无关良知的节目拉开帷幕……©豆瓣', '河正宇', '金秉祐', 8.7, 609338, 'tt2990738', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2054744538.jpg', 0.2, 0.6, 9.6, 41.3, 48.2, '0.074624,0.362452,-0.599845,0.650597,0.114852,0.046361,0.413852,0.176546,-0.216864,-0.049013,-0.204038,0.325247,-0.369659,0.236598,0.297029,-0.291925,-0.373491,-0.749665,-0.047970,0.194657,-0.085494,-0.751751,0.158337,-0.166391,-0.063623,0.041795,0.420670,0.123227,-0.544900,0.280535,0.473595,0.156336,-0.093047,0.684576,0.196269,-0.199318,-0.047934,-0.138585,-0.261450,0.087690,0.113243,-0.290637,-0.032178,0.132245,0.202782,0.575828,0.392352,0.103482,-0.080114,-0.116658,0.341457,-0.168963,0.055468,0.091675,0.462071,0.293805,0.086134,-0.052481,-0.319438,-0.155137,0.099653,-0.207461,-0.537165,0.051106,-0.203061,-0.131250,-0.220993,0.310247,-0.025306,0.259693,-0.082967,-0.247819,0.072131,0.457823,0.442783,0.239035,-0.225784,0.203916,-0.062210,0.283995,0.476461,0.324252,-0.062243,0.201580,0.174820,-0.290064,0.039876,0.111221,-0.234546,-0.156811,0.435870,-0.017426,-0.007844,-0.142542,-0.289058,-0.200356,-0.187003,-0.307369,0.168039,-0.555509,-0.080877,-0.776226,0.105862,0.084492,0.032522,0.191311,0.140311,-0.007819,0.341389,-0.842320,-0.154661,0.236272,0.321186,-0.557493,0.464010,0.231663,0.118774,-0.386728,0.052846,0.066661,0.085962,0.705060,0.218729,0.123431,-0.002075,-0.318371,-0.315654,0.199980', '25723905', '6041191', '1431694', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136071', '女人本色', '剧情', '成在信（梁咏琪饰）是香港典型的女强人，她的老公杜林（林子祥饰）在香港回归、公司政策改变的情况下被革职。成在信十年来的故事就从此刻开始。接着，她的丈夫因为车祸离世，当她以为自己可以把一切事情都处理得相当稳当的时候，她的儿子因为“非典”而病逝，失去工作，也失去了她与新任上司程必聪（聂远饰）的一段情。助手宋晓彤（薛凯琪饰）非常向往爱情，却被骗财骗色，深感伤心之际幸有早已对她倾心的卖花小子（张敬轩饰）的关怀。她准备放弃自己生命的时候，一个决定救回了她：她决定与昔日助手宋晓彤（薛凯琪饰）及毛毛（小仪饰）携手开办按摩椅公司，到最后，能否成功呢？©豆瓣', '梁咏琪', '黄真真', 6.1, 11121, 'tt1053898', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p481782495.jpg', 3.5, 16.7, 54.5, 19.8, 5.4, '0.095957,0.205444,-0.707272,0.408977,-0.393337,-0.312049,0.500579,0.206474,-0.574843,-0.193247,0.192546,0.685958,-0.067132,0.370689,0.186075,0.032642,-0.143818,-0.819852,0.127043,-0.126872,-0.207357,-0.317722,-0.054289,-0.114881,-0.232374,-0.348887,0.668897,0.091985,-0.046858,0.140535,0.302313,0.289584,0.205937,0.617125,-0.116828,0.174420,-0.158094,0.023673,-0.309666,0.075729,0.282306,-0.415714,-0.168268,0.460616,-0.158418,0.258642,0.634994,-0.114110,-0.361463,-0.138820,0.465656,-0.264152,0.114123,0.161114,0.247963,0.067871,0.119279,0.413298,-0.530641,-0.114457,0.214754,0.040620,-0.692547,0.025188,-0.050212,-0.006588,-0.815554,0.437391,-0.314078,0.086583,0.225145,-0.706898,0.159395,0.340676,0.141822,0.476572,-0.455774,0.011948,-0.607188,0.503161,0.715063,0.106666,-0.036430,0.556591,-0.003434,-0.417264,-0.161251,-0.188458,-0.433751,0.109456,0.279297,-0.011926,-0.231751,0.122076,-0.251847,-0.249350,-0.204669,-0.179935,-0.003316,-0.603227,-0.017410,-0.127140,-0.129504,-0.214529,-0.428194,-0.029704,0.096062,-0.346545,0.621426,-0.866453,0.174341,0.496710,0.071387,-0.786710,0.552426,0.254824,0.111068,-0.316772,0.036125,0.174907,-0.149398,0.189501,0.275166,0.070238,0.007592,-0.012692,-0.437101,0.608969', '1301022', '5446226', '1299965', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136201', '陆小凤传奇之铁鞋传奇', '动作', '桃花堡堡主花如令（夏志祥饰）六十寿诞大宴在即，宴请江湖五大掌门人及众位武林人士，齐聚毓秀山庄。寿宴前夕，花如令为儿子花满楼（张智尧饰）安排了一场除去心中魔怔的局。十五年前，花满楼被铁鞋大盗所害，双目失明。即使花如令已联合江湖五大门派将铁鞋大盗铲除，但十几年来花满楼却饱受心理魔怔的折磨。为在有生之年帮儿子驱走魔怔，花如令请来陆小凤（张智霖饰）假扮铁鞋大盗，成全花满楼亲手铲除仇人的心愿。本片根据古龙的武侠小说《陆小凤传奇》改编而成，但并非原著系列故事之一。《铁鞋传奇》根据原著的人物性格和故事情节，既忠于古龙先生的原著，又在此基础上加以艺术化的整理和演绎，环环紧扣，高潮迭起，把古龙笔下最快意恩仇的《陆小凤传奇之铁鞋传奇》呈现于荧屏。©豆瓣', '张智霖', '袁英明', 7.9, 17667, 'tt14691784', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2509843300.jpg', 0.3, 1.6, 23.7, 50.4, 24.1, '-0.252081,0.205345,-0.190875,0.626121,0.245303,-0.073232,0.404564,-0.003392,-0.414766,-0.383148,0.355520,0.724246,-0.233388,0.160605,0.344375,0.024261,0.048528,-0.663293,-0.192201,-0.287085,0.346893,0.105940,-0.427573,0.059158,-0.116169,-0.172078,0.677164,0.203055,-0.286386,0.337706,0.216402,0.651839,-0.441488,-0.291053,-0.349900,-0.112220,-0.135849,-0.187493,-0.618178,0.085911,-0.480553,-0.143141,-0.065553,0.251836,-0.604994,0.106571,0.562313,-0.216530,-0.108661,0.070899,0.371260,-0.209188,-0.070081,-0.115445,0.498339,-0.035992,0.216941,0.643443,0.097495,-0.138190,-0.128148,-0.056954,-0.924747,0.021635,0.815317,-0.109197,-0.455520,0.542842,-0.398722,-0.018116,-0.337757,0.033371,0.112702,0.178004,0.758662,0.027825,0.147434,-0.163016,-0.303967,0.644912,0.201013,-0.050850,0.215508,0.158182,0.488228,-0.242840,-0.025287,-0.420398,0.225444,0.168291,0.279016,-0.238396,0.126056,0.660644,-0.533154,-0.354686,-0.215884,0.042164,0.272590,-0.165941,-0.082241,-0.592683,-0.361732,0.055218,-0.045695,-0.430647,0.675008,-0.360265,0.560423,-0.591771,0.093354,-0.121982,-0.495190,-0.697216,0.612138,0.030187,0.225143,-0.243782,-0.204304,-0.026618,0.470316,0.168295,-0.050862,0.118910,-0.091413,-0.127769,-0.556027,0.070903', '26678784', '25918677', '26635323', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136204', '陆小凤传奇之陆小凤前传', '剧情', '“鲁班神斧门”传人朱停（杨树 饰）得知陆小凤（张智霖 饰）手中持有伪造的大通宝钞银票后，差捕头将陆小凤骗入天牢。原印版朱停已毁，须找到朱停师兄岳青（唐启龙 饰）再刻新版，但岳已死于几年前的瘟疫。唯一能补救的是马上找到岳的女儿无艳（杨丽菁 饰），大通宝钞东家公子花满楼（张智尧 饰）差人将陆小凤放出天牢，在酒宴中暗下“三日摧魂散”，责令陆小凤三日破案，否则无解药自毙性命。陆小凤找到大通宝钞掌柜钱老大（黄平环 饰），针对假钞分析一番断定，伪造银票来自风月场极乐楼。月黑风高之夜，陆小凤与朋友司空摘星（张明达 饰）造访极乐楼，意外发现了岳青的女儿无艳姑娘和花满楼，种种迹象表明，极乐楼与伪造银票有重大联系......©豆瓣', '张智霖', '邓衍成', 8, 22201, 'tt14685024', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2414132191.jpg', 0.3, 1.7, 22, 50.6, 25.4, '-0.252757,0.196257,-0.022545,0.204250,0.023053,-0.020698,0.268504,-0.014630,-0.482681,-0.292501,0.320732,0.417311,-0.152514,-0.024756,0.288166,0.182408,0.123725,-0.371260,-0.027661,-0.455061,-0.229549,-0.496148,0.032315,-0.107127,-0.231288,0.016797,-0.012328,0.253922,0.111809,0.435489,0.217499,-0.113900,-0.454961,-0.070715,-0.194874,0.099701,-0.201982,0.123437,-0.451446,0.435808,0.009076,-0.010432,-0.264954,-0.095225,0.298411,0.267665,0.403817,-0.307490,-0.226202,0.263962,0.356306,0.295686,-0.162481,-0.093532,-0.022969,0.232284,-0.040879,0.257616,-0.631517,-0.122800,0.300925,0.078139,-0.122034,0.174363,0.382275,-0.150460,-0.232043,0.100527,-0.532118,0.131985,-0.261122,-0.348225,0.292753,0.193653,0.409156,-0.266642,0.147633,-0.274605,-0.790943,0.526483,-0.117205,-0.145808,0.457416,0.001101,0.460011,-0.318072,0.003203,0.099870,0.297816,0.338409,0.624896,-0.036567,0.144871,-0.181202,-0.248898,-0.186104,-0.417137,0.185895,0.152132,0.157697,-0.239258,-0.481748,-0.215370,0.109590,-0.153306,-0.073872,0.618424,-0.195284,0.329997,-0.337772,0.044578,-0.077432,0.106311,-0.324378,0.418127,-0.056759,-0.019299,-0.218146,-0.230555,-0.103901,0.539936,0.592742,0.256250,-0.021288,-0.134386,-0.094383,-0.172871,-0.204253', '1306490', '1298761', '1297260', '1292262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136208', '陆小凤传奇之幽灵山庄', '剧情', '陆小凤（张智霖 饰）被西门吹雪（何润东 饰）一路追杀，原因是陆小凤染指西门的妻子。陆被刺中一剑后逃往幽灵山庄。幽灵山庄十分避世，世人无法找到。但是陆小凤一到幽灵山庄即染上血案，后得知那原是试探，陆小凤顺利被老刀把子收留成为幽灵山庄的一员。山庄内两姐妹叶灵和叶雪同时钟情陆小凤，陆小凤成为情感靶子，这时他意外发现叶氏姐妹十五年前失踪的父亲尚在人间，但他面对前来相认的叶雪却痛下毒手……老刀把子谋划已久的“天雷行动”即将开始，幽灵山庄全体成员被老刀把子兵分三路，向武当秘密进发，目标就是武当掌门人石雁头顶紫金冠里那本记录江湖人士隐秘的帐薄。不过，陆小凤却早已猜到老刀把子醉翁之意不在酒。©豆瓣', '张智霖', '邓衍成', 7.5, 12026, 'tt14792620', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2511532849.jpg', 0.6, 3.3, 34.5, 44.6, 16.9, '0.183734,0.153249,-0.264083,0.299489,0.062763,-0.089284,0.287349,-0.122736,-0.648758,-0.537859,0.147119,0.440746,0.172044,0.378137,-0.015505,0.113207,0.356774,-0.636138,-0.209886,-0.544208,0.101493,-0.009106,0.114436,-0.149992,-0.053293,0.060533,0.463266,0.506041,-0.152710,0.485478,0.453451,0.535020,-0.627173,0.443878,-0.069968,0.040940,0.223175,-0.063462,-0.234731,0.341098,-0.313836,0.057597,0.026591,0.261950,-0.239398,0.498633,0.362153,-0.155683,-0.181436,-0.244171,0.036669,-0.221211,0.090277,0.071745,0.866095,0.167174,0.251731,0.184773,-0.023002,-0.268568,-0.291476,-0.108847,-0.169107,0.105246,0.481719,0.062871,-0.483992,0.195485,-0.336797,0.099333,-0.126733,-0.444385,0.343454,0.071372,0.736749,-0.369370,-0.197771,-0.113105,-0.498498,0.168213,0.711964,-0.093603,0.147918,-0.190661,0.473280,-0.210404,-0.049595,-0.210054,0.095875,0.005132,0.512442,0.073895,0.084137,0.331819,-0.137069,-0.094584,-0.290180,0.247316,0.006475,-0.370615,-0.107826,-0.494234,-0.048883,-0.235456,-0.178901,-0.011030,0.035062,-0.131192,0.192215,-0.681914,0.326985,0.160528,-0.023250,-0.464119,0.381275,-0.210200,-0.000758,-0.207827,-0.053648,0.520893,0.363213,0.264459,0.189201,-0.004594,-0.343774,-0.208109,-0.316978,-0.010408', '1307456', '25723905', '1307186', '1301283');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136210', '陆小凤传奇之血衣之谜', '剧情', '深夜，于大内皇宫之中皇帝被蒙面人所挟持，交出星邪剑谱。蒙面人使出灵犀一指，天下人皆认为是陆小凤（张智霖 饰）所为，剑谱也被送往西门吹雪（何润东 饰）的万梅山庄。次日全城开始通缉陆小凤，江湖中人也纷纷围着陆小凤转，企图取他项上人头。陆小凤在毫无选择之中被血衣堂看中，血衣堂要他去拿回星邪剑谱。得到徒弟清清协助的陆小凤成功把西门吹雪带来京城，却在破庙处被血衣堂暗算，亲眼看见西门吹雪和清清被烈焰包围。抢回来的剑谱是一片空白。陆小凤为此内疚不已。被干爹南平郡王救出的清清前来安慰小凤，南平郡王请陆小凤调查清楚血衣堂的来历。血衣堂筹划七大血衣童子进入皇宫盗取真正的星邪剑谱。陆小凤的灵犀一指是最后一道关卡。当星邪剑谱到手后，血衣童子骤死。真正的幕后主使人令人吃惊。然而陆小凤却比他们更早一步洞悉天机。©豆瓣', '张智霖', '邓衍成', 7.6, 10484, 'tt14792828', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2629905675.jpg', 0.6, 2.9, 31.7, 45.9, 18.9, '0.154973,0.358032,-0.115623,0.283127,-0.180814,-0.059185,0.133751,-0.045794,-0.456931,-0.301681,0.671329,0.431275,0.227451,0.007478,0.083727,0.227380,0.508607,-0.670109,-0.148941,-0.444508,-0.101524,-0.054629,0.055121,0.289754,-0.361704,-0.203398,0.270462,0.189722,0.001974,0.414670,0.461263,0.446836,-0.471351,0.528856,-0.243562,-0.002517,0.042415,-0.424894,-0.161802,0.505029,-0.374143,-0.162564,-0.283043,0.601303,-0.236462,0.167347,0.431645,-0.060693,0.080435,-0.200981,0.251433,0.000294,-0.122137,0.128094,0.367599,0.198640,-0.038778,0.160974,-0.292624,-0.182580,-0.064551,0.019040,-0.426796,0.044274,0.395661,-0.064494,-0.572425,0.203718,-0.423783,0.056583,0.069114,-0.395425,0.401583,-0.094832,0.299083,-0.230271,-0.268463,-0.392440,-0.706142,0.282970,0.308499,-0.315929,0.439635,-0.304163,0.574413,-0.041541,-0.284534,-0.104725,0.402957,0.067519,0.714624,-0.006782,0.272457,0.201824,0.089175,-0.172723,-0.112105,0.109074,-0.003811,-0.353804,-0.252091,-0.335556,-0.020733,0.206060,-0.217359,-0.379463,0.303711,0.004248,0.282481,-0.594954,0.322679,0.057980,-0.102417,-0.309002,0.266548,-0.083413,0.004693,-0.152095,-0.415268,0.019152,0.528414,0.559320,0.372129,0.471727,-0.220709,-0.370227,-0.373024,0.078612', '1498658', '4323732', '26801782', '1307582');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136213', '陆小凤传奇之决战前后', '武侠', '西门吹雪（何润东饰）和叶孤城（严宽饰）约定于九月的月圆之夜决战紫禁之巅。消息刚刚传出，就发生了一系列匪夷所思的杀人案件。陆小凤（张智霖饰）还没来得及摸清头绪，红颜知己欧阳情（贺丹丹饰）也遭逢暗算。为查明真相，陆小凤一路明察暗访，他预感到“紫禁之战”的背后一定暗藏玄机。当谜底被一一揭开时，原来这些江湖风波都是叶孤城所设计的野心勃勃的复仇计划。本部古装数字电影根据古龙的武侠小说《陆小凤传奇》中的单元《决战前后》改编而成，由香港著名导演邓衍成执导，张智霖、何润东、严宽等主演。邓衍成号称“香港罪案题材电影”第一导，此次执导本片，更是把武侠大师古龙先生小说中最奇幻悬疑、最快意恩仇、最动人心弦的《陆小凤传奇》呈现于荧屏，广受武侠迷们的称赞与喜爱。©豆瓣', '张智霖', '邓衍成', 7.6, 14195, 'tt14755950', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2629906848.jpg', 0.7, 3.2, 32.1, 45.9, 18.1, '-0.130946,-0.074271,-0.388293,0.521093,0.562373,0.007170,0.336840,-0.261215,-0.500317,-0.438371,0.230564,0.532007,-0.606684,0.000442,0.518077,-0.188668,-0.109210,-0.692215,-0.180155,-0.278001,0.220128,-0.128367,-0.518640,0.254293,-0.027626,-0.146252,0.635622,0.301181,-0.366513,0.357124,0.357144,0.190133,-0.445724,0.235655,0.171734,0.162414,0.028429,0.117302,-0.641006,0.176966,-0.100746,-0.356819,-0.178190,0.144465,-0.235470,0.216834,0.432311,-0.335330,-0.104902,0.031909,0.704750,-0.177491,-0.136942,-0.006597,0.142851,0.165809,0.469554,0.376313,0.036743,0.082894,-0.202745,-0.242910,-0.812844,-0.005683,0.316470,0.192748,-0.078891,0.020628,-0.463130,-0.138890,0.048423,-0.253287,0.242790,-0.054140,0.878903,0.099363,-0.099724,-0.152133,-0.158962,0.626011,0.333773,0.132822,0.034544,0.380354,0.455256,-0.434688,-0.075028,-0.086976,-0.123626,0.441378,0.280243,-0.071248,0.106538,0.199467,-0.362087,-0.163715,0.154111,-0.108776,0.123488,-0.001621,-0.031993,-0.896368,-0.242655,-0.163846,0.087294,-0.330146,0.378004,-0.258119,0.662371,-0.509354,0.039405,0.173922,-0.139956,-0.362820,0.435880,0.131856,-0.095575,-0.051040,-0.089770,0.153262,0.027060,0.390405,-0.078410,0.469815,0.142616,-0.586760,-0.406204,0.304590', '3318306', '1322847', '26275494', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21362716', '拯救大明星', '喜剧', '小精灵伯纳德（马丁·弗瑞曼 Martin Freeman 配音）是一位身份卑微的粪便清理员，做事神经大条，囧态嗅事不断，而他的梦想是成为大发明家。在今年的圣诞科技大赛上，他又搞砸了实验。恰巧正是这次小小的实验意外给精灵城引来了危机。大反派班尼（蒂姆·克里 Tim Curry 配音）侵袭精灵城，所有人都面临灭顶之灾。伯纳德在重重险境中误打误撞，却惊喜不断，发现自己是唯一可以拯救这场灾难的人，在甜心女特工雪妮（阿什丽·提斯代尔 Ashley Tisdale 配音）的鼓励下，他鼓起勇气誓要挽救一切……©豆瓣', '马丁·弗瑞曼', '莱昂·乔森', 5.9, 9825, 'tt2204315', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2162351943.jpg', 6.4, 22.6, 47.9, 16.3, 6.7, '-0.201053,0.234298,-0.472700,0.154316,-0.026050,0.076744,0.508895,-0.072024,-0.404984,-0.161449,0.513120,0.833346,-0.319995,0.121917,0.382887,0.129702,-0.489966,-0.484684,-0.075861,0.071985,-0.510279,-0.197691,-0.390998,-0.352142,0.083456,-0.527211,0.426892,0.146913,-0.452599,0.117202,0.417247,0.382699,-0.140317,0.402211,0.057683,0.220705,0.443755,-0.255119,-0.035998,0.077838,-0.282912,-0.305614,-0.361228,0.434343,0.150138,0.415870,0.413686,-0.405093,-0.059885,-0.282934,0.363513,-0.687381,0.043011,-0.070136,0.122542,-0.229955,0.201750,-0.133044,0.018822,-0.267480,0.214829,-0.519124,-0.857798,0.110399,-0.011042,0.355330,-0.460828,0.291164,0.081565,0.116258,0.237451,-0.181246,-0.107486,0.212632,0.438437,0.307469,-0.168494,0.024664,-0.111786,0.338790,0.672578,-0.024864,-0.484654,0.340434,-0.307828,-0.307342,0.059765,-0.333631,-0.595860,0.008094,0.417160,0.024491,0.034527,0.606960,-0.339329,-0.105582,-0.496501,-0.398923,-0.109124,-0.313335,-0.115084,-0.525420,-0.063979,-0.040097,-0.279937,0.162512,0.125171,-0.347083,0.641465,-0.820870,0.214682,0.840022,0.004460,-0.122894,0.246151,-0.020613,0.129959,-0.214399,-0.115759,0.205972,0.054392,0.187983,0.137900,0.334498,0.129510,-0.280367,-0.335544,0.485474', '3769423', '34890458', '1793491', '3755531');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136477', '菲比梦游奇境', '剧情', '9岁女孩菲比（艾丽•范宁 Elle Fanning 饰）进入学校话剧团，饰演《爱丽丝梦游仙境》的主角爱丽丝，话剧老师道吉尔小姐（帕特里西娅•克拉克森 Patricia Clarkson 饰）对菲比赞誉有佳。但话剧团外的菲比却问题重重，因向同学吐口水和无法控制自己的行为而屡遭麻烦。菲比的母亲希拉里（菲莉丝蒂•夏夫曼 Felicity Huffman 饰）拒绝承认菲比身患强迫性神经官能症的事实，面对多重压力，希拉里与丈夫皮特（比尔•普曼 Bill Pullman 饰）的矛盾频繁升级。与此同时，菲比的症状日益加剧，头脑中的幻象与现实的界限越来越模糊，而校方也对道吉尔小姐对孩子们的教育方法不满。精心排演的《爱丽丝梦游仙境》最终还能公映吗？©豆瓣', '菲丽西提·霍夫曼', 'Daniel Barnz', 7.5, 6024, 'tt1034325', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p458616685.jpg', 0.7, 4, 32.3, 44.2, 18.8, '0.191361,0.111525,-0.219146,0.532504,0.006742,-0.137698,0.734633,0.290792,-0.549007,-0.385222,0.171286,0.715767,-0.389937,0.166690,0.255820,0.181704,-0.407687,-0.578405,0.108451,0.030282,-0.089357,-0.682953,-0.036348,-0.250538,-0.142418,-0.464559,0.405088,-0.101405,-0.136396,0.297139,0.307332,0.283544,0.015478,0.380030,0.251629,0.068830,0.235551,0.078329,-0.253620,0.116970,0.192820,0.129546,-0.127015,0.242935,0.129448,0.273208,0.348459,-0.355851,-0.051196,-0.082790,0.341537,-0.276767,0.156902,0.443160,0.293604,-0.226103,0.308388,-0.134469,0.022563,0.031105,-0.004435,-0.070254,-0.374402,0.137531,0.185954,0.196316,-0.239992,0.239936,-0.194588,-0.056955,0.200542,-0.148965,-0.310533,0.221029,0.190589,0.544620,-0.426644,-0.052581,-0.192025,-0.047736,0.220057,0.071878,-0.325175,0.399111,-0.505511,-0.420220,-0.244383,-0.109411,-0.759883,0.055119,0.054476,0.045485,-0.200709,0.429838,-0.384745,-0.284877,-0.407776,-0.108214,-0.399094,-0.280571,0.045387,-0.547097,-0.032834,-0.392989,-0.231591,-0.355483,0.095508,-0.295585,0.587486,-0.754734,0.080207,0.402018,0.254603,-0.242193,0.348870,0.178701,-0.062855,-0.300613,-0.280941,0.558520,-0.247244,-0.127980,0.055157,0.539073,0.139100,-0.126205,-0.127496,0.268459', '2002744', '1292062', '35161768', '3626365');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2136824', '成事在人', '剧情', '刚刚结束牢狱之灾的纳尔逊•曼德拉（摩根•弗里曼 Morgan Freeman 饰），竞选南非总统成功。他领导人们破除种族隔离制度，并身先士卒，雇佣白人护卫队，在各方面建立不同肤色的沟通。作为1995年橄榄球世界杯的东道主，南非重回国际体育大家庭。不过，南非的英式橄榄球队——队员均为白人的跳羚队，却被很多黑人看做种族歧视的代名词。为了破除隔膜，曼德拉高瞻远瞩，支持跳羚队与国外来访球队的交流比赛。他接见了跳羚队队长皮耶那（马特•达蒙 Matt Damon 饰），两人进行了推心置腹的交谈。后者带领着白人球员走访了南非各地，把橄榄球运动普及给普通民众，让这项运动成为了黑白联合的纽带……本片根据约翰•卡林的作品《与敌人战斗：纳尔逊曼德拉和一场改变国家的比赛》（Playing the Enemy：Nelson Mandela and the Game That Made a Nation）改编。', '摩根·弗里曼', '克林特·伊斯特伍德', 8.3, 45966, 'tt1057500', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1054037032.jpg', 0.2, 1.1, 16.2, 50.8, 31.7, '0.147736,-0.226254,-0.310725,0.536841,-0.029939,-0.388046,0.166976,0.100789,-0.403876,-0.180688,0.175488,0.721134,-0.274107,-0.155563,0.442169,-0.403574,-0.472806,-0.719228,-0.243920,0.198109,-0.138850,-0.508332,-0.261861,-0.306772,-0.100972,-0.341725,0.962776,-0.026956,-0.403489,0.611225,0.183516,0.237048,0.317348,0.014174,-0.080584,-0.329289,0.347005,-0.252647,-0.568486,0.148731,-0.326913,0.184929,-0.196912,0.096254,0.278082,0.446556,0.532399,-0.397502,0.359411,-0.330873,0.233065,-0.251162,0.152795,0.143899,0.506464,0.303280,0.069330,0.392925,0.081408,0.125985,-0.335988,-0.304315,-0.475805,0.167221,0.086034,0.202926,-0.410629,0.719662,-0.176358,0.158138,-0.048238,0.129107,0.082756,0.588374,0.203042,0.185166,0.197286,-0.016630,-0.421143,0.236907,0.659652,-0.090418,-0.486013,-0.326845,-0.517629,-0.636930,0.030014,-0.366973,-0.047781,-0.181249,0.238520,-0.293331,0.289380,0.235353,-0.866828,0.096243,-0.073807,-0.455391,0.085740,-0.397258,0.383697,-1.174523,0.021045,-0.203157,-0.195279,-0.092995,0.118909,-0.030033,0.887185,-0.844018,-0.086259,0.631303,0.310274,-0.424221,0.484854,0.072790,0.534791,-0.513600,-0.329183,0.246972,0.209348,0.173037,-0.069758,0.505753,0.016651,-0.232053,-0.013244,0.241110', '2369613', '20274039', '26365262', '3266509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2137060', '优雅的世界', '喜剧', '康仁久（宋康昊 饰）是一名黑社会帮派里的中层人物。但他有个贤淑的妻子（朴知英 饰），一双儿女，是一个极普通的家庭。仁久一心想过着田园生活，与世无争，跟妻子儿女和睦幸福的生活。因此他在帮派里表现突出，希望能像其他人一样做一名好丈夫与好父亲。可是最近帮派里的大人物有所矛盾，仁久自己跟女儿的关系也不是很好。他开始感到失落，他决心要做一件大事，让女儿及组织里的人能看到自己的能力。到最后，仁久最想要的舒适生活又能否如愿以偿呢？©豆瓣', '宋康昊', '韩在林', 7.5, 10170, 'tt1038110', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1534529644.jpg', 0.3, 3, 32.7, 48.6, 15.4, '0.267998,-0.147468,-0.707153,0.853378,-0.343911,0.041824,0.916363,0.089543,-0.919001,-0.215631,0.013588,0.999841,0.183648,0.551725,0.028505,0.175210,-0.121400,-0.721895,0.194013,-0.230752,-0.024619,-0.284209,-0.558926,-0.256663,-0.378750,-0.148078,0.444379,0.032326,0.049611,0.158812,0.252404,0.214735,0.173205,0.530704,-0.346400,-0.303565,-0.188412,0.327860,-0.279547,0.076393,0.073075,0.091354,-0.247049,0.413709,0.223045,0.321996,0.348988,-0.217814,-0.345680,-0.160002,0.077650,-0.000840,-0.123297,0.289229,0.263746,-0.019555,0.419906,0.261908,-0.043027,0.020323,0.117681,-0.298959,-0.938599,-0.255486,0.308417,0.249720,-0.754467,0.462953,0.010543,-0.346020,0.165107,-0.210225,0.336233,0.302411,0.231070,0.435056,-0.341347,0.260638,-0.706257,0.384314,1.031871,0.095946,-0.123365,0.479739,-0.398089,-0.510606,-0.012698,-0.570463,-0.646861,-0.051420,-0.005439,-0.149379,-0.172643,0.077983,-0.425531,0.332655,0.025245,0.112508,-0.319284,-0.616979,0.288833,0.055065,-0.095758,-0.786882,-0.607385,0.154313,-0.052386,-0.514893,0.888567,-1.022614,-0.231718,0.295833,0.254016,-0.777135,0.706068,0.378248,0.390106,-0.160667,-0.207203,-0.103871,-0.288194,-0.096288,-0.008803,0.410713,-0.106030,-0.309280,-0.148041,0.395590', '25721544', '1308805', '1877596', '1291586');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21370611', '圣罗兰传', '剧情', '法国男星加斯帕德·尤利尔（Gaspard Ulliel）将在传奇大师伊夫圣罗兰（Yves Saint Laurent）的传记电影中饰演这位公开同性恋。YSL被誉为“色彩创造者”，他17岁被Vogue发掘，21岁即担任Dior首席设计师，26岁时与爱人兼事业伙伴皮埃尔·贝 尔热（Pierre Bergé）开创以自己名字命名的奢侈品牌，从此以无数经典作品叱咤时尚界。', '加斯帕德·尤利尔', '贝特朗·波尼洛', 7.2, 8314, 'tt2707848', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206773929.jpg', 1, 5.8, 39.1, 40.2, 13.9, '-0.153181,0.164269,-0.301039,0.759168,0.362714,-0.190334,0.202255,-0.004827,-0.523193,-0.859661,-0.128592,1.208919,-0.469455,0.594496,0.885399,0.150364,-0.032759,-0.703516,-0.083347,-0.326223,0.237803,-0.332514,-0.672369,-0.012389,-0.328133,-0.563800,0.800521,-0.292445,-0.414452,0.235373,0.491570,0.735036,0.192192,-0.153056,0.057366,-0.165663,0.703346,-0.172399,-0.442846,0.303807,-0.285044,-0.401314,0.332471,-0.206529,-0.418465,0.274329,0.452222,-0.314130,0.249621,-0.521573,0.735741,0.003579,-0.055089,-0.086343,-0.009725,0.004961,0.201210,0.412038,0.302401,0.005630,-0.185476,-0.682326,-0.786318,-0.237029,0.476699,-0.084489,-0.710157,0.099660,-0.560428,-0.028236,0.028726,0.033916,0.112341,-0.059796,0.269392,0.358441,0.175613,0.454129,-0.256307,0.815784,0.475280,0.150840,-0.564889,0.136905,-0.094011,-0.503670,-0.122981,-0.574525,-0.708170,0.092202,0.032285,-0.270797,0.834510,0.347350,-0.651427,-0.463575,-0.090607,0.023011,0.477290,0.173547,0.013088,-0.577403,-0.192914,-0.228172,0.143456,-0.451001,0.091637,-0.525611,0.972529,-0.620532,0.067031,0.026253,0.258625,-0.203832,1.230527,-0.166340,0.350969,-0.696341,-0.234922,0.690402,0.228790,-0.020840,-0.316333,-0.000965,0.011062,-0.215068,-0.201363,0.386135', '26647163', '2338019', '1297368', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21370624', '伊夫圣罗兰传', '爱情', '1957年巴黎，著名服装设计师克里斯汀·迪奥因心脏病发突然去世，留下摇摇欲坠的Dior品牌。迪奥的学徒、21岁的伊夫·圣罗兰（皮埃 尔·尼内饰）临危受命，成为Dior最年轻的首席服装设计师。他的个人处女秀“Trapeze”一鸣惊人，让世界都注意到了他的存在，也促成了他和皮埃 尔·贝尔杰（圭洛姆·加里尼）的遇见。他们既是恋人也是事业拍档，在1962年创建了后来叱咤时尚界的奢侈品牌YSL。尽管内心的魔鬼时时困扰他，圣罗兰开始用他的服装改变整个世界…… ◎QAF', '皮埃尔·尼内', '加里·勒斯培', 6.7, 11407, 'tt2707858', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2161266106.jpg', 1.4, 10.1, 51.5, 28.4, 8.6, '0.212482,0.104706,-0.639740,0.319977,0.002426,-0.280637,0.488975,-0.041338,-0.451480,-0.627735,0.282466,1.069810,-0.400465,0.367469,0.508232,0.250910,-0.281209,-0.644481,0.266014,-0.209594,-0.218899,-0.300009,-0.323495,-0.310803,-0.112103,-0.470307,0.695519,0.129803,-0.050903,0.248765,0.266829,0.272156,0.569448,0.348910,0.017751,-0.011674,0.324700,-0.174896,-0.205059,0.021083,-0.121238,-0.281168,-0.000936,0.311856,-0.110985,0.504237,0.424748,-0.357574,0.236251,-0.119946,0.620721,-0.200621,0.133042,-0.329601,0.154834,-0.278969,-0.216392,0.324061,-0.170119,-0.021826,-0.163901,-0.250969,-0.694250,0.142203,0.375141,0.031900,-0.569052,0.552345,-0.342113,0.035086,-0.140137,-0.253768,0.034699,0.080065,0.283726,0.494315,0.190147,0.417683,-0.524476,0.287431,0.575208,0.027179,-0.437862,0.282974,-0.457380,-0.432310,-0.228927,-0.606247,-0.394161,-0.059680,0.136473,-0.251823,0.282614,0.327840,-0.662191,-0.083242,-0.162956,-0.241671,0.205827,-0.192957,-0.208512,-0.490484,-0.010686,-0.470236,-0.212032,-0.288553,-0.065382,-0.402141,0.717519,-0.775498,-0.081280,0.608651,0.399243,-0.470724,0.942734,-0.341766,0.272284,-0.299683,-0.264223,0.654728,-0.112875,-0.013185,0.153667,0.344445,0.140477,-0.049377,-0.066025,0.639960', '30162520', '1292720', '1870681', '30167633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21371664', '我们善熙', '剧情', '美丽聪慧但性格有些内向别扭的电影学院大学生善熙（郑有美 饰），在潜水很长一段时间后回到学校。她计划出国留学，因此拜托当初最欣赏自己的崔教授（金相中 饰）开具介绍信。因尚宇（李敏宇 饰）骗她说教授出国不在，以致于善熙一早晨就气呼呼的，坐在餐厅里喝酒解闷。期间她偶遇前男友金文洙（李善均 饰），文洙对善熙念念不忘，连处女作都是以二人的恋爱故事为蓝本。见善熙完全没有回头的意思，郁闷的文洙找到最景仰的前辈宰学（郑在泳 饰）诉苦，却又闹出一段不快。围绕着这个有着自己想法但同时又有些神经质的女孩，崔教授、文洙、宰学三个男人各自拼凑出一个令人难以忘怀的善熙……©豆瓣', '郑有美', '洪常秀', 7.2, 6348, 'tt2942512', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2079119933.jpg', 1.4, 5.6, 37.4, 43.1, 12.4, '0.137561,-0.103823,-0.466389,0.625212,-0.093651,-0.461002,0.763230,-0.074807,-0.448317,-0.428400,0.094345,0.458854,-0.327612,0.319069,0.153002,-0.085978,-0.258107,-0.194670,0.170810,-0.143323,-0.085746,-0.596812,0.068905,-0.000844,-0.128203,-0.179617,0.227578,-0.266679,-0.111215,0.511725,0.257924,0.114609,-0.069713,0.461529,-0.072066,0.070322,0.010533,0.384918,0.098485,-0.169409,0.311378,-0.201761,-0.370505,0.124525,0.017308,0.292813,0.539904,0.041807,-0.159080,0.118212,0.412594,-0.242008,-0.263353,0.081626,0.122784,-0.071573,0.327097,-0.008266,-0.304244,0.055382,0.093792,-0.047919,-0.408815,0.239922,0.087448,0.192857,-0.436155,0.372383,-0.067460,-0.165881,0.201097,-0.443265,0.090612,0.183701,0.225174,0.437498,-0.033325,0.216907,-0.322694,0.429876,0.458596,0.155196,-0.156182,0.458744,-0.264889,-0.341097,0.097901,0.063312,-0.638076,-0.002339,-0.042877,-0.218713,0.016733,-0.197243,-0.359123,0.003816,0.129453,0.074961,0.152157,-0.472991,-0.008310,-0.359729,-0.045629,-0.434803,-0.290674,-0.129423,0.058628,-0.262230,0.679909,-0.680512,0.034709,0.178221,0.022502,-0.539382,0.768492,0.340978,-0.143503,-0.151355,-0.070587,0.254317,-0.012228,0.153240,-0.021856,0.654204,0.107286,-0.307824,-0.325036,0.263838', '1302384', '2002744', '1304942', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2137298', '校园兔女郎', '喜剧', '性感美丽的雪莉·达灵顿（安娜·法瑞丝 Anna Faris 饰）曾是一名隶属于《花花公子》旗下的兔女郎，在27岁之前，她过着奢华无忧的快乐生活。然而就在27岁生日的第二天，她却被老板扫地出门。无所依靠且别无所长，雪梨漫无目的四处游走，偶然加入了由莫娜（凯特·戴琳斯 Kat Dennings 饰）、娜塔丽（艾玛·斯通 Emma Stone 饰）等女孩组成的女子联谊会Zeta Alpha Zeta，这些女孩穿着老土、性格怪异，在学校内其他团体的眼里如同怪胎。雪梨的到来有如一支催化剂，她利用自己丰富的经验帮助女孩们改变造型，打造吸引男性眼球的外形和气质，原本无人问津的女孩开始受到追捧，而雪梨也收获了属于自己的爱情……©豆瓣', '安娜·法瑞丝', '弗雷德·沃尔夫', 5.9, 23700, 'tt0852713', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p886522198.jpg', 4.1, 20.4, 55.3, 15.6, 4.6, '0.272117,-0.010473,-0.814841,0.298084,-0.599279,0.001519,0.964745,0.207708,-0.498944,-0.206835,0.283192,0.475075,-0.148692,0.259804,0.433703,0.233608,-0.117864,-0.517354,-0.003906,-0.274079,0.089075,-0.266801,-0.369643,-0.084937,0.045269,-0.605183,0.612561,-0.281776,-0.237271,0.702416,0.268192,0.173941,-0.042530,0.232108,-0.229389,-0.258078,0.196350,0.047261,-0.092276,0.242355,-0.309178,-0.141110,-0.106672,0.230427,-0.118971,0.347849,0.876999,-0.438276,-0.210234,-0.179596,0.404754,0.063540,0.046711,0.106129,0.136410,0.072182,0.418269,-0.128510,-0.017375,0.102358,0.145602,-0.180232,-0.403186,0.053581,0.406316,0.301313,-0.500402,0.518716,-0.030755,-0.330658,0.166635,-0.411045,0.095108,-0.039029,0.309592,0.369450,0.141726,0.278723,-0.573615,0.366072,0.555107,0.260846,-0.488391,0.397159,-0.626627,-0.164413,-0.063085,-0.315065,-0.590156,0.101003,0.068855,-0.041263,0.050599,0.093451,-0.723200,0.291855,-0.055708,-0.082676,0.056594,-0.201115,-0.313264,-0.647269,-0.054806,-0.587488,-0.372693,-0.097421,0.132754,-0.235067,0.970880,-0.867992,0.244018,0.458617,0.262386,-0.356307,0.572507,-0.126421,0.035921,-0.064417,-0.219790,0.207389,0.059469,-0.012927,-0.139604,0.560921,-0.132408,-0.123526,-0.369021,0.381947', '24839498', '3811356', '21619567', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2138299', '摇滚黑帮', '动作', '莱尼（汤姆•威尔金森 Tom Wilkinson 饰）是伦敦黑帮的头目，他手下有个得力干将艾奇（马克•斯特朗 Mark Strong 饰）。莱尼曾经做套逼小流氓头二（杰拉德•巴特勒 Gerard Butler 饰）还债。结果，头二凭借情人史黛拉（桑迪•牛顿 Thandie Newton 饰）提供的情报，成功打劫，抢得巨款，还清了债务，并且一发而不可收拾……莱尼买通议员想进军房地产市场。为了重金担保，他从俄罗斯黑帮头目尤里（卡瑞尔•罗登 Karel Roden 饰）手中借来了一副名画。然而，这幅名画却不翼而飞。于是，一群人卷入了这场寻找名画的闹剧中，其中不乏有莱尼失散多年的儿子，盗卖皮草的毛贼，打不死的保镖，同性恋的律师等等。最后，在名画事件水落石出之时，黑帮最大告密者的身份也被揭穿……©豆瓣', '杰拉德·巴特勒', '盖·里奇', 7.6, 36902, 'tt1032755', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p775111908.jpg', 0.4, 3.2, 31.5, 46.6, 18.3, '0.093619,-0.130529,-0.241692,0.195600,-0.214055,-0.264662,0.490466,0.083086,-0.452965,-0.086570,0.510514,0.656525,-0.009307,-0.119656,0.487718,0.319216,-0.361700,-0.648119,0.061923,-0.293499,0.080087,-0.388605,-0.435876,-0.233489,-0.230947,-0.086737,0.335402,-0.065789,-0.037090,0.272500,0.492776,0.435797,-0.032717,-0.093776,0.142762,0.135790,0.464490,-0.300584,-0.261763,0.020985,-0.187795,-0.086523,-0.046612,0.084249,0.142258,0.354663,0.239755,-0.286485,0.469121,-0.017055,0.203779,-0.287295,-0.075839,0.006920,0.097719,0.018107,0.231470,0.072463,-0.324284,-0.120835,0.525136,-0.029110,-0.664858,-0.072888,0.056136,0.236204,-0.384980,0.112770,-0.324153,0.265857,-0.057690,-0.145393,0.048585,0.281229,0.195400,0.022590,0.177631,0.101125,-0.760515,0.362303,0.183465,-0.187921,0.019252,-0.002166,-0.114067,-0.246450,0.132177,-0.621870,-0.180037,0.055730,0.606747,-0.290752,0.022541,0.093476,-0.529959,-0.221507,-0.292603,-0.128336,-0.009746,-0.108579,-0.275028,-0.611588,-0.306442,-0.069569,-0.024891,-0.160174,0.169754,-0.133428,0.550477,-0.253482,-0.054943,0.685719,0.030879,-0.251312,0.392903,-0.040995,0.145219,-0.107273,-0.436208,-0.094395,0.493755,0.329437,0.131852,0.014176,0.146496,-0.637563,0.328067,0.216923', '1300324', '26703844', '1293350', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2138300', '小山回家', '剧情', '1995年春节临近时，在北京某餐馆打工的河南民工王小山（王宏伟）因一心回家无心工作被老板开除。在回家前，他想找个老乡作伴。为此，他一一走访了他的建筑工人、票贩子、大学生、服务员、妓女等老乡，然而他们各自有留在北京不回家过年的理由（有想趁年关卖多些黄牛票多挣些钞票的，有很想回家但因为现在的工作觉得无脸见家人只让王小山把钱捎回去的，有觉得回家过年很没有意思的，不一而足），王小山费劲口舌也没能将他们说服，只落得无可奈何的失望。©豆瓣', '王宏伟', '贾樟柯', 7.2, 7915, 'tt1054062', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2170416750.jpg', 0.6, 4.4, 41.4, 39.9, 13.7, '0.331736,-0.478343,-0.739964,0.060766,-0.368426,-0.581028,0.513241,0.139663,-0.484130,-0.518152,-0.292886,0.604018,0.008506,0.285001,-0.024269,-0.098939,-0.287586,-0.101846,0.474611,-0.265187,0.012766,-0.413132,0.381503,-0.028244,-0.331531,0.409543,0.167443,-0.010678,0.434887,0.361389,-0.112023,-0.112656,0.316218,0.914467,-0.543684,0.140941,-0.283523,-0.009035,-0.098251,0.215528,0.589399,-0.176261,-0.502666,-0.036258,0.660295,0.371908,0.502953,0.692747,-0.302925,0.351389,0.288713,-0.238453,-0.043986,0.057485,0.046173,0.104945,0.263515,-0.119541,-0.511281,0.024361,0.182811,-0.077157,-0.423657,0.439239,0.045621,-0.127621,-0.875892,0.639697,-0.162751,0.077814,0.161723,-0.618115,0.551749,0.680954,-0.014858,0.288025,0.289410,0.144129,-0.967354,0.520692,0.978320,-0.006675,0.393167,0.244661,-0.080137,-0.064480,0.515376,-0.117967,-0.373898,0.034101,0.054194,0.130333,-0.714208,-0.389165,-0.515549,-0.093394,0.043426,-0.479352,0.067539,-0.472700,-0.202057,-0.168818,0.014439,-0.190515,-0.309867,-0.034940,0.475721,-0.109243,0.660033,-0.700724,0.019986,0.816585,0.807292,-0.722151,1.125319,0.203940,0.016166,0.013212,0.142353,-0.444738,0.129272,0.572146,0.637708,0.170465,0.108085,-0.482162,-0.231331,0.241414', '2990737', '26718282', '1759975', '25876760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2138404', '渔光曲', '剧情', '影片的故事发生在东海边，在“渔光曲”的歌声中展开了一个渔民家庭的悲惨故事。渔民徐福一家生活艰难，一对孪生子女小猫、小猴的出生更是加重了家庭负担。随后徐福死于海上，徐妈只好到船王何家做奶妈。小猫、小猴和何家少爷子英自小一起长大，感情要好。十年后，长大成人的小猫（王人美 饰）、小猴（韩兰根 饰）继承父业，以捕鱼为生；子英则被父亲安排出国攻读渔业，他一心希望学成归来能改良中国渔业。此后，盗匪猖獗，以及渔业公司的兴办，都使渔民的生活更加艰难。小猫、小猴难以维持生计，于是携着失明的母亲到上海找舅舅另谋出路。跟着舅舅卖唱的小猫、小猴在上海重遇了回国的子英，随后小猫、小猴却遭受了牢狱之灾，舅舅和徐妈也在一场火灾中丧生。经历了多番波折的三人，重新回海捕鱼。然而，命运弄人，那首熟悉的《渔光曲》再次响起……1935年2月，本片在莫斯科举行的国际电影节上获得“荣誉奖”，成为中国第一部在国际上获奖的影片。', '王人美', '蔡楚生', 7.7, 6388, 'tt1002784', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2028928087.jpg', 0.2, 1.6, 27.4, 52.1, 18.7, '-0.000780,-0.196947,-0.644511,0.421594,0.160280,-0.316229,0.458015,0.219777,-0.497695,0.008582,0.236752,0.738721,0.081894,0.448315,0.175991,-0.195361,-0.252706,-0.449342,0.006513,0.092931,0.072793,-0.199910,-0.026000,-0.061397,-0.194815,-0.215488,0.451701,0.023801,0.088438,0.590699,0.068074,0.030967,-0.376376,0.059118,-0.289276,0.235740,-0.113749,0.307670,-0.432157,0.084989,0.138161,-0.320623,-0.119900,-0.371840,0.185266,0.055894,0.787342,-0.119457,-0.063710,-0.397825,0.404934,-0.092666,-0.200244,-0.046920,0.413223,0.198392,0.241142,0.174622,-0.233732,-0.119686,0.052992,-0.257233,-0.240542,0.009849,0.152452,0.213717,-0.511853,0.359701,0.149623,0.136361,0.015216,-0.489435,0.138435,0.417443,0.164340,0.561097,-0.225908,0.552080,-0.389178,0.500059,0.812127,-0.155229,-0.144679,0.154196,-0.060666,-0.389144,0.186850,-0.421680,-0.419694,-0.057008,0.380515,-0.162484,-0.532689,0.254482,-0.511229,-0.025119,-0.092405,-0.332823,0.070010,-0.208875,-0.044359,-0.576723,-0.047829,-0.398165,-0.013917,0.143205,0.237293,-0.304501,0.697155,-0.578885,0.287870,0.392867,0.271002,-0.251295,0.319838,-0.234858,0.463370,-0.072404,0.151975,0.153223,-0.234183,0.161065,0.168006,-0.019110,-0.129239,0.076792,-0.328619,0.230051', '3811356', 