INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2138418', '咒怨3(美版)', '恐怖', '杰克•金伯勒（Matthew Knight 饰）一家的血腥灭门惨案轰动全芝加哥，而杰克本人也在严密监视的精神病院近乎病房中被残忍杀害。从此，金伯勒家所在的公寓成为全城闻名的凶宅，住户纷纷搬离此地。只有公寓管理员麦克斯（Gil McKinney 饰）和他的妹妹萝丝（Jadie Hobson 饰）、侄女丽莎（Johanna Braddy 饰）坚持住在这里。年幼多病的萝丝似乎能够看到那名面色惨白的男孩，麦克斯的状态也变得越来越怪。加耶子的妹妹直子（Emi Ikehata 饰）通过报纸来到这座公寓，她知道加耶子的怨念还没有终结，这个恶灵新的杀戮才刚刚开始……©豆瓣', '玛丽娜·赛提斯', '托比·维尔金森', 5.6, 5920, 'tt1053859', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1789367060.jpg', 8.8, 27.5, 44.6, 12.6, 6.6, '0.438615,0.110370,-0.743371,0.312512,0.065730,-0.197944,0.971496,0.202186,-0.433940,-0.448553,0.426219,0.702790,-0.095721,0.506024,0.164637,0.097172,-0.192412,-0.365482,-0.344721,-0.286763,-0.241026,-0.330113,-0.301672,-0.161316,0.230419,-0.370493,0.483479,0.285811,-0.012124,0.452785,0.338524,0.348526,-0.183753,0.248177,-0.116676,-0.099248,0.085719,-0.119400,-0.177658,0.108831,-0.252815,-0.204971,0.075664,0.281471,-0.031955,0.393266,0.764755,-0.110999,-0.285698,-0.070628,0.455141,-0.049860,-0.325779,0.354081,0.513810,-0.352734,0.177808,0.095832,-0.415212,0.092699,-0.040660,-0.002869,-0.677343,0.139304,0.365729,0.163584,-0.284032,0.286743,-0.174252,-0.185283,0.057171,-0.396253,0.323484,0.212951,-0.004673,0.545781,-0.180465,0.049402,-0.510730,-0.015184,0.307554,-0.405693,-0.114207,0.295904,-0.167279,-0.396236,0.013743,-0.217876,-0.533989,-0.076293,0.193609,0.013324,-0.146042,0.041429,-0.539303,-0.305224,-0.305687,-0.298156,-0.122143,-0.207856,-0.278664,-0.721079,-0.300558,-0.305809,0.050603,0.157187,-0.241711,-0.136740,0.437702,-0.674210,0.343374,0.321381,0.449499,-0.455447,0.442482,-0.089360,0.199913,0.127314,-0.359157,0.521227,0.216049,0.531534,0.081992,0.242810,0.001079,-0.228089,-0.294748,0.554605', '21619567', '1316693', '10466639', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2138838', '美国队长', '动作', '上世纪40年代，纳粹及其邪恶轴心的战火烧遍世界各个角落。居住在布鲁克林的小个子史蒂夫·罗格斯（克里斯·埃文斯 Chris Evans 饰）心系国家，一心上阵杀敌，可是糟糕的体格让他始终被征兵办拒之门外。偶然的机会，在德籍科学家厄斯金博士（Stanley Tucci 饰）的帮助下，这个小个子男孩得以走入兵营，并接受了博士的试验，化身成为高大健壮、膂力过人的超级战士。与此同时，德国纳粹红骷髅部队的首领约翰·施密特（雨果·维文 Hugo Weaving 饰）依靠超自然的力量建立起一支超级战队，企图称霸全世界。为了营救好友，史蒂夫以美国队长的形象闯入施密特的军营，正邪两大超级战士的战斗就此展开……©豆瓣', '克里斯·埃文斯', '乔·庄斯顿', 7.1, 352379, 'tt0458339', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1182659238.jpg', 1.2, 6.7, 41.6, 35.4, 15.2, '0.184203,0.050968,-0.531333,0.389120,-0.133960,-0.284317,0.413303,0.045767,-0.383558,-0.279188,0.423718,0.602946,0.251989,-0.034598,0.222728,-0.161192,-0.200107,-0.569254,-0.245590,0.127580,-0.179800,-0.434832,-0.580619,-0.342841,0.011280,-0.527773,0.882300,-0.153810,-0.301162,0.135536,0.232527,0.457226,0.110517,0.247526,-0.062753,-0.211032,0.281612,-0.404401,-0.449921,0.326463,-0.491857,0.071843,0.040100,0.047278,-0.199027,0.081796,0.508817,-0.522503,0.251911,-0.453761,0.273409,-0.098743,-0.221519,-0.098413,0.447817,0.016504,0.001119,-0.003407,0.414874,0.009783,-0.017156,-0.160551,-0.655183,-0.008515,0.314865,0.246408,-0.633902,0.373789,-0.155883,0.209768,0.091751,-0.106183,-0.047372,0.261351,0.226693,0.179330,-0.001993,0.290922,-0.490934,0.143192,0.332560,-0.008859,-0.435444,-0.404024,-0.214556,-0.383232,-0.095904,-0.395413,-0.372955,-0.188565,0.177240,-0.253058,0.077640,0.263996,-0.766406,0.138298,-0.412549,-0.087288,0.031718,-0.088199,-0.015242,-0.878802,0.114874,0.050176,-0.199268,0.094446,0.004631,-0.167244,0.773147,-0.645631,0.041265,0.505637,0.233275,-0.173638,0.484768,-0.066109,0.188213,-0.317374,-0.250994,0.556793,0.189415,0.325332,-0.090672,0.233356,-0.210834,-0.278523,-0.111456,0.467467', '2369613', '10439358', '1322847', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2139553', '鼠来宝', '剧情', '戴维·塞维尔（杰森·李 Jason Lee 饰）是洛杉矶一名郁郁不得志的词曲作者，他不分白天黑夜，努力创作，但作品总也得不到唱片公司老板的赏识。某天，满腔愤怒的戴维在家中大发雷霆，这时，三只来自大山的花栗鼠艾尔文（贾斯汀·朗 Justin Long 配音）、西蒙（马修·格雷·古柏勒 Matthew Gray Gubler 配音）、西尔多（杰西·麦卡尼 Jesse McCartney 配音）闯入戴维的生活。戴维惊讶地发现，这三个顽皮胡闹的小家伙不仅会说话，而且还能和声唱歌。于是他和小家伙们达成协议，它们可以在家中居住，但是必须演唱戴维创作的歌曲，妙趣横生的故事也由此展开……本片荣获2008年儿童选择奖最受欢迎电影。©豆瓣', '杰森·李', '蒂姆·希尔', 7.6, 63478, 'tt0952640', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456298793.jpg', 0.6, 3.1, 31.9, 46.1, 18.4, '-0.032248,-0.150258,-0.575623,0.614978,0.169649,-0.424363,0.647357,0.125222,-0.339797,-0.254336,0.049796,0.633418,-0.206377,0.465159,0.232960,-0.064373,-0.461286,-0.422736,0.149478,0.058530,0.255571,-0.367686,-0.005628,-0.506276,-0.142856,-0.193644,0.330114,-0.257588,-0.232106,0.439253,0.454059,0.074802,-0.032805,0.240399,0.060870,0.076648,0.360757,-0.179469,-0.013140,0.057070,0.034815,0.144663,-0.470197,-0.125129,0.445877,0.160499,0.424514,-0.033760,-0.114893,0.147187,0.487256,-0.197651,0.148120,0.012511,0.109112,-0.137002,0.378185,0.088071,-0.008858,0.197596,-0.173522,-0.103519,-0.704655,0.078862,-0.116434,0.230328,-0.375345,0.066531,0.013847,-0.040136,0.065227,-0.436715,0.003934,0.206473,0.269162,0.375133,-0.040965,0.255460,-0.544831,0.254354,0.338693,0.004014,-0.403858,0.174916,-0.149366,-0.590975,-0.160196,-0.084850,-0.762478,-0.061316,0.400670,-0.041702,0.118258,-0.056566,-0.420123,-0.170281,0.063259,-0.403926,-0.046913,-0.253939,-0.089935,-0.729123,0.006564,-0.263566,-0.340532,-0.307690,0.084832,-0.261829,0.965683,-0.589080,0.146000,0.450293,0.128936,-0.132666,0.529091,0.322587,-0.004047,-0.022468,-0.277541,0.362980,-0.039440,-0.059624,0.143442,0.290296,0.223799,-0.368765,-0.485171,0.435990', '27602116', '26348103', '3318306', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2139766', '暖春', '剧情', '在一个偏远的小山村里，村长的儿子捡来了一个晕倒的女孩，村民们都议论纷纷。宝柱的爹（田成仁 饰）年事已高，他费力的背起这个小女孩回家了。宝柱顿觉没了面子，他认为他的爹不满过门多年的媳妇香草（郝洋 饰）至今都没生下一子半女。女孩叫小花（张妍 饰），受不了家里人的虐待而离家出走。她乞求爷爷能收养她，宝柱的爹疼惜这个女孩，便不管儿子媳妇的不满收留了她。小花的乖巧懂事令爷爷倍感安慰，可是香草却非常眼红，竟然安排骗走小花。小花一直想有个妈妈，她非但没有怨恨叔叔跟婶娘对她的伤害，一次一次用自己的真诚善良感动宝柱跟香草。©豆瓣', '田成仁', '乌兰塔娜', 8.1, 34641, 'tt1054024', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2356969151.jpg', 1.6, 3.2, 19, 41.2, 35, '0.059056,-0.276716,-0.801405,0.449658,-0.736195,-0.490015,0.465710,0.102121,-0.564022,0.059177,0.497859,0.573367,0.077344,0.498391,-0.482175,0.430417,0.118989,-0.113175,0.258280,0.152098,-0.103845,-0.276915,-0.044572,-0.146093,-0.088758,0.025068,-0.214700,-0.538217,0.099423,0.497481,0.111612,-0.199873,0.269042,0.389208,-0.333131,0.704967,-0.023042,0.124699,0.140534,-0.238165,0.132159,0.064593,-0.199465,0.088525,0.190594,0.400606,0.579318,-0.231762,-0.205299,-0.196692,0.310554,-0.158089,0.024879,0.385024,-0.022763,-0.263116,0.431672,-0.168941,-0.206206,-0.283485,0.158261,0.227663,-0.380290,0.383216,0.056613,-0.023196,-0.981767,0.600874,0.032112,-0.017440,0.040327,-0.735213,0.221833,0.141870,-0.386807,0.704130,-0.533232,0.177043,-0.274739,0.344924,0.418456,-0.195197,0.178621,0.294104,-0.417756,-0.007251,0.659575,-0.245349,-1.066931,0.244385,0.251869,-0.221756,-0.425771,0.023761,-0.215194,0.114833,-0.273272,0.026417,0.019157,-0.594323,-0.197012,0.537360,-0.030844,-0.288422,-0.473210,-0.099750,-0.064569,-0.065450,0.973715,-0.415875,0.384642,0.328875,0.374420,-0.724300,0.480796,0.513654,-0.238478,-0.181752,-0.013944,-0.034423,-0.371989,0.046051,0.506612,0.327207,0.120164,-0.191474,-0.117386,0.059739', '26348103', '24879820', '1415573', '1291565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2141771', '女座头市', '剧情', '日本，幕府时代，流浪中的瞽女（抚琴卖艺的盲人女子）市（绫濑遥饰）在大雪中被人收留，收留她的男子心怀不轨，不想市一剑就将其刺伤。原来市深怀绝世剑法，流浪四方，目的是寻找一名男性盲人剑客。市在途中与貌似胆小的落魄剑客十马（大泽隆夫饰）相识，二人结伴来到了一个村镇。这里有名为万鬼党的流氓团伙作恶，市轻易杀掉几个恶人，但十马却被当地人误会为英雄，十马被当地人为保镖。万鬼党的复仇随之而来，小镇面临一场腥风血雨。市与十马不仅要拯救大家的性命，还从万鬼党中得知了一直寻找的剑客的消息。©豆瓣', '绫濑遥', '曾利文彦', 6.5, 6759, 'tt1060256', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p699847631.jpg', 2, 12.4, 53.2, 25, 7.4, '0.224847,-0.117832,-0.354710,0.445870,-0.078198,-0.024085,0.482607,-0.134425,-0.577095,-0.337378,0.324887,0.951023,0.011674,0.272344,0.353962,-0.142201,0.185500,-0.638266,-0.237327,-0.197574,-0.300987,0.075460,-0.304522,-0.084495,-0.378448,-0.067564,0.511155,0.487794,-0.112754,0.506853,0.291361,0.436038,-0.607000,0.362956,-0.459455,-0.204304,0.217649,-0.030323,-0.182456,0.594860,-0.460403,-0.545810,-0.016359,0.157538,-0.293791,0.405077,0.755980,0.044637,0.050509,-0.388273,0.130271,-0.309942,0.009052,-0.012215,0.505092,-0.311581,0.408320,0.181218,-0.120204,-0.174675,0.091704,-0.333438,-0.575835,0.079215,0.529887,-0.005277,-0.753803,0.322106,-0.067632,-0.300577,-0.056642,0.028529,0.585090,0.156100,0.374311,0.132726,0.090548,-0.130270,-0.498395,0.341885,0.952159,-0.034275,-0.069920,-0.135381,0.103560,-0.327513,0.306964,-0.424210,-0.279999,0.020755,0.121723,-0.173752,-0.286665,0.032036,-0.417257,-0.079101,-0.412087,0.155237,-0.119652,-0.254957,-0.323678,-0.356432,0.156474,-0.087576,0.062531,0.284642,0.293823,0.086695,0.668673,-0.850726,0.206632,0.638681,0.370646,-0.527166,0.783802,-0.181247,0.156963,-0.189634,-0.073877,0.113336,0.304811,0.246443,-0.098651,0.110380,-0.411355,-0.227022,-0.238319,0.256545', '1296978', '25721544', '35030151', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21441132', '爱丽丝梦游仙境2：镜中奇遇记', '奇幻', '爱丽丝（米娅·华希科沃斯卡 Mia Wasikowska 饰）为了拯救挚友疯帽子（约翰尼·德普 Johnny Depp 饰）而重返仙境，她与白皇后（安妮·海瑟薇 Anne Hathaway 饰）及一群老朋友一起，展开了一段璀璨华美、永生难忘的奇幻冒险。然而除了邪恶的红皇后之外，爱丽丝还要面对另一位劲敌——时间（萨莎·拜伦·科恩 Sacha Baron Cohen 饰），他是传说中无人能击败的角色！爱丽丝要如何才能扭转乾坤，拯救疯帽子和仙境世界？影片改编自路易斯·卡罗尔广受好评的同名原作。', '约翰尼·德普', '詹姆斯·博宾', 7, 166294, 'tt2567026', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2349374680.jpg', 1.2, 7.9, 43.7, 33, 14.2, '-0.283722,0.401282,-0.050932,0.676573,0.147391,-0.214401,0.641137,0.157316,-0.339738,-0.183831,0.227515,0.663683,-0.271126,0.086309,0.290466,0.185109,-0.669690,-0.492431,0.055369,-0.211501,-0.189124,-0.264509,-0.545950,-0.075851,-0.126776,-0.398892,0.474809,-0.110933,-0.020440,0.150896,0.552029,0.305682,-0.414373,-0.042213,-0.285825,-0.234410,0.214169,0.116337,-0.629180,0.358460,-0.130706,0.268982,-0.388492,0.271805,-0.193385,-0.250869,0.173530,-0.287111,0.327755,-0.383439,0.318783,-0.092147,0.075011,-0.026607,0.054755,-0.358703,0.382449,0.001900,0.267424,0.122980,0.392035,-0.322798,-0.698484,0.443820,0.251038,0.288514,-0.188088,0.104765,-0.149450,-0.028802,0.438539,-0.137680,-0.065492,0.001424,0.572134,0.195990,-0.124243,-0.031655,-0.374441,0.526261,0.395585,-0.013967,-0.180160,0.180484,-0.124592,-0.265494,-0.091840,-0.291868,-0.549874,0.198920,0.464371,-0.187282,0.262339,0.410595,-0.519445,-0.175424,-0.518229,0.026432,-0.268452,-0.253403,-0.060795,-0.591587,-0.119998,-0.213337,-0.021056,0.015508,0.350330,-0.322409,0.523677,-0.364184,0.273466,0.216899,-0.010535,-0.239398,0.632412,0.155729,0.078567,-0.356786,-0.043246,0.692289,-0.059016,0.102272,-0.303539,0.097070,-0.057716,-0.104276,-0.491716,0.374991', '26647163', '4301278', '3318306', '25731059');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2144242', '科洛弗档案', '科幻', '好友罗布（迈克尔•斯达-大卫 Michael Stahl-David 饰）要去日本工作，他的弟弟杰森（迈克•沃格尔 Mike Vogel 饰）和朋友莉莉（杰西卡•卢卡斯 Jessica Lucas 饰）为他举办了一场欢送派对。看到杰森拎着DV只顾拍摄美女玛莲娜（丽兹•卡潘 Lizzy Caplan 饰），莉莉很恼火，指出他更加关注罗布，因为后者才是今天的主角。罗布姗姗来迟，并且感到没落。原来他跟好友贝丝（奥黛塔•雅丝曼 Odette Yustman 饰）的地下情刚刚告吹，这令他异常沮丧。正在此时，贝丝携新男友出现在派对现场，这令好友感到既尴尬又愤怒，而真正的地震危险正在悄悄逼近……本片故事是采用伪DV风格的拍摄而成。©豆瓣', '丽兹·卡潘', '马特·里夫斯', 7.3, 82643, 'tt1060277', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1334135449.jpg', 1.8, 6.1, 33.9, 42.1, 16.1, '0.098854,-0.214486,-0.640234,0.253013,0.314579,-0.265717,0.729159,0.301782,-0.518587,-0.303867,0.291569,0.603809,-0.518146,0.083448,0.546311,0.149316,-0.563296,-0.361837,0.037575,0.093957,0.058818,-0.400046,-0.260790,-0.231728,0.008183,-0.351189,0.219189,-0.380385,-0.069537,0.748372,0.473616,0.517641,-0.028864,0.582057,0.283184,-0.021270,0.340255,-0.038866,-0.320792,-0.061315,0.153314,0.035412,-0.167749,0.440255,0.061309,0.362701,0.511751,-0.038969,0.016037,0.075255,0.166945,-0.274831,0.090901,0.008759,0.117308,-0.078715,0.260919,-0.109576,-0.045774,0.008120,0.064297,-0.055828,-0.375468,0.539392,0.123858,0.319304,-0.225959,0.325636,-0.388257,0.000803,0.378199,-0.458106,-0.023647,0.241459,0.347639,0.315405,0.049509,-0.037214,-0.146328,0.127096,0.508258,0.101221,0.264035,0.524701,-0.212013,-0.245230,0.145067,0.084623,-0.664753,-0.020145,0.318249,-0.075969,0.235375,0.248878,-0.510244,-0.274733,-0.250440,-0.161724,-0.068477,-0.378665,-0.024646,-0.798987,-0.048855,-0.334083,-0.133041,-0.417046,-0.194162,-0.315376,0.334845,-0.803663,0.224953,0.434051,0.065419,-0.141401,0.347054,0.192034,-0.078071,-0.307376,-0.364177,0.244539,-0.110563,0.039104,-0.079105,0.161074,0.126884,-0.295277,-0.257831,0.386289', '1301686', '4896894', '1819460', '25856453');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21442760', '最长的旅程', '剧情', '卢克（斯科特·伊斯特伍德 Scott Eastwood 饰）是一名职业牛仔，他年轻气盛，身强体壮，充满了阳刚之朝气，周身散发着迷人的男性荷尔蒙气味。某日，卢克在一场牛仔竞技比赛中邂逅了名为苏菲亚（布丽特妮·罗伯森 Brittany Robertson 饰）的女孩，俊男美女之间，霎时间便燃起了熊熊的爱情的火焰。然而，他们一个是奔放粗犷的牛仔，一个是细腻文艺的大学生，性格上的差异和对未来的不同规划令两人之间的矛盾愈演愈烈，渐渐走上了两条不同的道路。就在此时，两人在一场意外之中解救了一位名为伊拉（杰克·休斯顿 Jack Huston 饰）的老人，在听闻老人讲述了自己和妻子露丝（奥娜·卓别林 Oona Chaplin 饰）之间浪漫而又伤感的爱情故事后，卢克和苏菲亚对他们的感情重新燃起了希望。©豆瓣', '布丽特·罗伯森', '小乔治·提尔曼', 7.4, 13419, 'tt2726560', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2218476421.jpg', 0.9, 5, 36, 38.8, 19.3, '0.490751,-0.102196,-0.636168,0.745105,-0.101123,-0.326283,1.204563,0.210933,-0.551529,0.082336,0.232826,0.852949,-0.515452,0.174801,0.447865,0.057763,-0.180869,-0.792557,-0.265733,-0.046128,-0.133523,-0.460970,-0.355264,0.100879,-0.040156,-0.668930,0.658165,-0.149648,-0.092802,0.951682,0.474482,0.199059,-0.102597,0.449208,-0.045206,-0.157913,0.282896,0.073455,-0.036866,0.153649,0.128802,-0.132603,-0.039164,0.190798,-0.427638,0.567334,0.813999,-0.187841,0.085672,-0.019575,0.247637,0.121421,0.124429,0.247027,0.139382,-0.083676,0.215578,0.143298,-0.041350,-0.223526,0.036230,-0.159521,-0.330647,0.167110,0.111791,0.556235,-0.532678,0.852766,0.105213,-0.496076,0.369960,-0.122461,0.090036,0.009161,0.296859,0.485219,0.123331,-0.045369,-0.287999,0.116471,0.652135,0.244617,-0.357086,0.544796,-0.804810,-0.365581,-0.270452,0.192008,-0.726864,-0.334569,0.529968,-0.011160,0.187505,0.303336,-0.977480,0.146590,-0.071038,0.074460,-0.186824,-0.266153,0.043390,-0.567357,-0.443752,-0.711657,-0.272174,0.156800,0.184529,-0.129280,0.784299,-1.001097,0.148498,0.375772,-0.001731,-0.108579,0.523129,0.096604,0.231999,-0.249434,-0.098280,0.230712,-0.229607,-0.025156,0.090456,0.925085,-0.243922,0.050566,-0.374879,0.668790', '20020577', '1292062', '24839498', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21447058', '真命天子', '喜剧', '玛莎经历了渣男出轨后失恋，在这段痛苦的期间遇到了一个男人，几乎是一见钟情，两人在第一次见面时男人就向她提出了约会邀请。他告诉她自己几分钟前刚杀了人，她以为他在开玩笑。他似乎很适合她，就像一个完美的恋人。然而，随着他们的关系的发展，她发现他的不寻常，她甚至不知道他的名字，但他的风趣和疯狂却令她着迷...', '山姆·洛克威尔', '帕科·卡贝萨斯', 6.6, 8213, 'tt2091935', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2318037080.jpg', 2.6, 12.5, 47.8, 26, 11, '0.507091,-0.124923,-1.204761,0.710253,-0.554315,-0.198571,1.090456,-0.294853,-0.330926,-0.191743,0.252069,0.886580,-0.374648,0.196184,0.107073,0.337574,0.108081,-0.861414,0.217480,-0.135908,-0.229424,-0.407693,-0.272180,-0.174475,-0.043454,-0.269858,0.368236,-0.175774,-0.323151,0.334013,0.241794,-0.105726,0.242929,1.120114,-0.279278,0.114000,0.102730,0.418168,0.126436,0.049803,0.213742,-0.303211,-0.124990,0.455725,-0.232602,0.625846,0.474667,-0.133607,-0.548225,0.208647,0.474139,-0.280956,-0.107330,0.372252,0.236821,-0.186247,0.264417,0.085507,-0.154851,-0.277941,-0.007977,0.243304,-0.512807,0.239526,-0.169625,0.174460,-0.623947,0.839310,-0.130871,-0.006652,0.208969,-0.401879,0.194840,0.383938,0.245616,0.255390,-0.171393,-0.169866,-0.748156,0.400245,1.203687,0.337199,-0.599859,0.817457,-0.228240,-0.467541,-0.304459,-0.011146,-0.783071,0.112657,0.102815,-0.097762,-0.750585,0.034681,-0.237207,0.040012,0.011675,0.106299,-0.210482,-0.478211,0.007696,-0.297849,-0.286942,-0.805181,-0.633765,-0.143476,-0.257729,-0.648480,0.599699,-1.047919,0.103793,0.905898,0.562559,-0.705023,0.950283,0.491181,-0.318581,-0.240620,0.054300,0.200550,0.022522,-0.041139,0.458537,0.707115,0.239861,0.252875,-0.413553,0.812752', '26718282', '1292064', '4275444', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2146939', '从普拉达到纳达', '剧情', '影片是简·奥斯汀的经典小说《理智与情感》的拉丁版本。故事背景为现代的洛杉矶。姐姐诺拉·多米格兹（卡米拉·贝尔 Camilla Belle 饰）是一家法学院的学生，妹妹玛丽（阿丽夏·维加 Alexa Vega 饰）肄业在家，惟一在乎的就是购物和参加派对找乐子，她们和父亲一起在比佛利山过着极度奢华享受的生活。玛丽拒绝承认与生俱来的墨西哥血统当父亲突然过世之后，豪华的生活方式也就随之消失了。姐妹俩不仅变成了穷人，还被迫搬离现在的居所，搬到关系疏远的姑姑奥莉娅（阿德里安娜·芭拉扎 Adriana Barraza 饰）家中——位于洛杉矶东部博伊尔高地的一个以拉丁美洲人为主的社区。姐妹二人都感到非常地惊恐，她们既不会说西班牙语，也缺少应该具备的责任感，但是她们别无选择，只能慢慢地改变自己去适合一个全新的生活环境，把高档的跑车变卖掉，和普通人一样去搭乘公共汽车……最终诺拉和玛丽是否可完全融入到了这个一直以来都被她们拒绝接受的文化根源？', '卡米拉·贝勒', 'Angel Gracia', 6.1, 10826, 'tt0893412', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p820466376.jpg', 2.9, 16.6, 56.4, 19.8, 4.2, '0.416204,-0.045300,-0.687953,0.637673,-0.126297,-0.327358,0.652424,0.321481,-0.423393,-0.343106,0.050849,0.907507,0.031315,0.275710,0.353178,0.203107,-0.456263,-0.427269,0.083858,-0.115718,-0.123438,-0.533360,0.053964,-0.210864,-0.034517,-0.301262,0.419736,-0.077162,-0.209220,0.406800,0.133269,0.250814,0.016710,0.373209,-0.062384,-0.096514,-0.052792,0.057186,-0.357366,0.114326,0.048909,0.203335,0.004639,0.073485,0.347629,0.140457,0.643579,-0.187608,0.017316,-0.023201,0.288833,0.012269,-0.027473,0.113049,0.154546,-0.259974,0.260494,0.173753,-0.117391,0.059601,0.089160,-0.104078,-0.633737,0.219634,0.255133,-0.085527,-0.590918,0.484622,-0.011626,-0.372759,-0.077136,-0.456675,0.250524,0.121141,0.101684,0.508215,-0.062819,0.090507,-0.535585,-0.065644,0.718494,0.017582,-0.302865,0.253118,-0.442581,-0.379553,-0.186496,-0.368206,-0.510462,-0.130603,-0.014260,0.065531,-0.188453,0.208092,-0.726040,0.056363,-0.235057,-0.308193,0.224848,-0.510583,0.194133,-0.678145,0.068061,-0.503822,-0.161939,-0.093152,0.091580,-0.291339,0.637123,-0.695536,0.226470,0.453260,0.462711,-0.619842,0.618697,0.067392,0.214543,-0.193144,-0.188178,0.424936,-0.030566,0.124241,-0.004108,0.266036,0.135147,0.0217