INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2147836', '青蜂侠', '喜剧', '养尊处优的布里特•瑞德（塞斯•罗根Seth Rogen 饰）在父亲忽然离世之后，不得不开始经营庞大的报业集团。然而父亲的员工加藤（周杰伦 饰）出现，却让布里特的生活发生了彻底的改变。加藤不仅能磨制出美味的咖啡，而且还是空手道大师，更令人称奇的是，他是一名出色的机械师。加藤制造了一部无坚不摧的战车“黑美人”，自此，俩人驾驶着“黑美人”打着“青蜂侠”的名号，开始在夜幕下的洛杉矶打击各种犯罪。“青蜂侠”的名号大震，报业集团也因大幅报道各种“青蜂侠”的消息而发行量大增。可是，为了争得美女秘书丽诺尔（卡梅隆•迪亚茨Cameron Diaz 饰）青睐，两个男人之间产生心结并最终决裂。“青蜂侠”的行动威胁到了洛杉矶黑道大哥查德诺夫斯基的势力，他决定不借任何代价铲除“青蜂侠”。危机重重之际，布里特父亲意外身亡的真相也逐渐浮出水面，布里特与加藤能否再度联手惩治邪恶，让人充满期待……《青蜂侠》的故事起源于20世纪30年代的美国，70年代华裔影星李小龙正是凭借电视剧版《青蜂侠》典定其演艺事业的根基。这是《青蜂侠》第一次被搬上大银幕，也是华人明星周杰伦的好莱坞处女秀。', '塞斯·罗根', '米歇尔·贡德里', 5.8, 78362, 'tt0990407', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p759558937.jpg', 7, 24.3, 47.7, 14.8, 6.2, '-0.043245,0.141947,-0.361383,0.520081,0.283406,-0.193949,0.400797,0.361447,-0.443866,-0.224934,0.257357,0.674659,-0.163595,0.174559,0.221918,0.011241,-0.119691,-0.562589,0.004937,-0.037078,0.116223,-0.324955,-0.268297,-0.226151,-0.074204,-0.379805,0.618521,0.201422,-0.278068,0.229415,0.553154,0.235727,-0.063562,0.354062,-0.031329,0.022691,0.095741,-0.100313,-0.347347,0.179275,0.029439,-0.329991,-0.016181,0.323567,-0.207486,0.149506,0.369800,-0.222380,-0.111634,-0.225986,0.441116,-0.129960,-0.075649,-0.244890,0.390466,-0.201014,0.264844,0.204287,-0.051102,-0.158144,0.092079,0.047429,-0.778269,0.106457,0.298593,0.187427,-0.556891,0.357839,-0.272343,-0.023222,-0.027422,-0.057230,0.118097,0.208532,0.356551,0.177364,-0.041283,0.211850,-0.376033,0.196922,0.609445,-0.046668,-0.377176,0.169179,-0.055927,-0.296121,-0.322380,-0.318052,-0.280780,-0.001238,0.424556,-0.099817,-0.081365,0.349721,-0.467327,-0.013158,-0.312691,0.026189,0.164884,-0.188726,0.014166,-0.729914,-0.167322,-0.364410,-0.020689,-0.013177,0.155805,-0.237641,0.809015,-0.790821,0.089599,0.474301,0.074998,-0.226216,0.452954,-0.176063,-0.157228,-0.234057,-0.443307,0.224998,0.041059,0.062363,-0.059290,0.194084,0.105704,-0.405470,0.095643,0.236189', '27602116', '4301278', '1793491', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2147854', '好好先生', '喜剧', '已过而立之年的卡尔·阿伦（金·凯瑞 Jim Carrey 饰）虽然衣食无忧，但他的人生可谓失败透顶。三年前和妻子离婚，始终过着单身生活。他在银行工作，不过基本呈混吃等死、升迁无望的状态。生活中他拒绝和他人交往，反而更愿意窝在家里看电影，整个人生仿佛被灰色的浓雾所笼罩。在 朋友的建议下，卡尔来到一家名为“好好先生”的机构作咨询，在导师泰伦斯（特伦斯·斯坦姆普 Terence Stamp 饰）的指引下，他尝试对生活中每一个问题都以肯定的方式回答。这小小的改变令卡尔的人生天翻地覆，荣誉、金钱、机遇、爱情接踵而来，正当他信心满满之时，却发现人生并非像他想得如此简单……本片改编自英国喜剧演员、作家丹尼·华莱士（Danny Wallace）的同名自传，并荣获2009年MTV最佳喜剧表演奖（Jim Carrey）。©豆瓣', '金·凯瑞', '佩顿·里德', 7.8, 102204, 'tt1068680', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2166491697.jpg', 0.2, 2, 27.4, 49.2, 21.2, '-0.011998,0.072329,-0.622195,0.599557,0.087184,-0.292190,0.651296,0.173574,-0.458897,-0.264933,-0.033283,0.701471,-0.088154,0.169822,0.348257,-0.360741,-0.371171,-0.617342,0.009117,-0.038076,-0.016440,-0.381255,-0.166902,-0.038118,-0.313594,-0.165424,0.727248,0.014485,0.057491,0.274830,0.268955,0.118733,0.260947,0.428171,-0.060261,0.037709,-0.039849,0.290789,-0.543027,0.221145,0.082268,-0.149821,-0.115189,0.246309,0.098021,0.230077,0.381704,-0.274561,-0.289448,-0.015925,0.395296,-0.197759,-0.155290,0.133090,-0.012523,0.026245,0.273429,0.223032,-0.047928,0.171516,0.018297,-0.088749,-0.756123,-0.048788,0.041621,0.115688,-0.448243,0.386193,0.099478,-0.055442,-0.225866,-0.220630,-0.020104,0.164198,0.398029,0.246723,-0.256455,0.216713,-0.383322,0.375365,0.570050,0.063148,-0.504833,0.437500,-0.273166,-0.410389,-0.050689,-0.148301,-0.358376,-0.079948,-0.059239,0.216051,-0.138770,0.201966,-0.527681,0.251429,-0.055050,-0.106747,-0.029784,-0.536736,-0.022165,-0.450810,-0.051048,-0.300752,-0.574788,0.024520,0.069182,-0.509754,0.259107,-0.639429,0.192389,0.314994,0.247354,-0.368666,0.751614,0.321217,0.155105,-0.290200,-0.143346,0.638479,-0.053367,0.221786,-0.085331,0.107687,0.156600,-0.140209,-0.357141,0.713834', '26834930', '1303034', '1304641', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2147872', '德古拉元年', '剧情', '15世纪中叶，作风彪悍残忍的穿刺王弗拉德（卢克·伊万斯 Luke Evans 饰）在土耳其苏丹的扶持下回到故乡特兰西瓦尼亚，建立起一个和平祥和的国家。然而此时此刻他仍受制于土耳其苏丹王穆罕默德（多米尼克·库珀 Dominic Cooper 饰），苏丹要求弗拉德献上一千个男孩充军，包括他儿子在内的孩子们都将成为嗜血统治者的牺牲品。不愿孩子重走自己当年血腥之路的弗拉德奋起反抗，屠杀使者。为了赢得战争的胜利，他闯入神秘而恐怖的断牙山，期望借助传说中的怪物之手击退土耳其的入侵者。他为了国家不惜抛弃良知和灵魂，由此注定了千古悲剧的开始。吸血鬼德古拉的传说由此上演……©豆瓣', '卢克·伊万斯', '盖瑞·肖', 6.4, 28141, 'tt0829150', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2202249262.jpg', 2.2, 14.5, 53.3, 22.8, 7.1, '0.005386,0.337030,-0.714482,0.592271,-0.171476,-0.133881,0.562129,-0.051473,-0.337806,-0.171300,0.397895,0.648806,0.176392,-0.274070,0.356350,-0.138886,-0.114974,-0.471106,-0.318694,0.163707,-0.091561,-0.293225,-0.466770,-0.448156,-0.170529,-0.403302,0.779165,0.261904,-0.355735,0.137346,0.353878,0.517603,0.053124,0.107915,-0.074698,0.023303,-0.162325,-0.201602,-0.488833,0.149940,-0.243172,0.061325,-0.207200,0.312376,-0.336759,0.298569,0.466838,-0.821214,0.445140,-0.754212,0.422744,-0.402640,-0.168817,0.339645,0.098625,-0.084453,0.072687,0.315782,0.219082,-0.364243,0.193686,-0.149790,-0.752714,0.021850,-0.070293,0.085156,-0.411130,0.442940,-0.120495,0.197217,0.326874,-0.145834,0.104072,0.430511,0.426444,0.363507,-0.080718,0.087193,-0.493644,0.099753,0.887012,-0.272677,-0.424840,-0.166454,-0.259360,-0.375662,0.004097,-0.636234,-0.472805,-0.140801,0.452321,-0.089369,0.100826,0.816036,-0.692708,-0.310240,-0.441817,-0.068803,0.302816,-0.249916,-0.053096,-0.303278,-0.195633,0.002386,-0.097916,0.137284,0.099943,-0.311224,0.734182,-0.512872,0.273650,0.469256,0.442339,-0.400565,0.532208,0.127770,0.059783,-0.226021,-0.213052,1.013250,0.455214,0.188029,0.055636,-0.032785,-0.129114,0.126841,-0.001208,0.622168', '3001114', '1763916', '26667010', '4889554');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2147874', '燃烧的平原', '剧情', '影片沿袭了吉勒莫·阿里加独步天下的多线叙事手法，通过纵横交错的情节展现了五位主角不同的生活遭遇。波特兰一个名叫西尔维亚（查理兹·塞隆饰）的女人，一直在童年时不慎犯下的罪孽阴影中不能自拔，期待与家人和解的她试图寻找新的出路；生活在墨西哥边境小镇的16岁女孩玛利亚娜，想尽办法让感情破裂的父母重归于好；一对恋人吉娜和尼克不幸陷于难以自拔的地下情之中；小女孩玛丽亚则帮助自己的父母彼此宽恕，找到真爱……这五人都在自己的痛苦中实现着自我拯救，最终找到了生活的真谛。', '查理兹·塞隆', '吉列尔莫·阿里亚加', 7.6, 6049, 'tt1068641', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2456752585.jpg', 0.5, 2.7, 29.2, 50.6, 16.9, '0.098622,-0.014740,-0.635752,0.712998,-0.085947,-0.267196,0.779314,0.100424,-0.305668,-0.143527,0.280234,0.806402,0.099464,0.549995,0.292965,-0.044606,-0.494363,-0.874139,0.052118,0.012641,-0.329130,-0.593304,-0.273174,-0.139334,-0.171069,-0.480133,0.815334,0.159817,-0.220734,0.244216,0.005428,0.338848,-0.288348,0.344008,-0.105649,0.101590,0.175601,-0.025503,-0.481124,0.040466,-0.088550,-0.171868,-0.006659,0.236163,-0.188690,0.388995,0.978714,-0.558765,0.134697,-0.089601,0.400486,-0.085156,-0.017253,0.233487,-0.050768,-0.170898,0.118395,0.257163,-0.249636,-0.129241,0.116823,-0.174290,-1.014925,-0.162468,0.326277,0.088079,-0.383198,0.411277,0.068409,-0.093885,0.400417,-0.108731,0.125862,0.348266,0.465366,0.345705,-0.459718,0.030933,-0.469339,0.109659,0.772646,-0.120084,-0.193675,0.236006,-0.418930,-0.342558,-0.059983,-0.136538,-0.593149,-0.068495,0.476782,0.000386,-0.318189,0.476856,-0.604406,-0.042365,-0.246759,-0.038023,0.053958,-0.489071,-0.195020,-0.523921,-0.292319,-0.331050,-0.241510,-0.122169,-0.107861,-0.463479,0.721060,-0.647240,0.223859,0.601661,0.101099,-0.514649,0.953295,0.239328,0.199715,-0.378497,-0.019712,0.833164,-0.179492,0.010022,0.188489,0.049164,-0.198017,0.565554,-0.560002,0.678584', '1292925', '26678784', '25928048', '30279170');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2148257', '时尚先锋香奈儿', '剧情', '1893年，因母亲去世，加布里埃尔•香奈儿的葡萄酒商父亲将她与妹妹安托妮特抛给了奥巴兹孤儿院。成年后的香奈儿（奥黛丽•塔图 Audrey Tautou 饰）与安托妮特（玛丽•吉莲 Marie Gillain 饰）一边以缝纫为生，一边在酒吧唱歌赚钱。香奈儿因一曲《小狗可可》结识了法国百万富翁艾亭奈•巴桑（贝诺特•波维德 Benoît Poelvoorde 饰），并成为了他众多情妇中的一员。在巴桑的城堡，香奈儿开始制作女帽，并与演员艾米丽安（艾曼纽•德芙 Emmanuelle Devos）成为朋友。香奈儿对取悦巴桑的生活日益不满，同时发现爱上了巴桑的好友，英国工业家阿瑟•伯邑•卡伯（亚历桑德罗•尼沃拉 Alessandro Nivola 饰）。有了伯邑的支持，香奈儿是否便能开始她一直想要的个人事业呢？本片被提名2009年欧洲电影奖观众奖。©豆瓣', '奥黛丽·塔图', '安妮·芳婷', 7.2, 78088, 'tt1035736', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p957012671.jpg', 0.5, 4.6, 43, 39, 12.9, '0.233565,-0.071652,-0.186726,0.498645,0.276428,-0.439549,0.511462,0.192614,-0.466831,-0.327860,-0.095886,0.918830,-0.311675,0.318910,0.391779,0.315797,-0.401250,-0.654341,0.152511,-0.118886,-0.071360,-0.317184,-0.091159,-0.248690,-0.183818,-0.375279,0.378261,-0.221302,-0.002502,0.510856,0.540005,0.490462,0.146728,0.237891,-0.107552,0.228685,0.207188,-0.246334,-0.382780,0.261611,0.040967,-0.304988,-0.004920,0.174947,0.401571,0.091865,0.609003,-0.216423,0.379238,-0.164593,0.338765,0.119928,0.279476,-0.096378,0.159412,-0.122973,0.187125,0.133752,-0.062838,0.011368,0.092545,-0.272611,-0.441787,-0.002514,0.108331,0.079517,-0.626857,0.298122,-0.258985,0.086011,0.160124,-0.117091,-0.073100,0.246970,0.079703,0.366210,-0.078103,-0.006324,-0.698593,0.421174,0.125374,-0.024742,0.104471,0.444473,-0.260019,-0.666336,-0.003234,0.049895,-0.407395,-0.101752,0.364881,-0.012330,0.294058,0.312550,-0.756119,-0.165645,-0.228833,-0.336484,0.171615,-0.280882,-0.143327,-0.550787,0.017384,-0.303387,-0.021845,-0.124841,-0.085598,-0.181114,0.678123,-0.768292,0.266548,0.565133,0.490343,-0.240407,0.653842,-0.082326,0.301311,-0.178228,-0.280257,0.506946,-0.033449,-0.340184,0.263464,0.255925,0.120893,-0.253975,-0.167238,0.335773', '6858739', '1292720', '