INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2148618', '缘，妙不可言', '剧情', '故事发生在九十年代的上海。薇薇（赵薇 饰演）是旅行社导游，阿虹（李绮虹 饰）是某公司职员，她们俩是一对好朋友。隆（吴奇隆 饰）来自台湾，为逃避婚姻从台北来上海音乐学院进修音乐。东（何润东 饰）是来自香港的公子哥，在上海开了一家电脑商店。一天，薇薇和阿虹到电脑商城去买电脑，在自动扶梯上不巧撞倒了对面走来的隆，隆新买的电脑翻落在地。而走在前面的薇薇全然不知，踏进东的店铺，老板东向她介绍起电脑。不久，隆和虹在他们身后出现，四人目光交错；顿产生奇妙感觉。然而，这第一面的缘份却没有发展下去。但是，星移斗转，同地同时，这奇妙一幕重演……©豆瓣', '吴奇隆', '曹建南', 5.3, 9905, 'tt0910579', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2526604809.jpg', 7.4, 30.4, 52.8, 7.4, 2.1, '0.598938,-0.299718,-0.705915,0.578542,0.152766,-0.012984,0.729844,0.487500,0.023771,-0.030344,0.425371,0.846555,-0.438544,0.268192,0.194083,0.281672,-0.302362,-0.810436,0.050736,-0.581486,-0.194123,-0.536724,0.369779,0.170861,0.119896,0.097510,0.311500,-0.049396,-0.092943,0.775055,0.185756,-0.002641,-0.588852,0.484102,-0.381314,0.297646,-0.006212,0.032109,-0.182860,0.107747,0.328091,-0.210097,-0.353632,0.165174,0.294706,0.030238,0.598473,0.016598,0.082651,0.454118,0.434371,0.043512,0.064906,-0.352507,0.455164,0.091191,0.058442,0.004681,-0.206545,-0.032611,0.005631,0.087319,-0.478446,0.264431,-0.447697,-0.034160,-0.780546,0.428922,0.043327,0.365914,-0.020419,-0.428593,0.419059,0.260652,0.184968,0.537384,0.205438,0.321191,-0.388929,-0.098454,0.642064,0.260542,-0.249117,0.861598,0.115609,-0.054523,-0.269287,0.294560,-0.648452,-0.163287,0.340472,-0.075549,-0.015378,-0.318074,-0.540168,0.180328,-0.074900,-0.358413,0.406662,0.207193,-0.449504,-0.722576,-0.313421,-0.441074,-0.238537,0.001496,-0.265998,-0.389485,0.443094,-0.766577,-0.075844,0.662513,0.484611,-0.409821,1.178957,-0.439759,-0.095740,0.074122,-0.337757,-0.077974,-0.078587,0.378965,0.147437,0.177459,-0.193108,-0.005836,-0.455744,0.077488', '3055049', '1302384', '3326747', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2148619', '离开雷锋的日子', '剧情', '乔安山(刘佩琦 饰)和雷锋是最最亲密的好战友，岂料他们在执行一次任务时，乔安山倒车时不慎将电灯柱碰倒，砸在了在车尾指挥的雷锋身上，雷锋从此离开了人间。之后乔安山后悔不已，回想起往日雷锋全心全意帮助自己的点点滴滴，乔安山不禁潸然泪下。乔安山决定在自己往后的日子里，要以雷锋为榜样，全心全意为人民服务……©豆瓣', '刘佩琦', '雷献禾', 7.2, 29287, 'tt1021085', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2165707559.jpg', 1.6, 4, 39.5, 42.2, 12.7, '0.147349,-0.177471,-0.459930,0.828415,-0.162502,-0.556525,0.466500,0.258552,-0.512925,-0.277336,-0.030863,0.825005,-0.166744,0.463052,0.300996,-0.054745,-0.295931,-0.960655,-0.067318,-0.208865,-0.508955,-0.573725,0.142289,-0.484727,-0.106987,0.040939,0.183248,0.185205,0.016107,0.510557,0.281996,0.170669,0.000013,0.581093,-0.233981,0.183644,-0.100131,0.053655,-0.407229,-0.065820,0.519555,-0.411877,-0.125397,0.221858,0.237756,0.129716,0.524037,-0.250715,-0.335747,-0.226161,0.388823,-0.419633,0.465990,0.110211,-0.069830,-0.087405,-0.101423,-0.165249,-0.286740,0.469964,0.590040,-0.358787,-0.336469,-0.159639,-0.159652,-0.401480,-1.188730,0.488609,-0.092190,0.481448,0.370860,-0.259553,0.356277,0.602108,0.321810,0.280071,-0.444444,0.079374,-0.062537,0.494725,0.652326,0.045182,0.162705,0.394059,0.175596,-0.420916,0.060572,0.051652,-0.313943,-0.197919,0.246655,-0.031934,0.184816,0.007040,-0.311073,-0.533627,0.067757,-0.041314,-0.076624,-0.214388,-0.380554,-0.325090,-0.013400,-0.345342,0.055377,0.264782,-0.309791,-0.520744,0.722540,-0.999273,-0.062880,0.184741,0.005259,-0.721522,0.717800,-0.048208,0.269203,-0.165986,0.309956,0.110443,0.179118,0.666702,0.374778,0.151425,-0.454147,0.189978,-0.061652,0.489517', '1299062', '30345227', '1293607', '1305594');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2149465', '忘掉莎拉·马歇尔', '剧情', '皮特（杰森·席格尔 Jason Segel 饰）是个音乐人，有个比他出色得多的女朋友莎拉·马歇尔（克莉丝汀·贝尔 Kristen Bell 饰），她是个当红电视明星。皮特对她一片痴心当牛做马，但还是惨遭她的抛弃。备受打击的皮特经历了很久的消沉，还要整天在电视上看到莎拉的各种新闻，为了走出失恋阴影，他跑去夏威夷火奴鲁鲁度假，却恰好在酒店遇到莎拉和她的新男友。皮特感觉命运在捉弄他，不过此时他邂逅了度假村服务员瑞秋（米娜·古妮丝 Mila Kunis 饰），后者美丽、热情，愿意倾听他的不幸，还带他进入夏威夷的火热生活。皮特慢慢爱上瑞秋，但是莎拉又和新男友闹分手了，似乎有意愿向皮特回头……©豆瓣', '杰森·席格尔', '尼古拉斯·斯托勒', 6.5, 7834, 'tt0800039', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p606338305.jpg', 1.9, 10.8, 52.6, 27.3, 7.4, '0.256067,-0.017010,-0.680466,0.320937,-0.284943,-0.283189,1.027714,0.194540,-0.334704,0.007023,0.332858,0.952787,-0.454110,0.375632,0.251458,0.639766,-0.568131,-0.544369,0.395535,-0.017505,-0.006331,-0.331648,-0.162102,-0.138822,0.059420,-0.215571,0.343064,-0.226019,-0.128149,0.393906,0.308410,0.179516,0.218099,0.676236,-0.145190,0.367926,0.058816,-0.041807,-0.011816,0.168695,0.165591,-0.149284,-0.278057,0.113058,0.221196,0.275459,0.466066,0.146580,-0.124316,0.188753,0.358836,-0.264963,0.158600,0.313816,0.116816,-0.206404,0.109953,-0.113003,-0.086296,-0.247488,0.004305,-0.001423,-0.510486,0.395710,-0.159895,0.240270,-0.534226,0.563875,-0.260046,0.126918,0.248589,-0.327437,-0.016306,0.198504,0.013353,0.325813,-0.115178,0.213100,-0.403684,0.160229,0.725221,0.349898,-0.025794,0.546618,-0.421512,-0.301358,-0.108397,-0.007068,-0.722507,-0.087747,0.504410,-0.372748,-0.107922,0.063569,-0.494493,0.020789,-0.198740,-0.243358,-0.030122,-0.336104,-0.200987,-0.687808,-0.173817,-0.646255,-0.483569,-0.290410,-0.176090,-0.470699,0.632763,-0.790247,0.268257,0.810288,0.250825,-0.582529,0.785624,0.237041,-0.182237,-0.089822,-0.053525,0.608975,-0.128778,0.151023,0.190107,0.330059,0.120496,-0.140004,-0.379955,0.571574', '1309172', '4275444', '1296534', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2149806', '入殓师', '剧情', '买了昂贵的大提琴，想要成就一番事业的小林大悟（本木雅弘 饰），经历了4个月的管弦乐演奏，得到的却是“乐团解散”的噩耗与购买乐器的高昂债务。迫不得已，大悟与妻子美香（广末凉子 饰）搬到老屋，过着清贫的日子。某日，一则广告吸引了大悟的注意：NK代理公司，帮助旅行，高薪短工时。大悟来到NK代理公司面试，社长佐佐木生荣（山崎努 饰）二话不说就决定聘用大悟，但却对工作内容避而不谈。在大悟的再三追问下，佐佐木社长终于道明：是入殓（日语Nou Kan）工作！虽然心理上有所忌惮，高额的薪水还是令大悟接受了这份工作。但这样的工作对普通人谈何容易，一方面对遗体的不适，一方面又要对妻友隐瞒自己的工作，小林大悟不平凡的工作就这样开始了。©豆瓣', '本木雅弘', '泷田洋二郎', 8.9, 622575, 'tt1069238', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2707581855.jpg', 0.1, 0.5, 8.3, 37.9, 53.1, '0.034001,-0.218630,-0.143264,0.558276,-0.167983,-0.282702,0.360860,0.250457,-0.487642,-0.498337,0.386964,0.685717,-0.187395,0.262500,0.079209,0.107864,-0.378373,-0.685563,0.058379,-0.061500,0.089970,-0.475059,-0.103830,-0.115808,-0.359292,-0.043220,0.429960,0.285709,-0.128170,0.537712,0.071627,0.336979,0.195842,0.424763,0.353004,-0.019952,0.108357,0.522380,-0.185305,0.110536,0.199860,-0.243411,-0.541047,0.310367,0.578397,0.389298,0.449711,0.155423,-0.602203,0.058621,0.489303,-0.305720,-0.055993,0.133422,0.226513,0.342780,-0.012802,0.365475,-0.685002,0.385737,-0.077799,-0.092442,-0.787887,-0.013982,-0.028229,-0.048748,-0.862988,0.425444,-0.355898,-0.152464,-0.000304,-0.335133,0.134420,0.654353,0.241191,0.437220,-0.110301,0.128448,-0.220068,0.469255,0.536169,0.093554,-0.100792,0.596857,-0.183095,-0.483447,-0.091063,-0.124054,-0.282118,-0.148503,-0.121045,0.329124,-0.037614,-0.371674,-0.496780,-0.273096,-0.137928,-0.372919,-0.020604,-0.426734,-0.064229,-0.573976,-0.146968,-0.347239,-0.216762,-0.020573,0.484334,-0.339505,0.822238,-0.838709,-0.067784,0.351682,0.123474,-0.666271,0.352191,0.158603,-0.067122,-0.434159,0.035095,0.009898,-0.181505,0.461009,-0.016915,0.007632,0.187885,-0.594098,-0.233256,0.280529', '27602116', '1299649', '1877596', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2153526', '特工绍特', '动作', '结婚纪念日当天，CIA特工伊芙琳·绍特（安吉丽娜·朱莉 Angelina Jolie 饰）受命审讯一名投案自首的俄罗斯间谍。对方声称自80年代便潜入美国，并且透露有一名间谍大师曾训练数名儿童，将他们培养成间谍送入普通的美国家庭中，伺机刺杀美国总统。令在场所有特工震惊的是，这个俄国人竟指认绍特是这群孩子中的一员。不顾CIA探员们的阻拦，绍特执意返回家中。经过一番惊险追逐，她暂时逃过昔日同伴的追捕。不久，俄罗斯总统访问美国，绍特再次卷入各种阴谋之中，而她的真实身份也变得愈加扑朔迷离……©豆瓣', '安吉丽娜·朱莉', '菲利普·诺伊斯', 7.3, 142608, 'tt0944835', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1340533548.jpg', 0.6, 4.2, 39.4, 43.5, 12.4, '0.312866,-0.071819,-0.573441,0.551797,-0.084844,-0.015284,0.386074,-0.339576,-0.538738,-0.440453,0.344692,0.718555,0.000698,0.185533,0.338644,-0.158430,-0.426317,-0.677177,-0.330305,-0.123853,-0.108496,-0.431064,-0.480563,-0.420722,-0.084942,-0.142387,0.777895,0.058578,-0.339467,0.498632,0.354972,0.407085,-0.443397,0.387787,0.010590,-0.086277,0.652600,-0.121133,-0.407190,0.156073,-0.328921,-0.333615,-0.181615,0.049522,0.089714,0.505043,0.371963,-0.094876,0.120535,-0.441789,0.453921,-0.360770,-0.195188,0.329437,0.441248,0.278360,0.032344,0.409967,-0.141153,0.073681,-0.144619,-0.000847,-0.647039,-0.077525,0.207203,0.053043,-0.287308,-0.479702,-0.100079,0.217889,0.092669,0.038709,0.319601,0.425440,0.037459,0.042054,0.304295,0.109967,-0.422816,0.425063,0.911231,-0.298973,-0.356726,-0.339933,-0.116516,-0.359400,0.460750,-0.279897,-0.327083,-0.056479,0.188613,-0.209205,-0.151082,0.352626,-0.310104,-0.177199,-0.803870,-0.202439,-0.212367,-0.001010,0.184100,-0.921885,-0.067851,-0.217493,-0.285689,0.004041,0.004281,0.085433,0.639269,-0.585920,0.265622,0.554557,0.195589,-0.635056,0.229419,0.253493,0.328974,-0.100877,-0.320740,0.517519,0.458628,0.039923,-0.347488,0.236136,0.012381,-0.361350,-0.010927,-0.283668', '2369613', '5157137', '3147969', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2153579', '黄真伊', '剧情', '16世纪朝鲜，贵族小姐黄真伊（宋慧乔饰）美丽年轻，博学多识。两小无猜的伙伴兼仆役“奴”（刘志泰饰）深爱着真伊，然而身份卑微使他出卖了真伊的身世秘密。在得知出生秘密后，黄真伊脱去了贵族小姐的华服。真伊将“奴”作为自己第一位男人后，走进了烟花巷“青桥坊”，而他也独自离去。从此，黄真伊变为妓女明月，任何人只有有钱财都可以拥其入怀，但是没有人不被她的才智貌美所征服，名妓明月成了无论贵族或贱民的男人所仰慕憧憬的对象……后来，“奴”再次出现，黄真伊需要做出什么选择？©豆瓣', '宋慧乔', '张允炫', 6, 12545, 'tt1059200', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p722809577.jpg', 3, 18.4, 56.9, 17.3, 4.3, '0.146751,0.192988,-0.359805,0.384163,-0.455733,-0.126887,0.530329,0.138027,-0.486970,-0.392790,0.255682,0.677751,0.173568,0.250170,0.231695,0.403869,-0.106274,-0.715815,-0.220425,-0.486280,-0.012446,-0.391256,0.145923,-0.374337,-0.172725,-0.282233,0.790074,0.003525,-0.074387,-0.001589,0.411764,0.211779,-0.214797,0.391071,-0.374865,0.114726,0.251038,0.008145,-0.374272,0.253003,-0.145129,-0.248410,-0.116906,0.175733,-0.214338,0.079606,0.572830,-0.659912,0.011102,-0.376669,0.341710,0.113171,0.089725,0.300097,0.051023,-0.160975,0.237475,0.243003,0.126683,-0.047835,0.109976,-0.120673,-0.379772,0.055898,0.412040,0.126002,-0.642334,0.379544,-0.296323,-0.181832,0.120311,-0.093593,0.114438,-0.101130,0.106716,0.091475,-0.010845,0.220715,-0.648670,0.389137,0.695955,0.386378,-0.220199,0.339770,-0.405021,-0.605901,0.162800,-0.589074,-0.463801,0.122112,0.127387,0.238430,-0.121983,0.238203,-0.221433,-0.182703,-0.309840,0.400360,0.243711,-0.522132,-0.306396,-0.011019,-0.224655,-0.495494,-0.282708,-0.045412,0.293968,-0.304716,1.053722,-1.118250,0.074609,0.542258,0.470402,-0.850077,0.773903,-0.077111,0.033575,-0.018281,-0.236923,0.454487,-0.040499,0.152003,-0.191703,0.024446,-0.237165,-0.112027,0.008408,0.156292', '6963575', '3445516', '1877596', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2155676', '奇幻精灵事件簿', '剧情', '本片根据霍利•布莱克（Holly Black）及托尼•迪特里奇（Tony DiTerlizzi）的同名畅销小说改编。单亲母亲格蕾丝（玛丽-路易斯•帕克 Mary-Louise Parker 饰）带着双胞胎儿子贾里德与西蒙（弗莱迪•海默尔 Freddie Highmore 饰）和大女儿马洛丽（莎拉•伯格 Sarah Bolger 饰）搬入斯派特维克祖居，竟碰到一系列怪事。贾里德在独自调查过程中发现了楼顶阁楼中伯祖母父亲阿瑟•斯派特维克（大卫•斯特雷泽恩 David Strathairn 饰）的精灵探索指南。尽管书表皮有一纸警告，贾里德还是阅读了指南，随后便看到了书中描述的精灵之一，棕精灵辛伯来泰克（马丁•肖特 配音）。辛伯来泰克警告贾里德不能把书拿到斯派特维克祖居保护圈外，以防恶灵莫格拉斯（尼克•诺特 Nick Nolte 饰）将指南据为己有，加害其他精灵。但莫格拉斯的手下已得知指南重见天日的事实，并错抓了西蒙。为了保护指南及家庭，三兄妹必须与莫格拉斯展开殊死搏斗……', '弗莱迪·海默', '马克·沃特斯', 7.3, 46801, 'tt0416236', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p457182707.jpg', 0.3, 3.3, 39.5, 42.4, 14.3, '0.388980,-0.225502,-0.413056,0.639015,0.146004,-0.719844,0.575860,-0.011860,-0.448324,-0.511969,-0.007658,0.549217,-0.226628,0.164009,0.528985,0.380209,-0.819064,-0.313832,0.046497,-0.349683,-0.372346,-0.831706,-0.312441,-0.435357,-0.015571,-0.393180,0.094372,-0.179218,-0.171706,0.295110,0.105157,0.482773,-0.121903,-0.093120,0.358328,0.299773,0.259526,-0.327552,-0.383053,0.191923,0.130626,0.034298,-0.181645,0.192265,0.553915,0.367321,0.432009,-0.772783,0.484218,-0.275418,0.173427,0.206844,0.260453,0.148914,0.101427,-0.201134,-0.132732,0.217954,-0.344960,0.016179,0.266169,-0.163094,-0.384320,0.042387,0.059468,0.230127,-0.386081,-0.171060,-0.379172,0.090776,0.000618,-0.261267,-0.184669,-0.107891,0.439753,0.185361,0.170014,0.070750,-0.368009,-0.207309,-0.152729,-0.011849,0.032058,-0.160972,-0.199473,-0.460175,-0.014594,0.264859,-0.414010,-0.057218,0.683230,-0.028913,0.260402,0.494059,-0.395903,-0.449199,-0.581816,-0.236656,-0.041985,-0.028208,-0.221778,-0.707922,0.144753,-0.107909,-0.032507,-0.149769,0.030697,-0.246365,0.484920,-0.342755,0.372946,0.101929,0.131659,0.077702,0.249763,-0.034180,0.558844,-0.046902,-0.038770,0.544265,0.563250,0.129219,0.537359,0.1