INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2156069', '谷子和鲻鱼', '剧情', '曾在赛特港码头辛苦操劳大半生的工人赛门（哈比•布法莱斯 Habib Boufares 饰）被解雇了，他感到既气愤又无助，跟上司的抗争也无功而返。由于事业的不顺利，他跟家人的关系也变得紧张起来，前妻、情人、儿女都对他感到失望。正在赛门走投无路的时候，情人的女儿丽姆（阿弗西娅•埃尔奇 Hafsia Herzi 饰）挺身而出。在她的鼓励帮助下，赛门准备在废弃的船上开一家餐厅，但是投资方对于他资产的质疑，险些让这桩买卖泡了汤。但是，赛门已经重新找回生活的勇气和信心。他带领家人逐渐走出阴霾，正当一家人为餐厅筹备菜品的时候，他们却遇到了前所未有的麻烦……本片获得第64届威尼斯电影节评审团特别奖。©豆瓣', '哈比·布法莱斯', '阿布戴·柯西胥', 8.2, 7469, 'tt0487419', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2211800363.jpg', 0.7, 2, 16.7, 48.2, 32.4, '0.112151,0.028143,-0.775773,0.410014,0.010592,-0.580694,0.644641,0.473276,-0.487612,-0.064768,0.231848,0.731951,0.033773,0.257090,0.322795,-0.050324,-0.242057,-0.522769,0.162091,-0.029137,0.040967,-0.397460,-0.189041,-0.386261,-0.146228,-0.431535,0.419918,0.160831,0.146860,0.547404,0.363624,0.064393,0.169847,0.689531,-0.025707,0.040657,0.306152,0.190285,-0.376591,-0.155199,-0.038351,-0.266879,-0.217010,0.222505,0.422970,0.465880,0.450593,0.216476,-0.445404,0.129981,0.196019,-0.263742,0.111306,0.183992,0.251402,0.008683,0.043476,0.171756,-0.292715,-0.022223,-0.008953,-0.010876,-0.877915,0.093681,0.155917,-0.069465,-0.820670,0.480306,-0.134476,0.174395,0.045189,-0.298462,0.190646,0.410722,0.214113,0.493900,-0.205676,0.187343,-0.458113,0.133033,0.810417,-0.133043,0.111620,0.300523,-0.373566,-0.209229,0.144920,-0.123445,-0.571491,-0.185164,0.237544,-0.005963,-0.139419,0.237535,-0.594608,-0.144004,-0.211599,-0.317046,-0.028562,-0.454066,0.187810,-0.481272,-0.069998,-0.205974,-0.229516,0.059373,0.083119,-0.256862,0.620700,-0.668914,0.266945,0.450535,0.445737,-0.551849,0.630591,0.157461,0.092424,-0.193511,-0.239702,0.093197,-0.212843,0.242319,0.229972,0.215362,-0.062514,-0.147319,-0.205181,0.390964', '1299965', '26678784', '1793491', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2156945', '决胜21点', '剧情', 'Ben Campbell（吉姆·斯特加斯 Jim Sturgess 饰）有着惊人的才华，身为麻省理工高材生的他学业无懈可击，他亦毫无意外地赢得了哈佛医学院的录取通知书。然而30万的高昂学费和生活费令他的大学梦摇摇欲坠。在争取奖学金的面试中，教授对他说胜出者必须要有过人的经历而不是像本这种一张白纸的学生。Ben在一服装店打工，挣取每小时8美元的薪酬。同时和两个好友准备竞赛2.09以期获得认同和奖金。数学课上本的天才头脑被教授Mickey Rosa（凯文·史派西 Kevin Spacey  饰）发现，Mickey 希望本加入自己的21算法团队，专门去赌场依靠算牌赢得大钱。Ben并不同意，但Ben一直暗恋的女孩Jill Taylor（#凯特·波茨沃斯 Kate Bosworth 饰）也出面诱惑时，Ben开始动摇。Ben开始了严密的训练，出师的成功让Ben尝到了金钱、虚荣、欲望的权力。同时他和旧友开始疏远，渐渐迷失在赌场的漩涡里。', '吉姆·斯特吉斯', '罗伯特·路克蒂克', 6.9, 64214, 'tt0478087', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1338838068.jpg', 0.6, 5.8, 49.3, 35.4, 8.9, '0.191120,0.083499,-0.718750,0.584253,-0.288958,-0.350742,0.396864,0.116085,-0.502177,-0.122728,0.091895,0.740567,-0.115494,0.091978,0.414758,-0.208601,-0.146362,-0.739255,0.004421,-0.350083,-0.155694,-0.685907,-0.057150,-0.108848,-0.208632,-0.399119,0.585331,0.057750,-0.175741,0.735050,0.152425,0.155428,0.501891,0.309135,-0.016933,-0.254156,0.164917,0.186651,-0.104899,0.117776,0.124095,0.035264,-0.396932,0.021348,0.359468,0.376157,0.441872,0.080938,-0.172823,0.063708,0.457656,-0.152664,-0.178362,0.101548,0.096647,0.243863,0.278661,0.178741,-0.024614,0.194388,0.137113,-0.321728,-0.867974,-0.208483,0.215538,0.060402,-0.613600,0.670881,-0.122118,-0.020871,0.099148,-0.064080,-0.296396,0.374463,0.087565,0.329755,-0.230659,-0.041950,-0.581335,0.375954,0.492773,-0.102805,-0.313327,0.201454,-0.307959,-0.606166,0.084468,-0.330457,-0.347277,0.127290,0.295387,0.217161,-0.079972,0.125102,-0.652506,0.054957,-0.213252,-0.298837,-0.127871,-0.593468,-0.123607,-0.593245,-0.135705,-0.332291,-0.353783,0.096885,0.122568,-0.453726,0.861996,-1.169977,0.084060,0.553478,0.520534,-0.382794,0.809875,0.139054,0.067351,-0.143254,-0.353072,0.005678,0.012900,0.544523,0.049811,0.347775,0.036124,-0.252949,-0