INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2157504', '百万元与苦虫女', '剧情', '佐藤玲子（苍井优 饰）是个毫无一技之长的平凡女孩，刚刚大学毕业，和父母住在一起，对未来一片茫然。她本性内向又倔强，经常和家人发生矛盾，终于决定打工存够一百万就搬出去，寻找属于自己的生活。玲子并未食言，存够一百万的她拉着行李箱离开了家，开始四处游历，到了海边，她在小店卖冰沙；到了山里，她帮果农摘桃子，四处打工让她存够一个又一个一百万，每存够一次便是出发前往下一个地方之时，存钱很容易，但她想要的生活却还不知在哪里。不过，频繁换地打工的过程中，玲子也在学习与人相处，从最初的困窘慌乱戒备，到可以交下朋友，在一间花店打工时，她认识了不断向她借钱的大学生中岛（森山未来 饰），许久以来的困惑和寻找，似乎都有了答案……©豆瓣', '苍井优', '棚田由纪', 8, 36467, 'tt1077094', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p699101890.jpg', 0.2, 1.3, 21.5, 51.5, 25.5, '0.228104,0.029805,-0.759310,0.398462,-0.420500,-0.451010,0.686621,-0.058707,-0.161351,-0.301556,-0.129568,0.753926,0.063584,0.597805,0.139520,0.258396,-0.198976,-0.418212,0.203667,-0.405730,-0.284798,-0.243554,-0.301495,-0.164469,-0.248163,-0.085052,0.464664,0.213365,0.033849,0.517149,-0.005354,0.023724,-0.147680,0.645256,-0.437887,-0.010499,0.023713,0.369097,-0.018997,0.241375,-0.008923,-0.423768,-0.448064,0.176167,0.462665,0.543620,0.820478,0.184029,-0.336561,0.307857,0.063543,0.072493,-0.185597,0.065270,0.193747,-0.096623,0.264351,0.067453,-0.389853,0.121916,-0.064891,-0.237719,-0.411137,0.016438,0.075683,0.116539,-0.852090,0.440830,0.061631,-0.206785,0.183306,-0.685253,0.173840,0.516519,0.099475,0.481645,-0.435531,0.029992,-0.563858,0.365456,0.783746,-0.014856,0.079566,0.524808,-0.153154,-0.266065,0.204193,0.010098,-0.708286,-0.200324,0.154566,0.036002,-0.452099,-0.094773,-0.576093,0.214573,-0.089202,-0.307806,0.097382,-0.542717,-0.022511,-0.300845,-0.097269,-0.460913,-0.400260,0.176874,0.093616,-0.262566,0.606930,-0.802580,0.186247,0.781687,0.483685,-0.657710,0.599172,-0.046264,0.008127,-0.181821,0.167692,-0.074753,0.078420,0.543214,0.138871,0.433166,-0.024215,0.098062,-0.405641,0.599033', '1299965', '1297606', '1866424', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2157507', '魔幻时刻', '喜剧', '黑帮小喽罗备后登（妻夫木聪 饰）与老大天盐幸之助（西田敏行 饰）的女人高千穗玛丽（深津惠里 饰）有染，惹来杀身之祸。为保性命，备后不得不接受寻找传奇杀手富坚的任务。走投无路之时，他突发妙策，假扮成一名正在筹拍黑帮电影的导演，邀请多年来辛苦打拼却功不成名不就的小演员村田大树（佐藤浩市 饰）出演杀手富坚。不知就里的村田和有些秀逗的经纪人长谷川（小日向文世 饰）随备后来至黑帮云集的港口加护，开始了自己紧张而刺激的电影拍摄之旅……©豆瓣', '佐藤浩市', '三谷幸喜', 8.1, 45427, 'tt1077089', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p637438422.jpg', 0.3, 1.7, 18.2, 50.1, 29.7, '-0.170420,-0.410273,-0.362060,0.277955,-0.022225,-0.225642,0.444527,0.312280,-0.282958,-0.192618,0.512047,0.601590,-0.351561,0.032584,0.280557,0.142779,-0.228217,-0.597507,-0.083009,0.002061,0.055252,-0.135759,-0.250800,-0.196486,-0.284166,-0.035285,0.728598,0.045535,-0.292739,0.276612,0.478918,0.359634,-0.111941,0.088332,0.107481,0.101973,0.174300,0.065653,-0.091892,0.158069,-0.219428,-0.359507,-0.247576,-0.085897,0.103094,0.267658,0.532154,-0.073361,0.046091,-0.294357,0.265518,-0.339641,-0.105815,0.054190,0.313458,-0.100602,0.194107,0.040946,-0.128564,0.043806,-0.042952,-0.087678,-0.576368,0.254210,0.265724,0.233814,-0.415112,0.187128,-0.435563,-0.171132,0.187337,-0.310839,0.037456,0.263659,0.367168,0.080465,-0.113556,0.281827,-0.218129,0.496170,0.524173,0.133203,0.195413,0.181173,0.266728,-0.296560,-0.014314,-0.313859,-0.518533,-0.009094,0.148805,-0.450977,0.030452,0.102164,-0.335270,-0.099532,-0.161692,0.020861,0.125483,0.046955,-0.206485,-0.795359,-0.066586,-0.364560,-0.012088,0.103296,0.345250,-0.176780,0.755665,-0.619379,-0.161669,0.547284,0.014740,-0.466648,0.517807,0.165601,-0.348868,-0.220809,-0.136524,-0.064968,0.072663,0.509194,0.249151,0.102109,-0.164668,-0.359539,-0.085383,-0.169721', '1322847', '2369613', '3811356', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2158222', '歪小子斯科特对抗全世界', '喜剧', '梦想成为歌手的摇滚青年斯科特（迈克尔·塞拉 Michael Cera 饰）有一支乐队几个死党和一段不堪回首的恋情，他深爱的前女友安维·亚当斯（布丽·拉尔森 Brie Larson 饰）被自己崇拜的同行横刀夺爱。正当悲观的他陷入了深深的感情阴影中无法自拔时，高中生少女奈福斯·周（爱伦·王 Ellen Wong 饰）和梦中情人拉蒙娜·花（玛丽·伊丽莎白·文斯蒂德 Mary Elizabeth Winstead 饰）同时出现在了他的眼前.斯科特对花一见钟情，但令他没有想到的是，他必须先打败她的7个邪恶前男友，才能得到花的芳心。而此时，安维亚当斯的归来和奈福斯·周的乱入又为这看似不可能完成的任务增加了难度。影片使用了例如主角三条命、打BOSS升级掉金币、战败重新读档等经典的格斗游戏桥段，使得整个电影充斥着浓浓的漫画风格，游戏爱好者绝对能从中找到共鸣，不容错过。', '迈克尔·塞拉', '埃德加·赖特', 7.1, 36519, 'tt0446029', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2510517476.jpg', 2.2, 8.8, 36.3, 37.3, 15.5, '0.145333,0.191285,-0.476110,0.767603,0.109377,-0.425412,0.871327,-0.099972,-0.186512,-0.331109,-0.071957,0.663300,-0.408872,0.250212,0.342776,-0.037007,-0.268955,-0.565902,-0.092835,-0.124843,-0.247325,-0.401670,-0.281109,-0.183027,-0.159127,-0.252676,0.867481,0.074709,-0.228142,0.303860,0.453311,0.542441,0.186366,0.401571,-0.000832,0.200998,0.153643,-0.028646,-0.114642,0.251269,0.123860,-0.053378,-0.019535,0.061400,-0.098440,0.128131,0.735496,-0.336629,0.110308,0.068866,0.517867,-0.163508,-0.045309,-0.020486,-0.034593,-0.155090,0.121236,-0.138288,-0.178372,-0.103416,0.189292,-0.292193,-0.815247,-0.020011,0.033917,0.090045,-0.498816,0.249564,-0.221454,0.054067,0.231906,0.086872,0.038118,0.083806,0.656409,0.172003,-0.060337,-0.071185,-0.487541,0.315413,0.496187,0.109775,-0.307057,0.495820,-0.376664,-0.512226,-0.416974,-0.094601,-0.431285,0.072193,0.516780,0.050466,0.032092,0.139363,-0.583737,-0.223685,-0.145540,-0.092823,-0.041782,-0.505758,-0.156775,-0.544297,-0.278784,-0.281706,-0.182959,-0.025304,0.121106,-0.395884,0.677880,-0.793728,0.128475,0.566996,-0.006593,-0.414713,0.718687,0.271132,-0.087848,-0.271221,-0.121319,0.396282,-0.060109,-0.038422,0.418666,0.388843,0.009785,-0.060643,-0.328898,0.694032', '2