INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2158328', '叛国者', '剧情', '穆斯林恐怖组织势力日益强大，为了挫败他们的国际阴谋，FBI探员罗伊·克莱顿（盖·皮尔斯 Guy Pearce 饰）被派遣着手调查。然而在调查中，他意外发现，许多线索表明前特战军官塞莫·霍恩（唐·钱德尔 Don Cheadle 饰）与某恐怖组织有着密切的联系。霍恩本是CIA卧底探员，苏丹裔穆斯林的他很容易就打入了恐怖组织内部。但穷追不舍搜索证据的克莱顿觉察出，如今的霍恩早已不是单纯的卧底。随着调查步步深入，事情的真相也渐渐浮出水面，可一切背后的复杂，远远超乎克莱顿的预料......完全沉迷在了寻找隐藏在暗处的秘密，罗伊追踪塞莫几乎跑遍了全球，而他自己也正在一点点进入一个完全由阴谋和诡计构成的地下世界当中.....©豆瓣', '盖·皮尔斯', 'Jeffrey Nachmanoff', 7.1, 8772, 'tt0988047', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1352083281.jpg', 0.4, 3.3, 43.8, 44.9, 7.6, '0.322694,-0.041186,-0.629017,0.641019,-0.107974,0.053860,0.521941,-0.044736,-0.778349,-0.329562,-0.107793,0.347934,-0.021548,-0.315400,0.099746,-0.042451,-0.430617,-0.917584,0.041372,-0.399241,-0.225466,-0.809668,-0.607604,-0.661757,-0.089116,-0.222144,0.641714,0.563434,-0.438701,0.137491,0.221345,0.404471,-0.477666,0.689587,0.225609,-0.261839,0.453019,-0.201020,-0.178708,0.206411,0.058686,-0.323683,0.045105,0.410288,0.069770,0.717996,0.325706,-0.451088,-0.088706,0.037325,0.204997,-0.479890,-0.024092,0.093038,0.540271,0.194887,-0.235356,0.226229,-0.234155,-0.062059,0.118723,-0.067783,-0.750400,-0.201218,0.253223,0.333665,-0.427803,0.083296,-0.031820,0.140956,-0.022406,-0.079850,0.281996,0.419359,0.324712,-0.189931,0.063032,0.063905,-0.655913,-0.109488,0.395382,0.093262,-0.083745,0.010590,-0.212221,-0.412324,-0.237824,-0.038768,-0.039277,-0.069633,0.394434,0.072829,-0.116935,0.499472,-0.285514,-0.016924,-0.286357,-0.296477,-0.198733,-0.482603,0.173002,-0.600187,-0.426683,-0.224142,-0.187476,-0.026160,-0.188119,-0.242756,0.505134,-0.603881,0.108026,0.630540,0.095102,-0.452195,0.397397,-0.183094,-0.061478,-0.386934,-0.286998,0.447669,0.348254,0.189632,0.276807,0.257842,-0.070884,-0.320311,-0.141376,0.225744', '1307442', '3217142', '1292348', '1449962');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2158490', '正义联盟', '动作', '超人离去，举世陷入哀悼之中。可是世界并未就此和平，恶势力蠢蠢欲动，犯罪气焰重新抬头。更为糟糕的是，来自远古的可怕威胁正渐渐逼近。在很久很久以前，亚特兰蒂斯人、亚马逊人和神族联合对抗邪恶的荒原狼。历经艰苦的斗争，荒原狼最终战败，被迫流放，而他留在地球上的三个盒子则分别由亚特兰蒂斯人、亚马逊人和普通人类看管。如今荒原狼卷土重来，地球被邪恶的阴影笼罩。值此危急关头，神奇女侠戴安娜（盖尔·加朵 Gal Gadot 饰）、蝙蝠侠布鲁斯·韦恩（本·阿弗莱克 Ben Affleck 饰）、海王（杰森·莫玛 Jason Momoa 饰）、闪电侠（埃兹拉·米勒 Ezra Miller 饰）、钢骨维克多·斯通（雷·费舍尔 Ray Fisher 饰）等五名正义战士走到一起。他们结成正义联盟，与荒原狼大军展开殊死之战……©豆瓣', '本·阿弗莱克', '扎克·施奈德', 6.3, 296097, 'tt0974015', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2504027804.jpg', 2.5, 15.2, 51.8, 23.4, 7.1, '0.085850,0.163265,-0.683565,0.499064,0.279700,0.100852,0.804143,0.158554,-0.209714,-0.107409,0.414314,0.618738,0.124283,-0.110666,0.205335,-0.072622,-0.328254,-0.602224,-0.097373,0.060397,-0.303089,-0.141619,-0.620554,-0.353808,0.091179,-0.397155,0.793943,0.283075,-0.169360,0.491839,0.105259,0.504874,-0.581783,0.357957,-0.118112,-0.085739,0.095266,-0.112552,-0.434905,0.069407,-0.460038,0.249960,-0.095822,0.242054,-0.150041,-0.053131,0.580949,-0.755013,0.248352,-0.612438,-0.032878,-0.366921,-0.289291,0.117789,0.589565,-0.391546,-0.020625,0.227466,0.348719,0.040638,-0.108171,0.063403,-0.521820,0.111637,-0.122368,0.226838,-0.503070,0.488058,0.131230,0.137590,0.139109,0.030534,-0.037824,0.260635,0.354972,0.103801,0.426102,0.013141,-0.318592,-0.080363,0.582163,-0.077099,-0.272169,-0.295554,0.040381,-0.426067,-0.187690,-0.250144,-0.223551,-0.227071,0.458675,-0.168571,0.028748,0.531140,-1.032207,0.116565,-0.212557,-0.105836,-0.084698,-0.294619,-0.160935,-0.588485,-0.235070,-0.171969,-0.037044,0.211335,-0.053101,0.145615,0.522415,-0.384454,0.292169,0.289248,0.345700,-0.323592,0.318461,-0.101309,0.147770,-0.295376,-0.020659,0.745067,0.168887,0.400025,0.344155,-0.084674,-0.136462,0.290450,-0.143904,0.500820', '26290398', '30336307', '7056398', '25890017');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2159244', '逃亡鳄鱼岛', '动作', '供职于某旅游杂志的记者皮特•麦克卡尔（Michael Vartan 饰）参加了一个在澳大利亚卡卡度国家公园举行的水上冒险旅行团。不过这次旅程对寻求刺激的人们来说似乎过于枯燥，美丽的女导游凯特•瑞恩（Radha Mitchell 饰）带领大家进入尚未开发的水域。正当游客们享受这令人惊叹的湖光山色之时，不远处的天空升起了求救的信号弹。凯特不顾大家返回的要求，执意要去查看情况。当来到一片神秘的湖泊之时，游船遭到撞击，开始下沉。众人被迫下船，却不知自己已经来到食人鳄鱼的领地。一场实力悬殊的杀戮旋即展开……本片荣获2007年澳大利亚电影节最佳视觉效果奖、2009年Fangoria链锯奖最佳录影带第三名。©豆瓣', '拉达·米切尔', 'Greg Mclean', 5.8, 7841, 'tt0479528', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2172918767.jpg', 4.2, 22, 55.5, 14.7, 3.7, '0.128678,-0.073934,-0.796638,0.522147,0.281026,-0.119171,0.632027,0.333437,-0.342339,-0.045530,0.487919,0.656031,-0.289745,0.022365,0.557345,-0.075428,-0.502101,-0.460526,-0.162561,-0.160100,-0.108192,-0.164170,-0.182957,-0.168057,-0.132464,-0.156790,0.610585,0.183522,-0.218574,0.665990,0.207565,0.064946,-0.042104,0.584353,-0.096246,-0.265164,0.290218,0.007731,-0.337090,0.328832,-0.232152,-0.387153,-0.358075,0.006508,0.173747,0.259455,0.946168,-0.329965,0.021642,-0.155120,0.387409,-0.315844,0.071734,0.095568,0.255846,0.015438,0.025142,-0.206817,0.115596,0.239243,-0.000480,-0.446033,-0.411539,0.246615,-0.031179,0.139721,-0.393551,0.188357,-0.050375,0.046802,-0.062945,-0.300127,0.064853,0.211532,-0.004368,0.208998,-0.014948,0.040192,-0.112749,0.205212,0.688657,0.122347,-0.304645,0.104967,-0.129105,-0.704507,0.036766,0.048971,-0.315033,-0.091150,0.539593,0.144646,-0.023750,0.155600,-0.812945,0.077665,-0.172668,-0.732504,-0.029886,-0.046289,-0.341354,-1.142134,0.178062,-0.078805,-0.095155,0.008066,0.039827,-0.113718,0.650767,-0.664916,0.035534,0.593563,0.126251,-0.370607,0.687532,-0.229455,0.040892,-0.065400,-0.253136,0.251520,-0.270635,0.531597,-0.095761,0.183562,-0.049644,-0.203656,-0.350600,0.297053', '24751811', '3178770', '21349734', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2159331', '蓝精灵', '喜剧', '在广袤安宁的原始森林中，快乐的蓝精灵们正在准备一年一度的蓝月亮节。而就在这欢喜忙碌的关头，他们的宿敌——邪恶的巫师格格巫（汉克·阿扎瑞亚 Hank Azaria 饰）和他的宠物阿兹猫闯入了蓝精灵的秘密领地。受到惊吓的蓝精灵四散而逃，其中可怜的笨笨（安东·尤金 Anton Yelchin 配音）则盲打误撞跑进了据说曾经死掉99个蓝精灵的瀑布进去。最终，笨笨连同营救他的蓝爸爸、蓝妹妹、聪聪等卷入了神秘的漩涡，来到了美国纽约的中央花园。在这个完全陌生的世界，他们得到化妆品业的帕特里克（尼尔·帕特里克•哈里斯 Neil Patrick Harris 配音）的帮助。为了返回大森林，蓝精灵们想尽各种办法。与此同时，格格巫和阿兹猫也来到纽约……本片根据比利时漫画家沛优（Peyo）及其夫人共同创作的漫画改编，早年曾被美国引进制作成TV版动画。©豆瓣', '尼尔·帕特里克·哈里斯', '拉加·高斯内尔', 7.2, 102297, 'tt0472181', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p884990120.jpg', 0.9, 5.4, 39.3, 39.8, 14.6, '0.285735,-0.005992,-0.680874,0.520599,-0.048162,-0.249063,0.664976,0.107249,-0.317535,-0.253682,0.257287,0.693402,-0.043475,0.269138,0.284232,0.068184,-0.322054,-0.397715,-0.167265,-0.178706,-0.143237,-0.217567,-0.213839,-0.260146,0.046276,-0.340947,0.568075,0.038960,-0.077728,0.487240,0.360871,0.230697,-0.427880,0.235635,-0.180606,0.333484,0.104558,-0.149238,-0.185187,0.273697,-0.111050,-0.033491,-0.092033,-0.014650,0.113529,0.189627,0.708953,-0.559025,0.137711,-0.047156,0.384136,-0.362815,-0.032803,0.103000,0.395565,-0.171893,0.241216,-0.130642,-0.185915,0.145932,0.013691,-0.182946,-0.773431,0.132824,0.181798,0.211267,-0.518236,0.170777,0.204548,-0.072452,0.254927,-0.250228,0.258993,0.269281,0.056675,0.408264,-0.213881,0.320561,-0.408413,0.119183,0.449412,-0.263313,-0.122724,0.116317,0.013947,-0.392480,-0.074513,-0.161590,-0.360840,-0.076969,0.575682,-0.078900,-0.128369,0.144109,-0.950955,0.044662,-0.149682,-0.429351,0.007618,-0.114636,-0.205241,-0.746192,0.082588,-0.141334,0.040987,-0.026695,-0.050172,-0.072129,0.780027,-0.708621,0.366761,0.422289,0.167799,-0.517795,0.533579,-0.013540,0.157657,-0.140583,-0.181033,0.336717,0.090317,0.530432,0.115532,0.357995,0.030303,-0.279648,-0.556509,0.371041', '26290398', '4181031', '11810348', '5322572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2159676', '千年狐', '剧情', '优比（孙艺珍 配音）是一只千年狐，虽然有一百岁了，实际等同于十岁的人类小孩，正值青春花季，单纯天真的她和六个迫降地球的外星人生活在一起。按照规矩，如果千年狐想成为人类就必须得到人类的灵魂，这也导致千年狐们去杀害人类，反过来，人类为了自卫不断地捕杀千年狐，到优比这代，就剩 她一只了。在她眼里，人类是愚蠢的代名词，没有想成为人类的欲望。直至一天，她遇到了一个叫坤宜（孔炯真 配音）的男孩子，开始喜欢上了他，而男孩生活在人类的世界，优比为了接近她化妆成人类到他生活的地方，于是她怀着好奇心开始和人类交往，于是新生活向她展开了一个充满冒险的新世界……©豆瓣', '孙艺珍', '李成康', 7.4, 7033, 'tt1077274', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p797330753.jpg', 0.9, 4.1, 37.3, 40.1, 17.5, '0.350677,0.418926,-0.711004,0.550267,-0.573378,-0.028381,0.752090,-0.229794,-0.239815,-0.086431,0.016678,0.734290,0.155085,0.392894,0.055386,-0.022828,-0.034565,-0.416945,0.023358,-0.177193,-0.379055,-0.093847,-0.307018,-0.295578,-0.169981,-0.459736,1.034859,0.037116,-0.174119,0.129124,0.040764,0.193964,0.232764,0.214326,-0.562657,-0.061139,-0.174253,0.070539,-0.140392,0.389609,-0.162523,0.008908,-0.071867,0.250522,-0.404193,0.141177,0.742890,-0.434799,-0.251155,-0.403995,0.381172,-0.392838,-0.249877,0.118607,0.595269,-0.312690,0.022384,0.051188,0.158047,0.003512,0.014466,-0.180875,-0.866755,-0.125136,-0.159785,0.207375,-0.403530,0.328348,0.359115,0.012390,0.154067,-0.459093,-0.175533,0.305007,0.222817,0.533652,-0.229745,-0.049350,-0.698871,0.260580,0.981806,0.153680,-0.504919,0.616433,-0.220386,-0.673853,-0.329490,-0.466544,-0.474714,-0.225747,0.059437,-0.080958,-0.663544,0.473210,-0.844363,0.250893,-0.080696,-0.245697,0.273147,-0.388810,0.058701,-0.142935,-0.180309,-0.522631,-0.437611,0.073818,0.158746,-0.743601,0.922100,-1.047126,0.380466,0.814168,0.534223,-0.715036,0.671411,-0.022860,-0.131242,-0.295665,0.224016,0.454583,-0.166872,0.234942,0.128931,0.149900,0.112177,0.287453,-0.410690,0.857648', '26386465', '3592853', '26667010', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2160611', '恐怖星球', '动作', '脱衣舞女切丽（罗丝·迈格温饰）边跳钢管舞边流泪，她厌倦并想着逃离这样的生活，一切烂透了。另一边，附近军事基地在研发一种药物的过程中发生事故，病毒气体弥漫出来，附近周围的人们变成了僵尸，而切丽那赖以为生、修长惹火的右腿也被僵尸扯了下来。还好，她身边还有男友雷（弗莱迪·罗瑞格兹饰）的存在。医院被血洗，警察们无力阻挡僵尸的进攻。雷和其他幸存的人们汇集到小店，组成武装部队，展开与僵尸对抗的血战中。雷甚至给切丽装上一只假肢，而这只假肢其实是一把超强武器，可以当机关枪也可以当迫击炮。于是，切丽成为猎杀僵尸的超级女斗士。©豆瓣', '罗丝·麦高恩', '罗伯特·罗德里格兹', 7.4, 50752, 'tt1077258', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p559928049.jpg', 1.5, 5.4, 32.4, 41.4, 19.4, '0.406028,-0.163874,-0.524730,0.229786,-0.038397,0.027318,0.968564,-0.168784,-0.243706,-0.122198,0.054585,0.396125,-0.122424,0.152292,0.116865,-0.206635,-0.135095,-0.704344,-0.252862,0.228486,-0.628908,-0.018567,-0.371306,-0.391613,-0.053829,-0.304402,0.508001,0.283855,-0.450207,0.276900,0.337338,0.353899,-0.259711,0.270974,-0.213294,-0.038156,-0.158479,-0.360553,0.063979,0.252227,-0.135564,-0.243394,0.118862,0.075822,0.003349,0.197578,0.526881,-0.348551,0.288399,-0.473968,-0.008455,-0.295975,0.101746,0.085683,0.387102,0.159622,0.109382,-0.318950,0.135605,0.014606,0.134818,-0.017833,-0.684719,-0.209238,-0.291872,0.164516,-0.509894,0.174885,0.133944,0.145409,-0.027704,-0.277716,0.313435,-0.108952,-0.121989,0.159051,-0.416750,-0.013683,-0.849629,0.103716,0.631542,0.083173,-0.414473,0.107554,-0.164407,-0.489441,-0.517240,-0.212808,-0.025608,-0.254767,0.315117,0.244900,-0.130763,0.270811,-0.781151,-0.056545,-0.184615,-0.217946,-0.318572,0.006036,-0.094814,-0.640989,0.153543,-0.195804,-0.121070,0.136321,0.048531,-0.216643,0.350683,-0.592870,0.191774,0.270897,0.240610,-0.064610,0.199186,-0.243727,0.323114,0.118244,-0.161145,0.180306,0.213625,0.543936,0.481525,0.415182,-0.111649,0.043119,-0.366917,0.604331', '1293515', '21619567', '1578663', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2161696', '他其实没那么喜欢你', '剧情', 'GiGi(Ginnifer Goodwin 饰)是个对爱情充满幻想的女孩儿，却在一次次约会中受挫。她的闺蜜Beth（Jennifer Aniston 饰）和Janine（Jennifer Connelly 饰）不断鼓励GiGi在感情中振奋起来，却各自对爱情怀有遗憾。Beth与Neil（Ben Affleck 饰）同居七年，却一直未能等来期待的那枚婚戒。Janine的敏感让她与Ben（Bradley Cooper 饰）的婚姻陷入僵局，而Ben与歌手Anna（Scarlett Johansson 饰）的婚外情更是给他们的婚姻雪上加霜。Anna一边拒绝拥趸Conor（Kevin Connolly 饰）的示好，一边热情似火的期待Ben离开Janine，可是Ben真的能离开Janine来到她的身边么？另一方面Anna的好友Mary（Drew Barrymore 饰）在一个清晨和Conor面对面的不期而遇了。几个女孩儿带着爱情的梦想在城市中跌跌撞撞，而此时一直未遇真爱的GiGi在酒吧老板Alex（Justin Long 饰）的口中听到了让所有女人心碎的话“He is just not that into you!”', '詹妮弗·安妮斯顿', '肯·卡皮斯', 7.8, 418812, 'tt1001508', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p477821688.jpg', 0.3, 2, 27.3, 48.5, 21.9, '0.266090,0.291919,-0.899377,0.855486,-0.167875,-0.251786,1.286369,-0.029643,-0.639465,0.037649,0.140210,0.773047,-0.399019,0.344602,0.247880,0.044545,-0.106337,-0.970297,-0.005001,-0.120530,-0.346219,-0.478148,-0.175916,0.011434,-0.346997,-0.181326,0.650501,0.226757,0.015761,0.944780,0.679988,0.219711,-0.156646,0.674107,-0.391935,-0.182777,-0.070399,0.392017,-0.481249,0.203004,0.208284,-0.290069,-0.213265,0.367661,-0.144535,0.183379,0.793776,-0.446436,-0.056876,0.278193,0.242628,-0.219688,-0.007442,0.351093,0.101131,0.167575,0.453256,0.021995,-0.324950,0.084282,0.249664,0.036566,-0.959220,0.062275,0.148326,0.308814,-0.720565,0.781992,0.080533,-0.086273,0.413445,-0.232787,0.221709,0.260191,0.195281,0.744030,-0.582575,0.019975,-0.569846,0.159502,0.536372,0.049968,0.160077,0.520164,-0.264601,-0.204960,-0.041456,0.235374,-0.871984,-0.238768,0.132317,0.191450,-0.075361,0.012905,-0.832815,0.181291,-0.001858,-0.080343,0.215222,-0.902301,-0.117077,-0.412067,-0.081896,-0.776701,-0.402494,0.504475,0.225213,-0.155393,0.749722,-1.054899,0.217580,0.474039,0.405914,-0.652745,0.872641,0.512873,-0.084