INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21618782', '笔仙Ⅱ', '悬疑', '大学时期，宋倩（朴韩星 饰）与娜娜（辛芷蕾 饰）、羽菲（李昕岳 饰）、游峰（张皓然 饰）、宏瑞（杨帆 饰）、杨铮（孙绍龙 饰）几个人是非常要好的朋友。直到认识了新生小艾（章婷婷 饰）。漂亮的小艾让本来亲密无间的小团体产生了裂痕。特别是娜娜，处处针对她，只有宋倩努力维系着大家的关系。渐渐开始有不好的传言在学校漫延——小艾一直被视为邪恶的化身，所有与她接触的人都会有厄运。很快宏瑞发生意外摔伤腿，错过一场重要比赛。宋倩几个人在学校的屋顶阁楼玩起笔仙，结果笔仙也验证了小艾的不详，当晚小艾便跳楼自杀了。大学毕业后，宋倩和她的同学们事业都发展很顺利，有的成了大明星，有的成为了企业精英，而直到娜娜从美国回来，怪事接二连三的发生，每个人都开始遇到危险，谜底一层层揭开，原来大学时代小艾的死，是另有原因……2013年与2010年，都市中与校园里，一段尘封已久的大学往事，某个被记忆掩埋在心灵深处的名字再次因为笔仙的到来浮现脑海……', '朴寒星', '安兵基', 3.9, 10096, 'tt2993580', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2033410187.jpg', 37.2, 37, 20.8, 3.2, 1.8, '0.298287,-0.016447,-0.660273,0.303634,0.130047,-0.057430,0.565669,0.004351,-0.545823,-0.266655,0.133750,0.609385,-0.435171,0.525535,0.145657,-0.026505,-0.132290,-0.866697,0.075513,-0.370350,-0.445599,-0.261773,-0.094710,-0.083725,-0.088987,-0.403063,0.414770,0.109430,-0.216973,0.463105,0.261583,0.238808,-0.045448,0.446372,-0.209142,0.100349,0.080443,0.236350,-0.083258,-0.015663,0.141164,-0.146331,-0.298290,-0.012891,0.075230,0.276474,0.767452,0.012781,-0.302975,0.053555,0.485385,-0.247611,-0.189709,-0.083568,0.577960,0.124841,0.152489,0.369172,-0.177453,0.079020,0.245164,-0.135809,-0.408048,0.034776,0.269698,0.218672,-0.425725,0.457725,0.227825,-0.054344,0.258463,-0.315978,0.319187,0.437090,0.264006,0.218405,-0.067188,0.084368,-0.490484,0.311200,0.682323,0.036198,-0.304773,0.348625,-0.158730,-0.415034,-0.145259,-0.034155,-0.337229,0.194351,0.369783,0.024800,-0.336584,0.327768,-0.669558,0.061174,0.009376,-0.130183,0.054450,-0.373210,-0.086939,-0.404761,-0.422391,-0.340916,-0.343746,0.191501,-0.301958,-0.204327,0.905437,-0.971421,0.277094,0.432136,0.255550,-0.390353,0.687419,0.073866,-0.078533,-0.155742,0.003294,-0.041358,-0.221850,0.245048,0.002837,0.447751,-0.140321,-0.133173,-0.426088,0.430425', '1292219', '1826173', '25922902', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21619567', '短暂和平', '动画', '本片由四个短片组成。《九十九》健硕的手艺人在山中突逢暴雨，他仓促间在一座祠堂歇脚，谁知里面别有洞天。被人用烂丢弃的雨伞和绸缎将他团团围住，手艺人不为所惧，拿出随身携带的针头线脑缝补这些充满悲怨的旧物。《火要镇》商人之女若（早见沙织 配音）和邻家男孩年松吉（森田成一 配音）青梅竹马，两情相悦 。但是家境悬殊的二人终究有缘无分。即将出嫁的小若不慎引燃烛火，可在那一刻她却突然停止灭火呼救的念头。《GAMBO》某座山村饱受巨大的赤鬼困扰，村民不得不将少女奉献出去以求苟存。村中最后一个女孩（田村睦心 配音）在森林里遇见可怕的白熊，她诉说了心中的苦衷，而白熊却像听懂了一般杀向赤鬼的老巢。《别了武器》一伙全副武装的战士来到早已成为废墟的都市，他们高度戒备，全力备战，只为围捕一辆无人驾驶的战车。©豆瓣', '春名風花', '森本晃司', 8.1, 8646, 'tt3392330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1982059753.jpg', 0.4, 1.6, 19.3, 51, 27.7, '0.229351,-0.088089,-0.653862,0.342795,0.024964,-0.054243,1.075320,0.081775,-0.198612,-0.158362,0.435543,0.595381,-0.076438,0.125811,-0.078560,-0.148079,0.052462,-0.371655,-0.318141,-0.157140,-0.197892,-0.107580,-0.230538,-0.130243,-0.192063,-0.182680,0.683115,0.195959,-0.052459,0.137682,0.309210,-0.007467,-0.257170,0.212869,-0.423772,-0.127633,-0.338324,-0.040043,0.040628,0.165545,-0.506598,-0.185194,-0.139946,0.113115,-0.153610,0.338011,0.916004,-0.401551,0.020772,0.036043,0.181723,-0.140971,0.114710,0.160569,0.178593,-0.006746,0.103048,-0.109346,-0.123602,0.087580,0.108738,-0.160669,-0.468303,0.073282,0.148260,0.041683,-0.692274,0.416357,0.169827,-0.010939,0.115096,-0.269387,0.159325,-0.147239,0.170325,0.421571,-0.225389,0.037446,-0.605367,0.109820,0.559925,-0.118247,-0.065553,0.271717,-0.089492,-0.314872,0.034202,-0.060571,-0.368481,-0.283468,0.348515,-0.051641,-0.248879,0.067332,-0.672024,-0.036117,-0.247337,0.013600,-0.079118,-0.340643,-0.233247,-0.269707,0.138639,-0.148667,-0.166727,0.381067,0.194853,0.144888,0.684557,-0.520702,0.215620,0.398215,0.130051,-0.088594,0.386724,-0.226084,0.040747,0.088159,-0.093104,0.177280,0.264276,0.531136,0.295340,0.333109,-0.299948,-0.060166,-0.382830,0.259507', '1467779', '1293515', '1578663', '1394470');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21624974', '两天一夜', '剧情', '女主角桑德拉是一个刚走出忧郁症的女工、两个孩子的妈妈，却马上面临工厂裁员和失业。在丈夫坚定的支持和陪伴下，她要在一个周末的时间，去说服同事工友们为她重新投票，以保住至关重要的工作。然而，选择支持她的工友需要是以失去1000欧元的奖金为代价。', '玛丽昂·歌迪亚', '让-皮埃尔·达内', 7.6, 21102, 'tt2737050', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2406176936.jpg', 0.6, 2.5, 30.3, 51.6, 15, '-0.153173,-0.111416,-0.414105,0.351845,-0.396208,-0.647643,0.879222,0.251152,-0.149206,-0.250391,0.430147,0.730175,0.384627,0.423304,0.216478,-0.385868,-0.246316,-0.621717,-0.130595,0.158013,-0.481993,-0.492780,0.230708,-0.294588,-0.367647,-0.247657,0.866266,-0.048571,0.231252,0.458228,0.375617,0.072501,0.325593,0.591136,-0.030604,-0.080221,0.005073,-0.270838,-0.503222,0.636102,0.446780,-0.014976,-0.389695,0.021704,0.218569,0.577858,0.492147,-0.113742,-0.231077,0.101583,0.469242,-0.326412,-0.158895,0.125708,0.232063,-0.001510,0.360178,0.199613,-0.757977,0.210069,-0.050490,-0.351978,-1.086742,-0.355282,0.327841,0.200949,-1.076308,0.534149,-0.153472,0.171865,0.525373,-0.427252,-0.068792,0.754321,-0.066075,0.673462,-0.595215,0.174132,-0.446869,0.158635,0.877992,-0.122548,-0.000040,0.439960,-0.370478,-0.179073,0.162701,-0.338896,-0.581074,-0.000184,0.027716,-0.013673,0.037248,-0.094240,-0.696320,-0.148397,-0.219954,-0.743732,0.066090,-0.773535,0.013116,-0.332136,0.148249,0.136514,-0.155062,0.397165,0.213497,-0.594292,1.241949,-1.001236,0.043273,0.607968,0.592295,-1.119224,1.077635,0.162921,0.545746,-0.405518,0.089747,-0.021481,0.031321,0.417953,-0.121095,0.012228,0.027825,0.011405,-0.455928,0.319684', '1877596', '26678784', '1308424', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2170915', '跨国银行', '动作', '规模庞大几乎盘踞全球的跨国银行IBBC在这个钱权主宰的社会里简直无所不能，它不仅操控着各国经济，牵制着政府的决策，甚至参与洗钱、贩卖军火、勒索绑架等各种黑道行动，它就像一只大章鱼将触角伸向黑夜的每个角落。国际刑警路易斯·塞林格（克里夫·欧文 Clive Owen 饰）目睹同事因企图泄露银行机密而遭遇暗杀，他决意受命前往柏林彻查IBBC洗钱内幕，得益于另一位正义者副检察官埃莉诺·惠特曼（娜奥米·沃茨 Naomi Watts 饰）的同行协助，两人很快发现了跨国银行更多鲜为人知的非法活动，甚至包括资助恐怖分子和发动战争。两人决心揭露跨国银行的真实面目，然而，无所不知的IBBC早已注意到这两只蝼蚁，杀手随即派到，路易斯和埃莉诺最终能否赢得这场螳臂当车的生死周璇？©豆瓣', '克里夫·欧文', '汤姆·提克威', 6.4, 11139, 'tt0963178', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p775147125.jpg', 1.3, 11.5, 57.6, 24.7, 4.8, '0.252899,0.117502,-0.771527,0.495518,0.119249,0.137979,0.426063,0.213107,-0.381865,-0.215048,0.338462,0.556987,-0.092920,0.050945,0.251335,-0.159560,-0.269013,-0.579949,-0.242504,-0.024653,-0.018721,-0.485679,-0.628757,-0.362643,-0.004201,0.008744,0.539236,0.135830,-0.461404,0.264688,0.269262,0.163934,-0.403112,0.205144,0.044610,-0.385984,0.436531,-0.170051,-0.364644,0.129852,-0.207908,-0.189810,-0.003215,0.179182,-0.067965,0.436924,0.223884,-0.480903,0.002183,-0.186753,0.436081,-0.572953,0.005021,0.101488,0.384343,0.060383,-0.008705,0.351027,-0.279858,0.102920,0.308775,-0.099896,-0.984188,-0.125302,0.084595,0.384327,-0.381692,0.179723,-0.101867,0.174940,-0.092868,-0.081242,0.047641,0.442762,-0.084640,0.023256,0.128576,0.122175,-0.695252,0.072656,0.504383,-0.172044,-0.307607,-0.160778,0.078641,-0.321413,-0.174570,-0.301685,-0.001285,-0.204999,0.410334,-0.260224,-0.174036,0.508203,-0.657244,-0.171771,-0.315288,-0.165995,-0.061227,-0.310547,0.013994,-0.828484,-0.202554,-0.254246,-0.002077,0.166538,0.335464,-0.144020,0.452382,-0.445024,-0.047761,0.677035,0.239645,-0.475119,0.381061,-0.204577,0.232397,-0.162703,-0.294680,0.151429,0.535088,0.326192,0.027993,-0.005313,0.052039,-0.309936,0.041414,0.031098', '26747274', '4014397', '7155241', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2170916', '男孩们回来了', '剧情', '乔（克里夫·欧文 Clive Owen）的第二任妻子突患重症，不久便离开了人世，给他留下的除了无限的哀思同时，还有一个年仅五岁的儿子纳提。乔拒绝了妻子母亲的帮助，决定带着纳提独自生活，可是带孩子并不是想象的那么容易，特别是一个刚失去母亲的五岁小朋友，在与纳提相处的过程中，纳提的可爱和乖戾让乔无所适从；和前妻所生之子哈瑞专程从英国来看他，这个正处叛逆期而且沉默寡言的孩子同样让乔不知所措。琐碎的家务事和忙碌的工作让乔焦头烂额，单身父亲似乎并没有独自照顾两个儿子的能力，小儿子让岳母接走，大儿子回到了英国，乔同时失去了两个儿子。但故事并没有完，乔并不是一个没有责任心的父亲，他开始想法设法的挽回自己的儿子……伴随着舒缓的音乐，淡淡的哀伤满溢，故事也慢慢的拉开了序幕。©豆瓣', '克里夫·欧文', '斯科特·希克斯', 8, 6829, 'tt0926380', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p475238938.jpg', 0.3, 1.4, 22, 51.8, 24.5, '0.200432,-0.119356,-0.711576,0.856455,-0.541045,-0.510708,1.026985,0.224856,-0.636211,-0.609898,-0.441885,0.863277,0.059780,0.760982,0.021742,-0.176648,-0.147300,-0.615102,-0.210707,0.119473,-0.517406,-0.759096,0.214229,-0.381934,-0.184843,-0.170645,0.546674,0.144328,-0.066478,0.511914,0.153035,0.043418,0.073276,0.816327,-0.369222,0.146553,-0.099112,0.231111,-0.114758,0.115708,0.566487,-0.077922,-0.095338,0.423644,0.152701,0.581162,0.655411,-0.273213,-0.002732,-0.033369,0.326547,-0.272764,-0.005789,0.059934,0.145766,-0.056706,0.066685,-0.079110,-0.304830,-0.097404,0.061437,-0.381553,-0.751642,0.111457,0.077274,-0.205088,-0.678899,0.385519,-0.072771,-0.078085,0.389985,-0.063677,0.407818,0.618667,-0.022265,0.729479,-0.382043,0.262417,-0.490162,0.201866,0.613529,-0.048537,-0.225626,0.704779,-0.397386,-0.562073,0.051665,-0.446200,-0.619373,0.070375,0.230659,0.106874,-0.167791,0.131425,-0.197874,-0.160831,-0.144937,-0.098386,0.054110,-0.695402,0.008246,-0.134033,-0.123796,-0.462206,-0.213127,0.159484,-0.129618,-0.392990,0.788257,-0.802427,0.333034,0.188880,0.188259,-0.891023,0.739275,0.147504,0.292060,-0.225127,0.275324,0.432057,0.034863,-0.085419,0.454535,0.263904,-0.144795,0.018369,-0.276529,0.540791', '1305703', '26420626', '1304977', '1306916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2170919', '墙壁之间', '剧情', '新学期伊始，教师与学生们返回一所普通的社区学校。法语老师兼班主任的弗朗索瓦·马林（François Bégaudeau 饰）面对升一年级的新班级，继续用坦诚又有些好辩的方式教学，这群14岁左右的学生思维活跃，时常在宽松的课堂上反诘马林或是斗嘴、传播八卦，马林不得不一次次中断进度，解决无数琐碎的问题。这所学校内汇聚了来自多国的移民学生，随之而来的问题时常在课堂细节中体现，马林试图尽量让学生们找到自尊，但这些擅于让老师头疼的孩子似乎不太接受马林的说辞。课堂上的唇枪舌剑与部分学生敌视老师的态度让潜藏着的矛盾随时会爆发。本片获2008年戛纳金棕榈奖，由小说原著兼编剧的François Bégaudeau主演。©豆瓣', 'François Bégaudeau', '劳伦·冈泰', 7.7, 6514, 'tt1068646', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p479629463.jpg', 0.8, 2.5, 27.5, 50.5, 18.7, '0.619305,-0.215983,-0.153387,0.563644,-0.110286,0.037596,0.319852,0.089002,-0.563263,-0.395266,-0.070647,0.586758,-0.406305,0.540892,0.154359,-0.459248,-0.483658,-0.670520,-0.082792,-0.175942,-0.157364,-0.624931,0.120393,-0.411939,-0.338078,-0.494684,0.629017,-0.040396,-0.354776,0.423485,-0.045794,0.334481,0.073907,0.257137,0.159739,-0.405868,0.037183,0.173620,0.120466,-0.091098,0.198127,-0.016269,-0.430664,-0.099908,0.302113,0.410271,0.931200,0.242836,-0.046546,0.070133,0.651772,-0.199342,-0.133618,0.172805,0.500011,0.260238,0.263733,0.209869,0.139839,0.264651,-0.260840,-0.288664,-0.477124,-0.246561,0.196873,-0.061136,-0.262065,0.455843,0.183924,-0.000540,0.178760,-0.188077,-0.138503,0.183706,0.279588,0.579809,-0.057826,-0.036923,0.196136,0.284250,0.578521,-0.036137,-0.567126,0.035402,-0.494374,-0.390600,0.090883,-0.225773,-0.451519,-0.024079,-0.079288,0.093406,0.032013,0.267654,-0.635570,0.016385,0.040350,-0.237797,0.051693,-0.372228,-0.115413,-0.828792,0.142561,-0.224819,-0.054787,-0.258575,0.233701,-0.140364,1.212192,-0.844676,-0.106000,0.561678,0.237598,-0.318392,0.611695,0.162640,0.287509,-0.291326,-0.422711,-0.255842,-0.034319,0.536789,-0.119348,0.523466,-0.103749,-0.482885,-0.296077,0.367064', '25922902', '3811356', '5403927', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21724200', '脱轨时代', '喜剧', '八零后的许可（张静初 饰），在某个清晨醒来后，祥装气定神闲的走进民政局，闪婚太老，闪离却还来得及：谁的七年不曾痒一痒。回去的路上更祸不单行的与一辆宝马相撞，回到家的许可这才开始检阅自己的一地凄怆：青春已逝、老公出轨、净身出户、车辆被毁。富二代康少（吴克群 饰）的出现给许可的生活打了一剂强心剂，在无奈的上演了一出“他乡遇故知”的狗血戏码后，两人又几次三番的狭路相逢，许可一步步的发现这个大男孩不羁外表背后柔软又细腻的心，然而瞄了一眼自己的平胸和户口本上的高龄，许可迟迟不敢接招，谁知却又撞上闺蜜毛毛（朱珠 饰）的一见钟情二见倾心三见误终身，这场尴尬无比的三角恋注定要轰轰烈烈的展开。而另一边，气质忧郁的前夫刘光芒（潘粤明 饰），在度过失去婚姻的颓废期后，也在浪子回头的路上亦步亦趋：改掉自己不够浪漫的老毛病，拉拢毛毛为自己制造机会，贿赂鬼精灵的儿子成为自己的“帮凶”，在老房子的窗台，恋爱时的点滴回忆与温馨都在慢慢复苏，许可又将如何选择？独自远走异乡的许可，渴望寻找到内心真实的声音：生命的波澜起伏不定，内心的翻涌置之死地而后生。在洒满日光的海滩，熟悉的面孔再度重逢，阴云过后，阳光终于开启了人生新的一页。', '张静初', '五百', 6.1, 16917, 'tt4038736', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171948533.jpg', 4.7, 17.8, 51, 20.7, 5.8, '0.195314,0.236915,-0.747308,0.528873,-0.146075,-0.474472,0.797811,0.309595,-0.343033,0.132681,0.227140,0.657797,-0.405000,0.414076,0.361431,0.034713,-0.202924,-0.704388,-0.029135,-0.060306,-0.340118,-0.164264,-0.214994,0.129380,0.015230,-0.230727,0.677856,0.224382,-0.147020,0.437078,0.422778,-0.098002,-0.068321,0.431794,-0.429414,0.019585,-0.119221,0.409215,-0.145750,-0.003439,0.116958,-0.512833,-0.173495,0.134058,-0.227208,0.259117,0.655670,-0.135186,-0.208294,-0.032689,0.562845,-0.124975,-0.167879,0.272070,0.086594,0.076777,-0.019761,-0.087785,-0.269332,-0.015481,0.054351,0.192545,-0.565340,0.041551,-0.052695,0.104390,-0.543522,0.518537,0.083140,-0.122139,0.170930,-0.384049,0.189931,0.221582,0.046139,0.522363,-0.553658,0.080230,-0.386408,0.260162,0.583023,0.235602,-0.074647,0.547191,-0.156699,-0.247327,0.156357,0.026864,-0.562044,-0.311257,0.452900,0.174353,-0.184684,0.190074,-0.626390,0.046428,-0.186790,-0.036295,-0.162802,-0.462062,-0.171110,-0.491827,-0.285808,-0.359614,-0.235493,0.424485,0.099995,-0.243117,0.307761,-0.599064,0.228183,0.255191,0.132444,-0.290656,0.426513,0.217846,-0.000199,-0.044426,-0.050779,0.426429,0.066746,0.371274,0.134923,0.453623,-0.377409,0.209113,-0.519893,0.500225', '21619567', '2365260', '11615927', '1297598');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2174535', '天龙特攻队', '动作', '“汉尼拔”约翰·史密斯（连姆·尼森 Liam Neeson 饰）、坦普莱顿·派克（布莱德利·库珀 Bradley Cooper 饰）、莫多克（沙尔托·科普雷 Sharlto Copley 饰）和“水牛”巴拉克斯（昆顿·杰克逊 Quinton Jackson 饰）曾经是美军游骑兵成员，四人在与墨西哥恶徒交火中相遇，并由此成立靠赏金为生的天龙特工队。在成军8年后，天龙特工队接到新的任务。据说伊拉克战争期间有隶属美国的黑军抢夺伊方印钞机，并用它大量生产伪造美钞。史密斯等人的任务就是在伪钞和设备运回美国之前将其夺回。然而事态却朝着无法预料的方向发展，史密斯的上司更死于离奇的意外。在此之后，天龙特工队被军事法庭判刑。此后不久，史密斯和成员相继越狱，势要将黑军的败类绳之于法……本片根据美国20世纪80年代的同名电视剧集改编。©豆瓣', '连姆·尼森', '乔·卡纳汉', 7.7, 82016, 'tt0429493', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p987138955.jpg', 0.4, 2.9, 28.7, 48.2, 19.8, '0.058590,-0.189320,-0.607600,0.404804,0.130098,-0.275106,0.343050,-0.244494,-0.576277,-0.155458,0.150300,0.675066,0.055990,-0.352589,0.340678,-0.041550,-0.585979,-0.818761,-0.154112,-0.279195,-0.250513,-0.500047,-0.291419,-0.487597,0.048756,-0.424883,0.766324,-0.013128,-0.111029,0.641344,0.266940,0.530871,-0.257124,0.039343,-0.063735,0.116168,0.349415,-0.186916,-0.547079,0.275968,0.035301,-0.206326,-0.116064,0.040021,0.223170,0.457475,0.510155,-0.432291,0.168805,-0.273093,0.078176,-0.276271,-0.052734,-0.114856,0.584991,0.191766,-0.017342,0.379180,-0.277249,0.013224,-0.050252,-0.215499,-0.599283,-0.096792,-0.005521,0.341949,-0.258992,0.340748,-0.316209,0.422812,0.118788,-0.232044,-0.041394,0.442569,0.460897,0.146910,0.025494,0.048974,-0.493363,0.221870,0.333902,-0.196924,-0.197632,0.042692,0.125578,-0.430211,-0.226846,-0.138382,-0.139488,0.028589,0.529479,-0.074456,0.165521,0.407566,-0.664566,-0.092897,-0.351432,-0.270040,-0.121730,0.037022,-0.001647,-0.967926,0.112822,-0.177319,-0.091747,0.078273,0.101173,0.014653,0.419046,-0.613601,0.101446,0.288149,0.346382,-0.338694,0.210820,-0.133955,0.163393,-0.438346,-0.029203,0.208058,0.504002,0.345805,0.357836,0.130087,0.083241,-0.464470,-0.022853,0.346840', '25723905', '20274039', '1293572', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21765841', '甜蜜杀机', '喜剧', '资深刑警王志毅（苏有朋 饰），办案效率奇差，婚姻介绍的相亲照看得比嫌犯照还认真，对危险的任务预感奇准，总能在适当的时刻拉肚子躲警报。 但这一次，一向不被长官器重的志毅，突然被指派一项超级任务──监视刚从警校毕业的新进同事高依萍（林依晨 饰）。原来高依萍是警察署长的女儿，署长说不动女儿放弃当警察，只好细心挑选女儿的搭挡。经过考量，擅于闪躲任务、求安全的志毅正是最佳人选！从搭挡的第一天起，两人就被上司故意发配处理闲差，志毅乐得开心，依萍的热情却被浇了一大盆冷水。依萍的满腔热血，碰上了志毅的吊儿郎当，两人成天斗嘴，成了水火不容的冤家搭挡。 然而，他们却在一桩调查社区小狗意外死亡案件的过程中，误打误撞地查到遭通缉毒贩草纸（吴中天 饰）的下落，也因而卷入一起连续凶杀案。第一次碰到棘手的案子，依萍兴奋地想要要揪出幕后凶手，证明自己，志毅却一心只想把依萍拉出危险以求自保。这对冤家在拉扯之间，渐渐卷入整个案件的核心，却也随着破案线索的一一浮现，在凶手呼之欲出之际，陷入连他们自己都不自知的危险中……', '苏有朋', '连奕琦', 6, 14402, 'tt3582088', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171857992.jpg', 5.1, 18.8, 51.2, 19.4, 5.5, '0.345160,-0.181916,-0.591360,0.279371,-0.283263,-0.054032,0.394492,0.141257,-0.464154,-0.062880,0.414489,0.418790,-0.283582,-0.086680,0.281482,-0.127110,-0.082136,-0.770260,-0.033098,0.049986,-0.254142,-0.448877,-0.198769,-0.286779,-0.014128,-0.088957,0.226998,0.038794,-0.220906,0.288418,0.280733,0.278036,-0.381004,0.528580,-0.206129,-0.212181,0.128481,0.017487,-0.028000,0.108144,0.139503,-0.271916,-0.077389,0.052804,0.193119,0.586739,0.480527,-0.087172,-0.248874,0.195184,0.259761,-0.533717,-0.081846,0.083720,0.509553,0.141079,0.122513,0.201175,-0.189137,0.003564,0.092001,-0.216241,-0.691475,-0.006921,0.260116,0.158052,-0.442330,0.305828,-0.112529,0.096193,0.009889,-0.244252,0.210657,0.387902,0.056401,0.350429,-0.126862,0.232280,-0.286676,0.098927,0.471698,-0.225127,-0.052123,0.336512,-0.105009,-0.148473,0.091241,-0.200196,-0.216406,-0.138901,0.340365,0.062206,-0.282740,0.148824,-0.231932,-0.163741,-0.255586,0.021012,-0.135029,-0.377600,-0.176318,-0.135449,-0.076576,-0.163561,-0.450156,0.357858,0.022724,-0.223534,0.343137,-0.560307,0.035043,0.643206,-0.093363,-0.379303,0.491345,0.340135,0.079217,-0.323521,-0.193078,-0.115027,0.238177,0.457221,0.274542,0.336413,-0.138307,-0.393961,-0.343847,0.095721', '1293434', '1947080', '35073886', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21766698', '那天的氛围', '喜剧', '体育经理人在贤（柳演锡饰）是个相当玩世不恭的青年，他在釜山高速列车KTX上第一次见到了秀晶（文彩元饰）就对其一见钟情，性格直率不羁的他提出要和秀晶谈一场一天的恋爱。秀晶是一个不愿意给男人任何可乘之机的“铁壁女”，面对在贤的各种无理要求她相当恼火，而在贤却决心要在24小时 内得到秀晶的心，这样一对想法完全不合拍的两人从此展开了一场爱情拉锯战。', '文彩元', '曹圭章', 6.6, 9605, 'tt5586914', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2297932699.jpg', 2.4, 11.4, 48.9, 26.8, 10.6, '0.240746,0.094904,-0.788473,0.786490,-0.305033,-0.042255,0.805766,-0.007565,-0.599919,-0.091460,0.159518,0.841286,-0.488060,0.060553,0.345327,-0.095830,-0.069966,-0.650432,-0.268933,-0.085388,-0.335977,-0.668623,0.102616,-0.219689,-0.210296,-0.062447,0.693516,-0.010376,-0.156165,0.399037,0.578235,0.053747,0.185871,0.628347,-0.382229,-0.063531,-0.195468,0.095777,-0.107968,0.215073,0.206523,-0.261837,-0.210600,0.645066,-0.162254,0.188571,0.859094,-0.241183,-0.256871,0.188959,0.238187,-0.315825,-0.255988,0.208284,0.221505,-0.377302,0.126915,0.172614,-0.131954,-0.015417,0.146361,-0.173100,-0.455433,0.023892,-0.169977,0.300894,-0.584573,0.833934,-0.016267,0.021705,-0.133751,-0.329105,-0.290345,0.256775,0.194840,0.318886,-0.361934,-0.040872,-0.512511,0.063378,1.025615,0.493199,-0.204046,0.820206,-0.299442,-0.493877,-0.352229,-0.194295,-0.716860,-0.164033,0.357726,-0.201710,-0.270343,0.045532,-0.567301,-0.026584,-0.163428,0.241734,-0.092119,-0.469565,0.095558,-0.503687,-0.027803,-0.897453,-0.452568,0.433770,0.054356,-0.279647,0.728552,-1.421411,-0.101152,0.195966,0.195210,-0.587175,0.655897,0.386978,-0.134725,-0.447763,0.199173,-0.037136,-0.041260,-0.349946,0.034442,0.611070,0.006693,-0.069856,-0.201777,0.656155', '35030151', '1292219', '1395231', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21767183', '0.5毫米', '剧情', '在某老人护理机构供职的山岸佐和（安藤樱 饰）长久以来一直照顾生活不能自理的老人昭三（织本顺吉 饰）。某天昭三的女儿向其提出一个匪夷所思的要求，虽然有些勉强，佐和还是应承了下来，谁曾想这一决定竟彻底改变了她的命运。突如其来的灾难让佐和丢掉了工作，进而流落街头。在四处闲逛的时候，她先后邂逅了康夫（井上龙夫 饰）、阿茂（坂田利夫 饰）、义男（津川雅彦 饰）等有着各种各样怪癖和坏毛病的老年人。佐和就像恶意满满的魔女，不由分说闯入老人们的生活。她霸道地纠正老人们的恶习，却也为他们带来了久违的关怀……本片根据导演安藤桃子依据自身护理经验撰写的小说改编。©豆瓣', '安藤樱', '安藤桃子', 8.3, 27711, 'tt3825360', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507377459.jpg', 0.4, 1.2, 13.1, 51.3, 34.1, '-0.042605,-0.030968,-0.384860,0.567174,0.091330,-0.378988,0.613124,0.368645,-0.346041,-0.329332,0.040702,0.817971,-0.167581,0.304965,0.407698,0.006369,-0.419722,-0.696950,-0.204592,-0.016278,-0.153793,-0.367840,0.000266,-0.255227,-0.242787,-0.310828,0.465225,-0.093400,-0.274089,0.419304,0.312093,0.436552,-0.063539,0.389768,-0.228175,0.101543,-0.219351,-0.006753,-0.117310,-0.232802,0.068313,-0.375878,-0.326048,0.069818,0.189608,0.418585,0.568969,-0.328758,-0.383754,-0.076460,0.222931,-0.101675,-0.123674,0.084670,0.075468,-0.176910,0.164718,0.276835,-0.176864,-0.041221,0.117878,0.022415,-0.853216,-0.187109,0.115490,0.259944,-0.517595,0.270725,0.135490,0.046726,-0.072422,-0.315127,-0.122027,0.095223,0.061462,0.278534,-0.331523,0.066227,-0.126890,0.353749,0.449227,0.103905,-0.222628,0.185675,-0.332910,-0.227195,-0.151199,-0.067073,-0.541115,-0.058658,0.298982,0.013324,-0.291196,0.135757,-0.554762,-0.163267,-0.181245,-0.190697,0.201695,-0.197271,-0.019549,-0.582903,0.071431,-0.595199,-0.555457,0.030292,0.210991,-0.249640,0.883807,-0.882163,-0.120303,0.493912,0.133049,-0.465335,0.416348,0.160260,0.018260,-0.116338,-0.137687,-0.067978,-0.069673,0.442361,0.349674,0.594578,0.000171,0.065700,-0.197700,0.264682', '27602116', '3811356', '24284209', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21767208', '我的男人', '剧情', '女孩小花（二阶堂富美 饰）在大地震中失去了所有的亲人，救生员淳悟（浅野忠信 饰）收留了无家可归的小花，没有血缘关系的两人组成了家庭。一晃眼多年过去，小花已经出落成为了亭亭玉立的少女，淳悟也有了女友（河井青叶 饰），可是后者却发现，在淳悟和小花之间，一种古怪而又诡异的感情 以无法遏制的速度暗自生长着。小花乖戾而又散发着少女甜美的气息，淳悟自闭在深刻漫长的孤独里沉沉浮浮，终于，原本应该只是单纯的家人的两人，突破了道德的界限，双双被淹没在欲望的冰海之中。小花和淳悟，如同共生的动物一样，靠着本能在黑暗里贪婪的存活着，直到有一天，两人的秘密被第三者发现。©豆瓣', '浅野忠信', '熊切和嘉', 6.7, 6694, 'tt2763746', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2179692402.jpg', 2.2, 10.6, 49.2, 28.3, 9.8, '0.447437,0.161805,-0.891300,0.612618,-0.166506,-0.242263,1.012191,0.078219,-0.643273,0.024916,0.230648,0.620479,-0.172652,0.226761,0.093304,0.158095,0.126037,-0.848240,-0.206037,-0.267300,-0.250647,-0.469804,-0.537024,0.195337,-0.070232,-0.394395,0.739418,-0.001872,-0.049909,0.544124,0.034022,0.038945,-0.296178,0.495241,-0.202586,0.180273,0.079683,0.050242,-0.068504,0.112459,0.074975,-0.255156,-0.045217,0.013719,-0.287487,0.383321,0.831797,-0.710938,-0.238122,-0.056684,0.280030,-0.162349,-0.277373,0.333456,0.362009,0.073040,0.337575,-0.011611,-0.248148,0.002824,0.318795,0.139523,-0.517163,0.165416,0.099012,0.501695,-0.666475,0.833515,0.352403,-0.456530,0.320575,-0.557612,0.030255,-0.015411,0.024281,0.594895,-0.454581,-0.046768,-0.548493,0.065365,0.589422,0.136766,-0.593121,0.608058,-0.565230,-0.220936,-0.164137,-0.248543,-0.577335,-0.365945,0.376405,0.321019,-0.398874,0.485475,-0.913841,0.355878,-0.117789,0.020148,-0.340337,-0.458445,-0.285377,-0.159048,-0.487561,-0.637875,-0.379034,0.253591,0.024049,-0.285080,0.906924,-1.026743,0.459628,0.480658,0.310357,-0.028455,0.469727,-0.032016,-0.020125,-0.009692,-0.073619,0.201257,-0.310689,0.450798,0.533113,0.442755,-0.428852,0.162228,-0.503123,0.446101', '21619567', '20020577', '24839498', '21442760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21770915', '冬眠', '剧情', '远离伊斯坦布尔的安纳托利亚，业已退休的戏剧演员艾登（Haluk Bilginer 饰）以专栏作家的身份展开了新的人生。他故作关心地日复一日撰写宗教类的文章，沉浸陶醉在自我所营造的看似深刻的思考世界里无法自拔。艾登用退休金经营一家旅馆，名下还有多处正在出租的房产，在与普通民众的接触过程中让他看起来多了一份虚伪和冰冷。妹妹尼卡（Demet Akbag 饰）早年离婚，经常蜷缩在艾登的书房内针对写作而争论，甚至彼此嘲讽攻讦。他的妻子尼哈尔（Melisa Sözen 饰）年轻独立，热衷各种公益事业。聚少离多且人生态度迥异的老夫少妻渐行渐远，感情出现裂痕……本片荣获2014年戛纳电影节金棕榈奖。©豆瓣', '哈鲁克·比尔根纳尔', '努里·比格·锡兰', 8.2, 25421, 'tt2758880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2197728937.jpg', 0.9, 2.6, 16.8, 45.2, 34.5, '0.325009,-0.084446,-0.711210,0.753127,-0.034350,-0.240183,0.728502,0.401655,-0.428405,-0.328585,0.130070,0.665801,-0.165982,0.219865,0.271654,-0.095337,-0.301273,-0.709154,-0.214795,-0.128606,0.078093,-0.747117,-0.238786,-0.279973,-0.343954,-0.372095,0.564685,0.248734,-0.234506,0.458160,0.135344,0.239434,-0.211857,0.248368,-0.002822,-0.206540,0.136415,0.094826,-0.445432,-0.222405,-0.019959,-0.066011,-0.073730,-0.052771,-0.045101,0.278881,0.846352,-0.142555,0.051057,0.031596,0.573467,0.087410,-0.004308,0.171049,0.001860,0.182668,0.313972,0.336258,-0.430932,0.138237,-0.074354,-0.197410,-0.603690,-0.088211,0.032914,0.061514,-0.451749,0.739972,0.118420,0.000556,-0.074808,-0.147459,0.137677,0.242786,0.319427,0.552287,0.148845,0.167959,-0.245711,0.261106,0.259489,0.076015,-0.496623,0.419135,-0.500001,-0.240509,-0.121576,-0.340405,-0.497063,-0.336868,-0.018742,-0.084348,-0.032581,0.577192,-0.636324,0.195334,-0.072869,-0.230288,0.221992,-0.365660,-0.237633,-0.799406,-0.276522,-0.453631,-0.167431,-0.185373,0.057994,-0.259884,0.674600,-0.698352,0.273145,0.276933,0.259260,-0.307754,0.753279,0.040228,0.196336,-0.226361,-0.397942,0.480565,0.002820,-0.057736,-0.094790,0.170172,-0.104782,0.070757,-0.409337,0.627967', '2334814', '27666513', '1829230', '1299261');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21815004', '花容月貌', '剧情', '伊莎贝尔（玛丽恩·瓦斯 Marine Vacth 饰）是一名17岁的妙龄女孩，拥有着靓丽容貌和美好肉体的她对“性”有着一番独特的见解。一次偶然中，伊莎贝尔遇见了一位游客，就这样，她寥寥草草地献出了自己的处女之身，之后，伊莎贝尔在探索“性”的道路上一路走远。在网络上出售自己的性感照片、利用肉体换取金钱，在做着这些勾当的同时，伊莎贝尔依旧是同学和家人眼中的纯洁少女。一位老年嫖客的出现逐渐改变了伊莎贝尔，她不禁想要在年长的他的身上寻找亲情的依赖，不幸的是，在一次交易中，老年嫖客突发心脏病死亡，警察很快就找到了伊莎贝尔家，她所作的一切都在此时被公之于众。©豆瓣', '玛丽恩·瓦科特', '弗朗索瓦·欧容', 7.5, 53991, 'tt2752200', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1973379676.jpg', 0.5, 2.8, 35, 45.7, 16.1, '0.519100,0.235565,-0.670346,0.705845,-0.500758,-0.312217,1.060616,-0.071492,-0.512503,-0.077646,0.422822,0.878676,-0.217747,0.425644,0.169906,0.202649,-0.160419,-0.787447,-0.222770,-0.156313,-0.400215,-0.461858,-0.414055,0.063570,-0.356085,-0.573961,0.621795,0.061821,-0.207371,0.527438,0.315321,0.106705,-0.030061,0.422442,-0.405035,-0.085958,-0.001884,-0.078188,0.022638,0.271543,0.115658,-0.487920,-0.036309,0.350698,-0.307704,0.404154,0.927932,-0.297941,-0.158787,0.025176,0.523916,-0.053124,0.170558,0.219573,0.242069,0.012561,0.214850,0.046960,-0.309839,-0.195241,0.171392,0.115240,-0.745471,-0.294996,-0.020331,0.395652,-0.665869,0.430111,-0.048767,-0.203301,0.309797,-0.428705,0.099599,0.177182,0.139305,0.403053,-0.111974,-0.102448,-0.497328,0.374368,0.645445,0.385375,-0.368377,0.482461,-0.625276,-0.447506,-0.049945,-0.230790,-0.553418,-0.103943,0.492774,0.136614,-0.111208,0.217508,-0.607113,0.242134,-0.196190,-0.110955,-0.031705,-0.217054,-0.161854,-0.575401,-0.387168,-0.678987,-0.462965,0.098345,0.142651,-0.326625,0.962097,-0.927701,0.177985,0.851070,0.312888,-0.415383,0.667459,-0.073821,0.150512,0.002416,-0.196390,0.222129,-0.099916,0.246656,0.018317,0.554979,-0.093097,0.111224,-0.500861,0.599693', '1292062', '3811356', '30162520', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21817627', '爱宠大机密', '喜剧', '位于纽约的一栋红色公寓中，狗狗麦克（路易·C·K Louis C.K. 配音）陪伴它的主人凯蒂（艾丽·坎伯尔 Ellie Kemper 配音）过着平凡而幸福的生活。它不明白主人为什么每天早出晚归，总希望凯蒂能时时刻刻陪伴着它。这天傍晚，主人带回了一条身形庞大的狗狗杜老大（艾瑞克·斯通斯崔特 Eric Stonestreet 配音），顿时让麦克感觉如天塌了一般。它想办法撵走杜老大，而对方也用以牙还牙，你争我斗的过程中，两个小家伙遭到抓狗队的围捕。在此期间，它们邂逅了兔子小白（凯文·哈特 Kevin Hart 配音）率领的堕落宠帮，经历了史无前例的大冒险。另一方面，麦克的暗恋者啾啾则号召伙伴们，要将善良可亲的朋友救回来。主人不在家的时分，宠物们展开了惊心动魄的大作战……©豆瓣', '路易·C·K', '克里斯·雷纳德', 7.8, 266969, 'tt2709768', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363369616.jpg', 0.3, 2.3, 27.9, 47.5, 22.1, '-0.028035,-0.115448,-0.547530,0.565059,-0.024562,-0.169656,0.572754,0.084619,-0.189213,-0.070276,0.023136,0.388959,-0.014096,0.390729,0.301534,0.190102,-0.197222,-0.233520,-0.004410,0.114868,-0.081818,-0.203513,-0.229172,-0.326807,-0.024510,0.048905,0.238778,-0.164732,0.146561,0.402645,0.132216,-0.048562,0.013753,0.280095,0.048790,-0.064290,0.180348,-0.143285,0.014254,0.095473,-0.073469,0.051646,0.092589,0.163269,0.164371,-0.033323,0.565422,-0.494144,0.009846,-0.348617,0.111728,-0.049615,0.163908,0.129559,0.088666,-0.054907,0.299916,-0.134312,0.029890,0.047959,0.016317,-0.306348,-0.547875,0.189581,-0.145472,0.073224,-0.256362,0.135219,-0.141977,0.178644,0.211513,-0.239350,0.037129,0.231608,0.239519,0.289542,-0.073729,0.268205,-0.353870,0.074175,0.658584,-0.241034,-0.206888,0.240802,-0.230784,-0.309333,-0.009732,-0.055055,-0.572650,-0.119963,0.349543,-0.007772,-0.243289,0.301378,-0.584104,0.018128,-0.154196,-0.166913,-0.306501,-0.239938,-0.068015,-0.410272,0.131468,-0.296412,-0.078215,-0.093061,-0.058226,-0.227714,0.673695,-0.643800,0.285883,0.574279,0.209073,-0.209921,0.521395,0.086787,0.261981,-0.138761,0.113076,0.302757,0.319082,0.156568,0.522024,0.286750,0.091510,0.133255,-0.393842,0.536547', '4181031', '3005387', '5977789', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21871405', '鬼夫', '喜剧', '曼谷王朝战争期间，抱持着对妻子小奈以及即将出世孩子的思念，小小麦闯过血雨腥风的战场，总算和战友小特、老普、阿信以及阿艾熬到了退伍的那一天。历经千辛万苦，小小麦和伙伴们终于回到老家，然而村中清冷的景象却让众人颇为诧异。幸运的是他见到了妻子，夫妻久别重逢，执手相看泪眼竟无语凝噎。欢喜之余，小小麦更热情地留好哥们在家中居住。到了次日，其余四人赶集玩耍，谁知竟意外听说小奈早已难产的流言。那么他们前一日所看到的究竟是谁？当晚，阿艾来到小小麦的家中，不幸证实了听说的一切。他们该如何从女鬼手中救出自己的好兄弟呢？本片根据泰国著名民间传说改编。©豆瓣', '马里奥·毛瑞尔', '班庄·比辛达拿刚', 7.2, 24417, 'tt2776344', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2047570958.jpg', 1.5, 6.3, 37.3, 38, 16.9, '-0.223060,-0.125172,-0.857512,0.078090,0.147881,-0.573799,0.468533,-0.036365,-0.605800,-0.220383,0.272164,0.483042,-0.220371,0.619529,0.375726,-0.106972,-0.347353,-0.446494,-0.227580,-0.240151,-0.297904,-0.037382,-0.256280,0.077169,0.003902,-0.237110,0.245025,0.116567,0.290508,0.435217,0.096935,0.097029,-0.470273,0.296317,-0.316653,0.245431,-0.029757,0.356064,-0.510662,-0.171636,0.088747,-0.145516,-0.494709,-0.072452,0.112280,0.317611,0.698284,-0.241584,-0.399852,-0.053306,0.186111,-0.131023,-0.040304,0.240766,0.285588,-0.052575,0.590061,-0.041537,-0.187972,-0.083459,-0.129228,0.008267,-0.224237,0.305114,0.099567,-0.006701,-0.600100,0.445989,0.124928,-0.162075,0.192455,-0.508878,0.466212,0.601003,-0.022411,0.625638,-0.173250,-0.020092,-0.345277,0.121698,0.736223,-0.082157,0.082892,0.331182,0.299954,-0.354260,0.301808,-0.082118,-0.407186,0.426705,0.327580,0.221392,-0.131025,0.429518,-0.542230,-0.002561,-0.221067,-0.019697,0.208547,-0.347184,-0.123243,-0.407174,-0.101895,-0.287354,-0.318259,0.186648,0.241857,-0.083049,0.784626,-0.581134,0.144164,0.013496,0.143064,-0.362771,0.303791,0.036610,0.193798,-0.181943,-0.088231,0.222126,0.114268,0.120667,0.179871,0.209317,-0.250282,-0.160195,-0.438661,0.213171', '2122766', '5977789', '1306209', '10573695');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21937434', '美娜的文具店', '剧情', '京畿道税务科的公务员姜美娜（崔江熙 饰）工作努力，为人耿直，但却因一次冲动遭到停职两月的处罚，同时未婚夫也暴露了不靠谱的秉性，令她愤而分手。家乡的父亲因病入院，将经营了一辈子的文具店交给她转让出去，处于停职期间的美娜也恰好有时间看店兼处理存货。这家位于桂林小学门口的美娜文具店曾经让童年时的美娜受尽委屈，她只想把店尽快转手。另一方面，美娜昔日的同学——同样毕业于桂林小学的崔强浩（奉太奎 饰）此时回到母校担任老师，昔日不受重视的经历让崔强浩用心呵护自己的每一个学生，美娜此时则置身喧闹的孩子海努力清货。渐渐的，在店中的切身体会令美娜领悟了父亲的心思……©豆瓣', '崔江熙', '郑益奂', 7, 5770, 'tt2969508', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1936190832.jpg', 0.8, 5.7, 47.1, 36.1, 10.2, '0.164336,0.091172,-0.590611,0.446086,-0.098188,-0.344093,0.375083,0.264152,-0.506447,-0.457880,0.057493,0.576949,0.107083,0.547557,0.175457,-0.056758,-0.111714,-0.640511,0.070627,-0.169711,-0.243443,-0.342486,0.208441,-0.097184,-0.264373,-0.220661,0.490647,0.108305,0.030753,0.262640,0.010765,0.336135,0.106000,0.367307,-0.115098,-0.071279,0.006866,0.001053,-0.200524,-0.012334,0.346408,-0.335141,-0.136159,0.076603,0.390753,0.406477,0.848774,0.223570,-0.419338,-0.190024,0.523347,-0.069840,-0.073783,-0.045270,0.252446,0.171930,0.108474,0.178443,-0.678011,0.041477,0.046588,-0.280265,-0.643763,-0.231200,0.236561,-0.201965,-0.585654,0.514685,-0.059579,0.124881,0.031063,-0.183783,0.112545,0.309078,-0.113655,0.512052,-0.208908,0.158261,-0.182157,0.310661,0.830754,-0.102807,0.023900,0.274544,-0.263560,-0.109814,0.155763,-0.313187,-0.567463,0.193580,-0.012961,0.155137,-0.192672,0.078715,-0.246084,-0.214899,-0.240381,-0.126661,0.082015,-0.380351,-0.246604,-0.346487,0.020240,-0.179391,-0.231544,-0.157420,0.032303,-0.205214,0.612203,-0.794965,0.096438,0.330524,0.387884,-0.597407,0.762777,0.025044,0.322076,-0.133234,-0.060189,0.189640,0.168276,0.259257,0.162263,0.211312,-0.003689,-0.308372,-0.311241,0.461603', '3445516', '4861627', '2080130', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21937438', '蒙太奇', '剧情', '15年前，名叫西珍的小女孩遭人绑架杀害，重案组警官吴青浩（金相庆 饰）虽答应西珍母亲（严正花 饰）一定将凶手绳之以法，无奈经过漫长的追查却始终一无所获。眼看追诉期将近，吴警官孤注一掷，结果与嫌疑人对面错过。在此之后，吴警官抱着遗憾离开警队，过起破罐破摔的颓废生活。而西珍妈妈始终不曾放弃追凶的信念，她凭借柔弱女子之躯展开独立调查，终于发现罪犯留下的蛛丝马迹。未过多久，又有一名小女孩在光天化日之下遭人绑架，其作案手法与西珍案件如出一辙，警方旋即布下天罗地网，与之展开周旋。而面对狡猾多端的嫌犯，警方只得再次请出闲赋家中的吴青浩。小女孩命悬一线，西珍妈妈和吴青浩能否抓到犯人，一偿夙愿……©豆瓣', '金相庆', '郑根燮', 8.2, 119905, 'tt2969522', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1951590607.jpg', 0.2, 0.8, 16.1, 53.6, 29.3, '-0.256255,-0.085119,-0.470716,0.129711,-0.127572,-0.182942,0.706487,-0.233607,-0.339266,-0.452906,0.346945,0.142144,-0.046623,0.193706,0.229334,-0.354408,-0.289475,-0.608465,0.041369,-0.136856,-0.173175,-0.346694,-0.221897,0.095088,0.152577,0.069516,0.545276,0.083774,-0.020789,0.353548,0.326085,0.236804,-0.575140,0.423199,0.040798,-0.019994,0.109996,-0.034439,-0.508173,0.101116,0.184097,-0.510916,-0.261159,-0.222882,-0.170878,0.353684,0.517951,-0.278796,-0.280949,-0.119781,0.209861,-0.389306,-0.259603,0.053216,0.384747,0.113063,0.006300,0.309873,-0.331691,-0.157007,0.053654,-0.061122,-0.444748,0.104578,0.429670,-0.007424,-0.168190,-0.141228,-0.165263,0.313267,-0.102669,-0.407042,-0.178367,0.240559,0.294458,0.177462,0.002052,0.204465,-0.446019,-0.054738,0.321566,-0.004160,-0.091477,-0.174895,0.253846,-0.405277,0.316908,-0.536572,-0.133464,0.188456,0.119285,-0.007678,-0.219246,0.026184,-0.228373,-0.176875,-0.509870,0.429700,-0.139797,-0.400984,-0.141199,-0.363612,0.040455,0.037193,-0.354007,0.178918,0.035210,-0.336791,0.218327,-0.411477,0.292282,0.219802,0.339568,-0.411630,0.266207,0.162175,0.092390,-0.206493,-0.057197,0.392094,0.436411,0.625939,0.303945,-0.127415,-0.237180,-0.126884,-0.171806,-0.155150', '1304665', '4023433', '25986180', '4903581');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21937442', '恐怖故事2', '恐怖', '夜幕降临，某保险公司朴部长带着劣迹斑斑的员工李世英来到仓库。他知道世英拥有超能力，通过纸片大小的信息便可感知到某个人的生死过往。朴部长从仓库翻出一件件诡异曲折卷宗，让世英调查真相。《悬崖》靠短线交易赚钱的赵东旭（盛俊 饰）和合作伙伴成均（李秀赫 饰）登山减压，谁知二人意外跌落悬崖，困于绝境。生死存亡之际，一支巧克力棒成为生还的最后希望，却也引发了一连串的悲剧。《事故》录用考试落榜的姜知恩和两个女伴驾车游玩散心，结果在漆黑的山道上发生车祸。所幸三人并无大碍，她们相互搀扶向旅馆方向走去。而在这个事故多发地带，最恐怖的经历接二连三袭来。《逃生》废柴实习老师高柄晨出师不利，不过却结识了热衷咒术的女学生。在女孩的指引下，他坐上了一部灵异电梯，由此进入另一个世界……©豆瓣', '李洙赫', '金成浩', 6.1, 9502, 'tt2961802', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2006888340.jpg', 4.3, 18.8, 51.3, 18.6, 7, '0.330698,-0.072850,-0.482851,0.260832,0.017461,-0.132021,0.789397,0.338500,-0.232412,-0.161250,0.590242,0.571186,-0.296630,0.128797,0.341523,-0.194956,-0.270679,-0.466560,0.184055,-0.104797,-0.642464,-0.291260,-0.062939,-0.153121,0.110628,0.008228,0.444537,0.284028,-0.394351,0.462221,0.140704,0.193447,-0.606642,0.469837,-0.213154,0.031170,-0.094950,0.346061,-0.057812,0.122931,-0.118264,-0.495999,-0.294679,-0.129725,0.127074,0.373977,0.691196,-0.061703,-0.240954,0.136250,0.383354,-0.301834,-0.031731,-0.005797,0.308766,0.231567,-0.000369,0.109488,-0.045134,0.006643,0.092446,0.004874,-0.499019,-0.019519,-0.116852,0.242400,-0.398401,0.380758,0.045295,-0.186771,0.128429,-0.377481,0.124906,0.294271,-0.046955,0.093917,-0.194915,0.157484,-0.383822,0.049938,0.396705,-0.149013,-0.261921,0.244375,-0.020264,-0.409888,0.060772,0.086810,-0.106519,0.038366,0.455474,0.099657,-0.095810,-0.049340,-0.491340,0.287649,-0.109960,-0.054482,-0.104821,-0.172254,-0.282519,-0.669978,-0.071938,0.113332,-0.414475,0.154062,-0.028535,-0.139246,0.534847,-0.258284,0.083347,0.498167,0.099345,-0.327631,0.782887,-0.120124,0.113421,-0.269254,0.096515,0.112168,0.073563,0.651992,-0.016796,0.362526,-0.188598,-0.127937,-0.449905,0.070644', '10466639', '20451118', '1401900', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21937445', '辩护人', '剧情', '1978年，只有高中学历的宋佑硕（宋康昊 饰）通过多年的艰苦努力，终于通过司法考试，并在成为法官后很快转行成为一名律师。他敏锐地从最新政策中嗅到商机，以不动产代书业务起家。虽然被同行讥讽为随时随地派发名片的夜店小弟，但佑硕不以为忤，一步一步朝着心中的目标迈进。他依靠赚来的钱让妻儿过上富足的生活，也还了七年前在饭店大婶那里欠下的良心债。进入20世纪80年代，韩国民主化斗争愈演愈烈。佑硕全然不管窗外事，关起门来继续赚钱。然而社会的巨变已经不容他置身事外，饭店大婶的儿子朴镇宇因从属的釜山读书联合会被控为左翼社团而遭到逮捕，更受到残酷的虐待和不公的指控。虽然爱钱却更重感情的佑硕，就这样走上了为民主辩护的道路……©豆瓣', '宋康昊', '杨宇硕', 9.2, 554931, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2158166535.jpg', 0.1, 0.2, 4.4, 28.7, 66.5, '0.252481,0.086012,-0.454470,0.481185,-0.055553,-0.366717,0.406656,0.155079,-0.356289,-0.137536,0.035255,0.715285,-0.011074,0.284049,0.218993,-0.139267,-0.177941,-0.753778,-0.127981,-0.072749,-0.101865,-0.377372,-0.039667,-0.021946,-0.506430,-0.174204,0.760586,0.276911,-0.129729,0.357563,0.162478,0.100433,0.067364,0.333750,-0.135461,-0.080137,0.190256,0.109721,-0.462132,0.037031,0.156450,-0.384828,-0.298468,0.143014,0.137802,0.295843,0.458375,-0.067478,-0.197762,-0.053094,0.533508,-0.165537,-0.172477,0.167148,0.166768,0.118454,0.100072,0.538978,-0.186733,0.241416,-0.104431,-0.268558,-0.896965,-0.170783,-0.091170,-0.059034,-0.657948,0.398857,-0.022137,-0.088524,-0.001171,-0.180731,-0.011899,0.389549,0.154032,0.554369,-0.454110,0.385451,-0.440848,0.087648,0.669587,0.059537,-0.254143,0.291864,-0.131885,-0.353860,0.199769,-0.423303,-0.297428,-0.245280,-0.110825,0.077459,-0.117319,0.201508,-0.420457,0.284708,-0.142427,-0.275172,0.251493,-0.249765,-0.250899,-0.407209,-0.188871,-0.244533,-0.161325,0.307356,0.164383,-0.479086,0.459618,-0.702320,0.111894,0.323241,0.550704,-0.767315,0.720254,-0.023204,0.048228,-0.363033,-0.356239,0.219387,0.101782,0.443688,0.146342,0.001324,-0.031705,-0.418304,0.200167,0.580487', '26678784', '6101834', '1793491', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21937450', '国际市场', '剧情', '朝鲜战争期间，少年尹德秀随同父母登上美军的救援船，却遭遇了毕生难忘的生离死别。战火虽然停息，南北半岛则一分为二，饱受炮火荼毒的北方故乡遥不可及。长大之后，代替父亲成为顶梁柱的德秀（黄政民 饰）努力赚钱，为了筹备弟弟妹妹的学费，他和童年好友千达九（吴达洙 饰）前往西德当起了矿工。万里家国，乡愁如缕，孤独的德秀偶然邂逅在德国念护士专业的韩国女孩英子（金允珍 饰），从此黑若煤炭的生活照进了灿烂光芒。快乐的时光与死亡的磨难如影随形，好在在经历了生死考验之后，德秀回到朝思暮想的家中，并赢得了英子的芳心。漫长而坎坷的人生路，德秀在妻子、亲朋的陪伴下艰难前行……©豆瓣', '黄政民', '尹济均', 8.5, 74997, 'tt3812366', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2210568759.jpg', 0.3, 1.2, 13.1, 42.5, 43, '-0.283352,-0.075850,-0.608645,0.383131,0.263348,-0.410276,0.799157,0.058887,-0.462852,0.016093,0.211299,0.614952,0.168105,0.381860,0.465847,-0.070152,-0.148332,-0.790057,0.022860,-0.140917,-0.095730,-0.219613,-0.116995,0.081280,-0.000060,-0.422312,0.614596,0.373335,0.195501,0.627201,0.024544,-0.025485,-0.256977,0.121794,-0.335445,0.193996,-0.140640,0.338146,-0.615880,-0.094713,-0.168225,-0.311734,-0.182248,-0.179663,0.151529,-0.025811,0.883372,-0.139422,0.053611,-0.095486,0.195874,-0.300445,-0.121980,0.088658,0.030452,0.218738,0.266752,0.163216,-0.133472,-0.006899,-0.020246,-0.147672,-0.514958,-0.090520,0.187960,0.030129,-0.667209,0.853243,0.039853,0.033506,0.150737,-0.370815,0.026225,0.384626,0.077258,0.485604,-0.429248,0.367974,-0.111559,0.624735,0.960180,-0.101995,-0.115333,0.299308,-0.281680,-0.107216,0.169125,-0.292113,-0.716854,0.029391,0.447000,0.127703,-0.135997,0.541092,-0.632426,0.154851,-0.315813,-0.096646,0.121080,-0.236995,-0.310832,-0.527138,-0.071908,-0.443118,-0.313479,0.215638,-0.035128,-0.323947,0.868440,-0.661921,0.406776,0.370706,0.290511,-0.368813,0.563354,0.239027,0.386191,-0.251009,0.151523,0.800781,-0.167856,0.526187,-0.089249,-0.078753,-0.506945,0.221399,-0.494772,0.293396', '27040921', '26926321', '1308890', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21937452', '素媛', '剧情', '她（李来 饰）是一个美丽平凡的小女孩，和爸爸妈妈生活在位于街角的家中。家里经营着以她的名字素媛命名的杂货店，母亲（严智媛 饰）作为老板娘日夜忙碌不得闲暇，父亲则在工厂干着繁重的工作。在那个飘雨的早上，素媛打着雨伞独自上学。在离学校近在咫尺的地方，她遭遇一个相貌猥琐、酒气冲天的大叔，由此开启了她的悲剧之旅。柔嫩的小花遭到暴风雨无情摧残，受伤的岂止枝枝叶叶，更是那迎着阳光无忧成长的心。无良媒体铺天盖地大肆渲染，作为受害者的素媛一家仿佛成了周身污秽的耻辱之人，被四周诧异好奇的目光所包围。妈妈悲痛欲绝，几近崩溃。爸爸全力保护女儿，但受伤的小天使却拒绝爸爸的靠近。问凶之路伴随着天使的治愈旅程，美丽的女孩可会再露灿烂笑容？©豆瓣', '薛景求', '李濬益', 9.3, 637023, 'tt3153634', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2118532944.jpg', 0.1, 0.2, 3.7, 26.7, 69.3, '0.013442,-0.016709,-0.582604,0.363549,-0.249719,-0.112373,0.786521,0.437514,-0.194233,-0.108746,0.482808,0.384212,-0.032136,0.620225,0.308754,0.253360,0.030475,-0.394246,-0.257591,0.066522,-0.063663,-0.039772,-0.188476,-0.131960,0.131766,-0.423747,0.408863,0.090335,-0.036408,0.585513,0.097681,0.094686,-0.256012,0.434916,-0.261552,-0.092812,-0.169994,-0.168944,-0.094821,-0.037869,-0.206622,-0.330678,-0.148697,0.164718,-0.185712,0.288507,0.852889,-0.061799,-0.286589,-0.214399,0.522433,-0.303890,0.085519,0.228712,0.267705,0.005577,0.229386,-0.071586,-0.233430,-0.016966,0.196211,-0.241710,-0.634102,0.088038,0.281166,0.186407,-0.429268,0.522820,0.002611,-0.090879,0.253184,-0.490088,0.181495,-0.126158,-0.125520,0.851335,-0.228585,0.359051,-0.376828,0.341427,0.458076,0.004187,-0.212207,0.333445,-0.414481,0.148610,0.158987,-0.192009,-0.767732,-0.075082,0.341048,-0.066379,-0.095277,0.267102,-0.620889,0.164963,-0.101291,-0.088908,-0.082878,-0.269642,-0.424921,-0.462846,0.061121,-0.293654,-0.326341,0.121135,-0.161496,-0.157551,0.706503,-0.663817,0.327879,0.621307,0.257164,-0.275832,0.501347,0.156949,0.124595,0.058280,-0.173659,0.525352,0.008543,0.453220,-0.013160,0.202443,-0.202881,0.209710,-0.307151,0.461612', '10533913', '21619567', '4233625', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21939167', '灰烬重生', '悬疑', '十年前，九十年代末的斯城，工人徐峰在继父死后远走，警察陈维坤没有在命案中发现任何线索。十年后，医生王栋偶然进入陈维坤的视野，徐峰也回到斯城，面目全非。新的角逐就此展开，属于曾经的心灵秘密慢慢释放出来。', '罗晋', '李霄峰', 5.6, 5251, 'tt7708320', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2610558799.jpg', 7, 29.6, 45, 15, 3.5, '-0.098307,0.221519,-0.780347,0.293225,-0.105487,-0.451198,0.727063,-0.306820,-0.928302,-0.492891,0.284569,0.746538,-0.017701,0.160338,0.197138,-0.117050,-0.473260,-0.710645,0.025997,-0.770918,-0.536515,-0.358135,-0.197315,0.030593,-0.132633,-0.469287,0.759595,0.266525,-0.202725,0.449073,-0.278304,-0.115703,-0.396926,0.397891,-0.087730,0.351010,0.283233,-0.057436,-0.767226,0.406558,-0.086192,-0.221794,-0.225127,-0.120796,-0.013598,0.390000,0.647505,-0.251422,-0.412520,0.203767,0.507628,-0.024104,-0.335090,0.024187,0.496615,0.051324,0.243933,0.378027,-0.435200,-0.206594,-0.361045,-0.049760,-0.060650,-0.248223,-0.105822,0.450299,-0.341966,0.427957,-0.079550,0.196118,0.137510,-0.427199,0.131759,0.370577,-0.027734,0.087617,-0.158432,0.053067,-0.429967,0.124827,0.526706,-0.203072,-0.450371,0.220756,0.237045,-0.409459,-0.136946,-0.011544,-0.248183,0.104949,0.398121,0.244957,-0.241357,0.547377,-0.447848,-0.049718,-0.254744,-0.060373,0.376338,0.224731,-0.206230,-0.576232,-0.237380,0.088176,-0.049837,0.255410,-0.189128,-0.220936,0.081314,-0.763554,0.775558,0.312926,0.229459,-0.264675,0.369001,-0.316052,0.333962,-0.138186,0.089702,0.603294,0.247338,0.988214,-0.017959,0.134793,-0.167043,-0.277594,-0.513353,0.385256', '1465415', '1302488', '11615927', '1304665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21941770', '赏金猎人', '剧情', '李山（李敏镐 饰）和阿Yo（钟汉良 饰）曾经同为国际刑警，后因任务失败被一同革职，当起了私人保镖。在一起看似普通的爆炸案中，两人与由凌芯（唐嫣 饰）、Swan（吴千语 饰）和宝宝（樊少皇 饰）组成的赏金三人组狭路相逢，一番冲突较量后，他们组成了专门缉捕罪犯、维护社会安宁的赏金天团，在经历了连番惊险的任务后，五人凭着各自的绝技，成功挫败了连环恐怖袭击，抓住了幕后操控的黑手。©豆瓣', '李敏镐', '申太罗', 5.2, 38965, 'tt5243900', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2358403173.jpg', 17.7, 30.8, 34, 10.5, 6.9, '0.273507,0.011805,-0.584812,0.479036,0.036652,-0.148949,0.483023,0.151065,-0.469013,-0.088521,0.467777,0.449822,-0.182622,-0.220491,0.248931,-0.508046,-0.235074,-0.906550,-0.181404,-0.216589,-0.350726,-0.466946,-0.171555,-0.131658,-0.112035,-0.161534,0.490881,-0.090548,-0.025444,0.802299,0.608888,0.491338,-0.497813,0.065792,-0.092880,-0.059859,0.390429,0.081334,-0.458870,0.248723,-0.143623,-0.357891,-0.079465,0.080238,0.016243,0.435016,0.988642,-0.570586,0.053059,-0.399785,0.001840,-0.159230,-0.101301,0.009120,0.347652,0.387907,0.487129,0.153879,-0.244875,0.053726,0.260102,-0.088437,-0.719035,-0.168968,0.439469,-0.036329,-0.475180,0.531056,-0.090135,-0.049456,0.043193,0.003158,0.222392,0.490286,0.607130,0.219154,0.015646,0.071378,-0.237172,0.366740,0.708408,-0.073667,0.222308,0.118016,-0.036127,-0.567977,-0.278514,-0.255599,-0.038310,0.018506,0.476881,-0.055645,0.027689,0.175286,-0.880199,-0.096524,-0.235073,0.276225,-0.244438,-0.424226,0.198619,-0.853987,-0.035816,-0.341812,-0.318538,0.275139,-0.015458,-0.050485,0.442924,-0.851664,0.187417,0.408758,0.259270,-0.474021,0.289776,0.157307,0.446238,-0.190185,0.079119,-0.370380,0.164403,0.468437,0.506811,0.456734,-0.088181,-0.141640,-0.255737,0.174853', '26365262', '25723905', '26991880', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21941804', '白日焰火', '剧情', '外表冷艳的吴志贞（桂纶镁 饰）身上散发着熟女的魅力，这对于男人来说是一种致命的诱惑，对于与她曾有过一面之缘的警察张自力（廖凡 饰）来说更是如此。五年前，吴志贞的丈夫梁志军（王学兵 饰）被警方认定死于一桩离奇碎尸案，当时张自力破案后击毙了持枪拒捕的凶手。五年后，又发生了 类似的连环案件，并且这些死者都曾与吴志贞相恋，心结未了的张自力主动接近吴志贞，却飞蛾扑火般的爱上了这个女人，两个遭遇重大生活挫折的人逐渐从惺惺相惜到相爱，随着更加亲密的接触，张自力发现了五年前的真相……©豆瓣', '桂纶镁', '刁亦男', 7.6, 362977, 'tt3469910', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2174645340.jpg', 0.6, 2.9, 30.8, 49.5, 16.2, '0.292153,-0.126599,-0.592664,0.560388,-0.178452,-0.255417,1.132478,-0.221878,-0.659980,-0.332233,0.342538,0.450243,-0.256976,0.488025,0.163686,-0.296761,0.020840,-0.802007,-0.054961,-0.380689,-0.401173,-0.483915,-0.314810,0.162033,-0.178667,-0.015664,0.580416,0.102703,-0.370956,0.415130,0.372232,0.406067,-0.038641,0.480067,-0.099534,0.025393,-0.071235,0.361512,-0.457808,-0.207096,0.312968,-0.488979,-0.084599,0.162093,-0.301280,0.383036,0.561749,-0.347332,-0.672136,-0.268025,0.681806,-0.099874,-0.074908,0.312551,0.388096,0.174689,0.269533,0.361921,-0.253493,-0.270815,0.231770,0.058277,-0.666481,0.127778,0.155200,0.031342,-0.442825,0.133181,-0.166794,0.113852,0.145844,-0.272706,0.059445,0.450978,0.284672,0.277592,-0.167957,0.162077,-0.377150,0.320420,0.888846,0.185484,-0.510651,0.169751,-0.021236,-0.630135,-0.271798,-0.114387,-0.231424,0.432458,0.217312,0.068118,-0.193548,0.321496,-0.644418,0.157547,-0.201862,0.355072,0.086934,0.013974,-0.179078,-0.415484,-0.533950,-0.671813,-0.382161,0.367826,0.198308,-0.443261,0.532436,-0.625290,0.207972,0.178600,0.181085,-0.554921,0.494823,0.228627,-0.130153,-0.249059,-0.005322,0.431572,0.148990,0.132346,0.201878,0.509105,0.020985,0.113432,-0.055334,0.456984', '25828589', '1307748', '25909236', '21348112');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21943062', '黑猫警长之翡翠之星', '喜剧', '在一个电闪雷鸣的日子里，身陷囹圄的一只耳成功越狱，引起黑猫警长的高度重视。次日一早，崇拜黑猫警长的小猪三嘟被伙伴大壮拉走，偷偷进入了即将开幕的翡翠之星博物馆。博物馆的前身是一座宇宙飞船，六十年前由羊山博士亲手开发。正当他们玩得不亦乐乎的时候，两个小家伙突然看见了鬼鬼祟祟的一只耳以及一个身材魁梧穷凶极恶的邪恶之人。这个家伙声称曾遭羊山博士背叛，当得知羊山博士已经去世的消息，他一腔怒火无处宣泄。狡猾的一只耳怂恿对方将复仇对象转移到全城人们，等后天博物馆开幕之际将市民全部绑架。三嘟趁乱夺走了一只耳手中的能量块，而黑猫警长即将面临前所未有的大挑战……©豆瓣', '赵路', '于胜军', 5.3, 6720, 'tt4885924', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2256616545.jpg', 17.6, 27.2, 35.2, 12.3, 7.8, '0.180739,0.095724,-0.727531,0.303847,-0.005137,-0.116693,0.646972,0.221336,-0.324762,-0.267977,0.255947,0.613221,-0.409537,0.401216,0.255493,0.171280,0.113255,-0.539598,-0.336826,-0.088720,0.016653,-0.110456,-0.250458,0.055218,0.084926,-0.244587,0.518011,-0.058317,-0.139001,0.731691,0.117047,0.309982,-0.095847,0.441799,-0.270040,-0.198184,0.492767,-0.132095,0.029570,0.209272,-0.055331,-0.228152,0.086938,0.139742,-0.551594,0.125788,0.816475,-0.386307,-0.149043,-0.149335,0.470504,-0.465291,-0.040197,0.178586,0.654881,-0.064507,0.049788,-0.166088,-0.477811,-0.104231,0.130165,-0.335765,-0.616298,-0.062766,-0.239567,0.084165,-0.240174,0.080580,0.041954,0.498041,0.382966,-0.277852,0.455849,0.042121,-0.027161,0.432364,-0.237284,0.091483,-0.519369,0.026152,0.562508,-0.562176,0.154512,0.046726,0.316620,-0.238298,0.138613,-0.061407,-0.395641,-0.030095,0.680574,0.135285,-0.528721,0.231838,-0.564745,-0.081531,-0.525139,-0.165775,0.164073,-0.263248,-0.378491,-0.416567,-0.198123,0.273497,0.038420,0.140992,0.205825,0.084505,0.621373,-0.513097,0.307427,0.676368,-0.019736,-0.083089,0.464822,-0.157130,0.275850,-0.176304,-0.055031,-0.192217,0.592582,0.497828,0.045124,0.400630,-0.124824,-0.381419,-0.483471,0.453599', '1309194', '21619567', '26882457', '4832825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21965464', '圣人文森特', '剧情', '玛姬（梅丽莎·麦卡西 Melissa McCarthy 饰）和儿子奥利弗（杰顿·李博赫 Jaeden Lieberher 饰）两人过着相依为命的生活，在巨大的生活压力之下，玛姬不得不在医院里加班加点的工作赚钱，自然也就无力照看年幼的奥利弗。于是，玛姬将奥利弗托付给了邻居文森特（比尔·默瑞 Bill Murray 饰）——一位看上去风度翩翩的优雅老人。然而，真实的文森特脾气暴躁，酗酒如命，沉迷赌博，甚至和脱衣舞女达卡（娜奥米·沃茨 Naomi Watts 饰）一起带着奥利弗去夜总会鬼混。奥利弗目睹了文森特的种种“恶行”，却用一种孩童式的善意目光进行着解读，随着时间的推移，文森特和这个小男孩之间建立起了坚实的友谊。©豆瓣', '比尔·默瑞', '西奥多·梅尔菲', 7.7, 10726, 'tt2170593', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2217219990.jpg', 0.3, 2, 28.3, 51.5, 18, '0.243137,-0.024516,-0.617374,0.657642,-0.144593,-0.450870,0.914576,0.359123,-0.268745,-0.283227,0.023640,0.592368,-0.137133,0.611390,0.255391,0.085603,-0.568547,-0.606870,-0.210620,0.157547,-0.090308,-0.559729,-0.132742,-0.352622,-0.166304,-0.261901,0.183244,-0.244652,-0.111536,0.643462,0.340385,0.247970,-0.090639,0.359715,-0.187696,-0.025313,0.166994,-0.217083,-0.114435,-0.062276,0.354089,-0.058540,-0.122017,0.113914,0.311532,0.288024,0.633657,-0.314224,0.074419,0.029738,0.242000,0.084636,0.104514,0.215285,0.093104,0.035104,0.032507,0.047865,-0.299215,-0.025238,0.384042,-0.200428,-0.614799,0.146423,-0.086540,0.180868,-0.672923,0.551596,-0.044546,-0.109637,0.181788,-0.387391,-0.108925,0.254822,0.089525,0.399242,-0.225142,0.182409,-0.351612,0.056082,0.421216,0.198218,-0.303456,0.350237,-0.534413,-0.215989,-0.241367,-0.118214,-0.602334,-0.478164,0.309482,-0.073687,-0.029314,0.498586,-0.637588,-0.012976,-0.202609,-0.077278,-0.087951,-0.329477,-0.086706,-0.840275,-0.219457,-0.630543,-0.376854,0.085561,-0.019691,-0.168332,0.685657,-0.601116,0.238090,0.565716,0.218208,-0.053958,0.532364,-0.035388,0.262604,-0.140948,-0.241782,0.515351,0.001468,0.018006,0.319315,0.502472,-0.007740,0.117064,-0.219863,0.678907', '24639908', '26677495', '1309172', '1394176');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('21977761', '暗夜逐仇', '剧情', '吉米（连姆·尼森 Liam Neeson 饰）是一位经验丰富，精明强干的职业杀手，效力于黑帮老大肖恩（艾德·哈里斯 Ed Harris 饰），两人合作多年，彼此之间结下了深厚的友谊。整日生活在鲜血和阴谋之后，吉米感到十分疲倦，他产生了想要“退休”的念头。麦克（乔尔·金纳曼 Joel Kinnaman 饰）是吉米的儿子，父亲的特殊身份让两人的父子关系十分淡漠，然而，一场意外的发生让吉米杀死了肖恩的儿子丹尼（波伊德·霍布鲁克 Boyd Holbrook 饰），麦克亦成为了黑帮追杀的对象。为了保护儿子的安全，吉米重装上阵，和昔日旧友们展开了血腥厮杀。他们只有一夜的时间，一夜过去，吉米和麦克将会面临怎样的结局？©豆瓣', '连姆·尼森', '佐米·希尔拉', 6.8, 18139, 'tt2199571', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233767512.jpg', 0.8, 6, 52.6, 32.2, 8.4, '0.068260,-0.092316,-0.579957,0.421467,-0.011794,-0.315222,0.768918,0.129112,-0.771548,-0.456364,0.145741,0.674343,-0.092551,0.069263,0.420393,-0.305211,-0.242942,-0.853132,-0.104307,-0.019432,-0.110502,-0.501206,-0.298157,-0.449997,0.001340,-0.327494,0.501133,-0.129821,0.073380,0.511088,0.415132,0.531702,-0.092514,0.306264,-0.004377,0.013476,0.263878,-0.186219,-0.624966,-0.005773,0.225846,-0.031366,-0.188675,0.118660,0.010703,0.367228,0.423862,-0.066943,-0.105457,-0.163381,0.046017,-0.227823,0.067423,0.097494,0.337139,-0.154079,0.170870,0.385253,0.035817,-0.193487,0.179483,0.035332,-0.756537,0.193717,0.098768,0.208872,-0.543107,0.472965,-0.195101,-0.147450,0.041133,-0.183043,0.005227,0.542190,0.431579,0.232733,-0.086568,0.144926,-0.462170,-0.173736,0.847344,0.024366,-0.252813,0.035222,-0.299150,-0.247750,-0.191736,-0.380430,-0.373917,-0.127801,0.693668,-0.067878,-0.042984,0.515214,-0.704273,-0.187355,-0.403515,0.020701,-0.051395,-0.390009,0.235214,-0.742066,-0.271301,-0.535004,-0.492277,-0.075687,0.061778,-0.421463,0.665024,-0.792663,0.105561,0.326383,-0.024099,-0.354924,0.419598,0.347740,0.206262,-0.274039,0.216331,0.260212,0.101988,-0.162777,0.380631,0.199399,-0.071439,0.171383,-0.040108,0.416536', '11541282', '1301022', '25828589', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22049595', '钢铁侠：噬甲危机', '动作', '斯塔克公司最新研制的天幕卫星“霍华德”即将升空，它超强的监视功能饱受争议。而托尼·斯塔克则饶有兴致地与战争机器詹姆士·罗德穿着各自的铠甲进行连番惊险刺激的较量。就在此时，号称“突击兵”的武装机器人入侵发射场，与钢铁侠和战争机器展开激烈的混战。而指挥部方面，一名自称以西结的神秘白色铠甲人释放出神秘生物细胞，杀害了所有眼前的生物。钢铁侠在与他的对决中遭遇惨败，指挥塔也彻底毁灭。在此之后，他拒绝向神盾局汇报细节，独自一人找到正在休假的佩珀·波茨，一同调查以西结的身份及其真实目的。一方面，神盾局对斯塔克紧追不放；另一方面，来自暗处的敌人也接二连三向他袭来……©豆瓣', '诺曼·瑞杜斯', '滨崎博嗣', 5.9, 3328, 'tt2654124', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2040412492.jpg', 6.2, 22.4, 47.2, 16.1, 8, '0.020622,0.027710,-0.735774,0.655985,0.086601,0.369878,0.620471,-0.056405,-0.122803,-0.405257,0.486766,0.547815,-0.107035,-0.288186,0.173030,-0.146462,-0.344082,-0.654741,-0.247478,0.048428,-0.448163,-0.306450,-0.315061,-0.408465,0.349209,-0.473442,0.752925,0.102306,-0.501115,0.311801,0.305106,0.611701,-0.479867,0.488760,0.076928,-0.412073,-0.077483,-0.183075,-0.232876,0.267861,-0.243999,-0.182343,-0.000092,0.390685,-0.157025,0.261898,0.876448,-0.468938,0.116520,-0.241591,0.160922,-0.275434,0.245302,0.028979,0.506561,0.207459,-0.122762,0.112092,0.090585,-0.037519,0.078185,-0.001939,-0.799686,-0.221332,-0.050985,0.019555,-0.318622,0.399035,-0.354844,0.199088,0.071382,-0.165126,0.101842,0.431653,0.288536,0.325972,-0.211879,0.090725,-0.430631,0.005338,0.405351,0.155019,-0.397336,-0.098052,-0.008393,-0.213499,-0.323846,-0.248740,-0.217635,-0.354440,0.387040,0.138020,0.184508,0.309003,-0.932682,0.247606,-0.254337,-0.279222,0.017802,-0.359127,-0.061448,-1.058140,-0.070738,-0.308791,-0.143590,0.347071,-0.165341,0.127006,0.480163,-0.623238,0.064930,0.536893,0.228323,-0.445776,0.409549,0.054716,0.140583,-0.355284,-0.156236,0.018100,0.279345,0.459676,0.091049,0.338084,0.137346,-0.084838,-0.305705,0.175083', '1306809', '20274039', '2369613', '1307897');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2208890', '姊姊妹妹站起来', '剧情', '佟李氏（梁明 饰）很早就失去了丈夫，和女儿大香（李萌 饰）过着相依为命的生活。孤苦伶仃的母女两人进城投奔舅母孙大妈（田太宣 饰），就此结识了名为尚幼林（李纬 饰）的男子。善良的尚幼林常常帮助生活困苦的佟李氏，一来二去之间，两人之间渐渐产生了真挚的感情。贪婪阴险的孙大妈伙同崔胡子（崔超明 饰）和胭脂虎（李凌云 饰）夫妻两，设计将大香卖到了两人经营的妓院中，大香就此沦为妓女。眼看女儿遭受着非人的待遇，绝望的佟李氏选择了跳河自尽。然而尚幼林却没有放弃希望，想方设法替大香赎身，却最终以失败告终。1949年北平解放，解放军的到来让大香终于重新获得了自由。©豆瓣', '李萌', '陈西禾', 9, 12753, 'tt17059942', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2532438503.jpg', 0.2, 0.5, 7.1, 30.4, 61.8, '0.051144,0.133408,-0.557957,0.558491,-0.124096,-0.645820,0.583200,0.241265,-0.513347,-0.360982,-0.135298,0.216210,-0.227229,0.543281,0.213671,-0.423645,-0.002172,-0.647504,-0.284976,0.196604,-0.239265,-0.407267,-0.026796,-0.216503,-0.519329,0.182585,0.417247,0.293003,-0.025440,0.535973,0.248443,0.208821,-0.174988,0.551616,-0.117514,0.422367,0.082575,0.197164,-0.477620,-0.115556,0.182858,-0.502989,0.025018,-0.036824,0.034050,0.260027,0.838454,-0.386047,0.052727,-0.307939,0.211516,0.041305,-0.110122,0.231290,0.319231,-0.025491,0.100202,-0.083012,-0.341999,-0.090550,0.253805,-0.149151,-0.412404,0.233774,0.280370,-0.172923,-0.768408,0.363671,0.133744,0.096492,0.022118,-0.384102,0.225360,0.315502,0.344494,0.347981,-0.346970,0.199868,-0.590864,0.399527,0.718161,0.115368,-0.064903,-0.005911,-0.479277,-0.456243,0.207888,-0.268763,-0.467117,-0.141762,0.493198,0.124796,0.050117,0.254420,-0.619839,-0.247054,-0.135811,0.282490,0.370571,-0.434710,0.313414,-0.577737,-0.232817,-0.764217,-0.346409,0.198938,-0.074090,-0.455790,0.664890,-0.726229,0.187008,-0.112742,0.372010,-0.715985,0.589847,0.078670,0.532271,-0.089452,0.264626,0.306574,-0.102594,-0.023565,0.637419,0.124725,-0.367987,0.177124,0.173366,0.520877', '1301022', '1296044', '26730542', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2209368', '新宿事件', '剧情', '20世纪90年代中国东北，铁头（成龙 饰）和女孩秀秀（徐静蕾 饰）两情相悦。不久，秀秀作为二战遗孤返回日本，从此杳无音讯。挂念秀秀的铁头偷渡来至日本，投靠同乡阿杰（吴彦祖 饰），与一众华人偷渡客过着提心吊胆的黑工日子。此时的秀秀已经更名结子，嫁给了日本黑帮三和会的若头江口利成（加藤雅也 饰）。亲眼见到这一幕的铁头心灰意冷，自此决心千方百计赚钱，留在日本。他们捞钱的手段很快触及到台南帮的利益，最终导致阿杰被斩断右手。铁头跟踪台南帮老大高捷（高捷 饰），意外得知一场黑社会的利益仇杀阴谋，他和一众朋友不可避免地卷入其中……©豆瓣', '成龙', '尔冬升', 7.6, 132074, 'tt1075419', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1309888084.jpg', 0.5, 3, 30.5, 48.6, 17.4, '0.081596,-0.005050,-0.487046,-0.024386,-0.034621,-0.207579,0.235213,0.226231,-0.524742,-0.196732,0.347610,0.664972,-0.003419,-0.039815,0.173240,-0.005671,-0.202333,-0.663495,0.137533,-0.117145,0.066847,-0.233139,-0.233739,-0.027602,-0.118800,-0.035017,0.443500,0.022425,-0.161513,0.957556,0.348867,0.425798,-0.325946,0.130586,-0.002758,0.203121,0.134729,-0.103142,-0.765808,-0.050890,-0.269724,-0.287897,-0.078639,0.045942,-0.042198,0.259117,0.651985,0.045009,0.114641,-0.258715,0.011712,-0.453490,-0.408693,-0.044277,0.515649,0.097256,0.246988,0.399935,-0.197466,-0.115693,0.044360,0.144684,-0.339210,0.036473,0.307128,0.226822,-0.487500,0.206614,-0.087455,0.006017,-0.023027,-0.331372,0.166108,0.497362,0.163743,0.189956,-0.223039,0.350144,-0.503349,0.353576,0.848184,-0.307263,0.280944,-0.132637,0.420237,-0.073500,0.075176,-0.297986,-0.173155,-0.019819,0.428178,-0.348156,-0.351417,0.298702,-0.635140,-0.046253,-0.350771,0.055692,0.214853,-0.113389,0.078653,-0.486281,-0.226487,-0.472333,-0.195272,0.064034,0.029651,0.016704,0.643619,-0.568815,0.032667,0.502737,0.458704,-0.592730,0.379705,0.320553,0.169654,-0.400893,-0.213137,0.085774,-0.057081,0.187540,0.017280,0.014525,-0.122788,-0.384488,-0.124826,-0.079342', '35256235', '3078390', '1451563', '3230460');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2209573', '贫民窟的百万富翁', '剧情', '2006年，印度孟买。印度青年杰玛•马利克（戴夫•帕特尔饰）还差一个问题就能赢得2千万卢比。他是怎么做到的？A：他作弊；B：他幸运；C：他是天才；D：一切命中注定。这是《谁想成为百万富翁》电视猜谜节目的人生版。杰玛•马利克在已经赢得1千万卢比的情况下被警方以欺诈罪逮捕，严刑拷问下杰玛说出他获得1千万卢比的真相——他确实知道答案，但他只知道这些！出身贫民窟的杰玛年幼就生活艰苦，他与哥哥沙里姆、少女拉媞卡(芙蕾达•平托饰)三人却一起经历了几十年印度的变迁。之前每一个问题，都好像是杰玛的记忆碎片，牵动他关于亲情、爱情与人生的回忆。而现在，杰玛一方面要洗清自己的犯罪嫌疑，一方面要拯救与拉媞卡的爱。在金钱与爱之前，杰玛能够沉着冷静，选择出正确的答案吗？©豆瓣', '戴夫·帕特尔', '丹尼·博伊尔', 8.6, 705856, 'tt1010048', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2434249040.jpg', 0.2, 0.7, 11.3, 44.8, 43, '-0.029876,0.225152,-0.432830,0.403512,-0.342304,-0.299021,0.625063,-0.391902,-0.303164,-0.109051,0.067777,0.677600,0.043972,0.108626,0.205556,0.326987,-0.293761,-0.774024,0.415380,-0.167846,-0.132141,-0.686013,-0.345698,-0.305466,-0.183885,-0.288729,0.400082,0.206484,-0.312769,-0.097968,0.224644,0.202266,0.060414,0.295240,-0.142760,-0.053133,-0.025659,0.040063,-0.351978,0.014366,0.112831,-0.133804,-0.272902,0.469844,0.061263,0.272545,0.228003,-0.141717,-0.219496,0.350712,0.208144,-0.425748,-0.055659,0.060579,0.030252,-0.335550,0.261595,0.411535,0.065827,-0.113278,0.009298,-0.040265,-0.960629,-0.364042,-0.078770,0.195189,-0.446060,0.286131,-0.311584,0.011738,0.028889,-0.060869,-0.023979,0.274637,0.511929,0.315113,-0.320592,-0.436648,-0.523839,0.329286,0.678217,-0.016181,-0.402215,0.410587,-0.341001,-0.620838,-0.088993,-0.330168,-0.451297,0.360941,0.092683,0.011893,-0.393288,0.382946,-0.249721,-0.016386,-0.338735,-0.111612,-0.053848,-0.540087,0.068988,-0.081661,-0.355529,-0.357278,-0.506995,0.002924,0.188189,-0.496810,0.763546,-0.629819,0.196577,0.628190,0.356319,-0.524562,0.478339,0.431857,-0.014307,-0.255882,0.086452,0.293341,0.092426,0.002669,-0.162359,0.012661,0.374831,-0.053994,-0.371356,0.679554', '30163500', '26678784', '25917239', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2209575', '少年时代', '剧情', '本片讲述一个男孩从6岁到18岁的成长历程，导演理查德·林克莱特花了12年时间来完成这部作品。它仔细描画了孩子的成长过程，及其父母亲各个方面的变化，可以让观众细致入微地体会岁月流逝的痕迹。为了不打扰主演艾拉·萨尔蒙的正常生活，拍摄均在他暑假期间的简短时间内完成。', '埃拉·科尔特兰', '理查德·林克莱特', 8.5, 210512, 'tt1065073', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187391526.jpg', 0.3, 1.2, 13.4, 41.9, 43.2, '-0.304813,0.084419,-0.490932,0.505121,-0.140388,-0.489578,0.372336,-0.224483,-0.527875,-0.318509,0.021178,-0.071606,-0.484038,0.343825,0.537785,-0.274832,-0.708081,-0.607916,-0.094672,-0.100826,-0.395343,-0.034958,-0.074203,-0.515418,-0.176611,-0.726697,0.512726,0.184158,0.109208,0.299834,-0.170606,-0.349619,0.229000,0.248000,0.113161,0.207009,0.126058,-0.056748,-0.202479,0.295966,0.233426,-0.278515,-0.286094,-0.104566,0.112775,0.434940,1.185173,0.124337,-0.208456,0.246618,0.653752,-0.132927,-0.062259,-0.319485,0.338105,0.194503,0.091219,0.253222,-0.160733,0.150956,-0.557868,-0.557558,-0.811339,-0.069806,0.163175,0.206624,-0.511392,0.471376,-0.280606,0.109196,-0.062857,-0.542962,-0.228501,0.464534,0.391098,0.402561,-0.195932,-0.059986,-0.117566,0.911676,0.487554,-0.136396,-0.650139,0.680175,-0.571108,-0.776718,-0.409298,-0.294252,-0.329133,0.243232,0.155771,0.215012,-0.202421,0.349158,-0.367573,-0.249398,-0.287717,-0.621632,0.094568,-0.495927,-0.039254,-0.724541,-0.345726,-0.478425,-0.192251,-0.397230,-0.073024,-0.786602,0.804044,-0.356037,0.209069,0.403038,0.025012,-0.133044,0.952650,-0.111496,0.152025,-0.366834,0.164642,0.459519,-0.209435,0.295383,0.072126,0.323261,0.041660,-0.045735,-0.663113,0.523850', '2027945', '3105588', '22265121', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2210143', '牛仔和外星人', '动作', '1873年的美国西部，杰克·洛根（丹尼尔·克雷格 Daniel Craig 饰）突然醒来，发现自己身处荒漠。自己为什么会在这儿，完全不记得了，身上仅有手腕上的一个神秘金属装置。为了找回失去的记忆，杰克回到了小镇上。但是他发现小镇上的居民对他却不怎么友好，而且想要在小镇上呆下去，必须得到伍德罗（哈里森·福特 Harrison Ford 饰）这位小镇开拓者的首肯才行。可是，最恐怖的事情却发生了，几艘诡异的外星飞船突然出现，并用劫掠走了小镇上的很多人。这时，杰克突然触动了手腕上的金属装置，将一艘外星飞船打了下来，并组建找回了部分记忆。为了救回被抓走的人们，查明这些不明外星飞船的意图。小镇上团结起来，在杰克和伍德罗的带领下，向着外星飞船飞走的方向，去寻找答案。©豆瓣', '丹尼尔·克雷格', '乔恩·费儒', 5.8, 19880, 'tt0409847', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1091708792.jpg', 4.8, 23.8, 53.8, 13.9, 3.8, '0.626519,0.334271,-0.844147,0.377536,0.072012,-0.201729,1.037330,-0.152003,-0.449610,-0.080136,0.139450,0.709161,0.054148,0.139959,0.197834,0.511414,-0.643957,-0.353362,0.012113,-0.246049,-0.874971,-0.525328,-0.519460,-0.147811,0.045839,-0.296926,0.543774,0.293067,-0.300586,0.394159,0.029946,0.360172,-0.001502,0.678454,-0.463227,0.057245,-0.045615,-0.218903,0.129931,0.177265,-0.255668,-0.398436,0.065697,0.196622,-0.058778,0.409241,0.637113,-0.217539,-0.183530,-0.128064,0.023284,-0.205561,0.172213,-0.098876,0.235563,0.134511,-0.159614,-0.065596,-0.282142,-0.156524,0.110555,-0.086956,-0.395919,0.091812,-0.191039,0.333371,-0.589803,0.077945,-0.236106,-0.069989,-0.088095,-0.535742,0.427127,0.326700,0.150432,0.104719,-0.298924,0.155617,-0.690539,-0.225594,0.651231,-0.020435,-0.240775,0.214984,0.019521,-0.451836,-0.249349,-0.103716,-0.139472,-0.167974,0.509686,0.193477,-0.331650,0.016497,-0.569060,0.208522,-0.336499,-0.607608,-0.106321,-0.319488,-0.286945,-0.609670,-0.123182,-0.191484,-0.345512,0.223420,-0.163120,-0.057691,0.605353,-0.801982,0.248175,0.707397,0.427800,-0.150497,0.535527,-0.242598,-0.022961,-0.211542,0.157769,0.238543,0.260959,0.552931,0.064561,0.286667,-0.076682,-0.134979,-0.480793,0.687955', '21619567', '3011051', '1309172', '1302133');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2210391', '哈维的最后机会', '剧情', '人过中年，居住在纽约的作曲家哈维·山恩（达斯汀·霍夫曼 Dustin Hoffman 饰）的人生却逐渐走下坡路。早年和妻子（Kathy Baker 饰）离婚，老婆带着女儿（Liane Balaban 饰）前往伦敦开始崭新的生活；一生辛苦打拼，却落得随时会被老板开除的下场 。在某个周末，哈维乘机赶往伦敦参加女儿的婚礼，却发现女儿的继父（James Brolin 饰）取代了自己的位置。更糟糕的事接踵而来，哈维错过了返程的飞机，也因此丢掉早已风雨飘摇的工作。徘徊流连于英国机场的哈维，无意中邂逅中年女子凯特·沃克（艾玛·汤姆森 Emma Thompson 饰）。凯特专于工作，情感道路颇为坎坷。两个天涯沦落人不期而遇，似乎一段崭新的故事就这样慢慢展开……©豆瓣', '达斯汀·霍夫曼', '乔尔·霍普金斯', 7.4, 7913, 'tt1046947', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p683799500.jpg', 0.4, 2.4, 37.3, 46, 13.8, '-0.144814,-0.189453,-0.591675,0.366245,-0.028799,-0.531034,0.609422,0.263467,-0.420449,-0.279907,0.310993,0.864136,-0.023642,0.368531,0.541256,0.014914,-0.349982,-0.620918,0.283674,-0.007241,-0.212311,-0.370755,-0.133935,-0.186564,0.055173,-0.129611,0.698445,0.144439,-0.024551,0.486135,0.204286,0.304456,-0.182440,0.441905,-0.390232,0.005199,0.190825,0.157587,-0.466056,0.026667,-0.027498,-0.128090,-0.039933,-0.187228,-0.021111,0.296548,0.718803,0.065698,-0.018165,-0.063106,0.415335,-0.106837,-0.054170,-0.008887,0.243108,-0.052356,0.125998,0.204223,-0.428274,-0.043607,0.174591,-0.134418,-0.210537,0.189648,0.015596,0.237692,-0.534595,0.469081,-0.180632,0.064845,0.217892,-0.315578,0.234735,0.329866,0.184095,0.266502,0.032609,0.078180,-0.307325,0.255921,0.515162,0.125670,-0.074070,0.362577,-0.141526,-0.069297,0.120130,-0.104266,-0.686559,-0.189360,0.300863,-0.129288,-0.020877,0.488583,-0.434969,0.014767,-0.210201,-0.147501,0.154105,-0.355074,-0.151349,-0.725085,0.106546,-0.285447,-0.294385,0.116398,0.004736,-0.027114,0.400489,-0.596384,0.270058,0.442881,0.078914,-0.517853,0.618870,0.108263,0.493612,-0.276139,-0.040464,0.597212,-0.237153,0.199578,-0.085395,0.206273,-0.219521,-0.044424,-0.371834,0.582525', '1303333', '4319218', '34795703', '1291992');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2212281', '性爱之后', '剧情', '这是一部清谈电影，由八个小故事组成，每个故事都是发生在欢愉之后的两人间的对话。一个年轻人向伴侣阐述他认为男女关系不平等的原因，却听到对方解释两人之间的关系并不是爱情；一对儿Gay的其中一人，突然对自己的身份产生了怀疑；一对儿小情人经历了初夜，男孩却被女孩的母亲堵在了屋里；两个Les走出房间，其中一个急于撇清自己和同性恋的关系；一对垂暮的嬉皮士夫妻，回忆起昔日种种的疯狂经历；两个渐入中年的Gay，在车上展开了一场关于同性恋人中“女性一方”身份的讨论；一对分手后的情侣，背着各自恋人再次聚到了一起，但是他们又一次爆发了争论；两个几乎陌生的人在欢愉之后试图彼此沟通，但是在身份和经历的差异下，他们的交流将指向何处……©豆瓣', '米拉·库尼斯', 'Eric Amadio', 6.8, 7063, 'tt0465375', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p917893966.jpg', 1.7, 9.1, 46.2, 35.1, 7.9, '0.809932,-0.097719,-0.728940,0.668775,0.005995,-0.237719,1.172512,-0.012254,-0.425135,-0.261102,0.168272,0.771987,-0.446213,0.276973,0.062244,-0.374601,-0.070707,-1.051818,-0.071671,-0.158654,-0.276273,-0.590784,-0.061194,-0.040981,-0.282563,-0.085948,0.507102,-0.246475,-0.297183,0.442751,0.683906,-0.069993,-0.594249,0.317886,-0.211910,0.005374,0.275324,0.488994,-0.557944,0.031022,-0.140563,0.014667,-0.095680,0.158487,-0.361254,0.402977,0.798167,-0.445536,-0.219009,0.132464,0.215919,0.029962,-0.220635,0.206770,0.474963,0.228899,0.450898,0.272058,-0.065253,-0.044582,-0.048310,0.191780,-0.643914,0.174272,0.141993,0.429681,-0.513976,0.593354,0.235568,-0.366070,0.172499,-0.107733,0.314463,0.555981,0.608480,0.640164,-0.177959,-0.165612,-0.454910,-0.189054,1.117473,0.167978,-0.222084,0.707230,-0.385476,-0.416852,-0.400330,0.213947,-0.423610,-0.030969,0.254088,0.024400,-0.277063,0.276141,-0.833344,0.100355,-0.091545,0.058350,0.058198,-0.753317,0.159876,-0.498981,-0.411313,-0.697477,-0.477066,0.148965,0.218519,-0.211274,0.882887,-0.737883,-0.058204,0.317358,0.275574,-0.629279,0.738945,0.364136,0.246550,-0.531650,0.233324,0.028006,0.125500,-0.206522,0.048508,0.518037,-0.310311,0.422797,-0.575626,0.328408', '30162520', '1296534', '1303036', '1307748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2212901', '平凡岁月的魅力', '剧情', '一个受教育的年青女子未婚怀孕，她父亲强行安排她和孤单的农夫结婚。故事背景是二战。原本没有感情的两个人，莫名其妙地结了婚，经历了很久，终于互信互爱！', '凯丽·拉塞尔', '布兰特·席尔兹', 8.5, 20446, 'tt0406046', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2453086907.jpg', 0.5, 0.9, 12.5, 44.2, 41.8, '0.411730,-0.420147,-0.681702,0.489499,-0.304358,-0.398900,0.864374,-0.245863,-0.594064,-0.678239,0.081185,0.765138,-0.111803,0.544887,0.018374,0.081875,-0.219879,-0.765995,0.128308,0.206792,-0.267622,-0.243001,0.107477,-0.119403,-0.276624,-0.390235,0.801391,0.005578,-0.041053,0.153471,0.079626,0.131622,0.065359,0.206645,-0.570858,0.310476,0.278511,0.232381,-0.305531,-0.252431,-0.201240,-0.160311,-0.206607,0.051832,-0.057114,0.472704,0.406977,0.304301,-0.415963,-0.011948,0.529087,-0.220472,-0.370357,0.174006,0.418729,0.017471,0.550551,0.462558,-0.076891,-0.324969,-0.025363,-0.355847,-0.332262,0.041015,0.053415,0.102608,-0.523632,0.765258,0.040255,-0.015233,-0.117474,-0.174584,-0.000294,0.432835,0.291930,0.714313,-0.109692,0.490141,-0.411933,0.260981,1.372797,0.208316,-0.564273,0.537773,-0.394343,-0.601175,0.142800,-0.387644,-0.686487,0.243261,0.323935,-0.226327,-0.611967,0.325770,-0.299432,0.266860,-0.133023,0.307647,0.104152,-0.398655,0.070251,-0.049543,-0.602947,-0.875650,-0.792573,0.088409,-0.182999,-0.154174,0.907449,-0.701365,0.237870,0.258086,0.403140,-1.110337,0.665954,0.826773,0.168457,-0.314716,0.528161,0.407059,-0.642681,-0.523651,0.062659,0.245712,-0.201183,0.481835,-0.300538,0.330019', '25721544', '4145476', '1301376', '1308804');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2213119', '不要回头', '剧情', '珍妮（苏菲•玛索 Sophie Marceau 饰）是居住在法国的一名美女作家，她和丈夫迪奥（Andrea Di Stefano 饰）共同经营一个幸福美满的四口之家。但是近一段时间，珍妮却感到令人难以承受的压力。客户的要求让她无法随心所欲写作，渐渐地珍妮发现周遭的一切开始发生变化，房间、丈夫、儿女甚至她自己的容貌都让人倍感陌生。珍妮的歇斯底里使家中的欢乐荡然无存，她和丈夫的婚姻也走到尽头。某天，珍妮的容貌也完全发生改变，变成了一个拥有一头黑发、大眼明眸的异域风情女子（莫妮卡•贝鲁奇 Monica Bellucci 饰）。她偶然在母亲的住所看到一张相片，于是启程前往意大利，寻找自己真正的本源归宿……©豆瓣', '苏菲·玛索', '玛丽娜·德·范', 6.3, 22816, 'tt1075113', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2269225097.jpg', 2.6, 14.8, 52, 24.3, 6.3, '0.254827,0.165307,-0.857548,0.687993,-0.225561,-0.304777,0.926745,0.297294,-0.489242,-0.294956,0.272739,0.946249,-0.160837,0.489869,0.347682,0.200279,-0.145036,-0.732134,0.047280,-0.117701,-0.261029,-0.224768,-0.148926,-0.117602,0.047549,-0.332754,0.677894,0.048759,-0.031749,0.473920,0.031457,0.061838,-0.028220,0.458111,-0.124167,-0.029832,0.000505,-0.010458,0.019802,0.174564,-0.064794,-0.050930,-0.231189,0.453861,-0.330558,0.300701,0.847163,-0.172345,-0.429112,-0.125584,0.483969,0.028611,0.011650,0.234774,-0.065419,-0.149670,0.076835,0.032668,-0.310451,-0.126704,0.203851,0.262122,-0.668506,0.222832,0.070215,0.213531,-0.407348,0.397454,-0.069038,-0.275298,0.141709,-0.585061,0.109430,0.276786,0.110305,0.464142,-0.321417,0.254205,-0.668109,0.055874,0.569420,0.196324,-0.340419,0.463447,-0.473220,-0.369415,-0.160080,-0.095897,-0.771472,-0.224893,0.196968,0.296964,-0.065302,0.082218,-0.618763,0.074750,-0.386129,-0.264928,-0.081028,-0.429112,-0.034321,-0.585926,-0.359878,-0.510737,-0.451340,0.029501,0.077926,-0.291851,0.834420,-0.560227,0.169549,0.633101,0.285924,-0.495619,0.691868,-0.031162,0.277853,-0.159473,-0.240154,0.526824,-0.083062,0.304035,-0.034638,0.244993,-0.226295,0.293082,-0.585812,0.611511', '30162520', '1291877', '3154392', '26884422');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2213591', '重返十七岁', '剧情', '17岁的迈克（扎克·埃夫隆 Zac Efron 饰）是校园风云人物，在一次关键性的篮球冠军赛上，他决定放弃前途，向怀有身孕的女友斯佳丽求婚。20年后，人到中年的迈克（马修·佩里Matthew Perry 饰）生活事业两失意，妻子斯佳丽（莱斯利·曼恩 Leslie Mann 饰）决定与迈克分居，一双儿女也对他形同路人，迈克只好搬入科技新贵的朋友奈德（托马斯·列侬 Thomas Lennon 饰）家暂住。迈克追忆自己本来可有的锦绣前程，却在重返高中校园过程中遇到一位神秘的清洁工，让他突然重返17岁。迈克决定与奈德假扮父子，重入高中，相信这是上天给他第二次机会让他做出正确决定，却发现自己的女儿玛吉（米歇尔·崔切伯格Michelle Trachtenberg 饰）与儿子亚历克斯（斯特林·克耐特Sterling Knight 饰）在学校问题重重……©豆瓣', '扎克·埃夫隆', '布尔·斯蒂尔斯', 7.4, 202703, 'tt0974661', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p477810397.jpg', 0.3, 3.1, 38.2, 45, 13.3, '-0.091205,-0.026733,-0.462435,0.307906,-0.100694,-0.675671,0.525532,0.160163,-0.542164,-0.297271,0.197076,0.856083,-0.119405,0.459799,0.526900,0.092761,-0.383363,-0.664005,0.346746,-0.159690,-0.020355,-0.652162,-0.274413,-0.127414,0.113340,-0.307930,0.490458,-0.114159,0.111539,0.542142,0.286589,0.278735,0.226321,0.090616,0.037089,0.103663,0.271974,0.138180,-0.617107,0.220637,-0.068625,0.067307,-0.317116,0.039412,0.229606,0.381837,0.468019,-0.104844,-0.090847,-0.016701,0.350122,-0.098091,-0.083588,0.190491,0.141652,-0.164008,0.123725,0.306342,0.031462,-0.139940,0.013143,-0.215705,-0.208158,0.156722,-0.022843,-0.020407,-0.566387,0.353834,-0.368055,-0.120034,0.080848,-0.538088,-0.198483,0.239461,0.275689,0.307205,-0.213346,0.233760,-0.268457,0.140656,0.447500,0.161384,-0.042906,0.151125,-0.146254,-0.357528,-0.050734,-0.184161,-0.613570,-0.014080,0.434877,-0.086021,0.065891,0.324130,-0.235153,-0.205989,-0.480547,-0.030249,0.243043,-0.295765,0.135266,-0.340175,0.056656,-0.200168,-0.462270,0.040115,0.018567,-0.289867,0.311006,-0.774791,0.388985,0.400019,0.190975,-0.314667,0.674587,0.140466,0.282998,-0.537508,-0.076538,0.437872,-0.104275,0.075776,-0.209358,0.204527,0.182630,-0.084750,-0.303045,0.424809', '1292720', '1297239',