INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2213597', '朗读者', '剧情', '15岁的少年米夏·伯格（大卫·克劳斯 David Kross 饰）偶遇36岁的中年神秘女列车售票员汉娜（凯特·温丝莱特 Kate Winslet 饰），后来两个发展出一段秘密的情人关系。汉娜最喜欢躺在米夏怀里听米夏为他读书，她总是沉浸在那朗朗的读书声中。年轻的米夏沉溺于这种关系不能自拔的同时，却发现他自己根本不了解汉娜。忽然有一天，这个神秘女人不告而别，米夏在短暂的迷惑和悲伤之后，开始了新的生活。二战虽然结束了，但德国对于纳粹战犯的审判还在继续。成为法律学校的实习生的米夏，在一次旁听对纳粹战犯的审判过程中，竟然发现一个熟悉的身影。虽然已经事隔8年，但米夏还是一眼便认出那就是消失8年的汉娜。而这一次，她坐上了纳粹战犯审判法庭的被告席，这个神秘女人的往事在案件的审理过程中逐渐清晰。然而，米夏却发现了一个汉娜宁愿搭上性命也要隐藏秘密。汉娜最终被判终身监禁，而此时米夏（拉尔夫·费因斯 Ralph Fiennes 饰）与汉娜的故事还在继续……在2009年初的第81届奥斯卡上，该片共获包括最佳女主角在内的5项提名，最终温丝莱特凭借该片折冠当年奥斯卡影后。', '凯特·温丝莱特', '史蒂芬·戴德利', 8.6, 433142, 'tt0976051', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1140984198.jpg', 0.1, 0.6, 11, 45.7, 42.6, '0.042282,0.178709,-0.770763,0.706745,-0.194139,-0.543390,0.866540,0.054876,-0.547320,-0.424476,-0.095787,0.479242,-0.490045,0.454107,0.534708,-0.018013,-0.207239,-0.936832,-0.324353,-0.211223,-0.448623,-0.612879,-0.097248,-0.478373,-0.196261,-0.167818,0.433337,0.283179,-0.183734,0.284822,0.549151,0.063166,-0.109482,0.637087,-0.183454,-0.102247,0.199241,-0.019364,-0.184274,0.330887,0.076518,-0.376384,-0.152739,-0.166622,0.057204,0.368373,0.724860,-0.328416,-0.315462,0.141452,0.547575,-0.284348,-0.276559,0.024355,0.449257,-0.181165,-0.017076,-0.155533,0.008362,-0.113375,0.175323,-0.214194,-0.431349,-0.214880,-0.257766,0.229352,-0.341572,0.455748,-0.085569,0.253469,0.116208,-0.175734,0.233098,0.394573,0.297010,0.267257,-0.368814,0.089073,-0.572312,0.273933,0.470652,0.333112,-0.249576,0.213845,-0.269093,-0.891635,-0.377103,0.039953,-0.413416,0.034007,0.381551,0.012753,-0.004284,0.294633,-0.352870,-0.320877,-0.125163,-0.143371,-0.043353,-0.486562,0.090503,-0.375662,-0.232087,-0.450064,-0.327695,0.250680,-0.080330,-0.524640,0.528288,-0.604470,0.662717,0.421572,0.361310,0.115774,0.700118,0.218760,0.205354,-0.077572,-0.221855,0.595225,0.106074,0.043777,0.074919,0.559893,-0.019380,-0.098648,-0.432332,0.504483', '21348112', '1292211', '1309297', '35073565');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2214140', '合约情人', '喜剧', '霍启发（任贤齐饰）事业有成，收入不菲，却为女朋友一事而苦恼。他女友Rachel（徐子珊饰）甚为西化，着装开放暴露，正是见家长的大忌。父母催婚，为了让他们接受Rachel ，霍启发决定征选合约情人，带回老家。刘枣（范冰冰饰）是待业大学生，家境贫寒，应征成功令她开始了合约情人的身份。霍启发带她来到佛山老家，让她做尽令老人家失望之事。但刘枣和霍家关系竟越来越好，事情竟然往料想不到的方向发展。霍启发、Rachel和刘枣三人之间如何纠结？刘枣这个情人到底有多长的合约？©豆瓣', '任贤齐', '张坚庭', 5.4, 57903, 'tt1086704', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2193019047.jpg', 7.9, 28.6, 51.3, 9.7, 2.4, '-0.139704,-0.100924,-0.499838,0.508346,-0.188643,-0.362822,0.383796,0.212547,-0.393126,-0.492308,-0.294031,0.310981,-0.166132,0.167725,0.214809,-0.251328,-0.089507,-0.635481,0.229143,-0.229943,-0.192849,-0.409317,0.139361,-0.431640,-0.104142,0.035851,0.427878,0.207058,-0.401812,0.226649,0.653030,0.280267,-0.295741,0.403615,-0.059864,-0.013758,0.050250,0.687167,-0.400021,-0.043331,0.277529,-0.194083,-0.107498,0.184366,0.240757,0.496099,0.309500,0.208109,-0.627791,-0.059196,0.258598,0.021130,0.104722,0.135345,0.198518,0.121111,0.248530,-0.226571,-0.189862,-0.010950,0.037895,-0.102052,-0.105966,0.135933,0.375350,-0.079604,-0.626630,0.029161,-0.154461,0.003307,-0.122615,-0.341270,0.104276,0.453891,0.302169,0.236381,-0.075796,0.275119,-0.413417,0.354317,0.506625,0.148281,0.292788,0.096201,-0.407440,-0.450662,0.128385,0.269767,-0.355788,0.101714,0.152462,-0.057090,0.293918,0.181513,-0.328142,-0.365609,-0.149831,0.144010,-0.105449,-0.717763,0.398127,-0.267821,-0.241197,-0.318220,-0.062929,0.062781,0.203967,-0.360798,0.490305,-0.525284,0.123280,0.073129,0.437441,-1.114045,0.468110,0.286783,0.065963,-0.636026,-0.069215,0.020110,-0.089156,-0.188307,0.102686,-0.151445,0.240090,-0.302791,-0.142458,0.348029', '1421278', '1302110', '1484760', '4258485');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2215609', '歌舞青春3：毕业季', '剧情', '三年的时间匆匆一过，经历了风风雨雨的特洛伊（扎克·埃夫隆 Zac Efron饰）和女友盖比瑞拉（瓦妮莎·哈金斯 Vanessa Hudgens饰）即将迎来毕业，面临着各奔东西的局面。虽然两人非常希望能够继续在一间大学就读，延续彼此的感情，可惜无论是家人还是自己的志向，让两人产生分歧颇大，免不了争吵。但两人还是决定和野猫队的其他同伴们一起举办一场音乐剧，以此来怀念那些高中的美好时光，并憧憬美好的未来。盖比瑞拉接到的斯坦福大学的荣誉课程通知书，课程的日子正好与毕业舞会的日期相冲突，面对选择，她不知道自己到底该何去何从。特洛伊知道后，虽不愿分离却仍然劝说盖比瑞拉不要放弃这个机会，不要埋没自己的人生。最终盖比瑞拉最终决定离开，而且也没有在毕业舞会的前夕赶回来……最后，特洛伊和盖比瑞拉的爱情是否能修成正果？©豆瓣', '扎克·埃夫隆', '肯尼·奥特加', 7.4, 70675, 'tt0962726', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p585329608.jpg', 0.7, 4.1, 37.3, 39.6, 18.2, '0.086311,-0.174117,-0.687819,0.581302,0.102365,-0.462409,0.755765,0.006562,-0.326700,-0.419021,0.046918,0.733332,-0.282931,0.405870,0.301713,-0.374288,-0.554779,-0.845064,0.662848,-0.326169,-0.346634,-0.331405,-0.238574,0.320357,-0.181440,-0.119053,1.086417,-0.116480,0.165561,0.633695,0.257756,0.068206,0.105848,0.436271,-0.155408,-0.239419,-0.069915,0.550319,-0.679750,-0.009996,0.288962,0.033152,-0.396321,-0.016158,0.345487,0.208878,0.422991,-0.154209,-0.107010,0.010426,0.191676,-0.237187,-0.096833,0.406241,0.368750,0.080539,0.109396,0.501179,-0.126253,0.120125,0.002491,-0.265275,-0.675396,0.205220,0.277837,0.034489,-0.726697,0.832674,0.100542,0.157427,0.054208,-0.126404,-0.079761,0.742112,0.363354,0.514377,-0.178964,-0.014825,-0.393766,0.069042,0.764669,-0.125263,-0.137337,0.580362,0.001838,-0.354483,0.002838,-0.205551,-0.698816,0.228568,-0.021113,0.251837,-0.255682,0.287083,-0.551392,-0.286357,-0.391895,-0.379061,0.237885,-0.591023,0.056072,-0.398454,-0.053471,-0.576254,-0.404678,0.023437,-0.005866,-0.395567,0.784015,-1.097355,-0.117331,0.241773,0.528996,-0.585633,0.598219,0.613930,0.487231,-0.122907,-0.028366,0.274082,-0.401200,0.197443,0.144967,0.243359,0.216514,-0.131914,-0.526393,0.643092', '35030151', '30345227', '1826173', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2215964', '法内情', '剧情', '刘志鹏（刘德华 饰）是一位在孤儿院长大的青年律师，曾为一位被控谋杀的妓女刘惠兰（叶德娴 饰）打赢官司，但他始终不知她原来是自己的母亲。她仍操皮肉生涯，平日被杂差收黑钱敲诈，生活相当悲苦，不幸律师儿子的出世纸又落入坏蛋杂差手中，勒索叶巨款，迫得她到麻雀馆赌博出千，被捉毒打，走投无路之下，结果杀死了杂差， 被捕候审。孤儿院修女玛利亚知悉此事，找刘再次为母亲辩护。', '刘德华', '黄泰来', 7.6, 5276, 'tt0095124', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2347444843.jpg', 1, 2.2, 31.7, 48.1, 17, '-0.095365,-0.050306,-0.099861,0.182658,-0.412771,-0.349919,0.763776,0.147467,-0.203229,-0.337081,0.397944,0.499331,-0.064603,0.424968,0.222551,0.039143,0.306483,-0.468344,0.048267,0.100331,0.005902,-0.344389,-0.173209,-0.190216,-0.120409,0.067708,0.367788,0.107852,-0.060980,-0.023132,0.508620,0.426380,-0.061730,0.123594,-0.308752,0.159574,-0.051290,0.141077,0.012819,-0.010308,0.009451,-0.617054,-0.127553,-0.141618,0.082689,0.437804,0.534367,0.191138,0.031378,-0.270413,0.505277,-0.267836,-0.053682,0.200062,0.225210,-0.110815,-0.032658,0.017612,-0.162549,-0.284786,0.326348,-0.168566,-0.297522,0.079080,0.177981,-0.268331,-0.638546,-0.168573,-0.346847,0.574227,-0.301283,0.012167,0.122358,-0.027055,0.022746,0.354680,-0.043651,0.094610,-0.686921,0.644792,0.462649,-0.271544,0.316799,-0.089265,-0.074599,-0.501101,0.400864,-0.570735,-0.350102,0.071879,0.420462,-0.299758,-0.291581,-0.016607,-0.160497,-0.518390,-0.337671,0.174972,-0.016182,-0.420684,-0.159319,-0.119557,-0.144629,-0.004814,-0.487582,0.020563,0.103049,-0.178422,0.382956,-0.509499,0.217443,0.470378,-0.163390,-0.656502,0.510978,0.257636,-0.076573,-0.094336,-0.113966,0.270584,0.585756,0.102198,0.360735,-0.213711,0.029891,-0.124612,0.026036,0.250281', '1304021', '1305201', '3998385', '1293908');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2216966', '爱你长久', '剧情', '朱丽叶特（Kristin Scott Thomas 饰）亲手杀死了自己只有6岁的儿子，她被判入狱15年，期间丈夫与之离婚，父母和她断绝关系，只有小妹妹莉偷偷思念着疼爱自己的姐姐。15年后，朱丽叶特出狱，暂住莉（Elsa Zylberstein 饰）的家中。因其犯罪背景，朱丽叶特在求职过程中处处碰壁，妹夫卢克（Serge Hazanavicius 饰）也对她心存芥蒂。随着时间推移，冰冷自闭的朱丽叶特逐渐和妹妹一家人相处融洽，工作步入正轨，也有了心仪之人。这时，莉却无意中得知了姐姐亲手杀死孩子的真相……本片荣获2009英国学院奖最佳非英语片奖、2008柏林国际电影节天主教人道精神奖、2008欧洲电影节最佳女主角奖。©豆瓣', '克里斯汀·斯科特·托马斯', '菲利浦·克洛代尔', 8.2, 15856, 'tt1068649', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p459545990.jpg', 0.2, 1.4, 16.9, 53, 28.4, '-0.192709,-0.125804,-0.741882,0.464177,0.234507,-0.408885,0.617067,0.041111,-0.549093,-0.235273,0.029574,0.864149,-0.243612,0.479188,0.454684,0.135489,-0.356765,-0.911756,-0.001529,-0.216366,-0.202088,-0.494631,-0.083019,-0.035582,-0.352277,-0.489844,0.441087,-0.243412,0.250458,0.458905,0.346397,0.432180,-0.159055,0.354995,0.038500,0.183587,0.251202,-0.133905,-0.539883,0.184318,0.250682,-0.335863,-0.077816,0.055148,0.039682,0.395463,0.872665,-0.066186,0.073679,-0.387319,0.577649,-0.446204,-0.207224,0.013050,0.412696,-0.324868,0.396082,0.313167,-0.156364,-0.243241,-0.124361,-0.354490,-0.148209,-0.041874,0.319088,-0.051565,-0.488180,0.273858,-0.045180,0.324153,0.108351,-0.101539,0.377508,0.326532,-0.093186,0.283627,-0.152469,0.112672,-0.342795,0.517129,0.440159,0.033467,0.054971,0.246659,-0.292916,-0.459819,0.372393,-0.649420,-0.600267,0.148170,0.344801,-0.002546,0.180517,0.273454,-0.279837,-0.437931,-0.211882,0.237917,0.185132,-0.583278,0.306764,-0.262642,-0.091537,-0.514428,-0.447813,-0.095055,-0.086998,-0.328025,0.536880,-0.743205,0.398665,0.626662,0.540978,-0.362076,0.726918,0.064117,0.176784,-0.317946,-0.259772,0.272067,-0.177919,-0.264555,-0.024657,0.099971,0.464737,-0.116128,-0.337365,0.427823', '3155839', '1292207', '1307146', '30140107');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22203896', '洛克', '剧情', '伊万·洛克一直努力着为自己创造一个更好的生活，但今晚，他的生活将彻底土崩瓦解。在他职业生涯中最大的挑战前夕，伊万收到电话，将影响关于他的一系列事件，将击溃他的家庭、工作和灵魂。《洛克》这部影片，将是一次独特的影象体验，真实地将观众置于副驾驶座，来观看驾驶者的人生层层展开……', '汤姆·哈迪', '斯蒂文·奈特', 7.7, 11531, 'tt2692904', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2193307872.jpg', 1, 3.3, 26.8, 46.1, 22.8, '0.080672,0.318021,-0.466746,1.122696,-0.470356,0.065462,0.774743,0.119976,-0.590302,0.056923,0.188043,0.994814,-0.146316,0.161029,0.410083,0.055628,-0.280221,-1.117656,-0.286500,0.353728,-0.120040,-0.534285,-0.463762,-0.161283,-0.087431,-0.462823,0.826991,0.101415,-0.430085,0.209898,0.083846,0.308147,0.119094,0.581045,-0.074242,0.030806,-0.259009,-0.272426,-0.308756,0.371758,0.409422,-0.598200,-0.116328,0.625592,-0.047678,-0.002900,1.021428,-0.460263,-0.365036,0.111076,0.808811,-0.559303,-0.101696,0.160740,0.038557,0.573916,-0.172517,0.382536,-0.510927,0.185766,0.232729,-0.194435,-1.174436,-0.303980,-0.254347,-0.065049,-0.735149,0.493980,-0.241653,-0.137072,0.241223,-0.180136,0.323484,0.670209,0.536727,0.224351,-0.468194,0.060064,-0.374188,0.335360,0.764904,-0.263697,-0.147843,0.308904,-0.288772,-0.324283,-0.355337,-0.222136,-0.534432,-0.112640,0.442266,0.274842,-0.271849,0.294739,-0.659974,-0.032335,-0.537899,-0.912411,-0.238448,-0.763968,-0.187362,-0.767275,-0.362457,-0.116350,-0.271533,-0.440486,-0.107312,-0.660100,0.828587,-0.819900,0.261434,0.659416,0.268724,-0.159284,0.785895,-0.001488,0.429503,-0.180769,0.013582,0.320050,0.169542,0.539531,0.093518,0.532179,0.051362,0.288093,-0.488929,1.157539', '27666513', '1308815', '24733428', '1303263');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2222995', '硬汉', '喜剧', '老三（刘烨 饰）本来是个大有前途的海军军人，可是在一次救人中意外的损毁了脑神经，不得不提早退役。退役后的老三始终生活在自娱自乐的军人生活中，更是以见义勇为，消灭一切邪恶力量为己任。多年的军旅生活和坚持不懈的锻炼，让老三在与小偷、票贩子、犯罪团伙的一次次搏斗中战无不胜。另一方面，香港黑帮大哥阿龙（黄秋生 饰）带着妻子和手下悄悄的来到了老三所在的城市，他们的目标是即将在此展出的宋代文物——岳家抢。刑警队长老蒋（尤勇 饰）的暗中已经盯上了这股黑帮势力，却不想老三以十足的正义感和不大高明的头脑横搅入局。一场硬碰硬的三方对决在正义与邪恶之间拉开帷幕。©豆瓣', '刘烨', '丁晟', 6.2, 55120, 'tt1087906', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1117466357.jpg', 3.6, 14.8, 54.5, 21.9, 5.1, '0.244669,-0.173874,-0.607772,0.649315,-0.262594,-0.284227,0.637598,0.047661,-0.786255,-0.162626,0.281548,0.610321,0.116217,0.051406,0.241155,-0.278806,-0.039040,-0.742513,-0.365755,0.125611,-0.189249,-0.381449,-0.421906,-0.115599,-0.181406,-0.088017,0.776309,0.005646,-0.293415,0.600192,0.364997,0.332757,-0.207463,0.334141,-0.253942,-0.150736,0.057795,-0.159688,-0.563831,0.117799,0.202487,-0.370916,-0.207235,0.124110,0.025360,0.317579,0.510103,-0.235102,0.053927,-0.085817,0.141623,-0.459963,-0.355528,0.027504,0.487003,-0.033818,0.341781,0.265854,-0.006301,-0.061907,0.031960,-0.085231,-0.782070,-0.179400,0.319874,0.010001,-0.647701,0.632038,0.167217,0.001166,0.071281,-0.199572,0.232720,0.436533,0.158805,0.321719,-0.113666,0.020027,-0.478769,0.117492,0.798629,-0.074919,-0.135161,0.009396,0.026216,-0.138911,-0.080354,-0.432894,-0.478529,-0.283477,0.360576,-0.181797,-0.039283,0.365696,-0.775302,0.111546,-0.087047,0.073983,0.025584,-0.411441,0.070776,-0.471117,-0.337416,-0.616185,-0.092798,0.398709,0.209465,-0.084629,0.669632,-1.047061,-0.068288,0.380834,0.143021,-0.502791,0.467988,0.162117,0.170640,-0.226094,-0.096193,-0.164584,0.114409,0.407435,0.208820,0.430541,-0.065540,-0.272888,-0.193025,0.481818', '35030151', '1301022', '30345227', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2222996', '步履不停', '剧情', '“人生路上步履不停，为何总是慢一拍”。位于偏远小镇的横山一家，生活平静祥和。父亲恭平（原田芳雄 饰）是业已退休的医生，却时时牵挂小镇诊所内的事务。长子纯平继承了父亲的事业，却在15年前为救落水儿童而溺水身亡。次子良多（阿部宽 饰）与父亲意见相左，执意前往异地当起了绘画修复师。多年的打拼换来的却是失业，困顿的良多与带着孩子的由香里（夏川结衣 饰）结婚，相互扶持，继续生活。又逢纯平的忌日，良多和姐姐千奈美（YOU 饰）带着家人分别赶回家中。平静的横山家再次热闹起来……本片荣获2009年蓝丝带最佳导演奖和最佳女配角奖（树木希林）、2008年报知电影和2009年电影旬报最佳女配角（树木希林）、2009年每日电影奖最佳男主角（阿部宽）、2008年马塔布拉塔国际电影节评审团大奖和最佳影片。©豆瓣', '阿部宽', '是枝裕和', 8.8, 259353, 'tt1087578', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2375245718.jpg', 0.2, 0.6, 8, 40.5, 50.8, '-0.548297,-0.153372,-0.358545,0.454788,0.235838,-0.423812,0.366588,0.398283,-0.591408,-0.366802,0.088857,0.805876,-0.057586,0.362909,0.398152,-0.040622,-0.359683,-0.580053,-0.031199,0.010078,0.061706,-0.345669,-0.029513,-0.035643,-0.222424,-0.386575,0.698266,0.091872,0.274839,0.825162,0.231320,0.144029,-0.341898,-0.030997,-0.068446,0.115356,0.028822,0.244529,-0.616350,0.257312,-0.050765,-0.393140,-0.427513,-0.308812,0.448627,0.291479,0.729688,0.133567,-0.046157,0.005071,0.445662,-0.241722,-0.217868,-0.055161,0.332664,-0.055377,0.350080,0.348303,-0.246475,-0.037358,-0.086131,-0.380355,-0.301305,0.078652,0.318961,0.049446,-0.612348,0.508432,-0.022923,0.012650,0.043406,-0.252063,0.106039,0.319336,0.147793,0.421031,-0.357770,0.149759,-0.204357,0.476672,0.461876,-0.033400,0.029458,0.136580,-0.191462,-0.435206,0.006096,-0.367205,-0.583264,0.085791,0.138941,0.058556,0.078729,0.224061,-0.293060,0.000261,-0.066976,-0.249275,0.425143,-0.117722,0.038674,-0.635112,0.268907,-0.392392,-0.204700,0.004665,0.109394,-0.105389,0.710995,-0.498195,0.364543,0.334506,0.230729,-0.465832,0.681117,0.022335,0.206429,-0.322358,0.014866,0.200756,-0.305092,0.184384,0.102549,-0.063437,-0.277287,-0.134270,-0.443237,0.161589', '1780122', '3811356', '26365262', '6814906');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2223596', '特种部队：眼镜蛇的崛起', '动作', '近未来，武器研发集团MARS的创始人詹姆斯•麦库伦（Christopher Eccleston 饰）发明了名为“纳罗脉”的微型机器人，该机器人可以在很短时间内吞噬掉挡路的敌人，威力巨大。北大西洋公约组织（NATO）武器研究所对此颇感兴趣，向MARS集团购买了四颗纳罗脉弹头。运送途中，护卫队遭到一伙高科技武装分子的袭击。在弹头即将被抢去之际，另一组神秘人马阻止了武装分子的计划，并解救了护卫队仅剩的两名成员公爵（钱宁•塔图姆Channing Tatum 饰）和开伞索（Marlon Wayans 饰）。解救公爵的正是霍克将军（丹尼斯•奎德Dennis Quaid 饰）所统率的特种部队，公爵和开伞索请求加入该部队，以血前耻。另一方面，阴谋夺取弹头的幕后黑手正是麦库伦，他企图从NATO榨取巨额资金以支持他的研究，继而实现称霸世界的野心。一场正邪较量就此展开……', '查宁·塔图姆', '斯蒂芬·索莫斯', 7.3, 167986, 'tt1046173', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2243490128.jpg', 0.9, 4.7, 35.8, 44, 14.6, '-0.098635,0.096383,-0.386888,0.390372,0.081722,0.069852,0.275665,0.075329,-0.059694,-0.224892,0.328616,0.323235,0.397633,-0.347688,0.203451,-0.172198,-0.094104,-0.414848,-0.158803,-0.091510,-0.305699,-0.467282,-0.348481,-0.506599,0.273997,-0.598670,0.789665,0.210759,-0.420593,0.130817,0.368664,0.686999,-0.210796,0.375012,0.226976,-0.387794,0.486416,-0.414645,-0.335285,0.297720,-0.386175,-0.376261,0.264837,0.188547,0.005717,0.324318,0.564478,-0.434983,0.415423,-0.245937,-0.081675,-0.211910,0.131439,-0.146793,0.447445,0.295543,-0.288244,0.153510,-0.109575,-0.065036,0.247155,-0.103207,-0.954825,-0.425872,0.108772,-0.189596,-0.780100,0.271949,-0.425614,0.274797,0.229726,-0.025416,0.172785,0.643404,0.209106,-0.014331,-0.148538,0.078521,-0.817504,0.105223,0.571670,-0.375868,-0.131532,-0.041227,0.075684,-0.372602,-0.198387,-0.253194,-0.071262,-0.259734,0.591106,-0.083024,0.366671,0.369551,-0.758189,-0.035968,-0.466693,-0.068110,0.369887,-0.258723,0.245645,-0.775276,0.070382,0.049236,0.044746,0.302133,0.063458,0.073228,0.571026,-0.588354,-0.103686,0.575724,0.388197,-0.463533,0.309302,-0.163479,0.135222,-0.344766,-0.249210,-0.159609,0.389712,0.407924,0.210781,0.220573,0.372556,-0.546077,0.041261,-0.044276', '27009869'