INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2225175', '车库惊魂', '惊悚', '圣诞前夜，虽然家人热切地期盼，但美丽干练的女律师安吉拉（瑞秋·尼科尔斯Rachel Nichols 饰）仍在办公室努力工作，进行最后的冲刺。繁冗的工作终至尾声，安吉拉独自下到地下车库，准备驱车回家。不过她的车无论如何也发动不了，车库电梯门也被锁住，于是她只好向保安托马斯（韦斯·本特利 Wes Bentley 饰）求助。托马斯友善恭敬，热情施以援手，却不知其心中藏着怎样的黑暗念头。写字楼大门紧锁，致使准备乘计程车回家的安吉拉在此返回保安室求助托马斯。时机业已成熟，托马斯露出狰狞面目，他绑架了安吉拉，强迫她参加自己的圣诞晚宴。这个爱慕安吉拉的小男人，给安吉拉带来一个宛如噩梦般的圣诞节……©豆瓣', '瑞秋·尼科尔斯', 'Franck Khalfoun', 6.1, 7847, 'tt0804516', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1194355907.jpg', 2.9, 15.9, 57.4, 18.5, 5.3, '0.212253,0.376223,-0.708251,0.264391,-0.137592,-0.365626,0.756010,0.369998,-0.023818,-0.156981,0.507592,0.438129,-0.022797,0.347731,0.397751,0.186231,-0.634847,-0.451848,-0.082558,0.095214,-0.150354,-0.128085,-0.025320,-0.126689,0.163197,0.180961,0.288476,0.004387,0.226069,0.581606,0.314203,0.102095,0.016836,0.629725,0.059112,0.031152,0.107089,-0.376386,-0.253255,0.075488,0.168170,-0.278802,-0.449861,0.167607,0.197542,0.424346,0.636951,0.176647,-0.121091,0.102519,0.184067,-0.126432,0.138189,0.191203,0.188368,0.312598,-0.127277,-0.071851,-0.102089,-0.003188,0.077259,-0.026881,-0.319055,0.360096,-0.317128,-0.060532,-0.519480,0.245149,-0.374788,0.209397,0.181655,-0.580728,-0.179871,-0.031121,0.031701,0.063886,-0.193712,0.238499,-0.344199,0.059082,0.260275,0.194135,-0.054811,0.231941,-0.249109,-0.282032,0.253188,0.039302,-0.744397,-0.286998,0.594194,0.270216,-0.229252,-0.010867,-0.299439,-0.284687,-0.448256,-0.223097,-0.037641,-0.404045,-0.047120,-0.894867,0.176979,-0.012043,-0.278796,-0.019375,-0.007255,0.218577,0.369140,-0.562693,0.309900,0.551730,0.347393,-0.175919,0.711091,-0.093567,0.215599,0.028512,-0.084896,0.383027,-0.141007,0.678527,0.038356,0.465443,-0.071851,0.067122,-0.520519,0.440938', '1309110', '10466639', '3735015', '2159244');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2225321', '地球停转之日', '剧情', '某晚，供职于普林斯顿大学的太空微生物学教授海伦•本森（Jennifer Connelly 饰）被警察和几名神秘人物带走，与她一同前往新泽西林伍德军校的还有业界内无数顶尖科学家。原来，NASA在探测外太空时发现有一不明物体正飞速接近地球。不久，一个闪耀着白色光芒的物体莅临曼哈顿上空，并降落在纽约公园中央，百姓、科学家和军方将其团团围住。稍顷，一个与人类身形极其相似的外星人（基努•里维斯 Keanu Reeves 饰）以及身材高大的机器人出现在人类面前。粗鲁的人类完全浪费掉外星来客的友善，而等待人类的又将是怎样的命运？本片翻拍自1951年同名科幻影片，并荣获2009年美国科幻与恐怖电影学院奖最佳青年演员奖（Jaden Smith）。©豆瓣', '基努·里维斯', '斯科特·德瑞克森', 5.8, 48109, 'tt0970416', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2162954650.jpg', 5.2, 24.2, 50.8, 15.5, 4.4, '0.302799,-0.033658,-0.691807,0.652895,0.181062,0.061739,0.828887,-0.134793,-0.487759,-0.376489,0.228571,1.012410,-0.297233,0.074889,0.309178,0.004281,-0.293809,-0.692845,-0.461082,-0.266413,-0.431698,-0.465070,-0.586358,-0.148029,0.055211,-0.462029,0.732987,-0.025847,-0.070375,0.592952,0.261429,0.355359,-0.510272,0.313166,-0.209048,-0.318412,0.190048,-0.061305,-0.285582,0.229079,-0.270502,-0.321182,0.141886,-0.183600,-0.329630,0.031372,0.784152,-0.374319,0.037729,-0.259677,0.388657,-0.310293,-0.161287,-0.060384,0.420800,-0.080177,-0.071657,0.041955,0.142903,0.233472,0.162026,-0.209230,-0.483355,-0.046359,-0.063742,0.308438,-0.302430,0.316080,0.142267,-0.051450,0.027692,-0.200334,0.146128,0.028223,0.172221,0.288923,-0.005792,0.061688,-0.285065,0.270438,0.274643,0.269522,-0.542822,0.090402,-0.184756,-0.667069,-0.175631,-0.114640,-0.348545,-0.049870,0.258228,0.126315,0.007687,0.375086,-0.738517,0.251855,-0.226336,-0.256867,0.010465,-0.181878,-0.253891,-0.899659,0.063622,-0.328895,-0.284758,0.157816,-0.000985,0.071510,0.737871,-0.645672,0.331850,0.446750,0.315903,-0.159852,0.804635,-0.380484,0.058285,-0.239920,-0.436485,0.170958,0.408349,0.420670,-0.279402,0.281662,-0.262165,-0.150141,-0.238962,0.141772', '1293433', '1780122', '3811356', '1309194');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2225784', '末日病毒', '剧情', '一种高致命性和传染性的病毒在世界上蔓延开来，为了避难，丹尼（卢·泰勒·普奇 Lou Taylor Pucci 饰）和哥哥布莱恩（克里斯·派恩 Chris Pine 饰），女友波比（派珀·佩拉博 Piper Perabo 饰）还有好友凯特（艾米丽·万凯普 Emily VanCamp 饰），驾车以最快的速度穿越美国西南部的沙漠地带。他们希望寻找的是一个相对安全的地方，可是花掉了整整几天的时间，他们却意识到，也许偌大的国家再也没有可供他们容身的地方了。不仅是病毒的肆虐压迫着每个人的神经，他们还不断地被迫去面对道德伦理方面的决定和挑战制造出来的压力--都是一些他们以前无法想象出来的艰难与人性抉择。很快，他们就发现，原来阻挡在他们面前的最大的敌人，并不是不断袭击并打垮人类的致命细菌或病毒，而是隐藏在他们内心深处的黑暗与邪恶......©豆瓣', '卢·泰勒·普奇', '亚历克斯·帕斯特尔', 6.3, 14195, 'tt0806203', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1505236282.jpg', 3.2, 13.2, 55.2, 22.5, 5.9, '0.227027,-0.016637,-0.664721,0.718507,-0.087203,0.046411,0.819550,0.081838,-0.424752,-0.294608,-0.012119,0.570890,-0.035221,-0.136999,-0.096510,-0.059732,-0.273188,-0.621002,-0.064057,-0.096156,-0.559553,-0.453013,-0.540771,-0.441496,0.055252,-0.299494,0.507162,0.301362,-0.362262,0.394028,0.077590,0.295585,-0.166609,0.705901,-0.174460,-0.153216,-0.162085,-0.132008,-0.363998,0.229466,0.098356,-0.189834,-0.067550,0.423627,0.063754,0.289987,0.569080,-0.369191,-0.110914,0.031574,0.107159,-0.408195,0.104044,-0.037789,0.239784,-0.492220,0.320169,0.147688,0.102013,0.156653,0.185998,0.084994,-1.056899,-0.038275,0.087380,0.170770,-0.384872,0.422446,0.030546,-0.202635,0.065739,-0.356980,0.042691,0.187191,-0.035759,0.306599,-0.532785,-0.229143,-0.657085,-0.115333,0.628839,-0.155308,-0.436473,0.159972,-0.404374,-0.430426,-0.313688,-0.257444,-0.304699,-0.112318,0.235155,0.480269,-0.325333,0.232886,-0.734018,0.188628,-0.182575,-0.360964,-0.045157,-0.439322,0.172210,-0.786679,-0.032031,-0.473367,-0.175391,0.220401,0.050117,-0.252361,0.586253,-0.623886,0.230350,0.851463,0.470305,-0.623475,0.524313,-0.055897,0.031500,-0.044362,-0.258846,0.294413,0.117543,0.428671,0.121280,0.296208,0.082897,0.084423,-0.162701,0.715685', '1308784', '4820775', '3769423', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22263645', '猜火车2', '剧情', '一晃眼二十年过去。远赴他乡的雷登（伊万·麦克格雷格 Ewan McGregor 饰）再度踏上了爱丁堡的故土。哪知道刚一回来，就撞上了走投无路陷入绝望之中的屎霸（艾文·布莱纳 Ewen Bremner 饰）试图自杀，原来，屎霸不仅婚姻失败还再度染上了毒瘾。在雷登的鼓励下，屎霸决定用书写来治愈内心的伤痕。之后，雷登找到了曾经的挚友病孩（约翰·李·米勒 Jonny Lee Miller 饰），病孩因为曾经的龃龉痛揍了雷登，之后，一个复仇的计划在他心中慢慢成型。在病孩的邀请下，雷登决定和病孩合伙开一家妓院，之后，擅长设计的屎霸亦加入了进来。那边厢，锒铛入狱的贝格比（罗伯特·卡莱尔 Robert Carlyle 饰）越狱成功，在了解了当年事件的真相后，他亦决定找到雷顿向他寻仇。©豆瓣', '伊万·麦克格雷格', '丹尼·博伊尔', 8, 79418, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2416239096.jpg', 0.6, 2.4, 21.8, 46.5, 28.8, '0.249333,0.274481,-0.669153,0.357533,0.191546,-0.756435,0.500979,0.083808,-0.078012,-0.144920,0.005209,0.565447,-0.116710,0.210346,0.402210,0.015969,-0.459304,-0.675180,-0.013950,-0.331856,-0.478197,-0.392469,-0.321755,-0.013229,-0.043592,-0.135209,0.334112,0.211828,-0.030433,0.457985,0.510633,0.426151,0.119422,0.263677,-0.068033,0.272356,0.013238,0.012373,-0.338603,0.150964,0.242349,-0.330927,-0.085925,0.183734,0.036744,0.454263,0.473570,-0.309936,-0.059011,-0.049787,0.175771,-0.169626,0.045938,0.204110,0.279103,-0.053775,0.074855,0.117629,-0.312185,-0.071485,0.141724,0.103193,-0.602632,0.128491,-0.082433,-0.032370,-0.708271,0.252528,-0.176701,0.131368,-0.038332,-0.377586,0.064139,0.364592,0.183203,0.294031,-0.193584,0.130244,-0.442990,0.035335,0.773983,-0.025425,0.093775,0.034781,0.139870,-0.167112,0.030396,-0.144967,-0.021376,-0.151859,0.730459,0.060807,-0.308017,0.183941,-0.496652,-0.364169,-0.501925,0.118630,-0.030729,0.085039,-0.112073,-0.528398,-0.129774,0.028543,-0.271946,-0.149913,-0.026037,-0.190934,0.145586,-0.695132,0.416066,0.307878,0.186332,-0.291482,0.323317,-0.062949,-0.027466,-0.146735,-0.056483,0.242528,0.303164,0.462546,0.421834,0.449320,0.035743,-0.143046,-0.427145,0.667793', '1292533', '1292222', '1309069', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22265121', '另一个故乡', '剧情', '本片是80多岁高龄的德国电影大师爱德嘉·莱兹对其史诗系列作品的总结，亦是其电影人生的总结。影片的原始素材来自于其往年自编自导的现代德国史诗《故乡》三部曲剧集，而现在，这部大气磅礴的史诗则被搬到了电影银幕上。导演以强烈的黑白影像风格与冷峻的笔调，通过一个德国农村里农民生存的故事，向我们展示了德意志民族的人性、历史、文化等方方面面。静心感受一次涤荡灵魂的净化之旅，绝对会让你受益良多，更何况还有另一位德国电影大师赫尔佐格的友情出演。2014年第64届德国电影奖最佳导演、最佳剧本、杰出故事片。', '扬·迪特尔·施耐德', '爱德嘉·莱兹', 8.6, 8635, 'tt1998204', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2175719023.jpg', 0.4, 1.2, 10.7, 42.5, 45.1, '-0.218231,0.006644,-0.457666,1.078600,0.442347,-0.225394,0.390861,-0.036824,-0.384209,-0.126950,0.215328,0.940244,-0.187832,0.050159,0.308433,-0.086346,-0.429986,-0.524972,-0.370402,0.136887,-0.036629,-0.165099,-0.509771,0.083712,-0.219307,-0.367733,0.907352,-0.022785,-0.624515,0.144568,0.260070,0.294393,0.063974,-0.223153,0.058802,-0.061019,0.023116,-0.068681,-0.646222,0.379209,0.187365,-0.136800,-0.198885,0.036863,-0.308193,0.126861,0.798508,-0.094893,0.006448,0.054478,1.072348,-0.062463,-0.311467,-0.147290,-0.089718,0.169594,0.299802,0.491766,0.284506,0.162504,-0.339459,-0.366287,-1.108128,-0.312808,0.161376,0.068041,-0.223765,0.401660,-0.021087,0.042074,-0.009407,-0.062181,0.155059,-0.075902,0.596311,0.488136,-0.032391,-0.029602,-0.167121,0.826771,0.228367,0.091056,-0.573300,0.566800,-0.302793,-0.632251,-0.162668,-0.464556,-0.489756,0.405814,0.186472,-0.068577,0.053119,0.165653,-0.835729,0.115875,-0.004950,-0.427454,0.258196,-0.202317,0.080973,-1.008590,-0.330521,-0.372079,-0.062745,-0.400923,0.383753,-0.401492,1.268308,-0.122113,0.030174,0.535674,-0.017796,-0.222361,0.981640,-0.070186,-0.126606,-0.257480,0.047848,0.237735,-0.263332,0.233061,-0.154582,0.279420,0.125481,-0.260262,-0.416096,0.668386', '27602116', '2027945', '3318306', '26310114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22265299', '绝命海拔', '剧情', '友善谨慎的新西兰领队罗布·霍尔（杰森·克拉科 Jason Clarke 饰），他的队伍名为“冒险顾问”；而斯科特·费雪（杰克·吉伦哈尔 Jake Gyllenhaal 饰）则风趣搞怪，他带领来自西雅图的“疯狂山脉”登山队。他们相互竞争，又彼此帮助。两支队伍中的勇士们来自各行各业，他们中有邮差、记者、医生，还有一名来自日本的职业女性。这些登山者看似平凡, 但每个人背后都有一个属于自己的梦想，激励着他们前往海拔8000米以上、氧气稀薄的珠峰。在攀登过程中，他们的身体机能急速下降，在应对体力衰竭、缺氧、雪盲的同时，他们又极为不幸地遭遇了一场剧烈的暴风雪，因此命悬一线。影片改编自1996年的一次真实探险经历。', '杰森·克拉克', '巴塔萨·科马库', 7.5, 58696, 'tt2719848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2276208896.jpg', 0.5, 3, 33.8, 46.8, 15.9, '0.145445,-0.243461,-0.707634,0.653722,0.105179,-0.032474,0.871134,0.075266,-0.461946,-0.240805,0.550721,0.603123,0.066800,-0.112537,0.252342,-0.183263,-0.235275,-0.530706,-0.177854,-0.016859,-0.285139,-0.272089,-0.469436,-0.194045,-0.191486,-0.371354,0.347970,0.142088,-0.245199,0.665069,0.081465,0.342293,0.029592,0.409941,-0.051835,-0.081190,0.253725,-0.289724,-0.070310,0.120916,-0.082016,-0.005358,-0.231278,0.083734,0.066426,0.629844,0.790073,-0.138899,-0.002838,0.059514,0.177173,-0.342385,0.027930,0.020654,0.507277,0.194700,0.173945,-0.029371,0.057535,0.176994,-0.124352,-0.106980,-0.797179,-0.033133,0.201167,0.302239,-0.361570,0.366628,0.027006,-0.107221,0.099425,-0.227298,-0.108397,0.366780,0.248940,0.160243,-0.219567,-0.279036,-0.329512,0.128806,0.874774,0.043703,-0.567973,-0.133262,-0.527271,-0.727112,-0.139920,-0.162617,-0.723675,-0.093796,0.259568,0.052441,0.059521,0.499876,-0.683012,0.566803,-0.241158,-0.472679,-0.446309,-0.167771,0.057698,-0.709484,0.077186,-0.454387,-0.046688,-0.045531,-0.082432,-0.045023,0.888409,-0.385800,0.112604,0.839258,0.236166,-0.179603,0.537573,-0.110652,0.172995,-0.180154,-0.235304,0.471000,-0.055400,0.280204,0.010685,0.439427,-0.176078,0.102840,-0.188807,0.299368', '3005387', '3811356', '4181031', '1294941');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22265634', '星球大战8：最后的绝地武士', '动作', '邪恶的斯努克所率领的第一秩序正以前所未有的破坏力扫荡抵抗者组织最后的力量。几经辗转，蕾伊（黛西·雷德利 Daisy Ridley 饰）终于在银河一隅找到隐居的卢克·天行者（马克·哈米尔 Mark Hamill 饰），与此同时她自身的力量也正慢慢苏醒。遭到重创的抵抗者命悬一线，为了摆脱第一秩序的追杀，芬恩（约翰·博耶加 John Boyega 饰）和萝丝（凯莉·玛丽·陈 Kelly Marie Tran 饰）逃出主舰，试图找到能令他们起死回生的人物，而好逞英雄的波（奥斯卡·伊萨克 Oscar Isaac 饰）则留下来见证着抵抗者最为危机和绝望的时刻。另一方面，凯洛·伦（亚当·德赖弗 Adam Driver 饰）和蕾伊的精神世界意外连通，他终将和自己的恩师卢克迎来决算的时刻……©豆瓣', '马克·哈米尔', '莱恩·约翰逊', 7.1, 146801, 'tt2527336', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506694509.jpg', 1.8, 7.7, 39, 37.8, 13.8, '-0.058274,0.102931,-0.668915,0.571624,0.198076,-0.303546,0.468078,0.102876,-0.060172,-0.472851,0.150051,0.520773,-0.206028,0.082306,0.384296,-0.209372,-0.238357,-0.605079,0.129303,-0.071207,-0.218202,-0.415798,-0.531758,-0.191564,0.102609,-0.474090,0.714916,0.182564,-0.131289,0.190099,0.029359,0.740554,-0.085627,0.637007,0.030589,-0.000701,0.023924,-0.385556,-0.328915,0.086736,0.140727,-0.343092,-0.000505,0.513766,0.038939,0.180498,0.769050,-0.765685,0.458059,-0.040115,0.144694,-0.379117,0.151352,-0.066077,0.243850,-0.330598,-0.161402,0.066124,-0.144535,0.053710,0.212229,-0.246773,-0.877943,-0.245746,0.162404,0.239885,-0.285748,-0.007631,-0.214012,0.083244,0.133191,-0.145888,0.023721,0.621257,0.228794,0.260861,-0.229359,0.017475,-0.382938,-0.304602,0.392315,-0.100273,-0.259415,0.139022,-0.248183,-0.363629,-0.143470,-0.205258,-0.463497,-0.384320,0.494968,0.260480,0.379181,0.417179,-0.733705,-0.309871,-0.500896,-0.056644,-0.206563,-0.307113,0.065600,-0.848305,-0.088044,-0.226835,0.017194,0.266830,-0.109308,-0.111585,0.495531,-0.574428,0.266531,0.526689,0.325105,-0.153351,0.372806,-0.016982,0.322613,-0.280380,-0.227064,0.781514,0.230659,0.259106,0.200147,0.170186,0.007844,0.111252,-0.193168,0.602954', '20326665', '27133569', '25774050', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22265687', '星球大战9：天行者崛起', '动作', '本片为2017年电影《星球大战：最后的绝地武士》的续集，“星球大战后传三部曲”的第三部作品，同时是“天行者传奇”的第九部作品以及最终章。在卢克·天行者化为绝地英灵的一年后，残存的抵抗势力将再次面对第一秩序。同时，绝地和西斯之间的大战将天行者的传奇带到最后。', '黛西·雷德利', 'J·J·艾布拉姆斯', 6.2, 95312, 'tt2527338', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2575456458.jpg', 4.4, 17.2, 47.9, 22.7, 7.8, '-0.007631,0.051400,-0.422648,0.773676,0.873370,-0.157784,0.552128,-0.248933,-0.416871,-0.409736,0.621763,0.933012,-0.230601,0.016613,0.345902,-0.454347,-0.293834,-0.975976,-0.672942,-0.177189,-0.433091,-0.083154,-0.503890,0.336755,-0.207709,-0.597385,1.486431,0.270082,-0.199520,0.025354,0.216330,0.453332,-0.208838,0.126725,-0.120871,0.274270,0.053273,-0.264912,-0.780717,0.727825,0.090944,-0.168588,-0.363036,0.068078,-0.089834,0.150883,0.873799,-0.633385,0.547419,0.231585,0.712500,-0.196519,-0.480092,-0.151788,0.273105,-0.013885,0.302052,0.628583,0.134392,0.180529,0.025394,-0.390760,-1.354458,0.008948,0.246270,0.082347,-0.512744,0.410638,-0.088020,0.106769,0.388100,0.096015,0.271016,0.413726,0.601246,0.361519,-0.152655,0.028408,-0.221313,0.415347,0.334523,-0.053315,-0.261968,0.186681,0.233714,-0.648357,-0.705699,-0.714397,-0.184044,0.087755,0.451296,0.555286,0.238901,0.873571,-1.219873,-0.345957,-0.013039,-0.400269,0.202857,-0.299139,-0.480712,-0.759074,-0.199501,0.100661,0.433655,0.141922,0.310680,-0.147405,0.994205,-0.697639,0.372155,0.254304,0.310488,-0.173665,1.025216,-0.066673,0.221711,0.053147,0.057774,0.325959,0.071904,0.476609,0.490890,0.258127,-0.072479,-0.322484,-0.290618,0.464385', '26759820', '25880986', '26759819', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22266012', '全球风暴', '动作', '《全球风暴》的故事发生在未来，环境恶化导致自然灾害愈演愈烈，因此世界各国通力合作，创造了能控制天气的强大气象卫星网络。但是卫星网络突发故障开始攻击地球，摧毁一切的气象大灾变席卷世界。而随着事态发展，浩劫背后的阴谋人祸也开始浮出水面，令主人公的救世之旅面临更严峻考验。', '杰拉德·巴特勒', '迪安·德夫林', 5.9, 97209, 'tt1981128', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2497075814.jpg', 4, 22.2, 52.9, 16.9, 4, '-0.484243,0.325491,-0.673833,0.225629,0.487632,1.060056,0.402446,0.120602,-0.370441,-0.134215,0.220132,0.482875,-0.498685,-0.293340,0.206888,-0.398560,-0.224352,-0.594437,0.185552,0.298636,-0.441508,-0.246739,-0.566290,-0.548635,0.085161,-0.735086,0.967319,0.998585,-0.696668,-0.142899,-0.302760,0.214531,-0.405796,0.849629,0.009481,-0.526186,-0.392084,0.252757,-0.569835,0.312395,-0.081146,-0.183181,-0.038016,0.576619,-0.359974,0.040654,0.625767,-0.321436,-0.358873,-0.636288,0.955837,-0.591019,-0.186999,-0.446559,0.749872,0.266971,-0.398128,0.232973,0.204675,-0.131559,0.030898,-0.165043,-0.480699,0.144661,0.000311,0.222215,0.055434,-0.357094,0.218566,-0.235431,-0.247261,0.102312,0.215786,0.902753,0.961391,0.485570,-0.358594,0.282270,-0.428898,-0.143614,0.875417,-0.437706,-1.105557,0.645229,-0.302572,-0.125972,-0.702745,-0.313608,-0.147464,-0.092291,0.050912,0.245672,-0.261904,1.500484,-0.305621,0.415820,-0.232320,-0.684007,-0.207857,-0.190617,-0.351781,-0.951652,-0.460481,0.223704,0.152214,0.099323,0.069772,-0.279123,0.840555,-0.397372,0.029364,0.680471,0.271448,-0.605081,0.021828,0.149216,0.142930,-0.313212,0.010519,0.395766,-0.721362,0.430209,-0.416515,-0.209414,-0.016315,0.012154,0.019314,0.511352', '1308779', '26786669', '26277156', '30201138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22266126', '王牌保镖', '喜剧', '达瑞斯（塞缪尔·杰克逊 Samuel L. Jackson 饰）曾是一名令业内人士闻风丧胆的超级杀手，如今已经缉拿归案的他屈居在铁窗之后，等待着漫长的刑期到头。达瑞斯的妻子索尼娅（萨尔玛·海耶克 Salma Hayek 饰）同样身陷囹圄，某日，达瑞斯得到了一个意外的机会，能 够令索尼娅重获自由，作为交换，他必须出庭作证证明邪恶的罪犯弗拉迪斯拉夫（加里·奥德曼 Gary Oldman 饰）有罪。作为护送达瑞斯出庭的负责人，艾米莉亚（艾洛蒂·袁 Elodie Yung 饰）和她的团队遭到了弗拉迪斯拉夫所派出的佣兵的伏击，全军覆没，幸存的艾米莉亚无奈之下只能找到私人保镖兼前男友迈克尔（瑞安·雷诺兹 Ryan Reynolds 饰），委托他贴身保护达瑞斯。©豆瓣', '瑞安·雷诺兹', '帕特里克·休斯', 7.2, 162026, 'tt1959563', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498055621.jpg', 0.4, 4.3, 42.2, 43, 10.1, '0.158029,-0.079234,-0.277615,0.351854,-0.082366,-0.343555,0.337446,0.284931,-0.566201,-0.458288,0.310494,0.521824,-0.094559,-0.003759,0.505390,-0.085851,-0.659172,-0.592815,-0.294236,-0.410573,-0.128980,-0.574668,-0.386090,-0.148245,-0.132848,-0.412601,0.367730,-0.230246,0.008037,0.315345,0.484697,0.750329,0.127618,0.186972,-0.093718,-0.041959,0.495348,-0.634781,-0.278218,0.328005,-0.017978,0.195823,0.028879,-0.121306,-0.039547,0.415258,0.258749,-0.385755,0.257699,-0.333510,0.229634,-0.171303,0.362524,0.080935,0.248912,-0.157374,-0.005143,0.213686,-0.387670,0.018862,0.539937,-0.081280,-1.110648,0.146630,0.106482,0.116779,-0.392069,0.099564,-0.380695,-0.177116,0.217500,-0.094754,-0.098691,0.476289,0.106521,0.059092,-0.053255,0.027085,-0.485580,0.051333,0.513733,0.113055,-0.123645,-0.282615,-0.318947,-0.680651,-0.036903,-0.417968,-0.498416,0.027726,0.347588,0.142681,0.420504,0.275396,-0.467547,-0.401949,-0.818354,-0.082758,-0.151706,-0.369541,0.127773,-0.777620,0.146789,0.063985,-0.399762,0.072739,0.023112,-0.314099,0.344094,-0.406499,0.416118,0.568855,0.635385,0.152189,0.606895,0.060389,0.244176,-0.129912,-0.177144,0.687814,0.479521,0.267600,0.271112,0.076453,0.205053,-0.213269,-0.005407,0.325959', '27073234', '3157583', '1793491', '1299335');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22266320', '深海浩劫', '剧情', '麦克（马克·沃尔伯格 Mark Wahlberg 饰）是位于墨西哥湾的石油钻塔深水地平线号上的安全维修人员，在和妻子弗里西亚（凯特·哈德森 Kate Hudson 饰）告别之后，麦克将再度面对长达21天的连续作业。麦克的工作经验非常的丰富，在他任职期间，钻塔上没有发生过任何的生产事故，他因此深受上司和同事们的信赖。项目负责人唐纳德（约翰·马尔科维奇 John Malkovich 饰）希望能够加快开采的进程，但麦克表示这将带来很大的安全隐患。唐纳德并没有听取麦克的警告，而是一意孤行，导致钻塔中发声了剧烈的爆炸。霎时间，火海淹没了工人们，126名钻井工人被困在死亡的边缘线上。©豆瓣', '马克·沃尔伯格', '彼得·博格', 7, 50940, 'tt1860357', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2396092735.jpg', 0.5, 4.2, 48.6, 39.4, 7.4, '0.260641,-0.148839,-0.852977,0.545796,0.198331,-0.151129,0.960709,0.115078,-0.539645,-0.079848,0.131951,0.490888,-0.096291,0.035874,0.127523,-0.259088,-0.458492,-0.631132,-0.297663,0.001049,-0.470328,-0.774108,-0.147098,-0.243970,-0.319850,-0.269346,0.464328,-0.010118,-0.054778,0.568666,-0.099911,0.286426,0.283280,0.661943,0.087280,0.010444,0.282355,-0.364648,-0.143306,0.249087,-0.029602,-0.015062,0.076721,0.227735,0.476934,0.649841,0.477329,-0.357745,-0.036724,0.071801,0.263176,-0.246300,0.378419,0.098554,0.228140,0.210163,-0.057662,0.311802,-0.385962,0.137100,0.175472,-0.181947,-0.653614,0.000288,-0.248415,0.251074,-0.556797,0.441086,-0.136699,-0.037724,-0.092474,-0.228518,0.183152,0.289192,0.160474,0.081565,-0.355687,0.044456,-0.355250,0.039958,0.537728,-0.080890,-0.284244,0.171084,-0.269683,-0.378991,-0.261563,-0.174667,-0.406904,-0.193686,0.356549,0.257909,0.042827,0.207245,-0.556960,0.048304,-0.215649,-0.734639,-0.236587,-0.066949,-0.346866,-1.026650,0.104078,-0.329519,-0.280319,0.043202,-0.123631,-0.191145,0.588604,-0.805406,0.290377,0.520964,0.248953,-0.170554,0.574424,0.003843,0.239979,-0.192897,-0.118502,0.259212,0.214945,0.539057,0.087439,0.315304,-0.035989,-0.349817,-0.218977,0.403042', '3178770', '1316693', '3735015', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22266475', '惊天解密', '动作', '爱丽丝（劳米·拉佩斯 Noomi Rapace 饰）曾经是隶属于中情局的高级审讯官，在一次反恐任务中，她的疏忽导致了数十名百姓无辜丧生，受不了良心谴责的爱丽丝选择了辞职，并且彻底放下了过去，开始尝试着去过普通人的生活。可就在爱丽丝渐渐以往了曾经的日子时，中情局找到了她，邀请她再度出山协助破案。在破案的过程里，爱丽丝渐渐发觉了其中的猫腻。种种线索都在表明，在中情局中隐藏着内鬼。就这样，爱丽丝凭借着一人之力开始了对于内鬼的调查，这也让她身处险境之中。偌大的中情局里，只有杰克（奥兰多·布鲁姆 Orlando Bloom 饰）在她最需要帮助的时候伸出了援手，可是爱丽丝却并不相信这个神秘的男人。©豆瓣', '劳米·拉佩斯', '迈克尔·艾普特', 5.8, 4729, 'tt1734493', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2499413364.jpg', 1.8, 24.8, 58, 13.8, 1.6, '0.378071,0.228651,-0.847392,0.496513,-0.254007,-0.155593,0.731164,-0.105975,-0.819364,-0.251299,0.227873,0.514021,0.103777,0.128782,0.215575,-0.063145,-0.398519,-0.769797,-0.062105,-0.411238,-0.586499,-0.525323,-0.466633,-0.313755,-0.059649,-0.382599,0.450597,0.185922,-0.285549,0.228069,0.168923,0.207374,-0.109608,0.642789,-0.210125,-0.013498,0.210569,-0.061020,-0.093834,0.363313,0.200200,-0.601661,-0.133816,0.477475,0.088354,0.564278,0.519545,-0.543680,-0.154735,0.057789,0.131087,-0.335191,-0.182011,0.102578,0.343247,0.006997,0.243301,0.189676,-0.391559,0.176359,-0.034047,0.008336,-0.775835,-0.008291,-0.045764,0.463587,-0.732848,0.372698,-0.012850,-0.049636,0.102242,-0.310377,0.232457,0.394352,0.082612,0.077382,-0.172223,-0.149213,-0.501812,0.141810,0.645247,-0.136566,-0.099239,0.404926,-0.164058,-0.527419,-0.159855,-0.088654,-0.265584,-0.082506,0.220722,0.239326,-0.305051,0.271100,-0.565941,0.066313,-0.166850,-0.119333,-0.352164,-0.391953,-0.000137,-0.511731,-0.233348,-0.185004,-0.297313,0.141936,-0.184545,-0.327496,0.480199,-0.997300,0.327948,0.650296,0.328115,-0.361351,0.553057,0.121785,0.265182,-0.083742,-0.018233,0.306593,0.115612,0.498958,0.258251,0.375451,-0.012047,-0.436957,-0.372585,0.482390', '25870679', '1301022', '1947080', '1308050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2227293', '黑暗阴影', '喜剧', '1760年的利物浦码头，科林斯夫妇正带着年幼的巴纳巴斯登上开往新大陆的船，前去扩张科林斯家族帝国。16年后，巴纳巴斯（约翰尼·德普 Johnny Depp 饰）长大成人，继承了家族产业，坐拥科林伍德庄园。女巫安琪莉可（伊娃·格林 Eva Green 饰）投怀送抱，而巴纳巴斯却心系善良姑娘乔赛特（贝拉·希思科特 Bella Heathcote 饰），无情地拒绝了女巫。女巫恼羞成怒，对两人施行毒咒，乔赛特香消玉损，而巴纳巴斯则变成了一只永远的吸血鬼被封在棺中。两个世纪后，一个施工队无意间挖开了棺木，巴纳巴斯回到庄园准备东山再起时，却发现曾经属于自己的科林斯港已经变成了女巫的天使海湾，良民们被她统治长达200年之久，地位难以撼动。身为吸血鬼的巴纳巴斯能否夺回家族产业，击碎女巫的谎言呢？与此同时，一位长相酷似昔日爱人乔赛特的年轻女孩也鬼使神差地来到了科林斯港……本片改编自20世纪60年代于ABC电视台播出的一档肥皂剧，讲述了吸血鬼巴纳巴斯·科林斯与狼人、女巫、僵尸等非人类生物在各个时空间的冒险经历。', '约翰尼·德普', '蒂姆·波顿', 6.4, 65584, 'tt1077368', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1465134975.jpg', 2.1, 14.5, 52.5, 23.1, 7.8, '0.121537,0.030750,-0.394108,0.412546,0.040707,-0.378133,0.872721,0.240345,-0.538235,-0.295950,0.124663,0.802975,-0.011072,0.252829,0.490864,0.337769,-0.599514,-0.594733,0.085823,-0.343532,-0.073876,-0.398021,-0.247889,-0.347652,-0.013199,-0.555527,0.566231,0.059013,0.255408,0.258783,0.010572,0.410895,-0.126850,0.074339,-0.018765,0.205047,0.500030,-0.205227,-0.082593,0.320150,-0.336487,0.010295,-0.169388,0.017347,-0.023258,0.149908,0.425119,-0.476927,0.370950,-0.483870,0.048324,-0.377318,0.160338,0.217345,0.516930,-0.460485,0.091974,0.044096,-0.134661,-0.184768,0.286003,-0.301112,-0.413674,0.202908,0.024822,0.051942,-0.773577,0.673703,-0.345403,0.121422,0.012485,-0.300780,-0.016497,0.194563,0.303522,0.428349,0.083501,0.136848,-0.573881,-0.181783,0.288296,0.129431,-0.573420,-0.033997,0.044452,-0.532486,-0.247432,-0.274453,-0.562974,-0.088606,0.620463,0.085941,-0.010167,0.690785,-0.740099,-0.267077,-0.718719,-0.190364,0.241530,-0.238538,-0.387991,-0.643536,-0.052390,-0.239895,0.064285,-0.040067,0.044062,0.004376,0.490454,-0.610985,0.349054,0.294658,0.327393,-0.209175,0.559260,-0.442891,0.242455,-0.078015,0.051531,0.673226,0.312476,0.174442,0.190134,