INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2229243', '幸福', '剧情', '永诛（黄正民 饰）在首尔经营歌舞厅，但不幸破产又患上了肝硬化，更不幸的是他的女友秀妍（孔孝真 饰）也要离开他。他跟母亲及朋友们说到国外去，实际上他来到了一间乡村疗养院。结识了身患严重肺病的恩熙（林秀晶 饰）。虽然在疗养院生活了8年，每当发作她都觉得自己将要死去，但她乐观 的态度深深感染了永诛。两人很快便相爱了，永诛在恩熙的帮助下病情得到了很好的控制，后来两人更搬离了疗养院开始了同居生活。但当永诛再次回到首尔，他便有了要离开恩熙的念头，恩熙痛不欲生但还是让永诛离开了。分开后永诛的生活一塌胡涂，病情加重的他住院了，某天他也得知了恩熙的消息……©豆瓣', '林秀晶', '许秦豪', 7.4, 10005, 'tt1048159', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1173473781.jpg', 0.5, 3.7, 38.4, 41.3, 16, '0.070174,-0.018368,-0.675247,0.137176,0.006395,-0.416242,0.810042,0.345241,-0.582324,-0.058793,0.130529,0.863912,-0.194422,0.465152,0.194015,0.276141,-0.215456,-0.431939,0.402158,-0.179260,-0.426223,-0.302579,0.026086,-0.269660,-0.114680,-0.282403,0.451976,0.256779,-0.135481,0.322664,-0.076909,0.149397,0.232989,0.854828,-0.449498,0.394933,-0.308830,0.087241,-0.056956,0.205846,0.529162,-0.605765,-0.246589,0.396906,0.364216,0.458849,0.560791,0.233951,-0.463310,0.203702,0.320471,-0.356983,-0.326865,0.190080,0.348928,0.017505,0.157848,0.278001,-0.654353,0.079800,-0.226115,0.074737,-0.367114,0.244512,0.056562,0.022735,-0.788238,0.657925,-0.154386,-0.029075,0.001846,-0.463542,0.335353,0.555357,-0.132252,0.517278,-0.377928,-0.033702,-0.623833,0.206557,1.079070,-0.139611,-0.196488,0.424498,-0.333046,-0.507327,-0.154723,-0.028198,-0.362724,-0.078456,0.348210,0.097669,-0.549017,0.229982,-0.380543,-0.064116,-0.241383,-0.159302,-0.114778,-0.360885,0.184739,-0.400632,-0.191047,-0.376893,-0.528622,0.028533,-0.150092,-0.307206,0.753339,-0.995712,0.260924,0.506472,0.595885,-0.943997,0.563526,0.272821,0.231486,0.077865,0.249284,0.573959,-0.161141,0.442275,0.319189,0.326105,-0.077516,-0.039597,-0.482578,0.554668', '25721544', '26718282', '1292064', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2229427', '出埃及记', '剧情', '警察詹建业（任达华 饰）给一个在女厕偷窥的疑犯关炳文（张家辉 饰）录口供。关炳文不认罪，却说在厕所听到了有几个女人在商量用奇特药物杀死所有坏男人。建业虽然觉得无稽，但还是把口供记录下来。当天晚上，同僚告诉建业关炳文的口供不见了。当建业再次为关炳文录口供的时候，奇怪是他竟然承认自己在厕所偷窥，建业怀疑案件警察方子晴（邵美琪 饰）有关，决定追查下去。而方子晴则在女厕与建业的妻子（刘心悠 饰）见面，希望建业的妻子能阻止丈夫追查案件。正当建业继续调查之际，接到了关炳文失踪的的消息，而关的前妻潘小源（温碧霞 饰）也在这个时候出现了。本来与妻子（刘心悠 饰）关系越来越僵持的建业，在安慰失去丈夫的潘小源时与之发生了关系。当发现自己丈夫真的有外遇时，建业的妻子才显露了她的秘密……©豆瓣', '任达华', '彭浩翔', 7.1, 31400, 'tt1091616', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2588739573.jpg', 1.1, 5.8, 41.4, 40.4, 11.3, '0.363402,-0.035715,-0.638599,0.271814,-0.127232,-0.273948,0.590228,0.426880,-0.589839,-0.376787,0.300692,0.525410,-0.281687,-0.173727,0.169327,-0.008166,-0.348386,-0.897465,0.360571,-0.226173,-0.093623,-0.713787,0.118783,-0.038726,0.105331,-0.296284,0.345768,-0.162462,-0.070052,0.376062,0.234762,0.191771,-0.230032,0.631345,-0.031234,0.067234,0.191332,0.091801,-0.480493,0.260771,0.340164,-0.252062,-0.138382,0.050105,-0.074698,0.487246,0.496570,-0.061388,-0.576439,0.282031,0.330926,-0.065936,-0.124866,-0.007890,0.438561,0.075749,0.219098,0.422731,-0.585025,-0.193106,0.122686,0.400755,-0.546443,0.170445,0.206131,0.459548,-0.455278,0.275293,-0.370562,0.068180,0.302798,-0.445228,0.533214,0.599424,-0.051091,0.486892,-0.184984,-0.047162,-0.655305,0.155627,0.307543,-0.078669,0.340933,0.402657,0.270516,-0.033273,0.217169,0.197493,-0.377086,0.241198,0.108376,-0.000127,-0.545158,-0.040632,-0.226238,-0.335375,-0.282073,0.194283,0.140853,-0.376836,-0.331984,-0.282246,-0.316480,-0.017386,-0.310251,-0.054994,0.097695,-0.196926,0.454469,-0.965192,0.113047,0.394062,0.392306,-0.814745,0.526806,0.357111,-0.070595,-0.286082,-0.030529,-0.245331,0.102657,0.452752,0.173659,0.254888,0.134919,-0.599729,-0.449396,0.085212', '35073886', '3263169', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22299426', '二重身', '悬疑', '名不见经传的画家桐村忍（水川麻美 饰）与新搬入公寓的高村胜相恋成婚，过上了还算舒心的生活。某天，去超市购物的忍因涉嫌使用假钞被店员抓住，而且监控分明记录了她犯案的全过程。稍后不久，赶来的刑警加纳隆（泷藤贤一 饰）将忍带走，刑警表示相信忍的辩白，并将她带入一个神秘会场。那里由姓饭冢（丰原功补 饰）的人主持，另有大学生御手洗巧（千贺健永 饰）、家庭主妇门仓真由美（酒井若菜 饰）等不同身份的人。他们此前均饱受二重身的困扰，所谓二重身是和本人无论从容貌还是记忆均一模一样的虚幻之体，二重身会破坏本体的生活，夺走他们最重要的东西，甚至最终杀掉本体。忍和这些受害者该如何保护自己的人生？本片根据法条遥的同名原作改编。©豆瓣', '水川麻美', '安里麻里', 7.4, 14317, 'tt3029570', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2158545578.jpg', 1.1, 5.2, 33.6, 44.4, 15.7, '0.117874,0.118985,-0.217534,0.362380,-0.159674,-0.210695,0.405978,0.344258,-0.183176,-0.479064,0.261547,0.510327,-0.169524,0.040027,0.290884,-0.165142,-0.227920,-0.391920,0.076892,-0.204552,-0.346225,-0.258905,-0.167857,0.083094,-0.172933,-0.258134,0.754853,0.047212,-0.007718,0.150983,0.245728,0.301788,-0.216532,0.030251,-0.122199,-0.051669,-0.162316,0.008727,-0.143207,0.159774,-0.232689,-0.153377,-0.029155,0.205660,0.149185,0.488575,0.696358,-0.163273,-0.134942,0.003615,0.260236,-0.190342,-0.360569,0.169688,0.196069,-0.061232,-0.067603,0.269205,-0.279663,0.057935,-0.001777,0.188551,-0.810258,-0.233822,0.369360,-0.107459,-0.211758,0.292727,-0.079846,0.039238,0.006570,-0.091231,-0.006019,0.332609,0.102949,0.414596,-0.037595,0.076716,-0.422552,0.288344,0.558258,-0.161796,-0.129495,0.282909,-0.091713,-0.425415,-0.276237,-0.450883,-0.181822,0.015561,-0.109445,0.249398,-0.141474,-0.185430,-0.291275,-0.220453,-0.194968,0.089726,0.031776,-0.354183,-0.107134,-0.447910,-0.179375,-0.287698,-0.262945,-0.146407,0.198882,-0.184805,0.691012,-0.536732,-0.001252,0.205966,0.315627,-0.386312,0.497561,0.222676,0.125140,-0.306382,-0.162008,0.268276,0.386500,0.361755,0.032927,0.335321,-0.124398,-0.015364,-0.401355,0.200344', '25880986', '26759820', '27602116', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22300822', '百变爱人', '喜剧', '苏波荣（王祖蓝 饰）觉得自己的人生陷入了低谷。事业上，他饱受自私自利的老板马上发（许冠文 饰）的排挤和算计，工作多年亦看不见出头之日。亲情上，好吃懒做的母亲（元秋 饰）只将苏波荣当做是赚钱的工具，自打儿子十六岁起，母亲便过起了靠儿子养活的逍遥日子。友情中，好友华帝（方力申 饰）成天在外惹是生非，苏波荣往往就是帮他收拾烂摊子的那个不二人选。幸运的是，无论混的多惨，苏波荣的女友钟家宝（王莞之 饰）依然不离不弃的守在他的身边，接受着男友的负能量和脾气，毫无怨言，久而久之，苏波荣早已经在潜意识里将钟家宝当做了发泄不满的“垃圾桶”。一天，苏波荣的手机上收到了一条神秘的短信，此时的他并不知道，自己无心的转发，竟然彻底扭转了命运。©豆瓣', '王祖蓝', '叶念琛', 4.5, 4645, 'tt3560762', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2177006178.jpg', 26.1, 36.5, 28.1, 6, 3.2, '0.226485,0.118043,-0.485795,0.539560,-0.224573,-0.376801,0.484612,0.280690,-0.546551,-0.131482,-0.013865,0.605778,-0.027030,0.586707,0.215878,0.047305,-0.176828,-0.788176,-0.417256,0.043915,-0.193161,-0.618375,-0.359803,0.032123,-0.156045,-0.077264,0.239724,-0.063183,0.010473,0.137390,0.472798,0.082140,-0.093415,0.560446,-0.028780,0.213315,-0.232317,0.147892,-0.145992,-0.232841,0.117319,-0.627258,0.030061,0.415152,0.075189,0.279946,0.669624,-0.067388,0.003613,-0.227189,0.491006,-0.109353,-0.153212,-0.173015,0.031381,-0.043274,0.267514,0.164196,-0.191713,0.094821,0.097358,-0.030135,-0.773950,-0.146656,0.001256,0.018437,-0.685622,0.737121,-0.090843,0.236368,-0.272068,-0.409034,0.250992,0.119698,-0.085211,0.246080,-0.504235,0.155574,-0.366351,0.279590,0.414813,-0.076763,-0.085342,0.295253,-0.105021,0.022766,0.041598,-0.272339,-0.783822,-0.396744,0.424810,0.132519,-0.124352,0.062761,-0.427578,0.147291,-0.179457,0.019131,0.242003,-0.262246,-0.089418,-0.152334,-0.146429,-0.589750,-0.569966,0.211914,0.040897,-0.544342,0.674389,-0.701843,0.204848,0.239607,0.142389,-0.569606,0.672265,0.113209,0.236241,-0.232639,0.170697,0.196701,-0.101880,0.193588,0.392388,0.088280,-0.185026,-0.204687,-0.322185,0.583894', '30279170', '26809007', '1298880', '26773744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2230888', '最遥远的距离', '剧情', '小汤（莫子仪 饰）与相恋多年的女友分手了，独自来到了台东。在那里，他在大自然最美丽的声音陪衬下，录下了自己的真情告白。他把一卷卷录音带，寄给了身在台北的前女友。他希望可以挽回昔日的爱恋，可是他不知道女友早已搬走了原来的住所。上班族小云（桂纶镁 饰）搬到了新家之后接二连三收到了寄给前一任租客的录音带。这时的她正陷入了一段三角恋中，而录音带里的声音，仿佛在牵引她逃离复杂的感情世界。她要到台东去，寻找声音的来源。阿才（贾孝国 饰）是一名心理医生，他帮忙病患解答难题，却发现最需要治疗的是被婚姻问题困扰的自己。他决定放开当今的一切，到台东去寻找多年前的情人。小汤在台南到处录下声音的过程中，偶遇了阿才并帮助了逃离被勒索的险境。两人互相倾诉爱情的痛苦，互相安慰与帮助。小云则一路寻找小汤，直到他们不约而同来到了同一个沙滩，却不认识彼此。©豆瓣', '桂纶镁', '林靖杰', 6.9, 40211, 'tt1094291', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p461627429.jpg', 1.1, 8.1, 47.2, 33.5, 10, '0.464095,0.023976,-0.691697,0.590945,-0.118292,-0.201556,0.816313,0.071057,-0.439688,-0.136684,0.051426,0.739197,0.001657,0.331275,0.055210,0.117599,-0.310376,-0.840016,-0.026164,-0.287888,-0.481004,-0.481057,-0.222525,-0.064725,-0.143160,-0.111822,0.525135,0.190197,-0.155895,0.401805,0.184212,0.085357,-0.203974,0.644927,-0.332320,0.175026,0.085100,0.177308,-0.248993,0.335960,0.101170,-0.565920,-0.173083,0.385047,-0.041582,0.364989,0.687070,-0.179354,0.007099,0.343592,0.183080,-0.187294,0.035899,0.106352,0.131866,0.002874,0.313910,0.257037,-0.536968,-0.028113,0.001288,0.021981,-0.596463,-0.076746,-0.039461,0.309104,-0.753577,0.482860,-0.025874,-0.010410,0.276950,-0.492639,0.310596,0.275389,0.085296,0.478879,-0.361758,-0.090167,-0.365583,0.265914,0.701504,-0.007448,0.014871,0.541864,-0.108742,-0.369702,-0.113082,0.101072,-0.472269,-0.186409,0.379127,0.201350,-0.219301,0.004260,-0.587022,-0.123354,-0.148692,-0.230428,-0.029054,-0.621205,-0.192130,-0.449940,-0.319287,-0.315343,-0.153741,0.089080,0.011354,-0.282223,0.569332,-0.815479,0.282496,0.684169,0.220410,-0.392858,0.712912,0.150660,0.006321,-0.268356,0.145777,0.190392,-0.006558,0.525049,0.297890,0.206774,-0.155125,0.134573,-0.775779,0.350786', '4604803', '1937946', '1309066', '1299965');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2230893', '今晚带我回家', '剧情', '马特·富兰克林（托弗·戈瑞斯 Topher Grace 饰）刚刚从麻省理工学院毕业，然而他却似乎并不想遵从父愿进入金融界，而是选择了在一家音像店里打工，同时思索着自己究竟想要做什么。直到一天，马特高中时代暗恋的女生拖丽（泰莉莎·帕尔墨 Teresa Palmer 饰）偶然走进他的音像店，并邀请他参加一个劳动节聚会，聚会恰巧是由马特的妹妹温迪（安娜·法瑞丝 Anna Faris 饰）和她男友举办的。聚会上，马特发现原来温迪并非那么喜欢男友，昔日朋友也都各自面临人生的危机。这些怀揣烦恼的少年们不约而同地决意在今夜抛开顾虑放肆欢愉，然而今夜之后，几个年轻人的命运竟也开始交缠在一起……©豆瓣', '托弗·戈瑞斯', '迈克尔·道斯', 6.3, 6017, 'tt0810922', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p883170689.jpg', 2.4, 14.6, 55, 22.4, 5.6, '0.444189,0.009958,-0.789443,0.244048,-0.013572,-0.405591,0.763501,0.117475,-0.382730,-0.409458,0.141172,0.715087,-0.193544,0.586838,0.397939,-0.060281,-0.387553,-0.776141,0.221075,-0.264039,0.055358,-0.339546,-0.017931,-0.177146,0.027452,-0.050824,0.371736,0.138344,0.048162,0.609150,0.572740,0.068541,-0.226457,0.671422,0.014458,-0.284141,0.335977,0.394403,-0.313668,0.086770,-0.078085,-0.233297,-0.282520,0.168087,0.250134,0.438288,0.493205,-0.235430,0.013385,0.042587,0.105256,-0.029973,0.079785,0.212717,0.193703,0.077992,0.345945,0.178797,0.108118,0.116852,-0.040267,-0.106875,-0.372925,0.156201,0.038005,0.197833,-0.325385,0.467335,0.183151,-0.084761,-0.090530,-0.305107,0.107084,0.361985,0.214572,0.088116,-0.149507,0.005177,-0.330663,0.155750,0.693344,-0.055626,0.074879,0.388118,-0.063052,-0.291793,0.045481,0.131282,-0.543873,-0.005457,0.024298,0.247884,-0.076304,0.179466,-0.516264,-0.031746,-0.060831,0.007235,0.103058,-0.457484,0.052765,-0.675943,0.175295,-0.039895,-0.325209,0.150538,0.109472,-0.260927,0.453424,-0.938610,0.241038,0.485733,0.323576,-0.435309,0.551889,0.197241,0.094077,-0.261391,-0.186539,0.395153,-0.035117,-0.028288,-0.277773,0.277450,0.204710,-0.095529,-0.340672,0.400024', '1308755', '26687241', '1301022', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2230905', '阳光清洗', '剧情', '以清洁房屋为生的单身母亲罗丝（艾美•亚当斯Amy Adams 饰）高中时曾是风光一时的校啦啦队员。当年男友迈克（史蒂夫•赞恩 Steve Zahn 饰）终于另娶他人，罗丝却与身为警察的迈克依然保持情人关系。罗丝八岁的儿子奥斯卡（杰森•斯佩瓦克 Jason Spevack 饰）因捣乱被学校开除，罗丝决定送儿子入私立学校学习。迈克告知罗丝犯罪现场清洁有利可图，于是罗丝与失业的妹妹诺拉（艾米丽•布朗特 Emily Blunt 饰）组成“阳光清洗公司”，专门清洁犯罪、事故现场，而做小生意的父亲乔（阿兰•阿金 Alan Arkin 饰）暂时照顾奥斯卡。可公司起步没多久，却因诺拉的失误造成了无可挽回的损失，姐妹二人也因此不欢而散……本片被提名2008年圣丹斯电影节评委会大奖。©豆瓣', '艾米·亚当斯', '克莉斯汀·杰弗斯', 7.5, 20736, 'tt0862846', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453538635.jpg', 0.2, 1.7, 32.5, 52.4, 13.1, '-0.052425,-0.201581,-0.205796,0.185940,-0.122278,-0.543406,0.517349,0.413883,-0.423378,-0.474083,0.159418,0.692182,-0.183372,0.302821,0.403650,0.008388,-0.420193,-0.395839,0.179316,-0.002143,-0.093822,-0.416035,-0.029300,-0.130660,-0.054681,-0.182833,0.464683,-0.264463,0.013490,0.524408,0.330063,0.216323,-0.059190,0.124794,0.201562,0.131843,0.205901,0.022959,-0.523199,0.095822,-0.030975,-0.115364,-0.077989,-0.101460,0.411250,0.629924,0.514920,0.058554,0.039358,-0.520107,0.491836,-0.182203,0.215969,-0.039362,0.344923,-0.093338,0.246716,0.241441,-0.041882,-0.138822,0.250583,-0.330965,-0.311619,0.196773,0.217101,-0.081093,-0.439636,0.166983,-0.221320,0.253380,0.017624,0.005796,0.011099,0.209354,0.150382,0.239088,-0.127936,0.333702,-0.324584,0.305229,0.216341,-0.211290,-0.129133,0.175288,-0.322659,-0.467659,0.294276,-0.287430,-0.403288,0.234842,0.140099,-0.040034,0.232409,0.057670,-0.288542,-0.578222,-0.315409,-0.131413,0.056990,-0.303634,0.077381,-0.751770,0.095372,-0.086290,-0.334146,-0.129416,-0.083889,-0.064069,0.199490,-0.538313,0.154151,0.295660,0.309043,-0.500741,0.577276,0.016667,0.517668,-0.220504,-0.084435,0.373501,-0.050611,-0.010104,0.097136,0.012726,0.308309,-0.248612,0.080035,0.163796', '1484091', '1297239', '3217128', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2230906', '公爵夫人', '剧情', '本片根据英国作家艾曼达·佛曼的人物传记《乔治亚娜，德文郡公爵夫人》改编。18世纪末，年轻美貌的乔治亚娜·卡文迪什（凯拉•奈特利 Keira Knightley 饰）奉母命嫁给了长自己九岁的第五代德文郡公爵（拉尔夫·费因斯 Ralph Fiennes 饰）。乔治亚娜聪明风 趣，对时尚的敏感触觉使其成为了伦敦贵族的夺目中心，却无法触动不忠丈夫的心。德文郡公爵不满乔治亚娜没为自己带来儿子，与她最好的朋友，伊丽莎白夫人（海莉·阿特维尔 Harley Atwell 饰）公开偷情。愤怒的乔治亚娜投向了格辉党新秀查尔斯·格雷（1830-1834年任英国首相）（多米尼克·库珀 Dominic Cooper 饰）的怀抱，但二人的感情却为德文郡公爵所不允……本片获奥斯卡及英国电影电视协会最佳服装设计奖，并被提名奥斯卡最佳艺术指导、英国电影电视协会最佳化妆及发型和金球奖最佳男配角（拉尔夫·费因斯）。', '凯拉·奈特莉', '索尔·迪勃', 6.9, 52595, 'tt0864761', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p794903839.jpg', 0.5, 5.7, 50.2, 34.7, 8.9, '0.006439,-0.142220,-0.438810,0.817968,0.421841,-0.146663,0.526454,0.320068,-0.182508,-0.401118,0.065047,1.082567,-0.216809,0.197568,0.352422,0.728086,-0.856146,-0.745760,0.186470,-0.092286,0.243567,-0.537391,-0.220864,-0.173415,-0.138942,-0.498852,0.619014,-0.385151,-0.169310,0.482675,0.503067,0.283653,0.472184,0.226795,0.005491,0.223443,0.651902,-0.404866,-0.274926,0.078717,0.145994,0.101933,-0.121300,0.197130,0.445176,0.330079,0.562769,-0.386981,0.423427,-0.219239,0.775836,-0.170372,0.355473,0.138172,0.242256,-0.384700,0.051418,0.134248,0.020923,-0.039308,0.293399,-0.209886,-0.566634,0.323499,0.283743,-0.074875,-0.211477,0.496353,-0.512195,-0.128848,-0.027428,0.244965,0.153888,-0.073004,0.100969,-0.143550,-0.042427,0.154738,-0.141340,0.314817,0.153661,0.193725,-0.448431,0.272637,-0.456427,-0.676475,-0.086135,-0.401911,-0.540090,-0.147543,0.512510,-0.132369,0.457410,0.250562,-0.110634,-0.508506,-0.512493,-0.180160,0.088188,-0.344479,-0.005089,-0.740339,-0.139795,-0.506593,-0.056343,-0.430610,0.084484,-0.135189,0.430580,-0.444559,-0.124374,0.520478,0.076479,-0.343596,0.712732,-0.128381,0.245427,-0.413009,-0.522404,0.482998,-0.048253,-0.223686,0.144503,0.411260,0.136086,-0.088288,0.002585,0.379615', '1298616', '1780122', '1291859', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2238297', '迷情站台', '剧情', '电视电影『迷情站台』由BBC台在2007年推出，作为英国同性恋合法化40周年的特别场放映。编剧凯文·埃利奥特是英国文学最高荣誉奥利弗奖得主。电影撷取了伦敦同志的不同断面——从同性伴侣的宣誓仪式到各怀心事的老友聚会，从学校的写字间到酒吧夜店，从拘束的图书场馆到纵情的站台公 厕...剧情、场景和人物如万花筒般旋转，千丝万缕的因缘际会牵扯出同志世界的忠诚与背叛，愤怒与残忍，放纵与克制，懵懂与觉醒。©豆瓣', '瑞切尔·布莱克', '亚德里安·谢尔高德', 8.3, 13728, 'tt1043903', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2411719633.jpg', 0.4, 1.4, 15.5, 46.1, 36.7, '0.171159,0.022860,-0.625219,0.439191,0.133143,-0.038402,0.894133,0.391011,-0.253340,0.133201,0.480869,0.768492,-0.689563,0.295733,0.717333,-0.222545,-0.219778,-0.733869,-0.137434,-0.185901,0.084689,-0.327133,-0.056293,-0.205066,0.120939,-0.571054,0.804168,0.135110,-0.448986,0.420320,0.415806,0.294220,-0.612071,0.190752,-0.041849,-0.243875,0.087060,0.538634,-0.445415,-0.046149,-0.102091,0.022396,-0.361181,-0.211391,0.163715,0.059778,0.757577,-0.100811,-0.204078,0.180897,0.515687,-0.144938,-0.296777,-0.046053,0.449129,0.135261,0.044896,0.359331,0.326780,0.101725,-0.094500,-0.328507,-0.517005,-0.102854,0.039545,0.229342,-0.401746,0.735040,-0.107710,-0.062870,0.163232,-0.130415,0.085699,0.148180,-0.061229,0.749662,-0.075041,0.000969,-0.601248,0.555044,0.294426,0.230536,-0.589250,0.343536,-0.193868,-0.415865,-0.168866,-0.166162,-0.325815,-0.090818,0.285111,-0.237979,-0.098554,0.430233,-0.782933,-0.323203,0.269245,-0.322511,0.570362,-0.608929,-0.027252,-1.080492,-0.252307,-0.179994,0.188975,-0.201685,0.291116,-0.028045,0.801165,-0.990131,0.132300,0.569406,0.038346,-0.390227,1.202685,-0.091551,-0.249044,-0.286709,-0.111450,-0.001368,-0.004211,0.428312,-0.064461,0.517288,-0.207738,0.124480,-0.614275,0.311791', '1322847', '24751811', '2334814', '1306860');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2244426', '雷霆沙赞！', '动作', '因儿时与母亲失散，少年比利（亚瑟·安其 Asher Angel 饰）辗转多个家庭，却执着地要回到妈妈身边。当他再度栖身一个由养子养女的大家庭时，却阴差阳错来到某个未知的领域，并且成为古老巫师的继承人。当他喊出“沙赞”时，便会瞬间变成拥有强壮成年人身体的超级英雄雷霆沙赞（扎克瑞·莱维 Zachary Levi 饰）。比利兴奋不已，和新家的兄弟——患有腿部残疾的弗雷迪（杰克·迪伦·格雷泽 Jack Dylan Grazer 饰）共同分享这份快乐，两人更将展现各种超能力的视频上传网络，流布四方。结果，心怀叵测的赛迪斯·希瓦纳博士（马克·斯特朗 Mark Strong 饰）找上门来。希瓦纳童年时曾与沙赞身份失之交臂，一直不受父亲兄长待见的他将灵魂出卖给七宗罪魔鬼，他更企图摧毁那个让他求之不得又恨之入骨的雷霆沙赞……©豆瓣', '扎克瑞·莱维', '大卫·F·桑德伯格', 6.2, 241869, 'tt0448115', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2551249211.jpg', 3.1, 17, 51.8, 22.7, 5.4, '0.202284,0.053435,-0.484785,0.515967,-0.097382,-0.521454,0.699151,0.210767,-0.426912,-0.410053,0.109325,0.986155,-0.085115,0.437712,0.220588,0.092085,-0.217016,-0.577027,0.089036,-0.080019,-0.207080,-0.374531,-0.251597,-0.072246,-0.195406,-0.465748,0.661187,-0.297509,-0.054242,0.113574,0.282177,0.548990,0.003598,0.201281,-0.241283,0.206815,-0.034155,-0.102007,-0.332966,0.036814,-0.046029,0.138356,-0.007861,0.142784,-0.238223,0.046688,0.582296,-0.424720,0.269233,-0.630393,0.609995,-0.014002,0.067864,0.051490,0.046396,0.059937,0.143518,0.151775,-0.056734,-0.065047,0.251271,-0.193401,-0.722972,0.057454,0.076785,0.080224,-0.422465,0.104494,-0.127597,0.135428,0.250356,-0.245733,0.049481,0.177497,0.142800,0.381559,-0.258755,0.156574,-0.233190,-0.017922,0.473399,-0.068080,-0.225069,-0.044666,-0.305199,-0.275203,0.127486,-0.190609,-0.643533,-0.025889,0.376823,0.289584,0.096784,0.610538,-0.580926,-0.191870,-0.556862,0.188059,0.074556,-0.473124,-0.171080,-0.603801,-0.330343,-0.106761,0.071366,0.039192,0.125113,-0.203027,0.712589,-0.590557,0.306543,0.378153,0.359651,-0.313078,0.389281,0.047178,0.186091,-0.377832,-0.025602,0.429686,0.330196,0.090176,0.114200,0.023354,0.079390,0.144441,-0.272178,0.517083', '1303034', '25731059', '1482099', '1870681');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2244593', '解剖学教室', '惊悚', '医科大学新生善花（韩智敏）、启范（吴泰景）、忠石（温朱万）、京敏、志英和银珠被分到同一小组上解剖课，在解剖教室，面对来历不明的女尸，众人表现大相径庭，尤以优等生银珠和“万人迷”忠石反应最为突出，前者紧张尖叫转身离开，后者饶有兴致地拿起手机拍下尸体身上的老土纹身。银珠为战胜自己，深夜只身潜进解剖教室，被杀，当众人把怀疑的目光落在将银珠当情敌的志英身上时，志英不久也死于解剖教室，因为亲见志英的挣扎，京敏疯掉。意识到一切皆被神秘力量操纵后，善花、启范和忠石为自救，开始联手欲揭开噩梦真相。©豆瓣', '韩智敏', '孙泰雄', 5.9, 7768, 'tt1821446', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1395356855.jpg', 3.6, 20.2, 57, 15.1, 4.1, '0.384960,-0.046934,-0.498662,-0.082491,-0.036722,-0.149277,0.537287,-0.053045,-0.181918,-0.358138,0.246992,0.499343,-0.562005,0.310308,0.085531,-0.249543,-0.105611,-0.792277,-0.320033,-0.046156,-0.455012,-0.220028,0.076041,0.077675,-0.046906,-0.089865,0.567625,-0.034226,-0.409443,0.614409,0.305187,0.368533,-0.182948,0.246437,-0.004916,-0.113666,-0.268662,-0.180260,0.098698,0.078040,-0.018499,-0.419871,-0.108234,0.339103,-0.106960,0.016070,0.852916,-0.082208,0.090956,-0.275892,0.321534,-0.414767,-0.144377,0.357018,0.332503,0.165467,-0.146501,0.061883,-0.075816,0.122458,0.333506,0.073455,-0.461366,-0.054354,0.017775,0.073867,-0.441745,0.094320,-0.064194,0.237599,0.331790,-0.180932,0.226195,0.048386,0.153342,0.441346,-0.235550,0.044620,-0.308088,-0.026322,0.134981,-0.045996,0.080114,0.088115,0.163827,-0.540935,0.012403,-0.041031,0.157880,0.012059,0.364623,0.471039,0.094387,-0.002634,-0.306462,-0.391914,-0.093053,-0.089028,-0.095811,-0.375094,-0.485658,-0.416532,-0.251084,0.142681,-0.351590,-0.039541,-0.189695,-0.316316,0.303835,-0.443841,0.143146,0.124103,0.294964,-0.078205,0.382903,-0.104698,0.007537,-0.176216,-0.044404,0.241907,0.523767,0.442859,0.177281,0.183295,-0.391722,0.213687,-0.601928,0.246467', '1309194', '1307146', '3155839', '4268598');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2245683', '花美男连锁恐怖事件', '剧情', '高中校园从2月14号开始每月同一天都会有一个学校的花美男遭受神秘恐怖袭击。分别是伽蓝高中的白马王子李晟敏（李晟敏 饰），居尚高中的篮球天才韩庚（韩庚 饰），和NADAM高中BAND部的主唱艺声（艺声 饰）。3个月过去了，网上盛传下一个受害者将会出现在常青高中。常青高中学生金基范（金基范 饰）因为在博客上对这一连串花美男连续恐怖事件的推理，也变成了网络名人。常青高中有3个热门人选，分别是IQ数值与他本的身高相近，大脑就像是高配置运转的CPU，从小学开始就是全校第一的学生会长崔始源（崔始源 饰）；校服时尚旋风都从他身上开始刮起，常青高中的时尚指标。校内舞蹈部Ultra Junior队长金希澈（金希澈 饰）；创下全国竞赛决胜局开始仅1秒内就以过肩摔赢得胜利的神话记录，柔道部主将强仁（强仁 饰）。传闻激起了三个男人的好胜心，他们都暗中希望自己成为下一个受害者。这时，神秘的凶手也在暗中观察着一切的进展，事情并不像想象的那么简单......', '金起范', '李卷', 6.2, 8599, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2221614285.jpg', 5.6, 18.2, 46.9, 17.1, 12.2, '0.307270,-0.040756,-0.568725,0.576540,0.000286,0.009862,0.376356,-0.029733,-0.271698,-0.148133,0.375444,0.653253,-0.607604,0.339161,0.250920,-0.103613,-0.138047,-1.066510,-0.137199,-0.488611,-0.284324,-0.280663,-0.088589,0.126189,0.060914,-0.174628,0.560393,-0.145472,-0.163693,0.735326,0.370745,0.078161,0.193717,0.188868,-0.236569,-0.011760,0.040286,0.163429,0.156071,0.195521,-0.068337,-0.182593,-0.034187,0.007766,0.145553,0.282378,0.695260,0.039174,-0.008562,0.000071,0.672968,-0.004301,-0.288468,0.061022,0.808800,0.248742,0.264056,0.199510,0.124733,0.287523,-0.065496,-0.160889,-0.539651,-0.001072,0.095409,0.179766,-0.333042,0.720229,-0.108677,-0.154622,0.233353,-0.125781,-0.019209,0.205636,0.260154,0.329450,-0.229283,0.184097,-0.389290,0.334478,0.406663,0.017201,-0.518377,0.233566,0.017784,-0.485996,-0.392995,-0.090761,-0.147356,0.158057,0.215940,-0.162791,0.124580,0.052169,-0.456303,0.198949,0.144836,-0.214197,0.027423,-0.254653,-0.289695,-0.584760,-0.136623,-0.285078,-0.333121,0.084083,0.067095,-0.306505,0.953236,-0.920746,-0.040867,0.473682,0.207612,-0.240182,0.467567,0.125236,0.074409,-0.133145,-0.184379,-0.019919,-0.077517,0.547702,-0.168026,0.666176,-0.099328,-0.492004,-0.402043