INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22508259', '恶老板2', '喜剧', '《恶老板2》的故事紧接着第一集，Nick, Dale和Kurt这三个难兄难弟决定自己当老板，但是再次被狡猾的投资人欺骗。眼看着合同成了一纸空文，三人迫不得已决定绑架投资人的儿子，以重新夺回对公司的控制权……', '杰森·贝特曼', '西恩·安德斯', 6.2, 15998, 'tt2170439', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206929127.jpg', 3.1, 16.8, 54.1, 19.6, 6.5, '0.348757,0.123023,-0.495357,0.465555,-0.033658,-0.654920,0.433746,0.322684,-0.316526,-0.064946,0.078805,0.974162,0.021528,0.292641,0.448389,0.116933,-0.072682,-0.771257,-0.475780,-0.243803,-0.009844,-0.565580,0.036393,-0.068188,0.039762,0.063639,0.675517,-0.040900,-0.235986,0.220408,0.893336,0.073375,0.108954,0.293244,-0.002385,0.212647,0.045783,-0.149720,-0.672641,0.524369,0.223237,-0.087987,0.065363,0.276452,-0.204062,0.601246,0.684256,-0.456709,-0.527780,-0.397946,0.602660,-0.635054,-0.380041,0.174108,0.228874,0.268578,0.357537,0.271206,-0.455716,-0.354642,-0.007059,-0.180093,-0.960398,-0.100189,0.139869,-0.227129,-0.839668,0.185926,-0.031963,0.408146,0.112640,-0.307758,0.252412,0.368199,0.400258,0.538312,-0.280313,0.234059,-0.591401,-0.024324,0.538031,0.037715,-0.048753,0.307384,0.511259,-0.177252,0.045941,-0.416899,-0.324774,0.002472,0.576098,0.085025,-0.228222,-0.064167,-0.860034,-0.516630,-0.239046,-0.160998,0.290493,-0.923510,0.101375,-0.028575,-0.376583,0.001277,0.053483,0.165563,-0.034565,-0.193102,0.565511,-0.847699,-0.151069,0.613797,0.397534,-0.805678,0.481522,0.277569,0.178071,-0.625556,-0.041056,-0.513814,0.325768,0.567134,0.397850,0.118258,0.433958,-0.453581,-0.335156,0.212688', '26678784', '30345227', '1299649', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2251569', '男孩A', '剧情', '24岁的杰克（安德鲁·加菲尔德 Andrew Garfield 饰）获得假释出狱，负责接管他的特里（彼得·穆兰 Peter Mullan 饰）为他安排了新名字新房子新工作，于是他用“杰克”这个名字开始了新生活。在新的工作环境中，杰克认识了新朋友克里斯（肖恩·埃文斯 Shaun Evans 饰），也结交了一个女朋友米歇尔（凯蒂·里昂丝 Katie Lyons 饰），还在一次车祸中救了一名女孩。然而，已经改过自新的他必须向所有人隐瞒——自己曾经是个杀人犯的秘密。曾经的杰克是个受到老师家长冷落的少年，他和唯一的朋友菲利普整天厮混在一起，有一天，他们在小树林里残忍地杀害了一名少女……杰克在适应新生活的同时，往日的记忆常常一幕幕地浮现。多年前的命案引起社会的强烈关注，小报们时刻在关注这个少年杀人犯，网上也炒起了悬赏金。随后女朋友的无故失踪让他陷入不安中，曾经被称作“男孩A”的他又如何面对以后的生活……本片改编自乔纳森·特里盖尔获得多项大奖的同名小说。', '安德鲁·加菲尔德', '约翰·克劳利', 8.2, 25203, 'tt1078188', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p574349406.jpg', 0.3, 1.2, 17, 52.4, 29.1, '0.190513,-0.061795,-0.557801,0.644865,-0.369611,-0.461997,0.689301,0.068099,-0.554747,-0.338822,0.319980,0.861842,-0.183930,0.455211,0.322472,0.058241,-0.486520,-0.728431,0.015697,-0.296147,-0.320940,-0.440992,-0.320915,-0.332454,-0.074979,-0.273871,0.481885,-0.095013,-0.085851,0.314427,0.344268,0.342566,0.095549,0.372372,-0.151287,0.129343,0.396597,-0.015173,-0.170793,0.270206,0.010414,-0.197109,-0.217089,0.079293,0.193448,0.385248,0.656106,-0.144723,-0.241187,-0.070058,0.396495,0.010656,-0.006637,-0.034441,0.191563,0.044195,0.207015,0.162486,-0.250920,0.026196,-0.196554,-0.097589,-0.573756,-0.033616,0.023749,0.281163,-0.563040,0.392696,-0.163894,0.026987,0.119400,-0.264223,-0.041321,0.264342,0.244403,0.356440,-0.056417,0.203111,-0.214459,0.253449,0.664508,-0.031336,-0.264571,0.254020,-0.281435,-0.195354,-0.212571,0.116164,-0.726359,0.027823,0.378293,-0.219527,-0.273313,0.518384,-0.568698,-0.056447,-0.182751,-0.117670,0.111173,-0.169880,-0.251787,-0.642615,-0.215673,-0.197984,-0.347276,-0.248438,-0.035619,-0.344895,0.734518,-0.820610,0.367273,0.548852,0.089129,-0.475856,0.403366,0.205074,0.143554,-0.316606,-0.071342,0.217081,0.202286,0.277561,0.032469,0.186471,0.023798,-0