INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2251924', '野孩子', '剧情', '居住在加利福尼亚海滨的16岁的美丽少女波碧·摩尔（艾玛·罗伯茨 Emma Roberts 饰）家境优渥，衣食无忧。由于母亲早年去世，父亲盖瑞（艾丹·奎恩 Aidan Quinn 饰）对她纵容溺爱，致使她从小个性张扬，无法无天。某天，波碧的嚣张终于惹恼老爹，于是被送到一家英国寄宿学校学习。当然，即使到了异国他乡，波碧桀骜不驯的性格也未作改变，而她的作风自然也引起校内女生们的关注与反感，严格的校规更令她透不过气来。波碧无时无刻不想逃离这个古板沉闷的地方，不过在这段时间，她渐渐意识到自己从前行为的愚蠢，友情也慢慢来到身边……本片女主角艾玛·罗伯茨是著名女影星茱莉娅·罗伯茨的侄女。©豆瓣', '艾玛·罗伯茨', '尼克·摩尔', 7.3, 81153, 'tt1024255', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1444569569.jpg', 0.6, 4.6, 40.2, 39.5, 15.1, '0.379010,0.067614,-0.922875,0.490451,-0.420666,-0.087509,0.657893,0.234681,-0.572383,-0.212565,0.238554,0.914562,-0.023392,0.293999,0.370876,0.280674,-0.141144,-0.422226,0.045845,-0.238828,0.054077,-0.403808,-0.094317,-0.264113,-0.075353,-0.480819,0.182061,-0.133304,-0.202295,0.590192,0.255545,0.385953,0.095650,0.265466,-0.140599,-0.008135,0.138040,0.135286,0.086214,-0.100424,-0.016390,-0.116466,-0.014409,0.257198,0.253096,0.286480,0.555540,-0.153583,-0.368142,0.055994,0.487842,-0.288508,-0.204146,0.256227,0.304207,-0.327145,0.317923,0.198375,-0.157643,0.140374,-0.155370,-0.160121,-0.401349,0.247328,0.011881,-0.070716,-0.395364,0.480397,-0.036813,-0.371299,-0.091443,-0.538335,-0.097511,-0.015064,-0.030680,0.273676,-0.272178,0.266745,-0.003968,0.026156,0.617096,0.081783,-0.400225,0.225975,-0.481098,-0.132440,0.069191,-0.613009,-0.822827,-0.046102,0.084248,-0.076578,-0.229077,0.384556,-0.247574,-0.093105,-0.122166,-0.020743,0.132778,-0.314577,-0.221009,-0.409987,-0.277752,-0.642388,-0.286522,-0.155981,-0.116650,-0.238544,0.669187,-0.739803,0.345904,0.487856,0.214524,-0.721028,0.387043,0.186909,0.081240,-0.067006,-0.294023,0.651823,0.099609,0.083523,-0.246033,0.159324,-0.069807,-0.248562,-0.112186,0.500983', '1293590', '1292720', '21354767', '1293077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22519250', '爱的就是你', '爱情', '伊桑（马克·杜普拉斯 Mark Duplass 饰）和索菲（伊丽莎白·莫斯 Elisabeth Moss 饰）结婚多年，彼此之间的感情由浓转淡，最终陷入了僵局之中。为了挽回他们的婚姻，两人决定去咨询爱情专家，在爱情专家的建议下，伊桑和索菲来到了一个神秘之地度假，爱情专家告诉他们，曾经来这里度假的夫妻们最终都收获了美满的婚姻。在度假村，伊桑和索菲遇见了另一对夫妻，让两人感到震惊的是，这对夫妻的长相竟然和他们一模一样。在好奇心的驱使之下，伊桑和索菲决定留下，随着时间的推移，索菲竟然渐渐地爱上了另一个伊桑。与此同时，伊桑亦开始分辨不清，自己的妻子是否就是那个和自己同床共枕了许多年的枕边人。©豆瓣', '马克·杜普拉斯', '查理·麦克道威尔', 7.4, 14849, 'tt2756032', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2210334288.jpg', 0.6, 3.5, 35.2, 47.5, 13.2, '0.414537,-0.081934,-0.805790,0.754240,-0.137563,-0.547566,0.864264,-0.047558,-0.510600,-0.414372,-0.018547,0.913345,-0.363919,0.375310,0.359997,-0.097309,-0.442638,-0.780618,-0.066887,-0.169013,-0.280419,-0.696535,-0.262230,-0.161918,-0.038377,0.060308,0.709066,0.071337,0.107124,0.570451,0.370538,0.249310,-0.299067,0.277492,-0.090559,0.245778,0.338142,0.143812,-0.665734,0.037915,0.190846,0.021454,-0.045566,0.216863,-0.088753,0.425388,0.563063,-0.341374,-0.149914,0.175061,0.168547,-0.256530,0.067741,0.208068,0.140542,-0.165602,0.367615,0.317908,-0.425015,-0.266124,0.025812,0.122205,-0.722739,0.350957,0.101722,0.032632,-0.660716,0.601408,0.068133,-0.359922,0.122746,-0.293682,0.343866,0.687607,0.297757,0.477863,-0.232118,-0.113764,-0.369072,-0.033801,0.868994,0.175904,-0.231060,0.382356,-0.444992,-0.423458,-0.189330,-0.062083,-0.230154,-0.221406,0.310271,0.252804,-0.159262,0.251251,-0.762810,-0.074883,-0.177025,-0.033290,0.212771,-0.639678,0.058162,-0.560172,-0.347952,-0.600414,-0.372877,0.165370,0.017701,-0.346094,0.575212,-0.778258,0.059923,0.365420,0.293525,-0.720256,0.932428,0.352916,0.117843,-0.341839,-0.082850,0.333467,-0.151763,0.172610,0.295968,0.209874,0.199958,0.253155,-0.511035,0.380474', '3055049', '25721544', '4301278', '4604803');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22522269', '战斧骨', '恐怖', '美国西部某个小镇，警长富兰克林·亨特（库尔特·拉塞尔 Kurt Russell 饰）夜晚射伤了一名可疑的流浪汉，随后他请来小镇医生萨曼莎（莉莉·西蒙斯 Lili Simmons 饰）为嫌疑人治疗。夜深人静，一名马夫遭到神秘入侵者残忍杀害，而嫌疑人和萨曼莎也消失无踪。富兰 克林深感事态严重，他召集萨曼莎的丈夫亚瑟·欧·德怀尔（帕特里克·威尔森 Patrick Wilson 饰）以及其他村民们在当地酒馆开会，进而得知昨晚的事可能是一个神秘的穴居人所为。这群野蛮人近亲通婚，甚至会吃掉包括亲生母亲在内的人类。虽然凶险无比，富兰克林以及其他勇士决心勇闯穴居人的老巢，救回被绑架的村民，这次征程凶多吉少……©豆瓣', '帕特里克·威尔森', 'S·克雷格·扎勒', 7, 9067, 'tt2494362', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2265754525.jpg', 1.8, 7.4, 41.7, 37.2, 12, '0.147724,-0.232183,-0.430634,0.340711,-0.188469,-0.141685,0.797853,0.007070,-0.659779,-0.546506,0.304499,0.805062,0.246746,0.335476,0.389031,-0.062994,-0.354747,-0.380407,-0.137609,-0.192647,-0.453183,-0.354222,-0.172685,-0.720898,0.161110,-0.380079,0.170078,0.176586,-0.166904,0.481415,0.278354,0.725195,-0.328060,0.199601,-0.134775,0.072307,0.571319,-0.467063,-0.323023,0.071196,-0.374009,0.214104,-0.001395,0.205536,-0.130187,0.456456,0.491145,-0.166539,-0.116669,-0.330665,0.156008,-0.531243,0.246091,0.151935,0.602616,-0.278317,0.182124,0.262615,0.091991,-0.026447,0.048457,0.104280,-0.603701,0.060439,0.161733,0.192207,-0.389438,-0.118072,-0.022262,0.163652,0.063434,-0.192455,0.148826,0.247037,-0.007203,0.173650,0.210776,-0.024502,-0.419802,0.121776,0.680805,-0.264285,0.003644,-0.231537,-0.255335,-0.367024,0.214585,-0.143081,-0.346434,0.160149,0.442461,-0.101541,-0.001068,0.391733,-0.427859,-0.314306,-0.370876,-0.264445,-0.211149,0.040195,-0.193075,-0.780222,0.078853,-0.089682,-0.162761,-0.017584,0.061605,0.189936,0.607244,-0.497454,0.290375,0.493896,0.195064,-0.573216,0.262471,0.107819,0.247695,-0.130122,-0.224336,0.394810,0.513997,0.184879,-0.109812,0.024831,-0.038563,-0.339253,-0.189033,0.066100', '3147969', '10466639', '1292849', '1465415');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2252594', '海贼王剧场版3：珍兽岛的乔巴王国', '喜剧', '娜美偶然得到一张珍兽岛的地图，据说那里埋藏着无价的宝藏，草帽海贼团的诸位不顾乔巴的阻拦，决定向这座小岛挺进。正在此时，海底火山爆发，将黄金梅利号抛向空中。机缘巧合，他们竟然被抛到了珍兽岛。这个小岛由会说人话的动物统治，它们的老国王麒麟狮已经仙逝，偶然跌落于此的乔巴被众兽奉为新的国王。乔巴拗不过众兽，权且任职。正当珍兽岛为新国王的诞生欢欣鼓舞之时，贪婪邪恶的巴特拉伯爵及其爪牙登陆小岛。为了传说中的“国王宝藏”，他不惜对岛上的动物大开杀戒。他们也势必和草帽海贼团发生冲突……本片根据日本漫画家尾田荣一郎的同名原著改编，是2002年上映的第三部动画剧场版。©豆瓣', '田中真弓', 'Atsuji Shimizu', 7.8, 10515, 'tt0997084', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2300514704.jpg', 0.5, 2.6, 29.2, 42.7, 25, '0.097874,0.193172,-0.748897,0.814289,0.297074,0.063197,0.510944,-0.076646,-0.169040,0.026823,0.358761,0.833868,-0.140609,0.268677,0.280664,0.344717,-0.391940,-0.322738,-0.216303,-0.138131,-0.170180,-0.092123,-0.528979,-0.180939,-0.380081,-0.309458,0.832038,0.130221,-0.086953,0.390380,0.362286,0.436642,-0.278252,0.183804,-0.345362,0.048428,-0.011318,-0.092783,-0.157177,0.203795,-0.376765,0.006372,-0.029635,0.156327,0.119252,0.247753,0.794470,-0.622828,0.001458,-0.415168,0.262214,-0.401095,0.287241,0.037357,0.716310,-0.179585,-0.072261,0.148236,-0.140689,-0.139910,0.050076,-0.166019,-0.543340,-0.078928,0.041986,0.118205,-0.278771,0.162240,-0.033121,0.160603,0.163996,-0.184628,0.263186,0.328915,0.208883,0.086705,0.047150,0.082821,-0.415243,0.162233,0.336548,-0.075560,-0.039393,-0.091102,0.232255,-0.669877,0.033618,-0.179921,-0.057314,-0.071442,0.550686,-0.008957,-0.086685,0.302572,-0.953283,-0.170792,-0.426140,-0.495899,0.213032,-0.375350,-0.388376,-0.591236,0.103410,-0.029315,0.272794,-0.125676,0.293022,-0.053583,0.681829,-0.460460,0.258419,0.557631,0.211328,-0.345321,0.607952,-0.135747,-0.073433,-0.282721,-0.341514,0.305223,0.388054,0.545545,0.112036,0.015221,0.239970,-0.313673,-0.507417,0.401632', '26290398', '24879819', '1856675', '1294917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2252771', '继父', '悬疑', '在名叫波特兰的小镇，单身母亲苏珊·哈丁（雪拉·渥德 Sela Ward 饰）和一双儿女肖恩（Braeden Lemasters 饰）、贝丝（Skyler Samuels 饰）共同生活在一起，其长子迈克尔（佩恩·拜德格雷 Penn Badgley 饰）则在外地的军校求学。某日，苏珊在超市遇见了名叫大卫·哈里斯（迪伦·沃尔什 Dylan Walsh 饰）的单身男子。大卫举止得当、言语风趣，俨然一个完美的居家好男人。两人相见恨晚，只有半年便到了谈婚论家的地步。哈丁一家对大卫颇为满意，独有迈克尔似乎心存顾忌。他的顾忌不是没有道理。经过一段时间相处，迈克尔发现大卫温柔开朗的外表背后似乎隐藏着黑暗恐怖的一面，他试着调查大卫的一切，然而这也许为时已晚……©豆瓣', '迪伦·沃尔什', '尼尔森·麦科米克', 5.8, 6567, 'tt0814335', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1419613038.jpg', 4.2, 21.9, 55.2, 14.6, 4, '0.352421,-0.065079,-0.735802,0.448814,-0.357259,-0.258672,0.758110,0.396779,-0.617781,-0.439414,0.315939,0.487827,-0.263833,0.111168,0.219637,0.089614,-0.277181,-0.383062,-0.021699,-0.061505,-0.067508,-0.671963,-0.304061,-0.100463,-0.086057,-0.492741,0.253160,-0.156590,0.101674,0.608899,0.072915,0.412563,0.042742,0.362613,-0.305725,-0.025180,0.333359,0.030450,-0.427578,0.038003,0.033074,0.126674,-0.362221,0.195511,-0.069388,0.488497,0.600625,-0.040050,-0.246721,0.308404,0.295789,0.224299,0.033810,0.159427,0.313761,-0.207796,0.141525,0.238714,-0.091714,-0.228846,0.090072,-0.071330,-0.308944,0.135491,0.033069,0.250254,-0.356033,0.522264,-0.293553,-0.224539,0.149065,-0.306805,-0.191940,-0.029798,0.137727,0.176702,0.260488,0.243976,-0.448661,0.085081,0.464471,0.126125,-0.353189,0.365317,-0.277924,-0.366456,-0.218005,-0.056897,-0.640053,-0.079385,0.278375,-0.093911,-0.148097,0.153066,-0.389588,0.058226,-0.238346,0.156574,0.073178,-0.320999,-0.100110,-0.763720,-0.193868,-0.698285,-0.414740,-0.044503,-0.102727,-0.033009,0.450261,-0.791148,0.240087,0.353698,0.110508,-0.118569,0.645954,0.063283,0.226932,-0.367277,-0.267745,0.525529,0.026310,-0.207913,0.233819,0.501548,-0.063809,0.016099,-0.454600,0.618430', '1309172', '24639908', '1304989', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2252773', '末日危途', '剧情', '绝望的未来，世界恍如巨大的废墟，双眼所及之处尽是荒凉与灰暗。人类文明在末日的劫难中毁灭殆尽，在资源极度短缺的情况下，幸存者无所不用其极，甚至出现人吃人的惨烈情况，整个世界呈现地狱般的光景。一位父亲（Viggo Mortensen 饰）和他的儿子（Kodi Smit-McPhee 饰）进行着漫无止境的旅程。他们不断向南，寻找着更为温暖的避难场所，破旧的超市小推车负载着父子二人所有的家当。前路漫漫，希望渺茫，父亲不断回忆着妻子（查理兹·塞隆 Charlize Theron 饰）的音容笑貌和他们过去美好的时光，而如今美好不在，父子俩的明天更不知将在何方……本片根据美国小说家考麦克·麦卡锡（Cormac McCarthy）的作品改编。©豆瓣', '维果·莫腾森', '约翰·希尔寇特', 7.7, 42212, 'tt0898367', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2677701815.jpg', 0.8, 3.9, 26.9, 46.4, 22, '-0.096478,0.201514,-0.947028,0.667414,0.311927,-0.004792,1.015184,0.103903,-0.403964,-0.096612,0.290743,0.540717,0.030895,0.452820,0.211024,-0.081259,-0.453002,-0.589416,-0.359097,-0.186176,-0.343662,-0.433651,-0.556809,-0.104914,0.061001,-0.335169,0.670974,0.498546,-0.020039,0.198936,-0.007152,0.244975,-0.451265,0.490737,-0.379781,-0.216067,-0.063676,0.175860,-0.562046,-0.042625,0.014138,-0.254217,-0.352356,0.111893,-0.382454,-0.044036,0.999729,-0.455754,-0.168708,-0.009999,0.442812,-0.315442,-0.080592,0.231394,0.037179,-0.056410,0.139818,0.161975,-0.101350,-0.004516,0.221710,-0.278262,-0.815429,-0.116554,0.070906,0.465106,-0.528107,0.464407,0.015308,-0.141771,0.264053,-0.461073,0.352726,0.181926,0.227019,0.535472,-0.384853,-0.201069,-0.517648,0.426216,0.624921,0.066948,-0.403510,0.267373,-0.436861,-0.125483,-0.193053,-0.045304,-0.884874,-0.070689,0.436635,0.071362,-0.165726,0.803784,-0.697436,0.189687,-0.048111,-0.587569,-0.187411,-0.343691,-0.368476,-0.572319,-0.265195,-0.319328,-0.271669,0.099344,0.113868,-0.251032,0.776893,-0.462922,0.177949,0.477658,0.075034,-0.096047,0.688688,-0.211825,0.217756,-0.154820,-0.112143,0.313209,-0.059753,0.410167,0.224029,0.232728,-0.293421,0.330061,-0.545484,0.837317', '21619567', '3097044', '1305666', '10533913');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2252775', '太平间闹鬼事件', '剧情', '人过中年的莎拉•坎贝尔（Virginia Madsen 弗吉尼娅•曼德森 饰）生活幸福美满，丈夫皮特（Martin Donovan 饰）工作努力，三个孩子聪明可爱。然而一场灾难突然降临，他们的儿子迈特（Kyle Gallner 饰）患有癌症。夫妇俩想尽一切办法，只求爱子能逃离死神的魔掌。在得知康涅狄格州绍辛顿拥有治疗癌症的有效方法时，他们不惜将全家搬到当地。但似乎厄运反而变本加厉。自从搬进这所房子后，迈特和两个弟妹就经常看到恐怖的幻象。随着灵异事件不断发生，莎拉终于了解到，他们所居住的房子曾经是一个停尸房……本片根据真实事件改编。©豆瓣', '维吉妮娅·马德森', '彼特·康威尔', 6.9, 26597, 'tt0492044', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1675785269.jpg', 0.9, 6.6, 47.5, 35.2, 9.7, '-0.116525,-0.114918,-0.494508,0.238101,-0.149646,-0.101056,0.659063,-0.033798,-0.502134,-0.545955,0.336788,0.613449,0.055177,0.294110,0.159472,0.033496,-0.270959,-0.455386,0.180279,0.064782,-0.459925,-0.303546,-0.344931,-0.542311,0.024601,-0.569023,0.184312,0.100847,0.038438,0.265391,0.115438,0.638199,-0.540200,0.103639,-0.246214,-0.002298,0.095983,0.218271,-0.596717,0.277061,0.013688,-0.152428,-0.124123,0.076351,0.089499,0.042707,0.738326,-0.310642,-0.437720,0.004871,0.525800,-0.154079,-0.351708,0.504223,0.277114,-0.000803,0.392304,0.022782,-0.304687,-0.049226,-0.002888,-0.272230,-0.658014,-0.073276,0.126255,-0.031036,-0.400305,-0.016329,0.024413,-0.184266,0.294599,-0.339338,0.157988,0.312295,0.226416,0.567071,-0.410705,0.092319,-0.437820,0.094150,0.747818,-0.361799,-0.375704,0.463418,-0.090115,-0.184456,-0.057044,-0.261730,-0.300406,0.521449,0.298914,0.148938,-0.279821,0.315028,-0.310721,-0.297490,-0.515040,-0.318651,0.150297,-0.101649,-0.057585,-0.625644,-0.222923,-0.116413,-0.112340,0.015829,0.001094,-0.327199,0.604646,-0.575728,0.454418,0.532428,0.068442,-0.674356,0.168698,-0.113447,0.351935,-0.259061,-0.022812,0.245193,0.134176,0.281484,0.029952,0.315012,-0.041086,-0.055752,-0.250637,0.489261', '26678784', '20470260', '1303184', '2988294');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2252778', '夜魔', '惊悚', '拥有犯罪前科的男子阿金（乔什·斯图尔特 Josh Stewart 饰）靠着一份除虫的工作养家糊口，但是这点稀薄的工资对于巨额放贷以及等着吃饭的老婆孩子来说无异于杯水车薪。万般无奈之下，他打起雇主——珠宝商人迈克·切斯（Michael Reilly Burke 饰）的主意 。适逢切斯一家外出度假，阿金找到当年的好友罗伊（罗伯特·维斯登 Robert Wisdom 饰），他准备从切斯家偷出珠宝并拜托罗伊销赃。入夜，阿金潜入切斯家空空荡荡的房子里。但他的运气实在太差了，他发现已经有人先行来到这里。那个自称“收藏家”的神秘男子似乎目标并不在钱财，而是人命。阿金想要知难而退，结果发现自己被困在了这所地狱一般的房子中……©豆瓣', '玛德琳·奇玛', '马库斯·邓斯坦', 7.3, 36139, 'tt0844479', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2213045200.jpg', 1.3, 5.4, 35.4, 41.7, 16.2, '0.418139,-0.011378,-0.497128,0.264462,-0.424965,-0.603903,0.605033,0.307096,-0.711981,-0.502817,0.199952,0.650758,0.340366,-0.000517,0.166874,0.189723,-0.469399,-0.131293,0.205312,-0.407852,0.008384,-0.588345,-0.211606,-0.042567,-0.172646,-0.158723,0.301797,-0.060155,0.114054,0.324094,0.176690,0.222159,0.093761,0.289584,0.007990,-0.069483,0.169952,0.017168,-0.223271,0.451155,-0.054579,0.109993,-0.102828,0.111911,0.293815,0.443303,0.333153,-0.258956,-0.248494,-0.028479,0.137893,-0.095403,-0.016694,0.167722,0.183665,-0.197170,0.300249,0.018345,-0.355976,0.057753,0.267379,-0.024001,-0.556444,0.115715,0.166910,0.040718,-0.548703,0.336128,-0.104370,-0.088318,-0.250349,-0.431616,0.098849,0.256106,-0.003848,0.250836,-0.339290,-0.042121,-0.725707,-0.040723,0.332524,-0.064052,0.040652,0.373297,-0.163929,-0.251731,0.125213,0.056052,-0.470004,-0.109052,0.231536,0.086936,-0.117097,-0.065573,-0.688354,0.171319,-0.183889,-0.142650,-0.305564,-0.258892,-0.140263,-0.594542,-0.028236,0.037641,-0.288348,0.106511,0.295642,-0.181476,0.196237,-0.515926,0.128447,0.607414,0.377177,-0.143719,0.433715,-0.360454,0.179944,-0.141740,-0.616369,0.216714,0.231440,0.417676,0.021332,0.090671,0.095262,-0.489412,-0.150639,0.509605', '4944008', '1297659', '1309101', '26678509');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2253586', '本X', '剧情', '本X是本（格雷格·提姆曼斯 Greg Timmermans 饰）在游戏《霸王》里的名字，游戏里他技压群雄、所向披靡。然而现实中的本却是一个患有自闭症的少年，沉默寡言的他在同学们眼中犹如异类并且受尽那帮同学的欺负和侮辱。本时常幻想着自己就是游戏里面的勇士，可是现实的残酷却将一切幻想纷纷击碎。本游走于现实和游戏的之间，两者的界限逐渐模糊起来。本在游戏中结识一个叫斯嘉莱（劳拉·沃林登 Laura Verlinden 饰）的女孩，女孩用她的真诚和勇气鼓舞着本重拾自我，最终在本的臆想中女孩陪伴他走上了一条“置之死地而后生”的道路……在2007年的第31届蒙特利尔电影节上，本片获得了美洲大奖以及评审团和观众的最高奖。©豆瓣', '格雷格·提姆曼斯', '尼克·巴斯阿扎', 8, 11705, 'tt0953318', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1751771543.jpg', 0.5, 2.7, 20.5, 47.2, 29.2, '0.294709,0.329446,-0.643084,0.738764,-0.175321,-0.091090,0.684485,-0.073371,-0.447602,0.101035,0.132652,0.956125,-0.326942,0.345600,0.484060,-0.115135,-0.414017,-0.877298,-0.523140,-0.225488,-0.063517,-0.567454,-0.632138,-0.168541,-0.138676,-0.430141,0.674499,0.023714,-0.446534,0.499686,0.360053,0.180913,-0.079163,0.373083,-0.206394,-0.105780,0.009857,0.238181,-0.140486,0.080965,-0.233423,-0.481880,-0.323952,0.059251,-0.112315,0.294487,0.783032,-0.815593,0.077387,-0.027838,0.340981,-0.206460,-0.349529,-0.046072,-0.308983,-0.105836,0.377020,0.104456,0.078460,0.213440,0.150441,-0.389188,-0.711762,-0.325224,-0.092850,0.143839,-0.372763,0.633540,0.110653,0.077983,0.158821,-0.144005,0.047950,-0.180819,0.247527,0.284449,-0.373641,-0.092336,-0.511293,0.370686,0.534674,0.219638,-0.527638,0.195522,-0.302511,-0.436204,-0.353344,-0.229789,-0.705416,-0.209582,0.400436,-0.054722,-0.486723,0.394998,-0.846529,0.203372,0.051786,-0.293325,-0.260521,-0.318614,-0.149597,-0.523403,-0.098863,-0.472980,-0.295122,-0.075636,0.095336,-0.361827,1.101728,-0.970443,0.387975,0.319371,0.077184,-0.314926,0.778505,0.368428,0.228289,0.017897,-0.446336,0.129413,-0.038896,0.294012,0.080717,0.485124,-0.385497,0.139115,-0.708667,0.843574', '1870681', '3811356', '27602116', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2255476', '两个情人', '剧情', '理纳德（杰昆•菲尼克斯 Joaquin Phoenix 饰）因病理原因被未婚妻抛弃后长时间无法解脱，居住在纽约父母公寓中的他曾多次尝试自杀。理纳德的父母正考虑与好友科恩一家搞干洗店联营，科恩家的大女儿姗德拉（凡妮莎•肖 Vinessa Shaw 饰）爱上了理纳德，但理纳德却爱上了偶遇的金发邻居蜜雪儿（格温妮丝•帕特洛 Gwyneth Paltrow 饰），然而不幸的是，蜜雪儿正与一位有妇之夫的律师罗纳德（伊莱亚斯•科泰斯 Elia Koteas 饰）陷入婚外恋。理纳德在爱情的煎熬中痛苦不堪，曙光与黑夜交替出现，让他无所适从。本片是导演詹姆斯•格雷即“纽约三部曲”后的第四部作品，也是金球影帝杰昆•菲尼克斯的息影之作。©豆瓣', '华金·菲尼克斯', '詹姆斯·格雷', 7, 9286, 'tt1103275', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1579295923.jpg', 1.2, 6.9, 44.9, 36.7, 10.4, '0.226184,-0.017941,-0.605132,0.268176,0.136387,-0.481951,0.765144,0.332434,-0.578935,-0.222904,0.205301,0.857370,-0.262061,0.408973,0.316401,0.473898,-0.366863,-0.686818,0.045966,0.058279,-0.066346,-0.528698,-0.204304,-0.021836,0.000863,-0.230427,0.528539,-0.088072,0.020450,0.358445,0.472454,0.595974,-0.003887,0.309937,0.211633,0.227494,0.460089,-0.027412,-0.369456,0.269780,0.162883,-0.071777,-0.221699,0.172216,0.189909,0.278359,0.534283,0.000956,0.176903,-0.095956,0.249673,-0.040352,0.027771,0.167643,0.125970,-0.190011,0.319957,0.181402,-0.144024,-0.116255,0.143034,0.053391,-0.693212,0.127949,0.087755,0.242179,-0.495681,0.476441,-0.306631,-0.057277,0.111934,-0.265981,0.279592,0.099507,0.430422,0.318995,-0.209714,-0.125876,-0.294450,0.292415,0.454171,0.148454,-0.278204,0.356935,-0.405916,-0.229191,-0.133173,0.029374,-0.829948,-0.159913,0.427960,-0.002816,-0.125161,0.461912,-0.452759,-0.216811,-0.550784,0.071200,-0.088071,-0.170610,-0.148263,-0.487200,-0.101120,-0.353623,-0.327224,-0.145657,-0.063475,-0.193084,0.333159,-0.698045,0.341841,0.304328,0.218184,-0.156053,0.855717,0.215599,0.184586,-0.129184,0.030699,0.584551,-0.063174,-0.068876,0.079502,0.156927,0.123428,-0.097175,-0.519516,0.452915', '1298095', '26809592', '1302384', '1945337');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22555690', '冲锋战警', '动作', '香港九龙城警署车队队长林国权（任达华 饰）是一个兢兢业业、貌不惊人的大叔，但每当在街头巷尾遇到突发情况时，权哥便会一显身手，降服逞凶斗狠的恶徒。原来权哥当初曾是刑侦科的一名优秀干警，但为了照顾智障生活不能自理的儿子小忠，于是主动选择退居幕后，过期平凡单调的生活。日常权哥上班时，多将儿子交给美丽女孩连翠欣（牛萌萌 饰）照顾。但由于经常遇到突发事件，所以令翠欣和女友周江汉（李璨琛 饰）的关系颇为紧张。权哥和当年刑侦队的哥们骆华威（林雪 饰）、徒弟吕侨美（王子义 饰）在各种险恶境况下出生入死，体内的一腔热血蠢蠢欲动，他时刻感受到正义的召唤……©豆瓣', '任达华', '罗守耀', 4.2, 4388, 'tt3504158', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2156476151.jpg', 28.8, 39.1, 25.4, 4.7, 2, '0.087184,-0.161583,-0.275505,0.324348,-0.303056,-0.191043,0.328322,0.219948,-0.733951,-0.629589,0.030032,0.478265,-0.048671,0.372156,0.314324,-0.159317,0.035797,-0.468426,-0.068047,0.247742,-0.207573,-0.335845,-0.089319,-0.216012,-0.151902,-0.253511,0.478317,0.143419,-0.085914,0.425819,0.261602,0.273454,-0.352164,0.426174,-0.207439,-0.301055,0.090128,0.138703,-0.449230,-0.043494,0.171755,-0.078833,-0.068742,0.005510,0.426605,0.087921,0.591117,-0.005055,-0.419741,-0.103911,0.468098,-0.010301,0.048744,-0.157435,0.358230,-0.010007,0.175134,0.083017,-0.021700,0.059625,0.045490,-0.268937,-0.468695,-0.001350,0.157982,-0.042493,-0.557199,0.081260,0.050477,0.064771,0.153268,-0.212679,0.333156,0.289221,0.265044,0.187657,-0.020233,0.070096,-0.277630,0.222017,0.734369,0.101813,-0.089347,0.162777,-0.316708,-0.342682,0.017944,-0.360137,-0.566055,0.137241,-0.150769,-0.125725,-0.212926,0.026206,-0.203414,-0.062965,-0.034503,0.275830,0.019420,-0.189461,-0.051698,-0.294556,0.049139,-0.465021,-0.288912,0.201712,-0.014802,-0.271704,0.662671,-0.931170,0.028735,0.387161,0.163266,-0.685994,0.523860,0.202634,0.105825,-0.258105,-0.066666,0.148528,0.266040,-0.030936,0.065848,0.201359,-0.415526,-0.233532,0.089802,0.111176', '35030151', '3445516', '1293265', '1877596');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22556810', '猛龙特囧', '喜剧', '富二代李望峰（邹文正 饰）被卷入了一起交通肇事顶包案之中，作为唯一的目击证人，孟子良（胡耀辉 饰）在此事上却支支吾吾语焉不详。刘梦龙（郑中基 饰）是负责调查此案的卧底探员，而孟子良恰巧正是他的童年玩伴。借着这特殊的身份，刘梦龙开始接近孟子良，希望能够从他口中套出当日事件的真相。孟子良的妹妹孟子君（雨侨 饰）患有眼疾，视力随着时间流逝渐渐减退，对哥哥感情十分深厚的孟子君只有一个愿望，那就是能在完全失明之前看到想要成为明星的哥哥完成他的梦想，为此，孟子良参加了选秀节目《中国好男儿》，希望这个节目能够给自己带来一丝机遇，殊不知自己已经被卷入了他人精心策划的阴谋之中。©豆瓣', '胡耀辉', '胡耀辉', 4.5, 3435, 'tt4410798', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2274973501.jpg', 25.3, 38, 28.1, 4.8, 3.7, '0.009450,0.205623,-0.366147,0.549430,0.043735,-0.033636,0.524268,0.125411,-0.811715,-0.465963,0.032801,0.408071,-0.085211,0.406404,0.327761,-0.200072,-0.105688,-0.702494,-0.023167,-0.075345,-0.244912,-0.532704,-0.172049,-0.117134,-0.373515,-0.152702,0.866678,0.269463,-0.231461,0.174893,0.456131,0.277903,-0.055695,0.349217,-0.134271,-0.019019,-0.130612,0.081985,-0.324922,0.304803,0.172975,-0.235398,-0.143776,0.190068,-0.174715,0.391693,0.585453,-0.142387,-0.178612,-0.210610,0.586720,-0.315184,0.102391,0.141300,0.087868,0.235224,0.423957,0.300077,0.015363,-0.046510,-0.119515,-0.141499,-0.770916,-0.057782,0.178079,0.237315,-0.323667,0.278703,-0.149825,-0.215824,0.187829,-0.021484,0.342085,0.411592,0.185025,0.183244,-0.466927,0.120322,-0.246987,0.370431,0.349133,-0.147809,0.064206,0.490372,-0.280904,-0.363263,0.110250,-0.132323,-0.058962,0.241801,0.390619,0.170705,-0.163141,0.366009,-0.090646,-0.126021,-0.102491,0.070363,0.150415,-0.252373,0.054917,-0.202857,-0.058279,-0.277351,-0.283870,0.247268,0.065416,-0.648406,0.556237,-0.866408,-0.064387,0.503662,0.231286,-0.338334,0.497392,0.057811,-0.018757,-0.312623,0.045024,0.073619,0.022918,0.112493,-0.040270,0.358526,0.258967,-0.343941,-0.298121,0.391983', '25880986', '26759820', '30345227', '26834930');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22557335', '降魔传', '喜剧', '南宋建炎年间，少主即位，国师专权。是时镇世封印被解，各路妖魔纵横世间，遂令杭州城人心惶惶。适值此时，玄光寺的不通和尚（郑恺 饰）和女降魔师菁菁（张雨绮 饰）在一次降魔行动中相遇。一千年前，不通和菁菁是天界的金童玉女，两人因违犯天条相恋而被贬下凡间，被罚轮回十世而不得说一句话。下凡之前，菁菁决意不饮忘情水，所以积累了千年的记忆，她时刻渴望重逢金童，再续前缘。另一方面，当年被金童和佛祖所降伏的毒龙重现世间，他正阴谋加害当今皇帝，篡夺社稷。金童玉女重逢之路还有无数的磨难，他们的缘分今生能否有一个圆满结局？©豆瓣', '郑恺', '王晶', 2.9, 17059, 'tt7618430', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2503850915.jpg', 68, 22.9, 8, 0.7, 0.5, '0.020143,0.268101,-0.508514,0.551782,0.180416,-0.038599,0.508685,0.033476,-0.713286,-0.036468,0.175888,0.573329,-0.372941,0.115321,-0.039504,-0.003112,0.157445,-0.503147,0.341815,-0.248426,0.110049,-0.120165,-0.260073,0.431205,-0.347223,-0.383221,0.582807,0.270268,0.133605,0.277725,0.104570,0.192222,-0.294864,0.308485,-0.211288,0.120734,-0.199184,0.334211,-0.399303,0.003361,-0.193401,-0.394719,-0.293466,0.186719,-0.423670,0.057778,0.167458,-0.563020,-0.073106,-0.495755,0.431851,-0.239811,-0.248523,0.215005,0.292807,0.164898,0.419106,0.763007,-0.020363,-0.196375,-0.098752,0.096499,-0.408228,-0.105966,0.093040,0.006201,-0.188427,0.413483,-0.010656,0.024627,-0.069476,-0.241624,0.343194,0.403754,0.546999,0.205749,-0.253231,-0.409572,-0.590545,0.336189,0.877989,-0.226971,-0.016321,0.315833,0.310343,-0.320829,0.091715,-0.175872,-0.285904,0.266422,0.129986,-0.216317,0.118850,0.605546,-0.326301,-0.181521,-0.535143,0.398241,-0.010702,-0.181966,-0.080736,-0.109827,-0.199702,-0.359046,-0.438076,-0.037881,0.518641,-0.184534,0.735061,-0.564055,0.143177,0.337078,0.220976,-0.507212,0.818178,0.272748,0.277454,-0.140060,-0.037263,0.444688,-0.254459,0.495243,0.006553,0.074987,0.049890,0.447212,-0.432949,0.150440', '25721544', '34779692', '1308086', '1307023');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2255841', '死亡录像', '恐怖', '女记者安吉拉（Manuela Velasco 饰）和摄影师帕布罗（Pablo Rosso 饰）计划拍一部描写消防员工作的纪录片。接到报警电话后，他们随消防队来到一幢老式的公寓。公寓内似乎有某种致命的病毒在蔓延，感染者莫不心性癫狂，嗜血如命。住户被紧急疏散，死亡人数则不断增加。原本以为是一次平常的采访，却没想到通过摄像机拍下了真实而恐怖的场景……本片荣获2008年阿姆斯特丹奇幻电影节Silver Scream奖、2008葡萄牙奇幻国际电影节最佳影片和观众票选奖、2008西班牙戈雅奖最佳编剧和最佳新人女主角等多个电影节奖项。©豆瓣', '曼努埃拉·贝拉斯科', '豪梅·巴拉格罗', 7.6, 76041, 'tt1038988', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2490592235.jpg', 1.1, 4.4, 28.2, 45.5, 20.9, '-0.177294,-0.012079,-0.464494,0.551225,0.379021,0.326619,0.622767,0.068316,-0.349376,-0.090177,0.255749,0.823271,-0.740668,-0.088017,0.361195,-0.416390,-0.530018,-0.543180,-0.389460,-0.031349,-0.150768,-0.185463,-0.405281,-0.050399,0.093789,-0.290618,0.579581,0.105586,-0.164445,0.566028,0.531146,0.235187,-0.280846,0.129962,0.104694,-0.072453,0.452198,-0.084334,-0.329737,0.477415,0.118727,-0.225771,-0.173407,0.019004,0.210215,0.139620,0.714977,-0.097349,-0.142682,0.174962,0.640107,-0.405099,-0.106988,0.003942,0.304158,0.138354,0.481905,-0.130143,-0.199254,0.261483,0.006268,-0.233313,-0.603991,0.236139,0.044315,0.008305,-0.094868,0.249402,-0.380306,0.260740,-0.016783,0.002147,0.279722,0.048454,0.398829,0.192851,0.177434,-0.061822,-0.144321,0.478244,0.307343,-0.048341,-0.372290,0.251437,-0.258811,-0.590113,-0.187046,-0.086167,-0.346851,0.216939,0.517682,-0.092976,0.102131,-0.133087,-0.342437,-0.046352,-0.113328,-0.535263,-0.168081,-0.108257,-0.342186,-1.231268,0.026503,0.261688,0.057749,-0.073690,0.130158,0.029690,0.728096,-0.541739,0.254829,0.390761,0.198193,-0.346002,0.658196,-0.236017,-0.215982,-0.193429,-0.253043,0.097556,-0.099877,0.271671,-0.114587,0.235597,-0.356846,-0.546336,-0.337676,0.442654', '34961898', '24751811', '3003137', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2255999', '神枪手与智多星', '喜剧', '黑帮老大“校长”想金盆洗手，却被女友小嫂和手下阿一( 吴庆哲 饰)出卖，并遭到追杀。“校长”将自己瑞士银行的密码告诉了孙女小雨，并给了她两张半截的美钞，声称关键时刻寄出，能得到江湖传奇人物神枪手和智多星的保护。 阿一为了获得“校长”的巨款与境外的老大钟胜一（曾志伟 饰）合作，杀死了“校长”，并四处寻找小雨的下落；警方派出了菜鸟警官王小飞（方力申 饰）保护小雨，小雨也寄出了求救信。于是，智多星（黄秋生 饰）和神枪手（吴镇宇 饰） 重出江湖，他们除了要和阿一斗智斗勇之外，还要时时警惕来自身边的危险……©豆瓣', '吴镇宇', '姜国民', 5.6, 6629, 'tt1332723', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2478080303.jpg', 8.5, 22.6, 51.3, 13.1, 4.5, '0.242342,-0.241948,-0.245288,0.405884,0.012317,-0.388920,0.319333,0.110005,-0.469620,-0.239288,0.197343,0.666260,0.024419,-0.054040,0.082071,0.095417,-0.186546,-0.721651,-0.040759,-0.136628,-0.111514,-0.583778,-0.240570,0.124068,0.017703,-0.137674,0.326915,-0.203247,-0.141320,0.849700,0.387623,-0.010976,-0.190040,0.384682,-0.068494,0.028497,0.101810,-0.200946,-0.407249,0.300108,0.186604,-0.000644,-0.002123,0.225809,0.201406,0.395065,0.345434,-0.157719,-0.033936,-0.030916,-0.131420,-0.453522,0.084465,-0.023768,0.296807,0.007174,0.402194,0.428385,-0.009925,0.099547,0.132766,-0.026453,-0.772654,0.078195,0.222481,0.113072,-0.458466,0.193200,-0.313959,0.185789,0.216615,-0.274842,0.348615,0.252450,0.015832,0.203268,-0.314406,-0.062866,-0.392394,0.283636,0.123070,-0.290061,0.402607,-0.041897,0.162487,-0.251164,0.069584,-0.109770,-0.414118,0.350405,0.432905,0.043957,-0.195006,-0.097476,-0.685364,0.057405,-0.253854,0.045816,-0.166348,-0.582413,-0.030573,-0.358038,-0.175200,-0.102158,-0.229434,0.015804,0.207338,-0.129266,0.753458,-0.718919,-0.019007,0.392650,0.507647,-0.454935,0.393174,0.310695,-0.103840,-0.146272,-0.224822,-0.373319,0.366465,0.763760,0.167225,0.029846,0.133205,-0.530552,-0.009926,-0.222370', '4127270', '1462467', '3044878', '1467748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2256034', '豚鼠特攻队', '动作', '科学家本（Zach Galifianakis 饰）隶属于美国政府某个秘密部门，它通过高科技手段训练豚鼠说话与思考，并将它们培养成特工人员。然而，本的部门却面临被FBI关闭的局面，为了证明他和豚鼠特工的能力，本向豚鼠特工队的负责鼠达尔文（山姆·洛克威尔 Sam Rockwell 配音）下令，要它们潜入赛博林工业的CEO罗纳德·赛博（Bill Nighy 饰）的办公室，寻找罗纳德向中东国家出卖可用于军事的高科技芯片的证据。达尔文毫不怠慢，带着布拉斯特（崔西·摩根 Tracy Morgan 配音）、华蕾斯（佩内洛普·克鲁兹 Penélope Cruz 配音）、苍蝇莫奇和斯贝克斯（尼古拉斯·凯奇 Nicolas Cage 配音）等成员迅速展开行动。这群豚鼠特工队员体型虽小，却身怀绝技，它们成功闯入罗纳德的办公室，并下载到重要资料。然而，这场冒险才刚刚开始……', '比尔·奈伊', '霍伊特·耶特曼', 6.9, 56602, 'tt0436339', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2250468443.jpg', 0.7, 5.7, 49.5, 34.8, 9.3, '0.372956,-0.080436,-0.548556,0.528708,-0.032889,-0.126610,0.314697,-0.190551,-0.485815,-0.373383,0.112637,0.555357,0.144204,-0.403001,0.157535,-0.134818,-0.662795,-0.494540,-0.100448,0.018474,0.036228,-0.375543,-0.132335,-0.582731,-0.064067,-0.319239,0.737543,-0.167443,-0.326543,0.260955,0.082875,0.387370,-0.256136,0.180809,0.592449,-0.363463,0.544953,-0.472664,-0.180985,0.285878,0.041877,0.025423,-0.156163,0.144866,0.217303,0.243838,0.431408,-0.449068,0.010443,-0.330453,0.049312,-0.480888,0.082995,-0.034961,0.350883,0.048400,-0.188951,0.108460,0.080707,0.424958,0.014635,-0.331972,-0.810282,-0.327851,-0.172271,0.425976,-0.075762,-0.076135,-0.465528,0.395143,0.046866,-0.385214,-0.099586,0.116265,0.222062,0.165784,-0.065010,0.255586,-0.388479,-0.180110,-0.027791,-0.077703,-0.341756,-0.021990,-0.142576,-0.810462,-0.078894,-0.284303,-0.127031,-0.210223,0.429286,0.232621,-0.170804,0.103761,-0.760852,-0.072193,-0.212495,-0.473808,-0.207659,-0.336536,0.208607,-1.104014,0.076285,-0.134368,-0.173601,0.129879,0.277967,-0.316848,0.485478,-0.679849,-0.070940,0.526133,0.127071,-0.394090,0.133331,-0.156617,0.267754,-0.300628,-0.282036,0.184665,0.531038,0.530280,0.082833,0.170343,0.254780,-0.548031,-0.296441,-0.029885', '2369613', '2028645', '1306809', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2257094', '死神剧场版：无人的回忆', '动作', '宁静祥和的空座镇迎来金黄色的秋天，黑崎一护（森田成一 配音）和朽木露琪亚（折笠富美子 配音）刚刚处理完虚作乱的事件，镇车站旁便出现成群的欠魂。它们四处游走，任何驱逐方法都失去效力。正当他们一筹莫展之时，持有斩魂刀“弥勒丸”的死神少女茜雫突然出现，并成功驱散欠魂。露琪亚对一连串的事件颇感不安，于是回到尸魂界调查。从护廷十三队的口中，一护得知现世和尸魂界中间的断界出现新的空间，并且不断膨胀，导致现世与尸魂界相通。这一切并非自然形成，似乎有人正暗中操纵着一切，而茜雫正是这起事件的关键……本片根据日本漫画家久保带人的同名原著改编，系该动画的第一部剧场版。©豆瓣', '森田成一', '阿部记之', 7.1, 6492, 'tt1105263', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2226378048.jpg', 1, 7, 45.3, 31.5, 15.2, '0.322511,0.132482,-0.553043,0.323983,0.322836,0.048997,0.513036,0.155052,-0.271962,-0.500518,0.223445,0.563126,-0.417662,0.197225,0.331450,-0.097298,-0.272551,-0.617817,-0.366327,-0.012172,-0.138652,-0.200210,-0.170348,0.085318,-0.202340,-0.262984,0.873030,0.265675,-0.210532,0.446916,0.121224,0.661443,-0.618769,0.352373,0.264973,0.024935,-0.050586,-0.055048,-0.071409,0.110773,-0.149188,-0.274635,-0.145623,0.261994,0.023045,0.333484,0.871152,-0.473301,-0.195622,-0.166080,0.637511,-0.244645,-0.130262,-0.148131,0.377576,0.280250,-0.011378,0.180581,-0.246090,-0.100404,-0.293079,-0.201262,-0.548663,-0.083290,0.083105,0.316881,-0.076314,-0.186367,0.242539,-0.001915,0.434973,-0.203823,0.245582,0.443280,0.401234,0.184920,-0.373683,-0.211561,-0.166292,-0.110620,0.545865,-0.333827,-0.387546,0.161884,0.053998,-0.240235,-0.419920,0.067941,-0.073951,0.064081,0.109886,0.263775,0.105108,0.222482,-0.501844,-0.125131,-0.132016,-0.495389,0.259821,0.030555,-0.102839,-1.033419,0.013295,-0.070206,-0.322117,0.031220,0.200883,-0.105922,0.379080,-0.844335,0.255891,0.498026,-0.073249,-0.242778,-0.132881,-0.256656,0.100741,-0.465742,-0.385971,0.307538,0.256332,0.516249,0.072877,0.109664,0.070053,-0.080675,-0.678905,0.239132', '2369613', '25723905', '20274039', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2257732', '博物馆奇妙夜2', '喜剧', '由于在纽约自然历史博物馆担任警卫有出色表现，拉瑞（本·斯蒂勒 Ben Stiller 饰）出任某家电小公司的CEO，而且还在电视上接受了著名脱口秀主持人的访谈，儿子对他仰慕，爱情如影随形，一派春风得意的样子。不过，好景不长，当他故地重游，却意外发现馆长已经因为更新展览并准备把过时的展品挪到华盛顿的史密森博物馆继续展出。这让拉瑞感到有些气愤，他觉得自己有责任重振博物馆之雄风，于是他决定留下来再做一晚警卫，以唤起那些老朋友的共同努力。事实上，在搞定了罗斯福（罗宾·威廉斯 Robin Williams 饰）、林肯、拿破仑、伊凡雷帝和阿尔•卡邦等人之后，他遭遇了一个劲敌——邪恶的古埃及法老的卡门拉，二人在夜晚再度上演了博物馆的惊魂对决……©豆瓣', '本·斯蒂勒', '肖恩·利维', 7.1, 165828, 'tt1078912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1381135172.jpg', 0.6, 5, 43.9, 38.1, 12.5, '0.094608,0.100434,-0.843222,0.345134,0.034380,-0.297770,0.759274,0.226040,-0.521347,-0.265898,0.329183,0.895365,-0.452785,0.250434,0.369120,-0.091938,-0.510054,-0.624896,-0.001117,-0.080292,0.036536,-0.255227,-0.158660,-0.315789,-0.038727,-0.141999,0.472688,-0.033174,-0.032015,0.468639,0.342907,0.077017,0.258091,0.574940,-0.103926,-0.026619,0.123891,-0.011876,-0.173697,0.107955,0.137249,-0.275009,-0.215559,0.136643,0.292918,0.271165,0.384280,-0.195298,-0.342525,0.138274,0.329652,-0.260042,-0.041919,0.029003,0.070360,0.081680,-0.180184,0.128341,-0.197715,-0.122157,0.082097,-0.019202,-0.680467,0.192658,-0.036807,0.132875,-0.482855,0.569190,-0.146744,-0.015921,-0.016318,-0.500554,0.242310,0.258856,0.247902,0.308294,0.126203,0.167127,-0.396883,0.343004,0.437622,-0.061653,-0.194363,0.337436,-0.016119,-0.408105,0.031689,-0.113107,-0.215124,-0.014517,0.270956,-0.194364,0.134427,0.032679,-0.498243,-0.204849,-0.051003,-0.353128,-0.156230,-0.496860,0.114469,-0.769533,-0.096700,-0.211824,-0.315824,-0.232738,0.115152,-0.210586,0.479405,-0.775366,0.242912,0.497940,0.256527,-0.279031,0.730892,0.118795,-0.047239,-0.111011,-0.238931,0.293198,-0.032765,0.409079,0.152493,0.379230,0.141729,-0.428223,-0.435315,0.406270', '3055049', '11541282', '26259202', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2257738', '笨人晚宴', '喜剧', '本片根据1998年的法国电影《Le Diner de Cons》改编而成。蒂姆·瓦格纳（保罗·路德 Paul Rudd 饰）为了讨好上司，从而顺利升职，参加了一个被称为"白痴之宴"的活动，目的就是成功的寻找到一个完美的同伴共赴晚餐，届时看谁的同伴是白痴中的白痴。蒂姆找来了看上去很傻的国税局雇员巴里（史蒂夫·卡瑞尔 Steve Carell 饰）担当他的同伴，去竞选那个"白痴之最"的称号，以便逗乐老板。但是，哪里想到，阴差阳错的事情发生了，巴里虽然确实白痴，但是却意外的让蒂姆的老板同样出丑，在这场晚宴制造了不小的风波，蒂姆该如何收场？到底谁才是真正的白痴极品？©豆瓣', '史蒂夫·卡瑞尔', '杰伊·罗奇', 6.7, 10688, 'tt0427152', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p553496864.jpg', 2.7, 11.3, 44, 31.9, 10.2, '0.156723,-0.044136,-0.330876,0.386751,-0.602654,-0.347269,0.362721,-0.044544,-0.266094,-0.233184,0.317484,0.771873,-0.263744,-0.117288,0.323581,0.109797,-0.115326,-0.495562,0.083157,-0.139271,-0.194914,-0.573780,-0.576246,-0.155639,0.321919,-0.142473,0.350806,-0.077073,-0.027856,0.046979,0.616822,0.243005,0.034135,0.291523,0.087410,0.003173,0.427080,0.065086,-0.005267,0.180740,-0.052602,-0.211261,-0.186858,0.268055,0.052014,0.399443,0.378552,-0.417247,-0.226905,-0.002921,0.433902,-0.554234,0.057715,0.247431,0.049864,-0.242726,0.200825,-0.086832,0.027993,-0.036591,0.072186,-0.016273,-0.989215,0.139955,0.082756,0.157752,-0.268994,0.394497,0.013261,-0.214509,-0.019278,-0.186516,0.204096,0.519688,0.493570,0.411682,-0.183310,-0.133026,-0.414508,0.106839,0.676510,0.219714,-0.265732,0.350253,0.072604,-0.336263,0.164337,-0.459155,-0.431519,0.305115,0.204108,-0.168641,0.032642,0.135311,-0.487275,-0.190552,-0.440418,-0.075244,-0.021179,-0.518354,0.066053,-0.415581,0.061807,-0.162256,-0.033742,-0.310459,0.215046,-0.438165,0.600790,-0.693958,-0.042894,0.720073,0.012966,-0.373022,0.364930,0.172597,-0.152400,-0.327819,-0.276434,-0.207949,0.343694,0.137063,-0.011870,0.429201,0.461669,-0.615822,-0.188395,0.361900', '26678784', '1793491', '30216729', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2257740', '布鲁诺', '喜剧', '来自奥地利的布鲁诺（Sacha Baron Cohen 饰）是一档德语时尚节目的主持人，生活中他着装怪异前卫，大玩疯狂的同性恋游戏；荧屏中的他更加乖张出格，或诱导嘉宾说出争议性的言论，或干脆大闹T型台秀场。最终，他成名的愿望没有实现，反而被米兰的时装界所驱逐。一夜之间，布鲁诺的事业跌到谷底，连长久以来的同性恋人也琵琶别抱，最后只有忠心耿耿的第二助理鲁特兹（Gustaf Hammarsten 饰）陪其勇闯好莱坞。在洛杉矶，布鲁诺不改其张扬出位的本性，或为嘉宾奉上令人不忍卒睹的“男体盛”、或宽衣解带挑逗议员、甚至将自己的男性器官录进NBC的试播节目中。可想而知，嘉宾及电视台官员的脸色该有多难看。屡战屡败，屡挫屡勇，百折不挠的布鲁诺为了扬名，在娱乐的道路上高歌猛进……©豆瓣', '萨莎·拜伦·科恩', '拉里·查尔斯', 6.7, 16078, 'tt0889583', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1337485557.jpg', 4.3, 11.7, 40.4, 29.9, 13.7, '0.078998,0.064551,-0.580889,0.764125,-0.044936,0.022661,0.611342,0.233739,-0.526952,0.210933,0.384329,0.717020,-0.451576,0.096060,0.423612,-0.095018,-0.145102,-0.755266,-0.274483,0.091461,0.022919,-0.267564,-0.159416,-0.160301,-0.313570,-0.093497,0.750525,0.083077,-0.239259,0.171479,0.585968,0.143764,0.110287,0.300086,0.160456,-0.143433,-0.058369,-0.094377,-0.069406,0.028716,-0.047038,-0.458213,-0.094645,0.269362,-0.143008,0.414173,0.550294,-0.224669,0.027722,0.015766,0.670723,-0.178251,-0.005153,0.217812,0.115274,0.049154,0.298539,0.110646,0.014038,0.163677,0.106095,0.122411,-0.857820,0.021602,0.105303,0.259375,-0.232384,0.599339,-0.190326,-0.083607,0.099384,-0.092009,-0.055328,-0.020725,0.282394,0.171368,0.116746,0.015540,-0.200053,0.615676,0.451682,0.237589,-0.316261,0.161987,-0.381286,-0.395045,0.064174,-0.599858,-0.470334,-0.225669,0.150625,-0.085808,0.125901,0.283943,-0.502998,-0.053655,0.083787,-0.223585,-0.125031,-0.141206,-0.133074,-0.677937,0.039670,-0.213073,0.102981,-0.239863,0.225488,-0.176398,0.757304,-0.833250,0.021961,0.479972,0.246538,-0.423371,0.534527,0.060145,0.062193,0.167101,-0.448703,0.254822,-0.109323,0.172526,-0.019940,0.286241,-0.088768,-0.372910,-0.238338,0.400594', '27602116', '25880986', '4301278', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2257759', '九', '剧情', '著名导演吉多•孔蒂尼（丹尼尔•戴-刘易斯 Daniel Day Lewis 饰）欲筹拍第九部影片，由于之前票房惨败，让他遭媒体围攻，仅女记者斯蒂芬妮（凯特•哈德森 Kate Hudson 饰）没有发难。制片人也不断施压，幸好有助理莉莉（朱迪•丹奇 Judi Dench 饰）帮他解难。他感觉不适，躲在罗马一家旅馆，在电话中倾听妻子路易莎（玛丽昂•歌迪亚 Marion Cotillard 饰）的安慰，与情人卡拉（佩内洛普•克鲁兹 Penélope Cruz 饰）交欢，仍摆脱不掉被母亲（索菲娅•罗兰 Sophia Loren 饰）带来的童年阴影。在给大明星克劳迪娅（妮可•基德曼 Nicole Kidman饰）试镜时，他开始反思电影的意义……本片取材自意大利电影大师费里尼的《八部半》，并根据1982年百老汇的同名歌舞剧改编。本片获得第82届奥斯卡最佳女配角，最佳艺术指导，最佳服装设计，最佳歌曲4项提名。', '丹尼尔·戴-刘易斯', '罗伯·马歇尔', 6.9, 25812, 'tt0875034', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456868983.jpg', 1, 8.4, 46.6, 33.5, 10.4, '-0.197961,0.000598,-0.515619,0.601687,0.538019,-0.107753,0.519705,0.191568,-0.259110,-0.363663,0.212453,0.701470,-0.453331,-0.103391,0.412529,0.036572,-0.524377,-0.562685,0.274157,0.235019,0.178854,-0.357041,-0.454971,0.030137,-0.257132,-0.426094,0.438462,-0.312320,-0.248980,0.414321,0.592978,0.288496,0.176147,0.023595,0.298587,0.183962,0.458259,-0.122636,-0.359620,0.579525,0.274920,-0.180343,-0.176195,0.072330,0.188914,0.321694,0.611450,-0.201077,0.302855,0.224420,0.544794,-0.079331,0.094338,-0.040633,0.040774,-0.111750,0.279131,0.122342,-0.139972,0.308925,0.122820,-0.182186,-0.538864,0.195762,0.245024,0.232725,-0.275605,0.414073,-0.394255,0.308289,0.102326,0.050078,0.019115,0.140074,0.339120,0.108356,-0.003748,0.033140,-0.086695,0.551789,0.041981,0.120052,0.041548,0.371411,-0.248798,-0.584144,-0.060102,0.097029,-0.630048,0.132857,0.406013,-0.156583,0.197028,-0.028815,-0.270023,-0.357158,-0.282296,-0.315229,-0.082505,-0.205689,0.225772,-1.053990,-0.062098,-0.034540,0.014635,-0.348357,0.142176,-0.285438,0.500859,-0.553735,0.260360,0.440618,0.133844,-0.141710,0.696226,0.080928,0.100239,-0.389758,-0.286485,0.429092,-0.166707,-0.053124,0.224313,0.156639,0.014439,-0.381810,-0.209315,0.269335', '34961898', '24751811', '2075345', '3275168');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22604659', '美眉校探 电影版', '剧情', '告别了青春时代作为私家侦探的冲动与飞扬，美丽的维罗妮卡·玛斯（克里斯汀·贝尔 Kristen Bell 饰）如今已完成大学学业，考取了律师资格证书，准备准备在繁华都市纽约大展才华。而就在此关键时刻，她得知流行歌手——也是她的高中同学——邦妮·德维尔的死讯，而多年未见的罗根·埃克斯（杰森·多灵 Jason Dohring 饰）竟然作为邦妮的男友有着重大嫌疑。以此为契机，维罗妮卡返回阔别已久的家乡，父女亲朋相见自然格外暖心，而当年张扬散漫的罗根此时已穿上军装，变成仪表堂堂的英俊男人。交织着复杂的情愫，维罗妮卡重操侦探旧业，此次归乡之旅将带给她怎样不平凡的体验……©豆瓣', '克里斯汀·贝尔', '罗伯·托马斯', 6.6, 5411, 'tt2771372', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2181881354.jpg', 3.4, 14.5, 45.4, 20.9, 15.8, '0.263188,0.270806,-0.490682,0.497269,0.037170,-0.564439,0.400488,0.323648,-0.298126,-0.263328,0.080450,0.684620,-0.073721,0.301124,0.633729,0.316945,-0.442412,-0.656337,0.359101,-0.185611,0.061767,-0.287318,-0.364422,0.152827,-0.140224,-0.553752,0.638849,0.039943,-0.021282,0.407588,0.339201,0.595623,-0.116382,0.279881,0.056293,-0.319994,0.211804,0.119892,-0.529609,0.089021,-0.004651,0.027673,0.031732,0.066587,-0.047118,0.361194,0.600444,0.060972,-0.065317,-0.081365,0.601240,-0.093392,0.172055,-0.041119,0.037676,-0.137427,0.145602,0.108114,-0.051429,-0.163416,0.119350,-0.317521,-0.460966,0.136982,0.093609,0.056873,-0.346630,0.567997,-0.375774,-0.159994,0.165730,-0.167554,0.052987,0.380188,0.023023,0.204358,0.020541,0.094883,-0.123087,0.325139,0.439826,0.265203,-0.203638,0.288865,-0.316351,-0.393785,0.314962,-0.196273,-0.577264,-0.046700,0.090370,0.047654,-0.029319,0.229611,-0.432961,-0.094312,-0.646286,0.243660,0.213573,-0.205050,-0.260266,-0.569037,-0.173680,-0.406740,-0.581865,-0.202999,0.261141,-0.172235,0.567722,-0.942818,0.091885,0.312117,0.083464,-0.109328,0.441871,-0.111616,0.221140,-0.317378,-0.269486,0.389753,-0.047649,0.188419,-0.033574,0.192325,-0.163069,-0.054791,-0.207028,0.642804', '1826173', '4202326', '6843843', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2263102', '转转', '喜剧', '大学生竹村文哉（小田切让 饰）真可谓霉运当头，他自幼被父母抛弃，养父则被投入监狱，大学念了八年始终无法毕业，在外更债台高筑，欠下84万元债务。因迟迟无法还钱，他被讨债人福原爱一郎（三浦友和 饰）狠狠修理了一番。在最后期限的前一天，福原找到竹村，提议愿意取消他的一切债务 ，条件是竹村必须陪这个凶悍的老头子在东京散步。或者三天，或者一个月，直到福原满意为止。为钱所困的竹村别无选择，只得答应了这个奇怪的要求。一段不平凡的旅程就此展开……本片根据藤田宜永的原著《东京散步》改编。©豆瓣', '小田切让', '三木聪', 8.4, 16306, 'tt1098226', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1111394339.jpg', 0.2, 1, 13.7, 47, 38, '-0.229456,0.183485,-0.364734,0.214196,-0.184107,-0.502673,-0.060158,0.026570,-0.343933,-0.401273,-0.049688,0.509873,0.171177,0.247063,0.066306,0.003943,-0.080765,-0.282568,0.099505,-0.267470,0.038342,-0.546901,0.387286,0.117435,-0.350558,-0.125956,0.573932,0.258031,0.138405,0.404945,0.241996,0.264977,0.037085,0.193416,-0.190081,0.142705,0.181279,0.087693,-0.170449,0.185053,0.002227,-0.367916,-0.002266,0.033081,0.207069,0.418285,0.731227,0.214578,-0.476418,-0.033253,0.519129,-0.254729,-0.416000,0.281248,0.248723,-0.084418,0.133515,0.515060,-0.518619,-0.021933,0.186375,-0.181590,-0.560063,-0.182661,0.074095,-0.175179,-0.562399,0.597639,-0.250714,0.009713,-0.021537,-0.117247,-0.157907,0.396563,0.125529,0.256068,-0.309140,0.078227,-0.323788,0.618039,0.690667,-0.283288,-0.081617,0.459339,-0.034295,-0.246192,-0.019469,-0.266548,-0.379975,0.236427,0.143251,0.334336,-0.487839,-0.066025,-0.262523,-0.157105,-0.305576,-0.239002,0.246258,-0.422187,-0.075802,-0.373962,0.028524,-0.165795,-0.167204,0.185397,0.077198,-0.196997,0.356093,-0.375826,0.223373,0.514098,0.488199,-0.457824,0.471979,0.513698,-0.022193,-0.075746,0.271117,0.196296,0.116827,0.459199,0.407647,0.031103,0.136926,-0.201757,-0.455341,0.413641', '21937434', '26678784', '26418093', '3001184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2263112', 'C+侦探', '剧情', '住在曼谷唐人街，父母早年失踪的阿探（郭富城 饰），自幼渴望和好友风泽（廖启智 饰）一起投身警界，却因高度近视未能如愿，不甘心之下，他当起了私家侦探，却只能接一些鸡鸣狗盗的小案子，赚钱不多、口碑奇差，还时常入不敷出，要靠风泽接济。一天，阿探的朋友肥龙（成奎安 饰）委托他调查一个女人，声称自己正在被她追杀。好奇之下，阿探根据照片查出这个女子叫莫慧心，却在寻找相关知情人士时接连出现怪异事件：跟莫慧心有关的人相继死亡，而阿探总是第一个发现者，简直成了死神的化身。为此风泽百般奉劝阿探放弃追查，甚至不惜以两人多年友谊要挟，阿探却执意坚持。随着调查的进展，惊人的真相开始渐渐浮出水面……©豆瓣', '郭富城', '彭顺', 6.7, 31780, 'tt1107807', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2183184174.jpg', 1.2, 7.7, 52.5, 31.5, 7.1, '0.154152,0.071660,-0.593346,0.430767,-0.026771,-0.275564,0.284637,0.070811,-0.564215,-0.382021,0.084100,0.443822,-0.116248,0.302259,-0.040392,-0.177707,-0.142743,-0.571556,0.069952,-0.105781,-0.171396,-0.515295,-0.303439,-0.310854,-0.266367,-0.026089,0.425320,0.145641,-0.193270,0.462673,0.294826,0.248784,-0.320493,0.471047,-0.044030,-0.214833,0.091488,0.203741,-0.214147,-0.013666,0.227007,-0.445851,-0.104266,-0.034344,0.079041,0.539749,0.428437,-0.064355,-0.306492,-0.115642,0.381829,-0.253178,-0.056398,-0.032573,0.302889,-0.022837,0.172500,0.261239,-0.318536,-0.170284,0.048539,0.139218,-0.590915,0.105108,0.304541,0.141761,-0.579734,0.188065,-0.217268,0.009938,0.023358,-0.385196,0.112770,0.421545,0.170212,0.110806,-0.166265,0.103779,-0.352516,0.297000,0.686945,0.164739,-0.038121,0.173808,0.027773,-0.134632,0.083972,-0.176083,-0.177542,0.027927,0.136907,-0.009112,-0.261124,0.318186,-0.109274,-0.210219,-0.414593,0.115496,-0.022147,-0.298872,-0.145196,-0.426372,-0.014913,-0.304088,-0.042351,0.138125,-0.009402,-0.334183,0.631841,-0.684583,0.139918,0.507257,0.234601,-0.691366,0.503550,0.110130,0.007370,-0.340815,-0.184244,0.122120,0.056346,0.168765,0.195594,0.016282,0.150908,-0.027648,-0.160964,0.105033', '1877596', '25908042', '1308805', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22637441', '不死鸟', '剧情', '故事发生在1945年6月，身受重伤、面部毁容的奥斯维辛集中营幸存者内莉，返回了家乡柏林。整容尚未完全康复后的她，不顾莱内的警告，踏上了寻找丈夫强尼的征途。强尼——内莉生命中的爱人，曾长时间保护她免于受到纳粹的迫害，并拒绝与她离婚……', '尼娜·霍斯', '克里斯蒂安·佩措尔德', 7.5, 7202, 'tt2764784', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2256429655.jpg', 0.8, 3.8, 31.9, 48.6, 14.9, '0.094682,-0.035715,-0.608212,0.083875,-0.130753,-0.393880,0.631312,-0.228381,-0.729739,-0.160013,0.350001,0.760109,-0.109905,0.388373,0.359337,0.032940,-0.329993,-0.701254,0.060916,0.089465,-0.493561,-0.546318,0.041908,-0.050373,-0.223577,-0.772100,0.655647,0.135621,-0.137447,0.407715,-0.076472,0.055193,-0.087286,0.472616,0.164069,0.410534,-0.146276,-0.034534,-0.472987,0.338292,0.177837,-0.465757,-0.063418,0.266179,-0.133929,0.566084,0.661363,-0.194086,-0.153115,-0.438302,0.567530,-0.436150,0.058539,0.135484,0.191712,-0.149413,0.055941,0.507763,-0.266202,-0.221137,0.128196,-0.082130,-0.298621,0.001645,-0.065653,0.077333,-0.500095,0.435867,-0.167092,0.626769,-0.072883,-0.147461,0.350909,0.609522,-0.072942,0.397039,-0.353956,0.178570,-0.336327,0.428707,0.942650,-0.309418,-0.363785,-0.071131,-0.288570,-0.177403,0.064376,-0.427110,-0.485581,0.115371,0.159258,0.385332,-0.690025,0.251408,-0.211620,-0.269830,-0.667115,-0.266266,-0.018994,0.000191,0.069546,-0.611890,-0.331585,-0.217504,-0.142011,0.000392,-0.098501,-0.405952,0.227575,-0.698409,0.787283,0.413603,0.747757,-0.646254,0.353009,0.099547,0.297917,0.050134,0.051062,1.300441,0.079284,0.340943,0.155948,-0.235369,0.080981,0.318120,-0.260086,0.216247', '3289081', '1293964', '1844413', '1308806');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2264580', '迪迦&戴拿&盖亚·奥特曼 超时空的大决战', '科幻', '一个崇拜奥特曼的男孩小勉,在一次奇妙的际遇中得到了一个红色的玻璃球,原来那是一个能够实现愿望的神奇球,而它可从不同人许下的愿望中更加彰显出许愿者心灵的善恶.....', '吉冈毅志', '小中和哉', 8.9, 6796, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2631735909.jpg', 0.5, 0.8, 9.7, 32, 57, '0.341103,0.479296,-0.786111,1.179524,-0.739290,-0.182112,1.258271,-0.269340,-0.422331,0.307645,0.273870,0.910755,-0.204667,0.285282,0.360368,0.253255,0.389830,-0.511352,0.261225,-0.384134,-0.454440,-0.448982,-0.556953,-0.306844,-0.159627,-0.390544,0.861017,0.421535,0.032907,0.137367,0.363446,0.105793,-0.005751,0.305333,-0.399775,-0.211055,-0.232304,0.349108,-0.044403,0.407394,0.016223,0.050069,0.003485,0.705314,-0.928986,-0.003373,0.828672,-0.888884,-0.187907,-0.319473,0.667073,-0.037429,-0.318983,0.240873,-0.272268,0.258917,0.113678,-0.293961,0.147152,0.104685,0.260285,-0.387400,-1.242208,-0.555940,0.144317,0.266875,-0.404016,0.315172,0.161857,-0.236625,0.214026,-0.400363,0.017836,-0.039370,0.468583,0.738801,-0.780166,0.001772,-0.601048,0.067085,0.534255,-0.319817,-0.737332,0.682976,-0.649300,-0.624946,0.020960,0.040074,-0.513704,0.297553,0.555332,0.231280,-0.194155,-0.125072,-0.898649,0.250037,-0.324070,0.110539,-0.125215,-0.695540,-0.314285,-0.102376,-0.146823,-0.269762,-0.356362,0.219400,0.121953,-0.655686,1.243806,-0.991886,0.046620,0.760717,-0.110652,-0.021935,0.854733,0.068711,0.040534,-0.465061,-0.229078,0.257909,-0.217170,0.143780,-0.319371,0.555330,-0.018046,0.266139,-0.563743,0.737786', '1303542', '2053515', '24284209', '25932086');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2264715', '鹰眼', '动作', '中东某地，美国军方的情报系统锁定了一名目标人物，总统不顾系统电脑运算出的建议处理方式，下令定点清除，由此引发了意外的连锁反应……公司小职员杰瑞（Shia LaBeouf 饰）的生活平淡乏味，时常手头拮据，连房租也成了问题，由于供职于军方的孪生兄弟意外过世，杰瑞赶回家中参加葬礼，但此行归来后，杰瑞发现家中居然堆满了武器，随即赶到的FBI破窗而入将他逮捕。与此同时，名叫蕾切尔（Michelle Monaghan 饰）的女人从大街上的电子广告牌上得知自己的儿子被某人绑架，绑架者拥有超乎寻常的能力，能够控制电子产品并监控一切。这名绑架者引导杰瑞摆脱FBI，最终上了蕾切尔的车，两名陌生人被迫合作，在FBI的追捕中落入了神秘绑架者的计划……究竟绑架者是谁？他又有何居心呢？©豆瓣', '希亚·拉博夫', 'D·J·卡卢索', 7.2, 48126, 'tt1059786', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p620088759.jpg', 0.6, 4.2, 41.4, 42.9, 10.9, '0.330106,0.245896,-0.540367,0.262949,-0.193177,-0.045741,0.474891,0.184060,-0.525940,-0.267910,0.341129,0.533978,0.086752,-0.054864,0.382043,0.002984,-0.460846,-0.690226,-0.002682,-0.303961,-0.291678,-0.609859,-0.297429,-0.222476,0.016203,-0.397383,0.421606,-0.022279,-0.200398,0.347465,0.252303,0.408809,-0.328031,0.529340,0.118264,-0.058571,0.302825,-0.244596,-0.194721,0.262681,-0.161967,-0.371168,0.080535,0.173509,0.098034,0.572509,0.655478,-0.148802,-0.202401,-0.147706,0.281212,-0.242140,-0.070006,-0.004075,0.398331,0.210332,0.048114,0.254647,-0.362529,0.021316,0.174249,0.096901,-0.640396,-0.004474,-0.032479,0.108185,-0.454048,0.003531,-0.320662,-0.088061,-0.112993,-0.450586,0.266014,0.450154,0.105999,0.299179,-0.048454,0.237952,-0.410685,0.074089,0.401534,-0.240022,-0.307082,0.165796,-0.110522,-0.400338,-0.090990,-0.334877,-0.203828,-0.074613,0.414240,0.160209,-0.146403,0.162931,-0.304540,-0.101391,-0.373626,-0.145705,-0.084804,-0.242560,-0.120239,-0.817735,0.028749,0.030798,-0.285694,-0.115030,0.027226,-0.079319,0.426800,-0.705867,-0.007569,0.438959,0.339901,-0.530184,0.319819,-0.084881,0.233942,-0.093848,-0.238268,-0.069816,0.405912,0.417146,-0.077270,0.128334,0.062432,-0.420910,-0.157029,0.188509', '25723905', '1307442', '2369613', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2265098', '冒险乐园', '剧情', '毕业旅行被父母否决，大学生布伦南（杰西•艾森伯格 Jesse Eisenberg 饰）感到非常沮丧，好友给了他一带大麻以示安慰。布伦南决定利用假期打工赚点零花，因为夏天之后他将要奔赴纽约求学。四处碰壁之后，布伦南终于在一家名为冒险乐园的游乐场，找到了赠品游戏服务生的工作。起初他对此毫无兴趣，但是持刀抢劫大熊猫事件发生后，他却发现了游戏之外的意义——女孩艾（克里斯汀•斯蒂沃特 Kristen Stewart 饰），后者独特的忧郁气质深深吸引了这个处男。某次酒醉后，艾对布伦南坦白了自己的身世：原来她的生母因绝症离世，父亲续弦的继母令她非常反感。布伦南耐心安慰着她，两人的恋情逐渐升温。就在此时，布伦南却在无意中发现了艾的秘密，这让他的爱情几乎陷入了绝境……©豆瓣', '杰西·艾森伯格', '格雷格·莫托拉', 6.8, 10492, 'tt1091722', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p761701304.jpg', 0.9, 8.7, 50.7, 29.7, 10, '0.297827,0.029456,-0.790587,0.529131,-0.103621,-0.328350,0.745913,0.149623,-0.534031,-0.584615,-0.012300,0.634619,-0.307938,0.393145,0.387660,0.132533,-0.399165,-0.500673,0.030591,-0.112078,-0.192175,-0.397327,-0.139893,-0.278693,-0.183315,-0.167629,0.470855,0.026306,-0.190658,0.424673,0.075263,0.326551,0.071575,0.709590,0.106633,0.181665,0.281836,0.075505,-0.121776,0.217484,0.294557,-0.272044,-0.134727,0.487229,-0.065007,0.553968,0.816729,0.012378,-0.328976,-0.015707,0.320821,-0.315157,-0.032496,0.053236,0.181173,-0.007749,0.094963,-0.066778,-0.223265,-0.044659,0.144072,-0.032592,-0.246089,0.131260,-0.194173,0.056208,-0.334392,0.500435,-0.175118,0.115088,-0.107227,-0.245132,0.197593,0.347461,0.205252,0.100228,-0.034021,0.156324,-0.289153,0.306320,0.527856,-0.099604,-0.062203,0.535128,-0.579277,-0.411817,0.198231,-0.072125,-0.318589,-0.105081,0.420415,0.179878,-0.311483,0.291242,-0.479212,-0.235517,-0.151914,-0.040765,-0.161828,-0.380789,-0.121447,-0.500358,-0.217651,-0.215386,-0.400088,-0.263273,-0.057357,-0.281229,0.313087,-0.771734,0.285636,0.728409,0.161094,-0.404032,0.548478,-0.078521,0.046792,-0.296601,0.036991,0.442211,0.056196,0.095598,0.203224,0.183780,-0.060200,-0.229735,-0.304714,0.638790', '1309172', '3059036', '3114200', '2002683');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2265778', '重生男人', '剧情', '未来，随着科技的不断进步，人类医学也达到前所未有的高度。当你某个器官患有疾病时，不用担心自己会死于非命，也不必苦苦等待遥遥无期的捐赠器官，只要移植人造器官即可回归正常的生活。当然，天下没有免费的午餐，全新的器官伴随着高昂的购买金，受移植者一旦无法承担这笔费用，将面临被杀害并被夺走器官的悲惨命运。雷米（裘德·洛 Jude Law 饰）隶属这家销售器官的联盟公司，他的工作是追杀那些拖延还款的客人。凭借这份冷酷无情的工作，他过着养尊处优的生活。然而厄运突然降临，他因重病移植了联盟的人造心脏，更因无法偿还款项而遭到昔日好友的追杀。猎人和猎物的身份一夜之间对调……©豆瓣', '裘德·洛', '米格尔·萨普什尼克', 7.3, 26492, 'tt1053424', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1040094582.jpg', 0.8, 4.7, 36, 46.2, 12.3, '-0.107057,0.135886,-0.515645,0.336919,-0.274729,-0.054334,0.603209,0.206274,-0.362118,-0.263411,0.109997,0.649895,0.296476,0.266073,0.128981,-0.126986,0.071384,-0.476858,-0.128379,-0.074771,-0.568276,-0.330527,-0.129379,-0.419062,-0.244005,-0.487292,0.753622,0.075631,-0.477321,0.078918,-0.057070,0.558665,0.120372,0.410802,-0.312540,-0.297775,-0.042724,0.022413,-0.229721,0.275480,0.204617,-0.342676,0.384736,0.286513,-0.173918,0.500883,0.615696,-0.314786,-0.071136,-0.576742,0.492319,-0.265881,0.237629,0.058081,0.312046,0.196800,0.033858,0.337852,-0.443362,0.214847,0.171709,-0.148841,-1.403969,-0.473650,0.268627,0.100401,-0.391136,0.407519,-0.054983,0.151631,-0.104529,-0.132362,0.181054,0.776379,0.407399,0.367725,-0.242281,-0.026200,-0.644304,0.265626,0.741971,-0.112497,-0.491218,0.455884,-0.478286,-0.626923,-0.008116,-0.671304,-0.453984,-0.020090,0.164782,0.483128,-0.099031,0.618080,-0.457721,0.247535,-0.110562,-0.622797,0.071790,-0.194564,-0.052366,-0.570750,-0.167599,-0.284384,-0.162230,0.244098,0.277917,-0.298515,0.722015,-0.682976,0.165109,0.488736,0.448287,-0.908623,0.436768,-0.100739,0.176576,-0.168884,-0.116463,0.400773,0.258431,0.582592,0.216177,-0.244353,0.195502,0.096379,-0.199900,0.514632', '26678784', '1811755', '1793491', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2267369', '蕾切尔的婚礼', '剧情', '在康复中心戒毒治疗的金茉（安妮•海瑟薇 Anne Hathaway饰），因为姐姐蕾切尔（罗丝玛丽•德薇特 Rosemarie DeWitt 饰）即将举行婚礼，被父亲保罗（比尔•欧文 Bill Irwin 饰）接回了家。但她还是要定期去参加瘾君子互助会活动。巧的是，她发现姐夫的伴郎基兰（玛德•奇科尔 Mather Zickel 饰）竟然也是互助会成员，同命相怜的两人倍感亲近。在交流中，金茉得知伴娘不是自己，勃然大怒。经过一番争取，蕾切尔最终还是同意金茉出任伴娘。但是，这次妥协并没未让姐妹重修旧好。金茉不合时宜的“道歉计划”让整个家庭陷入了矛盾之中，只有父亲始终细心维护着她。在一次争吵中，姐姐蕾切尔提及早年弟弟车祸死亡之事，这让金茉内心的负罪感愈加沉重，并导致她与母亲艾比（德博拉•温格 Debra Winger 饰）大打出手……©豆瓣', '安妮·海瑟薇', '乔纳森·戴米', 6.9, 34825, 'tt1084950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1320709012.jpg', 0.9, 6.6, 48.3, 35.4, 8.9, '0.070888,-0.004885,-0.710696,0.320871,-0.033841,-0.577518,0.681173,0.160509,-0.663891,-0.249770,0.127968,0.632199,-0.261288,0.113296,0.176366,0.123931,-0.389731,-0.512983,0.198278,-0.008900,-0.129407,-0.802146,0.176769,0.003378,-0.060848,-0.410291,0.367065,-0.220951,0.090245,0.611845,0.371723,0.379717,-0.029421,0.617793,0.395367,0.029536,0.300705,-0.042802,-0.459100,0.053016,0.193848,0.005191,-0.246923,0.579090,0.426255,0.532540,0.335959,-0.411735,0.168144,-0.142683,0.122070,-0.144648,0.121997,0.079160,0.045595,-0.160258,0.533201,0.410075,-0.378888,0.028694,0.025470,-0.023241,-0.384217,0.369573,0.273784,0.148517,-0.728647,0.360324,-0.209697,-0.000997,0.106645,-0.211227,0.114216,0.674881,0.300299,0.370561,-0.227383,0.118235,-0.220625,-0.095932,0.808346,0.064876,-0.043076,0.309294,-0.341752,-0.159993,0.295406,-0.041847,-0.491413,0.090735,0.257506,0.020683,0.036448,0.280204,-0.429139,-0.255020,-0.566859,-0.078753,0.110570,-0.370910,0.186563,-0.499937,-0.062912,-0.156940,-0.603122,-0.258307,-0.073479,-0.364958,0.302930,-0.993465,0.197592,0.446099,0.410612,-0.472063,0.366071,0.309184,0.262482,-0.145026,-0.164810,0.222973,-0.123905,-0.039963,0.095411,0.170143,0.356732,-0.107288,-0.214562,0.194216', '1308755', '1301022', '1922691', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2267372', '圣诞颂歌', '剧情', '性情刻薄、冷酷的守财奴埃比尼泽•斯克鲁奇（金•凯瑞 Jim Carrey 配音），面对温暖的圣诞节，却表现出讨厌周遭的一切庆祝活动。圣诞临近，他想尽办法去剥削他那忠诚可靠的雇员鲍勃•克莱切特（加里•奥德曼 Gary Oldman 配音）以及爽朗乐观的侄子弗莱德（科林•费斯 Col in Firth 配音）。打从一开始，埃比尼泽根本就无心享受假期，只想像平常那样独自一个人待在家里。让埃比尼泽想象不到的是，他梦见刚逝去的合伙人约瑟夫•马利（加里•奥德曼 Gary Oldman 配音）的鬼魂。他希望能够借机帮助埃比尼泽，避免他以后走上自己的老路，后悔不堪。约瑟夫告诉埃比尼泽，在他之后还会有三个幽灵来拜访他……很快，这三个分别被称为圣诞节的"过去之灵"、"现在之灵"和"未来之灵"（金•凯瑞 Jim Carrey 配音）的鬼魂就找到了他，唤醒他人性的另一面……本片改编自查尔斯•狄更斯创作于1843年的同名小说，本片是迪士尼第一部将以IMAX 3D方式发行的影片，影片中的人物表情都是通过“表演捕捉”完成的。', '金·凯瑞', '罗伯特·泽米吉斯', 7.4, 22067, 'tt1067106', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2523240970.jpg', 0.6, 4.2, 35.7, 42.1, 17.4, '0.179676,0.095235,-0.624795,0.594427,0.203465,-0.477128,0.663662,-0.032185,0.005462,-0.255746,-0.287630,0.703743,-0.348361,0.340373,0.429419,0.105607,-0.432545,-0.604431,-0.157092,-0.020930,-0.098890,-0.479134,-0.060858,-0.335335,-0.053683,-0.384029,0.365549,0.206882,-0.347864,0.225688,0.190699,0.432002,0.172450,0.250584,0.054673,-0.097987,0.151359,-0.276293,-0.131847,0.172879,0.391119,0.090554,-0.134276,0.501547,0.064894,0.464073,0.519624,-0.493805,-0.022232,0.173330,0.412347,-0.171442,0.067065,-0.272653,0.115501,-0.210179,-0.098456,0.219418,-0.030330,-0.003953,-0.184410,-0.283196,-0.796760,0.029575,-0.284852,0.261252,-0.414320,0.241019,-0.040670,0.288307,0.113610,-0.306444,0.062866,-0.008947,-0.033895,0.376120,0.021447,0.063829,-0.314688,0.364723,0.714094,0.173985,-0.446095,0.563023,-0.282421,-0.287782,0.009296,-0.290102,-0.499229,0.022997,0.327914,-0.219486,0.107441,0.251441,-0.364795,-0.109444,-0.332580,-0.042544,0.046248,-0.142037,0.088423,-0.871601,-0.004133,-0.192384,-0.265820,-0.112485,-0.131051,-0.479910,0.595220,-0.670874,0.253906,0.774732,0.258588,-0.364139,0.699133,-0.146503,0.104105,-0.256164,-0.029457,0.381522,0.248130,-0.042617,