INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2268359', '暮光之城', '剧情', '因为父母离异，贝拉（克里斯汀•斯图尔特 Kristen Stewart 饰）随父亲来到小镇生活。在新学校里，贝拉留意到一群举止诡异的怪人，他们特立独行，很是神秘。在实验课上，她遇到了怪人中的一个——金发帅哥爱德华（罗伯特•帕丁森 Robert Pattinson 饰），他俊朗的外形与出众的谈吐令她着迷。在交往中，贝拉渐渐对爱德华产生了感情，但其他怪人对她心存戒备。与此同时，小镇里接连发生死亡事件，贝拉的父亲是警察，负责调查此案。然而，警方的介入并没有阻止死亡威胁的蔓延。在一次意外中，爱德华救出了贝拉。从此，她发现他拥有异于常人的超能力，开始怀疑对方是杀人凶手。在事实面前，爱德华对她坦白，自己是素食吸血鬼，所以凶手另有其人。在杀人凶案的羁绊中，一场人鬼之恋由此展开……©豆瓣', '克里斯汀·斯图尔特', '凯瑟琳·哈德威克', 7.6, 466556, 'tt1099212', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2601335410.jpg', 1.4, 5, 30.3, 40.4, 22.9, '0.515965,-0.027072,-0.779866,0.422997,-0.454623,0.144816,1.107514,-0.222152,-0.805626,-0.323135,0.252247,0.868153,-0.207895,0.252108,0.170124,0.035570,-0.217876,-0.657821,0.128442,-0.303965,-0.244999,-0.604090,-0.381685,-0.373484,-0.176259,-0.311780,0.439826,0.064783,-0.303830,0.583282,0.308645,0.314015,-0.334642,0.652182,-0.024036,-0.073057,0.137098,-0.149304,-0.240303,0.209150,0.093862,-0.329502,-0.096815,0.543509,-0.231764,0.557927,0.711212,-0.426629,-0.276420,-0.197553,0.360999,-0.283679,-0.122849,0.268672,0.401890,-0.020976,-0.045548,0.352763,-0.161027,-0.141622,-0.058791,0.056929,-0.350573,0.093666,0.043255,0.567540,-0.491959,0.320928,-0.150255,-0.188571,0.185005,-0.098955,0.087473,-0.036355,0.361827,0.119607,0.123752,-0.102544,-0.406004,-0.130281,0.739709,0.167925,-0.331261,0.252939,-0.537473,-0.486825,-0.127500,-0.050412,-0.465865,0.036188,0.176884,0.016105,-0.244589,0.411255,-0.416478,-0.012918,-0.256981,0.115743,-0.372169,-0.294968,-0.151908,-0.647584,-0.233178,-0.605059,-0.523730,-0.088625,-0.205594,-0.510126,0.315636,-1.052745,0.173041,0.566270,0.379688,-0.384465,0.569769,0.076552,0.039688,-0.223132,-0.298211,0.471684,0.170682,-0.048881,-0.032081,0.323513,0.136515,-0.011010,-0.308713,0.525990', '1308755', '4275444', '1309172', '1309080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2269525', '寻找午夜之吻', '喜剧', '在新年来临之际，与所爱之人共同分享一个午夜之吻，全年的孤独与压抑都会消失，新的一年亦将充满喜悦与希望。生活在洛杉矶的威尔逊（斯科特·麦克奈瑞 Scoot McNairy 饰）年届而立，仍然孤独无助。在过去的一年里，他的生活如此糟糕，没有女友，没有工作，内心的欲望得不到释放。为了帮助好友排遣寂寞，威尔逊的好兄弟雅克布鼓励他在Craigslist交友网站发布了一则征友广告。在一年的最后一天，这则广告让威尔逊和寻找真爱的薇薇安（Sara Simmonds 饰）相遇……本片荣获2008年弗罗里达电影节评委会大奖最佳影片奖、2009年独立精神奖John Cassavetes奖、2007年伍德斯托克电影节最佳剪辑奖。©豆瓣', 'Scoot McNairy', 'Alex Holdridge', 7.4, 6782, 'tt0989000', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1216985343.jpg', 0.8, 4.6, 34.1, 44.8, 15.8, '-0.291875,-0.154925,-0.642891,0.733686,0.095659,-0.268214,0.692983,0.017745,-0.471945,-0.159516,0.046453,0.811322,-0.468513,0.312078,0.480857,-0.130169,-0.256206,-0.856692,-0.122157,-0.374824,0.209512,-0.312069,-0.464300,-0.122222,-0.280311,-0.407679,0.790678,0.223255,0.281107,0.678671,0.357922,0.199157,0.055171,0.527976,-0.121731,-0.241617,0.366781,0.179280,-0.518649,0.408660,0.323343,-0.310276,-0.230560,0.153227,0.246241,0.101644,0.717628,-0.154471,-0.097410,0.238643,0.465620,-0.238855,0.019995,-0.200226,0.045209,-0.120359,0.315621,0.298672,-0.362046,0.157370,0.047565,-0.185404,-0.730034,0.112483,-0.006399,0.085018,-0.442217,0.767395,-0.271278,0.182154,0.041521,-0.180347,0.115208,0.417472,0.204448,0.505821,-0.122654,0.124246,-0.228415,0.714963,0.603784,-0.194749,-0.267369,0.291068,-0.243044,-0.375601,-0.022180,-0.134540,-0.723479,-0.053553,0.391885,0.266866,-0.079586,0.370515,-0.661331,0.122665,-0.067847,-0.301111,0.236214,-0.468812,-0.203237,-0.948514,-0.152346,0.031083,-0.197846,-0.039136,0.204882,-0.571331,0.689065,-0.773819,0.611566,0.411534,0.353293,-0.195851,0.964192,0.292944,0.071537,-0.183256,0.053739,0.528564,-0.331939,0.130251,0.032903,0.067069,-0.090887,0.036107,-0.564845,0.692266', '24751811', '1299663', '1293656', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2269893', '食人鱼3D', '喜剧', '一年一度的春假到来，来自全国各地的大学生纷纷涌向度假胜地维多利亚湖，他们纵情歌舞，寻欢作乐。青年杰克·福斯特（史蒂芬·R·麦克奎恩 Steven R. McQueen 饰）追随友人来到海边。在电视人德里克·琼斯的邀请下，杰克和心仪的女孩凯莉（杰西卡·斯佐尔 Jessica Szohr 饰）等友人登上了德里克的游艇。在一个幽静的角落，女孩们尽情游水，享受美好的时光，却不知危险正慢慢逼近。原来近期湖底的地壳发生变动，一群在史前时代因火山爆发而被困在湖底的恐怖食人鱼重返人间，它们纷纷向毫无防备的人类发起猛烈攻击。秀美宜人的湖泊一瞬间变成血腥残酷的修罗场……©豆瓣', '理查德·德莱福斯', '亚历山大·阿嘉', 5.9, 38292, 'tt0464154', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p588914134.jpg', 4.6, 20.7, 53, 16.4, 5.2, '0.435372,-0.202646,-0.998964,0.387356,0.105073,0.145648,1.178452,0.159422,-0.398151,0.040263,0.596162,0.595411,-0.434449,0.160411,0.465645,0.009721,-0.365405,-0.635546,-0.294820,-0.030301,-0.299998,-0.104043,-0.489121,-0.130876,0.154671,-0.196543,0.436608,0.229919,0.092210,0.730189,-0.010016,0.184523,-0.328008,0.529245,-0.174453,-0.072038,0.236794,-0.102639,-0.219494,0.313034,-0.253440,-0.324212,-0.371364,-0.097627,-0.055334,0.080571,0.861484,-0.367162,0.079225,-0.032214,0.278277,-0.196024,0.188532,0.258804,0.367944,-0.220240,-0.103780,-0.221256,-0.106545,0.032562,0.047933,-0.227353,-0.099603,0.284941,-0.095546,0.496957,-0.202691,0.429957,0.132347,-0.177204,0.250397,-0.366845,-0.147934,0.044215,0.105295,0.388885,0.086063,0.191572,-0.187813,0.026022,0.728215,0.310882,-0.448694,0.022316,-0.240415,-0.160774,-0.010270,0.045165,-0.581481,-0.362393,0.476663,0.054304,-0.085455,0.577432,-0.690078,0.167262,-0.315507,-0.424468,-0.189029,-0.072941,-0.727324,-1.080691,-0.055722,-0.076697,0.201933,0.200796,-0.030923,-0.030083,0.695527,-0.555305,0.383960,0.692043,0.102039,-0.003676,0.538347,-0.315645,0.006109,0.045791,-0.262658,0.600382,0.246268,0.332131,-0.105538,0.388363,-0.247275,0.306073,-0.375602,0.377261', '10466639', '3011051', '20451118', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22715021', '僵尸', '恐怖', '曾经凭借僵尸片红极一时的动作明星钱小豪（钱小豪 饰）事业和人生跌入谷底，他带着随身家当入住一栋破败老旧的公寓。经保安燕叔（卢海鹏 饰）指引，走进了传说的凶宅2442单元。小豪悬梁自尽，谁知命悬一线之际遭遇猛鬼缠身，多得隐世道长阿友（陈友 饰）出手方捡回一条命。小豪对白发 男孩小白及经常在2442门口窥视并吃祭祀食物的女人杨凤（惠英红 饰）感到好奇，进而从燕叔口中得知了当年曾发生的一起血腥惨案。同大厦的冬叔（吴耀汉 饰）不慎跌死，冬叔的老婆梅姨（鲍起静 饰）求专修邪法的阿九（钟发 饰）帮其还魂，但酿成不可逆转的悲剧。生生死死，死死生生，爱恋贪欲引出无限烦恼。僵尸猛鬼，趁夜横行……©豆瓣', '钱小豪', '麦浚龙', 7.9, 166008, 'tt2771800', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2153223458.jpg', 0.7, 2.7, 22, 48.6, 26, '0.122196,-0.097908,-0.351412,-0.014799,0.136694,-0.135928,0.629462,0.265903,-0.252501,-0.416715,0.318547,0.267384,-0.133853,0.064993,0.090997,-0.250420,0.058178,-0.270659,0.041385,0.042361,0.060903,0.051027,-0.310218,-0.024362,-0.000742,-0.266465,0.486054,0.417758,-0.187178,0.378083,0.407119,0.323889,-0.428686,-0.015658,-0.221246,0.189209,-0.150781,0.202110,-0.186684,-0.041805,-0.183684,-0.282666,0.083393,-0.130215,-0.192352,0.220279,0.563032,-0.187326,-0.133387,-0.154199,0.299894,-0.027386,-0.097052,-0.021281,0.086579,0.069725,0.141884,0.099870,-0.094237,-0.002895,0.410075,-0.064149,-0.271586,-0.040805,0.147766,0.147446,-0.327200,0.092570,-0.066970,0.203010,0.123091,-0.116187,0.192145,-0.190504,0.394891,0.316767,-0.165600,-0.012113,-0.402837,0.220544,0.326829,-0.364499,0.215559,0.204602,-0.044784,-0.353381,0.148731,-0.130704,-0.301343,0.118126,0.298843,0.069784,-0.218960,0.150574,-0.506157,-0.135141,-0.128588,0.262927,-0.054318,0.126049,-0.211482,-0.418433,-0.106743,-0.128252,-0.004138,0.007762,-0.040309,-0.214178,0.257573,-0.259755,0.354551,0.148880,0.236293,-0.499610,0.599541,-0.224147,0.167226,-0.108364,-0.064182,0.514375,-0.084391,0.240748,0.031295,0.046526,-0.366456,-0.098015,-0.169236,0.026158', '21619567', '10466639', '25986180', '10777687');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2272208', '世界奇妙物语 2007秋之特别篇', '剧情', '1 未来同学会3年后的同学会上竟然见到的是30年后的同学们，恍惚间却又回到了高中时代，女主角便这样不断地在时空中穿梭...（石原さとみ饰）2 倒计时早晨，师生们步入校门时发现课桌全被搬来操场，从高处看是个9的形状。第2天，晚上还好好在教室里的课桌又回到操场上，并变成8的形状，倒计时的最后会出来什么？（阿部サダヲ饰）3 自动贩卖机男贩卖机送出的饮料时冷时热，不仅会突然倒下来，还能报警，据说在机器里住了一个男人。（城島茂饰）4 垃圾女在捡垃圾的婆婆处接连发现湮没多年，满载自己的回忆的物品，难道自己不为人知的秘密竟被人发现了……（松下由树饰）5 48％の恋天使将光环套在幸福指数最高的两人头上，但他们真的是最般配的天生一对吗？到底谁才是自己的真爱呢。（白石美帆 岡田義徳饰）©豆瓣', '石原里美', '松木创', 8.1, 6713, '世界奇妙物语 07秋季篇', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1517939605.jpg', 0.2, 1.1, 19, 54.2, 25.5, '0.329971,0.054355,-0.594848,0.254614,-0.124147,-0.436076,0.659310,-0.004156,-0.441074,-0.049436,0.217012,0.659658,-0.528130,0.486222,0.254960,0.233446,-0.362409,-0.844061,-0.168863,-0.522685,-0.713691,-0.151938,-0.371594,-0.064852,0.106454,-0.191781,0.331171,0.115493,0.129590,0.152787,0.298179,-0.168657,-0.112268,0.533191,-0.432059,0.115771,-0.075784,0.382177,0.291974,0.149420,-0.209891,-0.393859,-0.203042,-0.067146,0.052834,0.031288,0.879932,-0.217355,-0.028521,0.063995,0.373561,0.005745,-0.284176,0.224576,0.351354,-0.007025,0.211504,0.039071,-0.147381,0.224435,0.186791,0.065492,-0.382546,-0.056637,-0.347698,0.029657,-0.559294,0.476159,0.236164,-0.035964,0.306279,-0.342238,0.255387,0.047843,0.153482,0.565469,-0.445414,-0.228384,-0.506749,0.027205,0.332709,0.010123,-0.100325,0.411719,0.136575,-0.449190,-0.150633,0.135200,-0.295700,-0.127341,0.178202,0.243446,-0.135504,0.019091,-0.778723,0.086661,-0.099381,-0.141599,0.055974,-0.341627,-0.523162,-0.415971,0.224078,-0.269142,-0.261529,0.409291,-0.029340,-0.212738,0.796711,-0.847617,0.286840,0.518909,0.016912,-0.259429,0.602112,0.066238,-0.200747,0.036007,-0.261279,-0.188676,0.042726,0.611579,0.119215,0.581320,-0.352828,-0.210329,-0.394727,0.373613', '1307146', '24839498', '3155839', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2272222', '耳朵大有福', '剧情', '东北某小镇，当了大半辈子火车修理工的大耳朵王抗美（范伟 饰）光荣退休。王本身患有气管病，老婆患病住院，儿子大军整天不务正业，女儿小萍跟丈夫春洋的婚姻也出现问题。虽然很多人说他耳朵大有福，生活美满，但时下的现状仍让他愁眉不展。拿着比原来少了一半的退休金，王总觉得心里没底，于是他开始琢磨找点儿事干。不过老王出师不利，老婆的病友给他介绍一个网络商务的工作，可没曾想竟是个传销组织，刚加入没多久便遭到警方取缔。在此之后，他又跟擦鞋女工、倒骑驴蹬车工、广告促销员、二人转演员、自行车修理工等各类手工艺者讨教赚钱之道，由此开始了自己别样的退休生活……©豆瓣', '范伟', '张猛', 8.1, 34269, 'tt1978472', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2404286339.jpg', 0.3, 1.8, 19.8, 48.3, 29.7, '0.200970,-0.070869,-0.448011,0.304868,-0.237700,-0.414075,0.407772,0.170456,-0.526990,-0.454115,-0.157234,0.553147,-0.206080,0.328062,-0.002943,0.007177,-0.218208,-0.431528,0.347759,0.097731,-0.215594,-0.131048,0.088406,-0.300877,-0.207924,0.117645,0.121568,-0.007238,-0.029441,0.110597,0.077576,-0.046601,0.399166,0.344889,-0.352761,0.124039,-0.026523,0.146409,0.063657,-0.117642,0.319494,-0.089728,-0.134641,-0.152222,0.289245,0.418149,0.244330,0.267808,-0.289995,-0.217149,0.214188,-0.144225,-0.032615,-0.106874,0.404704,0.240969,0.397455,-0.118669,-0.055225,-0.191275,0.013088,-0.042799,-0.417282,0.066165,-0.191070,-0.146108,-0.612495,0.043782,-0.229509,-0.008434,-0.054352,-0.128321,0.264338,0.477797,0.165200,0.461382,-0.083863,0.258991,-0.499864,0.512592,0.473252,0.078004,-0.018572,0.373906,-0.044888,-0.322720,0.175236,-0.056219,-0.332169,-0.064506,-0.008532,-0.243835,-0.412564,-0.112361,-0.269433,0.124106,0.040295,-0.165215,-0.001700,-0.337023,-0.195876,-0.248101,-0.066602,-0.235332,-0.105239,0.109266,0.395497,0.013629,0.586255,-0.584225,-0.008569,0.357497,0.185994,-0.834943,0.478019,0.250140,0.052475,-0.288938,-0.064734,-0.148495,-0.209518,0.425639,0.427414,0.301417,-0.046143,-0.507981,-0.165003,0.310282', '1421278', '1877596', '1302110', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22733673', '星运里的错', '剧情', '海泽尔（谢琳·伍德蕾 Shailene Woodley 饰）是一名十六岁的美丽少女，正处在黄金年代的她本该和其他同龄人一样尽情享受生命和青春带来的快乐与希望，但无情的病魔找上了海泽尔，她是一名肺癌患者。尽管最近病情有所好转，但海泽尔的心情却并没有因此而轻松半分，癌症随时可能复发的阴影和无法中断的治疗如影随形，让海泽尔对生命几乎失去了所有的热情和希望。一次偶然中，海泽尔在癌友互助会中结识了名叫奥古斯都（安塞尔·埃尔格特 Ansel Elgort 饰）的英俊男孩，他所患的是骨癌。两个境遇相似的年轻人很快就越走越近，他们在一起，探索着上帝留给他们的小小的一片世界，海泽尔也因此看到了未来和希望。©豆瓣', '谢琳·伍德蕾', '约什·布恩', 7.9, 104432, 'tt2582846', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2197680919.jpg', 0.4, 2.3, 24.6, 46.7, 26, '0.114716,-0.001485,-0.627949,0.630276,-0.143535,-0.303165,1.034003,0.065510,-0.545561,-0.152584,-0.151576,0.951580,-0.065409,0.521754,0.132252,-0.035697,-0.184433,-0.653848,-0.082344,0.064660,-0.483291,-0.495103,-0.397393,-0.087567,-0.251925,-0.619747,0.667753,0.238715,-0.048907,0.625221,0.159778,0.343915,-0.073154,0.765541,-0.257489,-0.225371,-0.014230,-0.045280,-0.232832,0.358638,0.262777,-0.109583,-0.043288,0.440357,-0.191884,0.336117,0.532398,-0.419787,-0.395029,0.025928,0.411745,-0.131526,0.071133,0.193552,0.217011,-0.135550,0.249344,-0.096946,-0.233896,-0.133739,0.015438,-0.091526,-0.809236,-0.063541,0.271880,0.413692,-0.579863,0.569411,0.133300,-0.269863,0.275640,-0.102751,0.299547,0.361463,0.238321,0.332886,-0.335090,-0.054044,-0.577125,0.061030,0.745025,0.150545,-0.466538,0.655699,-0.566159,-0.319908,-0.152205,-0.210940,-0.582467,0.105880,0.185512,0.364597,-0.169774,0.218385,-0.296002,0.224505,-0.291974,-0.180056,-0.175293,-0.412162,0.179529,-0.425802,-0.111453,-0.667967,-0.491381,0.160013,0.178900,-0.389972,0.879590,-0.868916,0.395520,0.471677,0.210449,-0.423118,0.679838,0.162561,0.162433,-0.168580,-0.170644,0.401120,-0.017389,0.173446,0.180217,0.350818,-0.254622,0.001907,-0.463174,0.756945', '1292062', '24756472', '4275444', '1291877');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22736358', 'SPEC：结 后篇', '剧情', '前人类和普通人类的人种战争已经到了白热化的阶段，野野村组长去世后，吉川（北村一辉 饰）、当麻纱绫（户田惠梨香 饰）和濑文焚流（加濑亮 饰）等人聚在未详总部，苦苦思索J教授的真身。谁知就在当麻刚刚弄清真相的同时，警察医院内的成年和儿童SPEC持有者遭到残忍屠戮。愤怒的当麻无法抑制体内被封印的SPEC，她狂乱暴走，继而现身御前会议。在犹大、世界（向井理 饰）、润（大岛优子 饰）的见证下，法蒂玛第三预言实现了。恐怖刺眼的蘑菇云在上空升起，成千上万的八尺乌遮天蔽日，被欲望所支配与荼毒的世界迎来了毁灭时刻。在命运的交叉点，当麻和焚流能否阻止世界的灭亡？©豆瓣', '户田惠梨香', '堤幸彦', 7.2, 12725, 'tt2798172', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2156823588.jpg', 3.2, 9.6, 34.5, 31, 21.6, '-0.090031,0.453178,-0.843887,0.112138,0.011597,-0.028207,0.695982,0.245280,-0.135896,-0.137484,0.304309,0.456135,-0.428770,0.158523,0.351175,-0.113686,-0.032117,-0.793152,-0.164349,-0.119989,-0.381732,-0.258005,-0.350493,-0.082556,-0.127401,-0.604155,0.895848,0.443401,-0.155855,0.194622,0.244907,0.645471,-0.343650,0.452021,-0.124692,0.084513,0.333219,-0.091633,-0.285058,0.230213,-0.185207,-0.169678,0.124955,0.385175,-0.210296,0.126591,0.851836,-0.630694,-0.013056,-0.321032,0.213093,-0.382838,-0.349513,0.412800,0.548144,-0.036177,-0.052988,0.160728,-0.185345,0.008068,0.030895,0.071250,-0.631351,-0.118290,0.181830,0.150819,-0.394612,0.315003,-0.007259,-0.291689,0.231732,-0.125531,0.037215,0.342740,0.157493,0.430143,-0.269792,-0.087311,-0.132447,0.177961,0.452424,-0.129147,-0.351250,0.231853,-0.152576,-0.245590,-0.442125,-0.231365,-0.123394,-0.226613,0.306548,0.372239,-0.256883,0.263819,-0.518254,-0.459113,-0.337875,-0.114538,0.116526,-0.294169,-0.407248,-0.419445,-0.282325,-0.145922,-0.217776,0.268730,0.188948,0.007654,0.557661,-0.782754,0.318531,0.449841,0.527706,0.069243,0.288086,-0.110080,-0.119636,-0.333882,0.055461,0.170669,0.095556,0.579096,0.194327,0.347192,-0.073566,0.248120,-0.431397,0.502458', '25774050', '26759819', '1438591', '11615927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2275370', '战略特勤组', '剧情', '前美军特种部队炸弹专家史蒂芬·阿瑟·杨格（麦克·辛 Michael Sheen 饰）正走向一条危险之途，作为穆斯林他不满美国对待阿拉伯国家的政策，于是策划发动恐怖袭击。他宣称在三个城市中分别安放了三颗小型原子弹，美国本土危在旦夕。FBI反恐部门女探员海伦·布洛迪（凯瑞-安·莫斯 Carrie-Anne Moss 饰）负责调查此案，却在紧要关头发现军方以及一个神秘部门介入其中。她的小队连同极度危险的谈判专家亨利·汉弗莱斯（塞缪尔·杰克逊 Samuel L. Jackson 饰）受命审讯史蒂芬。绰号H的亨利手段残忍严酷，加上政府高层的纵容他愈加有恃无恐。海伦反感这样惨无人道的非法手段，她想尽办法争取史蒂芬的信任，终于让他说出其中一颗炸弹的暗访地点。然而，一切并非如此简单，死亡与阴谋的狂潮随即袭来。在这场丧失人性的角力战中，注定没有胜利者……©豆瓣', '麦克·辛', '格雷格·乔丹', 7.9, 61166, 'tt0914863', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p498359093.jpg', 0.9, 2.7, 21.8, 49, 25.5, '0.299748,0.079372,-0.699858,0.609118,0.021417,0.181592,0.536694,-0.050250,-0.464294,-0.142923,0.464221,0.521605,0.033220,-0.113433,0.108822,-0.162511,-0.359728,-0.549758,-0.396599,-0.082437,-0.293803,-0.676176,-0.307899,-0.498663,0.006703,-0.025011,0.466733,0.206554,-0.249679,0.252389,0.302385,0.673467,-0.019624,0.375628,0.418094,-0.355140,0.552167,-0.332109,-0.384874,0.181769,-0.037406,-0.110984,-0.150623,0.411007,0.010538,0.551904,0.294045,-0.369340,0.081847,-0.355442,0.376148,-0.382685,0.004584,-0.005171,0.434377,0.067119,-0.070431,0.193657,-0.106256,0.073389,0.136031,-0.137077,-0.728485,-0.111738,-0.015959,0.241334,-0.213860,0.172461,-0.273952,0.436878,0.073096,-0.177166,-0.010838,0.254860,0.461809,-0.021468,0.074155,0.233599,-0.106557,0.077780,0.541567,-0.165121,-0.540538,-0.254574,-0.288594,-0.341600,0.136599,-0.277954,-0.189240,-0.145394,0.530558,-0.205330,0.125537,0.280048,-0.502403,-0.041275,-0.400862,-0.059288,-0.121154,-0.161613,0.041435,-0.848246,-0.002205,-0.173793,-0.304729,0.206830,0.019467,-0.029246,0.489360,-0.442087,0.054425,0.549151,0.097768,-0.470907,0.218128,0.099377,0.047993,-0.452140,-0.160378,0.503210,0.168702,0.099576,-0.000095,0.160146,0.091876,-0.146061,0.036960,-0.031108', '2028645', '1293433', '4014397', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22759660', '李碧华鬼魅系列：迷离夜', '恐怖', '《赃物》穷困潦倒的中年人关富强（任达华　饰）无工可开，渐入绝境，他怨天尤人，憎恨命运的不公。正所谓穷则思变，一生穷怕了的老关剑走偏锋，铤而走险盗取他人骨灰，企图勒索赎金求活。黑天黑地，人鬼难分；《放手》提倡音乐驱邪的风水师父何可（梁家辉 饰）迫于高昂租金准备关张，在最后一天他邂逅一对自称撞鬼的夫妇，因感事态复杂，遂将夫妇介绍给同行好友水晶占卜师王兰（陈慧琳 饰），但他的最后一天营业却没这么简单结束，紧接着一名紧握左手的学生妹找到何师父；《惊蛰》惊蛰祭白虎，朱婆婆（邵音音 饰）照例来到鹅颈桥下摆摊打小人。是夜，先后有阔太太（顾美华 饰）以及名为梁震婴（卢海鹏 饰）的客人上门。当朱婆婆准备收摊之时，一名面容阴森的少女坐在旁边，要求打小人报复三男一女。本片根据李碧华短篇故事改编。©豆瓣', '任达华', '任达华', 6.8, 21403, 'tt3054776', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2006602893.jpg', 1, 7.2, 51.6, 31.9, 8.4, '-0.037490,-0.090857,-0.183078,0.158509,0.002927,-0.213071,0.412251,0.398255,-0.072702,-0.410395,0.326160,0.209882,-0.123367,0.291988,0.358871,-0.148897,-0.006532,-0.217376,0.006889,0.048968,-0.054810,-0.236214,0.016704,-0.014132,-0.217509,0.177340,0.343675,0.049493,-0.112323,0.293416,0.330377,0.125606,-0.169464,-0.080451,-0.186421,-0.019093,-0.086373,-0.016771,-0.334354,0.054823,-0.113577,-0.154009,-0.150993,-0.109814,-0.109787,0.346890,0.578115,-0.188686,-0.069788,-0.042417,0.509339,-0.030648,-0.124328,0.204287,0.191300,0.129200,0.185717,0.059741,-0.194322,-0.161678,0.137247,-0.150985,-0.127658,0.224663,-0.021541,0.023493,-0.427953,0.216834,-0.218514,0.121948,-0.027063,-0.295696,0.145705,0.108928,0.220864,0.172195,0.150219,-0.054539,-0.167651,0.298710,0.243112,-0.074798,0.323550,0.204595,0.176317,-0.327780,0.204063,0.057636,-0.320086,-0.179674,0.526406,-0.123700,0.160840,-0.042703,-0.389443,-0.203631,-0.151803,0.295747,0.099748,0.024639,-0.190080,-0.386610,0.129557,-0.099975,-0.132212,0.212233,0.319718,-0.022890,0.386983,-0.238663,0.175923,0.044710,0.097170,-0.310822,0.450499,0.044846,0.144950,-0.313049,-0.127589,0.019947,0.141474,0.196516,0.205918,0.068978,-0.073064,0.059048,-0.120964,0.121193', '4268598', '25717233', '6874567', '1401900');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22759752', '李碧华鬼魅系列：奇幻夜', '恐怖', '《枕妖》在一次蛮不讲理的吵架过后，男友阮浩康（林家栋 饰）下落不明。失落的邹静怡（陈法拉 饰）懊恼不已，遍寻不见男友踪影，导致夜晚失眠，白天精神恍惚。为求睡眠，她从杂货铺买来一个药枕，谁知在睡上好觉之余，诡异的梦境也悄然而至；《迷藏》某座小学即将拆除，适逢好友Ceci即将生日，当年同在该校求学的肥强（陈耀荣 饰）等好友决定返回学校庆祝一番。可是他们没有听从校工陈伯（黎汉持 饰）的劝导在天黑前离开，甚至在漆黑的校舍里玩起了捉鬼游戏。不知不觉间，另外有“朋友”加入他们中间；《黑伞》落魄港府，泥泞湿漉，七月十四，人鬼同途。惨白的巷尾，走来身形佝偻的林伯（泰迪罗宾 饰），一路行走，一路感慨，人心凋零的年代，惟愿众生多多行善。不信鬼神和因果，作践了生前身后业。他知难而上，尽力行善。直至遇到站街北姑（莫绮雯 饰），一切骤变。©豆瓣', '陈法拉', '陈嘉上', 6.8, 21490, 'tt3105008', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2067205179.jpg', 1.2, 7.7, 50.7, 31.9, 8.5, '0.159624,-0.005082,-0.717794,0.042842,0.190892,-0.326357,0.573550,0.358717,-0.382650,-0.398588,0.116715,0.231884,-0.209457,0.345425,0.115212,-0.154785,-0.184220,-0.432693,-0.015974,-0.071587,-0.278603,-0.126648,-0.133006,-0.038239,-0.309521,-0.150395,0.357713,0.227238,0.157937,0.624305,0.303109,0.088497,-0.386749,0.373339,-0.252948,-0.124483,-0.022484,0.391084,-0.231007,0.047276,-0.184410,-0.350282,-0.162047,-0.294215,-0.046631,0.268537,0.702927,-0.037521,-0.101386,0.053817,0.414948,-0.053907,-0.191802,0.066294,0.450215,0.125197,0.124205,0.016936,-0.092761,0.029728,-0.204958,-0.161672,-0.142154,0.142451,0.027140,0.191577,-0.481154,0.439901,-0.038026,0.039886,0.113841,-0.485614,0.294263,0.288321,0.225825,0.223815,0.028890,0.098903,-0.396845,0.093540,0.345269,0.066430,0.074354,0.486285,0.069133,-0.074127,0.154188,0.171315,-0.379501,-0.244428,0.085760,-0.032450,-0.168817,0.124946,-0.372618,0.016187,-0.078812,0.049386,-0.045348,-0.060274,-0.277178,-0.301109,0.088053,-0.218707,-0.160329,0.304810,-0.007887,-0.061480,0.261230,-0.572129,0.455545,0.240882,0.132341,-0.166985,0.655672,-0.163475,0.234861,-0.098297,0.134836,0.361361,0.011070,0.414531,0.148610,0.151552,-0.287150,0.227965,-0.490773,0.163165', '1300945', '1451563', '1292211', '25