INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2276989', '出水芙蓉', '喜剧', '香港长洲岛是个小地方，人们生于斯长于斯，没有太大抱负也能享受安逸生活。但是偏偏出了个死心眼的“长洲美少女”罗娇（钟欣桐 饰），为了报情敌的一巴掌之仇，决心拉上几个好姐妹参加“出水芙蓉”4x100游泳接力赛夺下冠军。为此她绑架到“飞鱼王子”郭志远（方力申 饰），逼他训练自己和姐妹们：命犯天煞孤星的病秧子阿玉（黄圣依 饰），草食双胞胎“大花”（茜利妹 饰）与“小花”（朱熏 饰）。经过一番刻苦训练，加上阿娇无意中遇到“海上观音”（田亮 饰）赋予她的超能力，阿娇和姐妹们泳技飞涨，郭志远也慢慢对阿娇动了心，只是被她误会喜欢阿玉。比赛终于到来，“海上观音”显灵令阿娇他们获胜，而阿娇和郭志远的爱情却也随着志远被经纪人接走见了分晓……©豆瓣', '钟欣潼', '刘镇伟', 5, 10085, 'tt1500694', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1602821382.jpg', 15.6, 33.1, 38.8, 9.3, 3.2, '0.185487,-0.168368,-0.556206,0.385676,-0.165051,-0.416460,0.528339,-0.147666,-0.455659,-0.306637,0.205655,0.583366,-0.386902,0.158920,0.050589,-0.043701,-0.146969,-0.545575,0.143743,0.114812,-0.074626,-0.281139,-0.035635,0.122421,-0.184905,0.092700,0.424968,-0.299863,-0.000238,0.717333,0.379690,0.003818,0.225110,0.133130,-0.305769,0.220313,-0.072149,0.198588,-0.190194,0.115975,0.027737,0.023532,-0.337481,-0.046981,0.179677,0.049123,0.555467,-0.429013,-0.038791,-0.219402,0.104253,-0.353617,0.136222,0.144957,0.254014,-0.130858,0.297270,0.035929,-0.092669,-0.136126,0.008965,-0.237568,-0.170834,0.274559,0.306828,-0.017258,-0.334086,0.120182,0.153198,-0.140188,0.026620,-0.232940,0.063579,0.106360,0.300303,0.203673,-0.257715,-0.009642,-0.384979,0.282284,0.628866,-0.008795,0.130831,0.264585,-0.093681,-0.317762,0.157603,-0.318472,-0.558423,0.170632,0.296074,-0.137808,-0.021591,0.130273,-0.492047,0.104436,-0.353687,0.196552,-0.071299,-0.317426,0.177008,-0.371852,-0.029806,-0.627310,-0.414939,0.069824,0.176452,-0.302326,0.715160,-0.786967,0.088659,0.175055,0.192531,-0.598968,0.538487,0.203674,0.024497,-0.216187,0.088175,-0.005399,-0.166253,-0.062362,0.163692,0.385782,-0.083370,-0.204753,-0.219641,0.157954', '3445516', '1292219', '35030151', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2277018', '麦兜响当当', '喜剧', '长江三峡，考古学家掘出庞然巨物，手工奇劣，一看竟是麦子仲肥又一废物出土！麦子，名兜，字仲肥，是我国一位吃饱撑的思想家、发明家。正当大家不知如何处置这大而无当之物，一位怀疑是麦子十八代后人的小朋友，麦兜（郭君彦/张正中 配音），正与妈妈麦太（吴君如/宋丹丹 配音）一起在香港发呆。麦兜很慢，很乖，很钝，被评定为多元低智能。麦太也好不了多少，半辈子乱冲乱扑，却都在扑空。为了自己，为了麦兜，麦太决定带麦兜来内地闯天下。到了武汉，麦太忍痛先把麦兜送到山上一武术学校“太乙春花门”寄宿。山上生活清苦，掌门道长（黄秋生/张立昆 配音）呆头呆脑。麦兜无心习武，最大的乐趣是跟小同学偷入炼丹房煮方便面；值得庆幸的是，麦兜的身边还有一位可亲的助教“熊宝弟弟”，不时照顾麦兜。“世界幼儿园武术大赛”即将举行，“太乙春花门”小朋友软手软脚，看来只有挨揍的份儿。“国际幼儿园武术大赛”，麦兜迎战各地好打小朋友。这时，麦兜祖宗麦仲肥的巨物突然当、当、当的响起。原来这是个一年等于一秒，每三千六百年才报一次时的大钟…大成若缺，大器晚成。麦兜忽然领悟出太极拳，以至自己生命的道理……', '黄渤', '谢立文', 7.6, 102859, 'tt1430622', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2431279389.jpg', 0.9, 4.3, 31.5, 42.2, 21.2, '-0.137708,-0.231202,-0.447371,0.123451,-0.066186,-0.229951,0.061738,0.197906,-0.220119,-0.149860,0.143622,0.480280,-0.117081,0.439140,0.080071,0.065509,0.101929,-0.335786,0.022425,-0.080752,-0.259040,0.018883,-0.224393,0.012045,-0.146835,-0.009599,0.190285,-0.168247,-0.092635,0.217855,0.364955,-0.119325,0.050485,0.022645,-0.297098,0.008226,0.124749,0.148103,-0.154630,-0.094699,-0.068210,-0.183242,-0.335375,-0.281838,0.154612,0.068805,0.175731,-0.035021,0.007462,-0.099685,0.248022,-0.097874,-0.287857,-0.173424,0.337980,-0.003613,0.240787,-0.058855,0.241931,0.108289,0.126756,-0.362608,-0.338980,-0.051625,0.053692,-0.156641,-0.439848,0.212139,0.024456,-0.079634,0.039090,-0.355290,0.107500,0.071818,0.051197,0.508739,-0.198724,0.233416,-0.304330,0.370250,0.211958,0.004612,0.042086,0.295075,0.273703,-0.257426,0.437350,-0.271766,-0.228289,0.030431,0.189365,-0.172412,-0.158766,0.022900,-0.131693,0.031839,-0.066518,-0.183592,0.071053,-0.090799,-0.127948,-0.084226,0.188413,-0.058980,-0.008036,0.140940,0.227203,-0.039483,0.764067,-0.595180,0.281614,0.153793,-0.012528,-0.066234,0.545705,0.001269,0.004027,-0.211507,-0.023828,-0.133668,-0.040282,0.441003,0.236879,0.342367,0.107656,-0.270024,-0.383565,0.185747', '1908036', '27602116', '25922902', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2277019', '荒村客栈', '悬疑', '2002年，音乐学院大四的学生孟凡（关智斌 饰）在一次比赛上凭借原创歌曲《对不起，我爱你》一举夺得冠军，自此声名鹊起，还抱得美人归，与出色的女生何盈（何美钿 饰）在一起。几年后，他仍然无法创作出一首全新的代表作，爱情又迟滞不前。一天在网上看见一个叫“荒村”的地方，里面有一个“荒村客栈”，流传着关于明代一个叫胭脂的女子的故事。据说睡在明代那张床上，半夜会听见胭脂的歌声。孟凡决定前去寻找灵感，同时与何盈分手。荒村客栈的店主欧阳（薛山 饰）热情欢迎孟凡，在孟凡的要求下住进了胭脂的房间。孟凡开始见到明朝的鬼影，又噩梦连连。何盈来到荒村找孟凡，却被孟凡伤透心。欧阳跟孟凡讲起自己和妻子小枝（张檬 饰）的故事。不过渐渐地，孟凡发现，小枝这个人根本不存在。故事的最后，我们发现，一切都是因为那一首歌——《对不起，我爱你》。©豆瓣', '关智斌', '张菁', 3.9, 9170, 'tt1703058', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2371793040.jpg', 34.4, 40.7, 20.4, 3.1, 1.4, '0.306148,0.044302,-0.548771,0.569133,0.117785,-0.321866,0.770661,-0.054095,-0.668136,-0.279663,0.009815,0.580956,-0.350068,0.461082,0.293308,0.131860,-0.132616,-0.679679,0.078504,-0.186642,-0.241056,-0.353058,0.000610,-0.054373,-0.135603,-0.128565,0.387925,0.142499,-0.197062,0.519101,0.238208,-0.136202,-0.064731,0.307177,-0.133288,0.084719,-0.080358,0.277674,-0.221824,0.330658,-0.047907,-0.269444,-0.424567,-0.150146,-0.062250,-0.030012,0.444913,-0.226252,-0.018131,0.107365,0.423074,-0.061621,-0.177712,-0.120427,0.101942,-0.019733,0.486795,0.242590,-0.170311,-0.009630,-0.052061,-0.141136,-0.271424,0.108083,0.126209,0.297806,-0.515462,0.452018,-0.310485,0.097360,0.214917,-0.437168,0.301476,0.144136,0.334082,0.434820,-0.314104,0.077971,-0.672801,0.297884,0.340044,0.037087,0.183176,0.374115,0.252175,-0.462763,-0.194573,0.221976,-0.407457,0.244622,0.186264,0.047566,-0.286961,-0.282421,-0.490503,-0.122921,0.151542,-0.248704,0.144936,-0.335303,-0.249379,-0.432443,-0.109206,-0.054002,-0.193549,0.133560,-0.020438,-0.280470,0.637218,-0.707718,0.228770,0.375483,0.107964,-0.133240,0.468156,0.099771,-0.008421,-0.064762,0.050448,0.266412,-0.168769,0.272681,0.040211,0.411199,-0.168455,-0.134569,-0.617464,0.524930', '1296534', '1307146', '3111650', '1296332');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2277204', '异邦人：无皇刃谭', '动作', '在天下失序、列强割据的战乱时代，僧人祥庵将一名孤儿从中国带到了日本。孤儿名叫仔太郎，他背负着一个惊人的秘密。与祥庵失散后，孤苦无依的仔太郎带着爱犬飞丸前往赤池之国的万觉寺，在途中遇见了神秘剑士“无名”。仔太郎遭到追杀，危急时刻无名救了他一命。从此两人结伴同行。性格乖僻的浪人和紧闭心扉的少年虽然磕磕碰碰不断，但渐渐成了好朋友。白鸾率领的追杀组织还是抓住了仔太郎，他们开始着手筹备某种仪式。金发碧眼的剑士“罗狼”也是追杀组织中的一员，他虽然听命行事但并不真正在意组织的目的，对他来说，寻找可以与自己匹敌的对手才是生命的意义。罗狼与无名之间的生死对决拉开了帷幕……©豆瓣', '长濑智也', '安藤真裕', 8.6, 27757, 'tt1121794', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p456836953.jpg', 0.2, 0.9, 12.4, 42.4, 44, '0.144536,-0.011743,-0.428993,0.373200,0.003805,-0.069648,0.600398,0.143837,-0.551534,-0.111746,0.237721,0.648266,0.315721,0.068142,0.350820,-0.076870,-0.017687,-0.645098,-0.231078,-0.035795,-0.091260,-0.306772,-0.240312,-0.242455,-0.313282,-0.313864,0.829333,0.146320,-0.273213,0.576846,0.289726,0.299953,-0.283819,0.533016,-0.413518,-0.160004,0.119131,0.004825,-0.286753,0.307625,-0.361089,-0.302830,-0.212307,0.247043,-0.226043,0.573586,0.698515,-0.411415,-0.136606,-0.203875,-0.023995,-0.415611,-0.359150,0.098276,0.481770,0.038845,0.215844,0.370038,0.205429,-0.129687,-0.045199,-0.109654,-0.667977,-0.058112,0.351973,0.217794,-0.659569,0.393830,-0.228579,-0.172066,0.136362,-0.137000,0.309169,0.505385,0.254597,0.054434,-0.112781,0.047634,-0.339581,0.164588,0.901879,-0.219511,-0.185475,0.198434,0.150206,-0.422846,-0.105221,-0.254240,-0.253438,-0.165997,0.181482,0.036280,-0.439015,0.220586,-0.630020,-0.064090,-0.225996,0.035971,0.144452,-0.529180,0.110732,-0.405043,-0.171103,-0.581714,-0.426424,0.095734,0.163126,0.083047,0.891293,-0.863299,0.151741,0.634550,0.296036,-0.333827,0.616976,-0.051401,-0.027477,-0.187154,-0.170455,0.338281,0.210958,0.461988,-0.001439,0.448967,0.016287,-0.142129,-0.124138,0.235188', '35030151', '1826173', '3811356', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2277841', '兄弟', '剧情', '山姆（托比•马奎尔 Tobey Maguire 饰）到监狱接刑满释放的弟弟汤米（杰克•吉伦哈尔 Jake Gyllenhaal 饰）。回家后，母亲热烈欢迎，但父亲冷嘲热讽。山姆在美军海军陆战队服役，被派去阿富汗，因此这次聚会除了给汤米接风，也是在为山姆送行。父亲总拿完美的山姆跟差劲的汤米相比，令后者愤然离去。山姆依依不舍地跟爱妻格蕾丝（娜塔莉•波特曼 Natalie Portman 饰）和两个女儿告别，奔赴沙场。不幸的是，他所乘坐的黑鹰直升机被击落，他跟下属被俘。慑于阿富汗暴徒的淫威，山姆被迫就范，亲手杀害了下属，此事令他内心充满矛盾。后方以为山姆阵亡，全家人沉浸在悲痛中。痛醒的汤米决心改变自己，慢慢融入了家庭，不但父子关系有所缓和，而且还跟格蕾丝和孩子们相互抚慰，产生了微妙的感情。此时却传来了山姆幸存的消息……本片翻拍自2004年的影片《血海兄弟》。', '托比·马奎尔', '吉姆·谢里丹', 7.6, 24282, 'tt0765010', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230352738.jpg', 0.3, 2.3, 30.3, 52, 15.1, '0.087469,-0.183104,-0.900749,0.505003,-0.084557,-0.406418,0.689871,0.190751,-0.549667,-0.006463,0.269725,0.795929,-0.030967,0.301811,0.301803,-0.155891,-0.486366,-0.653092,-0.101989,0.187850,-0.236036,-0.505159,-0.028796,-0.322258,-0.111012,-0.428152,0.398950,-0.189781,-0.137021,0.699456,0.269737,0.564422,-0.189629,0.520880,-0.102195,0.188508,0.059312,-0.109240,-0.534716,-0.026430,0.132860,-0.123329,-0.143042,0.096845,0.126128,0.484102,0.676098,-0.044975,-0.114112,0.006817,-0.053805,-0.406117,-0.028083,0.156789,0.112822,0.075668,-0.007557,0.157539,-0.092674,0.012919,-0.003136,0.177829,-0.294227,0.097793,-0.063680,-0.174674,-0.616768,0.397534,-0.272309,0.068266,0.294780,-0.245261,0.284939,0.337316,-0.019362,0.381115,-0.281714,0.131944,-0.429524,0.163486,0.696863,-0.125302,-0.053475,0.007026,-0.258887,-0.418005,0.124824,-0.142409,-0.486514,-0.010700,0.477535,-0.020177,-0.037871,0.351898,-0.474866,-0.384124,-0.442638,-0.223603,-0.084626,-0.613467,0.096430,-0.562724,-0.152798,-0.415339,-0.329451,-0.003321,0.105054,0.001763,0.591868,-0.482758,0.347549,0.378314,0.151219,-0.515485,0.396924,0.122744,0.171857,-0.082997,0.047610,0.214734,0.247627,0.038467,0.384502,0.186191,-0.070919,0.014706,-0.337043,0.222611', '1300958', '3111650', '25723780', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2278017', '兄弟', '剧情', '谭颂尧（苗侨伟 饰）和谭颂舜（陈奕迅 饰）是黑社会老大谭信天（王志文 饰）的儿子，两兄弟年幼时被父亲安排分隔两地。尧长大后接手父亲的社团，并且锐意改革，一心想走上正途，可是帮会内九叔和儿子闫国区（汤镇业 饰）却不想放弃暴利的不法勾当，并对社团老大的位置虎视眈眈；另一边，警探奎（刘德华 饰）密切关注着谭家社团的一举一动，收集犯罪证据。谭信天被害去世，谭颂舜回到香港，他开车意外撞死九叔，在舜的女友庄晴（黄奕 饰）陪同下逃到泰国，却屡屡身陷险境，幸得亲信阿鬼（黄日华 饰）的搭救才得以生还。接连发生的事情，让谭颂舜心生疑惑，两兄弟之间的信任备受考验，而幼时“宣武门之变”的卦象似乎正在慢慢应验......©豆瓣', '苗侨伟', '赵崇基', 6.2, 23119, 'tt1121801', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1619165356.jpg', 2.3, 13.8, 58.2, 20.6, 5.1, '-0.052031,-0.262433,-0.582481,0.387287,0.285496,-0.319453,0.401573,0.299866,-0.752386,-0.225080,0.121553,0.404624,-0.119137,0.266926,0.170508,-0.162848,-0.226738,-0.823200,-0.082083,-0.117673,-0.094819,-0.476470,-0.111151,-0.147046,-0.146043,-0.135723,0.424871,0.061852,0.019642,0.588907,0.406027,0.364202,-0.581030,0.297626,-0.077166,0.098771,0.115996,0.194764,-0.565783,-0.124737,-0.001957,-0.352014,-0.217911,0.030881,0.225919,0.336448,0.594741,-0.084544,-0.288939,-0.213701,0.092607,-0.318682,-0.170904,0.024037,0.539392,0.113473,0.228916,0.593084,-0.088972,-0.127018,-0.027675,-0.040315,-0.422609,-0.108338,0.205051,0.125885,-0.676691,0.269717,-0.163667,-0.012915,-0.012445,-0.355122,0.291509,0.487510,0.206376,0.246715,-0.175593,0.153739,-0.248146,0.142662,0.641786,-0.169935,0.262369,0.102574,0.148201,-0.210230,0.002028,-0.146947,-0.415184,0.056960,0.328439,-0.065007,0.079300,0.189653,-0.209924,-0.193509,-0.196928,0.046159,0.081799,-0.314538,0.192408,-0.379842,-0.163738,-0.335823,-0.265145,0.388467,-0.027082,-0.231379,0.401630,-0.542248,0.199003,0.364959,0.412765,-0.783214,0.490161,0.043232,0.035546,-0.454876,-0.372633,0.033976,0.118241,-0.094801,0.002000,-0.064950,-0.209879,-0.345954,-0.170406,-0.170325', '27621189', '1482541', '1293265', '1410695');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2278795', '鬼怪屋', '喜剧', '绰号小尚的女中学生木枯（池上季実子 饰）迎来了快乐的暑假，当发现独身8年的父亲（笹沢左保 饰）交到新的女朋友（鰐淵晴子 饰）时，她拒绝和父亲前往轻井泽旅游，而是和6名同学相约前往香丽姨妈（南田洋子 饰）的庄园度假。姨妈年轻时曾和俊朗的青年（三浦友和 饰）相恋，但太平洋战争夺去了爱人的生命。从此香丽姨妈孤身一人，毕生等待爱人的归来。小尚她们的造访令孤独的姨妈分外高兴，这群青春活泼的女孩在山中尽情玩耍。然而，姨妈和庄园似乎隐藏着某种可怕的生物，少女们一个接一个地消失了……本片荣获1978年蓝丝带最佳新人导演奖。©豆瓣', '池上季实子', '大林宣彦', 7.5, 8218, 'tt0076162', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2157979027.jpg', 1.7, 5.4, 30, 41.9, 20.9, '-0.029550,-0.113538,-0.367741,0.580723,-0.177615,-0.407080,0.588724,0.199374,-0.489325,-0.416957,-0.014205,0.722819,-0.160913,0.715499,0.638801,0.125898,-0.003810,-0.524462,-0.160026,0.013336,-0.269050,-0.110044,-0.103255,-0.026803,-0.044719,-0.341668,0.541652,0.011964,0.091992,0.868138,0.321139,0.203364,-0.491737,0.290904,-0.283060,-0.094057,0.063849,0.392472,-0.283313,0.199375,-0.244931,-0.038840,-0.122500,-0.163856,0.050165,0.188399,0.825243,-0.186719,-0.110384,-0.127004,0.429381,-0.052885,-0.035277,0.042439,0.069681,-0.051881,0.236562,-0.009674,-0.201044,-0.094718,0.104791,-0.421587,-0.175239,0.146212,0.227616,-0.091079,-0.436603,0.453491,0.027287,0.083265,0.273138,-0.334784,0.183486,0.209527,-0.109715,0.366014,-0.154895,0.205698,-0.268209,0.532066,0.665792,-0.217582,-0.108668,0.121404,-0.202958,-0.254255,0.043358,-0.002981,-0.585350,0.092372,0.142808,0.081083,-0.012208,-0.103994,-0.791360,-0.166525,-0.139361,0.223766,0.376268,-0.410182,-0.260891,-0.579742,0.061499,-0.397420,-0.157839,0.276258,0.040678,-0.135660,0.774675,-0.768241,0.413505,0.290670,0.118799,-0.420982,0.814541,0.108952,0.061308,-0.311155,-0.078232,0.484105,0.103796,0.120177,-0.053246,0.128909,-0.437332,-0.003690,-0.508334,0.177373', '3811356', '3445516', '1303083', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2279152', '名侦探柯南：世纪末的魔术师', '喜剧', '小兰的朋友原子家铃木财团准备展出他们家珍藏的沙皇尼古拉二世家的宝物——回忆之卵，回忆之卵里收藏了沙皇尼古拉二世一家的珍贵照片，由此特别珍贵。岂料在展出之前，却收到了怪盗基德的通知函，上面用迷语的方式列明他盗宝的时间。原子找到小兰的爸爸名侦探毛利小五郎帮忙，当然，真正的幕后高手柯南也会和小兰一起前来。柯南遇到了同为侦探的服部平次，两人决定一起联手解开怪盗基德之谜！©豆瓣', '高山南', '儿玉兼嗣', 8.6, 119210, 'tt1067920', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453729256.jpg', 0.1, 0.5, 11.7, 45.1, 42.6, '0.401288,-0.041500,-0.259844,0.337154,0.110365,-0.390149,0.084863,0.101899,-0.384902,-0.401911,0.206771,0.699439,-0.031091,0.181526,0.070457,0.232873,-0.551511,-0.611463,0.115604,-0.271673,-0.114422,-0.312911,-0.250712,-0.185439,-0.067804,-0.152857,0.375944,-0.013087,0.314283,0.542295,0.077718,0.384737,-0.355000,0.069192,0.088263,0.186533,0.437568,-0.109890,-0.525784,0.343758,-0.012259,0.170354,0.139404,0.107084,0.468880,0.208146,0.183302,-0.136734,0.082962,0.049506,0.168266,0.107545,-0.090831,-0.000288,0.482874,0.115121,0.280924,0.398564,-0.248601,-0.297775,0.182407,0.065818,-0.650185,0.037315,0.280568,0.195136,0.034717,0.205059,-0.288102,0.174792,0.291296,-0.279027,0.311576,0.345022,0.454095,-0.122653,-0.075637,0.069020,-0.153943,0.253294,0.192460,-0.313705,0.431155,0.277815,-0.015816,-0.276103,-0.333141,-0.412743,-0.282830,0.234161,0.402492,0.038263,-0.093692,0.129412,-0.822692,-0.496529,-0.139728,0.143591,0.312357,-0.121810,0.120752,-0.797483,-0.199073,-0.007580,-0.139930,-0.028796,0.254661,-0.404138,0.937308,-0.363481,-0.055916,0.612855,0.295135,-0.113170,0.473305,-0.096833,-0.359363,-0.263638,-0.086312,0.037645,0.462150,0.338663,0.032807,0.122841,0.411804,-0.168594,-0.356620,0.161051', '27602116', '3318306', '3811356', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2279587', '棒子老虎鸡', '喜剧', '地产大亨王小虎（曾志伟饰）在大街上撞了一个捉鸡的老人，天上的热气球驾驶员李大春（夏雨饰）看见了这一幕，却并不知道那个老人就是自己的老丈人。大春打电话给老婆欢儿（梁咏琪饰）让她回家跟老丈人吃饭，被妻子断然拒绝。欢儿因为啤酒妹这份工作而被父亲赶出家门，一直心有怨气。老丈人因为撞击脑部有血块，需要马上做手术。窝囊的大春鼓起勇气三番四次向王小虎要钱都被赶出来。80后女孩糖糖（唐嫣饰）是小虎的情人，同时跟“钢琴家”乔邦（戚迹饰）恋爱。为了全国巡演乔邦跟高利贷借了30万，如今被高利贷追杀。为了替乔邦还债，糖糖自导自演了绑架案。棒子老虎鸡，一物降一物，这个连环套到最后，到底谁被降住了呢？©豆瓣', '曾志伟', '王光利', 4.6, 8464, 'tt1560136', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2364773520.jpg', 18.5, 39.9, 35.3, 4.8, 1.5, '0.054702,-0.200120,-0.555930,0.304904,-0.203111,-0.438104,0.463630,0.123510,-0.293116,-0.165126,0.054038,0.646043,-0.311411,0.420827,0.110671,0.114401,0.142384,-0.523216,-0.027070,0.142011,-0.336161,-0.061508,-0.043156,0.132003,-0.102614,0.224481,0.118667,-0.174766,0.031016,0.296385,0.497138,0.109936,-0.068006,0.361645,-0.256601,0.450925,0.049038,-0.023550,-0.008731,0.123705,0.387262,-0.260706,0.078100,0.089458,0.004196,0.308649,0.403342,0.006388,0.002970,-0.302491,0.130950,-0.211920,-0.073672,0.221926,0.183119,-0.096504,0.307670,-0.016722,-0.185644,-0.163828,0.312597,-0.014792,-0.373192,0.166787,-0.180022,-0.103338,-0.755811,0.370002,-0.242195,0.007723,0.127591,-0.306242,0.391463,0.272378,-0.020951,0.528331,-0.432405,0.057563,-0.707600,0.268611,0.490119,0.050650,0.389564,0.368760,0.036680,-0.058748,0.178642,-0.129148,-0.345719,0.167564,0.565180,-0.259798,-0.449122,-0.080447,-0.439124,-0.195278,-0.164466,-0.010648,-0.166035,-0.422127,-0.327940,0.011167,-0.021212,-0.194508,-0.052691,0.183934,0.177175,-0.022724,0.312905,-0.412629,-0.006562,0.697921,0.401966,-0.540721,0.610977,0.071446,-0.172471,-0.215942,0.076306,-0.459123,0.226230,0.421618,0.516333,0.232949,0.085726,-0.312953,-0.183312,0.278419', '1293908', '1306505', '1292584', '1309069');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2279772', '命运呼叫转移', '喜剧', '电影由四个独立的小故事组成。《误会》：陈局长（杨立新饰）、孙医生（徐峥饰）和孙大头（刘仪伟饰）本来是三个生活没有交集的陌生人，却因为阴差阳错在机场错拿了对方手机，而发生了接下来的混乱场面：陈局长本想与女网友搞一夜情，这个机会却葬送在了孙大头手中。而他却发现孙医生的病人正是自己的妻子，原来妻子眼中的婚姻早已千疮百孔。而孙医生，则陷入了黑帮漩涡当中。《生之欢歌》：宁灿（范冰冰饰）是个女歌手，由一直喜欢着她的岳为（王学兵饰）帮她写歌。然而，一场绝症袭来，让宁灿选择了默默离开。岳为知道了女友的死讯，为之颓废消沉，却意外收到了宁灿的短信回复。让人错愕惊叹的故事由此展开。《山区》：村里人都觉得老三（葛优饰）是个吊儿郎当的人。这天老三得到了一部画家（孙周饰）留下的手机，然而贫困落后的村里并不能让他顺利地享用到这个现代工具。他开始为这台手机四处奔忙，命运也随之发生了意想不到的转折。《山难》：奸商滕少延（邱心志饰）平日品行败坏道德低劣，在山难的生死边缘上，他打电话给自己的亲朋求助，却发现再没有人愿意相信他了，能否逃过死神掌心，对以往的恶行又该如何忏悔，此刻在他心中百感交集。', '葛优', '刘仪伟', 5.7, 54515, 'tt11108460', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2192303523.jpg', 6.1, 21.7, 54.4, 14.7, 3.1, '0.233209,0.142769,-0.656451,0.571141,-0.079161,-0.361609,0.810977,0.055312,-0.630366,-0.370146,-0.110710,0.444684,-0.105536,0.325827,0.011171,-0.113819,-0.191385,-0.587166,-0.074932,0.060670,-0.282751,-0.318378,-0.114439,-0.297488,0.016594,0.096294,0.340354,0.127794,-0.216258,0.404968,0.428550,0.161470,0.072690,0.608472,-0.046213,0.233670,-0.209892,0.097342,-0.143040,-0.046405,0.308063,-0.498758,-0.183311,0.467047,-0.005909,0.463275,0.640033,-0.013487,-0.377883,0.074957,0.351119,-0.270868,0.015459,0.115389,0.120225,-0.023905,0.203170,-0.217787,-0.067030,-0.085555,0.149658,0.146744,-0.631950,0.145526,0.011369,0.265467,-0.469187,0.297314,-0.270738,-0.003415,-0.134147,-0.422457,0.428580,0.213001,0.389849,0.403178,-0.233894,-0.120046,-0.422561,0.379852,0.610540,0.182463,-0.150379,0.351824,-0.226317,-0.560508,-0.089811,-0.128482,-0.488340,0.056357,0.360850,-0.031785,-0.063511,0.067825,-0.280531,-0.011728,-0.063718,-0.056600,-0.131446,-0.445714,-0.010877,-0.069475,-0.133991,-0.359056,-0.355313,0.167868,-0.042375,-0.207012,0.490645,-0.619515,0.090978,0.384848,0.095481,-0.579351,0.677144,0.090400,-0.021730,-0.233374,0.197499,-0.001235,0.088433,0.436761,0.397889,0.194213,0.055674,-0.233002,-0.280751,0.255803', '1301022', '25870679', '1296370', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2279811', '蓝与白形成的蔚蓝色', '剧情', '内山枫在学校经常被欺负，大家丢了自行车，丢了伞都怪她。还被恶意的嘲讽、羞辱。每次难过的时候她就冲上天台，想打开天台的门跳下去一死了之。然而天台的门锁很难打开，于是当她遇见会开锁的男生时便求他帮忙。可是他却说：我可以教你如何开锁，但是我不帮你开。学校调来了新的代课老师大内。大家都风传她少年时代也是被欺负的学生，所以从天台掉下来摔断了腿，于是她对内山的关怀就被认为是同病相怜的偏心。然而真相却恰好相反，而内山的痛苦也终于在某天迎来了爆发。©豆瓣', '宫崎葵', '高橋直治', 7.2, 5604, 'tt3945690', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2593518722.jpg', 0.6, 5.2, 41.9, 40, 12.2, '0.440860,0.002109,-0.634088,0.275061,-0.518266,-0.357441,0.379671,0.078230,-0.203357,0.244327,0.147293,0.649404,-0.116272,0.531111,-0.147737,0.420272,-0.111780,-0.624230,0.147631,-0.253888,-0.504068,0.042676,0.182305,-0.364860,0.033252,-0.034964,0.293428,0.114888,-0.528888,-0.034140,0.354704,0.091994,-0.017113,0.875768,-0.357398,0.020869,-0.156137,0.168454,0.473476,0.006477,-0.033225,-0.561285,-0.189854,0.221878,0.114974,0.343824,0.223500,0.229300,-0.154961,0.266302,0.263296,-0.464532,0.039451,0.213750,0.369671,0.003332,-0.025582,0.194551,-0.088259,0.078707,0.022747,-0.017640,-0.465663,0.091066,-0.142059,-0.262526,-0.872930,0.576182,-0.095117,-0.011195,0.151073,-0.173724,0.333595,0.099515,0.015432,0.298140,-0.418243,-0.141666,-0.695313,0.060000,0.552537,-0.402247,-0.234189,0.311297,0.131978,-0.167563,0.285011,-0.192277,-0.503579,0.060323,0.417125,-0.179602,-0.522123,-0.244908,-0.272630,-0.128463,-0.246596,-0.116224,-0.301166,-0.416589,-0.033220,-0.108614,-0.028147,-0.069378,-0.503027,0.073345,0.014157,-0.179713,0.659452,-0.690448,0.193978,0.565942,0.440555,-0.421755,0.819294,0.147554,-0.334604,0.252748,0.030483,-0.059413,0.035830,0.687737,0.346933,0.545901,0.253044,-0.341735,-0.326159,0.454998', '1307639', '1306801', '1853752', '1292719');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2279997', '海贼王剧场版4：死亡尽头的冒险', '喜剧', '曾经潇洒快活的草帽海贼团，如今因为路飞的大胃口也过上了入不敷出的拮据日子。迫于生计，他们求助于酒吧老板。而老板则指引他们走入一条深不见底的隧道。为了糊口，众人不顾死活向洞穴深处走去。到了尽头，他们来到一个空间甚为开阔的场所，这里云集了无数的海盗团伙。原来，近期正要举行海盗大赛。所谓海盗大赛，是几年才会举行的海盗王者的航行比赛，优胜者将有丰厚的奖金，与之相伴则是莫大的生命危险。巨额的奖金让路飞等人忘记危险，他们毅然报名参加。本次比赛不仅有巨人族、鱼人族，还有头号种子选手——令人望而生畏的加斯帕迪。这势必是一场精彩刺激的海盗大对决……©豆瓣', '田中真弓', '宇田钢之助', 8.1, 11247, 'tt1006926', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171251372.jpg', 0.4, 1.5, 20.1, 46.4, 31.6, '-0.063590,-0.151488,-0.639369,0.412083,0.028359,-0.219297,0.720319,-0.022271,-0.517234,0.169946,0.466144,0.869543,-0.292687,-0.005338,0.487701,-0.187038,-0.100385,-0.319298,-0.392834,-0.271269,-0.313993,-0.226196,-0.153572,-0.145239,-0.002061,-0.039423,0.588131,0.299392,-0.167644,0.676025,0.252790,0.061591,-0.096706,0.353823,-0.208809,-0.301315,0.210655,0.192507,-0.145039,0.054913,-0.318376,-0.341389,-0.319893,0.056107,0.334370,0.281860,0.613883,-0.258943,-0.253862,-0.042703,0.115667,-0.497910,-0.084668,-0.011004,0.498498,-0.127239,0.139384,0.155348,0.075852,-0.261415,-0.247649,-0.434702,-0.725801,0.161622,-0.000735,0.075261,-0.323370,0.574512,0.212392,-0.323785,0.087231,-0.206110,0.267747,0.389233,0.218068,-0.112000,0.030895,0.009838,-0.466168,0.267930,0.998316,-0.166452,-0.049572,-0.121088,-0.021645,-0.622504,0.123739,-0.416769,-0.384674,0.049109,0.599174,-0.075385,0.043298,0.148534,-0.709912,0.457670,-0.387183,-0.601304,-0.105030,-0.232541,-0.151961,-0.670636,0.253527,-0.082548,-0.142890,0.481106,0.183758,-0.250494,0.633562,-0.579381,0.204869,0.735802,0.357302,-0.467908,0.778393,-0.348601,0.347087,-0.085352,-0.277797,-0.009195,0.012838,0.517817,0.068181,0.233623,0.025222,-0.304410,-0.090591,0.322436', '3147969', '1294941', '25721544', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2280004', '海贼王剧场版5：被诅咒的圣剑', '动画', '在美丽的阿斯卡岛上，流传着这样一个传说：数千年前，岛民极为害怕红色满月的出现。为了消除恐慌，神赐予岛上的国王盾牌和七星剑，然而当七星剑和红色满月同时出现时，黑暗便会支配整个大地。暂时落脚阿斯卡岛的草帽海贼团遭到海军追捕，而此时原本守护船只的索隆却离奇消失。在娜美的坚持下，众人重返小岛，却来到一个陌生所在，继而遇见持有三颗美玉的美丽少女玛雅。另一方面，索隆在岛上的海军道场重逢当年的盟友萨卡。由于玛雅的关系，索隆和香吉士大打出手。而这一切，都和萨卡手中持有的七星剑有关。这把传说中的宝剑，其所隐藏的秘密渐渐浮出水面……©豆瓣', '田中真弓', '竹之内和久', 7.7, 11426, 'tt1010435', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p987661155.jpg', 0.5, 3.1, 30.4, 42.3, 23.7, '0.139514,0.215824,-0.901899,0.761270,0.260817,-0.108025,0.882746,0.124380,-0.173781,-0.401287,0.464041,0.622146,-0.043452,0.160071,0.278286,0.199556,-0.335156,-0.657100,-0.154057,-0.263277,-0.310276,-0.114669,-0.404642,0.219694,-0.288756,-0.566998,0.739658,0.263914,-0.021075,0.492508,0.054402,0.312645,-0.308076,0.226914,-0.276992,-0.239979,-0.121406,-0.010978,-0.228336,0.378868,-0.451356,0.036534,0.059432,0.339611,-0.029263,0.327438,0.729213,-0.556921,-0.063500,-0.252643,0.192141,-0.248533,-0.113836,-0.035530,0.412877,-0.010490,-0.046348,-0.247376,-0.368153,-0.229433,0.261892,-0.186718,-0.594719,0.245406,-0.054853,0.284447,-0.452296,0.234365,-0.121647,-0.042880,0.142039,-0.320011,0.529620,0.389359,0.065075,0.069111,-0.189198,0.140692,-0.548000,-0.083973,0.684485,-0.168005,-0.240417,-0.112415,-0.149186,-0.349920,-0.330223,-0.063391,-0.031614,-0.080177,0.410540,0.158785,0.244288,0.556617,-0.709123,0.033758,-0.295897,-0.129094,0.113137,-0.263393,-0.430987,-0.426343,-0.089848,-0.233004,-0.385838,0.109183,0.114864,-0.069203,0.546368,-0.674454,0.625029,0.187978,0.156460,0.035121,0.406945,0.089354,0.152906,-0.309460,-0.505047,0.571363,0.343865,0.457087,-0.121716,0.084704,-0.016061,0.191387,-0.486090,0.362873', '21619567', '1467779', '11615927', '3626364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2282449', '魔法奇幻秀', '喜剧', '几世纪前，帕纳索斯博士（Christopher Plummer 饰）还是一名德高望重的僧侣，他在与世隔绝的荒山野岭中讲述永恒的故事。某天，魔鬼尼克（Tom Waits 饰）不请自来。在他的引诱下，帕纳索斯与魔鬼作赌注，最终如愿得到永恒的生命。时间到了现在，博士带着由女儿瓦莲蒂娜（莉莉·科尔 Lily Cole 饰）、青年安东（Andrew Garfield 饰）、侏儒波西（Verne Troyer 饰）组成的奇幻马戏团周游各地。就在女儿将满16岁时，尼克再次出现。原来，博士曾爱上一个女子（Lily Cole 饰），但永恒的生命却没有永恒的青春，为了和爱人厮守，他又和魔鬼作了一次愚蠢的赌注，而他恢复青春的代价就是要将第一个孩子献给魔鬼。践约的日子越来越近，烦恼的博士再与魔鬼作赌，只要他最先收集到5个灵魂便可保住女儿。这时，落魄的东尼（希斯·莱杰 Heath Ledger 饰）适时出现……', '安德鲁·加菲尔德', '特瑞·吉列姆', 6.9, 38434, 'tt1054606', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p754505225.jpg', 1.6, 8.4, 44, 34.6, 11.4, '0.001857,0.110197,-0.436790,0.580651,-0.354164,-0.619812,1.015551,0.051266,-0.320682,-0.065881,0.370596,0.783741,-0.038579,0.170593,0.477392,0.226113,-0.310782,-0.651108,-0.039236,-0.232490,-0.192622,-0.515034,-0.335320,0.079901,-0.049224,-0.499161,0.623601,-0.067252,0.334028,0.387188,0.238768,0.217886,-0.031695,0.242144,-0.299230,-0.015002,0.138621,0.014858,-0.245380,0.365047,0.151015,-0.125365,-0.171334,0.222277,-0.467109,0.269326,0.624818,-0.703677,0.121790,-0.165099,0.269270,-0.195478,-0.144673,0.140890,-0.068297,-0.264422,0.089381,0.235952,-0.246727,-0.079802,0.250808,-0.170839,-0.787438,-0.027725,-0.027952,0.243937,-0.568336,0.352135,-0.019919,0.086452,0.376614,-0.458506,0.133670,0.166537,0.349322,0.368784,-0.342879,-0.125685,-0.453284,0.424548,0.451208,-0.096219,-0.273631,0.331312,-0.238552,-0.434277,-0.050312,-0.268541,-0.674823,0.012766,0.091954,0.120150,-0.159806,0.268301,-0.782129,-0.027026,-0.442940,-0.045112,0.135737,-0.283660,-0.298322,-0.276822,-0.212370,-0.131047,-0.234221,0.143876,0.198829,-0.181727,0.785691,-0.734026,0.389386,0.695774,0.158418,-0.157490,0.705452,0.005231,0.132389,-0.367410,-0.072285,0.381737,0.030179,0.564116,0.066700,0.218253,0.006645,0.056039,-0.339438,0.622123', '26884422', '21619567', '30401849', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2284481', '简·奥斯汀的遗憾', '剧情', '英国广播公司BBC制作《简-奥斯汀的遗憾》，以剧情片的诉述形式，独家披露简-奥斯汀的信件、日记和她的小说，重现这位女文豪的浪漫一生，走进她鲜为人知的内心世界。影片的背景设定在简·奥斯汀(奥莉维亚·威廉姆斯 Olivia Williams 饰)即将步入40岁之际，侄女范妮（伊莫琴·普茨 Imogen Poots 饰）请这位写过无数爱情小说的姑妈做参谋，帮忙挑选丈夫人选。一方面简既坚持婚姻关系中爱情不可缺少的地位，一方面长期拮据的生活又让她深知缺乏经济基础的爱情不会有善果。而简这些矛盾的态度也令范妮迷惘。简年轻时也曾有过真心相爱的人，可最后仍因经济原因各奔东西。而对真实爱情的崇拜又让她拒绝了富裕绅士的求婚。 最后简选择了不嫁的单身生活，她将对爱情的热情融入自己的创作中。选择了不一样的自由生活，到底她有没有后悔过呢？©豆瓣', '伊莫琴·普茨', '杰里米·洛夫林', 8.1, 6567, 'tt1076240', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1556361921.jpg', 0.3, 1.4, 21.4, 49.5, 27.5, '0.215875,-0.015299,-0.562966,0.879134,-0.290512,-0.377277,0.713711,0.000939,-0.359389,-0.438115,-0.125394,0.744703,-0.098373,0.285967,0.229879,0.082762,-0.060850,-0.466353,-0.034651,-0.037744,-0.132338,-0.527464,-0.283710,-0.612596,-0.109390,-0.072176,0.542993,0.121221,-0.446800,0.155362,0.311356,0.298848,0.021774,0.398350,-0.000186,0.019028,0.017481,0.463268,-0.407531,-0.119011,0.132825,-0.338545,-0.098090,0.307134,0.155156,0.264379,0.535178,-0.244097,-0.168843,0.053081,0.587066,-0.091044,-0.023457,0.171044,-0.079037,-0.011009,0.028677,0.260166,0.029902,0.000534,-0.047006,-0.292482,-0.934119,-0.301027,0.206075,0.100981,-0.572027,0.472014,-0.202979,-0.081836,-0.107529,-0.241219,0.127685,0.295253,0.462374,0.180569,-0.041350,0.016118,-0.323948,0.591217,0.692950,0.252641,-0.385545,0.329136,-0.709952,-0.509900,0.023734,-0.092768,-0.851502,0.028436,0.183811,0.223201,-0.123503,0.224198,-0.421864,-0.133742,-0.121322,0.000398,0.079819,-0.649859,0.122865,-0.320952,-0.293205,-0.789672,-0.425133,-0.231049,0.010102,-0.499022,1.005666,-0.614303,0.105155,0.348675,0.260828,-0.831219,0.820198,0.517676,-0.032197,-0.253317,0.052589,0.543668,-0.261289,-0.052848,0.047431,0.097709,0.133849,-0.061039,-0.337581,0.699206', '26348103', '1303542', '27602116', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2284851', '精英部队', '剧情', '号称世界上最危险的城市——巴西里约热内卢，警匪枪战时有发生。恶徒肆意横行，死亡如同家常便饭，甚至警匪沆瀣一气，危害城市。但就在这个混乱所在，却有一支刚正严明的部队横空出世。特别警察军事行动部队（Special Police Operation Battalion）凭借其果敢凶狠的办案作风而令匪徒闻风丧胆。时1997年，教皇即将来此视察，高层要求纳斯西蒙（Wagner Moura 饰）所率领的这支精英部队在最短时间内肃清贫民窟内的毒品链。厌倦刀光血影的纳斯西蒙将心思放在了妻子和尚未出世的婴儿身上，他将任务交给了两个热血且充满理想的年青人——内图（Caio Junqueira 饰）和马提阿斯（André Ramiro 饰）。他们俩都不满警察队伍的腐败，决心在精英部队中大展身手……本片荣获2008年柏林国际电影节金熊奖。©豆瓣', '瓦格纳·马拉', '何塞·帕迪里亚', 8, 47348, 'tt0861739', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p912245002.jpg', 0.5, 1.8, 19.8, 51.4, 26.5, '0.220594,0.089919,-0.766256,0.465001,0.215986,0.121716,0.657189,0.029937,-0.540637,-0.146269,0.351941,0.401415,0.221220,-0.155026,0.371863,-0.368201,-0.301583,-0.806718,-0.481340,-0.346590,-0.121475,-0.302912,-0.490489,-0.278715,-0.020498,-0.444836,0.705538,0.352371,-0.150701,0.378377,0.238944,0.280700,-0.153345,0.386722,-0.077163,-0.467809,0.312637,-0.014851,-0.379123,0.093508,-0.330772,-0.132786,-0.100088,0.166800,0.086316,0.101722,0.772512,-0.456739,-0.071706,-0.356388,0.207944,-0.312684,-0.212082,0.020934,0.566546,-0.045342,0.185374,0.181308,0.051730,0.201113,-0.150096,-0.246272,-0.749889,-0.249613,0.131617,0.072210,-0.490317,0.372122,-0.135920,0.139380,0.023892,-0.098245,0.250605,0.424859,0.232767,0.165369,-0.019386,-0.027036,-0.635964,0.174972,0.565018,-0.235313,-0.219599,-0.255147,-0.332465,-0.540847,-0.118632,-0.499118,-0.362987,-0.026205,0.263774,-0.298077,-0.015383,0.417266,-0.645316,0.039880,-0.007350,-0.301433,-0.066264,-0.218446,-0.071161,-0.616559,-0.068706,-0.179602,-0.161191,0.231414,0.244666,0.263368,0.718776,-0.629567,0.158823,0.431177,0.115157,-0.439034,0.466136,-0.012611,0.216670,-0.304077,-0.326040,0.240926,0.259592,0.415504,-0.011494,0.406491,-0.349219,-0.488581,-0.125393,0.286864', '10467125', '25928048', '257