INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2286009', 'PK.COM.CN', '剧情', '影片的剧本改编自网络小说《谁说青春不能错》，打出青春题材互动电影的招牌，从剧本到演员的挑选都采用了网络海选的形式。外科医生张文礼（房祖名 饰）麻木地过着无趣的生活。心中始终忘不了大学时的好朋友季银川（陈柏霖 饰）。这个每当他对生活感到绝望的时候都会带给他力量的朋友自大学毕业之后就再未出现过。同学聚会满心期待会出现的季银川却一直没有来，反而见到了季银川的恋人吴羽飞（牛萌萌 饰），却得知他们分手很久了。两人一起回忆往事，张文礼慢慢发现，吴羽飞爱的人可能是自己！最后，吴羽飞告诉张文礼一个惊人的事实——季银川已经死了。而杀死季银川的人，就是张文礼！这一切是真的吗？是别人的记忆出了错，还是自己的回忆背叛了自己？一切都扑朔迷离……©豆瓣', '房祖名', '小江', 7.1, 10906, 'tt2936212', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2462377498.jpg', 3.3, 10.3, 34.1, 33.6, 18.8, '-0.016201,-0.032473,-0.889929,0.754225,-0.131118,-0.431718,0.700823,-0.047433,-0.659323,-0.296470,-0.020144,0.594204,-0.434891,0.559710,0.254188,0.061150,-0.108308,-0.901003,-0.104325,-0.158137,-0.515919,-0.258498,-0.114391,-0.414275,-0.026333,0.000625,0.531908,0.502890,-0.236621,0.241284,0.361367,-0.098778,0.114640,0.790606,-0.148332,0.173857,-0.229873,0.237702,-0.158617,0.011169,0.363049,-0.393235,-0.185718,0.360919,0.114558,0.313203,0.705188,0.148813,-0.307206,0.322540,0.372859,-0.312188,-0.110998,-0.030626,0.121605,-0.216982,0.160087,-0.081909,-0.057459,-0.037677,-0.220301,0.064159,-0.735963,0.051629,-0.046307,0.218932,-0.465566,0.449017,-0.110206,0.093778,0.023200,-0.371887,0.445713,0.134234,0.592696,0.393581,-0.128621,-0.097462,-0.559587,0.599453,0.779546,0.062517,-0.317450,0.528354,-0.450206,-0.523994,-0.410999,-0.017442,-0.425754,0.295796,0.079336,0.220551,-0.360933,0.298859,-0.379782,-0.195862,0.207890,-0.057980,0.130787,-0.599803,0.122092,-0.377406,-0.288150,-0.540870,-0.407382,0.233781,-0.116340,-0.380672,0.708043,-0.855830,0.208407,0.379653,0.248168,-0.524771,0.759540,0.316375,-0.229811,0.004370,0.258953,0.357312,-0.148569,0.269518,0.270840,0.282630,0.275856,-0.140504,-0.458118,0.728560', '1301022', '3230462', '1870682', '34973399');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2286133', '冬之蝉', '剧情', '在幕末的动乱时期，在这个危机的时代，开国论者草加十马（三木真一郎 配音）和德川幕府的幕臣秋月景一郎（森川智之 配音）相遇了。二人一相遇便互生好感。草加更是对秋月的理念赞赏有加，而秋月则欣赏草加的开明和前瞻性。在草加去伦敦学习的前夕，互生情愫的二人终于向对方传达出自己的情意，约定回来后相见。但当二人再次相见时，却是在战场上。而此时的秋月却已断了双腿，被战败弄得意志消沉。草加将秋月安排到了自己家，悉心照顾。但身处对立面的二人终究抵不过这时代的悲剧。就像这“冬之蝉”，生在了错误的季节，终究逃不掉悲剧的命运。本片改编自新田佑克老师漫画《拥抱春天的罗曼史》的前传《冬之蝉》。共有三部分别是《江户恋歌》、《虾夷战记》和《东京悲话》。©豆瓣', '森川智之', '松本佳久', 8.8, 12766, 'tt14330332', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503152349.jpg', 0.3, 0.9, 10.9, 34.5, 53.4, '0.213369,0.083480,-0.797542,0.532307,0.261558,-0.404435,0.534589,0.363562,-0.212347,0.006606,0.328007,0.690130,-0.147733,0.151862,0.439023,-0.062908,-0.251793,-0.833793,-0.153775,-0.356376,-0.224107,-0.347574,-0.019826,0.166048,-0.174834,-0.123587,0.730510,0.089646,-0.090092,0.698213,0.191925,0.210453,-0.165231,0.514115,-0.003149,0.144380,-0.018765,0.095447,-0.480387,0.194596,-0.044840,-0.263644,-0.328236,0.186672,-0.017068,0.425901,0.668285,-0.375246,-0.166032,-0.057549,0.512472,-0.259514,-0.107923,0.245954,0.466214,0.042433,0.080036,0.248662,-0.077520,-0.069111,-0.190196,0.006286,-0.611264,0.162701,0.091310,0.123300,-0.523624,0.538514,0.227489,-0.130019,-0.045757,-0.294298,0.178964,0.317719,0.319178,0.509043,-0.347376,0.070174,-0.190732,-0.107238,0.528281,-0.070608,-0.314860,0.442009,-0.062132,-0.303849,-0.077179,-0.122392,-0.413478,-0.186859,0.315944,0.091438,-0.066128,0.221699,-0.543711,-0.172697,-0.074540,0.104529,0.238546,-0.318307,-0.040553,-0.435327,-0.244503,-0.698643,-0.583967,0.201722,0.459903,-0.204158,0.900513,-0.762213,0.007094,0.479405,0.190775,-0.379666,0.613342,0.346868,0.043105,0.016966,0.079992,0.295598,-0.223711,0.454651,0.317498,0.506846,-0.010165,-0.026453,-0.614472,0.362189', '3811356', '1826173', '26809007', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2286642', '名侦探柯南：贝克街的亡灵', '动画', '这日柯南、小兰一行人来到米花市市政大厅，一场有关最新游戏“茧”的发布会正在这里召开。由于迥异于以往任何一款游戏的“茧”可能一举改变全球游戏业界的价值观，发布会吸引了代表日本上流社会的政治、财经、演艺界人士，50名游戏体验者也多是他们的后代，新一的父亲、推理小说大师工藤优作由于参与故事编写，也来到现场。这边热热闹闹，游戏的研发者兼负责人坚村却被杀于地下室。坚村死前留在键盘J、T、R上的血迹令柯南想到答案可能在游戏中，他利用优作的关系加入了体验者队伍，小兰、灰原哀等人也拿到了体验入场券。50名体验者刚分别进入一个外型酷似蚕茧的“大型胶囊”，游戏即被自称“诺亚方舟”的人工智能控制，“诺亚方舟”称游戏将提供5个完全真实的历史场景，体验者可选择其中之一进入，被淘汰会进入休眠状态，若最后无人走到终点，他们的大脑组织皆会被摧毁，此举是为令日本社会重生。柯南一行及几个骄横无礼的上流社会公子哥进入的是19世纪伦敦的贝克街，那里杀人犯开膛手杰克正在兴风作浪，他身上正有柯南要找的答案！而优作也在现实中正对案件展开调查。', '高山南', '儿玉兼嗣', 9, 203593, 'tt0990372', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453731188.jpg', 0.1, 0.6, 7.6, 30.2, 61.6, '0.260972,0.337205,-0.462438,0.350396,-0.037837,0.109681,0.399814,0.016295,-0.642242,-0.277588,0.208507,0.713946,-0.366029,0.080295,0.322537,-0.103591,-0.273699,-0.456465,-0.146612,-0.324743,-0.289859,-0.279785,-0.152425,-0.225787,-0.121642,-0.160761,0.758720,0.001757,-0.463208,0.390098,0.202090,0.184402,-0.377398,0.311581,0.040884,-0.222697,0.293879,-0.034907,-0.437357,0.244438,-0.276243,-0.089435,0.136613,0.086663,-0.022147,0.064438,0.722698,-0.217587,-0.095340,-0.009323,0.591610,-0.169570,-0.292120,-0.211546,0.457557,0.178180,0.117986,0.297454,0.136167,0.251703,-0.081110,-0.098476,-0.831277,-0.046414,0.087271,0.223543,-0.104618,0.200612,-0.047033,-0.146384,-0.162277,0.013611,0.273211,0.194469,0.577513,0.252032,0.049350,0.062581,-0.402919,0.147209,0.487197,-0.154522,-0.259041,0.263677,0.018466,-0.591482,-0.243099,-0.310989,-0.072811,0.100504,0.097791,0.026565,-0.291723,0.101599,-0.550336,0.136479,-0.140789,-0.342171,0.188745,-0.246658,-0.142582,-0.978272,0.011876,0.071175,-0.182267,0.084910,0.215963,-0.408985,0.583728,-0.787181,0.110162,0.547356,0.086326,-0.646158,0.728497,-0.064579,0.013708,-0.353635,0.012929,0.326048,0.289637,0.473055,-0.234692,0.278808,-0.131399,-0.325682,-0.391117,0.323205', '2369613', '26313740', '24751811', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2287938', '钢琴之森', '剧情', '刚转学到乡下的雨宫修平（神木隆之介 配音），是一个励志成为钢琴家的小学5年级学生。刚进新班级就被班上同学捉弄了，同学一濑海挺身而出替他解围（上户彩 配音），两人从此相识。在一之濑海的带领下，雨宫修平见到了一架被舍弃森林中的钢琴，并发现这架钢琴只有一濑海能弹出悦耳的琴声。音乐老师阿字野（宫迫博之 配音），在听说海能够弹响这架钢琴之后，却表现出了出人意料的激动。原来，那架钢琴正是阿字野丢弃的。一濑海知道许多音乐家的曲子，当他回到森林演奏时，发现只有肖邦的小狗圆舞曲无法演奏。于是，第二天便拜托阿宇野教自己演奏小狗的方法，却被教导弹音阶。在几天的练习后，终于如愿以偿的能弹小狗了。作为回报，海答应完成阿宇野的一个愿望——参加全日本钢琴大赛的地区预选赛，他能通过预赛，并弹出属于自己的心灵音乐吗……本片改编自日本漫画家一色诚的同名漫画。©豆瓣', '上户彩', '小岛正幸', 7.9, 19490, 'tt1119194', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1010604997.jpg', 0.3, 1.8, 25.5, 49.3, 23.1, '0.345134,0.117283,-0.521433,0.557103,-0.106211,-0.289393,0.310147,0.028496,-0.250779,-0.308210,0.117953,0.738426,-0.176135,0.515251,0.246552,-0.132741,-0.139194,-0.753193,0.074671,-0.152296,-0.212479,-0.249577,0.263923,0.178988,-0.026118,-0.422101,0.661875,-0.021568,-0.289957,0.620174,0.203921,0.061874,0.024066,-0.014722,-0.266088,-0.132144,0.276621,0.220151,0.073882,0.126809,-0.251671,-0.230390,-0.153559,-0.136069,-0.022656,0.101645,0.814602,-0.014782,0.132363,0.064809,0.489199,-0.135033,0.102323,-0.256699,0.285249,0.178657,0.159151,-0.010041,-0.163989,0.322185,-0.303860,-0.258016,-0.587398,0.206554,-0.161016,-0.005940,-0.263809,0.245589,0.064622,-0.095602,0.199405,-0.179084,0.322080,0.000807,0.216625,0.498374,-0.441205,0.350536,-0.270781,0.278037,0.627471,-0.248451,-0.283042,0.510871,0.127730,-0.626596,0.055526,-0.388956,-0.188051,0.225275,0.299765,0.058455,-0.064543,-0.491922,-0.433727,-0.264860,-0.154552,-0.314226,0.168515,-0.537771,-0.194600,-0.681083,0.228904,0.092834,-0.124787,0.017772,0.058165,-0.425289,0.919966,-1.047365,0.192582,0.425131,-0.181842,0.057614,0.478908,0.034113,-0.199484,-0.085046,0.153099,0.077486,-0.017318,0.422990,0.005619,0.506743,0.095055,-0.270377,-0.752700,0.373479', '3811356', '26784898', '25922902', 