INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22939161', '星际迷航3：超越星辰', '动作', '柯克船长（克里斯·派恩 Chris Pine 饰）和企业号的船员们来到了银河系中未知的一个区域，开始完成他们5年的任务——探索新世界，寻找新物种。却在途中滞留异星，遭遇了当地种族追杀，他们必须找到方法离开这个星球。', '克里斯·派恩', '林诣彬', 7.4, 140699, 'tt2660888', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377455123.jpg', 0.8, 3.9, 34.1, 44.5, 16.7, '0.245270,0.332176,-0.617234,0.515762,-0.003418,0.109572,0.458197,-0.336611,-0.379416,-0.292402,0.012511,0.760470,0.180900,0.258826,0.421671,0.099743,-0.730231,-0.252385,0.096495,-0.477957,-0.826560,-0.259812,-0.471536,-0.700632,-0.015610,-0.350411,0.951267,0.346966,0.105522,0.201252,-0.226988,0.450558,-0.475945,0.619067,-0.313814,-0.006328,0.695746,-0.155212,-0.306896,0.428287,-0.529150,0.004238,-0.273366,-0.056262,0.055959,0.413998,0.727402,-0.334471,0.099388,-0.509589,-0.096953,-0.412662,-0.101822,-0.260541,0.508346,-0.197933,-0.129424,0.442560,0.032688,0.297995,-0.126845,-0.309367,-0.777058,-0.119730,0.125097,0.259820,-0.387493,-0.095900,-0.084435,0.137317,-0.103354,-0.574410,0.289452,0.525213,0.469562,0.176186,-0.099258,0.104212,-0.491219,0.005039,0.730189,-0.408191,-0.328517,-0.001159,0.020123,-0.736936,-0.111842,-0.072521,-0.247351,-0.078955,0.396567,0.414368,-0.286924,0.307010,-1.254791,0.251826,-0.541791,-0.880447,0.101815,-0.280077,-0.291418,-1.134945,0.195249,-0.049720,-0.325234,0.381843,-0.124326,-0.173456,0.926312,-0.658098,-0.003880,0.860438,0.504592,-0.990404,0.831351,-0.086266,0.471025,-0.729166,0.184445,0.417603,-0.139204,0.825147,-0.310453,0.095126,-0.079961,0.084320,-0.367345,0.459845', '26290398', '2159244', '3401684', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2294565', '拉贝日记', '剧情', '1937年，在中国南京生活多年的德国商人拉贝（乌尔里奇·图克尔 Ulrich Tukur 饰）与妻子多拉准备回国。他把在西门子中国分部担任的职务交给继承人，然而就在当天的欢送舞会上，日军开始轰炸南京城，到处烧伤抢劫，引起南京暴乱。恐慌的居民四处逃散，拉贝毅然打开公司大门 收留中国员工及其他难民。南京城的外国传教士、医生、商人们商议在南京建立一个“南京国际安全区”来保障无辜百姓的安全，拉贝被推举为主席。本来第二天决定回国的拉贝决定要留下来，去拯救无辜的老百姓。当他目睹日本帝国主义的军队对南京人民施加的惨无人道的暴行时，拉贝更加积极地与同伴们和日军斗智斗勇，试图挽救更多的生命。越来越多的难民涌入安全区，这完全超出了他们的想象。与之同时，日军的暴行更加疯狂，拉贝的人道救助引起他们的不满，安全区多次受到日军的冲击，补给变得越来越艰难。几十万的无辜百姓等待拉贝去拯救，巨大压力下拉贝怎样去完成这人性的使命？', '乌尔里希·图库尔', '佛罗瑞·加仑伯格', 7.5, 32007, 'tt1124377', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p488186582.jpg', 0.5, 3.3, 35.2, 44.3, 16.7, '0.187494,-0.062721,-0.686774,0.296222,0.073150,-0.068401,0.503216,0.119331,-0.408839,0.024194,0.251958,0.705987,0.115599,0.042275,0.084787,-0.306679,-0.591499,-0.524160,-0.215192,-0.011024,-0.193851,-0.355809,-0.144290,-0.631054,-0.219567,-0.349087,0.552199,0.403685,-0.178100,0.440179,0.149565,0.310372,0.005255,0.584034,-0.109921,-0.104997,0.192232,-0.256108,-0.430609,0.017984,-0.078857,-0.294159,-0.250738,0.260178,0.101029,0.131314,0.668399,-0.126389,-0.115306,-0.272122,0.392052,-0.563495,0.079923,0.273802,0.337633,0.212182,-0.066489,0.171706,-0.250699,0.006952,-0.139868,-0.154194,-0.648056,-0.130774,0.187285,0.050035,-0.519604,0.480038,-0.016792,0.170449,0.231723,-0.378932,0.103264,0.861849,-0.159466,0.328768,-0.286268,0.173152,-0.452306,0.218927,0.873165,-0.297867,-0.182023,-0.249413,-0.192658,-0.298715,0.221058,-0.350316,-0.408738,-0.136666,0.261466,-0.325740,-0.062556,0.385216,-0.775362,-0.104847,-0.379634,-0.710369,0.095640,-0.167227,-0.081864,-0.905669,-0.029002,-0.114363,0.005917,0.240292,0.238824,0.142326,0.907227,-0.545769,0.030669,0.698389,0.547291,-0.784417,0.348930,0.087934,0.155568,0.063946,-0.254931,0.280361,0.321619,0.811714,0.062122,-0.047439,-0.102688,-0.135839,-0.129951,0.189047', '6007281', '1306723', '2159244', '3871833');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2294568', '南京！南京！', '剧情', '1937年12月13日，时为国民政府首都的南京城沦陷，部分官员弃城逃亡，但仍有许多官兵留守，誓死保卫这个大厦将倾的城池。宋锡濂部军官陆剑雄（刘烨 饰）协同战友与日军展开了激烈的巷战，他们微弱而顽强的抵抗最终被压制，数以万计的中国军民成为俘虏，在枪炮声中血染长江；金陵女子学院安全区，女教师姜淑云（高圆圆 饰）奔波往复，尽力帮助和拯救所有来此避难的同胞，但兽性大发的日军早已虎视眈眈盯上了藏身于此的妇女；拉贝的秘书唐先生（范伟 饰）小心应付，委曲求全，为了保护家人而做出错误的选择，他也为此付出代价；舞女小江（江一燕 饰）纵使逃亡避难也不愿抛却女性的柔媚，她在关键时刻的选择则在其女性的外壳下注入一份刚强；日本人角川（中泉英雄 饰）随部队进驻这个千疮百孔、破败不堪的城池，在这个人间炼狱，他的心灵感受到前所未有的巨大冲击。狼烟滚滚，血流成河，大时代的背景下，人们既要承受时代的无情给予，也要做出攸关命运的痛苦抉择……', '刘烨', '陆川', 7.6, 173347, 'tt1124052', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p470463541.jpg', 2.1, 4.6, 27.9, 43.9, 21.5, '-0.062734,0.068567,-0.565219,0.447739,-0.053567,0.162714,0.602441,0.176712,-0.391231,-0.030905,0.498696,0.517056,0.248203,-0.065339,0.271391,-0.229887,-0.109936,-0.591915,-0.221910,0.066706,-0.195507,-0.250625,-0.216632,-0.312637,-0.161582,-0.257529,0.932994,0.530739,-0.207591,0.314004,0.124227,0.241230,-0.114712,0.453423,0.032008,-0.167237,-0.195170,-0.191645,-0.222616,0.115388,-0.191634,-0.359758,-0.139766,0.187000,-0.211915,0.365462,0.766580,-0.333977,-0.113722,-0.172951,0.520315,-0.412115,0.024578,0.226855,0.223399,-0.071640,-0.105379,0.048958,-0.187517,-0.107891,0.107187,0.034112,-0.619787,-0.239188,0.375569,-0.000023,-0.575947,0.515337,0.075691,0.176680,0.051268,-0.202256,0.063921,0.463960,0.041353,0.237618,-0.404847,-0.140447,-0.367000,0.261517,0.778063,-0.058382,-0.438059,-0.359339,-0.342664,-0.276278,0.088339,-0.499362,-0.664315,-0.230160,0.035475,0.024938,-0.026437,0.327448,-0.512602,-0.049621,-0.400732,-0.269689,-0.088837,-0.302254,-0.152175,-0.564512,-0.113345,-0.262771,-0.115586,0.301574,0.214618,0.120673,0.892695,-0.624394,-0.011585,0.591513,0.432870,-0.526962,0.553668,0.048446,0.200975,0.085268,-0.063632,0.541668,0.048842,0.362039,0.074286,0.056668,-0.361315,0.098739,-0.304895,0.1