INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2295401', '詹妮弗的肉体', '喜剧', '妮蒂（阿曼达•塞弗里德 Amanda Seyfried 饰）和詹妮弗（梅根•福克斯 Megan Fox 饰）是从小一起长大的好朋友，妮蒂其貌不扬，对朋友马首是瞻；詹妮弗是学校啦啦队队长，风光无限，追求者众，她们共同生活在偏僻的魔鬼壶小镇。某晚，一支名为Low Shoulder的摇滚乐队来到小镇唯一一间酒吧Melody Lane演出，詹妮弗拉着好友一同前往。演出伊始，酒吧即发生严重火灾。妮蒂侥幸逃生，却眼睁睁看着已经吓傻的詹妮弗被乐队成员拉进汽车，绝尘而去。当晚，浑身是血的詹妮弗出现在妮蒂的家中，从这天起她的脾气变得张扬怪异。她开始诱惑校内的男生，并将他们杀害、吃掉。小镇人民尚未从大火的悲剧中解脱出来，又被接二连三的凶杀案给击倒。倍感疑惑的妮蒂慢慢知道了大火之夜发生在詹妮弗身上的一切……©豆瓣', '梅根·福克斯', '卡瑞恩·库萨马', 5.5, 55445, 'tt1131734', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1021513414.jpg', 7, 29.2, 48, 11.9, 3.9, '0.120249,-0.018344,-0.665237,0.109401,0.077062,-0.058346,0.963413,0.203822,-0.416318,-0.125165,0.116215,0.715601,-0.487801,0.360690,0.547660,-0.119493,-0.306823,-0.676781,-0.213494,-0.290474,-0.190615,-0.268210,0.038047,-0.291207,0.259315,-0.475750,0.473748,0.012832,-0.110415,0.597686,0.478331,0.393982,-0.465936,0.313536,-0.226225,0.091998,0.008768,-0.083920,-0.161436,0.161569,-0.258552,-0.109644,-0.145863,-0.121732,0.391977,0.144646,0.866404,-0.176006,-0.181320,0.116164,0.359683,-0.279798,0.020287,-0.040509,0.387848,-0.185338,0.099657,-0.100990,-0.001983,-0.239969,0.137848,-0.247323,-0.388102,0.239605,-0.002434,0.202486,-0.655814,0.651738,0.134323,-0.026365,0.323875,-0.271846,0.293071,0.189781,0.097249,0.424879,0.012173,0.048912,-0.480302,-0.100450,0.755582,-0.112171,0.091419,0.235441,-0.346312,-0.247086,-0.050501,0.088350,-0.483668,-0.017330,0.426504,0.022272,0.012532,0.142920,-0.418328,-0.193962,-0.205984,-0.242995,0.180722,-0.481484,-0.136819,-0.717678,-0.061147,-0.142683,-0.151982,0.038309,-0.229485,-0.013349,0.521904,-0.657003,0.313603,0.495769,0.178541,-0.119961,0.383664,-0.135405,0.134853,0.082174,-0.052637,0.502381,0.294565,0.331537,0.202939,0.518241,-0.328462,0.020090,-0.363139,0.210285', '26687241', '21619567', '10466639', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22964524', '咏春小龙', '剧情', '本片取材于国际功夫巨星李小龙的少年传奇轶事。正处于青春叛逆期的小龙（王小龙 饰），桀骜不训，到处惹事生非，在一次打架事件中得罪了香港政府要员，不但被就读学校开除，父亲（元华 饰）跑遍全港也没有学校愿意收留他。就在父亲一筹莫展的时候，小龙却迷恋上了习武，一心想拜咏春大师学徒，恰巧大师（郑忠 饰）是父亲的故交。大师了解了下小龙的情况后，决定收留小龙，并告诉父亲他有一个教化小龙的计划。小龙在习武过程中逐渐明白思想的重要性，学会了做事和思考的关系，最终转变成一个德艺双馨的少年。在一次全港比武大赛中，他战胜了三年卫冕的冠军，取得了比赛冠军，并被香港著名学校特招入学。©豆瓣', '元华', '秦瑞明', 2.5, 8961, 'tt2187209', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2022882774.jpg', 86.6, 8.2, 2.1, 2.1, 1, '0.120312,0.090592,-0.524404,0.519640,-0.046622,-0.438264,0.186022,-0.109226,-0.635845,-0.288962,0.270519,0.739530,-0.131292,0.283446,0.187428,-0.305991,0.051901,-0.607849,0.132599,-0.220651,-0.103345,-0.550231,-0.190498,0.330557,-0.101974,-0.426319,0.652040,0.078927,-0.377186,0.743439,0.215030,-0.166388,0.243056,0.323697,-0.040205,-0.070003,0.353226,0.200800,-0.232796,0.273618,0.024971,-0.251731,-0.169837,0.074465,0.171224,0.303675,0.513943,-0.094205,-0.044746,-0.174019,0.388064,-0.133512,-0.258619,0.176357,0.507566,0.110907,0.317356,0.338932,0.047587,0.177607,-0.174545,-0.175846,-0.430099,0.022262,0.165735,0.088754,-0.667622,0.694360,0.046520,-0.051426,-0.136572,-0.303029,-0.007874,0.160357,0.185216,0.231028,0.034550,-0.010101,-0.324081,0.468904,0.521082,-0.239462,-0.056928,0.304508,-0.009627,-0.472650,0.079060,-0.459475,-0.273701,0.170452,0.186137,-0.156914,-0.346345,0.165822,-0.031931,-0.036631,-0.210257,-0.123628,-0.059380,-0.236319,-0.039014,-0.353665,-0.077619,-0.108597,-0.356690,-0.120834,-0.003791,-0.344097,0.730718,-1.149175,0.157056,0.398485,0.246208,-0.448244,0.797041,0.199412,0.152018,-0.245145,-0.187060,-0.046034,-0.023639,0.327192,-0.092977,0.429078,0.091144,-0.417940,-0.264339,0.412862', '35030151', '1306544', '3445516', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2297262', '甜蜜幼儿园', '喜剧', '专栏作家鲁多（Til Schweiger 蒂尔•斯威格 饰）及其摄影师朋友莫瑞兹（Matthias Schweighöfer 马提亚斯•施维赫夫 饰）是一对无孔不入的小报记者，他们以窥探名人隐私为己任，为达目的怪招迭出。在拍摄著名球星求爱过程时，鲁多不慎搅乱了整个仪式，并因此被控上法庭。严厉的法官判鲁多服刑8个月，在此之前还要进行300小时的社区服务，而他服务的地点则是一家社区幼儿园。美丽的幼儿园女老师安娜（Nora Tschirner 诺拉•茨切纳 饰）和鲁多是老相识，但她小时候因为长相平平而经常受到鲁多一班坏男孩的嘲弄。同年冤家再次相逢，他们之间又会发生怎样的故事呢？©豆瓣', '蒂尔·施威格', '蒂尔·施威格', 7.2, 8204, 'tt0960790', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p770852205.jpg', 1, 5.1, 41.1, 40.5, 12.2, '0.336186,-0.335259,-0.262055,0.435454,0.097740,-0.070817,0.487099,0.213769,-0.576232,-0.239671,0.151887,0.701967,-0.638629,0.127392,0.322737,0.089922,-0.365536,-0.679213,0.100415,-0.341479,-0.172171,-0.584024,0.036437,-0.136246,-0.028215,-0.244266,0.209177,-0.270722,0.026353,0.247550,0.315688,0.365164,-0.019028,0.197586,0.143912,-0.183585,0.039668,-0.145049,-0.207580,0.089462,-0.021412,-0.025226,-0.218354,-0.143811,-0.009498,0.318438,0.703700,-0.082768,-0.007603,-0.244601,0.502400,-0.173275,0.156114,0.011067,0.378990,-0.197390,0.481632,0.254764,-0.066940,-0.103868,0.207888,-0.310681,-0.357570,0.268445,0.112435,0.055783,-0.201407,0.307986,-0.049390,0.132261,0.154725,-0.079723,0.016984,0.393148,0.401745,0.356606,0.117518,-0.096350,-0.286993,0.150677,0.508718,0.260441,-0.238360,0.291141,-0.424808,-0.397693,0.064319,-0.383771,-0.592760,0.178564,0.008790,-0.052967,0.014314,0.393720,-0.402811,-0.121124,-0.260730,0.116111,0.045810,-0.372527,-0.159242,-0.932380,0.071554,-0.373153,-0.131234,-0.031956,0.186350,-0.113584,0.587687,-0.824679,0.039421,0.613313,0.241355,-0.271471,0.922921,0.049236,0.070834,-0.165418,-0.349380,0.123283,0.187692,0.171856,-0.125563,0.247944,0.115865,-0.166367,-0.013659,0.192569', '24751811', '26259202', '3326747', '1292894');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2297265', '浪潮', '剧情', '赖纳•文格尔（Jürgen Vogel 饰）是德国某所高中的老师，该学校正在进行“国家体制”的主题活动周。由于他最喜欢的“无政府主义”课被另一位老师捷足先登，因此他只能主讲“独裁统治”课程。对于自由散漫的学生们来说，任何课程都只是为了学分而上。他们在课上大声聊天，无心听讲。文格尔别出心裁提出假想“独裁”的实验。在为期一周的实验中，文格尔被置于至高无上的地位，学生们对他要绝对服从。从最初的玩乐心态，这些青年男女渐渐沉湎这个名为“浪潮”的组织中，他们体会到集体和纪律的重要性，却在不知不觉中滑向了“独裁”与“纳粹”的深渊……本片根据真实事件改编，并荣获2008年德国电影杰出剧情片和最佳男配角奖（Frederick Lau）。©豆瓣', '于尔根·福格尔', '丹尼斯·甘塞尔', 8.7, 260536, 'tt1063669', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1344888983.jpg', 0.2, 0.7, 9.4, 41.6, 48.1, '0.404809,-0.070312,-0.560217,0.668857,-0.135816,-0.072420,0.432842,-0.155369,-0.633857,-0.352222,0.065477,0.583033,-0.071823,0.305627,0.359498,-0.364420,-0.426523,-0.846485,-0.273550,-0.189264,-0.332148,-0.555736,0.056665,-0.227338,-0.326857,-0.182780,0.915283,-0.180374,-0.577569,0.301759,0.463020,0.386497,0.062191,0.252228,-0.140372,-0.404235,0.294021,-0.021322,-0.268429,0.089331,0.019119,-0.334569,-0.389330,0.170897,0.136503,0.221949,0.747948,-0.326820,-0.182408,-0.105054,0.661121,-0.498579,-0.261431,0.259977,0.566784,0.216548,0.212375,0.360229,0.285295,0.427145,-0.223678,-0.384663,-0.717460,-0.211798,0.055621,0.265319,-0.283577,0.625410,0.203179,-0.238319,0.037346,-0.050819,-0.023704,0.251078,0.075341,0.392312,-0.232597,-0.211776,-0.235750,0.499083,0.511146,0.123356,-0.436724,0.291027,-0.294862,-0.619120,0.083356,-0.352375,-0.276873,-0.205079,0.001975,0.155510,-0.065680,0.335969,-0.627852,0.145816,0.259317,-0.524432,0.035204,-0.407892,0.065692,-0.838615,-0.034173,-0.409384,-0.352403,0.064286,0.190700,-0.235731,1.011219,-1.140191,0.231053,0.552071,0.166892,-0.555152,0.668685,0.223444,0.205996,-0.313989,-0.332514,0.083796,0.020015,0.400089,-0.206231,0.463084,0.092896,-0.452574,-0.373738,0.538446', '1826173', '1316589', '25922902', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2297275', '马利和我', '剧情', '约翰（欧文·威尔逊 Owen Wilson饰）和珍妮（詹妮弗·安妮斯顿 Jennifer Aniston 饰）是一对正沉浸在幸福中的伉俪，婚后不久，他们前往佛罗里达州的西棕榈海岸的生活，并各自在新闻界找到满意的工作。按照传统的模式，这个已经步入正轨的家庭可以迎接新成员的到来了。不过约翰夫妇似乎对此尚未做好准备，在朋友萨宾斯坦（埃里克·迪恩 Eric Dane 饰）的建议下，约翰决定送给妻子一条黄色的拉布拉多犬，以此作为育儿之前的演练。这条名叫马利的小家伙就这样进入约翰的家中，它调皮捣蛋，不知疲倦，给约翰夫妇惹来不少的麻烦，却也同时成为这个家中不可或缺的一员……本片根据报纸专栏作家约翰·杰罗甘（John Grogan）的畅销书《马利和我：和世界上头号捣蛋狗的幸福生活》改编，并荣获2009年百代电影电视奖最佳电影音乐奖。©豆瓣', '欧文·威尔逊', '大卫·弗兰科尔', 7.9, 49585, 'tt0822832', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p957046790.jpg', 0.3, 1.9, 23.9, 48.8, 25.1, '0.267979,-0.074715,-0.522907,0.633549,0.066648,-0.391494,0.475399,0.156844,-0.479293,-0.326153,-0.019460,0.782761,-0.070555,0.327499,0.454674,0.022144,-0.508317,-0.644343,-0.085921,-0.134239,-0.027247,-0.440437,-0.369744,-0.172455,0.014866,-0.283295,0.625738,-0.073297,-0.006745,0.728554,0.358417,0.191301,0.046411,0.222063,-0.303815,0.219179,0.137456,0.010685,-0.458206,0.204543,-0.009126,0.112248,0.001276,0.124562,0.335476,0.300927,0.657984,-0.423894,-0.198172,-0.025850,0.350779,-0.170635,0.040031,0.136593,0.381247,0.029316,0.319186,0.174989,-0.143080,0.202187,-0.216414,-0.282936,-0.912898,-0.062288,-0.048086,0.145035,-0.585570,0.419270,-0.121800,0.014318,0.105896,-0.341634,0.221835,0.461026,0.210539,0.442605,-0.019362,0.201987,-0.416872,0.266046,0.502579,0.171758,-0.021814,0.356631,-0.215727,-0.353412,-0.091538,0.011793,-0.494616,-0.139052,0.342550,0.121834,-0.037557,-0.015529,-0.610041,0.046247,-0.111739,-0.476995,0.286316,-0.423964,0.064272,-0.887828,0.100185,-0.289599,-0.198172,-0.076919,0.062003,-0.264336,0.688415,-0.707445,0.444448,0.225262,0.042604,-0.348113,0.803339,0.180472,0.251662,-0.461186,-0.220801,0.147916,0.161669,0.280077,0.033850,0.278387,0.143410,-0.390010,-0.518768,0.535838', '4301278', '1293656', '3318306', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2297877', '水啸雾都', '动作', '狂虐的飓风向苏格兰内陆步步紧逼。泰晤士水闸首席设计师罗伯（罗伯特·卡莱尔 Robert Carlyle 饰）和前妻——水闸工程总监萨米（杰萨琳·吉尔西格 Jessalyn Gilsig 饰）被叫回到水闸做安全检查，而罗伯心怀芥蒂疏远的父亲莱纳德教授（汤姆·康特奈 Tom Courtenay 饰）根据自己丰富经验测算并料定一旦洪水袭来，泰晤士河水闸必将被击溃。他及时将此情况报告给了危机控制中心的纳什女士。然而他的警告并未到重视，危机控制中心的专家不能准确地判断情况，不置可否的副首相竟向人们承诺洪水不会抵达伦敦市区。洪峰3小时后到达了伦敦，滔天骇浪跃过水闸，数亿吨的洪水急速奔涌进中央伦敦，顷刻间一片汪洋。数百万伦敦人危在旦夕。罗伯特，萨米和莱纳德只有几小时来挽救这座城市……©豆瓣', '罗伯特·卡莱尔', '托尼·米歇尔', 5.5, 9590, 'tt0790665', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2877975432.jpg', 7.4, 29, 48.6, 12, 3, '0.184137,-0.026970,-0.716143,0.380382,0.278371,-0.162382,0.486068,0.219552,-0.599723,-0.103888,0.289946,0.388691,-0.215631,-0.147344,0.287109,-0.083219,-0.490845,-0.491041,-0.075156,-0.240667,-0.247235,-0.536590,-0.259882,-0.398278,0.284558,-0.368232,0.206633,0.223312,-0.000741,0.291588,-0.098103,0.605812,-0.003154,0.541730,0.045951,0.046005,-0.007289,-0.278715,-0.346487,0.522192,-0.139694,-0.090084,-0.058601,0.126846,0.019972,0.606839,0.446574,-0.049625,-0.078052,0.012928,0.304165,-0.324561,0.336242,0.204875,0.406109,-0.144552,-0.148349,0.177866,-0.399869,-0.147921,-0.160967,-0.283660,-0.045296,-0.179985,-0.261754,0.289929,-0.491281,0.149188,-0.293045,-0.127206,0.000687,-0.041589,-0.299517,0.014611,-0.039410,0.424400,-0.268585,0.029147,-0.420985,-0.033374,0.617921,-0.066101,-0.332476,0.042461,0.147425,-0.194915,0.017573,-0.106927,-0.254409,0.029383,0.288718,0.315920,0.084763,0.305505,-0.328351,-0.150060,-0.663832,-0.297282,-0.097555,-0.071106,-0.084686,-0.844066,0.124962,0.077522,0.121779,-0.075032,-0.081553,0.233814,0.390213,-0.282313,0.015805,0.378668,0.409929,-0.017226,0.582375,-0.316655,-0.067790,-0.464097,0.288210,0.302796,0.109048,0.679267,0.175740,0.235153,0.112794,-0.383511,0.084028,0.351005', '3871833', '2079017', '1297659', '3735015');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2299395', '皮帕李的私生活', '剧情', '本片根据丽贝卡·米勒的小说改编。布蕾克·莱弗利饰演少女时期的皮帕·李。丽贝卡的丈夫影帝丹尼尔·戴-刘易斯以布景师的身份参与了这部影片的拍摄。在五十岁的时候，皮帕·李（罗宾·莱特·潘 Robin Wright Penn 饰）已经和一名很有才气的出版商人结婚了30年，有两个事业成功的双胞胎儿子，还有一个她很敬重的朋友兼邻居。但是，丈夫决定退休后要离开纽约搬到郊区过田园生活，而且皮帕·李发现丈夫还与一个比她年轻得多的女人有染，在生活遭到打击的情况下，她回忆起自己的过往，发现了自身的真正需求，以相当大胆方式揭露了丈夫的另一面，也给自己找到了生活的另一条出路……©豆瓣', '基努·里维斯', '丽贝卡·米勒', 6.9, 9075, 'tt1134629', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p708783210.jpg', 0.8, 6.4, 49.9, 34.1, 8.8, '0.168723,-0.224080,-0.520819,0.962343,-0.288067,-0.483420,0.897681,0.078023,-0.252116,-0.583596,0.159688,0.893721,-0.240461,0.502831,0.387077,-0.195769,-0.381671,-0.488966,0.050479,-0.186253,-0.369691,-0.385969,-0.385313,-0.275678,-0.302910,-0.289653,0.682777,-0.163842,-0.334689,0.066734,0.374301,0.129687,0.216449,0.475283,-0.306315,0.274873,0.006953,0.205263,-0.269602,0.307443,0.230422,-0.273929,-0.139563,0.069580,0.074839,0.526033,0.641243,-0.041967,-0.169821,-0.000787,0.577035,0.036329,0.017675,0.107961,0.467740,-0.130459,0.086327,-0.048981,-0.248442,-0.107204,-0.142739,-0.285880,-0.692960,-0.091495,0.280139,-0.019542,-0.714596,0.131506,-0.190676,-0.023094,0.107026,-0.596116,0.134191,0.374719,0.150969,0.402979,-0.066166,0.091552,-0.613178,0.397108,0.691240,0.280795,-0.212960,0.326721,-0.402123,-0.678493,-0.068181,-0.160331,-0.604146,0.121110,0.387555,-0.198729,-0.017703,0.078903,-0.484932,-0.095241,-0.058882,-0.188088,0.075304,-0.484851,0.145418,-0.751596,-0.287726,-0.739248,-0.201248,-0.037488,-0.001114,-0.623190,0.839094,-0.746060,0.119771,0.315686,0.275217,-0.772913,0.868590,0.186160,0.207588,-0.381790,-0.069098,0.402222,0.122896,0.031166,0.182545,0.352795,-0.099204,-0.291383,-0.271723,0.657478', '3055049', '1456503', '30162520', '1793922');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('22994672', '狐仙丽莎煞煞煞', '喜剧', '纯情护士丽莎，平日除了贴身看护行动不便的老太太，就是和幻想中的70 年代日本偶像歌手谈天说地。30 岁生日这天，她决定将脑中的浪漫化为行动，出去寻找真爱。就在她短暂外出时，老太太竟意外身亡。平常不闻不问的家属们以为丽莎谋财害命而报警处理，却查无犯罪事实。只不过此后跟丽莎交往的人，也都一一死于非命，让迷恋日本文化的她忍不住怀疑自己就是传说中带来厄运的「狐仙」，只有无私的真爱才能化解悲惨的宿命。问题是谁的八字硬到足以克除她身上的诅咒呢？融合日本元素与东欧文化的情节，别出心裁，妙趣横生。绮丽的视觉风格及活泼的叙事观点，则令人想到《艾蜜莉的异想世界》。饰演丽莎的莫妮卡贝瑟，表演可圈可点；男主角虽然沈默寡言，必要时却能超越「地表最强」的连恩尼逊。这部悬疑又浪漫的黑色奇幻喜剧，是卡欧利乌梅萨罗的首部长片。', '莫妮卡·巴尔赛', '卡欧利·乌梅萨罗', 7.2, 6196, 'tt2210769', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2293154049.jpg', 1.1, 5.3, 38.5, 41.3, 13.9, '0.270087,0.101146,-0.550994,0.445245,-0.164643,-0.165700,0.701155,0.015302,-0.354485,-0.235213,0.229936,0.409843,-0.174418,0.089554,0.314875,-0.039702,-0.301535,-0.653960,0.034302,0.065215,-0.186695,-0.372524,-0.327580,-0.054251,0.065261,-0.489174,0.383042,0.022014,-0.338336,0.230401,0.200686,0.239644,-0.180471,0.231001,-0.062454,-0.055049,0.015932,0.090685,-0.339104,-0.018088,0.028268,0.007413,-0.158100,0.277931,-0.154759,0.198786,0.548148,-0.244190,-0.115577,-0.084218,0.552479,-0.050144,-0.065349,0.130868,0.063427,0.030777,0.482101,0.249245,0.025782,0.097495,0.133699,0.091496,-0.924244,0.186900,0.185068,0.053717,-0.155422,0.147710,0.083520,-0.228382,0.124002,-0.179796,0.220652,-0.007061,0.399021,0.485116,-0.104300,0.033899,-0.266599,0.391652,0.472423,0.072291,-0.502681,0.363425,-0.300799,-0.275786,0.020038,-0.327967,-0.417187,0.232455,0.008136,0.013090,-0.105509,0.232619,-0.537346,0.094576,-0.218012,-0.054476,-0.030215,-0.277402,-0.062376,-0.455569,-0.200110,-0.339831,-0.316794,-0.114981,0.361374,-0.136678,0.817576,-0.583130,0.153269,0.597424,0.127699,-0.457235,0.614754,0.422319,-0.225913,-0.201417,-0.300024,0.243422,-0.134723,0.055019,-0.169120,0.361221,0.150978,-0.146087,-0.450270,0.433078', '24284209', '27602116', '25928048', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2300450', '舞出我人生2：街舞', '剧情', '失去双亲的街舞者安迪（布莱恩娜·伊维根 Briana Evigan 饰）自小就开始了对街舞的执着练习，她所在的巴尔的摩知名街舞团体410最近完成了“锐舞争霸赛”的视频参赛宣言，而她的监护人因这次出格的视频内容威胁要把她送离此地，幸好在朋友的斡旋下，安迪选择进入马里兰艺术学校学习，保住了眼下的生活。学校里的明星学生查斯（罗伯特·霍夫曼 Robert Hoffman 饰）对安迪颇有兴趣，要求加入锐舞争霸赛却被后者无视。安迪因学业繁重不能兼顾410的训练，终于导致被开除。失意的安迪接受了查斯的邀请，和他物色来的众多校内隐藏的舞蹈高手组成新队伍，向锐舞争霸赛发起冲击……©豆瓣', '布莱恩娜·伊维根', '朱浩伟', 7.3, 43383, 'tt1023481', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p485034464.jpg', 0.5, 4.4, 38.9, 41.8, 14.4, '0.484166,-0.098648,-0.351538,0.522091,0.056655,-0.000138,0.261676,0.051416,-0.268501,-0.231371,0.173762,0.579471,-0.244096,0.360590,0.406477,-0.238290,-0.229586,-0.754868,-0.058739,-0.073443,-0.238737,-0.489787,-0.020285,-0.098878,0.003085,-0.389800,0.740967,-0.068579,-0.553293,0.723741,0.148743,0.127711,0.097398,0.330122,0.039490,-0.077127,0.263411,-0.054171,0.043253,0.263326,0.136320,-0.170298,-0.101676,0.167201,0.530011,0.445615,0.714464,0.005735,0.188962,-0.217928,0.466288,-0.264616,0.022251,0.089118,0.315687,0.138882,0.028422,0.274615,-0.034279,0.056931,-0.225327,-0.360052,-0.729368,0.075240,0.361106,0.041091,-0.517747,0.696206,-0.153108,0.016113,0.055569,-0.063268,-0.023875,0.299201,0.261385,0.133024,0.108160,0.111990,-0.233584,0.193055,0.686854,-0.296099,-0.130276,0.007871,-0.326240,-0.422041,-0.001874,-0.347127,-0.269492,-0.216862,0.244886,0.042329,0.076527,-0.145819,-0.504685,-0.211019,-0.025627,-0.282636,0.116152,-0.442483,0.085659,-0.877601,0.229741,-0.079493,-0.329616,-0.112707,-0.039929,-0.317883,0.860800,-1.013679,0.109582,0.636175,0.417735,-0.449462,0.683976,0.124494,0.346949,-0.098344,-0.088062,0.200157,-0.053155,0.348737,0.024992,0.354624,0.093572,-0.404776,-0.340466,0.505087', '3811356', '1826173', '1316589', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2300586', '这个男人来自地球', '剧情', '一个普通男人的秘密在他的辞职事件中开始显示出端倪。历史教授约翰奥德曼（David Lee Smith饰）说自己身上有一个让大家都匪夷所思的秘密，而为了保守这个秘密他不能在一个地方超过十年。他的朋友们试图去发掘他的故事中的秘密，这一举动让约翰非常生气，而他的朋友却发现约翰的故事是无法被否定也无法查证的，究竟约翰身上有着怎样的秘密？一幕幕碎片联系起来，带给我们一个意料之外的故事高潮。©豆瓣', '大卫·李·史密斯', '理查德·沙因克曼', 8.5, 349916, 'tt0756683', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p513303986.jpg', 0.8, 2, 13.6, 37.9, 45.7, '0.591653,0.098991,-0.713061,0.833516,-0.424982,0.041723,1.046215,-0.451690,-0.814114,-0.586668,-0.079950,0.777325,-0.127371,0.163511,-0.063265,0.171571,-0.142094,-0.734320,0.355251,-0.632031,-0.358342,-0.666622,-0.477374,-0.516599,-0.155143,-0.103011,0.482768,0.209606,-0.365169,0.135587,0.443889,0.336273,0.033268,0.615006,-0.191493,-0.007982,0.200999,0.073224,-0.039726,0.154338,0.124579,-0.404321,-0.115115,0.882413,-0.404077,0.316782,0.536414,-0.301692,-0.317358,0.284756,0.220053,-0.277813,-0.024482,0.072606,0.388100,-0.012045,0.318800,0.386264,-0.168051,-0.016192,0.089511,0.187409,-1.038048,-0.158631,0.165749,0.588106,-0.606152,0.070254,-0.190712,0.066490,0.030294,-0.450707,0.173051,0.108589,0.634396,0.287741,-0.282013,-0.109912,-0.561815,0.065561,0.780955,-0.125675,-0.202889,0.350386,-0.541078,-0.376721,-0.249396,-0.103133,-0.445267,0.235046,0.154032,0.128836,-0.345357,0.314334,-0.502237,-0.039760,-0.149658,-0.228368,-0.345625,-0.494187,-0.047005,-0.168444,-0.416962,-0.196827,-0.372203,-0.140616,0.002715,-0.368421,0.936846,-0.641925,0.092071,0.808832,0.090266,-0.529605,0.609191,0.457504,-0.015481,-0.496128,-0.106605,0.019021,0.032310,0.076260,-0.092027,0.395087,0.190614,-0.349061,-0.678551,0.622233', '25932086', '3785918', '30163500', '30368448');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2300618', '女王的教室特别篇  前篇～墮天使～', '剧情', '教师阿久津真矢（天海祐希饰）由于施行冷酷的教育方式，引发了巨大的社会争议，最终被学校辞退。老师离开后，学生们却开始纷纷怀念起她，当初最惧怕老师的神田和美（志田未来饰）屡次三番回来找她，寻求她的帮助。望着和美热切的眼神，真矢老师不禁想起多年前的自己——积极主动，对学生充满无尽的爱和关怀，立志献身教育。而一切都从认识那个名叫池内爱（後藤果萌饰）的女学生那天开始发生巨大转折……©豆瓣', '天海祐希', '大塚恭司', 8.6, 7100, '女王的教室特别篇', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2681307857.jpg', 0.1, 0.6, 14.5, 39.4, 45.4, '0.154276,-0.170461,-0.604991,0.576406,-0.195261,-0.209424,0.680444,-0.010172,-0.341829,-0.279709,0.037901,0.593456,-0.114236,0.660588,0.267917,-0.033401,-0.160228,-0.728507,-0.364766,-0.063925,-0.119161,-0.422284,0.113327,0.088021,-0.132601,-0.469422,0.401123,-0.006342,-0.107043,0.734627,0.271657,0.401736,0.127197,0.411654,0.194190,-0.155799,0.178547,0.386651,-0.334143,-0.147706,0.269992,-0.220786,-0.287071,0.218876,-0.069714,0.123325,0.540674,-0.077580,-0.316740,-0.355331,0.528883,-0.307938,-0.071646,0.483925,0.207210,0.340679,0.156920,0.165752,0.054144,-0.147962,-0.057743,-0.194784,-0.456672,-0.004664,0.026271,0.152992,-0.425759,0.467312,0.177853,-0.074254,0.463509,-0.328374,-0.096557,-0.080141,0.214183,0.606448,-0.310657,0.312579,0.145453,0.140040,0.680643,-0.106394,-0.194643,0.099275,-0.325698,-0.145071,0.471926,0.008111,-0.467199,0.055727,0.137785,0.035842,-0.163168,0.328613,-0.434856,-0.017974,0.019602,-0.213667,0.380474,-0.483695,-0.378161,-0.516425,-0.068030,-0.384711,-0.224749,0.071539,-0.047658,-0.318209,1.059082,-1.036441,0.245749,0.421645,0.406181,-0.702057,0.517393,0.123442,-0.242706,-0.267129,-0.230322,0.200650,-0.139398,0.533368,-0.173092,0.221887,0.068103,0.011822,-0.301181,0.336775', '25922902', '3445516', '6963575', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2301242', '时空罪恶', '剧情', '中年男子海克特（Karra Elejalde 饰）和妻子克莱拉（Candela Fernández 饰）搬到郊外一幢别墅居住，他用望远镜观察四周的景物，却意外看到一个正脱去衣衫的妙龄女子。海克特心感疑惑，决定前往女子出现的灌木丛中查看一番，结果遭到一个手持尖刀、全身缠满绷带的男子的追杀。海克特仓皇之中逃入一所空旷的实验室内，并在其中的大水槽内躲了起来。次日，当海克尔回到家时，却看到另一个自己正和妻子搬家具，他不知不觉穿越时空来到了一天前。原来水槽是一个时空机器，海克特的命运无意间发生了改变……本片荣获2008年阿姆斯特丹奇幻电影节黑郁金香奖、2007年奥斯汀奇幻电影节新浪潮奖。©豆瓣', '卡拉·埃莱哈尔德', '那奇欧·维加隆多', 7.3, 37994, 'tt0480669', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1533792590.jpg', 1.1, 5, 37.3, 43, 13.7, '0.082586,0.085859,-0.769292,0.262906,0.224509,-0.208395,1.037919,0.097271,-0.449280,-0.465468,0.385912,0.812797,-0.186632,0.235270,0.532094,0.319671,-0.719060,-0.623264,-0.259814,-0.201357,-0.686641,-0.085592,-0.295066,-0.059711,0.185104,-0.241969,0.397115,0.212327,-0.008804,0.596554,0.160219,0.138471,-0.324090,0.368118,-0.105281,0.043753,0.289550,0.134446,0.064774,0.411721,-0.436728,-0.192059,-0.463836,-0.004141,0.076079,0.276837,0.803871,-0.177275,0.036810,0.059828,0.273820,0.083365,-0.199113,-0.120933,0.380886,0.011018,-0.030733,-0.166705,-0.353206,0.065819,0.003774,-0.253247,-0.275453,0.054913,-0.039163,0.250410,-0.463063,0.316769,0.125678,-0.159878,-0.137770,-0.473790,0.137637,-0.153512,0.059269,0.415649,-0.066827,0.142213,-0.483922,-0.004659,0.246940,-0.032942,-0.048589,0.172375,0.099976,-0.132436,-0.097807,0.145315,-0.296718,-0.258674,0.464436,0.092135,0.006923,-0.101059,-0.642421,0.080033,-0.521300,-0.341461,0.111847,-0.034388,-0.616246,-0.578994,0.122360,0.027443,-0.185305,0.102981,-0.285046,-0.011033,0.126444,-0.274877,0.419349,0.230632,0.033198,-0.002235,0.728745,-0.392290,0.271064,-0.131589,-0.114372,0.446561,0.181368,0.632892,-0.081917,0.484738,-0.343734,-0.145193,-0.645894,0.240103', '20451118', '1316693', '3011051', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2301363', '继续活下去的5个故事', '恐怖', '《小饰和洋子》：虽然双胞胎姐妹小饰和洋子（小林凉子 分饰）有着同样的面容，但是妈妈（松田美由纪 饰）却更加偏爱前者，洋子感到自己随时都会被妈妈杀掉；《七个房间》姐姐（市川由衣 饰）和弟弟智司（须贺健太 饰）被人关在紧闭的房间内，相似的房间还有6间，每间都有一个女人。邪恶的男人每天杀掉一人，从不间断；《So Far》：似乎一场车祸，让原本冷淡的夫妻互相看不到对方，坚信对方已经死去。儿子（神木隆之介 饰）在他们中间充当传声筒，渐渐感到自己的灵魂深处开始撕裂；《向阳之诗》男子（龙坐 配音）制造出了美丽的女孩（铃木かすみ 配音），只希望她有朝一日将其埋葬；《动物园》他（村上淳 饰）在废弃的动物园杀了要分手的她（浜崎茜 饰），并每天为尸体拍摄照片，诡异的事情随即发生……本片根据乙一的短篇原作改编。©豆瓣', '小林凉子', '金田龙', 7.5, 21647, 'tt1014693', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1003946094.jpg', 0.7, 4, 33, 44.9, 17.4, '-0.015725,-0.226559,-0.570349,0.364675,-0.055152,-0.074022,0.917410,0.096869,-0.306167,-0.343125,0.313270,0.658185,-0.324622,0.268439,0.003600,0.119433,-0.282160,-0.560396,-0.273888,0.010844,-0.212789,-0.295710,-0.011546,-0.295321,-0.028565,-0.169941,0.656133,-0.128320,-0.048352,0.355967,0.118961,0.232207,-0.345492,0.323282,0.045398,0.187260,-0.226222,0.013036,0.023561,-0.037793,-0.076843,-0.109547,-0.102253,0.145797,-0.142591,0.321896,0.779176,-0.181447,-0.300260,-0.002328,0.140390,-0.013241,-0.183706,0.163405,0.231117,-0.083790,0.392101,0.180905,-0.328861,0.007538,0.246867,0.070547,-0.490054,0.170880,0.272919,0.244989,-0.230397,0.382180,-0.072064,0.056514,0.549638,-0.192025,0.180285,-0.038152,0.293451,0.358886,-0.390846,0.083231,-0.409120,0.061230,0.381028,-0.088724,0.036782,0.345650,-0.307006,-0.181897,-0.205279,-0.005394,-0.321608,0.132158,0.156134,0.012013,-0.013003,0.004067,-0.523270,-0.209424,0.055524,-0.033879,-0.007203,-0.511753,-0.051378,-0.459783,-0.139122,-0.378671,-0.283749,0.171123,0.056528,-0.302346,0.716328,-0.743313,0.090617,0.267034,0.323113,-0.195063,0.382792,0.035475,-0.091393,-0.159822,-0.008512,0.101678,0.132306,0.192408,0.204423,0.409639,-0.076599,0.132153,-0.484097,0.426314', '21619567', '1467779', '1417036', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2301701', '人兽杂交', '剧情', '在大公司纽斯特德的支持下，生物科学家克里夫·尼科利（阿德里安·布洛迪 Adrien Brody 饰）和女友艾尔莎·卡斯特（萨拉·波莉 Sarah Polley 饰）进行基因重组的实验，并取得初步进展。然而由于资金和公众舆论等原因，纽斯特德高层决定中断对他们现有研究的支持。克里夫和艾尔莎不愿半途而废，于是偷偷展开实验。他们对基因进行优化重组，并混入了艾尔沙的一部分基因，终于孕育出一个相貌奇特的雌性怪物。秉着科学家的道德和良知，克里夫执意要杀死怪物，而艾尔莎则全力保护，视若己出，并将其命名为卓伦。卓伦以飞快的速度成长，最终变成一位拥有独特美感的女孩（Delphine Chanéac 饰）。在这一过程中，克里夫和艾尔莎越陷越深……©豆瓣', '艾德里安·布洛迪', '文森佐·纳塔利', 5.6, 66240, 'tt1017460', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p537003213.jpg', 7.7, 27, 48.4, 13.1, 3.7, '-0.012721,0.196090,-0.586149,0.754906,0.086367,-0.279958,0.638904,0.034346,-0.402914,-0.386038,0.064624,0.460653,-0.030286,-0.211589,0.336751,-0.303357,-0.655518,-0.423093,0.181814,0.129087,-0.514676,-0.745381,-0.397721,-0.452158,-0.051355,-0.619788,0.739072,-0.141808,-0.311414,0.369968,0.109566,0.461015,-0.115829,0.207890,0.267900,-0.035327,0.335319,-0.396010,-0.359969,0.389088,0.255902,0.070170,-0.018649,0.057200,0.053333,0.320577,0.676003,-0.555402,-0.054166,-0.322343,0.141221,-0.251325,0.017685,0.096109,0.328453,-0.027590,-0.053814,0.341029,-0.123462,0.146768,0.086055,-0.172378,-1.086374,-0.295996,0.117422,0.305425,-0.322626,0.271072,-0.150365,0.023992,-0.062939,-0.410142,-0.454084,0.472955,0.376938,0.259193,-0.209678,0.180135,-0.340229,-0.284683,0.243358,-0.015623,-0.558567,0.404771,-0.328522,-0.664478,-0.354586,-0.192334,-0.259835,-0.111270,0.237559,0.506908,0.101847,0.428014,-0.979820,-0.134879,-0.592262,-0.318927,0.125344,-0.276224,0.188602,-0.873217,-0.101130,-0.162398,-0.376964,0.123661,0.069220,-0.388718,0.765525,-0.690825,0.106607,0.360436,0.408446,-0.663018,0.314653,-0.149540,0.337863,-0.451074,-0.384897,0.348758,0.256337,0.287850,-0.048776,0.215922,0.442951,-0.293539,-0.395163,0.358304', '1292680', '1972732', '25774050', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2301772', '侠盗石川', '剧情', '16世纪末的日本，明智光秀发动本能寺之变，杀害了离称霸天下只有一步之遥的织田信长，丰臣秀吉（奥田瑛二 饰）率兵打败光秀，继而建立丰臣政权，天下得到久违的和平。15年后的和平年代，劫富济贫的大盗石川五右卫门（江口洋介 饰）名扬四海，备受穷苦老百姓的喜爱。盛典之夜，五右卫门潜入某富豪家中行窃，结果导致该富豪及其家人被五奉行之一的石田三成杀害。原来五右卫门顺手牵羊偷走了一个藏有惊天秘密的匣子，随后又将其扔掉。次日，得知昨夜详情的五右卫门来到贫民窟寻找匣子，与此同时，石田三成也派出忍者雾隐才藏（大泽隆夫 饰）追踪匣子的下落。连番激烈的搏斗旋即展开，而那个惹来腥风血雨的匣子究竟有隐藏着什么秘密呢？©豆瓣', '江口洋介', '纪里谷和明', 6.8, 11836, 'tt1054122', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p939519892.jpg', 2.5, 9.9, 44.8, 32, 10.7, '0.062724,0.174124,-0.438982,0.233607,0.149875,0.115120,0.543732,0.125878,-0.203181,-0.586156,0.259315,0.440065,-0.147323,-0.120758,0.206146,0.113085,0.264678,-0.682781,-0.332344,-0.503874,-0.118649,-0.018874,-0.413228,-0.138120,0.042382,0.033470,0.445222,0.425910,-0.191682,0.219454,0.194665,0.563875,-0.509795,-0.077140,0.010528,0.089847,0.122645,0.061869,-0.128158,0.238859,-0.766611,-0.475859,-0.210566,0.024080,-0.193498,0.331155,0.455237,-0.398043,0.061262,-0.320915,0.089289,0.061837,-0.725156,-0.087892,0.573002,0.300737,-0.144052,0.454697,-0.198979,-0.048344,0.185452,-0.079415,-0.560976,0.087598,0.188658,-0.094851,-0.397461,0.223580,-0.273690,-0.294193,0.161482,-0.214635,0.033279,0.593647,0.050208,-0.074404,-0.214259,0.285575,-0.607548,0.124273,0.278706,-0.606213,0.080726,-0.188848,0.559517,-0.249387,0.234715,-0.547511,-0.117094,-0.152161,0.610574,-0.117670,0.273108,0.021774,-0.420578,-0.259283,-0.414019,-0.176992,0.638082,0.093058,-0.119907,-0.423359,-0.288892,-0.170927,-0.303694,0.026494,0.309149,-0.110398,0.768748,-0.592932,0.206291,0.375794,-0.138031,-0.574563,0.164081,0.097454,-0.071048,-0.076779,-0.226407,0.072302,0.469051,0.550170,-0.041894,0.028874,-0.176015,-0.445930,-0.186688,-0.087924', '26747274', '6425116', '1438924', '25912924');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2303163', '超级大坏蛋', '喜剧', '很多年前，银河系另一端的两颗行星被黑洞所吞噬，两个尚在襁褓中的外星孩子乘坐飞行器来到地球。拥有超能力的他们在截然不同的环境中长大，也造就了各自不同的性格和人生走向。长大后，仪表堂堂、正气凌然的成为了保卫城市和平的城市超人（布莱德·彼特 Brad Pitt 配音），而相貌猥琐、蓝皮大头的则化身破坏人民安康的大坏蛋麦克迈（威尔·法瑞尔 Will Ferrell 配音）。他们终日争斗，战争不断。城市超人博物馆开幕当天，麦克迈成功越狱，并劫持了美丽的女主播罗珊（蒂娜·费 Tina Fey 配音）。在天文台的终极决战中，麦克迈成功击败多年的老对手，完全统治了这座城市。好景不长，失去对手的麦克迈很快便觉得寡然无味。偶然间受到罗珊的启发，他决心创造出一个新的正义英雄，恢复当初此消彼长的快乐日子。只是，一切开始朝着不可预测的方向发展……©豆瓣', '威尔·法瑞尔', '汤姆·麦格拉思', 7.8, 123243, 'tt1001526', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p638548555.jpg', 0.2, 1.8, 26.2, 50.7, 21.2, '0.172991,0.234905,-0.492295,0.455109,-0.175792,-0.103116,0.667003,0.220346,-0.218881,-0.090773,0.200616,0.769311,-0.175007,0.050904,0.339179,-0.219209,-0.279546,-0.431529,-0.128834,-0.116568,-0.125844,-0.414752,-0.360745,-0.106864,0.018422,-0.417984,0.838264,0.181816,-0.211799,0.502939,0.077218,-0.011439,-0.188086,0.263759,-0.102788,0.076736,0.175365,-0.137938,-0.328806,0.280753,-0.220895,-0.025553,0.033782,0.129414,-0.241748,-0.006758,0.556552,-0.399739,0.057074,-0.336065,0.406666,-0.140055,-0.228392,-0.090285,0.189105,-0.036189,-0.097475,0.173897,-0.012297,0.145891,0.022503,-0.355371,-0.764713,0.077987,0.035665,0.049779,-0.423416,0.364413,0.242816,-0.145282,0.085926,-0.286598,-0.019490,0.385185,0.424765,0.538709,-0.127031,0.269555,-0.547261,-0.091306,0.578943,-0.111810,-0.694587,0.342448,-0.136619,-0.431942,-0.213439,-0.314440,-0.357753,-0.130451,0.320662,0.067958,-0.109527,0.437864,-0.605329,0.331473,-0.417068,-0.190981,0.065306,-0.294280,-0.124504,-0.693938,-0.167015,-0.287747,-0.055099,0.132254,-0.223194,-0.292231,0.690178,-0.718760,0.237766,0.410005,0.323611,-0.314311,0.587559,-0.091505,0.137288,-0.544950,-0.029362,0.763321,-0.090818,0.571484,-0.095679,0.232150,-0.091183,0.022088,-0.448940,0.714325', '1870681', '3718279', '25880986', '7051375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2303845', '刺客聂隐娘', '剧情', '寂寞天宝后，巍巍大唐辉煌告终，朝廷的威严和向心力进一步削弱。此时藩镇林立，派系迭起，在四分五裂的乱象之下李氏帝国勉强维持着不堪一击的和平与威信。河北三镇之一的魏博镇，刚愎暴戾的节度使田季安（张震 饰）野心勃勃，相机而动。会朝廷派神策兵讨伐王承宗，魏博主从各执一词，纷争连 连。与此同时，田季安自幼被公主道姑带到山上修炼剑法的表妹聂隐娘（舒淇 饰）满师归来。她谨遵师父教诲，奉行杀一人以救万人的理念，接连手刃多位大僚，而此次归来则将狙击目标锁定在田季安身上。剑术已成，道心未坚，侠女聂隐娘捷若猿猱，隐迹红尘……本片根据唐人裴刑的传奇小说《聂隐娘》改编，并荣获第68届戛纳电影节竞赛单元最佳导演奖。©豆瓣', '舒淇', '侯孝贤', 7.3, 207229, 'tt3508840', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2262306528.jpg', 4.1, 7.4, 29.2, 37.7, 21.6, '-0.154690,0.114825,-0.518005,0.742279,0.396885,0.161883,0.110614,0.508597,-0.548639,-0.191115,0.189047,0.397425,0.067559,-0.228145,0.222816,-0.441907,0.078754,-0.552292,-0.475021,0.000109,0.393913,-0.235458,-0.221703,0.065562,-0.387493,-0.507892,0.852924,0.099503,-0.241486,0.442454,0.380070,0.092337,-0.301333,0.226241,-0.042673,0.061293,-0.160530,-0.128117,-0.443429,0.376196,-0.222166,-0.360438,-0.326643,-0.069744,-0.214043,0.178518,0.433050,-0.410075,0.065577,-0.298259,0.451920,-0.082298,-0.168554,0.021971,0.457533,0.061799,0.249440,0.496540,0.166539,0.306727,-0.049792,-0.178532,-0.581736,-0.111772,0.337056,0.004952,-0.353526,0.580863,-0.176123,-0.123570,-0.305703,-0.316476,0.090394,0.426627,0.169641,-0.003892,-0.109579,0.099705,-0.265250,0.299098,0.361722,-0.142959,-0.333258,-0.264849,0.216091,-0.342427,0.083460,-0.607696,-0.264320,-0.183528,0.369370,-0.019121,0.356646,0.436877,-0.120067,-0.157839,-0.190188,0.075315,0.087781,-0.020563,0.051646,-0.300627,-0.061466,-0.208317,-0.177997,-0.103910,0.195084,-0.051348,0.517949,-0.656809,0.059138,0.032970,0.158418,-0.340902,0.372607,0.076545,0.124223,-0.006768,-0.345616,0.195025,0.192972,0.345176,-0.078901,0.112336,-0.079300,-0.130658,-0.319797,0.320125', '26615753', '24499012', '25880986', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23042272', '4B青年之4楼B座', '喜剧', '家毅（付辛博 饰）只是一介小小演员助理，却总是装的一副了不起的样子，然而，他的伪装却常常会被旁人毫不客气的拆穿，因此而闹出了不少的笑话。张杨（彭宇 饰）最崇拜的偶像就是大名鼎鼎的乔布斯，然而，他的理想却是成为一名合格的二B青年，为此，张杨不惜终日研读他的秘籍盛典《2B青年的自我修养》。奋斗（蒲巴甲 饰）虽然生的身强体壮，还是一名拳击陪练教练，但他的个性却是和外表毫不相称的内向木讷。丽川（夏梓桐 饰）是一名尚未熬到出头之日的小作家，虽然屡遭挫折却从未放弃过自己的理想。在4楼B座内，四名各有千秋的男女成为了室友，开启了一段有笑有泪的旅程。©豆瓣', '付辛博', '孙达', 4.3, 5071, '4楼B座 / 四楼B座', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2120288727.jpg', 31.1, 34.2, 26.2, 5.8, 2.7, '0.218422,0.035935,-0.468212,0.616263,-0.580747,-0.413789,0.853743,0.188957,-0.426321,-0.292000,0.462613,0.766316,-0.155991,0.426372,0.139836,-0.202276,0.152362,-0.596461,-0.180447,-0.152564,-0.054603,-0.033910,-0.423487,0.157108,-0.432224,-0.307617,0.876123,0.020354,-0.451510,0.238553,0.572635,0.073254,0.267180,0.454309,-0.414262,-0.035538,-0.049818,0.090725,0.172142,-0.143696,-0.034518,-0.343527,-0.402788,0.150100,-0.119241,0.591928,0.578063,-0.164194,-0.199311,0.101202,0.426504,-0.244317,-0.107901,0.129753,0.145009,0.007068,0.179564,-0.045959,0.006452,0.124452,0.054675,-0.084355,-0.963624,-0.020660,0.151939,0.241130,-0.600557,0.703508,-0.014595,-0.342667,-0.051732,-0.277276,-0.097832,0.023542,0.059092,0.344022,-0.237134,0.187014,-0.527102,0.497123,0.479788,0.259960,-0.455837,0.569662,-0.190016,-0.561078,0.037216,-0.599353,-0.632535,-0.136053,0.186793,-0.144485,0.012572,0.010005,-0.486144,0.124601,-0.361694,0.007559,-0.094676,-0.299624,-0.053099,-0.442020,0.093358,-0.733133,-0.440747,-0.063328,0.135629,-0.405754,1.055558,-0.998050,0.016157,0.273116,-0.150148,-0.597732,0.647946,0.503402,0.019516,-0.035005,-0.212446,0.338577,-0.057039,0.084167,-0.067845,0.655479,-0.047000,-0.410766,-0.366488,0.579772', '24284209', '27602116', '25880986', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23043659', '史努比：花生大电影', '喜剧', '总是闹出一堆笑话的查理·布朗（诺亚·施纳普 Noah Schnapp 配音）这一次有了暗恋的“红发小女孩”（弗朗西斯卡·卡帕尔迪 Francesca Capaldi 配音），他能否获得她的注意呢？而史努比（比尔·莫伦茨 Bill Melendez 配音）也将自己的幻想能力升级，变成王牌飞行员，飞上蓝天追逐自己的头号敌人“红色男爵”，还邂逅了梦中情人“菲菲”（克里斯汀·肯诺恩斯 Kristin Chenoweth 配音）……', '诺亚·施纳普', '史蒂夫·马蒂诺', 7.5, 14746, 'tt2452042', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2276238889.jpg', 1.3, 4.9, 32.1, 39.3, 22.4, '0.403189,0.042734,-0.290763,0.680156,-0.179334,-0.715699,0.536002,-0.101731,-0.011269,0.011308,0.440901,0.686132,-0.526754,0.301746,0.245246,0.524158,-0.512275,-0.626563,0.316706,-0.146309,-0.048857,-0.584742,-0.317517,-0.119972,-0.009209,-0.204655,0.377748,-0.315653,-0.188562,-0.072256,0.401866,-0.007000,0.174328,0.279994,0.163432,0.372928,0.155327,-0.056983,0.276869,0.280207,-0.031661,0.088139,0.115274,0.005679,0.321733,0.310409,0.661954,-0.470902,0.541196,-0.086528,0.378825,-0.404717,0.330072,-0.013887,-0.011663,-0.100792,-0.069642,-0.273102,-0.109270,-0.167482,0.008274,-0.050294,-0.605780,0.190661,-0.257932,0.372245,-0.281516,0.169610,-0.357048,0.252212,0.484282,0.104282,-0.008618,-0.018822,0.308720,0.033204,0.002614,0.146711,-0.361574,0.300084,0.229063,-0.151215,-0.374265,0.317260,-0.257781,-0.405158,-0.049512,-0.078896,-0.568476,-0.146387,0.446234,-0.264196,-0.010783,0.379027,-0.424497,-0.035956,-0.601894,-0.109278,-0.168169,-0.118945,-0.221052,-0.451191,0.063282,-0.283015,-0.298319,-0.325625,-0.093524,-0.520570,0.464059,-0.578845,0.070205,0.735755,0.047923,0.217092,0.464346,0.036097,-0.056767,-0.115316,-0.052296,0.445124,0.006393,0.213590,0.335950,0.160099,0.231477,0.121795,-0.005598,0.612610', '1422957', '30167633', '4816602', '3195759');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2310144', '七龙珠', '动作', '很久很久以前，来自遥远星系的比克大魔王及其手下大猩猩来到地球为非作歹，无恶不作，令人民时刻被死亡的阴影所困扰。此后一群优秀的武术家研究出魔封波，将比克大魔王封印，世界重归光明。当代美国某座城市，看似孱弱不堪的青年悟空（贾斯汀·查特文 Justin Chatwin 饰）自幼随爷爷悟饭（兰德尔·杜克·金 Randall Duk Kim 饰）学习武术，但是爷爷禁止他将一身功夫用于好勇斗狠上面，所以悟空在学校饱受欺负与嘲笑。在一个毫无征兆的日子里，比克大魔王（詹姆斯·马斯特斯 James Marsters 饰）意外复活，而悟饭则因此毙命。悲伤的悟空按照爷爷的嘱咐前去寻找龟仙人（周润发 饰）和七颗龙珠，以阻止比克的野心。有关地球命运的冒险由此展开……©豆瓣', '贾斯汀·查特文', '黄毅瑜', 3.7, 36488, 'tt1098327', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2289890876.jpg', 42.1, 35.3, 18.4, 2.5, 1.8, '0.010838,0.137271,-0.618341,0.599656,-0.015881,-0.160075,0.523163,0.063828,-0.456637,-0.352840,-0.012337,0.603973,-0.018025,0.133739,0.123568,-0.147313,-0.131699,-0.268405,-0.058017,-0.041937,-0.150072,-0.387458,-0.404744,-0.267367,-0.176543,-0.720723,0.445604,0.138969,-0.113978,0.358822,0.164627,0.375694,-0.209740,0.109164,0.054557,-0.139594,0.000856,-0.058334,-0.109176,0.129060,-0.010361,0.164394,0.245028,0.282915,-0.090479,0.040718,0.485724,-0.536280,-0.032984,-0.479227,0.335156,-0.082943,-0.091077,-0.037987,0.338269,-0.099111,-0.018074,0.108709,0.037544,0.163114,0.004247,-0.254526,-0.524891,0.074253,0.175245,0.100213,-0.461751,0.346598,0.039104,0.018764,-0.028983,-0.335533,0.041858,0.205726,0.386098,0.275963,0.003963,0.184708,-0.161540,0.063185,0.389785,-0.185931,-0.234128,-0.109135,-0.119832,-0.154096,-0.137599,-0.302246,-0.338224,0.001711,0.228405,-0.172787,-0.167023,0.497011,-0.484244,-0.160472,-0.414068,0.003860,0.007783,-0.096385,-0.164741,-0.528137,0.162224,-0.211752,-0.074945,-0.166710,0.148752,-0.062903,0.870822,-0.605109,0.513002,0.285551,0.293400,-0.363605,0.534688,-0.264653,0.220018,-0.229103,0.030467,0.498290,0.386017,0.424007,0.081878,0.044163,-0.057119,-0.096868,-0.138724,0.405892', '26348103', '27602116', '1870681', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23126901', '特殊身份', '动作', '身怀绝技、出手不凡的陈子龙（甄子丹 饰）是潜伏黑道多年的卧底，作为老大长毛雄（邹兆龙 饰）的左膀右臂，他的身心承受巨大压力，加上老大已对他升起疑心，威胁子龙妈妈的性命（鲍起静 饰），他急切希望复职，退出黑道。这一次，雄哥派子龙前往内地查探组织成员Sunny罗志伟（安志杰 饰）的虚实。Sunny出身美国唐人街，早年曾跟子龙混迹江湖，但逐渐做大的他暗中黑了雄哥的货。另一方面，子龙的上司张Sir（郑中基 饰）以复职为交换，同样命子龙调查Sunny。谁知内地之行凶险非常，Sunny为人狡猾毒辣，而与内地警方的配合又矛盾冲突频频，加上神秘刺客“刀锋”（张涵予 饰）时隐时现，子龙不知不觉踏入阴谋重重的漩涡之中……©豆瓣', '甄子丹', '霍耀良', 4.4, 69086, 'tt2118775', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2153376390.jpg', 30, 33.6, 26.6, 6, 3.9, '-0.047165,-0.176116,-0.565542,0.705167,-0.002340,0.016866,0.369923,0.230416,-0.754468,-0.409121,0.353218,0.411283,0.042461,0.113054,-0.082255,-0.095701,0.080858,-0.627848,0.021603,0.055333,0.007402,-0.183617,-0.645992,-0.230169,-0.171536,-0.128553,0.346622,0.457350,-0.219709,0.390518,0.391498,0.402252,-0.355348,0.403917,0.055159,-0.188829,-0.098579,0.152811,-0.395739,-0.067102,0.040030,-0.343022,-0.149643,0.051924,0.151154,0.597532,0.408436,-0.141546,-0.152342,-0.399559,0.320895,-0.422977,-0.088630,-0.000275,0.242937,0.260480,0.205670,0.260768,-0.134018,-0.052973,-0.209516,-0.139470,-0.603754,0.170100,0.226719,0.061067,-0.494929,0.268877,-0.282284,-0.066173,-0.109535,-0.033855,0.041899,0.155844,0.206784,-0.098888,0.078640,0.266370,-0.043691,-0.020237,0.588479,-0.068080,-0.093998,-0.171742,0.105689,-0.336936,0.095923,-0.299191,0.035888,-0.019430,0.276530,-0.125957,0.046235,0.193841,-0.426098,-0.071555,-0.225375,0.221696,-0.157498,-0.249152,0.114275,-0.402126,-0.303240,-0.524208,-0.028317,0.303821,0.129904,-0.076921,0.400384,-0.587026,-0.146818,0.154839,0.272392,-0.866261,0.356735,-0.214349,-0.169629,-0.421309,-0.091716,0.072785,0.196944,-0.124958,0.192270,0.175091,-0.075330,-0.257601,-0.095594,-0.069104', '1295746', '1293265', '3811342', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23127631', '大片', '剧情', '踌躇满志的青年导演（向飞 饰）计划投拍一部大片，好不容易攒齐人马，抵达四川外景地，谁知原定的两千万打了水漂。剧组成员相继撤离，最后只剩下导演一人。万般无奈之下，导演找来负责排花絮的天津男（边辉 饰）、群众演员刘小花（刘芸 饰）以及送盒饭的青年（王宁 饰），分别委以摄影师、女主角和制片主任等重要职务，组成一个迷你御用班底。导演天花乱坠，带领三个懵懵懂懂的傻青年四处拉赞助，可是关键时刻掉链子，所费辛苦不少，最终手中空空，空欢喜一场。失落的导演想方设法逃脱三个拖后腿的家伙，而他的大片梦想不知何时才能实现……©豆瓣', '吴孟达', '向飞', 4.8, 6434, 'tt4847452', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1978900841.jpg', 26.2, 29.6, 28.7, 9.7, 5.8, '-0.347000,-0.032866,-0.246368,0.153797,-0.070649,-0.396814,0.181996,0.248838,0.044118,-0.277310,0.362998,0.329368,-0.194129,0.053091,0.375546,-0.384534,-0.236004,-0.478139,-0.193760,-0.060412,0.014901,-0.168502,-0.281194,-0.016128,-0.126504,0.236191,0.836418,0.134153,0.223712,0.308187,0.712310,-0.091982,-0.365462,-0.025237,0.133765,0.090408,0.388459,-0.447992,-0.180252,0.258916,-0.070518,-0.199975,-0.127985,-0.244218,0.025042,0.234592,0.709681,0.094874,-0.028101,-0.033393,0.256469,-0.273930,-0.171657,-0.123707,0.242919,0.353106,0.414415,-0.346609,-0.138158,-0.097401,0.232075,-0.258814,-0.504816,0.091093,0.156546,0.115718,-0.590200,0.201706,0.003008,0.055717,0.190477,-0.349253,0.096106,0.138256,0.304880,0.206938,-0.091737,0.173982,-0.193854,0.699824,0.310816,-0.209358,0.127633,0.100173,0.324781,-0.122132,0.181959,-0.161141,-0.214886,0.242842,0.312826,-0.188992,0.455321,-0.539558,-0.427471,0.160812,-0.315002,-0.188781,-0.150861,-0.336288,-0.027782,-0.495881,0.156649,0.342919,0.247706,0.139367,0.168643,0.160126,0.669377,-0.099062,-0.117319,0.094629,0.028679,-0.414656,0.432555,-0.027759,0.288851,-0.312192,0.126986,-0.462688,0.101590,0.152497,0.340841,0.184977,-0.309081,-0.496662,-0.109675,-0.220752', '26759820', '10833970', '6101834', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23249761', '赛尔号大电影3之战神联盟', '动画', '宇宙中的螺旋星系有颗美丽的星球——纳斯星球，星球上有一种神奇的果实，一直保护着整个纳斯星的生态平衡。星球上的阿吉亚部落世世代代都守护着神之树，可是纳斯星上突然潜入了许多宇宙海盗，恰巧赛尔号上的先锋小队成员赛小息，阿铁打，卡璐璐途经此地，他们立刻加入了这场战斗…随着战况升级，四位神奇精灵：电系王者雷伊，暗影之王布莱克，武斗勇士盖亚，绝地武士卡修斯也加入了进来……', '杨欧', '王章俊', 5.8, 4165, 'tt4253212', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2033931285.jpg', 15.5, 20.4, 35.3, 14.7, 14.1, '-0.041627,0.493397,-0.812517,0.672727,0.132456,0.035192,0.521264,-0.183275,-0.268559,0.243461,0.264103,0.598858,0.037790,0.001098,0.500201,0.356701,-0.447937,0.033292,-0.514915,-0.268849,-0.667253,-0.262068,-0.613201,-0.140136,0.047013,-0.723182,0.681366,-0.058690,-0.091728,0.170015,-0.196925,0.189065,-0.378997,0.335644,0.188694,-0.153527,0.322805,-0.164250,-0.051689,0.231210,-0.837653,0.151913,0.144261,0.099340,0.021632,-0.113326,0.450749,-0.982361,0.579812,-0.670858,0.003940,-0.212986,0.123477,-0.550725,0.968046,-0.098808,0.069384,-0.135033,0.416592,-0.297187,-0.048365,-0.334298,-0.576916,-0.121140,0.127601,0.217364,-0.439292,0.142957,0.091455,-0.101483,0.022192,-0.177237,0.391229,0.349456,0.258542,-0.027772,-0.016198,-0.135260,-0.251070,-0.116925,0.847383,-0.098562,-0.592000,-0.439868,-0.146140,-0.865323,-0.462175,-0.326564,-0.476076,-0.078989,0.430874,0.060361,0.460471,0.639312,-1.109823,0.669654,-0.231276,-0.494284,-0.104091,-0.060939,0.163094,-0.631825,0.161473,0.142918,-0.358402,0.387533,0.142451,0.186141,0.922126,-0.690443,0.531173,0.855420,0.582757,0.105199,0.402612,-0.400338,0.255791,-0.318692,-0.118993,0.348106,0.241604,0.570338,0.059168,0.437713,-0.232892,0.173028,-0.072312,0.513642', '26290398', '2977870', '26309788', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2325873', '第七子：降魔之战', '奇幻', '这是一个魔法司空见惯的神奇世界，青年托马斯·沃德（本·巴恩斯 Ben Barnes 饰）的父亲排行第七，他也是父亲第七个儿子。他生来拥有奇怪的能力，总能在昏迷中看到未来即将发生的事情。某天，一个神秘之人找上门来，对方正是大名鼎鼎的猎魔人格雷戈里（杰夫·布里吉斯 Jeff Bridges 饰）。在过去的岁月里，格雷戈里已经失去了许多个徒弟，因此他找到作为第七子的托马斯，带他走上前所未有的修行之路。与此同时，黑暗女王马尔金（朱丽安·摩尔 Julianne Moore 饰）正耐心地等待血月之夜的到来。届时她的能力将会极大增强，而死对头格雷戈里绝不会对此坐视不管。时间一分一秒流逝，托马斯必须尽快变得更强……©豆瓣', '本·巴恩斯', '谢尔盖·波德罗夫', 5.1, 31243, 'tt1121096', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2219669553.jpg', 10.9, 36, 42.7, 7.8, 2.6, '-0.219990,0.152779,-0.684667,0.596881,-0.204050,-0.090281,0.728827,0.011671,-0.650833,-0.476466,0.168812,0.778831,0.114068,0.244973,0.666510,0.016117,-0.237431,-0.536980,0.007163,-0.223491,-0.305309,-0.369522,-0.585007,-0.190642,0.037395,-0.514179,0.582413,0.136102,-0.013348,0.269595,0.167506,0.437955,0.201431,0.402467,-0.070286,-0.057073,0.221176,-0.138577,-0.120016,0.123231,0.005834,-0.087140,-0.068080,0.172484,-0.123567,0.146616,0.367050,-0.518979,-0.075301,-0.262265,0.246945,-0.407259,-0.134947,0.100049,0.240698,-0.035724,0.098640,0.364266,-0.232660,-0.162804,-0.157148,-0.148271,-0.960333,0.236881,-0.150572,0.356577,-0.390294,0.174558,-0.115161,-0.126195,0.119583,-0.515563,-0.076297,0.292663,0.171678,0.153413,-0.199345,-0.231956,-0.345915,-0.297739,0.568008,0.088466,-0.338863,0.363264,-0.079614,-0.271293,-0.047778,-0.279356,-0.465150,-0.093746,0.488928,0.312529,0.140091,0.438235,-0.288616,0.142632,-0.318263,-0.287332,-0.076580,-0.280326,-0.136114,-0.538031,-0.146223,-0.390633,-0.389982,0.174410,0.138051,-0.290665,0.650536,-0.677996,0.445438,0.370412,0.092676,-0.401290,0.435831,0.081108,0.283748,-0.427904,-0.202912,0.471466,-0.063986,0.455951,-0.192007,0.186670,0.094757,-0.111658,-0.374789,0.769486', '1793491', '10440076', '30163500', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2326215', '沉睡的青春', '爱情', '徐青青（郭碧婷 饰）的母亲跟别人走了，只剩下她跟父亲一起生活，她独立经营着古老钟表店。某天，一名叫蔡子涵的男生前来修表，青青认得他，他之前曾睡在她家的门口。这个羞涩的男孩子几天都来找青青修表，他终于鼓起勇气告诉青青他是她的国中同学，青青还在言语间知道这个男孩子是喜欢自己的。自从上次去了山间瀑布之后，子涵就再也没有出现，直到青青打电话到子涵家中。子涵的父母竟告诉青青，他们的儿子已经死去了。当子涵再次出现的时候，青青要去他的家，他果然带到了自己的家。子涵的父母才告诉青青，当年子涵死去之后，柏宇患上了精神分裂，他每天三点钟之后，都会变成子涵。子涵的父母将要搬走，柏宇也将回到美国的父母身边。青青担心自己再也见不到子涵了，她终于踏上了多年来都不敢坐的火车……©豆瓣', '张孝全', '郑芬芬', 7.1, 25033, 'tt1142556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198952994.jpg', 0.9, 7.3, 42.9, 35.9, 12.9, '0.351018,0.022489,-0.855097,0.162311,-0.306081,-0.947443,0.478781,-0.000151,-0.444051,-0.143435,0.218216,0.753852,0.092540,0.475987,0.025267,0.514983,-0.360288,-0.815908,-0.060178,-0.340618,-0.245713,-0.235006,0.128745,0.083856,0.138201,0.066329,0.106296,-0.460606,0.016840,0.674152,0.064359,-0.257892,0.032311,0.579424,-0.399647,0.495493,0.072846,0.148190,-0.132191,0.129831,0.395553,-0.184239,-0.237232,0.162801,0.088315,0.330478,0.428784,-0.052210,-0.344238,0.027741,0.061986,-0.137905,-0.025730,0.043234,0.384655,-0.271098,0.462684,0.236868,-0.329026,0.034362,-0.111199,0.293403,-0.238943,0.224477,-0.109790,0.214813,-0.620677,0.375222,-0.035779,-0.236111,0.210443,-0.794080,0.531882,0.420053,-0.234275,0.470282,-0.374669,-0.039753,-0.517272,0.313791,0.723690,-0.043973,0.208591,0.366332,0.146338,-0.010435,0.293213,-0.034028,-0.664627,0.241561,0.181298,0.070267,-0.635759,-0.061579,-0.524182,0.093008,-0.301084,-0.157616,-0.043476,-0.245643,-0.215674,-0.043247,-0.262147,-0.364719,-0.394061,0.114437,-0.183281,-0.102491,0.584931,-0.856245,0.480812,0.307470,0.617260,-0.467850,0.658391,0.074355,-0.102324,0.042133,0.240105,-0.044232,-0.436045,0.748078,0.091117,0.344515,0.397398,-0.086470,-0.514028,0.239214', '1926007', '1307876', '1292219', '1451563');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2328749', '奇谈', '剧情', '1942年的韩国首尔，那时还叫做京城，正处在日本殖民统治之下。从日本留学归来的夫妻档金东原（金泰宇 饰）和金仁英（金宝京 饰），受上级的委托，被任命进入京城的安生病院工作。从外表上看，这是座颇具欧洲风情的漂亮建筑，但内里，却总是怪事不断。医院里聚集了从各处来的人。其中，有即将和医院院长的女儿结婚的前美术生振南（陈久 饰）；有性格阴郁但医术高超的医师李秀仁（李东奎 饰）等。他们在医院中，邂逅了各式各样的人。振南对自杀的女高中生尸体产生了难解的心情；秀仁邂逅了失语症少女（高珠妍 饰）；而东原在这时发现了妻子似乎藏着什么秘密。医院外的世界战火纷纷，而医院内的形式也是扑朔迷离。这到底只是奇谈，还是确有其事？©豆瓣', '金甫京', '郑范识', 6.9, 9088, 'tt1124378', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p613366208.jpg', 1.8, 9.4, 42.7, 33.7, 12.5, '0.222947,-0.104516,-0.712141,0.408307,0.081382,-0.048456,0.632600,0.243946,-0.758304,-0.260640,0.112595,0.656394,-0.165314,0.384113,0.153038,0.152994,-0.373280,-0.582267,-0.215154,-0.232099,-0.387484,-0.269312,-0.235494,-0.051232,0.022746,-0.185046,0.415349,0.220701,-0.021302,0.512243,0.225871,0.424747,-0.166458,0.518919,-0.262644,0.022591,0.105699,0.193565,0.036920,0.161843,0.244816,-0.413412,-0.203205,0.074092,0.056775,0.505777,0.626824,0.062594,-0.092487,-0.182961,0.386800,-0.052811,-0.224488,0.192211,0.334087,-0.031858,0.186510,0.206827,-0.208099,-0.046160,-0.001126,-0.028957,-0.430274,0.033316,0.285710,0.132613,-0.538181,0.537816,-0.015080,-0.177121,-0.038012,-0.236252,0.510364,0.292628,0.038577,0.406321,0.005339,-0.070902,-0.560901,0.049647,0.440478,0.042097,-0.260711,0.377956,-0.349477,-0.570141,-0.002940,-0.190448,-0.324349,-0.017815,0.002438,-0.044298,-0.167226,-0.131158,-0.434569,0.105325,-0.128085,-0.058549,-0.089958,-0.210509,-0.310541,-0.511769,-0.205470,-0.627242,-0.414952,-0.025622,0.125660,0.095886,0.728004,-0.790192,0.080457,0.394744,0.285580,-0.423491,0.869005,-0.113700,0.002796,0.102407,-0.265289,0.020516,-0.190255,0.457814,-0.149736,0.477010,-0.190172,-0.403969,-0.420943,0.233841', '3055049', '1302384', '1306544', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2330733', '东京少女', '爱情', '《东京少年》的姊妹篇，同样以“无法有结果的恋情”为主题。2008年的东京少女未步（夏帆 饰）的梦想是成为一名奇幻小说家，这天和母亲以及母亲的情人在餐厅用餐，对母亲准备再婚一事十分排斥的未步愤而离席。1912年，宫田时次郎（佐野和真 饰）再次被夏目漱石退稿，缺乏生活经验的他写作出来的小说缺乏打动人心的力量。他沮丧地拿着退稿离开出版社。突然发生地震，站立不稳的未步失手掉了手机，从楼梯坠入连接过去与未来的虫洞，被时次郎拾得。不可思议地，相隔几近一百年的两个人，由误会到了解，渐渐情愫暗生，彼此倾诉生活中遭遇的问题，还异时空约会。但是身处未来的未步总是知道历史的发生，而当她想改变时，却发现一切只是无能为力。但是即便不能改变命运，也仍有真爱留低。©豆瓣', '夏帆', '小中和哉', 7.7, 17191, 'tt1139641', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p816897412.jpg', 0.4, 2.7, 27.8, 47.1, 22, '0.326385,-0.018877,-0.707209,0.446930,0.092722,-0.315869,0.765102,-0.032928,-0.351318,-0.415265,0.103270,0.570549,-0.222639,0.408482,0.364297,-0.077167,-0.074984,-0.701686,0.112171,-0.119339,-0.239341,-0.327284,-0.097368,-0.127003,-0.341875,-0.216892,0.950720,0.356542,-0.336068,0.313743,-0.033795,0.428974,-0.073934,0.656171,-0.157876,0.018883,-0.323013,0.173945,-0.208425,0.068952,0.162485,-0.232642,-0.298242,0.011813,-0.109327,0.394660,0.537747,-0.299922,-0.401924,0.166266,0.535930,-0.261798,-0.122949,0.237111,0.375583,0.229898,-0.028846,0.248125,-0.213121,-0.010481,0.139977,-0.072324,-0.701817,0.012744,0.082776,0.227932,-0.440857,0.404900,-0.125396,-0.074660,0.209338,-0.386513,0.065764,0.340070,0.505383,0.459066,-0.403752,0.070465,-0.494284,-0.048235,0.768634,0.060684,-0.225839,0.504186,-0.231818,-0.458091,-0.282704,-0.192710,-0.540182,0.131469,0.014071,0.415946,-0.439476,0.288063,-0.453480,-0.017557,-0.132430,-0.231858,0.121486,-0.507451,-0.211103,-0.299711,-0.345894,-0.425374,-0.421100,0.046905,0.136347,-0.294856,0.622594,-0.753524,0.084865,0.533167,0.236421,-0.405491,0.762484,0.097860,-0.299381,-0.078437,-0.098511,0.426728,-0.134044,0.363264,-0.011283,0.253559,0.006469,0.012174,-0.494171,0.273824', '35287908', '26280710', '4840388', '20472738');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23331914', '狂怒', '剧情', '1945年4月，德国纳粹已成强弩之末，第二次世界大战即将落下帷幕，战火正转向德国本土。绰号“战争老爹”的坦克小队队长唐·柯利尔（布拉德·皮特 Brad Pitt 饰）刚刚与战友经历了一场殊死之战，疲惫和愤怒早已胜过了对战争的恐惧。休整期间，从没有过战场经验的打字员诺曼（罗根·勒曼 Logan Lerman 饰）被分到唐的坦克“狂怒”上。诺曼对自己的遭遇愤愤不平，也无法坦然接受新战友粗鲁暴虐的一面。接到新的任务后，唐带领坦克小队前往下一个城镇作志愿，然而一路上却遭到德军顽强的抵抗。最残酷的腥风血雨，让诺曼在悲伤、暴怒、惊恐和绝望中迅速成长起来，而他也即将和战友们经历一场最难忘的殊死决战……©豆瓣', '布拉德·皮特', '大卫·阿耶', 8, 187189, 'tt2713180', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2209858994.jpg', 0.3, 1.5, 21.5, 52.5, 24.2, '-0.025383,0.003124,-0.861871,0.603598,0.231527,-0.442921,0.836220,-0.333894,-0.567250,-0.115117,0.240996,0.485315,-0.091023,0.115376,0.305806,-0.479306,-0.169693,-0.901445,-0.399550,0.228694,-0.530764,-0.387855,-0.311281,-0.457391,0.084314,-0.339048,0.765826,0.404666,-0.104379,0.771105,0.460270,0.513648,-0.048180,0.834437,0.083478,0.001098,0.175965,-0.035010,-0.571673,-0.086261,-0.100575,-0.152787,-0.390205,0.158235,0.050594,0.359398,0.727254,-0.370039,-0.030625,-0.270206,0.065606,-0.369135,0.047977,0.425615,0.612809,0.171733,-0.100048,-0.054909,0.236318,-0.068795,-0.306032,-0.087188,-0.798143,0.041133,-0.113075,-0.041279,-0.675315,0.820451,-0.252520,0.476325,0.276265,-0.088149,0.187852,0.719274,0.555896,0.291717,-0.395009,0.031899,-0.173249,0.209166,0.927597,-0.101888,-0.257403,0.170819,-0.071428,-0.402369,-0.008594,-0.526817,-0.633606,0.080418,0.397015,0.027353,-0.038575,0.588805,-0.816159,-0.080910,-0.345069,-0.516402,-0.077417,-0.165700,0.006664,-0.714029,-0.174953,-0.377314,-0.248864,0.410868,-0.094239,0.005776,0.819031,-0.691691,0.321055,0.073510,0.225005,-0.074779,0.285452,0.161979,0.297783,-0.092960,0.181479,0.703156,-0.016496,0.350369,0.375988,0.368107,-0.269690,0.099714,-0.082203,0.591170', '5361544', '1826173', '25828589', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2333699', '蜡笔小新：呼风唤雨的热带雨林', '喜剧', '小新一家还有风间，妮妮，正男，阿呆一起报名动感超人周年纪念南海之旅，就在动感超人电影的船上首映会上，突然出现了一群粗暴的猴子将大人们都掳走了。春日部防卫队为了救出大人们而出动，小新一行人冒险渡海到南海上的一座荒岛希望可以查出发生了什么事，但本应在船上小葵和小白竟突然出现，小新还发现另一辆古怪的船......', '矢岛晶子', '原惠一', 8.6, 11822, 'tt2180441', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2507164631.jpg', 0.1, 0.8, 13.7, 39.8, 45.6, '0.486594,-0.043817,-0.795228,0.355409,0.273743,-0.275273,0.724218,-0.077149,-0.383259,0.078380,0.411262,0.618417,-0.165443,0.386662,0.376477,0.279843,-0.459740,-0.545049,-0.149996,-0.059816,-0.591506,-0.246211,-0.180534,-0.147220,0.236900,-0.149744,0.315704,0.117417,-0.043407,0.597933,0.549021,-0.188350,-0.585950,0.456787,-0.339392,0.116431,-0.047191,0.181320,0.288227,0.145150,-0.525720,-0.217337,-0.191982,0.042985,0.112344,0.280025,0.636039,-0.160585,-0.309090,-0.069939,-0.020569,-0.286223,0.051456,-0.040443,0.476568,-0.073588,0.072452,-0.158391,-0.176200,0.015803,-0.033078,0.023078,-0.230208,0.358369,-0.249067,0.320658,-0.428269,0.198940,0.133981,-0.168691,0.320506,-0.553792,0.112370,0.365797,0.284325,0.131921,-0.145969,-0.060595,-0.608409,-0.044049,0.778575,-0.250268,0.061340,0.186049,0.325148,-0.281381,-0.121762,-0.066811,-0.068959,0.041658,0.336481,-0.298605,-0.359279,-0.007620,-0.669658,0.259846,-0.183191,-0.275254,-0.165761,-0.014189,-0.060239,-0.823988,0.370654,0.059893,-0.121875,0.596877,0.234495,-0.146955,0.742538,-0.712678,0.316850,0.770818,0.279718,-0.304948,0.546904,-0.064477,0.053895,0.164608,-0.133356,-0.372440,0.195471,0.472713,0.022258,0.440824,-0.289001,-0.246285,-0.337308,0.105468', '3147969', '10466639', '1293019', '3326747');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23338330', '博士之日', '剧情', '被列入世界吉尼斯纪录的最长科幻系列电视剧《神秘博士》将迎来第50周年的播放纪念。为了庆祝这部长寿电视剧的半百生日，英国广播公司BBC电视台制作了《神秘博士》特辑，不仅将在英国电视台和电影院同步播映，还将首次以3D形式与观众见面。据悉，此次纪念活动将成为一次全国性的庆祝活动。BBC电视台电视剧部门相关负责人本·史蒂文森表示这部穿越时空的科幻电视剧的纪念甚至可以与女王的60周年钻禧和奥运会相媲美，庆祝活动将持续一年，并在11月达到高潮。年初，印有11任博士头像的纪念邮票由英国皇家邮政发布。有报道表示，之前几任博士的扮演者将齐聚一堂，在特辑中集体现身。', '马特·史密斯', '尼克·赫伦', 8.9, 8800, 'tt2779318', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2129762316.jpg', 0.9, 2, 9.7, 24, 63.4, '0.073376,0.077651,-0.559110,0.518004,0.418657,0.211041,0.132472,0.010878,-0.280814,-0.096303,0.169072,0.983898,-1.026013,0.226858,0.379460,-0.329488,-0.279015,-0.715459,-0.466683,-0.236499,0.167886,-0.307115,-0.190927,0.096826,-0.015536,-0.468926,0.770667,-0.071685,-0.196751,0.665978,0.565191,0.005391,-0.090184,0.260839,-0.046198,-0.351747,0.293424,0.021519,-0.603267,0.622560,0.077343,-0.258958,0.092328,-0.011113,0.063949,0.135994,0.799822,-0.356222,0.003233,-0.128657,0.943732,-0.180426,-0.183260,0.212847,0.273541,0.662986,0.224197,0.633955,-0.178816,0.392928,-0.073334,-0.638199,-0.881805,0.169597,0.172262,0.081274,-0.362732,0.572637,-0.476471,-0.008916,0.207422,-0.128894,0.610201,0.492771,0.533921,0.286944,0.250919,0.275620,-0.258233,0.861662,0.373605,-0.120227,-0.260364,0.208500,0.089058,-0.442578,-0.033977,-0.140610,-0.107357,0.509167,0.128523,-0.239932,0.123321,0.164380,-0.875041,-0.124412,-0.090952,-0.856598,0.353482,-0.472020,-0.185591,-1.471959,-0.005869,0.325696,0.260961,-0.377801,0.505638,-0.578434,0.821106,-0.796761,0.289731,0.491721,0.482709,-0.239184,1.029384,0.101084,0.023820,-0.246153,-0.200937,-0.183924,0.081788,0.528204,-0.102933,0.262397,0.120940,-0.465852,-0.488582,0.449962', '24751811', '30397916', '34961898', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2334073', '安娜与安娜', '剧情', '因为工作的关系，Anna（林嘉欣 饰）到了上海工作。她与蛋糕师Billy一直保持暧昧的关系，Billy很喜欢她，可是Anna心里一直记挂着前男友欧阳（陆毅 饰）。因为一副画的原因，Anna与自己相貌完全一样的思雨（林嘉欣 饰）。思雨买了一副自己丈夫欧阳的画，店员却送到了Anna的住处，两个人就此相识了。她们爱着的是同一个男人，欧阳本来是个钢琴家，却患上了忧郁症，思雨本来是名画家，为了丈夫她放弃了自己的爱好。Anna在网上查找到，她们是彼此的分身。8岁时她们曾在溺水时看到了一个相同的自己。十年前的堕胎经历，她们再次分成了两个相同的人，相同的名字，相同的生日，相同的遭遇，维持了十年直到她们遇见。这时候，她们决定互换身份三天。因为Anna想再一次与欧阳生活，思雨也厌倦了欧阳。可是她们各有思想，Anna想代替思雨，思雨则想取代Anna的身份，离开欧阳。欧阳发病，也让Anna想起了十年前与欧阳分手的情景，她也发现了思雨的阴谋……', '林嘉欣', '林爱华', 5.9, 5017, 'tt0985079', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2364180026.jpg', 4.5, 21.3, 54.4, 16.6, 3.2, '0.298826,-0.075248,-0.672739,0.538997,-0.495054,-0.489543,0.803518,-0.154756,-1.052026,-0.479765,0.024354,0.860817,-0.291801,0.508886,0.230082,0.021672,-0.049054,-0.744500,0.151740,-0.171953,-0.364198,-0.338775,-0.055241,-0.239463,-0.235336,-0.167636,0.465498,-0.205821,0.062599,0.569636,0.230562,-0.119424,-0.228750,0.635351,0.157082,0.127623,-0.252644,0.243333,-0.353949,0.258344,0.110375,-0.162782,-0.085356,0.061083,0.172222,0.536126,0.491035,-0.023955,-0.261386,-0.045046,0.181387,-0.267576,-0.315028,0.407644,0.091146,-0.136454,0.500412,-0.037542,-0.435140,-0.337326,-0.072556,0.058155,-0.462755,-0.067982,0.162290,0.216205,-0.666228,0.632387,-0.420369,-0.170745,0.204734,-0.581245,0.466301,0.652480,0.388329,0.431433,-0.303065,-0.366385,-0.721542,0.187775,0.860883,0.335657,-0.013163,0.339167,-0.230351,-0.398620,-0.490452,-0.112685,-0.274256,0.291793,0.111304,0.136303,-0.335454,-0.101871,-0.456639,-0.355006,0.184090,0.051172,0.117858,-0.861821,0.071632,-0.335341,-0.120605,-0.885753,-0.441900,0.026370,0.012337,-0.519477,0.573188,-1.135063,0.242119,0.236802,0.450267,-0.738885,0.602279,0.384176,-0.055224,-0.240953,0.122917,0.352822,-0.181226,0.183530,0.104845,0.532904,0.090162,0.173739,-0.590771,0.483906', '1308755', '25721544', '1301022', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2334814', '纽约，我爱你', '剧情', '数不尽的摩天大楼，看不完的车水马龙，这里便是不可思议的纽约。怀揣各种梦想的人们，来自不同地域，处于不同境遇，他们巧遇在街头的小酒馆，邂逅在街角的路灯下，因为好奇而交谈，因为寂寞而吸引，在那个充满巧合的城市，演泽着别样的风情与不同浪漫。本片由12个小短片混剪而成，是继《巴黎我爱你》之后的第二部“爱情城市”系列电影。十二位导演用自己独特的视角重新造访这座城市，他们用自己独特的方式展示了对于纽约的原创性看法。制片埃曼纽班毕伊表示此系列电影还将继续推出，2010年他们的目标锁定里约热内卢和上海两座城市。©豆瓣', '海登·克里斯滕森', '法提赫·阿金', 7.6, 98225, 'tt0808399', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p485029127.jpg', 0.2, 2.3, 30.6, 49.1, 17.8, '0.406131,0.021635,-0.799751,0.795673,0.295638,0.203350,0.928463,0.130349,-0.428836,-0.046078,0.262659,0.853588,-0.277901,0.342022,0.289607,-0.074024,-0.404191,-0.559446,-0.115277,-0.301118,-0.178903,-0.490522,-0.378839,-0.243806,0.007295,-0.172790,0.779451,0.231454,-0.321213,0.404310,0.433122,0.318027,-0.305120,0.289259,-0.227168,-0.279383,0.079342,0.123663,-0.418457,0.392228,-0.251042,-0.125299,-0.276345,0.135995,-0.265758,0.213983,1.052255,-0.030449,-0.353209,0.023707,0.468085,0.018914,-0.035722,-0.087284,0.126982,-0.170610,0.230415,-0.035814,-0.175977,-0.062035,-0.098317,-0.164146,-0.807130,0.051038,0.357030,0.029348,-0.288429,0.504146,0.244685,-0.350690,0.030196,-0.424574,0.327073,0.086864,0.608643,0.542882,-0.041106,-0.159799,-0.275034,0.272146,0.583755,0.159412,-0.383904,0.533940,-0.481250,-0.250349,-0.258423,-0.091391,-0.553726,0.079650,0.049845,-0.005584,0.013489,0.098058,-0.998602,0.154524,0.106857,-0.522330,0.201744,-0.527426,-0.037944,-1.073490,-0.087874,-0.502905,-0.026541,-0.124014,0.355971,0.023666,0.781145,-0.837627,0.163483,0.572368,0.302637,-0.374241,1.114571,-0.172899,-0.148414,-0.326213,-0.265230,0.300475,-0.190508,0.144658,-0.225508,0.412156,-0.045541,-0.047804,-0.761833,0.676229', '3055049', '19965431', '1322847', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2334904', '禁闭岛', '剧情', '本片根据美国小说家丹尼斯·勒翰（Dennis Lehane）的同名小说改编。 1954年，联邦警官泰迪（莱昂纳多·迪卡普里奥 Leonardo DiCaprio 饰）和搭档查克（马克·鲁弗洛 Mark Ruffalo 饰）乘船来到波士顿附近的禁闭岛精神病犯监狱调查一桩离奇失踪案。手刃亲生骨肉的女犯蕾切尔（艾米莉·莫迪默 Emily Mortimer 饰）从戒备森严的牢室神秘逃脱，藏匿于孤岛深处。泰迪怀疑监狱的主治精神病医师约翰·考利（本·金斯利 Ben Kingsley 饰）有意隐瞒内情，并向查克透露他上岛的真实目的其实是寻找当年纵火烧死他妻子德洛丽丝（米歇尔·威廉姆斯 Michelle Williams 饰）的管理员，并揭露美国政府利用精神病犯人进行人体科学实验的罪行。但随着调查的逐渐深入，真相却变得越来越扑朔迷离……©豆瓣', '莱昂纳多·迪卡普里奥', '马丁·斯科塞斯', 8.9, 903081, 'tt1130884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p450262388.jpg', 0.1, 0.5, 7.8, 39.7, 51.9, '0.204076,-0.301252,-0.290867,0.310415,0.247970,-0.095630,0.673935,0.023713,-0.525148,-0.370535,0.041708,0.353800,-0.065723,-0.067225,0.173988,0.159542,-0.754192,-0.328462,0.206794,-0.386305,0.064220,-0.871333,-0.280323,-0.367919,0.165440,-0.217986,0.486200,-0.033369,-0.282121,0.095590,0.258548,0.601261,-0.280171,0.054835,0.475739,-0.068880,0.459458,-0.299609,-0.169442,0.106115,-0.007170,0.031212,-0.042482,-0.001259,0.304933,0.594185,0.345606,-0.293994,-0.067314,-0.172308,0.343981,-0.181955,-0.003493,0.033974,0.307086,-0.118220,-0.101947,0.594474,-0.117980,-0.283539,0.005946,-0.165031,-0.379311,-0.061399,0.416928,0.353220,-0.123718,-0.262598,-0.320659,0.129780,-0.100853,-0.056711,-0.034132,0.300231,0.207662,0.034721,0.187098,0.030298,-0.340583,0.177171,0.189524,-0.070703,-0.135856,-0.082917,-0.116266,-0.402136,0.009373,0.126901,-0.305320,0.065145,0.259438,-0.259549,-0.088518,0.476280,-0.191889,-0.337209,-0.639470,-0.138120,-0.180493,-0.138020,0.053681,-0.701741,-0.285109,0.165014,-0.006514,-0.507728,-0.074049,-0.176833,-0.062913,-0.346403,0.414174,0.577462,0.035619,-0.327807,0.244849,-0.032575,-0.018852,-0.408404,-0.331873,0.847657,0.621707,0.205547,-0.175410,0.115386,0.393670,-0.443862,-0.262025,0.075475', '2369549', '3541415', '27031237', '1296217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2335116', '爱不胜防', '剧情', '伯克·瑞恩（亚伦·艾克哈特 Aaron Eckhart 饰）因写了一本关于如何自救的畅销书而成为许多人推崇的疗伤大师。一夜间，读者为他疯狂，多家媒体竞相抛来橄榄枝。但在他内心深处，却一直还未能真正面对妻子的过世。在一次前往西雅图的售书行程中，他遇到了一个经营小花店的女读者艾萝依（詹妮弗·安妮斯顿 Jennifer Aniston 饰）。他的成熟稳重让她心动，她的有趣可爱也同样让他倾心。与她一起，他总能体验到意料之外的人生，发自内心的久违笑容回到了他的脸上。他只会在西雅图停留三天，而艾萝依也并不确定他是否真正走出丧妻的阴影，做好开始一段新恋情的准备。可突如其来的爱情，是否真的能携子之手与君偕老？©豆瓣', '詹妮弗·安妮斯顿', 'Brandon Camp', 6.1, 7157, 'tt0899106', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p555519650.jpg', 2, 15.7, 60, 18.6, 3.6, '0.156497,0.167954,-0.839540,0.672904,-0.241595,-0.295705,0.725917,-0.003879,-0.438040,-0.161975,0.257353,0.791239,-0.192919,0.465020,0.182233,0.245821,-0.165909,-0.628912,0.244295,-0.210104,-0.230647,-0.121184,-0.425002,-0.254847,-0.151457,-0.094000,0.700026,0.448454,-0.057248,0.404308,0.230089,0.010869,0.069160,0.813453,-0.225037,0.144806,-0.001138,0.026915,-0.218348,0.061654,0.289839,-0.323340,-0.390911,0.414159,0.008011,0.310966,0.672799,-0.204881,-0.344623,0.238881,0.460679,-0.326838,0.201847,0.295081,-0.117356,0.144738,0.260925,0.204637,-0.246100,0.141807,-0.094525,-0.157599,-0.809681,0.133066,-0.175474,0.163728,-0.533032,0.483461,-0.210749,0.072189,0.080624,-0.466959,-0.015368,0.261905,0.172179,0.234120,-0.276630,0.041966,-0.303903,0.399251,0.779948,0.154387,-0.374233,0.486646,-0.048235,-0.392895,-0.091187,0.026787,-0.531761,0.065161,0.300109,0.168658,-0.135956,0.289922,-0.400255,0.141695,-0.559362,-0.052844,-0.015478,-0.528093,-0.023414,-0.579499,-0.158155,-0.295863,-0.375312,-0.130277,0.353338,-0.529866,0.900025,-0.837280,0.118007,0.489483,0.252113,-0.550381,0.580951,0.226995,-0.124625,-0.035010,-0.221840,0.533073,0.045230,0.210221,0.008574,0.324553,0.080554,0.021719,-0.395765,0.593975', '1870682', '1301022', '25928048', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2335122', '真相至上', '剧情', '女记者瑞秋（凯特·贝金赛尔 Kate Beckinsale 饰）从线人处获得了一份情报涉及政府一次相当不光彩的行为。在丈夫雷（大卫·休默 David Schwimmer 饰）支持下刊登了这起新闻报道。政府最终以泄露国家 机密的罪行将瑞秋推上被告席，主审该案件的则是自负的检察官帕顿（马特·狄龙 Matt Dillon 饰）。在法庭上，面对帕顿的层层逼问，瑞秋坦然地叙述了整个事件的前前后后，公众心中的天平也开始往瑞秋方面倾斜，但是艾伦坚持要求瑞秋必须说出资料的提供者是谁，瑞秋逐渐地陷入进退两难的境地。艾伦开始向舆论和瑞秋的家人施加压力，而雷也渐渐地抵抗不住国家给予的压力，建议瑞秋屈服于国家。但瑞秋向雷表达了自己的坚持：真相至上。©豆瓣', '凯特·贝金赛尔', '罗德·拉里', 8.3, 33209, 'tt1073241', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p769052768.jpg', 0.3, 1, 14.7, 51, 32.9, '0.187185,0.116845,-0.454775,0.657095,0.139648,-0.007055,0.359516,0.350144,-0.297997,0.157857,0.441275,0.592051,-0.236320,-0.018566,0.311680,0.030791,-0.675984,-0.707419,0.028807,0.048799,-0.182550,-0.947265,0.012602,-0.511921,-0.127431,-0.069481,0.577728,0.102864,-0.456724,0.052523,0.401400,0.575545,0.266459,0.521979,0.372345,-0.018544,0.104646,-0.335722,-0.295969,0.159633,0.257837,-0.404518,-0.333608,0.490832,0.311385,0.387398,0.505245,-0.293189,-0.186007,0.092905,0.585475,-0.460162,0.143204,0.201779,0.229255,0.138454,0.011398,0.625953,-0.117209,-0.103619,0.140319,0.199063,-0.814463,-0.244154,-0.008521,0.413834,-0.463000,0.329199,-0.356109,0.281736,-0.060309,-0.446380,-0.042489,0.324968,0.063812,0.218153,-0.186115,-0.095056,-0.319028,0.008349,0.309976,0.285142,-0.339559,-0.100916,-0.530375,-0.429472,-0.328007,-0.066973,-0.445192,-0.264795,0.433667,0.220552,0.027944,0.636255,-0.271652,-0.233303,-0.327585,-0.558687,-0.061990,-0.577992,-0.038306,-0.577603,-0.372739,-0.323784,-0.351008,-0.324614,0.038664,-0.214963,0.729145,-0.563014,-0.161001,0.600654,0.154953,-0.382675,0.405313,0.165002,0.116918,-0.308887,-0.095064,0.027817,0.057101,0.331054,0.235573,0.103392,0.143924,-0.315363,-0.005181,0.228730', '1307442', '1293989', '26848640', '3006781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2336387', '曼谷之恋', '剧情', '《曼谷之恋》是泰国第一部于影院上映的同性恋电影，并同时作为2007年11月22日-12月2日在香港举办的同志影展第18年的开幕影片。云(Rattanabalang Toesawad 饰)是个冷酷无情的杀手，除了妈妈与唯一的弟弟雾以杀人为目标过日子的他，从没奢望过任何感情，也从来没爱过谁。他的暗杀目标石(Chaiwat Thongsang 饰)是一个富有又英俊的警察，生活舒适还有个美丽的女朋友，看似美满的生活仍让他觉得生命中好像缺了一样很重要的东西。本来该杀了石的云，不知为何却下不了手，反而让两人都成了黑道追杀的目标。躲避的过程中，云为了保护石而受了重伤，在石细心的照顾下渐渐复原，而超越友谊的情愫也在两人心中滋长。面对这份陌生的同性之爱，犹豫不已的云选择了逃避，而热情执著的石坚守这自己的感情。最终他们会如何面对自己心中的情感？©豆瓣', 'Rattanaballang Tohssawat', '普安农', 6.8, 6474, 'tt1135961', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2578786781.jpg', 3, 11.9, 43, 28, 14.2, '-0.118304,-0.091264,-0.780345,0.771879,0.037343,-0.151612,0.724243,-0.043811,-0.516652,-0.189524,0.067425,0.548177,-0.003118,0.390606,0.311430,-0.219675,-0.138259,-0.676762,-0.268864,-0.109891,-0.481337,-0.251205,-0.342070,-0.078432,-0.144090,-0.037103,0.756295,0.475756,0.054138,0.279399,0.423306,0.134828,0.137938,0.489361,0.007435,-0.226261,-0.235071,0.338899,-0.447111,0.125107,0.103606,-0.301743,-0.228841,0.367122,0.008396,0.507813,0.556741,-0.273825,-0.298485,-0.082589,0.423096,-0.260454,-0.044688,-0.128764,-0.039256,-0.068868,0.091596,0.166167,-0.211673,0.101448,0.120729,-0.208742,-0.987201,0.091273,0.219321,0.060398,-0.573423,0.571668,-0.026331,0.169971,-0.281785,-0.243737,0.089408,0.209852,0.170792,0.474429,-0.379726,0.121642,-0.378928,0.241838,0.824798,0.260782,-0.437922,0.426720,-0.284836,-0.449508,-0.265096,-0.283731,-0.292535,-0.034103,0.073572,0.287132,-0.239328,0.284491,-0.490958,0.115790,-0.072718,0.062915,0.164550,-0.601123,-0.033536,-0.362811,0.064192,-0.588707,-0.321994,0.057719,0.181296,-0.413760,0.741724,-0.972924,0.109757,0.465412,0.385820,-0.730732,0.638223,0.455398,-0.238170,-0.146564,-0.171411,0.509365,-0.044137,0.046290,0.090076,0.098590,0.040126,0.057173,-0.276089,0.573797', '30163500', '1301022', '35030151', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2336735', '生命之树', '剧情', '故事发生在20世纪50年代的美国中西部，通过讲述一个典型的美国家庭故事表达了创作者对生命的看法。主人公是一名叫杰克（亨特·迈奎肯 Hunter McCracken 饰）的11岁男孩，他是家里三兄弟中的一个，父亲（布拉德·皮特 Brad Pitt 饰）严厉而粗暴，母亲（杰 西卡·查斯坦Jessica Chastain 饰）温柔却又无所作为，兄弟的死令他的家庭发生了改变。成年后的杰克（西恩·潘 Sean Penn 饰）生活得不顺利，当他思考自己的人生轨迹时重新面对了自己的记忆，开始站在不同的角度看待他的父母、家庭、童年，最后终于原谅了父亲，并且对生命和生活还有信仰有了更深的理解。本片获得第64届戛纳电影节金棕榈大奖，并获得最佳影片、最佳导演、最佳摄影提名。©豆瓣', '布拉德·皮特', '泰伦斯·马力克', 7.1, 43657, 'tt0478304', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2242204049.jpg', 2.9, 9.1, 35.6, 33.3, 19.1, '0.064741,0.025142,-0.529048,0.773533,-0.055572,-0.257034,0.768922,0.077021,-0.370430,-0.081577,0.136403,0.985529,-0.091861,0.329814,0.317692,-0.011462,-0.475065,-0.808975,-0.030908,0.108934,-0.314602,-0.667489,-0.127338,-0.052057,-0.222390,-0.331257,0.655537,-0.081377,-0.109329,0.348120,0.321357,0.339140,0.213494,0.192983,-0.208233,0.310047,0.246561,0.280247,-0.458183,0.179770,0.141410,-0.096592,-0.084481,0.432779,-0.061433,0.489884,0.802903,-0.256630,-0.194577,-0.015198,0.609200,-0.098767,-0.236795,-0.087221,0.143481,-0.056030,0.058909,0.344865,0.109532,-0.080595,-0.049436,-0.165526,-0.797018,-0.077948,0.164148,0.221066,-0.476036,0.246317,-0.060038,0.114326,0.125147,-0.108547,0.232619,0.359887,0.486467,0.426316,-0.315800,-0.065182,-0.314393,0.530050,0.591529,-0.087313,-0.710341,0.625312,-0.715401,-0.488862,-0.025799,-0.259868,-0.541080,0.106113,0.274762,0.157390,-0.133406,0.276588,-0.314309,-0.134782,-0.038571,-0.274529,0.231631,-0.524041,0.036517,-0.451933,-0.342794,-0.483075,-0.289855,-0.199857,-0.036573,-0.428368,0.906339,-0.733851,0.195742,0.327741,0.254856,-0.423855,0.792565,0.222377,0.159956,-0.454988,0.287750,0.465292,-0.214091,-0.185359,-0.217844,0.186579,0.064099,-0.068865,-0.284245,0.714786', '30162520', '27602116', '1303034', '1303542');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2336737', '米尔克', '剧情', '哈维•米尔克（Harvey Milk），被美国时代杂志评为20世纪代表人物之一的同性恋政治家。1970年，年届不惑事业有成然而感情生活却一路坎坷的小商人米尔克（Sean Penn 西恩•潘 饰），偶然邂逅了年轻英俊的男子斯科特•史密斯（James Franco 詹姆斯•弗兰科 饰），两人迅速陷入热恋，米尔克自此也开始认识到自身真正的性取向。不久他们搬到旧金山卡斯特罗街，合力经营一家摄影器材商店。随着两人恋情的公开化，小店逐渐成为同志们的聚集地，最后扩展到整个街区。然而同志在当时仍不为公众所接受，他们依然受到种种不公平的待遇。米尔克有感于此，决心从政，竞选城市监察员，以一己之力推动政府改善同志们的境遇。屡战屡败的米尔克最终获得成功，却也遭到保守势力的责难与攻击……本片荣获2009奥斯卡最佳男主角奖（Sean Penn）和最佳剧本奖、2009独立精神最佳剧本奖和最佳男配角奖（James Franco）。', '西恩·潘', '格斯·范·桑特', 8.3, 49913, 'tt1013753', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2434259081.jpg', 0.2, 1.1, 16.7, 49.4, 32.6, '0.038802,-0.023616,-0.505735,0.361707,0.126837,-0.172556,0.335091,0.156602,-0.501592,-0.292214,0.267038,0.913571,-0.358384,0.149121,0.525220,-0.342301,-0.473221,-0.569131,0.018796,0.035137,-0.024837,-0.364036,-0.329567,0.009574,-0.408823,-0.222276,0.846813,-0.063007,-0.260535,0.249727,0.473263,0.256960,-0.159937,0.153171,-0.080462,0.182639,0.442546,-0.239500,-0.742911,0.342069,-0.127501,-0.272470,-0.319803,0.002524,0.016020,0.192032,0.548454,-0.009318,-0.183558,0.109788,0.631527,-0.238690,-0.228089,0.087670,0.457496,-0.109650,0.201074,0.142766,0.144270,-0.011589,0.015647,-0.313313,-0.392142,0.148363,0.176801,0.051422,-0.309101,0.177324,0.110354,-0.010267,-0.173098,-0.119888,-0.132175,0.274283,0.168350,0.098981,-0.134892,0.168463,-0.330405,0.376297,0.573292,0.213464,-0.695541,0.168479,-0.241449,-0.624360,-0.176830,-0.455220,-0.496716,-0.055485,0.463606,0.234291,0.165461,0.351519,-0.475102,0.051936,-0.092195,-0.171335,0.189157,-0.132735,0.120114,-1.023319,-0.258646,-0.253076,-0.014711,0.055282,0.026854,-0.216350,0.708457,-0.518578,0.043190,0.310309,0.099028,-0.576489,0.738704,-0.004880,0.219407,-0.295060,-0.270539,0.303739,-0.015697,0.096644,-0.043066,0.130625,-0.180887,-0.214838,-0.102028,0.280964', '1780122', '24751811', '3077791', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2336783', '科学怪狗', '喜剧', '《科学怪狗》是根据波顿1984年拍摄的一部同名短片改编的，也是首部波顿参与制作的迪士尼动画。本片采用黑白单格拍摄，并会后期转制成3D形式，为了配合剧情，制作超过200只木偶和道具。小男孩维克多的爱狗Sparky被车撞死后，他十分伤心。在学校上课的时候，当老师做用电击 青蛙的方法使其神经抽搐的实验时，他有了救活他的小狗的灵感。于是晚上，他引了天上的雷电电击小狗的尸体，使它复活。重生的小狗吓坏了男孩家的邻居们，他们视这只狗为怪物。邻居们追赶狗时将狗和男孩逼进一间小木屋，失手几乎烧死他们。但小狗却将男孩救出，自己死去。邻居和男孩的父母为之感动，决心再次救活它。他们用汽车发动机制造电能，又一次救活了这只狗……©豆瓣', '马丁·肖特', '蒂姆·波顿', 7.7, 59403, 'tt1142977', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1572725518.jpg', 0.3, 2.4, 30.3, 47.7, 19.3, '-0.167169,-0.346860,-0.287784,0.278502,-0.207241,-0.113491,0.660629,0.014524,0.022626,0.035682,0.428079,0.698709,-0.172647,0.229327,-0.216813,0.015984,-0.172588,-0.449445,-0.000209,0.164018,-0.185003,-0.000985,-0.361307,-0.281513,0.159611,-0.400420,0.665826,-0.189982,-0.226269,0.172934,0.038358,-0.049388,-0.049593,0.268511,-0.187174,0.252937,-0.186400,-0.173436,0.258738,-0.067101,-0.065376,-0.146381,0.004257,0.039864,-0.184770,0.372686,0.794132,-0.392153,-0.097691,-0.450102,0.294092,-0.388086,-0.158693,-0.072425,0.058561,-0.038438,0.331672,-0.156183,-0.052742,0.050543,0.124807,0.063166,-0.692516,-0.118456,-0.022743,-0.013464,-0.440357,0.204144,-0.156339,0.450700,0.274715,-0.297805,0.053821,-0.011415,0.216743,0.446452,-0.232150,-0.030483,-0.589956,0.252884,0.428749,-0.408534,-0.324722,0.612887,-0.332954,-0.447795,0.052541,-0.246926,-0.062236,0.014063,0.506940,0.077167,-0.529976,-0.017558,-0.692503,-0.300212,-0.222852,-0.024943,-0.200107,-0.341911,-0.113431,-0.564308,0.229632,-0.144223,-0.040285,-0.177821,0.178912,-0.483136,0.669813,-0.456297,0.087239,0.595220,0.124589,-0.263867,0.726283,-0.274681,-0.023555,-0.216192,0.153522,-0.101920,0.226140,0.340334,0.325713,0.340763,0.249436,0.023931,-0.679421,0.599642', '2357162', '24733428', '1302661', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2336785', '爱丽丝梦游仙境', '奇幻', '爱丽斯（米娅·华希科沃斯卡 Mia Wasikowska 饰）始终被同一个梦魇所困扰，直到她20岁时参加的一场聚会。本认为是一场无聊至极的聚会而已，没想到却是精心策划的求婚仪式。面对养尊处优的公子哥哈米什突如其来的求婚，毫无准备的爱丽斯着实被吓了一跳。爱丽斯被一只身马甲 的兔子所吸引，在追赶过程中爱丽斯掉入了一个深不见底的树洞里，来到了一个如同仙境般不可思议的“地下世界”。此时，生活在地下世界的善良人们似乎都在盼望着她的到来，可是她却认为这是一场梦，只想快点醒过来回到现实世界。然而，在认识疯疯癫癫的疯帽子（约翰尼·德普 Johnny Depp 饰）之后，爱丽斯才知道地下世界正处于“红桃皇后”（海伦娜·伯翰·卡特 Helena Bonham Carter 饰）的血腥统治之下，按照“皇历”的预言，只有她才能帮助“白色皇后”（安妮·海瑟薇 Anne Hathaway 饰）战胜“红桃皇后”，让地下世界重归和睦与安宁……这部迪士尼的3D立体电影由曾带给人们无数惊喜的奇幻大师蒂姆·波顿（Tim Burton）执导，其灵感来自于英国著名童话大师刘易斯·卡洛尔（Lewis Carroll）的《爱丽斯漫游仙境》和《爱丽丝镜中奇遇记》。', '米娅·华希科沃斯卡', '蒂姆·波顿', 7.4, 391353, 'tt1014759', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p481556187.jpg', 0.4, 3.8, 37.5, 41.8, 16.4, '0.068677,0.225061,-0.605821,0.424761,-0.040972,-0.017140,0.605797,0.051239,-0.515051,-0.470280,0.364003,0.828261,-0.516496,0.207904,0.408170,0.075553,-0.333652,-0.515279,-0.291117,-0.206367,-0.065363,-0.296913,-0.425330,-0.001984,0.002796,-0.523208,0.628633,0.076733,-0.110742,0.332006,0.193588,0.319765,-0.125077,0.426002,-0.138579,-0.197814,0.187259,0.194880,-0.319909,0.131709,-0.181089,-0.037577,-0.083046,0.340441,-0.087879,-0.064869,0.488148,-0.694840,0.000349,-0.114460,0.484111,-0.290708,-0.139731,0.071126,0.226332,-0.190391,0.203546,-0.112207,0.041496,0.154962,0.293973,-0.332346,-0.667105,0.113788,0.266368,0.346469,-0.318927,0.248081,0.149702,-0.021648,0.063408,-0.284653,0.133991,0.073649,0.624112,0.667791,-0.153439,0.069198,-0.320528,0.144103,0.632936,0.025644,-0.346418,0.414566,-0.230784,-0.275024,0.095396,0.016404,-0.516844,0.203369,0.322757,-0.099933,-0.243690,0.386883,-0.458194,-0.099531,-0.498291,-0.266223,-0.122319,-0.562180,-0.372474,-0.615806,-0.078589,-0.199453,0.084313,0.000608,0.151021,-0.291510,0.378014,-0.701684,0.559726,0.454824,-0.010268,-0.019949,0.625369,0