INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2337773', '网络杀机', '悬疑', '单身妈妈珍妮弗·马什（迪安·雷恩 Diane Lane 饰）是供职于FBI网络犯罪科的探员，她日常的工作就是对网络进行监视，查找任何一个盗取信用卡及其他可能造成危害的犯罪分子。在一次围剿信用卡盗贼的行动中，珍妮弗偶然进入一个名为KillwithMe的网站，网站通过视频直播一只小猫受虐死去的全过程。珍妮弗直觉该网站背后必有黑幕，她试图追踪IP和服务器，最终一无所获，似乎她所面对的对手具有颇为复杂的背景。不久，该网站更新内容。画面中一个男子被捆绑起来，网站宣称浏览者越多，那名男子死得越快。珍妮弗等人眼睁睁看着男人死去，她决定不惜一切代价救出幕后黑手，却让自己也卷入这个死亡漩涡之中……©豆瓣', '戴安·琳恩', '格里高利·霍布里特', 6.6, 6591, 'tt0880578', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1258919988.jpg', 1.4, 8, 55.6, 29.2, 5.9, '0.043370,0.004358,-0.544777,0.642768,0.003155,0.100057,0.635781,-0.141226,-0.409496,-0.165612,0.269828,0.736825,-0.210380,0.223317,0.067241,0.057805,-0.238824,-0.619706,0.045002,-0.249432,-0.346912,-0.209745,-0.356140,-0.476806,0.072308,-0.088872,0.831369,0.105533,-0.252641,0.074842,0.274504,0.206120,-0.380918,0.620571,0.073696,-0.237882,0.194818,-0.466651,0.018044,0.226035,0.082887,-0.141777,0.095344,0.274165,-0.133507,0.106872,0.800013,-0.304257,-0.369576,-0.157612,0.574178,-0.470867,-0.126283,0.005641,0.486821,0.128447,0.236044,0.162850,-0.326541,0.003159,-0.077777,0.125066,-0.970691,-0.220735,-0.027740,0.519803,-0.356271,-0.040791,-0.338062,0.249555,0.058674,-0.323120,-0.144259,0.115572,0.361146,0.169106,-0.100747,-0.191876,-0.347957,0.182284,0.117606,0.113243,-0.176151,0.254704,-0.015619,-0.370478,-0.079981,-0.038598,-0.351177,0.000708,0.452762,-0.108431,-0.368577,0.249117,-0.352744,0.122602,-0.239478,-0.282235,-0.397818,-0.538165,-0.267788,-0.754270,-0.250073,0.129373,-0.043332,0.136223,0.101995,-0.293344,0.695566,-0.577794,0.052320,0.838687,0.348012,-0.560463,0.379324,0.449983,0.132614,-0.182102,-0.225232,0.118497,0.265596,0.336048,-0.032903,0.024293,0.194137,-0.343603,-0.303546,0.321265', '25928048', '26759820', '4820775', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2338019', '欲盖弄潮', '剧情', '无论如何，扎克（Trevor Wright 饰）看起来都是一个如此阳光、温柔的男孩，他热爱冲浪，喜欢学习，艺术素养颇高，而且有着十分难得的家庭观念。为了照顾姐姐的孩子，他甚至可以放弃读书的机会。平常的日子里，扎克便和好友盖布（Ross Thomas 饰）一起玩耍。某天，他结识了盖布的哥哥肖恩（Brad Rowe 饰）——一个在好莱坞小有名气的同性恋作家。他们互相欣赏，渐渐为对方所吸引，一段不被亲人们所理解的爱情悄悄滋生……本片荣获2007年西雅图同性恋电影节观众奖最佳新人导演和最佳影片奖；2007年坦帕同性恋国际电影节最佳摄影、最佳女配角（Tina Holmes）、最佳影片和最佳男主角（Trevor Wright）4项大奖。©豆瓣', '特莱沃·怀特', '乔纳·马科维茨', 8.1, 41978, 'tt0942384', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1414965747.jpg', 0.3, 1.6, 21.9, 45.3, 30.9, '-0.114331,-0.272123,-0.452575,0.811783,-0.019538,-0.011887,0.415826,0.065390,-0.492176,-0.185128,0.180865,0.950916,-0.282207,0.097017,0.385599,-0.114352,-0.472525,-0.615266,0.040437,-0.106166,0.000223,-0.276963,-0.608770,-0.006513,-0.458978,-0.148640,0.808763,-0.161098,0.042770,0.578097,0.384940,-0.030330,0.189764,0.148956,-0.109439,-0.148770,0.247006,0.164078,-0.369254,0.360601,-0.000021,-0.001264,-0.190386,-0.075470,0.156430,0.001795,0.672925,-0.172931,-0.061116,0.006363,0.615234,-0.396165,-0.042729,0.064962,0.063728,-0.264834,0.551829,0.005013,0.137189,-0.000314,0.075861,-0.352132,-0.569315,0.134356,0.300775,-0.114156,-0.475731,0.529574,0.115735,-0.019294,-0.107655,-0.071637,0.095809,0.088052,0.245031,0.128508,-0.275363,0.099070,-0.120587,0.757060,0.436189,0.195858,-0.327482,0.419835,-0.535464,-0.646353,0.016326,-0.276950,-0.691217,0.073826,0.326277,-0.093631,0.016013,0.147938,-0.385856,-0.058957,0.261877,-0.016120,0.091112,-0.513854,0.105707,-0.761701,-0.079141,-0.448790,-0.039245,-0.304299,0.095964,-0.426717,1.065404,-0.950141,0.193611,0.423913,0.135597,-0.430687,1.076275,0.075984,0.041853,-0.408090,-0.439531,0.191416,-0.289524,-0.302990,-0.139840,0.374121,-0.036143,-0.307932,-0.254503,0.447138', '27602116', '3811356', '1870681', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2338056', '鬼镇', '喜剧', '在纽约行医的伦敦牙医伯特伦•平库斯（瑞奇•吉弗斯 Richy Gervais 饰）不善与人相处，自私自利又愤世嫉俗。在一次结肠手术意外中，伯伦特假死7分钟，醒来后便具有了与鬼魂交流的能力。被众鬼魂骚扰烦不胜烦的伯伦特遇到了生前是公共关系专家的鬼魂弗兰克（格雷格•金尼尔 Greg Kinnear 饰），为求清净答应了他的请求，帮助阻止弗兰克遗孀、考古专家格温（蒂娅•莱欧妮Téa Leoni 饰）与人权律师男友理查德（比利•坎贝尔 Billy Campbell 饰）再婚。在与格温的接触中，伯伦特发现自己竟逐渐坠入爱河；而格温与理查德的婚事如愿取消，却并未达成弗兰克了结尘缘的心愿。不仅如此，众鬼魂求伯伦特协助完成最后愿望的请求愈演愈烈，这使一贯以自我为中心的伯伦特无所适从……本片获俄亥俄中部影评人协会最佳被忽视电影奖和卫星奖最佳男主角（瑞奇•吉弗斯）。©豆瓣', '瑞奇·热维斯', '大卫·凯普', 6.9, 8435, 'tt0995039', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1925234250.jpg', 1, 5.9, 47.2, 37.5, 8.4, '0.173858,-0.104059,-0.423667,0.550828,0.185434,-0.655172,0.428687,0.246988,-0.719350,-0.479169,-0.286464,0.663645,-0.440383,-0.024017,0.354998,-0.010422,-0.434018,-0.833896,-0.020659,0.019475,-0.035382,-0.615721,-0.204256,-0.342007,-0.100045,-0.662578,0.269896,0.018994,-0.145840,0.390211,0.330139,0.683394,0.106959,0.301973,0.174831,0.018498,0.147364,-0.154911,-0.310163,0.106500,0.012601,-0.064878,-0.109568,-0.047140,0.350825,0.419378,0.466309,-0.169812,-0.038897,-0.219497,0.162686,-0.120925,0.164333,0.234102,0.249477,-0.288334,0.192562,0.355189,-0.115298,0.041412,0.076209,-0.105993,-0.683300,0.101018,-0.075718,0.131934,-0.433507,0.190436,-0.244058,0.046294,-0.111239,-0.117651,0.000173,0.438324,0.181502,0.090769,-0.159008,-0.157241,-0.207694,0.277794,0.341889,0.130411,-0.350840,0.092922,-0.200550,-0.595060,0.086896,-0.165603,-0.264009,-0.042306,0.287180,0.152208,0.114747,0.281700,-0.421463,-0.474612,-0.497340,0.012087,-0.215248,-0.376512,0.101145,-0.900239,0.052510,-0.103594,-0.247911,-0.145046,-0.004912,-0.378503,0.260562,-0.659330,0.370174,0.449723,0.185238,-0.062749,0.556110,0.099537,0.298571,-0.456676,-0.117034,0.297039,0.098170,0.308603,0.291672,-0.009655,0.011034,-0.127524,-0.206642,0.310581', '25723905', '1293656', '1307442', '2028645');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2338058', '一个购物狂的自白', '喜剧', '居住在美国纽约丽贝卡·布鲁姆伍德（艾拉·菲舍尔 Isla Fisher 饰）是一家庭园杂志的记者，在这个繁花渐欲迷人眼的国际大都市，这个美丽女孩漫无边际的购物欲望得到极大宣泄，不实用的服饰源源不断运回家。然而硬币的另一面，却是由此导致的债台高筑。糟糕的财务状况让她的生活一团糟，虽然试图戒掉购物瘾，不过最终都在心仪的商品之前败下阵来。另一方面，丽贝卡希望进入梦寐以求的阿列特杂志供职，阴差阳错进入了该杂志旗下的一个财经杂志编辑部。对理财一窍不通的她偶尔写了一篇角度新颖的投资文章，受到了读者和业内的好评，甚至爱情也随即降临。不过谎言总有拆穿的一天，更何况还有那沉重如山的债务摆在眼前……本片根据英国作家索菲·金塞拉（Sophie Kinsella）的“购物狂”系列作品改编。©豆瓣', '艾拉·菲舍尔', 'P·J·霍根', 6.5, 65782, 'tt1093908', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p672653047.jpg', 2.3, 12.1, 53.3, 25.3, 7, '0.382354,0.093600,-0.653716,0.622413,0.137427,-0.160015,0.547711,0.211024,-0.303751,-0.258552,0.222679,0.663318,-0.197531,0.254089,0.329332,0.047116,-0.255448,-0.397725,0.102087,-0.158273,-0.082195,-0.372651,-0.433187,-0.253446,-0.201138,-0.108493,0.697259,0.250429,-0.391663,0.220399,0.223458,0.201197,0.134257,0.362107,-0.179504,-0.036834,0.107465,0.051321,-0.067880,0.346027,0.160233,-0.277827,-0.047381,0.206158,0.076717,0.240977,0.627141,-0.171021,-0.216538,0.323792,0.864335,-0.172835,-0.059414,0.042078,0.033227,0.088467,0.106967,-0.166189,-0.393233,0.001994,-0.068087,-0.132233,-0.838633,-0.282415,0.084776,0.269474,-0.538002,0.594875,-0.224432,-0.130989,-0.203140,-0.197316,0.035054,0.164320,0.228038,0.420185,0.049442,0.204531,-0.524839,0.382414,0.225307,0.391514,-0.409200,0.480902,-0.598277,-0.247700,-0.148744,-0.179342,-0.449346,-0.108249,0.368229,0.062572,-0.081614,0.208980,-0.794528,0.148637,-0.035505,-0.387508,0.098099,-0.363444,-0.337946,-0.763583,-0.214817,-0.220544,-0.116961,-0.245983,0.326691,-0.251338,1.085305,-0.575466,0.049311,0.551845,0.202137,-0.486632,0.711908,0.098030,-0.091960,0.044661,-0.341267,0.373534,0.220622,0.386982,-0.086992,0.258920,0.254411,-0.486997,-0.347836,0.661986', '27602116', '22265121', '24284209', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2338069', '亲密如贼', '惊悚', '精通算计又胆大心细的珠宝大盗凯斯·雷普利（摩根·弗里曼 Morgan Freeman 饰）在搭档维克多不幸身亡后，为了帮其还清巨额赌债，不得不接下债主尼基的一担高难度任务——窃取俄罗斯皇家彩蛋。雷普利开始四处物色搭档，一个偶然的机会他盯上了身手敏捷的街头扒手马丁（安东尼奥·班德拉斯 Antonio Banderas 饰），能说会道的雷普利很快说服了他一起加入这次任务，联手破解皇家重重防线。与此同时，维克多的女儿艾莉丝（拉妲·米契尔 Radha Mitchell 饰）意外出现，她的性感魅力使马丁沉迷，两人很快陷入热恋。然而就在雷普利和马丁闯入了戒备森严的皇家金库，准备实施盗宝计划之时，却发现警方早已在此恭候多时，而另一边，黑帮老大尼基则劫持了艾莉丝以要挟两人必须拿下彩蛋，更意想不到的是，马丁的身份也出现了巨大反转。在这千钧一发的关头，雷普利还能否成功扭转局势全身而退呢？', '拉德·舍博德兹加', '米密·莱德', 6.1, 8071, 'tt1112782', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p776596459.jpg', 2.6, 15.8, 59.1, 18.9, 3.5, '0.009902,0.184781,-0.642559,0.336652,-0.158328,-0.332250,0.380154,0.177435,-0.287613,-0.364759,0.151440,0.660295,-0.241766,-0.223816,0.541776,0.016889,-0.402952,-0.610755,0.039928,-0.125669,-0.201261,-0.507437,-0.496898,-0.374205,0.118982,-0.342277,0.252589,0.281851,-0.222750,0.323150,0.414228,0.427109,-0.153715,0.345569,-0.079752,0.001901,0.310020,-0.272164,-0.193044,0.250604,-0.101838,-0.328349,-0.103033,0.008573,0.317191,0.406033,0.333026,-0.115769,0.149993,-0.007904,0.164528,-0.329532,0.084014,-0.060857,0.286506,-0.281187,0.091292,-0.039852,-0.218951,-0.121149,0.298954,-0.161723,-0.857929,0.256362,0.068045,-0.040932,-0.472869,0.150859,-0.166293,0.303939,-0.042417,-0.237869,-0.128358,0.497512,0.259155,0.001528,-0.084810,0.027911,-0.524455,-0.201205,0.511753,-0.085242,-0.050465,0.051832,0.148920,-0.443693,0.028667,-0.010934,-0.052363,-0.205486,0.887508,-0.003605,0.230221,0.232106,-0.354161,-0.335833,-0.608907,0.152953,-0.179717,-0.345937,0.017464,-0.750857,0.047154,0.050877,-0.400970,0.264333,0.036762,-0.135817,0.297507,-0.638369,0.163088,0.615937,0.129048,-0.176581,0.393698,0.008142,0.292777,-0.142238,-0.247497,0.010581,0.334601,0.249673,0.263348,0.353902,0.090134,-0.265961,-0.177992,0.390327', '1307442', '1301345', '1306723', '1300324');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2338070', '绝命时钟2:22', '爱情', '有严格作息规律的男主角迪伦（米契尔·哈思曼 Michiel Huisman 饰）有一种天生的洞察规律的能力，某日下午2时22分，身为航空管制员迪伦·布兰森被神秘光亮所麻痹，而这差点让他指挥的飞机失事。从此他每天都会感受到这光亮，渐渐发现自己身处某种循环之中。一次非常偶然的机会，迪伦遇见了让他一见钟情的莎拉（泰莉莎·帕尔墨 Teresa Palmer 饰），二人聊天惊讶发现，莎拉就是迪伦差点酿成飞行事故的航班乘客，非常巧合的是他们同年同月同日出生。随着二人的了解深入，迪伦与莎拉的巧合也越来越多，频繁出现的幻觉与不断循环的事件将二人的命运与三十年前发生在纽约中央车站一起情杀案联系在一起，迪伦一直探究“2:22”背后的秘密，发现三十年前的凶杀案即将重演。', '泰莉莎·帕尔墨', '保罗·柯瑞', 5.8, 7717, 'tt1131724', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2511529908.jpg', 4.9, 25.3, 50.5, 15.7, 3.5, '0.360864,-0.002978,-0.920957,0.479936,0.190865,0.062193,0.815022,-0.102053,-0.705783,-0.401321,0.158668,0.898948,-0.615306,0.227259,0.410376,-0.086806,-0.220268,-0.726380,0.010451,-0.113206,-0.348854,-0.648697,-0.348137,-0.085468,-0.065031,-0.395377,0.315463,0.123524,-0.069601,0.680259,0.065727,0.087255,-0.417880,0.641425,-0.142700,-0.121541,0.160279,0.053918,-0.130042,0.073302,0.186151,-0.276249,0.268686,-0.074662,-0.060005,0.263060,0.689505,-0.252597,-0.352775,-0.084677,0.500543,-0.031671,-0.078484,0.007746,0.535193,0.170497,0.130778,0.270312,-0.167114,-0.155467,-0.087169,0.249801,-0.617995,0.138973,-0.042912,0.360474,-0.213934,0.224562,0.224649,-0.244283,0.223179,-0.239128,0.299293,0.629884,0.384949,0.106725,-0.312077,-0.180008,-0.333524,-0.291712,0.756690,-0.079472,-0.346029,0.551730,-0.199207,-0.439369,-0.136051,0.096585,-0.097540,0.133275,0.236628,0.355118,-0.147622,0.542602,-0.530035,0.138170,-0.140804,-0.060060,-0.249403,-0.295221,-0.113168,-0.750271,-0.082080,-0.601469,-0.385107,0.170480,-0.077859,-0.424548,0.190105,-0.770115,0.411061,0.745174,0.197608,-0.153250,0.639438,0.083877,0.150055,-0.251293,0.073205,0.299046,-0.038060,0.247005,-0.103330,0.430096,0.027323,0.150783,-0.365046,0.418859', '34461680', '1916995', '1309172', '1296534');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23398777', '热血高校3', '剧情', '乌鸦学校铃兰高中，新一学年战火再燃。强大可怕的强罗彻（柳乐悠弥 饰）接连摧毁对手的挑战，一步步朝着铃兰的顶点迈进。与此同时，干掉焚八商业四天王的镝木旋风雄（东出昌大 饰）转学来到铃兰，脑瓜灵光的小岐须健一（胜地凉 饰）等人便将宝压在旋风雄的身上，期待他和强罗的最终对决。拳哥（矢部享佑 饰）辗转回来，当初他最疼爱的老大的儿子加贺美辽平（早乙女太一 饰）则已成为铃兰的一年级生，更因击倒强罗而声名鹊起。与此同时，黑咲工业老大柴田浩树（岩田刚典 饰）的发小兼宿敌藤原一（永山绚斗 饰）走出看守所，在黑道的指示下勾结暴走族ODA对黑咲和铃兰分别展开狩猎，而他和加贺美联手则将战火推向顶点……本片根据高桥弘的同名原作漫画改编。©豆瓣', '东出昌大', '丰田利晃', 5.3, 23974, 'tt2825120', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2168195366.jpg', 13.1, 33.5, 37.2, 9.9, 6.3, '0.083878,-0.065738,-0.577278,0.419160,0.242209,-0.290273,0.507668,0.335224,-0.036320,-0.227337,0.362251,0.509433,-0.241586,0.072333,0.443058,-0.110705,0.088043,-0.790104,-0.321424,-0.167713,-0.123602,-0.324284,-0.126475,0.118981,0.119101,-0.167222,0.760166,-0.026468,-0.197571,0.635870,0.376594,0.434017,-0.229172,0.054342,-0.006892,0.157587,-0.073261,0.103287,-0.233583,0.259450,-0.285002,-0.245453,-0.048858,0.003876,0.067665,0.059966,0.664249,-0.292096,0.257592,-0.329924,0.225383,-0.308665,-0.336382,0.147334,0.611650,-0.169419,-0.043040,0.197161,-0.100311,0.116978,-0.000741,-0.126758,-0.629645,0.190417,0.119929,0.014991,-0.466132,0.441324,0.070248,0.058678,0.294561,-0.111902,-0.031755,0.186932,0.070482,0.218778,-0.382868,0.412012,-0.020273,-0.032544,0.412551,-0.138220,0.170585,-0.005957,0.151477,-0.159338,-0.303279,-0.167106,-0.009574,-0.302787,0.374851,0.167459,0.206062,0.129111,-0.566896,-0.164828,-0.011898,-0.019573,0.257513,-0.208362,-0.125364,-0.504500,-0.039856,-0.375696,-0.247104,0.229445,0.224674,-0.049985,0.765285,-0.672316,-0.028958,0.212965,0.326332,0.003700,0.191570,0.013130,-0.069377,-0.252247,-0.117071,0.123169,0.242289,0.456779,0.152358,0.436529,-0.262899,-0.324218,-0.478717,0.249106', '1826173', '10467125', '3811356', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23416554', '地狱医院', '悬疑', '自称来自牛津大学的精神病医生兼学者爱德华·纽盖特（吉姆·斯特吉斯 Jim Sturgess 饰）辗转来到了地处偏远的斯通赫斯特精神病院，他希望跟随卓有成就的塞拉斯·莱姆教授（本·金斯利 Ben Kingsley 饰）学习相关治疗方法。塞拉斯神情阴郁，所采用的治疗方法更与当时盛行的方法迥然不同，不过似乎病患的精神状况都得到了一定程度的缓解和康复。在此期间，爱德华被美丽端庄的贵妇人伊莉莎·格拉芙（凯特·贝金赛尔 Kate Beckinsale 饰）所吸引，这名女子因心因性的歇斯底里症状饱受折磨。初来乍到的爱德华隐隐察觉这座病院的诡异之处，而他随后不久更发现了病院背后那可怕惊人的秘密……本片根据爱伦·坡的短篇小说《塔尔博士和费瑟尔教授的疗法》改编。©豆瓣', '凯特·贝金赛尔', '布拉德·安德森', 7, 13339, 'tt1772264', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192514889.jpg', 0.7, 5.6, 46, 37.6, 10, '0.214237,-0.221771,-0.421372,0.415651,0.000026,-0.233657,0.565712,0.167860,-0.587703,-0.540379,0.255294,0.606960,-0.165522,0.005485,0.442015,0.210113,-0.515527,-0.229439,0.109880,-0.212308,-0.177481,-0.573023,-0.495358,-0.297204,0.099850,-0.877837,0.262834,-0.123268,-0.327052,0.565116,-0.215985,0.714566,0.113741,0.229792,0.169785,-0.241336,0.313111,-0.366741,-0.179103,0.185361,0.379321,-0.111851,-0.116526,0.176358,-0.186776,0.532593,0.489975,-0.203919,-0.221953,-0.142255,0.279830,0.065479,0.183679,0.201918,0.054317,-0.124869,0.265993,0.227668,-0.260728,-0.008229,-0.020857,0.084506,-0.521222,0.018957,0.287715,0.424545,-0.179082,0.215396,-0.280073,-0.219935,0.037467,-0.321075,0.120018,0.192869,0.140443,0.475316,-0.101747,-0.110475,-0.370738,-0.091237,0.262069,0.058813,-0.537448,0.243551,-0.457751,-0.590525,0.108981,-0.075614,-0.283005,0.011051,0.195468,0.057600,-0.119903,0.418224,-0.412164,-0.155387,-0.421884,0.029854,-0.369003,0.110017,-0.040191,-0.939287,-0.052193,-0.184988,-0.064548,-0.325798,0.176854,-0.148178,0.698133,-0.571085,0.326183,0.256517,0.183494,-0.113055,0.237284,-0.170041,0.153332,-0.140276,-0.511434,0.499946,0.118794,0.410146,-0.033455,0.496182,0.173297,-0.377484,-0.441203,0.643426', '2364001', '2369613', '1296805', '1946776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23424586', '猩红山峰', '剧情', '伊迪斯（米娅·华希科沃斯卡 Mia Wasikowska 饰）是一名业余恐怖小说作家，某日，她邂逅了英俊的英国发明家托马斯（汤姆·希德勒斯顿 Tom Hiddleston 饰），后者的彬彬有礼温文尔雅很快就吸引了伊迪斯的注意，两人发展迅速。然而，伊迪斯的父亲卡特（吉姆·比弗 Jim Beaver 饰）却对托马斯充满了敌意，坚决反对女儿同他来往。就在这个节骨眼上，卡特意外身亡，伊迪斯毅然决定离开自己的家乡，跟随托马斯来到了冰天雪地的坎布里亚郡，在这里，矗立着一间豪华而又荒凉的别墅，人们称它为“猩红山庄”。迎接伊迪斯和托马斯的，是托马斯的姐姐露希尔（杰西卡·查斯坦 Jessica Chastain 饰），露希尔诡异而又粗暴的态度让伊迪斯感到十分不适。很快，伊迪斯就发现，在这座仿佛具有生命的别墅里，飘荡着数缕游魂，埋藏了数不清的秘密。©豆瓣', '米娅·华希科沃斯卡', '吉尔莫·德尔·托罗', 6.4, 39368, 'tt2554274', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2260910627.jpg', 1.9, 14.9, 52.9, 23.3, 6.9, '0.319339,0.082836,-0.673492,0.645968,-0.003802,-0.278984,1.012967,0.422286,-0.352962,-0.086587,0.308618,0.819663,-0.225924,0.144129,0.220305,0.338071,-0.421268,-0.406926,-0.014747,-0.170338,-0.152886,-0.544244,-0.308697,-0.413932,-0.013727,-0.344026,0.056245,0.063089,-0.134636,0.627627,0.257488,0.411765,-0.143819,0.691243,-0.078235,0.054273,0.209623,-0.120979,0.092348,0.185401,-0.118661,-0.147027,-0.195265,0.267220,0.035456,0.431544,0.549764,-0.130602,-0.077641,0.138286,0.249231,-0.051423,0.148128,0.141601,0.185957,-0.284502,-0.122372,0.042103,-0.260181,-0.108622,-0.049537,-0.043037,-0.363707,0.133640,-0.013188,0.418944,-0.601205,0.517639,-0.106979,-0.264853,0.158053,-0.256036,0.196090,0.021159,0.063174,0.241817,0.128735,0.088615,-0.373541,-0.085652,0.168899,-0.041829,-0.397603,0.265503,-0.537536,-0.325843,-0.084565,0.192369,-0.558009,-0.348958,0.316480,0.025708,0.077420,0.246084,-0.544279,-0.204112,-0.389213,-0.225467,-0.228829,-0.246333,-0.249323,-0.636935,-0.085543,-0.463503,-0.294557,0.012672,-0.157497,0.002721,0.381374,-0.683428,0.391469,0.466602,0.160054,0.010126,0.564449,-0.291296,0.027791,0.047289,-0.212688,0.612030,0.040050,0.076675,0.094459,0.587713,0.056636,-0.202997,-0.357741,0.688495', '1309172', '1296534', '24639908', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2346881', '破事儿', '喜剧', '彭浩翔用试图他的“破事儿”去解释现代人生活中的困惑或出路。功德心Jason（陈冠希 饰）在酒吧向美女Shirley（郑融 饰）搭讪时说，他其实很有公德心。因为每次小便时他都会用小便顺便将厕所内的粪便残迹冲走，实在帮了清洁工人一个大忙。做节阿富（陈奕迅 饰）和慧英（陈逸宁 饰）相识一个月后开始同居，令阿富万万没想到的是慧英竟然不赞同婚前性行为。这让每晚和慧英睡在一起的阿富备受煎熬。终于，在一个圣诞节，他和慧英用另一种方式解决了问题。增值阿泽（杜汶泽 饰）经常在明哥的介绍下到酒店去嫖娼，至于明哥是谁，他见都没见过。一次，阿泽经明哥介绍去酒店和一名上海来的女孩（张铮 饰）开房，完事后，那女孩请阿泽帮她充值电话卡，只因她听不懂粤语。随后，阿泽来到了女孩常去的宾馆对面的面店吃面，他忽然记挂起那一位来港谋生的上海女孩。尊尼达黄生（金培达 饰）是杀手集团的VIP，一次，杀手集团送给了他一张礼券，凭券可免费杀一人，不过免费杀的那个人他们会派杀手学员去杀，以达到实践目的。乐仔（余文乐 饰）就是其中一名学员，他被派去谋杀保龄球场经理。关键时刻，乐仔的收工时间到了。大头阿慧学生阿琪（邓丽欣 饰）和大头阿慧（钟欣桐 饰）是好朋友。车房修理工飞鹰（麦浚龙 饰）追求阿慧，阿慧问阿琪意见，阿琪随口就说好，因为她想阿慧拍拖后不会再经常烦她。阿慧就真的拍拖了。随后，阿慧有了飞鹰的孩子，本想向阿琪借钱打掉，阿琪因为要存钱和男友去旅游，就叫阿慧和飞鹰结婚吧。阿慧就真的结婚了。随后阿琪也有了孩子，她的男友不顾而去，剩低阿琪一人做未婚妈妈。而飞鹰和阿慧结婚后，事业青云直上。阿慧成了最幸福的女人。德雅星杂志社员工的阿池（', '陈冠希', '彭浩翔', 7.5, 59993, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p486597227.jpg', 0.8, 3.4, 30.7, 49, 16.1, '0.201900,-0.250132,-0.434011,0.336243,-0.390792,-0.409229,0.507040,0.127342,-0.302367,-0.120473,0.094988,0.560791,0.022847,0.334248,0.295506,0.130063,-0.211437,-0.431391,0.132369,-0.295347,-0.447595,-0.225587,0.197762,-0.169732,-0.001845,0.016196,0.127353,-0.253450,-0.024633,0.321356,0.458107,-0.026812,-0.068929,0.557624,-0.225930,0.116334,0.034659,0.104565,-0.146270,0.302775,0.163159,-0.168950,-0.103494,0.059076,0.107786,0.294216,0.394075,0.084027,-0.035727,-0.041857,0.102542,-0.002192,0.000695,0.004789,0.265037,-0.136460,0.453293,0.144330,-0.242007,0.022147,0.041699,0.013829,-0.434429,0.217187,0.007712,-0.083439,-0.596439,0.454782,-0.210203,-0.091175,0.171359,-0.394973,0.229919,0.222876,0.115014,0.237905,-0.098470,0.002257,-0.464522,0.444529,0.648013,0.074540,0.345374,0.339602,0.089331,-0.296399,0.060285,0.066582,-0.331420,0.119346,0.157477,-0.186245,-0.240954,-0.291288,-0.557977,-0.171753,-0.086845,-0.066939,-0.015842,-0.316844,0.005219,-0.233351,0.072735,-0.139704,-0.303782,0.108122,0.189416,-0.067871,0.526918,-0.743638,-0.023919,0.594958,0.554182,-0.589497,0.799103,0.079457,-0.052318,-0.262705,0.043947,-0.246191,0.094567,0.326510,0.286861,0.413892,0.211458,-0.148750,-0.216013,0.196439', '2124718', '2990737', '1302384', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2348020', '告密者', '剧情', '本片根据真实事件改编而成。营养生化学家出身的马克·惠特克（马特·戴蒙 Matt Damon 饰）是美国伊利诺伊斯州迪凯特市AMD公司的副总裁。他领导的赖氨酸新产品试验持续失败，马克报告是日本竞争对手指使某位AMD员工恶意投毒所致。公司向FBI报案，后者开始监听马克家的电话。心惊胆战的马克担心他协助公司与全球赖氨酸生产厂商联合干扰自由竞争、抬高市场价格的不法行为暴露，在妻子金姬（梅兰妮·林斯基 Melanie Lynskey 饰）的劝说下，主动向FBI揭露公司限定赖氨酸价格一事。在FBI探员布莱恩（斯科特·巴库拉 Scott Bakula 饰）和罗伯特（乔尔·麦克哈尔 Joel McHale 饰）的协助下，马克当起了FBI的线人，开始收集公司的犯罪证据。但谁也没想到，马克在揭露AMD公司不法限价行为的同时，自己却隐瞒了一系列无法告人的秘密……本片获金球奖最佳影片原声配乐和音乐剧及喜剧类影片最佳男主角（马特·戴蒙）提名。', '马特·达蒙', '史蒂文·索德伯格', 6.9, 9391, 'tt1130080', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p753782018.jpg', 0.9, 6.2, 47.5, 37.4, 8, '0.119082,0.124467,-0.517588,0.478305,0.083643,-0.053322,0.213921,0.344586,-0.351811,0.014536,0.042987,0.509808,-0.206442,-0.064867,0.236257,-0.030876,-0.650504,-0.519106,0.134805,-0.195517,0.119507,-0.680278,-0.177630,-0.519955,0.008225,-0.304075,0.424014,-0.163563,-0.447988,0.196246,0.494365,0.521056,-0.101011,0.203805,0.377692,0.117481,0.573047,-0.299223,-0.531026,0.319444,0.044491,-0.336706,-0.121926,0.068558,0.502605,0.632175,0.201387,0.067384,-0.080202,-0.128744,0.526279,-0.274867,0.350441,-0.258776,0.447309,0.003869,0.174581,0.449619,-0.295357,0.083977,0.169602,0.011172,-0.910754,-0.126481,0.117366,0.225530,-0.438567,0.041347,-0.617097,0.294718,-0.177257,-0.228791,0.036350,0.335980,0.214289,0.077891,0.041458,0.050600,-0.472422,0.390764,0.284291,-0.026209,-0.207465,0.141192,-0.128577,-0.414272,-0.251942,-0.090680,-0.379717,-0.090905,0.417547,-0.065590,0.263606,0.138698,-0.335699,-0.341837,-0.213706,-0.387130,-0.046006,-0.227070,0.122576,-0.881975,-0.077440,-0.051546,-0.134584,-0.310393,0.256344,-0.059296,0.182654,-0.411005,-0.127099,0.571772,0.299325,-0.438733,0.302000,-0.139503,0.152202,-0.445894,-0.339875,-0.177349,0.164207,0.072233,0.023471,0.155114,0.449144,-0.434367,-0.205122,-