INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2350904', '电锯惊魂5', '悬疑', '饱受癌症折磨，“竖锯”约翰·克莱默（Tobin Bell 饰）油尽灯灭。然而他所创造的“拼图杀人案”却并未就此停止，反而愈演愈烈。警官马克·霍夫曼（Costas Mandylor 饰）曾假借“竖锯”之名向残害他家人的凶手复仇，但他很快成为约翰的猎物。经过一波三折，霍夫曼成为“拼图杀人案”的接班人，只是约翰警世救人的初衷被彻底抛却，取而代之的无休止的血腥杀戮。一场毫无胜算的五人逃生游戏在霍夫曼德主持下展开。另一方面，霍夫曼千方百计隐瞒身份，而警官皮特·斯特拉姆（Scott Patterson 饰）却对其产生怀疑。斯特拉姆千方百计寻找证据，却不曾想已走入霍夫曼布下的残酷迷局……©豆瓣', '托宾·贝尔', '大卫·海克尔', 7.8, 104496, 'tt1132626', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2197047787.jpg', 0.5, 2.8, 28.5, 43.7, 24.6, '0.027447,0.047286,-0.472991,0.199680,0.018349,-0.302485,0.672719,-0.109651,-0.510522,-0.306971,0.210958,0.307825,-0.126366,-0.191152,0.102574,-0.265845,-0.511051,-0.550529,0.301265,0.285543,0.085692,-0.564255,-0.327076,-0.477862,-0.119908,-0.154735,0.544966,0.119098,-0.313402,0.213142,0.224482,0.669258,-0.174025,0.445730,0.193231,0.083024,0.077910,-0.329016,-0.510820,0.221329,0.227228,-0.391853,-0.381657,0.305550,-0.425066,0.636069,0.510669,-0.625985,-0.056172,-0.048686,0.297494,-0.656503,-0.030064,0.264160,0.154004,0.087418,-0.151031,0.474650,-0.228340,-0.084894,0.184017,-0.166583,-0.754673,-0.056035,0.057991,0.495219,-0.123690,0.175230,-0.330057,0.278610,-0.041117,-0.096451,-0.102688,0.055220,0.583399,-0.058337,-0.304119,-0.116809,-0.453587,-0.011264,0.613147,-0.018097,-0.136783,0.166713,-0.112712,-0.131074,0.012446,-0.254909,-0.388982,-0.209643,0.424047,0.171002,0.109611,0.531899,-0.577316,-0.348928,-0.744074,0.052726,-0.049210,-0.202685,-0.011352,-0.536994,-0.221684,0.201332,-0.072896,-0.106686,0.026034,-0.447162,0.060236,-0.512856,0.414078,0.172386,0.019978,-0.282325,0.167286,0.070398,0.136454,-0.244451,-0.272129,0.521175,0.257525,0.199503,0.034563,-0.105738,0.367844,-0.114889,-0.064934,0.546577', '25828589', '1296217', '2988294', '3878157');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2352630', '谍海风云', '剧情', '1941年，美国海军情报局特工索姆斯（约翰•库萨克 John Cusack 饰）奉命来到上海，负责调查好友康纳被暗杀的真相。他以德国先驱报驻上海记者的身份游走于社会名流的酒会。他借助同纳粹工程师穆勒太太的情人关系消除猜疑、获取情报。在一次赌局中，他结识了黑帮头目兰亭的夫人安娜（巩俐 饰），对方与手下的神秘暗语令他好奇。跟踪未果，他只得继续打探。为了调查康纳的死因，他秘密约见了康纳的线人。然而，两人的会面却因为日本军队追查地下党而破产。一次偶然的机会，索姆斯再次与安娜重逢，并且在她的引荐中结识了上海黑社会头目安东尼•兰亭（周润发 饰）及日本情报处田中大佐（渡边谦 饰）。在调查中，索姆斯渐渐发现康纳的死跟一个神秘的日本女人（菊地凛子 饰）有关……©豆瓣', '约翰·库萨克', '米凯尔·哈弗斯特罗姆', 5.8, 20131, 'tt1092634', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p475550455.jpg', 4.1, 21.7, 55.5, 15.3, 3.4, '0.291747,-0.170661,-0.589132,0.606098,-0.086039,-0.233147,0.395911,0.007627,-0.716032,-0.235419,0.431464,0.702876,0.009178,0.145426,0.292070,0.018999,-0.494675,-0.877507,0.217501,-0.190034,0.018770,-0.644279,-0.435553,-0.418460,-0.013004,-0.129415,0.459683,0.134434,-0.107197,0.528773,0.240802,0.493547,-0.394132,0.443954,0.070932,-0.055571,0.711582,-0.322937,-0.523179,0.236469,0.025312,-0.372039,-0.061199,0.166300,0.129387,0.555167,0.466430,-0.268846,0.110970,-0.229796,0.109823,-0.178237,0.078291,0.067426,0.458637,0.183661,0.232014,0.566513,-0.344222,-0.170874,-0.107078,0.241948,-0.458014,0.156820,0.231898,0.460165,-0.369097,0.255113,-0.424320,0.162832,-0.017628,-0.244007,0.161504,0.543905,0.188166,-0.076452,-0.038233,0.029789,-0.324869,0.311319,0.550110,-0.025806,0.189720,-0.108547,0.018961,-0.249258,0.130885,-0.066085,-0.122023,0.086714,0.324097,-0.368412,-0.208173,0.274733,-0.591895,-0.330281,-0.474820,-0.004978,-0.018521,-0.251821,-0.014715,-0.958719,-0.258605,-0.202766,-0.241116,-0.075430,0.211455,0.064812,0.428112,-0.809907,-0.060754,0.876160,0.340301,-0.561940,0.477804,0.064709,-0.052415,-0.446081,-0.184215,0.142290,0.279128,0.293770,0.135326,0.296935,-0.055859,-0.425877,-0.216764,-0.254312', '25723905', '25833539', '2973528', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2353023', '驯龙高手', '动画', '维京岛国的少年小嗝嗝（杰伊•巴鲁切尔 Jay Baruchel 配音）是部落统领伟大的斯托里克（杰拉德·巴特勒 Gerard Butler 配音）的儿子，他非常想像自己的父亲一样亲手屠龙——这些飞龙是岛上维京人放牧羊群的主要天敌——但他每次出现在部落屠龙的战斗中都只给大家徒增烦恼。在一次对抗飞龙的战斗中，希卡普偷偷用射龙器击伤了一只最神秘的“夜之怒龙”，并背着族人放生、豢养，甚至驯服了这只龙，还给它起名“无牙”。希卡普的神秘行径引起了一同训练屠龙技巧的女孩阿斯特丽德（亚美莉卡·费雷拉 America Ferrera 配音）的怀疑。阿斯特丽德发现了希卡普的秘密，却同时被身骑“无牙”御风而飞的美妙体验所震撼。格雷决定在屠龙成人礼上向远征归来的斯托里克和族人讲明真相，说服大家放弃屠龙，却偏偏弄巧成拙，害得“无牙”被俘，一场更大的灾难就在眼前……©豆瓣', '杰伊·巴鲁切尔', '迪恩·德布洛斯', 8.8, 708116, 'tt0892769', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2210954024.jpg', 0.1, 0.4, 9.6, 41.5, 48.4, '0.245281,-0.165991,-0.548432,0.453785,0.033119,-0.484185,0.460205,-0.052850,-0.282785,-0.254997,0.273877,0.592122,0.104807,-0.100403,0.314117,0.073714,-0.355855,-0.406913,0.002877,0.098087,-0.080513,-0.254363,-0.346353,-0.236789,-0.064813,-0.341290,0.394149,-0.225760,-0.224315,0.427954,0.263240,0.398654,-0.000358,0.388040,-0.067088,0.175131,0.001775,-0.203970,0.038341,0.099012,-0.255400,0.103857,-0.426096,0.530949,0.063864,0.217027,0.545863,-0.697898,0.086353,-0.338591,0.063965,-0.465816,0.283606,-0.050178,0.221114,-0.269440,0.121974,0.075119,-0.060780,-0.022683,-0.059383,0.171247,-0.748295,0.034113,-0.017579,0.293266,-0.491397,0.326348,-0.120239,0.188325,0.269288,-0.258301,-0.106303,0.258862,0.243901,0.108738,-0.151196,-0.056296,-0.492872,-0.024743,0.779933,-0.203171,-0.171619,-0.101418,-0.088188,-0.400775,-0.026397,-0.287835,-0.215568,-0.003314,0.400131,-0.044591,0.053771,0.649581,-0.644381,-0.127001,-0.553865,-0.223131,-0.204842,-0.238323,-0.146874,-0.620678,0.023800,-0.070149,-0.335804,-0.209243,0.248910,-0.125778,0.529644,-0.670184,0.285750,0.635143,0.154536,0.085146,0.221411,-0.028557,0.190336,-0.130650,-0.305232,0.265819,0.492074,0.139745,0.166475,0.312790,0.256714,-0.146713,-0.245264,0.634807', '1306723', '2032339', '3213270', '1792917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2353665', '这不是斯巴达', '喜剧', '在军事化的斯巴达，列奥尼达（西恩•马奎尔 Sean Maguire 饰）经过与巨型企鹅的恶战证明了自己是斯巴达最强悍的战士，成功得到斯巴达王位，并迎娶玛戈为皇后。某日，正在对儿子进行毒打训练的列奥尼达接待了波斯使者，对方狂妄的宣称薛西斯王将统治希腊，斯巴达的孩子以后只能在血汗工厂中生产NIKE鞋。怒不可遏的列奥尼达杀死使者以及一干美国偶像，用化妆品贿赂先知请求开战，然而得到的却是丑女贝蒂神女的警告。列奥尼达仍然决定出征，他率领13名用喷漆画出腹肌的战士赶赴隘口布防，用街舞击败了波斯先头部队。肥佬薛西斯用蓝屏电脑特技制造出的大军压境，被列奥尼达弃用的帕里斯•希尔顿又告知波斯人包抄斯巴达军的小路，列奥尼达率众与洛奇、恶灵骑士等波斯大军展开了殊死搏杀。本片改编自《斯巴达300勇士》，用恶搞手法对原片进行了重新演绎。©豆瓣', '西恩·马奎尔', '贾森·弗莱德伯格', 6, 21093, 'tt1073498', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2097797752.jpg', 6.9, 19.5, 46.9, 19, 7.7, '-0.080146,-0.173023,-0.456821,0.661980,0.309829,-0.176857,0.467153,-0.095824,-0.117473,-0.063004,0.697178,0.447134,0.143616,-0.337881,0.548710,-0.091514,-0.388565,-0.656473,-0.066103,0.088091,-0.143886,-0.344978,-0.091945,-0.274140,0.102342,-0.591857,0.655773,-0.098779,-0.182308,0.162289,0.152902,0.135890,0.095316,0.137580,0.111119,-0.051926,-0.014451,-0.587711,-0.251357,0.222473,-0.416858,-0.082005,-0.322189,0.050768,0.012644,0.269774,0.549498,-0.729380,0.329847,-0.243233,0.009612,-0.231639,0.159599,0.167117,0.159931,0.119233,-0.035368,-0.065479,0.282229,-0.013119,-0.035585,-0.013276,-0.778603,-0.159177,-0.230573,-0.131553,-0.694009,0.382039,-0.316779,0.278690,0.276245,-0.239798,-0.020364,0.347738,0.443859,0.282202,0.228182,-0.096555,-0.520843,0.092433,0.236843,-0.102053,-0.239568,-0.348378,0.051926,-0.488482,0.207685,-0.458196,-0.108494,-0.002535,0.225497,-0.154852,0.305961,0.200653,-0.618410,-0.179960,-0.471662,-0.323371,0.072860,-0.233794,-0.053802,-0.859267,-0.010979,-0.006951,0.081566,0.187939,0.417261,0.138180,0.521051,-0.630971,-0.025808,0.148222,0.564015,-0.423114,0.203474,0.081316,-0.060882,-0.078069,-0.069785,0.239867,0.384738,0.266260,0.269165,0.228101,0.008105,-0.160375,-0.271491,0.545870', '1294917', '2369613', '1046712