INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2354729', '神秘代码', '剧情', '1959年，美国马塞诸塞州列辛顿威廉道斯小学，该校即将迎来校庆日，小女孩露辛达•安伯利（Lara Robinson 饰）提出的创意为校长所采纳。校庆日时，学生们将画下自己对未来的设想，并集中放入金属时间囊中埋入地下，准备50年后重新开启。校庆日之后，举止怪异的露辛达用鲜血在墙上写下奇怪文字，并向老师提出警告。2009年，威廉道斯小学再次迎来校庆日，被埋藏地下50年之久的时间囊重见天日。小男孩凯勒（Chandler Canterbury 饰）得到露辛达的信，上面没有任何图画，整页布满毫无规律可言的数字。凯勒的父亲约翰（尼古拉斯•凯奇 Nicolas Cage 饰）夜晚研究这些数字，竟发现这是一组具有预言性的密码。文中的数字清楚记录了世界上过去50年所发生的各种灾难。除此之外，这组数字还包括了接下来将发生的重大灾难……©豆瓣', '尼古拉斯·凯奇', '亚历克斯·普罗亚斯', 6.7, 124030, 'tt0448011', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2207854660.jpg', 1.6, 9.5, 48.3, 31.5, 9.2, '0.074929,0.076475,-0.409238,0.391210,0.484710,-0.101637,0.526433,-0.426186,-0.539415,-0.279175,0.028936,0.186355,-0.614981,0.346854,0.339962,-0.123595,-0.436785,-0.999957,-0.110656,-0.489059,-0.642394,-0.533859,0.099579,-0.232707,-0.041831,-0.351731,0.455264,0.133408,0.244082,0.278038,-0.145351,0.218610,0.107548,0.118117,0.055317,-0.108562,-0.190192,0.114342,-0.235921,0.168748,0.015688,-0.011910,-0.266290,-0.049462,0.108615,0.410831,0.781866,-0.499038,-0.299179,-0.085249,0.765620,-0.041309,-0.063854,0.115880,0.209926,0.510221,-0.149298,0.337035,-0.100760,0.013657,0.086762,-0.453178,-0.340038,-0.160250,-0.139581,0.271599,-0.156404,0.508815,-0.265497,0.160708,-0.113042,-0.633061,-0.018505,0.296029,0.548330,0.222797,-0.035008,0.137974,0.089432,0.098391,0.150960,-0.128582,-0.391225,0.215532,-0.295750,-0.363025,-0.042797,0.014663,0.029990,0.585822,0.123997,0.417063,0.129925,0.241655,-0.555166,-0.228109,-0.277408,-0.515216,0.411731,-0.137480,-0.529958,-0.606647,-0.171421,0.136001,-0.431911,-0.065910,0.169125,-0.256133,0.591133,-0.460903,0.419013,0.320521,0.257329,0.208558,0.543578,-0.340979,-0.246655,-0.295751,-0.026422,0.178708,0.131933,0.318845,-0.298614,0.137234,0.177010,-0.353506,-0.040832,0.404053', '1432699', '1307146', '26599076', '26877406');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2354897', '空之境界 第一章 俯瞰风景', '动画', '1998年9月，围绕巫条大厦发生了连续少女坠楼事件。媒体将其报道为无法解释的自杀事件，而有一个人，看出了事件背后的某种关联。她是魔术师苍崎橙子，伽蓝堂事务所的所长。解决都市不可思议事件的伽蓝堂只有三位成员：苍崎橙子、黑桐干也、两仪式。拥有“直死之眼”的两仪式受橙子所托，前往巫条大厦调查。等待她的是意想不到的敌人，而对抗敌人的武器，只有那把一直在式手中的匕首。而远在伽蓝堂，黑桐似乎被巫条大厦的魔力控制，失去了知觉。日本同人小说最高境界《空之境界》全七章动画化，本作为第一章电影版。©豆瓣', '坂本真绫', '青木荣', 8.7, 28521, 'tt1155650', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194396356.jpg', 0.3, 1.1, 11.3, 37.4, 49.8, '0.243864,0.168624,-0.507538,0.229063,0.195709,0.285584,0.482594,0.389676,-0.300179,-0.325903,0.459910,0.567090,-0.253945,0.158522,0.220681,-0.318711,0.129984,-0.669129,-0.133696,-0.197726,-0.401597,-0.318590,0.032212,-0.094969,-0.014442,-0.395631,0.760640,0.272281,-0.171376,0.047285,0.382571,0.622844,-0.178747,0.276547,0.026906,-0.091921,0.237341,-0.119288,-0.116618,0.326023,-0.208530,-0.355877,-0.019238,0.366414,0.016550,0.105655,0.760728,-0.050186,-0.255344,-0.316917,0.380830,-0.264382,-0.172076,-0.038502,0.580986,0.119380,-0.117556,0.460382,-0.122670,-0.166923,0.206923,-0.233564,-0.976913,-0.117234,0.318035,0.212211,-0.430095,0.310381,-0.085515,0.014370,0.145021,-0.086935,0.297618,0.280342,0.295131,0.247818,-0.061751,-0.176633,-0.595568,0.235217,0.471520,-0.250837,-0.297105,0.296301,0.127622,-0.461501,-0.637145,-0.306618,0.157487,0.246636,0.309670,0.074065,0.013065,0.343209,-0.423826,-0.342807,-0.078968,-0.356186,0.071327,-0.343336,-0.017025,-0.864624,-0.133287,-0.148202,-0.156431,0.058530,0.327882,-0.206678,0.670098,-0.774610,0.199558,0.588044,0.113522,-0.410433,0.731733,-0.109819,0.054826,-0.145704,-0.235009,0.199980,0.069154,0.458418,0.104778,0.305170,0.103070,0.073525,-0.295890,0.131519', '2369613', '26759820', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2354900', '空之境界 第二章 杀人考察（前）', '动画', '1995年9月，16岁的两仪式与黑桐干也相遇了。男孩子气的两仪式穿着和服来到学校，特殊的她与任何人都没有交集，除了黑桐干也。二人产生了某种关联，并开始了安稳的校园生活。同时，街上出现了连续猎奇杀人事件。由于警察朋友的关系，黑桐了解了一些内幕，他感到这个事件与式的双重人格有某种关系。两仪式与两仪织，猎奇杀人事件的真相到底是什么？两仪家的秘密在黑桐眼前逐渐展开。日本同人小说最高境界《空之境界》全七章动画化，本作为第二章电影版。©豆瓣', '坂本真绫', '野中卓也', 8.8, 22007, 'tt1155651', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192136839.jpg', 0.3, 0.9, 10.7, 37.3, 50.8, '0.471058,-0.201508,-0.645538,0.324046,0.263185,-0.005408,0.495653,0.005484,-0.318628,-0.607488,0.121087,0.643531,-0.565980,0.060357,0.248553,-0.506751,-0.115583,-0.783383,0.039879,-0.386954,-0.228070,-0.388206,-0.193497,-0.058426,-0.066938,-0.376811,0.680894,0.090951,-0.204544,0.426615,0.501758,0.323494,-0.361970,0.324626,0.050243,-0.023329,0.118088,0.233854,-0.275184,-0.137322,-0.155068,-0.005984,0.042828,0.081407,0.146259,0.497462,0.662153,-0.269437,-0.554841,-0.103580,0.446352,0.047612,-0.467732,0.103094,0.463557,0.141464,0.284211,0.680270,0.213588,0.009039,-0.172331,-0.172339,-0.423777,0.063844,0.180142,0.252831,-0.154333,0.277153,-0.072188,-0.418717,0.018235,-0.101586,0.281275,0.607540,0.529573,0.384060,-0.152293,-0.058565,-0.465426,0.037853,0.764301,0.018435,-0.240214,0.629975,-0.322111,-0.459961,-0.696706,-0.162132,0.286761,0.131921,0.138867,0.180830,-0.083736,0.451217,-0.696817,-0.298372,0.230488,-0.087060,0.208855,0.003735,0.165928,-0.702360,-0.157721,-0.539597,-0.546343,-0.080884,0.321249,-0.349085,0.585209,-0.926479,0.298576,0.572621,0.205516,-0.667428,0.692191,0.328746,0.197931,-0.255781,-0.320993,-0.046818,-0.414978,0.180140,-0.017827,0.510813,0.172844,-0.008170,-0.094553,0.298337', '1316589', '1293265', '1507140', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2354908', '空之境界 第三章 痛觉残留', '动画', '1998年7月，饮酒会归来的下雨之夜，黑桐干也收留了一位无家可归的少女。但不久，少女不辞而别，去向不明。与此同时，发生了连续杀人事件。死者无一例外，都是由于身体被强大的力量过渡扭曲而死。伽蓝堂开始为此展开调查。一步步深入的调查，犯罪者居然是当时不辞而别的少女浅上藤乃，而她的能力更是惊人的强大。两仪式，拥有“直死之眼”的少女，再次提起匕首迎战。日本同人小说最高境界《空之境界》全七章动画化，本作为第三章电影版。©豆瓣', '坂本真绫', '小船井充', 8.9, 21907, 'tt1155652', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1070325111.jpg', 0.2, 0.7, 8.8, 34.6, 55.6, '-0.074240,0.129563,-0.567660,0.221693,-0.000405,0.107253,0.338628,0.100332,-0.314109,-0.352285,0.335548,0.483677,-0.309464,0.096654,0.321521,-0.246017,0.334069,-0.508394,-0.062065,-0.136221,-0.339571,-0.048844,-0.156126,-0.004738,-0.034797,-0.607154,0.807743,0.308440,-0.300072,0.193467,0.203714,0.488923,-0.129298,0.277245,0.099322,-0.192193,0.006567,-0.127029,0.101605,0.291869,-0.156488,-0.486714,-0.003189,0.064705,-0.115889,0.325571,0.718349,-0.178392,-0.346185,-0.458718,0.777755,-0.251651,-0.390662,-0.013171,0.545903,0.185796,0.080520,0.432992,0.117862,-0.125250,-0.010404,-0.399485,-0.719241,0.180818,0.205616,-0.125290,-0.295772,-0.027752,-0.130299,0.132387,0.090482,-0.252869,0.080019,0.316249,0.246594,0.241382,-0.000947,-0.193662,-0.385971,0.305169,0.583216,-0.092438,-0.517527,0.257842,0.117698,-0.511730,-0.399454,-0.475598,0.088636,0.233468,0.110466,0.474351,-0.078804,0.473824,-0.344876,-0.179929,-0.424674,-0.081494,-0.091389,-0.017891,-0.288063,-0.595504,-0.196301,-0.176651,-0.089144,0.077443,0.215703,-0.370736,0.585353,-0.693917,0.361257,0.430836,0.244592,-0.584905,0.473759,-0.102373,-0.076144,0.074229,-0.207974,0.477744,-0.015678,0.185354,0.088568,0.082637,0.018481,0.095050,-0.229359,0.260489', '26759820', '2369613', '35151491', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2355418', '犬王', '战争', '取材于抗日战争时期中国军民协力以军犬为武器抗击日本侵略者的史实。地下党员关汉良为寻访良犬乔装来到武平山中村落。关与日军官八木皆发现二林的狗海龙是罕见的优秀狼犬。海龙为救主人不幸身亡，其幼犬大龙和小龙加入了关的军犬突击队。经过一年的强化训练，它们成为了军犬队的头犬。八木率军疯狂进攻游击队及附近的村庄，大龙赶回军犬训练基地后牺牲，小龙将八木引至海龙的墓前，以自己的方式报了仇。', '海顿', '姚守岗', 2.1, 62101, 'tt0347831', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2538911411.jpg', 97.3, 0.8, 0.8, 0.3, 0.7, '-0.086876,-0.301676,-0.260599,0.443550,0.281477,-0.086948,0.145905,-0.265388,-0.642268,0.031026,0.512092,0.357626,0.585753,-0.055208,0.132370,-0.373723,-0.159139,-0.532466,-0.137388,-0.046888,-0.191478,0.081203,-0.190422,-0.229343,0.172848,-0.430772,0.761696,0.024940,0.024293,0.736232,-0.118844,0.209812,-0.140930,-0.104743,-0.084601,0.102716,-0.005191,-0.411923,-0.206025,0.243392,-0.536288,0.053783,-0.234492,-0.039947,-0.032465,0.189126,0.871184,-0.414367,-0.126448,-0.666613,0.111031,-0.193251,-0.001366,0.145507,0.636771,0.076895,0.140506,0.219591,-0.058002,0.310094,-0.267564,0.015596,-0.651739,-0.091768,-0.119914,-0.103157,-0.610770,0.285935,0.007991,0.265089,0.612240,-0.411911,-0.114051,0.526723,0.036022,0.253771,-0.208910,0.317975,-0.397717,0.021255,0.584393,-0.584167,-0.013031,-0.535354,0.085819,-0.622508,0.336336,-0.193845,0.114635,-0.295631,0.317969,-0.197249,-0.138200,0.108450,-0.886608,-0.197416,-0.447051,-0.200228,0.160541,0.183357,-0.224938,-0.574520,0.277604,-0.333902,0.164898,0.215039,0.060121,-0.011404,0.580998,-0.801597,-0.042784,0.494954,0.193978,-0.342290,0.428827,-0.315884,0.186611,-0.107364,0.226818,0.066189,0.232100,0.808900,0.336858,0.108697,0.054609,-0.257595,-0.373587,0.156122', '26365262', '5364978', '1420088', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357162', '冰川时代3', '喜剧', '一群老朋友又将开始一段新的旅程。当猛犸象曼尼（Manny）沉浸在马上要当爸爸的喜悦之时，剑齿虎迭戈（Diego）却为自己的逐渐衰老而黯然伤神，此时树懒希德（Sid）则发现了三枚恐龙蛋，居然“母爱”泛滥，想做这三只小霸王龙的妈妈，结果被小恐龙真正的妈妈霸王龙掳走。为了寻 找同伴，一群可爱的动物朋友们走进了隐藏在冰河世纪之下的“侏罗纪公园”，在这片神奇的地方，他们会认识什么新朋友，又会遭遇到什么危险，这都让所有众多“冰粉”们充满期待。这部电影作为20世纪福克斯公司（20th Century Fox）第一部3D形式大规模上映的动画片其制作成本达到1.2亿美元，几乎是《冰河世纪1》的两倍。©豆瓣', 'Eunice Cho', '卡洛斯·沙尔丹哈', 8.3, 224964, 'tt1080016', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2213132432.jpg', 0.1, 0.8, 15.7, 51.1, 32.4, '0.054983,-0.058358,-0.659347,0.414214,-0.105315,-0.210117,0.846987,-0.130341,-0.285977,-0.196641,0.150305,0.868373,-0.408980,0.356505,-0.146850,-0.035891,-0.211283,-0.416665,-0.156829,-0.199410,-0.127342,0.143857,-0.622626,-0.001709,-0.018430,-0.095036,0.647702,-0.014139,-0.147259,0.347212,0.245805,0.208358,-0.139884,0.249708,-0.273664,0.095830,0.133172,-0.086647,-0.205178,0.180664,-0.007908,0.084812,-0.191967,0.085461,-0.222411,0.105775,0.797533,-0.185995,-0.216998,-0.096997,0.524519,-0.096613,0.157404,-0.059507,0.257128,-0.022165,0.286032,-0.179483,-0.013331,0.167357,0.019925,-0.150994,-0.891513,0.254939,-0.179897,0.215120,-0.441747,0.093265,0.234072,0.011728,0.482161,-0.423876,0.183556,0.339928,0.046121,0.707564,-0.243565,0.053303,-0.395800,0.215265,0.758083,-0.139574,-0.187727,0.586075,0.106186,-0.394128,0.161980,-0.110449,-0.455909,0.139817,0.454237,0.122562,-0.342665,0.339223,-0.896331,0.230070,-0.192295,-0.418309,0.021481,-0.215298,-0.183170,-0.542529,0.023136,-0.229641,0.001441,0.011981,0.194420,-0.223700,0.915102,-0.610369,0.306258,0.457488,0.186862,-0.424834,0.561649,-0.219817,-0.252542,-0.059061,0.101845,0.031862,-0.215961,0.397478,0.060007,0.239055,0.232914,-0.180872,-0.567587,0.713463', '4181031', '25928048', '24733428', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357302', '爱犬的奇迹', '剧情', '故事发生在宁静的小山村里，在青山绿水的映衬下，石川优（船越英一郎 饰）带着一双儿女亮太（广田亮平 饰）和彩（佐佐木麻绪 饰），以及父亲优造（宇津井健 饰）过着平静而安详的生活。一日，亮太和彩在路边捡到了一只年幼的狗仔，在爷爷的帮助下，他们说服了有些顽固的父亲，收养了狗仔取名玛丽，就这样，玛丽在石川家的新生活开始了。时间流水一样的过去了，玛丽已经成年并且有了三个孩子，当人们以为快乐幸福的生活将一直伴随着他们的时候，一场6.8级大地震的袭来粉碎了这一梦想，优造和彩被压在了沉重的房梁之下，而此时唯一能够帮得上忙的只有玛丽。在玛丽的帮助下，救援队很快便发现了爷孙二人，可是用来救援的直升机无法负担更多的重量，玛丽和孩子们被留在了灾区。©豆瓣', '船越英一郎', '猪股隆一', 8.7, 12202, 'tt1921012', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p638702029.jpg', 0.3, 0.9, 11.6, 35.8, 51.4, '0.109404,0.109036,-0.754798,0.427388,-0.158010,-0.215160,0.852406,0.251604,-0.423615,-0.006582,0.204055,0.690787,-0.239533,0.401917,0.159070,0.003631,-0.366472,-0.558833,-0.159699,-0.098866,-0.386002,-0.352697,-0.154719,-0.128575,-0.222196,-0.239673,0.377757,0.097621,0.149099,0.582920,0.122386,0.150801,0.037405,0.381473,-0.524444,0.180781,-0.145996,0.167889,0.038222,0.115420,0.030112,-0.252779,-0.178247,0.133382,0.045192,0.169393,0.754047,-0.521004,-0.286127,-0.102030,0.017241,-0.140885,-0.118257,0.240201,0.387746,0.001732,0.138697,0.078610,-0.385211,-0.007528,0.179910,-0.122686,-0.642597,0.208790,-0.010399,0.272348,-0.866562,0.521923,-0.063254,-0.312902,0.267640,-0.351017,0.221838,0.356554,-0.151540,0.416743,-0.475801,0.180395,-0.539515,0.268712,0.677818,-0.166337,-0.077674,0.469154,-0.344854,-0.261012,-0.203807,-0.083038,-0.432874,-0.207423,0.618143,0.021356,-0.432142,0.088051,-0.661165,0.062102,-0.143958,-0.425072,-0.126803,-0.442772,-0.274261,-0.351821,0.115577,-0.619730,-0.376784,0.352358,0.165355,-0.357913,0.859225,-0.805239,0.306106,0.394659,0.211346,-0.071078,0.480031,-0.100749,0.206002,0.188828,-0.084430,-0.032661,-0.093644,0.499477,0.575090,0.541487,-0.336163,0.016094,-0.491874,0.540924', '21619567', '21360412', '1292219', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357374', '工藤新一复活！与黑暗组织的对决', '剧情', '铃木财团最新的高级酒店落成，小兰（黑川智花 饰）、阿笠博士（田山凉成 饰）、柯南（藤崎直 饰；高山南 配音）、灰原哀（柴田幸花 饰；林原惠美 配音）受到园子（岩佐真悠子 饰）的邀请出席了隆重的开幕仪式。与此同时，“日本小姐”评选大赛庆功宴也在酒店同期召开，可就在此前不久，针对日本小姐获奖者寿可怜（奈都纪 饰）的威胁书送到了负责人的手中。当所有人都高度紧张的时刻，可怜突然失踪，当她再次出现在众人面前时，却已被杀害，以提线木偶般的恐怖形象登场。诡异的是，柯南和哀在吃了某个蛋糕后神奇地恢复成工藤新一（小栗旬 饰）和宫野志保（香椎由宇 饰）的本尊形象。他们一面要追查杀害可怜的真正凶手，一面要准备与躲在暗处的黑暗组织展开对决……©豆瓣', '小栗旬', '冈本浩一', 6.5, 18350, 'tt4854120', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2152493612.jpg', 2.7, 11.4, 51.9, 24.9, 9.1, '-0.024469,0.136325,-0.500258,0.235339,0.184205,-0.154099,0.544917,0.403320,-0.089673,-0.295474,0.507493,0.715358,-0.515706,0.152400,0.214406,0.052881,-0.301981,-0.679024,-0.327116,-0.193120,-0.081617,-0.162806,-0.216162,-0.096852,0.043424,-0.150606,0.396265,-0.015679,-0.325895,0.689509,0.614815,0.309194,-0.286797,0.317065,-0.077302,-0.186785,0.363215,0.068385,-0.109619,0.210032,-0.272582,-0.340847,-0.201600,0.207397,0.360568,0.236636,0.595779,-0.150768,-0.267733,-0.140112,0.354073,-0.174344,-0.018920,0.276241,0.556944,-0.106257,0.243195,0.099774,-0.288463,0.137798,0.149154,-0.188537,-0.783695,0.035243,0.253283,0.103485,-0.361767,0.379436,-0.243719,-0.067740,0.291751,-0.222283,0.338626,0.188159,0.137708,0.217176,0.045935,0.163224,-0.173078,0.280402,0.279413,-0.035261,-0.086529,0.178097,0.222204,-0.398174,-0.236948,-0.240391,-0.175428,0.056305,0.243418,-0.027078,0.160173,-0.047605,-0.582762,-0.356289,-0.108269,-0.172658,0.159908,-0.177172,-0.262114,-0.724969,0.149896,-0.238432,-0.354837,0.146290,-0.025477,0.011257,0.713515,-0.641714,0.323187,0.453303,0.128488,-0.199894,0.362615,0.138196,-0.077770,-0.061311,-0.145138,-0.291923,0.107064,0.405812,0.008205,0.321195,0.002155,-0.236626,-0.583534,0.197543', '3811356', '25928048', '25723905', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357397', '大胃王', '喜剧', '农民三好（潘长江 饰）只身闯城市，只为寻找当年负气离家的妻子芙蓉，无意中结识美女甜心（邓紫衣 饰），他与好友小帅（王宝强 饰）、甜心一同结伴寻找。当初，芙蓉因赌气来到城市，不料被八哥（郭德纲 饰）开车撞伤，八哥将她救起后又给她做了面部美容，后来成了广告代言人和八哥的新宠，并给她改名胡月（许慧欣 饰）。胡月因车祸伤了大脑，原先的记忆丧失，当三好找上门相认，她已不认识三好。三好为了给她筹治疗费，参加了大胃王比赛。甜心其实是八哥的女儿，为使家庭破镜重圆，她极力撮合三好与胡月相认，而八哥知道后，不惜采取下流手段干扰三好的比赛......©豆瓣', '潘长江', '罗惠德', 3.8, 6994, 'tt1825732', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321253184.jpg', 42.3, 31.9, 20.1, 3.3, 2.4, '0.073508,-0.070872,-0.310966,0.348369,-0.024543,-0.509954,0.313321,0.329771,-0.518905,-0.234005,0.081348,0.618117,-0.173709,0.088849,0.068947,0.225491,-0.109414,-0.711069,0.050488,0.123801,-0.005461,-0.352331,0.171467,0.023853,-0.096061,-0.084093,0.483027,-0.167539,-0.217232,0.489929,0.407364,0.106459,-0.057161,0.228408,0.003778,0.230889,-0.191507,0.216240,-0.247254,0.285607,0.064105,-0.326854,-0.082752,0.075248,-0.052784,0.440393,0.566262,-0.082668,0.135699,-0.453506,0.122905,-0.152180,0.083450,0.084639,0.099610,-0.048468,0.457658,0.044625,-0.398871,0.057954,0.284210,-0.074597,-0.249166,0.422668,0.261478,-0.163288,-0.589321,0.452279,-0.166193,-0.018641,0.390576,-0.123728,0.181349,0.479787,0.437250,-0.017132,-0.218511,0.018125,-0.307696,0.354759,0.577942,-0.087870,0.458121,0.478469,-0.157714,-0.271329,0.234763,-0.246974,-0.169468,0.145780,-0.012247,0.048783,-0.188706,0.050800,-0.446834,-0.220738,-0.245618,0.105996,0.067310,-0.285224,0.140633,-0.349773,-0.287970,-0.260664,-0.272168,-0.116444,0.076128,-0.200352,0.420186,-0.851701,0.178171,0.363635,0.441998,-0.882506,0.638905,0.147436,-0.010226,-0.246298,0.186137,0.056625,0.050849,0.172887,0.140845,0.039112,-0.035731,-0.137110,-0.404306,0.167886', '30345227', '1293265', '1299062', '1949320');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357699', '名侦探柯南：第十四个目标', '动画', '目暮警官、小兰的母亲妃英里、阿笠博士接连遭到不明身份之人的暗算。柯南追踪伤害阿笠博士的凶手，他根据几起案件现场留下的线索发现凶手按照扑克牌的顺序行凶，而且遇害者皆与毛利小五郎有关。目暮提供的线索初步揭开事情的真相，原来毛利当年任职警察的时候曾经逮捕犯下杀人罪的赌徒村上丈，当年也更因这一事件导致毛利离职以及婚姻变故。十年后，服刑期满的村上丈出狱，开始按照扑克牌的顺序向毛利身边之人展开报复。在得知原委后，毛利努力寻找身边与数字有关的人。在这一过程中，各种惊险场面接连出现。而柯南也对案件的真相产生疑惑……©豆瓣', '高山南', '儿玉兼嗣', 8.1, 91507, 'tt0965649', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1954017381.jpg', 0.1, 1.1, 20.4, 50, 28.3, '0.152505,-0.261629,-0.419382,0.371489,-0.040413,-0.160464,0.584983,-0.304150,-0.704464,-0.544864,0.436200,0.619552,-0.337605,0.206756,0.421986,-0.138064,-0.618279,-0.826923,-0.145408,-0.476113,-0.233207,-0.780079,-0.007931,-0.483377,0.150101,-0.262825,0.392787,0.087011,-0.125957,0.547280,0.198197,0.440561,-0.554388,0.259350,0.438448,0.275105,0.225473,-0.130940,-0.433129,0.036989,0.079405,-0.494703,0.096944,0.176775,-0.019743,0.626102,0.651611,-0.352419,-0.448950,-0.142373,0.531385,-0.239686,-0.033744,0.165373,0.825654,0.297781,0.281194,0.553919,-0.262539,-0.409246,0.016901,0.080664,-0.691652,-0.174936,0.084074,0.454147,0.166363,-0.228088,-0.341852,0.151092,0.375618,-0.291407,0.060713,0.547659,0.669890,0.054810,-0.546663,-0.240624,-0.187469,-0.005766,0.486565,-0.152812,0.216437,0.054498,-0.052871,-0.454967,-0.294515,-0.241236,0.091917,0.417252,0.240100,0.233992,-0.287279,0.365657,-0.195543,-0.381878,-0.006071,-0.125208,-0.049425,-0.065554,-0.366090,-0.557843,-0.036934,-0.174829,-0.548083,-0.066546,0.230664,-0.413192,0.390361,-0.484607,0.149001,0.422995,0.225627,-0.481708,0.206204,0.014309,-0.086260,-0.204287,-0.053477,-0.058285,0.344092,0.571933,-0.224055,-0.131563,0.135727,-0.537994,-0.289674,0.142059', '2357707', '3387546', '27110363', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357701', '名侦探柯南：瞳孔中的暗杀者', '剧情', '柯南在街头目睹一名正打电话的警察在雨中被射杀，忙将凶手追踪，但凶手逃脱。死者闭眼一刻紧抓左胸，似乎有所暗示。事后柯南从目暮警官口中了解到紧抓左胸是暗示那里有警察手册。不久又有警察手拿警察手册被人射杀于地下车库。对于这两起案件，目暮警官等人一反常态不愿向毛利小五郎及柯南透露太多信息。毛利不甘心进一步追问，白鸟警官只答一句“Need not to know”。该话是警察之间所用的密语，意味这两起杀人事件与警察内部人士有关。柯南、小兰等人参加白鸟妹妹的婚宴，电突然间停掉，那刻小兰正与女警佐藤在洗手间。小兰拿起身边的手电筒欲照明时，一颗子弹射进佐藤身体，小兰吓昏过去。次日小兰醒来，却因怪责自己害佐藤挨枪失去记忆。目暮见事态越来越严重，将秘密说出，原来死去的两名警察正与佐藤一起重查一桩有关医生仁野自杀的案件，该案涉及到警察局长的公子。将局长公子假定为嫌疑人之一时，柯南亦想到佐藤被射杀后宴会上少掉的两个人。', '茶风林', '儿玉兼嗣', 8.4, 104130, 'tt1068773', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453729514.jpg', 0.1, 0.7, 15.4, 47.7, 36.1, '0.511397,-0.129216,-0.246267,-0.092875,-0.085306,-0.106790,0.703021,-0.202547,-0.570271,-0.329550,0.381935,0.394467,-0.386838,0.119146,0.287359,0.033233,-0.483138,-0.675983,0.026174,-0.109300,-0.207410,-0.610195,0.033551,0.026192,-0.098466,-0.247504,0.319953,-0.015311,-0.158875,0.532081,-0.007055,0.383334,-0.418038,0.451597,0.207848,0.155798,0.185211,-0.274204,-0.210212,0.275149,0.258995,-0.485153,-0.081668,0.185707,-0.098117,0.259641,0.431597,-0.066715,-0.132070,-0.085990,0.172205,-0.371550,-0.076294,0.193967,0.610984,0.301821,0.058172,0.306890,-0.316426,-0.148569,0.231793,0.286471,-0.356727,0.159710,-0.062195,0.492650,-0.095465,-0.096128,-0.508004,0.109687,0.396900,-0.341640,0.241219,-0.004718,0.299115,0.047192,-0.289810,-0.107457,-0.330502,-0.151160,0.369626,-0.223378,0.343254,0.047889,0.147557,-0.409851,-0.010948,0.165204,-0.015783,0.081965,0.306746,-0.000162,-0.444702,-0.075947,-0.005457,-0.065254,-0.203426,-0.093267,-0.099866,-0.185734,-0.343920,-0.350835,0.141494,-0.003616,-0.273223,0.118781,0.252643,-0.116831,0.492441,-0.553249,0.006766,0.490938,0.257465,-0.033926,0.289339,-0.034553,-0.082960,-0.111869,0.022373,-0.267852,0.531326,0.567225,0.209683,0.220923,-0.222694,-0.144179,-0.137318,-0.300353', '3263169', '3387546', '1304665', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357703', '名侦探柯南：通向天国的倒计时', '动作', '柯南、灰原及少年侦探队成员步美、光彦、元太随博士这日露营完毕，绕道参观西多摩市新建于富士山前的日本第一双塔摩天大楼，毛利小五郎恰也应双塔所有者、他的学妹常盘美绪之邀，携小兰、园子参加开幕典礼。美绪介绍下，他们认识以画富士山闻名的画师如月峰水、市议员大木岩松、双塔的设计者风间英彦（森谷帝二的弟子，第一弹《引爆摩天楼》中，森谷曾向新一挑战）、天才程序员原。期间灰原的举动异常。大木提前入住B塔被害，目暮警官着手调查发现他与美绪似有不同寻常关系，不久原亦被杀害于家中。因为现场都留有与日本画画师作画时所用的乳钵相似的小酒杯碎片，两起案件似系一人所为。柯南由小酒杯联想到灰原曾效力的、以酒名为绰号的黑暗组织，并注意到第二起案件中碎片上未沾染血迹。与此同时他找到灰原举动异常的原因，却发现她正被人追踪。而园子玩笑弄的发式令她像极了雪莉（灰原）。开幕酒会上，美绪向宾客展示如月最为宝贵的富士山画作时被杀，死相正如横亘在富士山正中的双塔的缩影图，她的身下也有一个小酒杯，不过却是完好的。地上一颗原本该呆在美绪脖子上的珍珠令柯南将目光转向如月。紧接，A楼美绪公司电脑档案所在的楼层及地下配电室发生爆炸。逃亡时刻，柯南注意到正有一支枪瞄准园子，心中给出了所有疑问的答案，但他及小兰等人最迫切需要解决的却是如何从火海逃脱。', '高山南', '儿玉兼嗣', 8.6, 121066, 'tt1073223', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453730108.jpg', 0.1, 0.5, 11.2, 43.5, 44.8, '0.300861,-0.015799,-0.613436,0.198795,0.144624,-0.121755,0.568512,0.074703,-0.341837,-0.345889,0.403968,0.556684,-0.345197,0.267394,0.363745,-0.020691,-0.172517,-0.559549,-0.333850,-0.405852,-0.366884,-0.419722,-0.133928,0.115799,0.087692,-0.065127,0.506383,0.010305,-0.234628,0.423476,0.011026,0.202890,-0.348594,0.362102,0.111851,-0.114673,-0.059144,0.030683,-0.047953,0.108254,-0.215348,-0.385532,-0.255980,-0.005295,0.109938,0.318596,0.735484,-0.292139,-0.033201,-0.245425,0.103586,-0.083620,0.057162,0.019935,0.332827,0.085122,0.053362,0.143889,-0.144417,-0.061537,0.260816,-0.176009,-0.346983,0.109321,0.083515,0.262558,-0.264320,0.303812,-0.262722,-0.011295,0.151123,-0.316724,0.329931,0.073281,0.180280,0.147567,-0.221641,-0.052445,-0.348797,0.010295,0.234898,0.118718,0.004853,0.037332,0.060573,-0.389464,-0.152223,0.012549,0.134930,-0.012927,0.236574,0.150566,0.051680,-0.018743,-0.436307,-0.060668,-0.215518,-0.295208,0.160910,-0.166878,-0.232023,-0.759123,0.179300,-0.026570,-0.223530,-0.043003,0.104221,-0.144596,0.617493,-0.664787,-0.028207,0.409065,0.097243,0.078629,0.400910,-0.058197,-0.077101,-0.173475,-0.260902,0.066028,0.353179,0.516496,0.042592,0.288735,-0.283913,-0.339381,-0.597547,-0.003817', '3811356', '2369613', '26788667', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357707', '名侦探柯南：迷宫的十字路口', '动画', '东京、大阪、京都相继发生杀人事件，5名死者皆是被头戴面具的黑影人用武士刀和弓箭瞬间杀害。警方介入调查，发现死者都是出没于3地专门偷窃有名的佛像及美术品的偷盗集团“源氏萤”成员。该集团共有成员8名，以义经的家臣名字互相称呼，且都持有一本《义经记》，被害5人手中的《义经记》均被拿走。这日京都古寺山能寺收到奇怪书信，说若能解开信中所附的画谜，便能找到8年前被窃的如来佛像。柯南、小兰随毛利小五郎来到该寺，均对画谜一筹莫展。5名被杀者之一曾对与新一不相上下的大阪高中生服部平次照料有加，服部也来到京都对案件秘密展开调查，并借机找寻自己的初恋情人。柯南与服部相遇联手调查时，发现有人想置服部于死地，紧接“源氏萤”另一成员被害，而这一切，似乎又都与画谜有关。©豆瓣', '高山南', '儿玉兼嗣', 8.5, 112266, 'tt1133935', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p453732935.jpg', 0.1, 0.8, 14.8, 44.9, 39.5, '0.235995,-0.306323,-0.415452,0.318084,0.198586,-0.054778,0.245960,-0.119312,-0.494706,-0.618242,0.319194,0.853599,-0.134049,0.165040,0.318455,0.055945,-0.161781,-0.937824,-0.252816,-0.539641,-0.206968,-0.530549,-0.066416,-0.305540,0.000054,-0.069663,0.344724,0.148236,-0.076108,0.499661,0.315678,0.489192,-0.720046,0.269679,-0.113694,-0.005722,-0.087794,0.097457,-0.294551,0.004247,-0.343984,-0.426730,-0.122531,0.004424,0.058629,0.524858,0.486131,-0.272850,-0.133166,-0.140368,0.208421,-0.135639,-0.032623,0.121023,0.746237,0.218450,0.067768,0.557068,-0.302357,-0.180542,0.120747,0.086229,-0.680003,0.001889,0.482268,0.302499,-0.096912,0.068414,-0.235767,-0.078843,0.121844,-0.111486,0.263413,0.466499,0.348287,0.165030,0.019668,0.003043,-0.249770,0.102849,0.432684,-0.267129,0.285015,-0.177375,0.171213,-0.546911,-0.131283,-0.106593,0.234213,0.150369,0.154520,0.238636,0.059730,0.124406,-0.461775,-0.300881,-0.039655,0.003959,0.100894,-0.230396,-0.091185,-0.670114,0.066508,-0.137226,-0.274127,0.263827,0.463498,-0.039488,0.564912,-0.747620,0.064622,0.218013,0.373387,-0.481694,0.401670,0.114957,-0.150921,-0.220277,-0.367540,0.116196,0.768033,0.474372,0.012447,-0.020696,0.113904,-0.422784,-0.409650,-0.182340', '25723905', '3387546', '1308237', '1298104');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357708', '死神来了4', '惊悚', '尼克（鲍比•坎波 Bobby Campo 饰）携女友洛丽（珊特尔•范圣藤 Shantel VanSanten 饰）和朋友亨特（尼克•扎诺 Nick Zano 饰）及女友简妮（海莉•魏波）到赛车场观看赛车表演，尼克突然预见某辆赛车将发生事故冲向人群，部分看台坍塌，他与朋友全部丧生。惊慌失措的尼克强迫朋友随他离开赛场，并惊动了保安乔治（麦凯尔泰•威廉逊 Mykelti Williamson）及其他四位观众。逃过死神的尼克发现幸存者们纷纷在稀奇古怪的事故中丧命，而自己竟能预见死亡原因。恐惧中尼克和洛丽求助于乔治，试图打破怪圈对抗死神，然而努力真会见效，宿命真能改变吗？本片是《死神来了》系列的首部3D版本。©豆瓣', '鲍比·坎波', '大卫·R·艾里斯', 6.6, 120155, 'tt1144884', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p1137326910.jpg', 1.7, 11, 51.5, 25.8, 10.1, '0.245461,-0.144220,-0.520315,0.072460,0.154833,-0.188665,0.659121,-0.053541,-0.346684,-0.202778,0.207372,0.683794,-0.416058,-0.026722,0.494397,-0.283895,-0.463604,-0.748849,0.061281,-0.018459,-0.361217,-0.513671,-0.071598,-0.538746,-0.030923,-0.412789,0.437389,-0.097622,-0.040666,0.572776,0.286310,0.451948,-0.279220,0.411329,0.245947,0.270385,0.194753,-0.250554,-0.376593,0.159671,-0.155082,-0.028589,-0.289987,0.178360,0.124446,0.168733,0.533778,-0.418444,0.214881,0.017231,-0.023485,-0.283895,0.181469,0.045144,0.167808,-0.045810,-0.162631,0.225424,0.025332,0.020867,0.082934,0.225509,-0.403804,0.190044,-0.329770,0.326311,-0.361882,-0.017481,-0.008458,0.061928,0.277623,-0.097255,0.110736,-0.119018,0.230892,-0.039271,-0.249494,-0.186851,-0.435404,0.106121,0.604321,-0.133075,-0.160312,0.070419,-0.185784,-0.385809,-0.209560,-0.027788,-0.534162,0.148036,0.469883,-0.004924,0.009528,0.378779,-0.287884,-0.358180,-0.460940,-0.186084,-0.468464,-0.211259,0.001530,-0.863294,0.119692,0.071089,-0.114258,-0.141282,-0.299132,-0.217149,0.388479,-0.595673,0.224558,0.521734,0.252829,-0.137072,0.498338,-0.133964,0.200385,-0.011638,-0.384927,0.576733,0.093267,0.102140,-0.021173,0.198924,0.198883,0.000682,-0.125798,0.354823', '11541282', '3147969', '10466639', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357711', '名侦探柯南：银翼的魔术师', '动画', '知名舞台剧女演员牧树里这日收到怪盗基德的预告信：在26个字母的盘旋飞舞中，他来拜领无价的“命运的宝石”。毛利小五郎受到牧树里委托将信件分析，认为基德将在演出最后一晚前来盗取宝石，当晚他及柯南、小兰等人来到剧场，那里早有诸多警察守候。令柯南吃惊的是，基德竟扮成工藤新一出现在众人面前，但他及众人方向不同的紧张过后，宝石并没被盗，柯南醒悟字母预告信与航班相关。而柯南、小兰、牧树里及其同事搭乘的前往北海道的飞机上，尚有一起杀人计划正被精心设计。©豆瓣', '高山南', '山本泰一郎', 8.1, 96511, 'tt1133559', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1954029893.jpg', 0.2, 1.6, 20.9, 48.8, 28.4, '0.491806,0.008698,-0.792861,0.220056,0.282250,-0.008839,0.362864,-0.009538,-0.429318,-0.292752,0.343244,0.743487,-0.652427,0.046182,0.291299,-0.014052,-0.537220,-0.522372,-0.246505,-0.384509,-0.133666,-0.555123,-0.006241,0.064135,-0.100825,-0.102142,0.313762,0.015808,0.126289,0.962129,0.281769,0.070049,-0.410989,0.330386,0.038034,0.220754,0.072982,-0.202632,-0.092912,0.187130,0.096745,-0.191969,0.007328,0.023763,0.101385,0.221536,0.644526,-0.251413,0.009329,0.231853,0.195735,-0.281576,0.067289,0.239195,0.417330,0.293155,-0.146207,-0.055597,-0.428000,0.157057,0.187909,-0.025967,-0.490388,0.131056,0.008311,0.475126,-0.264751,0.110081,-0.284920,0.037900,0.151760,-0.359894,0.267240,0.161976,0.268984,0.042656,0.144712,-0.122255,-0.178422,0.110934,0.077743,-0.014019,0.135991,0.152189,-0.181443,-0.419720,-0.137370,0.104665,-0.103772,0.147320,0.424078,0.048266,-0.108927,-0.336275,-0.443272,-0.212021,-0.124433,-0.361879,-0.010674,-0.229553,-0.479737,-0.975215,0.291381,-0.075810,-0.268499,0.200112,0.211945,-0.115651,0.549725,-0.761832,0.179000,0.485516,0.123208,-0.224050,0.483308,-0.117879,-0.107703,0.095664,-0.110246,-0.049839,0.371472,0.453544,0.017923,0.000818,-0.042656,-0.080725,-0.493019,-0.052467', '2075345', '26788667', '26365262', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357713', '名侦探柯南：水平线上的阴谋', '动画', '日本著名造船公司八代商船设计制造了旗下第一艘豪华邮轮爱芙罗黛谛号，为庆祝该邮轮的处女航，八代商船邀请各界名流参加，上到首相下到富豪悉数前来。铃木园子的父母也接到邀请，因行程安排铃木夫妇无法出席，园子于是邀请、毛利小五郎、小兰、柯南等一众好友同行。蓝天白云，美酒佳肴，众人无不陶醉于这美好的假期之中。但是，这注定是一次不寻常的航行。先是园子突然遭人绑架，接着八代商船的女社长贵江被人杀害，与此同时董事长八代延太郎也从船上神秘失踪。此前不久，贵江的丈夫八代英人驾车时突发心脏病冲下山崖。这一连串死亡、失踪案件似乎都与15年前八代商船的沉船事故有关。在层层推理调查之下，隐藏的秘密渐渐浮出水面……©豆瓣', '高山南', '山本泰一郎', 7.8, 86392, 'tt1133936', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1954012128.jpg', 0.3, 2.3, 28.8, 46.8, 21.8, '0.080685,-0.065441,-0.695542,0.314495,0.234596,-0.027025,0.392583,0.121854,-0.684902,-0.267794,0.437209,0.705390,-0.153045,0.309943,0.491104,0.085999,-0.512399,-0.427003,-0.215832,-0.156776,-0.257871,-0.249152,0.124144,-0.251292,0.172337,-0.134992,0.351060,0.352555,0.117755,0.745817,0.143301,0.511116,-0.419502,0.422016,-0.166556,0.281214,0.427774,0.052046,-0.098471,0.036351,-0.634611,-0.290460,-0.023076,-0.095110,0.205930,0.471885,0.476734,-0.019894,-0.189670,-0.209805,0.146617,-0.140963,0.156732,0.051635,0.757319,0.212245,0.121903,0.569269,-0.299201,-0.220294,0.021828,0.377826,-0.506151,0.076659,0.092556,-0.001440,-0.268560,-0.034838,-0.177411,-0.191374,-0.068119,-0.109137,0.362052,0.509187,0.201067,-0.082726,-0.051079,0.492231,-0.302048,0.388824,0.789693,0.032471,0.177040,0.033613,0.048903,-0.140632,-0.039058,-0.306808,-0.096614,0.045157,0.212830,0.092157,0.028508,0.312192,-0.267781,-0.175985,-0.199971,-0.453400,0.128423,-0.114695,-0.425816,-0.949965,0.172984,-0.008675,-0.076947,0.101614,0.353090,0.131373,0.483120,-0.286023,0.081812,0.492925,0.061325,-0.216071,0.597860,-0.066542,-0.102543,-0.161723,0.008672,-0.308612,0.194067,0.418759,-0.252954,0.206047,0.056145,-0.214087,-0.328495,-0.130105', '3147969', '3871833', '35287558', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357717', '名侦探柯南：绀碧之棺', '剧情', '柯南和小五郎等拉着大队，来到位于太平洋中的美丽小岛“神海岛”渡假。这座岛屿自古已有流传，大概有关沉没于海底的古代遗迹“海底宫殿”，及300年前两名女海盗遗留下来的宝藏传说。小兰和园子不惧流传，在“海底宫殿”附近潜水时，意外遇到一大群正在寻找宝物的猎人，不料其中一人突然遭鲨鱼攻击，不幸身亡！小兰和园子幸运逃难，柯南见那位猎人死状诡异，与灰原一起展开调查。柯南认为猎人之死，跟宝藏传说有着莫大关系，他试图解开背后原因，“海底宫殿”的谜题一直系绕在他的脑海中。他找到了一组神秘名词“Jolly Roger(海盗旗)”后，满以为有所起色，猎人却突然现身，并偷走了原来发现的宝藏！小兰和园子落在猎人的魔掌之中，性命危在旦夕！隐藏于传说中的讯息是什么？“海底宫殿”有什么秘密？穿越300年时光的暗号，柯南誓要逐步解开迷题©豆瓣', '高山南', '山本泰一郎', 6.8, 73998, 'tt1146290', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2528437799.jpg', 1.6, 9.8, 47.5, 28.1, 13, '0.153858,-0.048193,-0.805576,0.398099,0.288619,0.237292,0.704576,-0.327861,-0.715723,-0.468337,0.151272,0.657930,-0.166289,0.075564,-0.022542,0.202096,-0.458324,-0.336499,-0.123300,-0.396302,-0.471674,-0.255418,-0.568658,-0.015816,0.036926,-0.401366,0.650351,0.421124,-0.290489,0.365717,0.000630,0.462377,-0.910048,0.260650,-0.538428,-0.109978,0.245340,0.289321,-0.165067,0.191652,-0.511885,-0.121513,-0.225382,-0.037562,-0.060911,0.118255,0.527056,-0.251837,-0.194159,0.178141,-0.008138,-0.110776,-0.065086,-0.335987,0.677326,-0.301080,0.167455,0.336556,0.052232,-0.207411,0.137376,-0.263283,-0.370635,-0.153431,0.239563,0.357287,-0.101996,-0.148565,0.121500,-0.085013,0.115344,-0.369231,0.397476,0.146432,0.422552,0.073320,-0.132589,0.011014,-0.605157,-0.013933,0.287119,-0.327872,0.037304,0.267612,0.228146,-0.469657,-0.196220,0.151071,0.027317,0.159604,0.379483,0.227763,-0.456166,0.167092,-0.756283,0.122271,-0.249149,-0.140988,-0.021945,-0.241877,-0.563849,-0.503452,-0.164537,-0.062923,-0.113031,0.144799,-0.057295,0.123234,0.481327,-0.483729,0.605844,0.575768,0.158485,-0.231630,0.762778,-0.226402,0.023435,-0.335879,0.117446,0.220766,0.240785,0.316155,-0.193002,0.027576,-0.243362,-0.192098,-0.680798,0.101617', '1458901', '24827406', '1309056', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2357719', '名侦探柯南：战栗的乐谱', '动画', '堂本一辉是著名的钢琴演奏家，两年前突然宣布不再演奏钢琴转而攻向管风琴，更斥资建造了堂本音乐厅，准备在落成之日举行演奏会。然而在演奏会之前，堂本音乐学院的学生相继死去，先是爆炸案，后是单个被杀。园子带着柯南一行人来听排练，认识了女高音歌唱家秋庭怜子，拥有绝对音感的秋庭也开始遭遇到危险：润生茶被下药、作森林浴时遭遇空气枪袭击、试演会当天更遭击晕。然而就是从这些事件中，柯南找到了推理的逻辑：凶手试图把秋庭排除在凶杀外。这边已经正式开演的演奏会浑然不知音乐大厅外已是爆炸连天，小兰、灰原哀以及演奏厅内的一千多人顿时危在旦夕，绝对音感成为了唯一的救命线索。柯南找到了爆炸的逻辑，要在罪犯引爆最后一个炸弹前，把他找出来。©豆瓣', '高山南', '山本泰一郎', 7.3, 89696, 'tt1155696', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p453739518.jpg', 0.7, 5.6, 40.7, 36.3, 16.7, '0.142398,-0.000918,-0.578880,0.189397,0.151507,-0.048972,0.636538,0.042665,-0.301025,-0.266719,0.154926,0.554726,-0.341029,0.222651,0.274122,-0.194279,-0.167586,-0.715311,-0.242036,-0.328177,-0.328173,-0.437651,0.248904,-0.009037,0.066239,-0.315470,0.153179,0.062250,-0.405137,0.490091,0.312045,0.236877,-0.140666,0.421121,-0.145119,-0.020852,0.241368,-0.071772,-0.103256,0.491504,-0.055108,-0.461719,-0.051824,0.062271,-0.178244,0.209800,0.491616,-0.103830,0.029870,-0.132253,0.447735,-0.188639,-0.104875,0.173652,0.524878,0.132727,0.171076,0.204953,-0.268739,0.200895,0.073278,-0.098004,-0.536274,0.233167,-0.008069,0.157451,-0.414389,0.241675,-0.005581,-0.143603,0.229404,-0.091620,0.541358,0.106133,0.291343,0.317915,-0.295236,-0.034626,-0.587815,-0.051104,0.629566,-0.270825,0.003071,0.385501,0.344656,-0.502339,-0.116754,-0.061836,0.051345,0.273823,0.318464,0.087923,-0.068296,-0.187943,-0.411986,-0.201795,-0.083706,-0.423807,0.012074,-0.291874,-0.219601,-0.902480,0.160127,0.241591,-0.123246,0.166562,0.043802,-0.200284,0.585589,-0.624360,0.264552,0.426906,0.123582,-0.125775,0.243212,-0.100654,-0.004658,0.209428,0.271773,-0.099600,0.133268,0.702056,0.138856,0.458480,0.018595,-0.447580,-0.584062,0.271691', '25723905', '6984051', '26788667', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2359431', '保持通话', '剧情', '改编自好莱坞电影《驳命来电》(Cellular)。这天和平日一样，身为工程师的单身妈妈Grace（徐熙媛 饰）拼命工作几乎通宵，次日送女儿婷婷上学。途中被霍德能（刘烨 饰）故意猛撞车身，Grace当场昏迷，醒来后发现已置身于一个密闭的货柜内。昏迷时她看见霍德能对她家大肆搜索并且杀害女佣，醒来后更被追问东西藏在何处。一无所知的Grace毫无办法，在悍匪离开后竭力地把一台损毁的电话接线，拨出给财务公司的阿邦（古天乐 饰）。阿邦面对Grace的苦苦哀求，随手把手机给交警辉Sir（张家辉 饰），由于听不清Grace的说话，辉警告阿邦别再胡闹。阿邦听到手机内枪声后意识到事态严重，决定帮助Grace。眼下第一件事就是拦截悍匪，他们正在前往学校企图带走婷婷以作威胁。悍匪第二个目标是找到Grace弟弟，他们相信他们的犯罪证据就在她弟弟手上。一路上阿邦被误认为劫匪，被警察追逐，陷入困局的他惊讶地发现霍德能一行人竟然是国际刑警，他只有凭着保持通话独力营救，辉Sir的出现也让事情有了一丝转机。', '古天乐', '陈木胜', 6.8, 155547, 'tt1156506', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p505145746.jpg', 1.3, 7.8, 50, 33.3, 7.5, '0.269365,0.100199,-0.688421,0.175308,0.073255,-0.131238,0.510889,0.002201,-0.528147,-0.525504,0.055788,0.459581,-0.185652,0.023359,0.135992,-0.210801,-0.388592,-0.783427,-0.153736,0.054525,-0.416781,-0.366967,0.219323,0.021764,0.137581,-0.201892,0.237622,0.025964,-0.241844,0.482393,0.143962,0.251650,-0.199648,0.670308,0.001166,0.099144,0.022875,-0.222629,-0.132451,0.332363,0.189020,-0.324926,0.044744,0.219126,0.022686,0.339172,0.646817,0.061945,-0.214701,0.172865,0.053664,-0.307935,-0.210142,0.045068,0.427709,0.170507,0.176644,0.026932,-0.450905,0.092362,0.127402,0.173192,-0.472034,0.144561,-0.142491,0.108265,-0.489133,0.030165,-0.278142,0.230715,0.207738,-0.340784,0.464922,0.246435,0.033037,0.349300,-0.139058,0.086175,-0.636128,-0.138238,0.334175,-0.259320,0.321779,0.295781,0.257095,-0.214252,0.186656,-0.015751,-0.327171,0.110711,0.328010,0.180280,-0.402646,-0.297548,-0.249622,-0.143452,-0.375506,-0.235154,-0.036925,-0.512753,-0.408608,-0.450391,0.039398,0.144612,-0.193745,0.302855,-0.053856,-0.062078,0.289385,-0.618307,0.072151,0.394843,0.383450,-0.334696,0.524529,-0.066239,0.032867,-0.240260,0.055881,0.012847,0.427243,0.440060,0.133134,-0.096128,-0.138493,-0.305417,-0.403697,-0.107887', '1305224', '25870679', '6722888', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2359442', '蝴蝶飞', '剧情', '自从大学时男友林旭东（周渝民 饰）交通意外死亡后，傅恩佳（李冰冰 饰）三年来一直未能忘情，每晚靠吃药丸来让自己入眠。而自从停吃药丸，恩佳就开始看见旭东，旭东在每一个夜晚前来，追问交通意外当天的问题：你到底是不是真的喜欢我？恩佳的生活从此被打乱，然而这也使她开始回望反思自己的生活，了解旭东的童年、父亲，还有他们爱情开始时最美妙情深的时刻。只有勇敢面对过去，才能真正地把握现在。©豆瓣', '李冰冰', '杜琪峰', 5.5, 14427, 'tt1156136', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p967695026.jpg', 7.3, 28, 49.3, 12.1, 3.3, '-0.077160,0.180586,-0.668932,0.181797,0.015571,-0.315806,0.401524,0.039487,-0.550894,-0.217181,0.106905,0.516453,0.028136,0.020691,0.275952,0.086417,-0.399699,-0.684311,0.482109,-0.045180,-0.234760,-0.224777,0.015268,-0.121839,0.107808,-0.071169,0.448820,0.046403,0.122062,0.529486,-0.012075,0.191058,0.244502,0.606315,-0.074156,-0.119770,0.054138,0.298143,-0.524315,0.089838,0.255188,-0.245183,-0.345797,0.252843,0.207083,0.020212,0.411834,-0.028098,-0.590892,-0.015262,0.211222,-0.098008,-0.276164,0.054768,0.019067,-0.052131,0.532501,0.216155,-0.135227,0.240167,-0.198631,0.212662,-0.485089,-0.030508,-0.109398,-0.021771,-0.328295,0.277148,0.133167,-0.186712,0.274725,-0.481655,0.322634,0.656056,0.436415,0.362156,-0.409883,0.010669,-0.166637,0.064915,0.750306,-0.174528,-0.026028,0.707410,0.183306,-0.229949,0.054962,0.047122,-0.225274,0.346703,-0.288821,0.439844,-0.369654,0.122635,-0.373146,0.249179,-0.120573,-0.205238,0.287636,-0.334524,-0.523715,-0.180353,0.009300,-0.291995,-0.455393,-0.047774,-0.122881,-0.354881,0.460468,-0.785029,0.231501,0.375050,0.222576,-0.493549,0.542855,0.495472,-0.195754,-0.429546,-0.086764,0.505769,-0.424751,0.410218,-0.173317,0.082187,0.118335,0.150910,-0.401061,0.302937', '2052978', '30345227', '27191829', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2359450', '夺帅', '动作', '“忠信义”帮主连浩龙（洪金宝 饰）老来得子，风光地办了满月酒招待帮众。虽然孩子是他新纳小妾（张文慈 饰）生的，但是连浩龙老婆Soso（恬妞 饰）的出场还是颇具阿嫂风范。不过，因为酒席人数众多，引起骚乱。在警匪对峙之时，反黑组高级督察廖志宗（李修贤 饰）出面化解，避免了一场血战。弟弟连浩东（任达华 饰）嗜赌成性，因此连浩龙特意做局劝他收手，共叙兄弟情义。在一次三亿元毒品交易却被警察捣破后，又发生了四叔(许绍雄饰)被绑架事件。警方的反黑行动令连浩龙的爪牙纷纷落马，仅剩下心狠手辣功夫了得的骆天虹（吴京 饰）死里逃生。女警员雷美珍（邵美琪 饰）通过诱敌深入，获得了关键情报，警方拉开了天罗地网。与此同时，连浩龙也赫然发现一起出生入死的同党中害他的奸细，这个人也最终导致了“忠信义”与连浩龙的覆灭……©豆瓣', '洪金宝', '罗守耀', 6.5, 26154, 'tt1156444', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p647260568.jpg', 2.6, 13.2, 51, 24.6, 8.7, '-0.021345,-0.096828,-0.488863,0.165638,0.016045,-0.109065,0.407364,0.308603,-0.389181,-0.262342,0.571359,0.300943,-0.199486,-0.148870,0.215541,-0.412119,0.059278,-0.548041,0.001722,0.009154,-0.076155,-0.186659,-0.196498,-0.088205,-0.017877,-0.043742,0.296745,0.127840,-0.119483,0.530099,0.446965,0.063283,-0.088244,0.214092,0.112336,0.195016,0.050598,-0.102283,-0.398453,-0.066101,-0.129323,-0.381203,-0.201237,0.128761,0.191865,0.561805,0.463413,-0.182644,-0.085373,-0.141888,0.180590,-0.294214,0.063420,0.047894,0.246869,0.006989,0.266284,0.372703,-0.136486,0.007776,0.098384,0.143622,-0.467534,0.228975,0.065651,0.051910,-0.498861,0.512315,-0.180286,0.021156,-0.341908,-0.033222,0.243911,0.277943,0.187582,-0.026833,-0.044021,-0.112006,-0.488487,0.085023,0.626863,-0.135656,0.250720,0.055189,0.139858,-0.453304,-0.064731,-0.464474,0.034144,0.104228,0.623185,-0.267878,0.007656,0.200615,-0.522615,-0.270884,-0.270570,0.235645,-0.083848,-0.146205,0.144284,-0.503265,-0.213477,-0.323818,-0.325313,0.257674,0.091803,-0.156347,0.602911,-0.475253,-0.185170,0.410423,0.280216,-0.827672,0.301122,0.336783,0.157262,-0.124622,-0.070385,-0.183416,0.259595,0.151408,0.417310,0.147363,-0.217013,-0.553700,-0.116444,-0.132605', '3998385', '1300857', '1302110', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2359497', '20世纪少年', '科幻', '20世纪末，一种神秘病毒在世界蔓延，感染者莫不血尽身亡。热爱摇滚乐的远藤贤知（唐泽寿明 饰）经历过叛逆时期，如今年奔三十的他窝在家乡大阪经营一家连锁超市，上层负责人责骂，母亲聒噪，姐姐的孩子神乃哭泣，贤知小心应付，手忙脚乱。在小学同学聚会上，贤知重逢当年好友义常（香川照之 饰）、青蛙仔（宮迫博之 饰）、丸夫（石塚英彦 饰）、福平（佐佐木藏之介）、阿门（宇梶剛士 饰）等人。从他们口中得知，如今社会上正时兴一个神秘的宗教组织，组织领袖自称“朋友”，而近期发生的一些列恐怖事件皆来自贤知众人童年时杜撰的一本“预言之书”。不久，童年时的好友当机（生濑胜久 饰）自杀身亡，他在死前几天曾寄给贤知一封信，信中提到秘密基地的标志。为弄清真相，贤知和朋友们挖出当年埋在树下的铁盒，找出那本“预言之书”。他们发现，儿时胡编乱造写下的情节正在一一应验。那位“朋友”似乎就是当年这群孩子中的一员，而他的目的究竟是什么呢？（影片简介中涉及的人名均以原著漫画中文版翻译为准）', '唐沢寿明', '堤幸彦', 6.9, 7802, 'tt1155705', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1081197256.jpg', 2.7, 9.8, 42.2, 31.8, 13.5, '0.140356,-0.189140,-0.381425,0.436073,0.106261,0.142281,0.482564,0.017238,-0.570333,-0.594642,0.210427,0.626898,-0.200083,0.430119,0.233938,-0.115640,-0.150606,-0.575043,0.053425,-0.397260,-0.145266,-0.422441,-0.305415,-0.134268,-0.111957,-0.254036,0.465457,0.093773,-0.168236,0.175609,0.073679,0.455625,-0.576075,-0.099450,-0.035386,-0.068428,0.088981,0.307611,-0.256130,-0.273397,-0.287759,-0.287655,-0.104655,0.003250,-0.067897,0.200419,0.598707,-0.246057,-0.169370,-0.289619,0.461907,0.007034,-0.228820,-0.021145,0.424537,0.147670,0.255340,0.358795,0.097297,-0.099085,-0.186109,0.012412,-0.396863,-0.286931,0.178395,0.288175,-0.237908,0.321354,-0.189612,0.254692,0.066820,-0.303009,0.296865,0.250532,0.262700,0.295541,-0.014799,0.110528,-0.182674,0.368314,0.391781,-0.257923,0.106380,0.288749,0.107298,-0.266738,0.040588,0.079468,-0.429173,0.277788,-0.058981,-0.029364,-0.273843,0.256948,-0.465231,-0.225707,0.010255,-0.063282,0.414645,-0.026242,-0.305537,-0.478558,-0.161418,-0.184369,-0.034023,-0.024128,0.206841,-0.130149,0.866401,-0.438197,0.278846,0.363575,-0.115347,-0.391345,0.309223,-0.018581,-0.060578,-0.302467,-0.063847,0.355093,0.341735,0.089274,-0.314410,-0.027733,-0.004951,-0.252308,-0.437126,0.140253', '3811356', '27602116', '25863940', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361266', '爱的曝光', '剧情', '高中生角田优（西岛隆宏 饰）自幼丧母，多年来他和身为神父的父亲角田哲（渡部笃郎饰）相互依靠，过着平淡的生活。但熏（渡边真起子 饰）到来打破了一切，她来去匆匆，敢爱敢恨，令角田哲癫狂不已，更将怨气全部撒在优的身上，强迫儿子每天忏悔认罪。为了讨好父亲，善良的优甚至主动去犯错，不久更加入了偷拍女性底裤的小组。父亲为他的大发雷霆，优却因此感到高兴。不久，优邂逅了如玛丽亚般美丽的女孩洋子（满岛光 饰），而讨厌庸俗男性的洋子也阴差阳错喜欢上了男扮女装的优。优继而得知，洋子是熏的养女，熏如今又回到哲的身边，四个人组成一个奇怪的家庭。优纠结于对洋子的迷恋中，却不知，一个名为“零教会”的宗教团体已经盯上了角田家……©豆瓣', '西岛隆弘', '园子温', 8.3, 33381, 'tt1128075', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p575424244.jpg', 1.2, 3.1, 16, 36.5, 43.2, '0.100674,0.099604,-0.473857,0.671896,-0.348550,-0.339453,0.647916,0.027928,-0.280570,-0.363409,0.131067,0.817004,-0.070116,0.437517,0.292008,0.201807,0.045252,-0.735192,-0.373967,-0.155703,-0.266419,-0.468741,0.019801,-0.054606,-0.243007,-0.431665,0.567292,-0.049150,-0.029774,0.498784,0.499544,0.498945,-0.145485,0.302785,-0.047610,0.099485,-0.106857,0.051562,0.031039,-0.059632,-0.163249,-0.218936,-0.189268,0.364395,0.029494,0.398543,0.775744,-0.261672,-0.256127,-0.409401,0.408402,-0.234753,-0.196443,0.123878,0.354873,-0.059190,0.212223,0.190934,-0.220080,-0.010356,0.110269,0.124907,-0.574210,-0.182067,0.224133,0.022326,-0.470847,0.449214,-0.009068,-0.121324,0.140444,-0.103555,0.177430,0.092061,0.009144,0.445775,-0.156650,0.184975,-0.254728,0.146617,0.700134,0.123228,-0.045700,0.309353,-0.495481,-0.122555,0.243412,-0.376893,-0.573778,-0.071568,-0.008575,0.060717,-0.091277,0.135398,-0.470927,-0.224475,-0.233459,0.119425,0.178043,-0.483882,-0.090101,-0.179288,0.039077,-0.469633,-0.291984,0.143553,-0.109717,-0.593394,0.682415,-0.831529,0.157372,0.672851,0.190732,-0.492557,0.390077,0.064711,0.011434,0.109376,-0.187190,0.222984,0.126598,-0.154906,0.194240,0.453695,-0.273253,-0.108726,-0.390656,0.252240', '1292219', '30345227', '4817024', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361269', '我们与驻在先生的700日战争', '喜剧', '1979年，平静的枥木乡间生活着一群不甘寂寞的少年。鬼点子超多的真间查理（市原隼人 饰）、好色的不良少年西条（石田卓也 饰）、偏差值为0的孝昭（加治将树  饰）、迷恋天文的井上（贺来贤人 饰）、超级大胃王千叶（肋之弘 饰）、颇有女性风采的后辈吉米（富浦智嗣 饰）和留级大王迁村（小柳友 饰），这七个活宝组成的恶作剧小分队让这个平静得有些沉闷的小镇多了一丝生气。不过他们的好日子很快就结束了，枥木迎来了新的驻警（佐佐木藏之介 饰），古板的警察先生和喧闹自在的少年们似乎注定不能相容，他们之间展开了旷日持久的大作战……©豆瓣', '市原隼人', '塚本连平', 8.2, 10096, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p476603837.jpg', 0.4, 2.1, 18.1, 46.9, 32.5, '0.304795,0.038014,-0.432908,0.471566,-0.150044,-0.180171,0.629161,0.189806,-0.371450,-0.114387,0.105424,0.434019,-0.337553,0.214495,0.174997,-0.103903,-0.138039,-0.423156,-0.160357,-0.153922,-0.169825,-0.214249,-0.322859,-0.213041,-0.074645,-0.141809,0.472833,0.255890,0.034498,0.639092,0.370312,0.148515,0.073795,0.203628,-0.219094,0.053403,-0.066274,0.138314,0.175055,-0.148452,-0.359666,-0.029969,-0.219701,-0.019949,0.090350,0.406266,0.704411,-0.376496,-0.224567,-0.063308,0.275426,-0.067632,-0.117071,0.185256,0.302875,0.041319,-0.145505,0.094379,-0.202334,-0.136838,0.080239,-0.016178,-0.472334,0.324281,0.016168,0.331016,-0.364510,0.715992,-0.012368,-0.426082,0.131719,-0.035370,0.053355,0.323966,0.340994,0.183555,-0.043407,0.120136,-0.323594,0.083796,0.463853,0.247222,-0.412061,0.067255,-0.306480,-0.533595,-0.258366,-0.269668,-0.312365,-0.187957,0.372913,-0.311582,0.063624,0.229109,-0.790317,0.119626,0.029640,0.035718,-0.147830,-0.248532,-0.147847,-0.554704,0.135463,-0.763379,-0.339208,0.309096,0.236952,-0.053548,0.968106,-0.741618,0.015458,0.327778,0.129635,-0.185587,0.411777,0.021164,-0.267216,-0.191165,-0.270086,-0.056127,-0.128468,0.265820,0.394649,0.769940,-0.286942,-0.293563,-0.154101,0.406655', '1826173', '3811356', '25922902', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361386', '堕入地狱', '恐怖', '供职于某银行信贷机构的美丽女孩克莉丝蒂安（艾莉森•洛曼 Alison Lohman 饰）经过多年的努力，事业终于有所起色；她和男友克雷（Justin Long 饰）的恋情虽遭对方母亲的反对，却也是情投意合，顺风顺水。可是，一场无妄之灾将她的人生推向谷底。住在布雷顿大街的吉普赛老妇人希尔维娅•加纳什（Lorna Raver 饰）因医疗纠纷面临房产被收回的困境，克莉丝蒂安同情她的遭遇，无奈规定所限无能为力。愤怒至极的加纳什迁怒于无辜的克莉丝蒂安，两人在车库中发生激烈搏斗，加纳什更向对方落下无情诅咒。在接下来的日子里，克莉丝蒂安遭遇诸多恐怖和离奇的事件。她决定拜访加纳什解决这一切，却发现老妇人已经去世。而魔鬼黑山羊的诅咒仍在继续……©豆瓣', '艾莉森·洛曼', '山姆·雷米', 6.5, 33829, 'tt1127180', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p449661697.jpg', 3, 12.8, 49.7, 26.8, 7.7, '0.211029,-0.050465,-0.772531,0.338329,0.001809,-0.346943,0.958095,0.093024,-0.364158,-0.186222,0.268534,0.552759,-0.603086,0.208900,0.264454,-0.251331,-0.044403,-0.602794,0.180742,-0.040789,-0.127022,-0.565066,-0.127823,-0.392846,-0.035030,-0.169207,0.488424,0.292224,-0.241580,0.078867,0.534106,0.595230,-0.277815,0.588301,0.026193,0.112257,-0.274056,-0.118427,-0.276192,0.015791,0.282150,-0.490253,-0.083834,0.208149,0.216350,0.376027,0.638717,-0.233475,-0.145462,0.078435,0.532863,-0.268595,0.010152,0.208633,0.356550,-0.046142,-0.268470,0.165068,-0.168549,-0.076746,0.053956,-0.158639,-0.625554,-0.017632,0.110615,0.152037,-0.556260,0.549284,0.031652,0.190145,-0.029889,-0.162026,0.006606,0.328978,0.386991,0.431253,-0.189588,0.012054,-0.248094,-0.010135,0.506679,0.002457,-0.316400,0.302498,-0.323389,-0.246563,0.057217,-0.252453,-0.437365,0.046282,0.451509,0.175639,-0.030959,0.638371,-0.423201,-0.239660,-0.436923,-0.327179,-0.230788,-0.304088,-0.157199,-0.476824,0.038866,-0.546999,-0.458406,0.013382,0.013719,-0.287754,0.469369,-0.569630,0.139184,0.375421,0.384187,-0.331644,0.300712,-0.007422,0.363623,0.108090,-0.070431,0.734754,-0.066240,0.039364,0.357366,0.052855,-0.157000,0.128411,-0.338941,0.417606', '21348112', '1292528', '3097044', '1307748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361528', '错爱', '恐怖', '陆慧（邓丽欣 饰）患上了胰脏癌，对自己、对同居男友恩明（余文乐 饰）都是不小的打击。陆慧妹妹爱看鬼故事，在学校被老师批评。心情不好的陆慧看着不懂事的妹妹，脾气大坏。恩明一边抚恤陆慧的情绪，一边应付繁重的工作。遇上公司裁员的恩明在面试新工作时重遇小学同学朱芳婷，虽然恩明还是抽出一切工余时间陪伴陆慧，但是备受病魔折磨的陆慧强颜欢笑、情绪不稳，而且行为古怪，这些都给恩明带来了巨大的压力。朱芳婷的善解人意与轻松自然，让恩明不自觉靠近，二人发生了关系，而且瞒着陆慧一直继续下去。一个雨夜，陆慧失踪，恩明开车寻找的时候遇上车祸，突发奇想去芳婷家寻找，发现芳婷受了伤而且表情怪异。深夜回到家的陆慧浑身湿透，在接下来的日子里身体还会发出恶臭。恩明怀疑自己与陆慧是鬼，然而事情的发展超出了所有人的意料。©豆瓣', '余文乐', '彭发', 5.9, 9699, 'tt1151318', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2355074026.jpg', 4.1, 18.9, 56.7, 16.8, 3.6, '0.348449,-0.299715,-0.467952,0.037979,-0.071006,-0.135359,0.525839,0.177874,-0.611843,-0.587185,0.103407,0.313298,-0.397920,0.136887,0.002919,-0.066081,-0.208009,-0.627956,-0.019167,-0.011007,-0.153059,-0.431784,0.002674,-0.226678,-0.041428,-0.494200,0.192911,0.055331,-0.195395,0.510360,0.111959,0.319504,-0.056738,0.661223,0.024389,-0.061815,-0.110909,0.206919,-0.046823,0.065999,0.447081,-0.184033,-0.142235,0.323582,0.302498,0.317564,0.545851,0.068659,-0.583904,0.180917,0.406194,-0.293605,-0.030819,0.196892,0.406945,0.227772,0.241111,0.134750,-0.306668,0.067291,-0.033105,0.014302,-0.441255,0.164715,0.152911,0.272628,-0.437849,0.409686,-0.010530,-0.097241,0.182574,-0.496134,0.366411,0.487584,0.211515,0.690502,-0.364691,0.289108,-0.373079,-0.087705,0.652157,-0.026364,-0.044074,0.444910,-0.336670,-0.056811,-0.083297,-0.092207,-0.443689,0.119042,-0.174243,0.222579,-0.150345,0.204553,-0.219501,-0.030461,-0.027774,-0.106662,-0.221794,-0.352381,-0.192208,-0.362063,-0.185652,-0.589455,-0.291156,0.045606,0.026274,-0.400430,0.404643,-0.641516,0.272870,0.213409,0.366553,-0.494811,0.443691,0.166080,-0.090675,-0.177360,-0.105807,-0.079671,-0.206491,0.060214,0.221588,0.169761,-0.164156,-0.313298,-0.248748,0.158913', '34841067', '1301022', '10574468', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361823', '我爱你莫里斯', '喜剧', '史蒂夫•拉塞尔（金•凯瑞 Jim Carrey 饰）是个付费收养来的孩子，他为了查出自己的亲生父母，做了一名警察，然而当他来到母亲的家门前，得到的却是闭门羹……幸好史蒂夫还有一个幸福的家庭，他与妻子育有一女，这对虔诚的夫妻每日祷告……然而这些都只是表象，事实上，史蒂夫是一名同性恋，他用无尽的谎言欺骗了所有人，终于一次车祸后，史蒂夫顿悟以前的生活一文不值，他公开了自己的性取向并远赴佛罗里达寻找幸福，常年欺瞒的日子造就了史蒂夫非凡的诈骗能力，不久东窗事发，史蒂夫入狱，却在狱中遇上了此生挚爱莫里斯（伊万•迈克格雷格 Ewan McGregor 饰 ），史蒂夫向莫里斯献出了自己全部的激情和勇气，这对儿从监狱中走出的恋人，留下了一段传奇故事。本片根据史蒂夫•迈克维克所写就的真实故事改编。©豆瓣', '金·凯瑞', '格伦·费卡拉', 7.9, 68773, 'tt1045772', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p669366779.jpg', 0.3, 1.7, 22.9, 50.6, 24.5, '0.102347,-0.028574,-0.522020,0.597885,-0.327200,-0.564993,0.871468,-0.066989,-0.441765,-0.330813,0.267390,0.900335,-0.085228,0.422701,0.224639,0.097046,-0.345112,-0.641953,0.106762,-0.271100,-0.124009,-0.503031,-0.211333,-0.292707,-0.141987,-0.196280,0.522164,0.050442,-0.072671,0.167455,0.373851,0.225578,-0.011808,0.276518,-0.258978,0.345325,0.143629,0.146270,-0.423650,0.082240,0.050447,-0.234115,-0.159435,0.277482,-0.148390,0.411357,0.428256,-0.316547,-0.234832,-0.025118,0.417785,-0.355560,-0.006032,0.159911,0.060559,-0.040544,0.190010,0.346070,-0.143916,-0.084990,-0.076155,-0.053364,-0.846813,-0.218257,-0.087940,0.047335,-0.459797,0.333209,-0.148473,-0.066392,0.119083,-0.177123,0.031202,0.192142,0.165978,0.506558,-0.330632,0.037237,-0.420719,0.330915,0.658005,-0.051435,-0.300639,0.499988,-0.271577,-0.364222,-0.002363,-0.058295,-0.585354,0.156842,0.368796,0.045775,-0.146337,0.233661,-0.406515,-0.136389,-0.413201,-0.057238,0.075023,-0.411395,-0.050619,-0.465326,-0.073661,-0.346551,-0.457865,-0.113462,0.033106,-0.430041,0.611501,-0.537370,0.276565,0.554599,0.088521,-0.506751,0.563143,0.171202,0.119138,-0.234953,0.071669,0.506988,0.087945,0.177474,0.155467,0.260492,0.122501,0.018419,-0.427450,0.596185', '34890458', '3119246', '30162520', '1308976');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361826', '如月疑云', '喜剧', 'C级、或者说D级明星如月美纪自杀了，这是一年前的新闻。她1周年忌日的追悼会召集了5位男士参加：家元（小栗旬饰）、小田裕二（中山裕介饰）、snake（小出惠介饰）、安男（冢地武雄饰）、草莓女孩（香川照之）。平日在网站上相识的5人第一次见面。献上花束的他们开始追思如月。“她不是自杀的”不知谁突然说的这句话,令所有在场的人都震惊了，大家开始就如月的死因进行分析，而5位男士，似乎也有自己的秘密。究竟真相是什么？这样的讨论，将聚会中的矛盾推向了高潮。©豆瓣', '小栗旬', '佐藤祐市', 8.1, 52967, 'tt1158278', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p655393674.jpg', 0.5, 1.9, 19.3, 49.8, 28.6, '0.274010,-0.069780,-0.726206,0.290564,-0.080381,-0.036131,0.569641,0.027461,-0.406200,0.106271,0.432658,0.554798,-0.781202,0.457586,0.408364,0.059462,-0.223981,-0.701089,-0.153044,-0.607118,-0.281789,-0.500526,-0.047658,-0.157467,0.123823,0.106237,0.400938,0.006785,0.046833,0.229885,0.439632,0.297300,0.198274,0.469289,0.103207,0.000466,-0.037245,0.296336,0.008023,-0.125961,-0.340845,-0.429034,-0.357454,0.385894,0.085129,0.560232,0.512367,-0.257000,0.067171,0.008848,0.450106,-0.136537,0.009000,0.026795,0.503396,0.188260,0.224662,0.427872,0.184273,-0.213612,-0.150493,-0.060485,-0.515882,0.276320,0.160473,0.275095,-0.334744,0.329786,-0.204271,0.080834,0.175435,-0.142203,0.271582,0.452093,0.154770,0.270475,-0.089513,-0.052983,-0.507652,0.514285,0.652038,-0.087733,-0.305646,0.345961,0.118743,-0.605344,-0.202513,-0.223090,-0.059952,0.258987,0.027525,0.196272,-0.166733,0.321555,-0.371025,-0.180957,0.161604,-0.186738,0.149324,-0.154919,-0.159932,-0.566541,-0.068708,-0.345721,-0.266171,-0.181622,0.299064,-0.211577,1.023445,-0.686375,-0.004655,0.340313,0.280974,-0.441437,0.594838,0.094487,-0.056257,0.094041,-0.219344,-0.103315,-0.136691,0.218749,0.130676,0.527877,0.149880,0.058218,-0.287880,0.260515', '27602116', '25922902', '25863940', '26790961');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2361919', '死神剧场版：钻石星尘的反叛 另一个冰轮丸', '动作', '在负责押送尸魂界王族秘宝“王印”的途中，一股神秘力量突然袭来，十番队虽奋力反击，却终究丢掉秘宝，日番谷冬狮郎（朴璐美 配音）也在阵前莫名逃亡。不久，日番谷临阵逃脱的报告传遍尸魂界，黑崎一护（森田成一 配音）从二番队队长碎蜂口中得知始末，之后遇见并救助了体力不支倒地的日番谷，继而得知袭击护送队伍且与日番谷交手的是一个早已死掉的死神草冠。这两个人当年曾是莫逆之交，他们的关系也让袭击事件变得扑朔迷离。日番谷的暧昧态度零十番队遭受软禁处罚，而草冠的背后有隐藏着怎样的势力和秘密？本片根据日本漫画家久保带人的同名原著改编，系该动画的第二部剧场版。©豆瓣', '森田成一', '阿部记之', 7.2, 7843, 'tt1148261', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p638715890.jpg', 0.7, 4.9, 40.4, 39.7, 14.3, '0.071988,0.033619,-0.456474,0.555701,0.295011,-0.021033,0.410508,0.108401,-0.402413,-0.387140,0.227427,0.691578,0.032030,0.023131,0.207580,-0.222158,0.004341,-0.484706,-0.464837,-0.184030,-0.322834,-0.234960,-0.061721,-0.007388,0.268085,-0.428498,0.681987,0.182952,-0.526585,0.604749,0.519348,0.599810,-0.567299,0.478134,0.049858,0.097505,0.350065,0.244515,0.030854,0.079489,-0.324893,-0.293528,-0.231750,0.052774,0.020948,0.479789,0.597580,-0.035035,-0.257141,-0.151379,0.210600,-0.213781,-0.104349,-0.108404,0.956736,0.023580,0.005703,0.450932,-0.035169,-0.265456,-0.379772,-0.001659,-0.786158,-0.036272,0.370753,0.084088,-0.345057,-0.015460,-0.056938,0.335050,0.246189,0.041522,0.196166,0.565713,0.377076,-0.023404,-0.131141,-0.173452,-0.379817,0.160582,0.805838,-0.521459,-0.242358,-0.160614,0.180038,-0.386370,-0.246477,-0.056291,-0.017630,0.025115,0.255726,0.029975,0.048898,0.041513,-0.522299,0.033072,-0.138586,-0.101219,-0.023233,-0.358767,0.139424,-0.751488,-0.140079,-0.185256,-0.241859,0.230130,0.297615,0.211735,0.379321,-0.435089,0.178920,0.695040,-0.158207,-0.442838,0.076196,0.257744,-0.020411,-0.155650,-0.096408,0.363859,0.308504,0.377081,0.168118,0.249176,0.074860,-0.283964,-0.529805,0.074988', '25980500', '3861846', '2369613', '1306983');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2362662', '寻找伴郎', '喜剧', '彼得（保罗·路德 Paul Rudd 饰）和佐伊（拉希达·琼斯 Rashida jones 饰）订婚了。在佐伊兴奋地向姐妹们报喜之时，彼得却发现自己居然找不出可以来做伴郎的死党。在走投无路的情况下，彼德开始了寻找伴郎的“相亲”过程。寻找伴郎的过程并不顺利，直到他遇到了神奇希德尼（杰森·西格尔 Jason Segel 饰）。希德尼激发出来不善于交际的彼得内心深处的潜能，俩个人成为无话不谈的朋友，曾至还组成了一个乐队。他们没完没了的聊天、打游戏、遛狗，几乎每天24个小时都粘在一起，这种狂热的关系最终影响到了彼得和未婚妻佐伊的感情。佐伊受不了自己的未婚夫满脑子装着另外一个男人，于是向他发出最后通牒，让他在哥们和自己中做出一个选择。©豆瓣', '保罗·路德', '约翰·汉博格', 7, 12194, 'tt1155056', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1367059227.jpg', 0.8, 5, 46.5, 39.7, 8.1, '0.415735,-0.238074,-0.911894,0.605131,-0.249681,-0.504021,0.601513,0.149976,-0.150367,-0.278987,0.061920,0.568374,-0.447839,0.277008,0.352936,-0.122822,-0.373201,-0.815413,-0.013322,-0.025430,-0.287610,-0.688994,-0.014202,-0.388562,-0.170802,-0.256543,0.289411,-0.287599,-0.010971,0.353808,0.517208,0.368953,0.025183,0.587269,0.025544,0.132653,0.367500,-0.255247,-0.229015,0.104162,0.145528,0.050240,0.058366,0.289892,0.231561,0.393886,0.661412,-0.436164,0.159362,0.181099,0.193367,-0.081300,0.108269,0.012419,0.242880,-0.220297,0.149070,0.052298,0.025212,-0.128467,0.089367,0.029154,-0.743158,0.178225,-0.000447,0.296539,-0.460927,0.255480,-0.048904,0.012329,0.233336,-0.495832,0.071569,0.448376,0.124782,0.333723,-0.274542,0.017161,-0.598612,0.002132,0.813916,0.207633,-0.203594,0.416556,-0.182351,-0.292871,-0.039694,-0.022658,-0.550718,-0.120032,0.382430,-0.066972,-0.104392,0.140265,-0.500475,-0.167677,-0.113838,-0.018092,0.300905,-0.470885,0.055791,-0.689001,0.102464,-0.289165,-0.488577,0.103858,-0.079475,-0.314538,0.657817,-0.793866,-0.016305,0.746037,0.163458,-0.266304,0.761697,0.029986,-0.045856,-0.197866,-0.041749,0.142388,0.218112,0.275549,0.409336,0.512242,0.132298,0.220854,-0.483411,0.417271', '4604803', '1947080', '3055049', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363506', '地球上的星星', '剧情', '对于8岁的男孩伊夏（达席尔·萨法瑞 Darsheel Safary 饰）来说，世界是充满了惊奇和快乐的万花筒，他正在用一切他能够想到的方式和这个陌生的世界进行着交流，同时也充分的享受着大地万物慷慨的赠与。可是，这样的伊夏却是成年人眼中的问题儿童，他的成绩不好，在班上的排名靠后， 脑子里还充满了各种匪夷所思的鬼点子，在又一次闯下大祸后，忍无可忍的父母将他送往了寄宿学校。虽然伊夏的新生活并没有什么改变，但在内心里，和父母分离的生活让他感到闷闷不乐，这时，一位名叫尼克（阿米尔·汗 Aamir Khan 饰）的美术老师走进了他的生活。和以往所见到的固守成规的老师不同，尼克主张让学生们保留自己的个性和思想，自由的发展。在和尼克相处的日子里，伊夏和尼克都慢慢的成熟了起来。©豆瓣', '达席尔·萨法瑞', '阿米尔·汗', 8.9, 192736, 'tt0986264', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2197897857.jpg', 0.2, 0.7, 8.3, 36, 54.9, '0.357099,0.006212,-0.848643,0.771056,-0.330585,-0.296483,0.920312,0.044169,-0.742163,-0.231438,-0.130038,0.721463,-0.155077,0.517605,0.233488,-0.005241,-0.351254,-0.879845,-0.174300,-0.122777,-0.274294,-0.633467,-0.189323,-0.188220,-0.243635,-0.427522,0.659499,-0.008885,-0.072984,0.645572,0.068584,0.125367,0.279040,0.601237,-0.348377,-0.122712,-0.023257,0.222776,-0.060728,-0.056471,0.383943,-0.051101,-0.338334,0.394269,0.099667,0.359474,0.693817,-0.356658,-0.406555,0.143021,0.366810,-0.229110,-0.205343,0.224916,0.095189,0.060470,0.204544,0.101150,-0.058764,0.212568,0.027589,0.071162,-0.952526,-0.178564,0.108866,0.154814,-0.828937,0.715216,0.094124,-0.237276,0.177042,-0.389641,0.133929,0.362261,0.298212,0.674823,-0.442166,0.049308,-0.406170,0.061606,0.671726,0.053887,-0.478336,0.472300,-0.596107,-0.452270,-0.256710,-0.060600,-0.569001,-0.108312,-0.054997,0.260859,-0.231766,0.300701,-0.654152,0.126326,0.050681,-0.350733,0.015769,-0.624779,-0.116473,-0.523034,-0.225450,-0.789431,-0.532014,0.025976,0.214737,-0.363601,0.969267,-1.181430,0.086258,0.219331,0.335617,-0.416427,0.772573,0.224003,0.001248,-0.317716,-0.256175,0.170954,-0.183237,0.395178,0.037871,0.699068,0.119406,-0.029594,-0.559478,0.830581', '35030151', '21360412', '35144311', '24756472');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363843', '一年到头', '喜剧', '春节将近，带着同村的几个兄弟在北京奋斗多年的包工头张国栋（陈刚 饰）正准备放下一年的辛劳，带着女友回家过年，但是一次小小的事故，让他结识了苦于无人装修新房的重点高中副校长白老师（冯丁洪 饰），于情于利，张国栋踊跃接下了白老师家的装修工作。另一面，内科主任医师李家梁（张彤 饰）也准备带家人回湖南老家为老父亲做寿，可不仅车票难求，一心想让儿子考上重点高中的妻子害怕耽误儿子学习，对回家一事坚决反对。张国栋的装修工程出了差错，着急用新家招待归国儿女的白老师急火攻心，进了李家梁所在医院，李妻得悉白老师身份，开始考虑如何为儿子拉上关系……一出回家探亲的戏剧在北京城里上演。©豆瓣', '陈刚', '王竞', 8.3, 7482, 'tt4543674', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1077092683.jpg', 0.4, 1, 16.5, 48.3, 33.7, '0.037894,0.060896,-0.395285,0.139165,-0.110037,-0.700979,0.312416,0.259895,-0.496300,-0.489865,-0.127067,0.283454,-0.151115,0.596106,0.106739,-0.196233,-0.128787,-0.213013,0.084298,-0.013843,-0.232270,-0.340244,0.392662,-0.222740,0.046279,0.208239,-0.000395,0.155911,0.393643,0.497549,0.278430,-0.173829,-0.070475,0.235259,-0.164707,0.057264,-0.172299,0.468469,-0.508135,0.203480,0.482544,0.069914,-0.299214,-0.155410,0.659622,0.337445,0.489558,0.574338,-0.106417,-0.012975,0.453027,0.033430,-0.009932,0.100912,0.530757,0.306504,0.179737,0.030266,-0.357544,0.100265,-0.132114,-0.254348,-0.131594,0.139313,0.266317,-0.175875,-0.860043,0.492233,-0.025353,-0.103005,-0.047072,-0.366297,0.201974,0.446517,-0.048147,0.621398,0.074036,0.544049,-0.171615,0.371618,0.425118,-0.383132,0.495912,-0.068376,-0.057314,-0.093971,0.504776,-0.164571,-0.495478,0.012855,0.109308,-0.218300,0.152396,-0.407204,-0.251197,-0.359322,-0.230473,-0.159381,0.241748,-0.277565,-0.016453,-0.392573,0.339420,-0.043317,-0.230273,0.189502,0.434448,-0.181477,0.314450,-0.552240,-0.054191,-0.074039,0.252113,-0.878361,0.575957,0.148099,0.338564,-0.332908,0.035256,-0.145853,0.017596,0.433983,0.253288,0.249571,-0.141634,-0.354763,-0.121617,0.257400', '1303485', '1308035', '1421278', '1295316');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363855', '蜡笔小新：呼风唤雨！会唱歌的屁股炸弹', '剧情', '小新一家去冲绳旅行，本来是平凡的一天，然而小新的宠物小白却突然沾上了一枚威力强大的炸弹！这个炸弹是被奇异的外星生物“屁股星人”遗留下来的，其力量足以毁掉整个地球。全球65亿人的注意力都集中在了一只小狗身上！面对来自宇宙监视中心和美女恐怖集团白黑两道对小白的争夺，小新挺身而出誓死保护小白！', '矢岛晶子', '武藤裕治', 8.3, 7846, 'tt2643866', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1720029338.jpg', 0.4, 1.8, 19.2, 40.1, 38.6, '0.379968,0.324326,-0.867462,0.460628,-0.127524,0.333275,0.627792,-0.013631,-0.107075,0.039432,0.299182,0.673046,-0.207744,0.042312,-0.135092,0.384240,0.370540,-0.452178,-0.293163,0.017368,-0.462966,-0.100133,-0.739173,-0.108326,-0.010336,-0.372676,0.619885,0.004107,-0.218019,0.383326,0.289237,0.342838,-0.262852,0.652051,-0.375140,-0.278710,-0.407187,-0.292610,0.184674,0.177430,-0.236864,-0.095282,0.457064,0.304149,-0.239890,0.014245,0.772260,-0.356318,0.173294,-0.437436,0.365291,-0.267564,-0.181216,-0.014917,0.590957,0.052841,0.143441,-0.421882,0.002431,0.131695,0.593167,-0.119424,-0.746092,-0.467174,-0.023378,0.092011,-0.302806,0.286707,0.039405,0.061472,0.065261,-0.016239,0.511481,-0.068752,-0.162198,0.404756,-0.159003,0.292090,-0.306953,-0.187791,0.516986,-0.391067,-0.394509,0.147519,-0.076228,-0.279458,-0.458043,-0.381999,-0.158471,-0.028423,0.375531,0.217771,-0.160462,0.324675,-1.158174,0.336715,-0.306903,-0.296944,-0.023463,-0.425207,-0.044869,-0.314964,-0.113276,-0.350197,-0.168957,0.469413,0.267623,-0.192531,1.035872,-0.474124,0.048662,0.674568,0.332137,-0.174810,0.569438,-0.243308,0.184670,-0.121269,-0.012138,0.126028,0.391184,0.435202,-0.048965,0.398585,0.218554,0.194718,-0.393363,0.661994', '26290398', '4181031', '1302661', '1309031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363876', '007：大破天幕杀机', '动作', '数月前军情六处一块记载了潜伏于全世界恐怖组织内部所有特工名单信息的硬盘丢失，而追索硬盘的行动也以失败告终。在此之后，行动主要负责人M（朱迪·丹奇 Judi Dench 饰）被高层解雇，而军情六处也遭到惨烈的袭击，伤亡惨重。为了查到幕后真凶，M召来佯死的传奇特工詹姆士·邦德（丹尼尔·克雷格 Daniel Craig 饰）。经过一轮严苛的特训和测试，邦德重新服役。在伊芙（娜奥米·哈里斯 Naomie Harris 饰）和新搭档Q（本·卫肖 Ben Whishaw 饰）的协助下，邦德追寻着某前CIA特工的踪迹来到繁华大都会上海。在这一过程中，特工的名单不断泄露，而邦德最新一次的生死冒险也拉开序幕……©豆瓣', '丹尼尔·克雷格', '萨姆·门德斯', 7.2, 246172, 'tt1074638', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1706050033.jpg', 0.8, 5.1, 41.2, 41, 11.9, '-0.125424,0.015540,-0.749606,0.649693,0.313197,0.026529,0.436437,-0.107981,-0.459936,-0.202726,0.328780,0.707853,-0.135611,-0.109335,0.503850,-0.111497,-0.519316,-0.785611,-0.042814,-0.430894,-0.437968,-0.628643,-0.253484,-0.440960,0.233200,-0.275518,0.678934,0.237097,-0.300851,0.393015,0.322120,0.369606,-0.495614,0.226832,0.169708,-0.158056,0.551354,-0.327107,-0.366978,0.269849,0.027327,-0.375714,-0.157663,0.051146,0.283518,0.483860,0.655778,-0.419797,-0.076448,-0.125634,0.321370,-0.308702,-0.093346,-0.082669,0.592247,0.202964,-0.001796,0.528790,-0.213969,0.146632,-0.008148,-0.203126,-1.026731,-0.292140,0.121746,0.275451,-0.314011,0.232048,-0.555139,0.348554,-0.037207,-0.227292,0.189907,0.580618,0.169217,-0.152598,0.070107,0.061007,-0.132346,0.088314,0.323239,-0.097858,-0.098243,-0.049757,0.209001,-0.515358,-0.064676,-0.148766,-0.177413,0.120204,0.361777,-0.074331,-0.003801,0.185368,-0.688288,-0.030556,-0.492446,-0.469978,-0.195652,-0.052747,-0.136339,-1.011281,-0.117172,-0.130862,-0.439642,0.190783,0.105558,0.005412,0.397868,-0.673269,0.170908,0.605956,-0.214248,-0.558589,0.153747,0.030062,0.375712,-0.355630,-0.186859,0.225282,0.660765,0.654831,0.055420,0.153676,0.001550,-0.385304,-0.374950,-0.124562', '2028645', '25723905', '10463953', '27126336');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363879', '女演员们', '剧情', '片中的演员们均以自己的本名出演，剧中的大量对话也均出自于演员们的即兴表演而非剧本。故事发生在寒冷的圣诞节前夜，杂志社开启了一个特殊的专题，召集不同年龄段的女演员们，共同拍摄一辑以她们为主题的写真。就这样，曾经红极一时但如今已经过气的尹汝贞和李美淑，资质最浅但目前风头最劲的金玉彬，身材火辣个性不羁的金敏姬，由于出演电视剧而在日本有着大批粉丝的崔智友，看似自信但对自己的脸庞很不满意的高贤贞，这样六个个性都极为强烈的女人们聚到了一起。在高贤贞咄咄逼人的挑衅之下，现场的气氛开始变得紧张，而拍摄使用的珠宝又迟迟不来，无聊之中，女演员们提议举办一场圣诞晚宴，一场关于女演员这个特殊的职业和她们所拥有和期望的人生的探讨开始了。©豆瓣', '尹汝贞', '李在容', 7.7, 7135, 'tt1459219', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p508995831.jpg', 0.4, 2, 27.3, 50.8, 19.4, '0.456294,-0.013996,-0.719316,0.769857,0.052973,0.132798,0.592734,0.136713,-0.364585,-0.370794,0.310170,0.846071,-0.546146,0.230849,0.338447,-0.371152,-0.211309,-0.599113,-0.427415,-0.096788,-0.023505,-0.296919,-0.215317,-0.054046,-0.224693,-0.280198,0.883900,-0.046199,-0.386758,0.636154,0.598447,0.136717,0.077570,0.398783,-0.001786,-0.256871,0.040828,0.184190,-0.067471,0.107371,0.029039,-0.161402,-0.352781,0.381493,0.073364,0.447485,0.759868,-0.234851,-0.260743,0.165910,0.645458,-0.279464,-0.045508,0.198809,0.347843,0.147402,0.540350,0.086560,-0.058193,0.229499,-0.382534,-0.186786,-0.958340,0.238344,0.307586,0.196999,-0.379522,0.404967,0.085672,-0.265336,0.032481,-0.086064,0.201657,0.296988,0.388008,0.318693,-0.079858,-0.047533,-0.285674,0.435268,0.850831,0.318307,-0.443371,0.555402,-0.386796,-0.507853,-0.279820,-0.347588,-0.610468,0.132368,-0.023381,0.012736,0.043683,0.148071,-0.862191,0.060246,0.168138,-0.219323,-0.096533,-0.440583,0.013435,-1.147951,-0.327529,-0.595734,-0.182329,-0.260218,0.381511,-0.351992,1.162779,-1.027946,-0.070066,0.226681,0.046115,-0.724272,0.656322,0.287912,0.060206,-0.097302,-0.438665,-0.064449,-0.022974,-0.128095,-0.170346,0.601638,-0.176240,-0.332375,-0.475968,0.476472', '3811356', '27602116', '3318306', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363919', '最后的风之子', '动作', '本片由知名动画剧集《Avatar：The Last Airbender》改编而成。水、火、土、气，乃支配世界的四大元素。操纵这四大元素的四个种族，分别是气和寺，水善部落，火烈国，土强王国。火烈国挑起了战争，气和寺被毁灭，水善部落面临灭绝，逃到了与世隔绝的冰天雪地；只有土强国仍在反抗。降世神通，是世上唯可以保护世界的平衡与和谐之人，却突然失踪。弹指百年，水深火热中的人们早已忘记了救世主的传说。而在南极雪原上，冰层突然爆裂，冰封的球形中出现了个12岁的神秘男孩安（诺亚·林格 noah ringer 饰），而这个孩子竟然就是失踪已久的降世神通！在水部落卡塔拉（妮可拉·佩尔茨 Nicola Peltz 饰）和哥哥索卡（杰克逊·拉斯波恩 Jackson Rathbone 饰）的帮助下，安被唤醒体内神力，最终与同伴一起踏上拯救人类的道路。可这个孩子是否能阻止邪恶的火烈国征服世界呢？', '诺亚·林格', 'M·奈特·沙马兰', 5, 22854, 'tt0938283', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p494445594.jpg', 17, 32.6, 36.5, 9.9, 4.1, '-0.034662,0.500241,-0.489017,0.454085,0.230483,0.018947,0.538064,0.215312,-0.237109,-0.210055,-0.200571,0.693257,-0.134470,0.151738,0.236298,0.129195,-0.059650,-0.648963,-0.311300,0.157537,-0.274085,-0.148445,-0.348464,-0.063513,0.045677,-0.959283,0.687831,0.302774,-0.267716,0.026164,0.260136,0.395222,-0.468326,0.211337,-0.376375,-0.112640,-0.113244,-0.022754,-0.185459,0.146739,-0.478372,-0.017450,0.043023,0.280949,-0.119017,0.135086,0.485590,-0.520260,0.316336,-0.445267,0.294436,-0.577083,-0.132256,-0.314608,0.416819,-0.328994,0.169177,0.177420,0.198726,-0.175547,0.364849,-0.237802,-0.821104,0.019554,0.383632,0.006693,-0.469186,0.348231,0.343047,-0.262943,-0.226788,-0.154276,0.329490,0.395054,0.108520,0.511080,-0.235276,-0.230799,-0.543290,-0.127688,0.579434,-0.507719,-0.486187,0.123991,-0.082181,-0.468798,-0.487096,-0.463850,-0.294911,-0.199349,0.365204,0.161066,0.041107,0.397245,-0.871508,-0.053171,-0.251670,-0.061247,0.255167,-0.364131,-0.095296,-0.292791,-0.066197,-0.070150,-0.156659,0.067447,0.355317,0.131337,0.733040,-0.615403,0.336350,0.389856,0.298133,-0.406062,0.735720,0.072272,-0.025955,-0.263081,0.173084,0.397451,0.150617,0.338474,0.017743,0.400367,-0.124125,0.389011,-0.479594,0.334589', '2364054', '26290398', '3769423', '6982558');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363925', '观鸟大年', '喜剧', '“大年（big year）”是观鸟爱好者的一种竞赛，参赛者需要用一整年的时间和精力，记录自己观察到的鸟类种类数量，数量最多者取胜。布莱德、斯图和肯尼就是三位铁杆观鸟爱好者。布莱德（杰克·布莱克 Jack Black 饰）是个一事无成的大龄宅男，因此决定花掉一大笔钱参加“大年”时，他父母觉得他疯了；斯图（史蒂夫·马丁 Steve Martin 饰）是一家大公司的总裁，所以当他决定放下手头百万生意，跑去参加“大年”，他助理觉得他疯了。此一老一少在竞争中相识，很快成为朋友，决定共同对付他们最强的对手——上一届“大年”的得胜者肯尼（欧文·威尔逊 Owen Wilson 饰）。只有鸟友才懂，放弃整整一年的事业和生活意味着什么，三个“鸟友”在大年中奋力竞争，最终要回头面对的还是生活中的问题……影片改编自1998年马克·欧布马克西(Mark Obmascik)的同名小说。', '欧文·威尔逊', '大卫·弗兰科尔', 7.6, 9670, 'tt1053810', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1200609529.jpg', 0.4, 3, 31.2, 45.6, 19.8, '0.016644,-0.226350,-0.494673,0.279287,-0.038261,-0.336432,0.439145,-0.236206,-0.543991,-0.422109,-0.001141,0.862137,-0.205564,0.238566,0.363821,-0.161250,-0.103559,-0.580114,-0.077054,-0.259175,-0.220966,-0.569227,-0.230318,-0.241187,-0.066923,-0.116148,0.401553,0.017974,0.010908,0.455178,0.416110,0.039834,0.398122,0.042886,0.034046,-0.192668,0.112831,-0.048582,-0.267998,0.322304,-0.017778,-0.004252,-0.528611,-0.224380,0.469433,0.264721,0.318560,-0.097444,-0.093176,0.030971,0.156786,-0.291718,-0.319648,-0.055408,0.360661,-0.020393,0.275045,0.174272,-0.184954,0.075429,-0.057981,-0.293225,-0.673867,0.099230,0.039110,0.034679,-0.634435,0.489453,-0.008132,-0.075081,-0.114739,-0.427662,-0.178359,0.291604,0.303041,0.243856,-0.073351,-0.193145,-0.346975,0.315369,0.772788,-0.033301,-0.165771,0.289984,0.070732,-0.467221,-0.384442,-0.515214,-0.384156,0.037361,0.117681,0.122361,-0.131806,0.354955,-0.660174,0.257816,-0.106582,-0.507316,0.139978,-0.224670,0.043494,-0.489577,-0.026497,-0.313101,-0.250078,0.252153,0.273582,-0.572811,1.007580,-0.727718,0.034912,0.452180,0.475003,-0.417894,0.901462,0.049907,0.081766,-0.126086,0.083422,-0.156155,0.010089,-0.004386,0.039638,0.135508,0.111291,-0.544381,-0.227471,0.430618', '26711487'