INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2363942', '44号孩子', '剧情', '故事发生在斯大林时代的前苏联，男主角Leo Demidov是一名苏联国家安全部(MGB)的特工，他尽忠职守、热爱自己的国家，充满理想主义。作为一名战斗英雄，Leo享受国家给予的特别待遇，不仅他自己一家住在莫斯科的豪宅区，他的父母也分到了很好的公寓。尽管也秘密逮捕和刑讯逼供，但Leo认为这都是为了国家利益。不过一桩儿童系列凶杀案改变了Leo的生活轨迹，政府不愿承认凶案的事实，一心想捉到凶手的Leo成为政府猜疑的目标，只有他的妻子始终站在他这一边……', '汤姆·哈迪', '丹尼尔·伊斯皮诺萨', 6.7, 6183, 'tt1014763', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2232866868.jpg', 1.7, 9.9, 50, 28.5, 9.9, '0.320840,-0.078047,-0.951163,0.703889,-0.303614,0.038559,0.823712,0.105450,-0.437384,-0.158636,0.579893,0.933331,0.284795,0.059693,0.331871,-0.055185,-0.323439,-0.538618,0.044581,-0.207217,-0.230828,-0.506790,-0.184954,-0.565103,-0.242000,-0.067582,0.855232,0.068427,-0.295494,-0.071969,0.463613,0.440638,0.057377,0.527888,-0.283631,-0.148464,0.263013,0.026220,-0.413325,0.161831,-0.047563,-0.263370,-0.140024,0.388595,-0.076350,0.351151,0.457185,-0.205461,-0.432720,-0.036236,0.311917,-0.525702,-0.153945,-0.073462,0.477505,-0.108225,-0.024846,0.565077,0.014924,-0.160805,0.126448,-0.087636,-0.953442,-0.279232,0.369010,0.240226,-0.414863,0.690629,-0.107838,0.041763,-0.059796,-0.310999,0.287786,0.522076,0.223796,0.383582,-0.390636,0.245446,-0.918871,0.290184,0.774582,-0.085445,-0.442017,0.240853,-0.689010,-0.514620,-0.156741,-0.349030,-0.536630,-0.236107,-0.086409,-0.182893,-0.309964,0.195416,-0.475647,-0.015580,0.057124,-0.396352,0.081722,-0.698947,0.138305,-0.335193,-0.177861,-0.651810,-0.502873,0.083210,0.132269,-0.409472,0.749700,-0.774681,-0.064422,0.792645,0.216104,-0.828132,0.913797,0.409007,0.104538,-0.219817,-0.356480,0.422941,0.104318,0.269151,-0.089848,0.241866,0.120689,-0.329294,-0.166568,0.572989', '30163500', '1456503', '25932086', '1299628');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364001', '梦幻岛', '恐怖', '迈克尔·佩纳将主演电影版[梦幻岛]，饰演剧集版中里卡多·蒙特尔班的角色。原剧包含黑暗主题及超自然元素，讲述太平洋上坐落着一个神秘度假岛屿，人们的各种古怪要求似乎都可以在这里得到满足。本片由杰夫·瓦德洛([海扁王2])自编自导，故事讲述岛上的监工罗尔克警告客人们，他们的幻想可能无法实现。', '露西·海尔', '杰夫·瓦德洛', 5.4, 10180, 'tt0983946', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2584076497.jpg', 8, 30.6, 47, 10.8, 3.6, '0.298483,0.016949,-0.519192,0.773271,0.310055,0.098427,0.631242,0.091777,-0.308158,-0.041545,0.139579,0.351837,0.095897,0.032429,0.333449,-0.101841,-0.810069,-0.096510,-0.188425,-0.165521,-0.052644,-0.613709,-0.410664,-0.342765,-0.290333,-0.494383,0.209198,-0.007325,-0.357255,0.036947,0.512444,0.539195,-0.201973,-0.048924,0.102954,0.038695,0.291368,-0.156899,-0.374663,0.175322,-0.180242,0.228422,-0.164477,-0.008400,0.138993,0.102750,0.676363,-0.199394,0.210535,0.036601,0.409097,-0.179667,0.358737,0.086329,0.041466,-0.087887,0.166888,0.044292,0.034908,-0.157919,0.021564,-0.258487,-0.660937,-0.074791,0.131472,0.465281,-0.097896,-0.243346,0.156032,-0.016026,-0.036968,-0.112814,-0.016091,-0.088729,0.732421,0.155641,0.157706,0.073270,-0.253616,0.531852,0.328489,-0.100301,-0.523655,-0.106931,-0.347296,-0.395738,-0.438895,0.070266,-0.686085,0.132617,0.303235,0.076828,0.141582,0.346386,-0.474451,-0.174467,-0.008520,-0.498118,-0.004492,-0.420655,-0.186573,-1.299290,-0.158161,0.201371,0.267852,-0.363355,0.317123,0.050270,0.657317,-0.452282,0.309601,0.481155,0.274921,-0.066275,0.666600,0.099345,0.079458,-0.411735,0.012673,0.325571,-0.020716,0.082781,0.077771,0.468287,0.069615,-0.022577,-0.456725,0.495154', '34961898', '6517421', '26275494', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364051', '鸡皮疙瘩', '喜剧', '影片《鸡皮疙瘩》是根据R.L.斯坦的同名畅销丛书《鸡皮疙瘩》改编而来的。《鸡皮疙瘩》丛书是90后群体的一大童年记忆，故事中充斥黑暗恐怖的元素，同时超级反转的结局也让人印象深刻。电影不仅截取了书中的故事，更将作者R.L.斯坦融入情节之中。杰克·布莱克就将扮演丛书的作者斯坦。影片的故事讲述了迪兰·米内特饰演的邻居家男孩在一次偶然中，将斯坦书里奇幻而恐怖的生物带到了真实世界。为了避免这些数量巨大的恐怖怪物毁灭宁静的小镇，斯坦必须联合他的邻居和女儿进行殊死抵抗······', '杰克·布莱克', '罗伯·莱特曼', 6.3, 20435, 'tt1051904', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2254745692.jpg', 2, 14.3, 54.8, 22.3, 6.6, '0.284940,-0.144439,-0.577870,0.708581,0.188829,-0.177422,0.947671,0.136718,-0.503863,-0.025855,0.357670,0.556574,-0.267531,-0.217694,0.166732,0.015585,-0.383085,-0.556108,-0.256287,0.079763,-0.232625,-0.382624,-0.533275,-0.415537,0.039666,-0.717689,0.353603,0.210591,-0.754620,0.082837,0.004842,0.510329,-0.346933,0.233272,0.168245,0.154550,-0.080377,-0.122662,-0.086289,0.282859,-0.186725,0.094444,-0.042658,0.086836,-0.327790,0.317623,0.856367,-0.411462,0.059945,-0.083464,0.630737,-0.242296,-0.430147,-0.157535,-0.018589,0.177049,0.784533,0.043530,0.045276,-0.199641,-0.157390,-0.262491,-1.021067,-0.119730,0.332619,0.265311,-0.210594,0.351571,-0.006003,-0.053815,0.449481,-0.180669,-0.010264,-0.329912,0.718407,0.530086,-0.010396,-0.000728,-0.109146,0.388332,0.405148,-0.182175,-0.428803,0.270244,-0.587720,-0.177209,-0.383478,-0.183668,-0.453589,0.328480,0.341609,0.108481,-0.084021,0.823011,-1.062295,-0.001577,-0.221532,-0.511497,-0.141102,-0.358864,-0.297741,-0.557555,-0.603314,0.221812,0.038961,-0.274244,0.243058,-0.402247,1.160367,-0.231165,0.418853,0.637907,-0.040564,0.105406,0.473992,-0.017495,0.094225,0.107654,0.254481,0.084321,0.024871,0.335507,0.121086,0.397851,-0.092634,-0.148906,-0.521989,0.962632', '4181031', '26667010', '27602116', '1302661');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364054', '绿灯侠', '动作', '几个世纪以来，有一群拥有强大力量的精英团队维护着浩瀚宇宙的和平。他们每人都有一只绿色的能量戒指，绿色的灯光就是他们的力量之源，他们被称为“绿灯军团”。但是，突然有一天，身处宇宙多处的绿灯侠不断传来受到袭击身亡的事件。原来，沉寂多年的邪恶魔王派瑞莱克斯苏醒，他要抢夺绿灯侠们的绿色能量源，因此展开了全宇宙追杀绿灯侠。这时在地球上，拥有非凡天赋却自命不凡的试飞员哈尔（瑞安·雷诺兹 Ryan Reynolds 饰）无意中获得了陨落地球的绿灯侠的绿色戒指，成为了守护地球的新的绿灯侠。而且其作为人类散发出的人性，也是其他绿灯侠们所不具备的独特气息。为了能打败派瑞莱克斯，保护地球拯救人类，哈尔需要克服恐惧，熟练运用自己的绿灯能量。魔王临近，哈尔能否打败魔王，成为最伟大的绿灯侠？©豆瓣', '瑞安·雷诺兹', '马丁·坎贝尔', 6, 82107, 'tt1133985', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p974363608.jpg', 3.9, 20.4, 54.6, 16.1, 5, '0.098512,0.494570,-0.632172,0.683484,0.020437,0.175422,0.668573,0.113067,-0.132952,-0.331000,0.357674,0.578059,0.129758,-0.012190,0.048343,0.057123,-0.037831,-0.244535,0.082073,0.007842,-0.359793,-0.242382,-0.633806,0.096688,0.069185,-0.811108,0.913057,0.243428,-0.257378,0.187277,0.042515,0.161564,0.028744,0.345521,-0.289814,-0.208350,0.042543,-0.180193,-0.086783,0.266807,-0.283770,0.196863,0.248947,0.395973,-0.458603,0.107655,0.574749,-0.475946,0.066902,-0.412033,0.495535,-0.592689,-0.067814,-0.348845,0.376255,0.044495,0.068377,-0.147343,0.225642,-0.125423,-0.111063,0.049391,-1.157820,-0.226849,-0.054645,0.241934,-0.346389,-0.014735,-0.172707,-0.321473,0.089728,-0.077719,0.091766,0.210856,0.090580,0.330159,-0.094634,-0.082876,-0.739783,-0.159202,0.729693,-0.448064,-0.885846,0.427352,-0.247775,-0.442840,-0.258347,-0.426743,-0.435523,-0.228210,0.644450,0.299946,0.141133,0.396865,-1.009789,0.299918,-0.045576,-0.151058,0.259239,-0.269568,-0.125228,-0.548308,-0.320391,-0.388210,-0.230593,0.171153,-0.068221,-0.249884,0.930822,-0.982972,0.474858,0.550603,0.208746,-0.525116,0.755815,-0.354621,-0.207832,-0.438544,-0.048215,0.118930,0.408636,0.476769,-0.065311,0.193674,0.148879,0.079774,-0.061648,0.504310', '24284209', '26667010', '3769423', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364074', '海云台', '剧情', '故事发生在韩国釜山的海云台，在2004年印尼海啸中，由于船长万植（薛景求 饰）的失误导致了妍熙（河智苑 饰）父亲的死，他内心怀有深深地自责，并无微不至地照顾这个邻家妹妹，慢慢地两人暗生情愫。不过，万植的中学同学吴东春（金仁权 饰）却并不看好这对苦命鸳鸯。万植的弟弟亨植 （李民基 饰）是海上救生员，他在一次行动中，认识了富家小姐金希美（姜艺媛 饰），两人在阴差阳错的交往中，闹出了不少误会。维珍（严正花 饰）推动海云台成为世博会旅游观光点的大使，她和前夫——国际海洋研究所地质专家金辉（朴重勋 饰）育有一女，但她现已另觅爱人。金博士为此非常苦闷，同时他在观测中发现大马岛和海云台的东海地质情况跟2004年的印尼海啸如出一辙，一次罕见的巨大海啸正在逼近海云台，然而灾难防御厅却对此不以为然……©豆瓣', '薛景求', '尹济均', 6.5, 39885, 'tt1153040', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1360132642.jpg', 3, 12.8, 50.1, 26.3, 7.8, '0.029518,-0.054636,-0.898303,0.639144,0.347940,-0.135838,0.690980,0.061795,-0.591913,-0.205894,0.259854,0.581170,-0.275496,0.194907,0.091753,0.048008,-0.206831,-0.589158,-0.097493,-0.052360,-0.349421,-0.436409,-0.091727,0.007356,-0.144852,-0.213763,0.376045,0.251735,-0.063315,0.728212,0.171654,0.455851,-0.057863,0.581725,-0.179833,0.170808,0.007773,0.246592,-0.217808,0.066844,-0.057635,-0.190312,-0.172267,0.273216,0.336882,0.328898,0.682748,-0.370501,-0.079840,-0.074717,0.191130,-0.236697,0.036529,-0.045030,0.579378,0.023024,0.046286,0.111220,-0.358197,-0.024078,0.026732,-0.093814,-0.269856,-0.003325,0.143360,0.158507,-0.452996,0.410826,0.048437,-0.146894,-0.123740,-0.009515,0.062661,0.200630,0.094104,0.372368,-0.324839,0.172259,-0.288096,0.153621,0.521412,0.239422,-0.027186,0.432575,-0.303280,-0.392799,-0.214778,-0.038888,-0.338105,0.078723,0.238941,-0.023176,-0.175025,0.316176,-0.471538,0.050043,-0.216460,-0.044487,-0.058644,-0.265167,-0.189034,-0.511289,-0.156516,-0.694509,-0.248481,-0.120327,-0.077353,0.041511,0.642337,-0.790176,0.167550,0.397910,0.299783,-0.438223,0.669280,0.314907,-0.165519,-0.335727,-0.262822,0.119734,-0.244594,0.149246,0.016259,0.277192,0.043206,-0.210138,-0.249513,-0.061124', '3111650', '25723081', '26354526', '26425072');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364086', '隐形人', '科幻', '西西莉亚（伊丽莎白·莫斯 Elisabeth Moss 饰）再也想不到，曾经将自己迷得神魂颠倒的英俊男人阿德里安（奥利弗·杰森-科恩 Oliver Jackson-Cohen 饰），如今会成为噩梦的始作俑者。在和自己恋爱后没多久，阿德里安便开始对西西莉亚进行精神和肉体上的双重控制，终于，忍无可忍的西西莉亚在一天深夜用安定将阿德里安迷晕，成功的逃出了魔窟。之后，西西莉亚震惊的收到了阿德里安自杀的消息了，她几乎不敢相信，这个魔头真的从自己的生活中彻彻底底的消失了。西西莉亚的疑虑并不是空穴来风，在她生活的角角落落中，似乎都有一个无形的影子在窥视着她，企图触碰她。©豆瓣', '伊丽莎白·莫斯', '雷·沃纳尔', 7.1, 203789, 'tt1051906', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2624945594.jpg', 0.7, 4.7, 40.5, 46.4, 7.8, '0.255559,0.340333,-0.902548,0.432119,-0.346464,-0.186643,0.979235,-0.103764,-0.686884,-0.144138,0.259481,0.693833,-0.498744,0.324729,0.365429,0.299275,-0.217098,-0.995678,-0.025407,-0.416639,-0.353295,-0.403367,-0.508194,-0.376336,-0.016849,-0.509148,0.495343,0.139801,-0.229953,0.291904,0.254701,0.062391,0.194619,0.847947,-0.239425,0.336024,0.092026,-0.185482,0.043026,0.341565,0.180911,-0.389004,-0.050653,0.524472,-0.274731,0.334792,0.625412,-0.523491,-0.103671,0.208492,0.240054,-0.437733,-0.227005,0.380578,0.083455,-0.164774,-0.069682,0.048538,-0.415857,-0.041738,0.232025,0.204106,-0.809063,-0.108433,-0.098302,0.181752,-0.550563,0.460244,-0.074129,0.003901,0.073395,-0.292654,0.235530,0.275912,0.093131,0.485822,-0.340070,0.092557,-0.488991,0.233828,0.500595,-0.035825,-0.347134,0.405740,-0.102370,-0.409604,-0.286723,0.010278,-0.403219,-0.132538,0.532404,0.272465,-0.420095,0.446144,-0.573774,-0.115022,-0.344766,-0.206812,-0.252313,-0.424298,-0.267286,-0.385437,-0.293748,-0.321472,-0.289546,0.047490,-0.118795,-0.292840,0.454788,-0.896240,0.446363,0.653372,0.155672,-0.276682,0.395938,0.028294,0.053649,0.015566,-0.098723,0.508783,0.088641,0.587347,0.375303,0.539398,-0.074601,0.100662,-0.544770,0.774013', '1947080', '21348112', '3027015', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364838', '鬼影', '悬疑', '美国摄影师本杰明•肖（Joshua Jackson 饰）因工作原因携新婚妻子简（Rachael Taylor 饰）飞往日本。夜晚，他们驱车行驶在一条荒无人烟的小路上。突然，一个女子（Megumi Okina 饰）出现在他们的面前，汽车无情撞上该女子。当他们清醒过来时，却未发现那名女子的尸体。本杰明认为女子已经接受治疗或纯粹是幻觉所至，遂匆匆离开此地。不久，本杰明发现自己的照片中经常浮现奇怪的光影，而简也不断为被撞女子的鬼影所困扰。恐怖事件变本加厉，夫妻俩的好友接连死去，随着事态的恶化，他们也逐渐知晓造成这一切的原因……©豆瓣', '乔舒亚·杰克逊', '落合正幸', 6.2, 5904, 'tt0482599', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2097804579.jpg', 2.4, 14.2, 58.4, 19.8, 5.2, '0.100592,0.039571,-0.742085,0.427439,0.058801,-0.150055,0.955146,0.040900,-0.538478,-0.640851,0.345724,0.770962,-0.361980,0.234359,0.458768,-0.077910,-0.173586,-0.530160,-0.085627,-0.192318,-0.587541,-0.217777,-0.166981,-0.479019,-0.169681,-0.152800,0.452287,0.305889,-0.222257,0.613097,0.200877,0.266667,-0.523908,0.688756,0.023860,0.017172,-0.065271,0.106278,-0.004176,0.002843,-0.036128,-0.736409,0.082583,0.052748,-0.405767,0.389610,0.991160,-0.131309,-0.330122,-0.419586,0.236113,-0.205168,0.154451,0.023181,0.366946,-0.061380,0.219857,-0.149057,-0.136584,-0.307975,0.025503,0.006309,-0.079811,0.091855,-0.096596,0.222719,-0.334647,0.186414,-0.156850,-0.003689,0.025523,-0.381326,0.232421,0.354975,0.328816,0.198528,-0.167759,-0.112796,-0.424121,0.178725,0.593764,0.251200,-0.246242,0.593789,-0.332926,-0.360193,-0.047027,0.208075,-0.308804,-0.020137,0.347947,0.371281,-0.125250,0.161253,-0.043179,-0.145612,-0.335737,0.023123,-0.323964,-0.155886,-0.343276,-0.530203,0.088478,-0.286755,-0.299105,0.199223,-0.299478,0.144541,0.362700,-0.644242,0.467417,0.380779,0.285410,-0.396856,0.478095,-0.189505,0.107354,-0.172580,-0.169172,0.235042,0.106217,0.152852,0.035579,0.034786,-0.351388,0.113160,-0.267212,0.385375', '1773217', '3011051', '21348112', '1309297');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364973', '超级英雄', '喜剧', '和叔叔婶婶一起生活的瑞克（德雷克•贝尔 Drake Bell 饰）算得上是一个标准的失意路人甲了，他暗恋同班的邻家美女吉尔（萨拉•帕克斯顿 Sara Paxton 饰），但在吉尔狂妄的男友兰斯面前却感到自己毫无机会。在班级旅行中，瑞克一班人参观了动物基因实验室，擅于把所有事情搞砸的瑞克被经过基因改造的蜻蜓咬啮，从此拥有了超人的能力：不死之身外加具有吸附力的身体。与此同时，兰斯的叔叔兰德斯（克里斯托弗•麦克唐纳 Christopher McDonald 饰）掌控的医疗中心正在加紧研制人类基因改造技术，罹患绝症的兰德斯借助该技术令自己获得新生，但代价是吸取别人的生命才能维系自身存活。瑞克经历了超人学院后勉为其难开始了自己的城市英雄生涯，他与代号“沙漏”的恶徒兰德斯之间必有一战……©豆瓣', '德雷克·贝尔', '克雷格·麦辛', 6.5, 15866, 'tt0426592', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2327821981.jpg', 4.1, 14.5, 46.5, 24.1, 10.8, '0.154434,0.077817,-0.340792,0.571224,-0.363138,-0.400366,0.592763,0.106077,-0.466595,-0.191877,0.278242,0.588831,0.064795,0.006567,0.081801,0.055312,-0.304169,-0.543269,-0.026800,-0.018315,-0.322033,-0.491319,-0.410371,-0.044236,-0.168576,-0.607502,0.812318,-0.388613,-0.030101,0.197359,0.149702,0.421009,0.197169,0.169196,-0.084251,-0.074356,0.353409,-0.149254,-0.315704,0.311742,0.033192,0.147584,0.185826,0.090416,-0.078024,-0.096789,0.662641,-0.198941,0.002048,-0.470038,0.358235,-0.159931,0.164853,0.066517,0.178695,0.110193,0.130624,0.118931,-0.063850,0.059633,0.223586,0.045423,-0.811512,-0.287455,0.144694,-0.043920,-0.517966,0.493181,-0.032108,-0.275188,0.290837,-0.212053,-0.137355,0.339660,0.425821,0.319723,-0.117180,-0.180166,-0.420592,0.093122,0.356278,-0.358340,-0.568289,0.455240,-0.425588,-0.582690,-0.165257,-0.412789,-0.373537,-0.047784,0.147610,0.123210,-0.251961,0.643758,-0.687066,0.011704,-0.286001,-0.158773,-0.025817,-0.216831,0.108640,-0.808391,-0.168711,-0.399901,-0.278208,-0.185771,0.127056,-0.459421,0.761436,-0.968749,0.005288,0.616801,0.230651,-0.222889,0.527042,-0.184359,0.268250,-0.200154,0.088797,0.264883,0.066331,0.410330,0.116437,0.545035,0.254825,0.055872,-0.417033,0.763595', '1420088', '1793491', '2369613', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2364982', '狱中豪杰', '喜剧', '居住在洛杉矶的斯坦·明顿（罗伯·施奈德 Rob Schneider 饰）是一名巧舌如簧、事业有成的房地产商人。他张狂无度，满嘴大话，最终不可避免地卷入一场诈骗案，面临着为期3年的牢狱之灾，而他所去的正是一所臭名昭著、以暴力著称的监狱。不过在此之前，斯坦还有6个月的自由时间。本来心情无比烦躁，还和女友敏迪（珍妮弗·莫瑞森 Jennifer Morrison 饰）闹出不快。为了防止在狱中被人强暴，斯坦开始拜师访友，修炼武功，期间更得到一名神秘武师（大卫·卡拉丁 David Carradine 饰）的指导。六个月时间转瞬即逝，斯坦终于迎来服刑的重要时刻。他将成为人人得而上之的公共汽车？还是打遍监狱无敌手的风云人物？答案即将揭晓……©豆瓣', '罗伯·施奈德', '罗伯·施奈德', 6.9, 15278, 'tt0490086', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2539263819.jpg', 1.2, 6.6, 48.4, 32.8, 11, '0.016874,0.051532,-0.605534,0.490372,-0.093576,-0.282818,0.623802,0.196201,-0.580186,-0.293779,0.228814,0.345701,-0.304048,0.253492,0.539202,-0.146954,-0.378479,-0.396269,0.059902,-0.242365,-0.154920,-0.370597,-0.149698,0.089624,-0.021933,-0.323888,0.412930,0.221837,-0.057076,0.343309,0.316988,0.417133,0.156312,0.388306,-0.090615,-0.332113,0.247702,-0.149881,-0.114633,0.278975,0.088048,-0.361977,-0.213961,-0.016136,0.022507,0.305043,0.417559,0.021483,-0.066437,-0.058618,0.442269,-0.383485,-0.254989,0.052218,0.240167,-0.100263,0.281761,0.172265,-0.235606,0.034191,0.079304,-0.330333,-0.780916,0.136891,0.064012,0.059600,-0.343719,0.402684,-0.140044,0.059843,-0.077714,-0.517631,-0.172545,0.394855,0.144108,0.307099,-0.180694,-0.023559,-0.648785,0.226823,0.822478,-0.097625,-0.134732,0.048125,0.252870,-0.417522,0.175778,-0.618491,-0.319285,-0.104059,0.200895,-0.208959,-0.085858,0.363264,-0.334611,0.063350,-0.455367,-0.299318,0.062575,-0.051558,-0.117662,-0.609477,-0.017059,-0.186355,-0.307821,-0.085263,0.245741,-0.379693,0.621704,-0.768519,0.400682,0.521627,0.163896,-0.275292,0.500179,0.095136,0.228596,-0.138800,-0.248443,0.324715,0.265009,0.338753,0.021193,0.324217,-0.035215,-0.355605,-0.128232,0.550105', '1793491', '1870682', '1877596', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2365079', '异国色恋浪漫谭', '动画', '近江鸾丸是日本黑帮近江组的少主，奉家族之命与吉原组的大小姐熏结婚。两人在前往意大利的豪华游艇中举行婚礼，在新婚之夜，并不相爱的二人发生了争吵。鸾丸被熏赶出房间后，独自一人在吧台借酒消愁。这时，另一个黑帮组织伺机挑衅鸾丸，混乱中一个意大利美男子亚尔出手相助。在一场打斗后，鸾丸和亚尔二人惺惺相惜，随后相约喝酒聊天。酒后二人却发生了关系……第二天醒来鸾丸要离开游艇了，他才发现原来温柔英俊的亚尔是游艇的船长……之后两人在意大利再度重逢，这时鸾丸却被卷入了麻烦的事件中，亚尔会不会出现……©豆瓣', '诹访部顺一', '大谷肇', 7.5, 10717, 'tt6103384', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2503152838.jpg', 0.5, 3.5, 34.3, 41.8, 20, '0.377275,0.496371,-0.862496,0.478665,0.102316,-0.101124,0.872303,0.220783,-0.559612,0.020161,0.273997,0.868219,-0.268024,0.048062,0.628372,0.094700,-0.147490,-0.914021,-0.063256,-0.120421,-0.374137,-0.389523,0.126276,0.178151,-0.099352,-0.333856,0.132669,0.039483,0.104633,0.733020,0.343623,0.246106,-0.393219,0.596480,0.250289,0.019334,0.196584,0.153895,-0.264168,0.423816,-0.192346,-0.337972,-0.218016,-0.021440,0.376712,0.087201,0.567298,-0.192415,-0.161170,-0.397824,-0.156494,0.141037,-0.168842,0.309877,0.473988,-0.126214,0.377697,0.235661,-0.342787,-0.215220,-0.233221,0.451820,-0.440208,0.529234,-0.179563,0.107361,-0.462083,0.679017,-0.047596,0.027695,0.065562,0.085923,0.494737,0.852497,0.317390,0.210914,0.048032,0.143934,-0.828358,-0.322137,0.997424,-0.068032,0.131552,0.375708,-0.001287,-0.132399,0.138411,0.087110,-0.056130,-0.095755,0.705907,-0.192057,-0.264417,0.243733,-0.565525,-0.002752,-0.310364,-0.213777,0.181491,0.196703,-0.138403,-0.818278,-0.070027,-0.360562,-0.233720,0.063218,-0.142471,-0.053367,0.467425,-0.929991,0.165818,0.207636,0.229002,-0.324675,0.693117,0.157175,0.217754,-0.180542,-0.141378,0.000674,-0.009971,0.248584,0.274589,0.552442,0.164365,0.026506,-0.504692,0.026740', '26687241', '11541282', '25721544', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2365260', '爱在暹罗', '剧情', 'Mew（Witwisit Hirunwongkul饰）和Tong（Mario Maurer饰）是一对小伙伴，一场悲剧却使二人不得不分开：Tong的姐姐阿红在一次野外旅行中不幸失踪，Tong的父母迅速决定离开这个伤心地。几年后，长大了的两人在曼谷广场意外重逢，此时，Mew是August乐团的创作加主唱，相依为命的嬷嬷去世后，他独自一人寂寞地生活。Tong的家庭也难现欢乐，爸爸因为过度思念死去的女儿，整日借酒浇愁。重逢后，时间就像是逆流回童年，两人重拾以往的亲密无间，还是无话不谈的朋友。渐渐的，一种新的情愫开始在两人心中滋生，派对上，Mew唱出他写的第一首情歌——为Tong而写的情歌，二人情不自禁亲吻了，不料这一幕却被Tong的妈妈尽收眼底……Tong和Mew的交往开始受到阻挠，二人陷入痛苦之中，亦因此得以重新审视这份感情。©豆瓣', '维特维斯特·海伦亚沃恩酷', '楚克·萨克瑞科', 8.3, 290040, 'tt1152282', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1024585648.jpg', 0.3, 1.5, 18.1, 41.8, 38.2, '0.286449,-0.134305,-0.802277,0.563428,0.143341,-0.574467,1.021292,0.058018,-0.837663,0.070295,0.211319,0.853500,-0.478575,0.708844,0.255723,-0.164793,-0.362888,-1.021199,-0.026022,-0.095699,0.032768,-0.219456,0.042906,0.011926,-0.154364,-0.234998,0.707515,0.128578,0.107613,1.003313,0.104947,0.083904,-0.316207,0.513837,-0.043778,0.172879,-0.137604,0.265206,-0.450645,-0.089849,0.297186,-0.234822,-0.191283,0.086189,-0.031782,0.206272,1.084203,-0.139876,-0.257184,0.030797,0.447406,-0.199481,-0.173388,0.071523,0.141761,0.259175,0.383862,0.131609,-0.356146,0.081626,-0.270695,0.060442,-0.446568,0.189581,0.127624,-0.009765,-0.501924,0.707443,0.124481,-0.171878,0.172791,-0.300470,0.204273,0.457354,0.456151,0.655477,-0.390965,0.053770,-0.023303,0.223266,0.981936,-0.241014,-0.125020,0.679945,-0.242452,-0.216218,0.016038,-0.028058,-0.542926,-0.048103,0.176043,0.291422,-0.222376,0.424570,-0.771356,0.039608,-0.318691,-0.135587,0.101288,-0.556577,-0.068653,-0.477820,-0.368987,-0.340822,-0.314461,0.077249,0.031690,-0.250770,0.689874,-0.829109,0.426965,0.162288,0.114393,-0.369505,0.476252,0.249135,0.117239,-0.147379,0.227727,0.462913,-0.422531,0.102836,0.160826,0.173895,-0.206212,0.484262,-0.746695,0.537283', '26687241', '1773217', '1301562', '1299433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2367213', '诈欺猎人', '剧情', '为了给家族复仇而追踪欺诈师御木本的黑崎（山下智久饰），接到了桂木（山崎努饰）的委托，消灭新的敌人，欺诈师石垣（竹中直人饰），通过赠送礼物来骗取他人的欺诈师。一直追踪黑崎的刑警神志名（哀川翔饰）与以大企业为目标的欺诈师白石（加藤浩次饰）也卷入了这场智力游戏之中。在调查过程中，黑崎发现石垣在与某个人物进行共谋。动摇日本经济的犯罪，巨大的诈骗事件在黑暗中酝酿。不顾吉川冰柱（堀北真希饰）的担心，黑崎向着真相前进。赌上性命的决斗，即将上演。©豆瓣', '山下智久', '石井康晴', 7.1, 17645, 'tt1159502', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p636649945.jpg', 1.2, 6, 43.1, 34.2, 15.5, '0.099783,0.032064,-0.357391,0.379024,-0.059411,-0.049707,0.461079,0.082112,-0.158129,-0.339776,0.360509,0.608249,0.144965,-0.018189,0.383351,-0.120985,-0.155960,-0.788412,-0.330953,-0.071527,-0.208846,-0.646674,-0.387458,-0.270998,-0.313044,-0.164224,0.948079,0.343441,-0.609498,0.276317,0.393293,0.474523,-0.417740,0.194836,0.332622,-0.038130,0.067015,-0.021730,-0.430867,0.322315,-0.363007,-0.443352,0.034287,0.135679,0.010850,0.414652,0.657283,-0.325507,0.006939,-0.372321,0.216434,-0.595515,-0.029376,0.108576,0.478967,0.044858,0.036614,0.151029,-0.334131,0.023876,-0.009845,-0.034379,-1.073351,-0.102705,0.114388,0.105181,-0.274255,0.299081,0.032463,-0.034933,0.432776,-0.111441,0.043191,0.533853,0.639578,-0.024625,-0.501536,0.044072,-0.073429,0.023910,0.505213,-0.244313,0.063649,-0.198639,0.008853,-0.355460,-0.064924,-0.281906,0.021563,-0.350325,0.273980,0.328577,-0.039959,0.477692,-0.759429,-0.258974,-0.145483,-0.073976,0.231906,-0.311072,-0.075747,-0.928816,0.063711,-0.247525,-0.114862,0.166434,0.369274,-0.414465,0.579705,-0.811171,0.152068,0.744025,0.242047,-0.451744,0.280884,0.040823,0.043310,-0.218739,-0.437663,-0.012537,0.439836,0.721451,0.141118,0.051560,0.065536,-0.102741,-0.390662,0.168389', '2369613', '27073234', '3861846', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2367243', '独奏者', '剧情', '史蒂夫·洛佩兹（小罗伯特·唐尼 Robert Downey Jr. 饰）是一名洛杉矶时报的记者，最近因为一次骑行意外而住进了医院。在病床上，他经常听见附近传来优美的小提琴声，从而结识了天才小提琴手纳萨尼尔·埃尔斯（杰米·福克斯 Jamie Foxx 饰），渐渐地他发现， 埃 尔斯原来曾进修于声名显赫的茱莉亚音乐学院，然而却因精神分裂症而辍学，如今只能流落街头卖艺为生。洛佩兹决意将埃尔斯的故事写成专栏，为此他开始留意埃尔斯的一举一动，在相互了解的过程中，两人渐渐建立了深厚友谊，洛佩兹为了帮助埃尔斯完成音乐梦想甚至抛家弃业，然而埃尔斯的精神疾病却始终是两人之间的羁绊……本片根据史蒂夫·洛佩兹发表在报纸上的文章进行改编。©豆瓣', '杰米·福克斯', '乔·赖特', 7.1, 10570, 'tt0821642', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p770805741.jpg', 0.8, 5.7, 44.2, 38.4, 10.9, '0.337788,0.035330,-0.609713,0.682668,0.206843,-0.360028,0.680212,0.178100,-0.743884,-0.265880,-0.018624,0.656941,-0.180858,0.306531,0.410567,-0.130991,-0.366331,-0.826382,0.234797,-0.116469,-0.163539,-0.523189,-0.276877,-0.245207,-0.266493,-0.367392,0.458425,0.174872,-0.232382,0.542682,0.194458,0.287445,-0.137471,0.238794,-0.038117,-0.023875,0.389488,-0.188652,-0.197100,0.167404,0.061842,-0.358559,-0.312757,-0.147999,0.116007,0.409713,0.434407,-0.001977,0.126557,0.144016,0.309313,0.136974,0.068406,0.005199,0.212051,0.104596,0.377337,0.331216,-0.179571,-0.065890,0.091214,-0.175898,-0.497162,0.151664,-0.047998,0.443741,-0.517050,0.518949,-0.388732,0.009660,-0.077282,-0.196095,-0.072144,0.202870,0.179292,0.260544,-0.135541,0.110319,-0.157594,0.035512,0.408055,0.092673,-0.219773,0.361531,-0.168411,-0.423671,-0.149122,0.053551,-0.374274,-0.127803,0.259535,-0.044965,-0.105595,0.355512,-0.415827,-0.146205,-0.279815,-0.285541,-0.045765,-0.143394,-0.094304,-0.939373,0.027096,-0.183835,-0.162383,-0.112990,-0.024944,-0.291859,0.622993,-0.785812,0.336378,0.564914,-0.105955,0.020373,0.537002,0.085956,0.241082,0.001577,-0.289758,0.475322,0.046204,0.212195,0.181901,0.173625,-0.005326,-0.131790,-0.351502,0.606734', '25723905', '1293656', '26259202', '1301172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2368587', '丑陋的真相', '喜剧', '艾比（凯瑟琳·海格尔 Katherine Heigl 饰）是同事眼中的完美女神，作为早间电视节目制作人的她不仅事业有成，而且还有着一张精致漂亮的脸蛋。但令同事们困扰的是，这样完美的艾比，年近三十却依然单身。只有艾比心里清楚，自己之所以单身，是因为心目中的那个完美先生还没有出现。作为艾比的同事，麦克（杰拉德·巴特勒 Gerard Butler 饰）对态度强硬的艾比产生了浓厚的兴趣，所以，当艾比邂逅了医生科林（艾里克·温特 Eric Winter 饰）并为之心动后，他主动提出要为她的恋情出谋划策。在麦克的帮助下，艾比的感情之路一帆风顺，但在这过程中，艾比发现自己对于麦克的感情渐渐地变得复杂起来。©豆瓣', '凯瑟琳·海格尔', '罗伯特·路克蒂克', 6.7, 28293, 'tt1142988', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265210238.jpg', 1, 7.7, 52.7, 30.8, 7.7, '0.218475,0.110735,-0.823592,0.657618,-0.243482,-0.463899,1.082368,0.137878,-0.597458,-0.317473,0.017774,0.377848,-0.215266,0.325108,0.343572,0.115615,-0.486376,-0.594309,-0.151789,-0.040384,-0.049993,-0.546833,-0.540588,-0.147579,-0.252015,-0.449930,0.289189,-0.078762,0.029096,0.532924,0.344379,0.273887,0.255960,0.403755,0.177481,-0.104627,0.234192,-0.077459,-0.367242,0.071836,0.088709,-0.033715,-0.174699,0.414218,-0.120734,0.446376,0.402404,-0.102328,-0.349818,0.165340,0.307365,-0.160363,0.209991,0.120307,0.087121,0.000149,0.294048,0.088972,-0.046863,-0.075873,0.188205,-0.067935,-0.931889,0.321178,0.053140,0.335144,-0.395337,0.465315,-0.504951,-0.210661,0.083959,-0.393226,-0.114708,0.200330,0.347292,0.317987,-0.220867,0.253824,-0.357115,-0.030601,0.522907,0.338364,-0.406546,0.322462,-0.470584,-0.596388,0.112025,-0.014707,-0.422201,0.093753,0.259030,0.167962,0.199759,0.353507,-0.563203,-0.073207,-0.320493,-0.138795,0.024786,-0.308065,0.000988,-0.506915,-0.179390,-0.615966,-0.494489,-0.214298,-0.023808,-0.540963,0.681194,-0.856416,0.415739,0.602480,0.206395,-0.255044,0.733163,0.210387,0.064092,0.017873,-0.467054,0.207266,-0.111669,0.098671,-0.018838,0.348625,0.329981,-0.298350,-0.314797,0.762008', '1417428', '3005387', '1304862', '35158375');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2368641', '情人节', '喜剧', '情人节，洛杉矶，花店老板瑞德（艾什顿•库彻 Ashton Kutcher 饰）向女友莫莉（杰西卡•阿尔芭 Jessica Alba 饰）求婚，对方欣然应允，他欣喜若狂地跟好友朱丽叶（珍妮弗•加纳 Jennifer Garner 饰）分享。而后者的医生情人却不能共度佳节， 所以她只能去陪闺蜜。小白领利兹（安妮•海瑟薇 Anne Hathaway 饰）跟男友乔什欢度春宵后，马上去做带班秘书。体育记者凯文（杰米•福克斯 Jamie Foxx 饰）临时被拉去做情人节的报道，他采访了瑞德，这使得后者店里的生意超好，宾客盈门，甚至还包括12岁的小男孩。后者的保姆正欲同男友初尝禁果，而爷爷、奶奶却在回首往事。他的母亲、美军上尉凯特（朱莉娅•罗伯茨 Julia Roberts 饰）却在飞机上与陌生人霍顿聊得火热。正在众人想方设法示爱的同时，橄榄球名将西恩（埃里克迪恩 饰）想要在此时宣布一个惊人的消息，所以他联系了高薪公关秘书卡拉（杰西卡•贝尔 Jessica Biel 饰）……', '朱莉娅·罗伯茨', '盖瑞·马歇尔', 7, 106184, 'tt0817230', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p466564944.jpg', 0.6, 5.3, 46.9, 37.4, 9.8, '0.219536,-0.179016,-0.457065,0.328310,-0.128222,-0.566281,0.705877,0.466884,-0.405008,-0.012785,0.287741,0.605966,-0.388268,0.289832,0.529062,0.369815,-0.650144,-0.681354,0.377126,0.024003,0.093776,-0.393184,-0.048049,-0.165727,0.026252,0.076491,0.155398,-0.613349,0.331566,0.527108,0.421106,0.099473,0.271527,0.522731,0.140083,0.175745,0.442933,-0.186411,-0.370448,0.177862,0.202098,0.060489,-0.293740,0.039117,0.408953,0.284410,0.337636,-0.078137,0.217196,0.011508,0.185213,0.153564,0.367216,0.249673,-0.006542,-0.036118,0.461325,-0.270971,-0.101988,0.033687,0.234076,0.146592,-0.075608,0.412466,-0.103560,0.248296,-0.329506,0.349052,-0.457724,0.189192,0.319806,-0.430467,-0.175997,0.320885,-0.019150,0.168091,0.065168,0.068808,-0.166948,0.502930,0.244272,0.375944,0.019159,0.299933,-0.219858,-0.338899,0.002983,0.373680,-0.682091,0.005739,0.449479,-0.081240,0.126091,0.244071,-0.547543,-0.414289,-0.318511,-0.022594,-0.042666,-0.287075,-0.174230,-0.928788,0.153254,-0.241421,-0.232401,-0.120088,0.283020,0.036598,0.480802,-0.721463,0.111325,0.601288,0.295964,-0.182226,0.571538,0.046642,0.144527,-0.418150,-0.129860,0.255294,-0.110114,0.220646,0.193405,0.371275,0.230385,-0.1552