INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2369549', '公众之敌', '剧情', '本片改编自真实事件。1933年，江洋大盗约翰•迪林格（约翰尼•德普 Johnny Depp 饰）与同伙约翰•汉密尔顿（杰森•克拉克 Jason Clark 饰）持械劫狱，从印第安纳州监狱中成功救出抢劫团伙成员，包括“漂亮男孩”弗洛伊德（查宁•塔图 Channing Tatum 饰），“娃娃脸”尼尔森（斯蒂芬•格拉汉姆 Stephen Granham 饰）等，并藏身腐败警察马丁（约翰•迈克•鲍格 John Michael Bolger 饰）的农宅。马丁说服迪林格藏身芝加哥，寻求黑帮保护。在一系列银行抢劫活动中，迪林格爱上了芝加哥女职员比莉•弗雷凯特（玛丽昂•歌迪亚 Marion Cotillard 饰）。与此同时，联邦调查局探员茂文•普维斯（克里斯蒂安•贝尔 Christian Bale 饰）被上司胡佛局长（比利•克鲁德普 Billy Crudup 饰）提升，在美国第一次“打击犯罪战”中誓将迪林格捉拿归案。行动中，随着迪林格的势败，联邦调查局却日益壮大……', '约翰尼·德普', '迈克尔·曼', 7.4, 64551, 'tt1152836', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p825100239.jpg', 0.5, 3.9, 35.4, 44.3, 15.8, '0.238470,-0.186159,-0.357371,0.182359,0.128303,-0.370423,0.633560,0.183923,-0.493242,-0.365620,0.175805,0.363873,-0.245859,-0.204389,0.440124,0.284763,-0.882675,-0.559767,0.052201,-0.099605,-0.042501,-0.714902,-0.501291,-0.372043,-0.005265,-0.303985,0.267874,-0.102965,0.035110,0.543994,0.301222,0.769014,-0.100732,-0.085681,0.366085,0.007785,0.818441,-0.629628,-0.463053,0.236514,-0.066081,0.019668,-0.103133,-0.069198,0.267631,0.372565,0.349475,-0.436106,0.375344,-0.179877,-0.035913,-0.101152,0.010023,0.124047,0.340187,-0.335915,0.115345,0.525450,-0.143525,0.010204,0.189222,-0.121864,-0.210064,0.306246,-0.024248,0.350312,-0.245546,0.039964,-0.478385,0.398403,0.217358,-0.029852,-0.175201,-0.032506,0.125434,0.026715,0.183558,-0.033156,-0.355530,0.042060,0.079920,-0.202856,0.028397,-0.287359,-0.281517,-0.378304,0.044171,-0.013910,-0.268793,-0.182756,0.423884,-0.353754,0.265350,0.275704,-0.381917,-0.265360,-0.732457,0.104324,-0.268685,0.066029,-0.082554,-1.062539,-0.133960,0.041551,0.015772,-0.224611,-0.173548,0.074258,0.159019,-0.487946,0.163048,0.669058,0.194154,0.031148,0.205029,-0.241700,0.265259,-0.462034,-0.321419,0.392832,0.602922,-0.057075,0.071381,0.199343,0.0419