INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2369613', '火影忍者疾风传剧场版：羁绊', '动作', '某日，一群使用风遁之术的空忍空袭火之国，无数民众和忍者遇害，形势危急。据纲手大人所言，这群不速之客正是在第二次忍者大战中落败的空之团，如今他们怀着复仇之心再次出现。卡卡西（井上和彦 配音）等人则负责侦查空之团的老巢，鸣人（竹内顺子 配音）、小樱（中村千绘 配音）、雏田（水樹奈々 配音）受命组成三人医疗小队，协助名医神农（石塚運昇 配音）前往其徒弟雨琉的家乡医治伤者。另一方面，病入膏肓的大蛇丸得知神农的再生之术业已完成，他命佐助（杉山纪彰 配音）前去寻找神农。这也促成佐助和昔日伙伴宿命的重逢……本片为《火影忍者》第五部剧场版动画。©豆瓣', '竹内顺子', '龟垣一', 7.2, 11066, 'tt1160524', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p699505407.jpg', 1.1, 5.4, 41.4, 34.9, 17.2, '-0.182737,-0.333403,-0.155097,0.383160,0.178375,-0.199182,0.061623,-0.042650,-0.124471,-0.700568,0.332571,0.490115,0.256190,0.131585,0.252503,-0.232966,-0.399421,-0.369736,-0.256752,-0.018460,-0.123080,-0.131442,0.055193,-0.164344,-0.206774,-0.343720,1.031140,0.029089,-0.059174,0.480153,0.079123,0.519873,-0.587242,-0.059113,0.267005,0.263478,0.022666,-0.130100,-0.317735,0.514716,-0.277108,-0.102429,-0.260866,0.081400,-0.096034,0.339868,0.722333,-0.231116,0.028267,-0.441016,0.249051,-0.421638,0.031267,0.023655,0.395766,0.093122,0.100091,0.116828,0.030427,-0.038163,-0.517214,-0.053458,-0.831399,0.050368,0.102045,0.009721,-0.097145,0.047525,-0.159142,0.062160,0.238732,-0.353955,0.086580,0.447022,0.220286,0.056617,-0.475957,0.156568,0.074801,0.154550,0.549009,-0.291872,0.271016,-0.062525,0.195041,-0.386106,0.010035,-0.113804,-0.054956,0.103669,0.178879,-0.014277,0.093477,0.265465,-0.314434,-0.120308,-0.265239,-0.050372,0.112647,0.131132,0.126230,-1.280589,0.286561,0.053563,-0.149358,-0.085612,0.295826,-0.280222,0.885516,-0.880571,0.009946,0.461773,0.097709,-0.291141,0.246868,0.038800,0.205495,-0.417740,-0.288091,0.225934,0.227442,0.403795,0.195981,0.168017,0.209379,0.154242,-0.493886,-0.186930', '3861846', '20274039', '25723905', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2369618', '花样男子最终章', '剧情', '几经风雨，道明寺（松本潤饰）和杉菜（井上真央饰）这对欢喜冤家的爱情终于开花结果，婚讯传出后，立刻成为全世界瞩目的焦点新闻。可就在新人成婚前夕，意外陡生，道明寺家的传世宝石皇冠——维纳斯的微笑突然遭歹人掠夺，这本是送给新人的结婚礼物，因担心母亲发怒，道明寺决定带着杉菜独自去寻找皇冠的下落。皇冠在拉斯维加斯和香港忽现踪迹，嫌疑人鏑木（藤木直人饰）登场，他的身后似乎隐藏着一个庞大的黑暗集团，道明寺和杉菜合二人之力，也终究难以匹敌……就在真相愈加扑朔迷离之际，F4其余三人花泽类（小栗旬饰）、西门（松田翔太饰）、美作（阿部力饰）重新聚集起来，与道明寺、杉菜共同与强大的敌人展开战斗，无敌组合F4又将重现辉煌！©豆瓣', '井上真央', '石井康晴', 7.3, 20479, 'tt1160539', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p724334774.jpg', 0.7, 5.7, 39.1, 34.3, 20.1, '0.026148,0.114750,-0.648616,0.431671,0.087001,-0.312940,0.628867,0.274702,-0.421731,-0.186785,0.042848,0.775578,-0.195526,0.271342,0.276968,0.072514,-0.309309,-0.736808,-0.068248,0.071404,0.142760,-0.307947,-0.235456,0.079361,0.097568,-0.156017,0.589823,0.280306,-0.235634,0.661513,0.536498,0.268785,-0.579506,0.493330,-0.015449,-0.068296,0.156514,0.393118,-0.374847,0.257703,-0.371774,-0.404605,-0.122399,0.332157,-0.113715,-0.137863,0.244649,-0.259679,-0.011336,-0.088329,0.236526,-0.259149,-0.192090,0.304977,0.267131,-0.052788,0.042801,0.069838,-0.344754,-0.042773,0.105811,0.035966,-0.820995,0.195237,0.124991,0.122268,-0.297819,0.469136,-0.142132,-0.179126,0.467399,-0.293889,0.200332,0.477733,0.376019,0.091401,-0.291748,0.220380,-0.330214,0.005265,0.542528,0.066484,-0.081389,-0.025303,0.106573,-0.283721,-0.362342,-0.079035,-0.215908,-0.158936,0.569223,0.420936,0.147001,0.331099,-0.564842,-0.146842,0.013972,-0.131727,0.128199,-0.416819,0.002984,-0.749351,-0.130459,-0.495690,-0.396586,0.262053,0.266117,-0.189896,0.660044,-0.580919,0.226320,0.384444,0.296440,-0.338753,0.309174,0.019673,0.086638,-0.217352,-0.162545,0.147611,0.081402,0.425308,0.124641,0.086259,-0.029458,0.205125,-0.496809,0.387565', '4301278', '25928048', '11541282', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2369845', '嫌疑人X的献身', '剧情', '天才物理学家汤川学（福山雅治 饰）此次又受内海薰（柴崎幸 饰）所托，调查一件不可思议命案。受害人富樫慎二被发现死在河边，面目指纹尽毁。最大的嫌疑人是他的前妻花冈靖子（松雪泰子 饰），然而靖子却有着完美的不在场证明。一个人能够同一时间出现在不同地方吗？当汤川发现住在靖子隔壁的是当年的大学同学、同为天才的数学家石神哲哉（堤真一  饰）时引起兴趣。毕业后因要照顾父母没有留校反而去高中教数学、一直生活得很落魄的石神每晚利用公用电话教靖子如何应对警察追查，靖子渐渐感到被束缚，但是由于给出的口供毫无可疑之处，警察决定放弃对靖子的调查，这时汤川却指出石神是关键人物。案件的真相如何？世界上真有一个人同时出现在两个地方的事情吗？本片改编自日本人气推理小说家东野圭吾06年的直木奖获奖作品。©豆瓣', '福山雅治', '西谷弘', 8.4, 203229, 'tt1160629', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p698531629.jpg', 0.2, 0.9, 13.9, 50.4, 34.6, '0.217496,-0.243353,-0.485500,0.446067,-0.061925,-0.102694,0.405993,0.016795,-0.662190,-0.625120,0.048306,0.574090,-0.277525,0.152024,0.015318,-0.071036,-0.239803,-0.569839,0.159719,-0.298927,-0.482738,-0.485322,-0.011371,-0.099928,-0.152531,-0.194273,0.624922,0.113976,-0.089684,0.213524,0.155415,0.467835,-0.204456,0.321452,0.008067,-0.116558,0.091857,0.201481,-0.006987,0.274422,-0.095013,-0.202548,-0.220388,0.159488,-0.183829,0.381924,0.475528,-0.099243,-0.368018,-0.037350,0.420417,-0.360552,-0.133909,0.078227,0.482899,-0.234764,0.161326,0.339386,-0.282058,-0.116417,0.205882,-0.025451,-0.609281,-0.041890,0.360539,0.380723,-0.321600,0.158595,-0.199086,-0.168475,-0.007934,-0.272298,0.192348,0.265552,0.337314,0.240591,-0.104604,0.086259,-0.350713,0.118530,0.709332,0.017619,-0.078783,0.141504,-0.123008,-0.425398,-0.069709,-0.209843,-0.309471,0.357951,-0.042437,0.206973,-0.156250,-0.009276,-0.126566,-0.228868,-0.067981,0.054869,0.016098,-0.358817,-0.151022,-0.499116,-0.044100,-0.136393,-0.355849,0.122975,0.199819,-0.473294,0.658747,-0.896086,-0.015213,0.431529,0.137647,-0.366470,0.632827,0.021522,-0.109618,-0.209799,-0.205674,-0.062036,0.285750,0.181857,-0.070519,0.185656,-0.048351,-0.423715,-0.285821,0.085433', '35030151', '1870682', '1395231', '26280710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23712401', '当男人恋爱时', '爱情', '太逸（黄政民 饰）是一名帮高利贷讨债的小混混，人到中年的他不仅没有份正经的工作，甚至连个住的地方都没有，寄宿在开美发店的哥哥英逸（郭道元 饰）家。太逸有着自己的人生哲学，那就是借出去的钱一定得要回来。大大咧咧的他完全不懂得如何尊重女性，亦和浪漫的爱情故事无缘。某日，在去讨债的途中，太逸邂逅了名为周皓婷（韩惠珍 饰）的美丽女子，那一瞬间，太逸懂得了什么叫一见钟情。然而，太逸并不能给予周皓婷她所想要的生活，第一次，太逸决定为了自己之外的人做出改变。然而，面对两人之间巨大的悬殊，太逸能够坚持他的感情吗？与此同时，接二连三发生的意外亦让太逸的生活陷入了麻烦之中。©豆瓣', '黄政民', '韩东旭', 8, 70264, 'tt3479250', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2167306070.jpg', 0.3, 2.2, 24.3, 45.4, 27.8, '0.352794,0.027786,-0.818636,0.641010,-0.455937,-0.362279,0.680613,0.111328,-0.361039,-0.392269,0.115717,0.501947,0.271543,0.113247,0.173422,0.061627,0.038215,-0.481977,-0.046546,-0.156794,-0.238734,-0.433123,-0.248361,-0.087024,-0.225327,-0.109069,0.429755,0.077142,-0.233565,0.207819,0.345395,0.152552,0.075201,0.543241,-0.263661,-0.095151,-0.207911,0.324397,-0.310523,0.145729,0.196016,-0.181412,-0.179357,0.328386,-0.016766,0.339505,0.446857,-0.299948,-0.319037,0.193839,0.369999,0.071851,0.125300,0.229481,-0.016919,-0.163721,0.315702,0.154630,-0.308357,0.085605,0.343390,0.012428,-0.848375,0.124990,0.219366,0.176148,-0.538064,0.644463,0.088426,-0.201290,0.035601,-0.272060,0.166168,0.404593,0.474881,0.357811,-0.272725,-0.053671,-0.540727,0.187980,0.919748,0.141852,-0.389672,0.535498,-0.390534,-0.353259,-0.074224,-0.435607,-0.480206,0.192683,0.067287,0.206434,-0.378119,0.089151,-0.394890,-0.056355,0.042861,0.062284,-0.027682,-0.462505,-0.114395,-0.321900,-0.139637,-0.600405,-0.305297,0.078400,0.162859,-0.278551,0.657569,-0.907697,0.214877,0.561100,0.399462,-0.590567,0.845907,0.222644,-0.012514,-0.042225,-0.153780,-0.021904,-0.017603,0.238969,0.116396,0.130394,0.158796,-0.134220,-0.104901,0.437089', '1308805', '1303112', '1877596', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23712691', '优雅的谎言', '剧情', '贤淑（金喜爱 饰）靠着在超市工作所得的微薄收入艰难抚养着两个女儿万智（高智星 饰）和天智（金香奇 饰），两个女孩虽然身为姐妹，却拥有着截然相反的性格。万智个性孤僻而叛逆，和家人之间关系十分冷淡；天智则乖巧可爱，常常想着法子逗妈妈开心。让贤淑和万智没有想到的是，乐观开朗的天智竟然在某一日选择了结束自己的生命，这一噩耗犹如一道晴空霹雳打响在贤淑一家人的头顶之上，使得本就辛苦的生活变得更加举步维艰。然而，即便如此，贤淑和万智还是坚强的维系着正常的生活。一次偶然中，万智意外的得知了有关妹妹生前的一些讯息，这些讯息让她明白了妹妹真正的死因和竭力隐藏的某个秘密。©豆瓣', '金喜爱', '李翰', 7.5, 14752, 'tt3837154', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2171002420.jpg', 0.4, 3.4, 33.9, 45.5, 16.7, '0.250274,0.157519,-0.655698,0.752057,-0.236156,-0.208282,0.738363,0.263323,-0.745365,-0.245202,0.086403,0.633583,0.056115,0.128076,0.071751,-0.003828,-0.068168,-0.465794,-0.110323,0.039642,0.173973,-0.685110,-0.265198,0.115746,-0.076194,-0.609952,0.308215,0.046547,-0.087726,0.696085,0.204003,0.212784,-0.240281,0.297832,-0.267727,-0.131896,-0.209076,0.359059,-0.213923,0.007780,0.097028,0.028929,-0.150281,0.281587,0.088177,0.449755,0.626439,-0.266678,-0.517336,0.051176,0.416058,-0.054808,-0.218474,0.231620,0.274982,-0.002047,0.516033,0.251964,-0.429049,0.068028,0.172911,-0.079747,-0.908301,-0.012032,0.389697,0.167872,-0.590753,0.382675,0.130998,-0.224931,0.192847,-0.602513,0.192888,0.479916,0.139246,0.583132,-0.383426,0.323353,-0.345217,0.088034,0.833050,0.090324,-0.396343,0.626604,-0.275498,-0.117160,0.137769,-0.412258,-0.571050,0.069950,0.073399,0.112108,-0.083789,0.330350,-0.418118,0.251512,-0.047379,0.134524,0.103474,-0.654969,-0.138714,-0.304912,-0.159786,-0.659724,-0.517481,0.140095,-0.161092,-0.250370,0.988954,-0.969056,0.256635,0.326952,0.171172,-0.484969,0.534089,0.383316,0.147652,-0.233122,0.039941,0.063779,0.003705,-0.250690,-0.074167,0.214412,-0.273832,-0.135022,-0.492739,0.362065', '26283288', '24284209', '35030151', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2371875', '那个男人的书198页', '剧情', '198。这个看上去毫不特殊的数字对于俊伍（李东旭 饰）而言，却是解密前女友离去的密码。曾经相爱的恋人突然离自己而去，只留下了“198页”这唯一的线索。想要破解其中奥秘的俊伍只得每天去图书馆翻找各类书籍，寻找第198页的秘密。而这怪异的行为引来了刚失恋的图书管理员恩秀（柳真 饰）的注意。起初，她只觉得俊伍是个怪人，但当她知道事情的缘由后，她开始自告奋勇的帮起俊伍一起寻找198页。在寻找的过程中，二人又回到了各自甜蜜的往昔，可越是甜蜜的回忆，越是萧瑟的当下。随着俊伍和恩秀接触的深入，二人开始被对方所吸引，那份失去爱人的心似乎又开始激烈跳动起来，再次为一个人所心动……©豆瓣', '柳真', '金正权', 6.8, 5379, 'tt2663738', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p720718159.jpg', 0.8, 7.2, 51.3, 32, 8.8, '0.664179,0.039726,-0.845134,0.743975,0.128310,-0.355831,0.811826,-0.096534,-0.552496,-0.281371,-0.040643,0.588126,-0.158561,0.238611,0.028019,0.279400,-0.381659,-0.667779,-0.041597,-0.407147,-0.286024,-0.396682,-0.247667,-0.254773,0.027351,-0.040914,0.564624,0.302114,-0.270595,0.461187,0.249591,0.267676,-0.183709,0.733325,-0.257517,0.085414,-0.028292,0.143334,-0.033985,-0.127465,0.312836,-0.275427,-0.264314,0.180650,-0.192936,0.569241,0.783102,-0.351154,-0.273737,0.211636,0.553488,-0.014104,-0.176870,0.087145,0.084064,0.347265,0.280934,-0.010697,-0.336024,0.323755,0.063782,0.088787,-0.808119,-0.134999,0.186089,0.289513,-0.305923,0.188402,-0.151506,0.032373,0.318018,-0.247670,0.261560,0.441553,0.304002,0.294643,-0.373782,-0.268098,-0.273430,0.152377,0.598305,0.160730,-0.035743,0.613332,-0.168114,-0.442678,-0.067902,0.001966,-0.082212,-0.053627,0.307445,0.710925,-0.030461,0.101081,-0.872700,0.148575,0.039537,-0.234899,-0.071591,-0.711470,-0.334262,-0.391476,-0.455968,-0.216767,-0.312124,0.072147,0.015264,-0.499605,0.827836,-0.695691,0.216471,0.561547,0.101774,-0.564694,0.567790,0.245310,-0.058219,-0.284990,-0.089081,0.380236,-0.095147,0.505811,0.075511,0.386992,0.008958,-0.128409,-0.556083,0.509234', '2053515', '25774050', '3262091', '35131347');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2372389', '草叶', '剧情', '倍受学生爱戴，事业如日中天的古典哲学教授比尔·金凯德（爱德华·诺顿 Edward Norton 饰）听闻自己孪生兄弟布雷迪（爱德华·诺顿 饰）的死讯后匆忙赶回奥克拉荷马州的老家，塔尔萨市的小迪克西镇。布雷迪的好友博尔格（提姆·布莱克·内尔森 Tim Blake Nelson 饰）负责接机，到家后发现布雷迪并未中弩箭而亡。比尔虽然气愤，但仍同意翌日去养老院看望十几年都没见面的母亲（苏珊·萨兰登 Susan Sarandon 饰）。布雷迪带比尔参观自己设计组装的第七代无土水栽优质大麻，并介绍他认识了当地中学的英语老师珍妮特（凯丽·拉塞尔 Keri Russell 饰）。就在比尔打算返回学校之际，他得知自己竟被卷入一起犹太毒枭（理查德·德莱福斯 Richard Dreyfuss 饰）谋杀案……©豆瓣', '爱德华·诺顿', '蒂姆·布雷克·尼尔森', 7.5, 14911, 'tt1151359', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2154240655.jpg', 0.4, 3.1, 34.5, 47.3, 14.6, '0.404323,-0.329895,-0.704574,0.190172,0.207626,-0.719204,0.311114,0.264811,-0.449266,-0.599633,-0.155480,0.757653,-0.023692,0.225918,0.296966,0.232345,-0.643125,-0.421714,0.237355,-0.296139,0.058232,-0.663641,-0.101401,-0.291892,0.133155,-0.484024,-0.108718,-0.197066,0.107012,0.707531,0.102772,0.436419,-0.055408,0.222636,0.078586,0.240130,0.618463,-0.152506,-0.245491,0.085302,0.071370,0.184612,-0.106017,0.073180,0.534309,0.420797,0.279671,-0.151514,0.379104,-0.067822,0.072213,0.022159,0.169499,0.114021,0.481152,-0.200734,0.002005,0.231061,-0.270240,-0.074959,0.183924,-0.138971,-0.213694,0.228058,-0.054537,0.250507,-0.499296,0.447176,-0.384035,-0.095557,0.010962,-0.370401,0.009376,0.200353,0.089823,0.162821,0.293093,0.029438,-0.194378,0.187552,0.310351,-0.145234,-0.061578,-0.053511,-0.316245,-0.141793,0.348955,0.013890,-0.544566,-0.196537,0.561979,-0.033007,0.238514,0.281641,-0.243345,-0.343952,-0.763490,-0.091722,0.046213,0.138743,0.074318,-0.988184,-0.048692,-0.150033,-0.026769,-0.201395,0.032810,0.006323,0.170553,-0.643958,0.295609,0.198097,0.240118,0.015920,0.178522,-0.129369,0.177226,-0.282583,-0.170130,0.520129,0.421850,0.023950,0.021463,0.323095,0.272315,-0.466564,-0.087579,0.411740', '1293572', '2075345', '6517421', '2034997');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2372586', '关于史蒂夫的一切', '喜剧', '玛丽（桑德拉·布洛克 Sandra Bullock 饰）是一个字谜游戏编撰者，她聪明漂亮却拙于社交，忧心她终身大事的父母一直为她安排各种相亲。本来不抱什么希望的玛丽，面对相亲对象史蒂夫（布莱德利·库珀 Bradley Cooper 饰）的英俊与才情，顿时沦陷。她滔滔不绝地对史蒂夫谈论自己的字谜工作，早觉枯燥的史蒂夫找了借口摆脱了她。玛丽在编撰一个“关于史蒂夫的一切”的字谜时，被上司发现而炒了鱿鱼。但是玛丽却认定了史蒂夫就是自己的灵魂伴侣，于是紧追史蒂夫不放。她在史蒂夫同事的鼓励下，跟随史蒂夫的新闻摄制组周游全国报道新闻。在跟随一次矿井塌陷新闻报道时，玛丽掉进陷塌的矿井中，她意外地发现井底下还遗漏了一个男孩，玛丽想尽各种办法拯救了男孩，并将功劳让给了别人。她的勇敢与智慧获得了史蒂夫的另眼相看，玛丽用她自己独特的方式赢得了大家的喜爱。©豆瓣', '桑德拉·布洛克', '菲尔·特雷尔', 6.4, 11130, 'tt0881891', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p648800207.jpg', 2.9, 14.2, 51, 25.2, 6.8, '0.337925,0.084767,-0.587850,0.509187,-0.346513,-0.293539,0.604263,0.061582,-0.391512,-0.066685,0.182819,0.766251,-0.349939,0.195357,0.098327,0.266402,-0.428855,-0.762321,0.161248,0.135928,-0.169004,-0.502168,-0.263606,-0.467139,-0.100887,-0.205087,0.438109,0.054465,-0.193538,0.170899,0.203008,0.158364,0.243764,0.697935,-0.040897,0.169332,0.092867,-0.175046,-0.031418,0.176167,0.163978,-0.356271,-0.250887,0.472364,-0.098152,0.483718,0.588523,-0.235765,-0.125180,0.030545,0.359155,-0.397367,0.148732,0.220747,0.028156,-0.142494,0.030818,0.226420,-0.075283,-0.084495,0.196094,0.016317,-0.703222,-0.248162,-0.020323,0.240704,-0.600323,0.375204,-0.323201,0.050533,-0.026468,-0.361548,-0.009181,0.071382,0.280986,0.176376,-0.201436,0.073566,-0.256987,0.255895,0.413362,0.117920,-0.086644,0.487712,-0.413527,-0.405322,0.021751,0.044535,-0.574635,-0.045374,0.432372,0.042555,-0.155842,0.023514,-0.571815,-0.181684,-0.253645,-0.335686,-0.151369,-0.558122,-0.177066,-0.440563,-0.050119,-0.255503,-0.400718,-0.329510,0.018251,-0.315243,0.692532,-0.625620,0.059646,0.685053,0.035565,-0.507502,0.644523,0.096013,0.017295,-0.181762,-0.102113,0.102436,-0.148622,0.171262,0.179556,0.394025,0.185257,-0.216465,-0.550404,0.646756', '30162520', '24733428',