INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2375763', '漂浪青春', '剧情', '妹狗，八岁的女孩每日要带盲女歌手姐姐菁菁（房思瑜 饰）去茶室卖唱，新乐手竹篙（赵逸岚 饰）虽是女性，可从打扮到做派都是男性的模式。妹狗对竹篙萌生了朦胧的情意，可是竹篙爱的却是姐姐。水莲（陆奕静 饰），年轻时选择和Gay阿彦结婚来掩人耳目，垂垂老去时，伴侣阿海已经不在人世，这时罹患艾滋病又遭遇爱人背叛的阿彦投靠她这法定的老妻。水莲此时却将阿彦误认为阿海，要他留在自己身边……竹篙，青春的年纪，她却只愿意和女人气的男生阿彦来往。发育的胸部令人气恼，向女生表白又被拒绝。直到遇见夜市舞台上光彩照人的水莲时，竹篙才确定了一些事情……©豆瓣', '赵逸岚', '周美玲', 7.5, 13289, 'tt1161444', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p585407890.jpg', 0.8, 4, 33, 44.3, 17.9, '0.022120,-0.081956,-0.484009,0.210288,-0.411013,-0.429251,0.851107,0.268395,-0.385176,-0.020583,0.307787,0.651605,-0.025886,0.283329,0.071097,0.416662,-0.189523,-0.757786,0.100846,-0.036661,-0.325510,-0.089871,0.110100,0.153479,-0.117029,-0.147523,0.502840,-0.153386,-0.316957,0.481513,0.377121,-0.026592,-0.108984,0.599521,-0.357201,0.033531,-0.034768,0.074060,-0.020672,0.076097,-0.017178,-0.250785,-0.307810,0.059599,-0.164299,0.422956,0.707766,0.030228,-0.102252,-0.109553,0.278505,-0.006602,0.017589,0.252575,0.294444,-0.088851,0.220626,-0.063222,-0.119177,0.026639,-0.084259,-0.041845,-0.208308,0.240230,0.134730,0.142047,-0.740500,0.377969,-0.117003,-0.220246,0.113336,-0.356456,0.112023,-0.046706,-0.105593,0.313355,-0.196955,0.120421,-0.515755,0.169314,0.525618,0.287505,0.079070,0.606614,-0.293444,-0.462128,-0.149739,-0.117423,-0.494310,0.044680,0.076445,-0.060275,-0.231409,0.043621,-0.409166,-0.101615,-0.077859,0.122293,0.105169,-0.380429,-0.195741,-0.089635,-0.015313,-0.570991,-0.352052,0.199286,0.251052,-0.145500,0.722341,-0.747553,0.132036,0.603618,0.288813,-0.467987,0.768825,0.249994,-0.008495,-0.208947,-0.153934,0.205414,-0.279211,0.190279,0.052905,0.284770,-0.049907,-0.078958,-0.543136,0.277876', '1302384', '3111650', '2081098', '1783772');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2375792', '樱花盛开', '剧情', '鲁迪（艾尔玛·韦伯 Elmar Wepper 饰）和杜莉（汉娜萝蕾·艾尔斯纳 Hannelore Elsner 饰）是一对相濡以沫的老夫妻，但噩耗突然来临，杜莉得知鲁迪已经身患癌症且无救治希望，于是暗自隐瞒实情，说服他一同回到柏林，完成他长久以来的心愿。到了柏林的两位老人发现子女已经有了自己的忙碌生活，根本无暇顾及他们二人，于是其意去波罗的海度假，不料二人刚到达目的地住进旅馆的第二天，杜莉却在睡梦中去世了。伤心的鲁迪决定独自完成妻子未偿的心愿，他来到东京，看到杜莉一直向往的樱花盛开和富士山，并认识了一位年轻的传统舞者优（入月彩 饰），由她带他寻找杜莉曾经的日本舞梦想……©豆瓣', '艾尔玛·韦伯', '多丽丝·德里', 8.5, 6490, 'tt0910559', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p675084528.jpg', 0.2, 1.4, 12.5, 42.8, 43.1, '0.116544,-0.114611,-0.782624,0.181811,-0.111687,-0.434938,0.632245,0.113067,-0.457615,-0.395666,0.127284,0.840771,-0.097075,0.471582,0.524782,0.110268,-0.352613,-0.641356,0.327984,-0.137334,-0.073489,-0.442750,0.129737,-0.234602,-0.132012,-0.162002,0.596867,0.265778,0.218474,0.754906,0.166309,0.234085,-0.263928,0.494160,-0.187646,0.046579,0.187349,0.138715,-0.405184,0.286574,-0.020552,-0.121350,-0.337648,0.102247,0.025771,0.461626,0.594319,-0.135230,-0.222620,0.067125,0.205113,-0.331442,0.122406,0.207865,0.058947,-0.110638,0.013934,0.083107,-0.307583,-0.031151,-0.157020,-0.254541,-0.293838,0.170083,0.177116,0.173558,-0.478091,0.366736,-0.259542,-0.198579,0.122335,-0.544686,0.142133,0.448020,-0.002038,0.489080,-0.218817,0.174000,-0.615837,0.189612,0.784637,-0.137419,-0.031083,0.448821,0.033455,-0.353564,0.107054,0.120622,-0.339429,0.005453,0.209687,0.412031,-0.195760,-0.192798,-0.332148,-0.185689,-0.412035,-0.278689,0.299820,-0.362137,0.072839,-0.689486,0.010477,-0.307773,-0.296674,0.102460,-0.007485,-0.371765,0.509606,-0.767955,0.404832,0.194754,0.126282,-0.598835,0.655798,0.111677,0.306098,-0.201263,0.252639,0.650259,-0.112067,0.334655,-0.025507,0.141996,-0.100958,-0.032787,-0.663596,0.103140', '1303333', '26687241', '1291992', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23761370', '速度与激情7', '动作', '经历了紧张刺激的伦敦大战，多米尼克·托雷托（范·迪塞尔 Vin Diesel 饰）和他的伙伴们重新回归平静的生活，但是江湖的恩恩怨怨却决不允许他们轻易抽身而去。棘手的死对头欧文·肖瘫在医院，不得动弹，他的哥哥戴克·肖（杰森·斯坦森 Jason Stantham 饰）则发誓要为弟弟复仇。戴克曾是英国特种部队的王牌杀手，不仅身怀绝技，而且心狠手辣。他干掉了远在东京的韩，还几乎把探长卢克·霍布斯（道恩·强森 Dwayne Johnson 饰）送到另一个世界，甚至多米尼克那世外桃源般的家也被对方炸毁。复仇的利刃已经架在脖子上，多米尼克再也没有选择，他找到长久以来最为信赖的团队，与来势汹汹的戴克展开生死对决……©豆瓣', '范·迪塞尔', '温子仁', 8.4, 454690, 'tt2820852', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233706697.jpg', 0.6, 1.7, 15.8, 42.2, 39.6, '0.092970,0.001003,-0.701026,0.650151,-0.230154,-0.528929,0.733055,0.051796,-0.276547,-0.086742,0.185196,0.706419,0.031921,0.172018,0.153851,-0.119493,-0.003117,-0.887581,-0.125388,-0.073036,-0.367403,-0.425707,-0.315463,-0.334834,0.122346,-0.093945,0.635667,0.030154,-0.254670,0.335440,0.317319,0.295033,-0.062924,0.544925,-0.359759,-0.144842,-0.051177,0.063526,-0.499401,0.020660,-0.037448,-0.144136,-0.133661,0.344761,0.159457,0.356009,0.519413,-0.192549,-0.031905,0.031016,0.193717,-0.442565,0.118937,0.060276,0.280075,-0.150074,-0.081396,0.113429,0.026070,-0.054623,0.132298,-0.081058,-0.731972,0.024320,0.084777,0.030139,-0.773991,0.494193,-0.121557,0.112303,-0.137576,-0.054198,0.346914,0.371858,0.019023,0.098075,-0.092091,0.044478,-0.549819,0.179003,0.622490,-0.095261,-0.306402,-0.013684,0.039712,-0.364092,-0.188766,-0.423936,-0.441658,-0.147696,0.501694,-0.146884,-0.161631,0.175492,-0.426653,-0.229933,-0.117921,-0.043407,-0.134734,-0.393911,0.161723,-0.651973,-0.066308,-0.354130,-0.287818,0.179603,0.015202,-0.156066,0.598991,-0.583686,0.285101,0.469986,0.289143,-0.429701,0.611430,0.243029,0.066371,-0.094637,-0.059884,0.609230,0.315932,0.326830,0.399833,0.300297,-0.086466,0.031374,-0.251661,0.607563', '30162520', '25828589', '1306801', '1299663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23767433', '年鉴计划', '科幻', '某日，大卫（乔尼·维斯顿 Jonny Weston 饰）在阁楼里找到了身为科学家的父亲留下的遗物——一台摄像机和一套图纸，让大卫感到震惊的是，这套图纸的内容竟然和如何制造一台时光机器有关。叫来了妹妹克里斯蒂娜（维吉尼亚·加德纳 Virginia Gardner 饰）、好友坤恩（山姆·勒纳 Sam Lerner 饰）和亚当（艾伦·伊万格力斯塔 Allen Evangelista 饰），以及暗恋的女孩杰西（索菲亚·布莱克-德埃利亚 Sofia Black-D''Elia 饰），一行五人用过努力竟然真的制造出了时间机器。使用时间机器，大卫和好友们频繁的回到过去，弥补了生命中大大小小的遗憾，也实现了心目里各式各样的幻想，但随着时间的推移，大卫发现，他们的所作所为有可能导致地球大爆炸。©豆瓣', '乔尼·维斯顿', '迪恩·以色列特', 6.7, 15547, 'tt2436386', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2224085970.jpg', 1.9, 9.6, 48, 30.9, 9.7, '0.090369,-0.003512,-0.598420,0.576715,-0.061007,-0.562128,0.717345,-0.169099,-0.461791,-0.529259,0.122019,0.726957,-0.235040,0.163637,0.168769,0.139592,-0.660220,-0.539233,0.147513,-0.424822,-0.457426,-0.742164,-0.452038,-0.286122,0.268455,-0.578713,0.257207,-0.131944,-0.149680,0.430959,0.140140,0.440396,-0.100050,0.110183,0.055424,0.259828,0.240411,-0.154876,-0.296537,-0.001516,0.088455,0.130644,0.103052,0.165348,0.092522,0.204757,0.576043,-0.338291,-0.083331,0.101993,0.337794,0.017577,0.037296,0.024950,-0.026872,0.294331,0.021271,0.114817,-0.361986,0.107786,0.054849,0.101599,-0.811428,0.115085,-0.116925,0.013105,-0.586093,0.407080,-0.333861,-0.254975,0.069866,-0.378714,0.381919,0.238923,0.431248,0.421897,-0.209361,-0.070019,-0.407772,-0.045055,0.219016,-0.185153,-0.175401,0.344652,-0.096371,-0.111154,-0.151886,0.060059,-0.362527,0.070095,0.399200,-0.012515,0.103320,0.379251,-0.740254,0.003991,-0.465460,-0.279439,0.190166,-0.161292,-0.144061,-0.858706,-0.035993,-0.357895,-0.260572,-0.166085,-0.011547,-0.385636,0.836890,-0.634991,0.297585,0.282923,0.320489,-0.150643,0.453719,-0.190335,0.177813,-0.055103,-0.025695,0.042957,0.268369,0.066121,0.112101,0.322606,0.175652,-0.297116,-0.494760,0.394820', '3318306', '1793922', '26577354', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23769147', '爱情限时恋未尽', '剧情', '布莱恩（安东·尤金 Anton Yelchin 饰）是一位名不见经传的小作家，每天都挣扎在退稿信中久久看不见出头之日。一次偶然中，布莱恩邂逅了名叫艾利艾尔（贝纳尼丝·玛尔洛 Bérénice Marlohe 饰）女子，这个温柔成熟的女人几乎满足了布莱恩对异性的一切幻想，只有一点十分遗憾，艾利艾尔已经结婚了。然而，艾利艾尔告诉布莱恩，自己和丈夫有一个约定，那就是每天的5点到7点之间，他们两人都是自由且不受婚姻束缚的，可以随心所欲的做任何想要做的事情，甚至是寻找另一段感情。在艾利艾尔的循循善诱之下，布莱恩接受并且加入了他们的这段关系中。©豆瓣', '安东·叶利钦', '维克多·列文', 7.7, 17630, 'tt2486678', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2255650112.jpg', 0.8, 3.7, 27.7, 43.2, 24.7, '0.424533,-0.051443,-0.637067,0.555334,-0.390222,-0.249932,0.589817,-0.128652,-0.533283,-0.369110,-0.090646,0.686925,-0.259439,0.263525,0.142326,0.095885,-0.289780,-0.817668,0.207116,-0.299405,-0.284644,-0.788710,-0.197115,-0.107707,-0.318598,-0.190230,0.600074,0.008721,-0.032863,0.439013,0.265470,0.057659,0.021373,0.611849,-0.043701,-0.031363,0.156681,-0.173356,-0.356378,0.105454,-0.020311,0.090940,0.020726,0.205323,0.077801,0.641688,0.349656,-0.521149,-0.106443,0.013974,0.229978,-0.037996,0.018537,0.216529,-0.074925,-0.124282,0.205912,0.293766,-0.271619,-0.213869,0.238320,-0.084777,-0.735385,-0.123605,0.080426,0.438808,-0.597383,0.441767,0.071043,-0.256805,0.343253,-0.278342,0.074969,0.333870,0.352164,0.224809,-0.258223,0.025014,-0.456308,-0.016524,0.537133,0.175348,-0.400185,0.446860,-0.497849,-0.320036,-0.202932,-0.082092,-0.490392,0.084123,-0.139277,0.225450,-0.095587,0.337841,-0.287096,-0.037614,-0.070283,-0.077084,0.023398,-0.687583,0.008882,-0.669283,-0.065998,-0.497792,-0.396388,0.134725,0.114530,-0.475687,0.566678,-0.886426,0.281753,0.475274,0.522621,-0.253773,0.651985,0.469644,0.346230,-0.219233,0.037412,0.414818,-0.072878,-0.220629,0.250751,0.394014,0.300856,0.149533,-0.292124,0.733378', '1783461', '20277433', '24325856', '4844903');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23774869', '绿毛怪格林奇', '喜剧', '《圣诞怪杰》根据“苏斯博士”（Dr. Seuss）的著名畅销童书改编，故事主角是一个绿色的怪物格林奇（Grinch），他非常非常痛恨圣诞节，因为他是一个孤儿。为了不让人们过圣诞，他把所有圣诞礼物都偷走了。最后还是一个纯真的小女孩融化了他冷漠的心。', '本尼迪克特·康伯巴奇', '亚罗·切尼', 6.2, 12612, 'tt2709692', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2539666559.jpg', 2.2, 15.9, 57.9, 18.9, 5.1, '0.204022,-0.296085,-0.396248,0.735286,-0.330267,-0.189769,1.083240,-0.259571,-0.326886,-0.430105,0.136135,0.809736,-0.500011,0.362165,0.018526,0.464432,-0.217254,-0.353751,-0.272077,-0.188002,0.133195,-0.236306,-0.517155,-0.130762,-0.194523,-0.052172,0.735490,0.052889,-0.004867,0.271089,0.347616,0.312659,0.313452,0.477420,-0.468408,-0.031315,0.022604,-0.265752,0.228668,0.113328,-0.142588,-0.130225,0.104859,0.624371,-0.246155,0.380489,0.769681,-0.592300,-0.041924,-0.269606,0.521623,-0.405508,-0.373096,0.069704,0.237990,-0.000807,0.381872,0.174875,-0.179516,-0.193247,0.079881,-0.123375,-0.842955,-0.180754,0.230126,0.184398,-0.461835,0.553170,-0.217367,0.142262,0.284218,-0.543511,0.322330,-0.198002,0.245235,0.368381,0.079681,0.060349,-0.378012,0.485404,0.746262,-0.210042,-0.278626,0.620824,-0.654106,-0.342209,0.378036,-0.191067,-0.626969,0.493107,0.422221,-0.121114,-0.044216,0.352351,-0.798339,-0.144952,-0.261939,-0.480137,-0.015830,-0.553670,-0.304059,-0.158949,0.080742,-0.150194,-0.349064,-0.294859,-0.171155,-0.397486,1.127623,-0.688614,0.234745,0.723204,-0.139426,-0.236381,0.454180,0.216260,-0.123103,-0.278175,-0.139048,0.344786,0.166457,0.180398,0.078561,0.579159,0.208858,-0.121523,-0.254341,1.031980', '2053515', '26667010', '4181031', '2357162');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2377539', '暗夜恐惧', '剧情', '男人牵着四只恶犬在街上行走，他每放走一只恶犬，就意味着世上有一无辜者受到戕害，当他放走最后一只恶犬之时，自己反而成为了最后的受害者。童年时代，男子迷恋收集昆虫，成年后，孤僻而沉默的他遇见了美丽的女子，女子对其一见倾心，然而，随着时间的流逝，女子的身上开始展现出了令男子感到毛骨悚然的变化。饱受同学欺凌的少女家住武士初的坟墓之后，有关初的恐怖传说一直纠缠着少女，横行的鬼怪和彻骨的恐惧看似只是梦境，但却同现实发生了交集。少年的叔叔无故失踪，朋友告诉了他关于沼泽中存在怪兽的传说，接连出现的亡者让少年逐渐相信，传说并不仅仅只是一个传说。五个意味深长的故事，用低沉婉转的旁白和光怪陆离的画面，揭露心底最深处的恐惧。©豆瓣', 'Gil Alma', 'Blutch', 8, 19194, 'tt0792986', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1005208327.jpg', 0.6, 2.3, 21.2, 46.6, 29.2, '0.160190,-0.058584,-0.660634,0.584070,0.072013,0.020147,1.329381,0.021559,-0.573257,-0.174595,0.298047,0.586485,-0.311324,0.231339,0.339374,0.022552,0.187175,-0.559969,-0.264105,-0.186244,-0.182096,-0.126962,-0.258924,-0.187126,0.066412,-0.563879,0.750437,0.201254,-0.480364,0.576848,0.092916,0.144640,-0.340844,0.551087,-0.313503,-0.187434,-0.127206,0.236278,-0.055255,-0.081950,-0.011087,-0.162680,-0.001387,0.060161,-0.579256,0.277641,0.791793,-0.488201,-0.299637,-0.118915,0.384327,-0.063131,-0.195155,-0.138426,0.247851,-0.058717,0.281274,0.181956,0.144509,-0.371719,-0.005046,0.041643,-0.635664,0.139512,-0.048531,0.427826,-0.286988,0.367172,0.190763,0.188589,0.282498,-0.133938,0.282233,-0.261120,0.460735,0.332938,-0.056135,-0.142673,-0.363810,0.169622,0.597555,-0.044578,-0.618923,0.440926,-0.327075,-0.549237,-0.183129,-0.206287,-0.436945,0.237897,0.069162,0.277424,-0.708803,0.542628,-0.554804,-0.018209,-0.101185,0.072732,-0.040164,-0.481180,-0.548671,-0.005000,-0.294253,-0.315991,-0.442609,0.020808,0.073460,-0.209721,0.638797,-0.858385,0.492118,0.666296,0.280596,-0.142153,0.635652,-0.157616,-0.002698,-0.090221,-0.083857,0.468869,0.176716,0.095678,0.036408,0.217556,-0.387510,0.142948,-0.369553,0.435792', '20451118', '21619567', '1467779', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2378640', '拥抱春天的罗曼史', '动画', '香藤洋二（三木真一郎 配音）是当红的AV男优，在一次试镜中，他败给了竞争对手岩城京介（森川智之 配音），虽然工作上落败了，但岩城的魅力却让香藤印象深刻。两人的故事并没有就此结束，不久之后，在一部电视剧中，他们扮演了一对恋人。电视剧反响极为热烈，两人很快成为了人气巨星，与此同时，香藤发现自己假戏真做，坠入了名为“岩城京介”的情网之中。强势的香藤自作主张搬进了岩城的公寓，两人快乐的“同居”生活正式开始，渐渐的，半推半就的岩城发现，香藤的身上有着他极为向往的特质。娱乐圈里鱼龙混杂，各种各样的诱惑层出不穷，一次次的误会与曲解，深陷其中的两人，能否坚守着最初坚贞的感情呢？©豆瓣', '森川智之', '新田义方', 7.5, 7089, '', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2503153062.jpg', 0.5, 4, 33.5, 41.8, 20.2, '0.473517,0.227301,-0.773517,0.786421,0.013627,-0.123509,0.842318,0.226893,-0.588082,-0.183812,0.077817,0.742284,-0.489407,0.280340,0.176993,-0.239599,-0.141837,-0.828238,-0.179353,-0.170814,-0.052982,-0.231171,-0.483126,0.209101,-0.283587,-0.144437,0.755523,0.315631,-0.354785,0.566828,0.415195,0.199863,-0.283444,0.452998,0.112023,0.124361,0.182465,0.161964,-0.293622,0.221020,-0.122878,-0.434574,-0.066844,0.296900,-0.098315,0.463320,0.768114,-0.218667,-0.378419,0.106289,0.492199,-0.149370,-0.331446,0.166465,0.224672,0.076776,0.425049,0.270831,-0.232756,-0.043694,-0.232993,-0.116235,-0.828421,0.046830,0.068105,0.301685,-0.399744,0.551955,0.248730,-0.148325,-0.014364,-0.225457,0.098628,0.056802,0.397129,0.270396,-0.220780,0.092708,-0.230637,0.239716,0.760031,0.051885,-0.274268,0.747503,-0.166716,-0.478820,-0.073999,-0.291976,-0.452101,-0.070323,0.439177,0.204926,-0.144050,0.171015,-0.740261,0.186659,0.041077,-0.134400,-0.091128,-0.492640,0.191892,-0.678472,-0.554120,-0.718034,-0.288016,-0.057454,-0.043266,-0.261179,0.829596,-0.915765,0.096627,0.395071,0.168976,-0.236498,0.552868,0.262150,-0.070870,0.060383,-0.030478,0.044202,-0.248784,-0.026149,0.128450,0.520138,-0.267709,-0.143764,-0.670589,0.625741', '2053515', '3811356', '25880986', '27666513');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23788440', '杀破狼2', '剧情', '倒卖人体器官集团的主脑洪文刚（古天乐 饰）罹患严重心脏病，为了活命他甚至计划摘取亲弟弟洪文标（恭硕良 饰）的心。为了完成卧底工作不惜身染毒瘾的志杰（吴京 饰）随老大去码头劫持试图逃跑的洪文标，他的上司见叔叔陈国华（任达华 饰）接到线报后也率队赶往现场，三方随即展开了激烈 的交火。侥幸逃生的志杰被送到泰国一所监狱，而掌控这里的狱头（张晋 饰）则与洪文刚有着千丝万缕的联系。女儿罹患血癌的狱警阿猜（托尼•贾 饰）对志杰的真实身份生出许多疑惑，而之后他无意中发现了监狱里的可怕秘密。为了营救侄子，陈国华不远万里追到泰国。而洪文刚仍在做着垂死挣扎，他最终陷入癫狂……©豆瓣', '吴京', '郑保瑞', 7.5, 175914, 'tt3197766', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2246885606.jpg', 0.8, 3.6, 33.1, 47.1, 15.4, '-0.032239,0.099973,-0.724059,0.566765,-0.004568,-0.236774,0.651802,0.207153,-0.519778,-0.188552,0.216204,0.533038,0.052501,0.138047,0.204342,-0.055231,-0.273731,-0.521416,-0.118902,-0.070555,-0.331323,-0.335645,-0.366638,-0.331888,0.016302,-0.205375,0.387474,0.300442,-0.190769,0.447958,0.405703,0.372085,-0.371143,0.325803,0.075086,0.026406,0.145726,-0.040545,-0.430274,0.234780,0.268508,-0.267885,0.033318,0.167121,0.072925,0.577634,0.635776,-0.046375,-0.143440,-0.177196,0.253451,-0.346797,0.026581,0.121536,0.263432,0.132153,0.069862,0.076892,-0.364130,-0.068634,0.268003,0.010351,-0.793083,0.060701,0.202473,0.223416,-0.356547,0.073472,-0.293725,0.094146,0.127104,-0.249205,0.287522,0.555161,0.036059,0.198211,-0.294529,0.084045,-0.459745,0.233231,0.609528,-0.307669,0.105454,-0.041950,0.072851,-0.253612,0.210561,-0.188643,-0.249788,-0.077153,0.473757,-0.043814,-0.217736,0.064415,-0.311673,-0.302250,-0.219111,0.067414,-0.137712,-0.235972,-0.045872,-0.500714,-0.048506,-0.117089,-0.078484,0.063920,0.088488,-0.115777,0.237520,-0.581348,0.193924,0.464241,0.250251,-0.685904,0.255669,-0.018126,0.091978,-0.310334,-0.098441,0.189520,0.219269,0.355101,0.192088,0.001391,-0.169945,-0.264663,-0.382174,0.013964', '35073886', '26678784', '1301022', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2379039', '走着瞧', '剧情', '七十年代，城市知青马杰（文章 饰）来到西北某农村插队，被村里漂亮种驴——黑六的叫声吸引。马杰嫌黑六不让他骑，某次工伤在诊所缝针时偷了麻醉剂打给黑六，队长大莲（岳红 饰）以为黑六生病，心急如焚。马杰奇迹般地“治愈”了黑六，赢得大莲和队里的信任，成为牲口饲养员。马杰一边喂驴，一边偷偷与村里的女青年彩凤（白静 饰）相恋。与此同时，马杰对黑六只配种不干活的特殊待遇愈发不满，并对大莲“驴比人值钱”的论调暗自气愤，发泄中竟打坏了黑六的“命根子”。无法配种也不能干活的黑六被马杰宰杀，却没曾想黑六的弟弟，毛驴黑七，从此与马杰不共戴天。人与驴的斗争愈演愈烈。©豆瓣', '文章', '李大为', 7.6, 15225, 'tt1459986', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2128614247.jpg', 0.4, 2.1, 28.7, 52.2, 16.6, '0.175352,-0.204831,-0.248554,0.329485,-0.171088,-0.487225,0.403187,0.111380,-0.184367,-0.068119,0.068453,0.232675,-0.325845,0.128306,-0.086802,-0.212699,0.066957,-0.329959,-0.172324,0.182106,-0.325095,-0.316800,-0.314003,-0.078569,0.035357,-0.037603,0.050661,-0.056320,-0.275897,0.445990,0.261448,0.210477,-0.102859,-0.136708,-0.396661,0.173628,-0.139929,-0.023784,0.200087,-0.184286,-0.142907,0.033112,0.012117,-0.337019,0.263365,0.411850,0.476386,-0.243466,-0.176234,-0.548113,-0.052762,0.021362,-0.227918,0.163992,0.423808,-0.247135,0.274436,0.047161,0.071866,-0.063971,0.060444,0.077517,-0.389233,0.424022,-0.119743,0.251189,-0.540732,0.617828,-0.193219,0.156032,0.219732,-0.163339,0.051025,-0.055401,-0.108313,0.601358,0.180752,0.327222,-0.376025,0.253774,0.529127,-0.105603,0.174970,0.161287,-0.011114,-0.085588,0.133277,-0.248372,-0.292023,-0.226371,0.476040,0.175920,-0.436380,-0.036595,-0.438040,-0.010893,-0.027058,-0.237542,-0.150649,0.084187,-0.244537,-0.074996,0.038859,-0.632980,-0.036563,0.365084,0.423068,-0.064073,0.436472,-0.407595,0.226269,-0.032139,0.261409,-0.604841,0.322652,0.088812,0.005973,-0.201738,-0.361843,-0.450473,0.203777,0.154314,0.609459,0.373207,-0.458009,-0.555482,-0.497404,0.224927', '1428208', '3998385', '1308607', '1876765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2381810', '伯纳德行动', '剧情', '20世纪30年代，二次大战如火如荼。而萨利（Karl Markovics卡尔•马克维斯 饰）凭借一手高超的伪造技巧春风得意，佳肴美女信手拈来，好不自在。但是他的好日子并为持续多久，很快他便因为遭罪被逮捕，随后投入毛特豪森集中营。时德国纳粹图谋制造大量假币，以扰乱同盟国的经济。萨利的才能得到发掘，他成了这个秘密伪钞制造小组的头目，但良心却促使他选择了另一条路……本片根据阿道夫•博格（Adolf Burger）原著《魔鬼工厂》（The Devils Workshop），书中所述为作者亲身经历，影片荣获2008年奥斯卡最佳外语片奖和2007年德国电影金像奖最佳男配角奖（Devid Striesow）。©豆瓣', '卡尔·马克维斯', '斯戴芬·卢佐维茨基', 7.9, 26875, 'tt0813547', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p676958835.jpg', 0.1, 1.1, 22.9, 57.2, 18.7, '-0.227847,0.093925,-0.221018,0.443425,0.189112,-0.219645,0.214774,-0.239141,-0.527592,-0.139944,0.178482,0.638472,-0.145050,-0.321045,0.280476,0.042529,-0.624659,-0.711887,0.214687,-0.249189,-0.083946,-0.294747,-0.442808,-0.306976,-0.230365,-0.416757,0.771651,-0.014513,-0.175935,0.073636,0.178467,0.174733,0.093477,0.043315,-0.060808,0.001382,0.363704,-0.376780,-0.393801,0.339116,0.006682,-0.235074,-0.490442,0.027871,-0.048316,0.323153,0.500384,-0.198412,-0.182339,-0.218188,0.625629,-0.268500,-0.215236,-0.157987,0.247738,0.014431,0.203822,0.167455,0.058300,0.021784,-0.004352,-0.209174,-0.897779,-0.064531,0.058737,-0.064992,-0.270974,0.133401,-0.298968,0.177855,-0.008392,0.089826,-0.097581,0.400883,0.616410,0.049532,-0.258679,0.079064,-0.337277,0.701937,0.314635,-0.047078,-0.499865,0.227177,-0.102200,-0.666409,-0.051393,-0.384844,-0.145560,0.123563,0.382630,0.040500,-0.032652,0.148185,-0.514607,0.107756,-0.256670,-0.236403,-0.005414,-0.127245,-0.081637,-0.786661,-0.179217,0.071539,-0.046826,-0.222136,0.077909,-0.254258,0.659607,-0.171398,0.316719,0.636373,0.054086,-0.368370,0.619892,-0.177138,-0.037582,-0.400115,-0.351697,0.258670,-0.157433,0.054845,0.148420,0.260229,0.110294,-0.507939,-0.010046,0.511802', '22265121', '27073234', '27602116', '1293692');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2381835', '春风物语', '剧情', '叶山托生（柳下大 饰）是个内向的高中二年级生，就读于私立祠堂学院，这是一所全日制的男子寄宿学校。托生的内向为他招惹到不少他人的欺负。而之所以有这样的性格，是因为托生患有“对人接触厌恶症”。这样的体质让托生害怕与人接触。在一次午餐时间，托生激怒了学院偶像高林泉（斋藤康嘉 饰），泉将餐盘砸向了托生，但是托生的同学崎义一（加藤庆佑 饰）突然冲到了托生面前，替其挡下了飞来横祸。而义一这已不是第一次替托生解围。第一次被人如此温柔的对待，让托生困惑不已。而义一在无意中说出了托生的秘密，让托生惊慌的逃出宿舍，结果被对其虎视眈眈的篮球部主将野崎大介（牧田哲也 饰）给逮住。大危机下，又是义一将其解救。而这时义一也向托生说出了自己的心意，托生会怎样回答呢？一出成长的恋爱物语就此展开。©豆瓣', '柳下大', '横山一洋', 5.8, 6513, 'tt1235445', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2191923813.jpg', 8.2, 22, 47, 15.8, 7, '0.367364,0.040144,-0.528813,0.486748,-0.136598,-0.388699,0.545933,0.179305,-0.391395,-0.086191,-0.014739,0.905021,-0.492020,0.399014,0.302948,0.135847,0.379771,-0.611716,-0.341966,-0.223057,-0.390985,-0.289681,-0.232939,-0.037409,-0.097534,-0.254260,0.373583,-0.070079,-0.355983,0.468361,0.515559,0.540815,0.192051,0.284861,-0.243195,-0.030736,-0.471707,0.232478,0.250991,0.307582,-0.024642,-0.360388,-0.125419,0.088649,-0.066017,0.409937,0.739606,-0.210946,-0.401817,-0.423934,0.559856,-0.337876,-0.249615,0.234747,0.308845,-0.297097,-0.068493,0.223971,-0.290580,0.240322,0.242134,-0.135979,-0.660125,-0.016585,-0.041854,0.000551,-0.728862,0.168429,0.110310,-0.240840,0.149786,-0.073845,0.143988,0.386233,0.287734,0.371558,-0.453962,-0.160070,-0.275028,0.081653,0.737153,-0.157831,-0.111300,0.234352,-0.021846,-0.331592,0.203876,-0.252811,-0.384731,-0.090022,0.038837,0.241956,-0.241618,0.069648,-0.106784,-0.162434,-0.213047,0.082717,0.050602,-0.507802,-0.212700,-0.164383,-0.074480,-0.102659,-0.618586,0.105690,0.028522,-0.125901,0.748873,-0.890956,-0.158244,0.378219,0.347546,-0.511956,0.775901,0.009898,-0.119738,0.019953,0.068129,0.130826,0.281555,0.228185,0.112380,0.515692,-0.156936,-0.364672,-0.348945,0.155673', '1292219', '35048413', '1296569', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2382939', '无忧无虑', '剧情', '波皮（莎莉·霍金斯 Sally Hawkins 饰）已经三十岁了，她是个普通的小学教师，没有房子，没有存款，仍旧单身，不再年轻也就不再漂亮……但是与沮丧现实相反的，是波皮极端乐观的个性，她明媚开朗得像涉世未深的孩子，甚至在一些外人眼里亢奋得不大正常。她练习蹦床，却遭到肌  肉拉伤，方知自己年龄已经不适合这项运动，只好改学弗拉门戈舞；她去学车打算考驾照，却因为表现得太过活泼亲热，引来严肃的学车教练斯考特（艾迪·马森 Eddie Marsan 饰）愤怒爆发，认为她在挑逗他……波皮“无忧无虑”的性格，不符合年龄的乐观，似乎已经与周围的一切格格不入……©豆瓣', '莎莉·霍金斯', '迈克·李', 7.3, 6851, 'tt1045670', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2453937908.jpg', 1.2, 5.7, 36.6, 42, 14.5, '0.652265,-0.090855,-0.768044,0.311814,-0.677599,-0.113083,0.844061,0.110906,-0.328539,-0.220825,0.123741,0.405252,-0.068745,0.175851,-0.265070,0.053119,-0.182238,-0.349011,-0.091162,0.260996,0.060016,-0.639726,-0.116134,-0.144441,-0.317146,-0.508664,0.507185,0.005047,-0.274660,0.528228,0.165282,-0.040804,0.367705,0.519343,-0.371598,-0.187917,-0.091881,0.156453,0.364730,-0.208096,0.135517,0.057731,-0.298646,0.459688,0.308883,0.732119,0.479411,0.096053,-0.499420,0.321272,0.540027,0.107171,-0.123707,0.375027,0.330178,-0.360599,0.208315,-0.381848,-0.058655,0.118197,-0.201582,-0.081422,-0.677990,0.237240,0.304048,0.233595,-0.387553,0.554302,-0.209870,-0.382087,0.016458,-0.278080,-0.283005,0.135791,0.093894,0.487941,0.186507,0.082074,-0.325000,0.198338,0.763194,0.562575,-0.842648,0.701774,-0.912569,-0.446464,-0.235068,-0.563033,-0.657610,-0.004341,0.087387,-0.123934,-0.299188,0.269293,-0.128013,0.230344,-0.023465,0.026844,-0.326599,-0.198891,-0.055760,-0.196869,-0.179532,-0.953842,-0.583511,-0.139162,-0.025678,-0.233210,0.618197,-1.017268,0.162303,0.375989,0.101671,-0.402766,0.463740,0.180579,-0.279323,-0.248506,-0.060784,0.263042,-0.222935,-0.195892,0.314400,0.680669,0.064310,-0.437653,-0.399146,0.766704', '30209802', '27191173', '3443074', '1304989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2383207', '重金摇滚双面人', '剧情', '来自大分县犬饲町的乡下男孩根吉崇一（松山健一 饰）怀着美好的理想来到大都会东京求学，在这繁华所在，他立志写出优美动听的歌曲，成为受万众瞩目的时尚达人。然而事与愿违，直到毕业他的纯情歌曲依旧得不到认可，反而经一番刻意包装后组成的死亡重金属乐队“底特律金属城”（DMC）大受欢迎，其中根吉所化身的主音吉他手克劳萨二世更令万千死忠疯狂痴迷。虽名声在外，根吉却时时想脱离这支只会贩卖死亡、性、暴力等噱头的乐队，只是苦于魔鬼社长（松雪泰子 饰）的存在，他只能小心翼翼在梦想与现实间挣扎。偶然机会重逢大学时暗恋的女孩相川由利（加藤罗莎 饰），根吉的心情愈加矛盾……©豆瓣', '松山研一', '李斗士男', 7.2, 9098, 'tt1142972', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p1480501012.jpg', 1.6, 7.1, 37, 37.7, 16.5, '0.126528,0.205230,-0.583857,0.412919,0.147141,-0.031738,0.550621,0.322301,-0.581266,-0.319065,0.041300,0.399407,-0.211938,0.223529,0.201682,-0.175253,-0.193004,-0.471285,0.181625,-0.047290,0.301983,-0.120554,-0.166631,-0.035568,-0.197261,-0.191859,0.826702,0.309765,-0.095596,0.426377,0.381150,0.508547,-0.190404,0.131176,-0.073244,-0.159973,0.323670,-0.011542,-0.280901,0.044923,-0.182324,-0.130963,-0.114080,0.100771,-0.081246,0.204761,0.760447,-0.239227,0.029761,-0.025579,0.560504,-0.036678,-0.138953,0.049130,0.051966,0.120890,0.126239,0.131891,-0.214218,0.049357,-0.036559,-0.289085,-0.558621,0.024209,0.326760,0.105079,-0.152012,0.382295,0.118488,-0.091657,0.200656,-0.091502,-0.047746,-0.055074,0.345325,0.211106,-0.056589,0.413107,-0.044664,0.292924,0.684243,0.072606,-0.418324,0.245546,-0.348000,-0.555552,-0.166673,-0.519177,-0.483318,-0.110873,0.056482,0.225475,0.049570,0.040835,-0.461644,-0.067420,-0.140501,0.120484,0.215255,-0.191173,-0.191731,-0.616677,0.099552,-0.223256,-0.131460,0.100648,0.051836,-0.066548,0.679175,-0.729474,0.207598,0.719671,0.126729,-0.046305,0.325568,0.176476,-0.195675,-0.218666,-0.435374,0.824754,-0.142200,0.189468,-0.198186,0.114192,-0.152993,-0.222369,-0.493676,0.635054', '3667102', '3811356', '26759820', '6772974');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('23856234', '摩登年代', '剧情', '名不见经传的小魔术师欧大卫（徐峥 饰），凭着掌握的有限几手把戏招摇撞骗，不仅没赚到什么钱，偶尔还被人饱以老拳，天天混吃等死。在哥们李文学（王太利 饰）的介绍下，大卫认识了海神文化艺术总监毛娜（王宣予 饰），并答应上演一场将伫立在海滩边的巨大雕像“海神之母”变消失的神奇魔术。虽然吹得神乎其神，但这只不过是他配合李文学做的一个哄骗定金的骗局。谁知半路杀出一个名叫的八岁孩子丢丢（张子枫 饰）不由分说认大卫为爸爸；被绊住手脚的大卫好不容易赶到机场，才发现李文学早就带着钱先行跑掉。一个是来历不明的“女儿”，一个是根本不可能完成的魔术，大卫陷入了前所未有的困境……©豆瓣', '徐峥', '邵晓黎', 5.7, 46462, 'tt3293724', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2091618013.jpg', 6.8, 26.1, 49.6, 12.9, 4.7, '0.210738,0.020183,-0.436939,0.333256,-0.484282,-0.164949,0.399587,0.091794,-0.258153,-0.381957,0.287214,0.686160,-0.350801,-0.113266,0.160081,-0.008950,-0.086932,-0.443828,-0.028423,0.055868,-0.232348,-0.416575,-0.132919,-0.028860,-0.128810,-0.123017,0.154231,0.014432,-0.099905,0.287654,0.489056,0.170297,-0.023760,0.230698,-0.274511,0.353636,-0.104865,-0.095775,0.022617,0.282491,-0.018667,-0.262063,0.090721,-0.008471,-0.091426,0.201847,0.476246,-0.134597,-0.113591,0.023707,0.319707,-0.441587,-0.240151,0.018792,0.035713,-0.062449,0.006631,-0.132460,-0.262020,0.175475,0.311704,-0.133405,-0.617163,0.168614,0.018498,0.090033,-0.641106,0.257998,0.118303,-0.129100,-0.126326,-0.239018,0.217886,0.197762,0.223918,0.311820,-0.056274,0.216784,-0.807520,0.100428,0.440203,-0.245614,0.023728,0.308640,0.158030,-0.354634,0.044711,-0.215894,-0.300303,0.110736,0.234127,-0.184984,-0.080008,-0.194749,-0.476938,0.006570,-0.283950,-0.049617,-0.007701,-0.619253,-0.285138,-0.311641,-0.037748,-0.199552,-0.215235,0.297170,0.031641,-0.251057,0.382635,-0.348435,0.394360,0.430364,0.095955,-0.061857,0.440177,-0.024415,0.041286,-0.050533,-0.257824,0.066932,0.341692,0.330129,0.249769,0.301508,-0.020969,-0.258652,-0.136495,0.353315', '1292584', '1299628', '1298667', '1299932');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24089455', '临终囧事', '喜剧', '牛小波（包贝尔 饰）出生在一个棺材世家，几代人以做棺材为生。因小时候一次离奇的事故，小波永远失去了“笑容”，无论碰上多么开心的事他都笑不出来，被人们称之为怪人，好在前些年一直生活在农村老家，他本人也没觉的不会笑是什么大不了的离奇事。渐渐长大成人的小波决定走出大山，到外面闯世界，可外面的世界虽精彩，闯起来却很无奈，原本想离开老家的棺材铺谋一份体面的工作，可最终还是进了殡仪馆工作，这令他多少有些失落。随着时间的推移，小波在殡仪馆领略了世间另一面的人生百态，目睹了各种各样家庭在亲人化为一缕青烟时所表现出的真实状态，明白了他先前没有悟到的人生百味......©豆瓣', '包贝尔', '钱江汉', 5.5, 5991, 'tt4263056', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1962594484.jpg', 11.9, 26.7, 43.4, 12.8, 5.2, '0.167585,0.132336,-0.732162,0.160194,-0.188038,-0.250943,0.898587,0.146778,-0.586633,-0.277188,0.024584,0.707559,-0.129362,0.390349,-0.142592,0.087932,-0.212146,-0.247706,0.151434,-0.458094,-0.196201,-0.097810,-0.085567,0.004585,-0.178245,-0.162814,0.488787,0.397982,0.072104,0.197108,0.128444,-0.026936,-0.022672,0.485279,-0.348195,0.128963,-0.229933,0.396160,-0.128914,-0.316830,0.153749,-0.409944,-0.509333,0.181229,0.126170,0.077094,0.588766,-0.002122,-0.498494,0.286400,0.250643,-0.134363,-0.196306,0.041879,0.236696,-0.123361,0.032250,0.124674,-0.163985,0.024524,0.013423,0.090751,-0.602117,-0.079825,0.045230,0.268385,-0.743754,0.447517,0.039855,-0.243482,0.085409,-0.590513,0.153439,0.124053,0.047717,0.612353,-0.431448,0.176455,-0.653904,0.238726,0.799353,-0.017550,-0.300505,0.526840,-0.201646,-0.226019,-0.263816,-0.197515,-0.301425,0.053394,0.150327,0.070190,-0.406909,0.421705,-0.375723,0.184778,-0.031451,-0.199098,-0.154523,-0.404909,-0.291404,-0.244979,-0.215391,-0.332958,-0.409735,0.036410,0.004175,-0.250033,0.562205,-0.715228,0.199096,0.315844,-0.117554,-0.433734,0.495026,0.221908,0.073010,-0.182466,0.170555,0.192670,-0.090734,0.330082,0.188482,0.451235,0.028070,-0.119746,-0.255823,0.604536', '21619567', '1299965', '26245360', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2416910', '伤', '剧情', '一座偏僻的小镇，一间冷清的酒吧，冗长无奇的生活因为一个人的到来而改变。朝人（小池徹平饰）搬家来此的第一天，就在酒吧里结识了车间修理员武雄（玉木宏饰）和服务生志穗（栗山千明饰），并和他们成为好朋友。让武雄和志穗惊讶的是，朝人竟与生具有超能力，能把人身上的伤任意转移。看到武雄和志穗身上的旧伤后，朝人毫不犹豫地把伤口都转嫁到自己身上。之后，朝人不顾武雄的劝阻，把援手伸向越来越多的人。事实上，朝人自己从小就开始背负着不为人知的伤口，至今未曾愈合，造成伤口的不是别人，正是朝人的生母……©豆瓣', '小池彻平', '荻岛达也', 6.9, 10147, 'tt1170400', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2184218913.jpg', 1, 6.9, 49.4, 33.1, 9.6, '0.537277,-0.147065,-0.549567,0.448419,-0.233385,-0.294343,0.883321,0.142819,-0.316416,-0.114152,0.302779,0.967808,-0.159218,0.296222,0.175092,0.103317,-0.068259,-0.832441,-0.233035,-0.056722,-0.611252,-0.455669,-0.199813,-0.199286,-0.194420,-0.563939,0.545897,0.211153,-0.321704,0.548751,0.079439,0.173029,-0.126713,0.811129,-0.364872,0.163167,-0.435786,0.087962,0.100173,0.123833,0.251535,-0.537313,0.021232,0.487862,0.001529,0.716111,0.827839,-0.039074,-0.228318,-0.239116,0.124391,-0.242442,0.010128,0.173316,0.372047,-0.139635,0.354584,0.210048,-0.288798,-0.022435,0.082924,-0.024093,-0.776555,-0.069176,0.196657,0.087326,-0.627091,0.613769,-0.115692,-0.354564,-0.001851,-0.568091,0.450640,0.335610,0.038786,0.355600,-0.330938,-0.147746,-0.443197,0.066416,0.727467,-0.159248,-0.009482,0.341101,-0.173216,-0.280176,0.017529,-0.282679,-0.171932,-0.012244,0.104184,0.322650,-0.388495,-0.070508,-0.562212,0.197616,-0.200767,-0.317864,0.068160,-0.522763,-0.302360,-0.366030,-0.084136,-0.317820,-0.308797,0.139929,-0.152673,-0.281032,0.639154,-0.885694,0.070708,0.265578,0.622706,-0.271943,0.806923,-0.260520,0.139644,0.150753,-0.167888,-0.016008,0.272149,0.397967,0.371018,0.559280,-0.331542,-0.118865,-0.291488,0.364769', '1308755', '1361252', '1292219', '1302384');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24284209', '开心超人', '动画', '故事发生在一个科技十分发达的星球之上，宅博士（邓玉婷 配音）是一名杰出的机械师，一次偶然中，他激活了五个散落在星球各处的超人，之后，这些超人们成为了保护星球和平的正义使者。活泼开朗，天真正直的开心超人（刘红韵 配音）、聪明大胆，温柔可靠的甜心超人（邓玉婷配音）、天性爱美，实力强大的花心超人（严彦子 配音）、稀里糊涂，丢三落四的粗心超人（祖晴 配音）和沉默寡言，外冷内热的小心超人（刘红韵 配音），五个各具特色的小小超人所要面对的，是来自灰心星球的大大怪（高全胜 配音），面对如此强大的敌人和敌人们惹出来的一堆大大小小的麻烦，这五个小家伙真的没问题吗？©豆瓣', '邓玉婷', '黄伟明', 8.3, 13180, 'tt6448502', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2014813703.jpg', 1, 2, 15.4, 43.1, 38.6, '0.072238,0.079857,-0.496600,0.436885,-0.442617,0.189295,0.491552,-0.001335,-0.214756,-0.205417,0.129022,0.746903,-0.023084,-0.152257,0.032199,-0.243123,0.079140,-0.277108,-0.131054,-0.036840,-0.300050,-0.369871,-0.607736,-0.168942,-0.203193,-0.490436,0.443932,-0.148036,-0.338553,0.246415,0.344213,0.262502,-0.045471,-0.062077,-0.356218,-0.180500,0.160479,0.097450,0.122498,0.073717,-0.292269,0.416165,0.099933,0.077010,-0.191464,0.072927,0.569041,-0.338913,-0.471204,-0.180822,0.720069,-0.373645,-0.217645,0.002873,0.334686,-0.180059,0.227151,-0.225108,0.231490,0.134561,-0.003691,-0.054798,-1.197271,-0.185220,0.065870,-0.068013,-0.317516,0.345595,0.176298,-0.387390,0.245455,-0.208502,0.167294,0.136971,0.112907,0.411827,0.058353,0.289743,-0.023571,0.256834,0.529386,0.344543,-0.802551,0.404180,0.117137,-0.393124,-0.025506,-0.699831,-0.669801,0.279400,0.110934,-0.284537,0.109487,0.218633,-0.675169,0.367713,-0.052399,0.019173,-0.113662,-0.220216,-0.282519,-0.282906,-0.099266,-0.478899,-0.174569,0.031303,-0.156707,-0.373853,1.436793,-0.941220,0.011572,0.674149,0.173631,-0.579036,0.514557,0.143167,-0.132451,-0.265844,-0.089514,-0.024043,0.037546,0.136409,-0.179692,0.526423,-0.108284,-0.313335,-0.497055,0.259185', '27602116', '3718665', '26348103', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24289477', '迪亚特洛夫事件', '惊悚', '1959年，九名俄罗斯登山爱好者在乌拉尔山脉附近失踪，当他们再次被人发现时却早已死亡，死前仿佛受到巨大的惊吓以及非人力的强大外力的袭击，这就是著名的迪亚特洛夫山径事件，时至今日仍然是一个未解之谜。远在美国俄勒冈州的女大学生霍莉·金（Holly Goss 饰）对该事件深深着迷，在获得基金支持后，她联系到电影系学生詹森·戴伊（Matt Stokoe 饰）以及其他三名爱好者，决定前往当年的事发地点拍摄一部纪录片，试图解开悬而未决的谜题。最初的旅程快乐有如度假一般，但随着他们逐渐接近目的地，各种匪夷所思的事件接连发生，队员的心头蒙上不祥的阴影。半个世纪前的噩梦即将在他们身上重现……©豆瓣', '吉玛·阿金森', '雷尼·哈林', 6.9, 16627, 'tt1905040', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1942959268.jpg', 1.4, 8.1, 45.9, 34.6, 9.9, '0.209844,-0.143808,-0.845609,0.443181,0.547541,-0.087193,0.823704,-0.185425,-0.575194,-0.420998,0.280814,0.590519,-0.328554,0.245968,0.274048,-0.158292,-0.300136,-0.746257,-0.173303,-0.346881,-0.504853,-0.154342,-0.502145,-0.070360,-0.003565,-0.318284,0.746119,0.460030,-0.308763,0.636317,0.382835,0.622445,-0.283395,0.379431,-0.125736,-0.108910,0.239025,0.025808,-0.270469,-0.013303,-0.087088,-0.216168,-0.041566,0.048213,0.010449,0.363589,0.662816,-0.360098,-0.257935,-0.019052,0.401469,-0.288968,-0.012793,0.115865,0.326721,0.474503,0.217836,0.179351,-0.109655,0.065893,0.025620,-0.228293,-0.510359,0.028969,0.257278,0.355883,-0.363978,0.343620,0.001361,0.001569,0.050303,-0.307008,0.058550,0.281792,0.253025,0.358132,-0.157273,0.038379,-0.270948,0.244784,0.935593,0.012866,-0.500073,0.190590,-0.087388,-0.381624,-0.317565,-0.224493,-0.201700,0.294994,0.456641,0.243214,-0.111053,0.463596,-0.563080,-0.080599,-0.097055,-0.295225,-0.120121,-0.190234,-0.229760,-0.857991,-0.027941,-0.200870,-0.132305,0.244508,0.172618,-0.290267,0.583756,-0.640473,0.489760,0.667470,0.178168,-0.317071,0.440232,-0.167713,0.132740,-0.117960,-0.132016,0.397786,-0.022115,0.466139,-0.115654,0.149566,-0.162903,-0.213213,-0.482786,0.437349', '2269893', '25828589', '3011051', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24298212', '鲁邦三世VS名侦探柯南 剧场版', '动作', '堪称动画史上的最强对决到来！传奇大盗鲁邦三世（栗田贯一 配音）和他的战友次元大介（小林清志 配音）、石川五卫门（浪川大辅 配音）来到东京，以怪盗基德之名挑战日本警察和柯南（高山南 配音）。在此之后，鲁邦高调寄出预告书，扬言要盗取某银行内的稀世珍宝樱桃蓝宝石，为此国际刑警组织（ICPO）的鲁邦三世专门搜查官钱形幸一警部（山寺宏一 配音）与目暮警官（茶风林 配音）为代表的日本警视厅通力配合，决心给大盗迎头痛击。另一方面，意大利偶像歌手艾米里翁·瓦力迪（入野自由 配音）赴日卡演唱会，但威胁杀害偶像的恐吓信也随之而来。人声鼎沸的演唱会会场，史无前例的对决拉开序幕……©豆瓣', '栗田贯一', '龟垣一', 7.8, 24197, 'tt3335192', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2162543461.jpg', 0.5, 2.9, 28.3, 44.2, 24.2, '-0.054488,-0.189793,-0.241987,0.531242,0.442681,-0.190093,0.232084,0.231615,-0.121627,-0.295318,0.298813,0.579713,-0.252633,-0.166508,0.382768,-0.149545,-0.214825,-0.567056,-0.174817,-0.258637,0.076334,-0.227659,-0.253991,-0.080613,-0.030513,0.010917,0.551466,0.008120,-0.391521,0.635640,0.460591,0.187687,-0.146151,0.041986,0.264366,-0.073975,0.560646,-0.014425,-0.397085,0.370687,-0.309261,-0.045007,-0.137640,0.173860,0.110852,0.218456,0.381751,-0.289389,0.117313,-0.058110,0.341792,-0.420657,-0.267902,0.038740,0.292625,0.302941,0.189012,0.289349,-0.079293,-0.007145,-0.159544,-0.368303,-0.616743,0.013767,0.076527,0.071426,0.118648,0.206653,-0.464436,0.318103,0.318205,0.050276,0.219677,-0.049872,0.464321,0.219326,0.115794,0.292525,-0.149834,0.573391,0.325418,-0.087246,0.147354,-0.017830,0.229002,-0.422965,0.105356,-0.320973,-0.285468,0.199295,0.211199,-0.507196,0.368905,-0.058985,-0.601291,-0.247483,-0.291153,-0.075767,-0.101254,-0.046913,-0.039555,-1.085419,-0.029577,-0.056538,0.232665,-0.055023,0.258995,-0.258407,0.744332,-0.665629,-0.071552,0.638855,0.095111,-0.225145,0.608675,0.132599,-0.136990,-0.291533,-0.279933,-0.022835,0.321095,0.417744,-0.119475,0.027738,0.256822,-0.374181,-0.285721,0.095005', '2369613', '24751811', '3003137', '26094129');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24298954', '疯狂原始人2', '喜剧', '经历了逃离洞穴、挺过末日危机之后的原始人咕噜家族，咕噜一家决定寻找新家园。中途盖（瑞恩·雷诺兹 Ryan Reynolds 配音）已成了咕噜一家中的一员，但让瓜哥（尼古拉斯·凯奇 Nicolas Cage 配音）头疼的是，盖跟女儿小伊（艾玛·斯通 Emma Stone 配音）每天你侬我侬，还妄想组成只属于两人的小家庭。就在咕噜一家人饥肠辘辘之际，他们发现了一片高墙内隐藏着食物丰饶的沃土，原来开辟这片世外桃源的文明人夫妇霍普和菲尔是已经去世的盖的父母的朋友。在最初的热情款待后，一心想要撮合盖和女儿晓晓的霍普和菲尔，发现咕噜一家成了绊脚石，为了把盖抢过来，他们用上了攻心计。两家人闹得不可开交，盖和小伊也产生了裂痕，却浑然不知危险正慢慢靠近……', '尼古拉斯·凯奇', '乔尔·克劳福德', 7.7, 249791, 'tt2850386', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2624607255.jpg', 0.3, 3, 29.6, 46.2, 20.9, '0.115012,-0.214327,-0.657387,0.340690,-0.035298,-0.316915,0.564956,0.200969,-0.375965,-0.024293,0.125523,0.700248,-0.257333,0.170030,0.356948,0.268558,-0.161812,-0.691199,0.128556,-0.199950,-0.298218,-0.411100,-0.501066,-0.333690,-0.219411,-0.222656,0.228034,0.008004,-0.068454,0.235867,0.010942,-0.133211,-0.399071,0.440025,-0.097885,0.280123,-0.058678,0.066320,-0.361329,-0.018672,-0.108235,-0.185354,0.040585,0.259914,0.155623,0.505069,0.442583,-0.465027,0.206538,-0.166514,-0.125082,-0.472435,-0.185101,0.136733,0.329512,-0.163143,0.279089,0.134763,-0.312557,-0.181888,0.068413,-0.218164,-0.474716,0.092476,0.028058,-0.103137,-0.588573,0.607924,0.174755,-0.104611,0.002766,-0.269465,0.366625,0.392486,0.069542,0.564634,-0.030156,0.197334,-0.385010,-0.130380,0.468262,-0.346802,0.119529,0.421382,0.060589,-0.138829,0.059833,-0.111423,-0.592534,-0.237420,0.417395,0.235986,-0.234180,0.024464,-0.814538,0.056386,-0.372000,-0.407801,0.225307,-0.295137,-0.165862,-0.216623,-0.194640,-0.172316,-0.167479,0.076530,-0.165719,-0.256307,0.377108,-0.767454,-0.080636,0.272479,0.313887,-0.148664,0.541424,-0.106177,0.433417,-0.001687,0.126250,-0.060520,0.031020,0.276138,0.422786,0.324020,-0.171293,0.055394,-0.477839,0.334442', '1783461', '1295416', '1299965', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24299052', '彼得的龙', '儿童', '查穆先生（罗伯特·雷德福 Robert Redford 饰）是一名老木匠，他总喜欢给孩子们讲一个关于龙的故事，故事中的龙居住在位于太平洋西北部的茂密丛林中，查穆先生说他曾经亲眼见证过龙的存在。女儿格蕾丝（布莱丝·达拉斯·霍华德 Bryce Dallas Howard 饰）对于这个父亲已经讲了一百万次的故事不屑一顾，她认为这绝对是父亲信口胡说乱编的故事。一次偶然中，格蕾丝遇见了一个名为彼得（奥克斯·弗格雷 Oakes Fegley 饰）的男孩，男孩告诉格蕾丝，他没有亲人也没有家，唯一的朋友便是一条名叫艾略特的飞龙。皮特的叙述让格蕾丝想到了父亲的故事，两者之间有着惊人的相似，为了证实彼得的话，格蕾丝踏上了寻找龙的旅途。©豆瓣', '奥克斯·费格雷', '大卫·洛维', 6.7, 9453, 'tt2788732', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2359505184.jpg', 2, 11.6, 48, 27, 11.4, '0.286440,-0.277008,-0.404169,0.914728,-0.107186,-0.362009,0.810952,-0.248301,-0.631433,-0.562160,0.082548,0.797484,-0.002989,0.278171,0.244562,0.214252,-0.200617,-0.283956,0.162150,-0.140645,-0.072939,-0.790595,-0.293907,-0.286703,-0.069639,-0.141946,0.319032,-0.152146,-0.304661,0.461796,0.216221,0.427769,-0.016954,0.154747,-0.468315,0.260219,0.132042,0.289906,-0.313054,0.125182,0.042436,0.124861,0.073676,0.356241,0.003773,0.526959,0.369327,-0.608988,-0.177526,0.136275,0.302853,-0.086307,0.157377,0.000015,0.325335,-0.157340,0.376987,0.249668,-0.080429,-0.145367,-0.022620,-0.190928,-0.775531,-0.111973,0.159682,0.291990,-0.466583,0.312550,-0.081263,-0.154533,0.269167,-0.147477,0.366301,0.047710,0.395436,0.281889,-0.045653,0.018702,-0.320514,0.223181,0.623291,-0.012410,-0.066723,0.422265,-0.165453,-0.340140,0.117599,0.049311,-0.444963,0.489036,0.016816,-0.068900,-0.186230,0.249897,-0.552061,-0.160880,-0.206857,-0.169201,0.046911,-0.389034,-0.227441,-0.105934,-0.136799,-0.321700,-0.012664,-0.018050,-0.113380,-0.386561,0.749927,-0.663561,0.318903,0.272553,0.225102,-0.369948,0.796870,0.173867,0.096377,-0.426600,0.102480,0.387220,0.247712,-0.113284,0.051702,0.335471,0.312610,-0.351909,-0.235509,0.533223', '3119246', '1303542', '1456503', '1303077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24299053', '老人和枪', '剧情', '奥斯卡影帝凯西·阿弗莱克（Casey Affleck）日前加盟新片《老人与枪》（Old Man And The Gun），该片由罗伯特·雷德福（Robert Redford）主演，根据《纽约客》上的一篇文章改编。福瑞斯特·塔克（Forrest Tucker）打从少年时就是个不法之徒，抢银行就是他的职业，进过十几次班房的经历还让他练就了“越狱”的本领——一共18次越狱，最近一次时他已70岁高龄！《老人与枪》着重刻画塔克暮年的一次抢劫，罗伯特·雷德福将饰演“塔克”，凯西·阿弗莱克饰演被这位独特罪犯深深吸引的侦探。此外还有67岁的奥斯卡影后茜茜·斯帕塞克（Sissy Spacek），她会饰演爱上这名老年罪犯的女士。《老人与枪》由大卫·劳瑞（David Lowery）导演，福克斯探照灯公司发行，今年4月3日将在辛辛那提开机。', '罗伯特·雷德福', '大卫·洛维', 7, 10038, 'tt2837574', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2536326483.jpg', 0.9, 5.8, 45.3, 38, 10, '-0.012464,-0.390146,-0.266409,0.243611,-0.123725,-0.537241,0.695575,-0.093727,-0.420344,-0.248326,0.513731,0.987070,-0.394736,0.284560,0.640814,0.076242,-0.363876,-0.692559,-0.213171,-0.145497,-0.118732,-0.339997,-0.350992,0.250987,0.036625,-0.599091,0.419529,-0.386256,-0.015594,0.455370,0.299553,0.162541,0.062269,0.029363,0.214924,0.130902,0.374096,-0.374422,-0.312900,0.653099,0.056522,-0.137432,-0.257625,-0.160803,-0.170350,0.543054,0.556725,-0.099491,-0.003270,-0.153329,0.526920,-0.000112,-0.204561,0.003884,0.215669,0.077762,0.221752,0.326385,-0.075184,-0.008356,-0.242851,-0.285782,-0.466700,0.077079,-0.083033,0.076655,-0.540626,0.296793,-0.614066,0.054918,-0.074511,-0.295813,0.010517,0.052345,0.152914,0.073998,-0.103352,-0.018186,-0.327438,0.624759,0.292155,0.100916,-0.125894,0.174659,0.140221,-0.504129,-0.094393,-0.206759,-0.484348,0.328183,0.465829,-0.270670,-0.039673,0.189196,-0.354882,-0.029486,-0.566832,-0.017600,-0.107718,-0.017248,-0.264244,-0.700123,-0.146191,-0.033233,0.051392,-0.271562,0.271690,-0.149798,0.474966,-0.460720,0.251244,0.442875,0.102919,0.376052,0.666173,-0.021038,-0.021014,-0.249106,-0.264548,0.081758,0.241286,0.235687,0.062318,0.461111,0.114252,-0.478097,-0.227955,0.363796', '1829654', '3182864', '34890458', 