INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24304229', '救世', '剧情', '在19世紀70年代美國，一個和平的美國定居者殺害他家人的兇手這釋放出一個臭名昭著的黑幫頭目的憤怒。他的懦弱的傢伙鄉民然後背叛他，迫使他追捕歹徒孤單。故事背景設置在1870年代的美國西部小鎮，一名性格溫和的丹麥移民在失去了家人之後向兇手報仇，然而這讓他成為了當地一個臭名昭著的大惡棍的眼中釘。鎮上貪生怕死的居民全都背叛了他，留下了主人公獨自面對那些不法之徒。丹麥預計2014年10月2日上映的西部劇情片【The Salvation】，入圍第67屆坎城影展競賽片，是丹麥導演克里斯汀‧萊伏林第五部上大螢幕的長片作品，由坎城影帝麥德‧米克森 以及 性感女星伊娃‧格林主演。本片由【勿怕我】克里斯汀‧萊伏林 Kristian Levring自編自導，【謊言的烙印】麥德‧米克森 Mads Mikkelsen、【300壯士：帝國崛起】伊娃‧格林 Eva Green、【紅潮入侵】傑佛瑞‧狄恩‧摩根 Jeffrey Dean Morgan領銜主演。', '麦斯·米科尔森', '克里斯蒂安·莱沃', 7.2, 6262, 'tt2720680', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2213024694.jpg', 0.5, 4.1, 40.9, 41.6, 12.8, '0.368282,-0.096562,-0.544670,0.560411,0.065067,-0.253877,0.443039,0.090975,-0.367409,-0.084716,0.278052,0.918850,-0.140779,0.036253,0.275049,0.205742,-0.368288,-0.607375,-0.269313,-0.466370,0.092770,-0.340794,-0.173220,-0.210876,0.058674,-0.596879,0.734584,0.138191,-0.182786,0.113961,0.362386,0.378330,0.050028,0.082693,0.220240,0.193832,0.089837,-0.432471,-0.247444,0.322597,-0.067522,-0.332314,-0.076849,0.248329,-0.070386,0.616867,0.685366,-0.447179,0.217975,-0.195347,0.473550,-0.648232,-0.143649,-0.016913,0.353946,-0.311659,0.025266,0.494731,-0.138508,-0.187818,0.050113,-0.166623,-0.744732,0.136808,0.054687,0.361618,-0.536793,0.526401,-0.376698,0.204198,-0.030878,-0.126491,0.419606,0.172458,0.039730,0.092450,0.082404,0.043143,-0.438060,0.381673,0.646621,0.013738,-0.134113,-0.027231,-0.289670,-0.322302,-0.304652,-0.434138,-0.653418,-0.102614,0.700329,-0.367529,-0.232514,0.609059,-0.575487,-0.240160,-0.324549,-0.236213,0.063706,-0.082221,-0.100135,-0.574588,-0.105563,-0.403012,0.080435,-0.119553,-0.004302,-0.246517,0.657050,-0.693960,0.299806,0.645891,0.445099,-0.309368,0.574399,0.156880,-0.128166,-0.186992,-0.295868,0.537409,0.297632,0.188754,0.293611,0.047284,0.052360,-0.19084