INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24307625', '屏息', '爱情', '影片《No Breathing》剧本由曾执笔《朝韩梦之队》、《7号房的礼物》等无数人气影片的编剧刘英亚创作。影片名“No Breathing”是游泳专业术语，意指“屏住呼吸后游泳”，本片旨意在于为了展示更好的未来，暂时放慢奋斗脚步的年轻人的热情与执着。影片以游泳竞技为大背景，融合了梦想、友情、亲情等元素。徐仁国饰演放弃过游泳但最终再次挑战的天才型选手，李钟硕则变身为帅气的“国家代表”选手。而权俞利则变身为对音乐怀抱热情，梦想成为音乐家的个性少女。', '李钟硕', '赵容善', 6.7, 13586, 'tt2917646', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2127334318.jpg', 1.7, 10.3, 52.1, 24.3, 11.7, '-0.290506,0.110918,-0.232764,0.709500,0.218676,-0.164103,0.279879,0.384264,-0.261143,-0.343724,0.061671,0.741637,-0.142121,-0.045349,0.412091,-0.603096,-0.169793,-0.807900,-0.372263,0.540336,-0.063774,-0.201744,0.075070,-0.051109,-0.179878,-0.368262,0.997104,-0.137191,-0.505116,0.420912,0.631559,-0.018874,-0.010706,-0.250939,0.132151,-0.421104,0.003138,0.010350,-0.622316,0.263419,-0.126767,-0.174765,-0.124999,-0.186288,-0.086002,-0.062022,0.481480,0.072802,-0.179353,-0.041692,0.493627,-0.312431,-0.074112,-0.227997,-0.054449,0.363960,0.176308,0.021153,0.486749,0.085614,-0.353625,-0.442231,-0.908773,0.143381,0.410054,0.165480,-0.455520,0.242300,-0.097207,-0.342178,0.098114,-0.085856,-0.086822,-0.034848,0.520451,0.183860,-0.163245,0.472399,0.024947,0.374455,0.390135,-0.013917,-0.393622,0.500725,-0.241131,-0.638450,-0.217974,-0.335890,-0.486819,0.144033,0.024576,0.397706,0.428280,0.155679,-0.554055,-0.037522,0.209880,-0.157177,0.262278,-0.616624,0.042432,-0.545862,-0.001015,0.089295,0.253486,-0.230619,0.079109,-0.548510,1.155394,-0.655103,0.185617,0.338235,0.161761,-0.739340,0.773087,0.014780,-0.080303,-0.193188,0.041521,0.428053,0.005836,-0.203271,-0.504128,0.112691,-0.172967,-0.109817,-0.471906,0.431896', '27602116', '25880986', '6101834', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24307637', '江南1970', '剧情', '白勇奇（金来沅 饰）和金钟大（李敏镐 饰）这对落难兄弟无路可去，偶然机会他们帮黑社会打架，擅长打斗的钟大得到老大姜佶秀的赏识，他为了温饱干脆拜入姜的门下。怎奈世事难料，姜在受伤后金盆洗手，试图退出江湖又身不由己。钟大搭上手眼通天的闵夫人，通过热炒地皮闯出名堂。与此同时，在最初的混战中白勇奇阴差阳错加入敌对帮派，凭着一股狠劲他越做越大，成为帮派中一员不可忽视的猛将。在某次行动中，钟大救下了险些被张德才手下杀害的白勇奇，两个好兄弟久别重逢。20世纪70年代的韩国，政客与黑道沆瀣一气，鱼肉乡民，在散发着腐臭气息的名利场，钟大和勇奇这对曾经的好兄弟也渐行渐远……©豆瓣', '李敏镐', '庾河', 6.8, 23363, 'tt3698118', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2219698329.jpg', 2.1, 10.3, 46.9, 28.8, 11.8, '0.330400,0.074475,-0.756634,0.570421,-0.149853,-0.206695,0.529797,0.125737,-0.616663,-0.164106,0.017990,0.700136,-0.224375,0.164754,0.155788,-0.227391,0.157258,-0.839526,-0.238771,-0.148720,-0.037469,-0.350239,-0.374092,-0.041402,-0.404833,0.081627,0.508434,0.349879,-0.334729,0.539459,0.475335,0.196844,-0.216690,0.312796,-0.376740,0.031791,-0.052275,0.218923,-0.419579,-0.110400,0.006171,-0.316255,-0.078338,-0.162004,0.087791,0.245287,0.209073,-0.174321,0.190629,-0.055406,0.091240,-0.211006,-0.043946,-0.028712,0.507404,0.054869,0.247341,0.244715,0.005607,-0.186948,-0.239606,0.007866,-0.755995,0.169693,0.256490,-0.034435,-0.823586,0.538655,0.093269,-0.138186,-0.093998,-0.134327,0.133281,0.259500,0.245456,0.024661,-0.102951,0.340980,-0.484351,-0.003840,0.863300,-0.100380,0.043784,-0.058579,0.185886,-0.358741,0.060603,-0.545933,-0.169144,-0.236336,0.447685,-0.231832,-0.106891,0.215465,-0.524658,0.131006,0.046286,0.205297,0.064219,-0.093023,0.157235,-0.451456,-0.429247,-0.318081,-0.138196,0.422095,0.109942,-0.231383,0.681959,-0.665351,0.036291,0.343428,0.396601,-0.375029,0.638394,0.282826,0.147469,-0.195935,-0.479749,-0.085842,0.287304,0.320498,0.549990,0.289111,-0.301688,-0.154692,-0.195991,0.077813', '25721544', '1897368', '1293829', '25908042');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24321138', '世界奇妙物语 2013年春之特别篇', '悬疑', '《诅咒Web》在职场饱受上司苛责训斥的OL吉田美咲（佐佐木希 饰）偶然发现一个诅咒网站，抱着玩乐好奇心态她输入上司的名字，谁知诅咒竟然成真。越陷越深的美咲，身心紧紧被贪痴欲望所缠缚；《石油出来了》经济大萧条背景下的日本，无业青年汤元义弘（丸山隆平 饰）的尿竟突然变成石油。逃脱了相关机构的追赶，汤元来到一个僻静的乡下，用自己的石油小便造福当地；《Air医生》憧憬成为外科医生的私立医大学生桐原亨（小栗旬 饰），在他乘坐的飞机上，不得不以医者身份面对患者，以及一群有着不同背景的莫名乘客；《不死身丈夫》厌倦了丈夫副岛圭介（尾美としのり 饰）完美温柔的举止，家庭主妇三惠（檀丽 饰）决意杀死丈夫，谁知圭介一次次死而复生，永无止境；《楼梯的花子》暑假在校值班的小学教师相川英树（徳井义实 饰）接待了此前来校实习的小谷千纱子（大政绚 饰），他们聊起了“楼梯花子”的恐怖传说以及不久前某个女孩死去的真相。', '小栗旬', '铃木雅之', 7.8, 14177, 'tt2891888', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2153892011.jpg', 0.2, 1.4, 25.4, 54.2, 18.8, '0.076619,0.066756,-0.365697,0.307403,-0.130641,-0.129588,0.507696,0.314051,-0.373340,-0.454949,0.432806,0.490028,-0.165298,0.443991,0.211367,0.052785,-0.007397,-0.486520,-0.179450,0.113638,-0.289071,-0.218652,-0.177013,-0.159075,-0.091247,-0.266605,0.532862,-0.022290,-0.290770,0.231907,0.328865,0.443140,-0.120788,0.211169,-0.270935,-0.050571,0.133078,-0.046333,-0.030084,0.020787,-0.174005,-0.275261,0.062553,0.007045,-0.069159,0.293847,0.640108,-0.103275,-0.167098,-0.162061,0.532015,-0.154002,-0.145079,0.217778,0.259828,0.140139,0.043866,-0.106594,-0.163564,-0.060517,0.259843,0.032206,-0.441419,-0.095557,-0.018031,0.312159,-0.339687,0.299223,-0.050199,-0.003396,0.066605,-0.229728,-0.099215,-0.133408,-0.001129,0.529703,-0.143747,0.224921,-0.317775,0.248636,0.417313,0.068605,-0.209200,0.282625,-0.307681,-0.168460,0.122719,-0.296172,-0.354800,-0.155629,0.215411,-0.123196,-0.244174,0.126602,-0.445839,-0.142897,-0.147523,0.188224,0.023116,-0.140247,-0.154534,-0.567036,0.011521,-0.219757,-0.240202,0.127845,0.206434,-0.159242,0.708855,-0.603081,0.119535,0.544217,0.118264,-0.486396,0.318145,0.020342,-0.018520,-0.182700,-0.201818,0.493624,0.146680,0.389539,-0.102702,0.370206,-0.312988,-0.074108,-0.294425,0.167744', '3811356', '25922902', '10174444', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24324730', '爸妈不在家', '剧情', '家乐（许家乐 饰）是个聪明却调皮捣蛋被学校视为头痛份子的小孩，怀孕的母亲（杨雁雁 饰）每天在公司和家事两边忙碌分身乏术的情况下，还会接到学校的抱怨电话总是相当无奈，最后只好找来菲律宾女佣泰莉（安吉莉·芭雅妮 Angeli Bayani 饰）来帮忙家事和照顾家乐。一开始相当排斥泰莉的家乐利用各种机会欺负她，但是为了要养家活口的泰莉只能努力在这个家庭里生存。家乐因为爸妈各自烦恼着自己的事情无暇关注他的情况下，让家乐和泰莉两人逐渐产生越来越深厚的感情，但是小小年纪的家乐却没有发现家庭风暴也日趋严重……而这是1997年，亚洲金融危机正在悄悄影响这个国家……©豆瓣', '杨雁雁', '陈哲艺', 8, 34831, 'tt2901736', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2007356495.jpg', 0.2, 0.8, 19, 60.5, 19.5, '0.423920,-0.112751,-0.711533,0.400744,-0.087131,-0.267894,0.604804,0.282029,-0.622243,-0.538362,-0.201362,0.452385,0.038161,0.408957,0.000911,-0.064682,-0.379614,-0.525460,0.090823,0.055619,-0.314220,-0.431580,-0.117051,-0.360533,-0.342927,-0.016660,0.131687,-0.144561,-0.149567,0.429497,0.104767,0.378487,0.056989,0.740667,-0.073881,0.034940,-0.112548,-0.017719,-0.067465,0.018489,0.304140,-0.155267,-0.363683,0.334260,0.288681,0.505844,0.555815,0.095939,-0.314819,-0.204045,0.399621,-0.361490,-0.163806,0.008476,0.628847,-0.151738,0.385414,-0.078905,-0.361145,0.002218,0.178175,-0.089103,-0.754357,0.039029,0.152882,0.049066,-0.639321,0.206019,0.030811,-0.187036,0.065679,-0.547829,0.229236,0.549653,0.031814,0.416184,-0.462510,0.077364,-0.430055,0.020947,0.619910,0.094852,0.046997,0.365214,-0.440179,-0.145698,0.063825,-0.392192,-0.672457,-0.127863,0.011648,0.137930,-0.240469,0.213580,-0.446703,0.151084,-0.140709,-0.418608,-0.081663,-0.539717,0.121655,-0.435985,-0.319881,-0.554390,-0.612204,0.178007,0.054999,-0.202806,0.775705,-0.862707,0.042861,0.562717,0.278674,-0.753900,0.619782,0.339696,0.207876,-0.095802,-0.126469,-0.177500,-0.292426,0.076600,0.003736,0.249221,0.235672,-0.294084,-0.051256,0.240345', '1877596', '1308206', '1301022', '1308805');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325798', '单亲度假村', '喜剧', '在如今这个离婚率飞速增长的年代，单亲妈妈和单亲爸爸早已经不是什么稀罕的“物种”了，这不，吉姆（亚当·桑德勒 Adam Sandler 饰）和劳伦（德鲁·巴里摩尔 Drew Barrymore 饰）就分别是这庞大队伍中的一员。一场相亲让本来毫无交集的两人牵扯到了一起，没想到，这场相亲最终沦为了一场灾难，愤怒之中，两人发誓一刀两断，永不再见。然而，这个誓言的效力却没能够持续多久，在一个前往非洲的旅行团中，吉姆和劳伦再次相遇，这一次，凑到一起的不仅仅是他们两人，还有他们各自古灵精怪的孩子们，一趟充满了自由与野性的旅途中，会发生怎样有趣的故事呢？吉姆和劳伦又该如何面对彼此之间根深蒂固的偏见与矛盾呢？©豆瓣', '亚当·桑德勒', '弗兰克·克拉斯', 7.4, 20069, 'tt1086772', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2163157487.jpg', 0.7, 4, 36.3, 43, 16.1, '0.445834,-0.007689,-1.049219,0.493723,-0.162363,-0.345347,0.883356,-0.229191,-0.522730,-0.030998,-0.058514,0.853250,-0.279172,0.257349,0.184121,-0.142647,-0.337747,-0.825680,-0.004496,-0.219220,-0.465782,-0.586465,-0.441019,-0.028991,-0.053557,0.009555,0.501762,0.072365,-0.022335,0.687882,0.422839,0.259527,-0.277265,0.554696,-0.204829,0.259755,0.341217,0.392023,-0.380959,0.119204,0.273362,0.025840,-0.269604,0.065644,0.052548,0.224278,0.406134,-0.350537,-0.003784,-0.081643,0.171454,-0.237282,-0.267523,0.327373,0.238606,-0.235741,0.341393,0.146636,-0.142743,-0.077836,-0.052781,0.057292,-0.740643,0.156632,-0.017485,0.348497,-0.605410,0.546300,0.103242,-0.511441,0.181865,-0.122503,0.196247,0.809312,0.405373,0.342057,-0.170163,-0.244712,-0.566432,-0.082273,1.199439,0.070426,-0.397176,0.220871,-0.099627,-0.353628,-0.137758,-0.159940,-0.628757,0.001706,0.220078,0.186260,-0.217696,0.462923,-0.729526,0.143921,-0.217884,-0.179072,-0.022307,-0.484108,0.044487,-0.381283,-0.225827,-0.997267,-0.340555,0.128673,0.152888,-0.132169,0.660952,-0.940486,0.262702,0.312587,0.367468,-0.553692,0.619447,0.387531,0.270309,-0.183879,0.103313,-0.179430,-0.251698,0.151234,0.404196,0.464493,0.442966,0.087454,-0.326738,0.610930', '25721544', '26320029', '1308755', '1293077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325815', '幻体：续命游戏', '科幻', '曾在纽约建筑界享有极高声誉的富豪马丁·戴米恩（本·金斯利 Ben Kingsley 饰），而今饱受癌症折磨，不得不面对即将在半年后去世的事实。除此之外，他与女儿克莱尔的关系始终处于冰封状态，这令他不仅慨叹金钱的无力。不久前，马丁与菲尼克斯生物科技公司取得联系，对方声称使用最先进的脱换技术可以帮助马丁重获新生，简而言之就是将他的意识或者灵魂注入一具更加年轻健康的躯体内再生。经过慎重的考虑，马丁以爱德华·基德纳（瑞恩·雷诺兹 Ryan Reynolds 饰）的身份复活。此后的一段时间里，爱德华尽情享受重返青春的乐趣。与此同时，这具陌生躯体背后所隐藏的秘密，则让他渐渐感到不安……©豆瓣', '瑞安·雷诺兹', '塔西姆·辛', 6.5, 37897, 'tt2140379', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350187311.jpg', 1.7, 11.3, 53.9, 25.8, 7.3, '-0.167717,0.241764,-0.725140,0.480560,-0.188247,-0.200440,0.437291,0.198994,-0.682259,-0.692216,0.165183,0.638056,-0.041653,0.310334,0.220238,-0.051693,-0.213397,-0.393630,-0.015846,-0.015715,-0.125574,-0.445583,-0.537751,-0.277910,-0.204762,-0.779860,0.738232,0.072756,-0.371187,0.252021,0.028798,0.551767,0.066693,0.250877,-0.018331,-0.280120,0.032747,-0.070518,-0.523101,0.141695,0.271825,-0.252229,0.311117,0.201626,0.023875,0.245554,0.634001,-0.301329,-0.187254,-0.295782,0.480623,0.020956,-0.035994,0.098219,-0.062019,0.070973,0.192360,0.357970,-0.483640,-0.017231,0.147868,-0.102314,-0.990243,-0.109857,0.074542,0.008821,-0.287412,0.276010,-0.128937,0.202139,0.076062,-0.112568,0.145017,0.374169,0.056131,0.457944,-0.245741,0.192408,-0.279456,0.010725,0.601458,-0.006222,-0.478850,0.310679,-0.384995,-0.285030,-0.164837,-0.272756,-0.330529,-0.218645,0.066325,0.566658,-0.072410,0.378365,-0.406196,-0.052588,-0.408602,-0.167497,0.072449,-0.114786,0.195991,-0.519853,-0.234569,-0.217568,-0.047582,-0.242807,-0.020170,-0.434492,0.596522,-0.674376,0.328620,0.358923,0.400969,-0.484159,0.399135,0.141223,0.397750,-0.457286,-0.260830,0.837037,0.116313,0.035035,-0.017604,-0.064797,-0.080684,0.069284,-0.502988,0.628569', '10440076', '26667010', '1793491', '3001114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325829', '电力之战', '剧情', '故事发生在19世纪的英国，第二次工业革命正在如火如荼的推进之中，当时最知名的两位电力企业家分别是爱迪生（本尼迪克特·康伯巴奇 Benedict Cumberbatch 饰）和威斯汀豪斯（迈克尔·珊农 Michael Shannon 饰），他们将彼此视作是自己的死对头，势均力敌，针锋相对。爱迪生是直流电的发明者，他高傲，自大，野心满满，在当时树敌颇多。某日，一位名为特斯拉（尼古拉斯·霍尔特 Nicholas Hoult 饰）的男子发明出了异于爱迪生的交流电，为了抢占市场，威斯汀豪斯火速向特斯拉抛出了橄榄枝，邀请他为自己工作。交流电的出现再一次改观了人们对电力的理解，大大推动了革命进程。©豆瓣', '本尼迪克特·康伯巴奇', '阿方索·戈麦斯-雷洪', 6.4, 13619, 'tt2140507', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2616761863.jpg', 0.9, 11.3, 57.6, 25.3, 5, '0.286284,0.015764,-0.614898,0.481658,-0.140130,-0.163411,0.693946,-0.004937,-0.554088,-0.134233,0.310248,0.856186,-0.289445,-0.013454,0.211110,-0.090169,-0.113136,-0.521335,0.026635,-0.189180,0.064573,-0.674490,-0.467146,-0.257041,-0.015872,-0.282219,0.332649,-0.042520,-0.500760,0.324748,0.321346,0.370170,0.283448,0.520702,-0.127166,-0.002728,-0.084344,-0.326892,-0.294527,0.207844,-0.106813,-0.271599,-0.150996,0.211886,-0.093067,0.341813,0.315829,-0.363684,-0.047477,-0.087964,0.515621,-0.121927,-0.078257,0.027244,0.144538,0.160523,-0.045165,0.064863,-0.076874,0.032847,0.018847,-0.168756,-0.681849,-0.038028,-0.309471,0.317460,-0.812945,0.583896,-0.125379,-0.057320,0.048152,-0.199169,-0.001747,0.227686,0.214875,0.393980,-0.070679,0.051838,-0.479843,0.203437,0.623359,0.137922,-0.195965,0.402883,-0.323993,-0.263583,-0.205167,-0.066414,-0.364022,-0.287942,0.426500,-0.120746,0.273972,0.567416,-0.565384,-0.059442,-0.271036,-0.139248,0.165828,-0.281213,0.037047,-0.835485,-0.077267,-0.528471,-0.027673,0.089734,0.043423,-0.372422,0.678343,-0.934361,0.040973,0.396347,0.215178,-0.268964,0.627585,0.089005,-0.111476,-0.332279,-0.321972,0.123429,0.017743,0.033016,-0.136264,0.483602,0.341213,-0.177893,-0.203188,0.372294', '1783461', '26259202', '20277433', '26971054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325856', '全民追女王', '喜剧', '夏洛特（查理兹•塞隆Charlize Theron 饰）身在美国国务卿之位，一次偶然中，她得知现任的总统（鲍勃•奥登科克 Bob Odenkirk 饰）并不准备参加连任竞选，一直认为自己能力出众的夏洛特终于得到了竞选总统之位的机会。目标已经决定了，夏洛特身边的团队很快 的组建并运转了起来，他们找到了演讲作家弗莱德（塞斯•罗根Seth Rogen 饰）替夏洛特撰写演讲稿。实际上，夏洛特和弗莱德是旧相识了，在夏洛特很小的时候，她曾经在弗莱德家做过保姆。青梅竹马的两人一经见面，曾经无忧无虑的童年往事纷纷浮现，弗莱德发现自己对夏洛特的爱意死灰复燃，可是，在一切都物是人非的今天，这段感情真的会有结果吗？©豆瓣', '查理兹·塞隆', '乔纳森·莱文', 6.6, 13055, 'tt2139881', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2552599434.jpg', 2.3, 11.2, 50.6, 27.2, 8.6, '0.055442,0.112295,-0.740761,0.572284,-0.157202,-0.549477,0.410638,-0.007806,-0.732333,-0.455998,-0.104815,0.982606,-0.305971,0.408394,0.282652,0.096962,-0.431645,-0.838388,0.101422,-0.309674,-0.145620,-0.784197,-0.219676,-0.333792,-0.088053,-0.309236,0.515697,-0.034664,-0.020505,0.469095,0.455621,0.094528,0.225363,0.456632,-0.063171,-0.077516,0.374642,0.105013,-0.457175,0.117359,0.118982,-0.156375,-0.129691,0.290307,0.424248,0.394977,0.260931,-0.276292,-0.056236,-0.073171,0.151874,-0.058001,0.233199,0.065575,0.429484,0.132217,0.222569,0.437575,-0.107003,-0.020418,-0.030525,-0.255260,-0.615012,0.081928,-0.036676,0.166542,-0.507054,0.488129,-0.174800,-0.066878,0.075061,-0.257759,0.131155,0.528372,0.237676,0.149826,-0.103847,0.053197,-0.424092,0.187971,0.612793,0.153730,-0.170121,0.541926,-0.106636,-0.374474,-0.144332,0.018648,-0.296832,0.173941,0.224739,0.229057,-0.073749,0.366964,-0.261888,-0.240610,-0.274351,-0.130833,0.131717,-0.447553,0.137140,-0.653275,-0.301477,-0.141212,-0.261678,-0.137732,-0.094621,-0.304605,0.580805,-1.077615,0.325187,0.356212,0.172689,-0.399682,0.433674,0.426918,0.103440,-0.302171,0.085405,0.377202,-0.120540,0.135044,0.146263,0.123955,0.219421,-0.323534,-0.395955,0.678550', '26971054', '30345227', '1306133', '1299556');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325861', '会计刺客', '动作', '沉默而神秘的数学天才克里斯蒂安·沃尔夫（本·阿弗莱克饰），从事的则是默默无闻的会计行业，专门为世界各大犯罪机构做账。随着财政部官员雷·金（J·K·西蒙斯饰）对于金融犯罪的关注，克里斯蒂安找来一家合法人工智能公司客户作为掩护，而该公司的会计（安娜·肯德里克饰）似乎发现了上百万美元的财务差额。克里斯蒂安接下来要面对的不仅是当局的调查，还有更严重的人身危险。', '本·阿弗莱克', '加文·欧康诺', 7.6, 78833, 'tt2140479', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2355993802.jpg', 0.5, 3.4, 30.3, 46.9, 19, '0.138006,0.015103,-0.488360,0.418899,0.056186,-0.140043,0.278049,0.361621,-0.702463,-0.540143,0.119246,0.519206,0.228693,0.016889,0.422146,0.003925,-0.210349,-0.689099,-0.334093,-0.256540,-0.361803,-0.872777,-0.277163,-0.527722,-0.163276,-0.060303,0.428840,0.078534,-0.158375,0.080563,0.440154,0.673526,0.023413,0.001788,0.220664,-0.605009,0.525136,-0.133561,-0.373325,0.157372,0.143740,-0.063216,0.023674,-0.109398,0.388492,0.417081,0.217677,0.060520,-0.169863,-0.328295,0.547909,-0.172703,0.041083,-0.287224,0.475762,0.044222,0.337325,0.368333,-0.224710,0.032481,0.161628,-0.261692,-0.982787,0.071341,0.335763,0.354400,-0.405819,0.105774,-0.199668,-0.139554,-0.077889,-0.280539,-0.020289,0.516944,0.311449,0.286880,0.147111,0.235533,-0.205187,0.304040,0.115633,0.223212,-0.096216,0.091279,-0.245783,-0.449463,-0.177060,-0.338524,-0.128735,0.005905,0.199134,0.070612,0.224582,0.208919,-0.636998,-0.122694,-0.106744,-0.313644,-0.023679,-0.375336,-0.020848,-0.750776,0.069165,-0.264860,-0.014392,0.230993,0.506491,-0.015089,0.566120,-0.751946,-0.114538,0.591595,0.393155,-0.727993,0.586482,-0.187995,0.102454,-0.470771,-0.294813,-0.095011,0.298180,0.273957,-0.286570,-0.103379,0.372728,-0.690198,0.025309,0.079267', '1307442', '1297689', '3428500', '1498811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325872', '下流祖父', '喜剧', '杰森（扎克·埃夫隆饰）是位一板一眼的准新郎，过着无趣保守的生活，被重度控制狂未婚妻使唤，结婚前夕，他去陪刚丧偶的爷爷迪克（罗伯特·德尼罗饰）度假散心，爷爷生性好色，带着保守的孙子踏上了一段啼笑皆非的风流旅程。', '罗伯特·德尼罗', '丹·马泽', 6.3, 17643, 'tt1860213', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2305978591.jpg', 3.3, 15.6, 50.3, 22.6, 8.2, '0.212806,-0.201211,-0.583686,0.136431,-0.474083,-0.529683,0.628548,0.234777,-0.486174,-0.146524,0.077188,0.667855,-0.190352,0.432396,0.582080,0.390791,-0.220920,0.112412,-0.038321,0.286517,0.037707,-0.470250,0.015128,0.185817,-0.178890,-0.495928,-0.125812,-0.260295,0.000458,0.720917,0.198554,0.229600,-0.050247,0.151794,-0.342137,-0.059387,0.001009,-0.000108,-0.126697,0.142318,0.374593,0.172420,-0.034070,-0.041292,0.096574,0.344649,0.511979,0.116520,0.096569,0.026578,0.110195,-0.155147,-0.372201,0.121987,0.060874,0.019495,0.113400,0.191429,-0.113099,-0.029967,-0.046711,-0.345417,-0.206110,0.226885,-0.138327,0.039996,-0.635058,0.460852,-0.238909,-0.130039,-0.009400,-0.526622,0.122376,0.217421,-0.065905,0.357980,0.015387,0.469566,-0.223700,0.523022,0.743714,0.094917,-0.151057,0.142179,-0.131083,0.041654,0.368731,-0.509254,-1.013974,-0.277259,0.261023,-0.599396,-0.227292,0.107317,-0.319509,0.114424,-0.225946,-0.008097,0.057908,-0.240216,-0.188645,-0.344325,0.153891,-0.457902,0.035478,0.003248,0.040613,-0.132650,0.402340,-0.507937,0.613878,0.754604,0.062653,-0.479076,0.509010,0.231781,0.153897,-0.164217,0.170960,0.393826,0.007582,-0.011345,0.098742,0.621430,0.072025,-0.131388,-0.521026,0.491470', '1297606', '1291565', '2910660', '2251924');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325918', '极端邪恶', '惊悚', '利兹（莉莉·科林斯 Lily Collins 饰）是一名单亲妈妈，和年幼的女儿过着相依为命的生活，日子并不容易。一次偶然中，利兹邂逅了名为泰德（扎克·埃夫隆 Zac Efron 饰）的男子，泰德自称是法律系的学生，并且对利兹表现出了浓厚的兴趣。随着时间的推移，利兹和泰德渐渐的走到了一起，泰德的温柔和体恤让利兹重新燃起了对未来生活的希望。然而，渐渐的，利兹在泰德的身上发现了他不为人知的一面。凡是泰德经过的州省，屡屡传来少女失踪案和谋杀案，虽然泰德坚称这一切和他没有任何的关系，但他还是成为了FBI的头号通缉犯。在法庭上，泰德据理力争为自己辩护，他的言之凿凿让利兹陷入了混乱之中。©豆瓣', '莉莉·柯林斯', '乔·伯灵格', 6.7, 8557, 'tt2481498', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2552505334.jpg', 1.7, 8.5, 52.5, 29.9, 7.5, '0.437735,0.017616,-0.851997,0.785801,-0.293657,-0.485206,1.076872,0.123972,-0.975077,0.020627,0.053520,0.873946,-0.216873,0.329698,0.308480,0.194538,-0.389159,-0.924433,0.026878,-0.231444,-0.318369,-0.666889,-0.432792,-0.022531,-0.337172,-0.495562,0.543296,0.105888,-0.043589,0.582321,0.254918,0.227820,0.090602,0.536505,-0.316989,0.192388,0.226285,0.020193,-0.229127,0.051724,0.094049,-0.128578,-0.318353,0.100047,0.115152,0.579549,0.459321,-0.260056,-0.049491,-0.000044,0.356033,-0.187814,0.176676,0.183760,0.052792,0.066535,0.294559,0.343180,-0.391060,-0.041180,0.052310,-0.057141,-0.637363,0.108370,-0.022870,0.372097,-0.937768,0.763659,-0.139968,-0.576063,0.306722,-0.201142,0.095067,0.487949,0.066679,0.340320,-0.086020,-0.174695,-0.415689,-0.091173,0.725176,0.045791,-0.454244,0.372830,-0.321628,-0.299301,-0.095799,-0.141556,-0.562525,-0.178503,0.421043,0.248276,-0.240414,0.461201,-0.516734,0.103980,-0.204531,-0.446123,-0.012003,-0.411627,-0.098514,-0.511814,-0.206136,-0.843722,-0.534562,-0.056135,-0.130155,-0.244562,0.762321,-1.133025,0.341983,0.567566,0.180459,-0.196144,0.543729,0.375076,0.201216,-0.087029,-0.055597,0.128401,0.050060,0.467259,0.354161,0.562933,0.058730,-0.180990,-0.434590,0.770559', '3111650', '35030151', '20277433', '3230121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24325923', '我和厄尔以及将死的女孩', '剧情', '高中生格雷戈（托马斯·曼 Thomas Mann 饰）性格善良却有点孤僻，他唯一的爱好是与死党厄尔（RJ·赛勒 RJ Cyler 饰）拍摄短片，改编他们喜爱经典电影，自娱自乐。有一天，格雷戈结识了身患白血病的女孩蕾切尔（奥利维亚·库克 Olivia Cooke 饰），乐观开朗的蕾切尔改变了格雷戈原有的世界，两人十分谈得来，格雷戈逐渐对蕾切尔萌生爱意，却不好意思说出口。就在此时，蕾切尔的病情加重，格雷戈意识到自己必须有所行动……本片改编自杰西·安德鲁斯的同名小说，影片剧本曾被誉为2012年的剧本黑名单。', '托马斯·曼', '阿方索·戈麦斯-雷洪', 8.2, 86768, 'tt2582496', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2263553175.jpg', 0.2, 1.3, 17.4, 50.5, 30.6, '0.145607,-0.112532,-0.543770,0.397032,-0.067284,-0.311321,0.765170,0.316741,-0.470929,-0.054260,0.153433,0.696998,-0.392870,-0.170332,0.332896,0.429158,-0.814261,-0.475247,0.295311,-0.380201,0.442594,-0.845736,-0.326749,0.212025,-0.091153,-0.915849,0.408614,-0.451578,-0.165598,0.307480,0.107705,0.394848,0.361878,0.243364,0.330693,0.304408,0.320065,-0.434316,-0.177562,-0.245865,0.083710,0.255774,-0.448784,0.205898,0.293002,0.581735,0.582557,-0.240881,-0.103054,0.298223,0.506565,-0.024575,-0.060365,-0.263498,0.276968,-0.268604,0.402073,0.192641,-0.019858,-0.137610,-0.146201,-0.080032,-0.521423,0.381283,-0.051604,0.307654,-0.303291,-0.027961,-0.445559,-0.220930,-0.040178,-0.353093,-0.291795,0.292922,0.539373,0.200317,0.147753,0.013659,-0.137550,0.146545,0.270076,0.256252,-0.705571,0.626786,-0.701845,-0.259195,-0.195440,0.011019,-0.721014,-0.036791,0.535371,-0.283199,-0.107096,0.302740,-0.019679,-0.104003,-0.320590,-0.255127,0.164451,-0.398030,-0.228902,-0.749858,-0.416118,-0.323287,-0.184906,-0.858066,0.013975,-0.241395,0.871506,-0.709144,0.198362,0.593761,0.008014,-0.358836,0.292874,-0.013380,-0.233618,-0.238592,-0.094563,0.804976,-0.242911,-0.399971,0.096210,0.424383,0.174974,-0.036165,-0.184904,0.569049', '26917393', '3718460', '26348103', '2364001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24397586', '小羊肖恩', '喜剧', '厌倦了每天千篇一律的枯燥生活，小羊肖恩决定做些改变。他煽动同伴们参与了他的计划，引开狗狗比泽尔的同时，将农夫催眠。可是他们的快乐假日还没开始，意外突然发生。关着农夫的拖车厢失去控制，一路向市中心冲去。比泽尔命令羊羊们回到农场，自己则惊慌失措地跑去营救农夫。好不容易醒来的农夫根本搞不清发生了什么状况，随后头部遭受撞击失去了记忆。另一边，农场在三只肥猪的祸害下沸反盈天，乱作一团。肖恩、提米、雪利他们都开始怀念一本正经的农夫了。一不做二不休，肖恩背起行囊混上了开往市中心的巴士，他的伙伴们也不打招呼尾随而至。怎奈城市的情况极其复杂，冷酷无情的抓狗人更成为羊羊们难以逾越的障碍……©豆瓣', '贾斯汀·弗莱彻', '马克·伯顿', 8.4, 101523, 'tt2872750', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2249261202.jpg', 0.2, 0.9, 14, 46.5, 38.3, '0.462895,-0.229441,-0.516881,-0.034429,-0.064439,-0.093802,0.737984,0.229819,-0.255173,0.035580,0.279655,0.211864,-0.003487,0.169714,0.248383,-0.022564,-0.500727,-0.475979,0.000909,0.109387,-0.242798,-0.144414,-0.023256,-0.493331,0.017743,-0.080195,0.331636,-0.065115,-0.217019,0.372603,0.174084,0.062930,-0.192974,0.617433,-0.393788,0.295486,-0.192699,-0.147493,0.120607,-0.186133,-0.045270,-0.345165,-0.283962,0.050469,0.174481,0.315580,0.827365,-0.278272,-0.152733,-0.122014,0.116346,-0.225582,-0.018652,0.103199,0.308485,0.135063,-0.294927,-0.128990,0.029948,0.041167,0.083878,0.054688,-0.450744,0.161350,-0.103042,0.176479,-0.637099,0.129554,0.069742,0.205582,0.312244,-0.586347,0.035210,0.446040,0.043699,0.396864,-0.115854,0.188949,-0.630770,0.090821,0.929779,-0.152466,-0.268260,0.263646,-0.202677,-0.196177,-0.097540,-0.047963,-0.303331,-0.411770,0.561798,0.091711,-0.505533,0.275740,-0.385437,-0.010559,-0.134386,-0.519005,-0.215162,-0.344688,-0.186360,-0.569373,0.244279,-0.060012,0.023498,0.032726,-0.106595,-0.061077,0.416215,-0.472910,0.217493,0.559013,0.294603,-0.291757,0.434329,-0.362841,0.117227,-0.084930,0.116072,0.348937,0.122259,0.677982,0.421104,0.270567,-0.229520,0.062740,-0.329560,0.437191', '21619567', '25837175', '26418093', '7155005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24404677', '超体', '动作', '被恶德男友强迫帮人送货的年轻女子露西（斯嘉丽·约翰逊 Scarlett Johansson 饰），遭遇了穷凶恶极的黑帮头目张先生（崔岷植 饰）一伙。她连同三个男人被张先生在腹部缝入了代号为CPH4的神秘药品，以此将药品偷偷带入不同国家。在台北盘桓期间，露西遭到恶男暴打，以致药品破裂进入血液之中。谁知令人难以置信的事情就此发生，药品激发了露西大脑的潜力，令人脑中约90%的神经元相继苏醒。伴随着身体的飞快进化，露西掌握了越来越多人们所谓的超能力。她清楚地了解到CPH4所拥有的强大威力，于是想方设法要阻止其他三袋药品落入张先生一伙手中。期间她试图与大脑研究方面的资深教授塞缪尔·诺曼（摩根·弗里曼 Morgan Freeman 饰）取得联系，在后者的见证下，露西将迎来大脑100%苏醒的历史性时刻……©豆瓣', '斯嘉丽·约翰逊', '吕克·贝松', 7.4, 534715, 'tt2872732', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2201909284.jpg', 1, 5.4, 34.5, 40.4, 18.7, '0.191482,0.291230,-0.412516,0.239702,0.020002,-0.092154,0.692657,0.013877,-0.440786,-0.302706,0.138825,0.402198,-0.249590,0.146220,0.204948,-0.091922,-0.130642,-0.630821,-0.054998,-0.074649,-0.342717,-0.486007,-0.222585,-0.139868,-0.066961,-0.689961,0.487469,-0.027658,-0.404676,0.086647,0.081574,0.385798,-0.191488,0.263308,0.049592,-0.118355,0.265916,-0.354952,-0.246815,0.152012,0.338411,-0.432620,0.076732,0.128648,-0.025537,0.180875,0.666490,-0.231049,0.018199,-0.085169,0.404239,-0.081978,0.039847,0.209958,0.310742,0.392387,-0.053447,-0.073422,-0.293525,0.009670,0.323736,0.146493,-0.701761,-0.020355,0.223520,0.143660,-0.596445,-0.084662,-0.164122,0.144951,0.241783,-0.343650,0.114493,0.234742,0.362230,0.225380,0.076645,0.085757,-0.301132,-0.030717,0.606767,-0.170883,-0.283844,0.066403,-0.130204,-0.446499,-0.281335,-0.078365,-0.276717,-0.109002,0.405541,0.252590,0.040464,0.458488,-0.617320,-0.035304,-0.326703,-0.227508,-0.068526,0.125922,-0.140333,-0.686382,-0.332982,-0.082363,-0.029732,0.017663,0.170139,-0.265861,0.753503,-0.610671,0.061546,0.592812,0.371632,-0.215999,0.318466,-0.161040,0.131125,-0.277150,-0.168918,0.113246,0.549813,0.150694,0.203367,0.416949,-0.085750,0.057287,-0.184693,0.364260', '3811356', '1292680', '3005387', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24405378', '王牌特工：特工学院', '喜剧', '哈里（科林·费斯 Colin Firth 饰）是英国秘密特工组织金士曼中的一员，某次行动中，他的战友不幸牺牲，哈里将一枚徽章和一个电话号码交给了战友年幼的小儿子艾格西（亚历克斯·尼科洛夫 Alex Nikolov 饰），叮嘱他将来如果遇到了什么麻烦可以拨打这个号码，然而，这样的机会只能使用一次。一晃眼十七年过去，破碎的家庭让艾格西（塔伦·埃格顿 Taron Egerton 饰）成长为了一个整日无所事事的小混混，某日，因为违反交通规则而遭到逮捕的艾格西使用了手中珍贵的号码，赶来的哈里在艾格西玩世不恭的外表之下发现了他善良的本质和极高的天赋，于是，哈里决定将艾格西培养成为新一代金士曼，他们需要共同面对的是强大而又邪恶的亿万富翁瓦伦丁（塞缪尔·杰克逊 Samuel L. Jackson 饰）。©豆瓣', '塔伦·埃哲顿', '马修·沃恩', 8.4, 634239, 'tt2802144', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2231932406.jpg', 0.3, 1.3, 14.5, 46.6, 37.3, '0.465507,0.228928,-0.579219,0.840145,-0.460777,-0.322837,0.573328,-0.059300,-0.336524,-0.566620,-0.164132,0.713676,0.047360,0.085168,0.326484,0.025684,-0.070315,-0.614923,0.046668,-0.314038,-0.387984,-0.685644,-0.249340,-0.585872,-0.087528,-0.415942,0.476016,0.255900,-0.214153,0.395099,0.408574,0.474573,0.114838,0.200496,-0.246135,-0.198936,0.144749,-0.144930,-0.119408,0.554684,0.247810,0.035362,0.144262,0.460494,0.121928,0.293208,0.528629,-0.341225,-0.033916,-0.210418,0.410007,-0.289549,0.142508,-0.084898,0.455508,0.197572,0.000792,-0.068686,-0.095276,0.117361,0.209584,-0.189125,-0.756864,-0.264895,0.000748,-0.075981,-0.679377,0.207520,-0.210804,-0.070428,0.074721,-0.208353,0.205078,0.380864,0.465717,0.267546,0.144989,0.068444,-0.374246,-0.044299,0.301804,-0.129631,-0.113733,0.184855,-0.350885,-0.562655,0.158659,-0.251565,-0.594532,0.037773,0.586806,-0.075644,0.183155,0.321287,-0.527665,-0.001691,-0.570978,0.054846,-0.175862,-0.468196,0.072469,-0.225827,-0.069727,-0.158324,-0.432176,0.157418,-0.082190,-0.218516,0.763794,-0.708373,0.332787,0.576704,0.358462,-0.271781,0.497217,0.185331,0.287710,-0.382174,0.125095,0.325214,0.409061,0.167563,-0.047598,0.056934,0.098435,-0.200018,-0.219676,0.316789', '3785918', '25932086', '30396443', '1308585');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24470523', '魔力月光', '喜剧', '世界上魔术师千千万，但大部分都是招摇撞骗的欺诈师，而斯坦利（科林·费斯 Colin Firth 饰）属于有真本事的那一拨，虽然身为英国人，但是他却非常擅长表演东方魔术，在巡演的同时，斯坦利还进行着“魔术打假”的事业，将行业内的害群之马一一驱逐。某日，来到法国的斯坦利邂逅了名为苏菲（艾玛·斯通 Emma Stone 饰）的少女，苏菲自称是灵媒师，能够和死去的人交流。不信邪的斯坦利一眼认定苏菲在说谎，于是她成为了斯坦利的下一个“猎物”。哪知道随着时间的推移，古灵精怪的苏菲渐渐动摇了斯坦利的意志，斯坦利发现自己竟然被这位神秘的少女给迷住了。©豆瓣', '艾玛·斯通', '伍迪·艾伦', 7.2, 45133, 'tt2870756', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2216746605.jpg', 0.5, 4.4, 41.7, 40.4, 13, '0.418998,0.238475,-0.668493,0.664600,-0.383433,-0.198546,0.574936,-0.096307,-0.609161,-0.178497,0.167013,0.753145,-0.161003,0.239112,0.419146,0.148648,-0.162335,-0.707371,-0.096105,-0.473797,-0.316217,-0.638399,-0.552459,-0.099250,0.017115,-0.551768,0.571973,0.024876,-0.340846,0.312739,0.583677,0.318945,0.151345,0.498147,-0.135206,0.053746,0.323606,-0.365088,0.075146,0.358733,-0.026189,-0.103137,-0.175811,0.000727,-0.286641,0.411446,0.467670,-0.319222,0.063018,-0.317950,0.414686,-0.327298,0.076722,0.195461,0.080911,-0.025605,0.130702,-0.004174,-0.046421,0.050259,0.128788,0.028633,-0.881170,0.187486,0.168193,0.335131,-0.915003,0.327594,-0.045715,-0.210890,-0.219579,-0.259884,0.219351,0.226471,0.356957,0.339234,0.025567,0.055924,-0.513598,-0.031627,0.260264,0.295458,-0.501067,0.452868,-0.099488,-0.464290,-0.154370,-0.169589,-0.477953,-0.213072,0.335385,0.107410,-0.071521,0.187542,-0.613641,-0.038800,-0.182060,-0.269219,-0.079206,-0.438865,-0.021376,-0.781824,-0.094678,-0.596191,-0.377026,-0.045014,0.113029,-0.425341,0.969798,-1.016621,0.193025,0.683751,0.243598,-0.212412,0.623714,0.179589,-0.011778,-0.100507,-0.507970,0.285620,0.206593,0.319920,0.180808,0.631637,0.086318,-0.301348,-0.301998,0.719668', '1793491', '1870681', '1783461', '1301172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24499012', '逆鳞', '剧情', '4月30日 韩国男演员玄彬退役后首部回归作定为历史片《逆鳞》，在片中扮演朝鲜时期年轻大王正祖。至今以王为主题的电视剧或电影虽很多，但玄彬将通过影片《逆鳞》以更加强韧且有气场的面貌，体现与众不同的大王“正祖”。影片名“逆鳞”指巨龙身上不可触摸的一块鳞片，一旦被触及立刻散发出无限龙威，即君主的怒气。含蓄表达了在两派老论和少论较量中，需要守住王权的正祖当时的心境。', '玄彬', '李宰圭', 6.7, 8373, 'tt3479208', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167163003.jpg', 1.6, 10.6, 50, 26.4, 11.4, '-0.167595,0.329611,-0.340451,0.933490,0.337735,0.031189,0.302438,0.375071,-0.226561,-0.038507,0.363467,0.547728,-0.352999,-0.167549,0.138743,-0.298996,0.064342,-0.391414,-0.055368,-0.010873,0.084539,-0.041089,-0.340356,0.379918,-0.379588,-0.547314,1.142676,0.105156,-0.304942,0.179802,0.332687,0.226105,0.185933,0.093604,0.110988,-0.350345,-0.308355,-0.061716,-0.128291,0.415795,0.088189,-0.159537,-0.145443,0.235850,-0.348501,0.378184,0.675947,-0.481776,-0.005739,-0.295693,1.006777,0.098041,-0.118261,0.191874,0.289252,0.411099,0.225352,0.395563,-0.109572,0.156704,-0.049180,-0.054696,-0.802798,-0.220108,0.172004,0.296538,-0.121147,0.339134,-0.054490,-0.148450,0.233874,-0.264153,0.247202,0.219505,0.247468,0.293824,-0.003410,-0.038972,-0.246925,0.144588,0.383867,0.173802,-0.494699,0.144130,-0.081537,-0.569472,-0.250705,-0.246624,0.165475,-0.212504,0.270197,0.048507,-0.025749,0.199884,-0.606503,-0.192430,-0.038625,0.032702,0.113844,-0.240238,0.093817,-0.370619,-0.435116,-0.624800,0.288375,-0.286164,0.439207,-0.232631,0.704766,-0.667165,0.162490,0.140612,0.313875,-0.336437,0.571929,0.025679,-0.182151,-0.064764,-0.071844,0.161428,0.249938,-0.129518,-0.012476,0.373366,-0.216258,-0.109716,-0.390918,0.484070', '26759820', '25880986', '22265121', '20458867');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24522026', '动物园长的夫人', '剧情', '据最新消息，《北方风云》、《鲸骑士》女导演妮基·卡罗将执导拍摄一部讲述二战时期纳粹屠杀犹太人题材的影片《动物园长的夫人》，该片改编自戴安娜·阿克曼同名小说，已确定由“劳模姐”杰西卡·查斯坦、丹尼尔·布鲁赫（《无耻混蛋》） 、约翰·海尔登贝格主演，《雪花与秘扇》编剧安吉拉·沃克曼负责脚本，另外焦点影业和环球影业则分别获得了该片北美以与欧洲的发行版权。 原著小说《动物园长的夫人》的故事发生在二战时期的华沙，在德军斯图卡轰炸机的肆虐下变成了一片废墟，城里的动物园也一起遭了殃，动物死了一大半。动物园园长简和他的夫人安东尼娜开始将犹太人偷偷带进空荡荡的兽栏。动物牢笼变身为诺亚方舟，躲藏在兽栏内的人以动物为代号，而动物却起了人的名字。每当夜幕降临，“游客们”便走出黑暗，一同用餐、交谈；遇到少有风平浪静的光景，还能来场钢琴音乐会。简活跃在波兰的秘密抵抗组织中，他将弹药埋在大象的围栏里，将炸药藏在水獭、獾、小土狼、猞猁代替吧这些动物身上……', '杰西卡·查斯坦', '妮琪·卡罗', 7.3, 12101, 'tt1730768', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2428974206.jpg', 0.5, 3.7, 39.3, 42, 14.6, '0.314409,-0.082546,-0.457433,0.468612,0.517751,-0.084997,0.787417,0.073117,-0.258934,-0.032000,0.181604,0.678635,-0.372121,0.080357,0.059033,0.063690,-0.589388,-0.418375,-0.432516,-0.085474,-0.032560,-0.297386,-0.315990,-0.359282,0.148462,-0.208634,0.557190,-0.041676,-0.094695,0.197616,0.253414,0.071816,-0.376632,0.165382,-0.018429,0.212890,0.159929,-0.163227,-0.185989,0.186906,-0.144248,-0.006284,-0.067684,-0.206874,0.166948,0.086450,0.835132,-0.532729,0.219291,-0.306765,0.271587,-0.135262,0.163829,0.008056,0.419672,-0.107125,0.193031,-0.013310,0.082088,0.226608,-0.066322,-0.139514,-0.389207,0.077542,-0.030766,0.291350,-0.392491,0.402552,-0.060847,0.362974,0.126829,-0.281830,0.223851,-0.153000,0.134120,0.239541,0.192275,0.225632,-0.478054,0.165979,0.314848,-0.201570,-0.131443,0.063525,-0.144229,-0.475179,-0.083770,-0.099778,-0.338461,-0.135849,0.414890,-0.302273,-0.200959,0.249802,-0.807121,-0.075750,-0.093458,-0.533720,-0.076764,-0.183553,-0.180095,-0.856503,-0.021132,-0.093918,0.193979,-0.114337,0.341248,-0.045354,0.651022,-0.496809,0.191600,0.502806,0.211192,-0.007545,0.507646,-0.346222,0.118980,0.037066,-0.086596,0.297749,0.170492,0.458077,0.386734,0.340734,-0.090640,-0.208443,-0.344395,0.343814', '1294917', '1467779', '2159244', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24522312', '怦然心动的人生整理魔法', '剧情', '某保健品牌客服人员二子玉川薰（夏菜 饰）欠缺归纳整理能力，房屋乱得一团糟，以至于因此失去三个男朋友。为了与心仪的男子小田雅人获得美好未来，薰决定好好给房间来个大扫除。可是这个缺乏计划性的女孩最终以失败告终，她不得已按照杂志的广告请来清理公司的负责人乘田磨辉子（仲间由纪惠 饰）。然而绰号“紫菜包饭”的辉子并非通常负责打扫的钟点工，她到来的任务是教薰学会整理房间衣物的办法，进而取得美好的人生。怀着半信半疑的心情，薰开始了整理祭祀，奇妙的人生拉开序幕，改变总是在不经意间……本片根据近藤麻理惠的原作改编。©豆瓣', '仲间由纪惠', '佐藤东弥', 7.3, 7449, 'tt2938472', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2554452641.jpg', 0.9, 5.7, 39.2, 37, 17.2, '0.265031,0.286863,-0.182677,0.159092,-0.145329,-0.292304,0.096300,0.275512,-0.266180,-0.698105,0.300598,0.121624,-0.075482,0.036231,0.615336,-0.201209,-0.421770,-0.643206,-0.139635,0.104206,-0.241072,-0.337841,-0.051184,-0.193306,-0.207210,-0.108759,0.736328,-0.102991,-0.202448,0.173798,0.065046,0.349325,-0.145294,-0.009551,0.110937,0.022742,-0.177259,-0.234682,-0.583152,0.152301,-0.078961,0.014185,-0.303722,0.278214,0.094958,0.485258,0.721689,-0.010493,-0.604572,0.037101,0.665619,-0.073089,-0.098914,-0.146170,0.227803,0.310148,0.210582,0.103929,-0.233984,0.178978,0.061865,-0.180830,-0.797241,-0.180292,0.380235,0.012771,-0.331297,0.214357,-0.003234,0.109381,0.185934,-0.343353,-0.149173,0.271941,0.451930,0.480096,-0.053167,0.249715,-0.085947,0.290145,0.227593,-0.153527,-0.070512,0.511631,-0.103539,-0.171035,0.196245,-0.133088,-0.367584,0.089952,-0.091308,0.189138,0.088167,-0.228612,-0.758853,-0.223505,-0.135771,-0.560800,0.244328,-0.088030,-0.035266,-0.685446,-0.156534,0.106395,-0.264421,-0.051755,0.149121,-0.336624,0.567811,-0.901152,-0.021272,0.270306,-0.120648,-0.562936,0.099463,-0.099326,0.286656,-0.350364,-0.226596,-0.118164,-0.059327,0.090155,-0.072726,0.262721,-0.105611,-0.188440,-0.735034,0.161686', '26759820', '2369613', '30272753', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24522915', '盂兰神功', '惊悚', '农历七月，盂兰将近。街头巷尾阴风惨淡，鬼影幢幢，自是一番萧索凄凉景象。晦暗的小巷，走来了在大陆经商失败的宗华 （张家辉 饰），他被朋友骗的倾家荡产，更遭遇了人生苦痛的变故，所幸年事已高的父亲接纳了他。他的父亲啸天（林威 饰）是一家神功戏的班主，此时正组织团员们抓紧彩排准备为鬼神上演一年一度的大戏。谁知在开戏前啸天突然病倒，而没有任何经验的宗华临危受命成为代班主。他手忙脚乱，难以服众，多亏美丽花旦小燕 （刘心悠 饰）出手相助，二人似乎更借此生出好感。但是越临近演出的日子，诡异恐怖的事件便越多。叛逆的妹妹突然转性、小燕时冷时热、一闪而过的毁容女子、自己跳楼的身影。冤有头，债有主，所做何因受何果，纵逃到天涯海角奈若何……©豆瓣', '张家辉', '张家辉', 5.7, 16161, 'tt3830194', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189101618.jpg', 5.7, 26.8, 51, 12.3, 4.3, '-0.049179,-0.150771,-0.600275,0.208523,0.217960,-0.162319,0.709257,0.193223,-0.581749,-0.207362,0.426255,0.414888,-0.287767,0.249830,0.167089,-0.088330,0.080843,-0.467364,0.065287,-0.041622,-0.038662,-0.150579,-0.071379,-0.044944,0.046263,-0.249034,0.584780,0.365643,-0.129153,0.416599,0.326779,0.184684,-0.076447,0.584735,-0.247563,0.063666,-0.052345,0.152552,-0.232445,-0.080190,0.015508,-0.466145,-0.510571,0.115058,-0.288710,0.340623,0.512814,-0.034219,-0.387988,-0.037168,0.585584,-0.383289,0.015183,0.107718,0.386428,-0.044356,0.163645,0.092275,-0.159377,-0.057601,-0.230815,-0.022666,-0.471917,0.396156,0.145378,0.179126,-0.411981,0.218594,-0.080202,-0.213586,0.029165,-0.181831,0.027528,0.218006,0.070955,0.183432,-0.331845,-0.020179,-0.495092,0.178172,0.727223,0.115589,0.057958,0.516618,0.031129,-0.276254,0.029666,-0.253665,-0.321513,0.099169,0.348147,-0.042535,0.001708,0.382053,-0.331095,-0.128098,-0.176608,0.017557,-0.231005,-0.243584,-0.245365,-0.352014,-0.184784,-0.114825,-0.443341,-0.012547,0.275486,-0.205668,0.494054,-0.605243,0.294617,0.216848,0.177804,-0.404099,0.460569,0.114828,0.048081,0.039489,-0.272885,0.211272,-0.251556,0.204738,0.176795,0.131827,-0.041239,-0.209968,-0.202521,0.377918', '25721544', '1301022', '1870682', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24523680', '麦克白', '剧情', '麦克白将军（迈克尔·法斯宾德 Michael Fassbender 饰）是苏格兰国王邓肯（大卫·休里斯 David Thewlis 饰）的表弟，在外抵御外敌平反谋乱，战功赫赫，某日归国途中，遇见了三个女巫，女巫预言麦克白将会加官进爵，此言令麦克白心中蠢蠢欲动。然而，最终将要继承王位的，却是班柯将军（帕迪·康斯戴恩 Paddy Considine 饰）的儿子。在妻子（玛丽昂·歌迪亚 Marion Cotillard 饰）的怂恿之下，麦克白杀死了国王，登上了王座，为了保住王位和弑君的秘密，麦克白的双手沾满了鲜血，班柯将军、麦克德夫夫人（伊丽莎白·德比齐 Elizabeth Debicki 饰）和她的孩子均死在了麦克白的屠刀之下，而麦克白亦在疯狂的道路上渐行渐远。©豆瓣', '迈克尔·法斯宾德', '贾斯汀·库泽尔', 7.3, 16477, 'tt2884018', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266410852.jpg', 0.9, 4.5, 37.3, 43.8, 13.4, '-0.166948,0.118352,-0.430652,0.526353,0.401977,-0.441781,0.529048,0.524096,-0.361722,-0.285669,0.452100,0.789139,-0.234130,-0.115002,0.513042,0.091859,-0.301330,-0.534284,-0.050991,0.079221,-0.025805,-0.600885,-0.330456,-0.322275,-0.106114,-0.640230,0.645179,0.032896,0.218380,0.435181,0.456621,0.334164,0.037806,0.220760,-0.110915,0.168433,0.155249,-0.261233,-0.327084,0.120974,0.123323,-0.164760,-0.256773,0.195986,-0.022071,0.299851,0.345780,-0.509415,0.469237,-0.268438,0.234568,-0.275643,0.250751,0.148404,0.196004,-0.305393,-0.002373,0.733235,0.243472,-0.138867,0.379667,0.034179,-0.402364,0.019697,0.077330,0.084272,-0.528651,0.627543,-0.487702,0.108572,0.114908,-0.189670,0.314995,0.163519,-0.154346,0.204967,-0.199531,-0.071175,-0.530567,0.065280,0.209405,-0.036460,-0.000670,-0.137621,-0.007434,-0.330885,0.102266,-0.273147,-0.471424,-0.064694,0.501350,0.030659,0.195479,0.681674,-0.289367,-0.511029,-0.701719,0.278086,0.103755,-0.167991,0.059174,-0.265302,-0.089054,0.000101,0.077129,-0.086456,0.177710,-0.094275,0.327880,-0.365629,0.161391,0.185501,0.125316,-0.220728,0.247684,0.217772,0.361318,-0.009597,-0.214576,0.241619,0.165436,0.147049,0.186569,0.047757,-0.054405,-0.177189,-0.315141,0.471680', '1293530', '3285073', '6390825', '1304646');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24523813', '遗孀秘闻', '剧情', '弗朗西斯（科洛·格蕾斯·莫瑞兹 Chloe Grace Moretz 饰）是一位单纯善良的女大学生，一天，在地铁上，弗朗西斯捡到了一个手提袋，寻着手提袋里的字条上的地址，弗朗西斯敲响了格雷塔（伊莎贝尔·于佩尔 Isabelle Huppert 饰）家的大门。格雷塔感谢了弗朗西斯的善举，言谈之间，弗朗西斯得知她是一名寡妇，终日生活在孤独之中，顿时对她心生怜悯。就这样，弗朗西斯和格雷塔之间的走动变得频繁起来，两人的关系越来越热络，甚至被人视为母女。某日，弗朗西斯偶然在格雷塔家里发现了很多和她当初捡到的手提袋同款的袋子，每一个袋子里都放着写有地址的字条，这让弗朗西斯开始意识到，自己似乎落入了格雷塔设下的圈套之中。©豆瓣', '伊莎贝尔·于佩尔', '尼尔·乔丹', 6.1, 7311, 'tt2639336', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2546900503.jpg', 3, 17.4, 57, 18.2, 4.4, '0.709625,0.232204,-0.844882,0.563559,-0.271294,-0.321037,0.978950,0.276050,-0.433549,0.052261,0.181572,0.760741,-0.377312,0.433791,0.218764,0.283366,-0.451187,-0.587395,-0.187193,-0.546260,-0.617607,-0.320453,-0.270786,-0.113141,-0.277109,-0.378731,0.187846,-0.020124,-0.061759,0.257956,0.288136,0.217961,-0.092075,0.537080,-0.198860,0.446625,0.145192,-0.077782,0.230074,0.205043,-0.122497,0.074156,-0.145698,0.357883,0.273070,0.271201,0.741922,-0.140516,-0.005810,0.134266,0.448994,0.283731,-0.181391,0.041197,0.397309,0.237709,0.033726,0.052274,-0.359301,0.066386,0.307227,-0.084118,-0.395390,0.011078,-0.047066,0.239860,-0.792874,0.491092,-0.081819,-0.028892,0.118841,-0.394300,0.319802,0.100832,-0.009508,0.213905,0.010481,-0.246087,-0.676246,0.071266,0.282491,-0.018616,-0.106678,0.199935,-0.200147,-0.283331,0.059140,0.295854,-0.498489,-0.288122,0.678264,-0.124246,-0.071327,0.126975,-0.625532,0.148527,-0.359383,-0.023114,-0.005245,-0.560634,-0.180105,-0.576439,-0.175429,-0.452162,-0.364352,0.186575,-0.203334,-0.105133,0.666226,-0.592494,0.381285,0.574228,0.123944,0.221858,0.604034,-0.021822,0.236243,-0.024828,-0.066958,0.292352,0.313545,0.347953,0.167746,0.444344,-0.134401,0.001250,-0.409437,0.648311', '21619567', '1302133', '1783772', '1421570');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24525283', '利维坦', '剧情', '这部影片讲述的故事发生在巴伦支海附近的小村中，但也可能发生在任何一个个人利益与政权利益发生冲突并且能够提前明确谁会赢得战斗的国家。贪得无厌的市长盯上了尼古拉一家所住的房子，并企图白占那块土地——实际就是强占。市长行为粗鲁，一切都在他的掌控之下，从警察局到法院，他知道如何驯服不顺从的人。', '阿列克谢·谢列布里亚科夫', '安德烈·兹维亚金采夫', 7.8, 18561, 'tt2802154', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2200544217.jpg', 0.6, 2.9, 25, 49.9, 21.6, '0.286876,0.300576,-0.891275,0.512033,-0.318091,0.355722,0.409345,0.074319,-0.485870,-0.028501,0.447616,0.752012,0.261241,-0.154394,0.138520,0.039755,-0.056153,-0.632824,0.225692,-0.021616,-0.170302,-0.694639,-0.226346,-0.503493,0.106719,-0.097437,0.541147,0.432944,-0.698477,-0.159276,0.222627,0.133102,-0.291452,0.500169,-0.132252,0.040121,0.169972,-0.006643,-0.498597,0.139346,-0.147566,-0.119749,-0.177036,0.299105,0.173714,0.364922,0.526934,-0.235527,-0.692494,0.192499,0.522758,-0.331523,0.134772,0.260119,0.398128,-0.109979,0.028383,0.695754,-0.216329,0.170576,-0.003326,-0.118262,-0.999545,-0.063718,-0.110921,0.502060,-0.369602,0.519600,0.166479,-0.028411,-0.168866,-0.296963,0.297440,0.669666,0.186775,0.205332,-0.212848,-0.083852,-0.816042,-0.090100,0.923114,-0.164831,-0.350391,0.259052,-0.280826,-0.323230,-0.285904,-0.379531,-0.476385,-0.093453,0.199496,0.118994,-0.326387,0.207670,-0.244679,-0.145295,-0.181264,-0.338646,0.278420,-0.716083,0.177531,-0.247590,-0.361316,-0.518470,-0.151714,0.007578,0.134840,-0.275745,0.368515,-0.800600,0.011894,0.771465,0.551942,-0.684492,0.415060,0.367037,0.016182,-0.151518,-0.233467,0.058616,0.510362,0.349004,-0.190083,0.130404,0.427975,-0.397126,-0.180307,0.362398', '35073886', '26678784', '25917239', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24529254', '莫比乌斯', '剧情', '整部电影没有台词，全部出场角色亦没有姓名。妻子（李恩宇 饰）得知了丈夫（赵宰贤 饰）出轨的事实，而儿子（徐英洙 饰）则目睹了父亲和开杂货铺老板娘（李恩宇 饰）在车内云雨的香艳场面。悲愤交加的妻子想要阉割熟睡中的丈夫未果，被愤怒冲昏了头脑的她将屠刀指向了儿子，惨叫声中，一个家庭彻底破碎了，丈夫将儿子送往了医院，妻子离家出走不知所踪。时光飞逝，拖着残缺的身体，儿子慢慢长大，他找到了父亲的情人，两人之间的关系紧张又带着一丝暧昧。一帮小混混闯进了杂货铺玷污了老板娘并逼迫儿子就范，事情败露后，儿子锒铛入狱。父亲发现用石头摩擦皮肤能够产生如同性交一般的快感，他将这一方法教给了狱中的儿子，在疼痛与欲望之间，儿子的性格渐渐产生了扭曲。©豆瓣', '赵宰贤', '金基德', 6.2, 24039, 'tt2942522', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2103988349.jpg', 6.6, 19.2, 42.9, 21.7, 9.6, '0.021731,0.062085,-0.584850,0.555323,-0.145999,-0.279771,1.002268,0.374356,-0.610916,-0.148612,0.140840,0.683943,-0.249108,0.285724,0.113184,-0.019600,-0.021187,-0.898208,-0.186157,-0.099078,-0.219874,-0.349766,-0.028814,-0.200643,-0.100491,-0.296220,0.525015,-0.194134,-0.114498,0.277579,0.381493,0.123611,-0.085520,0.381039,-0.237068,0.371003,-0.089864,0.041552,-0.209376,0.070432,0.266521,-0.382706,0.265145,0.251114,-0.501789,0.460094,0.995220,-0.130899,0.029477,-0.333608,0.400534,-0.112651,-0.124108,0.455288,0.128619,0.175598,0.232695,0.141267,-0.316120,-0.257475,0.401977,0.091138,-0.508507,0.099305,0.033986,-0.005865,-0.608459,0.347160,-0.220233,0.066061,0.184429,-0.450739,0.392653,0.036000,0.131803,0.684735,-0.489989,0.023310,-0.377288,0.363899,0.569564,-0.295530,0.087533,0.539878,-0.377386,-0.191528,-0.008592,-0.319680,-0.478205,-0.205697,0.597592,0.366132,-0.525849,0.377907,-0.229757,-0.303765,-0.240447,0.007523,-0.072679,-0.433624,-0.070898,-0.049957,-0.474383,-0.238364,-0.243697,-0.044541,-0.098294,-0.014019,0.448622,-0.573726,0.147855,0.465454,0.310504,-0.357661,0.398018,0.095700,0.053864,-0.067668,0.110905,0.210979,0.035184,0.184880,0.462661,0.300451,-0.276543,0.133778,-0.306199,0.447608', '21619567', '21348112', '1467779', '1448703');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24529353', '绝地逃亡', '喜剧', '香港探员陈港生（成龙饰）跟踪黑道老大维克多·王（赵文瑄饰）长达十数年，为搜集他犯罪证据而被卷入一场“计中计”中，还将自己的侄女白舒（范冰冰饰）牵扯进来。在这场被中国特警、维克多·王、俄罗斯黑帮三面夹攻的“绝地逃亡”中，班尼结识了共患难的最佳拍档康纳（约翰尼·诺克斯维尔饰），一位正被维克多·王和俄国杀手追捕逃命的美国赌博高手，三人最终将怎样结束这场冒险变得扑朔迷离。', '成龙', '雷尼·哈林', 5.7, 92323, 'tt2238032', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2366057661.jpg', 7.7, 25.1, 47.2, 14, 6, '0.280705,0.042527,-0.447026,0.424529,0.083506,-0.220912,0.505690,-0.181264,-0.669749,-0.296944,0.327023,0.728571,-0.304104,-0.124573,0.281450,-0.068131,-0.356470,-0.794639,-0.190114,0.177775,-0.093656,-0.128752,-0.619914,-0.045303,-0.243532,0.061105,0.525907,0.149240,-0.296783,0.374305,0.598781,0.277595,-0.288633,0.315551,0.201586,0.034968,0.305357,-0.253300,-0.434147,0.147174,0.003113,-0.439137,-0.097966,0.015733,0.162712,0.304785,0.594855,-0.219134,0.537927,-0.304388,0.147048,-0.661294,-0.203559,0.431034,0.532274,-0.120177,-0.034900,0.272069,-0.083645,-0.217975,0.159273,-0.068808,-0.833825,0.195294,0.144959,0.215768,-0.436012,-0.032170,-0.363218,0.000998,0.117612,0.033463,0.188376,0.675944,0.526024,-0.238886,-0.002417,-0.251070,-0.534563,0.430087,0.827826,-0.143561,-0.127854,-0.617158,0.227964,-0.618854,-0.075063,-0.338695,-0.227522,-0.079553,0.686908,-0.593554,0.015489,0.236650,-0.615125,-0.170532,-0.562997,-0.136722,-0.318100,-0.294365,-0.031663,-0.825313,-0.034424,-0.334342,-0.089052,0.034104,0.199363,-0.179194,0.327747,-0.318554,-0.026739,0.500266,0.340172,-0.164950,0.413327,-0.056987,0.369433,-0.353679,-0.253708,0.259162,0.289344,0.173187,0.473705,0.367421,-0.261643,-0.114237,0.125774,-0.005365', '4014397', '11541282', '1294941', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24530939', '骇客交锋', '剧情', '中国香港和美国洛杉矶同时发生了导致严重后果的黑客入侵事件，中国政府和美国联邦调查局决定联手，找到事件的真相。经过调查，黑客在犯罪过程中使用了远程访问工具，而程序的编写者是一位名为尼古拉斯（克里斯·海姆斯沃斯 Chris Hemsworth 饰）的神秘男子，身为网络高手的他此时正身陷囹圄。陈大伟（王力宏 饰）是负责此案的军官，他和妹妹（汤唯 饰）远赴洛杉矶，在特工卡罗尔（维奥拉·戴维斯 Viola Davis 饰）的帮助下寻得了尼古拉斯的踪迹。两人和尼古拉斯之间达成了一个交易，如果尼古拉斯能够帮助他们找到黑客事件的幕后真凶，那么尼古拉斯就将重新获得自由。©豆瓣', '克里斯·海姆斯沃斯', '迈克尔·曼', 4.1, 5581, 'tt2717822', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2208551645.jpg', 32, 39, 22.3, 4.3, 2.4, '0.335967,0.144099,-0.495553,0.602262,0.107748,-0.141835,0.437441,-0.129328,-0.636066,-0.382472,0.133107,0.700126,-0.133011,-0.113217,0.241160,-0.146894,-0.546998,-0.893625,0.057112,-0.218328,-0.451618,-0.753959,-0.414063,-0.380273,0.091515,-0.405309,0.718231,0.219204,-0.305693,0.226096,0.271551,0.527100,-0.387518,0.478377,-0.053480,-0.107992,0.436019,-0.207751,-0.642483,0.605663,0.111418,-0.323674,0.028124,0.266619,0.088426,0.343889,0.487889,-0.357803,-0.102118,-0.178673,0.146366,-0.484716,0.084857,0.017487,0.447196,0.058495,0.289258,0.478665,-0.230512,-0.117976,0.095596,-0.027212,-0.891213,-0.002502,0.101011,0.374046,-0.376406,0.044079,-0.473203,0.075081,0.129811,-0.296490,0.244799,0.547659,0.417398,0.084928,-0.023423,0.093874,-0.559549,0.076452,0.627003,0.071047,-0.013076,0.141967,0.022447,-0.696975,-0.305158,-0.250070,0.038448,0.099896,0.404882,-0.078386,0.136177,0.169291,-0.595570,-0.364742,-0.376604,-0.133282,-0.022251,-0.294409,0.067851,-0.888376,-0.103303,-0.172933,-0.334239,-0.039246,0.141052,-0.377346,0.566816,-0.853717,0.193668,0.626722,0.267404,-0.482073,0.524578,0.071694,0.252702,-0.350215,-0.076783,-0.111896,0.231863,0.252931,0.092122,0.181921,0.148050,-0.348572,-0.155266,0.064679', '1307442', '25723905', '4301278', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24530943', '情敌复仇战', '喜剧', '卡莉（卡梅隆·迪亚茨 Cameron Diaz 饰）是一位精明强干的律师，无论对于生活还是男人，她所要求的无疑都是最好和最完美的。一次偶然中，卡莉结识了名叫马克（尼可拉·科斯特-瓦尔道 Nikolaj Coster-Waldau 饰）的男子，后者的英俊和潇洒立刻就吸引了卡莉的注意，没过多久，两人就坠入了爱河。为了给马克一个惊喜，卡莉瞒着他来到了他的家乡，让卡莉没有想到的是，在这里迎接她的，竟然是一个自称是马克妻子的女人凯特（莱斯利·曼恩 Leslie Mann 饰），而凯特对于卡莉的存在亦是一无所知。直到这时，卡莉才开始渐渐看清马克的真实面目，她和凯特决定联手，将其揭穿。之后，一个名为艾伯（凯特·阿普顿 Kate Upton 饰）的女人加入了她们，三个女人联合在一起，好戏即将上演。©豆瓣', '卡梅隆·迪亚兹', '尼克·卡萨维蒂', 6.5, 20288, 'tt2203939', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2174051294.jpg', 1.5, 11.7, 54.4, 25.8, 6.6, '0.366850,-0.020463,-0.615138,0.672284,-0.480917,-0.482360,0.959241,0.043409,-0.555475,-0.232285,0.296112,0.920604,-0.347177,0.264580,0.475785,0.255130,-0.362968,-0.760339,-0.177867,-0.300380,-0.281083,-0.556662,-0.445673,-0.153983,-0.057022,-0.446455,0.306578,-0.172421,-0.177558,0.469677,0.680258,0.427235,-0.050659,0.664704,-0.246690,-0.112436,0.189917,-0.206800,-0.146492,0.423599,-0.012839,-0.233625,-0.092436,0.456402,-0.112775,0.428204,0.581720,-0.404884,-0.046039,0.087325,0.118884,-0.161634,0.033959,0.224867,0.166165,-0.438517,0.160560,0.244543,-0.301366,-0.099064,0.149494,0.020216,-0.881244,0.203694,0.017410,0.293939,-0.609918,0.453811,-0.080541,-0.312244,0.369702,-0.346281,0.248175,0.367936,0.315898,0.316808,0.007179,-0.014571,-0.421874,0.093503,0.576848,0.312345,-0.033758,0.470296,-0.122153,-0.413835,-0.075614,-0.055445,-0.451330,0.042729,0.303312,0.152090,0.044933,0.138330,-0.454841,-0.233998,-0.429621,-0.274063,-0.071605,-0.609026,-0.099349,-0.521844,-0.216235,-0.408776,-0.348003,0.175529,-0.185929,-0.295471,0.807727,-0.982861,0.239494,0.476793,0.140121,-0.438645,0.742383,0.090558,0.057523,-0.315193,0.079047,0.206436,0.168328,0.039533,0.001898,0.663294,0.096279,-0.162540,-0.264271,0.694340', '3230462', '1783461', '3119246', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24532100', '邻居同居', '爱情', '为了帮好朋友小萌（冈本玲 饰）出气，独自在公寓居住的高中女生西森葵（刚力彩芽 饰）找到学校头号帅哥久我山柊圣（山崎贤人 饰）理论，结果不慎将对方弄伤。小葵好不容易将柊圣带到家中，却发现这个坏心眼的男生就住在自己隔壁。葵帮柊圣做饭时不慎引发火灾，无处居住的柊圣自顾自住进西森家中，两个高中生就这样展开别别扭扭的同居生活。柊圣似乎尤其喜欢捉弄小葵，而小葵对之也从最初的厌恶悄悄转为喜欢。在此期间，一直照顾小葵的大学生三条亘（桐山涟 饰）和柊圣的前女友水野樱月（石桥杏奈 饰）相继出现，在两个当事人交替激起波澜……本片根据渡边あゆ的同名漫画改编。©豆瓣', '刚力彩芽', '川村泰祐', 6, 25331, 'tt2907640', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162459187.jpg', 5.7, 21.6, 48.5, 16.7, 7.5, '0.196616,0.062659,-0.522533,0.188105,-0.040041,-0.055775,0.292673,0.160265,-0.229976,-0.442246,0.229533,0.592803,-0.218001,0.318477,0.220765,0.038632,-0.069847,-0.628967,0.070572,-0.176485,-0.239613,-0.168834,-0.005701,0.079244,-0.342768,-0.331950,0.460688,-0.192215,-0.098961,0.430354,0.258282,0.433284,-0.404437,0.034295,-0.052183,0.126702,-0.084338,0.096439,-0.043116,0.289439,-0.359855,-0.034148,-0.227366,0.014088,0.392470,0.375891,0.703209,-0.111355,-0.247261,0.022016,0.230108,-0.194212,-0.305183,0.039809,0.557302,-0.302440,0.231541,0.028402,-0.326089,-0.205784,0.165994,-0.044460,-0.171400,0.217473,0.114472,0.085151,-0.280117,0.393136,0.153192,-0.051253,0.172487,-0.068110,0.086322,0.280003,-0.067278,0.240475,-0.343682,0.307712,0.058466,-0.014317,0.440286,0.001306,0.119143,0.174195,-0.015352,-0.089382,-0.081470,-0.188007,-0.265736,-0.166885,-0.031634,-0.043606,-0.131768,0.023630,-0.622068,-0.190093,-0.132043,0.246398,0.398831,-0.176777,-0.059505,-0.596857,0.202086,-0.163364,-0.197282,0.108693,0.089985,-0.136103,0.638409,-0.818949,0.442299,0.361639,0.431185,-0.211579,0.512153,0.165307,-0.034693,-0.234251,-0.219672,0.166983,0.227868,0.280731,0.161045,0.340351,-0.147218,-0.114923,-0.733909,0.114410', '3811356', '1826173', '26784898', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24639908', '新包法利夫人', '剧情', '珍玛（杰玛·阿特登 Gemma Arterton 饰）和丈夫查理（杰森·弗莱明 Jason Flemyng 饰）结婚多年，两人生活在一座民风温和而又淳朴的小镇中，日子在平静里缓缓流逝。查理是一位性格十分内敛的木匠，而珍玛则是一名画家，虽然查理平日里对珍玛照拂有加，呵护备至，但珍玛的内心里却总是渴望如同暴风雨一般猛烈的感情。一天，珍玛在野外被马蜂蛰到晕了过去，马丁（法布莱斯·鲁奇尼 Fabrice Luchini 饰）和布列西尼（爱迪丝·斯考博 Edith Scob 饰）两人路过将珍玛送到了医院。之后，珍玛再次在街上和马丁重逢了，后者邀请她到自己家里去玩，就这样，马丁和珍玛之间碰撞出了背德的爱情火花。©豆瓣', '杰玛·阿特登', '安妮·芳婷', 7.4, 5887, 'tt2788556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2209431782.jpg', 0.5, 3.1, 36.4, 47.3, 12.7, '0.332184,-0.003528,-0.782147,0.600511,-0.052081,-0.401446,1.092093,0.197000,-0.490780,-0.199216,-0.014375,0.826521,-0.542768,0.403151,0.336547,0.215356,-0.418652,-0.664760,0.091246,-0.268909,-0.089167,-0.359490,-0.274678,-0.218156,-0.164144,-0.272224,0.095470,-0.058686,0.178523,0.705397,-0.122794,0.372580,0.091846,0.408283,-0.175392,0.001830,-0.054768,0.211215,-0.209141,0.062644,0.255289,-0.159257,-0.282055,0.015308,0.209442,0.249082,0.485883,-0.184763,-0.004804,0.220704,0.175506,-0.179091,0.137257,0.268191,0.419217,-0.118111,0.345938,0.177291,-0.294150,0.215580,0.030951,-0.229986,-0.121676,0.151486,-0.164976,0.233574,-0.683498,0.536386,0.034055,-0.116944,-0.050889,-0.478203,0.210763,0.012200,0.219385,0.646358,-0.250643,-0.081160,-0.401729,-0.054229,0.615677,0.078231,-0.274597,0.396065,-0.409756,-0.257288,0.017075,-0.116842,-0.608957,-0.404879,0.318184,-0.131831,0.035597,0.485416,-0.696288,0.112000,-0.328894,-0.005542,-0.249697,-0.231778,0.003370,-0.791462,-0.136834,-0.959305,-0.463254,0.173978,0.006236,-0.131502,0.516183,-0.785041,0.376973,0.331513,0.120706,-0.122838,0.616300,0.102577,0.049840,-0.086976,0.247504,0.442487,0.208408,-0.012785,0.175520,0.568267,-0.172257,0.052222,-0.189427,0.637481', '1296534', '3111650', '26809592', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2464346', '白丝带', '剧情', '故事的讲述者——一位乡村教师回忆起一战前夕，德国北部某村庄里的一系列离奇往事。医生骑马回家的时候被绳索绊倒受伤，人们马上展开调查的同时，牧师对两名晚归的孩子施以体罚，并为孩子们系上了象征纯洁的白丝带。第二天，一名佃农的妻子因事故身亡，乡村教师在河边发现男孩马丁在高处行走，马丁声称想知道上帝是否要惩罚他。教师与男爵家的保姆伊娃相识，彼此留下了良好印象。不久男爵主持了丰收典礼，身亡农妇的儿子认为男爵对母亲的死有责任遂破坏了男爵的菜园泄愤。所有这些恶性事件可能的始作俑者迟迟没有调查出来，纵火和针对儿童的毒打仍然发生。第二年费迪南大公遇刺之后，教师似乎发现了一些线索，但却被牧师强硬的制止。本片获2009年戛纳电影节金棕榈奖、影评人费比西奖。©豆瓣', 'Christian Friedel', '迈克尔·哈内克', 8.2, 30254, 'tt1149362', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2196608840.jpg', 0.6, 2.1, 17.3, 47.2, 32.8, '0.238940,-0.088769,-0.382562,0.245260,0.006946,-0.294922,0.728987,0.044486,-0.494054,-0.463245,0.296795,0.771643,-0.246011,0.047250,0.365056,-0.215207,-0.417028,-0.550433,-0.048009,-0.043512,-0.291252,-0.328670,0.039191,-0.208366,-0.143036,-0.449250,0.360745,0.217132,0.023362,0.482696,0.272679,0.205643,-0.024796,0.250174,-0.108613,0.122259,0.131499,-0.060602,-0.220528,0.199031,0.075229,-0.266248,-0.137655,0.043946,0.009213,0.595813,0.628929,-0.242025,-0.159868,-0.265340,0.613365,-0.291543,0.263112,0.291070,0.671035,0.086422,0.127269,0.295431,0.030091,-0.258060,0.101921,-0.101503,-0.369984,0.000908,0.185013,0.222850,-0.561997,0.488007,0.001910,0.305290,0.034074,-0.158799,0.328078,0.285909,0.160410,0.320509,0.045823,0.025326,-0.452970,0.276363,0.619789,-0.275471,-0.042260,0.096460,-0.301802,-0.421878,0.258834,-0.210813,-0.447541,0.254102,0.328647,0.014073,-0.287712,0.124221,-0.211011,-0.334892,-0.465334,-0.235084,-0.043507,-0.239655,-0.157969,-0.539038,0.245986,0.004649,-0.071716,-0.095898,0.158500,-0.116514,0.485620,-0.727600,0.432542,0.585600,0.354997,-0.489690,0.520804,0.101193,0.308221,-0.101436,-0.114780,0.184637,0.258888,0.226387,0.009085,0.217974,-0.043221,-0.333054,-0.013770,0.187717', '1302384', '25721544', '3326747', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24695277', '一个人的武林', '动作', '孔武有力的夏侯武（甄子丹 饰）曾是佛山武馆合一门的弟子，当年他争强好胜，在香港担任教官时与他人比武，结果失手将对方打死最终锒铛入狱。三年后的某天，闹市街头发生一宗离奇车祸，死者似乎在车祸前就被武功高强之人残忍杀害。夏侯武在狱中看到该新闻，心知在此背后有一场针对武林中人的猎杀正有条不紊地展开。他强烈要求面见重案组总督察陆玄心（杨采妮 饰），由于言中接下来命案的遇害者，终于取得陆督察的信任，得以协助警方办案。与此同时，先天残疾却练得一身绝技的封于修（王宝强 饰）四处挑战隐于闹市的高手，更在获胜后将他们无情杀害。武林波涛汹涌，夏侯武和封于修迎来对决的终极时刻……©豆瓣', '甄子丹', '陈德森', 6.6, 89868, 'tt2952602', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2206992257.jpg', 2.9, 11.9, 47.1, 28, 10.1, '-0.054806,-0.094336,-0.537407,0.568563,0.002524,-0.032245,0.390107,0.061056,-0.680559,-0.366180,0.731601,0.641310,-0.251025,0.172445,0.364895,-0.469318,0.099563,-0.822744,-0.065416,-0.031224,-0.332726,-0.377948,-0.320331,-0.173134,-0.028036,-0.203361,0.565043,0.417937,-0.307765,0.448591,0.359588,0.399229,-0.318643,0.468075,-0.027728,-0.113539,0.121232,0.273984,-0.108309,0.143078,-0.034273,-0.643463,-0.251513,-0.072761,0.009100,0.310120,0.493460,-0.003184,-0.160977,-0.232556,0.445675,-0.466185,-0.008482,0.165705,0.553631,0.028507,0.381368,0.394798,-0.088939,-0.150552,-0.061745,0.058201,-0.655335,-0.077716,0.422713,-0.086779,-0.346146,0.482570,-0.285552,0.106943,-0.085974,-0.138654,0.091581,0.528394,0.362828,0.037720,0.082681,-0.351857,-0.501903,0.197333,0.639628,-0.138373,0.009422,-0.058796,0.371455,-0.565879,-0.166161,-0.651187,0.016217,0.085124,0.472171,-0.178372,0.056874,0.250715,0.025542,-0.371246,-0.118858,0.278634,-0.115540,-0.022885,-0.038107,-0.577465,0.134537,-0.251526,-0.337266,0.129865,0.192120,-0.376226,0.459945,-0.785651,0.077263,0.117166,-0.054343,-0.478422,0.521561,-0.004556,0.325803,0.155149,-0.195101,0.121777,0.464045,0.511387,0.097109,0.385615,-0.251767,-0.109415,-0.288861,0.162244', '4202326', '1301022', '25723905', '3002820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24695390', '我们假期做了什么', '剧情', '道格（大卫·田纳特 David Tennant 饰）和妻子阿比（裴淳华 Rosamund Pike 饰）带着三个孩子，一家五口自驾去遥远的苏格兰高地为道格的父亲戈蒂（比利·康诺利 Billy Connolly 饰）庆祝生日。他们的大女儿是一个总把重要事情记录在日记本上的严谨女孩，弟弟是一个酷爱读书的男孩，小女儿则是一个走到哪里都要带着她的两块大石头，随时跟它们说话的萌妹子。老爷子与道格的哥嫂同住，而哥嫂家暗藏的矛盾也不可小觑。父亲知道自己的病情将不久于人世，他早已厌倦了家人们的争吵，也不想参加特意为他准备的生日聚会。大人们都在紧张的筹备着父亲的生日。没想到的是，生日当天，父亲不顾家人反对，执意带着三个孩子去海边玩耍。而接下来发生的事情，不仅让沉浸在生日会欢乐气氛中的大人们难以置信，更会让你从搞笑喜剧的情节中瞬间出戏，转而面对残酷的死亡话题。©豆瓣', '裴淳华', '安迪·汉密尔顿', 7.9, 14394, 'tt2725962', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2317662829.jpg', 0.3, 2.2, 24.2, 49.6, 23.7, '0.183421,-0.169832,-0.862919,0.586547,-0.294382,-0.299300,0.829821,0.223598,-0.374982,-0.165066,0.148886,0.977922,-0.109692,0.589493,0.210930,0.019958,-0.207807,-0.620326,-0.189501,0.125974,-0.329368,-0.542669,0.087741,-0.175909,0.093686,-0.088260,0.098204,0.021830,0.022402,0.610430,0.459954,0.056320,-0.331408,0.541280,-0.187529,-0.188313,-0.069985,0.141295,-0.229213,0.086665,0.238673,-0.207083,-0.321864,0.211787,0.208161,0.350879,0.676122,-0.278582,-0.148984,0.060743,0.265432,-0.266851,-0.092794,0.286510,0.217249,-0.125337,0.195710,0.230741,-0.249244,0.047091,0.217239,-0.251895,-0.639025,0.218611,0.083674,0.190567,-0.770376,0.605470,-0.105368,-0.324436,0.331102,-0.456758,0.449905,0.367090,0.001348,0.581082,-0.243257,-0.087247,-0.401625,0.130856,0.699217,-0.125590,0.155205,0.204297,-0.119097,-0.105099,0.071179,-0.236135,-0.864436,0.188340,0.180520,-0.080144,-0.189146,0.302320,-0.439698,-0.047187,-0.120542,-0.371261,0.124294,-0.485101,-0.180986,-0.332817,0.192209,-0.379280,-0.282767,0.132164,0.269624,-0.126056,0.828014,-0.656006,0.324308,0.578339,0.316107,-0.618775,0.653861,0.188661,0.265300,-0.193468,-0.133099,-0.302362,-0.037483,0.070523,0.240982,0.399972,0.073986,-0.050171,-0.418194,0.532621', '1297606', '3016252