INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24695966', '杀人漫画', '悬疑', '当红网络恐怖漫画作家姜知允（李诗英 饰）新作接连问世，备受好评。而生活中她似乎越来越分不清现实和虚幻的界限，不仅经常遭遇极度逼真的恐怖噩梦，身上还常出现莫名其妙的伤口。某个夜晚，姜作家的责编徐美珍以极其残忍的方式自虐身亡，而其死亡过程和现场惨状竟与姜作家不久刚刚发给她的新作内容如出一辙。未过多久，又发生了一起和漫画内容相似的殡仪馆杀人事件。盆唐警局刑警琪哲（严基俊 饰）和后辈金永秀（金显祐 饰）介入调查，并慢慢追踪到姜作家鲜为人知的背景。霓虹灯下鬼影幢幢，每个人心中都有不愿为人知晓的秘密，冤有头，债有主。因果报应，毫厘不爽……©豆瓣', '严基俊', '金容钧', 7.2, 63716, 'tt2973516', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p1980106659.jpg', 0.6, 4.4, 40.8, 42.9, 11.2, '0.179675,-0.095096,-0.471877,0.683402,0.462820,0.249431,0.811558,0.112461,-0.676770,-0.578971,0.052594,0.500254,-0.548897,0.229181,0.316975,-0.320205,-0.241813,-0.726901,-0.114381,-0.085326,-0.504080,-0.359899,-0.164326,-0.275365,0.022136,-0.036141,0.524707,0.400154,-0.225242,0.382744,0.436177,0.401297,-0.524213,0.530971,-0.014895,0.035626,0.024235,0.221130,-0.198673,-0.155234,0.110999,-0.346161,-0.017579,0.175671,-0.210624,0.131333,0.569856,-0.113695,-0.459801,-0.055982,0.703646,-0.136303,-0.099612,0.117473,0.341815,0.088066,0.515065,0.100664,0.072366,0.041801,-0.161335,0.004714,-0.748551,0.083184,0.409646,0.191133,-0.076614,0.072667,-0.153046,0.167289,-0.018062,-0.092913,0.160883,-0.004111,0.578238,0.211993,-0.028572,-0.169455,-0.272896,0.290354,0.525024,0.225600,-0.354671,0.286332,-0.215688,-0.412808,-0.295635,-0.283721,-0.187158,0.378799,0.139403,0.180441,-0.249209,0.459158,-0.481747,-0.101820,0.023500,-0.077714,-0.076041,-0.178287,-0.174259,-0.676467,-0.491496,-0.533279,-0.146540,-0.065730,0.040386,-0.316915,0.603067,-0.520374,0.213129,0.325259,-0.007954,-0.363774,0.475988,0.074014,-0.115873,-0.200325,-0.223382,0.194430,0.350611,0.155559,-0.033518,0.027363,-0.133837,-0.023870,-0.306078,0.312697', '3318306', '2988294', '26649095', '26341750');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24696982', 'I型起源', '剧情', '伊恩·格雷是一名分子生物学在读博士，专攻眼睛的进化。在一个聚会上，他邂逅了一位神秘的面具女郎，凭着记忆里女孩美丽动人的眼睛，他找到了她，两人陷入爱河。尽管两人对于生活的基本信条完全不同，但却丝毫未影响感情。多年后，伊恩和他的实验搭档凯伦有了一次具有深远意义的发现，他必须要离开家人，穿越世界各地去找寻这项新发现的意义。', '迈克尔·皮特', '迈克·卡希尔', 7.8, 29568, 'tt2884206', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178390974.jpg', 0.9, 3.6, 25.8, 44.5, 25.2, '0.509484,0.118588,-0.794559,0.605399,-0.353558,-0.391436,1.062822,-0.103220,-0.615008,-0.466564,0.196480,0.734079,-0.074693,0.309691,0.101616,0.095039,-0.223312,-0.622596,0.247417,-0.244842,-0.418759,-0.593982,-0.407861,0.215910,-0.026423,-0.505535,0.877465,-0.084524,-0.448331,0.580033,0.014264,0.029326,0.100901,0.643221,-0.121023,-0.251294,0.357348,-0.000433,-0.154295,0.359172,0.134351,-0.021714,-0.318069,0.343352,-0.238498,0.242951,0.715953,-0.254491,-0.489888,0.124539,0.502859,0.074859,-0.185461,0.316307,0.216618,0.065880,-0.158596,0.315432,0.117751,-0.139811,-0.118798,0.090172,-0.727480,-0.167183,-0.077547,0.527374,-0.656577,0.636427,0.051002,-0.328703,-0.161532,-0.460260,0.107107,0.105639,0.347165,0.380373,-0.067686,0.249772,-0.587197,0.132655,0.729387,0.071901,-0.501299,0.529441,-0.393533,-0.713943,-0.263748,-0.008635,-0.341910,0.278798,0.313062,0.164774,-0.466021,0.140178,-0.505036,0.372206,-0.354924,-0.157682,-0.003663,-0.325997,-0.132552,-0.745194,-0.286944,-0.631753,-0.661672,0.051593,-0.114464,-0.485779,0.868635,-1.128818,0.258003,0.668660,0.100361,-0.528126,0.901250,0.200209,0.056552,-0.503395,-0.035848,0.421403,-0.069659,0.327691,0.067803,0.336956,0.154942,0.166484,-0.273213,0.501124', '1308755', '35030151', '3055049', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24698878', '落魄大厨', '剧情', '凯尔（乔恩·费儒 Jon Favreau 饰）从小就展现出了过人的烹饪天赋，长大后，他成为了洛杉矶一家知名餐厅的当家大厨，然而，这份工作并没有能够带给凯尔快乐，也无法满足他在烹饪方面的理想与抱负，因为他的老板（达斯汀·霍夫曼 Dustin Hoffman 饰）是一个既暴躁又强势的混蛋。愤怒之中，凯尔辞去了许多人梦寐以求的职务，他来到了迈阿密，找到了前妻（索菲娅·维加拉 Sofia Vergara 饰）和好友（约翰·雷吉扎莫 John Leguizamo 饰），三个大人一辆破车，就这样，一家移动餐厅成立了。开着这辆满载着凯尔梦想的餐车，一行人踏上了漫漫旅途，一路上，凯尔要面对的不仅是自己不断变化的心境，还有他同前妻和孩子之间复杂的关系。©豆瓣', '乔恩·费儒', '乔恩·费儒', 7.7, 57237, 'tt2883512', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2199407040.jpg', 0.3, 2.2, 30, 48.5, 19.1, '0.421049,0.092716,-0.655637,0.533551,-0.165070,-0.452547,0.860341,0.448624,-0.656266,-0.153745,0.058359,0.845198,0.044592,0.261587,0.390267,-0.035862,-0.258955,-0.460376,0.144565,-0.097315,-0.065097,-0.646676,-0.237509,-0.362511,-0.058990,-0.288588,0.477493,0.078888,-0.000163,0.673959,0.277257,-0.000349,-0.007041,0.618359,-0.242036,0.163434,0.334531,-0.009264,-0.166169,0.126633,0.051794,-0.049932,0.057096,0.148406,0.191526,0.160849,0.571637,-0.010113,-0.098102,0.019331,0.056733,-0.062450,0.111212,0.023459,0.086716,-0.012387,0.136253,0.336878,-0.131866,-0.029146,-0.030175,-0.108344,-0.744048,-0.024905,0.064898,-0.113346,-0.889140,0.528205,-0.178353,-0.321927,0.101555,-0.423145,0.143578,0.090052,0.210388,0.418276,0.037957,0.101636,-0.536280,0.091794,0.750266,-0.010764,-0.080709,0.481787,-0.332471,-0.375356,-0.361922,-0.245031,-0.662032,-0.175231,0.432302,0.179589,0.007318,0.020484,-0.504998,0.124168,-0.260572,-0.164016,0.059376,-0.442995,0.095864,-0.504059,0.066385,-0.458393,-0.281888,0.100218,-0.009650,-0.241256,0.691620,-0.871343,0.282699,0.383393,0.277589,-0.361847,0.790568,-0.011059,0.178309,-0.235237,-0.094208,0.291813,-0.109556,0.203670,-0.046824,0.493355,-0.008335,0.014597,-0.272136,0.683797', '1895119', '3111650', '1299965', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24702267', '警察游戏', '喜剧', '这是一部终极警匪拍档动作喜剧，除了他们并不是真的警察。当一对穷途末路的好兄弟选择以警装参加了一场化妆舞会后，他们成为了街坊邻居的大人物。这对新崛起的英雄在面对真实世界的歹徒恶棍及游走黑白的贪污警探时，他们拿起假证件整装备战。', '杰克·约翰逊', '卢克·格林菲德', 6.5, 12031, 'tt1924435', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2208475922.jpg', 1.9, 11.4, 52.6, 26.3, 7.8, '0.284429,-0.445409,-0.272703,0.064007,-0.073857,-0.150282,0.672026,-0.033583,-0.510439,-0.175876,0.553693,0.888929,-0.330525,-0.029701,0.439851,-0.350328,-0.573054,-0.884789,-0.349909,-0.202054,0.004974,-0.117704,-0.370885,-0.165975,0.104392,-0.090714,0.717195,0.126243,-0.262388,0.370503,0.632239,-0.284290,-0.093940,0.221746,-0.156003,-0.116680,-0.046412,0.144756,-0.788811,0.220759,0.158869,-0.030103,-0.180945,0.090588,-0.027119,0.367325,0.636426,-0.614846,0.129826,-0.167152,0.240424,-0.457922,-0.286441,0.009621,0.204148,0.036759,0.224573,0.101723,0.313258,-0.130339,-0.043544,-0.176132,-0.909553,0.042491,0.194874,0.261287,-0.262456,0.369657,-0.288716,-0.043792,0.082616,-0.196022,0.319544,0.283346,0.521971,0.199733,0.011694,-0.172658,-0.478961,0.464477,0.697795,0.076277,-0.100491,0.209939,-0.015118,-0.698263,-0.020950,-0.305757,-0.290255,0.086485,0.347952,-0.102319,0.231052,-0.015351,-0.677409,-0.100490,-0.006163,-0.250605,0.073172,-0.573612,-0.212936,-0.561888,0.271105,-0.098653,-0.121324,0.170345,0.118104,-0.101664,0.522600,-0.949482,-0.116973,0.426750,0.381520,-0.514312,0.666068,-0.015159,0.131218,-0.483383,-0.485897,-0.388811,0.192446,0.671936,0.327786,0.236182,-0.034327,-0.100442,-0.094299,0.281138', '4301278', '30345227', '2988294', '26759819');
