INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24707368', '封门村', '悬疑', '某工程公司原计划为河南的一处偏远山村修建一条路，但是临时变更计划绕过了村子。公司工程师小雨此前奉命去当地签合同，却突然下落不明。心怀叵测的老板派工程师胡东海（陈亦飞 饰）和助理苏牧（王良 饰）前往当地，二人的车子半路以外抛锚。深更半夜，荒郊野岭，正不知道怎么办的时候，二人发现写着“风门村”的石碑，于是兴奋地前去寻找村庄。然而村庄的情况诡异非常，四下里见不到一个人影，到处鬼影幢幢，阴森恐怖。苏牧坐上了一把奇怪的太师椅后不省人事，东海则撞见一名身穿白衣、手持砍刀的女子。暂时找地方安顿下来的东海，殊不知等待他的将是怎样可怕的经历……©豆瓣', '陈亦飞', '邢博', 2.9, 2840, 'tt6448284', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2182184959.jpg', 70.8, 18.6, 6.6, 1.1, 2.9, '0.340504,-0.030872,-0.615133,0.422121,0.241791,-0.200905,0.403516,0.245817,-0.569372,-0.466216,0.350904,0.337645,0.113183,0.222007,0.163867,0.156843,-0.292411,-0.306551,-0.248052,-0.225579,-0.567530,-0.162428,-0.064039,-0.190846,0.024861,0.192220,0.329649,0.301416,0.168456,0.562605,0.203432,0.330378,-0.585179,0.583532,-0.293859,-0.257463,0.217449,-0.043831,-0.118857,0.124799,-0.351085,-0.254560,-0.306080,-0.123459,0.028718,0.581068,0.571303,0.212386,-0.373308,-0.065011,0.109616,-0.000051,0.217729,-0.147856,0.724368,-0.153337,0.207389,-0.120156,-0.276032,-0.220425,0.087723,-0.168577,-0.265855,0.385615,0.080620,0.187092,-0.558643,-0.056667,-0.087974,-0.277516,0.035380,-0.573094,0.399975,0.295531,0.355328,0.173212,0.131130,0.136929,-0.560489,-0.073821,0.400643,0.075664,0.169888,0.131325,0.137507,-0.232911,0.039828,0.052698,-0.222889,-0.085337,0.181691,-0.169615,-0.271272,-0.497862,-0.519620,0.246711,-0.224905,-0.154685,-0.018158,-0.116681,-0.594640,-0.621707,0.327587,0.143590,0.041157,0.091465,-0.130597,0.355195,0.259919,-0.251314,-0.006628,0.520048,0.261006,-0.439735,0.724478,-0.205534,0.179031,-0.138131,-0.033786,-0.230271,0.102396,0.778109,0.109734,0.127622,-0.336403,-0.310488,-0.380101,0.062645', '1309184', '2079017', '1293143', '21937442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24708493', '美国情人', '喜剧', '特雷西（萝拉·科克 Lola Kirke 饰）是一名平凡的女大学生，落在人群之中毫不起眼。一成不变的生活和日复一日平淡令特雷西的内心备受煎熬，她一直向往着能够前往纽约生活，在她的内心里，纽约这座灯红酒绿的大城市代表着更多的希望和更璀璨的未来。终于有一天，特雷西的梦想要成真了。她联系上了即将要成为自己同父异母的姐姐的布鲁克（格蕾塔·葛韦格 Greta Gerwig 饰），在特雷西的眼中，布鲁克就是她想要成为的那种女孩。在布鲁克的带领之下，特里希过上了梦寐以求的生活，两人参加聚会，结交朋友，肆意挥洒着青春。然而，随着时间的推移，布鲁克所隐藏的秘密渐渐浮出水面。©豆瓣', '罗拉·科克', '诺亚·鲍姆巴赫', 7.3, 12182, 'tt2872462', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2261186463.jpg', 1, 5.2, 36.6, 42.3, 14.9, '0.195230,0.073558,-0.880247,0.768176,0.042778,-0.231037,0.926831,0.126214,-0.587304,-0.048073,0.067444,0.646049,-0.143685,0.582141,0.346958,0.033106,-0.386456,-0.855555,-0.258749,-0.343027,-0.084519,-0.390498,-0.388426,0.001012,-0.196250,-0.305592,0.843445,0.315585,0.076490,0.412668,0.382526,0.352819,-0.014700,0.414306,-0.494978,-0.370831,0.023266,0.060026,-0.236286,0.214350,0.204185,-0.265765,-0.123913,0.064299,0.027456,-0.006216,0.686544,-0.207318,0.013899,0.040412,0.238753,-0.247313,0.031925,0.119634,-0.059278,-0.046224,0.148920,0.192049,-0.228944,-0.004287,0.072057,-0.316327,-0.712052,-0.019894,0.101656,0.386312,-0.693625,0.565587,0.213192,-0.304419,0.219920,-0.262336,0.220520,0.352707,0.015923,0.289674,-0.301545,0.095516,-0.557647,0.309122,0.847216,0.249568,-0.306097,0.329371,-0.473751,-0.200357,-0.222537,-0.192031,-0.778150,-0.337615,0.235390,0.291541,-0.103758,0.600905,-0.522400,0.397800,0.001378,-0.355704,0.161632,-0.437597,0.016018,-0.698990,-0.180230,-0.615574,-0.278761,0.105451,-0.090422,-0.443592,0.883162,-1.129450,0.468989,0.521518,0.382712,-0.105283,0.797465,0.204591,0.279404,-0.028476,-0.163565,0.419363,-0.107674,0.252984,-0.116849,0.436630,-0.187225,0.118060,-0.377034,0.871636', '35030151', '4275444', '1870682', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24713882', '完美音调2', '喜剧', '贝卡（安娜·肯德里克 Anna Kendrick 饰）率领的巴顿大学阿卡贝拉女子美声合唱团终于出人头地，应邀为美国总统的生日宴会光荣献唱。谁知表演期间，“胖艾美”（蕾蓓尔·威尔森 Rebel Wilson 饰）竟意外走光，引起全场恐慌，令合唱团蒙上不雅污名，更被禁止公开演出！力挽狂澜的最后机会，就是赢得阿卡贝拉世界锦标赛的冠军，她们能否战胜来自德国的劲敌，挽回失去的名声，称霸阿卡贝拉的世界……', '安娜·肯德里克', '伊丽莎白·班克斯', 6.7, 23004, 'tt2848292', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2272070042.jpg', 1.3, 9.7, 49.7, 29.3, 10, '-0.269786,0.442200,-0.229320,0.278233,-0.066767,-0.293055,0.330384,0.094031,-0.331171,0.107672,0.381678,0.770915,-0.319114,-0.201552,0.776990,-0.068032,-0.526013,-0.890605,0.550916,-0.116838,0.230800,-0.337965,-0.163657,-0.090220,0.003366,-0.648378,0.587977,0.183030,-0.268655,0.682693,0.291456,0.135133,0.360379,0.299514,0.203290,-0.237540,0.480925,-0.031023,-0.324412,0.319756,-0.255377,0.057539,-0.399359,0.468117,0.176130,-0.002249,0.439519,-0.150504,0.466135,-0.448143,0.472993,-0.277507,0.189030,-0.058894,0.061782,-0.187394,0.336090,0.321007,0.215659,0.006804,0.361757,-0.157101,-0.436821,0.440026,0.241429,0.100732,-0.238889,0.323038,-0.345580,-0.199923,0.352340,0.348332,0.074995,0.381148,0.560890,0.176133,-0.062337,0.310415,-0.310748,0.191971,0.588831,-0.133557,-0.143071,-0.285127,-0.342993,-0.419574,0.270565,-0.348128,-0.376144,0.254136,0.291307,-0.214834,0.278169,0.541465,-0.287681,-0.576032,-0.600809,-0.365185,0.209676,-0.528545,0.006370,-0.869979,-0.061721,0.510758,-0.035005,-0.033765,0.139869,-0.220861,0.523858,-0.632077,0.424945,0.345157,0.255550,0.002920,0.610687,0.230116,0.146830,-0.407774,-0.297823,0.482597,-0.277156,0.154988,-0.391124,0.016443,0.093448,-0.242921,-0.129025,0.627216', '24751811', '1293656', '25723905', '11541282');
