INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24716045', '远离尘嚣', '剧情', '故事发生在维多利亚时代的英国，彼时田园牧歌式的封建宗法制社会遭到了资本主义的重创，濒临瓦解的边缘。美丽的少女巴斯希巴（凯瑞·穆丽根 Carey Mulligan 饰）继承了姑姑的农场，成为了农场主，有为青年加里布埃尔（马提亚斯·修奈尔 Matthias Schoenaerts 饰）爱上了巴斯希巴，来到了她的农场为她打工。然而，巴斯希巴却并没有将老实的加里布埃尔放在眼里，她疯狂的爱慕着一个名为特洛伊（汤姆·斯图里奇 Tom Sturridge 饰）的花花公子，虽然特洛伊曾经残忍的抛弃了纯洁的少女范尼（朱诺·坦普尔 Juno Temple 饰），但巴斯希巴还是盲目的相信这个男人能够给自己带来梦寐以求的完美爱情。©豆瓣', '凯瑞·穆里根', '托马斯·温特伯格', 7, 14196, 'tt2935476', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2235684794.jpg', 1.2, 8.2, 41.9, 35.4, 13.3, '0.490718,0.277087,-0.580254,0.548846,-0.414695,-0.239568,0.780214,0.233993,-0.305496,-0.177345,0.198353,0.713976,0.160484,0.082206,0.370170,0.453161,-0.148778,-0.563409,-0.037815,-0.183005,0.023959,-0.590637,-0.359893,-0.178467,-0.193539,-0.493712,0.594559,-0.081247,-0.148287,0.329853,0.253593,0.414926,0.409091,0.165241,-0.104048,0.355985,0.363731,-0.386673,-0.219898,0.331633,-0.151537,0.040448,0.011095,0.452461,-0.269218,0.331225,0.426175,-0.448073,0.103772,-0.087457,0.457719,-0.206596,0.129480,0.179222,0.043121,-0.467653,-0.093588,0.086936,-0.054069,-0.171517,0.328301,-0.210089,-0.622214,0.121289,0.142475,0.198502,-0.529217,0.729090,-0.262339,-0.024345,0.201146,-0.160954,-0.151538,0.075816,0.382626,0.482184,0.043647,0.086436,-0.372341,0.143191,0.374329,0.052793,-0.589288,0.283737,-0.547505,-0.290022,-0.084290,-0.497411,-0.673473,-0.117624,0.348169,-0.039803,-0.132373,0.668812,-0.599507,-0.034057,-0.384822,-0.158270,0.023901,-0.282482,-0.185380,-0.408245,-0.232771,-0.547933,-0.436150,-0.073890,0.002387,-0.151534,0.759511,-0.838488,0.465995,0.611911,0.261795,-0.224971,0.537842,-0.095567,0.088190,-0.076277,-0.144651,0.652025,0.105718,0.288468,0.068009,0.459303,0.100602,-0.198574,-0.373674,0.679492', '35158375', '1292062', '26348103', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24718797', '玩命速递：重启之战', '动作', '“弗兰克·马丁”这次惹上了大麻烦，麻烦竟然是他的老爸带给他的，夹在四位美女和俄罗斯黑帮之间的父子俩这次在法国尼斯上演了一出与黑帮的火爆较量。凭借高超的车技和劲爆的身手，弗兰克在枪林弹雨和围追堵截中杀出重围，与退休的特工老爸一起演绎“上阵父子兵，同抱美人归”。', '艾德·斯克林', '卡米尔·狄拉玛', 6.1, 34589, 'tt2938956', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2286211636.jpg', 3.9, 18.6, 53.5, 17.6, 6.3, '0.293683,-0.246812,-0.932267,0.471556,-0.128435,-0.241470,0.611446,0.007295,-0.499380,0.370409,0.124260,1.041506,-0.518499,0.027249,0.560574,-0.285650,-0.254411,-1.043211,-0.219344,0.384843,0.048609,-0.554071,-0.612364,0.179746,0.046037,-0.310679,0.097419,-0.181237,-0.565775,0.676393,0.512516,0.097096,-0.002900,0.100437,-0.318816,-0.099040,0.187113,0.299874,-0.241073,0.265477,0.147034,-0.276165,-0.064725,-0.090400,0.215175,0.211506,0.174907,0.022192,0.146748,0.086556,-0.153889,-0.298525,-0.188976,-0.012146,0.202528,-0.297101,0.492006,0.161260,-0.024797,-0.108130,-0.019507,-0.110933,-1.033915,0.304363,0.143894,-0.293311,-0.698695,0.544313,-0.075004,-0.127829,0.189025,-0.128083,0.272326,0.574806,0.028664,0.258336,0.031070,0.178584,-0.650557,0.031300,0.932016,0.046078,0.095131,-0.352886,0.171074,-0.096663,-0.182066,-0.675065,-0.241526,-0.214253,0.650700,-0.579567,-0.157026,0.121993,-0.604921,0.101032,-0.350567,-0.068999,-0.118213,-0.319378,0.020707,-0.907729,-0.067497,-0.903396,-0.270620,0.185232,0.230886,-0.390455,0.920385,-0.821638,-0.248192,0.396118,0.186157,-0.229829,0.864635,0.251606,0.061186,0.026750,-0.311934,-0.482527,0.213183,-0.078761,0.449524,0.751602,-0.130053,-0.165759,-0.312741,0.364633', '30162520', '4301278', '3000078', '34429100');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24718802', '远离人迹', '剧情', '达吕（维果·莫腾森 Viggo Mortensen 饰）是一名在阿尔及利亚出生的法国人，如今，他在一处地处偏远的山区学校里担任着教师的职务。某日，一名警察出现在了达吕的面前，将一名五花大绑的犯人默罕默德（雷达·卡特布 Reda Kateb 饰）交给了达吕，这个男人被控告杀死了自己的堂兄，达吕要将他押往临近的村庄接受审判。这门苦差事令达吕感到非常的头痛，因为他知道，只要默罕默德抵达了村庄，那么等待着他的就只有死亡，他不愿意做这样一个推手，但警察将默罕默德丢给达吕后就离开了，无奈之下，达吕只得带着默罕默德踏上了旅途。一路上，达吕不仅要提防默罕默德逃跑，还要保护他不受死者的亲属的袭击。©豆瓣', '维果·莫腾森', '达维德·厄洛芬', 7.7, 6872, 'tt2936180', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2312688228.jpg', 0.4, 2.2, 27.6, 52.2, 17.7, '0.460102,-0.140045,-0.620844,0.624570,-0.106327,-0.200949,0.598404,0.429402,-0.445057,-0.570162,0.059135,0.515807,-0.270738,0.547524,0.248950,-0.095896,-0.190560,-0.438289,-0.455738,-0.298015,-0.521419,-0.607780,0.093408,-0.228559,-0.199489,-0.028575,0.170370,0.285378,-0.229387,0.183163,0.578784,0.435665,0.109413,0.892229,-0.446124,0.014305,-0.176225,-0.718227,0.231497,0.290477,0.244700,-0.280619,0.338159,0.050024,-0.079145,0.420903,0.644465,-0.094068,0.051741,-0.162756,0.247400,-0.297722,0.290423,0.227041,0.368351,-0.281895,-0.460655,-0.122349,-0.455948,0.019611,0.347578,-0.301758,-0.702725,0.130661,-0.138371,0.041622,-0.974837,0.037115,-0.071936,0.131790,0.012124,-0.171679,0.233327,0.509593,0.032424,0.148477,-0.023736,-0.165190,-0.906076,-0.024404,0.615886,-0.146872,-0.040635,-0.179297,-0.246445,-0.717523,-0.234101,-0.238517,-0.485411,-0.084820,0.251398,-0.183744,0.102295,-0.216511,-0.241284,-0.203667,-0.302825,-0.043542,0.004157,-0.298951,-0.011612,-0.672358,0.362702,-0.308699,-0.631152,0.225884,-0.114755,-0.299962,0.473456,-0.441428,0.288729,0.618897,0.539822,-0.278980,0.860515,0.063108,0.203782,0.004688,0.190290,0.631472,0.529546,0.552341,0.577152,0.258920,-0.147776,-0.285020,0.052687,0.421338', '1299932', '1306801', '1292584', '26769480');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24718965', '正义联盟：闪点悖论', '动作', '某晚，中央城爆发激战，闪电侠巴里·艾伦（贾斯汀·钱伯斯 Justin Chambers 配音）和超人、蝙蝠侠、戴安娜、绿灯侠等正义联盟的伙伴们与来自25世纪的急速教授及其爪牙镜子大师、陀螺、速冻队长你来我往，最终将这群恶棍绳之于法。分别时刻，急速教授的一番话触动巴里心底最敏感的地方。在此之后，似乎一切都发生变化。他一觉醒来，发现无赖帮们继续为非作歹，自己则意外丧失了变身闪电侠的能力，更令他出乎意料的是本应在童年被盗贼杀害的母亲竟然活着出现在他面前。全世界仿佛也天翻地覆，戴安娜率领的亚马逊人以及亚特兰蒂斯阴谋毁灭世界，布鲁斯死去，他的父亲托马斯·韦恩则以粗暴的蝙蝠侠身份出现。从未存在过的正义联盟，世界灭亡的前夕……©豆瓣', '贾斯汀·钱伯斯', '杰伊·欧力瓦', 8.7, 27268, 'tt2820466', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2043193073.jpg', 0.2, 0.8, 11.3, 40.4, 47.4, '0.077157,0.061585,-0.673836,0.527642,-0.099027,-0.058782,0.714484,0.020393,-0.467993,-0.390881,0.452153,0.757264,-0.283801,0.026720,0.309870,-0.142013,-0.233672,-0.723608,-0.220932,-0.024415,-0.222564,-0.314449,-0.334049,-0.278869,0.047174,-0.404562,0.497797,-0.116028,-0.245071,0.388523,0.259709,0.317099,-0.246184,0.563642,0.024964,0.061625,0.257655,-0.162560,-0.324105,-0.058127,-0.073925,0.026390,-0.048786,0.468646,-0.484114,0.114303,0.643834,-0.453573,-0.046707,-0.446669,0.285300,-0.465580,-0.079350,0.001981,0.605727,-0.130727,0.114051,0.199802,0.357914,-0.181267,0.025104,0.048770,-0.806501,-0.043827,0.094235,0.133279,-0.349573,0.069829,-0.022712,0.136315,0.209475,-0.241861,0.267918,0.152410,0.552556,0.293343,-0.154567,-0.011277,-0.447621,0.070714,0.588972,-0.209000,-0.591308,-0.017760,-0.030232,-0.340738,-0.188750,-0.138527,-0.439943,-0.094632,0.207738,0.043303,-0.152076,0.581110,-0.590694,0.001425,-0.286461,-0.127987,0.010170,-0.439310,-0.167226,-0.485831,-0.190745,-0.069248,-0.064132,0.116848,-0.163815,-0.059393,0.628823,-0.764849,0.242011,0.541209,0.225711,-0.230626,0.382300,-0.002911,-0.009588,-0.435750,-0.253773,0.455540,0.304249,0.329314,0.059398,0.173182,-0.048185,0.224384,-0.181920,0.618229', '2988294', '25928048', '26667010', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24719063', '烈日灼心', '剧情', '七年前，福建西陇发生一起惨绝人寰的灭门惨案，某别墅内一家五口同日惨死，在社会上引起极大的震动，然而此去经年，嫌疑人杨自道（郭涛 饰）、辛小丰（邓超 饰）、陈比觉（高虎 饰）却依然逍遥法外。现如今，这三个人都在厦门过活，杨当起了出租车司机，小丰加入了协警队伍，因意外变成傻子的陈则带着三人捡来的女孩尾巴栖息在亲戚的渔场中。这一天，拥有丰富办案经验的伊谷春（段奕宏 饰）调到小丰所在的队伍担任警长。伊颇为器重能力卓越的小丰，但嗅觉灵敏的他也隐隐觉出这个男子和当年的灭门惨案有所关联。在此期间，道哥在一次意外中结识了伊的妹妹小夏（王珞丹 饰）。仿佛冥冥之中有一只看不见的手，正将这三个决心重新做人的男人推向无法更改的结局……本片根据须一瓜的长篇小说《太阳黑子》改编。©豆瓣', '邓超', '曹保平', 8.3, 600228, 'tt4079152', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2262236348.jpg', 0.3, 1.3, 15.3, 51, 32.1, '0.054247,0.014232,-0.794205,0.435374,0.074365,-0.088530,0.863695,0.183543,-0.503685,-0.236223,0.299171,0.513941,-0.104284,0.321092,0.277110,-0.204403,-0.076204,-0.464756,-0.153989,-0.185885,-0.414712,-0.333048,-0.251244,-0.185057,0.002179,-0.021101,0.494492,0.204264,-0.256536,0.575304,0.335412,0.136506,-0.331517,0.376365,-0.317456,0.228137,0.027044,0.097327,-0.116941,0.051813,-0.094764,-0.238837,-0.006689,-0.018662,0.068597,0.412191,0.608013,-0.319093,-0.337804,-0.046502,0.321877,-0.074156,-0.133379,-0.001960,0.427189,0.153655,0.135265,0.072719,-0.248177,-0.200197,0.072481,-0.045207,-0.650576,-0.146518,0.292053,0.288551,-0.519357,0.352607,0.020503,-0.103137,-0.025723,-0.258091,0.193884,0.372396,0.157262,0.227224,0.058963,0.166618,-0.622889,-0.010671,0.555980,-0.076524,-0.116248,0.027266,-0.163678,-0.443356,-0.152459,-0.128933,-0.193102,0.016687,0.311291,-0.088539,-0.089769,0.196509,-0.294528,0.032109,-0.163246,0.129390,-0.169181,-0.250952,-0.084445,-0.432132,0.021031,-0.471685,-0.285148,0.343786,0.142425,-0.354195,0.437016,-0.657394,0.100867,0.353196,0.119839,-0.165031,0.587862,-0.058352,0.231153,-0.247829,-0.196359,0.187104,0.186355,0.255651,0.231481,0.377261,-0.102201,-0.235696,-0.364516,0.252388', '21619567', '26342391', '1292211', '1297996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24719853', '神探伽利略XX 内海薰最后的案件 愚弄', '剧情', '九个月前，正值而立之年的内海薰（柴崎幸 饰）突然接到远赴美国俄克拉何马州研修的通知，情知自己正成为警界可有可无之人，薰在焦虑烦恼的同时也暗下决心要干出一番业绩。就在此时，机会从天而降。在街上执行任务时她偶然发现一名看护师用轮椅推着早已死亡的老人，进一步调查发现看护师上念研一（中山裕介 饰）竟是长野县通缉的在逃犯。在薰的面前，上念供诉了杀害主家女儿的经过。风光得意的薰在公众和同侪的注视下担当押送嫌犯的重任，谁知上念抵达长野后推翻了之前的供词，令内海陷入窘境。在此之后，他只得与新人当摩健斗（柳乐优弥 饰）联手调查，却意外探知到九年前的一起冤案。内海薰最后的案件，朝向未知的方向推进……©豆瓣', '柴崎幸', '西谷弘', 8, 19721, 'tt2956368', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2151819722.jpg', 0.3, 1.6, 21.5, 50.8, 25.9, '0.093812,0.186476,-0.700176,0.366387,0.039853,-0.273634,0.447946,0.222975,-0.436182,-0.160140,0.545908,0.299750,-0.248705,-0.036532,0.663555,-0.126499,-0.270595,-1.007852,-0.193826,-0.527626,-0.533595,-0.569370,-0.212814,0.046240,-0.031146,-0.132765,0.590946,0.153620,0.056571,0.509469,0.151038,0.364804,-0.534186,0.468075,-0.159945,-0.075823,0.256253,0.057653,-0.220218,0.273446,-0.126445,-0.458053,-0.354912,0.169536,-0.039846,0.501913,0.591700,-0.208879,-0.387885,-0.112435,0.122296,-0.369576,-0.164044,-0.082060,0.615107,0.098278,0.017073,0.169724,-0.358686,-0.118146,-0.134035,0.100980,-0.446127,0.182016,0.108774,0.379740,-0.409106,0.245891,0.017997,0.176036,0.057521,-0.334524,0.021039,0.439790,-0.070977,0.430019,-0.003182,0.352199,-0.174021,-0.032080,0.477202,-0.106198,-0.030831,0.062726,0.201639,-0.016781,0.131285,-0.096952,-0.371628,-0.156891,0.197078,0.245881,-0.063491,0.137762,-0.282094,-0.100412,-0.382285,-0.009493,0.119786,-0.045148,-0.022300,-0.596373,0.027094,-0.093733,-0.292178,0.287860,0.164771,-0.288160,0.368956,-0.550851,0.286589,0.445388,0.292313,-0.342408,0.312231,0.002922,0.232924,-0.086964,-0.231927,0.025454,0.071977,0.572255,-0.103131,0.268810,-0.147289,-0.273299,-0.638625,0.106515', '25723905', '6999256', '1298104', '3387546');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24721493', '小时代2：青木时代', '剧情', '大学毕业将至，林萧（杨幂 饰）、南湘（郭碧婷 饰）和唐宛如（谢依霖 饰）这三个好朋友紧张备战考试，而顾里（郭采洁 饰）早已修完所有学分，轻轻松松等待出国深造时刻的到来。在这个人生和心境都面临着巨大变革和震荡的时刻，很多事情开始发生改变。刚刚完成实习的林萧和简溪（李悦铭 饰）的恋情走向穷途末路；顾里一方面与顾源（柯震东 饰）各种冷战，而她和南湘的男朋友席城（姜潮 饰）的隐秘之事也被挑明。唐宛如与卫海（杜天皓 饰）有缘无分，在一厢情愿的过程中受尽屈辱。看似情同手足、亲密无间的好姐妹，她们的关系在顾里的生日派对当天走向崩溃……©豆瓣', '杨幂', '郭敬明', 5, 241620, 'tt3086582', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2060736910.jpg', 22.9, 26.2, 34.2, 10.1, 6.7, '0.151730,-0.111617,-0.884344,0.573861,-0.033709,-0.201094,0.841778,0.286921,-0.384209,-0.414559,-0.090157,0.354489,-0.615452,0.344523,0.489157,-0.419556,-0.056822,-1.052303,-0.199376,0.068031,-0.230681,-0.581082,0.051252,-0.139509,-0.209065,-0.039912,0.621725,0.165847,-0.118046,0.683977,0.507115,0.364497,-0.372109,0.590477,-0.144585,-0.060391,-0.131954,0.402127,-0.595555,0.102431,0.267304,-0.097838,-0.104563,0.223851,0.118296,0.272589,0.676204,-0.202140,-0.177356,0.243394,0.427058,-0.452813,-0.144131,0.246856,0.287617,0.244329,0.125250,0.064601,-0.245396,0.215115,0.157794,-0.300378,-0.431001,-0.121533,0.228558,0.183441,-0.472688,0.729761,-0.078005,-0.013210,0.167422,-0.437770,0.365228,0.756417,0.403481,0.299354,-0.349217,0.023444,-0.541989,0.167191,0.832580,0.157675,-0.064090,0.250885,0.116802,-0.299130,-0.272721,0.135908,-0.479486,0.042523,0.207701,0.050603,0.080466,0.280436,-0.609236,-0.202151,0.128858,-0.143218,-0.123849,-0.631490,0.101141,-0.664648,-0.241230,-0.781074,-0.420534,0.240808,-0.019828,-0.390589,0.600113,-0.815300,0.276411,-0.121661,0.292132,-0.512311,0.327738,0.087809,0.374140,-0.257257,-0.015188,0.242583,-0.050333,0.110993,0.140993,0.415953,-0.148569,0.279557,-0.583755,0.331340', '25777330', '1301022', '3078390', '24325798');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24723061', '魁拔Ⅲ战神崛起', '动作', '历经惨烈的元泱界大战，成功突破魁拔十二妖第一道防线的蛮吉（刘婧荦 配音）、镜心（刘校妤 配音）一行，为追赶曲境一号再踏征途，却意外闯入萨库人大仓（王宇腾 配音）与粼妖姑娘海问香（姚姝 配音）所设下的诡异防线。面对大仓与海问香的步步紧逼，蛮吉等人无奈应战。激战中，神秘少年 敖江（刘校妤 配音）凭空出现、曲境一号舰长远浪（杨晨 配音）更做出种种令人匪夷所思的决定，让本已复杂的局面，越发显得扑朔迷离；而机缘巧合下，脉门封闭已久的蛮吉竟意外开启六大脉门，化身无敌战神，携魁拔脉兽驰骋于漫天烽火中，上演了一场气势磅礴的惊世之战……', '刘婧荦', '王川', 8.5, 50475, 'tt4912418', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2202613921.jpg', 0.8, 1.8, 13.2, 37.8, 46.3, '-0.068618,0.153280,-0.661826,0.635356,0.467462,0.141078,0.429944,-0.114452,-0.288321,-0.187234,0.399641,0.260780,-0.315012,-0.214159,0.360356,-0.358461,0.329776,-0.482201,-0.113787,0.099487,-0.023923,0.051471,-0.289835,0.095524,-0.058760,-0.243455,0.734085,0.430130,-0.149720,0.375720,0.247253,0.187675,-0.535095,0.483207,0.059899,-0.091252,-0.065173,0.029506,-0.055673,-0.071338,-0.534321,-0.378787,-0.234780,0.427409,-0.021877,0.165111,0.588988,-0.690788,-0.194830,-0.054723,0.138084,-0.222442,-0.419026,0.048321,0.279572,0.069941,-0.108045,0.255095,-0.222107,0.039707,-0.318597,-0.144582,-0.821607,0.100824,-0.155234,-0.051766,-0.163747,0.135413,0.186941,0.134058,0.134069,-0.080839,-0.074844,0.231008,0.539420,0.293888,0.002317,-0.035367,0.111989,-0.000218,0.538426,0.100519,-0.358124,0.199826,0.331734,-0.257474,0.057039,-0.390441,-0.083779,0.068320,0.348306,0.113616,0.319850,0.509525,-0.589623,0.080527,-0.370551,0.021245,-0.486594,-0.149499,-0.286842,-0.556249,-0.078652,0.041966,-0.022026,0.168883,0.032696,-0.299595,0.413428,-0.641445,0.044804,0.116242,0.168664,-0.017890,0.233037,0.028448,0.065438,-0.084061,-0.153727,0.196298,-0.323262,0.329156,0.136571,0.558323,-0.408682,0.045937,-0.506014,0.133560', '26759819', '3213270', '7051375', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24733428', '心灵奇旅', '动画', '究竟是什么塑造了真正的你？电影将聚焦乔伊·高纳（杰米·福克斯配音）。这位中学音乐老师获得了梦寐以求的机会——在纽约最好的爵士俱乐部演奏。但一个小失误把他从纽约的街道带到了一个奇幻的地方“生之来处”（the Great Before）。在那里，灵魂们获得培训，在前往地球之前将获得他们的个性特点和兴趣。决心要回到地球生活的乔伊认识了一个早熟的灵魂“二十二”（蒂娜·菲 配音），二十二一直找不到自己对于人类生活的兴趣。随着乔伊不断试图向二十二展示生命的精彩之处，他也将领悟一些人生终极问题的答案。', '杰米·福克斯', '彼特·道格特', 8.7, 892531, 'tt2948372', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2626308994.jpg', 0.2, 0.8, 11.9, 38.5, 48.6, '0.121949,0.234900,-0.631680,0.824472,-0.367868,-0.247567,0.586419,-0.111291,-0.265799,-0.210283,-0.045348,1.023030,-0.056722,0.420217,0.217126,-0.038051,-0.175287,-0.733692,0.159571,-0.293551,-0.384339,-0.628766,-0.372218,-0.118014,-0.163231,-0.487952,0.540050,-0.051726,-0.338415,0.215530,0.158499,0.171180,0.131103,0.251954,-0.375153,-0.244003,0.266222,0.015617,-0.241203,0.442170,0.036708,-0.152357,-0.157805,0.292913,0.070334,0.176929,0.969280,-0.177592,-0.098656,0.050091,0.505714,-0.133752,0.058863,0.106789,0.027298,0.003837,-0.129966,0.258284,-0.028942,0.199536,-0.082320,-0.240441,-1.116797,-0.179467,-0.031186,0.222274,-0.569156,0.194188,0.011855,-0.263262,-0.057039,-0.381698,0.373398,0.437543,0.206303,0.312044,-0.343685,0.007881,-0.306402,0.129998,0.739334,-0.126237,-0.218974,0.658521,-0.132085,-0.619315,-0.253668,0.083677,-0.371737,0.010445,0.312031,0.220752,-0.119256,-0.045396,-0.857207,-0.081273,-0.019352,-0.582858,0.048893,-0.430673,0.024367,-0.652848,-0.173900,-0.103000,-0.222951,-0.111415,0.125061,-0.392608,1.075538,-0.795409,0.193842,0.822163,0.380394,-0.570638,0.830844,-0.006598,0.187965,-0.302219,0.058711,0.250516,-0.001474,0.391111,-0.145030,0.544802,0.041820,-0.237543,-0.753315,0.838597', '25928048', '27602116', '1308585', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24735062', '青春派', '剧情', '不疯狂，怎叫青春？居然（董子健 饰）在高考前拍毕业照时，当着全校师生的面，大声地用泰戈尔的诗句向暗恋了三年的黄晶晶（安悦溪 饰）表白，收获了甜蜜的初恋。但很快初恋的甜蜜就被闻讯赶来的母亲（咏梅 饰）破坏了，黄晶晶在居然母亲的刺激下傲然离去，居然伤心的想爬墙挽回初恋，却摔伤了尾骨。失恋加受伤的他高考失利，看着黄晶晶前往复旦的身影，决定复读追逐爱情。开始了一段疯狂的高三历程。在每个青春的回忆中，一个深陷暗恋默默付出的女孩儿，几个情感丰富讲义气的哥们，一群各有故事特色十足的损友，一段所有人共有的回忆。这就是青春派——生活里总在闪烁，永不褪色的一段岁月。©豆瓣', '董子健', '刘杰', 7.4, 168480, 'tt3285802', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2050428637.jpg', 1.1, 4.5, 33.1, 43.8, 17.6, '0.251814,-0.010278,-0.555049,0.579760,-0.047972,-0.662745,0.793538,-0.065081,-0.141627,0.052918,0.196550,0.228909,-0.478151,0.623554,0.104345,-0.271681,-0.018130,-0.749342,-0.040976,-0.005823,-0.148100,-0.336502,-0.004988,0.164858,0.014161,-0.150244,0.626805,0.112367,-0.141824,0.741355,0.323784,0.020319,-0.001747,0.163801,-0.131994,0.206673,0.212944,0.336134,-0.165363,-0.214134,0.122611,-0.414470,-0.002009,-0.022305,-0.242602,0.206372,0.810364,-0.139226,-0.264100,0.269559,0.663822,-0.207557,-0.360879,0.184238,0.183085,0.339395,0.252218,0.058209,-0.260587,0.061871,-0.117938,-0.061316,-0.518378,-0.164274,0.047320,0.242938,-0.638873,0.719701,0.167928,0.047737,0.356947,-0.112869,-0.053455,0.237273,0.169594,0.642081,-0.260289,0.153480,-0.160274,0.529000,0.662388,-0.188365,-0.160548,0.390016,-0.203835,-0.006753,0.088063,0.177461,-0.546966,0.035532,0.258783,-0.264801,-0.078622,0.221638,-0.710831,0.187113,-0.118843,-0.085890,0.034035,-0.347336,-0.421305,-0.238348,-0.139379,-0.268224,-0.527551,0.168678,0.090265,-0.235914,0.938218,-0.662137,0.256348,0.315550,0.144591,-0.332291,0.542781,0.512626,-0.169680,0.065327,0.015668,0.661365,-0.286447,0.062267,0.078649,0.490192,-0.295857,-0.009220,-0.584323,0.702448', '1307146', '5977789', '3811356', '3155839');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24736526', '人间·小团圆', '剧情', '郑惠清（杨千嬅 饰）是一名专职导游，她的丈夫邱健章（曾志伟 饰）是一名开诊所的医师，夫妻两人貌合神离，更出现了第三者（蔡洁 饰）。惠清弟弟郑伟滔（古天乐 饰）是著名的补习老师，妻子恩恩（梁咏琪 饰）是一个事业遇到瓶颈的模特，他们的孩子“小猪”虽然听话乖巧，但是相貌奇丑跟 夫妇二人完全不同，这令伟滔十分郁闷。老父亲郑东（吴孟达 饰）在妻子过世后与夜总会妈妈桑TA姐（吴家丽 饰）相恋，这令儿子伟滔冷眼相待。父子关系恶劣之余姐姐惠清更有解不开的心结，一家人的关系变得疏远。一次鲸鱼搁浅事件终于令一家人能够共同坦然面对生活的困境。©豆瓣', '古天乐', '彭浩翔', 5.5, 65784, 'tt3429014', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178995715.jpg', 21.4, 15.7, 36.7, 19.1, 7.2, '-0.020006,-0.501023,-0.163526,0.476760,0.081564,-0.319259,0.638534,0.401607,-0.714744,-0.402966,0.175810,0.648800,-0.154103,0.532325,0.068458,-0.236174,0.066794,-0.551087,0.189037,0.136694,-0.117651,-0.381563,-0.008582,-0.150376,-0.330462,-0.156895,0.591978,-0.162507,0.096978,0.414958,0.493406,0.245617,-0.265402,0.217508,-0.212206,-0.069411,0.082470,0.370431,-0.593515,-0.185943,-0.038413,0.249209,0.086340,0.020807,0.084997,0.203209,0.561106,0.092190,-0.423568,-0.158756,0.327125,0.028281,-0.119325,0.198755,0.401027,-0.143731,0.503306,0.056536,-0.091734,-0.029710,0.075097,-0.174687,-0.213085,0.251085,0.369456,0.065521,-0.440407,0.347201,0.033071,-0.219108,0.192416,-0.341899,0.186943,0.386076,0.327476,0.390982,-0.195249,0.237645,-0.352131,0.245220,0.589969,0.145107,0.034052,0.587232,-0.309339,-0.390453,-0.062986,-0.200075,-0.664136,0.306066,-0.064943,-0.074701,-0.062152,0.217800,-0.449372,-0.351947,-0.235265,0.364678,0.027033,-0.507409,0.206798,-0.250298,-0.042551,-0.595218,-0.354609,0.144558,-0.009819,-0.365765,0.806737,-0.781082,0.026371,-0.045078,0.250899,-0.569639,0.607220,0.269527,0.314609,-0.629145,0.038640,0.268606,-0.271880,-0.352280,0.042708,0.222662,-0.135500,-0.001836,-0.173592,0.010059', '3445516', '6963575', '1292219', '25738406');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24736566', '北京爱情故事', '爱情', '本片由5段故事组成。北漂屌丝男陈锋（陈思诚 饰）在好友（郭京飞 饰）的告别单身派对上对白领沈彦（佟丽娅 饰）一见钟情，随后两人开展了热恋，不料不久后两人未婚先孕，二人准备结婚但却遭到了沈彦母亲的反对，此时沈的有钱前男友洪江（耿乐 饰）又再次出现了。与此同时陈锋的老板 吴峥（王学兵 饰）由于出轨被老婆张蕾（余男 饰）发现，愤怒的张蕾深夜画着浓妆走出了家门……张蕾的老板刘辉（梁家辉 饰）与佳玲（刘嘉玲 饰）秘密来到希腊偷情，却不料两人因为意见不合险些吵翻。刘辉的女儿阳阳（欧阳娜娜 饰）发现隔壁班的男生（刘昊然 饰）经常跟自己搭乘同一辆车回家，意外认识后两人无话不谈，微妙的感情在两人心中产生。男孩的姥姥（斯琴高娃 饰）得了绝症，乐观的她决定给老伴（王庆祥 饰）找一个新的伴侣协助他走过余生，一名海归老太太（金燕玲 饰）走进了老两口的生活……©豆瓣', '梁家辉', '陈思诚', 6.1, 169949, 'tt3505950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167457161.jpg', 5.1, 17, 50.8, 20.9, 6.2, '0.433187,-0.155433,-0.560055,0.211118,0.094387,-0.537741,0.746575,0.302401,-0.630106,-0.354279,0.110643,0.550195,-0.464061,0.406877,0.328930,-0.042078,-0.259338,-0.527579,0.165428,0.013056,-0.190717,-0.210445,0.059308,-0.076961,-0.244464,-0.047960,0.298349,-0.239686,-0.009355,0.710302,0.558902,0.139392,-0.251669,0.425233,0.013808,0.312124,0.119113,0.219927,-0.401349,0.228670,-0.030892,-0.043478,-0.116067,-0.146823,-0.018184,0.438256,0.701149,0.050725,-0.185469,-0.020822,0.411832,-0.042952,-0.181548,0.199223,0.288165,0.202305,0.365183,-0.048066,-0.124006,0.013716,0.233026,-0.092539,0.168448,0.217862,0.172093,0.096377,-0.576303,0.545510,-0.210732,-0.191602,0.279247,-0.504381,0.230543,0.220533,0.185074,0.434319,-0.098823,0.221143,-0.393298,0.328114,0.539019,0.240998,0.156142,0.314726,-0.095835,-0.393009,-0.153027,0.300914,-0.596785,0.076807,0.446099,-0.025100,-0.008525,-0.129499,-0.584717,-0.195810,-0.037023,0.302052,-0.019574,-0.329330,-0.016682,-0.577997,-0.130314,-0.505228,-0.254360,0.257523,-0.025055,-0.064030,0.441864,-0.739643,0.136960,-0.122215,0.314759,-0.589912,0.542016,0.069779,0.124376,-0.514190,0.040483,0.026780,-0.069152,0.094436,0.161581,0.424593,-0.235459,-0.109675,-0.294159,-0.059584', '3111650', '26687241', '3155839', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24736793', '室友', '恐怖', '一场突如其来的车祸，让独自上京的派遣职员萩尾春海（北川景子 饰）住进医院。期间她邂逅体贴和善的护士西村丽子（深田恭子 饰），对方善解人意，并且殷勤地帮春海与肇事司机工藤谦介（高良健吾 饰）及工藤在保险公司的友人长谷川伸一（尾上宽之 饰）交涉赔偿事宜。出院前夕，春海邀请打算辞职的丽子和她合租公寓。两个女孩气味相投，快乐无比，还共同写下了同居日记交流彼此的心声。但是随着相处时间的增加，春海时不时会发现丽子偶尔闪过的冷酷表情。诡异而可怕的事件交替在她们身边发生，似乎丽子的体内还隐藏着一个名叫玛丽的冷血人格。她想要逃离，最终发现一切并非想象的那么简单……本片根据本格推理作家今邑彩的原作改编。©豆瓣', '深田恭子', '古泽健', 6, 6852, 'tt2998364', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2071264176.jpg', 2.7, 19.3, 56.4, 18.1, 3.5, '0.228568,-0.058568,-0.369415,0.523540,0.039865,-0.088211,0.659192,0.180632,-0.298930,-0.441892,0.241313,0.483544,-0.277619,0.273120,0.271307,-0.046004,-0.242329,-0.606330,-0.186142,0.198458,-0.055457,-0.591550,-0.048724,-0.155630,-0.010305,-0.196574,0.417350,0.002514,0.004633,0.723223,0.092064,0.235805,-0.434974,0.376069,0.040586,-0.096138,0.253555,0.245157,-0.287582,0.099102,0.107992,-0.041753,-0.071248,0.168181,-0.069535,0.435678,0.619236,0.047524,-0.462738,0.105784,0.528662,-0.031278,-0.018940,0.093427,0.180468,0.254045,0.360400,0.222165,-0.291716,-0.047239,0.075166,0.098105,-0.458730,0.104659,0.128711,0.201547,-0.233740,0.276707,-0.054335,-0.100710,0.464263,-0.368355,-0.132402,0.387512,0.468085,0.261708,-0.128709,0.072773,-0.075594,0.106320,0.509644,-0.154767,-0.294829,0.491700,-0.327547,-0.379433,-0.022142,0.020633,-0.277659,0.145494,0.039734,-0.011130,-0.073977,0.098521,-0.417477,-0.216216,-0.213050,0.029458,0.092184,-0.373196,0.034099,-0.862658,-0.118316,-0.368587,-0.470520,-0.011924,0.091637,-0.207995,0.550625,-0.727229,0.048930,0.494000,0.281512,-0.353155,0.395126,0.229003,-0.181084,-0.217609,-0.060236,0.203715,0.128398,0.076842,0.013709,0.400759,-0.115361,-0.056506,-0.518124,0.147532', '3811356', '5403927', '25723905', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24741412', '哪啊哪啊神去村', '剧情', '因为考大学失败，刚刚告别高中时代的都市青年平野勇气（染谷将太 饰）站在人生的十字路口。他偶然被林业培训生宣传材料上的美丽女孩所吸引，于是脑瓜一热来到三重县一个连手机信号都没有的偏僻小山村接受为期一年的林业培训课程。一开始他吊儿郎当，毫无干劲儿，因此饱受前辈饭田与喜（伊藤英明 饰）的斥责。正当勇气准备逃离之际，与封面美女石井直纪（长泽雅美 饰）不期而遇让他鬼使神差地又回到宿舍。前期培训结束，勇气随着饭田前辈来到神去村，跟随师父（光石研 饰）开始实地修行与学习。严苛的环境打磨着这个都市青年的骄傲和浮躁，不知不觉中他已成长为足以独当一面的优秀伐木工……本片根据三浦紫苑的同名原作改编。©豆瓣', '染谷将太', '矢口史靖', 8.6, 154549, 'tt2964120', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2212173720.jpg', 0.2, 0.8, 11.5, 46.1, 41.5, '0.225307,-0.074078,-0.544549,0.457025,-0.173771,-0.432801,0.379758,0.090800,-0.420417,-0.370249,0.315617,0.671647,-0.247178,0.398473,0.360071,-0.284739,-0.306667,-0.593092,-0.180155,-0.035498,-0.092399,-0.394043,0.085850,0.031603,-0.298186,-0.353709,0.917526,0.100716,-0.152198,0.517229,0.066820,0.129397,-0.131878,0.298806,-0.063593,0.009419,0.200565,0.031117,-0.096237,0.161907,-0.258362,-0.226203,-0.356961,0.032291,0.080843,0.279165,0.687237,0.019288,-0.340372,-0.116675,0.573835,-0.009497,-0.235397,0.227355,0.249874,0.024101,0.029276,0.116711,-0.192980,0.116012,-0.099122,-0.529440,-0.439454,-0.111739,0.079520,-0.028805,-0.531262,0.278601,0.031741,-0.318395,0.258470,-0.399435,-0.108355,0.336007,0.339877,0.320913,-0.180920,0.187625,0.103777,0.335634,0.558786,0.042983,-0.091022,0.362059,-0.083615,-0.543748,-0.013369,-0.223012,-0.367113,-0.045115,0.068026,0.171741,-0.103215,-0.125958,-0.497405,0.086143,-0.065952,-0.144838,0.067499,-0.256072,-0.306768,-0.641369,0.021674,-0.289521,-0.316595,0.154281,0.112210,-0.226399,0.858657,-0.899222,0.045165,0.289284,0.256538,-0.103236,0.494657,-0.091360,-0.053142,-0.169295,-0.046260,0.362318,-0.074796,0.691289,-0.071683,0.509471,-0.448020,-0.049919,-0.558642,0.378099', '10174444', '3811356', '26784898', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24742719', '至暴之年', '剧情', '电影《至暴之年》影片讲述在20世纪80年代的纽约，一名野心勃勃的商人被迫与一家腐败的商业机构打交道的故事。', '奥斯卡·伊萨克', 'J·C·尚多尔', 6.9, 6295, 'tt2937898', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2213497829.jpg', 1.6, 7.8, 44.2, 38.3, 8.1, '0.403147,-0.246007,-0.398218,0.791955,0.358707,-0.279754,0.862987,0.118754,-0.550405,-0.706895,0.232101,1.076810,-0.226556,0.051855,0.477241,-0.332980,0.127011,-0.785983,-0.215295,-0.244145,0.338376,-0.257563,-0.300900,-0.334360,-0.497216,-0.530859,0.823768,0.166004,-0.382000,0.267032,0.196742,0.263587,-0.162987,-0.177191,-0.549524,-0.466979,0.295641,0.264962,-0.779148,-0.068485,-0.191051,-0.473980,-0.238877,-0.399092,-0.164205,0.232392,0.727778,0.013222,0.253782,-0.140694,0.914671,0.100981,-0.382175,-0.260494,0.693453,0.193953,0.482843,0.699935,0.309574,-0.328583,-0.386200,-0.257713,-0.703430,-0.045027,0.126654,0.238066,-0.549138,0.456855,0.268780,0.518605,-0.481854,-0.378791,0.346671,0.297506,0.718887,0.922435,0.465057,0.101047,-0.655268,0.751586,0.826477,0.325866,-0.318659,0.723323,-0.157120,-0.716613,-0.453597,-0.482766,-0.986920,-0.127545,0.301809,-0.757668,-0.657806,0.703360,-1.216186,0.186166,0.268329,-0.301041,0.758746,-0.039149,-0.097979,-1.117915,-0.567512,-0.554784,0.086116,0.030157,0.486012,-0.261986,1.136689,-0.730058,0.244204,0.875543,0.183151,-0.892924,1.227773,-0.174566,-0.008230,-0.042140,0.104789,0.555412,0.101372,-0.080647,-0.507599,0.500100,-0.380758,-0.478413,-0.335102,0.478704', '22265121', '26611806', '1908036', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24743015', '哭泣的男人', '动作', '坤（张东健 饰）是一名技艺精湛的冷血杀手，效力于黑社会组织，深受上司的信赖。然而，一段不堪回首的往事使他生活在愧疚之中，对自己一直以来从事的行业亦产生了疑惑和动摇，就在此时，组织派给了他一个十分重要的任务，命他前往韩国，刺杀名为崔木景（金敏喜 饰）的女子。崔木景是一个悲剧般的女人，一场意外夺走了她的丈夫和孩子的性命，失去了生命中的挚爱，这位悲伤的妻子和母亲，终日沉浸在绝望之中，只能依赖酒精和药物度日，不仅如此，她还得照料患有阿兹海默症的母亲。当坤出现在崔木景的面前，他的身份不仅仅只是一个想要夺取她性命的杀手，女儿的死令崔木景的心中充满了疑问，而答案就在坤的手中。©豆瓣', '张东健', '李桢凡', 6.7, 9428, 'tt3697566', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2184034235.jpg', 1.7, 10.4, 48.6, 27.9, 11.5, '0.042585,0.090353,-0.792088,0.913621,-0.449053,-0.238118,0.908270,-0.000012,-0.626872,-0.266742,0.425209,0.931234,0.279648,0.364734,0.192212,-0.129069,0.027374,-0.896236,-0.241734,-0.226357,-0.224893,-0.511712,-0.395340,-0.309450,-0.267242,-0.595833,0.798777,0.221176,-0.266892,0.439026,0.408570,0.564985,-0.106856,0.678651,-0.218736,-0.144104,-0.007422,-0.028500,-0.244018,0.031192,0.240257,-0.523317,-0.018398,0.672626,-0.184671,0.352705,0.694694,-0.371893,-0.305074,-0.247968,0.275968,-0.453601,-0.110449,0.097775,0.210637,0.050557,0.170548,0.301462,-0.460117,-0.062161,0.125406,0.013787,-1.187551,-0.220440,0.230006,0.170450,-0.870027,0.605325,-0.179148,-0.011027,0.015724,-0.286657,0.416646,0.037860,0.160013,0.599611,-0.510834,-0.000363,-0.416406,0.322521,0.772849,-0.164604,-0.104672,0.386547,-0.277043,-0.335124,-0.148104,-0.353362,-0.736728,0.005682,0.238161,0.035145,-0.265506,0.373265,-0.344485,0.088340,-0.204097,-0.101950,-0.003353,-0.457809,-0.094498,-0.171076,-0.113067,-0.397573,-0.517841,0.053484,0.252921,-0.405494,0.893678,-0.950463,0.252155,0.486893,0.095012,-0.786552,0.708443,0.308544,0.125427,-0.229759,-0.203979,0.346267,0.023822,-0.038020,0.004238,0.168430,-0.219223,0.213588,-0.448116,0.548063', '30163500', '26678784', '3119246', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24743119', 'X射线营地', '剧情', '可儿（克里斯汀·斯图尔特 Kristen Stewart 饰）厌倦了日复一日的生活，周围一成不变的一切让她简直就快要发疯，于是，可儿做出了一个疯狂的决定，成为一名军人。就这样，穿上了迷彩服的可儿被分配到了专门关押恐怖分子的关塔那摩湾监狱，在那里，她遇见了名为阿里（佩曼·莫阿迪 Peyman Moaadi 饰）的穆斯林男子。监狱里发生的种种事迹一再地刷新着可儿的三观，亦让可儿开始思考什么才是真正的公平的正义，与此同时，可儿和阿里之间的关系也产生了变化，一种奇妙的“友谊”成为了联系两人的纽带。然而，可儿终究只是过客，她万万没有想到的是，自己的离开竟然会让阿里丧失继续活下去的希望。©豆瓣', '克里斯汀·斯图尔特', '彼得·萨特勒', 7.3, 7382, 'tt2994190', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2196486172.jpg', 1.5, 5.4, 36.4, 39.9, 16.8, '0.701146,0.083743,-0.804538,0.571169,-0.232097,-0.425280,0.802248,0.006699,-0.528467,-0.165475,0.331111,0.633390,-0.334188,0.182553,0.249194,0.177396,-0.221675,-0.959025,-0.148676,-0.070205,-0.399720,-0.410933,-0.177716,0.060638,-0.121951,-0.145089,0.588820,-0.093850,-0.173231,0.483620,0.157192,0.088747,0.133626,0.645959,-0.025136,0.216642,0.158597,-0.048219,-0.070621,0.114881,0.191367,-0.044007,0.017165,0.537887,-0.182027,0.327954,0.658402,-0.463693,-0.294003,0.121891,0.353459,-0.436685,0.093982,0.210673,0.104159,0.017192,0.058669,0.262241,-0.304805,-0.077264,0.170716,0.263855,-0.878547,0.045997,0.023260,0.241138,-0.596088,0.464513,0.107850,-0.320447,0.237581,-0.255008,0.281102,0.416380,0.472206,0.522946,-0.313044,-0.147295,-0.632031,0.047073,0.839441,-0.093990,-0.512911,0.205425,-0.206096,-0.189473,-0.122978,-0.101716,-0.448093,-0.255101,0.166053,0.041408,-0.326146,0.283871,-0.747932,0.070332,-0.406371,-0.244560,0.047191,-0.368866,0.034011,-0.326495,-0.200453,-0.518586,-0.506998,0.057459,0.089542,-0.457546,0.588514,-0.938900,0.258693,0.573312,0.286224,-0.573364,0.404058,0.063433,0.073571,0.104208,0.145724,0.364528,-0.053239,0.393999,0.160448,0.453162,0.126022,0.126977,-0.312370,0.630560', '1301022', '1308755', '35030151', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24743709', '北京纽约', '剧情', '2008是中国腾飞的一年，又是美国经济衰退的一年。北京，纽约，两座城市相隔万里，迥异的文化背景下来自异乡的人们都在找寻着自己的理想与幸福。茉莉（林志玲 饰），一个美丽的中国女人，年幼时只身到纽约追逐梦想；蓝一（刘烨 饰），茉莉青梅竹马的恋人，通过在北京不懈奋斗，功成名就；乔（理查德·德克里克 饰），一个才华横溢的美国男人，励志成为摄影师。命运安排让茉莉在两个男人、两种生活方式、两种文化之间作出抉择……', '林志玲', '李晓雨', 4.3, 13930, 'tt2313112', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2230505723.jpg', 31.7, 34.7, 23.6, 6.2, 3.8, '0.105952,0.059109,-0.499747,0.812272,-0.035275,-0.251471,0.578079,0.055121,-0.323084,-0.171929,0.189890,0.810113,-0.039432,0.569533,0.354632,0.114488,-0.077051,-0.780754,0.118464,-0.101901,-0.179104,-0.484272,-0.417931,-0.371505,-0.073884,-0.260987,0.697503,0.137930,0.006983,0.355676,0.172476,0.275529,-0.264132,0.199662,-0.406771,-0.151757,0.295740,0.191082,-0.648753,0.299548,-0.182289,-0.271809,-0.199948,0.142170,-0.417463,0.060242,0.853681,-0.060683,0.011301,-0.182921,0.555000,-0.126748,-0.416608,-0.126640,0.302298,-0.379005,-0.078417,0.323894,-0.162886,-0.050460,0.061109,-0.061183,-0.444348,-0.039432,0.239382,0.132659,-0.683826,0.522499,0.218429,-0.099556,0.101078,-0.551740,-0.090806,0.435683,0.333832,0.714952,-0.159750,0.244011,-0.464760,0.601218,1.029111,0.196596,-0.470055,0.181529,-0.503167,-0.452387,-0.101237,-0.074187,-0.876497,-0.205481,-0.042245,-0.308400,-0.022112,0.207254,-0.998731,0.363850,-0.201430,-0.047189,0.298328,-0.547048,0.120151,-0.761222,-0.111219,-0.684335,-0.413777,0.056211,0.206646,-0.307076,1.038355,-0.679759,0.034238,0.753732,0.165177,-0.607341,0.958055,0.114844,0.082507,-0.513524,0.113953,0.540595,-0.236485,-0.223537,-0.387433,0.361951,-0.106069,0.483755,-0.451765,0.764984', '30162520', '3811356', '26926321', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24743711', '催眠大师', '悬疑', '著名的心理治疗师徐瑞宁（徐峥 饰）擅长催眠治疗，深得业界的赞扬。但是心高气傲的他却遭遇了职业生涯中最棘手的案件，那就是恩师方教授（吕中 饰）推荐给他的女病人任小妍（莫文蔚 饰）。一天晚上，女助手Amy（杨凯迪 饰）引见来了任小妍，但是这个女病人似乎一直都不太配合，对待医生态度强硬，而且坚信自己能有超自然的能力，瑞宁觉得她没有说出真相，于是开始了催眠疗法。意想不到的是任小妍反而掌控了局面，而真相居然与瑞宁的妻子（胡静 饰）以及好友洛雨凇（王耀庆 饰）有关，任小妍的身份真正是什么？瑞宁似乎掉进了一个设计好的陷阱里……本片是陈正道导演自《101次求婚》之后的一部力作，徐峥担任了本片监制及主演。©豆瓣', '徐峥', '陈正道', 7.6, 382381, 'tt3720058', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2181062460.jpg', 0.4, 2.6, 29.8, 51.5, 15.7, '0.179197,-0.069309,-0.431570,0.769548,-0.301601,-0.209220,0.513119,0.001587,-0.602952,-0.573517,0.319960,0.484830,-0.228567,0.073073,0.247076,-0.033639,-0.130091,-0.502694,0.122313,-0.188726,-0.448717,-0.515255,-0.343015,-0.174407,-0.135963,-0.115149,0.463082,0.039526,-0.391827,0.092210,0.374979,0.359304,0.358208,0.546601,0.134214,0.168736,0.215995,-0.105093,-0.045129,0.195231,0.341196,-0.399085,-0.233254,0.579901,0.007312,0.423964,0.386420,-0.285683,-0.309197,-0.043941,0.604707,-0.379077,0.100620,0.119735,0.071600,0.178337,0.407752,0.122744,-0.090677,0.183929,0.132169,-0.013171,-0.813442,0.073467,0.268907,0.070006,-0.418329,0.169149,-0.100417,-0.105481,-0.157035,-0.202925,0.387581,0.211876,0.374188,0.287938,-0.148921,-0.029537,-0.471532,0.430162,0.432922,0.103007,-0.195653,0.446189,-0.222424,-0.666903,-0.005942,-0.166733,-0.413931,0.220074,0.120653,0.052518,0.028980,0.076639,-0.213928,-0.155826,-0.226060,0.042976,-0.145147,-0.313096,0.171284,-0.415507,-0.182744,-0.573727,-0.152304,-0.187273,0.067020,-0.400907,0.874316,-0.823606,-0.074570,0.151110,0.060685,-0.557515,0.747159,0.242772,0.019850,-0.065651,0.074622,-0.066373,-0.041318,0.026324,0.092857,0.436699,0.236421,-0.403936,-0.160523,0.146097', '25932086', '27602116', '24284209', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24743712', '有种你爱我', '喜剧', '左小欣（江一燕 饰）是一位小有名气的建筑师，快乐充实而又衣食无忧的生活让她无需拿婚姻当“饭碗”，目睹过感情脆弱的她对男人亦失去了最基本的信任。然而，随着时间的推移，左小欣想要一个孩子了，如何跳过“男人”和“婚姻”得到“孩子”？这成为了左小欣目前正在研究的最大难题。一次偶然中，左小欣结识了名叫查义（郑凯 饰）节目主持人，一来二去之中，左小欣的腹中怀上了查义的骨肉，然而对于这一切以及左小欣的“阴谋”，单纯懵懂的查义一无所知。一晃眼一年过去，左小欣将一切的真相告诉了查义，在震惊和愤怒的同时，血浓于水的亲情亦在查义的内心中荡漾开来。©豆瓣', '江一燕', '李欣蔓', 4.6, 49856, 'tt4561398', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2225669293.jpg', 21.7, 36.7, 32.4, 6.2, 3, '0.180104,0.060518,-0.678712,0.618869,-0.176158,-0.268394,0.889918,-0.183882,-0.646725,-0.225834,-0.092957,0.568653,-0.209745,0.342721,0.305906,-0.030997,-0.015785,-0.729007,-0.245465,-0.391308,-0.247278,-0.376233,-0.245696,-0.143268,-0.230528,-0.282195,0.923162,0.262730,0.066575,0.350703,0.473868,0.164485,-0.007595,0.455998,-0.208511,0.011165,-0.107987,0.242207,-0.381370,0.104375,0.266872,-0.256716,-0.069503,0.295285,-0.140930,0.238978,0.673383,-0.373141,-0.081339,-0.070656,0.498098,-0.324109,-0.106202,0.103072,0.068060,0.116916,0.220280,0.286970,-0.379974,-0.037649,0.032762,-0.121890,-0.925605,-0.074088,0.164603,-0.001055,-0.574934,0.582013,0.062814,-0.464755,0.123772,-0.163347,0.216101,0.467526,0.382494,0.550268,-0.538721,0.109877,-0.317293,0.142337,0.678491,0.135473,-0.201613,0.756904,-0.290156,-0.368368,-0.029732,-0.343096,-0.383600,0.023751,0.073736,0.412288,-0.233115,0.476687,-0.241202,0.140422,-0.107094,-0.337643,0.197667,-0.703971,-0.179631,-0.144866,-0.334414,-0.343887,-0.379258,-0.004884,0.205931,-0.447671,0.942031,-0.930986,0.137233,0.251269,0.240844,-0.476246,0.622233,0.290275,0.252375,-0.371136,-0.047917,0.250709,-0.020247,0.193111,0.126624,0.267504,-0.173613,-0.127214,-0.460404,0.463896', '2053515', '3318473', '25880986', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24743728', '夜孔雀', '剧情', '法国女留学生埃尔莎（刘亦菲 饰）在成都爱上了丝绸研究员、尺八高手马荣（黎明 饰），后又在巴黎与马荣的兄弟、纹身师建民（刘烨 饰）之间产生情感。前者找到了一种符合他理想的蚕——夜孔雀，后者把蝶化的夜孔雀永远铭刻在艾尔莎的肌肤上。', '刘亦菲', '戴思杰', 4.9, 35337, 'tt4310356', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2350515472.jpg', 23.8, 32.8, 26.4, 9.4, 7.7, '0.336230,0.341827,-0.470971,0.686045,0.110819,-0.099993,0.598917,0.243178,-0.548158,-0.014382,0.590570,0.592747,-0.187847,0.207822,0.453061,0.167335,-0.214207,-0.870417,0.036835,-0.169670,-0.282809,-0.163113,-0.264866,0.218286,-0.319538,-0.300664,0.858445,0.295819,-0.000735,0.532839,0.229396,0.159756,-0.147636,0.088224,-0.109713,-0.025424,0.172021,0.047288,-0.208593,0.164810,0.165606,0.058889,0.271783,0.070445,-0.455859,-0.010285,0.997605,-0.494684,0.161578,0.012079,0.519907,-0.129390,0.029870,0.217522,0.165737,0.026814,-0.069407,-0.145830,-0.186561,-0.040961,0.265630,0.316250,-0.110724,0.187276,0.194179,0.491043,-0.487381,0.806038,-0.215145,-0.007659,0.108330,-0.282448,0.023532,-0.060011,0.070172,0.218968,0.018879,-0.015385,-0.332631,0.500230,0.396352,0.288084,-0.202013,-0.094281,-0.513845,-0.674203,-0.593838,0.182077,0.044989,-0.320221,0.535958,-0.062149,-0.255535,0.150422,-0.905852,-0.042955,0.041179,0.460888,0.116543,-0.189402,-0.079947,-0.790619,-0.161229,-0.760722,-0.165632,0.093451,0.520777,-0.208163,0.485797,-1.056515,0.085443,0.295187,0.398347,-0.101103,0.655273,-0.387927,-0.174960,-0.348823,-0.015802,0.313637,-0.106556,-0.063136,0.168374,0.625513,-0.157941,0.278403,-0.249470,0.497453', '1826173', '26365262', '24839498', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24745500', '绣春刀', '剧情', '明崇祯皇帝登基，大太监魏忠贤（金世杰 饰）及其“阉党”被锦衣卫倾巢覆灭。锦衣卫中以卢剑星（王千源 饰）、沈炼（张震 饰）和靳一川（李东学 饰）三结拜兄弟最为勇猛正直。老大卢剑星为了升官百户，沈炼为替教坊司妓女周妙彤（刘诗诗 饰）赎身，三弟靳一川为摆脱浪人丁修（周一围 饰）的纠缠，三兄弟决定接受东厂都督赵靖忠（聂远 饰）追杀魏忠贤的秘密行动。行动中三人遭到魏忠贤义女魏廷（朱丹 饰）带队阻拦，一场腥风血雨后魏忠贤尸首被带回，卢剑星如愿以偿升官百户，本以为三人夙愿皆能实现，但没想到沈炼竟然隐瞒了一个天大的秘密，并且引起了大臣韩旷（赵立新 饰）的怀疑。此后三兄弟都面临着生命危险，沈炼终于说出真相但为时已晚，与一川相好的医馆女子（叶青 饰）和周妙彤都被牵连其中。面对危机，沈炼决意带着兄弟、爱人离开京城，朝廷腐朽混乱，小人物的命运将何去何从？©豆瓣', '张震', '路阳', 7.6, 431686, 'tt4019426', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194066391.jpg', 0.7, 2.8, 28.1, 50.2, 18.2, '-0.029822,-0.034787,-0.317234,0.275578,0.041308,-0.191321,0.451594,0.356025,-0.723488,-0.411096,0.413625,0.239610,-0.073194,-0.180526,0.354454,-0.337054,0.080961,-0.496269,-0.050158,-0.067898,0.031145,-0.423421,-0.011493,-0.130165,-0.268443,0.124593,0.541897,0.162708,0.173886,0.395544,0.420249,0.133034,-0.265971,0.376377,0.261961,0.218195,0.162181,-0.092987,-0.437447,-0.145380,-0.180532,-0.342437,-0.191192,-0.016090,-0.167445,0.083326,0.398273,-0.304348,0.217431,-0.325417,0.081555,-0.283675,0.076922,0.355905,0.134438,0.185845,0.096420,0.564030,-0.014156,-0.142243,0.088608,0.040351,-0.345802,0.243972,0.417428,-0.009286,-0.437837,0.077069,-0.330895,0.001648,-0.151911,-0.249798,0.232920,0.416952,0.457291,0.023464,-0.348761,0.170952,-0.633285,0.317595,0.482714,-0.152004,0.160502,-0.509213,0.280391,-0.224875,0.216344,-0.322933,-0.230349,0.105733,0.277262,-0.059562,0.187565,0.244408,-0.110576,-0.381080,-0.441530,0.321353,0.073073,-0.197281,-0.038654,-0.109543,-0.242027,-0.007400,-0.279640,0.070237,0.379032,-0.208046,0.330021,-0.328391,-0.105183,0.060810,0.250851,-0.878475,0.284044,0.233968,0.440310,-0.151015,-0.052377,-0.129467,0.176012,0.161698,0.223837,0.045096,-0.281860,-0.280065,0.064705,-0.149134', '1484760', '1302110', '1306249',