INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24746649', '杀戮指令', '动作', '在高度机械化的未来，先驱者集团的高级技术员梅尔斯发现，自己研发的S.A.R.型军用战斗机器人出现多起自我编程现象。与此同时，一直精英陆战小队被分派到先驱者集团的机器人训练基地进行实弹演练。梅尔斯跟随小队来到这个孤岛，发现通讯被阻断。由普科斯率领的小队在和小波机器人作战后，夜晚一名哨兵被机器人杀死，一场单纯的训练变成殊死战役。这座小岛正是S.A.R.型机器人的训练场地，而梅尔斯也发现，发出这次实弹演练指令的正是岛上的一个机器人...', '凡妮莎·柯比', '史蒂文·戈麦斯', 5.8, 7679, 'tt2667380', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2351977699.jpg', 4.2, 23.9, 52.5, 15.2, 4.2, '0.142488,-0.121126,-0.868767,0.691762,-0.258933,0.099878,0.611729,-0.312247,-0.311831,-0.531578,0.637559,0.614994,0.203235,0.004339,0.244515,-0.527824,-0.211972,-0.464998,-0.583736,0.117930,-0.461873,-0.509437,0.020697,-0.392781,0.415209,-0.738004,1.062232,-0.192247,-0.344422,0.238537,0.009500,0.464084,-0.270549,0.231415,0.193435,-0.278255,0.579861,-0.515252,-0.134573,0.393173,-0.743368,0.296746,0.063179,-0.121901,-0.134169,0.124943,1.087204,-0.283132,-0.183351,-0.394372,0.141197,-0.280580,0.138374,-0.402095,0.762546,0.339458,-0.391070,-0.231337,0.148307,0.402948,-0.283677,-0.116369,-0.820499,-0.093911,0.058580,-0.068153,-0.569035,0.230325,-0.337973,0.104987,0.045502,-0.279907,0.249505,0.714353,0.538932,0.406958,-0.298145,0.393712,-0.660934,-0.028528,0.502679,-0.271231,-0.607434,0.124365,0.251966,-0.775796,-0.132640,-0.405546,-0.001412,-0.205342,0.037436,-0.052080,-0.022999,0.064299,-0.974670,0.495954,-0.206354,-0.648393,0.020002,-0.279364,-0.211753,-1.449108,0.387976,-0.126581,-0.421227,0.723659,-0.327173,-0.119392,0.534225,-1.078300,0.218005,0.458814,0.076677,-0.224753,0.370025,-0.287971,0.052722,-0.441210,0.102267,0.191650,0.240251,0.642686,0.077610,0.544400,-0.196459,-0.352043,-0.585121,0.248696', '2369613', '1306809', '1307897', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24746974', '僵尸来袭', '动作', '机械工程师巴瑞（Jay Gallagher 饰）原本和妻子安妮（Catherine Terracini 饰）、女儿梅根（Meganne West 饰）  过着快乐无忧的生活，但在一个不祥之夜，他们的人生发生了翻天覆地的巨变。沉睡中的巴瑞突然接到妹妹布鲁克（Bianca Bradey 饰）的电话，妹妹声称朋友们毫无征兆的情况下甚至错乱，变成了凶恶残暴、嗜血如命的恐怖丧尸。话音未落之际，巴瑞一家也遭到丧尸们的袭击。夜幕退去，曙光降临。布鲁克被两名全副武装的士兵解救，随后则被打晕带走。与此同时，逃难中的巴瑞则不得不面对妻子女儿尸变的悲惨一幕。途中他遇到了其他的幸存者，为了搭救被困的妹妹，巴瑞选择穿越丧尸群集的恐怖地带……©豆瓣', 'Jay Gallagher', '凯亚·罗奇-特纳', 6.4, 9897, 'tt2535470', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2236430938.jpg', 3.2, 13.1, 50.6, 25.6, 7.5, '0.315396,-0.259625,-0.748376,0.324067,-0.089093,0.006528,1.144011,-0.033644,-0.423497,-0.268285,0.561414,0.601989,-0.143362,0.219134,0.410842,-0.219591,-0.041141,-0.579481,-0.233210,0.130908,-0.405319,-0.027846,-0.501293,-0.363374,0.213500,-0.528134,0.431163,0.116800,-0.033393,0.695771,0.053930,0.627676,-0.531539,0.489553,-0.035860,0.155823,0.148035,-0.115348,-0.292999,0.204698,-0.259663,-0.265168,-0.005749,0.191775,-0.255794,0.317559,0.806263,-0.636615,-0.242063,-0.315989,0.244737,-0.338932,0.006862,0.312457,0.338186,0.054677,0.099435,-0.016592,-0.022813,-0.085772,0.015961,-0.009942,-0.611696,0.198372,-0.035378,0.160163,-0.545441,0.161449,0.045539,0.078404,0.266593,-0.382070,0.364738,0.172406,0.193314,0.498061,-0.213186,0.096580,-0.550343,0.076998,0.844868,-0.092212,-0.268769,0.175810,-0.194205,-0.256253,0.084379,-0.136495,-0.561539,0.144804,0.569978,0.191739,-0.305436,0.556584,-0.542275,0.027042,-0.385858,-0.147750,-0.457570,-0.152899,-0.536079,-0.383082,0.099101,0.022528,-0.326610,0.445010,-0.074294,0.078455,0.657702,-0.685542,0.523965,0.265045,0.441492,-0.351237,0.300946,-0.127749,0.181650,0.093782,-0.041246,0.299265,0.170860,0.320684,0.184942,-0.014724,-0.366368,-0.095857,-0.188526,0.473739', '21619567', '1428054', '25884436', '20451118');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24750126', '荒蛮故事', '剧情', '《荒蛮故事》是一部黑色喜剧，由6个独立的暴力复仇小故事构成。影片是一次对于人类失控行径的颠覆性创作，从怪异的幽默感，独特的画面和大胆的配乐，到对于身处绝境的普通人这一题材的偏爱，都可以清晰地看到南美鬼才导演达米安·斯兹弗隆与阿莫多瓦在创作方面的相似之处。不过，斯兹弗隆仍然通过这部影片发出了自己独特的声音：一场对于一个腐败成风、经济和社会严重不平等的社会的尖锐抨击。', '达里奥·格兰迪内蒂', '达米安·斯兹弗隆', 8.8, 412596, 'tt3011894', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2584519452.jpg', 0.2, 0.6, 8.5, 41.7, 49, '0.459854,0.180263,-0.693742,0.974705,0.029050,0.266458,1.035282,-0.083386,-0.506925,-0.202896,0.249667,0.809972,-0.293598,-0.135566,0.128985,-0.075960,-0.166826,-0.608399,-0.329154,0.099886,-0.191910,-0.628081,-0.671868,-0.407790,-0.331846,-0.513225,0.765940,0.142209,-1.126296,0.340057,0.235415,0.274055,-0.080745,0.203877,-0.106226,-0.299039,0.003901,0.164090,-0.327568,-0.044521,0.370335,-0.038180,-0.328533,0.161282,-0.430622,0.285137,0.615760,-0.581966,-0.355906,0.300918,0.794208,-0.152013,-0.450903,0.091996,-0.005396,-0.003492,0.499588,0.361574,0.054167,0.143201,-0.222996,-0.209236,-1.286876,-0.073556,0.135223,0.267823,-0.145845,0.515931,-0.077158,-0.474617,0.170225,-0.459747,-0.111068,0.003270,0.759339,0.964553,-0.290607,0.203491,-0.147756,0.103573,0.720229,0.466010,-0.943052,0.596976,-0.455306,-0.652961,-0.355606,-0.418743,-0.523898,0.156951,0.252050,-0.227516,-0.116387,0.431653,-0.928653,0.315751,0.094266,-0.436076,0.010231,-0.317884,-0.237496,-0.506844,-0.562461,-0.536738,-0.004421,-0.004691,0.422466,-0.238486,1.220610,-0.797659,0.063872,0.461295,0.031281,-0.315999,0.590884,0.087874,-0.257028,-0.347717,-0.380198,0.002693,-0.075812,0.085806,-0.021021,0.577086,0.172630,-0.438925,-0.653989,0.691188', '27602116', '24284209', '6844861', '26667010');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24750460', '地狱男爵：血皇后崛起', '动作', '地狱男爵（大卫·哈伯 David Harbour 饰）本是作为生物武器被纳粹召唤出来的怪物，却幸运得到了布鲁姆教授（伊恩·麦柯肖恩 Ian McShane 饰）的营救和帮助，在教授的教导和训练之下，地狱男爵渐渐长大，之后加入了超自然调查防御局，成为了局里的王牌战将。某日，被镇压了千年的女巫血皇后（米拉·乔沃维奇 Milla Jovovich 饰）突破了收容，为了报复人类，她从地狱里召唤来一批可怕的怪兽，攻陷了伦敦。有能力和血皇后对抗的，只有地狱男爵一人，在通灵少女爱丽丝（萨莎·莱恩 Sasha Lane 饰）和上校本（金大贤 饰）的帮助下，一场艰苦且旷日持久的战斗开始了。©豆瓣', '大卫·哈伯', '尼尔·马歇尔', 5.7, 58316, 'tt2274648', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2623581295.jpg', 4.7, 24.8, 53, 14.8, 2.8, '0.181159,0.197367,-0.413385,0.450699,-0.133306,-0.148948,0.474265,-0.006947,-0.339473,-0.077510,0.528109,0.750156,-0.094888,-0.091889,0.206821,-0.075843,-0.385127,-0.366132,-0.119382,-0.078188,-0.484917,-0.371921,-0.605752,-0.070178,0.235529,-0.810077,0.580930,0.095225,-0.204983,0.301445,0.097077,0.548817,0.035713,0.168918,-0.120045,-0.076503,0.284560,-0.028818,0.074766,0.471345,-0.066827,-0.094203,-0.122093,0.178519,0.153652,0.242079,0.459437,-0.770040,0.392337,-0.311364,0.124385,-0.443573,-0.036749,0.245700,0.314504,0.152156,0.163703,0.247469,-0.004960,0.012005,-0.042116,-0.175311,-0.973189,-0.140812,0.093439,0.054693,-0.604417,0.249484,-0.074824,0.126381,0.261017,-0.174143,0.144680,0.319833,0.049792,0.395121,-0.111406,-0.047126,-0.565885,0.255680,0.568497,-0.406471,-0.348251,-0.123472,-0.055598,-0.562702,-0.018478,-0.360594,-0.116315,-0.145137,0.506002,0.027859,-0.048496,0.321112,-0.957538,-0.245796,-0.714183,0.073299,-0.237897,-0.232622,-0.074178,-0.608369,-0.231798,-0.030480,-0.178242,-0.097250,0.125425,-0.268435,0.697238,-0.810940,0.333404,0.385493,0.342803,-0.090259,0.532517,-0.159394,0.208591,-0.120498,0.138864,0.160838,0.188484,0.522157,0.301641,0.500863,0.141650,0.000710,-0.331139,0.495880', '1308585', '1793491', '1422920', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24750534', '蝙蝠侠大战超人：正义黎明', '动作', '故事发生在大都会之战18个月后，在那场战斗中许多建筑和市民惨遭波及。因为超人（亨利·卡维尔 饰）帮助人类解决了很多问题而被当做神来膜拜，但超人也因与佐德之战对城市造成的破坏而遭到逮捕和审讯，一度成为都市传说的蝙蝠侠韦恩（本·阿弗莱克 饰）重新出现在人们面前，他似乎正是为了惩罚超人而来。年轻的富豪莱克斯·卢瑟（杰西·艾森伯格 饰）又在二者的矛盾中挑拨离间，神秘的戴安娜·普林斯（盖尔·加朵 饰）也因自己的目的介入其中……©豆瓣', '本·阿弗莱克', '扎克·施奈德', 6.9, 275902, 'tt2975590', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2316834186.jpg', 2.6, 10.2, 40.7, 30.8, 15.7, '0.295714,0.123268,-0.799912,0.286803,-0.072618,-0.052361,1.006104,-0.021550,-0.427396,-0.568617,0.299141,1.017478,-0.364407,-0.064906,0.562227,-0.259239,-0.291788,-0.569165,0.223696,-0.215060,-0.219764,-0.495355,-0.360150,-0.303200,0.033077,-0.588978,0.593445,0.149467,-0.436646,0.437973,0.190946,0.508100,-0.044467,0.444779,0.130561,0.021842,0.023562,-0.003003,-0.226811,0.208084,-0.256737,-0.366870,-0.140369,0.340690,-0.097111,0.311469,0.614242,-0.640115,-0.263484,-0.201750,0.367490,-0.471428,0.013910,0.028167,0.427887,-0.231447,0.248037,0.275118,-0.057345,-0.139942,0.306033,-0.198036,-0.808782,-0.008416,0.110404,0.244995,-0.263778,0.396398,0.108784,-0.183153,0.018021,-0.047301,0.255575,0.455818,0.546350,0.275867,-0.202474,-0.095514,-0.635949,-0.021311,0.536803,0.011459,-0.253037,0.162607,-0.175277,-0.342427,-0.329592,-0.297748,-0.366109,-0.002355,0.289933,-0.095434,-0.215316,0.571099,-0.674730,-0.095240,-0.329902,-0.205374,-0.215850,-0.355362,-0.094551,-0.822277,-0.193700,-0.355857,-0.168605,-0.278920,0.120999,-0.283524,0.551237,-0.973123,0.378574,0.452934,0.206380,-0.609242,0.313063,0.194865,0.179976,-0.135949,-0.390605,0.360913,0.335859,0.193695,-0.080855,0.007007,0.081728,-0.176564,-0.117617,0.433134', '1301686', '2988294', '30137576', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751754', '前任攻略', '喜剧', '在一场婚礼上新郎（关喆  饰）新娘（毛俊杰 饰）设置了前男友桌和前女友桌，集合了新郎的前女友们和新娘的前男友们，埋伏了两场危机四伏的相遇。婚礼上，前男友桌和前女友桌或称兄道弟，或针锋相对，或真情流露，或举杯彷徨，男人和男人，女人和女人，男人和女人之间妙语连珠、嬉笑怒骂，折射出现代人当下的爱情百态。孟云（韩庚 饰）是一个生活在北京，工作上小有成就的普通青年，在这场“别开生面”的前女友婚礼上，意外结识了出现在新郎设置的“前女友桌”中的女孩夏露（姚星彤 饰）。就这样，孟云和前女友的老公的前女友开始了一段猝不及防的爱情。孟云与两个大学同学余飞（郑恺 饰）和罗茜（王丽坤 饰）合伙运营着一家小公司，三人从大学毕业初期的艰难创业岁月中起步走到现在，关于青春，他们珍藏着关于彼此的独家记忆。然而，罗茜对孟云的感情却从青春一路跨越伴随到当下，十四年，她默默守护着孟云，而孟云也在不自知的情况下爱着罗茜。在好哥们儿余飞和夏露闺蜜小文（班嘉佳 饰）的陪伴与见证下，孟云与夏露的爱情经受着历任极品前任的轮番考验，神经质般脆弱的前女友玲玲（麦迪娜 饰），喝酒上瘾的前女友萌萌（熊乃瑾 饰），花钱如流水的前女友尚丹（柳岩 饰），还有穷的只剩钱了的夏露前男友朴恩浩（李相烨 饰）都或多或少的影响到了他们的爱情，当聪明女孩夏露一一将这些状况化险为夷时，却没想到罗茜会成为无法逾越的鸿沟。罗茜与一个多金又成熟细心的男人赵明（张涵予 饰）订婚了，订婚宴上，喝多了的罗茜吐露真心，而孟云也发觉了被深埋藏在自己心底的对罗茜的爱情，夏露无法面对两人的感情，从订婚宴上逃走 。随后夏露与孟云在吵架时失足掉下楼梯，导致夏露流产 。孟云、夏', '韩庚', '田羽生', 6.1, 173263, 'tt3579688', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2171886373.jpg', 6.1, 18.7, 47.5, 21.1, 6.6, '0.476463,0.040336,-0.768807,0.519175,-0.193582,-0.275247,0.842150,0.135742,-0.274227,0.001633,0.297419,0.682314,-0.434313,0.392281,0.408401,-0.140806,-0.221208,-0.891544,-0.040107,-0.042518,-0.409210,-0.427419,-0.068424,0.003032,-0.231788,-0.205232,0.535144,-0.120339,-0.118415,0.494579,0.459100,0.097525,-0.284080,0.349815,-0.236627,0.066214,-0.028342,0.381458,-0.351041,0.073720,-0.003948,-0.298951,-0.085203,0.095689,-0.003094,0.271187,0.675510,-0.219893,-0.041033,0.163558,0.231517,-0.177940,-0.029468,0.210160,0.199188,-0.003414,0.326468,0.147567,-0.122590,-0.108895,0.298387,-0.088630,-0.308294,-0.032828,0.096956,0.190017,-0.626851,0.799373,-0.158879,-0.082563,0.248564,-0.403787,0.120218,0.380897,0.162043,0.482797,-0.297617,-0.099882,-0.457194,0.401753,0.717666,0.384518,-0.070244,0.436075,-0.093764,-0.360865,-0.354668,-0.035718,-0.677186,-0.021536,0.289818,-0.089473,-0.119187,0.230977,-0.714690,0.017387,0.02