INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751756', '老炮儿', '剧情', '老炮儿在北京话中，专指提笼遛鸟，无所事事的老混混儿。六爷（冯小刚 饰）就曾是“横行”老北京的老炮儿之一，如今过着悠闲自得的日子，却不想自己的儿子晓波（李易峰 饰）被卷入了与“小爷”小飞（吴亦凡 饰）的纠纷中。六爷试图出面摆平这起纠纷，并找来了昔日老友闷三儿（张涵予 饰 ）、话匣子（许晴 饰）、灯罩儿（刘桦 饰）帮忙，却发现这个时代已经有了一群新的“话事人”，自己这个顽主的江湖地位已经动摇，并且以往固守的生活方式已经渐渐被时代所抛弃，廉颇老矣尚能饭否？©豆瓣', '冯小刚', '管虎', 7.5, 732278, 'tt4701702', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2276674912.jpg', 2.1, 4.7, 29.6, 40.9, 22.7, '0.341734,0.347159,-0.463978,0.349440,-0.134971,-0.261621,0.502180,0.195035,-0.747212,-0.415897,-0.130240,0.510796,-0.050378,0.459954,-0.082905,-0.055495,-0.111615,-0.598623,-0.060554,-0.096902,-0.116450,-0.252699,-0.432118,0.082358,-0.350903,0.090281,0.242690,-0.052635,-0.353823,0.412001,0.409241,0.062152,0.065313,0.491272,-0.397237,0.270348,-0.042796,0.242641,-0.135963,-0.393035,-0.038444,-0.340753,-0.167393,-0.051986,0.047053,0.363370,0.329160,-0.172187,-0.025979,-0.084181,0.161626,-0.163552,-0.107006,0.161724,0.332238,-0.091330,0.375752,0.240150,-0.077823,0.075896,0.014733,-0.046207,-0.691447,0.176462,-0.020806,0.193023,-0.593038,0.363046,0.026873,-0.178337,-0.182643,-0.169369,0.377514,0.078992,0.207938,0.306057,-0.255356,-0.286234,-0.501925,0.625872,0.440701,0.063764,-0.278171,0.377953,0.183082,-0.186785,0.042254,-0.264010,-0.352012,-0.129736,0.177847,-0.133036,-0.362049,0.303501,-0.594934,0.021023,-0.145365,0.085767,0.135728,-0.220202,0.142333,-0.353416,-0.331185,-0.724801,-0.174727,0.295361,0.202992,0.166493,0.566301,-0.691211,0.082753,0.214393,0.171886,-0.562409,0.524048,0.294496,0.087016,-0.040501,-0.145963,-0.076008,-0.201504,0.419203,0.196339,0.336390,0.051422,-0.589821,-0.251223,0.407816', '1783461', '1890784', '1438708', '1418613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751757', '微爱之渐入佳境', '喜剧', '文艺三剑客沙果（陈赫 饰）、黄小瓜（张鲁一 饰）、马呆（曹璐 饰）经历着同甘共苦的北漂生活，土豪马大姐（王姬 饰）的出现让他们的职业生涯迎来了曙光。为了争取马大姐的投资，“微男”沙果开始了艰难的剧本创作。与此同时，美艳的“威女”车模陈西、小狗“莫愁”意外出现在了沙果的世界中。为了写好剧本，沙果倾其所有，黄小瓜、马呆怪招出尽；为了赢得爱情，沙果为陈西扑汤蹈火，而黄小瓜也邂逅了清纯的小青（姜瑞佳 饰），并且逐渐为爱走火入魔……在微时代的千变万化中，生活处处存在惊喜。本片为顾长卫导演的转型之作，蒋雯丽、文章、姜武及导演本人均有客串出镜。©豆瓣', '杨颖', '顾长卫', 4.5, 85810, 'tt4242844', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2213796763.jpg', 27.7, 34.9, 27.3, 6.6, 3.6, '-0.068693,0.136992,-0.497188,0.495611,0.064244,-0.060825,0.431599,0.241002,-0.098349,-0.047010,0.251927,0.536247,-0.290303,-0.066911,0.353490,-0.200348,0.012609,-0.557962,-0.111090,-0.074387,0.123770,0.039289,-0.308878,-0.142126,-0.217385,-0.313451,0.653566,0.025039,-0.046359,0.624340,0.487492,-0.000921,0.033843,0.111573,0.057073,0.238788,-0.040796,0.135219,-0.417903,0.177008,-0.060556,-0.336725,-0.150059,0.096250,-0.152678,0.134279,0.673504,-0.123196,-0.100135,-0.210398,0.417485,-0.125023,0.026505,-0.214394,-0.057955,0.046693,0.201038,-0.102046,-0.178855,0.264623,0.228587,-0.364652,-0.861998,0.047261,0.258701,0.248464,-0.476764,0.459980,-0.043897,-0.162517,0.331735,0.008552,0.165514,0.222276,0.718710,0.193356,-0.115689,0.325298,-0.265463,0.683450,0.241592,0.083663,0.016005,0.616747,-0.434514,-0.378277,0.086625,-0.026722,-0.407335,0.104918,0.172422,-0.093416,-0.014352,0.131402,-0.627371,0.019294,0.156907,0.005542,0.053762,-0.227486,-0.314340,-0.452873,-0.238843,-0.285554,0.043661,-0.042868,0.036217,-0.360581,0.742274,-0.713888,0.070995,0.190108,0.054774,-0.358887,0.691153,0.101124,-0.118509,-0.340750,-0.173182,0.264572,-0.381096,0.167622,0.065238,0.170472,-0.231970,-0.269221,-0.360252,0.373954', '27602116', '25880986', '26759820', '6101834');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751763', '罗曼蒂克消亡史', '剧情', '一出上世纪30年代旧上海的群像戏——叱咤风云的帮派大佬，不甘寂寞的交际花，说着地道上海话的日本妹夫，只收交通费的杀手，被冷落却忠诚的姨太太，外表光鲜的电影皇后，深宅大院里深不可测的管家，偶尔偷腥的电影皇帝，荷尔蒙满溢大脑的帮派小弟，一心想要破处的处男，善良的妓女，随波逐流的明星丈夫，投靠日本人的帮派二哥，日理万机却抽空恋爱的戴先生。战争之下，繁华落尽。帮派大佬逃亡香港，交际花不知所踪，日本妹夫死在上海，电影皇后被丈夫抛弃，处男遇上妓女，姨太太杀死二哥。战争惨烈，战争终于结束。', '葛优', '程耳', 7.7, 369445, 'tt4623812', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2404553168.jpg', 1.2, 4.2, 25.2, 47.6, 21.8, '0.187133,0.010338,-0.146848,0.177124,0.020543,-0.432788,0.688446,0.102774,-0.548865,0.054359,0.553897,0.411808,-0.367493,0.003509,0.284597,0.152960,-0.239421,-0.402423,-0.352756,0.091587,0.279825,-0.026098,-0.112164,-0.147842,0.040596,-0.135189,0.647707,0.198758,-0.169234,0.122664,0.255737,0.051756,-0.117115,0.109120,-0.062032,-0.060985,-0.036793,-0.016976,-0.410693,0.115705,-0.182854,-0.111650,-0.038708,-0.183822,-0.227540,0.287584,0.345653,0.032984,0.434262,-0.236492,0.733132,-0.128497,-0.281808,0.061886,0.584651,-0.082984,0.359719,0.085386,0.377782,-0.458227,-0.090841,0.001152,-0.186437,0.100484,0.364090,0.209801,-0.313281,0.597411,-0.024081,0.323378,-0.052747,-0.007969,0.370121,-0.090055,0.154545,0.380972,0.041653,0.411263,-0.527220,0.816601,0.704028,0.090901,-0.192079,-0.104507,-0.017072,-0.401332,0.117630,-0.839963,-0.630355,0.024579,0.049804,-0.739148,-0.199885,0.424167,-0.418996,0.137427,-0.014135,0.093427,0.095605,-0.183533,-0.281534,-0.478888,-0.257811,-0.312238,-0.009485,0.010371,0.455262,0.226879,0.729444,-0.697470,-0.055211,0.671130,0.427145,-0.486697,0.985961,0.127536,-0.125353,-0.292972,-0.229438,0.086675,-0.006693,0.059613,-0.058671,0.069177,-0.560877,-0.405550,0.033960,0.066224', '1422020', '1908036', '26322774', '35760330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751764', '三城记', '剧情', '在那个动荡的四、五十年代，爱情绝对得来不易——一件订情信物、一首情歌、一个约定都足以令恋人魂牵梦萦。身份复杂的警察房道龙（刘青云 饰）遇上具有传奇色彩的女子陈月荣（汤唯 饰），他们的爱情故事横越了三个城市：他们在安徽相爱，在上海分离，彼此仍坚守一个约定——在香港等候重聚。那夜，房道龙在港岛岸边等待接载月容的小船靠岸，却不料小船发生变故，月荣最后能否顺利抵港，与道龙开展新生活？影片取材自真实故事，讲述一段父辈的爱情故事。', '刘青云', '张婉婷', 6.2, 22255, 'tt3682770', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2263557391.jpg', 3.4, 18.4, 51.6, 20.4, 6.2, '-0.101551,0.005380,-0.545792,0.700091,0.374862,-0.042743,0.849615,0.010174,-0.353759,-0.238441,0.339453,0.696866,-0.171770,0.165570,0.288796,-0.153694,-0.203491,-0.710774,0.360271,-0.047608,-0.000588,-0.178439,-0.098942,-0.162161,0.057249,0.022384,0.537682,0.426766,-0.001335,0.536998,0.288132,-0.105198,-0.966743,0.205716,-0.500939,-0.022446,0.269270,0.374139,-0.658610,-0.135687,-0.370621,-0.350465,0.042946,0.077117,-0.064322,0.107292,0.832194,-0.357616,-0.335434,0.290955,0.290136,-0.084343,0.090340,-0.139232,0.224173,0.023744,0.003912,0.396680,-0.274689,0.027986,-0.097659,0.098239,-0.664051,0.099818,0.063165,0.325661,-0.345529,0.563576,0.082423,-0.084611,0.059030,-0.159388,0.154355,0.513265,0.351305,0.305028,-0.148176,0.129596,-0.462095,0.554617,0.754181,-0.114964,-0.266211,0.527675,0.141343,-0.507238,-0.281825,0.212123,-0.333771,-0.022711,0.315452,-0.022708,-0.028824,0.139747,-0.540485,-0.076716,-0.074395,-0.000210,0.181133,-0.512886,-0.080503,-0.673281,-0.042928,-0.377291,-0.206281,0.177579,0.130852,-0.032913,0.783938,-0.176012,0.166896,0.407741,0.060594,-0.590398,0.494594,0.336888,0.275037,-0.409949,0.132406,0.550956,-0.156859,-0.021476,0.072980,0.270817,-0.271770,0.498648,-0.563019,0.355124', '10466639', '3811356', '1308890', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751765', '喜羊羊与灰太狼之飞马奇遇记', '喜剧', '在经典的童话故事里，如梦如幻、色彩斑斓的天马之城，英俊的飞马王子（郑恺 配音）即将迎娶美丽的蓝马公主（白百合 配音），谁知婚礼现场却被抢婚的小矮马（刘红韵 配音）所破坏。飞马王子在追逐小矮马的时候遭遇意外，坠落到了青青草原。与此同时，草原上这个经典童话的结局也发生了改变。为了让痛哭流涕的大人们重新振作起来，也为了帮助飞马王子找回真爱，喜羊羊、美羊羊、懒洋洋、暖洋洋、沸羊羊以及小灰灰拿到了村长发明的飞行套装。在那个皓月当空的美丽夜晚，他们与王子一同飞上天空。在此之后，灰太狼和红太狼也紧随其后出发。悲哀的童话能否找回快乐的结局？新一年的旅程，这些好朋友们又将经历怎样的冒险？©豆瓣', '祖晴', '简耀宗', 6.2, 23373, 'tt4258716', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165380463.jpg', 13.4, 17.1, 34.4, 16.6, 18.5, '0.120721,0.307477,-0.555054,0.558005,0.118098,-0.146782,0.595654,-0.002945,-0.051309,-0.189225,0.410842,0.742718,-0.263191,0.315777,0.381806,0.166715,-0.378080,-0.449928,-0.065772,-0.029131,-0.203373,-0.086442,-0.267464,-0.060879,0.153802,-0.241686,0.729246,0.022944,-0.081068,0.789285,0.477660,-0.084004,-0.224092,0.269446,-0.299469,0.122371,-0.132487,0.507503,-0.121225,0.166463,-0.082585,-0.163876,0.039918,0.008569,-0.016139,-0.052235,0.941088,-0.677817,-0.121703,-0.261365,0.461514,-0.396623,0.280299,0.204593,0.108083,0.019318,-0.068343,-0.070472,-0.084453,-0.267622,-0.054115,-0.198767,-0.637357,0.183108,0.076292,0.073832,-0.520633,0.379318,0.108776,-0.099666,0.649904,-0.299718,0.304726,0.325401,0.458700,0.379944,-0.100830,0.336088,-0.415548,0.422773,0.811752,0.172876,-0.270498,0.306402,-0.083425,-0.414734,0.114049,-0.125536,-0.393043,0.154883,0.550604,0.018696,-0.070945,0.208225,-0.738980,0.124446,-0.239256,-0.320875,-0.054114,-0.482493,-0.202711,-0.332944,0.105179,-0.250190,-0.007580,-0.015194,0.241350,-0.266588,0.816206,-0.654037,0.262550,0.389756,0.189171,-0.253874,0.476413,0.003780,-0.016299,-0.104129,-0.018972,0.171794,0.011424,0.433211,-0.096346,0.297845,-0.186733,-0.031801,-0.731363,0.629107', '3811356', '5364978', '5403927', '2032339');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751811', '剧院魅影：25周年纪念演出', '剧情', '这是一场为庆祝音乐剧《剧院魅影》成功上演25周年的特别演出，地点在英国伦敦的皇家阿尔伯特音乐厅（Royal Albert Hall）。活动于2011年10月1日晚、次日下午和晚上，一共进行了3场声势浩大的演出，为到场的音乐剧迷们奉献了一次震撼人心的视听盛宴。演出同时，其 实况录像也在英美的大银幕上映。阵容方面，伊朗裔加拿大音乐剧男演员Ramin Karimloo领衔主演男主角幽灵（The Phantom），美国音乐剧女演员Sierra Boggess饰演女主角克里斯蒂（Christine Daaé）。两人在韦伯2010年的一部作为《剧院魅影》续集的新剧《魅影：爱无止尽》（Love Never Dies）中，曾联袂合作，是《Love Never Dies》伦敦首演版的男女主角。而在此之前，Ramin Karimloo曾在07至09年《剧院魅影》伦敦版剧组扮演幽灵；而Sierra Boggess是《魅影》拉斯维加斯首演版的Christine，因此二人虽然早已对各自的角色驾轻就熟，而且有过合作经历，但这3场音乐会之前还不曾同台演绎过这部韦伯的经典名剧。演出最后，来自世界各地、不同时代的《魅影》原创艺术家们一同上台，庆祝他们为之奉献的舞台经典。音乐剧《剧院魅影》（The Phantom of The Opera）由安德鲁•劳埃德•韦伯（Andrew Lloyd Webber）作曲创作，改编自法国小说家Gaston Leroux的同名小说,被认为是音乐剧的一部撼世之作。该剧自1986年在伦敦西区首演以来，长盛不衰，成为伦敦西区第二长寿的音乐剧（在伦敦目前仅次于《悲惨世界》）。在美国纽约百', '莱明·卡莱姆罗', '尼克·莫里斯', 9.7, 24215, 'tt2077886', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2006533765.jpg', 0.2, 0.1, 1.2, 10.1, 88.4, '-0.013242,-0.011319,-0.742352,0.521767,0.522063,-0.036410,0.481007,-0.068818,-0.346855,-0.114783,0.388175,0.880619,-0.591042,0.068897,0.586658,-0.391727,-0.384594,-0.765039,-0.296920,-0.233513,0.185777,-0.151717,-0.224919,0.019551,-0.165988,-0.343867,0.742445,0.162986,-0.065216,0.664240,0.580123,0.119774,-0.166025,-0.045545,-0.009541,-0.242506,0.356696,0.188837,-0.595653,0.582059,-0.117188,-0.376052,-0.480840,-0.013649,-0.008244,0.112198,0.740045,-0.143224,0.160769,-0.150994,0.662156,-0.174396,-0.236233,-0.263235,0.389059,0.164854,0.497222,0.336092,0.122723,0.103658,-0.416371,-0.583323,-0.807743,0.123342,0.279713,0.198381,-0.358771,0.593174,-0.169909,0.105498,0.042403,-0.105292,0.195675,0.061024,0.594640,0.304636,0.027475,0.219465,-0.306967,0.716292,0.778845,0.178978,-0.163166,0.373090,-0.032668,-0.601166,-0.199365,-0.269107,-0.360168,0.351704,0.092583,-0.267001,0.153431,0.107127,-0.614351,-0