INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24751825', '我为相亲狂', '喜剧', '大龄女强人白晶晶（韩雪 饰）美艳逼人，在一次相亲会上，富家子弟赵帅（李佳航 饰）被其风姿倾倒，主动搭讪遭拒，心有不甘的他使出浑身解数发动爱情攻势，结果惨败。戏痴啾啾（谢依霖 饰）自编自演五个性格迥异的女孩，宅男江小鱼（冯铭潮 饰）在母亲遥控指挥下与之“地铁闪约”，上演了一出哭笑不得的相亲喜剧。频频相亲未果的童军（杜海涛 饰）目睹此景，顿时被古灵精怪的啾啾所吸引，之前的童军由于在相亲过程中过于精明遭女方吐槽，啾啾的突然出现令他心中为之一震。其实，小鱼有个暗恋网友叫米雪（范玮琳 饰），由于他自身性格的原因，与其一直保持若即若离的关系，迟迟未能踏出关键一步......©豆瓣', '韩雪', '韩晶', 4, 5657, 'tt2963484', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2155198242.jpg', 40.4, 29.6, 23.5, 3.8, 2.7, '0.083843,-0.061690,-0.861292,0.554501,0.219910,0.036870,0.540348,0.232470,-0.245876,-0.149654,0.283172,0.327883,-0.714372,0.175940,0.426589,-0.252161,0.253823,-0.384899,-0.064960,0.467896,0.149502,-0.179318,-0.051531,0.065749,-0.321172,-0.181848,0.487159,-0.215005,-0.216551,0.619655,0.601836,0.223560,-0.083244,0.420807,0.158827,0.070850,-0.001427,-0.136260,0.084077,0.080195,-0.084465,-0.684021,-0.018857,0.054285,-0.171122,0.515670,0.685242,-0.364155,-0.118087,-0.144512,0.417393,-0.095058,-0.291664,0.271142,0.070503,-0.227854,0.299073,-0.023000,0.012835,-0.033242,0.323071,0.094938,-0.166709,0.346058,0.288687,0.031936,-0.135591,0.153322,-0.207631,-0.045756,0.064747,-0.261988,-0.101332,-0.080700,0.281276,0.171498,-0.216897,0.338886,-0.029593,0.207159,0.662945,0.287441,-0.158166,0.535263,-0.221662,-0.158778,-0.020229,-0.216930,-0.349822,0.018685,0.391692,0.144187,0.049199,0.145115,-0.408943,-0.043341,-0.028497,0.112637,-0.186071,-0.257070,-0.343139,-0.598287,-0.088372,-0.490400,-0.401813,0.049022,0.000814,-0.104686,0.417638,-0.787127,-0.302147,0.176321,-0.033015,-0.465004,0.347948,0.158395,-0.161707,-0.085900,-0.201700,0.318141,0.253471,-0.080094,-0.062637,0.220364,-0.183946,-0.074175,-0.267039,0.029578', '25870679', '25856453', '30166972', '3401409');
