INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24753477', '蜘蛛侠：英雄归来', '动作', '彼得帕克（汤姆·赫兰德 Tom Holland 饰）在内战后受到了钢铁侠托尼斯塔克（小罗伯特·唐尼 Robert Downey Jr. 饰）的赏识，表面上，彼得进入托尼的公司成为了一名实习生，实际上，他和复仇者联盟的成员们一起接受了各种各样的训练。托尼虽然欣赏彼得的勇敢和正直，却并不认为他目前已经拥有加入复联的实力，他派出了特工哈皮（乔恩·费儒 Jon Favreau 饰）暗中观察，这让十分想证明自己的彼得感到万分焦躁。在对付两个银行劫匪的过程中，彼得发现劫匪们使用的是一种前所未见的新型武器，他孤身一人深入敌后顺藤摸瓜找到了幕后主使秃鹰（迈克尔·基顿 Michael Keaton 饰），让他彼得没有想到的是，秃鹰竟然是他爱慕的女生利兹（劳拉·海瑞尔 Laura Harrier 饰）的父亲。©豆瓣', '汤姆·赫兰德', '乔·沃茨', 7.3, 412587, 'tt2250912', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2497756471.jpg', 0.8, 4.1, 37.1, 44.7, 13.3, '0.458997,-0.004640,-0.689125,0.546932,-0.199405,-0.224761,0.691551,-0.045058,-0.641312,-0.363784,0.481426,0.725446,-0.111163,0.134389,-0.061286,-0.044038,-0.535159,-0.496406,-0.100903,-0.107946,-0.126845,-0.544996,-0.579224,-0.303234,-0.182992,-0.342395,0.647272,-0.062386,-0.167940,0.472656,0.254447,0.492349,0.340626,0.305760,-0.044320,-0.028850,0.534596,-0.338309,-0.108697,0.092286,-0.016491,-0.003804,-0.160728,0.434379,0.073835,0.422758,0.436004,-0.361007,0.053748,-0.143188,0.153544,-0.388911,0.088520,0.049139,0.233590,-0.021987,-0.084010,0.119862,-0.140445,0.079967,0.096221,0.187001,-1.046568,0.061362,0.101792,0.392927,-0.594814,0.193520,-0.421165,0.071568,0.191632,-0.233827,-0.039403,0.210318,0.125003,0.163912,0.109063,0.093305,-0.653618,-0.154695,0.638823,-0.040229,-0.270505,0.008955,-0.296313,-0.444929,-0.050907,-0.259102,-0.301923,-0.116514,0.342558,-0.111433,0.080335,0.102061,-0.575345,-0.017335,-0.333909,-0.109424,-0.236691,-0.340060,0.080735,-0.977806,-0.095857,-0.477767,-0.495531,-0.243637,-0.047766,-0.395130,0.718689,-0.924675,-0.059178,0.472574,0.239066,-0.354882,0.594742,0.039995,-0.035181,-0.240890,-0.232856,0.124119,0.287864,0.011887,0.259484,0.562449,0.134680,-0.431929,-0.129191,0.391835', '1793491', '6731985', '2369613', 