INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24753685', '今天是再见的日子', '剧情', '在一个普通乡间小镇，马上迎来而立之年的富士冈耕太（大野智 饰）和父亲健二郎（三浦友和 饰）、母亲康子（岸本加世子 饰）、姐姐小春（ミムラ 饰）以及女友田边绘津子（木村文乃 饰）过着平凡的生活。大学肄业，工作始终没有着落，对于未来耕太似乎倍感迷茫，却从未想过生命的终点会这般迅速地出现在自己的面前。耕太被诊断患上死亡率为20%的恶性淋巴瘤，他被迫住进医院治疗。在此期间，病友信夫（山田凉介 饰）和心理疏导师大久保由里子（深田恭子 饰）给了他莫大的信心。血型配对成功，命运之神仿佛重新对这个青年露出微笑……本片根据幸和也的原作改编。©豆瓣', '大野智', '菅原伸太郎', 8.4, 6666, 'tt3101356', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2112961784.jpg', 0.4, 1.3, 16.6, 40.8, 40.9, '-0.056427,0.056620,-0.454560,0.510166,-0.073524,-0.365644,0.615416,0.279816,-0.424614,-0.507539,0.244579,0.789848,-0.156379,0.293215,0.130234,-0.077516,-0.111480,-0.542131,-0.147535,0.060680,-0.298837,-0.401216,-0.054654,0.008185,-0.257770,-0.226599,0.716733,-0.116252,0.180327,0.769844,0.215749,0.668795,-0.024930,0.308287,-0.050025,0.245393,0.060716,0.222714,-0.302598,0.278171,0.043957,-0.104024,-0.101262,0.176554,-0.048737,0.384952,0.867903,-0.047188,-0.392107,-0.235112,0.324243,0.028567,-0.114179,0.201937,0.398489,-0.041418,0.016690,0.270391,-0.176531,0.072411,0.216672,-0.063960,-0.554863,-0.307958,0.202498,0.369673,-0.416644,0.390774,-0.188055,-0.316039,0.191727,-0.109003,0.017830,0.201169,0.278714,0.279349,-0.545371,0.295179,-0.201376,0.267626,0.314648,0.001308,-0.130360,0.448218,-0.382470,-0.403777,-0.041582,-0.158604,-0.574631,0.198684,-0.093727,0.148845,-0.335229,0.029783,-0.324785,-0.052734,-0.243045,-0.020741,0.212621,-0.159100,0.110184,-0.579105,0.195145,-0.621071,-0.540923,0.085820,0.105635,-0.273523,0.582656,-0.869851,0.094638,0.172026,0.252949,-0.288598,0.256372,0.225872,-0.054949,-0.344799,-0.100138,0.163125,-0.127704,0.402560,0.073680,0.337135,-0.028724,-0.088556,-0.505470,0.401070', '3811356', '1292219', '3445516', '1507134');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24753687', '少女哪吒', '剧情', '李小路（李浩菲 饰）是班里新来的转学生，其貌不扬的她个性也内向温吞，却意外的和优等生王晓冰（李嘉琪 饰）成为了无话不谈的好友。李小路喜爱文学，两人徜徉在文学的海洋里，尽情吸收着养分。之后，李小路再度转学，来到了英才中学，遇见了英俊帅气了男生徐杰（辛鹏 饰），两人渐渐走到了一起。而被寄予厚望的王晓冰却在考试中失利，使一直带她十分严苛的母亲（陈瑾  饰）大失所望，与此同时，王晓冰还遇见了李教官（李欢 饰）。李小路和王晓冰两个女孩，在此踏上了不同的道路，她们之间的友情，亦在考验和磨难之中产生了裂痕。高考结束后，王晓冰忽然找到了李小路，两个女孩尽释前嫌，度过了美好的一天，然而，让李小路没有想到的是，这次见面，竟然成为了诀别。©豆瓣', '李嘉琪', '李霄峰', 6.5, 17989, 'tt4108872', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2247672271.jpg', 4.1, 15.3, 41.2, 29.5, 9.9, '0.256471,0.059955,-0.800736,0.864299,-0.103707,-0.706176,1.079869,-0.165214,-0.528493,-0.141404,-0.046324,0.221329,-0.552983,0.675299,0.299650,-0.582988,-0.260810,-0.660430,-0.156291,-0.228607,-0.673402,-0.314438,-0.162494,0.121040,-0.437088,-0.098353,0.618677,0.303711,-0.253653,0.716278,0.199039,-0.050883,-0.052913,0.713091,-0.363865,0.233256,0.150767,0.514741,-0.002447,-0.153374,0.285803,-0.658914,-0.293871,-0.027334,0.144899,0.358559,0.963846,-0.089529,-0.070351,0.083598,0.290037,-0.278520,-0.153241,0.038424,0.515036,0.021841,0.133583,-0.231660,-0.106242,-0.105688,-0.003454,-0.264556,-0.094282,0.053686,0.122637,0.173810,-0.552335,0.270200,0.087609,-0.352270,0.259145,-0.579373,0.162938,0.067473,0.469544,0.457449,0.012970,0.210722,-0.373777,0.175665,0.864840,0.220639,-0.502722,0.080174,-0.379358,-0.619084,0.210513,0.161620,-0.191565,0.047318,0.626894,-0.142436,0.365667,0.165840,-0.645334,-0.065782,0.188308,0.022177,0.014984,-0.421179,-0.150388,-0.549432,0.035671,-0.672206,-0.223608,0.617258,-0.243475,-0.369969,0.702387,-0.856236,0.188039,-0.045517,0.230481,-0.492376,0.977663,-0.130583,0.287004,-0.274478,0.335552,0.155372,-0.128622,0.349879,0.364400,0.880990,-0.333244,0.057742,-0.492541,0.565069', '21348112', '26687241', '3055049', '1308480');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24753712', '国王的全息图', '剧情', '电影《国王的全息图》（英文名：A Hologram for the King），由同名小说《国王的全息图》改编而成，讲述了一名失败的美国商人艾伦·克莱来到沙特阿拉伯寻找最后一丝发财希望，这也是他拯救濒临解散的家庭的最后一次机会。电影中的男主角艾伦（汤姆·汉克斯饰）陷入债务危机，而他的女儿还要支付大学学费，所以他不得不远赴沙特阿拉伯去完成一桩电脑生意，但是他身在异国他乡，却只能日复一日地等待交易的结束，原著寓言式故事折射出美国的国际处境及其中产阶级的衰退。', '汤姆·汉克斯', '汤姆·提克威', 6, 6746, 'tt2980210', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2325523252.jpg', 2.8, 18.8, 57, 17.4, 4.1, '-0.052650,0.183575,-0.365095,0.731441,0.177881,-0.380061,0.430164,0.289227,-0.261957,-0.315568,0.342102,0.888412,0.025673,0.141555,0.228576,0.078800,-0.438737,-0.552085,0.068993,-0.096191,0.125904,-0.432471,-0.208870,-0.375651,-0.262835,-0.110888,0.975568,0.339487,-0.170171,0.305964,0.113538,0.198537,0.093453,0.208346,0.001812,0.001426,0.044334,0.021382,-0.477873,0.486129,0.302949,0.011761,-0.202767,0.105344,0.154283,0.232052,0.669355,0.081759,0.099567,0.201508,0.690476,-0.396125,-0.278557,-0.049140,0.096057,0.143138,0.205782,0.199919,-0.094461,-0.114862,-0.022842,-0.141234,-0.821321,-0.053715,-0.045607,0.297382,-0.486269,0.379437,-0.202932,0.299580,-0.004636,-0.444592,-0.002655,0.404855,0.492236,0.508884,-0.240526,0.098259,-0.532329,0.513762,0.582427,-0.100648,-0.303045,0.400669,-0.242027,-0.523641,-0.147275,-0.301832,-0.353617,0.097097,0.323961,-0.181915,-0.233369,0.460827,-0.720920,-0.110407,-0.401599,-0.436180,0.240241,-0.339138,0.074062,-0.916748,-0.135268,-0.086231,-0.121803,0.021356,0.185513,-0.226669,0.691729,-0.503977,0.181689,0.788909,0.136542,-0.386886,0.725223,0.309685,0.145564,-0.267237,0.099320,0.365648,-0.174324,0.376983,-0.141702,-0.237023,0.183628,-0.313765,-0.360465,0.479683', '22265121', '1322847', '25880986', '30397916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24753810', '战狼', '动作', '在南疆围捕贩毒分子的行动中，特种部队狙击手冷锋（吴京 饰）公然违抗上级的命令，开枪射杀伤害了战友的暴徒武吉（周晓鸥 饰）。这一行动令冷锋遭到军方禁闭甚至强制退伍的处罚，不过各特种部队精英组成超级特种部队战狼中队的中队长龙小云（余男 饰），却十分欣赏这个敢作敢为且业务过硬的血性男儿，于是将其召入自己的麾下。在新近的一次演习中，冷锋凭借冷静的判断力从老首长处拔得一城，并且成功击退了突然出现的狼群。谁知在毫无准备的情况下，战狼遭到了一伙荷枪实弹分子的袭击。原来武吉的哥哥敏登（倪大红 饰）是一个冷酷无情的国际通缉犯，他手下豢养了一大批身怀绝技的雇佣兵。为了给弟弟报仇，敏登派出雇佣兵千里迢迢奔着冷锋而来……©豆瓣', '吴京', '吴京', 7, 292552, 'tt3540136', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2225660666.jpg', 4.4, 8, 37, 34.7, 15.8, '0.158056,-0.184753,-0.588823,0.803715,-0.285310,-0.112443,0.348282,-0.090197,-0.528177,-0.164304,0.646206,0.552551,0.248716,-0.130553,0.315185,-0.306509,-0.028767,-0.587616,-0.477011,-0.080160,-0.372686,-0.309849,-0.263561,-0.288200,0.192291,-0.174801,0.656153,-0.082154,-0.280051,0.505493,0.334684,0.344511,0.064664,0.428982,-0.169699,-0.095228,0.303570,-0.444698,-0.034743,0.275716,-0.220148,-0.293404,-0.085730,0.114933,-0.103169,0.520163,0.628940,-0.438597,-0.000674,-0.327977,0.092215,-0.497138,0.157290,0.001676,0.635159,0.182884,-0.037159,0.042898,0.037606,0.243848,-0.095976,0.112679,-0.720403,0.015835,0.120459,-0.049020,-0.759001,0.305002,-0.248355,0.327280,0.191982,-0.025553,-0.013356,0.393117,0.026235,0.036912,-0.123450,0.086153,-0.491430,0.069407,0.618901,-0.232092,-0.198819,-0.295725,-0.024071,-0.504648,0.123254,-0.342729,-0.128937,-0.192616,0.463788,-0.244754,-0.056658,-0.006957,-0.501828,-0.089358,-0.214613,0.007679,-0.427086,-0.246056,-0.197808,-0.666916,0.154782,-0.226343,-0.215731,0.305436,0.136832,0.230480,0.716818,-0.819119,-0.231708,0.445379,0.190531,-0.590634,0.183474,0.104449,-0.037221,0.054934,-0.308317,-0.081204,0.553525,0.529703,0.281718,0.426812,-0.307691,-0.521191,-0.007060,-0.084812', '1292829', '4127270', '20388224', '1420088');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24753811', '熊出没之夺宝熊兵', '喜剧', '在一个电闪雷鸣、大雨瓢泼的夜晚，相貌凶恶的大马猴和二狗两个坏家伙驾驶汽车飞驰在森林中间的小路上，后座上放着一只他们极为看重神秘箱子。谁知半路突发意外，他们的车子被撞毁，箱子也飞到了森林中央。与此同时，光头强从李老板那里得到一套超先进的伐木工具，他冒着大雨赶赴林间作业，结果遭遇熊大和熊二的阻挠。两只熊抢走了工具箱，光头强急忙追上前去。混乱之中，工具箱和大马猴他们的搞混，被光头强阴差阳错带回家中。第二天一早，光头强突然发现家里多了个小女孩，原来这正是大马猴和二狗两人绑架而来的孩子。全不知情的光头强带着女孩外出，路上遭遇警察的追捕。混乱就此开始，小女孩的命运该如何呢？©豆瓣', '张秉君', '丁亮', 7.6, 31801, 'tt3564806', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2165005086.jpg', 2, 4.2, 28.9, 39.2, 25.7, '0.400948,0.193160,-0.821588,0.206070,-0.068668,0.054932,0.626300,0.138762,-0.258089,-0.273203,0.489261,0.538367,0.000075,0.177343,0.051867,-0.058653,-0.438762,-0.300753,-0.292869,0.326135,-0.745156,-0.165807,-0.372905,-0.169116,0.221583,-0.000512,0.102361,0.114267,-0.080975,0.710316,0.358416,0.041375,-0.621389,0.413787,-0.452496,0.183400,0.074916,0.089745,0.352786,0.070131,-0.252463,-0.266418,-0.127686,-0.150490,-0.082514,0.268623,0.723742,-0.065515,-0.270743,-0.236143,0.212298,-0.199986,-0.157249,-0.194451,0.639976,0.049247,0.110372,-0.366149,0.091696,-0.059495,0.071077,-0.089533,-0.211712,0.380078,-0.206323,-0.119766,-0.772383,0.191079,0.022438,-0.047869,0.313375,-0.324004,0.164767,0.125616,-0.045597,0.441854,0.154712,0.081692,-0.732746,-0.198430,0.501741,-0.182617,0.098988,0.149951,0.020905,-0.109336,0.087768,-0.177558,-0.360176,-0.129760,0.855534,-0.155862,-0.538620,-0.199100,-0.371093,0.400591,-0.242432,0.119206,-0.288011,0.104179,-0.564915,-0.262714,0.365109,-0.271934,-0.171946,0.349562,-0.301618,0.263072,0.577426,-0.266225,0.336331,0.482005,0.170706,-0.136850,0.424078,-0.359535,0.076677,-0.102870,-0.147356,-0.304609,0.232504,0.316340,0.294386,0.332728,-0.380077,-0.321565,-0.337274,0.305434', '26882457', '3217669', '25837175', '1296636');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24756472', '我的兄弟情人', '剧情', '高尔夫（提拉帕·洛翰那 Teerapat Lohanan 饰）从小生活在一个破碎的家庭中，从未真正享受过亲情的他自然养成了桀骜不驯而又暴躁多变的性格，他整日生活在深深的孤独之中，觉得世间无人能够懂得他的喜怒哀乐。某日，高尔夫莫名其妙的多了一个比他小四个月的义弟班克（邦沙敦·西宾达 Pongsatorn Sripinta 饰），只因为他的父亲新交了一个女朋友。从一开始，高尔夫就将班克视为自己的敌人和对手，对他很不友好，然而，男孩子之间的情谊却是如此的玄妙和多变，高尔夫和班克同住一个屋檐下，一间卧室中，分享着彼此的快乐和悲伤，随着时间的推移，两人竟然成为了彼此生命中不可缺少的存在。©豆瓣', '提拉帕·洛翰那', '尼察庞·恰阿努', 6.9, 6312, 'tt3522738', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2160296350.jpg', 3.1, 11.4, 40.1, 28.3, 17.2, '0.452870,0.082606,-0.880033,1.007112,-0.301032,-0.153123,1.170464,0.069736,-0.483828,-0.234754,-0.117950,1.055770,-0.179019,0.444655,0.108600,-0.005280,-0.027947,-0.828620,-0.255495,-0.307900,-0.279163,-0.373223,-0.413047,-0.105922,-0.311741,-0.065142,0.582708,0.026796,-0.120994,0.517025,0.255190,0.134603,-0.020571,0.775306,-0.465416,-0.039064,-0.074162,0.130917,-0.133906,-0.167689,0.118043,-0.106557,-0.040838,0.287469,-0.187901,0.237989,0.775053,-0.558709,-0.186036,-0.216072,0.234060,0.048235,-0.203873,0.129919,0.181640,-0.104885,0.328057,0.158796,-0.266587,0.089757,0.046081,-0.142688,-0.996519,0.049472,-0.005810,0.082104,-0.497441,0.590961,0.060965,-0.467604,0.044745,-0.328417,0.087552,0.315144,0.251570,0.496082,-0.463618,-0.138590,-0.427712,0.145643,0.851503,-0.011426,-0.476032,0.682819,-0.460615,-0.378199,-0.168627,-0.308571,-0.789629,-0.435269,0.241327,0.160370,-0.175168,0.340965,-0.698791,0.445932,-0.012985,-0.046783,-0.023314,-0.783697,-0.143491,-0.289568,-0.365086,-0.952239,-0.547922,0.183044,0.022423,-0.440954,0.943934,-1.111376,0.083832,0.445533,0.389930,-0.306595,0.871463,0.324704,0.182198,-0.053939,-0.007634,0.398530,0.026067,0.093635,0.256897,0.695543,-0.170707,0.357446,-0.364058,0.919191', '1291877', '1292062', '4275444', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24756658', '神之一手', '动作', '时运不济的专业围棋选手宋泰锡（郑雨盛 饰）受沉湎于赌博的哥哥所托，帮助其在围棋赌局上出老千，结果被对方看破，哥哥遭受毒打后惨死，泰锡也被投入监牢。在狱中他利用棋艺从牢头处获得许多利益，更分别跟随神秘高手和黑帮老大锻炼出高超棋艺和强壮体魄。重获自由后，泰锡乔装打扮化名大石，并网罗了身处底层的宫秀、主（安圣基 饰）、许木匠等人组成各逞所能的团伙，发誓要向残害了他们兄弟的吴社长（李凡秀 饰）及其围棋诈骗团伙展开复仇。而狡诈凶残的吴社长绝不会轻易束手就擒，先失一着的他迅速展开反扑。决定命运的神之一手，一旦得到便有机会从地狱回到天堂，而这一切必将以血为代价……©豆瓣', '郑雨盛', '赵范九', 6.9, 16029, 'tt3419894', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2182978810.jpg', 1, 7, 48.8, 32.7, 10.5, '-0.216189,-0.026461,-0.426368,0.512027,-0.247383,-0.346298,0.482822,0.300451,-0.396402,-0.044583,0.430459,0.646657,0.036885,-0.067473,0.281899,-0.478681,-0.099686,-0.737551,-0.133889,-0.089913,-0.277514,-0.310634,-0.115666,-0.247935,-0.099674,-0.153767,0.458590,0.252852,-0.352330,0.238114,0.340967,0.229870,-0.245661,0.195109,-0.060521,-0.147214,-0.175293,0.062085,-0.457248,0.234502,-0.058371,-0.402219,-0.044610,0.098583,-0.082352,0.001548,0.741415,-0.436127,-0.064108,-0.382181,0.244628,-0.312176,-0.076057,0.243256,0.132633,0.084786,0.112540,0.156798,-0.199507,0.093522,0.176151,-0.338671,-0.975140,-0.246069,0.209124,-0.125284,-0.493749,0.090170,-0.032155,0.053963,-0.218009,-0.225175,-0.068650,0.321079,0.385677,0.018358,-0.078778,-0.088779,-0.282393,0.019104,0.595803,-0.188124,0.030194,-0.027474,0.076789,-0.595945,0.072314,-0.565839,-0.074994,-0.043588,0.595196,-0.015880,0.047261,0.131750,-0.475064,-0.137559,-0.133022,0.069949,-0.106771,-0.354903,0.232861,-0.487729,-0.153660,-0.079215,-0.022702,0.245952,0.166579,-0.328657,0.801613,-0.829184,0.229277,0.454697,0.236083,-0.588622,0.422801,-0.210493,0.116341,-0.158201,-0.036884,0.236658,0.424184,0.544190,0.197217,0.172857,-0.058602,-0.173230,-0.035807,0.207443', '26678784', '1793491', '3718665', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24758396', '江湖论剑实录', '喜剧', '北宋的普通青年司徒耀祖（郑恺 饰）在名门正派习武学成，进入社会后才发现现实的残酷，他放弃了毫无前途的捕快工作，奔赴首都汴梁寻找人生价值。在汴梁，司徒耀祖结识了无法走红的歌姬王二丫（潘之琳 饰），并与喜好丹青的官二代张鼎鼎（孙坚 饰）不打不相识。因张鼎鼎的父亲不愿儿子成为 危险系数过高的驸马，司徒耀祖偶然成为张父的义子，顶替张鼎鼎参与驸马的争夺，并与张鼎鼎的好友王翠（余思潞 饰）一较高下，胜出的耀祖有了做驸马的资格，但公主却已被番邦掳走，为了成为驸马，司徒耀祖、张鼎鼎、王二丫和王翠四人踏上了惊心且搞笑的搭救公主的旅途，同时他们也经历了各自的成长……©豆瓣', '郑恺', '蒋卓原', 6.1, 15242, 'tt7123244', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2192459009.jpg', 9.6, 20, 37.7, 21.4, 11.2, '0.183035,0.019034,-0.243837,0.762321,-0.157246,-0.467358,0.728306,0.299253,-0.746792,-0.246957,0.406042,0.726200,0.182888,0.435279,0.454189,0.084365,0.053183,-0.507317,0.257942,-0.175051,0.078881,-0.554368,-0.161108,-0.024164,-0.318998,-0.119996,0.894941,-0.058744,-0.272811,0.522768,0.366739,-0.350913,-0.105085,0.552076,-0.006358,0.157310,-0.063691,0.265714,-0.452511,-0.002818,-0.047272,-0.362057,-0.240684,-0.146716,0.118282,0.206401,0.343777,-0.356435,0.149886,-0.204377,0.447642,-0.259823,0.039460,0.351666,0.084731,0.064047,0.228671,0.105803,-0.041915,-0.083203,-0.013155,-0.065110,-0.548084,0.222387,0.560898,-0.110304,-0.573670,0.621617,-0.139105,-0.341015,0.051682,-0.497762,0.055618,0.449217,0.313716,0.082621,-0.284677,0.206645,-0.560002,0.386208,0.300000,0.060669,-0.226261,-0.070408,0.497313,-0.736633,0.063962,-0.562794,-0.407906,0.028695,0.424306,0.108759,-0.030368,0.260294,-0.417995,0.026611,-0.328394,0.090788,0.347794,-0.088406,0.001198,-0.391486,-0.243417,-0.421045,-0.154582,-0.077419,0.413014,-0.558978,0.693048,-0.821699,-0.258684,0.122723,-0.034201,-0.801071,0.431192,0.190617,0.133718,-0.144431,-0.246860,-0.009974,0.095459,0.609962,0.031786,0.367788,-0.147532,-0.189601,-0.066733,0.220607', '35030151', '6519585', '1301022', '3319776');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24773958', '复仇者联盟3：无限战争', '动作', '最先与灭霸军团遭遇的雷神索尔一行遭遇惨烈打击，洛基遇害，空间宝石落入灭霸之手。未几，灭霸的先锋部队杀至地球，一番缠斗后掳走奇异博士。为阻止时间宝石落入敌手，斯塔克和蜘蛛侠闯入了敌人的飞船。与此同时，拥有心灵宝石的幻视也遭到外星侵略者的袭击，为此美国队长、黑寡妇等人将其带到瓦坎达王国，向黑豹求助。幸免于难的索尔与星爵一行相逢，随后他们兵分两路。索尔与火箭、格鲁特踏上再铸雷神之锤的旅程，星爵则与卡魔拉等人试图阻止灭霸的恶行。而知晓灵魂宝石下落的卡魔拉，同样是其义父灭霸追踪的对象。攸关整个宇宙命运的史诗战役全面展开，超级英雄们为了平凡而自由的生命奋不顾身……©豆瓣', '小罗伯特·唐尼', '安东尼·罗素', 8.1, 748742, 'tt4154756', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2517753454.jpg', 0.9, 2.4, 19.8, 43.5, 33.4, '-0.048415,0.252536,-0.562037,0.559314,0.127915,-0.021487,0.774640,0.009175,-0.132197,-0.107483,0.355082,0.670795,0.064718,-0.319434,0.372573,-0.132310,-0.282076,-0.645728,-0.070901,0.130677,-0.460688,-0.191672,-0.211264,-0.166596,0.105599,-0.577653,0.719431,0.017545,-0.168730,0.511675,0.076597,0.758922,-0.553536,0.237990,-0.055543,-0.059532,-0.027748,-0.147987,-0.577651,0.461167,-0.390315,0.178379,-0.009160,0.387520,-0.386575,-0.094889,0.845903,-0.438068,0.278529,-0.475363,0.017656,-0.521398,0.082914,-0.121765,0.358668,0.001251,-0.200033,-0.069477,0.124029,0.131748,0.202696,0.114291,-0.958802,-0.094921,-0.053167,-0.129590,-0.364230,0.081874,-0.086145,0.289810,0.140376,-0.145913,0.261731,0.633336,0.333364,0.018076,-0.181211,-0.040514,-0.300031,-0.131409,0.601764,-0.320531,-0.155356,-0.047943,0.118246,-0.454486,-0.090437,-0.240590,-0.184936,0.034965,0.579981,0.420952,0.073398,0.565657,-0.924684,-0.210744,-0.602861,-0.173435,0.125494,-0.505922,-0.082003,-0.746616,-0.048788,-0.171720,-0.161504,0.220135,0.079614,0.218946,0.453536,-0.406419,0.237495,0.404308,0.260475,-0.440401,0.515677,-0.106070,0.066625,-0.267380,0.134414,0.258556,0.610843,0.514403,-0.000759,-0.199786,0.075221,0.047815,-0.377096,0.264116', '25774050', '2988294', '7051375', '20326665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24815502', '该死的歌德', '喜剧', '痞子泽基（埃利亚斯·穆巴里克饰）刚刚出狱，找到了藏有以前抢来的赃款的地方，谁知那里居然建了一所歌德学校。于是他装成代课老师混进学校，找寻藏匿的地点……', '埃利亚斯·穆巴里克', '博拉·达格特肯', 7.5, 8512, 'tt2987732', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2182749627.jpg', 0.6, 3.4, 31.9, 46.2, 17.9, '0.788359,-0.284163,-0.416437,0.188983,-0.083840,-0.521971,-0.018989,-0.116990,-0.224498,-0.617808,0.254189,0.283813,-0.129075,0.190037,-0.083481,0.250331,-0.611378,-0.290888,0.002992,-0.592676,-0.225130,-0.559875,-0.455763,-0.065531,0.177333,-0.264122,0.183432,-0.017226,0.313716,0.230287,-0.114255,0.577838,0.006757,-0.166232,-0.160120,-0.227886,0.358411,0.222479,0.148581,0.507536,-0.043938,0.038839,-0.225231,-0.441876,0.604424,0.544072,0.322837,0.297396,0.275114,-0.105245,0.188073,0.183290,-0.153905,-0.154666,0.326513,-0.336311,0.256101,-0.001648,-0.391792,-0.001993,0.255540,-0.447972,0.261978,-0.112413,0.219401,-0.024536,0.017329,-0.346329,0.140721,0.056607,0.154158,-0.631354,0.103270,0.165797,0.238197,0.293687,0.274631,0.048566,-0.794849,-0.193117,0.052658,-0.580649,0.007785,-0.300142,0.160972,-0.318421,0.400049,-0.008734,-0.146238,0.301861,0.218741,-0.242727,-0.121773,-0.355303,-0.413050,-0.348956,-0.448897,0.395966,0.492787,-0.080034,-0.655281,-1.053924,0.154996,0.533867,0.161781,-0.160050,-0.179084,-0.015684,-0.017539,-0.417873,0.141949,0.691723,0.191646,-0.217904,0.170227,-0.529651,-0.053629,0.043463,-0.082760,0.421907,0.549010,0.715726,0.020216,0.073284,-0.155161,-0.788334,-0.192646,0.176690', '1293572', '3003137', '6517421', '27013111');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24815950', '万物理论', '剧情', '霍金（埃迪·雷德梅恩 Eddie Redmayne 饰）和简（菲丽希缇·琼斯 Felicity Jones 饰）相识于一场舞会上，两人初次见面交谈甚欢，颇有一番相见恨晚的意味。之后，霍金大胆的邀请简参加舞会，二人以此为契机，陷入了热恋之中。不幸的是，一次昏迷令霍金被确诊患上了罕见的肌萎缩性侧索硬化症（ALS），医生坦言他只剩两年的生命，被病魔折磨的霍金陷入了抑郁之中，然而简并没有因此而抛弃他，恰恰相反，几经波折之后，两人踏入了婚姻的殿堂，简还为霍金生下了一个活泼可爱的孩子。霍金的身体迅速的虚弱下来，与此同时，他在学术研究上却取得了一个又一个成就。为了照顾霍金，简心甘情愿成为了他“背后的女人”，但是，这也恰恰成为了两人幸福婚姻里的第一道裂缝。©豆瓣', '埃迪·雷德梅恩', '詹姆斯·马什', 8.4, 271229, 'tt2980516', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2210832820.jpg', 0.1, 0.8, 14.3, 48.8, 35.9, '0.236810,0.167001,-0.635361,0.545106,-0.146138,-0.630094,0.943988,0.113879,-0.572518,-0.250712,-0.036901,0.840870,-0.552386,0.307373,0.328053,0.006467,-0.018305,-0.736315,-0.207893,0.026822,-0.493438,-0.549147,-0.279906,-0.362415,-0.251525,-0.431050,0.370202,0.350950,-0.134977,0.624079,0.281204,0.330195,0.084204,0.611419,0.073261,0.200914,0.165155,0.201785,-0.240159,0.177918,0.130126,-0.398791,-0.053567,0.328877,-0.170634,0.346777,0.609966,-0.206757,0.051391,-0.305253,0.360430,-0.203079,-0.240423,0.204424,0.193476,0.117843,0.340544,0.149023,-0.311648,-0.124905,0.234387,-0.200024,-0.706557,0.026053,-0.176816,0.146644,-0.484888,0.736361,0.017169,-0.061170,-0.224001,-0.263302,0.171782,0.429729,0.455659,0.243867,-0.329855,-0.082677,-0.473361,0.081658,0.754901,0.200910,-0.447578,0.363465,-0.308440,-0.587906,0.010093,-0.256722,-0.355444,-0.063954,0.632882,0.104145,-0.246602,0.310590,-0.269147,-0.174824,-0.584970,0.029671,-0.295075,-0.492629,0.136763,-0.518655,-0.291476,-0.354779,-0.616427,0.029773,-0.027247,-0.499523,0.580200,-0.747364,0.545491,0.294788,0.230849,-0.147685,0.754582,0.218530,0.389292,-0.101453,0.298834,0.222559,-0.170699,0.102890,0.349524,0.446022,-0.204945,0.302415,-0.616540,0.573318', '1292211', '1361252', '30162520', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24826968', '记忆碎片', '喜剧', '繁华都市的边缘地带有一栋老旧而神秘的公寓，里面居住着形形色色奇怪的人，有“高帅穷”的落魄小律师（雷佳音 饰）、有倔强的90后年轻漂亮女孩（夏梓桐 饰）、有惯于溜门撬锁的蠢贼（李菁 饰），更有黑社会老大（李彧 饰）和他的美艳性感情妇（孙宁 饰）以及假药小贩（何云伟 饰）等。一个山雨欲来的夜里，就在这样的公寓里，突如其来多出了一具尸体……到底是谁杀了这个被所有人恨之入骨的男人？是被骗去万贯家财的他？还是被欺骗强暴了的她？抑或一直被人踩在头上的他？围绕着这具让所有人都惊慌不已的尸体，有人惊慌失措准备逃之夭夭，有人面色镇定承认杀人罪行，有人偷梁换柱企图制造自杀现场，有人咬牙切齿主动提出埋尸……在一天一夜之间各色人等都历经了一场终身难忘的记忆。而当谁是凶手的真相貌似“盖棺定论”时，意外的结局反转，让所有人都瞠目结舌……©豆瓣', '雷佳音', '朴裕焕', 4.5, 3670, 'tt5904956', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2355447952.jpg', 31.5, 28.6, 27.9, 8.2, 3.9, '0.113929,-0.042857,-0.744828,0.305034,-0.353224,0.063773,0.832031,-0.030142,-0.606693,-0.093457,0.390566,0.652720,-0.382019,0.220411,0.008835,0.225660,-0.125994,-0.524870,-0.312909,-0.092140,-0.210348,-0.230602,-0.301940,-0.234223,-0.030792,-0.008696,0.232259,0.173178,-0.225510,0.253195,0.594076,0.244434,-0.004978,0.493047,-0.237966,0.094000,0.095874,-0.057760,0.389946,-0.016944,-0.083055,-0.577643,-0.101743,0.258289,-0.363963,0.411812,0.640398,-0.088381,-0.346793,0.113003,0.378157,-0.409282,-0.048749,0.427590,0.263344,-0.286998,0.119104,0.063855,-0.285730,-0.118314,0.375097,0.282150,-0.835333,0.025979,0.197285,0.112254,-0.665599,0.380557,-0.117168,0.062271,0.114130,-0.143113,0.546564,0.031595,0.266959,0.351001,-0.032463,-0.231165,-0.693352,0.183349,0.615160,0.206479,-0.180685,0.020390,-0.198843,-0.397076,0.061802,-0.245349,-0.551951,0.111197,0.388772,-0.228749,-0.279104,0.023054,-0.550013,-0.005045,-0.076517,0.030213,-0.245414,-0.285606,-0.434175,-0.237629,-0.150992,-0.381810,-0.263238,0.127698,-0.110651,-0.137580,0.503433,-0.583750,0.231135,0.489251,0.260989,-0.423687,0.580068,-0.161117,-0.170819,0.159441,-0.223649,-0.133977,0.280394,0.349157,0.231457,0.416244,-0.075514,-0.167828,-0.179066,0.397122', '1299932', '1306801', '21619567', '1297996');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24827387', '盗墓笔记', '悬疑', '落魄作家为了写作素材，寻访到了一个叫做吴邪（鹿晗 饰）的古董铺子老板，而吴邪正准备离开这个城市，临走之前，吴邪和他讲诉了关于自己奇怪的盗墓家族往事，并说出了自己第一次随家族探险所经历的诡异事件：那一次他们的家族因为偶然获取了一件特殊的青铜器， 追根溯源，寻找到了被掩埋在中国西北盆地中的西王母古国，他们招募了一批盗墓贼一同前往古城遗址探险，进入了位于古城地下的西王母陵中，发现了当年周穆王于西王母求长生不死之术的真相。作家听完吴邪的故事，却发现其中有很多疑点，吴邪到底说的是自己的臆想，还是真相更加可怕复杂，因为吴邪的离开变成了永恒之谜。', '井柏然', '李仁港', 4.8, 176465, 'tt5354664', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2370646859.jpg', 27.6, 28.9, 27.1, 9.5, 6.9, '0.515325,0.198848,-0.765737,0.577082,0.161609,-0.297889,0.745705,-0.441565,-0.690010,-0.485540,0.090844,0.917912,-0.128751,0.337880,0.136469,0.251185,-0.314572,-0.287343,0.094254,-0.448627,-0.436304,-0.405610,-0.338859,-0.067685,-0.138900,-0.014798,0.571340,0.578768,-0.362859,0.148213,-0.023473,0.417309,-0.328655,0.526535,-0.265635,0.151913,0.074944,0.219840,-0.194297,-0.022944,-0.026965,-0.393367,-0.300858,0.372145,-0.103193,0.417154,0.327879,-0.414719,-0.301213,0.100849,0.372047,-0.282566,-0.250227,-0.121469,0.225112,0.209839,0.234037,0.456065,-0.096165,-0.098267,-0.085387,-0.118862,-0.698914,-0.024253,0.250089,0.382422,-0.413466,0.265057,0.153654,-0.049379,0.209745,-0.471669,0.563950,0.479821,0.446375,0.276259,-0.142998,-0.110423,-0.516992,0.457952,0.631920,-0.198692,0.014142,0.250246,0.153675,-0.496164,0.166595,-0.000950,-0.081384,0.261632,0.507779,-0.014261,-0.224017,0.212800,-0.721951,-0.076567,-0.142239,-0.335107,0.067534,-0.173879,-0.203491,-0.383308,-0.239700,-0.158706,-0.158322,-0.005435,0.127972,-0.276173,0.577366,-0.650099,0.092105,0.628258,0.202882,-0.655133,0.414554,-0.281863,0.002749,-0.237113,-0.078827,0.406565,-0.119588,0.560813,-0.048271,0.382284,0.242812,-0.399861,-0.617765,0.341021', '34461680', '1309069', '1294941', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24827406', '九层妖塔', '动作', '1979年，昆仑山发生神秘生物骸骨，由胡八一（赵又廷 饰）率领的探险队深入昆仑山腹地，寻找有关古生物遗迹的更多秘密，却不料在这个过程中遭到不同神秘生物的轮番攻击，并意外坠入九层妖塔，除胡八一外，一行人生死成谜。胡八一退伍后回到北京，重逢了发小王凯旋（冯粒 饰），并在神秘人（李晨 饰）与科考队（凤小岳、唐嫣、李光洁 饰）两股力量的夹缝中重新踏上了探寻未知文明的征程，途中与Shirley杨（姚晨 饰）邂逅，熟识的面孔唤醒了他身处探险队那段日子的记忆。此行凶险，在还没来得及搞清楚Shirley的真实身份之际，胡八一、Shirley、王胖子率领一行人便在王子墓、石油小镇等地遭到不明生物的轰炸，这里所发生的一切再度指向九层妖塔，而这次等待他们的，将是一个尘封已千年的未解之谜……©豆瓣', '赵又廷', '陆川', 4.4, 186603, 'tt4819498', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267502788.jpg', 28.4, 35.7, 26.8, 6.1, 2.8, '0.177742,0.125200,-0.949071,0.587161,0.152076,0.068929,0.828516,-0.186728,-0.760744,-0.399725,0.218052,0.370757,-0.218006,0.191591,0.141411,-0.085947,-0.210783,-0.479499,0.056163,-0.247292,-0.537623,-0.225034,-0.404314,0.014964,-0.094573,-0.452128,0.697511,0.617569,-0.256926,0.429855,-0.033990,0.230746,-0.704632,0.622342,-0.188961,0.050103,0.195693,0.309196,-0.334267,-0.002783,-0.208879,-0.402415,-0.195890,0.133456,-0.207316,0.278566,0.739867,-0.369159,0.030988,0.107650,0.074410,-0.257422,-0.134722,-0.000440,0.516630,-0.087023,-0.042933,0.344398,-0.101439,0.098117,0.027061,-0.084586,-0.502655,-0.100547,0.139451,0.320395,-0.252495,0.134704,-0.017758,0.081575,0.097982,-0.423127,0.318152,0.488336,0.456352,0.248661,0.059420,-0.218683,-0.295511,0.146151,0.703210,-0.097528,-0.165036,0.201035,0.059873,-0.703912,-0.377249,0.188391,-0.099641,0.223959,0.438044,0.370227,-0.173550,0.344693,-0.746233,0.164679,-0.146227,-0.252096,0.075861,-0.243609,-0.183297,-0.725560,-0.311379,-0.274100,-0.094025,0.186081,0.028587,-0.042892,0.301429,-0.406387,0.420885,0.393812,0.151028,-0.427507,0.585090,-0.172972,0.098075,-0.257974,0.176642,0.443468,0.152645,0.509892,-0.197768,0.282315,-0.145702,-0.015370,-0.516129,0.120303', '3011051', '10733357', '1309056', '20380318');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24827612', '飞机总动员2：火线救援', '喜剧', '自从赢得世界大赛之后，农用飞机“尘土”已经成为尽人皆知的草根冠军。可是有一天在练习时，他的身体发现异样。经检查后得知他的变速箱出了问题，该型号变速箱由于老旧已经停产，这也意味着尘土再也无法参加激烈的比赛。一天夜里，不甘失败的尘土继续挑战极限，结果引发弯角服务站机场加油站的大火。虽然侥幸扑灭火灾，但是由于机场安全消防措施不过关，面临着被关闭的命运。眼看就到了机场玉米节狂欢，在场的每一个人都提心吊胆。感觉负主要责任的尘土主动要求参加消防员的培训，在此之后他结识了有着丰富丛林火灾扑灭经验的刀锋、乘风者、北斗星等新伙伴。一切从零开始，命运发生转折的尘土迎难而上……©豆瓣', '朱丽·鲍温', '罗伯茨·甘纳韦', 6.9, 4635, 'tt2980706', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2206343261.jpg', 1, 6.7, 51.2, 29.6, 11.5, '0.029593,0.214945,-0.852045,-0.083212,0.201524,-0.048228,0.371069,0.046378,-0.351239,-0.223590,0.500922,0.370959,-0.230566,-0.132030,0.197177,-0.407568,-0.196782,-0.675700,0.139392,-0.162774,-0.748200,-0.282982,0.078028,-0.191181,0.154839,-0.357978,0.602983,0.515816,-0.041439,0.436957,0.218845,-0.185048,0.097096,0.716088,-0.107967,-0.252354,0.029832,0.134791,-0.182269,0.174351,-0.087813,-0.364813,-0.226425,-0.140056,0.064546,0.553590,0.626268,0.140383,-0.337583,0.098540,0.415996,-0.297728,0.052061,0.041552,0.574774,0.203038,-0.104044,0.307279,0.145126,0.040356,-0.025954,0.073772,-0.572448,-0.029180,-0.053276,0.051832,-0.411337,0.576960,-0.040950,-0.042683,-0.118372,-0.118871,0.286499,0.215276,0.377318,0.395750,-0.405764,0.079934,-0.450360,0.108428,0.776709,-0.316660,-0.395716,0.305035,-0.128403,-0.325516,-0.024326,-0.379407,-0.064641,0.173329,0.317460,0.454419,-0.283492,0.221653,-0.466606,0.114373,-0.189053,-0.515619,-0.211371,-0.076391,-0.135229,-0.650317,-0.045916,-0.089404,-0.289732,0.100859,0.037763,-0.129589,0.416784,-0.611337,0.270018,0.391197,0.050194,-0.403988,0.345817,-0.121759,0.171549,-0.217717,0.081135,0.277608,-0.287455,0.671310,0.055271,0.363853,0.000710,-0.263035,-0.213892,0.296039', '26418093', '25786077', '25870679', '5157137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24839091', '捉迷藏', '悬疑', '事业有成的中年男子白成洙（孙贤周 饰）与妻子闽祉（全美善 饰）以及一双儿女户三和秀雅住在一幢高级公寓中，衣食无忧，幸福安逸。这一天，他意外收到一通电话，对方称成洙的哥哥成则失踪数月，下落不明。成则自高中后离家出走，期间履历中留下不光彩的记录。心中怀有隐秘的成洙来到哥哥所在的公寓，发现其房内有许多别人衣物，并且周围住户都对成则谈之色变，而各家门口也都标记了意义不明的记号。未过多久，一名头戴摩托盔的神秘男子袭击了闽祉母子，危险明显向白成洙一家逼近，有着严重洁癖的成洙精神几近崩溃。豪华敞亮的私宅内，神秘之人悄悄入住，与主人玩起了凶险非常的捉迷藏……©豆瓣', '孙贤周', '许政', 6.9, 31300, 'tt3155654', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2040176434.jpg', 2.3, 7.7, 43.5, 35.9, 10.6, '0.246491,0.029040,-0.729977,0.370161,0.010888,-0.056910,0.866032,0.100701,-0.535475,-0.347719,0.316568,0.533446,-0.202709,0.311590,0.420644,0.161171,-0.047783,-0.497103,-0.145682,-0.417037,-0.226522,-0.323456,-0.390426,-0.159544,0.013873,-0.294043,0.177481,0.483416,0.096307,0.556506,0.155313,0.151758,-0.497877,0.319485,-0.057866,-0.059077,-0.032950,0.007063,-0.115111,0.082833,-0.067114,-0.083874,0.062778,0.175211,-0.042134,0.366626,0.698971,-0.230441,-0.525395,-0.040587,0.339058,0.291763,-0.214439,0.278136,0.446614,0.238279,0.383883,0.219979,-0.250294,0.203661,-0.104889,0.082253,-0.315970,0.008639,0.146356,0.141682,-0.303148,0.532284,-0.088135,-0.419457,-0.081008,-0.235261,0.259421,0.216785,0.056014,0.342264,-0.161655,0.279941,-0.438952,-0.122007,0.504090,-0.032920,0.019185,0.118679,-0.128734,-0.280004,0.051772,-0.140224,-0.374776,0.084763,0.313156,0.213197,0.194058,-0.042206,-0.488504,0.308191,-0.163910,0.033949,-0.154265,-0.143934,-0.271501,-0.442573,0.022584,-0.365256,-0.262312,0.421091,0.019820,-0.109462,0.345557,-0.694724,0.354355,-0.080468,0.392852,-0.510925,0.524510,-0.214013,0.423758,-0.139119,-0.233497,0.250236,-0.026905,0.297056,-0.128941,0.290196,-0.377483,-0.218083,-0.317324,0.316228', '1296534', '3111650', '20380318', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24839101', '只在那里发光', '剧情', '故事发生在一座远离大都会的小城市，无所事事的青年佐藤达夫（绫野刚 饰）曾经在某矿山工作，但在目睹一次事故后让他选择逃离。日常里他周游在城市各个角落，直到某天在小钢珠店结识了小青年大城拓儿（菅田将晖 饰）。拓儿此前因伤害罪入狱服刑，后来假释出狱，经姐姐千夏（池胁千鹤 饰）介绍在熟人的公司谋得一份差事。他们的家贫穷不堪，父亲卧病在床，千夏在三流酒吧内出卖肉体，日常还不得不委身与拓儿的老板（高桥和也 饰），饱受屈辱。初次相逢，似乎让达夫和千夏对彼此有了好感，他们越走越近，孤独的心靠在一起相偎取暖。然而命运的捉弄却才刚刚开始……本片根据已故作家佐藤泰志唯一一部长篇小说改编。©豆瓣', '绫野刚', '吴美保', 7.3, 7476, 'tt3039932', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2213387895.jpg', 0.7, 3.9, 37.8, 43.4, 14.1, '0.167265,-0.130459,-0.533227,0.277681,0.199164,-0.236604,0.686018,0.394351,-0.501201,-0.284177,0.417801,0.772064,-0.156001,0.272261,0.209838,0.010240,-0.303025,-0.429859,0.082440,-0.272948,-0.137569,-0.508306,-0.200510,-0.146902,-0.258610,-0.199603,0.690832,0.039643,-0.063465,0.348130,0.058637,0.086817,-0.427215,0.337909,-0.189307,0.083675,0.239765,0.157276,-0.465963,0.119251,-0.074363,-0.309056,-0.334880,-0.161685,0.107416,0.146523,0.767853,-0.055314,-0.373368,-0.089644,0.214373,-0.010235,-0.128184,-0.105573,0.262406,-0.070696,0.398461,0.356087,-0.396498,0.140006,0.054822,0.086802,-0.298427,0.145814,0.218689,0.097931,-0.508710,0.704969,0.060764,-0.150185,0.275950,-0.521483,0.045050,0.285479,0.208362,0.336315,-0.348230,0.187551,-0.270716,0.244949,0.701725,-0.002269,0.079222,0.387393,0.122844,-0.199638,-0.085853,-0.251244,-0.536701,0.004600,0.006307,-0.096409,-0.300563,0.268495,-0.557746,0.071883,-0.178473,-0.076113,0.296859,-0.332564,-0.126228,-0.595134,-0.134448,-0.331136,-0.290981,0.117734,0.191444,-0.297902,0.666280,-0.759660,0.169521,0.573638,0.231899,-0.406962,0.509585,0.315226,0.083386,-0.102260,-0.061814,0.267406,0.051042,0.428111,0.107069,0.167355,-0.200297,-0.039426,-0.430229,0.314152', '3811356', '1292219', '3445516', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24839498', '热血青春', '喜剧', '在一个远离城市喧嚣的所在，有着姣好面容的英淑（朴宝英 饰）似乎与温柔娴淑绝缘，就读于洪城农高的她平日里时常带着一群女混混和邻校的帮派打架斗殴，身上的伤疤成了家常便饭。与之同校的姜中吉（李钟硕 饰）拥有一副好皮囊，他隔三差五寻花问柳，在花丛中恣意招摇。就读洪城工高的不良少年光石（金英光 饰）和英淑、中吉都是旧相识，他对英淑抱有好感，将其视为自己的女人，只是英淑不以为然。某天，美丽的女孩韶熙（李世英 饰）为了养病从首尔转学到洪城农高，她自然成为中吉下一个狩猎的目标。青年男女们傻乎乎的热血青春，有趣的故事就此展开……©豆瓣', '朴宝英', '李延宇', 7.2, 56544, 'tt3579990', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167586161.jpg', 0.9, 6.7, 41.7, 35.4, 15.4, '0.387095,0.149235,-0.601851,0.477122,-0.249357,-0.003774,0.952376,0.231482,-0.274195,-0.088149,0.152134,0.602846,-0.301891,0.475165,0.229104,0.098457,-0.192994,-0.890820,-0.343244,-0.314550,-0.024606,-0.201617,-0.152846,0.117649,-0.112403,-0.394431,0.506990,0.057057,-0.166511,0.637796,0.367890,0.346935,-0.305527,0.281445,-0.461905,-0.209692,-0.246390,0.160678,0.092184,-0.091495,-0.179647,-0.287016,-0.311253,0.070984,0.008256,0.266739,1.119105,-0.188085,-0.069860,-0.139526,0.290226,0.038711,-0.172581,0.177291,0.192783,-0.188245,0.168329,0.042778,-0.014685,-0.037552,0.270040,-0.181315,-0.482483,0.088924,0.085458,0.296451,-0.405289,0.776507,0.221767,-0.172387,0.162677,-0.163631,0.186726,0.058820,-0.040513,0.265668,-0.155976,0.403104,-0.531518,0.423397,0.525278,0.442665,-0.273988,0.227181,-0.353396,-0.341578,0.046489,-0.275859,-0.471078,-0.303981,0.200987,-0.358561,0.014505,0.067224,-0.695359,0.086589,-0.066350,0.077972,-0.026155,-0.206731,-0.272767,-0.465553,-0.239931,-0.849804,-0.499146,0.113746,0.075093,-0.103211,0.979438,-1.025982,0.108628,0.378834,0.256773,-0.544729,0.690153,0.095135,0.065512,-0.097295,-0.438701,0.115359,0.168775,0.112180,0.001930,0.627806,-0.463364,-0.171474,-0.410904,0.458781', '3811356', '1826173', '3155839', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24843198', '同桌的妳', '剧情', '成功在美国立足的青年林一（林更新 饰）收到了初恋女友周小栀（周冬雨 饰）寄来的结婚请帖，百感交集的林一准备回国参加，坐飞机的途中他回忆起了自己和周小栀长达十几年的故事。少年林一第一次看到同桌周小栀（张子枫 饰）时就喜欢上了这个文静的小姑娘，但是直到高中毕业两人也没有跟进一步的发展。大学时两人考到了同一所学校，遇到了假冒留学生Tom（隋凯 饰）、文艺青年王尔德（王啸坤 饰）、胖子学霸龚兵（龚格尔 饰）、沉默男李潇（李岷城 饰）、胆小姑娘赵晓溪（赵思园 饰）和美女曹阳（曹阳 饰）等一众好友，随即开始了他们的热血青春……本片取材于高晓松创作的风靡一时的校园歌曲《同桌的你》，高晓松出任了本片的监制。©豆瓣', '周冬雨', '郭帆', 6, 257355, 'tt3956312', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2179302706.jpg', 6.7, 21.2, 46.5, 18.7, 6.8, '0.300849,-0.013959,-0.611488,0.533318,0.081726,-0.642910,0.480072,0.215766,-0.451516,-0.345961,-0.186957,0.526825,-0.570296,0.498880,0.507545,-0.110289,-0.288879,-0.654095,-0.061725,-0.162269,-0.234299,-0.138937,0.095602,-0.088487,-0.147516,0.013747,0.426276,-0.019158,-0.100096,0.711658,0.587454,-0.034149,0.007699,0.372610,-0.059778,0.245535,0.115898,0.171331,-0.156119,0.112650,0.145511,-0.348853,-0.087321,-0.134414,0.161477,0.215047,0.823847,0.179090,-0.140770,0.031483,0.541294,-0.076208,-0.096351,-0.060759,0.373732,0.027514,0.217209,-0.191207,0.065636,-0.069865,0.078536,-0.264324,-0.036282,0.131581,0.144898,0.079860,-0.396357,0.396633,-0.061513,-0.061952,0.124751,-0.470494,0.135619,0.331290,0.328158,0.165703,0.065562,-0.079539,-0.261854,0.910513,0.399479,0.223934,-0.105309,0.282653,-0.036699,-0.713109,-0.244188,0.195272,-0.612319,0.290821,0.336792,-0.183606,0.022841,-0.260260,-0.456042,-0.266632,0.017308,0.064904,-0.013154,-0.263728,-0.112380,-0.587791,-0.129242,-0.535529,-0.213613,0.117022,0.081523,-0.086567,0.800154,-0.779038,0.103144,0.121741,0.242684,-0.317616,0.548031,-0.100467,-0.083735,-0.183064,0.257092,0.060558,-0.042796,0.143586,0.155485,0.720763,-0.234178,-0.224231,-0.300907,0.265032', '3811356', '25922902', '26784898', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24845115', '浪客剑心：京都大火篇', '动作', '进入了明治时代，曾经的“刽子手拔刀斋”绯村剑心（佐藤健 饰）已经习惯了神谷道场的安宁生活。谁知就在这一天，倒幕战争时的旧友——号称维新三杰之一的大久保利通（宫泽和史 饰）将其请去。原来继承了剑心刽子手身份的志志雄真实（藤原龙也 饰）当年被新政府背叛，侥幸活下来的志志雄正秘密筹措称霸日本的可怕计划。大久保死后，深感背负不可推卸责任的剑心只身上路，在途中不仅偶遇京都女忍卷町操（土屋太凤 饰），还在新月村和志志雄有了第一次的遭遇。与此同时，相乐左之助（青木崇高 饰）、神谷薫（武井咲 饰）、明神弥彦（大八木凯斗 饰）、斋藤一（江口洋介 饰）也相继赶往京都。阴云密布的时代，酝酿着一场席卷全国的风暴……本片根据和月伸宏的经典漫画原作改编。©豆瓣', '佐藤健', '大友启史', 8.1, 57001, 'tt3029558', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2184443605.jpg', 0.3, 1.9, 20.7, 48.7, 28.3, '-0.120466,0.103227,-0.514573,0.191294,0.206390,-0.319665,0.226334,0.352359,-0.350014,-0.349638,0.342255,0.572509,-0.178086,-0.031953,0.283027,0.066690,-0.169362,-0.513384,-0.243667,-0.153509,0.073746,-0.235564,-0.309414,-0.023485,-0.170312,-0.271301,0.629028,0.393382,-0.161019,0.370195,0.312734,0.368796,-0.127271,0.142577,-0.114598,0.154477,0.008118,0.172841,-0.184476,0.108586,-0.300784,-0.413192,-0.177417,0.380557,0.065599,0.265349,0.455584,-0.372683,0.017130,-0.203121,0.291825,-0.013812,-0.460515,0.106873,0.565823,0.004983,0.013458,0.372171,-0.287950,0.053988,0.032741,-0.107320,-0.594845,0.009735,0.183244,0.070999,-0.324145,0.504327,-0.248856,-0.313682,0.213537,-0.294540,0.112317,0.231049,0.466251,0.094602,-0.333902,0.017886,-0.178938,0.346441,0.531328,-0.225003,0.056440,0.094343,0.087358,-0.299204,-0.492154,-0.193473,0.035319,-0.233462,0.405223,-0.066501,-0.106742,0.249331,-0.323594,-0.168642,-0.159932,-0.054500,0.290117,-0.082055,-0.129431,-0.431734,0.043807,-0.366605,-0.151520,0.189957,0.386444,-0.003784,0.746430,-0.647215,0.224323,0.421693,-0.004790,-0.127668,0.286958,0.010814,-0.138535,0.052070,-0.024813,0.311177,0.078951,0.540351,0.238824,0.360672,-0.213410,-0.158836,-0.154206,0.314329', '1826173', '27602116', '1920765', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24845116', '浪客剑心：传说的完结篇', '剧情', '为了救神谷薰（武井咲 饰），绯村剑心（佐藤健 饰）纵身跃入大海，昏迷中他飘到某座小岛，最终为传授了他飞天御剑流的师父比古清十郎（福山雅治 饰）所救。深感到自身与志志雄真实（藤原龙也 饰）的巨大差距，为了拯救全日本，剑心恳请师傅传授他飞天御剑流的最高奥义。与此同时，志志雄剑指东京，迈出武力夺国的下一步。他强迫伊藤博文（小泽征悦 饰）对刽子手拔刀斋发布全国通缉令，得知消息的薰、左之助（青木崇高 饰）则匆匆向东京赶去。再度上路的剑心率先遭到御庭番众的首领四乃森苍紫（伊势谷友介 饰）的阻击，他一路披荆斩棘，将迎来与宿命的对手志志雄最终的对决……本片根据和月伸宏的同名经典漫画改编。©豆瓣', '佐藤健', '大友启史', 8.2, 49917, 'tt3029556', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194586665.jpg', 0.3, 1.8, 19, 46.7, 32.1, '-0.111657,0.206905,-0.371553,0.667940,0.205401,-0.136706,0.094372,0.080157,0.070240,-0.328957,0.525979,0.650593,0.064481,-0.202901,0.434724,-0.106637,-0.031985,-0.714806,-0.056654,-0.166919,-0.158914,-0.210742,-0.183470,-0.020416,-0.274144,-0.096158,0.736570,0.210280,-0.154518,0.618409,0.391281,0.598663,-0.281693,-0.084119,-0.013108,0.152479,-0.134401,-0.138753,-0.187354,0.411581,-0.179966,-0.321163,-0.251892,0.470482,-0.105235,0.311933,0.499305,-0.317626,-0.002932,-0.225964,0.158008,-0.157757,-0.110044,-0.029162,0.331417,0.212031,-0.146421,0.294773,-0.255250,0.248118,-0.074808,-0.022146,-0.624393,0.037560,0.176568,-0.039539,-0.381859,0.311778,-0.428382,-0.141390,0.383817,-0.329764,-0.203499,0.015713,0.286583,0.147250,-0.295028,0.005302,0.073206,0.099078,0.520923,-0.147633,0.241429,-0.006401,0.278087,-0.203659,-0.224336,-0.053301,0.312323,-0.219693,0.353973,0.327333,0.183529,0.224902,-0.396676,-0.202739,-0.083323,0.039260,0.018548,-0.119563,-0.012202,-0.516303,-0.000644,-0.306776,0.145015,-0.152699,0.112859,-0.104973,0.695538,-0.510705,0.120158,0.196431,0.245958,-0.171621,0.393067,-0.184077,-0.151439,-0.120586,-0.214945,0.462162,0.235258,0.460948,0.122922,0.188837,0.012065,-0.034762,-0.401133,0.163207', '25880986', '10467125', '3811356', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24847340', '小时代3：刺金时代', '剧情', '林萧（杨幂 饰）、顾里（郭采洁 饰）、南湘（郭碧婷 饰）、唐宛如（谢依霖 饰）四个从小一起长大的好姐妹大学毕业进入职场，开始了新的旅程。原本离开了姐妹们，准备和堕落的男友席城（姜潮 饰）离开上海的南湘重新回归到姐妹们身边。顾里率领众人搬进了新的别墅，大家继续着同一屋檐下的乌托邦生活。林萧、顾里陪同宫洺（锦荣 饰）参加罗马的时尚活动，还叫上了南湘和唐宛如，又在罗马遇上了顾里的混血表弟Neil（李贤宰 饰）。然而当林萧回到上海，却接到了男友崇光（陈学冬 饰）癌症复发不幸去世的噩耗。几个月后，终于振作起来重新开始新生活的林萧却遇到了一个总是让她莫名想起崇光的外国模特陆烧（陈学冬 饰）。与此同时，顾里从未见过面的亲生弟弟顾准（任佑明 饰）突然出现，手握顾家20%的隐藏股份，他告诉顾里M.E有一个巨大的财务漏洞，姐弟两人联手想要夺回被M.E收购的盛古公司。顾里说服姐妹们借着宫洺生日暨M.E周年庆的机会去宫家老宅偷取关键文件，一切会如她们预想的那样顺利吗？一个最漫长难熬的夜晚在静静等待着她们……', '杨幂', '郭敬明', 4.7, 230760, 'tt3861006', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189080319.jpg', 29.3, 27.3, 29, 7.9, 6.4, '0.075550,0.158944,-0.631300,0.469626,0.026708,-0.538143,0.608560,0.317187,-0.456589,-0.434300,0.078671,0.579803,-0.263727,0.586730,0.353756,-0.051522,-0.345813,-0.637378,-0.127921,-0.055169,-0.266249,-0.174596,0.090215,-0.147583,0.081390,0.074471,0.431167,0.007684,0.108172,0.615664,0.488450,0.253892,-0.299635,0.425648,-0.335609,0.156885,0.087831,0.204566,-0.408614,0.340672,-0.039166,-0.039918,-0.145688,0.130996,0.211160,0.085410,0.620443,-0.068489,-0.012839,-0.120045,0.523813,-0.043407,-0.129930,0.078728,0.362000,0.241474,0.193678,0.073575,-0.402548,0.090691,-0.067461,-0.343716,-0.270521,0.169698,0.197786,0.005196,-0.623403,0.315566,0.126155,0.004844,0.172869,-0.411639,0.408212,0.635512,0.226084,0.319491,-0.204343,0.209463,-0.534367,0.314268,0.652905,-0.081582,-0.008121,0.112683,0.240401,-0.281502,0.007083,0.094146,-0.371931,0.063970,0.392965,-0.021410,0.013429,-0.042292,-0.616488,-0.111577,-0.075763,-0.067524,0.218190,-0.362037,0.078689,-0.712951,0.008020,-0.265336,-0.287463,0.231361,-0.174260,-0.164064,0.624628,-0.733042,0.274085,0.175956,0.419051,-0.592482,0.311879,0.045923,0.285272,-0.183027,0.087935,0.267142,0.081157,0.223111,0.110363,0.339018,-0