INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24847343', '小时代4：灵魂尽头', '喜剧', '时间指向2015年，林萧（杨幂 饰）和陆烧（陈学冬 饰）在焰火盛放的外滩拥吻。这则花边新闻直接影响M.E.的经营，叶传萍（王琳 饰）强势入主，宫洺（锦荣 饰）形同傀儡，他对林萧的情感不易察觉，同时似乎也没有注意到南湘（郭碧婷 饰）的脉脉含情。叶传萍盛气凌人，质问顾里（郭采洁 饰）盛古亏空四个亿的情况，却始终没有攻破顾里的防线。与此同时，深陷财务危机的顾里被诊断患有子宫癌，精神和肉体的打击让这个倔强的女孩濒临崩溃。走入社会，进入职场，林萧、顾里、南湘、唐宛如（谢依霖 饰）、顾准（任言恺 饰）、Neil（李贤宰 饰）等好朋友被卷入充满尔虞我诈的漩涡之中，她们的友情和爱情也将承受前所未有的考验……本片根据郭敬明的同名原作改编。©豆瓣', '杨幂', '郭敬明', 5, 184825, 'tt4814354', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2250399288.jpg', 26.4, 24.9, 30.6, 10.1, 7.9, '0.063321,0.138190,-0.666937,0.491570,-0.030233,-0.024314,0.973685,0.338075,-0.405340,-0.246453,0.161181,0.218010,-0.424788,0.020431,0.128398,-0.253896,0.078039,-0.702908,-0.182513,0.108545,-0.149490,-0.278535,-0.189262,-0.098314,-0.091749,-0.286650,0.713068,0.202245,-0.516083,0.614907,0.300474,0.453939,-0.143064,0.709777,0.081067,0.144254,-0.036695,0.053366,-0.162427,0.256663,0.047286,-0.248400,0.056469,0.290580,-0.099472,0.434076,0.675202,-0.261421,-0.018802,0.274165,0.547889,-0.163097,-0.218807,0.252738,0.199374,0.011920,0.014217,0.027609,-0.523669,0.254489,0.139846,-0.135425,-0.636964,-0.128462,0.308496,0.238043,-0.392477,0.561136,-0.013510,-0.191437,-0.071638,-0.038900,0.189772,0.177657,0.381059,0.381177,-0.260279,0.113682,-0.457024,0.291563,0.296026,-0.006898,-0.348897,0.335765,-0.273107,-0.428147,-0.465865,-0.094891,-0.320340,-0.020741,0.273638,0.110126,-0.022101,0.161333,-0.543282,-0.191198,-0.055481,-0.122443,-0.165134,-0.380857,-0.009156,-0.577913,-0.469820,-0.530851,-0.228815,0.129919,-0.071377,-0.101772,0.541018,-0.608267,0.159178,0.054648,0.331151,-0.451044,0.555509,0.061159,-0.205827,-0.248974,-0.052357,0.579751,0.012552,0.051940,0.169099,0.345927,-0.199025,-0.014638,-0.299868,0.342382', '21348112', '25911595', '1417428', '2131640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24849892', '喜马拉雅', '剧情', '电影讲述的是韩国登山家朴武宅于2004年在攀登海拔8750M的珠穆朗玛峰时，不幸遇难。为了寻回同伴的遗骨使他们安息，严弘吉（黄政民饰）率团前往珠穆朗玛峰，开始了新一次远征。5月29日，严弘吉和他的队员不负众望，在8700 M处找到了朴武宅的遗体，在冰雪皑皑的世界屋脊之巅 举行了隆重的安葬仪式，并且立碑为念。当时这件事曝光后，也引发了感动如潮。韩国演员黄政民此次在片中饰演亚洲首位完成14座8000米的韩国登山家严弘吉一角。该片将由推出了《海云台》、《舞后》、《快递惊魂》等影片的JK Film担当制作，通过《和声》展现了细腻掌镜力的康大奎导演将再执导筒。影片还将在尼泊尔等地的雪山实地取景，以展现更加真实的雪山风貌。', '黄政民', '梨晳勳', 7.4, 8079, 'tt4253360', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2275273323.jpg', 0.8, 3, 36.9, 43.7, 15.6, '-0.261646,-0.042517,-0.831681,0.720083,0.222476,-0.026790,0.264914,0.160282,-0.331409,0.213857,0.368795,0.997004,-0.434785,0.127061,0.496891,-0.036740,-0.440916,-0.860473,-0.338203,-0.163014,-0.437967,-0.109916,-0.093017,0.001202,-0.068806,-0.423194,0.815361,0.203986,-0.318442,0.475907,0.080208,-0.098791,0.039101,0.201853,-0.348709,-0.073129,-0.164991,0.119995,-0.411134,0.509814,-0.062968,-0.478262,-0.224762,0.043614,0.041697,0.410024,0.849968,-0.354592,-0.226461,0.011358,0.470274,-0.457346,0.278018,0.008215,0.118364,0.093716,-0.133099,0.430592,-0.490853,0.034622,0.093941,-0.468868,-0.688317,-0.041328,0.087414,0.076958,-0.721218,0.511923,-0.227615,-0.047807,0.203019,-0.277222,0.311066,0.425826,-0.046442,0.360261,-0.100855,-0.026711,-0.145243,0.619630,0.538450,0.101145,-0.044507,0.081540,0.233144,-0.666350,-0.017615,-0.162086,-0.138206,0.015317,0.337780,-0.005679,0.053105,-0.017646,-0.638258,-0.253293,-0.249970,-0.592462,0.039435,-0.356303,-0.122082,-0.755483,-0.143060,-0.042386,0.209572,-0.432849,0.179778,-0.243882,0.807818,-0.473780,0.364110,0.503071,0.226439,-0.103116,0.674553,-0.083420,0.154763,-0.044021,0.020257,0.074818,-0.072153,0.679484,0.012019,0.460617,-0.065428,-0.204343,-0.726024,0.156647', '1780122', '25928048', '3811356', '3158990');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24851526', '我的男友和狗', '爱情', '蔡琬真（张钧甯 饰）和男友沈浩介（何润东 饰）交往多年，彼此之间感情十分要好。身为编辑的蔡琬真工作很是繁忙，巨大的职场压力下，她不得不将几乎全部的时间都放在了办公室之中。对于女友的忙碌，沈浩介十分理解，并给与了极大的支持，成为了蔡琬真最坚实的后盾。一只名叫拉里的小狗意外降临到了蔡琬真和沈浩介两人的生活之中，成为了家庭中的一份子，然而，真正能够陪伴拉里的却只有沈浩介，因为蔡琬真实在是太忙了。长此以往，蔡琬真和沈浩介之间的感情开始产生了裂痕，与此同时，拉里病了，它的生命时钟开始了倒计时，在此情况下，蔡琬真会做出怎样的选择呢？©豆瓣', '张钧甯', '陈慧翎', 5.7, 13483, 'tt3527134', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2247497649.jpg', 7.9, 26.5, 45.7, 14.3, 5.6, '0.266756,0.134692,-0.654830,0.510227,-0.065765,-0.060698,0.677560,0.226942,-0.699747,-0.234086,0.089968,0.631252,-0.216230,0.360696,0.137137,-0.354362,-0.158350,-0.723019,-0.228361,-0.110845,-0.423296,-0.371250,-0.258015,0.008773,-0.304951,-0.344587,0.700644,0.041335,-0.096126,0.300988,0.197290,0.360971,0.187660,0.631698,-0.099288,-0.006357,0.001042,0.082182,-0.288856,0.094743,0.221037,-0.271684,0.112776,0.436017,0.048903,0.374967,0.544679,-0.453382,-0.390124,-0.069586,0.375914,-0.199169,-0.050941,0.090329,0.281283,0.130777,0.394491,0.415938,-0.363511,0.095766,0.035865,-0.198585,-0.925259,-0.133323,0.097262,0.315742,-0.636604,0.490202,0.011478,-0.399620,0.105211,-0.495945,0.185641,0.505414,0.268831,0.292460,-0.439072,-0.012683,-0.401552,0.024177,0.683002,0.216364,-0.318294,0.648772,-0.349569,-0.421019,-0.254154,-0.171690,-0.284605,-0.157784,0.050375,0.464660,0.054500,0.306394,-0.600432,0.111598,-0.041043,-0.274790,0.042383,-0.789312,-0.031732,-0.322810,-0.266203,-0.601288,-0.409385,0.124465,0.073782,-0.461596,0.687495,-1.043640,0.122578,0.225522,0.247489,-0.224547,0.613264,0.226886,0.121382,-0.145801,0.117679,0.099563,-0.154070,0.194227,0.134643,0.116288,-0.074551,-0.274180,-0.366326,0.671868', '35030151', '1783461', '1937946', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24852462', '菜鸟评审员', '喜剧', '某广告公司小职员太田喜一郎（妻夫木聪 饰）虽然充满热情，但是无论职场还是日常的人际交往都饱受挫折，偏偏他的上司大泷一郎（丰川悦司 饰）又是自私自利、推诿塞责的人，以致于太田被他耍的团团转。这一天，即将前往圣莫尼卡广告节担当评委的大泷遇到棘手的难题，某金主客户要求自家拍的无聊广告必须在广告界上获奖，大泷转嫁危机，哄骗太田替自己去海外当评委。临危受命的傻小子先跟随资料室的镜先生（Lily Franky 饰）学习评委技巧，之后拜托精英女同事阿光（北村景子 饰）假扮老婆随行。在海外他们不仅遭遇强劲的对手木泽遥（铃木京香 饰），还必须应对评委们千奇百怪的小伎俩。过于驽钝迂直的太田能否顺利完成不可能的任务呢？©豆瓣', '妻夫木聪', '永井聪', 6.7, 6811, 'tt3063996', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2160558412.jpg', 1.9, 10.3, 46.5, 32.8, 8.5, '0.011573,-0.158759,-0.202945,0.265829,-0.198968,-0.134624,0.140538,0.277655,-0.356378,-0.305745,0.553543,0.573005,-0.038896,0.214475,0.259799,-0.051036,-0.393397,-0.439463,-0.024284,0.090643,-0.114818,-0.353590,-0.126195,-0.060734,-0.215640,0.068965,0.566812,-0.087349,-0.214270,0.003802,0.590039,0.157021,-0.061425,0.201444,0.114351,-0.035885,0.303877,0.121611,-0.100436,-0.028227,-0.197510,-0.151321,-0.310447,-0.113318,0.360535,0.368005,0.328189,-0.142283,-0.206368,-0.178517,0.279071,-0.284249,0.136519,0.213638,0.023880,0.144220,0.297854,0.136836,-0.101655,0.099981,0.054938,-0.090892,-0.579968,0.180200,0.271193,-0.007955,-0.416059,0.331098,-0.025940,-0.200712,0.141320,-0.217636,-0.356037,0.204261,0.157589,-0.044838,-0.131502,0.241442,-0.186793,0.306480,0.414764,0.159710,-0.044301,0.071911,0.076979,-0.463817,-0.097605,-0.555962,-0.263669,0.034909,0.123632,-0.156213,-0.199278,0.155011,-0.213659,0.125686,-0.059331,0.007415,0.002474,-0.149702,0.072307,-0.693634,0.429712,-0.351135,-0.274313,0.155166,0.454742,0.017325,0.977264,-0.622260,-0.155386,0.644280,0.252062,-0.422446,0.510249,0.375137,-0.218333,-0.246043,-0.506158,-0.354277,-0.006928,0.552802,0.222768,0.480671,0.218432,-0.441387,-0.069957,0.093465', '27602116', '24284209', '3072064', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24852545', '爱情公寓', '喜剧', '你的月亮我的心电台被临时改成了盗墓笔记深夜广播剧，曾小贤（陈赫饰）也不得不去读盗墓笔记。曾小贤、胡一菲（娄艺潇饰）、吕子乔（孙艺洲饰）、张伟（李佳航饰）、唐悠悠（邓家佳饰）、陈美嘉（李金铭饰）的故事继续展开，这一次，他们打算搞个大事情。在曾小贤的一次梦中，他与爱情公寓的伙伴们误打误撞进入了盗墓笔记的世界。之后他们与盗墓笔记的三人组一起对抗反派黄黑红，保护青铜门 。', '陈赫', '韦正', 3.2, 253079, 'tt8893870', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2521648155.jpg', 67.7, 15.1, 10, 3.1, 4.1, '0.139028,-0.100212,-0.476577,0.937722,-0.082699,-0.312975,0.573989,0.121673,-0.600667,-0.469930,-0.156878,0.562963,-0.108085,0.498646,-0.054841,-0.105844,-0.450592,-0.657514,0.057114,-0.125985,-0.445325,-0.301546,0.001996,-0.387393,-0.097490,0.254161,0.448707,0.159870,-0.407653,0.222594,0.287297,-0.136576,-0.302860,0.266284,0.048149,0.166305,0.202764,0.227614,-0.213746,0.013712,0.056334,-0.004670,-0.452388,0.009045,0.202398,-0.050356,0.543979,-0.026957,-0.093407,-0.050625,0.198355,-0.169265,-0.227055,-0.026862,0.355973,0.411564,0.349143,0.071420,0.046832,-0.039639,-0.001565,-0.113153,-0.471807,-0.119714,-0.196793,-0.159859,-0.617704,0.317449,-0.085436,0.244872,0.119486,-0.363347,0.170312,0.294570,0.647397,0.080210,-0.122382,-0.177568,-0.235242,0.636067,0.410627,0.014824,0.306690,0.479465,0.163756,-0.619657,-0.285746,0.252959,-0.346560,0.195986,0.691637,-0.344463,-0.256189,0.034360,-0.787736,-0.373512,0.113202,-0.125008,-0.033961,-0.220830,0.151077,-0.518179,-0.281217,-0.136639,-0.235649,0.197862,-0.033215,-0.228826,0.680465,-0.741680,0.301547,0.511976,-0.127569,-0.503626,0.433740,0.224354,0.000846,-0.095880,0.269865,-0.044880,0.230377,0.726140,0.450820,0.420271,0.250602,0.129003,-0.477449,0.538824', '1408130', '1294789', '26290398', '19899718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24857754', '吉屋出租：百老汇剧场版', '歌舞', '《吉屋出租》这部摇滚音乐剧在2006年的3月1日成为百老汇史上第七长寿的剧码，同时获得东尼奖及普立兹奖的肯定。这出音乐剧改编自普契尼的歌剧《波希米亚人》，剧情着重于一群穷困的艺术家和音乐家，即使在爱滋病的阴影下(在“波希米亚人”中是肺结核)仍在纽约的字母市挣扎努力生存。这出音乐剧的原声带是美国音乐剧界近三十年来最成功的录音，计有一套双碟的完整版，包含一首由史提夫·汪达演唱的混音版“Seasons of Love”，还有一套仅单张的精选辑。《吉屋出租》是百老汇音乐剧中，率先把同性恋、双性恋及跨性别等议题搬上舞台的，之前只要是触及这些议题的制作，都被归类至外百老汇(仅《一笼傻鸟》例外)。本片是2008年9月7日吉屋出租在百老汇演出的最后一场现场录制。', 'Will Chase', 'Michael John Warren', 9.3, 9891, 'tt1273675', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2037132488.jpg', 0.2, 0.8, 4.4, 22.1, 72.5, '0.131347,-0.204530,-0.440035,0.447537,0.171942,0.089880,0.325884,-0.144964,-0.239535,-0.006190,0.341012,0.746535,-0.278462,0.061035,0.270729,-0.258796,-0.219240,-0.410216,-0.239030,-0.254479,-0.103579,-0.197543,-0.196596,0.160773,-0.110389,-0.256421,0.746161,0.227742,-0.145765,0.250405,0.689515,0.126924,-0.128599,-0.085962,-0.006000,0.180620,0.164444,-0.078654,-0.131656,0.329255,-0.152866,-0.448713,-0.258662,-0.212651,-0.049894,0.224320,0.710373,-0.188544,0.264896,0.205656,0.714940,-0.273778,-0.310221,-0.186986,0.241495,0.104199,0.395929,0.395152,-0.178345,0.092239,-0.152101,-0.228062,-0.938480,-0.007767,0.253501,0.243826,-0.473228,0.565038,-0.149531,-0.061411,-0.083397,-0.086334,0.264889,-0.145056,0.348233,0.480434,0.000196,0.066152,-0.503101,0.492045,0.418958,-0.054901,-0.385768,0.484086,-0.063513,-0.596194,-0.133770,-0.448066,-0.269520,0.165498,0.218303,-0.135979,0.047067,-0.253937,-0.416023,-0.009482,0.032297,-0.628045,0.091069,-0.347117,-0.069087,-0.907725,0.038197,-0.095291,0.307575,-0.124271,0.383814,-0.406505,0.613946,-0.473346,0.331632,0.208960,0.125497,0.013484,0.885053,0.049000,0.133993,0.130179,-0.241400,0.043819,-0.047747,0.097226,-0.023785,0.422337,0.113073,-0.263615,-0.381221,0.646659', '3318306', '26275494', '2027945', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24857986', '定时拍摄', '科幻', '某座住宅区，负责公寓内各项维修事务的菲恩（Matt O''Leary 饰）和约瑟（George Finn 饰）是一对穷的叮当响的好基友。某天菲恩的女友凯莉（Danielle Panabaker 饰）来到他们的住处，当得知住在隔壁的贝先生已经很长时间没走出房门时，凯莉自告奋勇上门查看，结果却一脸错愕地回到二人面前。原来贝先生早已不见踪影，房间内一面墙贴满了以三个人为对象的拍立得照片，窗口则有一台奇怪的机器正对着菲恩和约瑟的房间。不久后他们发现，那台机器竟是可以拍摄到未来情景的照相机。他们发现了贝先生的尸体，然而因为照相机的原因秘藏了此事。无意间拥有了窥视未来的手段，年轻人们的心不知不觉躁动起来……©豆瓣', '丹妮尔·帕娜贝克', 'Bradley King', 7.2, 9084, 'tt2669336', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2188170587.jpg', 1, 5.4, 38, 42.7, 12.9, '0.417152,-0.047373,-0.656872,0.310746,0.172731,-0.379622,0.765143,0.276791,-0.440023,-0.671654,0.209842,0.614676,-0.381268,0.369801,0.369997,0.136063,-0.479032,-0.542035,-0.475074,-0.331124,-0.523649,-0.244357,-0.211610,-0.323495,-0.074206,-0.288040,0.325480,-0.108558,0.009338,0.429228,0.202767,0.171236,-0.266668,0.266044,-0.100234,-0.022774,0.198158,0.027890,-0.256621,0.083376,-0.108399,-0.203109,-0.157336,-0.032543,0.047060,0.321322,0.756064,-0.177439,-0.276063,0.205645,0.111562,0.023342,-0.052605,0.083992,0.510748,0.178999,0.184720,-0.165024,-0.397924,0.026385,0.160585,-0.132636,-0.544312,-0.101009,-0.004081,0.020853,-0.511014,0.211191,-0.252053,0.015330,0.100609,-0.673087,0.375654,0.261030,0.030005,0.669018,-0.145222,0.023631,-0.622411,-0.182725,0.214252,0.088088,0.081449,0.510228,0.097388,-0.499232,-0.008323,0.133353,-0.457196,-0.119437,0.614816,0.134906,0.082193,-0.111819,-0.526978,-0.151867,-0.259606,-0.254531,0.078989,-0.349569,-0.238507,-0.831578,-0.306314,-0.270873,-0.131001,0.268867,-0.373948,-0.107464,0.388914,-0.902939,0.219196,0.029899,0.132518,-0.190755,0.775091,-0.188801,0.141545,-0.148309,-0.269450,-0.037038,0.252918,0.554430,0.205668,0.319479,-0.216796,-0.382595,-0.577358,0.263431', '26951746', '1292272', '1297659', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24858414', '白雪公主杀人事件', '剧情', '某国家森林公园，一位美艳的OL被人残忍杀害。她身中十数刀后死亡，之后更被凶手泄愤般地纵火烧成焦炭。此案在日本国内引起轰动，由于死者三木典子（菜菜绪 饰）就职的公司生产了一款名为白雪的香皂，因此该案被网友称之为“白雪公主杀人事件”。供职于电视台的赤星雄治（绫野刚 饰）偶然接到前女友狩野里沙子（莲佛美沙子 饰）的电话，得知典子正是里沙子的职场前辈，死者生前不仅美丽光鲜，而且心地善良，乐于助人，宛如童话故事中的公主。赤星进而获悉，与典子同期入社的城野美姬（井上真央 饰）有着最大的嫌疑，而此人现已宣告失踪。为了获知真相，赤星单枪匹马对典子和美姬周围的人展开问询。看似接近真相的同时，双眼所及之处却愈加扑朔迷离……本片根据凑佳苗的同名原作改编。©豆瓣', '井上真央', '中村义洋', 7.5, 61521, 'tt3096712', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2176900061.jpg', 0.4, 2.6, 32.1, 51.2, 13.7, '0.302591,0.068380,-0.422884,0.405685,0.119123,0.124778,0.692748,-0.006167,-0.463084,-0.354428,0.259867,0.492054,-0.346696,0.193922,0.168550,-0.038544,-0.087131,-0.509809,-0.287935,-0.363145,-0.076095,-0.420435,-0.321387,0.031853,-0.083727,-0.102935,0.684150,0.287648,-0.237852,0.484261,0.188590,0.646893,-0.300783,0.151205,0.096169,-0.042613,0.060795,0.081331,-0.110379,0.334852,-0.184291,-0.449712,0.215276,0.123499,-0.345957,0.502056,0.682011,-0.323845,-0.116194,-0.389025,0.590784,-0.233522,-0.014340,0.288078,0.498990,0.093207,0.359253,0.362539,-0.388562,-0.069821,0.182900,-0.120056,-0.557448,-0.164761,0.401616,0.322913,-0.100229,0.124195,-0.271632,-0.079562,0.301975,-0.077865,0.206128,-0.165612,0.277440,0.243436,-0.145695,0.000050,-0.304394,0.314737,0.352366,0.074008,-0.155620,0.030259,-0.060852,-0.291160,0.171826,-0.186434,-0.032963,0.261825,0.331196,-0.058637,-0.031167,0.433799,-0.465365,-0.240182,-0.273068,-0.017829,0.011956,-0.020396,-0.381275,-0.646744,-0.111718,-0.357095,-0.213320,-0.096421,0.314003,-0.250602,0.546692,-0.647237,0.077006,0.294053,0.021223,-0.282000,0.155198,-0.017876,-0.021583,-0.084157,-0.283650,0.229061,0.465745,0.285864,-0.126518,0.070060,-0.204683,-0.374306,-0.549966,0.042230', '2369613', '10467125', '25774050', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24859034', '笔仙3', '悬疑', '因精神问题住院治疗的丽娜（江一燕 饰）丢失了部分记忆，她虽然没有结婚，却声称有一个怀胎十月生下的女儿小艾（荣益 饰）。丽娜的恢复情况良好，只差身为医学泰斗的爷爷徐东哲能够签字就可以出院。表情凄楚的丽娜再也无法忍受对女儿的思念，她想方设法从医院逃了出去，回到家中。然而奶奶口口声声说她从未生过孩子，丽娜却目睹爷爷和奶奶带着女儿开车逃走的一幕。谁知途中他们遭遇严重车祸，两位老人当场死亡，小艾则侥幸逃生。丽娜如愿见到了女儿，并且继承了爷爷留下的房产和遗物。她带着小艾来到远离城市喧嚣的别墅生活，快乐的时光并未持续太久，难以预料的恐怖则席卷而来……©豆瓣', '江一燕', '安兵基', 4.3, 9210, 'tt5040430', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187004396.jpg', 30.2, 34.5, 27.1, 4.9, 3.2, '-0.062173,0.015577,-0.658402,0.148427,-0.112719,-0.522050,0.787200,0.117447,-0.621265,-0.377192,0.346585,0.579835,0.073260,0.345718,-0.000633,0.050519,-0.345150,-0.179330,0.320253,0.095673,-0.126424,-0.205065,0.092805,0.037837,0.147560,-0.562634,0.420480,-0.172340,-0.011440,0.684538,-0.113812,0.086702,-0.236837,0.545178,-0.330277,0.417200,-0.038706,0.192006,-0.541350,0.186546,0.453844,-0.036773,-0.164615,0.119341,0.108519,0.232560,0.613089,0.071372,-0.316910,-0.033883,0.251797,-0.159242,-0.139255,0.358910,0.095880,0.004239,0.345942,0.401266,-0.402445,-0.224604,0.073167,0.099337,-0.439340,0.247138,0.138556,0.177306,-0.456934,0.411328,-0.401171,-0.127734,0.248014,-0.496436,0.302309,0.325120,-0.300508,0.635503,-0.426271,0.175614,-0.556251,0.164689,0.647927,-0.580964,-0.114331,0.402706,-0.118278,-0.183313,0.222819,-0.307554,-0.546546,0.357167,0.140154,0.282022,-0.528876,0.252295,-0.174692,-0.020199,-0.556551,-0.332756,0.078134,-0.313202,-0.273595,-0.092888,-0.070572,-0.040221,-0.410066,0.088449,-0.167624,-0.152210,0.629884,-0.552456,0.541383,0.215179,0.719277,-0.562663,0.516809,0.259568,0.088943,-0.270654,0.099070,0.558270,-0.336410,0.390839,0.238078,0.082115,-0.056758,0.008273,-0.309804,0.476201', '10355329', '34841067', '25721544', '4728342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24859095', '无人查收', '惊悚', '拥有一头金发的美女米兰达·威尔斯（裴淳华 Rosamund Pike 饰）是某医院的护士，她和同事们关系融洽，和善可亲。在预定好的相亲日子里，米兰达遭到送快递的小哥威廉·芬恩（希罗·弗南德兹 Shiloh Fernandez 饰）的强暴，从而身心遭到巨大创伤，生活偏离了常轨不说，还落下了手抖的毛病。在人生的最低潮，米兰达选择给正在狱中服刑的威廉写信，希望能见他一面。最初的几封信中，威廉都拒绝了对方匪夷所思的要求，不过他最终选择屈服。隔着一层玻璃，施暴者与受害者敞开心扉交谈。米兰达展现出圣母般温暖的笑容，威廉冰冷自卑的心仿佛被对方融化，对对方的欲望更加深了许多……©豆瓣', '裴淳华', 'Fouad Mikati', 5.5, 7516, 'tt2948790', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2249424956.jpg', 5.2, 30.4, 51, 9.7, 3.7, '0.297622,-0.028240,-0.541841,0.532091,-0.208101,-0.325700,0.977730,0.406910,-0.262675,-0.050038,0.256854,0.604473,-0.377305,0.274605,0.269259,-0.015312,-0.252343,-0.631561,-0.091183,-0.058049,-0.141590,-0.223286,-0.277347,-0.097750,-0.108100,-0.250637,0.339060,0.058413,-0.151085,0.308650,0.153133,0.224983,0.136407,0.532941,-0.288003,-0.059512,-0.097979,-0.119813,-0.135902,0.006897,0.322835,-0.117856,-0.057382,0.393377,-0.223415,0.544909,0.530361,-0.102078,-0.181509,-0.101545,0.272377,-0.217010,0.157416,0.460078,0.083036,0.196488,0.006674,0.156582,-0.169063,-0.004270,0.246082,-0.016791,-0.506067,-0.033526,-0.028176,0.184094,-0.301971,0.345849,-0.157457,0.174420,0.115678,-0.351724,0.016590,-0.081337,0.052925,0.406157,-0.225139,0.144338,-0.240303,0.071782,0.493289,-0.028558,-0.543979,0.258660,-0.610503,-0.273514,0.192349,-0.072900,-0.489425,-0.107427,0.361970,0.045888,-0.006654,0.236828,-0.636436,-0.171148,-0.470889,-0.109549,-0.313452,-0.385628,-0.060805,-0.619194,-0.435845,-0.427112,-0.396296,0.126813,-0.052374,-0.057789,0.525186,-0.497020,0.313654,0.383425,0.384757,-0.265011,0.490028,0.300147,-0.117759,-0.044384,-0.118636,0.581187,0.027206,0.193638,0.116218,0.377311,-0.127342,0.080896,-0.422051,0.446317', '1316693', '3097044', '1578663', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24859558', '哆啦A梦：新·大雄的大魔境', '动画', '又是一年暑假到来，胖虎（木村昴 配音）和小夫（关智一 配音）怂恿大雄（大原惠 配音），让他拜托哆啦A梦（水田山葵 配音）去寻找尚未被人类开发的秘境。在此期间，一条脏兮兮的小狗不请自来，它成功帮妈妈找到丢失的包，于是成了野比家的宠物，并得名扁扁。扁扁操纵卫星照相机拍到了神秘石像的照片，以此为契机，大雄、哆啦A梦、胖虎、小夫以及静香（嘉数由美 配音）组成了一支少年非洲密境探险队。他们一路上历经千辛万苦，更险些丢掉性命。而当离巨神像越来越近时，小伙伴们出乎意料发现了扁扁以及一个神秘王国的秘密。原本快乐的探险变成一场凶险的战争，他们能否拯救那个国家吗？本片根据藤子•F•不二雄同名大长篇漫画改编。©豆瓣', '水田山葵', '八锹新之介', 7.8, 11319, 'tt3949650', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2082462460.jpg', 0.5, 2.3, 29.1, 43.9, 24.2, '-0.223419,0.038712,-0.122350,0.224258,0.202739,-0.233825,0.176197,-0.052235,-0.085199,-0.151029,-0.099486,0.574450,-0.185701,0.093910,-0.069911,0.126779,-0.124371,-0.373788,-0.224211,0.053117,-0.237378,-0.111149,-0.141824,-0.079656,-0.017609,-0.274913,0.708788,-0.069662,-0.215289,0.186084,0.173651,0.225246,-0.472121,-0.177053,-0.121536,0.118628,0.018054,0.105071,-0.122168,0.042403,-0.518698,-0.005900,-0.079271,0.109723,0.020569,0.249996,0.644792,-0.431836,-0.272932,-0.379572,0.260880,-0.434252,-0.212804,-0.217144,0.310890,0.100787,0.170176,-0.095698,-0.214493,0.080835,0.071473,-0.424226,-0.722581,0.082889,0.060364,0.042451,-0.168050,0.128258,0.041885,0.100767,0.498807,-0.313163,0.237168,0.468207,0.434601,0.094489,-0.149374,0.251233,-0.134168,0.281984,0.504591,-0.130932,0.245455,0.380670,0.182955,-0.425638,-0.037426,-0.198614,-0.309316,0.272956,0.436273,-0.066079,-0.272502,0.084038,-0.765929,-0.028843,-0.299350,-0.204349,0.016595,-0.317938,-0.167092,-0.535245,0.163696,0.008455,0.115273,0.065371,0.136861,-0.358965,0.716899,-0.379293,0.059495,0.581170,0.154928,-0.007026,0.334018,-0.158661,-0.091001,-0.201239,0.087367,-0.006196,0.262259,0.141086,0.195595,0.069886,-0.044224,-0.217389,-0.571984,0.285265', '26290398', '26759820', '4181031', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24859795', '大力神', '动作', '王后阿尔克墨涅（罗姗妮·麦琪 Roxanne McKee 饰）无法忍受丈夫安菲特律翁（斯科特·阿特金斯 Scott Adkins 饰）对人民的残暴统治，向神祈求帮助，于是，她诞下了背负着推翻王权统治的责任的儿子赫拉克勒斯（凯南·鲁兹 Kellan Lutz 饰），可是，对于自己的使命，赫拉克勒斯一无所知。国王宠爱长子伊菲克勒斯（利亚姆·加里根 Liam Garrigan 饰），却对赫拉克勒斯嗤之以鼻。之后，赫拉克勒斯爱上了美丽的赫伯公主（盖娅·威斯 Gaia Weiss 饰），然而，国王却将河公主许配给了伊菲克勒斯。伊菲克勒斯虽然表面上待弟弟十分宽厚，背地却是个两面三刀的小人，为了能够和所爱的人双宿双飞，赫拉克勒斯决定同赫伯公主私奔，然而却被护卫拦下，等待着他的，将会是残酷的惩罚。©豆瓣', '凯南·鲁兹', '雷尼·哈林', 5, 17082, 'tt1043726', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2176698184.jpg', 13.9, 37.6, 38.1, 7.3, 3.2, '0.037794,0.489988,-0.525196,0.847120,0.203732,-0.525808,0.922567,0.182437,-0.305502,-0.236539,0.511379,0.785366,0.009832,-0.198202,0.379244,0.481581,-0.651218,-0.516538,0.190129,0.125427,0.066001,-0.387043,-0.049057,-0.353744,-0.161325,-0.741601,0.597773,-0.188115,0.301042,0.036367,0.514130,0.441662,0.224983,0.246582,-0.060245,0.095514,-0.183413,-0.328830,0.012424,0.224020,-0.133953,-0.051459,-0.209773,0.533563,0.035214,0.344906,0.201306,-0.950850,0.389180,-0.523823,0.352951,-0.525034,0.227129,0.393079,-0.049079,-0.249409,0.140726,0.386997,0.307208,-0.594164,0.416914,-0.273590,-0.717600,-0.029561,-0.025959,0.249759,-0.992644,0.667935,-0.432353,-0.041980,0.211216,-0.309618,0.001939,0.134341,0.315309,0.502778,-0.163397,-0.006491,-0.260681,-0.120234,0.364827,0.039496,-0.107095,0.073965,-0.494314,-0.475234,0.078601,-0.285568,-0.593368,-0.011759,0.398105,-0.030699,0.157351,0.640441,-0.196684,-0.592668,-0.875932,-0.014117,0.069713,-0.952938,0.115670,-0.084580,-0.020430,-0.552289,-0.186582,0.121236,0.248933,-0.215706,0.481541,-0.633675,0.352852,0.501089,0.368737,-0.586382,0.423177,0.110097,-0.174574,-0.403531,-0.007728,0.906680,-0.091412,-0.209456,0.023785,0.090363,0.121042,-0.388952,-0.118872,0.485869', '2131654', '6875263', '3157583', '3012819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24860289', '西葫芦的生活', '剧情', '男孩西葫芦（加斯帕德·施拉特 Gaspard Schlatter 配音）自幼被父亲抛弃，同母亲一起过着相依为命的生活。不幸的婚姻让母亲依赖酒精度日，常常苛责殴打西葫芦，可即便如此，在西葫芦的内心里，母亲依然是他最信赖的人。一场意外中，母亲从楼梯上跌落不幸死去，西葫芦成为了孤儿，亦背负上了杀死母亲的“罪名”，无处可去的他被送入了教养所。在那里，西葫芦结识了西蒙（波林·雅库 Paulin Jaccoud 配音）、爱丽丝（埃斯特尔·亨纳德 Estelle Hennard 配音）等孩子，他们虽然性格迥异，但都有着同样悲惨的遭遇。某日，教养所里新来了一个名为卡米尔（西斯汀·穆拉特 Sixtine Murat 配音）的女孩，她的出现瞬间吸引了西葫芦的目光。©豆瓣', '加斯帕德·施拉特', '克洛德·巴拉斯', 8.5, 28342, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2345382471.jpg', 0.2, 0.7, 12.6, 48.9, 37.6, '0.263171,-0.046203,-0.537070,0.577471,-0.099367,-0.324508,0.812263,0.354941,-0.474283,-0.069497,0.253974,0.785559,0.022936,0.510146,0.342847,0.155873,-0.234741,-0.503180,-0.134186,-0.289639,-0.514478,-0.450053,-0.225508,-0.161751,-0.098616,-0.267200,0.507658,-0.151297,-0.170690,0.550175,0.210178,0.161174,-0.157339,0.453223,-0.061454,0.238105,0.147170,0.007699,-0.069229,-0.047386,0.020658,-0.377263,0.093821,0.102268,0.015336,0.487206,0.588056,-0.449159,0.096776,-0.407553,0.221246,-0.215391,0.029020,0.204904,0.142310,-0.021963,0.271076,0.234742,-0.218515,-0.118032,0.173297,-0.108908,-0.435147,0.030255,0.143462,0.069004,-0.599212,0.578480,0.022399,0.065192,0.040299,-0.220458,0.241662,-0.057162,0.166999,0.617853,-0.225310,0.064790,-0.239799,0.017190,0.895960,-0.124464,-0.293547,0.101730,-0.413921,-0.276788,0.183200,-0.362784,-0.519020,0.064598,0.210592,0.039765,-0.194128,0.560485,-0.352944,0.016489,-0.171943,0.180091,-0.015529,-0.233721,-0.085660,-0.211128,-0.091414,-0.518284,-0.678873,0.006982,-0.054396,-0.352150,0.802614,-0.584262,0.324981,0.343185,0.362706,-0.058707,0.761739,0.129311,0.369459,0.110310,-0.034217,0.632078,0.074763,-0.009447,0.204334,0.169392,-0.195830,0.001207,-0.223229,0.500945', '25721544', '1292720', '30162520', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24860318', '但丁密码', '剧情', '《但丁密码》改编自丹·布朗2013年的小说《地狱》，讲述了符号学教授罗伯特·兰登（汤姆·汉克斯 Tom Hanks 饰）在意大利一所医院中醒来，发觉自己头部受到重创且失忆，同时还受到多组人马追杀，女医生西恩娜·布鲁克斯（费莉西蒂·琼斯 Felicity Jones 饰）帮助他逃出医院，寻回记忆，在这一过程中发现隐藏在但丁、米开朗琪罗等大师作品里的一个惊天阴谋，有极端邪恶的科学家妄图利用病毒把地球变成但丁《神曲》中描绘的地狱。', '汤姆·汉克斯', '朗·霍华德', 6.2, 88347, 'tt3062096', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2388072933.jpg', 1.6, 15.7, 59.1, 19.7, 3.8, '0.307463,0.065169,-0.427315,0.514057,0.191891,-0.050345,0.662275,-0.207225,-0.539405,-0.496991,0.211432,0.538543,-0.292692,0.193717,0.177132,0.185416,-0.345322,-0.396357,0.090814,0.014794,-0.429906,-0.410416,-0.542572,-0.170376,0.177754,-0.804899,0.336755,0.163073,-0.242710,0.338943,-0.205348,0.516542,-0.087968,0.196607,0.328117,0.422186,0.409964,-0.303235,-0.088092,0.583433,0.215904,-0.182739,0.126183,0.247879,-0.287212,0.103845,0.619167,-0.233038,0.272203,-0.092391,0.352912,-0.158396,-0.268254,0.138472,0.252384,0.124515,0.021317,0.179843,-0.206209,0.234871,-0.003275,-0.051700,-0.637992,-0.291943,0.093868,0.262159,-0.195907,0.052833,-0.182328,0.428031,-0.035949,-0.201674,0.072797,-0.095514,0.516033,0.418491,-0.032335,-0.236339,-0.517635,0.086792,0.171342,-0.630578,-0.268091,0.235480,-0.243294,-0.434355,-0.023718,-0.085814,-0.174760,0.129767,0.380819,0.031401,-0.317851,0.255386,-0.253347,-0.102344,-0.414761,-0.074304,-0.244811,-0.063965,-0.208785,-0.781256,-0.410623,0.102495,0.061017,-0.162160,-0.171320,-0.215998,0.536949,-0.390018,0.440732,0.508039,0.138880,0.042038,0.574960,-0.233857,-0.046526,-0.017845,0.002459,0.657587,0.264359,0.225223,0.001348,0.165020,0.199428,-0.106391,-0.283606,0.232941', '1316693', '1858678', '1291554', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24860563', '招魂2', '剧情', '故事发生在繁华的都市伦敦，佩吉（弗兰西丝·奥康纳 Frances O''Connor 饰）是一名家境十分贫寒的单亲妈妈，住在破旧的老房子里，独自抚养着三个孩子珍妮特（麦迪逊·沃芙 Madison Wolfe 饰）、玛格丽特（劳伦·埃斯波西托 Lauren Esposito 饰）和强尼（Patrick McAuley 饰）。最近，房子里出现的一些灵异现象让一家人陷入了恐惧和绝望之中，更糟糕的是，年纪最小的珍妮特似乎成为了恶灵附身的对象。教会的驱魔师劳瑞（维拉·法梅加 Vera Farmiga 饰）和艾德（帕特里克·威尔森 Patrick Wilson 饰）介入了此事，尽管他们十分同情这一家人，但两人的首要目的，则是探清此处灵异事件的真实性，然而，除了当事人的一些口述外，并没有确凿的证据证明这里真的发生了灵异事件，两人在无奈之中只有选择离去。©豆瓣', '帕特里克·威尔森', '温子仁', 7.9, 182758, 'tt3065204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2360924286.jpg', 0.4, 2.1, 24.2, 49, 24.4, '0.599756,-0.058021,-0.636029,0.365096,0.030262,0.042776,1.057374,0.017773,-0.709182,-0.587778,0.098388,0.738767,-0.130143,0.307595,0.213062,-0.037385,-0.425159,-0.415338,0.076355,-0.367192,-0.195644,-0.842363,-0.360833,-0.260516,-0.204888,-0.237313,0.468605,0.256765,-0.132496,0.429892,0.254813,0.591804,-0.280042,0.250639,-0.045738,-0.031054,0.125473,0.004049,-0.329631,0.174620,0.103300,-0.023696,-0.270775,0.308867,0.178934,0.381765,0.497646,-0.404445,-0.192062,0.121095,0.285124,-0.131626,-0.157097,0.107728,0.376127,-0.252257,0.426530,0.364043,-0.299995,0.097411,0.175109,0.055443,-0.635628,0.096900,0.338029,0.486660,-0.468489,0.413905,-0.042045,-0.307391,0.072329,-0.299814,0.478631,0.281299,0.143238,0.293873,-0.128174,-0.052824,-0.605109,-0.152908,0.578078,0.071033,-0.108806,0.171753,-0.511152,-0.396468,-0.157908,-0.092049,-0.463504,0.233993,0.182384,0.208052,-0.081930,0.398749,-0.546830,-0.049697,-0.197210,-0.241221,-0.295332,-0.292557,-0.019408,-0.554321,-0.128818,-0.457408,-0.456653,-0.182495,-0.072696,-0.265553,0.382749,-0.730933,0.115651,0.207173,0.197277,-0.213608,0.505496,0.112661,0.497086,-0.101602,-0.293488,0.253244,-0.046993,-0.014924,0.032969,0.321510,0.057108,-0.470694,-0.274928,0.450166', '10546747', '2002744', '1296534', '1301686');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24869803', '金橘', '剧情', '1990年的阿布哈兹战争期间，爱沙尼亚人伊福被迫留下了收获金橘，流血冲突打到了他家门口，一个受伤的男人留了下来，伊福被迫之下收留了他。', '连比特·乌尔夫萨克', '萨萨·乌鲁沙泽', 8.4, 8194, 'tt2991224', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2167417884.jpg', 0.2, 0.9, 12.8, 50.8, 35.3, '0.179478,0.297632,-0.635651,0.304103,-0.030286,-0.740027,0.449198,0.031293,-0.053401,0.204113,0.232686,0.457740,0.055885,-0.170370,0.307510,-0.310542,-0.176118,-0.389837,0.104414,0.129575,-0.568703,-0.130211,-0.316892,-0.186113,-0.320200,-0.483298,0.354241,0.562043,0.094944,0.536058,0.214816,0.190930,0.211903,0.460993,0.041532,0.636470,-0.097134,-0.415957,-0.091486,0.592231,-0.204863,-0.624493,0.078111,0.218429,-0.018124,0.661039,0.694733,0.020304,0.122368,-0.700942,0.022884,-0.157376,-0.297953,0.025117,0.429304,-0.206610,0.374508,0.258805,-0.507458,-0.335326,0.236306,0.435391,0.169647,-0.235582,-0.291423,0.105617,-0.869661,1.061009,0.033003,0.436962,-0.276418,-0.521006,0.090675,0.327072,0.140319,-0.261009,-0.317973,-0.054781,-0.774681,-0.061217,0.486740,-0.512317,-0.180657,0.345774,-0.373700,-0.308973,0.124434,-0.781733,-0.113498,0.154212,0.122992,-0.167399,-0.550737,0.155022,-0.460548,-0.352454,-0.474842,-0.409281,-0.055006,-0.312444,-0.128065,0.077488,0.070145,-0.191874,-0.912573,0.233850,-0.379070,0.183049,0.456135,-0.276866,0.450506,0.895916,0.570443,-0.037686,0.520410,0.161614,0.277132,0.339528,0.443577,0.133751,-0.209958,0.272378,0.551380,0.200880,-0.550674,-0.170586,-0.214985,0.298586', '1306505', '1303723', '1294737', '1296703');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24869824', '只要你说你爱我', '爱情', '东明高中的黑泽大和（福士苍汰 饰）是所有女孩崇拜追逐的对象，而他在一次意外遭遇后，偏偏对几乎没有人注意的女孩橘梅（川口春奈 饰）产生了兴趣。他自顾自将电话号码留给对方，偏巧小梅某晚被人跟踪，不得已打电话给黑泽，赶来解围的黑泽借机夺去了女孩的初吻。当年因某起事件，小梅封锁了自己的内心，可是阳光开朗的黑泽却蛮横地开启了她的心扉。随着交往时间的延长，他们对彼此的了解也越来越深。曾经单调的校园生活变得多姿多彩，当然悲伤和苦涩则成为恋爱之路上不可或缺的调味剂……本片根据漫画家葉月かなえ的同名原作改编。©豆瓣', '川口春奈', '日向朝子', 5.5, 11085, 'tt', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2176020740.jpg', 8.6, 30.4, 44, 12.1, 4.8, '0.362289,-0.044213,-0.710071,0.622072,-0.328009,-0.158612,0.809302,0.008177,-0.619926,-0.071109,0.182692,0.518449,-0.315669,0.061589,0.460689,-0.011692,-0.168329,-0.699135,0.026136,-0.065845,-0.035937,-0.439040,-0.403490,-0.040327,-0.092300,-0.377455,0.569200,0.018518,-0.311608,0.770686,0.114989,0.193634,-0.141237,0.703939,0.043296,0.254111,0.016922,-0.023381,-0.093773,-0.034078,0.047944,-0.352866,-0.124689,0.328616,-0.063143,0.575977,0.688770,-0.061492,-0.305322,-0.063198,0.471517,-0.279807,-0.204536,0.149262,0.191381,0.224054,0.288961,0.304072,-0.282852,-0.108421,-0.006390,0.127390,-0.732747,0.245328,0.094880,0.042446,-0.395089,0.588946,-0.123024,-0.199260,0.307437,-0.298348,0.192311,0.183658,0.411064,0.260698,-0.210633,-0.022775,-0.070757,0.065240,0.748187,-0.130704,-0.205326,0.584372,-0.290085,-0.246830,-0.067484,-0.038790,-0.474028,0.133076,0.347798,0.169390,-0.281267,0.266249,-0.518544,-0.095177,-0.101796,-0.193009,0.148041,-0.493629,-0.152266,-0.389395,-0.336063,-0.475381,-0.390441,-0.193785,-0.057201,-0.267016,0.748136,-0.886157,0.170471,0.586493,0.402812,-0.461808,0.503862,0.247707,-0.155239,-0.239090,-0.114195,0.237489,0.100129,0.359747,0.158342,0.347279,-0.181102,-0.069521,-0.408891,0.373097', '35030151', '1301022', '1308755', '1395231');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24870066', '我唾弃你的坟墓2', '惊悚', '美丽高挑却境遇不佳的模特凯蒂（杰玛·达兰德 Jemma Dallender 饰）四处寻找工作的机会，她偶然与一家工作是取得联系，短暂交流之后便于次日登门。谁知才拍摄没几张，摄影师伊凡（Joe Absolom 饰）便提出无理要求，不愿出卖肉体和灵魂的凯蒂当即离开。本以为这段糟糕的经历已告一段落，结果第二天夜晚，伊凡唯唯诺诺的助手乔治（Yavor Baharov 饰）闯入她的公寓，对其进行了无情凌辱与虐待，并且残忍杀害了闻讯赶来的邻居杰森（Michael Dixon 饰）。事后，乔治求助伊凡和尼基（Aleksandar Aleksiev 饰），三人决定嫁祸凯蒂，隐瞒真相。女孩的命运系在三个变态手中，在走投无路之际，唯有依靠自己的双手惩罚恶徒，逃出生天……©豆瓣', '杰玛·达兰德', '史蒂文·R·蒙若尔', 6.4, 20419, 'tt2537176', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2105110324.jpg', 2.7, 14.8, 50.6, 22.6, 9.3, '0.151894,0.011289,-0.596353,0.346947,-0.158517,-0.342707,0.590055,0.066559,-0.364161,-0.457910,0.278878,0.536097,-0.231084,0.044345,0.387276,0.023155,-0.428422,-0.742001,0.113260,-0.057837,-0.146452,-0.554082,-0.184866,-0.330406,0.075706,-0.305845,0.288075,-0.077535,-0.276452,0.517105,0.267086,0.276833,-0.202946,0.448397,0.056340,-0.097862,0.244459,0.060714,-0.406341,0.156578,0.022529,-0.267171,-0.044935,0.268918,0.025303,0.430076,0.703014,-0.384463,-0.303918,-0.192845,0.277446,-0.197497,-0.075851,0.347653,0.162019,0.010100,0.287357,0.232794,-0.512177,-0.070889,0.073498,0.042184,-0.523366,0.204285,0.020313,-0.124289,-0.347022,0.355763,-0.334132,0.188508,0.178015,-0.544983,-0.055157,0.390747,0.238143,0.170455,0.023168,-0.024936,-0.177442,0.261355,0.459930,0.046946,0.032273,0.233299,-0.050486,-0.129921,0.141168,-0.126552,-0.339791,-0.083264,0.399188,0.181825,-0.212702,0.073590,-0.230546,-0.415125,-0.726457,0.064236,0.170019,-0.394814,-0.099307,-0.800931,-0.111980,-0.092890,-0.383937,0.096455,0.021187,-0.123600,0.435034,-0.548715,0.316023,0.347266,0.350447,-0.467625,0.471324,0.188197,0.193310,-0.260485,0.077269,0.280066,0.122731,0.221244,0.158593,0.071100,0.134930,-0.072208,-0.244247,0.128972', '1298197', '1305249', '7916027', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24870808', '修女艾达', '剧情', '1962年的波兰。安娜是一名在修道院长大的孤儿。在宣誓正式成为修女之前，她离开了修道院，去见世上剩下的唯一亲人旺达。旺达告诉安娜，她是犹太人。两名女子踏上了一段旅程，不仅将发掘属于她们家族的悲剧，而且将找到她们自己真正的归属。她们开始质疑之前的信仰，质疑之前生活中所信任的一切。安娜和旺达都想继续活下去，但是当中只有一个人能做到。', '阿伽塔·特泽布霍夫斯卡', '帕维乌·帕夫利科夫斯基', 7.8, 15532, 'tt2718492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2177327412.jpg', 0.4, 2, 25.2, 51, 21.4, '0.281560,0.229135,-0.648771,0.564794,-0.299318,-0.283815,0.646854,-0.478439,-0.541408,-0.409984,0.224667,0.951819,0.262991,0.390186,0.177356,-0.054490,-0.397211,-0.741829,0.047654,-0.450087,-0.468851,-0.697105,0.028434,-0.092616,-0.304570,-0.532887,0.845728,0.160788,0.038216,0.348066,0.074119,0.015626,-0.013745,0.207718,-0.109199,-0.081384,0.230567,-0.178348,-0.688241,0.291256,0.016056,0.192199,-0.190347,0.403532,-0.011358,0.190351,0.411633,-0.531885,-0.030407,-0.228614,0.222317,-0.199333,-0.094593,0.378559,-0.023188,-0.022199,0.148892,0.537521,-0.196901,-0.099239,-0.136923,-0.215616,-0.704906,0.011583,0.038473,0.157917,-0.633338,0.338798,0.205329,-0.257936,0.307635,-0.307327,0.332840,0.346391,0.243861,0.512539,-0.359628,0.127007,-0.818113,0.104244,1.076488,-0.235541,-0.267210,0.249979,0.146893,-0.285738,-0.130194,-0.170137,-0.479110,0.230150,-0.194393,0.334000,-0.193166,0.085938,-0.520324,0.063334,-0.367938,-0.343348,0.368340,-0.747340,-0.074892,-0.455188,-0.045287,-0.015998,-0.498659,-0.065916,-0.020054,-0.804643,1.013375,-0.811520,0.408600,0.457614,0.757427,-0.705879,0.832705,-0.122126,0.391522,-0.258794,0.012835,0.834317,0.175940,0.112535,0.144572,0.074431,-0.159623,0.070468,-0.292488,0.497014', '25721544', '35048413', '27624661', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24872023', '贵族大盗', '喜剧', '表面看来，查理（约翰尼·德普 Johnny Depp 饰）是一位事业有成，春风得意的艺术品商人，家中有娇妻乔安娜（格温妮丝·帕特洛 Gwyneth Paltrow 饰）坐镇，日子过的如鱼得水。然而，他有着一个不为人知的秘密，每当夜幕降临，查理便会摇身一变，成为专门偷窃艺术品的大盗，这双重身份由来已久，却也从未露出过马脚。某日，一名专门修复戈雅作品的画匠无故死亡，他手中的天价艺术品神秘失踪，当局悬赏巨额，希望能够寻回此画，这赏金后头的一连串“零”让查理不由得心动起来，遂和搭档展开了一场充满了刺激和危险的旅途。在应付一连串怪人的同时，查理亦要提防名为马特兰（伊万·麦克格雷格 Ewan McGregor 饰）的男子，因为他不仅是英国军情五处的探员，还是同查理积怨已久的情敌。©豆瓣', '约翰尼·德普', '大卫·凯普', 5.4, 27053, 'tt3045616', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2233840624.jpg', 8.8, 31.8, 44.8, 10.7, 3.9, '-0.054252,-0.186961,-0.429680,0.651338,-0.121613,-0.202198,0.895667,0.011940,-0.662312,-0.359021,0.383843,0.729588,-0.372912,0.154661,0.423181,0.191300,-0.247097,-0.443753,0.037506,-0.402212,0.042715,-0.268371,-0.662059,-0.220241,-0.080438,-0.274561,0.461427,0.047285,-0.195871,0.608777,0.395215,0.512873,-0.082512,0.361014,-0.144735,-0.120336,0.297169,0.106793,-0.298266,0.022244,0.051319,-0.171469,-0.093676,0.295896,-0.079272,0.405094,0.341432,-0.217620,-0.127332,0.092208,0.366238,-0.155712,0.244665,0.019540,0.329113,0.056699,0.099305,0.098387,-0.297266,0.058128,0.373986,-0.083315,-0.794624,0.035749,0.176939,0.238035,-0.288989,0.252245,-0.272615,0.151350,-0.065946,-0.166661,0.204829,0.255433,0.198330,0.185903,0.033777,0.008370,-0.573100,0.380579,0.261180,0.063113,-0.164398,0.173685,-0.235317,-0.428674,-0.003865,-0.239396,-0.392951,-0.095353,0.478543,-0.064228,0.116759,0.342581,-0.574425,-0.087250,-0.416100,0.083071,-0.061869,-0.095800,-0.086160,-0.727430,-0.227441,-0.494646,-0.330263,0.109531,0.222311,-0.233470,0.526535,-0.681020,0.216848,0.645725,-0.005506,-0.348124,0.434145,0.216166,0.080914,-0.213717,-0.258682,0.219113,0.080215,-0.010624,0.019678,0.245842,0.065231,-0.442897,-0.098489,0.504201', '1301686', '1316693', '3005387', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24872189', '托尼·厄德曼', '剧情', 'Inès在一家位于布加勒斯特的德国大型企业工作。她的生活一直井然有序，直到她的父亲Winfried突然造访，并向她提出了这个问题：“你幸福吗？”面对这个根本无法回答的问题，她的生活开始出现一系列翻天覆地的变化。她并不喜欢自己的父亲，甚至有点以他为耻，但他却通过捏造一个名叫Toni Erdmann的诙谐人物，试图为她的生活找到一个方向。', '彼得·西蒙尼舍克', '玛伦·阿德', 7.6, 24331, 'tt4048272', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2356781122.jpg', 1.2, 4.9, 28.4, 44.1, 21.4, '0.328060,0.154659,-0.804014,0.908575,-0.278955,-0.200388,0.925242,-0.032659,-0.567164,-0.604072,0.009656,0.906566,0.201632,0.196782,0.153306,0.173207,-0.116586,-0.716834,0.277312,0.226232,-0.257164,-0.412702,-0.142303,-0.579785,-0.169779,0.104351,0.706711,0.003868,-0.208773,0.110019,0.011350,0.352673,0.171849,0.891656,-0.331163,-0.137069,-0.127546,0.218360,-0.169355,0.219106,0.033553,-0.332720,-0.192395,0.584585,-0.246818,0.577881,0.523254,-0.310770,-0.619304,0.060352,0.455786,-0.425966,-0.050709,0.159296,-0.010631,-0.236629,0.000776,0.128490,-0.275196,0.217898,-0.181429,-0.221734,-1.098718,-0.251127,-0.049854,0.286488,-0.456016,0.213780,-0.041907,-0.345006,0.024854,-0.496615,0.047683,0.621989,0.292870,0.389290,-0.742384,0.140184,-0.502693,0.023638,0.753961,0.215478,-0.434473,0.606540,-0.269325,-0.496837,-0.163312,-0.041269,-0.454692,-0.016048,-0.209407,0.140164,-0.232027,0.074383,-0.574372,0.149936,-0.013326,-0.478022,0.133370,-0.584895,-0.072453,-0.392971,0.109416,-0.382343,-0.447865,-0.177804,-0.260168,-0.470759,0.415199,-0.979850,0.018684,0.583333,0.375470,-0.968530,0.463106,0.316544,0.035679,-0.429055,-0.436749,0.408969,-0.189975,0.394165,-0.360110,0.254357,0.486385,-0.103142,-0.288378,0.690526', '1304977', '3670447', '6080756', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24873473', '疯狂72小时', '喜剧', '七年前的婚礼上，许三娜（阎妮 饰）的父亲，伍波（耿乐 饰）的准岳父实在看不上将来的女婿竟是一个一文不名的穷光蛋，大婚当天伍波落荒而逃，婚礼现场留下了目瞪口呆的亲朋和傻掉的新娘。逃婚后伍波立下宏愿，一定在短时期内创业成功，挣大钱住豪宅，让羞辱过自己的人看看，怎奈商场如战场，几年打拼下来，钱没赚到反而负债累累，走到了濒临自杀的地步。回过头来看三娜，当初伍波逃婚令她蒙羞，她发誓一定要嫁入豪门，但七年过后，高不成低不就的三娜仍待在闺中，成了年逾三旬的剩女。七年后，当初的冤家竟莫名做了邻居......©豆瓣', '闫妮', '李继贤', 4.7, 11323, 'tt4799538', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2183027701.jpg', 22, 35.9, 32.6, 6.3, 3.1, '-0.208839,-0.089609,-0.598692,0.119578,-0.221930,-0.558799,0.226826,0.090198,-0.445929,-0.103246,0.258024,0.718009,-0.424177,0.472667,0.446334,-0.064932,0.186593,-0.615392,-0.188921,-0.296041,-0.003663,-0.235882,-0.057481,-0.112579,-0.005445,-0.142427,0.539265,0.173873,0.262646,0.310649,0.250015,-0.028740,0.153799,0.245506,-0.417748,0.179320,-0.114098,0.448327,-0.354130,0.017402,0.017266,-0.296079,0.034912,-0.087826,0.157836,0.139578,0.369801,-0.068414,-0.096125,-0.171694,0.629629,-0.082056,-0.293355,0.326031,0.196657,-0.141199,0.238989,0.377327,-0.268491,-0.069840,0.221387,-0.125237,-0.339652,0.161946,0.125657,-0.370378,-0.914666,0.444195,-0.089983,0.048387,-0.170756,-0.155266,0.221527,0.434164,0.041406,0.510966,-0.370601,0.165868,-0.664201,0.490420,0.822442,0.071087,-0.110258,0.168265,0.255354,-0.302578,0.095926,-0.515425,-0.501235,0.198662,0.123171,-0.031130,-0.346089,0.183865,-0.164334,-0.349202,-0.398854,0.013236,0.246005,-0.436406,-0.326948,-0.124807,-0.191626,-0.210873,-0.251465,0.210869,0.084825,-0.370814,0.242487,-0.359116,0.161406,0.264511,0.392034,-0.670491,0.676027,0.073208,0.191493,0.126521,-0.079175,0.103948,-0.095120,0.395120,0.123301,0.021276,-0.260657,-0.124389,-0.116569,0.495197', '1306505', '1308035', '2080130', '30276726');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24874401', '各有少年时', '喜剧', '该片背景设置在80年代，讲述刚刚进入大学的新生Jake和他的棒球部队友们在一个周末里所经历的故事。影片与导演此前作品《年少轻狂》风格类似，时间上也是“接续”的关系。', '威尔·布里顿', '理查德·林克莱特', 6.7, 8254, 'tt2937696', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2299152872.jpg', 2.2, 10.4, 46, 31.2, 10.3, '0.296360,-0.010625,-0.443189,0.783541,0.217809,0.129002,0.744209,-0.123058,-0.678877,-0.683757,0.034841,0.524602,-0.310015,0.354833,0.268686,-0.404559,-0.518087,-0.779392,0.140686,-0.353831,-0.096777,-0.553650,-0.227694,0.111539,0.136610,-0.706526,0.859135,-0.090454,-0.555475,0.592862,0.033059,-0.128830,-0.403537,0.186158,-0.109957,-0.008642,0.143352,0.515309,-0.486114,0.040890,-0.140555,-0.319403,-0.080977,-0.146450,0.132236,0.421437,0.800576,-0.082403,-0.300448,0.230087,0.503535,0.096556,-0.264047,0.022234,0.529489,0.259130,0.833106,0.573422,0.246643,0.468345,-0.615294,-0.598057,-0.621256,-0.304781,0.045361,0.239667,-0.535752,0.765776,-0.071774,0.022996,-0.134678,-0.382960,0.318038,0.019889,0.581843,0.502871,0.014986,-0.031417,-0.148578,0.486974,0.948189,0.062141,-0.052608,0.675816,-0.128902,-0.468398,-0.648979,-0.075728,-0.635873,0.483858,-0.316588,-0.230763,-0.144699,0.319328,-0.851685,0.390609,0.193629,0.093829,0.197191,-0.278229,0.062592,-0.845821,-0.325019,-0.510874,-0.331026,-0.288477,0.123717,-0.500725,0.981953,-0.988416,-0.070515,0.307554,0.355734,-0.259418,0.953772,0.302654,0.180926,-0.235454,0.167924,0.142673,-0.219378,0.082087,-0.543293,0.566096,-0.125545,-0.696113,-0.493838,0.720633', '3811356', '1826173', '25922902', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24875409', '奎迪', '剧情', '从严格意义上来讲，《奎迪》也许不能算是《洛奇》的续作，而是另一部衍生作品。故事将以曾被洛奇打败的重量级拳王阿波罗·奎迪的儿子为主角，影片的片名也源于此。这位出身上流社会的年轻人具备与生俱来的拳击天赋，立志成为拳王的他却遭到家人的反对。他于是找到了已经退出拳击界并且无意回 归的洛奇（史泰龙饰）来担任自己的教练。', '迈克尔·B·乔丹', '瑞恩·库格勒', 7.6, 33146, 'tt3076658', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2321788979.jpg', 0.4, 2.2, 31.2, 49, 17.2, '0.500708,0.204195,-0.485258,0.796090,-0.262589,-0.201850,0.367192,0.051483,-0.468010,-0.505050,0.401426,1.002449,0.186619,-0.062909,0.217583,0.062232,-0.162237,-0.519522,0.006640,-0.085832,-0.031860,-0.301060,-0.206052,0.207672,-0.193566,-0.331019,0.986438,-0.281196,-0.707614,0.308151,0.309732,0.604188,0.214856,0.158056,-0.228217,0.197397,-0.166725,0.034830,-0.460922,0.402399,0.175807,-0.064345,-0.193715,0.151586,-0.167774,0.287853,0.375788,-0.290809,0.083025,-0.024176,0.679049,-0.347437,-0.043156,0.120242,0.260452,0.232451,0.234690,0.325983,0.287722,0.231771,0.137296,-0.233217,-1.150725,-0.162368,0.376620,0.038166,-0.646927,0.539897,-0.194193,-0.227227,-0.191399,-0.038996,-0.021603,-0.105925,0.184250,0.060300,0.008141,0.144924,-0.412335,0.203015,0.620778,-0.109456,-0.325848,0.267207,0.049610,-0.600079,-0.126295,-0.554707,-0.302999,0.179667,0.255463,0.146073,-0.041567,0.142544,-0.566621,-0.050614,-0.266039,-0.154193,0.068668,-0.264068,0.042346,-0.527683,-0.061428,-0.108491,-0.171714,-0.316136,0.279851,-0.449478,0.858600,-0.994166,0.221834,0.298945,0.193266,-0.450625,0.765598,0.062667,0.134266,-0.416134,-0.158615,0.259786,0.141764,0.216618,-0.030481,0.213835,0.068000,-0.419525,-0.179266,0.735787', '25880986', '27602116', '1793491', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24875534', '十二公民', '剧情', '某高校模拟法庭，正就社会上不久前发生的一起真实案件展开辩论。案件的嫌疑人是某房地产商收养的富二代，其生父是来自河南的务工人员。案发当晚，有人听到富二代和其生父发生激烈争吵，随后生父被人在家中杀害。学生们围绕嫌疑人是否有罪展开激烈辩论，而他们的父亲作为陪审团观摩整个法庭的审判过程。休庭期间，12名陪审员被带到另一个房间展开讨论，他们必须在一个小时内得出结论，而且需要全票通过嫌疑人是否有罪。这些人来自各行各业，有着不同的背景。大家普遍希望尽快敷衍了事，谁知第一轮投票过后，只有8号陪审员（何冰 饰）认为嫌疑人无罪。有的人暴跳如雷、有的人奚落戏谑、有的人摇摆不定、有的则固执己见。这是一场关于良心和道义的鏖战……本片根据经典影片《十二怒汉》改编。©豆瓣', '何冰', '徐昂', 8.4, 344468, 'tt3431598', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2242220716.jpg', 0.6, 1.5, 13.2, 46, 38.8, '0.333197,-0.133720,-0.654807,0.399578,-0.031187,0.329874,0.610268,0.053318,-0.666092,-0.302202,0.461957,0.479815,-0.323245,0.287248,0.277806,-0.435928,-0.545667,-0.763498,-0.072249,-0.241838,-0.331172,-0.753307,0.276003,-0.285890,0.045909,-0.115073,0.505228,-0.003981,-0.232901,0.119234,0.401645,0.470306,-0.505431,0.291629,-0.065544,-0.084316,0.167831,0.095700,-0.514053,0.081050,-0.156115,-0.069392,-0.212903,-0.225389,-0.060983,0.458912,0.517976,-0.251798,-0.341544,0.025982,0.608911,-0.299447,-0.246633,0.220152,0.621951,0.187334,0.344984,0.443927,0.088715,-0.086769,-0.129032,-0.065924,-0.848616,-0.224984,0.291500,0.326181,-0.050496,0.478472,0.003590,0.035164,0.033210,0.124380,0.111178,0.441395,0.272419,0.287440,0.082284,0.008084,-0.402875,0.154831,0.737630,0.118531,-0.423072,-0.202893,-0.172826,-0.504276,0.196570,-0.300267,-0.105380,0.107286,0.214357,0.157766,-0.102523,0.126785,-0.242885,-0.034461,0.076894,-0.327737,0.278779,-0.361463,-0.156924,-0.658316,-0.152855,-0.275647,-0.142175,0.071090,0.157756,-0.283547,0.844854,-0.850267,0.104423,0.378210,0.374803,-0.528459,0.690641,0.315033,0.175080,-0.268191,-0.291684,-0.264451,0.433629,0.234478,-0.034762,0.066038,0.017738,-0.172307,-0.257928,-0.063851', '4301278', '1874704', '1293989', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24877005', '伊丽莎白', '剧情', '呈现在这部音乐剧作品中的奥地利皇后伊丽莎白（1837-1898），远远超前于她所在的时代，是一位为个人自 由而不懈抗争的女性。但不幸的是，她身处于一个注定走向衰亡的旧世界，因此这种“现代性”将她引向了令人绝望的孤立境地。她的身上体现了日渐腐朽的哈布斯堡王朝的悲剧命运。意大利无政府主义者路易季·卢凯尼对她的暗杀是一件具有象征性意义的事件，它预示着一个千年之久的历史时代即将宣告终结。', '玛雅·哈克福特', 'Sven Offen', 9.6, 7860, 'tt0806061', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264336223.jpg', 0.3, 0.2, 1.9, 13.8, 83.8, '0.196180,0.470930,-0.718731,0.756202,-0.208887,0.140964,0.731782,0.049357,-0.577545,-0.113402,0.302800,0.811844,0.025943,0.150455,0.541707,-0.113780,0.196155,-0.723036,-0.219903,-0.058262,-0.561560,-0.324812,-0.558772,-0.441828,-0.567595,-0.334441,1.209953,0.543790,-0.530946,0.049477,0.351640,0.543276,0.072614,0.471725,-0.111319,-0.115692,-0.009608,-0.120939,-0.257299,0.277802,0.083719,-0.486785,-0.167104,0.552376,-0.614404,0.195487,0.627916,-0.612410,-0.022251,-0.271353,0.907369,-0.437219,-0.357151,0.238495,0.415063,0.016038,-0.313786,0.337822,0.089125,-0.296277,0.232821,-0.121473,-1.023605,-0.214774,0.099923,0.275079,-0.516620,0.705730,0.003080,-0.028230,-0.001533,-0.333102,0.317688,0.286125,0.510282,0.440617,-0.079333,-0.218804,-0.478737,0.334083,0.598853,0.161584,-0.687921,0.337545,-0.596659,-0.418678,-0.335784,-0.455280,-0.672142,-0.170369,0.337807,0.012057,0.062051,0.625560,-0.677617,-0.007923,-0.221019,-0.204925,-0.006848,-0.487620,0.077433,-0.300272,-0.334440,-0.680547,-0.077375,-0.092858,0.043881,-0.465504,0.751474,-0.605230,0.376767,0.482298,0.052672,-0.458239,0.719450,-0.090690,0.316066,-0.215513,0.109655,0.725991,-0.209142,0.017158,-0.127426,0.292571,0.222402,0.108158,-0.376246,1.021229', '26759820', '26667010', '1306795', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24879816', '计划男', '喜剧', '韩正锡（郑在泳 饰）是一个不喜欢变化的男人，生活中无论大事还是小事，正锡都会仔细的将它们记录在自己的计划表之中，并且严格按照计划表进行自己的人生。除此之外，正锡还拥有着远远超越了正常范畴的洁癖，如何在这个充满了细菌和病毒的世界里生存下去成为了正锡最大的课题。正锡龟毛的个性让他吃了不少的苦头，其中最令其耿耿于怀的就是年纪一大把却依然单身的悲惨事实。一次偶然中，正锡遇见了名为李智媛（韩智敏 饰）的女孩，智媛的活泼和开朗吸引了正锡的注意，但令正锡感到抓狂的是，生活中的智媛竟然是个大大咧咧邋里邋遢的姑娘。性格上的截然相反并没能熄灭正锡心中的爱情火花，有笑有泪的恋爱喜剧就此拉开序幕。©豆瓣', '郑在泳', '成时翕', 7.4, 12986, 'tt3696210', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2174394255.jpg', 0.5, 3.8, 36.5, 44.2, 15.1, '0.341140,0.256279,-0.773199,0.521223,-0.429820,-0.054721,0.962801,-0.012124,-0.486613,-0.038296,0.064123,0.628311,-0.157204,0.278873,0.034992,-0.082710,-0.142507,-0.709177,-0.136173,-0.050288,-0.445831,-0.347629,-0.435685,0.020185,-0.281650,-0.293137,0.553019,0.091782,-0.298749,0.356879,0.354240,0.107269,0.206063,0.620748,-0.213045,-0.026123,-0.068338,0.015348,0.146673,-0.010145,0.179159,-0.283286,-0.042038,0.511012,-0.102650,0.393282,0.650757,-0.426725,-0.415435,-0.037872,0.501992,-0.227005,-0.245064,0.096182,0.131332,0.027970,0.109264,0.124711,-0.295085,0.119610,0.020427,0.020573,-0.962086,-0.345818,0.267957,0.291052,-0.577253,0.532388,0.147906,-0.406546,0.083553,-0.263297,0.279745,0.067314,0.417878,0.394511,-0.222330,-0.083757,-0.403899,0.145531,0.598642,0.278599,-0.443582,0.454568,-0.656376,-0.440002,-0.118203,-0.553012,-0.414976,0.192469,0.011235,0.123952,-0.226018,0.333918,-0.534199,0.393439,-0.081636,-0.218699,-0.115516,-0.452204,-0.322858,-0.228982,-0.226039,-0.828192,-0.586679,0.023750,0.094573,-0.596486,0.920147,-0.871699,-0.034354,0.402065,0.072232,-0.327053,0.748765,0.348480,0.022818,-0.146357,-0.055299,0.124366,-0.194244,0.051474,-0.064220,0.620429,0.008756,-0.277640,-0.425060,0.772586', '24756472', '35158375', '26283288', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24879819', '海盗', '动作', '《海盗》以朝鲜建国初期为背景，讲述了为了捕获一只吞掉玉玺的鲸鱼而分开陆地的一伙男山贼和一群女海盗在茫茫大海上的新奇遭遇。该片是韩国首部海洋冒险题材影片。', '金南佶', '梨晳勳', 6.7, 14075, 'tt3485166', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2188692873.jpg', 2, 11.3, 49.3, 26.7, 10.7, '0.150213,-0.260992,-0.524854,0.826489,0.490097,0.015456,1.034715,0.035416,-0.426662,0.218815,0.280652,0.830648,0.046725,-0.354625,0.183663,0.289025,-0.269994,-0.436811,-0.266630,-0.103397,-0.103235,-0.112579,-0.684682,-0.335828,0.031729,-0.214186,1.129862,-0.186578,-0.463824,0.436726,0.654452,-0.057664,-0.382313,0.077543,-0.316648,-0.128038,-0.298850,0.097223,-0.302350,0.209174,-0.622546,-0.117721,-0.069259,-0.054100,-0.288737,0.078159,1.110667,-0.244669,0.161673,-0.434834,0.351843,-0.616962,-0.026718,-0.360682,0.697757,0.046295,0.127784,-0.191539,0.248419,-0.054284,0.071976,-0.036359,-0.728351,-0.105865,-0.015664,0.385571,-0.404675,0.208940,0.352292,0.012287,0.130413,-0.384780,0.207072,0.257899,0.419997,0.263186,0.137141,0.128370,-0.465142,0.545008,0.797963,-0.009957,0.025942,-0.049572,-0.122602,-0.406825,-0.067836,-0.256388,-0.401994,-0.091488,0.443751,-0.429562,-0.637853,0.330967,-1.111258,0.084297,-0.169742,-0.258052,-0.030878,-0.273785,-0.077332,-0.704671,-0.087794,-0.324615,0.128675,-0.154303,0.381539,-0.094663,0.827421,-0.342235,-0.167566,0.990342,0.140424,-0.381482,0.644274,0.014226,-0.082612,-0.049763,-0.072590,-0.078517,0.498150,0.082232,-0.052624,0.187967,-0.209675,-0.247286,-0.226695,0.125856', '26290398', '1467779', '21619567', '1856675');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24879820', '奇怪的她', '喜剧', '经营咖啡店的坏脾气老奶奶吴末顺（罗文熙 饰）自持有一个孝顺的教授儿子（成东日 饰）而处处霸道，除了少年时期的老佣人朴老头（朴仁焕 饰）真心对她好，朋友们都讨厌她，包括她的儿媳。一次儿媳住院，全家除了孙子智河（郑真英 饰）不同意，别人都觉得该送奶奶去老人院。末顺奶奶失落之 时想去照相馆拍张遗照，没想到这一拍竟然变成了年轻的模样。年轻的末顺改名吴斗丽（沈恩敬 饰），开始了新的生活，甚至重拾了年轻时的梦想——当歌手。斗丽特立独行却受到了大家的欢迎，甚至吸引了电视台导演（李真旭 饰）的倾慕，可是她的身份却面临着被揭穿的威胁，该留在20岁享受人生，还是重回正轨面对生活，末顺做出了艰难的抉择。©豆瓣', '沈恩京', '黄东赫', 8.3, 176698, 'tt3516378', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2162863558.jpg', 0.2, 1.1, 15.4, 48.9, 34.5, '-0.095407,0.043536,-0.506275,0.397723,-0.384711,-0.432499,0.431485,0.403547,-0.278661,-0.352193,0.346036,0.551912,0.013746,0.451072,0.309068,-0.032747,-0.025995,-0.426961,0.009984,0.140024,-0.177052,-0.045972,-0.052749,-0.211837,-0.152038,-0.151284,0.275402,-0.027248,-0.051080,0.285220,0.423430,0.022617,0.241529,0.355959,-0.137002,0.075475,0.033953,0.121360,-0.244664,-0.222764,0.097538,-0.078300,-0.128560,0.154552,0.121840,0.316665,0.573428,-0.086988,-0.377647,-0.058446,0.551820,-0.155433,-0.057677,0.337568,0.031211,0.052562,0.087522,0.005881,-0.112032,-0.008403,0.048860,-0.156260,-0.538215,0.124800,0.271725,-0.053635,-0.581735,0.355034,-0.099444,-0.146727,-0.013909,-0.357253,0.102346,0.126214,-0.006212,0.543061,0.005434,0.238487,-0.214103,0.440239,0.672714,-0.038999,-0.278096,0.288320,-0.165951,-0.159497,0.169031,-0.422986,-0.764224,0.215329,0.045406,-0.144486,0.041440,0.051893,-0.241554,-0.149350,-0.123638,-0.091528,0.366174,-0.412806,-0.098448,-0.245980,-0.030457,-0.400305,-0.288219,-0.005999,0.100373,-0.200321,0.865579,-0.690697,0.218286,0.321569,0.254562,-0.823273,0.649996,0.279329,-0.142133,-0.188167,-0.151787,0.131047,-0.102190,0.113221,0.043464,0.136109,-0.110729,-0.299788,-0.154849,0.281918', '1877596', '6963575', '26348103', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24879839', '道士下山', '喜剧', '动荡的时代下，武功高强的道士何安下（王宝强 饰）被师父（李雪健 饰）送下山自谋生路。不谙世事的他来到大千世界，因抢了荷叶鸡而拜入医生崔道宁（范伟 饰）的门下。老板娘玉珍（林志玲 饰）如花似玉，同时周旋在丈夫和叔叔道融（吴建豪 饰）之间，由此酿成一场悲剧。此后何安下独自经营药房，却无意中卷入江湖恩怨之中。他被隐姓埋名的扫地道士周西宁（郭富城 饰）高强的武功所折服，自愿拜其为师。与此同时，周的师弟彭乾吾（元华 饰）杀气腾腾找上门来。而曾与周一同练功的查老板（张震 饰）更将风波推向了高潮。上山，下山，何安下在短短的时间内悟出了许多真理……本片根据徐皓峰的原作改编。©豆瓣', '王宝强', '陈凯歌', 5.5, 210855, 'tt3594826', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2251450614.jpg', 11.2, 27.8, 42, 14.1, 5, '0.133255,-0.060767,-0.279793,0.422608,-0.064058,-0.177166,0.398252,0.260582,-0.536180,-0.394276,0.039922,0.535679,-0.158898,0.156125,0.161692,-0.371295,0.161884,-0.597518,-0.150309,-0.236761,-0.044763,-0.291067,-0.175416,0.042047,-0.269954,-0.072892,0.397797,0.074485,-0.235970,0.506680,0.324464,0.014613,-0.348076,0.212681,-0.233370,0.271501,-0.108419,0.193754,-0.251569,0.056930,-0.062178,-0.465992,-0.065541,-0.267690,-0.211285,0.179268,0.544388,-0.009360,0.023419,-0.293707,0.384137,-0.046926,-0.075057,-0.050157,0.291044,0.257332,0.291936,0.352011,-0.133585,0.104851,0.113075,-0.203293,-0.422188,0.300949,0.515708,-0.044070,-0.562881,0.286060,-0.031381,-0.074156,-0.205076,-0.134922,0.018517,0.237657,0.431816,0.068992,0.075177,-0.308497,-0.313240,0.442050,0.415764,-0.166759,0.243652,0.173335,0.227126,-0.177797,0.181304,-0.290663,-0.231483,0.112264,0.292232,-0.201576,0.150877,0.221354,-0.342067,-0.306737,-0.217282,0.182258,-0.123904,-0.100548,0.001433,-0.482495,-0.095985,-0.322906,-0.134738,-0.160016,0.359971,-0.131922,0.667852,-0.526062,0.152191,0.024393,0.140712,-0.390142,0.675334,-0.248186,0.334441,-0.209628,-0.054752,0.187779,0.144838,0.461822,0.159275,0.342376,-0.150061,-0.058798,-0.417203,0.003015', '3811356', '1908036', '1296044', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24879858', '分手大师', '喜剧', '梅远贵（邓超 饰）是一个情感经历极为丰富的男人，虽然有过这样那样的失败恋情，却也帮他铺就了一条通往荣华复归的康庄大道。现如今的梅远贵生活在首都北京，与其精英团队操办起帮人分手的奇葩业务，无论你有着怎样的感情和生活，只要票子给足，他总会高效率地完成任务。爱情那么虚幻的东西太不可靠，还是钱最让他放心。这一天，梅照例接了一单生意，那就是帮客户甩掉美丽女孩叶小春（杨幂 饰）。小春是一个自强不息的北漂姑娘，她渴望可以让之依靠休息的港湾，同时也为了美好的明天奋力打拼。原本踌躇满志的梅远贵，从和小春接触的第一天起，他们彼此的人生就发生了改变……本片根据同名人气话剧改编。©豆瓣', '邓超', '俞白眉', 5.1, 319799, 'tt3667798', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2188112867.jpg', 17.3, 30.1, 36.7, 10.8, 5.1, '0.024550,-0.093197,-0.474211,0.590223,-0.265729,-0.336935,0.673247,0.102417,-0.280048,-0.185637,0.108064,0.610203,0.075427,0.194859,0.346843,-0.097922,-0.239003,-0.478002,0.118429,-0.123717,-0.111683,-0.292008,-0.175267,-0.094323,-0.054449,-0.032723,0.827755,0.240374,-0.167470,0.278068,0.240165,-0.121183,0.035291,0.422893,-0.279133,-0.144889,-0.197687,0.353623,-0.425367,0.011476,0.064458,-0.206405,-0.025013,0.172812,-0.052572,0.164755,0.530479,-0.108857,-0.272995,0.090258,0.343235,-0.111186,0.003898,-0.254499,-0.021178,-0.150613,0.196762,0.300447,-0.263075,0.018185,0.032699,-0.253021,-1.058698,-0.087619,0.172334,0.109181,-0.734958,0.492385,0.082328,-0.003605,0.043570,-0.333132,0.093564,0.541326,0.372610,0.195427,-0.319023,0.162520,-0.475568,0.424854,0.778037,0.035004,-0.052328,0.559312,-0.438408,-0.400937,-0.060853,-0.151825,-0.547681,0.059345,0.081237,-0.038260,-0.253481,0.126889,-0.834477,0.176699,0.011967,-0.055019,0.165650,-0.656668,0.137274,-0.346555,-0.212374,-0.479907,-0.466160,0.030967,0.105258,-0.489742,0.839044,-0.739331,-0.094674,0.427264,0.359513,-0.520316,0.675384,0.261641,0.171249,-0.368705,0.109141,0.095715,-0.155148,0.391981,0.114695,0.370593,0.261098,-0.097014,-0.335462,0.645834', '1793491', '30163500', '26678784', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24882562', '悲惨世界：25周年纪念演唱会', '音乐', '《悲惨世界》是由法国音乐剧作曲家克劳德-米歇尔·勋伯格和阿兰·鲍伯利（Alain Boublil）共同创作的一部音乐剧，改编自维克多·雨果的同名小说。故事以法国大革命为背景，讲述主人公冉阿让在多年前遭判重刑，假释后计划重新作人、改变社会，但却遇上种种困难。该剧于1980年在法国巴黎的Palais des Sports首次公演，原本预计上演八周，结果延长加演，共演出了16周，因之后的场地时程已被预订才不得不下档。', '阿尔菲·博', '尼克·莫里斯', 9.6, 14777, 'tt1754109', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551186897.jpg', 0.3, 0.1, 1.8, 13.8, 84, '-0.141366,-0.166118,-0.444570,0.601357,0.445363,-0.321870,0.579783,0.041620,-0.379618,-0.257916,0.052075,0.804034,-0.547527,0.266218,0.550840,-0.463267,-0.607259,-0.665862,-0.182810,0.009883,-0.171536,-0.541505,-0.077762,-0.200568,-0.232335,-0.181778,0.711831,0.188837,-0.184006,0.134368,0.479900,0.230478,-0.204216,0.095974,0.246279,0.104318,0.276494,0.166087,-0.414613,0.299023,0.236031,-0.611772,-0.378553,-0.180086,-0.033054,0.260021,0.828603,-0.208120,-0.054414,-0.035787,0.682748,0.017931,-0.169466,-0.071662,0.254350,0.282918,0.281569,0.446739,-0.128739,0.084580,-0.269435,-0.478111,-0.735789,0.094763,0.209049,-0.173061,-0.388872,0.582706,-0.204246,0.251367,-0.097593,-0.292194,-0.032974,0.392108,0.874774,0.339413,0.092812,-0.009624,-0.076089,0.416762,0.521673,0.194316,-0.493501,0.505374,-0.110980,-0.480413,-0.154076,-0.170704,-0.245369,0.297664,0.177092,-0.033762,-0.069309,0.225395,-0.419572,-0.328990,-0.298306,-0.318964,0.167406,-0.191783,-0.028540,-0.858986,-0.280584,-0.152489,-0.046123,-0.157422,0.266478,-0.250677,0.674821,-0.547011,0.381904,0.391620,-0.175046,-0.359311,0.484934,0.026156,0.225721,0.013233,0.268251,0.174683,-0.361463,0.216037,0.200482,0.183956,0.044705,-0.168946,-0.295119,0.560444', '1322847', '3318306', '30397916', '6537486');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24883815', '午夜邂逅', '剧情', '一名女子Brooke（爱丽丝·伊芙 Alice Eve 饰）急着赶1:30开往波士顿的火车，然而终究晚了一步，Nick（克里斯·埃文斯 Chris Evans 饰）捡起她匆忙中遗落的手机，得知失窃的她必须及时赶回家中，Nick想要施以援手，然而信用卡不能使用，机缘巧合下，陌生的两个人通过彼此内心的交谈，重新找回生活方向。 这是克里斯·埃文斯的导演处女作，有点类似于理查德·林克莱特《日落之前》系列的电影，埃文斯还会担任主演和制片人，《雨人》罗纳德·巴斯编剧。', '克里斯·埃文斯', '克里斯·埃文斯', 7.1, 17499, 'tt0443465', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2258799735.jpg', 1.1, 6.8, 42.3, 35.8, 14.1, '0.375728,0.279229,-0.557989,0.625162,0.292941,-0.473071,0.503401,0.026700,-0.116952,-0.614267,0.135392,0.580219,-0.028059,0.343789,0.494156,0.090697,-0.649014,-0.454785,0.093041,-0.080693,-0.360171,-0.324831,-0.365432,-0.181325,-0.255782,-0.077240,0.646370,0.107784,-0.073371,0.392569,0.375040,0.166551,-0.337862,0.229432,0.015772,0.298019,0.150764,-0.136167,-0.543014,0.516198,0.383722,-0.150503,-0.353578,0.129242,0.381009,0.554041,0.306953,-0.212940,0.027499,0.026249,0.341744,0.065689,0.052341,-0.242761,-0.159779,0.209276,0.124318,-0.033428,-0.301931,0.373224,0.156640,-0.133223,-0.356032,0.412817,0.068252,0.178907,-0.590755,-0.014792,-0.488546,0.170836,0.196900,-0.501000,0.057731,0.106042,0.248951,0.142420,0.074529,-0.125995,-0.325739,0.025655,0.371317,0.104481,-0.210980,0.291629,-0.003177,-0.267265,0.013320,-0.016181,-0.672740,0.243283,0.411524,0.246566,0.048953,-0.000576,-0.081195,-0.055090,-0.404568,-0.100082,-0.177327,-0.232717,0.152188,-0.772618,0.198712,-0.195975,-0.090714,-0.294375,-0.103267,-0.196104,0.291895,-0.431704,0.154082,0.401172,0.089320,-0.096879,0.122045,-0.014977,0.164366,-0.381338,-0.001237,0.355747,0.138675,0.420023,0.242216,0.219215,-0.195378,-0.062632,-0.237722,0.376213', '2075345', '1298616', '1819460', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24885205', '在我消失前', '剧情', '里奇（肖恩•克里斯汀森Shawn Christensen 饰）是一个早就对生命失去了全部热情的抑郁男子，终于，他再也无法忍受精神上的重负，决定自杀。然而，就在他割了腕，徘徊在死亡线上的这个节骨眼，很久都没有联系的姐姐玛姬（埃米•罗森Emmy Rossum 饰）突然打来了电话，请求里奇去照顾她的小女儿索菲亚（法蒂玛•普泰西克 Fatima Ptacek 饰），一番天人交战之后，里奇决定先将自杀的事情放一放。就这样，里奇见到了索菲亚，这个早熟的小姑娘给予了他很深的影响，随着时间的推移，索菲亚和里奇之间建立了信任，可惜的是，索菲亚的依赖并不能够让里奇放弃自杀，他的下一个自杀计划已经提上了日程。©豆瓣', '肖恩·克里斯汀森', '肖恩·克里斯汀森', 7.5, 7242, 'tt3060492', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2208081193.jpg', 0.6, 3.3, 33.6, 43.8, 18.7, '0.340851,0.061462,-0.787720,0.418386,-0.138063,-0.441759,0.648395,0.079239,-0.305608,-0.115027,-0.011802,0.610809,-0.158966,0.247206,0.366606,0.328520,-0.512957,-0.904741,0.103213,-0.201061,-0.540141,-0.677885,-0.125785,-0.265538,-0.157795,-0.252358,0.502334,-0.075936,-0.096423,0.479722,0.226446,0.096514,0.661207,0.850360,-0.123751,0.321311,0.089005,-0.362007,-0.005218,0.303500,0.299297,-0.048466,-0.004282,0.530567,0.049077,0.587030,0.407789,-0.333191,-0.000805,0.031196,0.168354,-0.343164,0.252180,0.193015,0.249963,-0.228618,-0.115861,0.223661,-0.667645,-0.009557,0.155783,-0.064270,-0.698430,0.143514,-0.181036,0.004376,-0.802242,0.378705,-0.208126,-0.008368,-0.017559,-0.440912,0.128644,0.402955,0.234116,0.240606,-0.249209,-0.141586,-0.127793,0.079699,0.585122,0.044925,-0.248641,0.517801,-0.241011,-0.341438,-0.328676,-0.168445,-0.449430,-0.230337,0.319747,0.185829,-0.311075,0.278081,-0.227412,-0.110861,-0.472922,-0.331429,-0.028017,-0.384685,-0.043618,-0.353160,-0.359855,-0.253656,-0.653547,0.065162,-0.007300,-0.090438,0.603130,-0.762259,0.229905,0.614952,0.209223,-0.344684,0.451157,0.240726,0.022833,-0.121841,0.163087,0.279702,-0.087551,0.433671,0.476210,0.335779,0.250210,-0.052957,-0.321688,0.613733', '1306801', '25904974', '26752558', '2976072');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24888079', '好命先生', '喜剧', '秦思思（安以轩 饰）在经历过几次离奇的婚姻之后，变成了单身辣妈。秦思思经过大师指点寻找好命先生才能破除克夫的命运。机缘巧合下遇到了保安林中飞（陈小春 饰），两人在爱情与命运的玩笑中展开了一段令人啼笑皆非的“天赐良缘”。', '陈小春', '韩兆', 4.1, 11770, 'tt7267916', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2193692716.jpg', 35.8, 36, 21.1, 3.8, 3.3, '0.199877,-0.054231,-0.115472,0.384271,0.245106,-0.349155,0.790422,-0.379596,-0.604138,-0.241079,0.251335,0.450069,-0.821977,0.393314,0.542202,-0.137502,-0.161712,-0.587512,0.205173,0.017022,-0.323193,-0.360824,-0.280266,0.031464,-0.141402,-0.341453,0.438800,0.117474,-0.094182,0.396695,0.395529,0.043809,-0.441722,0.201075,-0.263274,0.507942,0.215645,0.755621,-0.785392,0.095391,0.165168,-0.515106,-0.145647,-0.030439,-0.269879,0.100986,0.512540,-0.494396,-0.308921,-0.101347,0.347444,-0.095629,-0.168472,-0.012278,0.253334,0.378334,0.293763,0.281561,-0.238344,0.064177,0.085873,0.093103,-0.540358,-0.121033,0.438507,-0.187505,-0.511514,0.177462,0.075357,-0.105356,-0.011081,-0.705509,0.170296,0.238863,0.739243,0.224525,-0.365895,-0.268143,-0.354212,0.569238,0.744115,-0.047325,-0.360847,0.515727,0.071417,-0.514980,0.160007,-0.089809,-0.484421,0.307291,0.345304,-0.112957,-0.140364,0.319263,-0.541236,-0.119408,-0.380838,0.267826,-0.172255,-0.424137,-0.118153,-0.230407,-0.296029,-0.554079,-0.292026,0.183538,-0.241727,-0.438577,0.467155,-0.817111,0.105408,0.112419,0.151091,-0.276197,0.610128,0.261953,0.269540,-0.150526,0.229947,0.202181,-0.426348,0.420823,0.258043,0.522603,0.010029,-0.006115,-0.226897,0.103119', '25881786', '26320029', '25962735', '26322792');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24901000', '神秘博士：博士之时', '科幻', '宇宙中最邪恶的物种都被一条神秘的消息吸引来到一座宁静的星球小镇：圣诞。博士和他的朋友们必须要破解出这条信息，因为博士的命运与整个宇宙的命运都握在其中。', '马特·史密斯', 'Jamie Payne', 8.7, 6323, 'tt2986512', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2161440153.jpg', 0.8, 2.2, 11.3, 29.9, 55.7, '0.284879,0.469618,-0.727164,0.782021,-0.158329,0.134177,1.001917,-0.214453,-0.279951,-0.011391,0.058563,0.820825,-0.173891,0.227003,0.646587,0.203311,-0.229898,-0.545881,-0.101072,-0.565124,-0.475445,-0.417285,-0.615675,-0.136442,0.110627,-0.599057,0.941975,0.142623,-0.065054,-0.024355,-0.099926,0.425633,-0.452326,0.352741,-0.683107,-0.265172,0.255394,0.050201,-0.437796,0.139934,-0.459845,-0.142022,0.087361,0.545707,-0.581026,-0.106051,0.889562,-0.767409,-0.046054,-0.110808,0.260766,-0.321496,-0.046755,-0.287501,0.669518,-0.113011,0.261863,0.564771,-0.288172,0.214066,0.104434,-0.135808,-1.142358,-0.268167,0.339063,0.466440,-0.118951,0.203621,0.318230,-0.221320,-0.121988,-0.766918,0.798677,0.190843,0.375843,0.559497,-0.269495,0.210511,-0.259158,-0.309150,0.788069,-0.397591,-0.239655,0.124207,-0.506631,-0.470418,-0.246402,-0.096531,-0.760261,0.264800,0.526677,0.341889,-0.167193,0.627879,-1.221547,0.275338,0.097060,-0.513114,-0.026757,-0.622549,-0.400641,-0.650219,-0.054595,0.040247,0.029110,0.431542,0.262863,0.048057,0.936555,-0.503183,0.290344,0.475756,0.142497,-0.526798,1.013966,0.126167,0.330225,-0.512336,0.109927,0.269788,0.244966,0.900484,-0.347167,0.544521,-0.028323,-0.170270,-0.623767,0.940837', '26290398', '26667010', '2357162', '19899707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24910035', '怪兽卡车', '喜剧', '影片讲述了卢卡斯饰演的高中生打算组装一辆卡车准备出出风头，但是报废车辆的零件哪有那么好用。这是，小镇上出现了一个类似章鱼的大怪兽，不知道从哪里来，但是这头怪兽竟然能躲进卢卡斯的卡车里，并且和卡车融为一体，就这样，卢卡斯拥有了惊世骇俗的怪兽卡车，去到哪里都是如履平地、所向披靡。', '卢卡斯·提尔', '克里斯·韦奇', 6.3, 8145, 'tt3095734', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2410836053.jpg', 2.6, 14.3, 56.2, 19.5, 7.4, '0.708501,-0.002500,-0.976383,0.513010,-0.165859,-0.202253,0.983205,-0.213721,-0.092380,-0.019937,0.443710,0.468059,-0.232277,-0.179265,-0.026969,0.139363,-0.224585,-0.287248,0.113463,-0.169882,-0.578787,-0.357284,-0.571599,-0.314182,0.349588,0.138922,0.444793,0.119775,-0.190308,0.116571,0.155997,-0.066846,-0.071170,0.348844,-0.575807,0.096492,-0.408303,0.313761,0.404062,0.230549,-0.043940,-0.027415,0.254745,-0.192002,-0.034601,0.168466,0.518934,-0.205584,0.045117,0.130486,0.159582,-0.016111,0.177930,0.049758,0.387163,0.048663,-0.048025,-0.561380,0.022399,0.333497,0.078868,0.134055,-0.691707,0.074875,-0.763040,0.187667,-0.966790,0.232560,-0.042515,-0.160207,-0.039959,-0.551700,0.315867,-0.192924,0.290934,0.428925,-0.042172,0.032147,-1.081608,-0.123438,0.575517,-0.166050,-0.293480,0.625477,0.118511,-0.556105,-0.312769,-0.466557,-0.375173,-0.236622,0.198770,-0.159934,-0.516623,-0.107813,-0.665579,0.202891,-0.459267,-0.250948,-0.238504,-0.040261,-0.275452,-0.588978,0.374204,-0.372144,0.043970,0.508512,0.100688,-0.293199,0.737154,-0.666377,-0.085377,0.507390,0.275464,-0.237318,0.663986,-0.515152,-0.135276,0.193830,0.121119,-0.425300,0.114955,0.446559,0.348030,0.638093,0.090475,-0.386985,-0.392594,0.501672', '21619567', '1309101', '1293515', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24973419', '渴望', '悬疑', '颓废堕落的中年人藤岛昭和（役所广司 饰）也曾拥有幸福美满的家庭，身为刑警的他因暴打前妻桐子（黑泽明日香 饰）的情人而被迫提前退休。在看不见未来的最低端，他接到桐子打来的电话，原来藤岛的女儿加奈子（小松菜奈 饰）已失踪多日。出于复杂的感情，这个粗鲁凶暴的男人风风火火展开调查，他走访了加奈子身边的人，包括高中同学森下（桥本爱 饰）和长野（森川葵 饰）、班主任东里惠（中谷美纪 饰）以及精神科医生辻村（国村隼 饰），从这些人的口中，却发现女儿天使般的外表下似乎住着一个可以让所有人堕落乃至遭遇不幸的魔鬼。藤岛全速奔跑 ，另一伙危险的人马也介入进来……本片根据深町秋生的推理小说《无尽的渴望》改编。©豆瓣', '役所广司', '中岛哲也', 6.6, 18578, 'tt3108158', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2214518650.jpg', 3.3, 13.8, 43.3, 27.9, 11.7, '0.278823,-0.225623,-0.454941,0.561843,-0.142142,-0.173806,0.764138,0.295249,-0.281609,-0.367229,0.354199,0.435153,-0.062858,0.104053,0.396717,0.134918,-0.308283,-0.500469,-0.090316,-0.164077,-0.097025,-0.337240,-0.245538,-0.169678,0.067311,-0.092047,0.650702,-0.092598,-0.114171,0.616965,0.455309,0.561964,-0.228548,0.244362,0.073340,0.312990,0.214629,-0.015216,-0.055925,0.186879,-0.250063,-0.188515,-0.047172,0.241590,0.038674,0.452809,0.499399,-0.343756,-0.196136,-0.233197,0.377693,-0.202475,-0.139655,0.185984,0.534095,0.015817,0.126930,0.171571,-0.253156,0.038325,0.094298,0.057923,-0.717134,0.027441,0.257045,0.220682,-0.253464,0.361159,-0.098138,-0.112706,0.415971,-0.039350,0.027489,0.173938,0.063019,0.384053,-0.170741,0.134699,-0.158720,0.277667,0.439472,-0.100316,-0.064844,0.123261,-0.318050,-0.296867,-0.111236,-0.229226,-0.534061,-0.015268,0.071170,0.162326,-0.184140,0.057146,-0.410564,-0.067742,-0.025002,0.053544,0.063564,-0.350476,-0.246422,-0.484669,0.004835,-0.579352,-0.355026,0.188519,0.101719,-0.025303,0.781908,-0.712871,0.126077,0.471838,0.313491,-0.144612,0.306104,0.071009,-0.199038,-0.309712,-0.126215,0.338329,0.236665,0.362793,0.116611,0.313661,-0.199695,-0.013191,-0.277936,0.088198', '3811356', '25922902', '10467125', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('24987018', '赤道', '剧情', '韩国秘密核武器神秘失踪，同时载着军方手提装置的飞机在中国境内坠毁。韩方接到消息，一名疑似绰号“赤道”的危险人物（张震 饰）带着助手“信差”（文咏珊 饰）将于香港实行秘密武器交易，韩国武器专家崔民号（池珍熙 饰）与特工朴宇哲（崔始源 饰）奉命前往调查。香港反恐特勤组主管李彦 明（张家辉 饰）与督察范家明（余文乐 饰）协助韩方寻找武器，而核物理教授肇志仁（张学友 饰）也受邀协助判案。武器很快被寻回，没想到竟还隐藏着潜在危机。正当香港及韩国警方决定送还武器回韩国之际，大陆安全局高管（王学圻 饰）带着助手袁小姐（冯文娟 饰）突然出现，三方陷入周旋之中，原来“赤道”另有其人，而他们一伙儿的阴谋也开始实施……©豆瓣', '张学友', '梁乐民', 6.3, 110538, 'tt3614922', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2238375159.jpg', 4.7, 16.9, 47.3, 23.2, 7.9, '-0.009693,0.040216,-0.666902,0.529374,0.260034,0.288746,0.080408,0.211529,-0.566956,-0.501005,0.319136,0.520483,0.022192,-0.050144,0.354725,-0.083466,-0.532379,-0.629400,-0.068263,-0.130825,-0.281422,-0.420180,-0.428335,-0.212718,0.059986,-0.208291,0.369683,0.268442,-0.123785,0.581900,0.470123,0.572674,-0.741193,0.441703,-0.025109,-0.471706,0.600895,-0.150551,-0.517409,0.297249,-0.102572,-0.324245,0.132816,0.090416,-0.029594,0.329295,0.539865,-0.034036,0.173184,-0.284625,-0.010751,-0.493127,-0.011166,-0.253214,0.531250,0.387646,0.033544,0.298163,-0.305211,0.389164,0.221486,-0.060619,-0.366056,0.227373,0.255378,0.295638,-0.334107,-0.025566,-0.544618,0.038471,0.080732,-0.168278,0.430016,0.389454,0.279207,-0.051368,0.173692,0.178115,-0.382923,0.250840,0.244325,-0.271288,0.154038,-0.390278,0.326874,-0.528677,0.079065,0.028174,0.013596,-0.057483,0.102202,-0.178832,0.211004,-0.111569,-0.601370,0.065875,-0.121328,-0.054877,0.111090,-0.176657,0.130309,-1.072640,0.116452,-0.075809,-0.230045,0.301405,0.305391,0.321249,0.485103,-0.542273,-0.025558,0.373166,0.291636,-0.599211,0.259280,-0.015791,0.004085,-0.646971,-0.209255,-0.090044,0.284996,0.289120,-0.115733,-0.058566,-0.139026,-0.537422,-0.044155,-0.410129', '1293572', '25723905', '3003137', '2369613');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25140779', '非常父女档', '剧情', '瓦伦丁（艾赫尼奥·德伯兹 Eugenio Derbez 饰）是城中有名的花花公子，在情海中徜徉多年的他自认为练就了一身“万花从中过片叶不沾身”的厉害本事。某一天，一位不速之客的到来将瓦伦丁平静的生活彻底打乱，这位不速之客不是别人，竟然是一个刚出生还没多久的小小婴儿。瓦伦丁给孩子取名玛姬（洛蕾托·佩拉尔塔 Loreto Peralta 饰），就这样开始了自己的“奶爸”生涯。之后，瓦伦丁带着玛姬来到了洛杉矶，意在寻找玛姬的亲生母亲。一年接着一年，玛姬渐渐长大，瓦伦丁的事业也渐渐走上正轨，父女两人之间的羁绊越来越深，这一段真挚而感人的亲情，究竟会迎来怎样的终结呢？©豆瓣', '欧赫尼奥·德尔维斯', '欧赫尼奥·德尔维斯', 7.8, 16845, 'tt2378281', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151512834.jpg', 0.5, 2.7, 26.9, 48.2, 21.7, '0.124268,0.210755,-0.520312,0.379398,-0.246157,-0.429180,0.526645,0.000490,-0.590404,-0.146934,0.162459,0.716515,-0.259507,0.352894,0.366875,0.190312,-0.179523,-0.757739,-0.011400,-0.232166,-0.088315,-0.367710,-0.528727,0.034443,0.069379,-0.430365,0.261222,0.196484,0.235355,0.374928,0.290115,0.260447,-0.023248,0.251541,-0.244881,0.278162,0.265746,0.077917,-0.044033,0.199790,0.018643,-0.232217,-0.144814,-0.057483,-0.149022,0.277100,0.605691,-0.103475,-0.173028,-0.115077,0.508081,-0.110934,-0.203240,0.063371,0.264902,-0.164147,0.226896,0.249750,-0.370301,-0.038943,-0.133062,-0.365154,-0.398902,0.158948,-0.189599,0.023585,-0.635289,0.356164,0.051749,-0.473132,0.222869,-0.368535,-0.016243,0.457566,0.163316,0.517041,-0.156285,-0.047278,-0.321470,0.169516,0.569854,-0.111411,-0.297485,0.554813,0.013502,-0.217620,0.127907,-0.299545,-0.469643,-0.202665,0.514326,0.052968,-0.054727,0.379025,-0.470538,0.141382,-0.490707,-0.059626,0.073112,-0.404331,-0.267616,-0.219406,-0.173329,-0.393055,-0.150228,0.143052,-0.018548,-0.306124,0.794114,-0.693069,0.583856,0.318883,-0.079279,-0.296993,0.386359,-0.006667,0.153629,-0.126750,-0.002563,0.373019,-0.104010,0.109380,0.220672,0.302995,-0.155910,-0.017226,-0.277981,0.572606', '1292720', '5977789', '1307146', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25300674', '冰封侠：时空行者', '动作', '明朝大将军贺英利用时空金球终于重返明朝，与锦衣卫兄弟萨獒获悉了倭寇和朝廷奸党之间足以倾覆皇权的密谋，绵延400年的惊天危机一触即发。贺英也在红颜知己小美的帮助下开始了抗倭锄奸和保护族人的战斗。', '甄子丹', '叶伟民', 2.8, 12600, 'tt2993848', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2537133715.jpg', 74.1, 17.6, 6.1, 0.7, 1.6, '0.126201,-0.089626,-0.552516,0.411024,0.533252,-0.124504,0.442171,0.240734,-0.660940,0.016997,0.274523,0.157411,-0.172049,-0.244454,0.304361,-0.405290,-0.435176,-1.065134,-0.401232,-0.055951,-0.081457,-0.365716,-0.663970,-0.185161,-0.261468,-0.471656,0.880164,0.318745,0.200201,0.569549,-0.081456,0.027660,-0.269172,0.603053,-0.329385,-0.033007,0.048262,-0.134461,-0.990052,-0.116373,-0.278824,-0.561397,-0.186142,0.064644,-0.177738,-0.057920,0.315030,-0.907575,0.181442,-0.354134,0.152118,-0.174833,-0.207091,0.047805,0.362431,0.054083,0.246507,0.481425,0.042793,-0.339750,-0.154148,-0.244656,-0.499857,-0.133128,0.189292,-0.162575,-0.110779,0.529477,-0.016988,0.063231,0.298596,-0.231071,0.478220,0.844749,0.412321,0.278611,-0.521250,0.062799,-0.430708,0.138061,0.940464,-0.184014,-0.104752,-0.359700,0.246471,-0.385762,-0.088028,-0.207630,-0.160318,0.023355,0.383973,0.066663,0.242714,0.728764,-0.659909,0.032470,-0.497971,0.168158,0.266182,-0.313430,-0.148648,-0.070067,-0.880432,-0.310126,-0.111557,0.397903,0.619107,-0.026213,0.754751,-0.763900,-0.000104,0.454347,0.464866,-0.436940,0.501610,0.060355,0.357258,-0.216052,-0.098853,-0.212124,-0.270547,0.645301,0.077497,0.119537,-0.249919,0.049261,-0.001253,-0.026194', '1433736', '25978126', '1427947', '26994321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25444447', '黄飞鸿之英雄有梦', '剧情', '清朝同治年间，古老的帝国行将就木，重要通商口岸广州珠江口正沐浴在最后的繁荣和血腥搏杀中。码头上黑虎帮和北海帮为非作歹，杀伐不断，而底层劳工饱受欺凌，朝不保夕。自幼习武的阿飞黄飞鸿（彭于晏 饰）在黑虎帮混迹五六年，他以死士身份取得北海帮主的首级，从而被黑虎帮老大雷公（洪金宝 饰）收为第四个义子。雷公心狠手辣，手下更有三个蛇蝎心肠的义子助纣为虐，为了赚钱不惜逼良为娼，草菅人命。阿飞凭借高强的武功很快成为黑虎帮内的一只猛虎，然而他在打杀之外似乎隐藏着不可告人的秘密。另一方面，父兄被黑虎帮卖到海外而无依无靠的孩子们，在赤火（井柏然 饰）、阿春（王珞丹 饰）等人的号召下组成孤儿帮，他们正试图向有着血海深仇的黑虎帮展开复仇……©豆瓣', '彭于晏', '周显扬', 5.6, 78361, 'tt3469592', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2209287190.jpg', 7.7, 25.5, 48.4, 13.2, 5.1, '0.031994,-0.009280,-0.510449,0.643469,-0.020457,-0.084625,0.337953,0.127214,-0.568622,-0.256533,0.343846,0.445197,0.429780,0.124354,-0.135724,-0.261613,0.071741,-0.693303,-0.288738,-0.015300,-0.214867,-0.200947,-0.479498,-0.212309,-0.367884,-0.062157,0.472651,0.121325,-0.036582,0.447572,0.313681,0.399488,-0.263182,0.147303,-0.535986,-0.096371,-0.246728,-0.147733,-0.348693,0.202536,-0.123687,-0.257905,-0.186517,-0.120555,-0.165998,0.242175,0.496325,-0.287012,0.106617,-0.648539,0.114138,-0.226463,-0.054312,0.042725,0.329025,0.078225,0.237888,0.347879,-0.177443,0.100547,-0.013004,-0.283885,-0.887908,-0.024986,0.229226,0.124172,-0.766724,0.401477,-0.056781,-0.147039,0.353437,-0.229676,0.027763,0.357061,0.027506,0.178055,-0.131050,0.296808,-0.725566,0.202052,0.729688,-0.222144,0.319397,-0.366969,0.286232,-0.038495,0.173895,-0.536683,-0.039251,-0.160873,0.236485,-0.323552,-0.117401,0.190567,-0.549260,-0.095671,-0.195806,0.124813,-0.080067,-0.259817,-0.169085,-0.425126,-0.241965,-0.319452,-0.021474,0.064891,0.282618,-0.227746,0.632352,-0.803463,0.139740,0.316928,0.335764,-0.601789,0.438567,-0.046044,0.248416,-0.164970,-0.432726,-0.129246,0.590102,0.356676,0.346692,0.044819,-0.227328,-0.036535,-0.101487,0.163710', '1877596', '1793491', '1438924', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25662063', '探员卡特', '动作', '在与红骷髅的殊死决斗后，美国队长（克里斯·埃文斯 Chris Evans 饰）驾驶着失控的飞机坠毁在茫茫冰原之上。最后的关头，他向佩吉·卡特（海莉·阿特维尔 Hayley Atwell 饰）告别，彼此生死相别。一年后，佩吉被安排在清冷的部门，完全不受重用。虽然她向上司自荐，怎奈对方完全不拿她当回事儿。某天晚上，佩吉被留在办公室加班，这时电话响起，对方说已经锁定十二宫的位置，对方携带杀伤力强大的武器，请求特工局派出探员支持。佩吉没有报告上司，而是独自一人前往目的地。夜幕之下，这位果敢女子勇闯虎穴……©豆瓣', '海莉·阿特维尔', 'Louis D''Esposito', 7.9, 10902, 'tt3067038', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2131074228.jpg', 0.3, 1.4, 25.2, 46.8, 26.2, '0.088846,0.192468,-0.831957,0.550486,0.013201,-0.155490,0.633843,0.298869,-0.089550,-0.198212,0.373015,0.547373,-0.022956,-0.219659,0.224464,-0.081291,-0.488867,-0.678142,-0.166708,-0.011523,-0.363286,-0.583903,-0.088960,-0.088028,0.033961,-0.114418,0.494269,-0.003719,-0.124473,0.225669,0.298936,0.431855,-0.116496,0.590602,0.050780,-0.199289,0.390850,-0.169908,-0.234027,0.458849,0.063385,-0.112936,-0.222410,0.086329,0.277748,0.284297,0.594643,-0.202536,0.012296,-0.200331,-0.037949,-0.208564,0.235123,0.011244,0.372131,0.015214,0.094916,0.106480,0.082097,-0.025040,-0.005260,-0.042030,-0.278051,0.121309,-0.224649,0.118275,-0.378606,0.192973,-0.475695,0.089132,0.084426,-0.413504,0.165077,0.177019,-0.070616,0.043572,-0.046286,0.117459,-0.340032,-0.100769,0.446849,0.206058,-0.183974,0.037430,0.172809,-0.399507,-0.231397,-0.095603,-0.566256,-0.045505,0.402254,0.100037,0.112029,0.010102,-0.197920,-0.195670,-0.251622,-0.273785,-0.225805,-0.517972,-0.161596,-0.675477,0.185481,-0.161510,-0.328108,0.169520,0.011320,0.225698,0.283871,-0.639459,0.218696,0.444969,0.227605,-0.180618,0.641554,0.135194,0.013767,-0.290890,0.121205,0.089950,0.243633,0.642603,0.545541,0.087421,-0.132774,0.056188,-0.293607,0.161105', '26951746', '3735015', '2159244', '25870679');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25662327', '火锅英雄', '剧情', '中学时代起就是好哥们儿的刘波（陈坤 饰）、许东（秦昊 饰）与王平川（喻恩泰 饰），因为合伙经营的防空洞改造的火锅店经营不善而渐生矛盾。三兄弟准备把店转让，为了能卖个好价钱，三人开始自行扩建。没想到却误打误撞地挖到了隔壁银行的金库，面对金钱的诱惑欠下赌债的刘波左右为难，无巧不成书，初中女同学 于小惠（白百合 饰）刚好就是这所银行的职员。三人准备请于小惠帮忙，没想到于小惠心心念念的却是当年的一封情书……被打破的防空洞串起了旧日青春和四个老同学，一场预谋已久的银行抢劫案也悄然滋生。©豆瓣', '陈坤', '杨庆', 7.2, 331297, 'tt5596352', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2325504300.jpg', 0.8, 4.5, 38.6, 44.3, 11.8, '0.404062,0.042398,-0.464293,0.328289,-0.131766,-0.605003,0.447958,0.295024,-0.373278,-0.147295,0.086504,0.434924,-0.143019,0.390234,0.280356,-0.231129,0.019480,-0.467309,-0.233311,-0.257507,-0.014227,-0.286195,-0.325497,-0.117403,-0.325031,0.115435,0.462837,0.221244,-0.086558,0.301630,0.244920,0.247655,-0.282348,0.133214,-0.134368,0.014225,0.028925,0.283275,-0.686860,0.078097,0.094953,-0.289528,-0.010192,-0.095391,0.365114,0.281131,0.585469,0.100276,-0.163403,-0.049781,0.408961,0.098128,-0.133500,-0.083604,0.237002,0.132440,0.499727,0.082712,-0.571479,-0.159293,0.496074,-0.292421,-0.641452,0.035151,0.155852,-0.154751,-0.604865,0.398173,-0.123229,0.074715,0.088916,-0.505540,-0.041088,0.344185,0.296490,0.461906,-0.303427,-0.131830,-0.495178,0.282171,0.304911,-0.158185,0.308443,0.347999,0.162578,-0.269670,0.208701,0.169904,-0.346540,0.039678,0.518135,-0.148986,0.024887,-0.136079,-0.928734,-0.260515,-0.298141,-0.236036,0.344654,-0.350440,-0.263158,-0.600061,-0.189882,-0.028742,-0.129088,0.305614,0.425529,0.119120,0.474806,-0.789696,-0.053117,0.382921,0.266569,-0.624462,0.334169,-0.164556,0.031983,-0.277411,-0.266533,-0.430197,-0.048200,0.544347,0.429449,0.450601,-0.197832,-0.345804,-0.346851,0.317158', '26290398', '11810348', '1408130', '6858739');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25662329', '疯狂动物城', '喜剧', '故事发生在一个所有哺乳类动物和谐共存的美好世界中，兔子朱迪（金妮弗·古德温 Ginnifer Goodwin 配音）从小就梦想着能够成为一名惩恶扬善的刑警，凭借着智慧和努力，朱迪成功的从警校中毕业进入了疯狂动物城警察局，殊不知这里是大型肉食类动物的领地，作为第一只，也是唯一的小型食草类动物，朱迪会遇到怎样的故事呢？近日里，城中接连发生动物失踪案件，就在全部警员都致力于调查案件真相之时，朱迪却被局长（伊德瑞斯·艾尔巴 Idris Elba 配音）发配成为了一名无足轻重的交警。某日，正在执勤的兔子遇见了名为尼克（杰森·贝特曼 Jason Bateman 配音）的狐狸，两人不打不相识，之后又误打误撞的接受了寻找失踪的水獭先生的任务，如果不能在两天之内找到水獭先生，朱迪就必须自愿离开警局。朱迪找到了尼克，两人联手揭露了一个隐藏在疯狂动物城之中的惊天秘密。©豆瓣', '金妮弗·古德温', '拜伦·霍华德', 9.2, 1779108, 'tt2948356', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2614500649.jpg', 0.1, 0.2, 4.5, 29.4, 65.8, '0.356927,-0.038557,-0.512097,0.340728,-0.051464,-0.122958,0.490995,-0.150455,-0.378463,-0.296855,0.093278,0.611541,-0.135795,0.246451,0.195619,-0.086481,-0.346800,-0.585440,0.046659,-0.337098,-0.207467,-0.389559,-0.273617,-0.190218,0.150619,-0.260596,0.470721,0.105589,-0.140431,0.288435,0.116774,0.389711,-0.551529,0.374422,-0.105247,0.015466,0.554126,-0.130489,-0.104885,0.295825,-0.000183,0.055965,0.087079,-0.011226,0.139417,0.078254,0.602278,-0.516076,-0.221274,-0.143261,0.198137,-0.327023,0.099052,0.032310,0.594608,-0.109864,0.340743,0.370214,-0.254530,0.130156,0.069523,-0.098276,-0.759829,-0.051404,-0.020450,0.439639,-0.349615,0.043026,0.098307,-0.047178,0.340599,-0.241877,0.281105,0.439329,0.345297,0.353822,-0.035020,0.206991,-0.571269,0.076715,0.770057,-0.093938,-0.311386,0.010115,0.122644,-0.644929,0.106201,-0.059637,-0.186125,0.039238,0.326761,0.051298,-0.374171,0.291957,-0.575160,-0.087596,-0.482073,-0.233196,-0.026609,-0.260072,-0.170239,-0.593916,0.045298,-0.071938,-0.197449,0.043025,0.154465,-0.312462,0.551938,-0.930866,0.335573,0.619436,0.085097,-0.204113,0.506464,-0.120012,0.353843,-0.195356,0.085517,0.100288,0.310340,0.576897,0.125243,0.375771,0.109951,-0.297721,-0.382755,0.326390', '1420088', '17