INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25662337', '惊天魔盗团2', '剧情', '四骑士重新聚首，借一场大秀意图揭穿一位科技大亨的不义之举，不料行动失败。同时，他们背后的支持者迪伦（马克·鲁法洛饰）自己也深陷危机。幕后黑手正是科学奇才沃尔特（丹尼尔·雷德克里夫饰），他胁迫四骑士去完成一次不可能的偷盗任务。四骑士只剩最后的希望，他们必须上演一场前所未有的魔术秀来为自己正名，揭穿背后主谋。', '杰西·艾森伯格', '朱浩伟', 6.9, 290266, 'tt3110958', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2355440566.jpg', 1.5, 8.8, 44.7, 32.8, 12.1, '-0.157385,0.069168,-0.416256,0.517369,-0.091762,-0.153250,0.424963,-0.064493,0.037583,-0.416569,0.816141,0.582589,0.088575,-0.181177,0.291805,-0.264873,-0.066938,-0.529604,0.192962,0.089879,-0.136897,-0.407315,-0.271891,-0.318528,0.015059,0.072278,0.581953,0.376997,-0.298203,0.165027,0.556064,0.397911,-0.258381,0.153384,0.404345,-0.235413,0.387494,-0.194994,-0.527066,0.097215,-0.148207,-0.171502,-0.321384,0.505068,-0.255633,0.249467,0.371618,-0.576366,0.213361,-0.475400,0.236812,-0.493684,-0.017223,0.172239,0.289454,-0.146395,0.160561,0.327698,0.170400,-0.028423,-0.006213,-0.070694,-1.183712,-0.074830,0.058634,0.045093,-0.351735,0.311320,-0.280003,0.230237,-0.148463,-0.010292,-0.373493,0.245671,0.727726,-0.060645,-0.056847,0.092196,-0.516752,0.054552,0.625505,-0.025891,-0.129275,0.132674,0.410539,-0.149887,-0.021245,-0.378111,-0.232857,-0.024612,0.504501,-0.132565,0.207355,0.350498,-0.239006,-0.170727,-0.989579,-0.087196,0.040791,-0.326811,0.331650,-0.482392,0.064283,0.183795,-0.055758,0.118117,0.381040,-0.544372,0.299006,-0.347263,0.128536,0.650703,-0.006449,-0.540659,0.127052,0.512339,0.403524,-0.552550,-0.396697,-0.216690,0.186212,-0.060006,0.300642,-0.003423,0.205228,-0.235014,-0.153995,0.156048', '27073234', '26678784', '1293605', '35076714');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25662977', '一次邂逅', '剧情', '皮埃尔（弗朗索瓦·克鲁塞 François Cluzet 饰）和安妮（丽萨·阿祖洛斯 Lisa Azuelos 饰）结婚多年，共同养育了两个孩子，感情一直十分亲密要好。皮埃尔自认为是一位称职的丈夫，一位负责人的父亲，能够拥有现在平静如水的生活，他十分满足，亦觉得无比幸运。某一日，皮埃尔结识了名叫艾尔莎（苏菲·玛索 Sophie Marceau 饰）的女子，艾尔莎身上独特的魅力渐渐吸引了皮埃尔，皮埃尔感到，自己内心里的某些东西复苏了。然而，皮埃尔并没有因此想要离开妻子，可是，他亦无法忽视内心的悸动，让他感到吃惊的是，艾尔莎对自己也有着同样的感觉，两个坦诚的成年人越走越近，终于越过了伦理道德的界限。©豆瓣', '苏菲·玛索', '丽萨·阿祖洛斯', 7.4, 5640, 'tt2760634', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2555536921.jpg', 0.7, 4.4, 38.3, 39.7, 16.9, '0.339305,-0.087969,-0.691775,0.760625,-0.151248,-0.399022,0.882804,0.058616,-0.834034,-0.438144,0.100379,0.968070,-0.218397,0.308592,0.249179,0.322608,-0.010225,-0.472276,-0.062484,-0.184556,-0.019013,-0.592118,-0.428365,-0.153443,-0.483051,-0.296645,0.579578,-0.070577,0.112770,0.460884,0.372601,0.374211,0.102837,0.625468,-0.136019,-0.325247,0.153473,-0.145181,-0.234062,0.004387,0.230538,0.211164,0.020367,0.453385,-0.233751,0.198724,0.323477,-0.105851,-0.335809,0.023300,0.381388,0.030597,0.032616,0.218639,-0.080546,0.074052,0.056544,0.163145,-0.285286,-0.029931,0.196479,0.083710,-0.767590,0.214522,0.047702,0.199455,-0.523482,0.333004,0.013777,-0.290630,0.259981,-0.416555,0.145839,0.231146,0.230032,0.564863,-0.263731,0.173851,-0.230292,-0.359505,0.773423,0.103201,-0.371684,0.509726,-0.715090,-0.396569,0.059037,-0.048043,-0.537173,0.023737,0.052532,0.642349,0.045844,0.284254,-0.374990,0.047304,-0.367440,0.020626,-0.073277,-0.593414,0.211000,-0.246886,-0.445318,-0.743182,-0.605507,-0.087720,-0.074913,-0.480143,0.784411,-0.902064,0.093616,0.299892,0.292192,-0.375337,0.572883,0.438421,-0.111349,-0.282027,-0.111365,0.719294,-0.431530,-0.185274,0.099399,0.444434,-0.121098,-0.085950,-0.214187,0.673525', '24756472', '2075721', '25721544', '26724989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2567521', '校花我爱你', '喜剧', '布法罗格林高中迎来一年一度的毕业典礼，呆板木讷的男孩丹尼斯·库夫曼（保罗·鲁斯特 Paul Rust 饰）作为学生代表上台发表讲话。令所有人都大吃一惊的是，这个毫不起眼的家伙竟然在大庭广众之下向校花——啦啦队长贝丝·库珀（海顿·潘妮蒂尔 Hayden Panettiere 饰）说出“我爱你”三个字。对丹尼斯来说，这不过是了却了自己的一桩心愿，剩下的事就是和好哥们里奇（杰克·卡朋特 Jack Carpenter 饰）快乐地度过毕业晚会。不过当晚贝丝竟带着两位姐妹淘来到丹尼斯的身边。当然，尾随前来的还有贝丝气急败坏的男朋友。一番混乱之后，丹尼斯和贝丝等五个人冲了出来。开始了难忘而美好的夜晚……本片根据拉里·道尔（Larry Doyle）的同名原著改编。©豆瓣', '海顿·潘妮蒂尔', '克里斯·哥伦布', 5.5, 6911, 'tt1032815', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2330105730.jpg', 7.1, 27.5, 49.5, 12.6, 3.3, '0.384593,-0.276263,-0.724943,0.591795,-0.173116,-0.536601,0.729998,0.014839,-0.509609,-0.198937,0.152072,0.617344,-0.593371,0.372106,0.612835,0.086373,-0.481439,-0.707183,-0.110469,-0.192369,-0.087563,-0.627204,0.103030,-0.198636,0.007646,-0.281999,0.227851,-0.021441,0.077081,0.755174,0.558449,0.358610,0.043659,0.242080,-0.087678,0.232157,0.247801,-0.078203,-0.274763,0.222139,0.122734,0.074579,-0.362776,0.136719,0.106640,0.297309,0.555666,-0.181961,0.000614,0.123339,0.286611,-0.399910,-0.075662,0.026426,0.162280,-0.021479,0.370800,0.152741,0.019420,0.167237,0.068363,-0.196285,-0.493011,0.325299,0.068768,0.211795,-0.570963,0.552365,-0.188355,-0.209782,0.235070,-0.338538,0.032572,0.153033,0.267865,0.426743,-0.011560,0.142759,-0.486101,0.046953,0.496234,0.087899,-0.243549,0.316669,-0.126569,-0.447387,0.002397,0.020368,-0.305057,0.213625,0.161987,-0.071695,0.050063,0.068648,-0.379209,-0.160180,-0.173783,-0.388828,0.095832,-0.480030,-0.122432,-0.709216,0.081904,-0.214543,-0.422661,-0.045449,0.007443,-0.187629,0.845263,-0.740140,0.183059,0.269428,0.169767,-0.026625,0.584352,0.334601,0.200519,-0.136966,-0.158862,0.009028,0.163761,0.126461,0.225533,0.444100,0.045131,-0.198242,-0.417702,0.481337', '1307146', '3811356', '5977789', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2567646', '福音战士新剧场版：破', '剧情', '在参拜母亲坟墓的回程途中，真嗣（绪方惠美 配音）和葛城美里（三石琴乃 配音）遭遇了第七使徒的攻击，关键时刻2号机势如破竹挫败对手，真嗣也由此结识了2号机的操纵者式波·明日香·兰格蕾（宫村优子 配音）。与沉默寡言的绫波丽（林原惠美 配音）不同，明日香自信张扬，甚至有些自大，在和真嗣相处的日子里，彼此闹出不少的笑话。他们三人分别驾驶着零号机、初号机和2号机，抵抗了第八使徒猛烈的攻击，在这一过程中，淡淡的情愫悄然在这三个青年男女的心中萌生。不久后，第九、十使徒相继降临，真嗣他们面临着生与死的残酷考验……本片为福音战士新剧场版四部曲第二部。©豆瓣', '绪方惠美', '庵野秀明', 9.3, 75539, 'tt0860906', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1026522114.jpg', 0.3, 0.6, 4.9, 22, 72.3, '0.245127,-0.121218,-0.753241,0.701207,0.278026,-0.253975,0.801621,0.083070,-0.217457,-0.173636,0.332987,0.726165,-0.439206,0.120168,0.309792,-0.122061,-0.390418,-0.407443,-0.315667,-0.168007,-0.111553,-0.311450,-0.072816,0.143892,0.083072,-0.404079,0.730114,0.007165,-0.226497,0.554508,0.260383,0.403686,-0.316207,0.353788,0.132850,0.322306,0.038093,0.024027,-0.007781,0.233076,-0.154548,-0.322517,-0.200184,0.261961,-0.057423,0.560923,0.911766,-0.437371,-0.011270,0.114376,0.253804,-0.188985,-0.268247,0.119657,0.455077,-0.085221,0.063520,0.168996,0.202613,0.188847,-0.162319,0.055060,-0.844376,-0.040179,-0.279370,0.008729,-0.281862,0.515727,-0.256873,0.186309,0.414082,-0.092246,0.208672,0.402983,0.383062,0.155303,-0.485587,-0.014764,0.019217,0.047727,0.651224,0.125067,-0.471633,0.443705,-0.125818,-0.422515,-0.514390,-0.298281,-0.391381,-0.227883,0.376070,0.273342,0.121943,0.340176,-0.613074,-0.081385,0.011162,0.013650,-0.155564,-0.193824,0.038837,-0.932997,-0.068191,-0.568887,-0.297032,0.171819,0.091836,-0.230187,0.721854,-0.914812,0.213354,0.478109,0.245392,0.027362,0.321823,0.232787,0.141548,-0.207768,0.065599,-0.052488,-0.332034,0.399048,0.472266,0.712431,-0.186479,0.106793,-0.379214,0.300538', '3811356', '2369613', '20274039', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('2567647', '福音战士新剧场版：Q', '剧情', '14年前，初号机疑似神化第一形态的觉醒带来近三冲击，使世界发生前所未有的巨变。在此之后，葛城美里（三石琴乃 配音）等NERV旧部出走，成立了反抗seele和NERV的Wille。Wille授命明日香（宫村优子 配音）和真里（坂本真绫 配音）夺回被封印在卫星轨道上的初号机和碇真嗣（绪方惠美 配音），但绝对禁止真嗣登上初号机。感受到周遭的敌意，懵懂的真嗣跟随绫波丽（林原惠美 配音）登上突然入侵的九号机，返回了千疮百孔的NERV总部。在这里，他意外重逢朝思夜想的绫波，还从父亲那里得知自己将和美少年渚薰（石田彰 配音）共同驾驶十三号机。长达14年的空白，期间的沧桑巨变和情感纠葛让真嗣不知所措。而看似温柔的渚薰为他揭开了种种难以置信的真相……本片为EVA新剧场版四部曲的第三部。©豆瓣', '绪方惠美', '庵野秀明', 8.4, 62317, 'tt0860907', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p1768906265.jpg', 1.2, 2.9, 16.6, 35.3, 44.1, '0.220224,0.237333,-0.644378,0.517172,0.155224,-0.215207,0.647794,0.120566,-0.286332,-0.284573,0.039761,0.534977,-0.426181,0.103270,0.379386,0.243511,-0.169253,-0.723741,-0.175281,-0.268092,-0.274058,-0.468478,-0.250002,0.077353,-0.025942,-0.439852,1.060416,-0.007794,-0.274544,0.586523,0.242765,0.414188,-0.362687,0.576753,0.191122,0.203865,-0.128572,0.065583,-0.027255,0.109584,-0.168880,-0.350513,-0.053188,0.358566,-0.140566,0.434477,0.771174,-0.304090,-0.247591,-0.002291,0.232554,-0.168920,-0.268703,0.190348,0.373855,0.160949,-0.127741,0.285714,-0.333530,0.178046,-0.153752,0.129736,-0.751425,-0.100583,-0.181867,0.090464,-0.351170,0.329569,-0.199991,-0.040509,0.397920,-0.214933,0.319333,0.585079,0.287890,0.504396,-0.442782,0.158217,-0.025811,0.037921,0.492123,-0.116719,-0.300629,0.363612,0.105537,-0.195181,-0.484712,-0.101658,-0.359806,-0.025410,0.064868,0.280275,0.058885,0.209325,-0.678678,-0.346843,-0.277199,-0.230065,-0.036797,-0.308562,-0.038384,-0.739823,-0.138341,-0.282627,0.024015,-0.051930,0.179569,-0.465693,0.685099,-0.850113,0.288589,0.412096,0.359299,-0.250451,0.187537,0.064875,-0.045635,-0.344325,0.043406,0.146572,0.046727,0.400464,0.187490,0.360772,-0.042563,0.225103,-0.523522,0.343028', '26759819', '2369613', '3266509', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25687245', '诉讼', '剧情', '在以色列并不存在民事婚姻与民事离婚，所有的结婚与离婚必须在犹太教拉比的裁决下才能成为“合法”，然而丈夫一方的权利往往凌驾于第三方的裁决人之上。《诉讼》正是在这样背景下所讲述的故事。故事的主人公薇薇安·阿姆萨勒姆自三年前已经提出结婚，然而她的丈夫伊莱莎并不同意。即使伊莱莎强硬地不肯妥协，薇薇安已经下定决心要争取自己的自由，然而宗教裁决人的态度却是暧昧不清。在三方拉锯的过程中，一幕幕悲剧与荒谬不断上演。', '罗内特·艾尔卡贝兹', '罗内特·艾尔卡贝兹', 8.3, 6263, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2198066908.jpg', 0.3, 1.3, 13.5, 55, 29.8, '0.398524,0.269644,-0.642757,0.559041,0.105208,-0.102849,0.574573,0.017877,-0.492397,-0.323789,0.287015,0.854619,0.001708,0.086295,0.430658,-0.022601,-0.515979,-0.935626,-0.101333,0.045143,-0.214722,-1.127229,0.192986,-0.205104,-0.300215,-0.041146,0.818814,0.034358,-0.111572,0.064572,0.448760,0.251715,-0.347365,0.399417,0.046529,-0.214269,0.072114,0.179135,-0.707417,0.019430,0.267327,-0.098015,-0.377862,0.376529,0.056499,0.293061,0.108902,-0.629993,0.000787,-0.000219,0.403458,-0.161122,-0.048324,0.545684,0.050378,-0.019195,0.384488,0.744409,-0.112085,-0.035100,0.044154,-0.185655,-0.765635,0.050991,-0.001032,0.362655,-0.402102,0.476724,-0.036912,0.292792,0.210829,-0.197315,-0.215411,0.552094,0.505493,0.543997,-0.599596,-0.244515,-0.444086,0.010571,0.799013,0.333844,-0.499969,0.308400,-0.335381,-0.343870,-0.547756,-0.173136,-0.617035,-0.121425,0.168898,0.437415,-0.250691,0.745600,-0.479804,-0.250773,-0.154863,-0.177259,0.113564,-0.435182,0.125773,-0.404447,-0.358588,-0.318669,-0.606123,0.187229,0.129904,-0.356402,0.450847,-0.950160,0.295258,0.430021,0.538671,-0.501072,0.429843,0.599168,0.450492,-0.459666,-0.041011,0.574500,0.128916,0.023973,0.002255,0.011750,0.246430,0.119825,-0.348072,0.714540', '30345227', '24325856', '27202818', '25978126');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25697098', '裁缝', '剧情', '蒂莉（凯特·温丝莱特 Kate Winslet 饰）回到了阔别已久的家乡，在十岁的时候，她因为被控谋杀了同学斯图尔特（Rory Potter 饰）而遭到了整个小镇的驱逐，就连蒂莉的母亲茉莉（朱迪·戴维斯 Judy Davis 饰）也不相信蒂莉的清白。虽然这么多年过去了，但蒂莉在这里依然是一个不受欢迎的存在，邪恶的一员伊万（沙恩·伯恩 Shane Bourne 饰）依然掌握着小镇居民们生死存亡的命脉，与此同时，他还有着另一个身份——斯图尔特的父亲。蒂莉在小镇上开了一家裁缝铺，随着时间的推移，她所售卖的款式新颖的服装和闪闪发亮的布料为她俘获了一批忠实的顾客。实际上，蒂莉一直没有放弃调查当年事件的真相，她并没有杀人，她坚信当年的那个凶手如今依然生活在这座小镇里。©豆瓣', '凯特·温丝莱特', '乔瑟琳·穆尔豪斯', 7.9, 121431, 'tt2910904', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2287885206.jpg', 0.2, 1.8, 22.8, 51.5, 23.6, '0.305302,0.175140,-0.728062,0.611351,-0.362267,-0.157244,0.974677,0.091750,-0.516672,-0.536062,0.273702,0.841866,0.046083,0.138263,0.080860,0.352516,-0.318662,-0.535159,0.093709,-0.496141,-0.224488,-0.490761,-0.460762,-0.209985,-0.150768,-0.205686,0.587631,0.228335,-0.175128,0.361054,0.283345,0.289857,0.078335,0.362463,-0.435490,-0.002789,0.307259,-0.043645,-0.031712,0.312574,-0.093125,-0.305227,-0.051915,0.289411,-0.003647,0.564068,0.620520,-0.402841,-0.086812,0.097560,0.273463,-0.322681,0.095096,0.192503,0.523356,-0.305270,0.169547,0.205033,-0.398541,-0.043261,0.076559,-0.113959,-0.892757,-0.041550,0.225786,0.342263,-0.829255,0.750983,-0.269485,-0.239284,-0.016926,-0.521270,0.273285,0.446268,-0.035661,0.288487,-0.082770,0.030970,-0.764475,0.132533,0.677122,0.119749,-0.107336,0.389269,-0.435148,-0.356476,-0.159880,-0.243486,-0.649189,-0.104634,0.361863,0.039085,-0.182592,0.176598,-0.562319,0.091311,-0.136842,-0.320071,0.193619,-0.330153,-0.215169,-0.541668,-0.036209,-0.637246,-0.300233,-0.090252,-0.126855,-0.091529,0.675615,-0.964985,0.350110,0.473285,0.326959,-0.481434,0.682084,0.181296,0.179945,-0.063258,-0.208738,0.328332,0.143697,0.374644,0.198779,0.443292,0.190152,-0.362198,-0.443005,0.701342', '1783461', '3055049', '1793491', '10774184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25700838', '人间中毒', '剧情', '越战英雄军官金镇平（宋承宪 饰）新接收了一个部下荆宇真大卫（温朱万  饰），荆大卫的妻子钟佳欣（林智妍 饰）也随丈夫一同住进了军队官邸。镇平为佳欣的魅力所吸引无法自拔，以致发展出一段军中不伦之恋。该影片由执导过《方子传》、《淫乱书生》等影片的导演金大宇导演执导。一直以偶像形象示人的宋承宪首度挑战大尺度裸露戏份。', '宋承宪', '金大佑', 6.6, 74821, 'tt3303730', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2208681237.jpg', 2.2, 13.4, 48.4, 25.3, 10.7, '-0.454472,-0.059659,-0.069933,0.550693,0.309038,-0.161357,0.133581,0.581339,-0.199639,-0.177025,0.317266,0.528563,-0.237803,-0.038013,0.417264,-0.365305,-0.085149,-0.470213,-0.317964,-0.018375,0.163103,0.020675,-0.226491,-0.033861,0.009517,-0.344144,0.580874,-0.048033,-0.402483,0.299902,0.645091,0.000416,-0.200400,0.041014,0.554479,-0.038593,0.195694,0.055944,-0.444360,0.107366,-0.169100,-0.229576,-0.043512,-0.050202,-0.069686,0.207541,0.473124,-0.289502,0.017909,-0.222888,0.693050,0.320251,0.067216,-0.235975,-0.082382,0.006136,0.185409,0.080701,-0.132536,0.210826,-0.215395,-0.187832,-0.556290,-0.081110,0.124178,-0.074812,-0.488627,0.084375,-0.190618,0.021613,-0.005974,-0.143991,-0.094105,-0.008666,0.355670,0.067530,-0.022944,0.257735,-0.061081,0.936552,0.217761,0.138246,-0.092263,0.098280,-0.148570,-0.513543,-0.388712,-0.193921,-0.746541,0.227426,0.250010,-0.352654,0.280787,-0.007511,-0.259388,-0.251048,-0.372195,0.144535,0.102329,0.014626,0.289714,-0.648823,-0.115665,-0.085858,0.260703,-0.145724,0.206219,0.070493,0.674303,-0.241216,0.045288,0.219244,0.284857,-0.684227,0.421273,0.303292,-0.056809,-0.217756,-0.140040,0.335061,-0.003747,0.017449,0.253550,0.284335,-0.178773,-0.587590,-0.287280,0.156332', '6869395', '1388176', '10833970', '7161707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25701866', '信号', '科幻', '双腿受伤的尼克（布伦顿·思韦茨 Brenton Thwaites 饰）和女友海莉（奥莉维娅·库克 Olivia Cooke 饰）以及好哥们约拿（伯乌·内普 Beau Knapp 饰）正在进行一段喜乐参半的漫长旅行。在此之前，就读于麻省理工的他一直和约拿在追踪一个黑进学校网站的天才骇客，经过一段时间的努力，他们终于抓住骇客的踪迹。二人扬言揭发对方，谁知对方竟仿佛在他们身边监视着一样。旅途继续，夜幕降临，三人准备在一个废弃的小屋落脚。就在此时屋外传来海莉的呼救声，而尼克也被人重重击倒。当他再度醒来，只见到穿着防辐射衣服的陌生男子（劳伦斯·菲什伯恩 Laurence Fishburne 饰）在和他说话。此时此刻，他仿佛置身一个关于外星生物的巨大阴谋之中，噩梦永远没有尽头……©豆瓣', '帕特里克·戴维森', '威廉·尤班克', 6.1, 7692, 'tt2910814', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2175985329.jpg', 5.3, 19.8, 47.8, 20.3, 6.8, '0.310435,-0.049394,-0.757389,0.329002,-0.039477,-0.232369,0.834882,0.037090,-0.344498,-0.485827,0.325153,0.529708,-0.307142,0.179235,0.250340,0.027673,-0.442106,-0.858473,0.047766,-0.205209,-0.425944,-0.226045,-0.392445,-0.154801,0.141900,-0.273791,0.550671,-0.054235,-0.127585,0.561368,0.091250,0.146556,-0.389430,0.499112,-0.355542,-0.165791,0.151948,-0.071741,-0.196532,0.155584,-0.142075,-0.280217,-0.173647,0.048982,-0.064665,0.334356,0.598324,-0.323473,0.017713,0.277105,0.221937,-0.245031,0.040094,0.093172,0.246631,-0.052014,0.210426,0.037496,-0.260208,-0.063802,0.137793,-0.189713,-0.311093,-0.017191,-0.153228,0.522187,-0.388461,0.421827,-0.113331,0.014983,0.157497,-0.415125,0.071235,0.203633,0.096733,0.391028,-0.114045,0.047613,-0.610449,0.057785,0.415353,-0.006080,-0.035918,0.179858,0.128965,-0.217148,-0.104501,0.191467,-0.448739,-0.289494,0.512827,0.059634,-0.230312,-0.085145,-0.487923,0.178140,-0.160554,-0.284731,-0.145996,-0.430910,-0.327206,-0.758492,0.039491,-0.197109,-0.235568,0.421433,-0.141347,-0.102027,0.245558,-0.568714,0.520589,0.491276,0.147370,0.030531,0.455928,-0.100004,0.258421,-0.176839,-0.161496,0.274333,0.293550,0.446337,0.211180,0.406595,-0.127259,0.104334,-0.748034,0.319817', '30136177', '1316693', '10466639', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25703430', '金鸡SSS', '剧情', '经过不懈的努力和拼搏，阿金（吴君如 饰）总算从一介小小妓女“升职”成为了“妈妈桑”，带领着手下吴露（王菀之 饰）、阿花（卫诗雅 饰）、莫娜（林宜芝 饰）等小姐妹们，过着自由自在，灯红酒绿的无忧生活。时光荏苒如同白驹过隙，每一日，香港这座城市都绽放出崭新的姿态，尽管如今生活更加便利，更加多姿多彩，但阿金有时却还是会怀念起曾经的旧日时光。前黑道老大哥顿（张家辉 饰）被捕入狱，当他重见天日之时，整个香港已经变成了他完全不认识的模样，于是，哥顿找到了阿金，却发现她也不再是往日的天真少女，得知哥顿心中的遗憾和失落，阿金决心帮助哥顿重新找到生活的方向。©豆瓣', '吴君如', '邹凯光', 6.2, 26596, 'tt3451660', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2166382280.jpg', 4, 17, 49.7, 21.9, 7.5, '-0.246523,0.128064,-0.569387,0.385976,-0.061583,-0.637313,0.769197,0.081550,-0.558220,-0.250676,0.066420,0.471169,-0.133041,0.669254,0.234789,-0.034327,-0.521123,-0.662255,-0.077913,-0.294953,0.086710,-0.081431,-0.349231,0.127186,-0.173479,-0.226996,0.418706,0.091645,0.082475,0.586970,0.181578,0.173008,-0.109001,0.350025,-0.379462,0.029180,-0.047681,0.235727,-0.387312,-0.205967,0.020903,-0.162233,-0.334379,0.071088,0.182213,0.233698,0.713132,-0.142819,-0.332783,-0.183114,0.154355,-0.010659,-0.029705,0.076269,-0.123435,0.141454,0.105251,0.112759,-0.125973,0.142966,0.047506,-0.249956,-0.445942,0.221072,0.176517,0.128203,-0.563481,0.214637,-0.012238,-0.186474,0.064794,-0.597107,0.065690,0.289452,0.325686,0.458795,-0.278499,0.202579,-0.588131,0.335681,0.773075,0.217446,-0.389583,0.466179,-0.133369,-0.336346,0.230015,-0.077863,-0.267055,-0.079228,0.051998,0.121155,-0.117950,0.445788,-0.627770,0.175734,-0.274802,-0.059412,0.104839,-0.267785,0.045967,-0.467642,-0.218975,-0.557373,-0.413147,0.016424,-0.110114,-0.252026,0.648391,-0.857769,0.358331,0.119199,0.340621,-0.236441,0.278720,0.031205,0.098578,-0.018248,0.309617,0.512377,-0.127136,0.356791,-0.073174,0.097180,-0.270362,-0.249715,-0.386116,0.466427', '1292219', '5977789', '2365260', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25704492', '红雀', '剧情', '多米尼卡（詹妮弗·劳伦斯 Jennifer Lawrence 饰）本是一名芭蕾舞演员，在一场意外中负伤，导致她无法再继续经营自己热爱的舞蹈事业。之后，多米尼卡在被迫的情况下被训练成为了一名间谍，代号“红雀”。她被上级指派潜伏在一位名叫内森尼尔（乔尔·埃哲顿 Joel Edgerton 饰）的美国中情局特工身边，套取他手中掌握的间谍名单。哪知道原本的逢场作戏竟然让多米尼卡动了真情，她和内森尼尔双双坠入了情网之中，后者也了解到了多米尼卡的悲惨身世，为了帮助爱人复仇，内森尼尔决定成为一名双重间谍，帮助多米尼卡揪出安插在美国军方中的俄罗斯间谍。©豆瓣', '詹妮弗·劳伦斯', '弗朗西斯·劳伦斯', 6.4, 51683, 'tt2873282', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2519628553.jpg', 2.3, 14.2, 50.3, 25.5, 7.7, '0.139188,0.076710,-0.644835,0.656565,-0.157150,-0.266321,0.524789,0.013957,-0.520236,-0.207608,0.398816,0.749956,0.142750,0.058848,0.646802,0.030622,-0.517771,-0.997290,-0.079367,-0.363655,-0.332958,-0.676368,-0.682951,-0.136655,-0.278149,-0.447198,0.530099,-0.120016,-0.151487,0.378099,0.178128,0.547844,0.059694,-0.024380,0.036134,-0.047814,0.796108,-0.462116,-0.212474,0.387969,-0.140773,-0.285114,0.053677,0.168831,0.123024,0.293788,0.664691,-0.382477,0.098266,-0.355238,0.067774,-0.247508,0.163764,0.372607,0.316335,-0.074639,0.150814,0.220762,-0.439496,-0.002203,0.310620,-0.085107,-0.943329,-0.180636,-0.059689,0.284229,-0.652153,0.097067,-0.353794,-0.192706,0.035374,-0.106395,0.115642,0.414064,0.384347,0.188241,-0.279602,-0.002998,-0.430678,0.015911,0.708817,0.066312,-0.129098,0.027793,0.039076,-0.432528,-0.066691,-0.203871,-0.284599,-0.142874,0.551391,-0.138581,-0.019342,0.229182,-0.497358,0.038150,-0.593687,-0.142236,-0.394544,-0.461825,0.054018,-0.415235,-0.203377,0.007373,-0.151105,-0.018680,-0.011301,-0.444630,0.734985,-0.715324,0.366415,0.820641,0.251077,-0.314449,0.286374,0.197926,0.416614,-0.181472,-0.006276,0.360842,0.123573,0.182906,-0.090307,0.346773,0.133021,-0.367890,-0.085168,0.227866', '1307442', '1793491', '1418190', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25704588', '不求上进的玉子', '喜剧', '出生在甲府一座平凡小镇的坂井玉子（前田敦子 饰），完成了东京的大学学业后返回故乡，成为终日懒散度日、百无聊赖的家里蹲。玉子的父亲善次（康すおん 饰）经营一家体育用品专卖店，他早年和妻子离婚，长女出嫁有了自己的生活，日常里善次和这个23岁还赖在家中的小女儿相依为命，虽然对玉子穷发牢骚与五体不勤的人生作派颇有微词，却似乎又甘愿为了女儿做牛做马。经营、洗衣、做饭，善次马不停蹄，而另一边的玉子看漫画、睡懒觉、吃剩饭、发呆，活在自己的小世界中。春夏秋冬，四季流转，父女俩习惯了如此寡然无味的相处，期待生活有所转机的同时，也静静注视着周遭一切的自然消亡……本片荣获2013年电影旬报十佳影片第九名。©豆瓣', '前田敦子', '山下敦弘', 7.3, 38385, 'tt3134060', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164912258.jpg', 0.9, 4.7, 37.4, 42.1, 14.9, '-0.113244,-0.031041,-0.746595,0.346051,-0.067942,-0.258067,0.408487,0.447772,-0.519609,-0.482499,0.002989,0.833357,-0.029451,0.624504,0.194879,-0.058956,-0.271201,-0.581099,-0.092071,-0.074709,0.006562,-0.157861,-0.051579,-0.180386,-0.335717,-0.036695,0.540461,-0.034002,0.178239,0.499347,0.102456,-0.064234,-0.028853,0.221647,-0.421705,0.094598,-0.150987,0.341607,-0.133848,0.002608,0.094062,-0.266330,-0.137477,-0.273786,0.435777,0.310374,0.863311,0.018952,-0.333594,-0.266691,0.394108,-0.149315,-0.386851,0.190524,0.272647,-0.043715,0.051335,0.025553,-0.339941,-0.022988,-0.188042,-0.079796,-0.448977,-0.205319,0.162758,0.090473,-0.585620,0.626959,0.249855,-0.318326,-0.038329,-0.350235,0.235468,0.384381,0.218130,0.542450,-0.160912,0.295407,-0.489144,0.349344,0.358515,0.089119,-0.057159,0.619637,-0.207129,-0.082260,0.133983,-0.243652,-0.729238,-0.353736,-0.244324,0.056918,-0.014342,0.211233,-0.393755,0.286911,0.191050,-0.220732,0.331019,-0.486188,-0.303204,-0.560264,0.083504,-0.557575,-0.380619,0.157831,0.251614,-0.322504,0.672834,-0.616712,0.231060,0.154590,0.371222,-0.409908,0.823932,0.074701,0.384794,-0.062087,-0.009241,0.514197,-0.189396,0.066056,-0.076715,0.308019,-0.212161,0.176347,-0.430845,0.529866', '26958479', '3732800', '1308609', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25705507', '生命如此美好', '剧情', '一部根据真实事迹改编的电影：讲述了一个男孩生下来残疾并不能说话，大家都以为他是像植物一样什么都不懂，后来他被送到精神病院，被医生发现他听得懂并教他怎么表达，用了近三十年时间证明自己拥有心智的故事。', '大卫·奥格尼克', '马切伊·佩普日察', 8.3, 12453, 'tt3092552', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2191670715.jpg', 0.3, 1.3, 13.9, 51.9, 32.6, '0.347809,0.075945,-0.504606,0.436080,-0.386393,0.061156,0.390198,-0.645365,-0.424964,-0.451897,-0.258648,0.419982,-0.150456,0.115504,-0.572032,0.003122,-0.237781,-0.417485,0.226342,0.014795,-0.171927,-0.456179,-0.046028,0.164988,0.007024,-0.305845,0.235101,-0.128424,-0.435570,-0.037002,-0.016800,-0.220197,0.269521,0.113744,-0.121566,0.463144,-0.133109,0.094980,0.125196,0.177661,0.307278,0.045237,-0.067348,0.287335,-0.423649,0.435529,0.384316,-0.149044,-0.518277,0.216427,0.553257,-0.147238,0.027193,0.100646,0.155969,0.122585,0.219255,0.156398,-0.078130,0.276399,-0.250398,0.485998,-0.868765,-0.192755,0.037650,0.440445,-0.650771,0.172112,-0.062671,-0.138477,-0.183018,-0.492738,0.234920,-0.010422,0.540027,0.528394,-0.086082,-0.323789,-0.932885,0.283261,0.953488,-0.215728,-0.739636,0.894174,-0.258869,-0.502596,-0.153794,-0.348789,-0.323254,0.465499,-0.261080,-0.083636,-0.420186,-0.021173,0.164627,-0.178947,-0.029135,-0.259694,0.089862,-0.791644,0.069295,0.061271,-0.134838,-0.338116,-0.292987,-0.510893,0.099107,-0.681366,0.938359,-0.630448,0.273349,0.448533,0.187280,-0.546084,0.500950,0.157753,-0.380674,-0.246974,0.220326,0.318783,0.466529,0.013552,0.417621,0.197528,0.180129,-0.211631,-0.502856,0.526813', '1306530', '1877596', '30163500', '25823663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25706773', '硬核亨利', '动作', '亨利（伊利亚·奈舒勒 Ilya Naishuller 饰）在某场事故中失去了记忆，连自己的名字都不记得了，他只知道眼前的这个美丽的女人艾斯戴尔（海莉·贝内特 Haley Bennett 饰）是自己的妻子。然而很快，艾斯戴尔就被一个名叫阿康（丹尼拉·科兹洛夫斯基 Danila Kozlovskiy 饰）的男人给绑架了。阿康是一个野心勃勃的邪恶的男人，他拥有自己的军队和军火库，人生的目标就是统治世界。在全无记忆的状态下，亨利必须在时限内奋力营救自己的妻子，想要置他于死地的人貌似很多，可亨利也不知道他们究竟是为了什么。亨利可以相信的，只有一个叫做吉米（沙尔托·科普雷 Sharlto Copley 饰）的男人，但是这个神秘的男人真的可以信赖吗？©豆瓣', '沙尔托·科普雷', '伊利亚·奈舒勒', 7.7, 55618, 'tt3072482', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2317785167.jpg', 1.3, 4.4, 26.4, 42.1, 25.8, '0.320880,0.176602,-0.745400,0.626791,-0.624172,-0.290512,0.854643,-0.105167,-0.449274,-0.299393,0.068170,0.880068,0.101179,0.116848,0.135138,0.442757,-0.116517,-0.770403,-0.155720,-0.156294,-0.532501,-0.654628,-0.451275,-0.475110,0.050346,-0.213024,0.645082,0.003714,-0.195467,-0.112434,0.521004,0.394782,0.186515,0.698957,-0.439828,0.174304,0.068521,-0.272581,-0.059223,0.188119,-0.001043,-0.258152,-0.043406,0.459504,-0.250818,0.464218,0.440980,-0.544334,-0.019970,-0.019607,0.243345,-0.289170,-0.056116,0.030053,0.070536,-0.467020,0.195028,0.047078,-0.146831,-0.181607,0.290887,-0.046373,-1.006626,-0.089061,0.171551,0.321455,-0.631503,0.433875,-0.244262,-0.187233,0.231956,-0.229805,0.331151,0.246117,0.275882,0.342948,-0.132126,-0.185099,-0.787139,0.009680,0.514979,0.010453,-0.307235,0.578213,-0.327912,-0.463242,-0.398457,-0.102083,-0.646596,0.091213,0.296549,0.022579,-0.353278,0.064921,-0.425776,0.021879,-0.186659,-0.126093,-0.232285,-0.600906,-0.225419,-0.011277,-0.157868,-0.501306,-0.306199,-0.006772,0.050794,-0.245200,0.720716,-1.035030,0.200981,0.790225,0.147920,-0.516004,0.697505,0.386639,-0.023780,-0.314739,-0.058427,0.262000,0.217509,0.072241,0.039930,0.513848,0.282407,-0.086488,-0.355706,0.960832', '1783461', '25763555', '1949005', '3230462');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25708452', '极速之巅', '动作', '凯西（尼古拉斯·霍尔特 Nicholas Hoult 饰）是一个无所事事整日里游手好闲的小贼，因为在美国前科太多，罪行累累，而最终决定逃往德国。在那里，凯西成为了大毒枭格兰（本·金斯利 Ben Kingsley 饰）的手下。虽然对于一个正常人来说，为毒枭卖命并不算是一份健康的工作，但对于过惯了颠沛流离生活的凯西来说，他感到很满足。某日，凯西得知自己的恋人朱丽叶特（菲丽希缇·琼斯 Felicity Jones 饰）患上了重病，急需肾脏移植，为了筹得巨额的医疗费，凯西决定先将自己的安危放到一边，做一单大买卖。哪知道这一单大买卖令凯西被卷入了和德国最大的毒枭哈根（安东尼·霍普金斯 Anthony Hopkins 饰）的利益纠葛之中。©豆瓣', '尼古拉斯·霍尔特', '伊兰·克里维', 5.1, 5833, 'tt2126235', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2402073066.jpg', 10.2, 34.9, 45.1, 7.8, 2, '0.296123,-0.023793,-0.501513,0.343051,-0.171033,-0.351430,0.675193,0.277467,-0.655605,-0.358315,0.004237,0.986957,0.157253,0.109863,0.288667,0.138469,-0.156735,-0.408434,-0.065417,-0.249874,-0.201976,-0.850409,-0.334145,-0.346445,-0.428529,-0.115996,0.456411,-0.049551,-0.019844,0.308875,0.484090,0.477161,0.260274,0.274902,0.026160,-0.221044,0.026257,0.058785,-0.323309,0.252857,0.209343,-0.113906,0.102887,0.218957,0.333911,0.338357,0.383382,-0.478848,-0.101805,-0.408326,0.309713,-0.363191,-0.119288,-0.081722,0.045167,-0.003018,0.248813,0.076734,-0.488727,0.051928,0.439161,-0.191268,-0.863322,-0.261201,0.090781,0.243705,-0.783202,0.388443,-0.078535,-0.145287,0.076331,-0.275398,-0.008341,0.537902,0.193683,0.244330,-0.173286,0.162186,-0.616705,0.053295,0.585987,-0.068178,0.105247,0.265607,-0.361500,-0.354309,0.065344,-0.326921,-0.268464,-0.058771,-0.008782,-0.156704,-0.135891,0.546772,-0.389262,0.167874,-0.345495,-0.377816,-0.114104,-0.338868,-0.059873,-0.508117,-0.178559,-0.452308,-0.424460,0.052399,0.287320,-0.354097,0.564848,-0.812460,0.024072,0.502859,0.389785,-0.429270,0.322873,0.237271,0.408016,-0.191248,-0.243931,0.253177,0.174131,0.058106,0.301992,-0.096376,0.024390,-0.539428,-0.134431,0.441619', '1783461', '1793491', '34968329', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25709273', '痞子英雄2：黎明升起', '剧情', '重案组刑警吴英雄（赵又廷 饰）在拯救客机后成为警界明星，出演各种警队宣传片风光无两。是日，海港城陷入突然危机，高铁、跨海大桥等交通要道突发连环爆炸，吴英雄在追索嫌凶过程中与东区分局刑事侦查组刑警陈真（林更新 饰）结为搭档，又再度重逢被逼做人肉炸弹的通缉犯徐达夫（黄渤 饰）。原来，一号为“夜行者”的神秘组织绑架了徐达夫等通缉犯的家属，逼迫他们作为人肉炸弹将海港城通向外界的各通路炸毁，使海港城变为孤城，以释放生化病毒，执行毁灭城市的“枯草计划”。吴英雄和陈真为解救徐达夫妻子杜小晴（关颖 饰）并阻止枯草计划，与鉴识官蓝西英（张钧甯 饰）、黑鹰队成员黄世楷（修杰楷 饰）等人向夜行者发起挑战。©豆瓣', '赵又廷', '蔡岳勋', 5.6, 52902, 'tt3421246', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199416829.jpg', 7.9, 25.7, 48.8, 13, 4.6, '-0.232218,-0.006882,-0.285038,0.503298,0.341240,-0.049049,0.435819,0.216764,-0.276432,-0.075100,0.040759,0.153940,-0.272043,0.029102,0.340953,-0.535743,-0.338195,-0.559956,-0.272121,-0.057339,-0.598847,-0.302577,0.071106,-0.360257,0.136564,-0.064733,0.740689,0.396527,-0.317072,0.105784,0.369378,0.437889,-0.437364,0.414235,0.016183,-0.006041,0.369274,-0.045795,-0.421095,0.262275,-0.350613,-0.261656,0.098851,-0.006668,0.120958,0.301247,0.785425,-0.045252,0.013041,-0.386511,0.081149,-0.381424,0.215521,-0.239693,0.818996,-0.193246,-0.238199,-0.100157,-0.061112,0.086440,0.197942,-0.220816,-0.512649,-0.154893,0.338119,-0.000823,-0.330466,-0.102575,-0.302454,0.172315,0.155244,0.110377,0.330482,0.303517,0.465148,0.159348,0.150724,0.330648,-0.437756,0.356197,0.508750,-0.072030,-0.228465,-0.446055,0.169348,-0.664669,-0.128836,-0.057267,0.054550,-0.066387,0.337230,-0.307776,0.341437,0.133669,-0.536203,-0.240210,-0.097099,-0.071050,-0.053733,-0.312404,0.012679,-0.963861,0.364915,-0.025390,0.270701,0.361594,0.162791,0.093458,0.349637,-0.513362,0.064036,0.170465,0.133352,-0.633626,0.362081,-0.006772,0.184046,-0.640111,0.290454,0.040378,0.575610,0.525447,0.334774,0.231840,-0.312209,-0.207862,-0.110238,-0.047349', '1306809', '2369613', '25723905', '1300371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25710797', '庆州', '剧情', '《庆州》讲述的是为了追溯过往的回忆而独自前往庆州的一个男人旅途中发生的故事。朴海日饰演踏上旅途的男人，而申敏儿则饰演他在旅途中遇到的茶馆女老板，两人也上演了微妙而浪漫的爱情故事。', '朴海日', '张律', 7.7, 8422, 'tt3675906', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2184954876.jpg', 0.7, 3.2, 26.5, 48.4, 21.3, '0.564483,-0.272517,-0.676069,0.734075,0.212305,-0.015535,1.344383,0.003124,-0.588437,-0.166009,0.479412,0.922636,-0.160758,0.304762,1.082116,-0.201874,-0.370146,-0.829058,0.091005,0.002496,-0.137597,-0.417663,0.030005,-0.141631,0.042599,-0.296881,0.927250,0.455156,-0.251523,0.695383,0.346107,0.337694,-0.674181,0.550818,-0.269110,0.133859,-0.129109,0.543743,-0.232530,0.096223,0.084979,-0.579905,-0.262065,-0.095660,-0.319391,0.243311,1.017665,-0.218324,-0.063370,0.221878,0.252805,-0.460837,-0.041144,-0.307048,-0.056150,0.236325,0.379400,0.391484,-0.124246,-0.195522,-0.086102,-0.321851,-0.752823,0.106465,0.122185,0.487992,-0.255454,0.352453,0.493204,-0.110466,0.489493,-0.260081,0.376738,0.233438,1.026542,0.235543,-0.067812,-0.194337,-0.241825,0.395762,0.777043,0.052117,-0.186940,0.894896,-0.311844,-0.290677,0.003761,0.024536,-0.748640,0.173285,0.007620,-0.072140,-0.242537,0.385045,-0.656219,0.287368,-0.157348,-0.388087,0.096883,-0.253966,-0.361607,-0.916396,-0.263923,-0.579874,0.103745,-0.216977,0.193664,-0.378647,0.436535,-0.677106,0.102352,0.750149,-0.145890,-0.532991,0.840487,0.232752,0.383807,-0.156504,0.132269,0.614890,-0.328532,-0.016705,-0.511305,0.317720,-0.663241,0.246183,-0.944915,0.569825', '10466639', '1296534', '1467779', '1297598');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25710912', '港囧', '喜剧', '徐来（徐峥 饰）大学时代的理想是能够成为一名出色的油画家，他的坚持和不屈吸引了美丽女孩杨伊（杜鹃 饰）的注意，随着时间的推移，他们相爱了。然而，徐来的这段初恋却最终被残酷的现实所粉碎，之后，他同一直守候在自己身边的内衣公司老板千金蔡波（赵薇 饰）走到了一起。毕业后，徐来和蔡波结婚，成了蔡家的“上门女婿”，他放弃了理想，开始经营内衣公司，尽管事业蒸蒸日上，但徐来的心中始终留存着一抹遗憾。某日，徐来意外得知如今已经成为画家的杨伊将在香港举行她的个展，心中五味杂陈的他带着一家老小前往香港，名为旅游，实则是相同杨伊“再续前缘”。然而，徐来的计划却屡屡遭到小舅子蔡拉拉（包贝尔 饰）的破坏，蔡拉拉正在拍摄一部家庭纪录片，在他的镜头背后，徐来发现了一个陌生的自己。©豆瓣', '徐峥', '徐峥', 5.7, 379722, 'tt4242158', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2266145079.jpg', 8.4, 25.5, 45.7, 15, 5.3, '0.225237,0.421749,-0.572515,0.507959,-0.086067,-0.312922,0.575422,0.326559,-0.591514,-0.220882,0.114010,0.616282,-0.164404,0.416998,0.274361,0.155784,-0.145886,-0.683654,-0.021370,-0.084250,-0.069914,-0.412462,-0.273116,0.000557,-0.255684,0.127442,0.794137,0.191930,0.030535,0.748864,0.448159,0.169368,-0.128761,0.616754,-0.215704,0.107489,0.192215,0.078022,-0.273501,0.106786,0.189305,-0.294773,-0.108528,0.016599,-0.032481,0.415867,0.575979,0.098891,-0.023693,0.165855,0.624137,-0.258551,0.022450,-0.001019,0.321485,0.193131,0.144846,0.130099,-0.241690,-0.077450,0.067510,-0.109903,-0.605207,0.051475,0.406036,0.019969,-0.724181,0.561568,-0.101215,-0.196667,0.079130,-0.522536,0.318264,0.442966,0.403965,0.502358,-0.047601,0.368211,-0.477154,0.441078,0.668305,-0.023273,-0.200272,0.343457,-0.351197,-0.301429,-0.297189,-0.183658,-0.549528,-0.072584,0.397694,0.222334,-0.088568,0.031757,-0.454699,-0.030507,-0.138412,-0.032940,0.131808,-0.513307,-0.003712,-0.572512,-0.283961,-0.474465,-0.423515,0.049194,0.078624,-0.492069,0.658539,-0.796962,0.165468,0.531950,0.213605,-0.368412,0.737703,0.287991,0.306513,-0.185371,-0.052914,0.391241,-0.048571,0.230415,0.054941,0.405477,-0.152228,-0.149041,-0.399881,0.408964', '35030151', '3445516', '3811356', '26021055');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25711527', '世界奇妙物语 2013年秋之特别篇', '剧情', '《0.03帧的女人》影视从业人员日暮美和（夏菜 饰）在为某电视剧做编辑时，在素材中发现一个仅出现0.03帧的神秘女子，她恶作剧将该帧延长到3秒，然而此后看过该片段的相关的人员竟接连死亡。《水的保管》正陷入创作瓶颈的原著名编剧汤原直也（香取慎吾 饰）迎来意外访客，自称隔壁邻居美丽女大学生水野（夏帆 饰）拜托他帮忙保管两箱水。疲劳焦虑的汤原开始想入非非，幻觉丛生。《人体微波炉》入职30年还是普通职员的久米清（志贺广太郎 饰）被同侪称为吃闲饭（工资小偷）的，女儿朋美（真野惠里菜）为了鼓励父亲，买来一台庞大的心灵微波炉。经微波炉加热后，久米全身充满正能量，以饱满的激情和斗志投入社会之中。《模拟结婚》为终身大事烦恼的单身OL盛田成美（石原さとみ 饰），偶然遇到自称模拟结婚咨询员的并木（北村有起哉 饰）。在对方的介绍下，成美打算通过模拟结婚体验一下婚后生活。《有一天，天上掉下个炸弹》未卜前途的青年远山聪（松坂桃李 饰）在房顶发呆，这时天上掉下一个自称帕鲁卡炸弹的女孩（黑木华 饰），与远山的高中同学永峰遥香长得一模一样。快乐的约会，往昔的回忆，唏嘘的结局。', '夏菜', '石井克人', 6.8, 7918, 'tt3262716', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2153940790.jpg', 0.7, 8, 51.9, 30.1, 9.2, '0.063956,0.158502,-0.394508,0.151383,0.055454,-0.070203,0.472381,0.166776,-0.315105,-0.414990,0.091507,0.404337,-0.406264,0.379552,0.204006,-0.087100,-0.157934,-0.564537,-0.110264,-0.081173,-0.233257,-0.278069,-0.248369,0.051301,-0.009509,-0.242632,0.453476,-0.045029,0.109035,0.307438,0.104926,0.080859,0.014189,0.144551,-0.002439,-0.011125,-0.088704,0.194152,-0.413062,0.060035,-0.216225,-0.209299,0.016722,-0.108915,0.145144,0.182160,0.698948,-0.078338,-0.201926,-0.082947,0.521180,0.062775,-0.196325,-0.019220,0.093868,0.291006,-0.014138,-0.109977,-0.337565,0.233287,0.141024,-0.120436,-0.545160,-0.068755,0.102074,0.212277,-0.189685,0.301207,-0.103660,0.073426,0.159546,-0.184284,-0.077711,0.061573,0.371896,0.538616,-0.254319,0.307014,-0.069649,0.340292,0.446398,0.107090,-0.171346,0.486166,-0.144300,-0.260406,0.069194,0.044923,-0.275378,0.020324,0.001026,0.113455,0.002419,0.137206,-0.601007,-0.026915,-0.002705,0.081889,0.117400,0.004129,-0.494483,-0.473578,-0.040982,-0.161555,-0.364888,0.201381,0.272923,-0.275522,0.680008,-0.488288,0.114860,0.420695,0.218610,-0.127407,0.503821,0.021296,-0.116695,-0.332481,-0.184610,0.147305,0.019373,0.222479,-0.011921,0.290905,-0.351027,-0.122542,-0.497510,0.083781', '3811356', '5403927', '4181031', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25713336', '盗马记', '喜剧', '某晚，一辆运送文物的卡车发生车祸，内中昭陵六骏之一的唐三彩“飒露紫”失窃，引起国内外极大关注。在此之后，热爱攀岩的电视台女主持夏梅（陈慧琳 饰）被派到英国伦敦参加某拍卖行的活动，借机调查“飒露紫”的下落。谁知在会场她的隐形耳机信号和警官张浩（郑伊健 饰）的耳机信号相冲突，以致于暗访行动以失败告终。在此之后，张浩主动登门拜访，告知神秘狡猾的国际大盗九尾狐（梁家辉 饰）很可能将“飒露紫”锁定为下一个偷盗目标。从暗访录像中，他们果然也看到一个疑似九尾狐的身影出现。为了彻底查到“飒露紫”的下落，夏梅请缨留在伦敦，而此时九尾狐也主动接近夏梅。浪漫而紧张的文物追查之旅由此展开……©豆瓣', '梁家辉', '李志毅', 5, 17413, 'tt3573354', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2171256764.jpg', 13, 36, 40.4, 7.8, 2.8, '0.237269,0.357603,-0.767784,0.606875,0.175973,0.140803,0.451418,0.084753,-0.472418,-0.192681,0.373811,0.554489,-0.340939,-0.096090,0.274289,0.000316,-0.173013,-0.604932,-0.184574,-0.149832,-0.330166,-0.145600,-0.188160,-0.062828,-0.016427,-0.194487,0.386936,0.349074,-0.413508,0.581253,0.543781,0.286518,-0.556250,0.478073,0.184945,-0.317339,0.147867,0.043861,-0.163531,0.583778,-0.180020,-0.286591,0.111492,0.046712,-0.053525,0.231250,0.602137,-0.302610,-0.303879,-0.078751,0.428487,-0.275881,-0.059437,-0.126029,0.497663,0.370194,0.032199,0.211322,-0.552291,0.098873,0.080000,0.204369,-0.591189,0.295151,0.022175,0.388953,-0.393525,0.080984,-0.267110,0.060432,0.153982,-0.436427,0.466460,0.413945,0.198999,-0.402205,0.001901,0.097589,-0.133068,0.216509,0.416282,-0.178666,0.123535,-0.019146,0.221475,-0.318245,0.143703,0.178285,0.048694,-0.021636,0.393837,0.025032,0.032933,-0.097702,-0.487905,-0.133097,-0.333002,-0.241637,-0.066524,-0.222118,-0.067192,-1.045593,0.028440,-0.157381,-0.145892,0.061174,0.056011,-0.217783,0.202909,-0.693092,0.116015,0.524184,0.082574,-0.420203,0.285201,-0.336383,-0.081313,-0.417027,-0.354872,0.097996,0.427145,0.429479,-0.334783,0.071809,0.046790,-0.513816,-0.535794,0.117963', '25723905', '2369613', '24751811', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25713408', '一生一世', '爱情', '故事发生在二十世纪七十年代，赵永远（谢霆锋 饰）和安然（高圆圆 饰）像两朵被风雨吹打的浮萍，相似的身世和不容乐观的境遇将两人紧紧拴在了一起，随着时间的推移，两人之间产生了真挚而又纯洁的友情。一晃眼十几年过去，历史车轮裹挟着赵永远和安然不断前进，原本天各一方的两人再度相遇，彼时的安然已经出落成为了亭亭玉立的美丽少女，儿时的友情转变成为了炙热的爱情，安然和赵永远都坚信，世间没有什么能再次将他们分开，然而，现实却恰恰相反。浩淼天地之间，他们的感情能够始终如一吗？茫茫人海之中，命运又是否会安排他们再度聚首呢？©豆瓣', '谢霆锋', '邹佡', 5.3, 104107, 'tt3906444', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196449817.jpg', 13.9, 29.9, 38.6, 12.1, 5.5, '0.266843,0.504998,-0.930264,0.613601,0.067060,-0.240544,0.922093,0.051918,-0.381985,0.117296,-0.248868,0.712069,-0.401232,0.265699,0.058017,-0.187590,-0.056726,-1.206888,-0.198841,-0.176244,-0.340161,-0.507876,-0.319080,0.029205,-0.075195,-0.012494,0.789452,0.162721,0.146628,0.765729,0.247358,0.012371,-0.517875,0.600315,-0.339700,0.187005,-0.091032,0.524129,-0.629186,-0.093729,0.172063,-0.332682,0.086044,-0.038968,-0.343805,-0.017761,0.732570,-0.310421,-0.239129,0.139143,0.372193,-0.115813,0.035619,0.124285,0.242210,-0.083058,0.022907,0.174229,-0.210412,-0.343846,0.070610,-0.066293,-0.465330,0.117894,0.069811,0.354321,-0.517969,0.397871,0.373348,-0.226966,0.167791,-0.324793,0.400067,0.568619,0.684619,0.460627,-0.389359,-0.148473,-0.608044,0.290367,0.935053,0.299058,-0.619392,0.553190,-0.401189,-0.208642,-0.450261,-0.052936,-0.639946,-0.119832,0.492649,0.438788,-0.076204,0.569053,-0.495359,0.101409,0.002340,0.033743,0.010157,-0.857525,0.176234,-0.312114,-0.424538,-0.998274,-0.541988,0.315504,0.014110,-0.423931,0.958804,-0.790363,0.395406,0.307931,0.330524,-0.242232,0.711047,0.202906,0.305212,0.105551,0.386220,0.431899,-0.196125,0.205224,0.486799,0.555023,-0.286271,0.702279,-0.489192,0.679726', '26354526', '6425147', '30162520', '25777330');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25713420', '钟馗伏魔：雪妖魔灵', '动作', '魔在魔界，神在天庭，人在人间。本是神鬼殊途，却为了那一线觊觎模糊三界的界限，引发连绵跌宕的搏杀。盛唐时节，某年的七月十五，恰逢千年不遇的升仙良日，西域重镇扈都之内鬼影幢幢，阴森可怖。当年的落拓书生钟馗（陈坤 饰）得到张道仙（赵文瑄 饰）的救助，从而成为扈都的守护者。他斩妖除魔，深入魔界获得魔灵，从而拉开了与魔界弘大的战争。在此过程中，钟馗意外重逢曾经令他魂牵梦绕的女孩——雪妖（李冰冰 饰）。身份截然对立的二人，却无法阻止爱意的滋生。神魔之战逐渐白热化，身陷乱局中央并以捍卫人间为己任的钟馗，最终发现了令他难以置信的阴谋……©豆瓣', '陈坤', '鲍德熹', 4.4, 81306, 'tt3585004', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2224452276.jpg', 26.6, 38.8, 27.3, 4.9, 2.4, '-0.094650,0.460590,-0.611017,0.598571,0.303149,0.020343,0.469096,0.102806,-0.599221,-0.117769,0.175964,0.448652,-0.220686,-0.106378,0.173410,-0.174423,0.165247,-0.725091,-0.323996,-0.157503,-0.036475,0.168251,-0.649103,0.044265,-0.369117,-0.339657,0.850503,0.532491,-0.132321,0.243211,0.074800,0.215948,-0.558139,0.405149,-0.283725,-0.234541,-0.240532,0.216766,-0.439724,0.146558,-0.506572,-0.280376,-0.321868,0.375507,-0.520321,0.316971,0.436745,-0.713286,-0.099747,-0.160746,0.407936,-0.293972,-0.259446,0.068232,0.363792,-0.111352,0.138318,0.219140,-0.084353,-0.088323,-0.063919,0.011086,-0.749652,0.155540,0.173925,0.250826,0.012830,0.656575,0.218782,0.130556,0.196357,-0.002356,0.180905,0.460835,0.540415,0.195968,-0.094854,-0.437559,-0.370185,0.209783,0.694340,-0.104683,-0.279585,0.194034,-0.038438,-0.463134,-0.179593,-0.397530,-0.258516,-0.094983,0.328822,0.183443,0.112107,0.696057,-0.683248,-0.216867,-0.249487,0.164951,-0.162606,0.098986,-0.008518,-0.321675,-0.306771,-0.276697,-0.171415,-0.080331,0.192716,-0.124805,0.533268,-0.860534,0.316603,0.451743,0.274792,-0.287138,0.730189,0.073912,0.164702,-0.394193,-0.379940,0.584082,0.047616,0.643923,-0.205846,0.015511,-0.207694,0.187402,-0.372002,0.334651', '26759819', '5308201', '19899707', '3213270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25715087', '最佳嫌疑人', '喜剧', '百年药厂承工制药的老板李总（刘桦 饰），决定炒楼盘卖地，不想再卖药了。他重金聘请的香港高管阮大志（林俊贤 饰）牵线找来日本的买家宫下先生。不想，宫下看中的只是能够治愈失眠的玉露散神片的独家配方。就在双方谈判陷入僵局之时，声称手握秘方的“神秘人S”的出现更让谈判迷雾 重重。承工制药厂销售总监林以泰（苏有朋 饰）是一名重度失眠患者，整日似梦非醒唯唯诺诺工作的他，却阴差阳错洞悉S与日本买家的交易。成为捉鬼人后，林以泰发觉无论是直属上司阮大志（林俊贤 饰）、关系暧昧的高级文秘安淇儿（陈乔恩 饰）、还是日方代表的妖娆助理梅川美纪子（洪晓熙 饰）每个人都心怀鬼胎，甚至他最信任的药厂员工老宋（由立平 饰）都行为古怪，每个人都是最佳嫌疑人！而此时，躲在某个角落的内鬼“神秘人S”却对所有人的一举一动都了如指掌……©豆瓣', '苏有朋', '张承', 6, 9235, 'tt7510132', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2178761206.jpg', 8.7, 22.6, 38.6, 19.5, 10.6, '0.022355,-0.125125,-0.393769,0.425602,-0.148316,-0.063089,0.455281,0.323832,-0.574271,-0.373850,0.271003,0.366880,-0.055176,0.150422,0.158186,0.155801,0.030910,-0.511551,-0.111973,-0.314386,-0.144423,-0.254505,-0.337250,-0.461224,-0.158738,0.015808,0.367913,0.117557,-0.264355,0.127294,0.367186,0.202077,-0.099243,0.521490,0.101327,-0.170437,0.279757,-0.217706,-0.301170,0.058516,-0.182934,-0.250417,-0.145690,0.138382,0.285979,0.449450,0.360112,-0.031284,-0.183561,-0.060365,0.356215,-0.189888,-0.011796,-0.094138,0.312990,-0.065879,0.311802,0.093244,-0.373875,-0.017843,0.144668,0.241098,-0.805649,0.066408,0.305538,0.392143,-0.440822,0.305204,-0.038824,0.234477,-0.096763,-0.148417,0.250701,0.157824,0.207143,0.077560,0.120230,-0.037186,-0.526277,0.500137,0.307705,0.116213,-0.102823,0.305319,-0.145527,-0.523525,0.007781,-0.161421,-0.245731,-0.052479,0.138334,-0.051980,0.142803,0.001657,-0.432704,-0.020474,0.082782,-0.040435,0.022249,-0.291296,0.068391,-0.688059,-0.087326,-0.272238,-0.217489,0.204878,0.277098,-0.125449,0.528216,-0.542923,-0.036515,0.501637,0.195138,-0.648793,0.656867,-0.036809,-0.191296,-0.414498,-0.395095,-0.026277,0.346462,0.390565,-0.004547,0.313929,0.029771,-0.283926,-0.168493,-0.005430', '4301278', '1793491', '1468527', '3670447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25715111', '绝命航班', '动作', '夜幕降临，从太平洋中心好运岛飞往新加坡的大洋航空615次航班正准备起飞。由于近几年乘客锐减，该航班即将取消，此次也是这架飞机最后一次飞行。方木（辜承 饰）、沈吟（伊娜 饰）、刘夏（李晨浩 饰）等寥寥九位乘客走入机舱。机长查尔斯（艾德·维斯特维克 ED Westwick 饰）颇有些伤感和落寞地向乘客们通报了最后一次飞行的消息。孤独而漫长的旅程，乘客们相继睡去，花花公子刘夏不忘勾搭空姐杰西卡（江琳琳 饰）寻求艳遇。夜色越来越浓，超级月亮升上高空，杰西卡竟然衣衫凌乱惨死机舱。死亡的恐怖氛围迅速蔓延，所有人都为各自的命运担忧，而神秘凶手却未打算就此罢休……©豆瓣', '爱德·维斯特维克', '周文武贝', 3.5, 16480, 'tt3259320', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173238135.jpg', 53, 26.7, 14.3, 3, 3, '-0.135630,0.124341,-0.706115,0.353659,0.391325,-0.224646,0.561490,0.245562,-0.354484,-0.095223,0.390204,0.442628,-0.206398,0.080959,0.386510,0.084818,-0.633840,-0.347420,-0.079745,-0.118245,-0.579476,-0.200855,-0.045573,-0.101320,-0.006878,0.052821,0.555550,0.420024,0.058561,0.702417,0.315352,0.055134,-0.362534,0.607719,-0.215589,-0.170965,0.315910,0.017252,-0.033422,-0.069290,-0.294774,-0.116078,-0.169960,-0.178473,0.107027,0.286957,0.822793,0.206547,0.057528,-0.067607,-0.016194,-0.156814,0.086917,-0.046494,0.311624,0.098742,-0.078391,-0.088808,0.068790,0.002722,-0.059209,0.394260,-0.158117,0.532621,-0.434879,-0.086342,-0.039523,0.335784,-0.400835,-0.037898,0.135882,-0.293873,0.025943,0.257530,-0.088222,0.140358,0.062122,0.017151,-0.204290,0.161544,0.429826,0.278285,-0.165070,0.446357,-0.112293,-0.367648,-0.099256,0.119742,-0.325255,-0.182198,0.581253,0.313188,0.206702,0.278787,-0.371249,0.096228,-0.451423,-0.639050,-0.281507,-0.156312,-0.354021,-0.674961,0.224662,0.030386,-0.128692,0.071838,0.093054,0.317903,0.472420,-0.319494,0.365848,0.359646,-0.029778,-0.313647,0.488210,-0.049843,0.099356,-0.113242,0.126259,0.253357,-0.401396,0.423060,0.072702,0.239933,-0.422519,0.085492,-0.336193,-0.044357', '2159244', '3011051', '21349734', '6519403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25716096', '狗十三', '剧情', '13岁的少女李玩，由于父母离异，与爷爷奶奶生活在一起。正处于青春期的她渴望了解、陪伴和爱。在“要听话”的中国式教育里，李玩也完成了属于她的“成人礼”。电影中，父亲希望通过一条宠物小狗完成与女儿的和解与沟通，李玩为狗取名“爱因斯坦”，暗潮涌动的青春因“爱因斯坦”意外走失，开启了它汹涌又无奈的成长之路。©豆瓣', '张雪迎', '曹保平', 8.2, 479269, 'tt3401962', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2540513831.jpg', 0.9, 2.6, 17.1, 46.2, 33.2, '0.026591,0.027920,-0.759330,0.677224,-0.171642,-0.312640,0.739118,-0.057173,-0.275432,-0.117837,0.008647,0.614502,0.050971,0.748221,0.325242,-0.253515,-0.128128,-0.589784,0.126808,0.110124,0.065006,-0.282341,-0.376602,0.031922,-0.231375,-0.431650,0.941443,0.067247,-0.054626,0.692363,0.042641,0.096896,-0.456081,0.089069,-0.170801,-0.136618,-0.251960,0.283326,-0.403679,-0.026430,0.110734,0.035958,0.307341,-0.018242,0.215185,0.337897,0.873244,-0.585471,-0.162946,-0.241681,0.448127,-0.058070,-0.149581,0.346872,0.023368,0.178546,0.299336,-0.047688,-0.154231,0.105024,-0.270283,-0.316167,-0.612043,-0.322469,0.046501,0.211182,-0.601217,0.451779,0.100809,-0.272319,0.304212,-0.356282,-0.073002,0.411293,-0.048908,1.053149,-0.329745,0.242766,-0.211665,0.143256,0.752429,-0.307849,-0.318791,0.451686,-0.545400,-0.372292,0.231158,-0.221302,-0.658789,-0.165059,0.192567,0.281803,-0.489965,0.427352,-0.564951,0.185273,0.108646,0.059171,0.097783,-0.521675,0.087085,-0.400223,-0.110655,-0.399253,-0.186002,0.002719,0.073249,-0.698952,0.749322,-0.951114,0.433274,0.506758,0.557473,-0.623414,0.943951,0.113733,0.420508,-0.612586,0.367998,0.460988,-0.214380,-0.028642,0.099393,0.220029,-0.039128,0.264674,-0.837285,0.577205', '4066127', '3445516', '26021055', '30401849');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25717176', '新宿天鹅', '喜剧', '无依无靠的青年白鸟龙彦（绫野刚 饰），在鱼龙混杂的新宿和几名小混混发生冲突。关键时刻，他被名叫真虎（伊势谷友介 饰）的男人救下，并接受对方的邀请成为一名星探。然而他这个所谓的“星探”，其实就是站在街头和稍有姿色的女性搭讪，引诱她们走入物欲横流的风尘行业的搜罗者。真虎隶属Burst搜罗者公司，背后有黑帮组织纹舞会撑腰。但是Burst越来越无法满足黑帮的贪婪胃口，随时有被踢走的危险。与之形成最大竞争关系的“闺阁”虎视眈眈，时时刻刻企图抢夺Burst的地盘，其头目南秀吉（山田孝之 饰）似乎对白鸟尤其憎恨。渴望让入行女孩们感到幸福的白鸟，目睹了某个女孩的悲剧，因此无论如何要将小凤（泽尻英龙华 饰）带出地狱。在看不见希望和明天的街道上，男男女女全力奔跑……本片根据和久井健的同名漫画改编。©豆瓣', '绫野刚', '园子温', 6.3, 11662, 'tt3148576', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2224728706.jpg', 2.5, 15, 53, 22.3, 7.2, '0.423476,-0.001686,-0.713643,0.428349,-0.118836,0.157229,0.677275,0.159656,-0.352371,-0.117933,0.304941,0.733220,-0.166939,0.227555,0.279146,-0.142223,0.016495,-0.761074,-0.183609,-0.089266,-0.144355,-0.185164,-0.326352,-0.199232,-0.387974,-0.397305,0.813696,0.182997,-0.328106,0.507661,0.479214,0.594797,-0.313132,0.345293,-0.332977,-0.331106,0.041445,0.077355,-0.162721,0.149445,-0.241913,-0.295496,-0.010873,-0.008524,-0.148851,0.249346,0.557708,-0.244168,-0.062027,-0.123631,0.336512,-0.242647,-0.012913,0.093643,0.281222,-0.192821,0.101345,0.088333,-0.082278,-0.057169,0.017637,-0.086085,-0.885090,-0.029121,0.431437,0.390364,-0.621019,0.350683,0.147242,-0.214216,0.209633,0.022914,0.182404,0.130986,0.259845,0.093058,0.070051,0.272239,-0.617973,-0.220134,0.561569,0.075806,-0.028913,0.052948,-0.225529,-0.287568,-0.098081,-0.239495,-0.369669,-0.132052,0.199874,-0.085801,-0.182233,-0.072962,-0.714862,-0.018993,0.106213,-0.090129,0.102915,-0.421628,-0.109341,-0.687557,-0.117957,-0.536492,-0.198133,0.139878,0.396146,-0.283112,0.917292,-1.000038,0.067284,0.662473,0.453785,-0.745654,0.757667,-0.061135,-0.045613,-0.238156,-0.388908,0.067299,0.386248,0.138895,-0.063757,0.384945,-0.328540,-0.165620,-0.245350,0.312993', '4301278', '1793491', '25928048', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25717233', '心花路放', '喜剧', '二手音响商耿浩（黄渤 饰）婚姻失败，他想用锤子爆小三（李晨 饰）的头，却迟迟没有勇气，幸亏在剧组做制片的兄弟郝义（徐峥 饰）及时发现自暴自弃的耿浩，他决定带着耿浩开启一段“治愈之旅”。于是一对好基友带着一只狗上路，邂逅三千公里的“桃花”。“阿凡达女郎”（陶慧 饰）、“杀马特”周丽娟（周冬雨 饰）、“白富美”（张俪 饰），各式各样的女人接连登场，耿浩一路艳遇一路疗伤。时光倒转，5年前的此时，大龄文艺女青年（袁泉 饰）因为听了一首流浪歌手耿浩的歌，毅然前往大理……在经历一连串奇葩遭遇之后，大家都放下了心里的“阴影”，找到了通向幸福的道路。©豆瓣', '黄渤', '宁浩', 7.2, 512279, 'tt3890264', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2221061003.jpg', 1.3, 6.2, 37.8, 40, 14.8, '-0.007178,-0.044426,-0.338011,0.380704,0.195255,-0.239858,0.743372,0.090204,-0.203144,-0.003685,0.296898,0.250950,-0.454276,0.121812,0.368372,-0.028774,-0.278594,-0.393438,0.223738,-0.004552,-0.098158,0.029312,-0.000881,0.105493,-0.086298,-0.086293,0.554773,0.083242,0.116131,0.574114,0.497684,-0.146650,-0.189354,0.136682,-0.098880,0.215988,-0.192424,0.021018,-0.110725,0.159769,0.112733,-0.215417,-0.071628,-0.130112,-0.220320,0.239884,0.873784,-0.123917,0.054113,0.220654,0.270267,-0.111123,-0.123963,-0.129749,0.050645,0.232422,0.091545,-0.026644,-0.130247,-0.112197,0.203419,-0.126879,-0.373618,0.252686,0.002909,0.130673,-0.305678,0.315157,-0.201260,0.033604,0.306662,-0.368858,0.007651,-0.008011,0.604967,0.257910,-0.219214,0.264797,-0.276124,0.562483,0.468650,-0.053506,0.138562,0.438224,-0.045319,-0.418572,-0.210428,0.251852,-0.582296,0.073298,0.434240,-0.029950,-0.136528,-0.211319,-0.593595,0.014190,-0.094248,-0.030555,0.113485,-0.200953,-0.138862,-0.451498,0.197809,-0.108852,-0.160020,0.259864,0.085313,-0.016756,0.603170,-0.357635,0.074054,0.313914,0.049634,-0.274995,0.563314,0.027836,-0.013535,-0.072048,0.076258,0.480027,-0.187042,0.233338,0.379923,0.456839,-0.261164,-0.230441,-0.296862,0.274685', '21619567', '1467779', '5403927', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25717896', '韩公主', '剧情', '韩恭珠（千禹熙 饰）是一位十七岁的平凡少女，她热爱音乐，希望有朝一日能够成为一名歌唱家。然而，本该处在一生中最快乐和无忧无虑的年华的她，却因为一场意外的发生而彻底失去了笑容，亦就此放弃了唱歌的梦想。离开了生于斯长于斯的家乡，韩恭珠成为了新学校的转校生。在这里，韩恭珠结识了许多善良的朋友们，在朋友们的带领和帮助下，韩恭珠渐渐走出了过去的阴影，笑容再一次回到了她的脸上。然而，快乐的日子并没有持续多久，灰暗的过去并不愿意放过这位可怜的少女，当往事席卷而来，一个韩恭珠千方百计想要隐瞒的秘密最终浮出了水面。©豆瓣', '千禹熙', '李铢真', 7.6, 33401, 'tt3265462', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2174810950.jpg', 0.6, 2.8, 29.6, 48.8, 18.1, '0.266863,0.216970,-0.621502,0.512808,-0.211865,-0.486131,0.823473,-0.063803,-0.331029,-0.453036,-0.054933,0.861425,0.125428,0.553328,0.184123,-0.289949,-0.163443,-0.679262,0.096110,-0.499989,-0.199547,-0.014105,-0.081144,-0.001073,-0.286476,-0.334404,1.091402,0.473558,0.120975,0.796465,0.329388,0.203361,0.168248,0.462628,-0.274422,-0.119464,-0.081551,0.210078,-0.353550,0.354208,-0.039006,-0.358196,-0.226143,0.239600,-0.087462,0.086080,0.832253,-0.326909,-0.249826,0.002552,0.315094,-0.413303,0.151632,0.167497,0.108581,-0.051584,-0.007305,0.273549,-0.385495,0.015362,0.021262,-0.344806,-0.818514,0.007347,0.037628,0.290157,-0.665744,0.359329,0.246583,-0.287581,0.234635,-0.249205,0.322749,0.336494,0.328126,0.407790,-0.442734,0.437791,-0.380797,0.275115,1.047485,0.096803,-0.516936,0.707513,-0.281048,-0.345499,-0.061150,-0.310857,-0.620702,0.131914,0.235353,0.383390,-0.292241,0.405710,-0.508263,-0.001946,-0.282645,-0.119927,0.108353,-0.647786,-0.095765,-0.272740,-0.191200,-0.219339,-0.283320,0.088367,-0.202827,-0.429199,0.892106,-1.028314,0.450461,0.380065,0.128510,-0.539337,0.719006,0.397205,0.216625,0.057482,0.295859,0.582677,-0.007531,0.215887,-0.123184,0.238818,-0.394939,0.005792,-0.437407,0.481867', '35030151', '25721544', '35287908', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25718082', '念念', '剧情', '在繁忙的大都市，每个人在快节奏的世界中生活着，繁重的生活重担让他们无瑕估计其他，然而，总有一些阴影在时时影响着他们。育美（梁洛施 饰）发现自己怀了男友阿翔（张孝全 饰）的孩子，但因为过去父母离婚后，母亲（李心洁 饰）难产而死的阴影一直笼罩着她，让她迷失了方向。育美几次想找阿翔商量，但梦想成为奥运拳击手的阿翔正因为眼疾的关系，濒临被禁赛的命运，不甘心失败的他，每天如着魔般练习，却不知不觉冷落了育美。育美思考再三提出分手。育美的哥哥育男（柯宇纶 饰）从小跟随父亲生活，父亲去世后，渴望家庭温暖的他终于鼓足勇气，外出寻找失去联系的妹妹。阿翔寻找育美到海边，遇到一个与遭遇海难的父亲非常相像的男人。没有影子的男人，能穿越时间的酒吧，疑似遭海难的父亲，人们必须直面自己的恐惧。究竟旧日恋人能否复合？失散兄妹能否重聚？一个关于爱情与青春的故事，在美丽的绿岛之滨，缓缓铺陈开来……', '梁洛施', '张艾嘉', 7, 46151, 'tt4484426', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2239530046.jpg', 1.6, 8.2, 41.9, 37, 11.3, '-0.083321,-0.082926,-0.689603,0.485618,-0.161007,-0.335485,0.849268,0.227976,-0.483323,-0.376260,0.118540,0.659612,0.050989,0.452792,0.083594,0.100589,-0.135537,-0.665366,0.067590,0.056000,-0.189459,-0.352532,-0.142753,-0.020531,-0.062577,-0.344180,0.804924,0.066840,-0.000745,0.313373,0.136249,0.172114,-0.280247,0.525503,-0.295866,-0.007538,-0.002913,0.310036,-0.440547,0.156483,0.087543,-0.091680,-0.034189,0.023568,-0.149946,0.231891,0.777641,-0.174425,-0.330565,-0.216114,0.472105,-0.127198,-0.097690,0.087508,0.259493,0.055740,0.204388,0.154082,-0.217564,-0.260025,0.089448,-0.069778,-0.493470,0.122886,0.386109,0.198989,-0.483060,0.364501,0.182217,-0.091453,0.206090,-0.265600,0.259223,0.413388,0.268994,0.339502,-0.452757,0.129232,-0.409599,0.281269,0.947504,-0.035694,-0.093306,0.447010,-0.461885,-0.153928,0.001434,-0.136139,-0.732390,0.134684,0.168703,0.190354,-0.609793,0.302293,-0.330588,-0.018354,-0.120016,0.038517,-0.044095,-0.539952,-0.015988,-0.354007,-0.162199,-0.430379,-0.398334,0.081832,-0.114024,-0.292086,0.610070,-0.810824,0.435948,0.652608,0.306006,-0.701727,0.711692,0.274701,0.091297,-0.250993,0.230053,0.684699,-0.217735,0.085301,-0.045414,0.088601,-0.173045,0.296144,-0.552160,0.464790', '1291835', '35287908', 