INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25721544', '不速之客', '动作', '一位退役归来的士兵与刚在战场上痛失长子的一家人结为朋友，相通的经历让他们的感情维系日益增强，士兵成为了这家人的贵客。然而这家人很快发现，士兵的真实身份并不像他所说的那样……via.张咏轩', '丹·史蒂文斯', '亚当·温加德', 6.4, 11000, 'tt2980592', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2533708046.jpg', 2.8, 14.9, 51.4, 22.7, 8.2, '0.598168,-0.145430,-0.781361,0.535101,-0.086146,-0.100736,1.027404,0.238378,-0.999937,-0.373361,0.414223,1.194218,0.026463,0.095660,0.506460,-0.225860,-0.283428,-0.628167,0.042679,-0.276975,-0.152618,-0.300795,-0.166401,-0.366495,-0.203267,-0.631922,0.946235,0.284782,-0.161332,0.656787,-0.213550,-0.091453,0.058316,0.538940,-0.144834,0.068962,-0.084571,0.392987,-0.486443,0.042115,-0.253070,-0.128433,0.012698,0.032838,-0.156765,0.391754,0.436289,-0.500533,-0.244752,-0.031939,0.024820,-0.188683,0.176405,0.054950,0.332467,0.074180,0.138656,0.299519,-0.032659,0.055523,-0.415893,-0.175659,-0.741757,-0.089162,0.220129,0.071991,-0.581138,0.826304,0.022272,0.025974,-0.069349,-0.175853,0.278589,0.573609,0.004384,0.476593,-0.258631,-0.185533,-0.857425,0.058861,1.513305,0.121188,-0.342217,0.235948,-0.308583,-0.621826,-0.158037,-0.424456,-0.463905,0.152440,0.023374,0.467790,-0.287234,0.145006,-0.501419,0.137327,0.003853,0.088570,0.116660,-0.638436,0.202560,-0.626777,-0.357166,-0.614645,-0.170929,-0.021573,0.017317,-0.326532,1.060985,-1.121002,-0.011869,0.128193,0.647995,-0.782737,0.757540,-0.165138,0.086749,-0.452539,-0.191127,0.390623,0.456309,0.139593,0.185732,0.067576,-0.420527,0.175872,-0.137058,0.319581', '35030151', '1870682', '1308755', '26724989');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25722262', '男人女人和孩子', '剧情', '在《男人女人和孩子》中，有经常浏览色情网站的父亲，有痴迷于Guild Wars(激战2）的儿子，还有误入歧途的母亲。小说探讨的是在互联网视讯如此发达的当下，美国家庭所面临的性压力，以及美国社会“不牢靠的情感文化”。', '安塞尔·艾尔高特', '贾森·雷特曼', 7.2, 6107, 'tt3179568', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2198689652.jpg', 1.3, 7.2, 38.9, 37.5, 15.2, '0.320927,-0.310337,-0.959043,0.781780,-0.113271,-0.044086,0.619204,0.232057,-0.737948,-0.121759,0.220211,0.843604,0.098186,0.248344,-0.117634,-0.259275,-0.298944,-0.723215,-0.265215,-0.023360,-0.194851,-0.784049,-0.317859,-0.580933,-0.199370,-0.616241,0.832918,-0.118060,-0.671764,-0.167498,0.048908,0.362556,-0.255708,0.741777,-0.396977,0.036591,-0.148415,0.285890,-0.570020,-0.049264,0.402052,-0.195627,0.206450,-0.057589,-0.038708,0.044375,0.743078,-0.242301,-0.303775,-0.148676,0.737371,-0.011993,-0.364591,-0.080093,0.317054,-0.177614,0.370243,0.190824,-0.009577,-0.151360,0.066609,-0.176479,-0.597409,-0.337538,0.400246,0.436034,-0.552910,0.644078,-0.233481,-0.374029,0.084769,-0.383181,0.171914,0.553870,0.369730,0.770217,0.045584,0.111656,-0.295854,0.293355,0.475519,0.249500,-0.414563,0.406941,-0.782069,-0.456879,-0.077553,-0.586701,-0.781084,0.019285,0.294514,-0.204563,-0.689451,0.682038,-0.574024,0.459028,0.410319,-0.159790,0.278664,-0.711059,-0.298041,-0.697709,-0.507887,-1.019192,-0.256057,-0.095993,0.448120,-0.513650,1.403886,-1.249000,0.000340,0.720025,0.482267,-0.937391,1.048127,0.100511,-0.160680,-0.082789,-0.180256,0.287389,-0.235791,0.057046,-0.482700,0.167683,0.128960,0.065957,0.011491,0.493699', '6963575', '3445516', '1303010', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25723081', '英雄之战', '动作', '高若飞（张智康 饰）是老高（午马 饰）多年前收养的一名弃婴。班主任陈老师（魏一 饰）一直被若飞视为心中的蝴蝶女神，若飞非常喜欢陈老师的一枚蝴蝶胸针。陈老师通知若飞参加学校的亲子运动会，他偷走蝴蝶胸针被老爸发现，没想到老高看到这枚蝴蝶胸针后却大发雷霆。委屈的若飞跟老高争执后离家出走，他在奔跑中穿越到了民国时期，一场别开生面的运动会正在举行。若飞在那里认识了跟陈老师神似的杨老师，和武功高强的东北军战士独龙（陆毅 饰）。富家少爷Jason（何润东 饰）为了在运动会中得到国术冠军专程从美国归来，他视独龙为最大的竞争对手。若飞崇拜英勇的独龙，一直不离不弃陪在身边，就在两人慢慢熟悉的过程中，若飞发现了惊人的秘密……©豆瓣', '陆毅', '虞军豪', 3.1, 9295, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2174242324.jpg', 65.9, 20.9, 8.3, 2, 3, '0.021480,-0.056194,-0.669207,0.509768,-0.017405,-0.301717,0.541933,-0.159893,-0.471997,-0.146801,0.188269,0.718838,-0.447741,0.330708,0.363536,0.031856,-0.020393,-0.760392,-0.235942,-0.212422,-0.236475,-0.188879,-0.138877,0.140226,-0.118224,-0.149658,0.322574,-0.100900,0.005224,1.006176,0.296947,0.043455,-0.286200,0.032439,-0.366006,-0.157540,0.067140,0.469386,-0.080891,0.233280,0.065419,-0.220879,0.005545,0.023074,0.153353,-0.081271,0.522015,-0.307418,0.012987,-0.245564,0.209193,-0.112947,-0.056169,0.061402,0.634805,0.278653,0.360455,-0.228605,-0.069039,0.205356,0.162139,-0.366750,-0.388205,0.071112,0.143263,0.182828,-0.522390,0.434476,-0.115747,0.007008,0.303757,-0.289150,0.273445,0.049683,0.082148,0.269746,-0.248233,0.100309,-0.400566,0.241122,0.436948,-0.161284,0.072420,0.051176,0.032603,-0.128228,0.314881,0.103615,-0.240418,0.109075,0.314601,-0.044503,-0.053987,-0.117563,-0.330669,-0.005350,-0.082983,0.041540,-0.154140,-0.342484,-0.220115,-0.377391,0.116786,-0.528581,-0.051163,0.136381,0.079513,-0.340301,0.621199,-0.885900,0.452700,0.211742,0.000011,-0.232926,0.505393,-0.044563,-0.002359,-0.236709,-0.167351,-0.119732,0.180282,0.299189,0.070380,0.305729,-0.046411,-0.301457,-0.316316,0.265140', '26365262', '1451563', '35030151', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25723095', '举报者', '剧情', '尹敏哲（朴海日 饰）是一名资深的电视台节目导演，在普通的寻找新闻素材中他意外发现了一家大型医疗企业也涉及其中，于是他带着女下属（金星 饰）开始调查真相。令人意外的是，生物技术权威的李章焕博士（李璟荣 饰）竟然涉嫌造假干细胞，但无奈的是他们没有准确的证据，就在这时，正义的举报者——博士团队的研究员沈敏浩（柳演锡 饰）出现了，他瞒着妻子（柳贤静 饰）和家人艰难地举报了造假者。沈敏浩的坚持让尹敏哲更加地坚定，与此同时李章焕采取了一系列非正义的手段来阻止他们的新闻报道，真相和国家权益的抗争一触即发。本片改编自轰动韩国的2006年韩国克隆之父黄禹锡博士干细胞造假风波。©豆瓣', '朴海日', '林顺礼', 7.3, 10286, 'tt4034414', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198331446.jpg', 0.3, 3.2, 39.8, 43.7, 13, '0.303270,-0.016752,-0.590739,0.412297,0.022571,0.162607,0.502592,0.072085,-0.540713,-0.168722,0.349379,0.617495,-0.244500,-0.072340,0.018701,0.030362,-0.352101,-0.663978,-0.166562,-0.118755,-0.142546,-0.519816,-0.232401,-0.445859,-0.105061,-0.214739,0.608806,0.153172,-0.322496,0.432442,0.291469,0.471555,-0.036755,0.381432,0.099045,-0.083592,0.398613,-0.098780,-0.167462,0.118930,0.248014,-0.458955,-0.157014,0.432895,0.000860,0.533886,0.433474,-0.195123,-0.071309,-0.008531,0.419067,-0.494810,-0.051459,0.059598,0.397347,0.182247,0.130113,0.532255,-0.199736,-0.118550,0.171682,0.175792,-1.114452,-0.126384,0.317110,0.592498,-0.438277,0.467120,-0.352653,-0.005618,0.059527,-0.222674,0.382345,0.262867,0.300127,0.307095,0.093631,0.107695,-0.492738,0.457522,0.363085,-0.007335,-0.285893,0.203031,-0.369986,-0.666524,-0.120379,-0.317306,-0.341494,0.004033,0.288602,-0.065222,-0.177192,0.115134,-0.548179,-0.067269,-0.128553,-0.087862,0.011601,-0.202988,-0.009177,-0.677754,-0.047335,-0.383827,-0.453350,-0.065781,0.074656,-0.320326,0.847166,-0.597899,-0.248797,0.646708,0.363449,-0.476487,0.776044,-0.115018,-0.091574,-0.128486,-0.211210,-0.233303,-0.048448,0.407710,0.059350,0.342349,0.420814,-0.537230,-0.091474,0.015727', '1793491', '27602116', '25932086', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25723583', '英伦对决', '动作', '关玉明（成龙 饰）和女儿小凡（梁佩诗 饰）在英国伦敦过着相依为命的日子。关玉明经营着一间小小的餐馆，老老实实的靠着辛勤劳作养活家庭，从未有过想要僭越法律或是道德的念头。然而，上天并不眷顾这个善良的男人，在一场恐怖袭击中，小凡不幸成为了受害者之一。让关玉明无法接受的除了女儿的死之外，还有英国政府对此次事件的轻视和不作为。政府高官莱姆（皮尔斯·布鲁斯南 Pierce Brosnan 饰）出现在了关玉明的视野之中，他坚信莱姆和恐怖组织以及事件的真相有着不可分割的联系。既然法律和正义无法还关玉明一个公道，关玉明决定用自己的力量来为女儿复仇。©豆瓣', '成龙', '马丁·坎贝尔', 7, 213415, 'tt1615160', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2499135561.jpg', 0.7, 5.2, 45.2, 41.1, 7.9, '0.092435,0.036018,-0.781271,0.687092,-0.242503,-0.128802,0.734502,0.182958,-0.751509,-0.226131,0.123991,0.905998,0.256282,0.134942,0.219531,-0.034388,-0.283325,-0.700814,-0.104904,-0.133094,-0.297852,-0.749149,-0.251749,-0.341434,-0.331485,-0.317247,0.697119,0.032778,-0.145708,0.224615,0.427316,0.437934,-0.146524,0.320380,-0.330835,-0.233325,0.083642,0.148204,-0.575401,0.196013,0.141766,-0.200091,-0.080582,0.309187,-0.171433,0.245293,0.563233,-0.558386,-0.181573,-0.309436,0.313505,-0.492674,-0.109973,0.207880,0.102166,-0.102591,0.438216,0.549566,-0.179299,0.083171,0.436988,-0.209121,-1.070464,-0.182996,0.324028,0.254587,-0.772632,0.696812,-0.100213,-0.257136,0.089964,-0.380597,0.214852,0.372995,0.314334,0.686858,-0.570624,0.104515,-0.674505,0.030447,0.775803,0.083239,-0.174431,0.222732,-0.440479,-0.386013,-0.008335,-0.442487,-0.596592,-0.117845,0.038671,0.055387,-0.214246,0.360913,-0.567799,-0.047017,-0.047397,-0.179970,0.194161,-0.515140,-0.018077,-0.296312,-0.149702,-0.439245,-0.399811,0.277003,0.165024,-0.408588,0.803688,-1.167588,0.146955,0.470800,0.558709,-0.698623,0.930272,0.483483,0.241031,-0.221963,-0.203718,0.102576,0.005926,0.202280,0.027776,0.063995,0.145370,-0.245377,-0.163283,0.493482', '1793491', '1783461', '1877596', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25723780', '大洋之间的灯光', '剧情', '汤姆（迈克尔·法斯宾德 Michael Fassbender 饰）是曾经在前线卖过命的退伍军人，如今，他带着妻子伊莎贝尔（艾丽西亚·维坎德 Alicia Vikander 饰）前往位于澳大利亚西部的一座小岛上，成为了那里的灯塔守灯人。小岛上离群索居的生活让汤姆和伊莎贝尔之间的感情越发要好，两人在喜悦之中等待着伊莎贝尔腹中的孩子慢慢长大。令夫妻两人没有想到的是，一场意外令伊莎贝尔流产了，孩子的逝去令伊莎贝尔陷入了绝望之中。一天，一艘船被海浪冲上了岸，船上出了有一具男性的尸体外，竟然还有一个婴儿。欣喜若狂的伊莎贝尔恳求汤姆同意她收留并抚养这个孩子，虽然这种做法有违汤姆的原则，但他还是答应。©豆瓣', '迈克尔·法斯宾德', '德里克·斯安弗朗斯', 7, 7028, 'tt2547584', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2365804463.jpg', 1.1, 7.9, 43.9, 35.2, 11.9, '0.328561,0.156960,-0.922858,0.554760,0.043766,-0.349157,1.010635,0.074051,-0.793946,-0.010749,0.133637,0.869833,-0.125550,0.277106,0.149156,0.238112,-0.406777,-0.635439,-0.333306,-0.209153,-0.384412,-0.594674,-0.171170,-0.129497,-0.332948,-0.296832,0.611147,0.110370,0.157528,0.544528,0.290917,0.177524,0.006990,0.518327,-0.203069,0.174386,0.064507,-0.039104,-0.094765,0.221145,0.133828,-0.053794,0.035314,0.304145,0.001270,0.403440,0.716273,-0.318481,-0.053380,-0.147093,-0.041335,-0.188889,0.048196,0.153250,0.227798,-0.282803,0.040549,0.153721,-0.265742,-0.073760,0.230962,-0.004901,-0.418839,0.050021,-0.019936,0.309949,-0.791244,0.491749,0.023462,-0.106256,0.074700,-0.339695,0.306399,0.271827,0.131287,0.589014,-0.314327,0.125028,-0.524234,-0.106986,0.718599,0.071982,-0.135349,0.109074,-0.588999,-0.410110,0.039012,-0.189696,-0.594901,0.039984,0.262392,0.093874,-0.251869,0.265236,-0.641030,0.008234,-0.481705,-0.064097,-0.103262,-0.421785,0.009014,-0.473974,0.101080,-0.367130,-0.382829,-0.041053,0.001924,-0.245384,0.645298,-0.694618,0.330734,0.349951,0.427837,-0.079344,0.638830,0.155895,0.238987,-0.147144,0.114406,0.420929,-0.174237,0.041383,0.193276,0.291445,-0.062037,0.107138,-0.287795,0.515011', '3111650', '1292211', '21619567', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25723905', '金田一少年事件簿 狱门塾杀人事件', '悬疑', '炎炎夏季，金田一（山田凉介 饰）和七濑美雪（川口春奈 饰）、佐木龙二（有冈大贵 饰）两名好友前往著名的狱门补习学校参加集中培训。当他们正聊天玩笑时，突然警铃声大作。校舍走廊内，名为茂吕井的学生手按在警铃上，惨遭毒害。经金田一缜密推理，确定这是一起有针对性和计划性的杀人事件。未过多久，他们重逢香港警员李白龙，并得知策划了九龙事件的真凶正是人称地狱傀儡师的高远遥一，一个自称犯罪艺术家的国际通缉犯。此前高远正展开一系列的艺术犯罪计划，而他则将下一个目标锁定在正准备前往马来西亚参加集训的金田一身上。神秘莫测的对手，异国他乡的较量……日本电视台开播六十周年纪念作品。©豆瓣', '山田凉介', '南雲聖一', 6.6, 7098, 'tt3185090', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2164984660.jpg', 2.1, 11.1, 52.6, 25.3, 9, '0.298936,0.027297,-0.420949,0.384322,0.268878,0.053958,0.308336,0.005298,-0.274450,-0.589860,0.365383,0.548774,-0.250333,0.210481,0.357918,-0.160547,-0.250028,-0.959660,-0.238798,-0.029180,-0.131813,-0.355412,-0.097528,-0.069708,0.079057,0.023026,0.711526,0.192222,-0.171971,0.526749,0.542804,0.354282,-0.516261,0.299388,-0.067953,-0.277535,0.186598,0.145020,-0.273057,0.144121,-0.182679,-0.262561,-0.099223,-0.040383,0.123109,0.337081,0.494261,-0.292103,-0.073081,-0.191562,0.309886,-0.187182,-0.098384,0.005216,0.631053,0.271382,0.244035,0.204880,-0.133239,0.072798,-0.276782,-0.233172,-0.606004,-0.023966,0.018582,0.063541,-0.254242,0.025688,-0.124691,0.054619,0.088104,-0.185200,0.234871,0.174925,0.437613,0.187096,-0.098371,0.131385,0.030066,0.149892,0.312342,-0.021583,0.195270,0.131397,0.231107,-0.560048,-0.070072,-0.061085,0.005471,-0.027859,0.277085,-0.175851,0.098553,-0.136365,-0.460812,-0.217282,-0.117193,-0.083386,0.041259,-0.037131,0.007727,-1.078916,0.240713,0.056610,-0.143150,0.190852,0.187257,-0.142496,0.552315,-0.868690,0.122042,0.518430,0.116126,-0.147791,0.324329,-0.027149,0.153280,-0.283225,-0.328750,0.038163,0.040633,0.474722,-0.057350,0.454172,-0.189784,-0.295066,-0.317090,0.193886', '2369613', '20274039', '3266509', '6984051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25723907', '捉妖记', '喜剧', '不知何年，妖界大乱。新妖王对前代势力痛下杀手，更誓要对前妖后腹中的孩子斩尽杀绝。妖后一行躲避追杀来到地处大山深处的永宁村，偏巧遇到捉妖天师霍小岚（白百何 饰）和罗刚（姜武 饰）。一番混乱过后，妖后自知气数将尽，遂将妖蛋放入永宁村保长宋天荫（井柏然 饰）的腹中保存。是夜，小岚所属的天师堂掌门人葛千户（钟汉良 饰）率领手下血洗永宁村，天荫不得已随小岚逃亡。时机成熟，萝卜妖怪胡巴降生人间。在接下来的旅途中，小岚和天荫对彼此的了解不断加深，而胡巴也终于成为他们中间最不可割舍的重要存在。战争仍在继续，人和妖的界限日渐模糊……©豆瓣', '白百何', '许诚毅', 6.7, 505766, 'tt3781476', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2257944916.jpg', 3.3, 9.9, 44.7, 32, 10.2, '-0.011533,0.194153,-0.399735,0.375227,0.353644,-0.033193,0.499063,0.174806,-0.681783,-0.136610,0.197753,0.218867,0.055793,-0.029462,0.255525,-0.178547,-0.048967,-0.374305,-0.157000,-0.299797,-0.138344,-0.034325,-0.295416,0.043011,-0.333102,-0.123871,0.630870,0.421857,0.056922,0.429233,0.313654,0.277861,-0.559467,0.348248,-0.083638,0.252717,-0.174079,-0.104426,-0.439271,0.183969,0.002816,-0.191944,-0.105567,-0.075194,-0.093722,0.301276,0.660128,-0.614893,-0.069427,-0.357624,-0.032287,-0.350409,-0.300564,0.228669,0.587838,-0.076401,0.273998,0.443078,-0.226174,-0.067257,-0.250698,0.053494,-0.491165,0.037698,0.410685,0.157769,-0.449473,0.248144,0.135486,-0.016142,0.166838,-0.266983,0.328852,0.537302,0.314482,0.183597,-0.029664,-0.058129,-0.327435,-0.132447,0.539899,-0.264847,0.336008,-0.118736,0.307951,-0.453002,0.005141,-0.314567,-0.209751,0.017953,0.099297,0.200855,0.004707,0.438779,-0.450804,-0.114014,-0.237220,-0.013167,0.201391,-0.102468,-0.070575,-0.320097,0.009870,-0.333378,-0.079334,-0.133395,0.262473,-0.006082,0.620039,-0.677519,0.239655,0.088909,0.484626,-0.408669,0.342522,-0.039181,0.410548,-0.488221,-0.315818,0.191040,0.324750,0.530935,0.146734,0.129893,-0.284315,-0.007319,-0.261682,-0.040706', '35030151', '1293265', '6974439', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25724855', '房间', '剧情', '女孩乔伊（布丽·拉尔森 Brie Larson 饰）被一个叫“老尼克”的男人拐骗，之后被他囚禁在其房子后院的棚屋里长达七年之久。在此期间她遭到强奸，并生下儿子杰克（雅各布·特伦布莱 Jacob Tremblay 饰）。靠着老尼克时不时的物资补给，母子二人艰难度日。尽管如此，母亲还是竭尽所能，为儿子杰克创造了一个安全而开心的成长空间。这个狭小逼仄的房间，成了杰克生活成长的神奇小天地。在杰克度过了他的五岁生日后，母亲决定告诉他真相，在这个小小的房间外面，有着更广阔的世界。他们开始策划逃跑计划，决心要逃出这个囚禁他们的房间……本片根据艾玛·唐纳修的同名小说改编。©豆瓣', '布丽·拉尔森', '伦尼·阿伯拉罕森', 8.8, 352106, 'tt3170832', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2259715855.jpg', 0.1, 0.4, 8.1, 43.6, 47.8, '-0.030284,0.123905,-0.684195,0.309664,-0.371508,-0.246008,0.708683,0.235593,-0.520382,-0.324361,0.169229,0.793985,-0.017503,0.413845,-0.008420,0.262725,-0.509851,-0.313427,-0.043956,-0.244449,-0.216169,-0.453941,-0.079855,-0.424976,0.026285,-0.346423,0.386587,-0.150299,0.046531,0.088856,0.112148,0.050157,-0.026105,0.299738,-0.221384,0.321008,0.288171,-0.359865,-0.208689,0.132889,-0.245435,-0.016799,-0.007428,-0.016303,0.013033,0.196605,0.769388,-0.013289,-0.209761,-0.169297,0.456083,-0.193790,-0.223987,0.037108,0.213318,-0.166553,0.128664,0.144637,-0.132181,-0.085979,0.058975,-0.427997,-0.685637,0.157954,0.162766,-0.223033,-0.383431,0.071914,-0.033063,0.047928,0.205841,-0.492954,-0.095294,0.461948,0.271707,0.361310,-0.361291,0.130425,-0.584577,-0.070792,0.399994,-0.535161,-0.143422,0.398091,-0.157225,-0.315056,0.057812,-0.037432,-0.661240,-0.079670,0.558240,-0.037200,-0.249395,0.182817,-0.474667,-0.016672,-0.413524,-0.150489,0.102094,-0.374911,-0.306990,-0.368886,-0.291220,-0.054760,-0.284817,-0.124068,-0.290422,-0.364610,0.558988,-0.430399,0.352836,0.650514,0.311629,-0.480342,0.597733,-0.023392,0.407426,-0.138861,0.271862,0.503545,0.018673,0.338576,0.032251,0.368823,0.026292,0.129403,-0.859908,0.439898', '24733428', '30401849', '1366165', '3001149');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25725759', '赌棍', '剧情', '《赌徒》根据1974年的同名电影改编而成，沃尔伯格饰演的吉姆·本内特（Jim Bennett）既是大学英语文学教授，又是一个大手笔的赌徒。他让学生打假球，使自己在赌局中牟利。随着赌瘾日渐加深，他的生活陷入万劫不复之中。由于债台高筑，他不得不已自己的生命为代价，向一位高利贷大佬弗兰克借债。', '马克·沃尔伯格', '鲁伯特·瓦耶特', 6.8, 5507, 'tt2039393', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2219181047.jpg', 3.3, 12.6, 40, 28.3, 15.8, '-0.043638,-0.084194,-0.290802,0.731592,-0.290005,-0.663389,0.747861,-0.023789,-0.517208,-0.311586,0.374176,0.790303,-0.188275,0.169715,0.455889,-0.235822,-0.097968,-0.764119,-0.196769,-0.131283,-0.017344,-0.555866,-0.341926,-0.227701,-0.315885,-0.338445,0.620711,0.191267,-0.282128,0.201647,0.249426,0.472776,0.321325,0.009430,0.265237,0.133161,0.107693,-0.332612,-0.279022,0.123942,0.324257,-0.260665,-0.275228,-0.149580,-0.131967,0.441844,0.684027,-0.228504,0.098308,-0.290818,0.515451,-0.250778,-0.381879,0.019187,0.109383,-0.043596,0.285780,0.320832,-0.361940,0.339904,0.019464,-0.233005,-0.807572,-0.073176,-0.071916,0.132254,-0.376120,0.432104,-0.089747,0.023202,-0.208017,-0.192180,-0.245015,0.073458,0.343608,0.371774,-0.164177,-0.150908,-0.311506,0.381194,0.707047,0.212704,-0.149430,0.334867,-0.604606,-0.390160,0.147640,-0.417361,-0.652857,0.045753,0.478390,-0.351832,0.072909,0.636191,-0.436512,0.035654,-0.206004,-0.374496,0.112378,-0.237593,-0.034985,-0.520241,-0.374132,-0.177408,0.076667,-0.374285,0.139412,-0.305544,0.797021,-0.844630,-0.223825,0.670908,0.021846,-0.360016,0.527141,0.012610,0.052001,-0.092575,-0.302043,0.061416,0.193618,0.339150,-0.010717,-0.033350,0.228999,-0.220558,0.005724,0.700310', '1303034', '27602116', '30345227', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25726614', '神奇动物在哪里', '剧情', '故事发生在1926年的纽约，彼时，麻鸡们对魔法师的抵制达到了最高峰，由玛丽露（萨曼莎·莫顿 Samantha Morton 饰）所领导的反魔法组织活动频繁。与此同时，街头巷尾之中时时发生的种种灾难意外让魔法世界的存在离暴露仅有一线之隔，整个魔法部陷入了空前紧张的气氛之中。就在这个节骨眼上，环游世界进行着研究神奇魔法动物之行动的魔法动物学家纽特（埃迪·雷德梅恩 Eddie Redmayne 饰）抵达了纽约，他随身携带的魔法手提箱里，装着几十种他一路营救的魔法动物们，而他的一举一动，均处于隶属于魔法部的前傲罗蒂娜（凯瑟琳·沃特森 Katherine Waterston 饰）的监视之下。一场意外中，麻鸡雅各布（丹·福格勒 Dan Fogler 饰）误拿了纽特的手提箱，并且放出了藏在箱子里的魔法动物，为此，纽特、蒂娜、雅各布和蒂娜的妹妹奎妮（艾莉森·苏朵儿 Alison Sudol 饰）不得不踏上了寻找魔法动物的旅途。', '埃迪·雷德梅恩', '大卫·叶茨', 7.7, 590437, 'tt3183660', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2392444121.jpg', 0.5, 3.3, 28, 45.1, 23.1, '0.514654,0.004974,-0.566092,0.540166,0.046756,0.269407,0.658058,-0.090724,-0.496262,-0.416502,0.325233,0.612688,-0.241757,0.034098,0.354778,-0.011498,-0.555355,-0.609690,0.063411,-0.280407,-0.444871,-0.501259,-0.499708,-0.200301,-0.233608,-0.765901,0.429050,0.260304,-0.182702,0.179897,-0.055531,0.327524,-0.334178,0.365907,0.247832,-0.128327,0.315198,-0.138994,0.016904,0.291353,0.150086,-0.284037,0.017427,0.115798,0.138551,0.160940,0.798775,-0.713673,0.300328,-0.198883,0.197570,-0.239913,0.042935,0.147561,0.240603,0.109689,0.037904,-0.152220,-0.221337,0.191456,0.258097,-0.058204,-0.599872,0.128294,0.158180,0.155025,-0.511083,0.323602,-0.141345,0.217361,0.113580,-0.258528,0.140145,0.288806,0.250453,0.237065,0.083150,-0.053897,-0.300820,-0.237209,0.180492,-0.277198,-0.427604,0.194337,-0.519987,-0.465973,-0.262354,-0.145142,-0.475901,-0.215094,0.293498,0.184207,0.136118,0.391884,-0.941583,0.174599,-0.245118,-0.307125,-0.079003,-0.013998,-0.236589,-0.859860,0.047839,-0.411097,-0.244926,0.037829,0.225999,-0.152613,0.433793,-0.812960,0.349911,0.339016,0.081481,-0.197706,0.495693,-0.283658,0.367428,-0.096773,-0.285344,0.218690,-0.056657,0.543549,0.087583,0.514337,0.187122,-0.098998,-0.22331