INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25727048', '福尔摩斯先生', '剧情', '故事发生在1947年的英格兰，名声远扬的大侦探福尔摩斯（伊恩·麦克莱恩 Ian McKellen 饰）如今已是93岁高龄的老人了，晚年期间，他过着离群索居的生活，陪伴在他身边的只有管家芒罗夫人（劳拉·琳妮 Laura Linney 饰）和她的儿子罗杰（米罗·帕克 Milo Parker 饰）。虽然已经不再过问江湖中的种种纷纷扰扰，但是对于福尔摩斯精彩的一生来说，仍旧有一些未解的谜团令他耿耿于怀。日渐僵硬的身体，每况愈下的记忆力和推理能力让他越发的意识到，现在，此刻，是他解开这些谜团的最后机会了。就这样，在缺少了老搭档华生的情况下，福尔摩斯独自开始了他的最后一次推理。©豆瓣', '伊恩·麦克莱恩', '比尔·康顿', 7.8, 45271, 'tt3168230', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2268827627.jpg', 0.4, 2.2, 26, 50.6, 20.8, '0.246745,0.054535,-0.726615,0.489899,-0.148153,-0.412159,0.906700,0.099919,-0.986351,-0.355920,0.158430,0.756994,-0.292435,0.566072,0.147804,-0.116982,-0.288651,-0.748820,-0.011239,-0.156487,-0.256556,-0.577572,-0.461753,-0.119245,-0.386407,-0.473283,0.481651,0.211236,-0.096551,0.237565,0.083712,0.177679,0.362880,0.590838,-0.289910,0.143288,0.068896,0.011468,-0.142417,0.122717,0.402634,-0.326775,-0.284420,0.347048,-0.019740,0.340844,0.587383,-0.430229,-0.303290,0.098989,0.443328,-0.093072,-0.184432,0.013230,0.368763,-0.021749,-0.010951,0.454701,-0.054214,-0.136790,-0.101706,0.068835,-0.824825,0.086232,0.049528,0.444741,-0.797193,0.569778,-0.372127,-0.120065,-0.154218,-0.615527,0.086581,0.342159,0.185984,0.122894,-0.365235,0.023868,-0.504976,0.353045,0.529063,0.347643,-0.447031,0.626272,-0.425517,-0.478263,-0.309963,-0.346174,-0.479502,-0.036433,0.069270,0.213629,-0.465434,0.553289,-0.259863,0.222791,-0.180839,-0.313950,-0.167139,-0.376436,-0.103847,-0.318033,-0.389195,-0.680497,-0.377323,-0.024838,0.084217,-0.414114,0.808808,-0.743896,0.169936,0.508782,0.009192,-0.153518,0.706278,0.067441,0.171125,0.015170,-0.067535,0.314278,-0.209994,0.289939,0.242881,0.510179,0.139927,-0.210551,-0.424065,0.733826', '1783461', '4058933', '24325918', '25810920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25727519', '上锁的房间SP', '剧情', '在榎本径（大野智 饰）消失后，芹泽豪（佐藤浩市 饰）律师和律界新人青砥纯子（户田惠梨香 饰）的工作与生活又重新回到平凡的轨道中。这天，芹泽出发与委托人藤林仓三洽谈价值10亿日元美术品的捐赠事宜。谁知当他和对方的外甥女冈村郁子（黑木瞳 饰）进入门窗紧闭的别墅时，却发现委托人已经被人用高尔夫球杆杀害。与此同时，正调查一起密室救人事件的纯子意外重逢半年前归国、此刻正经营一家防盗公司的榎本。奇妙的是两起看似不相关的密室案就这样交融在一起。围绕美术品的去留，新的密室杀人案再度发生，疑点重重，真凶何在？本片根据贵志佑介的同名原作改编，为该电视剧集的SP版。©豆瓣', '大野智', '松山博昭', 7.8, 11579, 'tt3196684', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2159300598.jpg', 0.3, 2, 27.5, 49.4, 20.7, '0.280997,0.086597,-0.591189,0.132854,0.253408,-0.228462,0.616098,0.261911,-0.332949,-0.654604,0.231912,0.628409,-0.386245,0.052875,0.264956,0.150206,-0.438088,-0.715384,-0.243565,-0.247724,-0.112621,-0.526061,-0.141029,-0.091324,-0.065881,0.122991,0.743251,0.232904,-0.072235,0.351846,0.182572,0.422223,-0.588562,0.229284,-0.095048,0.014992,0.147415,0.229451,-0.258092,0.083686,-0.202908,-0.276018,-0.136673,-0.135888,0.191553,0.366959,0.660509,-0.114442,-0.206553,-0.168943,0.290932,0.036778,-0.241863,0.052493,0.520009,0.254113,0.197743,0.394296,-0.583618,0.089700,0.071134,-0.221680,-0.511292,-0.146711,0.229397,0.260237,-0.255974,0.111031,-0.237468,-0.056590,0.148150,-0.308819,0.050867,0.440052,0.386813,0.175859,-0.079382,0.137864,-0.331035,0.120043,0.404610,-0.010465,0.128626,0.374042,0.056131,-0.373342,-0.290441,0.130910,-0.079948,-0.139406,0.336789,0.146559,0.008067,-0.151533,-0.550612,-0.370072,-0.202797,-0.099120,0.152401,-0.138398,-0.057388,-0.961487,-0.174811,-0.243824,-0.257710,0.221116,0.230669,-0.135451,0.216081,-0.727111,0.126068,0.217512,0.051905,-0.281011,0.363951,0.106903,0.105668,-0.216343,-0.142826,-0.145784,0.183689,0.500838,-0.058817,0.282293,0.092166,-0.188592,-0.548793,0.132638', '25723905', '2369613', '20274039', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25727544', '寻找罗麦', '剧情', '赵捷和罗麦相识已久，在经历过一次导致少年意外死亡的车祸之后，二人逐渐产生罅隙。事后，罗麦去了西藏，却全然未知等待他的是一场不测风云。罗麦走后，赵捷也踏入这段象征涅槃与救赎的莲花之旅，一直在路上的他，始终在寻找着一个模糊的身影。', '韩庚', '王超', 4.2, 6209, 'tt3728130', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2518268771.jpg', 31.2, 39.9, 19.6, 6.1, 3.2, '0.139080,0.036677,-1.076953,0.587537,0.076247,-0.418959,1.173646,0.038805,-0.772778,-0.285029,0.316148,0.853281,-0.398468,0.247540,0.307042,-0.121651,-0.108199,-0.584646,-0.043649,-0.296383,-0.519302,-0.381559,-0.318899,0.188272,-0.089144,-0.202511,0.684517,0.522656,-0.251947,0.819045,0.096073,-0.154960,-0.415986,1.079247,-0.150537,0.272966,0.000924,0.444550,-0.167961,0.054857,0.496443,-0.802616,-0.479473,0.288582,-0.109222,0.364795,0.805527,-0.619409,-0.161098,0.131027,0.090171,-0.459787,-0.217010,0.039438,0.311802,-0.027125,-0.031216,0.359547,-0.274338,-0.005828,-0.162564,0.052349,-0.616177,-0.203629,-0.177325,0.460665,-0.998699,0.857786,0.295152,-0.353224,0.308948,-0.501701,0.306623,0.607988,0.203522,0.315403,-0.297264,-0.207435,-0.373582,0.233773,0.926521,0.148180,-0.335276,0.674618,-0.183473,-0.407060,-0.421419,0.310067,-0.520274,0.118343,0.498487,0.269776,-0.379897,0.219299,-0.689030,0.179890,-0.317040,-0.210096,-0.165721,-0.414166,-0.161710,-0.563984,-0.064882,-0.627417,-0.494664,0.282609,-0.382805,-0.310689,0.215134,-0.810881,0.701037,0.634472,0.045110,-0.354358,0.620486,0.222330,0.286273,-0.375340,-0.009828,0.508696,-0.254395,0.728666,0.157943,0.382775,-0.034510,0.512491,-0.483645,0.422111', '3011051', '26245360', '21348112', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728006', '速度与激情9', '动作', '“唐老大”多姆·托莱多（范·迪塞尔 饰）与莱蒂（米歇尔·罗德里格兹 饰）和他的儿子小布莱恩，过上了远离纷扰的平静生活。然而他们也知道，安宁之下总潜藏着危机。这一次，为了保护他所爱的人，唐老大不得不直面过去。他和伙伴们面临的是一场足以引起世界动荡的阴谋，以及一个前所未遇的一流杀手和高能车手。而这个名叫雅各布（约翰·塞纳 饰）的人，恰巧是多姆遗落在外的亲弟弟。', '范·迪塞尔', '林诣彬', 5.2, 186238, 'tt5433138', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2640611704.jpg', 9.6, 36.2, 43.1, 9.2, 1.9, '-0.062845,-0.223470,-0.818555,0.514070,-0.168118,-0.327750,0.825728,0.131589,-0.807746,-0.310044,-0.082430,0.766600,0.043621,0.307900,0.668388,-0.053647,-0.287371,-0.589846,-0.097271,-0.123163,-0.261830,-0.348565,-0.464548,-0.387321,-0.083536,-0.324749,0.460764,0.220252,-0.220024,0.315958,0.553870,0.596514,-0.088729,0.629193,-0.018997,0.063472,-0.194709,-0.054901,-0.639190,-0.008450,0.092061,0.028511,-0.199464,0.100549,0.121880,0.174729,0.407364,-0.614705,-0.028698,-0.386322,0.031595,-0.487095,0.116315,0.204875,0.064623,-0.189550,0.267201,0.013481,-0.135291,-0.085307,0.194364,-0.077506,-0.669753,-0.043720,0.290904,0.019373,-0.653285,0.361947,-0.092224,-0.228854,-0.009690,-0.200733,0.300301,0.507246,0.444645,0.073705,-0.275406,-0.095510,-0.433973,-0.196508,0.848372,0.198904,-0.319990,0.109015,-0.169487,-0.342168,-0.323210,-0.455730,-0.877595,0.178275,0.379795,-0.037282,0.039346,0.453422,-0.457831,-0.265902,-0.194336,-0.241671,-0.230852,-0.555496,-0.087472,-0.427084,-0.208718,-0.543214,-0.179340,0.109507,0.117221,-0.345488,0.662767,-0.884760,0.375634,0.330583,0.289948,-0.333685,0.371015,0.237897,0.464872,-0.252073,-0.302562,0.294204,0.387105,0.277700,-0.050985,0.228144,-0.081818,-0.033180,-0.151575,0.446914', '25721544', '1308755', '1301022', '1293077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728008', '潜伏3', '惊悚', '兰伯特闹鬼事件数年前，美丽的花季女孩奎恩·布伦纳（斯戴芬妮·斯考特 Stefanie Scott 饰）辗转找到已经退休的灵媒伊莉丝（林·沙烨 Lin Shaye 饰）。奎恩的妈妈在一年半前去世，但是她总感觉妈妈就在身边，她渴望能和妈妈再说上几句话。被奎恩真挚的情感所打动，伊莉丝决定帮她一把，谁知却似乎与某个可怕的众生建立了联系，伊莉丝告诫女孩决不能再尝试与亡母沟通。在此之后，热爱表演的奎恩回到原有生活中，谁知某次诡异事件让她遭遇严重车祸。伤愈出院后，围绕在奎恩身边的怪事愈演愈烈。而本以为没有联系的伊莉丝，似乎也觉察到奎恩所处的危险境地，她艰难地作出决定，救助这名随时会被夺去性命的女孩……©豆瓣', '林·沙烨', '雷·沃纳尔', 6.5, 38105, 'tt3195644', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2236779569.jpg', 1.8, 12.9, 51.7, 23.4, 10.2, '-0.010729,0.136352,-0.727129,0.310755,-0.077395,-0.321662,0.691475,-0.120220,-0.526483,-0.348385,0.201454,0.693508,-0.333944,0.339384,0.247430,0.178303,-0.224958,-0.813005,0.263325,0.042196,-0.402418,-0.416374,-0.270247,-0.142096,-0.083851,-0.400883,0.479672,0.086842,-0.393102,0.503328,-0.006169,0.337399,0.047406,0.702553,-0.132079,-0.013960,-0.045982,0.250461,-0.445143,0.089325,0.299238,-0.229216,-0.083916,0.232915,0.212596,0.328681,0.579365,-0.181325,-0.335919,0.050056,0.459930,-0.102723,0.149682,0.242633,0.248653,0.112782,0.209384,0.148781,-0.542059,-0.120711,-0.041042,-0.075721,-0.437109,0.104892,-0.031459,0.186160,-0.487415,0.130318,0.050912,-0.001011,0.332535,-0.247987,0.196082,0.375256,0.192389,0.429307,-0.028553,0.030193,-0.215267,0.062785,0.650260,-0.230653,-0.224850,0.319694,-0.160494,-0.229649,-0.043384,-0.170547,-0.355430,0.170145,0.006078,0.148765,-0.333885,0.440631,-0.272506,-0.156598,-0.464853,0.142149,-0.015845,-0.349488,-0.109574,-0.419829,-0.097235,-0.176974,-0.409146,0.122900,-0.030901,-0.270697,0.516361,-0.691517,0.491605,0.514178,0.522329,-0.526678,0.433668,0.341901,0.214235,-0.306998,0.105011,0.614730,-0.199511,0.325707,0.296259,0.108345,-0.021610,0.113365,-0.351498,0.488489', '1301022', '1300958', '26245360', '25858759');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728010', '老手', '剧情', '该片主要描述刑警追缉罪犯的故事，黄正民饰演被称为“韩国FBI”的广域调查队刑警徐道哲（音），是一位极具使命感，同时又富有人情味的警察，刘亚仁则饰演“富三代”赵泰晤（音），虽然表面上显得自信十足，但内心里却隐藏着不为人知的自卑。实力派演员刘海镇饰演赵泰晤的帮手崔常务，吴达洙饰演徐道哲的助手吴组长。', '黄政民', '柳昇完', 7.7, 118584, 'tt4768764', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2251912398.jpg', 0.2, 1.6, 28, 51.2, 18.9, '0.060834,-0.006176,-0.235989,1.055649,0.092549,0.113119,0.712084,0.285942,-0.531846,-0.657087,0.048359,0.237822,-0.052550,0.133585,0.254101,-0.364021,-0.362228,-0.292691,-0.468790,-0.084586,-0.145563,-0.451676,-0.313408,-0.110889,-0.110206,0.081464,0.864962,0.233492,-0.394794,0.393823,0.684177,0.534231,-0.021136,0.030354,0.168025,0.016224,0.146646,-0.377824,0.236677,-0.395774,0.152823,-0.234747,-0.159281,0.132150,0.209330,0.580394,0.324749,0.100295,-0.201238,0.169307,0.255265,-0.238714,-0.030331,-0.514645,0.482025,0.157838,0.300468,0.194085,0.152980,-0.306607,-0.026831,-0.259791,-0.964132,0.264510,0.441621,0.201990,0.002829,0.132524,-0.027880,0.120384,-0.034048,0.219008,0.142690,-0.499140,0.081415,0.395923,0.164528,0.470782,0.036868,0.456426,0.420737,0.399047,-0.237250,-0.109708,-0.563295,-0.647805,-0.354083,-0.408182,-0.446441,0.219408,-0.041954,-0.346157,0.342391,-0.194914,-0.034110,-0.004938,0.014601,0.709122,-0.073871,-0.062570,0.113136,-0.663263,0.020930,-0.447587,0.146229,-0.140744,0.013348,-0.237217,0.946683,-0.709508,-0.259357,0.436886,-0.101924,-0.338086,0.402005,0.064697,0.025666,-0.538544,-0.326630,0.298743,0.205376,-0.254159,0.150430,0.410375,-0.651309,-0.572351,0.104691,-0.021154', '3670447', '27602116', '25880986', '26848640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728581', '少年透明人', '奇幻', '13岁的米迦勒（卢多维科·吉拉尔德罗 Ludovico Girardello 饰）是一个在学校经常被人欺负的少年，他喜欢同班的美丽女孩斯黛拉（诺雅·扎塔 Noa Zatta 饰），于是鼓起勇气接受了对方的万圣节化装舞会的邀请。他在中国人开的杂货店淘到一套超人服装，原本满心欢喜的去参加派对，谁知遭到了坏孩子们的羞辱。米迦勒冒着大雨跑回家，第二天一早居然发现自己变成了透明人。突如其来的变化让他惊诧不已，不过却也因此得到不少的乐趣，比如捉弄欺负他的孩子们，跟踪斯黛拉等等，当然与此同时也闹出了笑话。他的人生开始有了微妙的变化，借着隐身的机会和斯黛拉成为了朋友。而就在此时，斯黛拉被神秘之人绑架了……©豆瓣', '卢多维科·吉拉尔代洛', '加布里埃莱·萨尔瓦托雷斯', 6.4, 6927, 'tt3078296', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2272066864.jpg', 1.9, 13.1, 55.2, 22.1, 7.5, '0.500971,-0.029794,-0.795119,0.290759,-0.522185,-0.191746,0.617662,0.222148,-0.495412,-0.126454,0.181569,0.735742,-0.580646,0.399585,0.401836,0.085985,-0.134263,-0.547708,0.101661,-0.097014,-0.243101,-0.234862,-0.205720,-0.248057,0.168256,-0.381248,0.116347,0.031356,-0.300840,0.517776,0.453473,0.203313,0.115420,0.767788,-0.241098,0.075625,0.087657,0.099581,0.277651,0.220486,-0.084042,-0.334127,-0.236158,0.264946,-0.083149,0.449278,0.625914,-0.188975,-0.157785,-0.079011,0.456677,-0.337810,-0.015222,0.105568,0.273184,-0.059646,0.088627,-0.163521,-0.058843,-0.003523,0.101494,0.106095,-0.451997,0.381165,0.097221,-0.032231,-0.724704,0.549002,0.053098,-0.211388,0.049777,-0.322896,0.299503,0.330622,0.028929,0.401104,-0.027199,0.058557,-0.746580,0.120087,0.741513,-0.006495,-0.213918,0.339652,-0.232239,-0.152085,0.110526,-0.293978,-0.322210,-0.008446,0.489304,-0.213361,-0.332623,-0.109744,-0.579983,-0.209876,-0.119591,-0.183611,-0.055420,-0.542862,-0.219745,-0.649454,0.090367,-0.147466,-0.344886,0.192975,-0.051977,-0.327394,0.670939,-0.871330,0.267965,0.687153,0.140868,-0.603897,0.725499,-0.063837,-0.085250,0.071054,-0.131233,-0.007085,0.152913,0.288068,0.282380,0.501387,0.023471,-0.251861,-0.218316,0.491610', '2990737', '1308755', '3326747', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728590', '六福喜事', '喜剧', '马来西亚富商雷鸣（黄百鸣 饰）与死对头杨亚伟（曾志伟 饰）二人多年来斗生斗死，这次要斗快抱孙！雷鸣得知杨亚伟正期待儿子Alex（林德信 饰）与儿媳珊珊（吴千语 饰）诞下男孙，怒不可遏，就要挟二世祖侄孙雷带子（郑中基 饰）与侄孙媳妇雪儿（薛凯琪 饰）传宗接代，否则停止二人的生活资金。更重金礼聘天王级催生陪月婆宫三（吴君如 饰）严格监管，虽然起初令二人夫妻生活翻天覆地，但却间接重拾了夫妻间久违了的激情和浪漫，展开了活色生香的“生育的进击”。雷鸣确诊患有老年痴呆，为了圆其心愿，雪儿假装大肚，并向有孕在身的黛黛（熊黛林 饰）和秀波（于波 饰）夫妇求助，欲借其子瞒过叔公。不料想生产当日，杨亚伟出现，众人精心编造的弥天大谎眼看就要拆穿······©豆瓣', '黄百鸣', '谷德昭', 5.3, 35717, 'tt3456464', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164881898.jpg', 11.8, 29.9, 44.7, 9.4, 4.1, '-0.214095,-0.194426,-0.420156,0.264584,0.127379,-0.125471,0.376768,0.175448,-0.391993,-0.294251,0.165705,0.369697,-0.330758,0.066774,0.207858,-0.116213,-0.036187,-0.544208,0.128777,0.260941,0.021472,-0.289361,0.074221,-0.145455,-0.154119,-0.282570,0.338923,-0.175702,0.031682,0.574769,0.322449,0.090779,-0.313611,0.008122,0.009180,0.153724,-0.385650,0.405532,-0.430208,0.023932,-0.010229,-0.251253,-0.011073,-0.004003,0.093600,0.378766,0.409449,-0.340214,-0.003760,-0.295680,0.269504,-0.141615,-0.060675,0.189404,0.080596,-0.149351,0.290634,0.237081,-0.156665,-0.073383,0.101639,-0.127910,-0.288631,0.301098,0.300835,-0.133627,-0.344764,0.179877,-0.213738,-0.062436,-0.024974,-0.068506,0.024868,0.330164,0.001370,0.386800,-0.420572,0.245685,-0.352779,0.472281,0.218175,0.171162,0.025884,0.121270,0.231683,-0.156466,0.119388,-0.156367,-0.373721,0.013626,0.228357,0.259126,0.164564,0.167439,-0.225426,-0.147811,-0.333747,0.281643,0.389563,-0.269498,0.147672,-0.553697,0.029176,-0.332199,-0.027364,0.187868,0.374429,-0.398827,0.366896,-0.474354,0.161854,-0.272394,0.325738,-0.687295,0.336536,0.070613,0.233197,-0.372458,-0.001807,-0.156200,-0.150667,-0.219918,0.236111,0.053816,-0.115253,-0.016058,-0.091403,-0.181273', '6514136', '26991880', '3230195', '1304600');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728612', '书店', '剧情', '故事发生在1959年的英格兰。弗洛伦斯（艾米莉·莫迪默 Emily Mortimer 饰）在不久之前失去了她的丈夫，但坚强的女人并没有沉湎于悲痛之中，她知道，自己必须坚强的生活下去。弗洛伦斯来到了偏远的海滨小镇哈堡，在这里，她倾尽所有开了一家小小的书店。这是当地唯一的一家书店，在此之前，小镇上的所有人都从来没有接触过文学。弗洛伦斯的书店给小镇居民们的世界打开了新的大门，整个小镇都因为她的书店的出现而产生了变化，书店的存在更让弗洛伦斯结识了和自己趣味相投的同道中人艾德慕（比尔·奈伊 Bill Nighy 饰），与此同时，弗洛伦斯的出挑也招致了别有用心者异样的眼光。©豆瓣', '艾米莉·莫迪默', '伊莎贝尔·科赛特', 7.9, 24782, 'tt3127022', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522907851.jpg', 0.3, 1.5, 22.8, 50.9, 24.5, '0.574082,0.118814,-1.009014,0.553392,-0.196900,-0.291624,1.067333,0.170647,-0.598843,-0.082743,0.071339,0.919119,-0.190890,0.311246,0.236953,0.077385,-0.242501,-0.651815,0.000802,-0.580957,-0.330714,-0.316378,-0.318423,-0.376583,-0.227297,-0.368155,0.376683,0.232872,-0.152614,0.332882,0.190192,0.225341,0.090263,0.630136,-0.394634,0.191634,-0.059012,0.121501,-0.165978,0.022817,-0.071070,-0.195870,-0.398499,0.290951,-0.021489,0.345571,0.610380,-0.028335,-0.322764,0.063639,0.301595,0.101258,-0.034745,-0.007234,0.374265,-0.238974,0.064918,0.281121,-0.229873,-0.098430,0.172443,0.008923,-0.627967,-0.047871,0.148793,0.172704,-0.617324,0.606384,0.009657,-0.263649,-0.116468,-0.446330,0.292933,0.241079,0.247097,0.215766,-0.170236,-0.018161,-0.672621,0.193012,0.592586,0.009883,-0.535961,0.349095,-0.526031,-0.375744,-0.126870,-0.264693,-0.531910,0.152107,0.312450,0.109271,-0.392987,0.241463,-0.758259,-0.004513,-0.032745,-0.512813,0.266851,-0.340567,-0.320902,-0.791598,-0.148216,-0.396459,-0.282266,0.013718,0.014498,-0.143735,0.740622,-1.079256,0.290515,0.614729,0.359358,-0.506192,0.962782,-0.248125,0.140865,0.216488,-0.094795,0.335637,-0.039725,0.757441,0.067193,0.471772,-0.136891,-0.164518,-0.435597,0.806958', '3055049', '1292211', '1308755', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25728734', '非狐外传', '爱情', '故事发生在遥远的古代，那个世界里，人妖混居，世间永无太平。王生（方力申 饰）是一介平凡书生，在乱世之中，个性胆小懦弱的他只求能够安心读书，平安过活。一天，一位名叫仙儿（周秀娜 饰）的神秘女子不请自来，突然出现在了王生的面前，王生虽然不知仙儿究竟是何方神圣，但依旧被她身上所散发出来的媚气所深深吸引。自仙儿出现之后，城中屡屡发生离奇的杀人案件，被害者均因为心脏被掏出而死，没有人知道这些失踪的心脏到底去了哪里。少女小翠（谈莉娜 饰）暗恋着王生，看到他被仙儿迷得神魂颠倒，小翠的心中很不是滋味。一次偶然中，小翠窥见了仙儿用妖法迷惑王生的秘密，心急如焚的她决定靠自己的力量揭开仙儿的“画皮”。©豆瓣', '周秀娜', '钱升玮', 3.3, 9653, 'tt7494060', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2172800850.jpg', 59.6, 25.1, 10.2, 2.1, 3, '0.474430,0.285943,-0.579620,0.265019,-0.184565,0.164577,0.763980,-0.236753,-0.560909,-0.308573,0.428432,0.674897,-0.354640,0.305825,0.065793,0.458461,0.170701,-0.680075,-0.066121,-0.385465,-0.078868,-0.163329,-0.484189,0.221452,-0.141893,-0.372511,0.498554,0.101296,0.152459,0.491176,0.354860,0.311770,-0.248902,0.459231,-0.345818,0.062299,-0.044096,0.002853,0.013517,0.022200,0.163229,-0.476863,-0.194211,0.343703,-0.336575,0.062322,0.588797,-0.442119,-0.173373,-0.117167,0.391093,-0.048924,-0.053143,0.122371,0.014320,-0.199546,0.320387,0.146206,-0.257372,0.059930,0.213236,0.365812,-0.502313,0.127959,0.303746,0.461668,-0.365828,0.025224,-0.042726,-0.186993,0.072317,-0.438117,0.318066,-0.013454,0.429083,0.355775,-0.174619,-0.067438,-0.669846,-0.055977,0.752536,-0.006412,-0.305699,0.429528,-0.066528,-0.136632,0.160957,-0.287559,-0.535701,0.362421,0.078408,0.108697,-0.375977,0.232136,-0.202974,0.170861,-0.201625,0.175373,-0.214893,-0.259114,-0.625674,0.184219,-0.566135,-0.393641,-0.312449,-0.074614,0.057106,-0.295124,0.602390,-0.862714,0.176678,0.412978,0.034095,-0.338316,0.496669,0.207403,-0.044106,-0.057065,-0.248196,0.158801,-0.036248,0.217868,-0.150964,0.459928,-0.155188,-0.056576,-0.383253,0.365531', '1308755', '4275444', '35030151', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25731059', '宾虚', '剧情', '《宾虚：一个基督徒的故事》虚构了一个犹太王子——犹大·宾虚（Judah Ben-Hur），以一个类似《基督山伯爵》的故事为我们展现了他因与好友信念不同而遭到陷害、继而流放、被卖为奴、成为角斗士回乡复仇，最终成为一名耶稣信徒的曲折而传奇的一生。新版《宾虚》由《刺客联盟》（Wanted）导演提莫·贝克曼贝托夫（Timur Bekmambetov）导演，剧本由《为奴十二年》的编剧约翰·雷德利（John Ridley）在基思·克拉克（Keith Clarke）初稿剧本基础上创作。', '杰克·休斯顿', '提莫·贝克曼贝托夫', 5.7, 7704, 'tt2638144', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2382529006.jpg', 4.8, 26.1, 52.7, 12.2, 4.2, '0.150537,-0.099082,-0.013399,1.071174,0.020309,-0.443935,0.632470,0.157397,-0.327421,-0.535166,0.440280,1.215473,-0.004765,0.159631,0.471480,-0.158304,-0.255170,-0.518768,-0.020531,-0.133431,-0.024353,-0.501517,-0.081830,-0.361442,-0.367735,-0.373900,1.021514,-0.042231,-0.166750,0.031359,0.331273,0.492552,-0.003960,-0.304133,0.080721,0.180449,0.321435,-0.562078,-0.367318,0.447609,-0.216743,-0.073539,-0.023163,0.019902,-0.530108,0.388038,0.636449,-0.515663,0.310455,-0.331139,0.814648,-0.353335,0.026815,0.068745,0.006841,0.174514,0.140530,0.389813,0.170333,-0.142898,0.127861,-0.488336,-1.266466,-0.257579,0.225786,0.144009,-0.551456,0.430641,-0.211497,0.011438,0.115946,0.076097,0.064213,0.038849,0.857680,0.321877,-0.074099,-0.004088,-0.255473,0.664933,0.443860,-0.019298,-0.275138,0.250585,0.015580,-0.417453,0.094629,-0.268878,-0.634060,0.183539,0.153503,-0.242289,0.231388,0.378664,-0.766757,-0.446428,-0.485848,-0.063605,0.065904,-0.522378,-0.089990,-0.433985,-0.254863,0.275401,0.181559,-0.252892,0.320011,-0.289941,0.887081,-0.460459,0.267626,0.605360,0.041581,-0.509231,0.623751,0.005827,0.141529,-0.308043,0.110161,0.433909,0.391581,-0.024919,0.136828,0.015891,0.130011,-0.129089,-0.280161,0.534465', '27602116', '22265121', '6844861', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25731554', '西部慢调', '动作', '19 世纪末，16 岁男孩杰（柯蒂·斯密特-麦菲 Kodi Smit-McPhee 饰）来到美国，企图横跨北美寻找自己的心爱的姑娘，一名神秘的旅人塞勒斯（迈克尔·法斯宾德 Michael Fassbender 饰）加入杰的行列，两人一同向西行进，不料在美国西部荒原，被人 盯上，一场激烈的枪战也在等待着他们……', '本·门德尔森', '约翰·麦卡伦', 7.4, 11526, 'tt3205376', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2231094082.jpg', 0.6, 3.6, 34.5, 47.3, 13.9, '0.471924,0.062779,-1.105232,0.465955,0.281958,-0.271436,0.538074,0.174691,-0.053002,-0.229218,0.185314,0.987318,-0.301715,0.228727,0.496479,0.123350,-0.287947,-0.754312,-0.177785,-0.346250,-0.430699,-0.269699,-0.198372,-0.320758,-0.087466,-0.203034,0.638592,0.125921,-0.317072,0.591551,0.361250,0.679714,-0.299742,0.482195,-0.420931,0.147458,0.738405,-0.265805,-0.358407,0.378956,-0.141724,-0.161153,-0.261385,0.000788,-0.086142,0.332748,1.039667,-0.555641,0.385052,0.313206,0.198598,-0.534614,-0.081417,-0.073335,0.671236,-0.426657,-0.203356,0.314265,0.103931,0.318879,-0.228415,-0.425966,-0.288411,0.240470,-0.057743,0.429240,-0.675279,0.541358,0.121684,0.137453,0.127968,-0.098831,0.160060,0.368359,-0.293324,0.313276,0.189670,-0.020668,-0.621384,0.080738,0.800218,0.005312,-0.085930,0.267031,0.087390,-0.351361,0.028549,-0.282793,-0.701652,-0.234444,0.686138,-0.546763,0.134086,0.158951,-0.798901,0.072142,-0.658777,-0.005205,-0.028245,0.032653,-0.191099,-0.891357,0.102633,-0.399936,-0.078525,0.400735,-0.234579,0.069476,0.623831,-0.495511,0.019146,0.735855,0.383360,-0.147176,0.643421,-0.343556,0.214456,-0.390469,-0.316046,0.458091,0.242635,0.039434,0.182989,0.522939,-0.063640,0.088349,-0.320556,0.060022', '2159244', '3147969', '1309194', '3011051');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25731805', '宁静咖啡馆之歌', '剧情', '岬（永作博美 饰）自幼便对咖啡有着非常浓厚的兴趣，长大之后，她将兴趣变成了事业，成为了专业的咖啡豆烘焙师。岬自幼生长在一个破碎的家庭之中，父亲在某一日不告而别，父爱的缺失一直都是岬的一块心病，终于，她下定决心离开大城市，返回故乡能登半岛，将一座破败的小木屋改造成为了咖啡 店，一边从事着自己挚爱的咖啡事业，一边等待父亲的归来。父亲久久都没有现身，两个可爱又可怜的孩子吸引了岬的注意。这两个孩子由他们的妈妈抚养，但是妈妈常常都不在家，只留下泡面就匆匆出门打工去了。渐渐地，美咲开始扮演起了孩子们的照顾者和保护者的角色来。©豆瓣', '永作博美', '姜秀琼', 7.6, 5984, 'tt3524792', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2266319989.jpg', 0.3, 2.7, 32.2, 46.4, 18.4, '0.101050,0.079972,-0.590751,0.479275,-0.389825,-0.423283,0.730528,0.379601,-0.370311,-0.120761,0.135838,0.972434,0.230007,0.622057,0.085235,0.187330,-0.253905,-0.640506,-0.115280,-0.226271,-0.235943,-0.254186,-0.165811,0.020248,-0.229555,-0.223826,0.471363,-0.181159,0.039278,0.363679,0.032088,-0.125294,-0.121209,0.563402,-0.367132,0.195004,-0.004013,0.048163,0.011262,0.099398,0.135447,-0.255878,-0.006861,0.121647,0.260345,0.127772,0.953272,-0.149775,-0.165399,-0.369018,0.308161,-0.177368,-0.029222,0.148411,0.374111,0.151300,0.105952,0.144253,-0.427427,0.152131,0.021272,-0.191215,-0.488748,-0.195726,0.183516,0.035695,-0.974882,0.633477,0.136632,-0.442092,0.137923,-0.474547,0.327395,0.241462,-0.021529,0.709587,-0.365199,0.240787,-0.473151,0.210229,0.559234,-0.234917,0.075240,0.358458,-0.136234,-0.388845,0.163776,-0.234063,-0.469968,-0.320679,0.040252,0.243680,-0.136516,0.030787,-0.774232,0.161189,-0.117862,-0.350065,0.335169,-0.319262,-0.140278,-0.455280,0.134846,-0.249734,-0.242275,0.182189,-0.112911,-0.253983,1.074517,-0.581874,0.306918,0.592978,0.228951,-0.638954,0.790386,0.080348,0.318096,-0.155732,0.124070,0.391891,-0.146154,0.253905,0.190709,0.483303,-0.130174,0.008881,-0.468801,0.398745', '1308609', '3811356', '1306031', '1307146');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25733490', '奇迹', '剧情', '影片讲述了一对夫妻带着四个女儿，在靠近海边的独立小农庄里，依靠养蜂过着自给自足的独立生活，远离城市和社会人群。然而有一天，一个德国少年犯在重新融入社会 计划下进入到她们的生活里，同时，一个名叫《神奇村庄》的真人秀节目也在这里选景拍摄，片中有美丽性感的主持人……这一切新鲜事物，打乱了她们艰苦却简单平静的生活，尤其是进入青春期的大女儿吉索米拉，对外面的缤纷世界充满渴望。', '阿尔芭·罗尔瓦赫尔', '阿莉切·罗尔瓦赫尔', 7.5, 6726, 'tt3044244', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204889585.jpg', 0.6, 3.4, 34.8, 44.5, 16.7, '0.104651,0.231522,-0.851520,0.717735,-0.282459,0.139388,1.105512,0.033706,-0.373840,-0.011970,0.141143,0.618288,-0.136066,0.395488,0.189137,0.201162,-0.518381,-0.502900,-0.319508,-0.107334,-0.210166,-0.301307,-0.423257,-0.215736,-0.149207,-0.332276,0.710950,0.393952,-0.204126,0.274678,0.018158,-0.279193,-0.423358,0.235328,-0.307279,0.023599,0.199320,0.261954,-0.548221,0.290555,-0.201387,0.159157,-0.367547,-0.071631,0.084789,0.059983,0.972550,-0.306270,-0.352530,0.128768,0.462263,-0.013116,-0.402911,0.033931,0.284389,0.111104,0.213281,-0.090249,-0.336718,0.117468,-0.286937,-0.407743,-0.590602,0.017418,0.155673,0.053395,-0.570300,0.497719,0.444017,-0.343468,0.202317,-0.360575,0.210085,0.240942,0.363026,0.689094,-0.006946,0.331298,-0.437956,0.246344,0.802450,-0.040812,-0.530258,0.429943,-0.597450,-0.318450,-0.139921,-0.142510,-0.606758,-0.236665,0.085513,-0.160965,-0.443783,0.248105,-0.614982,0.637948,0.070290,-0.501897,0.222424,-0.457649,-0.272899,-0.833548,-0.148022,-0.424222,-0.329487,0.246006,-0.076207,-0.292197,0.993147,-0.811322,0.382185,0.501351,0.314769,-0.379887,0.840123,0.020233,0.464613,-0.317461,-0.222988,0.363691,-0.323966,0.349293,0.041992,0.556893,-0.634387,0.146792,-0.720228,0.651053', '21619567', '3005387', '1467779', '2334814');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25736048', '夏目友人帐：曾几何时下雪之日', '剧情', '4期にわたり放映されたアニメ『夏目友人帳』の完全新作OVA。妖怪を見ることができる夏目貴志が、自称用心棒の妖怪・ニャンコ先生と共に妖怪たちと交流する様を描く。', '神谷浩史', '大森贵弘', 9.4, 21722, '有朝一日暮雪时', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2151897085.jpg', 0.1, 0.2, 4.3, 21.3, 74.2, '0.118426,-0.417504,0.558611,0.098609,-0.142214,-0.116237,-0.222647,0.274057,0.045519,-0.681492,0.121650,-0.032193,-0.462903,0.112724,-0.005281,-0.596835,0.149059,-0.046002,0.241579,0.430923,0.532113,0.101613,-0.172584,0.037057,-0.425438,-0.530183,0.410573,-0.425268,0.198610,-0.108827,-0.422675,0.022180,-0.722825,-0.629691,0.503163,-0.099355,0.986866,0.112009,0.033333,0.284828,-0.925409,0.566155,0.238430,-0.409311,-0.119091,-0.059004,0.662618,-0.703940,-0.376915,0.173368,0.042337,0.603107,-0.050069,0.298692,0.359200,0.173697,0.622895,-0.119646,0.511314,0.134329,-0.599810,-0.187166,0.432645,0.244491,0.107423,0.213734,0.813974,0.270182,0.021551,0.010900,0.315690,0.016589,-0.328047,-0.100660,0.725142,-0.105789,0.470490,0.261994,0.711420,0.685962,-0.116390,-0.101043,-0.120602,0.508204,0.065312,-0.524223,-0.011383,-0.436247,0.138362,0.284385,-0.566462,-0.009862,-0.356167,0.374005,-0.562792,-0.268991,0.056504,0.842052,0.195381,0.030177,0.305263,-0.657210,0.046717,-0.037405,0.378813,-0.460214,0.926523,-0.568436,1.383646,-0.574087,-0.043337,0.661453,0.142070,0.190863,0.702139,-0.195713,-0.973497,-0.223284,-0.379400,0.225301,0.276837,0.287506,0.091358,-0.068233,0.424340,0.126786,0.005232,-0.081201', '27167055', '27602116', '1302661', '1298155');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25736455', '夜关门：欲望之花', '剧情', '老校长（申星一 饰）在人生暮年被查出身患绝症时日无多，心灰意冷的他并不急于治疗以苟且残喘，在一天天的平静时光和日益加重的病痛之中，他安然淡定的等待着死神的降临。一天，一位女护士（裴涩琪 饰）出现在了老校长暗淡的生命之中，护士年轻美艳，在有意无意之中，她似乎对老校长有着什么暗示，而这具鲜活热辣的肉体亦为老校长带来了生命之光。就这样，一段扭曲复杂的感情在白发苍苍的老者和朝气蓬勃的女子之间展开了，随着时间的推移，老校长渐渐发现，护士并没有表面看上去的那么单纯善良，在她的身后，似乎隐藏着什么不可告人的秘密。©豆瓣', '申星一', '林庆洙', 5.4, 7395, 'tt6059254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2154252366.jpg', 10.3, 30.8, 43.3, 10.9, 4.7, '0.162239,0.198529,-0.646634,0.416015,-0.411003,-0.283803,1.247257,0.083258,-0.621908,-0.413793,0.281221,0.497805,-0.189077,0.423732,0.128754,-0.088417,-0.144767,-0.522021,-0.270604,-0.129210,-0.243172,-0.628631,-0.458278,0.048139,-0.229080,-0.582358,0.597084,0.059578,0.024027,0.548561,0.166254,-0.023837,-0.030218,0.571954,-0.203628,-0.044768,0.112631,-0.009270,-0.034571,-0.137201,0.572395,-0.352039,-0.133404,0.157346,-0.371930,0.409271,0.661361,-0.290640,-0.376068,0.121363,0.466638,-0.196985,-0.060197,0.220370,0.369462,0.266538,-0.102171,0.263350,-0.370128,-0.048737,-0.139392,0.039327,-0.687784,0.160754,0.005940,0.827422,-0.441227,0.783839,0.344350,-0.268912,0.108477,-0.485063,0.223156,0.353338,0.055873,0.334290,-0.377837,-0.099279,-0.432784,0.296784,0.449048,0.298487,-0.639150,0.667347,-0.414695,-0.193759,-0.097257,0.030163,-0.682509,-0.194341,0.155277,0.187296,-0.293533,0.609639,-0.433179,0.190128,-0.182473,0.169871,-0.367380,-0.357110,-0.359336,-0.280470,-0.290401,-0.519911,-0.105472,0.242149,-0.031110,-0.167717,0.826947,-0.945004,0.472335,0.427775,0.343681,-0.100122,0.510752,0.111116,0.021524,-0.213267,-0.404357,0.358392,-0.130265,0.361684,0.235384,0.467199,-0.300751,0.144311,-0.349256,0.493361', '2377539', '2131640', '1304862', '1292062');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25738406', '如晴天，似雨天', '剧情', '电影《如晴天 似雨天》（Like Sunday, Like Rain）是由Leighton Meester (《绯闻女孩》Queen B)主演的一部文艺片。故事讲述在一个夏天，贫穷女生Eleanor为了生计去给一名12岁的孩子当保姆。Eleanor同时也是一名音乐家，而12岁的 孩子则是音乐神童，相处之下他们在彼此间找到自我....', '朱利安·夏特金', '弗兰克·威利', 8.3, 145299, 'tt3104818', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2261938616.jpg', 0.3, 1.6, 17.2, 44.6, 36.2, '-0.073257,-0.500468,-0.193083,0.553796,-0.345443,-0.268224,0.912514,0.163388,-0.700968,-0.609571,0.186211,0.913896,-0.055802,0.594174,0.260893,-0.198498,-0.200101,-0.612591,-0.173054,-0.238650,0.050087,-0.152276,0.140583,0.057816,-0.034723,-0.541630,0.822070,-0.334539,-0.089851,0.182862,0.452806,0.073098,-0.101550,0.214215,-0.317837,-0.100276,-0.147353,-0.014684,-0.303353,0.589408,-0.223321,-0.246402,-0.285618,-0.298264,-0.298376,0.437659,0.925574,-0.000848,0.057018,-0.023371,0.575887,-0.208790,-0.198384,-0.215853,0.440802,-0.051609,0.836782,0.006620,0.163743,0.092263,-0.184590,-0.472037,-0.475462,0.193732,0.300492,0.249767,-0.617900,0.375487,0.006983,-0.178824,0.234207,-0.413702,0.209914,-0.074789,0.326399,1.065396,-0.431064,0.284463,-0.503501,0.578754,0.932151,0.490620,-0.273355,0.895452,-0.505864,-0.461039,-0.157082,-0.315468,-1.055350,0.145820,0.146251,-0.357195,-0.199558,0.006105,-0.424914,0.067578,0.122704,0.004515,0.171433,-0.543897,-0.060190,-0.491215,0.214566,-0.184595,-0.181955,-0.173764,0.317464,-0.380679,1.470856,-0.752652,0.017325,0.787178,0.042359,-0.274754,1.024410,0.118016,0.231525,-0.318799,0.239647,0.141988,-0.120866,-0.084821,-0.266310,0.255935,-0.393271,-0.205833,-0.415071,0.084322', '1908036', '26348103', '25882279', '26593587');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25740192', '骄傲', '剧情', '1984年，英国首相撒切尔夫人采取铁腕手段打压工人运动，矿工群体发起了史上规模最大的一次罢工。在同年的伦敦同志骄傲游行中，一群男女同性恋决定主动为罢工工人筹款。然而尴尬也随之而来：工会竟然羞于接受他们的资助！这群同性恋决定绕过工会，直接走进工人家中。他们驱车前往南威尔士的一个煤矿村庄，给工人家庭带去了钱和物资。两个出身背景天差地远的群体从此产生了意外温暖的接触，并且在政府高压下结成了最不可能的联盟。《骄傲》改编自真实事件，不仅拥有80年代工人运动的历史影像，也记载了英国同志史上最感人的一页。两个群体从偏见到包容、从误解到联盟的蜕变充满欢笑和泪水，又让人为之动容。《骄傲》获得第67届戛纳电影节酷儿棕榈大奖以及英国最佳独立电影奖，同时提名2015金球奖最佳喜剧电影。©豆瓣', '本·施耐泽', '马修·沃楚斯', 8.3, 22694, 'tt3169706', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2218469416.jpg', 0.5, 1.3, 15.3, 48.1, 34.8, '0.107705,0.068141,-0.742605,0.776413,0.041474,-0.140134,0.418441,0.184967,-0.357890,-0.075234,0.255403,0.764443,-0.021176,0.128177,0.376493,-0.465178,-0.279116,-0.450977,-0.147051,-0.309995,-0.259995,-0.279300,-0.102612,-0.308443,-0.192544,-0.369487,0.703802,0.260077,-0.513042,0.435048,0.597303,0.368392,-0.081856,0.243404,-0.010401,-0.032769,0.542193,0.201132,-0.530194,0.285218,-0.304029,-0.071064,-0.247240,0.087471,0.049612,0.108144,0.625425,-0.203970,-0.199563,-0.184425,0.616089,-0.348741,-0.325966,0.067304,0.549473,0.120833,0.208581,0.222741,0.021390,0.102233,0.044349,-0.099731,-0.807972,0.010779,0.094958,0.020391,-0.662718,0.426116,0.056364,0.026924,-0.148314,-0.155145,0.139006,0.385474,0.184386,0.409806,-0.141338,0.236150,-0.321465,0.363064,0.686704,-0.116534,-0.427404,0.115939,-0.427346,-0.503664,0.127457,-0.454860,-0.268226,0.003025,0.278500,-0.203960,0.032419,0.392708,-0.769575,-0.050637,-0.032398,-0.423588,0.252675,-0.360511,0.189152,-0.761841,-0.196096,-0.008946,-0.136422,0.094510,0.272331,-0.138217,0.959612,-0.511143,0.107679,0.390288,0.315432,-0.697735,0.628111,0.159989,0.058359,-0.375068,-0.244130,0.159114,0.118799,0.280073,-0.164638,0.245598,-0.231737,-0.262846,0.015547,0.290436', '27602116', '3318306', '22265121', '25863940');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25741108', '中国好声音之为你转身', '剧情', '拥有音乐才华、天赋异禀的吴沛珊（吴莫愁 饰）在哥哥（华少 饰）的极力反对下不得不怀着遗憾报考了工商管理。即将开始的音乐节，是吴沛珊实现音乐梦想、让哥哥重新认识自己的最好舞台……同为热爱音乐的李子扬（李代沫 饰）是一位在酒吧工作的“草根”乐者。吴沛珊阴差阳错地与李子扬结识，并无意中发现了隐藏在李子扬心中不为人知的声乐才华。吴沛珊希望能帮助李子扬展现自己的才华，但李子扬非但不接受吴沛珊的帮助，反而与之渐行渐远，扑朔迷离的缘由让生性开朗的吴沛珊更为好奇，欲一探究竟……音乐节开赛在即，李子扬的心结在吴沛珊，丁飘飘（丁丁 饰），张乐（张玮 饰）、刘一宸（大山 饰）、王葳（王克 饰）、赵安娜（赵露 饰）等人的帮助下慢慢地云开雾散。正当吴沛珊，李子扬等人秣马厉兵、准备在音乐节一展身手时，哥哥的出现让吴沛珊的努力瞬间回到了冰点……音乐学院院长（汪峰 饰）对吴沛珊，这位来自工商管理专业的女孩关注有加，看着吴沛珊让他想到自己曾经热爱音乐的青春往事……', '吴莫愁', '蔡於位', 2.5, 3332, 'I Want You', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2163330003.jpg', 83.6, 10.2, 3.7, 0.8, 1.6, '0.229189,0.444054,-0.591495,0.774403,-0.244644,-0.244738,0.441869,0.294825,-0.701905,0.088890,-0.132889,0.380594,-0.276065,0.228157,-0.029781,-0.255923,-0.126448,-0.835678,-0.078228,-0.094028,-0.010243,-0.535722,0.060263,0.075321,-0.325648,-0.713125,0.274154,-0.159158,-0.032788,0.809846,0.490325,0.374472,-0.298856,0.730771,0.121012,-0.127398,-0.092544,0.203990,-0.516619,0.095164,0.166364,-0.170457,-0.225733,0.225024,-0.062257,0.039613,0.690533,0.047881,-0.081922,0.042905,0.417696,-0.202261,-0.092463,-0.130802,0.366767,-0.186758,-0.054239,0.072324,-0.288440,0.140980,-0.079882,-0.051183,-0.489035,-0.072399,0.367646,0.183294,-0.670976,0.577146,-0.128744,0.012925,0.258462,-0.333884,0.121098,0.295460,-0.029096,0.421726,-0.056534,0.110036,-0.321723,0.360909,0.526894,0.010725,0.333512,0.441669,-0.197856,-0.569759,-0.300996,0.359214,-0.674047,0.176070,0.312769,-0.132709,0.059368,-0.379459,-0.234348,-0.284213,-0.126428,0.172739,0.353568,-0.700338,-0.100634,-0.427604,-0.054250,-0.348310,-0.225073,-0.251607,0.070442,-0.649360,0.839826,-1.020239,-0.056020,0.298079,-0.124313,-0.343767,0.475586,-0.164697,-0.095508,0.171790,-0.442704,0.339569,-0.578394,-0.073458,-0.295706,0.800909,0.136276,-0.385113,-0.146315,0.252090', '4127270', '35030151', '3445516', '25908065');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25741398', '男孩与世界', '剧情', '荣获动画界最高荣誉——法国安锡动画影展首奖。童真如何面对成长的苦涩与世界的现实？宛如巴西版的囧男孩，一家务农生活穷苦却过得快乐。然而为求谋生，父亲只得离乡出外谋生。小男孩不忍母亲伤心，踏上寻父的大冒险旅程。沿途光怪陆离的人事，城乡风景，媒体，贪婪嘴脸的美国老板与压榨扁瘦得劳动者，美丽又悲伤的世界景象。', '阿莱·阿布鲁', '阿莱·阿布鲁', 8.8, 15479, 'tt3183630', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2183181319.jpg', 0.2, 0.9, 9.9, 37.5, 51.4, '-0.335815,0.069308,-0.300162,0.381841,0.118619,-0.547011,0.445587,0.267066,-0.310489,0.172307,0.059665,0.630720,-0.121545,0.530711,0.119154,-0.004515,-0.334960,-0.190175,-0.020776,-0.153266,0.435513,0.218293,-0.170142,-0.160229,-0.094557,-0.298983,0.922874,0.380844,-0.173332,0.267390,0.153490,0.061825,-0.554067,0.221305,-0.322864,-0.148216,-0.039445,0.347308,-0.601647,-0.474519,-0.251993,-0.099517,-0.519727,-0.071404,-0.092217,-0.030949,0.991985,0.167338,-0.254812,-0.173777,0.503660,-0.158864,-0.110278,0.028015,-0.114891,-0.154072,0.298516,-0.129989,0.259351,-0.056544,0.120043,-0.258638,-0.563972,0.056805,0.361265,0.012528,-0.267007,0.235078,-0.082198,-0.199598,-0.129130,-0.293012,0.157760,0.002400,0.505080,0.861159,0.237542,0.440207,-0.198657,0.668591,0.750631,0.082840,-0.600816,0.394926,-0.626667,-0.358381,0.032314,-0.845841,-0.848381,0.265754,0.160253,-0.378668,-0.368385,0.766576,-0.706096,0.157887,-0.182884,-0.222758,-0.072442,-0.086109,-0.208578,-0.386266,0.079589,-0.342225,-0.206443,-0.247179,0.322281,-0.185473,0.783093,-0.328466,0.177569,0.524537,0.151382,-0.444313,0.623210,0.300343,0.173910,-0.259796,-0.112791,0.772147,-0.252957,0.193253,-0.567161,-0.183671,-0.342574,0.017285,-0.382011,0.683820', '30349667', '3667102', '4066127', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25741577', '对不起，我爱你', '爱情', '从小被父母遗弃并被加拿大人领养到温哥华的武克（锦荣 饰）因帮朋友出头，误杀黑帮头目Billy的弟弟，出狱后被寻仇头部中枪却侥幸不死，但却因子弹取不出来，仅剩半年的生命。武克决定死前回中国寻找亲生父母，却再次遇见曾在温哥华有过一面之缘的女孩恩彩（温心 饰）。在堂姑姜海雁（伍宇娟 饰）的引导下武克找到生母谭慧茹（王姬 饰），见母亲身处豪门，想到自己被抛弃的命运和饥寒交迫的漂泊生活，此刻又命在旦夕，武克不忿，出于报复并未相认，且答应做其生母的养子崔允（黄恺杰 饰）的司机，与恩彩共同寻找妹妹过程中渐生情愫。最后得知，寻亲过程却是堂姑一手策划的阴谋，一段隐藏了二十多年的身世真相渐渐浮出水面……©豆瓣', '锦荣', '杨子', 4.2, 2816, 'tt3473390', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164220307.jpg', 42.5, 26.1, 18.5, 6.9, 6.1, '0.017646,0.050183,-0.522291,0.322206,-0.059000,-0.265633,0.737053,-0.182701,-0.703494,-0.483217,0.366208,0.569771,-0.049556,0.286647,0.083022,-0.125728,-0.010619,-0.494853,0.214156,-0.136530,-0.211044,-0.401834,-0.266235,0.130418,-0.083809,-0.276820,0.706704,0.162487,-0.096400,0.379398,0.218870,0.457416,-0.389438,0.286720,-0.141779,0.172940,-0.258776,0.258668,-0.475770,0.094285,-0.039267,-0.464699,-0.142849,-0.032784,-0.203902,0.611640,0.629576,-0.071267,0.014721,-0.284572,0.293612,-0.248896,-0.021016,0.030772,0.290971,0.038040,0.180798,0.365036,-0.145738,-0.215177,0.138697,-0.012216,-0.499835,0.093023,0.255803,0.170115,-0.635229,0.181211,-0.120822,0.011209,-0.031417,-0.339580,0.224577,0.277073,0.110114,0.293154,-0.494526,0.315035,-0.433363,0.258952,0.671124,-0.263573,0.169061,0.162800,-0.110252,-0.213763,0.341658,-0.259004,-0.379846,0.100723,0.205714,0.246733,-0.444658,0.361619,-0.247486,-0.131306,-0.376215,0.127951,0.308359,-0.541464,0.000894,-0.171363,-0.225639,-0.086646,-0.230371,0.112989,0.106222,-0.351756,0.338268,-0.695946,0.376040,0.262483,0.223300,-0.577382,0.405015,0.288117,0.143602,-0.340449,0.201095,0.661962,0.171207,-0.092708,-0.017346,-0.136073,-0.117613,0.037300,-0.406597,0.062291', '1293265', '25721544', '1301022', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25742242', '深夜前的五分钟', '爱情', '在上海某个里弄不起眼的角落里，为了学习机械表制作技术的日本青年阿良（三浦春马 饰）埋首工作。他在泳池偶然邂逅了美丽女子若蓝（刘诗诗 饰），应对方之邀，阿良帮对方选择了送给他人的礼物。以此为机缘，阿良得以结识若蓝及其双胞胎姐妹如玫（刘诗诗 饰）。与沉稳恬静的若蓝不同的是，身为知名模特的如玫落落大方，开朗洒脱。但在进一步的交往中阿良发现，若蓝对如玫抢走了许多她的东西抱有深深的怨恨，甚至连她最初喜欢的人天伦（张孝全 饰）如今也成为如玫的未婚夫。两个孤独的人儿敞开心扉，阿良和若蓝坠入爱河。谁知命运急转直下，如玫与若蓝相约前往毛里求斯做婚前的单身旅行，结果却发生了意外。姐妹俩只有一人回来，而她究竟是谁，没人能分得清楚……©豆瓣', '刘诗诗', '行定勋', 6.2, 22584, 'tt3793116', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2205357615.jpg', 9.8, 19.8, 36.7, 19.1, 14.6, '0.193423,0.204174,-0.452604,0.626322,-0.123461,-0.245454,0.799186,0.314886,-0.468323,-0.068629,-0.090591,0.538351,0.042676,0.125231,0.293314,0.374111,-0.220714,-0.655230,0.113833,-0.106061,-0.137891,-0.458191,-0.177832,-0.057728,0.119821,-0.209090,0.384237,0.145754,-0.164523,0.573693,0.484943,0.282690,-0.561662,0.488520,-0.060670,-0.393460,-0.212974,0.541126,-0.533441,0.181004,-0.214465,-0.048218,-0.122869,-0.069416,0.029079,0.350154,0.489104,-0.155952,-0.158465,-0.087144,0.269044,0.137802,0.223198,0.184927,-0.037577,-0.168234,0.410624,0.061724,-0.149565,0.180229,0.141598,-0.061400,-0.551581,0.175992,0.487986,-0.014314,-0.570439,0.564958,0.130321,0.197361,0.054123,-0.110839,-0.094924,0.158030,0.221550,0.240901,-0.075131,0.109474,-0.541299,0.009969,0.479678,0.209342,0.031186,0.508768,-0.022948,-0.522759,-0.110142,0.022310,-0.200640,0.211242,0.169218,0.044654,-0.037895,-0.173966,-0.345244,-0.031012,-0.080972,0.183240,0.138232,-0.523105,0.066064,-0.197810,0.079354,-0.525464,-0.617096,0.041002,0.145766,-0.418181,0.739119,-0.754808,0.194614,0.283064,-0.033192,-0.775178,0.497955,0.361369,-0.071485,-0.511811,-0.254649,0.401442,-0.031764,-0.086727,0.037668,0.203653,-0.116788,-0.038146,-0.341211,0.218881', '1418613', '1301022', '26730542', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25742299', '暴疯语', '悬疑', '失业在家的范国生（刘青云 饰）残忍地杀害了妻子（叶璇 饰），这件事震惊了全香港，而他随后被诊断为有精神疾病而逃脱了法律制裁。医学才俊周明杰（黄晓明 饰）主动承担为范国生的主治医生，极力帮助其治疗。三年后，周明杰力保范国生出院，重回社会，这遭到了医学界的一致反对，但是周却执意坚持。可是新的毒贩凶杀案又接踵而来，警方又再次把目标锁定为范国生，与此同时，周明杰的未婚妻宝儿（薛凯琪 饰）遭遇了死亡威胁，强大的压力让周明杰无法喘息。如何拯救爱人，拯救事业？真相到底是什么？精神病人究竟能否被治愈？新一轮的自我救赎悄然开始。©豆瓣', '刘青云', '李光耀', 5.9, 40250, 'tt4305562', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2304738889.jpg', 4.2, 20.8, 53.7, 17.1, 4.1, '-0.146282,0.162124,-0.402219,0.323124,-0.137773,-0.195243,0.292404,0.154955,-0.507224,-0.238585,0.137530,0.515653,0.006026,0.245382,-0.026206,-0.048375,-0.009156,-0.611100,0.098820,0.088519,-0.509470,-0.351404,-0.048760,-0.329430,0.062687,-0.119414,0.543225,0.301852,-0.213505,0.216928,0.531509,0.680819,-0.000625,0.616949,0.142786,0.059773,0.087670,0.043184,-0.239535,0.229622,0.390760,-0.652969,-0.004441,0.662174,-0.268886,0.417258,0.552761,0.017233,-0.236067,-0.264614,0.598765,-0.534690,0.064069,0.274468,0.094152,0.302251,-0.146257,0.229606,-0.259344,-0.115354,0.202571,0.098119,-0.860901,-0.145142,0.241681,0.014888,-0.561856,0.031371,-0.313559,-0.076324,-0.006602,0.027422,0.137093,0.681397,0.330131,0.359355,-0.363708,0.137749,-0.342463,0.181262,0.626889,-0.175428,-0.177752,0.196546,-0.277565,-0.578373,0.132125,-0.298414,-0.246911,0.027734,0.275009,0.429733,-0.225942,0.278884,-0.172058,-0.308966,-0.455436,-0.062818,-0.143529,-0.432712,0.104154,-0.186009,-0.198407,0.003961,-0.060609,-0.035929,0.117885,-0.355527,0.732343,-0.721136,0.064526,0.422944,0.316253,-0.822194,0.278351,0.176798,0.261271,-0.124587,0.023621,0.242226,-0.033356,0.425584,0.123227,0.001992,0.217218,-0.102267,-0.264712,0.176744', '26678784', '1877596', '30163500', '3811342');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25743807', '王牌', '剧情', '故事发生在二十世纪三十年代，共产党的秘密会议遭到了国民党的突袭，一大批地下党不幸遭到逮捕。地下党负责人王峰（梁家辉 饰）布置下了紧急任务，因为党内的重要任务“王牌”就在被逮捕的地下党中。敌人亦知道他们捕获了大鱼，但苦于无法甄别王牌究竟是谁，经过调查和研究，他们将目标缩小到了赵碧薇（林志玲 饰）、苏捷（钟欣桐 饰）、王霞芬（蒙亭宜 饰）、施老师（苏瑾 饰）和小红五人身上。为了从五人口中逼问中所谓的真相，敌方不惜动用了各种各样残酷的刑罚，企图从身体和心灵上使王牌崩溃。一个谎言掩盖着另一个谎言，究竟谁才是王牌？©豆瓣', '林志玲', '范建浍', 4.6, 8884, 'tt6419698', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2213350249.jpg', 24.9, 34.6, 27.9, 8.7, 3.9, '0.153370,0.027864,-0.530137,0.473710,-0.085619,0.328451,0.528484,-0.229183,-0.391031,-0.123239,0.401417,0.553325,-0.035257,-0.183991,0.085198,-0.292803,-0.147046,-0.802810,-0.103335,-0.355819,-0.498028,-0.547176,-0.565534,-0.057145,0.068131,-0.059358,0.464989,0.321800,-0.388200,-0.086217,0.495050,0.491305,-0.400989,0.113930,0.177856,-0.117105,0.338766,-0.180528,-0.056556,0.228427,-0.145829,-0.768317,-0.139274,0.382545,-0.150989,0.528340,0.754092,-0.395241,-0.024887,-0.161459,0.170222,-0.440184,-0.132047,0.264152,0.342225,0.208816,0.217653,0.390592,-0.128101,0.139131,0.093902,0.083878,-1.031667,-0.175535,0.221974,0.114937,-0.508612,0.149467,-0.331100,0.108022,0.026848,-0.273912,0.486986,0.568597,0.376353,0.119203,-0.136934,-0.077399,-0.498249,0.138519,0.383580,-0.247144,-0.238979,-0.000277,-0.118030,-0.347529,-0.115031,-0.370771,-0.000469,0.006343,0.391610,0.078685,-0.123945,0.024520,-0.587714,-0.182474,-0.395985,-0.187348,-0.286210,-0.149706,-0.050919,-0.443612,-0.264608,-0.260094,-0.315238,0.220414,0.140947,-0.201297,0.715712,-0.729982,0.089445,0.516355,0.233466,-0.541142,0.157700,0.262753,0.070185,-0.270608,0.072855,-0.038263,0.212358,0.329819,0.166424,0.283744,-0.094635,-0.355653,-0.288369,0.176154', '25774050', '26678784', '1308585', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25743833', '不能说的夏天', '剧情', '23岁的白白（郭采洁 饰）怀揣着纯洁而又热切的音乐梦想，只身一人远赴音乐学院深造，充满了自由和新鲜空气的大学校园让长久以来生活在压抑之中的白白第一次体会到了什么叫做真正的快乐。在学校里，白白遇见了英俊的学弟木宏（黄远 饰），两人意气相投，彼此之间距离越来越近。白白的单纯和可爱勾起了李教授（戴立忍 饰）对于自己岁月往事的回忆，受到欲望和占有欲的控制，李教授利用职务之便和年龄上的优势，将白白诱惑进了一段背德的师生恋情之中。恋情曝光后，社会、网络舆论如同排山倒海般席卷而来，涉世未深的白白该怎样负担这沉重的一切？©豆瓣', '徐若瑄 Vivian Hsu', '王维明', 6.9, 16326, 'tt4024410', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2206597790.jpg', 1.3, 7.5, 45.7, 35.8, 9.7, '0.374102,0.334054,-0.644491,0.629008,-0.055872,-0.189079,0.891831,0.161921,-0.537325,0.151999,-0.195787,0.550410,-0.269995,0.503505,0.226271,-0.145814,-0.022441,-0.728620,-0.058459,-0.288672,-0.067560,-0.239258,-0.402850,0.143797,-0.081063,-0.327526,0.743104,0.248170,-0.145489,0.730807,0.385511,0.211992,-0.202040,0.491827,-0.097891,-0.059593,0.016388,0.478412,-0.274342,-0.060432,0.274741,-0.243047,0.120603,0.125714,-0.253381,0.028256,0.850214,-0.180521,-0.350399,-0.001904,0.225769,-0.420780,-0.145957,0.242046,-0.092786,0.159388,0.092029,0.031421,-0.399137,0.193401,-0.060634,-0.201883,-0.505376,-0.184880,0.177872,0.155893,-0.431449,0.786026,0.194837,-0.279945,0.311277,0.043353,-0.129409,0.199578,0.211810,0.615754,-0.424602,0.025193,-0.265394,0.312456,0.720014,-0.178624,-0.526145,0.420464,-0.580291,-0.198279,-0.168602,-0.274947,-0.647344,-0.270570,0.196274,0.177210,-0.322851,0.322814,-0.743973,0.064144,-0.077714,0.047974,0.007338,-0.748513,0.001542,-0.465810,-0.385912,-0.640315,-0.145884,0.062457,0.170627,-0.461847,0.789357,-0.722644,0.124246,0.673127,0.213394,-0.355448,0.498434,0.034708,0.060887,0.060860,-0.004194,0.446513,-0.311799,0.334148,0.105297,0.423797,-0.362203,0.006504,-0.423320,0.724633', '4817024', '24839498', '2365260', '27062637');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25745494', '灵犬雪莉', '剧情', '改编自法国著名的童书，此前这部书就已经多次被拍成电视剧和电影。故事发生在二战期间的阿尔卑斯山脚下的小镇上，讲述了小男孩塞巴斯蒂安驯化灵犬雪莉的故事。这里位于法国和西班牙交界，大地被皑皑白雪，一切都那么宁静祥和，直到纳粹士兵的到来。在小镇上有一只叫 做雪莉的小白狗和叫做塞巴斯蒂安的小男孩，他们出生在同一天。这两个初生时互不相关的小生命，在无形命运的拉扯下，几年后被紧紧的连繫在一起，成了彼此相知并深深相惜的好伙伴。这是一次永恒友谊的历险，也是一个足智多谋而又令人感动孩子不平凡的故事。这是一个小男孩寻找母亲、一位老人追寻过往、一个抵抗战士寻找爱情、一位年轻女子寻觅奇遇、一个德国军官寻求宽恕的离奇旅程。这是灵犬雪莉与塞巴斯蒂安的生活..', '费利克斯·博叙埃', '尼古拉·瓦尼埃', 8.3, 16930, 'tt3146360', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2180821482.jpg', 0.2, 1.2, 16.9, 47.3, 34.5, '0.333035,-0.133896,-0.684933,0.713293,0.234349,-0.181806,1.008020,-0.064928,-0.414187,-0.170300,0.259388,0.987220,-0.221041,0.380553,0.261353,0.082537,-0.248393,-0.904039,-0.281180,-0.064411,-0.415915,-0.232736,-0.418861,0.082743,-0.130091,-0.323474,0.830111,0.211965,-0.208738,0.412691,0.085500,0.104126,-0.280052,0.326718,-0.595566,0.134711,0.180901,0.216802,-0.268286,0.106237,-0.169914,-0.236124,-0.077875,-0.087556,-0.316601,0.211911,0.769541,-0.411878,-0.158243,-0.211747,0.268720,-0.131219,-0.011196,0.020120,0.229614,-0.039978,0.364414,0.251174,-0.011325,-0.152813,0.043557,-0.320949,-0.655274,-0.008998,0.050796,0.387175,-0.580171,0.562545,0.268634,-0.051029,0.202680,-0.463340,0.292227,0.381964,0.286405,0.466814,-0.085995,-0.089643,-0.391839,0.422157,0.895899,-0.055923,-0.395600,0.500520,-0.338040,-0.393475,-0.105466,-0.099318,-0.709562,0.179787,0.325479,-0.045407,-0.313568,0.342036,-0.764696,0.280390,-0.100439,-0.232108,0.077966,-0.569658,-0.220556,-0.560749,-0.201218,-0.408554,-0.332597,0.254511,0.115792,-0.222288,0.974465,-0.568679,0.390831,0.580124,0.101428,-0.180694,0.800596,0.150377,0.163586,-0.139062,0.320505,0.501857,-0.037858,0.275785,0.068354,0.331200,-0.203393,0.315024,-0.614911,0.519275', '30162520', '26884422', '1307146', '1292001');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25745651', '妈咪', '剧情', '单亲妈妈戴安（安妮·杜尔瓦勒 Anne Dorval 饰）大大咧咧，抽烟喝酒满口脏话，有着一颗不服输的心。她独自抚养患有多动症、常做出暴力行为的儿子斯蒂夫（安托万-奥利弗·波尼安 Antoine-Olivier Pilon 饰），母子关系游走在爆炸的边缘。戴安担心斯蒂夫惹是生非，斯蒂夫迫切想表达对妈妈的爱。新邻居凯拉（苏珊娜·克莱蒙 Suzanne Clément 饰）适时出现，这位患有失语症的高中女教师充当了母子的缓冲阀，让三个人都开始看到平衡和希望。然而斯蒂夫以前暴力行为带来的后果正在发酵，戴安需要支付一大笔赔偿金。她决定出卖自己的幸福并且做出一个痛苦决定：将儿子送回医院接受治疗......《妈咪》是加拿大年轻导演泽维尔·多兰执导的第五部剧情长片，与多兰五年前在戛纳导演双周单元惊艳亮相的处女作《我杀了我妈妈》构成对照，同样讲述单亲家庭中狂躁而又深刻、依赖而又隔膜的母子关系。但不同于《我杀了我妈妈》的高度自传属性，《妈咪》更加宽厚和温暖，情绪更加饱满，几乎可以看作是多兰为自己处女作年少轻狂做出的一份愧意表达。本片入围第67届戛纳电影节主竞赛单元，与《再见语言》并列评审团奖。', '安娜·多尔瓦尔', '泽维尔·多兰', 8.2, 25840, 'tt3612616', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204888387.jpg', 0.5, 2.3, 17.5, 45.8, 33.9, '-0.153935,-0.178826,-0.408858,0.462503,-0.124536,-0.354664,0.559285,0.158880,-0.221727,-0.015643,0.115721,0.635191,-0.056586,0.307587,0.210335,-0.101469,-0.206799,-0.467678,0.171873,0.046394,0.040666,-0.536538,-0.105117,-0.236311,-0.014904,-0.450384,0.489068,-0.288189,-0.263191,0.395206,0.345529,0.286634,0.092963,0.163838,0.054282,-0.017078,-0.035947,0.018664,-0.443238,0.066676,0.202608,0.072907,0.029814,0.218863,0.210429,0.303441,0.569902,-0.118841,-0.229632,-0.091055,0.563552,-0.114118,-0.025785,0.045300,-0.100035,0.214677,0.325836,0.097045,-0.220859,0.169459,0.152777,-0.153142,-0.378179,0.061523,0.178511,0.073628,-0.486475,0.366192,-0.112979,-0.044565,0.347684,-0.181254,0.017912,0.154908,0.139288,0.384582,-0.288618,0.039557,-0.160864,0.048134,0.442950,-0.242059,-0.226990,0.213061,-0.385733,-0.248120,0.228416,-0.266613,-0.523414,0.150101,0.013568,-0.067842,-0.008546,0.265718,-0.218837,-0.148070,-0.087597,-0.120171,0.002092,-0.352794,0.199226,-0.480882,-0.181832,-0.129783,-0.165578,-0.124412,0.020600,-0.445481,0.666285,-0.573873,0.317775,0.223930,0.394105,-0.529626,0.505597,0.340602,-0.004497,-0.314750,0.026669,0.387949,-0.118787,-0.117951,-0.043922,0.164747,0.029217,0.217788,-0.273533,0.437109', '4847665', '1292720', '3445516', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25745752', '左耳', '剧情', '单纯美丽的李珥（陈都灵 饰）左耳失聪，无法听见声音，然而，生理上的缺陷并没有令她感到自卑，正相反，她的个性温顺又温柔。一次偶然中，李珥结识了名叫吧啦（马思纯 饰）的女孩，吧啦的个性和李珥截然相反，她无拘无束，桀骜不驯，向往自由的生活。在吧啦的身上，李珥看到了自己内心里叛 逆执着的一面。让李珥没有想到的是，吧啦竟然和自己一直暗恋的男生许弋（杨洋 饰）走到了一起，这让李珥开始体会到了青春的残酷。然而，吧啦的内心里其实喜欢着名为张漾（欧豪 饰）的男生，命运让他们的爱情成为了悲剧，并且最终夺走了吧啦年轻的生命，这场意外让几个懵懂的孩子们迅速蜕变成长，绽放出了最艳丽绝望的青春之花。©豆瓣', '陈都灵', '苏有朋', 5.7, 254474, 'tt4545806', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2238949728.jpg', 10.2, 24.8, 43.5, 15, 6.5, '0.390927,0.229851,-0.654470,0.687131,-0.464671,-0.284942,0.891653,0.226462,-0.332744,0.119404,-0.200777,0.417898,-0.171575,0.417060,0.231076,0.211244,-0.151532,-0.813455,-0.234035,-0.145529,-0.440505,-0.146253,-0.160309,-0.099184,-0.311079,-0.281644,0.674177,0.231891,0.024829,0.700725,0.389614,0.239572,0.158704,0.419142,-0.186473,-0.159971,-0.054419,0.369911,0.020579,0.063019,0.328121,-0.253055,0.024969,0.548932,-0.130871,0.202474,0.654265,-0.433558,-0.145023,-0.005689,0.502473,-0.062694,-0.135646,0.081915,-0.152359,-0.018591,0.243186,0.023669,-0.158163,0.021062,0.183967,0.036459,-0.825302,0.215080,0.085660,-0.023234,-0.438357,0.629157,0.133909,-0.387324,0.463559,-0.351876,0.370984,0.009703,0.421202,0.375172,-0.375154,0.058680,-0.170005,0.266366,0.761109,0.107884,-0.406809,0.499881,-0.413140,-0.360765,-0.029566,-0.285299,-0.555296,0.138766,0.072268,0.165697,-0.064261,0.196045,-0.687786,0.142843,0.164015,-0.010785,-0.217552,-0.509567,-0.007261,0.051393,-0.316795,-0.667921,-0.376437,0.120853,-0.147528,-0.296462,0.970403,-0.992869,0.254273,0.517571,0.249880,-0.480223,0.626416,0.320250,-0.133751,-0.061369,0.088194,0.391669,-0.302992,0.105247,0.186795,0.481681,-0.103612,-0.109576,-0.524297,0.765285', '35030151', '26283288', '5977789', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25746375', '我是路人甲', '剧情', '大学毕业后，怀揣着成为一名演员的梦想的万国鹏（万国鹏 饰）孤身一人背井离乡，远赴大名鼎鼎的浙江横店，希望能够在这里打拼出一片属于自己的天地。然而，现实远比想象之中要残酷得多，在这个弱肉强食的世界里，空有一份对于梦想的热情还远远不够，在经历了无数挫折和失败后，万国鹏总算混 出了点名堂，成为了一名专业的群众演员。在横店，万国鹏见到了无数和他极为相似的年轻人，他们中，有人最终获得了成功实现了梦想，有人误入歧途人生毁于一旦，但更多的，是经历了千辛万苦却放弃了梦想，回归了平淡的生活。一次偶然中，万国鹏结识了名为王婷（王婷 饰）的女孩，她仿佛一束光，照亮了万国鹏的前路。©豆瓣', '万国鹏', '尔冬升', 7.1, 142070, 'tt4786802', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2252471054.jpg', 1.9, 7, 38.5, 39.5, 13.1, '0.044356,0.559474,-0.931863,0.712536,-0.059697,-0.370660,0.535776,-0.186385,-0.495285,-0.117937,0.068183,0.910075,-0.202987,0.196159,0.316875,-0.182540,-0.077206,-0.714012,0.000875,-0.445493,-0.098510,-0.268807,-0.731667,0.225041,-0.531517,-0.091450,0.713624,0.534442,0.047542,0.454335,0.195604,0.154237,0.111073,0.396990,-0.454753,-0.018927,-0.006538,0.416263,-0.457112,0.095133,-0.030088,-0.567762,-0.277804,0.524237,-0.221532,0.045450,0.624854,-0.346847,-0.325446,-0.025165,0.364725,-0.244179,-0.523653,-0.100416,0.161549,0.031212,0.132341,0.146137,-0.057693,0.001326,-0.208094,-0.120883,-0.915609,-0.180898,0.142403,0.161278,-0.680703,0.502541,0.211311,-0.123896,-0.148193,-0.245048,0.060405,0.134937,0.178710,0.522552,-0.218220,0.211263,-0.651837,0.445440,1.052475,-0.214883,-0.362925,0.479519,-0.242367,-0.348744,-0.065118,-0.346187,-0.558897,0.097283,0.289638,-0.007856,-0.270281,0.111601,-0.694761,0.249581,-0.335600,0.003047,-0.056892,-0.174928,-0.173708,-0.445495,-0.161266,-0.508609,-0.311124,-0.065069,-0.092072,-0.593760,0.957026,-0.897466,0.148442,0.388517,0.467973,-0.348072,0.789894,-0.104863,0.333363,-0.014258,0.108055,0.014250,-0.317273,0.315438,0.132942,0.271847,-0.188277,-0.380484,-0.278748,0.655653', '1870682', '30162520', '25721544', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25746414', '暴走神探', '喜剧', '上海滩，十里洋场，租界林立，妖孽辈出，钱多人傻，浮华与罪恶并存，故名“冒险家乐园”，又名“魔都”。作为租界最聪明的一名“包打探”，范如一（阮经天 饰）每天都要跟三教九流打交道，从中获取各式各样的查案信息，也因此深得老板信任。可直到有一天，在接手老板交代的一项绝密任务之后，各种意想不到的离奇事件接踵而至：军阀之女宋小乔（杨子姗 饰）遭到绑架，少年小六惨死街头，贵族学校女学生、巡捕房同事等均被卷入其中且无一幸免，范如一试图阻止无辜者被杀，结果却连他自己也始料未及，所有凶案的“头号凶嫌”，竟然是他自己！为了洗刷罪名，范如一使尽浑身解数，既要躲避来自黑道、捕房和神秘杀手的多方追捕，更要保护报童小猴和风尘盲女慧兰（周冬雨 饰），舍得一身剐，终于慢慢接近真相，可真相却比他想象的残酷得多……©豆瓣', '阮经天', '罗卓瑶', 5.4, 15443, 'tt3976070', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2219749857.jpg', 14.8, 27.8, 37.2, 13.8, 6.5, '-0.081403,-0.126220,-0.421227,0.200725,-0.150579,-0.027596,0.357116,-0.040246,-0.438683,-0.314860,0.219127,0.648835,-0.128403,-0.128987,0.243978,-0.181578,-0.027848,-0.516233,-0.141713,-0.117399,-0.153220,-0.258246,-0.209162,-0.164267,-0.141173,-0.026283,0.255972,0.370788,-0.310947,0.221876,0.572670,0.245434,-0.372704,0.423266,-0.116667,-0.193830,0.236365,-0.076553,-0.066141,-0.062910,-0.166113,-0.449163,-0.222113,0.145147,-0.052573,0.150755,0.501235,-0.184441,-0.205266,-0.129832,0.399891,-0.420920,-0.122808,0.139304,0.269339,-0.175319,0.266443,0.336164,-0.102841,-0.103253,0.197504,0.104915,-0.883090,-0.123417,0.520541,-0.049050,-0.400935,-0.048346,0.072241,0.065999,-0.021561,-0.101170,0.208470,0.214290,0.230471,0.226455,0.133811,-0.000798,-0.429822,0.276540,0.609254,-0.048883,-0.004179,-0.001272,-0.007626,-0.390281,0.027501,-0.445758,-0.230207,0.138563,0.305970,-0.160528,-0.199080,0.361459,-0.405441,-0.212174,-0.208895,-0.082888,-0.095112,-0.242653,-0.141783,-0.365210,-0.167656,-0.205913,-0.186635,0.252612,0.397886,-0.056574,0.660621,-0.538121,0.119983,0.442272,-0.013764,-0.768790,0.299413,0.118997,0.144674,-0.059560,-0.179109,0.027255,0.669517,0.392555,-0.086537,0.193475,-0.085728,-0.486463,-0.103696,0.099711', '26678784', '30163500', '1302110', '1304382');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25747016', '惊天绑架团', '剧情', '本片根据真实案件改编。阿尔弗雷德·弗雷迪（安东尼·霍普金斯 Anthony Hopkins 饰）是世界著名啤酒巨头喜力啤酒的总裁，他因喜力啤酒而世界闻名。但是在1983年的三周里，他却因为另一事件闻名。因为在11月初，他遭到了绑架，并且和他的司机做了三个礼拜的人质。', '安东尼·霍普金斯', '丹尼尔·阿尔弗雷德森', 5.9, 4816, 'tt2917388', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2373853178.jpg', 4.2, 20.5, 56, 14.8, 4.5, '0.233156,0.246633,-0.724676,0.325831,-0.148089,-0.107283,0.962038,0.122409,-0.794831,-0.403845,0.222714,1.074596,-0.195528,0.079339,0.635354,0.074605,-0.101128,-0.702545,0.207720,-0.232226,-0.371527,-0.302912,-0.433074,-0.552806,0.031005,-0.174021,0.227236,-0.039599,-0.086166,0.215511,0.246003,0.106250,-0.084881,0.623047,0.154683,0.187487,0.441222,-0.359903,-0.279769,0.442839,0.161890,-0.520386,-0.269393,0.263504,0.104026,0.795070,0.436384,-0.336403,-0.071210,-0.127287,0.425755,-0.497774,-0.486867,-0.407333,0.492239,0.146891,0.214372,0.577970,-0.166609,-0.132811,0.179959,-0.190327,-0.713694,-0.097921,-0.120109,0.201498,-0.526071,0.951756,-0.617650,-0.121497,-0.035481,-0.023427,0.008050,0.071349,0.253173,0.430147,-0.014305,-0.173916,-0.637165,0.311718,0.480829,0.209036,0.039878,0.408113,-0.122918,-0.641558,-0.355858,-0.343615,-0.194644,0.202461,0.420584,-0.205927,-0.019879,0.469010,-0.784628,-0.039069,-0.342177,-0.321972,0.086247,0.000596,-0.358989,-0.359880,0.166176,-0.356049,-0.222837,-0.214078,0.078415,-0.067879,0.704927,-0.645483,-0.043309,0.633400,0.094561,-0.390623,0.839148,0.236835,0.006688,-0.298805,-0.063157,0.099155,-0.020966,0.069844,0.345280,0.621921,0.082237,-0.206151,-0.137174,0.346716', '30162520', '1292780', '1361252', '1422912');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25747028', '扑通扑通我的人生', '剧情', '大洙（姜东元 饰）曾经是一名前途无量的运动员，美娜（宋慧乔 饰）亦可能成为红极一时的偶像歌手，然而，一个意外降临的孩子让两个尚未成年的年青人毅然决定放弃未来和梦想，他们结为了夫妻，并且早早肩负上了为人父母的巨大责任与重担。然而，令两人没有想到的是，他们的孩子雅林竟然患上了罕见的先天性早衰症，乐观的大洙和善良的美娜并没有因此而放弃这个可怜的孩子，正相反，在两人的悉心照料下，亚雅林渐渐长大。一晃眼十七年过去，尽管生命中充满了病痛，但雅林依旧成为了一个开朗的，拥有8岁外貌的80岁“少年”。一次偶然中，大洙一家人的事迹被电视台制作成为了新闻报导，一下子将三人推到了舆论的风口浪尖。©豆瓣', '宋慧乔', '李在容', 7.2, 26539, 'tt3837820', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230880388.jpg', 0.7, 5.3, 40.1, 39.3, 14.7, '0.295067,0.039408,-0.717518,0.539925,-0.425180,-0.312546,0.835985,-0.033579,-0.712884,-0.259092,0.128731,1.176394,-0.112795,0.406756,0.278780,-0.191981,0.139254,-0.860903,-0.127408,-0.085211,-0.403761,-0.409779,-0.257726,-0.030853,-0.359711,-0.468288,0.944150,0.073295,0.037304,0.735574,0.406987,0.218192,0.092047,0.492435,-0.347361,0.036814,0.060343,0.177784,-0.116157,0.450963,-0.063270,-0.277358,0.013290,0.352791,-0.342321,0.302967,0.680984,-0.448391,-0.368696,-0.305770,0.539845,-0.313839,-0.272848,0.259719,0.380051,0.065514,0.219674,0.088793,-0.292019,-0.120988,0.172219,-0.179032,-0.847463,-0.085493,0.220663,-0.005988,-0.840633,0.648972,0.150625,-0.257388,0.083693,-0.233807,0.293802,0.320165,0.197683,0.606659,-0.366155,0.087965,-0.501797,0.189291,0.801053,0.130279,-0.589756,0.485372,-0.345169,-0.468465,-0.123299,-0.486954,-0.631052,0.236361,0.213113,0.207994,-0.258606,0.333470,-0.423593,0.073959,-0.311074,-0.100639,-0.019819,-0.502145,-0.117501,-0.149785,-0.155888,-0.468572,-0.387947,0.180619,0.046834,-0.418915,1.107973,-0.915847,0.305557,0.186744,0.163614,-0.582162,0.822638,0.035768,0.352364,-0.203516,-0.003030,0.218364,-0.214182,-0.009466,0.161879,0.245466,-0.411985,0.046021,-0.409641,0.477880', '30162520', '35030151', '1292720', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25747030', '慢放镜头', '剧情', '吕长富（车太贤 是）表面看来不过是一个普通的青年，却拥有着超强的“动态视力”，年幼时，因为这不同寻常之处，吕长富常常遭到周围人的欺负和非议，幼小的心灵受到了伤害，吕长富终日躲在家中，足不出户，依靠看电视剧度日。然而，屏幕背后的世界毕竟只是虚幻，终于，吕长富决心踏出家门，去看一看真正的社会是怎样一副模样。吕长富来到了韩国监控管制中心，却因为性格的原因在工作中四处碰壁，和同事们相处亦并不愉快。好在他结识了名为炳洙（吴达洙 饰）的博士，后者成为了他最坚实的后盾。凭借着自己的特殊能力，吕长富很快就得到了上司的重用，某日，在监视器中，吕长富见到了名为秀美（南相美 是）的少女，命运的车轮就此开始转动。©豆瓣', '车太贤', '金英卓', 6.7, 5978, 'tt3305060', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2196512978.jpg', 1.3, 11, 49.9, 28.2, 9.6, '0.251278,0.099176,-0.678990,0.537589,-0.309477,-0.026293,0.792427,0.214986,-0.649298,-0.291194,0.189719,0.774275,-0.171739,0.325499,-0.045282,-0.036994,-0.118663,-0.506828,-0.137934,-0.183448,-0.230603,-0.325926,-0.477935,-0.061561,-0.117254,-0.480954,0.764019,0.157351,-0.329471,0.308895,0.056585,0.188421,-0.019584,0.595135,-0.376633,-0.156893,-0.137238,0.045989,-0.061688,0.050252,0.077953,-0.453718,-0.163842,0.324975,-0.034761,0.333560,0.672595,-0.367389,-0.287679,-0.075199,0.369998,-0.139060,-0.033378,0.099476,0.344475,0.007474,0.269374,0.141802,-0.247495,0.271753,-0.049865,0.112928,-0.674189,-0.117080,0.329995,0.213127,-0.654168,0.495361,0.009414,-0.494381,0.002698,-0.172591,0.243092,0.216050,0.138784,0.501831,-0.209278,0.111381,-0.364172,-0.080728,0.552006,0.276653,-0.432272,0.613778,-0.241201,-0.436162,-0.107062,-0.365107,-0.412771,-0.175133,0.176420,0.165568,-0.223355,0.114770,-0.458657,0.344968,-0.014190,-0.079556,-0.163802,-0.651999,-0.087898,-0.669770,-0.246548,-0.643655,-0.416672,0.062457,-0.123321,-0.495712,0.755287,-0.976430,0.064668,0.485141,0.271632,-0.408995,0.915705,0.059758,0.014523,-0.063996,-0.054921,0.284302,0.129516,0.311600,-0.172171,0.202331,-0.033991,-0.293486,-0.331551,0.595313', '3230462', '3055049', '26280710', '26354526');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25747204', '长安道', '剧情', '为破获一起大型国宝失窃案，身为刑警的赵红雨（焦俊艳饰），为了调查亲生父亲万正纲（范伟饰）的现任妻子林白玉（陈数饰），在搭档邵宽城（宋洋饰）的掩护之下，到其身边卧底。就在案件得以水落石出之时，这批国家宝藏竟在警察的严密监控下不翼而飞，林白玉也突然失踪……身为历史学教授的万正纲遭到警察怀疑，作为女儿的赵红雨决心找父亲探询真相，却不料陷入一场更大的危机。是夫妻反目成仇引发的悲剧？还是父女冰释前嫌时突遇袭击？在邵宽城的调查下，随着真相浮出水面的，是一场真正关于人性的博弈……', '范伟', '李骏', 6, 48299, 'tt11203678', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2574145203.jpg', 2.7, 19.1, 55.2, 19.8, 3.2, '-0.058424,0.056495,-0.821684,0.433689,-0.032221,-0.264129,0.629855,0.026447,-0.800404,-0.406327,0.312098,0.388792,-0.236297,0.195628,0.318874,-0.387609,-0.238440,-0.985485,-0.329212,-0.121425,-0.316337,-0.578202,-0.401023,-0.264780,0.000295,-0.012093,0.468202,0.553910,-0.419365,0.097584,0.586993,0.589225,-0.603334,0.442816,0.065848,-0.100974,0.032748,0.219490,-0.740653,0.178292,0.225597,-0.288103,-0.067586,0.081294,-0.048170,0.351947,0.491861,-0.231953,-0.489162,-0.292712,0.285051,-0.534903,0.109833,-0.127422,0.839918,0.129890,0.008324,0.382458,-0.299605,-0.067619,0.347582,0.003990,-0.606371,-0.041614,0.292026,0.204057,-0.419045,-0.189534,-0.076703,0.101560,0.112320,-0.167498,0.465824,0.887327,0.403277,0.124805,-0.271348,0.227608,-0.364098,0.203924,0.803833,0.190027,0.266192,-0.133876,-0.027367,-0.409467,0.055366,-0.303220,-0.109383,0.043160,0.499165,0.027595,0.056869,0.480793,-0.193861,-0.397488,-0.409310,0.112098,0.045488,-0.451544,0.216968,-0.498336,-0.114837,-0.228937,-0.208695,0.317079,0.057855,-0.559839,0.353016,-0.592420,0.209683,0.379275,0.033981,-0.446598,0.200840,0.041212,0.141245,-0.440231,-0.037204,0.134080,0.342151,0.384534,-0.178629,-0.126727,0.104757,-0.226069,-0.337693,0.031714', '1298104', '25978126', '30347029', '10437779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25749813', '摇滚藏獒', '动画', '藏獒波弟（郭麒麟 配音）在山村长大，本该子承父业担当村庄卫士，却爱上了现代摇滚乐。为了追求音乐梦想，他进入城市，寻找乐队未果、拜师学艺受挫、屡遭狼群算计，但他坚持不懈，不仅拯救村民，还弥补了亲情上的裂痕，最终梦想成真。©豆瓣', '郭麒麟', '艾什·布兰农', 6.9, 10274, 'tt2822672', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2364347016.jpg', 2.8, 8.6, 42.8, 31.2, 14.6, '-0.220145,0.126003,-0.385693,0.475533,0.086247,-0.362725,0.482193,0.095525,-0.461967,-0.004741,0.099589,0.119853,0.105008,0.248803,-0.134562,-0.203616,-0.275448,-0.191137,0.423530,0.275660,0.003610,-0.066019,-0.365082,-0.388933,-0.347659,-0.141840,0.964514,0.614165,-0.198713,0.300594,0.015941,-0.426890,-0.167759,0.160628,-0.062301,0.197401,0.125789,0.224354,-0.091021,-0.192647,-0.460262,-0.596536,0.017162,0.170858,-0.149575,0.269548,0.638415,-0.081165,0.255591,-0.291511,0.162179,-0.300509,-0.038614,-0.062808,-0.038296,-0.238573,0.077470,0.090951,0.415670,-0.553299,-0.385630,-0.367265,-0.242415,-0.162713,0.266758,-0.051329,-0.550357,0.250045,0.080689,0.406691,-0.174541,-0.364203,-0.183886,-0.128214,0.416934,0.371642,-0.487006,0.270236,-0.387374,0.586874,0.833888,-0.352391,-0.132070,-0.050435,-0.538346,-0.607215,0.171172,-0.435445,-0.510267,-0.276044,0.145674,-0.149224,-0.253187,-0.133464,-0.557008,0.313934,-0.042081,-0.040021,0.146449,-0.267933,0.161090,-0.604028,-0.007363,0.062498,-0.168223,-0.117027,0.025888,-0.507416,0.773193,-0.756642,0.387810,0.845161,0.113502,-0.544236,0.726147,-0.156783,-0.078415,-0.220101,0.227097,0.780425,-0.129089,0.046758,-0.129247,-0.302639,-0.316385,0.119022,-0.261675,0.601815', '6772974', '2383207', '3667102', '30349667');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25750179', '沉睡的森林', '悬疑', '某日，高柳芭蕾舞团斋藤叶瑠子（木南晴夏 饰）被控杀害一名陌生男子而接受警方调查，搜查一课的加贺恭一郎（阿部宽 饰）受命协助石神井北署的太田刑警（柄本明 饰）追查真相。经过初步询问，警方认为这是因入室抢劫所引发的的正当防卫事件，但加贺却从中窥见诸多疑点。他先后走访剧团首席女演员高柳亚希子（音月桂 饰）、饰演黑天鹅的新人浅冈未绪（石原里美 饰）、饰演青鸟的男舞者柳生、剧团负责人梶田康成（平岳大），结果发现这群“擅长说谎”的舞者心中隐藏着错综复杂的关联和秘密。欲望当前，没有能永远隐藏的秘密……本片根据东野圭吾的同名原作改编，是“新参者”系列的SP作品。©豆瓣', '阿部宽', '土井裕泰', 7.5, 14513, 'tt3337228', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267639768.jpg', 0.3, 2, 35.6, 47.6, 14.5, '0.226019,-0.102715,-0.368542,0.467478,0.020978,0.324639,0.380789,-0.109394,-0.487866,-0.649322,0.366801,0.339127,-0.029208,0.021399,0.099651,0.019416,-0.323133,-0.550711,-0.088611,-0.243126,0.059892,-0.455628,-0.375189,-0.098669,-0.099722,-0.089028,0.953489,0.235181,-0.436884,0.405004,0.386567,0.611547,-0.409579,0.020849,0.210770,0.010757,0.386320,-0.079519,-0.095761,0.258979,-0.314750,-0.327286,-0.158821,0.060752,-0.143231,0.693551,0.572539,-0.263139,-0.218926,-0.044134,0.473309,-0.148720,0.026867,0.059888,0.418807,0.175947,0.058688,0.431578,-0.368011,-0.116303,-0.055505,0.052230,-0.738636,-0.127357,0.667606,0.571632,-0.204143,0.037001,-0.356437,-0.025722,0.180773,0.088948,0.075071,0.060326,0.595477,-0.015388,0.177999,0.146962,-0.100828,0.343545,0.373279,-0.160458,-0.060161,0.028272,-0.275113,-0.470966,-0.245031,-0.081991,-0.067836,0.124617,0.087606,0.055192,0.080288,-0.045285,-0.284700,-0.256973,-0.098241,0.132021,0.017237,-0.092329,0.081955,-0.896406,-0.163105,-0.196438,-0.214491,-0.141372,0.287008,-0.370396,0.592433,-0.678284,-0.000691,0.636123,-0.001553,-0.378894,0.388492,0.258185,-0.009690,-0.313486,-0.162894,-0.026817,0.330536,-0.002605,-0.212417,0.301655,0.135059,-0.556105,-0.372568,-0.313077', '2369613', '3266509', '25723905', '3861846');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25750969', '夜行者', '剧情', '路易斯（杰克·吉伦哈尔 Jake Gyllenhaal 饰）是个无所事事的小混混，整日干的尽是一些偷鸡摸狗的勾当。一次偶然中，他目睹了摄影记者工作的场面，从中觅得商机的他决定自己干上一票。路易斯购置了摄像装备，通过窃听警方无线电的方式抢先一步到达犯罪现场进行拍摄，再将摄像资料卖给晨间新闻制片人妮娜（蕾妮·罗素 Rene Russo 饰）换取酬劳。在尝到了几次甜头之后，路易斯招募了里克（里兹·阿迈德 Riz Ahmed 饰）作为搭档，准备“扩张”自己的事业。渐渐的，普通的车祸或火灾现场已经无法满足路易斯和妮娜的胃口，他们需要的是更血腥、更劲爆、更吸引眼球的新闻场面，为了得到珍贵的一手资料，路易斯甚至不惜“亲自动手”。©豆瓣', '杰克·吉伦哈尔', '丹·吉尔罗伊', 8.3, 164291, 'tt2872718', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2203693875.jpg', 0.2, 0.8, 13.4, 54.6, 31.1, '0.241143,0.037224,-0.397245,0.477412,-0.116846,-0.231316,0.450078,0.115246,-0.346808,-0.074326,0.174103,0.380089,-0.228490,-0.164737,0.101953,-0.129144,-0.611135,-0.745551,0.181203,-0.220897,-0.176797,-0.447576,-0.417037,-0.256085,-0.160557,-0.374883,0.358308,-0.070242,-0.125526,0.168058,0.380108,0.245789,0.317946,0.409462,0.089959,-0.134479,0.292667,-0.284736,-0.289547,0.342915,-0.028563,-0.358899,-0.099291,0.303477,0.231725,0.320233,0.673144,-0.003426,-0.168104,-0.097777,0.292677,-0.129384,0.311182,0.017775,-0.024964,0.118148,0.304640,-0.119004,-0.420512,0.178533,0.302563,-0.020804,-0.863918,-0.221566,-0.104362,0.193082,-0.515856,0.080498,-0.401070,0.169945,0.116280,-0.404835,0.121957,0.336325,0.296560,0.260389,0.005478,0.025951,-0.408350,0.389504,0.460307,-0.051363,0.209660,0.488340,-0.427393,-0.421399,0.135434,-0.245080,-0.250714,0.054504,0.697240,-0.196932,0.108362,0.372854,-0.630130,-0.181246,-0.195393,-0.510880,-0.005179,-0.143165,-0.012217,-1.076489,-0.266860,-0.115551,-0.133989,-0.005410,0.113350,-0.373032,0.607769,-0.378517,0.072007,0.741927,0.074173,-0.289931,0.382971,-0.179528,0.189762,-0.110391,-0.200306,-0.147171,0.218399,0.316671,0.246451,0.330794,0.326323,-0.497524,-0.282276,0.523333', '3318306', '4014397', '3003137', '26275494');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25751312', '特朗勃', '剧情', '好莱坞著名编剧达尔顿·特朗勃的传记片。特朗勃上世纪30年代进入好莱坞当编剧，奉献过《罗马假日》、《出埃及记》、《斯巴达克斯》、《约翰尼上战场》等经典作品。在荣誉背后，特朗勃的职业生涯实际上非常坎坷，他在40年代末遭到非美活动委员会(HUAC)的迫害，被米高梅于1950年解雇，并蹲了大牢。出狱后他被政府列进黑名单，一度无法工作，特朗勃就借用他人名字创作剧本。他曾凭借《罗马假日》与《勇敢的人》夺下两座最佳编剧的小金人，但当时剧本的作者署的都不是他的名字。直到1960年，特朗勃才走出迫害，他的编剧才华才得以重见天日。', '布莱恩·科兰斯顿', '杰伊·罗奇', 7.8, 12602, 'tt3203606', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2262419390.jpg', 0.4, 1.7, 26, 53.7, 18.2, '-0.087533,0.009737,-0.724316,0.574220,0.123536,-0.495105,0.384677,-0.045601,-0.629849,-0.259923,0.250685,0.766660,-0.291953,0.301151,0.455235,-0.087450,-0.400570,-0.861671,-0.202164,-0.273671,-0.182798,-0.313955,-0.415621,0.094456,-0.535590,-0.199515,0.902904,-0.034096,-0.458913,-0.053099,0.197159,0.084628,0.226014,0.224446,-0.209464,0.100642,0.323416,-0.097671,-0.395796,0.244886,-0.013302,-0.582350,-0.172339,0.096673,-0.025453,0.031495,0.449848,-0.287671,0.038187,-0.041169,0.545450,-0.280773,-0.209618,-0.096253,0.214180,0.108759,0.338082,0.650248,-0.053655,0.118174,-0.244474,-0.464636,-0.664194,-0.109366,0.015760,0.015139,-0.451545,0.548985,-0.346982,0.223544,-0.243216,-0.263956,0.035577,0.036114,0.475742,0.347002,-0.100182,0.190386,-0.242907,0.643177,0.434762,-0.081792,-0.411421,0.239207,-0.122701,-0.597958,-0.194603,-0.285311,-0.458755,0.177907,0.248380,-0.066987,-0.031982,0.114418,-0.510744,0.072635,-0.343616,-0.410341,0.129935,0.014598,0.049446,-0.588728,-0.345922,0.080082,-0.149342,-0.179044,0.144169,-0.253168,0.628398,-0.413909,0.443688,0.632484,0.298208,-0.294711,0.836339,0.145512,-0.026028,-0.044801,-0.014743,0.531110,0.045017,0.441286,-0.056332,0.049185,-0.015440,-0.551576,-0.256595,0.719499', '1299663', '1297368', '1302279', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25752261', '女间谍', '喜剧', '苏珊（梅丽莎·麦卡西 Melissa McCarthy 饰）是中情局专门协助处理危险任务却不为人知的后勤人员，她的搭档布莱德利（裘德·洛 Jude Law 饰）在一次行动中突然失踪，也波及另一位顶尖中情局特工瑞克（杰森·斯坦森 Jason Statham 饰 ）的安危。为了找出搭档的下落，拯救这个岌岌可危的世界，苏珊自愿充当卧底，混进史上最危险的军火商集团，试图查出事情的真相，并与蛇蝎美女头目（萝丝·拜恩 Rose Byrne 饰）斗智斗勇。然而在英勇救难的惊险过程中，苏珊发现事情远没有她想象的那么简单……', '梅丽莎·麦卡西', '保罗·费格', 7.5, 144006, 'tt3079380', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2254455238.jpg', 0.6, 3.5, 31.8, 46.6, 17.5, '0.169557,0.004649,-0.537086,0.478869,-0.055025,0.044738,0.705837,-0.184891,-0.481282,-0.672512,0.308365,0.560198,0.170845,-0.211796,0.318970,0.026122,-0.352640,-0.647270,0.068682,-0.206093,-0.496680,-0.624176,-0.529905,-0.646234,0.031414,-0.229906,0.607430,0.283390,-0.380288,0.354799,0.437149,0.519942,-0.437780,0.446988,0.104090,-0.369060,0.668197,0.150901,-0.391313,0.173689,-0.173088,-0.196236,-0.160021,0.403905,0.098034,0.487893,0.214604,-0.264785,-0.042484,0.090624,0.184386,-0.460818,0.222057,-0.312499,0.529853,-0.374230,-0.035320,0.134966,-0.070027,-0.028293,0.065363,-0.135386,-1.025517,-0.112305,0.395621,0.367187,-0.475024,0.029864,-0.283814,0.236328,0.328658,-0.111389,0.270698,0.469757,0.444878,0.028787,-0.033486,0.273655,-0.465103,0.178169,0.511784,0.029647,-0.061712,0.237852,-0.041489,-0.548479,-0.183954,-0.342038,-0.160607,0.168740,0.288607,-0.116730,-0.013933,0.494432,-0.358089,-0.148909,-0.358105,0.039830,-0.273973,-0.287138,0.018485,-0.649766,-0.003773,-0.114588,-0.294018,0.216257,-0.139895,-0.320860,0.501312,-0.616087,0.132333,0.854847,0.015064,-0.572001,0.456741,0.280330,0.344687,-0.550382,-0.355258,0.445081,0.288828,0.119035,-0.200995,0.135911,0.033546,-0.483654,-0.330072,-0.038464', '27009869', '1297689', '1793491', '1307442');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25753166', '等一个人咖啡', '喜剧', '大学新鲜人思萤（宋芸桦 饰），来到“等一个人”咖啡店打工，结识了咖啡冲调技术高超，任何客人点的特调咖啡都能做得到的超酷拉子——阿不思（赖雅妍 饰）、每天都看似无所事事的神秘美丽老板娘（周慧敏 饰），和她的暗恋对象－喜欢坐在固定座位，看似身边女友不断的泽于（张立昂 饰）。在大学里拥有许多离奇传说的学长阿拓（布鲁斯 饰）和一群好友到“等一个人”喝咖啡，却碰上抢走他前女友的拉子——阿不思，很有正义感的思萤看不惯阿拓被好友们嘲笑而大骂对方，而和阿拓结为好友。开朗的阿拓热血又真诚，为了完成去环游世界的梦想到处打工，因此不断的延毕而成为校园中的传奇老学长。也因为打工认识了看似黑道大哥但其实曾是电影导演的热炒店老板暴哥（李羅 饰），以及拥有一身惊人厨艺的洗衣店老板娘金刀婶（蓝心湄 饰）。深深被思萤的正义感电到的阿拓，常常介绍他那些有趣的好朋友给思萤认识，思萤的生活也因为有阿拓而变得多彩多姿。思萤一直暗恋着泽于而只是把阿拓当成无话不谈的好朋友，直到阿拓决定要离开台湾，出国去实现梦想时，思萤才明白——原来她所等的人不是泽于，而是阿拓……', '宋芸桦', '江金霖', 6.2, 52984, 'tt3974790', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2204562870.jpg', 7.6, 16.9, 42.3, 23.7, 9.6, '0.361692,-0.217575,-0.401347,0.463505,-0.309568,-0.301224,0.712110,0.099698,-0.421228,-0.353035,-0.064310,0.779793,-0.071052,0.466758,0.431712,-0.066545,0.015705,-0.574879,0.100859,-0.153079,-0.097744,-0.370585,-0.236149,-0.006083,-0.200931,-0.219295,0.329207,-0.146443,-0.018179,0.581874,0.292201,0.128388,0.074060,0.428198,-0.332055,-0.087355,0.026407,0.155456,-0.210485,0.101642,-0.033169,-0.027150,-0.069111,0.089075,0.185416,0.089085,0.465778,0.055432,-0.239770,0.107395,0.384106,-0.294542,-0.007479,-0.092254,0.177243,0.141552,0.376977,0.036926,-0.065054,0.012462,0.069190,-0.181864,-0.619118,0.116100,0.242382,-0.034585,-0.488571,0.513194,0.105776,-0.262181,0.174299,-0.359498,0.258949,0.058441,0.247633,0.364362,-0.088682,0.195921,-0.441197,0.338523,0.712925,0.074539,0.038614,0.505739,-0.095380,-0.095869,0.175853,-0.110877,-0.477953,0.125248,-0.157317,-0.010045,-0.090685,-0.058668,-0.690819,0.021763,0.123704,0.051766,0.234617,-0.544417,-0.157937,-0.542527,-0.224801,-0.462327,-0.172438,0.083678,0.062573,-0.328277,0.807503,-0.948561,0.116429,0.428150,0.240731,-0.610166,0.726525,0.151454,-0.197446,-0.164816,-0.283403,0.197964,0.223903,-0.0