INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25753326', '巴霍巴利王：开端', '剧情', '故事发生在一个名为摩喜施末底的王国之中，激烈的王位争夺之战正在巴霍巴利（帕拉巴斯 Prabhas 饰）和巴哈拉拉德瓦（拉纳·达格巴帝 Rana Daggubati 饰）之间如火如荼的展开着。巴霍巴利为人正直而勇敢，坚信要凭借自己的真正实力夺得王位，而巴哈拉拉德瓦却恰恰相反，为了得到想要的东西，阴险狡猾的他愿意不择手段。最终，代表着正义的巴霍巴利成为了国王，然而，巴哈拉拉德瓦却实行了暗杀行动，谋权篡位。巴霍巴利的儿子流落民间，被善良的人家收养取名为希瓦（帕拉巴斯 Prabhas 饰）。成人之后，希瓦得知了自己的身世，得知了自己体内流淌着皇家的血脉，他决定推翻统治者的暴政，夺回属于他的王位。©豆瓣', '帕拉巴斯', 'S·S·拉贾穆里', 7.5, 54693, 'tt2631186', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363089554.jpg', 1.5, 5.1, 29.9, 43.1, 20.4, '0.163059,0.584282,-0.688195,0.982306,-0.111311,-0.224476,0.446804,0.371394,-0.406394,-0.316363,0.044127,0.689847,0.296586,-0.230074,0.381446,0.377473,-0.346134,-0.781873,0.036938,0.087360,0.111138,-0.517298,-0.560481,-0.204844,-0.320062,-0.706976,0.444336,-0.126787,-0.064494,0.234489,0.776019,0.453820,0.067379,0.121239,0.052861,-0.081211,0.094989,-0.185871,-0.362171,0.287385,-0.081202,0.064614,-0.262473,0.376219,0.088558,0.445435,0.419683,-0.733698,0.455292,-0.318331,0.422222,-0.573938,0.072279,0.358157,0.348584,0.093203,-0.112990,0.447996,0.001135,-0.285889,0.411611,-0.110049,-0.924298,-0.096546,0.252199,0.339561,-0.525267,0.406575,-0.320420,-0.150859,0.324120,-0.300925,0.113894,0.799643,0.281822,0.218255,-0.266848,-0.287792,-0.825081,-0.003423,0.595130,-0.145875,-0.186333,-0.156086,-0.102610,-0.399583,0.098434,-0.514997,-0.495281,-0.426558,0.435294,0.134594,0.002069,0.718193,-0.596638,-0.301795,-0.593671,-0.225282,0.336126,-0.390220,0.077505,-0.196483,-0.402393,-0.125412,-0.238997,-0.097071,-0.122574,-0.542676,0.602580,-0.818037,0.230889,0.660155,0.445728,-0.368833,0.370322,0.354793,0.144704,0.038555,-0.271699,0.475269,0.143590,0.046557,-0.007717,0.204281,-0.041440,-0.468659,-0.312041,0.917638', '6972849', '1811755', '1295120', '1792917');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25755599', '小楼的奇幻生活', '喜剧', '法国儿童题材喜剧，根据畅销漫画改编，心地善良且富于幻想的12岁少女露，从小和天真烂漫的妈妈相依为命，在她缤纷的生活中有两项重要任务，一是每天偷偷观察对面男孩的一举一动、记录他的生活点滴；二是帮她宅到无可救药的妈妈找到人生新目标。一天，当一位潇洒不羁的音乐家搬进了她们的公寓大楼，不仅惊动了这对母女单纯平静的生活，也让露渐渐走出幻想的泡泡、踏入更辽阔精采的世界。', '洛拉·拉塞隆', '朱利安·内尔', 8.1, 12371, 'tt3202098', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2204912531.jpg', 0.3, 2, 20.7, 46.9, 30.1, '0.095476,-0.060910,-0.493839,0.409798,-0.347998,-0.170100,0.648467,0.069886,-0.309980,-0.152449,0.219895,0.662118,0.032514,0.306846,0.484454,-0.178193,-0.356968,-0.441173,-0.146437,-0.096927,-0.072243,-0.122902,-0.222499,-0.186914,0.008338,-0.437487,0.688099,0.129502,-0.032059,0.324639,-0.114340,0.011296,-0.383539,0.056070,-0.352798,-0.036254,0.104984,0.260976,-0.264471,0.175885,-0.151745,-0.134902,-0.065422,-0.129612,-0.045162,0.186944,0.939725,-0.112857,-0.476827,0.165941,0.645485,-0.063724,-0.390709,-0.035359,0.209803,-0.081099,0.267679,0.076912,-0.143916,0.046502,-0.380038,-0.444005,-0.661635,-0.134542,0.446080,0.049759,-0.338370,0.471224,0.098918,-0.249153,0.238565,-0.083463,0.212296,0.244134,0.027432,0.626563,-0.117834,0.439529,-0.292229,0.409376,0.210292,-0.092531,-0.220219,0.597006,-0.339433,-0.059815,0.132589,-0.354631,-0.549226,0.098794,0.104848,-0.078889,-0.321519,0.047154,-0.670925,0.233828,0.064022,-0.395329,0.318008,-0.496097,-0.252794,-0.663071,-0.159269,-0.395752,-0.158324,0.098103,-0.014805,-0.496024,0.903206,-0.627247,0.216386,0.154027,0.220553,-0.500666,0.886427,-0.024939,0.182531,-0.402098,-0.034159,0.722613,-0.151926,0.267981,-0.301989,0.487234,-0.180511,-0.073660,-0.732675,0.590179', '3811356', '2027945', '5416009', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25755608', '新女友', '剧情', '克莱儿(阿奈丝·德穆斯捷 Anaïs Demoustier 饰)与罗拉（伊希尔·勒·贝斯柯 Isild Le Besco 饰）从7岁起就是要好朋友，这对闺蜜分享成长过程中所有的甜酸苦痛，然而罗拉在生完女 儿露西后就因病逝世，留下哀伤的丈夫戴维(罗曼·杜里斯 Romain Duris 饰)独自抚养女儿。身为教母的克莱儿决心遵守对罗拉的承诺，好好照顾戴维和露西，但自己却陷在好友离去的阴影中，难以平复。某日她鼓起勇气去探望戴维，却惊见对方戴上假发、一身女装，浓妆艳抹的给婴儿喂奶。原来戴维一直都有变装癖好——克莱儿从开始发现时的震撼，转变为协助隐瞒，甚至鼓励对方穿上女装和她外出购物，这让她隐约找回了罗拉相处时的姐妹情谊。然而为了维持这段特殊关系，克莱儿需要对自己的丈夫吉尔（拉斐尔·佩尔索纳 Raphaël Personnaz 饰）不断撒谎，终于陷入由友情、爱情、偷情交织的欲望迷宫无法自拔…...本片是法国鬼才导演弗朗索瓦·欧容的最新作品，改编自同名畅销犯罪小说。', '罗曼·杜里斯', '弗朗索瓦·欧容', 7.5, 16789, 'tt3184934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199678535.jpg', 0.5, 2.5, 31.7, 50.1, 15.2, '0.025143,0.022124,-0.524175,0.494846,-0.034293,-0.572913,0.626390,0.118835,-0.403998,-0.388976,0.077860,0.500151,-0.352647,0.191641,0.330847,0.223164,-0.792123,-0.653959,0.101542,-0.041287,-0.238737,-0.401018,-0.143430,-0.237031,-0.142045,-0.438126,0.493273,-0.115962,-0.187508,0.362434,0.511918,0.458188,-0.085164,0.406646,0.099084,0.015159,0.009689,-0.096276,-0.322935,0.089604,0.192976,0.052769,0.038770,0.205804,0.145450,0.349870,0.652935,-0.189818,0.143410,0.064723,0.353124,0.019821,0.193340,0.160620,-0.245369,-0.003097,0.060452,0.010233,-0.306665,-0.088989,-0.033021,-0.168455,-0.515674,-0.027365,0.238053,0.148676,-0.592207,0.321174,-0.206401,-0.057017,0.323170,-0.131843,-0.071261,0.356311,0.318505,0.373199,-0.150568,0.142549,-0.289579,0.150318,0.310399,-0.119600,0.007034,0.378940,-0.482855,-0.336616,0.071678,0.100139,-0.444451,-0.141238,0.152906,0.139306,0.064430,0.269933,-0.457557,-0.379559,-0.308424,0.038057,0.132628,-0.429274,-0.024298,-0.552343,-0.258523,-0.491573,-0.270879,-0.067930,0.140521,-0.385623,0.517631,-0.540406,0.352166,0.386167,0.289701,-0.310742,0.643930,0.180732,0.174737,-0.356756,-0.106948,0.653153,-0.012931,-0.175266,0.234004,0.212759,0.10326