INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25755645', '老男孩猛龙过江', '剧情', '本片讲述了倒插门被媳妇全家嫌弃的王小帅（王太利 饰）面临生活困境，决心放下一切实现梦想，于是他找到了老同学肖大宝（肖央 饰）。曾经因为拉大提琴的女孩马璐（屈菁菁 饰）而分道扬镳的两人又聚在了一起，决定前往美国勇闯选秀节目。两兄弟千辛万苦来到纽约，却阴差阳错卷入了黑帮斗争事件。虽然他们只想取得好名次，但是却引发了一系列爆笑事件，更让他们摸不着头脑的是两位来自朝鲜的神秘杀手竟然也和此行有关。万般无奈之下两个“老男孩”决定这次把大的！能不能成功逆袭，会不会惨死他乡就看最后决赛！《老男孩猛龙过江》是5年前爆红的微电影《老男孩》的大电影延续。©豆瓣', '肖央', '肖央', 5.7, 129847, 'tt3872008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2189861035.jpg', 8.1, 24.4, 46, 15.3, 6.2, '-0.058529,-0.069430,-0.599156,0.322777,0.047784,-0.420928,0.431982,0.227776,-0.505413,-0.046981,0.224608,0.813545,-0.346486,0.342023,0.114050,-0.172174,-0.217765,-0.767629,-0.016217,-0.032737,-0.198746,-0.297437,-0.053585,-0.122617,-0.093348,0.122869,0.676520,0.110300,-0.325266,0.332292,0.683394,0.086199,-0.185218,0.333697,-0.270078,0.098947,0.021124,0.073064,-0.474744,0.161092,0.119343,-0.153905,-0.316778,0.128450,0.232864,0.163038,0.527007,-0.107378,-0.159895,-0.014728,0.216802,-0.513848,-0.400585,0.107177,0.256759,0.062951,0.232930,0.207037,-0.061060,-0.232295,0.033760,-0.106727,-0.515756,0.387255,0.166940,0.018388,-0.616024,0.150279,0.286655,-0.023244,0.071503,-0.289207,0.162277,0.497680,0.633005,0.250297,-0.123548,0.071427,-0.352621,0.322461,0.847027,-0.227175,0.104050,0.330954,0.052531,-0.412059,-0.107592,-0.313913,-0.385988,0.406761,0.442992,-0.030248,-0.162712,0.342109,-0.442622,-0.270381,-0.413719,-0.132843,0.091998,-0.454240,0.111312,-0.435640,-0.267858,-0.144640,-0.195660,0.259501,0.095267,-0.318147,0.850090,-0.633873,0.002408,0.500405,0.295568,-0.632049,0.465185,0.306450,0.153393,-0.258511,0.167638,0.003572,-0.282497,0.139642,0.257328,0.193203,-0.156368,-0.321157,-0.226770,0.213464', '4301278', '30162520', '1316525', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25756355', '特工艾米拉', '动作', '女特工艾米拉在执行一项任务时受挫被停职，回家之后又发现家里突遇变故，爸爸被杀妈妈被绑。为了追查线索救出妈妈，艾米拉和男友杰森开始到处追查线索，但 却处处遭遇莫名杀手，陷入重重危机。在他们终于以为有了线索的时候，却不知道他们其实已经陷入了一场更为恐惧的生化危机……', '许绍洋', '徐宏辉', 3, 9216, 'tt3717186', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2175238497.jpg', 71.7, 17.3, 5, 2, 4, '0.079993,-0.124954,-0.876609,0.220047,0.177131,-0.563778,0.757672,-0.066035,-0.622014,-0.713611,0.079683,0.485583,-0.268738,-0.086814,0.191605,-0.162972,-0.803574,-0.633155,0.510191,-0.357945,-0.394382,-0.356292,-0.015855,-0.244327,0.266040,-0.232637,0.511954,0.452652,-0.336509,0.418270,0.198161,0.587132,-0.064216,1.113527,0.139743,0.079738,0.324808,-0.056637,-0.168228,0.259760,0.581963,-0.452886,-0.259170,0.404740,-0.021855,0.434981,0.655360,-0.132815,-0.410902,-0.025804,0.174742,-0.495043,0.045414,0.109384,0.698189,-0.170200,0.058393,0.009421,-0.322489,-0.093696,0.440449,0.043170,-0.720931,0.080995,0.246651,0.380454,-0.339547,-0.098670,-0.300309,0.484951,0.068882,-0.434818,0.529818,0.664807,0.622197,0.248800,-0.219786,-0.089653,-0.702301,-0.406059,0.889573,-0.549880,0.338990,0.082424,-0.049521,-0.504593,0.229572,0.097083,-0.185684,0.302429,0.464935,0.125388,-0.732274,0.459074,-0.347643,-0.080449,-0.320313,-0.377031,-0.767974,-0.575933,-0.195201,-0.227956,-0.306116,0.307923,-0.238224,0.197040,-0.241247,-0.219004,0.237955,-0.836914,0.695565,0.540618,0.227139,-0.560610,0.380109,0.301504,0.070599,-0.467779,0.173049,0.053774,0.089514,0.476422,0.595303,-0.145250,-0.130692,-0.212468,-0.165109,0.279321', '1292064', '25870679', '35073886', '25789402');
