INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25757186', '伦敦陷落', '动作', '班宁（杰拉德·巴特勒 Gerard Butler 饰）是美国特勤局的特工，最近，他接到了一个重要的任务，那就是联手局长琳（安吉拉·贝塞特 Angela Bassett 饰），护送总统本杰明（艾伦·艾克哈特 Aaron Eckhart 饰）前往伦敦圣保罗教堂，参加英国首相的葬礼。英国首相死得蹊跷，班宁和琳知道，他们的行程一定受到了不法分子的密切关注，与此同时，在葬礼上，各国首脑均有出席，伦敦这座繁华靓丽的城市霎时间成为了世界关注的焦点。果不其然，刺客们潜伏在暗处等待着时机，国家领导人屡屡遭到伏击，伦敦地标建筑亦不能幸免于难，整座城市陷入了混乱和瘫痪之中。而对于班宁来说，最要紧的任务，便是护送总统，回到国内。©豆瓣', '杰拉德·巴特勒', '巴巴克·纳加非', 6.3, 100650, 'tt3300542', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2325735117.jpg', 2.8, 14.6, 54, 22.2, 6.4, '0.223838,0.088597,-1.003154,0.418200,0.289588,0.182406,0.312718,0.230502,-0.600301,-0.290883,0.446165,0.755858,-0.044517,-0.008250,0.685785,-0.093766,-0.585195,-0.611125,-0.133827,-0.379104,-0.356521,-0.677936,-0.218450,-0.492305,0.120612,-0.265878,0.508828,0.444860,0.006730,0.415486,0.335182,0.566199,-0.172027,0.326919,0.050828,-0.435681,0.550235,-0.392832,-0.434057,0.306798,-0.223036,-0.106914,0.012516,0.219884,0.312144,0.266918,0.452423,-0.245621,-0.088017,-0.198891,0.125812,-0.501564,0.055472,-0.014558,0.715266,-0.172163,0.138179,0.313884,-0.297812,0.017340,-0.015091,-0.257635,-0.435417,0.215487,0.421712,0.398756,-0.222579,0.465723,-0.166466,-0.049418,-0.218547,-0.188133,0.676611,0.584054,0.121187,0.053128,0.332283,0.327779,-0.205871,-0.144502,0.719436,-0.048441,-0.172997,-0.389342,-0.208760,-0.316600,0.019217,-0.395748,-0.248706,0.096777,0.225507,-0.246558,0.277188,0.259911,-0.351045,-0.006180,-0.387294,-0.557723,-0.051373,-0.238668,-0.003223,-1.082520,0.118308,-0.107218,-0.086710,0.251691,0.042865,0.122160,0.575043,-0.703487,0.270626,0.660679,0.372712,-0.500545,0.633549,-0.043428,0.526939,-0.366715,-0.211871,0.300694,0.204363,0.397454,-0.337502,-0.014543,-0.166412,-0.595507,-0.309149,0.089009', '3871833', '1297715', '25833539', '3036464');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25757187', '我不是王毛', '喜剧', '少林寺学武归来的狗剩（王大治 饰）暗恋青梅竹马的杏儿（葛晓凤 饰），但穷二代 的他遭到岳丈（罗京民 饰）嫌弃。一没家产继承，二没手艺创业的狗剩只能顶替兄弟从军，以舍身卖命的方式赚取军饷，攒钱提亲。但在从军过程中不仅被同村情敌杨三（郭金杰 饰）设计陷害，还遇到许多离奇波折……', '王大治', '赵小溪', 8, 64986, 'tt5606614', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2316504999.jpg', 0.6, 1.9, 19.7, 52.5, 25.4, '-0.094624,-0.405581,-0.530380,0.375373,-0.402592,-0.644065,0.149086,0.097225,-0.354382,-0.557621,0.083339,0.481498,0.303077,-0.026707,-0.109773,-0.565046,0.488671,-0.028161,0.148256,0.116492,0.042864,-0.333799,-0.142338,-0.077505,-0.349915,-0.193399,0.421664,0.094490,-0.098724,0.430825,0.260132,-0.032450,0.134529,-0.164057,-0.379512,0.366216,0.021251,0.512043,-0.255826,-0.138194,-0.351371,-0.120681,0.008685,-0.280910,0.233538,0.296981,0.516630,-0.129589,0.194397,-0.323871,0.221791,0.085785,-0.127963,0.290083,0.212625,0.177562,0.567970,0.204697,-0.001521,-0.316780,0.135383,-0.108171,-0.809172,-0.120867,0.209598,-0.198302,-0.678289,0.195621,-0.129173,0.043598,-0.025621,-0.409144,0.016044,0.229812,0.373015,0.397286,-0.211580,0.205547,-0.719709,0.568265,0.634016,-0.327244,-0.046581,0.106492,0.000267,-0.040947,0.825252,-0.788942,-0.365710,0.097956,0.350773,-0.256876,-0.174664,0.141371,-0.206857,-0.123344,-0.056681,0.023019,0.387343,-0.050283,-0.231929,-0.233725,-0.104658,-0.386861,-0.340158,0.309679,0.321835,-0.575182,0.370582,-0.640988,0.005210,0.122444,0.331103,-1.037782,0.720340,0.122499,0.094828,0.213662,-0.206757,-0.200331,0.168887,-0.210136,0.399826,-0.179298,-0.300292,-0.478301,-0.196635,0.100596', '1877596', '1302110', '1302874', '1421278');
