INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25760247', '鼠来宝4：萌在囧途', '喜剧', '艾文（贾斯汀·朗 Justin Long 配音）、喜多（杰西·麦卡尼 Jesse McCartney 配音）和塞门（马修·格雷·古柏勒 Matthew Gray Gubler 饰）是三只可爱的花栗鼠，它们一个拥有古灵精怪的头脑，一个拥有强壮坚实的体魄，一个拥有高超过人的智慧，感情十分要好的三人是亲密无间的好拍档。大卫（杰森·李 Jason Lee 饰）是三只小鼠的主人，近日里，他打算驱车前往迈阿密，那里居住着他深爱的女友，他要向她展开浪漫的求婚。然而，三只花栗鼠误会了主人的意思，以为艾文即将抛弃它们，不仅如此，它们还获悉，大卫的女友的儿子，是一个残暴的“恶魔”！为了阻挠大卫的求婚之旅，三只花栗鼠想出了一个天衣无缝的计划。©豆瓣', '贾斯汀·朗', '沃尔特·拜克', 7.2, 20048, 'tt2974918', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2305715574.jpg', 1.3, 6.1, 40.1, 36.3, 16.2, '0.225825,0.014440,-0.720767,0.851929,-0.360231,-0.241514,0.956560,0.076712,-0.162236,-0.183480,0.260978,0.623067,-0.019002,0.224243,0.188117,0.255979,0.112116,-0.366584,-0.102485,0.162756,-0.041401,-0.466906,-0.533685,-0.272899,0.062850,-0.272904,0.478145,-0.236710,-0.109187,0.315239,0.490653,0.052182,0.053055,0.268949,-0.192568,0.103976,0.069855,-0.093070,-0.086831,0.339486,-0.017191,0.288890,0.020424,0.234865,-0.296064,0.247464,0.655649,-0.210571,-0.230462,-0.371794,0.307488,-0.271118,0.183089,0.401854,0.346458,-0.239984,0.099722,-0.185630,-0.041289,0.115121,0.262813,-0.061333,-1.026074,-0.116381,0.052042,0.193552,-0.573688,0.245187,-0.181481,0.090927,0.268020,-0.640586,-0.140766,0.262784,0.154217,0.301435,0.122206,0.193201,-0.561461,0.024428,0.654848,0.046100,-0.352789,0.185020,-0.262417,-0.620962,-0.116425,-0.021731,-0.687273,-0.103213,0.477280,-0.167909,-0.079606,-0.065580,-0.663572,-0.140963,-0.287434,0.023204,-0.143415,-0.488559,0.188091,-0.407961,0.032012,-0.646137,-0.285417,-0.007748,-0.093333,-0.419349,0.715365,-0.705925,0.109518,0.672108,0.281732,-0.329462,0.554948,0.081498,0.030602,-0.225067,0.094508,0.179076,0.056286,-0.198466,0.161776,0.523910,0.276043,-0.088355,-0.595424,0.611353', '1308784', '3785918', '1793491', '3005387');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25760447', '正义联盟：战争', '动作', '高谭市接二连三发生绑架案，嫌疑人都指向了蝙蝠侠。蝙蝠侠（杰森·奥玛拉 Jason O''Mara 配音）和绿灯侠（贾斯汀·柯克 Justin Kirk 配音）分头找到真凶的线索，对方留下一个神秘仪器后自爆。为了解开仪器的秘密，二人出发寻找超人（艾伦·图代克 Alan Tudyk 配音）希望弄清真相。当他们正逼近事实时，仪器突然启动，原来这是某个外星入侵者设置的时空通道装置，大批外星人通过它开始侵略地球。与此同时，斯通博士也就神秘仪器展开调查，斯通博士的儿子维克（谢默·摩尔 Shemar Moore 配音）意外被仪器感染，死而复生化身拥有强大实力的超级战士。史无前例的危机，蝙蝠侠、超人、绿灯侠、闪电侠（克里斯托弗·高哈姆 Christopher Gorham 配音）、黛安娜（米歇尔·莫娜汉 Michelle Monaghan 配音）相继卷入战斗……©豆瓣', '西恩·奥斯汀', '杰伊·欧力瓦', 8.1, 13517, 'tt3060952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2169725723.jpg', 0.3, 1.4, 19.7, 49.8, 28.8, '0.056724,0.001245,-0.400483,0.388268,0.141296,0.144667,0.609510,-0.330606,-0.013758,-0.496309,0.327494,0.419569,-0.214465,-0.084153,0.191369,0.016982,-0.719110,-0.393880,0.265999,-0.049331,-0.450758,-0.602541,-0.503312,-0.409831,0.413829,-0.423938,0.427413,-0.096760,-0.374021,0.033810,0.142694,0.237487,-0.642588,0.282950,0.174029,0.062424,0.482707,-0.380622,-0.208246,0.232008,-0.180005,0.208821,0.187441,0.235335,-0.209972,0.217134,0.547380,-0.390699,0.015664,-0.148197,0.165099,-0.186131,0.124344,-0.165595,0.282630,0.063980,-0.047435,0.025600,0.283910,-0.095709,-0.110950,0.099742,-0.749904,-0.015928,-0.063000,0.181830,0.202775,-0.426971,-0.522137,0.199031,0.190338,-0.281299,0.132809,0.203685,0.747377,0.157151,-0.025695,0.186015,-0.328152,-0.129833,0.181451,-0.155104,-0.636510,0.169195,0.159873,-0.455706,-0.182025,0.217937,-0.105649,0.106437,0.739627,0.150316,0.091610,0.485134,-0.408842,-0.134617,-0.399646,-0.040676,-0.114892,0.004482,-0.091593,-0.928976,-0.071569,0.344201,0.101263,-0.032958,-0.311430,-0.332202,0.514751,-0.338488,0.295902,0.687448,0.079892,-0.292212,0.342217,-0.387321,0.062095,-0.684971,-0.039176,0.320698,0.268811,0.466659,0.018814,0.135835,0.101196,-0.310732,-0.130934,0.174852', '4014397', '2364001', '6517421', '1293572');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25760615', '回溯迷踪', '剧情', '故事发生在1990年，美国一名汽车修理工约翰·格雷（大卫·丹席克 David Dencik 饰）因涉嫌猥亵自己的女儿安吉拉（艾玛·沃森 Emma Watson 饰）而遭到逮捕。负责调查此案的警官布鲁斯·肯纳（伊桑·霍克 Ethan Hawke 饰）对约翰展开问询，而在这一过程中约翰起先承认罪行，随后又突然失忆。为了应对这一突发状况，心理学教授肯尼斯·睿恩斯博士（大卫·休里斯 David Thewlis 饰）也介入调查之中。他们发现，约翰信奉崇拜魔鬼撒旦的黑宗教，甚至布鲁斯的搭档都有可能参与其中。布鲁斯和肯尼斯想方设法要打开嫌疑人和受害者的记忆闸门，让他们想起最不堪回首的一段往事……本片根据真实事件改编。©豆瓣', '伊桑·霍克', '亚历杭德罗·阿梅纳瓦尔', 5.6, 6338, 'tt3319920', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2271641463.jpg', 5.3, 28.4, 51.4, 12, 2.9, '0.440870,-0.225602,-0.450168,0.403870,0.115435,-0.448523,0.797939,-0.168207,-0.569784,-0.585151,0.256601,0.651428,-0.160001,-0.165002,0.607290,0.022572,-0.743632,-0.577618,0.204750,-0.288193,-0.145923,-0.853844,-0.246522,-0.416263,0.208509,-0.443272,0.193647,-0.281617,-0.081928,0.553381,0.180951,0.618747,-0.136860,0.120522,0.543797,0.138178,0.447520,-0.124365,-0.497121,-0.044540,0.121561,-0.071448,-0.221545,0.200808,-0.247174,0.307359,0.299266,-0.346494,-0.174625,-0.096026,0.284920,-0.453148,-0.072943,0.050227,0.461681,0.090622,-0.043143,0.636110,-0.127376,-0.146127,0.053785,0.170382,-0.601988,-0.009946,-0.071328,0.494418,-0.201787,-0.132414,-0.346505,0.233491,0.174096,-0.225705,-0.008640,0.326217,0.649537,0.167019,-0.029488,0.005822,-0.271820,0.168307,0.266285,-0.172556,-0.176575,0.050491,-0.207946,-0.223344,0.022108,0.040261,-0.385593,0.086337,0.174547,-0.065795,-0.140233,0.598383,-0.371548,-0.273807,-0.426301,-0.223890,-0.330605,-0.090405,-0.143130,-0.684399,-0.387353,-0.074265,-0.151128,-0.376063,-0.061974,-0.231128,0.368423,-0.598819,0.333444,0.487071,0.107371,-0.278599,0.217881,0.218444,0.068531,-0.496358,-0.320476,0.201754,0.352038,0.121615,-0.226504,0.215855,0.405053,-0.515262,-0.212900,0.144876', '1296217', '27031237', '2369549', '3006781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25761178', '百元之恋', '剧情', '早已过了而立之年的一子（安藤樱 饰）整天百无聊赖，她根本无心帮助打理自家的料理店，整日玩游戏虐杀小外甥。她的妹妹二三子（早织 饰）离婚后回到娘家，极度看不惯姐姐的作为，为此两姐妹甚至大打出手。自感不被家人所容的一子搬了出去，并在日常光顾的百元超市谋得收银员的职位。这间小店云集着许多怪人，患有忧郁症的店长、话唠猥琐的同事、因盗窃被开除却还时常回来拿临过期食品的老太。在这些人中间，一子的心情愈加苦闷。偶然机缘，她和名不见经传的拳击手狩野（新井浩文 饰）走到一起，无奈他们之间甚至连爱情都谈不上。极度压抑之际一子选择学习拳击，她渴望释放心中不委屈和不满，渴望获得哪怕只有一次的认可。本片荣获2014年日本电影旬报十佳影片第八名。©豆瓣', '安藤樱', '武正晴', 8.4, 146561, 'tt4080598', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205471169.jpg', 0.3, 1.1, 14.2, 49.3, 35.1, '0.259218,-0.045143,-0.718867,0.290337,-0.056472,-0.423985,0.609334,0.341606,-0.593645,-0.264329,0.128368,0.515809,-0.287369,0.389346,0.105784,-0.098077,-0.112765,-0.262146,-0.087805,-0.084966,-0.025776,-0.213708,-0.112829,-0.058898,-0.406125,-0.238003,0.415337,-0.100298,-0.157668,0.361807,0.189325,0.112760,0.038933,0.361927,-0.118004,0.132628,-0.064764,0.115091,-0.091308,-0.033832,-0.014139,-0.156525,-0.164466,-0.028341,0.265442,0.331093,0.588550,0.020063,-0.188997,-0.189553,0.390669,-0.004846,-0.261728,0.127921,0.253140,0.022478,0.518075,0.053677,-0.243409,0.065295,0.154740,0.071294,-0.622517,0.211055,0.028020,0.133747,-0.452763,0.642465,0.008490,-0.049094,0.028258,-0.297627,0.111170,0.143519,-0.190720,0.345013,-0.329229,0.080224,-0.569371,0.388791,0.648757,-0.066845,0.092368,0.309931,-0.026259,-0.050359,0.158251,-0.364650,-0.476014,-0.109767,0.204068,0.085024,-0.110876,0.155773,-0.392332,0.132942,0.057388,0.053463,0.184789,-0.461739,0.032739,-0.579403,0.045612,-0.389994,-0.344438,0.036575,0.417440,-0.216717,0.706195,-0.596749,0.219495,0.324640,0.280055,-0.508711,0.583211,0.266091,0.093043,-0.089775,-0.259567,0.129351,-0.017560,0.167958,0.271712,0.225886,-0.104534,-0.193214,-0.089186,0.351784', '25721544', '26283288', '1296044', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25762566', '道熙呀', '剧情', '不苟言笑的首尔女警官李英男（裴斗娜 饰），因某件事被“流放”到一个偏远闭塞的海港小镇担任为期一年的派出所所长。抵达当地的第一天，英男便遇见了怯懦沉默的小女孩孙道熙（金赛纶 饰）。道熙是当地唯一的青壮年朴龙河收养的孩子，但是朴及其母亲却经常对道熙拳脚相向，女孩在校期间也饱受同学的欺负。某晚，英男从醉酒的朴龙河手中搭救了道熙，自此之后道熙便成为了她的小跟班。之后的一天，朴母死于意外，这让道熙得以暂时躲在英男的家中避难。在英男的呵护下，女孩的脸上展现了久违的笑容，然而彼时一股暧昧的气氛悄然升起，英男被迫卷入命运的漩涡之中……©豆瓣', '裴斗娜', '郑朱莉', 7.8, 44092, 'tt3661798', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2180405730.jpg', 0.2, 1.9, 27, 49.5, 21.3, '-0.017457,-0.013882,-0.628204,0.505758,-0.098420,-0.240698,0.607533,0.357699,-0.376231,-0.124227,0.171965,0.694561,-0.332704,0.705034,0.545079,-0.142459,-0.080994,-0.629234,-0.462394,-0.251023,-0.347162,-0.098949,0.219131,0.043536,-0.240037,-0.313687,0.622679,0.362001,-0.157083,0.536819,0.240010,0.248029,-0.291419,0.484210,-0.214102,0.085728,-0.043970,-0.068672,0.108132,0.030669,0.142518,-0.488682,-0.171430,0.157705,0.197043,0.575186,0.941041,-0.133829,-0.191503,-0.139613,0.317156,-0.233065,-0.181902,-0.148766,0.356385,-0.206790,0.027088,-0.105469,-0.355289,-0.158747,0.308455,-0.099257,-0.222933,0.161451,-0.046842,-0.050893,-0.440376,0.455068,0.339458,-0.117615,0.126908,-0.256968,0.161007,0.302820,-0.208347,0.340336,-0.107302,0.292634,-0.212783,0.342907,0.577698,-0.034841,-0.424879,0.346469,-0.253323,-0.504699,0.039019,-0.173100,-0.612730,-0.090391,0.297537,-0.037041,-0.193203,-0.076503,-0.389645,-0.120718,-0.215277,0.197103,0.064149,-0.159143,-0.303275,-0.646258,-0.107706,-0.290507,-0.192398,0.255228,-0.022762,0.003628,0.597867,-0.861769,0.289678,0.447580,0.254755,-0.294449,0.500932,0.093719,0.230762,-0.094531,0.022978,0.277659,0.219971,0.270087,0.214734,0.368607,-0.624485,-0.127069,-0.267601,0.211514', '3811356', '3155839', '26687241', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25763555', '废柴特工', '喜剧', '迈克（杰西·艾森伯格 Jesse Eisenberg 饰）是一名彻彻底底的宅男，长这么大，他一步都不曾踏出过他生活的小镇之外。平日里，迈克在超市当收银员，闲暇时光中，他喜欢画漫画，然而麦克甚至自己所创造的角色和故事永远都不会有被大众知晓的那一天。菲比（克里斯汀·斯图尔特 Kristen Stewart 饰）是迈克的女友，迈克最大的心愿，就是能够克服内心的恐惧，带菲比去夏威夷度假。让迈克怎么也想不明白的是，如此平凡的自己的身边，为何会忽然出现一波又一波想要夺走自己性命的变种人特工。然而，当事态的恶化牵连到了整个小镇以及菲比的安全之时，隐藏在迈克体内的力量爆发，他摇身一变，成为了凶残无情的杀人机器。©豆瓣', '杰西·艾森伯格', '尼玛·诺里扎德', 6.1, 32794, 'tt3316948', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2333514158.jpg', 3.5, 18.8, 51.5, 19.9, 6.4, '0.199474,-0.016299,-0.717404,0.562085,-0.377259,-0.224200,0.810014,0.001449,-0.470048,-0.215507,0.262124,0.948353,-0.186097,0.238735,0.102324,0.155052,-0.139255,-0.608641,-0.103426,-0.246973,-0.158921,-0.305392,-0.354715,-0.183763,0.063259,-0.297692,0.527689,0.052267,-0.212419,0.193562,0.318574,0.380874,0.047756,0.526130,-0.187659,0.067547,0.102803,-0.187185,0.010927,0.078901,0.144518,-0.284125,-0.152850,0.440508,-0.164271,0.279267,0.588153,-0.000406,-0.097327,-0.163186,0.356444,-0.262655,0.023655,-0.026769,0.076308,-0.267981,0.070988,0.149190,-0.130047,-0.009932,0.172675,-0.071429,-0.868806,0.036292,-0.085665,0.245979,-0.605462,0.063100,-0.151071,-0.254930,0.192172,-0.253421,0.096142,0.075654,0.391464,0.263879,-0.054262,0.005502,-0.629441,0.090455,0.792107,-0.071354,-0.479459,0.522047,-0.228185,-0.294780,-0.157896,-0.305859,-0.625258,-0.098477,0.204954,0.167615,-0.287917,0.310457,-0.395216,0.131296,-0.332202,-0.120180,0.003657,-0.404698,-0.298225,-0.427630,-0.179808,-0.467271,-0.217639,-0.054268,0.049835,-0.322776,0.663665,-0.747324,0.263144,0.589422,0.237530,-0.403801,0.603780,0.147608,-0.063465,0.017136,0.013651,0.212982,0.137799,0.391333,0.050107,0.293641,0.135156,-0.094113,-0.434389,0.821100', '30162520', '34890458', '1783461', '1308976');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25765735', '金刚狼3：殊死一战', '剧情', '故事发生在2029年，彼时，X战警早已经解散，作为为数不多的仅存的变种人，金刚狼罗根（休·杰克曼 Hugh Jackman 饰）和卡利班（斯戴芬·莫昌特 Stephen Merchant 饰）照顾着年迈的X教授（帕特里克·斯图尔特 Patrick Stewart 饰），由于衰老，X教授已经丧失了对于自己超能力的控制，如果不依赖药物，他的超能力就会失控，在全球范围内制造无法挽回的灾难。不仅如此，金刚狼的自愈能力亦随着时间的流逝逐渐减弱，体能和力量都早已经大不如从前。某日，一位陌生女子找到了金刚狼，将一个名为劳拉（达芙妮·基恩 Dafne Keen 饰）的女孩托付给他，嘱咐他将劳拉送往位于加拿大边境的“伊甸园”。让罗根没有想到的是，劳拉竟然是被植入了自己的基因而培养出的人造变种人，而在传说中的伊甸园里，有着一群和劳拉境遇相似的孩子。邪恶的唐纳德（波伊德·霍布鲁克 Boyd Holbrook 饰）紧紧的追踪着罗根一行人的踪迹，他的目标只有一个，就是将那群人造变种人彻底毁灭。', '休·杰克曼', '詹姆斯·曼高德', 8.3, 405866, 'tt3315342', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2431980130.jpg', 0.4, 1.5, 16.9, 45.6, 35.6, '0.163450,0.040662,-0.694261,0.536289,-0.411728,-0.180133,0.953434,0.002755,-0.445505,-0.449751,0.184495,0.577878,-0.003678,0.096526,0.088519,0.060953,-0.117497,-0.637178,-0.246303,-0.069777,-0.524786,-0.497865,-0.490088,-0.331062,0.198787,-0.847929,0.501304,-0.043281,-0.421295,0.235200,0.132724,0.392995,-0.087664,0.431170,-0.370543,0.149362,0.057203,-0.259071,0.082831,0.300863,0.155006,-0.161998,0.108443,0.167190,-0.173004,0.312445,0.829632,-0.602156,-0.104163,-0.230957,0.182397,-0.368706,-0.102369,0.081446,0.403244,-0.069560,0.068613,0.106595,-0.292828,0.081298,0.156775,-0.035160,-0.975264,0.181319,0.126666,0.212507,-0.635583,0.617282,-0.020168,-0.082619,0.084278,-0.344348,0.199961,0.202707,0.019687,0.437483,-0.021234,-0.024130,-0.566619,0.015151,0.555494,-0.087919,-0.582129,0.276440,-0.337165,-0.409810,-0.398711,-0.153018,-0.380171,-0.131750,0.401947,0.272801,-0.143492,0.459992,-0.572517,0.135863,-0.395507,-0.266590,-0.102721,-0.287625,0.004460,-0.570957,-0.128067,-0.400333,-0.254375,0.187182,0.197175,-0.185821,0.947171,-0.853002,0.371218,0.535959,0.353192,-0.432506,0.554747,-0.322036,0.120196,-0.296005,-0.064322,0.345391,0.080980,0.337687,0.375824