INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25766529', '走到尽头', '动作', '道貌岸然的水源警局警官高建洙（李善均 饰）正处在人生的危急关头，他的母亲不久前刚刚去世，警局方面因为和同事涉嫌受贿而被检察官调查，回家奔丧的路上速度过快又不慎撞死了人。高左右奔突，疲于奔命，最后以瞒天过海的方式逃过一劫。好不容易渡过危机的高和同事受命追查一个通缉犯，结果却发现对方正是自己撞到的人。雪上加霜的是，偏偏有人目击了车祸过程，并且匿名举报。之后不久，神秘之人（赵镇雄 饰）打来电话，直接道出高建洙撞到通缉犯的隐情。对方拥有和高警官同样体面的身份，而他反复纠缠这个惊弓之鸟背后又有怎样不可告人的目的？©豆瓣', '李善均', '金成勋', 8, 86742, 'tt3697626', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2183957412.jpg', 0.1, 1, 20.3, 54.8, 23.9, '0.144557,-0.012757,-0.630387,0.577001,-0.165454,-0.198358,0.722013,0.274486,-0.631314,-0.271056,0.467286,0.502906,-0.283581,0.107842,0.356891,-0.129904,-0.190656,-0.694440,0.226674,-0.157061,-0.629896,-0.438369,-0.339721,-0.212743,0.030610,0.108819,0.100677,0.114078,-0.325834,0.287416,0.137763,0.455681,-0.286053,0.671988,-0.124774,0.052768,0.047663,0.058836,-0.055109,0.105537,0.400579,-0.469716,-0.232060,0.039084,-0.199679,0.725079,0.409539,0.068267,-0.343229,-0.026038,0.435811,-0.458058,0.040544,0.005975,0.563722,-0.104676,0.381136,0.083478,0.000429,-0.195155,0.171406,0.158031,-0.586591,0.193702,-0.063923,-0.000484,-0.245804,0.111939,-0.172406,0.141884,0.192805,-0.380123,0.043459,0.480186,0.158852,0.208251,-0.165770,-0.082294,-0.629358,0.109117,0.660486,0.048305,-0.152058,0.096092,0.076503,-0.435142,0.083944,-0.354038,-0.139298,0.078300,0.625321,0.096427,-0.228896,-0.062070,-0.207864,-0.096506,-0.513328,0.182741,-0.254322,-0.267613,-0.289776,-0.255538,-0.116415,-0.253276,-0.400532,0.196773,0.148803,-0.120203,0.308190,-0.541141,-0.013597,0.810565,0.214925,-0.641942,0.535847,-0.101839,-0.164880,-0.218289,-0.193215,-0.191547,0.144661,0.700716,0.095698,0.067300,-0.172195,-0.304827,-0.500129,0.108141', '1309116', '1947080', '1293434', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25766754', '年轻气盛', '剧情', '老友米克和弗雷德结伴前往阿尔卑斯的度假旅馆，他们以爱和幽默的视角，探讨子女们满是麻烦的生活。米克是导演，正在积极创作自己看来最重要的一部电影，而早就没有了事业追求的指挥家、作曲家弗雷德却收到女王伊丽莎白二世的邀请为菲利普的生日演奏。', '蕾切尔·薇兹', '保罗·索伦蒂诺', 8.2, 124423, 'tt3312830', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2561567154.jpg', 0.5, 2, 17.6, 45.7, 34, '0.413200,-0.427473,-0.621679,0.919664,-0.160959,-0.531837,0.829401,0.243795,-0.226058,-0.467181,0.370904,1.029295,0.047192,0.252727,0.527000,-0.091948,-0.609054,-0.631306,0.096512,0.207111,0.120872,-0.559162,0.016259,-0.330802,-0.125535,-0.340724,0.653974,-0.247121,-0.114721,0.525258,0.315731,0.466169,0.009069,0.154984,-0.282605,-0.124278,0.523963,0.232463,-0.438701,0.235371,0.179241,-0.013209,-0.367325,0.184218,0.240053,0.505836,0.399388,-0.307953,0.013864,0.155704,0.532354,-0.441354,0.290661,0.050064,0.055405,-0.057312,0.535644,0.185032,0.198487,-0.290910,-0.158259,-0.452007,-1.035186,0.065178,0.224815,0.050525,-0.466887,0.416924,-0.176007,-0.286015,0.288700,-0.314041,0.480206,0.542931,0.225613,0.557496,0.102461,0.185380,-0.324421,0.339683,0.727983,0.115377,-0.101144,0.483863,-0.592035,-0.376868,0.208367,-0.223056,-0.794539,-0.057161,0.220374,-0.218048,0.338221,0.188353,-0.668055,-0.026443,-0.138770,-0.587051,0.583075,-0.615705,0.093394,-1.266458,-0.103173,-0.440572,0.066159,-0.323335,0.397701,-0.487248,1.081329,-1.062056,0.111025,0.564956,0.054168,-0.711288,1.200593,0.102360,-0.263637,-0.389899,-0.024416,0.088769,-0.064639,0.073041,-0.108223,0.328880,0.413165,-0.281027,-0.680732,0.624929', '3318306', '26611806', '4301278', '26259202');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25767747', '故事的故事', '剧情', '电影由三个相互关联的小故事组成。国王（约翰·C·赖利 John C. Reilly 饰）最宠爱的除了蛮横娇纵的公主维奥拉（蓓蓓·卡芙 Bebe Cave 饰）外，就是他的宠物跳蚤了，让所有人都没有想到的是，小小的跳蚤，竟然长成了绵羊的大小。女王（萨尔玛·海耶克 Salma Hayek 饰）常年被不孕之病困扰，国王用自己的生命换来了海兽的心脏给女王吃，如此便可药到病除，哪知道不仅仅是女王怀孕了，为女王烹饪心脏的侍女也怀孕了，两人于同一时间生下了孩子。国王爱上了在城堡下面唱歌的女子，他并不知道的是，这位女子的真身其实是一位丑陋的老巫婆，而她还有这一个双生姐妹。国王邀请她们其中的一位同自己共度良宵，哪知道被卷入了一场动乱之中。©豆瓣', '萨尔玛·海耶克', '马提欧·加洛尼', 7.7, 52546, 'tt3278330', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264784442.jpg', 0.5, 2.6, 28.1, 48.1, 20.7, '0.177201,-0.048235,-0.555622,0.662955,-0.164052,-0.108643,1.100384,0.118711,-0.408444,-0.168861,0.443394,0.587578,-0.296077,0.106216,0.182957,0.220467,0.094038,-0.453947,-0.222763,-0.131429,-0.302467,-0.228257,-0.248135,-0.268446,-0.012532,-0.540484,0.582841,-0.199792,0.047475,0.088831,0.568440,0.208109,0.008846,0.155000,-0.273683,0.196704,-0.066742,0.038393,0.088773,0.162460,-0.056206,-0.190843,0.093061,0.414106,-0.116954,0.348825,0.448223,-0.688873,0.111689,-0.471160,0.322609,-0.128047,0.055257,0.289205,0.343550,-0.323132,0.490196,-0.072926,-0.121398,-0.075094,0.365470,-0.053409,-0.731578,0.122136,0.078753,0.318825,-0.660363,0.371708,-0.097817,-0.246957,0.029040,-0.189989,0.420720,0.296799,0.100447,0.472041,-0.082122,0.051400,-0.637170,0.119407,0.690488,0.097630,-0.390534,0.348689,-0.212660,-0.579665,0.092744,-0.471591,-0.431539,0.259434,-0.043226,-0.014918,-0.106397,0.267870,-0.572002,0.114430,-0.418469,-0.120085,0.142694,-0.593560,-0.253609,-0.125831,-0.081739,-0.363839,-0.296436,0.098708,0.306627,-0.216157,0.951829,-0.857467,0.245891,0.492423,0.268142,-0.586661,0.811662,0.197528,-0.048601,-0.183662,-0.043258,0.041799,0.120486,-0.065756,0.153865,0.414183,0.093848,-0.079005,-0.422899,0.371818', '3005387', '35206315', '21619567', '7065238');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25769362', '哆啦A梦：伴我同行', '剧情', '生活在日本东京的野比大雄（大原惠美 配音），是一个学习不上进、日常迷迷糊糊并且饱受同学欺负的男孩。他的性格不仅左右着自己的事业和婚姻，还对未来子孙产生莫大的影响。为此，大雄孙子的孙子世修（松本さち 配音）带着猫型机器人哆啦A梦（水田山葵 配音）乘坐时光机突然来访，期望彻底改变大雄及整个家族的命运。在哆啦A梦的帮助下，大雄不再受到胖虎（木村昴 配音）和小夫（关智一 配音）等人的欺负，他喜欢美丽的女孩源静香（嘉数由美 配音）。为了实现和静香结婚的命运，他和哆啦A梦穿越时空，见证了决定人生的最关键的时刻和事件。当大雄慢慢开始变得幸福之际，哆啦A梦也到了必须返回22世纪的时候……本片根据藤子·F·不二雄的经典名作改编。©豆瓣', '水田山葵', '八木龙一', 8.1, 262087, 'tt3331846', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2244958975.jpg', 0.8, 3.1, 21.4, 40.3, 34.4, '-0.137429,-0.134431,-0.491227,0.493743,-0.052259,-0.265681,0.405124,0.324320,-0.171877,-0.306166,0.064243,0.767594,-0.149238,0.323396,0.275938,0.081996,-0.266673,-0.689828,-0.233188,0.296639,-0.304256,-0.272722,0.242534,-0.057419,-0.102029,-0.266369,0.624555,-0.058983,-0.195979,0.290684,0.156732,0.276170,-0.099891,0.077221,-0.154294,0.141412,0.007607,0.271015,-0.338813,0.051987,-0.111554,0.059793,-0.119299,0.102805,0.019836,-0.010645,0.612774,-0.574840,-0.394146,-0.190947,0.343186,-0.261005,-0.294253,-0.117107,0.155411,-0.047963,0.242699,0.139478,-0.151469,-0.008414,-0.060738,-0.228300,-0.805107,-0.049482,0.143299,-0.067294,-0.461739,0.381808,0.016434,-0.032444,0.597847,-0.277381,0.124462,0.402354,0.435470,0.471917,-0.404719,0.314668,-0.187024,0.200766,0.687078,0.099720,-0.082120,0.530664,-0.164723,-0.288546,-0.154186,-0.290492,-0.566846,0.109901,0.143687,-0.102376,-0.369056,0.351600,-0.388535,-0.017167,0.123592,-0.263661,0.247258,-0.541869,-0.116258,-0.458878,0.035353,-0.394606,-0.137943,0.222788,0.078223,-0.503333,0.949037,-0.913647,0.153057,0.657663,0.198596,-0.236999,0.588907,0.078038,-0.039369,-0.326684,0.041696,-0.001736,-0.089816,0.168700,0.231779,0.223203,-0.103643,0.088935,-0.471909,0.525510', '27602116', '24284209', '25928048', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25772639', '小飞侠：幻梦启航', '动作', '潘（莱维·米勒 Levi Miller 饰）自小失去了父母，生长在孤儿院中，是那里典型的“问题儿童”。潘热爱自由，脑袋里都是稀奇古怪天马行空的念头，调皮捣蛋惹事闯祸的总是他，让孤儿院的院长很是头痛。某天夜里，潘在意外之中来到了名为“梦幻岛”的神奇世界中，在这里，有海盗、战士，还有只曾在童话书里看见过的精灵。在梦幻岛，潘结识了女战士虎莲公主（鲁妮·玛拉 Rooney Mara 饰）和虎克船长（加内特·赫德兰 Garrett Hedlund 饰），他们在等待着一位佩戴牧笛项链的神秘人物的到来，这位神秘人将会率领他们，同邪恶的黑胡子海盗（休·杰克曼 Hugh Jackman 饰）展开激烈的斗争。©豆瓣', '莱维·米勒', '乔·赖特', 6.1, 15163, 'tt3332064', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2274761140.jpg', 2.6, 17.3, 56.1, 18.5, 5.4, '0.197105,0.019759,-0.665645,0.514566,-0.071778,0.021659,0.853522,-0.205987,-0.726995,-0.326588,0.097909,0.515723,-0.270652,0.507039,0.536843,0.174098,-0.402422,-0.549305,-0.157679,-0.176593,-0.353150,-0.574019,-0.399061,-0.523512,-0.005153,-0.462431,0.296448,0.248579,-0.239481,0.407655,0.393991,0.389727,-0.330688,0.328311,-0.494086,0.168000,0.227985,-0.025229,0.101682,-0.057262,0.076581,-0.202301,-0.016494,0.201071,0.335163,0.172541,0.640194,-0.781767,0.049680,-0.139884,0.073594,-0.003838,0.022232,-0.092499,0.521338,-0.139006,0.179787,-0.071231,0.036871,0.179621,0.088582,-0.241702,-0.412107,-0.030423,0.230164,0.352535,-0.801537,0.310273,0.086033,-0.060160,0.211727,-0.143083,0.387084,-0.014641,0.243268,0.313786,0.320200,0.005492,-0.422303,0.407293,0.471078,0.066422,-0.164469,0.024436,-0.508233,-0.497337,-0.131745,-0.184936,-0.512099,-0.134041,0.494655,-0.229030,0.048905,0.277860,-0.555908,0.142453,0.064082,0.092975,-0.100342,-0.226240,-0.309044,-0.418432,0.102818,-0.475111,-0.088410,0.376184,-0.276026,-0.131281,0.767296,-1.010892,0.446967,0.330468,0.291867,-0.144381,0.721216,-0.004139,0.062242,-0.276312,-0.103091,0.356858,0.192321,0.072834,0.198628,0.284240,-0.123958,-0.130962,-0.261669,0.472603', '1302384', '7065238', '1306544', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25773932', '爆裂鼓手', '剧情', '19岁少年安德鲁（迈尔斯·特勒 Miles Teller 饰）成长在单亲家庭，一心想成为顶级爵士乐鼓手。某晚他在学校练习时被魔鬼导师弗莱彻（J·K·西蒙斯 J.K. Simmons 饰）相中，进入正规乐队，同时也开始为追求完美付出代价。安德鲁越是刻苦练习，与外部世界越是隔膜。唯一理解他的是弗莱彻，但后者的暴躁与喜怒无常扭曲了这段师生关系，更让安德鲁耳濡目染，连带自身的性格亦发生变化。最后当安德鲁终于登上纽约音乐厅的舞台，他才惊恐的发现原来弗莱彻一直等着将他打入尘埃......《爆裂鼓手》讲述一名少年在严师督教下，以非常规手段挑战自己的极限、追逐爵士乐鼓手梦的热血故事。主人公热爱打鼓，但过度的投入让他失去对音乐的初衷，进而演变为生命的负荷以及师徒间近乎疯魔的对决。电影不只有音乐人的苦痛，更让人看到传统励志背后的残酷真相。 《爆裂鼓手》获得第30届圣丹斯电影节最高荣誉评审团奖。', '迈尔斯·特勒', '达米恩·查泽雷', 8.7, 542348, 'tt2582802', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2220776342.jpg', 0.4, 1, 10.9, 40.5, 47.1, '0.034267,0.039330,-0.606655,0.638961,-0.044115,-0.287889,0.627903,0.127747,-0.489144,-0.207216,0.303086,0.867663,-0.420186,0.088083,0.155404,-0.191860,-0.149998,-0.742967,-0.284107,0.002058,-0.050286,-0.439651,-0.085344,-0.067860,-0.199925,-0.472153,0.832193,0.037839,-0.521883,0.329377,0.394677,0.164798,0.194081,0.287544,0.036962,-0.285945,0.222762,-0.037588,-0.133620,-0.156903,0.091059,-0.271371,-0.101514,0.130093,-0.324765,0.065764,0.766855,-0.317302,0.143921,-0.145659,0.587742,-0.232951,-0.264857,0.088039,0.087827,0.192617,0.069816,0.207459,0.090271,0.225094,-0.259175,-0.091778,-0.829147,-0.018646,0.206931,-0.077255,-0.392555,0.283936,0.004995,-0.066645,0.364508,-0.018795,-0.005207,0.190135,0.511786,0.442604,-0.437826,-0.075368,-0.206246,0.183112,0.654608,0.091035,-0.642342,0.344497,-0.375406,-0.530662,-0.245296,-0.425749,-0.387161,-0.229184,0.165483,0.281235,0.044319,0.379200,-0.408661,0.008004,-0.022194,-0.220914,-0.109091,-0.396346,-0.176684,-0.667861,-0.232541,-0.253538,-0.083458,-0.219792,0.012395,-0.454642,0.975521,-0.740247,0.310701,0.428644,0.032972,-0.165912,0.616233,0.050241,-0.040211,-0.368427,-0.214622,0.522921,-0.225443,0.191719,-0.105943,0.354498,-0.211361,0.102208,-0.357415,0.793587', 