INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25774050', '寄生兽', '剧情', '在某个神秘的夜晚，可怕的孢子突然降临地球，它们钻进人类的身体，从而将其据为己有，并且将人类作为猎杀吞食的目标。高中生泉新一（染谷将太 饰）也险些被孢子控制大脑，结果这个待在右手中寄生兽“小右”（阿部隆史 饰）便与之展开了奇妙的共存。某天，学校里来了位新老师田宫良子（深津绘里 饰），她和小右都敏锐地察觉到对方的存在。田宫将A（池内万作 饰）和岛田秀雄（东出昌大 饰）介绍给小右，并邀请他加入全部由寄生兽组成的网络以谋求发展。在此期间，新一和小右遭到A的伏击，而相依为命的母亲（余贵美子 饰）也不慎沦为寄生兽的俘虏。为了保护最重要的人，新一只有向穷凶极恶的寄生兽展开攻击……本片根据岩明均的同名漫画改编。©豆瓣', '染谷将太', '山崎贵', 7.4, 150213, 'tt3345472', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2375921261.jpg', 0.6, 3.4, 34.7, 46.7, 14.6, '0.373064,0.069136,-0.514797,0.485067,-0.044112,-0.041374,0.763308,0.061183,-0.125512,-0.181217,0.176870,0.735177,-0.032585,-0.007757,0.362473,0.041684,0.065722,-0.720393,-0.220270,-0.091518,-0.502863,-0.218477,-0.452184,-0.094355,-0.008930,-0.249241,0.789176,-0.022916,-0.427933,0.348406,0.163848,0.527928,-0.260129,0.404106,-0.107507,0.163731,-0.222429,-0.165721,0.024586,0.278097,-0.147380,-0.296021,0.160218,0.280013,-0.137837,0.318698,1.006911,-0.716033,-0.111263,-0.458570,0.353266,-0.352479,-0.059443,0.222943,0.398188,0.237361,0.078855,0.197116,-0.250051,0.277512,0.179422,-0.075247,-1.075073,-0.129110,0.191777,0.074216,-0.292762,0.096121,0.208108,-0.162205,0.214638,-0.241556,0.160466,0.426506,0.198528,0.301216,-0.373873,0.059939,-0.127854,0.038275,0.376762,-0.205106,-0.310749,0.133878,-0.039334,-0.504345,-0.144107,-0.139671,0.006565,-0.243952,0.334259,0.399698,-0.067206,0.176101,-0.936255,-0.024677,-0.080603,-0.281163,0.093547,-0.368170,-0.140495,-0.561751,-0.103219,-0.250098,-0.186591,0.158534,0.239522,-0.212013,0.855627,-0.850516,0.083630,0.625793,0.449467,-0.369364,0.310200,-0.181198,0.146764,-0.128344,-0.131659,0.079340,0.347337,0.567528,0.109938,0.394255,0.010255,-0.158892,-0.501437,0.253017', '26759820', '1308585', '26759819', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25774051', '寄生兽：完结篇', '剧情', '岛田学校大暴走，让人类和寄生兽的共存设想彻底破灭。泉新一（染谷将太 饰）的人生遭受巨变，他和里美（桥本爱 饰）似乎也因此事件出现隔阂。另一方面，田宫良子（深津绘里 饰）在生下孩子后心境渐渐发生变化，她设法令同伴以和平的方式融入人类世界，但是东福市市长广川刚志（北村一辉 饰）则授意后藤（浅野忠信 饰）等寄生兽中的死硬派抹杀新一、小右（阿部隆史 配音）以及试图曝光寄生兽存在的自由记者仓森（大森南朋 饰）。双方的战斗逐渐升级，全副武装的警方开始冲击广川盘踞的市政府，而新一和良子则将再次迎来生命的巨大考验……本片根据岩明均累计发行量超过1300万册的经典漫画改编。©豆瓣', '染谷将太', '山崎贵', 7.1, 49938, 'tt3345474', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2232822577.jpg', 0.7, 5.6, 44.8, 36.8, 12.1, '0.017363,0.048077,-0.390861,0.330875,0.159211,-0.101088,0.582643,0.274221,-0.326140,-0.179302,0.311843,0.571608,-0.221667,0.058156,0.365488,-0.348270,-0.267900,-0.605641,0.007082,0.066228,-0.089859,-0.468279,-0.214232,-0.202335,-0.071830,-0.360133,0.931623,0.046793,-0.267760,0.393307,0.177845,0.403192,-0.265266,0.276450,0.310240,0.156560,-0.039740,-0.096574,-0.259872,0.101910,-0.221105,-0.203567,0.148890,0.183486,-0.125829,0.203936,0.831955,-0.578237,-0.085592,-0.403118,0.526465,-0.215340,-0.369689,0.262188,0.353953,0.242409,0.136914,0.396444,-0.282636,0.040997,-0.017662,-0.035004,-0.739700,-0.170109,0.144483,0.157335,-0.004159,0.237291,0.144859,-0.199473,0.273901,0.019035,-0.046659,0.396402,0.601229,0.176021,-0.425092,0.054298,-0.010163,0.050185,0.340613,-0.242321,-0.285437,0.211133,-0.212933,-0.343864,-0.362270,-0.195882,-0.200102,-0.126542,0.004796,0.269389,0.072883,0.307224,-0.718815,-0.120214,-0.248751,-0.359119,0.057790,-0.127366,-0.091499,-0.499068,-0.256416,-0.303829,-0.209886,0.122085,0.167601,-0.276268,0.857117,-0.696101,-0.029959,0.311782,0.459846,-0.346617,0.246677,-0.015494,0.049543,-0.317556,0.033926,0.192784,-0.077573,0.450154,0.118779,0.200183,-0.168184,-0.014442,-0.285284,0.515189', '26759820', '26759819', '25880986', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25774126', '爷们儿些', '喜剧', '南希（蕾克·贝尔 Lake Bell 饰）是一名34岁的女记者，一天，在火车上，南希邂逅了一个女孩，女孩将自己手上的一本书留给了南希，这本书是女孩和她的相亲对象的接头暗号。列车到站之后，南希想要将书还给女孩，然而女孩早已经不见了踪影。就在南希手持着书本在伦敦滑铁卢车站大钟底下徘徊之际，一个名为杰克（西蒙·佩吉 Simon Pegg 饰）的男子喊住了南希，他手中有一本和南希一模一样的书。原来，杰克误将南希错认为了自己的相亲对象。就这样，在误打误撞之中，南希和杰克开始了交往，这段由一个误会开启的感情，能否顺利的走到终点呢？©豆瓣', '西蒙·佩吉', '本·帕尔马', 7.6, 29886, 'tt3064298', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2272055771.jpg', 0.4, 2.9, 32.2, 47.7, 16.8, '0.771625,-0.073880,-0.602708,0.306658,-0.233203,-0.579772,0.825952,0.026661,-0.216120,-0.033178,0.528639,0.910172,-0.341803,0.347429,0.509516,0.433055,-0.343266,-0.936242,-0.044078,-0.482343,-0.429636,-0.602393,-0.179712,0.151019,0.069038,-0.336369,0.420656,-0.254565,0.158559,0.533962,0.228451,0.041370,-0.075241,0.506862,-0.237523,0.285726,0.365789,-0.251811,0.011127,0.464148,0.157068,-0.272892,-0.046640,0.461423,-0.076122,0.285266,0.839123,-0.215380,0.099537,0.202555,0.296831,-0.077093,-0.074624,0.155399,0.427456,-0.059445,0.188626,0.032986,-0.349424,-0.035059,0.122574,-0.045293,-0.267021,0.205262,-0.418387,0.288483,-0.618590,0.528633,-0.371154,-0.157327,0.218843,-0.713764,0.322611,0.251314,0.075662,0.097170,-0.188808,-0.211112,-0.450985,0.280100,0.260437,-0.030733,-0.021357,0.689462,0.151072,-0.228442,-0.298596,0.235732,-0.698963,-0.107705,0.614214,0.009065,-0.177488,-0.121131,-0.680758,0.145445,-0.290353,-0.074500,0.119723,-0.407669,-0.542269,-0.183843,-0.149276,-0.132921,-0.258860,0.016156,-0.099506,-0.198388,0.783047,-0.750752,0.155412,0.745616,0.051133,-0.100396,0.808657,0.017198,0.116927,-0.053526,0.222337,-0.044998,0.148885,0.520947,0.211879,0.632447,0.194446,-0.073752,-0.496116,0.500689', '1307146', '3155839', '4233625', '1915403');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25774688', '同等族群', '剧情', '故事发生在遥远的未来世界中，在彼时的社会里，一群被称为“Equals”的种族成为了其中的主要生产力。相较于普通人类，Equals更加的完美，他们有美丽的外貌，高尚的道德感，稳定的情绪，聪慧的头脑，但与此同时，过于的完美让Equals失去了人类的感情。被称为SOS的疾病是这个社会里存在的最大不稳定因素，患上了SOS的人会变得敏感悲伤，抑郁冲动，居民们一旦被发现患上SOS症，就会被政府流放，永远无法再回归社会。西拉斯（尼古拉斯·霍尔特 Nicholas Hoult 饰）就是一名SOS症患者，某日，他邂逅了名为尼雅（克里斯汀·斯图尔特 Kristen Stewart 饰）的女孩，尼雅虽然看似冷漠无情，但实际上，她也患有SOS症，一切只不过是她的伪装而已。©豆瓣', '克里斯汀·斯图尔特', '德雷克·多雷穆斯', 6.4, 16346, 'tt3289728', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318849461.jpg', 2.6, 16.1, 48.6, 23.7, 9.1, '0.537396,0.367580,-0.679129,0.434999,-0.519984,0.245879,0.977497,0.055552,-0.826750,-0.326031,0.055512,0.843851,0.109780,0.232467,0.112013,0.072825,-0.047103,-0.488587,-0.032137,-0.120351,-0.400750,-0.343987,-0.396869,-0.387764,-0.376577,-0.786279,0.855021,0.204148,-0.578654,0.094603,-0.005874,0.727418,0.164931,0.525044,-0.065392,-0.147109,-0.028488,-0.294949,-0.031313,0.170973,-0.016683,-0.161760,0.180661,0.569447,-0.432174,0.407085,0.625172,-0.446838,-0.468208,-0.174313,0.747614,-0.321063,-0.313742,0.154912,0.410582,-0.175877,0.026053,0.303756,-0.313147,0.150576,0.095381,0.055841,-1.049490,0.021438,0.308634,0.453744,-0.399805,0.639786,0.172186,-0.468246,-0.090663,0.001723,0.219775,0.130347,0.393332,0.478223,-0.013162,-0.142321,-0.346491,0.009542,0.732491,0.199952,-0.962591,0.499530,-0.855354,-0.612806,-0.196396,-0.614762,-0.459944,-0.030081,0.169866,0.118803,-0.586701,0.800717,-0.561915,0.270250,-0.164502,-0.100144,-0.332811,-0.205526,-0.114635,-0.238451,-0.221128,-0.937756,-0.430803,-0.174093,0.039064,-0.342384,1.051573,-1.048854,0.125278,0.608722,0.292010,-0.581265,0.525893,0.200346,0.030687,-0.017659,-0.081370,0.677625,-0.138729,0.007140,-0.127902,0.297897,-0.224068,-0.007752,-0.264436,0.925843', '24284209', '26667010', '26386465', '27186354');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25775571', '人类清除计划2：无政府状态', '科幻', '2023年，美国新政府所推行的“人类清除计划”迎来了第六个年头。剑走偏锋的极端政策，旨在抑制持续上升的失业率和犯罪率，在此期间却也有越来越多的无辜之人遇害，而富人们则斟好杯中酒，脑满肠肥欣赏甚至以看似高贵优雅的姿态参与一年一度的屠杀狂欢。在大屠杀即将开始之际，面临分手的情侣谢恩（Zach Gilford 饰）和莉兹（Kiele Sanchez 饰）的车在路上抛锚，他们慌乱不安地寻找藏身之地。刚刚失去最重要亲人的伊娃（Carmen Ejogo 饰）及其女儿卡莉（Zoë Soul 饰）躲在家中亦难免厄运临头，关键时刻母女被逡巡在城市巷尾的中士（弗兰克•格里罗 Frank Grillo 饰）救下，与此同时谢恩和莉兹也阴差阳错搭上了中士的车。新仇旧恨以及对世界的各种愤懑不满，在这个夜晚集中爆发，脆弱的生命面临最惨烈的考验……©豆瓣', '弗兰克·格里罗', '詹姆斯·德莫纳克', 6.5, 47233, 'tt2975578', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2205028302.jpg', 2.5, 12.2, 52.1, 25.8, 7.4, '0.146766,0.012727,-0.644038,0.248591,0.042156,-0.086791,0.721929,0.290117,-0.151514,-0.030773,0.610193,0.546506,-0.244378,-0.083561,0.399163,-0.387989,-0.199815,-0.508288,-0.038550,-0.000913,-0.268623,-0.239067,-0.201058,-0.260540,-0.139905,-0.483093,0.501047,0.385675,-0.166434,0.502971,0.250689,0.439717,-0.229119,0.584297,-0.074768,-0.331063,-0.008701,-0.001902,-0.266571,-0.064646,-0.158351,-0.482367,-0.053225,0.179231,0.058014,0.335519,0.790031,-0.209813,-0.079107,-0.060551,0.373284,-0.335644,-0.130804,0.061441,0.368139,-0.139405,-0.138438,0.000029,-0.214638,-0.155426,0.038489,-0.052942,-0.716993,0.058404,0.280335,0.006218,-0.504032,0.566575,0.126181,0.116656,0.140102,-0.219486,0.236447,0.610885,0.032799,0.373408,-0.139836,-0.072672,-0.344169,0.033532,0.547310,-0.171156,-0.158112,0.159920,-0.347662,-0.274653,0.014579,-0.245086,-0.332630,-0.286834,0.264289,0.099163,-0.014514,0.507138,-0.616622,-0.011202,-0.131619,-0.201848,0.131493,-0.494341,-0.229047,-0.598875,0.046048,-0.305325,-0.152872,0.149829,0.149087,-0.053848,0.672132,-0.468564,0.251342,0.338878,0.246659,-0.486001,0.433960,0.068880,0.133500,-0.287106,-0.266718,0.634532,-0.001637,0.246626,-0.162970,0.143507,-0.338723,0.086446,-0.354475,0.433864', '21619567', 