INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25777330', '闺蜜', '喜剧', '希汶（陈意涵 饰）、Kimmy（薛凯琪 饰）和小美（杨子姗 饰）一直是无话不谈的闺蜜，三人大学毕业后开始了同居生活。乖乖女希汶的生活重心全放在了相爱7年的未婚夫林杰（钟汉良 饰）身上，可随着林杰的出轨，三姐妹的生活全被打乱了。无男不欢的白富美Kimmy和酷酷的小美不得不 全天候照顾因失恋而混乱的希汶，但是她们俩为闺蜜的两肋插刀都比不上暖男乔立（余文乐 饰）的出现。当希汶正为乔立的性取向怀疑时，Kimmy和小美却陷入了与摇滚音乐人九天（吴建豪 饰）的三角恋中，并随着九天赴欧洲的演唱会而变得白热化，希汶与Kimmy都不支持小美和九天的恋情，而且小美要坚持与九天一起去演唱会，就不得不放弃现有的副导演工作。三人的友情危机一触即发，小美最终会何去何从？导演黄真真也出演了本片，扮演了自己，并且还原了自己的纪录片代表作《女人那话儿》的拍摄现场。©豆瓣', '陈意涵', '黄真真', 5.3, 101531, 'tt4074114', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2188986448.jpg', 12.5, 29.2, 41.9, 12.2, 4.2, '0.204257,-0.202626,-0.659953,0.653087,0.074364,-0.379586,0.678613,0.284936,-0.295553,-0.052866,0.125566,0.570618,-0.371563,0.232396,0.406992,-0.072709,-0.242625,-1.130508,-0.294942,0.115022,-0.241410,-0.277898,-0.150176,-0.007748,-0.378744,-0.131503,0.712535,-0.046813,-0.082400,0.597145,0.490366,0.073711,-0.159405,0.479379,-0.008768,0.049923,-0.212584,0.244230,-0.438056,0.113384,0.164201,-0.099208,-0.039586,0.169671,0.257108,0.327591,0.759032,-0.188174,-0.044547,0.028920,0.455792,-0.238147,-0.232020,0.095956,0.256536,-0.064727,0.410591,0.201326,-0.292894,0.041953,0.033124,-0.041175,-0.648118,0.227252,0.162604,0.052384,-0.417679,0.562662,-0.125191,-0.176790,0.118919,-0.096647,0.331819,0.491104,0.387572,0.417995,-0.275143,0.078444,-0.286045,0.429672,0.748027,0.340120,-0.243324,0.547252,-0.024747,-0.347994,-0.319649,-0.059112,-0.521750,0.026498,0.026585,0.222488,-0.053174,0.196925,-0.740832,-0.141601,-0.039463,-0.160499,-0.048207,-0.625297,-0.051284,-0.631803,-0.386737,-0.643793,-0.172063,0.027058,0.110323,-0.250373,0.884780,-0.986482,0.110142,0.140249,0.224212,-0.685864,0.744309,0.371638,0.161153,-0.169353,-0.050103,0.021529,-0.242332,0.121994,0.241355,0.400811,-0.153038,-0.035597,-0.440636,0.345981', '4301278', '4127270', '26809007', '1826173');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25777512', '要听神明的话', '惊悚', '对当下的生活倍感无聊和失望的高中生高畑瞬（福士苍汰 饰），从没想到人生会发生如此可怕的巨变。课堂上老师的脑袋突然爆开，紧接着会说话的达摩不倒翁出现在讲桌上，逼迫着惊慌失措的学生们玩起了“一二三不许动”。经过数轮血腥较量，瞬成为班内唯一的幸存者，他跌跌撞撞逃出教室，遇到了也从死亡线上暂时逃脱的青梅竹马秋元依智香（山崎紘菜 饰）。两人在寻找出路时撞进了体育馆，谁知这里正是下一轮游戏的舞台。未过多久，巨大的招财猫（前田敦子 配音）出现，和幸存者们玩起了抓老鼠的死亡游戏。考量体力、智力和想象力的关卡连番到来，瞬、依智香还有周身散发着死神气息的天谷武（神木隆之介 饰）迎接着命运的巨变……本片根据金城宗幸（原作）、藤村绯二（作画）的同名漫画的第一部改编。©豆瓣', '福士苍汰', '三池崇史', 6.6, 42886, 'tt3354222', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2207809849.jpg', 2.3, 11.9, 49.3, 27.6, 8.8, '0.243233,0.007666,-0.653122,0.261926,0.137132,0.002641,0.689777,0.158886,-0.345228,-0.155565,0.424285,0.590736,-0.547405,0.251068,0.284262,-0.225673,-0.185502,-0.723741,-0.356403,0.019262,-0.282077,-0.119309,-0.107966,0.019777,0.023904,-0.435002,0.452608,-0.010706,-0.194278,0.516925,0.392110,0.072400,-0.326324,0.259398,-0.095552,0.050140,-0.153822,0.280675,0.023191,0.169660,-0.125378,-0.311423,-0.343631,-0.099141,-0.021441,0.116934,0.778789,-0.183007,-0.106393,-0.065164,0.388978,-0.167193,-0.211832,-0.026465,0.398813,0.165222,-0.040579,-0.012520,0.005466,0.214997,0.063874,-0.093165,-0.569661,0.042559,-0.229232,0.399252,-0.451323,0.183190,0.116722,-0.186040,0.276352,-0.163792,0.076414,0.254463,0.270247,0.186311,-0.425209,0.072604,-0.405851,0.160344,0.456740,-0.163278,-0.191026,0.245277,-0.106663,-0.306817,-0.198864,-0.078026,-0.259756,-0.349293,0.373032,0.149136,-0.268279,0.021252,-0.637527,0.102006,0.082787,-0.326370,-0.032584,-0.242102,-0.246842,-0.652483,-0.094590,-0.127989,-0.289127,0.179638,-0.013983,-0.229048,0.807248,-0.653212,0.163572,0.466378,0.258218,0.191462,0.389990,0.009712,-0.186537,0.042894,-0.017571,0.067331,0.042245,0.450810,0.166959,0.507631,-0.203031,-0.022660,-0.575821,0.489627', '3811356', '1307146', '5403927', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25777594', '暗金丑岛君2', '剧情', '在赤裸裸的物欲时代，人们为了名利吞噬缠斗，跌入深渊，而高利贷公司的社长丑岛馨（山田孝之 饰）则站在铁围山的顶端，冷冷注视着这群愚蒙众生。牛郎神咲丽（洼田正孝 饰）一心爬到俱乐部最顶端，他怂恿家境平庸的女孩彩香（門脇麦 饰）为其砸下黄金万两；小混混阿胜（菅田将晖 饰）偷盗机车惹上暴走族头头爱泽（中尾明庆 饰），为还债委身丑岛的公司，却又联合爱泽上演蛇吞象的戏码；有黑道背景的犀元茜（高橋メアリージュン 饰）操纵爱泽对抗丑岛，爱泽疲于奔命；在犀元下属公司贱卖苦力的蝦沼（柳乐优弥 饰）盯上彩香，他以跟踪者的身份迫近这个疲惫的女孩。巨大的绞肉机开始运转，所有人都被卷入其中……本片根据真锅昌平的同名漫画中的“ヤンキーくん編”和“ホストくん編”改编。©豆瓣', '山田孝之', '山口雅俊', 8, 7824, 'tt3357178', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2176802562.jpg', 0.6, 1.8, 22.9, 48.1, 26.7, '0.141794,-0.025865,-0.586564,0.406572,-0.163972,-0.021371,0.569552,0.463286,-0.011364,-0.131597,0.600521,0.480040,-0.145462,0.053060,0.337913,-0.047703,-0.042270,-0.563565,-0.287154,0.059017,-0.057513,-0.223148,-0.143810,-0.181460,-0.413337,0.069132,0.740576,-0.008353,-0.251842,0.191542,0.500281,0.531521,-0.252838,0.197144,-0.118305,0.035016,-0.135876,-0.037337,0.071467,0.031161,-0.477602,-0.371385,0.004011,-0.069340,-0.129786,0.204753,0.669268,-0.308009,0.243801,-0.393991,0.232733,-0.346679,-0.080008,-0.002876,0.234904,0.000482,-0.136955,0.091077,-0.266362,0.011281,0.160951,0.122071,-0.764927,-0.229813,0.286814,0.128224,-0.351996,0.359186,0.130251,-0.071421,0.069493,-0.033525,-0.198308,-0.022979,0.135504,0.266264,-0.019540,0.092701,-0.433798,0.223061,0.247151,0.025384,-0.098499,0.209782,-0.050669,-0.201558,0.001038,-0.326877,-0.388989,-0.505564,0.220447,-0.160808,0.160966,0.222002,-0.678176,-0.012917,0.023953,-0.100396,-0.046197,-0.306367,-0.258560,-0.434254,-0.141127,-0.340641,-0.026185,0.154453,0.201731,-0.243664,0.473712,-0.454793,-0.165643,0.624518,0.285761,-0.215906,0.476429,-0.292767,-0.035812,-0.106970,-0.449744,-0.006364,0.344932,0.325834,-0.066786,0.194945,-0.141925,-0.022934,-0.260435,0.340743', '6124043', '26759820', '25774050', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25777634', '托尔金', '剧情', '托尔金（尼古拉斯·霍尔特 Nicholas Hoult 饰）和弟弟在很小的时候就被亲人抛弃了，善良的神父弗朗西斯（科尔姆·米尼 Colm Meaney 饰）收留了无家可归的兄弟两人，他们从此便浸淫在浓厚的天主教文化之中。长大后的托尔金凭借自己的努力进入了一所贵族学校就读，在那里，他遇见了罗伯特（帕特里克·吉布森 Patrick Gibson 饰）、杰弗里（安东尼·鲍伊 Anthony Boyle 饰）和怀斯曼（泰·田纳特 Ty Tennant 饰）等同龄人，对于文学和艺术的热情让他们之间结下了深厚的友谊。与此同时，托尔金还遇到了自己的伯乐约瑟夫教授（德里克·雅各比 Derek Jacobi 饰），他在托尔金的身上看到了无穷无尽的可能性。©豆瓣', '尼古拉斯·霍尔特', '多姆·卡如库斯基', 6.9, 7745, 'tt3361792', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551115978.jpg', 1.1, 8.1, 48.2, 32.2, 10.4, '0.477421,-0.034185,-0.931728,0.631297,-0.163651,-0.588199,0.829601,0.224488,-0.608449,-0.141664,-0.026682,0.992319,-0.252118,0.145610,0.320167,0.019740,-0.463806,-0.899518,0.043440,-0.348799,-0.366204,-0.621986,-0.366012,-0.159160,-0.339667,-0.524613,0.328543,0.006767,-0.089725,0.580334,0.033154,0.454256,0.139403,0.355178,-0.325023,0.309991,0.278730,-0.004092,-0.109599,0.255924,0.308108,-0.027444,-0.011497,0.113345,0.085685,0.326193,0.554509,-0.331295,0.110982,0.071931,0.027760,-0.088086,0.032313,0.404627,0.287654,-0.180372,0.160284,0.333073,-0.300127,0.120243,0.026158,-0.193212,-0.626589,-0.041427,0.130892,0.162834,-0.907363,0.766511,0.035214,-0.355411,0.071877,-0.287810,0.100718,0.154147,0.138655,0.483213,0.077324,-0.115312,-0.509585,0.138821,0.416141,-0.009975,-0.225707,0.191627,-0.457653,-0.352711,-0.263721,-0.129104,-0.525592,-0.139300,0.565078,-0.109630,-0.077198,0.387168,-0.758906,-0.189613,-0.300428,0.017573,-0.085214,-0.416963,0.060018,-0.622195,-0.242501,-0.659593,-0.288162,0.105881,0.011292,-0.312952,0.976937,-0.880946,0.340612,0.384728,0.501860,-0.098176,0.780359,-0.113173,0.234314,-0.008185,-0.093157,0.374376,0.086900,0.252991,0.368109,0.556245,0.240749,-0.213742,-0.246387,0.733709', '30162520', '3111650', '1307146', '1303449');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25777636', '奇幻森林', '剧情', '茂密的原始森林中，生活着人类小孩毛克利（尼尔·塞西 Neel Sethi 饰）。因某种原因他很小就成为了孤儿，黑豹巴希拉（本·金斯利 Ben Kingsley 配音）最先找到了他，并将毛克利托付给狼族的首领阿克拉。从此以后，毛克利以狼的身份在森林里成长起来，和他的兄弟姐妹们学习捕猎和求生技巧。然而并非所有动物都接受毛克利的存在，特别是曾被人类伤害的老虎谢利·可汗（伊德里斯·艾尔巴 Idris Elba 配音），更将男孩视为眼中钉肉中刺。谢利·可汗向狼族发出威胁，众狼们不得不为族群的命运做出考量。毛克利不希望“家人”为难，他选择离开狼群，而唯一陪伴他的巴希拉则希望带着男孩回归人类世界。即便如此，谢利·可汗也绝不肯善罢甘休，他对男孩展开了无休止的追杀……©豆瓣', '尼尔·塞西', '乔恩·费儒', 7.8, 249931, 'tt3040964', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2326337223.jpg', 0.3, 2.1, 26.2, 49.6, 21.8, '0.103739,0.017410,-0.578936,0.568539,-0.146112,-0.324296,0.682548,0.035088,-0.273139,-0.139336,-0.068812,0.468260,0.335006,-0.100028,0.055610,-0.011912,-0.265858,-0.492171,-0.112663,0.081489,-0.243592,-0.407026,-0.261869,-0.578968,-0.161045,-0.237150,0.628950,-0.211246,-0.155062,0.219658,0.196866,0.277585,0.043664,0.351203,-0.046324,0.082086,-0.054438,-0.224853,-0.174263,0.021353,-0.196016,0.157354,-0.151008,0.380510,-0.151849,0.192202,0.614871,-0.820396,0.050411,-0.790258,0.056317,-0.460934,0.056327,0.102892,0.346235,-0.396888,0.240380,0.271644,0.231008,0.051307,0.052440,-0.046772,-0.648768,-0.083431,0.148344,0.492373,-0.615471,0.221705,-0.128504,0.116190,0.280721,-0.463310,-0.100652,0.256363,0.338029,0.161310,-0.213194,0.115892,-0.683055,-0.289806,0.571550,-0.206405,-0.274946,-0.194950,-0.395845,-0.457268,0.178958,-0.125987,-0.657378,-0.245543,0.186239,0.079936,-0.275118,0.623352,-0.649365,-0.366878,-0.278537,-0.262814,0.072229,-0.627659,0.024367,-0.178337,-0.016389,-0.357734,-0.221097,-0.068891,0.238064,-0.399849,0.753708,-0.790701,0.442300,0.520512,0.546169,-0.161615,0.494491,-0.047369,0.393123,-0.272985,-0.013743,0.705500,0.354073,0.049965,0.247377,0.049315,0.177127,-0.107223,-0.261181,0.540500', '3012819', '6974439', '1305071', '25786060');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25777784', '再见歌舞伎町', '剧情', '故事发生在车水马龙灯红酒绿的歌舞伎町，高桥彻（染谷将太 饰）是当地一间情人旅馆的店长，然而他对外却宣称自己在高级酒店工作。高桥彻的女友饭岛沙耶（前田敦子 饰）希望能够进军音乐圈，无奈一直等不到合适的机会。美优（樋井明日香 饰）是阿彻的妹妹，拥有着美丽外貌的她隐藏了一个不可告人的秘密。铃木里美（南果步 饰）在情人旅馆里担任保洁员的职务，而他的丈夫却是池泽康夫（松重丰 饰）却是一名只能隐藏在阴影之中等待诉讼时效过期的逃犯。刑警新城龙平（宫崎吐梦 饰）一直以来都在追查池泽康夫的案件，与此同时，他亦陷入了和搭档藤田里香子（河井青叶 饰）的不伦之恋中。©豆瓣', '染谷将太', '广木隆一', 7.5, 8124, 'tt3876372', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2262112267.jpg', 0.4, 3.1, 33.8, 48, 14.7, '0.246150,0.141978,-0.500104,0.521378,-0.038376,0.038247,0.869821,0.349897,-0.496522,-0.400611,0.388583,0.482003,0.058128,0.289482,0.129722,0.184197,-0.318586,-0.730234,0.078575,-0.361034,0.004849,-0.419982,-0.368978,-0.090273,-0.288627,0.003745,0.750922,0.162853,0.036562,0.111354,0.520019,0.292009,-0.402295,0.357474,-0.065243,-0.094515,0.342533,-0.037068,-0.101887,0.316287,-0.292192,-0.406333,0.041892,0.199821,0.250705,0.432879,0.752931,-0.189909,-0.146556,0.125610,0.063293,0.055403,-0.081437,0.226175,0.440362,-0.225768,0.300927,0.267818,-0.554172,0.055303,0.171539,-0.037303,-0.706013,-0.088772,0.367367,0.522723,-0.394046,0.495283,-0.125522,-0.190014,0.256727,-0.358066,0.096905,-0.020212,0.236537,0.296366,-0.238067,0.236473,-0.318403,0.363404,0.304807,-0.042974,0.056705,0.346905,-0.292726,-0.442676,-0.506208,0.033773,-0.588162,-0.331808,0.047631,-0.056179,-0.064934,-0.095342,-0.591366,-0.101696,-0.008356,-0.102527,0.055191,-0.250834,-0.107211,-0.600307,0.246371,-0.494502,-0.289297,0.242273,0.151795,-0.131102,0.517625,-0.937304,0.076742,0.689313,0.165121,-0.262355,0.575948,0.123387,0.202632,-0.145958,-0.205023,0.340180,-0.088092,0.230839,0.057355,0.441404,-0.113235,-0.210979,-0.562656,0.215767', '1417036', '3033092', '1436998', '5416009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25778483', '消失的凶手', '动作', '银行相继倒闭，大批失业游民流落街头。一连串离奇自杀案件仿佛指引着松东路去探究隐藏在其背后更大的黑幕。十年前被掩埋的屠村案件被揭开、疑犯通过文字游戏传递着口令，接踵而至的案件掀起了巨大的恐慌，城中风云攒动，人人自危，富商、警察、教授、学生……每个人的言行举止都充满疑点，而每个人都在猜测下一个离奇自杀的会不会是自己？究竟是谁密谋了这一切，让这个原本美好的地方变成了绝望之城？寻找真相迫在眉睫……', '刘青云', '罗志良', 5, 31621, 'tt5190950', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2284651956.jpg', 15.8, 34.3, 37.7, 8.7, 3.4, '0.321497,-0.140909,-0.819829,0.290199,0.000750,0.451824,0.886900,-0.092962,-0.509922,-0.201620,0.350582,0.613417,-0.309396,0.305907,-0.022289,0.029562,-0.294175,-0.700883,-0.312683,-0.472916,-0.325726,-0.330207,-0.239846,-0.530087,0.032231,-0.048713,0.250620,0.529447,-0.238377,0.292796,0.511458,0.552097,-0.577524,0.634426,0.010594,0.078906,0.242023,-0.019552,0.058065,-0.125649,-0.085350,-0.610654,-0.121679,0.247887,-0.392636,0.478199,0.658905,-0.115204,-0.257772,0.049321,0.437387,-0.622528,-0.151420,0.231646,0.355313,0.096406,-0.103232,0.405567,-0.443940,-0.249024,0.048463,0.287680,-0.707140,-0.222728,0.305422,0.423225,-0.504481,0.115722,0.161975,0.030084,0.020823,-0.245223,0.561964,0.241080,0.238607,0.146215,0.159953,-0.336845,-0.612980,0.315112,0.911275,-0.170879,-0.405322,-0.278368,-0.273831,-0.153734,-0.153348,-0.068998,-0.382781,0.142255,0.516102,-0.000309,-0.336342,0.597124,-0.271771,0.032021,-0.286998,-0.400442,-0.263582,-0.400842,-0.395585,-0.472809,-0.233264,0.071676,-0.467634,0.173348,0.099626,-0.165782,0.540246,-0.538052,0.100138,0.850964,0.081472,-0.519228,0.147782,-0.180585,0.043362,-0.002368,-0.210006,-0.109972,0.157896,0.701074,0.067549,0.205323,-0.214870,-0.105376,-0.420361,0.422740', '1309116', '2073674', '1294941', '3312344');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25778488', '宅女侦探桂香', '喜剧', '桂香（王珞丹 饰）从小就显现出了远高于常人的智商，年仅十三岁就凭借着自己的逻辑推理帮助警方破获了重大案件，由此一发不可收拾，最终成为了声名远扬的天才名侦探。然而，看似无懈可击的桂香却有着一个致命的缺陷——超低的情商。桂香一辈子都受低情商的拖累，并且最终因此而遭到了男友的抛弃。桂香无法走出过去感情的阴影，沉溺于悲痛和自己的世界之中无法自拔，就在此时，一起碎尸案的发生吸引了桂香的注意使其再度出山，可半路杀出的可恶刑警阿哲（周瑜明 饰）却一次又一次的扰乱着桂香的思绪，仿佛故意和她作对。不服输的桂香将阿哲当做了强劲的竞争对手，两人你争我赶，誓要找到杀人凶手。©豆瓣', '王珞丹', '彭顺', 4.3, 24510, 'tt4819586', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2259115438.jpg', 27.3, 40.9, 25.6, 4.2, 2, '0.296513,0.214647,-0.693375,0.679640,-0.319956,-0.290235,0.633917,0.179832,-0.351987,-0.079280,0.119623,0.477936,-0.036748,0.121179,0.020991,-0.247235,0.131851,-0.837007,-0.061629,-0.166824,-0.212111,-0.347695,-0.356707,0.088330,-0.194119,-0.220960,0.497679,0.216734,-0.492096,0.357334,0.267460,0.148135,-0.120067,0.681805,-0.032705,0.158435,0.006022,-0.072928,-0.072360,0.193330,0.183752,-0.319216,-0.013561,0.095477,-0.316667,0.246614,0.606019,-0.258785,-0.154561,-0.033886,0.491549,-0.428438,-0.241127,0.108192,0.315516,-0.142724,-0.056832,0.127135,-0.157531,0.019800,0.168496,0.054080,-0.771327,0.159118,0.202427,-0.138688,-0.556386,0.310812,-0.009947,0.049193,-0.067107,-0.030826,-0.006666,0.103739,0.300422,0.308407,-0.418200,0.055507,-0.499929,-0.057616,0.669241,0.012344,-0.366746,0.115690,-0.182567,-0.295380,-0.145315,-0.430464,-0.337658,0.088931,0.460920,0.177777,-0.342989,0.311935,-0.489644,-0.101637,-0.357558,0.124553,-0.175021,-0.534091,-0.148081,-0.197216,-0.219471,-0.488094,-0.331242,0.084729,0.116250,-0.384497,0.596687,-0.622902,0.107993,0.500771,0.045033,-0.529882,0.477823,-0.069017,0.023178,-0.106023,-0.073732,0.108124,0.057067,0.266911,0.239426,0.326756,-0.149797,-0.158956,-0.338391,0.422967', '1301022', '1917313', '30163500', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25779217', '诛仙1', '爱情', '草庙村被屠，少年张小凡双亲离世，被青云门大竹峰收留。机缘巧合之下，他习得佛门天音功法，又意外获得魔教法器烧火棍，踏上强者之路的同时，也让他陷入了巨大的危机。至魔法器的现世，与陆雪琪、碧瑶、田灵儿三个女生间命运的交错，都让他原本单纯的人生轨迹充满变数。一个勇者驳斥命运的传奇之旅就此展开......', '肖战', '程小东', 4.5, 643276, 'tt9680630', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2567346094.jpg', 39.8, 23.7, 18.9, 8.1, 9.5, '0.226713,0.366169,-0.431272,0.781929,0.214957,-0.302367,0.477348,0.085175,-0.288289,-0.228476,0.471655,0.881067,-0.114934,0.220343,0.142282,-0.184600,0.188538,-0.558445,0.132349,-0.143680,-0.289486,0.259051,0.144543,0.254075,-0.205549,-0.481650,0.920300,0.382176,-0.306209,0.112219,-0.051556,0.399379,-0.362557,0.326539,-0.302978,0.248283,0.061404,0.174495,-0.373401,0.259841,-0.333466,-0.364908,-0.131570,0.666731,-0.867395,-0.012579,0.731554,-0.228874,0.028982,-0.339085,0.077413,-0.011547,-0.486846,-0.006513,0.479074,0.238959,0.029255,0.257546,-0.092194,0.119647,0.133288,-0.052292,-0.715927,0.123248,0.169030,-0.106300,-0.139369,0.273542,0.083284,0.071415,-0.162153,-0.462388,-0.074923,0.159300,0.465897,0.264877,-0.535032,-0.131325,-0.384737,0.131918,0.794147,-0.218098,-0.126974,0.190785,-0.103742,-0.386791,-0.219277,-0.432577,-0.373574,-0.057640,0.713051,0.125037,0.042806,0.744865,-0.716499,0.222568,-0.326691,0.341605,-0.288739,-0.396792,-0.239619,-0.392546,0.070316,-0.071563,-0.619315,0.010043,0.140111,-0.181831,0.800108,-0.408235,0.345426,0.273944,0.017234,-0.244731,0.675373,-0.118358,0.323248,-0.306167,-0.136123,0.429552,-0.157666,0.754365,0.214308,0.160816,-0.166248,0.294711,-0.110704,0.509627', '3001114', '26290398', '26667010', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25779218', '匆匆那年', '爱情', '时光流转，曾经美好的青春时代有如一场不真实的梦。她充满躁动、喜悦、悲伤与愤慨，她是远离着社会现实尔虞我诈的青春懵懂，傻了傻气的纯真涂抹下最为亮丽耀眼的色彩。而今回首往事，即使如梦般虚幻，却又让人唏嘘不已，感慨万千。只因偶然的机缘，早已过了而立之年的陈寻（彭于晏 饰）回想起那个曾经呼喊过千遍万遍的名字。遥远的学生时代，陈寻与让他心动的女孩方茴（倪妮 饰），以及乔燃（魏晨 饰）、林嘉茉（张子萱 饰）、赵烨（郑恺 饰）等一般死党行走在尘土飞扬的校园里。友情、爱情在诸多禁忌的年代里如野草般自由疯长，曾经那是他们所坚守笃定的一切，而这些又都被碾压得支离不堪。许下的誓言你还记得吗？本片根据九夜茴的同名小说改编。©豆瓣', '彭于晏', '张一白', 5.6, 260045, 'tt4284020', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2212273919.jpg', 10.9, 25.4, 42.6, 15, 6.1, '0.193998,0.188173,-0.716508,0.626089,-0.156551,-0.215306,1.041120,-0.106822,-0.460275,-0.126399,0.153185,0.393437,-0.351673,0.468636,0.004880,0.163621,-0.096988,-0.662637,-0.114402,-0.349246,0.243163,-0.326500,-0.331286,0.152661,-0.105134,-0.286513,0.755914,0.326128,-0.129833,0.374778,0.181799,0.078951,-0.300561,0.554866,-0.289765,0.120294,-0.226555,0.575283,-0.278299,-0.441531,-0.089126,-0.316496,-0.220461,0.275966,-0.486067,0.158627,0.615377,-0.394597,-0.217285,0.072213,0.495430,-0.082963,-0.077823,0.214549,-0.131923,0.016803,0.254913,0.040431,-0.094092,0.081338,-0.130607,0.132048,-0.716018,-0.057087,0.260862,0.179296,-0.508492,0.629543,0.036344,-0.066077,0.243971,-0.170442,0.200347,-0.116694,0.518418,0.687809,-0.169418,-0.166848,-0.327308,0.705793,0.592114,0.243361,-0.457991,0.606056,-0.553438,-0.285848,-0.216916,0.025721,-0.794549,0.159932,0.138180,-0.048150,-0.178418,0.528585,-0.573145,0.182447,0.084587,-0.039085,-0.164183,-0.400736,-0.329135,-0.165279,-0.226153,-0.717327,-0.425096,-0.063073,0.150861,-0.287731,0.737813,-0.699284,0.345369,0.363913,0.009283,-0.208225,0.344405,0.209593,-0.169448,-0.091530,-0.047772,0.677562,-0.221688,0.219878,0.045333,0.348175,-0.305093,0.107533,-0.545701,0.673321', '2131640', '1417428', '1296992', '1303077');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25780578', '好朋友们', '剧情', '17年前，三个好朋友相约上山，不料遭遇意外，被困雪山，幸好最终成功获救。自此三人成为生死之交，多年来感情深厚。泰贤（池晟 饰）是个兢兢业业具有正义感的消防员，与妻女过着清贫而和美的生活；仁哲（朱智勋 饰）就职于保险公司，为人聪明机灵，常常投机取巧；民洙（李光洙 饰）是三人中混得最不济的，经营着自己的小生意，平日很依赖这两位好朋友。为了骗取高额保险金，仁哲联合了泰贤的母亲，策划了一起抢劫纵火案件。素来胆小怕事的民洙被仁哲说服，也参与了这起案件。然而事情并没有按照计划进行，悲剧接连发生。三个好朋友，共同卷入了这起悲剧的漩涡中心。©豆瓣', '朱智勋', '李道允', 7.6, 26079, 'tt3957986', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2187159568.jpg', 0.5, 2.5, 30.2, 48.9, 17.9, '0.155520,-0.316524,-0.604284,0.534180,-0.075824,-0.099840,0.608584,0.117817,-0.646664,-0.477531,0.002993,0.582068,-0.018743,0.010764,0.234065,-0.147847,-0.123024,-0.662860,-0.155198,-0.052152,-0.169229,-0.534034,-0.148228,-0.290843,-0.327207,-0.260297,0.370030,0.175481,0.043938,0.592459,0.367573,0.264048,-0.379799,0.237501,-0.105194,-0.006212,0.048858,0.372258,-0.546887,0.122977,-0.169980,-0.201495,-0.103278,-0.011089,0.227250,0.432606,0.545136,0.055005,-0.494204,-0.098907,0.188810,-0.391666,-0.071808,0.103520,0.548080,0.166460,0.401127,0.530042,-0.290069,-0.097264,0.105537,-0.249912,-0.891751,0.028496,0.379007,-0.273277,-0.590811,0.464279,0.161208,-0.231708,-0.060571,-0.242794,0.116908,0.500252,0.482807,0.023069,-0.071852,0.206352,-0.362349,0.244082,1.036466,-0.028755,-0.139358,0.320265,-0.110503,-0.326784,0.134194,-0.429809,-0.182062,0.240579,0.110212,-0.171035,-0.149624,0.271957,-0.520198,0.127270,-0.188743,0.150139,0.096930,-0.386668,0.148381,-0.388325,-0.218196,-0.379363,-0.655272,0.152854,-0.217223,-0.385952,0.661540,-0.777882,0.128869,0.470182,0.179692,-0.790159,0.621836,0.225344,0.189632,-0.154194,-0.066724,-0.056318,0.023394,-0.094031,0.148535,0.026769,-0.065117,-0.275375,-0.259615,-0.035917', '26678784', '1877596', '1293265', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25780584', '我是女王', '剧情', '安妮（宋慧乔 饰）、康蒂（陈乔恩 饰）和缇娜（邬君梅 饰）是结识多年的好姐妹，彼此之间感情十分要好。安妮和张毅（秦昊 饰）交往多年，然而，梅丽莎（伊能静 饰）的出现却让两人的爱情产生了裂痕，最终，张毅抛弃了安妮。梅丽莎不仅抢走了安妮的恋人，更是在工作中对安妮处处使绊，导致安妮的事业落入了低谷，与此同时，康蒂同男友托尼（杨佑宁 饰）、缇娜同男友家伟（姜武 饰）这两对恋人的感情亦走入了瓶颈。之后，安妮遇见了善良单纯的马克（窦骁 饰）和充满了贵族气质的富二代王子煜（郑元畅 饰），在感情中兜兜转转找不到方向的安妮最终明白，这个世界上能够依靠的，只有自己。©豆瓣', '宋慧乔', '伊能静', 4.2, 19032, 'tt4483422', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2235582204.jpg', 35.3, 32.4, 23.1, 5.9, 3.3, '0.356284,-0.078046,-0.502164,0.588855,0.080718,-0.404268,0.812339,0.253611,-0.382829,-0.039023,0.214582,0.748438,-0.413008,0.311408,0.313052,0.322385,-0.387678,-0.688767,0.323842,-0.254536,-0.084772,-0.485524,-0.398546,0.121433,-0.248614,-0.254483,0.788484,-0.352711,-0.053459,0.629761,0.269355,0.237427,0.005666,0.426167,0.171908,0.293279,0.250373,0.119816,-0.443000,0.153356,0.095213,0.050214,0.130710,0.247606,-0.092741,0.344767,0.727348,-0.446708,0.213642,0.027572,0.358014,-0.090115,0.112968,-0.036364,0.165266,-0.212813,0.386862,0.114602,-0.227510,0.070471,0.424469,0.010215,-0.321576,0.164609,0.164819,0.090665,-0.694257,0.699647,0.160560,-0.190086,0.185117,-0.258721,0.078972,0.293400,0.262292,0.126714,-0.297410,0.178822,-0.231381,0.070630,0.380676,0.133661,-0.184330,0.648847,-0.378390,-0.337756,-0.144261,-0.064742,-0.619742,-0.198152,0.462943,0.261053,-0.029446,0.312068,-0.708077,-0.081806,-0.310501,0.373759,0.200518,-0.626774,-0.119296,-0.592525,-0.428419,-0.933484,-0.606263,-0.103634,-0.160381,-0.281268,0.602664,-1.075447,-0.057977,0.376464,0.283544,-0.432523,0.673444,0.232464,0.032115,-0.243495,-0.132240,0.387335,-0.442749,0.039675,0.185829,0.287610,-0.067731,0.045052,-0.294197,0.381209', '21766698', '1292219', '26354526', '24839498');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25782633', '名侦探柯南：异次元的狙击手', '动画', '风和日丽的一天，铃木财团巨资营建的铃木塔举行了盛大的开幕典礼。柯南（高山南 配音）和好朋友们自然受邀参观。谁知一名游客突然被远处建筑发射来的子弹狙击身亡，柯南锁定凶手果断展开追击，然而对方胆大非常，公然炸毁拦截他的警车，在重重包围中脱身而去。在此之后，FBI和日本警方组成联合调查总部，经朱蒂•斯泰琳（一城美由希 配音）介绍得知，嫌疑人很可能是原美国海豹突击队狙击手蒂莫西·亨特。战功显赫的亨特曾经获得过银星勋章，但是后来被战友指控违反交战原则，射杀了手无寸铁的平民，此后他更在战场上遭遇影响毕生的创痛，人生也彻底跌入低谷。此番他以神秘狙击手的出现，显然是想想那些毁灭了他的人生的人们复仇。狙击事件接连而起，全东京陷入莫大的恐慌之中……©豆瓣', '高山南', '静野孔文', 6.9, 56936, 'tt3455204', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173344236.jpg', 1.4, 8.8, 46.5, 29.5, 13.9, '0.178432,-0.173273,-0.652354,0.482317,-0.019234,0.069920,0.424681,-0.068057,-0.383786,-0.162639,0.479357,0.649957,0.023438,0.043054,0.330223,-0.267923,-0.234758,-0.588781,-0.212884,-0.190287,-0.319643,-0.451777,-0.300678,-0.289848,0.117131,-0.153269,0.654133,0.173363,-0.365024,0.499815,0.180026,0.501628,-0.054361,0.570604,0.035453,-0.014472,0.195823,-0.166441,-0.212615,0.298825,-0.428524,-0.332854,-0.060678,0.244431,-0.040838,0.438262,0.490920,-0.221861,-0.035913,-0.244527,0.370751,-0.389616,0.010014,0.157653,0.543605,0.169248,-0.014198,0.090268,-0.174287,-0.100129,-0.119543,0.026426,-0.631657,0.032013,0.005718,-0.127830,-0.421127,0.387489,-0.039649,0.189022,0.008973,-0.042819,0.250416,0.369081,0.262357,-0.133531,-0.250293,0.043879,-0.422209,0.211952,0.852390,-0.232199,-0.175315,-0.199904,0.007174,-0.442226,0.006881,-0.274682,-0.207034,-0.066386,0.517083,-0.037409,0.017352,0.238147,-0.486934,-0.060361,-0.522231,-0.332484,-0.232235,-0.240739,-0.181325,-0.856539,-0.018037,-0.060814,-0.347579,0.120490,-0.054996,-0.088539,0.636950,-0.832192,0.083508,0.605612,0.332665,-0.322664,0.377950,0.068783,0.046550,-0.034677,-0.184961,0.359739,0.385119,0.460155,0.010685,0.018868,-0.179909,-0.270125,-0.251452,0.208212', '2369613', '11541282', '5157137', '1306723');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25783914', '舞出我人生5', '剧情', '歌舞片《舞出我人生5》定档2014年7月25日，第五部的主演是《舞出我人生4》男主角瑞安·古兹曼，以及《舞出我人生2》的女主角布莱恩娜·伊维根。另外，片方宣布在前几部中的主演们也会有人回归，具体的演员表还待进一步确定。', '瑞安·古兹曼', '翠西·西埃', 6.4, 8964, 'tt2626350', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2208462295.jpg', 2.4, 15.1, 50.5, 22, 9.9, '-0.532572,-0.367737,-0.263619,0.365520,0.540445,-0.011158,0.142865,-0.203902,-0.109732,-0.010844,0.050094,0.582754,-0.433482,0.460939,0.806779,0.031960,-0.833588,-0.665347,-0.032406,-0.179146,-0.143757,-0.231813,-0.006053,-0.216690,0.040250,-0.290041,0.870254,0.011487,0.081033,0.233678,0.515605,-0.070080,-0.274039,0.159733,0.368739,0.651640,0.017090,-0.122429,-0.488415,0.430676,0.158516,-0.225214,-0.253177,-0.019901,0.287849,0.242521,0.526099,-0.264731,0.136689,0.180192,0.904928,0.008870,-0.092368,-0.290820,-0.065629,-0.131737,0.136691,0.552987,-0.195783,-0.065115,-0.515829,-0.642673,-0.664387,0.140402,-0.142500,-0.082613,-0.433614,0.301735,-0.066013,0.145290,0.112215,-0.043455,0.073830,0.362648,0.385683,-0.009760,-0.048786,-0.255361,-0.151306,0.732228,0.554004,0.127276,-0.227006,0.460208,0.234507,-0.595129,-0.789745,0.055159,-0.439101,0.201294,0.290322,0.077235,0.040373,-0.084960,-0.115318,-0.113654,-0.110513,-0.180881,0.115946,-0.162731,-0.035865,-0.556964,0.151580,-0.244385,-0.170265,-0.247146,0.084112,-0.446980,0.540235,-0.653264,0.364043,0.390895,0.268253,-0.157832,0.767498,0.070715,0.116796,-0.132457,-0.078488,0.643964,-0.134545,0.039669,0.208891,0.055391,0.307999,-0.130266,-0.098552,0.241196', '30397916', '3275168', '1293692', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25785124', '盲视', '剧情', '《八月三十一日，我在奥斯陆》的金奖编剧艾斯基佛格，今年首执导演筒长片作品《盲》，一鸣惊人横扫国际各大影展，拿下柏林影展最佳欧洲电影奖、日舞影展世界电影单元最佳剧本奖，以及入围挪威奥斯卡七项大奖。透过独特的叙事结构与影像魅力，捕捉盲眼女主角内心的脆弱与偏执。 最近失明的英格丽 几乎足不出户，尽管失去了视力，但她的心与想像力仍旧清晰而活跃，但恐惧却让她在自己的内在世界，书写出另一个人生剧本。 她时常幻想外出上班的丈夫偷溜回家，观察她在家中的一举一动，或是在网路上认识了一名单亲妈妈，偷偷与她约会；英格丽看见他们在餐厅里谈笑着，突然间，女子失去视力... 而察觉到异样的丈夫不久和女子分手，但她却说自己怀孕了，还挺着大肚子到派对上找他对峙。正当女子一身滑稽的礼服成为众人的笑柄，英格丽仿佛走进自己的幻想世界，化身成穿着礼服的女子和丈夫对峙着...', '艾伦·多丽特·彼得森', '埃斯基尔·沃格特', 7.4, 15428, 'tt2616810', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2194650504.jpg', 1.1, 4.5, 33.8, 45.4, 15.2, '-0.154992,0.126315,-0.833628,0.507335,-0.106807,-0.164267,0.748368,0.165292,-0.385163,-0.227924,0.147313,0.947475,-0.447609,0.317132,0.384167,0.136210,-0.365328,-0.805732,-0.112081,0.011802,0.031777,-0.122757,-0.383904,-0.056188,-0.020141,-0.534980,0.708120,-0.021947,-0.356533,0.383988,0.353834,-0.068038,-0.237380,0.470931,-0.205540,-0.179372,0.089897,0.135811,-0.136547,0.280619,0.029416,-0.216227,-0.399382,0.181053,-0.177530,0.259217,0.751901,-0.196852,-0.193714,0.264843,0.632582,-0.214924,-0.106623,0.028423,0.143941,0.024481,0.304232,-0.159791,-0.036146,0.103406,-0.014406,-0.123638,-0.407460,0.184610,0.153632,0.293851,-0.432570,0.428975,-0.244150,-0.014521,0.150373,-0.223939,0.187272,-0.015030,0.155127,0.383955,-0.185633,0.063606,-0.605285,0.351214,0.335297,0.101773,-0.416521,0.354917,-0.282774,-0.426286,-0.198903,-0.215052,-0.560987,-0.025132,0.226806,-0.034191,-0.137334,0.040390,-0.342812,0.163445,0.080571,-0.098180,-0.078419,-0.320698,-0.072029,-0.793301,-0.192900,-0.233286,-0.262492,-0.164614,0.081943,-0.297724,0.630604,-0.720017,0.257164,0.447345,0.272493,-0.250735,0.944441,0.008065,0.041685,-0.316465,-0.230281,0.382041,-0.180578,0.001323,-0.197661,0.451430,-0.153566,0.143382,-0.685417,0.660955', '1294565', '301