INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25785314', '爸爸去哪儿', '喜剧', '一部父子亲情真人秀《爸爸去哪儿》，在中国掀起收视狂潮和广泛热议。明星爸爸们的舐犊情深，和萌娃们天真可爱的俏皮模样，给观众留下了深刻的印象。2014年伊始，该档真人秀强势走上了大银幕。此次外景地挪到了广州长隆野生动物园林志颖、田亮、王岳伦、张亮和郭涛，带着他们的小宝贝小小志、田雨橙、王诗龄、张悦轩和郭子睿来到了这片野生动物的王国。在代理村长李锐的安排下，大人和孩子开始他们新一轮的任务，比如父子合作叉烧包、清理大象粪便、帮河马刷牙、去蟒蛇窝里找食材。惊险刺激之余，他们也与可爱的动物亲密接触。父亲们爽朗的笑声，孩子们无邪的笑脸，印刻在每一个人的脑中……©豆瓣', '林志颖', '谢涤葵', 5.8, 87836, 'tt4542658', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165007211.jpg', 15.3, 17.6, 37.9, 18.7, 10.5, '0.183889,-0.165335,-0.539530,0.410156,-0.089933,-0.045454,0.524969,0.330859,-0.334800,0.280866,0.045663,0.704980,-0.273817,0.347711,-0.068405,-0.078991,-0.503162,-0.493229,-0.265145,-0.000918,-0.008818,-0.141932,-0.213635,-0.167957,0.183905,0.042407,0.223558,-0.236301,0.000541,0.805809,0.338315,-0.142704,-0.473689,0.332124,-0.175267,0.323458,0.070465,0.055909,-0.168695,-0.114116,-0.068219,-0.014615,-0.360844,-0.092418,0.185238,0.182304,0.821342,-0.147483,-0.155148,-0.097118,0.284213,-0.360256,0.019926,0.099101,0.285568,-0.033495,0.549116,0.013677,0.073162,0.087048,0.029375,-0.259856,-0.425975,0.110919,-0.085708,0.125118,-0.591649,0.553046,0.085255,-0.023174,0.416518,-0.536055,0.230763,0.218528,-0.167931,0.602539,-0.100307,0.377165,-0.077039,0.343922,0.644041,0.080757,0.114722,0.009516,-0.002135,-0.455044,-0.020645,-0.185604,-0.421251,0.010027,0.502624,-0.214812,-0.288118,0.197846,-0.910776,0.078024,0.088110,-0.290058,0.058238,-0.300330,-0.088098,-0.761492,-0.200105,-0.530127,-0.189714,-0.085754,0.164313,-0.152708,1.000609,-0.699939,0.091713,0.248823,0.290177,-0.422996,0.607952,-0.075389,-0.025619,-0.194904,0.064561,-0.378061,-0.067930,0.205715,0.334647,0.483493,-0.145830,-0.058959,-0.453593,0.211587', '3811356', '4181031', '5403927', '3041753');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25785807', '死亡之雪2', '喜剧', '噩梦一般的雪山之旅，马丁（Vegar Hoel 饰）的女友和伙伴们全部被复活的纳粹僵尸屠杀殆尽。他虽然身受重伤，但是侥幸逃脱，然而却又因涉嫌杀害同伴被警方监控起来。更糟糕的是，自以为是的医生将他被僵尸病毒感染的右臂缝了起来，无法控制的屠杀在所难免。另一方面，复活的纳粹海军指挥官赫尔佐格（Ørjan Gamst 饰）带领部下暗夜前行，正秘密进行他们生前未尽的计划。马丁连杀两人，从医院逃脱，他根据一个小孩的建议打电话从美国请来了三个死宅组成的僵尸小队，试图消灭纳粹僵尸。逃亡途中，他也发现了赫尔佐格接下来的企图。争分夺秒，生死时速，纳粹僵尸的屠杀脚步能否中止……©豆瓣', '爱丽达·阿察瑞儿', '托米·维尔科拉', 7.1, 18736, 'tt2832470', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2198580186.jpg', 1.9, 6.7, 38.4, 40.1, 13, '0.139477,-0.186555,-0.460814,0.313977,-0.152323,-0.105466,0.918925,-0.236406,-0.312168,-0.138718,0.410063,0.504327,0.054417,-0.119621,0.035433,-0.183380,-0.211635,-0.562961,-0.211446,0.211393,-0.464096,-0.155441,-0.323151,-0.312356,0.192696,-0.329218,0.788922,0.270956,-0.179330,0.370209,0.201769,0.353107,-0.209017,0.351498,-0.189386,0.164825,0.227975,-0.558439,0.034147,0.290973,-0.074195,-0.336077,0.016289,0.397098,-0.343631,0.491959,0.857331,-0.226591,-0.007391,-0.313642,0.052749,-0.792149,-0.045013,0.226277,0.595129,0.171087,0.146700,0.181756,0.243140,-0.069324,-0.002373,0.267845,-0.937556,0.085501,-0.009804,0.215552,-0.546387,0.265928,-0.137907,0.688398,0.110621,-0.127497,0.051786,0.450753,0.080595,0.230303,-0.150821,-0.139581,-0.900748,0.198143,0.686490,-0.387492,-0.157174,0.025956,-0.127738,-0.345124,0.076814,-0.192039,-0.089363,-0.204286,0.633633,0.012585,-0.507119,0.340002,-0.598925,-0.254978,-0.573004,-0.197897,-0.474208,-0.305214,-0.013354,-0.671856,-0.030803,0.093856,-0.132591,0.110459,0.048331,-0.153659,0.639679,-0.556484,0.234131,0.727932,0.309309,-0.475057,0.147941,0.110849,0.187384,0.028724,0.080963,0.354770,0.439872,0.594086,0.523907,0.305865,-0.112257,-0.280969,-0.381775,0.248675', '21619567', '1292523', '26747274', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25785812', '鬼书', '惊悚', '数年前，艾米莉亚·范宁（艾斯·戴维斯 Essie Davis 饰）和丈夫遭遇一场严重车祸，丈夫不幸在这场意外中身亡。在此之后，艾米莉亚一面在养老院辛勤工作，一面又要照顾年幼的儿子塞缪尔（诺亚·维斯曼 Noah Wiseman 饰）。没有父亲的保护，塞缪尔从小害怕鬼怪，与之相对又表现出极其暴力叛逆的言行举止。带着危险品上学的塞缪尔遭到校方的斥责，艾米莉亚无奈暂时将其托付给克莱尔阿姨照看。某晚，塞缪尔选了一本从未见过的绘本《巴巴杜先生》作睡前故事，因故事太过诡异恐怖，艾米莉亚中止了阅读，谁知小塞缪尔却仿佛着魔了一般。他声称巴巴杜来到了家里，小家伙的举止越来越离经叛道，而各种可怕的现象也接二连三出现……©豆瓣', '埃茜·戴维斯', '詹妮弗·肯特', 6.5, 12215, 'tt2321549', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2167358933.jpg', 2.8, 12.6, 48.6, 28.1, 7.8, '0.119071,-0.168391,-0.458802,0.480441,0.108818,-0.263642,0.793986,-0.001318,-0.532605,-0.515440,0.055165,0.736155,-0.353634,0.381054,0.368574,-0.052397,-0.316086,-0.209775,-0.177810,0.009303,-0.297489,-0.572261,-0.161697,-0.270761,-0.234721,-0.300724,0.071171,-0.183522,-0.213040,0.523345,0.055337,0.399169,-0.213545,0.473828,0.045781,0.208169,-0.025228,0.100367,-0.012419,-0.106837,0.495725,-0.225004,-0.186398,0.279561,0.261873,0.335263,0.642529,-0.563239,-0.073181,-0.105707,0.488070,-0.149314,0.195772,0.085990,0.274848,-0.061714,0.169263,-0.053201,-0.249212,-0.096108,0.263532,-0.348509,-0.361956,0.165790,0.042954,-0.016659,-0.351621,0.254197,-0.127815,0.325662,0.230537,-0.309839,0.066355,0.265517,0.207099,0.365872,-0.047890,0.059370,-0.127513,-0.131224,0.297998,-0.034483,-0.350570,0.298944,-0.526850,-0.293371,0.062839,-0.438715,-0.685845,0.083695,0.395136,-0.031309,-0.070335,0.565598,-0.418647,-0.347051,-0.409163,0.143694,-0.188127,-0.077548,-0.201554,-0.417212,0.095193,-0.322197,-0.336450,-0.001568,-0.237582,-0.150767,0.436726,-0.571662,0.467759,0.358184,0.214212,-0.225284,0.351732,0.087139,0.379941,0.052077,-0.237623,0.549729,0.237348,0.057762,0.316124,0.220213,0.104402,-0.017010,-0.176021,0.461860', '4896894', '1309172', '1293647', '6827727');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25786060', 'X战警：天启', '动作', '变种人天启（奥斯卡·伊萨克 Oscar Isaac 饰）诞生于人类文明的最开端，被人类当做神一般敬仰膜拜，然而，这样的他，却遭到了他最蔑视的人类的背叛，被埋葬于废墟石砾之下，一晃眼就是数千年过去。一场意外使得沉睡千年的天启从混沌中醒来，重返人间的他却发现曾经高贵的变种人，如今境遇十分糟糕。为了创造一个属于变种人的新世界，他找到了暴风女（亚历山德拉·西普 Alexandra Shipp 饰）、灵蝶（奥立薇娅·玛恩 Olivia Munn 饰），天使（本·哈迪 Ben Hardy 饰），还有想要过平凡生活却依旧遭到人类驱逐的万磁王（迈克尔·法斯宾德 Michael Fassbender 饰）组成了天启四骑士。在察觉到天启的动向后，X教授（詹姆斯·麦卡沃伊 James McAvoy 饰）带领着魔形女（詹妮弗·劳伦斯 Jennifer Lawrence 饰）、野兽（尼古拉斯·霍尔特 Nicholas Hoult 饰）和凤凰（索菲·特纳 Sophie Turner 饰）等人，发誓要粉碎天启的阴谋。', '詹姆斯·麦卡沃伊', '布莱恩·辛格', 7.7, 362836, 'tt3385516', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2352321614.jpg', 0.5, 3, 29, 46.6, 20.9, '0.009520,0.123758,-0.598588,0.476286,-0.038683,-0.114291,0.840420,-0.091784,-0.520463,-0.360285,0.208842,0.734512,-0.255807,-0.128051,0.408966,-0.007615,-0.274239,-0.347076,-0.031352,-0.225086,-0.199753,-0.132876,-0.527743,-0.269788,-0.024880,-0.482438,0.808652,-0.003844,-0.205694,0.348705,0.012163,0.646725,-0.047663,0.291761,-0.209531,0.054335,-0.009950,0.011359,-0.220212,0.193342,-0.298384,-0.117155,-0.052675,0.460493,-0.352108,0.104710,0.485584,-0.842106,0.145186,-0.626974,0.192915,-0.256244,-0.172466,0.179696,0.256568,-0.107642,0.038365,0.210835,0.143710,0.053373,0.261645,-0.101001,-0.816089,-0.104589,0.040270,0.402962,-0.290975,0.472198,0.149129,0.068216,0.065176,-0.197239,0.091213,0.045118,0.366256,0.364399,0.011204,0.030748,-0.586410,-0.010107,0.489562,-0.081014,-0.503520,0.366207,-0.202339,-0.528848,-0.172063,-0.190314,-0.469721,-0.115642,0.328870,0.195623,0.051305,0.509592,-0.783035,-0.151548,-0.344179,-0.043956,-0.160554,-0.290181,-0.205232,-0.442692,-0.043002,-0.366860,-0.422081,-0.002046,0.100604,-0.174352,0.475909,-0.764183,0.541629,0.311058,0.310498,-0.172907,0.350989,-0.096024,-0.021809,-0.302120,-0.192874,0.633534,0.203926,0.340774,-0.000886,0.028019,0.013447,-0.090722,-0.300810,0.531853', '26759819', '10440076', '26667010', '3213270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25786077', '末日崩塌', '动作', '前美国大兵雷蒙德·盖恩斯（道恩·强森 Dwayne Johnson 饰）在结束硝烟战火的生涯后，而今成为洛杉矶消防局的直升机救援人员。虽然工作中全力以赴，受人敬仰，值得信赖，这些却都无法挽回他失败的婚姻。某次短暂休假后，雷重返岗位，这时在内华达州南部发生了百年不遇的大地震，胡佛水坝在强震中被彻底摧毁。未过多久，又一轮强震从旧金山袭向了洛杉矶，雷在直升机上目睹了繁华城市转眼变成废墟的可怕一幕。此时他的妻子艾玛（卡拉·古奇诺 Carla Gugino 饰）和女儿布蕾克（亚历珊德拉·达达里奥 Alexandra Daddario 饰）此时分处两座城市，为了拯救最爱的两个人，他只身一人，勇往直前，与地震展开争分夺秒的赛跑……©豆瓣', '道恩·强森', '布拉德·佩顿', 7, 159403, 'tt2126355', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2247341513.jpg', 0.8, 5.5, 45.5, 37.5, 10.8, '-0.084608,0.203704,-1.015709,0.302548,0.313618,-0.102099,0.862541,-0.012340,-0.354271,-0.001648,0.362236,0.777105,-0.413172,0.282451,0.428377,-0.049580,-0.484354,-0.858598,-0.210531,-0.215394,-0.465028,-0.115054,-0.315779,-0.004900,0.086304,-0.382427,0.383125,0.430822,0.068142,0.434801,0.212244,0.190953,-0.060116,0.606003,0.034798,-0.001523,0.069205,0.123898,-0.397221,0.215354,-0.255676,-0.320499,-0.130332,0.181934,-0.072136,0.342974,0.603515,-0.225503,-0.053744,-0.339996,0.230224,-0.449598,0.079751,0.132631,0.357880,-0.154192,-0.133699,-0.029909,-0.165628,-0.251695,0.042147,-0.059873,-0.359399,0.051482,-0.188650,0.021980,-0.581716,0.602652,-0.188060,-0.079157,-0.012817,-0.359254,0.148404,0.478327,0.068153,0.513382,-0.286449,0.161856,-0.351245,0.119804,0.901965,-0.040968,-0.335050,0.091327,0.034495,-0.279309,-0.094951,-0.233694,-0.306931,-0.162885,0.386834,-0.195535,0.145824,0.446152,-0.511337,0.096584,-0.380414,-0.539296,-0.182409,-0.200092,-0.351548,-0.712377,0.201585,-0.343837,-0.217657,0.074936,-0.099602,-0.061466,0.423770,-0.461253,0.349032,0.444769,0.313716,0.046765,0.383308,-0.058180,0.336916,-0.131296,0.267276,0.341761,-0.036229,0.688582,0.268731,0.154581,-0.181989,-0.107604,-0.319064,0.637928', '3011051', '1473795', '4832825', '34461680');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25787888', '八恶人', '剧情', '寒冷的怀俄明州山谷中，一辆马车载着赏金猎人“绞刑者”约翰·鲁斯（库尔特·拉塞尔 Kurt Russell 饰）及其价值一万美元的猎物黛西·多摩格（詹妮弗·杰森·李 Jennifer Jason Leigh 饰）踏雪而行。途中，黑人赏金猎人马奎斯·沃伦少校（塞缪尔·杰克逊 Samuel L. Jackson 饰）和新人警长克里斯·马尼克斯（沃尔顿·戈金斯 Walton Goggins 饰）相继登上马车，红石镇是他们共同的目标。由于风雪太大，马车停在了米妮男装店，然而熟悉的店主人不知去向，却另有四名不速之客百无聊赖地待在店里。约翰时刻担心他人抢走猎物，马奎斯警惕地扫视面前的陌生人们，多嘴多舌的克里斯不时为紧张的气氛中加油添醋，黛西则似乎等待更大的风暴到来。仿佛与世隔绝的小店内，即将刮起一场更为猛烈的风暴……©豆瓣', '塞缪尔·杰克逊', '昆汀·塔伦蒂诺', 8.6, 238895, 'tt3460252', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2287491621.jpg', 0.3, 0.9, 11.1, 44.7, 43.1, '0.347205,0.082768,-0.628620,0.451386,0.164496,-0.203723,0.855141,0.381647,-0.503682,-0.372886,0.497008,0.528744,-0.225144,-0.125944,0.515704,0.009956,-0.401255,-0.317680,-0.319853,-0.047992,-0.232603,-0.197734,-0.369296,-0.423903,-0.108955,-0.107593,0.190617,0.131131,0.140830,0.653026,0.329586,0.354197,-0.083762,0.359840,0.002317,-0.041200,0.430570,-0.175301,-0.157437,0.175345,-0.353298,-0.174472,-0.298971,-0.206487,0.182271,0.258793,0.654832,-0.285392,0.071114,-0.050312,-0.123514,-0.132797,0.333308,-0.042227,0.317348,-0.115131,0.166675,-0.369345,-0.048515,0.041249,0.001705,-0.061556,-0.200076,0.444452,-0.129818,0.331960,-0.233903,0.279864,-0.287120,0.103265,0.266707,-0.143355,-0.108306,-0.270352,0.289589,0.089382,0.089985,-0.051469,-0.340045,-0.237598,0.225798,0.032647,-0.233915,0.110488,-0.405192,-0.394439,-0.020996,0.086543,-0.610581,-0.407025,0.760392,0.166272,0.161809,0.174001,-0.539843,0.075113,-0.314575,-0.280506,-0.386803,-0.161007,-0.426614,-0.913599,0.272292,-0.371244,0.156836,0.270942,-0.078539,0.125599,0.189823,-0.345184,0.379650,0.422892,-0.022673,0.199822,0.245272,-0.475086,0.383498,-0.169991,-0.271980,0.148815,0.223426,0.258461,0.132606,0.265759,-0.298030,0.087188,-0.073327,0.628121', '10466639', '1316693', '2269893', 