INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25788426', '电锯惊魂8：竖锯', '悬疑', '远离尘嚣的一座封闭谷仓内，安娜（劳拉·范德沃特 Laura Vandervoort 饰）、赖安（保罗·布朗斯坦 Paul Braunstein 饰）、米奇（曼德拉·范·皮布尔斯 Mandela Van Peebles 饰）和卡莉（布列塔尼·艾伦 Brittany Allen 饰）从昏迷中醒来。他们的头部被奇怪的装置束缚，颈上的铁链连接着安装了圆锯的铁门。在竖锯的指示下，他们将经历一场场痛彻骨髓的生死考验，并在死神的屠刀面前低头认罪。繁华都市中，以各种方式惨死的尸体接连出现，共同特征全部指向了拼图杀人案的制造者——本该在十年前死去的竖锯约翰·克莱默（托宾·贝尔 Tobin Bell 饰）。竖锯不死，给予背德者以至痛的责罚和审判……©豆瓣', '马特·帕斯摩尔', '迈克尔·斯派瑞', 7, 86623, 'tt3348730', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2499761124.jpg', 1.3, 7.7, 44.7, 32.2, 14, '0.382628,-0.086393,-0.498656,0.244147,0.055667,-0.152274,1.044714,0.139092,-0.267704,0.189661,0.515342,0.452812,-0.450261,0.080299,0.126874,0.062347,-0.368042,-0.935313,-0.173875,0.113944,-0.725169,-0.493452,-0.290488,-0.265392,-0.150584,-0.273283,0.433364,-0.201353,0.016135,0.418503,0.239416,0.490782,-0.239679,0.120615,-0.189427,0.017627,-0.017605,-0.414068,-0.006377,0.088778,-0.087159,-0.454621,0.292171,0.220270,-0.235570,0.439403,0.586234,-0.627784,0.208193,-0.192470,0.062396,-0.148252,0.052615,0.527349,0.345700,0.337165,-0.058288,0.239557,-0.395281,0.174218,0.359875,-0.153694,-0.498929,-0.366125,0.018660,0.428319,-0.689853,0.579982,-0.229850,0.183970,-0.131287,-0.398766,0.138893,-0.050621,0.321434,0.432895,-0.310089,-0.151526,-0.454208,-0.187147,0.237023,-0.122810,-0.349081,-0.222242,-0.074728,-0.299675,-0.419271,0.158170,-0.271898,-0.367213,0.593096,0.193961,-0.097925,0.331586,-0.746996,-0.011045,-0.260051,-0.103439,-0.226009,-0.002619,-0.404395,-0.758549,-0.021999,-0.411220,-0.125877,0.144984,-0.052365,-0.164972,0.109770,-0.391175,0.466388,0.155224,0.248346,0.482721,0.504345,0.002156,0.326488,-0.022973,-0.081802,0.479501,0.369598,0.374441,0.420800,0.270871,0.064095,0.105885,-0.623195,0.660659', '1578663', '1316693', '1467779', '25884436');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25788954', '鞋匠人生', '剧情', '麦克斯（亚当·桑德勒 Adam Sandler 饰）出生在一个鞋匠世家，家里祖祖辈辈都靠着经营一间修鞋店维生，长大之后，麦克斯自然而然的也成为了一名修鞋匠，踏进了那间小小的店铺之中，继承了祖业。然而，修鞋匠的工作是何等的无聊啊，日复一日的重复生活渐渐让麦克斯感到无法忍耐，他的心情也因此渐渐走向谷底。某天，麦克斯突然发现了一间拥有神奇力量的传家之宝，他也因此而获得了特殊能力，当他穿上顾客的鞋子之时，他便能够成为那个人，体验那个人生命力的喜怒哀乐。这种能力会给麦克斯波澜不惊的生活带来怎样的转变呢？那些看似光鲜亮丽的生活真的一定充满了快乐吗？©豆瓣', '亚当·桑德勒', '汤姆·麦卡锡', 6.6, 15775, 'tt3203616', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2229417955.jpg', 1, 10.4, 54.2, 26.7, 7.7, '0.261553,0.200322,-0.597458,0.559521,-0.396724,-0.364306,0.668183,0.249343,-0.598379,-0.465345,0.094668,0.886676,0.149006,0.465584,0.180141,0.045242,-0.159360,-0.491132,0.092161,-0.114630,-0.329466,-0.030544,-0.316299,-0.281769,-0.060520,-0.265950,0.610516,0.286713,-0.096783,0.245421,0.050669,0.374463,0.286483,0.414107,-0.334141,-0.062549,0.161442,0.080652,0.019504,0.227789,-0.042797,-0.203552,0.153937,0.216722,-0.069868,0.095284,0.579159,-0.223281,-0.344326,-0.014764,0.357615,-0.053706,-0.198902,0.196349,-0.075208,0.118363,0.006460,0.139062,-0.287581,0.078336,-0.012025,-0.041445,-1.035444,-0.158697,-0.074490,0.088405,-0.523134,0.249676,0.362291,-0.327344,-0.200317,-0.385972,0.222128,0.239205,0.309011,0.538985,-0.393555,0.108888,-0.599724,0.021063,0.666465,-0.235423,-0.371947,0.689530,-0.256344,-0.396670,0.195650,-0.397466,-0.592001,-0.264653,0.129645,0.477161,-0.082540,0.142078,-0.632011,0.246633,-0.221922,-0.261445,-0.030219,-0.438244,-0.036749,-0.415226,-0.318188,-0.421233,-0.285401,0.078774,-0.051073,-0.548853,0.705757,-0.794409,0.214416,0.259822,0.253032,-0.585807,0.557020,-0.240103,0.191043,0.058219,-0.186992,0.450748,-0.019760,0.350507,-0.089108,0.439182,-0.028094,0.014124,-0.265165,0.823172', '1793491', '1783461', '30163500', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25789352', '触不可及', '爱情', '抗日战争时期，地下工作者傅经年（孙红雷 饰）有着双重特工的身份，他和拍档“影子”（徐静蕾 饰）原本要进行最后一次合作，可随着接头人“回声”（黄磊 饰）被傅经年上司——中统特务头子纪曾恩（方中信 饰）捕获，两人均面临重大威胁。危急关头影子牺牲了自己解救了傅经年，真相被影子收养的义妹宁待（桂纶镁 饰）看在眼里，随着深入接触和一系列事件纠葛，宁待与傅经年宿命般地相爱了，可是好景不长，国仇家恨又使两人分离。抗战结束后，纪夫人（蔡少芬 饰）给傅经年介绍了好姐妹卢秋漪（蒋勤勤 饰），此时此刻宁待又出现了，双重身份、国共两党的纠葛使得傅经年面对近在咫尺的爱情却无法触及，组织上的任务让他面临人生中最艰难的抉择，随着内战的白热化，他该何去何从？本片是导演赵宝刚的电影处女作，故事时间跨度达70年。融合谍战和爱情元素，诠释了一位地下工作者与一位舞蹈老师的恋情。©豆瓣', '孙红雷', '赵宝刚', 5.6, 42000, 'tt5473906', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199637691.jpg', 11.8, 26.5, 39.5, 15.5, 6.6, '-0.022993,-0.189350,-0.276226,0.340484,0.487612,-0.142057,0.515625,0.015982,-0.543984,-0.393332,0.172222,0.397559,-0.456176,-0.094537,0.340726,-0.172904,-0.248895,-1.015446,-0.049537,-0.183356,-0.215295,-0.324686,-0.281179,-0.105817,-0.084260,-0.180666,0.834804,0.237783,-0.232960,0.340457,0.368392,0.286581,-0.237783,0.267768,0.178348,-0.037549,0.253298,0.129146,-0.526550,0.050510,-0.065110,-0.480573,-0.102890,-0.007239,-0.175776,0.246142,0.604840,-0.300418,0.019429,-0.268036,0.361171,-0.272407,-0.244206,-0.003100,0.324778,0.157335,0.200976,0.596033,-0.137681,-0.262067,-0.174268,-0.271428,-0.528679,-0.005349,0.247043,0.194347,-0.406577,0.447565,-0.016727,0.225123,0.009002,-0.228407,0.237539,0.368286,0.687636,0.434458,-0.317854,-0.115687,-0.139605,0.473025,0.911438,0.019371,-0.188298,0.211229,-0.225028,-0.538021,-0.391597,-0.245204,-0.251279,0.163666,-0.034933,0.255001,-0.075667,0.529667,-0.615868,-0.117844,-0.259421,0.149596,0.093298,-0.464899,0.143532,-0.395631,-0.467303,-0.571359,-0.406288,0.229135,-0.071888,-0.310018,0.832551,-0.567489,0.124517,0.307382,0.430133,-0.377720,0.762593,0.246777,0.065741,-0.517628,0.362690,0.203737,-0.148598,-0.176848,0.141550,0.113625,-0.220951,-0.040191,-0.085124,0.033674', '1293643', '4301278', '25777330', '3212120');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25789402', '侠探杰克：永不回头', '动作', '续集故事继续围绕杰克（汤姆·克鲁斯 饰）展开，他重回弗吉尼亚州的军事基地和苏珊·特纳少校会面，要解决一些个人问题。此时，特纳却意外被捕。杰克同时也陷入谜团，因为他被诬告犯有重罪，而且牵涉到一个自己完全不知道的小孩。这些，杰克都记不起来了。他要克服重重困难，去寻找特纳，最终解决问题。', '汤姆·克鲁斯', '爱德华·兹威克', 5.9, 34677, 'tt3393786', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2382529090.jpg', 1.9, 19.7, 60.8, 14.5, 3.1, '0.357413,-0.014417,-0.489464,0.186095,-0.095166,-0.185254,1.135945,-0.079938,-0.359136,-0.493143,0.117659,0.677473,0.016447,-0.075507,-0.105487,0.032808,-0.821930,-0.417266,0.539406,-0.122492,-0.214784,-0.961721,-0.327547,-0.280447,-0.172910,0.162312,0.486251,0.066550,-0.155985,0.105987,0.167941,0.330049,0.195666,0.757949,0.153090,0.206111,0.161213,-0.328950,0.017575,0.224303,0.346816,-0.031692,-0.319537,0.496587,0.020759,0.484831,0.499454,-0.110901,-0.026210,0.064813,-0.002002,-0.441181,-0.089176,0.235607,0.030208,-0.272105,-0.128875,0.261538,0.004236,-0.165201,0.203998,0.166371,-0.726052,0.081921,0.136567,0.462170,-0.331294,-0.071645,-0.342477,0.182155,-0.048450,-0.445394,-0.134078,0.660018,0.553482,0.083953,-0.263387,-0.015400,-0.630983,0.099222,0.844270,-0.022911,-0.130529,0.055143,-0.243341,-0.387087,-0.359142,-0.043584,-0.143608,0.008387,0.376682,0.089904,-0.264062,0.322451,-0.159248,-0.224243,-0.276986,-0.383429,-0.471788,-0.490309,-0.126784,-0.322832,0.013157,0.045463,-0.265184,-0.094368,-0.009405,-0.210703,0.363035,-0.582991,0.150638,0.754601,0.194178,-0.498461,0.378118,0.240686,0.126658,-0.549489,-0.152477,0.196223,0.123329,0.310048,0.313846,0.250838,0.449606,-0.303591,-0.307237,0.308712', '25909236', '10546747', '1294941', '20497633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25790555', '记忆中的玛妮', '剧情', '初中女孩佐佐木杏奈（高月彩良 配音）深藏无限的愁绪心事，她与疼爱自己的养母赖子（松岛菜菜子 配音）也无法坦然相对。由于上学期间突发过呼吸的情况，于是杏奈利用暑假来到了风光秀美的北海道札幌市，在亲戚大岩清正（寺岛进 配音）和阿节阿姨（根岸季衣 配音）家疗养。在叔叔家不远处的溪地，矗立着一座老旧但风韵独存的西式建筑，奇妙的感觉令杏奈注意到了它的存在。某个夜晚，心情低落的杏奈划着小船超该建筑划去，结果发现本该许多年没人居住的房子居然灯火通明，并且她在那里邂逅了与之年龄相仿的金发碧眼女孩玛妮（有村架纯 饰）。相似的心境让两个女孩成为好朋友，她们依恋着彼此，却不知各自的心底隐藏着怎样令人难以置信的因缘……本片根据英国小说家琼安·G·罗宾森的同名儿童文学改编。©豆瓣', '高月彩良', '米林宏昌', 7.9, 36682, 'tt3398268', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2189907988.jpg', 0.3, 2.4, 25.4, 44.7, 27.1, '0.298386,-0.199642,-0.775075,0.550540,-0.076619,-0.175427,0.735901,0.437347,-0.455196,-0.372717,0.311910,0.572727,-0.186026,0.445192,0.153891,0.139694,-0.333786,-0.433340,-0.056922,-0.132088,-0.113577,-0.390104,-0.232705,-0.081915,-0.019903,-0.152672,0.565570,0.031118,-0.103701,0.463162,-0.136467,0.120763,-0.459846,0.276485,-0.269346,-0.015248,0.021133,0.007404,-0.143024,0.031546,-0.121875,-0.169077,-0.226394,0.118764,0.111549,0.362038,0.839183,-0.011891,-0.261555,0.288736,0.210493,0.243087,-0.073209,0.123254,0.287263,-0.052376,0.168456,-0.087532,-0.265166,-0.050260,0.103890,-0.107435,-0.213864,0.163363,0.179206,0.216718,-0.363304,0.733164,0.065761,-0.361197,0.037175,-0.413615,0.132132,-0.004896,0.108237,0.571055,-0.171104,0.286551,-0.288017,0.060488,0.561457,0.175908,-0.069389,0.398768,-0.353397,-0.351148,-0.179064,-0.191763,-0.446994,-0.042567,0.097424,0.139509,-0.137441,0.065669,-0.621877,0.043470,-0.055592,0.094658,0.092114,-0.353317,-0.201284,-0.558599,-0.052143,-0.503454,-0.361072,0.106378,0.060200,-0.206629,0.883677,-0.773549,0.095470,0.564272,0.204335,-0.043847,0.609169,-0.087347,-0.142153,-0.094693,-0.206650,0.338032,-0.275306,0.026527,0.161020,0.463943,-0.383037,-0.008832,-0.589135,0.346310', '3811356', '24839498', '25922902', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25790749', '最完美的离婚 2014特别篇', '剧情', '纷纷扰扰的一年过去，滨崎光生（瑛太 饰）和星野结夏（尾野真千子 饰）这对孽缘鸳鸯终于决定重新走入婚姻殿堂。只不过在孩子的问题上，两人再度发生分歧，结夏愤而离家出走。另一边的上原家，新生命的到来增添了几多温馨。谁知谅（绫野刚 饰）偶然邂逅当初和他一同私奔的潮见薰（臼田麻美 饰），平静的内心再起波澜。全心全意照顾女儿的灯里（真木阳子 饰）敏锐察觉到丈夫的变化，她不禁为这样的爱情和婚姻深感懊恼。结夏打算随同爱慕自己的便当店老板黑部三德去北海道，正和薰谈判的灯里目击这一幕，连忙告知光生。疾驰的列车上，三对男女面面相觑，他们的爱、婚姻和心，都需要得到一个答案……©豆瓣', '永山瑛太', '并木道子', 9.1, 37243, 'tt3400916', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2186872257.jpg', 0.2, 0.4, 6.8, 28.8, 63.8, '0.406692,0.085646,-0.702921,0.460492,0.177278,-0.528881,0.660802,0.119018,-0.330145,-0.260294,0.199644,0.421008,-0.219466,0.110087,0.483564,0.058310,-0.293112,-0.736617,-0.106580,-0.172339,-0.313114,-0.536527,0.012400,0.000643,-0.042859,-0.029932,0.678527,0.080087,0.209052,0.765552,0.564671,0.391553,-0.257011,0.278909,0.053957,0.272201,-0.094032,0.445469,-0.437849,-0.160801,-0.164318,-0.205029,-0.236512,0.368272,-0.206969,0.353203,0.642027,-0.310294,-0.457441,-0.100257,0.223666,-0.230560,0.014688,0.112243,0.136659,0.199588,0.167294,0.251845,-0.400319,-0.114674,-0.008379,0.154198,-0.422948,0.156861,0.109446,0.129328,-0.298957,0.365535,0.055829,-0.190222,0.299318,-0.196143,0.070298,0.432457,0.345889,0.395134,-0.488757,-0.033731,-0.190134,0.075971,0.706240,-0.104418,0.253065,0.534873,-0.191084,-0.247181,-0.108619,0.009184,-0.521928,-0.020428,0.052217,0.367449,-0.048944,0.211566,-0.494173,0.042583,-0.097771,-0.010279,0.242189,-0.351722,0.206866,-0.430892,-0.363702,-0.494931,-0.427544,0.217760,0.072970,-0.272804,0.524391,-0.637141,0.167382,0.272548,0.288038,-0.444511,0.579602,0.171624,0.043558,-0.383434,-0.109309,0.136460,-0.224147,-0.027298,-0.146452,0.148852,0.110201,0.293761,-0.466563,0.271185', '2365260', '25911595', '25777330', '30209018');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25790761', '东方快车谋杀案', '剧情', '影片改编自阿加莎·克里斯蒂原著小说《东方快车谋杀案》，讲述大侦探波洛（肯尼思·布拉纳 Kenneth Branagh 饰）在东方快车上巧破一桩谋杀奇案的故事。波洛乘上东方快车，夜间三次被吵醒，第二天清晨便发现同车的美国富商雷切特（约翰尼·德普 Johnny Depp 饰）被人谋杀，死者被戳了12刀。波洛根据他所观察到的各种可疑迹象以及同车人士的讯问，并结合美国实行的12人陪审团制度等情况进行逻辑推理，成功地揭开了一起“集体复仇”奇案。', '肯尼思·布拉纳', '肯尼思·布拉纳', 6.8, 295950, 'tt3402236', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2502165084.jpg', 0.9, 7.7, 48.2, 34.8, 8.5, '0.444360,-0.225441,-0.603281,0.517969,0.569528,0.100965,0.568500,0.178679,-0.339125,-0.280910,0.062734,0.433998,-0.631033,0.022658,0.519164,0.057031,-0.858632,-0.838583,0.090564,0.079979,-0.555957,-0.581663,0.001346,-0.370129,0.163330,-0.357596,0.362079,0.192545,-0.361206,0.297577,0.259192,0.416750,-0.269042,0.156171,-0.010711,0.246003,0.439352,-0.123502,-0.067051,0.336597,-0.088625,-0.478077,-0.180413,-0.084669,-0.038193,0.476682,0.550710,-0.379465,0.012369,0.087878,0.520135,-0.207923,-0.024579,0.124474,0.365319,0.034041,0.192309,0.576917,-0.027826,-0.117289,-0.012094,-0.107853,-0.400210,-0.030436,0.196875,0.067594,-0.181425,0.106648,-0.278299,0.299786,-0.262662,-0.146290,0.081324,0.054639,0.292895,0.315830,0.186534,-0.149485,-0.347600,0.316115,0.137666,0.105919,-0.197123,0.270443,0.045458,-0.369827,-0.196435,0.082445,-0.108708,0.076243,0.746276,-0.142512,-0.369226,0.304999,-0.543790,-0.229065,-0.611786,-0.302024,-0.044812,-0.068002,-0.018663,-1.092552,-0.150202,-0.002200,-0.170209,0.085066,0.325536,-0.314367,0.341320,-0.299974,0.088571,0.579556,-0.287830,-0.187430,0.513663,-0.060905,-0.013342,-0.119619,-0.134698,0.288395,0.629159,0.336205,0.193089,0.385792,0.021419,-0.045115,-0.368681,0.206551', '6517421', '2075345', '3003137', '34961898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25792690', '反贪风暴', '剧情', '商业犯罪搜查科警司黄文彬（林家栋 饰）的妻子前往廉政公署举报丈夫巨额现金来路不明，廉记首席调查主任陆志廉（古天乐 饰）奉命传唤黄到署问话，然而对手老奸巨猾，深谙暗箱一切套路，最终平安脱险。此前不久，黄曾调查素有香港会计界教父之称的罗德永（卢海鹏 饰）未果，视频中二人的反常举止引起陆的怀疑。与此同时，身份难辨的Z基金在道貌岸然的律师胡志勇（王敏德 饰）的推动下即将上市，该基金打着扶贫旗号，有望吸引港府150亿的专项关怀基金投入其中。陆敏感察觉其中的蹊跷，他和同事利用有限的时间展开全面调查。金钱巨大的诱惑之下，贪婪之徒铤而走险，更不惜为此杀人嗜血。狂扫污秽的Z风暴即将到来，黑云压城城欲摧……©豆瓣', '古天乐', '林德禄', 6.1, 76330, 'tt3469440', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195270848.jpg', 3.4, 17.9, 53.4, 18.6, 6.7, '-0.043621,0.210785,-0.457046,0.314309,0.128133,0.235949,0.083095,0.157222,-0.610988,-0.476603,0.202530,0.076494,-0.016870,-0.090407,0.286311,-0.291741,-0.027789,-0.453446,-0.397664,-0.075438,0.017369,-0.471177,-0.356673,-0.261057,-0.140647,-0.044735,0.336245,0.352585,-0.301951,0.397048,0.486604,0.301727,-0.316868,0.329542,0.248141,-0.279895,0.369935,0.093984,-0.434464,0.089267,0.093457,-0.310757,0.013057,0.096904,0.051590,0.530265,0.282057,-0.067085,-0.210307,-0.345462,0.522148,-0.234096,0.198000,-0.000295,0.387380,0.353189,0.287834,0.239739,-0.442167,-0.023142,0.031853,-0.112688,-0.786927,-0.237492,0.273007,0.103952,-0.273037,-0.261565,-0.258063,0.289538,-0.038956,0.082437,0.004387,0.437961,0.321082,0.074649,0.248581,0.146602,-0.131801,0.391521,0.265042,-0.048559,-0.065112,-0.101751,-0.109266,-0.255622,0.132707,-0.237431,-0.039770,-0.116558,0.385003,0.138273,0.232701,0.383236,-0.382364,-0.102364,-0.164982,0.231497,-0.109007,-0.224823,-0.006808,-0.743603,-0.260290,-0.104685,-0.016270,0.077652,0.271322,-0.149789,0.238535,-0.515579,-0.089912,0.417692,0.335335,-0.526378,0.491010,-0.136123,-0.057066,-0.537633,-0.215553,0.094648,0.432204,0.154584,-0.238747,0.017154,0.007106,-0.586978,0.075911,-0.126953', '26352445', '26984538', '24325861', '26996640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25792824', '蜡笔小新：决一胜负！逆袭的机器人爸爸', '喜剧', '美好的周末假期，野原新之助（矢岛晶子 配音）和爸爸广志（藤原启治 配音）一起去看机器人的科幻电影，走出电影后的父子俩兴奋地大玩合体游戏，谁知广志却不慎扭伤了腰。忍受不了老婆的碎碎念，广志去医院看病，可是周末医院休诊，父子俩只得来到公园休息，结果还被妈妈团赶了出去。当父子俩走在回家路上的时候，色色的广志被一家按摩店的美女招待员所吸引，于是把小新打发回家，自己则跟着对方进入店里。从昏迷中醒来的广志以飞快的速度回家，结果吓到了全家人，原来他被美容院改装成机器人。最初的震惊恐惧之后，野原家渐渐习惯了这个家务全能的新爸爸。然而随着城市中机器爸爸越来越多，潜在的危机则悄然浮出水面……©豆瓣', '矢岛晶子', '高桥涉', 8.9, 15165, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2173344684.jpg', 0.1, 0.7, 9.5, 33.5, 56.1, '0.291000,0.055066,-0.518345,-0.125071,-0.050929,-0.567248,0.520377,0.287285,-0.242823,-0.255020,0.074120,0.501699,-0.327046,0.533174,0.251280,0.139798,-0.335870,-0.438936,-0.172245,-0.030945,-0.415820,-0.009342,0.070296,-0.053656,0.053946,0.085718,0.254243,-0.192445,0.108365,0.553633,0.016715,-0.006439,-0.184983,0.585505,-0.003813,0.284177,0.210575,-0.125349,-0.093323,0.225991,0.270101,-0.188757,-0.017235,-0.119032,0.150687,0.044453,0.739283,0.199253,-0.195108,-0.103234,0.305714,-0.012971,-0.235707,0.155323,0.172048,0.150639,0.346773,-0.208175,-0.219405,0.192256,0.013536,0.041155,-0.347146,0.381017,-0.068476,-0.123322,-0.500074,0.251939,-0.071488,-0.050703,0.385219,-0.682015,0.325932,0.176472,0.118329,0.588499,-0.467226,0.393565,-0.247010,0.150413,0.269533,-0.190061,0.049720,0.537562,0.171637,-0.026284,0.245172,-0.088946,-0.232895,-0.105603,0.314266,0.223682,-0.498478,-0.054889,-0.373717,-0.058127,-0.160669,-0.530282,-0.186145,-0.295902,-0.353024,-0.622596,0.101809,-0.023017,-0.029300,0.252902,0.091487,-0.049216,0.546289,-0.490298,0.214651,0.555920,0.188541,-0.178309,0.501965,-0.373692,0.064936,-0.097319,0.169386,0.004326,-0.091109,0.880685,0.363465,0.562298,-0.296282,-0.090438,-0.560624,0.456325', '3735015', '2043154', '1309184', '1307811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25793398', '海洋奇缘', '动画', '故事最早始于住在风和海的半神毛伊（道恩·强森 Dwayne Johnson 配音），他偷走了女神的特菲堤之心，导致岩浆魔鬼厄卡陷入疯狂的状态，南太平洋各小岛也面临着毁灭的威胁。一千多年后，某座小岛上的酋长女儿莫阿娜（奥丽依·卡拉瓦霍 Auli''i Cravalho 配音）在父母的呵护下渐渐长大，童年时她曾偶然捡到特菲堤之心，亦曾受到大海的召唤，然而父亲却严厉禁止莫阿娜出海，即使小岛正遭受着死亡的威胁。从奶奶那里，莫阿娜知晓了他们这一族人的历史，于是为了拯救小岛，她依然出海去寻找被困在某地的毛伊，好让他归还特菲堤之心。历经千辛万苦，莫阿娜终于见到了这个传说中的高傲自大的半神。而毛伊则担心特菲堤之心带来霉运拒绝前往。只不过在命运的指引下，毛伊还是随着莫阿娜踏上未知的征途……©豆瓣', '奥丽伊·卡瓦洛', '罗恩·克莱蒙兹', 7.5, 173419, 'tt3521164', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2397960879.jpg', 0.4, 2.9, 34.4, 44.6, 17.7, '-0.185868,0.330761,-0.954388,0.795626,0.030884,-0.213752,0.642397,0.041435,-0.351938,-0.121399,0.337771,0.679044,0.159271,0.382154,0.440737,0.154030,-0.268245,-0.224406,-0.073468,-0.098218,-0.478428,-0.290773,-0.414836,0.093580,0.001996,-0.462901,0.651350,0.296312,-0.340329,0.264254,0.001980,0.306851,-0.214538,0.594869,-0.331946,0.098896,-0.157984,0.162030,-0.273626,0.130024,-0.058278,-0.346102,-0.072995,0.216419,-0.054310,0.242813,0.641372,-0.661875,-0.199587,-0.162882,0.310675,-0.398645,0.110704,-0.033762,0.344356,-0.073282,0.019042,0.222261,-0.023027,0.052579,0.201271,-0.083373,-0.551622,-0.126737,0.015472,0.138111,-0.512174,0.200442,0.243544,0.039162,-0.090667,-0.225805,0.271262,0.445358,0.105016,0.360867,-0.315537,-0.003174,-0.247861,0.012632,0.846950,-0.202067,-0.085646,0.091469,-0.025116,-0.307624,0.169896,-0.283679,-0.548782,-0.052271,0.363130,0.326658,-0.415205,0.432280,-0.650910,-0.020127,-0.154734,-0.234352,0.123659,-0.366366,-0.119413,-0.474831,-0.103691,-0.142902,-0.160879,0.065889,0.029588,-0.241023,0.639513,-0.627213,0.721797,0.655460,0.306738,-0.365063,0.509513,0.030136,-0.027877,-0.220385,0.111792,0.696277,0.008342,0.637889,-0.005489,-0.125210,-0.121424,0.021856,-0.430982,0.548597', '34461680', '3606973', '3626364', '1293952');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25794212', '分歧者2：绝地反击', '动作', '身为博学派的领导人，珍宁（凯特·温丝莱特 Kate Winslet 饰）对分歧者翠丝（谢琳·伍德蕾 Shailene Woodley 饰）和老四（提奥·詹姆斯 Theo James 饰）展开了无情的追杀，翠丝的父母在追杀之中双双死去。两人一路逃亡，并且不断的试图获取其他派系同仁的支援和结盟，想要扩大实力，推翻珍宁的残暴统治。让两人没有想到的是，曾经最一无是处的无派系阵营如今成为了革命的中坚力量，而反抗军的首领，竟然是老四失散多年的母亲伊芙琳（娜奥米·沃茨 Naomi Watts 饰）。然而，种种意外的发生令老四开始怀疑自己的母亲实际上另有打算，与此同时，翠丝亦发现了父母生前所隐藏的秘密。以这个秘密为诱饵，翠丝孤身一人来到了敌人大本营。©豆瓣', '谢琳·伍德蕾', '罗伯特·斯文克', 6.1, 72573, 'tt2908446', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2246877123.jpg', 3.8, 19, 52.5, 18.2, 6.5, '0.414868,-0.176774,-0.692358,0.766567,0.008223,-0.196816,0.669980,0.132017,-0.769470,-0.526528,0.297171,0.697435,0.164087,-0.027240,0.272171,-0.109946,-0.171747,-0.749010,-0.078643,-0.271751,-0.203125,-0.694625,-0.310049,-0.379753,-0.222819,-0.375896,0.794763,-0.010295,-0.367060,0.319086,0.379080,0.537675,-0.235125,0.323756,-0.048493,0.136361,0.201371,-0.145416,-0.492940,0.343737,-0.142878,-0.034116,-0.164788,0.433524,-0.162536,0.554929,0.555365,-0.492826,0.034769,-0.204014,0.252794,-0.390332,0.037845,0.305590,0.550431,-0.094594,0.187966,0.357382,0.013318,-0.117895,0.220078,-0.063010,-1.019351,-0.033955,0.388489,0.241644,-0.626984,0.382178,-0.141195,-0.129403,0.303005,-0.203724,0.254798,0.832692,0.128560,0.293323,-0.230424,-0.077559,-0.518529,-0.179484,0.734845,-0.155225,-0.056010,0.092955,-0.076508,-0.177177,0.021813,-0.383058,-0.379025,-0.061359,0.318156,0.224203,0.094095,0.666437,-0.612504,-0.266957,-0.376566,-0.088174,0.219388,-0.462642,0.004340,-0.515989,-0.267902,-0.397560,-0.113449,0.141180,-0.084691,-0.283341,0.685887,-1.057739,0.167181,0.345910,0.292442,-0.817583,0.489376,-0.000071,0.149452,-0.286455,-0.074249,0.315191,0.314824,-0.020227,0.112253,0.094364,0.050453,-0.391438,-0.157566,0.011430', '26678784', '1301022', '30345227', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25794302', '分歧者3：忠诚世界', '动作', '派系制度瓦解了，老四（提奥·詹姆斯 Theo James 饰）的母亲伊芙琳（娜奥米·沃茨 Naomi Watts 饰）成为了墙内世界的统治者，她利用强悍而又严格的武装力量控制墙内居民，不允许他们越雷池一步。可偏偏翠丝（谢琳·伍德蕾 Shailene Woodley 饰）和老四不信这个邪，他们坚信，未来和希望是属于墙外世界的。于是，两人带领着克里斯蒂娜（佐伊·克拉维兹 Zoe Kravitz 饰）、皮特（迈尔斯·特勒 Miles Teller 饰）和托里（李美琪 Maggie Q 饰）等人突出重围，终于来到了高墙的那一边。在那一边，基因局收留了翠丝一行人，表面看来基因局扮演的俨然是正义的一方，但实际上，其负责人大卫（杰夫·丹尼尔斯 Jeff Daniels 饰）怀揣着极大的野心，隐藏了一个惊人的秘密。©豆瓣', '谢琳·伍德蕾', '罗伯特·斯文克', 6, 47900, 'tt3410834', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2354368180.jpg', 4.8, 21.1, 51.5, 15.9, 6.6, '0.300931,0.122477,-0.740796,0.681941,-0.204198,-0.006194,0.657438,0.431589,-0.469746,-0.201605,0.304695,0.595017,0.142290,-0.203296,0.138407,0.236539,-0.408881,-0.471382,0.062598,-0.270020,-0.281090,-0.481486,-0.379522,-0.423586,-0.145278,-0.288352,0.483522,0.046849,-0.131702,0.318277,0.350428,0.424997,0.015471,0.208869,-0.005385,0.075165,0.387739,-0.300121,-0.203803,0.268045,-0.102394,0.225923,-0.199949,0.409040,-0.024325,0.258483,0.472201,-0.609188,0.104117,-0.009481,0.137360,-0.405414,0.065065,0.138722,0.337920,-0.200037,0.040758,0.285192,-0.131623,-0.002192,0.447669,-0.133890,-0.853682,-0.238058,0.318140,0.208660,-0.619888,0.673180,-0.266447,-0.240841,-0.029140,-0.108292,-0.006285,0.316573,0.170554,0.327575,-0.136606,-0.241557,-0.840126,-0.219167,0.128690,0.031537,-0.311240,0.174395,-0.318868,-0.320321,-0.399466,-0.179920,-0.552218,-0.290518,0.373432,0.075579,0.021793,0.115677,-0.493492,0.046153,-0.357600,0.049033,-0.023845,-0.632616,0.011368,-0.561309,-0.239480,-0.415289,-0.242243,0.147262,-0.179464,-0.102423,0.816933,-0.740838,0.044182,0.471291,0.288994,-0.529401,0.594010,0.135912,0.302998,-0.298731,-0.024862,0.171228,0.100751,0.131288,0.289260,0.638204,0.062398,-0.274856,-0.187142,0.429314', '1793491', '30163500', '25932086', 