INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25796222', '玉子爱情故事', '喜剧', '单纯善良的北白川玉子（洲崎绫 配音）、外刚内柔的常盘绿（金子有希 配音）、我行我素的牧野神奈（长妻树里 配音）和外冷内热的朝雾史织（山下百合惠 配音），四位好友相互陪伴，度过了人生中最快乐的三个年头，如今，毕业季在即，面对尚且处于迷雾之中的未来，四个女孩心中有着隐隐的不安，但更多的，还是对日后生活的希冀和幻想。玉子家中世代经营着一间打糕店，而玉子又是家中的长女，这让玉子不得不开始考虑起了继承家业的想法。与此同时，玉子的青梅竹马大路饼藏（田丸笃志 配音）亦有着自己的选择，尽管他家和玉子家是商店街的竞争对手，但他俨然已经喜欢上了可爱的玉子。©豆瓣', '洲崎绫', '山田尚子', 8.5, 68657, 'tt3413018', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2178271858.jpg', 0.3, 1.5, 15.3, 39.6, 43.3, '0.249052,0.060998,-0.486142,0.652036,0.106217,-0.319758,0.770857,0.292493,-0.487234,-0.314348,0.208960,0.665484,0.035737,0.523440,0.212183,0.246123,-0.117004,-0.457384,-0.189397,-0.130344,0.001978,-0.418116,-0.188648,-0.121416,-0.400139,0.005605,0.800898,0.251310,0.002549,0.327260,0.388467,0.318067,-0.235991,0.224844,-0.039508,-0.055623,0.073954,0.210777,-0.116443,0.111760,-0.163022,-0.140623,-0.147357,0.117145,0.356126,0.549517,0.612721,-0.044747,-0.200142,-0.118218,0.272072,-0.028296,-0.298673,0.217840,0.297776,-0.019194,0.406270,0.050550,-0.180243,-0.161876,-0.115249,-0.055099,-0.691899,-0.056787,0.413975,0.081939,-0.467735,0.427793,0.097246,-0.394126,0.212576,-0.236158,0.159184,0.109972,0.214152,0.366829,-0.447448,0.280491,-0.284476,-0.008583,0.423740,0.179335,0.021052,0.459848,-0.361926,-0.339363,-0.094386,-0.231207,-0.588151,-0.241825,-0.022113,0.231272,-0.061978,0.172096,-0.559547,0.208576,0.173169,-0.101669,0.387161,-0.438084,-0.094154,-0.483799,0.112378,-0.726442,-0.515789,0.136416,0.382151,-0.356278,1.060555,-0.895200,-0.149185,0.281250,0.329134,-0.336476,0.613832,0.225158,0.025361,-0.019079,0.010948,0.268974,-0.216972,-0.123595,-0.000296,0.419123,-0.310759,-0.059402,-0.753364,0.567527', '26283288', '26348103', '25880986', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25797778', '冰川时代5：星际碰撞', '喜剧', '影片讲述松鼠奎特（克里斯·韦奇 Chris Wedge 配音）为了追松果，偶然引发了宇宙事件，改变并威胁着冰川时代的世界。为了拯救自己，话唠树懒希德（约翰·雷吉扎莫 John Leguizamo 配音）、猛犸象曼尼（雷·罗马诺 Ray Romano 配音）、剑齿虎迪亚哥（丹尼斯·利瑞 Denis Leary 配音），以及别的动物群族必须离开家园，踏上了他们充满喜剧色彩的冒险旅程，他们来到了充满异国情调的新大陆，并遇到了许多形形色色的新角色。', '西蒙·佩吉', '麦克·特米尔', 7.1, 83537, 'tt3416828', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2365823697.jpg', 1.3, 7.5, 40, 34.7, 16.5, '0.104388,-0.010089,-0.250640,0.378250,0.340009,-0.388109,0.823591,0.100188,-0.130029,-0.182405,-0.280026,0.640845,-0.150370,0.039966,0.298203,-0.262063,-0.572682,0.070717,0.039923,0.126072,0.081786,-0.342218,0.025069,-0.282324,0.144978,-0.411150,0.582317,-0.085252,-0.595339,0.286357,0.214417,0.368412,-0.313941,0.427035,0.118950,0.288017,0.082752,0.295480,-0.264826,0.025255,-0.042929,0.317769,-0.327664,0.297734,-0.027132,-0.005918,0.425715,-0.511717,0.124037,-0.211056,0.171111,-0.310683,0.343395,-0.351231,0.314359,-0.233943,0.064791,0.401921,0.358684,0.166103,0.087756,-0.366761,-0.511403,0.226058,-0.205429,0.343216,-0.257962,0.005449,0.252115,0.245306,0.087584,-0.037476,0.245766,0.119648,0.669259,0.080872,-0.009248,0.305778,-0.322790,0.035496,0.413846,-0.046508,-0.140855,0.275419,-0.213643,-0.545522,-0.164975,0.040044,-0.403930,0.001786,0.608125,-0.049726,-0.235870,0.312862,-0.774579,-0.132631,-0.299440,-0.576310,-0.047806,-0.340189,-0.014933,-0.926427,0.127489,-0.020697,-0.075447,-0.255063,0.174507,-0.199448,0.412709,-0.677182,0.254684,0.738571,-0.098499,-0.317516,0.203266,-0.188913,0.068341,-0.561028,0.018280,0.827475,-0.004155,0.351659,-0.088081,0.143366,0.045738,0.080171,-0.094585,0.855631', '34961898', '3178770', '26374197', '6040982');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25798131', '疾速追杀', '动作', '不久之前刚刚经历丧妻之痛的约翰·威克（基努·里维斯 Keanu Reeves 饰），未曾料到磨难与折磨接二连三袭来。他那辆1964年的福特老爷车被一伙俄罗斯小混混盯上，旋即引来对方入室抢劫，心爱的狗狗被当场杀死，约翰也遭到无情毒打，那辆老爷车自然被对方抢走。偷车的混混（阿尔菲·艾伦 Alfie Allen 饰）是黑帮大佬维格•塔拉索夫（迈克尔·恩奎斯特 Michael Nyqvist 饰）的儿子，而维格在听说这件事后显得紧张非常，因为约翰有着令人胆战心惊的身份。他曾是名震江湖的冷血杀手，当年替塔拉索夫杀掉不少难缠的对手，后来却为了妻子金盆洗手。愤怒至极的约翰拒绝塔拉索夫的调解，他决定单枪匹马展开复仇……©豆瓣', '基努·里维斯', '大卫·雷奇', 7.8, 172405, 'tt2911666', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2210801408.jpg', 0.6, 3.4, 27.5, 44.1, 24.5, '0.258798,-0.128489,-0.550919,0.304042,-0.221301,-0.279312,0.884036,-0.094144,-0.821411,-0.359938,0.373444,0.581272,-0.272361,-0.036852,0.480887,-0.027251,-0.014945,-0.449629,0.098919,0.010687,0.112348,-0.282470,-0.248858,-0.254725,0.052105,-0.288697,0.465744,-0.049393,-0.116445,0.595636,0.417750,0.754765,0.188539,0.347665,0.057595,0.075934,0.274470,-0.200765,-0.161635,-0.053858,-0.226300,-0.273601,0.098287,0.275601,-0.408000,0.399495,0.190011,-0.072090,-0.158787,-0.263311,0.243012,-0.500084,0.160004,0.106064,0.527538,-0.171646,0.153597,0.248853,0.043524,-0.237579,0.211980,0.292418,-0.518796,0.328215,-0.067604,-0.103949,-0.614469,0.141883,-0.461722,0.383238,-0.060606,-0.092775,-0.007519,0.173984,0.402793,0.121798,0.102198,0.075617,-0.550251,0.094596,0.914172,-0.197342,-0.013870,-0.022258,-0.081962,-0.017807,0.389989,-0.750482,-0.418267,0.181828,0.588016,-0.187572,-0.212209,0.552576,-0.324369,-0.283975,-0.507861,0.103903,-0.110260,-0.178261,-0.185783,-0.414020,-0.233528,-0.290177,-0.273272,-0.184442,-0.064379,-0.093831,0.218213,-0.660090,0.333653,0.352366,0.214352,-0.280877,0.268251,0.078536,-0.168077,-0.005209,-0.233862,0.335398,0.631257,0.029734,0.035425,0.103215,0.192451,-0.378471,0.190037,0.286592', '25721544', '25828589', '1309116', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25798222', '亲爱的', '剧情', '田文军（黄渤 饰）和鲁晓娟（郝蕾 饰）曾是一对恩爱的夫妻，然而，两人之间的感情却被时间和争吵消耗殆尽，最终，他们选择了离婚。如今，联系着两人的唯一枢纽，就是可爱的儿子田鹏。然而，某一天，这唯一的纽带也断裂了，田鹏于一次外出玩耍时无故失踪，绝望和崩溃之中，田文军与鲁晓娟踏 上了漫漫寻子之路，并在途中结识了许多和他们一样无助的父亲和母亲们。时光匆匆流逝，一条关于田鹏的线索浮出水面，促使田文军和妻子来到了一处偏僻的村落之中，在那里，他们看到了酷似田鹏的男孩，然而，男孩口中的“妈妈”却并非鲁晓娟，而是一位名叫李红琴（赵薇 饰）的村妇，这错位的一切究竟是怎么回事？©豆瓣', '赵薇 Wei Zhao', '陈可辛', 8.4, 482886, 'tt3752930', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2199507156.jpg', 0.2, 0.8, 13, 48.7, 37.3, '0.365826,-0.070825,-0.802299,0.551767,0.132386,-0.403446,1.000936,0.015723,-0.558008,-0.214120,-0.062661,0.740777,-0.249967,0.318053,0.119832,-0.172795,-0.228867,-0.774253,-0.064179,-0.195720,-0.188262,-0.541470,-0.281955,0.123387,-0.071519,-0.145418,0.672568,0.146360,0.066395,0.845783,0.454298,0.008128,-0.600117,0.454731,-0.262116,0.184429,0.078165,0.275022,-0.221562,-0.075105,0.107605,-0.110777,0.053259,0.041845,-0.244057,0.550138,0.631310,-0.268760,-0.128695,-0.042886,0.105437,-0.237021,-0.007887,0.274214,0.371796,-0.040997,0.661381,0.311933,-0.301988,-0.190836,0.130497,-0.036029,-0.549458,0.082732,0.128584,0.286112,-0.659325,0.540327,0.243823,-0.406607,0.144520,-0.409303,0.579420,0.548604,0.233031,0.428721,-0.566832,-0.249001,-0.390224,0.023109,0.857289,-0.002379,-0.148755,0.549817,-0.061245,-0.348913,-0.240998,-0.034048,-0.445134,0.057504,0.258099,0.303708,-0.348599,0.155965,-0.724122,0.161598,-0.234645,-0.001049,-0.093812,-0.427461,-0.211893,-0.405339,0.018536,-0.660004,-0.354327,0.273824,-0.087389,-0.323383,0.590369,-0.758561,0.186917,0.142259,0.321233,-0.391246,0.800491,0.169862,0.317059,-0.298703,0.204655,0.212624,-0.106276,0.169269,0.179228,0.220298,-0.214415,0.152449,-0.602573,0.500099', '3111650', '1296534', '1308755', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25798448', '解救吾先生', '剧情', '春节假期的夜晚，市中心的酒吧一条街繁华喧嚣，香港电影明星吾先生（刘德华 饰）走出酒吧就被冒充警察的张华（王千源 饰）一伙人持枪绑架到一个与世隔绝的郊外小院里。吾先生意外发现绑匪还绑架了另外一个人质小窦（蔡鹭 饰）经过与张华的一番谈判，吾先生将小窦从死亡线拉回。两人开始了争取生机并相依为命的惊险20小时。接到报案的警方迅速组织最强警力，刑警队长刑峰（刘烨 饰）和曹刚（吴若甫 饰）联手展开侦破工作。但狡猾狂妄的绑匪张华有很强的反侦察能力，对同伙和人质也都不讲规矩，单独出门与吾先生的好友（林雪 饰）交收赎款。但是他在取得赎金之际交代同伙到晚上九点，无论能不能拿到赎金都要将人质杀害。经过几番侦查和对抗，警方掌握了张华的行踪，邢峰和曹刚精准配合，在极度危险的情况下将张华抓获。此事离绑匪约定好的撕票时间还剩下两个小时。深夜九点即将到来，邢峰和曹刚再次联手与垂死挣扎的张华展开心里较量，并在最后时刻找到突破口，但张华的同伙却打算提早撕票……影片改编自2004年的“吴若甫绑架案”。', '刘德华', '丁晟', 7.7, 391835, 'tt4819560', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2267511583.jpg', 0.4, 2, 26.5, 52.8, 18.3, '0.210652,-0.004079,-0.490198,0.283154,0.023918,-0.135570,0.541273,-0.049083,-0.390632,-0.342304,0.274881,0.307425,-0.169493,0.105720,0.390923,-0.185771,-0.528091,-0.738516,0.136519,-0.186875,-0.335934,-0.678208,-0.148216,-0.181267,0.145790,0.081234,0.332550,0.120587,-0.005898,0.509782,0.094511,-0.133752,-0.373151,0.452246,-0.192997,-0.075952,0.154769,-0.158528,-0.547262,0.390575,0.126683,-0.270790,-0.213978,-0.053840,0.146092,0.528958,0.623361,0.010384,-0.292905,0.148103,0.241244,-0.365527,-0.068973,0.066980,0.490448,0.035314,0.235298,0.429269,-0.305166,0.090382,0.028137,-0.176256,-0.508775,0.408972,-0.053608,-0.048669,-0.375735,0.282088,-0.235907,0.256330,0.209251,-0.351713,0.256536,0.541879,0.089083,0.248716,-0.111404,-0.085571,-0.495381,-0.048202,0.619474,-0.206104,0.233905,0.010008,0.309572,-0.706016,-0.086875,-0.115199,-0.038931,0.040134,0.374472,0.029416,-0.151386,-0.157930,-0.498512,-0.129992,-0.251480,0.092745,0.023267,-0.410426,0.038775,-0.766219,-0.096533,-0.119129,-0.292012,0.589911,0.246650,-0.023495,0.424125,-0.533438,0.005013,0.514091,0.524121,-0.459153,0.483647,0.111942,0.040496,-0.228560,-0.024999,-0.200861,0.312073,0.550853,0.387954,0.234947,-0.159384,-0.210862,-0.338571,-0.129932', '25723905', '1431694', '27126336', '1293374');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25798808', '死亡邮件', '悬疑', '司徒明浩（任泉 饰）和赵勇（乔任梁 饰）是在同一间杂志社工作的同事兼好友，两人相识多年，彼此之间的友谊十分坚固。最近，他们将杂志的焦点聚集到了一宗人体器官倒卖案件之上，在调查取证的过程中，赵勇意外失踪，之后等待着司徒浩明的，则是赵勇的死讯。让司徒明浩没有想到的是，赵勇的死并不是终点，悲剧发生后没多久，杂志社的职员们便开始接陆续收到赵勇发来的死亡邮件。更可怕的是，那些接收到邮件的人们，果真接二连三的死去。死亡的阴影笼罩着整个杂志社，人心惶惶之中，每个人都在暗暗猜测，谁是恐怖杀手的下一个目标，而那名杀手，又究竟是谁。©豆瓣', '任泉', '李彧', 3.6, 4109, 'tt6419578', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2186952703.jpg', 53.9, 25, 14.1, 2.4, 4.7, '0.532168,-0.193336,-0.841950,0.644730,-0.079921,-0.020801,1.029098,-0.040850,-0.855499,-0.167616,0.306431,0.617796,-0.442301,0.541230,0.228605,-0.207105,-0.116890,-0.819074,-0.263752,-0.343491,-0.487995,-0.499270,-0.251175,-0.308691,-0.156671,-0.041043,0.407742,0.232358,0.116632,0.446760,0.528172,0.348987,-0.564926,0.803615,-0.096415,0.177049,0.244147,0.101632,-0.061005,0.213245,-0.059717,-0.368550,-0.260191,0.383302,0.069537,0.460803,0.513409,-0.074833,-0.220866,0.018176,0.436475,-0.387832,-0.170383,0.216251,0.702874,0.127619,0.244816,0.243339,-0.318879,0.072058,-0.176891,0.194421,-0.806839,-0.019817,0.180765,0.400457,-0.568343,0.373235,-0.112210,-0.147985,0.024836,-0.505111,0.488593,0.457638,0.141390,0.328865,-0.010368,-0.121289,-0.403492,0.107661,0.797566,0.062939,-0.342812,0.165449,0.036361,-0.479718,-0.337032,0.131526,-0.361900,0.130366,0.403795,0.201458,0.085959,0.248459,-0.479474,0.013518,0.090805,-0.262079,-0.098622,-0.444700,-0.386844,-0.716968,-0.205258,-0.500030,-0.440719,0.284501,0.053382,-0.287562,0.668041,-0.774881,0.075058,0.311745,-0.082734,-0.583666,0.386903,-0.053329,-0.030431,0.063549,-0.051976,-0.054327,0.479872,0.453038,0.130769,0.286338,-0.254133,-0.215229,-0.175254,0.330697', '25870679', '1301022', '1309297', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25798854', '真幌站前狂想曲', '剧情', '真幌站前的多田便利屋，一对落魄的好友多田启介（（瑛太 饰）和行天春彦（松田龙平 饰）穷困潦倒度过了第三个年头。最近几天里，多田背着行天鬼鬼祟祟，似有隐瞒，原来行天此前有过一个妻子，二人通过人工受孕生下一个女儿小春（岩崎未来 饰）。而今前妻即将前往美国，所以打算将小春暂时放在多田这里一段时间。偏偏行天因过去的一些事件，极度讨厌小孩，这令多田倍感为难。与此同时，街上出现了专门出售有机蔬菜的可疑团体，其负责人小林（永濑正敏 饰）恰恰是某已解散的新型宗教的成员。黑道干部星良一（高良健吾 饰）找到便利屋二人组，要他们查明该组织所称的蔬菜的真相。不久后，行天和小春又意外卷入了巴士劫持事件……本片根据三浦紫苑的原作改编。©豆瓣', '永山瑛太', '大森立嗣', 7.7, 14861, 'tt3422606', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2194199028.jpg', 0.4, 3.1, 29.7, 43.6, 23.1, '0.290508,-0.046559,-0.382004,0.070623,0.188407,-0.226064,0.244148,0.135805,-0.501977,-0.529031,0.145230,0.504478,-0.097735,0.100212,0.358394,0.015481,-0.359347,-0.316697,-0.023367,-0.341967,-0.352748,-0.332466,-0.158042,-0.155916,-0.213776,-0.080898,0.600371,0.005238,0.043320,0.509048,0.210192,0.491924,-0.486560,0.107101,0.063672,0.193079,0.184612,0.084322,-0.355655,0.160036,-0.278563,-0.113135,-0.142989,0.056710,0.185405,0.330567,0.500974,-0.259858,-0.460181,-0.298098,0.316472,-0.032789,-0.304021,-0.102169,0.397604,0.039604,0.207262,0.393603,-0.450730,-0.003384,0.071858,-0.013546,-0.379352,-0.018941,0.021842,-0.018843,-0.452275,0.096125,0.047959,-0.057077,0.091523,-0.407971,0.204818,0.573592,0.354511,0.123062,-0.024674,0.150306,-0.215590,0.093387,0.499199,-0.080802,0.103780,0.229528,0.053240,-0.153229,-0.043259,-0.059728,-0.289490,0.078361,0.230233,-0.017283,-0.072429,-0.098503,-0.458499,-0.154504,-0.033485,0.005225,0.319718,0.043350,-0.152831,-0.379378,0.113283,-0.278074,-0.385988,0.013623,0.033030,-0.058458,0.391841,-0.676160,0.245874,0.355056,0.136383,-0.407685,0.311673,0.063934,0.221565,-0.286988,-0.226716,-0.230116,0.003852,0.252287,0.146413,0.198129,-0.051688,-0.393102,-0.340892,-0.200421', '35030151', '30345227', '2369613', '22555690');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25799331', '废纸板拳击手', '剧情', 'Willie是一个愚笨孤独的流浪汉，没有任何朋友，和他的流浪汉邻居们一样，每天麻木而重复的过着日子，仅仅就只是活着，为了50刀就可以去与人打一场“拳击”。直到有一天，他的睡袋被人抢走，在寻找御寒物件的时候，发现了一本同样孤独并过着不幸生活的小女孩的日记，从此他的生活开始一点点的改变...', '托马斯·哈登·丘奇', '内特·李', 8.2, 12171, 'tt3230660', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2380194237.jpg', 0.5, 2.1, 18.5, 44.4, 34.5, '0.254178,-0.337831,-0.500357,0.599075,-0.544023,-0.224865,1.283001,-0.021158,-0.723640,-0.308263,0.157704,0.760115,0.103732,0.438191,0.006166,0.096351,-0.184616,-0.826354,-0.107587,-0.021591,-0.617987,-0.327622,-0.059091,-0.434780,-0.072427,-0.464838,0.710367,0.074025,-0.133040,0.372977,-0.139534,-0.279964,0.094170,0.882684,-0.712526,0.073045,-0.352712,0.380846,-0.101337,0.136647,0.260439,-0.267998,-0.329434,0.427688,-0.112634,0.371114,0.730009,-0.347361,-0.213906,0.087437,0.224386,-0.115086,-0.244206,0.047606,0.218743,-0.064765,0.317614,0.131124,-0.044132,0.040185,0.250921,0.101234,-0.710203,0.001139,-0.093644,0.259601,-0.805550,1.195495,0.038707,0.030781,-0.030376,-0.503193,0.389530,0.146314,0.095133,0.279176,-0.301705,-0.275037,-0.789407,0.764069,0.850696,-0.108352,-0.368976,0.657874,-0.222236,-0.265583,-0.131729,-0.252206,-0.618386,-0.058194,0.321815,0.086464,-0.847140,0.082441,-0.639557,0.491902,-0.232900,-0.474623,0.177058,-0.653549,-0.178893,-0.297208,0.156798,-0.329978,-0.529631,0.346262,0.022589,-0.599951,0.712539,-1.038829,0.554860,0.994612,0.207251,-0.327347,0.858255,0.052640,-0.150304,0.067458,0.139892,0.413977,0.119743,0.443051,0.388084,0.376770,-0.059291,0.322949,-0.215824,0.877578', '1307561', '26754675', '1308755', '1309172');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25799475', '所罗门的伪证前篇：事件', '惊悚', '故事发生在泡沫经济即将破灭的前夕，白色圣诞节悄然来临。清晨的城东第三中学，洁白无瑕的雪地上惊现一名学生尸体。死者名叫柏木卓也（望月步 饰），是三年二班的学生。他的死令入职不久的班主任（黑木华 饰）忧伤慌乱，而校方则感到前所未有的压力。经警方对现场的检查判断，认定柏木死于自杀。原本事件归于沉寂，谁知数封告发信却激起新的波澜。信中称柏木生前受到同班同学大出俊次（清水寻也 饰）、桥田佑太郎（加藤干夫 饰）、井口充（石川新太 饰）的欺凌，并最终被三人所杀。此后媒体连番恶意解读，家长群情激奋，令这所学校不在平静。作为班长的藤野凉子（藤野凉子 饰）再也无法继续忍受，她决定在校内组织法庭，追查柏木自杀的真相……本片根据畅销推理作家宫部美幸的经典名作改编。©豆瓣', '藤野凉子', '成岛出', 6.6, 7588, 'tt3421614', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2225971911.jpg', 2, 10.1, 50.9, 30.1, 7, '0.031051,-0.084816,-0.376006,0.280730,0.196182,0.052127,0.405502,0.207337,-0.411056,-0.437100,0.120196,0.392865,-0.365699,0.337027,0.190150,-0.332506,-0.215333,-0.662051,-0.052005,-0.208245,0.030170,-0.360575,0.072865,-0.229522,0.026919,-0.254596,0.860531,0.288471,-0.243527,0.501550,0.400182,0.502899,-0.080687,0.251457,0.178178,0.003951,-0.028388,0.321326,-0.120980,-0.025163,-0.153763,-0.621286,0.002828,0.168789,0.079240,0.334219,0.652500,-0.122585,-0.357421,-0.048595,0.588507,-0.343086,-0.134375,0.202697,0.553599,0.112648,-0.049297,0.398191,-0.200633,0.019999,0.002014,0.045673,-0.443387,-0.000913,0.272147,0.325204,-0.208344,0.443250,-0.167177,0.056220,0.032504,0.053938,0.029563,0.102968,0.333296,0.190250,-0.362628,0.068700,-0.010035,0.335895,0.560582,-0.042486,-0.097840,0.044727,-0.201877,-0.305236,-0.003052,-0.077455,-0.098053,0.175794,0.093396,0.308405,-0.079502,0.085897,-0.350023,-0.373565,-0.203388,-0.187026,-0.031333,-0.167316,-0.155045,-0.691416,0.057567,-0.048208,-0.268673,0.003855,0.172342,-0.193898,0.488067,-0.477787,0.274071,0.150818,0.033282,-0.245950,0.231541,0.120115,-0.117915,-0.206694,-0.053188,0.321402,0.157193,0.522645,-0.049788,0.215358,-0.001996,-0.255626,-0.295701,0.154358', '3266509', '2369613', '25723905', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25801066', '西游伏妖篇', '喜剧', '历经千辛万苦，唐僧（吴亦凡 饰）、孙悟空（林更新 饰）、猪八戒（杨一威 饰）、沙僧（巴特尔 饰）这支取经团队朝着最终的目标持续前进，然而这一过程中他们不仅忍饥挨饿，还矛盾频生，似乎随时都有分裂的危险。尤其法师念念不忘死去的段小姐（舒淇 饰），而这件事也成为他和悟空之间矛盾和争吵的根源。在摆脱了蜘蛛精的纠缠后，师徒四人来至充满童趣的比丘国。比丘国王（包贝尔 饰）精神错乱，如同孩子般喜怒无常。国师九宫真人（姚晨 饰）将师徒迎进王宫，虽百般叮咛，却仍引出不少的乱子，甚至还揪出了藏在宫中的狡猾妖怪。冒险仍在继续，师徒间的危机一触即发……©豆瓣', '吴亦凡', '徐克', 5.5, 342667, 'tt5273624', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2411953504.jpg', 14.5, 25.7, 36.1, 16, 7.7, '0.068295,0.056038,-0.764647,0.373432,0.291259,-0.268837,0.649828,0.149692,-0.415146,-0.225930,0.287703,0.158876,-0.434220,-0.078512,0.076757,-0.336654,-0.162829,-0.346578,0.018049,0.014577,0.025067,-0.221100,-0.286165,-0.212943,-0.318155,-0.350489,0.518089,0.286282,0.012140,0.231663,0.222873,0.094565,-0.431436,0.712514,0.088783,0.087583,-0.031360,0.349664,-0.099419,-0.072534,0.105191,-0.278450,-0.077450,0.018999,0.059077,0.402277,0.621270,-0.692795,-0.121386,0.160923,0.225151,-0.166838,-0.106740,0.133390,0.316652,-0.045585,0.148028,0.270700,-0.122267,0.103849,0.084182,-0.152961,-0.264904,0.048139,0.348691,0.053676,-0.424463,0.407095,0.048366,0.159649,0.090389,-0.188554,0.077879,0.510320,0.457646,0.150572,-0.194004,-0.094840,-0.512243,0.106459,0.467608,-0.126575,-0.190601,0.132074,-0.041023,-0.373878,-0.307683,-0.059409,-0.191951,-0.195790,0.366720,0.042408,-0.054388,0.491162,-0.496651,0.015484,-0.246350,0.274041,-0.039649,-0.429251,0.090764,-0.539176,0.064830,-0.480686,-0.131550,0.104786,0.333791,0.036057,0.485352,-0.271747,0.232760,0.417616,-0.054963,-0.341380,0.391551,0.056620,0.243961,-0.303581,-0.414158,0.375141,-0.075827,0.381731,0.281202,0.362887,-0.052781,0.116711,-0.194928,0.058822', '3011051', '21619567', '4724373', '24827406');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25802211', '魔法总动员', '喜剧', '劳伦斯（道格·斯通 Doug Stone 配音）曾经是一名魔术师，某日，他收留了一只流浪的小猫，取名闪电（穆雷·布鲁 Murray Blue 配音）。闪电成为了劳伦斯家中的一份子，很快，它就和别墅里的各种机器人和玩偶们打成了一片。然而，在这欢乐祥和的气氛中，却产生了一丝不和谐的声音，对于闪电的到来，白兔和小鼠的态度一直不是十分友好。某日，为了把雷电赶走，白兔和小鼠想出了一个计划，然而，这个计划却令劳伦斯发生了车祸，受伤住院。劳伦斯离开后，一直觊觎他财产的侄子接管了别墅，并想要将它偷偷卖掉。为了保护自己赖以生存的家园，闪电、白兔和小鼠决定联手，奋起反击。©豆瓣', '信达·亚当斯', '杰里米·德格鲁森', 6.7, 4213, 'tt3148834', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233536668.jpg', 0.9, 9, 52.5, 27.5, 10.2, '0.291207,0.006869,-0.604252,0.582965,-0.158796,-0.201665,0.830686,0.230909,-0.331114,-0.460001,0.032074,0.868313,-0.147994,0.346660,0.070958,-0.014469,-0.181690,-0.685077,-0.313274,0.018748,-0.078858,-0.199363,-0.159557,-0.106744,-0.010861,-0.154346,0.533373,0.067720,-0.131193,0.596902,0.140698,0.290108,0.025875,0.508069,-0.265191,0.114306,-0.103975,-0.142819,-0.082046,0.250832,-0.008698,-0.196022,-0.003261,0.462085,0.053645,0.286996,0.709881,-0.388584,-0.126574,-0.322921,0.137000,-0.462747,0.105575,0.209836,0.152329,0.001417,0.271420,-0.001468,-0.334238,0.068514,0.253528,-0.383746,-0.826576,0.114147,-0.227839,0.197038,-0.540103,0.231118,-0.109328,0.089320,0.204995,-0.449929,0.259529,0.225287,0.155180,0.479947,-0.492878,0.249534,-0.619565,-0.129664,0.666695,-0.252869,-0.209680,0.323324,-0.134925,-0.288031,0.041903,0.096105,-0.151235,-0.232111,0.599477,0.345629,-0.361686,0.261835,-0.740275,-0.183680,-0.336153,-0.292101,-0.212719,-0.648051,-0.074125,-0.504904,-0.083318,-0.282556,-0.310114,0.029231,0.006832,-0.092636,0.449586,-0.980560,0.295087,0.355941,0.388343,-0.198233,0.380944,0.054882,0.202773,-0.054645,0.310306,-0.205566,0.324482,0.260413,0.303607,0.254750,0.203515,-0.175619,-0.363820,0.541368', '2032339', '1301022', '1420088', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25804790', '神探夏洛克：最后的誓言', '剧情', '本集因以电视电影形式报艾美奖评选而被单独列出，改编自原著《米尔沃顿》。华生受朋友请求来到一个年轻人吸毒聚集地，没想到在这里居然遇到夏洛克。华生把夏洛克带回贝克街，惊讶的发现夏洛克有了女友，这位女友正是自己婚礼上的伴娘洁琳。但随后华生发现，夏洛克之所以和自己的伴娘约会是因为在查的案件。夏洛克假装要求婚，混进了讹诈专家马格努森的办 公室，华生也和夏洛克一起，然而就在夏洛克发现马格努森被人威胁的时候，威胁者转过头，这个人竟然是华生的新婚妻子玛丽……', '本尼迪克特·康伯巴奇', '尼克·赫伦', 9, 59520, 'tt2781046', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2164957248.jpg', 0.1, 0.4, 7.3, 34.6, 57.6, '0.617707,-0.156232,-0.507548,0.368682,-0.155610,-0.310640,0.599357,0.103218,-0.422667,-0.461258,0.260084,0.821143,-0.447844,0.256412,0.444870,0.189533,-0.506322,-0.545329,0.250628,-0.118214,-0.178309,-0.603233,-0.020630,-0.436064,0.184863,-0.285532,0.270279,-0.312484,-0.227626,0.350732,0.477046,0.220819,-0.127875,0.526738,-0.055516,0.280238,0.569019,-0.041500,-0.121764,0.454359,0.149394,-0.209988,-0.138980,0.115434,0.000639,0.405612,0.428850,0.022921,-0.170290,0.229917,0.504455,-0.380557,-0.014761,0.155580,0.288864,-0.078258,0.231637,0.084848,0.059182,-0.158568,0.197765,-0.016719,-0.328349,0.407592,-0.163726,0.257400,-0.429223,0.179009,-0.247753,-0.031095,-0.013989,-0.265233,0.412009,0.247697,0.278249,0.103588,-0.070077,-0.035575,-0.590696,-0.136751,0.340052,-0.051478,-0.106143,0.210399,-0.083910,-0.510620,0.206780,-0.062510,-0.382043,0.351161,0.288623,-0.346468,-0.263400,-0.024056,-0.420726,-0.486870,-0.309494,-0.147414,0.110996,-0.228182,-0.120050,-0.891906,-0.040939,-0.035578,-0.288037,-0.110529,0.009525,-0.431286,0.320939,-0.695193,0.103986,0.551884,0.373576,-0.376135,0.860323,-0.002661,0.006216,-0.354160,-0.130182,-0.036239,0.335673,0.205011,0.194140,0.155869,0.169223,-0.225983,-0.248476,0.211207', '1484091', '3326747', '25833539', '2973543');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25805039', '云端之上', '剧情', '埃米尔（艾萨·安哈尔 Ishaan Kapoor 饰）是一个整日里游手好闲的小混混，一天，为了躲避警察的追捕，埃米尔躲进了姐姐工作的洗衣房，姐姐包庇埃米尔的行为被她的老板发现了，老板竟然以此为把柄威胁姐姐想要对她不轨。埃米尔一怒之下袭击了老板，导致老板重伤入院。如果老板死亡，那么埃米尔将因为过失杀人罪而面临牢狱之灾，为了避免这一情况的发生，埃米尔不得不留在医院里，贴身照顾自己的仇人。老板的妈妈（沙拉达 Sharada 饰）得知儿子住院，于是带着两个孙女来到医院探望，这下可好了，埃米尔需要照顾的人又多了三个。祖孙三人的到来虽然给埃米尔带来了很多麻烦，但在处理这些麻烦的过程中，埃米尔也逐渐领悟了人生的真谛。©豆瓣', '艾萨·安哈尔', '马基德·马基迪', 7.5, 13767, 'tt3224288', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2557269966.jpg', 0.6, 3.4, 32.1, 46.4, 17.5, '0.241986,-0.171253,-0.341063,0.216539,-0.311443,-0.433817,0.626203,0.450305,-0.731432,-0.482173,0.264488,0.498835,0.070286,0.225602,0.371265,-0.042357,-0.222129,-0.370318,0.053424,-0.089330,-0.295117,-0.521545,-0.085957,-0.387519,-0.051267,-0.356912,-0.007820,0.145264,-0.109585,0.165670,0.151814,0.226653,0.003927,0.598695,0.057642,0.111316,0.129808,-0.270309,-0.335485,0.442938,0.364347,-0.353301,0.215242,0.269286,0.180970,0.414723,0.667350,-0.202242,-0.316138,-0.324830,0.330483,-0.505414,0.130067,0.074707,0.264208,-0.081518,0.409717,0.150381,-0.383774,0.065252,0.144180,-0.151375,-0.744173,0.159565,0.155692,-0.054231,-0.817584,0.194239,-0.120063,0.033200,-0.006380,-0.208117,0.584279,0.547185,0.009885,0.343079,-0.288303,-0.043668,-0.604774,-0.228321,0.644787,-0.467896,0.472192,0.204375,-0.048522,-0.168435,0.228601,-0.251468,-0.366894,0.184609,0.178673,-0.189237,-0.279977,0.094621,-0.391555,-0.113156,-0.612633,-0.258141,-0.107386,-0.557256,0.070560,-0.245400,0.162251,-0.048633,-0.263661,0.025650,0.239856,-0.140631,0.557348,-0.636279,0.242243,0.728525,0.427366,-0.742504,0.408581,0.083723,0.282881,-0.192395,-0.051077,-0.082214,0.273138,0.329579,0.208754,0.120572,0.207788,-0.347495,-0.067734,-0.013668', '1877596', '1292584', '1299965', '1417543');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25805054', '十万个冷笑话', '喜剧', '剧版《十万个冷笑话》第二季第 6 集中， 没有名字的男主角（阿杰 配音）在打败鸟不拉屎大王之后，因自身的吐槽能量大爆发而导致地球遭受了空前绝后的大灾难，电影版的故事便从此开始。在灵魂中转站中， 男主角意外去到了神秘的“时之狭间”，在神秘人物的帮助下改写了地球被毁的历史，并回到过去成为了拯救地球的英雄；但是意料之外的事情发生了，时空发生混乱，不同维度的二次元人物穿越到了男主的世界， 男主更是邂逅了神话中的李靖（宝木中阳 配音）和哪吒（山新 配音），童话中的白雪公主（朱雀橙 配音）和匹诺曹（皇贞季 配音），为了扭转错乱的时空，众人一起踏上了再次拯救地球的旅程……©豆瓣', '张杰', '卢恒宇', 6.6, 106144, 'tt4320236', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217523448.jpg', 4.2, 12.7, 43.7, 28.2, 11.2, '0.309570,0.350765,-0.821094,0.546486,0.132380,-0.141997,0.624729,-0.052462,-0.252128,0.034639,0.124834,0.880102,-0.471901,-0.008871,0.421809,0.027159,-0.180645,-0.638647,-0.053240,-0.280730,-0.419737,-0.298195,-0.299784,0.115420,-0.107357,-0.484420,0.743814,0.175096,-0.523484,0.251746,0.091110,0.210162,-0.365404,0.526794,-0.024446,0.532721,-0.003548,0.259086,-0.157237,0.243494,-0.089027,-0.248279,0.054368,0.309947,-0.411960,0.063270,0.737560,-0.602366,-0.020658,-0.208000,0.592792,-0.285310,-0.472581,-0.307502,0.382785,0.072600,-0.010018,0.219146,0.173088,0.274478,0.087808,-0.220613,-0.807633,-0.123007,-0.004947,0.378117,-0.355112,0.420293,0.133345,-0.132682,0.189818,-0.105548,0.421516,0.201468,0.844276,0.416359,-0.262065,0.110028,-0.218654,0.361942,0.535452,-0.038998,-0.617495,0.684075,0.077536,-0.514423,-0.479302,-0.118727,-0.348989,0.173550,0.350831,0.232671,-0.312604,0.642440,-0.708485,-0.140251,-0.006649,-0.278040,-0.027457,-0.223340,-0.210990,-0.648181,-0.402253,-0.106625,0.173468,-0.048273,0.228890,-0.272197,0.681226,-0.801829,0.245154,0.522986,0.115063,-0.438289,0.524103,-0.014027,0.121781,-0.290550,0.323356,0.080004,-0.129754,0.791323,0.090905,0.270598,-0.299553,-0.149465,-0.682493,0.757914', '25928048', '26759819', '26759820', '1303263');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25805741', '后会无期', '剧情', '故事开始于虚构的中国最东边的小岛“东极岛”，智力低下的青年胡生（高华阳 饰）讲述了关于他的两个哥们儿——马浩汉（冯绍峰 饰）和江河（陈柏霖 饰）的故事。浩汉在外闯荡多年后回到故乡，却发现全岛面临着拆迁问题，而他最好的朋友，岛上唯一的老师江河也将被调到更为偏远的地区。于是 浩汉做出了一个决定，那就是开车送江河去三千多公里外的学校报到。兄弟三人踏上了前所未有的旅程，途中他们见了当临时演员的童年玩伴周沫（陈乔恩 饰），误入歧途的苏米（王珞丹 饰），还有浩汉心仪多年从未见面的笔友刘莺莺（袁泉 饰），以及不羁的摩托车手阿吕（钟汉良 饰）。看似平常的旅程却暗藏伏笔，浩汉和江河最终走到了终点，开始了截然不同的人生轨迹。本片是著名作家兼赛车手韩寒的电影导演处女作。©豆瓣', '冯绍峰', '韩寒', 7.2, 588870, 'tt3896016', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2195469915.jpg', 2.2, 6.9, 37.3, 37.8, 15.7, '0.327551,-0.154739,-0.529046,0.777476,0.113859,-0.395951,0.670114,0.122381,-0.585603,-0.160840,0.164192,0.734221,-0.130190,0.222596,0.328235,-0.173708,-0.228482,-0.549718,-0.138291,-0.174298,-0.243478,-0.311095,-0.143323,0.156152,-0.109314,-0.090189,0.546486,0.094311,-0.134155,0.516752,0.229001,0.126040,-0.176170,0.243778,-0.282684,0.126151,0.010200,0.253440,-0.372057,0.213166,0.033743,-0.212981,-0.138866,0.051940,-0.143354,0.418567,0.758468,-0.019532,-0.176991,0.160842,0.406936,-0.221555,-0.010576,-0.242854,0.231301,0.045322,0.296096,0.286872,-0.102024,0.105525,0.067416,-0.193748,-0.385813,0.014065,0.105123,0.135164,-0.639436,0.468383,0.095035,-0.250973,0.243384,-0.456372,0.144667,0.166346,0.207769,0.347126,-0.117858,-0.027004,-0.326597,0.494301,0.562391,0.061485,-0.198620,0.380553,0.098007,-0.373796,0.037194,-0.101392,-0.331463,0.149734,0.251172,-0.066299,-0.111304,0.070756,-0.800143,0.081920,-0.086484,-0.273743,0.119419,-0.328490,-0.183912,-0.601648,0.014821,-0.460542,-0.044596,0.144084,0.134493,-0.109784,0.747088,-0.673792,0.051476,0.351795,0.074287,-0.498125,0.667844,-0.028008,0.066909,-0.327131,0.256058,0.229587,-0.211447,0.500831,-0.028847,0.325499,-0.324855,-0.370839,-0.529466,0.415780', '1414808', '3811356', '1296769', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25806368', '呼吸', '剧情', '十七岁的查理（Joséphine Japy 饰）乖巧懂事，是个十分讨人喜欢的女孩，和大部分同龄的姑娘们一样，查理对未来充满了美好而又光明的幻想。莎拉（Lou de Laâge 饰）满头金发，走在校园里十分惹眼，而她的性格和她的发色一样张扬而高调，萨拉向往无拘无束的自由生活，几乎就是循规蹈矩墨守成规的查理的对照面。在充满了青春活力的校园中，这两个个性截然相反的女孩相遇了，只一眼，查理就被奔放开朗的萨拉给深深吸引。随着时间的推移，两人越走越近，最终成为了无话不谈的闺中密友，然而，交往的深入带来的却是友情的裂痕，无论是查理或是莎拉，都无法阻止这裂痕越来越大。©豆瓣', '约瑟芬·约比', '梅拉尼·罗兰', 7, 7450, 'tt3365778', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204598428.jpg', 1, 7.3, 46.5, 33.4, 11.8, '0.566076,-0.048851,-0.627925,0.732193,-0.399440,-0.360927,1.191971,0.137485,-0.416241,0.093831,0.035275,0.905198,-0.395358,0.212064,0.349079,-0.033842,-0.246124,-0.665098,-0.308055,-0.242440,-0.124221,-0.505593,-0.214691,0.102415,-0.133465,-0.315085,0.714134,-0.160014,-0.145910,0.870914,0.327666,0.160361,-0.006155,0.438541,-0.464298,-0.044749,-0.015504,0.110012,-0.029913,-0.072551,0.090445,0.116509,-0.087748,0.214964,-0.232146,0.269978,0.783937,-0.371795,-0.146155,-0.049870,0.685794,-0.064867,-0.143906,0.322033,0.276327,0.139575,0.107714,-0.176698,-0.231423,-0.040546,-0.064071,0.084878,-0.620737,0.417749,0.194401,0.253725,-0.614552,0.673649,0.417651,-0.517897,0.386020,-0.446771,0.097685,0.097950,0.108601,0.440134,-0.144218,0.040217,-0.342453,-0.094484,0.592856,0.279369,-0.633993,0.601127,-0.788961,-0.288288,-0.132276,-0.233259,-0.720868,-0.395656,0.306044,0.073138,-0.050888,0.529178,-0.699847,0.312667,-0.078094,-0.343657,-0.045435,-0.563521,-0.252670,-0.649780,-0.481040,-1.210024,-0.417527,0.160794,-0.016896,-0.118315,1.033842,-0.937267,0.268415,0.444597,0.179706,-0.528994,0.843147,0.504126,0.034806,-0.086479,-0.109793,0.549716,0.024131,-0.051500,0.095441,0.678301,-0.350104,-0.179342,-0.614440,0.847398', '25928069', '1292062', '24756472', '5029050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25806460', '杀人者', '惊悚', '在一个远离都市喧嚣的乡村小镇，懦弱无言的少年任龙浩日常饱受同学的欺负。某天，有着破碎家庭的女孩韩智秀随母亲转学来到这里，许是相同的境遇和心情，让少男少女从最初的排斥、警惕、与好奇，最终变得熟稔，俨然成为无话不说的好朋友。某个晚上，智秀接醉酒的妈妈回家，途中刚好遇到龙浩的爸爸朱协（马东锡 饰）。朱协开卡车载着母女回家，然而智秀却惊讶地发现朱协似曾相识，深藏脑海中的恐怖记忆不可遏止地浮现出来，这是龙浩自己都不曾知晓的关于父亲的秘密。一连串的事件，让看似敦厚平静的朱协，其灵魂深处嗜血的欲望再度勃发……©豆瓣', '马东锡', 'Lee Gi-wook', 5.9, 10517, 'tt3976234', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2165374843.jpg', 5.7, 24.4, 46.3, 16.4, 7.1, '0.462870,-0.043284,-0.764932,0.525697,0.022719,-0.207065,0.816425,0.132326,-0.589940,-0.349422,0.125286,0.575555,-0.247675,0.575951,0.369796,0.010654,-0.104510,-0.528747,-0.368563,-0.046175,0.117434,-0.304695,-0.165328,-0.042221,0.123523,-0.301130,0.472512,0.335801,-0.177103,0.841854,-0.045136,0.371760,-0.421146,0.564902,-0.170070,-0.062233,-0.262907,0.110051,-0.222966,-0.216225,0.141162,-0.023266,-0.058856,0.230532,-0.097417,0.328556,0.720888,-0.011414,-0.515407,0.304186,0.503086,-0.001611,-0.194110,0.000362,0.139433,0.237927,0.086381,0.038209,-0.085447,-0.012080,0.022553,0.114780,-0.487182,0.195703,0.145879,0.130982,-0.353802,0.436062,0.141040,-0.108741,0.265286,-0.358692,0.245844,0.096790,0.121175,0.765890,-0.278540,0.262817,-0.244052,-0.022872,0.694720,-0.083151,-0.278969,0.230816,-0.370806,-0.244762,0.152972,-0.198181,-0.535311,0.053657,0.023198,0.370630,-0.471001,0.517961,-0.526069,-0.109407,-0.154696,0.059710,0.077607,-0.366894,-0.437619,-0.453030,-0.330418,-0.341064,-0.241034,0.206397,-0.169151,-0.067694,0.662791,-0.897925,0.421827,0.341695,0.148265,-0.318986,0.476374,-0.020287,-0.157880,-0.193147,-0.130166,0.375439,-0.008062,0.179860,-0.227674,0.224689,-0.276201,0.107423,-0.536905,0.329343', '2365260', '1296534', '1292219', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25807345', '彗星来的那一夜', '科幻', '在一个静得有些诡异阴森的夜晚，年轻女子艾米丽（艾米丽·芭尔多尼 Emily Baldoni 饰）驱车来到朋友家参加聚会。此前她一边开车一边和男友打电话，然而通话突然中断，她的手机屏也莫名其妙出现裂痕。这一事件让艾米丽的心中升起隐隐不安，因为当晚一颗彗星刚好接近地球，一个 很久之前听过的传说使她对彗星的到来有着不祥的预感。稍后，朋友们落座，大家彼此交谈，叙说近况，虽然言语中有着许多莫名其妙、蹊跷反常的线索，然而均被一带而过。突然间，灯光尽灭。当光明重新来临时，众人发现附近只有一户人家还在亮灯，而亮灯人家里坐着的竟是……本片荣获2014年阿姆斯特丹奇幻电影节黑郁金香奖。©豆瓣', '艾米丽·芭尔多尼', '詹姆斯·沃德·布柯特', 8.5, 524660, 'tt2866360', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2187896734.jpg', 0.4, 1.2, 12.1, 43.6, 42.8, '0.296705,0.177261,-0.841544,0.442229,0.422744,0.002159,0.783700,0.060295,-0.763305,-0.534038,0.274735,0.698624,-0.789793,0.445452,0.339055,0.007483,-0.389820,-0.452811,0.189111,-0.176958,-0.195181,-0.263599,-0.251090,-0.186015,0.024311,-0.109462,0.042660,0.257383,-0.108178,0.793910,0.076529,0.157687,-0.343188,0.786676,-0.135059,-0.298508,0.119119,0.128978,0.053517,-0.066100,-0.043576,-0.221849,-0.296626,0.118707,0.000911,0.419450,0.381336,-0.062832,-0.473228,0.321760,0.292688,-0.064325,-0.146868,-0.046090,0.415261,0.316031,0.137568,-0.158490,-0.109059,0.150995,-0.180515,0.023356,-0.337117,0.510170,-0.239451,0.504967,-0.170560,0.248338,-0.045829,-0.061696,0.070184,-0.319072,0.433225,-0.073197,0.185134,0.456849,-0.202337,0.076427,-0.279809,-0.188397,0.608562,0.153969,-0.168553,0.398072,-0.140109,-0.345103,0.051492,0.517975,-0.230576,0.090041,0.368407,0.129065,0.176806,0.082418,-0.709354,0.040942,0.026889,-0.107497,-0.030348,-0.297841,-0.221504,-0.638465,-0.112779,0.001707,-0.529649,0.261166,-0.014842,0.009776,0.425684,-0.689758,0.448976,0.343645,0.133651,-0.120906,0.434218,-0.023711,-0.049514,-0.100574,-0.217642,0.231309,0.000740,0.280102,-0.089034,0.164501,-0.454957,-0.076213,-0.411825,0.067206', '25856453', '3011051', '3267195', '1292869');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25808075', '猩球崛起3：终极之战', '剧情', '凯撒（安迪·瑟金斯 饰）领导的猿族将被迫与残暴的Colonel（伍迪·哈里森 饰）领导的人类军队上演一场生死大战。猿族在战斗中遭遇了前所未有的重创，由此激发了凯撒内心中黑暗的一面，心中燃起复仇的烈火。最终，凯撒与Colonel面对面进行了一场关乎猿族和人类命运的终极之战。', '安迪·瑟金斯', '马特·里夫斯', 6.9, 211018, 'tt3450958', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494096554.jpg', 1.6, 8.4, 43.6, 36, 10.4, '0.072996,0.164944,-0.856805,0.799227,0.434938,-0.133447,0.917384,-0.058225,-0.323086,0.047927,0.624388,1.009381,-0.425088,-0.031529,0.471550,-0.422600,-0.185231,-0.889739,-0.471081,0.379964,-0.041622,-0.242506,-0.717788,-0.025923,0.039778,-0.298752,0.990937,0.253346,-0.471691,0.444576,0.203824,0.564397,-0.125284,0.223359,0.138517,-0.179717,0.000233,0.060107,-0.478711,0.160480,0.206261,-0.135142,-0.179521,0.614950,-0.170337,0.255372,0.661721,-1.084544,0.126468,-0.600275,0.204588,-0.578529,-0.068988,0.431892,0.304967,0.115938,0.037814,0.367567,0.181698,-0.158638,-0.078968,0.063569,-0.999695,-0.124248,-0.055539,0.014754,-0.445036,0.814463,0.220139,0.279704,0.380283,0.217520,0.244545,0.673090,0.567789,0.334777,-0.223936,-0.327806,-0.389729,-0.223744,1.058311,-0.343499,-0.217769,-0.144852,-0.138946,-0.584999,-0.372120,-0.509398,-0.497769,-0.305285,0.533429,0.143786,0.190360,0.913496,-1.126096,-0.144658,-0.485796,-0.232215,-0.035194,-0.300995,0.184646,-0.764059,-0.600021,-0.449802,-0.356183,0.131179,0.118398,-0.112267,0.617636,-0.972834,0.118529,0.219560,0.149857,-0.137929,0.333768,0.275279,0.582775,-0.101796,0.163577,0.279592,-0.178172,0.523567,0.314235,0.333241,0.001062,0.338451,-0.239940,0.629317', '26759819', '25828589', '1308837', '19899707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25809101', '涉外大饭店2', '剧情', '金盏花大酒店客满为患，穆瑞尔（玛吉·史密斯 Maggie Smith 饰）和桑尼（戴夫·帕特尔 Dev Patel 饰）开始寻找起了下一个“据点”——玛丽戈德大饭店，在那里，美好的图景展开，两人的事业将走上另一个高峰。玛琪（西莉亚·伊姆瑞 Celia Imrie 饰）终于邂逅了她的真命天子，只是天子的数量竟然有两位，一时之间，玛琪不知道改选哪个才好。桑尼即将和女友奈娜（蒂娜·德赛 Tina Desai 饰）携手步入婚姻的殿堂，但前提是，忙于工作的他得能抽得出时间参加他自己的婚礼。与此同时，诺曼（罗纳德·皮卡普 Ronald Pickup 饰）和卡罗（黛安娜·哈卡索 Diana Hardcastle 饰）亦从两人纠缠不休的感情漩涡里找到了未来的新的方向。©豆瓣', '比尔·奈伊', '约翰·马登', 6.8, 6429, 'tt2555736', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2225230659.jpg', 1, 8.7, 50.7, 29.9, 9.7, '0.353148,0.211212,-0.584015,0.546826,0.009375,-0.478651,0.746999,0.211352,-0.326039,-0.150021,0.183792,0.672253,-0.164363,0.332139,0.467059,0.376044,-0.433245,-0.775340,0.066860,-0.133991,-0.318974,-0.463584,-0.503335,-0.124311,-0.068017,-0.151170,0.401016,0.079837,0.162211,0.256744,0.490584,0.228834,-0.050608,0.349169,-0.064751,0.030610,0.288535,0.141122,-0.315176,0.189415,0.057564,-0.226168,-0.282787,0.262595,0.078505,0.402883,0.417943,-0.250397,0.178431,-0.142709,0.236832,-0.083306,0.151606,0.142839,0.127222,-0.176530,0.158031,0.137122,-0.265709,0.040566,0.286527,-0.180904,-0.592673,0.111486,-0.012482,0.250100,-0.614366,0.384316,-0.297395,-0.296722,0.095132,-0.294148,-0.041242,0.561616,0.247513,0.223987,-0.213776,-0.163997,-0.542545,0.118919,0.520350,0.256732,-0.235415,0.249079,-0.090504,-0.485946,-0.189862,0.107558,-0.325784,-0.316044,0.458535,0.104733,0.122428,0.157481,-0.634628,-0.012083,-0.374279,-0.238341,0.076873,-0.278099,-0.132158,-0.820441,-0.033051,-0.355070,-0.295277,-0.008184,-0.038847,-0.259517,0.493533,-0.811596,0.048118,0.303371,0.152068,-0.300916,0.800892,0.036040,0.304889,-0.181830,0.112941,0.142822,-0.269579,0.196857,0.153342,0.482582,0.079741,-0.114252,-0.469994,0.625011', '3055049', '11541282', '1301686', '7154463');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25809260', '工作女郎', '喜剧', '白宝熙（赵茹珍 饰）是在玩具公司上班的女白领，业务能力极强的她是公司里的销售精英，事业心爆棚的她也愿意将大部分的时间都投入到工作中，自然冷落了家里的老公和女儿，时间久了，白宝熙和老公之间的交流少了很多，夫妻之间的感情渐渐淡漠。一天，白宝熙正在进行一个非常重要的会议，哪知道在产品呈现的环节，她竟然错拿了邻居南希（克拉拉 饰）的情趣用品。克拉拉经营着一家情趣用品点，愤怒的白宝熙杀到她的店里准备兴师问罪，哪知道却意外的被琳琅满目的店内商品打开了新世界的大门，极富商业头脑的白宝熙在享受着快乐的同事开始盘算着进军情趣用品界的打算。©豆瓣', '曹汝贞', '郑范识', 6.5, 21230, 'tt4455690', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2215722769.jpg', 2.3, 12.8, 50.8, 25.7, 8.4, '0.558654,0.186139,-0.747857,0.387143,-0.147811,-0.266973,0.514803,0.238357,-0.516139,-0.105064,0.003506,0.482707,-0.008455,0.438401,0.213269,-0.024031,-0.058617,-0.714044,-0.211601,-0.347258,-0.186245,-0.356525,-0.355178,-0.191036,-0.034258,-0.164807,0.263061,0.105209,-0.019708,0.316401,0.277098,-0.083637,0.019619,0.645858,-0.074028,-0.119662,0.273250,0.041401,-0.294497,0.092319,0.177350,-0.123753,-0.022937,0.131585,0.316267,0.421859,0.469481,0.024947,-0.302009,0.193615,0.550860,-0.030437,-0.062374,0.085777,0.430414,0.252516,0.240812,0.101283,-0.415824,0.155795,0.125887,-0.031065,-0.900997,-0.164560,0.086768,0.118938,-0.799293,0.758910,-0.048856,-0.172426,-0.029104,-0.432224,0.294388,0.440963,0.099541,0.492440,-0.010724,0.093393,-0.704133,0.225382,0.508893,-0.045668,-0.048221,0.546559,-0.234848,-0.312202,-0.240962,-0.232975,-0.401984,-0.373803,0.228174,0.070256,-0.105504,0.076977,-0.787680,0.199051,0.157870,-0.462882,0.084362,-0.477396,-0.078127,-0.703609,-0.007485,-0.519797,-0.214958,0.208657,0.321782,-0.121433,0.737669,-0.996554,-0.001368,0.653879,0.448646,-0.567582,0.848150,-0.144341,0.072423,-0.228354,-0.379214,-0.195935,-0.122906,0.291475,0.147880,0.623227,0.156995,-0.274095,-0.541863,0.553241', '1793491', '2124718', '1783461', '21360412');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25809384', '极盗者', '动作', '年轻的FBI特工强尼·犹他（卢克·布雷西 Luke Bracey 饰），潜伏到一队喜欢寻找刺激挑战的盗匪里，该队伍由富有个人魅力的鲍迪（埃德加·拉米雷兹 Édgar Ramírez 饰）领导。这些盗匪被怀疑是在用极不寻常的方式进行着系列犯罪。在与鲍迪这一伙人的交往中，犹他发现自己无可自拔的与这伙人产生了伙伴情谊，犹他陷入了职业伦理与追求真我之间的矛盾，他放弃了自己的一切，加入到了对人类极限界的八项巅峰挑战的追寻中……', '埃德加·拉米雷兹', '埃里克松·科尔', 7.1, 107950, 'tt2058673', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2301979501.jpg', 1.5, 8.3, 38.7, 34.3, 17.2, '0.763538,-0.119866,-0.701369,0.681117,-0.334323,-0.076598,0.759888,-0.084222,-0.615239,-0.050916,-0.000467,0.713348,-0.027347,0.063997,0.300158,-0.095233,-0.057921,-0.769529,-0.142865,-0.263867,-0.278399,-0.512464,-0.549348,-0.084401,-0.353005,-0.424078,0.636802,0.185726,-0.644833,0.319037,0.373006,0.670846,-0.100847,0.434384,-0.075949,-0.063853,0.285536,-0.067138,-0.346329,0.209656,-0.017871,-0.140709,-0.050419,0.284149,-0.273368,0.194574,0.669538,-0.452246,0.100640,0.034192,0.207319,-0.405520,-0.142247,0.277626,0.461151,-0.027238,-0.094227,0.284121,-0.019773,0.271229,-0.168290,0.049772,-1.027270,-0.207118,0.111536,0.187016,-0.697451,0.343163,-0.073484,-0.307457,0.149305,-0.178371,0.080406,0.382494,0.162484,0.243608,0.010421,-0.454202,-0.567708,0.014985,1.031204,-0.044516,-0.303827,0.083329,-0.202495,-0.555092,-0.262833,-0.472607,-0.530181,-0.377058,0.255415,0.062501,-0.154808,0.255290,-0.837104,0.298369,0.116411,-0.054811,-0.313675,-0.493166,0.130855,-0.517770,-0.280484,-0.761361,-0.283724,0.169085,0.089697,-0.260211,0.676484,-1.025195,0.088084,0.705195,0.506344,-0.494172,0.714757,0.084475,0.080656,-0.289298,-0.219690,0.244017,0.043525,0.268013,0.208530,0.477397,-0.072639,-0.058677,-0.487968,0.529880', '1793491', '1874704', '25828589', '25917239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25810920', '潜龙风云', '剧情', '杨明（黄秋生 饰）在黑道中浸淫多年，早已经爬到了大哥的地位，可是，多年的摸爬滚打让杨明感到疲惫不堪，他只希望能够卸下帮派之中的繁杂事务，过一种平静的生活。一次偶然中，杨明结识了名叫阿媚（蔡卓妍 饰）的茶餐厅老板娘，阿媚的温柔和善良让杨明印象颇深，随着时间的推移，杨明渐渐爱上了阿媚。然而，杨明并不知道的是，自己手下的小弟阿良（黄又南 饰）亦对阿媚有着特殊的感情，两个男人之间的关系因为阿媚的存在而变得暗流涌动。与此同时，比尔一直在打着杨明店铺的主意，看到杨明和阿媚交往甚密，他决定将进攻的目标放在阿媚的身上。杨明和阿媚都不知道，他们正在渐渐陷入一场阴谋之中。©豆瓣', '蔡卓妍', '李保樟', 5.5, 6656, 'tt4141260', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2208594089.jpg', 18.5, 23, 35.2, 10.2, 13, '0.351954,0.025936,-0.737049,0.682316,-0.169248,-0.254829,0.851205,0.031451,-0.963891,-0.244693,0.254869,0.594629,-0.151510,0.265365,0.180076,-0.162215,-0.043810,-0.870937,-0.258377,-0.186106,-0.083767,-0.580496,-0.416075,-0.052293,-0.306382,-0.334961,0.590466,0.116526,-0.179148,0.651723,0.404191,0.129187,-0.357801,0.804253,0.012615,-0.052670,0.122085,0.040411,-0.301840,-0.091700,0.254622,-0.146132,-0.038930,0.091788,0.113292,0.297489,0.735349,-0.237098,-0.191460,0.146875,0.092279,-0.132771,-0.124949,0.073168,0.275830,0.210331,0.229660,0.295012,-0.351810,0.007804,-0.073856,0.024533,-0.634035,0.109841,0.219055,0.237903,-0.670776,0.599393,0.080875,-0.397937,0.025847,-0.454395,0.307979,0.324860,0.376967,0.337487,-0.158831,0.028048,-0.270828,-0.126493,0.768501,0.033280,-0.059971,0.506900,-0.307678,-0.284595,-0.202727,0.004877,-0.296184,-0.202893,0.261350,0.147242,-0.295889,0.342713,-0.533213,0.213014,0.083826,-0.244411,-0.091694,-0.437657,-0.046540,-0.259174,-0.711903,-0.772931,-0.296275,0.213823,-0.107331,-0.256876,0.679012,-1.077263,0.172099,0.210119,0.159044,-0.355468,0.606686,0.114345,0.038540,-0.288705,-0.154343,0.121188,-0.134912,0.016497,0.255119,0.415035,-0.363843,-0.221697,-0.358527,0.464885', '35030151', '1301022', '1308755', '21766698');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25811357', '冲锋车', '喜剧', '曾经在黑道中呼风唤雨的发哥（吴镇宇 饰）在挨过了漫漫十六年的牢狱之灾后终于重获自由，然而，刚刚出狱没多久，发哥便决定着手实施他在狱中早已经设计好的惊天劫案。于是，机械高手丧宝（任达华 饰）、造型师杜公子（谭耀文 饰）、飞车辣手林东（郑浩南 饰），这些昔日弟兄们重新聚首，将目标放到了一辆运送黑钱的运尸车上。徐安良（古巨基 饰）是一名警员，恪尽职守的他敏感地发现了发哥的计划，尽管没有得到上级的批准，但他还是决定依靠自己的力量将这一帮犯罪分子们一网打尽。就在情势越来越紧张之时，一帮悍匪加入了战局，成为了发哥一行人的“竞争对手”，复杂的情境之下，究竟谁会是最后的赢家呢？©豆瓣', '吴镇宇', '刘浩良', 6.7, 38777, 'tt4533838', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2233196307.jpg', 2.6, 10.6, 46.8, 31.4, 8.5, '0.195960,0.179714,-0.613067,0.436284,-0.184948,-0.290239,0.471282,0.010394,-0.506222,-0.123727,0.489168,0.546593,-0.055759,0.194657,0.254909,-0.098363,-0.274434,-0.844125,-0.139731,-0.163508,-0.293138,-0.304834,-0.428535,-0.083760,-0.014426,-0.116720,0.563153,0.290846,0.030773,0.245632,0.478240,0.075535,-0.082656,0.548052,-0.316807,0.061142,0.322284,-0.092585,-0.209941,0.126822,-0.043092,-0.558690,-0.256457,0.225948,0.049928,0.332524,0.617493,-0.245626,-0.184751,0.093695,0.269580,-0.330235,-0.052510,0.084371,0.318721,0.042771,0.100427,0.198781,-0.186726,0.110053,0.018356,0.100373,-0.650864,-0.127916,-0.082012,0.014405,-0.692707,0.192377,-0.144279,0.012283,-0.107124,-0.336048,0.248299,0.439776,0.212021,0.152987,-0.079244,-0.062681,-0.495087,0.357800,0.668003,-0.074496,-0.108916,0.301250,0.174654,-0.647858,-0.190632,-0.179237,-0.266368,-0.230311,0.632442,-0.033320,-0.118666,0.049902,-0.480135,-0.142787,-0.196339,-0.124523,-0.172799,-0.198379,0.102223,-0.390660,-0.224929,-0.356003,-0.207055,0.224439,0.033757,-0.131925,0.736971,-0.699297,0.084103,0.400844,-0.031444,-0.578124,0.255861,0.036339,0.218168,-0.043043,-0.043423,-0.274080,0.008395,0.507654,0.393890,0.535610,-0.177428,-0.413355,-0.235032,0.265989', '1301022', '1917313', '1292829', '24756658');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25812513', '杰克', '剧情', '杰克（艾沃·皮茨克 Ivo Pietzcker 饰）跟弟弟一起和母亲过着相依为命的生活，杰克的母亲是一个极为不负责任的女人，白天工作结束后，她便乔装打扮外出找乐子，照顾弟弟的全部责任就落在了杰克一人的身上。杰克对母亲身边经常更换的男友抱有强烈的敌意，母子之间的感情因此十分脆弱。某日，杰克的弟弟不幸被烫伤，社会福利机构勒令母亲必须将两个孩子之一送往福利院，母亲选择了杰克。在福利院里，杰克日日夜夜的思念担心着母亲和弟弟，终于，逃跑成功的他返回家中，却发现母亲丢下了弟弟不知所踪。带着弟弟，杰克踏上了充满了危险和未知的寻母之旅。©豆瓣', '艾沃·皮茨克', '爱德华·贝尔格', 8.1, 7694, 'tt3469918', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2170035518.jpg', 0.4, 0.9, 17.2, 55.7, 25.7, '0.083373,-0.244438,-0.785839,0.539627,-0.256648,-0.535131,0.914033,0.157213,-0.615197,-0.205630,0.140225,0.847747,0.172202,0.687801,0.287095,0.111937,-0.389615,-0.648172,-0.363107,-0.057658,-0.473181,-0.609376,-0.039780,-0.058777,-0.104692,-0.332380,0.396972,-0.271173,0.092491,0.556884,0.167223,0.262439,-0.433698,0.714885,-0.204761,0.157001,-0.077116,-0.024602,-0.349200,0.185909,0.466246,0.053180,0.151276,0.120305,0.141896,0.385253,0.865560,-0.169893,-0.060042,-0.290241,0.220407,-0.160428,0.113983,0.112125,0.266703,0.121835,0.453351,0.194500,-0.166652,-0.172124,0.108312,-0.159629,-0.451850,0.127260,0.172146,-0.097464,-0.896525,0.393977,-0.165807,0.091935,0.363131,-0.537965,0.544442,0.375061,-0.106513,0.655615,-0.463391,0.238972,-0.297112,0.059119,0.575197,-0.451894,0.261971,0.102268,-0.203212,-0.067941,0.364721,-0.211808,-0.608918,-0.089409,0.310209,0.106193,-0.220762,0.150590,-0.495504,-0.076450,-0.286117,-0.053764,0.034303,-0.594204,0.106334,-0.169303,0.171009,-0.444026,-0.518348,0.235237,0.010124,-0.167730,0.703788,-0.773420,0.492644,0.609047,0.576941,-0.541370,0.648732,0.050232,0.476618,-0.265865,0.247612,0.406163,0.028995,0.044073,0.276715,0.215179,-0.016137,0.132407,-0.350118,0.420804', '3111650', '25723780', '1299965', '24695390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25812712', '神偷奶爸3', '喜剧', '洗心革面之后，格鲁（史蒂夫·卡瑞尔 Steve Carell 配音）作为特工成绩斐然，却因未能打败坏小子巴萨扎·布莱德（崔·帕克Trey Parker 配音）而被新局长扫地出门。就在此时，他收到一封远方来信，这才得知自己原来还有一个双胞胎兄弟德鲁（史蒂夫·卡瑞尔 Steve Carell 配音）。在德鲁盛情邀请下，格鲁带着妻子露西•王尔德（克里斯汀·韦格 Kristen Wiig 配音）以及玛戈（米兰达·卡斯格拉夫 Miranda Cosgrove 配音）、伊迪丝（达娜·盖伊 Dana Gaier 配音）和阿格蕾丝（埃尔希·费舍 Elsie Fisher 配音）来到了他亲生父亲所居住的地方探亲。德鲁天真烂漫，却一心想和哥哥搭档成为坏蛋二人组。格鲁虽然暂时回归狂野，可正义之心并未泯灭。尤其当巴萨扎邪恶的计划和三个可爱的孩子牵扯到一起时，他再也无法坐视不理……', '史蒂夫·卡瑞尔', '凯尔·巴尔达', 6.8, 246672, 'tt3469046', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2469070974.jpg', 1.1, 9.3, 49, 30.6, 10, '0.095901,-0.129013,-0.443011,0.503573,-0.207542,-0.615766,0.793050,0.258588,-0.280308,-0.176643,0.056832,0.733961,-0.024057,0.294084,0.536746,0.247310,-0.740336,-0.514654,0.235225,-0.166069,0.053575,-0.657058,-0.227420,0.059867,0.057646,-0.435603,0.407080,-0.419290,-0.077566,0.349633,0.246452,0.325907,-0.247834,0.260576,0.235744,0.363932,0.465812,-0.217202,-0.145861,0.258360,0.170160,0.284175,-0.202502,0.122354,0.181909,0.314164,0.193960,-0.302680,0.383545,-0.162433,0.106026,-0.244627,0.294876,0.273297,0.053061,-0.338637,0.416466,0.080031,-0.201119,-0.005837,0.134522,-0.263134,-0.515983,0.323346,-0.079379,0.120480,-0.339767,0.198930,-0.354536,0.038640,0.145929,-0.358866,-0.072361,0.218982,0.210208,0.391952,-0.222344,0.241291,-0.042002,-0.211985,0.361761,-0.092454,-0.257322,-0.111219,0.172470,-0.177816,0.131927,0.011812,-0.712230,0.064966,0.498031,0.123490,0.019650,0.322186,-0.277221,-0.301481,-0.423866,-0.116921,0.105564,-0.329737,-0.055702,-0.634031,0.006193,-0.134488,-0.323424,-0.175419,0.127120,-0.152517,0.448762,-0.706181,0.410303,0.383604,0.022459,-0.164473,0.315972,0.201867,0.250390,-0.275647,-0.030029,0.416721,0.341414,0.131141,0.440484,0.275199,0.101971,-0.184332,-0.161545,0.634120', '1298095', '2034997', '1297239', '1295253');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25812885', '安娜贝尔', '悬疑', '新婚燕尔的约翰·戈登（瓦德·霍尔顿 Ward Horton 饰）和妻子米娅（安娜贝拉·沃丽丝 Annabelle Wallis 饰）共同孕育了新的生命，对于这对未经世事的小夫妻来说，喜悦和担忧相伴而行。那个晚上，约翰找到了妻子寻觅已久的娃娃安娜贝尔，与此同时，邻居彼得家则发生了残忍血案，更为可怕的厄运也朝着戈登夫妇袭来。几名丧失人性的邪教男女闯入戈登家中，试图对他们展开屠杀。虽然戈登夫妇侥幸保住性命，但其中一名女子抱着安娜贝尔死去。在此之后，惴惴不安的米娅待在家中安胎，她试图从阴影中走出，然而接二连三的怪事相继在家中发生。诡异而恐怖的恶魔盛宴就此拉开帷幕……©豆瓣', '安娜贝拉·沃丽丝', '约翰·R·莱昂耐迪', 6.4, 62482, 'tt3322940', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2203515671.jpg', 2.7, 15, 50.5, 22.7, 9.1, '0.387164,-0.022662,-0.588262,0.152671,0.007999,-0.340067,1.145764,0.108408,-0.504169,-0.364229,0.434806,0.623802,-0.160382,0.186659,0.270205,0.002408,-0.416627,-0.534724,0.001965,-0.069776,-0.160680,-0.246477,-0.214975,-0.144807,0.041782,-0.484143,0.374826,0.054147,0.066101,0.649642,0.321124,0.559517,-0.359084,0.403849,0.010870,0.275403,0.229021,0.063075,-0.427705,0.232494,0.063869,-0.097989,-0.121542,0.190220,-0.052787,0.361126,0.685713,-0.575554,-0.039792,-0.267702,0.191205,-0.219528,0.014963,0.499106,0.212188,0.081373,0.148627,0.180934,-0.181630,-0.136471,0.078056,-0.073807,-0.507194,0.306951,0.007631,0.302879,-0.470677,0.390992,-0.075474,-0.119494,0.414466,-0.180008,0.143730,0.607251,0.122486,0.342001,-0.205837,0.120329,-0.407323,-0.195238,0.506263,-0.226586,-0.206730,0.293151,-0.195364,-0.296850,0.136241,-0.039396,-0.469329,-0.252530,0.417529,0.328759,-0.050829,0.580449,-0.515169,0.078467,-0.364589,0.028276,-0.029841,-0.284600,-0.363990,-0.622354,-0.053714,-0.317830,-0.374596,0.006268,0.084317,-0.127013,0.616642,-0.562831,0.302548,0.291465,0.227228,-0.355603,0.508215,-0.115568,0.378567,-0.269882,-0.142984,0.745874,0.001103,0.188915,0.147934,0.197676,-0.128304,0.034047,-0.223765,0.406632', '1316693', '1578663', '25884436', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25814705', '小森林 夏秋篇', '剧情', '平凡女孩市子（桥本爱 饰）自幼生长在位于日本东北地区的村庄小森。这里远离都市的喧嚣和浮躁，为青山绿水所环绕，俨然一个幽静怡然的世外桃源。村民们日出而作，日落而息，依靠一双勤劳的双手经营渺小却舒适的生活，与世无争。市子曾经前往东京闯荡，只不过她终究无法适应都市快节奏的步伐，最终回到了妈妈早已不在的老宅。童年时妈妈福子利用山川田野各种食材做出胡乱命名的美食，实心眼的市子在感叹受骗之余，也将美好的回忆留在了味蕾深处。仿佛遵循着母亲的步伐，她将对故乡的热爱融入了美食的烹制中。在朋友佑太（三浦贵大 饰）和吉子（松冈茉优 饰）的环绕下，享受着无忧无虑的人生……本片根据五十岚大介的漫画改编。©豆瓣', '桥本爱', '森淳一', 9, 399124, 'tt', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2564498893.jpg', 0.2, 0.6, 7.2, 32.6, 59.4, '0.338180,-0.034479,-0.520184,0.629294,-0.144051,-0.167176,0.725584,0.484958,-0.595767,-0.234599,0.217555,0.632073,0.237192,0.282228,0.327983,0.001025,-0.278951,-0.538468,-0.133822,0.056982,0.190808,-0.216111,-0.231559,0.055804,-0.219702,-0.195399,0.720310,0.325457,-0.092630,0.349586,-0.399669,0.154644,-0.323986,0.254469,-0.419730,0.024932,-0.035534,0.213050,-0.419819,0.023542,-0.359098,-0.380885,-0.083711,0.099744,0.016480,0.081167,1.039841,-0.444494,-0.299957,-0.086016,0.344913,-0.003473,-0.083550,0.218755,-0.133657,0.016328,0.102330,0.048186,-0.420500,0.255618,0.064609,-0.363153,-0.559072,-0.274756,0.317708,0.062819,-0.632612,0.543108,0.240226,-0.460846,0.065589,-0.305415,0.227985,0.153249,0.151364,0.595951,-0.076626,0.343917,-0.091243,0.321201,0.695304,0.206823,-0.192252,0.383424,-0.690210,-0.292222,-0.108557,-0.153895,-0.786615,-0.411660,-0.042364,0.155642,-0.219971,0.267352,-0.835467,0.247802,0.191315,-0.446370,0.222470,-0.408872,-0.419918,-0.580459,0.172493,-0.511369,-0.048031,0.079446,0.104065,-0.285277,0.761561,-0.830926,0.241162,0.427605,-0.019562,-0.222916,0.557568,-0.085320,-0.035432,-0.110370,-0.077195,0.775280,-0.070135,0.545179,0.035366,0.386264,-0.325814,0.040129,-0.837338,0.615864', '3811356', '5416009', '5279593', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25814707', '小森林 冬春篇', '剧情', '于无法融入喧嚣吵闹的大城市，平凡女孩市子（桥本爱 饰）选择回到自幼生长的老家——位于日本东北地区的小森村。这里没有过多时尚文明的色彩，当地人过着日出而作日落而息的传统生活，他们靠天吃饭，靠着双手经营人生。生活虽不富裕，心中则是满满的充实和欢喜。受妈妈（桐島かれん 饰） 影响，市子似乎对亲手制作各种美味而廉价的料理有着格外浓厚的兴趣。妈妈失踪已经很久，对料理的回忆与再现成为母女间别具特色的交流方式。更何况还有取自大自然的各种食材，又怎能暴殄天物浪费了大好的韶光？在好友纪子（松冈茉优 饰）和裕太（三浦贵大 饰）的陪伴下，市子静静地走过了春夏秋冬……本片根据漫画家五十岚大介的原作改编。©豆瓣', '桥本爱', '森淳一', 9, 355830, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2215147728.jpg', 0.2, 0.5, 6.8, 32.2, 60.4, '0.382494,-0.260928,-0.485251,0.514549,-0.002832,-0.195220,0.834991,0.225454,-0.710215,-0.251835,0.018720,0.514884,0.032347,0.146610,0.248523,-0.126653,-0.293710,-0.368342,-0.036356,-0.008015,0.111058,-0.394177,-0.162837,-0.002776,-0.384869,-0.331891,0.782755,0.150918,-0.169427,0.486646,-0.115804,0.412794,-0.147109,0.271639,-0.223369,-0.066563,-0.117739,0.331594,-0.432263,0.006602,-0.104479,-0.258122,-0.013317,0.006861,0.121904,0.028643,0.785587,-0.230392,-0.344290,-0.048756,0.365757,-0.049550,-0.161896,0.107797,0.049273,0.155049,0.223242,0.149120,-0.403828,0.176723,-0.010666,-0.223822,-0.705272,-0.198250,0.439881,0.111613,-0.505644,0.782765,0.043282,-0.613402,-0.037467,-0.381423,0.298392,0.195980,0.370057,0.613228,0.026072,0.172589,-0.206817,0.380106,0.649713,0.141022,-0.183379,0.482210,-0.678629,-0.372219,-0.030232,-0.371478,-0.580775,-0.125629,-0.158487,0.229094,0.024025,0.284011,-0.811523,0.423012,0.219422,-0.491673,0.583254,-0.312481,-0.147850,-0.658464,-0.013925,-0.882382,-0.330387,0.086263,0.258848,-0.182337,0.857580,-0.891515,0.181894,-0.013754,0.212082,-0.267123,0.516118,0.091909,-0.107050,-0.272598,-0.229294,0.446631,-0.203042,0.201318,0.129308,0.212956,0.039244,-0.047924,-0.639314,0.359118', '26283288', '26354526', '3811356', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25815008', '依然爱丽丝', '剧情', '爱丽丝（朱丽安·摩尔 Julianne Moore 饰）是一位事业有成的大学语言学教授，和丈夫约翰（亚历克·鲍德温 Alec Baldwin 饰）结婚多年，感情一直十分要好，两人生养了三个孩子莉迪亚（克里斯汀·斯图尔特 Kristen Stewart 饰）、斐格利亚（凯 特·波茨沃斯 Kate Bosworth 饰）和汤姆（亨特·帕瑞施 Hunter Parrish 饰），每一个孩子都健康长大。五十岁那年，爱丽丝遭遇了生命中最大的变故，起初，她只是发现自己的记忆力有些退化，随着时间的推移，这种退化越来越严重，经过医生的诊断，她患上了阿尔兹海默病。丰沛的感情，珍贵的记忆，睿智的思想，爱丽丝渐渐的失去了生命中重要的一切，然而，在家人的陪伴和鼓励下，她并没有失去活下去的希望，勇敢而又坚强的迎接新的一天。©豆瓣', '朱丽安·摩尔', '理查德·格雷泽', 8, 66719, 'tt3316960', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2208286457.jpg', 0.2, 1, 21.3, 53, 24.6, '0.094568,-0.104765,-0.502199,0.471517,-0.247070,-0.468614,0.879738,-0.034074,-0.495120,-0.508789,0.004067,0.808608,-0.058186,0.397705,0.128143,0.039591,-0.368046,-0.691800,0.112333,0.083916,-0.355462,-0.621995,-0.368941,-0.086175,-0.233974,-0.728456,0.577465,-0.001838,0.234202,0.599351,0.014179,0.173412,0.343683,0.262560,-0.048719,0.180496,0.253789,-0.090241,-0.080011,0.102239,0.377144,0.066039,0.011366,0.352857,0.010381,0.330212,0.534755,-0.219362,-0.189898,-0.073380,0.616933,-0.151444,-0.044713,0.128638,0.243077,-0.102662,0.117237,0.348171,-0.324169,-0.137715,-0.092076,-0.087595,-0.690371,-0.034716,0.103514,0.313337,-0.740041,0.468785,0.049604,-0.175889,0.109218,-0.369994,0.097636,0.487379,0.001242,0.431533,-0.378046,-0.104178,-0.251770,0.046011,0.548146,-0.123914,-0.597940,0.541752,-0.655958,-0.362551,-0.042361,-0.227235,-0.632213,0.078590,0.065228,0.282081,-0.207620,0.495529,-0.388795,0.254327,-0.515807,-0.247302,-0.054924,-0.295955,-0.024640,-0.404199,-0.205779,-0.814202,-0.516244,-0.006974,-0.155416,-0.378474,0.907937,-0.778556,0.406849,0.368547,0.193964,-0.440659,0.489757,0.076452,0.174566,-0.303619,0.017936,0.666965,-0.231766,-0.084900,-0.014902,0.328490,0.062602,0.154215,-0.407052,0.751621', '26348103', '1292720', '4301215', '1309161');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25815034', '湄公河行动', '剧情', '金三角湄公河上，一处被称为“鬼门关”的河段，两艘来自中国的商船遭到不明身份之人的枪击袭击。未过多久，泰国军方召开新闻发布会，指责中国商船贩卖毒品。虽然发布会宣称船员全部逃亡，但是十三具遭受残忍杀害的中国船员尸体很快被人发现。这起胆大妄为的案件令中国警方大为震惊，云南省缉毒总队队长高刚（张涵予 饰）受命带特别行动小组前往泰国，并与情报员方新武（彭于晏 饰）合作接洽。根据现有资料显示，这件案子由盘踞在金三角的大毒枭糯卡所为。糯卡贪婪残忍，胆大包天，是湄公河流域上一颗惊扰运输安全的毒瘤。为了将这个恶棍绳之于法，中国、老挝、缅甸开展了三国联合巡逻，集中对糯卡的制毒窝点进行扫荡。而高刚等人也深入最危险境地，与丧失人性的贩毒分子进行惨烈对决……本片根据真实事件改编。©豆瓣', '张涵予', '林超贤', 8, 706883, 'tt6044910', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2380677316.jpg', 0.7, 2.9, 22.4, 45.9, 28.1, '0.091393,-0.227128,-0.699718,0.412728,0.229937,0.400858,0.481301,-0.240671,-0.691757,0.074635,0.309332,0.554715,-0.089047,-0.423072,0.119390,-0.063430,-0.421125,-0.711059,-0.313426,-0.059725,-0.272421,-0.510126,-0.082101,-0.205749,0.067825,0.011494,0.541885,0.455705,-0.530142,0.584588,0.190977,0.441214,-0.586974,0.437380,0.126193,-0.451766,0.249585,-0.365183,-0.213892,0.110326,-0.308913,-0.257092,0.103994,0.102826,-0.026251,0.569880,0.683401,-0.113111,-0.239731,-0.388208,0.286938,-0.632836,0.049393,-0.126949,0.699747,0.264442,-0.098999,0.425204,-0.266674,-0.148602,-0.067064,0.018047,-0.831738,-0.110421,0.145700,0.031047,-0.188259,0.160744,-0.150979,0.342385,-0.031757,0.010994,0.341316,0.612506,0.367822,0.076833,0.121576,0.165251,-0.318938,0.074011,0.564442,-0.314774,-0.117949,-0.396902,0.120430,-0.534722,0.174192,-0.455731,0.182435,0.144454,0.130353,-0.287115,-0.088421,0.381915,-0.649690,-0.000765,-0.276208,-0.457458,0.111646,-0.070905,-0.109004,-0.897038,-0.175892,-0.217892,0.010091,0.091323,0.297737,-0.069234,0.497102,-0.393343,-0.067169,0.547110,0.183762,-0.639809,0.233809,0.152354,0.008958,-0.338845,-0.346360,0.193659,0.520265,0.365111,0.027246,0.055872,-0.122450,-0.339148,-0.091567,-0.181886', '27110363', '1306809', '3621404', '25723905');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25815577', '蝙蝠侠之子', '动作', '在崇山峻岭之间，塔莉娅（莫蕾娜·巴卡林 Morena Baccarin 配音）和儿子达米安（Stuart Allan 配音）隐居于此。他的外公瑞斯组建并训练刺客联盟，期待着下一个继任者的成长。谁知就在这一天，瑞斯当初的得意弟子“丧钟”斯莱德·威尔逊（Thomas Gibson 配音）带着叛变的刺客杀来，一番激战过后，瑞斯不幸身亡。在此之后，来不及悲伤的塔莉娅带着达米安来到哥谭市，寻找儿子的生身父亲蝙蝠侠布鲁斯·韦恩（杰森·奥玛拉 Jason O''Mara 配音）。从未谋面的父子，展开了磕磕绊绊的相处。与此同时，丧钟的野心持续膨胀，当他的触角伸向哥谭市时，他终将和蝙蝠侠父子迎来一场大战……©豆瓣', '斯图尔特·艾伦', '伊桑·斯波尔丁', 6.7, 6577, 'tt3139072', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2181403674.jpg', 1.2, 8.7, 53.5, 27.5, 9.1, '0.076840,-0.152463,-0.916740,0.652910,0.084888,-0.491545,0.613890,0.143210,-0.287456,-0.207338,0.512675,0.484811,-0.307441,0.214455,0.189215,-0.173315,-0.692202,-0.706828,-0.248750,-0.120488,0.025153,-0.285875,-0.218582,0.007615,-0.030039,-0.400119,0.539254,-0.100048,-0.043698,0.505735,0.234473,0.072158,-0.145755,0.392783,0.057187,0.371388,0.396853,-0.030156,-0.321061,0.263652,0.230274,0.254186,-0.278083,-0.058007,0.073914,0.265420,0.623607,-0.387028,0.351179,-0.150698,0.152404,-0.252254,0.181009,-0.008953,0.385871,0.041102,-0.039673,0.227164,-0.040333,-0.130228,-0.099000,-0.296685,-0.533196,0.242202,-0.075529,0.137773,-0.530085,0.401394,-0.218891,-0.050555,0.225091,-0.269299,0.065013,0.840657,0.420392,0.344583,-0.095118,0.210241,-0.348114,0.064760,0.583563,-0.041143,-0.271363,-0.139935,0.044680,-0.375781,-0.185414,0.170597,-0.675793,-0.350242,0.752667,-0.161456,0.030438,0.876261,-0.507631,-0.082985,-0.478451,-0.034213,0.066232,-0.421625,-0.033829,-0.827953,0.067269,-0.144091,-0.035281,0.128101,0.020319,-0.160291,0.357158,-0.772467,0.460785,0.371980,0.492413,0.202856,0.343288,0.007362,-0.005505,-0.294312,-0.100495,0.643904,0.108814,0.184786,0.518898,0.279568,0.106329,0.182720,-0.494104,0.469933', '21349734', '1306723', '3178770', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25816182', '后备空姐', '喜剧', '赵小凡（赵奕欢 饰）从小就被空姐的干净制服和温暖笑容所吸引，立志长大后要成为其中的一员，然而她出生在极为普通的家庭之中，样貌和个性都平平凡凡，是个彻彻底底的“女屌丝”。可是，残酷的现实并没能打击赵小凡实现理想的信心，经历了几番波折，她总算是加入了空姐训练营，踏出了迈向梦想的第一步。在训练营中，等待着赵小凡的不仅仅有严苛的课程和巨大的压力，同行之间的明争暗斗亦时时在上演，再加上一个横竖看她不顺眼的凌院长，赵小凡腹背受敌，处境十分尴尬。然而，凭借着自己的不懈努力，赵小凡用出色的成绩赢得了教官的认可和对手的尊重，可就在此时，她却发现，自己患上了眩晕症，将要彻底于空姐这一职业无缘。©豆瓣', '赵奕欢', '管晓杰', 3.1, 3367, 'tt5680112', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2180919763.jpg', 65.2, 20.8, 8.8, 2.1, 3.1, '0.218342,0.098214,-0.679809,0.613253,-0.292700,-0.311374,0.695668,0.049803,-0.527656,-0.237076,0.256281,0.781834,-0.071720,0.246739,0.258947,-0.269185,-0.030348,-0.625793,-0.292683,-0.173424,-0.300513,-0.354057,-0.382099,-0.079242,-0.141791,-0.518466,0.853781,0.081909,-0.316871,0.385712,0.369997,0.052645,0.108167,0.588374,-0.276552,-0.037962,0.170267,0.261286,-0.179997,0.089515,0.062349,-0.415568,-0.202208,0.366884,-0.010050,0.286496,0.696846,-0.273335,-0.377742,0.084302,0.398010,-0.440695,-0.266090,0.271153,0.336881,0.062113,0.188644,0.050821,-0.073328,0.219078,-0.097285,-0.124993,-0.907826,-0.058110,0.333073,0.059186,-0.743077,0.870717,0.181029,-0.159391,-0.026484,-0.144064,0.116894,0.283021,0.241308,0.442813,-0.280876,0.183338,-0.397975,0.197747,0.931200,0.179048,-0.503204,0.381671,-0.470965,-0.551991,0.010352,-0.462618,-0.527996,-0.040800,0.350704,0.246263,-0.236736,0.225845,-0.456496,0.262393,-0.203753,-0.071739,-0.316509,-0.652930,0.092056,-0.344643,-0.352895,-0.720643,-0.523213,0.178687,-0.060750,-0.528310,0.984899,-0.956848,0.081435,0.241295,0.174392,-0.432263,0.676264,0.282755,0.238108,-0.169841,-0.133252,0.331917,-0.074947,0.196299,0.100072,0.622587,-0.238984,-0.282613,-0.379046,0.695853', '35030151', '26283288', '1870682', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25816274', '无法触碰的爱', '剧情', '嶋俊亚纪（米原幸佑 饰）是一名同性恋者，有着十分灰暗的过去。他的性取向在曾经工作过的公司里遭到了曝光，因此受到了同事和上司的排挤和鄙视，最终丢掉了工作。从此以后，他十分小心的隐藏着自己的真心，害怕从前遭遇的一切再度上演。好不容易找到了一份新的工作，亚纪发誓这一次绝对不会再搞砸了。去新公司上班的第一天，亚纪就在电梯里遇到了一个喝得醉醺醺的奇怪的男人，而这个男人正是他的上司外川阳介（谷口贤志 饰）。虽然见面的第一印象并不好，但在之后的工作和合作中，亚纪发现阳介其实是一个非常有担当负责人的男人，奇妙的电波相互吸引这两人，导致他们最终抵达了伦理的边界。©豆瓣', '米原幸佑', '天野千寻', 6.7, 8044, 'tt3902600', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2180800539.jpg', 2.4, 12.8, 44.8, 27.8, 12.2, '0.452403,-0.151351,-0.810536,0.580227,-0.217354,-0.240227,0.766115,0.242043,-0.533104,-0.234953,0.213102,0.963345,-0.150816,0.395601,0.417479,-0.068960,-0.177095,-0.697372,0.010388,-0.328516,-0.279476,-0.356102,-0.093157,-0.049918,-0.243921,-0.196884,0.576509,0.027320,-0.261112,0.383688,0.202951,0.109670,0.131282,0.945186,-0.142184,0.126242,-0.013136,0.042557,-0.033558,0.259104,0.284221,-0.177627,-0.043539,0.358182,0.179395,0.666508,0.532247,-0.229761,-0.669346,0.012820,0.562275,-0.407270,-0.174517,0.098805,0.426694,0.096871,0.169867,0.148088,-0.434520,-0.010467,-0.063496,0.070539,-0.768947,-0.093400,0.030642,0.152872,-0.576868,0.615269,0.219590,-0.174300,0.150376,-0.250231,0.273035,0.424563,0.296492,0.191958,-0.297922,0.116276,-0.557761,-0.066578,0.776346,0.077434,-0.137831,0.516842,-0.157228,-0.448172,-0.083979,-0.200508,-0.555568,0.010588,0.260928,0.103277,-0.282558,0.001217,-0.721663,-0.033530,0.002624,-0.251902,-0.044660,-0.568880,-0.091828,-0.540428,-0.113087,-0.646323,-0.507074,0.229016,-0.127409,-0.375856,0.572680,-1.088650,0.033260,0.635687,0.344567,-0.635994,0.659647,0.255606,0.125503,-0.095169,-0.148001,0.021365,0.149436,0.451840,0.134922,0.536533,0.064279,-0.354917,-0.385183,0.369220', '1301022', '1308755', '6080756', '1308206');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25817534', '哭声', '剧情', '在韩国某个偏远的山村，虽然这里生活并不富足，但长久以来安宁无忧，人们仿佛不知危险的逼近。直到某晚，村中突发杀人事件，彻底打破了这里的宁静。在村里担任警察的钟九（郭度沅 饰）与同侪迅速赶往现场调查，他初步推断这是一起恶性杀人事件，只不过当地人私下猜测，认为那个不知何时出现在村边树林的日本人（国村隼 饰）有最大嫌疑。这个日本人可能会某种巫术，他通过妖邪的手段将人诅咒之死。在此之后，接二连三离奇非常却又有着共通之处的死亡事件接连发生，甚至连钟九的女儿也被置身危险之中。万般无奈之下，钟九只得求助巫师（黄正民 饰），以禳解降临在村人和女儿头上的可怕诅咒……©豆瓣', '郭度沅', '罗泓轸', 7.3, 130839, 'tt5215952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2339592703.jpg', 2.7, 6.6, 31.2, 40.8, 18.6, '0.274662,0.054075,-0.728686,0.368749,0.205745,0.396295,0.634630,-0.042410,-0.672743,-0.445194,0.375899,0.607849,-0.144415,0.083415,0.175490,-0.157158,-0.178100,-0.490485,0.022592,-0.271545,-0.366264,-0.372854,-0.396524,-0.304371,0.002474,-0.146690,0.315845,0.529429,-0.322740,0.271529,0.138975,0.722463,-0.444607,0.588442,-0.114733,-0.064735,0.112341,0.144968,-0.157343,0.013220,-0.214760,-0.517456,-0.073315,0.318220,-0.088993,0.415049,0.531824,-0.477615,-0.506736,-0.177042,0.389379,-0.287892,-0.184950,0.233974,0.597034,-0.242827,0.257321,0.257975,-0.106755,-0.072530,-0.075333,0.182002,-0.596561,0.170155,0.184005,0.233767,-0.319638,-0.071375,0.217061,-0.129925,-0.165705,-0.233464,0.441063,0.249432,0.324492,0.103156,-0.196472,-0.135461,-0.364257,-0.033312,0.828679,-0.132506,-0.348287,0.024099,-0.320324,-0.459502,-0.063369,-0.232353,-0.291892,0.108092,0.290551,0.262504,-0.394386,0.346287,-0.289148,0.138818,-0.072123,0.031820,-0.172372,-0.196494,-0.294484,-0.576617,-0.080246,-0.388936,-0.299062,0.055904,0.045749,-0.107100,0.417533,-0.693750,0.358454,0.513016,0.248808,-0.497118,0.310779,0.089554,0.032957,-0.207745,-0.281581,0.268552,-0.069561,0.457938,0.009880,0.058400,-0.015244,-0.234224,-0.162657,0.247088', '25870679', '1292064', '1294941', '25721544');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25818101', '攻壳机动队', '动作', '近未来，人类的各种器官均可实现移植，一时间机器人、生化人、仿生人充斥世间，与人类真假莫辨。某座繁华都市的大厦内，汉卡公司高管正与非洲来宾洽谈业务，突然宴会变成血腥大屠杀，暴走的机器人大开杀戒。隶属公安九课的米拉·基里安少佐（斯嘉丽·约翰逊 Scarlett Johansson 饰）带领巴特（皮鲁·埃斯贝克 Pilou Asbæk 饰）等手下赶往现场，平息事态。根据对暴走艺伎机器人的调查发现，被称作“久世”的神秘之人策划了这一系列的行动，而且他的目标全部指向了掌握着生化前沿尖端科技的汉卡公司及其研发人员。经过一番凶险的周旋，少佐逐渐逼近真相，同时也渐渐解开了发生在自己身上的惊天秘密……本片根据士郎正宗的经典原作改编。©豆瓣', '斯嘉丽·约翰逊', '鲁伯特·桑德斯', 6.4, 197972, 'tt1219827', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2453176400.jpg', 2.3, 13.9, 52.5, 24.9, 6.3, '0.214539,-0.089951,-0.705482,0.212671,0.269001,0.105205,0.535097,-0.096287,-0.438310,-0.284604,0.341315,0.323422,-0.368640,-0.062341,0.423792,-0.093391,-0.452642,-0.659916,-0.398562,0.038925,-0.214483,-0.477904,-0.272704,-0.471804,0.212036,-0.312880,0.673918,0.240017,-0.183417,0.171338,0.074686,0.513846,-0.501569,0.315343,0.156301,-0.019318,0.384683,-0.512216,-0.211135,-0.004148,-0.133289,-0.169600,0.079507,0.099418,-0.096757,0.450978,0.672853,-0.387495,-0.074568,-0.176639,0.307707,-0.238027,0.044065,-0.065846,0.290391,0.178517,-0.233794,0.280242,-0.203950,-0.011226,-0.118511,-0.029125,-0.766031,-0.149895,0.207086,0.191832,-0.288594,0.071341,-0.132501,0.160263,0.102633,-0.115452,0.175319,0.461906,0.425387,0.247044,0.165797,0.116700,-0.397166,0.085046,0.476672,-0.107208,-0.346312,0.121612,-0.146241,-0.571987,-0.364489,-0.261865,-0.027434,-0.220560,0.198697,0.174484,0.133120,0.372798,-0.553510,-0.065330,-0.139384,-0.458762,0.072483,-0.098145,-0.071999,-1.019886,-0.234308,-0.143391,-0.098279,0.040249,0.016321,-0.021098,0.573619,-0.520081,-0.057819,0.449505,0.171210,-0.283877,0.256901,-0.467312,0.134037,-0.294584,-0.398262,0.084728,0.266486,0.529174,0.078030,0.374299,0.006603,-0.245895,-0.359973,0.120256', '2369613', '1306809', '25723905', '1309064');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25818615', '纸之月', '剧情', '20世纪末，供职于若叶银行的梅泽梨花（宫泽理惠 饰）转正成为正式员工，并且刚刚从独居老人平林孝三（石桥莲司 饰）那里拿下高额的业务，风韵犹存的她颇得领导井上（近藤芳正 饰）的器重。只是梨花的内心似乎隐藏着种种的不满与压抑，她和温柔的丈夫（田边诚一 饰）结婚多年，始终不曾育有子女，夫妻俩相敬如宾的外表下有着莫大的距离。在与平林老人的孙子光太（池松壮亮 饰）邂逅后，梨花的内心顿起波澜。她开始战战兢兢尝试着追逐如梦如幻的幸福，为此不惜将手伸向储户们的存款。在幸福的塔顶她和光太醉生梦死，可当梦醒来之际，幸福之塔轰然倒塌……本片根据角田光代荣获第25届柴田炼三郎的同名原作改编。©豆瓣', '宫泽理惠', '吉田大八', 7.3, 10458, 'tt3560492', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2188667287.jpg', 0.9, 4, 37.6, 46.1, 11.3, '-0.002249,0.043749,-0.833828,0.522586,0.027768,-0.238622,0.677964,0.230276,-0.472681,-0.149218,0.386252,0.539749,-0.192440,0.633679,0.186411,0.073619,-0.078512,-0.675481,-0.369021,-0.070383,-0.040787,-0.200097,-0.226868,0.055094,-0.393497,-0.283154,0.800088,0.159078,-0.010113,0.453057,0.235660,0.247908,-0.156907,0.147354,-0.296647,0.037117,-0.062729,0.249468,-0.434275,-0.072975,-0.145495,-0.294559,-0.321939,-0.078696,0.002454,0.327117,0.609115,-0.295725,-0.191407,0.107105,0.434754,0.017732,0.001865,0.187591,0.126725,0.212528,0.130937,0.253404,-0.419972,-0.013792,0.178501,-0.218763,-0.566372,-0.035500,0.149083,0.247179,-0.671879,0.521903,-0.121589,0.067543,0.271981,-0.104777,-0.002600,0.137641,0.029978,0.434093,-0.506135,0.213445,-0.313963,0.386610,0.392731,0.195058,-0.152224,0.266062,-0.422402,-0.271288,-0.062324,-0.133939,-0.446507,-0.185324,0.252493,0.077014,0.059747,0.338004,-0.506667,-0.091121,-0.052801,0.001178,0.170595,-0.369961,-0.224685,-0.491334,-0.219188,-0.560055,-0.327178,0.150444,0.157517,-0.398401,0.653908,-0.824472,0.384155,0.320016,0.228308,-0.054785,0.447171,0.168708,-0.001971,-0.228858,-0.127312,0.237065,-0.173639,0.269009,0.236543,0.206633,-0.365801,0.036307,-0.344608,0.397405', '35030151', '26354526', '26809007', '6900092');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25819229', '云中行走', '剧情', '从小就拥有杂技表演天赋的菲利普·帕特（约瑟夫·高登-莱维特 Joseph Gordon-Levitt 饰）在街头卖艺时，邂逅美丽的街头音乐女孩安妮（夏洛特·莱本 Charlotte Le Bon 饰）。偶然的机会，菲利普得知纽约世贸双子大厦即将竣工。从此，菲利普就萌生了在这两座摩天大厦间走钢索的的想法。然而这疯狂的“艺术犯罪”却遭到了一系列的质疑和误解，但这并没有击垮菲利普的坚定信念，他深入调查缜密部署，先后得到走钢丝经验丰富的鲁迪爸爸（本·金斯利 Ben Kingsley 饰）的执导，以及让-路易（克雷蒙·史鲍尼 Clement Sibony 饰）和杰夫（塞萨·多姆波伊 César Domboy 饰）等人的帮助。在110层412米的云中，菲利普开始了他的钢丝行走。本片根据法国杂技艺术家菲利普·帕特的个人自传改编，翻拍自2009年奥斯卡最佳纪录长片《走钢丝的人》，真实还原了1974年8月7日的惊世壮举。', '约瑟夫·高登-莱维特', '罗伯特·泽米吉斯', 7.6, 87449, 'tt3488710', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2309200993.jpg', 0.4, 2.4, 30.8, 49.5, 16.9, '0.233832,-0.152204,-0.761238,0.539872,0.042698,-0.227952,0.506512,0.074146,-0.440220,-0.095056,0.344175,0.778230,-0.519235,0.031522,0.606922,-0.040231,-0.590630,-0.756460,0.104472,-0.267224,0.018452,-0.447468,-0.384231,-0.330448,0.071375,-0.333238,0.482745,0.076915,-0.069302,0.580460,0.228832,0.192855,0.197528,0.152567,-0.064974,0.178966,0.262899,0.067450,-0.121895,0.184691,-0.064983,-0.131806,-0.125095,0.002284,-0.050154,0.391471,0.472673,-0.386150,0.143843,0.088108,0.467345,-0.037001,0.195651,0.138241,0.181977,-0.208484,-0.068248,0.216827,-0.268263,0.016467,0.096428,-0.257573,-0.696746,-0.087071,0.029442,0.092647,-0.519550,0.504222,-0.164924,0.013304,0.038312,-0.161197,-0.097989,0.251346,0.399957,0.279819,-0.036972,-0.141269,-0.405446,0.271639,0.282106,0.186747,-0.436530,0.218005,-0.162362,-0.521250,-0.201702,-0.077605,-0.271697,-0.095154,0.461137,-0.034702,-0.072484,0.249820,-0.585086,-0.113010,-0.381072,-0.066597,-0.105804,-0.234083,-0.183532,-0.880437,-0.078574,-0.467435,-0.115609,0.040311,-0.050340,-0.174493,0.471844,-0.716932,0.377249,0.473003,0.162770,-0.030336,0.667428,-0.108006,-0.107979,-0.122716,-0.210858,0.474355,-0.099243,0.269339,0.018464,0.573295,0.191625,-0.393819,-