INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25819726', '高手们', '动作', '年轻帅气的“技术者”志赫（金宇彬 饰），被誉为是窃盗界的最强头脑，任何金库都难不倒他，还能伪造一切资料，制订滴水不漏的盗窃计划。他联手“掌控者”人力调配专家久仁（高昌锡 饰），以及“隐形者”超强黑客宗裴（李玹雨 饰），3人每一个都是行业内最顶级的高手，他们曾在3分钟之内，轻松在警察眼皮底下偷走价值30亿的珠宝，并在盗窃界一夜成名。耳闻三人实力的黑手党赵社长（金英哲 饰），决定网罗他们，希望他们加入最高难度的偷窃任务──40分钟内，在全亚洲安保级别最高的仁川海关盗取1500亿现金的赃款。究竟这三位实力高超的“技术者”、“掌控者”和“隐形者”，能否成功达成任务？还是将失败落入法网？而志赫和赵社长之间的心机角力，又将会是谁胜谁负？', '金宇彬', '金泓善', 6.5, 17656, 'tt4319112', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2215157469.jpg', 1.9, 12.4, 54.7, 23.3, 7.8, '-0.109426,0.456172,-0.583008,0.528314,-0.248964,0.270439,0.093832,-0.227137,-0.647176,-0.432144,0.220684,0.326516,0.120170,-0.230451,0.207340,-0.449183,-0.160117,-0.580011,-0.138324,-0.642019,-0.484743,-0.457174,-0.618823,-0.303008,-0.263469,-0.313331,0.755404,0.242835,-0.421852,-0.159119,0.393692,0.092525,-0.242939,0.088896,-0.238505,-0.335077,0.281183,-0.057328,-0.428079,0.156515,-0.342125,-0.210137,0.086410,-0.011531,0.245219,0.101256,0.479249,-0.107258,-0.038512,0.150861,0.149141,-0.281462,-0.143639,-0.155121,0.593473,-0.150410,0.294413,0.400705,0.203659,0.055431,0.080707,-0.037998,-1.463656,-0.330556,0.659979,-0.078320,-0.292025,0.152532,-0.273018,0.204691,-0.377170,0.013587,-0.171398,0.345189,0.229633,0.247510,0.188846,-0.026977,-0.729377,0.353110,0.437801,-0.108624,-0.198001,0.003590,0.205479,-0.991669,-0.574942,-0.804323,-0.071677,0.226174,0.319718,0.095685,0.367803,0.125843,-0.506386,0.110757,0.043195,0.064507,-0.050113,-0.347528,0.334827,-0.688490,0.107138,-0.507984,-0.329971,0.492258,0.503294,-0.529935,0.826554,-0.764656,-0.127389,0.324867,0.321829,-0.519168,0.602984,-0.230489,0.162448,-0.424306,-0.361612,-0.171472,0.475552,0.331861,-0.038757,0.375522,0.138375,-0.462887,0.052059,0.046618', '1793491', '27073234', '3670447', '3718665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25820460', '美国队长3', '动作', '美国队长史蒂夫·罗杰斯（克里斯·埃文斯 Chris Evans 饰）带领着全新组建的复仇者联盟，继续维护世界和平。然而，一次执行任务时联盟成员不小心造成大量平民伤亡，从而激发政治压力，政府决定通过一套监管系统来管理和领导复仇者联盟。联盟内部因此分裂为两派：一方由史蒂夫· 罗杰斯领导，他主张维护成员自由，在免受政府干扰的情况下保护世界；另一方则追随托尼·斯塔克（小罗伯特·唐尼 Robert Downey Jr. 饰），他令人意外地决定支持政府的监管和责任制体系。神秘莫测的巴基（塞巴斯蒂安·斯坦 Sebastian Stan 饰）似乎成为内战的关键人物……©豆瓣', '克里斯·埃文斯', '安东尼·罗素', 7.9, 440331, 'tt3498820', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2332503406.jpg', 1, 2.8, 24.2, 45.3, 26.7, '-0.145557,0.378439,-0.623367,0.619913,-0.060993,0.013240,-0.116910,0.448387,-0.430650,-0.147773,0.432503,0.545109,0.366368,-0.258435,0.282524,-0.411299,-0.683130,-0.414788,-0.084677,-0.014441,-0.324454,-0.556197,-0.312405,-0.837083,-0.253011,-0.569860,1.044386,0.186735,-0.659404,-0.071953,0.138596,0.684895,-0.173634,0.259316,0.690506,-0.539353,0.644388,-0.366442,-0.674867,0.234349,-0.379102,0.163349,-0.276110,0.339289,0.262000,0.370032,0.435709,-0.670671,-0.028433,-0.640609,0.235949,-0.431490,0.043582,-0.229209,0.428568,0.324699,0.046491,0.624824,0.008883,0.101294,-0.034351,-0.284792,-0.857582,-0.241928,0.254492,0.276356,-0.388802,0.489766,-0.349840,0.036048,0.041982,-0.110868,-0.197832,0.879099,0.701372,0.216068,-0.202665,0.494508,-0.148158,-0.092218,0.556435,-0.259645,-0.508427,-0.371221,-0.393488,-0.329298,-0.250443,-0.371856,-0.270308,-0.302265,0.035018,-0.234689,0.435950,0.583937,-0.771526,-0.043343,-0.356483,-0.528512,-0.099975,-0.459702,0.576768,-0.966440,0.059542,0.335835,0.099383,0.110788,0.095607,0.027700,0.890840,-0.823224,0.064797,0.543232,0.528975,-0.926016,0.238425,0.502533,0.575380,-0.800263,-0.167120,0.049182,0.328082,0.229120,0.159498,-0.129780,0.143936,-0.156049,0.342568,-0.096862', '2369613', '1305096', '3861846', '1300371');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25821124', '地下墓穴', '惊悚', '伦敦大学的教授斯嘉丽（佩蒂塔·维克斯 Perdita Weeks 饰），年纪轻轻便拥有考古学、符号学等专业学位，更掌握四国语言。她的父亲曾经致力于点金石的探索研究，可悲的是最后死于非命。继承了父亲遗志的斯嘉丽在新近一次冒险中，从伊朗一座即将被炸毁的墓穴里找到了传说中的罗塞秘钥，这个关键发现可以帮她找到点金石的蛛丝马迹。为了实现这个目标，她请来班吉（艾德文·霍德吉 Edwin Hodge 饰）担任摄影记录工作，还拜托曾经与之一同出生入死的乔治（本·费德曼 Ben Feldman 饰）担任翻译。这几个胆大妄为的年轻人，随后试图闯入埋葬着六百万尸体的巴黎地下墓穴探险，而恐怖的体验也就此展开……©豆瓣', '佩蒂塔·维克斯', '约翰·埃里克·道达尔', 7, 20981, 'tt2870612', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2197368321.jpg', 2.1, 8.2, 40, 36.7, 12.9, '0.044278,0.120043,-0.782364,0.798068,-0.173200,-0.490345,0.545867,-0.266300,-0.305369,-0.485378,0.083033,0.644852,0.103245,0.020476,0.212549,0.043341,-0.302438,-0.605306,-0.047107,-0.289073,-0.481591,-0.553198,-0.546745,-0.177443,-0.184861,-0.237203,0.538251,0.191059,-0.344230,0.185205,0.118562,0.300090,0.033693,0.030801,-0.395879,-0.168557,0.152705,0.129064,-0.205198,0.278301,-0.012435,-0.263814,-0.001715,0.021199,0.027944,0.307052,0.373243,-0.340857,0.122969,-0.170392,0.299236,-0.314738,-0.066186,-0.049412,0.196186,0.072387,-0.022218,0.173966,-0.345338,0.045135,0.094315,-0.254003,-0.971304,-0.288427,0.022930,0.052119,-0.601762,0.086014,0.123398,-0.033814,-0.017353,-0.325724,0.385323,0.330781,0.199903,0.126276,-0.052360,0.048640,-0.314826,0.246888,0.334188,-0.353636,-0.071727,-0.010342,0.110381,-0.525995,0.282285,-0.122636,-0.168700,0.116941,0.310413,0.048886,0.046797,-0.046665,-0.736959,-0.097034,-0.392649,-0.126526,0.041272,-0.212666,0.006965,-0.769007,-0.322467,-0.083723,-0.151461,-0.014606,-0.054481,-0.379979,0.561465,-0.471502,0.253516,0.414707,0.259248,-0.435190,0.568734,0.034899,0.265775,-0.192544,-0.084806,0.286171,0.178328,0.558551,-0.035341,0.299848,0.308351,-0.379341,-0.579456,0.299027', '25928048', '3318306', '1295120', '1793491');
