INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25821498', '妇女参政论者', '剧情', '影片讲述一个多世纪前，英国妇女为了争取选举权而不懈斗争的故事。斯特里普在片中饰演的埃米琳·潘克赫斯特是一位著名的妇女选举权倡导者。她与几位同盟者发起成立了“妇女议会”，在国会开会时，她们也开会，与议会唱对台戏。由于采取了激进的斗争措施，潘克赫斯特同她的同盟者们曾多次入狱，在社会上造成了很大的反响。', '凯瑞·穆里根', '莎拉·加芙隆', 8.6, 34978, 'tt3077214', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2260682507.jpg', 0.2, 0.9, 12.2, 39.6, 47.1, '0.195702,-0.087975,-0.673111,0.728731,0.211856,-0.185808,0.561022,0.123456,-0.316625,-0.522629,0.392116,0.934094,-0.120928,0.178457,0.321554,-0.399448,-0.515031,-0.728417,-0.216810,0.075994,-0.332451,-0.638806,0.095418,-0.380938,-0.557434,-0.407004,0.647554,-0.183319,-0.508230,0.286043,0.628892,0.145179,0.058942,0.127780,0.169205,-0.100712,0.550216,-0.200491,-0.519467,0.148291,0.132598,-0.255504,-0.394014,0.135255,0.157740,0.479276,0.232825,-0.429890,0.292068,-0.078357,0.601055,-0.255724,0.064218,0.479518,0.784455,-0.039725,0.135785,0.606670,-0.147970,-0.200929,-0.150744,-0.244194,-0.556319,-0.010098,-0.099364,0.285429,-0.695413,0.477619,0.216710,0.131550,-0.094408,0.035319,-0.101949,0.756071,-0.059624,0.196144,0.070697,-0.080203,-0.317684,0.271813,0.543590,0.137751,-0.452224,0.049232,-0.383818,-0.525608,-0.236878,-0.266966,-0.268454,-0.433035,0.367741,-0.691850,-0.103560,0.621846,-0.868272,-0.102581,-0.297225,-0.245747,0.151635,-0.007428,0.018982,-1.105205,-0.218319,-0.398705,-0.079457,0.181677,0.015964,-0.129405,0.869597,-0.881820,0.319639,0.658649,0.328964,-0.595787,0.630589,0.329694,0.410955,-0.250509,-0.157189,0.226084,-0.057121,-0.090158,0.093827,0.215259,-0.198047,-0.163531,-0.122647,0.213429', '25833539', '1498811', '25723905', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25821585', '生活残骸', '喜剧', '女孩艾米（艾米·舒默 Amy Schumer 饰），从小被父亲教导婚姻不现实，一夫一妻不现实，长大后热衷泡吧，一直与不同男人约会却从不恋爱。一天，身为男性杂志编辑的她，前去采访一位专为运动员治疗运动损伤的医生亚伦（比尔·哈德尔 Bill Hader 饰），不料遇见了可能终结她完美单身生活的真命天子。本片由女主角艾米·舒默编剧，根据她本人的真实经历改编。', '柯林·奎恩', '贾德·阿帕图', 6.3, 8112, 'tt3152624', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2259048192.jpg', 3.2, 15.9, 49.7, 24.4, 6.9, '0.322044,-0.111014,-0.386782,0.247758,-0.166801,-0.454935,0.525205,0.067830,-0.340075,-0.555727,0.385608,0.703743,-0.120763,-0.051440,0.435748,0.235118,-0.520577,-0.454202,0.069210,0.241923,0.016819,-0.355134,-0.116757,-0.097303,-0.207524,-0.319753,0.716923,-0.599906,-0.305497,0.385322,0.307313,0.165545,0.075112,0.261924,0.116796,0.022325,0.449888,0.047000,-0.308109,0.158905,0.240202,0.020586,-0.021873,0.161208,-0.222912,0.132052,0.438359,-0.260364,-0.051045,-0.234174,0.683527,-0.061031,-0.140530,0.025610,0.082373,0.100850,0.440233,0.312223,0.167348,0.088639,-0.241955,-0.343322,-0.323721,-0.167359,0.233644,0.362478,-0.260737,0.552670,-0.385466,-0.072681,0.027501,-0.295046,-0.130461,0.217226,0.535009,0.255586,0.024173,0.136500,-0.152001,0.622415,0.657172,0.249307,-0.463560,0.444182,-0.595341,-0.489087,-0.078962,-0.267941,-0.930159,0.434173,-0.005987,-0.007659,-0.403861,0.471677,-0.374309,0.095354,-0.368025,0.191925,0.028360,-0.173993,-0.041654,-0.516933,-0.128122,-0.225569,-0.386726,-0.600620,-0.036839,-0.308771,0.781812,-1.013794,0.300610,0.532784,0.137954,-0.467733,0.887758,0.467463,-0.091979,-0.646478,0.106584,0.598317,0.002363,0.056820,-0.227401,0.360303,0.355028,0.006103,-0.315810,0.471348', '1292720', '3445516', '2338019', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25821622', '野良神 OAD1', '剧情', '初高中一体，让一岐日和（内田真礼 配音）和山下晶（高山优子 配音）、田端爱美（高桥未奈美 配音）再度成为同班同学。当日和考虑是否要加入料理部时，却被Get新技能的夜斗（神谷浩史 配音）附体，由此性情大变，先是在课堂大大咧咧宣言改变形象，尽展女汉子风范，接着又在走廊、校园内卖弄妩媚，派发联系方式，俨然一副夜店女郎做派。随后更冲上绿茵球场，与校队健儿共同挥洒汗水。倒霉的本尊紧随其后，希望夺回身体，无奈都以失败告终。等到了最后，夜斗更在众目睽睽之下做出了令全校师生大为震惊的壮举来。日和的高中生活，就以如此混乱的局面开始了……©豆瓣', '神谷浩史', 'タムラコータロー', 8.6, 7214, 'tt5235364', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2191875750.jpg', 0.4, 0.9, 13.2, 39, 46.5, '-0.085193,0.162782,-0.363500,0.391099,0.164895,-0.233838,0.204408,0.320004,-0.180187,0.017012,0.059304,0.643623,-0.463333,0.357315,0.417230,-0.474014,-0.244193,-0.647385,-0.270199,0.052480,-0.159177,-0.066931,0.009111,-0.003591,-0.091082,-0.363642,0.726758,0.013689,-0.374315,0.679998,0.451653,0.171236,-0.080748,0.219087,-0.024981,0.046243,-0.074893,0.243926,-0.018425,-0.083286,-0.188480,-0.425609,-0.280083,0.226874,0.213270,0.142537,0.830753,0.005364,-0.270143,-0.120267,0.544531,-0.116341,-0.054941,0.285205,0.233093,-0.074260,0.131230,0.170967,-0.038300,0.007428,0.047728,-0.161481,-0.540759,0.028305,0.004831,-0.128702,-0.371403,0.310045,0.045283,-0.287453,0.402525,-0.267258,-0.081982,0.333386,0.403873,0.315267,-0.244176,-0.061856,0.013665,0.217577,0.549991,0.226068,-0.299247,0.210171,0.021465,-0.245649,-0.003447,-0.222339,-0.035361,-0.113452,-0.028240,0.217445,0.157475,0.098365,-0.421296,-0.262929,-0.137946,-0.069903,0.045137,-0.432718,-0.152097,-0.762415,-0.111906,-0.065387,-0.160278,0.070286,0.055030,-0.042205,0.733584,-0.863203,-0.183925,0.197589,0.160745,-0.317188,0.414635,0.116739,-0.086777,-0.147799,0.060061,-0.022195,0.187148,0.315578,0.027057,0.512750,-0.194733,0.029379,-0.344068,0.294487', '3811356', '5403927', '26784898', '26365262');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25821634', '雷神3：诸神黄昏', '动作', '在“索科维亚战役”两年后，雷神索尔（克里斯·海姆斯沃斯 Chris Hemsworth 饰）识破了洛基（汤姆·希德勒斯顿 Tom Hiddleston 饰）的伪装，辗转找到了被放逐到地球的奥丁（安东尼·霍普金斯 Anthony Hopkins 饰）。然而垂死的奥丁却告知两个儿子，“诸神的黄昏”已经开始，曾遭到奥丁封禁的死亡女神海拉（凯特·布兰切特 Cate Blanchett 饰）即将重返阿斯加德。与海拉的初次对决中，索尔失去了雷神之锤，他和洛基也被打落至混乱不堪的萨卡星。在萨卡的决斗场上，索尔重逢失踪许久的绿巨人，也见到了曾从海拉魔爪下逃得一生的女武神。历经千辛万苦，索尔和战友们重返阴云密布的阿斯加德，去正视这注定要到来的“诸神的黄昏”……©豆瓣', '克里斯·海姆斯沃斯', '塔伊加·维迪提', 7.4, 394221, 'tt3501632', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2500451074.jpg', 0.8, 4.8, 35.5, 43.2, 15.7, '0.278731,0.385971,-0.807501,0.497339,0.039824,-0.734897,0.730676,-0.035228,-0.199737,-0.250461,0.479440,0.852993,-0.523743,0.068193,0.563262,0.127632,-0.609765,-0.770478,0.073953,-0.254091,-0.310046,-0.472084,-0.419803,0.204845,-0.031382,-0.576545,0.494030,0.016967,0.195735,0.383319,0.179005,0.417131,0.004142,0.481211,-0.179091,0.312544,0.034265,-0.185584,-0.274152,0.398027,-0.152147,-0.156021,-0.453739,0.279348,-0.085498,0.387327,0.334030,-0.544313,0.362579,-0.118470,0.372046,-0.461473,-0.078181,0.361888,0.499130,-0.304078,-0.310639,0.154095,-0.005760,0.004427,0.162723,0.017657,-0.551011,0.177273,-0.300378,0.166456,-0.697291,0.414160,-0.145460,0.086882,0.232618,-0.235813,0.262706,0.624777,0.042392,0.482969,0.008360,-0.170073,-0.431817,0.042356,0.700185,-0.135495,-0.417885,-0.028572,0.108163,-0.604886,-0.235211,-0.231479,-0.612204,-0.091352,0.653090,0.065198,-0.011621,0.943038,-0.816576,-0.427824,-0.653990,-0.363582,-0.235685,-0.226441,-0.150905,-0.781511,-0.413776,-0.376834,-0.283911,0.114754,0.040033,-0.172129,0.353483,-0.827302,0.834798,0.412802,0.166031,0.135505,0.329331,0.135441,0.320450,0.011049,0.048636,0.736536,0.386528,0.480349,0.199870,0.193515,0.074280,0.104083,-0.557573,0.705029', '25815577', '2062677', '2034997', '1298095');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25821673', '阿薇尔与虚构世界', '科幻', '安锡动画节最佳电影，被誉为不会令细路欲求动画公仔，而是令世界更美好的电影。20 世纪中拿破仑五世统治的另一个法国，科学家70 年来不断失踪，飞行、电力甚至电影等伟大发明都成泡影，只有艾菲尔建起了第二座铁塔。煤与蒸气把天空弄得乌烟瘴气，出街要戴防毒面具，大皇宫变大温室。阿菲（玛莉安歌迪雅美丽声演）父母是科学家，也无端失踪，当老猫达尔文病到七彩，阿菲偷偷研制不死药，却因此逃亡历险，牙尖嘴利的达尔文、主意多多的怪爷爷、变节特工祖利亚也一起有难同当。《我在伊朗长大》监制再接再厉，法国漫画家Jacques Tardi 原著，糅合凡尔纳和宫崎骏的灵光，以罕见的怀旧动画风，找回失落的动画年代。', '玛丽昂·歌迪亚', '克里斯汀·丹米尔斯', 8.1, 21665, 'tt3422078', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2333129394.jpg', 0.2, 1.4, 19.4, 52, 27, '-0.461645,-0.068522,-0.372266,0.401009,0.352653,-0.231760,0.436504,-0.000214,-0.401294,-0.219244,-0.088869,0.592175,-0.345837,0.081379,0.036937,0.261555,-0.539452,-0.368478,-0.040040,0.006025,0.079790,-0.166040,-0.325155,-0.138359,-0.019317,-0.391773,0.629627,-0.003295,-0.170995,0.102667,0.086488,0.087540,-0.037286,-0.151202,-0.251017,0.016324,0.066270,0.057634,-0.215715,0.095066,-0.072200,0.082441,-0.140210,-0.070563,0.121155,0.026317,0.443851,-0.045973,0.006648,-0.302864,0.536005,-0.132321,-0.273437,-0.158121,0.021588,-0.062042,0.174682,0.049470,0.213248,0.227785,-0.055576,-0.224713,-0.494706,0.346636,0.147835,-0.074118,-0.266414,0.251149,0.054171,-0.086756,0.215839,-0.134799,0.236399,0.011172,0.415716,0.382441,-0.178770,0.339774,-0.480201,0.547764,0.225603,0.009167,-0.336552,0.368304,-0.136723,-0.252850,-0.178022,-0.252046,-0.305122,0.074382,0.267978,-0.276828,-0.230182,0.559317,-0.603057,-0.063531,-0.200290,-0.164255,0.202474,-0.030553,-0.162687,-0.609434,-0.102450,-0.100672,-0.056302,-0.052556,0.258381,-0.106265,0.712899,-0.246087,0.294076,0.295984,0.030578,-0.192217,0.513618,0.002506,-0.202758,-0.257377,-0.118366,0.295998,-0.149280,0.274301,-0.090958,0.025637,0.052009,-0.230489,-0.338871,0.255463', '22265121', '1322847', '27602116', '3318306');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25822430', '炙热', '剧情', '拉妮（坦尼沙·查特里 Tanishta Chatterjee 饰）、拉齐奥（拉迪卡·艾普特 Radhika Apte 饰）和碧琪丽（苏莉温.查瓦拉 Surveen Chawla 饰）是三位个性大相径庭的女子，被命运的红线牵引到了一起。拉妮为了能够为儿子古拉布（瑞迪·森 Riddhi Sen 饰）操办一场体面的婚礼而债台高筑，可古拉布却讲这些来之不易的钱财挥霍在了吃喝玩乐上面。拉齐奥无法生育，因此常常受到丈夫的暴力相向，日子过得苦不堪言。碧琪丽曾经是流浪舞团里人气最高的台柱，无数恩客拜倒在她的石榴裙下，然而，在被老鸨榨干了最后一丝油水之后，碧琪丽也不可避免的要面对被抛弃的命运。在十胜节这一天，三个女人一拍即合，决定逃离她们受人摆弄的悲惨命运。©豆瓣', '阿迪勒·侯赛因', '莉娜·亚达夫', 8.3, 35435, 'tt3043252', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2312414159.jpg', 0.2, 0.9, 13.9, 52.2, 32.8, '0.158055,0.090132,-0.544919,0.365818,-0.265136,-0.246569,0.635267,0.195671,-0.432233,-0.197068,0.115485,0.645172,-0.311614,0.215395,0.290069,-0.155257,-0.040084,-0.758384,0.027939,-0.122482,-0.330149,-0.296135,0.040733,-0.301672,-0.298927,-0.160533,0.387679,0.205077,0.003089,0.205983,0.633226,0.366721,-0.046833,0.061836,-0.406540,-0.028959,-0.113348,-0.087956,-0.122559,0.223821,-0.002462,-0.283624,-0.147212,0.245508,0.168688,0.181841,0.620491,-0.311486,0.198687,-0.053144,0.320519,-0.169904,0.221040,0.459488,0.160676,-0.130946,0.018919,0.294586,-0.288302,-0.039626,0.430662,-0.178777,-0.814213,-0.059564,0.127142,0.162624,-0.769349,0.545225,0.009853,-0.032016,-0.232441,-0.250382,0.235998,0.309288,0.298390,0.317755,-0.001973,-0.106439,-0.501211,0.211209,0.802656,-0.104178,-0.034893,0.262155,-0.371521,-0.111716,-0.131546,-0.504253,-0.663669,-0.171563,0.401883,0.079593,0.014501,0.570345,-0.525847,0.071683,-0.295047,-0.154361,-0.234076,-0.433423,0.000828,-0.371337,-0.367843,-0.563521,-0.360852,0.450093,0.152624,-0.243869,0.547290,-0.620009,0.245910,0.449067,0.307246,-0.417142,0.534331,0.195815,0.268869,0.061571,0.068046,0.431498,0.295819,0.042187,0.136946,0.149545,-0.055547,-0.057602,-0.256088,0.578881', '34875369', '1877596', '26678784', '6874741');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25823035', '夜间飞行', '剧情', '高中优等生永俊和好友基泽并肩面对高考压力，也一起承受来自恶霸同学志雄的校园暴力。三人曾是最要好的童年死党，然而因为一段往事而形同陌路。在一场校外斗殴中，志雄骑走了永俊的自行车，两人的生活再次发生交集。永俊鼓足勇气，对志雄表露了深藏已久的爱慕，然而志雄只能默默守护永俊的心意。两人的暧昧被基泽看在眼里，深感背叛的他故意在校园散播这段男男恋情，让永俊乃至志雄都身陷空前危机......《夜间飞行》是韩国著名同志导演李宋熙日继《不后悔》后的最新力作，入围第64届柏林电影节全景单元。导演以一间叫做“夜间飞行”的废弃同志酒吧作为原点，徐徐展开两个高中男生的爱恨纠缠，大胆揭露韩国社会鲜为人知的校园暴力。《夜间飞行》以高校作为缩影，以小见大的反映了菁英教育给韩国社会带来的边缘人群问题，可以说是李宋熙日从影以来最富野心的一部作品。©豆瓣', '郭时旸', '李宋喜一', 8.3, 30209, 'tt3506934', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199463387.jpg', 0.5, 1.9, 17.2, 41.7, 38.8, '0.353169,-0.199753,-0.483507,0.493284,0.421383,-0.049134,0.389325,0.164289,-0.396422,-0.114045,0.202595,0.575513,-0.288045,0.218668,0.407822,-0.406595,-0.128965,-0.719384,-0.069964,-0.198824,0.070908,-0.369672,0.022065,0.007283,-0.174544,-0.246645,0.874784,0.038976,-0.322815,0.571612,0.398796,0.302985,-0.326323,0.371546,-0.060934,-0.114820,0.230559,0.318275,-0.480364,0.009789,-0.230260,-0.370392,-0.081264,0.118840,0.105895,0.003789,0.737990,0.084336,-0.199535,0.009257,0.480082,-0.260072,-0.301720,-0.193081,0.548238,-0.031740,0.310733,0.388800,0.142930,-0.022115,-0.151035,-0.126476,-0.423259,-0.209762,0.132076,-0.027826,-0.450319,0.451208,0.219466,-0.191780,0.208203,0.080208,0.157308,0.147212,0.390586,0.349871,-0.045285,0.152952,-0.093959,0.209245,0.630552,-0.086333,-0.354018,0.283066,-0.241041,-0.188191,0.046714,-0.206232,-0.709341,0.014727,-0.133485,-0.058582,-0.217666,0.257842,-0.401539,0.099564,-0.099792,-0.070610,0.265596,-0.462279,-0.118948,-0.640458,-0.305163,-0.358193,0.026341,0.055925,0.064396,-0.278498,0.699582,-0.765647,0.093061,0.401451,0.274820,-0.343481,0.802340,0.362541,0.034274,-0.243308,-0.052016,0.190534,-0.230919,0.268666,-0.247265,0.376596,-0.105884,-0.198593,-0.337800,0.219449', '3811356', '3445516', '26365262', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25823132', '暗杀', '剧情', '故事发生在20世纪30年代，日本帝国主义的铁蹄响彻东亚诸国，风起云涌的时代下，一段段传奇接连上演。在中国，效力于韩国临时政府的局务局队长廉锡镇（李政宰 饰）从监狱中释放了被判处死刑的独立军狙击手安沃允（全智贤 饰），随后又找来了爆破专家黄德三（崔德文 饰）、新兴武官学校毕业生“速射炮”秋尚沃（赵镇雄 饰），密令三人暗杀朝鲜驻军司令官以及本国的卖国贼。危险的行动开始了，可是日本方面却很快收到刺杀任务的线报。在狂蛇乱舞的十里洋场，紧张刺激且充满阴谋的较量交替展开，而这也是有关民族命运的惊险对决……本片荣获2015年第36届韩国青龙奖最佳影片奖。©豆瓣', '全智贤', '崔东勋', 8.1, 210868, 'tt3501416', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265086398.jpg', 0.4, 1.5, 19.7, 51.4, 27, '0.091327,0.023457,-0.675542,0.603082,0.427973,0.051390,0.292618,0.140903,-0.491406,-0.023970,0.213946,0.408810,-0.186457,-0.335197,0.337544,-0.464056,-0.214174,-0.853181,-0.303836,-0.246707,-0.042089,-0.361497,-0.214385,-0.215634,0.066797,-0.266739,0.567903,0.179994,-0.405434,0.405995,0.491434,0.425851,-0.173016,0.310253,-0.064287,-0.066505,0.368496,-0.086281,-0.435743,0.180163,-0.068862,-0.523125,-0.150006,-0.037107,0.008145,0.276196,0.519457,-0.242921,0.283375,-0.263173,0.445727,-0.139754,-0.384048,-0.078802,0.572779,0.154729,-0.082410,0.236965,0.209318,0.068077,-0.098066,-0.025464,-0.470620,0.045440,0.407380,0.154598,-0.355972,0.380989,-0.157052,0.222883,-0.040293,-0.003570,0.337563,0.617859,0.448425,0.317182,0.085185,0.285940,-0.367909,0.426630,0.541246,-0.121404,-0.514900,-0.339762,-0.083279,-0.596425,-0.133253,-0.232171,-0.158447,-0.101270,0.446832,-0.296100,0.173217,0.278477,-0.760779,-0.031918,-0.102227,-0.401767,0.033364,-0.141110,-0.108742,-0.821734,-0.087332,-0.383620,-0.156389,0.200080,0.281139,0.099879,0.723143,-0.677593,0.114934,0.446968,0.087809,-0.289912,0.395513,0.243412,-0.102684,-0.163787,-0.034439,0.098264,0.026936,0.442506,-0.028133,0.351151,-0.141285,-0.362452,-0.125159,0.172670', '25723905', '26365262', '20274039', '1307762');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25823277', '三生三世十里桃花', '爱情', '白浅（刘亦菲 饰）失去了上一世的记忆，盘踞在青丘山内，过着与世无争自由自在的生活。在东海盛宴上，白浅遇见了带着天孙阿离（彭子苏 饰）的天族太子夜华（杨洋 饰），实际上，两人之间早就定下了婚约。夜华震惊于白浅拥有的和他死去的妻子素素一模一样的外表，于是开始接近白浅，在此过程中被白浅善良开朗的性格渐渐吸引。实际上，白浅一直忘不了的是当年为了拯救众生而牺牲了自己的天族战神墨渊（杨洋 饰），他的仙体一直被保存在炎华洞内。夜华的侧妃素锦（李纯 饰）十分嫉妒白浅能够得到夜华的喜爱，于是勾结鬼族王后玄女（顾璇 饰）偷走了墨渊的仙体，得知此消息，白浅失去了理智。©豆瓣', '刘亦菲', '赵小丁', 4, 229396, 'tt6138688', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494279388.jpg', 45.1, 26.9, 17.1, 5.4, 5.5, '0.524716,0.672199,-0.620363,0.685181,-0.071857,-0.370551,0.552733,-0.008288,-0.781418,-0.142065,0.029577,0.492913,-0.051345,0.251835,0.096525,0.269258,-0.059959,-0.502332,-0.535198,-0.051729,-0.202277,-0.235146,-0.230422,0.080420,-0.419509,-0.357716,0.682867,-0.016839,0.013253,0.501758,0.354423,0.220037,-0.121406,0.338245,-0.336702,0.099864,-0.319687,-0.014924,0.059511,0.301685,0.029923,-0.250063,-0.010555,0.493204,-0.096262,0.254306,0.606039,-0.510029,-0.038635,-0.206497,0.322009,-0.171299,0.013024,0.176676,0.256823,0.124320,0.127931,0.251005,-0.435231,-0.145484,0.048027,0.126820,-0.463251,-0.147449,0.272938,0.285638,-0.395896,0.701714,0.047047,0.096679,0.115190,-0.344738,0.286842,0.215416,0.129044,0.127483,-0.110384,-0.063112,-0.419733,0.313326,0.627262,0.037552,-0.018584,0.194296,-0.259340,-0.404582,-0.283957,-0.202925,-0.225958,-0.087400,0.341292,0.030434,0.069428,0.372408,-0.491861,-0.066735,-0.163600,0.196742,-0.061678,-0.272334,-0.179337,-0.193017,-0.375234,-0.843144,-0.467704,0.048467,-0.087718,-0.447980,0.556254,-1.051031,0.333805,0.194803,0.158564,-0.447447,0.476265,0.062436,0.022987,-0.118079,-0.017584,0.603397,-0.362027,0.016785,0.136100,0.068881,-0.214985,0.052538,-0.596820,0.414438', '35030151', '21766698', '26354526', '25810920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25823663', '较量', '剧情', '影片前半场，一般幸福家庭生活叙述，与出场人物描述，主角是有线电视营运商，家中成员在一次意想不到的情况下，杀了警政署长的儿子。虽然没有飞天遁地、以一人对抗十人的英雄，但这些叙述都是在为后半场铺陈，缺一不可。请耐住热血，用心看完。影片后半场，主角如何顽抗警察，如何挽救家庭，宛如上帝般创造了日期，不在场的日期。这一连串的为什么…为什么会这样，…为什么会那样，整个剧情令您离不开沙发，憋尿也要看完知道为什么。没有帅哥，没有美女，剧情贴近生活，又那么不可思议，看完后，最大的收获是：你又多一位偶像了。虽然本片网络搜寻的知名度不高。但好片是大家模仿的对象。山寨版的重拍片(Drushyma泰卢固语)7月份已上映。本片制作成本只有4500万卢比，票房收入却高达5亿印度卢比，成为史上最卖座马拉雅拉姆语影片，上映时间更是突破100天，获奖无数。——印坛字幕组', '莫哈恩拉', '吉图·乔瑟夫', 8.4, 6891, 'tt3417422', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2633731823.jpg', 0.3, 0.8, 12.8, 52.1, 34, '-0.291528,-0.092793,-0.399192,0.526250,0.285224,-0.190829,0.469028,-0.075262,-0.246052,-0.185691,0.154563,0.638261,-0.479475,-0.031763,-0.063526,-0.140367,-0.311028,-0.428483,-0.189503,-0.234947,-0.126377,-0.184458,-0.209412,-0.021384,0.004103,-0.106114,0.662961,0.146799,-0.331273,-0.047167,0.404961,-0.075517,0.154150,0.349663,-0.146729,-0.013703,-0.039863,0.135240,-0.039892,0.395972,0.012267,0.008423,-0.326621,0.157298,-0.019999,0.199099,0.352734,-0.118566,-0.290557,0.275670,0.608992,-0.358728,-0.247468,-0.117441,0.251702,-0.085599,0.552930,-0.029742,0.089499,0.068769,-0.164524,0.006884,-1.115333,-0.051716,0.132372,0.248265,-0.477597,0.114261,-0.218909,-0.061082,-0.060351,-0.002700,-0.070509,0.307916,0.589725,0.437365,-0.112170,-0.175315,-0.499281,0.387209,0.583709,0.137367,-0.293498,0.688686,-0.005068,-0.552078,-0.215427,-0.394240,-0.321782,0.349698,-0.006953,-0.007557,0.063679,0.188219,-0.129816,0.049101,-0.170054,-0.564483,-0.177806,-0.528149,-0.112627,-0.490912,-0.071557,-0.207608,-0.132710,-0.126472,0.378317,-0.343112,1.033185,-0.539778,-0.020809,0.258624,0.221066,-0.443061,0.636369,0.369524,-0.305294,-0.061775,0.066280,-0.189780,0.015763,0.102299,0.021197,0.183707,0.230497,-0.568032,-0.341893,0.499712', '27602116', '24284209', '6844861', '27098364');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25823833', '天将雄师', '动作', '故事发生在遥远的西汉时代，汉元帝当政期间，大汉的疆土早已在其曾祖父汉武帝的连年征伐之下拓展到西域纵深处。此时坐镇西域的大都护霍安（成龙 饰）并不以天朝上国的身份自居，他以友善平等的方式与西域各国交往，平等相待，更以独特的方式化解各民族之间的矛盾，取得了单靠武力所无法达到的和平盛景。谁知霍安遭人陷害，被刺配雁门关修城。恰在此时，他遭遇了从遥远的罗马帝国逃命至此的小王子及其护卫卢魁斯（约翰•库萨克 John Cusak 饰），最初的误解过后，霍安与卢魁斯两位英雄化敌为友。但是危机之而来，企图夺得王位的罗马帝国大王子提比斯（阿德里安•布劳迪 Adrien Brody 饰）率领十万大军压境，东西方两大帝国即将发生前所未有的碰撞……©豆瓣', '成龙', '李仁港', 6, 107074, 'tt3672840', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2224484447.jpg', 5.6, 20.4, 49.4, 18, 6.6, '0.320503,0.239039,-0.745423,0.798535,0.365281,0.266191,0.290397,0.261244,-0.540370,-0.257812,0.251030,0.649839,0.066595,-0.282401,0.406703,-0.391175,0.094846,-0.800979,-0.182803,-0.044019,0.082463,-0.376744,-0.490059,-0.109111,-0.557182,-0.440888,0.689424,0.097743,-0.492784,0.459870,0.056326,0.351076,-0.273858,0.466056,0.001788,-0.210743,0.001959,-0.016516,-0.650739,0.110492,-0.250986,-0.258832,-0.166984,0.366247,-0.414966,0.317703,0.324125,-0.623318,0.173281,-0.061917,0.347308,-0.124852,0.018495,0.114790,0.487376,0.021540,0.061274,0.537173,0.136265,0.086149,-0.073392,-0.077025,-0.673582,0.032752,0.085072,0.091639,-0.377174,0.615647,0.033654,-0.274620,0.277647,-0.350613,0.098323,0.910491,0.312316,0.236433,-0.166015,-0.137295,-0.519963,0.087087,0.841804,-0.072786,-0.472411,-0.140337,-0.009425,-0.423861,0.077623,-0.567690,-0.296609,-0.051145,0.181436,-0.085623,0.198231,0.693678,-0.756321,-0.031558,-0.501650,-0.092050,0.316152,-0.141063,0.230642,-0.552979,-0.394709,-0.772341,-0.123497,0.010855,0.488650,-0.051400,0.493925,-0.768409,-0.129387,0.224828,0.469817,-0.587337,0.401430,0.152775,0.126416,0.010717,-0.355773,0.338838,0.182778,0.129296,-0.211843,0.040693,-0.016444,-0.003865,-0.307124,0.389116', '25978126', '1849026', '26316956', '24325798');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25823840', '奸臣', '剧情', '以朝鲜历史上著名暴君燕山君执政时期为背景，讲述的是在君王面前伪装忠臣，实际上却是扰乱政坛主谋的奸臣的故事，其视皇帝为傀儡，实为“王上之王”。', '朱智勋', '闵奎东', 6.6, 76563, 'tt4844288', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2237022344.jpg', 1.9, 12.3, 49.1, 27.5, 9.2, '-0.306239,0.516241,-0.267847,1.279782,0.324862,0.312503,0.296628,0.289898,-0.825867,-0.527258,0.717741,0.409609,0.084907,-0.290341,0.406591,-0.211135,-0.073914,-0.507612,-0.409729,0.000378,0.137917,-0.181174,-0.654148,-0.135565,-0.863209,-0.445926,1.119254,0.191045,-0.364724,-0.333884,0.561796,0.276009,-0.024116,0.195525,0.040601,-0.385886,-0.228141,-0.260533,-0.639986,-0.146140,-0.306710,-0.602333,0.015268,0.275137,-0.462539,0.007667,0.268600,-1.097055,0.262712,-0.677392,0.712629,-0.243455,-0.155277,0.023687,0.827903,0.075170,0.260777,0.841630,0.340614,-0.366478,0.041175,-0.073087,-1.101120,-0.782023,0.191665,0.324241,-0.351680,0.508687,-0.220849,0.051293,0.088990,0.020261,0.592620,0.195215,0.450694,0.477499,0.393005,0.221412,-0.025102,0.306023,0.327642,0.428900,-0.528927,-0.124643,0.045996,-0.529982,0.143673,-0.838312,-0.061357,-0.130184,-0.429508,-0.569548,0.109210,1.174172,-0.071919,-0.449233,-0.358197,0.336669,0.657272,-0.366682,-0.099916,0.000266,-0.054825,-0.441308,0.253283,-0.172640,0.308741,-0.426642,0.615536,-0.922388,-0.122131,0.384314,0.054470,-0.463353,0.619474,0.090151,0.048713,-0.438924,-0.454043,0.162967,0.327976,0.082485,-0.441254,-0.180068,-0.038194,-0.619212,-0.296579,0.581870', '24499012', '3670447', '35087486', '5308201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25824009', '脑残粉', '剧情', '高瑞夫（沙鲁克·汗 Shahrukh Khan 饰）经营着一家网吧，是一个看上去非常普通的男人。可实际上，他是著名影星阿利安（沙鲁克·汗 Shahrukh Khan 饰）的超级粉丝。从很小的时候起，他就被这个银幕上的大英雄深深的吸引着，让高瑞夫没有想到的是，随着年龄的增长，自己的样貌竟然和阿利安越来越相似，甚至相似到了会有人把他们认错的地步。和自己最喜欢的明星长得很像是一种怎样的体验？就这样，高瑞夫参加了明星模仿秀，并且顺利的得到了头筹，很快就要到阿利安的生日了，高瑞夫决定利用比赛获得的奖金前往孟买，真真切切的看自己的偶像一眼。然而，高瑞夫的计划很快就失控了。©豆瓣', '沙鲁克·汗', '玛尼什·莎玛', 6.6, 6808, 'tt3495026', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2393776153.jpg', 2.3, 9.6, 50.5, 32.3, 5.3, '0.345247,0.099318,-0.821104,0.784431,-0.300139,-0.246267,0.820719,0.152136,-0.293350,0.106485,0.268796,1.040416,-0.618701,0.214757,0.262778,0.113189,-0.038542,-0.657336,-0.303687,-0.219442,-0.325952,-0.422314,-0.462631,0.169769,-0.105657,-0.351242,0.527870,0.091616,-0.372268,0.375993,0.341855,0.053924,0.455255,0.663902,-0.524507,-0.062502,0.085174,0.190995,0.348493,0.471496,0.156720,-0.130982,-0.012364,0.397642,-0.299864,0.408090,0.580997,-0.418038,-0.355391,0.142186,0.591308,-0.129635,-0.200819,0.161084,0.361408,-0.087425,0.185524,-0.273039,-0.259279,-0.002379,-0.002415,-0.002921,-0.977993,0.118595,0.270648,0.242064,-0.992617,0.438542,-0.060874,-0.331627,0.239609,-0.389130,0.256606,0.292681,0.110281,0.410677,-0.228812,-0.099235,-0.836142,0.218275,0.822624,0.310749,-0.201432,0.496636,-0.295896,-0.611992,-0.205019,-0.465243,-0.469675,0.245345,0.343932,-0.018393,-0.125735,0.004091,-0.615927,0.018760,-0.017572,-0.400963,0.027694,-0.550617,-0.034890,-0.394509,-0.222773,-0.608289,-0.294383,0.052206,0.092588,-0.530028,1.056828,-1.040307,-0.061236,0.681875,0.199738,-0.385694,0.727595,-0.075675,-0.255627,-0.110878,-0.247741,-0.226883,0.060540,0.323897,0.242402,0.772319,-0.021522,-0.555081,-0.359305,0.933577', '30162520', '1793491', '26387939', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25824686', '变形金刚5：最后的骑士', '动作', '汽车人和霸天虎连年不断的战争，给地球带来了莫大的伤害。为此，地球各国联合成立反应部队，针对变形金刚无论正邪一律绞杀。与擎天柱交往甚密的地球人凯德•伊格尔（马克·沃尔伯格 Mark Wahlberg 饰）不顾身边人的反对和政府的压力，以一己之力为大黄蜂、钢锁等汽车人提供庇护场所，期间他无意得到一枚徽章，从而将危机引向自身。失踪的擎天柱飘回赛博坦，被变形金刚的创造者昆塔沙捕获并黑化，命令他返回地球寻找至高无上的权杖，毁灭地球，复兴赛博坦。与此同时，威震天和地球政府达成协议，彼此联合追寻凯德及其盟友的踪迹，其目标同样是曾属于魔法师梅林的权杖。地球真正的危机终于降临了……©豆瓣', '马克·沃尔伯格', '迈克尔·贝', 4.9, 237369, 'tt3371366', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2462475058.jpg', 18.3, 34.4, 34.7, 8.5, 4, '-0.013517,0.177024,-0.773358,0.792101,0.007818,0.228619,0.323852,0.197658,-0.377102,-0.191257,0.149639,0.879422,0.182500,-0.323704,0.363750,0.047903,-0.195822,-0.592911,0.105737,-0.037267,-0.439398,-0.413258,-0.483925,-0.347684,-0.070780,-0.557007,0.774984,0.158522,-0.368534,0.485013,0.128082,0.417368,-0.260895,0.562073,-0.152170,-0.100448,0.048039,-0.104418,-0.596287,0.119246,-0.512944,0.071914,0.240028,0.548498,-0.338843,0.030016,0.429745,-0.464502,0.320088,-0.657624,0.057987,-0.430031,0.070572,-0.075269,0.565575,0.040688,-0.227733,0.373896,0.129409,0.025008,0.243893,0.110501,-1.020347,-0.135140,-0.161665,-0.036530,-0.471558,0.370211,-0.096877,0.135732,-0.054343,0.054162,0.436137,0.584265,0.258995,0.191921,-0.144620,-0.086780,-0.585911,-0.099309,0.484197,-0.359438,-0.393466,-0.062022,-0.286784,-0.365501,-0.349665,-0.250943,-0.211169,-0.179435,0.382106,0.329437,0.010336,0.602749,-0.807192,0.019904,-0.334754,-0.422129,0.309523,-0.650567,-0.008535,-0.942339,-0.277037,-0.012174,0.017792,0.162092,0.143313,-0.011041,0.844721,-0.793757,0.169723,0.583252,0.740758,-0.682300,0.645229,0.079453,0.259690,-0.565137,-0.018467,0.320982,0.254067,0.553332,-0.075437,-0.309741,0.198317,0.136652,-0.082526,0.354231', '25928048', '4301278', '1793491', '3769423');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25824741', '男人不可以穷', '剧情', '一向安于现状的白领青年薛可正（黄宗泽 饰），被陷害导致失业，同时拍拖多年的女友以娜（邓丽欣 饰）提出分手，一夜间顿时成为双失青年。在儿时朋友栽（洪天明 饰）和刚刚出狱的弟弟可勇（陈伟霆 饰）介绍下，误打误撞进入一金融公司成为黄金经纪。兄弟二人见识了这一行的人生百态和金钱 的丑恶；可勇在公司更认识了后来成为太太的姚静悠YoYo（陈嘉桓 饰）；正当薜可正事业刚刚有起色，家中父亲因癌症去世，兄弟二人大受打击。 薜可正拒绝父亲的好友帮助，离开金融行业转为经营卖烤串的小摊档。在创业初期，薜可正认识了刚烈女子安儿（赵荣 饰）。因为看不过眼安儿的儿子思倪（陈学文 饰）给前夫虐待，毅然帮助安儿和前夫争夺思倪的抚养权。与此同时，可勇与YoYo也闹离婚要争夺孩子抚养权，薜可正从一个双失青年，在现实的生活和家庭纠纷下，逐渐成长为一个真正的男人，而可勇及YoYo也在可正及安儿的影响下，开展了人生的另一阶段……', '黄宗泽', '钟澍佳', 6, 29292, 'tt4216834', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2216942715.jpg', 6.8, 21, 46.2, 18.3, 7.7, '0.133750,-0.016883,-0.351703,0.313758,-0.157554,-0.540874,0.370498,0.446636,-0.495848,-0.304205,0.196538,0.867196,-0.078605,0.324532,0.437150,-0.226789,0.103310,-0.420701,0.005341,0.150189,-0.238411,-0.523327,-0.124958,0.047473,-0.300784,-0.382350,0.619135,-0.052442,-0.362093,0.472628,0.482559,0.102373,-0.164589,0.363432,-0.020258,0.095218,-0.048468,0.322589,-0.544135,0.086652,-0.154599,-0.295294,0.069086,-0.108730,0.017286,0.232690,0.529595,-0.001764,-0.078157,-0.406938,0.693927,-0.020971,-0.273921,-0.057896,0.413380,-0.068088,0.264970,0.257679,-0.437022,-0.139004,0.094301,-0.221177,-0.553629,0.081485,0.211496,-0.109426,-0.739096,0.207755,0.014915,-0.079859,0.205951,-0.120917,0.185453,0.633538,0.186377,0.454128,-0.169579,0.231197,-0.389311,0.329045,0.599146,0.095185,0.181401,0.223043,-0.052334,-0.377324,0.040360,-0.289230,-0.417613,-0.167803,0.246213,-0.107118,-0.207342,0.179025,-0.336268,-0.067972,-0.089073,0.095665,0.365571,-0.337916,-0.065498,-0.139613,-0.314753,-0.330197,-0.329368,0.167870,0.041110,-0.412105,0.630632,-0.805882,0.238869,0.175693,0.404731,-0.767458,0.618115,0.202497,0.364186,-0.370650,-0.036700,0.140648,-0.010878,-0.017564,-0.094599,-0.002708,-0.269799,-0.042969,-0.089562,0.222084', '30345227', '1308035', '35048413', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25824852', '不再说分手', '爱情', '阿森（郑伊健 饰）和小岚（周秀娜 饰）相恋8年，而他们用以维系感情的方法只得两个字——分手。每当小岚以分手作要胁时，阿森都会变成一条死狗去求和，令小岚更加得寸进尺。当他们经历了99次分手后，二人终于认定了彼此，因而许下不能再轻易分手的承诺，更决意要一起为未来打拼，自己当老板，合力经营咖啡店。一众猪朋狗友如茶餐厅太子女瑞哥（王菀之 饰）、阿森的小学同学飞云（何浩鹏 饰）及咖啡店员4大Boy （C  All Star 饰）等人不但见证着咖啡店的成长，同时亦目击营运咖啡店对阿森和小岚这对小情侣所造成的冲击。尤其是当本来平平无奇的咖啡店因着阿森天马行空的鬼主意——《分手迷你仓》，一个可以让所有爱情暴露狂来寄存自己的分手遗物，好让全世界来偷窥的地方——而大受欢迎后，阿森变得不再只以玩乐为先，开始变得成熟，对未来也更有想法。咖啡店的成功令阿森跟小岚之间的距离愈拉愈远，这时候咖啡店的熟客莱莱（温心 饰）跟阿森的关系又变得暧昧不清，这一切彷佛都在引爆他们的第100次分手……', '郑伊健', '郑丹瑞', 5.8, 5670, 'tt3898860', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191689837.jpg', 8.2, 23.9, 45.3, 16, 6.5, '0.318898,-0.116790,-0.643323,0.424228,-0.028214,-0.466565,0.619217,0.244426,-0.318057,-0.025417,-0.056600,0.706071,-0.239062,0.188681,0.143806,-0.194050,-0.166615,-0.709495,-0.087810,-0.191864,-0.153293,-0.581997,0.141228,-0.069269,-0.147863,-0.036375,0.236826,-0.134964,-0.025423,0.418281,0.433350,0.037420,-0.053778,0.341682,-0.057497,-0.134371,-0.096023,0.287200,-0.514254,-0.004642,-0.024509,-0.060625,-0.068257,0.124115,-0.021518,0.213556,0.617005,-0.035804,-0.398084,-0.185801,0.152035,0.037334,0.000846,0.040272,0.194746,0.066981,0.408857,0.353212,-0.313508,0.024163,0.139944,0.087739,-0.588928,0.234557,0.068256,-0.157059,-0.325992,0.214251,0.048513,-0.101426,0.417334,-0.416266,0.109564,0.483325,0.484308,0.251698,-0.304327,-0.089343,-0.498879,0.085206,0.868591,0.083311,-0.080113,0.414424,-0.088602,-0.290978,-0.084583,-0.032823,-0.461600,0.019447,0.148519,0.117404,-0.136063,0.191986,-0.657051,-0.204477,-0.070853,0.014448,0.160617,-0.489048,0.201140,-0.457798,-0.218704,-0.481682,-0.214817,0.354805,-0.032575,-0.120031,0.557953,-0.686886,0.169319,0.386087,0.571278,-0.622394,0.611332,0.222340,0.084610,-0.152016,-0.111087,0.138098,-0.114169,0.265774,0.199655,0.185817,0.23198