INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25825320', '蝙蝠侠：突袭阿卡姆', '动作', '一群由穷凶极恶的死刑犯组成的特种小队，小丑女、死亡射手、回旋镖队长、黑蜘蛛、冰霜杀手、鲨鱼王、克格勃野兽等人，受制于植入脑后的纳米炸药，他们被迫受命闯入阿卡姆疯人院，去取得一份被谜语人窃走的秘密名单。小队成员互相猜忌，各怀心思，哥谭的黑暗骑士又会不会任由自杀小队完成任务呢？囚禁于阿卡姆的小丑和其他恶人又会对任务造成怎样的影响？', '凯文·康瑞', '杰伊·欧力瓦', 8.1, 13282, 'tt3139086', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2193297721.jpg', 0.3, 1.1, 19.7, 51.7, 27.1, '0.157399,-0.282257,-0.221553,0.306028,-0.253670,0.187336,0.645082,-0.065924,-0.412708,-0.133826,0.757518,0.449324,0.306654,-0.406319,0.039094,-0.489482,-0.468645,-0.572432,-0.332923,-0.237562,-0.481091,-0.355806,0.022837,-0.658657,0.342909,-0.372713,0.594418,0.100646,-0.030963,0.022231,0.344993,0.726560,-0.450082,0.253654,0.079053,-0.048475,0.298256,-0.483622,0.098584,0.327064,-0.382255,0.143941,-0.041684,-0.102564,-0.034197,0.110298,1.188111,-0.631733,0.223899,-0.805785,-0.002191,-0.589951,0.053154,-0.063312,0.706400,-0.202398,0.202966,0.076168,0.312224,0.090754,0.047433,0.039390,-0.738338,-0.164295,0.186584,0.466600,-0.339033,0.289091,-0.108761,0.495105,0.373082,0.084061,0.012709,0.062040,0.671381,0.036328,0.032387,-0.043837,-0.510787,0.195796,0.548769,-0.132661,-0.175942,-0.675673,-0.281916,-0.766442,-0.318625,-0.243810,-0.073687,-0.200743,0.476694,0.011076,-0.086012,0.550289,-0.725332,-0.230188,-0.287932,0.083153,-0.153343,-0.960719,-0.080256,-0.727153,0.416158,0.321657,-0.067909,0.680375,0.305957,0.210835,0.475840,-0.603228,0.479945,0.530783,0.287488,-0.422693,0.282426,-0.065205,0.001476,-0.398786,0.066263,0.068897,0.511614,0.519793,0.463036,0.059654,0.021927,-0.107387,-0.055955,-0.054903', '26761688', '25774050', '5364978', '10581450');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25825412', '机械师2：复活', '动作', '系列电影《机械师》第一部中，假装死亡的顶级杀手亚瑟（杰森·斯坦森饰）金盆洗手，过着普通人平静的生活。在一桩看似意外的事件中，亚瑟的红颜知己梅（杨紫琼饰）请求亚瑟解救屡屡遭人毒打的神秘女子吉娜（杰西卡·阿尔芭饰），哪料，向来对爱情有免疫的亚瑟，竟与吉娜坠入了爱河，然而他平静的生活也因此被打破。五年远离是非的生活风平浪静，亚瑟以为自己已经和过去的杀手生涯告别，然而宿命难敌，竟然有人暗中盯上了他，亚瑟的身世之谜也浮出水面。原来，他年幼时和一群孩子被军火商抓去，训练他们玩枪、杀人，难以忍受的亚瑟从军火商手中逃脱，而他的一位小伙伴长大后却成了军火商的接班人，也是影片中的最大反派。这位反派找到了亚瑟，并绑架了他的挚爱吉娜，要挟他去刺杀三个世界上头号危险人物。为了他和他的爱人能够逃脱，亚瑟被迫再度从事刺客工作，他必须在有限的时间内完成一系列不可能的刺杀任务。亚瑟深知反派的残暴，最终一定不会放过自己，在成功暗杀了两个目标之后，亚瑟和第三个目标——另一支规模庞大的军火商头目亚当斯（汤米·李·琼斯饰）结成同盟，一同对付他们共同的对手。那么，亚瑟最终能否和吉娜一起逃脱，平静的生活能否再继续……', '杰森·斯坦森', '丹尼斯·甘塞尔', 5.7, 101199, 'tt3522806', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2385311728.jpg', 5.9, 26.5, 48.9, 14.3, 4.4, '0.246238,0.182293,-0.592340,0.479935,-0.187714,-0.365867,0.840105,-0.097023,-0.478066,-0.216429,0.292498,0.705501,0.091399,0.083421,0.328086,-0.050793,-0.310124,-0.664100,-0.012056,-0.173915,-0.289057,-0.389334,-0.502879,-0.324505,-0.011757,-0.143354,0.794706,0.079731,-0.130061,0.314027,0.401871,0.359699,-0.139446,0.557442,-0.098520,0.002043,0.184724,-0.080752,-0.330403,0.317535,0.006805,-0.334495,-0.080600,0.309811,-0.097532,0.328411,0.534262,-0.430431,-0.000174,-0.173348,0.193325,-0.510503,-0.206625,0.139179,0.377176,-0.184580,0.061742,0.248662,-0.064611,-0.099331,0.040826,-0.074179,-0.838231,0.001970,0.127017,0.109595,-0.601201,0.303478,0.000644,-0.013667,-0.020200,-0.191755,0.072023,0.396689,0.479610,0.102184,-0.267612,0.110912,-0.445162,0.221241,0.800057,-0.010310,-0.224716,0.137597,-0.055487,-0.564845,-0.192907,-0.453594,-0.412754,0.000711,0.529136,0.001637,-0.329056,0.398276,-0.450919,-0.075479,-0.381578,0.048208,-0.215882,-0.516204,0.096143,-0.587889,-0.073413,-0.292693,-0.502118,0.029298,-0.010075,-0.492858,0.611871,-0.812057,0.173750,0.606110,0.232031,-0.482127,0.503927,0.203705,0.247326,-