INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25827286', '钢铁苍穹2：即临种族', '喜剧', '铁空事件发生20年后，前纳粹月球基地已成为人类最后的避难所。地球被核战争摧毁，但是深埋在荒原之下的是一种可以拯救人类最后一部分或者一劳永逸地毁灭人类的力量。当一个老敌人带领我们的英雄进入空心地球探险时，人类创造背后的真相将被揭示。为了拯救人类，他们必须与Vril战斗，Vril是一个古老的变形爬行动物种族和他们的恐龙军队。', '拉腊·罗西', '提莫·沃伦索拉', 5.2, 5950, 'tt3038708', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2541663671.jpg', 11.8, 36.3, 38.5, 9, 4.4, '0.183960,0.320508,-0.449245,0.577236,-0.070603,0.157899,0.729124,-0.558996,-0.289515,-0.102817,0.117489,1.018421,0.197156,0.203595,0.016782,-0.114232,-0.213591,-0.449630,-0.243559,-0.175913,-0.702019,-0.187155,-0.697014,-0.364362,-0.218511,-0.249065,1.346256,0.384289,-0.477870,0.039167,-0.195368,0.590987,-0.189743,0.293027,-0.324722,-0.345380,0.154488,-0.178114,-0.434691,0.282779,-0.413874,0.074653,0.268125,0.468343,-0.722962,-0.047236,0.724228,-0.764657,0.196137,-0.878180,0.267590,-0.607517,-0.124418,0.183370,0.490008,-0.070030,-0.073827,0.515001,0.282463,-0.047258,0.317492,-0.174763,-1.363551,-0.332092,0.053523,-0.117040,-0.235639,0.158026,0.394222,0.156156,0.117898,-0.139075,0.486909,0.688787,0.788881,0.262016,-0.447872,0.065134,-0.684337,-0.143200,0.901165,-0.472981,-0.727465,0.064080,-0.160085,-0.715736,-0.227583,-0.608775,-0.206033,0.177338,0.096036,0.199731,-0.418219,0.542957,-1.234611,-0.083183,-0.443634,-0.436035,0.085001,-0.261850,-0.229386,-0.384445,-0.264182,-0.138308,-0.243398,0.150696,0.138191,-0.041445,0.861098,-0.501150,0.098363,0.695612,0.437925,-0.577672,0.735891,-0.127697,0.215125,-0.342902,0.396337,0.379001,-0.042985,0.660353,-0.075171,0.143830,0.064842,0.179825,-0.356225,0.635183', '26759819', '35377026', '3001114', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25827741', '反转人生', '喜剧', '保险推销员马奋斗（夏雨饰）空有满腔抱负却郁郁不得志，在和女朋友姗姗（宋茜饰）分手后他的人生彻底跌入谷底。然而，神秘人物（闫妮饰）的出现却颠覆了他的生活轨迹，作为一位史上最任性的土地娘，她将马奋斗许过的19个愿望一个个实现，马奋斗一步步走上人生巅峰却引发了一系列爆笑离奇的反转故事。', '夏雨', '伍仕贤', 5, 38077, 'tt3308358', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2633407194.jpg', 13.6, 36, 39.8, 8, 2.6, '-0.054506,0.099607,-0.544451,0.645828,-0.156366,-0.623205,0.931578,-0.033803,-0.101767,-0.181180,0.373291,0.730095,-0.132407,0.167316,0.513119,-0.496328,0.168409,-0.688053,0.094550,0.214581,-0.038624,0.010959,-0.287376,-0.072490,-0.406831,-0.181473,1.017914,0.263845,-0.262017,0.218938,0.306433,0.151374,-0.050489,0.356715,-0.290407,0.308312,0.135559,0.365088,-0.359744,-0.262790,-0.249636,-0.378833,-0.126766,0.223810,-0.355161,0.006645,0.539601,-0.091234,-0.157188,-0.007122,0.553697,-0.489044,-0.212414,-0.016367,-0.067176,0.084156,-0.315392,0.080774,-0.038725,-0.371049,0.104380,-0.199118,-0.916439,-0.219263,-0.114213,-0.100876,-0.677259,0.301569,0.035870,-0.017272,-0.004878,-0.303432,0.050202,0.033758,0.479821,0.292992,-0.426152,0.410458,-0.308723,0.679643,0.935669,-0.043009,-0.420650,0.480272,-0.177183,-0.386117,0.026745,-0.278722,-0.553420,-0.254345,0.201928,0.075771,-0.230122,0.409534,-0.439595,0.082371,-0.474125,-0.130714,-0.024698,-0.524260,-0.343532,0.133683,-0.145332,-0.105033,-0.167273,0.085903,-0.134582,-0.576171,0.819798,-0.483461,0.085215,0.395248,-0.031613,-0.554906,0.615181,0.127998,0.245014,-0.407958,0.309668,0.717828,-0.457448,0.251268,-0.178060,0.305205,-0.381358,0.299640,-0.543281,1.127617', '30349667', '25828589', '30279170', '26315728');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25827935', '七月与安生', '剧情', '七月（马思纯 饰）和安生（周冬雨 饰）的第一次相识在十三岁，她们一个是特立独行飞扬跋扈的“野孩子”，一个是单纯温婉循规蹈矩的“乖乖女”，从那一年开始，七月和安生几乎形影不离，她是她的光，她是她的影子，直到某一天，一位名为苏家明（李程彬 饰）的少年出现在了七月的身边，七月恋爱了。安生决定前往北京讨生活，临别之前，七月意外的发现苏家明贴身带着的玉佩，竟然出现在了安生的衣领里。安生走了，七月和苏家明的恋情持续着，他们考入了同一所大学，约定一毕业就结婚。可是，事情并没有像七月所想象的那样发展，而她和苏家明之间的关系，亦因为安生的归来而产生了新的变数。©豆瓣', '周冬雨', '曾国祥', 7.6, 606448, 'tt6054290', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2378140502.jpg', 0.9, 3.6, 30.1, 47.3, 18, '0.183175,-0.106806,-0.823711,0.451594,-0.177467,-0.358571,0.757275,0.089193,-0.570254,-0.441604,-0.002833,0.672621,-0.596186,0.463209,0.292422,-0.041185,0.046079,-0.825793,-0.107616,-0.436497,-0.239620,-0.367071,-0.096713,0.218614,0.127847,-0.088350,0.582813,-0.021576,0.089149,0.986847,0.449016,-0.202551,-0.060937,0.686846,-0.548385,-0.184955,-0.136789,0.480454,-0.268262,0.007240,0.066975,-0.268582,-0.281640,-0.074009,0.237574,0.472881,0.580257,-0.212917,-0.339103,0.104490,0.553730,-0.165145,-0.350666,0.393625,0.598887,0.077480,0.033245,0.186951,-0.138471,0.092825,0.121981,-0.097934,-0.455160,0.156177,-0.058570,0.162455,-0.681606,0.600365,0.110459,-0.255143,0.124926,-0.387725,0.377329,0.654957,-0.056905,0.332927,-0.289081,0.081315,-0.633741,0.355486,0.606872,-0.159568,-0.476187,0.631680,0.035581,-0.432364,-0.195099,-0.056105,-0.533663,-0.033855,0.009330,-0.188016,-0.343956,0.127836,-0.408295,0.090596,0.041151,-0.046722,0.043613,-0.341804,-0.244223,-0.356461,-0.169051,-0.789597,-0.650785,0.327534,-0.102467,-0.274558,0.486596,-0.974080,0.510984,0.528830,0.518680,-0.426874,0.830115,0.381395,0.314147,-0.067285,0.110819,0.338989,-0.183724,0.332791,0.122174,0.633171,-0.091337,-0.000018,-0.378309,0.488151', '25723081', '34973399', '35030151', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25827963', '西游记之孙悟空三打白骨精', '喜剧', '影片讲述了师徒四人在西行的路上，白骨精（巩俐 饰）为夺唐僧（冯绍峰 饰）而巧设圈套，被孙悟空（郭富城 饰）识破，屡次受挫。唐僧却误会孙悟空滥杀无辜，将其逐出师门。白骨精趁虚而入，掳走唐僧。悟空闻讯前往营救，彻底击溃白骨精。师徒冰释前嫌，重新上路。', '郭富城', '郑保瑞', 5.6, 139546, 'tt4591310', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2315805100.jpg', 9.5, 25.9, 43.9, 15.1, 5.6, '-0.022757,0.119870,-0.446366,0.376968,0.185021,-0.471124,0.191442,0.085286,-0.144349,-0.051560,0.275805,0.465075,-0.269431,-0.290921,0.214890,-0.077803,-0.243840,-0.474481,0.170385,0.100158,0.191781,0.052934,-0.145137,0.104661,-0.113983,-0.171712,0.492717,-0.039081,-0.494114,0.506039,0.450247,0.070041,-0.683873,0.220350,0.058016,0.935722,-0.488200,0.089852,-0.337820,0.038710,-0.498940,-0.513201,-0.002203,-0.162395,-0.614113,0.593525,0.597264,-0.285409,-0.166271,-0.338085,0.321902,-0.786041,-0.038920,0.072552,0.094545,0.057618,0.266414,0.176810,-0.228117,0.238032,0.162720,-0.175001,0.120698,0.370952,0.106574,-0.310635,-0.226698,0.198630,0.010001,0.694317,0.061072,-0.248597,-0.198676,0.245486,0.455996,0.033396,0.362120,-0.151810,-0.405986,0.267378,0.635843,-0.548793,0.735974,0.026097,0.611022,0.397833,0.376455,-0.057062,0.148040,-0.098023,0.961738,-0.030453,-0.113819,0.333685,-0.173239,-0.908960,-0.672760,0.716456,-0.196759,-0.370017,0.590648,-0.703764,0.004566,0.049863,-0.091583,-0.252222,0.346518,0.076657,0.359085,-0.107668,0.293727,0.197509,-0.069970,-0.823859,0.156626,0.084775,0.167130,-0.327551,0.078948,0.435980,0.281592,0.362193,0.431255,0.132820,-0.268502,-0.012722,-0.522695,-0.304128', '1299398', '26882327', '1304021', '1316510');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25828521', '今天的恋爱', '喜剧', '姜俊秀（李昇基 饰）和金贤雨（文彩元 饰）是从小玩到大的青梅竹马，姜俊秀一直以来都默默喜欢着金贤雨，然而，当他决定将心中的感情传达给对方时，却遭到了金贤雨的拒绝。尽管如此，姜俊秀却依然不离不弃的陪伴在金贤雨的身边，成为了她最亲密和最信赖的朋友。金贤雨是一名气象主播，她开朗而又活泼，在电视台里拥有着很高的人气，然而，如此美丽自信的她，却偏偏陷入了同前辈李东镇（李瑞镇 饰）之间的不伦之恋中无法自拔，每日为了这个不值得她付出的男人伤心难过，并常常因此而找姜俊秀大吐苦水。看到金贤雨的痛苦和难过，姜俊秀的心里十分不是滋味。©豆瓣', '李昇基', '朴珍杓', 5.9, 10069, 'tt4315956', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2217374047.jpg', 4.4, 21.5, 52.8, 15.3, 6, '0.205428,0.119802,-0.848697,1.097773,-0.015233,-0.251456,1.264678,0.185395,-0.675090,-0.340018,-0.237813,0.664618,-0.193894,0.848972,0.231001,-0.036635,0.059363,-0.526412,-0.333362,-0.004079,-0.231523,-0.561215,-0.395085,0.013560,-0.476751,-0.142760,0.592323,0.235210,-0.108509,0.608689,0.719251,0.301828,0.169588,0.982977,-0.127841,-0.295621,-0.171711,0.163141,-0.110867,-0.134658,0.394335,-0.398034,-0.099503,0.510131,-0.060535,0.258632,0.504696,-0.172220,-0.386433,-0.006352,0.398308,-0.282170,0.149184,0.135306,0.069843,-0.002969,0.333524,-0.060994,-0.317269,0.243070,0.162512,-0.181997,-0.799130,0.256314,0.535864,0.032884,-0.738602,0.579937,-0.000326,-0.047397,0.183647,-0.204288,0.188824,0.131608,0.332411,0.240986,-0.354367,0.257649,-0.537099,0.031199,0.908040,0.393496,-0.205844,0.457186,-0.415871,-0.525798,-0.042276,-0.430572,-0.550682,0.055402,-0.164306,0.245067,0.213866,0.197578,-0.435724,0.133638,0.184239,0.168845,-0.018022,-0.716022,-0.062088,-0.224191,-0.342780,-1.145129,-0.666746,0.266097,-0.269519,-0.539129,1.151100,-0.984031,0.016344,0.177617,0.259861,-0.693909,1.024505,0.594941,-0.138964,-0.220179,-0.213294,0.683455,-0.105513,-0.212459,0.253130,0.191612,-0.317862,-0.010050,-0.482191,0.864712', '24756472', '26283288', '1417428', '1466907');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25828589', '黑寡妇', '动作', '一部充满动作戏的间谍惊悚片。娜塔莎·罗曼诺夫/黑寡妇遭遇与她的过去相关的一场危险阴谋，将直面自己那些更为黑暗的经历。一股不惜一切要击倒她的力量袭来，娜塔莎必须面对自己在成为复仇者的很久之前那作为间谍的过往，和曾远离的破碎关系。©豆瓣', '斯嘉丽·约翰逊', '凯特·绍特兰', 6.2, 182709, 'tt3480822', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2665872718.jpg', 1.9, 15.8, 55.4, 22.2, 4.7, '0.374208,0.020371,-0.764025,0.680493,-0.111145,0.116864,1.244710,-0.339723,-0.432516,-0.505273,0.341912,0.972350,-0.163121,-0.200287,0.392161,0.007535,-0.123795,-0.948917,-0.363942,-0.091079,-0.086032,-0.111177,-0.538408,-0.043896,0.086966,-0.360675,1.053531,0.212761,-0.588047,0.146162,0.316850,0.482821,-0.164598,0.647826,-0.084072,-0.044269,-0.216042,-0.002292,-0.567167,0.212682,0.424920,-0.336814,-0.244594,0.321218,-0.375278,0.137698,0.482623,-0.229941,-0.174201,0.003887,0.582951,-0.673333,0.110803,0.307012,0.316609,0.449906,0.026091,0.256201,-0.023493,-0.036906,-0.067809,-0.077737,-1.245456,-0.114187,0.073310,0.185090,-0.638694,0.157366,0.008941,0.435797,0.232460,-0.222935,0.180972,0.163900,0.197818,0.261226,-0.361956,-0.007927,-0.377272,0.042426,1.231326,-0.025652,-0.093493,0.063121,-0.215881,-0.296317,-0.287163,-0.233889,-0.330297,-0.090671,0.660458,-0.046393,-0.181515,0.587199,-0.976361,-0.093122,-0.215302,-0.267930,-0.155005,-0.354800,0.122010,-0.747212,-0.465046,-0.592556,-0.197231,0.102450,0.226647,-0.495466,0.536726,-0.755617,0.232421,0.715892,0.392460,-0.331101,0.243865,0.334910,0.125672,-0.161776,-0.034990,0.481941,-0.020475,0.329044,0.131443,0.276020,0.179423,0.030259,-0.418292,0.675724', '2988294', '26667010', '1874704', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25828701', '笔仙惊魂3', '悬疑', '毕业在即，对户外旅行有着共同热爱的驴友高沫（余心恬 饰）、海蓝（郭艳 饰）、于帅（薛斐 饰）、李明哲（郎鹏 饰）和蒋小雪（付曼 饰），在张宇（郭鑫 饰）的召集下走进深山，进行他们的毕业旅行。向导阿吉（卡卡 饰）熟悉山里的情况，好朋友们又都装备齐全，可是最初的快乐轻松很快被意外事件所破坏。明哲和海蓝不慎掉入水中，弄丢了唯一能和外界联系的卫星电话，阿吉催促众人尽快赶路，他相信在山里枉死之人的鬼魂会给他们带来意想不到的麻烦。慌张的年轻人最终来到一个废弃已久的宅邸院落，夜幕降临，贪心的于帅到处在院子里找值钱的东西，之后这个无所顾忌和丧失敬畏心家伙又号召大家玩笔仙寻找刺激。可怕的事件降临在他们中间……©豆瓣', '余心恬', '关尔', 3.4, 5231, 'tt4117310', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2176186826.jpg', 56, 26.1, 12.7, 2.5, 2.8, '0.330277,0.004073,-0.662890,0.232430,-0.096440,-0.043762,0.587606,0.133867,-0.415017,-0.205048,0.144730,0.434390,-0.074845,0.088000,0.140537,-0.002491,-0.511922,-0.447102,0.096123,-0.218960,-0.374853,-0.274119,-0.286233,-0.365632,-0.030043,-0.184256,0.223376,0.152620,-0.147228,0.692357,0.228651,0.239889,-0.232938,0.557407,-0.275118,0.097486,0.036530,0.144589,-0.284540,0.027797,-0.179233,-0.079686,-0.236774,0.083801,0.253979,0.174825,0.677556,-0.159156,-0.337782,0.109088,0.157622,-0.216015,0.010094,0.128117,0.188721,-0.043990,0.269812,0.047235,-0.210223,0.152224,0.108876,-0.000989,-0.450556,0.139889,0.237124,0.076415,-0.501114,0.353890,0.259148,-0.014190,0.278156,-0.268242,0.265510,0.262782,0.208401,0.349194,-0.064926,-0.046098,-0.390151,0.107274,0.592821,-0.303957,-0.097328,0.089104,-0.117922,-0.287592,0.128144,0.113444,-0.353078,-0.052973,0.539489,0.030708,-0.121145,-0.028463,-0.664288,0.113459,-0.001360,-0.215864,-0.098774,-0.307712,-0.224187,-0.648464,0.001169,-0.299896,-0.325261,0.148050,-0.023214,-0.063576,0.633873,-0.566303,0.198423,0.370660,0.183168,-0.541458,0.499475,-0.208940,0.143870,-0.239758,-0.102734,0.080310,-0.011401,0.633103,0.158164,0.370541,-0.258490,0.011506,-0.520731,0.120633', '2159244', '25785314', '1293019', '3147969');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25829175', '西游记女儿国', '喜剧', '唐僧师徒途经忘川河，因激怒河神而误入西梁女界。闯入其中，众人才发现这个国家只有女性，并且建国以来此地就没来过男性。而且国中立有祖训，将男人视为天敌。典籍中更有预言，指明有朝一日，会有东土而来的僧人带着一只猴子、一头猪和一个小蓝人闯入其中。他们到来之日，便是女儿国走向毁灭之时。', '郭富城', '郑保瑞', 4.4, 148486, 'tt6466464', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2511375626.jpg', 28.4, 36.3, 24.3, 7.2, 3.8, '0.014265,-0.010570,-0.790483,0.687329,0.099028,0.184271,0.892901,-0.334405,-0.577539,-0.307425,0.118120,0.906489,-0.080197,0.267325,0.481510,0.042332,0.062587,-0.398422,-0.300823,-0.460118,-0.347612,0.150162,-0.317771,-0.023105,-0.486273,-0.260711,0.744849,0.103198,-0.538979,0.294868,-0.083276,0.195472,-0.575078,0.500809,-0.495725,0.042216,-0.112223,0.240622,-0.041885,0.338395,-0.203994,-0.100999,-0.169437,0.191560,-0.693740,0.138323,0.286652,-0.776203,-0.184271,-0.709362,0.285759,-0.344434,-0.112108,0.134064,0.583554,-0.004167,0.498657,0.344216,0.235427,0.048349,-0.027332,-0.170033,-0.305991,0.082529,-0.001533,0.385001,-0.178606,-0.004428,0.290202,-0.117594,0.012195,-0.342429,0.413305,0.211700,0.469711,0.225920,0.154170,-0.213040,-0.694507,-0.217183,0.712942,-0.430969,-0.180759,-0.117563,0.176550,-0.648410,0.511987,-0.078446,-0.218473,0.077837,0.249674,0.209483,0.084376,0.443022,-0.670689,0.135509,-0.482109,0.161272,0.167823,-0.089184,-0.315006,-0.429627,0.140802,-0.142010,-0.169595,0.452447,0.533587,-0.211389,0.689093,-0.864565,0.407222,0.505256,0.552494,-0.633701,0.926144,-0.288127,0.265534,-0.172238,-0.012465,0.265036,0.290107,0.364057,-0.338766,0.055085,-0.234541,-0.183275,-0.126154,0.117883', '3055049', '25721544', '1302384', '1296538');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25830732', '王牌贱谍：格林斯比', '喜剧', '格林姆斯比》讲述一名英国间谍和一个足球流氓的有趣故事。影片原本由派拉蒙发行，近期版权易主到了索尼哥伦比亚公司手中，片方也在今日宣布影片会在2015年暑期档公映。目前影片的前期筹备工作已经基本就绪，预计在今年夏天开机拍摄。', '萨莎·拜伦·科恩', '路易斯·莱特里尔', 7.4, 101913, 'tt3381008', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321193376.jpg', 1.3, 5.4, 34.5, 40.9, 17.9, '-0.045902,0.250595,-0.677672,0.187372,0.807127,0.017645,0.189453,0.158255,-0.207146,-0.278701,0.285700,0.769418,-0.616605,-0.011337,0.495759,-0.228926,-0.695754,-0.796707,-0.440303,-0.325600,0.103725,-0.278726,-0.388822,-0.308148,-0.290562,-0.448486,0.803428,0.267518,-0.224265,0.416526,0.370601,-0.369783,0.060926,-0.094653,0.059374,-0.030386,0.397774,-0.145652,-0.554106,0.576006,0.131412,-0.572266,-0.232131,-0.156285,0.382422,0.571412,0.689250,0.253122,-0.163323,0.246643,0.936007,-0.375807,-0.286806,-0.179304,0.581384,0.131194,0.122732,0.359471,-0.611556,0.309172,-0.667869,-0.827339,-0.921213,-0.067181,-0.239122,0.322892,-0.185087,0.400116,-0.518276,0.736273,-0.085045,-0.751544,0.030694,0.557806,0.333596,0.227673,0.390376,0.410333,-0.505330,0.970393,0.500688,-0.067606,-0.242980,0.500223,0.559399,-0.349491,-0.811466,-0.162723,-0.362539,0.290896,0.614694,-0.224325,0.020457,0.015454,-0.500802,-0.041807,0.118091,-0.902937,0.171053,-0.289442,0.233346,-1.311009,-0.181827,-0.081647,0.025867,-0.286209,0.512716,-0.096739,0.771652,-0.419953,0.312143,0.513690,0.225968,-0.325479,0.345876,0.070819,0.373126,-0.140524,0.039822,-0.080093,-0.118351,0.206021,0.015323,0.101457,0.265077,-0.779422,-0.492149,0.221777', '34961898', '26275494', '30373716', '3003137');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25830800', '泡沫之夏', '剧情', '尹夏沫（黄灿灿 饰）和洛熙（严禹豪 饰）因同是孤儿的身份让彼此互相吸引。但深爱夏沫的男朋友欧辰（罗仲谦 饰）为了分开两人，把洛熙送到英国留学。夏沫的养父母在送其弟尹澄去医院的路上出车祸死去，夏沫悲痛欲绝，将一切怪罪于欧辰，从而导致他出车祸丧失了记忆。五年后洛熙成了超级天王巨星，夏沫与他重新相遇再续前缘。但一切随着欧辰恢复记忆而崩塌，为了抢回夏沫，他以把肾给小澄作为条件。为了弟弟，夏沫选择了欧辰，却导致婚礼的当天，绝望的洛熙自杀身亡。而无意间得知真相的小澄，在上手术台的前一刻坚持拒绝接受手术。悲痛于洛熙的自杀，愧疚于欧辰的深情，本就备受内心煎熬的夏沫，再也无法接受小澄病逝的打击，支撑不住的她，陷入了与世隔绝的自我封闭状态……©豆瓣', '黄灿灿', '赖俊羽', 2.7, 8171, 'tt6075750', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2363746233.jpg', 76.7, 15.3, 5.6, 1.1, 1.3, '0.119925,0.297475,-0.580901,0.263588,-0.142860,-0.480339,0.593658,0.189514,-0.488269,-0.234227,0.160104,0.676681,-0.050047,0.538580,0.239904,0.026362,-0.194071,-0.853177,0.003517,-0.047329,-0.208892,-0.530766,0.062893,-0.002684,-0.055430,-0.340027,0.895744,-0.049551,-0.253381,0.405290,0.204534,0.509501,-0.139210,0.381700,-0.030422,0.040620,-0.283127,-0.070144,-0.454184,0.184651,0.310454,-0.476034,0.092785,0.389387,-0.125674,0.162030,0.849847,-0.169622,-0.290107,-0.214385,0.397076,-0.505284,-0.174664,0.163859,-0.097725,0.108227,0.215301,0.183427,-0.563458,-0.034826,0.397803,0.168144,-0.581753,0.003808,0.099568,0.000964,-0.498872,0.648725,-0.131797,0.088096,0.178397,-0.365901,0.296670,0.446723,0.170547,0.514772,-0.648115,-0.149814,-0.177985,0.103463,0.752756,-0.151366,-0.199722,0.402153,-0.192454,-0.326958,-0.012619,-0.309057,-0.543465,0.242546,0.289426,0.345965,-0.355386,0.387142,-0.223494,-0.316999,-0.322053,-0.202386,-0.013562,-0.427006,-0.117325,-0.299303,-0.294999,-0.152310,-0.227728,-0.074122,-0.040816,-0.289126,0.547208,-0.758047,0.457989,0.202178,0.268899,-0.634535,0.377703,-0.007306,-0.027783,-0.079683,0.193632,0.585238,-0.140587,0.121378,0.163410,-0.091692,-0.163704,0.443119,-0.592625,0.350559', '30345227', '4202326', '2365260', '34869495');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25830802', '对风说爱你', '剧情', '国共内战期间，连长盛鹏（杨佑宁 饰）身负重伤，却意外遇见了孤儿小奉先（邹轩琦 饰），命运的齿轮开始转动，盛鹏、顺子和小范（胡宇威 饰）精心的照顾着小奉先，三人之间产生了真挚的感情。带着小奉先，盛鹏一行人来到了码头，想要乘船前往台湾。在那里，他偶遇了邱香（郭碧婷 饰）和邱梅（郭采洁 饰）姐妹两，并成为了他们的恩人。来到台湾，人生地不熟的一群人日子过得十分艰苦，他们挤在肮脏狭小的棚户区，过着衣不遮体食不果腹的生活。然而，亲情友情和爱情牢牢的将他们维系在一起，彼此安慰取暖，第一次，这一群并没有血缘关系的人们体会到了家的幸福和温暖。©豆瓣', '杨祐宁', '王童', 6.6, 7529, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2252762269.jpg', 2.8, 13.6, 45.6, 27.7, 10.3, '0.278773,-0.134237,-0.799835,0.435564,-0.024156,-0.170896,0.871731,0.359860,-0.466429,-0.029441,0.158837,0.544760,-0.077926,0.341763,0.121419,-0.041757,-0.370197,-0.563837,-0.137865,-0.087834,-0.406836,-0.243205,-0.081396,-0.194981,-0.276435,-0.110821,0.408558,0.115663,0.038055,0.793164,0.209273,-0.114632,-0.471365,0.448354,-0.500876,0.181836,-0.051091,0.298428,-0.718109,-0.064667,-0.089410,-0.110564,-0.283874,0.021417,0.153178,0.203486,0.817980,-0.382803,-0.052844,0.203577,-0.104292,-0.278142,0.018301,0.123112,0.171351,0.050114,0.305159,0.317459,-0.146519,0.226412,0.211998,-0.213309,-0.559850,0.195249,0.066247,0.116239,-0.799604,0.844103,0.046844,-0.254153,0.117833,-0.480801,0.309201,0.512715,-0.035953,0.366532,-0.357180,0.060485,-0.552794,0.228117,0.863063,-0.127855,-0.017907,0.335890,-0.326135,-0.263027,-0.101544,-0.054358,-0.518209,-0.205166,0.284860,0.048857,-0.240825,0.076346,-0.792875,0.131350,0.067655,-0.097562,0.254832,-0.563568,0.163981,-0.607208,-0.257169,-0.779364,-0.432947,0.465136,0.067016,-0.105889,0.700543,-0.671396,0.109696,0.440669,0.424197,-0.441939,0.788509,0.389182,0.183110,-0.151943,-0.121278,0.241522,-0.169074,0.376588,0.545561,0.506668,-0.402619,0.388833,-0.487185,0.250354', '26687241', '3055049', '3111650', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25831308', '露水红颜', '爱情', '表面看来，刑露（刘亦菲 饰）是一个普通的女孩，享受着普通人的快乐与幸福，也有着普通人的悲伤与烦恼。然而，实际上，刑露拥有着一个特殊的身份——没落贵族的后代。一次偶然中，刑露在一间咖啡店里偶遇了名为徐承勋（郑智薰 饰）的画家，尽管徐承勋身无分文穷困潦倒，但他的善良和才情还是很快吸引了刑露的注意。陷入了爱情的刑露第一次知道了什么是真正的快乐，然而，随着时间的推移，同徐承勋距离越来越近的刑露开始对恋人的身份产生了怀疑。这个男人无牵无挂的仿佛从来没有过去，而他们之间的相遇也或许并不是巧合。面对种种疑问，刑露能够把握自己的未来吗？©豆瓣', '刘亦菲', '高希希', 4.9, 51740, 'tt4311466', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205519937.jpg', 20.5, 33.8, 30.8, 7.7, 7.3, '0.610311,0.155468,-0.791001,0.658957,-0.246988,-0.158364,1.124469,-0.059998,-0.644426,-0.508366,0.010294,0.826881,-0.073059,0.343154,0.199233,0.074209,0.132713,-0.609081,0.042796,-0.328425,-0.139313,-0.591982,-0.508606,-0.184736,-0.213273,-0.142666,0.719643,0.332911,-0.181482,0.787323,0.386566,0.048634,-0.074772,0.716075,-0.215780,-0.250273,0.028655,0.366366,-0.333671,0.116144,0.106584,-0.081434,-0.014919,0.376506,-0.272763,0.453715,0.463509,-0.513485,-0.383274,0.221190,0.402918,-0.251896,-0.111506,0.152807,0.248455,0.066517,0.264862,0.090930,0.001826,-0.043550,0.063801,0.117888,-0.988419,-0.071713,0.241478,0.217181,-0.496703,0.831539,0.216468,-0.529309,0.035057,-0.034702,0.398241,0.372265,0.413525,0.426569,-0.411042,-0.093855,-0.578275,-0.000268,0.916016,0.256497,-0.525201,0.845589,-0.582223,-0.436394,-0.193063,-0.325981,-0.565512,0.200517,-0.053508,0.484925,-0.326734,0.179976,-0.453776,0.257636,0.014383,0.162517,-0.003654,-0.759233,-0.081634,-0.294883,-0.237461,-0.903557,-0.555001,-0.128628,0.025332,-0.507965,0.843295,-1.140059,0.144485,0.552055,0.448960,-0.481029,0.849597,0.241896,0.014634,-0.184842,-0.208615,0.432520,-0.221036,-0.026789,-0.040394,0.279409,-0.102981,-0.087032,-0.332439,0.685777', '1296370', '24756472', '1308755', '1308076');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25831326', '临时同居', '喜剧', '项少龙（张家辉 饰）是一名房地产经纪人，和相恋多年的女友求婚之时，女友竟然嫌弃项少龙拿出的婚房面积太小，声称不购入豪宅便休想结婚，为了娶到心爱的女人，囊中羞涩的项少龙想破了脑袋却也找不到解决问题的办法。就在这个节骨眼上，一幢名为“天下无双”的豪华别墅低价开卖，凭借着敏感的职业直觉，项少龙从中发现了商机，他找来了金凤（郑秀文 饰）、阿黑（杨颖 饰）和瓦力（欧豪 饰），四人共同分担房款，盘下了别墅，只待炒高房价便可出手大赚一笔，可是，就在此时，政府开始打压楼市，无奈之下，项少龙一行人只得先行入住，一个奇特的“临时家庭”就此组成。©豆瓣', '张家辉', '卓韵芝', 5.1, 36539, 'tt3830812', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2195224239.jpg', 12.1, 35.2, 41.6, 7.9, 3.3, '0.170964,0.324300,-0.813694,0.354126,-0.365602,-0.361707,0.447464,0.152911,-0.254113,-0.147214,0.246779,0.690312,-0.073016,0.222043,0.069859,0.224812,0.135173,-0.418266,0.076229,-0.323934,-0.169539,-0.465945,-0.272702,-0.192291,-0.027845,0.084096,0.462223,0.058441,-0.196051,0.196602,0.504795,0.147613,-0.063932,0.351684,-0.236344,-0.029948,0.084205,0.311858,-0.243832,0.330726,-0.184452,-0.309151,-0.096685,0.164487,0.053526,0.393174,0.455953,0.021280,-0.241741,0.117586,0.317694,0.059163,-0.183424,0.046980,0.138923,-0.165171,0.472242,0.002957,-0.535715,0.135961,0.152055,0.037792,-0.566086,0.215346,0.150301,-0.315997,-0.744951,0.291041,-0.235543,-0.307963,-0.145245,-0.499485,0.067164,0.247945,0.174282,0.302507,-0.094399,0.189569,-0.564218,0.153274,0.526911,0.126861,0.109865,0.242691,0.082460,-0.283876,0.072578,-0.193682,-0.202586,-0.195314,0.346090,0.050580,0.017927,-0.405730,-0.618139,-0.024363,-0.354724,-0.052793,0.322286,-0.220198,0.089869,-0.417605,-0.162932,-0.094639,-0.213007,0.324866,0.334319,-0.177984,0.442331,-0.458127,-0.083500,0.456886,0.507412,-0.667740,0.583489,-0.151173,0.156641,-0.017393,-0.071085,-0.299484,-0.050967,0.212172,0.218124,0.212771,0.039038,-0.397105,-0.273211,0.342489', '35461732', '25908042', '1299965', '3215099');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25833230', '乐高幻影忍者大电影', '喜剧', '繁华时尚的忍者岛，乐高小人们过着快乐无忧的日子，除了……隔三差五会遭到邪恶魔头加满都（贾斯汀·塞洛克斯 Justin Theroux 配音）的入侵骚扰外。当然，幸亏有英勇无畏的幻影忍者，他们一次次挺身而出，与魔王大战，才使得忍者岛免于被邪恶统治的危险。绿色忍者劳埃德（戴夫·弗兰科 Dave Franco 饰）是加满都的亲生儿子，不知道他忍者身份的市民们因此经常嘲笑辱骂劳埃德。郁闷的青年只得将一腔怒火撒在以破坏为乐趣的加满都身上。在又一次遭到挫败后，加满都带着威力更强大的军团卷土重来。关键时刻，劳埃德启动了吴大师（成龙 配音）禁止使用的终极武器，最终给忍者岛带来毁灭性的灾难。为了拯救忍者岛，幻影忍者们跋山涉水，甚至与加满都展开了合作……©豆瓣', '成龙', '查理·宾', 6.6, 5847, 'tt3014284', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2493573503.jpg', 1.7, 11.5, 53, 24, 9.8, '-0.123971,-0.005958,-0.396358,0.670445,0.035394,-0.178336,0.485487,-0.219989,-0.144207,-0.213105,0.536986,0.450525,0.055220,-0.002540,0.327417,-0.434214,-0.191014,-0.423094,-0.017890,-0.155613,-0.433473,-0.085121,-0.336784,-0.473538,0.049263,-0.809076,0.374700,0.211643,-0.462525,0.082107,0.367371,0.337965,-0.169233,0.537110,0.032773,0.053020,-0.114272,-0.255357,-0.173541,0.254781,-0.069060,-0.217016,0.051590,0.291363,0.162510,0.274106,0.860468,-0.491893,-0.042282,-0.489773,0.078227,-0.434162,0.107710,0.154581,0.381342,-0.078736,0.131642,0.055847,0.124890,-0.052020,0.169489,-0.047863,-0.774769,0.034849,0.212773,-0.326723,-0.401347,0.324686,-0.035286,0.010209,0.109765,-0.152574,0.170703,0.211972,0.443993,0.283506,-0.120331,0.148321,-0.390746,0.253176,0.769767,-0.322103,-0.190980,-0.240148,-0.192873,-0.173320,-0.093831,-0.675637,-0.367158,-0.059330,0.342503,0.079269,0.017437,0.611979,-0.762465,-0.023520,-0.281182,-0.259463,0.144155,-0.237655,-0.041777,-0.683887,0.232173,-0.116143,-0.109622,0.218096,0.185723,-0.000496,0.900550,-0.648555,0.364210,0.575564,0.504853,-0.425009,0.336958,-0.100776,-0.057069,-0.158578,-0.419347,0.315631,0.379118,0.535157,0.343127,0.209893,-0.157827,-0.153015,0.200288,0.247589', '4181031', '1302661', '26667010', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25833233', '乐高大电影2', '喜剧', '五年前，平凡的艾米特（克里斯·帕拉特 Chris Pratt 配音）拯救了乐高世界，可是德宝星球的外来者却摧毁了好不容易得到的和平。在此之后，乐高世界一片荒芜，外星来客随时在摧毁着每一座完好的建筑。这一日，来自姊姊星系的美汉将军驾驶飞船来到乐高世界，她轻易击败露西、蝙蝠侠等人的进攻，随后带着包括露西在内的五个人前往姊姊星系。在外星球，露西等人见到了随身变女王。此时，女王正筹划在新修建的太空神庙上举办盛大的婚礼，而婚礼对象就是蝙蝠侠。另一方面，艾米特独自飞往太空寻找露西，途中遭遇了豢养恐龙的神秘男子雷斯，于是他们结伴进军姊姊星系。为了阻止末日的发生，艾米特拼尽全力……©豆瓣', '克里斯·帕拉特', '迈克·米切尔', 6.6, 16171, 'tt3513498', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2549353234.jpg', 0.8, 10.1, 54.2, 28.2, 6.7, '-0.161019,0.348688,-0.840002,0.399391,0.090763,-0.015987,0.582245,0.141195,-0.252274,-0.052222,0.308836,0.456010,-0.096906,0.022779,0.631687,0.234175,-0.660899,-0.137016,-0.225486,-0.236193,-0.543689,-0.300378,-0.049916,-0.474687,0.181849,-0.614075,0.685608,0.132996,0.012265,0.192650,-0.060192,0.216342,-0.412311,0.429685,-0.223291,-0.065676,0.167022,0.012463,-0.478592,0.419857,-0.419328,0.307991,-0.137066,0.096326,-0.226139,0.114035,0.624959,-0.429044,0.286176,-0.388751,0.154183,-0.196351,0.182368,-0.357406,0.349077,-0.372839,-0.123812,-0.108207,0.027542,-0.036106,0.379830,-0.320979,-0.398750,0.073089,0.046578,0.158765,-0.443508,0.313388,-0.083241,0.133016,0.061710,-0.146909,0.278809,0.612098,0.396902,0.092780,0.352964,0.444599,-0.535019,0.009951,0.646905,-0.062054,-0.301429,-0.005334,-0.129083,-0.365447,-0.116318,-0.154836,-0.605427,-0.077345,0.211862,-0.133077,0.062919,0.370362,-0.700817,0.151530,-0.550350,-0.368630,0.333094,-0.375154,-0.196470,-0.970369,0.197566,0.237947,0.095663,0.146075,0.017464,-0.085628,0.559394,-0.705900,0.536751,0.478931,0.588140,-0.110103,0.716981,-0.151738,0.179963,-0.501790,-0.085612,0.501730,0.115111,0.615398,-0.088959,0.115288,0.163357,0.120396,-0.295750,0.560867', '3871833', '2159244', '1307897', '1293656');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25833539', '百货战警2', '喜剧', '在商场当了六年保安的保罗（凯文·詹姆斯 Kevin James 饰）攒够了假期，带着即将上大学的女儿玛雅（莱妮·罗德里格兹 Raini Rodriguez 饰），来到“赌城”拉斯维加斯的安可酒店，参加保安大会。会议中途，保罗无意间发现了一个密谋抢劫拉斯维加斯所有赌场的黑帮团伙，于是，他继续跨着电动平衡车，与其他前来参加大会的保安们一起，和天才黑帮首领斗智斗勇，保卫赌城……', '凯文·詹姆斯', '安迪·菲克曼', 5.5, 4005, 'tt3450650', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2211243470.jpg', 8, 27.9, 49.7, 10.4, 4.1, '0.307682,0.164534,-0.696431,0.113481,0.091812,-0.394444,0.335035,0.272102,-0.357607,-0.204063,0.284888,0.877723,-0.429174,0.464181,0.645737,-0.231447,-0.423794,-0.802380,-0.205055,-0.283176,-0.275299,-0.221313,0.194611,-0.212345,0.058585,0.152936,0.174415,0.074867,0.081861,0.892762,0.606433,0.148093,-0.184934,0.269382,-0.177827,-0.280739,0.683369,-0.182411,-0.300599,0.036209,-0.246683,-0.035558,-0.327802,-0.263634,0.574914,0.087493,0.422724,0.136261,0.305930,-0.197350,-0.034448,-0.147541,-0.068181,-0.234237,0.574704,0.038932,0.106171,0.396448,0.192594,-0.136565,0.255814,-0.451549,-0.261388,0.164304,-0.191573,0.078768,-0.797520,0.354360,-0.038289,0.180890,-0.071952,0.037523,0.271528,0.546236,-0.011874,0.013387,0.335447,0.043788,-0.521842,0.325345,0.589832,-0.128409,0.161160,-0.059036,0.166587,-0.461721,-0.071275,-0.261741,-0.262156,-0.025713,0.486222,-0.694993,-0.075460,-0.158315,-0.717913,-0.376284,-0.113038,-0.422457,0.294596,0.014555,0.186376,-1.446478,0.188198,-0.003441,-0.172633,0.300570,0.049250,0.389009,0.385269,-0.984338,0.184894,0.804148,0.322100,-0.516430,0.754543,-0.177000,0.399660,-0.096637,-0.223241,-0.253043,0.268392,0.721755,-0.051782,0.503741,-0.227941,-0.345175,-0.193842,0.192601', '3003137', '2075345', '34961898', '3178770');
