INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25834333', '巴黎危机', '剧情', '执行卧底行动的美国中情局特工肖恩·布瑞尔（伊德里斯·艾尔巴 Idris Elba 饰）接到了一个新任务：他必须调查一个叫迈克尔·梅森（理查德·麦登 Richard Madden 饰）的美国职业骗子，因为这位年轻人可能会让美国官方遭受恐怖袭击巴黎的错误指控。但随着巴黎恐怖袭击的升级，特工意识到这位年轻人是无辜的，并且是他找到幕后真凶的唯一线索……', '伊德里斯·艾尔巴', '詹姆斯·瓦特金斯', 6.5, 14443, 'tt2368619', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2379938430.jpg', 1.2, 9.5, 58, 24.7, 6.7, '0.159058,0.026628,-0.317466,0.712083,-0.302753,-0.143117,0.196693,-0.074720,-0.569334,-0.500362,0.393460,0.820173,0.153764,-0.097308,0.544113,0.291268,-0.534406,-0.563298,0.092860,-0.318074,-0.371279,-0.768181,-0.552320,-0.734044,0.089681,-0.097368,0.395804,0.173244,-0.364353,0.181780,0.524267,0.759697,0.087903,0.199433,0.098688,-0.349476,0.802731,-0.453342,-0.169541,0.405235,-0.022384,-0.080894,0.171468,0.354730,-0.082770,0.620084,0.194857,-0.039255,-0.124775,-0.409504,0.576081,-0.422130,0.061324,-0.020603,0.578107,-0.187674,-0.139708,0.334791,-0.093265,-0.080440,0.123876,-0.118285,-0.922318,-0.159306,0.062496,0.424542,-0.286366,-0.132256,-0.526256,0.087444,0.038261,-0.058619,0.344345,0.546106,0.479386,0.026351,0.154502,0.181712,-0.392715,0.054832,0.339010,-0.149756,-0.263667,-0.036722,-0.148137,-0.610439,0.068783,-0.094834,-0.221425,0.336631,0.184419,-0.223853,-0.216799,0.114967,-0.490469,-0.325865,-0.586329,-0.159792,-0.287354,-0.182490,-0.175238,-0.840869,-0.082088,-0.076455,-0.221786,-0.024153,-0.084067,-0.106882,0.502516,-0.615400,0.123430,1.112168,0.079304,-0.669205,0.313288,0.267142,0.134951,-0.772424,-0.046784,0.229064,0.206813,0.314422,-0.057151,0.030092,0.161192,-0.634671,-0.062070,0.074359', '1309112', '3428500', '1297689', '3230115');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25834457', '偷狗的完美方法', '剧情', '智素（李甄 饰）是一名天真无邪的十岁少女，有一个活泼可爱的弟弟智石（洪恩泽 饰），在爸爸和妈妈正贤（姜惠贞 饰）的精心呵护下，姐弟两快乐而又茁壮的成长着。然而，某一日，幸福的日子突然画下了句点，爸爸离家出走，正贤带着两个孩子失去了唯一能够遮风避雨的归宿。智素一时间无 法接受这巨大的打击，她想尽一切办法，只希望能够找到爸爸，找回曾经拥有的生活。情急之下，她想到了一个损招，那就是绑架老奶奶（金惠子 饰）的狗，以此为筹码获得巨额赎金。年幼的少女是如此的天真，她精心策划的绑票计划能否顺利实施呢？她又能否最终实现自己的梦想呢？©豆瓣', '金惠子', '金成浩', 7.3, 6479, 'tt3812402', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2214375972.jpg', 0.5, 3.7, 38.7, 43.7, 13.4, '-0.326094,0.091822,-0.412923,0.560356,-0.384854,-0.475059,0.544521,0.035953,-0.297102,-0.190273,0.291507,0.478885,0.214299,0.473332,0.132181,0.248930,-0.032354,-0.534377,0.148367,0.049153,-0.136029,-0.364283,-0.318194,-0.056971,0.007826,-0.344498,0.627777,0.091523,0.111301,0.151743,0.313026,0.171548,0.013589,0.144787,-0.465764,0.166413,-0.109845,0.227510,-0.253437,0.112036,0.043821,-0.203081,-0.121919,0.252164,-0.275103,0.234108,0.684068,-0.442125,-0.275298,-0.189132,0.436901,-0.336015,-0.151334,0.188862,-0.202582,0.008655,0.203910,-0.000256,-0.380585,-0.075738,0.387100,-0.248814,-0.919877,-0.249738,0.158153,-0.082327,-0.678099,0.269622,0.085442,-0.056619,0.433675,-0.301449,-0.048116,0.677613,0.186724,0.517447,-0.614240,0.215681,-0.711978,0.384464,0.660137,-0.254352,-0.254132,0.481034,-0.304979,-0.321748,0.238183,-0.418504,-0.526851,0.173526,0.303959,0.048441,-0.155143,-0.080164,-0.456572,0.024427,-0.482897,0.059780,0.207036,-0.663943,-0.127671,-0.098306,0.017990,-0.212373,-0.374998,0.098055,-0.031844,-0.707552,1.022862,-0.803448,0.205897,0.549050,0.339537,-0.516975,0.535002,0.268656,0.065403,-0.251080,0.064879,0.106625,-0.283395,0.107432,0.118979,0.097830,-0.030187,0.173222,-0.407031,0.433396', '24284209', '1877596', '27602116', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25834473', '我的早更女友', '喜剧', '威嘉（周迅 饰）同男友交往多年，两人感情一直十分要好，然而，令威嘉没有想到的是，本以为能够与其顺利步入婚礼殿堂的男友，竟然在毕业的那一天残酷的拒绝了她，从此以后，威嘉的噩梦开始了。失败的爱情经历让威嘉陷入痛苦中无法自拔，心慌气短、精神衰弱、脾气暴躁，这一连串更年期的症状，接连出现在了年轻的威嘉身上。背负着沉重的枷锁，威嘉决定封闭自己的内心，拒绝所有人于千里之外，就在这时，一个名叫袁晓鸥（佟大为 饰）的男人出现在了她的身边。袁晓鸥用自己无微不至的温柔和体贴逐渐化解了威嘉内心的坚冰，在袁晓鸥的帮助下，威嘉逐渐找回了幸福和快乐的感觉。©豆瓣', '周迅', '郭在容', 5.5, 103251, 'tt4024368', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2214812972.jpg', 8.1, 28.8, 47.8, 11.7, 3.6, '0.237487,0.189968,-0.936247,0.709295,-0.096200,-0.187101,0.904806,0.090148,-0.595108,-0.310240,0.062533,0.802135,-0.546138,0.327947,0.351947,-0.106334,0.054791,-0.837364,-0.328775,0.145730,-0.418539,-0.300097,-0.236453,-0.272155,-0.271497,-0.486722,0.624922,0.309637,0.000401,0.591532,0.468927,0.366982,0.147605,0.618390,-0.210381,0.080645,-0.038268,0.071193,-0.311749,0.008649,0.192224,-0.321524,0.196565,0.474124,-0.050345,0.181227,0.636441,-0.141432,-0.477565,0.234476,0.556365,-0.197951,-0.272442,0.159246,-0.060335,0.123261,0.146149,0.136962,-0.461226,0.025269,0.173480,-0.032881,-0.778649,-0.026447,-0.055838,0.109218,-0.626786,0.553597,-0.021099,0.033606,0.069337,-0.344456,0.183961,0.351300,0.245431,0.597758,-0.393556,0.035858,-0.361575,0.120361,0.936854,0.029197,-0.406140,0.489802,-0.246546,-0.183716,-0.003600,-0.215923,-0.486750,-0.111153,0.179657,0.336973,-0.415304,0.282436,-0.379828,0.042218,-0.099785,-0.072517,-0.053663,-0.513309,-0.281438,-0.157310,-0.504878,-0.605590,-0.549378,0.043033,-0.372704,-0.381917,0.589760,-1.089879,0.487808,0.321937,0.333364,-0.326871,0.613191,0.355794,0.062573,0.012427,0.070709,0.331947,-0.380515,0.149896,0.348034,0.389848,-0.342145,0.216699,-0.528322,0.576135', '1301022', '35030151', '1308755', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25834735', '神奇队长', '剧情', '在太平洋西北部的森林深处，与世隔绝，一位慈爱的父亲全心全意地试图将自己六个年幼的孩子培养成出色的成年人。但当灾难降临，他们被迫离开了自己创建的天堂，开始走向外面的世界。这不仅挑战了他对“家长“这个角色的理解，也让孩子们开始怀疑父亲所教给他们的一切。', '维果·莫腾森', '马特·罗斯', 7.9, 42226, 'tt3553976', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2341555072.jpg', 1, 2.8, 22.2, 48, 26.1, '0.303608,0.231245,-0.982927,0.737364,-0.765615,-0.075000,0.634892,-0.133331,-0.514138,-0.116989,0.245598,1.175778,0.193067,0.525246,0.029262,0.177876,-0.179401,-0.713673,-0.412819,-0.137836,-0.422139,-0.418190,-0.397495,-0.396180,-0.150758,-0.166761,0.818958,0.282354,-0.110131,0.259100,0.132606,0.086915,0.093953,0.434803,-0.585280,0.051896,-0.140818,0.086085,-0.266766,0.183285,-0.133508,0.057785,-0.239165,0.549924,-0.137302,0.237530,0.822517,-0.431130,-0.165148,-0.301868,0.479159,-0.576389,-0.095425,0.431240,0.365010,0.049478,0.029023,0.249810,-0.014383,0.150885,-0.394607,-0.264518,-0.966303,-0.108009,0.082322,-0.126338,-0.930894,0.169373,0.251731,-0.290068,0.239629,-0.243954,0.156054,0.386326,0.049659,0.728694,-0.572510,0.079263,-0.425113,0.012826,0.818627,-0.339765,-0.349935,0.328329,-0.180466,-0.344275,-0.061670,-0.365735,-0.633535,-0.029865,0.141885,0.068203,-0.272639,0.380995,-0.495455,0.071340,-0.205105,-0.352664,-0.113262,-0.747499,-0.224235,-0.321320,-0.091559,-0.330335,-0.337333,-0.147487,-0.044536,-0.396695,1.159819,-0.790671,0.276152,0.558933,0.416067,-0.979707,0.788055,0.213730,0.413621,-0.501495,-0.083036,0.637429,-0.040871,0.431787,-0.013265,0.418600,-0.107052,0.129809,-0.509940,0.616123', '30163500', '25928048', '26678784', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25834936', '空中大灌篮：新传奇', '喜剧', '故事讲述勒布朗与他的小儿子多姆被人工智能困在了“华纳兄弟电影宇宙”虚拟空间，为了能安全回家，他必须率兔八哥、罗拉兔和那些不守规矩的乐一通卡通，战胜一支全明星篮球队。这场对决是勒布朗人生的最大挑战，也将重新定义他与儿子间的关系，并让勒布朗领悟到“做自己”的真谛；乐一通的小伙伴们则要打破陈规，超常发挥自己的独特技能，令勒布朗都刮目相看。然而他们面对的，是一群前所未见、所向披靡的人工智能强化型对手“末日狂徒队”，勒布朗和乐一通们真的能成功击败他们吗？', '勒布朗·詹姆斯', '马尔科姆·D·李', 6.2, 12594, 'tt3554046', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2657554193.jpg', 13.3, 17.2, 35.5, 14.5, 19.5, '0.199104,0.057887,-0.298004,0.695650,-0.164278,-0.228769,0.460922,-0.037105,-0.357055,-0.101394,-0.100238,0.720897,-0.421796,0.110769,0.001443,-0.363944,-0.009450,-0.662702,-0.200848,0.096817,-0.057783,-0.410017,-0.251039,-0.240125,-0.020037,-0.268173,0.703747,-0.328171,-0.533254,-0.016927,0.443553,0.307596,0.195755,0.206487,-0.183121,0.160475,-0.013208,-0.158751,-0.369816,0.166135,-0.067910,0.279138,-0.378106,0.402768,-0.037472,-0.261828,0.741605,-0.353738,-0.041611,-0.237661,0.197857,-0.361375,-0.014409,0.290501,0.088954,-0.124537,0.322911,0.222916,0.471682,0.266855,0.079676,-0.324737,-1.236760,-0.075957,-0.024287,-0.483747,-0.259629,0.245314,-0.055410,-0.045874,0.331931,-0.182155,0.116594,0.329166,0.399141,0.490387,-0.290505,-0.292293,-0.613944,0.125114,0.844397,-0.298452,-0.313319,0.236636,0.019642,-0.336707,-0.232784,-0.397973,-0.349153,0.103517,0.440816,0.119732,-0.008769,0.146750,-0.516153,0.206139,-0.223385,-0.344074,-0.230829,-0.673650,0.417137,-0.539978,-0.161621,-0.226005,-0.262326,0.099890,0.046251,-0.263275,0.827429,-0.733525,-0.031041,0.410959,-0.030017,-0.558034,0.465034,0.419486,0.248687,-0.376492,-0.160052,-0.000291,0.175957,0.096840,0.284965,0.443360,0.042762,0.024912,-0.333144,0.619620', '26678784', '30163500', '1793491', '1811755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25835285', '男与女', '剧情', '春电影公司制作的《男与女》，故事讲述一对男女在异国相遇后，沉溺於禁忌爱恋的故事。本片由《精彩的一天》、《爱，不爱》的导演李润基执导。孔侑饰演男主角基宏，是出道以来首次挑战激情戏。全度妍则饰演尚敏，是出於对春电影公司和李润基导演的信任,，接受此一挑战。', '孔刘', '李胤基', 8.1, 75420, 'tt5700648', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2308184818.jpg', 0.4, 1.9, 20.7, 47.1, 29.9, '-0.461700,-0.284617,-0.391210,0.644541,0.468882,-0.090345,0.587026,0.195198,-0.167808,-0.032948,0.181940,0.658827,-0.465711,0.271905,0.665998,-0.292219,-0.177193,-0.645492,-0.471907,-0.169197,0.291464,-0.439857,0.000370,0.175976,-0.186782,-0.618335,1.048157,-0.014051,-0.672390,0.298963,1.171794,0.251992,-0.335526,-0.060460,0.443857,-0.100858,0.129556,0.456645,-1.030716,0.222879,-0.046343,-0.057949,-0.300973,-0.117271,-0.199531,0.075558,0.658803,-0.214241,-0.479307,-0.071278,0.918579,-0.333100,-0.163342,-0.207432,0.276596,0.188375,0.653369,0.361785,0.145334,0.054299,-0.348212,-0.127210,-0.955144,-0.014497,0.417461,0.128955,-0.409538,0.189532,-0.036077,-0.046783,0.152254,-0.033175,0.086491,0.018574,0.886847,0.482625,0.062695,0.339064,-0.014007,0.709584,0.651781,0.243954,-0.206486,0.773914,0.019280,-0.484750,-0.312669,-0.254116,-0.810546,0.481106,-0.046198,-0.248696,0.038380,0.089297,-0.171316,-0.262054,0.259565,0.059318,0.669644,-0.352581,0.099044,-0.896388,-0.212404,-0.137768,0.078324,-0.323462,0.443286,-0.639584,0.885703,-0.758202,0.171150,0.454836,0.190175,-0.524863,1.277294,0.605087,-0.147232,-0.545678,0.217524,0.233347,0.040435,-0.511686,-0.251450,0.407597,-0.122089,-0.065549,-0.785995,0.154045', '1322847', '4109746', '22265121', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25835293', '失孤', '剧情', '黝黑的面颊上，深深刻着饱经沧桑后所特有的苦涩与坚韧，农民雷泽宽（刘德华 饰）驾着一台破旧的摩托车奔走在祖国广袤而荒凉的土地上，十五年的漫长旅程，早已不敢奢求何时是个尽头。1998年的一天，他年仅两岁的儿子被人拐卖，从此下落不明。这一事件彻底改变了老雷的人生，他带着有限的家当以及满满当当的寻人启事，踏上看不见终点的征程。期间的苦辣辛酸，更有几人得知。这一日，老雷因修车邂逅了俊朗的小青年曾帅（井柏然 饰）。仿佛是命运安排的一般，曾帅竟和老雷的儿子有着相似的遭遇。以此为契机，曾帅和老雷结伴同行。一个为了找到失踪的儿子，一个为了找到梦回的故乡。面容模糊的亲人，可曾等在未知的一处……©豆瓣', '刘德华', '彭三源', 6.9, 101701, 'tt4440036', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2231791943.jpg', 1.9, 9.8, 44, 31.7, 12.6, '0.123128,0.080866,-0.637041,0.742382,-0.005291,-0.417475,0.923929,-0.084491,-0.637358,-0.216993,0.167688,0.764772,-0.033832,0.427623,0.235464,0.103585,-0.015380,-0.600723,-0.264928,-0.365025,-0.385429,-0.495435,-0.534015,0.086684,-0.003458,-0.287772,0.693711,0.479318,0.150450,0.675829,0.172326,-0.046385,-0.247610,0.223952,-0.523817,-0.021011,-0.169440,0.266841,-0.176775,-0.117090,-0.082104,-0.384501,-0.103986,-0.083114,-0.478414,0.535413,0.788505,-0.096984,-0.359306,-0.042794,0.416116,-0.136754,-0.096394,0.085425,0.156518,0.046249,0.144751,0.208201,-0.301716,-0.105301,0.151871,-0.150137,-0.823909,-0.147143,0.057259,0.094256,-0.667466,0.686641,0.058181,-0.276888,0.158809,-0.399280,0.332617,0.335397,0.090106,0.519276,-0.187960,0.095590,-0.466815,0.309267,0.838845,0.058754,-0.116199,0.314832,-0.267908,-0.288422,0.055793,-0.381550,-0.792767,0.193512,0.275444,0.178599,-0.261520,0.108116,-0.727302,0.312768,-0.199211,-0.120453,0.065212,-0.316202,-0.335863,-0.201167,-0.200645,-0.646206,-0.296716,0.355895,0.112895,-0.375188,0.654496,-0.610837,0.433607,0.388179,0.024210,-0.303787,0.946189,0.005818,0.159780,-0.149735,-0.043601,0.439198,-0.131205,0.285616,0.051943,0.168211,-0.478594,0.013709,-0.558284,0.503245', '3055049', '26884422', '1303077', '30209018');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25835306', '狱前教育', '喜剧', '家财万贯的对冲基金经理詹姆斯（威尔·法瑞尔 Will Ferrell 饰）因为诈欺被判刑，法官特别给了他30天的时间让他安排处理工作上的相关事宜，身家百万的他为了准备好自己即将面对的恐怖监禁生活，雇用了平常帮他洗车的男子（凯文·哈特 Kevin Hart 饰），在最后自由的30天内对他加强训练，以应付之后的监狱生活……', '威尔·法瑞尔', '伊坦·柯亨', 6.6, 12804, 'tt2561572', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2212607822.jpg', 1.6, 11, 52.7, 26.4, 8.2, '0.074486,-0.048279,-0.448204,0.314340,-0.321495,-0.212483,0.691454,0.543787,-0.281727,-0.250391,0.351984,0.453915,0.131716,-0.020321,0.470537,0.022208,-0.476025,-0.765840,-0.173173,0.016580,-0.473739,-0.488328,-0.144718,-0.239273,-0.137158,-0.224437,0.251454,-0.154152,0.164223,0.175631,-0.146970,0.163827,0.564350,0.395951,-0.041217,-0.329059,0.075542,-0.187851,-0.193744,0.297012,0.176573,-0.159259,0.001143,0.160128,0.280468,0.574345,0.572974,0.032561,-0.260411,-0.089632,0.226288,-0.276086,0.036905,0.161950,-0.075414,0.118231,0.111039,0.389446,-0.513914,-0.247527,-0.015638,-0.182676,-1.106943,-0.155503,-0.094925,-0.159876,-0.598137,0.512396,-0.227976,0.323018,0.108186,-0.439550,-0.077294,0.605640,0.192088,0.318276,-0.079869,0.025189,-0.408665,0.637055,0.495576,-0.042533,-0.174611,0.166546,-0.314306,-0.273984,-0.005295,-0.348177,-0.426181,-0.273655,0.110151,-0.041118,-0.105678,0.055689,-0.534021,-0.058007,-0.344881,-0.575486,-0.323605,-0.484960,-0.176407,-0.676269,-0.204272,-0.325235,-0.671857,-0.098294,0.323614,-0.142696,0.554255,-0.799701,0.238551,0.771403,0.442676,-0.735006,0.604315,-0.035227,0.278394,-0.055642,-0.096167,-0.129989,0.135382,0.756965,0.345592,0.381946,0.217658,-0.315229,-0.347142,0.685507', '26678784', '1793491', '1307442', '3785918');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25837074', '咒怨：终结的开始', '恐怖', '佐伯家的悲剧，就如同一个遭受了最恶毒诅咒后永远无法摆脱的怪圈，所有无意中与之建立联系的人们全被卷入了死亡和恐怖的漩涡之中。年轻教师生野结衣（佐佐木希 饰）临时接到通知，顶替某个突然辞职的老师担任三年级某班的班主任。由于班上的孩子佐伯俊雄（小林飒 饰）长时间缺课，她下班后登门拜访，却见到了神情恍惚、阴森可怖的女主人伽椰子（最所美咲 饰），而她由此被厄运缠身。胆大包天的高中女生莉奈、小葵、弥生（黑岛结菜 饰）硬拉着胆小的女孩七海（特林德尔•玲奈 饰）闯入传说中闹鬼的佐伯家探险，她们注定为此付出惨痛的代价。咒怨的力量如影随形，难以消除，每个人都只能自求多福……©豆瓣', '佐佐木希', '落合正幸', 5.7, 6917, 'tt3572132', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2175018413.jpg', 6.9, 25.6, 49, 12.6, 5.9, '0.278449,-0.021036,-0.453427,0.123998,-0.280190,-0.251363,0.614230,0.100873,-0.300038,-0.393939,0.174988,0.750999,-0.032045,0.437099,0.304023,0.135084,-0.017197,-0.593778,-0.117471,-0.180664,-0.264893,-0.354709,0.062145,-0.012470,0.046120,-0.380459,0.565770,0.135041,-0.144991,0.398508,0.261972,0.593028,-0.266506,0.370791,0.223797,0.128010,0.211597,-0.017404,0.054107,0.121694,-0.228803,-0.163042,-0.028956,0.373014,-0.017570,0.312986,0.591419,-0.445977,-0.230421,-0.333850,0.402972,-0.338743,-0.354624,0.348095,0.321152,-0.063318,0.305717,0.172624,-0.229490,-0.077074,0.093065,0.108020,-0.704513,0.013083,0.198280,0.115281,-0.144606,0.297545,0.219128,-0.080596,0.282394,-0.173130,0.029907,0.069189,0.282792,0.235062,-0.477905,0.025114,-0.019295,0.088516,0.531620,-0.218480,-0.456713,0.021842,-0.178616,-0.068701,0.123827,-0.281353,-0.573340,0.132878,0.226293,0.235671,-0.242626,0.306612,-0.546507,-0.184564,-0.440654,-0.014465,-0.121299,-0.209101,-0.387197,-0.564423,-0.019026,-0.259673,-0.339912,0.196787,0.110215,-0.080953,0.668031,-0.697923,0.213343,0.576369,0.262996,-0.108975,0.319433,-0.113887,0.023720,-0.152519,-0.009772,0.302946,-0.010843,0.564918,0.196740,0.268698,-0.086687,-0.198350,-0.417717,0.277881', '25774050', '3811356', '25928048', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25837175', '谜城', '动作', '前警官天民（古天乐 饰）在纸醉金迷的香港城开着一家小酒吧，这夜，大陆女孩小云（佟丽娅 饰）在酒吧里孤身一人，愁容满面地喝闷酒。打烊之后，醉得不省人事的小云无法开车，无奈之下天民把她送往自己干妈家中休息。翌日，小云在天民和他弟弟少聪（余文乐 饰）的陪伴下去取车——一辆价值不菲的玛莎拉蒂，她发现车钥匙不见了，却不敢回家取。天民感觉到小云隐瞒着不少秘密，而少聪似乎被小云吸引，愿意帮忙。但就在他们取车的时候，一群亡命之徒冲出把小云抓走。兄弟俩和歹徒们激战，小云伺机逃跑。事发之后，天民酒吧被黑帮骚扰，少聪的士也被恶意破坏，甚至还遭到台湾黑帮的疯狂砍杀。两人渐渐地意识到自己已被卷入了涉及巨额黑金的斗争之中，只能奋力一战。本片为香港导演林岭东在阔别影坛7年之后的复出之作。©豆瓣', '古天乐', '林岭东', 5.6, 65707, 'tt3801934', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2257443441.jpg', 6, 27.4, 50.9, 12, 3.7, '0.312282,0.342400,-0.893710,0.169383,0.071453,-0.272483,0.636177,0.202895,-0.498408,-0.138646,0.213619,0.479206,-0.135499,0.400895,0.329558,-0.067157,-0.203921,-0.675024,-0.096010,-0.113529,-0.373127,-0.175512,-0.100881,-0.033903,-0.181228,0.011270,0.209994,0.206836,-0.121314,0.438970,0.225085,-0.031990,-0.336094,0.638086,-0.150346,0.189188,0.242099,-0.111505,-0.055369,0.349299,0.032078,-0.332385,-0.067352,0.062358,0.229222,0.053998,0.795995,-0.034165,-0.082087,-0.024677,0.008551,-0.165631,-0.097190,0.088624,0.379748,0.040194,0.192928,0.023567,-0.422373,0.083418,0.141881,0.285264,-0.341877,0.308443,-0.170180,-0.022650,-0.850257,0.403051,-0.124719,0.048328,-0.099656,-0.533209,0.375430,0.265885,0.141431,0.137988,0.001693,-0.017706,-0.629671,0.094084,0.731965,-0.166807,0.143239,0.348271,0.090497,-0.072712,-0.119162,-0.037411,-0.472718,-0.301987,0.556786,-0.089549,-0.386906,-0.178423,-0.392744,-0.179421,-0.331195,-0.294651,-0.285696,-0.084938,-0.167587,-0.455479,-0.041293,-0.202648,-0.135123,0.318704,-0.051885,0.117333,0.492828,-0.590738,0.232418,0.510665,0.416573,-0.397686,0.603931,-0.208306,-0.096002,-0.004932,-0.023503,0.072075,0.184081,0.406224,0.400144,0.251571,-0.382064,-0.164653,-0.330801,0.125503', '26882457', '1299965', '1303462', '1309125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25837262', '至爱梵高·星空之谜', '剧情', '影片用一封无法投递的信件串联起梵高在去世前最后六周里与他生命中最重要的三个人物之间的秘密，带观众穿越回十九世纪末的欧洲，并陪伴梵高走完他最后的人生。影片采用梵高原画作品中的人物原型还原梵高的艺术人生，让观众在享受美得令人窒息的视觉盛宴时，抽丝剥茧地发现隐藏了一个半世纪的秘密。', '道格拉斯·布斯', '多洛塔·科别拉', 8.5, 218787, 'tt3262342', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2506935748.jpg', 0.2, 1.5, 14.5, 40.5, 43.2, '0.088269,-0.001989,-0.563565,1.065511,0.180844,-0.167966,1.001293,-0.263797,-0.517031,-0.168939,0.189427,1.032645,-0.366675,0.435789,0.404735,-0.018480,-0.406129,-0.909506,-0.284028,-0.312075,-0.301587,-0.298122,-0.461959,0.036474,-0.187225,-0.177773,0.652083,0.272388,-0.194640,0.297041,0.080909,-0.086866,-0.270532,0.199477,0.071171,-0.098979,-0.027440,-0.072758,-0.318601,0.412187,0.037666,-0.422266,-0.113773,0.367880,-0.367551,0.072188,0.847539,-0.608827,0.116961,0.019742,0.550946,-0.051177,-0.489251,0.142718,0.003469,0.344057,0.264050,0.342073,-0.314367,0.255306,-0.159179,0.034238,-1.041828,-0.184928,-0.009408,0.298325,-0.284220,0.441720,-0.069058,0.200788,0.127149,-0.327908,0.513979,0.023065,0.193312,0.467517,-0.206464,0.173238,-0.427322,0.413473,0.194502,-0.152174,-0.362468,0.496879,-0.292775,-0.506067,-0.307214,-0.322777,-0.164505,0.264937,0.202704,0.321310,-0.042328,0.253004,-0.908685,0.073184,-0.093823,-0.307903,-0.096016,-0.400937,-0.416128,-0.789390,-0.189058,-0.365915,-0.197647,-0.086731,0.039553,-0.386524,0.955550,-0.155880,0.211276,0.401449,-0.094325,-0.133276,0.900797,0.153265,0.073465,-0.119450,-0.119244,0.266939,-0.184338,0.407128,-0.025964,0.293699,-0.275765,-0.294865,-0.890430,0.671180', '2027945', '4267948', '27666513', '22265121');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25837574', '男孩', '爱情', '15岁男孩西格（Gijs Blom 饰）性格温顺，喜爱运动。 他刚入选校田径队，经过一个夏天的训练，将和小伙伴们一起参加全国比赛。马克（Ko Zandvliet 饰）是西格的接力队友，两人关系亲昵，玩耍和练习都在一起，慢慢生出暧昧的情绪。清澈湖水中，两个男孩情不自禁的接 吻， 好像发生了什么，又好像什么也没发生......因为叛逆飙车的哥哥，西格认识了邻家女孩杰西卡（Lotte Razoux Schultz 饰）。可是和她在一起，并不像和马克那么惬意，马克看他的眼神更让他揪心。为什么喜欢一个人却不能表达？西格需要时间来理清头绪。©豆瓣', '吉斯·布洛姆', '米莎·坎普', 8.1, 18412, 'tt3318220', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2172200841.jpg', 0.3, 1.5, 22.5, 46.4, 29.3, '0.555432,-0.324094,-0.788207,0.519050,-0.244914,-0.266832,0.988494,0.043862,-0.441599,0.011860,-0.171127,0.498596,-0.425969,0.319106,0.078525,-0.168481,-0.379780,-1.040985,0.142681,0.135230,-0.033556,-0.436286,-0.095854,0.013781,0.148176,-0.244141,0.258284,-0.277905,0.118173,0.787726,0.315488,-0.220065,-0.087701,0.678815,-0.136389,-0.203839,0.178995,0.272704,0.127899,-0.032170,0.164784,-0.048908,-0.331071,-0.088729,0.344373,0.440567,0.406951,-0.066507,-0.178983,0.080598,0.026424,-0.048723,0.166043,0.211523,0.053873,0.020997,0.343710,-0.157019,0.142257,0.159856,0.019212,-0.048161,-0.473350,0.424442,-0.018448,0.588831,-0.499294,0.514852,-0.042292,-0.205349,0.258854,-0.331072,0.044074,0.386944,0.339622,0.432009,-0.269229,-0.064330,-0.397827,0.028601,0.850001,0.009891,-0.322548,0.571418,-0.370681,-0.374473,0.041465,-0.012373,-0.318887,0.164169,0.010968,-0.113564,-0.293442,0.248788,-0.461779,0.077183,0.167214,-0.144858,-0.244385,-0.660247,0.276843,-0.509726,-0.113461,-0.765803,-0.494411,-0.172991,0.045683,-0.244902,0.588966,-0.872421,0.021825,0.584113,0.411298,-0.207398,0.543316,0.220414,-0.241553,-0.061033,0.165612,0.150514,-0.077021,-0.084443,0.206866,0.895764,0.145127,0.102880,-0.323521,0.468463', '34429100', '4275444', '1308755', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25838216', '花宵道中', '剧情', '故事发生在江户时代末年，雾里（高冈早纪 饰）偶然之中遇见了孤女朝雾（安达佑实 饰），将她带回了妓院，训练其成为了游女。朝雾曾遭到母亲的虐待，身上遍布了樱花状的伤疤，却因祸得福，因为这异于常人之处而备受客人喜爱。某日，在盛大的祭奠中，朝雾邂逅了名为半次郎（渊上泰史 饰） 的青年，善良老实的半次郎吸引了朝雾的注意，使得她坠入了情网之中。然而，身为妓院头牌，恋爱是被明令禁止的，朝雾因此而遭到了老板娘的斥责。之后，在吉田屋（津田宽治 饰）举办的宴会上，朝雾和半次郎重逢了，吉田屋察觉到了两人流露出的情谊，占有欲极强的他决定拆散他们。©豆瓣', '安达祐实', '丰岛圭介', 6.3, 13394, 'tt3570006', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2245844114.jpg', 2.3, 15.8, 54, 20.2, 7.6, '0.388850,0.146279,-0.547254,0.353602,0.064743,-0.033837,0.612532,0.279681,-0.549462,-0.219735,0.345737,0.665386,-0.325744,0.331488,0.452659,0.103797,0.035075,-0.714612,-0.218307,-0.150353,-0.183349,-0.475447,-0.085729,0.235178,-0.262717,-0.296157,0.575222,0.281927,-0.276104,0.662334,0.217799,0.421985,-0.093540,0.421490,-0.086275,0.169772,0.038465,0.113959,-0.053173,0.385414,-0.337420,-0.466419,-0.092093,0.208899,-0.149011,0.522985,0.834855,-0.368180,-0.143187,-0.250045,0.400915,-0.222106,-0.056249,0.456624,0.368259,0.082517,0.120930,0.187370,-0.221314,-0.171124,0.284154,-0.031832,-0.411626,0.032882,0.194960,0.061551,-0.468921,0.480669,0.173945,-0.194266,0.119732,-0.037558,0.264248,0.014711,0.230554,0.200238,-0.222627,0.045332,-0.334144,0.157392,0.574781,-0.054230,-0.128335,0.413260,-0.272816,-0.227941,-0.128659,-0.551665,-0.126966,-0.060073,0.128507,0.074524,-0.301003,0.322664,-0.611491,-0.266154,-0.122322,-0.002558,0.098639,-0.089677,-0.409612,-0.543377,-0.078581,-0.660608,-0.572001,0.020798,0.049821,-0.231010,0.552242,-1.106412,0.195807,0.523142,0.321154,-0.166677,0.599087,-0.042296,-0.130181,0.271150,0.049034,0.264078,0.122331,0.100816,0.101878,0.324978,-0.301001,-0.079332,-0.421681,0.348782', '35030151', '1292219', '1826173', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25838463', '像素大战', '喜剧', '21世纪某天，神秘外星人突然入侵地球。奇怪的是外星人全部以20世纪80年代所流行的像素电子游戏形象出现，凡是被它们碰过的物体、人类无一例外都被像素化。现任美国总统威尔·库珀（凯文·詹姆斯 Kevin James 饰）深感事态严重，连忙电话叫来的当年极为擅长街机游戏的玩伴山姆·布伦纳（亚当·桑德勒 Adam Sandler 饰）。在另一个怪鸡朋友勒德洛·莱门梢夫（乔什·加德 Josh Gad 饰）的指点下，他们似乎明白了外星人的真身。入侵接二连三袭来，这群大男孩找来曾经的死对头埃迪·普兰特（彼特·丁克拉奇 Peter Dinklage 饰），联合与伪装成游戏的外星人们展开3D像素大作战。地球危在旦夕，这可真不是能让人轻松以对的游戏……©豆瓣', '亚当·桑德勒', '克里斯·哥伦布', 6.3, 92556, 'tt2120120', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2262297012.jpg', 3.2, 15.8, 50.9, 23.1, 6.9, '0.279401,-0.094065,-0.509378,0.364996,-0.229981,0.139668,0.450376,-0.093718,-0.381570,-0.289656,0.010427,0.892333,-0.298108,0.022692,0.159786,0.171378,-0.352921,-0.471253,-0.106282,-0.210648,-0.256344,-0.245629,-0.481397,-0.476491,0.032217,-0.249650,0.174429,-0.255414,-0.303685,0.358358,0.251570,0.810352,0.005667,0.275676,-0.197964,0.030886,0.059300,-0.211979,-0.187774,0.076618,-0.336348,0.272569,0.061148,0.241137,-0.173800,0.264175,0.377323,-0.406230,0.103094,-0.172820,0.339304,-0.129859,0.028716,-0.079922,0.366213,-0.002558,0.134358,-0.094875,0.311544,-0.040518,0.239172,-0.239558,-0.714094,0.299869,-0.050126,0.007491,-0.260631,0.008749,-0.282069,0.041104,-0.038788,-0.065754,-0.018077,0.256436,0.396454,0.432440,0.091161,0.101122,-0.369650,0.178648,0.335661,0.188898,-0.636771,0.289436,-0.032068,-0.463712,-0.297019,-0.301180,-0.333085,0.048773,0.478719,-0.198770,-0.112824,0.485812,-0.828790,0.063465,-0.251515,-0.156007,0.084298,-0.106956,-0.259519,-0.766799,-0.154283,-0.304646,-0.168334,0.139153,0.070005,-0.005878,0.689156,-0.796275,0.172379,0.570233,0.198464,-0.378155,0.491631,0.099985,-0.229565,-0.191157,-0.263086,0.228342,0.240160,0.332095,0.055171,0.230026,0.144081,-0.137251,-0.299765,0.372739', '1308585', '30382416', '1420088', '1293433');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25839041', '别了武器', '科幻', '看不到一点绿色的荒漠中央，一辆越野车载着数名全副武装的人类疾驰而过。他们来到了那座早已成为废墟的大都市，寻找各种可以回首的有用材料，同时执行这一项极其危险的秘密任务。他们的举动很快就被对手发现，那是一辆战争时期遗留下来的智能战车，它可准确感知对手的存在，并第一时间发动毁灭性的攻击。战士们按照原定计划展开合围，可是根本抵挡不住机器战车的猛烈炮火。死一般沉寂的都市，人和机器的战争逐渐升级。可叹的是，人类制造出如此精良的武器，却用它来毁灭了文明，毁灭了自己……©豆瓣', '二又一成', '角木肇', 8.7, 7595, 'tt15445964', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2172633608.jpg', 0.3, 1, 10.2, 42, 46.5, '0.296342,0.167630,-0.816831,0.760251,-0.012308,0.289533,0.891833,-0.247983,-0.349133,-0.296436,0.465175,0.462576,0.232775,-0.377883,0.024521,-0.304206,-0.160268,-0.316789,-0.142943,-0.066521,-0.577698,-0.279377,-0.337014,-0.288284,0.314029,-0.323474,1.009871,0.325848,-0.334569,0.234085,0.038759,0.145899,-0.043751,0.630922,-0.398088,-0.194774,-0.243423,-0.286063,-0.008073,0.348344,-0.510093,-0.061468,0.149859,0.242587,-0.506105,0.182495,0.838163,-0.468435,-0.183270,-0.226308,0.183341,-0.459445,0.110405,0.060312,0.461758,-0.007075,-0.215925,-0.165888,0.075979,0.288248,-0.157284,0.047583,-1.112247,-0.094481,-0.377683,-0.116686,-0.579246,0.200033,0.034609,-0.111961,-0.197198,-0.393653,0.432840,0.309128,0.288153,0.148539,-0.420039,-0.115722,-0.777161,0.004686,0.555740,-0.351229,-0.612194,0.517267,-0.184758,-0.589186,-0.425713,-0.550625,-0.350340,-0.177229,0.401680,0.458440,-0.098762,0.200502,-0.938542,0.274015,-0.238073,-0.578882,-0.120288,-0.346971,-0.195088,-0.806963,0.070659,-0.357587,-0.411735,0.392348,-0.231157,-0.016296,0.781384,-0.680807,0.076398,0.504855,0.442946,-0.402073,0.447750,-0.298024,0.004241,-0.127121,-0.136761,0.425969,0.029955,0.773069,0.037976,0.321144,0.301139,-0.229837,-0.304396,0.746485', '26667010', '1578502', '1308784', '25774050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25839662', '45周年', '剧情', '就在凯特（Kate）忙于筹备45周年的结婚纪念日之时，她丈夫杰夫（Geoff）突然接到了一条把他的思绪带回过去的消息，他50年前在瑞士阿尔卑斯山因意外丧生的女友的遗体被找到了。凯特和杰夫的内心都受到了极大的震撼却无法交流彼此深藏的不安。杰夫把自己封闭在回忆的世界里，而凯特则竭力压抑自己的嫉妒和焦虑，她还需要专心为聚会做准备，安排音乐、菜单以及其他诸如此类的东西。表面看来，一切如常，但摄影机却敏锐地捕捉了原本和谐的共存逐渐走向失衡的过程。不论是和杰夫共进早餐还是在镇子里独自漫步，凯特都感觉自己越像是一个陌生人。《45周年》中的夫妇二人被意想不到的情绪攫住，被迫面对自己不熟悉的感觉，在这个过程中，他们曾经的好时光仿佛一去不返。在共同生活了45年之后，在他们的结婚纪念日上究竟哪种情绪会占上风呢？', '夏洛特·兰普林', '安德鲁·海格', 7.8, 37601, 'tt3544082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2309810802.jpg', 0.2, 1.5, 24.8, 53.5, 20, '0.427894,0.128075,-1.078937,0.502649,-0.019538,-0.242380,0.908486,0.213916,-0.574777,-0.351506,0.040695,0.707537,-0.293174,0.359120,0.205798,0.053897,-0.431701,-0.862277,-0.048146,-0.128484,-0.200875,-0.354637,-0.425295,-0.224671,-0.137899,-0.295156,0.406146,0.180216,-0.059680,0.480116,0.092896,0.235584,-0.078808,0.969516,-0.192873,-0.067043,0.126122,-0.028795,-0.219127,-0.028795,0.245590,-0.372780,-0.077186,0.414165,0.043732,0.509216,0.846767,-0.148588,-0.198780,0.241204,0.171542,-0.039121,-0.014995,0.301761,0.095388,0.148071,0.047304,0.243280,-0.428658,0.102801,0.064862,-0.099061,-0.821448,0.114650,-0.020604,0.342436,-0.549901,0.678450,0.035151,0.132808,0.261370,-0.407717,0.361599,0.483012,0.364012,0.630749,-0.321103,-0.099124,-0.433109,0.017293,0.897216,-0.026979,-0.080051,0.529315,-0.385197,-0.340398,-0.135712,0.043270,-0.546324,-0.136334,0.280798,0.441088,-0.390701,0.533304,-0.499971,0.080581,-0.015357,-0.325446,-0.106480,-0.693642,-0.167819,-0.661141,-0.205842,-0.472353,-0.275253,0.059545,0.128361,-0.210161,0.597688,-0.813972,0.423647,0.518089,0.194391,-0.398089,0.636710,0.157151,0.118581,-0.095984,-0.083110,0.146066,-0.161457,0.397083,0.252932,0.463672,-0.160130,0.169674,-0.568318,0.716890', '35446144', '3059036', '3742987', '1292211');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25840396', '首尔站', '动画', '在日落后的首尔站，许多流浪汉中的一个老男人，看着象是在吞食着另外一个。不一会儿，整条街都充满着疯子，Hae-sun，一个逃跑的少女，和逼她卖淫的男友分手。她离开了那间在首尔站附近他们目击人们被袭击的破旧旅馆。被袭击的人们变成袭击者，以至于他们的人数呈指数级增长。政府宣布把整片区域 封闭。没被袭击的人们想从袭击者群中逃走，但无处可去。', '柳承龙', '延尚昊', 5.8, 24481, 'tt3845670', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2370768962.jpg', 7.9, 24.1, 45, 17.4, 5.7, '0.787831,-0.214493,-0.872204,0.393602,-0.381898,0.011675,1.292832,0.181974,-0.203560,0.144347,0.439180,0.920356,-0.375444,0.352315,0.151140,-0.224831,-0.091958,-0.584770,-0.242812,-0.290693,-0.282142,-0.372470,-0.292585,-0.274625,-0.142282,-0.080228,0.541761,0.121216,-0.336891,0.311712,0.212855,0.071491,-0.144006,0.739142,-0.556157,0.106979,0.083132,-0.524220,0.542901,0.599460,-0.401582,-0.475813,0.044798,-0.007705,-0.307051,0.517597,1.060488,-0.401055,-0.028639,-0.042682,0.372943,-0.584599,-0.256144,0.545558,0.684051,-0.058887,0.040651,-0.107919,-0.379608,-0.096569,0.048892,-0.056934,-0.412254,0.201208,0.085049,0.278890,-0.997114,0.595330,0.152434,-0.014600,0.171329,-0.428868,0.421691,0.267956,-0.242501,0.422589,-0.024198,-0.095140,-0.993069,-0.038030,0.837838,-0.183557,-0.398223,-0.115834,0.028149,-0.349666,-0.177820,0.054627,-0.560671,-0.434721,0.474671,-0.207899,-0.437293,-0.143174,-0.922948,0.173257,-0.381567,-0.575933,-0.472123,-0.299135,-0.724360,-0.714368,0.091453,-0.257109,0.002904,0.404257,-0.285490,-0.073590,0.632202,-0.749689,0.066412,0.630652,0.665986,-0.436316,0.819252,-0.308787,0.134886,0.340882,-0.201560,0.145507,0.253628,0.791773,0.374746,0.556927,-0.324117,0.080062,-0.426502,0.414186', '21619567', '1394470', '1578663', '1293515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25841341', '我的播音系女友', '喜剧', '故事发生在充满了青葱气息的戏剧学院校园之中，张了了（戚薇 饰）是名震全校的播音系系花，尽管身后随时都跟着一大串的追求者，但心高气傲的了了却从来不把他们放在眼里。戏文系的白亮（汪东城 饰）尽管个性开朗长相英俊，但感情世界一片空白的他对于女性毫无经验，经常搞得自己面红耳赤手足无措。就是这样一个“小白鼠”，竟然喜欢上了追求难度之高人尽皆知的张了了，为了能够获得“女神”的芳心，白亮会使出怎样的招数呢？刚开始，张了了也没把白亮放在心上，但随着时间的推移，白亮善良正直的个性和善解人意的性格渐渐吸引了她，一对有情人终成眷属。©豆瓣', '汪东城', '程中豪', 3.8, 6410, 'tt5364756', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2314811421.jpg', 44.8, 30.9, 17.4, 3, 3.8, '0.359179,0.237543,-0.566199,0.805565,-0.384104,-0.066536,0.729593,-0.017245,-0.416694,-0.147826,-0.100965,0.449772,-0.311493,0.307396,0.079106,-0.085655,0.041571,-0.708937,-0.267403,-0.179596,-0.170919,-0.401118,-0.317763,0.171757,-0.210572,-0.403522,0.474106,-0.031857,-0.422226,0.381436,0.530139,0.057582,0.188181,0.372111,-0.157404,-0.147338,-0.012073,0.229275,0.278101,-0.181788,0.209113,-0.377389,-0.111189,0.312560,-0.031684,0.322638,0.602638,-0.176349,-0.233162,0.107560,0.507395,-0.155904,-0.104171,0.193153,0.348067,-0.118312,0.333232,-0.166696,-0.084139,-0.047298,0.169393,-0.176042,-0.669497,0.209210,0.276937,0.017065,-0.559287,0.327567,-0.020213,-0.255791,0.085470,-0.370870,0.147662,-0.025730,0.317493,0.255157,0.085093,0.051428,-0.478126,0.324590,0.646256,0.260151,-0.600236,0.717718,-0.490140,-0.448552,-0.353949,-0.501887,-0.480982,0.034828,0.336380,0.086245,-0.068451,0.252051,-0.509157,0.158410,0.104551,-0.063220,-0.043181,-0.461229,-0.224008,-0.107599,-0.329757,-0.800778,-0.224160,0.195598,-0.107630,-0.242545,1.112490,-0.876105,-0.056428,0.270564,-0.144251,-0.475664,0.681976,0.117692,-0.241247,0.127097,0.048435,-0.128661,0.224765,0.071475,0.240268,0.649915,-0.155258,-0.437967,-0.264779,0.726440', '26283288', '24284209', '26348103', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25842038', '理查德·朱维尔的哀歌', '剧情', '影片改编自真实事件，理查德·朱维尔作为1996年亚特兰大奥运会爆炸案中发现炸弹装置的保安，而被全世界所熟知。当时他迅速采取行动，拯救了无数生命而成为英雄。但在几天之内，情况就急转直下，梦想成为执法者的他遭受媒体和公众的诽谤，竟成为联邦调查局的头号嫌疑犯，陷入了前所未有的 困境。朱维尔向独立律师沃森·布莱恩特寻求帮助，坚定地宣称自己无罪。然而，在为朱维尔洗脱罪名的过程中，布莱恩特发现自己对抗的是联邦调查局、佐治亚州调查局和警方的联合阻力；与此同时，他也不断提醒理查德不要相信任何试图毁灭他的人……', '保罗·沃尔特·豪泽', '克林特·伊斯特伍德', 8.2, 110610, 'tt3513548', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2578705064.jpg', 0.1, 0.5, 14.2, 60.4, 24.8, '0.123795,0.031441,-0.746098,0.595647,-0.149347,0.151811,0.627571,0.008585,-0.816406,-0.162788,0.186410,0.674135,-0.251513,0.231733,0.330365,-0.155118,-0.287573,-0.970446,0.033560,-0.050222,-0.209981,-0.619685,-0.296703,-0.565086,-0.004221,-0.389789,0.726348,0.464502,-0.457205,0.076412,0.147879,0.711311,0.076085,0.746886,0.305304,0.018750,0.220436,-0.388810,-0.412456,0.412916,0.014409,-0.516309,0.031519,0.504890,-0.145162,0.291260,0.339523,-0.466769,-0.073378,-0.145109,0.588048,-0.713226,0.055955,0.335717,0.168629,0.008292,-0.066128,0.189829,-0.250123,-0.076185,0.151028,-0.307296,-0.969307,-0.064390,-0.020094,0.132298,-0.468699,0.159523,-0.314272,0.118836,0.165684,-0.022416,0.127547,0.155893,0.447770,0.110770,-0.458398,0.219313,-0.467016,0.009149,0.609712,-0.063871,-0.489551,-0.138684,0.017134,-0.433330,-0.328113,-0.329001,-0.294472,-0.080499,0.315520,0.105366,-0.097519,0.533373,-0.345435,-0.331295,-0.466289,-0.553074,-0.043187,-0.497484,-0.030909,-0.572842,-0.093379,-0.122880,-0.098492,0.014676,-0.102035,-0.546233,0.534330,-0.792429,0.308777,0.768066,0.061403,-0.740139,0.643188,-0.014263,0.142051,-0.218203,-0.077602,0.415893,0.591973,0.482732,0.239673,0.005973,0.038762,0.086956,0.084570,0.381021', '1307442', '1917313', '3811342', '30163500');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25843022', '我的国王', '剧情', '影片由法国女导演麦温执导，法国巨星文森特·卡索搭档法国女星艾玛纽尔·贝克特和法国男星路易·加瑞尔出演，影片入围第68届法国戛纳电影节主竞赛单元。值得一提的是，文森特·卡索也有出演入围主竞赛的《故事的故事》，而艾玛纽尔·贝克特执导的影片《昂首挺胸》被选为本届电影节的开幕片 。女律师汤妮（Emmanuelle Bercot饰）滑雪受伤疗养时，回忆起她曾经历过的一段刻骨铭心爱情。她爱上了迷人的餐厅经理乔治欧（Vincent Cassel饰），两人从相互吸引、陷入热恋、甜蜜闪婚到天翻地覆的疯狂毁灭…。而她的疗伤过程，也不断地与这些感情经历相互对映，让观众彷彿置身其中、感同身受，前一秒才纵情欢笑、干柴烈火，下一秒却忌恨争执、甚至大打出手。当爱情从热恋跨向婚姻，究竟该是浓郁的幸福？抑或是烦苦的羁绊？', '文森特·卡索', '麦温', 7.7, 21510, 'tt3478962', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2312348682.jpg', 0.6, 2.5, 27.4, 50.2, 19.3, '-0.072499,-0.168372,-0.583097,0.540630,0.496150,-0.457775,0.882530,0.133593,-0.168567,0.184177,0.271412,0.604560,-0.768832,0.171706,0.655788,-0.101422,-0.361726,-0.783299,0.002532,0.096218,0.052713,-0.094249,-0.272792,0.020705,0.045972,-0.408709,0.745400,0.098301,-0.274995,0.513389,0.578013,0.227352,-0.112544,0.106481,0.197037,0.061727,0.288456,0.351479,-0.736475,0.079137,-0.090060,-0.201732,-0.444468,-0.230316,0.018412,0.147011,0.589892,-0.190549,0.041118,0.023349,0.605202,-0.319768,-0.075807,0.045367,0.009838,0.225204,0.263864,0.135810,0.093138,0.055721,-0.058562,-0.128234,-0.477075,0.138264,-0.061662,0.151612,-0.192572,0.397986,-0.141543,0.160706,0.192218,0.081494,0.081916,0.117915,0.305838,0.220352,-0.064312,0.011475,-0.136588,0.491917,0.756491,0.189039,-0.507376,0.531151,-0.236856,-0.529948,-0.205725,-0.216326,-0.631337,0.254447,0.396677,-0.246211,0.218204,0.518220,-0.503412,-0.034757,-0.008480,-0.305644,0.127839,-0.217738,0.185229,-0.955077,-0.395545,-0.145511,-0.135869,-0.354314,0.144018,-0.270856,0.659809,-0.444811,0.382073,0.504637,0.168793,-0.240200,0.753131,0.295786,-0.109439,-0.260924,-0.095459,0.621272,-0.194880,-0.068769,-0.174173,0.381336,-0.075460,0.244896,-0.424130,0.504130', '34795703', '24751811', '1322847', '10466639');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25843199', '世界奇妙物语 2014年春之特别篇', '悬疑', '《废柴的他与可爱的她》住在政府补贴单身公寓的待业青年秋田雅志（玉森裕太 饰）定制了代号MM－2020α的家庭管家（木村文乃 饰）帮助打理家务，奇妙的男女生活就此展开；《墓友》千代美（渡辺えり 饰）和伊能夕子（真野響子 饰）同买了一处公墓，千代美笑谈二人成为“墓友”，谁知接下来伊能便殷勤地频频来访；《空想少女》不善于和同学交流的高中女生朝比奈薫（能年玲奈 饰）迷恋战国时的武将，回家路上他总将帅气的男孩春斗（入江甚仪 饰）幻想成石田三成，而且为让座的问题陷入幻想；《最后的电影》电视台导演星野绫乃（荣仓奈奈 饰）遭遇施工事故，弥留之际，她不得不亲手为自己编辑人生闪回的影片；《复仇病院》儿子因伤住院，体育老师石田道夫（赤井英和 饰）在大雨之夜被主治医生（藤木直人 饰）叫到医院，谁知医患关系之外，他们还有另一段渊源。©豆瓣', '能年玲奈', '松木创', 6.8, 9193, 'tt3648934', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2177415887.jpg', 0.9, 7.7, 51.7, 30.5, 9.3, '0.074057,-0.084168,-0.241490,0.213039,0.107759,-0.215294,0.471409,0.486303,-0.340293,-0.414212,0.446419,0.461265,-0.163343,0.122160,0.320905,0.041661,-0.262524,-0.704277,0.098714,0.125600,-0.177706,-0.284838,0.002026,-0.047247,-0.246513,-0.243318,0.533189,0.050933,-0.023345,0.293786,0.178670,0.384477,-0.296763,0.183364,-0.001455,0.167701,0.164255,0.161772,-0.223812,0.071723,-0.222462,-0.200749,-0.104802,0.040961,0.076741,0.281723,0.822598,-0.003811,-0.167045,-0.186926,0.363110,0.059643,-0.115675,0.216478,0.191807,0.026293,0.227534,0.123060,-0.289933,-0.042334,0.219455,-0.112997,-0.507652,0.134552,0.165068,0.145734,-0.398778,0.436569,-0.159904,-0.218623,0.352869,-0.090458,-0.051203,0.216012,0.349490,0.247896,-0.095917,0.260527,-0.164380,0.454478,0.419986,0.040188,0.006501,0.451366,-0.215542,-0.316999,-0.279771,-0.082626,-0.460726,0.115180,0.011344,-0.201758,-0.053970,0.008905,-0.522313,-0.129775,-0.206992,0.100852,0.150005,-0.167079,-0.168736,-0.532334,0.165082,-0.308563,-0.339767,-0.009335,0.313549,-0.095391,0.787712,-0.688436,-0.127885,0.462355,0.305178,-0.294000,0.584636,0.150370,0.040510,-0.277806,-0.080197,0.075203,-0.164448,0.266035,0.242010,0.299333,-0.176781,-0.032205,-0.382363,0.045165', '3811356', '5403927', '10174444'