INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25843976', '夏有乔木 雅望天堂', '爱情', '年少的夏木（吴亦凡饰）因亲眼目睹母亲自杀而变得自我封闭，直到16岁的舒雅望（卢杉饰）出现，用温暖关怀渐渐融化夏木的心。雅望青梅竹马的恋人唐小天（韩庚 饰）高中毕业后进入军校，不料就在唐小天就读军校期间，曲蔚然（周元饰）出现并摧毁了雅望的生活，也让夏木在绝望之下做出疯狂行径……夏木、雅望、唐小天，他们还能找回曾经的那个天堂吗？', '韩庚', '赵真奎', 4.7, 83505, 'tt4171876', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2371135705.jpg', 29.9, 28.4, 25.1, 8.1, 8.6, '0.348765,0.310736,-0.772141,0.468480,-0.237150,-0.467751,0.601285,0.207948,-0.585776,-0.207514,0.428098,0.487913,-0.276482,0.557381,0.315411,0.015776,-0.072480,-0.839693,0.121850,0.024020,-0.158622,-0.215251,-0.004455,0.158479,-0.103371,-0.531838,0.760564,-0.150197,0.021852,0.545192,-0.130381,0.331341,0.099925,0.492208,-0.025979,0.070868,-0.121130,0.207529,-0.336087,0.075926,-0.060875,-0.209744,-0.120283,-0.010807,-0.268622,0.295753,0.878799,0.074527,-0.209046,-0.060772,0.363385,-0.461524,-0.508948,0.414993,0.104726,0.141990,-0.052127,0.208382,-0.480502,0.293084,-0.163228,0.155794,-0.435538,0.102245,0.003022,-0.073308,-0.275547,0.326668,0.209151,-0.004788,0.302161,-0.498147,-0.032264,0.113417,0.136718,0.709529,-0.719079,0.007696,-0.024517,0.150498,0.695771,-0.441103,-0.438442,0.426911,-0.280314,-0.249924,0.225898,-0.011070,-0.464152,-0.010097,-0.177961,0.106352,-0.370920,0.334956,-0.512557,-0.173539,-0.502007,-0.115904,0.330596,-0.472265,-0.392485,-0.441746,-0.289046,-0.147848,-0.230387,0.146200,-0.055241,-0.487301,0.513366,-0.949324,0.422930,0.143497,0.364559,-0.308638,0.253222,0.096722,-0.414563,0.220797,-0.090958,0.937739,-0.277629,0.387555,-0.290048,0.148646,-0.144296,0.075223,-0.329701,0.538649', '2365260', '30345227', '6973376', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25845294', '勇士之门', '奇幻', '废柴男孩（尤赖亚·谢尔顿 Uriah Shelton 饰）机缘巧合地开启了异世界的大门，卷入了一场惊心动魄的种族斗争：武士（赵又廷 饰）和公主（倪妮 饰）与蛮人军队斗智斗勇，不仅如此，两位身负国家和种族命运的勇士还要面对凶悍的蛮人和伺机夺命的巨人、树妖等精怪。一次次险象环生的经历，他们一直在等待传说中的黑骑士到来……', '赵又廷', '马蒂亚斯·霍恩', 3.5, 7952, 'tt4652532', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2393908940.jpg', 46.9, 35.4, 13.6, 2.1, 2.1, '-0.154154,-0.251938,-0.494059,0.576095,0.081479,0.257177,0.999560,-0.004609,-0.717667,-0.254351,0.603760,0.646103,-0.326424,-0.257819,0.572869,-0.523721,-0.224986,-0.514137,-0.073260,0.163340,-0.426490,0.136247,-0.493987,-0.326035,-0.144130,-0.681022,1.085548,0.162493,-0.228475,0.291729,0.062737,0.162255,-0.475004,0.422922,-0.342342,-0.135504,0.023236,0.188636,-0.367925,0.024294,-0.263323,-0.205388,-0.409481,0.080034,-0.276612,-0.046266,0.685881,-0.954021,0.374462,-0.504037,-0.203934,-0.374219,-0.301451,0.066168,0.549115,-0.333925,0.486031,0.132546,0.551038,-0.319856,0.123088,-0.264545,-0.771342,0.063142,0.352457,0.116201,-0.441384,0.596046,0.202175,0.396233,0.220113,-0.224325,-0.110080,0.354665,0.521962,0.380165,0.011250,-0.381259,-0.629384,0.141174,0.580487,-0.067412,-0.324751,0.108338,-0.003457,-0.781842,-0.598674,-0.516665,-0.832919,0.020661,0.486916,-0.112431,-0.319810,0.597074,-1.030959,0.244582,-0.263372,-0.055117,-0.053002,-0.680055,-0.221703,-0.593804,-0.036636,-0.642721,0.021052,0.343700,0.209865,0.049475,0.934127,-0.905250,0.002301,0.347859,0.393240,-0.327924,0.781128,-0.019274,0.083514,-0.376056,-0.158524,0.161908,0.069242,0.112487,0.198922,0.424762,-0.288105,0.238306,-0.207729,0.239476', '26290398', '26759819', '5938000', '19899707');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25845383', '青春之旅', '爱情', '高中女孩吉冈双叶（本田翼 饰）刻意让自己显得不修边幅，以避免成为其他女生攻击的对象，每天都不得不为此小心应付，殚精竭虑。某天，她意外重逢了曾在初中时代有过交集的男孩田中洸（东出昌大 饰）。当初田中搬家到了长崎，此番重逢后不仅将姓改成了马渕，性格似乎也发生巨大的变化。以班级活动为契机，双叶、马渕、马渕的好友小凑亚耶（吉泽亮 饰）、特立独行的高冷女村尾修子（新川优爱 饰）以及因过于可爱而遭到孤立的槙田悠里（藤本泉 饰）聚到了一起。原本他们的情感便彼此交错，而隔壁班的天才帅哥菊池冬马（千叶雄大 饰）、教师田中阳一（小柳友 饰）以及马渕在长崎的旧友成海唯（高畑充希 饰）又让男孩女孩们的关系更为复杂，于是平添了无数的烦恼……本片根据漫画家咲坂伊绪的同名原作改编。©豆瓣', '本田翼', '三木孝浩', 6.4, 19293, 'tt6075718', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2199393182.jpg', 2.4, 14.8, 51.6, 23.6, 7.6, '0.154241,-0.148513,-0.439597,0.384956,0.103300,-0.327829,0.376647,0.348642,-0.347634,-0.466886,0.114636,0.497506,-0.257894,0.285252,0.463816,-0.200516,-0.065424,-0.540368,-0.033100,-0.016665,-0.298505,-0.284576,0.000653,-0.190931,-0.292173,-0.274118,0.569454,-0.001327,-0.043679,0.686864,0.316291,0.402264,-0.171351,0.222953,0.103281,0.172444,-0.098452,0.326688,-0.044896,-0.153941,-0.379058,-0.197646,-0.242775,-0.044623,0.272463,0.434963,0.906930,-0.196019,-0.250152,-0.221609,0.219334,0.099002,0.000978,-0.024986,0.460207,0.043097,0.222683,0.121890,-0.114368,-0.001251,0.288209,0.130736,-0.273330,0.199460,0.231381,0.174725,-0.329822,0.342597,0.037174,-0.298014,0.307091,-0.216493,-0.110312,0.171050,0.478997,-0.079028,-0.241456,0.167886,0.027833,0.207625,0.560883,0.179789,-0.201871,0.233846,-0.373528,-0.251556,-0.280444,-0.182982,-0.279234,-0.004739,0.161022,-0.080635,0.069791,0.257747,-0.557139,-0.397862,-0.036921,0.189889,0.112747,-0.161283,0.007333,-0.535840,0.043187,-0.540064,-0.218674,0.143494,0.275204,-0.142329,0.845530,-0.881273,0.003486,0.327863,0.244290,-0.329078,0.164010,0.034468,0.008586,-0.218458,-0.235255,0.049908,0.060370,0.218051,0.098011,0.479460,-0.275064,-0.082117,-0.232417,0.317448', '3811356', '25922902', '1826173', '10174444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25845392', '长津湖', '剧情', '电影以抗美援朝战争第二次战役中的长津湖战役为背景，讲述了一段波澜壮阔的历史：71年前，中国人民志愿军赴朝作战，在极寒严酷环境下，东线作战部队凭着钢铁意志和英勇无畏的战斗精神一路追击，奋勇杀敌，扭转了战场态势，打出了军威国威。', '吴京', '陈凯歌', 7.4, 693941, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2681329386.jpg', 2.1, 8.7, 32.2, 32.9, 24, '-0.454698,0.142551,-0.592278,1.089709,0.633407,-0.001530,0.087074,0.009802,-0.241060,0.074658,0.649946,0.532445,0.465590,-0.644378,0.379547,-0.819153,-0.225734,-0.969346,-0.419607,0.822895,-0.293728,-0.220792,-0.688564,-0.048280,0.298980,-0.847084,0.992796,0.458483,-0.716089,0.697074,-0.487946,0.075733,0.087750,0.454697,0.195810,-0.183356,-0.425721,-0.129747,-0.863627,0.212290,-0.249198,-0.394115,-0.476719,-0.016261,-0.139345,0.019748,1.124966,-0.665865,0.096646,-0.112308,0.360482,-0.180507,-0.104521,0.062806,0.458749,0.269583,-0.190042,0.189102,0.368609,0.204518,-0.649104,-0.305298,-0.554626,-0.372759,-0.452103,-0.013522,-0.687532,0.586453,-0.041100,0.198192,0.248033,-0.199916,-0.151086,0.987626,0.520303,0.273395,-0.561147,-0.010193,-0.283817,0.177634,0.831759,-0.013891,-0.261817,0.088427,-0.317827,-0.252250,-0.176315,-0.599914,-0.074984,0.061401,0.087474,-0.315458,0.070902,0.511170,-0.810157,0.237080,-0.253868,-0.425955,-0.017951,-0.099550,-0.293465,-0.894212,-0.417226,-0.279759,-0.131024,0.291576,-0.142853,0.303369,0.709232,-0.613825,-0.538181,0.529861,0.084493,-0.241552,0.538199,0.243867,-0.059983,0.125263,0.761794,0.343767,-0.456775,0.541189,0.055242,0.398538,-0.289776,0.089902,-0.198089,0.845260', '35058077', '1424551', '1780122', '35155748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25845397', '飞不起来的童年', '剧情', '查拉（阿曼多·巴尔德斯·弗莱雷 Armando Valdes Freire 饰）出生于一个位于社会最底层的贫穷家庭之中，父亲在很早的时候就离开了他，母亲深受毒品之苦，根本无暇照顾和关心查拉。必须自食其力的查理以训练战犬维生，这导致他的性格非常的冷漠而且暴力。学校里，所有的人都认为查拉是一个无可救药的孩子，只有他的班主任卡梅拉（阿丽娜·罗德里格斯 Alina Rodríguez 饰）不这么想，她觉得查拉只不过是一个极度渴望爱的善良男孩而已。卡梅拉生病了，需要住院，新老师接手了她的班级。新来的老师并不是一个耐心的人，他误解了查拉的种种举动，并且最终将他送进了少管所。©豆瓣', '米利尔·赛加斯', '埃内斯托·达拉纳斯', 8.4, 9814, 'tt3595966', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2337193991.jpg', 0.2, 0.8, 14, 51.5, 33.6, '0.510809,-0.078537,-0.616712,0.648027,-0.681064,-0.344443,0.764214,0.093131,-0.514960,-0.425068,0.086998,0.821029,0.229461,0.397399,0.204057,0.185357,-0.240146,-0.428801,-0.037706,-0.192848,-0.273275,-0.570660,-0.101951,-0.118753,-0.081347,-0.384415,0.457941,-0.173010,-0.080146,0.222400,-0.006065,0.373254,0.368435,0.568564,0.039496,0.023956,-0.044342,-0.215772,0.124142,0.106380,0.103017,0.022437,-0.094885,0.376817,0.243749,0.523635,0.432660,-0.218957,-0.129460,-0.179813,0.417102,-0.297765,-0.108374,0.163956,0.138628,-0.169291,0.361497,0.098727,-0.355361,0.127359,0.132701,-0.063755,-0.889079,-0.093473,0.044619,0.080965,-0.789678,0.698969,-0.136001,-0.249244,0.110128,-0.489096,0.048698,0.249353,0.009142,0.411018,-0.190799,-0.155776,-0.546775,-0.032761,0.601979,-0.237795,-0.306875,0.425560,-0.497754,-0.435608,0.205814,-0.338948,-0.702865,0.121249,0.065719,-0.076339,-0.493946,0.089900,-0.441201,0.016496,-0.229294,-0.115227,-0.098060,-0.491850,-0.213774,-0.182210,-0.072082,-0.544389,-0.382080,-0.230507,-0.093900,-0.323729,0.896452,-0.952742,0.130315,0.679640,0.259620,-0.538240,0.618215,0.330823,0.040735,-0.080788,-0.007324,0.290376,0.158922,0.288033,-0.010469,0.508464,0.227233,-0.385351,-0.168662,0.582653', '1877596', '1303112', '1783461', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25845586', '赛尔号大电影4：圣魔之战', '剧情', '邪恶的宇宙海盗迪恩（胡谦 配音）得到了能够吸收力量的魔石，妄图凭此统治宇宙，天蛇星少主缪斯（李晔 配音）的能量被魔石吸收，性命岌岌可危，为了挽救缪斯，耶里梅斯出发寻找正气之铁，希望能够将它打造成煞魔圣剑，将迪恩彻底打败。镜头来到棱石星，迪恩的魔爪伸向了这片宁静的土地，为了对抗这股强大的邪恶力量，战神联盟聚集到了一起，然而，迪恩的实力实在过于可怕，雷伊（孙晔 配音）、卡修斯（刘北辰 配音）和布莱克（吴磊 配音）等人接二连三的被吸入魔石之中。最终，盖亚（蒋可 配音）和赛小息（罗玉婷 配音）等人顺利的夺回了魔石，却也引来了迪恩派出的杀手。©豆瓣', '杨鸥', '王章俊', 5.8, 16290, 'tt6105888', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2189861941.jpg', 16, 22.4, 32.1, 14.9, 14.5, '-0.081394,0.374379,-0.631034,0.584318,-0.232851,-0.127529,0.558130,0.187265,-0.291514,0.014331,0.153695,0.287429,-0.078989,-0.221900,0.319361,-0.097911,-0.033886,-0.328842,0.048501,0.095439,-0.284027,-0.159425,-0.456643,-0.016137,-0.138465,-0.737473,0.759273,0.318470,-0.141037,0.134678,-0.081383,0.213412,-0.133358,0.396239,0.074437,-0.003478,0.052764,-0.244309,-0.184069,0.604527,-0.163543,-0.089583,0.199864,0.476798,-0.215450,0.075980,0.573281,-0.362347,0.492946,-0.298029,0.272873,-0.509888,-0.160867,0.062581,0.184960,0.194739,-0.041777,-0.194635,-0.216834,0.056721,0.127873,-0.205660,-1.092961,-0.083020,-0.152911,0.053235,-0.060296,0.198355,0.133130,0.004523,0.050347,-0.236452,0.276642,0.143149,0.365056,0.219804,-0.294709,-0.055971,-0.299005,-0.103352,0.461785,-0.619454,-0.401817,0.083174,-0.079647,-0.464734,-0.301054,-0.348286,-0.060662,-0.117405,0.776919,0.505110,0.245988,0.376886,-0.886370,-0.224775,-0.180245,-0.309807,-0.019081,-0.363901,0.062187,-0.518416,-0.487958,0.092435,0.115887,0.128850,0.231842,-0.268406,0.738407,-0.549340,0.008966,0.741376,0.657672,-0.265762,0.264466,-0.324951,0.127507,-0.097745,-0.034499,0.216409,0.251793,0.723162,0.518292,0.317735,0.066891,0.051389,-0.221889,0.414786', '2051813', '7155241', '26667010', '3001114');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25845910', '小门神', '喜剧', '故事发生在当代的人间江南小镇和神界。门神神荼和郁垒是两兄弟。因为近年人间不再关注神仙，神界经济萧条，门神、土地爷、八仙等等小神们面临下岗失业的危险。门神郁垒决定去人间，做一番惊天动地的事情，证明门神的价值。郁垒和神荼先后来到人间，遇到了小镇上的单亲母女小英和雨儿，之后发生了一系列意想不到的有趣惊险故事……', '高晓松', '王微', 6.9, 47205, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2299783299.jpg', 1.8, 8.7, 43, 34.7, 11.8, '0.564183,-0.163736,-0.827675,0.102409,0.307469,0.245625,0.780597,0.094749,-0.761715,0.067341,0.166613,0.781173,-0.429857,0.113217,0.336289,-0.195634,-0.280174,-0.726141,0.147729,-0.254354,-0.164187,-0.302534,-0.201846,-0.160874,-0.174609,-0.362798,0.108700,0.189268,0.141836,0.326620,-0.064468,0.030341,-0.668333,0.114561,-0.226146,0.351275,-0.064091,0.774007,-0.705609,0.060580,0.035733,0.132605,-0.211693,0.094878,-0.008188,-0.095044,0.070743,-0.312296,-0.610421,-0.077976,0.273223,-0.401446,-0.079079,-0.078497,0.547815,-0.020707,0.220729,0.458491,0.067923,-0.390781,-0.137068,-0.178540,-0.303463,0.213903,0.351047,0.295500,-0.280384,0.596785,0.175994,-0.062009,0.181421,-0.463610,0.768432,0.701162,0.899410,0.570619,-0.068106,-0.139112,-0.540295,0.380798,0.965675,0.147427,-0.083010,0.235156,0.222635,-0.280138,-0.289117,-0.427512,-0.228159,0.500170,0.124831,-0.036917,-0.300130,0.469109,-0.475169,-0.096249,-0.204401,-0.131340,-0.139118,-0.247069,-0.067060,-0.587650,-0.183034,-0.544216,-0.043263,0.158053,0.406893,-0.150569,0.783772,-0.493607,0.235303,0.388253,0.475483,-0.329710,0.823517,-0.252553,0.338031,-0.418421,0.183925,-0.293381,-0.112855,0.589725,-0.136214,0.005276,-0.001891,0.155252,-0.150517,-0.073497', '25721544', '30162520', '26320029', '26321184');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25846857', '公牛历险记', '喜剧', '影片根据曼罗·里夫1936年经典童书《爱花的牛》改编，讲述西班牙一头名为“费迪南德”（约翰·塞纳 John Cena 配音）的公牛的爆笑历险故事。费迪南德体型健壮，但却心地善良性格温和，它被误认为是危险的野兽，从而被捕送往他乡被逼做一只“斗牛”。为回到家人身边，他不得不踏上了一场终极冒险旅程……', '约翰·塞纳', '卡洛斯·沙尔丹哈', 7.2, 51539, 'tt3411444', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2510825300.jpg', 0.4, 3.8, 43.2, 39.6, 12.9, '0.002186,-0.163437,-0.226812,0.521746,0.143833,-0.259745,0.548279,-0.117784,-0.379095,-0.134821,0.191373,0.639513,-0.054542,-0.090298,0.218856,0.108389,-0.062028,-0.366138,0.050252,0.325511,0.188906,-0.170200,-0.259507,-0.035662,0.081529,-0.390461,0.610902,-0.221090,-0.389051,0.611285,0.288670,0.545463,0.012395,-0.017552,-0.168233,0.072990,0.226004,-0.117750,0.024160,0.121194,-0.165652,-0.131528,-0.194746,-0.058849,-0.182375,0.192864,0.661528,-0.373015,-0.188099,-0.293624,0.559164,-0.425796,0.106663,0.179441,0.321540,0.165371,0.306519,0.200168,-0.057441,0.156049,-0.138403,-0.358729,-0.634940,-0.037570,-0.032141,0.094306,-0.530984,0.107504,-0.148902,0.430488,0.172387,-0.241151,0.018577,-0.175176,0.694162,0.421163,0.230232,0.308719,-0.042571,0.068142,0.900944,-0.045999,-0.370778,0.139428,-0.202324,-0.375260,0.235667,-0.436932,-0.417349,0.250006,0.455253,-0.030815,-0.299697,0.289868,-0.575762,-0.101666,-0.499882,-0.216358,-0.283908,-0.176298,-0.161616,-0.260886,-0.028148,-0.330285,0.089599,-0.280449,0.133683,-0.268194,0.651560,-0.168425,0.321692,0.694350,-0.134697,-0.293867,0.373790,-0.049217,0.198477,-0.158128,0.303548,0.502648,0.037142,-0.053310,-0.012310,0.302359,0.015511,-0.337586,-0.426828,0.656119', '25828589', '1792917', '30162520', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25846858', '破碎人生', '剧情', '《爆破》由布莱恩·赛普（Bryan Sipe）编剧，故事讲述杰克·吉伦哈尔（Jake Gyllenhaal）饰演的一位投资银行家在妻子遭遇意外身亡后，生活变得支离破碎，直到遇到了娜奥米·沃茨（Naomi Watts）饰演的单亲妈妈，人生才有了转机。据悉，娜奥米·沃茨饰演的这位单亲妈妈是一个既和老板约会、又吸大麻的客户服务代表，她的公司专门生产自动贩卖机。她和男主角的相遇也充满戏剧性，男主角的钱被自动贩卖机吞了，她去处理投诉时了解到了男主角的不幸遭遇，继而与他有了进一步的接触。', '杰克·吉伦哈尔', '让-马克·瓦雷', 7.6, 33780, 'tt1172049', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2359593888.jpg', 0.6, 3.3, 31.5, 45, 19.7, '0.202262,-0.249226,-0.451865,0.349665,0.004902,-0.409934,0.854732,0.400128,-0.037392,-0.242414,0.275118,1.116950,-0.409692,0.159725,0.543594,-0.015480,-0.326792,-0.454483,0.113486,-0.128709,-0.152645,-0.373144,-0.122084,-0.165294,0.259367,-0.511651,0.444029,-0.275165,-0.425104,0.368909,0.311360,0.399447,-0.009640,0.516232,0.108501,0.469443,0.346237,0.059142,-0.155043,0.251313,0.185609,-0.194740,0.061089,-0.058681,0.184460,0.441205,0.500208,0.004163,-0.179925,-0.014340,0.639624,-0.192613,0.111444,-0.065089,0.183229,0.057294,0.063976,0.112294,-0.509306,-0.068063,0.215174,-0.150099,-0.800969,-0.149489,0.159830,0.089011,-0.577192,0.243909,-0.031041,-0.040050,0.199968,-0.168934,0.233813,0.395295,0.243677,0.172335,-0.089962,0.088240,-0.406182,0.339208,0.653286,-0.128476,-0.214909,0.560428,-0.051043,-0.414582,-0.090081,0.109747,-0.715455,0.193776,0.415801,0.043738,-0.319499,0.261241,-0.570099,-0.343579,-0.390989,-0.287575,0.195628,-0.236292,-0.202433,-0.739757,-0.303201,-0.234348,-0.074329,-0.180832,-0.062261,-0.389181,0.648271,-0.704170,-0.013379,0.670911,0.150500,-0.581938,0.603795,-0.055787,0.072030,-0.278775,0.262969,0.354787,-0.000743,0.164342,0.171564,0.445262,0.069226,0.044640,-0.206067,0.347678', '34890458', '1829654', '30162520', '1361252');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25847558', '邻家大贱谍', '剧情', '杰夫（扎克·加利凡纳基斯 Zach Galifianakis 饰）与凯伦（艾拉·菲舍尔 Isla Fisher 饰）是一对住在城郊的夫妇，而他们发现新搬来的邻居并不简单。这对新搬来的夫妇蒂姆（乔恩·哈姆 Jon Hamm 饰）与娜塔莉（盖尔· 加朵 Gal Gadot 饰）过得可谓是光彩夺目，精致无比。而当他们发现琼斯夫妇实际上是秘密特工后，事情就变得更加复杂了。', '扎克·加利凡纳基斯', '格雷格·莫托拉', 6.1, 30632, 'tt2387499', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2394353738.jpg', 1.7, 15.4, 62.6, 17.8, 2.5, '0.313072,-0.618439,-0.552804,0.407702,-0.136383,-0.334271,0.984812,0.259025,-0.742157,-0.276462,-0.096392,0.825314,-0.235197,-0.002934,0.327923,0.473937,-0.759821,-0.297402,0.151496,-0.461932,0.029428,-0.725781,-0.348967,-0.375411,0.344708,-0.390679,0.099031,-0.315092,0.075270,0.785765,0.325472,0.460678,-0.086412,0.419212,0.149831,0.169696,0.151031,0.041603,-0.234075,-0.001719,-0.076049,0.202081,-0.317244,0.338587,0.304775,0.431004,0.368371,-0.325822,-0.147482,0.177066,-0.001072,-0.087224,-0.053920,0.281147,0.335806,-0.286509,0.200067,0.259698,-0.395654,-0.013815,0.236284,-0.293080,-0.678809,0.525963,0.192162,0.304696,-0.674290,0.575064,-0.341314,-0.423018,0.029586,-0.627415,0.288096,0.471552,0.045213,0.253740,0.336022,-0.337780,-0.534759,-0.137555,0.405494,0.029914,-0.086918,0.510545,-0.249080,-0.464172,-0.039074,0.080520,-0.244777,-0.067140,0.319295,0.078018,0.364701,0.181786,-0.673549,0.005295,-0.590321,-0.159097,0.022812,-0.412840,0.079610,-0.831984,-0.290315,-0.822214,-0.399827,-0.082190,-0.064954,-0.028200,0.374446,-0.849670,0.188202,0.068499,0.115821,-0.130768,0.445172,-0.087250,0.212784,-0.370374,-0.360362,-0.033334,0.157752,0.208696,0.273766,0.357917,0.176711,-0.319355,-0.094461,0.402952', '1297239', '24639908', '1301686', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25849006', '陆垚知马俐', '喜剧', '陆垚（包贝尔 饰）在上大学时重逢幼儿园同学马俐（宋佳 饰），虽然彼此心存好感，但由于陆垚有严重的“表白障碍症”，只能眼巴巴看着自己的女神马俐与别人谈恋爱。而自此之后很多年，陆垚只能以朋友的名义爱着马俐，也与她开始了一段“友情不甘、恋人不敢”的长跑。', '包贝尔', '文章', 5.6, 103734, 'tt5562066', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2361036748.jpg', 11.1, 26.5, 41.9, 14.2, 6.2, '0.311543,0.049820,-0.666119,1.049959,0.082354,-0.438000,0.710131,-0.026962,-0.597451,-0.311838,-0.097298,0.692250,-0.195017,0.945165,0.198154,-0.410842,-0.386263,-0.804744,0.472326,-0.068457,-0.492179,-0.705309,-0.082323,-0.236490,-0.552949,-0.049383,0.746017,0.133464,-0.193198,0.506917,0.589555,0.198319,0.009547,0.520363,-0.015183,-0.010524,-0.050760,0.699132,-0.467201,-0.070038,0.509813,-0.092028,-0.329003,0.122803,0.190976,0.336855,0.655564,0.101654,-0.128615,0.075052,0.518183,-0.303429,0.266228,0.356697,0.374032,0.021330,0.525260,-0.138132,-0.018638,0.120754,0.106480,-0.007207,-0.106662,-0.096071,0.120864,-0.289049,-0.693771,0.843529,-0.229173,0.029645,0.242610,-0.173994,-0.079265,0.563978,0.411056,0.363126,-0.568410,-0.160941,-0.221781,0.224696,0.494048,0.453894,-0.247294,0.252343,-0.164376,-0.669486,-0.359330,0.009939,-0.733788,0.028783,0.277682,0.236830,-0.252680,0.536784,-0.424206,-0.103579,0.230977,0.246833,0.155611,-0.546330,0.291530,-0.447835,0.078409,-0.948171,-0.066037,0.458154,0.255259,-0.476553,0.723762,-1.042610,0.094972,-0.118389,0.397780,-0.696603,0.906488,0.451072,-0.145161,-0.472479,0.045802,0.795828,-0.420904,0.039427,0.699779,0.391450,-0.112060,0.143455,-0.073236,0.575513', '1306544', '26354526', '35376457', '25828521');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25849049', '超人总动员2', '喜剧', '在一次挖地超人制造的大混乱中，超人家庭大力神巴鲍伯（格雷格·T·尼尔森 Craig T. Nelson配音）和弹力女超人巴荷莉（霍利·亨特 Holly Hunter 配音）和他们的子女巴小倩（莎拉·沃威尔 Sarah Vowell 配音）、巴小飞（赫克·米尔纳 Huck Milner 配音）使出浑身解数，然而不仅不能抓住狡猾的敌人，而且还因为对城市破坏太大而导致失去了政府的支持。此后不久，电信集团大亨温斯顿·狄弗（鲍勃·奥登科克 Bob Odenkirk 配音）通过酷冰侠鲁休斯（塞缪尔·杰克逊 Samuel L. Jackson 配音）找到鲍伯一家，希望将该公司的前沿技术应用到超人身上，更好地维护世界和平。可是狄弗只希望雇佣荷莉，偏偏荷莉大展雄风，成为了所有超人族群的偶像，这可令担任奶爸的鲍伯心有不甘。而就在此时，神秘对手悄然出现，似乎正试图摧毁荷莉他们所建立的新和平……', '格雷格·T·尼尔森', '布拉德·伯德', 7.8, 253343, 'tt3606756', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522880251.jpg', 0.1, 1.9, 27.2, 48.9, 21.9, '0.118541,0.107237,-0.639142,0.478773,-0.072220,-0.387315,0.299796,0.075382,-0.237733,-0.285637,0.079604,0.649329,-0.170881,-0.010777,0.167199,-0.015475,-0.258524,-0.669988,0.052283,0.110290,-0.177725,-0.550672,-0.495693,-0.489172,-0.053154,-0.461625,0.695929,0.042787,-0.424022,0.179392,0.160641,0.335902,0.139413,0.175652,0.070867,0.059045,0.240300,-0.211489,-0.369050,0.430125,0.064719,0.066126,-0.052801,0.204092,0.091841,0.221280,0.302685,-0.330799,0.047266,-0.063580,0.224113,-0.286705,0.037945,-0.135412,0.048533,-0.236392,0.109770,0.079368,-0.143809,-0.106396,0.056020,-0.176934,-0.893229,0.023090,0.043353,0.002276,-0.368742,0.125214,-0.160003,-0.005468,0.123827,-0.344494,-0.052897,0.354592,0.550594,0.206759,-0.204666,0.448801,-0.399172,-0.013021,0.531967,-0.087238,-0.490293,0.115636,-0.096217,-0.178630,-0.197486,-0.395226,-0.432280,-0.212698,0.305935,0.128807,0.131056,0.384347,-0.512208,-0.144838,-0.369704,-0.153088,-0.001073,-0.352127,0.114708,-0.788049,-0.070060,-0.021274,0.029874,-0.011461,0.140978,-0.416426,0.745100,-0.869257,0.227033,0.508861,0.371991,-0.153362,0.450903,-0.128978,0.323340,-0.341170,-0.252575,0.229988,0.367972,0.136292,0.229127,0.050318,-0.093722,-0.223188,-0.308671,0.458630',