INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25849475', '新娘大作战', '喜剧', '马丽（倪妮 饰）和何静（杨颖 饰）是从小玩到大的闺中密友，彼此之间感情十分要好。曾经，在一间豪华的酒店之中，两个姑娘目睹了一场浪漫的婚礼，她们就此立下誓言，等到结婚的那一天，一定要重回此地举行仪式。时光荏苒，马丽和何静都找到了如意郎君，可两人的男友似乎对结婚这件事情并不那么热衷。经过种种波折，两对情侣终于修成了正果准备步入婚姻的殿堂，两个女孩的梦想眼看就要完成，在这个节骨眼上，她们得知在未来三年内，酒店仅剩下一个档期，这也就意味着，若想要按时完婚，那么她们其中一人的梦想注定将要破灭。危机之下，马丽和何静反目成仇，开始了一场撕逼大战。©豆瓣', '杨颖', '陈国辉', 4.2, 87524, 'tt3833460', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2262229212.jpg', 31.2, 37.4, 23.6, 4.4, 3.4, '0.214980,0.175447,-0.766090,0.222563,0.079571,-0.352071,0.678211,-0.114105,-0.242423,-0.184839,0.078345,0.644883,-0.448179,0.446528,0.535252,-0.228000,-0.189744,-0.793886,0.176008,-0.274612,-0.196441,-0.328042,-0.003846,0.099098,-0.116998,0.010522,0.804760,0.184161,0.321838,0.451898,0.425211,-0.257370,-0.197717,0.321377,-0.214989,0.002585,0.128974,0.425046,-0.638041,0.187434,-0.040528,0.021003,0.109177,0.119197,-0.024561,0.063888,0.394770,-0.196813,-0.226318,-0.077846,0.333227,-0.106810,-0.284474,0.400949,0.342441,-0.168152,0.514867,0.534674,-0.313550,-0.106048,-0.003138,-0.252278,-0.421631,0.070792,0.270723,-0.114549,-0.469575,0.588223,0.250345,-0.091637,0.012700,-0.118099,0.134808,0.796297,0.471362,0.372441,-0.299692,0.004134,-0.643994,0.028272,0.991109,-0.149929,0.196429,0.562733,0.357357,-0.361032,-0.146466,0.038980,-0.500750,0.251904,0.210018,0.066895,-0.183976,0.096029,-0.553795,-0.016307,-0.344218,0.084219,0.211392,-0.635442,0.160609,-0.523300,-0.182337,-0.412020,-0.521395,0.412118,0.231222,-0.325962,0.540355,-0.761217,0.181191,0.104506,0.381990,-0.604932,0.663326,0.551622,0.668361,-0.316698,0.192290,0.044282,-0.468612,0.144822,-0.062463,0.355612,0.116254,0.125286,-0.482470,0.441221', '25721544', '25978126', '4145476', '26687241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25849480', '赛车总动员3：极速挑战', '喜剧', '征战沙场多年，闪电麦昆（欧文·威尔逊 Owen Wilson 配音）早已成为经验丰富的老将。对于现在的他来说，比赛更像与老友们的聚会，大家共同享受狂奔带来的乐趣。然而这和谐的一幕很快被残酷的现实打破，以风暴杰克逊（艾米·汉莫 Armie Hammer 配音）为代表的次世代高科技赛车相继步入赛场，他们凭借更加优良的性能与高科技的组装改造将老一代赛车一一淘汰，甚至包括王者麦昆。四个月后，伤愈的麦昆决定复出，而他也被合作多年的赞助商转到了斯特林（内森·菲利安 Nathan Fillion 配音）麾下。接受从内到外的全新改造后，麦昆在教练科鲁兹·拉米雷斯（克里斯黛拉·阿朗索 Cristela Alonzo 配音）的监督下展开训练。然而他面临着一项严峻的考验，如果他不能在接下来的比赛中取得胜利，那么他必须从此退休。希望渺茫，不服输的麦昆能否重新取得胜利的荣光……', '欧文·威尔逊', '布莱恩·菲', 7, 51237, 'tt3606752', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2492869476.jpg', 0.9, 5.5, 48.9, 33.8, 10.9, '0.174109,0.124398,-0.638837,0.591860,-0.193505,-0.493117,0.429437,-0.079662,-0.366156,-0.190254,0.378214,0.774368,-0.271921,0.043059,0.330720,-0.361634,-0.333739,-0.753813,-0.196374,-0.056424,-0.348387,-0.555164,-0.229877,-0.230728,0.092026,-0.336870,0.899487,0.042054,-0.136716,0.441352,0.276735,0.159200,0.196971,0.456946,0.077858,-0.158018,0.122878,0.036031,-0.480833,0.306962,-0.030421,-0.033200,-0.215174,0.046986,0.134613,0.150706,0.521201,-0.535843,0.008827,0.025926,0.417004,-0.291904,-0.002410,0.094268,-0.010877,0.291676,-0.056318,0.348096,-0.126397,0.226929,-0.306790,-0.235323,-0.935776,-0.023676,-0.114222,-0.047337,-0.605662,0.645819,0.045999,0.019778,0.104517,-0.148324,0.050962,0.492046,0.461190,0.323735,-0.205636,0.210908,-0.327619,0.204836,0.814150,-0.063006,-0.617847,0.144127,-0.054438,-0.440734,0.002702,-0.535786,-0.497577,-0.073701,0.492596,0.186614,0.122489,0.288090,-0.483695,0.165057,-0.257218,-0.520724,-0.176044,-0.309181,0.176657,-0.896538,-0.140614,-0.340367,-0.220020,0.010139,0.012332,-0.526992,0.918418,-0.867069,0.107913,0.169909,0.080303,-0.368684,0.381677,0.007330,0.427154,-0.261477,-0.270571,0.347350,0.036763,0.314864,0.113772,0.437358,-0.060817,-0.078852,-0.452785,0.712486', '27602116', 