INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25849599', '全城通缉', '剧情', '在某座城市的破败角落，精英警员唐越（刘烨 饰）孤独住在一个即将拆除的老楼里。他等待着失踪十年的女友徐雅（吴佩柔 饰）归来，为了找到徐雅他辞去工作，最终却未得到任何令人为之一振的消息。“找到我，我就嫁给你”，这是徐雅失踪前留给唐越的信息，仿佛一条永远也解不开的谜语，唐越被深深困在其中。电视上，某外资银行中国区副总裁邵云峰（赵文卓 饰）和白氏集团的负责人白晓芸谈笑风生，而邵云峰则与唐越有着千丝万缕的关系，十年前被唐越所射杀的女劫持者（秋瓷炫 饰）更成为他脑海中挥之不去的噩梦。不久后，白晓芸被人残忍杀害，她的妹妹白晓若（娜扎 饰）则找到唐越请求他追查凶手，并承诺作为回报帮他找到徐雅。谁知唐越竟见到了当初被他枪杀的女人！扑朔迷离，全城通缉……©豆瓣', '刘烨', '汪涛', 4.6, 15116, 'tt4514606', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2208596562.jpg', 23.6, 36.7, 30.1, 6, 3.7, '-0.091157,0.055093,-0.640222,0.484335,0.043067,-0.170789,0.703730,-0.114652,-0.548763,-0.397838,0.103064,0.601275,-0.066067,0.452756,0.153534,0.043295,-0.261094,-0.671094,-0.080895,-0.320261,-0.179406,-0.364890,-0.291743,-0.076543,0.091082,0.022859,0.779295,0.120856,-0.094871,0.232484,0.272143,0.299315,-0.271809,0.592556,-0.139180,0.021363,0.088265,-0.049131,-0.179981,0.099718,-0.043865,-0.180337,0.079181,0.199043,-0.064918,0.289588,0.365904,-0.256460,-0.170040,-0.100034,0.226947,-0.270611,-0.007295,-0.054830,0.193062,0.069400,0.377922,0.416422,-0.463397,-0.115410,0.247099,0.012904,-0.594812,0.137927,0.191024,0.201829,-0.421454,0.412685,-0.205353,0.171662,0.145935,-0.361013,0.359146,0.230899,0.241880,0.199041,-0.273816,0.231884,-0.502088,0.227985,0.500016,-0.075686,-0.018640,0.107422,0.154245,-0.273397,0.088405,-0.014845,-0.232237,0.143224,0.268511,0.236491,-0.125381,-0.000606,-0.245717,-0.168519,-0.228789,0.031382,0.168059,-0.439024,-0.274252,-0.575436,-0.043811,0.140389,-0.369948,0.180688,-0.014258,-0.372901,0.287311,-0.623915,0.247035,0.270651,0.351215,-0.513680,0.547716,0.005087,0.183734,-0.211935,-0.153785,0.411297,0.279161,0.416024,0.133385,-0.044025,-0.185009,-0.120536,-0.385586,0.343645', '1301022', '11615927', '25828589', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25850122', '封神传奇', '剧情', '三千年前，商末，昏君纣王（梁家辉 饰）受妖妃妲己（范冰冰 饰）蛊惑，联手申公豹（古天乐 饰），试图召唤黑暗力量降生灭世黑龙，一时间妖孽横行，民不聊生……为阻止昏君灭世，姜子牙（李连杰 饰）命雷震子（向佐 饰）、哪吒（文章 饰）与杨戬（黄晓明 饰）联手寻找光明之剑斩妖除魔，并协助武王引领西岐大军攻打朝歌。不料妲己施法令姜子牙中了逆生咒，朝歌大战迫在眉睫，黑龙降世已成定局，天下再度陷入危机……', '李连杰', '许安', 2.9, 60951, 'tt5481184', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2366372816.jpg', 70.5, 18, 7.7, 1.7, 2.2, '-0.466440,0.354902,-0.335958,0.286040,0.641439,0.269899,-0.053029,0.475579,-0.189563,-0.264280,0.384295,0.152176,-0.100852,-0.334272,-0.024293,-0.076400,-0.001870,-0.528992,0.044500,0.510073,0.399671,0.281901,-0.406018,0.206227,-0.362724,-0.588787,0.717842,0.143880,0.127026,0.267857,0.366246,0.328248,-0.534429,0.215973,0.134890,-0.047725,-0.436615,-0.049294,-0.295134,0.288268,-0.525401,-0.556763,-0.278956,0.375914,-0.605600,0.031120,0.213716,-0.757433,0.544230,-0.686445,0.272788,-0.188308,-0.354184,0.250668,0.125388,0.112578,0.049250,0.259893,0.053960,0.235785,0.111769,-0.285004,-0.471230,0.153847,-0.113210,0.067393,0.252918,-0.069508,0.103002,0.418663,0.201713,0.110934,0.048731,0.251078,0.552570,0.059372,-0.103606,-0.171030,-0.141854,0.121104,0.249897,-0.291506,0.117941,-0.146141,0.560336,-0.250821,-0.245467,-0.186035,-0.014024,0.090631,0.278602,0.022646,0.401856,0.698133,-0.557373,-0.521901,-0.576601,0.590026,-0.189709,0.341444,0.150615,-0.360043,-0.033164,0.256541,-0.121734,-0.151565,0.511752,0.358826,0.283510,-0.360665,0.075479,0.086436,0.417914,-0.444492,0.276127,0.012491,0.246794,-0.085697,0.045887,0.415633,0.030177,0.400880,0.112414,-0.402931,0.126387,-0.014511,-0.247216,-0.050670', '1303917', '27667334', '30201138', '1294564');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25850443', '史蒂夫·乔布斯', '剧情', '影片将取材于沃特·艾萨克森撰写的乔布斯生前唯一授权的传记，本片将不同于传统传记电影，由三段故事组成。索尔金的剧本会聚焦乔布斯生前三件关键性产品的发布时刻——1984年第一台Mac电脑的问世、乔布斯离开苹果后创立的NeXT电脑公司和1998年苹果首次推出的iMac。', '迈克尔·法斯宾德', '丹尼·博伊尔', 7.2, 48739, 'tt2080374', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264942503.jpg', 0.8, 4.6, 39, 43.5, 12.2, '0.118744,0.022907,-0.442926,0.800899,0.468052,-0.277213,0.262601,0.090297,-0.356867,-0.493946,-0.050446,0.897620,-0.491871,0.182289,0.477068,-0.027002,-0.212416,-0.664877,-0.349750,-0.269794,-0.149305,-0.474051,-0.269881,-0.412230,-0.045579,-0.450477,0.785898,-0.135084,-0.350173,-0.038617,0.316431,0.364917,-0.076232,-0.137972,0.181693,-0.069027,-0.051661,-0.126348,-0.455752,0.531249,0.001759,-0.337308,0.124405,-0.002894,0.190627,0.156937,0.580652,-0.483714,0.127941,-0.013378,0.818376,0.056477,-0.260697,-0.389862,0.116511,0.649633,-0.068615,0.733217,-0.149661,0.063002,-0.013490,-0.645639,-0.956135,-0.428312,-0.058374,0.120524,-0.526407,0.451643,-0.546802,0.552873,-0.089439,-0.513491,0.318164,0.201030,0.735280,0.590003,0.337352,0.326807,-0.421159,0.833451,-0.132151,0.030155,-0.328678,0.335576,-0.062195,-0.403005,-0.370480,-0.227398,-0.339160,0.240770,0.644982,0.148864,0.083339,0.369359,-0.872316,-0.385610,-0.100567,-0.549829,0.670149,-0.236437,-0.130246,-0.811038,-0.050898,0.022519,-0.028800,-0.250551,0.104649,-0.487478,1.108643,-0.337434,0.390692,0.023112,-0.037477,-0.129220,0.688500,-0.317890,0.089104,-0.192135,0.249035,0.451830,0.300436,0.195527,-0.077663,0.020276,0.188978,-0.391590,-0.480865,0.628249', '27602116', '22265121', '3318306', '26647163');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25850715', '虐杀器官', '科幻', '《屠杀器官》的舞台将设定在赛拉耶佛核爆后的地球，此时部分落后国家爆发了一连串内战及民族冲突，在这血腥风暴之中，美国特殊情报部队「克拉维斯（クラヴィス）」发现了在阴影之下有一名叫「约翰?保罗（ジョン?ポール）」的美国人参与其中，约翰路过之处必定掀起腥风血雨，这让众人疯狂的 「屠杀器官」到底是什么？剧场版动画《屠杀器官》根据早逝的天才科幻小说作家伊藤计划的同名小说改编，由富士电视台的noitaminA节目企划，manglobe制作，将于2015年10月上映。', '中村悠一', '村濑修功', 7.3, 6962, 'tt3615160', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2396428546.jpg', 1.7, 5.7, 36.6, 39.6, 16.4, '-0.003935,-0.163845,-0.645735,0.391415,0.453826,0.108035,0.525091,-0.096865,-0.449456,-0.172686,0.410018,0.698631,-0.481256,-0.176539,0.306317,-0.315448,-0.305787,-0.659111,-0.485552,-0.280047,-0.342695,-0.431103,-0.323167,-0.353021,0.083372,-0.657497,0.837360,0.324545,-0.427166,0.106712,0.102714,0.355166,-0.348046,0.249826,0.317646,0.069504,0.110021,-0.160727,-0.389552,0.275377,-0.263632,-0.270167,-0.173288,0.201874,-0.173692,0.418872,0.813936,-0.463882,0.263366,-0.424554,0.770203,-0.196474,-0.127876,-0.066137,0.558147,0.079566,0.255973,0.302837,-0.075566,-0.085569,-0.043419,-0.105328,-0.690858,-0.090085,0.022180,0.306156,-0.469893,0.307218,-0.162571,0.029025,0.075677,0.099611,0.303769,0.567571,0.593620,0.226415,0.012544,0.228696,-0.154061,0.235039,0.323438,-0.128873,-0.396431,0.228215,-0.386745,-0.536475,-0.393250,-0.425153,-0.122962,-0.064715,0.335076,-0.108835,0.030671,0.494034,-0.694872,-0.013826,0.209787,-0.616897,0.154517,-0.073565,-0.389111,-0.886032,-0.301283,0.127906,-0.099718,-0.030450,0.269949,0.014666,0.935795,-0.575764,-0.058067,0.827713,0.201499,-0.307658,0.580938,-0.118833,-0.046820,-0.022522,-0.060076,0.138720,0.054594,0.379373,0.067361,0.410211,0.077200,-0.330017,-0.243609,0.484558', '1322847', '25863940', '3811356', '10439358');
