INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25851683', '新咒怨(美版)', '悬疑', '一名年轻的单亲妈妈兼警探莫顿发现郊区的一间房子遭到一个复仇怨灵所诅咒，这使进入房子内的人都会惨死。进入被诅咒的屋子中的她们必须设法从中救出自己和她的儿子，以免受怨灵的袭击。', '安德丽娅·赖斯伯勒', '尼古拉斯·佩谢', 4.8, 6988, 'tt3612126', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2571068461.jpg', 17.4, 40.5, 32.3, 6.4, 3.4, '0.583225,0.158277,-0.645800,0.449546,-0.284044,-0.272787,1.015791,0.000136,-0.436279,-0.488805,0.376532,0.911883,0.215020,0.501508,0.014474,0.235527,-0.073175,-0.555537,-0.101699,-0.342182,-0.554548,-0.122798,-0.395309,-0.204335,0.171856,-0.579589,0.363551,0.382164,-0.147561,0.126064,0.049487,0.568375,-0.265030,0.293399,-0.194959,0.215906,0.181359,-0.234338,0.063159,0.292361,-0.381637,-0.170411,0.023096,-0.044042,-0.145211,0.495816,0.889070,-0.170221,-0.181516,-0.278617,0.356989,-0.020763,-0.260359,0.674448,0.375011,-0.050224,0.342064,0.479944,-0.819051,0.336262,-0.072157,-0.041130,-0.878456,-0.120455,0.356004,-0.207292,-0.656899,0.165678,0.435309,-0.032448,0.170584,-0.063912,0.364868,0.166023,-0.018842,0.729147,-0.389529,0.025673,-0.685282,-0.365227,0.865245,-0.642874,0.129716,-0.128872,-0.022298,-0.259169,0.032056,-0.091866,-0.563072,-0.031091,0.577728,0.031324,-0.242276,-0.260149,-0.567805,-0.247377,-0.774158,-0.031768,-0.250087,-0.184736,-0.276656,-0.537138,0.052966,0.012983,-0.107883,0.380975,-0.217392,-0.202092,0.683956,-0.558188,0.247374,0.432138,0.627363,-0.802064,0.620195,0.206204,0.567056,-0.079063,-0.306967,0.275684,0.279518,0.540206,0.066067,0.308457,-0.253532,-0.133140,-0.286480,0.208943', '21619567', '1428054', '26678784', '1292217');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25851799', '爱情与友谊', '喜剧', '苏珊夫人（凯特·贝金赛尔 Kate Beckinsale 饰）在不久之前永远的失去了自己的丈夫，她从兰福德搬到了小叔子查尔斯（贾斯汀·爱德华斯 Justin Edwards 饰）所在的教堂山庄园，在那里修养身心。查尔斯的妻子凯瑟琳（艾玛·格林韦尔 Emma Greenwell 饰）并不喜欢苏珊夫人，在这个女人的眼里，她看到了太多的野心。可凯瑟琳的弟弟金纳德（沙维尔·塞缪尔 Xavier Samuel 饰）却被这个风情万种的女人迷得神魂颠倒。尽管苏珊夫人口口声声的表达着对于金纳德纯洁的爱意，但这一切对于她来说只不过是演戏而已，实际上，她早在兰福德时期便有了一个名叫曼纳林（罗克雷恩·O·梅瑞恩 Lochlainn O''Mearain 饰）的情人。©豆瓣', '凯特·贝金赛尔', '惠特·斯蒂尔曼', 6.8, 5264, 'tt3068194', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2334057610.jpg', 1.7, 8.4, 49, 32.2, 8.7, '0.629643,0.206604,-0.866757,0.675785,-0.340819,-0.545889,0.845168,0.122698,-0.516605,-0.480747,0.314551,0.637387,-0.224625,0.330788,0.119829,0.512241,-0.394118,-0.327373,-0.092446,-0.303101,-0.115904,-0.578866,-0.055222,-0.292665,-0.201320,-0.375987,0.461772,-0.185627,0.139699,0.158756,0.402654,0.217869,0.485014,0.560795,-0.037025,0.277097,0.234440,-0.170183,-0.096726,0.197140,0.232901,-0.020453,-0.030879,0.439617,0.000874,0.349012,0.411030,-0.605611,-0.015749,0.047730,0.333108,-0.345112,0.271902,0.226875,0.220788,-0.599777,0.060309,-0.045828,-0.267833,-0.253287,0.360169,-0.047499,-0.614556,-0.027405,0.180778,0.313852,-0.598036,0.471057,-0.349185,-0.070317,0.028640,-0.301864,0.142192,0.144962,-0.117393,0.254529,-0.168748,0.005022,-0.710282,0.003080,0.462173,0.362952,-0.214956,0.528190,-0.525967,-0.417166,-0.138235,-0.043039,-0.812583,0.043534,0.209681,-0.261600,-0.031009,0.319032,-0.401916,-0.274378,-0.231814,0.003856,0.063880,-0.632680,-0.059490,-0.359173,-0.218359,-0.844103,-0.387695,-0.191019,0.139193,-0.098903,0.668674,-0.924680,0.271393,0.679171,0.226795,-0.255977,0.640996,0.103146,0.056920,-0.262985,-0.257740,0.588486,-0.002593,-0.040661,0.221970,0.559654,0.103052,-0.156260,-0.400247,0.834734', '24756472', '3443074', '1292062', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25852263', '哪一天我们会飞', '剧情', '彭盛华（林海峰 饰）和余凤芝（杨千嬅 饰）结婚十余载，两人早已经是老夫老妻，生活亦失去了浪漫和激情。某日，余凤芝于无意之中发现了高中同窗苏博文（吴肇轩 饰）的博客，一首老歌让她开始回忆起了曾经的校园岁月。在学校里，彭盛华、余凤芝和苏博文是形影不离的好友，彭盛华生性活泼好动，是班级里的开心果，而苏博文则要内向的多，沉默老实的他喜欢摆弄机械发明，希望能够成为一名飞机师。最终，余凤芝选择了彭盛华，于是有了如今波澜不惊的生活。最近，她发现丈夫行踪诡异，似乎有出轨的迹象。美好的回忆和苍白的现实令余凤芝决定寻找苏博文的踪迹，最终，她发现了一个隐藏多年的秘密。©豆瓣', '杨千嬅', '黄修平', 7.2, 16202, 'tt5180856', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2271330538.jpg', 1, 6.1, 38.5, 41.4, 13, '0.515926,0.053035,-0.673039,0.636557,-0.105585,-0.342107,0.803335,-0.036151,-0.723623,-0.372710,-0.159110,0.558261,-0.114134,0.723800,0.122186,0.012833,-0.154631,-0.800967,0.104186,-0.210729,-0.300676,-0.653699,-0.314892,-0.070739,-0.018525,-0.179052,0.485950,0.197072,-0.030962,0.667964,0.354497,0.033050,-0.100176,0.484224,-0.208419,0.020215,0.109879,0.286904,-0.287010,-0.050357,0.250449,-0.117876,-0.143716,0.067708,0.077596,0.463273,0.684125,0.113449,-0.335960,0.307560,0.442436,-0.033166,-0.077018,-0.005570,0.449105,0.229099,0.234278,0.164629,-0.094979,0.081741,-0.240197,0.072922,-0.526013,0.111746,0.392160,-0.011646,-0.392759,0.527776,0.120499,-0.002493,0.004758,-0.405583,0.227232,0.335100,0.514126,0.407671,0.072869,0.281728,-0.173872,0.298039,0.362799,-0.172676,-0.517137,0.772750,-0.106321,-0.290534,-0.133536,-0.264171,-0.538207,0.081856,0.144190,0.199443,-0.242758,0.309218,-0.621151,0.073849,-0.016308,0.053900,0.276410,-0.336997,-0.337896,-0.315283,-0.501011,-0.614202,-0.293695,0.226631,-0.314920,-0.393242,0.825810,-0.951807,0.199175,0.273940,0.003851,-0.675460,0.724728,0.261391,-0.127113,-0.101533,0.445246,0.405367,-0.205731,0.116998,0.206615,0.204400,-0.167863,-0.071887,-0.639428,0.318033', '1306544', '26354526', '1424748', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25852314', '蜜月酒店杀人事件', '剧情', '朴实勤劳的吴大志（金英民 饰）是豪华大酒店的一名门童，这天是他和心爱的妻子结婚的日子。吴大志用婚假向经理换取了总统套房两天的使用权，以满足妻子的新婚愿望：在总统套过一个短暂但甜蜜温馨的蜜月。哪知，吴大志发现经理临时改变主意，将总统套房让给了炙手可热的大明星佩儿（张静初 饰）。吴大志很爱自己的妻子，不忍违背对妻子的承诺，想尽办法从佩儿那里要回总统套。奇怪的事情发生了。大明星佩儿行踪古怪，举止反常，并卷进了一件连环敲诈勒索事件中。善良的吴大志对佩儿心生怜悯，帮助她摆脱危机。而就在同一天，整容师崔医生（何润东 饰）与其女友雯雯（倪虹洁 饰）住进了酒店。雯雯还带来了神秘的男人钟皓。原来，雯雯和钟皓有一个针对崔医生的秘密计划，正在悄无声息地进行着......连续阴差阳错的巧合，将吴大志彻底卷进了这个奇妙的误会中。他渐渐发现了佩儿身上隐藏的惊天秘密……©豆瓣', '张静初', '张哲洙', 3.5, 2748, 'tt5914618', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2346589849.jpg', 51.6, 29, 14.6, 2.8, 2, '0.121625,0.237651,-0.508985,0.396140,-0.202160,-0.224295,0.701761,0.069882,-0.511325,-0.492647,0.052223,0.337082,-0.221928,0.247127,0.373320,0.141865,0.082132,-0.491507,-0.058526,0.037647,-0.229626,-0.571883,-0.302797,-0.474880,0.133404,-0.070085,0.159918,0.216918,-0.103925,0.321042,0.709836,0.296061,-0.137576,0.587533,-0.007655,0.160217,0.185303,0.300888,-0.333490,0.094582,0.123827,-0.325404,0.099873,0.280509,-0.008665,0.356032,0.587389,-0.060849,-0.445254,0.002134,0.505666,-0.056470,-0.027657,0.124686,0.126056,0.062988,-0.000019,0.099874,-0.250046,-0.111128,0.271364,-0.046575,-0.555801,-0.120067,0.213446,0.003352,-0.576211,0.296002,-0.064817,0.062601,0.075701,-0.383927,0.250902,0.162177,0.292074,0.385138,-0.038271,0.253732,-0.381569,0.310656,0.541866,0.114281,-0.010519,0.256191,-0.260825,-0.375564,0.062131,0.053772,-0.559994,0.128583,0.329187,-0.110722,0.079075,0.106565,-0.469192,-0.251101,-0.236458,0.228765,-0.010955,-0.378976,0.105615,-0.230518,-0.084919,-0.341628,-0.317621,0.009262,-0.034421,-0.268277,0.533171,-0.701149,0.161967,0.330951,0.218535,-0.710845,0.706746,0.176851,0.245413,-0.365919,0.145333,-0.034472,-0.042256,0.223721,0.282304,0.437125,-0.211704,-0.274939,-0.242037,0.193336', '3033092', '1301022', '1302384'