INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25853073', '近距离恋爱', '爱情', '就读于某高中的16岁的枢木润希（小松菜奈 饰）拥有极为灵光的脑瓜，虽然经常拿下全年级第一，但是不知为何她总是刻意隐藏自己的情感，旁人难以从她扑克一般的表情中看到任何情感波动，只有初中时代的好朋友娜美（山本美月 饰）才能走入润希的内心世界。在最近一次期中考试中，润希的英语成绩只有0分，这让担任班主任的樱井遥（山下智久 饰）颇为恼火，于是也不管女孩愿意与否便自顾自安排为润希补课。樱井英俊帅气，自信满满，是女学生们崇拜喜欢的对象，可是润希偏偏讨厌这个自大的家伙。为了摆脱樱井老师，她尽最大努力学习英语。然而当补课意外结束时，她终于察觉到那心早已悄然变化的情感……本片根据みきもと凜的同名漫画改编。©豆瓣', '山下智久', '熊泽尚人', 6.3, 53391, 'tt3688018', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2207808539.jpg', 4, 17.8, 46.2, 22.1, 9.9, '0.173408,-0.002732,-0.474836,0.594458,-0.282334,-0.199209,0.312312,-0.080793,-0.338158,-0.654760,-0.043806,0.465512,-0.106066,0.559548,0.143086,-0.172300,-0.081592,-0.500337,-0.020410,-0.348602,-0.020047,-0.376755,-0.230621,0.045314,-0.175407,-0.265434,0.656433,0.010195,-0.159749,0.564866,0.365103,0.228043,0.098450,0.490084,0.165695,-0.293417,0.021968,0.048344,0.014974,-0.015984,0.017450,-0.084598,-0.157391,0.171738,0.133891,0.344918,0.766902,-0.081460,-0.319229,0.253979,0.580590,-0.073621,-0.323360,0.157835,0.208980,-0.015807,0.173835,-0.042657,0.059487,0.133974,-0.055633,-0.222218,-0.560902,-0.063247,0.098925,0.086627,-0.101691,0.333645,0.089283,-0.196549,0.321986,-0.151316,-0.100448,-0.132433,0.391408,0.320647,-0.358544,0.259794,-0.015461,0.043763,0.429243,0.121037,-0.305510,0.495674,-0.369654,-0.384557,0.057313,-0.430337,-0.258423,0.300016,-0.159713,0.387182,-0.062346,0.101094,-0.215384,-0.122741,0.102816,0.132283,0.108772,-0.491039,-0.106190,-0.329684,-0.104175,-0.430046,-0.380681,-0.001698,-0.028296,-0.348083,0.857644,-1.016672,0.027906,0.336267,0.115535,-0.228571,0.422948,0.340525,-0.239092,-0.340997,-0.373252,0.297820,-0.033679,0.165718,-0.217633,0.377938,-0.109462,-0.438791,-0.299578,0.684415', '25922902', '10174444', '1826173', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25853727', '破风', '剧情', '郑知元（崔始源 饰）是世界闻名的赛车手，在目睹了他精彩绝伦的技巧和速度之后，初出茅庐的车手仇铭（彭于晏 饰）和邱田（窦骁 饰）心甘情愿地成为了他的“破风手”，并以三人之间的绝佳默契打败了强敌。然而，胜利是属于“冲线手”的，无论怎样努力，“破风手”不过只是默默无闻的陪衬 ，在明白了这一道理之后，仇铭和邱田选择了离开，两人成为了“冲线手”，在一次又一次的挑战之中试图击败郑知元。与此同时，仇铭和邱田同时爱上了名为黄诗瑶（王珞丹 饰）的美丽女孩，危险的三角关系让三人之间的友谊走到了尽头，最终，仇铭失去了邱田的音讯。多年以后，仇铭和邱田再度重逢，这一次，他们之间又会发生怎样的故事呢？©豆瓣', '彭于晏', '林超贤', 7.3, 141727, 'tt4788638', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2259282065.jpg', 0.9, 5.2, 36, 42.8, 15.2, '0.214221,0.167193,-0.806962,0.748582,0.040207,-0.211046,0.804609,-0.044947,-0.551652,0.015145,-0.041178,0.812693,-0.316039,0.049702,0.348510,-0.149367,0.052775,-1.034879,0.013053,-0.196527,-0.472627,-0.447171,-0.471982,0.027366,-0.053883,-0.133256,0.657765,0.362295,-0.163348,0.754112,0.557512,-0.041846,-0.030862,0.504289,-0.165828,0.099294,0.122919,0.114668,-0.381827,0.336971,0.121672,-0.314115,-0.336236,0.227837,-0.143646,0.233126,0.614302,-0.284811,-0.236191,-0.007087,0.080026,-0.442559,0.011648,0.048255,0.214058,-0.067824,0.330560,0.258261,-0.222954,-0.044424,0.349267,-0.098263,-0.781752,0.236297,-0.133121,0.148433,-0.823953,0.675049,0.101389,-0.277772,0.007889,-0.323987,0.254883,0.427848,0.594412,0.135808,-0.332835,0.034802,-0.322806,-0.053521,0.985506,0.191752,-0.258090,0.457073,0.051993,-0.592088,-0.450251,-0.330754,-0.144669,-0.023360,0.388371,0.337878,-0.059179,0.090389,-0.594678,0.003851,-0.222367,0.082619,-0.045870,-0.630281,0.067170,-0.178156,-0.189324,-0.698824,-0.321743,0.449085,-0.192053,-0.463725,0.496113,-1.078155,0.049947,0.315772,0.346202,-0.328210,0.736964,0.173834,0.122556,-0.237381,0.099511,-0.099372,-0.181524,0.233083,0.395583,0.438505,0.021037,-0.214306,-0.409147,0.425587', '35030151', '1301022', '30345227', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25855071', '初恋这首情歌', '剧情', '故事发生在1980年代的都柏林，因为家境窘迫，十四岁的少年康纳（福迪亚·瓦尔什-匹罗 Ferdia Walsh-Peelo 饰）不得不转学来到了一所校规极为严苛死板的教会学校中就读。在那里，他惹上了横行霸道脾气古怪的巴里（伊安·肯尼 Ian Kenny 饰），可见未来的日子不会好过。某日，康纳邂逅了名叫蕾菲娜（露西·宝通 Lucy Boynton 饰）的美丽女孩，为了吸引蕾菲娜的注意，康纳邀请她来主演自己乐队拍摄的MV，哪知道蕾菲娜欣然应允，那么问题来了，对演奏音乐几乎一窍不通的康纳，该如何在短时间内组建一支乐队呢？好在康纳拥有一群热爱音乐的朋友们，很快，一支名为“唱街”的乐队成立了。©豆瓣', '福迪亚·瓦尔什-匹罗', '约翰·卡尼', 8.2, 116651, 'tt3544112', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2615284298.jpg', 0.1, 1.4, 17.7, 49.6, 31.3, '0.454818,-0.040479,-0.579030,0.388015,-0.199363,-0.072187,0.563712,0.170642,-0.341005,-0.205068,0.362924,0.751126,-0.079103,0.084049,0.402469,0.199017,-0.342490,-0.421823,0.377312,-0.548019,0.142818,-0.717559,-0.278097,0.086534,0.094976,-0.539542,0.041546,-0.337639,0.148358,0.510827,0.394440,0.286636,0.049203,0.085213,0.168243,-0.084067,0.473109,-0.022753,-0.050589,0.027197,0.009935,0.023538,-0.344466,-0.058014,0.124401,0.167263,0.613958,-0.187226,0.088648,-0.104741,0.331718,-0.031331,0.117809,0.078407,0.279554,-0.156471,0.297186,0.225565,-0.261568,0.169225,-0.252742,-0.130290,-0.470702,0.222075,0.102187,0.376664,-0.646344,0.247531,-0.164861,-0.471565,0.222933,-0.316849,-0.025969,0.551073,0.338859,0.370649,0.060000,0.154263,-0.295106,0.115505,0.590840,-0.100371,-0.453734,0.397294,-0.344380,-0.282795,-0.042232,-0.114930,-0.691377,-0.120790,-0.018763,-0.309445,-0.169508,0.125114,-0.446586,-0.147617,-0.172596,-0.266539,0.068985,-0.330025,-0.306248,-0.606369,-0.038251,-0.311602,-0.199501,-0.321146,-0.210626,-0.096303,0.903737,-0.972389,0.164435,0.362224,0.227452,-0.192354,0.459210,0.290189,0.135861,0.184730,-0.400895,0.373595,-0.067081,0.163370,0.048588,0.480049,0.279537,-0.573916,-0.353474,0.290347', '1292219', '1292720', '25922902', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25855951', '贝利叶一家', '剧情', '农场主贝利叶夫妇和他们的儿子都是听障，日常工作和生活都要依靠女儿宝拉充当手语翻译。宝拉的音乐老师发现了她的天赋，鼓励她去参加法国电台的歌唱比赛。向往着去巴黎继续音乐之路的宝拉将与家人分离。这个人生必经的成年礼，对于贝利叶一家有着更为特殊的意义。', '露安·艾梅哈', '艾里克·拉缇戈', 8.4, 68637, 'tt3547740', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2217443926.jpg', 0.1, 0.8, 14.1, 49.7, 35.2, '-0.012989,-0.305374,-0.361073,0.965000,-0.315541,-0.165127,0.425942,0.176018,-0.317831,-0.329444,0.091101,0.921278,0.245168,0.341473,0.222509,-0.125805,-0.474054,-0.612830,0.113115,0.138434,-0.209555,-0.588024,0.210460,-0.123406,-0.009710,-0.335146,0.536912,-0.342375,-0.282249,0.829051,0.045427,-0.082930,-0.036241,0.295317,-0.292030,0.039482,0.084743,0.165679,-0.560274,-0.044711,0.099118,0.134908,-0.360092,0.098708,0.267860,0.191273,0.812345,0.171963,0.120764,-0.046019,0.146032,-0.225496,0.034750,0.226031,0.125989,0.277439,0.364191,0.518250,0.052236,0.122175,-0.278407,-0.213421,-0.878091,-0.030795,0.266683,0.034008,-0.573352,0.660697,0.037379,-0.218669,0.107401,-0.420855,0.406733,0.374688,-0.094069,0.773143,-0.243108,0.194299,-0.421606,0.436516,0.937208,-0.106823,-0.068111,0.517036,-0.407453,-0.738018,-0.031837,-0.207021,-0.663156,-0.110369,-0.111445,0.162756,-0.191170,-0.063023,-0.837968,0.212021,0.183058,-0.429800,0.260318,-0.678542,0.416589,-0.960511,0.137179,-0.621746,-0.348229,0.014078,0.268902,-0.406121,1.151663,-0.873956,0.201092,0.742843,0.381923,-0.750951,1.150591,0.283669,0.436243,-0.380072,-0.226594,0.188959,-0.285743,0.343685,-0.292416,0.368745,0.223716,-0.106708,-0.498922,0.574171', '3811356', '10876425', '4301278', '26646649');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25856453', '闺蜜2', '喜剧', '经历过情感挫折的希汶（陈意涵 饰）突然收到男友乔立求婚，开心之余闺蜜Kimmy（薛凯琪 饰）决定邀请她去越南展开一场单身之旅，同行的人还有乔立的表妹晶晶（王水林 饰），没想到希汶还邀请了Kimmy的死对头嘉岚（张钧甯 饰）。期待已久的越南之行来临，但是Kimmy和嘉岚剑拔弩张气氛一直很尴尬，闺蜜四人更是误打误撞闯入了黑帮的大型聚会，Kimmy和嘉岚因为赌气斗酒，令场面一度失控。一夜酩酊大醉后，众人醒来发现晶晶失踪，冤家路窄的嘉岚、Kimmy以及一箱金子被莫名铐在一起。随即，闺蜜团接到神秘电话，要求她们在一天之内花光所有金条。三人惊慌失措之时，又有飞车黑帮赶来追杀。为了逃命、为了救出晶晶、为了解决谜团，闺蜜们踏上了一段啼笑皆非的脱险之旅 。©豆瓣', '薛凯琪', '黄真真', 2.7, 23980, 'tt7870578', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2514909788.jpg', 77.4, 14.3, 6.2, 1, 1, '0.059827,-0.034151,-0.787213,0.090339,0.260066,-0.289413,0.662528,-0.050632,-0.637737,-0.304646,0.149493,0.491073,-0.716567,0.272866,0.656304,-0.279007,-0.229404,-0.566539,0.060497,-0.242576,-0.100604,-0.213640,-0.002570,0.035622,0.022417,-0.150430,0.272700,0.084642,-0.040542,0.916585,0.441739,0.169189,-0.372607,0.680829,0.075752,0.046230,0.063798,0.280795,-0.602350,-0.021070,0.000219,-0.118066,-0.130134,0.095721,0.145224,0.011301,0.614429,-0.136230,-0.153627,-0.030281,0.061989,-0.256686,-0.154611,-0.046220,0.322929,0.091448,0.436109,-0.094299,-0.196046,0.066439,0.313967,0.093754,-0.229085,0.386937,0.153724,-0.006955,-0.352969,0.322615,-0.012049,0.198571,0.109903,-0.413738,0.201582,0.639196,0.415985,0.367151,-0.156335,0.046658,-0.376234,0.103159,0.885367,-0.091360,0.311384,0.243040,0.153758,-0.281878,0.321675,-0.014649,-0.166348,0.250986,0.431835,-0.000831,-0.040726,0.211470,-0.709459,-0.203721,-0.177850,0.094505,0.023948,-0.422255,-0.122987,-0.606095,-0.037778,-0.005902,-0.231685,0.283507,0.026512,-0.259398,0.360164,-0.839592,0.140236,0.232820,0.302198,-0.392715,0.251183,0.204968,-0.090005,-0.185397,-0.072535,0.010597,0.074391,0.311694,0.076802,0.167709,-0.334293,-0.102284,-0.220385,-0.133429', '26687241', '1451563', '1298346', '1302987');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25856577', '朝我心脏开枪', '剧情', '本片讲述两名青年男子企图飞越疯人院的“奋斗历程”。男主角李秀明（吕珍九 Jin-gu Yeo 饰）因对母亲的自杀怀有内疚心理而患上精神分裂症，后被亲生父亲送入精神病院，多次转院，屡次申请出院，均被以各种原因拒绝。面对从不探望的父亲，面对医院冰冷的管理，面临同院好友圣民（ 李民基 Min-gi Lee 饰）“自由”的诱惑，秀明最终能否走出病院？本片根据郑柚井（音译）同名原作改编，原作曾获得2009年第5届韩国世界文学奖。', '吕珍九', '文在容', 7.7, 10081, 'tt4596408', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2221281086.jpg', 0.5, 3.2, 29.7, 44.4, 22.3, '-0.174655,-0.015656,-0.386299,0.425015,0.171321,-0.196288,0.325028,0.103771,-0.460178,-0.475161,0.298194,0.610786,-0.006940,0.353452,0.554047,-0.270524,-0.031832,-0.497306,-0.204414,-0.035350,-0.262658,-0.339255,-0.044513,-0.080597,-0.065318,-0.460689,0.804245,-0.168752,-0.328848,0.344842,0.345395,0.971587,-0.338573,-0.016859,0.118417,0.022665,0.220554,0.260236,-0.613488,0.404245,0.123146,-0.235578,0.003531,0.012087,-0.120018,0.332225,0.761872,-0.071966,-0.241690,-0.329435,0.700806,-0.046057,-0.395542,-0.009936,0.281475,0.314421,0.153334,0.681397,-0.140486,0.116289,-0.211501,-0.301745,-0.591316,-0.143345,0.460623,-0.047540,-0.267973,-0.085415,-0.069130,0.395158,0.036874,0.030585,-0.153145,0.155789,0.379836,0.501007,-0.166514,0.108655,0.091913,0.398359,0.489636,-0.359634,-0.282307,-0.062872,-0.360040,-0.160307,0.379053,-0.348839,-0.476180,0.437341,0.060070,0.170423,-0.304427,0.058895,-0.098661,-0.354413,-0.421050,-0.158108,0.307275,0.088058,0.064340,-0.521465,-0.019234,0.034516,-0.100461,-0.355456,0.115065,-0.302331,0.477868,-0.586078,0.442332,0.119288,0.315206,-0.899894,0.523742,0.238976,-0.053763,-0.472666,0.185109,0.751085,0.088525,-0.000093,-0.390309,-0.205711,-0.128663,-0.067455,-0.327310,0.117952', '26759820', '1482099', '1295746', '4861408');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25856626', '极秘搜查', '剧情', '1978年，在釜山发生的真实的故事 一个孩子被诱拐，刑警孔吉勇受孩子父母的特别嘱托，负责此次案件。为了保护孩子，他决定秘密搜查。一方面孩子的家人寻访各个有名的算卦店，来确认孩子的生死，得到的回答却是孩子已死，最后找到了道士金钟山。 ‘孩子肯定还活着’ 金道士用孩子的生辰八字算卦，确信孩子还活着，并且半个月后罪犯会第一次联络。如金道士所言，在孩子失踪半个月的时候接到了罪犯的电话，孔吉勇通过罪犯提供的线索确信了孩子还活着，开始相信金道士的话。但是过了一个月，搜查依然没有进展。比起孩子的生死，所有人更为寻找罪犯急红了眼，只有金孔吉勇和金道士两个人继续为拯救孩子展开搜查。', '金允石', '郭景泽', 7, 10277, 'tt4791594', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2244117940.jpg', 0.6, 5.3, 46.5, 36.9, 10.7, '-0.496135,-0.435154,-0.332074,0.230303,-0.428569,-0.169500,0.274141,-0.328148,-0.825774,-0.466916,0.014402,0.386034,-0.029300,0.204881,0.155738,-0.114342,-0.285350,-0.292062,-0.005315,-0.113443,-0.300878,-0.766282,0.216328,-0.452581,0.024303,-0.555912,0.291905,0.179149,0.239298,0.049825,0.045977,-0.417665,-0.387371,0.219517,-0.161815,-0.101638,-0.114703,0.131526,-0.222200,0.321081,0.201890,-0.060018,-0.034827,0.052683,0.135984,0.535663,0.681887,-0.458194,-0.254050,-0.118335,0.197141,-0.179658,-0.241868,0.005925,0.192902,-0.050811,0.432800,0.396944,-0.172079,-0.365841,-0.058558,-0.178780,-0.301484,0.116829,0.315387,0.001319,-0.602629,0.165292,-0.103727,0.425091,0.040128,-0.470859,0.375351,0.385453,0.138940,0.518694,-0.259428,-0.066254,-0.597929,0.184136,0.669132,-0.372138,0.115148,-0.015812,0.037588,-0.586742,-0.030908,-0.205977,-0.289318,0.715788,0.199285,0.129249,-0.640279,-0.032613,0.018265,-0.159177,-0.322513,0.088648,0.210677,-0.543747,-0.239112,-0.278387,0.523975,0.294515,-0.265214,-0.006040,0.137294,-0.385122,0.827847,-0.692000,0.349360,0.656490,0.385801,-0.879463,0.626632,-0.017608,0.319631,-0.615443,-0.098541,0.281310,0.357910,0.299265,0.319719,-0.061149,-0.345193,-0.119220,0.085173,-0.182253', '1421278', '1424743', '1877596', '30159456');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25857966', '鲛珠传', '喜剧', '故事发生在九州，一个聪明的贼（王大陆 饰）、一个尽职的捕快（张天爱 饰）和一个单纯的王子（盛冠森 饰），一次偶然的相遇。三个人有着各自不同的目的，互相不信任，却不得不共同进入一段奇特的旅行。在旅行中，三个人都从对方的身上找到了友谊和爱，最终阻止一次毁灭世界的阴谋。', '王大陆', '杨磊', 4.2, 39363, 'tt6288650', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2493908018.jpg', 28.3, 41.9, 24.4, 3.8, 1.5, '0.318493,0.292042,-0.755905,1.126056,-0.248208,-0.007585,1.089146,-0.239297,-0.431589,-0.350697,0.242547,0.810497,-0.161440,0.024952,0.088209,-0.129130,0.134422,-0.634517,0.043155,-0.180946,-0.483047,-0.561321,-0.603920,-0.376453,-0.246092,-0.286986,0.642100,0.391337,-0.238553,0.644821,0.507499,-0.040031,-0.626718,0.542921,-0.354902,-0.297099,0.294171,0.445354,-0.335298,0.222003,-0.266840,0.145960,-0.288693,0.170824,-0.239855,0.322048,0.865673,-0.730801,-0.158698,0.034989,0.362474,-0.327353,-0.308154,0.064115,0.308936,-0.103007,0.350087,0.298260,-0.015321,0.170601,0.201368,-0.050510,-1.108963,-0.226511,0.369620,0.244521,-0.562219,0.903210,0.060669,-0.428258,-0.003815,-0.217461,0.342024,0.626082,0.684188,0.377469,-0.148526,0.131180,-0.474049,0.068740,1.290094,0.070451,-0.316058,0.396335,-0.145710,-0.477848,-0.324813,-0.108460,-0.410285,0.310137,0.410024,-0.198638,-0.204515,0.134725,-0.992301,0.095394,-0.134891,0.044021,0.192101,-0.858248,0.155734,-0.418275,-0.116343,-0.434695,-0.331953,0.423068,0.019600,-0.174633,0.945803,-0.943527,0.138039,0.555674,0.124011,-0.684856,1.004548,0.422790,0.090512,-0.710982,0.089616,0.190397,0.288416,0.003497,-0.094725,0.773868,-0.077484,0.130798,-0.708419,0.252325', '2053515', '26678784', '25721544', '26803711');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25858604', '普罗旺斯的夏天', '剧情', '居住在法国南部乡村的老人保罗，在一个暑假突然迎来了三个不速之客——来自巴黎的外孙女和外孙。认知的分歧加上与女儿多年的失和让保罗与三个年轻人难以顺利相处。祖孙几个你来我往地过招，外婆不停从中调和。在不知不觉中保罗与外孙们的感情距离拉近了。', '让·雷诺', '罗丝·博斯', 8.4, 107320, 'tt3013588', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2176944875.jpg', 0.1, 0.7, 14.7, 48.8, 35.7, '0.423187,-0.236735,-0.944291,0.906262,-0.107537,-0.591401,0.806613,0.263189,-0.792967,-0.318060,-0.055790,0.892963,-0.469324,0.558397,0.256791,-0.692564,0.061129,-0.998804,-0.263080,-0.219165,-0.344204,-0.623162,-0.232212,-0.374932,-0.288705,-0.373410,0.301650,-0.090633,-0.051322,0.555769,-0.052733,0.031676,-0.730172,0.190352,-0.698492,-0.116197,0.432165,0.152119,-0.737546,0.323764,-0.102961,0.119744,-0.250348,-0.138560,-0.026374,0.369421,0.985345,-0.236417,-0.260120,0.148157,0.143923,0.096379,-0.256773,0.113150,0.562737,-0.120369,0.538953,0.197874,-0.252706,-0.161798,-0.246506,-0.318230,-0.470864,0.548542,-0.108361,-0.014075,-0.945229,0.974932,0.251966,-0.653489,0.039647,-0.362941,0.299492,0.878662,0.005050,0.713753,-0.278130,0.049559,-0.329670,-0.355532,1.007801,0.055972,-0.264588,0.216957,-0.148529,-0.178065,0.033564,-0.187633,-0.499259,-0.168777,0.657550,-0.216514,-0.120055,0.552771,-0.835891,0.325158,-0.521740,-0.219066,0.468709,-0.647296,0.129514,-0.589495,-0.391307,-0.808545,-0.324597,0.364861,0.014079,0.002918,1.146487,-0.786073,0.311647,0.509028,0.306700,-0.379516,0.809771,0.391817,0.366146,-0.552288,0.006178,-0.167024,-0.081798,-0.118584,0.434677,0.569393,-0.556333,0.415752,-0.580638,0.352261', '1296044', '1307146', '27040921', '1292219');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25858758', '侠盗联盟', '动作', '十七世纪西班牙皇室赠送给中国皇帝的礼物GAIA，而今虽然被分为森之瞳、灵之泉、命之翼三份，却依然价值连城，令人垂涎。出狱不久的江洋大盗张丹（刘德华 饰）将目标锁定在这几件宝物上，他找到资深黑客小宝（杨祐宁 饰）以及女贼叶红（舒淇 饰），成功混进戛纳拍卖会场， 在交手多次的法国警探皮埃尔（让·雷诺 饰）鼻子底下偷走了命之翼，最终交到幕后老板金刚（曾志伟 饰）的手上。连上坐牢前偷到的森之瞳，只差最后的灵之泉即可将GAIA重新合在一起。而就在此时，皮埃尔找到当初遭到张丹背叛的前女友Amber Li（张静初 饰），展开对大盗们新一轮的追捕……©豆瓣', '刘德华', '冯德伦', 5.2, 63655, 'tt5866930', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2494018217.jpg', 7.6, 36.4, 47, 6.9, 2.2, '0.269945,0.380705,-0.605267,0.455242,0.083349,-0.293145,0.452407,-0.104211,-0.552246,0.066660,0.328669,0.587600,-0.418919,-0.091310,0.124756,0.118208,-0.163492,-0.733693,-0.088769,-0.295844,-0.380034,-0.270575,-0.508460,0.252670,-0.121164,-0.218867,0.563660,0.047124,-0.076447,0.490544,0.647735,0.298088,-0.014907,0.096942,-0.295644,0.045277,0.194741,-0.050877,-0.333589,0.493833,-0.040661,-0.301101,0.112544,0.124787,0.037704,0.299973,0.584605,-0.356590,0.079769,-0.028344,0.362285,-0.228219,-0.185143,0.187649,0.261415,0.452911,0.182661,0.174282,-0.406765,0.112441,0.355017,0.016110,-0.567055,0.082812,0.366592,0.076062,-0.438492,0.236012,-0.278379,0.437149,-0.010246,-0.372414,0.292313,0.250141,0.086480,0.104688,0.041016,0.017651,-0.556910,0.237835,0.433503,-0.230393,0.231534,-0.082187,0.314244,-0.312697,0.083702,-0.483698,-0.076088,0.147333,0.498071,0.046821,0.250633,-0.132895,-0.837360,-0.152377,-0.215232,-0.106280,0.213203,-0.102044,-0.005617,-0.635067,-0.058922,-0.279365,-0.402164,0.034626,0.164413,-0.392440,0.471609,-0.376674,0.381827,0.357589,0.243505,-0.116093,0.412999,-0.073399,0.078046,-0.168762,-0.551292,0.146437,0.570537,0.315293,0.094662,0.196800,-0.065971,-0.376085,-0.339538,0.336401', '4301278', '4212172', '1780122', '26290398');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25858759', '有一个地方只有我们知道', '爱情', '“你永远也不知道，两通没有接到的电话，竟会失去两个最爱的人，人生从此发生改变。”美丽女孩金天（王丽坤 饰）遭到未婚夫背叛，而她在这个世上的唯一亲人奶奶陈兰心（徐静蕾 饰）也因病去世。这个万念俱灰的女孩顿时失去人生的方向，彷徨间她拉起行李箱，乘飞机来到了浪漫都市布拉格。至于为什么来到这里她没有确切的原因，或许是因为这是奶奶年轻时曾生活过的地方。金天不愿再像从前那样浑浑噩噩，她尝试着做一些不平凡的事情，于是便在某个喧嚣的舞厅结识了英俊帅气的大提琴手彭泽阳（吴亦凡 饰）。以爱情的名义，金天仿佛和去世的奶奶建立了某种联系，数十年前发生在兰心身上的恋情似乎又以别样的方式重演。在浪漫的河畔流连忘返，男男女女兀自朝着未知的方向行进……©豆瓣', '王丽坤', '徐静蕾', 4.9, 167159, 'tt4074958', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2226010180.jpg', 22.2, 31.8, 31.2, 9.3, 5.4, '0.420421,0.009427,-0.932242,0.523609,-0.042109,-0.188432,0.961473,0.044131,-0.430920,-0.379091,0.077175,0.773707,0.062256,0.505644,0.284038,0.013919,-0.200347,-0.723261,0.189165,-0.049008,-0.234602,-0.392115,-0.150377,-0.066221,0.098245,-0.257601,0.584658,0.096086,-0.230620,0.412111,0.240937,0.273148,-0.237752,0.568289,-0.443011,0.224204,-0.025092,0.525831,-0.432147,0.053178,0.217563,-0.333028,-0.091371,0.189611,-0.237891,0.221475,0.507503,-0.357699,-0.531331,-0.050218,0.412604,0.050706,-0.150622,0.023412,0.111394,-0.037501,0.101129,0.293851,-0.289746,-0.041488,0.084713,-0.006515,-0.457939,0.109990,0.086241,0.298160,-0.532407,0.361736,-0.026189,-0.318506,0.272839,-0.439733,0.372645,0.315411,0.207117,0.320411,-0.270098,-0.007062,-0.490035,0.244335,1.034733,0.258586,-0.283357,0.514507,-0.200279,-0.204734,-0.059214,-0.074474,-0.524022,0.306879,-0.004939,0.081591,-0.253298,0.216829,-0.433105,0.109279,-0.008187,-0.123308,0.218759,-0.364671,-0.333001,-0.240602,-0.155327,-0.565272,-0.363371,0.092513,-0.166002,-0.137502,0.514372,-0.970339,0.384487,0.324718,0.297349,-0.757783,0.735015,0.158433,0.002049,-0.287974,0.177071,0.626076,-0.261859,0.256213,-0.105778,0.105057,-0.083878,0.157205,-0.451767,0.534211', '25721544', '4275444', '1308755', '1296370');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25858760', '大宅男', '喜剧', '阿宅（萧敬腾 饰）和他的室友抠男（大鹏 饰）是大学里的“铁血纯屌丝”，他们最大的梦想就是可以献身女神。抠男为了接近他的女神川美（谢娜 饰），假扮富二代，在川美身边神出鬼没，闹出很多笑话。而不善于表达的阿宅则通过“计算与奔跑”努力制造出一次次走廊偶遇，来与女神雅玲（江疏影 饰）搭话，但他这些伎俩总会被高冷的雅玲看穿，最后尴尬收场。一场建校以来最大的情侣PARTY举办在即，作为惯例，大家要成双入对出席，这一晚仍单身的人，他的名字就将会被刻在学校的“耻辱柱”上，成为笑柄。在这个危急存亡的关头，阿宅和抠男决定背水一战，化被动为主动，想尽方式求爱献身，于是，一场事关雄性动物尊严的“女神杯”大战降临……©豆瓣', '萧敬腾', '朱延平', 4, 4369, 'tt4412082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2250779952.jpg', 40.3, 32.5, 19.3, 4.1, 3.9, '0.188433,0.101050,-0.352018,0.447215,-0.192770,0.010336,0.511631,-0.166819,-0.174028,-0.126539,0.310752,0.706937,-0.392225,0.056877,0.359264,-0.227907,0.065168,-0.687525,-0.039534,-0.054373,0.007411,-0.222688,-0.173702,-0.053019,-0.273759,0.029636,0.676723,-0.137631,-0.491234,0.345400,0.746597,0.347537,-0.030788,0.121171,-0.121405,-0.281095,-0.237876,0.107523,-0.130943,0.137357,-0.004056,-0.261259,-0.053678,0.261041,-0.007551,0.195386,0.593966,-0.491632,-0.028881,-0.083727,0.408788,-0.631558,-0.095044,0.304486,0.326321,0.031337,0.154140,0.127305,0.125441,-0.139446,0.224986,-0.160205,-0.767555,-0.028199,0.171690,0.059142,-0.464856,0.558193,0.151184,-0.129381,0.270337,-0.310806,0.255785,0.179629,0.452323,0.357690,-0.169384,0.045147,-0.310968,0.253680,0.693611,0.067659,-0.099827,0.070016,-0.092527,-0.331064,0.056901,-0.458048,-0.543439,-0.140311,-0.025350,0.009655,-0.036367,0.140086,-0.589133,-0.083304,-0.076330,0.073069,0.299653,-0.498334,-0.053948,-0.521816,0.022169,-0.330701,-0.121003,0.117864,0.143497,-0.528180,0.607443,-1.077255,0.097558,0.475149,0.380569,-0.481653,0.830178,0.323557,0.005679,-0.332269,-0.139485,0.088057,-0.058234,0.261636,-0.072618,0.277866,-0.012022,-0.027171,-0.373645,0.373613', '4301278', '1316589', '35030151', '30345227');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25858785', '澳门风云2', '喜剧', '曾经名贯国际赌坛的赌侠“魔术手”石一坚（周润发 饰），在半年前协助国际刑警摧毁洗钱集团DOA后便销声匿迹，隐退江湖，整日里和他那台操着四川话的机器人傻强插科打诨，倒也逍遥自在。但是好景不长，某天他险些遭到女杀手刺杀。原来宿敌DOA对其恨之入骨，定欲灭之于无形。除此之外， DOA首席会计师小马（张家辉 饰）卷走组织高达150亿美元的黑金，带着女儿初一（王诗龄 饰）逃到泰国。迫不得已，石一坚和担任国际刑警的大弟子阿乐（余文乐 饰）合作，追查DOA的幕后主使，并试图寻找到小马的踪迹。上天入地，子弹横飞，围绕着巨额黑金和DOA的秘密，正邪双方展开了新一轮的较量与厮杀……©豆瓣', '周润发', '王晶', 5.6, 161512, 'tt4310772', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2224055583.jpg', 10.6, 26, 43.5, 14.2, 5.8, '-0.072689,-0.084259,-0.751171,0.610973,0.047371,0.011598,0.424328,0.196924,-0.322986,-0.166743,0.281360,0.625242,-0.143411,0.002188,0.155051,-0.143622,-0.073417,-0.830858,-0.232215,-0.097010,-0.107507,-0.362710,-0.363954,-0.017525,-0.059270,-0.015412,0.421265,0.093052,-0.390753,0.509494,0.387791,0.132728,-0.517932,0.293905,-0.158969,-0.135230,0.091484,0.244063,-0.340306,0.161065,-0.080220,-0.422312,-0.050096,-0.219502,-0.023925,0.389822,0.446380,-0.306074,0.324254,-0.182141,-0.046148,-0.480986,-0.177886,-0.080744,0.504254,0.221140,0.257713,0.249216,-0.101054,-0.075155,0.166695,-0.113972,-0.698482,-0.013106,0.089934,0.035986,-0.644751,0.388369,-0.371577,0.192571,-0.016169,-0.051505,0.128420,0.279335,0.085842,-0.105330,0.078633,0.163238,-0.542197,0.378889,0.393659,-0.165649,-0.047783,-0.070193,0.452318,-0.242978,-0.256987,-0.258769,-0.174124,-0.385196,0.459419,-0.113330,-0.104286,0.196487,-0.649258,0.111877,-0.147075,0.015445,-0.036190,-0.292401,0.029176,-0.696349,-0.168557,-0.457816,-0.052015,0.173370,0.201314,-0.114683,0.432899,-0.665074,0.127082,0.401216,0.290410,-0.380733,0.405525,-0.020273,0.151003,-0.289154,-0.363941,-0.029328,0.280963,0.486727,0.336357,0.104709,-0.002298,-0.269820,-0.175949,0.076472', '25723905', '1307442', '1307762', '1293829');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25859495', '思悼', '剧情', '18世纪初，朝鲜李氏王朝正值英祖（宋康昊 饰）在位时期。英祖舐犊情深，在长子早逝后，他全部希望寄托在次子李愃（刘亚仁 饰）身上。不仅在他刚出生之际就册封为世子，更为其安排名臣督导功课。然而天不遂人意，世子耽于玩乐，无心学业，英祖一度提拔世子代理国政，可却使这对站在权力顶峰的父子渐行渐远。在一个瓢泼雨夜，世子杖刀闯入王宫。次日，他因意图谋反而遭到英祖的训斥，并被锁入米柜之中。在接下来的八日里，这对形同寇仇的父子各自回忆起过往的种种。也许翻为平民父子更好，王宫内院最残酷的竟发生在最亲近人的中间……©豆瓣', '宋康昊', '李濬益', 8.5, 119494, 'tt4010918', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2256702287.jpg', 0.3, 1, 13.2, 45.6, 39.9, '-0.071176,0.254673,-0.825488,0.730684,0.080163,-0.174623,0.660965,0.480104,-0.670452,-0.608996,0.443905,0.523922,-0.239194,0.046402,0.403471,-0.282688,-0.234790,-0.496114,-0.001894,-0.246670,-0.101027,-0.364843,0.143339,-0.133903,-0.352023,-0.274737,0.714754,0.085574,0.105382,0.264667,0.202784,0.079779,-0.080455,0.596221,-0.179222,0.080775,-0.180601,0.038699,-0.234408,-0.122723,-0.101144,-0.571874,-0.307780,0.103892,-0.067475,0.176768,0.637927,-0.487042,0.136634,-0.363390,0.415287,-0.144618,-0.116506,0.308104,0.527172,0.026585,0.010950,0.475064,-0.171762,0.080410,-0.014317,-0.175502,-0.519654,-0.022107,0.082182,-0.046668,-0.391492,0.645353,-0.078162,-0.067176,0.048284,-0.197193,0.390130,0.640821,-0.151456,0.397013,-0.313630,0.024731,-0.528740,0.197838,0.582613,-0.110200,-0.150402,0.187776,0.140567,-0.269030,0.246491,-0.244852,-0.329905,-0.330601,0.160434,0.027131,-0.045657,0.663972,-0.127967,0.196048,-0.366253,0.090835,0.464727,-0.475437,-0.080088,-0.170806,-0.083643,-0.451163,-0.252005,0.196420,0.417120,-0.287741,0.349612,-0.653456,0.268266,0.096090,0.286623,-0.382178,0.532459,0.107767,0.269880,-0.025294,-0.280996,0.108465,0.175184,0.169426,-0.212157,0.090852,-0.180128,-0.135895,-0.409834,0.218181', '25870679', '1301022', '25721544', '26280710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25860868', '敲敲门', '惊悚', '小有名气的建筑师埃文·韦伯（基努·里维斯 Keanu Reeves 饰）事业有成，生活美满。他住在洛杉矶一套亲手设计的别墅中，妻子凯伦（伊格纳西·阿尔曼德 Ignacia Allamand 饰）美艳动人，一双儿女杰克（Dan Baily 饰）和莉莎（Megan Baily 饰）乖巧可爱。某个假日，凯伦驱车带着孩子们外出度假，留下埃文一人在家中工作。瓢泼大雨之夜，艾文突然听到了敲门声。来者是被淋成落汤鸡的女孩贝尔（安娜·德·阿玛斯 Ana de Armas 饰）和吉妮丝（洛伦扎·伊佐 Lorenza Izzo 饰），他们迷失方向，请求埃文提供帮助。两个女孩就像善解人意又诱惑媚人的小妖精，让埃文多少有些把持不住。色字头上一把刀，世间哪有从天而降的美食和便宜……©豆瓣', '安娜·德·阿玛斯', '伊莱·罗斯', 5.1, 10170, 'tt3605418', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2264507480.jpg', 16.6, 32.8, 36, 10.1, 4.5, '0.051313,-0.000453,-0.412110,0.293910,-0.080851,-0.232778,0.685293,0.314859,-0.072498,-0.047352,0.161745,0.681500,-0.233573,0.419784,0.426197,0.295989,-0.472766,-0.525611,0.156199,0.096082,-0.016892,-0.354709,-0.117972,0.014450,0.127031,-0.291546,0.070809,-0.331548,0.227528,0.604057,0.459828,0.448947,-0.335186,0.059238,-0.306246,-0.040149,0.189009,-0.311329,0.084566,0.164095,-0.236960,0.079810,-0.108876,0.117544,0.112166,0.217550,0.660979,-0.263818,0.055578,-0.173402,0.001017,0.029852,0.129054,0.191998,-0.212926,-0.165682,0.256790,-0.098448,-0.250503,-0.027347,0.352432,-0.329604,-0.128767,0.104109,0.159032,0.118204,-0.455986,0.326656,-0.191732,-0.147224,0.006150,-0.524883,-0.170237,-0.145028,0.067493,0.577253,0.204976,0.332934,-0.576600,0.067489,0.120631,0.062554,-0.004937,0.253900,-0.256275,-0.154534,0.082706,0.048858,-0.707489,-0.055587,0.566246,-0.144977,0.190320,0.074709,-0.523505,0.105044,-0.518400,-0.001080,-0.030969,-0.295886,-0.300122,-0.651679,0.208954,-0.415817,-0.464861,0.060781,0.133279,0.166189,0.524741,-0.502041,0.166355,0.414313,0.192737,0.080826,0.481540,-0.009913,0.258320,0.027974,-0.186247,0.267792,0.120733,-0.142468,0.329773,0.362313,-0.344013,-0.058032,-0.227840,0.301145', '1301686', '1394176', '10466639', '1292050');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25861695', '海月姬', '喜剧', '曾经充满幻想的小女孩仓下月海，一直希望能像妈妈说的那样成为美丽雍容的公主。无奈如今的她（能年玲奈 饰）一身宅女打扮，根本无法融入当下的时尚社会中。依然保持着对水母喜爱之情的月海离开鹿儿岛，住在东京一处名为“天水馆”的老旧公寓中。正所谓物以类聚，这里住着好几位宅属性爆表的女孩。搜集名贵风物的管理员千绘子（马场园梓 饰）、痴迷铁路的爆炸头邦巴（池胁千鹤 饰）、《三国志》狂热爱好者玛雅雅（太田莉菜 饰）、迷恋中年大叔的吉吉（筱原友惠 饰）以及一位足不出户的神秘BL漫画家目白树音。偶然机缘，月海将一个美丽女孩带回家，谁知对方竟然是热衷女装的男孩鲤渊藏之介（菅田将晖 饰）。藏之介的出现令宅女们的世界发生前所未有的改变，与此同时她们赖以憩息的“天水馆”也面临消失的命运……本片根据东村明子创作的同名漫画改编。©豆瓣', '能年玲奈', '川村泰祐', 7.1, 15553, 'tt3673764', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2204589689.jpg', 1, 6.3, 41.9, 37.6, 13.2, '0.180855,0.166426,-0.460811,0.432425,-0.046485,-0.016605,0.601677,0.038989,-0.413454,-0.291261,0.367126,0.567591,-0.224759,0.295618,0.399166,0.173203,-0.194595,-0.332024,-0.254319,-0.173541,0.027384,-0.157949,-0.303158,0.156963,-0.209265,-0.398452,0.609346,0.163568,-0.165205,0.407863,0.338810,0.574456,-0.283923,0.128547,-0.079325,-0.079372,-0.084580,-0.027382,-0.124246,0.273466,-0.289549,0.023923,-0.031484,0.011673,0.026162,-0.092159,0.896485,-0.396783,-0.161470,-0.145260,0.588434,0.294079,-0.152833,0.084758,0.208063,0.037314,0.113953,-0.044939,-0.198680,-0.224421,0.236680,-0.219499,-0.364312,0.044663,0.392569,0.264349,-0.229119,0.231143,0.132454,-0.284555,0.188659,-0.207030,0.013067,-0.116967,0.318565,0.397204,-0.095551,0.301271,-0.312186,0.370749,0.262884,0.146325,-0.311588,0.180538,-0.371447,-0.267578,-0.225737,-0.295905,-0.593213,-0.007301,-0.002471,-0.003326,-0.086916,-0.024669,-0.473030,0.114870,-0.070506,-0.012629,0.286771,-0.139241,-0.390631,-0.663930,0.094103,-0.572292,-0.077829,-0.069418,0.189944,-0.182640,0.903424,-0.799648,0.142061,0.373771,0.234184,-0.119069,0.625914,-0.191792,-0.129774,-0.236400,-0.471734,0.516725,-0.204102,0.177758,-0.110505,0.593153,-0.223848,-0.125977,-0.425261,0.329929', '3811356', '10174444', '25922902', '5403927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25862300', '发掘', '剧情', '第二次世界大战即将爆发时，一个富有的寡妇雇用了一名业余考古学家在她的庄园内挖掘墓冢。当他们做出历史性发现时，英国的过去和不确定的未来将遥相呼应。', '凯瑞·穆里根', '西蒙·斯通', 7.9, 19372, 'tt3661210', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2627529751.jpg', 0.3, 1.6, 23.5, 52, 22.6, '0.505299,0.307731,-0.951005,0.447432,-0.021709,-0.372683,0.886992,-0.183437,-0.167892,-0.193084,0.369261,1.127544,-0.362295,0.156214,0.168070,0.155265,-0.230160,-0.811268,-0.493828,-0.178657,-0.503096,-0.153701,-0.451514,0.020327,-0.273469,-0.191933,0.939692,0.044672,-0.464790,0.192995,0.017236,0.546296,0.143214,0.290071,-0.313205,-0.110862,0.452603,0.212254,-0.158274,0.453547,-0.135629,-0.277937,-0.241477,0.022966,-0.170149,0.363612,0.711075,-0.415219,-0.205276,-0.270194,0.880962,-0.126768,-0.114941,0.225743,0.396993,0.241942,-0.373813,0.328055,-0.458142,-0.075170,-0.066506,-0.190178,-0.957255,0.001807,0.081588,-0.102858,-0.860347,0.434205,0.192312,-0.369388,0.553169,-0.498623,0.577150,0.867598,0.169065,0.104515,-0.424388,0.092301,-0.724025,0.195937,0.835852,-0.120114,-0.594878,0.115746,0.209624,-0.673780,0.023020,-0.143160,-0.519971,0.064066,0.392290,0.066158,-0.300053,-0.043807,-0.473238,-0.386214,-0.311743,-0.314236,0.145142,-0.159906,-0.668192,-0.743024,-0.223257,-0.261353,-0.399591,-0.009401,-0.116900,-0.109870,0.832489,-0.905906,0.241589,0.757156,0.302571,-0.158461,1.044194,-0.196923,0.087533,-0.341936,-0.153947,-0.081489,0.218773,0.537775,0.247167,0.600026,-0.277999,-0.168940,-0.287458,0.688525', '30162520', '25928048', '3055049', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25862354', '局内人', '剧情', '电影《局内人》该片是一部犯罪动作片，通过保守派报纸评论员、国会议员、大企业委员、黑社会混混、情报科刑警、纪录片摄影家等人的经历，来揭露韩国社会的腐败和不正之风。李秉宪在片中饰演的安尚久一角原本是作为权利者的“猎狗”干尽坏事，但在自己成为废人之后，为了报仇而成为向着权利者开战的“政治流氓”。曹承佑饰演"禹长勋检察官"一角,是个在检察官组织中让踢人就踢人让掩盖罪行就掩盖罪行的腐败政治人的阻击手。白允植饰演的首都日报评论员李强熙。', '李秉宪', '禹民镐', 8, 106833, 'tt3779028', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2275293773.jpg', 0.3, 1.4, 20.9, 50.5, 27, '0.120640,-0.251605,-0.296178,0.651128,-0.104212,0.253328,0.540603,0.254410,-0.528105,0.013531,0.418300,0.680950,-0.009495,-0.026873,0.462836,-0.126787,-0.456015,-0.989287,-0.127321,-0.166860,-0.144845,-0.372795,-0.131785,-0.585924,-0.121067,-0.286176,1.146907,0.112152,-0.557893,-0.027974,0.549474,0.171757,-0.038075,0.141294,0.064300,0.018493,0.308228,-0.362176,-0.262221,0.164382,0.170480,-0.554521,-0.221211,0.012847,-0.113141,0.267348,0.327692,-0.180104,0.093614,-0.307086,0.431260,-0.730878,-0.140628,0.033531,0.456488,-0.141674,0.430135,0.507642,0.071843,-0.012548,0.091537,-0.161333,-0.852327,-0.295004,0.229136,0.394985,-0.432215,0.708194,-0.063373,0.189851,-0.030240,0.184366,0.194012,-0.109915,0.186954,0.539653,0.213151,0.112469,-0.361830,0.481494,0.492773,0.125216,-0.312613,0.128466,-0.252922,-0.442950,-0.297215,-0.577115,-0.355472,-0.198385,0.227665,-0.524473,-0.172813,0.330719,-0.376750,-0.040249,-0.085696,-0.109094,0.079846,-0.317627,0.003102,-0.518577,-0.196953,0.125079,0.147093,0.008146,0.287098,-0.527912,0.715913,-0.691974,-0.193190,0.693281,0.107326,-0.617119,0.887624,-0.103342,-0.045397,-0.386033,-0.216464,-0.089300,0.535572,0.326084,-0.094667,0.053019,-0.123432,-0.656271,0.209298,0.092663', '6101834', '25880986', '3014200', '35262731');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25862355', '二十', '剧情', '该片讲述的是三个二十岁的小伙儿青春年少的故事，金宇彬饰演的是一个不善处理异性关系、冲动热血、游手好闲的家伙。', '金宇彬', '李炳宪', 6.9, 28681, 'tt4415016', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2229383316.jpg', 1.3, 8.7, 44.4, 34.1, 11.5, '0.520672,-0.629033,-0.183148,0.430673,-0.567243,-0.025278,0.882704,-0.115624,-0.535523,-0.564634,0.217445,0.421307,-0.188420,0.607523,0.291460,-0.099242,0.549224,-0.887874,-0.412470,0.123453,0.178011,-0.540151,-0.253687,-0.004418,-0.146503,-0.744827,0.431576,-0.492498,-0.359619,0.380873,0.924826,0.122318,-0.141640,0.216209,-0.227544,-0.384656,0.104096,-0.233114,-0.081327,-0.148761,-0.347380,-0.028329,0.022918,-0.119762,-0.242942,1.028597,0.804674,0.474367,-0.291784,0.079351,0.743079,-0.066468,-0.663653,-0.115616,0.526785,-0.062975,0.368813,0.251518,0.177591,-0.295339,-0.334439,-0.283046,-0.763448,-0.109930,0.095478,0.601299,-0.789958,0.361596,0.422391,-0.366152,0.242878,0.158527,0.183202,-0.248357,0.382997,0.783634,0.322700,0.089666,-0.126284,0.340028,0.719477,0.341657,-0.254955,0.876487,-0.201198,-0.174257,-0.067778,-0.070154,-0.914336,0.200776,-0.095430,-0.534184,-0.439088,0.210944,-0.553186,-0.111181,-0.100653,0.117997,0.230806,-0.506890,0.057742,-0.291388,-0.581270,-0.556204,-0.302901,-0.039416,0.363551,-0.439147,1.344574,-0.438955,-0.515451,0.628988,-0.170784,-0.817806,0.620462,0.581863,-0.218052,-0.380268,0.262796,0.116998,0.054526,-0.914296,-0.349997,0.882995,-0.538979,-0.389639,-0.383291,0.529345', '26348103', '25738406', '26790961', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25862560', '真相背后', '剧情', '麦克（加布里埃尔·巴索 Gabriel Basso 饰）是一名17岁的少年，他被控告谋杀了自己的父亲。所有证据都表明麦克确实犯下了不可饶恕的罪行，行凶的刀上检测到了他的指纹，更糟的是，麦克似乎并无意于为自己发声，从逮捕到临近开庭，他一言未发。理查德（基努·里维斯 Keanu Reeves 饰）是负责为麦克辩护的律师，法庭上所有的一切都对他的辩护非常不利。然而，理查德的直觉告诉他，麦克并不是杀人凶手，一切的背后定有隐情。于是，他找来了同行珍妮（古古·姆巴塔-劳 Gugu Mbatha-Raw 饰）做帮手，两人决定重新彻查此案，不放过任何的蛛丝马迹。©豆瓣', '基努·里维斯', '科特妮·亨特', 7, 6786, 'tt3503406', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2392537011.jpg', 0.5, 4.8, 47.1, 39.3, 8.3, '0.312402,-0.092836,-0.616310,0.479049,-0.511352,-0.085565,0.865690,0.079399,-0.466135,-0.259591,0.340767,0.604571,-0.003955,0.095629,0.139579,0.221550,-0.322483,-0.967461,0.091956,-0.206004,-0.318398,-0.978698,-0.094122,-0.159076,-0.121138,-0.088302,0.232046,-0.116137,-0.277616,0.075357,0.448325,0.301199,0.284948,0.644358,0.017927,-0.177966,0.058613,-0.276741,-0.193974,0.014038,0.180678,-0.443343,-0.253902,0.570250,-0.123619,0.752528,0.256739,-0.211886,-0.320204,0.186018,0.489824,-0.530985,0.401991,0.248126,0.253949,0.013012,-0.226611,0.567784,-0.313191,-0.121052,0.133764,0.023921,-1.110499,-0.164807,-0.036564,0.402355,-0.541542,0.105806,-0.495902,0.131460,-0.006848,-0.251451,0.114356,0.053930,0.037670,-0.035521,-0.190983,-0.292855,-0.694558,-0.040759,0.380856,0.120612,-0.070249,-0.110447,0.032185,-0.494412,-0.076590,0.110992,-0.305685,0.146835,0.281114,-0.039333,-0.160146,0.189000,-0.236616,-0.389131,-0.521692,-0.335596,-0.157565,-0.474512,0.086678,-0.407798,-0.123662,-0.144400,-0.482115,-0.061343,0.318417,-0.416219,0.288216,-0.591231,0.105629,0.741438,-0.038577,-0.515542,0.504502,0.212108,0.054911,-0.264299,-0.271517,0.168544,0.525697,0.441271,0.282426,0.351115,0.587401,-0.154602,-0.400682,0.445343', '1307442', '1296217', '2027938', '35073886');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25863940', '预告犯', '悬疑', '自称“报纸男”的人悄然出现网络，他上传视频，宣称对一些行为不断的人或企业进行私刑处罚。起初网民们嗤之以鼻，谁知报纸男居然真的行动起来。报纸男的行径煽动了人们一颗颗被压抑已久的正义之心，他也得到了越来越多的粉丝。事实上，报纸男绝非一人，他是由“盖茨”奥田宏明（生田斗真 饰）、 “关西”葛西智彦（铃木亮平 饰）、“大雄”木村浩一（滨田岳 饰）以及“胖墩”寺原慎一（荒川良良 饰）组成。有着不同背景的四人沦落社会最底层，他们在远离城市喧嚣的地方曾见证过人间最残酷的一面，也缔结了浓浓化不开的友情。报纸男们携手对这个世界进行公审，而网络犯罪对策课的警部吉野绘里香（户田惠梨香 饰）则全力追查这几个男人背后的故事……本片根据筒井哲也的漫画原作改编。©豆瓣', '生田斗真', '中村义洋', 7.4, 31188, 'tt3952226', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2232713173.jpg', 0.5, 4.4, 37.2, 42.7, 15.2, '-0.013910,-0.046169,-0.519443,0.648424,0.081277,0.247741,0.481060,0.246727,-0.299690,-0.154533,0.244546,0.554797,-0.389121,0.159128,0.157102,-0.195003,-0.397925,-0.650707,0.018414,-0.293661,-0.016625,-0.224718,-0.000429,-0.343385,-0.259995,-0.148181,0.802439,0.038906,-0.308595,0.243707,0.440495,0.143553,-0.193100,0.278734,0.009879,0.038715,0.154237,0.004454,-0.112774,-0.141179,-0.118417,-0.266819,-0.269332,0.322109,-0.116202,0.204111,0.775341,-0.253897,-0.253981,-0.290646,0.457428,-0.156379,-0.146943,0.081023,0.596506,-0.093236,0.128367,0.257506,-0.013856,-0.130520,0.125599,0.136598,-0.571918,-0.100441,-0.007318,0.283433,-0.026330,0.334714,-0.263796,-0.020867,-0.144693,-0.075060,0.011275,-0.034734,0.274392,0.078289,-0.070329,-0.182699,-0.235473,0.306353,0.322486,0.265063,-0.013834,0.336522,-0.365979,-0.414861,-0.406210,-0.011482,-0.436398,-0.172926,0.181771,-0.224608,-0.282044,0.267101,-0.672025,0.047286,0.139860,-0.144178,0.194714,-0.274429,-0.157476,-0.880135,-0.199313,-0.235262,-0.127363,0.105572,0.267798,-0.150143,1.193372,-0.637938,-0.186715,0.497497,0.274220,-0.486535,0.417579,0.161483,-0.198176,-0.115147,-0.392814,0.057136,0.212179,0.243615,0.164348,0.349475,-0.059745,-0.273191,-0.165774,0.407311', '3811356', '5403927', '27602116', '25922902');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25864085', '火星救援', '剧情', '载人航天宇宙飞船阿瑞斯3号成功抵达火星，谁知一场破坏力极其巨大的风暴向宇航员们袭来，阿瑞斯3号被迫中断任务，紧急返航。撤离途中，宇航员马克·沃特尼（马特·达蒙 Matt Damon 饰）被飞船上吹落的零件击中，由于生还希望渺茫，队友们只得匆匆返航，并向世人宣告他已牺牲的事实。出乎意料的是，马克以极低的概率活了下来。他躲进驻火星的航天基地疗伤。下一次火星任务要等到四年后，而基地内的补给仅够他维持31天。短暂的绝望后，马克决定利用有限的食物，在这颗空无一人的星球上种植作物，寻找一线生机。与此同时，地球方面也很快发现马克生还的事实，他们想尽办法部署营救计划。孤军奋战的马克，能否等到救援队伍的到来？影片改编自安迪·威尔的同名科幻小说。©豆瓣', '马特·达蒙', '雷德利·斯科特', 8.5, 669382, 'tt3659388', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2280097442.jpg', 0.2, 0.7, 11.6, 48.8, 38.8, '-0.072189,0.341057,-0.714302,0.311051,0.200773,-0.124267,0.377386,-0.086105,-0.101525,-0.100615,0.332708,0.547560,0.047332,-0.124512,0.104447,-0.108488,-0.532920,-0.179026,-0.005923,-0.250578,-0.492295,-0.418828,-0.232400,-0.353611,0.073076,-0.345411,0.825834,0.360726,0.003695,0.460754,-0.153913,0.189240,0.079251,0.567362,0.020351,-0.105819,0.143293,-0.311725,-0.249690,0.434486,-0.175518,-0.179531,-0.032718,0.041093,0.040613,0.481223,0.720443,-0.145846,0.030305,-0.182888,0.044164,-0.511120,0.237432,-0.066980,0.238934,-0.120059,-0.200362,0.017752,-0.073560,0.034207,-0.054733,-0.029215,-0.633050,-0.019970,-0.184888,0.051059,-0.478591,0.215780,-0.326238,0.349967,-0.004046,-0.531109,-0.030954,0.510046,0.090463,0.143872,-0.557849,0.137114,-0.354511,0.057504,0.622339,-0.197636,-0.469249,0.251361,0.055844,-0.450364,-0.086807,-0.154396,-0.238285,-0.098417,0.660945,0.394381,0.077177,0.176498,-0.526519,0.174654,-0.631549,-0.673707,-0.088422,-0.202530,-0.119815,-1.031638,0.373344,0.181981,-0.323062,0.290121,0.081224,-0.145952,0.567679,-0.354064,0.133548,0.634772,0.135002,-0.234145,0.350398,-0.133937,0.233271,-0.441343,0.268430,0.242864,-0.127214,0.577019,-0.022280,0.168724,-0.030428,-0.288534,-0.584290,0.259505', '2369613', '3871833', '2159244', '27073291');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25864124', '亚瑟王：斗兽争霸', '动作', '故事发生在遥远的1500年前，沃提根（裘德·洛 Jude Law 饰）背叛了自己的哥哥尤瑟王（艾瑞克·巴纳 Eric Bana 饰），导致了人类和巫师之间维系了百年的平衡被打破。幸运的是，尤瑟王唯一的后裔逃过了一劫，这令他的血脉并不至于就此断绝。一晃眼15年过去，小小的婴儿被取名为亚瑟（查理·汉纳姆 Charlie Hunnam 饰），成长在社会的最底层，并且对自己的身世一无所知。沃提根杀死了哥哥之后独揽大权，施展自己的铁腕统治手段，一时间民不聊生。一次偶然中，亚瑟拔出了一把深深插进了巨石中的宝剑，在传说中，这把剑只有拥有王室血统的人才能够举起。这一消息很快就传到了沃提根的耳中，亚瑟遭到了逮捕。©豆瓣', '查理·汉纳姆', '盖·里奇', 6.9, 66264, 'tt1972591', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2453433569.jpg', 1.2, 8.6, 42.9, 36.6, 10.8, '0.158026,0.457695,-0.589836,0.527733,-0.054603,-0.047787,0.506474,-0.107548,-0.712861,-0.177562,0.176183,0.789991,-0.131765,0.116530,0.292026,0.040853,-0.066476,-0.793863,0.009508,-0.311932,-0.503473,-0.381365,-0.471657,-0.196930,-0.344598,-0.605439,0.597086,0.171414,-0.435294,0.182880,0.075225,0.431528,0.099225,0.328590,-0.359377,0.241353,0.125935,-0.042634,-0.175084,0.350443,0.046809,-0.421311,0.199475,0.484632,-0.286583,0.385886,0.561568,-0.799808,0.118016,-0.222579,0.333123,-0.320541,-0.319702,0.048270,0.396035,-0.001054,-0.005885,0.249660,-0.390619,-0.037268,0.204011,-0.130798,-0.734648,-0.151841,-0.004735,-0.028283,-0.742880,0.568264,-0.036078,-0.124581,0.028948,-0.300310,0.357585,0.430984,0.367118,0.312519,-0.356474,-0.099561,-0.568457,0.082149,0.690184,-0.354339,-0.522402,0.294806,-0.229516,-0.548884,-0.371669,-0.440306,-0.154509,-0.131257,0.806910,0.258565,-0.204647,0.667447,-0.422118,-0.194066,-0.425371,-0.151727,0.162652,-0.483037,-0.238969,0.032612,-0.258252,-0.402652,-0.289226,-0.094477,0.013929,-0.267541,0.677257,-0.730850,0.255167,0.304177,0.285927,-0.078068,0.566969,-0.076424,0.268531,0.032859,0.057749,0.419424,0.315021,0.266275,0.444231,0.234463,0.015554,-0.160946,-0.274674,0.548669', '1309069', '1303034', '2032339', '19975090');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25864173', '我是谁2015', '喜剧', '李子威（王海祥 饰）是一名平凡的快递员，某日，在送快递的途中，李子威竟然被卷入了一桩命案之中，他所要送达的包裹亦成为了凶徒想要抢夺之物。在紧张刺激的你追我赶之中，李子威遭遇了车祸，醒来后发现自己竟然患上了“脸盲症”，这也就意味着，尽管见过凶手的真面目，但如今的他亦不能分辨此人究竟是谁。在凶手的布局之下，李子威成为了警方重点怀疑的对象，就在这个节骨眼上，收件人楠叔致电李子威，声称拥有能够证明他清白的证据。就这样，李子威带着致命包裹踏上了前往丽江的旅途，途中结识了名为童欣（姚星彤 饰）的游客，两人在误打误撞之中产生了真挚的感情。©豆瓣', '王海祥', '宋胤熹', 3.6, 3274, 'tt4838422', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2247842585.jpg', 50.2, 27.5, 15.9, 3.6, 2.7, '0.410406,0.403800,-0.589441,0.570993,-0.227887,0.121439,0.632311,0.180523,-0.405302,-0.120542,0.409465,0.443220,-0.217044,0.103125,0.145425,-0.016835,-0.052579,-0.506318,0.137518,-0.194554,-0.233071,-0.404714,-0.641257,0.017334,-0.051171,-0.502261,0.463591,0.443180,-0.150636,0.428844,0.104201,0.152994,-0.357327,0.745630,-0.161469,0.212483,0.006145,0.344796,-0.078221,0.494420,-0.047539,-0.538876,0.289524,0.631027,-0.243925,0.288242,0.593248,-0.222836,-0.036368,0.071778,0.393844,-0.171385,0.103886,0.440388,0.320753,-0.033481,0.193670,0.061705,-0.504534,0.074761,0.237903,0.350179,-0.904599,-0.166466,0.175049,0.081964,-0.649125,0.183516,-0.347889,-0.200398,-0.226207,-0.255155,0.258764,0.465561,0.206790,0.311003,-0.034137,0.001894,-0.583452,-0.146645,0.548743,-0.363264,-0.145341,0.092296,-0.158281,-0.568724,-0.052925,-0.088702,-0.166466,0.135227,0.445848,0.105340,-0.153625,-0.138362,-0.307324,-0.124603,-0.237172,0.116697,0.020612,-0.201946,-0.176650,-0.262129,-0.031121,-0.147238,-0.423019,-0.060272,0.150647,-0.433463,0.331451,-0.532621,0.166515,0.665513,-0.096040,-0.506021,0.494811,0.149385,-0.174591,-0.050608,-0.207647,-0.052762,0.330173,0.490296,0.288294,0.450875,-0.059264,-0.203190,0.014365,0.366059', '1851857', '3785918', '1793491', '26747274');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25864719', '嗜人之夜', '动作', '《嗜人之夜》围绕伊托（乔·塔斯利姆饰演）展开，他曾经是一名三合会打手，他的神秘消失在雅加达引发了一场激战。而现在他要保护一位少女，还要逃离前帮派的追杀。', '乔·塔斯利姆', '提莫·塔哈亚托', 6.9, 11193, 'tt6116856', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2535452413.jpg', 2, 9.8, 41.7, 32.1, 14.4, '-0.319524,-0.285394,-0.553462,0.680234,-0.142380,0.156956,1.219398,-0.005236,-0.327333,-0.251564,0.653121,0.663444,-0.088726,0.329608,0.631065,0.073055,-0.057562,-0.736423,-0.324401,0.004057,-0.177733,-0.220540,-0.487546,-0.281094,-0.182941,-0.273685,0.632220,0.234766,-0.384626,0.306777,0.672722,0.222891,-0.541499,0.503527,-0.066716,-0.198616,0.390334,0.015518,-0.062234,0.615661,0.077020,-0.463729,-0.203906,0.228085,-0.169788,0.424234,0.613845,-0.066294,0.277296,-0.325577,-0.000097,-0.699601,-0.043868,0.153484,0.495884,-0.227269,0.038401,-0.251977,-0.098546,-0.303554,-0.130653,-0.307332,-0.615637,0.275081,0.298570,0.139291,-0.677795,0.327197,0.024629,0.303632,0.006467,-0.114377,0.198419,0.614027,0.159957,0.021609,0.260228,-0.042431,-0.501062,0.309288,1.107029,-0.135681,-0.198911,0.205887,0.041982,-0.280152,-0.355322,-0.231869,-0.520241,-0.183018,0.414630,-0.297769,0.038953,0.337024,-0.604758,-0.326924,-0.471097,-0.201723,-0.292118,0.049180,-0.136991,-0.565867,-0.286977,-0.229177,-0.038124,0.428132,-0.429354,-0.226501,0.545591,-0.998935,0.469026,0.765561,0.398221,-0.393091,0.473953,0.179168,0.278502,-0.088923,0.109333,0.447431,0.375299,0.149673,-0.120693,0.189670,-0.201263,0.084960,-0.305638,0.400412', '25828589', '1308755', '1296534', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25866686', '第五波', '动作', '某日，人类赖以生存的家园地球遭到了外星人的猛烈袭击，现代设施和发达科技均遭受到了毁灭性的打击，人类文明仿佛一下子退回了石器时代。凯西（科洛·格蕾斯·莫瑞兹 Chloe Grace Moretz 饰）和弟弟山姆（扎克瑞·亚瑟 Zackary Arthur 饰）在灾难之中失去了母亲，姐弟两人顾不上悲伤，跟随着父亲奥利弗（朗·里维斯顿 Ron Livingston 饰）来到难民营避难。沃斯上校（列维·施瑞博尔 Liev Schreiber 饰）带领着军队来到了难民营，他们带走了孩子们，并且声称之后会回来接遗留下来的成年人，凯西和山姆依依不舍的离开了父亲。山姆心爱的泰迪熊落在了难民营，凯西返回寻找，哪知道外星人拥有了能够寄宿在人类体内的能力，导致难民营中发生了动乱。混乱之中，凯西和山姆失散了，为了寻找弟弟，凯西毅然踏上了充满了危险的旅途。©豆瓣', '科洛·莫瑞兹', 'J·布莱克森', 4.9, 15411, 'tt2304933', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2285035197.jpg', 15.5, 38.1, 35.3, 7.4, 3.6, '0.332307,0.096347,-0.880171,0.236806,0.095009,-0.437355,0.715369,0.048793,-0.518579,-0.082389,0.218791,0.852875,-0.023655,0.181219,0.414094,0.071874,-0.583144,-0.513948,-0.131292,-0.327425,-0.448841,-0.508589,-0.292022,-0.309994,0.079086,-0.611235,0.151864,0.011483,-0.138817,0.538247,0.008658,0.592976,-0.421673,0.413620,-0.190253,0.483574,0.158227,-0.162883,-0.458283,0.359970,0.120456,-0.004100,0.083764,0.149167,0.115218,0.176232,0.824425,-0.447426,0.143556,-0.295313,0.121171,-0.177708,-0.063677,0.312587,0.243029,-0.033265,-0.092021,0.168188,-0.111059,0.222688,0.282377,-0.186578,-0.304787,0.053049,-0.106597,0.078097,-0.711874,0.418253,0.133325,-0.144966,0.272612,-0.370921,0.595751,0.611884,0.073154,0.494490,-0.042616,0.033797,-0.465015,0.015910,0.647907,-0.327689,-0.143364,0.123286,-0.217600,-0.273014,-0.116378,-0.193800,-0.498815,-0.081582,0.601885,0.217566,-0.259940,0.542781,-0.743405,-0.140247,-0.358267,-0.426003,-0.174162,-0.233461,-0.217054,-0.591072,-0.065594,-0.381592,-0.071303,0.353625,-0.329852,-0.007519,0.606525,-0.842972,0.230563,0.448610,0.641076,-0.429763,0.237794,-0.486520,0.195751,-0.082598,0.335268,0.480044,0.090784,0.529062,0.321012,0.117880,-0.167162,-0.002643,-0.307864,0.345397', '1438591', '26393561', '1299433', '1293019');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25867012', '追鹰日记', '剧情', '在阿尔卑斯山的秀丽山谷中，孤独少年邂逅被遗弃的受伤幼鹰，两个年轻的生命被命运绑在了一起，并成为彼此生命中最重要的伙伴，一段少年与鹰的故事就此展开。他们经历了磨合，经历了冒险，同样也经历了大自然的灾难洗礼。在相处过程中，雄鹰逐渐找到了自己的世界，少年也随之成长，最终懂得真正的爱不是拥有而是给它自由！', '让·雷诺', '杰拉多·奥利瓦雷斯', 7.6, 6561, 'tt3532278', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2358657797.jpg', 0.4, 3.6, 31.3, 47.1, 17.6, '0.101260,0.189798,-0.633230,0.572119,-0.258503,-0.273373,0.918601,-0.304498,-0.509700,-0.000778,0.220474,0.820145,0.243584,0.243707,0.263614,-0.440715,-0.014995,-0.819999,-0.012711,0.033816,-0.526400,-0.362583,-0.308420,0.087571,-0.080984,-0.572826,1.195154,0.352700,-0.017423,0.435328,-0.039167,0.011163,-0.323224,0.367530,-0.516028,-0.024720,0.073018,0.358621,-0.564137,0.087280,-0.306502,-0.287191,0.063923,0.205996,-0.355392,-0.086132,1.021669,-0.686103,-0.234988,-0.432000,0.305734,-0.190756,-0.144451,-0.196136,0.269402,0.129164,0.167941,0.424598,-0.012501,-0.072960,-0.221324,-0.219886,-0.858090,-0.062706,0.181523,0.206616,-0.526860,0.646228,0.512471,-0.196552,0.223010,-0.078880,0.257191,0.282998,0.718943,0.259475,-0.272367,-0.115128,-0.238047,0.315803,0.995566,-0.180285,-0.512104,0.734595,-0.663195,-0.572147,-0.207130,-0.481986,-0.471238,0.044819,0.365590,0.450268,-0.671142,0.631362,-0.798696,0.430733,-0.110610,-0.162990,0.058169,-0.694992,0.015949,-0.381241,-0.500644,-0.686716,-0.362504,0.039107,-0.183057,-0.474822,0.883466,-0.787782,0.444847,0.713482,0.238378,-0.258711,0.697250,0.063631,0.506693,-0.339400,0.404330,0.770708,-0.054417,0.169962,0.076172,0.233209,-0.271848,0.499506,-0.771831,0.766880', '26759819', '26759820', '35287908', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25867546', '岳父岳母真难当', '喜剧', '克劳德（克里斯汀·克拉维尔 Christian Clavier 饰）和玛利亚（尚塔尔·罗比 Chantal Lauby 饰）结婚多年，感情十分要好。两人育有四个女儿伊莎贝拉（福德莉奇·贝尔 Frédérique Bel 饰）、奥迪尔（茱莉亚·皮雅顿 Julia Piaton 饰）、赛格利亚（艾米丽·卡恩 Emilie Caen 饰）和劳拉（艾罗娣·方坦 Elodie Fontan 饰），一眨眼，如花似玉的四姐妹都已经长大成人，到了谈婚论嫁的年龄。克劳德和玛利亚是虔诚的天主教徒，两人当然希望他们的女婿能够和自己有着相同的信仰，然而现实却往往不尽如人意，前三个女儿分别爱上了阿拉伯人、犹太人和中国人，老夫妻两将最后的希望放在了小女儿的身上，让两人没有想到的是，小女儿却领着一位非裔黑人站在了他们的面前。©豆瓣', '克里斯蒂昂·克拉维埃', '菲利普∙德∙肖伏隆', 8, 44262, 'tt2800240', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2223293087.jpg', 0.2, 1.3, 20.3, 52.4, 25.7, '0.540528,-0.115902,-0.813125,0.554319,-0.184247,-0.498580,0.987395,0.178361,-0.526714,-0.214375,0.273397,0.947056,-0.159095,0.284568,0.222177,0.391374,-0.511129,-0.764019,-0.051379,-0.232419,-0.292351,-0.728903,-0.260989,-0.024552,-0.366254,-0.198508,0.366181,-0.234284,0.337837,0.629429,0.428226,0.155621,0.102256,0.244672,-0.099273,0.192358,0.280365,-0.068642,-0.228436,0.145985,-0.036117,0.164625,-0.214220,0.166172,0.079677,0.403073,0.435194,-0.225372,0.281971,-0.019878,0.040140,-0.035259,0.099669,0.405805,0.060905,-0.527107,0.359092,0.064879,-0.038121,-0.149366,0.236489,-0.032899,-0.633158,0.342620,0.093020,0.268819,-0.845177,0.732724,-0.382659,-0.414465,0.273231,-0.331406,-0.026601,0.449992,0.041582,0.433377,-0.123933,-0.182663,-0.749184,-0.138000,0.334408,0.257202,-0.444669,0.297278,-0.341759,-0.393119,-0.315612,-0.152938,-0.511010,0.016896,0.415207,0.230146,-0.062786,0.260734,-0.589961,-0.063766,-0.392249,-0.179723,0.292174,-0.540724,-0.038814,-0.530549,-0.144952,-1.036026,-0.634225,0.074412,0.071376,-0.144026,0.929201,-0.748564,0.167904,0.206155,0.323874,-0.316344,0.797957,0.155700,0.134495,-0.312037,-0.001178,0.192934,-0.164000,-0.110880,0.358075,0.441034,-0.008694,0.050664,-0.203907,0.548257', '3111650', '25777634', '26809592', '1769507');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25869868', '女生宿舍', '悬疑', '20世纪30年代，华南医科大学迎来了新的学生。出身优渥的好姐妹夏梦芊（温心 饰）和方慧茹（赵多娜 饰）同被分到传说中闹鬼并死过人而被封闭起来的宿舍415，与她们一同入住的还有神神叨叨勤学卦术的汪子乔（赵美彤 饰）和高贵冷艳自视甚高的何秋岚（王千一 饰）。校园恐怖传说，配合浪漫美好的青涩恋情，让少女们的校园生活充满了别样的乐趣。然而一切急转直下，梦芊无意间撞破秋岚的风流韵事，而后者因匿名举报信跳楼自杀。未过多久，子乔也死于非命。清新的校园生活蒙上恐怖的阴影，一连串恐怖事件的背后，邪恶阴险的阴谋悄然浮出水面……©豆瓣', '温心', '梁婷', 4.1, 8338, 'tt5036516', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2199250458.jpg', 40.2, 31.6, 18.6, 4, 5.6, '0.490355,0.077227,-0.432091,0.428834,-0.078394,0.065081,0.866505,0.105447,-0.551067,-0.147414,0.004004,0.390300,-0.404190,0.329792,0.339271,0.073135,-0.115791,-0.604247,-0.065729,-0.238470,-0.152587,-0.183056,-0.217225,-0.023969,0.083939,-0.380966,0.272935,0.394435,-0.128137,0.673212,0.320966,0.364753,-0.441722,0.261151,-0.213608,0.006676,-0.154388,0.374211,-0.158199,-0.147651,-0.024265,-0.226042,-0.224144,-0.006066,-0.210377,0.185369,0.577720,-0.001681,-0.136722,-0.096314,0.599952,-0.177727,-0.216774,0.264958,0.399116,0.156906,0.230031,0.134396,0.026773,-0.012623,0.122685,-0.131360,-0.549313,0.109025,0.182787,-0.068243,-0.148653,0.624649,0.225657,-0.118861,0.113069,0.016423,0.208536,-0.084874,0.302618,0.489250,-0.074971,0.220231,-0.356347,0.394197,0.351995,0.129289,-0.476054,0.268919,-0.314259,-0.326189,-0.175936,-0.334338,-0.318420,0.067767,0.376174,0.051550,-0.076817,0.326138,-0.705174,0.080395,-0.078346,0.104956,-0.087899,-0.338056,-0.417874,-0.556036,-0.333498,-0.397848,-0.396473,0.150091,0.096089,-0.164190,0.595134,-0.712509,0.337309,0.223773,0.041648,-0.311870,0.502527,0.077054,0.040226,0.052677,-0.277128,0.277055,-0.009729,0.210394,0.051599,0.553571,-0.509955,-0.036112,-0.375716,0.401247', '24839498', '21442760', '26586766', '26967920');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25870084', '重返20岁', '喜剧', '七十岁的老太太沈梦君（归亚蕾 饰）年纪越大，脾气越大，渐渐的，除了管家李大海（王德顺 饰）还愿意留在她的身边，没有一个人愿意与她共处。在儿媳妇杨琴（李宜娟 饰）因压力过大而生病入院后，沈梦君终于被家人送入了养老院，气愤和悲伤之中，沈梦君决定在照相馆里留下自己最后的容颜， 没想到却因此而开启了一段返老还童的奇幻旅程。一眨眼之间，满面皱纹的沈梦君变成了二十岁的妙龄少女孟丽君（杨子姗 饰），重获青春的沈梦君不仅体会到了年轻带来的机遇与活力，更品尝到了爱情的酸涩滋味。然而，就在她沉浸在幸福的幻觉中不能自拔之时，一场意外将她抛到了人生的十字路口之前，二十岁还是七十岁，沈梦君必须做出选择。©豆瓣', '杨子姗', '陈正道', 7.1, 390379, 'tt4344878', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2216353367.jpg', 1.9, 6.1, 39.8, 38.4, 13.8, '-0.037910,0.355334,-0.930910,0.498752,-0.246534,-0.649733,0.995578,0.241906,-0.502874,-0.192211,0.165572,0.643461,-0.363595,0.451795,0.287398,-0.326710,-0.082532,-0.563379,-0.062306,-0.168784,-0.326152,-0.173654,-0.237732,-0.036936,-0.204732,-0.454744,0.619337,0.312406,-0.141698,0.493079,0.190501,0.046230,0.080027,0.601352,-0.273712,0.239654,0.003072,0.110124,-0.157518,0.063843,0.297112,-0.443467,-0.061587,0.188631,-0.218213,0.230821,0.924324,-0.255620,-0.305497,-0.023087,0.437366,-0.120784,-0.279413,0.212673,0.038088,0.002493,0.158090,0.005108,-0.464184,0.018081,0.195837,-0.123729,-0.568854,0.106314,0.075262,0.355917,-0.574833,0.355725,0.094591,-0.287072,0.216387,-0.424545,0.177527,0.109588,0.141634,0.532223,-0.438070,-0.036105,-0.546974,0.447666,0.787154,-0.054775,-0.236308,0.587843,-0.299228,-0.472438,-0.047693,-0.315666,-0.476252,0.147117,0.299222,0.298068,-0.237319,0.249193,-0.372754,0.016633,-0.325322,-0.163506,-0.100512,-0.447146,-0.092848,-0.186530,-0.361146,-0.457140,-0.350626,0.241804,0.245805,-0.369311,0.626883,-0.655055,0.402768,0.333748,0.158976,-0.357872,0.657590,0.181575,0.204601,-0.168247,0.094976,0.300355,-0.386740,0.372455,0.236793,0.346250,-0.483125,0.082828,-0.510607,0.623855', '21619567', '1292211', '21348112', '26245360');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25870236', '可爱的你', '剧情', '吕慧红（杨千嬅 饰）曾经是名校校长，和丈夫谢永东（古天乐 饰）结婚多年，感情依然恩爱如初，幸福美满的两人即将迎来他们的十周年结婚纪念日。吕慧红早早离开了工作岗位，为了半年之后的环球旅行做起了准备，内心里满怀着期待和盼望。一次偶然中，吕慧红得知一所名叫元田的幼儿园濒临倒闭的边缘，而园中仅有小雪（何涴潆 饰）、珠女（王诗雅 饰）、嘉嘉（傅舜盈 饰）、凯蒂（李咏珊 饰）和珍妮（陈丽儿 饰）五个天真单纯的孩子，如果幼儿园倒闭，那么这五个孩子将要面对无学可上的糟糕现实。冲动之下，吕慧红决定成为元田幼儿园的园长，哪知道想要胜任这一职位，需要付出那么多的努力和那么大的代价。©豆瓣', '杨千嬅', '关信辉', 7.9, 43643, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2232074658.jpg', 0.5, 2.6, 24.6, 46.4, 25.9, '0.025897,0.208347,-0.742834,0.238970,-0.021441,-0.173048,0.513346,0.104285,-0.261080,-0.250566,-0.146397,0.608281,-0.071868,0.671424,0.293754,-0.132014,-0.025687,-0.587704,-0.027883,-0.197240,-0.120972,-0.429975,-0.289252,0.058794,-0.066227,-0.142364,0.513620,0.290979,0.449165,0.694870,0.587828,0.044909,0.049597,0.075734,0.077067,-0.153392,0.171825,0.541377,-0.470315,0.163803,0.261830,0.118676,-0.051008,-0.006643,0.163939,0.246501,0.423151,0.033205,-0.268619,-0.252849,0.528208,-0.057304,-0.046289,0.265814,0.178735,0.020836,0.377880,0.307483,-0.428189,0.029401,0.204090,-0.210148,-0.575468,0.068466,0.149220,-0.065629,-0.627942,0.333312,-0.031508,-0.116427,0.340877,-0.341379,0.064231,0.629229,0.293010,0.437441,-0.302874,-0.055559,-0.409183,0.163958,0.652265,-0.183977,0.020134,0.348089,0.096984,-0.203268,0.180831,-0.321991,-0.405888,0.271213,-0.105355,0.252378,-0.232350,-0.009010,-0.249513,0.192145,-0.297441,-0.026423,0.047985,-0.437497,-0.044004,-0.347029,0.061565,-0.325377,-0.340808,0.107610,0.006257,-0.304560,0.830099,-0.834312,0.185882,0.102090,0.594831,-0.552687,0.502300,0.218242,0.239111,-0.223893,0.165336,0.117983,-0.399329,0.115961,-0.171709,0.170096,-0.044973,-0.210291,-0.304669,0.422348', '35030151', '1292219', '25922902', '35048413');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25870483', '它在身后', '悬疑', '19岁的女孩洁依（麦卡·梦露 Maika Monroe 饰）美丽迷人，她憧憬浪漫美好的青春恋情，却未曾想莫大的灾难突然降临。她和男孩休（杰克·威尔瑞 Jake Weary 饰）外出约会，期间休表现出恐慌的一面。在那个迷离的夜晚，燕好之后的洁依遭到休粗暴对待，继而得知休恐 慌的原因。原来一直有一个他人看不见的“人”跟随着休，TA可以变换任何人的容貌，并以杀死休为目标。摆脱TA的方法只有通过性将其转给其他人。自此之后，洁依无时无刻不出在恐慌之中，妹妹凯莉以及好友保罗、雅拉等人为其担忧，可是那看不见的追踪者随时随地出现。TA是洁依无法摆脱的原罪，是投射在灵魂深处的恐怖阴影……©豆瓣', '麦卡·梦露', '大卫·罗伯特·米切尔', 6.4, 26692, 'tt3235888', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2232895531.jpg', 3.6, 13.9, 47.7, 27.9, 6.9, '0.201343,0.026514,-0.817237,0.500551,-0.206185,-0.014487,0.980661,0.005896,-0.468778,-0.145677,0.068458,0.599609,-0.349098,0.274964,0.227665,0.112074,-0.197467,-0.665468,-0.028408,-0.177060,-0.106777,-0.400386,-0.196950,-0.056328,0.092510,-0.545664,0.564269,0.013143,-0.190454,0.439851,0.321279,0.476904,-0.245079,0.660735,-0.021795,-0.107608,-0.220003,-0.046810,-0.402505,0.138267,0.046458,-0.313660,-0.259010,0.220175,-0.406484,0.356879,0.651266,-0.555010,-0.272831,-0.032094,0.428665,-0.140449,-0.163135,0.214290,-0.058480,-0.232156,0.126753,0.087082,-0.308458,0.029746,0.064153,0.018547,-0.858999,0.130575,0.191869,0.240777,-0.342369,0.251641,-0.019786,-0.005865,0.363951,-0.225982,0.089718,-0.002965,0.108528,0.307229,-0.357614,0.171240,-0.360382,0.008864,0.491351,0.043989,-0.510360,0.407597,-0.384260,-0.073880,0.060061,-0.281500,-0.633884,0.184331,0.166578,0.334240,-0.255895,0.294204,-0.293733,-0.237179,-0.355608,-0.043181,-0.143332,-0.500785,-0.425923,-0.235851,-0.228652,-0.447645,-0.375533,0.183155,-0.048956,-0.255066,0.434941,-0.957120,0.309553,0.367444,0.385932,-0.373155,0.554014,0.160834,0.028527,-0.190386,-0.349878,0.422054,-0.071868,0.215932,0.067653,0.266664,0.117300,0.234334,-0.423459,0.534431', '1296370', '3059036', '1308755', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25870679', '罪恶的编年史', '惊悚', '资深刑警崔昌植（孙贤周 饰）新近升职，加上极其器重他的署长跟上层不断美言，崔班长的前途一片光明。谁知正当他春风得意之际，一桩意外突然向他袭来。在和下属饮酒聚餐后，崔昌植乘坐出租回家，不曾想出租车司机将他拉到荒郊野外。对方似乎知道崔班长干过的所有罪恶勾当，一番激烈搏斗后，对方死于崔班长之手。在此之后，他刻意伪装不在场证明，以图瞒混过关。次日一早，受害者尸体竟然被人用吊车悬挂在江南警察局的对面，由此在社会上引起极大震动，而做贼心虚的崔昌植也感觉受到了前所未有的威胁。隐藏在黑暗之中的对手是谁？他究竟想干什么？©豆瓣', '孙贤周', '白云学', 6.8, 6927, 'tt4619940', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2237556168.jpg', 1, 7.8, 50.8, 30.6, 9.9, '0.221275,-0.026210,-0.891147,0.447094,-0.155595,0.048965,0.647013,0.216042,-0.662995,-0.361259,0.298014,0.388412,-0.321295,0.090961,0.189931,-0.383102,-0.194370,-0.480622,-0.014271,0.052844,-0.402127,-0.433182,-0.239148,-0.202974,-0.139415,0.023531,0.156885,0.116284,-0.366514,0.243851,0.464218,0.341726,-0.107597,0.720831,-0.142052,-0.113157,0.183766,0.070779,0.020443,-0.023483,0.046441,-0.702463,-0.162318,0.289260,0.027346,0.287286,0.443537,-0.015348,-0.090172,0.018081,0.132883,-0.265130,0.259370,0.207970,0.433134,0.050275,-0.016350,0.020272,-0.075686,-0.086953,-0.107726,0.114517,-0.466318,0.051650,-0.069664,0.045185,-0.428661,0.258700,0.043990,0.011688,0.037677,-0.119530,0.352911,0.273334,0.059260,0.170139,0.164402,0.056452,-0.426860,0.079686,0.706686,-0.086951,0.001643,0.205192,-0.042799,-0.227197,0.006114,-0.106442,-0.334354,-0.235179,0.332198,-0.047304,0.051679,0.049681,-0.179131,-0.082175,-0.073657,0.050737,-0.193906,-0.320554,-0.030193,-0.334925,-0.101810,-0.299830,-0.101757,0.095222,0.070970,-0.197552,0.350591,-0.799651,0.109506,0.398320,0.075685,-0.418509,0.531194,0.013090,0.012567,-0.121940,-0.051190,-0.197858,0.532159,0.409392,0.297747,0.189165,-0.088981,-0.074787,0.057938,0.204470', '1292064', '1301022', '35073886', '1309125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25872311', '当怪物来敲门', '剧情', '自从妈妈进行化疗开始，少年康纳就每天晚上都做噩梦。梦中总是漆黑阴暗的天气，狂风大作，尖叫声和无论怎么努力都不能紧握的双手让他倍受折磨。他总是做着同样内容的噩梦，直到有一天家里出现了一个不速之客，拥有古老气息的恶魔对康纳说它是由他召唤而来，它要以三个故事交换一个康纳自己真实的故事。康纳并不害怕恶魔，因为他在面对的事——最心爱的妈妈正一步步走向死亡，这是更加恐怖的事情。夜晚让康纳感觉诡异，而他白天的生活也十分难熬。康纳的爸爸离开了他们母子，前来照料他们生活的外婆又与康纳相处的不甚愉快。除此之外，他还必须忍受学校里那些惨淡的日子——老师们夸张的同情以及同学的霸凌。渐渐的，康纳发现恶魔每晚出现的时间都存在一定规律，并且它所讲的意义不明的故事似乎都隐喻着什么，它究竟是死神的使者，还是康纳所期待的出现的奇迹？而康纳一直不愿意与恶魔兑现的故事，其实是他内心深处最黑暗的秘密……', '刘易斯·麦克杜格尔', 'J·A·巴亚纳', 7.2, 45884, 'tt3416532', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2457871671.jpg', 0.8, 5.8, 41.1, 37.9, 14.4, '0.083154,-0.328471,-0.604258,0.533020,-0.117300,-0.036901,1.023130,-0.166451,-0.486880,-0.449859,0.401432,0.632369,0.070780,0.410181,0.057592,0.172128,-0.331834,-0.523728,0.018888,-0.019116,-0.190069,-0.381629,-0.266789,-0.298842,0.136735,-0.306966,0.374058,-0.028897,0.004349,0.199351,0.069229,0.122274,-0.135151,0.761071,-0.152315,-0.269510,-0.066668,0.272906,-0.205396,-0.193789,0.376147,-0.039593,-0.291477,0.362954,-0.161301,0.198156,0.451356,-0.488642,-0.341894,0.041030,0.282172,-0.457334,-0.085783,0.287825,0.081346,-0.064745,0.369231,0.338990,-0.030736,0.121497,-0.223236,0.086631,-0.941717,0.065682,0.029191,0.476118,-0.359547,0.323242,-0.043723,-0.051258,0.458120,-0.357666,0.215384,0.234512,0.397952,0.608452,-0.470973,-0.159544,-0.476119,0.013751,0.782946,-0.123218,-0.443318,0.490175,-0.483444,-0.306729,-0.051590,-0.085726,-0.663201,0.035776,-0.198916,0.054021,-0.364362,0.613680,-0.597816,0.060127,-0.010630,-0.379107,-0.092555,-0.488012,-0.218071,-0.217072,-0.054767,-0.359049,-0.430141,0.080128,0.069559,-0.275576,0.775542,-0.722600,0.509138,0.719776,0.297259,-0.294199,0.542290,0.321001,0.014369,-0.227873,-0.112994,0.352445,-0.103376,0.300479,0.114247,0.290534,0.245098,0.058223,-0.386048,0.746940', '1