INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25872931', '万物生长', '喜剧', '故事发生在20世纪90年代，医科大学生秋水（韩庚 饰）和宿舍好友厚朴（张博宇 饰）、黄芪（杨迪 饰）、辛夷（赵一维 饰）在插科打诨、学习玩乐的过程中，靠写武侠小说赚取零花。他曾有过一段刻骨铭心的初恋，而今则和极度自律的女孩白露（齐溪 饰）享受着校园爱情。意外的邂逅让他结识了充满成熟气息的美人柳青（范冰冰 饰），接下来的一系列事件则让柳青闯入了秋水的人生。他有意无意隐藏着和白露正在交往的事实，另一边则与柳青在暧昧中欢声笑语。青春有甜蜜，青春有懊悔，正因为无法重来一遍，才让每一次的喜怒哀乐都那么刻骨铭心且永生难忘……本片根据冯唐的小说改编。©豆瓣', '范冰冰', '李玉', 5.7, 154025, 'tt4255554', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2236439154.jpg', 7.8, 26.1, 46, 15.1, 5, '0.189234,-0.143200,-0.562130,0.717897,-0.009694,-0.288504,0.973660,-0.063618,-0.615200,-0.149013,0.145848,0.235532,-0.372726,0.312137,0.281494,-0.114411,-0.259958,-0.632696,-0.111609,-0.190010,-0.004643,-0.487981,-0.189711,0.157509,0.028528,-0.262327,0.537109,-0.166767,-0.250911,0.643188,0.206770,0.233230,-0.322288,0.389802,-0.175016,0.226043,-0.002047,0.396686,-0.392872,-0.073610,0.389369,-0.413075,-0.302630,0.017998,-0.118908,0.117004,0.773431,-0.112557,-0.177748,0.338981,0.541251,0.132794,-0.163009,-0.030542,-0.048915,0.262090,0.469306,0.205937,-0.073367,0.027625,0.063190,0.055460,-0.663705,-0.064110,0.391339,0.330398,-0.320325,0.705771,0.047296,-0.034561,0.401135,-0.204500,0.049965,0.221849,0.712383,0.462116,-0.112243,0.007981,-0.316922,0.720237,0.489293,0.318228,-0.083282,0.535266,-0.426920,-0.368752,-0.091212,-0.014151,-0.574881,0.150817,0.301828,0.011962,-0.029352,0.420945,-0.568126,0.265319,0.222651,-0.098140,0.156018,-0.326227,-0.196897,-0.618916,-0.347453,-0.644604,-0.560538,0.081424,0.294908,-0.410544,0.755136,-0.791328,0.301637,0.453199,0.060809,-0.128165,0.615453,0.236344,-0.146683,-0.143791,-0.151207,0.424289,-0.302486,0.321216,0.042344,0.505027,-0.328275,0.137751,-0.664464,0.546511', '24839498', '1296992', '1304989', '4233625');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25875021', '圆梦巨人', '奇幻', '生活在孤儿院的小女孩苏菲（鲁比·巴恩希尔 Ruby Barnhill 饰）总是闷闷不乐。某天的凌晨三点，她独自趴在窗口守望长夜，却无意中见到一个身形巨大的巨人（马克·里朗斯 Mark Rylance 饰）。巨人被发现后惊慌失措，匆忙中抓起苏菲一路飞奔，回到了他所在的巨人国。幸运的是这个被称作好心眼儿的巨人人如其名，他不像其他同类一样以“人豆子”为食，只吃水果和蔬菜，而且他还会把寻找到的美梦送入孩子们的梦想。这也算是对同类暴行的一种补偿。兴许是拥有共同的孤独感和善良，小小的苏菲和高大的好心眼儿慢慢熟络，并彼此信任，他们成为了毫无芥蒂和隐藏的好朋友……本片根据著名儿童文学作家罗尔德•达尔的同名原著改编。©豆瓣', '鲁比·巴恩希尔', '史蒂文·斯皮尔伯格', 6.8, 90471, 'tt3691740', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2386736909.jpg', 1.3, 10.1, 49, 28.7, 10.8, '0.494047,-0.043015,-0.803591,0.491456,-0.208181,-0.156921,0.903527,0.068942,-0.590579,-0.097681,0.222907,0.781652,-0.059082,0.158847,0.118035,0.198631,-0.351498,-0.632206,-0.126729,-0.133776,-0.263989,-0.349274,-0.586631,-0.251780,-0.167956,-0.218130,0.355767,-0.129932,-0.018493,0.534794,0.153499,0.269003,-0.145378,0.473020,-0.340165,0.219564,0.079521,0.094894,-0.038618,0.193580,-0.126908,0.006606,-0.160597,-0.005156,-0.094109,0.388884,0.607198,-0.476330,-0.208048,-0.218413,0.215867,-0.286247,-0.131369,0.173523,0.193156,-0.076249,0.390214,-0.135499,-0.036992,0.201538,0.033223,-0.185057,-0.609667,-0.033226,0.144958,0.241068,-0.772062,0.629177,0.126462,-0.306679,0.432204,-0.359752,0.072418,0.147604,0.153786,0.435008,-0.082429,0.041864,-0.567474,0.061718,0.466556,0.154777,-0.533529,0.330142,-0.209093,-0.470633,-0.055225,-0.053714,-0.426311,-0.197663,0.434380,0.158852,-0.122899,0.177326,-0.776607,0.166055,-0.107504,-0.109590,0.025932,-0.532280,-0.163020,-0.454664,-0.053071,-0.546609,-0.216715,0.054216,-0.033066,-0.345717,0.896196,-0.770365,0.446507,0.397224,0.360969,-0.201583,0.643560,-0.154722,-0.046608,-0.207360,-0.031590,0.339456,0.106208,0.169371,0.208407,0.413468,-0.094653,-0.000456,-0.530086,0.564931', '3111650', '3005387', '1783772', '30162520');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25876760', '少年巴比伦', '剧情', '上个世纪90年代的戴城，路小路（董子健 饰）在一家糖精厂上班，他是个愣头青，不知道未来和生活目标在哪里。跟着一个叫“牛魔王”（尚铁龙 饰）的师傅混，没学会半点技术。在钳工班，除了拧螺丝之外什么都不会。在电工班，也只会换灯泡。除此之外，他还喜欢迟到、打架、翻工厂的院墙，也结识了一帮兄弟们。直到某天，路小路遇见了一个叫白蓝（李梦饰）的厂医，他的人生由此发生了改变……', '董子健', '相国强', 6.7, 39576, 'tt5112400', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2410887742.jpg', 1.6, 10.8, 48, 31.5, 8, '0.282643,-0.456561,-0.617375,0.423839,-0.209216,-0.456500,0.516636,0.084154,-0.148689,-0.221085,-0.173403,0.447719,0.061669,0.247066,-0.033715,-0.338628,-0.206340,-0.352001,0.273639,-0.117570,-0.593232,-0.219981,-0.007310,-0.333825,-0.081648,-0.111427,0.368281,0.199501,-0.159655,0.308897,0.354855,-0.202584,-0.021092,0.218280,-0.563124,0.120181,0.179942,0.351169,0.041470,-0.065624,-0.208505,0.060316,-0.222911,-0.157486,0.249091,0.391557,0.310767,0.207552,-0.214142,0.123496,0.094942,-0.039040,0.009294,-0.156502,0.634637,-0.419006,-0.114387,0.248302,-0.126104,0.159218,0.102125,0.188657,-0.464776,-0.051586,0.034712,0.172904,-0.702309,0.425590,0.073073,-0.416621,-0.173928,-0.427793,0.278434,0.210391,0.036953,0.297177,-0.090678,0.100985,-0.881732,0.248699,0.733481,0.010723,-0.179499,0.568131,0.146790,-0.031322,-0.337400,0.118022,-0.353444,-0.212959,0.117616,-0.357600,-0.542985,-0.262891,-0.319546,0.268899,0.327939,-0.226983,0.191311,-0.250592,-0.306265,-0.306911,0.313340,-0.581089,-0.311235,0.402697,0.012369,-0.198622,0.489615,-0.812937,-0.018902,0.417770,0.140047,-0.708088,1.197881,0.174324,-0.108044,-0.245467,0.097680,-0.199487,-0.023429,0.287619,0.022947,0.697605,0.117475,-0.271692,-0.148055,0.375982', '3055049', '1302384', '2046839', '2124718');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25880244', '一路惊喜', '喜剧', '影片由六个风格迥异的故事组成，讲述一群人在除夕当日发生的一连串奇遇囧事。在新年的前夜，或是团聚、或是旅行，人们选择不同的方式度过这充满仪式感的时刻，而剧中的主角们却在旅程中遭遇着各种意外，有被逼婚的、有流落异乡的、也有暴发户装逼遭“雷劈”的。在一串令人爆笑的旅程意外后，人生的答案充满希望的出现在他们面前，在笑泪相伴的故事背后，却是充满真挚情感的惊喜。', '郭采洁', '金依萌', 5.2, 38213, 'tt4481934', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2223445941.jpg', 16, 31.4, 36.3, 9.3, 6.9, '0.073447,-0.181858,-0.757131,0.673654,0.200637,0.115203,1.262757,0.107126,-0.464900,-0.126156,0.520147,0.849114,-0.660460,0.324830,0.424538,-0.367355,-0.260464,-0.555271,-0.012937,-0.154297,-0.164498,-0.236467,0.159397,-0.163578,0.081073,-0.410807,0.612892,0.309188,-0.451304,0.574662,0.568089,0.420474,-0.318501,0.718932,-0.410053,0.101729,-0.017714,0.555889,-0.180243,-0.151137,-0.078455,-0.258234,-0.460456,0.106969,-0.369414,0.174340,0.869309,-0.355916,-0.268338,0.336652,0.471231,-0.232863,-0.147302,0.012285,0.120731,0.167716,0.101540,0.184732,-0.089986,0.115105,0.220759,0.051986,-1.069859,-0.066575,0.140229,0.480688,-0.326565,0.727415,0.332646,-0.029764,0.351150,-0.288120,0.401000,0.316649,0.644045,0.590645,-0.121579,0.105530,-0.441671,0.151761,0.899430,-0.109960,-0.327899,0.589460,-0.613094,-0.288698,-0.038435,-0.067605,-0.489495,0.096605,0.178516,0.024640,-0.418745,0.623658,-0.726637,0.133369,0.261076,-0.329534,-0.071230,-0.512714,-0.428256,-0.920829,-0.011919,-0.488983,-0.641536,0.180202,0.193330,-0.285269,0.816927,-0.785276,0.294606,0.493262,-0.267302,-0.407828,0.792660,0.490430,-0.031051,-0.238406,-0.183022,0.275286,-0.222034,0.057314,-0.114870,0.400592,-0.287357,0.242920,-0.645236,0.766512', '10466639', '35360296', '3005387', '2053515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25880937', '轻松自由', '喜剧', '塞巴斯蒂安（巴普蒂斯特·勒卡普兰 饰）生命中只有一个心愿：什么也不做。他的世界，就是他的沙发。他并不想维持生活，只想发呆。但今天，如果你什么也不做，那你什么也不是。塞巴斯蒂安的两个室友安娜（夏洛特·勒·邦 饰）和布鲁诺（费利克斯·莫阿蒂 饰）则不断地做 实习打零工，在室友的影响下，塞巴斯蒂安不得不做一点事来改变现状……', '巴普蒂斯特·勒卡普兰', '本杰明·格德杰', 8.3, 46616, 'tt2922440', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2658086366.jpg', 0.3, 1.4, 16.9, 46.2, 35.2, '0.374133,-0.202251,-0.472188,0.671589,-0.518246,-0.324303,0.892726,0.087990,-0.152617,-0.365040,-0.068491,0.733260,-0.059273,0.328545,-0.094984,0.595533,-0.492861,-0.734406,0.424558,0.217071,-0.308618,-0.737785,-0.209613,-0.338871,-0.222356,0.177838,0.578196,-0.128124,0.018654,-0.152647,0.481879,-0.023914,0.309991,0.671480,-0.081223,-0.115768,-0.006063,-0.011014,0.105498,-0.141915,0.494033,-0.276836,-0.279488,0.494103,0.466283,0.390840,0.167743,-0.327414,0.004953,-0.151380,-0.197631,-0.343377,0.269103,-0.130595,-0.335516,-0.639253,0.284434,0.414341,0.027915,0.120772,0.215916,0.115500,-0.905290,-0.078907,0.102145,0.525597,-0.501513,0.423277,-0.372837,-0.291812,0.011988,-0.247287,0.113727,0.537018,0.148341,0.465248,-0.459098,-0.116746,-0.728268,0.102356,0.525978,0.220071,-0.142737,0.739647,-0.335641,-0.217962,-0.307445,0.208109,-0.590288,-0.136216,-0.488330,-0.122819,-0.177818,-0.095957,-0.271512,-0.009766,-0.117336,-0.341746,-0.171656,-0.594377,0.247716,-0.169283,0.463452,-0.556282,-0.547448,0.052024,0.286644,-0.208269,0.387214,-0.741850,-0.110254,0.681203,0.563686,-0.247295,0.560337,0.536756,0.121401,-0.208507,0.040684,0.008790,-0.189241,0.140776,0.324620,0.426157,0.910394,-0.102567,-0.113410,0.852519', '25706773', '1308762', '1949005', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25880986', '食梦者', '喜剧', '擅长画画的高中生真城最高（佐藤健 饰）有一天被头脑灵光的同学高木秋人（神木隆之介 饰）缠上。对方自称超级喜欢漫画，可却没有绘画才能，秋人希望和最高搭档进军漫画界。最高的叔叔川口太郎（宫藤官九郎 饰）曾是小有名气的漫画家，但因过劳和连载被砍最终英年早逝，这让青年深知这一行的残酷性。经不住秋人的怂恿，最高终于就范。两人选择自荐的方式将目标锁定在集英社旗下的殿堂级周刊《JUMP》上，并初步得到了编辑服部哲（山田孝之 饰）的认可。与此同时，天才高中生新妻英二（染谷将太 饰）横空出世，促使两个人不顾一切地要与之一较高低。不知不觉中，他们已经踏入了这个瑰丽精彩却又残酷万分的漫画世界……本片根据创作了超人气漫画《死亡笔记》的大场鸫（原作）、小畑健（作画）的同名漫画改编。©豆瓣', '佐藤健', '大根仁', 7.7, 29618, 'tt3715854', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2253403387.jpg', 0.4, 2.4, 27.6, 50.1, 19.5, '0.205282,0.104330,-0.402810,0.739011,0.196170,-0.136028,0.380032,0.121560,-0.275013,-0.494521,0.188881,0.843739,-0.265099,0.126547,0.256968,-0.221375,0.005165,-0.704434,-0.220026,-0.220709,-0.016863,-0.395757,-0.282531,0.209204,-0.385265,-0.181282,1.111140,0.073625,-0.443473,0.469518,0.511371,0.384714,0.044913,-0.108920,-0.107648,0.092305,0.260707,-0.035439,-0.093218,0.197153,-0.081569,-0.267913,0.014283,0.331296,-0.064944,0.091348,0.758443,-0.317074,-0.156893,0.002842,0.587868,-0.326058,-0.246151,0.040639,0.400623,-0.039702,0.176401,0.200292,0.014035,0.073280,-0.130448,-0.098858,-1.038321,-0.086573,0.335637,0.076185,-0.346714,0.297874,-0.106440,-0.291888,0.098589,-0.100097,-0.097756,0.052812,0.477354,-0.009228,-0.084295,0.041217,-0.110691,0.305181,0.307852,0.099523,-0.079381,0.470954,-0.040645,-0.482875,-0.366567,-0.562328,-0.219681,0.090697,0.167043,0.171902,-0.000824,-0.044307,-0.585593,0.013074,-0.038499,-0.130468,0.171350,-0.310355,-0.107588,-0.636871,-0.051767,-0.400281,-0.271465,-0.042442,0.182390,-0.416176,1.101133,-0.836949,-0.037257,0.388262,0.272248,-0.249095,0.751333,0.132741,-0.285265,-0.174610,0.029529,-0.028780,0.215840,0.284299,0.008597,0.408200,-0.030748,-0.484767,-0.686301,0.539054', '27602116', '26759820', '35262731', '1920765');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881247', '边境杀手', '剧情', '在美国与墨西哥的边界有一块灰色地带，那里是毒贩和杀手们的天堂，他们在此交易火并，完全视法律为无物。凯特（艾米莉·布朗特 Emily Blunt 饰）是联邦调查局的探员，心里怀揣着惩奸除恶的正义理想，她来到此地，加入了联邦政府特种部队，成为了马特（乔什·布洛林 Josh Brolin 饰）的部下。亚历桑德罗（本尼西奥·德尔·托罗 Benicio Del Toro 饰）是曾经卧底在毒枭身边的前任特工，马特找到了他，希望经验丰富的他能够成为行动小组的战略顾问，然而亲历过地狱的亚历桑德罗完全不按常理出牌，他的所作所为时常刺激着凯特脆弱而又敏感的神经。随着调查的深入，死亡的气息笼罩着行动组内的每一个人，一次又一次与死神擦肩而过，凯特的三观开始发生动摇。©豆瓣', '艾米莉·布朗特', '丹尼斯·维伦纽瓦', 7.7, 130100, 'tt3397884', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2263976596.jpg', 0.6, 3, 27.3, 49.4, 19.7, '0.441973,-0.002777,-0.782817,0.583437,-0.191904,-0.238150,0.753096,0.231256,-0.626718,-0.002106,0.338343,0.690397,-0.155236,0.031532,0.286077,0.157549,-0.393295,-0.837064,-0.239921,-0.228803,-0.158910,-0.549785,-0.431574,-0.243136,-0.052734,-0.380892,0.661313,0.052363,-0.197515,0.337105,0.270359,0.457619,-0.044174,0.370617,-0.139954,-0.147081,0.197867,-0.186063,-0.364840,0.007189,-0.022925,0.012287,-0.166210,0.209514,0.019131,0.478308,0.477798,-0.435780,0.056660,-0.101855,0.373263,-0.443862,0.153617,-0.076834,0.324687,0.077240,-0.004538,0.228458,0.157537,0.186290,0.047965,-0.094897,-0.889377,-0.122627,-0.080298,0.560009,-0.656402,0.288449,-0.388671,0.001931,0.126465,-0.315017,0.118108,0.307271,0.323809,0.164645,-0.023298,-0.175812,-0.513192,-0.043937,0.762842,-0.032405,-0.464965,-0.016391,-0.434416,-0.504863,-0.088726,-0.089901,-0.245343,-0.144117,0.306807,-0.079766,-0.091999,0.315396,-0.603982,-0.021987,-0.256378,-0.184996,-0.143418,-0.343152,0.058483,-0.738129,-0.228341,-0.480565,-0.311384,0.087016,0.019261,-0.151204,0.474310,-0.888498,0.283568,0.842043,0.311388,-0.241298,0.616635,0.219347,0.139902,-0.178680,-0.067426,0.417142,0.206733,0.394298,0.158204,0.390202,0.031502,0.002978,-0.137125,0.228027', '1307442', '1793491', '25828589', '1947080');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881535', '信长协奏曲 电影版', '喜剧', '懵懵懂懂的21世纪日本高中生三郎（小栗旬 饰），在意外穿越了时空后，居然来到了风起云涌的战国时代。不知为何和他长得一模一样的织田信长与之交换了身份，从此三郎便以一代霸主的尊荣行走战国。历经无数磨难，他逐渐取得家臣的信任和爱戴，而斋藤道三的女儿归蝶（柴崎幸 饰）似乎也对他用情更深。然而在得知自己死期临近之际，三郎内心倍受打击，历史看似无法逆转。与此同时，羽柴秀吉（山田孝之 饰）和真正的织田信长——明智光秀（小栗旬 饰）合谋，正准备断送第六天魔王的霸业。所谓的本能寺之变一天天临近，三郎的命运以及战国的命运到了最终决断的时刻……本片根据石井あゆみ的漫画原作改编，该漫画在“2012年全国书店店员强烈推荐”榜单中位列第7名。2014年作为富士电视台开播55周年纪念作品推出真人日剧，本片是该剧的电影版。©豆瓣', '小栗旬', '松山博昭', 7, 8791, 'tt4122254', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2276314726.jpg', 1.3, 7.1, 45.1, 32.9, 13.6, '-0.199542,0.137510,-0.529585,0.680306,0.329522,-0.225135,0.366426,0.188619,-0.353570,-0.365801,0.377371,0.793341,-0.368138,0.239961,0.433339,-0.137940,-0.030835,-0.790585,-0.300738,-0.266148,0.060692,-0.243002,-0.445185,0.005177,-0.281990,-0.182202,0.948530,0.221608,-0.055921,0.304957,0.318294,0.356668,-0.237415,0.276855,-0.111469,0.240731,0.114289,0.099946,-0.395253,0.069205,-0.120004,-0.528636,-0.282388,0.217685,-0.202799,0.259026,0.696869,-0.515858,-0.140479,-0.190062,0.626683,-0.078296,-0.449613,0.108181,0.508738,0.051791,0.016704,0.346727,0.016896,0.057155,-0.093418,-0.162283,-0.505685,-0.154231,0.141776,0.169564,-0.465854,0.621059,-0.215103,-0.127872,0.147643,-0.401019,0.100768,0.309888,0.481778,0.313570,-0.179048,0.019935,-0.192704,0.381845,0.499399,-0.007554,-0.167953,0.357733,0.091573,-0.401775,-0.285598,-0.402288,-0.478927,0.020101,0.240652,0.112545,0.162191,0.439277,-0.375039,-0.148609,-0.138441,-0.155173,0.319094,-0.330314,-0.034140,-0.500830,-0.334107,-0.575313,-0.152130,0.190474,0.307920,-0.298631,0.927837,-0.726183,0.050639,0.259929,0.045132,-0.444852,0.474151,0.106174,-0.156866,-0.258270,-0.001193,0.248241,-0.141510,0.258149,0.067263,0.235674,-0.115251,-0.384238,-0.351983,0.458249', '25880986', '27602116', '3811356', '25863940')