INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881611', '战神纪', '奇幻', '少年铁木真(陈伟霆 饰）身为部落首领之子，年幼丧父，母亲独自将他抚养成人，铁木真成人之际返回翁吉剌部落迎娶自幼定有婚约的孛尔帖（林允 饰），谁知途中却逐步陷入叔父（赵立新 饰）设置的杀戮陷阱，而青梅竹马的恋人孛尔帖也在新婚之夜被另一部落首领忽出鲁（胡军 饰）掳走，铁木真在好兄弟札木合（李光洁 饰）的支持与萨满长老的辅佐下，踏上拯救恋人和守卫草原的征途……', '陈伟霆', '哈斯朝鲁', 3.4, 13639, 'tt7473390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2519726014.jpg', 64.5, 18.5, 5.7, 3.2, 8.2, '0.107271,0.387501,-0.506646,0.710240,0.319221,-0.131700,0.615750,0.367874,-0.242819,-0.444728,0.383153,0.650497,-0.038756,0.357128,0.517089,-0.034171,-0.233029,-0.600705,-0.221278,-0.137449,-0.329879,-0.459009,-0.056884,-0.108813,-0.241571,-0.531106,0.855414,0.121959,0.030253,0.581194,0.385944,0.260176,-0.364811,0.389452,0.037648,0.335320,-0.084325,0.050727,-0.293785,0.011541,-0.251744,-0.297875,0.015503,-0.311309,-0.159773,0.423205,0.799385,-0.793434,0.521095,-0.536378,-0.020526,-0.232422,0.311558,0.003144,0.531332,-0.204891,0.098954,0.368479,0.039418,-0.209581,0.013494,-0.257944,-0.194490,0.043741,0.423740,-0.060459,-0.822667,0.199703,-0.185277,0.234369,0.087077,-0.325736,0.036224,0.708372,0.206015,0.343549,0.082006,0.253855,-0.310027,0.178014,0.707458,-0.041577,0.082745,-0.542468,0.077583,-0.779136,0.262075,-0.211569,-0.306853,-0.036581,0.700139,-0.055884,0.252495,0.257429,-0.384796,-0.349409,-0.202789,0.357347,0.551964,-0.343440,0.102975,-0.320980,0.216403,-0.312432,-0.203703,0.204192,0.366886,0.004723,0.507171,-0.552823,0.175980,-0.162603,0.490537,-0.427184,0.738154,-0.100667,0.379850,-0.250228,0.019748,0.492688,0.411766,-0.000936,0.372048,0.019833,-0.325232,0.290966,-0.392795,0.225104', '1918648', '1780122', '1307200', '1303390');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881615', '超凡战队', '动作', '五个在校园被孤立的高中生，因为青春的荷尔蒙面临着许许多多的烦恼与迷茫。同时，黑暗势力丽达女王正蠢蠢欲动，为了寻找更多能量打造金人怪兽哥达来到地球。五名青少年命中注定地相遇，团结克服难关成为五色超凡战队，与他们的恐龙佐德人机合一雷霆出击拯救世界，毁天灭地一触即发……', '戴克·蒙哥马利', '迪恩·以色列特', 4.5, 20413, 'tt3717490', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2441013548.jpg', 19.5, 43.9, 30.5, 4.7, 1.4, '0.102817,0.140228,-0.787326,0.333442,-0.033130,0.009638,0.825322,0.150176,0.081101,-0.137759,0.290143,0.481572,-0.202849,0.243031,0.284684,-0.599331,0.067338,-0.744502,-0.154036,0.135793,-0.043992,-0.201277,-0.416097,-0.304823,0.122853,-0.752760,1.183256,0.504884,-0.296557,0.153561,0.011895,0.431176,-0.382273,0.251210,-0.148608,-0.539006,-0.115126,0.035967,-0.450715,0.129784,-0.448252,0.025485,-0.157755,0.180244,-0.205433,-0.419494,0.938332,-0.499411,0.379319,-0.522005,0.175373,-0.427849,-0.162786,-0.156946,0.429719,0.019236,0.031102,-0.178277,0.310781,0.110076,0.072195,-0.129545,-0.943176,0.109584,0.063002,0.338595,-0.259997,0.274111,0.297237,-0.249127,0.469453,-0.033071,-0.210046,0.640135,0.452783,0.402631,-0.284882,0.274925,-0.538649,-0.245619,1.020639,-0.109705,-0.404402,-0.142798,-0.151177,-0.325800,-0.531102,-0.175804,-0.424421,-0.303376,0.533811,0.214454,0.077734,0.726847,-1.191324,0.239960,-0.132467,-0.293250,0.022085,-0.507544,-0.104243,-0.754861,-0.091822,-0.154277,-0.268962,0.315607,0.521498,-0.249073,1.085880,-0.678688,0.117740,0.668752,0.451801,-0.573821,0.495152,0.001998,0.118618,-0.566165,-0.175605,0.366523,-0.051186,0.391481,-0.021640,0.223827,-0.416479,0.557683,-0.596232,0.487028', '26290398', '26667010', '3001114', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881628', '幸存的女孩', '喜剧', '文静少女麦克斯（泰莎·法米加 Taissa Farmiga 饰）和妈妈（玛琳·阿克曼 Malin Akerman 饰）相依为命，她的妈妈是一位小有名气的B级恐怖片演员。虽然妈妈一直希望闯出名头，但是却命运多舛，始终名不见经传。在一次失败的试镜过后，麦克斯和妈妈遭遇一场严重的车祸，而妈妈也在这场灾难中去世。三年后，母亲的忌日当天，一群好友约上麦克斯去影院重温妈妈的经典营地恐怖片。可是观影途中突发意外，大火引起莫大的混乱。当麦克斯再度醒来时，发现自己和好友竟然穿越来到了母亲的电影之中。随后的九十多分钟里，他们将随同逝去的母亲一同经历可怕的营地血腥大屠杀……©豆瓣', '泰莎·法米加', '托德·施特劳斯-舒尔森', 6.7, 15422, 'tt2118624', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2271640652.jpg', 1.8, 10.4, 48.6, 31.3, 7.8, '0.108626,0.023339,-0.725333,0.200710,0.250790,-0.385944,0.941322,-0.189002,-0.709198,-0.406109,0.412242,0.936512,-0.326215,0.433300,0.321348,-0.064490,-0.360619,-0.624706,-0.097964,-0.076464,-0.307766,-0.181975,-0.305004,0.196302,0.171577,-0.407326,0.393394,0.122766,-0.041541,0.807942,0.172731,0.124202,-0.276185,0.354955,0.094008,0.282989,0.198546,0.332559,-0.305513,0.279682,0.083979,-0.277406,-0.284141,0.123520,0.132035,0.242574,0.634235,-0.250999,-0.175359,-0.018284,0.515139,-0.211011,-0.324280,0.152555,0.372349,0.143247,0.637436,0.117939,-0.001361,-0.043802,-0.376170,-0.004305,-0.492683,0.217017,0.122702,-0.075665,-0.483922,0.404623,0.036881,-0.048519,0.335450,-0.146487,0.120944,0.323751,0.259672,0.523075,-0.443401,0.086441,-0.167382,0.290069,0.829383,-0.141552,0.037442,0.239191,0.077702,-0.209100,0.113135,-0.242577,-0.628631,0.564145,0.170550,-0.216712,-0.135069,0.391023,-0.566802,0.049238,-0.472401,-0.187442,-0.155419,0.082112,-0.316834,-0.611632,0.016660,-0.248427,-0.322962,-0.003588,-0.127493,-0.226083,0.595664,-0.584658,0.637692,0.300914,0.207830,-0.217286,0.650064,0.126755,0.208246,-0.274702,0.213040,0.336024,-0.203010,0.211346,0.156984,0.071778,-0.093789,-0.158480,-0.477595,0.325812', '1296534', '26687241', '2365260', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881778', '我要我们在一起', '剧情', '你有没有爱过一个人，曾经拼了命，只为和TA在一起。十年前，差生吕钦扬当众告白凌一尧，两人从校园步入社会，为了让她幸福，他不惜以命相搏。然而金钱、房子、婚姻等现实的考验，却将两人越推越远。十年长跑，他们能否还记得曾经刻在心底的约定：我要我们在一起。电影改编自长帖《与我十年长跑的女友明天要嫁人了》。', '屈楚萧', '沙漠', 6, 122067, 'tt14546082', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2872957602.jpg', 5, 20.1, 50.8, 19.7, 4.4, '-0.190156,-0.004313,-0.688426,0.635705,-0.084548,-0.723358,0.499826,-0.186440,-0.157182,-0.090874,-0.071804,0.677309,-0.101925,0.133527,-0.046158,-0.032486,-0.111794,-0.938867,0.000410,-0.403760,-0.392430,-0.329238,0.243752,-0.169084,-0.179908,-0.105189,0.695283,0.120381,0.089019,0.348628,0.274048,-0.275586,-0.290561,0.136310,-0.524222,-0.260924,0.096869,0.429064,-1.007693,0.116637,0.239318,-0.233776,-0.252238,-0.094758,0.016811,-0.313637,0.387450,0.324082,-0.213287,0.369828,0.279198,-0.266984,-0.166570,0.192200,0.003201,-0.421188,0.440914,0.636518,0.014804,-0.262168,-0.027398,-0.399529,-0.645655,0.089626,-0.345399,-0.398120,-0.692155,0.915358,-0.042708,0.292481,0.630525,-0.008776,-0.057295,0.467476,0.269954,0.347957,-0.589974,-0.343026,-0.552303,0.603189,1.131259,-0.149767,0.207670,0.367583,0.166017,-0.314141,-0.358972,-0.016040,-0.679953,0.282725,0.283954,-0.227710,-0.705372,0.078102,-0.502886,0.065337,-0.107256,-0.032811,0.515877,-0.529989,0.126814,-0.215397,-0.285827,-0.408797,-0.372065,0.093396,0.163727,-0.564705,0.607102,-0.779591,0.545939,0.835089,0.581821,-0.832953,1.082323,0.740734,-0.044369,-0.120046,0.325942,0.205029,-0.340046,0.478587,0.207612,0.233597,0.235878,0.519161,-0.692475,0.832160', '2080130', '1308804', '1308035', '5985887');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881780', '命中注定', '喜剧', '少女时期的方圆经历了两次算命结果命中注定她未来的爱人叫宋昆明。长大成年后的方圆在即将与谢明江结婚前却意外接到宋昆明的电话。于是，方圆不顾一切地追到意大利，随后在异国他乡展开了一段充满戏剧性的寻爱之旅。', '汤唯', '张皓', 5.8, 59798, 'tt4819544', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2253231009.jpg', 6.2, 24, 47.7, 16.5, 5.5, '-0.009810,0.196457,-1.078677,0.939962,0.132065,-0.254964,0.710780,-0.454823,-0.164367,-0.131496,-0.434797,0.769189,-0.445537,0.651010,0.526476,-0.439023,0.070430,-0.999056,-0.437346,-0.417447,-0.526457,-0.393908,-0.069942,-0.015190,0.200046,0.271262,0.194593,0.377766,0.008501,0.564358,0.266644,0.144599,-0.163501,0.684811,-0.217633,0.532087,0.171117,0.480034,-0.449714,-0.037770,0.305440,-0.340565,0.064523,0.023213,-0.090560,0.333010,0.727520,-0.113750,-0.305420,-0.247761,0.455673,0.049458,0.046903,0.047385,0.325928,0.010614,0.346976,-0.082383,-0.228564,-0.062168,0.101351,-0.188450,-0.065383,0.081512,-0.083525,-0.522056,-0.483750,0.266330,0.147132,0.367202,0.038896,-0.449444,0.132568,0.709133,0.319747,0.416161,-0.114260,0.452401,-0.297566,-0.059450,0.845142,-0.054842,-0.534445,0.109499,0.237533,-0.529245,-0.005818,0.278570,-0.415989,0.050822,0.470673,-0.094480,0.113667,0.082957,-0.500237,-0.223060,-0.278006,-0.105891,0.256912,-0.208760,-0.493418,-0.279189,-0.014563,-0.579467,-0.521389,0.380317,-0.069332,-0.115928,0.175850,-0.627176,0.324660,0.216430,0.003531,-0.555579,0.646017,0.222678,0.347399,-0.356974,0.532659,0.774906,-0.282090,0.826950,0.393552,0.199881,-0.270585,0.177853,-0.592837,0.654607', '25786077', '34461680', '25858759', '4832825');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25881781', '纽约纽约', '剧情', '上世纪90年代的上海，许多人都为出国狂热。路途（阮经天 饰）是最年轻的五星级酒店领班，处事精明、为人仗义，无论是手下阿坤（杨旭文 饰）等一众小弟，还是打算开娱乐城的金小姐（叶童 饰），都对路途很是信任。从美国归来的精英商人米先生（苗侨伟 饰）更是看中他，邀请他担任纽约新酒店的负责人。为了去纽约，许多人怀着不同目的来接近路途，其中也包括令路途着迷的女孩阿鹃（杜鹃 饰）。纽约梦能否如愿以偿？路途和阿鹃的爱情又将何去何从？一段在欲望都市中关于选择的爱欲纠缠，就此展开……©豆瓣', '阮经天', '罗冬', 5.5, 17829, 'tt5576336', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2324916383.jpg', 10, 30.3, 41.4, 13.3, 5, '-0.082865,0.043954,-0.532731,0.518675,-0.076396,-0.297337,0.429052,0.159886,-0.585985,-0.266208,0.217877,0.665978,0.120947,0.091076,0.527829,-0.021797,-0.264490,-0.312355,-0.109905,-0.406892,-0.229818,-0.317380,-0.124715,-0.110473,-0.035263,-0.166704,0.483935,0.371139,-0.133827,0.542680,0.499560,0.332928,-0.240166,0.468727,-0.300071,-0.246351,0.050994,0.118246,-0.566848,-0.084404,-0.155577,-0.117184,-0.143908,-0.047985,0.189957,0.159550,0.695601,0.148291,-0.056990,-0.025950,0.221715,-0.132149,0.207261,-0.145756,0.369277,0.043012,0.340849,0.367734,-0.210924,0.007317,-0.057074,-0.111242,-0.716375,0.196148,0.477044,-0.030857,-0.638475,0.403232,-0.162768,-0.072329,0.210027,-0.276996,0.144017,0.190128,0.286503,0.188901,0.272281,0.039994,-0.334606,0.227926,0.840486,0.197162,0.200769,0.220229,-0.193086,-0.530534,0.052122,-0.173717,-0.407980,0.073602,0.111244,-0.031349,-0.056278,0.029855,-0.459419,0.131866,-0.059420,-0.181850,0.251823,-0.490015,0.054754,-0.645658,0.152163,-0.419903,-0.064170,-0.013334,0.207734,0.144606,0.790198,-0.639236,0.108340,0.508090,0.418263,-0.681704,1.071391,0.107967,0.065949,-0.312236,-0.195216,0.166254,0.041312,0.060741,-0.392805,0.262119,-0.208374,-0.332930,-0.383810,0.221659', '26646649', '3055049', '4301278', '2080130');
