INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25882279', '有一天', '剧情', '影片由9个温暖励志的小故事组成，讲述9个弱势儿童群体追梦的故事。9个故事分别关注的是：贫困儿童、读写困难儿童、智障儿童、被拐卖儿童、盲童、肥胖儿童、聋哑儿童、少数民族留守儿童、服刑人员子女。《有一天》包含的九支短片：《独唱乐团》-聋哑儿童 他们住在寂静无声的世界里， 却能唱出最纯粹的歌。《疯狂的面包》-智障儿童 他们终其一生都无法长大，但他们也拥有自己的悲伤快乐。《回家的路》-被拐卖儿童 他们现在流落街头，但他们也曾是父母心头的宝贝。《看不见的画》-视力障碍儿童 他们住在黑暗无光的世界里，却可能比我们看到更多。《小笨蛋日记》-读写困难儿童 他们不会读课文，不会写作业，却可能是个小天才。《太阳会飞》-服刑人员子女 他们的父母在接受惩罚，但他们依然值得被疼爱。《小小电影院》-贫困儿童 他们的生活中少有光影故事，但他们依然有权利放飞梦想。《秋扎》-肥胖儿童 他们的生活或许沉重，但如果给他们多一些关注，他们也会散发光彩。《礼物》-留守儿童 他们的语言已经行将消失，但他们的文化依然是不一样的烟火。', '周迅', '李睿珺', 7.4, 6171, 'tt4051858', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2198749463.jpg', 2, 4.8, 34, 40.4, 18.9, '0.329874,-0.301266,-0.588546,0.530850,-0.172284,0.167006,0.878219,0.029895,-0.533193,-0.253802,0.206469,0.726992,0.256680,0.440473,-0.382027,-0.097332,-0.290892,-0.400351,0.116808,-0.188825,-0.144018,-0.417672,-0.125329,-0.364952,-0.258965,-0.112811,0.512411,0.076918,-0.056434,0.270712,0.056754,-0.085343,-0.103125,0.158581,-0.381315,-0.061548,-0.087599,0.096274,0.056202,-0.047536,-0.074807,0.030316,-0.131490,-0.022774,-0.026180,0.201028,0.870289,-0.146650,-0.115872,0.034157,0.263564,-0.224322,-0.288427,0.238074,0.084225,-0.024243,0.460558,-0.017149,0.117555,0.160233,-0.217091,-0.175583,-0.740513,0.104631,0.218870,0.391790,-0.372740,0.540014,0.231011,-0.192826,0.114671,-0.209606,0.260118,-0.059361,0.359003,0.618242,-0.135855,0.141047,-0.583399,0.302630,0.635124,-0.188347,-0.578700,0.410279,-0.956212,-0.491992,-0.122931,-0.387546,-0.648404,0.278141,0.173300,-0.033436,-0.602799,0.329177,-0.412532,0.244511,0.032594,-0.155025,-0.296634,-0.437619,-0.185427,-0.297963,0.135728,-0.405689,-0.364804,0.182687,0.272153,-0.300316,1.337028,-0.707542,0.266164,0.522117,0.254774,-0.606806,0.838946,0.165350,0.007326,-0.025779,-0.093310,0.449511,-0.175971,0.157750,0.041947,0.150395,-0.109866,-0.058661,-0.238204,0.496928', '26348103', '24284209', '27602116', '26283288');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25882296', '狄仁杰之四大天王', '动作', '狄仁杰（赵又廷 饰）大破神都龙王案后，高宗（盛鉴 饰）御赐神器亢龙锏，遭天后武则天（刘嘉玲 饰）嫉妒，天后为盗取亢龙锏陷害狄仁杰，召集了一帮会方术的“异人组”图谋不轨，并命令尉迟真金（冯绍峰 饰）带队。狄仁杰在医官沙陀忠（林更新 饰）的帮助下成功摆脱“异人组”迫害，并和尉迟真金商议和解，与此同时“异人组”刺客水月（马思纯 饰）却发现都城出现不明势力，在狄仁杰周旋于武则天的埋伏时，大唐陷入更深的危机，“封魔族”携异术登场，一场“屠魔”大战即将爆发……©豆瓣', '赵又廷', '徐克', 6.1, 259801, 'tt6869538', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2526405034.jpg', 4.2, 18.8, 49.4, 23, 4.7, '-0.146416,0.146615,-0.276337,0.511357,0.529584,0.091594,0.494963,0.372894,-0.531602,-0.390334,0.601045,0.206439,-0.426184,-0.075609,0.306548,-0.335387,-0.367805,-0.565534,-0.050912,0.115437,-0.171481,-0.282656,-0.220498,-0.125038,-0.208742,-0.318572,0.550183,0.297185,-0.151290,0.505700,0.572720,0.051417,-0.281188,0.555556,0.291972,0.033224,-0.006486,0.170672,-0.393018,0.242723,-0.376996,-0.474239,-0.307296,0.201180,-0.046048,0.241539,0.187880,-0.530015,0.270170,-0.345138,0.276011,-0.213670,-0.042209,0.148177,0.284275,0.251032,-0.105997,0.308554,-0.182532,0.304976,0.129856,0.118885,-0.595320,0.126399,0.236559,0.056798,-0.180749,0.233215,-0.208601,0.147947,0.021375,0.003298,0.315890,0.690345,0.365318,-0.098471,-0.127006,-0.122226,-0.464880,0.305639,0.181833,-0.208043,0.292510,-0.263820,0.338153,-0.623656,-0.165855,0.107041,0.241640,-0.225381,0.517785,0.121629,0.308032,0.266656,-0.242659,-0.406211,-0.060811,0.250284,0.086575,-0.102915,0.157287,-0.759756,-0.057709,-0.092135,-0.165592,0.202193,0.425090,-0.053664,0.228368,-0.470146,0.144489,0.015255,0.232356,-0.719075,0.232189,0.151225,-0.081856,-0.109768,-0.423106,0.288623,0.316529,0.168479,-0.085422,0.057845,-0.196183,-0.232561,-0.214150,-0.006561', '25723905', '1292287', '6517421', '26996640');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25882861', '危楼愚夫', '剧情', '管道工接到报告说某个住满底层群众的筒子楼水管崩裂，去勘察时发现大楼豆腐渣工程即将在24小时内倒塌，于是通过母亲好友联系到女镇长，女镇长和手下考虑了自身利益，又经扶植女镇长上位的经济操手怂恿，大家决定放弃转移大楼中的820名住客并暗中杀害了两个头头当做替罪羊。其中被杀的 负责建筑的头临死替管道工求了情，允许他闭嘴带着家人远走他乡，管道工心中良心未死，不听父母及妻子的劝告执意去救人……', '阿尔焦姆·贝斯特罗夫', '尤里·贝科夫', 8.4, 72666, 'tt3560686', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2253299818.jpg', 0.3, 1.2, 12.9, 48.7, 37, '0.144856,0.015562,-0.525677,0.176171,-0.250177,-0.263427,0.424040,0.198330,-0.433485,-0.331303,0.144214,0.455550,0.142996,0.169011,0.169542,-0.228453,-0.423761,-0.349447,-0.162631,-0.195472,-0.287412,-0.489704,0.444707,-0.181111,-0.186860,0.018514,0.337567,0.097188,-0.172561,0.186082,0.266726,0.180699,-0.200843,0.238098,-0.080111,0.106757,0.033112,-0.376549,-0.435626,0.172385,-0.196333,-0.022543,-0.102390,-0.073349,-0.005525,0.575412,0.312577,-0.059978,-0.064823,-0.191842,0.292284,-0.246502,0.200443,0.338679,0.574134,0.236843,0.249983,0.463266,-0.352739,0.042227,0.136334,0.011647,-0.535201,-0.135377,0.086728,-0.013848,-0.770369,-0.022895,0.041062,0.090249,0.062594,-0.075705,0.431397,0.149643,-0.161588,0.455798,-0.225916,0.180834,-0.264997,0.034738,0.561750,-0.136438,0.260552,-0.326863,0.270544,-0.152735,0.382621,-0.064815,-0.304932,-0.321423,0.149551,0.244805,-0.176828,-0.121738,-0.338022,-0.364951,-0.337637,-0.163548,0.114857,-0.693756,-0.116313,-0.534859,-0.135035,0.377817,0.243047,0.222595,0.191742,-0.148069,0.473186,-0.670926,-0.016122,0.385463,0.666948,-0.778611,0.536390,0.262814,0.245700,-0.178482,-0.058812,-0.078845,0.354685,0.650262,0.001023,-0.145456,-0.123646,-0.448657,-0.259516,-0.248873', '1417543', '1428876', '1421278', '2990737');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25884416', '麦兜·我和我妈妈', '喜剧', '在城市的破败角落，脑顶光秃秃的重案组老警察入职三十年，虽然破了许多大案要案，满身都是伤痕弹孔，但是他的家庭情况却一团糟。老婆和他离婚，儿子嫌他臭。与老警察相对，青年私家侦探波比（黄磊 配音）如日中天，扶摇直上，FBI请他讲课，相关动画片热播，波比俨然成为福尔摩斯一般的存在。在某起密室杀人案后，老警察不得已请来波比调查。波比为什么会这么厉害，这一切似乎都与他的妈妈麦太（吴君如 配音）有关。在崇拜他的小孩子们的追问下，波比的思绪回到孩童时代，麦兜（张正中 配音）和妈妈共处的那个快乐无忧的童年，一切美好都早已注定……©豆瓣', '黄磊', '谢立文', 8.6, 70822, 'tt4179512', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2551331237.jpg', 0.3, 1.2, 12.9, 40.9, 44.7, '0.202620,-0.254540,-0.492120,0.078208,-0.298798,-0.243899,0.794437,0.178021,-0.466655,-0.341319,0.199084,0.456532,-0.121671,0.518117,-0.116035,-0.118762,-0.417482,-0.546353,-0.067634,-0.178210,-0.130176,-0.399715,-0.218656,-0.089131,0.127229,-0.052109,0.558078,-0.098760,-0.073290,0.089822,0.112799,-0.079533,-0.164617,0.305042,-0.335112,0.253171,0.003741,-0.012113,-0.199184,-0.389627,0.045213,-0.091445,-0.166768,0.056955,-0.020787,0.217812,0.386022,-0.064220,-0.243519,0.021798,0.459925,-0.182444,-0.133967,0.038332,0.473111,-0.075636,0.356804,0.166365,0.085481,-0.243571,-0.067852,0.016371,-0.344002,0.219747,0.116582,0.413478,-0.363818,0.326921,0.010827,0.085504,0.129648,-0.278668,0.167219,-0.032233,0.073388,0.577381,-0.099771,0.219539,-0.341245,0.360353,0.439526,0.146827,-0.191063,0.228739,-0.039914,-0.244263,-0.182685,-0.166104,-0.498328,0.133831,0.193970,-0.281010,-0.241762,0.448309,-0.372619,0.119112,-0.007167,-0.067002,-0.278883,-0.238937,-0.265174,-0.613196,-0.136870,-0.274785,-0.108562,-0.054769,0.047155,-0.351477,0.651857,-0.577869,0.066817,0.216680,0.046585,-0.367362,0.456180,0.141905,0.022115,-0.256334,-0.006043,0.173374,0.171885,0.309942,0.221398,0.181331,-0.119911,0.015398,-0.267154,0.481386', '10466639', '1296534', '2002744', '4275444');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25884436', '灭绝', '剧情', '不知曾几何时，地球突然爆发恐怖的丧尸病毒，成千上万的人被病毒感染，随后化作嗜血丧尸撕咬同类，正常人类的数字直线减少。帕特里克（马修·福克斯 Matthew Fox 饰）和杰克（杰弗里·多诺万 Jeffrey Donovan 饰）当年乘坐巴士疏散，谁知途中遭遇最惨烈的 事件，这两个男人以及一个尚在襁褓中的小婴儿成为唯一的幸存者。九年后，地球上人类所剩无几，杰克以及当年的婴儿——可爱的小女孩露（奎恩·麦克科甘 Quinn McColgan 饰）住在一个寒冷的山村，父女俩相亲相爱，甜蜜温馨。与之相对，胡子拉碴的帕特里克与他们比邻而居，他似乎与杰克有着深深的隔膜。某个飘雪的夜晚，露意外在院落外目击到久未出现的丧尸的行踪，曾经的噩梦再度浮现……©豆瓣', '马修·福克斯', '米古尔·安格尔·维瓦斯', 5.8, 5657, 'tt3467412', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2259943367.jpg', 6.7, 24.4, 48.4, 15.2, 5.3, '0.392753,0.052348,-0.799186,0.440328,0.042525,0.051545,1.374928,0.083776,-0.388192,-0.097091,0.528964,0.796386,-0.395618,0.306361,0.073021,-0.215299,-0.111039,-0.553225,-0.229619,-0.312647,-0.440359,-0.233945,-0.524877,-0.261171,0.127099,-0.378640,0.615422,0.234236,-0.016161,0.546735,-0.010684,0.397147,-0.617761,0.427735,-0.320907,0.082064,0.131486,0.090147,-0.162510,0.053884,-0.143506,-0.028214,0.006741,-0.033494,-0.482486,0.497691,0.945088,-0.567331,-0.185110,-0.226923,0.196430,-0.109779,-0.101819,0.142149,0.426874,-0.081124,0.238632,-0.217354,0.118258,-0.097219,0.158025,0.063690,-0.556796,0.087997,-0.056537,0.345021,-0.301273,0.486571,0.056940,-0.088845,0.479085,-0.151985,0.056746,0.392886,0.032578,0.463066,-0.146781,0.259456,-0.510033,0.025930,0.471720,0.019925,-0.764474,0.387700,-0.417845,-0.580879,-0.179130,-0.139661,-0.406188,-0.027321,0.482409,0.045458,-0.345551,0.510840,-0.844209,0.122371,-0.144726,-0.014468,-0.174169,0.033358,-0.572358,-0.702168,-0.271897,-0.545670,-0.276868,0.260819,0.038988,-0.021396,0.517215,-0.745014,0.456710,0.264426,0.215179,-0.014468,0.393272,-0.260669,0.101231,-0.064326,-0.222335,0.356216,0.066608,0.341943,0.330652,0.413235,-0.403551,0.167477,-0.565385,0.648927', '20451118', '1467779', '21619567', '1578663');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25884741', '美国甜心', '剧情', '斯塔（萨莎·莱恩 Sasha Lane 饰）带着妹妹和酒鬼父亲过着相依为命的生活，姐妹两人靠着在垃圾堆里捡别人吃剩的食物过活，不仅如此，斯塔还承受着来自父亲的侵犯和猥亵，精神在压抑中渐渐趋向绝望。某日，斯塔在偶然之中认识了名为杰克（希亚·拉博夫 Shia LaBeouf 饰）的男子，杰克是一支杂志推销团队里的领头人物，在杰克的邀请下，斯塔最终下定决心登上了驶往自由的面包车，彻底离开了荒谬不堪的原生家庭。就这样，斯塔成为了一名杂志推销员，由杰克负责指导。在此过程中，杰克和斯塔之间产生了炙热的感情，然而杰克一直以来和他们的顶头上司克里斯塔（莱莉·科奥 Riley Keough 饰）保持着肉体关系。这段注定见不得光的恋情让斯塔体味到了别样的辛酸和悸动。©豆瓣', '萨莎·莱恩', '安德里亚·阿诺德', 7.4, 16530, 'tt3721936', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2403671949.jpg', 1.7, 6.1, 32.6, 40.8, 18.8, '0.414248,-0.073870,-0.750073,0.569384,-0.215138,-0.535186,0.909347,0.316029,-0.676550,-0.048901,0.265093,0.715893,-0.180736,0.290518,0.372358,0.085832,-0.432225,-0.625735,-0.176046,-0.195451,-0.280337,-0.664940,-0.428565,0.062588,-0.197717,-0.574999,0.444273,-0.046656,-0.162307,0.618842,0.055812,0.278383,-0.277279,0.465909,-0.135929,0.077846,0.336564,-0.092711,-0.391474,0.274210,0.137755,0.012642,-0.137354,0.242773,-0.024271,0.314032,0.598143,-0.381810,0.068329,-0.054303,-0.012245,0.041502,-0.005639,0.205328,0.047028,0.159322,0.202882,0.307547,-0.306815,0.211928,0.222568,0.129378,-0.611312,0.090846,-0.079312,0.307329,-0.936913,0.623548,-0.049534,-0.285171,0.294502,-0.405712,0.268333,0.160302,0.189922,0.511280,-0.225399,0.001146,-0.605440,0.072254,0.582726,-0.022312,-0.264171,0.191094,-0.382999,-0.099482,-0.166803,-0.030097,-0.723581,-0.358519,0.221059,0.175487,-0.191062,0.627364,-0.775032,0.170268,-0.084411,0.037914,-0.074098,-0.493556,-0.130058,-0.731798,-0.280625,-0.442158,-0.213647,0.068329,0.100893,-0.319845,0.684829,-0.803737,0.428984,0.440729,0.429918,0.019389,0.546585,0.110230,0.166607,-0.021765,-0.189820,0.361422,0.061473,0.198633,0.314946,0.516417,-0.128843,0.064298,-0.446259,0.611072', '3111650', '24698878', '1876765', '25723780');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25884801', '记忆大师', '悬疑', '故事发生在2025年，因为和妻子张代晨（徐静蕾 饰）婚姻破裂，男主角江丰（黄渤 饰）走进记忆大师医疗中心接受手术，却不料手术失误记忆被错误重载，他莫名其妙变成了“杀人凶手”。警官沈汉强（段奕宏 饰）的穷追不舍让他逐渐发现，自己脑内的错误记忆不仅是破案的关键，更是救赎自己的唯一希望。与此同时，妻子身边出现的女人陈姗姗（杨子姗 饰）、记忆中浮现出的神秘女子（许玮甯 饰），似乎也和真相有着千丝万缕的联系，一场记忆烧脑战也随之开始。', '黄渤', '陈正道', 7.1, 348514, 'tt', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2455156816.jpg', 1, 6.4, 40.5, 41.8, 10.3, '-0.020581,0.276775,-0.520550,0.402583,0.033140,-0.115797,0.957946,-0.105945,-0.623113,-0.585240,0.287681,0.515406,-0.124832,0.118211,0.227774,-0.065339,-0.226448,-0.708877,0.186784,0.157086,-0.286551,-0.603521,-0.209032,-0.207981,0.078331,-0.566773,0.770746,0.214067,-0.291505,0.370214,0.314219,0.373048,-0.305199,0.344294,0.281074,0.201218,0.060691,0.177880,-0.290616,-0.122459,0.283928,-0.548940,0.217349,0.183663,-0.486156,0.401305,0.749111,-0.180911,-0.316473,0.186971,0.497594,-0.235261,-0.264845,0.011496,0.019700,0.269791,0.222808,0.257037,-0.203124,-0.284843,-0.005558,0.052521,-0.498540,-0.067889,0.280340,0.602504,-0.212103,0.044111,-0.236369,0.098703,0.242789,-0.168761,0.357712,0.008689,0.650764,0.273933,-0.650953,0.081215,-0.419382,0.165845,0.409046,-0.116191,-0.206158,0.476904,-0.212310,-0.440280,-0.194578,0.023272,-0.107855,0.485967,0.042844,0.190890,-0.218900,0.482213,-0.314049,-0.150560,-0.241143,0.136108,-0.054189,-0.206148,-0.061635,-0.262804,-0.461029,-0.116249,-0.488619,-0.049416,-0.233098,-0.424612,0.488238,-0.768844,0.218254,0.305142,0.106847,-0.475194,0.525987,0.011525,0.044338,-0.609401,0.142598,0.529212,-0.106374,0.113381,-0.205717,0.126359,-0.078648,-0.157370,-0.412022,0.333162', '1417036', '2377539', '3263169', '1304665');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25885742', '谜一样的双眼', '剧情', '雷（切瓦特·埃加福特 Chiwetel Ejiofor 饰）是一名非常出色的FBI探员，搭档杰西（朱莉娅·罗伯茨 Julia Roberts 饰）和检察官克莱尔（妮可·基德曼 Nicole Kidman 饰）是他的好友，三人组成了坚不可摧的铁三角，惩奸除恶，所向披靡。然而，某日，杰西的女儿被残忍的杀害了，女儿的死带给了杰西巨大的精神创伤，三人也就此渐渐分道扬镳。一晃眼十三年过去，当年耸人听闻的凶杀案如今已经渐渐尘封，可它给人们带来的伤害却并没有减少分毫，凶手依然逍遥法外。一次偶然中，雷发现了某些新的线索，这些线索让他开始重新调查当年的案件，此时的雷并不知道的是，他即将开启的，是隐藏了怎样可怕秘密的潘多拉魔盒。©豆瓣', '妮可·基德曼', '比利·雷', 6.4, 10262, 'tt1741273', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266433053.jpg', 2.2, 13.3, 53.9, 24.7, 5.9, '0.273708,-0.045575,-0.581794,0.499800,-0.250089,-0.246102,0.949250,-0.086659,-0.698459,-0.360942,0.012505,0.676352,-0.255752,0.144511,0.083194,0.096359,-0.186117,-0.682588,0.044868,-0.138132,-0.398144,-0.567961,-0.502453,-0.040000,-0.000743,-0.203913,0.459698,0.359279,-0.216079,0.283356,0.363031,0.376263,-0.066293,0.611490,-0.120054,0.252440,0.112450,-0.042224,0.047844,0.120692,0.127250,-0.429885,-0.061345,0.547438,-0.110681,0.662571,0.443079,-0.359904,-0.270152,-0.092123,0.455278,-0.367518,-0.068255,0.082545,0.285722,-0.033400,0.119431,0.221747,-0.166693,-0.209434,0.031292,-0.051678,-0.898268,-0.047503,0.190138,0.101685,-0.530255,0.333559,-0.186428,0.059729,0.089291,-0.173158,0.296971,0.302797,0.232498,0.154456,-0.004018,-0.172007,-0.542250,0.174729,0.524519,-0.018020,-0.457202,0.223655,-0.247050,-0.352827,-0.151838,-0.185521,-0.357696,0.185548,0.661470,0.335677,-0.106994,0.519199,-0.485955,-0.312713,-0.531335,-0.025264,-0.169204,-0.451800,-0.044876,-0.424308,-0.250843,-0.521299,-0.275514,-0.007670,-0.196722,-0.405262,0.542530,-0.790587,0.328745,0.381360,0.034896,-0.327180,0.367954,-0.051090,0.098941,-0.092933,-0.007940,0.236776,0.441028,0.280538,0.387111,0.342900,0.291493,-0.209460,-0.275571,0.555159', '25828589', '1307748', '3569911', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25885827', '时间脱离者', '爱情', '生活在过去时空的一个男人和生活在现在时空的一个男人，都为了一个女人的命运而努力的爱情故事。', '林秀晶', '郭在容', 6.9, 8806, 'tt5597408', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2324019591.jpg', 1.1, 7.8, 47.2, 34.2, 9.7, '-0.066633,0.127863,-0.714152,1.318239,-1.021572,-0.355427,1.743927,0.288220,-0.169413,-0.120432,0.155000,1.335790,0.376660,0.156701,0.733574,-0.180581,-0.184882,-0.911256,-0.057656,-0.288842,-0.974597,-0.101159,-0.092740,-0.847162,-0.017597,-0.605751,1.335438,0.042463,0.404961,-0.225957,0.143463,-0.162813,-0.378065,0.654425,-0.992968,-0.245067,0.073819,0.353032,-0.565496,0.634405,-0.212648,-0.162354,-0.214772,0.365742,-1.032512,-0.461760,1.309033,-0.491220,-0.208008,-0.152179,0.322181,-0.144237,-0.512411,-0.354707,0.347875,-0.652352,0.334797,-0.009286,-0.148981,-0.040294,0.512997,-0.399240,-1.468083,-0.269799,0.039577,0.318004,-0.342319,0.937489,0.317885,-0.110103,-0.255700,-1.023258,0.191449,0.465965,0.948807,0.828015,-1.134944,0.354422,-0.660753,0.280598,1.007506,0.102765,-0.465717,0.994900,-0.600171,-0.131023,-1.050019,0.081249,-1.712520,-0.406497,0.177869,-0.355872,-1.024810,0.439176,-0.933441,0.489813,-0.023763,-0.238685,0.029671,-1.276766,-0.509909,-0.087112,-0.412104,-0.422444,-0.216366,0.323904,0.367058,-0.467766,1.229677,-0.953793,0.173044,1.641069,0.227664,-0.933302,1.532598,0.644235,0.410725,-0.686859,0.168670,0.506490,0.125207,0.238219,-0.409745,0.973329,-0.472117,0.837471,-0.619108,1.328062', '26884422', '1296757', '30279170', '35337517');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25886500', '年少轻狂', '喜剧', '胡多多（孙坚 饰）个性谨慎而又胆小，表面看来平平无奇，实际上一肚子的鬼主意，却又因为内向和腼腆，而常常招致他人的忽略。邓小余（包贝尔 饰）智商一般，性格则是没由来的乐观和开朗，虽然常常因为矮小的身材收到同学的欺负，但天生心大的他从来不会将这些事情放在心上。这迥异的两人在大学校园中相遇了，组成了处处惹是生非的二货组合，倒也十分相称。邱樱子（陈妍希 饰）是学校里公认的校花，容貌姣好成绩优异的她这四年里少不了优质男生追随其后，但邱樱子却不为所动。周游（郑恺 饰）拥有高超的智商，是活跃在黑客界的知名人物，现实中，他一直都在和老师斗智斗勇。毕业季将近，每一个人都希望自己最后的青春能够燃烧绽放出最绚丽的焰火。©豆瓣', '陈妍希', '戴睿', 3.7, 3177, 'tt6447856', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2276731256.jpg', 49.1, 27.4, 15.4, 3.5, 4.7, '0.420747,0.072979,-0.705100,0.851256,-0.453492,-0.007743,0.783952,0.053749,-0.547981,-0.302319,-0.051506,0.605916,-0.325074,0.224583,-0.057395,-0.162474,0.046777,-0.505883,-0.173569,-0.253144,-0.008241,-0.344901,-0.378199,-0.058272,-0.344264,-0.193794,0.562718,0.048702,-0.202998,0.660730,0.473616,0.131285,0.051154,0.473615,-0.199941,-0.147436,-0.328778,0.330897,0.331257,-0.044525,0.093994,-0.207067,-0.130219,0.224278,0.243628,0.484047,0.657672,-0.093628,-0.265141,0.003206,0.533509,-0.177032,-0.257383,0.127036,0.418538,-0.120691,0.524093,-0.008978,0.020928,0.288408,0.064701,-0.087296,-0.637282,0.100744,0.464577,0.042514,-0.492007,0.617563,0.228335,-0.279783,0.033911,-0.120613,0.000492,-0.038874,0.290461,0.257379,0.045387,0.078918,-0.404914,0.189905,0.521250,0.285587,-0.578290,0.323644,-0.629416,-0.339028,0.012530,-0.537132,-0.524838,-0.064384,-0.105168,-0.031604,0.067632,0.307981,-0.525790,0.338770,0.160141,0.267707,-0.324891,-0.587094,-0.095312,-0.380130,-0.178609,-1.055034,-0.488050,0.289263,-0.100723,-0.301641,0.973849,-1.066086,-0.137672,0.178279,0.165044,-0.426827,0.698251,0.350478,-0.019330,-0.142009,-0.338616,0.187779,0.125447,-0.148908,-0.199190,0.531448,-0.135375,-0.439297,-0.497184,0.562342', '1390020', '26354526', '26283288', '6963575');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25887288', '冰雪奇缘2', '喜剧', '历经严酷考验，阿伦戴尔王国终于回归往日平静。艾莎女王（伊迪娜·门泽尔 Idina Menzel 配音）、安娜公主（克里斯汀·贝尔 Kristen Bell 配音）以及他们的好友雪宝（乔什·加德 Josh Gad 配音）、克里斯托弗（乔纳森·格罗夫 Jonathan Groff 配音）、驯鹿斯文过着平静安逸的生活。可是最近一段时间，艾莎总会被一段神秘的吟唱所困扰，为了追寻真相，她义无反顾踏上了征途。担心姐姐的安全，安娜和雪宝、克里斯托弗他们紧紧跟随。在那座常年被浓雾所笼罩的森林里，不仅藏着神秘的自然力量，更隐藏着关于阿伦戴尔王国、艾莎的魔法来源以及两位公主父母丧生等一系列的秘密。艾莎开启了一段寻找自我的旅程……©豆瓣', '克里斯汀·贝尔', '克里斯·巴克', 7, 364619, 'tt4520988', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2572847101.jpg', 0.9, 7.4, 44.9, 33.8, 12.9, '0.186533,0.060421,-0.429319,0.690395,0.066463,-0.217881,0.675526,-0.040508,-0.439630,-0.432402,0.244297,0.470464,0.057387,0.286856,0.270346,0.172881,-0.821896,-0.257544,-0.004208,-0.175882,0.058210,-0.455807,-0.253710,0.021487,-0.065130,-0.721847,0.617824,-0.104491,-0.015354,0.253618,0.001276,0.300617,-0.645235,0.362207,0.225216,0.233888,0.461044,-0.349569,-0.311583,-0.012200,0.063951,-0.095388,-0.144482,0.202336,0.178593,0.111754,0.491694,-0.570672,0.060039,0.087908,0.240309,-0.379572,0.331035,0.106731,0.072838,-0.010179,0.264607,0.273228,-0.283821,-0.207837,-0.174805,-0.442650,-0.583484,0.192169,0.070889,0.334955,-0.417777,0.108097,-0.062131,-0.261810,0.177053,-0.335894,0.122628,0.726706,0.337262,0.154355,-0.250301,0.343368,0.018433,0.059904,0.535309,-0.218683,-0.351026,0.130045,-0.121321,-0.338801,-0.082641,0.008445,-1.017641,-0.005698,0.529932,0.102447,0.052521,0.695781,-0.634551,0.142525,-0.425116,-0.394464,-0.024840,-0.433370,-0.134274,-0.855466,-0.007677,-0.188330,-0.116419,-0.206344,0.088569,-0.302349,0.532064,-0.695626,0.731766,0.655953,0.224015,-0.032077,0.163302,-0.290085,0.356196,-0.207063,-0.022260,0.864460,-0.032210,0.229378,0.102927,0.503789,0.193549,0.146456,-0.548357,0.696322', '2364001', '4889554', '2132932', '25815577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25889465', '双面劫匪', '动作', '沃恩（杰弗里·迪恩·摩根 Jeffrey Dean Morgan 饰）本质上是个善良的男人，可小女儿的重病逼得他不得不成为了一名劫匪。和搭档考克斯（戴夫·巴蒂斯塔 Dave Bautista 饰）一起，两人设计从赌场大亨教皇（罗伯特·德尼罗 Robert De Niro 饰）的手中抢走了300万美元的巨款，哪知道这个看似完美无瑕的计划却在最后一步掉了链子，本应该负责接应他们的那个人临阵脱逃，导致沃恩最终劫持了一辆巴士车开始了逃往之旅。巴士车上搭载着的除了老人和小孩外，还有即将临盆的孕妇，开着这辆车，沃恩不仅要躲避特警克里斯（吉娜·卡拉诺 Gina Carano 饰）和她的手下们的追踪，还要对抗教皇所派出的杀手的猎杀。©豆瓣', '杰弗里·迪恩·摩根', '斯科特·曼', 6.3, 5740, 'tt3276924', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2507024038.jpg', 2.3, 12.5, 58.3, 22.2, 4.7, '0.339139,-0.049785,-0.605029,0.571262,-0.325118,-0.484257,0.678057,0.265090,-0.184980,-0.240074,0.512939,0.748641,0.013076,0.055731,0.534547,0.170642,-0.472601,-0.436257,-0.283372,-0.087484,-0.454271,-0.400851,-0.384142,-0.169560,0.038954,-0.111314,0.612036,0.016493,0.083778,0.420664,0.632660,0.288010,-0.142400,0.178242,-0.283742,-0.029035,0.172487,-0.397862,-0.010011,0.186230,-0.125783,-0.155579,0.041447,-0.012863,0.086883,0.476371,0.436328,-0.331287,0.266767,-0.149186,-0.034807,-0.276116,0.151115,-0.049459,0.322597,-0.128264,0.107069,0.063789,-0.091786,0.008957,0.437888,0.075059,-0.727529,0.177171,-0.183695,0.024071,-0.803507,0.247019,-0.351689,0.206557,0.065096,-0.324990,0.154850,0.258493,-0.072886,0.127982,-0.106009,-0.192758,-0.718737,-0.053474,0.495499,-0.000704,-0.000219,0.333650,-0.068831,-0.250434,-0.195999,-0.323627,-0.498779,-0.081448,0.588857,-0.098724,-0.057077,0.018170,-0.482746,-0.037677,-0.380149,-0.073436,-0.141563,-0.255354,-0.057293,-0.795137,0.248963,-0.356041,-0.143036,0.164173,0.021964,0.027227,0.549278,-0.489630,0.102139,0.520355,0.197332,-0.451806,0.549870,0.045043,0.129920,-0.109287,-0.336728,0.053793,0.199549,0.328297,0.008946,0.430982,-0.040237,-0.292367,-0.241730,0.404735', '1294917', '1829654', '1301345', '34890458');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25889476', '麦兜·饭宝奇兵', '喜剧', '外星巨兽屁屁怪突然袭击地球大肆破坏，全球进入一级戒备，手足无措的军方决定向全球征集优秀的机器人设计，来对抗屁屁怪。梦想当发明家的麦兜（张正中 配音），也带着他设计的“电饭宝”去参赛，机缘巧合下，竟然侥幸当选。于是地球的希望，一下子都落在了麦兜身上！麦兜又能否成为英雄，拯救地球？', '金刚', '谢立文', 6.4, 9229, 'tt6167646', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2377091643.jpg', 4.5, 16.8, 45.2, 22.3, 11.2, '-0.219981,0.390989,-0.641189,0.527406,-0.134040,-0.193553,-0.003264,-0.233379,0.289820,0.205858,0.280150,0.579930,-0.293662,0.265581,0.014458,-0.118871,-0.047252,-0.477494,-0.094389,-0.076676,-0.697640,-0.052298,-0.689562,-0.279560,0.067808,-0.116356,0.642154,0.397409,-0.612333,0.198347,0.640013,0.285570,-0.227824,0.469006,-0.232288,-0.233146,-0.113902,-0.025580,-0.013442,0.190635,-0.393638,-0.156394,0.157812,0.104872,0.116972,0.051959,0.752959,-0.414696,0.126573,-0.311340,0.401677,-0.256643,0.147174,-0.196279,0.419362,0.270899,-0.389628,-0.368797,0.150684,0.344771,0.213972,-0.134367,-0.922307,-0.111518,-0.086007,-0.188792,-0.793263,-0.012860,0.016111,0.248404,0.103390,0.153793,0.169626,0.125928,0.171690,0.584581,-0.076506,0.838121,-0.302576,0.167108,0.049447,-0.131404,-0.245727,-0.095416,0.151719,-0.412221,0.222637,-0.410555,-0.225426,-0.312782,0.314951,-0.259997,-0.012550,0.145878,-0.512460,-0.103317,-0.240336,-0.397218,0.187179,-0.360667,0.477079,-0.337871,0.148964,0.229701,-0.005745,0.317100,0.036587,-0.390216,0.829971,-0.445913,0.053919,0.744915,0.463826,-0.349434,0.488698,0.246110,0.326696,-0.067295,-0.249991,0.245299,0.155825,0.630719,0.194019,0.260608,0.152594,-0.131961,-0.369006,0.481445', '25928048', '24284209', '27602116', '26792822');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25890005', '山河故人', '剧情', '1999年，山西汾阳县城，开朗雀跃的女孩沈涛（赵涛 饰）徘徊在矿工梁子（梁景东 饰）和煤矿老板张晋生（张译 饰）两端。一女二男的三角恋，无法维持长久的平衡。梁子和晋生的友情破裂。涛儿结婚的时节，有人选择远方。2014年，因长期在煤矿工作，梁子的健康已经到了不可挽回的地步。最后的时光，他带着妻儿回到故乡。此时沈涛和晋生已经离婚，晋生带着孩子到乐常住上海。人届中年，彼此都身不由己站在了生离死别的界限上。2025年，只会说英文的到乐（董子健 饰）和父亲分外隔膜，但和中文老师米娅（张艾嘉 饰）成为忘年交。他渴望脱离父亲的控制，渴望得到甚至都不知道什么意思的“自由”。©豆瓣', '赵涛', '贾樟柯', 8, 282932, 'tt3740778', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2274320140.jpg', 0.6, 2.4, 20.2, 47.5, 29.3, '0.300103,-0.054811,-0.726710,0.253125,-0.089253,-0.257233,0.655694,0.334571,-0.439840,-0.060706,-0.019368,0.327982,-0.184267,0.530240,0.103023,-0.137754,-0.190922,-0.571154,0.180811,-0.231849,-0.266404,-0.449740,0.008332,-0.025437,-0.366332,-0.146963,0.595230,0.159390,0.008568,0.382379,0.084873,0.051516,-0.147842,0.428053,-0.313452,0.052717,-0.124939,0.172784,-0.472187,-0.060670,0.129190,-0.063695,-0.269796,-0.053500,0.075789,0.336482,0.648878,-0.112384,0.008262,0.232906,0.087293,-0.153980,-0.104794,0.333367,0.202979,-0.064905,0.174695,0.303723,-0.315125,-0.255656,0.062567,-0.091259,-0.299137,0.088213,0.188567,0.187378,-0.472258,0.737927,-0.027532,-0.144319,0.056179,-0.553708,0.222849,0.442602,0.117003,0.602374,-0.404042,0.036838,-0.565323,0.189820,0.697459,0.044055,-0.280328,0.223710,-0.246366,-0.472340,-0.470600,-0.090072,-0.701336,-0.215333,0.156052,0.105485,-0.050792,0.213467,-0.511606,0.026537,0.044990,0.115243,0.175388,-0.411427,-0.124575,-0.260733,-0.214901,-0.639749,-0.068721,0.359408,0.247169,-0.408727,0.688011,-0.742274,0.213137,0.297340,0.399624,-0.590101,0.653784,0.153302,0.058225,-0.527752,-0.092833,0.344482,-0.173533,0.115244,0.411575,0.328159,-0.265920,0.149749,-0.128545,0.494327', '26354526', '3445516', '10574468', '4066127');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25890017', '哥斯拉2：怪兽之王', '动作', '随着《哥斯拉》和《金刚：骷髅岛》在全球范围内取得成功，传奇影业和华纳兄弟影业联手开启了怪兽宇宙系列电影的新篇章—一部史诗级动作冒险巨制。在这部电影中，哥斯拉将和众多大家在流行文化中所熟知的怪兽展开较量。全新故事中，研究神秘动物学的机构“帝王组织”将勇敢直面巨型怪兽，其中强大的哥斯拉也将和魔斯拉、拉顿和它的死对头——三头王者基多拉展开激烈对抗。当这些只存在于传说里的超级生物再度崛起时，它们将展开王者争霸，人类的命运岌岌可危……', '凯尔·钱德勒', '迈克尔·道赫蒂', 6.2, 259786, 'tt3741700', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2554370800.jpg', 3.2, 17.4, 50.4, 22.6, 6.5, '0.216768,0.357156,-0.827006,0.756395,0.555477,0.486295,0.760036,-0.321449,-0.369780,-0.024181,0.097178,0.946658,-0.169598,-0.187400,-0.000456,-0.382059,-0.118060,-0.569684,-0.330791,0.111270,0.001583,0.105850,-1.143427,-0.081476,-0.121655,-0.479887,1.119571,-0.008680,-0.678345,0.114800,0.194515,0.407140,-0.677904,0.055983,-0.113791,-0.186487,0.101999,-0.085023,-0.598406,0.527920,-0.324113,0.234778,0.009165,0.304390,-0.278854,-0.275886,0.709365,-1.166934,0.305344,-0.645781,0.358595,-0.260137,-0.328803,0.089115,0.483874,0.210140,0.281506,0.243267,0.241408,0.215267,-0.279645,-0.390516,-1.284355,-0.234589,0.165898,0.068675,-0.467261,0.288667,-0.015512,0.026948,0.324726,-0.146073,0.189503,0.192329,0.575514,0.304544,0.180297,0.141265,-0.283490,0.176297,0.558082,-0.000822,-0.627217,0.024473,0.368719,-0.622401,-0.768955,-0.648514,-0.226487,-0.179874,0.458167,0.332598,-0.002204,0.647736,-1.350085,0.090915,-0.207080,-0.365163,-0.158874,-0.444644,-0.010217,-0.698924,-0.162586,-0.314889,0.004617,-0.133221,0.266961,-0.418640,0.890026,-0.748978,0.215634,0.355098,0.594240,-0.023904,0.809254,-0.497316,0.277908,-0.349255,0.006066,0.070503,0.235833,0.333604,0.206792,0.377982,0.029342,0.014162,-0.250413,0.780011', '19899707', '3213270', '35377026', '26759819');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25890078', '中国城', '剧情', '讲述的是被遗弃在地铁投币储物柜的女孩，被高利贷不法分子养大成人的故事，被称为女版《华颐：吞噬怪物的孩子》。金惠秀饰演高利贷集团的老板，也是女孩的养母。而金高恩则饰演“储物柜女孩”日英，并为高利贷组织执行各种任务。严泰九将在片中饰演守护日英的宇坤一角。对于高利贷集团中长大的日英有着爱恋之情，是一个纯洁又充满浪漫细胞的角色。而为了解救日英，也展现出男子汉的一面，角色性格反转令影迷非常期待。', '金惠秀', '韩俊熙', 7.3, 31138, 'tt4647788', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2239933990.jpg', 0.9, 4.7, 37.9, 41.2, 15.4, '-0.075212,-0.193163,-0.192426,0.637925,-0.414398,0.222072,0.902262,0.100758,-0.319860,-0.147246,0.372739,0.771446,-0.083556,0.174396,0.386124,-0.115516,0.021965,-0.431657,-0.353542,0.012867,-0.017129,-0.317707,-0.154529,-0.223557,-0.036639,-0.506032,1.146983,0.109673,-0.249687,0.004491,0.628812,0.308948,-0.359022,0.162302,0.004825,-0.162137,-0.096106,0.118994,-0.059731,0.210548,-0.080175,-0.139377,0.116359,0.075134,-0.194705,0.189698,0.873668,-0.216948,0.028055,-0.373188,0.384053,-0.174095,-0.244840,-0.371318,0.360778,0.038002,0.423460,0.227579,-0.077536,-0.209407,0.338578,-0.389028,-0.955239,-0.251296,0.529314,0.044928,-0.602578,0.406526,0.027552,0.119905,0.211851,-0.192524,-0.055928,-0.118992,0.387440,0.780713,-0.119523,0.345509,-0.398774,0.143392,0.221179,-0.117752,-0.116626,0.591654,-0.600820,-0.487313,-0.069655,-0.363753,-0.563313,0.062559,0.132141,-0.194071,-0.241988,0.360091,-0.606139,-0.034391,-0.123576,-0.024647,0.382592,-0.680295,-0.183123,-0.608074,-0.286124,-0.080107,0.118925,0.049741,0.252204,-0.395392,0.963256,-0.821043,-0.043109,0.606863,0.185423,-0.509471,0.797160,0.125262,-0.193275,-0.540628,-0.124071,0.302559,0.257475,-0.159532,-0.247279,-0.000464,-0.382478,-0.144391,-0.209723,0.437194', '26759820', '25880986', '3014200', '5416009');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25890079', '等着你', '惊悚', '熙朱（沈恩京 饰）的父亲死在了连环杀人犯基范（金圣武 饰）的屠刀之下，这残酷的一幕被当时只有七岁的熙朱尽收眼底，虽然一晃眼很多年过去，但当时的一幕幕和凶手穷凶极恶的模样依旧时时出现在熙朱的眼前。尽管基范最终受到了法律的制裁被关入了大牢，但这并不足以消解盘踞在熙朱心头的仇恨。十五年后，基范的刑期已满重获自由，而熙朱也长大成人，开始了她的复仇计划，她决心手刃仇人替父亲报仇。然而，基范天性邪恶狡诈，缺乏经验的熙朱很可能复仇不成，反而成为其手下冤魂。这些年来，刑警大英（尹济文 饰）一直照顾着无依无靠的熙朱，如今，和当年相似的连环杀人案件再度发生，他亦展开了对于凶手的追击。©豆瓣', '沈恩京', '毛弘镇', 6.8, 14290, 'tt5545862', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2316209126.jpg', 1.3, 8.2, 49.2, 30.8, 10.4, '0.085743,0.109686,-0.775605,0.670289,0.049208,-0.152063,0.729444,-0.040362,-0.403746,-0.521336,-0.197143,0.404860,-0.275571,0.810840,0.080446,-0.433800,0.059889,-0.762674,-0.464974,-0.142945,-0.289296,-0.446723,0.205127,-0.176699,-0.113025,-0.064004,0.600916,0.541838,0.291167,0.462802,0.467109,0.280343,0.088189,0.703965,-0.173131,0.212341,-0.308565,-0.262301,0.001679,-0.055610,0.604872,-0.593013,0.098411,0.618914,0.032293,0.363310,0.865592,-0.625864,-0.181518,0.090404,0.523565,-0.591817,0.073574,0.341940,0.362028,-0.173947,-0.303423,0.229777,-0.259292,-0.215252,0.130324,-0.268207,-0.860154,-0.047487,0.004218,-0.370084,-0.616902,0.260697,0.033836,0.562017,-0.194987,0.070827,0.430217,0.211798,0.284411,0.213977,-0.315832,0.105404,-0.547869,0.127868,0.845717,-0.024056,-0.204009,0.263470,-0.242287,-0.508937,-0.457214,-0.371654,-0.203034,0.004793,0.552808,-0.141898,-0.132621,-0.005063,-0.214110,-0.408037,-0.386668,0.249488,-0.105257,-0.182940,-0.058092,0.010839,-0.169926,-0.705642,-0.474515,0.080338,-0.253384,-0.559046,0.392692,-0.897715,0.087732,0.371639,0.113601,-0.860373,0.458189,0.092421,0.070366,0.060563,-0.306985,0.671160,0.345271,0.167545,0.469785,0.221062,-0.106354,0.135201,-0.110901,0.585298', '1301022', '35073886', '1293265', '5446226');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25890082', '意外来客', '悬疑', '电影改编自德国传说《花衣魔笛手》，讲述在朝鲜战争结束不久，一位名叫武龙[音译]（柳承龙饰）的魔笛手和他的儿子一起来到一个遭受到严重鼠患的偏远山区村庄。村长（李圣旻饰）允许武龙留下来，让他做些零工并且达成了驱除鼠患的交易。到了武龙要村长兑换诺言并离开的时候，却发现被欺骗了。武龙发誓要报仇，他把老鼠引回村庄，让村庄笼罩在恐怖之中，为实现一个古老的预言。', '柳承龙', '金光泰', 7, 6687, 'tt4718500', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2253756309.jpg', 1.3, 7.2, 43.8, 35.4, 12.3, '0.217155,0.272279,-0.550899,0.469259,-0.319118,-0.081249,0.730434,-0.079605,-0.155115,-0.311314,0.383471,0.800061,-0.000773,-0.090935,0.096696,0.074328,0.192643,-0.410960,0.139499,-0.129708,-0.295718,-0.413839,-0.012011,-0.217228,-0.154791,-0.705341,0.443668,0.341978,-0.301783,0.244794,-0.037474,0.207416,-0.214538,0.302988,-0.226656,0.184215,0.084369,-0.069473,-0.171899,0.648236,-0.270341,-0.076611,-0.078731,0.333016,-0.232751,0.176577,0.760172,-0.181242,-0.416996,-0.003283,0.322833,-0.357517,-0.117475,0.289397,0.308224,-0.074431,0.058400,0.287535,-0.395395,0.077363,-0.153212,-0.086121,-0.714654,0.016029,0.010341,0.115290,-0.616015,0.286662,0.278160,0.042905,0.194318,-0.441490,0.345169,0.295292,0.235777,0.630555,-0.121492,0.226409,-0.684736,0.249838,0.938484,-0.506049,0.002386,-0.004105,0.131366,-0.291859,0.197390,-0.083143,-0.197475,0.083605,0.275217,-0.199767,-0.455873,-0.024573,-0.767202,-0.305321,-0.378883,-0.345922,0.246040,-0.247740,-0.149139,-0.386934,-0.110841,0.139430,-0.057024,0.143519,0.041945,-0.506379,0.577528,-0.759726,0.610470,0.860279,0.409782,-0.457967,0.612812,-0.052730,0.217719,-0.116596,0.171098,0.187833,0.314168,0.699570,0.240476,0.101684,-0.062482,-0.074054,-0.372144,0.379738', '2032339', '26857170', '3285642', '1949005');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25892603', '沼泽地', '剧情', '上世纪80年代初的西班牙正处于大变革之中，瓜达尔基维尔流域的沼泽地上有一座偏远小镇，一件极其残忍的少女凶杀案就发生于此。来自马德里的警探帕德罗（劳尔·阿雷瓦罗 Raúl Arévalo 饰）和搭档胡安（哈维尔·古铁雷斯 Javier Gutiérrez 饰）奉命来调查此事。然而凶杀案并不像封建保守的当地居民想的那样简单，两人逐渐发现这是一宗连环少女失踪案，他们面对的很可能不只是一个残忍的凶手，而是一个组织。随着受害者母亲（内瑞雅·巴德洛斯 Nerea Barros 饰）提供的关键线索，案件更加地扑朔迷离，而在调查过程中帕德罗也发现了胡安不为人知的过去，更让人不安的是社会的腐败，以及小镇人民的贫穷与冷漠，两人都面对着极大的挑战。©豆瓣', '劳尔·阿雷瓦洛', '阿尔韦托·罗德里格斯', 7.3, 13447, 'tt3253930', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2193145198.jpg', 0.7, 3.8, 37.3, 47.2, 11, '0.599806,-0.260169,-0.648748,0.653967,0.120065,-0.002034,0.896928,-0.046983,-0.673632,-0.278893,0.170538,0.809664,-0.060499,-0.031102,0.323070,0.039934,-0.373113,-0.551841,-0.173701,-0.241268,-0.347562,-0.708688,-0.403750,-0.380014,-0.133017,-0.031214,0.471746,0.417586,-0.186517,0.227444,0.209969,0.638583,-0.135459,0.545183,0.021155,-0.229724,0.107502,0.015711,-0.151849,0.052661,0.059512,-0.097628,-0.160291,0.340504,0.074780,0.406380,0.396956,-0.530729,-0.158063,-0.075807,0.431317,-0.149412,0.001959,0.122793,0.389632,-0.247368,0.202786,0.290645,-0.151421,-0.197996,0.128565,-0.266942,-0.638164,0.158711,0.217401,0.482331,-0.279876,0.409968,-0.016907,-0.047380,0.044204,-0.447618,0.103286,0.467146,0.429558,0.308690,-0.048167,-0.243508,-0.474788,-0.018275,0.439767,0.300927,-0.408198,0.004722,-0.528612,-0.631614,-0.220816,-0.264119,-0.368554,-0.037401,0.216504,-0.144594,-0.087644,0.606736,-0.605132,0.170860,-0.281390,-0.204136,-0.056725,-0.128635,-0.165605,-0.601961,-0.030061,-0.550634,-0.314182,0.131564,0.099442,-0.205940,0.384320,-0.780964,0.087254,0.617755,0.156147,-0.228486,0.362576,0.045292,0.130562,-0.188870,-0.390124,0.449626,-0.020183,0.200716,-0.112706,0.370470,0.052351,-0.299221,-0.026376,0.463875', '1309172', '1769507', '2268359', '3213250');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25894431', '星球大战外传：侠盗一号', '动作', '共和体制崩塌，银河帝国的阴影笼罩着宇宙文明每一个角落。为了加强对反抗势力的镇压，塔金主义直接催生了一种足以摧毁星球的超级武器——死星的诞生，而物理科学家盖伦·厄索（麦斯·米科尔森 Mads Mikkelsen 饰）正是死星的主要设计者。厄索的女儿琴（菲丽希缇·琼斯 Felicity Jones 饰）在童年时代与父母经历了生离死别，之后她被反抗组织领袖索•格雷拉（福里斯特·惠特克 Forest Whitaker 饰）所抚养长大。成年后琴罪行累累，成为帝国的阶下囚，最终却被反抗组织救出。从格雷拉那里她得知死星的存在，并见证了一个城市的灰飞烟灭。然而义军同盟决然不信死星的存在，万般无奈琴和飞行员卡西安·安多（迭戈·鲁纳 Diego Luna 饰）等人孤身前往收藏着死星设计图的星球，攸关全宇宙命运的战争拉开了序幕……故事根据1977年《星球大战：新希望》片头的一段文字改编。', '菲丽希缇·琼斯', '加里斯·爱德华斯', 7.3, 170876, 'tt3748528', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2403049086.jpg', 1.3, 5.4, 36.3, 40.9, 16.2, '0.103162,0.403868,-0.671517,0.576006,0.240672,0.061797,0.457976,0.208629,-0.254847,-0.253962,-0.015817,0.592148,-0.036088,-0.175399,0.315542,-0.192628,-0.229286,-0.539567,-0.113078,-0.135834,-0.526616,-0.331072,-0.283444,-0.262404,0.020520,-0.573151,0.988305,0.163652,-0.260297,0.103166,0.167060,0.397644,-0.149865,0.173437,0.031723,-0.113276,0.086713,-0.059091,-0.509920,0.143134,-0.438073,0.042969,-0.070497,0.187886,-0.262228,0.063488,0.547768,-0.548695,0.387611,-0.377057,0.195502,-0.329569,-0.180197,-0.272079,0.334980,-0.068473,-0.181817,0.262323,0.037892,-0.034803,0.335616,-0.294723,-0.841692,-0.279055,0.070982,0.149455,-0.405932,0.445174,-0.172372,0.051235,-0.287522,-0.124530,0.257363,0.366861,0.194488,0.278393,-0.224114,0.043483,-0.520084,0.123674,0.218008,-0.268749,-0.513779,0.052058,-0.218280,-0.545051,-0.272594,-0.475288,-0.377059,0.095779,0.244397,0.011345,-0.100162,0.439774,-0.849117,-0.110447,-0.570316,-0.294953,0.254848,-0.631448,0.020273,-0.444364,-0.269013,0.144928,-0.181004,0.041202,0.000273,-0.050303,0.770355,-0.494671,0.323381,0.395836,0.405999,-0.293244,0.498097,0.014367,0.174785,-0.453342,0.062373,0.653660,0.140017,0.401496,0.011609,0.013177,0.113769,-0.002982,-0.181138,0.438111', '3001114', '26290398', '7051375', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25894468', '世界奇妙物语 2014年秋之特别篇', '剧情', '《惊喜》勤恳的派遣员工藤村优希（多部未华子 饰）渴望像同事那样得到来自恋人的惊喜庆祝，于是男友和健斗（马场彻 饰）和周围的人为她送上一波又一波超乎寻常的惊喜；《奔跑的相扑弟子》上班族信田（仲村亨 饰）和后辈龟井（音尾琢真 饰）喝酒时惹到了旁边的相扑弟子，随后他们被对方追着满街跑；《未来小偷》腰缠万贯的学者大叶国正（吉田钢太郎 饰）正走向死亡，他利用人格交换机和对周遭一切都不满意的青年白井直辉（神木隆之介 饰）交换了身体，两人各自去追寻认为最有价值的东西；《冷》家庭主妇志仓赖子（若村麻由美 饰）不慎被关在打工超市的冷库中，当她获救后却发现自己越来越怕冷；《FANAMO》近未来的人们通过身体改造，可以将粪尿变成一种被称为“FANAMO”的黑色圆柱体，对该技术持抵触情绪的温子（户田惠梨香 饰）不得不和已经接受改造的恋人拓也（平山浩行 饰）面临重大的抉择。©豆瓣', '户田惠梨香', '前田司郎', 6.8, 7599, 'tt4070966', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2201149948.jpg', 0.8, 7.1, 51.1, 32.4, 8.6, '0.226127,-0.149443,-0.378598,0.313616,0.060841,-0.121404,0.684940,0.285761,-0.367673,-0.271857,0.224411,0.536555,-0.298426,0.145842,0.320113,0.132053,-0.225456,-0.676655,-0.144342,-0.057868,-0.282011,-0.299135,-0.265951,-0.212104,-0.184393,-0.188314,0.686379,0.030372,-0.249024,0.403704,0.339904,0.446007,-0.019088,0.456000,-0.175333,0.099883,0.030752,0.079953,-0.027859,0.125365,-0.117949,-0.210381,-0.027355,0.227691,0.000515,0.346642,0.691526,-0.293685,-0.256916,-0.174772,0.142113,-0.167733,-0.109895,0.201647,0.245772,0.242544,0.154602,0.115825,-0.143706,0.151287,0.220360,-0.014476,-0.487177,-0.052640,0.268131,0.156045,-0.437778,0.401919,-0.029014,-0.136533,0.372034,-0.213820,0.044327,0.126995,0.115830,0.403779,-0.330335,0.014356,-0.296682,0.186254,0.493284,-0.052256,-0.079438,0.262145,-0.323087,-0.316225,-0.125364,-0.248540,-0.362234,-0.252009,0.212848,0.243904,0.111892,0.020283,-0.479783,-0.051028,0.005103,-0.081643,0.056153,-0.306118,-0.061608,-0.537078,0.115764,-0.434832,-0.236808,0.209287,0.172185,-0.259399,0.746395,-0.633446,-0.035466,0.407436,0.293720,-0.295940,0.409068,-0.292706,-0.138001,-0.412428,-0.151810,0.011847,0.114021,0.303253,0.112716,0.367956,-0.183425,-0.032329,-0.330674,0.243770', '3811356', '1826173', '10174444', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25895276', '煎饼侠', '喜剧', '人气偶像大鹏（董成鹏 饰）遭遇了意外事件，令其跌入人生谷底，女友采洁（郭采洁 饰）也离他而去，只剩助理董成龙（潘斌龙 饰）和红颜知己柳岩（柳岩 饰）对他不离不弃。大鹏草率签下电影合约，却因资金问题一筹莫展，还遭到了黑道大哥王老板（梁超 饰）的威胁。无奈之下大鹏只得找来小 明星杜潇潇（袁姗姗 饰）、群头马涛（衣云鹤 饰）、狗仔摄影师胡来（崔志佳 饰）组成一个临时摄制组，准备拍摄一部全明星阵容的大片，而拍摄方式也是前所未有的尝试，邓超、吴君如、曾志伟、东北F4等一线大咖能否顺利出演？逼入绝境的大鹏将遭遇什么样的困难？©豆瓣', '大鹏', '大鹏', 5.8, 366891, 'tt4818250', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2253038483.jpg', 9.6, 23, 43.4, 17.5, 6.6, '-0.128284,-0.132445,-0.345652,0.412263,0.315234,-0.106669,0.299715,0.433584,-0.247568,-0.129011,0.438391,0.508567,-0.170260,-0.025083,0.049615,-0.173756,0.041144,-0.590302,0.099369,0.253432,0.204150,-0.174535,-0.367064,0.015750,-0.036394,0.292956,0.551199,0.018137,-0.172193,0.486047,0.523386,0.084217,-0.359845,0.311536,0.222002,0.275737,0.066255,-0.041439,-0.440914,0.135457,0.021159,-0.042166,-0.021100,0.045243,0.075712,0.326845,0.625780,0.019979,-0.324898,-0.057479,0.324113,-0.281362,0.054462,0.087540,0.087054,0.069713,0.493093,-0.045512,-0.177424,0.415634,0.135879,-0.117356,-0.631919,0.315583,-0.111732,0.072153,-0.429233,0.366136,-0.228361,0.085705,0.168990,-0.234486,-0.007455,-0.041333,0.408101,0.068131,-0.155948,0.106858,0.065107,0.568803,0.329019,-0.060742,-0.004587,0.310837,0.229452,-0.306975,-0.170354,-0.046487,-0.316741,0.158667,0.261520,-0.040475,-0.062112,-0.139331,-0.523401,0.040158,-0.282754,0.134349,-0.347446,-0.211159,0.017294,-0.442839,-0.037678,-0.256662,-0.024198,-0.072223,0.173518,-0.183410,0.528615,-0.183992,-0.211710,0.039083,0.314921,-0.537016,0.419129,0.009789,0.079234,-0.211728,0.043690,0.003058,-0.272662,0.154082,0.404959,-0.040810,0.052899,-0.311578,0.027481,-0.004551', '4301278', '25918677', '6101834', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25895901', '海街日记', '剧情', '临海古都镰仓，顺山而成的小镇，不起眼的角落里生活着香田家四姐妹。她们的父亲早年和情人离家出走，母亲则干脆将女儿们抛给了外婆照顾。外婆去世后，外孙女们继承了这栋有着悠久历史的大房子。过早担负起家庭重任的大姐香田幸（绫濑遥 饰），尽心尽力照顾着两个妹妹佳乃（长泽雅美 饰）、千佳（夏帆 饰）健康成长。这一天，父亲去世的消息传到姐妹手中。她们结伴而行参加了父亲的葬礼，并且结识了从未谋面的异母妹妹浅野铃（广濑丝丝 饰）。许是血缘中的亲近之感，幸在临行前邀请铃搬来镰仓同住。未过多久，抱着对姐姐们的憧憬，铃迈入了父亲曾经生活过的房子。四季流转，姐妹们的故事悄然上演……本片根据吉田秋生的同名漫画改编。©豆瓣', '绫濑遥', '是枝裕和', 8.8, 413728, 'tt', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2603364117.jpg', 0.1, 0.5, 8.5, 40.9, 50, '-0.039642,-0.022222,-0.569728,0.564547,-0.116807,-0.217941,0.401957,0.256307,-0.539723,-0.399474,0.090503,0.628341,0.118226,0.775951,0.214537,0.017072,-0.112551,-0.612698,-0.085752,-0.065199,-0.184672,-0.163837,0.001529,-0.057634,-0.185914,-0.323856,0.378575,-0.195368,0.164521,0.647168,0.022252,0.241674,-0.458062,-0.114586,-0.445949,0.292100,-0.108645,0.378920,-0.510079,0.071627,-0.147165,0.057004,-0.095448,-0.189512,0.330903,0.080801,0.676600,-0.209988,-0.097251,-0.322475,0.406081,0.228881,0.022837,0.173977,0.400735,0.309808,0.351096,0.403361,-0.406988,-0.110327,-0.033930,-0.411836,-0.285200,0.124387,0.233720,-0.108813,-0.811046,0.406261,-0.057270,-0.252577,0.108268,-0.277060,0.332896,0.335883,-0.216361,0.547976,-0.339777,0.317726,-0.138807,0.336195,0.636835,-0.321939,0.265975,0.124449,-0.182102,0.082415,0.207384,-0.157971,-0.670890,0.153419,0.186242,-0.066253,0.069061,0.171724,-0.549969,-0.233955,-0.159838,-0.063263,0.584727,-0.366233,-0.081288,-0.600024,-0.037812,-0.469776,-0.354374,-0.052109,0.046315,-0.143938,0.881835,-0.657565,0.418594,0.116475,0.322815,-0.485963,0.619251,0.148482,0.404241,-0.062073,0.037373,0.312614,-0.172403,0.021683,0.158757,0.057003,-0.232445,0.070299,-0.494788,0.205690', '25922902', '3811356', '3445516', '1292720');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25898213', '军犬麦克斯', '剧情', '凯尔（罗比·阿梅尔 Robbie Amell 饰）是一名海军陆战队队员，忠心耿耿的军犬麦克斯是他的搭档和战友，两人穿梭在枪林弹雨之间，经历过许多生死攸关的危急时刻，结下了深厚的友谊。最终，凯尔死在了战场上，心碎的麦克斯竟患上了战后创伤应激症，无法作战也不肯认新主人的麦克斯只能离开了军队。凯尔的家人领养了麦克斯，凯尔的弟弟贾斯汀（乔什·维金斯 Josh Wiggins 饰）格外疼爱这是有故事的忠犬，在凯尔家人的温柔守护下，麦克斯的心理疾病渐渐康复，重新展现出了活力。就在一家人其乐融融之时，一位名为泰勒（卢克·克莱坦克 Luke Kleintank 饰）的男子出现在了麦克斯面前，声称自己是凯尔曾经的战友。©豆瓣', '托马斯·哈登·丘奇', '鲍兹·亚金', 7.3, 10318, 'tt3369806', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2254382850.jpg', 0.9, 4.6, 39.5, 39.5, 15.5, '0.248554,-0.232675,-0.661543,0.547197,-0.173705,-0.602165,1.050914,0.297574,-0.614256,0.017871,0.634886,0.852464,0.031698,0.280012,0.287138,-0.105690,-0.297420,-0.677326,-0.072846,-0.028037,-0.355135,-0.565094,-0.338177,-0.150709,-0.219206,-0.677110,0.598202,-0.179435,0.024203,0.454531,0.241704,0.283772,0.040358,0.412785,-0.207921,0.238305,0.149559,-0.246506,-0.331169,0.002949,0.075459,-0.192271,-0.052498,0.140863,0.048982,0.251865,0.608756,-0.240225,0.036221,-0.058285,0.315141,-0.129943,0.176722,0.164440,0.277256,-0.161795,0.133751,0.078666,-0.053666,-0.188281,-0.044018,0.107515,-0.777953,-0.080894,0.013811,0.380505,-0.883105,0.651988,-0.212537,-0.044439,0.201510,-0.352711,0.179152,0.444185,0.155941,0.225668,-0.136731,-0.072927,-0.517746,0.072903,0.646937,0.027005,-0.336689,0.183714,-0.470908,-0.473349,-0.228547,-0.227854,-0.758723,-0.161093,0.534122,-0.159213,-0.136225,0.563720,-0.477681,-0.071217,-0.333719,-0.095088,-0.168976,-0.243825,-0.005850,-0.542304,-0.152446,-0.706779,-0.512061,0.334405,-0.169780,-0.172288,0.865059,-0.985989,0.312721,0.566754,0.144641,-0.047452,0.607089,0.133981,0.238272,-0.096474,0.152531,0.583147,-0.000364,0.242231,0.482941,0.486965,0.012284,0.312841,-0.391401,0.650516', '4301215', '1292062', '3230121', '3111650');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25899379', '请叫我英雄', '动作', '居住在东京的35岁男子的铃木英雄（大泉洋 饰）是某著名漫画家的助手，他早年曾出版过单行本，但在此之后一直籍籍无名。不仅生活拮据，与女朋友黑川彻子（片濑那奈 饰）的关系也日趋紧张。许是太过为自身的境遇所焦灼，英雄根本没发觉周遭接连发生的异样。直到冷战许久的女友化身为恐怖丧尸，他才发现全日本早已被名为ZQN的僵尸病毒所攻占。原本秩序井然的都市，顿时变成了僵尸肆虐的狩猎场。他慌不择路之际，与女高中生早狩比呂美（有村架纯 饰）坐上一辆出租车，历经千难万险逃出了城市。根据手机上收到的信息，他们朝向ZQN不宜生存的富士山前进，并在途中邂逅了护士的薮（长泽雅美 饰）所在的幸存者们。只不过，危机和考验并未就此结束……本片根据漫画家花泽健吾的同名原作改编。©豆瓣', '大泉洋', '佐藤信介', 7.2, 69603, 'tt3775202', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2395074307.jpg', 1.2, 5.4, 37.7, 41.8, 13.9, '0.266354,-0.155828,-0.591264,0.210734,0.237788,-0.141595,0.545968,-0.077265,-0.579462,-0.514538,0.301137,0.508621,-0.215153,0.119611,0.349570,-0.219904,-0.214900,-0.485967,-0.182247,-0.066764,-0.226390,-0.171849,-0.367912,0.066311,-0.096972,-0.378570,0.803579,0.174271,-0.213223,0.459430,0.091590,0.379260,-0.445696,0.425645,-0.076176,0.143729,-0.017245,0.062290,-0.135863,-0.003583,-0.310749,-0.535813,-0.076289,0.042679,-0.014029,0.474682,0.710352,-0.366628,-0.333541,-0.056488,0.322355,-0.063833,-0.160891,0.003141,0.396077,0.031519,0.279740,0.058634,-0.010272,0.053886,-0.126532,-0.028135,-0.464261,0.008674,0.063276,0.168286,-0.290098,0.474958,-0.031446,-0.246001,-0.002007,-0.165238,0.238427,0.323028,0.086769,0.170836,-0.164002,0.155370,-0.246154,0.281442,0.611932,0.262086,-0.255434,0.398454,-0.114636,-0.568867,-0.250131,-0.182924,-0.390296,0.083647,0.149984,0.206673,-0.287029,0.113978,-0.703342,0.019581,-0.215930,-0.152546,0.138314,0.011282,-0.207289,-0.680609,-0.065178,-0.415319,-0.048194,0.142224,0.077049,-0.115230,0.531585,-0.819557,0.176563,0.325692,0.215643,-0.265659,0.470340,-0.154221,-0.044444,0.048972,-0.154460,0.364582,0.106610,0.542389,0.015457,0.101042,-0.207014,-0.356198,-0.339306,0.384290', '2369613', '3266509', '1826173', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25899616', '将错就错', '喜剧', '运势一向极差并且做任何事都十分倒霉的宫男（小沈阳 饰）因为听信了坑蒙拐骗、信口开河的不靠谱算命先生萨摩耶夫（李诚儒 饰）的指点，因此与为了一份跟梦中情人的口头婚约而绞尽脑汁、迫切求财的秦招妹（田亮 饰）组成“呆萌寻女”二人团，阴差阳错来到新加坡，想借出国碰运气，开始了他们的发财梦。从坐上飞机开始，两个“逗比”就一路笑料百出，风波不断，为了赚钱甚至还打起了挖地道到古董店抢劫的主意，令人啼笑皆非。也在经历了“赌场风波”后，两个倒霉蛋又卷入一宗古董大劫案之中，并因此与“南洋富商”董大山（陈小春 饰）结下梁子。但赚钱的同时泡妞也不能耽误，宫男邂逅了神秘“女神”颜琪（熊黛林 饰），虽然令他魂牵梦绕的女神一直难以琢磨，并不妨碍他与董大山展开一场激烈的“女神”争夺战，原本庸庸碌碌平平淡淡的宫男也在新加坡引来了人生中戏剧性的变化……©豆瓣', '小沈阳', '王宁', 3.9, 9921, 'tt4674506', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2230699039.jpg', 41, 31.6, 21, 3.6, 2.8, '0.316703,0.091138,-0.566873,0.537383,0.098964,-0.264552,0.626509,-0.058246,-0.517291,-0.113447,-0.030498,0.536581,-0.374981,0.252775,0.279051,-0.143549,-0.207150,-0.475092,0.055747,-0.147782,-0.074442,-0.333018,-0.014071,-0.286851,-0.407223,0.051742,0.363444,0.226174,-0.312592,0.359997,0.715007,0.011486,-0.314163,0.420208,-0.117753,-0.063067,-0.118947,0.445373,-0.117696,-0.087018,0.062032,-0.347265,-0.174526,0.195201,0.220968,0.289255,0.546159,-0.297028,-0.169053,-0.163777,0.145599,-0.019351,-0.112236,0.086532,0.275146,-0.056829,0.263572,0.187565,-0.151201,-0.064016,0.230150,-0.082719,-0.416069,0.177563,0.323632,-0.094519,-0.443489,0.282231,0.214323,-0.196100,-0.013769,-0.176459,0.168759,0.431340,0.493683,0.117624,-0.142627,-0.033729,-0.477111,0.544258,0.602911,0.152264,-0.148126,0.308036,0.238283,-0.417820,-0.012836,-0.172689,-0.316734,0.003703,0.222192,-0.185123,0.061325,0.251828,-0.644532,0.149680,-0.187408,0.052551,-0.104646,-0.443019,0.120786,-0.422192,-0.020561,-0.263921,-0.222631,0.382053,0.266696,-0.166883,0.344817,-0.652024,0.089267,0.474973,0.062320,-0.540659,0.475956,0.026893,0.057772,-0.356733,-0.226479,-0.097892,-0.009025,0.276609,0.173473,0.333888,-0.126141,-0.303127,0.044175,0.296614', '1301022', '3033092', '3326747', '1297418');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25900248', '震荡效应', '剧情', '改编自珍妮·玛丽·拉斯卡斯于2009年在《GQ》上发表的文章《Game Brain》。电影主要描述脑神经学医生班奈特·奥玛鲁最先发现到运动员容易罹患一种慢性创伤性脑病（CTE），会使该运动员产生自杀念头。故事改编自真实事件，叙述班奈特·奥玛鲁是一名美国脑神经学医生，他是首位发现美式橄榄球员高概率会因职业缘故而造成脑部慢性病变，便决定将此研究公诸于世。但此研究却遭国家美式橄榄球联盟强烈否认，使得班奈特将面临对事业造成强烈冲击的危机。', '威尔·史密斯', '彼得·兰德斯曼', 7.3, 10344, 'tt3322364', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2265122127.jpg', 0.5, 4, 40.8, 42, 12.8, '0.121741,-0.194622,-0.238495,0.173828,0.355443,0.375380,0.426441,0.123713,-0.426410,-0.228318,0.273622,0.596826,-0.226271,-0.098839,0.355267,-0.311242,-0.043969,-0.359253,0.416451,0.147027,-0.457260,-0.456604,0.021547,-0.445511,0.074243,-0.789157,0.435831,-0.200132,-0.826613,0.369397,0.007537,0.809663,0.331672,0.125141,0.466154,-0.076476,0.094789,-0.260638,-0.134016,0.453182,0.520401,-0.125646,-0.069751,0.211478,0.040475,0.115299,0.636688,-0.024888,-0.257443,-0.169315,0.775452,-0.234782,-0.132022,-0.054218,0.528559,0.421738,-0.020124,0.239906,0.136296,0.123819,0.009853,-0.019276,-0.301395,-0.000311,0.279097,0.274779,-0.189225,-0.069564,-0.185437,-0.243995,-0.036879,0.057320,-0.023214,0.115252,0.564704,0.341931,0.113234,-0.023971,0.027163,0.153842,0.424503,-0.455768,-0.517889,0.172876,-0.481224,-0.404482,-0.074935,-0.447528,-0.113636,0.177922,0.059173,0.169168,-0.219303,0.302518,-0.141634,-0.096415,-0.159410,-0.312912,-0.110384,-0.028854,0.059615,-0.322040,-0.187173,0.267336,-0.260728,-0.167693,0.151538,-0.359313,0.749087,-0.722481,0.331229,0.686514,0.072536,-0.537428,0.235194,0.089918,0.057607,-0.242248,-0.072866,0.401141,-0.169536,0.101196,-0.436315,0.269225,0.141114,-0.118575,0.017045,0.297930', '24284209', '35151491', '27602116', '4221515');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25900249', '住货车的女士', '剧情', '故事发生在1977年的英国伦敦，一位名为谢波德（玛吉·史密斯 Maggie Smith 饰）的老太太开着她的姥爷车来到了一个位于这里的中产社区中。谢波德没有家，吃喝拉撒都在自己的车里，换句话说，在别人的眼中，她就是一名脏兮兮臭烘烘的流浪汉。在这个社区里生活的中产们凭借着他们出色的教养容忍了谢波德女士的入侵，然而他们的善良和宽容却并没有换来谢波德太太的好脸色。这个脾气又倔又犟的老太太让生活在这里的人吃尽了苦头。久而久之，没有人再搭理谢波德太太了，除了一个看上去憨憨的剧作家阿兰（阿历克斯·杰宁斯 Alex Jennings 饰），他不仅每天都对谢波德太太笑脸相迎，甚至同意她占用自己家的车道停车。©豆瓣', '玛吉·史密斯', '尼古拉斯·希特纳', 7.7, 8662, 'tt3722070', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2278664736.jpg', 0.5, 2.2, 28.8, 49.2, 19.3, '0.609140,0.030595,-0.591502,0.628814,-0.277946,-0.735583,0.861597,0.207890,-0.288590,-0.344887,0.058594,0.664158,-0.036976,0.130725,0.156777,-0.084393,-0.135202,-0.239951,0.108712,-0.152405,-0.279567,-0.481308,-0.073827,-0.415272,-0.228326,-0.043261,-0.043133,-0.131363,0.005036,0.390753,0.392840,-0.037942,0.542221,0.593657,-0.466076,0.405531,-0.038656,0.151924,0.025242,-0.133760,0.036424,-0.356101,-0.152349,0.054310,0.495182,0.362142,0.264434,-0.230685,-0.179259,0.133582,0.145531,-0.101750,0.111914,0.219860,0.393769,-0.506422,0.192638,-0.105563,-0.282052,-0.119118,0.092420,-0.078114,-0.440590,-0.153437,0.091450,0.027873,-0.807985,0.471846,-0.017484,-0.145546,-0.260300,-0.168151,0.432786,0.174660,-0.132999,0.462206,0.187106,0.187452,-0.677361,0.277726,0.492437,0.189915,-0.378920,0.094243,-0.524883,-0.416969,-0.081599,-0.318408,-0.979282,-0.140643,0.116982,-0.306828,-0.269430,0.028673,-0.571964,0.219296,-0.048012,-0.224356,-0.042907,-0.501580,-0.108064,-0.429408,-0.183427,-0.887908,-0.194072,0.225509,-0.003796,-0.117337,0.667893,-0.600238,0.361661,0.061059,0.403200,-0.565454,1.059557,0.280660,0.301975,-0.000611,-0.130831,0.235176,0.149765,0.352498,0.260502,0.607342,0.037361,0.004347,-0.157719,0.455831', '26809592', '1302384', '1427319', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25900819', '斯诺登', '剧情', '斯诺登2004年应征入伍、后被派遣到伊拉克战场，因不幸在训练时双腿受伤，斯诺登退役回国后应聘加入中情局。之后，他又进入国安局工作，并意外发现政府在“9·11”事件后对公民电话和社交网络实施大规模监控计划，于是泄露了大量机密文件。事发后，斯诺登遭当局通缉，便逃到香港。此后，他几经辗转逃至俄罗斯寻求庇护。', '约瑟夫·高登-莱维特', '奥利佛·斯通', 7.6, 41887, 'tt3774114', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2399215062.jpg', 0.3, 2.5, 31.5, 48.5, 17.3, '-0.208160,0.167837,-0.999212,0.195133,0.415151,-0.104826,-0.044885,-0.054685,-0.728563,0.012842,0.052198,0.808372,-0.230247,-0.112867,0.437954,0.033106,-0.812466,-1.013616,0.309428,-0.490371,-0.519002,-0.266983,0.138691,-0.301282,0.083096,-0.574369,0.625517,0.293954,-0.533979,0.635820,-0.327516,0.135624,-0.226295,0.761428,0.141437,0.012176,0.706997,0.026927,-0.210267,0.495490,0.032583,-0.473471,-0.218987,-0.055514,0.578889,0.599182,0.467406,0.014037,-0.322614,-0.258700,0.204315,-0.486576,-0.129398,0.079537,0.763610,0.458461,-0.126188,0.510705,-0.522546,0.109297,-0.120343,0.036269,-0.272994,-0.131103,-0.489641,0.122823,-0.460710,0.161434,-0.521817,0.299020,-0.238628,-0.349963,0.034099,1.255571,0.005672,-0.120096,0.061835,0.468129,-0.167021,0.180720,0.576131,-0.454804,-0.207231,-0.051207,0.320334,-0.586301,0.354876,-0.011498,0.149733,-0.230799,0.445399,-0.059774,-0.174883,0.274265,-0.387363,-0.263061,-0.592585,-0.450126,-0.137430,-0.029859,-0.194938,-1.089116,-0.227488,0.288976,-0.453159,0.112992,-0.012214,0.136090,0.234845,-0.792483,0.536638,0.847055,0.471547,-0.859543,0.177844,0.025287,0.267737,-0.236982,0.173505,0.508562,0.299768,0.939388,0.035857,-0.168013,-0.023930,-0.536492,-0.041640,-0.153906', '1431694', '2973528', '1296947', '25833539');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25900945', '美女与野兽', '爱情', '贝儿（艾玛·沃森 Emma Watson 饰）和小镇上的其他女孩不同，是一个热爱阅读和幻想的姑娘，孔武有力英俊强壮的加斯顿（卢克·伊万斯 Luke Evans 饰）发誓要娶贝儿为妻，但贝儿却一眼看穿了他的自私和虚伪，拒不从命。某日，贝儿的父亲莫里斯（凯文·克莱恩 Kevin Kline 饰）迷路误打误撞之下来到了一座荒凉破败的城堡中，那里居住着样貌可怖半人半兽的野兽（丹·史蒂文斯 Dan Stevens 饰）。因为偷摘了城堡里种植的玫瑰，莫里斯被野兽囚禁了起来，得知此消息的贝儿赶到城堡，要求和父亲作交换。就这样，贝儿开始了和野兽的同居生活。在会说话的茶壶太太（艾玛·汤普森 Emma Thompson 饰）、烛台卢米亚（伊万·麦克格雷格 Ewan McGregor 饰）和时钟葛士华（伊恩·麦克莱恩 Ian McKellen 饰）的照顾和帮助下，贝儿渐渐发现，野兽在丑陋的外表下，隐藏了一颗善良温柔的心。实际上，野兽的真实身份是一位王子，因受到了女巫的诅咒而沦落至此，而贝儿，是解除诅咒最后的，也是唯一的希望。', '艾玛·沃森', '比尔·康顿', 7.1, 380458, 'tt2771200', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2417948644.jpg', 0.8, 6.6, 42.4, 36.4, 13.9, '0.393908,0.112183,-0.554819,0.718134,-0.232021,-0.197587,1.004745,0.134090,-0.281682,-0.250136,0.287701,0.734255,-0.171382,0.293532,0.104070,0.283109,-0.321772,-0.365947,-0.068837,-0.112406,-0.281292,-0.546679,-0.381362,-0.206833,-0.015542,-0.400946,0.452281,0.089234,-0.079456,0.494941,0.124220,0.243175,0.138946,0.169401,-0.258936,0.032564,0.097201,-0.115350,0.027297,0.251882,-0.084706,-0.062004,0.122663,0.287459,0.033984,0.407799,0.610576,-0.404915,-0.068667,-0.232754,0.264501,-0.119293,0.209650,0.391027,0.148951,-0.374775,0.129050,0.048604,-0.377320,0.044667,0.273792,-0.159817,-0.515758,0.035676,0.174038,0.335976,-0.567042,0.385800,-0.190880,-0.032141,0.146575,-0.269850,0.200716,0.081239,0.085828,0.482645,0.092802,-0.040317,-0.512205,-0.060444,0.399582,0.047089,-0.178907,0.106146,-0.432970,-0.426864,0.076070,-0.114732,-0.588536,-0.247532,0.246849,0.086954,-0.188395,0.286134,-0.672852,-0.092508,-0.339799,0.091423,-0.054717,-0.498807,-0.312961,-0.457028,-0.093510,-0.520800,-0.245777,0.127417,-0.017871,-0.274967,0.641385,-0.780674,0.311202,0.345692,0.453597,-0.211443,0.551247,0.003494,0.028630,-0.015763,0.122779,0.379227,0.200699,0.050572,