INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25900947', '游侠索罗：星球大战外传', '动作', '在《游侠索罗》中，影迷们将跟随“千年隼号”及银河系中最受爱戴的“恶棍”韩·索罗，迎来全新的银河系探险旅程。经过在黑暗危险的罪犯地下社会中的重重冒险，韩·索罗遇见了他未来强大的副驾驶丘巴卡、以及臭名昭著的赌徒兰多·卡瑞辛，共同展开了一场星战传奇中最不“正统”的英雄 历程。', '阿尔登·埃伦瑞奇', '朗·霍华德', 6.8, 59726, 'tt3778644', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2521436880.jpg', 1.1, 9.7, 47.9, 32.5, 8.7, '0.413065,0.282707,-0.635645,0.842991,0.344384,0.062759,0.626250,-0.455394,-0.603240,-0.142983,0.241093,0.825518,-0.025076,0.413538,0.694655,-0.245969,-0.134384,-0.658288,-0.741702,-0.210904,-0.547446,-0.250809,-0.602436,-0.113103,-0.382342,-0.146994,0.809681,0.479686,-0.201276,0.265061,0.369033,0.598785,-0.296919,0.294257,-0.242403,0.067847,0.598736,0.086934,-0.487895,0.211058,-0.212497,-0.254129,0.126604,0.425644,-0.064045,-0.005923,0.507661,-0.963826,0.439296,-0.452378,0.360532,-0.373931,-0.210501,-0.048754,0.497866,0.122222,-0.132044,0.283312,0.389916,0.298008,-0.102318,-0.347150,-0.734645,-0.289037,0.201469,0.079748,-0.689879,0.367109,0.222668,-0.186086,0.175425,0.278180,0.337017,0.125861,0.400942,0.066042,0.137961,0.147203,-0.110092,0.277473,0.692479,0.031112,-0.477612,-0.050107,-0.186981,-0.786492,0.074562,-0.472093,-0.549539,-0.306821,0.651262,-0.104540,0.032648,0.772476,-0.864945,0.307795,-0.015762,-0.307831,-0.157345,-0.057815,-0.192270,-0.805194,-0.071760,-0.690112,0.083657,0.284932,-0.039375,-0.477431,0.924666,-0.768892,0.189512,0.336142,0.177815,-0.125554,0.567970,-0.120642,0.467434,-0.344667,0.015593,0.500322,0.176082,0.606017,0.011660,0.076067,-0.525349,-0.135549,-0.316030,0.738940', '1870681', '19899707', '1308837', '5308201');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25901741', '奋斗的乔伊', '剧情', '乔伊（詹妮弗·劳伦斯 Jennifer Lawrence 饰）是一名独自抚养两个孩子的单身母亲，虽然她和丈夫托尼（埃德加·拉米雷兹 Edgar Ramirez 饰）已经离了婚，但这个穷困潦倒的男人还常常需要前妻的经济支持。不仅如此，乔伊还要照顾自己每天都瘫坐在电视机前的 母亲和生性风流四处沾花惹草的父亲，她所承担的压力可想而知。实际上，乔伊有着非凡的经商头脑，她发明了魔术拖把，大大减少了主妇们花费在家务活上的时间。乔伊和商人尼尔（布莱德利·库珀 Bradley Cooper 饰）之间达成了交易，开始推广魔术拖把进入市场，但很快乔伊就发现，自己仿佛是一块香喷喷的肉，每个路过的人都想从她身上捞到点什么。©豆瓣', '詹妮弗·劳伦斯', '大卫·O·拉塞尔', 6.7, 22281, 'tt2446980', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2263171191.jpg', 1, 8.4, 51.9, 29.7, 9, '0.173351,-0.100291,-0.687909,0.278537,-0.402985,-0.446992,0.677931,0.321200,-0.466792,-0.274030,0.237050,0.839520,-0.014806,0.324874,0.061335,0.014563,-0.434927,-0.676047,-0.020645,-0.010114,-0.449446,-0.369072,-0.204542,-0.277984,-0.356624,-0.173404,0.475356,-0.278279,-0.124265,0.270577,0.152219,0.001403,0.098752,0.471019,-0.376916,0.056651,0.006603,0.047506,0.031517,0.033016,0.143877,-0.167008,-0.197338,0.118954,0.307585,0.462886,0.445330,-0.066563,0.033309,-0.010088,0.219607,-0.122224,0.000798,0.188915,0.176251,-0.083708,0.241726,-0.071148,-0.220728,0.106592,0.205776,-0.172683,-0.685734,-0.214506,0.081219,0.162472,-0.873875,0.446993,-0.120410,-0.100962,-0.090778,-0.436740,0.053495,0.408113,-0.167932,0.479396,-0.274520,0.042936,-0.643529,0.142870,0.427358,0.032363,-0.133206,0.509756,-0.316785,-0.397276,-0.204103,-0.223482,-0.453481,-0.162137,0.169910,-0.033413,-0.153340,0.201941,-0.741870,0.156343,-0.112193,-0.249403,0.071130,-0.392628,-0.066170,-0.596279,-0.220573,-0.654250,-0.380902,0.096754,0.225979,-0.372772,0.864617,-0.744013,0.224235,0.493845,0.138727,-0.477904,0.524543,0.030329,0.274636,-0.051131,-0.160479,0.192496,0.158483,0.154747,0.043760,0.444368,0.150068,-0.163680,-0.267447,0.638568', '1783461', '30162520', '1308609', '4904026');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25903033', '我是马布里', '剧情', '影片根据真实故事改编。被称为“独狼”的NBA球星马布里事业陷入低谷，黯然隐退。在王牌经纪人李楠（吴尊 饰）的邀请和家人的鼓励下，马布里做出了人生中关键的决定——前往中国追寻自己的“篮球梦”。当坐在飞往中国的飞机上，背后却是他在NBA留下的辉煌和遗憾…重新焕发激情和热血的马布里，却没预想辗转到一支没落的球队，遭遇性格各异、士气低落的队友。在去留抉择间，他对意气相投的教练郑亚雷（何冰 饰）说出了唯一可以使自己留下来的条件——冠军。迎着所有人的质疑和不屑，带领着这支残兵野将的球队，两个拥有共同梦想的男人带领球队踏上了成功概率几乎为零的巅峰征程……', '斯蒂芬·马布里', '杨子', 6.2, 8915, 'tt4662708', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2494729086.jpg', 7.1, 16.9, 44.3, 21.3, 10.5, '0.084792,0.303658,-0.821639,0.787604,-0.069908,-0.464121,0.555262,0.182834,-0.386698,0.054699,0.386952,0.854931,0.030758,0.114603,0.417246,-0.508874,-0.119774,-0.904896,-0.108146,0.010707,-0.200317,-0.605991,-0.405654,-0.072505,-0.081788,-0.292541,1.020173,0.256199,-0.453433,0.683934,0.367671,0.362012,0.131293,0.325099,-0.105860,0.122508,0.096846,0.181884,-0.621933,0.188659,-0.068470,-0.122176,-0.273295,0.156274,-0.141559,0.317681,0.838713,-0.325772,-0.092198,0.164886,0.149620,-0.360227,-0.107381,0.133016,0.135424,0.216661,0.026890,0.199097,0.050547,0.249235,-0.354484,0.002449,-1.150165,-0.146869,0.134677,0.157777,-0.720395,0.723961,-0.109653,0.025476,0.432520,-0.182045,0.196344,0.480263,0.284029,0.381566,-0.301361,0.155654,-0.321965,0.318056,0.704336,0.070172,-0.267648,0.153821,-0.244658,-0.306681,-0.052974,-0.321231,-0.519322,0.013869,0.308085,0.260720,0.194901,0.137736,-0.616437,0.094087,-0.046561,-0.470914,0.080918,-0.642815,0.122199,-0.407813,-0.031133,-0.142483,-0.293134,0.162656,0.001125,-0.266439,0.975261,-0.834240,-0.026536,0.356609,0.242682,-0.384667,0.612106,0.002999,0.193135,-0.328370,-0.192839,0.450582,-0.243009,0.169226,-0.045889,0.354514,-0.314869,0.080393,-0.568376,0.542143', '25880986', '27602116', '6101834', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25904974', '爱情天文学', '剧情', '艾美（欧嘉·柯瑞兰寇 Olga Kurylenko 饰）是一名天文学博士生，过往的伤痛经历让她成为了一名兼职替身演员，只有身处于千钧一发的危险境地，艾美内心的痛苦才有可能稍稍淡化。这样一个伤痕累累的女人，遇见了名为艾德（杰瑞米·艾恩斯 Jeremy Irons 饰）的天文学教授，趣味相投的两人相互吸引着，很快便走到了一起打得火热。可是，让艾美没有想到的是，自己竟然意外的得知了艾德的死讯，可与此同时，来自艾德的讯息一直没有间断过，就好像他仍然还活在人世一样。这诡异的一切让艾美百思不得其解，随着时间的推移，巨大的压力击垮了她，崩溃的艾美要求艾德不要再来打扰她的生活，从此之后，艾德音信全无。后悔莫及的艾美开始想方设法和艾德取得联系，因为只有他才是解开一切谜团的钥匙。©豆瓣', '欧嘉·柯瑞兰寇', '朱塞佩·托纳多雷', 7.2, 8302, 'tt3530978', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2306448007.jpg', 1.7, 9, 36.4, 35.4, 17.5, '0.298682,-0.131765,-0.901690,0.482597,-0.144194,-0.450658,0.936117,0.049051,-0.490045,-0.384279,0.017352,0.690470,-0.313594,0.297548,0.222659,0.090501,-0.259937,-0.995899,-0.050885,-0.289553,-0.499686,-0.503715,-0.230670,-0.349928,-0.064103,-0.403640,0.563514,0.328945,-0.254797,0.477433,0.255683,0.207169,0.004493,0.835020,-0.392291,0.111788,0.175297,-0.031058,-0.063307,0.077809,0.427968,-0.310445,-0.195074,0.415372,-0.061281,0.300234,0.494831,-0.319806,-0.200949,0.292074,0.309272,-0.192739,0.035337,-0.113004,0.286481,-0.175010,-0.014372,-0.033819,-0.440503,0.031790,0.185639,0.127817,-0.747503,0.193349,-0.084450,0.289749,-0.622105,0.382683,0.076596,-0.176398,0.026790,-0.423512,0.142482,0.415704,0.252588,0.285343,-0.210383,0.112705,-0.292330,-0.050157,0.716765,-0.044901,-0.544089,0.499153,-0.183109,-0.302732,-0.171892,-0.164792,-0.476327,-0.082958,0.369475,0.396534,-0.192446,0.325413,-0.471097,-0.048628,-0.433327,-0.272873,-0.271235,-0.413803,-0.089795,-0.321427,-0.346686,-0.396337,-0.549089,0.186711,-0.171957,-0.279319,0.683297,-0.830083,0.517351,0.684624,0.253289,-0.369073,0.553039,0.112984,0.026614,-0.113509,-0.050989,0.425020,-0.037402,0.276561,0.433610,0.383550,0.193045,0.084058,-0.385632,0.666325', '1301022', '1292211', '3059036', '1291577');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25905044', '刺猬索尼克', '喜剧', '《刺猬索尼克》改编自世嘉公司出品的风靡全球的电子游戏。索尼克（本·施瓦兹 Ben Schwartz 配音）是一只蓝色的刺猬，原本快乐的生活在自己的星球上。然而，邪恶的势力觊觎索尼克所拥有了超快速度，想要将这一门绝技夺走，为了保护索尼克，善良的猫头鹰养母给了索尼克一包魔力环，它可以帮助索尼克传送到安全的星球上。就这样，索尼克来到了地球，降落在了位于蒙大拿州的青山市。起初，索尼克在这里生活的非常惬意，并且结交了一批好友。当政府发现了索尼克的存在后，一切都变得复杂起来。政府派出了邪恶的科学家蛋头博士（金·凯瑞 Jim Carrey 饰），命令他捉住索尼克，对他进行可怕的科学研究。为了躲避蛋头博士的追捕，索尼克和警长汤姆（詹姆斯·麦斯登 James Marsden 饰）必须前往旧金山，取得丢在那里的魔力环。©豆瓣', '詹姆斯·麦斯登', '杰夫·福勒', 6, 39591, 'tt3794354', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2615056902.jpg', 2.2, 17.6, 60, 17.5, 2.8, '0.282050,0.150557,-0.715486,0.692191,-0.045775,-0.153948,0.470829,0.197121,-0.233818,-0.043795,0.161893,0.768179,-0.073720,0.099847,0.070064,0.312778,-0.222312,-0.327158,-0.147751,-0.249468,-0.163335,-0.365265,-0.511434,-0.338005,0.014926,-0.553304,0.600140,-0.096195,-0.162587,0.363963,0.106997,0.378975,0.009572,0.290746,-0.337266,-0.068754,0.073389,-0.119136,-0.186798,0.294571,-0.131488,-0.114957,0.203168,0.243774,0.068473,0.095239,0.642680,-0.415171,0.019880,-0.258003,0.310284,-0.459465,-0.102417,-0.279472,0.344680,0.069549,-0.184236,0.003700,-0.205866,0.180175,0.213457,-0.244715,-0.974856,-0.033013,-0.099954,-0.010331,-0.498604,0.380100,-0.213379,0.080736,0.064347,-0.516140,0.295172,0.240654,0.050829,0.187968,-0.184350,0.470994,-0.496177,0.152430,0.553358,-0.416150,-0.154851,0.337853,-0.087031,-0.317901,-0.292807,-0.323514,-0.433125,-0.316303,0.614760,0.133875,-0.066495,0.310504,-0.919906,-0.032076,-0.198915,-0.270244,0.019387,-0.429662,-0.040076,-0.502355,0.002448,-0.292895,0.023698,-0.048323,0.110225,-0.274626,0.756667,-0.773345,0.220695,0.674017,0.192055,-0.261425,0.443444,-0.127065,0.012751,-0.216704,-0.028494,0.105553,0.361707,0.563735,0.152474,0.285251,0.259280,-0.292796,-0.348163,0.627363', '1308585', '3769423', '1793491', '25928048');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25905124', '澄沙之味', '剧情', '故事发生在一间名为“铜锣之春”的铜锣烧专卖店里，千太郎（永濑正敏 饰）是这里的店长，曾经，他有过一段十分灰暗的过往，如今，他将不堪回首的回忆深深的埋葬在心底，安安心心，只做一介卖铜锣烧的小贩。某日，一位名叫德江（树木希林 饰）的老人来到了店铺，声称自己是来应聘做店员的，然而，小小的铜锣之春里并不需要店员，千太郎从一开始就打算拒绝德江。然而，德江拿出了自己制作的红豆馅，品尝过后，千太郎被馅料的美味所震惊了，就这样，德江成为了店里的一员。随着时间的推移，一些有关德江的不利传闻在小镇上蔓延开来，甚至影响到了店铺的经营。©豆瓣', '树木希林', '河濑直美', 8.3, 44450, 'tt4298958', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2234753078.jpg', 0.2, 1, 16.9, 47.9, 34, '0.361786,0.195884,-0.462882,0.233767,0.058632,-0.061071,0.771536,0.365855,-0.572308,-0.109208,0.270538,0.561300,-0.359314,0.161496,0.296798,0.177149,-0.068742,-0.604794,-0.191608,-0.427712,-0.051253,-0.382354,-0.185623,-0.221531,-0.228628,-0.106355,0.401515,0.230655,-0.116011,0.265851,-0.003696,0.070630,0.073317,0.328806,-0.376744,0.354108,0.085621,-0.014445,-0.216534,-0.097266,-0.112175,-0.516098,-0.056302,0.178171,0.218857,0.446661,0.552527,-0.195174,-0.385158,0.162403,0.264671,0.033556,-0.151413,0.209876,0.385241,0.322628,0.178233,0.189930,-0.617969,-0.080526,0.058692,-0.085427,-0.579780,0.028044,0.118384,0.255239,-0.742155,0.137377,-0.067951,-0.051371,0.157689,-0.385905,0.439959,0.051257,0.195185,0.284464,-0.083123,-0.073863,-0.447387,0.514314,0.760328,-0.099128,0.069237,0.395684,-0.160903,-0.044969,-0.120389,0.044697,-0.258241,-0.153093,0.079497,0.140502,-0.032402,-0.061985,-0.739772,0.023979,-0.152477,-0.619755,0.440453,-0.062261,-0.570002,-0.506674,-0.242684,-0.239049,-0.298615,-0.121430,0.221710,-0.091330,0.776620,-0.794848,0.139485,0.341036,0.123634,-0.029376,0.385492,-0.285469,-0.050615,0.061492,-0.043469,0.013802,0.071319,0.409495,0.106601,0.525361,0.047822,-0.296139,-0.344379,0.318590', '1299965', '1309101', '34429100', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25905519', '美好的一天', '剧情', '善于描绘社会荒谬景象的西班牙导演阿拉诺，新作《极渴救援》将镜头转向战乱的巴尔干半岛冲突区，讲述一件原本能轻易解决的水源危机，却在一连串刁难和天人交战后，成为不可能的任务，令一批好莱坞影星班尼西欧岱托罗、提姆罗宾斯、欧嘉柯瑞兰寇所饰演的国际义工们，在各怀心机下陷入不可收拾的荒谬情境。', '本尼西奥·德尔·托罗', '费尔南多·莱昂·德·阿拉诺亚', 7.8, 8186, 'tt3577624', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2318160502.jpg', 0.6, 2.6, 25.9, 50.1, 20.8, '0.350590,0.173032,-0.615241,0.530001,0.320839,-0.019944,0.513840,0.209411,-0.381700,-0.103620,0.270254,0.744396,-0.363647,-0.392415,0.216209,-0.482876,-0.455005,-0.921372,-0.312493,-0.027344,-0.135096,-0.476848,-0.438973,-0.352898,-0.080792,-0.370276,0.514162,0.304499,-0.604946,0.018865,0.377999,0.578599,-0.327323,0.513661,0.101475,-0.106061,0.415723,-0.001836,-0.499466,0.150734,-0.251729,0.043793,-0.290700,0.359275,-0.021853,0.083878,0.779536,-0.361178,-0.063381,0.169479,0.478733,-0.375418,0.172381,0.110435,0.248121,-0.186168,0.043943,0.041789,-0.191757,-0.058345,-0.026772,0.130330,-0.816837,0.038660,-0.051056,0.430320,-0.377912,0.077321,0.057200,-0.026491,-0.012469,-0.348925,0.077168,0.813759,0.687212,0.336508,0.134825,0.089698,-0.285090,0.329944,1.000577,0.236409,-0.419282,0.161747,-0.240486,-0.299673,-0.080649,-0.213593,-0.380002,-0.156645,0.646954,-0.215793,-0.003697,0.709003,-0.305542,-0.234019,-0.378299,-0.365330,-0.130581,-0.402796,-0.182706,-0.745804,-0.199063,-0.109200,-0.171962,-0.129232,0.228299,0.091804,0.664019,-0.524867,0.085844,0.641652,-0.029089,-0.123763,0.426217,0.250410,0.229097,-0.030501,-0.228342,0.410556,-0.055906,0.195868,-0.266803,0.575699,0.022047,-0.273775,-0.381075,0.158071', '25978126', '1306454', '26678784', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25905892', '生活艰难也许快乐', '剧情', '自上次一别已经过了八年时间，因为某件事，当年的好朋友贵田春彦（大野智 饰）、二叶廉太郎（松本润 饰）、冈野瞬（相叶雅纪 饰）和鸭川忠（樱井翔 饰）再度聚首。虽然恩田琢磨（二宫和也 饰）暂时缺席，不过并不妨碍四人坐在裸男酒馆里叙旧畅谈。留着夸张胡子的春彦娶了前女友的妈妈，头上绿帽光芒四射；忠总想给儿子注入男子汉气概，但和妻子的观念相左；廉太郎娶了奇葩的冲绳女郎，开起了蛋糕连锁店；瞬在事业上兜兜转转，突发奇想闯出自己的品牌。未过多久，一身奇怪打扮的琢磨带着庞大的家族成员加入进来。而今成为社会人年过三十的好朋友们，此时此刻又有着怎样的心情呢？©豆瓣', '相叶雅纪', '木村尚', 7.6, 6069, 'tt3914706', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2191915838.jpg', 1.4, 5.9, 32.3, 34.5, 25.9, '0.043047,0.039976,-0.350131,0.179853,-0.069524,-0.431494,0.388091,0.361096,-0.461934,-0.337977,-0.142004,0.474539,-0.259967,0.208806,0.396617,0.113637,-0.355887,-0.572156,0.044311,-0.039584,-0.148303,-0.309676,-0.053341,0.018347,-0.086629,-0.085858,0.358346,0.099102,0.020517,0.582977,0.454797,-0.016354,-0.117949,0.242678,-0.118693,0.053156,-0.033311,0.407532,-0.113822,-0.004032,0.044587,-0.210399,-0.021635,0.053424,0.232076,0.347585,0.386564,-0.158062,-0.238363,0.017418,0.148963,0.162299,-0.187983,-0.017504,0.255014,0.030827,0.251732,0.069558,0.001706,0.104660,-0.047304,-0.069924,-0.301474,0.084142,0.017414,-0.075060,-0.588877,0.601545,0.016696,-0.314453,0.059491,-0.103235,0.069352,0.351288,0.203105,0.182357,-0.240201,0.243989,-0.358098,0.336800,0.437922,0.239964,0.088867,0.117634,-0.023395,-0.187287,-0.206437,-0.312754,-0.243640,-0.143725,-0.092850,-0.009615,0.021909,-0.064972,-0.571732,0.032488,-0.092723,0.071868,0.454081,-0.322033,0.065244,-0.201900,0.015239,-0.504970,-0.399751,0.115984,0.246342,-0.057991,0.620625,-0.771880,0.032105,0.132907,0.367610,-0.376632,0.608623,-0.005354,-0.069415,-0.263698,-0.144979,-0.010762,-0.058181,0.059528,0.213430,0.481072,0.035527,-0.350359,-0.367175,0.012509', '35030151', '1292219', '1826173', '3091208');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25907004', '坏姐姐之拆婚联盟', '喜剧', '黄二珊（陈意涵 饰）是一名职业占星师，某日，她得知身处韩国的弟弟黄一峰（陈学冬 饰）即将和女友步入婚姻的殿堂，而那个女孩在星盘上却是黄一峰的克星，心急如焚的黄二珊想都没想就登上了驶往异国的飞机，势必要将两人拆散。在飞机上，喝醉的黄二珊邂逅了名为朴俊昊（池珍熙 饰）的男子，误打误撞之中，她竟然将自己的“毁婚”计划对朴俊昊和盘托出，哪知道这位深藏不露的大叔的真实身份竟然就是自己准弟媳妇的父亲。让黄二珊没有想到的是，朴俊昊竟然加入了自己的毁婚行动之中。在吵吵闹闹之间，两颗寂寞的心灵渐渐靠近，碰撞出了灿烂的爱情火花。©豆瓣', '陈意涵', '金泰均', 4.5, 10042, 'tt5234016', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2205689007.jpg', 23.6, 38.1, 29.8, 5.4, 3, '0.417336,0.290741,-0.849267,0.699139,-0.246961,-0.422674,0.756105,0.075632,-0.284526,-0.084321,0.440156,0.668814,-0.300308,0.290200,0.285517,0.163159,0.099281,-0.709112,-0.212007,-0.202894,-0.363658,-0.495921,-0.465386,0.119418,0.048195,-0.147383,0.550209,0.233971,-0.385656,0.258312,0.615152,0.110285,-0.089984,0.470861,-0.359685,0.049419,0.003313,0.306105,-0.212412,0.028933,-0.043988,-0.529387,0.077926,0.270656,-0.157565,0.249492,0.643370,-0.310538,-0.105454,0.025693,0.333829,-0.325490,-0.016511,0.275007,0.335162,-0.027696,0.130471,0.013400,-0.220792,-0.037826,0.175320,0.063665,-0.663892,0.258593,0.063042,0.130302,-0.692379,0.254414,-0.070355,-0.305360,0.201451,-0.428953,0.461408,0.271484,0.244744,0.308527,-0.270155,0.010428,-0.499910,0.210083,0.750678,0.072965,-0.000963,0.264227,-0.127595,-0.365204,-0.118178,-0.039402,-0.419494,-0.100146,0.329308,-0.104597,-0.050898,0.132252,-0.430607,0.073404,-0.249420,-0.060190,0.010181,-0.361257,-0.115978,-0.207353,-0.217006,-0.418244,-0.319657,0.158593,-0.032186,-0.246072,0.734811,-0.986669,0.214132,0.414424,0.261094,-0.525139,0.676650,0.256346,-0.054828,-0.287298,0.087682,0.000940,0.067823,0.174191,0.012259,0.543454,-0.073582,0.082900,-0.335169,0.453251', '1301022', '21360412', '35030151', '1870682');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25907029', '宝贝老板', '喜剧', '孩子到底是从哪里来的呢？不同于人们以往的认知，小Baby们竟然是批量生产的？！《娃娃老板》的主角小男孩Timothy本来是爸爸妈妈心中唯一的宝贝，可在一个穿着西装提着公文包的小婴儿的突然出现之后，他一下子就失宠了，爸爸妈妈的心思全都在弟弟身上，让他很是不爽。不过更让他 震惊的是，这个弟弟不仅穿得像个老板，还是个来自Baby公司肩负重任心思缜密的优秀员工？！为了赶紧摆脱这个小Baby，让爸爸妈妈重新回到自己的身边，Timothy必须和『弟弟』联手阻止Puppy公司颠覆世界的阴谋......', '亚历克·鲍德温', '汤姆·麦格拉思', 7.7, 95733, 'tt3874544', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2407336615.jpg', 0.4, 2.7, 30.9, 46, 20, '0.198721,0.046897,-0.739996,0.520148,-0.628638,-0.399016,0.692524,0.052525,-0.551575,-0.346158,0.146318,0.803754,-0.070436,0.544341,0.027441,0.152668,-0.239329,-0.562231,-0.363393,-0.183472,-0.391583,-0.335451,-0.268927,-0.000745,0.065982,-0.226855,0.578654,-0.124495,-0.035180,0.088731,0.625665,-0.010371,0.116111,0.611272,-0.425514,-0.109986,-0.198395,0.052655,0.160081,0.051379,0.194127,0.122427,-0.114806,0.382456,0.044084,0.234002,0.513706,-0.432152,-0.331343,-0.166246,0.449792,-0.069032,-0.144994,0.013193,0.068940,-0.185651,0.377947,-0.179810,-0.182657,0.163817,0.395885,-0.200743,-0.813166,0.261911,0.208414,0.041926,-0.845492,0.040025,-0.032004,-0.140837,0.308217,-0.568820,0.383730,0.372930,0.045250,0.751805,-0.429360,0.287816,-0.832351,-0.075458,0.662180,0.131248,0.085016,0.343536,-0.099372,-0.199727,-0.054672,-0.190526,-0.519684,0.244101,0.074266,-0.175862,-0.375193,0.215370,-0.524542,0.053886,-0.062568,-0.147028,0.128579,-0.782119,-0.195982,0.095925,-0.119695,-0.331091,-0.165973,0.007744,0.233338,-0.292147,1.077544,-0.966000,-0.006151,0.509034,0.113376,-0.688368,0.574311,0.128637,0.072543,-0.182206,-0.180452,-0.249343,0.052877,0.173262,0.027571,0.590651,0.017213,-0.445201,-0.236191,0.462202', '1877596', '24284209', '30163500', '1296770');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25907086', '爱情麻辣烫之情定终身', '爱情', '李小央（秦昊 饰）、刘家毅（何润东 饰）和高东华（周一围 饰）是大学时代的死党兼舍友，彼此之间感情十分要好。李小央一直默默喜欢着名为陈心（张梓琳 饰）的漂亮学妹，可是陈心只当李小央是对她关怀备至的大哥哥。刘家毅毕业之后成为了一名导游，他和女友杨菲（张歆艺 饰）交往多年，决定共同携手步入婚姻的殿堂。哪知道就在这个节骨眼上，一位名叫邓雨琪（黄灿灿 饰）的女游客走进了刘家毅的生活。那边厢，高东华和田小雅（田园 饰）结婚已经七年之久，在这七年里，高东华没少偷腥，但他自认为聪明过人，以为妻子一直被蒙在鼓中。然而，一次偶然之中，田小雅的一个秘密颠覆了高东华的整个世界。©豆瓣', '何润东', '肖飞', 5, 3483, 'tt6423542', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2322210657.jpg', 21.2, 27.9, 35.2, 10.3, 5.5, '0.246979,0.139018,-0.939463,0.585714,-0.408971,-0.312307,0.397311,-0.033995,-0.606075,-0.285068,-0.062392,0.815811,-0.340740,0.462236,0.021432,0.339000,0.124372,-0.798071,-0.088043,-0.487202,-0.173893,-0.492101,-0.256024,0.116340,-0.239099,-0.160951,0.338344,0.013878,0.116863,0.507118,0.467506,0.040375,-0.000890,0.184851,-0.242450,-0.010032,0.271911,0.416511,-0.336800,0.002787,-0.112183,-0.005346,-0.105101,0.074706,0.106888,0.085040,0.305285,-0.112952,-0.406151,0.028561,0.308426,-0.138714,-0.293956,0.097370,0.584905,0.004907,0.418214,0.311530,-0.078899,0.000786,0.008940,-0.175689,-0.244927,0.194074,0.157479,-0.146825,-0.691594,0.772333,0.097880,-0.218034,-0.071997,-0.280377,0.116117,0.265517,0.218533,0.416866,-0.168535,0.162581,-0.356910,0.366233,0.745681,0.254345,-0.076899,0.266763,0.005571,-0.186042,-0.133375,-0.008418,-0.596917,-0.001927,0.142865,-0.265215,-0.087736,0.075864,-0.321089,0.273931,-0.258760,0.284315,0.206489,-0.132319,-0.178770,-0.232426,-0.140312,-0.791423,-0.420454,0.199427,-0.041425,-0.470473,0.847536,-0.998665,0.324382,0.119504,0.520101,-0.594442,0.847183,0.233882,0.123230,-0.258056,-0.071153,0.000027,-0.203399,-0.074315,0.183357,0.335103,-0.248223,-0.328796,-0.473894,0.261876', '1292219', '1292720', '26354526', '1306544');
