INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25908042', '横冲直撞好莱坞', '喜剧', '何宇明（黄晓明 饰）一心扑在工作上，只希望能存够了钱，迎娶身在洛杉矶的女友，然而，让他没有想到的是，痴心付出等来的却是女友决定同他分手的消息。怎么也想不通的何宇明决定远赴洛杉矶，找女友当面问个清楚。就这样，他加入了名为“好莱坞冒险之旅”的旅行团。途中，何宇明结识了名叫方大伟（佟大为 饰）的骨灰级影迷和旅行团的导游赵薇薇（赵薇 饰），表面上相处融洽的三人并不知道的是，从他们加入旅行团的那一刻起，就已经被卷入了一场阴谋之中。电光火石之间，三人从碌碌无名的小卒，一下子变为了警方跨国追捕的走私通缉犯，他们展开了逃亡行动，并发誓要找出事件的真相。©豆瓣', '赵薇 Wei Zhao', '蒂姆·肯德尔', 4.5, 84789, 'tt4115932', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2240845701.jpg', 25.7, 37, 28.6, 5.8, 2.9, '0.305373,-0.176222,-0.708335,0.374927,0.055544,-0.235170,0.362756,0.045368,-0.393242,-0.101185,-0.011549,0.785250,-0.259837,0.025907,0.310850,0.105256,-0.149402,-0.777410,-0.143466,-0.250046,-0.029011,-0.603450,-0.116740,-0.119732,0.046298,0.034791,0.592440,0.278355,-0.192528,0.693808,0.488997,0.045095,-0.340733,0.690559,-0.062672,0.037377,0.095074,0.332145,-0.309806,0.285543,0.127875,-0.341350,0.050426,0.327509,0.132155,0.548719,0.502609,-0.083691,0.021657,0.200761,0.150797,-0.524763,-0.009666,-0.001149,0.291245,0.068235,0.236621,0.212569,-0.260173,0.008723,-0.063223,-0.137791,-0.723296,0.256517,0.189701,0.144984,-0.837873,0.224652,-0.131904,0.073654,0.094998,-0.147723,0.337143,0.447627,0.193073,0.147722,0.013076,0.036513,-0.524033,0.252173,0.952557,0.092271,0.044507,0.269256,0.049981,-0.381994,-0.059624,0.040185,-0.142822,-0.080810,0.374569,0.086378,-0.221960,-0.057396,-0.606756,-0.058225,-0.347790,-0.050870,0.132713,-0.290219,0.076582,-0.457639,-0.242033,-0.250857,-0.288196,0.025277,0.028653,-0.360329,0.490604,-0.813872,0.104149,0.535469,0.294744,-0.719958,0.792704,0.201666,0.065044,-0.152714,0.274968,-0.109565,0.037813,0.346885,0.113304,0.131370,0.057531,-0.435836,-0.199636,0.137158', '4604803', '1301022', '2990737', '1897368');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25908051', '间谍之桥', '剧情', '冷战初期，纽约律师詹姆斯·多诺万（汤姆·汉克斯 Tom Hanks 饰），为苏联情报员鲁道夫·阿贝尔（马克·里朗斯 Mark Rylance 饰）辩护，当时美苏关系紧张，詹姆斯仍然秉持公平正义的原则，毫不偏私地为阿贝尔抗辩，阿尔贝欣赏他的正直，他也欣赏阿贝尔的忠诚，虽然最后输了官司，两人却建立起微妙的情谊。不久之后，美军U2高空侦察机在执行机密任务时，被苏联军方击落，詹姆斯受雇于中情局，代表美方与苏联谈判，试图在极其渺茫的机会中，与苏联交涉换囚条件，营救被劫持的美国飞行员。影片根据美国律师詹姆斯·多诺万真实经历改编。', '汤姆·汉克斯', '史蒂文·斯皮尔伯格', 8.2, 97367, 'tt3682448', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2247974249.jpg', 0.2, 1, 17.6, 53.2, 27.9, '0.201197,0.223076,-0.758301,0.719764,-0.007430,-0.475427,0.233520,-0.057063,-0.416642,-0.041142,0.327265,0.750468,0.058855,-0.341919,0.285516,-0.067257,-0.667145,-0.770848,-0.050755,0.190142,-0.016454,-0.944691,-0.546993,-0.494671,-0.441241,-0.007466,0.534673,0.097361,-0.202730,0.313740,0.191703,0.464823,-0.006109,0.309590,0.254950,-0.374650,0.483185,-0.218911,-0.709959,0.100447,0.055197,-0.141751,-0.139509,0.161005,0.146373,0.750907,0.283377,-0.059900,0.038194,-0.240690,0.187385,-0.246823,0.165798,0.182419,0.204325,0.168525,0.043268,0.446235,0.032283,-0.003531,-0.219635,0.038185,-0.527482,0.041339,-0.175874,0.256304,-0.119247,0.493623,-0.573352,0.312622,0.081924,-0.051386,-0.137238,0.382815,0.294479,0.046502,-0.085908,0.180062,-0.195267,0.132947,0.474799,0.157755,-0.301228,-0.138336,-0.346700,-0.472711,0.246014,-0.339026,-0.175815,-0.027350,0.348982,-0.195248,0.126469,0.412469,-0.513893,0.040871,-0.558074,-0.061702,-0.407593,-0.354660,0.273210,-0.856146,-0.051891,-0.373441,-0.540689,-0.068062,-0.027387,0.004964,0.507545,-0.588747,-0.047698,0.447559,0.249079,-0.157365,0.408462,0.410756,0.219573,-0.511983,0.043922,0.377949,-0.146872,0.074993,-0.016596,0.134304,0.200791,-0.135506,-0.050057,0.244872', '1293537', '1293572', '1307442', '3006781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25908065', '我们的十年', '剧情', '张静依（赵丽颖 饰）、陈伊诺（吴映洁 饰）和梁小艺（班嘉佳 饰）是大学时代的同窗兼好友，三个姑娘之间感情十分要好。温柔贤淑弹得一手好钢琴的陈伊诺是校园里的校花级人物，追求她的男生数不胜数，而个性大大咧咧不拘小节的张静依则甘愿成为绿叶，衬的一朵红花更加的娇艳。一次偶然之中，张静依和陈伊诺结识了名为郭宇辰（乔任梁 饰）的男生，后者的潇洒和智慧很快就吸引了陈伊诺的注意，看着闺蜜终于坠入了情网，张静依义不容辞的充当起了军师的角色，为好友出谋划策。可是，在此过程中，张静依渐渐发现了自己内心里对于郭宇辰的感情，而郭宇辰似乎也更喜欢能够轻松相处的张静依。©豆瓣', '赵丽颖', '马伟豪', 5.8, 16712, 'Days of Our Own', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2375677172.jpg', 19.5, 23.2, 26.1, 10.1, 21, '0.486451,0.085810,-0.343164,0.844809,-0.149360,-0.117495,0.748339,0.204877,-0.731424,0.118404,-0.095000,0.550561,-0.320466,0.431887,0.523763,-0.101486,-0.144714,-0.885679,-0.366461,-0.230526,-0.327933,-0.510566,-0.306841,0.188855,-0.282388,-0.315465,0.614491,-0.064862,-0.031450,0.698994,0.383622,0.355422,0.023604,0.298305,-0.152565,-0.201927,-0.198888,0.177576,-0.153458,0.070016,0.046800,-0.119064,-0.088365,0.105904,0.074348,0.302112,0.702756,-0.164245,-0.244628,-0.186069,0.583276,0.119117,0.271106,-0.038146,0.279734,0.024889,0.396706,0.042717,-0.250340,0.083139,0.093404,-0.212547,-0.701588,0.040963,0.489317,-0.015499,-0.615206,0.347242,0.199122,-0.372338,0.169691,-0.096068,0.109823,0.119503,0.296407,0.406226,-0.110933,-0.043959,-0.339701,0.248169,0.372644,0.589856,-0.101062,0.740468,-0.254439,-0.528420,-0.127857,-0.139874,-0.539500,0.147630,0.088706,0.043556,0.210011,0.086387,-0.434884,-0.035628,0.059012,0.301131,-0.077619,-0.579673,-0.057639,-0.201030,-0.347263,-0.568945,-0.311895,0.150301,-0.187241,-0.346737,1.014444,-1.114682,-0.193126,0.108270,0.167068,-0.206193,0.732949,0.087539,-0.033431,-0.124954,0.106509,0.067863,-0.114377,-0.173448,0.129171,0.744697,-0.169234,-0.368954,-0.218521,0.418219', '4127270', '6963575', '3445516', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25908302', '爸爸的假期', '喜剧', '某外企高管老郭（郭涛 饰）的婚姻进入七年之痒，一心扑在工作上的他和妻儿疏于交流，而事业也进入了困顿起。老实木讷的小编剧岳伦儿（王岳伦 饰）饱受欺凌，软弱无能，此刻也经历着来自家庭和事业的双重压力。英俊帅气的模特亮子（张亮 饰）奋力打拼却没有出头天，家庭琐事更令他不过气来。三个痛苦难耐的大男孩在田教练（田亮 饰）的建议下前往韩国参加一个名为“帝王假期”的旅游活动，谁知竟遭遇了国际大盗Jimmy Lin（林志颖 饰）的搅局。没有放松，没有言语，只有险象环生、惊险刺激的各种冒险，性格各异的爸爸们在异国他乡夺路狂奔……©豆瓣', '郭涛', '王岳伦', 4, 14361, 'tt4084042', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2224242410.jpg', 37.3, 34.5, 21.5, 4, 2.6, '0.070791,-0.202749,-0.761584,0.484050,-0.151527,-0.292057,0.635346,0.314885,-0.482288,-0.397383,0.225324,0.532706,-0.136642,0.408206,0.024110,-0.306739,-0.048321,-0.592905,-0.270712,0.284954,-0.010028,-0.191803,-0.177312,-0.137445,-0.364544,-0.120148,0.544813,-0.025005,-0.322674,0.617610,0.521526,0.052206,-0.040326,0.425328,-0.151987,0.076085,0.148632,0.372839,-0.137682,-0.066251,0.134020,-0.335178,-0.194157,-0.022920,0.246918,0.471630,0.611393,-0.159140,-0.147470,-0.044647,0.413748,-0.125845,-0.221747,0.105667,0.206405,0.037879,0.122258,-0.048765,-0.117251,0.112792,0.282783,-0.173863,-0.738232,0.089642,0.094134,0.232787,-0.833687,0.620781,-0.041464,-0.140390,-0.032702,-0.342488,-0.007093,0.410756,0.097655,0.266336,-0.083276,0.428233,-0.226452,0.580610,0.885110,0.333152,-0.228038,0.193126,-0.529036,-0.371962,0.050238,-0.424058,-0.531813,-0.342956,0.304129,-0.182287,-0.198670,0.152952,-0.568994,0.279845,0.025375,-0.129371,-0.216094,-0.187059,-0.052544,-0.624592,-0.000992,-0.536039,-0.373895,0.197709,0.040294,-0.235508,0.807524,-0.866036,0.061039,0.325312,0.296116,-0.586760,0.836860,0.214104,0.047712,-0.105771,-0.090530,0.433265,-0.196007,0.252200,0.089457,0.272682,-0.439703,-0.225470,-0.337893,0.391877', '35030151', '35144311', '1870682', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25909236', '致命感应', '悬疑', '麦迪森（安娜贝拉·沃丽丝 Annabelle Wallis 饰）在梦中不断看到恐怖谋杀案现场的幻象，而这些幻象实际上是真实发生过的凶案，她决定挖掘真相和自己的过去，却发现这一切与一位名叫“盖博瑞”的魔鬼有关。', '安娜贝拉·沃丽丝', '温子仁', 6.7, 74497, 'tt3811906', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2672792129.jpg', 0.9, 8.5, 48.5, 36.3, 5.7, '0.346084,0.070360,-0.998021,0.423139,-0.259821,0.196708,1.641312,-0.557200,-0.685649,-0.810083,0.295450,0.793214,-0.700139,0.288633,0.135691,0.185237,-0.379662,-0.890244,-0.096496,-0.217123,-0.388949,-0.528551,-0.494529,-0.136879,0.035656,-0.008960,0.569487,0.295803,-0.148532,0.259373,0.381608,0.517260,-0.602750,0.417816,-0.106295,0.171469,-0.077666,0.132670,-0.437014,-0.063882,0.058463,-0.187706,-0.283829,0.617695,-0.135638,0.256731,0.588241,-0.741471,-0.466451,0.214273,0.533709,-0.374276,0.006449,0.370669,0.204405,0.207795,0.269163,0.076081,-0.103631,-0.256768,-0.235305,0.160728,-1.111761,-0.159233,0.265870,0.771028,-0.279035,0.001931,0.004120,-0.136640,0.383749,-0.464908,0.249926,0.298944,0.471412,0.390171,-0.195631,-0.318687,-0.672712,0.126449,0.973206,-0.002129,-0.422802,0.708907,-0.023090,-0.226933,-0.415508,0.160452,-0.047261,0.533874,0.099079,0.259717,-0.345108,0.674774,-0.389049,-0.260496,-0.293637,-0.282989,-0.489103,-0.448714,-0.417135,-0.407882,-0.447970,-0.652444,-0.466023,-0.107668,-0.228647,-0.474696,0.270093,-0.890796,0.348432,0.808202,-0.001241,-0.120901,0.303175,-0.003002,0.032909,-0.195738,-0.252399,0.330864,0.269308,0.309889,-0.157531,0.549251,0.471674,-0.098522,-0.769784,0.496778', '20451118', '25828589', '1428054', '1292528');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25909389', '亡命救赎', '动作', 'Lydia很小的时候父亲就进了监狱，她从小和母亲生活在一起，但骨子里继承了父亲Link的基因，十分叛逆。一次闯下大祸后，Lydia走投无路联系到多年未曾见面的父亲，Link已经退隐江湖很多年，在拖车里以纹身为生。为了解决女儿的困境，他鼓起勇气挺起胸膛，以父亲的身份对决Jonah一行人，用鲜血为女儿换来了重生……', '梅尔·吉布森', '让-弗朗索瓦·雷切', 5.8, 7685, 'tt3647498', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2539779201.jpg', 3.9, 24.4, 53.3, 14.3, 4.1, '-0.111670,0.224053,-0.878749,0.694576,-0.629269,-0.710201,0.694483,0.055486,-0.900793,-0.436083,0.255199,1.134068,0.139695,0.636433,0.051391,0.080346,0.166637,-0.704161,0.053904,-0.202622,-0.625331,-0.324537,-0.106236,-0.053011,-0.237228,-0.412288,0.891696,-0.023741,-0.086423,0.362313,0.149280,0.177164,-0.036264,0.362319,-0.529018,-0.118010,-0.218990,0.318190,-0.482412,0.220268,0.131903,-0.183031,-0.102470,0.117025,-0.059663,0.266095,0.704256,-0.135284,-0.040931,-0.329998,0.181266,-0.118788,-0.282320,0.239033,0.539574,-0.015472,0.515340,0.467323,-0.271478,-0.169831,-0.228666,-0.105885,-0.648649,-0.217824,-0.251272,-0.231206,-1.083023,0.538355,-0.040299,-0.068459,0.161503,-0.683717,0.063527,0.358566,0.186654,0.394302,-0.576308,-0.024089,-0.484059,-0.004521,1.021567,-0.339395,0.132944,0.421083,-0.107721,-0.167464,0.291424,-0.736684,-0.371527,0.144773,0.044576,0.068449,-0.769113,0.350012,-0.246960,-0.100588,-0.304847,0.199673,0.452863,-0.443424,-0.012953,-0.285880,-0.674838,-0.376356,-0.248666,0.055924,-0.060972,-0.365796,0.564964,-1.050501,0.235636,0.205192,0.216502,-0.790342,0.685719,0.069804,0.107384,-0.421368,0.370026,0.417660,0.128854,0.197344,0.208150,0.059183,-0.101701,0.153817,-0.372798,0.631310', '25721544', '30345227', '1299965', '34968329');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25909566', '足不出户', '喜剧', '吸毒成瘾凯莉·巴克奈尔（Morgana O''Reilly 饰）和同伴抢劫取款机，结果被警方抓个正着。在此之后，她被法官判处家中监禁八个月。凯莉的老家位于一处偏远小镇，母亲米莉亚（Rima Te Wiata 饰）现正和另一个男人居住。在被装上监控装置后，凯莉失去了自由，每日只能蜷缩在这幢老旧破败的房子内。某天，她听广播时意外发现母亲向电台打进了热线，米莉亚声称曾在家中的地下室见过鬼影，这让她惶恐不安。凯莉一向反感妈妈神神叨叨的言行，可是没过多少天，她便真的遭遇了一连串的奇怪事件。在法律禁止逃离的情况下，凯莉只能求助于对灵异事件感兴趣的保安员阿莫斯（格伦-保罗·瓦鲁 Glen-Paul Waru 饰）。生死考验，迫在眉睫……©豆瓣', '莫嘉娜·奥莱利', '热拉尔·约翰斯通', 7.2, 14732, 'tt3504048', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2188143871.jpg', 1.4, 6.1, 35.5, 43.4, 13.6, '0.348258,-0.076996,-0.842636,0.144816,0.086940,-0.067585,0.931027,0.109023,-0.693724,-0.223627,0.377538,0.380333,-0.325560,0.252900,0.140641,0.230127,-0.517803,-0.432289,-0.010953,-0.362046,-0.442355,-0.559283,-0.184149,-0.318284,0.072543,-0.365679,0.090647,-0.072614,-0.120709,0.143247,0.060115,0.408746,-0.312028,0.357261,-0.223348,0.149742,0.257360,-0.145783,-0.079915,0.085531,-0.042715,-0.219265,-0.163505,0.109503,0.216260,0.525336,0.642728,-0.368610,-0.451409,0.052407,0.263861,-0.196718,-0.141768,0.369377,0.346977,0.052013,0.329439,0.195226,-0.281064,-0.142636,0.149857,0.044622,-0.343570,0.077543,-0.225786,0.182200,-0.519844,0.514821,-0.306514,0.099038,-0.071306,-0.511334,0.248350,0.142768,0.020930,0.493384,-0.192664,0.065194,-0.414042,0.065357,0.463065,0.061837,-0.266259,0.271230,-0.024350,-0.353948,-0.036912,-0.009003,-0.505559,-0.069645,0.351260,-0.131416,-0.266179,-0.044339,-0.202653,0.081992,-0.369519,-0.283717,-0.115964,-0.031255,-0.416071,-0.532709,0.055597,-0.186130,-0.390210,0.063200,-0.185793,0.071254,0.305385,-0.730728,0.559553,0.656472,0.397302,-0.314423,0.582937,0.134637,0.152891,0.116202,-0.179156,0.129998,0.193816,0.648216,0.232903,0.265487,-0.068842,-0.244506,-0.302352,0.173765', '1908318', '20451118', '1302488', '4724373');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25911595', '第三种爱情', '爱情', '邹雨（刘亦菲 饰）是一名律师，事业有成的她却遭遇了婚姻的不幸，与此同时，她的妹妹邹月（孟佳 饰）亦因为陷入了同财团二公子林启正（宋承宪 饰）的苦恋之中而想不开企图自杀。愤怒的邹雨找到林启正想要替妹妹讨回公道，却发现妹妹不过是一厢情愿，林启正实则无辜。一场意外让邹雨再度 遇见了林启正，随着时间的推移，邹雨的坚强和善良渐渐吸引了林启正，后者对其展开了热烈的追求。一直暗恋邹雨的同事高展旗（欧弟 饰）告诫邹雨远离林启正，而邹月对林启正的痴情和疯狂亦让邹雨对她心中火热的感情充满了不安和犹豫。种种波折之后，邹雨和林启正最终走到了一起，可就在此时，横空杀出的林启正的青梅竹马江心瑶（江语晨 饰）让两人的感情再度陷入了动荡之中。©豆瓣', '刘亦菲', '李宰汉', 5.2, 72996, 'tt5057982', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2267236332.jpg', 15.1, 31.9, 35.8, 10.4, 6.7, '0.191340,0.086625,-0.662879,0.619296,0.033657,-0.445460,1.200944,0.155573,-0.503771,-0.034021,0.190594,0.495577,-0.372515,0.254136,0.369046,-0.012463,0.021644,-0.910513,-0.158435,-0.027291,-0.047174,-0.484365,-0.197406,-0.068388,-0.192975,-0.171002,0.688362,0.109671,-0.064595,0.825435,0.548288,0.333187,-0.150477,0.652601,0.124803,0.062066,-0.017939,0.235066,-0.359206,0.009390,0.288361,-0.469476,0.032919,0.389218,-0.159160,0.504423,0.617119,-0.116073,-0.168504,0.069156,0.317053,-0.410982,0.033561,0.131633,0.263048,0.077510,0.282599,0.184321,-0.549477,-0.179003,0.106851,0.048459,-0.477442,0.181242,0.225985,0.089483,-0.552854,0.635795,-0.026142,-0.315992,0.213660,0.009668,0.222547,0.383006,0.452158,0.324706,-0.536064,0.002518,0.085636,-0.052220,0.671877,0.309666,-0.022225,0.453372,-0.206574,-0.305468,0.031735,-0.040235,-0.649383,-0.121732,0.439281,0.274559,-0.032281,0.411102,-0.606645,-0.117114,-0.119626,0.064040,-0.058764,-0.665121,-0.022712,-0.069662,-0.385186,-0.518208,-0.430991,0.208052,-0.068005,-0.314826,0.728502,-0.930582,0.149679,0.309683,0.390558,-0.582117,0.600085,0.199327,-0.197839,-0.071969,0.093924,0.300023,-0.311943,0.044621,0.138731,0.219509,-0.191488,-0.039804,-0.389013,0.222964', '2131640', '3111650', '1308755', '1307748');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25911694', '摆渡人', '喜剧', '摆渡人是城市里的超级英雄，摆渡就是把人从痛苦中解救出来。用快乐和温暖，抵抗这个世界的悲伤。酒吧老板陈末（梁朝伟 饰）和合伙人管春（金城武 饰）就是这座城市的“金牌摆渡人”，他们平时看起来吊儿郎当，却从不对每位需要帮助的人说拒绝，只要你“预约摆渡”，刀山火海都会“使命必达”。邻居女孩小玉（杨颖 饰）为了偶像马力（陈奕迅 饰），预约了他们的服务，但在帮助小玉挑战整个城市的过程中，陈末和管春也逐渐发现了自己躲不过的问题。从欢天喜地的生活，到惊天动地的疯狂，摆渡人最辉煌的篇章，从这里开启。', '梁朝伟', '张嘉佳', 4.1, 229172, 'tt3824950', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2390687452.jpg', 43.8, 24.6, 19.4, 7.2, 5, '-0.056875,0.112135,-0.568779,0.475430,-0.341072,-0.034427,0.778699,0.088208,-0.530493,0.061487,0.245146,0.786495,0.082373,0.197293,0.292732,0.033189,-0.204913,-0.535636,0.031877,-0.171112,-0.379808,-0.315883,-0.188552,-0.386591,-0.077753,-0.407755,0.499076,0.131806,-0.234446,0.263847,0.250099,0.106602,-0.138779,0.696436,-0.262303,-0.175255,0.022970,0.176227,-0.296641,0.151196,-0.386600,-0.207558,-0.186595,0.283930,0.071950,0.372371,0.387554,-0.260408,-0.169452,0.169217,0.083131,-0.141198,-0.167859,-0.141720,0.027400,-0.271654,0.417076,0.272409,-0.110841,-0.001181,-0.018074,-0.217453,-0.888043,-0.008825,0.232661,0.189911,-0.607703,0.414723,0.012005,-0.182107,0.196480,-0.265531,0.444518,0.101032,0.246177,0.454651,-0.249622,0.014135,-0.510518,0.386751,0.462884,-0.191940,-0.123932,0.610539,-0.273879,-0.401339,-0.203710,-0.071407,-0.611362,-0.063957,-0.117294,0.014970,-0.176197,-0.065397,-0.792721,0.116222,0.048603,-0.303266,-0.161711,-0.471121,-0.112137,-0.531718,-0.035661,-0.290431,-0.033316,0.150100,0.134334,-0.206227,0.952436,-0.808400,0.066132,0.535773,0.484619,-0.338063,0.933107,0.040781,-0.021032,-0.399154,-0.026953,0.199880,0.023366,0.354046,-0.023105,0.381490,-0.034470,-0.141973,-0.392573,0.709461', '3230462', '1793491', '1302661', '1783461');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25912924', '暗杀教室 真人版', '剧情', '名门高中椚椚丘中学的垫底班级3年E班，在新一学年迎来了一个奇怪的老师（二宫和也 配音）。这个老师长着圆圆的黄色大脑袋以及黏滑恶心的触角，原来他就是不久前将月亮炸成月牙的罪魁祸首。日本防务省特种部队的精英乌间惟臣（椎名桔平 饰）向学生们介绍了怪物的情况，他拥有20马赫的超快速度，人类寻常的武器对他完全不起作用。为了阻止怪物一年后摧毁地球的阴谋，人类必须想方设法除掉他。而怪物自告奋勇愿意出任3年E班的班主任，于是乎手无缚鸡之力的学生们担当起刺杀怪物的重任。此后，学生们接受了乌间的严格培训，而杀手比琪（知英 饰）、智能机器人自律思考固定炮台（桥本环奈 饰）、转学生堀部系成（加藤清史郎 饰）以及教官鹰冈明（高岛政伸 饰）等强大对手也相继来到这间暗杀教室内，搞怪的“杀老师”将面临永无止息的刺杀行动……本片根据松井优征的超人气漫画改编。©豆瓣', '山田凉介', '羽住英一郎', 6.5, 16868, 'tt3853452', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2216800764.jpg', 2.6, 12, 51.3, 24.4, 9.8, '0.113072,-0.301460,-0.203788,0.413225,-0.201374,0.066980,0.355836,0.051532,-0.229281,-0.322534,0.315599,0.332890,-0.015397,0.209960,0.203248,-0.329143,-0.050375,-0.699648,-0.128625,-0.286453,-0.413872,-0.336652,-0.053282,-0.472705,0.042781,-0.341623,0.621746,-0.023938,-0.123080,0.501297,0.283174,0.204432,0.069660,-0.071885,0.026596,-0.167329,0.128471,-0.042837,0.052659,0.122462,-0.291377,-0.063605,-0.134562,-0.014783,0.084601,0.219814,0.750074,-0.212972,0.000391,-0.382791,0.222674,-0.398410,-0.211784,0.215760,0.732131,0.191538,-0.093777,0.047929,0.135709,0.185244,0.046848,-0.233024,-0.462893,-0.035988,0.067919,0.011212,-0.265865,0.367340,-0.028262,0.001151,0.113331,-0.150513,-0.200786,0.100681,0.279857,0.250861,-0.170060,0.317170,-0.015209,0.296310,0.208485,-0.135421,-0.395672,-0.053349,-0.089245,-0.467355,-0.130123,-0.374142,-0.093777,-0.022634,0.141911,0.067201,-0.030237,0.126477,-0.446752,-0.170972,-0.135725,-0.160390,0.065413,-0.295956,-0.132186,-0.590698,0.178664,-0.163990,-0.174660,0.328690,0.184193,-0.184484,0.988949,-0.832339,-0.089945,0.477948,0.242784,-0.292829,0.396561,-0.095845,0.005344,-0.228130,-0.119604,-0.119447,0.298360,0.647304,0.035452,0.531617,-0.036895,-0.336860,-0.215342,0.124522', '25922902', '26999591', '1826173', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25917239', '浴血华沙', '剧情', '在华沙起义爆发前不久，一群当地的年轻人加入了地下组织，不仅是为了履行爱国 义务，同时也开启了一段青春冒险，可以跟同龄人吹嘘还可以吸引女孩子。在地下组织培训时，他们边调情、炫耀，边制订计划，殊不知接下来的那个夏天将是他们生命的考验，而历史已经为他们做好了计划。 他们成为华沙起义战斗中最为勇敢的组织之一，共同见证了牺牲精神和英雄气概，也看见了残忍、背叛与谋杀；他们懂得了爱，也体会了什么叫仇恨。尽管他们不情愿，历史还是在他们成熟的过程中，给他们上了血腥残酷的一课……', '乔瑟夫·帕夫洛夫斯基', '扬·科马萨', 7.6, 12924, 'tt3765326', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2239016308.jpg', 0.9, 4.1, 29.2, 45.1, 20.7, '0.171390,0.057191,-0.677867,0.497168,-0.504080,-0.150037,0.312463,-0.160839,-0.441020,0.180037,0.106750,0.718876,0.122088,-0.031649,0.272795,-0.284984,-0.417138,-0.833171,-0.083967,-0.093551,-0.285427,-0.580717,-0.243915,-0.380173,-0.106452,-0.402046,0.597286,0.360936,-0.393355,0.457955,0.302096,-0.064781,-0.007623,0.490275,-0.185243,-0.186516,0.319998,-0.014589,-0.534300,-0.026307,-0.085641,-0.360552,-0.245883,0.326775,-0.070726,0.304500,0.473907,-0.242447,-0.226692,-0.254330,0.201469,-0.526241,-0.006471,0.284028,0.210948,0.023240,0.188577,0.508242,0.146708,-0.105830,-0.254729,-0.186847,-1.343048,-0.248933,0.013963,-0.082034,-0.700249,0.688041,0.167780,-0.109350,0.346034,-0.023209,0.324362,0.545902,0.386258,0.226274,-0.184672,-0.180959,-0.429945,0.300954,1.120432,-0.188341,0.000752,0.410080,-0.318506,-0.360320,-0.060352,-0.304218,-0.219482,-0.109170,0.117085,-0.031891,-0.246153,0.150808,-0.720516,-0.038083,-0.088174,-0.229953,0.086874,-0.593910,0.065189,-0.411184,-0.448197,-0.477593,-0.395348,0.179129,-0.001335,-0.196031,1.097097,-0.953510,0.141626,0.760159,0.561560,-0.664572,0.652841,0.390204,0.126364,-0.288599,0.048834,0.072440,-0.219295,0.297416,0.171917,0.403963,0.097307,-0.079961,-0.484192,0.567379', '26678784', '30163500', '1793491', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25917789', '铁血战士', '动作', '一艘宇宙飞船坠落地球，正在执行军事任务的狙击手奎因·麦肯纳（波伊德·霍布鲁克 饰演）恰好遭遇外星人并发生激战，侥幸逃脱的他捡到了外星人的装备并寄回了家想再做他用。传说这种被称为铁血战士的外星人曾数次光临地球，使用各种残忍的手段对人类进行猎杀游戏。而这一次，奎因的儿子罗里 收到包裹后意外触发机关，引来了更强大的终极铁血战士降临地球。而想要阻止其大开杀戒的却是一群问题士兵和一位生物科学家凯茜·布拉克（奥立薇娅·玛恩 饰演）。事情却远不像他们想象的那样简单，一场铁血、终极铁血与人类之间的三方猎杀大战正式拉响！', '波伊德·霍布鲁克', '沙恩·布莱克', 4.9, 50810, 'tt3829266', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2537399580.jpg', 11.8, 40.4, 38.9, 6.9, 2, '0.190535,-0.012560,-0.615324,0.594253,-0.085185,0.149013,0.795621,-0.351610,-0.187450,-0.365034,0.452789,0.643575,-0.015966,-0.379332,0.260960,-0.302302,-0.242542,-0.354540,0.202587,0.163045,-0.411746,-0.289912,-0.415530,-0.404333,0.287470,-0.486022,0.768465,0.077504,-0.608617,0.341029,0.202818,0.506179,-0.232528,0.473290,-0.191720,-0.213873,0.071835,0.232919,-0.191052,0.299102,-0.293483,0.184671,-0.142143,0.167063,-0.164181,0.237126,0.421506,-0.501959,-0.197359,-0.322251,0.010286,-0.437098,0.031889,-0.046361,0.525303,-0.166981,-0.210973,-0.028005,0.473952,-0.005176,0.055269,0.089252,-0.931166,-0.199047,-0.111149,-0.008666,-0.230574,0.073008,-0.208631,0.391385,-0.060726,0.131310,0.012548,0.408731,0.427505,0.192254,-0.134719,-0.090862,-0.395781,0.225904,0.664115,-0.223611,-0.661598,0.230683,-0.013906,-0.621499,-0.290856,-0.524133,-0.161607,0.257742,0.246402,0.074818,-0.264550,0.491523,-0.858679,0.028926,-0.305873,-0.229178,-0.051256,-0.206619,-0.044876,-0.978411,0.010765,-0.092740,-0.480913,0.174754,0.140106,-0.184948,0.673148,-0.652627,0.285524,0.511163,0.413337,-0.517512,0.176917,0.102851,0.151073,-0.239314,-0.000440,0.201529,0.244760,0.414148,0.108665,0.296342,0.109955,-0.182269,-0.148288,0.506933', '2369613', '26667010', '1306809', '1578502');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25917973', '心迷宫', '剧情', '一个想要挣脱父权控制的青年，在一次争执中失手杀死了同村的痞子，被迫逃亡。他没有想过会用这样的方式逃离安逸的生活，离开之际却惊人的发现宿命早已将他和专制的父亲紧紧连接在一起，走或留他都将失去一切。一个饱受家庭暴力摧残的留守女人，在曾经恋人的怀抱里找到了慰藉。黑暗里绝望的女人与情夫密谋杀夫，可当莽夫的死讯真的传来时，情夫却避而不见矢口否认一切。当女人又一次陷入绝望，另一个男人出现在她的生活里，他给女人带来的不仅仅是关心……一个行为正直严格自律的老村长，精心设计着自己退休后的晚年生活。一生忠诚于信仰的他，却在本性面前轻易地低下了头；一个污点掉落在命运蓝图上，他竭力去擦掉污迹，却剥开了一个黑洞，深陷其中。', '霍卫民', '忻钰坤', 8.7, 479730, 'tt4078856', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2276780256.jpg', 0.2, 0.7, 8.4, 43.1, 47.5, '0.159325,0.309290,-0.765727,0.696131,-0.690510,-0.358313,1.328398,0.003593,-0.397839,-0.192702,0.288062,0.866789,0.101664,0.269618,-0.019532,0.005015,-0.100036,-0.907764,-0.233698,-0.002601,-0.392041,-0.302485,-0.312084,-0.179896,-0.258255,-0.134840,0.858666,0.068662,-0.355498,0.231178,0.284898,0.149136,-0.186891,0.683521,-0.407540,-0.045129,-0.062315,-0.108268,-0.196232,0.181142,0.056928,-0.420968,-0.148062,0.412032,-0.455320,0.278825,0.714291,-0.625103,-0.098148,-0.131768,0.332046,-0.428692,-0.290305,0.314572,-0.019086,0.008506,0.140804,0.092970,-0.355685,-0.114557,0.346311,0.027399,-0.799984,-0.206063,-0.158620,0.214651,-0.824440,0.566182,0.041730,0.044344,0.136062,-0.468819,0.212391,0.049959,0.240529,0.556610,-0.398045,0.200221,-0.367868,0.064643,0.799995,-0.111322,-0.276064,0.200089,-0.344434,-0.228447,0.178882,-0.264305,-0.712442,-0.218099,0.398483,0.069296,-0.551229,0.368930,-0.394711,0.165743,-0.374800,0.022965,-0.168388,-0.558177,-0.399490,-0.039905,-0.290077,-0.143481,-0.488602,0.189661,-0.166484,-0.304284,0.508398,-0.735430,0.331764,0.562970,0.373230,-0.460353,0.754863,0.358387,0.103157,-0.062547,0.000182,0.425369,0.165973,0.348055,0.239660,0.298653,-0.335975,0.388958,-0.503577,0.741315', '26884422', '21619567', '26920017', '1428054');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25918597', '爱情进化论', '喜剧', '正值适婚年龄的单身女青年安安（郭碧婷 饰）是位普通的广告公司白领，她为了摆脱前男友的骚扰搬家，新邻居是一对兄妹，哥哥潘小哲（段奕宏 饰）是喜欢用生物学知识看待一切日常事务的生物学博士后，妹妹潘小星（刘雅瑟 饰）乐观开朗。一次广告提案的竞争中，平日里常常让人哭笑不得的潘小哲用生物学知识意外地帮到了安安，安安得以顺利升职。安安的广告公司被收购，美国总部空降来了年轻英俊的运营总监黎夏（戴立忍 饰）。安安对黎夏暗生情愫。在好朋友周佳妮（谢依霖 饰）的提醒下，曾经在感情上屡经挫败的安安意识到感情的规则和进化论一样：弱者淘汰，适者生存。她决定请潘小哲帮忙，运用生物学的科学知识帮自己谈一场成功恋爱……©豆瓣', '段奕宏', '刘荣艳', 4.4, 6887, 'tt11151636', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2194649873.jpg', 29.2, 33.7, 27.1, 6.2, 3.8, '0.289232,0.129586,-0.367761,0.321765,-0.379370,-0.198479,0.133116,0.121097,-0.554572,-0.140511,0.208010,0.512340,-0.098492,0.313634,0.127928,0.075305,-0.038194,-0.431159,0.001777,-0.070719,-0.193355,-0.514334,-0.286625,0.123963,-0.112017,-0.363482,0.467606,-0.302653,-0.233576,0.602666,0.096667,0.141774,0.015286,0.252557,0.032561,-0.193633,0.075683,0.051377,-0.595392,-0.018641,-0.048647,0.105300,0.073996,-0.069180,0.075029,0.309964,0.522761,0.172012,-0.165840,0.012759,0.438577,-0.184351,-0.183604,0.107223,0.429287,0.208020,0.174778,0.185404,-0.098246,0.108516,-0.103992,-0.134682,-0.561631,-0.025100,0.158175,0.111315,-0.632117,0.465596,-0.056920,-0.003607,0.082281,-0.441579,-0.102058,0.156557,0.379377,0.500303,0.035753,0.388888,-0.177535,0.411318,0.569994,0.005151,-0.181749,0.416170,-0.326634,-0.220852,0.142554,-0.280416,-0.436458,0.073224,-0.057266,-0.255660,-0.336122,0.141075,-0.598597,0.010208,0.004920,0.200232,0.056805,-0.457193,0.093098,-0.484480,-0.289752,-0.313108,-0.343617,-0.186165,0.250392,-0.439111,0.897452,-0.819555,-0.010658,0.454292,0.346346,-0.458636,0.680628,0.228587,0.035000,-0.403799,-0.108730,-0.129970,-0.293330,0.175029,-0.135402,0.422797,0.027740,-0.298476,-0.417202,0.027125', '3445516', '25922902', '35048413', '4127270');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25918677', '命运速递', '剧情', '影片讲述了一个投资煤窑失败的 屌丝，利用身为演员的女友色诱老 板，从而诈骗钱财用来还债的故事。 其中，美人计色诱诈骗、娱乐圈潜规 则横行等情节大胆、香艳，也让这个 以命运为主题的故事有了更多看点。 此外，诸多线索并行发展，大款、屌 丝、要账的混混、黑帮大哥、小演 员、快递员等众多角色的命运交织在 一起，最终汇集成一幕五味俱全的人 间悲喜剧。', '赵铭岳', '李非', 6.2, 6511, 'tt5219310', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2522418412.jpg', 3.4, 19, 47.6, 23.9, 6, '0.261548,-0.134484,-0.108062,0.541824,0.016812,-0.044050,0.431463,0.069364,-0.397917,-0.087863,0.127852,0.552441,-0.304026,0.079534,0.204282,-0.368632,-0.365080,-0.433546,-0.211387,0.056248,-0.125246,-0.369061,-0.130987,-0.199972,-0.111209,0.015196,0.642174,0.137861,-0.256431,-0.008451,0.613097,0.185730,-0.264596,-0.039060,-0.025880,-0.023376,0.341228,-0.013877,-0.334402,0.054873,-0.180577,-0.298810,0.077297,-0.109959,-0.287104,0.103794,0.706953,0.055364,-0.054482,-0.018645,0.529380,-0.093570,-0.176794,-0.311620,0.143752,-0.029812,0.592505,0.287384,-0.182499,-0.023551,-0.027653,0.012375,-1.062547,-0.117125,0.225984,-0.032996,-0.169042,-0.018442,0.211036,0.102346,0.072402,-0.153633,0.100118,0.216936,0.744279,0.300532,-0.111582,0.126945,-0.233450,0.605090,0.447844,0.151353,-0.042260,0.391286,-0.080888,-0.223483,-0.008874,-0.224895,-0.199636,-0.073673,0.287121,-0.300438,-0.161379,0.461461,-0.681386,-0.009734,0.009417,0.085698,0.122736,-0.330475,-0.208038,-0.700290,-0.334666,0.051032,0.077928,0.224313,0.576636,-0.088215,0.806568,-0.279065,-0.217645,0.677414,0.071981,-0.797418,0.677311,0.184086,0.073258,-0.234024,-0.354207,-0.121021,-0.017150,0.105142,-0.051889,0.238091,-0.051179,-0.456689,-0.069194,0.245044', '3318306', '26678784', '1468527', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25918693', '境界的彼方 剧场版 过去篇', '爱情', '鳥居なごむのライトノベルを原作に京都アニメーションが制作し、2013年10月から12月にテレビ放送されたダークファンタジー「境界の彼方」の劇場版2部作の前編。ヒロインとなる栗山未来を中心に、テレビシリーズ全12話で描かれた出来事を振り返る。この世を徘徊する異形のもの「妖夢」を討伐する「異界士」で、特異な呪われた血をもつ一族の最後の生き残りである少女・栗山未来。そして、人間と妖夢の間に生を受けた「半妖」で、その希少さゆえに孤独を感じて生きていた神原秋人。ある日の放課後、学校の屋上から今にも飛び降りそうな未来と秋人が出会ったことから、2人の世界は大きく変わっていく。', '种田梨沙', '石立太一', 8.1, 5551, 'tt4531412', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2233074775.jpg', 0.7, 2.2, 21.4, 43.1, 32.6, '-0.797278,0.129215,-0.001351,-0.207880,0.307844,-0.014310,-0.348617,0.123028,-0.204410,-0.537263,-0.097007,0.194066,-0.396820,0.244808,0.126270,-0.186593,-0.077035,-0.110275,0.095557,-0.504081,-0.178774,0.462635,0.299552,-0.028075,-0.190758,-0.232663,0.757824,-0.065463,0.482938,-0.309801,0.007121,0.553087,-0.282195,-0.345100,0.280451,0.138372,-0.516529,0.131724,-0.091528,0.140054,-0.560089,0.147765,-0.548617,-0.357714,-0.073918,-0.170666,0.739394,0.057273,-0.132093,-0.961188,0.684942,0.069639,-0.606125,-0.475192,0.552783,-0.184554,0.024001,0.431472,0.226058,-0.653170,0.210955,-0.385948,0.199462,0.217665,0.033606,-0.189950,0.146299,0.091584,-0.181621,0.171984,0.048396,0.026374,-0.083455,0.171374,0.243543,0.352828,-0.244198,0.127215,0.211873,0.131540,0.375244,-0.436677,-0.393862,0.132348,0.185806,-0.438514,-0.303431,-0.472520,-0.179135,0.195036,-0.219189,0.446947,-0.044447,0.562489,-0.127978,-0.014309,-0.050551,0.154478,0.251335,0.021656,-0.320847,0.034110,-0.003407,0.147521,-0.177489,0.100198,0.628237,-0.288151,0.660019,-0.277233,0.407846,0.230725,0.277528,-0.285572,0.651298,-0.303325,0.013302,-0.164110,0.027698,0.667645,-0.541588,0.172008,-0.211406,-0.181090,-0.678878,0.469847,-0.052016,0.219504', '27030639', '26273481', '27621192', '26635321');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25919385', '长寿商会', '喜剧', '一个脾气顽固的老头星七（朴根滢饰）在一家位于韩国某老城区的超市工作。老板很年轻，但生意被新区的新超市所威胁，一心盼望重建赔偿让他解困，可惜被老头一人反对从而延误整个老区的重建计划。独居的老头爱上了邻居花店婆婆金妮（尹茹贞饰），两个老人想鼓起勇气谈恋爱，但对方女儿反对， 就在老头患得患失之时，婆婆原来的病情开始反复。而一段往事渐渐浮出水面……', '尹汝贞', '姜帝圭', 7.8, 14815, 'tt4695462', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2233458295.jpg', 0.5, 2.3, 26.1, 47, 24.1, '0.083636,-0.031286,-0.537722,0.303171,-0.257286,-0.677362,0.558510,0.343221,-0.566800,-0.426958,0.212266,0.589518,-0.003759,0.430528,0.133743,0.073107,0.377783,-0.106064,0.270933,0.078605,0.183882,-0.373254,0.164691,-0.298783,-0.374133,-0.046201,0.443758,0.280109,0.078267,0.064729,-0.011590,0.062667,-0.075654,0.407541,-0.020747,-0.000056,0.407013,-0.226559,-0.252793,0.056321,0.109905,-0.177716,0.016720,0.359861,-0.177061,0.468336,0.732751,0.237175,-0.571944,-0.039297,0.488203,-0.057799,-0.216321,0.306218,0.580617,0.081301,0.240412,0.262164,-0.318477,-0.428216,-0.115857,-0.212565,-0.050873,0.146052,-0.018954,0.011366,-0.750404,0.297638,-0.002054,-0.084046,-0.131932,-0.521952,0.167006,0.377668,0.189164,0.400812,-0.226663,0.119467,-0.518928,0.049854,0.523857,-0.049578,-0.053623,0.642921,0.005890,0.003957,0.340656,-0.099658,-0.538821,0.056871,0.155513,-0.329085,-0.382548,0.174934,-0.568235,0.252313,-0.416863,-0.069834,0.181378,-0.187941,-0.281026,-0.364108,-0.149922,0.146994,0.006088,-0.035287,0.040653,-0.035570,0.566727,-0.776916,-0.020085,0.537106,0.157001,-0.742341,0.340823,0.142103,0.112902,-0.294177,0.004854,-0.120314,-0.087294,0.263810,0.039127,0.203972,-0.076280,-0.431587,-0.227250,0.325488', '1299965', '30205667', '1308035', '26280899');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25919910', '师父', '剧情', '民国年间南派咏春传人陈识（廖凡 饰）来到天津，结识了天津武术泰斗郑山傲（金士杰 饰），为在武术界开馆立足，郑山傲建议陈识用教徒弟踢馆的传统方式达成目的。几经周折，陈识娶了一名天津绝色女子赵国卉（宋佳 饰）为妻，还收下了本地青年耿良辰（宋洋 饰）为徒代其踢馆，夫妻二人暂居 在贫民窟，防被踢馆的仇家前来寻仇。陈识与妻子原本看不上好斗好色的耿良辰，但接触后也发觉了耿良辰的可取之处。但随着第八家武馆邹馆长（蒋雯丽 饰）和军界人士林希文（黄觉 饰）的介入，天津武术界面临着一场巨变，靠武术复兴家业的愿望、对妻子的爱意，以及作为师父的责任，让陈识陷入了两难之境。©豆瓣', '廖凡', '徐浩峰', 8.2, 310968, 'tt4851640', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2554541437.jpg', 0.7, 1.9, 17, 49.7, 30.8, '-0.004009,0.123532,-0.436560,0.577151,0.079480,-0.116794,0.000162,0.371113,-0.519954,-0.576261,0.061792,0.731673,0.180861,0.097961,0.515509,-0.102202,0.270727,-0.542124,-0.009181,-0.233113,-0.050360,-0.326917,0.193349,-0.185571,-0.219355,-0.127254,0.375745,0.397055,-0.621458,0.562059,0.463741,0.297498,-0.056627,0.072234,-0.105214,-0.111510,0.169576,0.143303,-0.574670,0.098499,-0.209729,-0.367530,-0.079750,-0.112719,-0.133427,0.151407,0.434327,0.191905,0.124682,-0.185074,-0.037051,-0.005354,-0.164267,0.099390,0.490691,-0.090085,0.247896,0.426700,0.075387,0.019156,0.118525,-0.214535,-0.404751,0.094637,0.675378,-0.217304,-0.593464,0.529056,-0.043130,-0.135420,-0.332533,-0.209253,0.350435,0.564696,0.276002,0.188257,0.003919,0.332902,-0.347280,0.459292,0.436722,-0.070775,0.217151,-0.054651,0.120510,-0.363549,0.136098,-0.455323,-0.243878,-0.157751,0.106629,-0.183873,0.121280,-0.012974,-0.365006,-0.202284,-0.080068,0.085310,0.163285,-0.153657,0.230751,-0.345883,-0.151890,-0.287425,-0.171459,-0.050550,0.336724,-0.114619,0.704666,-0.738482,0.060614,0.108222,0.239979,-0.584893,0.883846,0.228294,0.181045,-0.441271,-0.265827,0.048124,0.071597,0.080741,-0.141365,0.281159,-0.332414,-0.304737,-0.085927,0.019805', '35048413', '22964524', '3445516', '25881781');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25919961', '蚱蜢', '剧情', '繁华闹市区，一名戾气十足的男子（金儿宪史 饰）被人推入滚滚车流，碾压身亡。此人是拥有黑道背景企业芙洛莱茵的寺原会长（石桥莲司 饰）的公子，两年前曾驾车冲入人群造成大规模伤亡，却凭借老爹的势力全身而退。任职于芙洛莱茵的铃木（生田斗真 饰）目睹车祸一幕，他的爱人当年就死在对方车轮之下，原本想亲手复仇的他此刻却被卷入难以预料的漩涡之中。附近高楼上，受雇于寺原的神秘杀手鲸（浅野忠信 饰）正怂恿猎物自杀，而楼下被称为蝉（山田凉介 饰）的冷血杀手则接到介绍人岩西（村上淳 饰）的指示，准备杀死鲸。寺原公子之死，让全然没有关系的几个人搅在一起，命运难测……本片根据伊坂幸太郎2004年发表的同名小说改编。©豆瓣', '生田斗真', '泷本智行', 6.2, 6889, 'tt3846972', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2254492197.jpg', 2.7, 17.3, 52.7, 19.9, 7.5, '0.067193,0.126370,-0.450590,0.573664,0.045256,-0.124217,0.569395,0.264598,-0.360455,-0.425383,0.487252,0.447735,0.003227,-0.020824,0.307582,-0.127519,0.094080,-0.507799,-0.249429,0.084347,-0.013527,-0.376382,-0.209842,-0.090561,-0.014577,-0.268622,0.742848,0.162060,-0.318497,0.441808,0.249866,0.465965,-0.355682,0.200557,-0.101287,0.214917,0.007028,0.058660,-0.159522,0.021389,-0.419174,-0.474711,-0.012806,0.057128,-0.001474,0.175357,0.572039,-0.257720,-0.078008,-0.205813,0.214581,-0.093905,-0.063604,0.103002,0.591004,-0.155046,0.190847,0.324454,-0.306787,-0.319709,0.122478,0.164897,-0.621788,0.040363,0.135889,0.080347,-0.262296,0.244601,-0.057131,0.100126,0.024303,-0.039765,0.081597,-0.000059,0.271340,0.138045,0.038258,0.048965,-0.339241,0.117509,0.790041,-0.134741,0.068342,-0.131970,-0.032133,-0.185920,-0.242527,-0.207728,-0.175097,0.023497,0.391329,-0.069947,-0.168668,0.311167,-0.247792,-0.033486,-0.273389,0.082501,0.064466,-0.049182,-0.202462,-0.570273,0.038565,-0.107802,-0.101749,0.070793,0.000518,-0.076700,0.407473,-0.478459,0.183658,0.407296,0.199955,-0.270967,0.523624,-0.043071,-0.114184,-0.044980,-0.253060,0.110831,0.280660,0.209340,0.154403,0.150837,-0.209283,-0.259213,-0.231553,0.178088', '25828589', '3861846', '2369613', '10467125');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25920326', '我的青春有个你', '剧情', '大学军训里一场意外，让乖乖女周舟（王可如 饰）和学渣混混邱飞（刘冬沁 饰），彼此相遇。从英雄救美到勇敢表白，张扬的邱飞就这样走进周舟的心。当两人沉醉热恋时，已收敛张扬个性的邱飞，却卷入一场斗殴事件，他似乎在隐藏什么秘密？被迫退学的邱飞，在周舟痛苦的挽留下转身离去，只有他知道自己所做一切都是为了保护这个心爱的女孩。十多年后的周舟终于知道了真相，面对青春最痛的错过，她还能找回这段爱情吗……', '王可如', '林子平', 4.2, 10593, 'tt16359836', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2682258967.jpg', 29.4, 39.3, 24.5, 5.3, 1.5, '0.276885,0.024372,-0.749259,0.226657,-0.418123,-0.440127,0.818636,-0.283889,-0.168914,-0.174857,0.290471,0.598533,-0.416768,0.399657,0.382778,0.096565,-0.126765,-0.796052,0.010027,-0.141166,-0.072096,-0.256983,-0.267055,-0.098918,0.045418,-0.048604,0.751621,0.305647,-0.370359,0.485030,0.543391,0.044063,-0.086943,0.671838,0.032407,0.142539,-0.239435,0.455481,-0.331922,-0.247979,0.177499,-0.439723,-0.451569,0.302985,-0.008897,0.283196,0.686612,-0.214759,-0.201223,0.259833,0.430802,-0.606755,-0.222487,0.243859,-0.086767,-0.163378,0.071936,0.056983,-0.206297,0.204542,-0.040658,0.221558,-0.388755,-0.148755,-0.110263,0.083088,-0.552049,0.577739,0.193674,0.009329,0.410755,-0.173961,0.030460,0.400849,0.220844,0.505509,-0.379178,-0.045193,-0.293394,0.318641,0.969022,-0.110575,-0.232244,0.577384,-0.134441,-0.412912,-0.013309,0.004155,-0.514456,0.085033,0.318667,0.015511,-0.208482,0.172025,-0.234198,-0.311634,-0.166080,0.141331,-0.119632,-0.656051,-0.223546,-0.234608,-0.368081,-0.314881,-0.415523,0.257614,0.015731,-0.395345,0.414085,-0.873909,0.218589,0.650528,0.072598,-0.628616,0.280548,0.465420,0.089836,-0.197549,-0.085190,0.466925,-0.168941,0.294623,-0.105993,0.477063,0.047929,0.214688,-0.401598,0.374691', '1301022', '30345227', '35030151', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25920885', '神探夏洛克：可恶的新娘', '剧情', '《神探夏洛克》（Sherlock）2016年推出特别篇，福尔摩斯回归原著维多利亚时代，调查一宗神秘的幽灵新娘谋杀案。Thomas Ricoletti惊讶地发现，几小时前自杀身亡的妻子Emelia Ricoletti身着旧婚纱再次出现了，她的幽灵带着强烈的复仇欲望在街上徘徊。从迷雾笼罩的莱姆豪斯到被废弃的教堂深处，福尔摩斯、华生以及他们的朋友不得不想尽办法对付这个“从坟墓里爬出来”的敌人，但最终的真相却出乎所有人的意料……', '本尼迪克特·康伯巴奇', '道格拉斯·麦金农', 7.2, 237341, 'tt3845232', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2299823043.jpg', 1.7, 7.3, 38.3, 35.3, 17.5, '0.460164,-0.069036,-0.802515,0.482435,-0.087619,-0.318413,0.999143,0.031774,-0.603983,-0.562292,0.475125,0.653755,-0.425005,0.218307,0.307871,0.299496,-0.467454,-0.649052,-0.357074,-0.201593,-0.244482,-0.306658,-0.625056,-0.463681,0.067985,-0.066688,0.740320,0.503223,-0.069558,0.434952,0.367610,0.387793,-0.440797,0.352203,-0.102652,-0.043163,0.309294,0.098780,-0.138563,0.360308,-0.178228,-0.352578,-0.081720,0.285412,-0.388597,0.454248,0.600811,-0.356425,-0.000965,0.298959,0.453010,-0.511552,-0.353974,0.269860,0.414439,0.084409,-0.193144,0.198428,-0.031559,-0.228140,-0.287726,-0.156352,-0.546410,0.028726,0.087116,0.435895,-0.418112,0.282364,-0.073940,0.319917,0.262192,-0.292352,0.056386,-0.284243,0.198667,0.399512,-0.226269,0.150892,-0.635268,0.017827,0.479095,-0.138132,-0.365880,0.208019,-0.198436,-0.355456,-0.193455,0.106736,-0.542597,0.017315,0.484427,0.272390,-0.316284,0.541742,-0.740047,-0.408281,-0.406991,-0.189898,-0.014099,-0.033871,-0.400000,-0.697203,-0.281054,-0.231743,-0.079095,-0.079496,-0.218584,-0.103390,0.347362,-0.555678,0.390277,0.603723,0.052685,-0.095701,0.653168,-0.400696,0.146799,-0.035080,-0.267409,0.542460,0.249683,0.505418,-0.060642,0.346632,-0.156737,-0.202851,-0.942097,0.447559', '20451118', '1316693', '1302133', '11615927');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25921812', '驴得水', '剧情', '一群“品行不端”却怀揣教育梦想的大学教师，从大城市来到偏远乡村开办了一所小学校。学校待遇惨淡、生活艰苦，但老师们都自得其乐，每天嘻嘻哈哈打成一片。然而教育部特派员要来突击检查的消息打破了安宁，因为学校有一位“驴得水老师”隐藏着不可告人的秘密。就在所有人都担心丑事即将败露的时候，一个神奇天才的出现拯救了大家，然而谁能料到真正的麻烦才刚刚开始……', '任素汐', '周申', 8.3, 867110, 'tt6167014', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2393044761.jpg', 0.9, 2.5, 15, 43.1, 38.5, '0.271689,0.026247,-0.510683,0.179036,-0.105260,-0.003697,0.168579,0.098643,-0.679694,-0.416346,0.333842,0.353802,-0.179152,0.389246,0.244264,-0.181354,-0.109071,-0.533810,0.167806,-0.410947,-0.246855,-0.202953,-0.219930,-0.329854,-0.053659,-0.329562,0.141578,0.211416,-0.116948,0.195712,0.067185,0.007120,-0.200003,0.308745,-0.252913,-0.365231,0.547131,0.457863,-0.054756,-0.031323,-0.194286,-0.108277,-0.586739,-0.141236,0.387548,0.163858,0.442585,0.260577,-0.514383,0.198524,0.372435,-0.334636,-0.193450,0.247745,0.589940,-0.313213,0.062141,0.166544,-0.014485,0.237826,-0.085206,-0.281169,-0.583471,0.017334,-0.015499,0.092082,-0.450950,0.545572,0.494029,-0.321913,0.015501,-0.421184,0.265926,0.422464,0.245385,0.598445,-0.118607,0.449641,-0.504455,0.378491,1.017789,-0.430601,-0.358751,0.151756,-0.219379,-0.346470,0.092346,-0.356254,-0.782275,0.144070,-0.070932,-0.123998,-0.424425,0.165438,-0.431663,-0.096420,-0.189271,-0.203811,0.158874,-0.310869,-0.363603,-0.484311,0.090729,0.129220,-0.342562,0.343176,-0.019376,-0.205438,1.091242,-0.934982,0.243320,0.652560,-0.136629,-0.681854,0.718045,0.141456,0.122204,-0.030824,-0.214498,0.086907,0.115013,0.527147,-0.124678,0.389268,-0.211616,-0.613629,-0.008614,0.287989', '1877596', '1307741', '1296770', '24284209');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25921830', '办公室', '惊悚', '发生在办公室的恐怖故事.影片以一家人遭受的杀人事件为起点，公司职员们一个接一个被神秘杀害，而凶手却始终不知是何人。高雅星将饰演事件中心的女实习生一角。《追击者》、《黄海》、《我是杀人犯》等影片编剧洪元灿此次首执导筒，将作为导演出道。', '高雅星', '洪元灿', 6.3, 7836, 'tt4682562', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2258840740.jpg', 2.9, 15.6, 52.6, 21.8, 7.1, '0.207910,0.277040,-0.178842,0.609611,0.172588,0.296707,0.926636,0.211381,-0.400541,-0.307872,0.266007,0.861397,-0.273484,0.181609,0.198291,-0.018605,0.042511,-0.582524,-0.396033,-0.114389,-0.196557,-0.106441,-0.121571,-0.012990,-0.058639,-0.099001,0.640216,0.160158,-0.191874,0.023618,0.803093,0.668159,-0.426714,0.173893,0.064951,-0.164961,0.127645,-0.029881,-0.217648,0.370271,-0.153994,-0.635800,-0.299433,0.069427,-0.282692,0.302801,0.660199,-0.017331,-0.241844,-0.367037,0.919013,-0.716054,-0.014552,-0.136498,0.538826,0.157427,0.153251,0.447239,0.069091,0.030885,0.225371,-0.412651,-1.273640,-0.081720,0.365687,0.077968,-0.524533,-0.120509,-0.399343,-0.168661,0.177606,-0.023067,0.341186,0.129143,0.492952,0.214994,0.054022,0.175679,-0.230236,0.337045,0.727995,0.002345,-0.279304,-0.034775,0.091182,-0.433523,0.019023,-0.442966,-0.409951,0.418010,0.144317,-0.238065,0.073986,-0.200199,-0.343494,-0.237970,-0.302394,-0.308383,0.071843,-0.349337,-0.405182,-0.753387,0.107272,0.246534,-0.120678,-0.279401,0.112981,-0.212194,0.726160,-0.710605,0.059635,0.827564,0.098208,-0.628875,0.947878,0.095874,0.083063,-0.207039,0.062465,-0.268829,0.368438,0.293669,-0.085787,0.303593,-0.182868,-0.272175,-0.116893,-0.067336', '26678784', '3785918', '27098364', '1874704');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25922902', '唇上之歌', '剧情', '坐落于五岛列岛福江岛上的五岛中学，由于合唱团指导老师松原晴子（木村文乃 饰）待产休假，她便委托好友柏木由里（新垣结衣 饰）代课一学期。柏木美艳冷漠，学生们对她既好奇又忌惮，虽然听说她曾是某交响乐团的钢琴家，可是却因某种原因而辞职回家，并且决然不愿指导学生们练习。女神般的老师从天而降，吸引一帮原来对何尝没有任何兴趣的男孩加入这个清一色的女生团体中来。而女孩子们与男孩争吵不断，她们也对柏木老师的不闻不问颇有微词。一年一度的NHK全国学校音乐比赛即将召开，合唱团积极练习指定曲目《信～敬启　致十五岁的你～》。在此期间，柏木老师深藏心底的秘密逐渐浮出水面，而孩子们也在音乐的熏陶中找到人生的方向……本片根据作家中田永一（乙一）的同名小说改编（又译《再会吧，青春小鸟》）。©豆瓣', '新垣结衣', '三木孝浩', 7.7, 13645, 'tt3855730', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2207639509.jpg', 0.4, 2.9, 29.4, 45.7, 21.7, '0.107480,-0.283545,-0.406443,0.550267,-0.020395,-0.038860,0.452353,0.010651,-0.410571,-0.292865,0.116791,0.509512,-0.054082,0.575973,0.115032,-0.054358,-0.198469,-0.539276,-0.022316,-0.201049,-0.012150,-0.305567,0.054021,-0.094339,-0.050874,-0.260036,0.648668,-0.169815,-0.091621,0.725565,0.359449,0.120602,-0.143233,0.194654,0.211510,-0.104838,0.194217,0.311191,0.040527,-0.008896,-0.156848,-0.145905,-0.461169,-0.071882,0.255980,0.415343,0.703130,0.082800,-0.051005,-0.261134,0.432778,-0.180213,-0.110879,0.215378,0.437076,0.197485,0.188125,0.193421,0.088439,-0.031534,-0.301587,-0.315218,-0.218350,0.182913,0.177983,0.273985,-0.205570,0.485175,0.176765,-0.172963,0.146788,-0.026258,-0.152114,-0.155921,0.167851,0.233976,-0.226438,0.114032,0.249839,0.376981,0.469532,-0.012935,-0.174201,0.167726,-0.302364,-0.300667,0.175356,0.042401,-0.473439,0.102366,-0.156703,0.044729,-0.070615,0.040346,-0.381421,-0.031046,-0.051846,-0.159298,0.135606,-0.375695,0.041562,-0.743646,0.284127,-0.202009,-0.167708,-0.102643,0.283924,-0.060893,1.175012,-0.963894,0.092691,0.456177,0.107888,-0.476531,0.464954,0.284109,-0.162114,-0.270073,-0.276268,0.173798,-0.170936,0.163331,-0.253756,0.375125,-0.007974,-0.389836,-0.240148,0.245863', '3811356', '1316589', '26999591', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25924056', '小飞象', '奇幻', '有一只小象，因为耳朵特别的大而遭到了嫌弃。过气的马戏团明星霍尔特（科林·法瑞尔 Colin Farrell 饰）带着一双儿女米莉（妮可·帕克 Nico Parker 饰）、乔（芬利·霍宾斯 Finley Hobbins 饰），成为了小象的照顾者，他们非常喜欢小象，给它取名小飞象。一次偶然中，父女一行人震惊的发现，小飞象竟然真的会飞，这消息一经传出，市民们纷纷买票来到马戏团，想看一眼这奇妙的景象，本来濒临倒闭的马戏团因此而重获新生，小飞象也一夜成名。大企业家范德威尔（迈克尔·基顿 Michael Keaton 饰）在小飞象的身上发现了商机，于是抛出橄榄枝，邀请小飞象到自己的俱乐部工作，然而没过多久，霍尔特就发现，范德威尔表面上光鲜亮丽，实际上是一个吃人不吐骨头，眼里只有金钱的贪婪资本家。©豆瓣', '伊娃·格林', '蒂姆·波顿', 6.5, 68784, 'tt3861390', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2549234765.jpg', 1.2, 11.4, 54.5, 25.8, 7.2, '0.346575,-0.055036,-0.749556,0.386895,0.057302,-0.183359,0.694838,0.127934,-0.500525,-0.192678,-0.037934,0.763371,-0.567537,0.495784,0.230872,0.052224,-0.240572,-0.432081,-0.078650,-0.324320,-0.242629,-0.303454,-0.279039,-0.276285,0.117282,-0.246738,0.217617,0.128770,-0.241308,0.673169,0.524605,0.065015,0.270259,0.275720,-0.083189,0.126015,0.223698,0.153410,0.129400,0.197346,0.029239,0.070081,-0.237307,0.067830,0.115788,0.260963,0.473142,-0.436350,-0.128025,-0.228717,0.396156,-0.226799,0.235081,0.028761,0.183954,0.002097,0.324504,-0.473381,0.007872,0.222994,0.340154,-0.271519,-0.515739,0.219928,-0.016383,0.309391,-0.481087,0.182928,0.186996,-0.143153,-0.032711,-0.386202,0.075325,-0.033019,0.254060,0.396759,0.074081,0.259971,-0.732541,-0.030095,0.411166,0.131642,-0.382129,0.365137,-0.063525,-0.517334,0.048804,-0.120607,-0.332435,0.008765,0.690543,0.057265,-0.103587,0.132581,-0.531669,0.043073,-0.108207,-0.168688,-0.174130,-0.419768,-0.147720,-0.640107,-0.111982,-0.430882,-0.145042,0.351634,0.080079,-0.291573,0.666793,-0.664658,0.231956,0.268196,0.184447,-0.191711,0.687776,-0.237337,0.016452,-0.027561,-0.206948,0.140043,0.444558,0.085011,0.250573,0.099920,-0.243822,-0.472737,-0.263757,0.268439', '1301686', '3055049', '1309101', '1414808');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25924268', '喜乐长安', '动作', '这是一个小木寺俗家弟子释然，和青梅竹马的姑娘喜乐，骑着小马游走江湖的故事。一场大饥荒，6岁的孤儿随饥民逃荒到小木寺，冲突中只有她在夹缝中挤进了小木寺被小木寺收留，方丈给她起名为喜乐，喜乐成了大家的愿望。释然儿时看到一场在长安城妓院楼顶上对决武林盟主的盛事，却以苦当派掌门人虽然夺得盟主，被困楼顶饿死的荒诞结局而收场。江湖风云突变，人心自此大乱。十八岁那年，释然的师父（万仓 饰）预感小木寺将有一劫，秘密安排释然（张天阳 饰）改名长安还俗下山，去找寻一名铸剑老人（王连生 饰）。机缘巧合下，释然得到了老头赠送的当世奇兵，并用它夺取了武林盟主的称号。虽然在雪邦做了盟主，但在释然心里，霸主的位子比不上一个喜乐（何泓姗 饰）有意思。而万永（金亮 饰）一心想成为武林霸主并劫持喜乐以挟释然交出盟主之位，释然最终放弃盟主之位与喜乐归隐山林。 万永当初一手操办了雪邦比武，然而这究竟是万永在操控着江湖还是被江湖所操控？一切江湖动荡，好似一盘棋局，人如棋子，岂能由己？世间的事，只是人类的一个游戏，而人类，是上天的一个游戏。电影根据韩寒武侠题材小说《长安乱》改编。', '张天阳', '竹卿', 3.1, 2987, 'tt4892556', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2323300602.jpg', 65.6, 20.9, 8.8, 2.8, 1.9, '0.086411,0.196484,-0.359140,0.343769,0.061944,-0.142652,0.316563,0.156201,-0.606347,-0.113962,0.296487,0.835833,-0.190728,0.185440,0.163641,0.037482,0.134652,-0.436224,0.006523,-0.303527,0.145291,-0.219367,-0.315124,-0.073688,-0.018444,-0.228317,0.609288,0.438969,-0.206127,0.516309,0.548832,0.056842,-0.259116,0.243694,-0.408557,-0.085367,-0.226757,0.237378,-0.488344,0.148897,-0.456233,-0.276484,-0.272122,0.026130,-0.216801,0.088057,0.480348,-0.375426,-0.139217,-0.167017,0.154803,-0.330011,-0.243049,-0.183673,0.241442,0.154132,0.012190,0.310142,0.025936,0.086867,0.007990,-0.081583,-0.525335,0.046405,0.325982,0.135283,-0.485069,0.294444,-0.014209,-0.287366,-0.386409,-0.227897,0.277374,0.248539,0.469445,0.181106,-0.112748,-0.010467,-0.594205,0.348323,0.733058,-0.108317,-0.111309,0.230758,0.282940,-0.338745,0.108955,-0.482125,-0.207372,0.137523,0.182440,-0.287009,0.074130,0.347837,-0.211926,0.002736,-0.154839,-0.038431,0.064784,-0.464622,0.024063,-0.003751,-0.144940,0.189556,-0.324242,-0.159573,0.390060,-0.296275,0.822924,-0.816904,0.108510,0.167076,-0.079141,-0.457808,0.548767,0.160296,0.211908,-0.232702,0.019651,0.167096,-0.100877,0.473469,-0.042886,0.082374,-0.209299,-0.249682,-0.403269,0.211710', '35030151', '25721544', '35048413', '26711487');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25924935', '闪烁的爱情', '剧情', '平凡的高中内，少男少女青涩单纯的爱恋故事从未间断上演。高一女生木下仁菜子（有村架纯 饰）悄悄喜欢着同年级的一之濑莲（福士苍汰 饰），一之濑虽然堪称多数女生心仪的对象，但是他冷若冰川，将斗胆表白的女孩们拒之千里之外。不过幸运之神不经意间眷顾了仁菜子，电车上偶然的交谈消除了横在她和一之濑之间的樊篱，她以笨拙的方式追随者对方的脚步，发自心底为对方呐喊和鸣不平，而一之濑似乎也对这个多少有些特别的女孩青眼相看。只是青春的爱情绝非如此简单，是永大树（入江甚仪 饰）、永麻由香（佐藤亚璃纱 饰）、安堂拓海（山田裕贵 饰）、杉本真央（黑岛结菜 饰）等人的出现都让初恋物语变得复杂起来……本片根据咲坂伊绪少女漫画。©豆瓣', '福士苍汰', '广木隆一', 5.5, 9866, 'tt3872958', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2219851446.jpg', 7.8, 30.2, 44.5, 12.4, 5.2, '0.387711,0.004067,-0.588515,0.574867,-0.065928,-0.106777,0.690729,0.047652,-0.290254,-0.266453,0.132385,0.498112,-0.372624,0.250073,0.178018,0.093790,-0.106200,-0.639226,-0.243932,-0.143658,-0.107071,-0.231833,-0.078681,-0.060458,-0.353715,-0.100833,0.672587,0.025765,-0.158979,0.529982,0.430979,0.298590,0.077875,0.270568,-0.084521,0.102765,-0.029659,0.221118,-0.068657,-0.198305,-0.201862,-0.331168,-0.313555,0.307359,-0.187495,0.444309,0.582533,-0.321617,-0.145034,0.101214,0.262788,-0.095743,-0.006818,0.160444,0.199014,0.096088,0.130922,0.085982,0.017963,0.044059,0.183331,0.204130,-0.419268,-0.004067,-0.034392,0.120764,-0.138930,0.520245,0.179806,-0.194402,0.260469,-0.083973,-0.096374,-0.234319,0.312201,0.060798,-0.278268,-0.139596,-0.033329,0.225391,0.448287,0.364744,-0.285227,0.534704,-0.432190,-0.431091,-0.127501,0.008825,-0.515894,-0.071209,0.034660,0.074818,-0.012853,-0.038391,-0.462834,0.004996,0.037050,0.206459,0.062960,-0.408820,-0.203718,-0.472389,0.026149,-0.836952,-0.435773,-0.012465,0.121510,-0.446595,0.899539,-0.900747,-0.023238,0.562683,0.260081,-0.143354,0.365763,0.157805,-0.391030,-0.194665,-0.383462,0.263996,-0.091752,-0.006344,0.117021,0.485653,-0.278355,0.070013,-0.384573,0.417686', '26354526', '1826173', '25922902', '3811356');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25925430', '真相', '剧情', '索尼卖下《真相》的北美发行权，影片由凯特·布兰切特和罗伯特·雷德福主演，改编自《真相与责任：媒体、总统和特权》。原书聚焦2004年丹·拉瑟(罗伯特)关于小布什在越战期间享受特殊待遇的报道，事后被怀疑部分参考文件涉嫌伪造。', '凯特·布兰切特', '詹姆斯·范德比尔特', 7.7, 9249, 'tt3859076', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2269815979.jpg', 0.4, 2.1, 28.1, 50.9, 18.6, '0.064702,-0.181656,-0.571797,0.447345,0.413039,0.403600,0.112245,0.468060,-0.489250,-0.376639,0.028786,0.835205,-0.480082,-0.175120,0.439202,-0.082417,-0.790866,-0.810597,-0.015861,0.005431,0.311675,-1.153858,-0.277534,-0.639657,-0.202770,-0.643249,0.477877,-0.015518,-0.632191,0.142064,0.594032,0.469933,-0.413590,-0.036101,0.504995,-0.241146,0.483997,-0.067182,-0.593979,0.321451,0.173562,-0.232485,-0.005477,-0.150619,0.527594,0.307830,0.400949,-0.016513,-0.044850,0.179661,0.409535,-0.327457,0.230127,0.274003,0.227817,0.163999,0.487317,0.646779,-0.223340,-0.155163,-0.054846,-0.147693,-0.864289,-0.242152,-0.059504,0.556820,-0.310556,0.507236,-0.774940,0.480468,0.055398,-0.131075,0.317512,0.330037,0.206665,0.247371,0.340256,0.097551,-0.008482,0.301293,0.075541,0.076672,-0.004537,0.125038,-0.209373,-0.329309,-0.387194,-0.115555,-0.398273,0.508612,0.355673,0.135459,0.182345,0.567034,-0.363821,-0.558526,-0.252495,-0.632115,-0.087184,-0.354221,0.119176,-0.982759,-0.377503,0.080934,-0.001752,-0.546088,0.589556,-0.422241,0.564845,-0.158140,0.301731,0.127779,0.248898,-0.564746,0.675250,0.190944,0.259870,-0.312113,-0.247131,0.117634,0.666392,-0.095179,0.013376,-0.155761,0.366531,-0.637714,-0.126570,0.006955', '3006781', '26990609', '6517421', '1293537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25925764', '派对搭讪秘诀', '喜剧', '1977年的伦敦郊区，三个痴迷庞克音乐的男孩，整日游荡街头、耍废装酷。某日得知当地的庞克精神领袖要举办派对，青春生涩的男孩们决定闯入把妹，没想到却误入外星人派对。撩妹不成，反而对外星女孩一见锺情，为了展现地球人的大爱，一场四十八小时的地球庞克体验之旅也就此展开！本片改编自奇幻小说家尼尔盖曼的同名短篇故事，曾以《摇滚芭比》风靡影乐坛的导演约翰卡麦隆米契尔，巧妙结合宅男把妹与外星人报到的喜剧元素，并添入庞克音乐与叛逆精神，找来妮可基嫚变身银髮爆炸头庞克教母，嘶吼呐喊摇滚不死；饰演外星女孩的艾儿芬妮，则是从乖巧天真，摇身一变为性感烟燻庞克妹，在迷幻怪诞的影像风格中，与潜力新人亚历克斯夏普，谱出一段诡谲浪漫的恋情。', '妮可·基德曼', '约翰·卡梅隆·米切尔', 6.7, 11479, 'tt3859310', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2459885970.jpg', 3.2, 13.5, 39.5, 32.3, 11.5, '-0.005403,0.033090,-0.223906,0.346818,0.124641,0.076349,0.476565,-0.176084,-0.129892,-0.210315,0.084970,0.420148,-0.300223,0.184772,0.574483,0.024460,-0.329263,-0.582465,0.039018,-0.018548,0.207491,-0.137382,-0.169715,-0.021287,0.001240,-0.600094,0.472881,-0.050202,-0.329488,0.407082,0.478719,0.211558,-0.388999,-0.059242,-0.123549,-0.044759,0.059285,-0.040647,-0.159454,0.077944,-0.273443,-0.109615,0.044439,-0.089661,-0.206431,-0.011218,0.682450,-0.262612,0.243160,-0.294694,0.589489,-0.004471,-0.417860,-0.112476,0.197366,-0.143354,0.239639,0.004607,0.091078,-0.165590,-0.041211,-0.248130,-0.462737,0.283721,-0.041788,0.022882,0.010613,0.081669,0.044746,-0.063324,0.065752,0.028566,0.063944,-0.112405,0.549041,0.404786,0.224369,0.397301,-0.017801,0.270679,0.344891,0.217057,-0.404768,0.220308,-0.184766,-0.377188,-0.168003,-0.306353,-0.512886,0.053534,0.067339,-0.216254,-0.006057,0.246711,-0.760174,-0.111271,-0.193641,-0.021895,0.197747,-0.079049,-0.269038,-0.955044,-0.000646,0.038739,0.213987,-0.137910,0.119201,-0.175252,0.636832,-0.683998,0.218790,0.563766,0.001114,-0.244838,0.453272,0.072285,-0.114957,-0.328772,-0.142500,0.496433,0.057641,0.077582,-0.174035,0.473544,-0.150974,-0.076570,-0.441644,0.358825', '5403927', '3811356', '20274039', '1322847');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25926267', '一个勺子', '剧情', '农民拉条子（陈建斌 饰）在镇上遇到一个讨饭的傻子（金世佳 饰），傻子跟着他回了家。拉条子贴了寻人启示，不久有人认领了傻子。紧接着又有自称傻子的家人陆续出现，说拉条子把傻子卖了。麻烦接踵而至，拉条子自知上当受骗却有口难言，他想不明白，好事怎么就成了坏事？他开始以一位农民最淳朴的办法想自证清白。而为了寻找傻子，他成了另一个到处缠着别人的傻子……影片根据短篇小说《奔跑的月光》改编，陈建斌自编自导自演的处女作。', '陈建斌', '陈建斌', 7.7, 161530, 'tt3856504', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2284639043.jpg', 0.5, 2.3, 27.3, 53.4, 16.4, '0.456618,-0.176023,-0.238700,0.337225,-0.424905,-0.029593,0.491809,0.328382,-0.175330,0.058688,0.072764,0.800142,-0.065170,-0.161690,0.020039,0.176825,-0.245943,-0.311938,0.421528,-0.117210,-0.277327,-0.089927,-0.020909,-0.388334,-0.071151,0.195756,0.005681,-0.164917,-0.009468,0.102199,0.763551,0.235296,-0.046510,-0.041741,-0.389076,0.286341,-0.297664,0.211895,0.183312,0.408521,-0.176511,-0.115321,-0.088393,0.007331,-0.234861,0.292398,0.429637,-0.026694,0.271693,-0.025931,0.222135,-0.563718,-0.022782,-0.093214,0.133742,-0.315352,0.198369,-0.147350,-0.108814,0.029932,0.008485,0.153145,-0.423754,0.048370,0.162932,0.192219,-0.635429,0.089169,0.299571,-0.131715,-0.118774,-0.136322,0.300048,0.343119,0.036591,0.057508,0.058104,-0.069697,-0.888008,0.420880,0.287285,-0.159756,0.228046,0.584343,0.088377,-0.050204,0.476060,-0.111828,-0.392762,0.088430,0.334073,-0.155574,-0.467826,-0.394794,-0.258346,-0.227311,0.027348,0.260763,-0.021377,-0.739140,-0.267823,0.096256,-0.026386,0.127632,0.143606,-0.013857,-0.141571,-0.031587,0.284185,-0.240822,-0.090015,0.480346,-0.020411,-0.621353,0.399342,0.096689,-0.234910,-0.349381,0.140255,-0.181128,0.314673,0.697366,0.499461,-0.149819,-0.027265,-0.518603,0.018338,0.263464', '1293908', '23856234', '6753166', '1297710');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25928048', '哆啦A梦：大雄的宇宙英雄记', '剧情', '近日里，大雄（大原惠 配音）迷上了一部名为《银河防卫队》的电视剧，剧中英雄们对抗邪恶势力的英勇形象在大雄的脑海里留下了深深的印记，希望自己有朝一日也能够如同这些英雄般惩恶扬善。某日，大雄来到小夫（关智一 配音）家，发现他竟然弄来了剧中英雄的戏服，还找来了摄影机，打算同胖虎（木村昂 配音）、静香（嘉数由美 配音）一起拍摄属于他们自己的英雄电视剧，然而，让他们没有想到的是，他们玩得不亦乐乎的景象，竟然被一只名为艾伦（井上麻里奈 配音）的外星人尽收眼底，艾伦的所居住的星球遭到了宇宙海盗的侵略，来到地球搬救兵的他，将拯救母星的期望，托付在了眼前这些仿佛能够呼风唤雨的“英雄”们身上。©豆瓣', '水田山葵', '大杉宜弘', 7, 6591, 'tt4788602', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2371784693.jpg', 1.8, 9.2, 45.6, 26.2, 17.2, '0.206021,0.082611,-0.768567,0.564381,0.089377,-0.226027,0.527248,0.034722,-0.260740,-0.298188,0.211115,0.889296,-0.301426,0.290523,0.015284,0.014296,-0.293244,-0.765471,-0.464252,-0.101393,-0.108527,-0.106260,-0.386096,-0.065837,-0.039682,-0.230306,0.687302,0.078989,-0.212082,0.290055,0.277879,0.170041,-0.140842,0.230450,-0.387328,0.163320,-0.034122,0.016797,-0.063693,0.284976,-0.342705,0.011402,-0.068882,0.471565,-0.202803,0.107485,0.785120,-0.441178,-0.087237,-0.113952,0.387849,-0.302187,0.109196,0.018257,0.216851,-0.029805,0.014092,-0.176334,0.062994,0.115996,0.147313,-0.274574,-1.146799,-0.038308,-0.047152,0.261823,-0.540668,0.237951,-0.001828,-0.230409,0.306926,0.014633,0.440088,0.097542,0.489936,0.351910,-0.142121,0.349636,-0.350500,0.427918,0.582692,-0.102497,-0.206476,0.444122,-0.104055,-0.237326,-0.156563,-0.281295,-0.374997,-0.045264,0.224478,-0.099859,-0.166084,0.135339,-0.633537,0.003921,-0.253048,-0.217969,-0.041975,-0.379497,-0.109754,-0.767540,-0.103859,-0.286294,-0.013416,0.292460,0.165739,-0.202235,1.060064,-0.706361,-0.045423,0.745045,0.171107,-0.373274,0.591680,0.005098,-0.176864,0.050339,-0.027467,-0.048214,0.189800,0.420841,0.259648,0.310266,-0.142347,-0.207561,-0.600796,0.417495', '27602116', '24284209', '3318306', '25880986');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25928069', '浪漫天降', '喜剧', '新上任的空姐沙沙（关晓彤 饰）对即将到来的飞行任务感到万分期待而又有一丝紧张。在飞机上，她于无意之中得罪了名为林子大（夏雨 饰）的男子。林子大拥有英俊帅气的外表和豪放挥霍的做派，是一介典型的钻石王老五。更可贵的是，他为人心思细腻，体贴善良，随着时间的推移，沙沙和林子大之间相互吸引，产生了真挚的感情。刁蛮苛刻的乘务长白晶晶（刘孜 饰）、风流倜傥的机长胡英俊（邱泽 饰）、精明强干的空姐贾斯雯（崔宝月 饰）和声名显赫的大明星右立（左立 饰），小小的机舱里，个性迥异的男女们产生了激烈碰撞，会诱发出怎样的喜剧旋风呢？©豆瓣', '夏雨', '宁瀛', 3.7, 8205, 'tt5191028', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2274938394.jpg', 52.6, 24.9, 13.8, 3.2, 5.5, '0.168909,0.175742,-0.801980,0.628439,-0.343651,0.098102,1.033703,0.202109,-0.518994,0.076140,0.284684,0.407771,-0.532806,0.086157,0.376898,0.078167,-0.081349,-0.321453,-0.226377,-0.002997,-0.228090,-0.331877,-0.510749,-0.158811,-0.013184,-0.281992,0.408585,0.113583,-0.248627,0.714775,0.662512,0.099890,-0.003458,0.393021,-0.135978,-0.143015,0.036705,0.254570,0.142580,-0.210547,-0.193390,-0.104300,-0.091974,-0.120006,-0.218605,0.433539,0.619790,0.055301,-0.244634,-0.127561,0.648573,-0.003418,0.110037,-0.051878,0.125442,0.178757,0.185208,-0.131338,-0.247995,-0.025035,0.211838,-0.171287,-0.375625,0.392821,0.147263,0.101312,-0.328765,0.449694,-0.120394,-0.623291,0.453737,-0.315862,-0.068522,-0.024790,0.378661,0.357504,0.018250,0.196063,-0.139890,0.077073,0.382550,0.436579,-0.526649,0.182274,-0.553929,-0.593319,-0.220016,-0.408104,-0.488463,-0.209188,0.432512,0.061663,0.066460,0.310861,-0.365411,0.216345,0.046404,0.130044,0.118874,-0.434013,-0.433998,-0.688845,-0.152577,-1.089485,-0.491602,0.102932,0.270000,-0.205645,1.146120,-0.860710,-0.075872,0.265742,0.095116,-0.373679,0.539511,0.172441,-0.328526,0.065884,-0.288456,0.020765,-0.140279,-0.011937,-0.003070,0.648310,-0.458146,0.056444,-0.122909,0.388389', '26348103', '26354526', '10833971', '1390020');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25928148', '罗密欧与朱丽叶', '剧情', '凯普莱特和蒙太古是声名显赫的两大家族，因为祖先们结下恩怨，两家人将彼此视为眼中钉肉中刺。可是造化弄人，在机缘巧合之下，蒙太古家的小儿子罗密欧（达米安·萨格 Damien Sargue 饰）在一场宴会上偶遇了凯普莱特家的女儿朱丽叶（希西莉亚·卡拉 Cécilia Cara 饰），在不知道彼此身份的情况下，两人双双坠入了爱河，并且在神父的见证之下私定终身。终于，罗密欧和朱丽叶的情事还是被两家人知晓了，罗密欧遭到了驱逐永远也不能够回到朱丽叶的身边，这让朱丽叶伤心欲绝。善良的神父给了朱丽叶一种能够令人假死的药，并且答应帮助朱丽叶和罗密欧私奔。©豆瓣', '达米安·萨格', 'Redha', 9.4, 7476, 'tt0410532', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2224933614.jpg', 0.2, 0.2, 3.5, 23.4, 72.6, '0.505078,-0.014461,-0.682884,0.548283,-0.020202,-0.257818,0.671578,0.128236,-0.696658,0.036926,0.362411,1.250183,-0.315069,0.238035,0.223929,0.114050,-0.384523,-1.072565,0.024556,-0.294510,-0.406818,-0.584089,0.107532,-0.069625,-0.197066,-0.115958,0.542665,0.034869,-0.114379,0.437381,0.419470,0.552841,-0.244163,0.192570,-0.334513,0.254574,0.275977,-0.040597,-0.673789,0.274276,-0.077776,0.003153,-0.273896,0.280035,0.022480,0.232320,0.476050,-0.523171,0.061103,-0.130049,-0.026731,-0.140362,0.069347,0.433783,0.288087,-0.206340,0.288253,0.417812,-0.284802,-0.095221,0.273831,0.200926,-0.703962,0.300141,0.282671,0.082406,-0.869353,0.716904,0.166463,-0.265445,0.292566,-0.154398,0.392450,0.559193,0.464198,0.228965,-0.107855,-0.258112,-0.881178,-0.020210,0.922696,0.117526,-0.105312,0.482452,-0.235098,-0.297177,-0.257945,-0.353304,-0.726854,0.090080,0.550918,0.106567,-0.163269,0.824089,-0.704372,-0.443724,-0.290970,0.247858,0.076030,-0.784573,0.184328,-0.489028,-0.553401,-0.659032,-0.446342,0.048597,0.223294,-0.233457,0.700635,-0.915979,0.111804,0.291972,0.388874,-0.317791,0.813734,0.400381,0.086724,-0.153835,0.046438,0.033795,0.159990,0.012495,0.409090,0.398444,-0.031404,0.170489,-0.591222,0.340783', '30162520', '35048413', '25721544', '1309069');
