INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25929151', '遇见你之前', '剧情', '来自于小镇的年轻女孩小露（艾米莉亚·克拉克 Emilia Clarke 饰）应聘成为了一名看护，她所要照顾的对象，是一位名叫威尔（山姆·克拉弗林 Sam Claflin 饰）的男子。曾经的威尔家境优渥，热爱自由，喜欢到世界各地冒险，然而，一场可怕的车祸粉碎了他的脊椎，使他四肢瘫痪，这也就意味着，威尔漫长的下半生只能在轮椅上度过了。就这样，小露在误打误撞之中开始了和威尔的共同生活，但威尔很快就发现，小露和之前的看护们截然不同，个性大大咧咧的她从来不会对自己的伤痛避而不谈，但正是这种直面惨淡的勇气给威尔带来了不一样的感觉。在小露的陪伴下，威尔开始渐渐重新体味到了快乐的感觉，小露的坚强亦让威尔开始认真思考起自己的未来。©豆瓣', '艾米莉亚·克拉克', '西娅·夏罗克', 8, 301627, 'tt2674426', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2317441943.jpg', 0.4, 2.6, 22.6, 44.5, 29.9, '0.261411,0.037085,-0.751932,0.330596,-0.617392,-0.242339,0.858120,0.198292,-0.356989,-0.012456,0.495408,0.947477,0.008148,0.219244,0.542124,0.306840,-0.016248,-0.708393,-0.137079,0.210899,-0.353280,-0.529959,-0.482946,-0.259274,-0.214849,-0.451157,0.480099,0.150300,-0.303626,0.430530,0.036170,0.432697,0.304547,0.529241,-0.167861,-0.112479,0.067513,-0.113972,0.003322,0.093444,0.012153,-0.353909,-0.062835,0.546926,-0.084994,0.249136,0.572637,-0.231073,-0.116625,0.090619,0.273092,-0.048492,-0.009508,0.061111,0.085559,0.068831,0.321770,0.064365,-0.139577,-0.209702,0.112336,-0.066378,-0.794217,0.080256,-0.123553,0.309305,-0.726447,0.490546,0.002365,-0.362320,0.330611,-0.527178,0.031459,0.407955,0.072690,0.379220,-0.376980,-0.062786,-0.297721,0.185585,0.699101,0.225725,-0.460177,0.580075,-0.304834,-0.358799,-0.081096,-0.218600,-0.546854,-0.232513,0.276178,0.156495,-0.377810,0.415778,-0.580988,0.247929,-0.183932,-0.359350,-0.085521,-0.403320,0.124263,-0.444889,-0.236538,-0.504948,-0.565560,-0.000730,-0.035019,-0.473554,0.707632,-1.007650,0.567097,0.708068,-0.086311,-0.430959,0.555390,0.208399,0.261845,0.206550,0.070272,0.601867,-0.001928,0.384016,0.192274,0.641748,-0.009417,-0.089284,-0.664463,0.919151', '1309172', '25763555', '26410683', '4058933');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25931246', '龙珠Z：复活的弗利萨', '动画', '许多年前，宇宙最大魔王弗利萨（中尾隆圣 配音）接连败在超级赛亚人之手，他的残党欲孽则流浪宇宙之中寻找那美克星人的新定居点，以期将弗利萨再度复活。几经周折，军队代理索尔贝（斋藤志郎 配音）利用地球的龙珠把弗利萨带回人间，而这个刚刚复活不久的魔王很快展开了他的复仇计划。半年之后，浩浩荡荡的弗利萨大军降临地球，悟饭（野泽雅子 配音）、比克大魔王（古川登志夫 配音）、克林、天津饭、武天老师挺身而出，而孙悟空（野泽雅子 配音）和贝吉塔（堀川亮 配音）则正跟随维斯（森田成一 配音）在遥远的宇宙深处接受试炼。危机时刻，地球被入侵的消息终于传到维斯和比鲁斯那里，悟空、贝吉塔即将与他们宿命中的冤家再度展开对决……©豆瓣', '野泽雅子', '山室直儀', 5.7, 16065, 'tt3819668', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2389784085.jpg', 5.8, 25.3, 52.5, 13.4, 3.1, '-0.047967,0.300601,-0.586233,0.644023,0.209656,-0.382216,0.271880,0.077408,0.004569,-0.239800,-0.036204,1.037661,-0.219337,-0.071974,0.540430,0.088477,-0.522946,-0.542104,0.019911,-0.153733,-0.073404,-0.348865,-0.579710,-0.228996,-0.035277,-0.397471,0.535613,0.274105,0.015867,0.301640,0.207053,0.350307,-0.317950,0.214055,0.149538,0.215977,0.361736,-0.319247,-0.060361,0.338897,-0.064056,0.034748,0.105122,0.518789,0.070733,0.109362,0.439492,-0.841029,0.479443,-0.398941,0.124134,-0.451467,-0.170596,-0.120438,0.443219,-0.246838,0.040452,0.103222,-0.129551,-0.139083,-0.067141,-0.448856,-0.523069,0.084552,-0.240766,0.053417,0.025050,-0.132069,0.033364,0.458160,0.300283,-0.093636,0.141824,0.706338,0.503079,0.305309,-0.292877,-0.091080,-0.070645,0.066109,0.591707,-0.121685,-0.171300,-0.148116,0.215527,-0.520935,-0.192221,-0.314434,-0.249356,-0.219279,0.595226,0.207370,0.149068,0.602494,-0.683532,-0.148128,-0.519962,-0.152751,-0.012933,-0.001806,-0.108049,-0.940170,-0.068485,0.046424,0.071570,-0.016061,0.171812,0.027517,0.696600,-0.759948,0.546847,0.551948,0.299901,-0.147278,0.448284,-0.266212,0.360065,-0.377767,0.230058,0.518121,0.079880,0.651207,0.207452,0.174619,-0.100484,0.096582,-0.429070,0.680066', '11541282', '1870681', '3178770', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25931618', '铜牌巨星', '剧情', '霍普（梅丽莎·劳奇 Melissa Rauch 饰）从小就立志成为一名体操运动员，在一场世界级的比赛中，霍普虽然脚踝受伤却依然忍痛完成了比赛动作并获得了铜牌的荣誉，这让她成为了家乡乃至世界的骄傲。然而数十年过去，霍普依然生活在过去的光辉之中，靠着曾经的荣誉无所事事的在镇上骗吃骗喝，丝毫没有考虑过已经无法再参加体操比赛的自己今后该过怎样的人生。霍普曾经的教练自杀身亡，留下遗书将体操界的新星玛姬（海莉·路·理查森 Haley Lu Richardson 饰）托付给了霍普，如果霍普能够指导玛姬在世锦赛中成功晋级，前者便能够获得巨额的遗产。在金钱的诱惑下，霍普开始了对玛姬的魔鬼训练。©豆瓣', '梅丽莎·劳奇', '布莱恩·巴克利', 7.1, 17444, 'tt3859304', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2355611320.jpg', 0.7, 4.5, 45.3, 40, 9.5, '-0.092716,0.485310,-0.687833,0.646910,-0.315917,-0.608295,0.366404,-0.047299,-0.441154,-0.192968,0.200616,0.846379,-0.005400,0.250813,0.321915,-0.217736,-0.114961,-0.752242,-0.055642,-0.232765,-0.510953,-0.430228,-0.269568,-0.031760,-0.217271,-0.444242,1.016249,0.166452,-0.189865,0.496379,0.368901,0.054414,0.320349,0.300224,-0.423075,-0.038095,0.119642,0.227481,-0.529251,0.338688,0.101606,-0.264758,-0.170117,0.317862,0.277163,0.006214,0.560016,-0.369975,0.090844,-0.116264,0.366317,-0.075536,0.040971,0.086388,0.232793,0.122786,0.158632,0.314473,-0.068791,0.324836,0.070897,-0.290113,-0.980812,-0.182436,0.054566,0.267304,-0.685764,0.610010,-0.001913,-0.084596,-0.081902,-0.104728,0.032473,0.215396,0.102511,0.292347,-0.375921,0.088135,-0.464164,0.427889,0.524709,-0.139308,-0.316758,0.359576,-0.145751,-0.513950,-0.093446,-0.378947,-0.273947,0.118197,0.354506,0.340976,-0.214531,0.229015,-0.571683,0.174487,-0.246321,-0.396729,-0.034106,-0.463071,0.068720,-0.516993,0.116930,-0.267423,-0.364515,0.041395,0.059533,-0.564630,0.666503,-0.963737,0.284816,0.568435,0.287306,-0.153655,0.495350,0.163006,0.378528,-0.073533,-0.146986,0.560685,-0.000260,0.520319,0.018554,0.297845,0.102773,-0.153826,-0.331546,0.974573', '24875409', '1870681', '25880986', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25932065', '睡梦医生', '剧情', '《闪灵》续集《睡眠医师》(Doctor Sleep)北美定档2020年1月24日，依然根据斯蒂芬·金的同名小说改编，迈克·弗拉纳甘(《杰罗德游戏》《死亡占卜2》《梦醒之前》)执导。本片聚焦闪灵里的儿子Danny Torrance，经历了Overlook Hotel里可怕的童年时光后，他已经流浪了几十年，渴望摆脱父亲的绝望、酒精、暴力等特质，最终定居在新罕布什尔州的一个小镇上，这是一个支持他的AA制社区，他在一家养老院找到工作，在那里他残余的“闪灵”之力为垂死之人提供了至关重要的最终安慰。在一只有预知能力的猫的帮助下，他成为了“睡眠医师”。2001年女婴Abra Stone诞生，她逐渐开始展现超自然之力，似乎预测到了911事件。她缓慢而无意地与Danny建立起心灵感应的纽带，随着她的成长，力量也比Danny的更加强大，Danny被重新激起他心中的恶魔，并召唤他为Abra的灵魂和生存战斗。弗拉纳甘重写剧本，此前由Akiva Goldsman改编。', '伊万·麦克格雷格', '迈克·弗拉纳根', 7, 31333, 'tt5606664', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2571039507.jpg', 1.6, 8.2, 40.9, 37.3, 11.9, '-0.078461,0.163305,-0.628444,0.656906,-0.043468,-0.158604,0.706393,0.035912,-0.366929,-0.233671,0.227124,0.703113,-0.083303,0.265072,0.211357,-0.203092,-0.236648,-0.719962,0.060961,0.119047,-0.292462,-0.354463,-0.597162,-0.097390,-0.097983,-0.608665,0.816099,0.162354,-0.185252,0.238948,-0.187170,0.239896,0.067794,0.311959,-0.085637,-0.045410,-0.071432,-0.005208,-0.175390,0.390132,0.121697,-0.415568,-0.064343,0.188438,-0.107795,0.312904,0.741944,-0.390613,-0.147928,-0.308455,0.530259,-0.259553,-0.151685,-0.119661,0.104537,0.222620,0.043387,0.166094,-0.250455,-0.077663,-0.183000,-0.130828,-1.050481,-0.093449,0.034162,0.110667,-0.492403,0.343604,-0.019024,0.097565,0.007412,-0.374535,-0.119598,0.312804,0.181339,0.418747,-0.388380,-0.022507,-0.348409,0.255482,0.554863,-0.216938,-0.588058,0.503531,-0.216065,-0.570176,-0.239300,-0.179122,-0.354239,-0.088733,0.373812,0.447032,-0.260123,0.482927,-0.747444,0.115414,-0.226621,-0.268760,-0.041021,-0.336947,0.078975,-0.667220,-0.485081,-0.143384,-0.162790,-0.150162,0.245292,-0.520754,0.766627,-0.762032,0.345702,0.747595,0.261913,-0.379031,0.467775,-0.161593,0.173150,-0.242311,0.075184,0.539846,-0.102528,0.485994,0.261180,0.283903,