INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25932086', '我是谁：没有绝对安全的系统', '悬疑', '本杰明是一个这样的人：三次元现实世界中，他是一个十足的屌丝&Loser，难以找到存在感，没有时尚感、没有朋友，也没有女朋友。但是二十五岁的他却是一个的电脑极客，拥有对数字技术不可思议的天赋。而影片中另一位主人公马克思是一个渴望“黑客世界”的潜在革命者，他注意到了本杰明在 网络方面的惊人才华，马克思、本杰明和神童斯蒂芬以及保罗私人组建了黑客组织CLAY，并且为了正义入侵国际安全系统。他们凭借高超黑客技术的所为引起了德国秘密警察组织、欧洲刑警组织的重视，并且一个邪恶的黑客将他们视作威胁，想要将他们除去。本杰明因此感觉到自己正在面临生死攸关的考验，并且他们的目标似乎不值得他付出如此大的代价……', '汤姆·希林', '巴伦·博·欧达尔', 8.2, 221595, 'tt3042408', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2201518484.jpg', 0.3, 1.4, 16.9, 49.6, 31.8, '0.310606,0.271870,-0.889089,1.064602,-0.571477,0.124871,0.810349,-0.151461,-0.757720,-0.382084,0.315687,0.911071,0.120601,-0.001275,0.053767,-0.014189,0.014448,-0.634270,-0.121960,-0.308245,-0.391685,-0.626131,-0.716309,-0.489164,-0.433735,-0.356900,0.769044,0.150409,-0.600039,0.068403,0.136390,0.420142,0.279807,0.711596,-0.171553,-0.207226,0.378943,-0.222944,-0.210860,0.339928,0.116971,0.049432,-0.017302,0.723452,-0.390962,0.254581,0.562051,-0.291562,-0.229797,-0.184044,0.544130,-0.414694,-0.142169,-0.011899,0.324807,-0.051762,0.151943,0.192157,0.214517,-0.083227,0.082958,-0.138315,-1.463446,-0.189219,0.155487,0.152451,-0.355358,0.483354,-0.547678,-0.211574,0.101658,-0.165332,0.061147,0.251977,0.468134,0.305478,-0.115441,0.099608,-0.487247,0.157190,0.713560,-0.078300,-0.488008,0.560993,-0.499463,-0.659602,-0.264754,-0.503727,-0.454887,-0.002279,0.268050,0.118907,-0.229912,0.173625,-0.605281,0.157195,-0.240550,-0.148647,-0.090065,-0.538704,0.052303,-0.583604,-0.402743,-0.513296,-0.174630,0.109430,0.174961,-0.407074,1.365739,-1.028854,-0.053575,0.950313,0.292369,-0.660954,0.924269,0.008492,-0.087996,-0.382364,-0.167670,0.051426,-0.063585,0.326071,-0.015045,0.331631,0.026855,-0.248979,-0.040408,0.520607', '27602116', '24284209', '30163500', '1793491');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25933890', '极盗车神', '动作', '由英伦鬼才导演埃德加·赖特执导编剧的《极盗车神》，讲述了关于天赋极高的犯罪团伙司机——名为“Baby”的年轻人的故事。Baby（安塞尔·艾尔高特 Ansel Elgort 饰）专门负责帮银行抢劫犯开车逃脱。Baby因童年的一场事故导致耳疾，要靠专属的音乐来掌控开车节奏。偶然的一次邂逅，他与餐厅女服务生（莉莉·詹姆斯 Lily James 饰）坠入爱河，并想就此金盆洗手。头目老大道哥（凯文·史派西 Kevin Spacey 饰）表示，只要Baby再完成最后一次任务，就可以给他自由。殊不知，巨大的危险和挑战在等待着Baby……', '安塞尔·艾尔高特', '埃德加·赖特', 7, 158325, 'tt3890160', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2496901482.jpg', 1.1, 6.1, 42.5, 39.7, 10.6, '-0.030607,0.054307,-0.203457,0.470048,-0.077389,-0.401961,0.315714,0.241502,-0.405900,-0.240471,0.074630,0.693098,0.090385,-0.083091,0.601692,-0.130199,-0.379316,-0.416388,0.043793,0.048970,-0.276372,-0.494209,-0.037645,-0.130939,0.064750,-0.188654,0.370435,-0.036028,-0.348304,0.256298,0.289969,0.246699,-0.188978,0.111838,-0.012423,-0.129609,0.159876,0.005015,-0.382774,0.291489,0.224735,-0.063434,0.037106,-0.006823,0.125957,-0.026573,0.506691,-0.349760,-0.113206,-0.076586,0.252939,-0.252443,0.068940,-0.256509,0.015912,0.098074,0.387512,0.470961,-0.014025,0.004568,0.173365,-0.195804,-0.683287,-0.009772,0.075214,-0.015016,-0.465578,0.301311,-0.041689,0.061518,0.128381,-0.139270,-0.110259,0.223886,0.548286,0.247397,-0.046004,-0.074124,-0.235595,0.318304,0.466851,0.187076,0.014248,0.349967,0.039909,-0.350237,-0.065755,-0.043013,-0.430387,0.260930,0.348867,-0.005586,-0.076757,-0.062688,-0.500122,-0.119874,-0.368407,-0.029270,-0.128782,-0.304655,0.064814,-0.820514,0.145350,0.222322,0.003478,-0.004453,0.264068,0.013041,0.311297,-0.742904,0.343917,0.690768,0.230425,-0.236717,0.613008,0.186674,0.196635,-0.606197,-0.034941,0.065703,0.028890,0.398423,-0.038481,0.195189,-0.019899,-0.360457,-0.289886,0.233746', '3178770', '11541282', '3326747', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25933898', '爱恋', '剧情', '曾携手莫妮卡·贝鲁奇和文森特·卡索以电影《不可撤销》轰动戛纳的导演加斯帕·诺携新作《爱恋3D》重返戛纳，影片聚焦一男两女的情欲爱情，新人男主卡尔·格洛斯曼单挑大梁，让影片备受关注。影片入围第68届戛纳电影节午夜展映单元和酷儿棕榈单元。', '卡尔·格洛斯曼', '加斯帕·诺', 6.8, 26865, 'tt3774694', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2261493682.jpg', 2.3, 11, 44.9, 28.9, 12.9, '-0.364296,-0.273265,-0.577426,0.731367,0.876807,-0.223608,0.549363,0.337669,-0.338659,0.279488,0.355101,0.815739,-1.002631,0.167241,0.571594,-0.038947,-0.930547,-0.723780,-0.214131,0.035281,0.475674,0.162556,-0.240994,0.418546,-0.105067,-0.433398,0.850136,-0.033102,-0.286095,0.559512,0.995738,0.267402,-0.257126,-0.154835,0.491862,0.282628,0.438510,-0.011574,-1.001117,0.541317,0.003370,-0.093540,-0.659853,-0.244250,0.092876,0.103696,0.587349,0.032278,0.156428,0.097380,0.881288,-0.339859,-0.130729,0.133424,0.016122,-0.126010,0.634118,0.343530,0.343324,0.379906,-0.145087,-0.300294,-0.547554,0.354790,0.024051,0.285925,-0.017636,0.436955,-0.379655,0.222220,0.154563,0.204291,-0.089430,-0.021294,0.521724,-0.023428,0.003209,-0.023952,0.163746,0.391345,0.283969,-0.042790,-0.440036,0.451879,-0.116382,-0.538854,-0.244773,-0.263387,-0.737421,0.619558,0.551287,-0.182619,0.179996,0.551452,-0.234103,-0.354114,-0.078644,-0.728560,0.201434,-0.005868,0.421713,-1.459607,-0.243776,-0.044170,0.114090,-0.459565,0.310612,-0.427203,0.591361,-0.258145,0.214240,0.376338,0.384720,-0.287316,1.095642,0.062370,-0.117829,-0.331181,-0.275321,0.545959,-0.237130,0.013048,-0.197456,0.396740,-0.141425,-0.150795,-0.356081,0.427729', '34961898', '30397916', '3275168', '24751811');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25934014', '爱乐之城', '剧情', '米娅（艾玛·斯通 Emma Stone 饰）渴望成为一名演员，但至今她仍旧只是片场咖啡厅里的一名平凡的咖啡师，尽管不停的参加着大大小小的试镜，但米娅收获的只有失败。某日，在一场派对之中，米娅邂逅了名为塞巴斯汀（瑞恩·高斯林 Ryan Gosling 饰）的男子，起初两人之间产生了小小的矛盾，但很快，米娅便被塞巴斯汀身上闪耀的才华以及他对爵士乐的纯粹追求所吸引，最终两人走到了一起。在塞巴斯汀的鼓励下，米娅辞掉了咖啡厅的工作，专心为自己写起了剧本，与此同时，塞巴斯汀为了获得一份稳定的收入，加入了一支流行爵士乐队，开始演奏自己并不喜欢的现代爵士乐，没想到一炮而红。随着时间的推移，努力追求梦想的两人，彼此之间的距离却越来越远，在理想和感情之间，他们必须做出选择。©豆瓣', '瑞恩·高斯林', '达米恩·查泽雷', 8.4, 818202, 'tt3783958', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2395517414.jpg', 0.6, 2.2, 16.1, 37.9, 43.1, '0.494401,0.379194,-0.693898,0.690291,0.022663,-0.303761,0.830985,0.167674,-0.377584,-0.250002,0.119853,0.678980,-0.142910,0.144695,0.367490,-0.045452,-0.289152,-0.819182,-0.004773,-0.036197,-0.162024,-0.525160,-0.470390,-0.036776,-0.417323,-0.389185,0.566125,0.119807,-0.092598,0.579859,0.425898,0.012577,-0.055520,0.526544,0.177012,-0.103746,0.348084,-0.033318,-0.230358,0.318037,0.272143,-0.227566,-0.240725,0.031568,0.101369,0.432060,0.570578,-0.117453,-0.066084,0.160606,0.372410,-0.217567,-0.056820,-0.001201,0.070514,0.227257,0.374264,0.044743,-0.213833,0.053324,0.018259,-0.138930,-0.737568,0.199045,0.170310,0.294320,-0.588152,0.577780,-0.082098,-0.361558,0.212383,-0.378101,0.033526,0.440628,0.356758,0.212305,-0.372384,-0.065092,-0.410763,0.039785,0.778087,0.129689,-0.422750,0.454249,-0.513067,-0.387126,-0.261546,-0.089915,-0.397381,-0.238017,0.249085,0.247253,0.097100,0.119501,-0.752755,0.035706,-0.046764,-0.240219,0.106003,-0.498909,0.152183,-0.759525,-0.035216,-0.518648,-0.291517,-0.097649,0.009355,-0.534228,0.796541,-0.909150,0.214764,0.598840,0.276587,-0.277611,0.649954,0.042726,0.325261,-0.007901,-0.177896,0.350126,-0.240431,0.090050,0.048232,0.502783,0.016895,-0.231592,-0.544640,0.769760', '30162520', '2053515', '34429100', '5977789');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25936147', '意外空间', '科幻', '兄弟二人生活过的紧巴巴，弟弟生性懦弱，哥哥强势霸道，这天，哥哥抢劫别人得来了钱，兄弟二人正高兴之际，一名侦探找上门来，双方发生争执，追逐之中，三个人发现自己被困于无穷无尽的楼梯上，无论如何都走不到尽头 ……另一边，一家人被困于无边无境的马路上，相同的加油站，相同的便利店，四周一望无际的荒野，却如何都逃不出这可怕的地狱……两个没有界限的空间，他们要如何应对内心逐渐升起的绝望？', '胡伯托·巴斯托', '伊萨克·厄兹本', 7.6, 42594, 'tt3528756', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2192863764.jpg', 1.1, 4.1, 28.9, 46.7, 19.2, '0.351042,0.047685,-0.913163,0.527994,-0.015522,-0.203395,0.993880,0.119656,-0.412974,-0.089849,0.151654,0.463259,-0.048016,0.237386,-0.065737,-0.095348,0.104343,-0.294695,-0.530421,-0.142934,-0.358613,-0.154881,-0.417743,0.160264,-0.204042,0.310150,0.598019,0.339062,0.056097,0.389164,0.226999,0.046178,-0.446958,0.627949,-0.186429,0.028611,-0.014845,0.233328,-0.041243,-0.112199,-0.231134,0.024469,-0.120740,0.203857,-0.214333,0.297744,0.636681,0.002461,-0.057059,-0.107022,0.349766,-0.078688,-0.225668,0.468496,0.302471,-0.212253,0.064955,-0.167595,-0.022752,-0.303237,-0.308250,0.194989,-0.712556,-0.015809,-0.105204,-0.022463,-0.458553,0.119640,0.231101,-0.342500,-0.023027,-0.453658,0.108102,-0.038254,0.096647,0.410400,-0.203690,-0.449623,-0.595975,-0.164503,1.067678,-0.213736,-0.244374,0.211882,-0.258013,-0.055614,0.081928,-0.536317,-0.778575,-0.292197,0.310673,0.149838,-0.315900,0.171998,-0.397852,0.402670,-0.222515,-0.098793,-0.379978,-0.485239,-0.285902,-0.244861,-0.141285,-0.501264,-0.227971,0.531477,-0.249487,-0.084125,0.345701,-0.463281,0.313155,0.545054,0.330782,-0.204844,0.706058,0.067653,0.101247,-0.106764,-0.081007,0.168483,0.283840,0.461473,0.235073,0.246092,-0.058628,0.370682,-0.469694,0.446739', '26715845', '1291835', '21619567', '1307311');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25937854', '银河护卫队2', '动作', '火箭浣熊（布莱德利·库珀 Bradley Cooper 饰）偷走了大祭司阿耶莎（伊丽莎白·德比齐 Elizabeth Debicki 饰）的能量电池，包括星爵（克里斯·帕拉特 Chris Pratt 饰）、卡魔拉（佐伊·索尔达娜 Zoe Saldana 饰）、德拉克斯（戴夫·巴蒂斯塔 Dave Bautista 饰）在内的一行人遭到了后者派出的舰队的袭击。一个神秘人物乘坐着飞船救下了银河护卫队的众人，而驾驶着飞船的不是别人，竟然正是星爵的亲生父亲伊戈（库尔特·拉塞尔 Kurt Russell 饰）。在伊戈的带领下，星爵、卡魔拉和德拉克斯来到了由伊戈一手制造的星球上，而剩下的成员们则着手修复损坏的飞船。那边厢，阿耶莎委托勇度（迈克尔·鲁克 Michael Rooker 饰）抓住星爵替自己报仇，而卡魔拉亦渐渐发现了伊戈和善面目下隐藏的巨大阴谋。©豆瓣', '克里斯·帕拉特', '詹姆斯·古恩', 8, 432647, 'tt3896198', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2455261804.jpg', 0.4, 2.5, 22.8, 47, 27.2, '0.308120,0.103617,-0.548902,0.672135,-0.022571,-0.186700,0.772160,0.360986,-0.152876,-0.251070,0.369456,0.588399,-0.003644,0.176042,0.506824,0.256914,-0.460016,-0.382164,-0.180201,-0.026654,-0.526716,-0.593681,-0.307257,-0.312213,0.218538,-0.612960,0.466839,-0.083173,0.176018,0.484525,0.394535,0.697450,-0.222055,0.067690,0.045883,0.222342,0.118567,-0.449792,0.059319,0.220242,-0.487068,-0.004966,-0.021216,0.196825,-0.040535,0.508485,0.580759,-0.404137,0.472580,-0.376004,0.024164,-0.387212,0.470216,-0.152162,0.177975,-0.036061,-0.148500,0.000754,-0.220713,0.264121,0.364669,-0.034328,-0.683592,0.020712,-0.006923,0.190280,-0.643260,0.260212,-0.414286,-0.021545,-0.000759,-0.116711,0.136230,0.313866,0.012113,0.064696,-0.073083,0.062218,-0.626342,-0.132277,0.089893,-0.188036,-0.032805,0.187558,-0.038431,-0.238487,-0.210708,-0.183771,-0.382763,-0.302820,0.629244,0.071345,0.472698,0.193798,-0.691479,-0.218042,-0.390985,-0.228277,-0.060941,-0.264593,-0.004313,-0.836908,0.098019,-0.194381,-0.223646,0.163253,-0.255538,0.066899,0.519180,-0.357788,0.164248,0.334491,0.027352,-0.113619,0.320888,-0.257876,0.167701,-0.125568,-0.151032,0.226952,0.415773,0.174068,0.316276,0.347220,-0.021533,-0.268361,-0.134606,0.384262', '6040982', '651