INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25937991', '命运之夜——天之杯Ⅰ：恶兆之花', '动画', '动画剧场版《命运之夜—— 天之杯：恶兆之花》，是TYPE-MOON发售的文字冒险游戏《Fate/stay night》中第三条剧情线，简称“HF”或“樱线”。在故事中，圣杯是传说中可实现持有者一切愿望的宝物。7位御主（Master）和7位从者（Servant）为了得到圣杯而相互厮杀的仪式被称为圣杯战争。「圣杯战争」发生十年后，冬木市再次迎来了战争，一股不安的氛围笼罩着全城。有人暗施诡计，让这场战争开始逐渐陷入混乱……', '杉山纪彰', '须藤友德', 7.4, 35189, 'tt4054952', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2545044503.jpg', 2.4, 7.7, 30.2, 38.2, 21.5, '-0.314284,0.674502,-0.488447,0.448347,0.441319,0.273535,0.677492,-0.448649,-0.299366,-0.231738,0.120911,0.785858,-0.620144,-0.226003,0.425406,-0.036641,-0.317838,-0.915889,-0.106304,0.131953,-0.377515,-0.079698,0.161146,-0.012785,-0.136382,-0.727006,1.314495,0.711394,-0.393072,-0.035013,0.364031,0.479386,-0.473640,0.290819,0.294010,-0.285363,0.025332,-0.039959,-0.632376,0.284271,-0.433070,-0.331438,-0.504397,0.288022,-0.342811,-0.144006,0.937664,-0.795446,0.202574,-0.178816,0.630437,-0.452882,-0.484177,0.047803,0.304808,0.347963,0.252683,0.383671,0.115682,0.039738,-0.046001,-0.369631,-0.723153,-0.051966,-0.268188,0.529341,0.224224,0.077017,0.189092,0.042220,0.328375,0.111448,0.613423,0.448806,0.967921,0.020175,-0.327885,-0.399980,-0.551150,0.037477,0.816212,-0.466220,-0.569858,0.632405,-0.231008,-0.535639,-0.302655,-0.184885,-0.275563,0.167644,0.530410,0.170095,0.089477,0.873385,-1.037569,-0.001681,0.092830,-0.602469,0.142770,-0.292503,0.048075,-0.721094,-0.661593,-0.001589,-0.051247,-0.061942,0.271153,-0.517699,0.435832,-0.924764,0.350324,0.550554,-0.303814,-0.170316,0.257466,0.545317,0.333670,-0.223886,0.213437,0.036756,-0.286801,0.261457,-0.003777,-0.150655,0.191967,0.163263,-0.207902,0.737885', '26759819', '26759820', '7051375', '30201138');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25938113', '火影忍者剧场版：终章', '喜剧', '第四次忍界大战结束的两年后，此时此刻的漩涡鸣人（竹内顺子 配音）早已成为盖世英雄一般的人物，无论他走到哪里都受到女孩子和小朋友的喜爱与追捧，他似乎也有其享受这样喧嚣欢闹的氛围。与之相对，壁花小姐日向雏田（水树奈奈 配音）则始终站在角落里，默默注视着这个她喜欢了多年的男孩子。雏田亲手为鸣人织了围巾，怎奈无法鼓足勇气交给对方，喜欢的话语更难以说出口。某个夜晚，雏田的妹妹花火（浅井清己 配音）遭到不明身份之人劫持，带火的陨石则落在附近的山坡之上。为了救回花火，阻止地球毁灭，鸣人、雏田、小樱（中村千绘 配音）、鹿丸（森久保祥太郎 配音）和佐井奉命前去调查舍人（福山润 配音）的真身。在此过程中，鸣人不小心知晓了雏田的心意……本片情节介乎《火影忍者》漫画699话和700话之间©豆瓣', '竹内顺子', '小林常夫', 7.6, 24832, 'tt3717532', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2204929585.jpg', 3.4, 6.6, 27, 33.3, 29.8, '0.235097,0.022856,-0.608213,0.452833,0.091075,-0.059208,0.529791,0.249690,-0.131001,-0.352711,0.184898,0.619731,-0.346549,0.249267,0.179671,0.026045,-0.307759,-0.611890,-0.290527,0.043929,-0.142294,-0.446570,0.026147,0.105432,-0.371157,-0.178342,0.717529,0.026819,-0.097866,0.439163,0.215463,0.304006,-0.303717,0.475811,0.145344,0.106588,-0.024759,0.056892,-0.115556,0.120152,-0.119311,-0.340235,-0.223152,0.160032,-0.059177,0.100608,0.570071,-0.207982,0.094403,0.043279,0.126295,-0.386337,-0.035965,0.128675,0.470475,-0.191154,0.283406,0.056969,0.059443,0.006825,-0.044889,-0.019068,-0.448940,-0.004127,-0.016020,0.471145,-0.149540,0.326747,-0.010343,-0.182247,0.318265,-0.309650,0.098965,-0.053421,0.339107,0.222799,-0.499608,0.158759,0.046328,0.006497,0.527318,0.104956,-0.069914,0.301088,-0.089667,-0.346129,-0.088513,-0.125534,-0.320767,0.047952,0.100907,0.290481,-0.140224,0.236397,-0.378266,-0.100947,0.168783,-0.115090,0.110045,-0.496833,-0.156693,-0.608129,-0.048056,-0.572987,-0.207720,0.142623,0.102579,-0.168147,0.805487,-0.898535,-0.052912,0.377953,0.237516,-0.073932,0.402439,0.216912,0.039986,-0.124026,-0.053372,0.139347,-0.073039,0.280020,0.213995,0.293664,0.108446,0.121548,-0.631782,0.180080', '3811356', '1826173', '25922902', '26784898');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25938803', '莫娣', '剧情', '真人真事改编，描述在加拿大美丽的大西洋省份新斯科舍省（Nova Scotia），一位患有关节炎的民间艺术家莫娣·刘易斯(Maud Lewis)，对艺术不懈的追求，与她的丈夫相识，并以艺术、贩卖作品为生的励志生活。', '莎莉·霍金斯', '艾斯林·沃什', 9.1, 115424, 'tt3721954', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2431089276.jpg', 0.1, 0.4, 5.5, 33, 61.1, '0.021302,-0.448407,-0.318133,1.158907,0.255330,-0.281835,0.922572,-0.096280,-0.412378,-0.159062,0.198353,1.079230,0.178035,0.047510,0.331704,0.076575,-0.142053,-0.798979,0.009385,0.099599,-0.026467,-0.238776,-0.414797,-0.260280,-0.296299,-0.410641,0.716402,-0.032443,-0.727125,0.644458,0.023683,0.374714,-0.245181,-0.069278,-0.526062,-0.201770,-0.085556,0.301724,-0.678669,0.111077,-0.007083,-0.102854,-0.199251,-0.105883,-0.283464,0.295736,0.874021,0.028402,-0.064347,-0.063610,0.647981,0.093643,0.144869,0.143616,0.359429,0.025472,0.147105,0.309133,-0.130780,0.052843,-0.023308,-0.389947,-1.004208,-0.396722,0.227183,0.248531,-0.420379,0.578710,0.203718,-0.337804,-0.060132,-0.121644,-0.069164,0.081341,0.258503,0.855594,0.084391,0.240846,-0.309046,1.064215,0.312800,0.082543,-0.419015,0.638223,-0.824985,-0.669966,-0.007045,-0.556048,-0.706158,-0.080543,-0.099288,-0.252423,-0.220562,0.233716,-0.873021,0.196613,0.190339,-0.308168,0.271339,-0.217082,-0.019202,-1.008216,-0.082276,-0.704710,0.009923,-0.330240,0.331788,-0.407910,1.157934,-0.915677,-0.018081,0.581862,0.139890,-0.828731,0.794021,0.427662,-0.153954,-0.393615,-0.467947,0.931559,-0.037112,0.050614,-0.578484,0.441484,0.256040,0.025012,-0.622594,1.070442', '22265121', '27602116', '26647163', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25938856', '七日地狱', '喜剧', '这是部喜剧，伪装成了纪录片，安迪·萨姆博格和“雪诺”基特·哈灵顿饰演两位网球选手，在2004年的一场比赛中，打了整整七天。凯伦·吉兰、莉娜·邓纳姆、迈克尔·辛、小威、约翰·麦肯罗、威尔·福特客串。7月11日HBO台播出。', '安迪·萨姆伯格', '杰克·西曼斯基', 7.3, 7521, 'tt3895884', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2258047899.jpg', 1.3, 5.1, 36.1, 43, 14.6, '-0.340876,-0.445700,-0.062248,0.160321,0.194532,-0.713382,0.438091,-0.112730,-0.263119,-0.031486,0.051747,0.475354,-0.885189,0.150094,0.969872,-0.065249,-0.887859,-0.761420,-0.240517,-0.274712,-0.001019,-0.534394,-0.131225,-0.168817,0.449424,-0.452354,0.488706,-0.388622,0.161317,0.757994,0.425847,0.257818,0.440901,-0.241363,0.588713,0.518072,0.513659,-0.664422,-0.129215,0.484213,-0.030783,0.038358,-0.471613,-0.195161,0.663272,0.399722,0.233851,-0.077795,0.474950,-0.101090,0.250221,-0.172314,0.007549,-0.245704,0.411484,-0.236352,0.247396,0.433151,-0.155955,-0.071791,-0.067132,-0.525378,-0.243228,0.784583,-0.706912,0.069535,-0.356822,0.672776,-0.386043,0.121128,-0.052379,0.000518,-0.182146,0.200949,0.067528,0.057594,0.138889,-0.296519,-0.116291,0.496756,0.442700,0.177366,-0.313393,0.101104,0.428478,-0.444141,-0.492766,-0.298709,-0.413197,0.243361,0.732951,-0.418442,0.204044,0.202603,-0.306215,-0.098610,-0.372191,-0.554896,-0.117616,0.056183,-0.090852,-1.260162,-0.018006,-0.496739,-0.193697,-0.774994,0.097037,-0.128072,0.381208,-0.792204,0.354787,0.490065,-0.092608,0.511692,0.802906,0.225647,0.281581,0.085729,0.081447,0.303336,-0.054757,0.150551,0.462409,0.697193,0.227442,-0.043260,-0.298592,0.664351', '2075345', '34961898', '3003137', '6517421');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25944282', '纸镇', '剧情', '昆汀（奈特·沃尔夫 Nat Wolff 饰）从很小的时候起就暗恋邻居玛格（卡拉·迪瓦伊 Cara Delevingne 饰），然而拥有美丽外表和开朗个性的玛格从来都不缺少追求者，亦有了相恋的男友，因此昆汀选择将这份感情深深的埋藏在心底。一天深夜，玛格意外的潜入了昆汀的房间，她恳请昆汀帮她一个忙，协助她报复劈腿的前男友。可是第二天，玛格神秘的失踪了，没有留下任何线索，而她和昆汀那一夜的经历成为了永远的秘密。昆汀深知事情没有看上去的那么简单，于是决定凭借自己的力量寻找玛格的下落。一点又一点的线索被发掘出来，一个名为纸镇的地点渐渐浮出了水面。©豆瓣', '纳特·沃尔夫', '杰克·施莱尔', 6.2, 8833, 'tt3622592', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2257178991.jpg', 4.4, 18.1, 48.8, 21.6, 7.1, '0.327166,-0.099589,-0.735733,0.690356,-0.444523,-0.285623,0.759700,0.047295,-0.417650,-0.329738,-0.001692,0.737453,-0.159283,-0.059564,0.140154,-0.087162,-0.381957,-0.631860,0.152251,-0.268260,-0.039843,-0.554036,-0.503189,-0.142992,0.077295,-0.391796,0.611187,0.079166,-0.116312,0.553929,0.230765,0.310806,0.026833,0.637457,-0.128888,-0.034359,0.131499,0.028837,0.206198,0.253465,0.211782,-0.238316,0.147439,0.467359,-0.078937,0.581203,0.343966,-0.308661,-0.178199,0.093485,0.308574,-0.213830,0.078386,0.042320,0.320916,-0.067723,-0.033791,0.303286,-0.416030,-0.244719,0.337329,-0.202999,-0.885040,-0.135945,0.249883,0.370029,-0.698092,0.317223,-0.337274,-0.153416,0.009651,-0.349825,0.211326,0.321759,0.256789,0.077000,-0.101667,-0.202998,-0.607061,0.059893,0.425582,-0.185158,-0.220216,0.607201,-0.259245,-0.371869,-0.180023,0.044080,-0.260405,0.068888,0.327486,0.215066,-0.282889,0.101901,-0.550114,-0.137288,-0.229253,-0.206497,0.002274,-0.637394,-0.126648,-0.442948,-0.357545,-0.329423,-0.473779,-0.208016,-0.029663,-0.174074,0.624609,-0.865272,0.428725,0.644906,0.159617,-0.303430,0.661546,0.130511,0.123438,0.123775,0.221679,0.448148,-0.041866,0.160331,0.109698,0.347750,0.022404,-0.248668,-0.438644,0.556952', '1793491', '1783461', '25932086', '3119246');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25944714', '超脑48小时', '剧情', '一位知悉国家机密的CIA探员比利·波普（瑞恩·雷诺兹 Ryan Reynolds 饰）意外身亡，在弗兰克斯博士（汤米·李·琼斯 Tommy Lee Jones 饰）的协助下将其记忆与技能植入了一位极度危险且无法预测的罪犯杰里科·斯图尔特（凯文·科斯特纳 Kevin Costner 饰）身上，而探员贵格·威尔斯（加里·奥德曼 Gary Oldman 饰）必须靠这位不定时炸弹来摧毁企图攫取国家机密的犯罪组织。杰里科·斯图尔特为了救回换脑后渐渐爱上的比利·波普被胁迫的妻子和孩子，重新找回自己的生活，不得不在48小时的时间里，与犯罪组织展开殊死搏斗。©豆瓣', '凯文·科斯特纳', '阿里尔·弗罗门', 6.6, 50538, 'tt3014866', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2351313845.jpg', 1.6, 10.7, 53.2, 27.3, 7.3, '0.249983,-0.066489,-0.446985,0.625960,-0.226092,-0.325768,0.803774,0.024776,-0.507851,-0.454926,0.137356,0.618644,0.026265,0.037482,0.396076,0.041642,-0.646148,-0.725980,-0.044857,-0.389672,-0.509044,-0.818623,-0.502938,-0.349071,0.006891,-0.345200,0.616424,-0.109316,-0.173873,0.207391,0.217185,0.833067,0.128504,0.269082,-0.056201,-0.032649,0.290984,-0.474570,-0.356771,0.304242,0.385786,-0.221701,0.033182,0.116735,-0.081635,0.183604,0.677493,-0.403321,0.094197,-0.490603,0.230279,-0.277710,0.211750,0.018603,0.217265,0.007339,0.006557,0.330640,-0.250218,-0.086380,0.407357,-0.123439,-0.754756,-0.090368,0.092261,0.325689,-0.359083,-0.015144,-0.454155,0.282527,0.056416,-0.214669,-0.067035,0.364316,0.315882,0.094508,-0.233456,0.029011,-0.466889,0.077949,0.322501,-0.090098,-0.244963,0.079039,-0.174600,-0.473466,-0.115918,-0.070091,-0.395808,-0.153396,0.463618,0.196862,-0.025384,0.412642,-0.398481,-0.359994,-0.519809,-0.117402,-0.253209,-0.286818,0.049056,-0.682757,-0.165264,-0.042718,-0.043611,0.041092,0.086683,-0.066558,0.440222,-0.607808,0.268507,0.424883,0.110053,-0.249639,0.322840,0.012304,0.291808,-0.429121,-0.106172,0.380280,0.407559,0.345354,0.290466,0.262827,0.039209,-0.053771,-0.270754,0.284702', '2988294', '1316693', '1307442', '20277632');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25944886', '灾难艺术家', '剧情', '詹姆斯·弗兰科从去年起就计划将邪典电影《房间》的拍摄过程搬上银幕，近日该片不仅确定了片名《灾难艺术家》(The Disaster Artist)，还找来了以投拍发行恐怖电影为主的新线影业做接盘侠。2003年上映的《房间》是托米·韦素自编自导自演的一部邪典电影，该片被很多人视作最烂电影之一。不过，影片完全烂出了风格与境界，甚至被称为“烂片界的《公民凯恩》”。影片基本上就是围绕着托米·韦素饰演的主人公与他的未婚妻以及最好朋友之间的三角恋情展开，无论是演员的渣演技、剧情的神转折还是毫无美感的运镜都让人印象深刻。2013年，参演《房间》的演员之一格雷·戈泽斯特洛和汤姆·比塞尔联合出版了《灾难艺术家》，回顾了该片的拍摄过程。戈泽斯特洛在书中写到，托米·韦素在开拍此片时完全没有任何电影制作经验。弗兰兰在担任该片导演的同时，还会出演托米·韦素，他的弟弟戴夫·弗兰科则会出演格雷·戈泽斯特洛。弗兰兰的好基友塞斯·罗根在担任影片制片的同时还在协商加盟演出，另外担任制片的还包括埃文·戈登伯格、Vince Jolivette以及弗兰兰自己。小清新爱情片《星运里的错》和《好景当前》的编剧斯考特·诺伊施塔特和迈克尔·H·韦伯已为影片执笔剧本。影片定于今年12月7日开拍。', '詹姆斯·弗兰科', '詹姆斯·弗兰科', 7.5, 48584, 'tt3521126', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2498866082.jpg', 0.8, 3.5, 30.8, 47.8, 17.1, '0.070130,-0.213701,-0.415531,0.614724,0.414702,-0.424163,0.540406,0.367531,-0.228669,-0.308807,0.119914,0.709970,-0.414931,-0.122865,0.404276,-0.044274,-0.733066,-0.685470,-0.356072,-0.008465,0.025578,-0.380222,-0.349870,0.029921,-0.110884,-0.530405,0.708524,-0.206628,-0.401186,0.216669,0.368654,0.150717,-0.068103,0.221138,0.341169,0.331642,0.129579,-0.194408,-0.474919,0.425405,0.215205,-0.091807,-0.332239,-0.039555,0.166996,0.489596,0.707491,-0.114015,-0.013511,0.101151,0.614371,-0.249176,-0.145748,-0.165686,0.153720,-0.159299,0.430674,0.346949,-0.033884,0.263524,-0.045371,-0.508192,-0.978494,0.127003,0.191844,0.240199,-0.359277,0.381798,-0.362537,0.063406,0.019135,-0.398043,0.038493,0.028966,0.343534,0.313044,-0.036273,0.028740,-0.384800,0.590061,0.226035,0.173600,-0.233452,0.488657,0.039384,-0.540909,-0.404158,-0.188065,-0.478417,0.225166,0.279946,-0.192711,0.066380,0.108115,-0.530143,-0.151269,-0.065085,-0.395069,0.087894,-0.310211,0.137214,-1.084676,-0.239766,-0.102990,0.048425,-0.425105,0.265924,-0.339007,0.742540,-0.520533,0.175967,0.435064,0.220405,-0.072380