INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25945280', '我的特工爷爷', '剧情', '退休军官老丁（洪金宝 饰）因“健忘症”弄丢孙女，内疚回到老家。邻居小女孩春花（陈沛妍 饰）成为他的慰藉。可女孩的父亲（刘德华 饰）无意卷入了当地黑帮团伙的争斗中。老丁为营救春花挺身而出，也寻回那份作为军人的骄傲和弥补作为爷爷的过错。', '洪金宝', '洪金宝', 5.5, 65630, 'tt4076934', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2325687277.jpg', 9.1, 27.9, 45.4, 12.5, 5.1, '-0.161281,-0.296823,-0.279537,0.006763,-0.536701,-0.236902,0.605434,0.199507,-0.497345,-0.153730,0.434891,0.748642,0.377784,0.427793,0.379290,0.217086,-0.085059,-0.474980,0.149841,-0.008020,0.231264,-0.293923,-0.212268,-0.104571,-0.009298,-0.200721,0.731266,-0.248674,-0.541256,0.371622,0.136145,0.383350,-0.323121,0.093531,-0.169399,0.373336,-0.227567,0.129915,-0.381402,-0.240881,-0.217744,-0.057829,-0.059877,-0.188820,0.155063,0.527098,0.581787,-0.136176,-0.084386,-0.357373,0.293560,-0.185989,-0.255303,-0.119374,0.095808,0.027783,0.319864,0.130683,-0.090934,-0.286930,0.330368,-0.011530,-0.534559,0.171123,0.560648,-0.036997,-0.682402,0.493648,0.172583,-0.019308,0.218529,0.165334,0.203991,0.145755,-0.092210,0.394862,-0.338067,0.307843,-0.320301,0.517086,0.273889,-0.407766,0.141961,0.038455,-0.128297,0.079668,0.553671,-0.543469,-0.439829,0.149898,0.119598,-0.331501,-0.088973,0.299630,-0.412966,-0.408426,-0.252000,0.130922,0.280334,-0.332263,-0.050244,-0.123695,-0.177774,-0.245222,-0.489862,-0.275394,0.113259,0.007463,0.663198,-0.429621,0.137354,0.397838,0.090129,-0.568199,0.547306,0.260111,0.356225,-0.474206,-0.156052,0.200501,0.097346,0.074802,0.124354,-0.244713,-0.185428,-0.352998,0.036366,-0.093829', '1908036', '4847665', '6101834', '25890078');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25945356', '新步步惊心', '爱情', '早已成为国际大都会的北京城，生活着古灵精怪的小白领张小文（陈意涵 饰）。她渴望浪漫美好的恋情，无奈命中注定的另一半始终不曾到来。某天，她突遭意外跌入水中。当小文浮出水面，发现自己身着古装，旁边有一个念着奇怪咒语的戴面具的男子，之后更被神秘之人追杀，关键是个则被一名英俊帅气的男子救起。小文原本以为这只是一个离奇的梦，谁知一觉醒来发现自己真的穿越到清朝，成了名叫马尔泰若曦的哥哥。在此期间，她邂逅了还未成为雍正皇帝的四阿哥胤禛（杨祐宁 饰）以及日后卷入皇储之争的十四阿哥胤禵（窦骁 饰）。浪漫的爱情和皇宫风云，小文注定经历一场传奇……本片根据桐华的小说《步步惊心》改编。©豆瓣', '陈意涵', '宋迪', 4.1, 26541, 'tt4886030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2259532859.jpg', 34, 35.2, 23.3, 4.8, 2.6, '0.193782,0.289212,-0.725404,0.564619,0.147429,-0.364793,1.013598,-0.066487,-0.323549,-0.392914,0.466444,0.452004,-0.243486,0.329912,0.432102,0.153247,-0.036060,-0.534447,-0.287689,-0.021128,-0.022404,-0.072855,-0.452922,0.245865,-0.151907,-0.371267,0.619207,0.207593,-0.118777,0.371823,0.461845,0.123456,-0.141090,0.326667,-0.346254,0.217513,0.060312,0.192467,-0.019025,-0.028192,-0.046857,-0.416122,-0.117613,0.158013,-0.361469,0.155533,0.653966,-0.553599,-0.060007,-0.157380,0.823339,-0.155940,-0.349956,0.057732,0.242786,0.111100,0.072440,-0.059181,0.078502,-0.181238,0.180820,-0.007023,-0.506346,0.201726,0.081517,0.360498,-0.276772,0.182819,0.009679,-0.096127,0.253339,-0.268840,0.141967,0.188019,0.459591,0.160782,-0.187467,0.279659,-0.450615,0.524047,0.772290,0.182458,-0.442712,0.368270,-0.011658,-0.325765,0.126683,-0.232503,-0.370447,0.208616,0.374755,-0.131557,0.056448,0.303755,-0.266530,0.163280,-0.041296,0.110052,0.028444,-0.239616,-0.331300,-0.170243,-0.264568,-0.302213,-0.364172,0.096594,0.049452,-0.422115,0.583152,-0.495687,0.344603,0.473989,-0.025111,-0.431565,0.588535,0.143615,0.074346,-0.064861,-0.122093,0.281161,-0.358224,0.014847,-0.104607,0.591603,-0.352490,-0.124903,-0.443585,0.293727', '21619567', '2377539', '25909236', '1467779');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25945408', '所罗门的伪证后篇：审判', '剧情', '圣诞节期间，城东第三中学学生柏木卓也（望月步 饰）意外死亡的事件，让这所学校所有师生都卷入久久无发摆脱的阴影之中。虽然警察调查认定卓也系自杀身亡，但是有匿名者指出死者其实是被同班同学大出俊次（清水寻也 饰）、桥田佑太郎（加藤干夫 饰）、井口充（石川新太 饰）联合杀害。为了弄清真相，班长藤野凉子（藤野凉子 饰）、自称卓也好友的外校生神原和彦（板垣瑞生 饰）、高材生井上康夫（西村成忠 饰）等同龄人组成学生法庭，要对嫌疑人逐一审问。他们顶住了校方的巨大压力，一步一步朝着那个飘雪的死亡之夜迈进……本片根据畅销推理作家宫部美幸的经典名作改编。©豆瓣', '藤野凉子', '成岛出', 6.2, 6522, 'tt3923082', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2232007307.jpg', 3.6, 16.7, 52.4, 21, 6.3, '0.116490,-0.402616,-0.234373,0.278157,0.129645,0.031634,0.263522,0.006458,-0.311682,-0.523084,0.096106,0.332374,-0.219082,0.159658,0.298396,-0.189283,-0.189540,-0.770050,0.036615,-0.386081,-0.227818,-0.529704,0.097023,-0.258197,-0.067406,0.032533,0.676426,0.251950,-0.244246,0.496943,0.315284,0.490374,-0.265469,-0.002791,0.206071,0.050667,0.322725,0.132301,-0.137223,0.141014,-0.241948,-0.499654,-0.039760,0.231952,0.167126,0.425471,0.554314,-0.221754,-0.257184,-0.014250,0.277102,-0.449180,-0.232356,0.190054,0.641882,0.049782,-0.009558,0.376027,-0.058549,0.013702,-0.068017,-0.118182,-0.375532,-0.011756,0.448170,0.066012,-0.186920,0.238899,-0.060636,-0.053625,0.205233,0.117925,-0.099440,0.127424,0.397631,-0.106205,-0.290984,0.147114,0.003733,0.268583,0.405409,-0.065671,0.058208,-0.066504,-0.259898,-0.302202,-0.196572,0.010882,-0.055695,0.261148,0.041044,0.217389,0.085380,0.000385,-0.355358,-0.312517,-0.162796,0.033113,-0.055054,-0.232765,-0.049717,-0.657510,0.021579,-0.165685,-0.192812,0.040491,0.209622,-0.242277,0.625552,-0.261249,0.010157,0.275551,0.217539,-0.251555,0.448257,-0.086352,-0.118915,-0.331956,-0.113858,0.028697,0.344929,0.453351,-0.113287,0.429462,0.024816,-0.377789,-0.264534,-0.098421', '25723905', '25799475', '2369613', '25912924');
