INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25951720', '寻找心中的你', '剧情', '在上世纪90年代，电话和电脑完全未普及的时候，一个男生（黄又南 饰）通过电台寻找他一见钟情的王家欣。而王家欣这个名字很普遍，他找到了其中的一个“王家欣”（吴千语饰），但却不并非他的真命天女。“王家欣”觉得男生大海捞针是很傻很天真的事情，但逐渐被其真诚打动，更发展处一段感情。该片来自导演刘伟恒的原创故事，讲述的是一个20世纪90年代发生在香港的一个男主角寻找一个叫王家欣的女生的故事。2015年，黄又南及吴千语凭借该片获得美国加州独立电影节最佳男女主角奖。', '黄又南', '刘伟恒', 7.4, 12224, 'tt3911074', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2321454566.jpg', 1.1, 5, 33, 43.5, 17.5, '0.408857,0.001427,-0.513402,0.941640,-0.017972,0.007333,0.612773,-0.262341,-0.094811,-0.496057,-0.199093,1.045409,-0.319747,0.334044,-0.137793,0.040048,-0.205806,-0.762014,0.078416,-0.316052,-0.139823,-0.616855,0.017047,-0.065890,-0.232955,-0.061019,0.756159,0.098229,-0.378828,0.227082,0.187378,0.238827,-0.025219,0.337686,-0.271124,0.143365,0.125440,0.257124,0.078898,0.121836,0.144673,-0.379968,-0.156216,0.548331,-0.189835,0.508679,0.583529,-0.303350,-0.137468,0.074088,0.585047,-0.284146,-0.520083,-0.261135,0.523706,-0.178007,0.141743,0.189013,-0.182351,-0.325301,0.029851,-0.285761,-0.783374,0.036837,0.087857,0.260832,-0.273050,0.076403,-0.013422,0.239148,-0.147816,-0.165287,0.420981,0.283532,0.325707,0.286132,-0.117361,0.083176,-0.585704,0.545956,0.874101,0.218549,-0.301020,0.894447,-0.341611,-0.638753,-0.123117,0.041330,-0.974792,0.201308,0.090130,-0.191421,-0.049406,-0.342403,-0.474307,0.190734,-0.205950,0.094151,0.029279,-0.293641,-0.129407,-0.596562,-0.410747,-0.463615,-0.270878,-0.118495,-0.051274,-0.478274,1.085150,-0.805488,-0.333139,0.481584,0.311919,-0.690020,1.000932,-0.059146,-0.129125,-0.411018,-0.144049,0.179945,-0.387361,-0.441513,-0.203686,0.427354,-0.281471,-0.331263,-0.337480,0.553736', '30162520', '27602116', '35262731', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25951736', '爸爸去哪儿2', '喜剧', '由湖南卫视从韩国MBC电视台同类节目移植而来的大型亲子户外真人秀节目《爸爸去哪儿》，在万千观众的支持下热播两季，成为当下并不多见的超话题类综艺节目。借着前两季的风头，《爸爸去哪儿》迈出荧屏，走入影院，在2015年初闪亮登场。此次的外景地走出国门，选在了瓦努阿图以东、汤加以西的南太平洋岛国斐济，村长李锐坐镇，陆毅、黄磊、曹格、杨威则带着贝儿、多多、Joe、Grace、杨阳洋这几个古灵精怪、人小鬼大的孩子相继前来。在这个极具异域风情的国度，孩子们将和他们的父亲通力合作，完成各种各样有趣搞怪的任务，而他们也和银幕前的观众们度过了一个快乐祥和的新年……©豆瓣', '黄磊', '谢涤葵', 4.6, 19161, 'tt4542692', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2225907485.jpg', 29.3, 27.6, 30.1, 8.7, 4.3, '-0.019850,0.017772,-0.738472,0.594409,-0.013863,0.134503,0.580344,0.188583,-0.104308,0.092483,0.101527,0.847259,-0.371407,0.367301,0.283918,0.026801,-0.290479,-0.398981,-0.365846,-0.058735,-0.133333,0.060914,-0.153315,-0.013299,0.059179,0.148796,0.611068,0.076867,-0.044350,0.670196,0.506817,-0.066063,-0.291807,0.493106,-0.227576,0.208824,0.110962,-0.037702,-0.218089,0.327785,-0.054940,-0.162821,-0.446753,-0.079710,0.285074,-0.022361,0.812028,-0.112017,0.100990,0.039476,0.395632,-0.261062,-0.056367,0.072683,0.230047,0.079335,0.238364,0.122116,-0.079509,0.265915,-0.201831,-0.367076,-0.590181,0.232842,0.054303,0.081771,-0.458016,0.512291,0.111135,-0.325192,0.212463,-0.417567,0.359552,0.453595,-0.038203,0.475032,-0.143837,0.220472,-0.299444,0.277968,0.559336,0.029629,-0.032761,0.227788,0.035574,-0.411756,-0.029008,-0.103332,-0.380400,0.013807,0.367326,-0.412400,0.013487,0.081382,-0.734920,0.186141,0.205714,-0.504458,0.111507,-0.294867,-0.218637,-1.062419,0.262231,-0.233416,-0.207036,-0.063914,0.190802,-0.066928,0.940309,-0.611022,0.108859,0.504180,0.313791,-0.364515,0.788344,0.049529,0.374886,-0.277976,-0.289958,-0.103376,0.009678,0.583499,-0.106883,0.500100,-0.172198,-0.356395,-0.558932,0.393176', '3811356', '2159244', '5403927', '3318306');
