INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25954475', '聚焦', '剧情', '“聚焦”是波士顿环球报的一个专栏，罗比·罗宾森（迈克尔·基顿饰）是"聚焦"栏目的编辑，栏目拥有一个独立的调查小组，组员包括萨夏·菲弗（瑞秋·麦克亚当斯饰），迈克尔（马克·鲁弗洛饰），马特·卡罗尔（布莱恩·达西·詹姆斯饰）。当马蒂·巴伦（列维·施瑞博尔饰）接替了环球报的总编辑一职，他开始指派罗宾森和他的团队，紧跟一桩被雪藏已久的案件，一个天主教牧师性骚扰教区里的孩子。虽然最开始他们以为这只是个小任务，但很快他们就发现，其背后还隐藏一系列事件，涉及了上百名受害者，而教会已经私下赔偿了受害者，并派人掩盖了这些罪行。随着调查的越发深入，他们发现这一阴谋的更多证据，不仅仅是神职人员，就在波士顿以外，甚至全世界，都在上演着这种暴行。罗宾森和他的团队遭遇到了当地官员们的掣肘。教会内的，教会外的势力都在向他们施压，想让他们放弃这个案件。', '马克·鲁弗洛', '汤姆·麦卡锡', 8.8, 256955, 'tt1895587', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2263822658.jpg', 0.1, 0.5, 8.1, 40.6, 50.7, '0.502886,-0.138202,-0.643837,0.725605,-0.233116,-0.109400,0.698180,0.019345,-0.527685,-0.231370,0.194021,0.866756,-0.214069,0.245471,0.217490,-0.150389,-0.523031,-0.801579,-0.065488,-0.315683,-0.279302,-0.728511,-0.213412,-0.432245,-0.140540,-0.098395,0.455072,0.079360,-0.207949,0.231893,0.518893,0.252190,-0.021615,0.435479,0.138098,0.179684,0.410968,-0.249982,0.072485,0.148627,0.021522,-0.397565,-0.132171,0.284994,0.089412,0.592706,0.408477,-0.295227,0.013676,-0.156096,0.277277,-0.498447,0.152449,0.248129,0.511631,-0.035661,0.071270,0.471247,-0.217695,-0.043968,-0.019296,0.109644,-1.004429,0.040803,0.078685,0.372295,-0.598579,0.313312,-0.174999,0.084308,-0.111510,-0.189648,0.219849,0.435210,-0.000309,0.103368,-0.018154,-0.087137,-0.667375,0.209758,0.433561,-0.094813,-0.256571,-0.030531,-0.199364,-0.535447,-0.170274,-0.053437,-0.228132,-0.158982,0.327758,-0.167688,0.188431,0.307085,-0.600364,0.090075,-0.226988,-0.562629,-0.235962,-0.417894,0.208441,-0.913951,-0.147655,-0.222295,-0.343498,0.122510,0.159724,-0.174849,0.612080,-0.618728,0.061408,0.681048,0.269675,-0.547676,0.630811,0.142658,0.380745,-0.087879,-0.391556,0.084202,0.381789,0.399341,0.159265,0.421781,0.193919,-0.533488,-0.237404,0.382393', '1307442', '1793491', '1299799', '4301278');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25955372', '1980年代的爱情', '爱情', '曾经，关雨波（芦芳生 饰）是学校里唯一一个考上了大学的高材生，他的名字因此响彻校园，成为历史。如今，四年过去，命运让关雨波再次回到了闭塞的小镇之中，成为了一名镇政府的工作人员。本以为能够逃离这个封闭的世界，哪知道转了一圈之后却依旧回到了原点，关雨波感到现实是如此的讽刺。失意的关雨波只能向酒精寻求安慰。某日，他意外遇见了如今在供销社上班的成丽雯（杨采钰 饰）。远在学生时代，关雨波就喜欢上了成丽雯，后因为分隔两地而渐渐淡忘了这段感情。如今旧梦重温，关雨波内心里对于成丽雯的感情蠢蠢欲动，可是成丽雯却对眼前这个颓废的男人态度冷淡。©豆瓣', '芦芳生', '霍建起', 6.6, 7705, 'tt5004918', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2266309313.jpg', 4, 14.8, 42.4, 27.2, 11.7, '0.319608,0.488104,-0.792508,0.559959,-0.058847,-0.375686,0.759241,-0.040819,-0.758857,-0.330560,-0.220722,0.608582,-0.227939,0.565522,0.231644,-0.066183,-0.156362,-0.705083,-0.184514,-0.711208,-0.289375,-0.335723,-0.333893,-0.000402,-0.272164,-0.176215,0.653891,0.555117,-0.240910,0.512875,0.170632,0.211303,0.168232,0.559044,-0.235699,-0.028660,-0.013610,0.267103,-0.089048,0.140822,0.141770,-0.272491,-0.107309,0.161974,-0.037226,0.269424,0.662243,-0.016799,-0.400515,-0.028329,0.539400,-0.249489,-0.405411,0.055553,0.282257,-0.022665,0.136559,-0.110928,-0.307934,-0.017573,-0.107363,-0.056959,-0.432694,0.089336,-0.095488,0.065997,-0.723279,0.494926,0.065290,-0.370673,-0.044483,-0.366771,0.441637,0.232212,0.388215,0.726290,-0.243335,0.338326,-0.291795,-0.057755,0.841878,0.102762,-0.421772,0.431803,-0.283774,-0.355012,-0.035733,-0.068443,-0.331546,-0.081850,-0.025261,0.228104,-0.082829,0.206630,-0.369493,0.091849,-0.130707,-0.126115,0.239448,-0.562830,-0.231824,-0.141582,-0.225279,-0.384355,-0.235888,0.023932,-0.167863,-0.299111,0.616401,-1.029321,0.270824,0.412261,0.372502,-0.535123,0.677519,0.167401,0.187653,-0.243642,0.268053,0.292119,-0.137137,0.577897,0.006411,0.374036,-0.222919,-0.376416,-0.585308,0.725855', '35030151', '1870682', '1301022', '1308755');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25955412', '数码宝贝大冒险tri. 第1章：再会', '动画', '故事發生在被選召的孩子們首次接觸數碼世界的6年後。2005年的一天，東京港區海面上的波浪在朝陽下搖曳……17歲的高中生八神太一，如常地用手按停眼前的鬧鐘，踢開混亂的被鋪，低聲滴咕下伸展四肢。拉開了窗簾，光線照到桌上一幅「那一天」的集體照上。隨後他在「一路順風，哥哥」的送別聲下，騎上腳踏車出門，奔向那片初夏的青空……現在，冒險再度進化……', '花江夏树', '元永庆太郎', 6.9, 8391, 'tt4307880', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2268023247.jpg', 4, 11.1, 38.2, 27.9, 18.9, '0.817117,0.133090,-0.517146,0.533746,-0.184829,-0.278131,0.669302,0.307583,-0.217492,0.372279,0.548696,0.615888,-0.644557,0.324368,0.702638,0.231444,0.225447,-1.022743,-0.357646,-0.046417,-0.601972,-0.086845,-0.241475,0.089865,0.102931,-0.328004,0.757548,0.008094,0.491017,0.659950,-0.029000,-0.304992,0.108355,0.171760,-0.608302,-0.010124,-0.539329,0.172637,0.398394,0.610202,0.008173,-0.827057,-0.045955,-0.164369,-0.586964,0.285013,1.113686,-0.360995,0.233251,0.063848,0.313085,-0.393398,-0.100986,0.167157,0.426182,0.106771,-0.245218,0.266971,-0.196418,-0.342080,0.216384,-0.181828,0.013200,-0.411031,-0.068517,0.205924,-1.051106,0.779131,-0.131136,0.065264,-0.121748,-0.533079,0.239761,0.305823,-0.096088,0.781918,-0.348407,0.127162,-0.224785,0.123944,-0.002190,0.180135,-0.246767,0.507777,-0.205269,-0.166067,-0.413340,0.202089,-0.396018,-0.469376,0.551639,0.161862,-0.565555,0.155426,-0.826875,0.314865,-0.377025,-0.774338,-0.233173,-0.237040,-0.657851,0.023125,0.027310,-0.411143,-0.008613,0.161138,-0.058040,-0.051327,0.464836,-0.375513,0.528369,0.479351,-0.028949,0.697954,0.909310,-0.061301,-0.303814,0.017092,-0.050407,-0.019478,0.084402,0.708768,0.318307,0.799398,-0.427999,-0.039324,-0.584912,0.729504', '3155839', '1307146', '1467779', '1304469');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25955488', '查泰莱夫人的情人', '剧情', '故事发生在第一次世界大战结束之后，战争给克里夫特查泰来爵士（詹姆斯·诺顿 James Norton 饰）带来了永久的创伤，亦给他同妻子康妮（荷丽黛·格兰杰 Holliday Grainger 是）之间的婚姻造成了无法弥补的缺憾。无奈之下，年轻的康妮只能终日生活在压抑之下。一次偶然中，康妮邂逅了名为帕尔金（理查德·麦登 Richard Madden 饰）的男子，后者是查泰来爵士雇佣的园丁。康妮无法自持的被体格壮硕充满了男子气概的帕尔金吸引着，两人天雷勾地火，很快走到了一起，在帕尔金强壮蛮横的肉体之中，康妮重新找回了身为女人的意义和快乐。然而，好景不长，就在康妮怀上了帕尔金的孩子之后，帕尔金的妻子现身揭露了他们两人的奸情。©豆瓣', '荷丽黛·格兰杰', '杰德·默丘里奥', 6.2, 6342, 'tt4116030', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2266214389.jpg', 2.7, 15.8, 55.9, 20.7, 4.9, '0.322999,0.105712,-0.635832,0.425638,-0.316286,-0.363898,0.935916,0.242947,-0.556201,-0.033872,0.214798,0.730569,-0.243496,0.272988,0.402960,-0.022801,-0.214083,-0.780647,-0.044467,-0.103658,-0.242324,-0.532888,-0.167317,-0.083971,-0.134262,-0.678722,0.578736,-0.101416,-0.103269,0.399597,0.309242,0.324982,0.034436,0.481860,-0.209250,0.277858,0.131548,-0.131800,-0.367938,0.301495,0.349555,-0.276546,0.064632,0.351781,-0.170988,0.253635,0.675341,-0.416417,-0.069139,-0.102406,0.408281,0.013547,-0.052833,0.201756,0.150761,-0.097963,0.112579,0.356352,-0.245419,-0.101757,0.306279,0.099552,-0.435031,0.141738,0.064623,0.260057,-0.694140,0.868222,0.090782,-0.170717,0.089133,-0.173212,0.127755,0.291028,0.304777,0.344816,-0.123918,0.039640,-0.386628,0.154730,0.696306,0.125801,-0.432136,0.335121,-0.499002,-0.295260,-0.070882,-0.416898,-0.519163,-0.058964,0.515244,0.299658,-0.171090,0.431022,-0.546328,-0.140158,-0.426865,0.015759,-0.206594,-0.353291,-0.222568,-0.537820,-0.314224,-0.529187,-0.381310,0.050579,0.009124,-0.296826,0.589049,-0.809045,0.250916,0.488866,0.311748,-0.006275,0.482403,0.058468,0.344776,-0.126293,0.086555,0.216379,-0.190652,0.176836,0.428206,0.435137,-0.218785,0.038729,-0.394370,0.570808', '3111650', '26245360', '1308755', '21442760');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25955491', '罪恶之家', '剧情', '亚瑟（肯·斯托特 Ken Stott 饰）是一位成功的资本家，在不久之后即将加官进爵。希拉（克洛伊·皮里 Chloe Pirrie 饰）是亚瑟的女儿，这位单纯善良的千金小姐在家宴中接受了男友杰拉德（凯尔·索列尔 Kyle Soller 饰）的求婚，两人喜结连理，亚瑟和妻子对这门亲事显然十分满意，而希拉的弟弟艾瑞克（芬恩·科尔 Finn Cole 饰）却显然并不怎么高兴。就在一家人欢聚一堂之时，一位不速之客的到来让五人倍感警惕。来人自称警局的探长（大卫·休里斯 David Thewlis 饰），前来为一起女工自杀的案件调查取证，而这位名为伊娃（苏菲·兰道尔 Sophie Rundle 饰）的可怜姑娘曾经在亚瑟手下的工厂里干过活，并且因为领导罢工而被亚瑟开除。亚瑟并不认为自己应该为伊娃的死负什么责任，而随着时间的推移，众人渐渐发现，在这间狭小的房间里，无论是有意或无心，每一个人都是罪人。', '大卫·休里斯', '艾斯林·沃什', 8.3, 119101, 'tt4271918', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2266257360.jpg', 0.6, 1.8, 15.4, 47, 35.3, '0.244787,-0.046934,-0.675530,0.362095,-0.333745,-0.394885,0.819245,0.199667,-0.740017,-0.399340,0.274899,0.770627,-0.129576,0.134423,0.484627,0.207917,-0.236013,-0.482803,0.009861,-0.292332,-0.290160,-0.619053,-0.019510,-0.364886,-0.080455,-0.294617,0.399157,-0.081443,0.258187,0.502116,0.442896,0.410262,0.048466,0.486790,0.065478,0.037340,0.214604,-0.101683,-0.166399,0.107898,-0.098264,-0.057519,-0.283398,0.208375,0.052682,0.341376,0.446838,-0.359200,-0.022348,-0.206613,0.194815,-0.300961,0.157887,0.231784,0.318375,-0.231754,0.355354,0.242618,-0.188931,-0.027796,0.137078,-0.106226,-0.608128,0.231882,0.109976,0.126163,-0.599989,0.458196,-0.144813,-0.099306,0.080770,-0.224156,0.076761,0.314237,0.129117,0.298803,-0.228668,0.017599,-0.341375,-0.084251,0.450837,0.174484,-0.030214,0.313917,-0.244308,-0.229428,0.098724,-0.015943,-0.717055,-0.036115,0.182479,0.084329,0.047108,0.252599,-0.322348,-0.257234,-0.386283,-0.084511,-0.016894,-0.431099,-0.027429,-0.580952,0.023821,-0.308653,-0.220128,-0.092134,0.038323,-0.145716,0.573987,-0.917422,0.306992,0.303549,0.175361,-0.465145,0.522735,0.234261,0.279925,-0.240398,-0.370935,0.012412,0.198017,0.047948,0.151610,0.296340,0.041767,-0.286998,-0.260194,0.412726', '1