INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25955779', '忍者神龟2：破影而出', '喜剧', '城市在恢复平静后，大反派重新召集旧部卷土重来，并勾结外星恶势力朗格试图称霸地球，忍者神龟莱昂纳多（皮特·普劳泽克 Pete Ploszek 饰）、拉斐尔（阿兰·里奇森 Alan Ritchson 饰）、多纳泰罗（杰瑞米·霍华德 Jeremy Howard 饰）和米开朗基罗（诺尔·费舍 Noel Fisher 饰）与女记者艾蓓丽尔·奥尼尔（梅根·福克斯 Megan Fox 饰）、韦恩·芬威克（威尔·阿奈特 Will Arnett 饰），及面具义警凯西·琼斯（斯蒂芬·阿梅尔 Stephen Amell 饰）并肩作战打击恶徒。在史莱德（布莱恩·泰 Brian Tee 饰）逃脱拘留后，他与疯狂的科学家巴克斯特斯·托克曼（泰勒·派瑞 Tyler Perry 饰）及其两个笨拙的左膀右臂猪面和牛头联合，发布了一个控制世界的恶魔计划。在神龟们与史莱德及其同伙对抗的同时，他们发现自己正面临着一个更邪恶的力量大反派格朗，神龟们面对的将是宇宙级的强大对手。', '梅根·福克斯', '戴夫·格林', 6.5, 82497, 'tt3949660', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2357111716.jpg', 1.9, 11.5, 52.7, 25.8, 8.1, '0.008739,0.012399,-0.554024,0.449906,0.070707,-0.228183,0.797149,0.324828,-0.182662,-0.354026,0.092248,0.704895,-0.255216,0.018503,0.303422,-0.104655,-0.499818,-0.610225,0.067566,-0.023727,-0.074404,-0.563659,-0.560884,-0.440047,0.029169,-0.632256,0.443375,-0.136252,-0.144538,0.280541,0.407674,0.644388,-0.026384,0.131292,0.033547,0.053397,0.528791,-0.472908,-0.217622,0.099643,-0.124233,0.304324,-0.104905,0.223642,0.059460,0.091841,0.488956,-0.754092,0.443582,-0.358583,-0.117025,-0.222616,0.112628,0.061103,0.424836,-0.398483,-0.204420,0.222079,0.141636,-0.034577,0.413541,-0.111905,-0.798476,0.242977,-0.034055,0.376832,-0.513275,0.222797,-0.314704,0.064887,0.057313,-0.035475,-0.101196,0.435021,0.203193,0.061524,0.199706,-0.009076,-0.391559,-0.062143,0.098782,0.060336,-0.336294,-0.119923,-0.240747,-0.375960,-0.308669,-0.131643,-0.485022,-0.303576,0.708921,-0.294237,0.205098,0.674306,-0.700107,-0.320747,-0.661973,-0.028348,-0.190134,-0.175181,0.092570,-1.011433,-0.058560,-0.254915,-0.144622,0.047167,0.070059,-0.064089,0.641912,-0.600998,0.144700,0.375933,0.388513,-0.129247,0.201958,-0.087722,0.332068,-0.230669,-0.232613,0.423025,0.454371,0.024044,0.454503,0.385484,-0.067860,0.053210,-0.056629,0.583681', '6517421', '4014396', '6040982', '1316693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25956520', '太平轮(下)·彼岸', '剧情', '20世纪40年代，内战快结束之际，台湾医生严泽坤（金城武 饰）频繁往返于台湾通往大陆的邮轮“太平轮”上，以便购买药品。为了维持家庭生计，表面上他风平浪静，内心却一直没有停止思念因战争被迫分离的恋人雅子（长泽雅美 饰），而他的弟弟严泽明（杨佑宁 饰）则一心想去大陆搞革命，苦难家庭风雨飘摇。严泽坤偶遇有过一面之缘的将军雷义方（黄晓明 饰）夫人（宋慧乔 饰），雷将军的通信兵佟大庆（佟大为 饰）念念不忘底层女性于真（章子怡 饰），还有士官（王千源 饰）、夫人（俞飞鸿 饰），众人相逢在最后一班去台湾的“太平轮”上，书写了战乱年代的悲欢离合，命运的齿轮开启，大时代下的小人物该何去何从？©豆瓣', '章子怡', '吴宇森', 6.6, 64332, 'tt4027270', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2258079139.jpg', 2.8, 11.8, 47.7, 28, 9.6, '-0.209861,0.214912,-0.432604,0.201949,0.323956,-0.166226,0.393089,0.092520,-0.330966,-0.278765,0.227129,0.437039,-0.169542,0.011359,0.272582,-0.095429,-0.266721,-0.460690,0.054468,0.038337,-0.277412,-0.176727,-0.248149,-0.205436,-0.268004,-0.056318,0.558946,0.246528,-0.058071,0.362843,0.221074,0.132748,-0.292763,0.219278,-0.070428,0.046990,-0.112031,0.249538,-0.686811,-0.177187,-0.154331,-0.315333,-0.143017,-0.111892,0.205523,0.120758,0.646966,-0.290736,0.328789,-0.284996,0.429957,0.186845,-0.205769,-0.134114,0.332325,0.172642,0.092300,0.243418,-0.036247,-0.227179,0.312504,-0.098635,-0.243308,0.083293,0.156288,0.186267,-0.241410,0.608913,-0.193181,0.060843,-0.193895,-0.276056,0.306253,0.531495,0.451703,0.189081,-0.132730,-0.087738,-0.143978,0.523475,0.573225,0.177304,-0.175846,0.111804,-0.272256,-0.347715,-0.086605,-0.346832,-0.582021,-0.154362,-0.030325,-0.164744,-0.063220,0.386167,-0.431393,0.197383,-0.257036,-0.008052,0.283149,-0.069133,-0.095689,-0.537887,-0.027833,-0.691845,-0.246741,0.142507,0.209558,-0.026574,0.730501,-0.645869,0.001071,0.309722,0.421703,-0.367661,0.617530,0.316349,0.112735,-0.246935,-0.072795,0.424803,-0.487381,0.357339,-0.002640,0.015888,-0.291533,-0.014560,-0.001835,0.236958', '3078390', '3811356', '26354526', '3445516');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25958704', '超新约全书', '喜剧', '全能的神确实存在，并且居于布鲁塞尔寻常住宅？还用电脑掌管一切生命？《小英雄杜杜》鬼才导演继《小国民尼谟》后又一奇幻狂放之作，这次斗胆玩转宗教。原来神不只有独生子道成肉身，还有个反叛的十岁女儿，对人间种种不幸看不过眼，决定离家出走改造世界，推翻暴君父亲。先发短讯泄露天机公布大限，再化身小救主，下凡召集六大使徒，聆听各人心曲，开启《超新约全书》。暴怒的神也追到凡间，力阻女儿造反。天马行空出奇制胜，更有凯瑟琳·德纳芙演富婆使徒，与黑猩猩擦出爱火花。', '伯努瓦·波尔沃德', '雅克·范·多梅尔', 7.8, 65770, 'tt3792960', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2240337400.jpg', 0.7, 2.8, 24.3, 48.2, 24, '-0.221888,0.358624,-0.229375,0.277878,-0.066967,-0.121191,0.191198,-0.011839,-0.201255,-0.323811,0.198814,0.719733,-0.248138,-0.089342,0.282062,-0.215263,-0.398008,-0.469906,0.139258,-0.061385,0.021069,-0.123793,-0.106851,-0.018340,-0.153939,-0.374336,0.448238,-0.156414,-0.221849,-0.210715,0.069338,-0.041965,-0.189694,-0.105074,-0.260392,0.049006,-0.268533,0.330819,-0.019292,0.004060,-0.256500,-0.003829,-0.012208,-0.007252,-0.145041,0.027819,0.274751,-0.701420,0.035866,-0.527758,0.426670,-0.401282,-0.349824,-0.027712,0.247395,-0.047153,0.139110,0.033621,0.137897,-0.198895,0.067527,-0.188134,-0.899445,-0.318178,0.068398,-0.174626,0.052714,-0.331788,-0.078415,-0.048206,0.117274,-0.124663,-0.038287,0.189358,0.236526,0.425007,-0.094688,-0.110696,-0.039014,0.326665,0.238651,0.102856,-0.337168,0.020697,0.085917,-0.408917,0.135366,-0.508386,-0.262014,0.067753,0.067751,0.000794,0.277972,0.431387,-0.423181,-0.397191,-0.355213,0.101295,0.022123,-0.261064,0.026954,-0.303557,-0.169840,0.140845,0.115335,0.007808,0.890280,0.036222,0.642730,-0.618598,0.276867,0.045566,0.322347,-0.396047,0.520768,0.009605,-0.278712,-0.677447,0.137969,0.250232,0.030500,0.360282,-0.149557,-0.159442,-0.074781,-0.008803,-0.267663,0.105324', '27602116', '27098364', '24284209', '30465281');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25958713', '记住', '剧情', '一家疗养院里，年逾古稀的犹太人古特曼先生（克里斯托弗·普卢默 Christopher Plummer 饰）呻吟着从睡梦中醒来。他的记忆正在消退，连妻子不久前去世的事也险些忘记。不过妻子的离开似乎也帮他卸去最后一点儿牵挂，他在朋友的帮助下，从养老院偷偷跑出。古特曼的身上携带着朋友写的信，上面记载着他沿途需要注意的事项以及此行最大的目的。几经辗转，他终于找到了名叫鲁迪·克兰德的老人。对方年轻时曾是参与过二战的德国士兵，家族的血海深仇驱使着古特曼先生不远万里追踪仇人。奥斯维辛集中营的恐怖记忆，让每个切身经历者都背上了毕生无法摆脱的罪……©豆瓣', '克里斯托弗·普卢默', '阿托姆·伊戈扬', 8.2, 16863, 'tt3704050', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2299734368.jpg', 0.2, 1, 16.7, 54.4, 27.6, '0.219983,0.038465,-0.576430,0.605911,0.123930,-0.456998,0.525234,-0.287453,-0.835402,-0.602882,0.099898,0.629647,0.090027,0.386915,0.232735,0.258027,-0.217170,-0.590561,-0.243584,-0.086828,-0.579473,-0.527052,-0.324591,-0.089855,-0.118920,-0.388798,0.302097,0.207804,-0.216336,0.473238,0.176103,0.253317,-0.169344,0.331872,-0.156429,0.093745,-0.096597,-0.042836,-0.260208,0.084172,0.212034,-0.173110,-0.285184,0.048364,0.039762,0.350591,0.419131,-0.184410,-0.059917,0.085231,0.214197,0.006503,0.270952,0.191432,0.134902,0.217219,0.312769,0.505688,-0.075859,-0.115624,-0.018649,0.135045,-0.684954,-0.255289,0.137181,0.080199,-0.826535,0.246207,-0.349159,0.179830,0.041497,-0.409664,0.397766,0.354218,-0.231044,0.327050,-0.255883,-0.095876,-0.602715,0.277528,0.501540,-0.299826,0.012401,-0.030738,-0.239838,-0.318335,-0.195809,-0.287830,-0.361922,0.125142,0.158669,0.261268,-0.378117,0.327306,-0.391372,-0.017935,-0.243373,-0.227214,0.024788,-0.055174,-0.166783,-0.478742,-0.304124,-0.103750,-0.272531,0.167978,-0.107280,-0.305074,0.676141,-0.566832,0.398535,0.749352,0.268374,0.041188,0.693585,-0.064373,0.023911,-0.167330,-0.299016,0.527498,0.225590,0.343474,0.247594,0.061632,-0.099053,-0.197346,-0.316203,0.359851', '6030611', '1793491', '1783461', '1303693');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25958717', '海蒂和爷爷', '剧情', '孤儿海蒂（阿努克·斯特芬 饰）被姨母迪蒂（安娜·希恩斯 饰）送上了阿尔卑斯山，与远离小镇独居于高山的祖父（布鲁诺·甘茨 饰）一同生活。活泼的海蒂在这里如鱼得水，不仅收获了羊倌彼得（奎林·阿格里皮 饰）的友情和孤僻祖父的亲情，还与山下彼得的家人打成一片。一天，海蒂同彼得在山上放羊，姨母突然出现，连哄带骗将海蒂卖到法兰克福的泽塞曼家。从此，目不识A的海蒂成为了小姐克拉拉（伊莎贝尔·奥特曼 饰）的伴读。克拉拉幼年丧母，大病一场再不能站立，只能被困在豪宅中与轮椅相伴。父亲（马克西姆·梅米特 饰）常年在外很少回家，寂寞的克拉拉把海蒂当成了救命稻草。海蒂能适应泽塞曼家的新生活吗？远在天边的祖父和彼得还能再见吗？克拉拉的腿还有好起来的希望吗？©豆瓣', '阿努克·斯特芬', '阿兰·葛斯彭纳', 9.3, 524559, 'tt3700392', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2554525534.jpg', 0.1, 0.3, 4.4, 26.1, 69.1, '0.292264,-0.023541,-0.628603,0.483140,0.094602,-0.765576,0.472241,0.267713,-0.255023,-0.223208,0.013638,0.832174,-0.090340,0.347129,0.298684,0.295436,-0.380619,-0.627387,0.020856,-0.066848,-0.259633,-0.506994,-0.034492,-0.099198,-0.109761,-0.522840,0.275660,-0.190771,0.177384,0.623395,0.054394,0.283156,-0.166365,0.078229,-0.493171,0.197046,0.071852,0.101662,-0.490749,-0.043463,0.105377,0.231276,-0.001279,0.087336,0.467131,-0.003692,0.692363,-0.327215,0.061580,-0.097895,-0.084378,0.075230,0.311479,-0.017856,0.241004,-0.348123,0.175373,0.284586,-0.101005,0.054256,0.179819,-0.110445,-0.207654,0.204603,0.057134,0.194055,-0.580758,0.514594,-0.039208,-0.392156,-0.044070,-0.282396,0.295401,0.418499,-0.227129,0.470320,-0.301612,0.123630,-0.570636,0.055793,0.545414,-0.039254,-0.174097,0.337646,-0.216127,-0.114359,0.220619,-0.101078,-0.683711,-0.032127,0.308433,-0.309464,-0.267262,0.431297,-0.679732,-0.141656,-0.505579,0.098463,0.075726,-0.398688,-0.044536,-0.487161,0.142021,-0.433809,-0.183253,0.008794,0.078751,-0.221384,0.464597,-0.579019,0.676006,0.311009,0.355588,-0.037689,0.522331,-0.028500,0.392212,0.005919,-0.033087,0.363591,0.013744,0.097801,0.279291,0.240353,-0.024912,-0.019867,-0.429497,0.520872', '1297239', '1292720', '1895119', '6128003');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25958726', '开战日', '剧情', '1940年4月9日清晨，德国军队穿过国界进入丹麦境内。丹麦日德兰岛的自行车连队和摩托车连队是最先抵御德军进攻的丹麦部队……', '皮鲁·埃斯贝克', '罗尼·伊兹拉', 7.6, 6689, 'tt3542188', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2263287670.jpg', 0.6, 2.6, 31.5, 48.8, 16.5, '-0.155618,0.068505,-0.831900,0.694848,0.698236,0.236658,-0.377595,-0.536358,-0.809939,0.371336,0.023675,0.538156,0.410491,-0.294508,0.721856,-0.022024,-0.472071,-0.657944,-0.192246,-0.372116,-0.832971,0.007360,-0.066516,-0.430792,0.400668,-0.637985,0.980637,0.555346,0.060626,0.593445,-0.243287,0.307241,0.152596,0.425894,0.045354,-0.132710,0.250850,-0.465083,-0.394784,0.539028,-1.126415,0.008919,-0.334465,-0.357683,0.435799,0.288027,1.058458,-0.126185,0.540970,-0.703941,-0.177139,-0.043916,-0.136185,-0.388862,0.935584,0.219853,-0.074361,0.499072,0.349291,-0.283062,-0.755051,-0.427858,0.614483,0.224847,-0.274724,-0.662866,-0.411844,0.119923,-0.602307,0.547180,0.266020,-0.280714,0.209005,1.218779,-0.219730,0.541627,-0.115100,0.134217,-1.003230,0.139600,0.763412,-0.484736,-0.651789,-0.694821,0.329965,-0.349971,0.177343,-0.640954,0.142435,0.112295,-0.043534,-0.334499,0.048032,0.039550,-0.813114,0.680415,-0.461779,-0.953389,0.345432,-0.017437,0.023159,-1.219770,0.659238,-0.311774,0.140213,0.816767,0.108647,1.160695,0.522752,-0.404637,0.299995,0.802814,0.928414,0.007934,0.919049,-0.084821,0.018443,-0.328841,0.442858,0.831653,-0.456799,0.233315,-0.167932,0.592333,-0.350263,-0.052653,0.139257,-0.045346', '1422938', '3871833', '1291824', '3742937');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25958787', '深夜食堂电影版', '剧情', '夜幕笼罩下的东京霓虹闪烁，在城市某个不起眼的角落，充满温情的深夜食堂悄然开张。妖媚的川岛玉子（高冈早纪 饰）一脸颓唐，她的靠山不久前去世，却没给她留下分文遗产。在颓唐无助的时候，貌不惊人的上班族小初（柄本时生 饰）走入玉子的视野，他们的关系迅速拉近。乡下女孩栗山美知留（多部未华子 饰）独自来到东京，走投无路之际她在老板（小林薰 饰）这里吃了霸王餐，事后主动登门要求打工还钱，女孩因此找到了暂时的栖身地。3•11大地震让福岛灾民大石谦三（筒井道隆 饰）和来自东京的志愿者杉田明美（菊池亚希子 饰）相识。大石对后者展开狂热的追求，甚至尾随来至东京。平凡人的小故事，在深夜食堂内交替上演……©豆瓣', '小林薰', '松冈锭司', 7.9, 98524, 'tt3958276', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2205014862.jpg', 0.2, 1.7, 24.4, 49.5, 24.1, '0.111788,0.220863,-0.741807,0.176997,-0.136545,-0.219343,0.599569,0.571352,-0.263798,-0.289115,0.547393,0.567791,-0.200699,0.247128,0.192852,0.039005,-0.352249,-0.590181,-0.007186,-0.231608,-0.038071,-0.238395,-0.103761,-0.145305,-0.259572,0.033371,0.462852,0.264928,0.039475,0.585694,0.116810,0.259028,-0.264890,0.402871,-0.151070,0.029562,-0.015331,0.184655,-0.134943,0.365006,-0.359473,-0.383844,-0.302648,-0.021875,0.206035,0.501847,0.836737,0.178637,-0.189111,-0.046290,0.142162,0.023531,-0.221932,0.122724,0.271085,-0.137607,0.118609,-0.177004,-0.433242,-0.075358,0.164853,0.027520,-0.022806,0.128412,0.142835,0.182170,-0.372384,0.563894,-0.000250,-0.214663,0.352351,-0.495764,0.137061,0.053806,0.028743,0.277486,-0.118775,0.311728,-0.324550,0.228225,0.306272,0.103416,0.161133,0.224559,-0.376566,-0.241315,0.029855,-0.003936,-0.225322,-0.207081,0.227865,-0.033300,-0.159634,0.085954,-0.653176,-0.208889,-0.029175,0.021417,0.140333,-0.082078,-0.403394,-0.810928,0.258739,-0.277400,-0.227292,0.374621,0.094730,0.105633,0.551167,-0.515306,0.323056,0.568286,0.435834,0.039363,0.589187,-0.131206,-0.149270,0.083549,-0.184862,0.127851,-0.012355,0.527100,0.201519,0.162718,-0.504656,0.079401,-0.548143,0.388328', '2159244', '10466639', '1309194', '2269893');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25960953', '没有秘密', '剧情', '钟灿（金柱赫 饰）和妻子妍红（孙艺珍 饰）结婚多年，膝下有一可爱的女儿，两人男才女貌，在外人眼中是如同神仙眷侣一般的存在。钟灿涉足政坛，事业小有成就，同僚们都知道，他将有极大的可能成为下一任的国会议员。某一日，厄运降临到了这个幸福的家庭之中，女儿无故失踪下落不明，留下难以解释的模糊线索，令警方毫无头绪。让妍红感到不可思议的是，对于女儿的失踪，钟灿似乎并没有那么焦急，他脑中所想的，只有如何在下一场竞选中取得胜利，夫妻两人之间的感情因此而产生裂痕。无奈之下，妍红只得强打起精神，她知道，女儿所能依靠的只有自己。©豆瓣', '孙艺珍', '李京美', 6.8, 7586, 'tt5768474', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2363317124.jpg', 1.6, 10.1, 48.1, 28.6, 11.6, '0.089458,0.060600,-0.836351,0.626031,0.085621,0.018215,0.693253,-0.156354,-0.735810,-0.213033,0.057554,0.812467,-0.280017,0.400623,-0.131804,-0.088041,-0.082013,-0.881555,-0.050681,-0.487916,-0.168239,-0.650556,-0.183379,0.017223,-0.244565,-0.204204,0.625324,0.262078,0.008730,0.419774,0.556775,0.297314,-0.245738,0.373431,-0.111313,0.184984,-0.126508,0.321205,-0.372389,-0.056263,0.327858,0.056844,-0.217180,0.386892,-0.127722,0.502314,0.345999,-0.406286,-0.443470,-0.121483,0.358764,-0.312088,-0.154771,0.255025,0.293814,-0.023628,0.219313,0.056143,-0.152712,-0.005493,0.176149,0.208235,-0.963686,0.237753,0.276725,0.276483,-0.521569,0.184024,0.040906,-0.253864,-0.022640,-0.235045,0.368976,0.498606,0.269482,0.360584,-0.420018,0.287146,-0.462024,0.127990,0.790988,0.225876,-0.501140,0.411893,-0.439686,-0.178046,-0.111801,-0.439000,-0.504350,0.025338,0.201988,0.457445,-0.060905,0.306717,-0.149735,0.141412,-0.254033,-0.067055,-0.151381,-0.473232,-0.057569,0.081024,-0.222822,-0.531921,-0.542432,0.182787,-0.024181,-0.647660,0.671977,-0.995260,0.123506,0.093609,0.594965,-0.619479,0.634241,0.319592,0.161034,-0.246952,-0.177936,0.229372,-0.249738,-0.102219,0.138506,-0.059415,-0.161698,0.050670,-0.336965,0.190223', '1301022', '1783461', '35030151', '27056396');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25962735', '既然青春留不住', '喜剧', '洋溢着青春气息的大学校园里，劲辉（张翰 饰）、冯松（王啸坤 饰）等人立下了“兄弟盟约”，希望以此来维持他们之间的友谊。然而事与愿违，冯松喜欢上了名为朱婷（施雨斐 饰）的漂亮女孩，然而，令他没有想到的是，朱婷的芳心早就有了归属，那就是样貌英俊有着校草美誉的劲辉，然而落花有 意流水无情，劲辉的眼中只有身材性感火爆的周蕙（陈乔恩 饰）。一段曲折离奇的多角恋就此拉开序幕。一晃眼十年过去，曾经的兄弟好友们踏入社会，各奔东西，某日，朱婷组织了一场盛大的同学聚会，让旧友们重新走到了一起。当众人回忆起曾经的青葱岁月之时，又会有怎样的释怀和感悟呢？©豆瓣', '张翰', '田蒙', 4.7, 22370, 'tt5033038', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2274949132.jpg', 23.8, 33.2, 30.4, 7.9, 4.7, '0.364152,0.091384,-0.609793,0.435791,0.012675,-0.394964,0.613905,0.063213,-0.577112,-0.008679,0.057102,0.400037,-0.422714,0.479847,0.303753,-0.227628,-0.067755,-0.817505,-0.187432,-0.345550,-0.056590,-0.076171,-0.184174,0.368683,-0.205223,-0.248807,0.793846,0.146730,0.172733,0.879108,0.377564,0.078282,-0.100328,0.260113,-0.161866,-0.019466,-0.073322,0.347411,-0.475179,0.075368,0.109448,-0.329611,-0.218685,0.136296,-0.196235,0.317000,0.496336,-0.050815,-0.032126,0.069582,0.468656,0.042890,-0.020598,0.162764,0.026582,0.111501,0.294528,0.261845,-0.194707,-0.170331,0.144132,-0.254631,-0.467506,0.139359,0.187342,0.150320,-0.391299,0.593273,-0.014777,-0.343475,0.308013,-0.307440,0.262831,0.212871,0.583599,0.229200,0.058398,0.150854,-0.300160,0.283040,0.828156,0.105437,-0.261250,0.297868,-0.206555,-0.378393,-0.106598,-0.227611,-0.372504,0.310573,0.150222,0.262080,0.072585,0.136358,-0.790451,0.014748,-0.095438,0.112217,0.283070,-0.460014,-0.274713,-0.479142,-0.624156,-0.639032,-0.433311,0.218198,0.199527,-0.310442,0.856697,-1.104548,0.176447,0.294449,0.100151,-0.272095,0.763114,0.193934,-0.080121,0.061141,0.124405,0.076524,-0.124705,0.068414,-0.011101,0.348639,-0.327064,-0.063381,-0.285049,0.320593', '35030151', '1826173', '3139191', '1316589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25964071', '夏洛特烦恼', '喜剧', '在学生时代的初恋秋雅（王智 饰）的婚礼上，毕业后吃软饭靠老婆养的夏洛（沈腾 饰）假充大款，出尽其丑，中间还被老婆马冬梅（马丽 饰）戳穿暴捶。混乱之中，夏洛意外穿越时空，回到了1997年的学生时代的课堂里。他懵懵懂懂，以为是场真实感极强的梦，于是痛揍王老师，强吻秋雅，还尝试跳楼让自己醒来。当受伤的他从病床上苏醒时，他意识到自己真的穿越了时空。既然有机会重新来过，那不如好好折腾一回。他勇敢追求秋雅、奚落优等生袁华（尹正 饰）、拒绝马冬梅的死缠烂打。后来夏洛凭借“创作”朴树、窦唯等人的成名曲而进入娱乐圈。他的人生发生翻天覆地的巨变，但是内心某个地方却越来越感到空虚……©豆瓣', '沈腾', '闫非', 7.8, 903691, 'tt5061814', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2264377763.jpg', 1.8, 4.3, 23.8, 42.4, 27.7, '0.093103,0.200635,-0.660169,0.097585,-0.309012,-0.307767,0.537199,-0.031407,-0.566081,-0.163225,0.164773,0.349611,-0.346889,0.491718,0.376725,0.155201,-0.150386,-0.621725,0.249352,0.145511,-0.299686,-0.161870,-0.333016,0.014855,-0.105471,-0.246279,0.544945,-0.055324,-0.483257,0.256164,0.193023,-0.004032,0.226140,0.519708,-0.114843,0.217168,-0.051948,0.413280,0.023090,0.041980,-0.093944,-0.381616,-0.129422,0.162497,-0.050831,0.131003,0.562885,0.017797,-0.133367,-0.169621,0.634601,-0.142367,-0.459871,0.059873,0.010711,0.118643,0.136227,-0.004189,-0.023320,-0.043456,0.071349,-0.005593,-0.206863,-0.009260,-0.015223,-0.091801,-0.381757,0.443171,0.135905,0.041841,0.119454,-0.128725,0.095807,0.174153,0.277754,0.360639,-0.299883,0.105087,-0.339843,0.160403,0.567504,-0.093273,-0.209757,0.312340,-0.045837,-0.195078,0.096870,-0.139909,-0.375114,0.007825,-0.007027,0.080886,-0.570317,0.031150,-0.139763,-0.045810,-0.157869,0.093165,-0.223070,-0.282790,-0.187986,-0.229245,-0.155634,-0.100406,-0.274585,-0.132147,-0.110015,-0.517228,0.297254,-0.696440,0.340799,0.578399,0.317034,-0.240930,0.519291,0.061628,-0.233530,-0.246666,-0.012911,0.333663,-0.261345,0.171498,-0.040264,0.330120,-0.170679,-0.140011,-0.381469,0.692322', '1870682', '1292719', '34973399', '30450313');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25964630', '黑镜：圣诞特别篇', '剧情', '圣诞节将至，一间地处偏远的小木屋里，波特（拉菲·斯波 Rafe Spall 饰）和马特（乔恩·哈姆 Jon Hamm 饰）同坐一桌，用红酒和烤土豆庆祝这个银装素裹的节日。波特沉默寡言，无精打采，而马特却恰恰相反，为了逗波特讲话，他向波特讲述了自己的过去。曾经的马特是一名“恋爱导师”，他通过摄像头和网络“远程操控”他的客户，让这些平日里无人问津的“宅男”们能够在派对山成功抱得美人归。然而，一场意外让马特决定永远离开这个他经营得风生水起的行当，此间究竟发生了什么？听了马特的叙述，波特终于决定向马特讲述自己的故事，这个故事关乎于他和他的女友，但并不完全关乎于爱情。©豆瓣', '乔恩·哈姆', '卡尔·蒂贝茨', 9.1, 117620, 'tt3973198', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233676442.jpg', 0.1, 0.3, 5.4, 31.7, 62.6, '0.478992,0.033038,-0.621342,0.539764,-0.117689,-0.325349,0.898351,-0.073620,-0.406820,-0.342736,-0.171956,0.833835,-0.271061,0.313289,0.318508,0.161341,-0.221621,-0.579802,0.057335,-0.050712,-0.186417,-0.526855,-0.246232,-0.302764,-0.260903,0.092209,0.333050,-0.057021,-0.238581,0.160864,0.411123,0.272748,0.091001,0.327238,-0.183178,0.038300,-0.136077,0.006078,-0.337422,0.126125,0.022712,-0.120875,-0.291204,0.313794,0.296624,0.375935,0.738761,-0.398182,-0.259459,0.059310,0.244615,-0.330729,0.024023,0.320926,0.092259,-0.035086,0.099049,0.252278,-0.007899,-0.103418,-0.094307,-0.118522,-0.651322,0.062621,-0.135150,0.262600,-0.420824,0.489945,-0.133332,-0.093510,0.145574,-0.384623,0.186174,0.368392,0.235950,0.475192,-0.188477,-0.114510,-0.711331,0.111291,0.491580,0.087399,-0.058292,0.587268,-0.165731,-0.482521,-0.108154,0.023193,-0.656382,-0.060589,0.286639,-0.005507,-0.085599,0.301209,-0.678306,0.056051,-0.090279,-0.434237,0.158149,-0.547544,-0.088367,-0.713846,0.036270,-0.309716,-0.243290,-0.111666,0.120824,-0.393310,0.650611,-0.812169,0.040494,0.411412,0.115243,-0.311018,0.567276,0.267027,0.391050,-0.087912,-0.025343,0.268682,0.169042,0.176309,0.045531,0.642106,0.362802,-0.100805,-0.518961,0.541911', '1394176', '1296534', '2002744', '3055049');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25965924', '唐顿庄园：2014圣诞特别篇', '剧情', '2014年圣诞我们依然有长达两个小时的《唐顿庄园》特别篇作伴。鉴于2012年以悲剧结尾的圣诞特辑播出之后，大批愤怒的观众向ITV投诉说这个结局毁了他们的圣诞节，这几年我们应该不会看到编剧朱利安·费罗斯在圣诞又一次大开杀戒了。今年的特别篇会给剧迷塑造出前所未有节日气氛，剧情也将难得聚焦在克劳利一家的圣诞经历上。其实圣诞剧集是可以完全不必植入圣诞元素的，这也是一直以来英剧中存在的不成文习惯。', '休·博纳维尔', 'Minkie Spiro', 9.1, 15771, 'tt3962976', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2221108128.jpg', 0.1, 0.2, 5.8, 31.4, 62.5, '0.125979,-0.110163,-0.443271,0.223939,0.356168,-0.209459,0.468529,-0.193884,-0.461992,-0.404639,0.067071,0.733393,-0.858845,0.135324,0.550143,-0.126182,-0.360808,-0.623696,-0.175380,-0.377128,-0.139966,-0.229132,0.007139,-0.101963,0.068703,-0.435930,0.400484,0.235274,0.160754,0.395387,0.549182,0.130542,0.328138,0.245879,-0.031671,-0.106847,-0.066266,-0.071417,-0.255814,0.297218,-0.111674,-0.500724,-0.188292,0.064887,0.364484,0.298334,0.678255,-0.109303,-0.303209,0.214050,0.681483,-0.321672,-0.437410,-0.006515,0.426486,-0.133486,0.355294,0.430822,-0.220649,0.015659,-0.296061,-0.369602,-0.713378,0.253770,-0.183902,0.073348,-0.197921,0.727495,0.269114,-0.058202,-0.119447,-0.181852,0.246080,0.436811,0.435565,0.204311,0.026620,0.094380,-0.322996,0.359553,0.889726,-0.132041,-0.225435,0.306015,-0.222063,-0.415487,-0.333180,-0.396967,-0.452654,0.355591,0.080069,0.096703,-0.299868,0.295262,-0.708536,-0.001602,-0.119556,-0.631430,0.251106,-0.372705,-0.119842,-0.900907,-0.023199,-0.458579,-0.342131,0.178836,0.180965,-0.308627,0.694908,-0.768082,0.341839,0.340315,0.549738,-0.224520,1.013131,0.267367,-0.147472,-0.205545,0.022463,0.044851,-0.246741,0.171280,0.400303,0.298930,0.313537,-0.270516,-0.400623,0.666398', '24751811', '26259202', '26687241', '11541282');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25966085', '踏血寻梅', '剧情', '2009年，十六岁的湖南女孩王佳梅（春夏 饰）追随改嫁的妈妈和姐姐的脚步来到了香港，全新而陌生的环境，她感觉到格格不入，与家人的关系也逐渐紧张起来。志愿成为模特的佳梅以助理身份入行，尝尽了圈内的苦辣酸甜，最终为了赚更多的钱而出卖肉体。直到某天，她认识了拥有悲惨童年经历的肥仔丁子聪（白只 饰），两人的命运同时朝着悲剧的方向转变。繁忙的警署内，肥仔前来自首，负责此案的臧SIR（郭富城 饰）针对相关人士展开调查，在此过程中，佳梅和丁子聪个人的故事交替展开。有如两条悲伤的河流，最终汇成混杂着血污与泪的黄泉之水……本片根据真实案件改编。©豆瓣', '郭富城', '翁子光', 7.5, 186720, 'tt4417522', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2283225569.jpg', 0.7, 3, 30.4, 50.2, 15.8, '0.123656,0.025238,-0.480146,0.476753,0.270189,-0.150503,0.694973,0.213942,-0.401105,-0.228017,-0.015343,0.568985,0.047688,0.125876,0.441809,-0.234078,-0.206943,-0.734503,-0.197298,-0.189833,-0.315988,-0.500452,-0.193639,-0.066172,-0.063219,-0.276934,0.566195,0.354345,-0.100381,0.630262,0.341044,0.125337,-0.428642,0.245306,0.039469,-0.026369,-0.033063,0.192096,-0.494407,0.001016,0.081180,-0.212151,-0.093362,-0.056338,-0.093323,0.327389,0.752276,-0.206698,-0.215901,-0.105961,0.540170,-0.194684,-0.146403,-0.096823,0.170005,0.420551,0.315764,0.276501,-0.212753,0.014697,-0.050803,-0.206837,-0.705398,-0.002664,0.302252,0.356964,-0.347517,0.193007,0.049480,-0.159435,0.178947,-0.475038,-0.038179,0.141428,0.213228,0.475951,-0.263598,0.050716,-0.242654,0.293725,0.814431,0.145555,-0.192735,0.306146,-0.204518,-0.299805,-0.127737,-0.284063,-0.191151,0.053810,0.103858,0.323468,-0.072259,0.444743,-0.659604,-0.071990,-0.015040,-0.222727,-0.026762,-0.229125,-0.186142,-0.308663,-0.374088,-0.472313,-0.129744,-0.012474,0.073935,-0.365078,0.578209,-0.637227,0.111775,0.368994,0.211355,-0.527683,0.645094,-0.058665,0.209101,-0.353868,-0.075999,0.274199,-0.006397,0.318937,0.028443,0.088401,-0.300183,0.003923,-0.473162,0.229376', '26678784', '1294713', '27062637', '25828589');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25969095', '秘术', '悬疑', '设计师魅可（安以轩 饰）不顾合伙人反对，向媒体坦诚自己的孤儿身份，希望以诚示人之外，也一直没有放弃寻找生身父母的愿望。魅可在孤儿院帮助下找到被拆迁的老宅，因此结识在工地打工的忠哥（汪东城 饰），在忠哥引领下，魅可拜访守候着可能是自己家遗物的哑口婆婆，却未得到自己出身的线索，然而怪事很快接连而至：她的父母很可能来自盗墓家族，工队队长可能不怀好意，而那位婆婆又似乎早已死去……谜底渐渐揭开，原来忠哥亦是一名出身盗墓世家的孤儿，他为了寻找自己父母的线索，试图在魅可家的遗物中找到一本《盗墓秘术》，为了达成目的，他不惜运用父母留下的工具和迷药来制造绑架事件，他坚信自己并非恶人，但行动却渐渐失控……©豆瓣', '安以轩', '吴兵', 2.5, 4034, 'tt5370104', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2211086480.jpg', 82.8, 11.8, 3.2, 0.5, 1.8, '0.139197,-0.078265,-0.588771,0.647578,-0.254210,-0.154481,0.513091,-0.121100,-0.547738,-0.696830,0.409958,0.726648,0.479939,0.151232,-0.175222,-0.086778,-0.093481,-0.559731,0.254493,-0.309292,-0.143859,-0.440678,-0.315601,-0.295762,-0.208876,-0.310568,0.577289,0.134752,-0.284210,0.305976,0.353648,0.497797,-0.402217,0.400497,-0.217411,-0.131368,0.056997,0.081047,-0.331802,0.184241,-0.014484,-0.298294,-0.304661,0.393926,-0.078367,0.628676,0.502326,-0.212877,-0.175883,-0.157401,0.177865,-0.345825,0.147613,0.125867,0.417017,-0.026016,0.387343,0.616773,-0.145686,-0.062775,0.210915,0.049555,-0.872634,-0.060979,0.485757,0.256210,-0.619555,0.194797,-0.149007,-0.072677,-0.081457,-0.465812,0.408914,0.409030,0.266583,0.227056,-0.464359,0.124703,-0.587287,0.280070,0.505182,-0.235183,0.050724,0.445457,-0.199472,-0.201045,0.211697,-0.294021,-0.502891,-0.053018,0.173617,0.292029,-0.224436,0.088367,-0.261364,-0.183145,-0.213112,-0.123921,0.157630,-0.446318,0.026724,-0.331608,-0.182946,-0.010720,-0.201476,-0.042417,0.026516,-0.488344,0.690421,-0.795926,0.092032,0.528584,0.229638,-0.888662,0.636580,0.027432,-0.092447,-0.296756,-0.301172,0.196073,0.143540,0.259592,-0.002160,-0.127184,0.078142,-0.142654,-0.233464,0.272785', '3670447', '1877596', '30163500', '26678784');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25969201', '投靠女与出走男', '剧情', '故事发生在19世纪中叶的日本德川幕府时期，位于镰仓的东庆寺得到幕府的支持，可以向饱受苦难婚姻折磨的女性施以援手，帮助他们成功和夫家断绝关系。这一日，不法商人堀切屋三郎卫门（堤真一 饰）的小妾阿吟（满岛光 饰）以及被混蛋丈夫（武田真治 饰）残酷剥削的铁匠阿茹（户田惠梨香 饰）结伴来到东庆寺，并且认识了寺脚下御用宿柏屋主人源兵卫（树木希林 饰）的外甥信次郎（大泉洋 饰）。信次郎是一名见习医生，他利用医术尝试着治疗阿茹的烧伤，同时希望记录下女性们的遭遇写出传世剧本。有着不同背景的女性们相继前来，她们共同站在了人生的岔路口上……本片以井上厦的小说《東慶寺花だより》为参考改编而成。©豆瓣', '大泉洋', '原田真人', 8.2, 15295, 'tt3989744', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2233635683.jpg', 0.4, 1.5, 17.7, 47.1, 33.3, '0.083516,-0.149721,-0.251379,0.457121,0.193024,-0.086439,0.357295,0.125774,-0.285964,-0.424042,0.388684,0.483164,-0.016052,0.164021,0.223895,-0.212385,-0.191069,-0.525647,-0.082715,-0.115519,-0.343023,-0.384966,0.034185,-0.234744,-0.395546,-0.288112,0.772839,0.060661,-0.283734,0.243133,0.255276,0.418714,-0.075783,-0.303544,-0.191146,0.208603,-0.055001,-0.175879,-0.427357,0.231636,-0.240446,-0.090258,-0.170232,-0.142792,-0.000054,0.244751,0.589591,-0.350836,0.041149,-0.194925,0.434950,0.153104,0.092069,0.283795,0.279257,0.257054,0.057548,0.262052,-0.180143,-0.105974,0.219717,-0.190885,-0.569730,-0.079296,0.338866,0.289045,-0.528179,0.199909,-0.046326,-0.148515,0.098339,-0.284891,0.021065,0.347664,0.402294,0.302873,-0.316384,0.227314,-0.253885,0.272751,0.413557,0.021625,0.031590,0.175624,-0.346336,-0.413198,-0.135255,-0.288313,-0.423500,-0.050606,0.181585,-0.062878,-0.005600,0.095082,-0.423549,-0.242691,-0.011307,-0.095842,0.405131,-0.057602,-0.039766,-0.574576,-0.007293,-0.369200,-0.326944,0.226617,0.299708,-0.324880,1.063171,-0.567331,-0.036611,0.450464,0.386262,-0.367412,0.696189,0.110421,-0.216039,-0.004811,-0.224723,0.372300,0.278592,0.293150,0.100188,0.285683,-0.045704,-0.140237,-0.274793,0.109152', '27602116', '3811356', '25863940', '1908036');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25975249', '心灵想要大声呼喊', '动画', '少女成濑顺（水濑祈 配音）有着一段不堪回首的童年往事，曾经，年少无知的她因为口无遮拦，导致了家族的悲剧，而她本人亦被封印了言语，无法再开口说话。这样的顺终日生活在悲伤之中，和所有人都保持着距离，紧紧的关闭上了心门。某一天，浑浑噩噩迷迷糊糊的少年坂上拓実（内山昂辉 配音）、因为受伤而无法完成棒球梦想的田崎大树（细谷佳正 配音）、深陷令人苦恼的恋爱之中的拉拉队员仁藤菜月（雨宫天 配音）以及顺，这四人被老师任命组成了“地域沟通交流会”，他们要在交流会上表演一出音乐剧，可是班级里的大部分学生对此兴趣寥寥。在一片争执声中，顺突然出声，担下了演唱的任务。©豆瓣', '水濑祈', '长井龙雪', 7.6, 16569, 'tt4489416', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2258854364.jpg', 0.9, 4.4, 30, 42.7, 21.9, '0.381313,0.238812,-0.599366,0.507901,0.142772,-0.257012,0.829353,0.019247,-0.568992,-0.162018,0.056888,0.504019,-0.420942,0.371896,0.264932,-0.351541,-0.022866,-0.850067,-0.259236,-0.334051,-0.249419,-0.556517,0.072919,-0.077866,-0.323131,-0.210079,0.846028,0.071346,-0.132830,0.453111,0.166324,0.134865,-0.272872,0.397320,0.030016,-0.012355,-0.041498,0.010622,0.112439,-0.134433,-0.063119,-0.412175,-0.250682,0.168186,-0.136520,0.366110,0.752789,-0.305191,-0.186165,0.181457,0.258723,-0.359368,-0.130325,0.113377,0.218005,0.143619,0.358247,0.310982,-0.075024,-0.013458,-0.019781,-0.130002,-0.330266,0.090584,-0.043199,0.453303,-0.346164,0.741259,0.090013,-0.195093,0.018155,-0.162076,0.185207,0.225237,0.336249,0.403797,-0.383689,0.059589,-0.225599,0.455799,0.585604,-0.168740,-0.314456,0.386010,-0.226040,-0.327661,-0.274128,-0.326913,-0.571032,-0.124140,0.159568,0.362775,-0.051853,0.077502,-0.354092,0.087384,0.115646,-0.238631,-0.278246,-0.295921,-0.053462,-0.461527,-0.181291,-0.071402,-0.283504,0.091721,0.035733,-0.285715,0.567484,-1.071063,-0.002208,0.429793,0.272118,0.103264,0.516004,0.136546,0.110632,0.073544,-0.091089,0.275010,-0.309450,0.215898,0.282614,0.433965,-0.130964,-0.119021,-0.697014,0.345571', '35030151', '1826173', '1417036', '2027925');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25975323', '十月初五的月光', '剧情', '夜总会歌女朱莎娇（薛家燕 饰）爱上了港大学生祝展辉（郭峰 饰），朱莎娇的腹中更是怀上了后者的孩子。然而，祝展辉要前往纽约深造，朱莎娇只得独自生下女儿祝君好（佘诗曼 饰），抚养他长大。之后，善良朱莎娇又收留了好姐妹的儿子文初（张智霖 饰），无奈文初的嗓子被毒药烧坏，无法发声。一晃眼二十二年过去，祝君好和文初都已经长大成人。某日，朱莎娇再度遇见了祝展辉，继而结识了祝展辉的弟子司徒礼信（马浚伟 饰），与此同时，文初遇见了曾经抛弃他的生母，两人尽释前嫌，文初更是帮助母亲还债。随着时间的推移，文初和司徒礼信都爱上了善良美丽的祝君好。©豆瓣', '张智霖', '叶念琛', 5.5, 17421, 'tt5111790', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2267564099.jpg', 9.8, 28.8, 42.3, 13.3, 5.9, '0.012152,-0.044927,-0.349152,0.506312,-0.099065,-0.475079,0.510348,0.352573,-0.533816,-0.064339,-0.011805,0.501597,-0.013108,0.669109,0.339337,0.251325,-0.113506,-0.640899,0.064580,-0.145109,-0.276320,-0.296384,0.012196,-0.042028,0.050672,-0.214788,0.378484,0.011172,0.297260,0.660538,0.330575,-0.075303,0.005831,0.468824,-0.145097,0.492700,-0.187042,0.233562,-0.116481,0.133435,-0.045651,-0.199949,-0.047237,-0.142470,0.182188,0.379311,0.490760,0.088707,0.161778,-0.499652,0.307985,-0.166276,0.015360,0.333158,0.138951,0.064498,0.578252,0.129246,-0.390842,-0.066270,-0.129941,-0.137525,-0.115879,0.132319,0.512019,-0.477428,-0.721374,0.578492,-0.205867,-0.118037,0.085042,-0.409138,0.086762,0.360501,0.133412,0.422635,-0.299543,0.080842,-0.222874,0.293813,0.509369,0.088534,-0.081048,0.269254,0.200074,-0.582679,-0.073342,-0.193370,-0.271185,0.092936,0.433036,0.306030,-0.341616,0.201106,-0.154247,-0.126705,-0.061319,0.166275,0.252587,-0.308069,0.113512,-0.221955,-0.137076,-0.415361,-0.381185,0.058825,-0.115896,-0.326715,0.640117,-0.435913,0.226358,0.140950,0.309174,-0.600859,0.423071,0.062718,0.064165,0.098161,0.130410,0.501128,-0.114127,0.199423,0.189499,0.276503,-0.362663,0.025540,-0.334935,0.188040', '1364764', '1307146', '1304091', '1296044');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25977027', '小姐', '剧情', '公爵（河正宇 饰）为了得到日本贵族秀子小姐（金敏喜 饰）的财产，意欲娶她为妻，而后以其患上精神疾病为由将秀子送入精神病院。为了实现自己的阴谋，公爵将出生于小偷世家的南淑熙（金泰璃 饰）送到秀子的身边担任女佣，如此一来两人里应外合，深闺之中不谙世事的秀子和她的万贯家财根本 就是他们的囊中之物。在南淑熙的眼中，秀子天真而又脆弱，善良但是敏感，随着时间的推移，朝夕相处的两人之间产生了真挚的情谊，而公爵虚伪而又贪婪的假面渐渐令南淑熙意欲作呕。可是，面对高额的报酬，南淑熙选择了背叛，在她的游说之下，秀子和公爵私奔，举行了结婚仪式，就在这时，发生了一件令南淑熙再也想不到的意外。©豆瓣', '金敏喜', '朴赞郁', 8.4, 409753, 'tt4016934', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2355555424.jpg', 0.3, 1.1, 13.9, 45.2, 39.5, '0.204190,0.187606,-0.655765,0.619735,-0.140523,-0.213684,0.941072,0.216783,-0.327594,-0.255506,0.282508,0.664380,0.005559,0.181844,0.483038,0.140350,-0.046856,-0.993265,-0.168376,-0.449932,0.019527,-0.576225,0.049623,-0.288814,-0.176710,-0.403245,0.766019,0.264498,-0.001234,0.432069,0.730709,0.471828,-0.200993,0.464283,-0.027529,-0.118195,0.022628,0.039602,-0.312475,0.295307,0.136814,-0.277788,0.063668,0.255345,-0.139713,0.359111,0.644807,-0.436174,-0.061708,-0.287027,0.330550,-0.343468,0.039172,0.258034,0.236088,-0.069342,0.200306,0.263674,-0.438881,-0.094426,0.426260,-0.079566,-0.855551,0.023605,0.176365,0.050625,-0.614668,0.311492,-0.063004,-0.114008,0.221167,-0.137800,0.384943,0.477808,0.139980,0.328252,-0.501971,0.143901,-0.343286,0.007182,0.615074,-0.042310,-0.294017,0.236628,-0.284710,-0.397553,0.244319,-0.532214,-0.471801,-0.075064,0.165336,0.206090,0.070301,0.379669,-0.535786,-0.312538,-0.456632,0.019089,0.379960,-0.605101,-0.005673,-0.242906,-0.277132,-0.414157,-0.187247,-0.086373,0.266481,-0.420988,0.638299,-1.001697,0.080833,0.480961,0.453216,-0.673665,0.463867,-0.027671,0.042152,0.033650,-0.306668,0.129345,0.097991,0.225314,0.013716,0.217670,-0.031180,0.097402,-0.180669,0.115619', '30345227', '1301022', '4301278', '1296569');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25978126', '间谍同盟', '剧情', '故事发生在第二次世界大战期间，盟军反情报特工马克斯（布拉德·皮特 Brad Pitt 饰）和法国间谍卧底玛丽安（玛丽昂·歌迪亚 Marion Cotillard 饰）在军事战略要地卡桑布兰卡相遇，为了完成刺杀德国大使的共同愿景，两人不得不假扮夫妻。刚开始，个性大相径庭的马克思和玛丽安之间屡屡产生误会和矛盾，但随着时间的推移，当他们经历了一些生死存亡的危急时刻并且互相救助之后，两人间的假戏慢慢变成了真做，他们相爱了。最终，任务顺利完成，有情人终成眷属，他们结了婚，还有了爱情的结晶。本以为日子就将长此以往的这样进行下去的马克斯，在一次偶然中开始怀疑自己的妻子的真实身份是一名纳粹间谍。©豆瓣', '布拉德·皮特', '罗伯特·泽米吉斯', 7, 70505, 'tt3640424', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2430248243.jpg', 0.8, 7.2, 45.1, 35.5, 11.5, '0.375838,0.061064,-0.718365,0.550295,0.096453,-0.284354,0.569651,-0.084183,-0.501775,-0.267567,0.124385,0.796699,-0.378195,-0.060883,0.423899,-0.226142,-0.526588,-1.018191,-0.022126,-0.176968,-0.288397,-0.680434,-0.325084,-0.308475,-0.199069,-0.265406,0.714319,0.253153,-0.067749,0.405616,0.325957,0.315796,-0.107098,0.248671,-0.115958,-0.109631,0.405544,0.060543,-0.679937,-0.028961,0.339295,-0.097041,-0.020713,0.046516,-0.044406,0.264726,0.540801,-0.453079,-0.033979,-0.234305,0.228258,-0.279175,0.000460,0.116424,0.378329,-0.018362,0.178318,0.439524,-0.159004,-0.116722,-0.074304,-0.054156,-0.641056,0.125461,-0.099793,0.192962,-0.323425,0.369654,-0.082067,0.068735,0.357542,-0.233423,0.171916,0.966645,0.620732,0.173205,-0.278391,-0.144649,-0.499385,0.073062,1.090890,0.027475,-0.319556,0.354485,-0.051682,-0.326941,-0.038799,-0.248890,-0.127790,0.039420,0.210144,-0.078398,-0.159714,0.437972,-0.661414,-0.100082,-0.321407,-0.088180,0.166248,-0.435878,0.086930,-0.678732,-0.339248,-0.637617,-0.358568,0.130932,-0.008562,-0.298063,0.727369,-0.854976,0.175643,0.632022,0.251850,-0.607847,0.390459,0.490684,0.330682,-0.386411,0.002397,0.133941,-0.030254,0.101327,0.252242,0.218158,0.199598,0.127293,-0.133546,0.173035', '30345227', '25721544', '34822138', '1306454');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25980243', '小菜一碟', '爱情', '对爱情有着依赖症的25岁女孩梅宫志乃（多部未华子 饰）此时正陷入恋爱困局，她的男友正树（柄本佑 饰）充满猜忌，为人刻薄，还时不时殴打女友。无以为继的恋爱，两人最终走向分手。在好友奈奈子（木村文乃 饰）和小天（松坂桃李 饰）的帮助下，志乃搬到一处新的公寓，展开全新生活。搬家当晚，志乃便被邻居菅原京志郎（绫野刚 饰）温暖的笑容所击中。可以想不到的是，对方居然就是她接下来将要打工的音像租赁店店长。前男友奚落轻蔑的样子时不时萦绕眼前，志乃不愿承认她就是对方所说的有男人就行的花痴女，但她还是不由自主被已经有女友的对方所吸引……本片根据少女漫画家乔治朝仓的同名漫画改编。©豆瓣', '多部未华子', '田口智朗', 6.4, 7323, 'tt4061360', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2251204816.jpg', 2.9, 15.2, 51.5, 22.3, 8.1, '0.200448,-0.103549,-0.290099,0.263793,-0.169194,-0.122512,0.651375,0.210514,-0.249739,-0.281703,0.338104,0.490179,-0.400410,0.420355,0.249908,0.148822,-0.136003,-0.557523,-0.183433,-0.154607,0.059580,-0.351379,-0.209688,-0.007037,-0.076379,-0.238710,0.801543,-0.083886,-0.367855,0.201404,0.418576,0.505141,-0.204987,0.458877,-0.154783,0.170570,-0.064522,0.057434,-0.229383,0.074150,-0.080736,-0.218314,-0.103078,0.055375,-0.238230,0.444997,0.834999,-0.142168,-0.269651,0.073451,0.514082,-0.010578,-0.174111,0.255603,0.222991,-0.030201,0.312065,-0.138502,-0.330963,-0.014023,0.196274,-0.090979,-0.476856,-0.071574,0.174438,0.100254,-0.203249,0.404257,-0.006117,0.015167,0.431885,-0.264323,-0.041224,0.096387,0.372168,0.338560,-0.115772,0.111917,-0.269328,0.286578,0.445381,0.234617,-0.145684,0.447279,-0.399647,-0.137227,-0.137456,-0.082170,-0.586347,-0.006421,0.160858,0.075688,0.092053,0.017766,-0.509167,-0.205043,-0.046079,0.054570,0.333999,-0.521364,-0.180868,-0.637038,-0.186925,-0.353528,-0.230227,0.109919,0.261269,-0.284826,0.609340,-0.959759,0.079412,0.463661,0.357310,-0.193263,0.587288,0.045873,-0.382734,-0.308985,-0.370013,0.246972,0.109908,0.008413,0.100475,0.415476,-0.058923,-0.067275,-0.212098,0.450544', '10174444', '1316589', '3811356', '26759820');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25980443', '海边的曼彻斯特', '剧情', '李（卡西·阿弗莱克 Casey Affleck 饰）是一名颓废压抑的修理工，在得知哥哥乔伊（凯尔·钱德勒 Kyle Chandler 饰）去世的消息后，李回到了故乡——海边的曼彻斯特处理乔伊的后事。根据乔伊的遗嘱，李将会成为乔伊的儿子帕特里克（卢卡斯·赫奇斯 Lucas Hedg es 饰）的监护人，李打算将帕特里克带回波士顿，但很显然帕特里克并不愿意离开家乡和朋友们，但李亦不愿在这片伤心地久留。原来，曼彻斯特埋藏着李的一段绝望的回忆，他的过失使得三个孩子葬身火海，妻子兰迪（米歇尔·威廉姆斯 Michelle Williams 饰）亦因此而离开了他。此次重回故乡，李再度见到了已经再婚并且即将做妈妈的兰迪，与此同时，帕特里克那失踪已久的母亲艾丽斯（格瑞辰·摩尔 Gretchen Mol 饰）亦联系上了帕特里克，希望他能够成为她的新家庭中的一员。©豆瓣', '卡西·阿弗莱克', '肯尼思·洛纳根', 8.6, 475347, 'tt4034228', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2421855655.jpg', 0.2, 1, 11.5, 43.4, 43.8, '0.177903,0.281449,-0.740545,0.598978,-0.136711,-0.846404,0.844353,-0.034799,-0.488460,-0.627566,-0.038880,0.626633,0.168188,0.711341,0.350380,-0.002873,-0.363479,-0.599731,-0.088812,-0.292813,-0.396838,-0.594660,-0.303226,-0.220437,-0.199618,-0.155238,0.516350,0.092087,0.118837,0.374230,0.347514,0.413848,0.035432,0.471794,-0.027194,0.207948,0.122836,0.293860,-0.445463,0.144425,0.367270,-0.222270,-0.013460,0.131272,0.409611,0.336106,0.529639,-0.327817,0.062985,-0.128934,0.205175,-0.109086,0.204912,0.279543,0.226409,-0.089178,-0.114328,0.006960,-0.423843,-0.178699,0.012867,-0.053686,-0.394579,0.070013,0.147933,0.279822,-0.650469,0.119250,-0.385169,-0.017050,0.025860,-0.585418,0.297939,0.515367,0.146105,0.394815,-0.141397,0.211355,-0.403586,0.148505,0.672662,0.006741,-0.045785,-0.249463,-0.262177,-0.553192,0.065564,0.200831,-0.661114,0.078591,0.488034,0.112295,0.177807,0.325288,-0.302841,-0.423695,-0.272755,-0.256766,-0.157040,-0.325317,0.251488,-0.677782,0.000408,-0.187577,-0.084606,-0.112334,-0.000048,-0.269925,0.461902,-0.664000,0.538031,0.065626,0.076670,-0.539190,0.334833,0.086146,0.551774,-0.288098,0.216451,0.781796,0.235789,0.039058,0.139002,0.262376,0.021509,-0.199115,-0.359305,0.607476', '1844413', '26580232', '2075721', '1298733');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25980500', '正义联盟：亚特兰蒂斯的宝座', '动作', '一艘海军潜艇在马里亚纳海沟神秘沉没，正义联盟派出钢骨维克多（Shemar Moore 配音）调查，谁知维克多却在事故现场遭到一伙神秘对手的袭击。在此之后，超人（Jerry O''Connell 配音）、黛安娜（Rosario Dawson 配音）、闪电侠（Christopher Gorham 配音）、绿灯侠（Nathan Fillion 配音）、蝙蝠侠（Jason O''Mara 配音）、神奇上尉等正义联盟伙伴相继云集总部，经联合调查后发现幕后真凶竟与古老的亚特兰蒂斯有关。这群深海战士在野心勃勃的奥姆王子的率领下向人类宣战，两个种族的全面战争一触即发。危机时刻，不久前刚刚承受丧父之痛的男子亚瑟（Matt Lanter 配音）成为事件的关键。以此为契机，亚瑟以及整个正义联盟的命运都发生了改变……©豆瓣', '克里斯托弗·戈勒姆', '伊桑·斯波尔丁', 6.2, 8052, 'tt3878542', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2246141431.jpg', 2.3, 16, 56.2, 18.4, 7.1, '0.121511,0.253289,-0.678174,0.524253,0.314559,0.036911,0.417482,-0.051588,-0.240145,-0.373691,0.433911,0.510798,0.042522,-0.249275,0.322834,-0.287536,-0.399287,-0.500342,-0.181991,-0.021482,-0.233458,-0.262134,-0.441618,-0.243784,0.157833,-0.406903,0.789021,0.158176,-0.439802,0.213152,0.349119,0.468032,-0.544695,0.178445,0.190483,-0.215237,0.639374,-0.150991,-0.488929,0.196762,-0.555701,0.024173,0.089167,0.258247,-0.475984,0.320414,0.479313,-0.522072,0.063499,-0.434394,0.321175,-0.466462,-0.003609,-0.125708,0.937995,0.048045,-0.265040,0.242451,0.322868,-0.248147,-0.252544,0.118971,-0.962530,-0.080256,0.016709,0.395174,-0.134668,0.064947,-0.123219,0.115147,0.345627,-0.026575,0.151124,0.659027,0.671368,0.043345,0.224426,0.404316,-0.212061,0.075408,0.937919,-0.200530,-0.323867,-0.124176,0.281930,-0.471641,-0.076697,-0.366480,-0.311459,0.014868,0.328411,-0.248909,0.244796,0.517259,-0.733706,0.091401,-0.350364,-0.174476,0.057175,-0.266796,0.011578,-1.097255,-0.186556,0.126326,0.061294,0.185803,0.110057,-0.076171,0.700892,-0.666316,0.184076,0.754767,0.104004,-0.586848,0.370833,0.131716,0.014423,-0.420888,-0.040235,0.257981,0.263506,0.270280,-0.241200,0.018246,0.014630,-0.083171,-0.063061,-0.140770', '2369613', '4014397', '1306809', '7155241');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25983044', '比利·林恩的中场战事', '剧情', '伊拉克战争时期，来自美国德州的19岁技术兵比利·林恩（乔·阿尔文 Joe Alwyn 饰）因为一段偶然拍摄的视频而家喻户晓。那是一次规模不大却激烈非常的遭遇战，战斗中林恩所在的B班班长（范·迪塞尔 Vin Diesel 饰）遭到当地武装分子的伏击和劫持，而林恩为了营救班长不惜铤而走险冲锋陷阵。视频公布于世让他成为全美民众所崇拜的英雄，然而却鲜有人理解他和战友们所经历的一切。为了安葬班长，B班得到了短暂的休假，因此他们得以受邀参加一场在德州举行的橄榄球比赛。林恩的姐姐因某事件深感愧疚，她希望弟弟能借此机缘回归普通生活。而周围的经纪人、球迷、大老板、普通民众则对战争、卫国、士兵有着各种各样想当然的理解。球场上的庆典盛大开幕，林恩和战友们的心却愈加沉重与焦躁……本片根据作家本·方丹（Ben Fountain）的同名小说改编。©豆瓣', '乔·阿尔文', '李安', 8.3, 372025, 'tt2513074', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2391542403.jpg', 0.3, 1.5, 16.3, 45.5, 36.3, '-0.001629,-0.205377,-0.566721,0.534755,0.170283,-0.052894,0.548046,-0.151720,-0.530093,-0.426887,0.252944,0.789627,-0.219600,0.159493,0.299150,-0.477805,-0.309622,-0.577434,-0.132411,0.085363,-0.064653,-0.319361,-0.227769,-0.470976,-0.006652,-0.357199,0.848095,0.260702,-0.374487,0.743620,0.214620,0.333394,0.128109,0.425758,0.026695,-0.244457,0.061410,0.032847,-0.486885,-0.046416,-0.241674,-0.094119,-0.370676,0.207661,0.222071,0.240191,0.627510,-0.327479,-0.123934,-0.105547,0.466154,-0.443962,0.024981,0.061660,0.198133,0.201979,0.342840,0.023889,0.130451,0.056864,-0.202784,-0.215821,-0.742930,0.067399,0.105611,0.036866,-0.283224,0.628272,0.031220,0.117381,0.172229,-0.004540,0.241262,0.550657,0.302189,0.182573,-0.232437,-0.119915,-0.235830,0.332693,0.951819,-0.023431,-0.225073,0.077796,-0.396887,-0.527968,0.130280,-0.424747,-0.556393,0.370464,0.186516,-0.214520,0.163966,0.405233,-0.496587,-0.040044,-0.124037,-0.339681,0.009202,-0.443282,0.134569,-0.928478,-0.045253,-0.244129,-0.179638,-0.138433,0.129933,-0.342683,1.004699,-0.848468,-0.040831,0.490267,0.218834,-0.540050,0.459124,0.236433,0.228945,-0.253375,-0.344936,0.108809,-0.024026,0.158848,-0.100703,0.175170,-0.051721,-0.320454,-0.194450,0.393919', '3811356', '2369613', '25922902', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25984803', '假如猫从世界上消失了', '剧情', '年轻俊朗30岁的邮差（佐藤健 饰）被诊断脑部长有恶性肿瘤，仅剩下半年左右的生命了。在无助的时刻，自称魔鬼且和邮差长得一模一样的阿罗哈（佐藤健 饰）出现在邮差面前。他声称为邮差准备了一个延长生命的机会，只不过在魔鬼的法则中，有得必有失。假设邮差的生命延长一天，则世界上就会有某样东西消失。半信半疑的邮差接受了阿罗哈的建议，他先后消除了电话、电影和钟表。如电话的消失，让低头族从虚拟的世界中解放出来，使邮差有了隐隐的成就感。然而看似无关紧要的消失，却也带走了他最为看重的人和事。比如他的初恋女友（宫崎葵 饰）以及因电影而结缘的好友百视达（滨田岳 饰）。最终，连邮差的爱猫高丽菜也面临消失的命运……©豆瓣', '佐藤健', '永井聪', 7.4, 31514, 'tt4042994', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2324946184.jpg', 0.7, 5, 36, 40.3, 18.1, '0.099529,0.232265,-0.459856,0.466122,-0.293601,-0.236720,0.687577,0.318552,-0.253779,-0.249031,0.127802,0.749458,-0.320386,0.082466,0.276747,-0.041449,-0.029712,-0.618837,-0.308839,-0.174969,-0.251689,-0.379165,-0.229910,-0.215690,0.007882,-0.480895,0.552035,0.086627,-0.147456,0.379665,0.125577,0.279933,-0.010372,0.319380,-0.079750,0.079558,-0.070983,0.041446,-0.024520,0.163678,0.142428,-0.111787,0.306294,0.204151,-0.304473,0.384818,0.710000,-0.318468,-0.299907,-0.060195,0.555309,-0.210521,-0.104593,-0.128195,0.286602,0.124743,0.030537,0.083829,-0.246542,-0.010107,0.151876,0.019619,-0.813126,-0.124533,0.006253,0.277914,-0.316631,0.464377,0.045500,-0.119821,0.228655,-0.327185,0.360210,0.087389,0.262251,0.502519,-0.081219,-0.031838,-0.562766,0.178969,0.189061,-0.024562,-0.492041,0.493559,-0.310960,-0.497944,-0.226337,-0.191562,-0.260781,0.010464,0.333169,0.154566,-0.225823,0.159601,-0.586716,-0.019034,-0.130256,-0.102631,0.158537,-0.352211,-0.326758,-0.410899,-0.036246,-0.363416,-0.395522,0.369306,0.155917,-0.244658,0.889534,-0.758158,0.352552,0.575956,0.197191,-0.141746,0.878447,0.123524,-0.035738,-0.197824,0.172589,0.380645,0.067807,0.329237,0.170894,0.038677,-0.272214,-0.117001,-0.550595,0.549239', '27602116', '24284209', '25880986', '2027945');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25986180', '釜山行', '动作', '证券公司基金管理人石宇（孔侑 饰）光鲜精干，却也是个重利轻义之徒。妻子为此与之决裂，女儿秀安（金秀安 饰）则对如此自私的父亲越来越失望，决定前往釜山和母亲生活。在秀安生日这天，石宇抽出时间陪伴女儿登上开往釜山的特快列车。而与此同时，城市四处出现了极为可疑的暴动事件。政府极力洗白无法掩盖丧尸肆虐的事实，即便懵然无知的列车乘客也因为不速之客的到来而堕入恐慌绝望的地狱中。开车的刹那，一名感染者冲入车厢，而她很快尸变并对目光所及之处的健康人展开血腥屠杀。未过多久，丧尸便呈几何数爆发性地增长。石宇被迫和幸存者的乘客们在逼仄的空间中奋力求生。通往釜山的遥遥旅途布满杀机，危难时刻每个幸存者的人性也承受巨大的考验……©豆瓣', '孔刘', '延尚昊', 8.6, 1115508, 'tt5700672', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2360940399.jpg', 0.3, 0.8, 11.1, 44.7, 43.1, '-0.020360,-0.078652,-0.769175,0.401503,0.178158,-0.081673,1.079556,0.160737,-0.506144,-0.108708,0.367388,0.431748,-0.052390,0.033721,0.384490,-0.427082,-0.114437,-0.362403,-0.234484,-0.103682,-0.308302,-0.213821,-0.143958,-0.240108,0.047858,-0.304878,0.807447,0.576395,-0.078218,0.650237,0.265310,0.185009,-0.327884,0.663117,-0.052379,-0.300084,-0.174214,-0.003408,-0.180673,0.015699,-0.158532,-0.374866,-0.065477,0.128448,-0.264064,0.297189,0.871972,-0.252624,-0.141570,-0.242306,0.147032,-0.422110,-0.026860,0.173129,0.272779,0.022233,0.115011,0.071729,-0.066669,0.071822,-0.200097,0.144891,-0.576501,-0.089750,-0.100559,0.079064,-0.332054,0.195910,0.057994,-0.106435,-0.096397,-0.357974,0.029524,0.114126,-0.047174,0.365373,-0.413264,0.031492,-0.291135,-0.161345,0.585644,-0.075801,-0.286259,0.187388,-0.344376,-0.453527,-0.140270,-0.154178,-0.626594,-0.293451,0.203882,0.201357,-0.142914,0.472299,-0.609338,0.129537,-0.331732,-0.454675,-0.123448,-0.164028,-0.278182,-0.537472,0.048527,-0.201353,-0.082970,0.236462,0.086473,-0.041242,0.479621,-0.627403,0.173421,0.335210,0.520791,-0.463307,0.511579,-0.103898,0.167314,-0.150743,-0.158118,0.515621,0.055156,0.547142,-0.171483,-0.082402,-0.347174,-0.000643,-0.397167,0.413998', '21619567', '3011051', '20451118', '20497633');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25986662', '疯狂的外星人', '喜剧', '号称银河系最先进的外星文明试图和地球建交，谁知一连串的误会导致意外发生。外星使者的飞船坠入大气层，最终摔在了中国某市的世界公园中。靠耍猴戏为生的耿浩（黄渤 饰）和酒贩子好友大飞（沈腾 饰）把受伤的外星人错认为来自南美洲的猴子，在自家猴子受伤的情况下，耿浩开始训练起这个他口中的“刚果骚骚猴”来了。由于失去了超能力加成设备，外星人的本事无法施展，只能任由这两个傻乎乎的地球人打骂操练。尽管如此，他仍试图夺回自己的装备。另一方面，之前与外星人交流失败的超级大国根据外星人留下的信息，穿梭世界各地寻找外星使者。地球的命运朝着不可预测的方向发展……本片创意来自刘慈欣的科幻小说《乡村教师》。©豆瓣', '黄渤', '宁浩', 6.4, 658776, 'tt6660238', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2541901817.jpg', 4.3, 15.8, 44.7, 27, 8.2, '0.479268,0.045718,-0.733770,0.613468,-0.042140,0.057532,0.459122,-0.239433,-0.412974,-0.031203,0.245020,0.649189,0.033197,-0.046256,0.144538,-0.057409,-0.391475,-0.403525,-0.149898,0.036958,-0.380242,-0.314219,-0.553861,-0.261017,-0.083042,-0.230764,0.516392,-0.079684,-0.593913,0.252549,0.093218,0.419985,-0.359803,0.175026,-0.357581,0.080877,-0.016479,-0.062560,-0.212773,0.289630,0.099371,-0.143595,0.104224,0.191510,-0.238366,0.304146,0.802763,-0.480282,0.044182,-0.519476,0.365313,-0.155059,-0.010894,-0.091179,0.384286,0.071411,-0.118137,0.084180,0.338078,0.301364,0.263764,0.116059,-0.737672,-0.146293,0.112596,0.113464,-0.412403,0.321954,-0.061110,0.030415,-0.083754,-0.296860,0.316883,0.370252,0.415089,0.376084,-0.291316,0.046214,-0.461001,0.219619,0.417483,0.007171,-0.335948,0.392307,-0.140470,-0.541998,-0.236245,-0.277196,-0.356631,0.025118,0.347541,0.093897,-0.537597,0.410076,-0.799283,0.252824,0.069714,-0.432484,-0.157781,-0.167096,-0.075251,-0.678088,0.027821,-0.381212,0.027724,0.152630,0.100666,-0.017005,0.717926,-0.466502,-0.159113,0.654900,0.430630,-0.376419,0.591795,-0.047146,-0.188333,-0.363073,-0.072480,0.249893,0.173448,0.512683,-0.082807,0.228276,0.188688,-0.199007,-0.329789,0.368223', '26290398', '25774050', '25928048', '4181031');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('25995508', '移动迷宫2', '动作', '托马斯（迪伦·欧布莱恩 Dylan O''Brien 饰）、米诺（李基弘 Ki Hong Lee 饰）一行人被带到一座神秘的庇护所，这个机构由表里不一的詹森（艾丹·吉伦 Aidan Gillen 饰）所管理，詹森为他们提供安稳且舒适的环境，并下令让幽地斗士们在医疗实验室中接受一连串的测试，詹森向托马斯保证将会把他们送到更加安全的保护区与其他对“闪焰症病毒”免疫的年轻人一同居住。察觉事有蹊跷的托马斯决定再次带领他的伙伴们逃出詹森的掌控，然而等待他们的，却是比迷宫更加危险的焦土。影片改编自詹姆斯·达什纳撰写的同名反乌托邦科幻小说三部曲的第二部。', '迪伦·奥布莱恩', '韦斯·鲍尔', 6, 113681, 'tt4046784', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2276189752.jpg', 4, 20.8, 51.2, 17.6, 6.3, '0.387471,-0.157885,-0.566980,0.612120,0.080564,0.043030,0.669089,0.100483,-0.491922,-0.402883,0.256516,0.747049,-0.137480,0.007658,0.339416,-0.149526,-0.441947,-0.413181,-0.305218,-0.136838,-0.422608,-0.545918,-0.190947,-0.595427,-0.061502,-0.389170,0.623967,0.157092,-0.351603,0.184402,0.125631,0.485902,-0.178082,0.248501,-0.058999,-0.057821,0.030391,-0.349757,-0.385656,0.340469,-0.144058,0.107234,-0.128714,0.160963,0.228254,0.252231,0.717816,-0.521769,-0.260453,-0.013829,0.389067,-0.360050,0.046424,0.017016,-0.044955,-0.020265,-0.255227,0.199448,-0.273058,0.319438,-0.027588,-0.299568,-0.866006,0.043745,0.225370,0.248889,-0.376930,-0.020483,0.138181,-0.035409,0.049277,-0.190495,0.081941,0.282777,0.139478,0.439816,-0.044311,0.193236,-0.311444,-0.037502,0.406306,-0.095005,-0.335489,0.040743,-0.269299,-0.550033,-0.098637,0.082873,-0.516910,-0.065653,0.376042,0.156277,0.311207,0.072748,-0.707226,-0.187715,-0.215678,-0.444242,-0.086462,-0.450920,0.196959,-1.209157,-0.013056,-0.039255,0.012819,0.136839,0.063978,-0.282672,0.535769,-0.483779,0.241912,0.396245,0.162502,-0.643165,0.394569,0.033778,0.445118,-0.167533,-0.152753,0.523793,0.515508,0.280088,-0.083500,0.365983,0.042084,-0.287078,-0.390166,0.253870', '2369613', '6517421', '26577354', '1306809');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26000205', '鲨滩', '惊悚', '为了纪念早逝的母亲，南希（布蕾克·莱弗利 Blake Lively 饰）来到了那片对于母亲来说有着别样意义的沙滩，准备在此进行一场冲浪运动。幽静的环境，清澈的海水，温暖的阳光，活跃的水鸟，南希深深觉得这里是上帝赐予她和母亲的福地。在冲浪途中，南希意外发现了一头遭到鲨鱼攻击而不幸死亡的鲸鱼尸体，这不祥的一幕预示了她即将要面对的可怕经历。尸体的气味吸引了鲨鱼远道而来，南希遭到了鲨鱼的攻击，大腿受伤，挣扎之下，南希爬到了一块露出海面的礁石之上，在这里等待着不知从何而来的救援。更糟糕的是，这块礁石随着潮水的到来很快就要被淹没，这也就意味着，到那时，南希将彻底陷入鲨鱼的血盆大口之中，无处可逃。©豆瓣', '布蕾克·莱弗利', '佐米·希尔拉', 7.1, 101036, 'tt4052882', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2346553438.jpg', 0.6, 4.2, 42.7, 42.4, 10.1, '0.482456,-0.038125,-0.973674,0.535803,0.195080,-0.039591,1.109293,0.236949,-0.470320,0.148183,0.688104,0.639974,-0.312397,0.152325,0.250180,0.144358,-0.054404,-0.557141,-0.185728,-0.067906,-0.477304,-0.265939,-0.533837,0.064152,0.248006,-0.446129,0.572152,0.432720,-0.098636,0.789172,0.017993,0.337072,0.004397,0.831158,-0.211713,0.019918,-0.085778,0.045235,-0.075586,0.343568,0.138683,-0.278599,0.128696,0.455143,-0.299778,0.274134,0.824368,-0.422820,-0.236765,-0.140913,0.206782,-0.527325,0.371578,0.441200,0.631091,-0.105322,-0.113787,-0.028724,-0.272285,0.187312,0.381211,0.012753,-0.537653,-0.086975,-0.193109,0.449610,-0.448777,0.254958,0.140020,-0.146166,0.176119,-0.297044,0.317412,0.116419,-0.011987,0.469927,-0.229149,0.133452,-0.362830,0.008867,0.783835,-0.165238,-0.127045,0.371993,-0.404793,-0.306040,0.145972,-0.152918,-0.149789,-0.174859,0.613832,0.488268,-0.470780,0.350366,-0.869283,0.130635,-0.188889,-0.515516,-0.378844,-0.154393,-0.568484,-0.345288,-0.223820,-0.298729,-0.052959,0.183065,-0.133839,-0.121348,0.529209,-0.693570,0.303664,0.743248,0.140617,0.147476,0.464991,-0.104316,-0.105050,0.244934,0.088949,0.248339,-0.128061,0.497201,0.187414,0.343214,-0.059434,0.136621,-0.573446,0.620213', '3011051', '20451118', '20380318', '21619567');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26004132', '移动迷宫3：死亡解药', '动作', '托马斯（迪伦·奥布莱恩饰）率领的林间斗士在经历了迷宫逃脱和末日丧尸的生死考验后，终于迎来最后的正邪较量。由托马斯、纽特（托马斯·桑斯特饰）等人领军的营救团队，耗时三年筹划营救被抓走的米诺，却意外地发现米诺不在劫获的那截火车上。经调查得知，米诺深陷在WCKD组织的控制之中，托马斯和纽特毅然决定起身前往被称为“最后之都”的人类最后净土，更不惜利用背叛林间斗士投身WCKD的特蕾莎（卡雅·斯考达里奥饰）闯入WCKD，营救米诺和其他人。', '迪伦·奥布莱恩', '韦斯·鲍尔', 5.3, 90710, 'tt4500922', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2508618114.jpg', 8.7, 32.9, 45.7, 10.3, 2.3, '0.168014,0.069652,-0.626653,0.363622,0.205783,-0.401858,0.598374,-0.017747,-0.297651,-0.241408,0.238355,0.514028,-0.189619,-0.107664,0.636753,-0.113217,-0.505051,-0.778966,-0.141406,-0.147985,-0.405665,-0.473101,-0.435235,-0.000619,0.029305,-0.412663,0.700624,0.356181,-0.261923,0.505944,0.149759,0.391394,-0.090220,0.341781,0.077699,0.008549,0.376290,-0.066876,-0.139964,0.228538,-0.184000,-0.369536,-0.195540,0.114768,0.100972,0.487616,0.589635,-0.594161,0.346011,-0.205545,-0.049436,-0.536053,0.077099,-0.104468,0.393983,-0.081633,0.034265,0.303594,-0.070703,-0.027629,0.057487,-0.069937,-0.798790,0.112319,0.172299,0.235527,-0.659736,0.208253,-0.001081,0.272153,0.195094,-0.165602,-0.015604,0.619528,0.139661,0.249672,0.021163,-0.232641,-0.620354,-0.114146,0.624142,-0.382659,-0.060698,-0.236100,0.040854,-0.473875,0.078164,-0.308593,-0.163288,-0.165277,0.381559,0.219391,-0.059039,0.353968,-0.731814,-0.201935,-0.508192,-0.108986,-0.070961,-0.275661,-0.097537,-0.946342,-0.016828,-0.032382,-0.213007,0.270881,-0.072731,-0.212775,0.212325,-0.682074,0.411351,0.181166,0.341739,-0.222451,0.609851,-0.061434,0.278838,-0.202645,0.280611,0.468503,0.320078,0.396697,0.226070,0.299228,0.123716,-0.123629,-0.550413,0.201996', '1294917', '1293656', '25723905', '20274039');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26011893', '全能囧爸', '喜剧', '李国富（罗京民 饰）和儿子平娃（孙波 饰）一起过着相依为命的生活，令辛辛苦苦将平娃拉扯长大的李国富感到心塞的是，尽管平娃已经是奔三的男人了，可他的一堆大事却还要自己操心，更糟糕的是，平娃似乎还处于叛逆期中，对父亲干涉自己的人生感到十分不满。李国富帮儿子找工作、找老婆，却还是放心不下，与此同时，他还是广场舞小分队中的领袖人物，为了领导队伍殚精竭虑。为了向儿子证明自己的能力，一把年纪的李国富毅然报名参加了选秀比赛，将自己的生活弄得鸡飞狗跳。幸运的是，李国富并不是白忙一场，他忙来了亲情，更忙来了久违的爱情。©豆瓣', '罗京民', '董春泽', 7.8, 10089, 'tt10299856', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2230484792.jpg', 0.7, 2.8, 24.9, 46.8, 24.8, '-0.151647,-0.089619,-0.663244,0.553325,-0.326941,-0.634990,0.824356,0.101546,-0.525628,-0.103437,0.099313,0.320900,0.023234,0.470955,0.078615,-0.186643,-0.037342,-0.728140,-0.135131,0.145789,-0.359195,-0.262014,-0.089647,-0.162635,-0.380475,0.008858,0.493092,0.090394,-0.218489,0.272327,0.407079,0.081502,0.402457,0.606760,-0.243608,0.005025,-0.252455,0.366882,-0.293818,-0.371602,0.466745,-0.410809,-0.454659,0.321185,0.317682,0.354363,0.565273,-0.020177,-0.061523,-0.317208,0.251312,-0.290790,-0.151787,-0.041582,0.217595,-0.082463,0.092983,-0.131531,-0.085892,-0.090627,0.014407,-0.210716,-0.964232,0.248058,0.304360,0.059110,-0.828369,0.102487,-0.276099,-0.204626,0.298161,-0.451689,0.259526,0.368081,0.052808,0.593094,-0.396302,0.150091,-0.334351,0.524803,0.838969,0.036978,0.044725,0.060258,-0.326496,-0.408024,0.166217,-0.178567,-0.561232,-0.035842,0.295617,-0.357341,0.160248,0.105829,-0.314554,0.045751,-0.014191,-0.330806,0.033470,-0.613215,0.310069,-0.029598,-0.010029,-0.507210,-0.357852,0.077106,0.152018,-0.447868,0.548738,-0.561560,0.037397,0.354533,0.274400,-0.687031,0.673048,0.178343,0.209918,-0.386582,0.031915,-0.076321,-0.318339,0.397219,0.435742,0.401292,0.267611,-0.354663,-0.250057,0.533856', '6874741', '1877596', '30163500', '1306916');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26012321', '我的新野蛮女友', '喜剧', '影片讲述了男主人公牵牛（车太贤 饰）与新“野蛮”女友星星（宋茜 饰）从相恋到结婚的浪漫经历。星星是牵牛的小学初恋，由于韩语不流利常常被周围同学欺负。牵牛最初仍无法忘记分手离别的前任“她”，直到有一天，牵牛再次遇见初恋星星后，便不顾身边人的反对和她走进婚姻殿堂，没想到摆在他面前的却是超出想象的烦恼。', '宋茜', '赵根植', 3.7, 15281, 'tt4080594', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2339686339.jpg', 52.8, 24.9, 11.9, 3.9, 6.6, '0.332418,-0.143958,-0.767323,0.357208,0.042278,-0.365714,0.868767,-0.135472,-0.262007,-0.248224,0.086453,0.432623,-0.484604,0.493081,0.425238,-0.199262,-0.259999,-0.830981,-0.049573,0.119854,-0.165348,-0.526903,0.136331,0.358053,-0.375528,-0.241016,0.552993,-0.087900,-0.270580,0.565782,0.221610,-0.040431,-0.212970,0.190977,-0.202034,0.119321,0.154039,0.692420,-0.251068,0.066243,-0.114628,-0.027344,-0.022477,0.074853,-0.202934,0.125825,0.624084,-0.103685,-0.255247,-0.096400,0.654183,-0.009070,-0.196683,0.138548,0.357198,0.166811,0.265346,0.096463,0.024913,-0.016354,-0.057468,-0.015118,-0.323320,0.438809,0.137016,0.153721,-0.287807,0.415575,0.033035,-0.095626,0.519172,-0.423538,0.122571,-0.035960,0.399082,0.555266,-0.345205,-0.077133,-0.488884,0.466525,0.981701,0.258570,-0.132490,0.596928,-0.169061,-0.103349,0.021191,0.099773,-0.609224,0.601717,-0.053445,0.180302,-0.303822,0.484827,-0.435794,-0.101764,-0.039222,0.088113,0.615617,-0.346860,-0.209592,-0.566810,-0.306459,-0.410987,-0.407611,0.108969,-0.070702,-0.225647,0.706970,-0.834270,0.289310,0.153769,0.484594,-0.187826,0.786285,0.274562,-0.104647,-0.260005,0.321463,0.443387,0.027449,0.103396,-0.287018,0.106694,-0.071745,0.039798,-0.435644,0.262393', '26687241', '25858759', '4275444', '10535447');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26020796', '家族之苦', '喜剧', '劳碌半生的平田周造（桥爪功 饰）定年退休，而今这个老头优哉游哉，日常和老友们打高尔夫球散心，玩乐过后再来到居酒屋和风韵犹存的老板娘佳代（风吹纯 饰）调笑一番，生活好不惬意。这一日，当他一如往常醉醺醺回到家中时，看似逆来顺受的老婆富子（吉行和子 饰）居然提出离婚的请求，登时令周造酒醒了大半。次日醒来，富子依然没有改变主意，周造的心情因此变得越来越糟。父母婚变，连带平田家的其他成员长子幸之助（西村雅彦 饰）、儿媳妇史枝（夏川结衣 饰）、女儿成子（中岛朋子 饰）、女婿泰藏（林家正藏 饰）、小儿子庄太（妻夫木聪 饰）及其女友宪子（苍井优 饰）也被卷入其中。吵吵闹闹，喜怒哀乐，东京平凡的一户人家日常一瞥……©豆瓣', '桥爪功', '山田洋次', 8.1, 50537, 'tt4065842', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2364502659.jpg', 0.2, 1, 17.3, 54.5, 26.9, '0.114254,-0.126822,-0.352176,0.056752,-0.172561,-0.375821,0.435638,0.537504,-0.587810,-0.609359,0.014294,0.600385,-0.280520,0.364147,0.297832,-0.014147,-0.260672,-0.323926,0.085407,0.178815,0.237087,-0.230739,0.267637,-0.071011,-0.280887,0.053683,0.288566,-0.126591,0.222766,0.523951,0.040615,0.239561,-0.123443,0.225722,-0.113880,0.341147,-0.130138,0.345786,-0.019917,0.006719,-0.303712,0.016348,-0.293522,-0.118612,0.246455,0.496405,0.589930,0.036275,-0.264323,-0.297657,0.154343,0.098606,-0.386046,0.384426,0.350071,-0.047910,0.275102,0.219415,-0.317645,-0.134793,0.093720,-0.018716,0.050975,0.255100,0.246085,-0.011316,-0.136000,0.418501,-0.045912,-0.246851,0.051912,-0.271312,0.095822,0.232975,0.013077,0.260422,-0.278767,0.255582,-0.318901,0.361986,0.367574,0.031466,0.181759,0.307967,-0.089349,-0.033105,0.148407,-0.314167,-0.350157,-0.271700,0.056246,0.106634,-0.037094,0.052071,-0.426332,-0.172828,-0.102691,0.035832,0.269865,-0.194412,-0.088090,-0.588368,0.032653,-0.519716,-0.349232,0.293171,0.096912,0.043538,0.360192,-0.554340,0.070970,-0.163015,0.056319,-0.213999,0.299355,0.106800,0.072354,-0.341128,0.102735,0.060415,0.162844,0.066110,0.082897,0.236488,-0.283082,-0.197406,-0.226156,0.080972', '1461079', '3811356', '1306183', '1297239');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26020814', '胜者即是正义 2014SP', '剧情', '东都综合医院为一位疑难病症患者投放新型药物，仅仅三天后该患者突发心肌梗塞身亡。患者遗孀中原纱弥加（吉濑美智子 饰）悲痛交加，她认为丈夫死于医疗事故，因此拜托“敲诈律师”九条和马（大森南朋 饰）对医院提起指控。因盲肠炎住院治疗的古美门研介（堺雅人 饰）刚好是该医院的顾问律师，他三下五除二赶走了九条。谁知九条一改当初的敲诈作风，而是煞有其事地将东都综合医院正式告上法庭。随着庭审的进行，医护人员涉嫌隐藏新药的致死副作用以及院长赤目义和专横跋扈、糜烂堕落的生活作风接连被曝了出来。终于开始认真应战的古美门律师以及在法律和道义两端摇摆不定的黛真知子（新垣结衣 饰），在一波三折中奔向庭审的终点线……©豆瓣', '堺雅人', '石川淳一', 8.7, 65389, 'tt2725232', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2876748819.jpg', 0.2, 1, 12.2, 38.1, 48.6, '-0.018870,-0.162724,-0.219364,0.199573,0.193466,-0.193475,0.386007,0.204867,-0.171995,-0.296875,0.370014,0.392642,-0.188772,0.025771,0.463877,-0.161332,-0.130819,-0.536954,-0.092858,0.244275,-0.274781,-0.684452,0.060012,-0.208637,-0.007437,-0.258457,0.373198,-0.154436,-0.245179,0.575824,0.287409,0.653211,-0.173026,0.138910,0.179907,-0.117074,-0.019483,-0.012567,-0.268147,0.161567,0.471179,-0.390890,0.099548,0.018354,0.197840,0.431851,0.562045,-0.054918,-0.210938,-0.192739,0.484147,-0.199647,-0.121501,0.290646,0.425702,0.054851,0.218966,0.390164,-0.374292,-0.087876,0.159339,0.030934,-0.505579,-0.267453,0.014001,0.213556,-0.299687,0.526071,-0.233087,0.081304,0.114279,-0.285806,-0.050335,0.192681,-0.151532,0.571323,-0.187191,-0.210990,-0.442117,0.255886,0.114899,-0.100159,-0.082671,0.140838,-0.033184,-0.559053,0.053608,-0.211043,-0.172301,-0.113500,0.106005,-0.060872,-0.287312,0.050592,-0.251624,-0.204061,-0.303698,-0.110710,-0.034953,0.060666,-0.028808,-0.528141,0.248821,-0.107241,-0.216091,0.029406,0.083499,0.083195,0.312477,-0.612182,0.108013,0.108812,0.108642,-0.684374,0.341292,0.080444,0.047583,-0.180445,-0.285839,-0.049364,0.316692,0.563735,0.353955,0.206471,0.075442,-0.224521,-0.330749,0.005526', '2042181', '25723905', '33591810', '4202326');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26021055', '栀子花开', '爱情', '校内闻名的栀子花乐队主唱许诺（李易峰 饰）和芭蕾舞专业的言蹊（张慧雯 饰）是大学校园里一对幸福热恋的情侣。二人为各自的梦想而奋斗着：怀揣芭蕾梦想的言蹊和三位室友兼好友，一同申请去巴黎深造；许诺和队友们也在不懈努力着，希望能在“梦想之夜”得到唱片公司青睐，出道成为职业乐队。然而就在言蹊以为巴黎之梦触手可及的时候，她却遭遇了现实中的巨大障碍。看着言蹊处于崩溃边缘，许诺一直陪伴她左右。为了让她重新振作燃起希望，许诺决定和乐队成员一起，为她准备一个意想不到的大惊喜。但是，这个决定却让他付出了不小的代价。这些处于青春迷茫期的年轻人，究竟何去何从……©豆瓣', '李易峰', '何炅', 4.5, 151898, 'tt4819470', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2253155703.jpg', 31.7, 30.3, 24.7, 6.2, 7.1, '-0.013002,0.248360,-0.787118,0.803548,-0.064453,-0.428733,0.738920,0.146774,-0.240876,-0.149194,0.067536,0.850579,-0.052702,0.618675,0.293509,-0.252122,-0.215993,-0.941236,-0.200710,-0.237326,-0.232967,-0.316071,-0.314224,0.032338,-0.291244,-0.244126,0.824363,0.220367,0.044865,0.610798,0.575410,-0.005271,-0.083584,0.244559,-0.105894,-0.244216,0.271004,0.270825,-0.604864,0.213453,-0.099185,-0.189264,-0.201800,0.200864,0.006387,-0.096511,0.806127,-0.180863,-0.061548,0.037843,0.316648,-0.296142,0.132489,0.177624,0.034368,0.231259,0.297369,-0.169211,-0.253496,0.042789,-0.021515,-0.240997,-1.104324,0.102991,0.239293,0.123857,-0.799754,0.663382,0.050202,-0.128285,0.566159,-0.241239,0.188475,0.524824,0.434265,0.522082,-0.397779,0.155948,-0.371153,0.349319,0.874173,-0.036937,-0.125589,0.326143,-0.406171,-0.309956,-0.065069,0.001072,-0.651009,-0.158981,0.058510,0.187123,-0.007750,0.095467,-0.485652,0.173324,-0.125201,-0.262301,0.027285,-0.667113,0.037423,-0.584849,0.004449,-0.166940,-0.237300,0.263002,0.187986,-0.549053,1.086177,-1.034646,0.272160,0.701705,0.418579,-0.541493,0.963787,0.188702,0.223888,-0.302502,-0.148791,0.093426,-0.324622,0.206318,0.005250,0.157438,-0.205944,-0.081128,-0.605164,0.474444', '4301278', '25928048', '35048413', '27602116');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26022182', '她', '剧情', '米歇尔（伊莎贝尔·于佩尔 Isabelle Huppert 饰）是一家游戏公司的老板，在同事和朋友们眼中，她为人冷淡疏离，行事雷厉风行，是一个无坚不摧的女人。可是，就在某一天晚上，米歇尔被闯入家中的蒙面暴徒强暴了。米歇尔没有报警，因为她的父亲曾是臭名昭著的连环杀人犯，而作为他的女儿，米歇尔再也不想和警方和媒体打交道了，她决定依靠自己的力量查出事件的真相。米歇尔要解决的麻烦还有很多，她的儿子娶了一个咄咄逼人的女人，她的母亲即将嫁给一个比她年纪还要小的男人，她的前夫有了新的约会对象，而她正在和她最好的朋友的丈夫偷情。某一日，暴徒再度潜入了米歇尔家中，这一次，米歇尔看清了他的面貌。©豆瓣', '伊莎贝尔·于佩尔', '保罗·范霍文', 7.7, 117991, 'tt3716530', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2402012821.jpg', 0.7, 3.2, 27.4, 48.7, 19.9, '0.319980,-0.208797,-0.638405,0.635931,-0.704115,-0.359286,1.035306,0.144572,-0.557633,-0.354910,0.282475,0.944100,-0.033327,0.437655,0.158524,0.234083,-0.040650,-0.754159,0.028097,-0.122348,-0.128955,-0.435588,-0.242670,-0.457490,0.096906,-0.119830,0.595064,-0.119394,-0.189859,0.081911,0.453606,0.174232,0.162008,0.729453,-0.505505,0.031531,0.015260,-0.103148,-0.181765,0.306177,0.151853,-0.305160,-0.092820,0.448513,-0.124939,0.621371,0.480755,-0.024740,-0.201037,-0.166006,0.431656,-0.302684,-0.032908,0.212655,0.350812,-0.360279,0.290096,0.296737,-0.195485,-0.410337,0.141370,-0.022978,-0.711873,0.135890,0.111803,0.102639,-0.720664,0.532459,-0.322432,0.113310,0.153604,-0.251143,0.243731,0.243988,-0.004893,0.259260,-0.125578,-0.077950,-0.601325,0.276819,0.796906,0.164376,-0.049609,0.427266,-0.146215,-0.304341,0.022585,-0.427283,-0.654808,0.132997,0.416854,-0.249151,-0.495709,0.213496,-0.502347,-0.191685,-0.279859,-0.002563,-0.023576,-0.502646,-0.039420,-0.367914,-0.149515,-0.509040,-0.463745,0.103587,0.076539,-0.249305,0.793060,-1.061796,0.091252,0.886699,0.443445,-0.854154,0.823106,0.318204,0.073122,-0.231429,0.036555,-0.134524,0.151730,0.243754,0.093620,0.479024,0.194277,-0.086091,-0.222597,0.521052', '1308755', '1302384', '3230462', '1301022');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26022765', '致命弯道6：终极审判', '恐怖', '一文不名的青年丹尼（Anthony Ilott 饰）偶然得知他在偏远的西佛尼亚州山村还有亲戚的消息，于是在一个阳光明媚的日子里，丹尼带着女友托妮（Aqueela Zoll 饰）以及维克（Rollo Skinner 饰）吉莉安（Roxanne Pallett 饰）、罗德（Billy Ashworth 饰）等朋友来到了幽静而神秘的霍布温泉庄园。该庄园建于20世纪初，虽然老旧却不失典雅庄严。号称丹尼表兄妹的杰克森（Chris Jarvis 饰）和萨莉（Sadie Katz 饰）殷勤接待了一行人。快乐无忧的年轻人们纵情玩耍，口无遮拦，却不知晓这里隐藏着怎样可怕而惊人的秘密。对丹尼来说，原本是继承家产的愉快旅程，而今变成了遭受可怕恶魔猎杀的狩猎游戏……©豆瓣', '安东尼·伊洛特', '瓦列·米利夫', 5.3, 13309, 'tt3612032', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2202680657.jpg', 15.1, 30.4, 36.5, 10.5, 7.6, '0.405441,0.032761,-0.612212,0.436831,-0.085559,-0.028187,0.882791,0.356431,-0.698460,-0.218096,0.267167,0.528012,-0.066228,0.145301,0.369111,0.289126,-0.313266,-0.147929,0.051803,-0.360896,-0.174380,-0.411080,-0.409189,-0.156337,0.076564,-0.443134,0.164339,0.272295,0.007858,0.661668,0.233086,0.308425,-0.488764,0.378445,-0.438533,-0.276453,0.291030,0.225634,-0.232766,0.096088,-0.306117,-0.061222,-0.286702,0.054253,0.133994,0.405049,0.627442,-0.364931,-0.229843,0.083988,0.202555,-0.022547,-0.062023,0.041069,0.275933,-0.176699,0.254618,0.227170,-0.125610,-0.036456,0.109280,-0.339179,-0.419630,0.263938,0.333339,0.337149,-0.444602,0.768995,-0.122913,-0.354594,0.094705,-0.263718,0.123028,0.207319,0.028103,0.482897,0.333771,0.158560,-0.580596,0.184465,0.530068,-0.096964,-0.372979,0.265071,-0.274153,-0.354217,0.190961,-0.331988,-0.583388,-0.065012,0.171771,0.013948,-0.024679,0.165895,-0.657939,0.183021,-0.290028,-0.000352,0.189295,-0.346752,-0.502147,-0.756765,-0.069547,-0.489929,-0.298696,0.005456,0.017623,0.068771,0.637652,-0.949455,0.356047,0.370741,0.174999,-0.240098,0.628187,-0.202100,0.144260,-0.180679,-0.097656,0.368014,-0.054421,0.064846,0.039818,0.375028,-0.301550,-0.293170,-0.408713,0.414202', '1308755', '1296332', '3139191', '2002744');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26035290', '悟空传', '剧情', '这不是西游记的任何章节，这是悟空的故事，彼时孙悟空（彭于晏 饰）还不是震撼天地的齐天大圣，他只是只桀傲不驯的猴子。天庭毁掉他的花果山以掌控众生命运，他便决心跟天庭对抗，毁掉一切戒律。在天庭，孙悟空遇到不能爱的阿紫（倪妮 饰），一生的宿敌杨戬（余文乐 饰），和思念昔日爱人 阿月的天蓬（欧豪 饰），他们的身份注定永生相杀，但其实不甘命运摆布的又何止孙悟空一人？却没想到反抗却带来更大的浩劫。他们所做的一切，究竟是不知天高地厚的热血轻狂，还是无奈宿命难改的压抑绝望？难道命运真的早已注定？悟空不服，他再次挥动金箍棒，要让这诸佛都烟消云散！', '彭于晏', '郭子健', 5.1, 223064, 'tt6513406', 'https://img1.doubanio.com/view/photo/s_ratio_poster/public/p2475060299.jpg', 16.2, 33.7, 35.2, 10.3, 4.5, '-0.034400,0.275510,-0.781080,0.569250,-0.212218,-0.459295,0.706138,0.107246,-0.342614,0.078935,0.248984,0.483102,0.114159,0.157066,-0.304317,0.126329,-0.119178,-0.632003,-0.175902,0.198293,0.231521,-0.188808,-0.326614,-0.063312,0.123105,-0.098412,0.881683,0.183252,-0.216471,-0.021031,0.561711,0.109437,-0.119472,0.613625,-0.421435,0.192665,-0.463541,0.363998,-0.248235,-0.406236,-0.095420,-0.222412,-0.226914,0.627509,-0.438161,0.192710,0.209000,-0.744730,-0.402685,-0.187665,0.444210,-0.471559,-0.239997,0.075657,-0.191247,-0.148001,-0.022102,0.173545,0.119319,0.066144,0.309296,0.251667,-0.841862,-0.060116,0.030004,0.121907,-0.225371,0.418547,-0.040581,0.080916,-0.102740,-0.171343,-0.007288,-0.002888,0.558188,0.293526,-0.423425,-0.302256,-0.568878,0.320166,0.895402,-0.151746,-0.087895,0.289329,-0.218962,-0.254948,-0.344477,-0.236366,-0.431502,0.112901,0.237218,0.057017,0.109397,0.683430,-0.155188,-0.234873,-0.187355,0.201992,-0.304294,-0.738191,0.136829,-0.030691,-0.221945,-0.334815,-0.490457,-0.095508,0.608313,-0.185351,0.723176,-0.597807,0.267758,0.582692,0.048034,-0.581462,0.631854,0.386204,-0.101437,-0.322536,0.038384,0.522061,-0.275171,0.183884,0.204433,0.126147,0.410701,0.331746,-0.150257,0.698662', '30163500', '6874741', '3318473', '4218768');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26050200', '擦枪走火', '喜剧', '蓝天（倪虹洁 饰）是一名网络主播，在一场相亲之中，她意外的被身为妇产科医生的相亲对象孙桡（邱泽 饰）诊断为已经怀孕。孩子的父亲，是龙套小演员黄斗（喻恩泰 饰），而此时两人已经分手，黄斗和名为菊子（赵文琪 饰）的女孩走到了一起。得知蓝天怀孕的消息，善良正直的黄斗决心负起责任，他离开了菊子，回到了蓝天的身边，暂时没有能力抚养这个孩子的两人决定将孩子打掉，可是事到临头，蓝天却犹豫了。当黄斗得知两人爱情的结晶还好端端的待在蓝天的肚子里时，他决定要和蓝天好好的走下去。可是，就在这个节骨眼上，意外和麻烦接踵而至，蓝天失踪，不知所措的黄斗不知该何去何从。©豆瓣', '喻恩泰', '周伟', 4.5, 6564, 'tt5460738', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2286232540.jpg', 24.2, 38.5, 27.6, 5.8, 4, '0.168595,0.099036,-0.786328,0.432745,-0.316371,-0.395081,0.508281,0.256002,-0.501476,-0.200559,0.126576,0.648124,-0.101460,0.546392,0.237653,0.233353,-0.319405,-0.782125,0.022132,-0.064048,-0.329446,-0.587810,-0.062911,-0.037771,-0.027693,-0.004142,0.755208,-0.032534,0.069006,0.489273,0.576213,-0.103670,-0.040770,0.641433,-0.326252,0.216316,0.010829,0.056235,-0.254888,0.415210,0.158147,-0.148252,-0.030600,0.287666,0.174225,0.145671,0.791326,-0.065619,-0.233373,0.035406,0.394939,-0.363523,0.167282,0.323355,0.399587,-0.147584,0.161962,0.195863,-0.282089,-0.115338,0.169995,-0.014021,-0.432532,0.114931,0.130722,0.226672,-0.918488,0.552926,-0.214589,-0.281718,0.011203,-0.387346,0.434852,0.417882,0.209173,0.732641,-0.426302,-0.090769,-0.219034,0.263198,0.492898,0.120363,-0.011313,0.536070,0.029596,-0.508144,-0.153913,0.163693,-0.442481,0.036869,0.306784,0.074822,-0.317068,0.070113,-0.167642,-0.118330,-0.273236,-0.081041,-0.222251,-0.414070,-0.193926,-0.017982,-0.079120,-0.198030,-0.498359,0.382419,-0.001576,-0.071034,0.619161,-0.877580,0.231890,0.288400,0.276732,-0.503311,0.592083,0.242522,0.163632,-0.347264,0.249896,-0.050974,-0.235105,0.164797,0.225233,0.309926,-0.096785,-0.103677,-0.418376,-0.044680', '1301022', '1299965', '35030151', '5446226');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26050295', '妻子小姐', '喜剧', '妍雨（严正花 饰）拥有天使的外表和魔鬼的身材，不仅如此，她还是一名毕业于著名大学法学系的女律师，事业上亦经营得风生水起。然而，正当她以为自己渐渐攀上了人生巅峰之时，一场突如其来的意外夺去了妍雨的生命。之后，妍雨遇见了一个神秘的男人，在男人的建议和帮助下，妍雨以一种全新的身份重生了，她有一个的时间来体味这种生活。妍雨附身在了一名家庭主妇的身上，有了一个名为成焕（宋承宪 饰）的丈夫。成焕虽然碌碌无为，却有着一颗深爱妻子和家庭的心，尽管妻子最近变得十分奇怪，但他依然宽容的接受了她。妍雨怎么也无法想象自己有朝一日会变身成为家庭主妇，异常的生活和成焕的存在令妍雨渐渐产生了变化。©豆瓣', '严正化', '姜孝镇', 7.4, 10865, 'tt5058114', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2253154595.jpg', 0.6, 3.5, 36.9, 43.5, 15.5, '0.006673,0.216474,-0.565682,0.872032,-0.081890,-0.296982,0.763198,0.337330,-0.121357,-0.372613,0.338700,0.704863,-0.283523,-0.009480,0.421212,-0.217405,-0.240729,-0.666839,-0.058954,-0.075378,-0.461905,-0.289206,-0.233236,0.256642,-0.244434,-0.274577,0.993636,0.145478,-0.097460,0.443696,0.153269,0.315548,0.222708,0.420921,-0.583108,-0.052138,0.030366,0.461821,0.055672,0.210514,0.264293,-0.195714,-0.293792,0.414750,-0.168031,0.315250,0.832619,-0.315006,-0.549238,-0.193989,0.626795,-0.131428,-0.024498,-0.073632,0.265085,-0.068269,0.120098,-0.119957,-0.153470,-0.096420,0.114095,-0.061033,-0.917471,0.045758,0.179807,0.019788,-0.345019,0.239382,0.025374,0.044575,-0.216396,-0.193974,0.202359,0.410866,-0.084710,0.723360,-0.520802,0.273545,-0.550710,0.112907,0.879463,0.373458,-0.689546,0.698641,-0.485568,-0.365931,-0.308322,-0.256757,-0.867245,-0.118869,0.293754,0.120654,-0.491881,0.093140,-0.556890,0.116823,-0.278162,0.008149,-0.036995,-0.298746,-0.068622,-0.116874,-0.262940,-0.584189,-0.488235,-0.045914,-0.058046,-0.505478,0.966470,-1.222834,0.244007,0.249157,0.351128,-0.635672,0.482160,0.062733,-0.055588,-0.094123,-0.128896,0.393199,-0.246701,-0.023207,0.020129,0.677998,-0.174633,0.058866,-0.370822,0.543262', '1395231', '24284209', '4817024', '35030151');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26051523', '尊严殖民地', '剧情', '1973年智利政变，德国夫妇丹尼尔被独裁者皮诺切特的秘密警察绑架，莉娜跟踪他们到一个封闭社区Colonia Dignidad，智利军政府将那里作为刑讯和秘密人体试验的基地，由前纳粹分子保罗·费舍尔统领，莉娜假意加入他们，以伺机救出丹尼尔。', '艾玛·沃森', '佛罗瑞·加仑伯格', 7.7, 20443, 'tt4005402', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2338992930.jpg', 0.5, 2.7, 27.9, 49.2, 19.6, '0.444402,-0.108390,-0.427383,0.470655,-0.136366,-0.210898,0.386048,-0.193464,-0.604561,-0.293091,0.268875,0.641087,0.110643,-0.369089,0.333563,0.363596,-0.741125,-0.675912,-0.234856,0.031339,-0.316638,-0.712555,-0.431264,-0.523764,-0.008462,-0.327939,0.739791,-0.320386,-0.191261,0.325114,0.114267,0.758730,-0.068833,0.186301,0.292802,0.080795,0.891263,-0.871923,-0.681802,0.426691,-0.255820,-0.373367,-0.064947,0.124354,0.143576,0.188680,0.392137,-0.229627,0.361386,-0.712311,-0.146433,-0.547344,-0.267690,0.099519,0.583429,0.100663,0.116548,0.645399,-0.250855,-0.143727,-0.054143,-0.085440,-0.155883,-0.054815,0.015292,-0.093259,-0.142251,-0.008875,-0.377018,0.350253,0.157144,-0.259039,0.124703,0.829265,-0.134646,-0.022468,-0.146189,0.022585,-0.731209,-0.167786,0.673270,-0.490799,-0.164148,-0.701347,0.050484,-0.241484,0.307582,-0.286470,0.158842,-0.087298,0.426126,-0.438697,-0.073918,0.186559,-0.752077,-0.311868,-0.668827,-0.231030,0.103147,-0.269811,0.170558,-1.070426,-0.296207,0.163866,-0.217987,-0.093561,-0.036566,0.078216,0.430634,-0.651005,0.217280,0.781552,0.559355,-0.459623,0.291686,-0.048352,0.272199,-0.542791,-0.087570,0.251509,0.365526,0.339785,0.018466,0.290649,0.054751,-0.121265,-0.128892,-0.145445', '1293572', '2973528', '2369549', '1293537');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26061679', '触不可及(美版)', '剧情', '菲利普（布莱恩·科兰斯顿 Bryan Cranston 饰）是一位腰缠万贯的富翁，在一场滑翔伞事故中，他伤及了颈椎，导致全身瘫痪。如今，他隐居在自己豪华的别墅中，凭借着雄厚的资金过着离群索居的日子。在好友的建议下，菲利普决定招聘一名贴身助理来照顾自己的生活起居，在招聘启事发出去不久之后，一位名叫戴尔（凯文·哈特 Kevin Hart 饰）的年轻人出现在了他的面前。戴尔并不算一个底细非常干净的人，他因为无法向前妻付清赡养费而即将面临失去孩子探视权的糟糕状况。大大咧咧口吐芬芳的戴尔很快就吸引了菲利普的注意，尽管所有人都觉得这个年轻人不靠谱，但菲利普还是决定就是他了。©豆瓣', '凯文·哈特', '尼尔·博格', 7.5, 94268, 'tt1987680', 'https://img2.doubanio.com/view/photo/s_ratio_poster/public/p2575135153.jpg', 0.5, 3.9, 31.4, 47.3, 17, '0.303370,0.104281,-0.727208,0.433047,-0.488702,-0.454300,0.919695,0.279520,-0.495596,-0.383681,0.467815,0.823377,-0.114449,0.182383,0.351947,0.021981,-0.084790,-0.538397,-0.058675,-0.257699,-0.326630,-0.476517,-0.194987,-0.210939,-0.210158,-0.424859,0.359874,-0.087853,-0.158552,0.243284,0.196872,0.304862,0.143937,0.629563,-0.159673,-0.041549,0.121778,-0.268977,-0.065851,0.233143,0.126717,-0.298283,-0.080483,0.290633,0.205585,0.391621,0.466856,-0.149983,-0.285982,0.036774,0.305259,0.003030,0.034852,0.149419,0.506974,0.008604,0.161265,0.153521,-0.472510,0.015656,0.005023,-0.080406,-0.752623,-0.176660,0.087449,0.330324,-0.882266,0.508632,-0.214527,-0.275317,-0.097294,-0.512231,0.142829,0.328308,0.057850,0.414493,-0.128686,0.066751,-0.521453,0.181283,0.643727,0.167583,-0.433404,0.353321,-0.235742,-0.377746,-0.255723,-0.112127,-0.608030,-0.123135,0.328878,0.018535,-0.187475,0.163687,-0.250627,0.047159,-0.300865,-0.527864,-0.187006,-0.243290,-0.164736,-0.501654,-0.080065,-0.356055,-0.332009,0.080274,-0.032217,-0.168500,0.670619,-0.897613,0.159708,0.598166,0.333581,-0.216590,0.524688,-0.020698,0.319273,-0.090643,-0.227112,0.208673,0.173569,0.254789,0.238030,0.384266,-0.067973,-0.308876,-0.272878,0.545782', '1299965', '1783461', '24698878', '1866424');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26061902', '东北偏北', '剧情', '在东北地带，性侵案件频发，却始终抓不到罪犯，甚至没人能看清罪犯真容。公安队长李占山（班赞 饰）对刑侦知识没有太多认识，徒有一腔破案热情，对恶行深恶痛疾。当他遇见劳改下放的中医老教授蔡滨（李滨 饰），并与她成为破案搭档，大老粗搭档知识分子，英雄遭遇书生，彼此就成为了对方最大的问题，新鲜组合妙趣横生。在土方法和科学推理不断碰撞不断磨合下，诸多证据逐一浮现，来无影去无踪的罪犯也渐渐清晰。灵感启发自真实事件，抓流氓抓出一段旧时代人情义理之故事。情节曲折丌过丐道颠沛，巧合中洞见丐事之必然不偶然。让人笑也让人叹。', '班赞', '张秉坚', 6.3, 7425, 'tt4131508', 'https://img3.doubanio.com/view/photo/s_ratio_poster/public/p2291164980.jpg', 2.9, 15, 51.4, 25.4, 5.3, '0.073493,-0.188314,-0.286633,0.219433,-0.091454,0.124483,0.656398,-0.250942,-0.554472,-0.201079,0.043370,0.326424,-0.162191,-0.152253,0.040115,-0.430548,-0.222878,-0.547129,0.355306,-0.315145,-0.146392,-0.525102,-0.332317,-0.198130,-0.173679,-0.091174,0.378492,0.035114,-0.522807,0.231007,0.077638,0.268197,-0.486818,0.447086,-0.142907,-0.069153,0.190271,0.216884,-0.223424,-0.279769,0.066341,-0.481296,-0.198284,-0.022573,-0.500890,0.141281,0.458998,-0.241366,-0.205480,-0.005036,0.135888,-0.290504,-0.108682,-0.048921,0.145522,0.063045,0.337041,0.401574,0.210151,-0.099798,-0.247360,0.057648,-0.562632,-0.005030,0.221579,0.234647,-0.132180,0.121141,-0.023960,-0.174326,-0.020848,-0.313155,-0.058567,-0.116612,0.491156,0.297148,0.014577,0.078022,-0.164448,0.274805,0.285284,0.025001,-0.367795,0.260508,-0.276645,-0.448894,0.039394,-0.209965,0.115073,0.179979,0.200542,-0.039180,-0.182587,0.381483,-0.438452,0.187488,-0.071397,0.185030,-0.036841,-0.207272,0.034128,-0.363629,-0.202879,-0.132149,-0.395955,0.044624,0.245294,-0.233723,0.525159,-0.507902,-0.013359,0.521635,-0.021500,-0.358206,0.394913,0.217602,-0.184172,-0.401738,-0.184456,0.010797,0.273119,0.531652,0.212073,0.292756,0.022419,-0.221184,-0.153197,0.205650', '3005387', '2988294', '26328483', '10581450');
INSERT INTO movie_web.movie (mid, mname, type, content, actors, director, rate, rate_num, imdb, pic, one_star, two_star, three_star, four_star, five_star, feature, s1_mid, s2_mid, s3_mid, s4_mid) VALUES ('26088403', '检察官外传', '喜剧', '《检察官外传》讲述了黄政民饰演的检察官被冤枉成杀人罪而判刑入狱，在监狱中他结识了姜东元饰演的诈骗犯，于是利用他偷抢拐骗的才能，向黑社会组织展开复仇的故事。', '黄政民', '李日炯', 7.5, 81647, 'tt5442308', 'https://img9.doubanio.com/view/photo/s_ratio_poster/public/p2298188494.jpg', 0.3, 2.4, 35, 46.9, 15.4, '0.477099,-0.303053,-0.206908,0.556051,-0.352052,-0.140828,0.673758,0.049861,-0.118667,0.205086,0.364836,0.554821,-0.041112,0.192823,0.626364,0.142865,-0.236196,-0.895715,-0.170534,-0.145964,-0.118928,-0.625374,-0.395006,-0.076474,0.241584,-0.261820,0.617188,-0.149880,-0.687410,0.204969,0.840096,0.505812,-0.295599,-0.099297,-0.123226,0.365625,0.337243,-0.067749,-0.270051,0.299428,-0.085022,-0.638824,0.100820,-0.110781,-0.206159,0.562363,0.506702,-0.176508,-0.035643,-0.375173,0.842252,-0.871592,-0.189047,-0.036729,0.275466,0.349344,0.114770,0.598206,-0.293882,-0.149307,0.173813,-0.251876,-0.906459,-0.222388,0.324874,0.030478,-0.453768,-0.145646,0.152636,0.307461,0.198958,0.174524,0.143093,0.129442,0.086940,0.547805,-0.077808,-0.048985,-0.632725,0.678607,0.358143,-0.430261,-0.042628,0.103037,0.228180,-0.147542,0.349683,-0.547274,-0.286372,-0.239290,0.565774,-0.509438,-0.426361,0.133940,-0.104842,-0.595222,-0.085846,0.139140,0.178361,-0.408793,-0.131000,-0.581847,-0.517435,-0.096440,-0.017332,-0.067586,-0.064067,-0.467237,0.261787,-0.422306,0.210219,0.860966,0.100263,-0.770285,0.497383,0.290164,-0.076477,-0.019430,0.120442,-0.026376,0.665312,0.472144,0.299031,0.096174,0.007144,-0.480792,-0.468854,0.094276', '25921830', '26331839', '1302110', '27073234');
